INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 1, 'Im Anfang schuf Gott den Himmel und die Erde;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 2, 'die Erde war aber eine Wüstenei und Öde, und Finsternis lag über der weiten Flut, und der Geist Gottes schwebte (brütend) über der Wasserfläche.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 3, 'Da sprach Gott: »Es werde Licht!«, und es ward Licht.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 4, 'Und Gott sah, daß das Licht gut war; da schied Gott das Licht von der Finsternis');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 5, 'und nannte das Licht »Tag«, der Finsternis aber gab er den Namen »Nacht«. Und es wurde Abend und wurde Morgen: erster Tag.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 6, 'Dann sprach Gott: »Es entstehe ein festes Gewölbe inmitten der Wasser und bilde eine Scheidewand zwischen den beiderseitigen Wassern!« Und es geschah so.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 7, 'So machte Gott das feste Gewölbe und schied dadurch die Wasser unterhalb des Gewölbes von den Wassern oberhalb des Gewölbes.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 8, 'Und Gott nannte das feste Gewölbe »Himmel«. Und es wurde Abend und wurde Morgen: zweiter Tag.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 9, 'Dann sprach Gott: »Es sammle sich das Wasser unterhalb des Himmels an einen besonderen Ort, damit das Trockene sichtbar wird!« Und es geschah so.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 10, 'Und Gott nannte das Trockene »Erde«, dem Wasser aber, das sich gesammelt hatte, gab er den Namen »Meer«. Und Gott sah, daß es gut war. –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 11, 'Dann sprach Gott: »Die Erde lasse junges Grün sprossen, samentragende Pflanzen und Bäume, die je nach ihrer Art Früchte mit Samen darin auf der Erde tragen!« Und es geschah so:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 12, 'die Erde ließ junges Grün hervorgehen, Kräuter, die je nach ihrer Art Samen trugen, und Bäume, die Früchte mit Samen darin je nach ihrer Art trugen. Und Gott sah, daß es gut war.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 13, 'Und es wurde Abend und wurde Morgen: dritter Tag.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 14, 'Dann sprach Gott: »Es sollen Lichter am Himmelsgewölbe entstehen, um Tag und Nacht voneinander zu scheiden; die sollen Merkzeichen sein und zur (Bestimmung von) Festzeiten sowie zur (Zählung von) Tagen und Jahren dienen;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 15, 'und sie sollen Lichter am Himmelsgewölbe sein, um Licht über die Erde zu verbreiten!« Und es geschah so.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 16, 'Da machte Gott die beiden großen Lichter: das größere Licht zur Herrschaft über den Tag und das kleinere Licht zur Herrschaft über die Nacht, dazu auch die Sterne.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 17, 'Gott setzte sie dann an das Himmelsgewölbe, damit sie Licht über die Erde verbreiteten');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 18, 'und am Tage und in der Nacht die Herrschaft führten und das Licht von der Finsternis schieden. Und Gott sah, daß es gut war.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 19, 'Und es wurde Abend und wurde Morgen: vierter Tag.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 20, 'Dann sprach Gott: »Es wimmle das Wasser von einem Gewimmel lebender Wesen, und Vögel sollen über der Erde am Himmelsgewölbe hin fliegen!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 21, 'Da schuf Gott die großen Seetiere und alle Arten der kleinen Lebewesen, die da sich regen, von denen die Gewässer wimmeln, dazu alle Arten der beschwingten Vögel. Und Gott sah, daß es gut war.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 22, 'Da segnete Gott sie mit den Worten: »Seid fruchtbar und mehret euch und erfüllet das Wasser in den Meeren, und auch die Vögel sollen sich auf der Erde mehren!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 23, 'Und es wurde Abend und wurde Morgen: fünfter Tag.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 24, 'Dann sprach Gott: »Die Erde bringe alle Arten lebender Wesen hervor, Vieh, Kriechgetier und wilde Landtiere, jedes nach seiner Art!« Und es geschah so.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 25, 'Da machte Gott alle Arten der wilden Landtiere und alle Arten des Viehs und alles Getier, das auf dem Erdboden kriecht, jedes nach seiner Art. Und Gott sah, daß es gut war. –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 26, 'Dann sprach Gott: »Laßt uns Menschen machen nach unserm Bilde, uns ähnlich, die da herrschen sollen über die Fische im Meer und über die Vögel des Himmels, über das (zahme) Vieh und über alle (wilden) Landtiere und über alles Gewürm, das auf dem Erdboden kriecht!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 27, 'Da schuf Gott den Menschen nach seinem Bilde: nach dem Bilde Gottes schuf er ihn; als Mann und Weib schuf er sie.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 28, 'Gott segnete sie dann mit den Worten: »Seid fruchtbar und mehrt euch, füllt die Erde an und macht sie euch untertan und herrscht über die Fische im Meer und über die Vögel des Himmels und über alle Lebewesen, die auf der Erde sich regen!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 29, 'Dann fuhr Gott fort: »Hiermit übergebe ich euch alle samentragenden Pflanzen auf der ganzen Erde und alle Bäume mit samentragenden Früchten: die sollen euch zur Nahrung dienen!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 30, 'Aber allen Tieren der Erde und allen Vögeln des Himmels und allem, was auf der Erde kriecht, was Lebensodem in sich hat, weise ich alles grüne Kraut der Pflanzen zur Nahrung an.« Und es geschah so.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 31, 'Und Gott sah alles an, was er geschaffen hatte, und siehe: es war sehr gut. Und es wurde Abend und wurde Morgen: der sechste Tag.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 2, 1, 'So waren der Himmel und die Erde mit ihrem ganzen Heer vollendet.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 2, 2, 'Da brachte Gott am siebten Tage sein Werk, das er geschaffen hatte, zur Vollendung und ruhte am siebten Tage von aller seiner Arbeit, die er vollbracht hatte.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 2, 3, 'Und Gott segnete den siebten Tag und heiligte ihn; denn an ihm hat Gott von seinem ganzen Schöpfungswerk und seiner Arbeit geruht.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 2, 4, 'a Dies ist die Entstehungsgeschichte des Himmels und der Erde, als sie geschaffen wurden. b Zur Zeit, als Gott der HERR Erde und Himmel schuf,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 2, 5, 'als es auf der Erde noch keine Sträucher auf dem Felde gab und noch keine Pflanzen auf den Fluren gewachsen waren, weil Gott der HERR noch keinen Regen auf die Erde hatte fallen lassen und auch noch keine Menschen da waren, um den Ackerboden zu bestellen –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 2, 6, 'es stieg aber ein Wasserdunst von der Erde auf und tränkte die ganze Oberfläche des Erdbodens –:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 2, 7, 'da bildete Gott der HERR den Menschen aus Erde vom Ackerboden und blies ihm den Lebensodem in die Nase; so wurde der Mensch zu einem lebenden Wesen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 2, 8, 'Hierauf pflanzte Gott der HERR einen Garten in Eden nach Osten hin und versetzte dorthin den Menschen, den er gebildet hatte.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 2, 9, 'Dann ließ Gott der HERR allerlei Bäume aus dem Erdboden hervorwachsen, die lieblich anzusehen waren und wohlschmeckende Früchte trugen, dazu auch den Baum des Lebens mitten im Garten und den Baum der Erkenntnis des Guten und des Bösen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 2, 10, 'Es entsprang aber ein Strom in Eden, um den Garten zu bewässern, und teilte sich von dort aus, und zwar in vier Arme.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 2, 11, 'Der erste heißt Pison: dieser ist es, der das ganze Land Hawila umfließt, woselbst sich das Gold findet,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 2, 12, 'und das Gold dieses Landes ist kostbar; dort kommt auch das Bedolachharz vor und der Edelstein Soham.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 2, 13, 'Der zweite Strom heißt Gihon: dieser ist es, der das ganze Land Kusch umfließt.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 2, 14, 'Der dritte Strom heißt Hiddekel: dieser ist es, der östlich von Assyrien fließt; und der vierte Strom ist der Euphrat.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 2, 15, 'Als nun Gott der HERR den Menschen genommen und ihn in den Garten Eden versetzt hatte, damit er ihn bestelle und behüte,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 2, 16, 'gab Gott der HERR dem Menschen die Weisung: »Von allen Bäumen des Gartens darfst du nach Belieben essen;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 2, 17, 'aber vom Baum der Erkenntnis des Guten und des Bösen – von dem darfst du nicht essen; denn sobald du von diesem ißt, mußt du des Todes sterben.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 2, 18, 'Hierauf sagte Gott der HERR: »Es ist nicht gut für den Menschen, daß er allein ist: ich will ihm eine Hilfe schaffen, die zu ihm paßt.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 2, 19, 'Da bildete Gott der HERR aus Erde alle Tiere des Feldes und alle Vögel des Himmels und brachte sie zu dem Menschen, um zu sehen, wie er sie benennen würde; und wie der Mensch sie alle benennen würde, so sollten sie heißen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 2, 20, 'So legte denn der Mensch allem Vieh und den Vögeln des Himmels und allen wilden Tieren Namen bei; aber für einen Menschen fand er keine Hilfe darunter, die zu ihm gepaßt hätte.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 2, 21, 'Da ließ Gott der HERR einen tiefen Schlaf auf den Menschen fallen, so daß er einschlief; dann nahm er eine von seinen Rippen heraus und verschloß deren Stelle wieder mit Fleisch;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 2, 22, 'die Rippe aber, die Gott aus dem Menschen genommen hatte, gestaltete er zu einem Weibe und führte dieses dem Menschen zu.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 2, 23, 'Da rief der Mensch aus: »Diese endlich ist es: Gebein von meinem Gebein und Fleisch von meinem Fleisch! Diese soll ›Männin‹ heißen; denn vom Manne ist diese genommen.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 2, 24, 'Darum verläßt ein Mann seinen Vater und seine Mutter und hängt seinem Weibe an, und sie werden ein Fleisch sein.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 2, 25, 'Und sie waren beide nackt, der Mensch und sein Weib, und doch schämten sie sich nicht (voreinander).');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 3, 1, 'Nun war die Schlange listiger als alle Tiere des Feldes, die Gott der HERR geschaffen hatte; die sagte zum Weibe: »Sollte Gott wirklich gesagt haben: ›Ihr dürft von allen Bäumen des Gartens nicht essen!‹«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 3, 2, 'Da antwortete das Weib der Schlange: »Von den Früchten der Bäume im Garten dürfen wir essen;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 3, 3, 'nur von den Früchten des Baumes, der mitten im Garten steht, hat Gott gesagt: ›Ihr dürft von ihnen nicht essen, ja sie nicht einmal anrühren, sonst müßt ihr sterben!‹«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 3, 4, 'Da erwiderte die Schlange dem Weibe: »Ihr werdet sicherlich nicht sterben;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 3, 5, 'sondern Gott weiß wohl, daß, sobald ihr davon eßt, euch die Augen aufgehen werden und ihr wie Gott selbst sein werdet, indem ihr erkennt, was gut und was böse ist.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 3, 6, 'Da nun das Weib sah, daß von dem Baume gut zu essen sei und daß er eine Lust für die Augen und ein begehrenswerter Baum sei, weil man durch ihn klug werden könne, so nahm sie eine von seinen Früchten und aß und gab auch ihrem Manne, der bei ihr war, und der aß auch.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 3, 7, 'Da gingen ihnen beiden die Augen auf, und sie nahmen wahr, daß sie nackt waren; darum hefteten sie Blätter vom Feigenbaum zusammen und machten sich Schürze daraus.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 3, 8, 'Als sie dann aber die Stimme Gottes des HERRN hörten, der in der Abendkühle im Garten sich erging, versteckten sie sich, der Mann (Adam) und sein Weib, vor Gott dem HERRN unter den Bäumen des Gartens.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 3, 9, 'Aber Gott der HERR rief nach dem Mann mit den Worten: »Wo bist du?«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 3, 10, 'Da antwortete er: »Als ich deine Stimme im Garten hörte, fürchtete ich mich, weil ich nackt bin; darum habe ich mich versteckt.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 3, 11, 'Da fragte Gott: »Wer hat dir gesagt, daß du nackt bist? Du hast doch nicht etwa von dem Baume gegessen, von dem zu essen ich dir verboten habe?«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 3, 12, 'Da antwortete Adam: »Das Weib, das du mir beigesellt hast, die hat mir von dem Baume gegeben, da habe ich gegessen.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 3, 13, 'Da sagte Gott der HERR zu dem Weibe: »Warum hast du das getan?« Das Weib antwortete: »Die Schlange hat mich verführt; da habe ich gegessen.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 3, 14, 'Da sagte Gott der HERR zu der Schlange: »Weil du das getan hast, sollst du verflucht sein vor allen Tieren, zahmen und wilden! Auf dem Bauche sollst du kriechen und Staub fressen dein Leben lang!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 3, 15, 'Und ich will Feindschaft setzen zwischen dir und dem Weibe und zwischen deinem Samen und ihrem Samen: er wird dir nach dem Kopfe treten, und du wirst ihm nach der Ferse schnappen.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 3, 16, 'Zum Weibe aber sagte er: »Viele Mühsal will ich dir bereiten, wenn du Mutter wirst: mit Schmerzen sollst du Kinder gebären und doch nach deinem Manne Verlangen tragen; er aber soll dein Herr sein!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 3, 17, 'Zu dem Manne aber sagte er: »Weil du der Aufforderung deines Weibes nachgekommen bist und von dem Baume gegessen hast, von dem zu essen ich dir ausdrücklich verboten hatte, so soll der Ackerboden verflucht sein um deinetwillen: mit Mühsal sollst du dich von ihm nähren dein Leben lang!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 3, 18, 'Dornen und Gestrüpp soll er dir wachsen lassen, und du sollst dich vom Gewächs des Feldes nähren!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 3, 19, 'Im Schweiße deines Angesichts sollst du dein Brot essen, bis du zum Erdboden zurückkehrst, von dem du genommen bist; denn Staub bist du, und zu Staub mußt du wieder werden!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 3, 20, 'Adam gab dann seinem Weibe den Namen Eva; denn sie ist die Stammutter aller Lebenden geworden.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 3, 21, 'Darauf machte Gott der HERR dem Manne und seinem Weibe Röcke von Fellen und bekleidete sie (damit).');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 3, 22, 'Und Gott der HERR sagte: »Der Mensch ist jetzt ja geworden wie unsereiner, insofern er gut und böse zu unterscheiden weiß. Nun aber – daß er nur nicht seine Hand ausstreckt und auch (Früchte) vom Baume des Lebens nimmt und (sie) ißt und unsterblich wird!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 3, 23, 'So stieß ihn denn Gott der HERR aus dem Garten Eden hinaus, damit er den Erdboden bestelle, von dem er genommen war;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 3, 24, 'und als er den Menschen hinausgetrieben hatte, ließ er östlich vom Garten Eden die Cherube sich lagern und die Flamme des kreisenden Schwertes, damit sie den Zugang zum Baume des Lebens bewachten.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 4, 1, 'Eva gebar dann dem Adam, ihrem Gatten, einen Sohn Kain. Da sagte sie: »Einen Mann habe ich ins Dasein gerufen mit Hilfe des HERRN!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 4, 2, 'Hierauf gebar sie nochmals, nämlich seinen Bruder Abel; und Abel wurde ein Hirt von Kleinvieh, Kain aber ein Ackerbauer.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 4, 3, 'Nun begab es sich nach Verlauf geraumer Zeit, daß Kain dem HERRN eine Opfergabe von den Früchten des Ackers darbrachte;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 4, 4, 'und auch Abel opferte von den Erstgeburten seiner Herde, und zwar von ihren Fettstücken. Da schaute der HERR (mit Wohlgefallen) auf Abel und seine Opfergabe;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 4, 5, 'aber Kain und seine Gabe sah er nicht an. Darüber geriet Kain in heftige Erregung, so daß sein Angesicht sich finster senkte.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 4, 6, 'Da sagte der HERR zu Kain: »Warum bist du erregt geworden, und warum hat dein Angesicht sich finster gesenkt?');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 4, 7, 'Wird nicht, wenn du recht handelst, dein Opfer angenommen? Lagert nicht, wenn du böse handelst, die Sünde vor der Tür (als ein Feind, dessen) Verlangen auf dich gerichtet ist, den du aber bezwingen sollst?«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 4, 8, 'Hierauf sagte Kain zu seinem Bruder Abel: (»Laß uns aufs Feld gehen!«) Und als sie auf dem Felde waren, fiel Kain über seinen Bruder Abel her und schlug ihn tot.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 4, 9, 'Da sagte der HERR zu Kain: »Wo ist dein Bruder Abel?« Er antwortete: »Ich weiß es nicht; bin ich etwa meines Bruders Hüter?«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 4, 10, 'Gott aber sagte: »Was hast du getan? Ich höre das Blut deines Bruders zu mir aus dem Erdboden schreien!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 4, 11, 'Und nun – verflucht sollst du sein, (hinweggetrieben) vom Ackerboden, der seinen Mund aufgetan hat, um das von deiner Hand vergossene Blut deines Bruders in sich aufzunehmen!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 4, 12, 'Wenn du den Acker bestellst, soll er dir hinfort keinen Ertrag mehr geben: unstet und flüchtig sollst du auf der Erde sein!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 4, 13, 'Da sagte Kain zum HERRN: »Meine Strafe ist zu groß, als daß ich sie tragen könnte!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 4, 14, 'Du treibst mich ja heute von dem Ackerland hinweg, und ich muß mich vor deinen Augen verbergen und werde unstet und flüchtig auf der Erde sein; so wird denn jeder, der mich antrifft, mich totschlagen!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 4, 15, 'Aber der HERR antwortete ihm: »Nicht also! Jeder, der Kain totschlägt, soll siebenfältiger Rache verfallen!« Hierauf brachte der HERR an Kain ein Wahrzeichen an, damit ihn niemand erschlüge, der mit ihm zusammenträfe.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 4, 16, 'So ging denn Kain vom Angesicht des HERRN hinweg und ließ sich im Lande Nod östlich von Eden nieder.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 4, 17, 'Dem Kain gebar hierauf sein Weib einen Sohn, Henoch; und als Kain dann eine Stadt erbaute, benannte er sie nach seines Sohnes Namen Henoch.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 4, 18, 'Dem Henoch wurde dann Irad geboren; dieser wurde der Vater Mehujaels, Mehujael wurde der Vater Methusaels und Methusael der Vater Lamechs.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 4, 19, 'Lamech aber nahm sich zwei Frauen, von denen die eine Ada, die andere Zilla hieß.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 4, 20, 'Ada gebar dann den Jabal; dieser wurde der Stammvater der Zeltbewohner und Herdenbesitzer.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 4, 21, 'Sein Bruder hieß Jubal; dieser wurde der Stammvater aller Zither- und Flötenspieler.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 4, 22, 'Auch Zilla gebar einen Sohn, nämlich Thubalkain, den Hämmerer von allen schneidenden Geräten aus Kupfer und Eisen. Die Schwester Thubalkains war Namma.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 4, 23, 'Lamech aber sagte (einst) zu seinen Frauen: »Ada und Zilla, höret meine Rede! Ihr Weiber Lamechs, vernehmet meinen Spruch! Einen Mann erschlage ich, wenn er mich verwundet, und einen Jüngling, wenn er mir eine Strieme beibringt!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 4, 24, 'Denn wenn Kain siebenfältig gerächt werden soll, so Lamech siebenundsiebzigfach!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 4, 25, 'Dem Adam aber gebar sein Weib (Eva) nochmals einen Sohn, dem sie den Namen Seth gab; »denn«, sagte sie, »Gott hat mir einen andern Sproß verliehen an Stelle Abels, weil Kain ihn erschlagen hat«.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 4, 26, 'Auch dem Seth wurde ein Sohn geboren, den er Enos nannte. Damals fing man an, den Namen des HERRN anzurufen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 1, 'Dies ist die Geschlechtstafel Adams: Am Tage, als Gott den Adam schuf, gestaltete er ihn nach Gottes Ebenbild;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 2, 'als Mann und Weib schuf er sie und segnete sie und gab ihnen den Namen »Mensch« damals, als sie geschaffen wurden.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 3, 'Adam aber war 130 Jahre alt, als ihm ein Sohn geboren wurde, der ihm als sein Abbild glich und den er Seth nannte.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 4, 'Nach der Geburt Seths lebte Adam noch 800 Jahre und hatte Söhne und Töchter.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 5, 'Demnach betrug die ganze Lebenszeit Adams 930 Jahre; dann starb er. –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 6, 'Als Seth 105 Jahre alt war, wurde ihm Enos geboren.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 7, 'Nach der Geburt des Enos lebte Seth noch 807 Jahre und hatte Söhne und Töchter.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 8, 'Demnach betrug die ganze Lebenszeit Seths 912 Jahre; dann starb er. –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 9, 'Als Enos 90 Jahre alt war, wurde ihm Kenan geboren.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 10, 'Nach der Geburt Kenans lebte Enos noch 815 Jahre und hatte Söhne und Töchter.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 11, 'Demnach betrug die ganze Lebenszeit des Enos 905 Jahre; dann starb er. –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 12, 'Als Kenan 70 Jahre alt war, wurde ihm Mahalalel geboren.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 13, 'Nach der Geburt Mahalalels lebte Kenan noch 840 Jahre und hatte Söhne und Töchter.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 14, 'Demnach betrug die ganze Lebenszeit Kenans 910 Jahre; dann starb er. –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 15, 'Als Mahalalel 65 Jahre alt war, wurde ihm Jered geboren.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 16, 'Nach der Geburt Jereds lebte Mahalalel noch 830 Jahre und hatte Söhne und Töchter.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 17, 'Demnach betrug die ganze Lebenszeit Mahalalels 895 Jahre; dann starb er. –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 18, 'Als Jered 162 Jahre alt war, wurde ihm Henoch geboren.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 19, 'Nach der Geburt Henochs lebte Jered noch 800 Jahre und hatte Söhne und Töchter.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 20, 'Demnach betrug die ganze Lebenszeit Jereds 962 Jahre; dann starb er. –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 21, 'Als Henoch 65 Jahre alt war, wurde ihm Methusalah geboren.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 22, 'Henoch wandelte mit Gott; er lebte nach der Geburt Methusalahs noch 300 Jahre und hatte Söhne und Töchter.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 23, 'Demnach betrug die ganze Lebenszeit Henochs 365 Jahre.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 24, 'Henoch wandelte mit Gott und war plötzlich nicht mehr da, denn Gott hatte ihn hinweggenommen. –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 25, 'Als Methusalah 187 Jahre alt war, wurde ihm Lamech geboren.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 26, 'Nach der Geburt Lamechs lebte Methusalah noch 782 Jahre und hatte Söhne und Töchter.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 27, 'Demnach betrug die ganze Lebenszeit Methusalahs 969 Jahre; dann starb er. –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 28, 'Als Lamech 182 Jahre alt war, wurde ihm ein Sohn geboren,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 29, 'den er Noah nannte; »denn«, sagte er, »dieser wird uns Trost verschaffen bei unserer Arbeit und bei der Mühsal, die unsere Hände durch den Acker haben, den der HERR verflucht hat«.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 30, 'Nach der Geburt Noahs lebte Lamech noch 595 Jahre und hatte Söhne und Töchter.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 31, 'Demnach betrug die ganze Lebenszeit Lamechs 777 Jahre; dann starb er. –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 32, 'Als Noah 500 Jahre alt war, wurden ihm seine Söhne Sem, Ham und Japheth geboren.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 6, 1, 'Als nun die Menschen sich auf der Oberfläche des Erdbodens zu vermehren begannen und ihnen auch Töchter geboren wurden');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 6, 2, 'und die Gottessöhne die Schönheit der Menschentöchter sahen, nahmen sie sich von ihnen diejenigen zu Frauen, die ihnen besonders gefielen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 6, 3, 'Da sagte der HERR: »Mein Geist soll nicht für immer im Menschen erniedrigt sein, weil er ja Fleisch ist; so sollen denn seine Tage (fortan) nur noch hundertundzwanzig Jahre betragen!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 6, 4, 'Zu jener Zeit waren die Riesen auf der Erde und auch später noch, solange die Gottessöhne mit den Menschentöchtern verkehrten und diese ihnen (Kinder) gebaren. Das sind die Helden, die in der Urzeit lebten, die hochberühmten Männer.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 6, 5, 'Als nun der HERR sah, daß die Bosheit der Menschen groß war auf der Erde und alles Sinnen und Trachten ihres Herzens immerfort nur böse war,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 6, 6, 'da gereute es ihn, die Menschen auf der Erde geschaffen zu haben, und er wurde in seinem Herzen tief betrübt.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 6, 7, 'Darum sagte der HERR: »Ich will die Menschen, die ich geschaffen habe, vom ganzen Erdboden weg vertilgen, die Menschen wie das Vieh, das Gewürm wie die Vögel des Himmels; denn ich bereue es, sie geschaffen zu haben.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 6, 8, 'Noah aber hatte Gnade beim HERRN gefunden.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 6, 9, 'Dies ist die Geschichte Noahs: Noah war ein frommer, unsträflicher Mann unter seinen Zeitgenossen: mit Gott wandelte Noah.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 6, 10, 'Er hatte drei Söhne: Sem, Ham und Japheth.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 6, 11, 'Die Erde wurde aber immer verderbter vor Gott und war voll von Gewalttaten.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 6, 12, 'Als nun Gott die Erde ansah und die völlige Verderbtheit wahrnahm – denn alles Fleisch hatte sich in ihrem ganzen Tun auf Erden zum Bösen gewandt –,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 6, 13, 'da sagte Gott zu Noah: »Das Ende aller lebenden Geschöpfe ist bei mir beschlossen; denn die Erde ist durch ihre Schuld voll von Gewalttaten; darum will ich sie mitsamt der Erde verderben.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 6, 14, 'Baue dir eine Arche aus Tannenholz; mit lauter Zellen sollst du die Arche versehen und sie von innen und von außen mit Erdharz verpichen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 6, 15, 'Und so sollst du sie bauen: dreihundert Ellen soll die Länge der Arche betragen, fünfzig Ellen ihre Breite und dreißig Ellen ihre Höhe.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 6, 16, 'Eine Lichtöffnung sollst du an der Arche anbringen, und zwar eine Elle hoch sollst du sie ganz herum hoch oben herstellen, und den Eingang zur Arche an ihrer Seite anbringen und ein unteres, ein mittleres und ein oberes Stockwerk in ihr anlegen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 6, 17, 'Denn wisse wohl: ich will die große Flut über die Erde kommen lassen, um alle Geschöpfe, die Lebensodem in sich haben, unter dem ganzen Himmel zu vertilgen: alles, was auf der Erde lebt, soll umkommen!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 6, 18, 'Mit dir aber will ich einen Bund schließen: du sollst in die Arche gehen, du und mit dir deine Söhne und dein Weib und die Weiber deiner Söhne.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 6, 19, 'Und von allen lebenden Wesen, von allen Tieren, sollst du je ein Paar in die Arche mit hineinnehmen, um sie mit dir am Leben zu erhalten: je ein Männliches und ein Weibliches sollen es sein.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 6, 20, 'Von jeder Art der Vögel und von jeder Art der Vierfüßler, von jeder Art der Kriechtiere des Erdbodens – von diesen allen soll immer ein Paar zu dir in die Arche hineinkommen, damit sie am Leben erhalten bleiben.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 6, 21, 'Du selbst aber nimm dir alle Arten von Nahrungsmitteln, die als Speise genossen werden, und sammle bei dir Vorräte davon, damit sie dir und ihnen zur Nahrung dienen.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 6, 22, 'Und Noah tat es; er machte alles genau so, wie Gott es ihm geboten hatte.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 7, 1, 'Dann sagte der HERR zu Noah: »Gehe du mit deiner ganzen Familie in die Arche, denn dich habe ich als gerecht vor mir erfunden unter diesem Geschlecht.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 7, 2, 'Von allen reinen Tieren nimm je sieben Paare zu dir, immer ein Männchen und sein Weibchen, aber von den unreinen Tieren nur je zwei Stück, ein Männchen und sein Weibchen;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 7, 3, 'auch von den Vögeln des Himmels je sieben Paare, Männchen und Weibchen, damit Nachkommenschaft auf der ganzen Erde am Leben erhalten bleibt;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 7, 4, 'denn es sind nur noch sieben Tage, dann will ich es vierzig Tage und vierzig Nächte hindurch auf die Erde regnen lassen und will den ganzen Bestand an Lebewesen, die ich geschaffen habe, vom ganzen Erdboden vertilgen.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 7, 5, 'Da tat Noah alles genau so, wie der HERR es ihm geboten hatte.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 7, 6, 'Noah war aber sechshundert Jahre alt, als die Sintflut über die Erde kam.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 7, 7, 'Da ging Noah und mit ihm seine Söhne, sein Weib und seine Schwiegertöchter in die Arche hinein vor den Gewässern der Sintflut.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 7, 8, 'Von den reinen und von den unreinen Vierfüßlern sowie von den Vögeln und von allem, was auf dem Erdboden kriecht,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 7, 9, 'kamen immer zwei, ein Männchen und ein Weibchen, zu Noah in die Arche hinein, wie Gott ihm geboten hatte.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 7, 10, 'Und nach Ablauf der sieben Tage, da kamen die Gewässer der Sintflut über die Erde.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 7, 11, 'Es war im sechshundertsten Lebensjahre Noahs, am siebzehnten Tage des zweiten Monats: an diesem Tage brachen alle Quellen der großen Tiefe auf, und die Fenster des Himmels öffneten sich,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 7, 12, 'und der Regen strömte vierzig Tage und vierzig Nächte hindurch auf die Erde.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 7, 13, 'An eben diesem Tage ging Noah mit seinen Söhnen Sem, Ham und Japheth und mit seinem Weibe und seinen drei Schwiegertöchtern in die Arche hinein,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 7, 14, 'sie und alle Arten der wilden Tiere und alle Arten des Viehs und alle Arten des Gewürms, das auf der Erde kriecht, auch alle Arten der Vögel, alles, was Flügel hatte und beschwingt war;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 7, 15, 'die kamen zu Noah in die Arche hinein, je ein Paar von allen Geschöpfen, die Lebensodem in sich hatten;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 7, 16, 'und die da hineinkamen, waren immer ein Männchen und ein Weibchen von allem Fleische, wie Gott ihm geboten hatte. Hierauf schloß der HERR hinter ihm zu.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 7, 17, 'Da kam die Sintflut vierzig Tage lang über die Erde, und das Wasser stieg und hob die Arche empor, so daß sie hoch über der Erde schwamm.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 7, 18, 'Und das Wasser nahm gewaltig zu und stieg hoch über der Erde, so daß die Arche auf der weiten Flut dahinfuhr.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 7, 19, 'Und das Wasser stieg immer noch höher über der Erde, so daß alle höchsten Berge, die unter dem ganzen Himmel sind, überflutet wurden.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 7, 20, 'Fünfzehn Ellen hoch ging das Wasser über sie hin, so daß die Berge überflutet wurden.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 7, 21, 'Damals kamen alle Geschöpfe um, die auf der Erde sich regten: was an Vögeln, an Vieh und an wilden Tieren da war, sowie alles Gewürm, von dem die Erde wimmelte, und auch alle Menschen:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 7, 22, 'alles, in dessen Nase ein Hauch von Lebensodem war, das starb, alles, soweit es auf dem Trockenen lebte.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 7, 23, 'So vertilgte Gott alle Geschöpfe, die auf dem ganzen Erdboden waren, vom Menschen bis zum Vieh, bis zum Gewürm und bis zu den Vögeln des Himmels: sie wurden alle von der Erde vertilgt; nur Noah blieb übrig und was sich bei ihm in der Arche befand.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 7, 24, 'Das Wasser aber stieg unaufhörlich über der Erde hundertundfünfzig Tage lang.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 8, 1, 'Da dachte Gott an Noah und an alle wilden Tiere und an all das Vieh, das bei ihm in der Arche war; und Gott ließ einen Wind über die Erde wehen, so daß die Wasser sanken;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 8, 2, 'die Quellen der Tiefe und die Fenster des Himmels schlossen sich, und dem Regen vom Himmel her wurde Einhalt getan.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 8, 3, 'Da verlief sich das Wasser allmählich von der Erde und begann nach Ablauf der hundertundfünfzig Tage zu fallen;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 8, 4, 'und am siebzehnten Tage des siebten Monats saß die Arche auf einem der Berge von Ararat fest.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 8, 5, 'Das Wasser nahm dann immerfort ab bis zum zehnten Monat: am ersten Tage des zehnten Monats kamen die Gipfel der Berge zum Vorschein.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 8, 6, 'Nach Verlauf von vierzig Tagen aber öffnete Noah das Fenster der Arche, das er angebracht hatte,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 8, 7, 'und ließ den Raben ausfliegen; der flog hin und her, bis das Wasser auf der Erde abgetrocknet war.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 8, 8, 'Hierauf ließ er die Taube ausfliegen, um zu erfahren, ob das Wasser sich auf der Erdoberfläche verlaufen habe.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 8, 9, 'Da die Taube aber keinen Ort fand, wo ihre Füße hätten ruhen können, kehrte sie zu ihm zu der Arche zurück; denn das Wasser bedeckte noch die Oberfläche der ganzen Erde. Da streckte er seine Hand hinaus, ergriff sie und nahm sie wieder zu sich in die Arche.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 8, 10, 'Hierauf wartete er noch weitere sieben Tage und ließ dann die Taube zum zweitenmal aus der Arche fliegen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 8, 11, 'Da kam die Taube um die Abendzeit zu ihm zurück, und siehe da: sie hatte ein frisches Ölbaumblatt im Schnabel! Daran erkannte Noah, daß das Wasser auf der Erde sich verlaufen hatte.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 8, 12, 'Nun wartete er nochmals weitere sieben Tage und ließ die Taube wieder ausfliegen; doch diesmal kehrte sie nicht wieder zu ihm zurück.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 8, 13, 'Und im sechshundertundersten Lebensjahre Noahs, am ersten Tage des ersten Monats, da war das Wasser von der Erde weggetrocknet. Als jetzt Noah das Dach von der Arche abnahm und Ausschau hielt, da war der Erdboden abgetrocknet;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 8, 14, 'und am siebenundzwanzigsten Tage des zweiten Monats war die Erde ganz trocken geworden.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 8, 15, 'Da gebot Gott dem Noah:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 8, 16, '»Verlaß (jetzt) die Arche, du und mit dir dein Weib und deine Söhne und deine Schwiegertöchter!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 8, 17, 'Sämtliche Tiere von allen Arten, die bei dir sind, Vögel, Vieh und alles Gewürm, das auf der Erde kriecht, laß mit dir hinausgehen, damit sie sich auf der Erde frei bewegen und fruchtbar seien und sich mehren auf der Erde.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 8, 18, 'Da ging Noah mit seinen Söhnen, seinem Weibe und seinen Schwiegertöchtern hinaus;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 8, 19, 'auch alle vierfüßigen Tiere, alles Gewürm, alle Vögel, alles, was sich auf der Erde regt, gingen nach ihren Arten aus der Arche hinaus.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 8, 20, 'Noah baute dann dem HERRN einen Altar, nahm von allen reinen Tieren und von allen reinen Vögeln (je ein Stück) und brachte Brandopfer auf dem Altar dar.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 8, 21, 'Als nun der HERR den lieblichen Duft roch, sagte er bei sich selbst: »Ich will hinfort den Erdboden nicht noch einmal um der Menschen willen verfluchen; denn das Sinnen und Trachten des Menschenherzens ist böse von Jugend auf; auch will ich hinfort nicht noch einmal alles Lebende sterben lassen, wie ich es getan habe.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 8, 22, 'Hinfort, solange die Erde steht, sollen Säen und Ernten, Frost und Hitze, Sommer und Winter, Tag und Nacht nicht mehr aufhören!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 1, 'Dann segnete Gott Noah und seine Söhne mit folgenden Worten: »Seid fruchtbar und mehret euch und füllet die Erde.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 2, 'Die Furcht und der Schrecken vor euch soll auf allem Getier der Erde liegen und auf allen Vögeln des Himmels! Alles, was sich auf dem Erdboden regt, auch alle Fische des Meeres: in eure Gewalt sind sie gegeben.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 3, 'Alles, was sich regt und was da lebt, soll euch zur Nahrung dienen: wie (einstmals) die grünenden Pflanzen, so weise ich euch (jetzt) alles zu.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 4, 'Nur Fleisch, das noch seine Seele, nämlich sein Blut, in sich hat, dürft ihr nicht essen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 5, 'Jedoch euer eigenes Blut, um wessen Leben es sich auch bei euch handle, will ich rächen; an jedem Tiere will ich es rächen; und auch an jedem Menschen, an euch untereinander, will ich das Leben jedes Menschen rächen:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 6, 'Wer Menschenblut vergießt, dessen Blut soll wieder durch Menschen vergossen werden; denn nach seinem Bilde hat Gott den Menschen geschaffen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 7, 'Ihr aber – seid fruchtbar und mehret euch, wimmelt auf der Erde und werdet zahlreich auf ihr!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 8, 'Weiter sagte Gott zu Noah und seinen Söhnen, die bei ihm waren, folgendes:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 9, '»Ich will (jetzt) einen Bund mit euch aufrichten und mit eurer Nachkommenschaft, die nach euch sein wird,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 10, 'auch mit allen lebenden Wesen, die bei euch sind, mit den Vögeln, den zahmen und allen wilden Tieren, die bei euch sind, nämlich mit allen denen, die aus der Arche herausgegangen sind, mit allem Getier der Erde.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 11, 'Ich schließe also meinen Bund mit euch dahin, daß hinfort niemals wieder alle lebenden Geschöpfe durch das Wasser einer Sintflut vertilgt werden sollen und daß niemals wieder eine Sintflut eintreten soll, um die Erde zu verheeren!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 12, 'Dann fuhr Gott fort: »Dies soll das Zeichen des Bundes sein, den ich zwischen mir und euch und allen lebenden Wesen, die bei euch sind, auf ewige Zeiten festsetze:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 13, 'meinen Bogen stelle ich in die Wolken; der soll das Zeichen des Bundes zwischen mir und der Erde sein!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 14, 'Wenn ich hinfort Gewölk über der Erde sammle und der Bogen in den Wolken sichtbar wird,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 15, 'dann will ich meines Bundes gedenken, der zwischen mir und euch und allen lebenden Wesen jeglicher Fleischesart besteht; und das Wasser soll niemals wieder zu einer Sintflut werden, um alle lebenden Geschöpfe zu vertilgen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 16, 'Nein, wenn der Bogen in den Wolken steht, so will ich ihn anschauen, um des ewigen Bundes zwischen Gott und allen lebenden Wesen von jeglicher Fleischesart, die auf der Erde ist, zu gedenken.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 17, 'Und Gott schloß mit den Worten an Noah: »Dies ist das Zeichen des Bundes, den ich zwischen mir und allen lebenden Wesen auf der Erde aufgerichtet habe.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 18, 'Die Söhne Noahs, die aus der Arche gingen, waren Sem, Ham und Japheth; Ham aber ist der Vater Kanaans.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 19, 'Diese drei waren die Söhne Noahs, und von diesen aus ist die ganze Erde bevölkert worden.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 20, 'Noah aber wurde nun ein Landmann und legte auch einen Weinberg an.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 21, 'Als er dann aber von dem Weine trank, wurde er trunken und lag entblößt in seinem Zelt.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 22, 'Als nun Ham, der Vater Kanaans, seinen Vater entblößt hatte daliegen sehen, erzählte er es seinen beiden Brüdern draußen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 23, 'Da nahmen Sem und Japheth das Obergewand (ihres Vaters), legten es beide gemeinsam auf ihre Schultern, traten rückwärts hinzu und bedeckten ihren entblößten Vater damit; ihr Gesicht aber war dabei abgewandt, so daß sie die Blöße ihres Vaters nicht sahen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 24, 'Als nun Noah von seinem Rausch erwachte und erfuhr, wie sein jüngster Sohn sich gegen ihn benommen hatte,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 25, 'rief er aus: »Verflucht sei Kanaan! Der niedrigste Knecht soll er seinen Brüdern sein!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 26, 'Dann fuhr er fort: »Gepriesen sei der HERR, der Gott Sems! Kanaan aber soll sein Knecht sein!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 27, 'Weiten Raum schaffe Gott dem Japheth, und er wohne in den Zelten Sems! Kanaan aber soll sein Knecht sein!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 28, 'Nach der Sintflut lebte Noah noch dreihundertfünfzig Jahre;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 29, 'demnach betrug die ganze Lebenszeit Noahs neunhundertundfünfzig Jahre; dann starb er.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 1, 'Dies ist der Stammbaum der Noahsöhne, Sem, Ham und Japheth; Söhne wurden ihnen erst nach der Sintflut geboren.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 2, 'Die Söhne Japheths waren: Gomer, Magog, Madai, Jawan, Thubal, Mesech und Thiras.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 3, 'Die Söhne Gomers waren: Askenas, Riphath und Thogarma.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 4, 'Und die Söhne Jawans: Elisa und Tharsis, die Kitthiter und die Dodaniter.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 5, 'Von diesen aus haben sich die Bewohner der Meeresländer der (heidnischen) Völker abgezweigt. Dies sind die Söhne Japheths nach ihren Ländern, jeder nach seiner Sprache, nach ihren Geschlechtern, nach ihren Völkerschaften.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 6, 'Die Söhne Hams waren: Kusch, Mizraim, Put und Kanaan.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 7, 'Und die Söhne Kuschs: Seba, Hawila, Sabtha, Ragma und Sabthecha; und die Söhne Ragmas: Seban und Dedan. –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 8, 'Kusch war der Vater Nimrods; dieser wurde der erste Gewalthaber auf der Erde.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 9, 'Er war ein gewaltiger Jäger vor dem HERRN; darum pflegt man zu sagen: »Ein gewaltiger Jäger vor dem HERRN wie Nimrod.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 10, 'Den Anfang seines Königtums bildeten Babel, Erech, Akkad und Kalne im Lande Sinear.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 11, 'Von diesem Lande zog er nach Assur und erbaute Ninive, Rehoboth-Ir und Kalah,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 12, 'dazu Resen zwischen Ninive und Kalah, das ist die große Stadt. –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 13, 'Von Mizraim sodann stammen die Luditer, Anamiter, Lehabiter, Naphthuchiter,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 14, 'Pathrusiter, Kasluchiter und Kaphthoriter, von denen die Philister ausgegangen sind. –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 15, 'Kanaan aber hatte zu Söhnen Sidon, seinen Erstgeborenen, und Heth,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 16, 'ferner die Jebusiter, Amoriter, Girgasiter,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 17, 'Hewiter, Arkiter, Siniter,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 18, 'Arwaditer, Zemariter und Hamathiter. Später haben sich dann die Geschlechter der Kanaaniter zerstreut,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 19, 'so daß das Gebiet der Kanaaniter von Sidon in der Richtung auf Gerar bis Gaza, dann in der Richtung auf Sodom und Gomorrha, Adma und Zeboim bis Lesa reichte.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 20, 'Dies sind die Söhne Hams nach ihren Stämmen, ihren Sprachen, ihren Ländern, ihren Völkerschaften.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 21, 'Aber auch dem Sem, dem Stammvater aller Söhne Ebers, dem älteren Bruder Japheths, wurden Söhne geboren.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 22, 'Die Söhne Sems waren: Elam, Assur, Arpachsad, Lud und Aram.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 23, 'Und die Söhne Arams waren: Uz, Hul, Gether und Mas.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 24, 'Arpachsad aber war der Vater Selahs und Selah der Vater Ebers.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 25, 'Dem Eber aber wurden zwei Söhne geboren; der eine hieß Peleg, weil sich die Erde zu seiner Zeit teilte; und sein Bruder hieß Joktan.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 26, 'Joktan hatte zu Söhnen Almodad, Seleph, Hazarmaweth, Jerah,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 27, 'Hadoram, Usal, Dikla,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 28, 'Obal, Abimael, Seba,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 29, 'Ophir, Hawila und Jobab; diese alle waren Söhne Joktans,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 30, 'und ihre Wohnsitze erstreckten sich von Mesa in der Richtung auf Sephar bis zum Ostgebirge.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 31, 'Dies sind die Söhne Sems nach ihren Geschlechtern, nach ihren Sprachen, ihren Ländern, ihren Völkerschaften.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 32, 'Dies sind die Geschlechter der Söhne Noahs nach ihrer Abstammung, nach ihren Völkerschaften; und von ihnen aus haben sich die Völker auf der Erde nach der Sintflut abgezweigt.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 1, 'Es hatte aber die ganze Erdbevölkerung eine einzige Sprache und einerlei Worte.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 2, 'Als sie nun nach Osten hin zogen, fanden sie eine Tiefebene im Lande Sinear und blieben dort wohnen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 3, 'Da sagten sie zueinander: »Auf! Wir wollen Ziegel streichen und sie im Feuer hart brennen!« So dienten ihnen denn die Ziegel als Bausteine, und das Erdharz diente ihnen als Mörtel.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 4, 'Dann sagten sie: »Auf! Wir wollen uns eine Stadt und einen Turm bauen, dessen Spitze bis in den Himmel reichen soll, und wollen uns einen Namen schaffen, damit wir uns nicht über die ganze Erde hin zerstreuen!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 5, 'Da fuhr der HERR herab, um sich die Stadt und den Turm anzusehen, welche die Menschen erbauten.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 6, 'Da sagte der HERR: »Fürwahr, sie sind ein einziges Volk und haben alle dieselbe Sprache, und dies ist erst der Anfang ihres Unternehmens: hinfort wird ihnen nichts mehr unausführbar sein, was sie sich vornehmen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 7, 'Auf! wir wollen hinabfahren und ihre Sprache dort verwirren, so daß keiner mehr die Sprache des andern versteht!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 8, 'So zerstreute sie denn der HERR von dort über die ganze Erde, so daß sie den Bau der Stadt aufgeben mußten.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 9, 'Daher gab man der Stadt den Namen Babel; denn dort hat der HERR die Sprache der ganzen Erdbevölkerung verwirrt und sie von dort über die ganze Erde zerstreut.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 10, 'Dies ist der Stammbaum Sems: Als Sem 100 Jahre alt war, wurde ihm Arpachsad geboren, zwei Jahre nach der Sintflut.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 11, 'Nach der Geburt Arpachsads aber lebte Sem noch 500 Jahre und hatte Söhne und Töchter. –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 12, 'Als Arpachsad 35 Jahre alt war, wurde er der Vater Selahs.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 13, 'Nach der Geburt Selahs lebte Arpachsad noch 403 Jahre und hatte Söhne und Töchter. –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 14, 'Als Selah 30 Jahre alt war, wurde ihm sein Sohn Eber geboren.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 15, 'Nach der Geburt Ebers lebte Selah noch 403 Jahre und hatte Söhne und Töchter. –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 16, 'Als Eber 34 Jahre alt war, wurde ihm sein Sohn Peleg geboren.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 17, 'Nach der Geburt Pelegs lebte Eber noch 430 Jahre und hatte Söhne und Töchter. –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 18, 'Als Peleg 30 Jahre alt war, wurde ihm sein Sohn Rehu geboren.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 19, 'Nach der Geburt Rehus lebte Peleg noch 209 Jahre und hatte Söhne und Töchter. –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 20, 'Als Rehu 32 Jahre alt war, wurde ihm sein Sohn Serug geboren.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 21, 'Nach der Geburt Serugs lebte Rehu noch 207 Jahre und hatte Söhne und Töchter. –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 22, 'Als Serug 30 Jahre alt war, wurde er der Vater Nahors.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 23, 'Nach der Geburt Nahors lebte Serug noch 200 Jahre und hatte Söhne und Töchter. –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 24, 'Als Nahor 29 Jahre alt war, wurde er der Vater Tharahs.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 25, 'Nach der Geburt Tharahs lebte Nahor noch 119 Jahre und hatte Söhne und Töchter. –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 26, 'Als Tharah 70 Jahre alt war, wurden ihm seine Söhne Abram, Nahor und Haran geboren.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 27, 'Und dies ist der Stammbaum Tharahs: Tharah hatte drei Söhne: Abram, Nahor und Haran; Haran aber war der Vater Lots.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 28, 'Haran starb dann noch bei Lebzeiten seines Vaters Tharah in seinem Geburtslande, zu Ur in Chaldäa.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 29, 'Abram und Nahor aber nahmen sich ebenfalls Frauen: Abrams Frau hieß Sarai, und Nahors Frau hieß Milka; diese war eine Tochter Harans, des Vaters der Milka und der Jiska.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 30, 'Sarai aber war unfruchtbar: sie hatte keine Kinder.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 31, 'Da nahm Tharah seinen Sohn Abram und seinen Enkel Lot, den Sohn Harans, und seine Schwiegertochter Sarai, die Frau seines Sohnes Abram, und zog mit ihnen aus Ur in Chaldäa weg, um sich ins Land Kanaan zu begeben; als sie aber bis Haran gekommen waren, blieben sie daselbst wohnen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 32, 'Tharah brachte hierauf sein Leben auf zweihundertfünf Jahre; dann starb er in Haran.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 12, 1, 'Der HERR sprach zu Abram: »Verlaß dein Land und deine Verwandtschaft und deines Vaters Haus (und ziehe) in das Land, das ich dir zeigen werde;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 12, 2, 'denn ich will ich zu einem großen Volke machen und will dich segnen und deinen Namen groß machen, und du sollst ein Segen werden.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 12, 3, 'Ich will die segnen, die dich segnen, und wer dich verflucht, den will ich verfluchen; und in dir sollen alle Geschlechter der Erde gesegnet werden.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 12, 4, 'Da machte sich Abram auf den Weg, wie der HERR ihm geboten hatte, auch Lot zog mit ihm; Abram aber war fünfundsiebzig Jahre alt, als er aus Haran aufbrach.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 12, 5, 'Abram nahm also seine Frau Sarai und Lot, den Sohn seines Bruders (Haran), und alle Habe, die sie besaßen, und alles Gesinde, das sie in Haran erworben hatten, und so zogen sie aus, um nach dem Lande Kanaan zu wandern. Als sie nun in diesem Lande angekommen waren,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 12, 6, 'zog Abram im Lande umher bis zu der heiligen Stätte von Sichem, bis zur Orakel-Terebinthe; die Kanaanäer wohnten damals im Lande.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 12, 7, 'Da erschien der HERR dem Abram und sagte zu ihm: »Deinen Nachkommen will ich dieses Land geben!« Da baute er dort dem HERRN, der ihm erschienen war, einen Altar.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 12, 8, 'Hierauf zog er von dort weiter nach dem Berglande östlich von Bethel und schlug sein Zelt zwischen Bethel im Westen und Ai im Osten auf; dort baute er dem HERRN einen Altar und rief den Namen des HERRN an.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 12, 9, 'Dann brach er wieder auf und zog immer weiter nach dem Südgau zu.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 12, 10, 'Als dann eine Hungersnot im Lande ausbrach, zog Abram nach Ägypten hinab, um dort als Fremdling eine Zeitlang zu verbleiben; denn die Hungersnot lag schwer auf dem Lande.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 12, 11, 'Als er nun auf seinem Zuge von Ägypten nicht mehr weit entfernt war, sagte er zu seiner Frau Sarai: »Ich weiß sehr wohl, daß du eine Frau von großer Schönheit bist.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 12, 12, 'Wenn dich nun die Ägypter sehen und denken: ›Das ist seine Frau‹, dann werden sie mich erschlagen, während sie dich am Leben lassen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 12, 13, 'Sage doch, du seiest meine Schwester, damit es mir um deinetwillen gut ergehe und ich, soweit es sich um dich handelt, am Leben bleibe.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 12, 14, 'Als nun Abram in Ägypten ankam, sahen die Ägypter, daß die Frau überaus schön war;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 12, 15, 'und als die Hofleute des Pharaos sie zu Gesicht bekommen hatten, rühmten sie die Frau dem Pharao gegenüber; da wurde sie in dessen Palast geholt.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 12, 16, 'Dem Abram aber bewies sich der Pharao um ihretwillen wohlwollend, so daß er Kleinvieh und Rinder, Esel, Knechte und Mägde, Eselinnen und Kamele geschenkt erhielt.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 12, 17, 'Aber der HERR suchte den Pharao und sein Haus mit schweren Plagen heim wegen Sarais, der Frau Abrams.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 12, 18, 'Da ließ der Pharao Abram rufen und sagte zu ihm: »Was hast du mir da angetan! Warum hast du mir nicht mitgeteilt, daß sie deine Frau ist?');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 12, 19, 'Warum hast du sie für deine Schwester ausgegeben, so daß ich sie mir zur Frau genommen habe? Doch nun – hier hast du deine Frau: nimm sie und gehe!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 12, 20, 'Hierauf entbot der Pharao seinethalben Leute, die ihn samt seiner Frau und seiner ganzen Habe (aus dem Lande) geleiten mußten.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 13, 1, 'So zog denn Abram mit seiner Frau und mit all seinem Hab und Gut aus Ägypten wieder hinauf nach dem Südgau; auch Lot war bei ihm.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 13, 2, 'Abram war aber sehr reich an Herden, an Silber und Gold;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 13, 3, 'und er zog weiter von einem Lagerplatz zum andern aus dem Südgau bis nach Bethel, bis an die Stätte, wo sein Zelt anfangs gestanden hatte, zwischen Bethel und Ai,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 13, 4, 'zu der Stätte, wo der Altar stand, den er dort zuvor gebaut hatte; und Abram rief dort den Namen des HERRN an.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 13, 5, 'Aber auch Lot, der mit Abram zog, besaß Kleinvieh, Rinder und Zelte.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 13, 6, 'So reichte denn das Land nicht aus, daß beide hätten beisammen bleiben können; denn ihr Hab und Gut war groß geworden; daher konnten sie nicht beieinander bleiben.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 13, 7, 'So entstand denn Streit zwischen den Hirten von Abrams Herden und den Hirten von Lots Vieh; es waren nämlich die Kanaanäer und Pherissiter damals im Lande ansässig.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 13, 8, 'Da sagte Abram zu Lot: »Laß doch keine Streitigkeiten zwischen mir und dir und zwischen meinen und deinen Hirten herrschen: wir sind ja Brüder.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 13, 9, 'Steht dir nicht das ganze Land zur freien Verfügung? Trenne dich lieber von mir! Willst du nach der linken Seite, so gehe ich nach rechts, und willst du nach der rechten Seite, so gehe ich nach links.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 13, 10, 'Da hob Lot seine Augen auf und sah, daß die ganze Gegend am Jordan überall wohlbewässertes Land war – bevor nämlich der HERR Sodom und Gomorrha zerstört hatte –, wie der Garten Gottes, wie das Land Ägypten, bis nach Zoar hin.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 13, 11, 'Da wählte Lot für sich die ganze Gegend am Jordan und zog ostwärts. So trennten sich beide voneinander:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 13, 12, 'Abram blieb im Lande Kanaan wohnen, während Lot sich in den Ortschaften der Jordanaue niederließ und mit seinen Zelten bis nach Sodom zog.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 13, 13, 'Die Einwohner von Sodom aber waren böse Leute und arge Sünder vor dem HERRN.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 13, 14, 'Der HERR aber sagte zu Abram, nachdem Lot sich von ihm getrennt hatte: »Hebe deine Augen auf und schaue von der Stelle, auf der du stehst, nach Norden und Süden, nach Osten und Westen:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 13, 15, 'denn das ganze Land, das du siehst, will ich dir und deinen Nachkommen auf ewige Zeiten geben');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 13, 16, 'und will deine Nachkommenschaft so zahlreich werden lassen wie den Staub der Erde, so daß, wenn jemand den Staub der Erde zu zählen vermöchte, auch deine Nachkommenschaft zählbar sein sollte.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 13, 17, 'Wohlan, durchziehe das Land nach seiner Länge und Breite, denn dir will ich es geben!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 13, 18, 'Da zog Abram mit seinen Zelten weiter und nahm (endlich) seinen Wohnsitz unter den Terebinthen Mamres, die bei Hebron stehen; dort baute er dem HERRN einen Altar.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 14, 1, 'Es begab sich dann zur Zeit Amraphels, des Königs von Sinear, Ariochs, des Königs von Ellasar, Kedorlaomers, des Königs von Elam, und Thideals, des Königs von Gojim:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 14, 2, 'die fingen Krieg an mit Bera, dem König von Sodom, und mit Birsa, dem König von Gomorrha, mit Sineab, dem König von Adma, mit Semheber, dem König von Zebojim, und mit dem König von Bela, das ist Zoar.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 14, 3, 'Alle diese kamen als Verbündete im Tale von Siddim zusammen, wo jetzt das Salzmeer liegt.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 14, 4, 'Zwölf Jahre lang waren sie dem Kedorlaomer untertan gewesen, aber im dreizehnten Jahre waren sie von ihm abgefallen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 14, 5, 'Im vierzehnten Jahre kamen dann Kedorlaomer und die mit ihm verbündeten Könige und schlugen die Rephaiter bei Astheroth-Karnajim und die Susiter bei Ham und die Emiter in der Ebene von Kirjathajim');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 14, 6, 'und die Horiter auf ihrem Gebirge Seir bis nach El-Paran, das am Rand der Wüste liegt.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 14, 7, 'Darauf kehrten sie um und kamen nach En-Mispat, das ist Kades, und verwüsteten das ganze Gefilde der Amalekiter sowie auch das Gebiet der Amoriter, die in Hazazon-Thamar wohnten.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 14, 8, 'Da zogen der König von Sodom und die Könige von Gomorrha, von Adma, von Zebojim und von Bela – das ist Zoar – aus und stellten sich gegen sie zur Schlacht auf im Siddimtal,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 14, 9, 'nämlich gegen Kedorlaomer, den König von Elam, und Thideal, den König von Gojim, und Amraphel, den König von Sinear, und Arioch, den König von Ellasar: vier Könige gegen die fünf.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 14, 10, 'Das Siddimtal war aber voll von Gruben mit Erdharz. Als nun der König von Sodom und der von Gomorrha in die Flucht geschlagen waren, gerieten sie da hinein, die Überlebenden aber flohen ins Gebirge (Juda).');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 14, 11, 'Da plünderten jene Sodom und Gomorrha ganz aus, raubten alle ihre Lebensmittel und zogen damit ab;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 14, 12, 'sie nahmen auch Lot, Abrams Brudersohn, der damals in Sodom wohnte, samt seinem Hab und Gut mit sich und zogen ab.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 14, 13, 'Da kam ein Flüchtling und meldete es Abram, dem Hebräer; dieser wohnte damals unter den Terebinthen des Amoriters Mamre, der ein Bruder Eskols und Aners, der Bundesgenossen Abrams, war.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 14, 14, 'Als nun Abram die Kunde erhielt, daß sein Brudersohn (Lot) gefangen weggeführt worden war, da bot er seine waffengeübten Leute, dreihundertundachtzehn Mann, die in seinem Hause geboren waren, zum Kampfe auf und eilte jenen nach bis Dan.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 14, 15, 'Hier teilte er seine Leute in mehrere Haufen, überfiel die Feinde zur Nachtzeit mit seinen Knechten, schlug sie und verfolgte sie bis Hoba, das nördlich von Damaskus liegt.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 14, 16, 'So brachte er die gesamte Habe zurück; auch seinen Brudersohn Lot und dessen Hab und Gut brachte er zurück, ebenso die Frauen und das Volk.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 14, 17, 'Als Abram nun von seinem Siege über Kedorlaomer und die mit ihm verbündeten Könige zurückkehrte, ging ihm der König von Sodom entgegen in das Tal Sawe, das ist das Königstal.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 14, 18, 'Melchisedek aber, der König von Salem, brachte Brot und Wein aus der Stadt heraus; er war aber ein Priester des höchsten Gottes.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 14, 19, 'Er segnete ihn dann mit den Worten: »Gesegnet seist du, Abram, vom höchsten Gott, dem Schöpfer des Himmels und der Erde,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 14, 20, 'und gepriesen sei der höchste Gott, der dir deine Feinde in die Hand geliefert hat!« Ihm gab (Abram) alsdann den Zehnten von allem.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 14, 21, 'Da sagte der König von Sodom zu Abram: »Gib mir die (gefangenen) Leute und behalte die Habe für dich!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 14, 22, 'Aber Abram antwortete dem König von Sodom: »Ich hebe meine Hand zum HERRN auf, zum höchsten Gott, dem Schöpfer des Himmels und der Erde (und schwöre):');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 14, 23, 'Keinen Faden und keinen Schuhriemen, überhaupt nichts von deinem ganzen Eigentum will ich behalten! Du sollst nicht sagen können, du habest Abram reich gemacht.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 14, 24, 'Ich will nichts davon! Nur was die Knechte verzehrt haben und den Beuteanteil, der den mit mir verbündeten Männern Aner, Eskol und Mamre zukommt: die sollen ihren Anteil nehmen!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 15, 1, 'Nach diesen Begebenheiten erging das Wort des HERRN an Abram in einem Gesicht also: »Fürchte dich nicht, Abram! Ich bin ja dein Schild; dein Lohn soll sehr groß sein.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 15, 2, 'Abram aber antwortete: »Ach HERR, mein Gott, was könntest du mir geben? Ich gehe ja als kinderloser Mann dahin, und der Besitzer meines Vermögens wird (mein hausgeborener Knecht) Elieser von Damaskus sein.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 15, 3, 'Dann fuhr Abram fort: »Ach, du hast mir ja keine Kinder gegeben [darum wird einer von den Knechten meines Hauses mein Erbe sein]!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 15, 4, 'Aber da erging das Wort des HERRN an ihn also: »Nicht dieser soll dein Erbe sein; sondern ein leiblicher Sproß soll es sein, der dich beerbt.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 15, 5, 'Darauf ließ er ihn ins Freie hinaustreten und sagte: »Blicke zum Himmel empor und zähle die Sterne, wenn du sie zählen kannst!« Dann fuhr er fort: »So (unzählbar) soll deine Nachkommenschaft sein!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 15, 6, 'Da glaubte Abram dem HERRN, und das rechnete dieser ihm als Gerechtigkeit an.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 15, 7, 'Dann sagte Gott zu ihm: »Ich bin der HERR, der dich aus Ur in Chaldäa hat auswandern lassen, um dir dieses Land zum Besitz zu geben.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 15, 8, 'Abram erwiderte: »HERR, mein Gott! Woran soll ich erkennen, daß ich es besitzen werde?«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 15, 9, 'Da antwortete er ihm: »Hole mir eine dreijährige Kuh, eine dreijährige Ziege und einen dreijährigen Widder, dazu eine Turteltaube und eine junge Taube!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 15, 10, 'Da holte er ihm alle diese Tiere, schnitt sie in der Mitte durch und legte die Hälften eines jeden Tieres einander gegenüber; die Vögel aber schnitt er nicht entzwei.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 15, 11, 'Da stießen die Raubvögel auf die Fleischstücke herab, aber Abram verscheuchte sie.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 15, 12, 'Als nun die Sonne sich zum Untergang neigte, fiel ein tiefer Schlaf auf Abram, und zugleich stellte sich eine Beängstigung, tiefe Finsternis, bei ihm ein.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 15, 13, 'Da sprach er zu Abram: »Sicher wissen sollst du, daß deine Nachkommen als Fremdlinge in einem Lande weilen werden, das ihnen nicht gehört; dort werden sie als Knechte dienen müssen, und man wird sie bedrücken vierhundert Jahre lang.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 15, 14, 'Aber auch das Volk, dem sie dienen müssen, will ich zur Rechenschaft ziehen; und darnach werden sie mit reicher Habe ausziehen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 15, 15, 'Du aber sollst in Frieden zu deinen Vätern eingehen und in gutem Alter begraben werden.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 15, 16, 'Aber erst das vierte Geschlecht von ihnen wird hierher zurückkehren; denn das Maß der Sündenschuld der Amoriter ist bis jetzt noch nicht voll.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 15, 17, 'Als dann die Sonne untergegangen und tiefe Dunkelheit eingetreten war, da war es wie ein rauchender Backofen und eine Feuerfackel, was zwischen jenen Fleischstücken hindurchfuhr.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 15, 18, 'An jenem Tage schloß der HERR einen Bund mit Abram und erklärte: »Deiner Nachkommenschaft will ich dieses Land geben vom Bach Ägyptens bis an den großen Strom, den Euphratstrom:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 15, 19, 'die Keniter, Kenissiter, Kadmoniter,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 15, 20, 'Hethiter, Pherissiter, Rephaiter,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 15, 21, 'Amoriter, Kanaaniter, Girgasiter und Jebusiter.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 16, 1, 'Sarai, Abrams Frau, hatte ihm keine Kinder geboren; sie hatte aber eine ägyptische Leibmagd namens Hagar.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 16, 2, 'Da sagte Sarai zu Abram: »Du siehst, daß der HERR mir Kindersegen versagt hat. So gehe doch ein zu meiner Leibmagd: vielleicht komme ich durch sie zu Kindern.« Als Abram auf diesen Vorschlag seiner Frau einging,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 16, 3, 'nahm Sarai, Abrams Frau, ihre ägyptische Leibmagd Hagar und gab sie ihrem Manne Abram zum Weibe. – Abram hatte damals aber zehn Jahre lang im Lande Kanaan gewohnt. –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 16, 4, 'Abram ging dann zu Hagar ein, und sie wurde guter Hoffnung; als sie aber merkte, daß sie Mutter werden würde, sah sie ihre Herrin geringschätzig an.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 16, 5, 'Da sagte Sarai zu Abram: »Die Kränkung, die mir zugefügt wird, ist deine Schuld! Ich selbst habe dir meine Leibmagd in die Arme gegeben; jetzt aber, da sie fühlt, daß sie Mutter werden wird, sieht sie mich geringschätzig an: der HERR sei Richter zwischen mir und dir!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 16, 6, 'Da sagte Abram zu Sarai: »Deine Leibmagd steht ja doch unter deiner Gewalt: verfahre mit ihr, wie es dich gut dünkt!« Als nun Sarai sie hart behandelte, entfloh sie ihr.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 16, 7, 'Da fand der Engel des HERRN sie an einer Wasserquelle in der Wüste, an der Quelle auf dem Wege nach Sur,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 16, 8, 'und fragte sie: »Hagar, Leibmagd der Sarai, woher kommst du, und wohin willst du?« Sie antwortete: »Ich bin auf der Flucht vor meiner Herrin Sarai.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 16, 9, 'Da sagte der Engel des HERRN zu ihr: »Kehre zu deiner Herrin zurück und unterwirf dich ihrer Gewalt.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 16, 10, 'Dann fuhr der Engel des HERRN fort: »Ich will deine Nachkommenschaft überaus zahlreich werden lassen, so daß man sie vor Menge nicht soll zählen können.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 16, 11, 'Weiter sagte der Engel des HERRN zu ihr: »Du bist jetzt guter Hoffnung und wirst Mutter eines Sohnes werden, den du Ismael nennen sollst; denn der HERR hat auf deinen Notschrei gehört.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 16, 12, 'Der wird ein Mensch wie ein Wildesel sein: seine Hand gegen alle und die Hand aller gegen ihn, und allen seinen Brüdern wird er trotzig gegenüberstehen.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 16, 13, 'Da nannte sie den Namen des HERRN, der zu ihr geredet hatte: »Du bist der Gott des Schauens; denn«, sagte sie, »ich habe wirklich hier den geschaut, der nach mir geschaut hat.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 16, 14, 'Darum hat man den Brunnen ›Brunnen des Lebendigen, der nach mir schaut‹ genannt; er liegt bekanntlich zwischen Kades und Bered.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 16, 15, 'Hagar gebar dann dem Abram einen Sohn, und Abram gab seinem Sohne, den Hagar ihm geboren hatte, den Namen Ismael.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 16, 16, 'Abram war aber sechsundachtzig Jahre alt, als Hagar ihm den Ismael gebar.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 1, 'Als nun Abram neunundneunzig Jahre alt war, erschien ihm der HERR und sagte zu ihm: »Ich bin der allmächtige Gott: wandle vor mir und sei fromm!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 2, 'Ich will einen Bund zwischen mir und dir stiften und dich überaus zahlreich werden lassen.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 3, 'Da warf sich Abram auf sein Angesicht nieder; Gott aber redete weiter mit ihm so:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 4, '»Wisse wohl: mein Bund mit dir geht dahin, daß du der Stammvater einer Menge von Völkern werden sollst.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 5, 'Darum sollst du hinfort nicht mehr Abram heißen, sondern dein Name soll jetzt Abraham lauten; denn zum Stammvater einer Menge von Völkern habe ich dich bestimmt.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 6, 'Ich will dich also überaus zahlreich werden lassen und dich zu (ganzen) Völkern machen; auch Könige sollen von dir abstammen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 7, 'Und ich will meinen Bund errichten zwischen mir und dir und deinen Nachkommen nach dir, Geschlecht für Geschlecht, als einen ewigen Bund, um dein Gott zu sein und (der Gott) deiner Nachkommen nach dir.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 8, 'Und ich will dir und deinen Nachkommen nach dir das Land, in dem du (jetzt) als Fremdling weilst, nämlich das ganze Land Kanaan, zum ewigen Besitz geben und will ihr Gott sein.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 9, 'Weiter sagte Gott zu Abraham: »Was dich aber betrifft, so sollst du den Bund mit mir halten, du samt deinen Nachkommen nach dir, Geschlecht für Geschlecht!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 10, 'Dies aber ist mein Bund, den ihr halten sollt und der zwischen mir und euch und deinen Nachkommen nach dir besteht: Alles Männliche soll bei euch beschnitten werden!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 11, 'Und zwar sollt ihr am Fleisch eurer Vorhaut beschnitten werden: das soll das Zeichen des Bundes zwischen mir und euch sein!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 12, 'Jedes Knäblein soll im Alter von acht Tagen bei euch die Beschneidung empfangen, Geschlecht für Geschlecht, auch der im Hause geborene, sowie der für Geld von irgendeinem Fremden gekaufte Knecht, mag er auch nicht zu deiner Nachkommenschaft gehören.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 13, 'Ja, beschnitten soll werden sowohl der in deinem Hause geborene als auch der für Geld von dir gekaufte Knecht: darin soll mein Bundeszeichen an eurem Leibe bestehen als ein ewiges Bundeszeichen!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 14, 'Ein unbeschnittener Männlicher aber, der am Fleisch seiner Vorhaut nicht beschnitten worden ist – ein solcher Mensch soll aus seinen Volksgenossen ausgerottet werden: meinen Bund hat er gebrochen!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 15, 'Weiter sprach Gott zu Abraham: »Deine Frau Sarai sollst du nicht mehr Sarai nennen, sondern Sara soll ihr Name sein.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 16, 'Denn ich will sie segnen und dir auch von ihr einen Sohn geben; ja ich will sie segnen, daß sie zu (ganzen) Völkern werden soll; sogar Könige von Völkerschaften sollen von ihr abstammen.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 17, 'Da warf sich Abraham auf sein Angesicht nieder und lachte; denn er dachte bei sich: »Einem Hundertjährigen soll noch (ein Sohn) geboren werden? Und die neunzigjährige Sara soll noch Mutter werden?«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 18, 'So sagte denn Abraham zu Gott: »Ach möchte nur Ismael vor dir am Leben bleiben!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 19, 'Doch Gott antwortete: »Ganz gewiß wird deine Frau Sara dir einen Sohn gebären, den du Isaak nennen sollst; und ich will meinen Bund mit ihm aufrichten als einen ewigen Bund für seine Nachkommen nach ihm.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 20, 'Aber auch in betreff Ismaels habe ich dich erhört; wisse wohl: ich will ihn segnen und fruchtbar werden lassen und ihm eine überaus zahlreiche Nachkommenschaft verleihen: zwölf Fürsten soll er zu Nachkommen haben, und zu einem großen Volke will ich ihn machen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 21, 'Jedoch meinen Bund will ich mit Isaak aufrichten, der dir von Sara übers Jahr um diese Zeit geboren werden soll.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 22, 'Als Gott nun seine Unterredung mit Abraham beendet hatte, fuhr er (zum Himmel) empor von Abraham weg.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 23, 'Darauf nahm Abraham seinen Sohn Ismael und alle in seinem Hause geborenen Knechte sowie alle für Geld von ihm gekauften Knechte, alle männlichen Personen unter den Leuten in seinem Hause, und vollzog die Beschneidung an ihnen noch an eben diesem Tage, wie Gott es ihm geboten hatte.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 24, 'Abraham war aber neunundneunzig Jahre alt, als er vorschriftsgemäß beschnitten wurde,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 25, 'und sein Sohn Ismael war dreizehn Jahre alt, als man ihn vorschriftsgemäß beschnitt.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 26, 'An einem und demselben Tage wurden Abraham und sein Sohn Ismael beschnitten;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 27, 'und mit ihm wurden alle männlichen Personen in seinem hause beschnitten, sowohl die im Hause geborenen als auch die für Geld von Fremden gekauften Knechte.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 1, 'Dann erschien ihm der HERR bei den Terebinthen Mamres, während er gerade um die Zeit der Mittagshitze am Eingang seines Zeltes saß.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 2, 'Als er nämlich aufblickte und hinsah, standen plötzlich drei Männer vor ihm. Kaum hatte er sie erblickt, da eilte er ihnen vom Eingang seines Zeltes aus entgegen, verneigte sich vor ihnen bis auf den Boden');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 3, 'und sagte: »O Herr, wenn ich irgend Gnade in deinen Augen gefunden habe, so gehe doch nicht an deinem Knechte vorüber!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 4, 'Man soll euch etwas Wasser bringen, damit ihr euch die Füße waschen könnt; dann ruht euch unter dem Baume aus,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 5, 'und ich will euch etwas zu essen holen, damit ihr euch erquickt: danach mögt ihr weiterziehen; ihr seid doch nun einmal bei eurem Knecht vorübergekommen.« Sie antworteten: »Tu so, wie du gesagt hast!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 6, 'Da eilte Abraham zu Sara ins Zelt und sagte: »Nimm schnell drei Maß Mehl, feines Mehl, knete es und backe Kuchen!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 7, 'Dann eilte Abraham zu den Rindern, nahm ein zartes, gutes Kalb und übergab es dem Knechte; der mußte es schnell zubereiten.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 8, 'Dann holte er Sauermilch und süße Milch sowie das Kalb, das er hatte zubereiten lassen, und setzte es ihnen vor; er selbst aber bediente sie unter dem Baume, während sie aßen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 9, 'Da fragten sie ihn: »Wo ist deine Frau Sara?« Er antwortete: »Drinnen im Zelt.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 10, 'Da sagte jener: »Übers Jahr um diese Zeit will ich wieder zu dir kommen: dann wird deine Frau Sara einen Sohn haben.« Sara horchte aber am Zelteingang, der hinter ihm war.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 11, 'Abraham und Sara waren aber alt und hochbetagt, so daß Sara nach ihrer leiblichen Beschaffenheit keine Kinder mehr erwarten konnte.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 12, 'Darum lachte Sara in sich hinein und dachte: »Jetzt, nachdem ich verwelkt bin, sollte ich noch an Liebeslust denken? Und mein Eheherr ist ja auch ein Greis.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 13, 'Da sagte der HERR zu Abraham: »Warum hat denn Sara gelacht und denkt: ›Sollte ich alte Frau wirklich noch Mutter werden können?‹');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 14, 'Ist etwa für den HERRN irgend etwas unmöglich? Zu der genannten Zeit, übers Jahr, komme ich wieder zu dir: dann wird Sara einen Sohn haben.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 15, 'Da leugnete Sara und sagte: »Ich habe nicht gelacht!«, denn sie fürchtete sich. Er aber entgegnete: »Doch, du hast gelacht!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 16, 'Nunmehr brachen die drei Männer von dort auf und schauten aus nach Sodom hinab, während Abraham mit ihnen ging, um ihnen das Geleit zu geben.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 17, 'Da dachte der HERR: »Soll ich vor Abraham geheimhalten, was ich zu tun vorhabe?');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 18, 'Abraham soll ja doch zu einem großen und mächtigen Volk werden, und in ihm sollen alle Völker der Erde gesegnet werden;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 19, 'denn ich habe ihn dazu ausersehen, daß er seinen Söhnen und seinem ganzen Hause nach ihm ans Herz lege, den Weg des HERRN innezuhalten, indem sie Gerechtigkeit und Recht üben, damit der HERR für Abraham alles in Erfüllung gehen lasse, was er in bezug auf ihn verheißen hat.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 20, 'So sagte denn der HERR: »Das Geschrei über Sodom und Gomorrha ist gar groß geworden, und ihre Sünde ist wahrlich sehr schwer.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 21, 'Darum will ich hinabgehen und zusehen, ob sie wirklich ganz so gehandelt haben, wie die lauten Klagen, die zu mir gedrungen sind, von ihnen melden, oder ob es sich nicht so verhält: ich will es erkunden.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 22, 'Hierauf wandten sich die (anderen beiden) Männer von dort weg und gingen auf Sodom zu, während Abraham noch vor dem HERRN stehenblieb.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 23, 'Da trat Abraham näher heran und sagte: »Willst du wirklich die Gerechten zugleich mit den Gottlosen wegraffen?');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 24, 'Vielleicht gibt es fünfzig Gerechte innerhalb der Stadt: willst du die wirklich umkommen lassen und nicht lieber dem Orte vergeben um der fünfzig Gerechten willen, die in ihm sind?');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 25, 'Fern sei es von dir, so zu handeln, die Gerechten zusammen mit den Gottlosen ums Leben zu bringen, so daß es den Gerechten ebenso ergeht wie den Gottlosen: das sei fern von dir! Der Richter der ganzen Erde muß doch Gerechtigkeit üben!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 26, 'Da antwortete der HERR: »Wenn ich in Sodom fünfzig Gerechte innerhalb der Stadt finden sollte, so will ich dem ganzen Ort um ihretwillen vergeben.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 27, 'Darauf nahm Abraham wieder das Wort und sagte: »Ach siehe, ich habe es gewagt, zu dem Allherrn zu reden, obgleich ich nur Staub und Asche bin.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 28, 'Vielleicht fehlen an den fünfzig Gerechten noch fünf: willst du da wegen dieser fünf die ganze Stadt vernichten?« Er antwortete: »Nein, ich will sie nicht vernichten, wenn ich dort fünfundvierzig finde.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 29, 'Darauf fuhr Abraham fort, ihn nochmals anzureden, und sagte: »Vielleicht finden sich deren dort nur vierzig.« Jener erwiderte: »Ich will ihnen um der vierzig willen nichts tun.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 30, 'Abraham sagte: »Möge doch der Allherr nicht zürnen, wenn ich nochmals rede: vielleicht finden sich dort nur dreißig.« Er antwortete: »Ich will ihnen nichts tun, wenn ich dort dreißig finde.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 31, 'Er sagte weiter: »Siehe doch, ich habe es gewagt, zu dem Allherrn zu reden: vielleicht finden sich dort nur zwanzig.« Er antwortete: »Ich will sie schon um der zwanzig willen nicht vernichten.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 32, 'Da sagte er: »Möge doch der Allherr nicht zürnen, wenn ich noch dies eine Mal rede: vielleicht finden sich dort nur zehn.« Er erwiderte: »Ich will sie schon um der zehn willen nicht vernichten.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 33, 'Hierauf ging der HERR weg, nachdem er das Gespräch mit Abraham beendet hatte; Abraham aber kehrte nach Hause zurück.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 1, 'Als nun die beiden Engel am Abend nach Sodom kamen, saß Lot gerade am Tor von Sodom. Sobald Lot sie erblickte, erhob er sich vor ihnen, verneigte sich mit dem Angesicht bis zur Erde');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 2, 'und sagte: »Bitte, meine Herren! Kehrt doch im Hause eures Knechtes ein, um dort zu übernachten, und wascht euch die Füße; morgen früh mögt ihr euch dann wieder aufmachen und eures Weges ziehen.« Sie aber antworteten: »Nein, wir wollen hier im Freien übernachten.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 3, 'Da nötigte er sie dringend, bis sie bei ihm einkehrten und in sein Haus eintraten. Dann bereitete er ihnen ein Mahl und ließ ungesäuerte Kuchen backen, die sie aßen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 4, 'Noch hatten sie sich aber nicht schlafen gelegt, als die Männer der Stadt, die Bürger von Sodom, das Haus umzingelten, jung und alt, die ganze Bevölkerung bis auf den letzten Mann.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 5, 'Die riefen nach Lot und sagten zu ihm: »Wo sind die Männer, die heute abend zu dir gekommen sind? Bringe sie zu uns heraus, damit wir uns an sie machen!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 6, 'Da trat Lot zu ihnen hinaus an den Eingang des Hauses, schloß aber die Tür hinter sich zu');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 7, 'und sagte: »Meine Brüder, vergeht euch doch nicht so arg!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 8, 'Hört: ich habe zwei Töchter, die noch mit keinem Manne zu tun gehabt haben; die will ich zu euch herausbringen: macht dann mit ihnen, was euch beliebt. Nur diesen Männern tut nichts zuleide, nachdem sie einmal unter den Schatten meines Daches getreten sind!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 9, 'Doch sie antworteten: »Zurück da!«, und weiter sagten sie: »Der ist der einzige Fremde, der gekommen ist, um hier zu wohnen, und will nun den Herrn spielen! Warte nur, wir wollen es mit dir noch schlimmer machen als mit jenen!« So drangen sie denn auf den Mann, auf Lot, mit Gewalt ein und gingen daran, die Tür zu erbrechen;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 10, 'doch die Männer griffen mit ihren Händen hinaus, zogen Lot zu sich ins Haus herein und verschlossen die Tür;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 11, 'dann schlugen sie die Männer vor dem Eingang des Hauses mit Blindheit, klein und groß, so daß sie sich vergebens bemühten, den Eingang zu finden.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 12, 'Darauf sagten die Männer zu Lot: »Wen du sonst noch hier hast – einen Schwiegersohn sowie deine Söhne und Töchter und wer dir sonst noch in der Stadt angehört –, die laß aus diesem Orte weggehen;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 13, 'denn wir wollen diesen Ort zerstören, weil schlimme Klagen über ihn vor dem HERRN laut geworden sind; daher hat der HERR uns gesandt, die Stadt zu zerstören.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 14, 'Da ging Lot aus dem Hause hinaus und sagte zu seinen Schwiegersöhnen, die seine Töchter geheiratet hatten: »Macht euch auf und verlaßt diesen Ort! Denn der HERR will die Stadt zerstören.« Aber er kam seinen Schwiegersöhnen vor wie einer, der Scherz (mit ihnen) trieb.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 15, 'Als dann die Morgenröte aufstieg, drängten die Engel Lot zur Eile mit den Worten: »Auf! Nimm deine Frau und deine beiden Töchter, die hier bei dir anwesend sind, damit du nicht auch wegen der Sündhaftigkeit der Stadt ums Leben kommst.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 16, 'Als er aber immer noch zögerte, faßten die Männer ihn und seine Frau und seine beiden Töchter bei der Hand, weil der HERR ihn verschonen wollte; sie führten ihn hinaus und ließen ihn erst draußen vor der Stadt wieder los.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 17, 'Als sie nun mit ihnen draußen im Freien waren, sagte der eine: »Rette dich: es gilt dein Leben! Sieh dich nicht um und bleibe nirgends in der Jordan-Ebene stehen! Rette dich in das Gebirge, damit du nicht auch ums Leben kommst!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 18, 'Da antwortete ihnen Lot: »Ach nein, mein Herr!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 19, 'Bedenke doch: dein Knecht hat (nun einmal) Gnade in deinen Augen gefunden, und du hast mir die große Barmherzigkeit erwiesen, mich am Leben zu erhalten; aber ich vermag mich nicht in das Gebirge zu retten: das Verderben würde mich ereilen, so daß ich sterben müßte!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 20, 'Siehe, dort ist eine Ortschaft in der Nähe, so daß ich dahin fliehen könnte, und sie ist ja ganz klein: dorthin möchte ich mich retten; sie ist ja doch ganz klein; dann könnte ich am Leben bleiben!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 21, 'Da antwortete er ihm: »Nun gut, ich will dir auch in diesem Stück zu Willen sein, indem ich den Ort, von dem du sprichst, nicht mit zerstöre.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 22, 'Flüchte dich eilends dorthin! denn ich kann nichts tun, bis du dorthin gekommen bist.« Daher hat der Ort den Namen Zoar erhalten.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 23, 'Als dann die Sonne über der Erde aufgegangen und Lot in Zoar angekommen war,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 24, 'ließ der HERR Schwefel und Feuer vom Himmel herab auf Sodom und Gomorrha regnen');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 25, 'und vernichtete diese Städte und die ganze Jordan-Ebene samt allen Bewohnern der Ortschaften und allem, was auf den Fluren gewachsen war.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 26, 'Lots Frau aber hatte sich hinter ihm umgeschaut; da wurde sie zu einer Salzsäule.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 27, 'Als Abraham sich nun am folgenden Morgen in der Frühe an den Ort begab, wo er vor dem HERRN gestanden hatte,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 28, 'und nach Sodom und Gomorrha hinabschaute und die ganze Fläche der Jordan-Ebene überblickte, da sah er, wie der Rauch vom Lande aufstieg gleich dem Rauch von einem Schmelzofen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 29, 'Gott aber hatte, als er die Städte in der Jordan-Ebene zerstörte, an Abraham gedacht und Lot mitten aus der Zerstörung hinausgeführt, als er die Städte zerstörte, in denen Lot gewohnt hatte.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 30, 'Lot aber zog aus Zoar weiter aufwärts und nahm seinen Wohnsitz zusammen mit seinen beiden Töchtern im Gebirge, denn er fürchtete sich, in Zoar zu bleiben; er ließ sich vielmehr mit seinen beiden Töchtern in einer Höhle nieder.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 31, 'Da sagte die ältere zu der jüngeren: »Unser Vater ist alt, und kein Mann ist sonst im Lande, der Umgang mit uns haben könnte, wie es in aller Welt Brauch ist.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 32, 'Komm, wir wollen unserm Vater Wein zu trinken geben und uns zu ihm legen, damit wir von unserm Vater Nachkommenschaft ins Leben rufen.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 33, 'So gaben sie denn ihrem Vater an jenem Abend Wein zu trinken, und die ältere ging dann hinein und legte sich zu ihrem Vater; er aber merkte nichts davon, weder wie sie sich hinlegte, noch als sie aufstand.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 34, 'Am andern Morgen sagte dann die ältere zu der jüngeren: »Siehst du, ich habe in der vorigen Nacht bei meinem Vater gelegen. Wir wollen ihm nun auch heute abend Wein zu trinken geben; dann gehst du hinein und legst dich zu ihm, damit wir von unserm Vater Nachkommenschaft ins Leben rufen.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 35, 'So gaben sie denn ihrem Vater auch an diesem Abend Wein zu trinken, und die jüngere stand auf und legte sich zu ihm; er aber merkte nichts davon, weder als sie sich hinlegte, noch als sie aufstand.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 36, 'So wurden denn die beiden Töchter Lots von ihrem Vater schwanger.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 37, 'Und die ältere gebar einen Sohn und nannte ihn »Moab«; der ist der Stammvater der heutigen Moabiter.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 38, 'Die jüngere gebar auch einen Sohn und gab ihm den Namen »Ben-Ammi«; der ist der Stammvater der heutigen Ammoniter.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 20, 1, 'Abraham brach dann von dort auf (und zog) in den Südgau, wo er seinen Wohnsitz zwischen Kades und Sur nahm. Er hielt sich aber zeitweise als Fremdling auch in Gerar auf');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 20, 2, 'und gab dort seine Frau Sara für seine Schwester aus. Da sandte Abimelech, der König von Gerar, hin und ließ Sara zu sich holen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 20, 3, 'Aber in der Nacht kam Gott zu Abimelech im Traum und sagte zu ihm: »Jetzt bist du des Todes wegen der Frau, die du dir hast holen lassen: sie ist ja eines Mannes Ehefrau!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 20, 4, 'Abimelech war ihr aber noch nicht nahegekommen; darum antwortete er: »O Herr, du wirst doch nicht ein schuldloses Volk umbringen?');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 20, 5, 'Hat er nicht selbst zu mir gesagt, daß sie seine Schwester sei? Und auch sie selbst hat erklärt, er sei ihr Bruder. In der Unschuld meines Herzens und mit reinen Händen habe ich dies getan!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 20, 6, 'Da sagte Gott weiter im Traum zu ihm: »Auch ich weiß wohl, daß du in der Unschuld deines Herzens so gehandelt hast, und ich selbst habe dich davor behütet, daß du dich gegen mich versündigt hast; darum habe ich auch nicht zugelassen, daß du sie berührtest.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 20, 7, 'So gibt also jetzt dem Manne seine Frau zurück, denn er ist ein Prophet; dann soll er Fürbitte für dich einlegen, so daß du am Leben bleibst. Gibst du sie aber nicht zurück, so wisse, daß du mit allen deinen Angehörigen sterben mußt!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 20, 8, 'Am andern Morgen in der Frühe berief Abimelech eiligst alle seine Diener und teilte ihnen den ganzen Vorfall mit; da gerieten die Männer in große Bestürzung.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 20, 9, 'Abimelech ließ dann Abraham rufen und sagte zu ihm: »Was hast du uns da angetan? Worin habe ich mich dir gegenüber verfehlt, daß du eine so große Verschuldung über mich und mein Reich gebracht hast? Du hast an mir in einer Weise gehandelt, wie es nicht recht ist!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 20, 10, 'Weiter sagte Abimelech zu Abraham: »Was hast du dir denn dabei gedacht, daß du so gehandelt hast?«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 20, 11, 'Da antwortete Abraham: »Ja, ich dachte, es sei sicherlich keine Gottesfurcht an diesem Orte zu finden und man werde mich um meiner Frau willen ums Leben bringen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 20, 12, 'Übrigens ist sie wirklich meine Schwester, die Tochter meines Vaters, nur nicht die Tochter meiner Mutter, und so hat sie meine Frau werden können.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 20, 13, 'Als mich nun Gott einst aus meines Vaters Hause ins Ungewisse wegziehen hieß, da habe ich zu ihr gesagt: ›Erweise mir die Liebe, daß du überall, wohin wir kommen werden, von mir sagst, ich sei dein Bruder.‹«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 20, 14, 'Da nahm Abimelech Kleinvieh und Rinder, Knechte und Mägde und schenkte sie dem Abraham, auch seine Frau Sara gab er ihm zurück.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 20, 15, 'Dann fügte er hinzu: »Mein Land steht dir nunmehr offen: nimm deinen Wohnsitz, wo es dir gefällt!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 20, 16, 'Zu Sara aber sagte er: »Hier gebe ich deinem Bruder tausend Silberstücke: das soll für dich ein Sühnegeld in den Augen aller sein, die bei dir sind, so daß du nun in allem gerechtfertigt dastehst!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 20, 17, 'Darauf legte Abraham Fürbitte bei Gott ein, und Gott ließ Abimelech, seine Frau und seine Mägde wieder gesund werden, so daß sie wieder Kinder bekommen konnten;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 20, 18, 'denn der HERR hatte den Mutterschoß aller Frauen im Hause Abimelechs verschlossen um Saras, der Frau Abrahams, willen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 1, 'Der HERR suchte dann Sara gnädig heim, wie er verheißen hatte, und tat an ihr, wie er zugesagt hatte:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 2, 'Sara wurde guter Hoffnung und gebar dem Abraham in seinem Greisenalter einen Sohn zu der Zeit, die Gott ihm im voraus angegeben hatte.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 3, 'Abraham gab dann seinem Sohne, der ihm geboren worden war, den Sara ihm geboren hatte, den Namen Isaak');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 4, 'und beschnitt seinen Sohn, als er acht Tage alt war, wie Gott ihm geboten hatte.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 5, 'Hundert Jahre war Abraham alt, als ihm sein Sohn Isaak geboren wurde.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 6, 'Da sagte Sara: »Ein Lachen hat mir Gott bereitet: jeder, der von der Sache hört, wird über mich lachen.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 7, 'Weiter sagte sie: »Wer hätte wohl je dem Abraham gesagt, daß Sara noch Kinder an der Brust nähren würde? Und nun habe ich ihm doch noch einen Sohn in seinem Greisenalter geboren!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 8, 'Und der Knabe wuchs heran und wurde entwöhnt; da veranstaltete Abraham am Tage der Entwöhnung Isaaks ein großes Festmahl.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 9, 'Als nun Sara den Sohn der Ägypterin Hagar, den diese dem Abraham geboren hatte, mit ihrem Sohne Isaak spielen sah,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 10, 'sagte sie zu Abraham: »Verstoße die Magd da und ihren Sohn! Denn der Sohn dieser Magd soll nicht mit meinem Sohn, mit Isaak, erben!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 11, 'Dieses Wort betrübte Abraham sehr mit Rücksicht auf seinen Sohn;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 12, 'aber Gott sagte zu Abraham: »Laß es dir um den Knaben und um deine Magd nicht leid sein: gehorche der Sara in allem, was sie von dir verlangt; denn nur nach Isaak soll dir Nachkommenschaft genannt werden.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 13, 'Doch auch den Sohn der Magd will ich zu einem Volke werden lassen, weil er dein Sohn ist.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 14, 'So stand denn Abraham am andern Morgen früh auf, nahm Brot und einen Schlauch mit Wasser und gab dies der Hagar; den Knaben aber setzte er ihr auf die Schulter und entließ so beide. Da ging sie weg und irrte in der Wüste von Beerseba umher.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 15, 'Als dann das Wasser im Schlauch zu Ende gegangen war, warf sie den Knaben unter einen der Sträucher,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 16, 'ging weg und setzte sich abseits ihm gegenüber, wohl einen Bogenschuß weit entfernt; »denn«, sagte sie, »ich kann das Sterben des Knaben nicht ansehen!« Sie setzte sich also ihm gegenüber; er aber fing an, laut zu weinen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 17, 'Da hörte Gott das Schreien des Knaben, und der Engel Gottes rief der Hagar vom Himmel her die Worte zu: »Was ist dir, Hagar? Fürchte dich nicht! Denn Gott hat das Schreien des Knaben gehört, ebendort wo er liegt.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 18, 'Stehe auf, nimm den Knaben und halte ihn fest an der Hand, denn ich will ihn zu einem großen Volke werden lassen.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 19, 'Dann tat Gott ihr die Augen auf, so daß sie eine Quelle mit Wasser erblickte; da ging sie hin, füllte den Schlauch mit Wasser und gab dem Knaben zu trinken.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 20, 'Und Gott war mit dem Knaben, so daß er heranwuchs; er nahm seinen Aufenthalt in der Wüste und wurde ein gewaltiger Bogenschütze;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 21, 'und zwar nahm er seinen Aufenthalt in der Wüste Paran, und seine Mutter nahm ihm eine Ägypterin zur Frau.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 22, 'Zu derselben Zeit hatte Abimelech nebst seinem Heerführer Pichol eine Unterredung mit Abraham und sagte: »Gott ist mit dir in allem, was du unternimmst.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 23, 'Darum schwöre mir jetzt hier bei Gott, daß du weder gegen mich noch gegen meine Kinder und Kindeskinder jemals treulos handeln, sondern dieselbe Freundschaft, die ich dir erwiesen habe, auch mir und dem Lande erweisen willst, in welchem du als Fremdling dich aufhältst!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 24, 'Da antwortete Abraham: »Ja, ich will den Schwur leisten.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 25, 'Abraham machte aber dem Abimelech Vorhalt wegen des Wasserbrunnens, den die Knechte Abimelechs sich mit Gewalt angeeignet hatten.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 26, 'Abimelech erwiderte: »Ich weiß nicht, wer das getan hat: weder hast du mir bisher etwas davon mitgeteilt, noch habe ich bis heute etwas davon gehört.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 27, 'Hierauf nahm Abraham Kleinvieh und Rinder und gab sie dem Abimelech, und sie schlossen beide einen Vertrag miteinander.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 28, 'Als nun Abraham noch sieben Schaflämmer abgesondert stellte,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 29, 'fragte Abimelech den Abraham: »Was sollen die sieben Lämmer hier bedeuten, die du besonders gestellt hast?«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 30, 'Er antwortete: »Die sieben Lämmer mußt du von mir annehmen, damit dies mir zum Zeugnis diene, daß ich diesen Brunnen gegraben habe.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 31, 'Darum nennt man jenen Ort »Beerseba«, weil sie beide dort einander geschworen haben.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 32, 'Nachdem sie so einen Vertrag zu Beerseba geschlossen hatten, brach Abimelech mit seinem Heerführer Pichol auf, und sie kehrten ins Philisterland zurück.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 33, '(Abraham) aber pflanzte eine Tamariske in Beerseba und rief dort den Namen des HERRN, des ewigen Gottes, an.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 34, 'Abraham hielt sich dann noch geraume Zeit als Fremdling im Philisterlande auf.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 22, 1, 'Nach diesen Begebenheiten wollte Gott den Abraham auf die Probe stellen und sagte zu ihm: »Abraham!« Dieser antwortete: »Hier bin ich!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 22, 2, 'Da sagte Gott: »Nimm Isaak, deinen Sohn, deinen einzigen, den du liebhast, und begib dich (mit ihm) in die Landschaft Morija und bringe ihn dort als Brandopfer dar auf einem der Berge, den ich dir angeben werde!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 22, 3, 'Da sattelte Abraham am andern Morgen früh seinen Esel und nahm zwei von seinen Knechten und seinen Sohn Isaak mit sich; er spaltete Holzscheite für das Brandopfer und machte sich dann auf den Weg nach dem Orte, den Gott ihm angegeben hatte.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 22, 4, 'Als er am dritten Tage die Augen aufschlug, sah er den Ort in der Ferne liegen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 22, 5, 'Da sagte Abraham zu seinen Knechten: »Bleibt ihr für euch hier mit dem Esel; ich aber und der Knabe wollen dorthin gehen und anbeten; dann kommen wir wieder zu euch zurück.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 22, 6, 'Hierauf nahm Abraham das Holz für das Brandopfer und belud seinen Sohn Isaak damit; er selbst aber nahm das Feuer und das Schlachtmesser in die Hand, und so gingen die beiden zusammen weiter.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 22, 7, 'Da sagte Isaak zu seinem Vater Abraham: »Mein Vater!« Abraham antwortete: »Was willst du, mein Sohn?« Da sagte er: »Wir haben hier wohl Feuer und Holz; aber wo ist das Schaf für das Brandopfer?«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 22, 8, 'Abraham erwiderte: »Gott wird schon für ein Schaf zum Brandopfer sorgen, mein Sohn.« So gingen die beiden zusammen weiter.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 22, 9, 'Als sie nun an den Ort gekommen waren, den Gott ihm angegeben hatte, errichtete Abraham daselbst einen Altar und legte die Holzscheite auf ihm zurecht; dann band er seinen Sohn Isaak und legte ihn auf den Altar oben über die Scheite;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 22, 10, 'darauf streckte er seine Hand aus und nahm das Messer, um seinen Sohn zu schlachten.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 22, 11, 'Da rief ihm der Engel des HERRN vom Himmel her die Worte zu: »Abraham, Abraham!« Er antwortete: »Hier bin ich!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 22, 12, 'Jener rief: »Lege deine Hand nicht an den Knaben und tu ihm nichts zuleide! Denn jetzt weiß ich, daß du gottesfürchtig bist, weil du mir deinen einzigen Sohn nicht vorenthalten hast.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 22, 13, 'Als Abraham dann um sich blickte, sah er hinter sich einen Widder, der sich mit seinen Hörnern im Dickicht verfangen hatte. Da ging Abraham hin, holte den Widder und brachte ihn statt seines Sohnes als Brandopfer dar.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 22, 14, 'Abraham nannte dann jenen Ort: »Der HERR sieht«; deshalb sagt man noch heutigentags: »Auf dem Berge, wo der HERR gesehen wird«.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 22, 15, 'Hierauf rief der Engel des HERRN dem Abraham zum zweitenmal vom Himmel her die Worte zu:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 22, 16, '»Ich schwöre bei mir selbst« – so lautet der Ausspruch des HERRN –: »darum, daß du so gehandelt und mir deinen einzigen Sohn nicht vorenthalten hast,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 22, 17, 'will ich dich reichlich segnen und deine Nachkommenschaft überaus zahlreich machen wie die Sterne am Himmel und wie den Sand am Gestade des Meeres; und deine Nachkommen sollen die Tore ihrer Feinde besitzen,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 22, 18, 'und in deiner Nachkommenschaft sollen alle Völker der Erde gesegnet werden zum Lohn dafür, daß du meiner Aufforderung nachgekommen bist!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 22, 19, 'Darauf kehrte Abraham zu seinen Knechten zurück; und sie machten sich auf den Weg und begaben sich miteinander nach Beerseba; dort nahm Abraham seinen dauernden Wohnsitz.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 22, 20, 'Nach diesen Begebenheiten wurde dem Abraham gemeldet: »Auch Milka hat deinem Bruder Nahor Söhne geboren,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 22, 21, 'nämlich seinen Erstgeborenen Uz und dessen Bruder Bus und Kemuel, den Vater von Aram,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 22, 22, 'und Kesed sowie Haso, Pildas, Jidlaph und Bethuel.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 22, 23, '- Bethuel aber war der Vater der Rebekka. – Diese acht Söhne gebar Milka dem Nahor, dem Bruder Abrahams.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 22, 24, 'Auch sein Nebenweib namens Rehuma hatte Söhne geboren, nämlich Tebah und Gaham, Thahas und Maacha.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 23, 1, 'Als Sara nun ihr Leben auf hundertundsiebenundzwanzig Jahre gebracht hatte,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 23, 2, 'starb sie in Kirjath-Arba, das ist Hebron, im Lande Kanaan. Da ging Abraham hinein, um Sara zu beklagen und zu beweinen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 23, 3, 'Hierauf stand Abraham von der Seite seiner Verstorbenen auf und verhandelte mit den Hethitern so:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 23, 4, '»Ich bin (nur) ein Fremdling und Beisasse hier bei euch: überlaßt mir doch ein Erbbegräbnis bei euch, damit ich meine Tote, die in meinem Hause liegt, begraben kann!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 23, 5, 'Die Hethiter gaben dem Abraham folgende Antwort:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 23, 6, '»Höre uns an, Herr! Du lebst hier als ein Gottesfürst unter uns: begrabe deine Tote in dem besten von unsern Gräbern: keiner von uns wird dir seine Grabstätte zur Bestattung deiner Toten versagen.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 23, 7, 'Da erhob sich Abraham, verneigte sich tief vor den Bewohnern des Landes, den Hethitern,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 23, 8, 'und sagte weiter zu ihnen: »Wenn ihr damit einverstanden seid, daß ich meine Tote, die in meinem Hause liegt, hier begrabe, so erweist mir die Liebe und legt ein gutes Wort für mich bei Ephron, dem Sohne Zohars, ein,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 23, 9, 'daß er mir die Höhle in der Machpela überläßt, die ihm gehört und am Ende seines Feldes liegt; für den vollen Wert möge er sie mir zu einem Erbbegräbnis hier in eurer Mitte überlassen!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 23, 10, 'Nun saß Ephron mitten unter den Hethitern und gab dem Abraham vor den versammelten Hethitern im Beisein aller, die ins Tor seiner Stadt gekommen waren, folgende Antwort:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 23, 11, '»Nicht doch, Herr! Höre mich an! Das Feld schenke ich dir; auch die Höhle darauf schenke ich dir; im Beisein meiner Volksgenossen schenke ich sie dir: begrabe nur deine Tote!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 23, 12, 'Da verneigte sich Abraham tief vor den Bewohnern des Landes');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 23, 13, 'und sagte dann zu Ephron, im Beisein aller Bewohner des Landes: »O doch! Wenn du mich nur anhören wolltest! Ich zahle dir den Preis für das Grundstück: nimm ihn von mir an, so will ich meine Tote dort begraben!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 23, 14, 'Darauf antwortete Ephron dem Abraham:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 23, 15, '»Höre mich doch an, Herr! Ein Stück Land im Wert von vierhundert Schekel Silber – was will das zwischen mir und dir besagen?! Begrabe nur deine Tote!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 23, 16, 'Abraham nahm die Forderung Ephrons an und wog ihm den Kaufpreis dar, den Betrag, welchen jener im Beisein der Hethiter gefordert hatte, nämlich vierhundert Schekel Silber, nach der beim Kauf und Verkauf üblichen Währung.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 23, 17, 'So wurde das Grundstück Ephrons, das in der Machpela östlich von Mamre lag, das Feld samt der Höhle darauf nebst allen Bäumen, die auf dem Grundstück in seinem ganzen Umfang ringsum standen,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 23, 18, 'dem Abraham rechtskräftig als Eigentum abgetreten im Beisein der Hethiter, so viele ihrer ins Tor seiner Stadt gekommen waren.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 23, 19, 'Hierauf begrub Abraham seine Frau Sara in der Höhle auf dem Grundstück in der Machpela östlich von Mamre, das ist Hebron, im Lande Kanaan.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 23, 20, 'So wurde das Grundstück samt der Höhle darauf dem Abraham als Erbbegräbnis von den Hethitern rechtskräftig überlassen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 1, 'Als nun Abraham alt und hochbetagt geworden war und der HERR ihn in allem gesegnet hatte,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 2, 'sagte Abraham zu dem ältesten Knechte seines Hauses, der seinen gesamten Besitz zu verwalten hatte: »Lege deine Hand unter meine Hüfte:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 3, 'ich will dir beim HERRN, dem Gott des Himmels und dem Gott der Erde, einen Eid abnehmen, daß du für meinen Sohn keine Frau aus den Töchtern der Kanaanäer nehmen willst, unter denen ich hier wohne;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 4, 'nein, du sollst in mein Vaterland und zu meiner Verwandtschaft gehen und dort um eine Frau für meinen Sohn Isaak werben!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 5, 'Da antwortete ihm der Knecht: »Vielleicht wird das Weib mir in dieses Land nicht folgen wollen; soll ich alsdann deinen Sohn wieder in das Land zurückführen, aus dem du ausgewandert bist?«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 6, 'Abraham antwortete ihm: »Hüte dich wohl, meinen Sohn dorthin zurückzuführen!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 7, 'Der HERR, der Gott des Himmels, der mich aus meines Vaters Hause und aus meinem Heimatlande weggeführt und der mir zugesagt und mir zugeschworen hat: ›Deinen Nachkommen will ich dieses Land geben‹ – der wird seinen Engel vor dir her senden, so daß du von dort eine Frau für meinen Sohn gewinnst.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 8, 'Wenn das Weib dir aber nicht folgen will, so sollst du von diesem mir geleisteten Eide entbunden sein; nur darfst du meinen Sohn nicht dorthin zurückführen!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 9, 'Da legte der Knecht seine Hand seinem Herrn Abraham unter die Hüfte und leistete ihm in dieser Sache den verlangten Eid.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 10, 'Hierauf nahm der Knecht zehn Kamele von den Kamelen seines Herrn und allerlei Kostbarkeiten seines Herrn zu sich, machte sich auf den Weg und zog nach Mesopotamien nach der Stadt Nahors (Haran).');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 11, 'Dort ließ er die Kamele draußen vor der Stadt bei dem Wasserbrunnen sich lagern zur Abendzeit, zu der Zeit, wo die Frauen herauszukommen pflegen, um Wasser zu holen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 12, 'Dann betete er: »O HERR, du Gott meines Herrn Abraham! Laß es mir doch heute glücken und erweise meinem Herrn Abraham Gnade!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 13, 'Siehe, ich stehe jetzt hier bei der Quelle, und die Töchter der Stadtbewohner werden herauskommen, um Wasser zu holen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 14, 'Wenn ich nun zu einem Mädchen sage: ›Neige, bitte, deinen Krug, damit ich trinke!‹ und sie mir dann antwortet: ›Trinke! Und auch deinen Kamelen will ich zu trinken geben!‹, so möge diese es sein, die du für deinen Knecht Isaak bestimmt hast; und daran will ich erkennen, daß du meinem Herrn Gnade erwiesen hast.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 15, 'Er hatte noch nicht zu Ende geredet, da kam schon Rebekka heraus, die Tochter Bethuels, der ein Sohn der Milka, der Frau Nahors, des Bruders Abrahams, war; sie trug ihren Krug auf der Schulter.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 16, 'Das Mädchen war von großer Schönheit und noch unverheiratet, eine Jungfrau; sie stieg zur Quelle hinab, füllte ihren Krug und kam wieder herauf.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 17, 'Da eilte der Knecht auf sie zu und sagte: »Laß mich doch ein wenig Wasser aus deinem Kruge trinken!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 18, 'Sie antwortete: »Trinke, Herr!« und ließ sogleich ihren Krug (von der Schulter) auf ihre Hand herab und ließ ihn trinken.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 19, 'Als sie aber seinen Durst gestillt hatte, sagte sie: »Auch für deine Kamele will ich Wasser schöpfen, bis sie sich satt getrunken haben.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 20, 'Mit diesen Worten goß sie ihren Krug eilends in die Tränkrinne aus, lief dann nochmals zum Brunnen, um Wasser zu schöpfen, und schöpfte so für alle seine Kamele,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 21, 'während jener ihr verwundert zusah, ohne jedoch ein Wort zu sagen, um zu erkennen, ob der HERR Glück zu seiner Reise gegeben habe oder nicht.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 22, 'Als nun die Kamele sich satt getrunken hatten, nahm der Mann einen goldenen Nasenring, einen halben Schekel schwer, und zwei Spangen für ihre Arme, zehn Schekel Goldes schwer,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 23, 'und fragte sie: »Wessen Tochter bist du? Teile es mir doch mit! Ist wohl im Hause deines Vaters Platz für uns zum Übernachten?«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 24, 'Sie antwortete ihm: »Ich bin die Tochter Bethuels, des Sohnes der Milka, den sie dem Nahor geboren hat.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 25, 'Dann fuhr sie fort: »Sowohl Stroh als auch Futter haben wir in Menge und auch Platz zum Übernachten.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 26, 'Da verneigte sich der Mann, warf sich vor dem HERRN nieder');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 27, 'und rief aus: »Gepriesen sei der HERR, der Gott meines Herrn Abraham, der seine Güte und Treue meinem Herrn nicht entzogen hat! Gerades Weges zum Hause des Verwandten meines Herrn hat mich der Ewige geführt!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 28, 'Das Mädchen aber war unterdessen hingelaufen und hatte im Hause ihrer Mutter alles erzählt, was sich zugetragen hatte.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 29, 'Nun hatte Rebekka einen Bruder namens Laban; dieser eilte zu dem Manne hinaus an die Quelle.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 30, 'Sobald er nämlich den Nasenring und die Spangen an den Armen seiner Schwester erblickt und seine Schwester Rebekka hatte erzählen hören, was der Mann zu ihr gesagt habe, ging er zu dem Manne hinaus, der immer noch bei den Kamelen an der Quelle stand.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 31, 'Er sagte nun zu ihm: »Komm in mein Haus, du Gesegneter des HERRN! Warum stehst du hier draußen? Ich habe das Haus schon aufräumen lassen und Platz für die Kamele geschafft!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 32, 'So kam denn der Mann in das Haus; dort zäumte Laban die Kamele ab, gab ihnen Stroh und Futter und brachte ihm sowie den Leuten, die bei ihm waren, Wasser zum Waschen der Füße.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 33, 'Als man ihm aber zu essen vorsetzte, sagte er: »Ich werde nicht eher essen, als bis ich meine Sache vorgetragen habe.« Jener erwiderte: »So rede!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 34, 'Da berichtete er: »Ich bin ein Knecht Abrahams.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 35, 'Gott der HERR hat meinen Herrn außerordentlich gesegnet, so daß er reich geworden ist; denn er hat ihm Kleinvieh und Rinder, Silber und Gold, Knechte und Mägde, Kamele und Esel gegeben.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 36, 'Dazu hat Sara, die Frau meines Herrn, ihm noch in ihrem Alter einen Sohn geboren; dem hat er alles übergeben, was er besitzt.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 37, 'Nun hat mein Herr mir folgenden Eid abgenommen: ›Du darfst meinem Sohne keine Frau aus den Töchtern der Kanaanäer nehmen, in deren Lande ich wohne,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 38, 'sondern sollst zu meines Vaters Hause und zu meiner Verwandtschaft ziehen, um für meinen Sohn dort eine Frau zu nehmen.‹');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 39, 'Ich entgegnete meinem Herrn: ›Vielleicht wird das Weib mir nicht folgen wollen.‹');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 40, 'Da erwiderte er mir: ›Gott der HERR, vor dessen Angesicht ich gewandelt bin, wird seinen Engel mit dir senden und dir Glück zu deiner Reise geben, damit du für meinen Sohn eine Frau aus meiner Verwandtschaft, und zwar aus dem Hause meines Vaters, gewinnst.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 41, 'Dann sollst du von dem mir geleisteten Eid entbunden sein, wenn du zu meiner Verwandtschaft kommst und man sie dir dort nicht geben will – dann bist du von dem mir geleisteten Eid entbunden.‹');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 42, 'Nun bin ich heute zu der Quelle gekommen und habe gebetet: ›O HERR, du Gott meines Herrn Abraham! wenn du doch Glück zu der Reise geben möchtest, auf der ich mich jetzt befinde!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 43, 'Siehe, ich stehe jetzt hier an der Quelle. Laß es doch geschehen, daß das Mädchen, das herauskommt, um Wasser zu holen, und zu der ich sage: Gib mir, bitte, ein wenig Wasser aus deinem Kruge zu trinken!,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 44, 'daß die mir dann antwortet: Trinke du selbst, und auch für deine Kamele will ich Wasser schöpfen! – so möge diese es sein, die Gott der HERR dem Sohne meines Herrn zur Frau bestimmt hat!‹');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 45, 'Ich hatte dieses bei mir noch nicht zu Ende geredet, da kam auch schon Rebekka aus dem Orte heraus mit ihrem Kruge auf ihrer Schulter; sie stieg zur Quelle hinab und schöpfte Wasser. Da bat ich sie: ›Gib mir, bitte, zu trinken!‹');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 46, 'Sogleich ließ sie ihren Krug (von der Schulter) herab und sagte: ›Trinke, und auch deinen Kamelen will ich zu trinken geben!‹ Da trank ich, und sie tränkte dann auch die Kamele.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 47, 'Hierauf fragte ich sie, wessen Tochter sie sei, und sie antwortete: ›Die Tochter Bethuels, des Sohnes Nahors, den Milka ihm geboren hat.‹ Da legte ich ihr den Ring an die Nase und die Spangen an ihre Arme;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 48, 'dann verneigte ich mich vor Gott dem HERRN, warf mich vor ihm nieder und pries den HERRN, den Gott meines Herrn Abraham, der mich den rechten Weg geführt hatte, um die Tochter des Verwandten meines Herrn für seinen Sohn zu gewinnen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 49, 'Und nun, wenn ihr meinem Herrn Liebe und Treue erweisen wollt, so sagt es mir! Wo nicht, so sagt es mir auch, damit ich mich zur Rechten oder zur Linken wende!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 50, 'Da antworteten Laban und Bethuel: »Von Gott dem HERRN ist dies ausgegangen: wir können dir nichts dazu sagen, weder ja noch nein.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 51, 'Rebekka steht dir zur Verfügung: nimm sie und ziehe hin, damit sie die Frau des Sohnes deines Herrn wird, wie Gott der HERR es bestimmt hat!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 52, 'Sobald der Knecht Abrahams diese ihre Worte gehört hatte, verbeugte er sich vor Gott dem HERRN bis auf die Erde;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 53, 'dann holte er silberne und goldene Geräte und Gewänder hervor und schenkte sie der Rebekka; auch ihrem Bruder und ihrer Mutter schenkte er Kostbarkeiten.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 54, 'Dann aßen und tranken sie, er und die Leute, die bei ihm waren, und blieben über Nacht da. Am andern Morgen aber, als sie aufgestanden waren, sagte er: »Laßt mich nun zu meinem Herrn ziehen!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 55, 'Da erwiderten ihm ihr Bruder und ihre Mutter: »Laß doch das Mädchen noch einige Zeit oder (wenigstens) zehn Tage bei uns bleiben, dann magst du aufbrechen.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 56, 'Doch er entgegnete ihnen: »Haltet mich nicht auf! Da Gott der HERR Glück zu meiner Reise gegeben hat, so laßt mich nun ziehen, damit ich zu meinem Herrn zurückkehre.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 57, 'Da sagten sie: »Wir wollen das Mädchen rufen und sie selbst entscheiden lassen.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 58, 'So riefen sie denn Rebekka und fragten sie: »Willst du mit diesem Manne ziehen?« Sie antwortete: »Ja, ich will mit ihm ziehen.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 59, 'Da ließen sie ihre Schwester Rebekka samt ihrer Amme und ebenso den Knecht Abrahams samt seinen Leuten ziehen');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 60, 'und segneten Rebekka mit den Worten: »Du, unsere Schwester, werde die Mutter von tausendmal Tausenden, und deine Nachkommen mögen die Tore ihrer Feinde besetzen!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 61, 'So machte sich denn Rebekka mit ihren Dienerinnen auf den Weg; sie setzten sich auf die Kamele und zogen hinter dem Manne her: der Knecht hatte Rebekka übernommen und zog von dannen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 62, 'Isaak aber war gerade auf der Heimkehr von einem Gang nach dem ›Brunnen des Lebendigen, der mich sieht‹; er wohnte nämlich im Südgau');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 63, 'und war gegen Abend aufs Feld hinausgegangen, um mit seinen Gedanken allein zu sein. Als er nun aufblickte, sah er auf einmal Kamele daherkommen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 64, 'Als nun auch Rebekka ihre Augen aufschlug und den Isaak erblickte, ließ sie sich rasch vom Kamele herab');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 65, 'und fragte den Knecht: »Wer ist der Mann dort, der uns auf dem Felde entgegenkommt?« Der Knecht antwortete: »Das ist mein Herr!« Da nahm sie den Schleier und verhüllte sich.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 66, 'Der Knecht erzählte dann dem Isaak alles, wie es ihm ergangen war.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 67, 'Isaak aber führte Rebekka in das Zelt seiner (verstorbenen) Mutter Sara und nahm sie auf; sie wurde seine Frau, und er gewann sie lieb. So tröstete sich Isaak nach dem Hingang seiner Mutter.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 1, 'Abraham aber nahm nochmals eine Frau namens Ketura;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 2, 'die gebar ihm Simran und Joksan, Medan und Midian, Jisbak und Suah.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 3, 'Joksan wurde dann der Vater Sebas und Dedans; und die Söhne Dedans waren die Assuriter und Letusiter und die Leummiter.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 4, 'Die Söhne Midians waren Epha und Epher, Henoch, Abida und Eldaba. Alle diese sind Nachkommen der Ketura.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 5, 'Abraham aber übergab seinen gesamten Besitz dem Isaak;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 6, 'dagegen den Söhnen, die er von den Nebenweibern hatte, gab er nur Geschenke und ließ sie noch bei seinen Lebzeiten von seinem Sohn Isaak hinweg ostwärts in das Ostland ziehen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 7, 'Dies aber ist die Zeit der Lebensjahre, die Abraham gelebt hat: 175 Jahre;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 8, 'da verschied und starb er in gesegnetem Alter, hochbetagt und lebenssatt, und wurde zu seinen Stammesgenossen versammelt.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 9, 'Seine Söhne Isaak und Ismael begruben ihn in der Höhle der Machpela auf dem Felde des Hethiters Ephron, des Sohnes Zohars, das östlich von Mamre lag,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 10, 'auf dem Felde, das Abraham von den Hethitern käuflich erworben hatte; dort sind Abraham und seine Frau Sara begraben worden.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 11, 'Nach Abrahams Tode aber segnete Gott dessen Sohn Isaak; dieser wohnte bei dem ›Brunnen des Lebendigen, der mich sieht‹.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 12, 'Dies ist der Stammbaum Ismaels, des Sohnes Abrahams, den die Ägypterin Hagar, die Leibmagd Saras, dem Abraham geboren hat;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 13, 'dies sind die Namen der Söhne Ismaels nach ihrer Geburtsfolge: Der erstgeborene Sohn Ismaels war Nebajoth, sodann Kedar, Abdeel und Mibsam,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 14, 'Misma, Duma und Massa,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 15, 'Hadad und Thema, Jetur, Naphis und Kedma.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 16, 'Dies waren die Söhne Ismaels und dies ihre Namen nach ihren Niederlassungen und ihren Zeltlagern; zwölf Fürsten entsprechend ihren Völkerschaften.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 17, 'Und dies war die Lebensdauer Ismaels: 137 Jahre; da verschied er und starb und wurde zu seinen Stammesgenossen versammelt.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 18, 'Sie hatten aber ihre Wohnsitze von Hawila an bis nach Sur, das östlich von Ägypten liegt, in der Richtung nach Assyrien hin: er hatte sich ostwärts von allen seinen Brüdern niedergelassen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 19, 'Dies ist der Stammbaum Isaaks, des Sohnes Abrahams: Abraham war der Vater Isaaks;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 20, 'und Isaak war vierzig Jahre alt, als er Rebekka, die Tochter des Aramäers Bethuel aus Nord-Mesopotamien, die Schwester des Aramäers Laban, zur Frau nahm.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 21, 'Und Isaak betete zum HERRN für seine Frau, denn sie hatte keine Kinder; da ließ der HERR sich von ihm erbitten, so daß seine Frau Rebekka guter Hoffnung wurde.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 22, 'Als aber die beiden Kinder sich in ihrem Schoße stießen, sagte sie: »Wenn es so steht, wozu bin ich da in diesen Zustand gekommen?« Und sie ging hin, um den HERRN zu befragen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 23, 'Da antwortete ihr der HERR: »Zwei Völker sind in deinem Mutterschoße, und zwei Volksstämme werden sich von deinem Leibe ausscheiden; der eine Stamm wird stärker sein als der andere, und der Ältere wird dem Jüngeren dienen.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 24, 'Als nun die Zeit ihrer Niederkunft da war, stellte es sich wirklich heraus, daß Zwillinge in ihrem Leibe waren.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 25, 'Der erste, der zum Vorschein kam, war rotbraun, rauh am ganzen Leibe wie ein haariger Mantel; darum nannte man ihn Esau.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 26, 'Hierauf kam sein Bruder zum Vorschein, der mit seiner Hand die Ferse Esaus gefaßt hielt; darum nannte man ihn Jakob. Isaak aber war bei ihrer Geburt sechzig Jahre alt.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 27, 'Als nun die Knaben heranwuchsen, wurde Esau ein tüchtiger Jäger, ein Mann des freien Feldes; Jakob dagegen war ein stiller Mann, der in den Zelten blieb.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 28, 'Isaak hatte den Esau lieber, weil er gern Wildbret aß; Rebekka aber hatte Jakob lieber.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 29, 'Nun hatte Jakob eines Tages ein Gericht gekocht, als Esau ganz erschöpft vom Felde heimkam.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 30, 'Da sagte Esau zu Jakob: »Laß mich doch schnell essen von dem Roten, dem roten Gericht da, denn ich bin ganz erschöpft!« Darum gab man ihm den Namen Edom.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 31, 'Aber Jakob antwortete: »Verkaufe mir zuvor dein Erstgeburtsrecht!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 32, 'Da erwiderte Esau: »Ach, ich muß ja doch (bald) sterben: wozu nützt mir da das Erstgeburtsrecht?«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 33, 'Jakob aber sagte: »Schwöre mir zuvor!« Da schwur er ihm und verkaufte so dem Jakob sein Erstgeburtsrecht.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 34, 'Hierauf gab Jakob dem Esau Brot und von dem Linsengericht. Als er dann gegessen und getrunken hatte, stand er auf und ging seines Weges. So gab Esau sein Erstgeburtsrecht geringschätzig preis.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 1, 'Es kam aber eine Hungersnot über das Land, wie schon früher einmal eine zur Zeit Abrahams geherrscht hatte; darum begab sich Isaak nach Gerar zu dem Philisterkönig Abimelech.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 2, 'Denn der HERR war ihm erschienen und hatte zu ihm gesagt: »Ziehe nicht nach Ägypten hinab, sondern nimm deinen Wohnsitz in dem Lande, das ich dir angeben werde!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 3, 'Bleibe als Fremdling in diesem Lande wohnen; ich will mit dir sein und dich segnen; denn dir und deinen Nachkommen will ich alle diese Länder geben und so den Eid erfüllen, den ich deinem Vater Abraham geschworen habe:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 4, 'ich will deine Nachkommen so zahlreich werden lassen wie die Sterne am Himmel und will deinen Nachkommen alle diese Länder geben; und in deiner Nachkommenschaft sollen alle Völker der Erde gesegnet werden,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 5, 'zum Lohn dafür, daß Abraham meinen Weisungen gehorsam gewesen ist und meine Anordnungen beobachtet hat, meine Gebote, meine Satzungen und meine Gesetze.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 6, 'So blieb denn Isaak in Gerar wohnen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 7, 'Als nun die Bewohner des Ortes sich nach seiner Frau erkundigten, sagte er: »Sie ist meine Schwester«; er scheute sich nämlich zu sagen: »Sie ist meine Frau«; »denn«, dachte er, »es könnten sonst die Leute des Ortes mich um Rebekkas willen ums Leben bringen; sie ist ja von großer Schönheit«.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 8, 'Als er sich nun längere Zeit dort aufgehalten hatte, schaute der Philisterkönig Abimelech einmal zum Fenster hinaus und sah, wie Isaak seine Frau Rebekka herzte.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 9, 'Da ließ Abimelech den Isaak rufen und sagte: »Sie ist ja doch deine Frau! Wie hast du sie da für deine Schwester ausgeben können?« Isaak antwortete ihm: »Ja, ich dachte, ich müßte sonst ihretwegen sterben.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 10, 'Da erwiderte Abimelech: »Was hast du uns da angetan! Wie leicht hätte es geschehen können, daß einer aus dem Volke hier deiner Frau Gewalt angetan hätte! Dann würdest du eine Verschuldung über uns gebracht haben.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 11, 'Hierauf gebot Abimelech dem ganzen Volke: »Wer sich an diesem Manne oder an seiner Frau vergreift, soll unfehlbar mit dem Tode bestraft werden!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 12, 'Isaak säte dann in jenem Lande und erntete in jenem Jahre das Hundertfache; denn der HERR segnete ihn.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 13, 'So wurde er denn ein reicher Mann und wurde immer reicher, bis er über die Maßen reich war;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 14, 'denn er besaß Herden von Kleinvieh und Herden von Rindern und ein zahlreiches Gesinde, so daß die Philister neidisch auf ihn wurden.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 15, 'Daher verschütteten die Philister alle Brunnen, welche die Knechte seines Vaters einst bei Lebzeiten seines Vaters Abraham gegraben hatten, und füllten sie mit Schutt an.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 16, 'Da sagte Abimelech zu Isaak: »Verlaß unser Land, denn du bist uns zu stark geworden.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 17, 'Da zog Isaak von dort weg, schlug sein Lager im Tale von Gerar auf und nahm dort seinen Wohnsitz.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 18, 'Hierauf ließ Isaak die Wasserbrunnen, welche man bei Lebzeiten seines Vaters Abraham gegraben und die die Philister nach dem Tode Abrahams verschüttet hatten, wieder aufgraben und legte ihnen dieselben Namen bei, die sein Vater ihnen gegeben hatte.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 19, 'Auch gruben die Leute Isaaks im Talgrunde nach und fanden dort einen Brunnen mit Quellwasser.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 20, 'Aber die Hirten von Gerar fingen mit den Hirten Isaaks Streit an, indem sie behaupteten, das Wasser gehöre ihnen. Da nannte er den Brunnen ›Zankbrunnen‹, weil sie sich dort mit ihm gezankt hatten.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 21, 'Dann gruben sie einen andern Brunnen, gerieten aber auch über diesen in Streit; daher nannte er ihn ›Anfeindung‹.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 22, 'Darauf zog er von dort weiter und grub wieder einen Brunnen, über den dann kein Streit mehr entstand; daher nannte er ihn ›Freier Raum‹, indem er sagte: »Jetzt hat der HERR uns freien Raum geschafft, so daß wir uns im Lande ausbreiten können.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 23, 'Von dort zog er dann nach Beerseba hinauf.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 24, 'Da erschien ihm der HERR in jener Nacht und sprach: »Ich bin der Gott deines Vaters Abraham. Fürchte dich nicht, denn ich bin mit dir; ich will dich segnen und deine Nachkommenschaft zahlreich werden lassen um meines Knechtes Abraham willen.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 25, 'Da baute er dort einen Altar, rief den Namen des HERRN an und schlug dort sein Zelt auf; hierauf gruben die Knechte Isaaks dort nach einem Brunnen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 26, 'Da kam Abimelech mit seinem Freunde Ahussath und seinem Heerführer Pichol aus Gerar zu ihm.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 27, 'Isaak fragte sie: »Warum kommt ihr zu mir, da ihr doch feindlich gegen mich gesinnt seid und mich aus eurem Lande vertrieben habt?«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 28, 'Da antworteten sie: »Wir haben klar erkannt, daß der HERR mit dir ist; darum haben wir gedacht, es solle doch ein eidliches Abkommen zwischen uns beiden, zwischen uns und dir, zustande kommen, und wir wollen einen Vertrag mit dir schließen,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 29, 'daß du uns nichts zuleide tun willst, wie auch wir dir keinen Schaden zugefügt, sondern dir nur Gutes erwiesen und dich in Frieden haben ziehen lassen: du bist nun einmal der Gesegnete des HERRN!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 30, 'Da richtete er ihnen ein Gastmahl aus, und sie aßen und tranken.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 31, 'Am andern Morgen in der Frühe aber leisteten sie einander den Schwur; dann ließ Isaak sie ziehen, und sie schieden als Freunde von ihm.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 32, 'An demselben Tage kamen dann die Knechte Isaaks und berichteten ihm von dem Brunnen, den sie gegraben hatten, mit den Worten: »Wir haben Wasser gefunden!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 33, 'Da nannte er ihn ›Sibea‹ (Sebua = Schwur, Eidvertrag). Daher heißt die Stadt dort ›Beerseba‹ bis auf den heutigen Tag.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 34, 'Als nun Esau vierzig Jahre alt war, heiratete er Judith, die Tochter des Hethiters Beeri, und Basmath, die Tochter des Hethiters Elon:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 35, 'die waren ein Herzenskummer für Isaak und Rebekka.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 1, 'Als aber Isaak alt geworden und sein Augenlicht erloschen war, so daß er nicht mehr sehen konnte, berief er seinen älteren Sohn Esau und sagte zu ihm: »Mein Sohn!« Er antwortete ihm: »Hier bin ich!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 2, 'Jener fuhr fort: »Du siehst, ich bin alt geworden und weiß nicht, wie bald ich sterben werde.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 3, 'So nimm nun doch deine Jagdgeräte, deinen Köcher und Bogen, und gehe aufs Feld hinaus und erjage ein Stück Wild für mich;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 4, 'dann bereite mir ein schmackhaftes Gericht, wie ich es liebe, und bringe es mir herein, damit ich esse und dich dann segne, bevor ich sterbe.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 5, 'Rebekka hatte aber zugehört, als Isaak so zu seinem Sohne Esau redete. Während nun Esau aufs Feld hinausging, um ein Stück Wild zu erjagen und heimzubringen,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 6, 'sagte Rebekka zu ihrem Sohne Jakob: »Ich habe soeben gehört, wie dein Vater mit deinem Bruder Esau geredet hat und zu ihm sagte:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 7, '›Bringe mir doch ein Stück Wild und bereite mir ein schmackhaftes Gericht, damit ich esse und dich dann vor dem Angesicht des HERRN segne, bevor ich sterbe.‹');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 8, 'So höre nun, mein Sohn, auf den Rat, den ich dir jetzt gebe!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 9, 'Gehe hin zur Herde und hole mir von dort zwei gute Ziegenböckchen; die will ich dann für deinen Vater zu einem schmackhaften Gericht zubereiten, wie er es liebt;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 10, 'das bringst du dann deinem Vater hinein, damit er es ißt und dich dann noch vor seinem Tode segnet.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 11, 'Da erwiderte Jakob seiner Mutter Rebekka: »Ja, aber mein Bruder Esau ist stark behaart, während ich eine glatte Haut habe.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 12, 'Vielleicht wird mein Vater mich betasten: dann würde ich als Betrüger vor ihm dastehen und einen Fluch statt des Segens über mich bringen.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 13, 'Aber seine Mutter antwortete ihm: »Den Fluch, der dich treffen könnte, nehme ich auf mich, mein Sohn! Folge du nur meinem Rat: geh hin und hole mir die Böckchen!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 14, 'Da ging er hin, holte die Böckchen und brachte sie seiner Mutter; und diese bereitete davon ein schmackhaftes Gericht, wie sein Vater es liebte.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 15, 'Hierauf holte Rebekka die Festtagskleider ihres älteren Sohnes Esau, die sich bei ihr in der Wohnung befanden, und gab sie ihrem jüngeren Sohne Jakob zum Anziehen;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 16, 'die Felle der Ziegenböckchen aber legte sie ihm um die Arme und um die glatten Stellen seines Halses;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 17, 'dann gab sie das schmackhafte Essen nebst dem Brot, das sie gebacken hatte, ihrem Sohne Jakob in die Hand.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 18, 'So ging er denn zu seinem Vater hinein und sagte: »Mein Vater!« Dieser antwortete: »Hier bin ich! Wer bist du, mein Sohn?«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 19, 'Jakob erwiderte seinem Vater: »Ich bin Esau, dein erstgeborener Sohn; ich habe getan, wie du mir aufgetragen hast. Richte dich nun auf, setze dich und iß von meinem Wildbret, damit du mich dann segnest.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 20, 'Da fragte Isaak seinen Sohn: »Wie hast du denn so schnell etwas gefunden, mein Sohn?« Er antwortete: »Ja, der HERR, dein Gott, hat es mir entgegenlaufen lassen.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 21, 'Da sagte Isaak zu Jakob: »Tritt doch näher heran, mein Sohn, damit ich dich betaste, ob du wirklich mein Sohn Esau bist oder nicht!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 22, 'Da trat Jakob nahe an seinen Vater Isaak heran, und als dieser ihn betastet hatte, sagte er: »Die Stimme ist Jakobs Stimme, aber die Arme sind Esaus Arme«;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 23, 'und er erkannte ihn nicht, weil seine Arme behaart waren wie die Arme seines Bruders Esau; so segnete er ihn denn.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 24, 'Er fragte nämlich: »Du bist doch wirklich mein Sohn Esau?« Jener antwortete: »Ja, ich bin’s.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 25, 'Da fuhr er fort: »So reiche es mir her, damit ich von dem Wildbret meines Sohnes esse und ich dich dann segne.« Da reichte er es ihm hin, und er aß; er brachte ihm auch Wein, den er trank.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 26, 'Hierauf sagte sein Vater Isaak zu ihm: »Tritt nun nahe heran, mein Sohn, und küsse mich!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 27, 'Da trat er heran und küßte ihn; dabei roch jener den Geruch seiner Kleider und segnete ihn mit den Worten: »Ja, der Geruch meines Sohnes ist wie der Geruch eines Feldes, das der HERR gesegnet hat.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 28, 'So gebe Gott dir denn vom Tau des Himmels und von den Fruchtgefilden der Erde Überfluß sowohl an Korn als auch an Wein!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 29, 'Völker sollen dir dienen und Völkerschaften sich vor dir beugen! Sei ein Herr über deine Brüder, und bücken sollen sich vor dir die Söhne deiner Mutter! Wer dir flucht, der sei verflucht, und wer dich segnet, der soll gesegnet sein!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 30, 'Als nun Isaak mit der Segnung Jakobs eben zu Ende war und Jakob kaum von seinem Vater Isaak hinausgegangen war, da kam sein Bruder Esau von seiner Jagd zurück.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 31, 'Er bereitete gleichfalls ein schmackhaftes Gericht, brachte es seinem Vater hinein und sagte zu ihm: »Richte dich auf, mein Vater, und iß vom Wildbret deines Sohnes, damit du mich dann segnest!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 32, 'Da fragte ihn sein Vater Isaak: »Wer bist du?« Er antwortete: »Ich bin dein erstgeborener Sohn Esau.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 33, 'Da erbebte Isaak über alle Maßen und sagte: »Wer ist denn der gewesen, der ein Stück Wild erjagt und es mir gebracht hat? Ich habe von allem gegessen, ehe du kamst, und habe ihn gesegnet; so wird er nun auch gesegnet bleiben.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 34, 'Sobald Esau diese Worte seines Vaters vernahm, erhob er ein überaus lautes und klägliches Geschrei und bat seinen Vater: »Segne auch mich, mein Vater!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 35, 'Isaak aber antwortete: »Dein Bruder ist mit List gekommen und hat den dir gebührenden Segen vorweggenommen.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 36, 'Da sagte Esau: »Ja, er heißt mit Recht Jakob; denn er hat mich nun schon zweimal überlistet: mein Erstgeburtsrecht hat er mir genommen, und jetzt hat er mich auch um meinen Segen gebracht!« Dann fragte er: »Hast du denn für mich keinen Segen zurückbehalten?«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 37, 'Da antwortete Isaak dem Esau mit den Worten: »Ich habe ihn nun einmal zum Herrn über dich gesetzt und alle seine Brüder ihm zu Knechten gegeben; mit Korn und Wein habe ich ihn versorgt! Was könnte ich also nun noch für dich tun, mein Sohn?«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 38, 'Da sagte Esau zu seinem Vater: »Hast du denn nur den einen Segen, mein Vater? Segne auch mich, mein Vater!« Und Esau begann laut zu weinen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 39, 'Da antwortete ihm sein Vater Isaak mit den Worten: »Ach, ohne fetten Erdboden wird dein Wohnsitz sein und ohne Tau vom Himmel droben!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 40, 'Mittels deines Schwertes mußt du leben, und deinem Bruder sollst du dienstbar sein. Wenn du aber rüttelst, wirst du sein Joch dir vom Nacken abschütteln.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 41, 'So wurde denn Esau dem Jakob feind wegen des Segens, den sein Vater ihm erteilt hatte; und Esau dachte bei sich: »Bald werden die Tage der Trauer um meinen Vater kommen, dann will ich meinen Bruder Jakob totschlagen!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 42, 'Als nun der Rebekka diese Äußerungen ihres älteren Sohnes Esau hinterbracht wurden, ließ sie ihren jüngeren Sohn Jakob rufen und sagte zu ihm: »Wisse: dein Bruder Esau sinnt auf Rache gegen dich und will dich totschlagen!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 43, 'Darum höre nun, was ich dir rate, mein Sohn! Mache dich auf, fliehe zu meinem Bruder Laban nach Haran');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 44, 'und bleibe einige Zeit bei ihm, bis der Groll deines Bruders sich gelegt hat!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 45, 'Wenn dann sein Zorn gegen dich geschwunden ist und er vergessen hat, was du ihm angetan hast, dann will ich hinsenden und dich von dort zurückholen lassen. Warum soll ich euch beide an einem Tage verlieren?«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 46, 'Hierauf sagte Rebekka zu Isaak: »Das Leben wird mir verleidet durch diese Hethiterinnen! Wenn auch Jakob sich solch eine Hethiterin zur Frau nähme, eine von den Töchtern des Landes, was hätte ich da noch vom Leben?«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 28, 1, 'Da ließ Isaak den Jakob rufen, segnete ihn und gebot ihm: »Du darfst dir keine Frau aus den Töchtern der Kanaanäer nehmen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 28, 2, 'Mache dich auf, gehe nach Nord-Mesopotamien zum Hause Bethuels, des Vaters deiner Mutter, und hole dir von dort eine Frau, eine von den Töchtern Labans, des Bruders deiner Mutter!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 28, 3, 'Der allmächtige Gott aber segne dich, er mache dich fruchtbar und lasse dich zahlreich werden, so daß du zu einem Haufen von Völkern wirst!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 28, 4, 'Und er gewähre dir den Segen Abrahams, dir und deinen Nachkommen mit dir, damit du das Land, in dem du bis jetzt als Fremdling gewohnt hast und das Gott dem Abraham verliehen hat, in Besitz nimmst.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 28, 5, 'So ließ Isaak den Jakob ziehen, und dieser machte sich auf den Weg nach Nord-Mesopotamien zu Laban, dem Sohne des Aramäers Bethuel, dem Bruder Rebekkas, der Mutter Jakobs und Esaus.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 28, 6, 'Als nun Esau sah, daß Isaak den Jakob gesegnet und ihn nach Nord-Mesopotamien hatte ziehen lassen, damit er sich von dort eine Frau hole, und daß er ihn gesegnet und ihm die Weisung gegeben hatte, keine Frau von den Töchtern der Kanaanäer zu nehmen,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 28, 7, 'und daß Jakob seinem Vater und seiner Mutter gehorsam gewesen und nach Nord-Mesopotamien gezogen war:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 28, 8, 'da merkte Esau, daß die Töchter der Kanaanäer seinem Vater mißfielen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 28, 9, 'Darum begab er sich zu Ismael und nahm zu seinen Frauen noch eine andere Frau hinzu, nämlich Mahalath, die Tochter Ismaels, des Sohnes Abrahams, die Schwester Nebajoths.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 28, 10, 'Als Jakob aber von Beerseba aufgebrochen war und sich auf die Wanderschaft nach Haran begeben hatte,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 28, 11, 'gelangte er an die (heilige) Stätte und blieb daselbst über Nacht; denn die Sonne war schon untergegangen. Er nahm also einen von den Steinen, die dort lagen, machte ihn zu seinem Kopflager und legte sich daselbst schlafen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 28, 12, 'Da hatte er einen Traum: er sah eine Leiter, die auf der Erde stand und mit ihrer Spitze bis an den Himmel reichte, und die Engel Gottes stiegen auf ihr hinauf und herab.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 28, 13, 'Plötzlich stand dann der HERR auf ihr und sagte: »Ich bin der HERR, der Gott deines Vaters Abraham und der Gott Isaaks; das Land, auf dem du liegst, will ich dir und deinen Nachkommen geben;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 28, 14, 'und deine Nachkommen sollen so zahlreich werden wie der Staub der Erde; und du sollst dich nach Westen und Osten, nach Norden und Süden hin ausbreiten, und in dir und in deinen Nachkommen sollen alle Geschlechter der Erde gesegnet werden.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 28, 15, 'Und siehe, ich will mit dir sein und dich überall behüten, wohin du gehst, und will dich auch in dieses Land zurückbringen; denn ich will dich nicht verlassen, bis ich das ausgeführt habe, was ich dir verheißen habe.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 28, 16, 'Da erwachte Jakob aus seinem Schlaf und sagte: »Wahrlich, der HERR ist an dieser Stätte gegenwärtig, ohne daß ich es wußte!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 28, 17, 'Da fürchtete er sich und rief aus: »Wie schaurig ist diese Stätte! Ja, hier ist das Haus Gottes und hier die Pforte des Himmels!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 28, 18, 'Am Morgen aber in aller Frühe stand Jakob auf, nahm den Stein, den er sich zum Lager für sein Haupt gemacht hatte, richtete ihn als Denkstein auf und goß Öl oben darauf.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 28, 19, 'Er gab dann jener Stätte den Namen ›Bethel‹ – vordem hatte die Ortschaft ›Lus‹ geheißen –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 28, 20, 'und sprach hierauf folgendes Gelübde aus: »Wenn Gott mit mir ist und mich auf dem Wege, den ich jetzt gehen muß, behütet und mir Brot zur Nahrung und Kleidung zum Anziehen gibt');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 28, 21, 'und ich glücklich in mein Vaterhaus zurückkehre, so soll der HERR mein Gott sein,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 28, 22, 'und dieser Stein, den ich als Denkstein aufgerichtet habe, soll zu einem Gotteshause werden, und von allem, was du mir geben wirst, will ich dir getreulich den Zehnten entrichten!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 1, 'Hierauf setzte Jakob seine Wanderung fort und gelangte in das Land, das gegen Osten lag.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 2, 'Als er sich dort umsah, gewahrte er auf dem Felde einen Brunnen, an dem gerade drei Herden Kleinvieh lagerten; denn aus diesem Brunnen pflegte man die Herden zu tränken; über der Öffnung des Brunnens aber lag ein großer Stein.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 3, 'Diesen wälzte man erst dann, wenn alle Herden dort zusammengetrieben waren, von der Brunnenöffnung ab und tränkte das Kleinvieh; darauf legte man den Stein wieder zurück an seinen Platz über der Öffnung des Brunnens.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 4, 'Da sagte Jakob zu den Leuten: »Meine Brüder, woher seid ihr?« Sie antworteten: »Wir sind aus Haran.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 5, 'Hierauf fragte er sie: »Kennt ihr Laban, den Sohn Nahors?« Sie antworteten: »Ja, den kennen wir.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 6, 'Da fragte er sie: »Geht es ihm gut?« Sie erwiderten: »Ja; und da kommt gerade seine Tochter Rahel mit dem Kleinvieh!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 7, 'Da sagte er: »Es ist ja noch hoch am Tage, und noch ist’s nicht die Zeit, das Vieh zusammenzutreiben; tränkt doch das Kleinvieh und laßt es dann wieder weiden!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 8, 'Sie antworteten: »Das können wir nicht, bis alle Herden beisammen sind; dann erst wälzt man den Stein von der Öffnung des Brunnens ab, und wir tränken das Kleinvieh.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 9, 'Während er noch mit ihnen redete, war Rahel mit dem Kleinvieh ihres Vaters herangekommen; denn sie war eine Hirtin.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 10, 'Sobald nun Jakob Rahel, die Tochter seines Oheims Laban, und das Kleinvieh seines Oheims Laban erblickt hatte, trat er hinzu, wälzte den Stein von der Brunnenöffnung ab und tränkte das Kleinvieh seines Oheims Laban.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 11, 'Dann küßte er Rahel, weinte laut');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 12, 'und teilte ihr mit, daß er ein Neffe ihres Vaters, und zwar ein Sohn Rebekkas, sei; da eilte sie weg und berichtete es ihrem Vater.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 13, 'Als nun Laban die Nachricht über Jakob, den Sohn seiner Schwester, vernahm, lief er ihm entgegen, umarmte und küßte ihn und führte ihn in sein Haus; da erzählte er dem Laban seine ganze Lebensgeschichte.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 14, 'Laban aber sagte zu ihm: »Fürwahr, du bist von meinem Fleisch und Bein.« Als Jakob nun einen Monat lang bei Laban geblieben war,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 15, 'sagte dieser zu ihm: »Du bist doch mein Verwandter: solltest du da umsonst für mich arbeiten? Laß mich wissen, was dein Lohn sein soll!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 16, 'Nun hatte Laban zwei Töchter: die ältere hieß Lea, die jüngere Rahel;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 17, 'Lea hatte matte Augen, während Rahel schön von Gestalt und schön von Angesicht war.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 18, 'Daher hatte Jakob die Rahel liebgewonnen und sagte: »Ich will dir sieben Jahre lang um deine jüngere Tochter Rahel dienen.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 19, 'Laban antwortete: »Es ist besser, ich gebe sie dir als einem fremden Manne: bleibe also bei mir!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 20, 'So diente denn Jakob um Rahel sieben Jahre, und diese kamen ihm wie wenige Tage vor: so lieb hatte er Rahel.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 21, 'Hierauf sagte Jakob zu Laban: »Meine Zeit ist abgelaufen: gib mir nun meine Frau, damit ich mich mit ihr verheirate.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 22, 'Da lud Laban alle Einwohner des Ortes ein und veranstaltete ein Festmahl;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 23, 'am Abend aber nahm er seine Tochter Lea und brachte sie zu ihm hinein, und er wohnte ihr bei;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 24, 'und Laban gab seiner Tochter Lea seine Magd Silpa zur Leibmagd. Am andern Morgen aber stellte es sich heraus, daß es Lea war.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 25, 'Als er nun zu Laban sagte: »Was hast du mir da angetan! Habe ich nicht um Rahel bei dir gedient? Warum hast du mich betrogen?«,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 26, 'antwortete Laban: »Hierzulande ist es nicht Sitte, die jüngere Tochter vor der älteren wegzugeben.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 27, 'Bringe die Brautwoche mit dieser zu Ende, dann soll dir auch die andere gegeben werden für den Dienst, den du mir noch weitere sieben Jahre leisten mußt.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 28, 'Jakob willigte ein und hielt die Brautwoche mit Lea aus; dann gab Laban ihm auch seine Tochter Rahel zur Frau;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 29, 'und Laban gab seiner Tochter Rahel seine Magd Bilha zur Leibmagd.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 30, 'Jakob ging nun auch zu Rahel ein, hatte aber Rahel lieber als Lea; er blieb dann noch weitere sieben Jahre bei Laban im Dienst.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 31, 'Als nun der HERR sah, daß Lea ungeliebt war, machte er sie fruchtbar, während Rahel kinderlos blieb.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 32, 'Lea wurde also guter Hoffnung und gebar einen Sohn, den sie Ruben nannte; »denn«, sagte sie, »der HERR hat mein Elend angesehen; ja, nun wird mein Mann mich liebgewinnen«.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 33, 'Hierauf wurde sie wieder guter Hoffnung, und als sie einen Sohn geboren hatte, sagte sie: »Weil der HERR gehört hat, daß ich ungeliebt bin, hat er mir auch diesen Sohn gegeben«; darum nannte sie ihn Simeon.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 34, 'Als sie dann wieder guter Hoffnung geworden war und einen Sohn gebar, sagte sie: »Nun endlich wird mein Mann mir anhangen, denn ich habe ihm drei Söhne geboren«; darum nannte sie ihn Levi.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 35, 'Hierauf wurde sie nochmals guter Hoffnung und gebar einen Sohn; da sagte sie: »Diesmal will ich den HERRN preisen!« Darum nannte sie ihn Juda. Danach bekam sie kein Kind mehr.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 1, 'Als nun Rahel sah, daß sie dem Jakob keine Kinder gebar, wurde sie auf ihre Schwester neidisch und sagte zu Jakob: »Schaffe mir Kinder, oder ich sterbe!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 2, 'Da geriet Jakob in Zorn gegen Rahel und sagte: »Stehe ich etwa an Gottes Statt, der dir Kindersegen versagt hat?«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 3, 'Da erwiderte sie: »Hier hast du meine Leibmagd Bilha; gehe zu ihr ein, damit sie auf meinen Knien gebiert und auch ich durch sie zu Kindern komme!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 4, 'So gab sie ihm ihre Leibmagd Bilha zum (Neben-) Weib, und Jakob ging zu ihr ein;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 5, 'da wurde Bilha guter Hoffnung und gebar dem Jakob einen Sohn.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 6, 'Rahel aber sagte: »Gott hat mich mein Recht finden lassen und auch meine Bitte erhört und mir einen Sohn geschenkt!« Darum gab sie ihm den Namen Dan.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 7, 'Hierauf wurde Bilha, die Leibmagd Rahels, wieder guter Hoffnung und gebar dem Jakob einen zweiten Sohn.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 8, 'Da sagte Rahel: »Gotteskämpfe habe ich mit meiner Schwester gekämpft und habe auch gesiegt!« Darum nannte sie ihn Naphthali.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 9, 'Als nun Lea sah, daß sie nicht mehr Mutter wurde, nahm sie ihre Leibmagd Silpa und gab sie dem Jakob zum (Neben-) Weibe.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 10, 'So gebar denn Silpa, die Leibmagd Leas, dem Jakob einen Sohn.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 11, 'Da sagte Lea: »Glückauf!« und gab ihm den Namen Gad.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 12, 'Hierauf gebar Silpa, die Leibmagd Leas, dem Jakob noch einen zweiten Sohn.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 13, 'Da sagte Lea: »Ich Glückliche! Ja, glücklich werden mich die Töchter des Volkes preisen!« Darum nannte sie ihn Asser.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 14, 'Als nun Ruben einmal in den Tagen der Weizenernte ausging, fand er Liebesäpfel auf dem Felde und brachte sie seiner Mutter Lea. Da sagte Rahel zu Lea: »Gib mir doch einige von den Liebesäpfeln deines Sohnes!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 15, 'Aber sie antwortete ihr: »Ist es nicht genug, daß du mir meinen Mann genommen hast? Willst du mir nun auch noch die Liebesäpfel meines Sohnes nehmen?« Darauf antwortete Rahel: »So mag Jakob denn diese Nacht bei dir verbringen zum Entgelt für die Liebesäpfel deines Sohnes!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 16, 'Als Jakob nun am Abend vom Felde heimkam, ging Lea hinaus ihm entgegen und sagte: »Zu mir mußt du eingehen; denn ich habe dich um vollen Preis mit den Liebesäpfeln meines Sohnes erkauft!« So verbrachte er denn jene Nacht bei ihr;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 17, 'und Gott erhörte die Bitte der Lea, so daß sie guter Hoffnung wurde und dem Jakob einen fünften Sohn gebar.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 18, 'Da sagte Lea: »Gott hat mir meinen Lohn dafür gegeben, daß ich meine Leibmagd meinem Manne überlassen habe«; darum gab sie ihm den Namen Issaschar.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 19, 'Hierauf wurde Lea noch einmal guter Hoffnung und gebar dem Jakob einen sechsten Sohn.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 20, 'Da sagte Lea: »Gott hat mich mit einem schönen Geschenk bedacht: nun endlich wird mein Mann bei mir wohnen; denn ich habe ihm sechs Söhne geboren!« Darum nannte sie ihn Sebulon.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 21, 'Später gebar sie noch eine Tochter, die sie Dina nannte.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 22, 'Nun dachte Gott auch an Rahel: Gott erhörte sie und vergönnte ihr Mutterfreuden;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 23, 'sie wurde guter Hoffnung und gebar einen Sohn. Da sagte sie: »Gott hat meine Schmach hinweggenommen!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 24, 'Darum gab sie ihm den Namen Joseph, indem sie sagte: »Der HERR möge mir noch einen Sohn hinzufügen!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 25, 'Als nun Rahel den Joseph geboren hatte, sagte Jakob zu Laban: »Laß mich ziehen! Ich möchte in meine Heimat und in mein Vaterland zurückkehren.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 26, 'Gib mir meine Frauen und meine Kinder, um die ich dir gedient habe, damit ich hinziehen kann; du weißt ja selbst, welche Dienste ich dir geleistet habe.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 27, 'Da antwortete ihm Laban: »Erweise mir doch eine Liebe! Es ist mir klargeworden, daß der HERR mich um deinetwillen gesegnet hat.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 28, 'Dann fuhr er fort: »Bestimme nur den Lohn, den du von mir verlangst, so will ich ihn dir geben.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 29, 'Da antwortete er ihm: »Du weißt selbst, wie ich dir gedient habe und was aus deinem Viehbesitz unter meiner Hut geworden ist.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 30, 'Du besaßest ja vor meiner Ankunft nur wenig; aber nun hat er sich gewaltig vermehrt, und der HERR hat dich bei allem, was ich unternommen habe, gesegnet. Nun aber – wann soll auch ich für meine Familie sorgen?«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 31, 'Da fragte jener: »Was soll ich dir geben?« Jakob antwortete: »Du brauchst mir gar nichts zu geben! Wenn du nur auf folgenden Vorschlag von mir eingehst, so will ich dein Kleinvieh von neuem weiden und hüten:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 32, 'ich will heute durch dein sämtliches Kleinvieh hindurchgehen, indem ich daraus alle gesprenkelten und gefleckten Tiere und überdies jedes dunkelfarbige Stück unter den Schaflämmern und alle gefleckten und gesprenkelten Ziegen absondere; und nur solche Tiere sollen mein Lohn sein.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 33, 'Und darin soll an irgendeinem künftigen Tage meine Ehrlichkeit sich klar erweisen: Wenn du kommst, um dir meinen Lohn anzusehen, so soll jedes Stück, das unter den Ziegen nicht gesprenkelt oder gefleckt und unter den Schafen nicht dunkelfarbig ist, als von mir gestohlen gelten.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 34, 'Da sagte Laban: »Gut! Dein Vorschlag soll gelten!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 35, 'Er sonderte dann noch an demselben Tage die gestreiften und gefleckten Ziegenböcke und alle gesprenkelten und gefleckten Ziegen ab, jedes Stück, woran nur etwas Weißes war, und alles, was unter den Schafen dunkelfarbig war, und übergab diese Tiere der Hut seiner Söhne.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 36, 'Sodann setzte er einen Zwischenraum von drei Tagereisen zwischen sich und Jakob fest; Jakob aber blieb als Hirt bei dem übrigen Kleinvieh Labans.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 37, 'Nun holte sich Jakob frische Stäbe von Weißpappeln sowie von Mandelbäumen und Platanen und schälte an ihnen weiße Streifen heraus, indem er das Weiße an den Stäben bloßlegte;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 38, 'dann stellte er die Stäbe, die er geschält hatte, in die Wassertröge, in die Wassertränkrinnen, zu denen das Kleinvieh zum Trinken zu kommen pflegte, gerade vor die Tiere hin. Wenn dann die Tiere, die zur Tränke kamen, brünstig wurden');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 39, 'und sich vor den Stäben begatteten, so brachten sie gestreifte, gesprenkelte und gefleckte Junge zur Welt.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 40, 'Jakob sonderte dann die Lämmer ab und richtete die Blicke der Tiere auf das Gestreifte und alles Dunkelfarbige unter dem Kleinvieh Labans und legte (so) für sich besondere Herden an, die er nicht zu dem Kleinvieh Labans tat.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 41, 'Und sooft fortan das kräftige Kleinvieh brünstig wurde, stellte Jakob die Stäbe den Tieren vor die Augen in die Wassertröge, damit sie sich vor den Stäben begatteten;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 42, 'wenn dagegen die Tiere schwächlich waren, stellte er sie nicht hin; so kam es, daß die schwächlichen Tiere dem Laban, die kräftigen aber dem Jakob zuteil wurden.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 43, 'So wurde er ein außerordentlich reicher Mann, und er erwarb sich große Herden, auch Mägde und Knechte, Kamele und Esel.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 1, 'Da erhielt Jakob Kunde von den Äußerungen der Söhne Labans, die da sagten: »Jakob hat das ganze Hab und Gut unsers Vaters an sich gebracht und seinen ganzen jetzigen Reichtum aus dem Besitz unsers Vaters gewonnen.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 2, 'Zugleich merkte Jakob an Labans Gesichtsausdruck wohl, daß er gegen ihn nicht mehr so gesinnt war wie früher.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 3, 'Da sagte der HERR zu Jakob: »Kehre in das Land deiner Väter und zu deiner Verwandtschaft zurück; ich will mit dir sein!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 4, 'Da sandte Jakob hin, ließ Rahel und Lea auf das Feld zu seiner Herde rufen');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 5, 'und sagte zu ihnen: »Ich sehe es dem Gesicht eures Vaters an, daß er gegen mich nicht mehr so gesinnt ist wie früher, obgleich doch der Gott meines Vaters mit mir gewesen ist.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 6, 'Ihr selbst wißt ja, daß ich eurem Vater mit meiner ganzen Kraft gedient habe;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 7, 'doch euer Vater hat mich betrogen und mir den Lohn schon zehnmal abgeändert, Gott aber hat ihm nicht gestattet, mir Schaden zuzufügen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 8, 'Sooft er nämlich sagte: ›Die gesprenkelten Tiere sollen dein Lohn sein!‹, warf die ganze Herde gesprenkelte Lämmer, und sooft er sagte: ›Die gestreiften Tiere sollen dein Lohn sein!‹, warf die ganze Herde gestreifte Lämmer.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 9, 'So hat Gott eurem Vater den Viehbesitz genommen und ihn mir gegeben.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 10, 'In der Brunstzeit des Kleinviehs nämlich hob ich meine Augen auf und sah im Traume, wie die Böcke, welche das Kleinvieh belegten, gestreift, gesprenkelt und getüpfelt waren.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 11, 'Der Engel Gottes aber sagte im Traume zu mir: ›Jakob!‹ Ich antwortete: ›Hier bin ich!‹');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 12, 'Da sagte er: ›Hebe doch deine Augen auf und sieh: alle Böcke, die das Kleinvieh belegen, sind gestreift, gesprenkelt und getüpfelt! Denn ich habe alles gesehen, was Laban dir angetan hat.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 13, 'Ich bin der Gott von Bethel, wo du einen Denkstein gesalbt und wo du mir ein Gelübde getan hast. Mache dich jetzt auf, verlaß dieses Land und kehre in dein Heimatland zurück!‹«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 14, 'Da antworteten ihm Rahel und Lea mit den Worten: »Haben wir etwa noch ein Teil und Erbe im Hause unsers Vaters?');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 15, 'Haben wir ihm nicht als Fremde gegolten? Er hat uns ja verhandelt und den Erlös für uns längst vollständig verbraucht.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 16, 'Ja, der ganze Reichtum, den Gott unserm Vater entzogen hat, gehört uns und unsern Söhnen. Tu also nun alles, was Gott dir geboten hat!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 17, 'Da machte Jakob sich auf, setzte seine Kinder und seine Frauen auf die Kamele');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 18, 'und nahm sein sämtliches Vieh und all sein Hab und Gut mit, das er erworben hatte, das Vieh, das ihm gehörte, das er in Nord-Mesopotamien erworben hatte, um sich zu seinem Vater Isaak nach dem Lande Kanaan zu begeben.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 19, 'Während aber Laban hingegangen war, um seine Schafe zu scheren, entwandte Rahel das Bild des Hausgottes ihres Vaters;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 20, 'und auch Jakob täuschte den Aramäer Laban, insofern er ihm nichts davon mitteilte, daß er sich heimlich entfernen wollte.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 21, 'Er entfloh also mit allem, was ihm gehörte, und machte sich auf den Weg; er setzte über den Euphratstrom und schlug den Weg nach dem Gebirge Gilead ein.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 22, 'Erst am dritten Tage erfuhr Laban, daß Jakob entflohen war.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 23, 'Da nahm er seine Stammesgenossen mit sich, verfolgte ihn sieben Tagereisen weit und holte ihn am Gebirge Gilead ein.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 24, 'Aber Gott erschien dem Aramäer Laban nachts im Traum und sagte zu ihm: »Hüte dich wohl, mit Jakob anders als freundlich zu reden!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 25, 'Als nun Laban den Jakob eingeholt hatte – Jakob hatte aber sein Zelt auf dem Berge aufgeschlagen, und auch Laban lagerte sich mit seinen Stammesgenossen im Gebirge Gilead –,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 26, 'da sagte Laban zu Jakob: »Warum hast du es unternommen, mich zu täuschen, und hast meine Töchter wie Kriegsgefangene entführt?');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 27, 'Warum bist du heimlich entflohen und hast mich hintergangen und mir nichts davon mitgeteilt – ich hätte dir sonst mit Sang und Klang, mit Paukenschall und Saitenspiel das Geleit gegeben –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 28, 'und hast mir nicht einmal verstattet, meine Enkel und Töchter (zum Abschied) zu küssen? Ja, du hast töricht gehandelt!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 29, 'Es stände nun wohl in meiner Macht, dir übel mitzuspielen; aber der Gott deines Vaters hat gestern nacht zu mir gesagt: ›Hüte dich ja davor, mit Jakob anders als freundlich zu reden!‹');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 30, 'Nun gut, du bist von mir weggegangen, weil du so starke Sehnsucht nach dem Hause deines Vaters hattest; aber warum hast du mir meinen (Haus-) Gott gestohlen?«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 31, 'Da antwortete Jakob dem Laban: »(Ich bin geflohen) weil ich mich fürchtete; denn ich dachte, du würdest mir deine Töchter entreißen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 32, 'Bei wem du aber dein Götterbild findest, der soll nicht am Leben bleiben! Durchsuche im Beisein unserer Stammesgenossen alles, was ich bei mir habe, und nimm das an dich, was dir gehört!« Jakob wußte nämlich nicht, daß Rahel (das Götterbild) entwandt hatte.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 33, 'Da ging Laban in Jakobs Zelt und in Leas Zelt und in das Zelt der beiden Mägde, fand aber nichts. Aus dem Zelt der Lea ging er dann in das Zelt der Rahel.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 34, 'Diese hatte aber das Götterbild genommen und es in den Sattelkorb des Kamels gelegt und sich daraufgesetzt. Laban durchsuchte nun das ganze Zelt, fand aber nichts.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 35, 'Sie hatte nämlich zu ihrem Vater gesagt: »O Herr, sei nicht ungehalten darüber, daß ich vor dir nicht aufstehen kann! Ich bin eben unwohl nach der Frauen Weise.« So hatte er denn trotz seines Suchens das Götterbild nicht gefunden.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 36, 'Nunmehr geriet Jakob in Zorn und machte Laban laute Vorwürfe mit den Worten: »Was habe ich nun verbrochen, was verschuldet, daß du mich so hitzig verfolgt hast?');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 37, 'Du hast nun all meinen Hausrat durchstöbert: was hast du denn von deinem gesamten Hausrat gefunden? Lege es hierher vor meine und deine Stammesgenossen: sie sollen entscheiden, wer von uns beiden im Recht ist!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 38, 'Zwanzig Jahre bin ich jetzt bei dir gewesen: deine Mutterschafe und deine Ziegen haben nie fehlgeworfen, und von den Böcken deines Kleinviehs habe ich keinen gegessen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 39, 'Wenn ein Stück Vieh (von wilden Tieren) zerrissen war, habe ich es nicht zu dir bringen dürfen, nein, ich habe es ersetzen müssen: von mir hast du es gefordert, mochte es bei Tage oder in der Nacht geraubt sein.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 40, 'So ging es mir: bei Tage kam ich vor Hitze um und nachts vor Frost, und kein Schlaf kam in meine Augen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 41, 'Jetzt sind es zwanzig Jahre, daß ich dir in deinem Hause gedient habe: vierzehn Jahre um deine beiden Töchter und sechs Jahre bei deinem Kleinvieh; und zehnmal hast du mir den Lohn abgeändert.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 42, 'Wenn nicht der Gott meines Vaters, der Gott Abrahams, den auch Isaak verehrt, auf meiner Seite gestanden hätte, ja, dann hättest du mich jetzt mit leeren Händen ziehen lassen! Aber Gott hat mein Elend und die mühselige Arbeit meiner Hände gesehen und gestern nacht sein Urteil abgegeben!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 43, 'Da gab Laban dem Jakob zur Antwort: »Die Töchter sind meine Töchter, und die Kinder sind meine Kinder, das Vieh ist mein Vieh, und alles, was du hier siehst, gehört mir! Aber was könnte ich heute noch für diese meine Töchter tun oder für ihre Kinder, die sie geboren haben?');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 44, 'So komm denn, laß uns beide einen Vertrag miteinander schließen, der soll als Zeuge zwischen mir und dir dienen!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 45, 'Hierauf nahm Jakob einen Stein und richtete ihn als Denkstein auf;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 46, 'dann sagte er zu seinen Stammesgenossen: »Lest Steine zusammen!« Da holten sie Steine und machten einen Haufen davon; dann hielten sie dort auf dem Steinhaufen ein Mahl.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 47, 'Und Laban nannte ihn ›Jegar-Sahadutha‹, Jakob aber nannte ihn ›Galed‹.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 48, 'Darauf sagte Laban: »Dieser Steinhaufe ist heute ein Zeuge zwischen mir und dir!« Darum nannte er ihn ›Galed‹;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 49, 'und den Denkstein, den er aufgerichtet hatte, nannte er ›Mizpa‹, indem er sagte: »Der HERR sei Wächter zwischen mir und dir, wenn wir einander aus den Augen gekommen sind!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 50, 'Solltest du je meine Töchter schlecht behandeln oder noch andere Frauen zu meinen Töchtern hinzunehmen, wenn dann auch kein Mensch bei uns sein sollte – bedenke wohl: Gott ist Zeuge zwischen mir und dir!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 51, 'Weiter sagte Laban zu Jakob: »Siehe, der Steinhaufe hier und der Denkstein hier, den ich zwischen mir und dir aufgerichtet habe:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 52, 'dieser Steinhaufe soll ein Zeuge und der Denkstein hier ein Zeugnis sein, daß weder ich über diesen Steinhaufen zu dir hinausgehen darf, noch du über diesen Steinhaufen und diesen Denkstein zu mir in böser Absicht hinausgehen darfst.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 53, 'Der Gott Abrahams und der Gott Nahors sollen Richter zwischen uns sein, der Gott je ihres Stammvaters!« Als dann Jakob bei dem Gott, den sein Vater Isaak verehrte, geschworen hatte,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 54, 'brachte er ein Schlachtopfer auf dem Berge dar und lud seine Stammesgenossen zur Teilnahme am Mahl ein. So hielten sie denn das Mahl und übernachteten auf dem Berge.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 1, 'Am andern Morgen aber in der Frühe küßte Laban seine Enkel und seine Töchter und nahm Abschied von ihnen; dann brach er auf und kehrte an seinen Wohnort zurück.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 2, 'Als nun auch Jakob seines Weges zog, begegneten ihm Engel Gottes.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 3, 'Sobald Jakob sie erblickte, sagte er: »Hier ist Gottes Heerlager!« Darum nannte er jenen Ort ›Mahanaim‹.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 4, 'Hierauf sandte Jakob Boten voraus an seinen Bruder Esau nach der Landschaft Seir, ins Gebiet der Edomiter,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 5, 'und gab ihnen folgenden Auftrag: »So sollt ihr zu meinem Herrn, zu Esau, sagen: ›Dein Knecht Jakob läßt dir folgendes melden: Ich habe bei Laban in der Fremde gelebt und mich bis jetzt dort aufgehalten;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 6, 'ich habe mir dort Rinder und Esel, Kleinvieh, Knechte und Mägde erworben und sende nun Boten, um es meinem Herrn mitzuteilen, damit ich Gnade in deinen Augen finde.‹«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 7, 'Die Boten kehrten dann zu Jakob zurück mit der Meldung: »Wir sind zu deinem Bruder Esau gekommen, und er zieht dir auch schon in Begleitung von vierhundert Mann entgegen.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 8, 'Da geriet Jakob in große Angst, und es wurde ihm bange; er teilte daher die Leute, die er bei sich hatte, und ebenso das Kleinvieh sowie die Rinder und Kamele in zwei Heere;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 9, 'denn er dachte: »Wenn Esau den einen Zug überfällt und niederschlägt, so wird doch der andere Zug entrinnen können.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 10, 'Dann betete Jakob: »Gott meines Vaters Abraham und meines Vaters Isaak, HERR, der du mir geboten hast: ›Kehre in dein Vaterland und zu deiner Verwandtschaft zurück, ich will dir Gutes tun‹ –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 11, 'ich bin zu gering für all die Gnadenerweise und all die Treue, die du deinem Knecht erwiesen hast! Denn nur mit meinem Wanderstabe bin ich (einst) über den Jordan dort gezogen und bin jetzt zu zwei Heeren geworden.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 12, 'Ach, errette mich nun aus der Hand meines Bruders, aus der Hand Esaus! Denn ich bin in Angst vor ihm, daß er kommt und uns erschlägt, die Mütter samt den Kindern!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 13, 'Du hast mir doch verheißen: ›Gewiß, ich will dir Gutes tun und deine Nachkommen so zahlreich werden lassen, daß sie sind wie der Sand am Meer, den man vor Menge nicht zählen kann.‹«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 14, 'Er blieb dann in jener Nacht dort und wählte aus dem Vieh, das ihm gerade zur Hand war, ein Geschenk für seinen Bruder Esau aus,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 15, 'nämlich zweihundert Ziegen und zwanzig Böcke, zweihundert Mutterschafe und zwanzig Widder,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 16, 'dreißig säugende Kamele nebst ihren Füllen, vierzig junge Kühe und zehn junge Stiere, zwanzig Eselinnen und zehn Eselfüllen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 17, 'Er übergab diese seinen Knechten, jede Herde besonders, und befahl seinen Knechten: »Zieht vor mir her und laßt einen Abstand zwischen den einzelnen Herden!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 18, 'Dann gab er dem ersten folgende Weisung: »Wenn mein Bruder Esau dir begegnet und dich fragt: ›Wem gehörst du, und wohin willst du, und wem gehören die Tiere, die du da treibst?‹,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 19, 'so antworte: ›Sie gehören deinem Knecht Jakob; es ist das ein Geschenk, das er meinem Herrn Esau sendet; er selbst kommt gleich hinter uns her.‹«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 20, 'Dieselbe Weisung gab er auch dem zweiten und dem dritten und allen anderen, welche die Herden trieben, nämlich: »Ganz ebenso sollt ihr zu Esau sagen, wenn ihr ihm begegnet,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 21, 'und sollt weiter sagen: ›Dein Knecht Jakob kommt selbst gleich hinter uns her.‹« Er dachte nämlich: »Ich will ihn durch das Geschenk versöhnen, das mir vorauszieht; erst dann will ich ihm selber vor die Augen treten; vielleicht nimmt er mich dann freundlich an.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 22, 'So zog also das Geschenk vor ihm her, während er selbst jene Nacht im Lager zubrachte.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 23, 'Er machte sich aber noch in derselben Nacht auf, nahm seine beiden Frauen und seine beiden Leibmägde samt seinen elf Söhnen und setzte über die Furt des Jabbok.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 24, 'Er nahm sie also und ließ sie über den Fluß fahren, und als er dann auch alle seine Habe hinübergebracht hatte,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 25, 'blieb er allein zurück. Da rang ein Mann mit ihm bis zum Aufgang der Morgenröte.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 26, 'Als dieser nun sah, daß er ihn nicht bezwingen konnte, gab er ihm einen Schlag auf das Hüftgelenk; dadurch wurde Jakobs Hüftgelenk während seines Ringens mit ihm verrenkt.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 27, 'Da sagte jener: »Laß mich los, denn die Morgenröte ist schon heraufgezogen!« Jakob aber antwortete: »Ich lasse dich nicht los, bevor du mich gesegnet hast.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 28, 'Da fragte jener ihn: »Wie heißt du?« Er antwortete: »Jakob.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 29, 'Da sagte er: »Du sollst hinfort nicht mehr Jakob heißen, sondern ›Israel‹; denn du hast mit Gott und mit Menschen gekämpft und bist Sieger geblieben.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 30, 'Da richtete Jakob die Bitte an ihn: »Teile mir doch deinen Namen mit!« Er aber erwiderte: »Warum willst du meinen Namen wissen?« Hierauf segnete er ihn dort.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 31, 'Jakob nannte dann jenen Ort ›Pniel‹; »denn«, sagte er, »ich habe Gott von Angesicht zu Angesicht gesehen und bin doch am Leben geblieben«.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 32, 'Als er dann an Pniel vorübergezogen war, ging ihm die Sonne auf; er hinkte aber an seiner Hüfte.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 33, 'Darum essen die Israeliten bis auf den heutigen Tag den Muskel nicht, der über der Hüftpfanne liegt, weil er dem Jakob einen Schlag auf die Hüftpfanne, den Hüftmuskel, versetzt hatte.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 33, 1, 'Als nun Jakob aufblickte und seinen Bruder Esau mit vierhundert Mann herankommen sah, verteilte er die Kinder auf Lea, auf Rahel und auf die beiden Leibmägde,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 33, 2, 'und zwar stellte er die Leibmägde mit ihren Kindern vornan, dann Lea mit ihren Kindern hinter sie und Rahel mit Joseph zuletzt.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 33, 3, 'Er selbst aber ging vor ihnen her und verneigte sich siebenmal bis zur Erde, bis er nahe an seinen Bruder herangekommen war.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 33, 4, 'Esau aber eilte ihm entgegen und umarmte ihn, fiel ihm um den Hals und küßte ihn, und sie weinten beide.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 33, 5, 'Als Esau dann aufblickte und die Frauen mit den Kindern gewahrte, fragte er: »Wer sind diese da bei dir?« Er antwortete: »Es sind die Kinder, mit denen Gott deinen Knecht gesegnet hat.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 33, 6, 'Da traten die beiden Leibmägde mit ihren Kindern herzu und verneigten sich;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 33, 7, 'dann trat auch Lea mit ihren Kindern herzu, indem sie sich verneigten; zuletzt traten Joseph und Rahel herzu und verneigten sich.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 33, 8, 'Hierauf fragte Esau weiter: »Was hat denn dieser ganze Zug (des Viehs) zu bedeuten, auf den ich gestoßen bin?« Jakob antwortete: »Ich wollte dadurch die Gunst meines Herrn gewinnen.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 33, 9, 'Da sagte Esau: »Ich habe Besitz genug, lieber Bruder: behalte, was dir gehört!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 33, 10, 'Aber Jakob erwiderte: »Ach nein! Wenn du mir eine Liebe erweisen willst, so nimm mein Geschenk von mir an! Denn als ich dein Angesicht sah, war es mir, als hätte ich Gottes Angesicht gesehen: so freundlich hast du mich angesehen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 33, 11, 'Nimm doch mein Bewillkommnungsgeschenk an, das dir überbracht worden ist! Gott hat mich ja reich gesegnet, und ich habe alles vollauf.« So nötigte er ihn mit Bitten, bis er es annahm.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 33, 12, 'Hierauf sagte Esau: »Laß uns nun aufbrechen und weiterziehen! Ich will vor dir herziehen.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 33, 13, 'Aber Jakob antwortete ihm: »Mein Herr sieht selbst, daß die Kinder noch zart sind und daß ich noch Bedacht auf die säugenden Schafe und Kühe nehmen muß; wenn man diese auch nur einen Tag übertriebe, so würde die ganze Herde zugrunde gehen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 33, 14, 'Mein Herr wolle doch seinem Knecht vorausziehen; ich aber will ganz langsam weiterziehen, wie eben das Vieh, das ich zu treiben habe, und die Kinder fortkommen können, bis ich zu meinem Herrn nach Seir gelange.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 33, 15, 'Da sagte Esau: »So will ich wenigstens einen Teil meiner Leute bei dir zurücklassen.« Doch er antwortete: »Wozu das? Möchte ich nur Gnade in den Augen meines Herrn finden!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 33, 16, 'So kehrte denn Esau an jenem Tage um und zog seines Weges nach Seir zurück.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 33, 17, 'Jakob aber brach nach Sukkoth auf, wo er sich ein Haus baute und für sein Vieh Ställe errichtete; daher erhielt der Ort den Namen Sukkoth.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 33, 18, 'Darauf kam Jakob bei seiner Rückkehr aus Nord-Mesopotamien wohlbehalten nach der Stadt Sichem, die im Lande Kanaan liegt, und schlug dort östlich von der Stadt sein Lager auf.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 33, 19, 'Das Stück Land aber, auf dem er sein Zelt aufgeschlagen hatte, kaufte er von den Söhnen Hemors, des Vaters Sichems, für hundert Silberstücke;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 33, 20, 'und er baute dort einen Altar, den er ›Allgott ist der Gott Israels‹ nannte.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 1, 'Als Dina, die Tochter Jakobs, welche Lea ihm geboren hatte, einst ausging, um sich unter den Mädchen des Landes umzusehen,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 2, 'da sah Sichem sie, der Sohn des Hewiters Hemor, des Landesfürsten; der ergriff sie und tat ihr Gewalt an.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 3, 'Sein Herz hing aber an Dina, der Tochter Jakobs; er gewann das Mädchen lieb und redete ihr freundlich zu.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 4, 'Er sagte daher zu seinem Vater Hemor: »Nimm mir dieses Mädchen zur Frau!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 5, 'Nun hatte Jakob zwar von der Entehrung seiner Tochter Dina Kunde erhalten; weil aber seine Söhne gerade bei seinem Vieh auf dem Felde waren, verhielt er sich ruhig, bis sie heimkamen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 6, 'Da begab sich Hemor, der Vater Sichems, zu Jakob hinaus, um mit ihm zu reden.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 7, 'Als nun die Söhne Jakobs vom Felde heimgekommen waren und von dem Vorfall hörten, fühlten die Männer sich schwer gekränkt und gerieten in lodernden Zorn; denn eine Schandtat hatte Sichem an Israel durch die Entehrung der Tochter Jakobs verübt: derartiges hätte nicht geschehen dürfen!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 8, 'Da sprach sich Hemor folgendermaßen gegen sie aus: »Mein Sohn Sichem hat sein Herz an eure Tochter gehängt; gebt sie ihm doch zur Frau');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 9, 'und verschwägert euch (überhaupt) mit uns: gebt uns eure Töchter und nehmt euch die unsrigen');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 10, 'und bleibt bei uns wohnen! Das Land soll euch zur Verfügung stehen: bleibt darin wohnen und durchzieht es und macht euch darin ansässig!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 11, 'Sichem aber sagte zu ihrem Vater und zu ihren Brüdern: »Gewährt mir doch meine Bitte! Alles, was ihr von mir verlangt, will ich geben!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 12, 'Mögt ihr auch noch so viel als Heiratsgabe und Brautgeschenk von mir fordern: ich will euch geben, soviel ihr von mir verlangt; nur gebt mir das Mädchen zur Frau!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 13, 'Da gaben die Söhne Jakobs dem Sichem und seinem Vater Hemor eine arglistige Antwort – es redeten nämlich die, deren Vollschwester Dina er entehrt hatte –;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 14, 'sie sagten nämlich zu ihnen: »Darauf können wir uns nicht einlassen, unsere Schwester einem unbeschnittenen Manne zu geben; denn das wäre eine Schande für uns.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 15, 'Nur unter der Bedingung wollen wir euch zu Willen sein, wenn ihr so werden wollt, wie wir sind, nämlich wenn alles, was männlichen Geschlechts bei euch ist, sich beschneiden läßt.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 16, 'In diesem Falle wollen wir euch unsere Töchter geben und auch eure Töchter uns zu Frauen nehmen und wollen bei euch wohnen bleiben und zu einem Volk mit euch werden.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 17, 'Wollt ihr aber auf unsern Vorschlag, euch beschneiden zu lassen, nicht eingehen, so nehmen wir unsere Tochter und ziehen von hier weg.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 18, 'Ihr Vorschlag gefiel dem Hemor und seinem Sohne Sichem,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 19, 'und der junge Mann zögerte nicht, darauf einzugehen; denn er war in die Tochter Jakobs verliebt; auch war er der Angesehenste in der ganzen Familie seines Vaters.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 20, 'So gingen denn Hemor und sein Sohn Sichem auf den Marktplatz ihrer Stadt, besprachen sich mit ihren Mitbürgern und sagten:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 21, '»Diese Männer sind friedlich gegen uns gesinnt; so mögen sie bei uns im Lande wohnen bleiben und darin umherziehen; das Land ist ja groß genug für sie nach allen Seiten hin. Wir wollen uns ihre Töchter zu Frauen nehmen und ihnen unsere Töchter geben.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 22, 'Jedoch nur unter der Bedingung sind die Männer gewillt, bei uns zu bleiben und ein Volk mit uns zu bilden, wenn alles, was männlichen Geschlechts bei uns ist, beschnitten wird, wie sie selbst beschnitten sind;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 23, 'ihre Herden, ihr Hab und Gut und all ihr Vieh würden alsdann uns gehören. Ja, wir wollen ihre Forderung annehmen, damit sie bei uns wohnen bleiben.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 24, 'Der Vorschlag Hemors und seines Sohnes Sichem fand die Zustimmung aller, die zum Tor seiner Stadt hinauszugehen pflegten: alle männlichen Personen, alle, die zum Tor seiner Stadt hinauszugehen pflegten, ließen sich beschneiden.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 25, 'Am dritten Tage aber, als sie im Wundfieber lagen, da nahmen die beiden Söhne Jakobs, Simeon und Levi, die Vollbrüder der Dina, jeder sein Schwert, drangen in die Stadt ein, die nichts Böses ahnte, und erschlugen alles Männliche;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 26, 'auch Hemor und seinen Sohn Sichem erschlugen sie mit der Schärfe des Schwertes, holten Dina aus dem Hause Sichems und zogen davon.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 27, 'Die (übrigen) Söhne Jakobs fielen dann über die Erschlagenen her und plünderten die Stadt, weil man ihre Schwester entehrt hatte.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 28, 'Ihr Kleinvieh, ihre Rinder und Esel, sowohl was in der Stadt als auch was draußen auf dem Felde war, nahmen sie weg,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 29, 'überhaupt ihren gesamten Besitz, auch alle ihre Kinder und Frauen führten sie als Gefangene und als Beute weg und raubten alles, was in den Häusern war.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 30, 'Da sagte Jakob zu Simeon und Levi: »Ihr habt mich ins Unglück gestürzt, indem ihr mich bei den Bewohnern des Landes, den Kanaanäern und Pherissitern, tödlich verhaßt gemacht habt, und ich bilde doch nur ein leicht zählbares Häuflein. Wenn sie sich jetzt gegen mich zusammentun, so werden sie mich erschlagen, und ich gehe samt meinem Hause zugrunde!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 31, 'Sie aber antworteten: »Durfte er denn mit unserer Schwester wie mit einer Dirne verfahren?«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 1, 'Da gebot Gott dem Jakob: »Mache dich auf, ziehe nach Bethel hinauf, nimm dort deinen Wohnsitz und errichte dort einen Altar für den Gott, der dir erschienen ist, als du vor deinem Bruder Esau flohst!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 2, 'Da befahl Jakob seiner Familie und allen anderen, die bei ihm waren: »Schafft die fremden Götter weg, die ihr bei euch habt, reinigt euch und legt andere Kleider an!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 3, 'Wir wollen aufbrechen und nach Bethel hinaufziehen: dort will ich einen Altar errichten dem Gott, der mich zur Zeit meiner Not erhört hat und auf dem Wege, den ich gezogen bin, mit mir gewesen ist.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 4, 'Darauf übergaben sie dem Jakob alle fremden Götter, die in ihrem Besitz waren, und ebenso ihre Ohrringe, und Jakob vergrub sie unter der Terebinthe, die bei Sichem steht.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 5, 'Als sie dann aufbrachen, fiel ein Schrecken Gottes auf die Ortschaften der ganzen Umgegend, so daß sie die Söhne Jakobs nicht verfolgten.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 6, 'So kam denn Jakob nach Lus, das im Lande Kanaan liegt – das ist Bethel –, er samt allen Leuten, die sich bei ihm befanden.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 7, 'Er baute dort einen Altar und nannte die Stätte ›der Gott von Bethel‹, weil Gott sich ihm dort geoffenbart hatte, als er vor seinem Bruder floh.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 8, 'Damals starb Debora, die Amme der Rebekka, und wurde unterhalb Bethels unter der Eiche begraben, die seitdem die ›Klageeiche‹ heißt.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 9, 'Da erschien Gott dem Jakob zum zweitenmal seit seiner Rückkehr aus Nord-Mesopotamien und segnete ihn;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 10, 'und Gott sagte zu ihm: »Dein Name ist Jakob; aber künftig sollst du nicht mehr Jakob heißen, sondern ›Israel‹ soll dein Name sein«; so gab er ihm den Namen Israel.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 11, 'Weiter sagte Gott zu ihm: »Ich bin der allmächtige Gott; sei fruchtbar und mehre dich! Ein Volk, ja eine ganze Menge von Völkern soll aus dir werden, und Könige sollen unter deinen leiblichen Nachkommen sein.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 12, 'Und das Land, das ich Abraham und Isaak gegeben habe, will ich dir geben und es auch deiner Nachkommenschaft nach dir verleihen.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 13, 'Hierauf fuhr Gott von ihm in die Höhe empor an der Stätte, wo er mit ihm geredet hatte.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 14, 'Da errichtete Jakob einen Denkstein an der Stätte, wo er mit ihm geredet hatte, ein Denkmal von Stein, und goß ein Trankopfer auf dasselbe aus und begoß es mit Öl.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 15, 'Und Jakob nannte die Stätte, wo Gott mit ihm geredet hatte, ›Bethel‹.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 16, 'Hierauf zogen sie von Bethel weiter; und als sie nur noch eine Strecke Weges bis nach Ephrath zu gehen hatten, wurde Rahel von Geburtswehen befallen und hatte eine schwere Niederkunft.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 17, 'Als sie nun bei der Geburt schwer zu leiden hatte, sagte die Wehmutter zu ihr: »Laß dir nicht bange sein! Denn du wirst auch diesmal einen Sohn haben.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 18, 'Als ihr dann aber die Seele entfloh – denn sie mußte sterben –, nannte sie ihn ›Benoni‹, sein Vater aber nannte ihn ›Benjamin‹.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 19, 'So starb Rahel und wurde auf dem Wege nach Ephrath, das jetzt Bethlehem heißt, begraben.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 20, 'Jakob errichtete dann einen Denkstein auf ihrem Grabe; das ist der Denkstein, der auf dem Grabe Rahels noch heute steht.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 21, 'Hierauf zog Israel weiter und schlug sein Zelt jenseits von Migdal-Eder auf.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 22, 'Während nun Israel sich in jener Gegend aufhielt, ging Ruben hin und verging sich mit Bilha, dem Nebenweibe seines Vaters; und Israel erfuhr es. – Jakob hatte aber zwölf Söhne.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 23, 'Die Söhne der Lea waren: Ruben, der Erstgeborene Jakobs, ferner Simeon, Levi, Juda, Issaschar und Sebulon.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 24, 'Die Söhne der Rahel waren: Joseph und Benjamin.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 25, 'Die Söhne der Bilha, der Leibmagd Rahels, waren: Dan und Naphthali,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 26, 'und die Söhne der Silpa, der Leibmagd Leas, waren: Gad und Asser. Dies sind die Söhne Jakobs, die ihm in Nord-Mesopotamien geboren worden waren.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 27, 'Jakob kam dann zu seinem Vater Isaak nach Mamre, der Stadt Arbas, das ist Hebron, woselbst Abraham und Isaak als Fremdlinge gewohnt hatten.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 28, 'Isaak brachte aber sein Leben auf hundertundachtzig Jahre;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 29, 'da verschied Isaak und starb und wurde zu seinen Stammesgenossen versammelt, alt und lebenssatt; und seine Söhne Esau und Jakob begruben ihn.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 1, 'Dies sind die Nachkommen Esaus, das ist Edoms.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 2, 'Esau hatte seine Frauen aus den Kanaanäerinnen genommen, nämlich Ada, die Tochter des Hethiters Elon, und Oholibama, die Tochter Anas, die Enkelin des Hewiters Zibeon,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 3, 'und Basmath, die Tochter Ismaels, die Schwester Nebajoths.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 4, 'Ada gebar dann dem Esau den Eliphas, und Basmath gebar den Reguel;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 5, 'und Oholibama gebar Jehus und Jaglam und Korah. Dies sind die Söhne Esaus, die ihm im Lande Kanaan geboren wurden.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 6, 'Dann nahm Esau seine Frauen, seine Söhne und Töchter, überhaupt alle Personen, die zu seinem Hause gehörten, dazu auch seinen Besitz, sowohl all sein Vieh als auch seine ganze Habe, die er im Lande Kanaan erworben hatte, und zog von seinem Bruder Jakob weg in ein anderes Land (Seir);');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 7, 'denn ihr Besitz war zu groß, als daß sie hätten beieinanderbleiben können, und das Land, in dem sie als Fremdlinge wohnten, reichte für sie wegen der Menge ihrer Herden nicht aus.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 8, 'So ließ sich denn Esau im Gebirge Seir nieder: Esau, das ist Edom.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 9, 'Dies sind die Nachkommen Esaus, des Stammvaters der Edomiter im Gebirge Seir.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 10, 'Dies sind die Namen der Söhne Esaus: Eliphas, der Sohn der Ada, der Frau Esaus, Reguel, der Sohn der Basmath, der Frau Esaus.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 11, 'Die Söhne des Eliphas waren: Theman, Omar, Zepho, Gaetham und Kenas.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 12, 'Thimna aber war ein Nebenweib des Eliphas, des Sohnes Esaus; die gebar dem Eliphas den Amalek. Dies sind die Nachkommen der Ada, der Frau Esaus.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 13, 'Die Söhne Reguels aber sind diese: Nahath und Serah, Samma und Missa. Dies waren die Nachkommen der Basmath, der Frau Esaus.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 14, 'Und die Söhne von Esaus Frau Oholibama, der Tochter Anas, der Enkelin Zibeons, die sie dem Esau gebar, waren diese: Jehus, Jaglam und Korah.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 15, 'Dies sind die Gaufürsten unter den Nachkommen Esaus: Die Söhne des Eliphas, des erstgeborenen Sohnes Esaus, waren: der Häuptling Theman, der Häuptling Omar, der Häuptling Zepho, der Häuptling Kenas,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 16, 'der Häuptling Korah, der Häuptling Gaetham, der Häuptling Amalek. Dies sind die Häuptlinge, die von Eliphas im Lande Edom abstammen, die Abkömmlinge der Ada.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 17, 'Und dies sind die Söhne Reguels, des Sohnes Esaus: der Häuptling Nahath, der Häuptling Serah, der Häuptling Samma, der Häuptling Missa. Dies sind die Häuptlinge, die von Reguel im Lande Edom abstammen, die Abkömmlinge der Basmath, der Frau Esaus.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 18, 'Und dies sind die Söhne der Oholibama, der Frau Esaus: der Häuptling Jehus, der Häuptling Jaglam, der Häuptling Korah. Dies sind die Häuptlinge, die von Esaus Frau Oholibama, der Tochter Anas, abstammen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 19, 'Dies sind die Söhne Esaus und dies ihre Häuptlinge: das ist Edom.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 20, 'Dies sind die Söhne des Horiters Seir, die früher im Lande wohnten: Lotan, Sobal, Zibeon, Ana,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 21, 'Dison, Ezer und Disan. Dies sind die Gaufürsten der Horiter, der Söhne Seirs, im Lande Edom.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 22, 'Die Söhne Lotans waren: Hori und Hemam, und Lotans Schwester hieß Thimna.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 23, 'Und dies sind die Söhne Sobals: Alwan und Manahath und Ebal, Sepho und Onam.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 24, 'Und dies sind die Söhne Zibeons: Ajja und Ana. Das ist derselbe Ana, der die heißen Quellen in der Wüste entdeckte, als er seinem Vater Zibeon die Esel hütete.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 25, 'Die Söhne Anas aber sind diese: Dison; und Oholibama war die Tochter Anas.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 26, 'Und dies sind die Söhne Disons: Hemdan, Esban, Jithran und Cheran.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 27, 'Dies sind die Söhne Ezers: Bilhan, Saawan und Akan.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 28, 'Dies sind die Söhne Disans: Uz und Aran.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 29, 'Dies sind die Häuptlinge der Horiter: der Häuptling Lotan, der Häuptling Sobal, der Häuptling Zibeon, der Häuptling Ana,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 30, 'der Häuptling Dison, der Häuptling Ezer, der Häuptling Disan. Da sind die Häuptlinge der Horiter nach ihren Stämmen im Lande Seir.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 31, 'Und dies sind die Könige, die im Lande Edom geherrscht haben, ehe ein König der Israeliten geherrscht hat:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 32, 'Bela, der Sohn Beors, war König in Edom, und seine Stadt hieß Dinhaba.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 33, 'Nach Belas Tode wurde König an seiner Statt Jobab, der Sohn Serahs, aus Bozra.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 34, 'Nach Jobabs Tode wurde König an seiner Statt Husam aus der Landschaft der Themaniter.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 35, 'Nach Husams Tode wurde König an seiner Statt Hadad, der Sohn Bedads, der die Midianiter auf der Hochebene der Moabiter besiegte; seine Stadt hieß Awith.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 36, 'Nach Hadads Tode wurde Samla aus Masreka König an seiner Statt.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 37, 'Nach Samlas Tode wurde Saul aus Rehoboth am Euphratstrom König an seiner Statt.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 38, 'Nach Sauls Tode wurde König an seiner Statt Baal-Hanan, der Sohn Achbors.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 39, 'Als Baal-Hanan, der Sohn Achbors, starb, wurde König an seiner Statt Hadar, dessen Hauptstadt Pagu hieß; seine Frau hieß Mehetabeel und war die Tochter Matreds, die Enkelin Mesahabs.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 40, 'Dies sind die Namen der Gaufürsten Esaus nach ihren Geschlechtern, nach ihren Wohnplätzen und mit ihren Namen: der Häuptling von Thimna, der Häuptling von Alwa, der Häuptling von Jetheth,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 41, 'der Häuptling von Oholibama, der Häuptling von Ela, der Häuptling von Pinon,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 42, 'der Häuptling von Kenas, der Häuptling von Theman, der Häuptling von Mibzar,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 43, 'der Häuptling von Magdiel, der Häuptling von Iram. Das sind die Häuptlinge der Edomiter nach ihren Wohnsitzen in dem Lande, das sie in Besitz genommen hatten. Das ist Esau, der Stammvater der Edomiter.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 1, 'Jakob aber blieb in dem Lande wohnen, in dem sich sein Vater als Fremdling aufgehalten hatte, im Lande Kanaan.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 2, 'Dies ist die Geschichte Jakobs: Als Joseph siebzehn Jahre alt war, hütete er das Kleinvieh mit seinen Brüdern, und zwar war er als junger Bursche bei den Söhnen der Bilha und Silpa, der Frauen seines Vaters, und was man diesen Übles nachsagte, hinterbrachte er ihrem Vater.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 3, 'Israel hatte aber Joseph lieber als alle seine anderen Söhne, weil er ihm in seinem Alter geboren war; und so ließ er ihm ein langes Ärmelkleid machen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 4, 'Als nun seine Brüder sahen, daß ihr Vater ihn lieber hatte als alle seine Brüder, faßten sie einen Haß gegen ihn und gewannen es nicht über sich, ein freundliches Wort mit ihm zu reden.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 5, 'Einst hatte Joseph einen Traum und teilte ihn seinen Brüdern mit; seitdem haßten sie ihn noch mehr.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 6, 'Er sagte nämlich zu ihnen: »Hört einmal diesen Traum, den ich gehabt habe!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 7, 'Wir waren gerade damit beschäftigt, Garben draußen auf dem Felde zu binden, und denkt nur: meine Garbe richtete sich empor und blieb auch aufrecht stehen, eure Garben aber stellten sich rings im Kreise um sie auf und verneigten sich vor meiner Garbe.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 8, 'Da sagten seine Brüder zu ihm: »Du möchtest wohl gern König über uns werden oder gar Herrscher über uns sein?« Seitdem haßten sie ihn noch mehr wegen seiner Träume und wegen seiner Reden.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 9, 'Ein andermal hatte er wieder einen Traum, den er seinen Brüdern so erzählte: »Hört, ich habe wieder einen Traum gehabt! Denkt nur: die Sonne, der Mond und elf Sterne verneigten sich vor mir!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 10, 'Als er das seinem Vater und seinen Brüdern erzählte, schalt ihn sein Vater und sagte zu ihm: »Was ist das für ein Traum, den du da gehabt hast! Meinst du, ich und deine Mutter und deine Brüder sollen kommen und uns vor dir zur Erde verneigen?«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 11, 'So wurden denn seine Brüder eifersüchtig auf ihn, sein Vater aber behielt das Wort im Gedächtnis.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 12, 'Als nun seine Brüder einst hingegangen waren, um das Kleinvieh ihres Vaters bei Sichem zu weiden,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 13, 'sagte Israel zu Joseph: »Du weißt, deine Brüder sind auf der Weide bei Sichem: komm, ich will dich zu ihnen schicken.« Joseph antwortete ihm: »Ich bin bereit!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 14, 'Da sagte er zu ihm: »Gehe doch hin und sieh zu, wie es deinen Brüdern geht und wie es um das Vieh steht, und bringe mir Bescheid!« So sandte er ihn aus dem Tal von Hebron, und Joseph kam nach Sichem.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 15, 'Während er nun dort auf dem Felde umherirrte, traf ihn ein Mann; der fragte ihn: »Was suchst du?«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 16, 'Er antwortete: »Meine Brüder suche ich; sage mir doch, wo sie jetzt weiden!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 17, 'Der Mann antwortete: »Sie sind von hier weggezogen; denn ich habe sie sagen hören: ›Wir wollen nach Dothan gehen.‹« Da ging Joseph hinter seinen Brüdern her und fand sie bei Dothan.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 18, 'Als sie ihn nun von weitem sahen, machten sie, ehe er noch in ihre Nähe gekommen war, einen Anschlag auf sein Leben');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 19, 'und sagten zueinander: »Da kommt ja der Träumer her!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 20, 'Nun wohlan! Wir wollen ihn totschlagen und in eine der Gruben werfen und dann sagen, ein wildes Tier habe ihn gefressen; dann werden wir ja sehen, was aus seinen Träumen wird!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 21, 'Als Ruben das hörte, suchte er ihn aus ihren Händen zu retten, indem er sagte: »Wir wollen ihn nicht totschlagen!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 22, 'Dann sagte Ruben weiter zu ihnen: »Vergießt kein Blut! Werft ihn in die Grube dort in der Steppe, aber legt nicht Hand an ihn!« – er wollte ihn nämlich aus ihrer Hand retten und ihn dann wieder zu seinem Vater bringen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 23, 'Sobald nun Joseph bei seinen Brüdern angekommen war, zogen sie ihm seinen Rock aus, das lange Ärmelkleid, das er anhatte,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 24, 'ergriffen ihn hierauf und warfen ihn in die Grube; die Grube war aber leer, es befand sich kein Wasser darin.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 25, 'Als sie sich dann niedergesetzt hatten, um zu essen, und in die Ferne schauten, sahen sie eine Karawane von Ismaelitern, die aus Gilead herkamen und deren Kamele mit Tragakanth, Mastix und Ladanum beladen waren; sie wollten damit nach Ägypten hinabziehen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 26, 'Da sagte Juda zu seinen Brüdern: »Welchen Vorteil hätten wir davon, wenn wir unsern Bruder erschlügen und seine Ermordung verheimlichten?');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 27, 'Kommt, wir wollen ihn an die Ismaeliter verkaufen, aber nicht selbst Hand an ihn legen; er ist ja doch unser Bruder, unser Fleisch und Blut!« Seine Brüder gingen auf den Vorschlag ein.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 28, 'Als nun die midianitischen Kaufleute vorüberkamen, zogen sie Joseph aus der Grube herauf und verkauften ihn für zwanzig Silberstücke an die Ismaeliter; diese brachten Joseph dann nach Ägypten.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 29, 'Als Ruben nun zu der Grube zurückkehrte und Joseph sich nicht mehr in der Grube befand, da zerriß er seine Kleider,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 30, 'kehrte zu seinen Brüdern zurück und rief aus: »Der Knabe ist nicht mehr da! Wohin soll ich nun gehen?«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 31, 'Hierauf nahmen sie Josephs Rock, schlachteten einen Ziegenbock und tauchten den Rock in das Blut;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 32, 'dann ließen sie das lange Ärmelkleid durch einen Boten ihrem Vater überbringen und ihm sagen: »Dieses haben wir gefunden: sieh doch genau zu, ob es der Rock deines Sohnes ist oder nicht!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 33, 'Er sah es genau an und rief aus: »Es ist der Rock meines Sohnes! Ein wildes Tier hat ihn gefressen! Ja, ja, Joseph ist zerfleischt worden!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 34, 'Und Jakob zerriß seine Kleider, legte ein härenes Gewand um seine Hüften und trauerte um seinen Sohn lange Zeit.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 35, 'Alle seine Söhne und alle seine Töchter bemühten sich zwar, ihn zu trösten, aber er wies jeden Trost zurück und sagte: »Nein, im Trauerkleid will ich zu meinem Sohn in die Unterwelt hinabfahren!« So beweinte ihn sein Vater.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 36, 'Die Midianiter aber verkauften Joseph nach Ägypten an Potiphar, einen Hofbeamten des Pharaos, den Obersten der Leibwächter.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 1, 'Um diese Zeit begab es sich, daß Juda sich von seinen Brüdern trennte und sich an einen Mann aus Adullam namens Hira anschloß.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 2, 'Dort sah Juda die Tochter eines Kanaanäers namens Sua; die nahm er zur Frau und lebte mit ihr.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 3, 'Sie wurde guter Hoffnung und gebar einen Sohn, den er Ger nannte.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 4, 'Hierauf wurde sie wieder guter Hoffnung und gebar einen Sohn, den sie Onan nannte.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 5, 'Sodann wurde sie nochmals Mutter eines Sohnes, dem sie den Namen Sela gab; sie befand sich aber in Chesib, als sie ihn gebar. –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 6, 'Juda nahm dann für seinen erstgeborenen Sohn Ger eine Frau namens Thamar.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 7, 'Aber Ger, der Erstgeborene Judas, zog sich das Mißfallen des HERRN zu; daher ließ der HERR ihn sterben.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 8, 'Da sagte Juda zu Onan: »Gehe zu der Frau deines Bruders ein und leiste ihr die Schwagerpflicht, damit du das Geschlecht deines Bruders fortpflanzest!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 9, 'Da Onan aber wußte, daß die Kinder nicht als seine eigenen gelten würden, ließ er, sooft er zu der Frau seines Bruders einging, (den Samen) zur Erde fallen, um seinem Bruder keine Nachkommen zu verschaffen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 10, 'Dieses sein Tun mißfiel aber dem HERRN, und so ließ er auch ihn sterben.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 11, 'Da sagte Juda zu seiner Schwiegertochter Thamar: »Bleibe als Witwe im Hause deines Vaters wohnen, bis mein Sohn Sela herangewachsen ist!« Er fürchtete nämlich, daß auch dieser sterben würde wie seine Brüder. So ging denn Thamar hin und wohnte im Hause ihres Vaters.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 12, 'Als nun geraume Zeit vergangen war, starb die Tochter Suas, die Frau Judas; und als die Trauerzeit vorüber war, ging Juda (einmal) mit seinem Freunde Hira, dem Adullamiter, nach Thimna hinauf, um seine Schafe zu scheren.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 13, 'Als nun der Thamar berichtet wurde, daß ihr Schwiegervater sich gerade zur Schafschur nach Thimna hinauf begäbe,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 14, 'legte sie ihre Witwenkleidung ab, hüllte sich dicht in einen Schleier und setzte sich an den Eingang von Enaim, das am Wege nach Thimna liegt; denn sie hatte gesehen, daß Sela erwachsen war, ohne daß man sie ihm zur Frau gegeben hatte.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 15, 'Als nun Juda sie da sitzen sah, hielt er sie für eine Dirne; denn sie hatte ihr Gesicht verhüllt.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 16, 'Er bog also zu ihr ab zu der Stelle des Weges hin, wo sie saß, und sagte: »Komm her, sei mir zu Willen!« Denn er wußte nicht, daß sie seine Schwiegertochter war. Sie antwortete: »Was willst du mir dafür geben, wenn ich dir zu Willen bin?«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 17, 'Er sagte: »Ich will dir ein Böckchen von der Herde herschicken.« Sie erwiderte: »Ja, wenn du mir solange ein Pfand gibst, bis du es herschickst.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 18, 'Da fragte er: »Was für ein Pfand ist es, das ich dir geben soll?« Sie antwortete: »Deinen Siegelring, deine Schnur und den Stab, den du da in der Hand hast.« Da gab er es ihr und wohnte ihr bei, und sie wurde schwanger von ihm.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 19, 'Hierauf stand sie auf, entfernte sich, legte ihren Schleier ab und zog ihre Witwenkleidung wieder an.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 20, 'Juda schickte nun das Böckchen durch seinen Freund, den Adullamiter, um das Pfand von dem Weibe zurückzuerhalten; aber der fand sie nicht;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 21, 'und als er bei den Leuten jenes Ortes nachfragte: »Wo ist die geweihte Buhlerin, die hier bei Enaim am Wege gesessen hat?«, antworteten sie ihm: »Hier ist keine geweihte Buhlerin gewesen.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 22, 'So kehrte er denn zu Juda zurück und sagte: »Ich habe sie nicht gefunden; auch haben die Leute des Ortes gesagt, es sei dort keine geweihte Buhlerin gewesen.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 23, 'Da erwiderte Juda: »So mag sie es für sich behalten, damit wir uns nicht den Spott der Leute zuziehen! Du weißt ja, daß ich dies Böckchen geschickt habe; du hast sie aber nicht gefunden.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 24, 'Ungefähr drei Monate später wurde dem Juda als sicher berichtet: »Deine Schwiegertochter Thamar hat sich verführen lassen und ist infolge ihrer Ausschweifung schwanger geworden.« Da gebot Juda: »Führt sie hinaus, damit sie verbrannt wird!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 25, 'Als sie nun hinausgeführt werden sollte, schickte sie zu ihrem Schwiegervater und ließ ihm sagen: »Von dem Manne, dem diese Sachen hier gehören, bin ich schwanger«; und weiter ließ sie ihm sagen: »Sieh doch genau zu, wem dieser Siegelring, diese Schnur und dieser Stab gehören!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 26, 'Als nun Juda die Sachen genau angesehen hatte, sagte er: »Sie ist mir gegenüber im Recht: warum habe ich sie meinem Sohne Sela nicht zur Frau gegeben!« Er vollzog aber hinfort keine Beiwohnung mehr mit ihr.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 27, 'Als nun die Zeit ihrer Niederkunft da war, ergab es sich, daß Zwillinge in ihrem Mutterschoße waren;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 28, 'und bei der Geburt streckte das eine Kind die Hand vor; da griff die Wehmutter zu, band ihm einen roten Faden um die Hand und sagte: »Dieser ist zuerst zum Vorschein gekommen.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 29, 'Doch (das Kind) zog seine Hand wieder zurück, und nun kam sein Bruder zum Vorschein. Da sagte sie: »Was für einen Riß hast du dir da gerissen!« Daher nannte man ihn ›Perez‹.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 30, 'Darauf kam sein Bruder zum Vorschein, an dessen Hand der rote Faden war; daher nannte man ihn ›Serah‹.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 39, 1, 'Als aber Joseph nach Ägypten gebracht worden war, kaufte ihn Potiphar, ein Ägypter, ein Hofbeamter des Pharaos, der Oberste der Leibwächter, von den Ismaelitern, die ihn dorthin gebracht hatten.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 39, 2, 'Gott der HERR aber war mit Joseph, so daß ihm alles gelang, während er im Hause seines Herrn, des Ägypters, war.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 39, 3, 'Weil nun sein Herr sah, daß Gott mit ihm war und daß Gott alles, was er vornahm, ihm gelingen ließ,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 39, 4, 'wandte er dem Joseph seine Gunst zu, so daß er sich selbst von ihm bedienen ließ; dann machte er ihn zum Aufseher über sein Hauswesen und vertraute ihm alles an, was er besaß.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 39, 5, 'Und von der Zeit an, wo er ihn zum Aufseher über sein Haus und zum Verwalter seines ganzen Besitzes gemacht hatte, segnete Gott das Haus des Ägypters um Josephs willen, so daß der Segen Gottes auf allem ruhte, was er besaß, im Hause und auf dem Felde.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 39, 6, 'Daher überließ er sein ganzes Besitztum der Verwaltung Josephs: er selbst kümmerte sich neben ihm um nichts mehr als um seine Mahlzeiten. Joseph war aber schön von Gestalt und schön von Angesicht.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 39, 7, 'So kam es schließlich dahin, daß die Gattin seines Herrn ihre Augen auf Joseph richtete und ihn verführen wollte.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 39, 8, 'Er weigerte sich aber und sagte zu der Gattin seines Herrn: »Bedenke doch! Mein Herr kümmert sich neben mir um nichts im Hause und hat mir alles anvertraut, was er besitzt.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 39, 9, 'Er selbst hat in diesem Hause keine größere Geltung als ich, und nichts hat er mir vorenthalten als dich allein, weil du ja sein Weib bist. Wie sollte ich da ein so großes Unrecht begehen und mich gegen Gott versündigen!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 39, 10, 'Obgleich sie daher Tag für Tag auf Joseph einredete, hörte er doch nicht auf sie, daß er sich zu ihr getan und sich mit ihr vergangen hätte.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 39, 11, 'Nun begab es sich eines Tages, daß Joseph, wie gewöhnlich, ins Haus kam, um seine Geschäfte zu besorgen, während gerade keiner von den Hausangehörigen drinnen im Hause anwesend war.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 39, 12, 'Da faßte sie ihn am Gewand mit den Worten: »Sei mir zu Willen!« Er aber ließ sein Gewand in ihrer Hand, ergriff die Flucht und eilte zum Hause hinaus.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 39, 13, 'Als sie nun sah, daß er sein Gewand in ihrer Hand gelassen hatte und zum Hause hinausgeflohen war,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 39, 14, 'rief sie die Leute ihres Hauses herbei und sagte zu ihnen: »Seht doch! Er hat uns da einen Hebräer hereingebracht, daß er seinen Mutwillen an uns auslasse! Der ist zu mir hereingekommen, um mich zu verführen; ich habe aber laut geschrien,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 39, 15, 'und als er hörte, daß ich ein lautes Geschrei erhob und um Hilfe rief, hat er sein Gewand neben mir liegen lassen und ist zum Hause hinaus entflohen!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 39, 16, 'Dann ließ sie sein Gewand neben sich liegen, bis sein Herr nach Hause kam;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 39, 17, 'und sie erzählte ihm den Vorfall mit denselben Worten, nämlich: »Der hebräische Sklave, den du uns hergebracht hast, ist zu mir hereingekommen, um seinen Mutwillen an mir auszulassen;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 39, 18, 'als ich aber ein lautes Geschrei erhob und um Hilfe rief, hat er sein Gewand neben mir liegen lassen und ist zum Hause hinausgeflohen!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 39, 19, 'Als nun sein Herr die Mitteilung seiner Frau hörte, die ihm berichtete: »So und so hat dein Sklave sich gegen mich benommen!«, da stieg der Zorn in ihm auf;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 39, 20, 'und der Herr Josephs ließ ihn ergreifen und ins Gefängnis werfen, an den Ort, wo die Gefangenen des Königs in Gewahrsam lagen; dort saß er nun im Gefängnis.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 39, 21, 'Aber Gott der HERR war mit Joseph und ließ ihn die Zuneigung aller gewinnen und wandte ihm auch die Gunst des obersten Aufsehers des Gefängnisses zu.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 39, 22, 'Dieser übergab alle Gefangenen, die sich im Gefängnis befanden, dem Joseph zur Aufsicht; und alles, was es dort zu tun gab, hatte dieser zu besorgen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 39, 23, 'Der oberste Aufseher des Gefängnisses kümmerte sich um gar nichts bei allem, was ihm anvertraut war; denn Gott der HERR war mit ihm, und Gott ließ alles gelingen, was er vornahm.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 40, 1, 'Nun begab es sich einige Zeit danach, daß der Mundschenk und der Bäcker des Königs von Ägypten sich gegen ihren Herrn, den König von Ägypten, verfehlten.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 40, 2, 'Da geriet der Pharao über seine beiden Hofbeamten, den Obermundschenken und den Oberbäcker, in Zorn,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 40, 3, 'und er ließ sie im Hause des Obersten der Leibwächter in Haft legen, ins Gefängnis, an den Ort, wo auch Joseph gefangen lag.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 40, 4, 'Der Oberste der Leibwächter aber betraute Joseph mit der Fürsorge für sie, so daß er sie zu bedienen hatte; und so befanden sie sich eine Zeitlang in Haft.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 40, 5, 'Da träumten sie beide in einer und derselben Nacht einen Traum, und zwar jeder einen eigenen Traum von besonderer Bedeutung, der Mundschenk und der Bäcker des Königs von Ägypten, die im Kerker gefangen saßen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 40, 6, 'Als nun Joseph am Morgen zu ihnen hineinkam und bemerkte, daß sie mißgestimmt waren,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 40, 7, 'fragte er sie, die beiden Hofbeamten des Pharaos, die sich mit ihm im Hause seines Herrn in Haft befanden: »Warum seht ihr denn heute so mißmutig aus?«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 40, 8, 'Sie antworteten ihm: »Wir haben einen Traum gehabt, und nun ist niemand da, der ihn uns deuten könnte.« Da sagte Joseph zu ihnen: »Traumdeutungen sind Sache Gottes: erzählt mir doch eure Träume!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 40, 9, 'Da erzählte der Obermundschenk dem Joseph seinen Traum folgendermaßen: »In meinem Traume war es mir, als ob ich einen Weinstock vor mir stehen sähe;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 40, 10, 'an diesem Weinstock waren drei Reben; und sowie er anfing zu treiben, brachen auch schon seine Blüten hervor, und die Trauben brachten die Beeren zur Reife.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 40, 11, 'Ich aber hielt den Becher des Pharaos in der Hand, nahm die Trauben, preßte sie aus in den Becher des Pharaos und gab dann den Becher dem Pharao in die Hand.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 40, 12, 'Da sagte Joseph zu ihm: »Dies ist die Deutung: Die drei Weinreben sind drei Tage;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 40, 13, 'in drei Tagen von heute ab wird der Pharao dir das Haupt erheben, indem er dich wieder in dein Amt einsetzt, so daß du ihm den Becher in die Hand gibst ganz nach der früheren Weise, als du noch sein Mundschenk warst.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 40, 14, 'Aber halte dann auch die Erinnerung an mich fest, wenn es dir wieder gut geht, erweise mir dann die Liebe, den Pharao auf mich aufmerksam zu machen, und bringe mich aus diesem Hause hinaus!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 40, 15, 'Denn ich bin aus dem Lande der Hebräer heimlich gestohlen worden und habe auch hier gar nichts begangen, daß man mich in den Kerker geworfen hat.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 40, 16, 'Als nun der Oberbäcker sah, daß Joseph eine günstige Deutung gegeben hatte, sagte er zu Joseph: »Auch in meinem Traume war es mir, als trüge ich drei Körbe mit feinem Gebäck auf meinem Haupte;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 40, 17, 'und in dem obersten Korb befanden sich allerlei Eßwaren für den Pharao, wie sie der Bäcker herstellt; aber die Vögel fraßen sie aus dem Korbe auf meinem Haupte weg.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 40, 18, 'Da sagte Joseph: »Dies ist die Deutung des Traumes: Die drei Körbe sind drei Tage;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 40, 19, 'in drei Tagen von heute ab wird der Pharao dir das Haupt erheben, nämlich dich an einen Baum hängen lassen; da werden dann die Vögel das Fleisch von dir oben wegfressen.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 40, 20, 'Drei Tage später nun war der Geburtstag des Pharaos; da veranstaltete er ein Festmahl für alle seine Diener und erhob seinem Obermundschenken und seinem Oberbäcker das Haupt inmitten seiner Diener;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 40, 21, 'den Obermundschenken setzte er wieder in sein Schenkenamt ein, so daß er dem Pharao wieder den Becher zu reichen hatte;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 40, 22, 'den Oberbäcker aber ließ er hängen, ganz so, wie Joseph ihnen (die Träume) gedeutet hatte.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 40, 23, 'Aber der Obermundschenk dachte nicht mehr an Joseph, sondern vergaß ihn.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 1, 'Nun begab es sich nach Verlauf von zwei vollen Jahren, daß der Pharao einen Traum hatte: ihm war es, er stehe am Nil.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 2, 'Da sah er aus dem Strom sieben schöne, wohlgenährte Kühe heraufsteigen und im Riedgras weiden.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 3, 'Dann sah er nach diesen sieben andere Kühe aus dem Strom heraufsteigen, die sahen häßlich aus und waren mager am Fleisch und traten neben die anderen Kühe am Ufer des Stromes;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 4, 'hierauf fraßen die häßlichen und mageren Kühe die sieben schönen und wohlgenährten Kühe auf. Da erwachte der Pharao.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 5, 'Als er dann wieder eingeschlafen war, hatte er einen zweiten Traum; und zwar sah er sieben Ähren oben an einem Halme wachsen, dicke und schöne;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 6, 'nach diesen aber schossen sieben dünne und vom Ostwind versengte Ähren hervor,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 7, 'und diese dünnen Ähren verschlangen die sieben dicken und vollen Ähren. Da erwachte der Pharao und merkte, daß es ein (bedeutungsvoller) Traum war.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 8, 'Am Morgen fühlte er sich darüber innerlich beunruhigt, so daß er alle Schriftkundigen Ägyptens und alle Weisen des Landes rufen ließ; er erzählte ihnen seine Träume, aber es war keiner da, der sie dem Pharao zu deuten vermochte.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 9, 'Da nahm der Obermundschenk das Wort und sagte zum Pharao: »Ich muß heute meine Verfehlungen in Erinnerung bringen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 10, 'Als der Pharao (einst) über seine Diener in Zorn geraten war und mich im Hause des Obersten der Leibwächter in Gewahrsam hatte legen lassen, mich und den Oberbäcker,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 11, 'da hatten wir beide in einer und derselben Nacht einen Traum, ich und er, und zwar jeder einen Traum von besonderer Bedeutung.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 12, 'Nun befand sich dort ein hebräischer junger Mann bei uns, ein Sklave des Obersten der Leibwächter; dem erzählten wir’s, und er deutete uns unsere Träume: er gab dem Traum eines jeden die entsprechende Deutung,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 13, 'und ganz so, wie er uns die Deutung gegeben hatte, so ist es eingetroffen: mich hat (der Pharao) wieder in mein Amt eingesetzt, und jenen hat er hängen lassen.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 14, 'Da sandte der Pharao hin und ließ Joseph rufen; man holte ihn in aller Eile aus dem Gefängnis; er mußte sich scheren lassen und andere Kleider anziehen und trat dann vor den Pharao.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 15, 'Da sagte der Pharao zu Joseph: »Ich habe einen Traum gehabt, aber niemand weiß ihn zu deuten. Nun habe ich von dir sagen hören, du brauchtest einen Traum nur zu hören, so könntest du ihn schon deuten.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 16, 'Da antwortete Joseph dem Pharao: »O nein, nicht ich! Aber Gott wird etwas kundtun, was dem Pharao Segen bringt.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 17, 'Nun sagte der Pharao zu Joseph: »In meinem Traume war es mir, ich stände am Ufer des Nils;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 18, 'da sah ich sieben wohlgenährte, schöne Kühe aus dem Strom heraufsteigen und im Riedgras weiden.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 19, 'Nach diesen sah ich sieben andere Kühe heraufsteigen, die dürr und sehr häßlich und mager am Fleisch waren; ich habe in ganz Ägypten nirgends so häßliche gesehen wie diese.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 20, 'Hierauf fraßen die mageren und häßlichen Kühe die sieben ersten wohlgenährten Kühe auf;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 21, 'aber auch als sie in ihren Leib gekommen waren, merkte man ihnen nicht an, daß sie in ihren Leib gekommen waren; nein, ihr Aussehen blieb so häßlich wie im Anfang. Da wachte ich auf.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 22, 'Dann sah ich in meinem Traume sieben Ähren, die oben an einem Halme wuchsen, volle und schöne.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 23, 'Nach diesen aber schossen sieben dürre, dünne, vom Ostwind versengte Ähren hervor;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 24, 'und die dünnen Ähren verschlangen die sieben schönen Ähren. Ich habe dies schon den Schriftkundigen mitgeteilt, aber keiner hat mir eine Erklärung geben können.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 25, 'Da sagte Joseph zum Pharao: »(Beides,) was der Pharao geträumt hat, bedeutet ein und dasselbe: Gott hat dem Pharao angekündigt, was er zu tun gedenkt.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 26, 'Die sieben schönen Kühe bedeuten sieben Jahre, und die sieben schönen Ähren bedeuten auch sieben Jahre: es ist ein und derselbe Traum.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 27, 'Auch die sieben mageren und häßlichen Kühe, die nach ihnen (aus dem Strom) heraufstiegen, sind sieben Jahre, und die sieben leeren, vom Ostwind versengten Ähren bedeuten, daß sieben Hungerjahre kommen werden.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 28, 'Das meinte ich, als ich (vorhin) zum Pharao sagte: ›Gott hat dem Pharao geoffenbart, was er zu tun gedenkt.‹');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 29, 'Wisse: es werden sieben Jahre mit großem Überfluß im ganzen Land Ägypten kommen;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 30, 'aber nach diesen werden sieben Hungerjahre eintreten, so daß der ganze Überfluß im Lande Ägypten vergessen sein wird; und die Hungersnot wird das Land so verzehren,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 31, 'daß man von dem früheren Überfluß im Lande Ägypten nichts mehr merken wird infolge der späteren Hungersnot; denn diese wird überaus schwer sein.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 32, 'Daß aber der Traum sich dem Pharao zweimal wiederholt hat, das bedeutet: die Sache ist bei Gott fest beschlossen, und Gott wird sie ohne Verzug ausführen.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 33, '»Und nun möge der Pharao sich nach einem einsichtigen und weisen Manne umsehen, den er über das Land Ägypten setze!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 34, 'und der Pharao wolle Vorsorge tragen, daß er Aufseher über das Land bestelle, und erhebe den fünften Teil des Ertrages vom Lande Ägypten während der sieben Jahre des Überflusses!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 35, 'Man sammle so den gesamten Ernteertrag jener guten Jahre, die nun kommen werden, und speichere das Getreide unter der Obhut des Pharaos als Vorrat in den Städten auf und verwahre es dort.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 36, 'Dann wird dieser Vorrat dem Lande einen Rückhalt für die sieben Hungerjahre gewähren, die im Lande Ägypten eintreten werden, und das Land wird durch die Hungersnot nicht zugrunde gerichtet werden.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 37, 'Diese Darlegung fand den Beifall des Pharaos und aller seiner Diener;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 38, 'und der Pharao sagte zu seinen Dienern: »Könnten wir wohl noch einen Mann finden, in dem der Geist Gottes wohnt wie in diesem?«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 39, 'Zu Joseph aber sagte der Pharao: »Nachdem Gott dir dieses alles geoffenbart hat, gibt es keinen, der so einsichtig und weise wäre wie du.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 40, 'Du selber sollst über mein Haus gesetzt sein, und deinen Befehlen soll mein ganzes Volk sich fügen; nur den Besitz des Thrones will ich vor dir voraushaben.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 41, 'Weiter sagte der Pharao zu Joseph: »Hiermit setze ich dich über das ganze Land Ägypten!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 42, 'Darauf zog der Pharao seinen Siegelring vom Finger und steckte ihn dem Joseph an die Hand, ließ ihn in Gewänder von Byssus kleiden und legte ihm die goldene Kette um den Hals.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 43, 'Außerdem ließ er ihn auf seinem zweiten Staatswagen fahren, und man rief vor ihm her aus: »Abrek!« So setzte er ihn über das ganze Land Ägypten.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 44, 'Sodann sagte der Pharao zu Joseph: »Ich bin der Pharao; aber ohne deine Einwilligung soll niemand die Hand oder den Fuß im ganzen Lande Ägypten rühren.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 45, 'Außerdem verlieh der Pharao dem Joseph den Titel ›Zaphenath-Paneah‹ und gab ihm Asenath, die Tochter Potipheras, des Priesters von On zur Frau. So gebot denn Joseph über das (ganze) Land Ägypten.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 46, 'Dreißig Jahre war Joseph alt, als er in den Dienst des Pharaos, des Königs von Ägypten, trat. Nachdem Joseph sich nun vom Pharao wegbegeben hatte, durchzog er das ganze Land Ägypten.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 47, 'Das Land trug aber während der sieben Jahre des Überflusses (Getreide) in Hülle und Fülle.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 48, 'Da sammelte er den ganzen Ernteertrag der sieben guten Jahre, die über Ägypten kamen, und ließ das Getreide in die Städte schaffen: nämlich in jede Stadt brachte er den Ertrag der umliegenden Felder hinein.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 49, 'So speicherte Joseph Getreide auf wie Sand am Meer, unendlich viel, bis man aufhörte, es zu messen, denn es war nicht mehr zu messen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 50, 'Noch ehe das Hungerjahr kam, wurden dem Joseph zwei Söhne geboren von Asenath, der Tochter Potipheras, des Priesters von On.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 51, 'Joseph nannte seinen erstgeborenen Sohn Manasse; »denn«, sagte er, »Gott hat mich all mein Unglück und mein ganzes Vaterhaus vergessen lassen«.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 52, 'Den zweiten aber nannte er Ephraim; »denn«, sagte er, »Gott hat mich fruchtbar werden lassen im Land meines Elends«.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 53, 'Als dann die sieben Jahre des Überflusses, der im Lande Ägypten geherrscht hatte, zu Ende waren,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 54, 'da brachen die sieben Hungerjahre an, ganz so wie Joseph es vorausgesagt hatte; und es entstand eine Hungersnot in allen Ländern; aber in ganz Ägypten hatte man Brot.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 55, 'Als dann aber auch das ganze Land Ägypten Hunger litt und das Volk zum Pharao um Brot schrie, sagte der Pharao zu allen Ägyptern: »Wendet euch an Joseph; was der euch sagen wird, das tut!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 56, 'Die Hungersnot erstreckte sich aber über die ganze Erde. Da ließ Joseph allenthalben die Kornhäuser öffnen und den Ägyptern Getreide verkaufen; und doch wurde die Hungersnot immer drückender in Ägypten.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 57, 'Da kam die ganze Erdbevölkerung zu Joseph nach Ägypten, um Getreide zu kaufen; denn auf der ganzen Erde herrschte drückende Hungersnot.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 1, 'Als nun Jakob erfuhr, daß in Ägypten Getreide zu haben sei, sagte er zu seinen Söhnen: »Was seht ihr euch lange an?«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 2, 'Dann fuhr er fort: »Wisset wohl: ich habe gehört, daß in Ägypten Getreide zu haben ist; zieht hinab und kauft uns dort Getreide, damit wir zu leben haben und nicht verhungern!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 3, 'So machten sich denn zehn von den Brüdern Josephs auf den Weg, um Getreide in Ägypten zu kaufen;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 4, 'Benjamin aber, den Vollbruder Josephs, ließ Jakob nicht mit seinen Brüdern ziehen; denn er fürchtete, es könne ihm ein Unfall zustoßen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 5, 'So kamen denn die Söhne Israels, um Getreide zu kaufen wie andere Leute, die auch hinzogen; denn es herrschte Hungersnot im Lande Kanaan.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 6, 'Nun war Joseph der Gebieter im Lande; er war es, der allem Volk im Lande das Getreide verkaufte. Als nun die Brüder Josephs zu ihm kamen, verneigten sie sich vor ihm mit dem Angesicht bis zur Erde.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 7, 'Sobald Joseph seine Brüder sah, erkannte er sie, gab sich ihnen aber nicht zu erkennen, sondern redete sie hart an und fragte sie: »Woher seid ihr gekommen?« Sie antworteten: »Aus dem Lande Kanaan, um Lebensmittel zu kaufen.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 8, 'Wiewohl Joseph nun seine Brüder erkannt hatte, erkannten sie ihn doch nicht.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 9, 'Da mußte Joseph an die Träume denken, die er einst in bezug auf sie geträumt hatte, und er sagte zu ihnen: »Kundschafter seid ihr! Ihr seid nur hergekommen, um zu erspähen, wo das Land offen steht!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 10, 'Sie antworteten ihm: »O nein, Herr! Deine Knechte sind gekommen, um Lebensmittel zu kaufen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 11, 'Wir alle sind Söhne eines Mannes, ehrliche Leute sind wir, deine Knechte sind keine Kundschafter!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 12, 'Doch er antwortete ihnen: »Nein, sondern ihr seid hergekommen, um zu erkunden, wo das Land offen steht!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 13, 'Sie erwiderten: »Wir, deine Knechte, sind zwölf Brüder, die Söhne eines Mannes im Lande Kanaan; der jüngste ist allerdings augenblicklich bei unserm Vater, und der eine ist nicht mehr da.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 14, 'Aber Joseph entgegnete ihnen: »Es ist doch so, wie ich euch gesagt habe: ihr seid Kundschafter!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 15, 'Daran sollt ihr geprüft werden: Beim Leben des Pharaos: ihr sollt von hier nicht weggehen, wenn euer jüngster Bruder nicht hierher kommt.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 16, 'Schickt einen von euch hin, daß er euren Bruder hole! Ihr anderen aber bleibt so lange gefangen, bis eure Aussagen geprüft sind, ob ihr mit der Wahrheit umgeht oder nicht! So wahr der Pharao lebt: ihr seid Kundschafter!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 17, 'Hierauf ließ er sie beisammen drei Tage lang in Gewahrsam nehmen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 18, 'Am dritten Tage aber sagte Joseph zu ihnen: »Wollt ihr am Leben bleiben, so müßt ihr es folgendermaßen machen; denn ich bin ein gottesfürchtiger Mann.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 19, 'Wenn ihr ehrliche Leute seid, so soll nur einer von euch Brüdern als Gefangener hier in eurem bisherigen Gewahrsam zurückbleiben; ihr anderen aber mögt hinziehen und Getreide für den Bedarf eurer Familien mitnehmen!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 20, 'Aber euren jüngsten Bruder müßt ihr zu mir herbringen; dann sollen eure Aussagen als wahr gelten, und ihr braucht nicht zu sterben!« Sie gingen darauf ein,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 21, 'sagten aber einer zum andern: »Wahrlich, das haben wir an unserm Bruder verschuldet! Denn wir sahen seine Seelenangst, als er uns anflehte, aber wir hörten nicht auf ihn; deshalb ist jetzt dieses Unglück über uns gekommen!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 22, 'Da antwortete ihnen Ruben: »Habe ich euch damals nicht gesagt: ›Versündigt euch nicht an dem Knaben!‹, aber ihr wolltet nicht hören; so wird denn jetzt auch sein Blut von uns gefordert!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 23, 'Sie wußten aber nicht, daß Joseph sie verstand; denn er verhandelte mit ihnen durch einen Dolmetscher.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 24, 'Da wandte er sich von ihnen ab und weinte. Als er dann wieder zu ihnen zurückgekehrt war und mit ihnen gesprochen hatte, ließ er Simeon aus ihrer Mitte ergreifen und vor ihren Augen in Fesseln legen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 25, 'Dann gab Joseph Befehl, man solle ihre Säcke mit Getreide füllen, ihr Geld aber einem jeden wieder in seinen Sack legen und ihnen auch Zehrung für den Weg mitgeben. Als das geschehen war,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 26, 'luden sie ihr Getreide auf ihre Esel und zogen von dannen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 27, 'Als aber einer von ihnen in der Herberge seinen Sack öffnete, um seinem Esel Futter zu geben, bemerkte er sein Geld, das in seinem Sack obenauf lag.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 28, 'Da sagte er zu seinen Brüdern: »Mein Geld ist wieder da! Denkt euch nur: es liegt hier in meinem Sack!« Da entfiel ihnen der Mut; sie sahen einander erschrocken an und riefen aus: »Was hat Gott uns da angetan!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 29, 'Als sie hierauf zu ihrem Vater Jakob ins Land Kanaan zurückkamen, erzählten sie ihm alles, was sie erlebt hatten, mit den Worten:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 30, '»Der Mann, der im Lande Herr ist, hat uns hart angelassen und uns wie Leute behandelt, die das Land auskundschaften wollten;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 31, 'und als wir zu ihm sagten: ›Wir sind ehrliche Leute, wir sind nie Kundschafter gewesen;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 32, 'zwölf Brüder sind wir, die Söhne unsers Vaters; der eine ist nicht mehr da, und der jüngste befindet sich zur Zeit bei unserm Vater im Lande Kanaan‹, –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 33, 'da erwiderte uns der Mann, der im Lande Herr ist: ›Daran will ich erkennen, ob ihr ehrliche Leute seid: laßt einen von euch Brüdern bei mir zurück und nehmt den Bedarf für eure hungernden Familien mit und kehrt heim;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 34, 'bringt dann aber euren jüngsten Bruder zu mir! Daran werde ich erkennen, daß ihr keine Kundschafter, sondern ehrliche Leute seid; dann will ich euch auch euren Bruder zurückgeben, und ihr könnt im Lande frei verkehren.‹«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 35, 'Als sie dann ihre Säcke leerten, fand jeder seinen Geldbeutel in seinem Sack; und als sie samt ihrem Vater sahen, daß es ihre Beutel waren, erschraken sie.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 36, 'Da sagte ihr Vater Jakob zu ihnen: »Ihr beraubt mich meiner Kinder! Joseph ist nicht mehr da, Simeon ist nicht mehr da, und nun sollt ihr Benjamin holen! Über mich ist all dieses Leid hereingebrochen!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 37, 'Da antwortete Ruben seinem Vater: »Meine beiden Söhne magst du töten, wenn ich ihn nicht zu dir zurückbringe! Vertraue ihn mir an: ich bringe ihn zu dir zurück!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 38, 'Doch Jakob entgegnete: »Mein Sohn soll nicht mit euch hinabziehen! Sein rechter Bruder ist tot, und er ist allein übriggeblieben; wenn ihm ein Unfall auf dem Wege zustieße, den ihr ziehen müßt, so würdet ihr mein graues Haar mit Herzeleid in die Unterwelt bringen!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 1, 'Die Hungersnot lag aber schwer auf dem Lande.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 2, 'Als nun das Getreide, das sie aus Ägypten geholt hatten, vollständig aufgezehrt war, sagte ihr Vater zu ihnen: »Zieht noch einmal hin und kauft uns etwas Getreide zur Nahrung!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 3, 'Da antwortete ihm Juda: »Der Mann hat uns eindringlich gewarnt mit den Worten: ›Ihr dürft mir nicht mehr vor die Augen treten, wenn euer Bruder nicht bei euch ist!‹');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 4, 'Willst du uns also unsern Bruder mitgeben, dann wollen wir hinabziehen und Lebensmittel für dich kaufen;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 5, 'willst du ihn aber nicht mitgehen lassen, so ziehen wir nicht hinab; denn der Mann hat uns gesagt: ›Ihr dürft mir nicht vor die Augen treten, wenn euer Bruder nicht bei euch ist!‹«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 6, 'Da sagte Israel: »Warum habt ihr mir das zuleide getan, dem Manne mitzuteilen, daß ihr noch einen Bruder habt?«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 7, 'Sie antworteten: »Der Mann erkundigte sich genau nach uns und unserer Familie und fragte: ›Lebt euer Vater noch? Habt ihr noch einen Bruder?‹ Da haben wir ihm auf seine Fragen Auskunft gegeben. Konnten wir denn wissen, daß er verlangen würde: ›Bringt euren Bruder her‹?«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 8, 'Juda aber sagte zu seinem Vater Israel: »Laß den Knaben mit mir gehen; dann wollen wir uns auf den Weg machen und hinziehen, damit wir am Leben bleiben und nicht verhungern, weder wir selbst noch du und unsere Familien!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 9, 'Ich will Bürge für ihn sein; von meiner Hand sollst du ihn zurückfordern! Wenn ich ihn nicht wieder zu dir bringe und ihn dir nicht vor die Augen stelle, so will ich Zeit meines Lebens schuldbeladen vor dir dastehen!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 10, 'Ja, hätten wir nicht so lange gezögert, gewiß, wir wären jetzt schon zweimal wieder zurückgekehrt.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 11, 'Da erwiderte ihnen ihr Vater Israel: »Wenn es denn sein muß, so macht es folgendermaßen: Nehmt von den besten Erzeugnissen des Landes etwas in euren Säcken mit und überbringt es dem Manne als Geschenk: etwas Mastixbalsam und etwas Honig, Gewürzkräuter und Ladanum, Pistaziennüsse und Mandeln!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 12, 'Außerdem nehmt an Geld den doppelten Betrag mit! Denn auch das Geld, das sich oben in euren Säcken wiedergefunden hat, müßt ihr wieder mit euch nehmen: vielleicht liegt ein Versehen vor.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 13, 'Auch euren Bruder nehmt mit und macht euch auf den Weg und zieht wieder hin zu dem Manne!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 14, 'Der allmächtige Gott aber lasse euch Erbarmen bei dem Manne finden, daß er euren andern Bruder wieder mit euch ziehen läßt und auch Benjamin! Ich aber – wie ich einstmals kinderlos gewesen bin, so habe ich auch jetzt wieder keine Kinder!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 15, 'So nahmen denn die Männer das betreffende Geschenk und den doppelten Betrag an Geld mit sich, dazu auch den Benjamin, machten sich auf den Weg, zogen nach Ägypten hinab und traten vor Joseph.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 16, 'Als nun Joseph den Benjamin bei ihnen sah, befahl er seinem Hausverwalter: »Führe die Männer ins Haus hinein, laß ein Schlachttier schlachten und richte zu, denn die Männer sollen zu Mittag bei mir speisen.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 17, 'Der Mann tat, wie Joseph ihm befohlen hatte, und führte die Männer in Josephs Haus.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 18, 'Da fürchteten sie sich, daß sie in das Haus Josephs geführt wurden, und dachten: »Wegen des Geldes, das vorigesmal wieder in unsere Säcke geraten ist, werden wir hineingeführt: man will sich auf uns stürzen, uns überwältigen und uns zu Sklaven machen samt unsern Eseln.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 19, 'Darum traten sie an den Hausverwalter Josephs heran und redeten ihn noch am Eingang des Hauses so an:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 20, '»Bitte, mein Herr! Wir sind schon einmal hergekommen, um Lebensmittel zu kaufen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 21, 'Als wir dann aber in die Herberge gekommen waren und unsere Säcke öffneten, da fand sich das Geld eines jeden oben in seinem Sack, unser Geld in vollem Betrage. Darum haben wir es jetzt wieder mitgebracht,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 22, 'haben aber auch noch anderes Geld bei uns, um Lebensmittel zu kaufen. Wir wissen nicht, wer uns damals unser Geld in unsere Säcke gelegt hat.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 23, 'Da antwortete jener: »Seid unbesorgt, ihr habt nichts zu fürchten! Euer Gott und eures Vaters Gott hat euch da heimlich einen Schatz in eure Säcke gelegt; euer Geld ist richtig an mich gekommen.« Dann führte er Simeon zu ihnen heraus.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 24, 'Hierauf ließ er die Männer in das Haus Josephs eintreten, gab ihnen Wasser zum Füßewaschen und ließ ihren Eseln Futter geben.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 25, 'Sie legten aber das Geschenk zurecht und warteten dann, bis Joseph zur Mittagszeit kommen würde; sie hatten nämlich gehört, daß sie dort speisen sollten.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 26, 'Als nun Joseph nach Hause gekommen war, brachten sie ihm das Geschenk, das sie bei sich hatten, ins Zimmer hinein und verneigten sich vor ihm bis zur Erde.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 27, 'Er begrüßte sie freundlich und fragte sie: »Geht es eurem alten Vater wohl, von dem ihr mir erzählt habt? Ist er noch am Leben?«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 28, 'Sie antworteten: »Deinem Knecht, unserm Vater, geht es wohl; ja, er ist noch am Leben.« Dabei verbeugten sie sich wiederholt tief.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 29, 'Als er dann hinblickte und Benjamin, seinen Vollbruder, den Sohn seiner eigenen Mutter, sah, fragte er: »Ist dies euer jüngster Bruder, von dem ihr mir erzählt habt?« Dann fügte er hinzu: »Gott sei dir gnädig, mein Sohn!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 30, 'Hierauf aber brach Joseph schnell ab, denn sein Gefühl überwältigte ihn beim Anblick seines Bruders, so daß er weinen mußte; er ging deshalb ins Innengemach und weinte sich dort aus.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 31, 'Dann wusch er sich das Gesicht und kam wieder heraus, nahm sich zusammen und befahl: »Tragt das Essen auf!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 32, 'Da trug man für ihn besonders auf und für sie besonders und auch für die Ägypter, die bei ihm speisten, besonders; denn die Ägypter dürfen nicht mit den Hebräern zusammen speisen, weil das für die Ägypter eine Verunreinigung sein würde.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 33, 'Sie hatten aber ihre Plätze nach seiner Anweisung, vom Ältesten bis zum Jüngsten, genau nach ihrem Alter; darüber sahen sie sich einander verwundert an.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 34, 'Hierauf ließ er von den vor ihm stehenden Gerichten Anteile zu ihnen hintragen; es war aber dessen, was man Benjamin vorlegte, fünfmal so viel, als was man allen anderen vorlegte. Und sie tranken mit ihm und wurden guter Dinge.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 1, 'Hierauf befahl er (Joseph) seinem Hausverwalter: »Fülle den Männern ihre Säcke mit Getreide, soviel sie fortschaffen können, und lege einem jeden sein Geld (wieder) oben in seinen Sack!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 2, 'Meinen Becher aber, den silbernen Becher, sollst du dem Jüngsten oben in seinen Sack legen samt dem Gelde für sein Getreide!« Jener tat nach dem von Joseph ihm erteilten Befehl.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 3, 'Am andern Morgen, als es hell wurde, ließ man die Männer mit ihren Eseln ziehen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 4, 'Als sie aber kaum zur Stadt hinausgezogen und noch nicht weit gekommen waren, befahl Joseph seinem Hausverwalter: »Auf! Eile den Männern nach! Und hast du sie eingeholt, so sage zu ihnen: ›Warum habt ihr Gutes mit Bösem vergolten?');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 5, 'Warum habt ihr den silbernen Becher gestohlen? Es ist gerade der Becher, aus dem mein Herr trinkt und mittels dessen er auch wahrzusagen pflegt. Ihr habt da schlecht gehandelt!‹«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 6, 'Als er sie nun eingeholt hatte, sagte er diese Worte zu ihnen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 7, 'Da antworteten sie ihm: »O Herr, wie kannst du so etwas sagen? Es liegt deinen Knechten fern, so etwas zu tun!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 8, 'Wir haben dir ja doch auch das Geld, das wir oben in unsern Säcken gefunden hatten, aus dem Lande Kanaan zurückgebracht: wie sollten wir da jetzt aus dem Hause deines Herrn Silber oder Gold gestohlen haben?');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 9, 'Bei wem von deinen Knechten (der Becher) gefunden wird, der soll sterben, und auch wir anderen wollen Sklaven meines Herrn werden!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 10, 'Er antwortete: »Gut! Es sei, wie ihr gesagt habt: bei wem er gefunden wird, der soll mein Sklave sein; ihr anderen aber sollt frei ausgehen!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 11, 'Da setzten sie jeder seinen Sack schnell auf die Erde nieder, und jeder öffnete seinen Sack.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 12, 'Er aber fing an zu suchen; beim Ältesten fing er an, und beim Jüngsten hörte er auf: da fand sich der Becher im Sack Benjamins.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 13, 'Da zerrissen sie ihre Kleider; ein jeder belud seinen Esel wieder, und sie kehrten in die Stadt zurück.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 14, 'Als nun Juda und seine Brüder in das Haus Josephs gekommen waren – dieser war aber dort noch anwesend –, warfen sie sich vor ihm auf die Erde nieder.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 15, 'Da sagte Joseph zu ihnen: »Was für eine Tat habt ihr da begangen! Wußtet ihr nicht, daß ein Mann wie ich sich auf Zeichendeutung versteht?«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 16, 'Da antwortete Juda: »Was sollen wir zu meinem Herrn sagen? Was sollen wir reden und wie uns rechtfertigen? Gott hat die Schuld deiner Knechte ans Licht gebracht: wir (alle) gehören jetzt meinem Herrn als Sklaven, wir ebensogut wie der, in dessen Besitz der Becher gefunden worden ist.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 17, 'Joseph aber antwortete: »Fern sei es von mir, so zu verfahren! Nur der, in dessen Besitz der Becher sich gefunden hat, soll mein Sklave werden; ihr anderen aber mögt ungehindert zu eurem Vater zurückkehren!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 18, 'Da trat Juda an ihn heran und sagte: »Bitte, mein Herr! Laß doch deinen Knecht ein Wort an dich richten, mein Herr, ohne daß dein Zorn gegen deinen Knecht entbrennt, obgleich du so hoch stehst wie der Pharao!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 19, 'Mein Herr hat vordem seine Knechte gefragt: ›Habt ihr noch einen Vater oder einen Bruder?‹');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 20, 'Da antworteten wir meinem Herrn: ›Wir haben noch einen alten Vater und einen noch jungen Bruder, der ihm im Alter geboren ist; dessen rechter Bruder ist tot, und so ist er ihm allein von seiner Mutter übriggeblieben und ist deshalb der Liebling seines Vaters.‹');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 21, 'Da befahlst du deinen Knechten: ›Bringt ihn zu mir her, ich will ihn mit eigenen Augen zu sehen bekommen!‹');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 22, 'Da antworteten wir meinem Herrn: ›Der Knabe kann seinen Vater nicht verlassen; denn wenn er seinen Vater verließe, so würde dieser sterben.‹');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 23, 'Aber du antwortetest deinen Knechten: ›Kommt euer jüngster Bruder nicht mit euch her, so dürft ihr mir nicht wieder vor die Augen treten!‹');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 24, 'Als wir dann zu deinem Knecht, meinem Vater, zurückgekehrt waren, teilten wir ihm die Worte meines Herrn mit;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 25, 'und als später unser Vater sagte: ›Zieht wieder hin und kauft uns etwas Getreide!‹,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 26, 'da antworteten wir: ›Wir können nicht hinabziehen; nur wenn unser jüngster Bruder uns begleitet, wollen wir hinabziehen; denn wir dürfen uns vor dem Manne nicht sehen lassen, wenn unser jüngster Bruder nicht bei uns ist.‹');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 27, 'Da erwiderte uns dein Knecht, mein Vater: ›Ihr wißt selbst, daß meine Frau mir nur zwei Söhne geboren hat;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 28, 'der eine ist von mir weggegangen, und ich mußte mir sagen: Sicherlich hat ihn ein Tier zerrissen!, und ich habe ihn bis heute nicht wiedergesehen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 29, 'Wenn ihr mir nun auch diesen noch wegnehmt und ihm ein Unglück zustößt, so werdet ihr mein graues Haar mit Jammer in die Unterwelt hinabbringen!‹');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 30, 'Käme ich jetzt also zu deinem Knecht, meinem Vater, heim und der Knabe wäre nicht bei uns, an dem doch sein ganzes Herz hängt,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 31, 'und müßte er sehen, daß der Knabe nicht da ist, so würde er sterben, und deine Knechte hätten wirklich das graue Haar deines Knechtes, unsers Vaters, mit Herzeleid in die Unterwelt hinabgebracht!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 32, 'Weil nun dein Knecht sich bei meinem Vater für den Knaben verbürgt und gelobt hat: ›Wenn ich ihn dir nicht zurückbringe, so will ich zeit meines Lebens vor meinem Vater schuldbeladen dastehen!‹,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 33, 'so laß doch jetzt deinen Knecht anstatt des Knaben als Sklaven meines Herrn hierbleiben, den Knaben aber laß mit seinen Brüdern heimziehen!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 34, 'Denn wie könnte ich zu meinem Vater zurückkehren, ohne daß der Knabe bei mir wäre? Ich könnte den Jammer nicht mitansehen, der meinen Vater träfe!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 1, 'Da vermochte Joseph nicht länger an sich zu halten vor allen, die um ihn her standen, sondern er rief aus: »Laßt jedermann von mir weg hinausgehen!« So war denn niemand zugegen, als Joseph sich seinen Brüdern zu erkennen gab.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 2, 'Er brach aber in ein so lautes Weinen aus, daß die Ägypter es hörten und auch das Haus des Pharaos Kunde davon erhielt.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 3, 'Joseph sagte aber zu seinen Brüdern: »Ich bin Joseph! Lebt mein Vater noch?« Seine Brüder vermochten aber nicht, ihm zu antworten: so bestürzt standen sie vor ihm.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 4, 'Da sagte er zu seinen Brüdern: »Tretet doch nahe an mich heran!« Als sie nun näher getreten waren, sagte er: »Ich bin euer Bruder Joseph, den ihr nach Ägypten verkauft habt!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 5, 'Nun beunruhigt euch aber nicht und macht euch keine Vorwürfe darüber, daß ihr mich hierher verkauft habt! Denn um uns alle am Leben zu erhalten, hat Gott mich euch vorausgesandt.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 6, '»Denn jetzt herrscht die Hungersnot erst zwei Jahre im Lande, und fünf Jahre stehen noch bevor, in denen kein Pflügen und kein Ernten stattfinden wird.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 7, 'Darum hat Gott mich euch vorausgesandt, um das Fortbestehen eures Geschlechts auf Erden zu sichern und um euch, eine große Schar von Erretteten, am Leben zu erhalten.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 8, 'So habt also nicht ihr mich hierher gebracht, sondern Gott; der hat mich dem Pharao zum Vater gemacht und zum Herrn über sein ganzes Haus und zum Gebieter im ganzen Lande Ägypten.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 9, 'Zieht nun eilends zu meinem Vater hinauf und meldet ihm: ›So läßt dir dein Sohn Joseph sagen: Gott hat mich zum Gebieter von ganz Ägypten gemacht: komm zu mir herab, säume nicht!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 10, 'Du sollst im Lande Gosen wohnen und in meiner Nähe sein, du, deine Kinder und Kindeskinder samt deinem Kleinvieh und deinen Rindern und deinem ganzen Hab und Gut.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 11, 'Ich will dich daselbst versorgen, denn noch fünf Jahre wird die Hungersnot dauern, damit du nicht verarmst, du und dein Haus und alles, was du besitzest.‹');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 12, 'Ihr seht es ja mit eigenen Augen, und auch mein Bruder Benjamin sieht es mit eigenen Augen, daß ich persönlich es bin, der zu euch redet.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 13, 'Berichtet also meinem Vater alle die hohen Ehren, die ich in Ägypten habe, und alles, was ihr gesehen habt, und bringt meinen Vater eilends hierher!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 14, 'Darauf fiel er seinem Bruder Benjamin um den Hals und weinte, und auch Benjamin weinte an seinem Halse;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 15, 'dann küßte er alle seine Brüder und umarmte sie unter Tränen; nun erst vermochten auch seine Brüder mit ihm zu reden.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 16, 'Als nun die Kunde von der Ankunft der Brüder Josephs in den Palast des Pharaos drang, war sie dem Pharao und seinen Dienern angenehm.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 17, 'Daher sagte der Pharao zu Joseph: »Sage deinen Brüdern: ›Tut also: beladet eure Lasttiere und zieht heim ins Land Kanaan,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 18, 'holt euren Vater und eure Familien und kommt zu mir! Ich will euch den besten Teil des Landes Ägypten geben, damit ihr das Fett des Landes genießen könnt.‹');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 19, 'Du bist ermächtigt (ihnen zu sagen): ›Tut also: nehmt euch aus Ägypten Wagen mit für eure Kinder und Frauen, laßt auch euren Vater aufsteigen und kommt hierher!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 20, 'Laßt es euch um euren Hausrat nicht leid sein! Denn das Beste vom ganzen Land Ägypten soll euch zuteil werden.‹«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 21, 'So taten denn die Söhne Israels also, und Joseph gab ihnen Wagen nach dem Befehl des Pharaos und außerdem Zehrung für die Reise.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 22, 'Ihnen allen schenkte er, einem jeden, einen Festtagsanzug; dem Benjamin aber schenkte er dreihundert Silberstücke und fünf Festtagsanzüge.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 23, 'Seinem Vater aber sandte er dementsprechend: zehn Esel, die mit den besten Erzeugnissen Ägyptens beladen waren, und zehn Eselinnen, die Getreide, Brot und Reisekost für seinen Vater trugen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 24, 'Alsdann entließ er seine Brüder, und sie zogen ab, nachdem er sie noch ermahnt hatte: »Erzürnt euch nicht unterwegs!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 25, 'So zogen sie denn aus Ägypten ab und kamen ins Land Kanaan zu ihrem Vater Jakob,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 26, 'dem sie berichteten: »Joseph lebt noch und ist Gebieter über das ganze Land Ägypten!« Aber sein Herz blieb kalt dabei, denn er glaubte ihnen nicht.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 27, 'Als sie ihm aber alles erzählten, was Joseph ihnen aufgetragen hatte, und als er die Wagen sah, die Joseph geschickt hatte, um ihn zu holen, da kam wieder Leben in den Geist ihres Vaters Jakob,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 28, 'so daß er ausrief: »Genug! Mein Sohn Joseph lebt noch! Ich will hinziehen und ihn noch einmal sehen, ehe ich sterbe!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 1, 'So brach denn Israel mit allen seinen Angehörigen auf, und als er nach Beerseba gekommen war, brachte er dort dem Gott seines Vaters Isaak Schlachtopfer dar.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 2, 'Da redete Gott mit Israel nachts in einem Gesicht und sagte: »Jakob, Jakob!« Er antwortete: »Hier bin ich!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 3, 'Darauf sagte Gott: »Ich bin Gott, der Gott deines Vaters! Fürchte dich nicht, nach Ägypten hinabzuziehen; denn ich will dich dort zu einem großen Volk machen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 4, 'Ich selbst will mit dir nach Ägypten hinabziehen, und ich selbst will dich (einst) auch wieder zurückführen, und Josephs Hand soll dir die Augen zudrücken.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 5, 'Da brach Jakob von Beerseba auf, und seine Söhne ließen ihren Vater Jakob nebst ihren Kindern und ihren Frauen auf den Wagen fahren, die der Pharao geschickt hatte, um ihn zu holen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 6, 'Sie nahmen auch ihr Vieh und ihre Habe mit, die sie im Lande Kanaan erworben hatten, und kamen so nach Ägypten, Jakob mit seiner gesamten Nachkommenschaft:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 7, 'seine Söhne und Enkel, seine Töchter und Enkelinnen, überhaupt seine ganze Nachkommenschaft brachte er mit sich nach Ägypten.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 8, 'Dies aber sind die Namen der Nachkommen Israels, die nach Ägypten kamen: Jakob und seine Söhne. Der erstgeborene Sohn Jakobs war Ruben;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 9, 'und die Söhne Rubens waren Hanoch, Pallu, Hezron und Karmi.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 10, 'Die Söhne Simeons waren Jemuel, Jamin, Ohad, Jachin, Zohar und Saul, der Sohn der Kanaanäerin.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 11, 'Die Söhne Levis waren Gerson, Kehath und Merari.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 12, 'Die Söhne Judas waren Ger, Onan, Sela, Perez und Serah; aber Ger und Onan waren schon im Lande Kanaan gestorben, und die Söhne des Perez waren Hezron und Hamul.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 13, 'Die Söhne Issaschars waren Thola, Puwwa, Job und Simron.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 14, 'Die Söhne Sebulons waren Sered, Elon und Jahleel.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 15, 'Dies sind die Söhne der Lea, die sie dem Jakob in Nord-Mesopotamien geboren hatte, dazu seine Tochter Dina, insgesamt dreiunddreißig Söhne und Töchter. –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 16, 'Die Söhne Gads aber waren Ziphjon und Haggi, Suni und Ezbon, Heri, Arodi und Areli.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 17, 'Die Söhne Assers waren Jimna, Jiswa, Jiswi, Beria und ihre Schwester Serah; und die Söhne Berias waren Heber und Malkiel.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 18, 'Dies sind die Söhne der Silpa, die Laban seiner Tochter Lea (als Leibmagd) gegeben hatte; diese hatte sie dem Jakob geboren, zusammen sechzehn Seelen. –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 19, 'Die Söhne der Rahel, der Frau Jakobs, waren Joseph und Benjamin.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 20, 'Dem Joseph aber waren in Ägypten Manasse und Ephraim geboren, die ihm Asenath, die Tochter Potipheras, des Priesters von On, geboren hatte.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 21, 'Die Söhne Benjamins waren Bela, Becher und Asbel, Gera und Naaman, Ehi und Ros, Muppim und Huppim und Ard.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 22, 'Dies sind die Söhne der Rahel, die dem Jakob geboren waren, insgesamt vierzehn Seelen. –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 23, 'Die Söhne Dans aber waren: Husim;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 24, 'und die Söhne Naphthalis: Jahzeel, Guni, Jezer und Sillem.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 25, 'Dies sind die Söhne der Bilha, die Laban seiner Tochter Rahel (als Leibmagd) gegeben hatte; diese hatte sie dem Jakob geboren, insgesamt sieben Seelen. –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 26, 'Die Gesamtzahl der Seelen, die mit Jakob nach Ägypten kamen, seine leiblichen Nachkommen, ungerechnet die Frauen der Söhne Jakobs, betrug sechsundsechzig.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 27, 'Die Söhne Josephs aber, die ihm in Ägypten geboren wurden, waren zwei Seelen. Daher betrug die Gesamtzahl der Seelen des Hauses Jakobs, die nach Ägypten kamen, siebzig.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 28, 'Jakob hatte aber Juda zu Joseph vorausgesandt, damit dieser ihm die Landschaft Gosen im voraus anweisen lasse. Als sie nun im Lande Gosen angekommen waren,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 29, 'ließ Joseph seinen Wagen anspannen und fuhr seinem Vater Israel nach Gosen entgegen; und als er vor ihm erschien, fiel er ihm um den Hals und weinte lange an seinem Halse.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 30, 'Israel aber sagte zu Joseph: »Nun will ich gern sterben, nachdem ich dein Angesicht gesehen habe (und weiß), daß du noch am Leben bist.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 31, 'Hierauf sagte Joseph zu seinen Brüdern und zu den anderen Angehörigen seines Vaters: »Ich will jetzt hinfahren und dem Pharao Bericht erstatten und ihm melden: ›Meine Brüder sowie die Angehörigen meines Vaters, die bisher im Lande Kanaan gewohnt haben, sind zu mir gekommen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 32, 'Diese Leute sind Hirten von Kleinvieh – sie sind von jeher Viehzüchter gewesen –, und sie haben ihr Kleinvieh, ihre Rinder und ihren gesamten Besitz mitgebracht.‹');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 33, 'Wenn euch dann der Pharao rufen läßt und euch fragt: ›Was ist euer Gewerbe?‹,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 34, 'so antwortet: ›Deine Knechte sind von Jugend auf bis jetzt Viehzüchter gewesen, wir wie auch schon unsere Väter‹, – damit ihr im Lande Gosen wohnen dürft; denn alle Hirten von Kleinvieh sind den Ägyptern ein Greuel.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 1, 'So ging denn Joseph hin und erstattete dem Pharao Bericht mit den Worten: »Mein Vater und meine Brüder sind mit ihrem Kleinvieh, ihren Rindern und ihrem gesamten Besitz aus dem Lande Kanaan angekommen und befinden sich jetzt im Lande Gosen.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 2, 'Er hatte aber aus der Gesamtzahl seiner Brüder fünf Männer mitgebracht, die er dem Pharao vorstellte.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 3, 'Als nun der Pharao die Brüder Josephs fragte: »Was ist euer Gewerbe?«, antworteten sie dem Pharao: »Deine Knechte sind Hirten von Kleinvieh, wir wie auch schon unsere Väter.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 4, 'Weiter sagten sie zum Pharao: »Wir sind hergekommen, um eine Zeitlang als Fremdlinge hier im Lande zu wohnen, weil deine Knechte keine Weide mehr für ihr Kleinvieh haben: so schwer liegt die Hungersnot auf dem Lande Kanaan. Laß nun doch deine Knechte im Lande Gosen wohnen!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 5, 'Da sagte der Pharao zu Joseph: »Dein Vater und deine Brüder sind zu dir gekommen:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 6, 'das Land Ägypten steht dir zur Verfügung; laß deinen Vater und deine Brüder im besten Teil des Landes wohnen! Sie dürfen im Lande Gosen wohnen; und wenn du siehst, daß tüchtige Leute unter ihnen sind, so mache sie zu Oberhirten über meine eigenen Herden!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 7, 'Hierauf ließ Joseph auch seinen Vater Jakob eintreten und stellte ihn dem Pharao vor; Jakob aber begrüßte den Pharao mit einem Segenswunsch.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 8, 'Da sagte der Pharao zu Jakob: »Wie groß ist die Zahl deiner Lebensjahre?«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 9, 'Jakob antwortete dem Pharao: »Die Zahl der Jahre meiner Wanderschaft beträgt hundertunddreißig Jahre; gering an Zahl und mühselig sind die Tage meiner Lebensjahre gewesen und reichen nicht an die Tage der Lebensjahre meiner Väter in der Zeit ihrer Wanderschaft heran.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 10, 'Hierauf entfernte sich Jakob vom Pharao mit einem Segenswunsch für ihn.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 11, 'Joseph aber wies seinem Vater und seinen Brüdern Wohnsitze an und verlieh ihnen eigenen Grundbesitz in Ägypten, im besten Teile des Landes, nämlich in der Landschaft Ramses, wie der Pharao befohlen hatte.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 12, 'Und Joseph versorgte seinen Vater, seine Brüder und alle Angehörigen seines Vaters mit Brotkorn, einen jeden nach der Zahl seiner Familienglieder.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 13, 'Es gab aber kein Brotkorn im ganzen Lande; denn die Hungersnot war überaus drückend, so daß Ägypten ebenso wie das Land Kanaan infolge der Hungersnot am Verschmachten war.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 14, 'So brachte denn Joseph (schließlich) alles Geld, das sich im Lande Ägypten und in Kanaan vorfand, in seiner Hand zusammen für das Brotkorn, das man kaufen mußte; und Joseph lieferte das Geld an das Haus des Pharaos ab.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 15, 'Als dann im Lande Ägypten und in Kanaan kein Geld mehr vorhanden war, kamen alle Ägypter zu Joseph und sagten: »Schaffe uns Brot! Warum sollen wir vor deinen Augen sterben? Denn das Geld ist zu Ende gegangen!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 16, 'Joseph antwortete: »Bringt euer Vieh her, so will ich euch Brotkorn als Entgelt für euer Vieh geben, wenn ihr kein Geld mehr habt.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 17, 'Da brachten sie ihr Vieh zu Joseph, und dieser gab ihnen Brotkorn als Entgelt für die Pferde, für die Schaf- und Rinderherden und für die Esel; so versorgte er sie in jenem Jahr mit Brotkorn um den Preis ihres gesamten Viehs.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 18, 'Als nun dieses Jahr zu Ende war, kamen sie im nächsten Jahre wieder zu ihm und sagten: »Wir können es unserm Herrn nicht verhehlen, daß das Geld zu Ende ist und, weil auch unser Bestand an Vieh schon an unsern Herrn übergegangen ist, nichts mehr zur Verfügung unseres Herrn übriggeblieben ist als unser Leib und unsere Äcker.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 19, 'Warum sollen wir vor deinen Augen zugrunde gehen, wir samt unserm Landbesitz? Kaufe uns und unsern Landbesitz um Brotkorn, so wollen wir samt unserm Landbesitz dem Pharao leibeigen sein; aber gib uns Saatkorn, damit wir am Leben bleiben und nicht verhungern und die Felder nicht zur Wüste werden!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 20, 'So kaufte denn Joseph alles Ackerland der Ägypter für den Pharao auf; denn die Ägypter verkauften ein jeder seine Felder, weil die Hungersnot schwer auf ihnen lastete; und so wurde das Land Eigentum des Pharaos.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 21, 'Und was die Bevölkerung betrifft, so machte er sie leibeigen von einem Ende des ägyptischen Gebiets bis zum andern.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 22, 'Nur die Ländereien der Priester kaufte er nicht an; denn die Priester bezogen ein festes Einkommen von seiten des Pharaos und lebten von ihrem festen Einkommen, das der Pharao ihnen angewiesen hatte; deshalb brauchten sie ihre Ländereien nicht zu verkaufen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 23, 'Joseph aber sagte zum Volk: »Ich habe nunmehr euch und eure Äcker für den Pharao angekauft; hier habt ihr Saatkorn zum Besäen der Äcker!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 24, 'Aber von dem Ertrage müßt ihr ein Fünftel an den Pharao abgeben; die übrigen vier Fünftel dagegen sollt ihr behalten zur Aussaat für die Felder sowie zur Nahrung für euch und euer Gesinde und zur Ernährung eurer Familien.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 25, 'Da antworteten sie: »Du hast uns am Leben erhalten! Möchten wir nur Gnade finden vor den Augen unsers Herrn, so wollen wir gern dem Pharao leibeigen sein!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 26, 'So machte Joseph es zu einer gesetzlichen Verpflichtung, die bis auf diesen Tag für den Grundbesitz der Ägypter besteht, daß dem Pharao der fünfte Teil des Ernteertrages gehört; nur die Ländereien der Priester allein kamen nicht in den Besitz des Pharaos.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 27, 'So siedelten sich denn die Israeliten in Ägypten, in der Landschaft Gosen, an; sie setzten sich darin fest und mehrten sich so, daß sie überaus zahlreich wurden.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 28, 'Jakob aber lebte in Ägypten noch siebzehn Jahre, so daß seine ganze Lebensdauer 147 Jahre betrug.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 29, 'Als dann die Zeit herankam, daß er sterben sollte, ließ er seinen Sohn Joseph rufen und sagte zu ihm: »Wenn ich dir etwas gelte, so lege deine Hand unter meine Hüfte und erweise mir die Liebe und Treue, mich nicht in Ägypten zu begraben,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 30, 'sondern ich möchte bei meinen Vätern ruhen! Darum bringe mich aus Ägypten weg und begrabe mich in ihrer Ruhestätte!« Da antwortete er: »Ja, ich werde nach deinem Wunsche tun.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 31, 'Da sagte er: »Schwöre es mir!«, und er schwur ihm. Israel aber beugte sich anbetend auf das Kopfende des Bettes hin.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 48, 1, 'Nach diesen Begebenheiten meldete man dem Joseph: »Wisse, dein Vater ist erkrankt«; da nahm er seine beiden Söhne Manasse und Ephraim mit sich.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 48, 2, 'Als man nun dem Jakob mitteilte: »Dein Sohn Joseph kommt zu dir«, da machte Israel sich stark, setzte sich im Bett aufrecht hin');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 48, 3, 'und sagte dann zu Joseph: »Der allmächtige Gott ist mir einst zu Lus im Lande Kanaan erschienen und hat mich gesegnet');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 48, 4, 'mit den Worten: ›Ich will dich fruchtbar machen und mehren und dich zu einer Menge von Stämmen werden lassen und will dieses Land deiner Nachkommenschaft nach dir zu ewigem Besitz geben.‹');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 48, 5, 'Und nun sollen deine beiden Söhne, die dir im Lande Ägypten geboren worden sind, ehe ich zu dir nach Ägypten kam, mir gehören: Ephraim und Manasse sollen mir gehören wie Ruben und Simeon.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 48, 6, 'Deine übrigen Kinder aber, die dir nach ihnen geboren sind, sollen dir gehören: den Namen (eines) ihrer (beiden) Brüder sollen sie in ihrem Erbteil führen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 48, 7, 'Was mich aber betrifft: als ich aus Mesopotamien heimkehrte, starb mir Rahel unterwegs im Lande Kanaan, als nur noch eine Strecke Weges bis Ephrath zu gehen war, und ich begrub sie dort am Wege nach Ephrath [das ist Bethlehem].«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 48, 8, 'Als nun Israel die Söhne Josephs sah, fragte er: »Wer sind diese?«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 48, 9, 'Joseph antwortete seinem Vater: »Es sind meine Söhne, die Gott mir hier geschenkt hat.« Da sagte er: »Bringe sie her zu mir, damit ich sie segne!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 48, 10, 'Israels Augen waren nämlich infolge des Alters schwach geworden, so daß er nicht (mehr) sehen konnte. Als er sie nun dicht an ihn herangebracht hatte, küßte und umarmte er sie.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 48, 11, 'Hierauf sagte Israel zu Joseph: »Ich hatte nicht gehofft, dein Angesicht je wiederzusehen; und nun hat Gott mich sogar noch Kinder von dir sehen lassen!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 48, 12, 'Darauf zog Joseph sie wieder von seinen Knien weg und verneigte sich vor ihm bis zur Erde.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 48, 13, 'Dann nahm Joseph sie beide, Ephraim mit seiner rechten Hand auf der linken Seite Israels und Manasse mit seiner linken Hand auf der rechten Seite Israels, und ließ sie so an ihn herantreten.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 48, 14, 'Da streckte Israel seine rechte Hand aus und legte sie auf das Haupt Ephraims, obgleich er der jüngere war, und seine linke Hand auf das Haupt Manasses, indem er seine Arme übers Kreuz legte; denn Manasse war der Erstgeborene.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 48, 15, 'Dann segnete er Joseph mit den Worten: »Der Gott, vor dessen Angesicht meine Väter Abraham und Isaak gewandelt sind, der Gott, der mein Hirt gewesen ist, seitdem ich lebe, bis auf diesen Tag,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 48, 16, 'der Engel, der mich aus allem Unglück errettet hat: er segne diese Knaben, daß durch sie mein Name und der Name meiner Väter Abraham und Isaak fortlebt und sie sich zu einer großen Menge auf Erden vermehren!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 48, 17, 'Als nun Joseph sah, daß sein Vater seine rechte Hand andauernd auf das Haupt Ephraims legte, mißfiel ihm dies; er faßte daher die Hand seines Vaters, um sie vom Haupt Ephraims auf das Haupt Manasses zu legen,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 48, 18, 'indem er dabei zu seinem Vater sagte: »Nicht so, lieber Vater, denn dieser ist der Erstgeborene; lege deine rechte Hand auf sein Haupt!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 48, 19, 'Aber sein Vater wollte nicht und sagte: »Ich weiß es wohl, mein Sohn, ich weiß es! Auch dieser wird zu einem Volk werden, und auch er wird groß werden; jedoch sein jüngerer Bruder wird größer sein als er, und seine Nachkommen werden zu einer Menge von Völkern werden.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 48, 20, 'So segnete er sie denn an jenem Tage mit den Worten: »Mit deinem Namen werden die Israeliten einen Segenswunsch aussprechen, indem sie sagen: ›Gott mache dich gleich Ephraim und gleich Manasse!‹« Damit stellte er Ephraim vor Manasse.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 48, 21, 'Hierauf sagte Israel zu Joseph: »Ich werde nun sterben; aber Gott wird mit euch sein und euch in das Land eurer Väter zurückkehren lassen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 48, 22, 'Ich aber gebe dir einen Landstrich, den du vor deinen Brüdern voraushaben sollst; ich habe ihn den Amoritern einst mit meinem Schwert und meinem Bogen abgenommen.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 1, 'Dann berief Jakob seine Söhne und sagte: »Versammelt euch, damit ich euch das verkünde, was euch in künftigen Tagen widerfahren wird!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 2, 'Schart euch zusammen und hört zu, ihr Söhne Jakobs, ja, hört euren Vater Israel an!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 3, 'Du, Ruben, bist mein erstgeborener Sohn, meine Kraft und der Erstling meiner Stärke, bevorzugt an Würde und bevorzugt an Macht!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 4, 'Doch überwallend wie Wasser, sollst du keinen Vorzug genießen! Denn du hast deines Vaters Lager bestiegen; damals hast du es entweiht: mein Bett hat er bestiegen!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 5, 'Simeon und Levi sind Brüder; Werkzeuge der Gewalttat sind ihre Schwerter:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 6, 'ich will nichts zu schaffen haben mit ihren Ratschlägen, will keine Gemeinschaft haben mit ihren Entschlüssen! Denn in ihrem Zorn haben sie Männer erschlagen und in ihrem Mutwillen Stiere verstümmelt.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 7, 'Verflucht sei ihr Zorn, daß er so gewalttätig ist, und ihre Wut, daß sie sich so grausam zeigt! Ich will sie zerteilen in Jakob und will sie zerstreuen in Israel!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 8, 'Juda, du bist’s, den deine Brüder preisen werden! Deine Hand wird deinen Feinden auf dem Nacken liegen; vor dir werden sich verbeugen die Söhne deines Vaters.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 9, 'Ein junger Löwe ist Juda: vom Raub bist du emporgestiegen, mein Sohn. Er kauert sich nieder, streckt sich hin wie ein Löwe und wie eine Löwin; wer darf ihn aufstören?');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 10, 'Nicht wird das Zepter von Juda weichen noch der Herrscherstab zwischen seinen Füßen hinweg, bis der kommt, dem er gebührt, und die Völker werden ihm Gehorsam leisten.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 11, 'Er bindet sein Eselfüllen an den Weinstock und das Junge seiner Eselin an die Edelrebe; er wäscht im Wein sein Gewand und im Blut der Trauben seinen Mantel;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 12, 'trübe sind ihm die Augen vom Wein, und die Zähne schimmern von Milch.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 13, 'Sebulon wird bis hin zum Meeresstrand wohnen, und zwar am Gestade der Schiffe, und mit dem Rücken wird er sich an Sidon lehnen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 14, 'Issaschar ist ein starkknochiger Esel, der zwischen den Hürden lagert.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 15, 'Als er sah, daß die Ruhe etwas Schönes und sein Land gar lieblich sei, da beugte er seinen Nacken zum Lasttragen und wurde zum dienstbaren Fronknecht.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 16, 'Dan wird seinem Volke Recht schaffen wie irgendeiner von den Stämmen Israels;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 17, 'Dan wird eine Schlange am Wege sein, eine Hornotter am Pfad, die das Roß in die Fersen sticht, so daß sein Reiter rücklings zu Boden stürzt. –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 18, 'Auf dein Heil harre ich, HERR!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 19, 'Gad – Kriegsscharen werden ihn bedrängen, er aber wird ihnen nachdrängen auf der Ferse.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 20, 'Asser hat Brot im Überfluß; auch Königsleckerbissen wird er liefern.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 21, 'Naphthali ist eine flüchtige Hirschkuh; er ist’s, der schöne Lieder vernehmen läßt.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 22, 'Joseph ist eine junge Fruchtrebe, eine junge Fruchtrebe am Quell: ihre Schößlinge ranken über die Mauer empor.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 23, 'Wenn die Pfeilschützen ihm zusetzen und ihn beschießen und befehden,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 24, 'bleibt sein Bogen doch beständig gespannt, und gelenkig sind seine Arme und Hände infolge der Hilfe des starken Gottes Jakobs, von dorther, wo der Hirt, der Felsen Israels ist,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 25, 'von dem Gott deines Vaters: er helfe dir! –, und mit dem Beistand des Allmächtigen: er segne dich mit Segensfülle vom Himmel droben, mit Segensfülle aus der Urflut, die in der Tiefe lagert, mit Segensfülle aus Brüsten und Mutterschoß!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 26, 'Die Segnungen deines Vaters überragen die Segensfülle der uralten Berge, die köstlichen Gaben der ewigen Höhen; mögen sie zuteil werden dem Haupte Josephs und dem Scheitel des Geweihten unter seinen Brüdern!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 27, 'Benjamin ist ein räuberischer Wolf: am Morgen noch wird er den Raub verzehren und abends Beute verteilen.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 28, 'Dies sind die zwölf Stämme Israels insgesamt, und dies ist es, was ihr Vater zu ihnen geredet und womit er sie gesegnet hat, einen jeden mit einem besonderen Segen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 29, 'Dann erteilte er ihnen folgenden Auftrag: »Wenn ich jetzt zu meinen Stammesgenossen versammelt bin, so begrabt mich bei meinen Vätern in der Höhle auf dem Felde des Hethiters Ephron,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 30, 'in der Höhle auf dem Felde Machpela östlich von Mamre im Lande Kanaan, welche (Höhle) Abraham samt dem Felde von dem Hethiter Ephron zum Erbbegräbnis gekauft hat.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 31, 'Dort ist Abraham und seine Frau Sara begraben, dort ist Isaak und seine Frau Rebekka begraben, und dort habe ich Lea begraben.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 32, 'Abgekauft ist das Feld mit der Höhle darauf den Hethitern.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 33, 'Als nun Jakob mit der Mitteilung seines letzten Willens an seine Söhne zu Ende war, zog er seine Füße auf das Bett zurück und verschied und wurde zu seinen Stammesgenossen versammelt.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 1, 'Da warf sich Joseph über seinen Vater hin, weinte über ihn gebeugt und küßte ihn.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 2, 'Hierauf befahl Joseph den Ärzten, die in seinem Dienst standen, seinen Vater einzubalsamieren; da balsamierten die Ärzte Israel ein.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 3, 'Darüber vergingen vierzig Tage; denn so lange Zeit ist zum Einbalsamieren erforderlich; und die Ägypter trauerten siebzig Tage lang um ihn.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 4, 'Als dann die Zeit der Trauer um ihn vorüber war, sagte Joseph zu den Hofbeamten des Pharaos: »Wenn ich Gnade bei euch gefunden habe, so bringt doch folgendes zur Kenntnis des Pharaos:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 5, 'Mein Vater hat mir einen Eid abgenommen und mir geboten: ›Wenn ich tot bin, sollst du mich in meinem Grabe beisetzen, das ich mir im Lande Kanaan angelegt habe!‹ Deshalb möchte ich nun hinaufziehen, um meinen Vater zu begraben; dann kehre ich wieder zurück.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 6, 'Da ließ ihm der Pharao sagen: »Ziehe hinauf und begrabe deinen Vater, wie du ihm hast schwören müssen!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 7, 'So zog denn Joseph hin, um seinen Vater zu begraben, und mit ihm zogen alle Diener des Pharaos, die höchsten Beamten seines Hofes und alle Würdenträger des Landes Ägypten,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 8, 'dazu die ganze Familie Josephs, seine Brüder und überhaupt die Angehörigen seines Vaters; nur ihre kleinen Kinder sowie ihr Kleinvieh und ihre Rinder ließen sie im Lande Gosen zurück.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 9, 'Ebenso zogen sowohl Wagen als auch Reiter mit ihm, so daß es ein gewaltiger Zug war.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 10, 'Als sie nun nach Goren-Haatad, das jenseits des Jordans liegt, gekommen waren, veranstalteten sie dort eine große und sehr feierliche Totenklage, und (Joseph) stellte um seinen Vater eine siebentägige Leichenfeier an.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 11, 'Als nun die dort wohnenden Kanaanäer die Trauerfeier bei Goren-Haatad sahen, sagten sie: »Da findet eine ernste Trauerfeier der Ägypter statt«; daher gab man dem Ort den Namen ›Trauerfeier der Ägypter‹; er liegt jenseits des Jordans.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 12, 'Seine Söhne hielten es dann mit ihm so, wie er ihnen befohlen hatte:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 13, 'sie brachten ihn nämlich in das Land Kanaan und bestatteten ihn in der Höhle auf dem Felde Machpela, welche (Höhle) Abraham samt dem Felde zum Erbbegräbnis von dem Hethiter Ephron gekauft hatte, östlich von Mamre.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 14, 'Hierauf kehrte Joseph, nachdem er seinen Vater bestattet hatte, nach Ägypten zurück, er und seine Brüder und alle, die mit ihm hinaufgezogen waren, um seinen Vater zu bestatten.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 15, 'Als nun die Brüder Josephs sahen, daß ihr Vater tot war, sagten sie: »Wie nun, wenn Joseph feindselig gegen uns aufträte und uns all das Böse vergälte, das wir ihm zugefügt haben?«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 16, 'Darum sandten sie zu Joseph und ließen ihm sagen: »Dein Vater hat uns vor seinem Tode folgende Weisung gegeben:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 17, '›So sollt ihr zu Joseph sagen: Ach bitte, vergib doch deinen Brüdern ihr Vergehen und ihre Verschuldung, daß sie so übel an dir gehandelt haben!‹ So vergib uns nun doch unser Vergehen; wir sind ja doch auch Knechte des Gottes deines Vaters!« Da weinte Joseph, als sie ihm das sagen ließen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 18, 'Hierauf gingen seine Brüder selbst hin, warfen sich vor ihm nieder und sagten: »Hier sind wir als deine Knechte!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 19, 'Joseph aber antwortete ihnen: »Seid ohne Furcht! Denn stehe ich etwa an Gottes Statt?');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 20, 'Ihr freilich hattet Böses gegen mich im Sinn, aber Gott gedachte es zum Guten zu wenden, um das auszuführen, was jetzt klar zutage liegt, nämlich um ein zahlreiches Volk am Leben zu erhalten.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 21, 'Fürchtet euch also nicht! Ich selbst werde euch und eure Kinder versorgen.« So tröstete er sie und redete ihnen freundlich zu.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 22, 'So wohnte denn Joseph in Ägypten samt der ganzen Familie seines Vaters, und Joseph wurde 110 Jahre alt.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 23, 'Von Ephraim sah er Urenkel, und auch die Söhne Machirs, des Sohnes Manasses, wurden noch bei Lebzeiten Josephs geboren.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 24, 'Da sagte Joseph zu seinen Brüdern: »Ich stehe nun nahe vor dem Tode; Gott aber wird sich euer sicherlich gnädig annehmen und euch aus diesem Lande in das Land zurückführen, das er Abraham, Isaak und Jakob zugeschworen hat.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 25, 'Hierauf ließ Joseph die Söhne Israels folgendes beschwören: »Wenn Gott sich (dereinst) euer gnädig annehmen wird, dann sollt ihr meine Gebeine von hier mitnehmen.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 26, 'Dann starb Joseph im Alter von 110 Jahren; man balsamierte ihn ein und legte ihn in Ägypten in einen Sarg.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 1, 1, 'Dies sind die Namen der Söhne Israels, die nach Ägypten gekommen waren – mit Jakob waren sie gekommen, ein jeder mit seiner Familie –:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 1, 2, 'Ruben, Simeon, Levi und Juda;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 1, 3, 'Issaschar, Sebulon und Benjamin;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 1, 4, 'Dan und Naphthali, Gad und Asser.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 1, 5, 'Die Gesamtzahl der leiblichen Nachkommen Jakobs betrug siebzig Seelen; Joseph aber hatte sich (bereits) in Ägypten befunden.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 1, 6, 'Als aber Joseph und alle seine Brüder, überhaupt alle gestorben waren, welche in jener Zeit gelebt hatten,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 1, 7, 'vermehrten sich die Israeliten gewaltig und wurden über alle Maßen zahlreich und stark, so daß das Land voll von ihnen wurde.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 1, 8, 'Da kam ein neuer König in Ägypten zur Regierung, der Joseph nicht gekannt hatte.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 1, 9, 'Der sagte zu seinem Volk: »Seht, das Volk der Israeliten wird uns zu zahlreich und zu stark.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 1, 10, 'Wohlan, wir wollen klug gegen sie zu Werke gehen, damit ihrer nicht noch mehr werden; sonst könnte es geschehen, daß, wenn ein Krieg ausbräche, sie sich auch noch zu unsern Feinden schlügen und gegen uns kämpften und aus dem Lande wegzögen.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 1, 11, 'So setzten sie denn Fronvögte über das Volk, um es mit den Fronarbeiten, die sie ihm auferlegten, zu bedrücken; und es mußte für den Pharao Vorratsstädte bauen, nämlich Pithom und Ramses.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 1, 12, 'Aber je mehr man das Volk bedrückte, desto zahlreicher wurde es und desto mehr breitete es sich aus, so daß die Ägypter ein Grauen vor den Israeliten empfanden.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 1, 13, 'Daher zwangen die Ägypter die Israeliten gewaltsam zum Knechtsdienst');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 1, 14, 'und verleideten ihnen das Leben durch harte Fronarbeit in Lehm- und Ziegelsteinen und durch allerlei Feldarbeit, lauter Dienstleistungen, die sie zwangsweise von ihnen verrichten ließen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 1, 15, 'Da erteilte der König von Ägypten den hebräischen Hebammen, von denen die eine Siphra, die andere Pua hieß, folgenden Befehl:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 1, 16, '»Wenn ihr den Hebräerinnen bei der Geburt Hilfe leistet, so gebt bei der Entbindung wohl acht: wenn das Kind ein Knabe ist, so tötet ihn! ist es aber ein Mädchen, so mag es am Leben bleiben!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 1, 17, 'Aber die Hebammen waren gottesfürchtig und befolgten den Befehl des Königs von Ägypten nicht, sondern ließen die Knaben am Leben.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 1, 18, 'Da rief der König von Ägypten die Hebammen zu sich und fragte sie: »Warum verfahrt ihr so und laßt die Knaben am Leben?«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 1, 19, 'Die Hebammen antworteten dem Pharao: »Ja, die hebräischen Frauen sind nicht so (schwächlich) wie die ägyptischen, sondern haben eine kräftige Natur; ehe noch die Hebamme zu ihnen kommt, haben sie schon geboren.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 1, 20, 'Gott aber ließ es den Hebammen gut ergehen. So vermehrte sich denn das Volk stark und wurde sehr zahlreich;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 1, 21, 'und weil die Hebammen gottesfürchtig waren, verlieh Gott ihnen reichen Kindersegen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 1, 22, 'Da befahl der Pharao seinem ganzen Volke: »Jeden neugeborenen Knaben (der Hebräer) werft in den Nil, alle Mädchen aber laßt am Leben!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 2, 1, 'Nun ging ein Mann aus dem Stamme Levi hin und heiratete eine Levitin.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 2, 2, 'Diese Frau wurde Mutter eines Sohnes; und als sie sah, daß es ein schönes Kind war, verbarg sie ihn drei Monate lang.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 2, 3, 'Als sie ihn dann nicht länger verborgen halten konnte, nahm sie für ihn ein Kästchen von Papyrusrohr, machte es mit Erdharz und Pech dicht, legte das Knäblein hinein und setzte es in das Schilf am Ufer des Nils.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 2, 4, 'Seine Schwester aber mußte sich in einiger Entfernung hinstellen, um zu sehen, was mit ihm geschehen würde.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 2, 5, 'Da kam die Tochter des Pharaos an den Nil hinab, um zu baden, während ihre Dienerinnen am Ufer des Stromes hin und her gingen. Da erblickte sie das Kästchen mitten im Schilf und ließ es durch ihre Leibmagd holen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 2, 6, 'Als sie es dann öffnete, siehe, da lag ein weinendes Knäblein darin! Da fühlte sie Mitleid mit ihm und sagte: »Das ist eins von den Kindern der Hebräer.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 2, 7, 'Da fragte seine Schwester die Tochter des Pharaos: »Soll ich hingehen und dir eine Amme von den Hebräerinnen holen, damit sie dir den Knaben nährt?«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 2, 8, 'Die Tochter des Pharaos antwortete ihr: »Ja, gehe hin!« Da ging das Mädchen hin und holte die Mutter des Kindes.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 2, 9, 'Die Tochter des Pharaos sagte zu dieser: »Nimm dieses Knäblein mit und nähre es mir! Ich will dir den Lohn dafür geben.« So nahm denn die Frau das Knäblein und nährte es.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 2, 10, 'Als der Knabe dann größer geworden war, brachte sie ihn der Tochter des Pharaos; die nahm ihn als Sohn an und gab ihm den Namen Mose; »denn«, sagte sie, »ich habe ihn aus dem Wasser gezogen«.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 2, 11, 'Zu jener Zeit nun, als Mose zum Mann geworden war, ging er (einmal) zu seinen Volksgenossen hinaus und sah ihren Fronarbeiten zu. Da sah er, wie ein Ägypter einen Hebräer, einen von seinen Volksgenossen, schlug.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 2, 12, 'Da blickte er sich nach allen Seiten um, und als er sah, daß kein Mensch sonst zugegen war, erschlug er den Ägypter und verscharrte ihn im Sand.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 2, 13, 'Am folgenden Tage ging er wieder hinaus und sah, wie zwei Hebräer sich miteinander zankten. Da sagte er zu dem, der im Unrecht war: »Warum schlägst du deinen Volksgenossen?«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 2, 14, 'Der gab zur Antwort: »Wer hat dich zum Obmann und Richter über uns bestellt? Willst du mich etwa auch totschlagen, wie du den Ägypter totgeschlagen hast?« Da erschrak Mose, denn er sagte sich: »So ist also die Sache doch ruchbar geworden!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 2, 15, 'Als nun auch der Pharao von dem Vorfall erfuhr und Mose töten lassen wollte, floh Mose vor dem Pharao und nahm seinen Wohnsitz im Lande Midian. Er hatte sich nämlich (nach seiner Ankunft dort) am Brunnen niedergesetzt.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 2, 16, 'Nun hatte der Priester der Midianiter sieben Töchter; die kamen und wollten Wasser schöpfen und die Tränkrinnen füllen, um das Kleinvieh ihres Vaters zu tränken.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 2, 17, 'Aber die Hirten kamen dazu und wollten sie wegdrängen. Da erhob sich Mose, leistete ihnen Beistand und tränkte ihre Herde.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 2, 18, 'Als sie nun zu ihrem Vater Reguel heimkamen, fragte er sie: »Warum kommt ihr heute so früh heim?«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 2, 19, 'Sie antworteten: »Ein ägyptischer Mann hat uns gegen die Hirten in Schutz genommen, ja, er hat sogar das Schöpfen für uns besorgt und die Herde getränkt.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 2, 20, 'Da sagte er zu seinen Töchtern: »Und wo ist er? Warum habt ihr denn den Mann dort draußen gelassen? Ladet ihn doch zum Essen ein!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 2, 21, 'Mose entschloß sich dann, bei dem Manne zu bleiben, und dieser gab ihm seine Tochter Zippora zur Frau.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 2, 22, 'Als sie ihm einen Sohn gebar, gab er ihm den Namen Gersom; »denn«, sagte er, »ein Gast bin ich in einem fremden Lande geworden«.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 2, 23, 'Es begab sich dann während jener langen Zeit, daß der König von Ägypten starb. Die Israeliten aber seufzten unter dem Frondienst und schrien auf, und ihr Hilferuf wegen des Frondienstes stieg zu Gott empor.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 2, 24, 'Als Gott nun ihr Wehklagen hörte, gedachte er seines Bundes mit Abraham, Isaak und Jakob;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 2, 25, 'und Gott sah die Israeliten an, und Gott nahm Kenntnis davon.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 3, 1, 'Mose aber weidete das Kleinvieh seines Schwiegervaters Jethro, des Priesters der Midianiter. Als er nun einst die Herde über die Steppe hinaus getrieben hatte, kam er an den Berg Gottes, an den Horeb.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 3, 2, 'Da erschien ihm der Engel des HERRN als eine Feuerflamme, die mitten aus einem Dornbusch hervorschlug; und als er hinblickte, sah er, daß der Dornbusch im Feuer brannte, ohne jedoch vom Feuer verzehrt zu werden.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 3, 3, 'Da dachte Mose: »Ich will doch hingehen und mir diese wunderbare Erscheinung ansehen, warum der Dornbusch nicht verbrennt.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 3, 4, 'Als nun der HERR sah, daß er herankam, um nachzusehen, rief Gott ihm aus dem Dornbusch heraus die Worte zu: »Mose, Mose!« Er antwortete: »Hier bin ich!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 3, 5, 'Da sagte er: »Tritt nicht näher heran! Ziehe dir die Schuhe aus von den Füßen; denn die Stätte, auf der du stehst, ist heiliger Boden.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 3, 6, 'Dann fuhr er fort: »Ich bin der Gott deines Vaters, der Gott Abrahams, der Gott Isaaks und der Gott Jakobs.« Da verhüllte Mose sein Gesicht; denn er fürchtete sich, Gott anzuschauen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 3, 7, 'Hierauf sagte der HERR: »Ich habe das Elend meines Volkes in Ägypten gesehen und ihr Geschrei über ihre Fronvögte gehört; ja, ich kenne ihre Leiden!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 3, 8, 'Daher bin ich herabgekommen, um sie aus der Gewalt der Ägypter zu erretten und sie aus jenem Lande in ein schönes, geräumiges Land zu führen, in ein Land, das von Milch und Honig überfließt, in die Wohnsitze der Kanaanäer, Hethiter, Amoriter, Pherissiter, Hewiter und Jebusiter.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 3, 9, 'Weil also jetzt das Wehgeschrei der Israeliten zu mir gedrungen ist und ich auch gesehen habe, wie schwer die Ägypter sie bedrücken,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 3, 10, 'so gehe jetzt hin! Denn ich will dich zum Pharao senden, damit du mein Volk, die Israeliten, aus Ägypten hinausführst.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 3, 11, 'Da sagte Mose zu Gott: »Wer bin ich, daß ich zum Pharao gehen und die Israeliten aus Ägypten hinausführen sollte?«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 3, 12, 'Er antwortete: »Ich selbst werde mit dir sein! Und dies soll dir das Wahrzeichen dafür sein, daß ich dich gesandt habe: Wenn du das Volk aus Ägypten wegführst, werdet ihr an diesem Berge Gott dienen.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 3, 13, 'Da sagte Mose zu Gott: »Wenn ich nun aber zu den Israeliten komme und ihnen sage: ›Der Gott eurer Väter hat mich zu euch gesandt‹, und wenn sie mich dann fragen: ›Wie heißt er denn?‹, was soll ich ihnen dann antworten?«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 3, 14, 'Da sagte Gott zu Mose: »Ich bin, der ich bin.« Dann fuhr er fort: »So sollst du zu den Israeliten sagen: Der ›Ich bin‹ hat mich zu euch gesandt!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 3, 15, 'Und weiter sagte Gott zu Mose: »So sollst du zu den Israeliten sagen: ›Der HERR, der Gott eurer Väter, der Gott Abrahams, der Gott Isaaks und der Gott Jakobs, hat mich zu euch gesandt.‹ Das ist mein Name in Ewigkeit und meine Benennung von Geschlecht zu Geschlecht.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 3, 16, '»Gehe hin und versammle die Ältesten der Israeliten und sage zu ihnen: ›Der HERR, der Gott eurer Väter, ist mir erschienen, der Gott Abrahams, Isaaks und Jakobs, und hat gesagt: Ich habe auf euch und auf das, was euch in Ägypten widerfahren ist, genau achtgegeben');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 3, 17, 'und habe beschlossen, euch aus dem Elend Ägyptens in das Land der Kanaanäer, Hethiter, Amoriter, Pherissiter, Hewiter und Jebusiter wegzuführen, in ein Land, das von Milch und Honig überfließt.‹');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 3, 18, 'Wenn sie dann auf dich hören, sollst du mit den Ältesten der Israeliten zum König von Ägypten hingehen, und ihr sollt zu ihm sagen: ›Der HERR, der Gott der Hebräer, ist uns erschienen; und nun möchten wir drei Tagereisen weit in die Wüste ziehen, um dort dem HERRN, unserm Gott, zu opfern.‹');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 3, 19, 'Ich weiß aber, daß der König von Ägypten euch nicht wird ziehen lassen, wenn er nicht durch eine starke Hand dazu gezwungen wird.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 3, 20, 'Darum werde ich dann meine Hand ausstrecken und das Ägyptervolk mit all meinen Wundertaten schlagen, die ich in seiner Mitte verrichten werde; daraufhin wird er euch ziehen lassen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 3, 21, 'Auch will ich dieses Volk bei den Ägyptern Gunst finden lassen, so daß ihr bei eurem Auszug nicht mit leeren Händen ausziehen sollt,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 3, 22, 'nein, jede Frau soll sich von ihrer Nachbarin und ihrer Hausgenossin silberne und goldene Schmucksachen und Kleider geben lassen; die sollt ihr dann euren Söhnen und Töchtern anlegen und so die Ägypter ausplündern.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 1, 'Mose aber entgegnete: »Ach, sie werden mir nicht glauben und auf meine Aussagen nicht hören, sondern behaupten: ›Der HERR ist dir nicht erschienen!‹«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 2, 'Da erwiderte ihm der HERR: »Was hast du da in deiner Hand?« Er antwortete: »Einen Stab.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 3, 'Da sagte er: »Wirf ihn auf die Erde!« Als er ihn nun auf die Erde geworfen hatte, wurde er zu einer Schlange, vor welcher Mose die Flucht ergriff.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 4, 'Da sagte der HERR zu Mose: »Strecke deine Hand aus und ergreif sie beim Schwanz!« Er streckte seine Hand aus und faßte sie: da wurde sie wieder zum Stab in seiner Hand –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 5, '»damit sie glauben, daß dir der HERR erschienen ist, der Gott ihrer Väter, der Gott Abrahams, der Gott Isaaks und der Gott Jakobs.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 6, 'Weiter sagte der HERR zu ihm: »Stecke deine Hand in deinen Busen!« Er steckte seine Hand in den Busen, und als er sie wieder herauszog, war seine Hand vom Aussatz weiß wie Schnee.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 7, 'Dann sagte er: »Stecke deine Hand noch einmal in deinen Busen!« Als er es getan hatte und die Hand dann wieder aus seinem Busen hervorzog, da war sie wieder wie sein übriges Fleisch geworden.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 8, '»Wenn sie dir also nicht glauben und sich von dem ersten Zeichen nicht überzeugen lassen, so werden sie doch auf das zweite Zeichen hin glauben.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 9, 'Sollten sie aber selbst auf diese beiden Zeichen hin nicht glauben und auf deine Aussagen nicht hören, so nimm etwas Wasser aus dem Nil und schütte es auf den trockenen Boden, dann wird das Wasser, das du aus dem Strom genommen hast, auf dem trocknen Boden zu Blut werden.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 10, 'Mose aber sagte zum HERRN: »Bitte, HERR! Ich bin kein Mann, der zu reden versteht; ich bin es früher nicht gewesen und bin es auch jetzt nicht, seitdem du zu deinem Knecht redest, sondern ich bin mit Mund und Zunge unbeholfen.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 11, 'Da antwortete ihm der HERR: »Wer hat dem Menschen den Mund geschaffen, oder wer macht ihn stumm oder taub, sehend oder blind? Bin ich es nicht, der HERR?');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 12, 'So gehe also hin! Ich will schon mit deinem Munde sein und dich lehren, was du reden sollst.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 13, 'Doch er antwortete: »Bitte, HERR! Sende lieber einen andern, wen du willst!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 14, 'Da entbrannte der Zorn des HERRN gegen Mose, und er sagte: »Ist nicht dein Bruder Aaron da, der Levit? Ich weiß, daß der trefflich zu reden versteht; auch ist er schon im Begriff, dir entgegenzugehen, und wenn er dich sieht, wird er sich herzlich freuen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 15, 'Dann sollst du dich mit ihm besprechen und ihm die Worte in den Mund legen; ich aber will mit deinem und mit seinem Munde sein und euch angeben, was ihr zu tun habt.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 16, 'Er soll also für dich zum Volk reden, und zwar so, daß er für dich der Mund ist und du für ihn an Gottes Statt bist.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 17, 'Und den Stab da nimm in die Hand, um mit ihm die Wunderzeichen zu tun!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 18, 'Hierauf kehrte Mose zu seinem Schwiegervater Jethro zurück und sagte zu ihm: »Ich möchte doch einmal zu meinen Angehörigen nach Ägypten zurückkehren, um zu sehen, ob sie noch am Leben sind.« Jethro antwortete ihm: »Ziehe hin in Frieden!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 19, 'Da sagte der HERR zu Mose im Midianiterlande: »Kehre nunmehr nach Ägypten zurück; denn alle die Leute, die dir nach dem Leben getrachtet haben, sind tot.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 20, 'So nahm denn Mose seine Frau und seine Söhne, setzte sie auf Esel und trat die Rückkehr nach Ägypten an; den Gottesstab aber nahm er in die Hand.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 21, 'Da sagte der HERR zu Mose: »Wenn du jetzt nach Ägypten zurückkommst, so sieh wohl zu, daß du alle die Wunderzeichen, deren Vollführung ich dir aufgetragen habe, vor dem Pharao verrichtest! Ich aber werde sein Herz verhärten, daß er das Volk nicht ziehen läßt.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 22, 'Dann sollst du zum Pharao sagen: ›So hat der HERR gesprochen: Israel ist mein erstgeborener Sohn;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 23, 'daher fordere ich dich auf: Laß meinen Sohn ziehen, damit er mir diene! Weigerst du dich aber, ihn ziehen zu lassen, so werde ich deinen erstgeborenen Sohn sterben lassen!‹«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 24, 'Unterwegs aber, in der Nachtherberge, überfiel der HERR den Mose und wollte ihn töten.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 25, 'Da nahm Zippora einen scharfen Stein, schnitt damit die Vorhaut ihres Sohnes ab, warf sie ihm vor die Füße und sagte: »Ein Blutbräutigam bist du mir!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 26, 'Da ließ er von ihm ab. Damals sagte sie ›Blutbräutigam‹ im Hinblick auf die Beschneidung.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 27, 'Der HERR aber hatte dem Aaron geboten: »Gehe Mose entgegen nach der Wüste zu!« Da machte er sich auf und traf ihn am Berge Gottes und küßte ihn.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 28, 'Mose teilte nun dem Aaron alles mit, was der HERR ihm bei der Sendung aufgetragen, und alle Wunderzeichen, die er ihm geboten hatte.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 29, 'Darauf gingen Mose und Aaron hin und versammelten alle Ältesten der Israeliten;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 30, 'und Aaron teilte ihnen alles mit, was der HERR dem Mose aufgetragen hatte, und dieser verrichtete die Wunderzeichen vor den Augen des Volkes.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 31, 'Da schenkte ihm das Volk Glauben, und als sie hörten, daß der HERR sich der Israeliten gnädig angenommen und ihr Elend angesehen habe, verneigten sie sich und warfen sich zur Erde nieder.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 5, 1, 'Hierauf gingen Mose und Aaron hin und sagten zum Pharao: »So hat der HERR, der Gott Israels, gesprochen: ›Laß mein Volk ziehen, damit sie mir ein Fest in der Wüste feiern!‹«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 5, 2, 'Der Pharao aber antwortete: »Wer ist der HERR, daß ich seinen Befehlen gehorchen und Israel ziehen lassen müßte? Ich kenne (diesen) HERRN nicht und will auch Israel nicht ziehen lassen.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 5, 3, 'Da entgegneten sie: »Der Gott der Hebräer ist uns erschienen; wir möchten nun drei Tagereisen weit in die Wüste ziehen und dem HERRN, unserm Gott, dort Schlachtopfer darbringen, damit er uns nicht mit der Pest oder mit dem Schwert heimsucht!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 5, 4, 'Aber der König von Ägypten erwiderte ihnen: »Warum wollt ihr, Mose und Aaron, das Volk von seiner Arbeit abziehen? Geht an eure Frondienste!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 5, 5, 'Dann fuhr der Pharao fort: »Es gibt schon genug Gesindel im Land; und da wollt ihr sie noch von ihren Frondiensten feiern lassen?!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 5, 6, 'An demselben Tage erteilte dann der Pharao den Fronvögten und Aufsehern des Volkes den Befehl:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 5, 7, '»Ihr sollt dem Volk nicht mehr wie bisher Stroh zur Anfertigung der Ziegel liefern! Sie sollen selbst hingehen und sich Stroh zusammensuchen!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 5, 8, 'Dabei sollt ihr ihnen aber dieselbe Zahl von Ziegeln, die sie bisher gefertigt haben, auferlegen, ohne etwas davon zu erlassen! Denn sie sind träge; darum schreien sie immerfort: ›Wir wollen hinziehen und unserm Gott Opfer darbringen!‹');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 5, 9, 'Die Arbeit soll den Leuten erschwert werden, damit sie daran zu schaffen haben und nicht auf Lügenreden achten!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 5, 10, 'Da gingen die Fronvögte und Aufseher des Volkes hinaus und sagten zum Volk: »So hat der Pharao befohlen: ›Ich lasse euch hinfort kein Stroh mehr liefern:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 5, 11, 'geht selbst hin und holt euch Stroh, wo ihr es findet! Doch von eurer Arbeit wird euch nichts erlassen.‹«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 5, 12, 'Da zerstreute sich das Volk im ganzen Lande Ägypten, um Stoppeln zu sammeln zu Häckerling;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 5, 13, 'die Fronvögte aber drängten sie mit der Forderung: »Ihr müßt Tag für Tag die volle Arbeit leisten wie früher, als es noch Stroh gab.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 5, 14, 'Und die israelitischen Aufseher, welche die Fronvögte des Pharaos über sie gesetzt hatten, erhielten Stockschläge, und man sagte zu ihnen: »Warum habt ihr weder gestern noch heute euren bestimmten Satz Ziegel fertiggestellt wie früher?«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 5, 15, 'Da gingen die israelitischen Aufseher hin und wehklagten beim Pharao mit den Worten: »Warum behandelst du deine Knechte so?');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 5, 16, 'Stroh wird deinen Knechten nicht mehr geliefert, und doch heißt es: ›Schafft Ziegel!‹ Und nun werden deine Knechte sogar geschlagen, und die Schuld wird auf dein Volk geschoben!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 5, 17, 'Er aber antwortete: »Träge seid ihr, träge! Darum sagt ihr: ›Wir möchten hinziehen, um dem HERRN zu opfern.‹');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 5, 18, 'Und nun marsch an die Arbeit! Stroh wird euch nicht geliefert, aber die festgesetzte Zahl von Ziegeln habt ihr zu liefern!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 5, 19, 'So sahen sich denn die israelitischen Aufseher in eine üble Lage versetzt, nämlich (ihren Volksgenossen) sagen zu müssen: »Von den Ziegeln, die ihr Tag für Tag zu liefern habt, dürft ihr keinen Abzug machen!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 5, 20, 'Als sie nun aus dem Palast des Pharaos herauskamen, stießen sie auf Mose und Aaron, die auf sie warteten.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 5, 21, 'Da sagten sie zu ihnen: »Der HERR möge es euch gedenken und euch dafür richten, daß ihr uns beim Pharao und seinen Beamten ganz verhaßt gemacht und ihnen das Schwert in die Hand gegeben habt, uns umzubringen!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 5, 22, 'Da wandte sich Mose wieder an den HERRN und sagte: »Herr! Warum läßt du diesem Volk solches Unheil widerfahren? Warum hast du mich hergesandt?');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 5, 23, 'Denn seitdem ich zum Pharao gegangen bin, um in deinem Namen zu reden, hat er dies Volk erst recht mißhandelt, und du hast zur Rettung deines Volkes nichts getan!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 1, 'Da sagte der HERR zu Mose: »Jetzt sollst du sehen, was ich mit dem Pharao machen werde: Durch eine starke Hand gezwungen, wird er sie ziehen lassen, ja durch eine starke Hand gezwungen, wird er sie aus seinem Lande wegtreiben!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 2, 'Da redete Gott mit Mose und sagte zu ihm: »Ich bin der HERR.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 3, 'Ich bin dem Abraham, Isaak und Jakob als ›der allmächtige Gott‹ erschienen, aber mit meinem Namen ›Gott der HERR‹ habe ich mich ihnen nicht geoffenbart.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 4, 'Auch habe ich meinen Bund mit ihnen geschlossen, ihnen das Land Kanaan zu geben, das Land ihrer Fremdlingschaft, in dem sie als Gäste sich aufgehalten haben.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 5, 'Ich habe auch die Klagen der Israeliten gehört, die von den Ägyptern geknechtet werden, und habe meines Bundes gedacht.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 6, 'Darum sage zu den Israeliten: ›Ich bin der HERR und will euch von dem Druck der Fronarbeiten der Ägypter frei machen und euch aus ihrem Zwangsdienst erretten und euch erlösen mit hoch erhobenem Arm und mit gewaltigen Strafgerichten.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 7, 'Und ich will euch zu meinem Volk annehmen und will euer Gott sein, und ihr sollt erkennen, daß ich der HERR, euer Gott, bin, der euch vom Druck des Frondienstes der Ägypter frei macht.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 8, 'Ich will euch auch in das Land bringen, dessen Verleihung ich dem Abraham, Isaak und Jakob durch einen feierlichen Eid zugesagt habe, und will es euch zum erblichen Besitz geben, ich, der HERR!‹«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 9, 'Mose berichtete dies den Israeliten; aber sie hörten nicht auf ihn aus Kleinmut und wegen des harten Frondienstes.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 10, 'Da sagte Gott zu Mose:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 11, '»Gehe hin, fordere den Pharao, den König von Ägypten, auf, die Israeliten aus seinem Lande ziehen zu lassen!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 12, 'Aber Mose sprach sich vor dem HERRN offen so aus: »Nicht einmal die Israeliten haben auf mich gehört: wie sollte da der Pharao mich anhören, zumal da ich im Reden ungewandt bin!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 13, 'Da redete der HERR mit Mose und Aaron und ordnete sie ab an die Israeliten und an den Pharao, den König von Ägypten, um die Israeliten aus Ägypten wegzuführen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 14, 'Dies sind ihre Familienhäupter: Die Söhne Rubens, des erstgeborenen Sohnes Israels, waren: Hanoch und Pallu, Hezron und Karmi; dies sind die Geschlechter Rubens.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 15, 'Und die Söhne Simeons waren: Jemuel, Jamin, Ohad, Jachin, Zohar und Saul, der Sohn der Kanaanäerin; dies sind die Geschlechter Simeons.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 16, 'Und dies sind die Namen der Söhne Levis nach ihren Geschlechtern: Gerson, Kehath und Merari; Levi aber wurde 137 Jahre alt.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 17, 'Die Söhne Gersons waren: Libni und Simei nach ihren Familien.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 18, 'Die Söhne Kehaths waren: Amram, Jizhar, Hebron und Ussiel; Kehath aber wurde 133 Jahre alt.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 19, 'Und die Söhne Meraris waren: Mahli und Musi; das sind die Familien Levis nach ihren Geschlechtern.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 20, 'Amram aber heiratete seine Muhme Jochebed; die gebar ihm Aaron und Mose; Amram wurde dann 137 Jahre alt.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 21, 'Die Söhne Jizhars aber waren: Korah, Nepheg und Sichri;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 22, 'und die Söhne Ussiels waren: Misael, Elzaphan und Sithri.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 23, 'Aaron aber heiratete Eliseba, die Tochter Amminadabs, die Schwester Nahsons; die gebar ihm Nadab und Abihu, Eleasar und Ithamar.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 24, 'Und die Söhne Korahs waren: Assir, Elkana und Abiasaph; dies sind die Familien der Korahiten.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 25, 'Eleasar aber, der Sohn Aarons, heiratete eine von den Töchtern Putiels; die gebar ihm den Pinehas. Dies sind die Stammhäupter der Leviten nach ihren Geschlechtern. –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 26, 'Dieser Aaron und dieser Mose sind es, denen der HERR geboten hatte: »Führt die Israeliten aus dem Lande Ägypten hinaus nach ihren Heerscharen!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 27, 'Diese sind es, die mit dem Pharao, dem König von Ägypten, verhandelten, um die Israeliten aus Ägypten wegzuführen: dieser Mose und dieser Aaron.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 28, 'Damals nun, als der HERR mit Mose im Lande Ägypten redete,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 29, 'sagte der HERR zu Mose folgendes: »Ich bin der HERR! Vermelde dem Pharao, dem König von Ägypten, alles, was ich dir sagen werde.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 30, 'Mose aber antwortete vor dem HERRN: »Ach, ich bin im Reden ungewandt: wie sollte da der Pharao auf mich hören!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 7, 1, 'Da erwiderte der HERR dem Mose: »Siehe, ich mache dich für den Pharao zu einem Gott, und dein Bruder Aaron soll dein Prophet sein.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 7, 2, 'Du sollst ihm alles sagen, was ich dir auftragen werde, doch dein Bruder Aaron soll mit dem Pharao verhandeln, daß er die Israeliten aus seinem Lande ziehen lasse.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 7, 3, 'Ich aber will das Herz des Pharaos verhärten, um viele Zeichen und Wunder im Lande Ägypten zu verrichten.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 7, 4, 'Wenn der Pharao nun auf euch nicht hört, so will ich meine Hand an die Ägypter legen und meine Heerscharen, mein Volk, die Israeliten, aus Ägypten unter gewaltigen Strafgerichten wegführen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 7, 5, 'Dann werden die Ägypter zur Erkenntnis kommen, daß ich der HERR bin, wenn ich meine Hand gegen die Ägypter ausgestreckt und die Israeliten aus ihrer Mitte weggeführt habe.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 7, 6, 'Da taten Mose und Aaron so, wie der HERR ihnen geboten hatte, genau so taten sie.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 7, 7, 'Mose war aber achtzig und Aaron dreiundachtzig Jahre alt, als sie mit dem Pharao verhandelten.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 7, 8, 'Hierauf sagte der HERR zu Mose und zu Aaron:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 7, 9, '»Wenn der Pharao euch auffordert, ein Wunder zu eurer Beglaubigung zu verrichten, so sollst du zu Aaron sagen: ›Nimm deinen Stab und wirf ihn vor den Pharao hin!‹, dann wird er zu einer großen Schlange werden.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 7, 10, 'Da gingen Mose und Aaron zum Pharao und taten so, wie der HERR ihnen geboten hatte: Aaron warf seinen Stab vor den Pharao und dessen Hofleute hin, und er verwandelte sich in eine große Schlange.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 7, 11, 'Aber der Pharao ließ auch seinerseits die Weisen und Zauberer kommen, und auch sie, die ägyptischen Zauberkünstler, taten dasselbe vermittels ihrer Geheimkünste:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 7, 12, 'jeder warf seinen Stab hin, da verwandelten diese sich in Schlangen; jedoch Aarons Stab verschlang ihre Stäbe.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 7, 13, 'Aber das Herz des Pharaos blieb hart, so daß er nicht auf sie hörte, wie der HERR es vorausgesagt hatte.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 7, 14, 'Hierauf sagte der HERR zu Mose: »Das Herz des Pharaos ist verstockt: er weigert sich, das Volk ziehen zu lassen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 7, 15, 'Begib dich morgen früh zum Pharao – da geht er nämlich an den Fluß – und tritt ihm am Ufer des Nils entgegen; den Stab, der sich in eine Schlange verwandelt hat, nimm in deine Hand');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 7, 16, 'und sage zu ihm: ›Der HERR, der Gott der Hebräer, hat mich zu dir gesandt mit der Weisung: Laß mein Volk ziehen, damit es mir in der Wüste diene! Doch du hast bisher nicht gehorchen wollen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 7, 17, 'Daher spricht der HERR so: Daran sollst du erkennen, daß ich der HERR bin: ich werde jetzt mit dem Stabe, den ich hier in der Hand habe, auf das Wasser im Nil schlagen, dann wird es sich in Blut verwandeln,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 7, 18, 'die Fische im Strom werden sämtlich sterben, und der Strom wird stinkend werden, so daß die Ägypter vor Ekel kein Wasser mehr aus dem Strom trinken werden.‹«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 7, 19, 'Weiter sagte der HERR zu Mose: »Befiehl dem Aaron: ›Nimm deinen Stab und strecke deine Hand aus über die Gewässer in Ägypten, über seine Stromarme, seine Kanäle und Teiche und über alle seine Wasserbehälter, damit sie zu Blut werden! Und Blut soll überall in Ägypten sein, selbst in den hölzernen und steinernen Gefäßen!‹«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 7, 20, 'Mose und Aaron taten so, wie der HERR ihnen geboten hatte: Aaron hob den Stab hoch und schlug mit ihm auf das Wasser im Nil vor den Augen des Pharaos und seiner Diener: da verwandelte sich alles Wasser im Strom in Blut;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 7, 21, 'die Fische im Strom starben sämtlich, und der Strom wurde stinkend, so daß die Ägypter das Wasser aus dem Strom nicht mehr trinken konnten; und das Blut war überall im Land Ägypten.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 7, 22, 'Aber die ägyptischen Zauberer taten dasselbe vermittels ihrer Geheimkünste; daher blieb das Herz des Pharaos hart, und er hörte nicht auf sie, wie der HERR es vorausgesagt hatte:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 7, 23, 'der Pharao wandte sich ab und ging nach Hause und nahm sich auch dieses nicht zu Herzen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 7, 24, 'Alle Ägypter aber gruben rings um den Nil nach Trinkwasser; denn von dem Nilwasser konnten sie nicht trinken.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 7, 25, 'So vergingen volle sieben Tage, nachdem der HERR den Strom geschlagen hatte.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 7, 26, 'Hierauf gebot der HERR dem Mose: »Gehe zum Pharao und sage zu ihm: ›So hat der HERR gesprochen: Laß mein Volk ziehen, damit es mir diene!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 7, 27, 'Wenn du dich aber weigerst, es ziehen zu lassen, so will ich dein ganzes Gebiet mit Fröschen heimsuchen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 7, 28, 'Der Nil soll dann von Fröschen wimmeln; die sollen heraufkommen und in deinen Palast, in dein Schlafgemach und auf dein Bett kriechen und in die Häuser deiner Diener und unter dein Volk, auch in deine Backöfen und Backtröge dringen;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 7, 29, 'ja an dir selbst und deinen Untertanen und an all deinen Dienern sollen die Frösche hinaufkriechen!‹«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 1, 'Hierauf gebot der HERR dem Mose: »Sage zu Aaron: ›Strecke deine Hand mit deinem Stabe aus über die Stromarme, die Kanäle und Teiche, und laß die Frösche über das Land Ägypten heraufkommen!‹«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 2, 'Da streckte Aaron seine Hand über die Gewässer Ägyptens aus, und die Frösche kamen herauf und bedeckten das Land Ägypten.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 3, 'Aber auch die Zauberer taten dasselbe vermittels ihrer Geheimkünste: auch sie ließen die Frösche über das Land Ägypten kommen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 4, 'Da ließ der Pharao Mose und Aaron kommen und sagte: »Legt beim HERRN Fürbitte für mich ein, daß er die Frösche von mir und meinem Volk entferne! Dann will ich das Volk ziehen lassen, damit es dem HERRN opfert.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 5, 'Mose antwortete dem Pharao: »Verfüge über mich! Auf wann soll ich für dich, für deine Diener und dein Volk die Vertilgung der Frösche erbitten, damit sie von dir und aus deinen Palästen verschwinden und nur noch im Nil verbleiben?«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 6, 'Er antwortete: »Auf morgen!« Da sagte Mose: »Wie du wünschest, so sei es! Du sollst erkennen, daß niemand dem HERRN, unserm Gott, gleich ist.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 7, 'Die Frösche sollen also von dir und aus deinen Palästen, von deinen Dienern und deinem Volk weichen; nur im Nil sollen sie verbleiben!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 8, 'Als Mose und Aaron dann vom Pharao weggegangen waren, betete Mose laut zum HERRN wegen der Frösche, mit denen er den Pharao heimgesucht hatte.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 9, 'Da tat der HERR nach der Bitte Moses, so daß die Frösche in den Häusern, in den Gehöften und auf den Feldern hinwegstarben;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 10, 'man schüttete sie überall in Haufen zusammen, und das Land stank davon.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 11, 'Als aber der Pharao merkte, daß er Luft bekommen hatte, verstockte er sein Herz weiter und hörte nicht auf sie, wie der HERR es vorausgesagt hatte.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 12, 'Hierauf sagte der HERR zu Mose: »Befiehl dem Aaron: ›Strecke deinen Stab aus und schlage mit ihm den Staub auf dem Erdboden, damit er sich in ganz Ägypten in Stechmücken verwandelt!‹«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 13, 'Und sie taten so: Aaron streckte seine Hand mit dem Stabe aus und schlug damit den Staub auf dem Erdboden; da kamen die Stechmücken an die Menschen und an das Vieh; aller Staub auf dem Erdboden wurde zu Stechmücken in ganz Ägypten.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 14, 'Die ägyptischen Zauberer bemühten sich mit ihren Geheimkünsten ebenso, Stechmücken hervorzubringen, vermochten es aber nicht; die Stechmücken aber saßen an Menschen und Vieh.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 15, 'Da sagten die Zauberer zum Pharao: »Das ist eines Gottes Finger!« Doch das Herz des Pharaos blieb hart, und er hörte nicht auf sie, wie der HERR es vorausgesagt hatte.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 16, 'Hierauf gebot der HERR dem Mose: »Mache dich morgen in der Frühe auf und tritt vor den Pharao hin, wenn er hinaus an den Fluß geht, und sage zu ihm: ›So hat der HERR gesprochen: Laß mein Volk ziehen, damit es mir diene!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 17, 'Denn wenn du mein Volk nicht ziehen läßt, so will ich Hundsfliegen über dich und deine Diener, über dein Volk und deine Paläste kommen lassen, so daß die Häuser der Ägypter und sogar der Erdboden, auf dem sie stehen, voll von Hundsfliegen sein werden.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 18, 'Aber an demselben Tage will ich das Land Gosen, wo mein Volk wohnt, absondern, so daß es dort keine Hundsfliegen geben soll, damit du erkennst, daß ich der HERR bin inmitten dieses Landes.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 19, 'Ich will also eine Scheidung zwischen meinem und deinem Volk eintreten lassen: morgen soll dies Zeichen geschehen!‹«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 20, 'Und der HERR tat so: es kamen Hundsfliegen in gewaltiger Menge in den Palast des Pharaos und in die Wohnungen seiner Diener und über das ganze Land Ägypten, und das Land litt schwer unter den Hundsfliegen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 21, 'Da ließ der Pharao Mose und Aaron rufen und sagte: »Geht hin und opfert eurem Gott hier im Lande!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 22, 'Da antwortete Mose: »Es geht nicht an, daß wir das tun; denn wir bringen dem HERRN, unserm Gott, Opfer dar, die den Ägyptern ein Greuel sind. Wenn wir nun vor den Augen der Ägypter Opfer darbrächten, die ihnen ein Greuel sind, würden sie uns da nicht steinigen?');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 23, 'Nein, drei Tagereisen weit wollen wir in die Wüste ziehen und dem HERRN, unserm Gott, dort opfern, wie er uns geboten hat.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 24, 'Da sagte der Pharao: »Ich will euch ziehen lassen, damit ihr dem HERRN, eurem Gott, in der Wüste opfern könnt; nur entfernt euch nicht zu weit und legt Fürbitte für mich ein!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 25, 'Mose antwortete: »Sobald ich dich jetzt verlassen habe, will ich beim HERRN Fürbitte einlegen, daß die Hundsfliegen morgen vom Pharao, von seinen Dienern und seinem Volk verschwinden; nur möge dann der Pharao uns nicht abermals täuschen, indem er das Volk doch nicht ziehen läßt, damit es dem HERRN opfern kann!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 26, 'Als Mose hierauf vom Pharao weggegangen war und zum HERRN gebetet hatte,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 27, 'erfüllte der HERR dem Mose seine Bitte: er ließ die Hundsfliegen vom Pharao, von seinen Dienern und seinem Volk verschwinden, so daß keine einzige übrigblieb.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 28, 'Aber der Pharao verstockte sein Herz auch diesmal und ließ das Volk nicht ziehen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 1, 'Hierauf sagte der HERR zu Mose: »Gehe zum Pharao und sage zu ihm: ›So hat der HERR, der Gott der Hebräer, gesprochen: Laß mein Volk ziehen, damit es mir diene!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 2, 'Denn wenn du dich weigerst, es ziehen zu lassen, und sie noch länger zurückhältst,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 3, 'so wird die Hand des HERRN über dein Vieh auf dem Felde kommen, über die Pferde, Esel und Kamele, über die Rinder und das Kleinvieh mit einer sehr schlimmen Seuche.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 4, 'Der HERR wird dabei aber einen Unterschied zwischen dem Vieh der Israeliten und dem Vieh der Ägypter machen, so daß von dem gesamten Besitz der Israeliten kein Stück fallen wird.‹«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 5, 'Darauf setzte der HERR eine bestimmte Zeit fest mit den Worten: »Morgen schon wird der HERR dies im Lande geschehen lassen!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 6, 'Und am andern Tage ließ der HERR dies wirklich eintreten: alles Vieh der Ägypter starb, während vom Vieh der Israeliten kein einziges Stück fiel.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 7, 'Als der Pharao nämlich hinsandte, um nachzusehen, stellte es sich heraus, daß vom Vieh der Israeliten kein einziges Stück gefallen war. Aber das Herz des Pharaos blieb trotzdem verstockt, so daß er das Volk nicht ziehen ließ.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 8, 'Hierauf gebot der HERR dem Mose und Aaron: »Nehmt euch eure beiden Hände voll Ofenruß, und Mose soll ihn vor den Augen des Pharaos himmelwärts streuen!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 9, 'Dann wird er sich als feiner Staub über das ganze Land Ägypten verbreiten und an Menschen und am Vieh zu Beulen werden, die als Geschwüre aufbrechen, im ganzen Lande Ägypten!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 10, 'Da nahmen sie Ofenruß und traten vor den Pharao, und Mose streute ihn himmelwärts; da wurde er zu Beulen, die als Geschwüre an den Menschen und am Vieh aufbrachen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 11, 'Die Zauberer aber konnten nicht vor Mose treten wegen der Beulen; denn die Beulen waren an den Zauberern ebenso wie an allen anderen Ägyptern aufgebrochen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 12, 'Doch der HERR verhärtete das Herz des Pharaos, so daß er nicht auf sie hörte, wie der HERR es dem Mose vorausgesagt hatte. –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 13, 'Hierauf gebot der HERR dem Mose: »Tritt morgen in der Frühe vor den Pharao und sage zu ihm: ›So hat der HERR, der Gott der Hebräer, gesprochen: Laß mein Volk ziehen, damit es mir diene!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 14, 'Denn diesmal will ich alle meine Plagen gegen dich selbst sowie gegen deine Diener und dein Volk loslassen, damit du erkennst, daß niemand mir gleichkommt auf der ganzen Erde!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 15, 'Denn schon jetzt hätte ich meine Hand ausstrecken und dich samt deinem Volk mit der Pest schlagen können, so daß du von der Erde vertilgt worden wärst;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 16, 'aber ich habe dich absichtlich leben lassen, um an dir meine Kraft zu erweisen und damit mein Name auf der ganzen Erde gepriesen wird.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 17, 'Wenn du dich noch länger dagegen sträubst, mein Volk ziehen zu lassen,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 18, 'so will ich morgen um diese Zeit einen sehr schweren Hagel niedergehen lassen, wie ein solcher nie zuvor in Ägypten dagewesen ist vom Tage seiner Gründung an bis jetzt.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 19, 'Sende also hin und laß dein Vieh und alles, was du im Freien hast, in Sicherheit bringen: denn alle Menschen und alle Tiere, die sich im Freien befinden und nicht unter Dach und Fach gebracht worden sind, werden sterben, wenn der Hagel auf sie niederfällt!‹«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 20, 'Wer nun von den Leuten des Pharaos die Drohung des HERRN fürchtete, der brachte seine Knechte und sein Vieh unter Dach und Fach in Sicherheit;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 21, 'wer aber die Drohung des HERRN nicht beachtete, der ließ seine Knechte und sein Vieh im Freien.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 22, 'Da gebot der HERR dem Mose: »Strecke deine Hand gen Himmel aus, damit Hagel in ganz Ägypten falle auf Menschen und Vieh und auf alles, was in Ägypten auf den Feldern gewachsen ist!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 23, 'Als nun Mose seinen Stab gen Himmel ausstreckte, ließ der HERR donnern und hageln, und Feuer fuhr zur Erde nieder, und der HERR ließ Hagel auf Ägypten regnen;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 24, 'mit dem Hagel aber kamen unaufhörliche Blitze mitten in den Hagel hinein so furchtbar, wie man etwas Derartiges in ganz Ägypten noch nicht erlebt hatte, seit es von einem Volk bewohnt war.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 25, 'Der Hagel erschlug in ganz Ägypten alles, was sich im Freien befand, Menschen wie Tiere; auch alle Feldgewächse zerschlug der Hagel und zerschmetterte alle Bäume auf dem Felde.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 26, 'Nur im Lande Gosen, wo die Israeliten wohnten, fiel kein Hagel.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 27, 'Da ließ der Pharao Mose und Aaron rufen und sagte zu ihnen: »Diesmal habe ich mich versündigt: der HERR ist im Recht, ich aber und mein Volk sind im Unrecht!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 28, 'Legt Fürbitte beim HERRN ein; denn der Donnerschläge Gottes und des Hagels ist nun mehr als genug: ich will euch ziehen lassen, und ihr sollt nicht länger hier bleiben!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 29, 'Da antwortete ihm Mose: »Sobald ich zur Stadt hinausgehe, will ich meine Hände zum HERRN ausbreiten; dann werden die Donnerschläge aufhören, und kein Hagel wird mehr fallen, damit du erkennst, daß die Erde dem HERRN gehört.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 30, 'Aber ich weiß wohl: du und deine Diener, ihr fürchtet euch immer noch nicht vor Gott dem HERRN.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 31, 'Der Flachs und die Gerste waren zerschlagen, denn die Gerste stand schon in Ähren und der Flachs in Blüte;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 32, 'aber der Weizen und der Spelt waren nicht zerschlagen, weil sie spätzeitig sind.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 33, 'Als Mose dann vom Pharao hinweg aus der Stadt hinausgegangen war, breitete er seine Hände zum HERRN aus; da hörten die Donnerschläge und der Hagel auf, und auch der Regen strömte nicht mehr auf die Erde nieder.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 34, 'Als nun der Pharao sah, daß der Regen, der Hagel und der Donner aufgehört hatten, fuhr er fort zu sündigen und verstockte sein Herz, er samt seinen Dienern.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 35, 'So blieb denn das Herz des Pharaos hart, und er ließ die Israeliten nicht ziehen, wie der HERR es durch Mose vorausgesagt hatte.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 1, 'Hierauf sagte der HERR zu Mose: »Gehe zum Pharao! Denn ich selbst habe ihm und seinen Dienern das Herz verhärtet, um diese meine Zeichen in ihrer Mitte zu verrichten,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 2, 'und damit du deinen Kindern und Kindeskindern einst erzählen kannst, wie ich gegen die Ägypter vorgegangen bin und welche Zeichen ich unter ihnen vollführt habe: erkennen sollt ihr, daß ich der HERR bin!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 3, 'Da gingen Mose und Aaron zum Pharao und sagten zu ihm: »So hat der HERR, der Gott der Hebräer, gesprochen: ›Wie lange willst du dich noch sträuben, dich vor mir zu demütigen? Laß mein Volk ziehen, damit es mir diene!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 4, 'Denn wenn du dich weigerst, mein Volk ziehen zu lassen, so will ich morgen Heuschrecken in dein Land kommen lassen;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 5, 'die werden die Oberfläche des Erdbodens so bedecken, daß man den Erdboden nicht mehr wird sehen können, und sollen alles auffressen, was von dem Hagelwetter verschont geblieben und euch noch übriggelassen ist; sie sollen auch alle Bäume abfressen, die euch auf dem Felde wachsen;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 6, 'sie sollen auch deine Paläste und die Häuser aller deiner Diener und die Häuser aller Ägypter anfüllen, wie es deine Väter und die Väter deiner Väter, seitdem sie auf dem Erdboden gewesen sind, bis auf den heutigen Tag nicht erlebt haben!‹« Damit wandte er sich und verließ den Pharao.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 7, 'Da sagten die Diener des Pharaos zu ihm: »Wie lange soll dieser Mensch uns noch unglücklich machen? Laß doch die Leute ziehen, damit sie dem HERRN, ihrem Gott, dienen! Siehst du noch nicht ein, daß Ägypten zugrunde gerichtet wird?«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 8, 'Hierauf holte man Mose und Aaron zum Pharao zurück, und er sagte zu ihnen: »Zieht hin und dient dem HERRN, eurem Gott! Wer soll denn alles hinziehen?«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 9, 'Da antwortete Mose: »Mit jung und alt wollen wir hinausziehen, mit unsern Söhnen und unsern Töchtern, mit unserm Kleinvieh und unsern Rindern wollen wir hinausziehen; denn wir haben ein Fest des HERRN zu feiern.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 10, 'Da antwortete er ihnen: »Möge der HERR ebenso mit euch sein, wie ich euch mit Weib und Kind ziehen lasse! Seht ihr wohl, daß ihr Böses im Sinn habt?');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 11, 'Daraus wird nichts! Ihr Männer mögt hinziehen und dem HERRN dienen: das ist ja auch euer Begehr gewesen!« Hierauf wies man sie vom Pharao weg.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 12, 'Da gebot der HERR dem Mose: »Strecke deine Hand über das Land Ägypten aus, damit die Heuschrecken über das Land kommen und alle Feldgewächse abfressen, alles, was der Hagel übriggelassen hat!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 13, 'Da streckte Mose seinen Stab über das Land Ägypten aus, und der HERR ließ einen Ostwind über das Land hin wehen jenen ganzen Tag und die ganze Nacht; als es dann Morgen wurde, hatte der Ostwind die Heuschrecken herbeigebracht.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 14, 'So kamen denn die Heuschrecken über das ganze Land Ägypten und ließen sich in allen Teilen Ägyptens in gewaltiger Menge nieder; nie zuvor waren so viele Heuschrecken dagewesen wie damals, und künftig wird es nie wieder so viele geben.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 15, 'Sie bedeckten die Oberfläche des ganzen Landes, so daß der Erdboden nicht mehr zu sehen war, und sie fraßen alle Feldgewächse ab und alle Baumfrüchte, die der Hagel übriggelassen hatte, so daß nichts Grünes mehr an den Bäumen und an den Feldgewächsen im ganzen Lande Ägypten übrigblieb.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 16, 'Da ließ der Pharao in aller Eile Mose und Aaron rufen und sagte: »Ich habe mich am HERRN, eurem Gott, und an euch versündigt!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 17, 'Und nun vergib mir meine Verfehlung nur noch dies eine Mal und betet zum HERRN, eurem Gott, daß er wenigstens dieses Verderben von mir abwende!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 18, 'Als nun (Mose) vom Pharao weggegangen war und zum HERRN gebetet hatte,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 19, 'da wandte der HERR den Wind, so daß er sehr stark aus dem Westen wehte; der hob die Heuschrecken auf und warf sie ins Schilfmeer, so daß keine einzige Heuschrecke im ganzen Bereich von Ägypten übrigblieb.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 20, 'Aber der HERR verhärtete das Herz des Pharaos, so daß er die Israeliten nicht ziehen ließ.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 21, 'Hierauf gebot der HERR dem Mose: »Strecke deine Hand gen Himmel aus, damit eine Finsternis über das Land Ägypten komme, so dicht, daß man sie greifen kann.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 22, 'Als nun Mose seine Hand gen Himmel ausgestreckt hatte, entstand eine Finsternis im ganzen Land Ägypten drei Tage lang.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 23, 'Kein Mensch konnte den andern sehen, und keiner erhob sich von seinem Platz drei Tage lang; aber die Israeliten hatten alle hellen Tag in ihren Wohnsitzen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 24, 'Da ließ der Pharao Mose rufen und sagte: »Zieht hin, dient dem HERRN! Nur euer Kleinvieh und eure Rinder sollen hier zurückbleiben; auch eure Frauen und Kinder mögen mit euch gehen!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 25, 'Da antwortete Mose: »Nicht nur mußt du selbst uns Tiere zu Schlacht- und Brandopfern mitgeben, damit wir sie dem HERRN, unserm Gott, darbringen,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 26, 'sondern auch unser Vieh muß mit uns ziehen: keine Klaue darf zurückbleiben! Denn davon müssen wir Tiere zur Verehrung des HERRN, unsers Gottes, nehmen; wir wissen ja nicht, was wir dem HERRN zu opfern haben, ehe wir an Ort und Stelle sind.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 27, 'Aber der HERR verhärtete das Herz des Pharaos, so daß er sie nicht ziehen lassen wollte,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 28, 'sondern zu Mose sagte: »Hinweg von mir! Hüte dich, mir nochmals vor die Augen zu treten! Denn sobald du dich wieder vor mir sehen läßt, bist du des Todes!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 29, 'Da antwortete Mose: »Du hast recht geredet: ich werde dir nicht wieder vor die Augen treten!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 11, 1, 'Darauf sagte der HERR zu Mose: »Noch eine einzige Plage will ich über den Pharao und über Ägypten kommen lassen; alsdann wird er euch von hier ziehen lassen, ja er wird, wenn er euch bedingungslos entläßt, euch sogar gewaltsam von hier wegtreiben.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 11, 2, 'Gib nun dem Volke die bestimmte Weisung, daß sie sich insgesamt, Männer wie Weiber, silberne und goldene Wertsachen von ihren Nachbarn und Nachbarinnen erbitten.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 11, 3, 'Der HERR stimmte dann die Ägypter günstig gegen das Volk; auch stand Mose in den Augen der Diener des Pharaos und des ganzen ägyptischen Volkes als ein großer Mann da.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 11, 4, 'Hierauf sagte Mose: »So hat der HERR gesprochen: ›Um Mitternacht will ich mitten durch Ägypten schreiten;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 11, 5, 'da soll dann jede Erstgeburt in Ägypten sterben, vom erstgeborenen Sohn des Pharaos an, der auf seinem Thron sitzt, bis zum Erstgeborenen der Magd, die hinter der Handmühle sitzt, auch alles Erstgeborene vom Vieh.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 11, 6, 'Da wird sich ein großes Wehgeschrei im ganzen Land Ägypten erheben, wie ein solches noch nie dagewesen ist und nie wieder stattfinden wird.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 11, 7, 'Aber gegen keinen Israeliten, weder gegen einen Menschen noch gegen das Vieh, soll auch nur ein Hund ein Knurren hören lassen, damit ihr erkennt, daß der HERR eine Scheidung zwischen den Ägyptern und den Israeliten macht.‹');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 11, 8, 'Dann werden alle diese deine Diener zu mir herabkommen, sich vor mir niederwerfen und bitten: ›Ziehe weg, du und das ganze Volk, das deiner Leitung folgt!‹, und danach werde ich wegziehen.« Hierauf ging (Mose) vom Pharao weg in glühendem Zorn.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 11, 9, 'Der HERR hatte aber zu Mose gesagt: »Der Pharao wird nicht auf euch hören, damit meine Wunder in Ägypten zahlreich werden.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 11, 10, 'So haben denn Mose und Aaron alle diese Wunder vor dem Pharao vollführt; aber der HERR verstockte das Herz des Pharaos, so daß er die Israeliten aus seinem Lande nicht ziehen ließ.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 1, 'Darauf gebot der HERR dem Mose und Aaron im Lande Ägypten folgendes:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 2, '»Der gegenwärtige Monat soll euch als Anfangsmonat gelten! Der erste soll er euch unter den Monaten des Jahres sein!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 3, 'Gebt der ganzen Gemeinde Israel folgende Weisungen: Am zehnten Tage dieses Monats, da nehme sich jeder (Hausvater) ein Lamm, für je eine Familie ein Lamm;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 4, 'und wenn eine Familie zu klein für ein ganzes Lamm ist, so nehme er und sein ihm zunächst wohnender Nachbar eins gemeinsam nach der Zahl der Seelen! Ihr sollt auf das Lamm so viele Personen rechnen, als zum Verzehren erforderlich sind!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 5, 'Es müssen fehlerlose, männliche, einjährige Lämmer sein; von den Schafen oder von den Ziegen sollt ihr sie nehmen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 6, 'Bis zum vierzehnten Tage dieses Monats sollt ihr sie in Verwahrung haben; dann soll die gesamte Volksgemeinde Israel sie zwischen den beiden Abenden schlachten!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 7, 'Hierauf sollen sie etwas von dem Blut nehmen und es an die beiden Türpfosten und an die Oberschwelle an den Häusern streichen, in denen sie die Mahlzeit halten.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 8, 'Sie sollen dann das Fleisch noch in derselben Nacht essen, und zwar am Feuer gebraten, und dazu ungesäuertes Brot; mit bitteren Kräutern sollen sie es essen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 9, 'Ihr dürft nichts davon roh oder im Wasser gekocht genießen, sondern am Feuer gebraten, und zwar so, daß der Kopf noch mit den Beinen und mit dem Rumpf zusammenhängt!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 10, 'Ihr dürft nichts davon bis zum andern Morgen übriglassen, sondern was etwa davon bis zum Morgen übrigbleibt, sollt ihr im Feuer verbrennen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 11, 'Und auf folgende Weise sollt ihr es essen: eure Hüften gegürtet, eure Schuhe an den Füßen und euren Stab in der Hand; und in ängstlicher Hast sollt ihr es essen: ein Vorübergehen des HERRN ist es.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 12, 'Denn ich will in dieser Nacht durch das Land Ägypten schreiten und alle Erstgeburt in Ägypten sterben lassen sowohl von den Menschen als vom Vieh, und ich will an allen ägyptischen Göttern ein Strafgericht vollziehen, ich, der HERR!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 13, 'Dabei soll dann das Blut an den Häusern, in denen ihr euch befindet, ein Zeichen zu eurem Schutz sein; denn wenn ich das Blut sehe, will ich schonend an euch vorübergehen, und es soll euch kein tödliches Verderben treffen, wenn ich den Schlag gegen das Land Ägypten führe.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 14, '»Dieser Tag soll dann für euch ein Gedächtnistag sein, den ihr zu Ehren des HERRN festlich begehen sollt! Von Geschlecht zu Geschlecht sollt ihr ihn als eine ewige Satzung feiern!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 15, 'Sieben Tage lang sollt ihr ungesäuertes Brot essen; gleich am ersten Tage sollt ihr allen Sauerteig aus euren Häusern entfernen; denn jeder, der vom ersten bis zum siebten Tage Gesäuertes ißt, ein solcher Mensch soll aus Israel ausgerottet werden!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 16, 'Weiter soll am ersten Tage eine heilige Festversammlung bei euch stattfinden und ebenso am siebten Tage eine heilige Festversammlung: keinerlei Arbeit darf an diesen (beiden Tagen) verrichtet werden! Nur was ein jeder zum Essen nötig hat, das allein darf von euch zubereitet werden!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 17, 'So beobachtet denn das Fest der ungesäuerten Brote! Denn an eben diesem Tage habe ich eure Heerscharen aus dem Land Ägypten hinausgeführt; darum sollt ihr diesen Tag von Geschlecht zu Geschlecht als eine ewige Satzung beobachten!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 18, 'Im ersten Monat, am vierzehnten Tage des Monats, am Abend sollt ihr ungesäuertes Brot essen bis zum Abend des einundzwanzigsten Tages des Monats!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 19, 'Sieben Tage lang darf kein Sauerteig in euren Häusern zu finden sein; denn wer da Gesäuertes ißt, ein solcher Mensch soll aus der Gemeinde Israel ausgerottet werden, er sei ein Fremder oder ein Einheimischer im Lande!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 20, 'Nichts Gesäuertes dürft ihr essen: überall, wo ihr auch wohnen mögt, sollt ihr ungesäuertes Brot essen!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 21, 'Da berief Mose alle Ältesten der Israeliten und sagte zu ihnen: »Geht hin und holt euch Kleinvieh, für jede Familie ein Stück, und schlachtet es als Passah!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 22, 'Dann nehmt einen Büschel Ysop, taucht ihn in das Blut im Becken und streicht etwas von dem Blut im Becken an die Oberschwelle und an die beiden Pfosten der Tür; keiner von euch darf aber bis zum andern Morgen aus der Tür seines Hauses hinausgehen!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 23, 'Wenn dann der HERR einherschreitet, um die Ägypter sterben zu lassen, und er das Blut an der Oberschwelle und an den beiden Türpfosten sieht, so wird der HERR an der Tür schonend vorübergehen und dem Würgengel nicht gestatten, in eure Häuser einzutreten, um euch sterben zu lassen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 24, 'Ihr sollt aber dieses Gebot als eine Satzung für euch und eure Kinder auf ewige Zeiten beobachten!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 25, 'Auch wenn ihr in das Land kommt, das der HERR euch nach seiner Verheißung geben wird, sollt ihr diesen heiligen Brauch stets beobachten!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 26, 'Wenn eure Kinder euch dann fragen: ›Was bedeutet dieser Brauch bei euch?‹,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 27, 'so sollt ihr antworten: ›Es ist das Passahopfer für den HERRN, der in Ägypten an den Häusern der Israeliten schonend vorübergegangen ist: während er die Ägypter sterben ließ, hat er unsere Häuser verschont.‹« Da verneigte sich das Volk und warf sich zur Erde nieder.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 28, 'Hierauf gingen die Israeliten hin und taten so; wie der HERR dem Mose und Aaron geboten hatte, so taten sie.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 29, 'Um Mitternacht aber begab es sich, daß der HERR alle Erstgeburten im Lande Ägypten sterben ließ, vom erstgeborenen Sohn des Pharaos an, der auf seinem Thron saß, bis zum Erstgeborenen des Gefangenen, der im Kerker lag, auch alles Erstgeborene des Viehs.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 30, 'Da stand der Pharao in dieser Nacht auf, er und alle seine Diener und alle übrigen Ägypter, und es erhob sich ein großes Wehgeschrei in Ägypten; denn es gab kein Haus, in dem nicht ein Toter gelegen hätte.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 31, 'Da ließ (der Pharao) noch in der Nacht Mose und Aaron rufen und sagte: »Macht euch auf, zieht aus meinem Volk hinweg, sowohl ihr als auch die Israeliten! Geht hin und dient dem HERRN, wie ihr gesagt habt!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 32, 'Auch euer Kleinvieh und eure Rinder nehmt mit, wie ihr gesagt habt: geht hin und bittet auch für mich um Segen!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 33, 'Auch die Ägypter drängten das Volk zu schleunigem Aufbruch aus dem Lande; denn sie dachten: »Wir sind (sonst) alle des Todes!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 34, 'Da nahm das Volk seinen Brotteig, noch ehe er gesäuert war, ihre Backschüsseln, die sie, in ihre Mäntel gewickelt, auf den Schultern trugen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 35, 'Die Israeliten hatten aber (zuvor) die Weisung Moses befolgt und sich von den Ägyptern silberne und goldene Wertsachen sowie Kleider erbeten;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 36, 'und der HERR hatte dabei die Ägypter gegen das Volk günstig gestimmt, so daß sie ihnen das Erbetene gewährten; und so plünderten sie die Ägypter aus.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 37, 'So brachen denn die Israeliten von Ramses nach Sukkoth zu auf, ungefähr 600000 Mann zu Fuß, die Männer allein, ungerechnet die Weiber und Kinder.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 38, 'Auch viel zusammengelaufenes Volk zog mit ihnen, dazu Kleinvieh und Rinder, eine gewaltige Menge Vieh.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 39, 'Aus dem Teig aber, den sie aus Ägypten mitgenommen hatten, buken sie (unterwegs) ungesäuerte Brotkuchen; denn er war ungesäuert, weil man sie aus Ägypten vertrieben und ihnen keine Zeit gelassen hatte; daher hatten sie auch für keine Wegzehrung sorgen können.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 40, 'Die Zeit aber, während welcher die Israeliten in Ägypten gewohnt hatten, betrug 430 Jahre;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 41, 'und nach Ablauf dieser 430 Jahre, und zwar an eben jenem Tage, zogen alle Heerscharen des HERRN aus dem Land Ägypten weg.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 42, 'Eine Nacht des Wachens für den HERRN war das, damit er sie aus Ägypten wegführe; eben diese Nacht ist dem HERRN geweiht als ein von allen Israeliten für alle ihre künftigen Geschlechter zu beobachtendes Wachen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 43, 'Da sagte der HERR zu Mose und Aaron: »Dies ist die Verordnung für das Passah: Kein Fremder darf davon essen;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 44, 'aber jeder für Geld gekaufte Knecht darf davon essen, sobald er beschnitten worden ist.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 45, 'Ein Beisasse oder Lohnarbeiter dürfen nicht davon essen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 46, 'In einem und demselben Hause muß es gegessen werden; man darf nichts von dem Fleisch aus dem Hause hinausbringen, und keinen Knochen dürft ihr an ihm zerbrechen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 47, 'Die ganze Gemeinde der Israeliten soll es feiern;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 48, 'und wenn ein Fremder sich unter euch aufhält und das Passah zu Ehren des HERRN feiern will, so müssen zuvor alle männlichen Personen seiner Familie beschnitten werden: alsdann darf er an der Feier teilnehmen und soll den Einheimischen des Landes gleichgeachtet sein; aber kein Unbeschnittener darf davon essen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 49, 'Ein und dasselbe Gesetz soll für den Einheimischen und für den Fremden gelten, der in eurer Mitte weilt!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 50, 'Da taten alle Israeliten so; wie der HERR dem Mose und Aaron geboten hatte, genau so taten sie. –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 51, 'An eben diesem Tage, an welchem der HERR die Israeliten aus Ägypten nach ihren Heerscharen hinwegführte,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 13, 1, 'gebot der HERR dem Mose folgendes:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 13, 2, '»Heilige mir alles Erstgeborene, alles, was bei den Israeliten zuerst aus dem Mutterschoß ans Tageslicht hervortritt, von Menschen wie vom Vieh: es gehört mir!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 13, 3, 'Hierauf sagte Mose zum Volk: »Gedenkt des heutigen Tages, an dem ihr aus Ägypten weggezogen seid, aus dem Hause der Knechtschaft! Denn mit starker Hand hat der HERR euch von dort weggeführt; daher darf nichts Gesäuertes gegessen werden!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 13, 4, 'Heute zieht ihr aus im Monat Abib.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 13, 5, 'Wenn dich nun der HERR in das Land der Kanaanäer, Hethiter, Amoriter, Hewiter und Jebusiter gebracht hat, dessen Verleihung er deinen Vätern einst zugeschworen hat, ein Land, das von Milch und Honig überfließt, so sollst du diesen heiligen Brauch in diesem Monat beobachten:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 13, 6, 'Sieben Tage lang sollst du ungesäuertes Brot essen, und am siebten Tage findet ein Fest zu Ehren des HERRN statt!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 13, 7, 'Während der sieben Tage soll ungesäuertes Brot gegessen werden, und nichts Gesäuertes und kein Sauerteig darf in deinem ganzen Gebiet zu finden sein!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 13, 8, 'Deinen Kindern aber sollst du an diesem Tage folgendes kundtun: ›(Diesen Brauch beobachte ich) zur Erinnerung an das, was der HERR an mir getan hat, als ich aus Ägypten auszog.‹');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 13, 9, 'Und (dieser Brauch) soll dir gleichsam ein Denkzeichen an deiner Hand und ein Erinnerungsmal auf deiner Stirn sein, damit das Gesetz des HERRN in deinem Munde lebendig bleibt; denn mit starker Hand hat der HERR dich aus Ägypten weggeführt.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 13, 10, 'Darum sollst du diese Satzung zur bestimmten Zeit Jahr für Jahr beobachten!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 13, 11, '»Wenn der HERR dich dann, wie er es dir und deinen Vätern zugeschworen hat, in das Land der Kanaanäer gebracht und es dir zum Besitz gegeben hat,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 13, 12, 'so sollst du dem HERRN alles weihen, was zuerst aus dem Mutterschoß ans Tageslicht hervortritt! Auch jeder erste Wurf des Viehs, der dir zuteil wird, soweit er männlich ist, gehört dem HERRN.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 13, 13, 'Jedes erstgeborene Eselfüllen aber sollst du mit einem Stück Kleinvieh loskaufen; oder, wenn du es nicht loskaufen willst, so brich ihm das Genick! Weiter sollst du jede Erstgeburt vom Menschen bei deinen Söhnen loskaufen!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 13, 14, 'Wenn dann dein Sohn künftig die Frage an dich richtet: ›Was bedeutet dieser Brauch?‹, so antworte ihm: ›Mit starker Hand hat der HERR uns aus Ägypten, aus dem Hause der Knechtschaft, weggeführt.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 13, 15, 'Denn weil der Pharao sich hartnäckig dagegen sträubte, uns ziehen zu lassen, hat der HERR alle Erstgeburt in Ägypten sterben lassen, von den Erstgeborenen der Menschen an bis zur Erstgeburt des Viehs; darum opfere ich dem HERRN alle männlichen Erstgeburten, aber jeden Erstgeborenen meiner Söhne kaufe ich los.‹');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 13, 16, 'Und dieser Brauch soll dir gleichsam ein Denkzeichen an deiner Hand und ein Erinnerungsmal auf deiner Stirn sein; denn mit starker Hand hat der HERR uns aus Ägypten weggeführt!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 13, 17, 'Als nun der Pharao das Volk hatte ziehen lassen, führte Gott sie nicht in der Richtung nach dem Lande der Philister, obgleich dies der nächste Weg gewesen wäre; denn Gott dachte: Das Volk könnte es sich gereuen lassen, wenn es Krieg in Aussicht hätte, und möchte wieder nach Ägypten zurückkehren.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 13, 18, 'Darum ließ Gott das Volk sich seitwärts in der Richtung nach der Wüste, gegen das Schilfmeer hin, wenden, und kampfgerüstet zogen die Israeliten aus Ägypten ab.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 13, 19, 'Mose nahm aber die Gebeine Josephs mit; denn dieser hatte die Israeliten feierlich schwören lassen und gebeten: »Wenn Gott sich einst an euch gnädig erweist, dann nehmt meine Gebeine von hier mit euch!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 13, 20, 'So brachen sie denn von Sukkoth auf und lagerten in Etham am Rande der Wüste.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 13, 21, 'Der HERR aber zog vor ihnen her, bei Tage in einer Wolkensäule, um ihnen den Weg zu zeigen, und nachts in einer Feuersäule, um ihnen zu leuchten, damit sie bei Tag und bei Nacht wandern könnten:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 13, 22, 'nicht wich die Wolkensäule bei Tage und nicht die Feuersäule nachts von der Spitze des Zuges.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 1, 'Da gebot der HERR dem Mose folgendes:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 2, '»Befiehl den Israeliten umzukehren und östlich von Pi-Hahiroth zwischen Migdol und dem Meer zu lagern! Gerade gegenüber von Baal-Zephon sollt ihr am Meer lagern!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 3, 'Dann wird der Pharao von den Israeliten denken: ›Ratlos irren sie im Lande umher, die Wüste hält sie umschlossen!‹');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 4, 'Dann will ich das Herz des Pharaos verhärten, daß er sie verfolgt, damit ich mich am Pharao und an seiner ganzen Heeresmacht verherrliche und damit die Ägypter erkennen, daß ich der HERR bin.« Und sie taten so.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 5, 'Als nun dem König von Ägypten gemeldet wurde, daß das Volk entwichen sei, trat bei ihm und seinen Dienern eine Sinnesänderung dem Volk gegenüber ein, und sie sagten: »Was haben wir da getan, daß wir die Israeliten aus unserm Dienst entlassen haben!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 6, 'So ließ er denn seinen Streitwagen anschirren und nahm sein Kriegsvolk mit sich;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 7, 'sechshundert auserlesene Kriegswagen nahm er mit und was sonst an Kriegswagen in Ägypten vorhanden war und die besten Kämpfer auf einem jeden von ihnen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 8, 'Denn der HERR hatte das Herz des Pharaos, des Königs von Ägypten, verhärtet, so daß er die Israeliten verfolgte, obgleich diese mit hocherhobener Hand ausgezogen waren.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 9, 'So setzten denn die Ägypter ihnen nach und holten sie ein, als sie sich eben am Meer gelagert hatten, alle Rosse und Wagen des Pharaos, seine Reiter und überhaupt seine Heeresmacht, bei Pi-Hahiroth, Baal-Zephon gegenüber.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 10, 'Als nun der Pharao nahe herangekommen war und die Israeliten hinschauten und die Ägypter erblickten, die hinter ihnen herzogen, da gerieten die Israeliten in große Angst und schrien zum HERRN');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 11, 'und sagten zu Mose: »Hast du uns etwa deshalb, weil es in Ägypten keine Gräber gab, mitgenommen, damit wir in der Wüste sterben? Was hast du uns da angetan, daß du uns aus Ägypten weggeführt hast!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 12, 'Haben wir dir nicht schon in Ägypten aufs bestimmteste erklärt: ›Laß uns in Ruhe: wir wollen den Ägyptern dienen!‹; denn besser wäre es für uns, den Ägyptern zu dienen, als hier in der Wüste zu sterben!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 13, 'Da entgegnete Mose dem Volk: »Fürchtet euch nicht! Haltet nur stand, so werdet ihr sehen, welche Rettung euch der HERR heute noch schaffen wird! Denn so, wie ihr die Ägypter heute seht, werdet ihr sie in alle Ewigkeit nicht wieder sehen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 14, 'Der HERR wird für euch streiten, verhaltet ihr euch nur ruhig!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 15, 'Da sagte der HERR zu Mose: »Was schreist du zu mir? Befiehl den Israeliten aufzubrechen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 16, 'Du aber hebe deinen Stab empor, strecke deine Hand über das Meer aus und spalte es, damit die Israeliten mitten durch das Meer hindurch auf trockenem Boden ziehen können.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 17, 'Ich aber will dann das Herz der Ägypter verhärten, daß sie hinter ihnen herziehen, und will mich am Pharao und an seiner ganzen Heeresmacht, an seinen Wagen und Reitern, verherrlichen;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 18, 'und die Ägypter sollen erkennen, daß ich der HERR bin, wenn ich mich am Pharao, an seinen Wagen und Reitern verherrlicht habe.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 19, 'Da änderte der Engel Gottes, der (bisher) vor dem Heer der Israeliten hergezogen war, seine Stellung und trat hinter sie; infolgedessen ging auch die Wolkensäule vorn vor ihnen weg und trat hinter sie,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 20, 'so daß sie zwischen das Heer der Ägypter und das Heer der Israeliten zu stehen kam; und sie zeigte sich dort als Wolke und Finsternis, während sie hier die Nacht erleuchtete; so gerieten beide Heere die ganze Nacht hindurch nicht feindlich aneinander.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 21, 'Als dann Mose seine Hand über das Meer ausstreckte, drängte der HERR das Meer durch einen starken Ostwind die ganze Nacht hindurch zurück und legte den Meeresboden trocken, und die Wasser spalteten sich.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 22, 'So gingen denn die Israeliten trocknen Fußes mitten durch das Meer, während die Wasser ihnen wie eine Wand zur Rechten und zur Linken standen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 23, 'Die Ägypter aber eilten ihnen nach und zogen hinter ihnen her, alle Rosse des Pharaos, seine Wagen und seine Reiter, mitten ins Meer hinein.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 24, 'Zur Zeit der Morgenwache aber schaute der HERR in der Feuer- und Wolkensäule hin auf das Heer der Ägypter und brachte ihren Zug in Verwirrung;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 25, 'er ließ die Räder ihrer Wagen abspringen und machte, daß sie nur mühsam vorwärts kamen. Da riefen die Ägypter: »Laßt uns vor den Israeliten fliehen, denn der HERR streitet für sie gegen die Ägypter!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 26, 'Da gebot der HERR dem Mose: »Strecke deine Hand über das Meer aus: damit die Wasser auf die Ägypter, auf ihre Wagen und ihre Reiter, zurückströmen!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 27, 'So streckte denn Mose seine Hand über das Meer aus, da kehrte das Meer bei Tagesanbruch in sein altes Bett zurück, während die Ägypter ihm gerade entgegen flohen; und der HERR stürzte die Ägypter mitten ins Meer hinein.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 28, 'Denn als die Wasser zurückgeströmt waren, bedeckten sie die Wagen und die Reiter der ganzen Heeresmacht des Pharaos, die hinter ihnen her ins Meer gezogen waren, so daß auch nicht einer von ihnen am Leben blieb.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 29, 'Die Israeliten aber waren trocknen Fußes mitten durch das Meer gezogen, während die Wasser ihnen wie eine Wand zur Rechten und zur Linken standen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 30, 'So rettete der HERR die Israeliten an diesem Tage aus der Hand der Ägypter, und Israel sah die Ägypter tot am Meeresufer liegen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 31, 'Als die Israeliten aber die große Wundertat sahen, die der HERR an den Ägyptern vollbracht hatte, da fürchtete das Volk den HERRN, und sie glaubten an den HERRN und an seinen Knecht Mose.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 1, 'Damals sangen Mose und die Israeliten zum Preise des HERRN folgendes Lied: Singen will ich dem HERRN, denn hocherhaben ist er; Rosse und Reiter hat er ins Meer gestürzt.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 2, 'Meine Stärke und mein Lobgesang ist der HERR, der mir Rettung geschafft hat; er ist mein Gott: ihn will ich preisen, meiner Väter Gott: ihn will ich erheben!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 3, 'Der HERR ist ein Kriegsheld, HERR ist sein Name.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 4, 'Die Wagen des Pharaos und seine Macht hat er ins Meer gestürzt, seine auserlesenen Krieger sind im Schilfmeer versunken.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 5, 'Die Fluten haben sie bedeckt, wie Steine sind sie in die Tiefen gefahren.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 6, 'Deine Rechte, o HERR, ist herrlich durch Kraft; deine Rechte, o HERR, zerschmettert den Feind.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 7, 'Durch die Fülle deiner Hoheit vernichtest du deine Gegner; du läßt deine Zornglut ausgehn: die verzehrt sie wie Spreu.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 8, 'Durch den Hauch deiner Nase türmten die Wasser sich hoch, wie ein Wall standen die Fluten aufrecht, die Wogen erstarrten mitten im Meer.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 9, 'Da dachte der Feind: »Ich will nachsetzen, einholen, will Beute verteilen, meine Gier soll sich letzen an ihnen! zücken will ich mein Schwert, meine Hand soll sie tilgen!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 10, 'Da bliesest du mit deinem Odem: das Meer bedeckte sie; wie Blei versanken sie in den gewaltigen Wogen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 11, 'Wer ist dir gleich, HERR, unter den Göttern? wer ist wie du so herrlich an Majestät, furchtbar an Ruhmeswerken, ein Wundertäter?');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 12, 'Du hast deine Rechte ausgestreckt: da verschlang sie die Erde.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 13, 'Mit deiner Huld hast du das Volk geleitet, das du erlöst hast; mit deiner Kraft hast du es geführt zu deiner heiligen Wohnstatt.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 14, 'Die Völker vernahmen’s und bebten, Angst befiel die Bewohner des Philisterlandes.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 15, 'Da erschraken die Fürsten von Edom, Zittern ergriff die Häuptlinge Moabs, die Bewohner Kanaans verzagten alle;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 16, 'Entsetzen und Angst überfiel sie; ob der Kraft deines Armes wurden sie starr wie ein Stein, bis dein Volk hindurchzog, HERR, bis das Volk hindurchzog, das du erworben.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 17, 'Du brachtest sie hinein und pflanztest sie ein auf den Berg deines Eigentums, an die Stätte, die du, HERR, zur Wohnung dir bereitet, in das Heiligtum, Herr, das deine Hände gegründet.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 18, 'Der HERR ist König immer und ewig!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 19, 'Als nämlich die Rosse des Pharaos mit seinen Wagen und Reitern ins Meer gekommen waren, hatte der HERR die Fluten des Meeres über sie zurückströmen lassen, während die Israeliten trocknen Fußes mitten durchs Meer gezogen waren.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 20, 'Darauf nahm die Prophetin Mirjam, Aarons Schwester, die Handpauke zur Hand, und alle Frauen zogen mit Handpauken und im Reigenschritt tanzend hinter ihr her.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 21, 'Und Mirjam sang den Männern als Antwort zu: Singet dem HERRN! Denn hocherhaben ist er; Rosse und Reiter hat er ins Meer gestürzt!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 22, 'Hierauf ließ Mose die Israeliten vom Schilfmeer aufbrechen, und sie zogen weiter in die Wüste Sur hinein; drei Tage lang wanderten sie in der Wüste, ohne Wasser zu finden.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 23, 'Als sie dann nach Mara kamen, konnten sie das Wasser dort nicht trinken, weil es bitter war; daher hieß der Ort Mara.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 24, 'Da murrte das Volk gegen Mose und sagte: »Was sollen wir trinken?«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 25, 'Da flehte er laut zum HERRN, und der HERR zeigte ihm ein Holz; als Mose dieses in das Wasser geworfen hatte, wurde das Wasser süß. Dort gab er dem Volk Gesetze und Verordnungen und stellte es dort auf die Probe,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 26, 'indem er sagte: »Wenn du auf die Weisungen des HERRN, deines Gottes, willig hörst und das tust, was ihm wohlgefällt, wenn du seinen Befehlen gehorchst und alle seine Gebote beobachtest, so will ich von allen Heimsuchungen, die ich über die Ägypter verhängt habe, keine über dich kommen lassen; denn ich, der HERR, bin dein Arzt.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 27, 'Hierauf kamen sie nach Elim; dort waren zwölf Wasserquellen und siebzig Palmbäume; und sie lagerten dort am Wasser.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 1, 'Dann brachen sie von Elim auf, und die ganze Gemeinde der Israeliten gelangte in die Wüste Sin, die zwischen Elim und dem Sinai liegt, am fünfzehnten Tage des zweiten Monats nach ihrem Auszug aus dem Lande Ägypten.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 2, 'Da murrte die ganze Gemeinde der Israeliten gegen Mose und Aaron in der Wüste;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 3, 'und die Israeliten sagten zu ihnen: »Wären wir doch durch die Hand des HERRN in Ägypten gestorben, als wir bei den Fleischtöpfen saßen und reichlich Brot zu essen hatten! Jetzt habt ihr uns in diese Wüste hinausgeführt, um diese ganze Volksgemeinde Hungers sterben zu lassen!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 4, 'Da sagte der HERR zu Mose: »Gut! Ich will euch Brot vom Himmel regnen lassen; das Volk braucht dann nur hinauszugehen und sich seinen täglichen Bedarf Tag für Tag zu sammeln; damit will ich es auf die Probe stellen, ob es nach meinen Weisungen wandeln will oder nicht.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 5, 'Wenn sie aber am sechsten Tage das, was sie heimgebracht haben, zubereiten, so wird es das Doppelte von dem sein, was sie sonst tagtäglich gesammelt haben.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 6, 'Da sagten Mose und Aaron zu allen Israeliten: »Heute abend werdet ihr erkennen, daß der HERR es gewesen ist, der euch aus Ägypten weggeführt hat;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 7, 'und morgen früh, da werdet ihr die Herrlichkeit des HERRN zu sehen bekommen! Denn er hat gehört, wie ihr gegen ihn gemurrt habt; wir dagegen – was sind wir, daß ihr gegen uns murren könntet?«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 8, 'Dann fuhr Mose fort: »Ja, daran werdet ihr (die Herrlichkeit des HERRN) erkennen, daß der HERR euch heute abend Fleisch zu essen gibt und morgen früh Brot zum Sattwerden, weil der HERR gehört hat, wie ihr gegen ihn laut gemurrt habt. Denn was sind wir? Euer Murren ist nicht gegen uns gerichtet, sondern gegen den HERRN.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 9, 'Hierauf sagte Mose zu Aaron: »Befiehl der ganzen Gemeinde der Israeliten: ›Tretet heran vor den HERRN; denn er hat euer Murren gehört!‹«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 10, 'Als dann Aaron dies der ganzen Gemeinde der Israeliten mitgeteilt hatte und sie sich nach der Wüste hin gewandt hatten, da erschien plötzlich die Herrlichkeit des HERRN in der Wolke.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 11, 'Darauf sagte der HERR zu Mose:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 12, '»Ich habe das Murren der Israeliten gehört; mache ihnen folgendes bekannt: ›Gegen Abend sollt ihr Fleisch zu essen bekommen und morgen früh euch an Brot satt essen und sollt erkennen, daß ich, der HERR, euer Gott bin.‹«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 13, 'Und wirklich: am Abend kamen Wachteln herangezogen und bedeckten das Lager; und am anderen Morgen lag eine Tauschicht rings um das Lager her;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 14, 'und als die Tauschicht vergangen war, da lag überall auf der Wüstenfläche etwas Feines, Körniges, fein wie der Reif auf der Erde.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 15, 'Als das die Israeliten sahen, fragten sie einer den andern: »Was ist das?«; denn sie wußten nicht, was es war. Da sagte Mose zu ihnen: »Dies ist das Brot, das der HERR euch zum Essen gegeben hat.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 16, '»Folgendes ist es, was der HERR euch gebietet: ›Sammelt euch davon, jeder soviel er für sich zum Essen nötig hat, je einen Gomer für den Kopf; nach der Zahl der Seelen, die jeder in seinem Zelt hat, sollt ihr euch holen.‹«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 17, 'Da taten die Israeliten so und sammelten, der eine viel, der andere wenig;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 18, 'als sie es dann aber mit dem Gomer maßen, da hatte der, welcher viel gesammelt hatte, keinen Überschuß, und wer wenig gesammelt hatte, dem mangelte nichts: jeder hatte so viel gesammelt, als er zu seiner Nahrung bedurfte.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 19, 'Hierauf befahl ihnen Mose: »Niemand hebe etwas davon bis zum anderen Morgen auf!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 20, 'Aber sie hörten nicht auf Mose, sondern manche hoben etwas davon bis zum anderen Morgen auf; aber da waren Würmer darin gewachsen, und es roch übel; Mose aber wurde zornig über sie.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 21, 'So sammelten sie es denn alle Morgen, ein jeder nach seinem Bedarf; sobald aber die Sonne heiß schien, zerschmolz es.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 22, 'Am sechsten Tage aber hatten sie doppelt so viel Brot gesammelt, zwei Gomer für jede Person. Da kamen alle Vorsteher der Gemeinde und berichteten es dem Mose.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 23, 'Dieser antwortete ihnen: »Folgendes ist es, was der HERR geboten hat: ›Ein Ruhetag, ein dem HERRN heiliger Feiertag (Sabbat) ist morgen!‹ Was ihr backen wollt, das backt, und was ihr kochen wollt, das kocht; alles aber, was übrigbleibt, legt beiseite und hebt es euch für morgen auf!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 24, 'Da hoben sie es bis zum folgenden Morgen auf, wie Mose angeordnet hatte, und diesmal wurde es nicht übelriechend, und auch kein Wurm war darin.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 25, 'Da sagte Mose: »Eßt es heute! Denn heute ist Sabbatfeier für den HERRN: heute werdet ihr auf dem Felde nichts finden.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 26, 'Sechs Tage sollt ihr es sammeln; aber am siebten Tage ist Sabbat, an diesem gibt es keins.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 27, 'Als trotzdem am siebten Tage einige vom Volk hinausgingen, um zu sammeln, fanden sie nichts.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 28, 'Da sagte der HERR zu Mose: »Wie lange wollt ihr euch noch weigern, meine Gebote und Weisungen zu befolgen?');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 29, 'Seht doch! Weil der HERR euch den Sabbat eingesetzt hat, darum gibt er euch am sechsten Tage Brot für zwei Tage. Bleibt also alle daheim: niemand verlasse am siebten Tage seine Wohnung!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 30, 'So ruhte denn das Volk am siebten Tage.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 31, 'Die Israeliten nannten es aber Manna; es sah weißlich aus wie Koriandersamen und schmeckte wie Honigkuchen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 32, 'Hierauf sagte Mose: »Folgendes hat der HERR geboten: ›Ein Gomer voll soll davon für eure künftigen Geschlechter aufbewahrt werden, damit sie das Brot sehen, mit dem ich euch in der Wüste gespeist habe, als ich euch aus dem Lande Ägypten wegführte.‹«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 33, 'Da befahl Mose dem Aaron: »Nimm einen Krug, tu einen Gomer Manna hinein und stelle ihn hin vor den HERRN zur Aufbewahrung für eure künftigen Geschlechter!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 34, 'Nach dem Befehl, den der HERR dem Mose gegeben hatte, stellte Aaron (den Krug später) vor die Gesetzestafeln in der Bundeslade zur Aufbewahrung.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 35, 'Die Israeliten haben aber das Manna vierzig Jahre lang gegessen, bis sie in bewohntes Land kamen; sie haben das Manna gegessen, bis sie an die Grenze des Landes Kanaan kamen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 36, 'Ein Gomer aber ist der zehnte Teil eines Epha.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 17, 1, 'Hierauf zog die ganze Gemeinde der Israeliten nach dem Befehl des HERRN aus der Wüste Sin weiter, einen Tagemarsch nach dem andern, und lagerte in Rephidim, wo es aber kein Trinkwasser für das Volk gab.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 17, 2, 'Da haderte das Volk mit Mose und rief: »Gebt uns Wasser zum Trinken!« Aber Mose antwortete ihnen: »Was hadert ihr mit mir? Was versucht ihr den HERRN?«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 17, 3, 'Weil aber das Volk dort infolge des Wassermangels Durst litt, murrte es gegen Mose und sagte: »Warum hast du uns nur aus Ägypten hergeführt? Etwa um mich und meine Kinder und mein Vieh hier verdursten zu lassen?«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 17, 4, 'Da betete Mose laut zum HERRN mit den Worten: »Was soll ich mit diesem Volk machen? Es fehlt nicht viel, so steinigen sie mich!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 17, 5, 'Da antwortete der HERR dem Mose: »Tritt an die Spitze des Volkes und nimm einige von den Ältesten der Israeliten mit dir! Auch deinen Stab, mit dem du den Nil geschlagen hast, nimm in die Hand und gehe!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 17, 6, 'Dann will ich dort vor dich auf den Felsen am Horeb treten, und wenn du dann an den Felsen geschlagen hast, wird Wasser aus ihm hervorfließen, so daß das Volk zu trinken hat.« Mose tat so vor den Augen der Ältesten Israels.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 17, 7, 'Darauf nannte er den Ort Massa und Meriba, weil die Israeliten dort gehadert und den HERRN geprüft (oder versucht) hatten, indem sie sagten: »Ist der HERR in unserer Mitte oder nicht?«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 17, 8, 'Als darauf die Amalekiter heranrückten, um mit den Israeliten bei Rephidim zu kämpfen,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 17, 9, 'befahl Mose dem Josua: »Wähle uns Männer aus und ziehe zum Kampf mit den Amalekitern aus! Morgen will ich mich mit dem Gottesstabe in der Hand auf die Spitze des Hügels stellen.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 17, 10, 'Josua tat, wie Mose ihm befohlen hatte, (und zog aus,) um mit den Amalekitern zu kämpfen, während Mose, Aaron und Hur auf die Spitze des Hügels stiegen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 17, 11, 'Solange nun Mose seinen Arm hochhielt, hatten die Israeliten die Oberhand; sobald er aber seinen Arm ruhen ließ, waren die Amalekiter siegreich.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 17, 12, 'Als nun schließlich die Arme Moses erlahmten, nahmen sie einen Stein und legten den unter ihn, und er setzte sich darauf; dann stützten Aaron und Hur seine Arme, der eine auf dieser, der andere auf jener Seite; so blieben seine Arme fest bis zum Sonnenuntergang,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 17, 13, 'so daß Josua die Amalekiter und ihr Kriegsvolk mit der Schärfe des Schwertes niederhieb.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 17, 14, 'Da sagte der HERR zu Mose: »Schreibe dies zu dauernder Erinnerung in ein Buch und schärfe es dem Josua ein, daß ich das Andenken an die Amalekiter unter dem Himmel ganz und gar austilgen werde!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 17, 15, 'Darauf baute Mose einen Altar und nannte ihn ›der HERR ist mein Banner‹;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 17, 16, '»denn«, sagte er, »die Hand an das Banner des HERRN! Krieg führt der HERR mit den Amalekitern von Geschlecht zu Geschlecht!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 1, 'Jethro aber, der Priester der Midianiter, der Schwiegervater Moses, hatte alles erfahren, was Gott an Mose und an seinem Volke Israel getan hatte, daß der HERR nämlich die Israeliten aus Ägypten weggeführt hatte.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 2, 'Da nahm Jethro, der Schwiegervater Moses, Zippora, Moses Frau, die dieser zurückgesandt hatte,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 3, 'samt ihren beiden Söhnen, von denen der eine Gersom hieß, weil Mose gesagt hatte: »Ein Gast bin ich in einem fremden Lande geworden«,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 4, 'während der andere Elieser hieß, denn »der Gott meines Vaters ist meine Hilfe gewesen und hat mich vor dem Schwert des Pharaos errettet« –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 5, 'Jethro also, der Schwiegervater Moses, kam mit den Söhnen Moses und dessen Frau zu Mose in die Wüste, wo jener sich am Berge Gottes gelagert hatte,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 6, 'und ließ dem Mose sagen: »Ich, dein Schwiegervater Jethro, komme zu dir mit deiner Frau und ihren beiden Söhnen, die bei ihr sind.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 7, 'Da ging Mose seinem Schwiegervater entgegen, verneigte sich vor ihm, und (jener) küßte ihn; nachdem sie dann einander begrüßt hatten, traten sie in das Zelt ein.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 8, 'Hierauf erzählte Mose seinem Schwiegervater alles, was der HERR am Pharao und an den Ägyptern um der Israeliten willen getan hatte, und alle die Leiden, die ihnen unterwegs zugestoßen waren, und wie der HERR sie errettet hatte.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 9, 'Da freute sich Jethro über alles Gute, das der HERR den Israeliten erwiesen hatte, indem er sie aus der Gewalt der Ägypter errettete.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 10, 'Und Jethro rief aus: »Gepriesen sei der HERR, der euch aus der Gewalt der Ägypter und aus der Gewalt des Pharaos errettet und der das Volk aus der Gewaltherrschaft der Ägypter befreit hat!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 11, 'Nun erkenne ich, daß der HERR größer ist als alle Götter; er hat es bewiesen, als (jene) sich übermütig gegen sie benahmen.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 12, 'Darauf ließ Jethro, Moses Schwiegervater, Tiere zu einem Brand- und Schlachtopfer für Gott herbeibringen, und Aaron nebst allen Ältesten der Israeliten kam herbei, um mit dem Schwiegervater Moses das Opfermahl vor Gott zu halten.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 13, 'Am folgenden Tage aber hielt Mose eine Gerichtssitzung ab, um dem Volke Recht zu sprechen; und das Volk stand vor Mose vom Morgen bis zum Abend.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 14, 'Als nun der Schwiegervater Moses sah, was er alles mit dem Volk zu tun hatte, sagte er: »Was machst du dir da mit dem Volk so viel zu schaffen? Warum sitzest du allein zu Gericht, während das ganze Volk vom Morgen bis zum Abend vor dir steht?«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 15, 'Mose antwortete seinem Schwiegervater: »Ja, das Volk kommt zu mir, um Gott zu befragen;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 16, 'sooft sie einen Rechtshandel haben, kommen sie zu mir, damit ich Schiedsrichter zwischen den Parteien sei und ihnen Gottes Rechtssprüche und Entscheidungen kundtue.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 17, 'Da sagte sein Schwiegervater zu ihm: »Dein Verfahren ist nicht zweckmäßig;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 18, 'dabei mußt du selbst und ebenso auch diese Leute, die bei dir stehen, ganz erschöpft werden; denn die Sache ist zu schwer für dich, und du allein kannst sie nicht durchführen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 19, 'Nun höre mich an: ich will dir einen Rat geben, und Gott möge mit dir sein! Sei du der Vertreter des Volkes Gott gegenüber und bringe du ihre Anliegen vor Gott!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 20, 'Mache ihnen daneben die Rechtssprüche und Entscheidungen klar und gib ihnen den Weg an, den sie innezuhalten haben, und das Verfahren, das sie beobachten müssen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 21, 'Zugleich sieh dich aber unter dem ganzen Volke nach tüchtigen, gottesfürchtigen und zuverlässigen Männern um, die keiner Bestechung zugänglich sind, und setze diese als Obmänner über sie, die einen über tausend, andere über hundert, andere über fünfzig und andere über zehn,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 22, 'damit sie dem Volke jederzeit Recht sprechen, und zwar so, daß sie alle wichtigen Sachen vor dich bringen, alle geringfügigen Sachen aber selbst entscheiden! Auf diese Weise verschaffe dir Erleichterung und laß sie die Last mit dir tragen!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 23, 'Wenn du es so machst und Gott es dir gestattet, so wirst du dabei bestehen können, und auch alle diese Leute werden befriedigt nach Hause zurückkehren.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 24, 'Mose befolgte den Rat seines Schwiegervaters und tat alles, was er ihm vorgeschlagen hatte:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 25, 'er wählte tüchtige Männer aus allen Israeliten aus und setzte sie zu Obmännern über das Volk ein, die einen über tausend, andere über hundert, andere über fünfzig und über zehn.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 26, 'Diese hatten dem Volk zu jeder Zeit Recht zu sprechen: die schwierigen Sachen legten sie dem Mose vor, aber alle geringfügigen Sachen entschieden sie selbst.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 27, 'Hierauf ließ Mose seinen Schwiegervater ziehen, und dieser kehrte in sein Land zurück.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 19, 1, 'Im dritten Monat nach dem Auszug der Israeliten aus Ägypten, an diesem Tage kamen sie in die Wüste Sinai.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 19, 2, 'Sie waren nämlich von Rephidim aufgebrochen und in die Wüste Sinai gelangt und lagerten sich dort in der Wüste, und zwar dem Berg gegenüber.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 19, 3, 'Als Mose dann zu Gott hinaufstieg, rief der HERR ihm vom Berge herab die Worte zu: »So sollst du zum Hause Jakobs sprechen und den Kindern Israels verkündigen:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 19, 4, '›Ihr habt selbst gesehen, was ich an den Ägyptern getan und wie ich euch auf Adlersflügeln getragen und euch hierher zu mir gebracht habe.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 19, 5, 'Und nun, wenn ihr meinen Weisungen willig gehorcht und meinen Bund haltet, so sollt ihr aus allen Völkern mein besonderes Eigentum sein; denn mir gehört die ganze Erde;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 19, 6, 'ihr aber sollt mir ein Königreich von Priestern und ein heiliges Volk sein.‹ Das sind die Worte, die du den Israeliten verkünden sollst.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 19, 7, 'Da ging Mose hin, berief die Ältesten des Volkes und teilte ihnen alle diese Worte mit, die der HERR ihm aufgetragen hatte.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 19, 8, 'Das ganze Volk aber antwortete einmütig: »Alles, was der HERR geboten hat, wollen wir tun!« Als hierauf Mose dem HERRN die Antwort des Volkes überbracht hatte,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 19, 9, 'sagte der HERR zu Mose: »Ich werde diesmal in dichtem Gewölk zu dir kommen, damit das Volk es hört, wenn ich mit dir rede, und dir für immer Glauben schenkt.« [Mose aber berichtete dem HERRN die Antwort des Volkes.]');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 19, 10, 'Dann sagte der HERR weiter zu Mose: »Gehe zum Volk und laß sie sich heute und morgen heiligen und ihre Kleider waschen,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 19, 11, 'damit sie übermorgen bereit sind! Denn übermorgen wird der HERR vor den Augen des ganzen Volkes auf den Berg Sinai herabfahren.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 19, 12, 'Bestimme daher dem Volk ringsum eine Grenze und sage ihnen: ›Hütet euch wohl, an dem Berge emporzusteigen oder auch nur seinen Fuß zu berühren! Wer den Berg berührt, der ist des Todes!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 19, 13, 'Niemandes Hand darf ihn berühren, sondern ein solcher soll gesteinigt oder erschossen werden: weder ein Tier noch ein Mensch darf am Leben bleiben! Erst wenn das Widderhorn geblasen wird, dürfen sie am Berge emporsteigen.‹«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 19, 14, 'Darauf stieg Mose vom Berge zum Volk hinab und ließ das Volk sich heiligen, und sie wuschen ihre Kleider;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 19, 15, 'auch gebot er dem Volke: »Haltet euch für übermorgen bereit: keiner nahe sich bis dahin einem Weibe!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 19, 16, 'Am dritten Tage aber, als es Morgen wurde, entstand ein Donnern und Blitzen; schweres Gewölk lag auf dem Berge, und gewaltiger Posaunenschall ertönte, so daß das ganze Volk, das sich im Lager befand, zitterte.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 19, 17, 'Da führte Mose das Volk aus dem Lager hinaus, Gott entgegen, und sie stellten sich am Fuß des Berges auf.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 19, 18, 'Der Berg Sinai aber war ganz in Rauch gehüllt, weil der HERR im Feuer auf ihn herabgefahren war; Rauch stieg von ihm auf wie der Rauch von einem Schmelzofen, und der ganze Berg erbebte stark.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 19, 19, 'Und der Posaunenschall wurde immer stärker: Mose redete, und Gott antwortete ihm mit lauter Stimme.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 19, 20, 'Als nun der HERR auf den Berg Sinai, auf den Gipfel des Berges, hinabgefahren war, berief er Mose auf den Gipfel des Berges, und Mose stieg hinauf.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 19, 21, 'Da befahl der HERR dem Mose: »Steige hinab, warne das Volk, daß sie ja nicht zum HERRN durchbrechen, um ihn zu schauen, sonst würde eine große Zahl von ihnen ums Leben kommen!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 19, 22, 'Auch die Priester, die sonst dem HERRN nahen dürfen, müssen die Heiligung an sich vollziehen, damit der HERR nicht gegen sie losfährt.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 19, 23, 'Da erwiderte Mose dem HERRN: »Das Volk kann ja nicht auf den Berg Sinai hinaufsteigen; denn du selbst hast uns gewarnt und mir geboten, eine Grenze um den Berg festzusetzen und ihn für unnahbar zu erklären.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 19, 24, 'Doch der HERR antwortete ihm: »Steige hinab und komm dann mit Aaron wieder herauf! Die Priester aber und das Volk dürfen die festgesetzte Grenze nicht überschreiten, um zum HERRN hinaufzusteigen, damit er nicht gegen sie losfährt.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 19, 25, 'Da stieg Mose zum Volk hinab und kündigte es ihnen an.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 20, 1, 'Hierauf redete Gott alle diese Worte und sprach:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 20, 2, '»Ich bin der HERR, dein Gott, der dich aus dem Land Ägypten hinausgeführt hat, aus dem Diensthause.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 20, 3, 'Du sollst keine anderen Götter haben neben mir!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 20, 4, 'Du sollst dir kein Gottesbild anfertigen noch irgendein Abbild weder von dem, was oben im Himmel, noch von dem, was unten auf der Erde, noch von dem, was im Wasser unterhalb der Erde ist!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 20, 5, 'Du sollst dich vor ihnen nicht niederwerfen und ihnen nicht dienen! Denn ich, der HERR, dein Gott, bin ein eifriger Gott, der die Verschuldung der Väter heimsucht an den Kindern, an den Enkeln und Urenkeln bei denen, die mich hassen,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 20, 6, 'der aber Gnade erweist an Tausenden von Nachkommen derer, die mich lieben und meine Gebote halten.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 20, 7, 'Du sollst den Namen des HERRN, deines Gottes, nicht mißbrauchen! Denn der HERR wird den nicht ungestraft lassen, der seinen Namen mißbraucht.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 20, 8, 'Gedenke des Sabbattages, daß du ihn heilig hältst!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 20, 9, 'Sechs Tage sollst du arbeiten und alle deine Geschäfte verrichten!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 20, 10, 'Aber der siebte Tag ist ein Feiertag zu Ehren des HERRN, deines Gottes: da darfst du keinerlei Geschäft verrichten, weder du selbst noch dein Sohn oder deine Tochter, weder dein Knecht, noch deine Magd, noch dein Vieh, noch der Fremdling, der bei dir in deinen Ortschaften weilt!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 20, 11, 'Denn in sechs Tagen hat der HERR den Himmel und die Erde geschaffen, das Meer und alles, was in ihnen ist; aber am siebten Tage hat er geruht; darum hat der HERR den Sabbattag gesegnet und ihn für heilig erklärt.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 20, 12, 'Ehre deinen Vater und deine Mutter, damit du lange lebst in dem Lande, das der HERR, dein Gott, dir geben wird!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 20, 13, 'Du sollst nicht töten!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 20, 14, 'Du sollst nicht ehebrechen!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 20, 15, 'Du sollst nicht stehlen!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 20, 16, 'Du sollst kein falsches Zeugnis ablegen gegen deinen Nächsten!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 20, 17, 'Du sollst nicht begehren deines Nächsten Haus! Du sollst nicht begehren deines Nächsten Weib, noch seinen Knecht, noch seine Magd, noch sein Rind, noch seinen Esel, noch irgend etwas, was deinem Nächsten gehört.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 20, 18, 'Als aber das ganze Volk die Donnerschläge und die flammenden Blitze, den Posaunenschall und den rauchenden Berg wahrnahm, da zitterten sie und blieben in der Ferne stehen');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 20, 19, 'und sagten zu Mose: »Rede du mit uns, dann wollen wir zuhören; Gott aber möge nicht mit uns reden, sonst müssen wir sterben!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 20, 20, 'Da antwortete Mose dem Volk: »Fürchtet euch nicht! Denn Gott ist nur deshalb gekommen, um euch auf die Probe zu stellen und damit die Furcht vor ihm euch gegenwärtig bleibt, auf daß ihr nicht sündigt.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 20, 21, 'So blieb denn das Volk in der Ferne stehen; Mose aber trat an das dunkle Gewölk heran, in welchem Gott war.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 20, 22, 'Hierauf gebot der HERR dem Mose: »So sollst du zu den Israeliten sagen: ›Ihr habt selbst gesehen, daß ich vom Himmel her mit euch geredet habe.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 20, 23, 'Darum sollt ihr keine anderen Götter neben mir anfertigen: Götter von Silber und Götter von Gold sollt ihr euch nicht anfertigen!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 20, 24, 'Einen Altar von Erde sollst du mir herstellen und auf ihm deine Brandopfer und Heilsopfer, dein Kleinvieh und deine Rinder darbringen! An jeder Stätte, wo ich ein Gedächtnis meines Namens stiften werde, will ich zu dir kommen und dich segnen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 20, 25, 'Willst du mir aber einen Altar von Steinen errichten, so darfst du ihn nicht von behauenen Steinen bauen! Denn sobald du mit deinem Meißel über sie hingefahren bist, hast du sie entweiht.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 20, 26, 'Auch darfst du nicht auf Stufen zu meinem Altar hinaufsteigen, damit deine Blöße nicht vor ihm sichtbar wird!‹«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 1, '»Und dies sind die Rechtssatzungen, die du ihnen vorlegen sollst:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 2, 'Wenn du einen hebräischen Knecht kaufst, soll er dir sechs Jahre lang dienen; aber im siebten Jahre soll er unentgeltlich freigelassen werden.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 3, 'Ist er allein gekommen, so soll er auch allein wieder gehen; war er aber verheiratet, so soll auch seine Frau mit ihm freigelassen werden.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 4, 'Hat ihm dagegen sein Herr eine Frau gegeben und diese ihm Söhne oder Töchter geboren, so soll die Frau samt ihren Kindern ihrem Herrn verbleiben, und er soll allein entlassen werden.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 5, 'Erklärt aber der Knecht ausdrücklich: ›Ich habe meinen Herrn, meine Frau und meine Kinder lieb, ich will nicht freigelassen werden‹,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 6, 'so soll sein Herr ihn vor Gott hintreten lassen und ihn an die Tür oder an den Türpfosten stellen: dort soll sein Herr ihm das Ohr mit einer Pfrieme durchbohren, und er soll dann zeitlebens sein Knecht bleiben. –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 7, 'Wenn aber jemand seine Tochter als Magd verkauft, so darf sie nicht wie die Knechte freigelassen werden.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 8, 'Wenn sie ihrem Herrn, der sie für sich bestimmt hatte, mißfällt, so lasse er sie loskaufen; jedoch sie an fremde Leute zu verkaufen, dazu hat er kein Recht, weil er treulos an ihr gehandelt hat.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 9, 'Wenn er sie aber für seinen Sohn bestimmt, so hat er sie nach dem Recht der Töchter zu behandeln.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 10, 'Nimmt er sich noch eine andere, so darf er ihr doch die Fleischkost, die Kleidung und die Beiwohnung nicht verkürzen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 11, 'Will er ihr aber diese drei Verpflichtungen nicht gewähren, so soll sie umsonst, ohne Entgelt, frei ausgehen.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 12, '»Wer einen andern so schlägt, daß er stirbt, soll mit dem Tode bestraft werden.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 13, 'Hat er es aber nicht vorsätzlich getan, sondern hat Gott es seiner Hand widerfahren lassen, so will ich dir eine Stätte bestimmen, wohin er fliehen soll.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 14, 'Wenn sich aber jemand gegen einen andern so weit vergißt, daß er ihn hinterlistig ums Leben bringt, so sollst du ihn sogar von meinem Altar wegholen, damit er stirbt! –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 15, 'Wer seinen Vater oder seine Mutter schlägt, soll mit dem Tode bestraft werden!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 16, 'Wer einen Menschen raubt, sei es, daß er ihn verkauft hat oder daß der Betreffende noch in seiner Gewalt gefunden wird, soll mit dem Tode bestraft werden.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 17, 'Auch wer seinem Vater oder seiner Mutter flucht, soll mit dem Tode bestraft werden! –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 18, '»Wenn Männer in Streit geraten und einer den andern mit einem Stein oder mit der Faust so schlägt, daß er zwar nicht stirbt, aber doch bettlägerig wird,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 19, 'so soll, wenn er wieder aufkommt und draußen an seiner Krücke umhergehen kann, der andere, der ihn geschlagen hat, straflos bleiben; nur soll er ihm den Schaden ersetzen, der ihm aus der Arbeitsunfähigkeit erwachsen ist, und für die Heilkosten aufkommen!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 20, 'Wenn jemand seinen Knecht oder seine Magd mit dem Stock so schlägt, daß sie ihm unter der Hand sterben, so muß das bestraft werden;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 21, 'wenn jedoch der Betreffende noch einen oder zwei Tage am Leben bleibt, so soll keine Bestrafung stattfinden, denn es handelt sich um sein eigenes Geld. –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 22, 'Wenn Männer in Streit geraten und dabei eine schwangere Frau so stoßen, daß eine Frühgeburt eintritt, ihr sonst aber kein Schaden entsteht, so soll der Schuldige diejenige Geldbuße zahlen, die der Ehemann der Frau ihm auferlegt, und zwar nach Anhörung von Schiedsrichtern. –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 23, 'Wenn aber ein bleibender Leibesschaden entsteht, so sollst du geben: Leben um Leben,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 24, 'Auge um Auge, Zahn um Zahn, Hand um Hand, Fuß um Fuß,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 25, 'Brandmal um Brandmal, Wunde um Wunde, Strieme um Strieme! –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 26, 'Schlägt jemand seinen Knecht oder seine Magd so ins Auge, daß er es zugrunde richtet, so soll er sie zur Entschädigung für ihr Auge freilassen!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 27, 'Und schlägt er seinem Knecht oder seiner Magd einen Zahn aus, so soll er sie zur Entschädigung für ihren Zahn freilassen!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 28, '»Wenn ein Rind einen Mann oder eine Frau so stößt, daß der Tod eintritt, so soll das Rind gesteinigt, sein Fleisch aber nicht gegessen werden; der Eigentümer des Rindes jedoch bleibt straflos.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 29, 'Wenn aber das Rind schon früher stößig war und sein Eigentümer trotz erfolgter Verwarnung es nicht gehörig gehütet hatte, so soll das Rind, wenn es einen Mann oder eine Frau tötet, gesteinigt und auch sein Eigentümer mit dem Tode bestraft werden.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 30, 'Wenn ihm nur eine Geldbuße auferlegt wird, so soll er als Lösegeld für sein Leben so viel bezahlen, als ihm auferlegt wird.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 31, 'Wenn das Rind einen Knaben oder ein Mädchen stößt, so soll mit ihm nach derselben Rechtsbestimmung verfahren werden.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 32, 'Stößt das Rind aber einen Knecht oder eine Magd, so soll sein Eigentümer ihrem Herrn dreißig Schekel Silber bezahlen; das Rind aber soll gesteinigt werden.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 33, '»Läßt jemand eine Grube offen stehen, oder gräbt jemand eine Grube aus und deckt sie nicht zu, und es fällt ein Rind oder ein Esel hinein,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 34, 'so soll der Eigentümer der Grube Ersatz leisten: mit Geld soll er den Eigentümer des Tieres entschädigen; das tote Tier aber gehört dann ihm. –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 35, 'Wenn jemandes Rind das Rind eines andern so stößt, daß es stirbt, so sollen sie das lebende Rind verkaufen und sich in den dadurch gewonnenen Erlös teilen, und auch das tote Tier sollen sie unter sich teilen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 36, 'War es jedoch bekannt, daß das Rind schon vorher stößig war, und hatte sein Eigentümer trotzdem es nicht gehörig gehütet, so soll er unweigerlich ein Rind für das Rind als Ersatz geben, das tote Tier aber soll ihm gehören.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 37, 'Wenn jemand ein Rind oder ein Stück Kleinvieh stiehlt und es schlachtet oder verkauft, so soll er für das eine Rind fünf Rinder und für das eine Stück Kleinvieh vier Stück erstatten. Ersatz muß er unbedingt leisten; wenn er nichts besitzt, so soll er zum Ersatz für das von ihm Gestohlene verkauft werden.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 1, 'Wird ein Dieb beim Einbruch betroffen und totgeschlagen, so ist dies für den Täter nicht als Mord anzusehen;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 2, 'wenn aber die Sonne zur Zeit der Tat über ihm schon aufgegangen war, so soll ein Mord für ihn als vorliegend angenommen werden.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 3, 'Wird das gestohlene Tier, es sei ein Rind oder ein Esel oder ein Stück Kleinvieh, noch lebend in seinem Besitz vorgefunden, so soll er nur doppelten Ersatz leisten;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 4, 'Läßt jemand ein Feld oder einen Baumgarten abweiden und sein Vieh dabei frei laufen, so daß es auf dem Felde eines andern weidet, so hat er mit dem besten Ertrage seines Feldes und mit dem besten Ertrage seines Baumgartens Ersatz zu leisten. –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 5, 'Wenn Feuer ausbricht und Dornhecken ergreift und es wird ein Garbenhaufen oder das auf dem Halm stehende Getreide oder das Feld dadurch verbrannt, so soll der, welcher den Brand verursacht hat, den Schaden ersetzen.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 6, '»Wenn jemand einem andern Geld oder Wertsachen zur Aufbewahrung übergibt und es wird dies aus dem Hause des Betreffenden gestohlen, so hat der Dieb, wenn er ausfindig gemacht wird, doppelten Ersatz zu leisten.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 7, 'Wird aber der Dieb nicht ausfindig gemacht, so soll der Besitzer des Hauses vor Gott hintreten, damit festgestellt wird, ob er sich nicht an dem Eigentum des andern vergriffen hat! –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 8, 'Bei jedem Fall von Veruntreuung, mag es sich um ein Rind, einen Esel, ein Stück Kleinvieh, ein Kleidungsstück, kurz um irgend etwas abhanden Gekommenes handeln, wovon jemand behauptet, daß es sein Eigentum sei, soll die Angelegenheit beider vor Gott kommen, und wen Gott für schuldig erklärt, der soll dem andern doppelten Ersatz leisten. –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 9, 'Wenn jemand einem andern einen Esel oder ein Rind oder ein Stück Kleinvieh oder sonst irgendein Stück Vieh zur Hut übergibt und dieses zu Tode oder zu Schaden kommt oder geraubt wird, ohne daß jemand es gesehen hat,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 10, 'so soll ein Eid bei Gott zwischen den beiden Parteien entscheiden, ob der Betreffende sich nicht am Eigentum des andern vergriffen hat. Der Eigentümer des Tieres muß dann den Verlust hinnehmen, und (der andere) braucht keinen Ersatz zu leisten.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 11, 'Ist es ihm aber wirklich gestohlen worden, so hat er dem Eigentümer Ersatz zu leisten.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 12, 'Ist es dagegen (von einem Raubtier) zerrissen worden, so mag er das zerrissene Tier zum Beweis beibringen: für das Zerrissene braucht er keinen Ersatz zu leisten. –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 13, 'Wenn ferner jemand ein Stück Vieh von einem andern entlehnt hat und dieses zu Schaden oder zu Tode kommt, so muß er, wenn sein Eigentümer nicht zugegen war, unweigerlich Ersatz leisten;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 14, 'war jedoch der Eigentümer zugegen, so braucht er keinen Ersatz zu leisten. Wenn das Tier (um Geld) gemietet war, so ist der Schaden in dem Mietgeld eingeschlossen.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 15, '»Wenn jemand eine Jungfrau verführt, die noch nicht verlobt ist, und ihr beiwohnt, so muß er sie sich durch Erlegung der Heiratsgabe zur Ehefrau erkaufen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 16, 'Wenn ihr Vater sich aber durchaus weigert, sie ihm zu geben, so soll er das als Heiratsgabe für Jungfrauen übliche Kaufgeld bezahlen.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 17, 'Eine Zauberin sollst du nicht am Leben lassen. –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 18, 'Wer einem Tiere beiwohnt, soll mit dem Tode bestraft werden. –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 19, 'Wer den Göttern opfert außer dem HERRN allein, soll dem Bann verfallen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 20, 'Einen Fremdling sollst du nicht übervorteilen und nicht bedrücken; denn ihr selbst seid Fremdlinge im Land Ägypten gewesen. –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 21, 'Keine Witwe oder Waise sollt ihr bedrücken.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 22, 'Wenn du sie irgendwie bedrückst und sie dann zu mir schreien, so werde ich ihr Schreien gewißlich erhören,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 23, 'und mein Zorn wird entbrennen, und ich werde euch durch das Schwert sterben lassen, so daß eure Frauen zu Witwen und eure Kinder zu Waisen werden. –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 24, 'Wenn du jemandem aus meinem Volk, einem Armen, der neben dir wohnt, Geld leihst, so sollst du dich nicht als Wucherer gegen ihn benehmen: ihr sollt keine Zinsen von ihm fordern. –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 25, 'Wenn du dir von einem andern den Mantel als Pfand geben läßt, so sollst du ihm diesen bis zum Sonnenuntergang zurückgeben;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 26, 'denn das ist seine einzige Decke, die einzige Hülle für seinen Leib: worauf soll er sonst beim Schlafen liegen? Wenn er zu mir schriee, so würde ich ihn erhören; denn ich bin gnädig. –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 27, 'Gott sollst du nicht lästern und einem Fürsten in deinem Volk nicht fluchen. –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 28, 'Mit der Abgabe von dem Überfluß deiner Tenne und von dem Abfluß deiner Kelter sollst du nicht zögern. – Den Erstgeborenen deiner Söhne sollst du mir geben.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 29, 'Ebenso sollst du es mit deinen Rindern und deinem Kleinvieh halten! Sieben Tage soll (das Erstgeborene) bei seiner Mutter bleiben, und am achten Tage sollst du es mir darbringen. –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 30, 'Heilige Männer sollt ihr mir sein und Fleisch von einem auf dem Feld zerrissenen Tiere nicht essen: den Hunden sollt ihr es vorwerfen.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 1, '»Du sollst kein falsches Gerücht verbreiten. – Biete dem, der eine ungerechte Sache hat, nicht die Hand, daß du ein falscher Zeuge für ihn würdest. –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 2, 'Du sollst dich nicht der großen Menge zu bösem Tun anschließen und bei einem Rechtsstreit nicht so aussagen, daß du dich nach der großen Menge richtest, um das Recht zu beugen. –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 3, 'Den Vornehmen sollst du in seinem Rechtshandel nicht begünstigen. –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 4, 'Wenn du das Rind deines Feindes oder seinen Esel umherirrend antriffst, so sollst du ihm das Tier unweigerlich wieder zuführen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 5, 'Wenn du den Esel deines Widersachers unter seiner Last zusammengebrochen siehst, so hüte dich, ihn bei dem Tier allein zu lassen! Du sollst unweigerlich im Verein mit ihm die Hilfeleistung vollbringen. –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 6, 'Beuge nicht das Recht eines von den Armen deines Volkes in einem Rechtshandel! –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 7, 'Von falscher Anklage halte dich fern und hilf nicht dazu, einen Unschuldigen, der im Recht ist, ums Leben zu bringen! denn ich lasse den Schuldigen nicht Recht haben.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 8, 'Nimm keine Bestechungsgeschenke an; denn Geschenke machen die Sehenden blind und verdrehen die Sache der Unschuldigen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 9, 'Einen Fremdling sollst du nicht bedrücken! Ihr wißt ja selbst, wie einem Fremdling zumute ist; denn ihr seid selbst Fremdlinge im Land Ägypten gewesen.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 10, '»Sechs Jahre sollst du dein Land bestellen und seinen Ertrag einernten;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 11, 'aber im siebten Jahre sollst du es ruhen lassen und es freigeben, damit die Armen deines Volkes sich davon nähren können; und was diese übriglassen, soll das Getier des Feldes fressen. Ebenso sollst du es mit deinen Weinbergen und mit deinen Ölbaumgärten halten. –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 12, 'Sechs Tage hindurch sollst du deine Arbeit verrichten; aber am siebten Tage sollst du feiern, damit dein Ochs und dein Esel ausruhen und der Sohn deiner Magd sowie der Fremdling Atem schöpfen können. –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 13, 'Auf alles, was ich euch geboten habe, sollt ihr achtgeben. Den Namen anderer Götter aber sollt ihr nicht aussprechen: er soll nicht über deine Lippen kommen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 14, 'Dreimal im Jahre sollst du mir ein Fest feiern.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 15, 'Das Fest der ungesäuerten Brote sollst du beobachten: sieben Tage lang sollst du ungesäuertes Brot essen, wie ich dir geboten habe, zur bestimmten Zeit im Monat Abib! Denn in diesem Monat bist du aus Ägypten ausgezogen. Man darf aber nicht mit leeren Händen vor meinem Angesicht erscheinen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 16, 'Sodann das Fest der Ernte, der Erstlinge deines Ackerbaus, dessen, was du auf dem Feld ausgesät hast, und das Fest der Lese beim Ausgang des Jahres, wenn du deinen Ertrag vom Feld einsammelst.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 17, 'Dreimal im Jahr sollen alle deine männlichen Personen vor dem Angesicht Gottes, des HERRN, erscheinen. –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 18, 'Du sollst das Blut meiner Schlachtopfer nicht zusammen mit gesäuertem Brot opfern, und von dem Fett meiner Festopfer soll nichts bis zum andern Morgen übrigbleiben.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 19, 'Das Beste von den Erstlingen deiner Felder sollst du in das Haus des HERRN, deines Gottes, bringen. – Ein Böckchen sollst du nicht in der Milch seiner Mutter kochen.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 20, '»Wisse wohl: ich will einen Engel vor dir hergehen lassen, um dich unterwegs zu behüten und dich an den Ort zu bringen, den ich dir bestimmt habe.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 21, 'Nimm dich vor ihm in acht, gehorche seinen Weisungen und sei nicht widerspenstig gegen ihn; denn er würde euch eure Verschuldungen nicht vergeben, weil ich persönlich in ihm bin.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 22, 'Doch wenn du seinen Weisungen willig gehorchst und alles tust, was ich (dir durch ihn) gebieten werde, so will ich der Feind deiner Feinde und der Bedränger deiner Bedränger sein.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 23, 'Wenn mein Engel nun vor dir hergeht und dich in das Land der Amoriter, Hethiter, Pherissiter, Kanaanäer, Hewiter und Jebusiter bringt und ich sie ausrotte:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 24, 'dann wirf dich vor ihren Göttern nicht nieder, diene ihnen nicht und ahme ihr Tun nicht nach! Nein, du sollst ihre Götzenbilder allesamt niederreißen und ihre Malsteine zertrümmern.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 25, 'Dient vielmehr dem HERRN, eurem Gott, so will ich dein Brot und dein Wasser segnen und Krankheiten von dir fernhalten;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 26, 'keine Frau soll in deinem Lande eine Fehlgeburt tun oder kinderlos bleiben, und ich will deine Lebenstage auf die volle Zahl bringen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 27, 'Meinen Schrecken will ich vor dir hergehen lassen und alle Völker, zu denen du kommst, verzagt machen und alle deine Feinde vor dir die Flucht ergreifen lassen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 28, 'Die Hornissen will ich vor dir hersenden, damit sie die Hewiter, Kanaanäer und Hethiter vor dir vertreiben.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 29, 'Nicht in einem Jahr will ich sie vor dir her vertreiben, sonst würde das Land zur Wüste werden und die wilden Tiere zu deinem Schaden überhandnehmen;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 30, 'nein, nach und nach will ich sie vor dir vertreiben, bis du so zahlreich geworden bist, daß du das ganze Land in Besitz nehmen kannst.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 31, 'Und ich will dein Gebiet sich ausdehnen lassen vom Schilfmeer bis zum Meer der Philister und von der Wüste bis an den Euphratstrom; denn ich will die Bewohner des Landes in deine Gewalt geben, daß du sie vor dir her vertreibst.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 32, 'Du darfst mit ihnen und mit ihren Göttern keinen Vertrag schließen;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 33, 'sie dürfen in deinem Lande nicht wohnen bleiben, damit sie dich nicht zur Sünde gegen mich verführen; denn wenn du ihren Göttern dientest, so würde das dich ins Verderben stürzen.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 24, 1, 'Hierauf gebot er dem Mose: »Steige zum HERRN herauf, du nebst Aaron, Nadab und Abihu und siebzig von den Ältesten der Israeliten, und bringt von fern eure Verehrung dar.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 24, 2, 'Mose aber soll dann allein nahe an den HERRN herantreten; die anderen dagegen sollen nicht näher hinzutreten, und auch das Volk darf nicht mit ihm heraufsteigen.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 24, 3, 'Hierauf kam Mose und teilte dem Volke alle Verordnungen des HERRN und alle Rechtssatzungen mit. Da gab das ganze Volk einstimmig die Erklärung ab: »Alle Verordnungen, die der HERR erlassen hat, wollen wir ausführen.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 24, 4, 'Da schrieb Mose alles, was der HERR geboten hatte, nieder und baute am andern Morgen früh einen Altar am Fuß des Berges und (errichtete) zwölf Malsteine entsprechend den zwölf Stämmen Israels.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 24, 5, 'Dann erteilte er den jungen israelitischen Männern den Auftrag, Brandopfer(tiere) herzubringen und junge Stiere als Heilsopfer für den HERRN zu schlachten.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 24, 6, 'Hierauf nahm Mose die eine Hälfte des Blutes und goß es in die Opferschalen; die andere Hälfte des Blutes aber sprengte er an den Altar.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 24, 7, 'Hierauf nahm er das Bundesbuch und las es dem Volke laut vor; und sie erklärten: »Alles, was der HERR geboten hat, wollen wir tun und willig erfüllen.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 24, 8, 'Dann nahm Mose das Blut und besprengte mit ihm das Volk, wobei er ausrief: »Dies ist das Blut des Bundes, den der HERR mit euch auf Grund aller dieser Gebote geschlossen hat!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 24, 9, 'Als hierauf Mose und Aaron, Nadab und Abihu und siebzig von den Ältesten der Israeliten hinaufgestiegen waren,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 24, 10, 'schauten sie den Gott Israels: (der Boden) unter seinen Füßen war wie ein Gebilde von Saphirplatten und wie der Himmel selbst an hellem Glanz.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 24, 11, 'Er streckte aber seine Hand nicht aus gegen die Auserwählten der Israeliten: nein, sie schauten Gott und aßen und tranken.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 24, 12, 'Hierauf gebot der HERR dem Mose: »Steige zu mir auf den Berg herauf und verweile dort, damit ich dir die Steintafeln mit dem Gesetz und den Geboten gebe, die ich zu ihrer Unterweisung aufgeschrieben habe.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 24, 13, 'Da machte sich Mose mit seinem Diener Josua auf den Weg und stieg auf den Berg Gottes hinauf.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 24, 14, 'Zu den Ältesten aber hatte er gesagt: »Wartet hier auf uns, bis wir zu euch zurückkehren. Aaron und Hur sind ja bei euch: wer irgendeinen Rechtshandel hat, wende sich an sie.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 24, 15, 'Als Mose dann auf den Berg gestiegen war, verhüllte Gewölk den Berg,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 24, 16, 'und die Herrlichkeit des HERRN ließ sich auf den Berg Sinai nieder, und das Gewölk verhüllte den Berg sechs Tage lang; erst am siebten Tage rief er dem Mose aus dem Gewölk heraus zu.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 24, 17, 'Die Herrlichkeit des HERRN zeigte sich aber vor den Augen der Israeliten wie ein verzehrendes Feuer auf der Spitze des Berges.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 24, 18, 'Da begab sich Mose mitten in das Gewölk hinein und stieg auf den Berg hinauf. Und Mose verweilte auf dem Berge vierzig Tage und vierzig Nächte.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 1, 'Der HERR sprach dann zu Mose folgendermaßen:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 2, '»Fordere die Israeliten auf, eine Beisteuer an mich zu entrichten! Von einem jeden, den sein Herz dazu treibt, sollt ihr die Abgabe an mich annehmen!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 3, 'Und zwar besteht die Abgabe, die ihr von ihnen erheben sollt, in folgendem: in Gold, Silber und Kupfer;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 4, 'in blauem und rotem Purpur und Karmesin, in Byssus und Ziegenhaar;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 5, 'in rotgefärbten Widderfellen und Seekuhhäuten; in Akazienholz;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 6, 'in Öl zur Beleuchtung, in Gewürzkräutern für das Salböl und für das wohlriechende Räucherwerk;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 7, 'in Onyxsteinen und anderen Edelsteinen zum Besatz für das Schulterkleid und für das Brustschild.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 8, 'Sie sollen mir nämlich ein Heiligtum herstellen, damit ich mitten unter ihnen wohne.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 9, 'Genau so, wie ich dir das Musterbild der Wohnung und das Musterbild aller ihrer Geräte zeigen werde, so sollt ihr es herstellen.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 10, '»Sie sollen also eine Lade aus Akazienholz anfertigen, zweieinhalb Ellen lang, anderthalb Ellen breit und anderthalb Ellen hoch.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 11, 'Du sollst sie mit feinem Gold überziehen, und zwar inwendig und auswendig, und oben einen goldenen Kranz ringsum an ihr anbringen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 12, 'Sodann gieße für sie vier goldene Ringe und befestige sie unten an ihren vier Ecken, und zwar zwei Ringe an ihrer einen Seite und zwei Ringe an ihrer andern Seite.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 13, 'Weiter fertige zwei Stangen von Akazienholz an, überziehe sie mit Gold');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 14, 'und stecke diese Stangen in die Ringe an den Seiten der Lade, damit man die Lade vermittels ihrer tragen kann.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 15, 'Die Stangen sollen in den Ringen der Lade verbleiben: sie dürfen nicht daraus entfernt werden.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 16, 'In die Lade sollst du dann das Gesetz legen, das ich dir geben werde.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 17, 'Sodann fertige eine Deckplatte aus feinem Gold an, zweieinhalb Ellen lang und anderthalb Ellen breit.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 18, 'Weiter sollst du zwei goldene Cherube anfertigen, und zwar in getriebener Arbeit, an den beiden Enden der Deckplatte.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 19, 'Den einen Cherub sollst du am Ende der einen Seite und den andern Cherub am Ende der andern Seite anbringen; mit der Deckplatte zu einem Stück verbunden sollt ihr die Cherube an den beiden Enden der Deckplatte anbringen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 20, 'Die Cherube sollen die Flügel nach oben hin ausgebreitet halten, so daß sie die Deckplatte mit ihren Flügeln überdecken; ihre Gesichter sollen einander zugekehrt und zugleich zur Deckplatte hin gerichtet sein.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 21, 'Die Deckplatte sollst du dann oben auf die Lade legen; und in die Lade sollst du das Gesetz tun, das ich dir geben werde.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 22, 'Daselbst will ich mit dir dann zusammenkommen; und von der Deckplatte herab, aus dem Raum zwischen den beiden Cheruben hervor, die auf der Gesetzeslade stehen, will ich dir alles mitteilen, was ich den Israeliten durch dich aufzutragen habe.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 23, 'Ferner sollst du einen Tisch aus Akazienholz anfertigen, zwei Ellen lang, eine Elle breit und anderthalb Ellen hoch.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 24, 'Überziehe ihn mit feinem Gold und bringe an ihm ringsum einen goldenen Kranz an.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 25, 'Sodann bringe an ihm ringsum eine Einfassung an, die eine Handbreit hoch ist, und an dieser Einfassung wiederum einen goldenen Kranz ringsum.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 26, 'Dann fertige für ihn vier goldene Ringe an und befestige diese Ringe an den vier Ecken bei seinen vier Füßen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 27, 'Dicht an der Einfassung sollen sich die Ringe befinden zur Aufnahme der Stangen, mit denen man den Tisch tragen kann.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 28, 'Die Stangen verfertige aus Akazienholz und überziehe sie mit Gold; mit ihnen soll der Tisch getragen werden.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 29, 'Weiter fertige die für ihn erforderlichen Schüsseln und Schalen, die Kannen und Becher an, die zu den Trankopfern gebraucht werden; aus feinem Gold sollst du sie herstellen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 30, 'Auf den Tisch aber sollst du beständig Schaubrote vor mich hinlegen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 31, 'Weiter sollst du einen Leuchter aus feinem Gold anfertigen; in getriebener Arbeit soll der Leuchter, sein Fuß und sein Schaft, angefertigt werden; seine Blumenkelche – Knäufe mit Blüten – sollen aus einem Stück mit ihm gearbeitet sein.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 32, 'Sechs Arme sollen von seinen Seiten ausgehen, drei Arme auf jeder Seite des Leuchters.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 33, 'Drei mandelblütenförmige Blumenkelche – je ein Knauf mit einer Blüte – sollen sich an jedem Arm befinden; so soll es bei allen sechs Armen sein, die von dem Leuchter ausgehen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 34, 'Am Schaft selbst aber sollen sich vier mandelblütenförmige Blumenkelche – Knäufe mit Blüten – befinden,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 35, 'und zwar soll sich an ihm immer ein Knauf unter jedem Paar der sechs Arme befinden, die vom Schaft des Leuchters ausgehen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 36, 'Ihre Knäufe und Arme sollen aus einem Stück mit ihm bestehen: der ganze Leuchter soll eine einzige getriebene Arbeit von feinem Gold sein.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 37, 'Sodann sollst du sieben Lampen für ihn anfertigen; und man soll ihm diese Lampen so aufsetzen, daß sie den vor dem Leuchter liegenden Raum erleuchten.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 38, 'Auch die zugehörigen Lichtscheren und Pfannen sollen aus feinem Gold bestehen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 39, 'Aus einem Talent feinen Goldes soll man ihn nebst allen diesen Geräten herstellen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 40, 'Gib wohl acht, daß du alles genau nach dem Musterbild anfertigst, das dir auf dem Berge gezeigt werden soll.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 1, '»Die Wohnung aber sollst du aus zehn Teppichen herstellen; von gezwirntem Byssus, blauem und rotem Purpur und Karmesin, mit Cherubbildern, wie sie der Kunstweber wirkt, sollst du sie herstellen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 2, 'Die Länge eines jeden Teppichs soll 28 Ellen und die Breite 4 Ellen betragen; alle Teppiche sollen dieselbe Größe haben.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 3, 'Je fünf dieser Teppiche sollen zu einem Stück zusammengefügt werden, einer an den andern.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 4, 'Sodann sollst du Schleifen von blauem Purpur am Saum des äußersten Teppichs des einen zusammengefügten Stücks anbringen; und ebenso sollst du es am Saum des äußersten Teppichs bei dem andern zusammengefügten Stück machen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 5, 'Fünfzig Schleifen sollst du an dem einen Teppich anbringen und ebenso fünfzig Schleifen am Saum des Teppichs, der zu dem andern zusammengesetzten Stück gehört, die Schleifen müssen einander genau gegenüberstehen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 6, 'Sodann fertige fünfzig goldene Haken an und verbinde die Teppiche durch die Haken miteinander, so daß die Wohnung ein Ganzes bildet.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 7, 'Weiter sollst du Teppiche aus Ziegenhaar zu einer Zeltdecke über der Wohnung anfertigen; elf Teppiche sollst du zu diesem Zweck anfertigen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 8, 'Die Länge eines jeden Teppichs soll 30 Ellen und die Breite 4 Ellen betragen; die elf Teppiche sollen dieselbe Größe haben.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 9, 'Dann sollst du fünf von diesen Teppichen zu einem Stück für sich zusammenfügen und ebenso die anderen sechs Teppiche für sich, und zwar sollst du den sechsten Teppich an der Vorderseite des Zeltes doppelt legen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 10, 'Weiter sollst du fünfzig Schleifen am Saum des äußersten Teppichs des einen zusammengefügten Stückes anbringen und ebenso fünfzig Schleifen am Saum des äußersten Teppichs des andern zusammengesetzten Stückes.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 11, 'Dann fertige fünfzig kupferne Haken an, stecke diese Haken in die Schleifen und füge die Zeltdecke so zusammen, daß sie ein Ganzes bildet.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 12, 'Was aber das Überhangen des Überschusses an den Zeltteppichen betrifft, so soll die Hälfte des überschüssigen Teppichs an der Hinterseite der Wohnung herabhangen;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 13, 'und von dem, was an der Länge der Zeltteppiche überschüssig ist, soll auf beiden Seiten je eine Elle auf den Langseiten der Wohnung überhangen und so zu ihrer Bedeckung dienen. –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 14, 'Außerdem sollst du für das Zeltdach noch eine Schutzdecke von rotgefärbten Widderfellen und oben darüber noch eine andere Schutzdecke von Seekuhhäuten anfertigen.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 15, '»Weiter sollst du die Bretter für die Wohnung aus Akazienholz anfertigen; sie sollen aufrecht stehen;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 16, 'die Länge jedes Brettes soll zehn Ellen und die Breite anderthalb Ellen betragen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 17, 'An jedem Brett sollen zwei Zapfen sitzen, einer dem andern gegenüber eingefügt; so sollst du es an allen Brettern der Wohnung machen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 18, 'Und zwar sollst du an Brettern für die Wohnung herrichten: zwanzig Bretter für die Mittagsseite südwärts,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 19, 'und unter diesen zwanzig Brettern sollst du vierzig silberne Füße anbringen, nämlich je zwei Füße unter jedem Brett für seine beiden Zapfen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 20, 'Ebenso für die andere Seite der Wohnung, nämlich für die Nordseite, zwanzig Bretter');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 21, 'und vierzig silberne Füße, nämlich je zwei Füße unter jedes Brett.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 22, 'Für die Hinterseite der Wohnung aber, nach Westen zu, sollst du sechs Bretter anfertigen,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 23, 'außerdem noch zwei Bretter für die Ecken der Wohnung an der Hinterseite.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 24, 'Diese sollen unten und gleicherweise oben vollständig sein bis an den ersten Ring hin. So soll es bei beiden sein: die beiden Eckstücke sollen sie bilden.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 25, 'Demnach sollen es im ganzen acht Bretter sein und ihre Füße von Silber: sechzehn Füße, immer zwei Füße unter jedem Brett.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 26, 'Sodann sollst du Riegel aus Akazienholz anfertigen, fünf für die Bretter der einen Langseite der Wohnung');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 27, 'und fünf Riegel für die Bretter der andern Langseite der Wohnung und fünf Riegel für die Bretter an der Hinterseite der Wohnung gegen Westen;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 28, 'und der mittlere Riegel soll in der Mitte der Bretter von einem Ende bis zum andern durchlaufen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 29, 'Die Bretter aber sollst du mit Gold überziehen und die dazu gehörigen Ringe, die zur Aufnahme der Riegel dienen, aus Gold anfertigen und auch die Riegel mit Gold überziehen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 30, 'Dann sollst du die Wohnung in der erforderlichen Weise aufrichten, wie es dir auf dem Berg gezeigt worden ist.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 31, '»Weiter sollst du einen Vorhang von blauem und rotem Purpur, von Karmesin und gezwirntem Byssus anfertigen, und zwar in Kunstweberarbeit mit (eingewirkten) Cherubbildern.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 32, 'Du sollst ihn dann an vier mit Gold überzogenen Ständern von Akazienholz aufhängen, deren Haken von Gold sind und die auf vier silbernen Füßen stehen;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 33, 'und zwar sollst du den Vorhang unter den Teppichhaken anbringen und dorthin, hinter den Vorhang, die Lade mit dem Gesetz bringen, so daß der Vorhang für euch eine Scheidewand zwischen dem Heiligen und dem Allerheiligsten bildet.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 34, 'Dann sollst du die Deckplatte auf die Gesetzeslade im Allerheiligsten legen,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 35, 'den Tisch aber draußen vor dem Vorhang aufstellen und den Leuchter dem Tisch gegenüber an die Südseite der Wohnung setzen, während du den Tisch an die Nordseite stellst.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 36, 'Ferner fertige für den Eingang des Zeltes einen Vorhang von blauem und rotem Purpur, von Karmesin und gezwirntem Byssus in Buntwirkerarbeit an.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 37, 'Für diesen Vorhang fertige fünf Ständer von Akazienholz an und überziehe sie mit Gold; ihre Haken sollen von Gold sein, und fünf kupferne Fußgestelle sollst du für sie gießen.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 27, 1, '»Den (Brandopfer-) Altar sollst du aus Akazienholz anfertigen, fünf Ellen lang und fünf Ellen breit – viereckig soll der Altar sein – und drei Ellen hoch.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 27, 2, 'Die zu ihm gehörenden Hörner sollst du an seinen vier Ecken anbringen; sie sollen mit ihm aus einem Stück bestehen; und du sollst ihn mit Kupfer überziehen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 27, 3, 'Sodann verfertige die zugehörigen, zur Wegräumung der Fettasche dienenden Töpfe, sowie die zugehörigen Schaufeln, Becken, Gabeln und Pfannen; alle erforderlichen Geräte sollst du aus Kupfer herstellen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 27, 4, 'Weiter fertige ein Gitterwerk, netzartig, aus Kupfer für den Altar an, und setze an das Netzwerk vier kupferne Ringe an seine vier Ecken,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 27, 5, 'und bringe es unterhalb der Einfassung des Altars von unten auf an, so daß das Netzwerk bis zur halben Höhe des Altars hinaufgeht.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 27, 6, 'Sodann fertige Tragstangen für den Altar an, Stangen von Akazienholz, und überziehe sie mit Kupfer.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 27, 7, 'Diese seine Stangen sollen dann in die Ringe gesteckt werden, so daß sich die Stangen an den beiden Seiten des Altars befinden, wenn man ihn trägt.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 27, 8, 'Du sollst ihn aus Brettern so herstellen, daß er inwendig hohl ist; wie man es dir auf dem Berge gezeigt hat, so soll man ihn anfertigen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 27, 9, 'Den Vorhof der Wohnung aber sollst du so herstellen: auf der Mittagseite, nach Süden zu, Umhänge für den Vorhof aus gezwirntem Byssus, hundert Ellen lang, für die eine Seite;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 27, 10, 'dazu zwanzig Ständer nebst den zugehörigen zwanzig kupfernen Füßen; die Nägel und Ringbänder der Säulen müssen von Silber sein.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 27, 11, 'Ebenso auf der nördlichen Langseite: Umhänge von hundert Ellen Länge; dazu zwanzig Ständer nebst den zugehörigen zwanzig kupfernen Füßen; die Nägel und Ringbänder der Säulen müssen von Silber sein.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 27, 12, 'Ferner auf der westlichen Breitseite des Vorhofs: Umhänge von fünfzig Ellen Länge; dazu zehn Ständer nebst den zugehörigen zehn Füßen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 27, 13, 'Die Breite der östlichen Vorderseite des Vorhofs soll fünfzig Ellen betragen,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 27, 14, 'und zwar fünfzehn Ellen Umhänge für die eine Seite mit ihren drei Säulen und deren drei Füßen,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 27, 15, 'und ebenso fünfzehn Ellen Umhänge für die andere Seite mit ihren drei Säulen und deren drei Füßen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 27, 16, 'Am Eingang zum Vorhof aber soll sich ein Vorhang von zwanzig Ellen Breite befinden, aus blauem und rotem Purpur, aus Karmesin und gezwirntem Byssus in Buntwirkerarbeit gefertigt; dazu vier Säulen nebst deren vier Füßen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 27, 17, 'Alle Säulen rings um den Vorhof sollen mit silbernen Ringbändern versehen sein, auch ihre Nägel von Silber, ihre Füße aber von Kupfer.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 27, 18, 'Die Länge des Vorhofs soll hundert Ellen, die Breite je fünfzig und die Höhe fünf Ellen betragen, nämlich Umhänge von gezwirntem Byssus; ihre Füße aber sollen von Kupfer sein.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 27, 19, 'Alle Gerätschaften der Wohnung für den gesamten Dienst an ihr, auch alle ihre Pflöcke und alle Pflöcke des Vorhofs sollen von Kupfer sein.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 27, 20, 'Sodann befiehl du den Israeliten, dir ganz reines Öl aus zerstoßenen Oliven für den Leuchter zu bringen, damit man beständig Lampen aufsetzen kann.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 27, 21, 'Im Offenbarungszelt, außerhalb des Vorhangs, der sich vor (der Lade mit) dem Gesetz befindet, soll Aaron mit seinen Söhnen die Lampen zurechtmachen, damit sie vom Abend bis zum Morgen vor dem HERRN brennen. Diese Verordnung soll ewige Geltung für die Israeliten von Geschlecht zu Geschlecht haben!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 1, '»Du aber sollst deinen Bruder Aaron nebst seinen Söhnen aus der Mitte der Israeliten zu dir herantreten lassen, damit er mir als Priester diene, nämlich Aaron und seine Söhne Nadab und Abihu, Eleasar und Ithamar.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 2, 'Du sollst also für deinen Bruder Aaron heilige Kleider anfertigen lassen, ihm zur Ehre und zum Schmuck.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 3, 'Besprich dich also mit allen kunstverständigen Personen, die ich mit kunstsinnigem Geist erfüllt habe, daß sie die Kleider Aarons anfertigen, damit man ihn darin weihe und er mir als Priester dienen kann.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 4, 'Folgendes aber sind die Kleidungsstücke, die sie anfertigen sollen: das Brustschild, das Schulterkleid, das Obergewand, das Unterkleid aus gewürfeltem Stoff, der Kopfbund und der Gürtel. Diese heiligen Kleider sollen sie für deinen Bruder Aaron und seine Söhne anfertigen, damit er mir als Priester diene;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 5, 'und zwar sollen sie Gold, blauen und roten Purpur, Karmesin und Byssus dazu verwenden.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 6, '»Das Schulterkleid sollen sie aus Gold, blauem und rotem Purpur, Karmesin und gezwirntem Byssus in Kunstweberarbeit anfertigen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 7, 'Es soll ein Paar zusammenfügbarer Schulterstücke haben und an seinen beiden (oberen) Enden mittels derselben zusammengefügt werden.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 8, 'Die Binde, die sich an ihm befindet und dazu dient, es fest anzulegen, soll von gleicher Arbeit und aus einem Stück mit ihm bestehen, nämlich aus Goldfäden, blauem und rotem Purpur, Karmesin und gezwirntem Byssus.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 9, 'Ferner sollst du zwei Onyxsteine nehmen und die Namen der Söhne Israels in sie eingraben,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 10, 'sechs ihrer Namen auf den einen Stein und die sechs übrigen Namen auf den andern Stein, und zwar nach ihrer Geburtsfolge.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 11, 'In Steinschneiderarbeit, mittels Siegelstecherkunst, sollst du die beiden Steine mit den Namen der Söhne Israels stechen lassen, und mit einer Einfassung von goldenem Flechtwerk sollst du sie versehen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 12, 'Dann sollst du die beiden Steine auf die beiden Schulterstücke des Schulterkleides als Steine des Gedenkens an die Israeliten setzen, damit Aaron ihre Namen vor dem HERRN auf seinen beiden Schultern zur Erinnerung trägt.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 13, 'Ferner sollst du Geflechte von Golddraht anfertigen');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 14, 'und zwei Kettchen von feinem Gold; in Gestalt von gedrehten Schnüren sollst du sie anfertigen und diese aus Schnüren geflochtenen Kettchen an den Goldgeflechten befestigen.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 15, '»Sodann fertige das Orakel-Brustschild in Kunstweberarbeit an; ganz so, wie das Schulterkleid gearbeitet ist, sollst du es anfertigen, nämlich aus Gold, blauem und rotem Purpur, Karmesin und gezwirntem Byssus sollst du es herstellen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 16, 'Viereckig soll es sein, doppelt gelegt, eine Spanne lang und eine Spanne breit.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 17, 'Besetze es mit einem Besatz von Edelsteinen in vier Reihen von Steinen; eine Reihe: ein Karneol, ein Topas und ein Smaragd sollen die erste Reihe bilden;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 18, 'die zweite Reihe: ein Rubin, ein Saphir und ein Jaspis;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 19, 'die dritte Reihe: ein Hyazinth, ein Achat und ein Amethyst;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 20, 'die vierte Reihe: ein Chrysolith, ein Soham und ein Onyx; in Goldgeflecht sollen sie bei ihrer Einsetzung gefaßt sein.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 21, 'Die Steine sollen also entsprechend den Namen der Söhne Israels zwölf sein, nach deren Namen; mittels Siegelstecherkunst sollen sie, ein jeder mit seinem besonderen Namen nach den zwölf Stämmen versehen sein.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 22, 'An dem Brustschild sollst du dann schnurähnlich geflochtene Kettchen von feinem Gold befestigen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 23, 'Du sollst nämlich zwei goldene Ringe an dem Brustschilde anbringen und diese zwei Ringe an den beiden (oberen) Ecken des Brustschildes befestigen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 24, 'Hierauf befestige die beiden goldenen Schnüre an den beiden Ringen, die sich an den (oberen) Ecken des Brustschildes befinden,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 25, 'und befestige die beiden (anderen) Enden der beiden Schnüre an den beiden Geflechten und diese wiederum an den Schulterstücken des Schulterkleides auf dessen Vorderseite.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 26, 'Dann fertige noch zwei goldene Ringe an und setze sie an die beiden (unteren) Ecken des Brustschildes, und zwar an seinen inneren Saum, der dem Schulterkleide zugekehrt ist.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 27, 'Fertige dann noch zwei goldene Ringe an und setze sie an die beiden Schulterstücke des Schulterkleides, unten an seine Vorderseite, dicht bei der Stelle, wo das Schulterkleid zusammengeht, oberhalb der Binde des Schulterkleides.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 28, 'Hierauf knüpfe man das Brustschild mit seinen Ringen vermittels einer Schnur von blauem Purpur an die Ringe des Schulterkleides, so daß das Brustschild über der Binde des Schulterkleides fest anliegt und das Brustschild sich nicht von seiner Stelle auf dem Schulterkleide verschieben kann.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 29, 'Aaron soll so die Namen der Söhne Israels an dem Orakel-Brustschild auf seinem Herzen tragen, sooft er in das Heiligtum hineingeht, zur beständigen Erinnerung vor dem HERRN.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 30, 'In das Orakel-Brustschild aber sollst du die (heiligen Lose) Urim und Thummim tun, damit sie auf dem Herzen Aarons liegen, sooft er vor den HERRN tritt; und Aaron soll so das Orakel für die Israeliten beständig vor dem HERRN auf seinem Herzen tragen.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 31, '»Sodann sollst du das Obergewand zu dem Schulterkleide ganz aus blauem Purpur anfertigen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 32, 'Seine Kopföffnung soll sich in der Mitte befinden, und rings um diese Öffnung soll ein Saum in Weberarbeit gehen; eine Öffnung soll es haben wie die eines Panzerhemdes, damit es nicht einreißt.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 33, 'Unten an seinem Saum sollst du Granatäpfel aus blauem und rotem Purpur und Karmesin ringsum anbringen und zwischen ihnen goldene Glöckchen ringsum,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 34, 'so daß am ganzen Saum des Obergewandes ringsum immer auf ein goldenes Glöckchen ein Granatapfel folgt.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 35, 'Aaron soll (dieses Kleid) tragen, um den heiligen Dienst darin zu versehen, damit man es klingeln hört, sooft er in das Heiligtum vor den HERRN hineingeht und sooft er hinausgeht, damit er nicht stirbt.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 36, '»Weiter sollst du ein Stirnblatt aus feinem Gold anfertigen und auf ihm mittels Siegelstecherarbeit die Worte eingraben: ›Dem HERRN geweiht‹.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 37, 'Du sollst es dann mit einer Schnur von blauem Purpur versehen, damit es am Kopfbund angebracht werden kann: an dessen Vorderseite soll es sich befinden,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 38, 'und zwar soll es auf der Stirn Aarons liegen, damit Aaron die Verfehlungen in betreff der heiligen Gaben, welche die Israeliten weihen, auf sich nimmt, welche heiligen Gaben sie auch darbringen mögen. Es soll also beständig auf seiner Stirn liegen, um die Israeliten wohlgefällig vor dem HERRN zu machen. –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 39, 'Sodann sollst du das Unterkleid aus Byssus würfelförmig gemustert weben und einen Kopfbund aus Byssus anfertigen, auch einen Gürtel in Buntwirkerarbeit herstellen.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 40, '»Ferner sollst du für die Söhne Aarons Unterkleider herstellen und ihnen Gürtel und hohe Mützen zur Ehre und zum Schmuck anfertigen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 41, 'Dann sollst du deinen Bruder Aaron und ebenso seine Söhne damit bekleiden und sollst sie salben, sie in ihr Amt einsetzen und sie weihen, damit sie mir als Priester dienen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 42, 'Auch fertige ihnen leinene Unterbeinkleider an zur Verhüllung ihrer Blöße; diese sollen von den Hüften bis an die Schenkel reichen,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 43, 'und Aaron sowie seine Söhne sollen sie tragen, sooft sie in das Offenbarungszelt hineingehen oder an den Altar treten, um den Dienst im Heiligtum zu verrichten, damit sie keine Verschuldung auf sich laden und nicht sterben müssen. Diese Verordnung soll für ihn und seine Nachkommen nach ihm ewige Gültigkeit haben.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 1, '»Behufs ihrer Weihe für den Priesterdienst, den sie mir zu verrichten haben, sollst du folgendermaßen verfahren: Nimm einen jungen Stier und zwei fehlerlose Widder,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 2, 'ungesäuertes Brot und ungesäuerte, mit Öl gemengte Kuchen sowie ungesäuerte, mit Öl bestrichene Fladen; aus feinem Weizenmehl sollst du sie bereiten.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 3, 'Lege sie dann in einen Korb und bringe sie in dem Korbe herbei, dazu den jungen Stier und die beiden Widder.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 4, 'Dann laß Aaron und seine Söhne an den Eingang des Offenbarungszeltes treten und laß sie eine Abwaschung mit Wasser an sich vornehmen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 5, 'Hierauf nimm die heiligen Kleider und laß Aaron das Unterkleid und das zum Schulterkleid gehörige Obergewand sowie das Schulterkleid selbst nebst dem Brustschild anlegen und gürte ihm die Binde des Schulterkleides fest um;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 6, 'setze ihm dann den Kopfbund aufs Haupt und befestige das heilige Diadem am Kopfbund.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 7, 'Hierauf nimm das Salböl, gieße ihm (etwas davon) aufs Haupt und salbe ihn so.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 8, 'Sodann laß auch seine Söhne herantreten und sich die Unterkleider anlegen;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 9, 'umgürte sie mit dem Gürtel [Aaron und seine Söhne] und laß sie die hohen Mützen aufsetzen, damit ihnen das Priestertum kraft einer ewig gültigen Einsetzung zusteht. Wenn du so Aaron und seine Söhne in ihr Amt eingesetzt hast,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 10, 'sollst du den jungen Stier vor das Offenbarungszelt führen lassen, und Aaron nebst seinen Söhnen sollen ihre Hände fest auf den Kopf des Stieres legen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 11, 'Dann schlachte den Stier vor dem HERRN am Eingang des Offenbarungszeltes,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 12, 'nimm etwas von dem Blut des Stieres und streiche es mit deinem Finger an die Hörner des Altars; alles übrige Blut aber schütte an den Fuß des Altars.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 13, 'Sodann nimm das gesamte Fett, welches die Eingeweide überzieht, sowie den Leberlappen und die beiden Nieren samt dem daransitzenden Fett und laß es auf dem Altar in Rauch aufgehen;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 14, 'das Fleisch des Stieres aber sowie sein Fell und den Inhalt seiner Gedärme verbrenne im Feuer außerhalb des Lagers: es ist ein Sündopfer.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 15, 'Dann nimm den einen Widder, und Aaron nebst seinen Söhnen sollen ihre Hände fest auf den Kopf des Widders legen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 16, 'Hierauf schlachte den Widder, nimm sein Blut und sprenge es an den Altar ringsum;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 17, 'den Widder aber zerlege in seine Stücke, wasche seine Eingeweide und Beine ab und lege sie zu seinen übrigen Stücken und zu seinem Kopf');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 18, 'und laß dann den ganzen Widder auf dem Altar in Rauch aufgehen: es ist ein Brandopfer für den HERRN, ein lieblicher Geruch; ein Feueropfer ist es für den HERRN.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 19, 'Hierauf nimm den zweiten Widder, und Aaron nebst seinen Söhnen sollen ihre Hände fest auf den Kopf des Widders legen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 20, 'Darauf schlachte den Widder, nimm etwas von seinem Blut und bestreiche damit das rechte Ohrläppchen Aarons und das rechte Ohrläppchen seiner Söhne sowie den Daumen ihrer rechten Hand und die große Zehe ihres rechten Fußes; das übrige Blut aber sprenge auf den Altar ringsum.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 21, 'Sodann nimm etwas von dem Blut, das sich auf dem Altar befindet, sowie von dem Salböl und besprenge mit ihm Aaron und seine Kleider, ebenso seine Söhne und deren Kleider, damit er und seine Kleider und ebenso seine Söhne und deren Kleider geheiligt sind.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 22, 'Nimm dann von dem Widder das Fett, nämlich den Fettschwanz und das Fett, welches die Eingeweide überzieht, sowie den Leberlappen und die beiden Nieren samt dem daransitzenden Fett sowie die rechte Keule – denn es ist ein Einweihungswidder –,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 23, 'dazu einen Laib Brot, einen mit Öl gemengten Brotkuchen und einen Fladen aus dem Korb mit den ungesäuerten Broten, der vor den HERRN hingestellt ist;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 24, 'lege dies alles dem Aaron und seinen Söhnen in die Hände und laß es als Webeopfer vor dem HERRN weben.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 25, 'Dann nimm es ihnen wieder aus den Händen und laß es auf dem Altar über dem Brandopfer in Rauch aufgehen zu einem lieblichen Geruch vor dem HERRN: ein Feueropfer ist es für den HERRN.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 26, 'Hierauf nimm die Brust von dem Einweihungswidder, der für Aaron bestimmt ist, und webe sie als Webeopfer vor dem HERRN: dann soll sie dir als Anteil zufallen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 27, 'Darum sollst du die Brust des Webeopfers und die Hebekeule, die von dem für Aaron und für seine Söhne bestimmten Einweihungswidder gewebt und als Hebe entnommen sind, für geweiht erklären:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 28, 'sie sollen für Aaron und seine Söhne eine von seiten der Israeliten ewig zu leistende Gebühr sein; denn es ist ein Hebeopfer und soll seitens der Israeliten als Hebeopfer von ihren Heilsopfern abgegeben werden, als ihr Hebeopfer für den HERRN.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 29, 'Die heiligen Kleider Aarons aber sollen nach ihm an seine Söhne kommen, damit man sie darin salbe und sie darin in ihr Amt einsetze.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 30, 'Sieben Tage lang soll sie derjenige von seinen Söhnen tragen, der an seiner Statt Priester wird und in das Offenbarungszelt hineingehen wird, um den Dienst im Heiligtum zu verrichten.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 31, 'Den Einweihungswidder aber sollst du nehmen und sein Fleisch an heiliger Stätte kochen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 32, 'Dann sollen Aaron und seine Söhne das Fleisch des Widders samt dem Brot, das sich in dem Korbe befindet, am Eingang des Offenbarungszeltes verzehren:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 33, 'sie sollen die Stücke verzehren, durch welche die Sühne für sie bewirkt wurde, als man sie in ihr Amt einsetzte und sie weihte; aber ein Fremder darf nicht davon essen, denn sie sind heilig.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 34, 'Und wenn von dem Fleisch des Einweihungsopfers oder von dem Brot etwas bis zum Morgen übrigbleibt, so sollst du das Übriggebliebene im Feuer verbrennen: es darf nicht mehr gegessen werden, denn es ist heilig.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 35, 'So also sollst du mit Aaron und seinen Söhnen verfahren, genau so, wie ich dir geboten habe: sieben Tage soll die Einweihung dauern!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 36, '»Und für jeden Tag sollst du einen jungen Stier als Sündopfer zum Vollzug der Sühne darbringen und den Altar entsündigen, indem du die Sühngebräuche an ihm vollziehst, und sollst ihn salben, um ihn zu weihen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 37, 'Sieben Tage hindurch sollst du die Sühngebräuche am Altar vornehmen, um ihn zu weihen, damit der Altar hochheilig werde: jeder, der den Altar berührt, soll dem Heiligtum verfallen sein!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 38, '»Folgendes aber ist es, was du auf dem Altar opfern sollst: zwei einjährige Lämmer an jedem Tage ohne Ausnahme.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 39, 'Das eine Lamm sollst du am Morgen opfern, das andere gegen Abend,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 40, 'und außerdem ein Zehntel Epha Feinmehl, das mit einem Viertel Hin Öl von zerstoßenen Oliven gemengt ist; und als Trankopfer soll ein Viertel Hin Wein zu dem einen Lamm kommen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 41, 'Das zweite Lamm aber sollst du gegen Abend opfern – mit dem Speisopfer und dem zugehörigen Trankopfer sollst du es dabei halten wie am Morgen – zu einem lieblichen Geruch, als ein Feueropfer für den HERRN:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 42, 'ein regelmäßiges Brandopfer (soll es bei euch sein) für eure Geschlechter vor dem HERRN am Eingang zum Offenbarungszelt, wo ich mit euch in Verkehr treten werde, um dort mit dir zu reden.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 43, '»Ich will dort nämlich mit den Israeliten in Verkehr treten, und es (das Zelt) wird durch meine Herrlichkeit geheiligt werden.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 44, 'Ich will also das Offenbarungszelt und den Altar heiligen; auch Aaron und seine Söhne will ich heiligen, damit sie mir als Priester dienen;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 45, 'und ich will inmitten der Israeliten wohnen und will ihr Gott sein,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 46, 'und sie sollen erkennen, daß ich, der HERR, ihr Gott bin, der ich sie aus Ägypten hinausgeführt habe, um mitten unter ihnen zu wohnen, ich, der HERR, ihr Gott.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 1, '»Sodann sollst du einen Altar herstellen, um Räucherwerk auf ihm zu verbrennen; aus Akazienholz sollst du ihn anfertigen;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 2, 'eine Elle lang und eine Elle breit, viereckig soll er sein und zwei Ellen hoch; seine Hörner sollen aus einem Stück mit ihm bestehen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 3, 'Du sollst ihn, sowohl seine Platte als auch die Wände ringsum und die Hörner, mit feinem Gold überziehen und einen goldenen Kranz ringsum an ihm anbringen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 4, 'Zwei goldene Ringe sollst du für ihn anfertigen und sie unterhalb seines Kranzes an seinen beiden Seiten anbringen; die sollen zur Aufnahme der Stangen dienen, mittels derer man ihn tragen kann.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 5, 'Die Stangen sollst du aus Akazienholz anfertigen und sie mit Gold überziehen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 6, 'Du sollst den Altar dann vor dem Vorhang aufstellen, der sich vor der Gesetzeslade befindet, der Deckplatte gegenüber, die über dem Gesetz liegt, woselbst ich mit dir in Verkehr treten werde.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 7, 'Aaron soll dann auf ihm wohlriechendes Räucherwerk verbrennen; an jedem Morgen, wenn er die Lampen zurechtmacht, soll er es verbrennen;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 8, 'ebenso soll Aaron es verbrennen, wenn er gegen Abend die Lampen aufsetzt: ein regelmäßiges Rauchopfer vor dem HERRN soll es für ewige Zeiten sein.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 9, 'Ihr dürft kein ungehöriges Räucherwerk und kein Brand- oder Speisopfer auf ihm darbringen; auch kein Trankopfer dürft ihr auf ihm ausgießen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 10, 'Aaron soll einmal im Jahr die Sühnehandlung an seinen Hörnern vornehmen; mit dem Blut des Versöhnungsopfers soll er einmal im Jahr die Sühnehandlung an ihm vornehmen, von Geschlecht zu Geschlecht: hochheilig ist er dem HERRN.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 11, 'Hierauf sagte der HERR zu Mose folgendes:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 12, '»Wenn du die Kopfzahl der Israeliten, soweit sie gemustert werden, aufnimmst, so sollen sie ein jeder ein Lösegeld für ihr Leben dem HERRN bei ihrer Musterung entrichten, damit keine schlimme Heimsuchung bei ihrer Musterung über sie kommt.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 13, 'Es soll also ein jeder, der sich der Musterung zu unterziehen hat, einen halben Schekel entrichten – nach dem Schekel des Heiligtums, wobei zwanzig Gera auf den Schekel gehen –, einen halben Schekel als Abgabe an den HERRN.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 14, 'Jeder, der sich der Musterung zu unterziehen hat, von zwanzig Jahren an und darüber, soll die Abgabe an den HERRN entrichten:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 15, 'der Reiche soll nicht mehr und der Arme nicht weniger als einen halben Schekel geben, wenn ihr die Abgabe an den HERRN entrichtet, um die Deckung eures Lebens zu bewirken.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 16, 'Du sollst also dieses Sühnegeld von den Israeliten erheben und es zur Bestreitung der Kosten des Dienstes am Offenbarungszelt verwenden; so wird es den Israeliten zum (gnädigen) Gedenken vor dem HERRN dienen, um Deckung eures Lebens zu bewirken.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 17, 'Weiter sagte der HERR zu Mose folgendes:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 18, '»Fertige auch ein kupfernes Becken nebst einem kupfernen Gestell dazu für die Waschungen an, stelle es zwischen dem Offenbarungszelt und dem Altar auf und tu Wasser hinein,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 19, 'damit Aaron und seine Söhne ihre Hände und Füße daraus waschen;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 20, 'sooft sie in das Offenbarungszelt hineingehen, sollen sie sich mit Wasser waschen, damit sie nicht sterben, oder auch, wenn sie an den Altar treten, um ihren Dienst zu verrichten, indem sie Feueropfer für den HERRN in Rauch aufgehen lassen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 21, 'Da sollen sie sich dann ihre Hände und Füße waschen, damit sie nicht sterben; und dies soll eine ewiggültige Verordnung für sie sein, für Aaron und seine Nachkommen von Geschlecht zu Geschlecht.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 22, 'Weiter gebot der HERR dem Mose folgendes:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 23, '»Nimm du dir Wohlgerüche von der besten Sorte, nämlich Stakte fünfhundert Schekel, wohlriechenden Zimt halb soviel, also zweihundertundfünfzig Schekel, ferner wohlriechenden Kalmus ebenfalls zweihundertundfünfzig Schekel');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 24, 'und Kassia fünfhundert Schekel nach dem Gewicht des Heiligtums, dazu ein Hin Olivenöl,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 25, 'und stelle daraus ein heiliges Salböl her, eine Salbenmischung, wie sie der Salbenmischer herstellt: heiliges Salböl soll es sein.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 26, 'Du sollst damit das Offenbarungszelt und die Gesetzeslade salben,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 27, 'ferner den Tisch samt allen seinen Geräten, den Leuchter samt den zugehörigen Geräten und den Räucheraltar,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 28, 'ferner den Brandopferaltar samt allen seinen Geräten und das Becken nebst seinem Gestell.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 29, 'So sollst du sie heiligen, damit sie hochheilig werden: jeder, der sie berührt, soll dem Heiligtum verfallen sein!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 30, 'Auch Aaron und seine Söhne sollst du salben und sie dadurch zu Priestern für meinen Dienst weihen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 31, 'Den Israeliten aber sollst du folgendes gebieten: ›Als ein mir heiliges Salböl soll dieses euch für alle eure Geschlechter gelten!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 32, 'Auf keines Menschen Leib darf es gegossen werden! und ihr dürft solches Salböl nicht in der gleichen Zusammensetzung für euren eigenen Gebrauch bereiten: es ist heilig und soll euch auch als heilig gelten!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 33, 'Wer ein gleiches durch Mischung herstellt und etwas davon an eine unbefugte Person bringt, der soll aus seinen Volksgenossen ausgerottet werden!‹«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 34, 'Weiter gebot der HERR dem Mose folgendes: »Nimm dir Gewürzkräuter, nämlich Stakte, Räucherklaue, Galban, [Gewürzkräuter] und reinen Weihrauch, alle zu gleichen Teilen,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 35, 'und stelle daraus ein Räucherwerk her, eine würzige Mischung, wie sie der Salbenmischer herstellt, mit (etwas) Salz vermengt, sonst rein, zu heiligem Gebrauch bestimmt.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 36, 'Zerstoße etwas davon zu feinem Pulver und lege etwas davon vor die Gesetzeslade im Offenbarungszelt, woselbst ich in Verkehr mit dir treten werde: als hochheilig soll es euch gelten!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 37, 'Das Räucherwerk aber, das ihr für euch selbst bereitet, dürft ihr nicht in dem gleichen Mischungsverhältnis herstellen; nein, es soll dir als dem HERRN geheiligt gelten!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 38, 'Wer sich das gleiche Räucherwerk bereitet, um seinen Wohlgeruch zu genießen, soll aus seinen Volksgenossen ausgerottet werden!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 31, 1, 'Weiter sagte der HERR zu Mose folgendes:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 31, 2, '»Wisse wohl: ich habe Bezaleel, den Sohn Uris, den Enkel Hurs, aus dem Stamme Juda, namentlich berufen');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 31, 3, 'und ihn mit göttlichem Geist erfüllt, mit Kunstsinn und Einsicht, mit Verstand und allerlei Fertigkeiten,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 31, 4, 'um Kunstwerke zu ersinnen, Arbeiten in Gold, in Silber und in Kupfer auszuführen,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 31, 5, 'Edelsteine zu schneiden, um Kunstwerke damit zu besetzen, Holz zu schnitzen, kurz Werke jeder Art kunstvoll auszuführen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 31, 6, 'Zugleich habe ich ihm Oholiab, den Sohn Ahisamachs, aus dem Stamme Dan, beigegeben und allen Kunstverständigen die erforderliche Begabung verliehen, damit sie alles, was ich dir geboten habe, herstellen,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 31, 7, 'nämlich das Offenbarungszelt und die Gesetzeslade mit der Deckplatte darauf und alle anderen Geräte des Zeltes,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 31, 8, 'nämlich den Tisch mit allen seinen Geräten, den Leuchter aus feinem Gold samt allen zugehörigen Geräten, den Räucheraltar,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 31, 9, 'den Brandopferaltar mit allen seinen Geräten, das Becken mit seinem Gestell;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 31, 10, 'sodann die [Prachtkleider und] heiligen Kleider für den Priester Aaron sowie die Kleider seiner Söhne, die mir als Priester dienen sollen;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 31, 11, 'ferner das Salböl und das wohlriechende Räucherwerk für das Heiligtum. Genau so, wie ich dir geboten habe, sollen sie alles ausführen!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 31, 12, 'Weiter gebot der HERR dem Mose folgendes:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 31, 13, '»Du aber präge den Israeliten folgendes Gebot ein: ›Beobachtet ja meine Sabbate! Denn sie sind ein Zeichen (des Bundes) zwischen mir und euch für eure künftigen Geschlechter, damit ihr erkennt, daß ich, der HERR, es bin, der euch heiligt.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 31, 14, 'Beobachtet also den Sabbat! Denn er soll euch heilig sein; wer ihn entweiht, soll unfehlbar mit dem Tode bestraft werden; ja wer irgendeine Arbeit an diesem Tage verrichtet, ein solcher Mensch soll aus der Mitte seiner Volksgenossen ausgerottet werden:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 31, 15, 'Sechs Tage lang darf gearbeitet werden, aber am siebten Tage ist der dem HERRN geheiligte Feiertag mit vollständiger Ruhe: wer irgend am Sabbattag eine Arbeit verrichtet, soll unfehlbar mit dem Tode bestraft werden!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 31, 16, 'So sollen also die Israeliten den Sabbat beobachten, indem sie den Ruhetag von Geschlecht zu Geschlecht feiern, als eine ewige Verpflichtung.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 31, 17, 'Für ewige Zeiten soll er ein Zeichen (des Bundes) zwischen mir und den Israeliten sein! Denn in sechs Tagen hat der HERR den Himmel und die Erde geschaffen, aber am siebten Tag hat er gefeiert und geruht.‹«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 31, 18, 'Als der HERR nun seine Unterredung mit Mose auf dem Berge Sinai beendet hatte, übergab er ihm die beiden Gesetzestafeln, steinerne Tafeln, die vom Finger Gottes beschrieben waren.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 1, 'Als aber das Volk sah, daß Mose mit seiner Rückkehr vom Berge auf sich warten ließ, sammelte sich das Volk um Aaron und sagte zu ihm: »Auf! Mache uns einen Gott, der vor uns herziehen soll! Denn von diesem Mose, dem Mann, der uns aus dem Land Ägypten hierher geführt hat, wissen wir nicht, was aus ihm geworden ist.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 2, 'Da antwortete ihnen Aaron: »Reißt die goldenen Ringe ab, die eure Frauen und eure Söhne und Töchter in den Ohren tragen, und bringt sie mir her!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 3, 'Da riß das gesamte Volk sich die goldenen Ringe ab, die sie in den Ohren trugen, und brachten sie zu Aaron.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 4, 'Der nahm sie von ihnen in Empfang, bearbeitete das Gold mit dem Meißel und machte ein gegossenes Kalb daraus. Da riefen sie: »Dies ist dein Gott, Israel, der dich aus dem Land Ägypten hergeführt hat!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 5, 'Als Aaron das sah, errichtete er einen Altar vor dem Stierbild und ließ ausrufen: »Morgen findet ein Fest statt zu Ehren des HERRN!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 6, 'Da machten sie sich am andern Morgen früh auf, opferten Brandopfer und brachten Heilsopfer dar, und das Volk setzte sich nieder, um zu essen und zu trinken; dann standen sie auf, um sich zu belustigen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 7, 'Da sagte der HERR zu Mose: »Auf! Gehe hinab! Denn dein Volk, das du aus Ägypten hergeführt hast, begeht eine große Sünde:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 8, 'gar schnell sind sie von dem Wege abgewichen, den ich ihnen geboten habe; sie haben sich ein gegossenes Stierbild gemacht und es angebetet, haben ihm geopfert und ausgerufen: ›Dies ist dein Gott, Israel, der dich aus dem Land Ägypten hergeführt hat!‹«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 9, 'Dann fuhr der HERR fort: »Ich habe dieses Volk beobachtet und sehe wohl: es ist ein halsstarriges Volk.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 10, 'Nun so laß mich, daß mein Zorn gegen sie entbrenne und ich sie vernichte! Dich aber will ich zu einem großen Volk machen!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 11, 'Mose aber suchte den HERRN, seinen Gott, zu besänftigen, indem er sagte: »Warum, o HERR, soll dein Zorn gegen dein Volk entbrennen, das du mit großer Kraft und starkem Arm aus dem Land Ägypten herausgeführt hast?');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 12, 'Warum sollen die Ägypter sagen: ›In böser Absicht hat er sie hinausgeführt, um sie in den Bergen umkommen zu lassen und sie vom Erdboden zu vertilgen‹? Laß ab von deiner Zornesglut und laß dir das Unheil leid sein, das du deinem Volk zugedacht hast!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 13, 'Denke an deine Knechte Abraham, Isaak und Israel, denen du bei dir selbst zugeschworen und verheißen hast: ›Ich will eure Nachkommenschaft so zahlreich machen wie die Sterne am Himmel und will dies ganze Land, von dem ich geredet habe, euren Nachkommen zu ewigem Besitz geben.‹«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 14, 'Da ließ der HERR sich das Unheil leid sein, das er seinem Volk zugedacht hatte.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 15, 'Mose aber machte sich auf den Rückweg und stieg vom Berge hinab mit den beiden Gesetzestafeln in der Hand, Tafeln, die auf ihren beiden Seiten, vorn und hinten, beschrieben waren.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 16, 'Diese Tafeln waren von Gott selbst angefertigt, und die Schrift war Gottes Schrift, in die Tafeln eingegraben.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 17, 'Als nun Josua das laute Jubelgeschrei des Volkes hörte, sagte er zu Mose: »Kriegslärm ist im Lager!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 18, 'Der aber antwortete: »Das klingt nicht wie Geschrei von Siegern und auch nicht wie Geschrei von Besiegten: nein, lautes Singen höre ich!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 19, 'Als er sich dann dem Lager genähert hatte und das Stierbild und die Reigentänze sah, da geriet Mose in lodernden Zorn, so daß er die Tafeln aus seinen Händen schleuderte und sie am Fuß des Berges zertrümmerte.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 20, 'Dann nahm er das Stierbild, das sie angefertigt hatten, verbrannte es im Feuer und zerstieß es zu feinem Staub, den streute er aufs Wasser und ließ es die Israeliten trinken.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 21, 'Hierauf sagte Mose zu Aaron: »Was hat dir dieses Volk getan, daß du es zu einer so großen Sünde verführt hast?«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 22, 'Aaron antwortete: »Mein Herr möge nicht in Zorn geraten! Du weißt selbst, wie das Volk zum Bösen geneigt ist.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 23, 'Sie forderten mich auf: ›Mache uns einen Gott, der vor uns herziehen soll! Denn von diesem Mose, dem Mann, der uns aus dem Land Ägypten hergeführt hat, wissen wir nicht, was aus ihm geworden ist.‹');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 24, 'Da antwortete ich ihnen: ›Wer Goldschmuck hat, der reiße ihn von sich ab!‹ Sie gaben es mir dann, und ich warf es ins Feuer; da kam dieses Stierbild heraus.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 25, 'Als nun Mose sah, daß das Volk zügellos geworden war – denn Aaron hatte ihm die Zügel schießen lassen zur Schadenfreude für ihre Feinde –,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 26, 'trat Mose in das Tor des Lagers und rief aus: »Her zu mir, wer es mit dem HERRN hält!« Da scharten sich alle Leviten um ihn.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 27, 'Zu diesen sagte er: »So spricht der HERR, der Gott Israels: ›Gürtet euch ein jeder sein Schwert an die Hüfte, geht im Lager hin und her von einem Tor zum andern und erschlagt ein jeder den eigenen Bruder und ein jeder seine Freunde und Verwandten!‹«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 28, 'Die Leviten kamen dem Befehl Moses nach, und so fielen an diesem Tage von dem Volk gegen dreitausend Mann.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 29, 'Da sagte Mose: »Weiht euch heute dem HERRN zu Priestern! Denn ein jeder ist sogar gegen den eigenen Sohn und gegen den eigenen Bruder schonungslos vorgegangen; darum soll euch heute Segen verliehen werden!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 30, 'Am andern Tage aber sagte Mose zum Volk: »Ihr habt eine schwere Sünde begangen; darum will ich jetzt zum HERRN hinaufsteigen! Vielleicht kann ich euch Sühne für eure Sünde erwirken.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 31, 'So kehrte denn Mose zum HERRN zurück und sagte: »Ach bitte! Dieses Volk hat eine schwere Sünde begangen: es hat sich einen Gott aus Gold angefertigt!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 32, 'Und nun – vergib ihnen doch ihre Sünde! Wo nicht, so streiche lieber mich aus deinem Buche aus, das du geschrieben hast!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 33, 'Der HERR aber antwortete dem Mose: »Wer gegen mich gesündigt hat, nur den werde ich aus meinem Buche ausstreichen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 34, 'Jetzt aber gehe hin und führe das Volk dahin, wohin ich dir geboten habe! Jedoch nur mein Engel wird vor dir hergehen; und am Tage meines Strafgerichts will ich sie für ihre Versündigung büßen lassen!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 35, 'So suchte denn der HERR fortan das Volk heim (zur Strafe) dafür, daß sie das Stierbild hatten machen lassen, welches Aaron angefertigt hatte.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 33, 1, 'Hierauf sagte der HERR zu Mose: »Ziehe nunmehr weiter, hinweg von hier, du und das Volk, das du aus dem Land Ägypten hergeführt hast, in das Land, das ich Abraham, Isaak und Jakob zugeschworen habe mit den Worten: ›Deinen Nachkommen will ich es geben!‹');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 33, 2, 'Ich will aber einen Engel vor dir hersenden und die Kanaanäer, Amoriter, Hethiter, Pherissiter, Hewiter und Jebusiter vertreiben, – in ein Land, das von Milch und Honig überfließt.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 33, 3, 'Doch ich selbst will nicht in deiner Mitte hinaufziehen, weil du ein halsstarriges Volk bist; ich müßte dich sonst unterwegs vertilgen.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 33, 4, 'Als das Volk diese schlimme Botschaft vernahm, wurde es betrübt, und keiner legte seinen Schmuck an;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 33, 5, 'denn der HERR hatte zu Mose gesagt: »Sage den Israeliten: ›Ihr seid ein halsstarriges Volk; wenn ich auch nur einen Augenblick in deiner Mitte einherzöge, müßte ich dich vertilgen. So lege denn jetzt deinen Schmuck von dir ab, dann will ich sehen, was ich für dich tun kann!‹«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 33, 6, 'Da legten die Israeliten ihren Schmuck ab, vom Berge Horeb an.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 33, 7, 'Mose aber nahm jedesmal das Zelt und schlug es für sich außerhalb des Lagers in einiger Entfernung vom Lager auf und gab ihm den Namen ›Offenbarungszelt‹. Sooft nun jemand den HERRN befragen wollte, ging er zu dem Offenbarungszelt hinaus, das außerhalb des Lagers lag.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 33, 8, 'Sooft aber Mose zu dem Zelt hinausging, standen alle Leute auf und traten ein jeder in den Eingang seines Zeltes und blickten hinter Mose her, bis er in das Zelt eingetreten war.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 33, 9, 'Sobald dann Mose in das Zelt getreten war, senkte sich die Wolkensäule herab und nahm ihren Stand am Eingang des Zeltes, solange der HERR mit Mose redete.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 33, 10, 'Wenn nun das ganze Volk die Wolkensäule am Eingang des Zeltes stehen sah, erhob sich das ganze Volk, und jeder warf sich im Eingang seines Zeltes nieder.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 33, 11, 'Der HERR aber redete mit Mose von Angesicht zu Angesicht, wie jemand mit seinem Freunde redet. Mose kehrte dann wieder ins Lager zurück, während sein Diener Josua, der Sohn Nuns, ein junger Mann, das Innere des Zeltes nie verließ.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 33, 12, 'Hierauf sagte Mose zum HERRN: »Siehe, du hast mir wohl geboten, dieses Volk (nach Kanaan) hinaufzuführen, hast mich aber nicht wissen lassen, wen du mit mir senden willst; und doch hast du zu mir gesagt: ›Ich kenne dich mit Namen, und du hast auch Gnade bei mir gefunden!‹');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 33, 13, 'Wenn ich denn wirklich Gnade bei dir gefunden habe, so laß mich doch deine Pläne wissen, damit ich dich erkenne und damit ich (inne werde, daß ich) Gnade bei dir gefunden habe! Bedenke doch auch, daß dies Volk dein Volk ist!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 33, 14, 'Da antwortete der HERR: »Wenn ich in Person mitzöge, würde ich dir dadurch Beruhigung verschaffen?«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 33, 15, 'Da entgegnete ihm Mose: »Wenn du nicht in Person mitziehst, so laß uns lieber nicht von hier wegziehen!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 33, 16, 'Woran soll man denn sonst erkennen, daß ich samt deinem Volk Gnade bei dir gefunden habe? Doch eben daran, daß du mit uns ziehst und daß wir, ich und dein Volk, dadurch vor allen Völkern auf dem Erdboden ausgezeichnet werden.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 33, 17, 'Da antwortete der HERR dem Mose: »Auch diese Bitte, die du jetzt ausgesprochen, will ich dir erfüllen; denn du hast Gnade bei mir gefunden, und ich kenne dich mit Namen.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 33, 18, 'Als Mose nun bat: »Laß mich doch deine Herrlichkeit schauen!«,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 33, 19, 'antwortete der HERR: »Ich will all meine Schöne vor deinen Augen vorüberziehen lassen und will den Namen des HERRN laut vor dir ausrufen, nämlich daß ich Gnade erweise, wem ich eben gnädig bin, und Barmherzigkeit dem erzeige, dessen ich mich erbarmen will.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 33, 20, 'Dann fuhr er fort: »Mein Angesicht kannst du nicht schauen; denn kein Mensch, der mich schaut, bleibt am Leben.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 33, 21, 'Doch der HERR fuhr fort: »Siehe, es ist ein Platz neben mir: da magst du dich auf den Felsen stellen!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 33, 22, 'Wenn ich dann in meiner Herrlichkeit vorüberziehe, will ich dich in die Höhlung des Felsens stellen und meine Hand schirmend über dich halten, bis ich vorübergezogen bin.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 33, 23, 'Habe ich dann meine Hand zurückgezogen, so wirst du meine Rückseite schauen; mein Angesicht aber kann nicht geschaut werden.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 1, 'Darauf gebot der HERR dem Mose: »Haue dir zwei Steintafeln zurecht, wie die ersten waren, dann will ich auf die Tafeln die Worte schreiben, die auf den ersten Tafeln gestanden haben, die du zertrümmert hast!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 2, 'Halte dich für morgen bereit, gleich früh auf den Berg Sinai zu steigen und dort auf der Spitze des Berges vor mich zu treten!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 3, 'Es soll aber niemand mit dir heraufsteigen, und es darf sich auch niemand am ganzen Berge blicken lassen; sogar das Kleinvieh und die Rinder dürfen nicht gegen diesen Berg hin weiden!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 4, 'So hieb sich denn Mose zwei Steintafeln zurecht, wie die ersten gewesen waren, und machte sich dann am andern Morgen früh auf und stieg zum Berge Sinai hinauf, wie der HERR ihm geboten hatte; die beiden Steintafeln trug er in der Hand.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 5, 'Da fuhr der HERR im Gewölk hernieder, und er (Mose) trat dort neben ihn und rief den Namen des HERRN an.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 6, 'Da zog der HERR vor seinen Augen vorüber und rief aus: »Der HERR, der HERR ist ein barmherziger und gnädiger Gott, langmütig und reich an Gnade und Treue,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 7, 'der Gnade auf Tausende hin bewahrt, der Unrecht, Übertretung und Sünde vergibt, doch auch (den Schuldigen) keineswegs ungestraft läßt, sondern die Schuld der Väter an Kindern und Kindeskindern heimsucht, am dritten und am vierten Glied.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 8, 'Da verneigte sich Mose eilends bis zur Erde, warf sich nieder');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 9, 'und sagte: »Habe ich irgend Gnade bei dir, o Herr, gefunden, so wolle mein Herr doch in unserer Mitte einherziehen! Denn es ist ein halsstarriges Volk. Aber vergib uns unsere Schuld und Sünde und laß uns dein Eigentum sein!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 10, 'Da antwortete der HERR: »Wohlan, ich schließe einen Bund: vor deinem ganzen Volk will ich Wunder tun, wie sie auf der ganzen Erde und unter allen Völkern noch nie vollführt sind, und das ganze Volk, in dessen Mitte du lebst, soll das Walten des HERRN wahrnehmen; denn wunderbar soll das sein, was ich an dir tun werde.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 11, 'Beobachte wohl, was ich dir heute gebiete! Siehe, ich will vor dir die Amoriter, Kanaanäer, Hethiter, Pherissiter, Hewiter und Jebusiter vertreiben.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 12, 'Hüte dich wohl, mit den Bewohnern des Landes, in das du kommen wirst, einen Vertrag zu schließen, damit sie für dich nicht, wenn sie unter dir wohnen bleiben, ein Fallstrick werden!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 13, 'Ihr sollt vielmehr ihre Altäre niederreißen, ihre Malsteine zertrümmern und ihre Götzenbäume umhauen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 14, 'Denn du sollst keinen andern Gott anbeten! Denn der HERR heißt ›Eiferer‹ und ist ein eifersüchtiger Gott.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 15, 'Schließe daher ja keinen Vertrag mit den Bewohnern des Landes, damit du nicht, wenn sie ihren Götzendienst treiben und ihren Göttern opfern und sie dich dazu einladen, an ihren Opfermahlen teilnimmst.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 16, 'Du würdest dann auch von ihren Töchtern manche für deine Söhne zu Frauen nehmen, und diese würden, wenn sie ihren Götzendienst treiben, deine Söhne zu demselben Götzendienst verführen.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 17, '»Du sollst dir keine gegossenen Gottesbilder machen! –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 18, 'Das Fest der ungesäuerten Brote sollst du beobachten! Sieben Tage lang sollst du ungesäuertes Brot essen, wie ich dir geboten habe, zur bestimmten Zeit des Monats Abib; denn im Monat Abib bist du aus Ägypten ausgezogen. –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 19, 'Alle Erstgeburt gehört mir, auch von all deinem Vieh jede männliche Erstgeburt, der erste Wurf vom Rind- und Kleinvieh.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 20, 'Aber das Erstgeborene vom Esel sollst du entweder mit einem Lamm lösen oder, wenn du das nicht willst, ihm das Genick brechen. Jeden Erstgeborenen von deinen Söhnen sollst du lösen! Und man darf vor mir nicht mit leeren Händen erscheinen! –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 21, 'Sechs Tage lang sollst du arbeiten, aber am siebten Tage sollst du ruhen! Auch während der Zeit des Pflügens und der Ernte sollst du ruhen! –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 22, 'Auch das Wochenfest sollst du feiern, nämlich das Fest der Erstlinge der Weizenernte, sowie das Fest der Lese an der Wende des Jahres! –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 23, 'Dreimal im Jahr sollen alle deine männlichen Personen vor Gott dem HERRN, dem Gott Israels, erscheinen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 24, 'Denn ich werde die Heidenvölker vor dir austreiben und dein Gebiet weit ausdehnen; und niemand soll nach deinem Land Verlangen tragen, während du hinaufziehst, um dich vor dem HERRN, deinem Gott, sehen zu lassen dreimal im Jahr. –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 25, 'Du sollst das Blut meines Schlachtopfers nicht zusammen mit gesäuertem Brot darbringen! Und vom Opferfleisch des Passahfestes darf nichts über Nacht bis zum andern Morgen übrigbleiben! –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 26, 'Das Vorzüglichste von den Erstlingen deines Feldes sollst du in das Haus des HERRN, deines Gottes, bringen! – Du sollst kein Böckchen in der Milch seiner Mutter kochen!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 27, 'Weiter gebot der HERR dem Mose: »Schreibe dir diese Verordnungen auf! Denn auf Grund dieser Verordnungen habe ich mit dir und mit Israel einen Bund geschlossen.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 28, 'Hierauf verweilte Mose dort beim HERRN vierzig Tage und vierzig Nächte, ohne Brot zu essen und Wasser zu trinken; und er schrieb auf die Tafeln die Gebote des Bundes, die zehn Gebote.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 29, 'Als Mose dann vom Berge Sinai hinabstieg – die beiden Gesetzestafeln hatte er in der Hand, als er vom Berge hinabstieg –, da wußte Mose nicht, daß die Haut seines Angesichts infolge seiner Unterredung mit dem HERRN strahlend geworden war.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 30, 'Als nun Aaron und alle Israeliten Mose ansahen (und wahrnahmen), daß die Haut seines Angesichts strahlte, da fürchteten sie sich, ihm nahe zu kommen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 31, 'Als Mose sie aber herbeirief, wandten sich Aaron und alle Vorsteher der Gemeinde ihm wieder zu, und Mose redete mit ihnen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 32, 'Darauf traten auch alle Israeliten nahe an ihn heran, und er teilte ihnen alles mit, was der HERR ihm auf dem Berge Sinai aufgetragen hatte.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 33, 'Als er dann mit seinen Mitteilungen zu Ende war, legte er eine Hülle auf sein Angesicht.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 34, 'Sooft Mose nun vor den HERRN trat, um mit ihm zu reden, legte er die Hülle ab, bis er wieder hinausging; und wenn er hinausgekommen war, teilte er den Israeliten alles mit, was ihm geboten worden war.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 35, 'Dabei bekamen dann die Israeliten das Gesicht Moses zu sehen (und machten die Beobachtung), daß die Haut in seinem Gesicht strahlend geworden war; Mose aber legte dann die Hülle wieder auf sein Gesicht, bis er wieder hineinging, um mit dem HERRN zu reden.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 1, 'Hierauf versammelte Mose die ganze Gemeinde der Israeliten und sagte zu ihnen: »Dies ist es, was der HERR zu tun geboten hat:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 2, 'Sechs Tage lang soll gearbeitet werden; aber der siebte Tag soll euch heilig sein als ein Feiertag mit völliger Ruhe zu Ehren des HERRN! Wer an diesem Tage eine Arbeit verrichtet, soll den Tod erleiden!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 3, 'Am Sabbattage dürft ihr kein Feuer in allen euren Wohnungen anzünden!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 4, 'Weiter sagte Mose zu der ganzen Gemeinde der Israeliten: »Dies ist es, was der HERR geboten hat:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 5, 'Bringt von eurem Besitz eine Abgabe für den HERRN! Jeder, den sein Herz dazu treibt, möge die Abgabe für den HERRN herbringen: Gold, Silber und Kupfer,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 6, 'blauen und roten Purpur und Karmesin, Byssus und Ziegenhaar,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 7, 'rotgefärbte Widderfelle und Seekuhhäute, Akazienholz,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 8, 'Öl für den Leuchter, sowie Gewürzkräuter für das Salböl und für das wohlriechende Räucherwerk,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 9, 'Onyxsteine und andere Edelsteine zum Besatz für das Schulterkleid und für das Brustschild.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 10, 'Und alle, die kunstverständig unter euch sind, mögen kommen und alles herstellen, was der HERR geboten hat,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 11, 'nämlich die Wohnung mit ihrem Zelt und ihrer Überdachung, ihren Haken und Brettern, ihren Riegeln, Säulen und deren Füßen,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 12, 'die Lade mit ihren Tragstangen, die Deckplatte und den abschließenden Vorhang;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 13, 'den Tisch mit seinen Tragstangen und all seinen Geräten und den Schaubroten;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 14, 'den Leuchter zur Beleuchtung mit seinen Geräten und seinen Lampen und das Öl für den Leuchter;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 15, 'den Räucheraltar mit seinen Tragstangen, das Salböl und das wohlriechende Räucherwerk;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 16, 'den Türvorhang für den Eingang der Wohnung; den Brandopferaltar mit dem kupfernen Gitterwerk daran, samt seinen Tragstangen und all seinen Geräten; das Becken mit seinem Gestell;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 17, 'die Umhänge für den Vorhof samt den dazu gehörigen Säulen und deren Füßen sowie den Vorhang für das Tor am Vorhof;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 18, 'die Pflöcke der Wohnung und die Pflöcke des Vorhofs nebst den erforderlichen Stricken;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 19, '');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 20, 'Hierauf ging die ganze Gemeinde der Israeliten von Mose weg;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 21, 'dann aber kam ein jeder, den sein Herz dazu trieb, und jeder, der einen willigen Sinn besaß, brachte die Beisteuer für den HERRN zur Herstellung des Offenbarungszeltes und für den gesamten heiligen Dienst in ihm und für die heiligen Kleider;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 22, 'und zwar kamen sowohl die Männer als auch die Frauen, jeder, den sein Herz dazu trieb; sie brachten Spangen, Ohrringe, Fingerringe und Halsgeschmeide, goldene Schmucksachen aller Art; und jeder, der dem HERRN etwas von Gold als Weihgabe darzubringen beschlossen hatte, brachte es herbei;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 23, 'und jeder, in dessen Besitz sich blauer und roter Purpur und Karmesin, Byssus und Ziegenhaar, rotgefärbte Widderfelle und Seekuhhäute befanden, brachte sie herbei;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 24, 'jeder, der eine Beisteuer an Silber und Kupfer leisten wollte, brachte die Spende für den HERRN herbei; und jeder, in dessen Besitz sich Akazienholz zu irgendeiner Verwendung befand, brachte es herbei.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 25, 'Und alle Frauen, welche die erforderliche Geschicklichkeit besaßen, spannen eigenhändig und brachten das Gespinst herbei: blauen und roten Purpur, karmesinfarbige Garne und Byssus;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 26, 'und alle Frauen, die sich infolge ihrer Geschicklichkeit dazu getrieben fühlten, verspannen die Ziegenhaare.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 27, 'Die Stammfürsten aber brachten Onyxsteine und andere Edelsteine zum Besatz für das Schulterkleid und für das Brustschild,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 28, 'ferner die Gewürzkräuter und das Öl zur Beleuchtung und zum Salböl und zum wohlriechenden Räucherwerk.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 29, 'So brachten die Israeliten, alle Männer und Frauen, die sich dazu getrieben fühlten, zu dem ganzen Werk, dessen Ausführung der HERR durch Mose geboten hatte, etwas beizutragen, freiwillige Gaben für den HERRN dar.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 30, 'Hierauf sagte Mose zu den Israeliten: »Wisset wohl: der HERR hat Bezaleel, den Sohn Uris, den Enkel Hurs, vom Stamme Juda, namentlich berufen');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 31, 'und ihn mit göttlichem Geist erfüllt, mit Kunstsinn, Einsicht, Verstand und allerlei Fertigkeiten,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 32, 'nämlich um Kunstwerke zu ersinnen, Arbeiten in Gold, Silber und Kupfer auszuführen,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 33, 'Edelsteine zu schneiden, um Kunstwerke damit zu besetzen, Holz zu schnitzen, kurz Werke jeder Art kunstvoll herzustellen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 34, 'Aber auch die Gabe, andere zu unterweisen, hat er ihm verliehen, ihm und Oholiab, dem Sohn Ahisamachs, vom Stamme Dan.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 35, 'Er hat sie beide mit Kunstsinn reich ausgestattet, um alle Arten von Arbeiten auszuführen, wie sie die Künstler in festen Stoffen sowie die Kunstweber und Buntwirker in blauem und rotem Purpur, in Karmesin und Byssus schaffen und die (einfachen) Weber liefern, indem sie Arbeiten aller Art ausführen und Kunstwerke ersinnen!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 1, 'So werden denn Bezaleel und Oholiab und alle kunstverständigen Männer, denen der HERR Kunstsinn und Einsicht verliehen hat, so daß sie sich auf die Ausführung aller für das Heiligtum erforderlichen Arbeiten verstehen, alles nach den Anordnungen des HERRN ausführen.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 2, 'Hierauf berief Mose den Bezaleel und Oholiab und alle kunstverständigen Männer, denen der HERR Kunstsinn verliehen hatte, alle, die sich dazu getrieben fühlten, sich an der Ausführung des Werkes zu beteiligen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 3, 'Sie empfingen dann von Mose alle die Gaben, welche die Israeliten zur Ausführung der Arbeiten für das Heiligtum beigesteuert hatten; man brachte ihm aber an jedem Morgen immer noch freiwillige Geschenke.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 4, 'Da kamen alle Künstler, welche die ganze Arbeit für das Heiligtum auszuführen hatten, Mann für Mann, von der besonderen Arbeit, mit der sie beschäftigt waren,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 5, 'und sagten zu Mose: »Das Volk bringt viel mehr, als zur Verwendung für die Arbeiten, deren Ausführung der HERR geboten hat, erforderlich ist.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 6, 'Da ließ Mose durch Ausruf im Lager bekanntmachen: »Niemand, weder Mann noch Frau, möge fernerhin noch eine Arbeit als Beisteuer für das Heiligtum anfertigen!« Da mußte das Volk aufhören, noch weitere Spenden zu bringen;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 7, 'denn der gelieferte Vorrat reichte für die Ausführung aller Arbeiten aus, ja es blieb davon noch übrig.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 8, 'So stellten denn alle kunstverständigen Männer unter den Werkleuten die Wohnung aus zehn Teppichen her; aus gezwirntem Byssus, blauem und rotem Purpur und Karmesin, mit Cherubbildern in Kunstweberarbeit stellte er sie her.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 9, 'Die Länge jedes einzelnen Teppichs betrug achtundzwanzig Ellen und die Breite vier Ellen: alle Teppiche hatten dieselbe Größe.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 10, 'Je fünf Teppiche fügte er dann zu einem Stück zusammen, einen an den andern.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 11, 'Sodann brachte er Schleifen von blauem Purpur am Saum des äußersten Teppichs des einen zusammengesetzten Stückes an, und ebenso machte er es am Saum des äußersten Teppichs bei dem andern zusammengesetzten Stück.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 12, 'Fünfzig Schleifen brachte er an dem einen Teppich an und ebenso fünfzig Schleifen am Saum des Teppichs, der zu dem andern zusammengesetzten Stück gehörte, so daß die Schleifen einander genau gegenüberstanden.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 13, 'Sodann fertigte er fünfzig goldene Haken an und verband die Teppiche vermittels der Haken miteinander, so daß die Wohnung ein Ganzes bildete.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 14, 'Weiter fertigte er Teppiche aus Ziegenhaar zu einer Zeltdecke über der Wohnung an; elf Teppiche fertigte er dazu an.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 15, 'Die Länge jedes Teppichs betrug dreißig Ellen und die Breite vier Ellen: alle elf Teppiche hatten dieselbe Größe.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 16, 'Dann fügte er fünf von diesen Teppichen zu einem Stück für sich zusammen und ebenso die sechs anderen Teppiche für sich.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 17, 'Dann brachte er fünfzig Schleifen am Saum des äußersten Teppichs des einen zusammengesetzten Stückes an und ebenso fünfzig Schleifen am Saum des äußersten Teppichs des andern zusammengesetzten Stückes.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 18, 'Hierauf fertigte er fünfzig kupferne Haken an, um die Zeltdecke zusammenzufügen, so daß sie ein Ganzes bildete. –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 19, 'Sodann verfertigte er für das Zeltdach eine Schutzdecke von rotgefärbten Widderfellen und darüber noch eine andere Schutzdecke von Seekuhhäuten.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 20, 'Weiter fertigte er die Bretter für die Wohnung aus Akazienholz an, sie standen aufrecht;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 21, 'die Länge jedes Brettes betrug zehn Ellen und die Breite anderthalb Ellen;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 22, 'an jedem Brett saßen zwei Zapfen, einer dem andern gegenüber eingefügt; so machte er es an allen Brettern der Wohnung.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 23, 'Und zwar stellte er an Brettern für die Wohnung her: zwanzig Bretter für die Mittagsseite südwärts;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 24, 'und er brachte unter diesen zwanzig Brettern vierzig silberne Füße an, je zwei Füße unter jedem Brett für seine beiden Zapfen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 25, 'Ebenso fertigte er für die andere Seite der Wohnung, nämlich für die Nordseite, zwanzig Bretter an');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 26, 'und vierzig silberne Füße dazu, je zwei Füße unter jedem Brett.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 27, 'Aber für die Hinterseite der Wohnung, nach Westen zu, fertigte er sechs Bretter an,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 28, 'außerdem noch zwei Bretter für die Ecken der Wohnung an der Hinterseite.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 29, 'Diese waren unten und gleicherweise oben vollständig bis an den ersten Ring hin; so machte er es bei beiden für die beiden Ecken.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 30, 'Demnach waren es im ganzen acht Bretter, dazu ihre Füße von Silber: sechzehn Füße, immer zwei Füße unter jedem Brett.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 31, 'Sodann fertigte er Riegel aus Akazienholz an: fünf für die Bretter der einen Seitenwand der Wohnung');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 32, 'und fünf Riegel für die Bretter der andern Seitenwand der Wohnung und fünf Riegel für die Bretter an der Hinterseite der Wohnung gegen Westen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 33, 'Den mittleren Riegel aber machte er so, daß er in der Mitte der Bretter von einem Ende bis zum andern durchlief.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 34, 'Die Bretter aber überzog er mit Gold, und auch die dazugehörigen Ringe, die zur Aufnahme der Riegel dienten, stellte er aus Gold her und überzog die Riegel gleichfalls mit Gold.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 35, 'Weiter fertigte er den Vorhang aus blauem und rotem Purpur, aus Karmesin und gezwirntem Byssus an, und zwar in Kunstweberarbeit mit Cherubbildern.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 36, 'Dann fertigte er für ihn vier Säulen von Akazienholz an und überzog sie mit Gold; auch ihre Nägel waren von Gold; und er goß für sie vier silberne Füße. –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 37, 'Sodann fertigte er für den Eingang des Zeltes einen Vorhang von blauem und rotem Purpur, von Karmesin und gezwirntem Byssus in Buntwirkerarbeit;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 38, 'außerdem die dazugehörigen fünf Säulen und ihre Nägel. Ihre Köpfe und Ringbänder überzog er mit Gold; die fünf dazu gehörigen Füße aber waren von Kupfer.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 1, 'Weiter fertigte Bezaleel die Lade aus Akazienholz an, zweieinhalb Ellen lang, anderthalb Ellen breit und anderthalb Ellen hoch.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 2, 'Er überzog sie inwendig und auswendig mit feinem Gold und brachte an ihr einen goldenen Kranz ringsum an.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 3, 'Dann goß er für sie vier goldene Ringe und befestigte diese an ihren vier Ecken, und zwar zwei Ringe an ihrer einen Seite und zwei Ringe an ihrer andern Seite.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 4, 'Sodann fertigte er Tragstangen von Akazienholz an und überzog sie mit Gold;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 5, 'darauf steckte er die Stangen in die Ringe an den Seiten der Lade, so daß man die Lade tragen konnte. –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 6, 'Weiter fertigte er eine Deckplatte von feinem Gold an, zweieinhalb Ellen lang und anderthalb Ellen breit.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 7, 'Auch fertigte er zwei goldene Cherube an, und zwar in getriebener Arbeit, an den beiden Enden der Deckplatte;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 8, 'den einen Cherub brachte er am Ende der einen Seite und den andern Cherub am Ende der andern Seite an, und zwar mit der Deckplatte zu einem Stück verbunden, an ihren beiden Enden.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 9, 'Die Cherube breiteten ihre Flügel nach oben hin aus, so daß sie die Deckplatte mit ihren Flügeln überdeckten und ihre Gesichter einander zugekehrt waren; nach der Deckplatte hin waren die Gesichter der Cherube gerichtet.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 10, 'Sodann fertigte er den Tisch aus Akazienholz an, zwei Ellen lang, eine Elle breit und anderthalb Ellen hoch.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 11, 'Er überzog ihn mit feinem Gold und brachte einen goldenen Kranz ringsum an ihm an.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 12, 'Außerdem brachte er an ihm ringsum noch eine Einfassung an, die eine Handbreite hoch war, und an dieser Einfassung wieder einen goldenen Kranz ringsherum.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 13, 'Weiter goß er für ihn vier goldene Ringe und befestigte diese Ringe an den vier Ecken bei seinen vier Füßen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 14, 'Dicht an der Einfassung befanden sich die Ringe und dienten zur Aufnahme der Stangen, damit man den Tisch tragen konnte.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 15, 'Die Stangen aber verfertigte er aus Akazienholz und überzog sie mit Gold, damit man den Tisch tragen konnte.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 16, 'Weiter fertigte er die Geräte an, die auf dem Tische stehen sollten, nämlich die erforderlichen Schüsseln und Schalen, die Becher und Kannen, mit denen Trankopfer gespendet werden sollten, (alles) aus feinem Gold.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 17, 'Sodann fertigte er den Leuchter aus feinem Gold an; in getriebener Arbeit stellte er den Leuchter, seinen Fuß und seinen Schaft, her; seine Blumenkelche – Knäufe mit Blüten – waren aus einem Stück mit ihm gearbeitet.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 18, 'Sechs Arme gingen von seinen beiden Seiten aus, drei Arme auf jeder Seite des Leuchters.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 19, 'Drei mandelblütenförmige Blumenkelche – je ein Knauf mit einer Blüte – befanden sich an jedem Arm; so war es bei allen sechs Armen, die von dem Leuchter ausgingen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 20, 'Am Schaft selbst aber befanden sich vier mandelblütenförmige Blumenkelche – Knäufe mit Blüten –,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 21, 'und zwar befand sich an ihm immer ein Knauf unter jedem Paar der sechs Arme, die vom Schaft des Leuchters ausgingen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 22, 'Ihre Knäufe und Arme bestanden aus einem Stück mit ihm: der ganze Leuchter war eine einzige getriebene Arbeit aus feinem Gold.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 23, 'Sodann fertigte er auch die sieben Lampen für ihn an nebst den erforderlichen Lichtputzscheren und den Pfannen aus feinem Gold.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 24, 'Aus einem Talent feinen Goldes stellte er ihn nebst allen zugehörigen Geräten her.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 25, 'Weiter fertigte er den Räucheraltar aus Akazienholz an, eine Elle lang und eine Elle breit, viereckig, und zwei Ellen hoch; seine Hörner waren aus einem Stück mit ihm.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 26, 'Er überzog ihn, sowohl die Platte als auch die Wände ringsum, sowie die Hörner mit feinem Gold und brachte an ihm einen goldenen Kranz ringsherum an.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 27, 'Außerdem brachte er zwei goldene Ringe unterhalb seines Kranzes an den beiden Ecken auf jeder der beiden Seiten an, zur Aufnahme der Stangen, mittels derer man ihn tragen sollte.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 28, 'Die Stangen fertigte er aus Akazienholz an und überzog sie mit Gold.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 29, 'Dann bereitete er das heilige Salböl und das wohlriechende Räucherwerk aus reinen Gewürzkräutern, wie es der Salbenmischer herstellt.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 1, 'Hierauf fertigte er den Brandopferaltar aus Akazienholz an, fünf Ellen lang und fünf Ellen breit, viereckig und drei Ellen hoch.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 2, 'Die zu ihm gehörenden Hörner brachte er an seinen vier Ecken an; diese Hörner waren mit ihm aus einem Stück gearbeitet; und er überzog ihn mit Kupfer.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 3, 'Sodann verfertigte er alle für den Altar erforderlichen Geräte: die Töpfe und Schaufeln, die Becken, Gabeln und Pfannen; alle erforderlichen Geräte stellte er aus Kupfer her.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 4, 'Weiter verfertigte er für den Altar ein Gitterwerk, eine netzartige Arbeit aus Kupfer, und brachte es unterhalb seiner Einfassung von unten her bis zur halben Höhe (des Altars) an.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 5, 'Ferner goß er vier Ringe und setzte sie an die vier Ecken des kupfernen Gitterwerks zur Aufnahme der Stangen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 6, 'Die Stangen fertigte er aus Akazienholz und überzog sie mit Kupfer.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 7, 'Sodann steckte er die Stangen in die Ringe an den Seiten des Altars, damit man ihn mittels ihrer tragen könnte; aus Brettern stellte er ihn so her, daß er (inwendig) hohl war.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 8, 'Hierauf verfertigte er das Becken aus Kupfer und sein Gestell gleichfalls aus Kupfer [aus den Spiegeln der diensttuenden Frauen, die am Eingang des Offenbarungszeltes den Dienst versahen].');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 9, 'Sodann stellte er den Vorhof so her: auf der Mittagseite, nach Süden zu, die Umhänge für den Vorhof aus gezwirntem Byssus, hundert Ellen lang;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 10, 'dazu zwanzig Säulen nebst den zugehörigen zwanzig kupfernen Füßen; die Nägel der Säulen aber und die zugehörigen Ringbänder waren von Silber.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 11, 'Ebenso fertigte er für die Nordseite die Umhänge an, hundert Ellen lang; dazu zwanzig Säulen nebst den zugehörigen zwanzig kupfernen Füßen; die Nägel der Säulen aber und die zugehörigen Ringbänder waren von Silber.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 12, 'Ferner verfertigte er für die Westseite Umhänge von fünfzig Ellen; dazu zehn Säulen nebst den zugehörigen zehn Füßen; die Nägel der Säulen aber und die zugehörigen Ringbänder waren von Silber.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 13, 'Weiter für die Ostseite, gegen Morgen, Umhänge von fünfzig Ellen,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 14, 'nämlich fünfzehn Ellen Umhänge für die eine Seite mit ihren drei Säulen und deren drei Füßen,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 15, 'und ebenso für die andere Seite fünfzehn Ellen Umhänge; dazu drei Säulen nebst den zugehörigen drei Füßen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 16, 'Alle Umhänge des Vorhofes ringsum waren von gezwirntem Byssus;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 17, 'und die Füße der Säulen bestanden aus Kupfer, die Haken der Säulen aber und die zugehörigen Ringbänder aus Silber und der Überzug ihrer Köpfe gleichfalls aus Silber; es waren aber die Säulen des Vorhofes alle mit silbernen Ringbändern versehen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 18, 'Der Vorhang aber für den Eingang zum Vorhof war Buntwirkerarbeit von blauem und rotem Purpur, Karmesin und gezwirntem Byssus; und zwar betrug die Länge zwanzig Ellen, die Höhe, beziehungsweise die Breite, fünf Ellen, entsprechend den übrigen Umhängen des Vorhofs.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 19, 'Die zugehörigen vier Säulen aber nebst ihren vier Füßen waren von Kupfer, ihre Nägel von Silber und der Überzug ihrer Köpfe und ihre Ringbänder auch von Silber.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 20, 'Alle Pflöcke aber an der Wohnung und am Vorhof ringsum waren von Kupfer.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 21, 'Folgendes ist die Kostenberechnung für die Wohnung, nämlich für die Wohnung des Gesetzes, wie sie auf Befehl Moses durch die Dienstleistung der Leviten unter der Leitung des Priesters Ithamar, des Sohnes Aarons, aufgestellt worden ist.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 22, 'Bezaleel, der Sohn Uris, der Enkel Hurs, aus dem Stamm Juda, hatte alles angefertigt, was der HERR dem Mose geboten hatte;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 23, 'und mit ihm Oholiab, der Sohn Ahisamachs, aus dem Stamm Dan, ein Künstler in festen Stoffen sowie ein Kunstweber und Buntwirker in blauem und rotem Purpur, in Karmesin und Byssus.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 24, 'Was das gesamte Gold betrifft, das bei der Herstellung des Heiligtums für alle Arbeiten verbraucht worden ist, so betrug das freiwillig beigesteuerte Gold 29 Talente und 730 Schekel nach dem Gewicht des Heiligtums.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 25, 'Das Silber aber, das infolge der Musterung der Gemeinde eingegangen war, betrug 100 Talente und 1775 Schekel nach dem Gewicht des Heiligtums,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 26, 'je ein Beka auf den Kopf, die Hälfte eines Schekels, nach dem Gewicht des Heiligtums, von allen, die sich der Musterung unterzogen hatten, von zwanzig Jahren an und darüber, im ganzen von 603550 Mann.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 27, 'Es dienten aber die 100 Talente Silber zum Gießen der Füße des Heiligtums und der Füße des Vorhangs, 100 Talente für 100 Füße, also ein Talent für jeden Fuß.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 28, 'Aus den 1775 Schekeln aber fertigte (Bezaleel) die Nägel für die Säulen an und überzog damit ihre Köpfe und versah sie mit Ringbändern.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 29, 'Das freiwillig beigesteuerte Kupfer aber betrug 70 Talente und 2400 Schekel.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 30, 'Daraus verfertigte er die Füße (der Säulen) am Eingang des Offenbarungszeltes sowie den kupfernen Altar nebst seinem kupfernen Gitterwerk und alle Geräte des Altars,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 31, 'ferner die Füße des Vorhofs ringsum und die Füße (der Säulen) am Eingang des Vorhofs sowie alle Pflöcke der Wohnung und alle Pflöcke des Vorhofs ringsum.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 1, 'Aus dem blauen und roten Purpur aber und dem Karmesin verfertigten sie die Prachtkleider für den Dienst im Heiligtum, und zwar stellten sie die heiligen Kleidungsstücke für Aaron so her, wie der HERR dem Mose geboten hatte.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 2, 'Das Schulterkleid fertigten sie also aus Gold, blauem und rotem Purpur, Karmesin und gezwirntem Byssus an.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 3, 'Sie hämmerten nämlich das Gold zu breiten Blechen und zerschnitten sie dann in dünne Fäden, um diese mittels Kunstweberarbeit mit dem blauen und roten Purpur, dem Karmesin und dem Byssus zu verweben.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 4, 'Sie fertigten (zwei) zusammenfügbare Schulterstücke an, mittels derer das Kleid an seinen beiden (oberen) Enden zusammengefügt wurde.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 5, 'Die Binde aber, die sich an ihm befand und dazu diente, es fest anzulegen, war aus einem Stück mit ihm angefertigt und von gleicher Arbeit, nämlich aus Goldfäden, blauem und rotem Purpur, Karmesin und gezwirntem Byssus gearbeitet, wie der HERR dem Mose geboten hatte. –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 6, 'Sodann richteten sie die (beiden) Onyxsteine so zu, daß sie in ein Geflecht von Golddraht eingefaßt und mittels Siegelstecherkunst mit den (eingestochenen) Namen der Söhne Israels versehen waren.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 7, 'Diese setzte man auf die Schulterstücke des Schulterkleides als Steine des Gedenkens an die Israeliten, wie der HERR dem Mose geboten hatte.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 8, 'Hierauf fertigten sie das Brustschild in Kunstweberarbeit an, ganz so, wie das Schulterkleid gearbeitet war, nämlich aus Goldfäden, blauem und rotem Purpur, Karmesin und gezwirntem Byssus.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 9, 'Viereckig war es; doppelt gelegt fertigten sie das Brustschild an, eine Spanne lang und eine Spanne breit, doppelt gelegt.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 10, 'Sie besetzten es dann mit vier Reihen von Edelsteinen: ein Karneol, ein Topas und ein Smaragd bildeten die erste Reihe;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 11, 'die zweite Reihe bestand aus einem Rubin, einem Saphir und einem Jaspis;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 12, 'die dritte Reihe aus einem Hyazinth, einem Achat und einem Amethyst;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 13, 'die vierte Reihe aus einem Chrysolith, einem Soham und einem Onyx; in ein Geflecht von Gold gefaßt, bildeten sie den Besatz.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 14, 'Die Steine waren aber, entsprechend den Namen der Söhne Israels, nach deren Namen, zwölf (an Zahl); mittels Siegelstecherkunst waren sie, ein jeder mit seinem besonderen Namen, für die zwölf Stämme versehen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 15, 'Dann befestigten sie an dem Brustschilde schnurähnlich geflochtene Kettchen von feinem Gold.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 16, 'Weiter verfertigten sie zwei goldene Geflechte und zwei goldene Ringe und setzten die beiden Ringe an die beiden (oberen) Ecken des Brustschildes.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 17, 'Dann befestigten sie die beiden goldenen Schnüre an den beiden Ringen an den (oberen) Ecken des Brustschildes;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 18, 'die beiden anderen Enden der beiden Schnüre aber befestigten sie an den beiden Geflechten und (hefteten) diese wiederum an die beiden Schulterstücke des Schulterkleides auf dessen Vorderseite.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 19, 'Dann fertigten sie noch zwei goldene Ringe an und setzten sie an die beiden (unteren) Ecken des Brustschildes, und zwar an seinen (inneren) Saum, der dem Schulterkleide zugekehrt war.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 20, 'Dann fertigten sie noch zwei goldene Ringe an und setzten sie an die beiden Schulterstücke des Schulterkleides, unten auf seine Vorderseite, dicht bei der Stelle, wo das Schulterkleid zusammenging, oberhalb der Binde des Schulterkleides.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 21, 'Hierauf knüpften sie das Brustschild mit seinen Ringen vermittels einer Schnur von blauem Purpur an die Ringe des Schulterkleides an, so daß das Brustschild oberhalb der Binde des Schulterkleides fest anlag und sich nicht von seiner Stelle auf dem Schulterkleide verschieben konnte: so wie der HERR dem Mose geboten hatte.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 22, 'Sodann fertigten sie das zu dem Schulterkleid gehörige Obergewand in Weberarbeit an, ganz aus blauem Purpur.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 23, 'Die Halsöffnung des Obergewandes befand sich in seiner Mitte (und war) wie die Öffnung eines Panzers; einen Saum hatte die Halsöffnung ringsum, damit sie nicht einrisse.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 24, 'Hierauf brachten sie unten am Saum des Obergewandes Granatäpfel aus blauem und rotem Purpur, aus Karmesin und gezwirntem Byssus an.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 25, 'Weiter verfertigten sie Glöckchen aus feinem Gold und setzten diese Glöckchen zwischen die Granatäpfel an den Saum des Obergewandes ringsum zwischen die Granatäpfel,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 26, 'so daß immer auf ein Glöckchen ein Granatapfel am Saum des Obergewandes ringsum folgte, zur Verwendung beim heiligen Dienst, wie der HERR dem Mose geboten hatte.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 27, 'Dann fertigten sie die Unterkleider aus Byssus in Weberarbeit für Aaron und seine Söhne an,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 28, 'ferner den Kopfbund aus Byssus und die hohen Mützen aus Byssus und die leinenen Unterbeinkleider aus gezwirntem Byssus;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 29, 'endlich den Gürtel aus gezwirntem Byssus, aus blauem und rotem Purpur und Karmesin in Buntwirkerarbeit, wie der HERR dem Mose geboten hatte.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 30, 'Hierauf fertigten sie das Stirnblatt, das heilige Diadem, aus feinem Gold an und gruben auf ihm in Siegelstecherschrift die Worte ein: »Dem HERRN geweiht!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 31, 'Sie banden daran eine Schnur von blauem Purpur fest, um es oben am Kopfbund zu befestigen, wie der HERR dem Mose geboten hatte.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 32, 'So wurde die ganze Arbeit für die Wohnung des Offenbarungszeltes fertiggestellt: die Israeliten hatten alles genau so gemacht, wie der HERR dem Mose geboten hatte.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 33, 'So brachten sie denn alles zur Wohnung Gehörige zu Mose: das Zelt mit allen seinen Geräten, seinen Haken, Brettern, Riegeln, Säulen und Füßen;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 34, 'ferner die Schutzdecke von rotgefärbten Widderfellen, die Schutzdecke von Seekuhhäuten und den abschließenden (inneren) Vorhang;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 35, 'die Gesetzeslade mit ihren Tragstangen und der Deckplatte;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 36, 'den Tisch mit allen seinen Geräten und den Schaubroten;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 37, 'den Leuchter aus feinem Gold mit seinen in einer Reihe aufgesetzten Lampen und allen seinen Geräten sowie das Öl zur Beleuchtung;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 38, 'ferner den goldenen Altar, das Salböl, das wohlriechende Räucherwerk und den Vorhang für den Eingang zum Zelt;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 39, 'den kupfernen Altar mit dem zugehörigen kupfernen Gitterwerk, seinen Tragstangen und allen seinen Geräten; das Becken nebst seinem Gestell;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 40, 'die Umhänge des Vorhofs nebst seinen Säulen und Füßen; den Vorhang für den Eingang des Vorhofs nebst den zugehörigen Stricken und Pflöcken sowie alle Geräte für den Dienst in der Wohnung des Offenbarungszeltes;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 41, 'die heiligen Kleider für den Priester Aaron sowie die Kleider seiner Söhne für den priesterlichen Dienst.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 42, 'Genau so wie der HERR dem Mose geboten hatte, war die ganze Arbeit von den Israeliten ausgeführt worden. –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 43, 'Als Mose dann alles von ihnen Hergestellte besichtigt und sich überzeugt hatte, daß sie es genau nach den Anordnungen des HERRN ausgeführt hatten, dankte er ihnen unter Segenswünschen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 1, 'Hierauf gebot der HERR dem Mose folgendes:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 2, '»Am ersten Tage des ersten Monats sollst du die Wohnung des Offenbarungszeltes aufschlagen,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 3, 'die Lade mit dem Gesetz hineinstellen und den Vorhang vor der Lade aufhängen!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 4, 'Dann sollst du den Tisch hineinbringen, die erforderlichen (Schaubrotschichten) auf ihm zurechtlegen, auch den Leuchter hineinbringen und die zu ihm gehörigen Lampen aufsetzen!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 5, 'Dann stelle den goldenen Räucheraltar vor (den Vorhang vor der) Gesetzeslade und hänge den Vorhang am Eingang zur Wohnung auf!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 6, 'Hierauf stelle den Brandopferaltar vor dem Eingang zur Wohnung des Offenbarungszeltes auf');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 7, 'und setze das Becken zwischen das Offenbarungszelt und den Altar und tu Wasser hinein!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 8, 'Weiter laß den Vorhof ringsum aufrichten und den Vorhang am Eingang des Vorhofs anbringen!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 9, 'Dann nimm das Salböl und salbe die Wohnung nebst allem, was sich darin befindet: weihe sie dadurch samt allen ihren Geräten, damit sie heilig sei!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 10, 'Ebenso salbe den Brandopferaltar samt allen seinen Geräten und weihe so den Altar, damit er hochheilig sei!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 11, 'Auch das Becken samt seinem Gestell mußt du salben und es dadurch heiligen!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 12, 'Hierauf laß Aaron und seine Söhne an den Eingang des Offenbarungszeltes herantreten und laß sie eine Abwaschung mit Wasser an sich vornehmen!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 13, 'Sodann laß Aaron die heiligen Kleider anlegen und salbe ihn und weihe ihn so zur Ausübung des Priesterdienstes für mich!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 14, 'Ebenso laß seine Söhne herantreten und die Unterkleider anziehen;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 15, 'dann salbe sie, wie du ihren Vater gesalbt hast, damit sie mir als Priester dienen! Und diese Salbung soll ihnen das Priestertum für ewige Zeiten von Geschlecht zu Geschlecht verleihen!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 16, 'Da Mose alles genau nach den Anordnungen des HERRN ausführte,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 17, 'wurde die Wohnung im zweiten Jahr (nach dem Auszuge aus Ägypten), am ersten Tage des ersten Monats aufgeschlagen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 18, 'Als Mose damals die Wohnung aufrichten ließ, legte er ihre Füße fest, stellte die zugehörigen Bretter darauf, brachte ihre Riegel an und richtete ihre Säulen auf;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 19, 'dann breitete er das Zeltdach über der Wohnung aus und legte die Schutzdecke des Zeltes oben darüber, wie der HERR dem Mose geboten hatte.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 20, 'Dann nahm er die (beiden) Gesetzestafeln und legte sie in die Lade, steckte die Tragstangen an die Lade und legte die Deckplatte oben auf die Lade;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 21, 'alsdann brachte er die Lade in die Wohnung hinein und hängte den abschließenden Vorhang so auf, daß er die Lade mit dem Gesetz abschloß, wie der HERR dem Mose geboten hatte.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 22, 'Darauf stellte er den Tisch in das Offenbarungszelt an die Nordseite der Wohnung, außerhalb des Vorhangs,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 23, 'und legte auf ihm die Schichten der Schaubrote vor dem HERRN zurecht, wie der HERR dem Mose geboten hatte.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 24, 'Dann stellte er den Leuchter in das Offenbarungszelt dem Tisch gegenüber, an die Südseite der Wohnung,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 25, 'und setzte die Lampen vor dem HERRN auf, wie der HERR dem Mose geboten hatte.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 26, 'Darauf stellte er den goldenen Altar in das Offenbarungszelt vor den Vorhang');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 27, 'und verbrannte wohlriechendes Räucherwerk auf ihm, wie der HERR ihm geboten hatte.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 28, 'Dann hängte er den Vorhang für den Eingang der Wohnung auf,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 29, 'stellte den Brandopferaltar vor den Eingang der Wohnung des Offenbarungszeltes und brachte das Brandopfer und das Speisopfer auf ihm dar, wie der HERR ihm geboten hatte.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 30, 'Dann ließ er den Kessel zwischen dem Offenbarungszelt und dem Altar aufstellen und Wasser für die Waschungen hineintun,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 31, 'damit Mose und Aaron nebst dessen Söhnen sich die Hände und Füße daraus wuschen;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 32, 'sooft sie in das Offenbarungszelt hineingingen oder an den Altar herantraten, wuschen sie sich daraus, wie der HERR dem Mose geboten hatte.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 33, 'Schließlich richtete er den Vorhof rings um die Wohnung und um den Altar auf und brachte den Vorhang am Tor des Vorhofs an.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 34, 'Als Mose so das ganze Werk vollendet hatte, verhüllte die Wolke das Offenbarungszelt, und die Herrlichkeit des HERRN erfüllte die Wohnung,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 35, 'so daß Mose nicht in das Offenbarungszelt hineingehen konnte, weil die Wolke sich auf dasselbe niedergelassen hatte und die Herrlichkeit des HERRN die Wohnung erfüllte.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 36, 'Sooft sich nun die Wolke von der Wohnung erhob, brachen die Israeliten auf während der ganzen Dauer ihrer Wanderungen;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 37, 'wenn aber die Wolke sich nicht erhob, brachen sie nicht auf bis zu dem Tage, wo sie sich erhob.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 38, 'Denn bei Tage lag die Wolke des HERRN über der Wohnung; bei Nacht aber war sie, mit Feuerschein erfüllt, dem ganzen Hause Israel sichtbar während der ganzen Dauer ihrer Wanderzüge.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 1, 1, 'Der HERR berief hierauf Mose und gebot ihm aus dem Offenbarungszelte folgendes:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 1, 2, '»Rede zu den Israeliten und befiehl ihnen: Wenn jemand von euch dem HERRN eine Opfergabe darbringen will, so sollt ihr eure Opfergabe vom Vieh, und zwar von den Rindern und vom Kleinvieh, darbringen.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 1, 3, '»Wenn seine Opfergabe in einem Brandopfer bestehen soll, und zwar von einem Rind, so muß er ein fehlerloses männliches Tier opfern. Er bringe dieses an den Eingang des Offenbarungszeltes, damit es ihm das Wohlgefallen des HERRN verschaffe.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 1, 4, 'Dann lege er seine Hand fest auf den Kopf des Brandopfertieres, so wird es wohlgefällig aufgenommen werden und ihm Sühne verschaffen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 1, 5, 'Hierauf schlachte man das junge Rind vor dem HERRN; und die Priester, die Söhne Aarons, sollen das Blut herzubringen, und zwar so, daß sie das Blut ringsum an den Altar sprengen, der am Eingang des Offenbarungszeltes steht.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 1, 6, 'Dann soll man dem Brandopfertier die Haut abziehen und es in seine Stücke zerlegen;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 1, 7, 'die Söhne Aarons aber, die Priester, sollen Feuer auf den Altar tun und Holzstücke über dem Feuer aufschichten;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 1, 8, 'sodann sollen die Söhne Aarons, die Priester, die Stücke, auch den Kopf und das Fett, auf dem Holz, das auf dem Altar über dem Feuer liegt, gehörig zurechtlegen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 1, 9, 'Die Eingeweide und Beine des Tieres aber soll man mit Wasser waschen, und der Priester soll dann das Ganze auf dem Altar in Rauch aufgehen lassen: so ist es ein Brandopfer, ein Feueropfer zu lieblichem Geruch für den HERRN.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 1, 10, '»Wenn aber seine Opfergabe, die ein Brandopfer sein soll, in einem Stück Kleinvieh, einem Schaf oder einer Ziege, besteht, so muß es ein männliches, fehlerloses Tier sein, das er zum Opfer bringt.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 1, 11, 'Man schlachte dieses vor dem HERRN an der Nordseite des Altars; die Söhne Aarons aber, die Priester, sollen das Blut des Tieres ringsum an den Altar sprengen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 1, 12, 'Dann soll man es in seine Stücke zerlegen, und der Priester soll diese, und zwar auch den Kopf und das Fett, auf dem Holz, das auf dem Altar über dem Feuer liegt, gehörig zurechtlegen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 1, 13, 'Die Eingeweide und Beine aber soll man mit Wasser waschen, und der Priester soll dann das Ganze darbringen und es auf dem Altar in Rauch aufgehen lassen: so ist es ein Brandopfer, ein Feueropfer zu lieblichem Geruch für den HERRN.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 1, 14, '»Wenn aber seine Opfergabe für den HERRN, die ein Brandopfer sein soll, in Geflügel besteht, so müssen es Turteltauben oder junge Tauben sein, die er als Opfergabe darbringt.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 1, 15, 'Der Priester bringe das Tier an den Altar, knicke ihm den Kopf ab und lasse diesen auf dem Altar in Rauch aufgehen; das Blut aber lasse er an die Wand des Altars auslaufen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 1, 16, 'Darauf soll er den Kropf mit seinem Unrat entfernen und ihn neben den Altar gegen Osten auf die Aschenstelle werfen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 1, 17, 'Hierauf soll er dem Vogel die Flügel einreißen, jedoch ohne sie ganz abzutrennen, und der Priester soll ihn auf dem Altar, auf dem Holz, das über dem Feuer liegt, in Rauch aufgehen lassen: so ist es ein Brandopfer, ein Feueropfer zu lieblichem Geruch für den HERRN.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 2, 1, '»Wenn aber jemand dem HERRN ein Speisopfer als Opfergabe darbringen will, so muß seine Gabe aus Feinmehl bestehen, das er mit Öl übergießen und zu dem er Weihrauch hinzufügen muß.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 2, 2, 'Wenn er es dann den Söhnen Aarons, den Priestern, gebracht hat, soll der Priester eine Handvoll davon nehmen, nämlich von dem dargebrachten Feinmehl und Öl samt dem ganzen zugehörigen Weihrauch, und der Priester soll den zum Duftopfer bestimmten Teil auf dem Altar in Rauch aufgehen lassen: so ist es ein Feueropfer zu lieblichem Geruch für den HERRN.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 2, 3, 'Was dann von dem Speisopfer noch übrig ist, soll Aaron und seinen Söhnen gehören als etwas Hochheiliges von den Feueropfern des HERRN.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 2, 4, 'Willst du aber als Opfergabe eines Speisopfers etwas im Ofen Gebackenes darbringen, so muß es aus Feinmehl bereitet sein: ungesäuerte, mit Öl gemengte Kuchen oder ungesäuerte, mit Öl bestrichene Fladen. –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 2, 5, 'Soll aber deine Opfergabe in einem Speisopfer auf der Platte bestehen, so muß es aus ungesäuertem, mit Öl gemengtem Feinmehl bereitet sein.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 2, 6, 'Wenn du es dann in Stücke zerbrichst und Öl darübergießest, so ist es ein Speisopfer. –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 2, 7, 'Soll deine Opfergabe aber ein in der Pfanne bereitetes Speisopfer sein, so muß es aus Feinmehl mit Öl hergestellt sein.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 2, 8, '»Du sollst dann das Speisopfer, das aus diesen Zutaten bereitet ist, dem HERRN hinbringen, und zwar übergebe man es dem Priester, damit der es an den Altar trage.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 2, 9, 'Der Priester soll dann von dem Speisopfer den zum Duftopfer bestimmten Teil abheben und diesen auf dem Altar in Rauch aufgehen lassen: so ist es ein Feueropfer zu lieblichem Geruch für den HERRN.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 2, 10, 'Was dann von dem Speisopfer noch übrig ist, soll Aaron und seinen Söhnen gehören als etwas Hochheiliges von den Feueropfern des HERRN. –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 2, 11, 'Kein Speisopfer, das ihr dem HERRN darbringt, darf aus Gesäuertem hergestellt sein; denn aller Sauerteig und aller Honig – davon dürft ihr dem HERRN kein Feueropfer darbringen;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 2, 12, 'als Erstlingsgabe dürft ihr sie dem HERRN darbringen, aber auf den Altar dürfen sie nicht zum lieblichen Geruch kommen. –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 2, 13, 'Alle deine Gaben aber, die du als Speisopfer darbringst, mußt du gehörig salzen und darfst niemals das Salz des Bundes deines Gottes bei deinen Speisopfern fehlen lassen: zu all deinen Opfergaben mußt du auch Salz darbringen.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 2, 14, '»Willst du aber dem HERRN ein Speisopfer von den Erstlingsfrüchten darbringen, so mußt du am Feuer geröstete Ähren (oder) zerstoßene Körner von der frischen Frucht als Speisopfer von deinen Erstlingsfrüchten darbringen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 2, 15, 'Wenn du Öl daraufgießest und Weihrauch hinzufügst, so ist es ein Speisopfer.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 2, 16, 'Der Priester soll dann den zum Duftopfer bestimmten Teil von ihm – von seinen zerstoßenen Körnern und von seinem Öl – samt dem ganzen zugehörigen Weihrauch in Rauch aufgehen lassen: so ist es ein Feueropfer für den HERRN.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 3, 1, '»Soll aber seine Opfergabe ein Heilsopfer sein, so soll er, wenn er sie von den Rindern darbringen will, mag es ein männliches oder ein weibliches Tier sein, ein fehlerloses Tier vor den HERRN bringen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 3, 2, 'Dann lege er seine Hand fest auf den Kopf seines Opfertieres, und man schlachte es am Eingang des Offenbarungszeltes; die Söhne Aarons aber, die Priester, sollen das Blut ringsum an den Altar sprengen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 3, 3, 'Hierauf soll er von dem Heilsopfer dem HERRN ein Feueropfer darbringen, nämlich das Fett, das die Eingeweide bedeckt, und alles Fett, das an den Eingeweiden sitzt,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 3, 4, 'ferner die beiden Nieren samt dem Fett, das an ihnen, an den Lendenmuskeln sitzt, und den Lappen an der Leber – bei den Nieren soll er es ablösen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 3, 5, 'Wenn die Söhne Aarons es dann auf dem Altar über dem Brandopfer, das auf dem Holz über dem Feuer liegt, in Rauch aufgehen lassen, so ist es ein Feueropfer zu lieblichem Geruch für den HERRN.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 3, 6, '»Wenn aber seine Opfergabe, die er dem HERRN als Heilsopfer darbringen will, dem Kleinvieh entnommen ist, so muß es ein fehlerloses männliches oder weibliches Tier sein, das er opfert.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 3, 7, 'Bringt er ein Schaf als seine Opfergabe dar, so bringe er es vor den HERRN,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 3, 8, 'lege seine Hand fest auf den Kopf seines Opfertieres, und man schlachte es dann vor dem Offenbarungszelt; die Söhne Aarons aber sollen sein Blut ringsum an den Altar sprengen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 3, 9, 'Hierauf soll er dem HERRN von dem Heilsopfer ein Feueropfer darbringen, nämlich das Fett des Tieres: den ganzen Fettschwanz, den man dicht am Steißbein ablösen muß, ferner das Fett, das die Eingeweide bedeckt, und alles Fett, das an den Eingeweiden sitzt,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 3, 10, 'ferner die beiden Nieren samt dem Fett, das an ihnen, an den Lendenmuskeln sitzt, und den Lappen an der Leber – bei den Nieren soll man es ablösen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 3, 11, 'Wenn der Priester es dann auf dem Altar in Rauch aufgehen läßt, so ist es eine Feueropferspeise für den HERRN.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 3, 12, 'Wenn aber seine Opfergabe in einer Ziege besteht, so soll er sie vor den HERRN bringen,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 3, 13, 'dann seine Hand fest auf ihren Kopf legen, und man schlachte sie dann vor dem Offenbarungszelt; die Söhne Aarons aber sollen ihr Blut ringsum an den Altar sprengen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 3, 14, 'Hierauf soll er dem HERRN von ihr seine Gabe als Feueropfer darbringen, nämlich das Fett, das die Eingeweide bedeckt, und alles Fett, das an den Eingeweiden sitzt,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 3, 15, 'ferner die beiden Nieren samt dem Fett, das an ihnen, an den Lendenmuskeln sitzt, und den Lappen an der Leber – bei den Nieren soll man es ablösen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 3, 16, 'Wenn der Priester es dann auf dem Altar in Rauch aufgehen läßt, so ist es eine Feueropferspeise zu lieblichem Geruch für den HERRN. Alles Fett gehört dem HERRN.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 3, 17, 'Das ist eine ewiggültige Satzung für eure Geschlechter, wo ihr auch wohnen mögt: keinerlei Fett und keinerlei Blut dürft ihr genießen!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 1, 'Weiter gebot der HERR dem Mose folgendes:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 2, '»Rede zu den Israeliten und befiehl ihnen: Wenn jemand sich unvorsätzlich gegen irgendein Verbot des HERRN (über Dinge) vergeht, die nicht getan werden dürfen, und gegen irgendeins von ihnen verstößt (so sollen folgende Bestimmungen gelten).«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 3, '»Wenn sich der gesalbte Priester versündigt, so daß er eine Verschuldung über das Volk bringt, so soll er für sein Vergehen, das er begangen hat, dem HERRN einen fehlerlosen jungen Stier als Sündopfer darbringen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 4, 'Er hat also den Stier vor den HERRN an den Eingang des Offenbarungszeltes zu bringen, dann seine Hand fest auf den Kopf des Stieres zu legen und den Stier vor dem HERRN zu schlachten.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 5, 'Hierauf nehme der gesalbte Priester etwas von dem Blut des Stieres und bringe es in das Offenbarungszelt hinein.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 6, 'Dort tauche der Priester seinen Finger in das Blut und sprenge etwas von dem Blut siebenmal vor dem HERRN, nämlich vor den Vorhang des Heiligtums.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 7, 'Dann streiche der Priester etwas von dem Blut an die Hörner des für das wohlriechende Räucherwerk bestimmten Altars, der vor dem HERRN im Offenbarungszelt steht; alles übrige Blut des jungen Stieres aber schütte er an den Fuß des Brandopferaltars, der am Eingang des Offenbarungszeltes steht.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 8, 'Dann löse er alles Fett von dem Sündopferstier ab, nämlich das Fett, das die Eingeweide bedeckt, und alles Fett, das an den Eingeweiden sitzt,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 9, 'ferner die beiden Nieren samt dem Fett, das an ihnen, an den Lendenmuskeln sitzt, sowie den Lappen an der Leber – bei den Nieren soll er es ablösen –,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 10, 'so wie es von dem Stier bei einem Heilsopfer abgelöst wird; dann lasse der Priester (alle Fettstücke) auf dem Brandopferaltar in Rauch aufgehen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 11, 'Aber das Fell des Stieres und all sein Fleisch samt dem Kopf und den Beinen sowie seine Eingeweide und seinen Gedärmeinhalt,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 12, 'also das ganze Tier soll man an einen reinen Ort außerhalb des Lagers hinausschaffen, an den Platz, wohin man die Fettasche schüttet, und ihn dort auf Holzscheiten im Feuer verbrennen: an dem Ort, wohin man die Fettasche schüttet, soll er verbrannt werden.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 13, '»Wenn aber die ganze Gemeinde Israel sich unvorsätzlich verfehlt hat, ohne daß das Volk sich dessen bewußt gewesen ist, und sie gegen irgendein Verbot des HERRN verstoßen haben und dadurch in Verschuldung geraten sind,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 14, 'so soll die Gemeinde, sobald das Vergehen, dessen sie sich durch die Übertretung schuldig gemacht haben, erkannt worden ist, einen jungen Stier als Sündopfer darbringen und ihn vor das Offenbarungszelt führen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 15, 'Dort sollen die Ältesten der Gemeinde ihre Hände vor dem HERRN fest auf den Kopf des Stieres legen, und dann soll man den Stier vor dem HERRN schlachten.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 16, 'Hierauf bringe der gesalbte Priester etwas von dem Blut des Stieres in das Offenbarungszelt hinein,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 17, 'tauche dort seinen Finger in das Blut und sprenge etwas von dem Blut siebenmal vor dem HERRN, nämlich vor den Vorhang.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 18, 'Dann streiche er etwas von dem Blut an die Hörner des Altars, der vor dem HERRN im Offenbarungszelte steht; alles übrige Blut aber schütte er an den Fuß des Brandopferaltars, der am Eingang des Offenbarungszeltes steht.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 19, 'Dann soll er alles Fett von ihm ablösen und es auf dem Altar in Rauch aufgehen lassen');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 20, 'und hierauf mit dem Stiere so verfahren, wie er es mit dem eigenen Stier beim Sündopfer getan hat: genau so soll er auch mit ihm verfahren. Wenn der Priester ihnen so Sühne erwirkt hat, wird ihnen Vergebung zuteil werden.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 21, 'Den Stier aber soll man vor das Lager hinausschaffen und ihn dort so verbrennen, wie man den zuerst erwähnten Stier verbrannt hat. Dies ist das Sündopfer für die Gemeinde.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 22, '»Wenn ein Stammfürst sich versündigt und unvorsätzlich irgend etwas tut, wovon der HERR, sein Gott, geboten hat, daß man es nicht tun dürfe, und er dadurch in Verschuldung geraten ist,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 23, 'so soll er, sobald das Vergehen, dessen er sich schuldig gemacht hat, ihm bekannt geworden ist, einen fehlerlosen Ziegenbock als seine Opfergabe darbringen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 24, 'Er lege dabei seine Hand fest auf den Kopf des Bockes, und man schlachte ihn an dem Ort, wo man die Brandopfer vor dem HERRN schlachtet: so ist es ein Sündopfer.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 25, 'Alsdann soll der Priester mit seinem Finger etwas von dem Blut des Sündopfers nehmen und es an die Hörner des Brandopferaltars streichen, sein übriges Blut aber an den Fuß des Brandopferaltars schütten.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 26, 'Hierauf soll er das gesamte Fett des Tieres auf dem Altar in Rauch aufgehen lassen wie das Fett des Heilsopfers. Wenn der Priester ihm so Sühne wegen seiner Versündigung erwirkt hat, wird ihm Vergebung zuteil werden.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 27, '»Wenn sich aber jemand aus dem gemeinen Volk unvorsätzlich versündigt, indem er irgend etwas von dem tut, was nach den Geboten des HERRN nicht getan werden darf, und dadurch in Verschuldung geraten ist,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 28, 'so soll er, sobald das Vergehen, dessen er sich schuldig gemacht hat, ihm bekannt geworden ist, eine fehlerlose Ziege als Opfergabe für sein Vergehen bringen, das er sich hat zu Schulden kommen lassen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 29, 'Er lege dann seine Hand fest auf den Kopf des Sündopfers, und man schlachte das Sündopfer an dem für die Brandopfer bestimmten Ort.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 30, 'Darauf soll der Priester mit seinem Finger etwas von dem Blut nehmen und es an die Hörner des Brandopferaltars streichen, das gesamte übrige Blut des Tieres aber an den Fuß des Altars schütten.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 31, 'Hierauf soll man alles Fett des Tieres ablösen, wie das Fett von einem Heilsopfer abgelöst wird, und der Priester soll es auf dem Altar in Rauch aufgehen lassen zum lieblichen Geruch für den HERRN. Wenn der Priester ihm so Sühne erwirkt hat, wird ihm Vergebung zuteil werden. –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 32, 'Wenn er aber ein Schaf als seine Gabe zum Sündopfer bringen will, so muß es ein fehlerloses weibliches Tier sein, das er bringt.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 33, 'Er lege dann seine Hand fest auf den Kopf des Sündopfers, und man schlachte es als Sündopfer an dem Ort, wo man die Brandopfer schlachtet.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 34, 'Darauf soll der Priester mit seinem Finger etwas von dem Blut des Sündopfers nehmen und es an die Hörner des Brandopferaltars streichen, das gesamte übrige Blut aber an den Fuß des Altars schütten.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 35, 'Hierauf soll man alles Fett ablösen, wie das Fett des Schafes von einem Heilsopfer abgelöst wird, und der Priester soll es auf dem Altar, über den Feueropfern des HERRN, in Rauch aufgehen lassen. Wenn der Priester ihm so Sühne für das Vergehen, das er sich hat zu Schulden kommen lassen, erwirkt hat, wird ihm Vergebung zuteil werden.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 5, 1, '»Wenn jemand sich dadurch vergeht, daß er nach Anhörung der gerichtlichen Verfluchung (über einen Verbrecher), obgleich er als Zeuge auftreten könnte, weil er entweder die Tat gesehen oder die Sache sonst in Erfahrung gebracht hat, trotzdem keine Aussage macht und so in Verschuldung gerät; –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 5, 2, 'oder wenn jemand irgend etwas Unreines berührt, sei es das Aas eines unreinen wilden Tieres oder das Aas eines unreinen Haustieres oder das Aas eines unreinen Kriechtieres, ohne sich dessen (zunächst) bewußt zu sein, aber doch so, daß er unrein geworden ist und sich dessen bewußt wird; –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 5, 3, 'oder wenn er mit der Unreinigkeit eines Menschen in Berührung kommt, mit irgendeiner Unreinigkeit, durch die man sich verunreinigen kann, ohne daß er es (zunächst) weiß, nachher aber Kenntnis davon erhält und er sich schuldig fühlt; –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 5, 4, 'oder wenn jemand unbesonnen schwört, indem der Schwur seinen Lippen entfährt, daß er etwas Gutes oder Böses tun wolle, wie ja jemandem ein Schwur unbesonnenerweise entfahren mag, ohne daß er sich dessen (zunächst) bewußt ist, nachher aber zur Erkenntnis kommt und so in bezug auf irgend etwas Derartiges sich schuldig fühlt:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 5, 5, 'so soll er, wenn er durch irgend etwas Derartiges eine Schuld auf sich geladen hat, das Vergehen, dessen er sich schuldig gemacht hat, bekennen');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 5, 6, 'und dann dem HERRN als Buße für das Vergehen, das er sich hat zu Schulden kommen lassen, ein weibliches Stück Kleinvieh, ein Schaf oder eine Ziege, als Sündopfer darbringen; und der Priester soll ihm dadurch Sühne für sein Vergehen erwirken.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 5, 7, '»Wenn aber sein Vermögen zur Beschaffung eines Stückes Kleinvieh nicht ausreicht, so bringe er als seine Buße für das, wodurch er sich vergangen hat, dem HERRN zwei Turteltauben oder zwei junge Tauben dar, die eine zum Sündopfer, die andere zum Brandopfer.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 5, 8, 'Er bringe sie also zum Priester, und dieser soll die zum Sündopfer bestimmte zuerst darbringen, und zwar so, daß er ihr den Kopf dicht beim Genick abknickt, doch ohne ihn ganz abzutrennen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 5, 9, 'Dann soll er etwas von dem Blut des Sündopfers an die Wand des Altars sprengen, das übrige Blut aber an den Fuß des Altars ausdrücken: so ist es ein Sündopfer.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 5, 10, 'Die andere Taube aber soll er in der vorgeschriebenen Weise zum Brandopfer herrichten. Wenn der Priester ihm so Sühne für das Vergehen, das er sich hat zu Schulden kommen lassen, erwirkt hat, wird ihm Vergebung zuteil werden. –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 5, 11, 'Wenn aber sein Vermögen nicht einmal zur Beschaffung zweier Turteltauben oder zweier jungen Tauben ausreicht, so bringe er als seine Opfergabe für das, wodurch er sich vergangen hat, ein Zehntel Epha Feinmehl als Sündopfer dar, ohne jedoch Öl daraufzugießen oder Weihrauch hinzuzufügen; denn es ist ein Sündopfer.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 5, 12, 'Er bringe es also zum Priester, und der Priester nehme eine Handvoll davon als den zum Duftopfer bestimmten Teil und lasse es auf dem Altar über den Feueropfern des HERRN in Rauch aufgehen: so ist es ein Sündopfer.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 5, 13, 'Wenn der Priester ihm so für sein Vergehen, das er sich in irgendeinem der ebengenannten Fälle hat zu Schulden kommen lassen, Sühne erwirkt hat, wird ihm Vergebung zuteil werden. (Was dann von dem Sündopfer noch übrig ist) soll dem Priester gehören wie das (gewöhnliche) Speisopfer.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 5, 14, 'Weiter gebot der HERR dem Mose folgendes:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 5, 15, '»Wenn jemand eine Veruntreuung begeht, daß er sich unvorsätzlich an Dingen vergreift, die dem HERRN geheiligt sind, so soll er dem HERRN als sein Schuldopfer einen fehlerlosen Widder von seinem Kleinvieh, der nach deiner Schätzung mindestens zwei Schekel Silber nach dem Gewicht des Heiligtums wert ist, als Schuldopfer darbringen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 5, 16, 'Außerdem soll er den Betrag, um den er das Heiligtum freventlich geschädigt hat, erstatten und noch ein Fünftel des Betrags dazulegen und es dem Priester übergeben. Wenn der Priester ihm dann durch den als Schuldopfer dargebrachten Widder Sühne erwirkt hat, wird ihm Vergebung zuteil werden.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 5, 17, '»Wenn sich aber jemand vergeht, indem er unwissentlich irgend etwas tut, was man nach den Geboten des HERRN nicht tun darf, und er unbewußt in Schuld geraten ist und ein Unrecht auf sich geladen hat,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 5, 18, 'so soll er einen fehlerlosen Widder von seinem Kleinvieh nach deiner Schätzung als Schuldopfer zum Priester bringen. Wenn der Priester ihm dann für sein Vergehen, das er unwissentlich begangen hat, Sühne erwirkt hat, so wird ihm Vergebung zuteil werden.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 5, 19, 'Es ist ein Schuldopfer; er hat sich ja doch gegen den HERRN verschuldet.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 5, 20, 'Weiter gebot der HERR dem Mose folgendes:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 5, 21, '»Wenn jemand sich versündigt und sich eine Veruntreuung gegen den HERRN zu Schulden kommen läßt, indem er seinem Volksgenossen gegenüber etwas Anvertrautes oder Hinterlegtes oder Entwendetes ableugnet oder seinen Volksgenossen um etwas übervorteilt');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 5, 22, 'oder etwas Verlorenes gefunden hat und es verhehlt, oder wenn er falsch schwört in bezug auf irgendeine Handlung, durch die sich jemand versündigen kann –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 5, 23, 'wenn er sich also auf solche Weise vergangen hat und in Verschuldung geraten ist, so soll er das Entwendete, das er an sich gebracht, oder das Erpreßte, das er sich mit Unrecht angeeignet hat, oder das Anvertraute, das ihm in Verwahrung gegeben worden ist, oder das Verlorene, das er gefunden hat, zurückgeben');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 5, 24, 'oder alles, in bezug worauf er falsch geschworen hat, zurückerstatten, und zwar soll er es nach seinem vollen Wert erstatten und noch ein Fünftel des Betrags dazulegen: wem es zukommt, dem soll er es erstatten am Tage, an dem er sein Schuldopfer darbringt.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 5, 25, 'Als seine Buße für den HERRN aber soll er einen fehlerlosen Widder von seinem Kleinvieh nach deiner Schätzung als Schuldopfer zum Priester bringen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 5, 26, 'Wenn der Priester ihm dann Sühne vor dem HERRN erwirkt hat, wird ihm Vergebung zuteil werden für alle Handlungen, durch deren Begehung er sich eine Verschuldung zugezogen hat.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 1, 'Weiter gebot der HERR dem Mose folgendes:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 2, '»Gib Aaron und seinen Söhnen folgende Weisungen: Diese Vorschriften gelten für das Brandopfer: Dieses, das Brandopfer, soll auf dem Altar da, wo es angezündet worden ist, die ganze Nacht hindurch bis zum Morgen verbleiben, und das Altarfeuer soll dadurch brennend erhalten werden.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 3, 'Der Priester soll sein linnenes Gewand anziehen und sich die linnenen Beinkleider an den Leib legen und die Fettasche, in welche das Feuer das Brandopfer auf dem Altar verbrannt hat, wegräumen und sie neben den Altar schütten.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 4, 'Alsdann soll er seine (linnenen) Kleider ausziehen und andere (gewöhnliche) Kleider anlegen und die Asche an einen reinen Ort vor das Lager hinausschaffen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 5, 'Das Feuer aber auf dem Altar soll dadurch in Brand erhalten werden und darf nicht erlöschen: jeden Morgen soll der Priester Holzscheite auf dem Altar anzünden und das (Morgen-) Brandopfer auf ihm zurechtlegen und über ihm die Fettstücke der Heilsopfer in Rauch aufgehen lassen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 6, 'Ein beständiges Feuer soll auf dem Altar unterhalten werden; es darf nie erlöschen!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 7, '»Folgende Vorschriften aber gelten für das Speisopfer: Die Söhne Aarons sollen es vor den HERRN an die Vorderseite des Altars heranbringen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 8, 'Dann nehme er eine Handvoll davon, nämlich von dem Feinmehl des Speisopfers und von dessen Öl, dazu den gesamten Weihrauch, der auf dem Speisopfer liegt, und lasse es auf dem Altar in Rauch aufgehen als ein Feueropfer lieblichen Geruchs, als den Duftteil davon für den HERRN.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 9, 'Was dann (von dem Speisopfer) noch übrig ist, sollen Aaron und seine Söhne essen; ungesäuert soll es an heiliger Stätte verzehrt werden; im Vorhof des Offenbarungszeltes sollen sie es essen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 10, 'Es darf nicht mit Sauerteig gebacken werden; es ist ihr Anteil, den ich ihnen von meinen Feueropfern zugewiesen habe: hochheilig ist es wie das Sündopfer und wie das Schuldopfer.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 11, 'Alle männlichen Personen unter den Nachkommen Aarons dürfen es genießen; eine für ewige Zeiten festgesetzte Gebühr von den Feueropfern des HERRN soll es von Geschlecht zu Geschlecht sein. Jeder (Unbefugte), der diese Dinge berührt, soll dem Heiligtum verfallen sein.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 12, 'Weiter gebot der HERR dem Mose folgendes:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 13, '»Dies soll die Opfergabe Aarons und seiner Söhne sein, die sie dem HERRN darzubringen haben an dem Tage, an welchem er gesalbt wird: ein Zehntel Epha Feinmehl als regelmäßiges Speisopfer, die eine Hälfte davon am Morgen, die andere Hälfte am Abend.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 14, 'Auf einer Platte soll es mit Öl zubereitet werden; zusammengerührt sollst du es darbringen; zerbröckelt zu einem Brockenspeisopfer sollst du es darbringen als einen lieblichen Geruch für den HERRN.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 15, 'Auch der Priester, der an Aarons Statt aus der Zahl seiner Söhne gesalbt ist, soll es als eine auf ewige Zeiten festgesetzte Gebühr für den HERRN herrichten: als Ganzopfer soll es verbrannt werden;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 16, 'denn jedes Speisopfer eines Priesters soll ein Ganzopfer sein: es darf nichts davon gegessen werden.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 17, 'Weiter gebot der HERR dem Mose folgendes:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 18, '»Rede mit Aaron und seinen Söhnen und gebiete ihnen: Folgende Vorschriften gelten für das Sündopfer: An dem Orte, wo das Brandopfer geschlachtet wird, soll auch das Sündopfer vor dem HERRN geschlachtet werden: es ist hochheilig.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 19, 'Der Priester, der das Sündopfer darbringt, soll es verzehren; an heiliger Stätte soll es gegessen werden, nämlich im Vorhof des Offenbarungszeltes.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 20, 'Jeder (Unbefugte), der sein Fleisch berührt, soll dem Heiligtum verfallen sein; und wenn etwas von seinem Blut an ein Kleid spritzt, so mußt du das Kleidungsstück, an das es gespritzt ist, an heiliger Stätte waschen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 21, 'Ein irdenes Gefäß, in dem man es gekocht hat, muß zerbrochen werden; ist es aber in einem kupfernen Gefäß gekocht worden, so muß dieses gescheuert und mit Wasser ausgespült werden.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 22, 'Alle männlichen Personen der Priesterschaft dürfen davon essen: es ist hochheilig.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 23, 'Aber von allen Sündopfern, von deren Blut ein Teil in das Offenbarungszelt gebracht worden ist, (damit) im Heiligtum die Sühnung zu vollziehen, darf nichts gegessen werden, sondern sie sind im Feuer zu verbrennen.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 1, '»Folgende Vorschriften gelten für das Schuldopfer: es ist hochheilig.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 2, 'An dem Orte, wo man das Brandopfer schlachtet, soll man auch das Schuldopfer schlachten, und sein Blut soll man ringsum an den Altar sprengen;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 3, 'das gesamte Fett des Tieres aber soll man darbringen, nämlich den Fettschwanz und das Fett, das die Eingeweide bedeckt,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 4, 'ferner die beiden Nieren samt dem Fett, das an ihnen, an den Lendenmuskeln sitzt, und den Lappen an der Leber – bei den Nieren soll man es ablösen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 5, 'Dies alles soll der Priester dann auf dem Altar als ein Feueropfer für den HERRN in Rauch aufgehen lassen: so ist es ein Schuldopfer.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 6, 'Alle männlichen Personen der Priesterschaft dürfen davon essen; an heiliger Stätte muß es gegessen werden: es ist hochheilig.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 7, 'Wie mit dem Sündopfer, so soll auch mit dem Schuldopfer verfahren werden; dieselbe Bestimmung soll für beide gelten: es soll dem Priester gehören, der die Sühnung mit ihm vollzogen hat.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 8, 'Ebenso soll dem Priester, der jemandes Brandopfer darbringt, das Fell des Brandopfertieres gehören, das er dargebracht hat.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 9, 'Ebenso soll jedes Speisopfer, das im Ofen gebacken, sowie alles, was in der Pfanne oder auf der Platte zubereitet worden ist, dem Priester gehören, der es darbringt.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 10, 'Aber jedes Speisopfer, das mit Öl gemengt oder trocken ist, soll allen Söhnen Aarons gehören, dem einen wie dem andern.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 11, '»Folgende Vorschriften gelten für das Heilsopfer, das man dem HERRN darbringt:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 12, 'Wenn jemand es zum Zweck der Danksagung darbringt, so soll er außer dem Dank-Schlachtopfer noch ungesäuerte, mit Öl gemengte Kuchen und ungesäuerte, mit Öl bestrichene Fladen und mit Öl eingerührtes Feinmehl darbringen;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 13, 'nebst Kuchen von gesäuertem Brotteig soll er seine Opfergabe darbringen, außer dem Opfertier, in welchem sein Dank-Heilsopfer besteht.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 14, 'Und zwar soll er davon je ein Stück von jeder Opfergabe als Hebe für den HERRN darbringen; (was dann noch übrig ist) soll dem Priester gehören, der das Blut des Heilsopfers an den Altar gesprengt hat.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 15, 'Das Fleisch des Tieres aber, das als Dank-Heilsopfer geschlachtet wird, muß noch am Tage seiner Darbringung gegessen werden: man darf nichts davon bis zum nächsten Morgen übriglassen. –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 16, 'Wenn aber die Opfergabe eines Schlachttieres infolge eines Gelübdes dargebracht wird oder eine freiwillige Leistung ist, so soll zwar das Fleisch am Tage der Darbringung des Schlachtopfers gegessen werden; jedoch darf das, was etwa davon übriggeblieben ist, auch noch am folgenden Tage gegessen werden.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 17, 'Was aber dann noch vom Fleisch des Opfertieres am dritten Tage übrig ist, muß im Feuer verbrannt werden;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 18, 'denn wenn man vom Fleisch seines Heilsopfers noch am dritten Tage äße, so würde dies nicht gottwohlgefällig sein; es würde dem, der es dargebracht hat, nicht zugerechnet werden, sondern als Greuel gelten, und jeder, der davon äße, würde eine Verschuldung auf sich laden. –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 19, 'Auch solches Fleisch, das mit etwas Unreinem in Berührung gekommen ist, darf nicht gegessen werden, sondern ist im Feuer zu verbrennen. Was sonst aber das Opferfleisch betrifft, so darf jeder Reine es genießen;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 20, 'aber ein Mensch, der im Zustand der Unreinheit Fleisch von einem Heilsopfer genießt, das dem HERRN gehört, die Seele eines solchen Menschen soll aus seinen Volksgenossen ausgerottet werden.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 21, 'Wenn ferner jemand mit irgend etwas Unreinem in Berührung gekommen ist, sei es mit einem unreinen Menschen oder mit einem unreinen Haustier oder mit irgendeinem unreinen Gewürm, und trotzdem von dem Fleisch eines Heilsopfers ißt, das dem HERRN gehört, ein solcher Mensch soll aus seinen Volksgenossen ausgerottet werden.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 22, 'Weiter gebot der HERR dem Mose folgendes:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 23, '»Gib den Israeliten folgende Weisung: Keinerlei Fett von Rindern, Schafen und Ziegen dürft ihr genießen!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 24, 'Das Fett von verendeten oder zerrissenen Tieren darf zwar zu beliebigen Zwecken verwendet werden, aber genießen dürft ihr es nimmermehr;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 25, 'denn jeder, der Fett von den Haustieren genießt, von denen man dem HERRN Feueropfer darbringt, dessen Seele soll, weil er es genossen hat, aus seinen Volksgenossen ausgerottet werden.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 26, 'Ebenso dürft ihr, wo ihr auch wohnen mögt, kein Blut genießen, weder von Vögeln noch von vierfüßigen Tieren.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 27, 'Ein jeder, der irgendwelches Blut genießt, dessen Seele soll aus seinen Volksgenossen ausgerottet werden.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 28, 'Weiter gebot der HERR dem Mose:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 29, '»Gib den Israeliten folgende Weisungen: Wer dem HERRN ein Heilsopfer darbringt, soll dem HERRN von seinem Heilsopfer den gebührenden Anteil zukommen lassen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 30, 'Mit eigenen Händen soll er die zum Feueropfer für den HERRN bestimmten Stücke herbeibringen; nämlich das Fett samt der Brust soll er herbeibringen, und zwar die Brust, damit sie als Webeopfer vor dem HERRN gewebt werde.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 31, 'Das Fett soll der Priester dann auf dem Altar in Rauch aufgehen lassen, die Brust aber soll Aaron und seinen Söhnen gehören.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 32, 'Auch die rechte Keule sollt ihr als Hebe dem Priester von euren Heilsopfern geben.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 33, 'Wer von den Söhnen Aarons das Blut und das Fett der Heilsopfer darbringt, dem soll die rechte Keule als Anteil gehören.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 34, 'Denn die Webebrust und die Hebekeule habe ich von den Israeliten als meinen Anteil an ihren Heilsopfern genommen und habe sie dem Priester Aaron und seinen Söhnen als eine von seiten der Israeliten ewig zu leistende Gebühr überwiesen.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 35, 'Dies ist der Anteil Aarons und seiner Söhne an den Feueropfern des HERRN, der ihnen überwiesen worden ist an dem Tage, als der HERR sie zu sich herantreten ließ, damit sie ihm als Priester dienten.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 36, 'Diesen Anteil hat der HERR ihnen als eine von seiten der Israeliten zu leistende Gebühr an dem Tage, als er sie salbte, überwiesen; es ist eine ewige, für ihre Geschlechter verbindliche Gebühr.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 37, 'Dies sind die Vorschriften in betreff des Brandopfers, des Speisopfers, des Sündopfers, des Schuldopfers, des Einweihungsopfers und des Heilsopfers,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 38, 'wie sie der HERR dem Mose auf dem Berge Sinai geboten hat an dem Tage, als er den Israeliten gebot, ihre Opfergaben dem HERRN darzubringen, in der Wüste Sinai.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 1, 'Hierauf gebot der HERR dem Mose folgendes:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 2, '»Nimm Aaron und seine Söhne mit ihm, dazu die heiligen Kleider und das Salböl, ferner den jungen Stier zum Sündopfer, die beiden Widder sowie den Korb mit dem ungesäuerten Backwerk,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 3, 'und versammle die ganze Gemeinde am Eingang des Offenbarungszeltes!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 4, 'Mose tat, wie der HERR ihm geboten hatte; und als die Gemeinde sich am Eingang des Offenbarungszeltes versammelt hatte,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 5, 'sagte Mose zu der Gemeinde: »Dies ist es, was der HERR zu tun geboten hat.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 6, 'Hierauf ließ Mose Aaron mit seinen Söhnen herantreten und nahm eine Waschung mit Wasser an ihnen vor;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 7, 'dann ließ er ihn das Unterkleid anlegen, umgürtete ihn mit dem Gürtel, bekleidete ihn mit dem Obergewand, legte ihm das Schulterkleid darüber an, umgürtete ihn mit der Binde des Schulterkleides und legte es ihm vermittels dieser fest an.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 8, 'Dann befestigte er auf demselben das Brustschild und tat die heiligen Lose Urim und Thummim in das Brustschild hinein.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 9, 'Hierauf setzte er ihm den Kopfbund auf das Haupt und befestigte an der Vorderseite des Kopfbundes das goldene Stirnblatt, das heilige Diadem, wie der HERR dem Mose geboten hatte.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 10, 'Dann nahm Mose das Salböl, salbte die heilige Wohnung und alles, was sich in ihr befand, und heiligte sie so;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 11, 'auch sprengte er etwas davon siebenmal auf den Altar und salbte den Altar nebst allen seinen Geräten, auch das Becken samt seinem Gestell, um sie dadurch zu weihen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 12, 'Hierauf goß er dem Aaron etwas von dem Salböl auf das Haupt und salbte ihn, um ihn dadurch zu weihen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 13, 'Dann ließ Mose die Söhne Aarons herantreten, ließ sie die Unterkleider anziehen, umgürtete sie mit den Gürteln und setzte ihnen die hohen Mützen auf, wie der HERR dem Mose geboten hatte.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 14, 'Dann ließ er den jungen Stier zum Sündopfer heranführen, und Aaron und seine Söhne legten ihre Hände fest auf den Kopf des Sündopferstieres.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 15, 'Hierauf schlachtete man ihn, Mose nahm das Blut, strich etwas davon mit seinem Finger an die Hörner des Altars ringsum und entsündigte so den Altar; das (übrige) Blut aber goß er an den Fuß des Altars und heiligte ihn so, indem er die Sühngebräuche an ihm vollzog.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 16, 'Dann nahm man das ganze Fett, das an den Eingeweiden saß, sowie den Lappen an der Leber und die beiden Nieren samt dem Fett daran, und Mose ließ es auf dem Altar in Rauch aufgehen;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 17, 'den Stier aber samt seinem Fell, seinem Fleisch und dem Inhalt seiner Gedärme verbrannte man in einem Feuer außerhalb des Lagers, wie der HERR dem Mose geboten hatte.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 18, 'Dann ließ er den Widder zum Brandopfer herbeibringen, und Aaron und seine Söhne legten ihre Hände fest auf den Kopf des Widders.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 19, 'Dann schlachtete man ihn, und Mose sprengte das Blut ringsum an den Altar;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 20, 'den Widder aber zerlegte man in seine Stücke, und Mose ließ den Kopf sowie die Fleischstücke und das Fett in Rauch aufgehen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 21, 'Nachdem man dann die Eingeweide und die Beine mit Wasser abgewaschen hatte, ließ Mose den ganzen Widder auf dem Altar in Rauch aufgehen: so war es ein Brandopfer zu lieblichem Geruch, ein Feueropfer für den HERRN, wie der HERR dem Mose geboten hatte.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 22, 'Hierauf ließ er den zweiten Widder, den Einweihungswidder, herbeibringen, und Aaron und seine Söhne legten ihre Hände fest auf den Kopf des Widders.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 23, 'Dann schlachtete man ihn, und Mose nahm etwas von seinem Blut und strich es an das rechte Ohrläppchen Aarons sowie an den Daumen seiner rechten Hand und an die große Zehe seines rechten Fußes.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 24, 'Dann ließ Mose die Söhne Aarons herantreten und strich etwas von dem Blut an ihr rechtes Ohrläppchen sowie an ihren rechten Daumen und an die große Zehe ihres rechten Fußes; das (übrige) Blut aber sprengte Mose ringsum an den Altar.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 25, 'Hierauf nahm er das Fett, nämlich den Fettschwanz und alles Fett, das an den Eingeweiden saß, ferner den Lappen an der Leber, sowie die beiden Nieren samt ihrem Fett und die rechte Keule;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 26, 'weiter nahm er aus dem Korbe mit dem ungesäuerten Backwerk, der vor dem HERRN stand, einen ungesäuerten Kuchen sowie einen mit Öl zubereiteten Brotkuchen und einen Fladen, legte dies auf die Fettstücke und auf die rechte Keule,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 27, 'gab dann dies alles dem Aaron und seinen Söhnen in die Hände und ließ es als Webeopfer vor dem HERRN weben.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 28, 'Dann nahm Mose ihnen alles wieder aus den Händen zurück und ließ es auf dem Altar über dem Brandopfer in Rauch aufgehen; so war es ein Einweihungsopfer zu lieblichem Geruch, ein Feueropfer für den HERRN.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 29, 'Dann nahm Mose die Brust und webte sie als Webeopfer vor dem HERRN; von dem Einweihungswidder fiel sie dem Mose als Anteil zu, wie der HERR dem Mose geboten hatte.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 30, 'Hierauf nahm Mose etwas von dem Salböl und von dem Blut, das sich auf dem Altar befand, und besprengte damit Aaron und seine Kleider sowie dessen Söhne und deren Kleider und weihte so Aaron und seine Kleider sowie dessen Söhne mit ihm nebst deren Kleidern.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 31, 'Hierauf gebot Mose dem Aaron und dessen Söhnen: »Kocht das Fleisch am Eingang zum Offenbarungszelt und eßt es dort mitsamt dem Brot, das sich in dem zum Einweihungsopfer gehörigen Korb befindet, wie es mir geboten worden ist mit den Worten: ›Aaron und seine Söhne sollen es essen.‹');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 32, 'Was dann aber von dem Fleisch und dem Brot übrigbleibt, müßt ihr im Feuer verbrennen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 33, 'Auch dürft ihr sieben Tage lang nicht vom Eingang des Offenbarungszeltes weggehen bis zu dem Tage, an dem die für euer Einweihungsopfer festgesetzte Zeit abgelaufen ist; denn sieben Tage lang soll eure Einweihung dauern.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 34, 'Wie man heute verfahren ist, so soll man nach des HERRN Gebot (auch an den folgenden Tagen) tun, um Sühne für euch zu erwirken.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 35, 'Ihr müßt also sieben Tage lang Tag und Nacht am Eingang des Offenbarungszeltes bleiben und die Verordnungen des HERRN beobachten, damit ihr nicht sterbt; denn so ist mir geboten worden.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 36, 'So taten denn Aaron und seine Söhne alles, was der HERR durch Mose geboten hatte.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 9, 1, 'Am achten Tage aber berief Mose Aaron und dessen Söhne sowie die Ältesten der Israeliten');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 9, 2, 'und gebot dem Aaron: »Nimm dir ein junges Rind zum Sündopfer und einen Widder zum Brandopfer, beides fehlerlose Tiere, und bringe sie vor dem HERRN dar.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 9, 3, 'Den Israeliten aber gebiete folgendes: ›Nehmt einen Ziegenbock zum Sündopfer sowie ein Kalb und ein Schaf, beides einjährige, fehlerlose Tiere, zum Brandopfer;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 9, 4, 'ferner einen Stier und einen Widder zum Heilsopfer, um sie vor dem HERRN zu schlachten; dazu ein mit Öl gemengtes Speisopfer; denn heute wird der HERR euch erscheinen.‹«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 9, 5, 'Da brachten sie das, was Mose befohlen hatte, vor das Offenbarungszelt, und die ganze Gemeinde kam herbei und stellte sich vor dem HERRN auf.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 9, 6, 'Dann sagte Mose: »Dies ist es, was der HERR euch zu tun geboten hat, damit euch die Herrlichkeit des HERRN erscheine.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 9, 7, 'Hierauf sagte Mose zu Aaron: »Tritt an den Altar und bringe dein Sündopfer und dein Brandopfer dar, damit du für dich [und für das Volk] Sühne erwirkst; danach bringe die Opfergabe des Volkes dar, damit du auch für sie Sühne erwirkst, wie der HERR geboten hat.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 9, 8, 'Da trat Aaron an den Altar heran und schlachtete das Kalb, das zum Sündopfer für ihn selbst bestimmt war.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 9, 9, 'Hierauf reichten seine Söhne ihm das Blut dar, und er tauchte seinen Finger in das Blut und strich etwas davon an die Hörner des Altars; das (übrige) Blut aber goß er an den Fuß des Altars.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 9, 10, 'Dann ließ er das Fett sowie die Nieren und den Lappen an der Leber von dem Sündopfertier auf dem Altar in Rauch aufgehen, wie der HERR dem Mose geboten hatte;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 9, 11, 'das Fleisch aber und das Fell verbrannte man in einem Feuer außerhalb des Lagers.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 9, 12, 'Hierauf schlachtete er das Brandopfertier, und seine Söhne reichten ihm das Blut, das er ringsum an den Altar sprengte.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 9, 13, 'Dann reichten sie ihm das in Stücke zerlegte Brandopfer samt dem Kopf, und er ließ es auf dem Altar in Rauch aufgehen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 9, 14, 'Nachdem er dann die Eingeweide und die Beine gewaschen hatte, ließ er sie auf dem Altar über dem Brandopfer in Rauch aufgehen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 9, 15, 'Hierauf brachte er die Opfergabe des Volkes dar: er nahm den Bock, der zum Sündopfer für das Volk bestimmt war, schlachtete ihn und brachte ihn als Sündopfer dar wie das vorige Sündopfer.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 9, 16, 'Dann brachte er das Brandopfer dar und verfuhr dabei auf die vorgeschriebene Weise.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 9, 17, 'Weiter brachte er das Speisopfer dar, nahm von demselben eine Handvoll und ließ es auf dem Altar in Rauch aufgehen, [außer dem Morgenbrandopfer].');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 9, 18, 'Endlich schlachtete er das Rind und den Widder als Heilsopfer für das Volk; seine Söhne reichten ihm dabei das Blut, das er ringsum an den Altar sprengte.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 9, 19, 'Die Fettstücke von dem Rind aber, ferner von dem Widder den Fettschwanz und das die Eingeweide bedeckende Fett nebst den Nieren und dem Lappen an der Leber –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 9, 20, 'diese Fettstücke legten sie auf die Bruststücke, und er ließ dann die Fettstücke auf dem Altar in Rauch aufgehen;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 9, 21, 'die Bruststücke aber und die rechte Keule webte Aaron als Webeopfer vor dem HERRN, wie Mose geboten hatte.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 9, 22, 'Hierauf erhob Aaron seine Hände gegen das Volk hin und segnete es; dann stieg er (vom Altar) herab, nachdem er das Sündopfer, das Brandopfer und das Heilsopfer dargebracht hatte.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 9, 23, 'Dann begaben sich Mose und Aaron in das Offenbarungszelt hinein, und als sie wieder herausgetreten waren, segneten sie das Volk. Da erschien die Herrlichkeit des HERRN dem ganzen Volk:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 9, 24, 'Feuer ging von dem HERRN aus und verzehrte das Brandopfer und die Fettstücke auf dem Altar. Als das ganze Volk dies sah, jubelten sie und warfen sich auf ihr Angesicht nieder.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 10, 1, 'Die Söhne Aarons aber, Nadab und Abihu, nahmen beide ihre Räucherpfannen, taten glühende Kohlen hinein, legten Räucherwerk darauf und brachten so dem HERRN ein ungehöriges Feueropfer dar, das er ihnen nicht geboten hatte.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 10, 2, 'Da ging Feuer vom HERRN aus und verzehrte sie, so daß sie vor dem HERRN starben.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 10, 3, 'Da sagte Mose zu Aaron: »Hier trifft das ein, was der HERR angekündigt hat mit den Worten: ›An denen, die mir nahestehen, will ich mich als den Heiligen erweisen und vor dem ganzen Volk meine Herrlichkeit offenbaren.‹« Aaron aber sagte kein Wort.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 10, 4, 'Darauf rief Mose den Misael und den Elzaphan, die Söhne Ussiels, des Oheims Aarons, herbei und befahl ihnen: »Tretet herzu und tragt eure Verwandten aus dem Heiligtum hinweg vor das Lager hinaus!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 10, 5, 'Da traten sie herzu und trugen sie in ihren (leinenen) Unterkleidern weg vor das Lager hinaus, wie Mose ihnen befohlen hatte.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 10, 6, 'Darauf sagte Mose zu Aaron und dessen Söhnen Eleasar und Ithamar: »Ihr dürft euer Haupthaar nicht auflösen und eure Kleider nicht zerreißen; sonst müßtet ihr sterben, und der HERR würde der ganzen Gemeinde zürnen. Doch eure Volksgenossen, das ganze Haus Israel, mögen über den Brand weinen, den der HERR angerichtet hat.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 10, 7, 'Auch dürft ihr euch nicht vom Eingang des Offenbarungszeltes entfernen, damit ihr nicht sterbt; denn das Salböl des HERRN ist auf euch (gekommen).« So taten sie denn nach der Weisung Moses.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 10, 8, 'Hierauf gebot der HERR dem Aaron folgendes:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 10, 9, '»Wein und berauschendes Getränk dürft ihr, du und deine Söhne mit dir, nicht trinken, wenn ihr in das Offenbarungszelt eintretet, damit ihr nicht sterbt – das ist eine ewiggültige Verordnung für alle eure Geschlechter –:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 10, 10, '(ihr sollt lernen,) einen Unterschied zwischen dem Heiligen und Unheiligen, zwischen dem Reinen und Unreinen zu machen,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 10, 11, 'und sollt die Israeliten in allen Satzungen unterweisen, die der HERR euch durch den Mund Moses verkündigt hat.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 10, 12, 'Hierauf gebot Mose dem Aaron und dessen Söhnen Eleasar und Ithamar, die ihm noch übriggeblieben waren: »Nehmt das Speisopfer, das von den Feueropfern des HERRN noch übrig ist, und eßt es ungesäuert neben dem Altar; denn es ist hochheilig.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 10, 13, 'Und zwar müßt ihr es an heiliger Stätte verzehren, denn es ist der für dich und deine Söhne bestimmte Anteil von den Feueropfern des HERRN – so ist mir geboten worden.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 10, 14, 'Die Webebrust aber und die Hebekeule sollt ihr, du und deine Söhne und deine Töchter mit dir, an einer reinen Stätte essen; denn als der für dich und deine Söhne bestimmte Anteil von den Heilsopfern der Israeliten sind sie euch überwiesen worden.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 10, 15, 'Die Hebekeule und die Webebrust soll man mitsamt den zu Feueropfern bestimmten Fettstücken herbringen, um sie als Webeopfer vor dem HERRN zu weben; dann sollen sie dir und deinen Söhnen mit dir als eine für ewige Zeiten festgesetzte Gebühr zufallen, wie der HERR geboten hat.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 10, 16, 'Als Mose dann aber eifrig nach dem Sündopferbock suchte, stellte es sich heraus, daß er verbrannt worden war! Da geriet er über Eleasar und Ithamar, die übriggebliebenen Söhne Aarons, in heftigen Zorn und fragte:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 10, 17, '»Warum habt ihr das Sündopferfleisch nicht an heiliger Stätte gegessen? Es ist ja doch hochheilig, und der HERR hat es euch gegeben, damit ihr die Schuld der Gemeinde wegschafft, indem ihr ihnen Sühne vor dem HERRN erwirkt.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 10, 18, 'Bedenkt doch! Das Blut davon ist nicht ins Innere des Heiligtums gebracht worden; darum hättet ihr es unbedingt im heiligen Bezirk essen müssen, wie ich geboten habe!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 10, 19, 'Da antwortete Aaron dem Mose: »Bedenke doch: heute haben (meine Söhne) ihr Sündopfer und ihr Brandopfer vor dem HERRN dargebracht, und mich hat trotzdem solches Geschick betroffen! Wenn ich nun heute Sündopferfleisch genossen hätte, würde das dem HERRN wohlgefällig gewesen sein?«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 10, 20, 'Als Mose das hörte, erkannte er es als begründet an.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 1, 'Hierauf gebot der HERR dem Mose und Aaron folgendes:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 2, '»Teilt den Israeliten folgende Verordnung mit: Dies sind die Tiere, die ihr von allen Vierfüßlern auf der Erde essen dürft:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 3, 'Alles, was unter den Vierfüßlern gespaltene Klauen hat, und zwar ganz durchgespaltene Klauen, und was zugleich wiederkäut, das dürft ihr essen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 4, 'Nur folgende Tiere dürft ihr von den Wiederkäuern und von denen, die gespaltene Klauen haben, nicht essen: das Kamel, denn es ist zwar ein Wiederkäuer, hat aber keine durchgespaltenen Klauen: als unrein soll es euch gelten; –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 5, 'ferner den Klippdachs; denn er ist zwar ein Wiederkäuer, hat aber keine gespaltenen Klauen: als unrein soll er euch gelten; –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 6, 'ferner den Hasen; denn er ist zwar ein Wiederkäuer, hat aber keine gespaltenen Klauen: als unrein soll er euch gelten; –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 7, 'ferner das Schwein; denn es hat zwar gespaltene Klauen und sogar ganz durchgespaltene Klauen, ist aber kein Wiederkäuer: als unrein soll es euch gelten.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 8, 'Vom Fleisch dieser Tiere dürft ihr nicht essen und ihren toten Körper nicht berühren: als unrein sollen sie euch gelten.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 9, 'Folgende Tiere dürft ihr von allen im Wasser lebenden Tieren essen: Alles, was Flossen und Schuppen hat im Wasser, in den Meeren und in den Flüssen, das dürft ihr essen;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 10, 'alles aber, was in den Meeren und Flüssen keine Flossen und Schuppen hat unter allen Geschöpfen, von denen das Wasser wimmelt, und unter allen lebenden Wesen, die sich im Wasser befinden, die sollen euch ein Greuel sein,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 11, 'ja ein Greuel sollen sie euch sein: von ihrem Fleisch dürft ihr nichts genießen, und vor ihren toten Körpern sollt ihr einen Abscheu haben.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 12, 'Alle Wassertiere, die keine Flossen und Schuppen haben, sollen euch ein Greuel sein.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 13, 'Von den Vögeln aber sollt ihr folgende verabscheuen, die nicht gegessen werden dürfen, sondern ein Greuel sind: den Adler, den Bartgeier, den Lämmergeier,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 14, 'die Weihe, alle Falkenarten,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 15, 'alle Arten der Raben,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 16, 'den Strauß, die Schwalbe, die Möwe, alle Arten Habichte,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 17, 'das Käuzchen, den Sturzpelikan, den Uhu,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 18, 'die Eule, den Pelikan, den Erdgeier,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 19, 'den Storch und alle Reiherarten, den Wiedehopf und die Fledermaus.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 20, 'Alle kleinen geflügelten Tiere [die auf vier Beinen gehen,] sollen euch ein Greuel sein.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 21, 'Nur diejenigen von allen geflügelten kleinen Tieren dürft ihr essen, die auf vier Beinen gehen und oberhalb ihrer vier Beine noch ein Paar Springbeine haben, um mit ihnen auf der Erde zu hüpfen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 22, 'Von diesen dürft ihr die folgenden essen: alle Arten der Zugheuschrecke, alle Arten der Solhamheuschrecke, alle Arten der Hargolheuschrecke und alle Arten der Hagabheuschrecke.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 23, 'Aber alle übrigen geflügelten kleinen Tiere [die vier Beine haben,] sollen euch ein Greuel sein.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 24, '»Durch folgende Tiere also verunreinigt ihr euch – jeder, der ihre toten Körper berührt, ist bis zum Abend unrein,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 25, 'und jeder, der etwas von ihrem toten Körper trägt, muß seine Kleider waschen und ist bis zum Abend unrein –:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 26, 'ihr werdet also unrein durch alle Tiere, die zwar gespaltene, aber nicht ganz durchgespaltene Klauen haben und keine Wiederkäuer sind: sie sollen euch als unrein gelten; wer sie berührt, wird dadurch unrein.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 27, 'Auch alle vierfüßigen Tiere, die auf Tatzen gehen, sollen euch als unrein gelten; wer ihre toten Körper berührt, ist bis zum Abend unrein,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 28, 'und wer ihre toten Körper trägt, muß seine Kleider waschen und ist bis zum Abend unrein; sie sollen euch als unrein gelten.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 29, 'Weiter sollen folgende Tiere euch unter den kleinen Tieren, von denen die Erde wimmelt, als unrein gelten: das Wiesel, die Maus, alle Arten Eidechsen, nämlich');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 30, 'der Mauergecko, der Dornschwanz, der Schleuderschwanz, der Salamander und das Chamäleon.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 31, 'Diese sollen euch unter allen kleinen Tieren als unrein gelten; wer sie berührt, wenn sie tot sind, ist bis zum Abend unrein.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 32, 'Auch jeder Gegenstand, auf den eins von ihnen, wenn sie tot sind, gefallen ist, wird unrein: jedes Holzgerät oder Kleidungsstück oder Fell oder Sack, jedes Gerät, mit dem irgendeine Arbeit verrichtet wird, muß ins Wasser getan werden und ist bis zum Abend unrein; dann wird es wieder rein.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 33, 'Auch jedes irdene Geschirr, in das eins von ihnen hineinfällt, wird samt seinem ganzen Inhalt unrein, und ihr müßt es zerschlagen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 34, 'Jede Speise, die gegessen zu werden pflegt und an die solches Wasser kommt, wird unrein; und jede Flüssigkeit, die man zu trinken pflegt, wird in jedem (derartigen) Gefäß unrein.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 35, 'Auch alles, worauf eins von solchen toten Tieren fällt, wird unrein; ein Backofen oder Kochherd muß eingerissen werden: sie sind unrein und sollen euch als unrein gelten;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 36, 'nur Quellen und Zisternen, also Wasseransammlungen, bleiben rein; wer aber das hineingefallene tote Tier berührt, wird unrein.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 37, 'Wenn ferner eins von solchen toten Tieren auf irgendwelche Sämereien fällt, die gesät werden sollen, so bleiben diese rein;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 38, 'wenn aber Wasser auf die Sämereien gegossen worden ist und dann eins von solchen toten Tieren darauffällt, so sollen sie euch als unrein gelten.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 39, 'Wenn ferner ein Stück von den Haustieren stirbt, deren Fleisch ihr essen dürft, so wird der, welcher das tote Tier berührt, bis zum Abend unrein;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 40, 'wer aber etwas von einem solchen toten Tiere genießt, muß seine Kleider waschen und ist bis zum Abend unrein; ebenso muß der, welcher solch ein totes Tier trägt, seine Kleider waschen und ist bis zum Abend unrein.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 41, '»Alle kleinen Kriechtiere ferner, von denen die Erde wimmelt, sind ein Greuel: sie dürfen nicht gegessen werden.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 42, 'Alles, was auf dem Bauche kriecht, und alles, was sich auf vier Füßen bewegt, auch alle vielfüßigen Tiere, überhaupt alle kleinen Kriechtiere, die auf der Erde wimmeln, dürft ihr nicht essen, denn sie sind ein Greuel.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 43, '»Macht euch nicht selbst zum Greuel durch irgendein kleines Kriechtier, und verunreinigt euch nicht durch sie, so daß ihr durch sie unrein werdet!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 44, 'Denn ich bin der HERR, euer Gott. Heiligt euch also und seid heilig; denn ich bin heilig. Verunreinigt euch nicht selbst durch irgendein Gewürm, das auf der Erde kriecht!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 45, 'Denn ich bin der HERR, der euch aus Ägypten hergeführt hat, um euer Gott zu sein; darum sollt ihr heilig sein, denn ich bin heilig.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 46, 'Dies sind die Vorschriften in betreff der vierfüßigen Tiere, der Vögel und aller lebenden Wesen, die sich im Wasser regen, und all der Wesen, von denen die Erde wimmelt,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 47, 'damit man einen Unterschied macht zwischen dem Unreinen und dem Reinen, zwischen den Tieren, die man essen darf, und denen, die nicht gegessen werden dürfen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 12, 1, 'Darauf gebot der HERR dem Mose folgendes:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 12, 2, '»Teile den Israeliten folgende Verordnungen mit: Wenn ein Weib Mutter wird und einen Knaben gebiert, so ist sie sieben Tage lang unrein! Ebenso lange wie in den Tagen ihrer Unreinheit infolge ihres regelmäßigen Unwohlseins ist sie unrein.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 12, 3, 'Am achten Tage soll dann das Kind an seiner Vorhaut beschnitten werden.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 12, 4, 'Alsdann muß sie noch dreiunddreißig Tage während der Zeit ihrer Blutreinigung (zu Hause) bleiben: sie darf nichts Heiliges berühren und nicht ins Heiligtum kommen, bis die Tage ihrer Reinigung abgelaufen sind.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 12, 5, 'Gebiert sie aber ein Mädchen, so ist sie zwei Wochen lang unrein, wie bei ihrer regelmäßigen Unreinheit, und muß dann noch sechsundsechzig Tage während der Zeit ihrer Blutreinigung (zu Hause) bleiben.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 12, 6, 'Sobald dann die Tage ihrer Reinigung abgelaufen sind, so soll sie, mag das Kind ein Knabe oder ein Mädchen sein, ein einjähriges Lamm zum Brandopfer und eine junge Taube oder eine Turteltaube zum Sündopfer an den Eingang des Offenbarungszeltes zu dem Priester bringen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 12, 7, 'Dieser soll dann die Opfertiere vor dem HERRN darbringen und ihr dadurch Sühne erwirken, dann wird sie von ihrem Blutfluß rein sein. Diese Vorschriften gelten für die Wöchnerinnen, mag das Kind ein Knabe oder ein Mädchen sein.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 12, 8, 'Sollte ihr Vermögen aber zur Beschaffung eines Lammes nicht ausreichen, so soll sie zwei Turteltauben oder zwei junge Tauben nehmen, die eine zum Brandopfer, die andere zum Sündopfer. Wenn der Priester ihr dann Sühne erwirkt hat, wird sie rein sein.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 1, 'Hierauf gebot der HERR dem Mose und dem Aaron folgendes:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 2, '»Wenn sich bei einem Menschen auf seiner bloßen Haut eine Anschwellung oder ein Ausschlag oder ein heller Fleck bildet und sich so auf seiner Haut ein aussatzartiges Leiden entwickeln könnte, so soll der Betreffende zu dem Priester Aaron oder zu einem von dessen Söhnen, den Priestern, gebracht werden.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 3, 'Wenn dann der Priester die betroffene Stelle auf der Haut ansieht und dabei findet, daß die Haare auf der betroffenen Stelle weiß geworden sind und daß die betroffene Stelle tiefer liegend erscheint als die sie umgebende Haut, so handelt es sich um wirklichen Aussatz; und sobald der Priester dies wahrnimmt, soll er den Betreffenden für unrein erklären.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 4, 'Wenn sich aber ein weißer Fleck auf der Haut befindet, der nicht tiefer liegend erscheint als die ihn umgebende Haut und auf dem die Haare nicht weiß geworden sind, so soll der Priester den Betroffenen sieben Tage lang einschließen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 5, 'Wenn der Priester ihn dann am siebten Tage wieder untersucht und dabei findet, daß die betroffene Stelle sich in ihrem Aussehen gleichgeblieben ist, da das Übel sich auf der Haut nicht weiter ausgebreitet hat, so soll der Priester ihn noch einmal sieben Tage lang einschließen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 6, 'Wenn dann der Priester ihn am siebten Tage wieder untersucht und dabei findet, daß die betroffene Stelle blässer geworden ist und das Übel sich auf der Haut nicht weiter ausgebreitet hat, so soll ihn der Priester für rein erklären: es ist nur ein gewöhnlicher Ausschlag; der Betreffende muß seine Kleider waschen und ist dann rein.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 7, 'Wenn aber der Ausschlag, nachdem der Betreffende, um rein zu werden, sich dem Priester gezeigt hat, auf der Haut immer weiter um sich greift, so soll er sich dem Priester zum zweitenmal zeigen;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 8, 'wenn ihn dann der Priester untersucht und dabei findet, daß der Ausschlag sich auf der Haut weiter ausgebreitet hat, so soll der Priester ihn für unrein erklären: es ist wirklicher Aussatz.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 9, '»Wenn sich ein aussatzartiges Leiden an einem Menschen zeigt, so soll er zum Priester gebracht werden.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 10, 'Wenn der Priester ihn dann untersucht und dabei findet, daß sich eine weiße Anschwellung auf der Haut befindet, auf der die Haare weiß geworden sind, und daß wildes Fleisch auf der Anschwellung wuchert,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 11, 'so ist das ein bereits veralteter Aussatz auf seiner Haut; darum soll der Priester ihn für unrein erklären, ohne ihn erst einzuschließen; denn er ist wirklich unrein.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 12, 'Wenn aber der Aussatz auf der Haut so wuchert, daß der Aussatz die ganze Haut des Betroffenen vom Kopf bis zu den Füßen überzieht, soweit die Augen des Priesters blicken mögen,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 13, 'wenn also der Priester bei seiner Besichtigung findet, daß der Aussatz den ganzen Körper überzogen hat, so soll er den Betroffenen für rein erklären: er ist ganz und gar weiß geworden und daher rein.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 14, 'Sobald sich aber wildes Fleisch an ihm sehen läßt, ist er unrein.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 15, 'Sobald daher der Priester das wilde Fleisch wahrnimmt, soll er ihn für unrein erklären: das wilde Fleisch ist unrein, es ist wirklicher Aussatz.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 16, 'Wenn jedoch das wilde Fleisch wieder weggeht und der Betreffende wieder weiß wird, so soll er zum Priester gehen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 17, 'Wenn dieser ihn dann untersucht und dabei findet, daß die kranke Stelle wieder weiß geworden ist, so soll der Priester den Betroffenen für rein erklären: er ist wirklich rein.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 18, '»Wenn sich ferner an jemandes Leibe auf der Haut ein Geschwür bildet und wieder heilt,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 19, 'dann aber an der Stelle des Geschwürs eine weiße Anschwellung oder ein weiß-rötlicher Fleck entsteht, so soll der Betreffende sich dem Priester zeigen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 20, 'Wenn dieser ihn dann untersucht und dabei findet, daß die Stelle tiefer liegend erscheint als die sie umgebende Haut und daß die Haare darauf weiß geworden sind, so soll der Priester ihn für unrein erklären: es ist wirklicher Aussatz, der in dem Geschwür zum Ausbruch gekommen ist.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 21, 'Wenn aber der Priester bei der Besichtigung der Stelle findet, daß keine weißen Haare darauf vorhanden sind und daß der Fleck nicht tiefer liegt als die ihn umgebende Haut und blaß aussieht, so soll der Priester den Betreffenden sieben Tage lang einschließen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 22, 'Wenn sich dann (der Fleck) auf der Haut immer weiter ausgebreitet hat, so soll der Priester ihn für unrein erklären: es ist wirklicher Aussatz.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 23, 'Wenn aber der Fleck ruhig stehengeblieben ist, ohne weiter um sich gegriffen zu haben, so ist es nur ein vernarbtes Geschwür, und der Priester darf ihn für rein erklären.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 24, '»Oder wenn sich auf jemandes Haut eine Brandwunde befindet und das in der Brandwunde sich bildende Fleisch einen weiß-rötlichen oder weißen Fleck darstellt');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 25, 'und der Priester bei dessen Besichtigung findet, daß die Haare auf dem Fleck weiß geworden sind und (der Fleck) tiefer liegend erscheint als die ihn umgebende Haut, so liegt wirklicher Aussatz vor, der in der Brandwunde zum Ausbruch gekommen ist; darum soll der Priester den Betreffenden für unrein erklären: es ist wirklicher Aussatz.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 26, 'Wenn aber der Priester bei seiner Besichtigung findet, daß keine weißen Haare auf dem Fleck vorhanden sind und daß (der Fleck) nicht tiefer liegt als die ihn umgebende Haut und blaß aussieht, so soll der Priester den Betreffenden sieben Tage lang einschließen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 27, 'Wenn ihn dann der Priester am siebten Tage untersucht, so soll er, falls (der Fleck) sich auf der Haut weiter ausgebreitet hat, den Betreffenden für unrein erklären: es ist wirklicher Aussatz.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 28, 'Wenn aber der Fleck ruhig stehengeblieben ist, ohne auf der Haut weiter um sich gegriffen zu haben, und blaß aussieht, so liegt nur eine Anschwellung der Brandwunde vor; darum soll der Priester den Betreffenden für rein erklären, denn es ist nur eine vernarbte Brandwunde.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 29, '»Wenn ferner ein Mann oder eine Frau einen Ausschlag am Kopf oder am Bart bekommt');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 30, 'und der Priester bei der Untersuchung des Ausschlags findet, daß er tiefer liegend erscheint als die ihn umgebende Haut und daß sich feine, goldgelbe Haare darauf befinden, so soll der Priester den Betreffenden für unrein erklären: es ist bösartiger Grind, der Aussatz des Kopfes oder des Bartes.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 31, 'Wenn der Priester aber den bösen Grind besichtigt und dabei findet, daß (die kranke Stelle) zwar nicht tiefer liegend erscheint als die sie umgebende Haut, daß aber keine dunklen Haare darauf vorhanden sind, so soll der Priester den des Grindleidens Verdächtigen sieben Tage lang einschließen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 32, 'Wenn dann der Priester die betroffene Stelle am siebten Tage wieder untersucht und dabei findet, daß der Grind sich nicht weiter ausgebreitet hat und keine goldgelben Haare darauf vorhanden sind und der Grind nicht tiefer liegend erscheint als die ihn umgebende Haut,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 33, 'so soll der Betreffende sich scheren lassen – nur die grindige Stelle darf er nicht scheren –; und der Priester soll dann den des Grindleidens Verdächtigen noch einmal sieben Tage lang einschließen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 34, 'Wenn der Priester dann den Grind am siebten Tage wieder untersucht und dabei findet, daß der Grind sich auf der Haut nicht weiter ausgebreitet hat und daß er nicht tiefer liegend erscheint als die ihn umgebende Haut, so erkläre der Priester den Betreffenden für rein; er muß dann seine Kleider waschen und soll als rein gelten.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 35, 'Wenn aber, nachdem der Betreffende für rein erklärt worden ist, der Grind sich auf der Haut weiter ausbreitet');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 36, 'und der Priester bei der Untersuchung findet, daß der Grind auf der Haut weiter um sich gegriffen hat, so braucht der Priester nicht erst noch nach goldgelben Haaren zu suchen: der Betreffende ist unrein.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 37, 'Ist der Grind sich aber in seinem Aussehen gleich geblieben und sind dunkle Haare darauf gewachsen, so ist der Grind geheilt: der Betreffende ist rein, und der Priester soll ihn für rein erklären.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 38, '»Wenn ferner ein Mann oder eine Frau auf der Haut helle Flecke, weiße, helle Flecke bekommen');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 39, 'und der Priester bei seiner Untersuchung nur blasse, weiße Flecke auf ihrer Haut findet, so ist es ein ungefährlicher Ausschlag, der auf der Haut zum Ausbruch gekommen ist: der Betreffende ist rein.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 40, 'Wenn ferner einem Manne das Haupthaar ausgeht, so ist er ein Hinter-Kahlkopf: ein solcher ist rein;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 41, 'und wenn ihm das Haupthaar nach der Gesichtsseite zu ausgeht, so ist er ein Vorder-Kahlkopf: ein solcher ist ebenfalls rein.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 42, 'Wenn sich aber vorn oder hinten auf seiner Glatze ein weiß-rötlicher Ausschlag zeigt, so ist es der Aussatz, der vorn oder hinten auf seiner Glatze zum Ausbruch gekommen ist.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 43, 'Wenn also der Priester bei seiner Untersuchung findet, daß die Anschwellung des Ausschlags vorn oder hinten auf seiner Glatze weiß-rötlich aussieht, wie sonst der Aussatz auf der Haut des Leibes aussieht,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 44, 'so ist der Betreffende ein Aussätziger und daher unrein; der Priester muß ihn unbedingt für unrein erklären: er hat das Aussatzleiden an seinem Kopfe.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 45, '»Was nun den Aussätzigen betrifft, der dieses Leiden an sich hat, so soll er zerrissene Kleider tragen und sein Haupthaar ohne Pflege wachsen lassen; seinen Lippenbart soll er verhüllen und ›unrein! unrein!‹ ausrufen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 46, 'Solange die Krankheit an ihm haftet, soll er unrein sein: er ist unrein und soll abgesondert wohnen; außerhalb des Lagers soll seine Wohnung sein.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 47, '»Wenn ferner eine aussätzige Stelle an einem Kleidungsstück, es sei von Wolle oder von Leinen, zum Vorschein kommt');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 48, 'oder an gewebten oder gewirkten Stoffen von Leinen oder von Wolle oder an einer Lederhaut oder an irgendeinem Gegenstand von Leder');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 49, 'und die betroffene Stelle an dem Kleide oder am Leder oder an dem gewebten oder gewirkten Stoff oder an irgendeinem Gegenstand von Leder grünlich oder rötlich aussieht, so liegt Aussatz vor, und man soll es vom Priester beschauen lassen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 50, 'Der Priester soll dann den vorliegenden Schaden beschauen und den betroffenen Gegenstand sieben Tage lang unter Verschluß halten.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 51, 'Wenn er dann am siebten Tage bei der Besichtigung des betroffenen Gegenstandes findet, daß der Schaden an dem Kleidungsstück oder dem gewebten oder gewirkten Stoff oder am Leder – an irgendeinem Gegenstand, zu welchem Leder verarbeitet wird – weiter um sich gegriffen hat, so ist der Ausschlag ein bösartiger Aussatz: (der betreffende Gegenstand) ist unrein,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 52, 'und man soll das Kleidungsstück oder den gewebten oder gewirkten Stoff von Wolle oder von Leinen oder jeden ledernen Gegenstand, an dem der Aussatz haftet, verbrennen; denn es ist ein bösartiger Aussatz: (der betreffende Gegenstand) muß im Feuer verbrannt werden.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 53, 'Wenn der Priester aber bei der Besichtigung findet, daß der Schaden an dem Kleidungsstück oder dem gewebten oder gewirkten Stoff oder an irgendeinem Gegenstand von Leder nicht weiter um sich gegriffen hat,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 54, 'so soll der Priester anordnen, daß man den Gegenstand, an welchem der Ausschlag haftet, wasche, und soll ihn dann noch einmal sieben Tage lang unter Verschluß halten.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 55, 'Wenn der Priester dann den betroffenen Gegenstand nach der Waschung besichtigt und dabei findet, daß die betroffene Stelle ihr Aussehen nicht verändert hat, so ist der Gegenstand, wenn auch der Ausschlag nicht weiter um sich gegriffen hat, dennoch unrein: du sollst ihn im Feuer verbrennen; es ist eine eingefressene Vertiefung auf seiner Hinter- oder seiner Vorderseite.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 56, 'Findet der Priester aber bei der Besichtigung, daß die betroffene Stelle nach der Waschung blaß geworden ist, so soll er sie aus dem Kleidungsstück oder dem Leder oder dem gewebten oder gewirkten Stoff herausreißen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 57, 'Wenn (der Ausschlag) aber wiederum an dem Kleidungsstück oder dem gewebten oder gewirkten Stoff oder an irgendeinem Gegenstande von Leder zum Vorschein kommt, so ist es ein frisch ausbrechender Aussatz; darum mußt du den (ganzen) Gegenstand, an dem der Ausschlag haftet, im Feuer vernichten.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 58, 'Das Kleidungsstück aber oder der gewebte oder gewirkte Stoff oder jeder lederne Gegenstand, an welchem der Ausschlag nach der Waschung verschwunden ist, muß noch einmal gewaschen werden und soll dann als rein gelten.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 59, 'Dies sind die Vorschriften bezüglich des Aussatzes an Kleidungsstücken von Wolle oder von Leinen oder an gewebten oder gewirkten Stoffen oder an irgendeinem Gegenstand von Leder, um (derartige Sachen) für rein oder für unrein zu erklären.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 1, 'Weiter gab der HERR dem Mose folgende Weisungen:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 2, '»Folgende Vorschriften gelten für einen Aussätzigen am Tage, da er für rein erklärt wird: Er soll zu dem Priester geführt werden;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 3, 'und zwar muß der Priester vor das Lager hinausgehen. Wenn der Priester ihn dann untersucht und dabei findet, daß der bösartige Aussatz an dem Aussätzigen zur Heilung gekommen ist,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 4, 'so soll der Priester anordnen, daß man für den, der als rein erklärt werden soll, zwei lebende reine Vögel sowie ein Stück Zedernholz, Karmesinfäden und Ysop bringe.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 5, 'Sodann soll der Priester anordnen, daß man den einen Vogel über einem irdenen Gefäß mit Quell- oder Flußwasser schlachte.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 6, 'Den lebenden Vogel aber nebst dem Zedernholz, dem Karmesin und dem Ysop soll er nehmen und dies alles, auch den lebenden Vogel, in das Blut des über dem Quell- oder Flußwasser geschlachteten Vogels eintauchen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 7, 'Hierauf soll er den, welcher für rein vom Aussatz erklärt werden soll, siebenmal damit besprengen und ihn so reinigen; den lebenden Vogel aber soll er ins freie Feld fliegen lassen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 8, 'Hierauf soll der, welcher sich reinigen läßt, seine Kleider waschen, sein gesamtes Haar abscheren und ein Wasserbad nehmen: dann ist er rein. Danach darf er zwar wieder ins Lager kommen, muß aber noch sieben Tage außerhalb seines Zeltes bleiben.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 9, 'Am siebten Tage sodann soll er alle seine Haare abermals scheren, Kopfhaar, Bart und Augenbrauen, überhaupt sein gesamtes Haar soll er abscheren, seine Kleider waschen und seinen Leib im Wasser baden: dann ist er rein.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 10, '»Hierauf soll er am achten Tage zwei fehlerlose (männliche) Lämmer und ein einjähriges, fehlerloses weibliches Lamm nehmen, außerdem drei Zehntel Epha Feinmehl, das mit Öl gemengt ist, zum Speisopfer, und ein Log Öl.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 11, 'Der Priester aber, der die Reinigung vollzieht, soll denjenigen, der sich reinigen läßt, samt jenen Opfergaben vor den HERRN an den Eingang des Offenbarungszeltes stellen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 12, 'Dann nehme der Priester das eine (männliche) Lamm, bringe es als Schuldopfer dar nebst dem Log Öl und webe beides als Webeopfer vor dem HERRN.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 13, 'Dann schlachte er das andere Lamm an der Stätte, wo man die Sündopfer und die Brandopfer zu schlachten pflegt, an heiliger Stätte; denn wie das Sündopfer, so gehört auch das Schuldopfer dem Priester: es ist hochheilig.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 14, 'Hierauf nehme der Priester etwas von dem Blut des Schuldopfers und streiche es dem, der sich reinigen läßt, an das rechte Ohrläppchen und an den Daumen seiner rechten Hand sowie an die große Zehe seines rechten Fußes.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 15, 'Dann nehme der Priester etwas von dem Log Öl und gieße es in seine linke Hand,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 16, 'tauche dann seinen rechten Finger in das Öl, das sich in seiner linken Hand befindet, und sprenge von dem Öl mit seinem Finger siebenmal vor den HERRN.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 17, 'Von dem übrigen Öl aber, das sich in seiner Hand befindet, streiche der Priester dem, der sich reinigen läßt, etwas an das rechte Ohrläppchen und an den Daumen seiner rechten Hand sowie an die große Zehe seines rechten Fußes auf die Stelle, wo sich schon das Blut des Schuldopfers befindet.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 18, 'Was dann von dem Öl in der Hand des Priesters noch übrig ist, das tue er dem, der sich reinigen läßt, auf den Kopf, um ihm so Sühne vor dem HERRN zu erwirken.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 19, 'Hierauf richte der Priester das Sündopfer her und erwirke dadurch dem, welcher sich reinigen läßt, Sühne wegen seiner Unreinheit; darauf schlachte er das Brandopfertier.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 20, 'Wenn dann der Priester das Brandopfer und das Speisopfer auf dem Altar dargebracht und ihm so Sühne erwirkt hat, so ist der Betreffende rein.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 21, '»Wenn er aber arm ist und sein Vermögen nicht ausreicht, so soll er nur ein einziges Lamm als Schuldopfer zur Vollziehung der Webe nehmen, damit ihm Sühne erwirkt werde, ferner nur ein einziges Zehntel Feinmehl, das mit Öl gemengt ist, zum Speisopfer und ein Log Öl,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 22, 'dazu zwei Turteltauben oder zwei junge Tauben, je nach seinem Vermögen, und zwar die eine zum Sündopfer, die andere zum Brandopfer.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 23, 'Er bringe sie am achten Tage, nachdem er für rein erklärt worden ist, zu dem Priester an den Eingang des Offenbarungszeltes vor den HERRN.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 24, 'Der Priester nehme dann das zum Schuldopfer bestimmte Lamm sowie das Log Öl und webe beides als Webeopfer vor dem HERRN.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 25, 'Hierauf schlachte man das zum Schuldopfer bestimmte Lamm, und der Priester nehme etwas von dem Blut des Schuldopfers und streiche es dem, der sich reinigen läßt, an das rechte Ohrläppchen und an den Daumen seiner rechten Hand sowie an die große Zehe seines rechten Fußes.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 26, 'Dann gieße der Priester etwas von dem Öl in seine linke Hand');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 27, 'und sprenge mit seinem rechten Finger von dem Öl, das sich in seiner linken Hand befindet, siebenmal vor den HERRN.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 28, 'Dann streiche der Priester etwas von dem Öl, das sich in seiner Hand befindet, dem, welcher sich reinigen läßt, an das rechte Ohrläppchen und an den Daumen seiner rechten Hand sowie an die große Zehe seines rechten Fußes auf die Stelle, wo sich schon das Blut des Schuldopfers befindet.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 29, 'Was dann von dem Öl in der Hand des Priesters noch übrig ist, das tue er dem, der sich reinigen läßt, auf den Kopf, um ihm so Sühne vor dem HERRN zu erwirken.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 30, 'Hierauf richte der Priester die eine von den Turteltauben oder von den jungen Tauben her, für deren Beschaffung das Vermögen des Betreffenden ausgereicht hat,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 31, 'die eine zum Sündopfer, die andere zum Brandopfer samt dem Speisopfer. So erwirke der Priester dem, der sich reinigen läßt, Sühne vor dem HERRN.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 32, 'Dies sind die Vorschriften in betreff eines Aussätzigen, dessen Vermögen bei seiner Reinigung für die regelmäßigen Opfer nicht zureicht.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 33, 'Hierauf gebot der HERR dem Mose und Aaron folgendes:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 34, '»Wenn ihr in das Land Kanaan kommt, das ich euch zum Eigentum geben will, und ich in dem Lande, das euch alsdann gehört, an einem Hause einen Aussatzschaden entstehen lasse,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 35, 'so soll der Eigentümer des Hauses hingehen und dem Priester die Anzeige machen: ›Es zeigt sich mir an meinem Hause etwas, das wie Aussatzschaden aussieht.‹');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 36, 'Dann soll der Priester anordnen, daß man, noch ehe er selbst zur Besichtigung des Schadens hineingeht, das Haus ausräume, damit nicht alles, was sich im Hause befindet, unrein werde; hierauf soll der Priester hingehen, um das Haus zu besichtigen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 37, 'Wenn er dann bei der Besichtigung des Ausschlags findet, daß der Ausschlag sich an den Wänden des Hauses in Gestalt grünlicher oder rötlicher Vertiefungen zeigt und diese tiefer liegend erscheinen als die sie umgebende Wand,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 38, 'so soll der Priester aus dem Hause hinaus an den Eingang des Hauses gehen und das Haus auf sieben Tage verschließen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 39, 'Wenn der Priester dann am siebten Tage wiederkommt und bei der Besichtigung findet, daß der Schaden sich an den Wänden des Hauses weiter verbreitet hat,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 40, 'so soll der Priester anordnen, daß man die Steine, an denen sich der Schaden zeigt, herausbreche und sie außerhalb der Ortschaft an einen unreinen Ort hinwerfe.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 41, 'Das Haus aber lasse er im Inneren überall abkratzen, und den abgekratzten Bewurf schütte man außerhalb der Ortschaft an einen unreinen Ort hin.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 42, 'Dann soll man andere Steine nehmen und sie an die Stelle der ausgebrochenen Steine einsetzen; auch soll man andern Lehm nehmen und das Haus damit bewerfen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 43, 'Wenn dann der Ausschlag wiederkehrt und am Hause ausbricht, nachdem man die Steine ausgebrochen und das Haus abgekratzt und neu beworfen hat,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 44, 'so soll der Priester wiederkommen. Wenn er dann bei der Besichtigung findet, daß der Ausschlag am Hause weiter um sich gegriffen hat, so ist es ein bösartiger Aussatz am Hause: es ist unrein.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 45, 'Man soll deshalb das Haus niederreißen, seine Steine, sein Holzwerk und allen Bewurf des Hauses, und soll dies alles außerhalb der Ortschaft an einen unreinen Ort schaffen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 46, 'Und wer in das Haus hineingegangen ist, solange es verschlossen ist, soll bis zum Abend als unrein gelten,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 47, 'und wer in dem Hause geschlafen hat, muß seine Kleider waschen; ebenso muß der, welcher in dem Hause gegessen hat, seine Kleider waschen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 48, 'Wenn aber der Priester hineingeht und bei der Besichtigung findet, daß der Ausschlag am Hause, nachdem das Haus neu beworfen worden ist, nicht weiter um sich gegriffen hat, so soll der Priester das Haus für rein erklären; denn der Schaden ist geheilt.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 49, 'Er soll dann zur Entsündigung des Hauses zwei Vögel nehmen, ferner ein Stück Zedernholz, Karmesinfäden und Ysop,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 50, 'und soll den einen Vogel über einem irdenen Gefäß mit Quell- oder Flußwasser schlachten.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 51, 'Dann nehme er das Zedernholz, den Ysop, den Karmesin und den lebenden Vogel und tauche das alles in das Blut des geschlachteten Vogels und in das Quell- oder Flußwasser, besprenge damit das Haus siebenmal');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 52, 'und entsündige so das Haus mit dem Blut des Vogels und mit dem Quell- oder Flußwasser sowie mit dem lebenden Vogel und dem Zedernholz, mit dem Ysop und dem Karmesin;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 53, 'den lebenden Vogel aber lasse er außerhalb der Ortschaft ins freie Feld fliegen. Wenn er so dem Hause Sühne erwirkt hat, so ist es rein.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 54, 'Dies sind die Vorschriften bezüglich aller Arten von Aussatz und bezüglich des Grindes,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 55, 'ferner bezüglich des Aussatzes an Kleidungsstücken und an Häusern,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 56, 'ferner bezüglich der Anschwellungen sowie des Ausschlags und der hellen Flecken,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 57, 'um Belehrung darüber zu geben, wann etwas für unrein und wann für rein zu erklären ist. Dies sind die Vorschriften über den Aussatz.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 1, 'Weiter gebot der HERR dem Mose und Aaron folgendes:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 2, '»Teilt den Israeliten folgende Verordnungen mit: Wenn ein Mann einen Ausfluß aus seiner Scham hat, so ist dieser sein Ausfluß etwas Unreines;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 3, 'und zwar steht es mit seiner Unreinheit infolge seines Ausflusses so: Mag der Ausfluß aus seiner Scham dauernd sein oder nur zeitweise eintreten: in beiden Fällen liegt Unreinheit für ihn vor.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 4, 'Jedes Lager, auf dem der mit einem Ausfluß Behaftete liegt, wird unrein, und jedes Gerät, auf dem er sitzt, wird unrein.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 5, 'Wer sein Lager berührt, muß seine Kleider waschen und ein Wasserbad nehmen und ist bis zum Abend unrein.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 6, 'Auch wer sich auf das Gerät setzt, auf dem der mit einem Ausfluß Behaftete gesessen hat, muß seine Kleider waschen und ein Wasserbad nehmen und ist bis zum Abend unrein.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 7, 'Wer den Leib eines mit einem Ausfluß Behafteten berührt, muß seine Kleider waschen und ein Wasserbad nehmen und ist bis zum Abend unrein.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 8, 'Wenn ferner der mit einem Ausfluß Behaftete einen Reinen anspeit, so muß dieser seine Kleider waschen und ein Wasserbad nehmen und ist bis zum Abend unrein.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 9, 'Alles Reitzeug, auf dem der mit einem Ausfluß Behaftete beim Reiten sitzt, ist unrein;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 10, 'und wer irgend etwas berührt, was er unter sich gehabt hat, wird bis zum Abend unrein; und wer etwas Derartiges wegträgt, muß seine Kleider waschen und ein Wasserbad nehmen und ist bis zum Abend unrein.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 11, 'Jeder, den der mit einem Ausfluß Behaftete berührt, ohne sich zuvor die Hände mit Wasser abgespült zu haben, muß seine Kleider waschen und ein Wasserbad nehmen und ist bis zum Abend unrein.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 12, 'Ein irdenes Gefäß, das der mit einem Ausfluß Behaftete berührt, muß zerschlagen werden; und jedes Holzgerät muß im Wasser abgespült werden.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 13, 'Wenn aber der mit einem Ausfluß Behaftete von seinem Leiden befreit wird, so soll er von dem Zeitpunkte, wo er rein geworden ist, sieben Tage zählen; dann wasche er seine Kleider und bade seinen Leib in Quell- oder Flußwasser: so ist er rein.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 14, 'Am achten Tage aber nehme er sich zwei Turteltauben oder zwei junge Tauben, trete damit vor den HERRN an den Eingang des Offenbarungszeltes und übergebe sie dem Priester;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 15, 'dieser soll sie dann herrichten, die eine zum Sündopfer, die andere zum Brandopfer, und der Priester soll ihm so Sühne vor dem HERRN wegen seines Ausflusses erwirken.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 16, 'Wenn ferner ein Mann einen unfreiwilligen Samenerguß hat, so soll er seinen ganzen Leib im Wasser baden und ist bis zum Abend unrein;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 17, 'und jedes Kleidungsstück und alles Leder, an welches der Samenerguß gekommen ist, muß im Wasser gewaschen werden und ist bis zum Abend unrein. –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 18, 'Wenn ferner ein Mann bei einer Frau liegt und ein Samenerguß erfolgt, so müssen beide ein Wasserbad nehmen und sind bis zum Abend unrein.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 19, '»Wenn aber eine weibliche Person einen Ausfluß hat, und zwar ihren gewöhnlichen Blutfluß, so soll ihre Unreinheit sieben Tage lang dauern, und jeder, der sie während dieser Zeit berührt, wird bis zum Abend unrein.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 20, 'Alles, worauf sie während ihrer Unreinheit liegt, wird unrein, ebenso alles, worauf sie sitzt,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 21, 'und jeder, der ihr Lager berührt, muß seine Kleider waschen und ein Wasserbad nehmen und ist bis zum Abend unrein.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 22, 'Und jeder, der irgendein Gerät berührt, auf dem sie gesessen hat, muß seine Kleider waschen und ein Wasserbad nehmen und ist bis zum Abend unrein.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 23, 'Auch wenn einer etwas berührt, das sich auf ihrem Lager oder auf dem Gerät befindet, auf dem sie gesessen hat, so ist er bis zum Abend unrein.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 24, 'Und wenn etwa ein Mann ihr beiwohnt und etwas von ihrer Unreinigkeit an ihn kommt, so ist er sieben Tage lang unrein, und jedes Lager, auf dem er liegt, wird unrein.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 25, 'Wenn aber eine weibliche Person außer der Zeit ihrer regelmäßigen Unreinheit an einem langdauernden Blutfluß leidet oder über die Zeit ihrer regelmäßigen Unreinheit hinaus den Blutfluß hat, so soll von ihr während der ganzen Dauer ihres unreinen Flusses dasselbe gelten wie während der Zeit ihrer regelmäßigen Unreinheit: sie ist unrein.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 26, 'Jedes Lager, auf dem sie während der ganzen Dauer ihres Flusses liegt, soll für sie gelten wie das Lager zur Zeit ihrer regelmäßigen Unreinheit; und jedes Gerät, auf dem sie sitzt, wird gerade so unrein wie während der Zeit ihrer regelmäßigen Unreinheit;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 27, 'wer also irgendein solches (Gerät) berührt, wird dadurch unrein: er muß seine Kleider waschen und ein Wasserbad nehmen und bleibt bis zum Abend unrein.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 28, 'Wenn sie aber von ihrem Fluß rein geworden ist, so soll sie noch sieben Tage zählen: dann soll sie als rein gelten.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 29, 'Am achten Tage aber nehme sie sich zwei Turteltauben oder zwei junge Tauben und bringe sie zu dem Priester an den Eingang des Offenbarungszeltes;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 30, 'der Priester soll dann die eine als Sündopfer, die andere als Brandopfer darbringen und ihr so Sühne vor dem HERRN wegen ihres unreinen Flusses erwirken.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 31, '»So sollt ihr die Israeliten von ihrer Unreinheit befreien, damit sie nicht infolge ihrer Unreinheit sterben, wenn sie meine Wohnung, die sich mitten unter ihnen befindet, verunreinigen.« –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 32, 'Diese Vorschriften gelten für den mit einem Ausfluß Behafteten sowie für den, der durch Samenerguß verunreinigt wird,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 33, 'ferner für weibliche Personen, die an ihrer regelmäßigen Unreinheit leiden, und für jeden, der einen Ausfluß hat, es sei ein Mann oder eine weibliche Person, sowie für den Mann, der einer unreinen Frau beiwohnt.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 1, 'Weiter redete der HERR mit Mose nach dem Tode der beiden Söhne Aarons, die da hatten sterben müssen, als sie (mit einem ungehörigen Opfer) vor den HERRN getreten waren.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 2, 'Der HERR gebot damals dem Mose: »Sage deinem Bruder Aaron, er dürfe nicht zu jeder beliebigen Zeit in das (innerste) Heiligtum hinter den Vorhang eintreten vor die Deckplatte, die über der Lade liegt, er müßte sonst sterben; denn ich offenbare mich in der Wolke über der Deckplatte.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 3, 'Nur in dem Falle darf Aaron in das (innerste) Heiligtum eintreten, wenn er mit einem jungen Stier zum Sündopfer und mit einem Widder zum Brandopfer erscheint.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 4, 'Er muß ferner ein heiliges Unterkleid von Leinen anhaben und Unterbeinkleider von Leinen auf dem bloßen Leibe tragen und mit einem Gürtel von Leinen umgürtet sein und sich einen Kopfbund von Leinen umgebunden haben; das sind die heiligen Kleider, die er anlegen muß, nachdem er ein Wasserbad genommen hat.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 5, 'Von der Gemeinde der Israeliten aber soll er sich zwei Ziegenböcke zum Sündopfer und einen Widder zum Brandopfer geben lassen.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 6, '»Hierauf soll Aaron den jungen Stier, der zum Sündopfer für ihn selbst bestimmt ist, herzubringen und sich und seinem Hause Sühne erwirken.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 7, 'Dann soll er die beiden Böcke nehmen und sie vor den HERRN an den Eingang des Offenbarungszeltes stellen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 8, 'Hierauf soll Aaron Lose über die beiden Böcke werfen, das eine Los für den HERRN, das andere Los für Asasel.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 9, 'Dann soll Aaron den Bock, auf den das für den HERRN bestimmte Los gefallen ist, heranbringen und ihn als Sündopfer herrichten;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 10, 'der Bock aber, auf den das für Asasel bestimmte Los gefallen ist, soll lebend vor den HERRN gestellt werden, damit man über ihm die Sühnehandlungen vollziehe und ihn dann zu Asasel in die Wüste schicke.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 11, '»Aaron soll also den jungen Stier, der zum Sündopfer für ihn selbst bestimmt ist, herzubringen, um für sich und sein Haus Sühne zu erwirken. Er schlachte demnach den Stier, der zum Sündopfer für ihn bestimmt ist,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 12, 'nehme dann die Räucherpfanne voll glühender Kohlen von dem Altar, der vor dem HERRN steht, und seine beiden Hände voll feinzerstoßenen, wohlriechenden Räucherwerks und bringe es hinein in den Raum hinter dem Vorhange.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 13, 'Dort tue er das Räucherwerk vor dem HERRN auf die Kohlenglut, damit die Wolke des Räucherwerks die Deckplatte, die auf der Gesetzeslade liegt, verhülle und er nicht zu sterben braucht.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 14, 'Dann nehme er etwas von dem Blut des Stieres und sprenge es mit seinem Finger auf die Vorderseite der Deckplatte, und auf die Stelle vor der Deckplatte sprenge er siebenmal von dem Blut mit seinem Finger.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 15, '»Hierauf schlachte er den Bock, der zum Sündopfer für das Volk bestimmt ist, und bringe sein Blut in den Raum hinter dem Vorhang. Dort verfahre er mit diesem Blut ebenso, wie er mit dem Blut des Stieres verfahren ist: er sprenge es auf die Deckplatte und auf die Stelle vor die Deckplatte');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 16, 'und erwirke so dem Heiligtum Sühne wegen der Verunreinigungen durch die Israeliten und wegen aller Übertretungen, die sie sich haben zuschulden kommen lassen; ebenso verfahre er dann auch mit dem Offenbarungszelt dessen, der bei ihnen mitten unter ihren Versündigungen wohnt.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 17, 'Es darf aber kein Mensch im Offenbarungszelt anwesend sein, wenn er hineingeht, um im Heiligtum die Sühnehandlungen vorzunehmen, bis er wieder herausgekommen ist. So erwirke er Sühne für sich und sein Haus und für die ganze Gemeinde Israel.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 18, 'Alsdann soll er an den Altar hinausgehen, der vor dem HERRN steht, und auch an diesem die Entsündigung vollziehen. Er nehme nämlich etwas von dem Blut des Stieres und vom Blut des Bockes und streiche es an die Hörner des Altars ringsum;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 19, 'dann sprenge er etwas von dem Blut siebenmal mit seinem Finger an den Altar und heilige ihn so und reinige ihn von den Versündigungen der Israeliten.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 20, '»Nachdem er so die Sühnung des Heiligtums und des Offenbarungszeltes und des Altars vollzogen hat, soll er den noch lebenden Bock herbeiholen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 21, 'Aaron lege diesem Bock seine beiden Hände fest auf den Kopf, bekenne über ihm alle Verschuldungen der Israeliten und alle Übertretungen, die sie sich irgendwie haben zuschulden kommen lassen; er lege sie auf den Kopf des Bockes und lasse diesen durch einen bereitstehenden Mann in die Wüste fortschaffen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 22, 'So soll der Bock alle ihre Verschuldungen auf sich nehmen und sie in eine abgeschiedene Gegend tragen; (der Mann) soll ihn dann in der Wüste loslassen.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 23, '»Hierauf soll Aaron wieder in das Offenbarungszelt hineingehen und die leinenen Kleider, die er bei seinem Eintritt in das innerste Heiligtum angezogen hatte, ausziehen und sie dort niederlegen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 24, 'Darauf soll er an heiliger Stätte ein Wasserbad nehmen, dann seine gewöhnlichen Amtskleider anziehen, hierauf wieder hinausgehen und das Brandopfer für sich und das Brandopfer für das Volk herrichten, um dadurch sich und dem Volke Sühne zu erwirken.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 25, 'Das Fett des Sündopfers soll er auf dem Altar in Rauch aufgehen lassen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 26, 'Der Mann aber, der den Bock zu Asasel hinausgeschafft hat, muß seine Kleider waschen und ein Wasserbad nehmen: dann darf er wieder ins Lager kommen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 27, 'Den Sündopferstier aber und den Sündopferbock, deren Blut hineingebracht worden ist, um im innersten Heiligtum zur Vollziehung der Sühnehandlungen zu dienen, soll man vor das Lager hinausschaffen und ihre Felle, ihr Fleisch und ihren Eingeweideinhalt im Feuer verbrennen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 28, 'Der (Mann), welcher die Verbrennung besorgt hat, muß seine Kleider waschen und ein Wasserbad nehmen: dann darf er wieder ins Lager kommen.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 29, '»Und folgendes soll für euch eine ewiggültige Verordnung sein: Im siebten Monat, am zehnten Tage des Monats, sollt ihr eure Seelen beugen und dürft keinerlei Arbeit verrichten, weder der Einheimische noch der Fremdling, der sich bei euch aufhält;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 30, 'denn an diesem Tage erwirkt man für euch Sühne, um euch zu reinigen: von all euren Sünden sollt ihr da vor dem HERRN rein werden.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 31, 'Ein Tag völliger Ruhe soll es für euch sein, und ihr sollt fasten; das ist eine ewiggültige Verordnung.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 32, 'Die Sühnung soll aber der Priester vollziehen, den man gesalbt und in sein Amt eingesetzt haben wird, damit er an Stelle seines Vaters den Priesterdienst versehe; und er soll die leinenen Kleider, die heiligen Gewänder, anlegen');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 33, 'und das Allerheiligste entsündigen; ebenso soll er das Offenbarungszelt und den Altar entsündigen und auch den Priestern und der gesamten Volksgemeinde Sühne erwirken.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 34, 'Dies soll für euch eine ewiggültige Verordnung sein, daß man den Israeliten einmal im Jahr Sühne für all ihre Sünden erwirken soll.« – Und (Aaron) tat, wie der HERR dem Mose geboten hatte.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 17, 1, 'Hierauf gebot der HERR dem Mose folgendes:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 17, 2, '»Rede mit Aaron und seinen Söhnen und mit allen Israeliten und sage ihnen: Dies ist es, was der HERR geboten hat:«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 17, 3, '»Jedermann vom Hause Israel, der ein Rind oder ein Schaf oder eine Ziege innerhalb oder außerhalb des Lagers schlachten will,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 17, 4, '(das Tier) aber nicht an den Eingang des Offenbarungszeltes bringt, um es dem HERRN als Opfergabe vor der Wohnung des HERRN darzubringen, einem solchen Manne soll das als Blutschuld angerechnet werden: Blut hat er vergossen, darum soll ein solcher Mann aus der Mitte seines Volkes ausgerottet werden!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 17, 5, 'Die Israeliten sollen also ihre Schlachttiere, die sie jetzt auf freiem Felde zu schlachten pflegen, herbeibringen, und zwar sollen sie sie für den HERRN an den Eingang des Offenbarungszeltes zu dem Priester bringen und sie als Heilsopfer für den HERRN schlachten.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 17, 6, 'Der Priester soll dann das Blut an den Altar des HERRN, der vor dem Eingang des Offenbarungszeltes steht, sprengen und das Fett zum lieblichen Geruch für den HERRN in Rauch aufgehen lassen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 17, 7, 'Sie sollen also ihre Schlachttiere hinfort nicht mehr den bösen Geistern schlachten, deren Götzendienst sie jetzt treiben! Dies soll für sie eine ewiggültige Verordnung von Geschlecht zu Geschlecht sein.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 17, 8, '»Weiter sollst du ihnen sagen: Wenn jemand vom Hause Israel und von den Fremdlingen, die sich als Gäste bei ihnen aufhalten, ein Brandopfer oder ein Schlachtopfer darbringen will');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 17, 9, 'und es nicht an den Eingang des Offenbarungszeltes bringt, um es für den HERRN herzurichten, so soll ein solcher Mensch aus seinen Volksgenossen ausgerottet werden.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 17, 10, '»Wenn ferner jemand vom Hause Israel und von den Fremdlingen, die sich bei ihnen aufhalten, irgendwelches Blut genießt: gegen einen solchen Menschen, der Blut genießt, will ich mein Angesicht richten und ihn aus der Mitte seines Volkes ausrotten.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 17, 11, 'Denn das Leben des Leibes liegt im Blut, und ich habe es euch für den Altar bestimmt, damit ihr euch dadurch Sühne für eure Sünden erwirkt; denn das Blut ist es, das Sühne durch das in ihm enthaltene Leben bewirkt.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 17, 12, 'Darum habe ich den Israeliten geboten: Niemand von euch darf Blut genießen! Auch der Fremdling, der als Gast unter euch lebt, darf kein Blut genießen!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 17, 13, '»Wenn also jemand von den Israeliten und von den Fremdlingen, die als Gäste unter ihnen leben, ein Stück Wild oder Geflügel erjagt, das gegessen werden darf, so soll er das Blut des Tieres auslaufen lassen und es mit Erde bedecken.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 17, 14, 'Denn was das Leben alles Fleisches betrifft, so liegt sein Leben in seinem Blut. Darum habe ich den Israeliten geboten: Von keinem Fleisch dürft ihr das Blut genießen, denn das Leben alles Fleisches liegt in seinem Blut: jeder, der es genießt, soll ausgerottet werden. –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 17, 15, 'Und wer das Fleisch eines gefallenen oder von Raubtieren zerrissenen Tieres genießt, er sei ein Einheimischer oder ein Fremdling, der soll seine Kleider waschen und ein Wasserbad nehmen und ist bis zum Abend unrein: alsdann ist er wieder rein.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 17, 16, 'Wenn er aber (seine Kleider) nicht wäscht und sich nicht badet, so hat er seine Verschuldung zu tragen.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 1, 'Weiter gebot der HERR dem Mose folgendes:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 2, '»Teile den Israeliten folgende Verordnungen mit: Ich bin der HERR, euer Gott!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 3, 'Nach der Weise der Bewohner des Landes Ägypten, in dem ihr gewohnt habt, dürft ihr nicht verfahren; auch nach der Weise der Bewohner des Landes Kanaan, wohin ich euch bringen werde, dürft ihr nicht verfahren und nach ihren Satzungen nicht wandeln;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 4, 'nein, meine Gebote sollt ihr befolgen und meine Satzungen beobachten, um in ihnen zu wandeln: ich bin der HERR, euer Gott!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 5, 'So beobachtet denn meine Satzungen und meine Gebote; denn der Mensch, der nach ihnen tut, wird durch sie das Leben haben: ich bin der HERR!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 6, '»Keiner von euch darf sich irgendeiner seiner nächsten Blutsverwandten nahen, um mit ihr geschlechtlichen Umgang zu haben: ich bin der HERR!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 7, 'Mit deinem Vater und mit deiner Mutter darfst du keinen geschlechtlichen Umgang haben; sie ist deine Mutter: du darfst ihr nicht beiwohnen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 8, 'Mit deiner Stiefmutter darfst du keinen geschlechtlichen Umgang haben: dein Vater allein hat ein Recht an sie.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 9, 'Mit deiner Schwester, der Tochter deines Vaters oder der Tochter deiner Mutter, mag sie im Hause geboren oder auswärts geboren sein, darfst du keinen geschlechtlichen Umgang haben.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 10, 'Mit der Tochter deines Sohnes oder mit der Tochter deiner Tochter darfst du keinen geschlechtlichen Umgang haben; denn sie sind (wie) deine eigenen Töchter.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 11, 'Mit der Tochter der Frau deines Vaters, die dein Vater gezeugt hat – sie ist (wie) deine Schwester – darfst du keinen geschlechtlichen Umgang haben.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 12, 'Mit der Schwester deines Vaters darfst du keinen geschlechtlichen Umgang haben: sie ist deines Vaters nächste Blutsverwandte.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 13, 'Mit der Schwester deiner Mutter darfst du keinen geschlechtlichen Umgang haben, denn sie ist die nächste Blutsverwandte deiner Mutter.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 14, 'Mit der Frau des Bruders deines Vaters darfst du keinen geschlechtlichen Umgang haben; seinem Weibe darfst du nicht nahen, sie ist deine Muhme.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 15, 'Mit deiner Schwiegertochter darfst du keinen geschlechtlichen Umgang haben; sie ist das Weib deines Sohnes: du darfst ihr nicht beiwohnen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 16, 'Mit der Frau deines Bruders darfst du keinen geschlechtlichen Umgang haben; nur dein Bruder hat ein Recht an sie.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 17, 'Mit einer Frau und zugleich ihrer Tochter darfst du keinen geschlechtlichen Umgang haben; die Tochter ihres Sohnes und die Tochter ihrer Tochter darfst du nicht nehmen, um ihnen beizuwohnen; sie sind nächste Blutsverwandte: es wäre eine Schandtat.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 18, 'Auch darfst du eine Frau nicht zu ihrer Schwester als Nebenfrau hinzunehmen, um ihr neben jener, solange sie lebt, beizuwohnen.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 19, '»Du darfst ferner einer Frau während der Zeit ihrer Unreinheit nicht nahen, um ihr beizuwohnen. –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 20, 'Mit der Ehefrau deines Nächsten darfst du nicht den Beischlaf vollziehen, weil du dich dadurch verunreinigen würdest. –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 21, 'Von deinen Kindern darfst du keines hingeben, um es dem Moloch zur Opferung zu weihen, damit du den Namen deines Gottes nicht entweihst: ich bin der HERR. –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 22, 'Bei einem Manne darf man nicht liegen, wie man bei einer Frau liegt; das wäre eine Greueltat. –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 23, 'Auch mit keinem Tiere darfst du dich paaren und dich dadurch verunreinigen; und eine weibliche Person darf sich nicht vor ein Tier hinstellen, um sich von ihm begatten zu lassen; das wäre eine schändliche Versündigung.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 24, '»Verunreinigt euch nicht durch etwas Derartiges! Denn durch alles dieses haben sich die Völkerschaften verunreinigt, die ich vor euch vertreiben werde.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 25, '[Da das Land dadurch verunreinigt wurde, habe ich seine Verschuldung an ihm heimgesucht, so daß das Land seine Bewohner ausgespien hat.]');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 26, 'Ihr aber sollt meine Satzungen und meine Gebote beobachten und dürft keinen von allen solchen Greueln verüben, weder der Einheimische noch der Fremdling, der als Gast unter euch lebt –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 27, 'denn alle diese Greuel haben die Leute verübt, die vor euch im Lande gewohnt haben, und das Land ist dadurch verunreinigt worden –;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 28, 'das Land würde auch euch sonst ausspeien, wenn ihr es verunreinigt, wie es das Volk ausgespien hat, das vor euch da war.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 29, 'Denn wer irgendeinen von diesen Greueln verübt: alle, die Derartiges verüben, sollen aus der Mitte ihres Volkes ausgerottet werden.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 30, 'So beobachtet denn, was mir gegenüber zu beobachten ist, daß ihr keinen von den greulichen Bräuchen übt, die vor euch geübt worden sind, und euch dadurch nicht verunreinigt: ich bin der HERR, euer Gott!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 1, 'Weiter gebot der HERR dem Mose folgendes:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 2, '»Teile der ganzen Gemeinde der Israeliten folgende Verordnungen mit: Ihr sollt heilig sein, denn ich, der HERR euer Gott, bin heilig!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 3, 'Ihr sollt ein jeder Ehrfurcht vor seiner Mutter und seinem Vater haben und meine Ruhetage beobachten: ich bin der HERR, euer Gott. –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 4, 'Wendet euch nicht den Götzen zu und fertigt euch keine gegossenen Götterbilder an: ich bin der HERR, euer Gott!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 5, 'Wenn ihr dem HERRN ein Heilsopfer schlachten wollt, sollt ihr es so opfern, daß ihr Wohlgefallen (beim HERRN) dadurch erlangt.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 6, 'Am Tage, an dem ihr es opfert, und am Tage darauf muß es gegessen werden; was aber bis zum dritten Tage übriggeblieben ist, muß im Feuer verbrannt werden.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 7, 'Sollte dennoch am dritten Tage davon gegessen werden, so würde das als verdorbenes Fleisch gelten und nicht wohlgefällig aufgenommen werden:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 8, 'wer es äße, würde eine Verschuldung auf sich laden; denn er hätte das dem HERRN Geheiligte entweiht, und ein solcher Mensch soll aus seinen Volksgenossen ausgerottet werden.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 9, 'Wenn ihr die Ernte eures Landes schneidet, so sollst du dein Feld nicht ganz bis an den äußersten Rand abernten und auch keine Nachlese nach deiner Ernte halten.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 10, 'Auch in deinem Weinberge sollst du keine Nachlese vornehmen und die abgefallenen Beeren in deinem Weinberge nicht auflesen; dem Armen und dem Fremdling sollst du sie überlassen: ich bin der HERR, euer Gott!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 11, 'Ihr sollt nicht stehlen und nicht ableugnen und euch nicht untereinander betrügen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 12, 'Ihr sollt bei meinem Namen nicht falsch schwören, daß du den Namen deines Gottes entweihst: ich bin der HERR! –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 13, 'Du sollst deinen Nächsten nicht bedrücken und nicht berauben; der Lohn eines Tagelöhners soll von dir nicht über Nacht bis zum (andern) Morgen zurückbehalten werden. –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 14, 'Du sollst einem Tauben nicht fluchen und einem Blinden keinen Anstoß in den Weg legen, sondern dich vor deinem Gott fürchten: ich bin der HERR!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 15, 'Begeht kein Unrecht beim Rechtsprechen; sieh die Person eines Geringen nicht an, begünstige aber auch keinen Vornehmen, sondern richte deinen Nächsten dem Rechte gemäß.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 16, 'Geh nicht als Verleumder unter deinen Volksgenossen umher; tritt im Gericht nicht gegen das Blut deines Nächsten auf: ich bin der HERR! –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 17, 'Du sollst gegen deinen Bruder keinen Haß in deinem Herzen hegen, sondern sollst deinen Nächsten ernstlich zurechtweisen, damit du seinetwegen keine Verschuldung auf dich lädst.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 18, 'Du sollst den Angehörigen deines Volkes gegenüber nicht rachgierig sein und ihnen nichts nachtragen, sondern sollst deinen Nächsten lieben wie dich selbst: ich bin der HERR!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 19, '»Meine Gebote sollt ihr beobachten! Du darfst bei deinem Vieh nicht zweierlei Arten sich paaren lassen, auch dein Feld nicht mit zweierlei Samen besäen; und kein Kleid, das aus zweierlei Stoffen gewebt ist, darf auf deinen Leib kommen. –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 20, 'Wenn ein Mann bei einem Weibe liegt und ihr beiwohnt, die eine Sklavin ist, die als Nebenweib einem andern Manne angehört, aber weder losgekauft noch freigelassen ist, so soll eine Bestrafung stattfinden; doch sie sollen nicht den Tod erleiden, weil sie keine Freie gewesen ist.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 21, 'Er soll jedoch Gott dem HERRN als seine Buße einen Widder als Schuldopfer an den Eingang des Offenbarungszeltes bringen;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 22, 'und der Priester soll ihm mittels des Schuldopferwidders Sühne vor dem HERRN wegen seiner Sünde erwirken, die er begangen hat; dann wird ihm seine Sünde, die er begangen hat, vergeben werden. –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 23, 'Wenn ihr in das (verheißene) Land gekommen seid und allerlei Obstbäume pflanzt, so sollt ihr deren Vorhaut – d.h. ihren Fruchtertrag – als Vorhaut ansehen: drei Jahre lang sollen sie euch als unbeschnitten gelten, so daß nichts von ihnen gegessen werden darf.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 24, 'Im vierten Jahr aber soll ihr ganzer Fruchtertrag dem HERRN als Gabe des Dankes geweiht sein.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 25, 'Erst im fünften Jahr dürft ihr Früchte von ihnen genießen und werdet alsdann einen um so reicheren Ertrag erlangen: ich bin der HERR, euer Gott! –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 26, 'Ihr dürft nichts essen, was Blut enthält. – Ihr dürft nicht Wahrsagerei noch Zauberei treiben. –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 27, 'Ihr dürft euer Haupthaar an den Schläfen nicht rund scheren; auch darfst du den Rand deines Bartes nicht stutzen. –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 28, 'Wegen eines Toten dürft ihr euch keine Einschnitte an eurem Leibe machen und keine Ätzschrift an euch anbringen: ich bin der HERR! –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 29, 'Du sollst deine Tochter nicht entweihen, indem du eine Buhldirne aus ihr machst; denn das Land soll keine Buhlerei treiben, und das Land darf nicht voll von Unzucht werden. –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 30, 'Meine Ruhetage sollt ihr beobachten und vor meinem Heiligtum Ehrfurcht haben: ich bin der HERR! –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 31, 'Wendet euch nicht an die Totengeister und an die Wahrsagegeister; sucht sie nicht auf, damit ihr nicht durch sie verunreinigt werdet: ich bin der HERR, euer Gott!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 32, '»Vor einem grauen Haupte sollst du aufstehen und die Person eines Greises ehren und dich vor deinem Gott fürchten: ich bin der HERR! –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 33, 'Wenn ein Fremdling sich bei dir in eurem Lande als Gast aufhält, so sollt ihr ihn nicht bedrücken;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 34, 'wie ein Einheimischer aus eurer eigenen Mitte soll euch der Fremdling gelten, der unter euch lebt, und du sollst ihn lieben wie dich selbst; denn ihr seid ja selbst Fremdlinge im Lande Ägypten gewesen: ich bin der HERR, euer Gott!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 35, 'Ihr sollt kein Unrecht verüben weder beim Rechtsprechen noch mit dem Längenmaß, mit dem Gewicht und dem Hohlmaß;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 36, 'richtige Waage, richtige Gewichtstücke, richtiges Getreide- und Flüssigkeitsmaß sollt ihr führen: ich bin der HERR, euer Gott, der euch aus dem Lande Ägypten weggeführt hat.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 37, 'So beobachtet denn alle meine Satzungen und alle meine Gebote und handelt nach ihnen: ich bin der HERR!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 1, 'Weiter gebot der HERR dem Mose folgendes:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 2, '»Den Israeliten sollst du sagen: Wenn irgendeiner von den Israeliten oder von den Fremdlingen, die in Israel als Gäste leben, eins von seinen Kindern dem Moloch hingibt, so soll er unfehlbar mit dem Tode bestraft werden: das Volk des Landes soll ihn steinigen!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 3, 'Ich selbst will mein Angesicht gegen einen solchen Menschen kehren und ihn aus der Mitte seines Volkes ausrotten, weil er eins von seinen Kindern dem Moloch hingegeben und so mein Heiligtum verunreinigt und meinen heiligen Namen entweiht hat.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 4, 'Wenn also das Volk des Landes die Augen vor einem solchen Menschen, der eins von seinen Kindern dem Moloch hingibt, verschließen sollte, so daß es ihn nicht tötet,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 5, 'so will ich selbst mein Angesicht gegen den betreffenden Menschen und gegen sein ganzes Geschlecht kehren und ihn samt allen, die denselben Götzendienst treiben und sich dem Moloch mit ihrem Götzendienst ergeben, aus der Mitte ihres Volkes ausrotten.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 6, 'Wenn sich ferner jemand an die Totenbeschwörer und die Wahrsager wendet, um Götzendienst mit ihnen zu treiben, so will ich mein Angesicht gegen einen solchen Menschen kehren und ihn aus der Mitte seines Volkes ausrotten.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 7, '»So heiligt euch denn, daß ihr heilig werdet; denn ich bin der HERR, euer Gott;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 8, 'beobachtet meine Satzungen und tut nach ihnen: ich, der HERR, bin es, der euch heiligt.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 9, 'Ein jeder, der seinem Vater oder seiner Mutter flucht, soll unfehlbar mit dem Tode bestraft werden! Er hat seinem Vater oder seiner Mutter geflucht: Blutschuld lastet auf ihm.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 10, 'Wenn ferner ein Mann Ehebruch mit einer verheirateten Frau treibt, wenn er mit der Ehefrau seines Nächsten Ehebruch treibt, so sollen beide, der Ehebrecher und die Ehebrecherin, unfehlbar mit dem Tode bestraft werden. –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 11, 'Wenn ein Mann der Frau seines Vaters beiwohnt, so hat er seinen Vater geschändet; beide Schuldige sollen unfehlbar mit dem Tode bestraft werden: Blutschuld lastet auf ihnen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 12, 'Wenn ein Mann seiner Schwiegertochter beiwohnt, so sollen beide unfehlbar mit dem Tode bestraft werden; sie haben eine schändliche Befleckung verübt: Blutschuld lastet auf ihnen. –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 13, 'Wenn ein Mann bei einem andern Manne liegt, wie man einem Weibe beiwohnt, so haben beide eine Greueltat begangen; sie sollen unfehlbar mit dem Tode bestraft werden: Blutschuld lastet auf ihnen. –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 14, 'Wenn ein Mann eine Frau ehelicht und zugleich ihre Mutter, so ist das eine Schandtat: man soll ihn und die beiden Frauen verbrennen, damit keine solche Schandtat unter euch verübt werde. –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 15, 'Wenn sich ferner ein Mann mit einem Tiere paart, so soll er unfehlbar mit dem Tode bestraft werden, und auch das Tier sollt ihr töten.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 16, 'Und wenn ein Weib sich irgendeinem Tiere naht, um sich mit ihm zu paaren, so sollst du das Weib samt dem Tiere töten; sie sollen unfehlbar mit dem Tode bestraft werden: Blutschuld lastet auf ihnen. –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 17, 'Wenn ein Mann seine Schwester nimmt, die Tochter seines Vaters oder die Tochter seiner Mutter, und den Beischlaf im Einverständnis mit ihr vollzieht, so ist das Blutschande; sie sollen vor den Augen ihrer Volksgenossen ausgerottet werden: er hat seiner Schwester beigewohnt: er soll für seine Verschuldung büßen! –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 18, 'Wenn ferner ein Mann mit einer weiblichen Person zur Zeit ihres monatlichen Unwohlseins geschlechtlichen Umgang gehabt hat, wenn er also den Quell ihres Blutes enthüllt und sie (selbst) den Quell ihres Blutes aufgedeckt hat, so sollen beide aus der Mitte ihres Volkes ausgerottet werden! –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 19, 'Mit der Schwester deiner Mutter und mit der Schwester deines Vaters darfst du keinen geschlechtlichen Umgang haben; denn wer das tut, der hat sich mit seiner nächsten Blutsverwandten geschlechtlich vergangen: sie sollen für ihre Verschuldung büßen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 20, 'Wenn ferner ein Mann der Frau seines Oheims beiwohnt, so hat er seinen Oheim geschändet; sie sollen für ihre Sünde büßen: kinderlos werden sie sterben.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 21, 'Und wenn ein Mann die Frau seines Bruders zum Weibe nimmt, so ist das Blutschande; er hat damit seinen Bruder geschändet: sie werden kinderlos bleiben.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 22, '»So beobachtet denn alle meine Satzungen und alle meine Gebote und tut nach ihnen, damit euch das Land nicht ausspeie, in das ich euch bringen will, damit ihr darin wohnt.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 23, 'Ihr dürft also nicht nach den Satzungen der Völkerschaften wandeln, die ich vor euch vertreiben werde; denn alle diese Sünden haben sie verübt, so daß sie mir zum Ekel geworden sind.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 24, 'Euch aber habe ich verheißen: Ihr sollt ihr Land in Besitz nehmen, und ich will es euch zu eigen geben, ein Land, das von Milch und Honig überfließt: ich bin der HERR, euer Gott, der ich euch von den übrigen Völkern abgesondert habe.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 25, 'So macht denn einen Unterschied zwischen den reinen und den unreinen vierfüßigen Tieren und zwischen den unreinen und den reinen Vögeln, und macht euch nicht selbst zu einem Greuel durch (unreine) vierfüßige Tiere oder durch Vögel oder durch irgendwelche Tiere, die sich auf dem Erdboden regen, die ich euch als unrein bezeichnet und ausgesondert habe.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 26, 'Ihr sollt mir also heilig sein, denn ich, der HERR, bin heilig und habe euch von den übrigen Völkern abgesondert, damit ihr mir angehört.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 27, '»Wenn ferner ein Mann oder ein Weib einen Geist der Totenbeschwörung oder einen Wahrsagegeist in sich hat, so sollen sie unfehlbar mit dem Tode bestraft werden; man soll sie steinigen: Blutschuld lastet auf ihnen.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 21, 1, 'Weiter gebot der HERR dem Mose: »Teile den Priestern, den Söhnen Aarons, folgende Verordnungen mit: (Ein Priester) darf sich unter seinen Volksgenossen an keiner Leiche verunreinigen;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 21, 2, 'nur an seinen nächsten Blutsverwandten, nämlich an seiner Mutter und seinem Vater, an seinem Sohn und seiner Tochter und seinem Bruder,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 21, 3, 'auch an seiner Schwester, wenn sie noch Jungfrau ist und ihm darum nahesteht und noch keinem Manne angehört hat – an dieser darf er sich verunreinigen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 21, 4, 'Er darf sich nicht als Gatte unter seinen Volksgenossen verunreinigen, so daß er dadurch entweiht würde.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 21, 5, 'Sie dürfen sich an ihrem Haupt keine Glatze scheren und den Rand ihres Bartes nicht stutzen und sich keine Einschnitte in ihren Leib machen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 21, 6, 'Sie sollen ihrem Gott heilig sein und den Namen ihres Gottes nicht entweihen; denn sie haben die Feueropfer des HERRN, die Speise ihres Gottes, darzubringen; darum sollen sie heilig sein. –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 21, 7, 'Eine Buhldirne oder eine Entehrte dürfen sie nicht zur Ehefrau nehmen, ebensowenig eine von ihrem Manne verstoßene Frau; denn (der Priester) ist seinem Gott geweiht.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 21, 8, 'Darum sollst du ihn für heilig achten, denn er bringt die Speise deines Gottes dar: als heilig soll er dir gelten, denn ich bin heilig, der HERR, der euch heiligt.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 21, 9, 'Und wenn die Tochter eines Priesters sich durch Unzucht entweiht, so entweiht sie dadurch ihren Vater: im Feuer soll sie verbrannt werden!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 21, 10, 'Der Priester aber, welcher der oberste unter seinen Amtsgenossen ist, auf dessen Haupt das Salböl gegossen worden ist und den man in sein Amt eingesetzt hat, damit er die heiligen Kleider anziehe, darf sein Haupthaar (in der Trauer) nicht auflösen und seine Kleider nicht zerreißen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 21, 11, 'Er darf auch zu keiner Leiche hineingehen; sogar an seinem Vater und an seiner Mutter darf er sich nicht verunreinigen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 21, 12, 'Aus dem Heiligtum darf er sich nicht entfernen, damit er das Heiligtum seines Gottes nicht entweiht; denn die Weihe des Salböls seines Gottes befindet sich auf ihm: ich bin der HERR.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 21, 13, 'Zur Ehefrau muß er sich eine Jungfrau nehmen;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 21, 14, 'eine Witwe oder eine verstoßene Frau oder eine Entehrte oder eine Buhldirne – diese darf er nicht ehelichen; sondern eine Jungfrau aus seinen Volksgenossen muß er sich zur Frau nehmen,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 21, 15, 'damit er seine Nachkommenschaft unter seinen Volksgenossen nicht entweiht; denn ich bin der HERR, der ihn heiligt.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 21, 16, 'Weiter gebot der HERR dem Mose folgendes:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 21, 17, '»Teile dem Aaron folgende Verordnungen mit: Wenn irgendeiner von deinen Nachkommen in ihren künftigen Geschlechtern einen Leibesfehler an sich hat, so darf er nicht herantreten, um die Speise seines Gottes darzubringen;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 21, 18, 'denn keiner, der ein leibliches Gebrechen an sich hat, darf mir nahen, kein Blinder oder Lahmer, kein im Gesicht Entstellter oder einer, an dem ein Glied zu lang ist;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 21, 19, 'auch keiner, der einen Beinbruch oder einen Armbruch hat,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 21, 20, 'auch kein Buckliger und kein Zwerg, keiner, der weiße Flecken im Auge hat oder der mit Krätze oder mit Flechten behaftet oder der entmannt ist.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 21, 21, 'Keiner von den Nachkommen des Priesters Aaron, der ein Gebrechen an sich hat, darf mir nahen, um die Feueropfer des HERRN darzubringen; hat er ein Gebrechen an sich, so darf er mir nicht nahen, um die Speise seines Gottes darzubringen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 21, 22, 'Von der Speise seines Gottes, sowohl von den hochheiligen als auch von den heiligen Gaben, darf er essen;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 21, 23, 'doch zu dem (inneren) Vorhang darf er nicht hineingehen und an den Altar nicht treten, weil er ein Gebrechen an sich hat; sonst würde er meine Heiligtümer entweihen; denn ich bin der HERR, der sie heiligt.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 21, 24, 'Mose teilte dies dann dem Aaron und dessen Söhnen und allen Israeliten mit.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 1, 'Weiter gebot der HERR dem Mose folgendes:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 2, '»Befiehl Aaron und seinen Söhnen, daß sie den heiligen Gaben gegenüber, die die Israeliten mir weihen, Zurückhaltung beobachten, damit sie meinen heiligen Namen nicht entweihen: ich bin der HERR.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 3, 'Sage zu ihnen: (Diese Verordnung gilt) für alle eure künftigen Geschlechter: Wenn irgendeiner von all euren Nachkommen den heiligen Gaben, welche die Israeliten dem HERRN weihen, nahekommt, während er eine Unreinheit an sich hat, ein solcher Mensch soll von meinem Angesicht hinweg ausgerottet werden: ich bin der HERR!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 4, 'Wer von den Nachkommen Aarons mit Aussatz oder mit einem Ausfluß behaftet ist, darf von den heiligen Gaben nicht mitessen, bis er wieder rein ist; und wer irgendeinen durch eine Leiche Verunreinigten berührt oder wer einen Samenerguß gehabt hat');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 5, 'oder wer irgendein kriechendes Tier berührt hat, durch das man unrein wird, oder einen Menschen, durch den man in irgendeiner Beziehung unrein wird: –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 6, 'einer, der etwas Derartiges berührt hat, ist bis zum Abend unrein und darf nichts von den heiligen Gaben genießen, es sei denn, daß er zuvor ein Wasserbad genommen hat.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 7, 'Nach Sonnenuntergang aber ist er wieder rein und darf alsdann von den heiligen Gaben essen; denn sie sind die ihm zukommende Speise.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 8, 'Ein gefallenes oder (von Raubtieren) zerrissenes Tier darf er nicht essen; er würde dadurch unrein werden: ich bin der HERR.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 9, 'So sollen sie denn meine Verordnungen befolgen, damit sie nicht wegen einer Übertretung Sünde auf sich laden und infolge einer Entweihung des Geheiligten sterben müssen: ich bin der HERR, der sie heiligt!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 10, 'Kein Unbefugter darf etwas Geheiligtes genießen; kein Beisasse eines Priesters und keiner von seinen Tagelöhnern darf etwas Geheiligtes genießen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 11, 'Wenn aber ein Priester einen Sklaven für Geld erwirbt, so darf dieser davon (mit)essen; ebenso dürfen die in seinem Hause geborenen Sklaven von seiner Speise (mit)essen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 12, 'Wenn ferner die Tochter eines Priesters einen Nichtpriester geheiratet hat, so darf sie von den Hebeopfern der heiligen Gaben nichts genießen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 13, 'Wenn aber die Tochter eines Priesters Witwe oder (von ihrem Mann) geschieden wird, ohne Kinder zu haben, und in das Haus ihres Vaters zurückkehrt, so darf sie, gerade wie in ihrer Jugend, von der Speise ihres Vaters (mit)essen; dagegen darf kein Unbefugter etwas davon genießen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 14, 'Wenn ferner jemand aus Versehen etwas Geheiligtes genießt, so soll er den fünften Teil des Wertes hinzufügen und das Geheiligte dem Priester erstatten.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 15, 'Die Priester aber sollen die heiligen Gaben der Israeliten, die sie als Hebeopfer für den HERRN empfangen, nicht entweihen,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 16, 'damit sie ihnen kein Vergehen und keine Schuld dadurch aufladen, daß sie ihre heiligen Gaben genießen; denn ich bin der HERR, der sie heiligt.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 17, 'Weiter gebot der HERR dem Mose folgendes:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 18, '»Teile dem Aaron und seinen Söhnen und allen Israeliten folgende Verordnungen mit: Wenn irgend jemand vom Hause Israel oder von den Fremdlingen in Israel seine Opfergabe darbringen will – es seien irgendwelche gelobte oder freiwillige Gaben, die sie dem HERRN als Brandopfer darbringen wollen –,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 19, 'so muß es, um euch wohlgefällig zu machen, ein fehlerloses männliches Tier von den Rindern, von den Schafen oder den Ziegen sein.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 20, 'Kein Tier, das einen Fehler an sich hat, dürft ihr darbringen; denn es würde euch nicht wohlgefällig machen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 21, 'Und wenn jemand dem HERRN ein Heilsopfer darbringen will, ein Rind oder ein Stück Kleinvieh, sei es um ein Gelübde zu erfüllen oder als freiwillige Gabe, so darf es, um wohlgefällig zu sein, keinen Fehler, keinerlei Gebrechen an sich haben.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 22, 'Ist es blind oder hat es ein gebrochenes Glied oder einen Wundschaden oder ist es mit Geschwüren oder mit Krätze oder mit Flechten behaftet: derartige Tiere dürft ihr dem HERRN nicht darbringen und kein Feueropfer von ihnen dem HERRN auf den Altar legen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 23, 'Ein Rind oder ein Stück Kleinvieh, an dem ein Glied zu lang oder zu kurz (verkrüppelt) ist, magst du als freiwillige Gabe opfern, aber als Gelübdeopfer würde es nicht wohlgefällig aufgenommen werden.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 24, 'Ein Tier ferner, dem die Hoden zerquetscht oder zerschlagen oder ausgerissen oder ausgeschnitten sind, dürft ihr dem HERRN nicht darbringen; weder dürft ihr Tiere in eurem Lande zu verstümmelten (Tieren) machen');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 25, 'noch solche von einem Ausländer kaufen und sie als Speise eurem Gott darbringen; denn eine Verstümmlung, ein Gebrechen haftet ihnen an; sie würden euch nicht wohlgefällig machen.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 26, 'Weiter gebot der HERR dem Mose folgendes:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 27, '»Ein Rind oder ein Schaf oder ein Ziegenlamm soll nach der Geburt sieben Tage lang unter seiner Mutter bleiben; erst vom achten Tage an und weiterhin wird es (als Opfergabe) wohlgefällig sein, wenn man es als Feueropfer dem HERRN darbringt. –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 28, 'Ein Rind oder ein Stück Kleinvieh dürft ihr nicht zugleich mit seinem Jungen an einem und demselben Tage schlachten. –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 29, 'Wenn ihr ferner dem HERRN ein Dankschlachtopfer darbringen wollt, sollt ihr es so opfern, daß ihr Wohlgefallen dadurch erlangt:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 30, 'es muß noch an demselben Tage verzehrt werden; ihr dürft nichts davon bis zum andern Morgen übriglassen: ich bin der HERR!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 31, '»So beobachtet denn meine Gebote und tut nach ihnen: ich bin der HERR!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 32, 'Und entweiht meinen heiligen Namen nicht, damit ich inmitten der Israeliten geheiligt werde: ich bin der HERR, der euch heiligt,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 33, 'der euch aus Ägypten herausgeführt hat, um euer Gott zu sein: ich bin der HERR!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 1, 'Hierauf gebot der HERR dem Mose folgendes:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 2, '»Teile den Israeliten folgende Verordnungen mit: Die Feste des HERRN, die ihr als Festversammlungen am Heiligtum ausrufen sollt, meine Feste, sind folgende:«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 3, 'Sechs Tage hindurch soll gearbeitet werden, aber der siebte Tag ist ein Tag völliger Ruhe mit Versammlung am Heiligtum; da dürft ihr keinerlei Arbeit verrichten: es ist ein Ruhetag zu Ehren des HERRN in allen euren Wohnsitzen.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 4, '»Folgendes sind die Feste des HERRN mit Versammlungen am Heiligtum, die ihr zu dem für sie festgesetzten Zeitpunkt ausrufen sollt:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 5, 'Am vierzehnten Tag des ersten Monats gegen Abend findet die Passahfeier für den HERRN statt;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 6, 'und am fünfzehnten Tage desselben Monats wird das Fest der ungesäuerten Brote zu Ehren des HERRN gefeiert; da sollt ihr sieben Tage lang ungesäuerte Brote essen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 7, 'Am ersten Tage habt ihr eine Festversammlung am Heiligtum zu halten: da dürft ihr keinerlei Werktagsarbeit verrichten');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 8, 'und sollt dem HERRN sieben Tage lang ein Feueropfer darbringen. Am siebten Tage soll wieder eine Festversammlung am Heiligtum stattfinden: da dürft ihr keinerlei Werktagsarbeit verrichten.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 9, 'Weiter gebot der HERR dem Mose folgendes:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 10, '»Teile den Israeliten folgende Verordnungen mit: Wenn ihr in das Land kommt, das ich euch geben werde, und ihr die Ernte dort abhaltet, so sollt ihr von eurer Ernte die Erstlingsgarbe zum Priester bringen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 11, 'Dieser soll dann die gespendete Garbe vor dem HERRN weben, damit sie euch wohlgefällig mache; am Tage nach dem Sabbat soll der Priester sie weben;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 12, 'und ihr sollt an dem Tage, an welchem ihr die Garbe weben laßt, dem HERRN ein fehlerloses einjähriges Lamm als Brandopfer darbringen;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 13, 'dazu als Speisopfer für ihn zwei Zehntel Epha Feinmehl, das mit Öl gemengt ist, als ein Feueropfer für den HERRN zu lieblichem Geruch; dazu als Trankopfer für ihn ein Viertel Hin Wein.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 14, 'Brot (vom neuen Getreide) und geröstete oder zerstoßene Körner (der frischen Frucht) dürft ihr bis zu eben diesem Tage, bis ihr eurem Gott die Opfergabe dargebracht habt, nicht essen: diese Verordnung soll ewige Geltung für eure künftigen Geschlechter in allen euren Wohnsitzen haben.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 15, '»Hierauf sollt ihr euch vom Tage nach dem Sabbat an, von dem Tage an, wo ihr die Webegarbe dargebracht habt, sieben Wochen abzählen: volle Wochen sollen es sein;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 16, 'bis zu dem Tage, der auf den siebten Sabbat folgt, sollt ihr fünfzig Tage abzählen und dann dem HERRN ein Speisopfer vom neuen Getreide darbringen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 17, 'Aus euren Wohnsitzen sollt ihr zwei Webebrote darbringen, die aus zwei Zehntel Epha Feinmehl hergestellt und mit Sauerteig gebacken sein müssen, als Erstlingsgaben für den HERRN.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 18, 'Weiter sollt ihr zu den Broten sieben fehlerlose einjährige Lämmer und einen jungen Stier und zwei Widder darbringen – die sollen für den HERRN ein Brandopfer sein – samt dem zugehörigen Speisopfer und den erforderlichen Trankopfern, als ein Feueropfer zu lieblichem Geruch für den HERRN.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 19, 'Ferner sollt ihr einen Ziegenbock zum Sündopfer und zwei einjährige Lämmer zum Heilsopfer herrichten.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 20, 'Der Priester soll sie dann samt den Erstlingsbroten als Webeopfer vor dem HERRN weben zugleich mit den beiden Lämmern; sie sollen dem HERRN geheiligt sein und dem Priester gehören.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 21, 'Und ihr sollt an eben diesem Tage ausrufen lassen: ›Eine Festversammlung am Heiligtum sollt ihr abhalten und keinerlei Werktagsarbeit verrichten!‹ Diese Verordnung soll ewige Geltung in allen euren Wohnsitzen für eure künftigen Geschlechter haben! –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 22, 'Wenn ihr aber die Ernte eures Landes schneidet, sollst du das Feld nicht bis zum äußersten Rand abernten und auch keine Nachlese nach deiner Ernte vornehmen; nein, dem Armen und dem Fremdling sollst du beides überlassen: ich bin der HERR, euer Gott.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 23, 'Weiter gebot der HERR dem Mose folgendes:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 24, '»Teile den Israeliten folgende Verordnungen mit: Am ersten Tage des siebten Monats soll bei euch ein Ruhetag sein, ein Gedenktag mit Posaunenschall, eine Festversammlung am Heiligtum.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 25, 'Da dürft ihr keinerlei Werktagsarbeit verrichten und sollt dem HERRN ein Feueropfer darbringen.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 26, 'Weiter gebot der HERR dem Mose folgendes:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 27, '»Sodann fällt auf den zehnten Tag desselben siebten Monats der Versöhnungstag; da sollt ihr eine Festversammlung am Heiligtum halten und sollt fasten und dem HERRN ein Feueropfer darbringen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 28, 'Keinerlei Arbeit dürft ihr an eben diesem Tage verrichten, denn es ist der Versöhnungstag, an dem man euch Sühne vor dem HERRN, eurem Gott, erwirken soll.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 29, 'Denn wer an eben diesem Tage nicht fastet, der soll aus seinen Volksgenossen ausgerottet werden;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 30, 'und wer irgendeine Arbeit an eben diesem Tage verrichtet, einen solchen Menschen will ich aus der Mitte seines Volkes vertilgen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 31, 'Keinerlei Arbeit dürft ihr verrichten; diese Verordnung soll ewige Geltung für eure künftigen Geschlechter in allen euren Wohnsitzen haben.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 32, 'Ein Tag völliger Ruhe soll es für euch sein, und ihr sollt fasten! Am neunten Tage des Monats, am Abend, von einem Abend bis wieder zum Abend, sollt ihr den euch gebotenen Ruhetag halten!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 33, 'Weiter gebot der HERR dem Mose folgendes:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 34, '»Teile den Israeliten folgende Verordnungen mit: Am fünfzehnten Tage desselben siebten Monats findet das (Laub-)Hüttenfest sieben Tage lang zu Ehren des HERRN statt.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 35, 'Am ersten Tage soll eine Festversammlung am Heiligtum stattfinden; da dürft ihr keinerlei Werktagsarbeit verrichten.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 36, 'Sieben Tage hindurch sollt ihr dem HERRN ein Feueropfer darbringen, dann am achten Tage nochmals eine Festversammlung am Heiligtum abhalten und dem HERRN ein Feueropfer darbringen. Es ist dies der Schlußfesttag, an dem ihr keinerlei Werktagsarbeit verrichten dürft.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 37, '»Dies sind die Feste des HERRN, zu denen ihr Festversammlungen am Heiligtum ausrufen sollt, um dem HERRN Feueropfer darzubringen: Brandopfer und Speisopfer, Schlachtopfer und Trankopfer, wie sie für jeden einzelnen Tag geboten sind,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 38, 'abgesehen von den Sabbaten des HERRN und abgesehen von euren Gaben sowie von all euren Gelübdeopfern und abgesehen von all euren freiwilligen Gaben, die ihr dem HERRN darbringen werdet.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 39, '»Jedoch am fünfzehnten Tage des siebten Monats, wenn ihr den Ertrag des Landes eingeerntet habt, sollt ihr das Fest des HERRN sieben Tage lang feiern. Am ersten Tage soll Ruhetag sein und ebenso am achten Tage;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 40, 'und ihr sollt euch am ersten Tage schöne Baumfrüchte holen, Palmenwedel und Zweige von dichtbelaubten Bäumen und von Bachweiden und sollt sieben Tage lang vor dem HERRN, eurem Gott, fröhlich sein.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 41, 'Dies Fest sollt ihr alljährlich sieben Tage lang zu Ehren des HERRN feiern; diese Verordnung hat ewige Geltung für alle eure künftigen Geschlechter: im siebten Monat sollt ihr es feiern.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 42, 'Da sollt ihr sieben Tage lang in (Laub-)Hütten wohnen; alle, die zum Volk Israel gehören, sollen in (Laub-)Hütten wohnen,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 43, 'damit eure künftigen Geschlechter erfahren, daß ich die Kinder Israel habe in Hütten wohnen lassen, als ich sie aus Ägypten wegführte, ich, der HERR, euer Gott.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 44, 'So belehrte Mose die Israeliten über die Festzeiten des HERRN.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 24, 1, 'Weiter gebot der HERR dem Mose folgendes:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 24, 2, '»Gib den Israeliten die Weisung, dir reines Öl von zerstoßenen Oliven für den Leuchter zu bringen, damit beständig Lampen aufgesetzt werden können.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 24, 3, 'Außerhalb des Vorhangs vor der Lade mit dem Gesetz im Offenbarungszelt soll Aaron (den Leuchter) zurichten, damit er vom Abend bis zum Morgen ohne Unterbrechung vor dem HERRN brenne. Diese Verordnung hat ewige Geltung für alle eure künftigen Geschlechter:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 24, 4, 'auf dem Leuchter von reinem Gold soll er die Lampen zu beständigem Brennen vor dem HERRN zurichten.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 24, 5, 'Sodann sollst du Feinmehl nehmen und daraus zwölf Kuchen backen; zwei Zehntel Epha sollen auf jeden Kuchen kommen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 24, 6, 'Du sollst sie dann in zwei Schichten, je sechs in einer Schicht, auf den Tisch von reinem Gold vor dem HERRN auflegen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 24, 7, 'Dann sollst du auf jede Schicht reinen Weihrauch tun, der für das Brot als Duftteil dienen soll, als ein Feueropfer für den HERRN.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 24, 8, 'An jedem Sabbattage soll er (die Brote) regelmäßig so vor dem HERRN aufschichten; zu dieser Leistung sollen die Israeliten für ewige Zeiten verpflichtet sein.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 24, 9, 'Die Brote sollen dann Aaron und seinen Söhnen gehören; die sollen sie an heiliger Stätte verzehren; denn als ein Hochheiliges sollen sie ihm von den Feueropfern des HERRN zuteil werden als eine ewige Gebühr.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 24, 10, 'Der Sohn einer Israelitin – er war aber der Sohn eines Ägypters – begab sich einst unter die Israeliten; da gerieten sie im Lager in Streit miteinander, der Sohn der Israelitin und ein israelitischer Mann.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 24, 11, 'Dabei lästerte der Sohn der Israelitin den Namen (des HERRN) und fluchte dazu; da brachte man ihn vor Mose – seine Mutter aber hieß Selomith und war die Tochter Dibris, vom Stamme Dan.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 24, 12, 'Hierauf legten sie ihn in Gewahrsam, bis Mose ihnen Verhaltungsmaßregeln auf Grund einer Weisung des HERRN gäbe.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 24, 13, 'Da gebot der HERR dem Mose:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 24, 14, '»Laß den Lästerer vor das Lager hinausführen, und alle, die es gehört haben, sollen ihm die Hände fest auf den Kopf legen, und dann soll die ganze Gemeinde ihn steinigen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 24, 15, 'Zu den Israeliten aber sollst du sagen: Wenn jemand seinem Gott flucht, so lädt er Sünde auf sich,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 24, 16, 'und wer den Namen des HERRN lästert, soll unfehlbar mit dem Tode bestraft werden: die ganze Gemeinde soll ihn steinigen; der Fremde wie der Einheimische soll den Tod erleiden, wenn er den Namen (des HERRN) lästert. –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 24, 17, 'Wenn ferner jemand irgendeinen Menschen erschlägt, soll er unfehlbar mit dem Tode bestraft werden;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 24, 18, 'wer aber ein Stück Vieh erschlägt, soll es ersetzen: Leben um Leben.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 24, 19, 'Wenn ferner jemand seinem Nächsten einen Leibesschaden zufügt, so soll man ihm ebenso tun, wie er getan hat:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 24, 20, 'Bruch um Bruch, Auge um Auge, Zahn um Zahn; derselbe Leibesschaden, den er dem andern zugefügt hat, soll auch ihm zugefügt werden.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 24, 21, 'Wer also ein Stück Vieh erschlägt, soll es ersetzen; wer aber einen Menschen erschlägt, soll den Tod erleiden.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 24, 22, 'Das gleiche Recht soll bei euch für den Fremden wie für den Einheimischen gelten; denn ich bin der HERR, euer Gott!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 24, 23, 'Als Mose dies den Israeliten verkündigt hatte, führten sie den Lästerer vor das Lager hinaus und steinigten ihn dort; die Israeliten taten so, wie der HERR dem Mose geboten hatte.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 1, 'Und der HERR gebot dem Mose auf dem Berge Sinai folgendes:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 2, '»Teile den Israeliten folgende Verordnungen mit: Wenn ihr in das Land kommt, das ich euch geben werde, so soll das Land dem HERRN einen Sabbat halten.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 3, 'Sechs Jahre sollst du dein Feld bestellen und sechs Jahre deinen Weinberg beschneiden und den Ertrag des Landes einbringen;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 4, 'aber im siebten Jahre soll das Land einen Sabbat der Ruhe haben, eine dem HERRN geweihte Ruhezeit: da darfst du dein Feld nicht bestellen und deinen Weinberg nicht beschneiden;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 5, 'auch den Wildwuchs deiner (vorjährigen) Ernte darfst du nicht einheimsen und die Trauben von deinem unbeschnittenen Weinstock nicht lesen: es soll ein Sabbatjahr für das Land sein.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 6, 'Was das Land während seiner Ruhezeit von selbst hervorbringt, soll euch zur Nahrung dienen, dir sowie deinen Knechten und Mägden, deinen Tagelöhnern und den Beisassen, die bei dir als Gäste leben;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 7, 'auch deinem Vieh und den wilden Tieren, die in deinem Lande leben, soll der gesamte Ertrag (dieses Jahres) zur Nahrung dienen.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 8, '»Sodann sollst du dir sieben solcher Sabbatjahre, also siebenmal sieben Jahre, abzählen, so daß dir die Zeit der sieben Sabbatjahre neunundvierzig Jahre beträgt.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 9, 'Dann sollst du am zehnten Tage des siebten Monats die Lärmposaune erschallen lassen; am Versöhnungstage sollt ihr die Posaunen überall in eurem Lande erschallen lassen');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 10, 'und so das fünfzigste Jahr heiligen, und sollt im Lande Freiheit für alle seine Bewohner ausrufen: ein Halljahr soll es für euch sein, in dem ein jeder von euch wieder zu seinem Besitz kommen und ein jeder zu seiner Familie zurückkehren soll.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 11, 'Ein Halljahr soll also jedes fünfzigste Jahr für euch sein; da dürft ihr weder säen, noch das, was von selbst gewachsen ist, einernten, noch Trauben von den unbeschnittenen Weinstöcken lesen;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 12, 'denn ein Halljahr ist es: es soll euch heilig sein; vom Felde weg sollt ihr essen, was es von selbst hervorbringt.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 13, 'In solchem Halljahr soll ein jeder von euch wieder zu seinem Besitz kommen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 14, 'Wenn du also deinem Nächsten etwas verkaufst oder von deinem Nächsten etwas kaufst, so sollt ihr einander nicht übervorteilen,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 15, 'sondern nach der Zahl der Jahre, die seit dem (letzten) Halljahr verflossen sind, sollst du von deinem Nächsten kaufen, und nach der Zahl der Erntejahre soll er dir verkaufen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 16, 'Bei einer größeren Zahl von Jahren (bis zum nächsten Halljahr) sollst du den Kaufpreis für ein Grundstück verhältnismäßig erhöhen und bei einer kleineren Zahl von Jahren den Kaufpreis verhältnismäßig verringern; denn er verkauft dir nur eine (bestimmte) Anzahl von Ernten.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 17, 'Keiner übervorteile also den andern, sondern du sollst dich vor deinem Gott fürchten; denn ich bin der HERR, euer Gott.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 18, 'So verfahrt denn nach meinen Anordnungen und beobachtet meine Gebote und handelt nach ihnen, so werdet ihr in eurem Lande in Sicherheit wohnen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 19, 'Dann wird das Land euch seinen Ertrag geben, so daß ihr euch satt essen könnt und in Sicherheit darin wohnt.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 20, 'Wenn ihr aber fragt: ›Wovon sollen wir uns denn im siebten Jahre nähren, wenn wir doch weder säen noch den erforderlichen Ertrag einernten dürfen?‹,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 21, 'so sollt ihr wissen: ich werde euch im sechsten Jahre meinen Segen zuwenden, daß es euch den Ertrag für drei Jahre liefern soll.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 22, 'Obgleich ihr daher erst im achten Jahre säet, werdet ihr doch immer noch von dem früheren Ertrage altes Getreide zu essen haben; bis ins neunte Jahr, bis dessen Ernte eingebracht ist, werdet ihr altes Getreide zu essen haben.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 23, 'Der Landbesitz darf also nicht für immer verkauft werden, denn mir gehört das Land: ihr seid ja nur Fremdlinge und Beisassen bei mir.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 24, 'Daher sollt ihr in dem ganzen Lande, das ihr innehabt, für euren Landbesitz die Wiedereinlösung gestatten.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 25, '»Wenn einer deiner Volksgenossen verarmt und etwas von seinem Grundbesitz verkauft, so soll sein nächster Verwandter als Löser für ihn eintreten und das wieder einlösen dürfen, was sein Verwandter verkauft hat.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 26, 'Wenn ferner jemand keinen Löser hat, aber selbst soviel Geld aufzubringen vermag, als zur Wiedereinlösung seines Besitzes erforderlich ist,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 27, 'so soll er die Jahre, die seit seinem Verkauf verflossen sind, in Anrechnung bringen und das Überschüssige demjenigen zurückzahlen, an den er verkauft hat, damit er so wieder zu seinem Besitz kommt.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 28, 'Wenn er aber nicht soviel Geld aufbringen kann, als zum Rückkauf erforderlich ist, so soll das von ihm verkaufte Grundstück im Besitz des Käufers bis zum Halljahr verbleiben; aber im Halljahr soll es frei werden, so daß er wieder zu seinem Eigentum kommt.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 29, 'Wenn ferner jemand ein Wohnhaus in einer ummauerten Stadt verkauft, so soll das Rückkaufsrecht für ihn bestehen, bis ein Jahr nach dem Verkauf des Hauses vergangen ist: ein volles Jahr soll das Rückkaufsrecht für ihn bestehen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 30, 'Wenn ein Rückkauf aber bis zum Ablauf eines vollen Jahres nicht stattgefunden hat, so soll das Haus, das in einer ummauerten Stadt liegt, dem Käufer und seinen Nachkommen für immer verbleiben: es soll im Halljahr nicht frei werden.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 31, 'Dagegen die Häuser in den Gehöften, die von keiner Mauer umgeben sind, sollen als zum Feldbesitz gehörig angesehen werden: es soll (unbeschränktes) Rückkaufsrecht für sie gelten, und im Halljahr sollen sie frei werden.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 32, 'Was ferner die Städte der Leviten, die Häuser in den Städten betrifft, die ihnen zum Eigentum überwiesen sind, so soll den Leviten ein ewiges Rückkaufsrecht zustehen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 33, 'Wenn jedoch einer von den Leviten sein verkauftes Haus nicht wieder einlöst, so soll es, wenn es in einer ihm zugewiesenen Stadt liegt, im Halljahr wieder frei werden; denn die Häuser in den Städten der Leviten sind ihr Erbbesitz inmitten der Israeliten.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 34, 'Das zu ihren Städten gehörende Weideland aber darf überhaupt nicht verkauft werden, denn es gehört ihnen als ewiges Eigentum.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 35, '»Wenn ferner einer deiner Volksgenossen verarmt, so daß er sich neben dir nicht zu halten vermag, so sollst du ihn unterstützen, so daß er wie ein Fremdling oder Beisasse neben dir lebt.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 36, 'Du darfst nicht Zins und Aufschlag von ihm nehmen, sondern sollst dich vor deinem Gott fürchten, damit dein Bruder neben dir leben kann.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 37, 'Du darfst ihm dein Geld nicht um Zins geben und deine Nahrungsmittel nicht um Aufschlag:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 38, 'ich bin der HERR, euer Gott, der euch aus dem Lande Ägypten geführt hat, um euch das Land Kanaan zu geben und euer Gott zu sein!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 39, 'Wenn ferner einer deiner Volksgenossen neben dir verarmt und sich dir verkauft, so sollst du ihn keine Sklavenarbeit verrichten lassen,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 40, 'nein, wie ein Tagelöhner, wie ein Beisasse soll er bei dir sein: nur bis zum Halljahr soll er bei dir dienen;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 41, 'dann aber soll er frei von dir ausgehen, er und seine Kinder mit ihm, und zu seinem Geschlecht zurückkehren und wieder in den Besitz seiner Väter eintreten.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 42, 'Denn meine Dienstknechte sind sie, die ich aus dem Lande Ägypten herausgeführt habe: sie dürfen nicht wie gewöhnliche Sklaven verkauft werden.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 43, 'Du sollst nicht mit Härte über ihn herrschen, sondern dich vor deinem Gott fürchten!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 44, 'Was aber deine leibeigenen Knechte und Mägde betrifft, die du besitzen wirst, so mögt ihr euch solche Knechte und Mägde von den Heidenvölkern kaufen, die rings um euch her wohnen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 45, 'Auch aus den Kindern der Beisassen, die bei euch als Gäste leben – aus ihnen könnt ihr euch welche kaufen sowie aus ihren Nachkommen, die bei euch leben und die sie in eurem Lande gezeugt haben: diese mögen euch als Eigentum gehören,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 46, 'und ihr könnt sie auf eure Kinder nach euch vererben, damit diese sie als Eigentum besitzen: auf ewig könnt ihr diese als Sklaven dienen lassen. Aber über eure Brüder, die Israeliten – da darfst du nicht, einer über den andern, mit Härte herrschen!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 47, 'Wenn ferner ein Fremdling oder Beisasse neben dir Vermögen erwirbt, während einer deiner Volksgenossen neben ihm verarmt und sich dem Fremdling, dem Beisassen neben dir, oder einem Abkömmling aus der Familie eines Fremdlings als Sklaven verkauft,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 48, 'so soll, nachdem er sich verkauft hat, das Loskaufsrecht für ihn bestehen: einer von seinen Volksgenossen mag ihn loskaufen;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 49, 'oder sein Oheim oder der Sohn seines Oheims mag ihn loskaufen, oder sonst einer von seinen nächsten Blutsverwandten aus seinem Geschlecht darf ihn loskaufen; oder wenn er selbst soviel Geld aufbringt, kann er sich selbst loskaufen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 50, 'Und zwar soll er mit dem, der ihn gekauft hat, die Zeit von dem Jahre ab, wo er sich verkauft hat, bis zum Halljahr berechnen, und der Preis, um den er sich ihm verkauft hat, soll auf die Zahl der Jahre gleichmäßig verteilt werden: wie bei einem Lohnarbeiter soll die Dienstzeit bei ihm berechnet werden.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 51, 'Wenn also der Jahre noch viele (bis zum Halljahr) sind, so soll er diesen entsprechend sein Lösegeld von der Kaufsumme zurückzahlen;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 52, 'wenn aber nur noch wenige Jahre bis zum Halljahr übrig sind, so muß er danach die Berechnung anstellen: nach Maßgabe seiner Dienstjahre hat er sein Lösegeld zurückzuzahlen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 53, 'Wie ein Mietling, der Jahr für Jahr um Lohn arbeitet, soll er bei seinem Herrn sein, und dieser darf ihn vor deinen Augen nicht mit Härte als Herr behandeln.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 54, 'Wird er aber nicht auf diese Weise losgekauft, so soll er im Halljahr frei ausgehen, er und seine Kinder mit ihm.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 55, 'Denn mir gehören die Israeliten als Dienstknechte; meine Dienstknechte sind sie, die ich aus dem Lande Ägypten herausgeführt habe, ich, der HERR, euer Gott!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 1, '»Ihr sollt euch keine Götzen verfertigen und dürft euch keine Schnitzbilder und Malsteine aufrichten, auch keine Steine mit Bildwerk in eurem Lande aufstellen, um euch davor niederzuwerfen; denn ich, der HERR, bin euer Gott!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 2, 'Meine Sabbate sollt ihr beobachten und mein Heiligtum fürchten: ich bin der Herr!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 3, '»Wenn ihr in meinen Satzungen wandelt und meine Gebote beobachtet und nach ihnen tut,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 4, 'so will ich euch Regen zu rechter Zeit geben, damit das Land seinen Ertrag liefert und die Bäume auf dem Felde ihre Früchte spenden.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 5, 'Dann wird die Dreschzeit bei euch bis an die Weinlese reichen und die Weinlese bis an die Saatzeit; und ihr sollt Brot reichlich zu essen haben und sicher in eurem Lande wohnen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 6, 'Dann will ich Frieden im Lande herrschen lassen, daß ihr euch niederlegen könnt, ohne daß jemand euch aufschreckt; auch die wilden Tiere will ich aus dem Lande verschwinden lassen, und kein Schwert soll durch euer Land ziehen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 7, 'Ihr werdet eure Feinde in die Flucht schlagen, und sie sollen vor euch durch das Schwert fallen;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 8, 'fünf von euch sollen hundert in die Flucht schlagen und hundert von euch zehntausend vor sich her treiben, und eure Feinde sollen vor euch durch das Schwert fallen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 9, 'Ich will mich euch gnädig zuwenden, will euch zahlreich werden lassen und euch mehren und meinen Bund mit euch aufrechthalten.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 10, 'Ihr werdet altes Getreide von der vorletzten Ernte zu essen haben und das vorjährige wegschaffen müssen, um für das neue Raum zu schaffen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 11, 'Und ich will meine Wohnung in eurer Mitte aufschlagen, und mein Herz wird keine Abneigung gegen euch hegen,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 12, 'sondern ich will in eurer Mitte wandeln und euer Gott sein, und ihr sollt mein Volk sein.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 13, 'Ich bin der HERR, euer Gott, der euch aus dem Lande Ägypten herausgeführt hat, damit ihr ihnen nicht länger als Knechte dienen solltet; ich habe die Stäbe eures Joches zerbrochen und euch aufrecht einhergehen lassen.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 14, '»Wenn ihr mir aber nicht gehorcht und nicht alle diese Gebote erfüllt,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 15, 'sondern meine Satzungen mißachtet und im Herzen Widerwillen gegen meine Verordnungen hegt, so daß ihr nicht alle meine Gebote befolgt, sondern den Bund mit mir brecht,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 16, 'so will auch ich dementsprechend mit euch verfahren und schreckliche Heimsuchungen über euch verhängen: Schwindsucht und Fieber, daß euch das Augenlicht erlöschen soll und das Leben qualvoll dahinschwindet. Vergebens sollt ihr dann euren Samen aussäen, denn eure Feinde werden ihn verzehren;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 17, 'und ich werde mein Angesicht gegen euch kehren, daß ihr vor euren Feinden die Flucht ergreifen müßt; und eure Widersacher sollen über euch herrschen, und ihr sollt fliehen, auch wenn niemand euch verfolgt.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 18, '»Und wenn ihr mir auch dann noch nicht gehorcht, so will ich euch noch siebenmal härter strafen um eurer Sünden willen;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 19, 'den trotzigen Hochmut werde ich euch dann brechen und will den Himmel über euch hart wie Eisen machen und euren Erdboden wie Erz,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 20, 'so daß eure Kraft und Arbeit sich nutzlos erschöpfen wird; denn euer Land wird euch keinen Ertrag geben und die Bäume auf dem Felde keine Früchte spenden.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 21, '»Und wenn ihr mir auch dann noch widerstrebt und mir nicht gehorchen wollt, so will ich fortfahren, euch noch siebenmal härter um eurer Sünden willen zu schlagen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 22, 'Dann will ich die wilden Tiere gegen euch loslassen, daß sie euch eure Kinder rauben und euer Vieh zerreißen und eure Zahl vermindern, so daß eure Straßen öde werden.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 23, '»Und wenn ihr euch auch dadurch nicht von mir warnen laßt, sondern mir immer noch widerstrebt,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 24, 'so will auch ich euch widerstreben und euch auch meinerseits siebenfach für eure Sünden schlagen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 25, 'Ich will das Schwert über euch kommen lassen, das die Rache für den Bundesbruch vollziehen soll; und wenn ihr euch dann in eure Städte zurückzieht, so werde ich die Pest unter euch senden, und ihr sollt in Feindeshand fallen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 26, 'Wenn ich euch dann noch die Stütze des Brotes zerbreche, so daß zehn Frauen Brot für euch in einem einzigen Ofen backen und sie euch das Brot abgewogen zurückbringen, so werdet ihr essen, ohne satt zu werden.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 27, '»Und wenn ihr mir trotzdem nicht gehorsam seid und mir immer noch widerstrebt,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 28, 'so will auch ich im Grimm euch widerstreben und euch siebenfach für eure Sünden züchtigen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 29, 'Ihr sollt dann das Fleisch eurer eigenen Söhne essen und das Fleisch eurer eigenen Töchter verzehren;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 30, 'und ich werde eure Höhentempel zerstören und eure Sonnensäulen umstürzen; eure Leichname werde ich auf die Leichname eurer Götzen werfen, und mein Herz wird euch verabscheuen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 31, 'Eure Städte will ich in Trümmerstätten verwandeln und eure Heiligtümer verwüsten und euren lieblichen Opferduft nicht mehr riechen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 32, 'Ja, ich selbst werde das Land veröden, so daß eure Feinde, die dort ihren Wohnsitz nehmen, sich darüber entsetzen sollen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 33, 'Euch aber werde ich unter die (heidnischen) Völker zerstreuen und das Schwert hinter euch her zücken; euer Land soll zur Wüste werden und eure Städte zu Schutthaufen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 34, 'Da wird dann das Land seine Ruhezeiten ersetzt bekommen die ganze Zeit hindurch, in der es verwüstet daliegt, während ihr im Lande eurer Feinde weilt; ja, da wird dann das Land Ruhe haben und seine Ruhezeiten nachholen;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 35, 'die ganze Zeit hindurch, in der es verwüstet daliegt, wird es die Ruhe haben, die ihm in den euch gebotenen Ruhezeiten versagt war, als ihr in ihm wohntet.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 36, 'Die aber dann von euch noch übrig sind, denen will ich in den Ländern ihrer Feinde Verzagtheit ins Herz legen, so daß das Rascheln eines verwehten Blattes sie aufschreckt und sie davor fliehen sollen, wie man sonst vor dem Schwerte flieht, und sie fallen sollen, obwohl niemand sie verfolgt.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 37, 'Sie sollen dann einer über den andern hinstürzen, wie wenn es gälte, vor dem Schwerte zu fliehen, obgleich doch niemand sie verfolgt; und es wird für euch kein Standhalten vor euren Feinden geben:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 38, 'ja, ihr sollt unter den Heidenvölkern umkommen, und das Land eurer Feinde soll euch fressen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 39, 'Und diejenigen von euch, die dann noch übrig sind, sollen in den Ländern eurer Feinde infolge ihrer Sündenschuld verschmachten und auch infolge der Sünden ihrer Väter hinschwinden mit ihnen.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 40, '»Da werden sie dann ihre Schuld bekennen und auch die Schuld ihrer Väter infolge ihres Treubruchs, den sie gegen mich begangen haben, und werden auch eingestehen, daß, weil sie mir widerstrebt haben,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 41, 'auch ich ihnen widerstrebt und sie in das Land ihrer Feinde gebracht habe. Wenn alsdann ihr unbeschnittenes Herz sich demütigt und sie dann die Strafe für ihre Verschuldung büßen,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 42, 'so will ich an meinen Bund mit Jakob gedenken und ebenso an meinen Bund mit Isaak und an meinen Bund mit Abraham gedenken und will des Landes gedenken.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 43, 'Jedoch zuvor muß das Land von ihnen verlassen sein und die ihm zukommenden Ruhezeiten vergütet erhalten, solange es nach ihrer Entfernung verödet liegt; und sie selbst müssen die Strafe für ihre Verschuldung erleiden, weil sie ja doch meine Gebote mißachtet und in ihrem Herzen gegen meine Satzungen einen Widerwillen gehegt haben.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 44, 'Aber selbst auch dann, wenn sie sich im Lande ihrer Feinde befinden, will ich sie nicht so verwerfen und keinen solchen Widerwillen gegen sie hegen, daß ich sie ganz vertilge und meinen Bund mit ihnen breche, denn ich bin der HERR, ihr Gott.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 45, 'Nein, zu ihrem Heil will ich meines Bundes mit ihren Vorfahren gedenken, die ich vor den Augen der Heidenvölker aus dem Lande Ägypten weggeführt habe, um ihr Gott zu sein: ich, der HERR.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 46, 'Dies sind die Satzungen, Verordnungen und Weisungen, die der HERR auf dem Berge Sinai zwischen sich und den Israeliten durch Vermittlung Moses gegeben hat.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 1, 'Hierauf gebot der HERR dem Mose folgendes:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 2, '»Teile den Israeliten folgende Verordnungen mit: Wenn jemand dem HERRN ein besonderes Gelübde erfüllen will, und zwar in betreff von Personen nach dem Schätzungswert,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 3, 'so soll der Schätzungswert einer männlichen Person im Alter von zwanzig bis zu sechzig Jahren fünfzig Silberschekel nach dem Gewicht des Heiligtums betragen;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 4, 'ist es aber eine weibliche Person, so soll der Schätzungswert dreißig Schekel betragen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 5, 'Wenn es sich aber um eine Person im Alter von fünf bis zu zwanzig Jahren handelt, so soll der Schätzungswert einer männlichen Person zwanzig Schekel und bei einer weiblichen Person zehn Schekel betragen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 6, 'Bei Kindern aber im Alter von einem Monat bis zu fünf Jahren soll der Schätzungswert eines Knaben fünf Silberschekel und der Schätzungswert eines Mädchens drei Silberschekel betragen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 7, 'Wenn ferner die Person sechzig Jahre alt ist oder darüber, so soll der Schätzungswert, wenn es sich um einen Mann handelt, fünfzehn Schekel betragen, bei einer weiblichen Person dagegen zehn Schekel.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 8, 'Ist der Betreffende aber für die Entrichtung dieses Schätzungswertes zu arm, so stelle man ihn vor den Priester, damit dieser ihn abschätze; nach Maßgabe dessen, was der Gelobende zu leisten vermag, soll der Priester ihn abschätzen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 9, 'Handelt es sich ferner um Vieh, von dem man dem HERRN eine Opfergabe darbringen kann, so soll jedes Stück, das man von solchem Vieh dem HERRN gibt, als geheiligt gelten:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 10, 'man darf es nicht umwechseln noch vertauschen, weder ein gutes Stück gegen ein schlechtes noch ein schlechtes Stück gegen ein gutes; und wenn jemand dennoch ein Stück Vieh gegen ein anderes vertauscht, so soll sowohl jenes als auch das eingetauschte dem Heiligtum verfallen sein.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 11, 'Handelt es sich aber um irgendein Stück unreinen Viehes, von dem man dem HERRN keine Opfergabe darbringen kann, so stelle man das betreffende Stück Vieh vor den Priester;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 12, 'dieser soll es dann abschätzen, je nachdem es gut oder schlecht ist; bei der Abschätzung des Priesters soll es dann sein Bewenden haben.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 13, 'Will der Betreffende es aber einlösen, so hat er noch ein Fünftel zu dem Schätzungswert hinzuzufügen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 14, 'Wenn ferner jemand sein Haus als heilige Gabe dem HERRN weiht, so soll der Priester es abschätzen, je nachdem es gut oder schlecht ist; wie der Priester es abschätzt, so soll der Wert festgesetzt sein.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 15, 'Wenn dann der, welcher sein Haus geweiht hat, es wieder einlösen will, so hat er noch ein Fünftel des Betrags zu dem Schätzungswert hinzuzufügen: dann bleibt es sein Eigentum.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 16, 'Wenn ferner jemand ein Stück von seinem ererbten Grundbesitz dem HERRN weiht, so soll sich der Schätzungswert nach dem Maß der dafür erforderlichen Aussaat richten: ein Homer Gerste Aussaat soll zu fünfzig Silberschekel gerechnet werden.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 17, 'Wenn der Betreffende sein Stück Land vom Halljahr ab weiht, so soll es nach dem vollen Schätzungswert zu stehen kommen;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 18, 'wenn er aber sein Stück Land erst nach dem Halljahr weiht, so soll der Priester ihm den Geldbetrag mit Rücksicht auf die Zahl der Jahre berechnen, die bis zum (nächsten) Halljahr noch ausstehen, so daß also von dem Schätzungswert ein verhältnismäßiger Abzug gemacht wird.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 19, 'Will aber der, welcher das Stück Land geweiht hat, es wieder einlösen, so hat er noch ein Fünftel des Betrages zu dem Schätzungswert hinzuzufügen: dann soll es ihm verbleiben.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 20, 'Hat er aber das Stück Land nicht eingelöst, und er verkauft es trotzdem an einen andern, so kann es nicht mehr eingelöst werden,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 21, 'sondern das Stück Land soll, wenn es im Halljahr frei wird, als dem HERRN geweiht gelten wie ein mit dem Bann belegtes Stück Land: es soll dem Priester als Eigentum gehören.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 22, 'Wenn ferner jemand ein von ihm gekauftes Stück Land, das nicht zu seinem ererbten Grundbesitz gehört, dem HERRN weiht,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 23, 'so soll ihm der Priester den Betrag des Schätzungswertes bis zum (nächsten) Halljahr berechnen, und der Betreffende soll diese Schätzungssumme an demselben Tage als eine dem HERRN geweihte Gabe entrichten.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 24, 'Im Halljahr aber soll das Stück Land wieder an den zurückfallen, von dem er es gekauft hatte, also an den, welchem das Landstück als Erbbesitz zusteht.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 25, 'Jede (priesterliche) Schätzung aber soll nach dem Schekel des Heiligtums erfolgen: der Schekel gilt zwanzig Gera.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 26, '»Jedoch die Erstlinge vom Vieh, die als Erstgeburten dem HERRN an sich schon zustehen, darf niemand weihen; sei es ein Rind oder ein Stück Kleinvieh: es gehört dem HERRN.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 27, 'Wenn es sich aber um eine Erstgeburt von einem unreinen Haustier handelt, so muß der Betreffende sie nach dem Schätzungswert lösen und noch ein Fünftel des Betrags hinzufügen. Wird sie aber nicht gelöst, so soll sie nach dem Schätzungswert verkauft werden.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 28, '»Jedoch alles mit dem Bann Belegte, das jemand von seinem gesamten Besitz dem HERRN mittels des Bannes weiht, es seien Menschen oder Vieh oder Stücke von seinem ererbten Grundbesitz, darf weder verkauft noch eingelöst werden: alles Gebannte ist dem HERRN hochheilig.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 29, 'Handelt es sich dabei um Menschen, die mit dem Bann belegt sind, so dürfen sie nicht losgekauft, sondern müssen unbedingt getötet werden.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 30, '»Ferner sollen alle Zehnten des Landes, vom Saatertrag des Feldes wie von den Früchten der Bäume, dem HERRN gehören: sie sind dem HERRN geweiht.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 31, 'Wenn aber jemand einen Teil von seinem Zehnten einlösen will, so hat er ein Fünftel des Betrags mehr zu bezahlen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 32, 'Was ferner allen Zehnten von Rindern und vom Kleinvieh betrifft, so soll von allen Tieren, die unter dem Hirtenstabe hindurchgehen, immer das zehnte Stück dem HERRN geheiligt sein.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 33, 'Man soll dabei nicht untersuchen, ob es gut oder schlecht sei, und man darf es auch nicht vertauschen; wenn man es aber doch vertauscht, so soll sowohl das betreffende als auch das eingetauschte Tier dem Heiligtum verfallen sein und darf nicht gelöst werden.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 34, 'Dies sind die Gebote, die der HERR dem Mose auf dem Berge Sinai für die Israeliten aufgetragen hat.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 1, 'Hierauf gebot der HERR dem Mose in der Wüste Sinai, im Offenbarungszelt, am ersten Tage des zweiten Monats im zweiten Jahr nach ihrem Auszug aus dem Lande Ägypten folgendes:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 2, '»Nehmt die Kopfzahl der gesamten Gemeinde der Israeliten auf nach ihren Geschlechtern und nach ihren Familien, mit Aufzählung der einzelnen Namen, alle männlichen Personen Kopf für Kopf;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 3, 'von zwanzig Jahren an und darüber, alles, was in Israel zum Heeresdienst tauglich ist, die sollt ihr mustern, Schar für Schar, du und Aaron.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 4, 'Dabei soll euch je ein Mann von jedem Stamm Beistand leisten, nämlich der Obmann der Familien seines Stammes.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 5, 'Und dies sind die Namen der Männer, die euch dabei zur Seite stehen sollen: für Ruben: Elizur, der Sohn Sedeurs;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 6, 'für Simeon: Selumiel, der Sohn Zurisaddais;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 7, 'für Juda: Nahson, der Sohn Amminadabs;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 8, 'für Issaschar: Nethaneel, der Sohn Zuars;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 9, 'für Sebulon: Eliab, der Sohn Helons;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 10, 'für die Söhne Josephs, für Ephraim: Elisama, der Sohn Ammihuds; für Manasse: Gamliel, der Sohn Pedazurs;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 11, 'für Benjamin: Abidan, der Sohn Gideonis;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 12, 'für Dan: Ahieser, der Sohn Ammisaddais;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 13, 'für Asser: Pagiel, der Sohn Ochrans;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 14, 'für Gad: Eljasaph, der Sohn Deguels;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 15, 'für Naphthali: Ahira, der Sohn Enans.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 16, 'Dies waren die aus der Gemeinde Berufenen, die Fürsten ihrer väterlichen Stämme, die Häupter der Tausendschaften Israels.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 17, 'Hierauf ließen Mose und Aaron diese Männer, die ihnen mit Namen bezeichnet worden waren, zu sich kommen');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 18, 'und versammelten dann die ganze Gemeinde am ersten Tage des zweiten Monats. Da ließen sie sich in die Geburtsverzeichnisse eintragen nach ihren Geschlechtern und nach ihren Familien, mit Aufzählung der einzelnen Namen, von zwanzig Jahren an und darüber, Kopf für Kopf;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 19, 'wie der HERR dem Mose geboten hatte, so musterte er sie in der Wüste Sinai.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 20, 'Es beliefen sich aber die Nachkommen Rubens, des erstgeborenen Sohnes Israels, ihre Abkömmlinge nach ihren Geschlechtern und nach ihren Familien, nach der Zahl der einzelnen Namen, Kopf für Kopf, alle männlichen Personen von zwanzig Jahren an und darüber, alles, was zum Heeresdienst tauglich war,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 21, 'soviele ihrer vom Stamme Ruben gemustert wurden, auf 46500.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 22, 'Bei den Nachkommen Simeons beliefen sich ihre Abkömmlinge nach ihren Geschlechtern und nach ihren Familien, [seine Gemusterten] nach der Zahl der einzelnen Namen, Kopf für Kopf, alle männlichen Personen von zwanzig Jahren an und darüber, alles, was zum Heeresdienst tauglich war,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 23, 'soviele ihrer vom Stamme Simeon gemustert wurden, auf 59300.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 24, 'Bei den Nachkommen Gads beliefen sich ihre Abkömmlinge nach ihren Geschlechtern und nach ihren Familien, nach der Zahl der einzelnen Namen, von zwanzig Jahren an und darüber, alles, was zum Heeresdienst tauglich war,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 25, 'soviele ihrer vom Stamme Gad gemustert wurden, auf 45650.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 26, 'Bei den Nachkommen Judas beliefen sich ihre Abkömmlinge nach ihren Geschlechtern und nach ihren Familien, nach der Zahl der einzelnen Namen, von zwanzig Jahren an und darüber, alles, was zum Heeresdienst tauglich war,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 27, 'soviele ihrer vom Stamme Juda gemustert wurden, auf 74600.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 28, 'Bei den Nachkommen Issaschars beliefen sich ihre Abkömmlinge nach ihren Geschlechtern und nach ihren Familien, nach der Zahl der einzelnen Namen, von zwanzig Jahren an und darüber, alles, was zum Heeresdienst tauglich war,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 29, 'soviele ihrer vom Stamme Issaschar gemustert wurden, auf 54400.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 30, 'Bei den Nachkommen Sebulons beliefen sich ihre Abkömmlinge nach ihren Geschlechtern und nach ihren Familien, nach der Zahl der einzelnen Namen, von zwanzig Jahren an und darüber, alles, was zum Heeresdienst tauglich war,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 31, 'soviele ihrer vom Stamme Sebulon gemustert wurden, auf 57400.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 32, 'Was die Nachkommen Josephs betrifft, so beliefen sich bei den Nachkommen Ephraims ihre Abkömmlinge nach ihren Geschlechtern und nach ihren Familien, nach der Zahl der einzelnen Namen, von zwanzig Jahren an und darüber, alles, was zum Heeresdienst tauglich war,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 33, 'soviele ihrer vom Stamme Ephraim gemustert wurden, auf 40500.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 34, 'Bei den Nachkommen Manasses beliefen sich ihre Abkömmlinge nach ihren Geschlechtern und nach ihren Familien, nach der Zahl der einzelnen Namen, von zwanzig Jahren an und darüber, alles, was zum Heeresdienst tauglich war,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 35, 'soviele ihrer vom Stamme Manasse gemustert wurden, auf 32200.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 36, 'Bei den Nachkommen Benjamins beliefen sich ihre Abkömmlinge nach ihren Geschlechtern und nach ihren Familien, nach der Zahl der einzelnen Namen, von zwanzig Jahren an und darüber, alles, was zum Heeresdienst tauglich war,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 37, 'soviele ihrer vom Stamme Bejamin gemustert wurden, auf 35400.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 38, 'Bei den Nachkommen Dans beliefen sich ihre Abkömmlinge nach ihren Geschlechtern und nach ihren Familien, nach der Zahl der einzelnen Namen, von zwanzig Jahren an und darüber, alles, was zum Heeresdienst tauglich war,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 39, 'soviele ihrer vom Stamme Dan gemustert wurden, auf 62700.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 40, 'Bei den Nachkommen Assers beliefen sich ihre Abkömmlinge nach ihren Geschlechtern und nach ihren Familien, nach der Zahl der einzelnen Namen, von zwanzig Jahren an und darüber, alles, was zum Heeresdienst tauglich war,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 41, 'soviele ihrer vom Stamme Asser gemustert wurden, auf 41500.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 42, 'Bei den Nachkommen Naphthalis beliefen sich ihre Abkömmlinge nach ihren Geschlechtern und nach ihren Familien, nach der Zahl der einzelnen Namen, von zwanzig Jahren an und darüber, alles, was zum Heeresdienst tauglich war,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 43, 'soviele ihrer vom Stamme Naphthali gemustert wurden, auf 53400.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 44, 'Dies sind die Gemusterten, die Mose und Aaron mit den Fürsten der Israeliten musterten; die letzteren waren zwölf Männer, und zwar je ein Mann für die zu seinem Stamm gehörigen Familien.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 45, 'Und es beliefen sich alle, die von den Israeliten nach ihren Familien, von zwanzig Jahren an und darüber, gemustert worden waren, alles, was in Israel zum Heeresdienst tauglich war –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 46, 'es beliefen sich also alle Gemusterten auf 603550.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 47, 'Die Leviten aber nach ihrem väterlichen Stamm waren in dieser Musterung nicht inbegriffen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 48, 'Der HERR hatte nämlich dem Mose folgendes geboten:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 49, '»Nur die zum Stamm Levi Gehörigen sollst du nicht mustern und ihre Kopfzahl nicht mit den übrigen Israeliten aufnehmen;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 50, 'sondern bestelle du die Leviten zum Dienst an der Wohnung des Gesetzes und über ihre sämtlichen Geräte und über alles, was zu ihr gehört: sie sollen die Wohnung und ihre sämtlichen Geräte tragen, und sie sollen den Dienst an ihr versehen und rings um die Wohnung her lagern.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 51, 'Und wenn die Wohnung weiter wandert, sollen die Leviten sie abbrechen; und wenn die Wohnung halt macht, sollen die Leviten sie aufschlagen; jeder Nichtzugehörige aber, der an sie herantritt, soll sterben.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 52, 'Und die übrigen Israeliten sollen nach ihren Heerscharen ein jeder auf seinem Lagerplatz und ein jeder bei seiner Fahne lagern;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 53, 'die Leviten aber sollen rings um die Wohnung des Gesetzes her lagern, damit kein Zorn Gottes über die Gemeinde der Israeliten hereinbricht. Die Leviten sollen also den Dienst an der Wohnung des Gesetzes versehen.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 54, 'So machten denn die Israeliten alles genau so, wie der HERR dem Mose geboten hatte.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 1, 'Weiter gebot der HERR dem Mose und Aaron folgendes:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 2, '»Die Israeliten sollen ein jeder bei seinem Panier, bei den Feldzeichen ihrer Stämme, lagern; dem Offenbarungszelt gegenüber sollen sie ringsum lagern.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 3, 'Und zwar sollen folgende ostwärts gegen Sonnenaufgang lagern: das Panier des Lagers Judas nach seinen Heerscharen, und als Anführer des Stammes Juda Nahson, der Sohn Amminadabs;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 4, 'sein Heer beläuft sich auf 74600 gemusterte Männer.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 5, 'Neben ihm soll der Stamm Issaschar lagern, und als Anführer des Stammes Issaschar Nethaneel, der Sohn Zuars;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 6, 'sein Heer beläuft sich auf 54400 gemusterte Männer.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 7, 'Ferner der Stamm Sebulon, und als Anführer des Stammes Sebulon Eliab, der Sohn Helons;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 8, 'sein Heer beläuft sich auf 57400 gemusterte Männer.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 9, 'Alle Gemusterten im Lager Judas machen nach ihren Heerscharen 186400 Mann aus: sie sollen (beim Abmarsch) zuerst aufbrechen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 10, 'Das Panier des Lagers Rubens soll südwärts nach seinen Heerscharen lagern, und als Anführer des Stammes Ruben Elizur, der Sohn Sedeurs;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 11, 'sein Heer beläuft sich auf 46500 gemusterte Männer.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 12, 'Neben ihm soll der Stamm Simeon lagern, und als Anführer des Stammes Simeon Selumiel, der Sohn Zurisaddais;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 13, 'sein Heer beläuft sich auf 59300 gemusterte Männer.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 14, 'Ferner der Stamm Gad, und als Anführer des Stammes Gad Eljasaph, der Sohn Reguels;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 15, 'sein Heer beläuft sich auf 45650 gemusterte Männer.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 16, 'Alle Gemusterten im Lager Rubens machen nach ihren Heerscharen 151450 Mann aus: sie sollen an zweiter Stelle aufbrechen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 17, 'Dann soll das Offenbarungszelt, das Lager der Leviten, in der Mitte der übrigen Lager aufbrechen; wie sie gelagert sind, so sollen sie aufbrechen, ein jeder an seiner Stelle, nach ihren Panieren.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 18, 'Das Panier des Lagers Ephraims soll nach seinen Heerscharen westwärts lagern, und als Anführer des Stammes Ephraim Elisama, der Sohn Ammihuds;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 19, 'sein Heer beläuft sich auf 40500 gemusterte Männer.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 20, 'Neben ihm soll sich der Stamm Manasse lagern, und als Anführer des Stammes Manasse Gamliel, der Sohn Pedazurs;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 21, 'sein Heer beläuft sich auf 32200 gemusterte Männer.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 22, 'Ferner der Stamm Benjamin, und als Anführer des Stammes Benjamin Abidan, der Sohn Gideonis;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 23, 'sein Heer beläuft sich auf 35400 gemusterte Männer.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 24, 'Alle Gemusterten im Lager Ephraims machen nach ihren Heerscharen 108100 Mann aus: sie sollen an dritter Stelle aufbrechen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 25, 'Das Panier des Lagers Dans soll nordwärts nach seinen Heerscharen lagern, und als Anführer des Stammes Dan Ahieser, der Sohn Ammisaddais;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 26, 'sein Heer beläuft sich auf 62700 gemusterte Männer.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 27, 'Neben ihm soll der Stamm Asser lagern, und als Anführer des Stammes Asser Pagiel, der Sohn Ochrans;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 28, 'sein Heer beläuft sich auf 41500 gemusterte Männer.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 29, 'Ferner der Stamm Naphthali, und als Anführer des Stammes Naphthali Ahira, der Sohn Enans;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 30, 'sein Heer beläuft sich auf 53400 gemusterte Männer.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 31, 'Alle Gemusterten im Lager Dans machen 157600 Mann aus: sie sollen zuletzt nach ihren Panieren aufbrechen.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 32, 'Dies sind die Gemusterten der Israeliten nach ihren Stämmen; sämtliche Gemusterte der einzelnen Lager nach ihren Heerscharen beliefen sich auf 603550 Mann.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 33, 'Die Leviten aber waren in dieser Musterung der Israeliten nicht inbegriffen, wie der HERR dem Mose geboten hatte.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 34, 'So taten denn die Israeliten genau so, wie der HERR dem Mose geboten hatte: also lagerten sie nach ihren Panieren, und also brachen sie auf ein jeder nach seinem Geschlecht bei seiner Familie.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 1, 'Dies sind die Nachkommen Aarons [und Moses] zu der Zeit, als der HERR mit Mose auf dem Berge Sinai redete.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 2, 'Und zwar sind dies die Namen der Söhne Aarons: der Erstgeborene war Nadab, sodann Abihu, Eleasar und Ithamar.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 3, 'Dies sind die Namen der Söhne Aarons, der gesalbten Priester, die in ihr Amt eingesetzt worden waren, um den Priesterdienst zu verrichten.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 4, 'Aber Nadab und Abihu starben (im Dienst) vor dem HERRN, als sie in der Wüste Sinai ein ungehöriges Feueropfer vor dem HERRN darbrachten, und hatten keine Söhne. So versahen denn Eleasar und Ithamar den Priesterdienst unter der Aufsicht ihres Vaters Aaron.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 5, 'Der HERR gebot aber dem Mose folgendes:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 6, '»Laß den Stamm Levi herantreten und stelle ihn vor den Priester Aaron, damit sie ihm Dienste leisten;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 7, 'denn sie sollen alles das besorgen, was ihm und was der ganzen Gemeinde vor dem Offenbarungszelt zu beobachten obliegt, so daß sie den Dienst an der heiligen Wohnung verrichten.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 8, 'Sie sollen also die sämtlichen Geräte des Offenbarungszeltes und alles besorgen, was den Israeliten zu besorgen obliegt, und so den Dienst an der heiligen Wohnung versehen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 9, 'Du sollst also die Leviten dem Aaron und seinen Söhnen beigeben; ganz zu eigen sollen sie ihm von seiten der Israeliten überwiesen sein.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 10, 'Aaron aber und seine Söhne sollst du dazu bestellen, daß sie ihres Priesteramts warten; ein Unbefugter aber, der das Amt ausübt, soll sterben.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 11, 'Weiter sagte der HERR zu Mose folgendes:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 12, '»Wisse wohl: ich selbst habe die Leviten aus der Mitte der Israeliten herausgenommen als Ersatz für alle Erstgeborenen, als Ersatz für alle Kinder, die unter den Israeliten zuerst zur Welt gekommen sind, damit die Leviten mir gehören.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 13, 'Denn mir gehören alle Erstgeborenen; an dem Tage, als ich alle Erstgeburten im Lande Ägypten sterben ließ, habe ich mir alles Erstgeborene in Israel geweiht sowohl von Menschen als auch von Tieren: mir sollen sie gehören, mir, dem HERRN.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 14, 'Hierauf gebot der HERR dem Mose in der Wüste Sinai folgendes:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 15, '»Mustere die Leviten nach ihren Familien und nach ihren Geschlechtern; alle männlichen Personen von einem Monat an und darüber sollst du bei ihnen mustern.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 16, 'Da nahm Mose nach dem Befehl des HERRN die Musterung bei ihnen vor, wie ihm geboten worden war.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 17, 'Und dies waren die Söhne Levis mit ihren Namen: Gerson, Kehath und Merari.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 18, 'Und dies sind die Namen der Söhne Gersons nach ihren Geschlechtern: Libni und Simei;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 19, 'und die Söhne Kehaths nach ihren Geschlechtern: Amram und Jizhar, Hebron und Ussiel;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 20, 'und die Söhne Meraris nach ihren Geschlechtern: Mahli und Musi. Das sind die Geschlechter der Leviten nach ihren Familien.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 21, 'Von Gerson stammt also das Geschlecht der Libniten und das Geschlecht der Simeiten; dies sind die Geschlechter der Gersoniten.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 22, 'Ihre Gemusterten, nach der Zahl aller männlichen Personen bei ihnen von einem Monat an und darüber, beliefen sich auf 7500.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 23, 'Die Geschlechter der Gersoniten lagerten hinter der heiligen Wohnung gegen Westen;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 24, 'und der Fürst des Hauses der Gersoniten war Eljasaph, der Sohn Laels.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 25, 'Die Dienstleistung der Gersoniten im Offenbarungszelt betraf die heilige Wohnung und das Zeltdach, seine Überdecke und den Vorhang am Eingang des Offenbarungszeltes,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 26, 'ferner die Umhänge des Vorhofs und den Vorhang am Eingang des Vorhofs, der die heilige Wohnung und den Altar rings umgab, sowie die zugehörigen Seile nebst allem, was es dabei zu tun gab.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 27, 'Von Kehath stammt das Geschlecht der Amramiten sowie das Geschlecht der Jizhariten, das Geschlecht der Hebroniten und das Geschlecht der Ussieliten: dies sind die Geschlechter der Kehathiten.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 28, 'Ihre Gemusterten, nach der Zahl aller männlichen Personen von einem Monat an und darüber, beliefen sich auf 8600, denen der Dienst im Heiligtum oblag.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 29, 'Die Geschlechter der Kehathiten lagerten an der südlichen Längsseite der heiligen Wohnung;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 30, 'und das Familienoberhaupt der Geschlechter der Kehathiten war Elizaphan, der Sohn Ussiels.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 31, 'Ihre Dienstleistung betraf die Lade und den Tisch, den Leuchter, die Altäre, die heiligen Geräte, die beim Dienst gebraucht wurden, ferner den Vorhang (vor dem Allerheiligsten) nebst allem, was es dabei zu tun gab.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 32, 'Das Oberhaupt der Levitenoberhäupter aber war Eleasar, der Sohn des Priesters Aaron; er hatte die Aufsicht über die, welche Dienste am Heiligtum zu leisten hatten.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 33, 'Von Merari stammte das Geschlecht der Mahliten und das Geschlecht der Musiten; dies sind die Geschlechter Meraris.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 34, 'Ihre Gemusterten, nach der Zahl aller männlichen Personen von einem Monat an und darüber, beliefen sich auf 6200.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 35, 'Das Familienoberhaupt der Geschlechter Meraris war Zuriel, der Sohn Abihails. Sie lagerten an der nördlichen Längsseite der heiligen Wohnung;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 36, 'und die Dienstleistung der Merariten betraf die Bretter der heiligen Wohnung sowie ihre Riegel, ihre Säulen und Füße nebst allen zugehörigen Geräten und allem, was es dabei zu tun gab,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 37, 'ferner die Säulen des Vorhofs ringsum nebst ihren Füßen, ihren Pflöcken und Seilen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 38, 'Diejenigen aber, welche vor der heiligen Wohnung nach Osten hin, vor dem Offenbarungszelt gegen Sonnenaufgang, lagerten, waren Mose und Aaron mit seinen Söhnen, die den Dienst am Heiligtum zu verrichten hatten, nämlich alles das, was den Israeliten dabei zu besorgen oblag. – Der Unbefugte aber, der den Dienst ausübte, sollte sterben.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 39, 'Die Kopfzahl sämtlicher Leviten, die Mose und Aaron auf Befehl des HERRN nach ihren Geschlechtern gemustert hatten, alle männlichen Personen von einem Monat an und darüber, belief sich auf 22000.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 40, 'Weiter gebot der HERR dem Mose: »Mustere nun auch alle männlichen Erstgeborenen bei den Israeliten von einem Monat an und darüber und nimm die Zahl ihrer Namen auf.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 41, 'Du sollst aber die Leviten für mich, den HERRN, als Ersatz für alle Erstgeborenen unter den Israeliten nehmen und ebenso das Vieh der Leviten als Ersatz für alle Erstgeburten unter dem Vieh der Israeliten.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 42, 'So musterte denn Mose alle Erstgeborenen unter den Israeliten, wie der HERR ihm geboten hatte;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 43, 'und es belief sich die Gesamtzahl der männlichen Erstgeborenen, nach der Zahl der Namen von einem Monat an und darüber, soviele ihrer gemustert waren, auf 22273.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 44, 'Hierauf gebot der HERR dem Mose folgendes:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 45, '»Nimm die Leviten als Ersatz für alle Erstgeborenen unter den Israeliten und das Vieh der Leviten als Ersatz für das Vieh jener, damit die Leviten mir gehören, mir, dem HERRN.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 46, 'Was aber den Loskauf der 273 israelitischen Erstgeborenen betrifft, welche über die Zahl der Leviten überschüssig sind,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 47, 'so sollst du fünf Schekel für jeden Kopf erheben; nach dem Gewicht des Heiligtums sollst du sie erheben, den Schekel zu zwanzig Gera gerechnet.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 48, 'Dies Geld sollst du als Lösegeld für die, welche überzählig bei ihnen sind, Aaron und seinen Söhnen übergeben.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 49, 'So erhob denn Mose das Loskaufgeld von denen, welche über die durch die Leviten Ausgelösten überzählig waren;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 50, 'von den Erstgeborenen der Israeliten erhob er das Geld, 1365 Schekel, nach dem Gewicht des Heiligtums.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 51, 'Dann übergab Mose das Lösegeld dem Aaron und seinen Söhnen nach dem Befehl des HERRN, wie der HERR dem Mose geboten hatte.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 1, 'Hierauf gebot der HERR dem Mose und Aaron folgendes:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 2, '»Nehmt unter den Leviten die Kopfzahl der Kehathiten nach ihren Geschlechtern und nach ihren Familien auf,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 3, 'von dreißig Jahren an und darüber bis zu fünfzig Jahren, alle, die zum Dienst tauglich sind, so daß sie am Offenbarungszelt tätig sein können.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 4, 'Dies soll der Dienst der Kehathiten am Offenbarungszelt sein: (die Sorge für) das Hochheilige.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 5, 'Wenn nämlich das Lager aufbricht, sollen Aaron und seine Söhne hineingehen und den abschließenden Vorhang abnehmen und die Gesetzeslade mit ihm bedecken.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 6, 'Dann sollen sie eine Decke von Seekuhfell darauflegen und ein ganz aus blauem Purpur bestehendes Tuch oben darüberbreiten und dann die zugehörigen Tragstangen anlegen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 7, 'Auch über den Schaubrottisch sollen sie ein Tuch von blauem Purpur breiten und die Schüsseln, Schalen und Becher sowie die Kannen für das Trankopfer daraufstellen; auch das regelmäßig aufzulegende Brot soll sich auf ihm befinden.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 8, 'Dann sollen sie über das alles ein Tuch von Karmesin breiten, dieses mit einer Decke von Seekuhfell überdecken und dann die zugehörigen Tragstangen anlegen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 9, 'Hierauf sollen sie ein Tuch von blauem Purpur nehmen und den lichtspendenden Leuchter damit überdecken samt den zugehörigen Lampen, Lichtputzscheren, Näpfen und allen Ölgefäßen, mit denen man ihn zu bedienen pflegt;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 10, 'dann sollen sie ihn nebst allen seinen Geräten in eine Decke von Seekuhfell tun und auf die Tragbahre legen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 11, 'Auch über den goldenen Altar sollen sie ein Tuch von blauem Purpur breiten und ihn mit einer Decke von Seekuhfell überdecken und die zugehörigen Tragstangen anlegen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 12, 'Weiter sollen sie alle für den Dienst erforderlichen Geräte, mit denen man den Dienst im Heiligtum zu verrichten pflegt, nehmen, sie in ein Tuch von blauem Purpur tun, sie dann mit einer Decke von Seekuhfell überdecken und auf die Tragbahre legen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 13, 'Hierauf sollen sie den (Brandopfer-) Altar von der Fettasche reinigen und ein Tuch von rotem Purpur über ihn breiten;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 14, 'auf dieses sollen sie dann alle zugehörigen Geräte legen, mit denen man den Dienst auf ihm zu verrichten pflegt: die Kohlenpfannen, Gabeln, Schaufeln, Becken, überhaupt alle zum Altar gehörigen Geräte; darüber sollen sie eine Decke von Seekuhfell breiten und die zugehörigen Tragstangen anlegen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 15, 'Wenn dann Aaron und seine Söhne beim Aufbruch des Lagers mit der Einhüllung des Heiligen und aller heiligen Geräte fertig sind, so sollen danach die Kehathiten kommen, um alles zu tragen; sie dürfen aber die heiligen Gegenstände nicht berühren, sonst würden sie sterben. Dies ist es, was die Kehathiten vom Offenbarungszelt zu tragen haben.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 16, 'Eleasar aber, dem Sohne des Priesters Aaron, ist das Öl für den Leuchter und das wohlriechende Räucherwerk sowie das regelmäßige Speisopfer und das Salböl anvertraut, ferner die Aufsicht über die ganze heilige Wohnung und über alles das, was sich an heiligen Gegenständen und an zugehörigen Geräten in ihr befindet.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 17, 'Hierauf gebot der HERR dem Mose und Aaron folgendes:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 18, '»Laßt den Stamm der Geschlechter der Kehathiten nicht aus der Mitte der Leviten der Vernichtung anheimfallen,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 19, 'sondern tut folgendes für sie, damit sie am Leben bleiben und nicht sterben müssen, wenn sie an die hochheiligen Gegenstände herantreten: Aaron und seine Söhne sollen hineingehen und jeden einzelnen von ihnen anstellen, um das zu verrichten und das zu tragen, was ihm obliegt;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 20, 'aber sie selbst sollen nicht hineingehen, um auch nur einen Augenblick die heiligen Gegenstände anzusehen; sonst müssen sie sterben.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 21, 'Weiter gebot der HERR dem Mose folgendes:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 22, '»Nimm nun auch die Kopfzahl der Gersoniten nach ihren Familien und nach ihren Geschlechtern auf;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 23, 'von dreißig Jahren an und darüber bis zu fünfzig Jahren sollst du sie mustern, alle, die zum Dienst tauglich sind, so daß sie Verwendung bei den Verrichtungen am Offenbarungszelt finden können.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 24, 'Darin soll der Dienst der Geschlechter der Gersoniten bezüglich der ihnen obliegenden Verrichtungen und der zu tragenden Gegenstände bestehen:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 25, 'sie haben die Teppiche der heiligen Wohnung und das Offenbarungszelt zu tragen, auch seine Decke und die Decke von Seekuhfell, die oben darüber liegt, sowie den Vorhang am Eingang zum Offenbarungszelt,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 26, 'ferner die Umhänge des Vorhofes, und den Vorhang am Eingangstor des Vorhofes, der die heilige Wohnung und den Brandopferaltar rings umgibt, samt den zugehörigen Seilen und allen Geräten, die zu diesem Dienst nötig sind; überhaupt alles, was dabei zu tun ist, sollen sie besorgen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 27, 'Nach der Anordnung Aarons und seiner Söhne soll der ganze Dienst der [Söhne der] Gersoniten vor sich gehen bei allem, was sie zu tragen, und bei allem, was sie zu verrichten haben; und zwar sollt ihr ihnen alles, was sie zu tragen haben, Stück für Stück überweisen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 28, 'Dies ist der Dienst, den die Geschlechter der [Söhne der] Gersoniten am Offenbarungszelt zu verrichten haben; und die Aufsicht über ihre Verrichtungen soll Ithamar, dem Sohn des Priesters Aaron, obliegen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 29, 'Auch die Merariten sollst du nach ihren Geschlechtern und nach ihren Familien mustern;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 30, 'von dreißig Jahren an und darüber bis zu fünfzig Jahren sollst du sie mustern, alle, die zum Dienst tauglich sind, so daß sie Verwendung bei den Verrichtungen am Offenbarungszelt finden können.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 31, 'Und dies ist es, was ihnen zu tragen obliegt und worin ihr ganzer Dienst am Offenbarungszelt besteht: die Bretter der heiligen Wohnung sowie ihre Riegel, Säulen und Füße,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 32, 'ferner die Säulen rings um den Vorhof samt ihren Füßen, ihren Pflöcken und Seilen, samt allen zugehörigen Geräten und nebst allem, was es dabei zu tun gibt; und zwar sollt ihr ihnen die Geräte, deren Fortschaffung ihnen obliegt, Stück für Stück zuweisen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 33, 'Dies ist der Dienst der Geschlechter der Merariten, alles, was sie am Offenbarungszelt unter der Aufsicht Ithamars, des Sohnes des Priesters Aaron, zu verrichten haben.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 34, 'So musterten denn Mose und Aaron samt den Stammesfürsten der Gemeinde die [Söhne der] Kehathiten nach ihren Geschlechtern und nach ihren Familien,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 35, 'von dreißig Jahren an und darüber bis zu fünfzig Jahren, alle, die zum Dienst tauglich waren, so daß sie Verwendung bei den Verrichtungen am Offenbarungszelt finden konnten.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 36, 'Und es belief sich die Zahl derer, welche aus ihnen nach ihren Geschlechtern gemustert wurden, auf 2750.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 37, 'So viele waren die aus den Geschlechtern der Kehathiten Gemusterten, alle, welche Dienste am Offenbarungszelte zu leisten hatten und welche Mose und Aaron nach dem durch Mose übermittelten Befehl des HERRN gemustert hatten.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 38, 'Was sodann diejenigen betrifft, welche aus den Gersoniten nach ihren Geschlechtern und nach ihren Familien gemustert wurden,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 39, 'von dreißig Jahren an und darüber bis zu fünfzig Jahren, alle, die zum Dienst tauglich waren, so daß sie Verwendung bei den Verrichtungen am Offenbarungszelt finden konnten,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 40, 'so belief sich die Zahl derer, welche aus ihnen nach ihren Geschlechtern und nach ihren Familien gemustert wurden, auf 2630.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 41, 'So viele waren die aus den Geschlechtern der Gersoniten Gemusterten, alle, welche Dienste am Offenbarungszelt zu leisten hatten und welche Mose und Aaron nach dem Befehl des HERRN gemustert hatten.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 42, 'Was ferner diejenigen betrifft, welche aus den Geschlechtern der Merariten nach ihren Geschlechtern und nach ihren Familien gemustert wurden,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 43, 'von dreißig Jahren an und darüber bis zu fünfzig Jahren, alle, die zum Dienst tauglich waren, so daß sie Verwendung bei den Verrichtungen am Offenbarungszelt finden konnten,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 44, 'so beliefen sich die, welche aus ihnen nach ihren Geschlechtern gemustert wurden, auf 3200.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 45, 'So viele waren die aus den Geschlechtern der Merariten Gemusterten, welche Mose und Aaron nach dem durch Mose übermittelten Befehl des HERRN gemustert hatten.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 46, 'Was aber die Gesamtzahl der gemusterten Leviten betrifft, welche Mose und Aaron samt den Stammesfürsten der Israeliten nach ihren Geschlechtern und nach ihren Familien gemustert hatten,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 47, 'von dreißig Jahren an und darüber bis zu fünfzig Jahren, alle, welche tauglich waren, um bei den Dienstleistungen und bei der Verrichtung des Tragens Verwendung am Offenbarungszelt zu finden,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 48, 'so belief sich die Zahl der aus ihnen Gemusterten auf 8580.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 49, 'Nach dem durch Mose übermittelten Befehl des HERRN wies man dem einzelnen von ihnen das zu, was er zu verrichten und zu tragen hatte; und sie wurden so angestellt, wie es der HERR dem Mose geboten hatte.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 1, 'Weiter gebot der HERR dem Mose folgendes:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 2, '»Befiehl den Israeliten, daß sie alle Aussätzigen und alle mit einem Ausfluß Behafteten sowie alle, die sich an einer Leiche verunreinigt haben, aus dem Lager entfernen;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 3, 'sowohl Männer als Weiber sollt ihr hinausschaffen, vor das Lager hinaus sollt ihr sie schaffen, damit sie ihre Lager nicht verunreinigen, da doch ich in deren Mitte wohne.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 4, 'Da taten die Israeliten so und schafften sie vor das Lager hinaus; wie der HERR dem Mose geboten hatte, so taten die Israeliten.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 5, 'Weiter gebot der HERR dem Mose folgendes:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 6, '»Teile den Israeliten folgende Verordnungen mit: Wenn ein Mann oder ein Weib irgendeine von den mannigfachen Sünden begeht, wie Menschen sie zu begehen pflegen, so daß sie eine Veruntreuung gegen den HERRN verüben und der Betreffende dadurch eine Verschuldung auf sich lädt,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 7, 'so sollen sie die Sünde, die sie begangen haben, bekennen, und der Betreffende soll das von ihm Veruntreute nach seinem vollen Wert zurückerstatten und noch ein Fünftel des Betrags hinzufügen und es dem geben, an dem er sich verschuldet hat.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 8, 'Wenn dieser Mann aber keinen nächsten Verwandten hat, dem der Ersatz geleistet werden könnte, so soll die Buße, die dem HERRN zu erstatten ist, dem Priester gehören, abgesehen von dem Sühnewidder, mittels dessen man ihm Sühne erwirkt.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 9, 'Ebenso soll jede Hebe von allen heiligen Gaben, welche die Israeliten dem Priester bringen, diesem gehören.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 10, 'Ihm sollen also die heiligen Gaben eines jeden gehören: was irgend jemand dem Priester gibt, soll diesem gehören.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 11, 'Weiter gebot der HERR dem Mose folgendes:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 12, '»Teile den Israeliten folgende Verordnungen mit: Wenn jemandes Ehefrau sich vergeht und ihrem Manne untreu wird,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 13, 'so daß ein anderer fleischlichen Umgang mit ihr hat, ohne daß jedoch ihr Mann etwas davon weiß, und ihr tatsächlicher Ehebruch unentdeckt geblieben ist, auch kein Zeuge gegen sie da ist, weil man sie bei der Tat nicht ertappt hat,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 14, 'es kommt nun aber der Geist der Eifersucht über den Mann, so daß er auf seine Frau, die sich wirklich vergangen hat, eifersüchtig wird – oder auch es kommt der Geist der Eifersucht über den Mann, so daß er auf seine Frau eifersüchtig wird, ohne daß sie sich tatsächlich vergangen hat –:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 15, 'so soll der Mann seine Frau zum Priester bringen und zugleich die ihrethalben erforderliche Opfergabe mitbringen, nämlich ein Zehntel Epha Gerstenmehl; doch darf er kein Öl darübergießen und keinen Weihrauch darauftun, denn es ist ein Speisopfer der Eifersucht, ein Speisopfer der Offenbarung, das eine Verschuldung offenbar machen soll.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 16, 'Hierauf soll der Priester sie herantreten lassen und sie vor den HERRN stellen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 17, 'Dann nehme der Priester heiliges Wasser in einem irdenen Gefäß; weiter nehme der Priester etwas von dem Staube, der auf dem Fußboden der Wohnung liegt, und tue es in das Wasser.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 18, 'Dann lasse der Priester die Frau vor den HERRN treten, löse ihr das Haupthaar auf und gebe ihr das Offenbarungs-Speisopfer auf die Hände – es ist ein Speisopfer der Eifersucht –; aber das fluchbringende Wasser des bitteren Wehs behalte der Priester in der Hand.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 19, 'Sodann beschwöre sie der Priester und sage zu der Frau: ›Wenn kein (fremder) Mann dir beigewohnt hat und du, die du deinem Gatten angehörst, dich nicht vergangen und verunreinigt hast, so sollst du durch dieses fluchbringende Wasser des bitteren Wehs unversehrt bleiben!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 20, 'Wenn du dich aber, obgleich du deinem Gatten angehörst, vergangen und verunreinigt hast, so daß ein Mann außer deinem Gatten dir beigewohnt hat‹ –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 21, 'es beschwöre also der Priester die Frau mit feierlicher Verfluchung und spreche so zu der Frau –, ›so mache der HERR dich zum abschreckenden Beispiel einer feierlichen Verfluchung inmitten deines Volkes, indem der HERR deine Hüften schwinden macht und deinen Leib anschwellen läßt;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 22, 'und es möge dieses fluchbringende Wasser in deine Eingeweide dringen, so daß dein Leib anschwillt und deine Hüften schwinden!‹ Die Frau aber soll sagen: ›Ja, so geschehe es! Amen!‹');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 23, 'Dann schreibe der Priester diese Verfluchungen auf ein Blatt und wasche die Schrift wieder ab in das Wasser des bitteren Wehs hinein.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 24, 'Hierauf gebe er der Frau das fluchbringende Wasser des bitteren Wehs zu trinken, damit das fluchbringende Wasser in sie eindringe zu bitterem Weh.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 25, 'Dann nehme der Priester der Frau das Eifersuchts-Speisopfer aus der Hand, webe das Speisopfer von dem HERRN und bringe es hin zum Altar;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 26, 'dort nehme der Priester von dem Speisopfer eine Handvoll, nämlich den zum Duftopfer bestimmten Teil, und lasse es auf dem Altar in Rauch aufgehen; danach gebe er der Frau das Wasser zu trinken.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 27, 'Hat er sie nun das Wasser trinken lassen, so wird, falls sie sich vergangen hat und ihrem Mann untreu gewesen ist, das fluchbringende Wasser zu bitterem Weh in sie eindringen: ihr Leib wird anschwellen, und ihre Hüften werden schwinden, und die Frau wird zum abschreckenden Beispiel einer Verfluchung inmitten ihres Volkes werden.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 28, 'Wenn aber die Frau sich nicht verunreinigt hat, sondern schuldlos ist, so wird sie unversehrt bleiben und kann wieder Mutter von Kindern werden.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 29, 'Dies ist die Verordnung bezüglich der Eifersucht: Wenn eine Frau, die einem Ehemann angehört, sich vergeht und sich verunreinigt,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 30, 'oder auch wenn über einen Mann der Geist der Eifersucht kommt, so daß er auf seine Frau eifersüchtig wird, so soll er die Frau vor den HERRN treten lassen, und der Priester soll genau nach dieser Verordnung mit ihr verfahren.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 31, 'Der Mann soll dabei außer Schuld bleiben, eine solche Frau aber muß ihre Schuld büßen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 1, 'Weiter gebot der HERR dem Mose folgendes:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 2, '»Teile den Israeliten folgende Verordnungen mit: Wenn ein Mann oder ein Weib das Absonderungsgelübde eines Nasiräers ablegen will, um sich dem HERRN zu weihen,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 3, 'so muß er sich des Weines und jedes andern berauschenden Getränks enthalten; auch Essig von Wein oder Essig von berauschendem Getränk darf er nicht trinken; ebenso darf er keinerlei aus Trauben hergestellte Flüssigkeit trinken und keine Trauben, weder frische noch getrocknete, genießen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 4, 'Während der ganzen Dauer seiner Weihezeit darf er von allem, was vom Weinstock kommt, nichts genießen, auch keine unreifen Trauben und keine Rankenspitzen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 5, 'Während der ganzen Dauer seines Weihegelübdes darf kein Schermesser auf sein Haupt kommen; bis zum Ablauf der Zeit, für die er sich dem HERRN geweiht hat, soll er als geheiligt gelten: er hat sein Haupthaar frei wachsen zu lassen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 6, 'Während der ganzen Zeit, für die er sich dem HERRN geweiht hat, darf er zu keinem Toten hineingehen;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 7, 'selbst wenn ihm Vater oder Mutter, Bruder oder Schwester sterben, darf er sich an ihren Leichen nicht verunreinigen; denn die Weihe seines Gottes ruht auf seinem Haupt:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 8, 'solange seine Weihe dauert, ist er dem HERRN heilig.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 9, '»Sollte aber jemand ganz plötzlich neben ihm sterben und er dadurch sein geweihtes Haupt verunreinigen, so soll er an dem Tage, an dem er wieder rein wird, sein Haupt scheren, also am siebten Tage;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 10, 'und am achten Tage soll er zwei Turteltauben oder zwei junge Tauben zu dem Priester an den Eingang des Offenbarungszeltes bringen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 11, 'Der Priester soll dann die eine zum Sündopfer und die andere zum Brandopfer herrichten und ihm so Sühne erwirken dafür, daß er sich an der Leiche (verunreinigt und sich dadurch) versündigt hat. Dann soll er an demselben Tage sein Haupt nochmals für geheiligt erklären');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 12, 'und sich dem HERRN für die gelobte Zeit von neuem weihen, auch ein einjähriges Lamm als Schuldopfer darbringen; die vorige Zeit aber soll als verfallen gelten, weil seine Weihe unrein geworden war.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 13, '»Folgende Vorschriften aber gelten für den Nasiräer: An dem Tage, an welchem die von ihm gelobte Weihezeit zu Ende ist, führe man ihn an den Eingang des Offenbarungszeltes;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 14, 'und er hat dem HERRN seine Opfergabe darzubringen, nämlich ein einjähriges, fehlerloses Lamm zum Brandopfer und ein einjähriges, fehlerloses weibliches Lamm zum Sündopfer, ferner einen fehlerlosen Widder zum Heilsopfer;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 15, 'außerdem einen Korb mit ungesäuertem Backwerk von Feinmehl, nämlich mit Öl gemengte Kuchen und ungesäuerte, mit Öl bestrichene Fladen, nebst dem zugehörigen Speisopfer und den erforderlichen Trankopfern.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 16, 'Der Priester soll dann dies alles vor den HERRN bringen und das Sündopfer und das Brandopfer für ihn herrichten;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 17, 'den Widder aber soll er als Heilsopfer für den HERRN herrichten samt dem Korbe mit dem ungesäuerten Backwerk; auch das Speisopfer und das Trankopfer soll der Priester für ihn darbringen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 18, 'Sodann schere der Nasiräer sein geweihtes Haupt am Eingang des Offenbarungszeltes, nehme sein geweihtes Haupthaar und lege es in das Feuer, das unter dem Heilsopfer brennt.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 19, 'Hierauf nehme der Priester den gekochten Bug von dem Widder nebst einem ungesäuerten Kuchen und einem ungesäuerten Fladen aus dem Korbe und lege dies alles dem Nasiräer auf die Hände, nachdem dieser sich das geweihte Haar abgeschoren hat.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 20, 'Sodann webe der Priester dieses alles als Webeopfer vor dem HERRN: es ist eine dem Priester zufallende heilige Gabe samt der Webebrust und der Hebekeule. Danach darf der Nasiräer wieder Wein trinken.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 21, 'Diese Vorschriften gelten für den Gottgeweihten, der ein Gelübde abgelegt hat, nämlich bezüglich seiner Opfergabe, die er dem HERRN auf Grund seiner Weihe darzubringen hat, abgesehen von dem, was er sonst noch zu leisten vermag. Auf Grund seines Gelübdes, das er abgelegt hat, soll er nach den für seine Weihe geltenden Vorschriften verfahren.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 22, 'Der HERR gebot alsdann dem Mose folgendes:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 23, '»Gib Aaron und seinen Söhnen folgende Weisung: Mit diesen Worten sollt ihr den Segen über die Israeliten aussprechen:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 24, '›Der HERR segne dich und behüte dich!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 25, 'Der HERR lasse sein Angesicht leuchten über dir und sei dir gnädig!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 26, 'Der HERR erhebe sein Angesicht zu dir hin und gewähre dir Frieden!‹');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 27, 'Wenn sie so meinen Namen auf die Israeliten legen, will ich sie segnen.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 1, 'An dem Tage nun, als Mose mit der Errichtung der heiligen Wohnung fertig war und sie gesalbt und geheiligt hatte samt allen ihren Geräten, auch den Brandaltar mit allen seinen Geräten gesalbt und geweiht hatte,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 2, 'da brachten die Fürsten der Israeliten, die Häupter der einzelnen Stämme – das sind die Stammesfürsten, die als Vorsteher die Musterung vorgenommen hatten –,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 3, 'da brachten sie ihre Opfergabe vor den HERRN, nämlich sechs überdeckte Wagen und zwölf Rinder, je einen Wagen auf zwei Fürsten und je ein Rind von jedem: die brachten sie vor die heilige Wohnung.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 4, 'Da gebot der HERR dem Mose folgendes:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 5, '»Nimm sie von ihnen an, damit sie beim Dienst am Offenbarungszelt Verwendung finden, und übergib sie den Leviten unter Berücksichtigung des von jedem zu leistenden Dienstes.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 6, 'So nahm denn Mose die Wagen und die Rinder und übergab sie den Leviten.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 7, 'Zwei von den Wagen und vier Rinder übergab er den Gersoniten mit Rücksicht auf den von ihnen zu leistenden Dienst;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 8, 'die andern vier Wagen und acht Rinder aber übergab er den Merariten mit Rücksicht auf den Dienst, den sie unter der Aufsicht Ithamars, des Sohnes des Priesters Aaron, zu leisten hatten.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 9, 'Den Kehathiten aber übergab er nichts; denn ihnen oblag die Besorgung der heiligsten Gegenstände, die sie auf der Schulter tragen mußten.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 10, 'Sodann brachten die Fürsten die Einweihungsgaben für den Altar an dem Tage dar, an welchem er gesalbt wurde, und zwar brachten die Fürsten ihre Opfergaben vor den Altar.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 11, 'Da gebot der HERR dem Mose: »Tag für Tag soll jedesmal nur einer der Fürsten seine Opfergabe zur Einweihung des Altars darbringen.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 12, 'Derjenige nun, welcher am ersten Tage seine Opfergabe darbrachte, war Nahson, der Sohn Amminadabs, vom Stamme Juda.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 13, 'Seine Opfergabe war: eine silberne Schüssel, 130 Schekel schwer, ein silbernes Becken, 70 Schekel schwer nach dem Gewicht des Heiligtums, beide gefüllt mit Feinmehl, das mit Öl gemengt war, zum Speisopfer;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 14, 'eine Schale von Gold, 10 Schekel schwer, mit Räucherwerk gefüllt;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 15, 'ein junger Stier, ein Widder und ein einjähriges Lamm zum Brandopfer;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 16, 'ein Ziegenbock zum Sündopfer;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 17, 'ferner zum Heilsopfer zwei Rinder, fünf Widder, fünf Böcke und fünf einjährige Lämmer. Das war die Opfergabe Nahsons, des Sohnes Amminadabs.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 18, 'Am zweiten Tage opferte Nethaneel, der Sohn Zuars, der Fürst von Issaschar.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 19, 'Er brachte als seine Opfergabe dar: eine silberne Schüssel, 130 Schekel schwer, ein silbernes Becken, 70 Schekel schwer nach dem Gewicht des Heiligtums, beide gefüllt mit Feinmehl, das mit Öl gemengt war, zum Speisopfer;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 20, 'eine Schale von Gold, 10 Schekel schwer, mit Räucherwerk gefüllt;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 21, 'einen jungen Stier, einen Widder und ein einjähriges Lamm zum Brandopfer;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 22, 'einen Ziegenbock zum Sündopfer;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 23, 'ferner zum Heilsopfer zwei Rinder, fünf Widder, fünf Böcke und fünf einjährige Lämmer. Das war die Opfergabe Nethaneels, des Sohnes Zuars.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 24, 'Am dritten Tage opferte der Fürst des Stammes Sebulon, Eliab, der Sohn Helons.');
