INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 81, 'ein junger Stier, ein Widder und ein einjähriges Lamm zum Brandopfer;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 82, 'ein Ziegenbock zum Sündopfer;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 83, 'ferner zum Heilsopfer zwei Rinder, fünf Widder, fünf Böcke und fünf einjährige Lämmer. Das war die Opfergabe Ahiras, des Sohnes Enans.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 84, 'Dies waren von seiten der Fürsten der Israeliten die Gaben zur Einweihung des Altars an dem Tage, an welchem er gesalbt wurde, nämlich 12 silberne Schüsseln, 12 silberne Becken, 12 goldene Schalen,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 85, 'jede silberne Schüssel 130 Schekel, jedes Becken 70 Schekel schwer; das gesamte Silber der Gefäße betrug also 2400 Schekel nach dem Gewicht des Heiligtums;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 86, 'ferner zwölf goldene Schalen, mit Räucherwerk gefüllt, jede Schale 10 Schekel schwer nach dem Gewicht des Heiligtums; das gesamte Gold der Schalen betrug also 120 Schekel.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 87, 'Die Gesamtzahl der Rinder zum Brandopfer belief sich auf 12 junge Stiere, dazu 12 Widder, 12 einjährige Lämmer nebst dem zugehörigen Speisopfer, und 12 Ziegenböcke zum Sündopfer.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 88, 'Die sämtlichen Rinder zum Heilsopfer beliefen sich auf 24 junge Stiere, dazu 60 Widder, 60 Böcke, 60 einjährige Lämmer. Dies waren die Gaben zur Einweihung des Altars, nachdem er gesalbt worden war.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 89, 'Wenn nun Mose in das Offenbarungszelt hineinging, um mit dem HERRN zu reden, hörte er die Stimme zu sich reden von der Deckplatte her, die über der Gesetzeslade lag, und zwar von dem Raum zwischen den beiden Cheruben her; und so redete er (der HERR) zu ihm.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 8, 1, 'Hierauf gebot der HERR dem Mose folgendes:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 8, 2, '»Gib dem Aaron folgende Weisung: Wenn du die Lampen aufsetzt, so sollen die sieben Lampen ihr Licht nach der Vorderseite des Leuchters hin werfen.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 8, 3, 'Da machte Aaron es so: an der Vorderseite des Leuchters setzte er dessen Lampen auf, wie der HERR dem Mose geboten hatte.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 8, 4, 'Der Leuchter war aber aus Gold in getriebener Arbeit hergestellt: sowohl sein Schaft als auch seine Blüten – alles war getriebene Arbeit; nach dem Muster, das der HERR dem Mose gezeigt hatte, so hatte er den Leuchter anfertigen lassen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 8, 5, 'Weiter gebot der HERR dem Mose folgendes:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 8, 6, '»Sondere die Leviten aus der Mitte der Israeliten aus und reinige sie;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 8, 7, 'und zwar sollst du behufs ihrer Reinigung so mit ihnen verfahren: Besprenge sie mit Entsündigungswasser; dann sollen sie ein Schermesser über ihren ganzen Leib gehen lassen und ihre Kleider waschen und so sich reinigen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 8, 8, 'Hierauf sollen sie einen jungen Stier nehmen nebst dem zugehörigen Speisopfer, nämlich Feinmehl, das mit Öl gemengt ist; und einen zweiten jungen Stier sollst du zum Sündopfer nehmen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 8, 9, 'Dann sollst du die Leviten vor das Offenbarungszelt treten lassen und die ganze Gemeinde der Israeliten dort versammeln.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 8, 10, 'Hierauf laß die Leviten vor den HERRN treten, und die Israeliten sollen ihre Hände fest auf die Leviten legen;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 8, 11, 'dann soll Aaron die Leviten vor dem HERRN als ein von seiten der Israeliten dargebrachtes Webeopfer weben, damit sie den Dienst des HERRN zu verrichten geeignet werden.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 8, 12, 'Nachdem dann die Leviten ihre Hände fest auf den Kopf der Stiere gelegt haben, sollst du den einen Stier zum Sündopfer, den andern zum Brandopfer für den HERRN herrichten, um den Leviten Sühne zu erwirken.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 8, 13, 'Dann laß die Leviten vor Aaron und seine Söhne treten und webe sie als Webeopfer für den HERRN:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 8, 14, 'auf diese Weise sollst du die Leviten aus der Mitte der Israeliten aussondern, damit die Leviten mir gehören.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 8, 15, 'Darnach sollen die Leviten hineingehen, um den Dienst am Offenbarungszelt zu verrichten. So sollst du sie reinigen und als Webeopfer weben;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 8, 16, 'denn sie sind mir aus der Mitte der Israeliten ganz zu eigen gegeben: als Ersatz für alle Erstgeburten, für alle Kinder, die unter den Israeliten zuerst zur Welt kommen, habe ich sie für mich genommen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 8, 17, 'Denn mir gehört alles Erstgeborene in Israel, von den Menschen wie vom Vieh; an dem Tage, als ich alle Erstgeburten im Lande Ägypten sterben ließ, habe ich sie mir geheiligt.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 8, 18, 'So habe ich denn die Leviten als Ersatz für alle Erstgeborenen unter den Israeliten genommen');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 8, 19, 'und habe die Leviten dem Aaron und seinen Söhnen aus der Mitte der Israeliten zu eigen gegeben, damit sie den von den Israeliten zu leistenden Dienst am Offenbarungszelt verrichten und den Israeliten als Deckung dienen, auf daß kein Unglücksschlag die Israeliten trifft, wenn sie selbst sich dem Heiligtum nähern würden.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 8, 20, 'Hierauf verfuhren Mose und Aaron und die ganze Gemeinde der Israeliten mit den Leviten genau so, wie der HERR dem Mose bezüglich der Leviten geboten hatte: genau so verfuhren die Israeliten mit ihnen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 8, 21, 'Die Leviten ließen sich nämlich entsündigen und wuschen ihre Kleider; Aaron webte sie dann als Webeopfer vor dem HERRN, und Aaron vollzog zu ihrer Reinigung die Sühnehandlungen für sie.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 8, 22, 'Danach gingen die Leviten hinein, um ihren Dienst am Offenbarungszelt unter der Aufsicht Aarons und seiner Söhne zu verrichten; wie der HERR dem Mose in betreff der Leviten geboten hatte, so verfuhren sie mit ihnen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 8, 23, 'Hierauf sagte der HERR weiter zu Mose:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 8, 24, '»Folgende Vorschriften sollen in betreff der Leviten gelten: Im Alter von fünfundzwanzig Jahren und darüber soll der Levit im Dienst zur Besorgung der Verrichtungen am Offenbarungszelt tätig sein;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 8, 25, 'aber von fünfzig Jahren an soll er von den Dienstleistungen befreit sein und nicht mehr dienen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 8, 26, 'Er mag alsdann seinen Brüdern im Offenbarungszelt behilflich sein, wenn sie ihren Dienst verrichten, aber regelmäßigen Dienst soll er nicht mehr leisten. So sollst du es mit den Leviten bezüglich ihrer Amtsgeschäfte halten.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 9, 1, 'Weiter gebot der HERR dem Mose in der Wüste Sinai im zweiten Jahr nach ihrem Auszug aus dem Lande Ägypten, im ersten Monat, folgendes:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 9, 2, '»Die Israeliten sollen das Passah zur festgesetzten Zeit feiern:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 9, 3, 'am vierzehnten Tage in diesem Monat gegen Abend sollt ihr es zur festgesetzten Zeit feiern; nach allen darauf bezüglichen Bestimmungen und nach allen dafür geltenden Vorschriften sollt ihr es feiern.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 9, 4, 'Da befahl Mose den Israeliten, das Passah zu feiern;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 9, 5, 'und sie feierten es im ersten Monat, am vierzehnten Tage des Monats, gegen Abend in der Wüste Sinai; ganz wie der HERR dem Mose geboten hatte, so verfuhren die Israeliten dabei.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 9, 6, 'Nun waren aber einige Männer da, die sich an einer Menschenleiche verunreinigt hatten und deshalb das Passah an jenem Tage nicht feiern konnten. Diese traten nun an jenem Tage vor Mose und Aaron');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 9, 7, 'und sagten zu ihm: »Wir sind durch eine Menschenleiche unrein geworden: warum sollen wir benachteiligt werden, daß wir die Opfergabe für den HERRN nicht zur festgesetzten Zeit inmitten der Israeliten darbringen dürfen?«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 9, 8, 'Mose antwortete ihnen: »Wartet, ich will hören, was der HERR euretwegen anordnet!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 9, 9, 'Der HERR aber gebot dem Mose folgendes:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 9, 10, '»Teile den Israeliten folgende Verordnungen mit: Wenn irgend jemand von euch oder von euren Nachkommen sich an einer Leiche verunreinigt hat oder sich auf einer Reise in der Ferne befindet, so soll er doch das Passah zu Ehren des HERRN feiern:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 9, 11, 'im zweiten Monat, am vierzehnten Tage, gegen Abend sollen die Betreffenden es feiern; mit ungesäuertem Brot und bitteren Kräutern sollen sie es verzehren.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 9, 12, 'Sie dürfen nichts davon bis zum folgenden Morgen übriglassen, auch keinen Knochen an ihm zerbrechen; nach allen für das Passah geltenden Bestimmungen sollen sie es feiern.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 9, 13, 'Wer aber rein ist und sich auf keiner Reise befindet und die Passahfeier trotzdem unterläßt, ein solcher Mensch soll aus seinen Volksgenossen ausgerottet werden, weil er dem HERRN die Opfergabe nicht zur festgesetzten Zeit dargebracht hat: ein solcher Mensch soll für seine Sünde büßen! –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 9, 14, 'Wenn ferner ein Fremdling sich unter euch aufhält und dem HERRN das Passah feiern will, so soll er es nach den für das Passah geltenden Bestimmungen und Vorschriften feiern; die gleichen Bestimmungen sollen für euch gelten, sowohl für den Fremdling als auch für den im Lande Geborenen.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 9, 15, 'An dem Tage aber, an welchem man die heilige Wohnung aufgeschlagen hatte, bedeckte die Wolke die Wohnung, nämlich das Zelt mit dem Gesetz; doch am Abend lag sie über der Wohnung wie ein Feuerschein bis zum Morgen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 9, 16, 'So blieb es die ganze Folgezeit hindurch: die Wolke bedeckte die Wohnung, und zwar nachts als ein Feuerschein.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 9, 17, 'Sobald sich nun die Wolke von dem Zelt erhob, brachen die Israeliten alsbald danach auf; und an dem Orte, wo die Wolke sich wieder niederließ, da lagerten die Israeliten:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 9, 18, 'nach dem Befehl des HERRN brachen die Israeliten auf, und nach dem Befehl des HERRN lagerten sie; solange die Wolke ruhig über der Wohnung lag, so lange blieben sie gelagert.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 9, 19, 'Auch wenn die Wolke viele Tage lang über der Wohnung stehen blieb, beobachteten die Israeliten die Weisung des HERRN und zogen nicht weiter.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 9, 20, 'Es kam aber auch vor, daß die Wolke nur wenige Tage über der Wohnung stehen blieb – nach dem Befehl des HERRN lagerten sie, und nach dem Befehl des HERRN brachen sie auf.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 9, 21, 'Es kam auch vor, daß die Wolke nur vom Abend bis zum Morgen blieb; wenn sie sich dann am Morgen erhob, so brach man auf; oder wenn die Wolke einen Tag und eine Nacht blieb und sich dann erhob, so brach man auf;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 9, 22, 'oder wenn die Wolke zwei Tage oder einen Monat oder noch längere Zeit blieb, indem die Wolke über der Wohnung Halt machte und auf ihr ruhte, so blieben die Israeliten gelagert und brachen nicht auf; sobald sie sich aber erhob, brachen sie auf:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 9, 23, 'nach dem Geheiß des HERRN blieben sie gelagert, und nach dem Geheiß des HERRN brachen sie auf: sie beobachteten die Weisung des HERRN nach dem durch Mose übermittelten Geheiß des HERRN.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 1, 'Weiter gebot der HERR dem Mose folgendes:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 2, '»Fertige dir zwei silberne Trompeten an; in getriebener Arbeit sollst du sie anfertigen, und sie sollen dir dazu dienen, die Gemeinde zusammenzurufen und das Zeichen zum Aufbruch der Lager zu geben.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 3, 'Sobald mit ihnen (beiden) geblasen wird, soll sich die ganze Gemeinde bei dir am Eingang des Offenbarungszeltes versammeln;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 4, 'wird aber nur mit einer geblasen, so sollen sich die Fürsten, die Häupter der Tausendschaften der Israeliten, bei dir versammeln.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 5, 'Wenn aber Alarm geblasen wird, so sollen die ostwärts liegenden Lager aufbrechen;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 6, 'und wenn zum zweitenmal Alarm geblasen wird, sollen die südwärts liegenden Lager aufbrechen: Alarm soll geblasen werden zu ihrem Aufbruch.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 7, 'Wenn es sich aber um die Versammlung der Gemeinde handelt, sollt ihr einfache Trompetenzeichen geben, aber keinen Alarm blasen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 8, 'Das Blasen der Trompeten soll den Söhnen Aarons, den Priestern, obliegen; diese Vorschriften sollen bei euch ewige Geltung für eure künftigen Geschlechter haben.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 9, 'Und wenn ihr in eurem Lande gegen den Feind, der euch bedrängt, in den Krieg zieht und Alarm mit den Trompeten blast, so wird euer beim HERRN, eurem Gott, gedacht werden, so daß ihr Rettung von euren Feinden erlangt.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 10, 'Auch an euren Freudentagen und Festen sowie an euren Neumonden sollt ihr zu euren Brandopfern und zu euren Heilsopfern die Trompeten blasen, damit sie euch zu gnädigem Gedenken bei eurem Gott verhelfen: ich bin der HERR, euer Gott!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 11, 'Im zweiten Jahr, am zwanzigsten Tage des zweiten Monats, erhob sich die Wolke von der Wohnung des Gesetzes.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 12, 'Da brachen die Israeliten aus der Wüste Sinai auf, nach ihren Zügen; und die Wolke ließ sich in der Wüste Paran nieder.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 13, 'So brachen sie denn zum erstenmal nach dem durch Mose übermittelten Befehl des HERRN auf;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 14, 'und zwar brach zuerst das Panier des Lagers des Stammes Juda auf, eine Heerschar nach der andern; das Heer dieses Stammes befehligte Nahson, der Sohn Amminadabs.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 15, 'Das Heer des Stammes Issaschar aber befehligte Nethaneel, der Sohn Zuars;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 16, 'und das Heer des Stammes Sebulon befehligte Eliab, der Sohn Helons.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 17, 'Als dann die heilige Wohnung niedergelegt war, brachen die Gersoniten und die Merariten auf, welche die (heilige) Wohnung zu tragen hatten.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 18, 'Hierauf brach das Panier des Lagers Rubens auf, eine Heerschar nach der andern; das Heer dieses Stammes befehligte Elizur, der Sohn Sedeurs.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 19, 'Das Heer des Stammes Simeon aber befehligte Selumiel, der Sohn Zurisaddais;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 20, 'und das Heer des Stammes Gad befehligte Eljasaph, der Sohn Deguels.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 21, 'Dann brachen die Kehathiten auf, die das (Hoch-) Heilige zu tragen hatten; man hatte aber die (heilige) Wohnung bis zu der Ankunft dieser schon aufgerichtet.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 22, 'Hierauf brach das Panier des Lagers der Ephraimiten auf, eine Heerschar nach der andern; das Heer dieses Stammes befehligte Elisama, der Sohn Ammihuds.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 23, 'Das Heer des Stammes Manasse aber befehligte Gamliel, der Sohn Pedazurs;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 24, 'und das Heer des Stammes Benjamin befehligte Abidan, der Sohn Gideonis.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 25, 'Hierauf brach das Panier des Lagers des Stammes Dan auf, das die Nachhut sämtlicher Lager bildete, eine Heerschar nach der andern; das Heer dieses Stammes befehligte Ahieser, der Sohn Ammisaddais.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 26, 'Das Heer des Stammes Asser aber befehligte Pagiel, der Sohn Ochrans;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 27, 'und das Heer des Stammes Naphthali befehligte Ahira, der Sohn Enans.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 28, 'Dies war die Marschordnung, in der die Israeliten aufbrachen, eine Heerschar nach der andern.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 29, 'Da sagte Mose zu Hobab, dem Sohn des Midianiters Reguel, des Schwiegervaters Moses: »Wir brechen jetzt nach dem Lande auf, von dem der HERR verheißen hat: ›Ich will es euch geben.‹ Ziehe mit uns, wir wollen es dir gut lohnen; denn der HERR hat Israel Gutes verheißen.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 30, 'Der aber antwortete ihm: »Nein, ich mag nicht mitziehen, sondern will in meine Heimat und zu meiner Verwandtschaft zurückkehren.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 31, 'Da bat ihn Mose: »Verlaß uns doch nicht! Denn da gerade du die Plätze kennst, wo wir in der Wüste lagern können, so sollst du unser Auge sein.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 32, 'Wenn du mit uns ziehst und jenes Glück uns zuteil wird, mit dem der HERR uns segnen will, so wollen wir es dir gut lohnen.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 33, 'So brachen sie denn vom Berge des HERRN auf, drei Tagereisen weit, indem die Bundeslade des HERRN vor ihnen herzog, drei Tagereisen weit, um einen Lagerplatz für sie ausfindig zu machen;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 34, 'dabei stand die Wolke des HERRN bei Tage über ihnen, wenn sie aus dem Lager aufbrachen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 35, 'Und sooft die Lade sich in Bewegung setzte, rief Mose aus: »Erhebe dich, HERR, auf daß deine Feinde zerstieben und deine Widersacher vor dir fliehen!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 36, 'Und sooft sie Halt machte, rief er aus: »Kehre zurück, HERR, zu den Zehntausenden der Tausende Israels!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 11, 1, 'Da erging sich das Volk in lauten Klagen über sein Ungemach vor den Ohren des HERRN. Als der HERR es hörte, entbrannte sein Zorn, und das Feuer des HERRN zündete unter ihnen und richtete am Ende des Lagers Verheerung an.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 11, 2, 'Da schrie das Volk zu Mose, und dieser betete zum HERRN: da erlosch das Feuer.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 11, 3, 'Man gab deshalb diesem Orte den Namen Thabera, weil dort das Feuer des HERRN gegen sie aufgelodert war.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 11, 4, 'Das Gesindel aber, das sich unter ihnen befand, wurde lüstern; da fingen auch die Israeliten wieder an zu jammern und klagten: »Wer gibt uns Fleisch zu essen?');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 11, 5, 'Wir denken an die Fische zurück, die wir in Ägypten umsonst zu essen hatten, an die Gurken und Melonen, an den Lauch, die Zwiebeln und den Knoblauch!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 11, 6, 'Jetzt aber sind wir ganz ausgehungert; gar nichts ist da! Nichts bekommen wir zu sehen als das Manna!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 11, 7, 'Das Manna aber sah aus wie Koriandersamen und glich dem Bedolachharz.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 11, 8, 'Das Volk streifte umher und las es auf; hierauf zermahlten sie es mit Handmühlen oder zerstießen es in Mörsern, kochten es dann in Töpfen oder bereiteten Kuchen daraus; es schmeckte wie Ölbackwerk.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 11, 9, 'Wenn der Tau nachts auf das Lager herabfiel, fiel das Manna mit auf ihn herab.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 11, 10, 'Als nun Mose das Volk in allen Familien wehklagen hörte, einen jeden am Eingang seines Zeltes, und der Zorn des HERRN heftig entbrannt war, da regte sich der Unwille in Mose,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 11, 11, 'so daß er zum HERRN sagte: »Warum verfährst du so übel mit deinem Knecht, und warum nimmst du so wenig Rücksicht auf mich, daß du die Last (der Sorge) für dieses ganze Volk auf mich legst?');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 11, 12, 'Habe ich denn Mutterpflichten gegen dieses ganze Volk zu erfüllen, oder habe ich es in die Welt gesetzt, daß du zu mir sagen dürftest: ›Trage es auf deinen Armen, wie die Wärterin den Säugling trägt, und bringe es in das Land, das du ihren Vätern zugeschworen hast?‹');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 11, 13, 'Woher soll ich Fleisch nehmen, um es diesem ganzen Volke zu geben? Mir jammern sie ja ihre Not vor und rufen: ›Gib uns Fleisch zu essen!‹');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 11, 14, 'Ich allein vermag die Last (der Sorge) für dieses ganze Volk nicht zu tragen; sie ist für mich zu schwer!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 11, 15, 'Willst du trotzdem so mit mir verfahren, so bringe mich doch lieber gleich um, wenn du es gut mit mir meinst, damit ich mein Unglück nicht länger anzusehen brauche!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 11, 16, 'Da antwortete der HERR dem Mose: »Versammle mir siebzig Männer aus den Ältesten der Israeliten, von denen du weißt, daß sie wirklich Älteste des Volkes und seine Obmänner sind; führe sie dann zum Offenbarungszelt und laß sie sich dort neben dir aufstellen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 11, 17, 'Ich will dann herabkommen und dort zu dir reden und will von dem Geist, der auf dir ruht, etwas nehmen und es ihnen mitteilen, damit sie im Verein mit dir die Last (der Sorge) für das Volk tragen und du sie nicht mehr allein zu tragen brauchst.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 11, 18, 'Zu dem Volke aber sollst du sagen: ›Heiligt euch für morgen! Da sollt ihr Fleisch zu essen bekommen; denn ihr habt vor den Ohren des HERRN gejammert und ausgerufen: Wer gibt uns Fleisch zu essen? In Ägypten hatten wir es so gut! Darum wird der HERR euch Fleisch geben, damit ihr zu essen habt.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 11, 19, 'Nicht nur einen Tag sollt ihr es zu essen haben, auch nicht nur zwei oder fünf oder zehn oder zwanzig Tage:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 11, 20, 'nein, einen ganzen Monat lang, bis ihr es nicht mehr riechen könnt und es euch zum Ekel wird! Denn ihr habt den HERRN, der in eurer Mitte weilt, mißachtet und vor ihm gejammert und geklagt: Warum sind wir nur aus Ägypten weggezogen!‹«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 11, 21, 'Da erwiderte Mose: »Sechshunderttausend Mann zu Fuß zählt das Volk, unter dem ich lebe, und doch sagst du: ›Fleisch will ich ihnen geben, daß sie einen ganzen Monat lang zu essen haben‹?');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 11, 22, 'Können so viele Stück Kleinvieh und Rinder für sie geschlachtet werden, daß es für sie ausreicht? Oder sollen alle Fische des Meeres für sie eingefangen werden, daß es für sie ausreicht?«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 11, 23, 'Da antwortete der HERR dem Mose: »Ist etwa der Arm des HERRN zu kurz? Jetzt sollst du sehen, ob mein Wort sich dir erfüllt oder nicht!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 11, 24, 'Hierauf ging Mose hinaus und teilte dem Volk die Worte des HERRN mit; dann berief er siebzig Männer aus den Ältesten des Volkes und ließ sie sich rings um das (heilige) Zelt aufstellen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 11, 25, 'Da fuhr der HERR in der Wolke herab und redete zu ihm, nahm dann etwas von dem Geist, der auf ihm ruhte, und teilte ihn den siebzig Ältesten zu. Sobald nun der Geist auf sie gekommen war, gerieten sie in prophetische Begeisterung, später aber nicht wieder.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 11, 26, 'Es waren aber zwei Männer im Lager zurückgeblieben, von denen der eine Eldad hieß, der andere Medad; auch auf diese ließ der Geist sich nieder – sie gehörten nämlich zu der Zahl der Aufgeschriebenen, waren aber nicht ans Zelt hinausgegangen –; diese gerieten nun im Lager in prophetische Begeisterung.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 11, 27, 'Da kam ein Jüngling gelaufen und meldete dem Mose: »Eldad und Medad sind im Lager in prophetische Begeisterung geraten!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 11, 28, 'Da brach Josua, der Sohn Nuns, der schon von seiner Jünglingszeit an der Diener Moses gewesen war, in die Worte aus: »O Mose, mein Herr, gebiete ihnen Einhalt!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 11, 29, 'Aber Mose entgegnete ihm: »Gerätst du aus Sorge für mich in solchen Eifer? Möchte doch das ganze Volk des HERRN zu Propheten werden, daß der HERR seinen Geist auf sie kommen ließe!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 11, 30, 'Hierauf begab sich Mose mit den Ältesten der Israeliten ins Lager zurück.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 11, 31, 'Da erhob sich ein vom HERRN gesandter Wind, der führte Wachteln vom Meere herüber und ließ sie auf das Lager hineinfallen, ungefähr eine Tagereise weit nach allen Seiten rings um das Lager, und sie flogen nur etwa zwei Ellen hoch über der Erde.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 11, 32, 'Da machte sich das Volk jenen ganzen Tag und die ganze Nacht und den ganzen folgenden Tag daran und sammelte Wachteln; wer auch nur wenig sammelte, brachte es doch auf zehn Homer; dann breiteten sie sich diese (zum Dörren) weithin aus rings um das Lager her.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 11, 33, 'Als sie aber das Fleisch noch zwischen ihren Zähnen hatten, noch ehe es verzehrt war, da entbrannte der Zorn des HERRN gegen das Volk, und der HERR ließ ein verheerendes Sterben unter dem Volke ausbrechen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 11, 34, 'Daher gab man diesem Orte den Namen Kibroth Hattaawa, weil man dort die Leute begraben hatte, die ihrem Gelüst gefrönt hatten. –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 11, 35, 'Von den Lustgräbern zog das Volk dann weiter nach Hazeroth, woselbst sie längere Zeit blieben.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 12, 1, 'Mirjam und Aaron aber redeten gegen Mose wegen des kuschitischen Weibes, das er zur Frau genommen hatte; er hatte nämlich eine Kuschitin geheiratet.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 12, 2, 'Außerdem sagten sie: »Hat der HERR etwa nur mit Mose geredet? Hat er nicht auch mit uns geredet?«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 12, 3, 'Der HERR hörte dies; Mose aber war ein überaus sanftmütiger Mann, sanftmütiger als irgendein anderer Mensch auf der Erde.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 12, 4, 'Da sagte der HERR sofort zu Mose, zu Aaron und zu Mirjam: »Begebt euch alle drei zum Offenbarungszelt hinaus!« Als nun die drei hinausgegangen waren,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 12, 5, 'fuhr der HERR in einer Wolkensäule herab und trat an den Eingang des Zeltes; als er dann Aaron und Mirjam gerufen hatte und die beiden hinausgegangen waren,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 12, 6, 'sagte er: »Hört jetzt meine Worte! Wenn ein Prophet des HERRN unter euch ist, so offenbare ich mich ihm durch Gesichte und rede zu ihm durch Träume.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 12, 7, 'So steht es aber nicht bei meinem Knecht Mose; der ist mit meinem ganzen Hause betraut;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 12, 8, 'von Mund zu Mund rede ich mit ihm, unzweideutig und nicht in Rätseln, und er darf die Gestalt des HERRN selbst schauen. Warum habt ihr euch also nicht gescheut, gegen meinen Knecht, gegen Mose, übel zu reden?«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 12, 9, 'Darauf entbrannte der Zorn des HERRN gegen sie, und er verschwand.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 12, 10, 'Als aber die Wolke sich vom Zelt entfernt hatte, war Mirjam plötzlich vom Aussatz weiß wie Schnee geworden; und als Aaron sich zu Mirjam hinwandte, sah er, daß sie aussätzig war.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 12, 11, 'Da sagte Aaron zu Mose: »Ach, bitte, mein Herr, laß uns doch nicht für die Sünde büßen, daß wir in Unbesonnenheit gehandelt und uns vergangen haben!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 12, 12, 'Laß doch Mirjam nicht wie ein totes Kind sein, dessen Leib beim Austritt aus dem Mutterschoß schon halb verwest ist!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 12, 13, 'Darauf flehte Mose laut zum HERRN mit den Worten: »Ach Gott! Laß sie doch wieder gesund werden!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 12, 14, 'Da antwortete der HERR dem Mose: »Wenn ihr Vater ihr ins Gesicht gespien hätte, müßte sie sich da nicht sieben Tage lang schämen? Sie soll sieben Tage lang außerhalb des Lagers eingeschlossen bleiben; alsdann mag sie wieder Aufnahme im Lager finden.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 12, 15, 'So wurde denn Mirjam sieben Tage lang außerhalb des Lagers eingeschlossen; das Volk aber zog nicht eher weiter, als bis Mirjam wieder ins Lager aufgenommen war.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 12, 16, 'Danach brach das Volk von Hazeroth auf und lagerte in der Wüste Paran.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 13, 1, 'Darauf gebot der HERR dem Mose folgendes:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 13, 2, '»Sende Männer aus, damit sie das Land Kanaan auskundschaften, das ich den Israeliten geben will; je einen Mann aus jedem Stamme seiner Väter sollt ihr aussenden, lauter Fürsten unter ihnen.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 13, 3, 'So sandte denn Mose sie nach dem Befehl des HERRN aus der Wüste Paran aus, allesamt Männer, welche Stammeshäupter der Israeliten waren,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 13, 4, 'und dies sind ihre Namen: vom Stamme Ruben: Sammua, der Sohn Sakkurs;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 13, 5, 'vom Stamme Simeon: Saphat, der Sohn Horis;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 13, 6, 'vom Stamme Juda: Kaleb, der Sohn Jephunnes;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 13, 7, 'vom Stamme Issaschar: Jigal, der Sohn Josephs;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 13, 8, 'vom Stamme Ephraim: Hosea, der Sohn Nuns;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 13, 9, 'vom Stamme Benjamin: Palti, der Sohn Raphus;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 13, 10, 'vom Stamme Sebulon: Gaddiel, der Sohn Sodis;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 13, 11, '[vom Stamme Joseph] vom Stamme Manasse: Gaddi, der Sohn Susis;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 13, 12, 'vom Stamme Dan: Ammiel, der Sohn Gemallis;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 13, 13, 'vom Stamme Asser: Sethur, der Sohn Michaels;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 13, 14, 'vom Stamme Naphthali: Nahbi, der Sohn Wophsis;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 13, 15, 'vom Stamme Gad: Geuel, der Sohn Machis.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 13, 16, 'Dies sind die Namen der Männer, die Mose entsandte, um das Land auszukundschaften. Mose hatte aber Hosea, dem Sohne Nuns, den Namen Josua gegeben.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 13, 17, 'Mose entsandte sie also, um das Land Kanaan auszukundschaften, und befahl ihnen: »Zieht hier hinauf im Südland und steigt dann auf das Hochland hinauf;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 13, 18, 'seht zu, wie das Land beschaffen ist und ob das Volk, das darin wohnt, stark oder schwach, spärlich oder zahlreich ist;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 13, 19, 'auch wie das Land beschaffen ist, in dem es wohnt, ob fruchtbar oder unfruchtbar, und wie die Ortschaften beschaffen sind, in denen es wohnt, ob in offenen Lagern oder in festen Plätzen;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 13, 20, 'auch wie der Boden beschaffen ist, ob fett oder mager, ob Bäume darauf stehen oder nicht. Zeigt euch mutig und bringt auch von den Früchten des Landes einige mit!« Es war aber damals gerade die Zeit der ersten Trauben.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 13, 21, 'So zogen sie denn hinauf und kundschafteten das Land aus von der Wüste Zin bis Rehob, wo der Weg nach Hamath geht.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 13, 22, 'Sie zogen also im Südland hinauf und kamen bis Hebron, wo die Enakssöhne Ahiman, Sesai und Thalmai wohnten; Hebron aber war sieben Jahre vor der ägyptischen Stadt Zoan gegründet worden.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 13, 23, 'Als sie dann ins Tal Eskol gekommen waren, schnitten sie dort eine Rebe mit einer einzigen Weintraube ab, die sie zu zweien an einer Stange trugen, auch einige Granatäpfel und Feigen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 13, 24, 'Die betreffende Örtlichkeit nannte man Tal Eskol wegen der Traube, welche die Israeliten dort abgeschnitten hatten.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 13, 25, 'Nach Verlauf von vierzig Tagen machten sie sich dann auf den Rückweg, nachdem sie das Land ausgekundschaftet hatten.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 13, 26, 'Als sie nun zu Mose und Aaron und zur ganzen Gemeinde der Israeliten in die Wüste Paran nach Kades zurückgekehrt waren, erstatteten sie ihnen und der ganzen Gemeinde Bericht und zeigten ihnen die Früchte des Landes.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 13, 27, 'Sie trugen ihm aber folgenden Bericht vor: »Wir haben uns in das Land begeben, in das du uns gesandt hast: es fließt wirklich von Milch und Honig über, und dies hier sind Früchte von dort.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 13, 28, 'Jedoch das Volk, das im Lande wohnt, ist stark, und die Städte sind befestigt und sehr groß; auch die Enakssöhne haben wir dort gesehen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 13, 29, 'Die Amalekiter bewohnen das Südland, die Hethiter, Jebusiter und Amoriter wohnen im Berglande, und die Kanaanäer wohnen am Meer und an der Seite des Jordans.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 13, 30, 'Kaleb suchte nun den Unwillen des Volkes gegen Mose zu beschwichtigen, indem er ausrief: »Laßt uns nur hinaufziehen und (das Land) in Besitz nehmen! Denn wir können es sicherlich überwältigen.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 13, 31, 'Jedoch die Männer, die mit ihm hinaufgezogen waren, erklärten: »Wir sind nicht imstande, gegen das Volk hinaufzuziehen; denn es ist uns zu stark.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 13, 32, 'Dann entwarfen sie den Israeliten eine schlimme Schilderung von dem Lande, das sie ausgekundschaftet hatten, mit den Worten: »Das Land, das wir durchzogen haben, um es auszukundschaften, ist ein Land, das seine Bewohner frißt; und alles Volk, das wir darin gesehen haben, sind hochgewachsene Leute;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 13, 33, 'auch die Riesen haben wir dort gesehen, die Enakssöhne vom Geschlecht der Riesen; wir kamen uns selbst gegen sie wie Heuschrecken vor, und ebenso erschienen wir ihnen.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 1, 'Da erhob die ganze Gemeinde ein lautes Geschrei, und das Volk weinte in jener Nacht;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 2, 'alle Israeliten murrten über Mose und Aaron, und die ganze Gemeinde klagte vor ihnen: »Ach wären wir doch im Lande Ägypten gestorben! Oder wären wir doch hier in der Wüste gestorben!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 3, 'Warum führt uns der HERR in dieses Land? Damit wir durch das Schwert fallen? Damit unsere Frauen und kleinen Kinder (den Feinden) zur Beute werden? Ist es nicht das Beste für uns, wir kehren nach Ägypten zurück?«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 4, 'Und sie sagten einer zum andern: »Wir wollen uns einen Anführer wählen und nach Ägypten zurückkehren!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 5, 'Da warfen sich Mose und Aaron vor der ganzen versammelten Gemeinde der Israeliten auf ihr Angesicht nieder.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 6, 'Josua aber, der Sohn Nuns, und Kaleb, der Sohn Jephunnes, die zu denen gehörten, welche das Land ausgekundschaftet hatten, zerrissen ihre Kleider');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 7, 'und gaben vor der ganzen Gemeinde der Israeliten folgende Erklärung ab: »Das Land, das wir als Kundschafter durchzogen haben, ist ein außerordentlich schönes Land!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 8, 'Wenn der HERR uns wohlwill, so wird er uns schon in dieses Land bringen und es uns geben, ein Land, das von Milch und Honig überfließt.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 9, 'Nur empört euch nicht gegen den HERRN und fürchtet euch ja nicht vor den Bewohnern des Landes! Denn wie einen Bissen Brot werden wir sie verspeisen. Der Schutz ihrer Götter ist von ihnen gewichen, aber mit uns ist der HERR: fürchtet euch nicht vor ihnen!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 10, 'Als nun die ganze Gemeinde schon daran dachte, sie zu steinigen, erschien die Herrlichkeit des HERRN allen Israeliten am Offenbarungszelt;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 11, 'und der HERR sagte zu Mose: »Wie lange will dieses Volk mich noch verhöhnen und wie lange noch mir kein Vertrauen schenken trotz aller Wunderzeichen, die ich unter ihnen getan habe?');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 12, 'Ich will sie mit der Pest schlagen und sie ausrotten; dich aber will ich zu einem Volk machen, das größer und stärker ist als sie!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 13, 'Da erwiderte Mose dem HERRN: »Die Ägypter haben es vernommen, daß du dieses Volk mit deiner Kraft aus ihrer Mitte hergeführt hast,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 14, 'und man wird es auch den Bewohnern dieses Landes sagen, welche gehört haben, daß du, HERR, inmitten dieses Volkes weilst, daß du dich ihm Auge in Auge offenbarst und daß deine Wolke über ihnen steht und du in einer Wolkensäule bei Tage und in einer Feuersäule bei Nacht vor ihnen herziehst.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 15, 'Wenn du nun dieses Volk wie einen Mann tötest, so werden die Völkerschaften, welche die Kunde von dir vernommen haben, laut aussprechen:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 16, '›Weil der HERR nicht imstande war, dieses Volk in das Land zu bringen, das er ihnen zugeschworen hatte, darum hat er sie in der Wüste abgeschlachtet!‹');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 17, 'So möge sich denn jetzt deine Kraft, o HERR, groß erweisen, wie du es verheißen hast, als du sagtest:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 18, '›Der HERR ist langmütig und reich an Gnade; er vergibt Unrecht und Übertretung, läßt aber auch den Schuldigen keineswegs ungestraft, sondern sucht die Schuld der Väter an den Kindern heim bis ins dritte und vierte Glied.‹');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 19, 'So vergib doch diesem Volk seine Schuld nach deiner großen Gnade und so, wie du diesem Volke von Ägypten an bis hierher verziehen hast!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 20, 'Da antwortete der HERR: »Ich habe ihm vergeben, wie du es erbeten hast.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 21, 'Aber wahrlich, so wahr ich lebe und so wahr die ganze Erde von der Herrlichkeit des HERRN erfüllt werden soll:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 22, 'alle die Männer, die meine Herrlichkeit und meine Wunderzeichen, die ich in Ägypten und in der Wüste getan habe, gesehen und mich trotzdem nun schon zehnmal versucht und nicht auf meine Weisungen gehört haben –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 23, 'sie sollen das Land, das ich ihren Vätern zugeschworen habe, nicht zu sehen bekommen! Nein, keiner von allen, die mich verhöhnt haben, soll es zu sehen bekommen!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 24, 'Nur meinen Knecht Kaleb, der einen anderen Geist gezeigt und mir vollen Gehorsam bewiesen hat, den will ich in das Land bringen, das er schon einmal betreten hat, und seine Nachkommen sollen es besitzen;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 25, 'die Amalekiter aber und die Kanaanäer bleiben in der Niederung wohnen! Morgen kehrt um und brecht nach der Wüste auf in der Richtung nach dem Schilfmeer zu!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 26, 'Hierauf sagte der HERR zu Mose und Aaron:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 27, '»Wie lange soll es noch dauern, daß diese nichtswürdige Gemeinde gegen mich murrt? Ich habe das Murren wohl gehört, das die Israeliten gegen mich erheben.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 28, 'Sage ihnen: ›So wahr ich lebe!‹ – so lautet der Ausspruch des HERRN –: ›Ich will es euch genau so ergehen lassen, wie ihr es laut vor meinen Ohren ausgesprochen habt!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 29, 'In der Wüste hier sollen eure Leiber tot hinfallen, und zwar ihr alle, die gemustert worden sind, ihr alle vollzählig von zwanzig Jahren an und darüber, die ihr gegen mich gemurrt habt.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 30, 'Ihr sollt nimmermehr in das Land kommen, das ich euch durch einen Eid zum Wohnsitz zugesagt habe, keiner außer Kaleb, dem Sohne Jephunnes, und Josua, dem Sohne Nuns.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 31, 'Eure kleinen Kinder aber, von denen ihr gesagt habt, sie würden (den Feinden) zur Beute werden, die will ich hineinbringen, und sie sollen das Land kennen lernen, das ihr verschmäht habt;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 32, 'eure eigenen Leiber aber sollen in der Wüste hier tot hinfallen,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 33, 'und eure Söhne sollen vierzig Jahre lang als Hirten in der Wüste umherziehen und für euren treulosen Abfall von mir büßen, bis eure Leiber in der Wüste aufgerieben sind.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 34, 'Nach der Zahl der vierzig Tage, in denen ihr das Land ausgekundschaftet habt – immer ein Tag für ein Jahr gerechnet –, sollt ihr vierzig Jahre lang für eure Verschuldungen büßen und sollt erfahren, was es auf sich hat, wenn ich mich von euch abwende!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 35, 'Ich, der HERR, habe es ausgesprochen! Wahrlich, so will ich mit dieser ganzen nichtswürdigen Gemeinde verfahren, die sich gegen mich zusammengerottet hat: in der Wüste hier sollen sie aufgerieben werden, und hier sollen sie sterben!‹«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 36, 'Die Männer aber, die Mose zur Auskundschaftung des Landes ausgesandt hatte und die nach ihrer Rückkehr die ganze Gemeinde zum Murren gegen ihn durch ihren ungünstigen Bericht über das Land verleitet hatten –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 37, 'diese Männer, die über das Land ungünstig berichtet hatten, starben eines plötzlichen Todes vor dem HERRN.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 38, 'Nur Josua, der Sohn Nuns, und Kaleb, der Sohn Jephunnes, blieben am Leben von jenen Männern, die zur Auskundschaftung des Landes ausgezogen waren.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 39, 'Als nun Mose diese Drohworte des HERRN allen Israeliten mitgeteilt hatte, da geriet das Volk in tiefe Betrübnis.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 40, 'Sie machten sich also am andern Morgen in der Frühe fertig, auf die Höhe des Gebirges hinaufzuziehen, und sagten: »Wir sind jetzt bereit, in die Gegend hinaufzuziehen, von welcher der HERR geredet hat; denn wir haben gesündigt.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 41, 'Aber Mose antwortete: »Warum wollt ihr doch den Befehl des HERRN übertreten? Das wird euch nicht gelingen!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 42, 'Zieht ja nicht hinauf, denn der HERR ist nicht in eurer Mitte; ihr werdet sonst von euren Feinden geschlagen werden;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 43, 'denn die Amalekiter und Kanaanäer stehen euch dort gegenüber, und ihr werdet durch das Schwert fallen: durch euren Abfall vom HERRN habt ihr nun einmal verschuldet, daß der HERR nicht mit euch sein wird!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 44, 'Trotzdem blieben sie in ihrer Vermessenheit dabei, auf die Höhe des Gebirges hinaufzuziehen; doch die Lade mit dem Bundesgesetz des HERRN und Mose verließen das Innere des Lagers nicht.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 45, 'Da kamen die Amalekiter und Kanaanäer, die in jenem Gebirge wohnten, herab, schlugen sie und zersprengten sie bis Horma.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 1, 'Weiter gebot der HERR dem Mose folgendes:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 2, '»Teile den Israeliten folgende Verordnungen mit: Wenn ihr in das Land kommt, das ich euch zum Wohnsitz geben will,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 3, 'und ihr dem HERRN ein Feueropfer darbringen wollt, ein Brandopfer oder ein Schlachtopfer, sei es, um ein besonderes Gelübde zu erfüllen oder bei einer freiwilligen Gabe oder an euren Festen, um dem HERRN einen lieblichen Duft zu bereiten, von den Rindern oder vom Kleinvieh:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 4, 'so soll der, welcher dem HERRN seine Opfergabe darbringt, zugleich auch als Speisopfer ein Zehntel Epha Feinmehl darbringen, das mit einem Viertel Hin Öl gemengt ist;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 5, 'und an Wein zum Trankopfer sollst du neben dem Brandopfer oder zu dem Schlachtopfer noch ein Viertel Hin für jedes Lamm herrichten.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 6, 'Für einen Widder dagegen sollst du als Speisopfer zwei Zehntel Epha Feinmehl, das mit einem Drittel Hin Öl gemengt ist, herrichten');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 7, 'und an Wein zum Trankopfer ein Drittel Hin als lieblichen Duft für den HERRN darbringen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 8, 'Wenn du ferner ein junges Rind als Brandopfer oder als Schlachtopfer herrichten willst, um ein besonderes Gelübde zu erfüllen oder als Heilsopfer für den HERRN,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 9, 'so soll man neben dem jungen Rind noch drei Zehntel Epha Feinmehl, das mit einem halben Hin Öl gemengt ist, als Speisopfer darbringen;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 10, 'und an Wein sollst du als Trankopfer ein halbes Hin beim Feueropfer zu lieblichem Duft für den HERRN darbringen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 11, 'So soll es bei jedem Rind sowie bei jedem Widder und bei jedem Schaf- oder Ziegenlamm gehalten werden:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 12, 'nach der Zahl (der Tiere), die ihr darbringt, sollt ihr bei jedem einzelnen Stück so verfahren.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 13, 'Jeder Einheimische soll hierbei in dieser Weise verfahren, wenn er dem HERRN ein Feueropfer zu lieblichem Geruch darbringt;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 14, 'und wenn sich ein Fremdling als Gast bei euch aufhält oder wenn sonst einmal jemand in eurer Mitte weilt und ein Feueropfer zu lieblichem Geruch für den HERRN herrichtet, so soll er ebenso verfahren, wie ihr es tut.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 15, 'Für die ganze Bevölkerung gilt eine und dieselbe Satzung, für euch wie für den Fremdling, der sich als Gast bei euch aufhält; eine ewiggültige Satzung soll es für euch von Geschlecht zu Geschlecht sein: vor dem HERRN soll der Fremdling ebenso dastehen wie ihr selbst.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 16, 'Das gleiche Gesetz und das gleiche Recht soll für euch und für den Fremdling gelten, der sich als Gast bei euch aufhält.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 17, 'Weiter gebot der HERR dem Mose folgendes:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 18, '»Teile den Israeliten folgende Verordnungen mit: Wenn ihr in das Land kommt, in das ich euch bringen werde,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 19, 'so sollt ihr, wenn ihr von dem Brotkorn des Landes eßt, für den HERRN ein Hebeopfer abgeben.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 20, 'Als Erstling eures Schrotmehls sollt ihr einen Kuchen als Hebeopfer abgeben; wie die Hebe von der Tenne, ebenso sollt ihr auch diese abgeben.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 21, 'Von den Erstlingen eures Schrotmehls sollt ihr dem HERRN ein Hebeopfer abgeben in allen euren künftigen Geschlechtern.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 22, '»Und wenn ihr euch unabsichtlich vergeht und irgendeines von diesen Geboten, die der HERR dem Mose aufgetragen hat, unbefolgt laßt,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 23, 'irgend etwas von dem, was der HERR euch durch Mose geboten hat seit dem Tage, wo der HERR euch Gebote gegeben hat, und weiterhin von Geschlecht zu Geschlecht,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 24, 'so soll, wenn das Vergehen unabsichtlich von der Gemeinde in Übereilung begangen ist, die ganze Gemeinde einen jungen Stier als Brandopfer zu lieblichem Geruch für den HERRN samt dem zugehörigen Speisopfer und dem erforderlichen Trankopfer nach der vorgeschriebenen Weise herrichten, außerdem einen Ziegenbock als Sündopfer.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 25, 'Wenn der Priester so der ganzen Gemeinde der Israeliten Sühne erwirkt hat, so wird ihnen Vergebung zuteil werden; denn es hat nur ein Versehen stattgefunden, und sie haben dem HERRN ihre Opfergabe in Gestalt eines Feueropfers, dazu auch ihr Sündopfer vor dem HERRN wegen ihres Versehens dargebracht.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 26, 'So wird dann der ganzen Gemeinde der Israeliten sowie den Fremdlingen, die sich als Gäste bei ihnen aufhalten, Vergebung zuteil werden; denn es lag ein Versehen des ganzen Volkes vor.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 27, 'Wenn sich aber ein einzelner unabsichtlich verfehlt, so soll er eine einjährige Ziege als Sündopfer darbringen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 28, 'Wenn dann der Priester einem solchen, der sich unvorsätzlich ein Vergehen gegen den HERRN hat zuschulden kommen lassen, Sühne durch Vollziehung der Sühnegebräuche erwirkt hat, so wird ihm Vergebung zuteil werden.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 29, 'Für den Einheimischen unter den Israeliten und für den als Gast im Lande weilenden Fremdling soll die gleiche Bestimmung bei euch gelten, wenn sich jemand unvorsätzlich ein Vergehen zuschulden kommen läßt.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 30, 'Wenn sich aber jemand vorsätzlich vergeht, mag es ein Einheimischer oder ein Fremdling sein, ein solcher gilt als Gotteslästerer, und der Betreffende soll aus seinem Volk ausgerottet werden;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 31, 'denn er hat das Wort des HERRN verachtet und sein Gebot übertreten; ein solcher Mensch soll ohne Gnade ausgerottet werden: seine Schuld komme über ihn!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 32, 'Als die Israeliten sich in der Wüste befanden, trafen sie einen Mann, der am Sabbattage Holz auflas.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 33, 'Da brachten die, welche ihn beim Holzlesen angetroffen hatten, ihn zu Mose und Aaron und zu der ganzen Gemeinde,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 34, 'und man legte ihn in Gewahrsam; denn es lag noch keine Bestimmung darüber vor, was mit ihm geschehen solle.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 35, 'Da gebot der HERR dem Mose: »Der Mann soll unbedingt mit dem Tode bestraft werden: die ganze Gemeinde soll ihn außerhalb des Lagers steinigen!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 36, 'So führte ihn denn die ganze Gemeinde vor das Lager hinaus, und man warf ihn mit Steinen tot, wie der HERR dem Mose geboten hatte.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 37, 'Weiter gebot der HERR dem Mose folgendes:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 38, '»Gib den Israeliten die Weisung, daß sie sich Quasten an die Zipfel ihrer Obergewänder setzen, sie und ihre kommenden Geschlechter, und daß sie an jeder Zipfelquaste eine Schnur von blauem Purpur anbringen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 39, 'Die Quasten sollen euch dann dazu dienen, daß ihr bei ihrem Anblick aller Gebote des HERRN gedenkt, um nach ihnen zu tun und nicht von mir abzufallen nach den Gelüsten eures Herzens und eurer Augen, durch die ihr euch zum Treubruch verführen laßt.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 40, 'Ihr sollt vielmehr aller meiner Gebote eingedenk bleiben und nach ihnen tun und so eurem Gott geheiligt sein:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 41, 'ich bin der HERR, euer Gott, der euch aus dem Land Ägypten weggeführt hat, um euer Gott zu sein, ich, der HERR, euer Gott!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 1, 'Es empörte sich aber Korah, der Sohn Jizhars, des Sohnes Kahaths, des Sohnes Levis, und mit ihm Dathan und Abiram, die Söhne Eliabs, des Sohnes Pallus, des Sohnes Rubens.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 2, 'Diese empörten sich gegen Mose und mit ihnen zweihundertundfünfzig Israeliten, welche Vorsteher der Gemeinde, aus der Gemeindeversammlung berufene und hochangesehene Männer waren.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 3, 'Sie rotteten sich also gegen Mose und Aaron zusammen und sagten zu ihnen: »Ihr beansprucht für euch zu viel; denn die ganze Gemeinde, alle ohne Ausnahme sind heilig, weil der HERR in ihrer Mitte weilt: warum erhebt ihr euch da über die Gemeinde des HERRN?«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 4, 'Als Mose das hörte, warf er sich auf sein Angesicht nieder;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 5, 'dann sagte er zu Korah und seinem ganzen Anhang: »Morgen, da wird der HERR kundtun, wer ihm angehört und wer geweiht ist, so daß er ihn zu sich nahen läßt; wen er sich dann erwählt, den wird er zu sich nahen lassen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 6, 'Tut folgendes: Nehmt euch Räucherpfannen, du, Korah, und ihr, sein ganzer Anhang,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 7, 'tut morgen Feuer hinein und legt vor dem HERRN Räucherwerk darauf; wen dann der HERR erwählt, der soll als geweiht gelten! Damit gebt euch zufrieden, ihr Söhne Levis!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 8, 'Mose sagte dann weiter zu Korah: »Hört doch, ihr Söhne Levis!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 9, 'Genügt es euch nicht, daß der Gott Israels euch aus der Gemeinde der Israeliten ausgesondert hat, um euch zu sich nahen zu lassen, damit ihr den Dienst an der Wohnung des HERRN verrichtet und im Dienst der Gemeinde dieses Amt verwaltet?');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 10, 'Dich und alle deine Brüder mit dir, die Leviten, hat er zu sich nahen lassen, und nun verlangt ihr auch noch die Priesterwürde?');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 11, 'Somit rottet ihr euch gegen den HERRN zusammen, du und dein ganzer Anhang; denn was ist Aaron, daß ihr gegen ihn murrt?«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 12, 'Hierauf ließ Mose Dathan und Abiram, die Söhne Eliabs, durch Boten rufen; aber sie ließen sagen: »Wir kommen nicht zu dir hinauf!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 13, 'Ist es nicht genug, daß du uns aus einem Lande, das von Milch und Honig überfließt, hierher geführt hast, um uns in der Wüste sterben zu lassen? Willst du dich gar noch zum Herrscher über uns aufwerfen?');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 14, 'Du hast uns wahrlich nicht in ein Land gebracht, das von Milch und Honig überfließt, und uns keine Äcker und Weinberge zum Erbbesitz gegeben! Willst du etwa den Leuten hier Sand in die Augen streuen? Wir kommen nicht zu dir hinauf!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 15, 'Darüber geriet Mose in heftigen Zorn und betete zum HERRN: »Wende dich nicht zu ihrer Opfergabe! Keinem von ihnen habe ich auch nur einen Esel genommen und keinem von ihnen etwas zuleide getan!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 16, 'Hierauf sagte Mose zu Korah: »Du und dein ganzer Anhang, ihr mögt morgen vor dem HERRN erscheinen, du und sie und auch Aaron.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 17, 'Nehmt dann ein jeder seine Räucherpfanne und legt Räucherwerk darauf; dann bringe ein jeder seine Räucherpfanne vor den HERRN, zweihundertundfünfzig Räucherpfannen, auch du und Aaron, ein jeder seine Räucherpfanne!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 18, 'So nahmen sie denn ein jeder seine Räucherpfanne, taten feurige Kohlen hinein und legten Räucherwerk darauf; dann traten sie an den Eingang des Offenbarungszeltes, auch Mose und Aaron.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 19, 'Korah hatte aber die ganze Gemeinde am Eingang des Offenbarungszeltes gegen sie versammelt. Da erschien der ganzen Gemeinde die Herrlichkeit des HERRN;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 20, 'und der HERR gab dem Mose und Aaron folgende Weisung:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 21, '»Sondert euch von dieser Gemeinde ab: ich will sie in einem Augenblick vertilgen!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 22, 'Da warfen sie sich (beide) auf ihr Angesicht nieder und beteten: »O Gott, du Herr über Leben und Tod alles Fleisches! Willst du denn, wenn ein einzelner Mann gesündigt hat, der ganzen Gemeinde zürnen?«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 23, 'Da gebot der HERR dem Mose:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 24, '»Befiehl der Gemeinde, sich aus der Umgebung der Wohnung Korahs, Dathans und Abirams zu entfernen!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 25, 'Nun erhob sich Mose und begab sich zu Dathan und Abiram, und es folgten ihm die Ältesten der Israeliten.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 26, 'Dann gab er der Gemeinde die Weisung: »Entfernt euch ja von den Zelten dieser gottlosen Männer und rührt nichts von dem an, was ihnen gehört, damit ihr nicht auch hinweggerafft werdet um all ihrer Sünden willen!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 27, 'Da entfernten sie sich aus der Umgebung der Wohnung Korahs, Dathans und Abirams. Dathan und Abiram aber waren herausgetreten und standen mit ihren Frauen und ihren großen und kleinen Kindern im Eingang ihrer Zelte.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 28, 'Da sagte Mose: »Daran sollt ihr erkennen, daß der HERR es ist, der mich gesandt hat, um alle diese Taten zu vollbringen, und daß ich nicht nach eigenem Ermessen gehandelt habe:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 29, 'wenn diese hier so sterben, wie alle anderen Menschen sterben, und von dem gewöhnlichen Schicksal der Menschen betroffen werden, dann hat der HERR mich nicht gesandt;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 30, 'wenn aber der HERR etwas noch nie Vorgekommenes geschehen läßt und der Erdboden seinen Mund auftut und sie mit allem, was ihnen gehört, verschlingt, so daß sie lebendig in das Totenreich hinabfahren, so werdet ihr daran erkennen, daß diese Männer Verächter des HERRN gewesen sind!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 31, 'Kaum hatte er diese Worte zu Ende gesprochen, da spaltete sich der Erdboden unter ihren Füßen,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 32, 'und die Erde tat ihren Mund auf und verschlang sie samt ihren Familien sowie alle Anhänger Korahs mit ihrer gesamten Habe:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 33, 'lebend fuhren sie mit allem, was sie besaßen, in das Totenreich hinab, die Erde schloß sich über ihnen, und sie waren aus der Mitte der Gemeinde verschwunden.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 34, 'Alle Israeliten aber, die rings um sie her standen, flohen bei ihrem Geschrei; denn sie dachten, die Erde würde auch sie verschlingen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 35, 'Und es ging Feuer vom HERRN aus und verzehrte die zweihundertundfünfzig Männer, die das Räucherwerk dargebracht hatten.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 17, 1, 'Hierauf gebot der HERR dem Mose folgendes:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 17, 2, '»Befiehl Eleasar, dem Sohne des Priesters Aaron, er solle die Räucherpfannen von der Brandstätte aufheben und die feurigen Kohlen in einiger Entfernung von hier umherstreuen;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 17, 3, 'denn dem Heiligtum sind die Räucherpfannen dieser Männer verfallen, die durch ihre Sünde ihr Leben verwirkt haben. Man mache daraus breitgehämmerte Bleche zu einem Überzug für den Altar; denn da sie die Pfannen vor den HERRN gebracht haben, sind sie dem Heiligtum verfallen und sollen nun ein Wahrzeichen für die Israeliten bleiben.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 17, 4, 'Da nahm der Priester Eleasar die kupfernen Räucherpfannen, welche die vom Feuer Getöteten vor den HERRN gebracht hatten, und man hämmerte sie breit zu einem Überzug für den Altar.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 17, 5, 'So bildeten sie denn ein Erinnerungszeichen für die Israeliten, damit kein Unbefugter, der nicht zu den Nachkommen Aarons gehört, herantrete, um Räucherwerk vor dem HERRN zu verbrennen, und damit es ihm nicht ergehe wie Korah und seiner Rotte, wie der HERR es ihm durch Mose hatte ankündigen lassen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 17, 6, 'Am folgenden Tage aber murrte die ganze Gemeinde der Israeliten gegen Mose und Aaron; sie riefen: »Ihr habt das Volk des HERRN umgebracht!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 17, 7, 'Als sich nun die Gemeinde gegen Mose und Aaron zusammenrottete, wandten (diese) sich dem Offenbarungszelt zu, und siehe: die Wolke bedeckte es, und die Herrlichkeit des HERRN wurde sichtbar.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 17, 8, 'Als dann Mose und Aaron vor das Offenbarungszelt getreten waren,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 17, 9, 'gebot der HERR dem Mose:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 17, 10, '»Entfernt euch aus der Mitte dieser Gemeinde: ich will sie in einem Augenblick vernichten!« Da warfen sie sich auf ihr Angesicht nieder,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 17, 11, 'und Mose rief dem Aaron zu: »Nimm die Räucherpfanne, tu feurige Kohlen vom Altar hinein und leg Räucherwerk darauf! trage es dann eilends unter die Gemeinde und erwirke ihnen dadurch Sühne! Denn das Zorngericht ist bereits vom HERRN ausgegangen, und das Sterben hat schon begonnen!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 17, 12, 'Da nahm Aaron (die Räucherpfanne), wie Mose ihm befohlen hatte, und lief mitten in die Volksmenge hinein, wo das Sterben beim Volk wirklich schon begonnen hatte. Dann legte er Räucherwerk auf und erwirkte dem Volk dadurch Sühne;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 17, 13, 'denn als er mitten zwischen den Toten und den Lebenden dastand, wurde dem Sterben Einhalt getan.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 17, 14, 'Es belief sich aber die Zahl derer, die durch das Sterben ums Leben gekommen waren, auf 14700, abgesehen von denen, die um Korahs willen ihr Leben verloren hatten.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 17, 15, 'Hierauf kehrte Aaron zu Mose an den Eingang des Offenbarungszeltes zurück, als das Sterben ein Ende genommen hatte.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 17, 16, 'Darauf gebot der HERR dem Mose folgendes:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 17, 17, '»Rede mit den Israeliten und laß dir von ihnen je einen Stab für jeden Stamm geben, von allen ihren Fürsten Stamm für Stamm, zwölf Stäbe. Schreibe auf jeden Stab den Namen des betreffenden Fürsten;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 17, 18, 'auf den Stab Levis aber schreibe den Namen Aarons; denn ein Stab soll für jedes Haupt ihrer Stämme sein.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 17, 19, 'Dann lege sie im Offenbarungszelt vor der Gesetzeslade nieder, da, wo ich mich euch zu offenbaren pflege.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 17, 20, 'Da soll dann der Stab des Mannes, den ich mir erwähle, grünen, und ich will so dem Murren der Israeliten, das sie gegen euch erheben, ein Ende machen [damit es mich nicht nochmals belästigt].«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 17, 21, 'Als nun Mose dies den Israeliten mitgeteilt hatte, übergaben ihm alle ihre Fürsten, Stamm für Stamm, je einen Stab für jeden Fürsten, (im ganzen) zwölf Stäbe; auch der Stab Aarons war unter ihren Stäben.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 17, 22, 'Darauf legte Mose die Stäbe vor dem HERRN im Offenbarungszelt nieder.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 17, 23, 'Als nun Mose am folgenden Tage in das Offenbarungszelt hineinging, siehe, da hatte der Stab Aarons, der dem Stamme Levi angehörte, gesproßt, und zwar hatte er Schosse getrieben und Blüten hervorgebracht und trug reife Mandeln.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 17, 24, 'Mose holte nun alle Stäbe aus dem Heiligtum des HERRN heraus und legte sie allen Israeliten vor; diese besahen sie und nahmen ein jeder seinen Stab zurück.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 17, 25, 'Der HERR aber gebot dem Mose: »Bringe den Stab Aarons wieder vor die Gesetzeslade zurück; er soll dort als ein Mahnzeichen für die Widerspenstigen aufbewahrt werden, damit du ihrem Murren gegen mich ein Ende machst und sie nicht zu sterben brauchen.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 17, 26, 'Mose tat es; wie der HERR ihm geboten hatte, so tat er.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 17, 27, 'Die Israeliten aber sagten zu Mose: »Wehe! Wir kommen um, wir sind verloren, alle sind wir verloren!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 17, 28, 'Wer irgend der Wohnung des HERRN nahe kommt, muß sterben! Sollen wir denn rettungslos ums Leben kommen?«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 18, 1, 'Der HERR sagte dann zu Aaron: »Du und deine Söhne und das Haus deines Vaters mit dir, ihr sollt die Verfehlungen am Heiligtum auf euch nehmen; und du und deine Söhne mit dir, ihr habt die Verfehlungen an eurem Priesteramt zu tragen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 18, 2, 'Aber auch deine Brüder, den Stamm Levi, deinen väterlichen Stamm, laß mit dir herantreten: sie sollen sich dir anschließen und dir behilflich sein, während du und deine Söhne mit dir den Dienst vor dem Offenbarungszelt verrichtet.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 18, 3, 'Und zwar sollen sie das besorgen, was zu deiner Bedienung und zur Bedienung des ganzen Zeltes erforderlich ist; nur an die heiligen Geräte und an den Altar dürfen sie nicht herantreten, sonst müßt sowohl ihr als auch sie sterben.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 18, 4, 'Sie sollen sich also dir anschließen und den Dienst am Offenbarungszelt in seinem ganzen Umfang besorgen, und kein Unbefugter darf sich neben euch daran beteiligen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 18, 5, 'Ihr aber sollt den Dienst im Heiligtum und den Dienst am Altar verrichten, damit nicht nochmals ein Strafgericht über die Israeliten ergeht.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 18, 6, 'Bedenkt wohl: ich selbst habe eure Brüder, die Leviten, aus der Mitte der Israeliten als ein Geschenk für euch herausgenommen, als solche, die dem HERRN zu eigen gegeben sind, um den Dienst am Offenbarungszelt zu verrichten.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 18, 7, 'Du aber und deine Söhne mit dir, ihr habt eures Priesteramts zu warten bezüglich aller Geschäfte, die den Altar betreffen, und bezüglich aller Verrichtungen drinnen hinter dem Vorhange und sollt so den Dienst versehen; als einen geschenkten Dienst überweise ich euch das Priestertum; der Unbefugte aber, der es ausübt, soll den Tod erleiden.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 18, 8, 'Weiter sagte der HERR zu Aaron: »Ich selbst überweise dir hiermit das, was von meinen Hebeopfern (nicht verbrannt wird, sondern) den Abhub bildet: von allen heiligen Gaben der Israeliten verleihe ich sie dir und deinen Söhnen als Anteil, als eine ewige Gebühr.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 18, 9, 'Folgendes soll von den hochheiligen Gaben, soweit sie nicht verbrannt werden, dir zustehen: alles, was von ihnen dargebracht wird an Speisopfern sowie an Sündopfern und an Schuldopfern, die sie mir als Ersatz für Veruntreuungen darbringen; diese (Opfergaben) sollen dir und deinen Söhnen als etwas Hochheiliges zustehen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 18, 10, 'An einer hochheiligen Stätte sollst du sie verzehren; jede männliche Person darf davon essen; als heilig sollen sie dir gelten.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 18, 11, 'Auch folgendes soll dir als Hebe von ihren Gaben zustehen: alle Webeopfer der Israeliten; dir und deinen Söhnen und Töchtern mit dir weise ich sie als eine ewige Gebühr zu: wer rein ist in deinem Hause, darf davon essen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 18, 12, 'Alles Beste vom Öl und alles Beste vom Most und vom Getreide, ihre Erstlingsgaben, die sie dem HERRN weihen, das weise ich dir zu:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 18, 13, 'die Erstlinge von allen Früchten, die in ihrem Lande wachsen und die sie dem HERRN darbringen, sollen dir gehören: wer rein ist in deinem Hause, darf davon essen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 18, 14, 'Alles, was in Israel mit dem Bann belegt worden ist, soll dir gehören.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 18, 15, 'Alles Erstgeborene von allem Fleisch, das man dem HERRN darzubringen hat, vom Menschen wie vom Vieh, soll dir gehören; jedoch sollst du die Erstgeburten der Menschen unbedingt lösen lassen, und auch die Erstgeburten der unreinen Tiere sollst du lösen lassen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 18, 16, 'Was aber die Lösung (einer menschlichen Erstgeburt) betrifft, so sollst du sie im Alter von einem Monat an lösen lassen, und zwar nach deiner Schätzung, für einen Betrag von fünf Schekeln Silber nach dem Schekel des Heiligtums, der zwanzig Gera beträgt.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 18, 17, 'Jedoch das Erstgeborene eines Rindes oder das Erstgeborene eines Schafes oder einer Ziege darfst du nicht lösen lassen, sie sind heilig; ihr Blut sollst du an den Altar sprengen und ihr Fett als Feueropfer zum lieblichen Geruch für den HERRN in Rauch aufgehen lassen;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 18, 18, 'ihr Fleisch aber soll dir gehören: wie die Webebrust und wie die rechte Keule soll es dir gehören.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 18, 19, 'Alle Hebeopfer von heiligen Gaben, welche die Israeliten dem HERRN von ihrem Besitz darbringen, überweise ich dir und deinen Söhnen und Töchtern bei dir als ewige Gebühr: das soll ein ewiger Salzbund vor dem HERRN für dich und deine Nachkommen bei dir sein!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 18, 20, 'Weiter sagte der HERR zu Aaron: »In ihrem Lande sollst du keinen Erbbesitz haben und keinen Teil des Landes unter ihnen besitzen: ich bin dein Anteil und dein Erbbesitz inmitten der Israeliten!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 18, 21, '(Als Entgelt) aber überweise ich hiermit den Leviten alle Zehnten in Israel zum Erbbesitz für ihren Dienst, den sie zu verrichten haben, für den Dienst am Offenbarungszelte.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 18, 22, 'Die Israeliten nämlich dürfen künftighin am Offenbarungszelt nicht mehr tätig sein, weil sie sonst Sünde auf sich laden würden und sterben müßten.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 18, 23, 'Vielmehr sollen die Leviten den Dienst am Offenbarungszelt verrichten, und sie sollen für etwaige Verfehlungen verantwortlich sein: diese Bestimmung hat ewige Geltung für eure künftigen Geschlechter. Aber einen Erbbesitz sollen sie inmitten der Israeliten nicht haben;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 18, 24, 'denn den Zehnten, den die Israeliten als Hebeopfer an den HERRN abgeben, habe ich den Leviten als Erbbesitz überwiesen; darum habe ich in bezug auf sie verordnet, daß sie keinen Erbbesitz inmitten der Israeliten zu eigen haben sollen.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 18, 25, 'Weiter gebot der HERR dem Mose folgendes:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 18, 26, '»Teile den Leviten folgende Verordnungen mit: Wenn ihr von den Israeliten den Zehnten in Empfang nehmt, den ich euch von ihnen als euren Erbbesitz zugewiesen habe, so sollt ihr davon ein Hebeopfer für den HERRN abgeben, nämlich den Zehnten vom Zehnten.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 18, 27, 'Dann soll dies euer Hebeopfer euch so angerechnet werden, wie (wenn die anderen Israeliten) das Getreide von der Tenne und die Fülle von der Kelter (abgeben).');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 18, 28, 'Ebenso sollt auch ihr ein Hebeopfer für den HERRN von allen euren Zehnten abgeben, die ihr von den Israeliten in Empfang nehmt, und sollt davon das Hebeopfer, das dem HERRN gebührt, an den Priester Aaron abführen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 18, 29, 'Von allen Gaben, die euch zufallen, sollt ihr ein unverkürztes Hebeopfer für den HERRN abgeben, und zwar von allem Besten davon, als die davon zu entrichtende heilige Gebühr.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 18, 30, 'Sage also zu ihnen: ›Wenn ihr das Beste davon abgebt, so soll (das übrige) euch, den Leviten, so angerechnet werden wie (den anderen Israeliten) der Ertrag der Tenne und wie der Ertrag der Kelter,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 18, 31, 'so daß ihr es an jedem beliebigen Ort verzehren dürft, ihr und eure Familie; denn es ist euer Lohn für euren Dienst am Offenbarungszelt.‹');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 18, 32, 'Wenn ihr also das Beste davon abgebt, so werdet ihr seinetwegen keine Sünde auf euch laden und werdet die heiligen Gaben der Israeliten nicht entweihen und darum auch nicht sterben müssen.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 19, 1, 'Der HERR sagte dann weiter zu Mose und Aaron folgendes:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 19, 2, '»Dies ist die Gesetzesbestimmung, die der HERR erlassen hat durch die Verordnung: Sage den Israeliten, sie sollen dir eine fehlerlose, rötliche Kuh bringen, die kein Gebrechen an sich hat und auf die noch kein Joch gekommen ist.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 19, 3, 'Die sollt ihr dem Priester Eleasar übergeben, und man soll sie dann vor das Lager hinausführen und sie vor seinen Augen schlachten.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 19, 4, 'Hierauf nehme der Priester Eleasar mit seinem Finger etwas von ihrem Blut und sprenge siebenmal von ihrem Blut in der Richtung nach der Vorderseite des Offenbarungszeltes hin.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 19, 5, 'Dann verbrenne man die Kuh vor seinen Augen: alles, ihre Haut, ihr Fleisch und ihr Blut samt dem Inhalt ihrer Eingeweide soll man verbrennen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 19, 6, 'Hierauf nehme der Priester Zedernholz, Ysop und Karmesinwolle und werfe es mitten in das Feuer, in welchem die Kuh verbrannt wird.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 19, 7, 'Dann wasche der Priester seine Kleider und nehme ein Wasserbad; hierauf darf er wieder ins Lager kommen, bleibt jedoch bis zum Abend unrein.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 19, 8, 'Auch derjenige, welcher die Kuh verbrannt hat, muß seine Kleider im Wasser waschen und ein Wasserbad nehmen und bleibt bis zum Abend unrein.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 19, 9, 'Dann soll ein Mann, der rein ist, die Asche der Kuh sammeln und sie außerhalb des Lagers an einen reinen Platz hinschütten, damit sie dort für die Gemeinde der Israeliten zur Herstellung von Reinigungswasser aufbewahrt werde: es ist ein Entsündigungsmittel.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 19, 10, 'Auch der Mann, welcher die Asche der Kuh gesammelt hat, muß seine Kleider waschen und ist dann noch bis zum Abend unrein. Es soll dann aber für die Israeliten und für die Fremdlinge, die sich als Gäste unter ihnen aufhalten, folgende Vorschrift ewige Geltung haben:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 19, 11, 'Wer einen Toten, irgendeine Menschenleiche, berührt, soll sieben Tage lang unrein sein.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 19, 12, 'Ein solcher Mensch soll sich damit am dritten und am siebten Tage entsündigen, dann ist er wieder rein; wenn er sich aber am dritten und am siebten Tage nicht entsündigt, so wird er nicht rein.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 19, 13, 'Wer einen Toten, die Leiche irgendeines gestorbenen Menschen, berührt und sich danach nicht entsündigt, der hat die Wohnung des HERRN verunreinigt, und ein solcher Mensch soll aus Israel ausgerottet werden. Weil er nicht mit Reinigungswasser besprengt worden ist, bleibt er unrein: seine Unreinheit bleibt an ihm haften.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 19, 14, '»Folgende Bestimmung gilt, wenn jemand in einem Zelte stirbt: Jeder, der in das Zelt hineingeht, und jeder, der sich im Zelte befindet, ist sieben Tage lang unrein;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 19, 15, 'auch jedes offene Gefäß, auf dem sich kein festschließender Deckel befindet, ist unrein.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 19, 16, 'Ebenso soll jeder, der auf freiem Feld einen mit dem Schwert Erschlagenen oder sonst einen Toten oder menschliche Gebeine oder ein Grab anrührt, sieben Tage lang unrein sein.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 19, 17, 'Für einen so unrein Gewordenen nehme man etwas von der Asche des zur Entsündigung verbrannten Opfertieres und gieße lebendiges Wasser in ein Gefäß darüber.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 19, 18, 'Dann nehme ein reiner Mann einen Ysopbüschel, tauche ihn in das Wasser und besprenge damit das Zelt samt allen Geräten und die darin befindlichen Personen sowie den, der mit Totengebeinen oder einem Erschlagenen oder einem Toten oder einem Grabe in Berührung gekommen ist.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 19, 19, 'Und zwar soll der Reine den Unreinen am dritten und am siebten Tage besprengen und ihn so am siebten Tage entsündigen. Alsdann soll der Betreffende seine Kleider waschen und ein Wasserbad nehmen, dann wird er am Abend wieder rein sein.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 19, 20, 'Wenn aber jemand unrein wird und sich nicht entsündigt, so soll ein solcher Mensch aus der Gemeinde ausgerottet werden; denn er hat das Heiligtum des HERRN verunreinigt und ist nicht mit dem Reinigungswasser besprengt worden: er ist unrein.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 19, 21, 'Diese Verordnung soll bei euch ewige Geltung haben. Und auch der, welcher die Besprengung mit dem Reinigungswasser vorgenommen hat, muß seine Kleider waschen, und wer das Reinigungswasser berührt, soll bis zum Abend unrein sein.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 19, 22, 'Auch alles, was der Unreine anrührt, wird unrein, und ebenso wird jeder, der ihn berührt, bis zum Abend unrein.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 20, 1, 'Hierauf gelangte die ganze Gemeinde der Israeliten in die Wüste Zin im ersten Monat (des vierzigsten Jahres), und das Volk ließ sich in Kades nieder. Dort starb Mirjam und wurde dort begraben.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 20, 2, 'Weil aber die Gemeinde kein Wasser hatte, rottete sie sich gegen Mose und Aaron zusammen;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 20, 3, 'und das Volk haderte mit Mose und rief laut aus: »Ach, wären wir doch auch umgekommen, als unsere Brüder vor dem HERRN umkamen!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 20, 4, 'Warum habt ihr nur die Gemeinde des HERRN in diese Wüste geführt, daß wir hier mit unserem Vieh sterben müssen!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 20, 5, 'Und warum habt ihr uns aus Ägypten hierher gebracht und uns in diese traurige Gegend geführt, an einen Ort, wo man nicht säen kann und wo kein Feigenbaum, kein Weinstock und kein Granatbaum zu finden ist und wo es nicht einmal Trinkwasser gibt!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 20, 6, 'Da gingen Mose und Aaron aus der Versammlung weg an den Eingang des Offenbarungszeltes und warfen sich auf ihr Angesicht nieder; da erschien ihnen die Herrlichkeit des HERRN.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 20, 7, 'Und der HERR gebot dem Mose folgendes: »Nimm den Stab und versammle die Gemeinde, du und dein Bruder Aaron; redet dann den Felsen vor ihren Augen an, daß er sein Wasser hergeben solle,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 20, 8, 'so wirst du Wasser für sie aus dem Felsen hervorfließen lassen und so der Gemeinde und ihrem Vieh Trinkwasser verschaffen.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 20, 9, 'Da holte Mose den Stab vor dem HERRN weg, wie der HERR ihm geboten hatte.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 20, 10, 'Darauf ließen Mose und Aaron die Gemeinde vor dem Felsen zusammenkommen, und er sagte zu ihnen: »Hört doch, ihr Widerspenstigen! Können wir wohl Wasser für euch aus diesem Felsen hervorfließen lassen?«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 20, 11, 'Als Mose dann seine Hand erhoben und zweimal mit seinem Stabe an den Felsen geschlagen hatte, da strömte Wasser in Fülle heraus, so daß die Gemeinde und ihr Vieh zu trinken hatten.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 20, 12, 'Der HERR aber sagte zu Mose und Aaron: »Zur Strafe dafür, daß ihr mir kein Vertrauen geschenkt und mir nicht als dem Heiligen die Ehre vor den Augen der Israeliten gegeben habt, darum sollt ihr diese Gemeinde nicht in das Land bringen, das ich für sie bestimmt habe!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 20, 13, 'Das ist das Haderwasser (von Kades), wo die Israeliten mit dem HERRN gehadert haben und er sich an ihnen als der Heilige erwies.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 20, 14, 'Von Kades aus sandte Mose dann Boten an den König der Edomiter: »So lassen dir deine Brüder, die Israeliten, sagen: Du kennst selbst alle Leiden, die uns betroffen haben,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 20, 15, 'wie unsere Väter nach Ägypten hinabgezogen sind und wir lange Zeit in Ägypten gewohnt haben. Als dann die Ägypter uns und unsere Väter mißhandelten,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 20, 16, 'haben wir zum HERRN um Hilfe geschrien, und er hat unser Flehen gehört und einen Engel gesandt, der uns aus Ägypten hinausgeführt hat. Jetzt befinden wir uns nun in Kades, einer Stadt an der Grenze deines Gebietes.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 20, 17, 'Gestatte uns doch den Durchzug durch dein Land! Wir wollen nicht durch die Äcker und durch die Weinberge ziehen, auch kein Wasser aus den Brunnen trinken; nein, auf der Königsstraße wollen wir ziehen, ohne nach rechts und nach links abzubiegen, bis wir dein Gebiet durchzogen haben.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 20, 18, 'Aber der Edomiter antwortete ihm: »Du darfst nicht durch mein Land ziehen, sonst trete ich dir mit bewaffneter Hand entgegen.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 20, 19, 'Darauf ließen ihm die Israeliten sagen: »Auf der Landstraße wollen wir ziehen, und wenn wir von deinem Wasser trinken, ich und meine Herden, so will ich den vollen Preis dafür bezahlen; ich will nur – das ist die ganze Sache – zu Fuß hindurchziehen.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 20, 20, 'Doch er antwortete: »Nein, du darfst nicht hindurchziehen!« Zugleich zogen die Edomiter ihm mit zahlreichem Kriegsvolk und mit bewaffneter Hand entgegen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 20, 21, 'Da die Edomiter also den Israeliten den Durchzug durch ihr Gebiet nicht gestatten wollten, mußten die Israeliten seitwärts von ihnen abbiegen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 20, 22, 'So brachen sie denn von Kades auf, und die Israeliten, die ganze Gemeinde, kamen an den Berg Hor.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 20, 23, 'Da sagte der HERR zu Mose und zu Aaron am Berge Hor, an der Grenze des Edomiterlandes:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 20, 24, '»Aaron soll jetzt zu seinen Volksgenossen versammelt werden; denn er soll nicht in das Land kommen, das ich für die Israeliten bestimmt habe, weil ihr beim Haderwasser meinem Gebot nicht nachgekommen seid.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 20, 25, 'Nimm Aaron und seinen Sohn Eleasar und laß sie auf den Berg Hor hinaufsteigen;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 20, 26, 'laß dort Aaron seine Gewänder ausziehen und lege sie seinem Sohne Eleasar an; denn Aaron soll (zu seinen Volksgenossen) versammelt werden und dort sterben.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 20, 27, 'Mose tat, wie der HERR ihm geboten hatte, und sie stiegen vor den Augen der ganzen Gemeinde auf den Berg Hor hinauf.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 20, 28, 'Dort ließ Mose den Aaron seine Gewänder ausziehen und legte sie dessen Sohne Eleasar an; darauf starb Aaron dort auf dem Gipfel des Berges; Mose aber und Eleasar stiegen wieder vom Berge hinab.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 20, 29, 'Als nun die ganze Gemeinde erfuhr, daß Aaron gestorben sei, trauerte das ganze Haus Israel um Aaron dreißig Tage lang.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 1, 'Als nun der kanaanäische König von Arad, der im Südland wohnte, die Kunde erhielt, daß die Israeliten auf dem Wege von Atharim heranzögen, griff er die Israeliten an und nahm einige von ihnen gefangen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 2, 'Da legten die Israeliten ein Gelübde vor dem HERRN ab und versprachen: »Wenn du dieses Volk in unsere Gewalt gibst, so wollen wir an ihren Ortschaften den Bann vollstrecken.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 3, 'Da erhörte der HERR die Bitte der Israeliten und gab ihnen die Kanaanäer preis. Man vollstreckte dann an ihnen und ihren Ortschaften den Bann und nannte die Stätte seitdem Horma.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 4, 'Dann brachen sie vom Berge Hor auf in der Richtung nach dem Schilfmeer, um das Land der Edomiter zu umgehen. Unterwegs aber wurde das Volk mißmutig');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 5, 'und erhob Anklage gegen Gott und gegen Mose: »Warum habt ihr uns aus Ägypten hierher geführt? Um uns in der Wüste sterben zu lassen? Es gibt hier ja weder Brot noch Wasser, und uns ekelt vor diesem erbärmlichen Brotzeug!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 6, 'Da sandte der HERR feurige Schlangen unter das Volk; die bissen die Leute, so daß zahlreiche Israeliten starben.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 7, 'Da kam das Volk zu Mose und bekannte: »Wir haben gesündigt, daß wir Anklagen gegen den HERRN und gegen dich erhoben haben; lege Fürbitte beim HERRN ein, daß er uns von den Schlangen befreie!« Als Mose nun Fürbitte für das Volk einlegte,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 8, 'sagte der HERR zu ihm: »Fertige dir ein Schlangenbild an und befestige es an einer Stange; wer dann gebissen ist und es anschaut, soll am Leben bleiben.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 9, 'Da fertigte Mose eine eherne Schlange an und befestigte sie oben an einer Stange. Wenn nun eine Schlange jemanden gebissen hatte und er auf die eherne Schlange hinschaute, so blieb er am Leben.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 10, 'Darauf zogen die Israeliten weiter und lagerten bei Oboth.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 11, 'Dann zogen sie von Oboth weiter und lagerten bei Ijje-Abarim in der Wüste, die vor dem Lande der Moabiter nach Osten liegt.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 12, 'Von dort zogen sie weiter und lagerten im Bachtal Sered.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 13, 'Von dort zogen sie weiter und lagerten jenseits des Arnon, [der in der Wüste ist,] der im Lande der Amoriter entspringt; der Arnon bildet nämlich die Grenze Moabs zwischen den Moabitern und Amoritern.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 14, 'Daher heißt es im Buch der Kriege des HERRN: »Waheb in Supha, dazu die Bachtäler des Arnon');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 15, 'und den Abhang der Bachtäler, der bis in die Gegend von Ar reicht und sich an die Grenze von Moab anlehnt.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 16, 'Von dort (zogen sie) dann nach Beer; das ist der Brunnen, den der HERR meinte, als er zu Mose sagte: »Versammle das Volk, damit ich ihm Wasser gebe.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 17, 'Damals sangen die Israeliten folgendes Lied: »Quill empor, o Brunnen! Singt ihm zu:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 18, '›O Brunnen, den Fürsten gegraben, den die Edlen des Volks erschlossen haben mit dem Zepter, mit ihren Stäben!‹« Aus der Wüste (zogen sie) dann nach Matthana,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 19, 'von Matthana nach Nahaliel, von Nahaliel nach Bamoth,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 20, 'von Bamoth in das Tal, das in der moabitischen Ebene liegt an der Höhe des Pisga, der auf die weite Einöde hinabblickt.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 21, 'Darauf sandten die Israeliten Boten zu Sihon, dem König der Amoriter, und ließen ihm sagen:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 22, '»Gestatte uns den Durchzug durch dein Land! Wir wollen nicht auf die Äcker und in die Weinberge abbiegen, auch kein Wasser aus den Brunnen trinken; nein, wir wollen auf der Königsstraße ziehen, bis wir dein Gebiet durchzogen haben.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 23, 'Aber Sihon gestattete den Israeliten den Durchzug durch sein Gebiet nicht, sondern sammelte sein gesamtes Kriegsvolk und zog den Israeliten in die Wüste entgegen; und als er nach Jahaz gekommen war, griff er die Israeliten an.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 24, 'Diese aber schlugen ihn mit der Schärfe des Schwertes und eroberten sein Land vom Arnon bis zum Jabbok, bis an das Land der Ammoniter; denn Jaser liegt an der Grenze des Ammoniterlandes.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 25, 'So nahmen denn die Israeliten alle dortigen Städte ein und ließen sich in allen Städten der Amoriter nieder, in Hesbon und allen dazugehörigen Ortschaften.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 26, 'Denn Hesbon war die Hauptstadt des Amoriterkönigs Sihon; dieser hatte nämlich mit dem vorigen Könige der Moabiter Krieg geführt und ihm sein ganzes Land bis an den Arnon abgenommen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 27, 'Darum singen die Dichter: Kommt nach Hesbon! Aufgebaut und befestigt werde die Stadt Sihons!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 28, 'Denn Feuer ging (einst) aus von Hesbon, eine Flamme von der Stadt Sihons; die fraß die Städte Moabs und verbrannte die Höhen am Arnon.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 29, 'Wehe dir, Moab! Dem Untergang geweiht bist du, Volk des Kamos, der seine Söhne zu Flüchtlingen gemacht hat und seine Töchter zu Gefangenen für Sihon, den Amoriterkönig.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 30, 'Da haben wir (Moab) niedergeschossen, Hesbon ist verlorengegangen bis Dibon; da haben wir verwüstet bis Nophah: Feuer ging aus bis Medeba.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 31, 'Als sich nun die Israeliten im Lande der Amoriter festgesetzt hatten,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 32, 'sandte Mose Männer aus, um Jaser auszukundschaften, und sie nahmen dann die Stadt und die dazugehörigen Ortschaften ein, und man vertrieb die dort ansässigen Amoriter.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 33, 'Hierauf wandten sie sich und zogen in der Richtung nach Basan hinauf. Da rückte Og, der König von Basan, mit seinem gesamten Kriegsvolk ihnen nach Edrei entgegen, um ihnen eine Schlacht zu liefern.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 34, 'Der HERR aber sagte zu Mose: »Fürchte dich nicht vor ihm! Denn ich habe ihn mit seinem ganzen Volk und seinem Land in deine Gewalt gegeben: verfahre mit ihm so, wie du mit dem Amoriterkönig Sihon, der in Hesbon wohnte, verfahren bist.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 35, 'Da erschlugen sie ihn nebst seinen Söhnen und seinem ganzen Kriegsvolk, so daß ihm auch nicht einer übrigblieb, der entronnen wäre, und nahmen sein Land in Besitz.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 1, 'Hierauf zogen die Israeliten weiter und lagerten in den Steppen der Moabiter jenseits des Jordans, Jericho gegenüber.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 2, 'Als nun Balak, der Sohn Zippors, alles Unheil sah, das die Israeliten den Amoritern zugefügt hatten,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 3, 'überkam die Moabiter eine große Angst vor dem Volk (Israel), weil es so zahlreich war, und sie empfanden ein Grauen vor den Israeliten.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 4, 'Da sagten die Moabiter zu den Ältesten der Midianiter: »Nun wird dieser Schwarm alles rings um uns her kahlfressen, wie die Rinder das Grün des Feldes abfressen!« Damals war aber Balak, der Sohn Zippors, König der Moabiter.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 5, 'Dieser sandte Boten zu Bileam, dem Sohne Beors, nach Pethor, das am Euphratstrom liegt, ins Land seiner Volksgenossen, um ihn holen zu lassen, und ließ ihm sagen: »Da ist ein Volk aus Ägypten ausgezogen, das hat sich jetzt über das ganze Land ausgebreitet und sich mir gegenüber festgesetzt.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 6, 'So komm nun doch her und verfluche mir dieses Volk; denn mir ist es zu stark; vielleicht gelingt es mir dann, eine Niederlage unter ihnen anzurichten und es aus dem Lande zu vertreiben; denn ich weiß: wen du segnest, der ist gesegnet, und wem du fluchst, der ist verflucht.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 7, 'Da machten sich die Ältesten der Moabiter samt den Ältesten der Midianiter, nachdem sie sich mit Wahrsagerlohn versehen hatten, auf den Weg, kamen glücklich bei Bileam an und teilten ihm das Anliegen Balaks mit.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 8, 'Er aber antwortete ihnen: »Bleibt diese Nacht hier, dann will ich euch Bescheid geben, je nachdem der HERR mir Weisung erteilt.« So blieben denn die Fürsten der Moabiter bei Bileam.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 9, 'Da erschien Gott dem Bileam im Traum und fragte ihn: »Was sind das für Männer bei dir?«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 10, 'Bileam antwortete Gott: »Balak, der Sohn Zippors, der König der Moabiter, hat mir durch sie sagen lassen:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 11, '›Da ist ein Volk, das aus Ägypten ausgezogen ist und sich über das ganze Land ausgebreitet hat. So komm nun her und verfluche es mir; vielleicht vermag ich dann den Kampf mit ihm aufzunehmen und es zu vertreiben.‹«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 12, 'Gott aber sagte zu Bileam: »Du darfst nicht mit ihnen gehen! Du darfst das Volk nicht verfluchen; denn es ist gesegnet.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 13, 'Als Bileam nun am Morgen aufgestanden war, sagte er zu den Häuptlingen Balaks: »Kehrt in euer Land zurück; denn der HERR hat mir die Erlaubnis versagt, mit euch zu ziehen.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 14, 'So machten sich denn die Häuptlinge der Moabiter auf den Weg, kehrten zu Balak zurück und berichteten ihm: »Bileam hat sich geweigert, mit uns zu gehen.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 15, 'Da sandte Balak noch einmal Fürsten ab, die zahlreicher und vornehmer waren als die ersten.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 16, 'Als diese zu Bileam kamen, sagten sie zu ihm: »So läßt Balak, der Sohn Zippors, dir sagen: ›Weigere dich doch nicht, zu mir zu kommen!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 17, 'Denn ich will dich gar hoch ehren und alles tun, was du von mir verlangen wirst. So komm doch her und verfluche mir dieses Volk!‹«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 18, 'Bileam aber gab den Gesandten Balaks die Antwort: »Wenn Balak mir auch alles Silber und Gold geben wollte, soviel in seinen Palast geht, so vermöchte ich doch den Befehl des HERRN, meines Gottes, nicht zu übertreten, weder im Großen noch im Kleinen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 19, 'Indessen – bleibt doch auch ihr diese Nacht hier, damit ich in Erfahrung bringe, was der HERR mir weiter zu sagen hat.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 20, 'Da erschien Gott dem Bileam in der Nacht und sagte zu ihm: »Wenn die Männer gekommen sind, um dich zu holen, so mache dich auf und gehe mit ihnen; aber du darfst nur das tun, was ich dir sagen werde.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 21, 'Da machte sich Bileam am Morgen auf, sattelte seine Eselin und machte sich mit den Häuptlingen der Moabiter auf den Weg.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 22, 'Da entbrannte aber der Zorn Gottes darüber, daß er sich aufgemacht hatte, und der Engel des HERRN stellte sich ihm in den Weg, um ihm feindlich entgegenzutreten, während er auf seiner Eselin dahinritt und zwei seiner Diener ihn begleiteten.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 23, 'Als nun die Eselin den Engel des HERRN sah, der mit gezücktem Schwert in der Hand ihm den Weg vertrat, bog sie vom Wege ab und ging ins Feld; da schlug Bileam die Eselin, um sie wieder auf den Weg zu bringen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 24, 'Hierauf stellte sich der Engel des HERRN in einem Hohlwege zwischen den Weinbergen auf, wo zu beiden Seiten eine Mauer war.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 25, 'Als nun die Eselin den Engel des HERRN erblickte, drückte sie sich fest an die Mauer und preßte dabei den Fuß Bileams gegen die Mauer; da schlug er sie zum zweitenmal.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 26, 'Hierauf ging der Engel des HERRN nochmals eine Strecke weiter und blieb an einer engen Stelle stehen, wo ein Ausweichen nach rechts oder links unmöglich war.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 27, 'Als nun die Eselin den Engel des HERRN erblickte, legte sie sich unter Bileam auf den Boden nieder. Da geriet Bileam in Zorn, so daß er die Eselin mit dem Stock schlug.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 28, 'Der HERR aber tat der Eselin den Mund auf, und sie sagte zu Bileam: »Was habe ich dir getan, daß du mich nun schon dreimal geschlagen hast?«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 29, 'Bileam antwortete der Eselin: »Weil du mich zum besten gehabt hast! Hätte ich nur ein Schwert in der Hand, so hätte ich dich längst umgebracht!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 30, 'Da sagte die Eselin zu Bileam: »Bin ich nicht deine Eselin, auf der du zeit deines Lebens bis auf den heutigen Tag geritten bist? Ist es denn jemals meine Art gewesen, mich so gegen dich zu benehmen?« Er antwortete: »Nein.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 31, 'Nun tat der HERR dem Bileam die Augen auf, so daß er den Engel des HERRN auf dem Wege mit dem gezückten Schwert in der Hand stehen sah. Da verneigte er sich und warf sich auf sein Angesicht nieder.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 32, 'Der Engel des HERRN aber sagte zu ihm: »Warum hast du deine Eselin nun schon dreimal geschlagen? Wisse wohl: ich habe mich aufgemacht, um dir feindlich entgegenzutreten; denn diese deine Reise ist unheilvoll und gegen meinen Willen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 33, 'Die Eselin aber hat mich gesehen und ist alle drei Male vor mir ausgewichen; hätte sie das nicht getan, so hätte ich dich längst erschlagen, sie aber am Leben gelassen.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 34, 'Da sagte Bileam zu dem Engel des HERRN: »Ich habe mich vergangen; ich wußte ja nicht, daß du mir auf dem Wege entgegenstandest. Nun aber will ich, wenn mein Vorhaben dir mißfällt, wieder umkehren!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 35, 'Da antwortete der Engel des HERRN dem Bileam: »Gehe mit den Männern hin; aber du darfst nur das reden, was ich dir eingeben werde.« So zog nun Bileam mit den Häuptlingen Balaks weiter.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 36, 'Als nun Balak hörte, daß Bileam komme, zog er ihm bis Ar-Moab entgegen, das am Grenzfluß Arnon, an der äußersten Grenze seines Landes, lag.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 37, 'Da sagte Balak zu Bileam: »Habe ich nicht in angemessener Weise zu dir gesandt, um dich rufen zu lassen? Warum bist du nicht sofort zu mir gekommen? Meinst du vielleicht, ich sei nicht imstande, dich zu ehren?«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 38, 'Da antwortete ihm Bileam: »Ich bin jetzt ja doch zu dir gekommen; aber werde ich wohl irgend etwas kundtun können? Nur die Worte, die der HERR mir in den Mund legt, die werde ich kundtun.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 39, 'So ging denn Bileam mit Balak, bis sie nach Kirjath-Huzoth kamen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 40, 'Dort schlachtete Balak Rinder und Kleinvieh und schickte davon an Bileam und an die Fürsten, die bei ihm waren.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 41, 'Am folgenden Morgen aber nahm Balak den Bileam mit sich und führte ihn nach Bamoth-Baal hinauf, von wo er den äußersten Teil des (israelitischen) Volkes sehen konnte.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 23, 1, 'Da sagte Bileam zu Balak: »Baue mir hier sieben Altäre und stelle mir hier sieben junge Stiere und sieben Widder bereit.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 23, 2, 'Balak kam der Aufforderung Bileams nach, und beide opferten je einen Stier und einen Widder auf jedem Altar.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 23, 3, 'Hierauf sagte Bileam zu Balak: »Bleibe du hier bei deinem Brandopfer stehen, während ich einen Gang mache; vielleicht kommt der HERR mir entgegen, und was immer er mir offenbart, das will ich dir kundtun.« Dann begab er sich auf eine kahle Anhöhe.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 23, 4, 'Da kam Gott dem Bileam wirklich entgegen, und dieser sagte zu ihm: »Die sieben Altäre habe ich errichtet und auf jedem Altar einen jungen Stier und einen Widder geopfert.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 23, 5, 'Da legte der HERR dem Bileam Worte in den Mund und gebot ihm: »Kehre zu Balak zurück und sprich so zu ihm!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 23, 6, 'Als er nun zu ihm zurückgekehrt war, stand jener immer noch neben seinem Brandopfer, er mit allen Häuptlingen der Moabiter.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 23, 7, 'Da trug er seinen Spruch folgendermaßen vor: »Aus Aram hat Balak mich holen lassen, Moabs König von den Bergen des Ostens: ›Komm her, verfluche mir Jakob! ja komm, verwünsche Israel!‹ –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 23, 8, 'Wie soll ich den verfluchen, den Gott nicht verflucht? Und wie den verwünschen, den der HERR nicht verwünscht?');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 23, 9, 'Ja, vom Felsengipfel erblicke ich es, und von den Höhen herab erschaue ich es; ein Volk zeigt sich mir, das für sich abgesondert wohnt und sich nicht zu den übrigen Völkern rechnet.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 23, 10, 'Wer könnte den Staub Jakobs zählen oder nur den vierten Teil Israels berechnen? Möchte ich doch den Tod dieser Gerechten sterben und mein Ende dem ihren gleichen!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 23, 11, 'Da sagte Balak zu Bileam: »Was hast du mir da angetan! Um meine Feinde zu verfluchen, habe ich dich holen lassen, und nun hast du sie sogar gesegnet!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 23, 12, 'Da gab jener ihm zur Antwort: »Ich muß doch das, was der HERR mir in den Mund legt, getreulich aussprechen!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 23, 13, 'Nun sagte Balak zu ihm: »Komm doch mit mir an einen anderen Ort, von wo aus du (das Volk) sehen kannst; du siehst hier nur den äußersten Teil von ihm und kannst es nicht ganz überblicken; verfluche es mir dann von dort aus!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 23, 14, 'Hierauf nahm er ihn mit sich nach dem Späherfeld, auf den Gipfel des Pisga, baute dort sieben Altäre und opferte auf jedem Altar einen jungen Stier und einen Widder.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 23, 15, 'Dann sagte Bileam zu Balak: »Bleibe hier neben deinem Brandopfer stehen; ich aber will dort einer Kundgebung entgegengehen.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 23, 16, 'Da kam der HERR dem Bileam entgegen, legte ihm Worte in den Mund und sagte: »Kehre zu Balak zurück und sprich so zu ihm!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 23, 17, 'Als er nun zu ihm zurückgekehrt war, stand jener immer noch neben seinem Brandopfer, und die Häuptlinge der Moabiter waren bei ihm.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 23, 18, 'Als nun Balak ihn fragte: »Was hat der HERR gesagt?«, trug er seinen Spruch folgendermaßen vor: »Wohlan, Balak, höre zu! Leihe mir dein Ohr, Sohn Zippors!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 23, 19, 'Gott ist nicht ein Mensch, daß er lüge, noch ein Menschenkind, daß ihn etwas gereue: sollte er etwas sagen und es nicht ausführen? Sollte er etwas verheißen und es nicht erfüllen?');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 23, 20, 'Siehe, zu segnen ist mir aufgetragen, und hat er gesegnet, so kann ich’s nicht ändern.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 23, 21, 'Man erblickt kein Unheil in Jakob und gewahrt kein Leid in Israel: der HERR, sein Gott, ist mit ihm, und Königsjubel erschallt in seiner Mitte.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 23, 22, 'Gott, der sie aus Ägypten geführt, ist ihm wie die Hörner eines Wildstiers!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 23, 23, 'Ja, keine Zauberei haftet an Jakob und keine Beschwörung gegen Israel. Jetzt sagt man von Jakob und Israel: ›Wie Großes hat Gott vollführt!‹');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 23, 24, 'Sieh, welch ein Volk! Es steht auf wie die Löwin und erhebt sich wie der Leu; es legt sich nicht nieder, ehe es Raub verzehrt und das Blut der Erschlagnen getrunken.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 23, 25, 'Da sagte Balak zu Bileam: »Wenn du es nicht verfluchen willst, so brauchst du es doch nicht zu segnen!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 23, 26, 'Bileam aber antwortete dem Balak: »Habe ich dir nicht bestimmt erklärt: Alles, was der HERR (mir) mitteilen wird, das werde ich tun?«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 23, 27, 'Nun sagte Balak zu Bileam: »Komm, ich will dich an einen andern Ort mitnehmen; vielleicht gefällt es Gott dann, daß du mir das Volk von dort aus verfluchst.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 23, 28, 'So nahm denn Balak den Bileam mit sich auf den Gipfel des Peor, der über die weite Einöde emporragt.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 23, 29, 'Dort sagte Bileam zu Balak: »Baue mir hier sieben Altäre und stelle mir hier sieben junge Stiere und sieben Widder bereit.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 23, 30, 'Balak kam der Aufforderung Bileams nach und opferte einen Stier und einen Widder auf jedem Altar.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 24, 1, 'Da Bileam aber erkannte, daß es der Wille des HERRN war, Israel zu segnen, ging er nicht, wie die vorigen Male, auf Wahrzeichen aus, sondern wandte sein Gesicht nach der Wüste hin.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 24, 2, 'Als er nun seine Augen aufschlug und Israel nach seinen Stämmen gelagert sah, da kam der Geist Gottes über ihn,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 24, 3, 'und er trug seinen Spruch folgendermaßen vor: »So spricht Bileam, der Sohn Beors, und so spricht der Mann, dessen Auge geschlossen ist;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 24, 4, 'so spricht der, der Gottes Worte vernimmt und die Gedanken des Höchsten kennt, der die Offenbarungen des Allmächtigen schaut, der hingesunken ist und dessen Augen enthüllt sind:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 24, 5, 'Wie schön sind deine Zelte, Jakob, deine Wohnungen, Israel!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 24, 6, 'Wie Täler, die sich weithin dehnen, wie Gärten an einem Strom, wie Aloebäume, die der HERR gepflanzt, wie Zedern am Wasser!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 24, 7, 'Wasser rinnt aus seinen Eimern, und seine Saat ist reichlich getränkt. Sein König ist mächtiger als Agag, und sein Königtum steigt stolz empor.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 24, 8, 'Gott, der aus Ägypten es geführt, ist ihm wie die Hörner eines Wildstiers. Es frißt die ihm feindlichen Völker und zermalmt ihre Gebeine, es zerschmettert sie mit seinen Pfeilen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 24, 9, 'Es hat sich hingestreckt, liegt da wie ein Leu und wie eine Löwin: wer will es aufstören? Wer dich segnet, ist gesegnet, und wer dir flucht, ist verflucht!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 24, 10, 'Da geriet Balak in Zorn gegen Bileam, so daß er die Hände zusammenschlug. Dann sagte Balak zu Bileam: »Um meine Feinde zu verfluchen, habe ich dich holen lassen, und nun hast du sie sogar gesegnet, nun schon dreimal!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 24, 11, 'Kehre jetzt nur sofort in deine Heimat zurück! Ich hatte gedacht, dich hoch zu ehren; doch nun hat der HERR dich um die Ehre gebracht!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 24, 12, 'Da antwortete Bileam dem Balak: »Habe ich nicht schon deinen Boten, die du an mich gesandt hattest, ausdrücklich erklärt:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 24, 13, '›Wenn Balak mir auch sein ganzes Haus voll Silber und Gold geben wollte, so vermöchte ich doch den Befehl des HERRN nicht zu übertreten, um nach eigenem Belieben etwas zu tun, sei es zum Guten oder zum Bösen; sondern nur, was der HERR mir eingäbe, das würde ich kundtun‹?');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 24, 14, 'Weil ich denn jetzt zu meinem Volk zurückkehre, so komm: ich will dir verkünden, was dieses Volk deinem Volk in künftigen Zeiten antun wird!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 24, 15, 'Hierauf trug er seinen Spruch folgendermaßen vor: »So spricht Bileam, der Sohn Beors, und so spricht der Mann, dessen Auge geschlossen ist;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 24, 16, 'So spricht der, welcher Gottes Worte vernimmt und die Gedanken des Höchsten kennt, der die Offenbarungen des Allmächtigen schaut, der hingesunken ist und dessen Augen enthüllt sind:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 24, 17, 'Ich sehe ihn, doch nicht schon jetzt, ich gewahre ihn, doch noch nicht in der Nähe; es geht ein Stern aus Jakob auf, und ein Herrscherstab ersteht aus Israel, der zerschmettert die Schläfen Moabs, den Scheitel aller Söhne Seths.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 24, 18, 'Und Edom wird sein Eigentum werden und Seir sein Eigentum, sie, seine Feinde; Israel aber wird große Taten verrichten.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 24, 19, 'Von Jakob wird der Herrscher ausgehn und Entronnene vertilgen aus den Städten.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 24, 20, 'Als er dann die Amalekiter erblickte, trug er seinen Spruch folgendermaßen vor: »Der Völker erstes ist Amalek, doch sein Ende fällt dem Untergang anheim!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 24, 21, 'Als er dann die Keniter erblickte, trug er seinen Spruch folgendermaßen vor: »Fest ist dein Wohnsitz, (Kain,) und auf Felsen gebaut dein Nest;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 24, 22, 'gleichwohl ist Kain dem Untergang geweiht: wie lange noch, so führt Assur dich in Gefangenschaft!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 24, 23, 'Dann trug er nochmals seinen Spruch folgendermaßen vor: »Wehe! Wer wird am Leben bleiben, wenn Gott dies eintreten läßt?');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 24, 24, 'Denn Schiffe kommen vom Strand der Kittäer, die demütigen Assur und demütigen Eber; doch auch der wird dem Untergang verfallen!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 24, 25, 'Hierauf machte Bileam sich auf den Weg und kehrte in seine Heimat zurück; und auch Balak ging seines Weges.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 25, 1, 'Als aber die Israeliten sich in Sittim niedergelassen hatten, fing das Volk an, mit den Moabitinnen Unzucht zu treiben.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 25, 2, 'Diese luden das Volk zu den Opferfesten ihrer Götter ein, und das Volk nahm an ihren Opfermahlen teil und betete ihre Götter an.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 25, 3, 'Als nun die Israeliten sich so an Baal-Peor gehängt hatten, entbrannte der Zorn des HERRN gegen Israel,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 25, 4, 'so daß der HERR dem Mose gebot: »Nimm alle Häupter des Volkes und hänge sie angesichts der Sonne auf, damit der lodernde Zorn des HERRN sich von Israel abwende.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 25, 5, 'Da befahl Mose den Richtern der Israeliten: »Tötet ein jeder diejenigen von seinen Leuten, die sich an Baal-Peor gehängt haben!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 25, 6, 'Da kam gerade einer von den Israeliten (ins Lager) und brachte eine Midianitin zu seinen Volksgenossen mit vor den Augen Moses und vor den Augen der ganzen Gemeinde der Israeliten, während diese am Eingang des Offenbarungszeltes wehklagten.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 25, 7, 'Als Pinehas, der Sohn des Priesters Eleasar, des Sohnes Aarons, das sah, trat er aus der Mitte der Gemeinde heraus, nahm einen Speer in seine Hand,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 25, 8, 'ging dann dem Israeliten in das Schlafgemach nach und durchbohrte beide, den israelitischen Mann und das Weib, und zwar letzteres durch ihren Unterleib. Da wurde dem Sterben unter den Israeliten Einhalt getan.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 25, 9, 'Es belief sich aber die Zahl derer, die durch das Sterben umgekommen waren, auf 24000.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 25, 10, 'Hierauf sagte der HERR zu Mose:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 25, 11, '»Pinehas, der Sohn des Priesters Eleasar, des Sohnes Aarons, hat meinen Zorn von den Israeliten dadurch abgewandt, daß er denselben Eifer, der mir eigen ist, unter ihnen bewiesen hat; darum habe ich die Israeliten trotz meines Eifers nicht ganz vertilgt.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 25, 12, 'So mache denn bekannt: Ich schließe hierdurch mit ihm meinen Bund, daß ihm Heil widerfahren soll;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 25, 13, 'und zwar soll ihm und seinen Nachkommen nach ihm das Priestertum auf ewige Zeiten zustehen, zum Lohn dafür, daß er für seinen Gott geeifert und den Israeliten Sühne erwirkt hat.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 25, 14, 'Der damals getötete Israelit aber, der mitsamt der Midianitin getötet worden war, hieß Simri; er war der Sohn Salus und das Haupt eines Geschlechts der Simeoniten;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 25, 15, 'die damals getötete Midianitin aber hieß Kosbi; sie war die Tochter Zurs, des Hauptes einer Familie, eines midianitischen Geschlechts.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 25, 16, 'Darauf gebot der HERR dem Mose folgendes:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 25, 17, '»Behandelt die Midianiter als Feinde und erschlagt sie!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 25, 18, 'Denn sie haben feindlich gegen euch gehandelt durch ihre Ränke, die sie gegen euch verübt haben in betreff des Peor und in betreff ihrer Landsmännin Kosbi, der Tochter eines midianitischen Fürsten, die am Tage des wegen des Peor verhängten Sterbens getötet worden ist.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 25, 19, '');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 1, 'Nachdem aber das Sterben zu Ende war, gebot der HERR dem Mose und Eleasar, dem Sohne des Priesters Aaron, folgendes:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 2, '»Stellt die Kopfzahl der ganzen Gemeinde der Israeliten fest, von zwanzig Jahren an und darüber, Geschlecht für Geschlecht, alle, die zum Kriegsdienst in Israel tauglich sind!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 3, 'Da nahmen Mose und der Priester Eleasar die Musterung vor in den Steppen der Moabiter am Jordan, Jericho gegenüber,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 4, 'von zwanzig Jahren an und darüber, wie der HERR dem Mose geboten hatte. Es waren aber die Israeliten, die aus Ägypten ausgezogen waren:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 5, 'Ruben, der Erstgeborene Israels. Die Söhne Rubens waren: Hanok, von dem das Geschlecht der Hanokiten stammt; von Pallu das Geschlecht der Palluiten;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 6, 'von Hezron das Geschlecht der Hezroniten; von Karmi das Geschlecht der Karmiten.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 7, 'Dies sind die Geschlechter der Rubeniten, und die Zahl ihrer Gemusterten betrug 43730.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 8, 'Der Sohn Pallus war Eliab;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 9, 'und die Söhne Eliabs: Nemuel, Dathan und Abiram. Dieser Dathan und Abiram waren die zur Gemeindeversammlung Berufenen, die sich gegen Mose und Aaron mit der Rotte Korahs aufgelehnt hatten, als sie sich gegen den HERRN auflehnten,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 10, 'worauf die Erde ihren Mund auftat und sie samt Korah verschlang, während die Rotte dadurch umkam, daß das Feuer die 250 Männer verzehrte, so daß sie zu einem abschreckenden Beispiel wurden.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 11, 'Die Söhne Korahs aber waren nicht mit umgekommen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 12, 'Die Söhne Simeons nach ihren Geschlechtern waren diese: von Nemuel stammte das Geschlecht der Nemueliten; von Jamin das Geschlecht der Jaminiten; von Jachin das Geschlecht der Jachiniten;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 13, 'von Serah das Geschlecht der Sarchiten; von Saul das Geschlecht der Sauliten.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 14, 'Dies sind die Geschlechter der Simeoniten: 22200.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 15, 'Die Söhne Gads nach ihren Geschlechtern waren: von Zephon das Geschlecht der Zephoniten; von Haggi das Geschlecht der Haggiten; von Suni das Geschlecht der Suniten;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 16, 'von Osni das Geschlecht der Osniten; von Eri das Geschlecht der Eriten;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 17, 'von Arod das Geschlecht der Aroditen; von Areli das Geschlecht der Areliten.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 18, 'Dies sind die Geschlechter der Söhne Gads, soviele von ihnen gemustert wurden: 40500.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 19, 'Die Söhne Judas waren: Er und Onan, die beide im Lande Kanaan starben.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 20, 'Es waren aber die Söhne Judas nach ihren Geschlechtern: von Sela das Geschlecht der Selaniten; von Perez das Geschlecht der Parziten; von Serah das Geschlecht der Sariten.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 21, 'Die Söhne des Perez aber waren: von Hezron das Geschlecht der Hezroniten; von Hamul das Geschlecht der Hamuliten.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 22, 'Dies sind die Geschlechter Judas, soviele von ihnen gemustert wurden: 76500.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 23, 'Die Söhne Issaschars nach ihren Geschlechtern waren: von Thola das Geschlecht der Tholaiten; von Puwwa das Geschlecht der Puwwiten;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 24, 'von Jasub das Geschlecht der Jasubiten; von Simron das Geschlecht der Simroniten.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 25, 'Dies sind die Geschlechter Issaschars, soviele von ihnen gemustert wurden: 64300.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 26, 'Die Söhne Sebulons nach ihren Geschlechtern waren: von Sered das Geschlecht der Sarditen; von Elon das Geschlecht der Eloniten; von Jahleel das Geschlecht der Jahleeliten.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 27, 'Dies sind die Geschlechter der Sebuloniten, soviele von ihnen gemustert wurden: 60500.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 28, 'Die Söhne Josephs nach ihren Geschlechtern waren: Manasse und Ephraim.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 29, 'Die Söhne Manasses waren: von Machir das Geschlecht der Machiriten. Machir war der Vater Gileads; von Gilead stammt das Geschlecht der Gileaditen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 30, 'Dies sind die Söhne Gileads: von Jeser stammt das Geschlecht der Jesriten; von Helek das Geschlecht der Helkiten;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 31, 'von Asriel das Geschlecht der Asrieliten; von Sichem das Geschlecht der Sichmiten;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 32, 'von Semida das Geschlecht der Semidaiten; von Hepher das Geschlecht der Hephriten.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 33, 'Zelophhad aber, der Sohn Hephers, hatte keine Söhne, sondern nur Töchter, die hießen Mahla und Noa, Hogla, Milka und Thirza.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 34, 'Dies sind die Geschlechter Manasses, soviele von ihnen gemustert wurden: 52700.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 35, 'Dies waren die Söhne Ephraims nach ihren Geschlechtern: von Suthelah das Geschlecht der Suthalhiten; von Becher das Geschlecht der Bachriten; von Thachan das Geschlecht der Thachaniten.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 36, 'Und dies waren die Söhne Suthelahs: von Eran das Geschlecht der Eraniten.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 37, 'Dies sind die Geschlechter der Söhne Ephraims, soviele von ihnen gemustert wurden: 32500. Dies sind die Söhne Josephs nach ihren Geschlechtern.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 38, 'Die Söhne Benjamins nach ihren Geschlechtern waren: von Bela das Geschlecht der Baliten; von Asbel das Geschlecht der Asbeliten; von Ahiram das Geschlecht der Ahiramiten;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 39, 'von Supham das Geschlecht der Suphamiten; von Hupham das Geschlecht der Huphamiten.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 40, 'Und die Söhne Belas waren: Ard und Naaman; von Ard stammt das Geschlecht der Arditen, von Naaman das Geschlecht der Naamaniten.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 41, 'Dies sind die Söhne Benjamins nach ihren Geschlechtern, soviele von ihnen gemustert wurden: 45600.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 42, 'Dies waren die Söhne Dans nach ihren Geschlechtern: von Suham das Geschlecht der Suhamiten.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 43, 'Dies sind die Söhne Dans nach ihren Geschlechtern. Alle Geschlechter der Suhamiten, soviele von ihnen gemustert wurden, beliefen sich auf 64400.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 44, 'Die Söhne Assers nach ihren Geschlechtern waren: von Jimna das Geschlecht der Jimniten; von Jiswi das Geschlecht der Jiswiten; von Beria das Geschlecht der Beriiten.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 45, 'Von den Söhnen Berias: von Heber das Geschlecht der Hebriten; von Malkiel das Geschlecht der Malkieliten.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 46, 'Und die Tochter Assers hieß Serah.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 47, 'Dies sind die Geschlechter der Söhne Assers, soviele von ihnen gemustert wurden: 53400.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 48, 'Die Söhne Naphthalis nach ihren Geschlechtern waren: von Jahzeel das Geschlecht der Jahzeeliten; von Guni das Geschlecht der Guniten;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 49, 'von Jezer das Geschlecht der Jizriten; von Sillem das Geschlecht der Sillemiten.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 50, 'Dies sind die Söhne Naphthalis nach ihren Geschlechtern; und ihre Gemusterten beliefen sich auf 45400.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 51, 'Dies ist die Gesamtzahl der gemusterten Israeliten: 601730.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 52, 'Hierauf sagte der HERR zu Mose folgendes:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 53, '»Unter diese soll das Land als erblicher Besitz nach der Kopfzahl verteilt werden;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 54, 'den größeren Stämmen sollst du einen größeren Erbbesitz geben, dagegen den kleineren einen weniger großen Erbbesitz zuteilen; jedem Stamme soll sein Erbbesitz nach der Zahl der aus ihm Gemusterten zugeteilt werden.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 55, 'Doch soll die Verteilung des Landes durch das Los erfolgen: nach den Namen ihrer väterlichen Stämme sollen sie es in Besitz nehmen;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 56, 'nach der Entscheidung des Loses soll der Erbbesitz zwischen den größeren und den kleineren Stämmen verteilt werden.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 57, 'Und folgendes sind die Leviten, soviele von ihnen nach ihren Geschlechtern gemustert wurden: von Gerson das Geschlecht der Gersoniten, von Kehath das Geschlecht der Kehathiten, von Merari das Geschlecht der Merariten.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 58, 'Dies sind die Geschlechter Levis: das Geschlecht der Libniten, das Geschlecht der Hebroniten, das Geschlecht der Mahliten, das Geschlecht der Musiten, das Geschlecht der Korhiten. Kehath aber war der Vater Amrams.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 59, 'Und die Frau Amrams hieß Jochebed, eine Tochter Levis, die dem Levi in Ägypten geboren war; diese gebar dem Amram Aaron und Mose und deren Schwester Mirjam.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 60, 'Dem Aaron aber wurden Nadab und Abihu, Eleasar und Ithamar geboren;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 61, 'aber Nadab und Abihu kamen ums Leben, als sie ein ungehöriges Feueropfer vor dem HERRN darbrachten.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 62, 'Es belief sich aber die Zahl der aus ihnen Gemusterten auf 23000 Seelen, alle männlichen Personen von einem Monat an und darüber; sie waren nämlich nicht mit unter den übrigen Israeliten gemustert worden, weil ihnen kein Erbbesitz inmitten der Israeliten zugeteilt wurde.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 63, 'Dies war die Musterung, die Mose und der Priester Eleasar bei den Israeliten in den Steppen der Moabiter am Jordan, Jericho gegenüber, vorgenommen haben.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 64, 'Unter diesen befand sich aber kein einziger Mann mehr von denen, die von Mose und dem Priester Aaron einst in der Wüste am Sinai gemustert worden waren.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 65, 'Der HERR hatte ihnen ja angekündigt, daß sie in der Wüste sterben sollten. So war denn kein einziger von ihnen übriggeblieben außer Kaleb, dem Sohn Jephunnes, und Josua, dem Sohne Nuns.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 27, 1, 'Da traten herzu die Töchter Zelophhads, des Sohnes Hephers, des Sohnes Gileads, des Sohnes Machirs, des Sohnes Manasses, aus den Geschlechtern Manasses, des Sohnes Josephs; und die Namen seiner Töchter waren Mahla, Noa, Hogla, Milka und Thirza.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 27, 2, 'Die traten also vor Mose und vor den Priester Eleasar, vor die Stammesfürsten und die ganze Gemeinde am Eingang des Offenbarungszeltes und sagten:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 27, 3, '»Unser Vater ist in der Wüste gestorben, hat aber nicht zu der Rotte derer gehört, die sich gegen den HERRN zusammengetan haben, zu der Rotte Korahs, sondern er ist wegen seiner eigenen Sündhaftigkeit gestorben, ohne Söhne zu hinterlassen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 27, 4, 'Warum soll nun der Name unseres Vaters aus seinem Geschlecht gestrichen werden, weil er keinen Sohn gehabt hat? Gib uns einen Erbbesitz unter den Geschlechtsgenossen unseres Vaters!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 27, 5, 'Als nun Mose ihre Rechtssache dem HERRN (zur Entscheidung) vorlegte,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 27, 6, 'gab der HERR dem Mose folgenden Bescheid:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 27, 7, '»Die Töchter Zelophhads haben recht; du sollst ihnen daher unweigerlich einen Erbbesitz unter den Geschlechtsgenossen ihres Vaters geben und sollst den ihrem Vater zustehenden Erbbesitz auf sie übergehen lassen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 27, 8, 'Den Israeliten aber sollst du folgende Verordnung kundtun: ›Wenn ein Mann stirbt, ohne einen Sohn zu hinterlassen, so sollt ihr seinen Erbbesitz auf seine Tochter übergehen lassen;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 27, 9, 'und wenn er keine Tochter hat, so sollt ihr seinen Erbbesitz seinen Brüdern geben;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 27, 10, 'wenn er auch keine Brüder hat, so sollt ihr seinen Erbbesitz den Brüdern seines Vaters geben;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 27, 11, 'und wenn sein Vater keine Brüder hat, so sollt ihr seinen Erbbesitz seinem nächsten Blutsverwandten aus seinem Geschlecht geben, damit er ihn in Besitz nimmt.‹« Dies soll für die Israeliten eine Rechtsbestimmung sein, wie der HERR dem Mose geboten hat.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 27, 12, 'Hierauf gebot der HERR dem Mose: »Steige auf das Gebirge Abarim hier und sieh dir das Land an, das ich für die Israeliten bestimmt habe.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 27, 13, 'Wenn du es dir angeschaut hast, sollst auch du zu deinen Volksgenossen versammelt werden, wie dein Bruder Aaron zu ihnen bereits versammelt worden ist,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 27, 14, 'weil ihr in der Wüste Zin, als die Gemeinde mit mir haderte, meinem Geheiß, mich durch Beschaffung von Wasser vor ihnen zu verherrlichen, nicht nachgekommen seid« – das bezieht sich auf das Haderwasser von Kades in der Wüste Zin.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 27, 15, 'Da antwortete Mose dem HERRN folgendermaßen:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 27, 16, '»Gott, der HERR über Leben und Tod alles Fleisches, wolle einen Mann über die Gemeinde bestellen,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 27, 17, 'der an ihrer Spitze aus- und einziehe, der sie ins Feld hinausführe und wieder zurückführe, damit die Gemeinde des HERRN nicht wie eine Herde ohne Hirten sei!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 27, 18, 'Da gebot der HERR dem Mose: »Nimm Josua zu dir, den Sohn Nuns, einen Mann, in dem (mein) Geist wohnt, und lege deine Hand fest auf ihn;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 27, 19, 'laß ihn dann vor den Priester Eleasar und vor die ganze Gemeinde treten, setze ihn vor ihren Augen in sein Amt ein');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 27, 20, 'und teile ihm etwas von deiner Hoheit mit, damit die ganze Gemeinde der Israeliten ihm gehorsam ist.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 27, 21, 'Er soll sich dann (bei jeder Gelegenheit) an den Priester Eleasar wenden, damit dieser für ihn das Urim-Orakel vor dem HERRN befragt: nach dessen Weisung sollen sie zum Kampf ausziehen und ebenso nach dessen Weisung wieder heimkehren, er und alle Israeliten mit ihm, überhaupt die ganze Gemeinde.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 27, 22, 'Mose tat, wie der HERR ihm geboten hatte: er nahm Josua, ließ ihn vor den Priester Eleasar und vor die ganze Gemeinde treten,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 27, 23, 'legte dann seine Hände fest auf ihn und setzte ihn so in sein Amt ein, wie der HERR es durch Mose angeordnet hatte.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 28, 1, 'Weiter gebot der HERR dem Mose folgendes:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 28, 2, '»Teile den Israeliten folgende Verordnungen mit: Ihr sollt darauf achten, meine Opfergaben, meine Speise in Gestalt der mir zukommenden Feueropfer zu lieblichem Geruch für mich, mir zu rechter Zeit darzubringen!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 28, 3, '»Sage ihnen also: Dies ist das Feueropfer, das ihr dem HERRN darbringen sollt: täglich zwei fehlerlose, einjährige Lämmer als regelmäßiges Brandopfer.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 28, 4, 'Das eine Lamm sollst du am Morgen opfern und das andere Lamm gegen Abend herrichten;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 28, 5, 'dazu als Speisopfer ein Zehntel Epha Feinmehl, das mit einem Viertel Hin Öl von zerstoßenen Oliven gemengt ist.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 28, 6, 'Dies ist das regelmäßige Brandopfer, das am Berge Sinai zum lieblichen Geruch als Feueropfer für den HERRN eingesetzt worden ist;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 28, 7, 'dazu als zugehöriges Trankopfer ein Viertel Hin Wein für das eine Lamm; im Heiligtum sollst du das Trankopfer von starkem Getränk dem HERRN spenden.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 28, 8, 'Das zweite Lamm aber sollst du gegen Abend herrichten; mit einem Speisopfer wie am Morgen und dem zugehörigen Trankopfer sollst du es herrichten als ein Feueropfer zu lieblichem Geruch für den HERRN.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 28, 9, '»Ferner am Sabbattage: zwei fehlerlose, einjährige Lämmer und zwei Zehntel Epha mit Öl gemengtes Feinmehl als Speisopfer nebst dem zugehörigen Trankopfer.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 28, 10, 'Dies ist das Sabbat-Brandopfer, das an jedem Sabbat außer dem regelmäßigen Brandopfer und dem zugehörigen Trankopfer darzubringen ist.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 28, 11, '»Ferner sollt ihr an jedem ersten Tage eurer Monate dem HERRN als Brandopfer darbringen: zwei junge Stiere und einen Widder, sieben fehlerlose, einjährige Lämmer');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 28, 12, 'und zu jedem Stier drei Zehntel Epha mit Öl gemengtes Feinmehl als Speisopfer und zu dem einen Widder zwei Zehntel Epha mit Öl gemengtes Feinmehl als Speisopfer;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 28, 13, 'und zu jedem Lamm ein Zehntel Epha mit Öl gemengtes Feinmehl als Speisopfer – das (alles) als Brandopfer zu lieblichem Geruch, als Feueropfer für den HERRN.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 28, 14, 'Was ferner die zugehörigen Trankopfer betrifft, so soll ein halbes Hin Wein auf jeden Stier und ein Drittel Hin auf den Widder und ein Viertel Hin auf jedes Lamm kommen. Das ist das an jedem Neumondstage des Jahres, Monat für Monat, darzubringende Brandopfer.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 28, 15, 'Außerdem soll neben dem regelmäßigen Brandopfer und dem zugehörigen Trankopfer dem HERRN ein Ziegenbock als Sündopfer dargebracht werden.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 28, 16, '»Sodann findet am vierzehnten Tage des ersten Monats das Passahfest zu Ehren des HERRN statt.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 28, 17, 'Und am fünfzehnten Tage dieses Monats wird Festfeier gehalten; sieben Tage lang soll ungesäuertes Brot gegessen werden.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 28, 18, 'Am ersten Tage findet eine Festversammlung am Heiligtum statt; da dürft ihr keinerlei Werktagsarbeit verrichten');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 28, 19, 'und habt als Feueropfer, als Brandopfer, für den HERRN darzubringen: zwei junge Stiere, einen Widder und sieben einjährige Lämmer – fehlerlose Tiere müssen es sein –;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 28, 20, 'sodann als zugehöriges Speisopfer von Feinmehl, das mit Öl gemengt ist: drei Zehntel Epha sollt ihr zu jedem Stiere und zwei Zehntel zu dem Widder herrichten;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 28, 21, 'und je ein Zehntel sollst du zu jedem Lamm von den sieben Lämmern herrichten;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 28, 22, 'außerdem noch einen Ziegenbock zum Sündopfer, um euch Sühne zu erwirken.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 28, 23, 'Außer dem Morgen-Brandopfer, welches das regelmäßige Brandopfer bildet, sollt ihr dies alles darbringen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 28, 24, 'Dieselben Opfer sollt ihr täglich, alle sieben Tage hindurch, als eine Feueropferspeise zu lieblichem Geruch für den HERRN herrichten; außer dem regelmäßigen Brandopfer und dem zugehörigen Trankopfer soll es hergerichtet werden.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 28, 25, 'Am siebten Tage aber soll bei euch wieder eine Festversammlung am Heiligtum stattfinden; da dürft ihr keinerlei Werktagsarbeit verrichten.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 28, 26, '»Ferner am Tage der Erstlingsfrüchte, wenn ihr dem HERRN ein Speisopfer vom neuen Getreide darbringt, an eurem Wochenfest, soll bei euch eine Versammlung am Heiligtum stattfinden; da dürft ihr keinerlei Werktagsarbeit verrichten.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 28, 27, 'Und als Brandopfer zu lieblichem Geruch für den HERRN sollt ihr darbringen: zwei junge Stiere, einen Widder, sieben einjährige Lämmer (lauter fehlerlose Tiere);');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 28, 28, 'dazu als zugehöriges Speisopfer Feinmehl, das mit Öl gemengt ist, nämlich drei Zehntel zu jedem Stier, zwei Zehntel zu dem einen Widder,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 28, 29, 'je ein Zehntel zu jedem Lamm von den sieben Lämmern;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 28, 30, 'außerdem einen Ziegenbock, um euch Sühne zu erwirken;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 28, 31, 'außer dem regelmäßigen Brandopfer und dem zugehörigen Speisopfer sollt ihr dies alles herrichten – fehlerlose Tiere müssen es sein – nebst den erforderlichen Trankopfern.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 1, '»Ferner am ersten Tage des siebten Monats soll bei euch eine Festversammlung am Heiligtum stattfinden; da dürft ihr keinerlei Werktagsarbeit verrichten: der Tag des Posaunenblasens soll es euch sein.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 2, 'Da sollt ihr als Brandopfer zu lieblichem Geruch für den HERRN darbringen: einen jungen Stier, einen Widder und sieben fehlerlose, einjährige Lämmer;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 3, 'dazu als zugehöriges Speisopfer von Feinmehl, das mit Öl gemengt ist: drei Zehntel Epha zu dem Stier, zwei Zehntel zu dem Widder');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 4, 'und ein Zehntel zu jedem Lamm von den sieben Lämmern;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 5, 'außerdem einen Ziegenbock als Sündopfer, um euch Sühne zu erwirken;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 6, 'außer dem Neumond-Brandopfer nebst dem zugehörigen Speisopfer und außer dem regelmäßigen Brandopfer nebst dem zugehörigen Speisopfer und den erforderlichen Trankopfern, in der vorgeschriebenen Weise, zu lieblichem Geruch, als ein Feueropfer für den HERRN.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 7, '»Ferner am zehnten Tage desselben siebten Monats soll bei euch eine Festversammlung am Heiligtum stattfinden, und ihr sollt fasten; keinerlei Werktagsarbeit dürft ihr da verrichten.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 8, 'Als Brandopfer sollt ihr dabei für den HERRN zu lieblichem Geruch herrichten: einen jungen Stier, einen Widder, sieben einjährige Lämmer – fehlerlose Tiere müssen es sein –;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 9, 'außerdem als zugehöriges Speisopfer von Feinmehl, das mit Öl gemengt ist: drei Zehntel zu dem Stier, zwei Zehntel zu dem einen Widder,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 10, 'je ein Zehntel zu jedem Lamm von den sieben Lämmern;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 11, 'auch einen Ziegenbock als Sündopfer, außer dem Versöhnungs-Sündopfer und dem regelmäßigen Brandopfer nebst dem zugehörigen Speisopfer und den erforderlichen Trankopfern.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 12, '»Ferner am fünfzehnten Tage des siebten Monats soll bei euch eine Festversammlung am Heiligtum stattfinden; da dürft ihr keinerlei Werktagsarbeit verrichten, sondern sollt dem HERRN ein Fest sieben Tage lang feiern.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 13, 'Dabei sollt ihr als Brandopfer, als Feueropfer zu lieblichem Geruch für den HERRN, darbringen: dreizehn junge Stiere, zwei Widder, vierzehn einjährige Lämmer – fehlerlose Tiere müssen es sein –;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 14, 'dazu als zugehöriges Speisopfer von Feinmehl, das mit Öl gemengt ist: drei Zehntel zu jedem von den dreizehn Stieren, zwei Zehntel zu jedem von den beiden Widdern');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 15, 'und je ein Zehntel zu jedem Lamm von den vierzehn Lämmern;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 16, 'auch einen Ziegenbock als Sündopfer, außer dem regelmäßigen Brandopfer nebst dem zugehörigen Speisopfer und dem erforderlichen Trankopfer.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 17, 'Sodann am zweiten Tage: zwölf junge Stiere, zwei Widder, vierzehn fehlerlose, einjährige Lämmer');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 18, 'nebst dem zugehörigen Speisopfer und den erforderlichen Trankopfern zu den Stieren, zu den Widdern und zu den Lämmern, nach ihrer Zahl, der vorgeschriebenen Weise gemäß;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 19, 'auch einen Ziegenbock als Sündopfer, außer dem regelmäßigen Brandopfer nebst dem zugehörigen Speisopfer und den erforderlichen Trankopfern.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 20, 'Sodann am dritten Tage: elf junge Stiere, zwei Widder, vierzehn fehlerlose, einjährige Lämmer');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 21, 'nebst dem zugehörigen Speisopfer und den erforderlichen Trankopfern zu den Stieren, zu den Widdern und zu den Lämmern, nach ihrer Zahl, der vorgeschriebenen Weise gemäß;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 22, 'auch einen Ziegenbock als Sündopfer, außer dem regelmäßigen Brandopfer nebst dem zugehörigen Speisopfer und dem erforderlichen Trankopfer.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 23, 'Sodann am vierten Tage: zehn junge Stiere, zwei Widder, vierzehn fehlerlose, einjährige Lämmer');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 24, 'nebst dem zugehörigen Speisopfer und den erforderlichen Trankopfern zu den Stieren, zu den Widdern und zu den Lämmern nach ihrer Zahl, der vorgeschriebenen Weise gemäß;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 25, 'auch einen Ziegenbock als Sündopfer, außer dem regelmäßigen Brandopfer, dem zugehörigen Speisopfer und dem erforderlichen Trankopfer.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 26, 'Sodann am fünften Tage: neun junge Stiere, zwei Widder, vierzehn fehlerlose, einjährige Lämmer');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 27, 'nebst dem zugehörigen Speisopfer und den erforderlichen Trankopfern zu den Stieren, zu den Widdern und zu den Lämmern, nach ihrer Zahl, der vorgeschriebenen Weise gemäß;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 28, 'auch einen Ziegenbock als Sündopfer, außer dem regelmäßigen Brandopfer nebst dem zugehörigen Speisopfer und dem erforderlichen Trankopfer.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 29, 'Sodann am sechsten Tage: acht junge Stiere, zwei Widder, vierzehn fehlerlose, einjährige Lämmer');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 30, 'nebst dem zugehörigen Speisopfer und den erforderlichen Trankopfern zu den Stieren, zu den Widdern und zu den Lämmern, nach ihrer Zahl, der vorgeschriebenen Weise gemäß;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 31, 'auch einen Ziegenbock als Sündopfer, außer dem regelmäßigen Brandopfer, dem zugehörigen Speisopfer und den erforderlichen Trankopfern.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 32, 'Sodann am siebten Tage: sieben junge Stiere, zwei Widder, vierzehn fehlerlose, einjährige Lämmer');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 33, 'nebst dem zugehörigen Speisopfer und den erforderlichen Trankopfern zu den Stieren, zu den Widdern und zu den Lämmern, nach ihrer Zahl, der vorgeschriebenen Weise gemäß;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 34, 'auch einen Ziegenbock als Sündopfer, außer dem regelmäßigen Brandopfer, dem zugehörigen Speisopfer und dem erforderlichen Trankopfer.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 35, 'Am achten Tage soll bei euch eine Festversammlung stattfinden; da dürft ihr keinerlei Werktagsarbeit verrichten.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 36, 'Und als Brandopfer, als Feueropfer zu lieblichem Geruch für den HERRN, sollt ihr darbringen: einen jungen Stier, einen Widder, sieben fehlerlose, einjährige Lämmer');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 37, 'nebst dem zugehörigen Speisopfer und den erforderlichen Trankopfern zu dem Stier, zu dem Widder und zu den Lämmern, nach ihrer Zahl, der vorgeschriebenen Weise gemäß;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 38, 'auch einen Ziegenbock als Sündopfer, außer dem regelmäßigen Brandopfer nebst dem zugehörigen Speisopfer und dem erforderlichen Trankopfer.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 39, '»Diese Opfer sollt ihr an euren Festen für den HERRN herrichten, abgesehen von dem, was ihr infolge von Gelübden und als freiwillige Gaben sowohl an Brandopfern und Speisopfern als auch an Trankopfern und Heilsopfern darbringen werdet.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 30, 1, 'Mose teilte dies alles den Israeliten genau so mit, wie der HERR es ihm geboten hatte.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 30, 2, 'Darauf sagte Mose zu den Stammeshäuptern der Israeliten: »Folgendes hat der HERR geboten:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 30, 3, 'Wenn ein Mann dem HERRN ein Gelübde ablegt oder einen Eid schwört, durch den er sich zu einer Enthaltung verpflichtet, so darf er sein Wort nicht brechen: genau so, wie er es ausgesprochen hat, soll er es auch ausführen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 30, 4, 'Wenn aber eine weibliche Person, die in ihrer Jugend im Hause ihres Vaters lebt, dem HERRN ein Gelübde ablegt oder sich zu einer Enthaltung verpflichtet');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 30, 5, 'und ihr Vater von ihrem Gelübde oder von der Enthaltung, zu der sie sich verpflichtet hat, Kunde erhält und dann ihr gegenüber dazu schweigt, so sollen alle ihre Gelübde gültig sein, und auch jede Enthaltung, zu der sie sich verpflichtet hat, soll zu Recht bestehen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 30, 6, 'Wenn aber ihr Vater an dem Tage, an dem er davon erfährt, ihr die Genehmigung versagt, so sollen alle ihre Gelübde und alle ihre Enthaltungen, zu denen sie sich verpflichtet hat, ungültig sein; und der HERR wird ihr verzeihen, weil ihr Vater ihr die Genehmigung versagt hat.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 30, 7, 'Wenn sie sich dann aber verheiraten sollte, während ihre Gelübde oder ein unbedachter Ausspruch ihrer Lippen, durch den sie sich eine Enthaltung auferlegt hat, für sie noch verbindlich sind,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 30, 8, 'und ihr Mann erhält Kunde davon, schweigt aber ihr gegenüber an dem Tage, an dem er davon hört, so sollen ihre Gelübde gültig sein, und die Enthaltungen, zu denen sie sich verpflichtet hat, sollen zu Recht bestehen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 30, 9, 'Wenn aber ihr Mann an dem Tage, an dem er davon erfährt, ihr die Genehmigung versagt, so macht er dadurch das Gelübde, das auf ihr ruht, und den unbedachten Ausspruch ihrer Lippen, durch den sie sich eine Enthaltung auferlegt hat, ungültig, und der HERR wird ihr verzeihen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 30, 10, 'Aber das Gelübde einer Witwe oder einer verstoßenen Frau, alles, wozu sie sich verpflichtet hat, soll für sie verbindlich sein.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 30, 11, 'Wenn ferner eine Frau im Hause ihres Mannes etwas gelobt oder sich durch einen Eid zu einer Enthaltung verpflichtet hat');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 30, 12, 'und ihr Mann Kunde davon erhält, aber ihr gegenüber dazu schweigt und ihr nicht die Genehmigung versagt, so sollen alle ihre Gelübde gültig sein, und jede Enthaltung, zu der sie sich verpflichtet hat, soll zu Recht bestehen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 30, 13, 'Wenn ihr Mann aber an dem Tage, an dem er davon hört, sie für ungültig erklärt hat, so soll nichts von dem, was sie bezüglich ihrer Gelübde und bezüglich der Verpflichtungen zu einer Enthaltung ausgesprochen hat, Gültigkeit haben: ihr Mann hat sie für ungültig erklärt, darum wird der HERR ihr verzeihen.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 30, 14, '»Jedes Gelübde und jedes eidliche Versprechen einer Enthaltung behufs einer Selbstkasteiung kann ihr Mann für gültig und ebenso für ungültig erklären.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 30, 15, 'Wenn aber ihr Mann von einem Tage bis zum andern stillschweigt, so bestätigt er dadurch alle ihre Gelübde oder alle die Enthaltungen, die auf ihr ruhen; er hat sie dadurch bestätigt, daß er ihr gegenüber an dem Tage, an welchem er Kunde davon erhielt, geschwiegen hat.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 30, 16, 'Wenn er sie aber erst später aufhebt, nachdem er schon vorher davon gehört hat, so hat er die Verschuldung (seiner Frau) zu tragen.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 30, 17, 'Das sind die Verordnungen, die der HERR dem Mose geboten hat, damit sie Geltung haben zwischen einem Manne und seiner Frau und zwischen einem Vater und seiner Tochter, solange diese in ihrer Jugend im Hause ihres Vaters lebt.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 1, 'Der HERR gebot hierauf dem Mose folgendes:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 2, '»Nimm Rache für die Israeliten an den Midianitern! Danach sollst du zu deinen Volksgenossen versammelt werden.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 3, 'Da befahl Mose dem Volke folgendes: »Rüstet aus eurer Mitte Männer zu einem Kriegszuge aus, sie sollen gegen die Midianiter ziehen, um die Rache des HERRN an den Midianitern zu vollstrecken.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 4, 'Je tausend Mann von einem Stamm, und zwar von allen Stämmen der Israeliten, sollt ihr zu dem Kriegszuge entsenden.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 5, 'So wurden denn aus den Stämmen der Israeliten je tausend Mann von jedem Stamme ausgehoben, im ganzen zwölftausend kriegsgerüstete Männer.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 6, 'Diese sandte Mose, tausend Mann von jedem Stamm, zum Kriegszuge aus und mit ihnen Pinehas, den Sohn des Priesters Eleasar, zum Kriegszuge; der hatte die heiligen Geräte und die Alarmtrompeten bei sich.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 7, 'So zogen sie denn gegen die Midianiter zu Felde, wie der HERR dem Mose geboten hatte, und töteten alle männlichen Personen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 8, 'Auch die Könige der Midianiter töteten sie zu den anderen hinzu, die von ihnen erschlagen waren, nämlich: Ewi, Rekem, Zur, Hur und Reba, die fünf Könige der Midianiter; auch Bileam, den Sohn Beors, machten sie mit dem Schwert nieder.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 9, 'Hierauf führten die Israeliten die midianitischen Frauen und ihre Kinder gefangen weg, erbeuteten ihr sämtliches Lastvieh und alle ihre Herden und ihre gesamte Habe');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 10, 'und verbrannten alle Ortschaften in ihren Wohnsitzen und alle ihre Zeltlager mit Feuer.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 11, 'Dann nahmen sie die gesamte Beute und alles, was sie an Menschen und Vieh geraubt hatten,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 12, 'und brachten die Gefangenen sowie den Raub und die Beute zu Mose und zu dem Priester Eleasar und zu der Gemeinde der Israeliten ins Lager, in die moabitischen Steppen, die am Jordan, Jericho gegenüber, lagen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 13, 'Da gingen Mose und der Priester Eleasar und alle Fürsten der Gemeinde ihnen entgegen vor das Lager hinaus.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 14, 'Mose aber geriet in Zorn über die Befehlshaber des Heeres, die Hauptleute der Tausendschaften und die Hauptleute der Hundertschaften, die von dem Feldzuge zurückkehrten;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 15, 'und Mose sagte zu ihnen: »Habt ihr denn alle Frauen am Leben gelassen?');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 16, 'Sie sind es ja gerade, die auf den Rat Bileams den Israeliten ein Anlaß geworden sind, Untreue gegen den HERRN zu begehen [in betreff des Peor], so daß das Sterben über die Gemeinde des HERRN kam.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 17, 'So tötet nun alle männlichen Kinder unter ihnen, und ebenso tötet alle weiblichen Personen, die schon mit einem Manne zu tun gehabt haben;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 18, 'aber alle Kinder weiblichen Geschlechts, die noch mit keinem Manne zu tun gehabt haben, laßt für euch am Leben.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 19, 'Ihr selbst aber müßt sieben Tage lang außerhalb des Lagers bleiben: jeder, der einen Menschen getötet, und jeder, der einen Erschlagenen berührt hat, muß sich am dritten und am siebten Tage entsündigen, ihr selbst und eure Gefangenen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 20, 'Auch alle Kleider und alle Gegenstände von Leder sowie alles aus Ziegenhaaren Gefertigte und alle hölzernen Geräte müßt ihr entsündigen!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 21, 'Hierauf sagte der Priester Eleasar zu den Kriegsleuten, die an dem Feldzuge teilgenommen hatten: »Dies ist eine Bestimmung des Gesetzes, das der HERR dem Mose zur Pflicht gemacht hat:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 22, 'das Gold und das Silber, das Kupfer, Eisen, Zinn und Blei,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 23, 'überhaupt alles, was das Feuer verträgt, müßt ihr durchs Feuer gehen lassen, dann wird es rein sein; jedoch muß es auch noch mit dem Reinigungswasser entsündigt werden. Alles aber, was kein Feuer verträgt, müßt ihr durchs Wasser gehen lassen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 24, 'Wenn ihr also am siebten Tage eure Kleider gewaschen habt, dann werdet ihr rein sein und dürft danach wieder ins Lager kommen.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 25, 'Hierauf gebot der HERR dem Mose folgendes:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 26, '»Nimm von allem, was ihr als Beute an Menschen und an Vieh weggeführt habt, die Gesamtzahl auf, du mit dem Priester Eleasar und den Stammeshäuptern der Gemeinde;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 27, 'und teile die Beute zur Hälfte zwischen denen, die als Teilnehmer am Kriege ins Feld gezogen sind, und zwischen der ganzen übrigen Gemeinde.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 28, 'Dann erhebe von den Kriegsleuten, die ins Feld gezogen sind, eine Abgabe für den HERRN, nämlich je ein Stück von fünf Hunderten, sowohl von den Menschen als auch von den Rindern, von den Eseln und vom Kleinvieh;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 29, 'von der ihnen zufallenden Hälfte sollt ihr sie nehmen, und du sollst sie dem Priester Eleasar als ein Hebeopfer für den HERRN übergeben.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 30, 'Von der den (anderen) Israeliten zufallenden Hälfte aber sollst du aus fünfzig Stück immer eins herausgreifen, sowohl aus den Menschen als auch aus den Rindern, den Eseln und dem Kleinvieh, also aus dem gesamten Vieh, und sollst sie den Leviten übergeben, die den Dienst an der Wohnung des HERRN zu verrichten haben.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 31, 'Da taten Mose und der Priester Eleasar, wie der HERR dem Mose geboten hatte.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 32, 'Es betrug aber das Erbeutete, das, was von der Beute, die das Kriegsvolk gemacht hatte, übriggeblieben war: 675000 Stück Kleinvieh,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 33, '72000 Rinder');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 34, 'und 61000 Esel;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 35, 'und was die Menschen betrifft, so belief sich die Zahl der Mädchen, die noch mit keinem Manne zu tun gehabt hatten, auf insgesamt 32000 Seelen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 36, 'So betrug also die Hälfte, nämlich der Anteil derer, die als Kriegsleute ins Feld gezogen waren, 337500 Stück Kleinvieh,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 37, 'und die Abgabe vom Kleinvieh für den HERRN betrug 675 Stück;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 38, 'die Zahl der Rinder betrug 36000 Stück und die Abgabe davon für den HERRN 72;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 39, 'ferner die Zahl der Esel 30500 und die Abgabe davon für den HERRN 61;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 40, 'sodann die Zahl der Menschen 16000 und die Abgabe davon für den HERRN 32 Seelen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 41, 'Mose übergab dann die zum Hebeopfer für den HERRN bestimmte Abgabe dem Priester Eleasar, wie der HERR dem Mose geboten hatte.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 42, 'Endlich von der den Israeliten zufallenden Hälfte, die Mose von dem für die Kriegsleute bestimmten Anteil abgesondert hatte –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 43, 'es belief sich aber die der Gemeinde zukommende Hälfte ebenfalls auf 337500 Stück Kleinvieh,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 44, '36000 Rinder,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 45, '30500 Esel');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 46, 'und 16000 Menschen –,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 47, 'von der den Israeliten zukommenden Hälfte also nahm Mose immer ein Stück, das er aus je fünfzig Stück herausgegriffen hatte, sowohl von den Menschen als auch vom Vieh und übergab sie den Leviten, die den Dienst an der Wohnung des HERRN zu verrichten hatten, wie der HERR dem Mose geboten hatte.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 48, 'Nun traten zu Mose die Befehlshaber über die Abteilungen des Heeres, die Hauptleute der Tausendschaften und die Hauptleute der Hundertschaften,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 49, 'und sagten zu Mose: »Deine Knechte haben die Gesamtzahl der Kriegsleute festgestellt, die unter unserm Befehl gestanden haben, und es ist dabei kein einziger von unseren Leuten vermißt worden.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 50, 'Darum bringen wir jetzt als Opfergabe für den HERRN das dar, was ein jeder an Goldschmuck erbeutet hat: Armketten und Armspangen, Fingerringe, Ohrringe und Geschmeide, um für unsere Seelen Sühne vor dem HERRN zu erlangen.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 51, 'Da nahmen Mose und der Priester Eleasar das Gold, allerlei künstlich gearbeitete Sachen, von ihnen in Empfang;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 52, 'und es belief sich alles Gold, das sie zum Hebeopfer für den HERRN bestimmt hatten, auf 16750 Schekel von seiten der Hauptleute über tausend und der Hauptleute über hundert Mann;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 53, 'die gemeinen Kriegsleute aber hatten ein jeder für sich Beute gemacht.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 54, 'Mose und der Priester Eleasar nahmen also das Gold von den Hauptleuten der Tausendschaften und der Hundertschaften in Empfang und brachten es in das Offenbarungszelt, damit es dort den Israeliten vor dem HERRN zum gnädigen Gedächtnis diene.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 1, 'Die Stämme Ruben und Gad besaßen aber außerordentlich viel Vieh. Als sie sich nun die Landschaft Jaser und die Landschaft Gilead ansahen, erkannten sie, daß die Gegend zur Viehzucht geeignet war.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 2, 'So gingen denn die Stämme Gad und Ruben hin und sagten zu Mose und zu dem Priester Eleasar und zu den Häuptern der Gemeinde:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 3, '»Ataroth, Dibon, Jaser, Nimra, Hesbon, Eleale, Sebam, Nebo und Beon,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 4, 'das Land, das der HERR der Gemeinde Israel unterworfen hat, ist ein zur Viehzucht geeignetes Land, und deine Knechte besitzen viel Vieh.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 5, 'Dann fuhren sie fort: »Wenn du uns eine Liebe erweisen willst, so möge diese Landschaft deinen Knechten als Erbbesitz überwiesen werden: laß uns nicht mit über den Jordan ziehen!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 6, 'Darauf antwortete Mose den Stämmen Gad und Ruben: »Eure Brüder sollen also in den Krieg ziehen, und ihr wollt ruhig hier bleiben?');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 7, 'Warum wollt ihr denn die (übrigen) Israeliten von dem Entschluß abbringen, in das Land hinüberzuziehen, das der HERR für sie bestimmt hat?');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 8, 'Ebenso haben es auch eure Väter gemacht, als ich sie von Kades-Barnea zur Besichtigung des Landes aussandte.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 9, 'Als sie nämlich bis zum Tal Eskol hinaufgezogen waren und sich das Land angesehen hatten, brachten sie die Israeliten von ihrem Entschluß ab, so daß sie nicht in das Land ziehen wollten, das der HERR für sie bestimmt hatte.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 10, 'Da entbrannte aber der Zorn des HERRN an jenem Tage, so daß er mit einem Schwur aussprach:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 11, '›Die Männer, die aus Ägypten ausgezogen sind, von zwanzig Jahren an und darüber, die sollen nimmermehr das Land zu sehen bekommen, das ich Abraham, Isaak und Jakob zugeschworen habe, denn sie sind mir nicht in allen Stücken gehorsam gewesen,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 12, 'außer dem Kenissiter Kaleb, dem Sohn Jephunnes, und außer Josua, dem Sohne Nuns; denn diese beiden sind dem HERRN in allen Stücken gehorsam gewesen.‹');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 13, 'So entbrannte also der Zorn des HERRN gegen Israel, und er ließ sie vierzig Jahre lang in der Wüste umherirren, bis das ganze Geschlecht, das in den Augen des HERRN übel gehandelt hatte, ausgestorben war.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 14, 'Und jetzt seid ihr an Stelle eurer Väter aufgetreten, ein Nachwuchs von Sündern, um den lodernden Zorn des HERRN gegen Israel noch zu mehren!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 15, 'Wenn ihr euch vom Gehorsam gegen ihn abwendet, so wird er das Volk noch länger in der Wüste belassen, und ihr werdet so dies ganze Volk zugrunde richten!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 16, 'Da traten sie an ihn heran und sagten: »Wir wollen hier nur Viehhürden für unsere Herden und feste Wohnorte für unsere Frauen und Kinder bauen;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 17, 'wir selbst aber wollen kampfgerüstet an der Spitze der Israeliten einherziehen, bis wir sie in ihre Wohnsitze gebracht haben; unterdessen sollen unsere Frauen und Kinder wegen der (feindseligen) Bewohner des Landes in den befestigten Ortschaften bleiben.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 18, 'Wir wollen nicht eher in unsere Häuser zurückkehren, als bis die Israeliten sämtlich ihren Erbbesitz empfangen haben;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 19, 'denn wir beanspruchen keinen Besitz neben ihnen jenseits des Jordans und weiterhin, wenn uns unser Erbbesitz diesseits des Jordans gegen Osten zuteil geworden ist.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 20, 'Da sagte Mose zu ihnen: »Wenn ihr das wirklich tut, daß ihr euch vor dem HERRN zum Kriege rüstet');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 21, 'und ihr alle gerüstet vor den Augen des HERRN über den Jordan zieht, bis er seine Feinde vor sich her ausgetrieben hat,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 22, 'und ihr erst dann wieder heimkehrt, nachdem das Land vor dem HERRN unterworfen ist, so sollt ihr eurer Verpflichtungen gegen den HERRN und gegen Israel los und ledig sein, und dieses Land soll euch als Erbbesitz vor dem HERRN zuteil werden.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 23, 'Wenn ihr aber nicht so handelt, so habt ihr euch damit gegen den HERRN versündigt und werdet die Folgen eurer Versündigung zu fühlen bekommen!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 24, 'Baut euch also Städte für eure Frauen und Kinder und Hürden für euer Kleinvieh, tut aber auch, was ihr versprochen habt!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 25, 'Da gaben die Stämme Gad und Ruben dem Mose folgende Versicherung: »Deine Knechte werden tun, wie du, Herr, befiehlst:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 26, 'unsere Kinder, unsere Frauen, unsere Herden und all unsere Lasttiere sollen hier in den Ortschaften Gileads bleiben,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 27, 'wir aber, deine Knechte, werden alle, soweit sie waffenfähig sind, vor dem HERRN her zum Kampf hinüberziehen, wie du, Herr, befohlen hast.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 28, 'Darauf gab Mose ihretwegen dem Priester Eleasar und Josua, dem Sohne Nuns, und den Stammeshäuptern der Israeliten Anweisung,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 29, 'indem er ihnen auftrug: »Wenn die Gaditen und Rubeniten, alle Waffenfähigen, mit euch zum Kriege vor dem HERRN her über den Jordan ziehen, so sollt ihr, wenn das Land unterworfen vor euch daliegt, ihnen die Landschaft Gilead zum Erbbesitz geben;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 30, 'wenn sie aber nicht kampfgerüstet mit euch hinüberziehen, so sollen sie unter euch im Lande Kanaan angesiedelt werden.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 31, 'Da gaben die Gaditen und Rubeniten folgende Erklärung ab: »Wie der HERR deinen Knechten geboten hat, so wollen wir tun:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 32, 'wir wollen kampfgerüstet vor dem HERRN her in das Land Kanaan hinüberziehen, damit uns unser Erbbesitz diesseits des Jordans verbleibt.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 33, 'Darauf überwies Mose ihnen – den Stämmen Gad und Ruben und dem halben Stamme Manasses, des Sohnes Josephs – das Reich des Amoriterkönigs Sihon und das Reich des Königs Og von Basan, das Land mit den darin liegenden Städten samt den zugehörigen Gebieten ringsum.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 34, 'Da bauten die Gaditen Dibon, Ataroth, Aroer,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 35, 'Ateroth-Sophan, Jaser, Jogbeha,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 36, 'Beth-Nimra und Beth-Haran wieder auf, feste Städte und Hürden für das Kleinvieh.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 37, 'Die Rubeniten aber bauten Hesbon, Eleale, Kirjathaim,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 38, 'Nebo, Baal-Meon [mit verändertem Namen zu sprechen!] und Sibma wieder auf; sie gaben aber den Städten, die sie wieder aufgebaut hatten, andere Namen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 39, 'Die Söhne Machirs aber, des Sohnes Manasses, zogen nach Gilead, eroberten es und trieben die Amoriter aus, die darin wohnten.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 40, 'Mose verlieh dann Gilead dem Machir, dem Sohne Manasses, und dieser siedelte sich dort an.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 41, 'Jair aber, der Sohn Manasses, zog hin, bemächtigte sich ihrer (der Amoriter) Zeltdörfer und gab ihnen den Namen »Zeltdörfer Jairs«. –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 42, 'Auch Nobah zog hin, nahm Kenath und die dazugehörigen Ortschaften ein und benannte es nach seinem Namen Nobah.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 1, 'Folgendes sind die einzelnen Züge der Israeliten, in denen sie aus Ägypten nach ihren Heerscharen unter der Führung Moses und Aarons ausgezogen sind.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 2, 'Mose hatte nämlich auf Befehl des HERRN die Orte aufgeschrieben, von denen ihre Auszüge erfolgt waren; und folgendes sind ihre Züge von einem Aufbruchsort zum andern:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 3, 'Sie brachen von Ramses am fünfzehnten Tage des ersten Monats auf; am Tage nach dem Passah zogen die Israeliten mit hoch erhobener Hand vor den Augen aller Ägypter aus,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 4, 'während die Ägypter alle Erstgeborenen begruben, die der HERR unter ihnen hatte sterben lassen; denn der HERR hatte auch an ihren Göttern ein Strafgericht vollzogen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 5, 'Die Israeliten brachen also von Ramses auf und lagerten in Sukkoth.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 6, 'Von Sukkoth zogen sie dann weiter und lagerten in Etham, das am Rande der Wüste liegt.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 7, 'Von Etham zogen sie weiter und wandten sich nach Pi-Hahiroth, das Baal-Zephon gegenüber liegt, und lagerten östlich von Migdol.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 8, 'Von Pi-Hahiroth brachen sie auf und zogen mitten durch das Meer nach der Wüste hin; sie wanderten dann drei Tagereisen weit in der Wüste Etham und lagerten in Mara.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 9, 'Von Mara zogen sie weiter und kamen nach Elim; dort waren zwölf Wasserquellen und siebzig Palmbäume, und sie lagerten daselbst.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 10, 'Von Elim zogen sie weiter und lagerten am Schilfmeer.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 11, 'Vom Schilfmeer zogen sie weiter und lagerten in der Wüste Sin.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 12, 'Aus der Wüste Sin zogen sie weiter und lagerten in Dophka.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 13, 'Von Dophka zogen sie weiter und lagerten in Alus.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 14, 'Von Alus zogen sie weiter und lagerten in Rephidim; dort hatte das Volk kein Wasser zu trinken.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 15, 'Von Rephidim zogen sie weiter und lagerten in der Wüste Sinai.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 16, 'Aus der Wüste Sinai zogen sie weiter und lagerten bei den Lustgräbern.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 17, 'Von den Lustgräbern zogen sie weiter und lagerten in Hazeroth.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 18, 'Von Hazeroth zogen sie weiter und lagerten in Rithma.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 19, 'Von Rithma zogen sie weiter und lagerten in Rimmon-Perez.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 20, 'Von Rimmon-Perez zogen sie weiter und lagerten in Libna.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 21, 'Von Libna zogen sie weiter und lagerten in Rissa.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 22, 'Von Rissa zogen sie weiter und lagerten in Kehelatha.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 23, 'Von Kehelatha zogen sie weiter und lagerten am Berge Sepher.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 24, 'Vom Berge Sepher zogen sie weiter und lagerten in Harada.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 25, 'Von Harada zogen sie weiter und lagerten in Makheloth.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 26, 'Von Makheloth zogen sie weiter und lagerten in Thahath.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 27, 'Von Thahath zogen sie weiter und lagerten in Therah.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 28, 'Von Therah zogen sie weiter und lagerten in Mithka.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 29, 'Von Mithka zogen sie weiter und lagerten in Hasmona.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 30, 'Von Hasmona zogen sie weiter und lagerten in Moseroth.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 31, 'Von Moseroth zogen sie weiter und lagerten in Bene-Jaakan.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 32, 'Von Bene-Jaakan zogen sie weiter und lagerten in Hor-Hagidgad.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 33, 'Von Hor-Hagidgad zogen sie weiter und lagerten in Jotbatha.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 34, 'Von Jotbatha zogen sie weiter und lagerten in Abrona.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 35, 'Von Abrona zogen sie weiter und lagerten in Ezjon-Geber.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 36, 'Von Ezjon-Geber zogen sie weiter und lagerten in der Wüste Zin, das ist Kades.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 37, 'Von Kades zogen sie weiter und lagerten am Berge Hor, an der Grenze des Landes der Edomiter.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 38, 'Da stieg der Priester Aaron nach dem Befehl des HERRN auf den Berg Hor hinauf und starb daselbst im vierzigsten Jahr nach dem Auszug der Israeliten aus dem Lande Ägypten am ersten Tage des fünften Monats;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 39, 'Aaron war aber 123 Jahre alt, als er auf dem Berge Hor starb.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 40, '[Und der Kanaanäer, der König von Arad, der im südlichen Teile des Landes Kanaan wohnte, hörte vom Heranrücken der Israeliten.]');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 41, 'Vom Berge Hor zogen sie dann weiter und lagerten in Zalmona.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 42, 'Von Zalmona zogen sie weiter und lagerten in Phunon.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 43, 'Von Phunon zogen sie weiter und lagerten in Oboth.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 44, 'Von Oboth zogen sie weiter und lagerten in Ijje-Abarim an der Grenze des Moabiterlandes.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 45, 'Von Ijjim zogen sie weiter und lagerten in Dibon-Gad.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 46, 'Von Dibon-Gad zogen sie weiter und lagerten in Almon-Diblathaim.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 47, 'Von Almon-Diblathaim zogen sie weiter und lagerten am Gebirge Abarim östlich vom Nebo.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 48, 'Vom Gebirge Abarim zogen sie weiter und lagerten sich in den Steppen der Moabiter am Jordan, Jericho gegenüber;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 49, 'und zwar lagerten sie am Jordan von Beth-Jesimoth bis Abel-Sittim in den Steppen der Moabiter.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 50, 'Der HERR gebot dann dem Mose in den Steppen der Moabiter am Jordan, Jericho gegenüber: »Teile den Israeliten folgende Verordnungen mit:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 51, 'Wenn ihr über den Jordan in das Land Kanaan hinübergezogen seid,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 52, 'sollt ihr alle Bewohner des Landes vor euch her austreiben und alle ihre Götzenbilder vernichten; auch alle ihre Gußbilder sollt ihr vernichten und alle ihre Höhen zerstören.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 53, 'Ihr sollt dann das Land in Besitz nehmen und darin wohnen; denn euch habe ich das Land als Eigentum verliehen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 54, 'Und zwar sollt ihr euch das Land durch das Los als Erbbesitz zuteilen entsprechend euren Stämmen: den größeren Stämmen sollt ihr einen größeren Erbbesitz geben und den kleineren einen weniger großen Erbbesitz zuteilen; doch wohin immer einem jeden das Los fällt, da soll es ihm als Eigentum zuteil werden: nach euren väterlichen Stämmen sollt ihr euch das Land als Erbbesitz zuteilen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 55, 'Wenn ihr aber die Bewohner des Landes nicht vor euch her austreibt, so werden die, welche ihr von ihnen übriglaßt, zu Dornen in euren Augen und zu Stacheln in euren Seiten werden und euch in dem Lande, in dem ihr wohnen werdet, bedrängen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 56, 'Die Folge wird dann sein, daß ich euch das Geschick widerfahren lasse, das ich ihnen zugedacht hatte.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 34, 1, 'Weiter sagte der HERR zu Mose:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 34, 2, '»Folgende Verordnungen sollst du den Israeliten mitteilen: Wenn ihr in das Land Kanaan kommt, so soll dies das Gebiet sein, das euch als Erbbesitz zufällt: das Land Kanaan in seinem ganzen Umfang.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 34, 3, 'Und zwar soll die Südseite sich euch von der Wüste Zin an, Edom entlang, hinziehen, so daß eure Südgrenze im Osten am (südlichen) Ende des Salzmeeres beginnt.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 34, 4, 'Dann soll eure Grenze südlich vom Skorpionenstieg umbiegen und sich nach Zin hinüberziehen, wo sie südlich von Kades-Barnea endigt; von dort soll sie weiter nach Hazar-Addar hin laufen und nach Azmon hinübergehen;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 34, 5, 'und von Azmon wende sich die Grenze nach dem Bach Ägyptens hin und endige nach dem Westmeer zu. –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 34, 6, 'Was sodann die Westgrenze betrifft, so gelte euch da das große Meer zugleich als Grenze; das soll eure Westgrenze sein. –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 34, 7, 'Und folgendes soll eure Nordgrenze sein: vom großen Westmeer an sollt ihr euch eine Grenzlinie bis zum Berge Hor ziehen;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 34, 8, 'vom Berge Hor an sollt ihr euch eine Grenzlinie in der Richtung auf Hamath hin ziehen, und das Ende der Grenze soll nach Zedad hin sein;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 34, 9, 'dann laufe die Grenze weiter nach Siphron hin und erreiche ihr Ende bei Hazar-Enan. Das soll eure Nordgrenze sein. –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 34, 10, 'Als Ostgrenze aber sollt ihr euch eine Linie von Hazar-Enan nach Sepham festsetzen;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 34, 11, 'und von Sepham gehe die Grenze nach Ha-Ribla hinab östlich von Ain; dann ziehe sich die Grenze noch weiter hinab und stoße auf den Höhenzug östlich vom See Genezareth;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 34, 12, 'dann ziehe sich die Grenze den Jordan entlang hinab und erreiche ihr Ende am Salzmeer. Dies soll euer Land nach seinen Grenzen ringsum sein.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 34, 13, 'Mose gab dann den Israeliten folgende Weisung: »Dies ist das Land, das ihr euch durchs Los als euren Erbbesitz zuteilen sollt und das der HERR den neun Stämmen und dem halben Stamm (Manasse) zu geben geboten hat.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 34, 14, 'Denn alle zu den beiden Stämmen Ruben und Gad gehörenden Familien und der halbe Stamm Manasse haben ihren Erbbesitz bereits empfangen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 34, 15, 'Diese zweieinhalb Stämme haben ihren Erbbesitz auf der andern Seite des Jordans, Jericho gegenüber, im Osten, nach Sonnenaufgang hin, bereits erhalten.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 34, 16, 'Weiter sagte der HERR zu Mose folgendes:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 34, 17, '»Dies sind die Namen der Männer, die das Land als Erbbesitz unter euch verteilen sollen: der Priester Eleasar und Josua, der Sohn Nuns;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 34, 18, 'dazu sollt ihr von jedem Stamm einen Fürsten zu der Verteilung des Landes hinzuziehen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 34, 19, 'Und dies sind die Namen der Männer: für den Stamm Juda: Kaleb, der Sohn Jephunnes;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 34, 20, 'für den Stamm Simeon: Samuel, der Sohn Ammihuds;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 34, 21, 'für den Stamm Benjamin: Elidad, der Sohn Kislons;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 34, 22, 'für den Stamm Dan als Fürst: Bukki, der Sohn Joglis;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 34, 23, 'für die Nachkommen Josephs: für den Stamm Manasse als Fürst: Hanniel, der Sohn Ephods,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 34, 24, 'und für den Stamm Ephraim als Fürst: Kemuel, der Sohn Siphtans;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 34, 25, 'für den Stamm Sebulon als Fürst: Elizaphan, der Sohn Parnachs;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 34, 26, 'für den Stamm Issaschar als Fürst: Paltiel, der Sohn Assans;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 34, 27, 'für den Stamm Asser als Fürst: Ahihud, der Sohn Selomis;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 34, 28, 'für den Stamm Naphthali als Fürst: Pedahel, der Sohn Ammihuds.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 34, 29, 'Diese waren es, denen der HERR gebot, den Israeliten ihren Erbbesitz im Lande Kanaan zuzuteilen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 35, 1, 'Weiter gebot der HERR dem Mose in den Steppen der Moabiter am Jordan, Jericho gegenüber, folgendes:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 35, 2, '»Befiehl den Israeliten, daß sie von ihrem Erbbesitz den Leviten Städte zum Wohnen geben; und zu den Städten sollt ihr auch eine Weidetrift rings um sie her den Leviten geben.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 35, 3, 'Die Städte sollen ihnen dann als Wohnsitze dienen, während die zugehörigen Weidetriften für ihr Lastvieh und ihre Herden und für alle ihre übrigen Tiere bestimmt sind.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 35, 4, 'Es sollen sich aber die Weidetriften bei den Städten, die ihr den Leviten zu geben habt, von der Stadtmauer nach außen hin tausend Ellen weit ringsum erstrecken;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 35, 5, 'und ihr sollt außerhalb der Stadt auf der Ostseite zweitausend Ellen abmessen und ebenso auf der Südseite zweitausend Ellen und auf der Westseite zweitausend Ellen und auf der Nordseite zweitausend Ellen, so daß die Stadt selbst in der Mitte liegt; dies sollen für sie die Weideplätze bei den Städten sein.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 35, 6, 'Unter den Städten aber, die ihr den Leviten zu geben habt, sollen sich die sechs Freistädte befinden, die ihr ihnen abtreten sollt, damit dorthin fliehen kann, wer einen Totschlag begangen hat; außer diesen aber sollt ihr ihnen noch zweiundvierzig Städte geben:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 35, 7, 'die Gesamtzahl der Städte, die ihr den Leviten zu geben habt, soll sich auf achtundvierzig Städte nebst den zugehörigen Weidetriften belaufen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 35, 8, 'Was aber die Städte betrifft, die ihr von dem Besitztum der Israeliten abzugeben habt, so sollt ihr von den größeren Stämmen eine größere Anzahl und von den kleineren Stämmen eine kleinere Anzahl von Städten nehmen: jeder Stamm soll nach Maßgabe seines Erbbesitzes, den er erhalten wird, von seinen Städten eine bestimmte Zahl an die Leviten abtreten.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 35, 9, 'Der HERR gebot dann weiter dem Mose folgendes:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 35, 10, '»Teile den Israeliten folgende Verordnungen mit: Wenn ihr über den Jordan in das Land Kanaan hinüberkommt,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 35, 11, 'sollt ihr euch passend gelegene Städte auswählen, die euch als Freistädte dienen sollen, damit ein Totschläger dahin fliehen kann, der einen Menschen unvorsätzlich erschlagen hat.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 35, 12, 'Diese Städte sollen euch nämlich als Zufluchtsorte vor dem Bluträcher dienen, damit der Totschläger nicht getötet wird, ehe er vor der Gemeinde gestanden hat, um abgeurteilt zu werden.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 35, 13, 'Es sollen aber die Städte, die ihr zu solchen Freistädten herzugeben habt, sechs an Zahl sein:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 35, 14, 'drei Städte sollt ihr diesseits des Jordans dazu bestimmen und drei Städte im Lande Kanaan dazu hergeben: Freistädte sollen es sein.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 35, 15, 'Für die Israeliten wie für die Fremdlinge und die Beisassen, die unter ihnen leben, sollen diese sechs Städte als Zufluchtsorte dienen, damit jeder dorthin fliehen kann, der einen Menschen unvorsätzlich erschlagen hat.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 35, 16, '»Wenn er ihn aber mit einem eisernen Werkzeug geschlagen hat, so daß er daran gestorben ist, so ist er ein Mörder: als solcher muß er unbedingt mit dem Tode bestraft werden.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 35, 17, 'Wenn er ihn ferner mit einem Stein, den er in der Hand hatte und der den Tod verursachen kann, geschlagen hat, so daß jener daran gestorben ist, so ist er ein Mörder: als solcher muß er unbedingt mit dem Tode bestraft werden.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 35, 18, 'Oder wenn er ihn mit einem hölzernen Werkzeug, das er in der Hand hatte und durch das jemand getötet werden kann, geschlagen hat, so daß jener daran gestorben ist, so ist er ein Mörder: als solcher muß er unbedingt mit dem Tode bestraft werden;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 35, 19, 'der Bluträcher soll den Mörder töten; sobald er ihn antrifft, soll er ihn töten.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 35, 20, 'Wenn ferner jemand einem andern aus Haß einen Stoß versetzt oder vorsätzlich nach ihm geworfen hat, so daß jener daran gestorben ist,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 35, 21, 'oder wenn er ihn aus Feindschaft mit der Hand geschlagen hat, so daß jener daran gestorben ist, so muß der, welcher ihn geschlagen hat, unbedingt mit dem Tode bestraft werden: er ist ein Mörder: der Bluträcher soll den Mörder töten, sobald er ihn antrifft.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 35, 22, 'Hat er ihn aber von ungefähr, nicht aus Feindschaft, gestoßen oder unabsichtlich irgendeinen Gegenstand auf ihn geworfen');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 35, 23, 'oder, ohne ihn zu sehen, irgendeinen Stein, durch den jemand getötet werden kann, auf ihn fallen lassen und jener ist daran gestorben, obgleich er ihm nicht feindlich gesinnt war und ohne daß er ihm Schaden zufügen wollte:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 35, 24, 'so soll die Gemeinde zwischen dem Totschläger und dem Bluträcher nach diesen Rechtsbestimmungen entscheiden,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 35, 25, 'und die Gemeinde soll den Totschläger vor der Gewalttätigkeit des Bluträchers schützen, und die Gemeinde soll ihn in die ihm zustehende Freistadt, in die er sich geflüchtet hatte, zurückbringen, und er soll darin wohnen bleiben bis zum Tode des Hohenpriesters, den man mit dem heiligen Öl gesalbt hat.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 35, 26, 'Wenn aber der Totschläger aus dem Gebiet der ihm zustehenden Freistadt, in die er geflohen ist, hinausgeht');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 35, 27, 'und der Bluträcher ihn außerhalb des Gebiets der betreffenden Freistadt antrifft und den Totschläger tötet, so lädt er keine Blutschuld auf sich;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 35, 28, 'denn jener hat in der ihm zustehenden Freistadt bis zum Tode des Hohenpriesters zu bleiben, und erst nach dem Tod des Hohenpriesters darf der Totschläger an den Ort, wo sein Erbbesitz liegt, zurückkehren.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 35, 29, 'Diese Rechtsbestimmungen sollen bei euch für eure künftigen Geschlechter in allen euren Wohnsitzen zu Recht bestehen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 35, 30, 'Wenn irgend jemand einen Menschen erschlägt, so soll man den Mörder auf die Aussage von Zeugen mit dem Tode bestrafen; aber das Zeugnis eines einzelnen soll nicht hinreichen, um jemand zum Tode zu verurteilen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 35, 31, 'Ihr dürft auch kein Lösegeld für das Leben eines Mörders, der des Todes schuldig ist, annehmen, vielmehr soll er unbedingt mit dem Tode bestraft werden.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 35, 32, 'Auch dürft ihr kein Lösegeld für jemand, der in die ihm zustehende Freistadt geflohen ist, zu dem Zweck annehmen, daß er schon vor dem Tode des Hohenpriesters zurückkehren und irgendwo im Lande wohnen dürfe.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 35, 33, 'Ihr sollt das Land, in dem ihr wohnt, nicht entweihen; denn das Blut entweiht das Land, und dem Lande kann für das Blut, das darin vergossen worden ist, keine Sühne geschafft werden außer durch das Blut dessen, der es vergossen hat.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 35, 34, 'So verunreinigt denn das Land nicht, in dem ihr wohnt und in dessen Mitte auch ich wohne; denn ich, der HERR, wohne inmitten der Israeliten.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 36, 1, 'Die Familienhäupter des Geschlechts, das von Gilead, dem Sohne Machirs, dem Enkel Manasses, stammte und zu den von Joseph stammenden Geschlechtern gehörte, traten auf und trugen dem Mose und den Fürsten, den Stammeshäuptern der Israeliten,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 36, 2, 'folgendes Anliegen vor: »Gott hat dir, o Herr, geboten, den Israeliten das Land durch das Los zum Erbbesitz zu geben; auch hast du, Herr, von Gott die Weisung erhalten, den Erbbesitz unseres Stammgenossen Zelophhad seinen Töchtern zu überweisen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 36, 3, 'Wenn diese sich nun aber mit einem Manne verheiraten, der zu einem andern Stamme der Israeliten gehört, so geht ihr Erbbesitz dem Erbbesitz unserer Väter verloren und wird zu dem Erbbesitz des Stammes geschlagen, dem sie (nach ihrer Verheiratung) angehören, während er dem Losteile unseres Erbbesitzes verlorengeht.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 36, 4, 'Und auch wenn das Halljahr für die Israeliten kommt, so bleibt ihr Erbbesitz mit dem Erbbesitz des Stammes vereinigt, dem sie (nach ihrer Verheiratung) angehören; aber dem Erbbesitz des Stammes unserer Väter geht ihr Erbbesitz verloren.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 36, 5, 'Da gab Mose den Israeliten nach dem Geheiß des HERRN folgende Weisung: »Der Stamm der Nachkommen Josephs hat recht.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 36, 6, 'So lautet die Verordnung, die der HERR in betreff der Töchter Zelophhads erlassen hat: Sie mögen sich ganz nach ihrem Gefallen verheiraten; jedoch dürfen sie nur mit einem Manne aus einem Geschlecht ihres väterlichen Stammes die Ehe eingehen,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 36, 7, 'damit nicht ein Erbbesitz der Israeliten von einem Stamm an einen andern übergeht; denn die Israeliten sollen ein jeder den Erbbesitz ihres väterlichen Stammes ungeschmälert erhalten.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 36, 8, 'Darum darf jedes Mädchen, das in einem von den israelitischen Stämmen zu Grundbesitz gelangt, nur einen Mann aus einem Geschlecht ihres väterlichen Stammes heiraten, damit die Israeliten allesamt ihren väterlichen Erbbesitz ungeschmälert erhalten');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 36, 9, 'und kein Erbbesitz von einem Stamm an einen andern übergeht; denn die Stämme der Israeliten sollen ein jeder seinen Erbbesitz ungeschmälert erhalten.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 36, 10, 'Wie der HERR dem Mose geboten hatte, so taten die Töchter Zelophhads;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 36, 11, 'denn Mahla, Thirza, Hogla, Milka und Noa, die Töchter Zelophhads, verheirateten sich mit den Söhnen ihrer Oheime;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 36, 12, 'mit Männern aus den Geschlechtern, die von Manasse, dem Sohne Josephs, stammten, verheirateten sie sich, und so verblieb ihr Erbbesitz bei dem Stamme, dem das Geschlecht ihres Vaters angehörte.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 36, 13, 'Dies sind die Gebote und Verordnungen, die der HERR an die Israeliten in den Steppen der Moabiter am Jordan, Jericho gegenüber, durch Vermittlung Moses hat ergehen lassen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 1, 'Dies sind die Worte, die Mose an ganz Israel gerichtet hat jenseits des Jordans in der Wüste, in der Steppe, gegenüber Suph, zwischen Paran, Thophel, Laban, Hazeroth und Disahab.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 2, 'Elf Tagereisen lang ist der Weg vom Horeb nach dem Gebirge Seir bis Kades-Barnea. –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 3, 'Im vierzigsten Jahre, am ersten Tage des elften Monats, war es: da trug Mose den Israeliten alles genau so vor, wie der HERR es ihm für sie geboten hatte,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 4, 'nachdem er den Amoriterkönig Sihon, der in Hesbon wohnte, und Og, den König von Basan, der in Astharoth wohnte, bei Edrei geschlagen hatte.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 5, 'Jenseits des Jordans, im Lande der Moabiter, unternahm es Mose, die folgende Unterweisung vorzutragen:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 6, '»Der HERR, unser Gott, hat am Horeb so zu uns gesprochen: ›Ihr habt nun lange genug an diesem Berge verweilt;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 7, 'brecht jetzt auf und zieht unverweilt nach dem Bergland der Amoriter und zu all ihren Nachbarn, die in der Jordanebene, in dem Bergland, in der Niederung, im Südland und an der Meeresküste wohnen, (also) in das Land der Kanaanäer und nach dem Libanon bis an den großen Strom, den Euphratstrom.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 8, 'Ich übergebe euch hiermit das Land: zieht hinein und nehmt es in Besitz, das Land, dessen Verleihung der HERR euren Vätern Abraham, Isaak und Jakob und ihrer Nachkommenschaft nach ihnen eidlich zugesagt hat.‹«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 9, '»Damals sagte ich zu euch: ›Ich allein bin nicht imstande, (die Sorge für) eure Angelegenheiten zu tragen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 10, 'Der HERR, euer Gott, hat euch so zahlreich werden lassen, daß ihr schon jetzt den Sternen des Himmels an Menge gleichkommt.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 11, 'Der HERR, der Gott eurer Väter, möge eure jetzige Zahl noch tausendmal größer werden lassen und euch so segnen, wie er euch verheißen hat!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 12, 'Wie vermöchte ich aber allein die Last und Bürde eurer Angelegenheiten und eurer Streitsachen zu tragen?');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 13, 'Bringt aus euren Stämmen weise, verständige und erfahrene Männer her, damit ich sie zu Oberhäuptern über euch einsetze!‹');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 14, 'Da antwortetet ihr mir: ›Der Vorschlag, den du gemacht hast, eignet sich trefflich zur Ausführung.‹');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 15, 'Da nahm ich eure Stammeshäupter, weise und erfahrene Männer, und setzte sie zu Oberhäuptern über euch ein als Oberste über die Tausendschaften oder Hundertschaften und als Anführer von je fünfzig oder je zehn und auch als Obmänner für eure Stämme.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 16, 'Zu gleicher Zeit gab ich euren Richtern folgende Anweisung: ›Wenn ihr eure Volksgenossen bei Streitsachen verhört, so entscheidet mit Gerechtigkeit, mag jemand mit einem von seinen Volksgenossen oder mit einem bei ihm wohnenden Fremdling einen Streit haben!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 17, 'Ihr dürft beim Rechtsprechen die Person nicht ansehen: den Niedrigsten müßt ihr ebenso wie den Vornehmsten anhören und euch vor niemand scheuen; denn das Gericht ist Gottes Sache. Sollte aber ein Rechtsfall für euch zu schwierig sein, so legt ihn mir vor, damit ich die Untersuchung dabei führe.‹');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 18, 'So gab ich euch damals Anweisung für alles, was ihr tun solltet.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 19, '»Als wir dann vom Horeb aufgebrochen waren, durchwanderten wir jene ganze große und schreckliche Wüste, die ihr gesehen habt, in der Richtung nach dem Bergland der Amoriter hin, wie der HERR, unser Gott, uns geboten hatte, und kamen bis Kades-Barnea.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 20, 'Da sagte ich zu euch: ›Ihr seid nun bis zum Bergland der Amoriter gekommen, das der HERR, unser Gott, uns geben will.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 21, 'Ihr wißt, daß der HERR, euer Gott, euch dies Land übergeben hat; so zieht denn hinauf und nehmt es nach dem Befehl des HERRN, des Gottes eurer Väter, in Besitz: fürchtet euch nicht und seid unverzagt!‹');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 22, 'Da tratet ihr alle zu mir und sagtet: ›Wir wollen einige Männer vor uns her senden, die uns das Land auskundschaften und uns Bericht erstatten sollen über den Weg, auf dem wir hinaufziehen müssen, und über die Städte, zu denen wir gelangen werden.‹');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 23, 'Weil der Vorschlag mir zusagte, wählte ich zwölf Männer aus eurer Mitte, je einen Mann für den Stamm.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 24, 'Die zogen dann unverweilt in das Bergland hinauf und kamen bis zum Tal Eskol und kundschafteten (das Land) aus.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 25, 'Sie nahmen auch einige von den Früchten des Landes mit, brachten sie zu uns herab und erstatteten uns Bericht mit den Worten: ›Es ist ein schönes Land, das der HERR, unser Gott, uns geben will.‹');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 26, 'Doch ihr wolltet nicht hinaufziehen, sondern widersetztet euch dem Befehl des HERRN, eures Gottes,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 27, 'und sagtet murrend in euren Zelten: ›Weil der HERR uns haßte, hat er uns aus Ägypten weggeführt, um uns in die Hand der Amoriter fallen zu lassen, damit sie uns vernichten.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 28, 'Wohin sollen wir hinaufziehen? Unsere Volksgenossen haben uns das Herz mutlos gemacht, indem sie berichtet haben: Die Leute sind dort zahlreicher als wir und höher gewachsen, die Städte groß und bis an den Himmel befestigt, und sogar Riesen haben wir dort gesehen.‹«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 29, '»Da sagte ich zu euch: ›Laßt euch nicht entmutigen und fürchtet euch nicht vor ihnen!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 30, 'Der HERR, euer Gott, der vor euch einherzieht, wird selbst für euch streiten, ganz so, wie er euch in Ägypten sichtbar geholfen hat');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 31, 'und auch in der Wüste, wo, wie ihr gesehen habt, der HERR, euer Gott, euch getragen hat, wie ein Vater seinen Sohn trägt, auf dem ganzen Wege, den ihr gezogen seid, bis zu eurer Ankunft an diesem Orte.‹');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 32, 'Aber trotz alledem bliebt ihr ohne Vertrauen auf den HERRN, euren Gott,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 33, 'der doch auf dem Wege vor euch einherzog, um einen Platz zum Aufschlagen eurer Lager für euch ausfindig zu machen: bei Nacht im Feuer, damit ihr auf dem Wege sehen könntet, den ihr ziehen solltet, und bei Tag in der Wolke.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 34, '»Als nun der HERR euer lautes Reden vernahm, wurde er zornig und schwur:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 35, '›Wahrlich, kein einziger von diesen Männern, von diesem nichtswürdigen Geschlecht, soll das schöne Land zu sehen bekommen, dessen Verleihung ich euren Vätern zugeschworen habe,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 36, 'außer Kaleb, dem Sohn Jephunnes; dieser soll es zu sehen bekommen, und ihm und seinen Söhnen will ich das Land geben, dessen Boden er bereits betreten hat, zum Lohn dafür, daß er dem HERRN in allen Stücken gehorsam gewesen ist.‹');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 37, 'Auch mir zürnte der HERR um euretwillen, so daß er aussprach: ›Auch du sollst nicht dorthin kommen:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 38, 'Josua, der Sohn Nuns, dein Diener, der soll dorthin kommen; ihm sprich Mut ein, denn er soll das Land den Israeliten als Erbbesitz austeilen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 39, 'Auch eure kleinen Kinder, von denen ihr gesagt habt, sie würden eine Beute (der Feinde) werden, und eure jungen Söhne, die heute noch nicht Gutes und Böses zu unterscheiden wissen, die sollen dorthin kommen! Denn ihnen will ich das Land geben, und sie sollen es in Besitz nehmen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 40, 'Ihr aber – kehrt um und zieht in die Wüste in der Richtung nach dem Schilfmeer!‹');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 41, 'Da gabt ihr mir zur Antwort: ›Wir haben uns gegen den HERRN versündigt; wir wollen nun doch hinaufziehen und kämpfen, ganz wie der HERR, unser Gott, uns geboten hat!‹ So gürtetet ihr euch denn sämtlich eure Waffen um und wolltet leichtfertig in das Bergland hinaufziehen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 42, 'Da gebot mir der HERR: ›Warne sie hinaufzuziehen und zu kämpfen! Denn ich bin nicht in eurer Mitte; sonst werdet ihr von euren Feinden eine Niederlage erleiden!‹');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 43, 'Ich warnte euch also, doch ihr wolltet nicht hören, sondern widersetztet euch dem Befehl des HERRN und zogt in Vermessenheit in das Bergland hinauf.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 44, 'Da rückten die Amoriter, die in jenem Gebirge wohnten, euch entgegen und verfolgten euch wie ein Bienenschwarm und zersprengten euch [in Seir] bis Horma.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 45, 'Nach eurer Rückkehr jammertet ihr dann vor dem HERRN; er aber achtete nicht auf euer Wehklagen und schenkte euch kein Gehör.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 46, 'So mußtet ihr denn in Kades die lange Zeit bleiben, die ihr dort zugebracht habt.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 1, '»So machten wir denn kehrt, zogen nach der Wüste hin in der Richtung nach dem Schilfmeer, wie der HERR mir geboten hatte, und wanderten lange Zeit im Bogen um das Gebirge Seir herum.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 2, 'Da sagte der HERR zu mir:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 3, '›Ihr seid nun lange genug um dieses Gebirge herumgezogen; wendet euch jetzt nordwärts');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 4, 'und gib dem Volk folgende Weisung: Ihr seid jetzt im Begriff, das Gebiet eurer Brüder, der Nachkommen Esaus, die in Seir wohnen, zu durchziehen, und sie werden Furcht vor euch haben; aber hütet euch wohl,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 5, 'Krieg mit ihnen anzufangen! Denn ich werde euch nichts von ihrem Lande geben, auch nicht einen Fußbreit, weil ich das Gebirge Seir dem Esau als Erbbesitz gegeben habe.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 6, 'Lebensmittel für euren Bedarf sollt ihr von ihnen für Geld kaufen, und sogar Wasser zum Trinken sollt ihr von ihnen für Geld erstehen;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 7, 'denn der HERR, dein Gott, hat dich in all deinen Unternehmungen gesegnet; er hat sich deiner während deiner Wanderung durch diese große Wüste angenommen; nun schon vierzig Jahre hindurch ist der HERR, dein Gott, mit dir gewesen, so daß es dir an nichts gemangelt hat.‹');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 8, 'So wanderten wir denn weiter, weg von unseren Brüdern, den Nachkommen Esaus, die in Seir wohnten, weg von der Straße durch die Niederung (am Jordan), weg von Elath und Ezjon-Geber, änderten dann die Marschrichtung und schlugen den Weg nach der Steppe der Moabiter ein.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 9, 'Da sagte der HERR zu mir: ›Greife die Moabiter nicht an und laß dich in keinen Krieg mit ihnen ein! Denn ich werde dir von ihrem Lande nichts zum Besitz geben, weil ich Ar den Nachkommen Lots als Besitztum gegeben habe.‹');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 10, '[Ehemals haben die Emiter darin gewohnt, ein großes, zahlreiches und hochgewachsenes Volk wie die Enakiter.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 11, 'Auch sie wurden, wie die Enakiter, für Rephaiter gehalten; die Moabiter aber nannten sie Emiter.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 12, 'Und in Seir wohnten ehemals die Horiter; aber die Nachkommen Esaus verdrängten sie aus ihrem Besitz, rotteten sie vor sich her aus und ließen sich an ihrer Statt nieder, gerade so wie Israel es mit dem von ihm besetzten Lande gemacht hat, das der HERR ihnen gegeben hatte.] –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 13, '›Macht euch also jetzt auf und zieht über den Fluß Sered!‹ Da zogen wir über den Fluß Sered.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 14, 'Die Zeit unserer Wanderung aber von Kades-Barnea bis zu unserm Übergang über den Fluß Sered hat achtunddreißig Jahre betragen, bis das ganze Geschlecht der kriegstüchtigen Männer aus dem Lager weggestorben war, wie der HERR es ihnen zugeschworen hatte.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 15, 'Es war aber auch die Hand des HERRN gegen sie gewesen, um sie aus dem Lager bis auf den letzten Mann zu vertilgen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 16, 'Als nun die kriegstüchtigen Männer sämtlich aus dem Volke weggestorben waren,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 17, 'sagte der HERR so zu mir:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 18, '›Du bist jetzt im Begriff, die Grenze der Moabiter zu überschreiten, an Ar vorüber,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 19, 'und wirst nun in die Nähe des Gebiets der Ammoniter kommen. Greife sie nicht an und laß dich in keinen Krieg mit ihnen ein! Denn ich werde dir vom Lande der Ammoniter nichts zum Besitz geben, weil ich es den Nachkommen Lots zum Erbbesitz verliehen habe.‹ –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 20, '[Für ein Land der Rephaiter wird auch dieses gehalten: Rephaiter haben ehemals in ihm gewohnt, welche die Ammoniter aber Samsummiter nannten:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 21, 'ein großes, zahlreiches und hochgewachsenes Volk wie die Enakiter; aber der HERR rottete sie vor ihnen her aus, so daß diese ihnen ihr Land wegnahmen und sich an ihrer Statt niederließen,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 22, 'wie er es auch bei den Nachkommen Esaus, die in Seir wohnen, getan hat, vor denen er die Horiter ausrottete, so daß sie ihnen ihr Land wegnahmen und sich an ihrer Statt bis auf den heutigen Tag niedergelassen haben.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 23, 'Auch die Awwiter, die in Gehöften bis Gaza hin wohnten, wurden von den Kaphthoritern ausgerottet, die aus Kaphthor ausgewandert waren und sich an ihrer Statt ansiedelten.] –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 24, '›Brecht nun unverweilt auf und geht über den Fluß Arnon! Ich gebe hiermit den Amoriter Sihon, den König von Hesbon, und sein Land in deine Gewalt. Mache dich sofort an die Eroberung und greife ihn mit den Waffen an!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 25, 'Vom heutigen Tage an will ich Furcht und Schrecken vor dir sich auf die Völker unter dem ganzen Himmel lagern lassen: wenn sie nur die Kunde von dir vernehmen, sollen sie vor dir zittern und beben!‹«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 26, '»Da schickte ich Gesandte aus der Wüste Kedemoth an Sihon, den König von Hesbon, mit folgender friedlichen Botschaft:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 27, '›Laß mich durch dein Land hindurchziehen! ich will überall auf der Landstraße bleiben und weder nach rechts noch nach links davon abweichen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 28, 'Lebensmittel zum Unterhalt sollst du mir für Geld verkaufen und ebenso Wasser zum Trinken mir für Geld überlassen: ich will lediglich zu Fuß hindurchziehen –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 29, 'wie auch die Nachkommen Esaus, die in Seir wohnen, und die Moabiter, die in Ar wohnen, es mit mir gehalten haben –, bis ich über den Jordan in das Land hinüberziehe, das der HERR, unser Gott, uns geben will.‹');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 30, 'Aber Sihon, der König von Hesbon, wollte uns den Durchzug durch sein Land nicht gestatten; denn der HERR, dein Gott, hatte seinen Sinn hart und sein Herz trotzig gemacht, um ihn in deine Gewalt zu geben, wie der heutige Tag es klar zeigt.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 31, 'Da sagte der HERR zu mir: ›Du weißt, daß ich Sihon und sein Land dir bereits preisgegeben habe; mache dich sofort an die Besetzung seines Landes, um es einzunehmen!‹');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 32, 'Als nun Sihon uns mit seinem ganzen Kriegsvolk entgegenzog, um bei Jahaz mit uns zu kämpfen,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 33, 'gab ihn der HERR, unser Gott, in unsere Gewalt, so daß wir ihn samt seinen Söhnen und seinem ganzen Kriegsvolk besiegten.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 34, 'Wir eroberten damals alle seine Städte und vollstreckten in jeder Ortschaft den Bann an Männern, Weibern und Kindern, ohne einen einzigen entrinnen zu lassen;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 35, 'nur das Vieh und den Raub aus den von uns eroberten Städten behielten wir als Beute für uns.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 36, 'Von Aroer, das am Ufer des Arnonflusses liegt, und überhaupt von den Städten, die an dem Flusse liegen, bis nach Gilead hin gab es keinen einzigen festen Platz, der für uns uneinnehmbar gewesen wäre; alles gab der HERR, unser Gott, in unsere Gewalt.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 37, 'Nur das Land der Ammoniter habt ihr unberührt gelassen, alles, was seitwärts vom Flusse Jabbok liegt, und die Ortschaften im Berglande, überhaupt alles, was der HERR, unser Gott, uns verboten hatte.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 3, 1, '»Als wir uns dann wieder aufmachten und in der Richtung nach Basan weiterzogen, rückte uns Og, der König von Basan, mit seinem ganzen Kriegsvolk entgegen, um bei Edrei mit uns zu kämpfen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 3, 2, 'Da sagte der HERR zu mir: ›Fürchte dich nicht vor ihm! Denn ich habe ihn samt seinem ganzen Volk und seinem Lande in deine Gewalt gegeben, und du sollst mit ihm verfahren, wie du mit dem Amoriterkönig Sihon getan hast, der in Hesbon wohnte.‹');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 3, 3, 'So gab denn der HERR, unser Gott, auch Og, den König von Basan, samt seinem ganzen Kriegsvolk in unsere Gewalt, und wir schlugen ihn so, daß kein einziger von ihnen entkam und übrigblieb.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 3, 4, 'Damals eroberten wir alle seine Städte; es gab keine Ortschaft, die wir ihnen nicht entrissen hätten; sechzig Städte, die ganze Landschaft Argob, alles, was zum Königreich Ogs in Basan gehörte,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 3, 5, 'lauter Städte, die mit hohen Mauern, Toren und Riegeln befestigt waren, abgesehen von der großen Zahl der offenen Landstädte.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 3, 6, 'Wir vollstreckten dann den Bann an ihnen, wie wir es bei Sihon, dem König von Hesbon, gemacht hatten, indem wir den Bann in jeder Ortschaft an Männern, Weibern und Kindern vollstreckten;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 3, 7, 'alles Vieh aber und den Raub aus den Städten behielten wir als Beute für uns.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 3, 8, '»So entrissen wir damals der Gewalt der beiden Amoriterkönige das Land diesseits des Jordans vom Fluß Arnon bis zum Gebirge Hermon –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 3, 9, '[die Phönizier nennen den Hermon Sirjon, die Amoriter dagegen nennen ihn Senir] –,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 3, 10, 'alle Städte in der Ebene und ganz Gilead sowie ganz Basan bis Salcha und Edrei, die zum Königreich Ogs gehörenden Städte in Basan.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 3, 11, '[Denn Og, der König von Basan, war der einzige, der vom Rest der Rephaiter noch übriggeblieben war; sein Sarg, ein Sarg von Basalt, befindet sich bekanntlich zu Rabba im Ammoniterlande; seine Länge beträgt neun Ellen und seine Breite vier Ellen, nach der gewöhnlichen Elle gemessen.]');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 3, 12, 'Dieses Land nahmen wir also damals in Besitz. (Das Land) von Aroer an, das am Fluß Arnon liegt, und die Hälfte des Berglandes Gilead samt seinen Städten übergab ich den Stämmen Ruben und Gad;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 3, 13, 'das übrige Gilead aber und ganz Basan, das Reich Ogs, übergab ich dem halben Stamm Manasse, die ganze Landschaft Argob. [Dieser ganze Teil von Basan wird Land der Rephaiter genannt.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 3, 14, 'Jair, der Sohn Manasses, eroberte die ganze Landschaft Argob bis zum Gebiet der Gesuriter und der Maachathiter und nannte diesen Teil von Basan nach seinem Namen die ›Zeltdörfer Jairs‹, wie sie noch bis auf den heutigen Tag heißen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 3, 15, 'Dem Machir aber gab ich Gilead,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 3, 16, 'und den beiden Stämmen Ruben und Gad gab ich von Gilead: das Land bis zum Fluß Arnon, bis zur Mitte des Flusses nebst dem zugehörigen Gebiet, und bis zum Fluß Jabbok, der Grenze der Ammoniter,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 3, 17, 'ferner die Ebene mit dem Jordan und dem zugehörigen Gebiet, vom See Genezareth an bis zum Meer der Steppe, dem Salzmeer, am Fuße der Abhänge des Pisga, gegen Osten.]«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 3, 18, '»Darauf gab ich ihnen damals folgende Weisung: ›Der HERR, euer Gott, hat euch zwar dieses Land zum Besitz gegeben; aber ihr müßt nun kampfgerüstet, soviele von euch waffenfähige Männer sind, an der Spitze eurer Volksgenossen, der Israeliten, hinüberziehen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 3, 19, 'Nur eure Frauen und kleinen Kinder und euer Vieh – ich weiß ja, daß ihr viel Vieh besitzt – sollen in euren Städten, die ich euch gegeben habe, zurückbleiben,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 3, 20, 'bis der HERR euren Volksgenossen, ebenso wie euch, Ruhe geschafft hat und auch sie das Land in Besitz genommen haben, das der HERR, euer Gott, ihnen jenseits des Jordans geben wird; dann mögt ihr wieder heimkehren, ein jeder zu seinem Besitztum, das ich euch gegeben habe.‹ –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 3, 21, 'Dem Josua aber habe ich damals folgende Weisung gegeben: ›Du hast mit eigenen Augen alles gesehen, was der HERR, euer Gott, diesen beiden Königen hat widerfahren lassen. Ebenso wird der HERR es mit allen anderen Königreichen machen, in die du hinüberziehen wirst.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 3, 22, 'Fürchtet euch nicht vor ihnen! Denn der HERR, euer Gott, wird selbst für euch streiten.‹«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 3, 23, '»Auch betete ich in jener Zeit zum HERRN mit den Worten:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 3, 24, '›O HERR, mein Gott, du hast deinen Knecht bisher schon oft deine Größe und deine starke Hand sehen lassen; denn wo gäbe es einen Gott im Himmel und auf der Erde, der solche Werke und so gewaltige Taten vollbringen könnte wie du?');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 3, 25, 'Laß mich doch hinüberziehen und das schöne Land jenseits des Jordans sehen, dieses schöne Bergland und (besonders) den Libanon!‹');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 3, 26, 'Aber der HERR, der um euretwillen Zorn gegen mich hegte, erhörte meine Bitte nicht, sondern antwortete mir: ›Laß es genug sein! Rede nicht noch weiter zu mir in dieser Sache!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 3, 27, 'Steige auf den Gipfel des Pisga hinauf und richte deine Blicke nach Westen und Norden, nach Süden und Osten und sieh dir das Land mit deinen Augen an; denn du wirst nicht über den Jordan da gehen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 3, 28, 'Gib also dem Josua Anweisung, sprich ihm Mut ein und stärke ihn; denn er soll an der Spitze dieses Volkes hinüberziehen, und er soll ihnen das Land, das du sehen wirst, zum Erbbesitz geben.‹ –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 3, 29, 'So blieben wir denn im Tale liegen, Beth-Peor gegenüber.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 1, '»Und nun, Israel, höre auf die Satzungen und auf die Verordnungen, deren Beobachtung ich euch lehren will, damit ihr am Leben bleibt und in den Besitz des Landes kommt, das der HERR, der Gott eurer Väter, euch geben will!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 2, 'Ihr sollt zu den Geboten, die ich euch zur Pflicht mache, nichts hinzufügen und nichts davon wegnehmen, damit ihr die Gebote des HERRN, eures Gottes, beobachtet, die ich euch zur Pflicht mache.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 3, 'Ihr habt mit eigenen Augen gesehen, was der HERR wegen des Baal-Peor getan hat; denn alle Männer, die dem Baal-Peor nachgingen, hat der HERR, dein Gott, aus deiner Mitte vertilgt,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 4, 'während ihr, die ihr am HERRN, eurem Gott, festgehalten habt, heute noch alle am Leben seid.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 5, 'Bedenkt wohl: ich habe euch Satzungen und Verordnungen gelehrt, wie der HERR, mein Gott, mir geboten hat, damit ihr nach ihnen handelt in dem Lande, in das ihr einzieht, um es in Besitz zu nehmen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 6, 'So beobachtet sie denn und haltet sie! Denn darin soll eure Weisheit und eure Einsicht nach dem Urteil der übrigen Völker bestehen, die, wenn sie von all diesen Satzungen Kenntnis erhalten werden, bekennen müssen: ›Wahrlich, ein weises und einsichtiges Volk ist diese große Volksgemeinde!‹');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 7, 'Denn wo gäbe es sonst noch ein großes Volk, das eine Gottheit hätte, die ihm so nahe stände, wie der HERR, unser Gott, zu uns steht, sooft wir zu ihm rufen?');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 8, 'Und wo gäbe es sonst noch ein großes Volk, das so gerechte Satzungen und Verordnungen hätte wie dies ganze Gesetz, das ich euch heute vorlege?«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 9, '»Nur hüte dich und nimm dich wohl in acht, daß du die Ereignisse nicht vergißt, die du mit eigenen Augen gesehen hast, und laß sie dir dein ganzes Leben lang nicht aus der Erinnerung entschwinden! Nein, tu sie deinen Kindern und Kindeskindern kund!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 10, '(Gedenke insbesondere) des Tages, als du am Horeb vor dem HERRN, deinem Gott, standest, als der HERR mir gebot: ›Versammle mir das Volk: ich will sie meine Worte hören lassen, damit sie mich fürchten lernen, solange sie auf dem Erdboden leben, und es auch ihre Kinder lehren!‹');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 11, 'Da tratet ihr nahe heran und stelltet euch am Fuß des Berges auf, während der Berg bis in das Innerste des Himmels hinein in Feuerglut brannte, von Finsternis, Gewölk und Wetterdunkel umgeben.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 12, 'Der HERR redete dann zu euch mitten aus dem Feuer heraus; den Schall seiner Worte vernahmt ihr wohl, aber nur den Schall; eine Gestalt dagegen nahmt ihr nicht wahr.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 13, 'Er verkündete euch seinen Bund, den er euch zu halten gebot, die zehn Gebote, die er dann auf zwei Steintafeln schrieb.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 14, 'Mir aber trug der HERR damals auf, euch Satzungen und Verordnungen zu lehren, die ihr befolgen solltet in dem Lande, in das ihr hinüberziehen würdet, um es in Besitz zu nehmen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 15, 'Da ihr nun an dem Tage, als der HERR am Horeb aus dem Feuer heraus zu euch redete, keinerlei Gestalt von ihm gesehen habt,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 16, 'so hütet euch mit aller Sorgfalt davor, euch dadurch zu versündigen, daß ihr euch ein Gottesbild in der Gestalt irgendeiner Bildsäule anfertigt, die Nachbildung eines männlichen oder weiblichen Wesens,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 17, 'die Nachbildung irgendeines vierfüßigen Tieres, das auf der Erde lebt, die Nachbildung eines beschwingten Vogels, der am Himmel fliegt,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 18, 'die Nachbildung irgendeines Tieres, das auf dem Erdboden kriecht, die Nachbildung irgendeines Fisches, der im Wasser unter der Erde lebt.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 19, 'Laß dich auch, wenn du deine Augen zum Himmel hin erhebst, durch den Anblick der Sonne, des Mondes und der Sterne, des ganzen Himmelsheeres, nicht dazu verführen, dich vor ihnen niederzuwerfen und ihnen zu dienen. Denn der HERR, dein Gott, hat sie allen anderen Völkern unter dem ganzen Himmel zur Verehrung zugewiesen:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 20, 'euch aber hat der HERR genommen und euch aus dem Eisenschmelzofen, aus Ägypten, herausgeführt, damit ihr sein Eigentumsvolk würdet, wie ihr es am heutigen Tage seid.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 21, 'Gegen mich aber ist der HERR um euretwillen in solchen Zorn geraten, daß er geschworen hat, ich solle nicht den Jordan überschreiten und nicht das schöne Land betreten, das der HERR, dein Gott, dir zum Besitz geben will;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 22, 'sondern ich muß in diesem Lande sterben, ohne über den Jordan zu kommen, während ihr hinüberziehen werdet und jenes schöne Land in Besitz nehmt.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 23, 'So hütet euch nun, den Bund, den der HERR, euer Gott, mit euch geschlossen hat, zu vergessen und euch ein Gottesbild anzufertigen, ein Abbild von irgend etwas, das der HERR, dein Gott, dir verboten hat;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 24, 'denn der HERR, dein Gott, ist ein verzehrendes Feuer, ein eifersüchtiger Gott.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 25, '»Wenn euch dann Kinder und Kindeskinder geboren sind und ihr euch in dem Lande eingelebt habt und euch dann versündigt, indem ihr euch ein Gottesbild in irgendeiner Gestalt anfertigt und somit tut, was dem HERRN, eurem Gott, mißfällt, so daß ihr ihn erbittert,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 26, 'so rufe ich heute den Himmel und die Erde zu Zeugen gegen euch an, daß ihr dann unfehlbar gar bald aus dem Lande verschwinden werdet, in das ihr jetzt über den Jordan zieht, um es in Besitz zu nehmen. Ihr werdet dann nicht lange Zeit in ihm wohnen bleiben, sondern gänzlich daraus vertilgt werden.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 27, 'Der HERR wird euch dann unter die Völker zerstreuen, und nur eine geringe Zahl von euch wird übrigbleiben unter den Heidenvölkern, zu denen der HERR euch führen wird.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 28, 'Dort werdet ihr dann Göttern dienen, die von Menschenhänden aus Holz und Stein gemacht sind, die weder sehen noch hören, nicht essen und nicht atmen können.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 29, 'Aber von dort aus wirst du den HERRN, deinen Gott, suchen, und du wirst ihn finden, wenn du mit ganzem Herzen und ganzer Seele nach ihm verlangst.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 30, 'Wenn du in Bedrängnis bist und alle diese Leiden dich in zukünftigen Tagen treffen, so wirst du zum HERRN, deinem Gott, zurückkehren und seinen Befehlen gehorchen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 31, 'Denn der HERR, dein Gott, ist ein barmherziger Gott: er wird dich nicht verlassen und dich nicht ins Verderben geraten lassen und wird den Bund nicht vergessen, den er deinen Vätern mit einem Eide bekräftigt hat.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 32, '»Denn forsche doch in den früheren Zeiten nach, die vor dir gewesen sind, seit dem Tage, wo Gott Menschen auf der Erde geschaffen hat, und forsche von einem Ende des Himmels bis zu dessen anderem Ende nach, ob je etwas so Großes sich zugetragen hat oder etwas Derartiges gehört worden ist:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 33, 'ob je ein Volk die Stimme Gottes mitten aus dem Feuer heraus hat reden hören, wie du sie gehört hast, und dennoch am Leben geblieben ist;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 34, 'oder ob je ein Gott auch nur den Versuch gemacht hat, auf die Erde zu kommen, um sich ein Volk mitten aus einem andern Volk herauszuholen durch Prüfungen, durch Zeichen und Wunder, durch Krieg, mit starker Hand und hocherhobenem Arm und durch schreckenerregende Großtaten, wie das alles der HERR, euer Gott, in Ägypten vor euren Augen an euch getan hat.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 35, 'Du hast es zu sehen bekommen, um zu erkennen, daß der HERR der (einzige) Gott ist und daß es keinen anderen außer ihm gibt.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 36, 'Vom Himmel her hat er dich seine Stimme hören lassen, um dich zu unterweisen, und auf der Erde hat er dich sein gewaltiges Feuer sehen lassen, und aus dem Feuer heraus hast du seine Worte vernommen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 37, 'Weil er also deine Väter geliebt und ihre Nachkommen nach ihnen erwählt und in eigener Person mit seiner großen Kraft dich aus Ägypten herausgeführt hat,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 38, 'um Völker, die dir an Größe und Macht überlegen waren, vor dir zu vertreiben und um dich herzubringen, damit er dir ihr Land als Eigentum gebe, wie es am heutigen Tage der Fall ist –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 39, 'so erkenne es heute und nimm es dir zu Herzen, daß der HERR (allein) Gott ist oben im Himmel und unten auf der Erde, sonst aber keiner.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 40, 'Darum beobachte seine Satzungen und Gebote, die ich dir heute zur Pflicht mache, damit es dir und deinen Kindern nach dir gut ergeht und du lange in dem Lande wohnen bleibst, das der HERR, dein Gott, dir für immer geben will.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 41, 'Damals sonderte Mose im Ostjordanlande drei Städte aus,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 42, 'damit ein Totschläger, der einen andern unvorsätzlich getötet hätte, ohne vorher mit ihm verfeindet gewesen zu sein, in eine von diesen Städten fliehen und dadurch sein Leben retten könnte.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 43, 'Diese Städte waren: Bezer in der Steppe, im Gebiet der Hochebene, für den Stamm Ruben, ferner Ramoth in Gilead für den Stamm Gad und Golan in Basan für den Stamm Manasse.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 44, 'Und dies ist das Gesetz, das Mose den Israeliten vorlegte;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 45, 'dies sind die Zeugnisse und die Satzungen und die Verordnungen, die Mose den Israeliten bei ihrem Auszug aus Ägypten vortrug,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 46, 'und zwar jenseits des Jordans in dem Tal gegenüber von Beth-Peor im Lande des ehemaligen Amoriterkönigs Sihon, der in Hesbon gewohnt hatte und den Mose und die Israeliten bei ihrem Auszug aus Ägypten geschlagen');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 47, 'und dessen Land sie in Besitz genommen hatten ebenso wie das Land Ogs, des Königs von Basan, (das Land) der beiden Amoriterkönige, die im Ostjordanlande gewohnt hatten');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 48, 'von Aroer am Ufer des Arnonflusses an bis zum Berge Sion – das ist der Hermon –,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 49, 'nebst der ganzen Steppe auf der Ostseite des Jordans bis an das Meer der Steppe am Fuß der Abhänge des Pisga.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 5, 1, 'Da berief Mose alle Israeliten und sagte zu ihnen: »Vernimm, Israel, die Satzungen und Verordnungen, die ich euch heute laut vortrage: lernt sie und beobachtet sie genau!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 5, 2, 'Der HERR, unser Gott, hat am Horeb einen Bund mit uns geschlossen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 5, 3, 'Nicht mit unsern Vätern hat der HERR diesen Bund geschlossen, sondern mit uns hier, die wir alle heute noch am Leben sind.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 5, 4, 'Von Angesicht zu Angesicht hat der HERR auf dem Berge aus dem Feuer heraus mit euch geredet,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 5, 5, 'während ich selbst damals zwischen dem HERRN und euch stand, um euch die Worte des HERRN zu verkündigen; denn ihr fürchtetet euch vor dem Feuer und waret nicht auf den Berg gestiegen. Die Worte aber lauteten so:«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 5, 6, '»Ich bin der HERR, dein Gott, der dich aus dem Lande Ägypten, aus dem Diensthause, hinausgeführt hat.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 5, 7, 'Du sollst keine anderen Götter haben neben mir!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 5, 8, 'Du sollst dir kein Gottesbild anfertigen, irgendein Abbild von dem, was oben im Himmel oder unten auf der Erde oder im Wasser unterhalb der Erde ist!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 5, 9, 'Du sollst dich vor ihnen nicht niederwerfen und ihnen nicht dienen; denn ich, der HERR, dein Gott, bin ein eifriger Gott, der die Verschuldung der Väter heimsucht an den Kindern, ja an den Enkeln und Urenkeln derer, die mich hassen,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 5, 10, 'der aber Gnade erweist an Tausenden von Nachkommen derer, die mich lieben und meine Gebote halten.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 5, 11, 'Du sollst den Namen des HERRN, deines Gottes, nicht mißbrauchen!; denn der HERR wird den nicht ungestraft lassen, der seinen Namen mißbraucht.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 5, 12, 'Beobachte den Sabbattag, daß du ihn heilig hältst, wie der HERR, dein Gott, dir geboten hat!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 5, 13, 'Sechs Tage sollst du arbeiten und alle deine Geschäfte verrichten!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 5, 14, 'Aber der siebte Tag ist ein Feiertag zu Ehren des HERRN, deines Gottes: da darfst du keinerlei Arbeit verrichten, weder du selbst, noch dein Sohn oder deine Tochter, weder dein Knecht noch deine Magd, weder dein Ochs, noch dein Esel, noch all dein Vieh, noch der Fremdling, der sich bei dir in deinen Ortschaften aufhält, damit dein Knecht und deine Magd ausruhen können wie du selbst.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 5, 15, 'Denke daran, daß du selbst ein Knecht gewesen bist im Lande Ägypten und daß der HERR, dein Gott, dich von dort mit starker Hand und hocherhobenem Arm weggeführt hat; darum hat der HERR, dein Gott, dir geboten, den Sabbattag zu feiern.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 5, 16, 'Ehre deinen Vater und deine Mutter, wie der HERR, dein Gott, dir geboten hat, damit du lange lebst und damit es dir wohlergeht in dem Lande, das der HERR, dein Gott, dir geben wird!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 5, 17, 'Du sollst nicht töten!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 5, 18, 'Du sollst nicht ehebrechen!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 5, 19, 'Du sollst nicht stehlen!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 5, 20, 'Du sollst kein falsches Zeugnis ablegen gegen deinen Nächsten!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 5, 21, 'Du sollst nicht begehren deines Nächsten Weib und sollst dich nicht nach dem Hause deines Nächsten gelüsten lassen, nach seinem Felde, nach seinem Knecht und seiner Magd, nach seinem Ochsen und seinem Esel und nach allem, was deinem Nächsten gehört!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 5, 22, '»Diese Worte hat der HERR auf dem Berge zu eurer ganzen Versammlung mit lauter Stimme mitten aus dem Feuer und dem dunklen Gewölk heraus gesprochen und nichts weiter hinzugefügt; er hat sie dann auf zwei Steintafeln geschrieben und diese mir übergeben.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 5, 23, 'Als ihr aber die Stimme mitten aus dem Dunkel heraus vernahmt, während der Berg in Feuerglut brannte, da tratet ihr zu mir heran, alle eure Stammeshäupter und eure Ältesten,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 5, 24, 'und sagtet: ›Der HERR, unser Gott, hat uns nunmehr seine Herrlichkeit und Größe sehen lassen, und wir haben seine Stimme aus dem Feuer heraus gehört: heute haben wir erlebt, daß, wenn der HERR mit Menschen redet, diese doch am Leben bleiben.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 5, 25, 'Aber warum sollen wir uns jetzt noch in Todesgefahr begeben? Denn dieses gewaltige Feuer wird uns verzehren! Wenn wir selbst die Stimme des HERRN, unseres Gottes, noch weiter hören, so werden wir sterben.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 5, 26, 'Denn wo gäbe es in der ganzen Menschheit jemanden, der wie wir die Stimme des lebendigen Gottes aus dem Feuer heraus hätte reden hören und doch am Leben geblieben wäre?');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 5, 27, 'Tritt du hinzu und höre alles an, was der HERR, unser Gott, sagen wird; berichte du uns dann alles, was der HERR, unser Gott, dir sagen wird, so wollen wir es hören und befolgen.‹');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 5, 28, 'Als nun der HERR diese Worte vernahm, die ihr mit lauter Stimme an mich gerichtet hattet, sagte der HERR zu mir: ›Ich habe die Worte gehört, die dieses Volk mit lauter Stimme an dich gerichtet hat; sie haben recht in allem, was sie zu dir gesagt haben.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 5, 29, 'Möchte doch dieser ihr Vorsatz ihnen verbleiben, daß sie mich allezeit fürchten und alle meine Gebote halten! Dann sollte es ihnen und ihren Kindern immerdar gut ergehen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 5, 30, 'Gehe hin und sage ihnen: Kehrt zu euren Zelten zurück!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 5, 31, 'Du aber bleibe hier bei mir stehen, damit ich dir alle Verordnungen und die Satzungen und Gebote mitteile, die du sie lehren sollst, damit sie danach tun in dem Lande, das ich ihnen zum Besitz geben will.‹');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 5, 32, 'So achtet denn darauf, daß ihr so tut, wie der HERR, euer Gott, euch geboten hat: weicht weder zur Rechten noch zur Linken davon ab!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 5, 33, 'Wandelt genau auf dem Wege, den der HERR, euer Gott, euch geboten hat, damit ihr das Leben behaltet und es euch wohlgeht und ihr lange in dem Lande wohnen bleibt, das ihr in Besitz nehmen sollt.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 6, 1, '»Dies ist nun das Gesetz, die Satzungen und die Verordnungen, die ich euch nach dem Befehl des HERRN, eures Gottes, lehren soll, damit ihr nach ihnen lebt in dem Lande, zu dessen Eroberung ihr jetzt hinüberzieht,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 6, 2, 'auf daß ihr, du und deine Kinder und Kindeskinder, den HERRN, euren Gott, euer ganzes Leben lang fürchtet und alle seine Satzungen und Gebote beobachtet, die ich dir zur Pflicht mache, und auf daß deine Tage lange Dauer haben.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 6, 3, 'So höre sie denn, Israel, und achte darauf, sie zu befolgen, damit es dir wohlgeht und ihr sehr zahlreich werdet, wie der HERR, der Gott deiner Väter, es dir zugesagt hat – in einem von Milch und Honig überfließenden Lande.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 6, 4, 'Höre, Israel: Der HERR ist unser Gott, der HERR allein!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 6, 5, 'So liebe denn den HERRN, deinen Gott, mit deinem ganzen Herzen, mit deiner ganzen Seele und mit all deiner Kraft!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 6, 6, 'So mögen denn diese Worte, die ich dir heute gebiete, dir am Herzen liegen,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 6, 7, 'und du sollst sie deinen Kindern einschärfen und von ihnen reden, wenn du in deinem Hause sitzt und wenn du auf der Wanderung begriffen bist, wenn du dich niederlegst und wenn du aufstehst.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 6, 8, 'Du sollst sie dir als ein Gedenkzeichen an die Hand binden und sie als Binde zwischen deinen Augen tragen');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 6, 9, 'und sollst sie auf die Pfosten deines Hauses und an deine Tore schreiben.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 6, 10, '»Auch wenn der HERR, dein Gott, dich in das Land bringen wird, das er dir, wie er deinen Vätern Abraham, Isaak und Jakob zugeschworen hat, zu eigen geben will, große und schöne Städte, die du nicht gebaut hast,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 6, 11, 'und Häuser, angefüllt mit Gütern jeder Art, die du nicht angefüllt hast, in Fels gehauene Brunnen, die du nicht ausgehauen hast, Weinberge und Olivengärten, die du nicht angelegt hast, und du dich dann satt daran ißt:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 6, 12, 'so hüte dich wohl, den HERRN zu vergessen, der dich aus dem Lande Ägypten, aus dem Hause der Knechtschaft, ausgeführt hat!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 6, 13, 'Den HERRN, deinen Gott, sollst du fürchten und ihm dienen und bei seinem Namen schwören.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 6, 14, 'Ihr dürft keinem andern Gott von den Göttern der Völker, die rings um euch her wohnen, anhangen;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 6, 15, 'denn der HERR, dein Gott, ist ein eifriger Gott in deiner Mitte; es möchte sonst der Zorn des HERRN, deines Gottes, gegen dich entbrennen und er dich vom Erdboden vertilgen.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 6, 16, '»Ihr sollt den HERRN, euren Gott, nicht versuchen, wie ihr ihn in Massa versucht habt;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 6, 17, 'ihr sollt vielmehr die Gebote des HERRN, eures Gottes, getreulich beobachten sowie seine Zeugnisse und seine Verordnungen, die er dir zur Pflicht gemacht hat;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 6, 18, 'und du sollst das tun, was in den Augen des HERRN recht und gut ist, damit es dir wohlergeht und du in das schöne Land, das der HERR deinen Vätern zugeschworen hat, einziehst und es in Besitz nimmst,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 6, 19, 'indem du alle deine Feinde vor dir her vertreibst, wie der HERR es verheißen hat.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 6, 20, '»Wenn dann dein Sohn dich künftig fragt: ›Was hat es denn mit den Zeugnissen, den Satzungen und den Verordnungen auf sich, die der HERR, unser Gott, euch geboten hat?‹,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 6, 21, 'so sollst du deinem Sohne antworten: ›Wir waren Knechte des Pharaos in Ägypten; aber der HERR hat uns mit starker Hand aus Ägypten hinausgeführt,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 6, 22, 'und der HERR hat vor unsern Augen große und furchtbare Zeichen und Wunder in Ägypten am Pharao und seinem ganzen Hause getan;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 6, 23, 'uns aber hat er von dort weggeführt, um uns hierher zu bringen, damit er uns das Land gäbe, das er unsern Vätern zugeschworen hatte.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 6, 24, 'Daher hat der HERR uns geboten, alle diese Satzungen zu beobachten, indem wir den HERRN, unsern Gott, fürchteten, damit es uns allezeit wohlergehe und er uns am Leben erhalte, wie es noch an diesem Tage der Fall ist.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 6, 25, 'So werden wir denn als gerecht dastehen, wenn wir es uns angelegen sein lassen, dieses ganze Gesetz vor dem HERRN, unserm Gott, zu erfüllen, wie er uns geboten hat.‹«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 7, 1, '»Wenn der HERR, dein Gott, dich in das Land gebracht hat, in das du jetzt ziehst, um es in Besitz zu nehmen, und viele Völkerschaften, die Hethiter, Girgasiter, Amoriter, Kanaanäer, Pherissiter, Hewiter und Jebusiter, sieben Völkerschaften, die an Zahl und Stärke dir überlegen sind, vor dir her vertrieben hat,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 7, 2, 'und wenn der HERR, dein Gott, sie in deine Gewalt gegeben hat und du sie besiegt hast, so sollst du den Bann schonungslos an ihnen vollstrecken: du darfst kein Abkommen mit ihnen treffen und keine Gnade gegen sie üben.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 7, 3, 'Du darfst dich auch nicht mit ihnen verschwägern, weder deine Töchter an ihre Söhne verheiraten noch ihre Töchter für deine Söhne zu Frauen nehmen;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 7, 4, 'denn sie würden deine Söhne von mir abwendig machen, so daß sie anderen Göttern dienen, und der Zorn des HERRN würde gegen euch entbrennen und euch schnell vertilgen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 7, 5, 'Vielmehr sollt ihr so mit ihnen verfahren: ihre Altäre sollt ihr niederreißen, ihre Malsteine zertrümmern, ihre Götzenbäume umhauen und ihre geschnitzten Götterbilder im Feuer verbrennen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 7, 6, 'Denn du bist ein dem HERRN, deinem Gott, geheiligtes Volk: dich hat der HERR, dein Gott, aus allen Völkern, die auf dem Erdboden sind, zu seinem Eigentumsvolk erwählt.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 7, 7, 'Nicht deshalb, weil ihr zahlreicher wärt als alle anderen Völker, hat der HERR sich euch zugewandt und euch erwählt – ihr seid ja das kleinste unter allen Völkern –;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 7, 8, 'nein, weil der HERR Liebe zu euch hegte und weil er den Eid halten wollte, den er euren Vätern zugeschworen hatte, deshalb hat der HERR euch mit starker Hand weggeführt und euch aus dem Hause der Knechtschaft, aus der Gewalt des Pharaos, des Königs von Ägypten, erlöst.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 7, 9, 'So erkenne denn, daß der HERR, dein Gott, der (wahre) Gott ist, der treue Gott, der den Bund und die Gnade bis ins tausendste Glied denen bewahrt, die ihn lieben und seine Gebote halten,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 7, 10, 'aber denen, die ihn hassen, mit Vernichtung ihrer eigenen Person vergilt und seinen Widersachern keinen Aufschub gewährt, sondern ihnen an ihrer eigenen Person vergilt.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 7, 11, 'So halte denn das Gesetz, sowohl die Satzungen als auch die Verordnungen, deren Beobachtung ich dir heute gebiete.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 7, 12, '»Wenn du nun diesen Verordnungen gehorchst und sie in deinem ganzen Tun beobachtest, so wird der HERR, dein Gott, dir dafür den Bund und die Gnade bewahren, die er deinen Vätern zugeschworen hat,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 7, 13, 'und wird dich lieben und segnen und dich zahlreich werden lassen, dir Kindersegen bescheren und deine Feldfrüchte, dein Getreide, deinen Wein und dein Öl, die Jungen deiner Rinder und den Nachwuchs deines Kleinviehs in dem Lande segnen, das du, wie er deinen Vätern zugeschworen hat, besitzen sollst.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 7, 14, 'Gesegnet wirst du vor allen Völkern sein: kein Mann und kein Weib unter dir soll unfruchtbar sein und ebenso auch kein Stück von deinem Vieh.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 7, 15, 'Der HERR wird auch alle Krankheiten von dir fernhalten und keine von den bösen Seuchen Ägyptens, die du kennst, über dich kommen lassen, sondern alle deine Feinde damit heimsuchen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 7, 16, 'Du sollst aber alle Völker vernichten, die der HERR, dein Gott, in deine Gewalt gibt: dein Auge soll sie nicht mitleidig ansehen, und du sollst ihren Göttern nicht dienen, denn das würde ein Fallstrick für dich sein.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 7, 17, 'Wenn du aber bei dir denken solltest: ›Diese Völkerschaften sind mir zu stark, wie sollte ich sie vertreiben können?‹ –:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 7, 18, 'fürchte dich nicht vor ihnen! Denke vielmehr an das zurück, was der HERR, dein Gott, am Pharao und an allen Ägyptern getan hat,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 7, 19, 'an die großen Machterweise, die du mit eigenen Augen gesehen hast, an die Zeichen und Wunder, an die starke Hand und den hocherhobenen Arm, mit dem der HERR, dein Gott, dich herausgeführt hat: ebenso wird der HERR, dein Gott, mit allen Völkern verfahren, vor denen du dich jetzt fürchtest.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 7, 20, 'Auch die Hornissen wird der HERR, dein Gott, gegen sie loslassen, bis die Übriggebliebenen und die sich vor dir Versteckenden umgekommen sind.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 7, 21, 'Habe also keine Angst vor ihnen! Denn der HERR, dein Gott, ist in deiner Mitte, ein großer und furchtbarer Gott.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 7, 22, 'Doch der HERR, dein Gott, wird diese Völker nur nach und nach vor dir vertreiben: du darfst sie nicht schnell vernichten, sonst würden die wilden Tiere zu deinem Schaden überhandnehmen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 7, 23, 'Jedoch wird der HERR, dein Gott, sie dir preisgeben und sie in große Bestürzung versetzen, bis sie ausgerottet sind;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 7, 24, 'und er wird ihre Könige in deine Gewalt geben, und du wirst ihre Namen unter dem Himmel austilgen: niemand soll vor dir standhalten, bis du sie ausgerottet hast.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 7, 25, 'Ihre geschnitzten Götzenbilder sollt ihr im Feuer verbrennen: du sollst nach dem Silber und Gold, das sich an ihnen befindet, kein Verlangen tragen und es nicht für dich hinnehmen, damit du dadurch nicht ins Verderben gerätst, denn es ist ein Greuel für den HERRN, deinen Gott,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 7, 26, 'und du sollst einen solchen Greuel nicht in dein Haus kommen lassen, um nicht gleich ihm dem Bann zu verfallen; du sollst es vielmehr mit Ekel verabscheuen und es durchaus für etwas Greuelhaftes halten, denn es ist dem Banne geweiht.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 8, 1, '»Das ganze Gesetz, das ich dir heute gebiete, sollt ihr gewissenhaft befolgen, damit ihr am Leben bleibt und zahlreich werdet und hineinkommt, um das Land in Besitz zu nehmen, das der HERR euren Vätern zugeschworen hat.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 8, 2, 'Und du sollst des ganzen Weges gedenken, den der HERR, dein Gott, dich nun vierzig Jahre lang in der Wüste hat wandern lassen, um dich demütig zu machen und dich zu erproben, damit er erkenne, wie es um dein Herz steht, ob du nämlich seine Gebote halten wirst oder nicht.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 8, 3, 'So demütigte er dich denn und ließ dich Hunger leiden; dann aber speiste er dich wieder mit dem Manna, das weder du noch deine Väter gekannt hatten, um dich zu der Erkenntnis zu führen, daß der Mensch nicht vom Brot allein lebt, sondern daß der Mensch von allem lebt, was vom Mund des HERRN ausgeht.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 8, 4, 'Die Kleider, die du anhattest, haben sich nicht abgenutzt, und die Füße sind dir während dieser vierzig Jahre nicht geschwollen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 8, 5, 'So erkenne denn in deinem Herzen, daß der HERR, dein Gott, ebenso dein Erzieher ist, wie ein Vater seinen Sohn erzieht,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 8, 6, 'und befolge die Gebote des HERRN, deines Gottes, indem du auf seinen Wegen wandelst und ihn fürchtest.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 8, 7, '»Denn der HERR, dein Gott, will dich in ein schönes Land bringen, in ein Land mit Wasserbächen, Quellen und Grundwassern, die in der Niederung und im Gebirge entspringen,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 8, 8, 'ein Land mit Weizen und Gerste, mit Weinstöcken, Feigenbäumen und Granaten, ein Land mit Ölbäumen und Honig,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 8, 9, 'ein Land, in welchem du dein Brot nicht kärglich zu essen brauchst, sondern an nichts Mangel leiden wirst, ein Land, das in seinem Gestein Eisen birgt und aus dessen Bergen du Kupfer heraushauen wirst.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 8, 10, 'Wenn du dann gegessen hast und satt geworden bist, so preise den HERRN, deinen Gott, für das schöne Land, das er dir gegeben hat.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 8, 11, '»Hüte dich ja, alsdann den HERRN, deinen Gott, zu vergessen, so daß du seine Verordnungen, sowohl seine Gebote als auch seine Satzungen, deren Befolgung ich dir heute zur Pflicht mache, nicht beobachtest.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 8, 12, 'Laß nicht, während du dich satt ißt und dir schöne Häuser zum Bewohnen baust');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 8, 13, 'und deine Rinder und dein Kleinvieh sich mehren und Silber und Gold sich dir mehren und dein gesamter Besitz zunimmt,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 8, 14, 'dein Herz sich überheben und vergiß nicht den HERRN, deinen Gott, der dich aus dem Lande Ägypten, aus dem Hause der Knechtschaft, herausgeführt,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 8, 15, 'der dich durch die große und furchtbare Wüste mit ihren feurigen Schlangen und Skorpionen geleitet hat, durch wasserlose, dürre Gegenden, und der dir Wasser aus dem kieselharten Felsen hat sprudeln lassen;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 8, 16, 'der dich mit Manna, das deine Väter nicht gekannt hatten, in der Wüste gespeist hat, um dich demütig zu machen und auf die Probe zu stellen, damit er dir zuletzt Gutes erweisen könnte.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 8, 17, 'Denke dann nicht etwa bei dir selbst: ›Meine Kraft und meine starken Arme haben mir diesen Wohlstand verschafft!‹');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 8, 18, 'Denke vielmehr daran, daß der HERR, dein Gott, es ist, der dir die Kraft verliehen hat, solchen Wohlstand zu erwerben, weil er seinen Bund aufrechthalten will, den er deinen Vätern zugeschworen hat [wie es an diesem Tage offenbar ist].');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 8, 19, 'Wenn du aber trotzdem den HERRN, deinen Gott, vergißt und anderen Göttern nachgehst und ihnen dienst und sie anbetest, so bezeuge ich euch heute feierlich, daß ihr unfehlbar zugrunde gehen werdet!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 8, 20, 'Wie die Völkerschaften, die der HERR vor euch vernichtet, so werdet auch ihr alsdann zugrunde gehen zur Strafe dafür, daß ihr nicht auf die Stimme des HERRN, eures Gottes, gehört habt.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 9, 1, '»Höre, Israel! Du bist jetzt im Begriff, über den Jordan zu ziehen, um dir drüben Völker zu unterwerfen, die größer und stärker sind als du: große und bis an den Himmel befestigte Städte,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 9, 2, 'ein großes und hochgewachsenes Volk, die Enakiter, die du selbst schon kennst und von denen du selbst hast sagen hören: ›Wer könnte es mit den Enakitern aufnehmen?‹');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 9, 3, 'So sollst du denn jetzt erkennen, daß der HERR, dein Gott, selbst es ist, der an deiner Spitze als ein verzehrendes Feuer hinüberzieht: er wird sie vernichten, und er wird sie vor dir her niederwerfen, so daß du sie schnell aus ihrem Besitz vertreiben und sie vernichten kannst, wie der HERR es dir verheißen hat.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 9, 4, 'Denke nun nicht bei dir selbst, wenn der HERR, dein Gott, sie vor dir her vertreibt: ›Um meines Verdienstes willen hat der HERR mich hierher geführt, damit ich dieses Land in Besitz nehme‹ [während der HERR diese Völkerschaften doch wegen ihrer Verworfenheit vor dir her ausrottet].');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 9, 5, 'Nicht um deines Verdienstes willen und nicht wegen deines aufrichtigen Herzens gelangst du in den Besitz ihres Landes, sondern der HERR, dein Gott, rottet diese Völkerschaften vor dir her aus wegen ihrer Verworfenheit und auch um die Verheißung zu erfüllen, die der HERR deinen Vätern Abraham, Isaak und Jakob zugeschworen hat.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 9, 6, 'Bedenke also wohl, daß der HERR, dein Gott, dir dieses schöne Land nicht um deines Verdienstes willen zum Eigentum gibt; denn du bist ein halsstarriges Volk.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 9, 7, '»Denke daran und vergiß es nicht, daß du den HERRN, deinen Gott, in der Wüste erzürnt hast! Von dem Tage an, da ihr aus dem Land Ägypten ausgezogen seid, bis zu eurer Ankunft an diesem Ort habt ihr euch widerspenstig gegen den HERRN gezeigt.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 9, 8, 'Besonders am Horeb habt ihr ihn erzürnt, und der HERR wurde gegen euch so aufgebracht, daß er euch vertilgen wollte.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 9, 9, 'Als ich auf den Berg gestiegen war, um die Steintafeln, die Tafeln des Bundes, den der HERR mit euch geschlossen hatte, in Empfang zu nehmen, da blieb ich vierzig Tage und vierzig Nächte auf dem Berge, ohne Brot zu essen und Wasser zu trinken.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 9, 10, 'Da übergab der HERR mir die beiden Steintafeln, die vom Finger Gottes beschrieben waren und auf denen alle die Worte standen, die der HERR am Tage der Versammlung an dem Berge aus dem Feuer heraus zu euch geredet hatte.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 9, 11, 'Als nun der HERR mir damals nach Verlauf von vierzig Tagen und vierzig Nächten die beiden Steintafeln, die Tafeln des Bundes, übergeben hatte,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 9, 12, 'sagte der HERR zu mir: ›Auf! Steige schnell von hier hinab, denn dein Volk, das du aus Ägypten hergeführt hast, handelt sündhaft: sie sind schnell von dem Wege abgewichen, den ich ihnen geboten habe; sie haben sich ein gegossenes Bild gemacht.‹');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 9, 13, 'Dann sagte der HERR weiter zu mir: ›Ich habe dieses Volk beobachtet und erkenne wohl: es ist ein halsstarriges Volk.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 9, 14, 'Laß mich sie nun vertilgen und ihren Namen unter dem Himmel auslöschen! Dich will ich dafür zu einem Volk machen, das stärker und zahlreicher ist als sie.‹');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 9, 15, 'Hierauf kehrte ich um und stieg vom Berge hinunter, während der Berg im Feuer brannte und die beiden Bundestafeln in meinen beiden Händen waren.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 9, 16, 'Da sah ich denn wirklich, daß ihr gegen den HERRN, euren Gott, gesündigt und euch ein gegossenes Stierbild gemacht hattet; ihr wart schnell von dem Wege abgewichen, den der HERR euch geboten hatte.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 9, 17, 'Da faßte ich die beiden Tafeln, schleuderte sie weg aus meinen beiden Händen und zertrümmerte sie vor euren Augen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 9, 18, 'Darauf aber warf ich mich vor dem HERRN nieder wie das erste Mal, vierzig Tage und vierzig Nächte lang, ohne Brot zu essen und Wasser zu trinken, wegen all der Sünden, die ihr begangen hattet, indem ihr etwas tatet, was dem HERRN mißfiel und ihn erzürnen mußte;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 9, 19, 'denn mir war bange vor dem Zorn und Grimm, den der HERR gegen euch hegte, so daß er euch vertilgen wollte. Und der HERR erhörte mich auch diesmal.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 9, 20, 'Auch gegen Aaron war der HERR heftig erzürnt, so daß er ihn vertilgen wollte; darum legte ich damals auch für Aaron Fürbitte ein.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 9, 21, 'Das Machwerk eurer Sünde aber, das Stierbild, das ihr angefertigt hattet, nahm ich und verbrannte es im Feuer, ich zerschlug es in Stücke und zermalmte es, bis es zu feinem Staub geworden war; und diesen Staub warf ich in den Bach, der vom Berge herabfloß.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 9, 22, '»Auch bei Thabera und Massa und bei den Lustgräbern habt ihr den HERRN immerfort erzürnt;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 9, 23, 'und als der HERR euch aus Kades-Barnea aufbrechen hieß mit dem Befehl: ›Zieht hinauf und besetzt das Land, das ich euch bestimmt habe!‹, da habt ihr euch dem Befehl des HERRN, eures Gottes, widersetzt und kein Vertrauen zu ihm gehabt und seiner Weisung nicht gehorcht:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 9, 24, 'widerspenstig seid ihr gegen den HERRN gewesen, seit ich euch kenne!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 9, 25, '»Als ich nun jene vierzig Tage und vierzig Nächte vor dem HERRN am Boden hingestreckt gelegen hatte – denn der HERR hatte es ausgesprochen, daß er euch vertilgen wolle –,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 9, 26, 'da betete ich zum HERRN folgendermaßen: ›O HERR, unser Gott! Vernichte nicht dieses Volk und dein Eigentum, das du durch deine große Macht befreit, das du mit starker Hand aus Ägypten herausgeführt hast!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 9, 27, 'Gedenke an deine Knechte Abraham, Isaak und Jakob! Kehre dich nicht an die Halsstarrigkeit dieses Volkes und an seine Bosheit und Sünde,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 9, 28, 'damit man in dem Lande, aus dem du uns weggeführt hast, nicht sagen kann: Weil der HERR nicht imstande war, sie in das Land zu bringen, das er ihnen zugesagt hatte, und weil er sie haßte, hat er sie hinausgeführt, um sie in der Wüste sterben zu lassen!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 9, 29, 'Sie sind ja doch dein Volk und dein Eigentum, das du mit deiner großen Kraft und deinem hocherhobenen Arm hinausgeführt hast.‹');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 10, 1, 'Damals sagte der HERR zu mir: ›Haue dir zwei Steintafeln zurecht, wie die ersten waren, und steige zu mir auf den Berg herauf; fertige dir auch eine hölzerne Lade an.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 10, 2, 'Ich will dann auf die Tafeln die Worte schreiben, die auf den ersten Tafeln gestanden haben, welche du zertrümmert hast; dann sollst du sie in die Lade legen.‹');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 10, 3, 'So fertigte ich denn eine Lade von Akazienholz an, hieb zwei Steintafeln zurecht, wie die ersten waren, und stieg mit den beiden Tafeln in der Hand auf den Berg hinauf.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 10, 4, 'Da schrieb er auf die Tafeln in derselben Schrift, wie das erste Mal, die zehn Gebote, die der HERR am Tage der Versammlung an dem Berge aus dem Feuer heraus euch zugerufen hatte, und übergab mir (die Tafeln).');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 10, 5, 'Als ich dann umgekehrt und vom Berge wieder hinabgestiegen war, legte ich die Tafeln in die Lade, die ich angefertigt hatte; dort sind sie liegen geblieben, wie der HERR mir geboten hatte.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 10, 6, 'Die Israeliten aber brachen von Beeroth-Bene-Jaakan nach Mosera auf; dort starb Aaron und wurde dort begraben, und sein Sohn Eleasar trat als Priester an seine Stelle.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 10, 7, 'Von da zogen sie nach Gudgoda weiter und von Gudgoda nach Jotba, einem reichbewässerten Landstrich.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 10, 8, 'Damals sonderte der HERR den Stamm Levi dazu aus, die Lade mit dem Bundesgesetz des HERRN zu tragen und als seine Diener vor ihm zu stehen und in seinem Namen zu segnen, wie es bis auf den heutigen Tag geschieht.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 10, 9, 'Darum haben die Leviten kein Erbteil und kein Besitztum erhalten wie ihre Brüder: der HERR ist ihr Erbteil, wie der HERR, dein Gott, ihnen zugesagt hat.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 10, 10, 'Als ich aber auf dem Berge ebenso lange wie das erste Mal, nämlich vierzig Tage und vierzig Nächte, geblieben war, erhörte der HERR mich auch diesmal; der HERR wollte dich nicht verderben');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 10, 11, 'und gebot mir: ›Mache dich auf den Weg und brich an der Spitze des Volkes auf, damit sie ans Ziel kommen und das Land in Besitz nehmen, das ich ihnen geben will, wie ich ihren Vätern eidlich versprochen habe!‹«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 10, 12, '»Und nun, Israel, was fordert der HERR, dein Gott, von dir? Doch nur, daß du den HERRN, deinen Gott, fürchtest und immerdar auf seinen Wegen wandelst und daß du ihn liebst und dem HERRN, deinem Gott, mit ganzem Herzen und mit ganzer Seele dienst,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 10, 13, 'indem du die Gebote und die Satzungen des HERRN, die ich dir heute gebiete, zu deinem eigenen Wohlergehen beobachtest.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 10, 14, 'Bedenke wohl: dem HERRN, deinem Gott, gehört der Himmel, und zwar der innerste Himmel, die Erde und alles, was auf ihr ist;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 10, 15, 'und doch hat der HERR sich nur deinen Vätern in Liebe zugewandt und hat euch, die Nachkommen jener, aus allen Völkern auserwählt, wie es an diesem Tage offenbar ist.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 10, 16, 'So beschneidet denn die Vorhaut eures Herzens und zeigt euch nicht länger halsstarrig!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 10, 17, 'Denn der HERR, euer Gott, ist der Gott der Götter und der Herr der Herren, der große, starke und furchtbare Gott, der die Person nicht ansieht und sich nicht bestechen läßt,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 10, 18, 'der den Waisen und Witwen Recht schafft und den Fremdling liebhat, so daß er ihm Brot und Kleidung gibt.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 10, 19, 'Darum sollt ihr auch den Fremdling lieben; denn ihr seid selbst Fremdlinge im Lande Ägypten gewesen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 10, 20, 'Den HERRN, deinen Gott, sollst du fürchten, ihm sollst du dienen, ihm anhangen und nur bei seinem Namen schwören!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 10, 21, 'Er ist dein Ruhm und er dein Gott, der an dir jene großen und wunderbaren Taten vollführt hat, die du mit eigenen Augen gesehen hast.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 10, 22, 'Siebzig Seelen an Zahl sind einst deine Väter nach Ägypten hinabgezogen, und jetzt hat der HERR, dein Gott, dich so zahlreich gemacht wie die Sterne am Himmel.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 11, 1, '»So liebe denn den HERRN, deinen Gott, und beobachte allezeit, was er beobachtet wissen will, seine Satzungen, seine Verordnungen und seine Gebote,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 11, 2, 'und erkennet heute – denn nicht zu euren Kindern rede ich, welche die Zucht des HERRN, eures Gottes, nicht miterlebt und seine große Macht nicht gesehen haben, seine starke Hand und seinen hocherhobenen Arm,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 11, 3, 'seine Wunderzeichen und seine Taten, die er in Ägypten am Pharao, dem König von Ägypten, und an seinem ganzen Lande vollführt hat,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 11, 4, 'und was er der Heeresmacht der Ägypter, ihren Rossen und Kriegswagen, hat widerfahren lassen, über die er die Wasser des Schilfmeeres hinströmen ließ, als sie euch verfolgten, und die der HERR so bis auf den heutigen Tag vernichtet hat;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 11, 5, 'und was er sodann an euch in der Wüste bis zu eurer Ankunft an diesem Ort vollbracht hat,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 11, 6, 'und was er an Dathan und Abiram, den Söhnen des Rubeniten Eliab, getan hat, wie da die Erde ihren Mund auftat und sie samt ihren Familien und Zelten und dem ganzen Bestand, der zu ihnen gehörte, inmitten aller Israeliten verschlang –:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 11, 7, 'nein, zu euch rede ich, die ihr mit eigenen Augen alle die großen Taten gesehen habt, die der HERR vollbracht hat.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 11, 8, 'So beobachtet denn das ganze Gesetz, das ich euch heute gebiete, damit ihr stark seid und dazu kommt, das Land in Besitz zu nehmen, in das ihr hinüberzieht, um es zu erobern,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 11, 9, 'und damit ihr lange in dem Lande wohnen bleibt, dessen Verleihung der HERR euren Vätern und ihren Nachkommen zugeschworen hat, ein Land, das von Milch und Honig überfließt.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 11, 10, '»Denn das Land, in das du einziehst, um es in Besitz zu nehmen, ist nicht so wie das Land Ägypten, aus dem ihr ausgezogen seid, wo du die Saat, die du gesät hattest, wie einen Gemüsegarten (durch Schöpfräder) mit den Füßen bewässern mußtest;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 11, 11, 'nein, das Land, in das ihr hinüberzieht, um es in Besitz zu nehmen, ist ein Land mit Bergen und Tälern, das vom Regen des Himmels getränkt wird,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 11, 12, 'ein Land, für das der HERR, dein Gott, Sorge trägt und auf das die Augen des HERRN, deines Gottes, beständig gerichtet sind vom Anfang des Jahres bis zum Ende des Jahres.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 11, 13, 'Wenn ihr nun den Geboten, die ich euch heute zur Pflicht mache, getreulich nachkommt, indem ihr den HERRN, euren Gott, liebt und ihm von ganzem Herzen und mit ganzer Seele dient,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 11, 14, '›so wird er eurem Lande zu rechter Zeit Regen geben, Frühregen und Spätregen, damit du dein Getreide, deinen Wein und dein Öl einbringen kannst;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 11, 15, 'auch wird er auf deinen Feldern Futter für dein Vieh wachsen lassen, so daß du zu essen hast und satt wirst‹.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 11, 16, 'Hütet euch (aber) wohl, daß euer Herz sich nicht betören läßt und ihr nicht abfallt und anderen Göttern dient und sie anbetet!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 11, 17, 'Sonst wird der Zorn des HERRN gegen euch entbrennen, und er wird den Himmel verschließen, so daß kein Regen mehr fällt und der Erdboden keinen Ertrag mehr gibt und ihr schnell aus dem schönen Lande verschwindet, das der HERR euch geben will.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 11, 18, '»Laßt also diese meine Worte Eingang in euer Herz finden und euch ganz durchdringen, bindet sie euch als ein Gedenkzeichen an eure Hand und tragt sie als Binde auf eurer Stirn,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 11, 19, 'lehrt sie auch eure Kinder, indem ihr davon redet, wenn ihr zu Hause sitzt oder auf der Wanderung begriffen seid, wenn ihr euch niederlegt und wenn ihr aufsteht;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 11, 20, 'und schreibt sie auf die Türpfosten eurer Häuser und an eure Tore,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 11, 21, 'damit ihr und eure Kinder in dem Lande, dessen Verleihung der HERR euren Vätern zugeschworen hat, so lange wohnen bleibt, wie der Himmel über der Erde steht.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 11, 22, 'Denn wenn ihr dieses ganze Gesetz, dessen Beobachtung ich euch heute gebiete, gewissenhaft beobachtet, indem ihr den HERRN, euren Gott, liebt, allezeit auf seinen Wegen wandelt und ihm anhangt,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 11, 23, 'so wird der HERR alle diese Völkerschaften vor euch her ausrotten, und ihr werdet Völkerschaften aus ihrem Besitz verdrängen, die größer und stärker sind als ihr.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 11, 24, 'Das ganze Gebiet, das eure Fußsohle betreten wird, soll euer Eigentum werden: von der Wüste bis an den Libanon, von dem Strome, dem Euphratstrom, bis an das Meer im Westen soll euer Gebiet reichen;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 11, 25, 'niemand soll euch gegenüber standhalten können; Furcht und Schrecken vor euch wird der HERR, euer Gott, über das ganze Land verbreiten, das ihr betreten werdet, wie er es euch zugesagt hat.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 11, 26, 'Seht, ich lege euch heute Segen und Fluch zur Wahl vor:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 11, 27, 'den Segen, wenn ihr den Geboten des HERRN, eures Gottes, gehorcht, die ich euch heute gebiete;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 11, 28, 'aber den Fluch, wenn ihr den Geboten des HERRN, eures Gottes, nicht gehorcht und von dem Wege, den ich euch heute gebiete, abweicht, um anderen Göttern anzuhangen, von denen ihr vorher nichts gewußt habt.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 11, 29, '»Wenn nun der HERR, dein Gott, dich in das Land gebracht hat, in das du jetzt ziehst, um es in Besitz zu nehmen, so sollst du den Segen auf dem Berge Garizim und den Fluch auf dem Berge Ebal erteilen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 11, 30, 'Diese liegen bekanntlich jenseits des Jordans, westlich von der nach Sonnenuntergang führenden Straße, im Lande der Kanaanäer, die in der Jordanebene wohnen, Gilgal gegenüber, neben dem Terebinthenhain von More.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 11, 31, 'Denn ihr seid im Begriff, den Jordan zu überschreiten, um in den Besitz des Landes zu gelangen, das der HERR, euer Gott, euch geben will. Wenn ihr es dann besetzt habt und in ihm wohnt,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 11, 32, 'so seid auf die Erfüllung aller Satzungen und Verordnungen bedacht, die ich euch heute vorlege.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 12, 1, '»Dies sind die Satzungen und die Verordnungen, die ihr in dem Lande, das der HERR, der Gott eurer Väter, euch zum Eigentum bestimmt hat, allezeit beobachten sollt, solange ihr auf dem Erdboden lebt«:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 12, 2, '»Ihr sollt alle Stätten von Grund aus zerstören, an denen die Völkerschaften, die ihr aus ihrem Besitz verdrängen werdet, ihre Götter verehrt haben, auf den hohen Bergen wie auf den Hügeln und unter jedem dichtbelaubten Baum.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 12, 3, 'Ihr sollt also ihre Altäre niederreißen und ihre Malsteine zertrümmern, ihre Götzenbäume im Feuer verbrennen, ihre geschnitzten Götterbilder zerschlagen und ihren Namen von den betreffenden Stätten verschwinden lassen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 12, 4, 'Mit dem HERRN, eurem Gott, dürft ihr es nicht so halten (wie jene Völker mit ihren Göttern);');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 12, 5, 'vielmehr nur die eine Stätte, die der HERR, euer Gott, aus all euren Stammesgebieten erwählen wird, um seinen Namen dorthin zu versetzen und dort Wohnung zu nehmen, die sollt ihr aufsuchen und euch dorthin begeben;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 12, 6, 'und dorthin sollt ihr eure Brandopfer und Schlachtopfer, eure Zehnten und die Hebeopfer, die ihr darbringt, eure Gelübdeopfer und freiwilligen Gaben sowie die Erstgeburten eurer Rinder und eures Kleinviehs bringen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 12, 7, 'Dort sollt ihr auch eure Opfermahlzeiten vor dem HERRN, eurem Gott, halten, ihr und eure Familien, und euch der Freude über alles das hingeben, was ihr mit eurer Hände Arbeit beschafft habt und womit der HERR, dein Gott, dich gesegnet hat.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 12, 8, 'Ihr dürft es künftig nicht mehr so machen, wie wir es heutigentags hier ein jeder ganz nach seinem Belieben zu tun pflegen;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 12, 9, 'denn bis jetzt seid ihr noch nicht zum ruhigen Besitz des Erbteils gekommen, das der HERR, dein Gott, dir geben wird.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 12, 10, 'Wenn ihr aber den Jordan überschritten habt und in dem Lande wohnt, das der HERR, euer Gott, euch als Erbbesitz verleihen will, und wenn er euch Ruhe vor allen euren Feinden ringsum verschafft hat, so daß ihr in Sicherheit wohnt,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 12, 11, 'dann sollt ihr an die Stätte, die der HERR, euer Gott, zur Wohnung für seinen Namen erwählen wird, alles das bringen, was ich euch gebiete: eure Brand- und Schlachtopfer, eure Zehnten und die Hebeopfer, die ihr darbringt, und alle eure auserlesenen Gelübdeopfer, die ihr dem HERRN geloben werdet.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 12, 12, 'Dort sollt ihr auch vor dem HERRN, eurem Gott, fröhlich sein, ihr und eure Söhne und Töchter, eure Knechte und Mägde, auch die Leviten, die in euren Ortschaften wohnen; denn sie haben keinen eigenen Landbesitz und kein Erbteil gleich euch.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 12, 13, 'Hüte dich wohl, deine Brandopfer an jedem beliebigen Ort, den du dir ersehen wirst, darzubringen!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 12, 14, 'Vielmehr sollst du nur an der Stätte, die der HERR in einem deiner Stammesgebiete erwählen wird, deine Brandopfer darbringen und dort alles das verrichten, was ich dir gebiete.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 12, 15, 'Doch darfst du in all deinen Wohnorten ganz nach Herzenslust schlachten und Fleisch essen, je nachdem der HERR, dein Gott, dich gesegnet hat: der Reine wie der Unreine darf es essen, wie das Fleisch einer Gazelle oder eines Hirsches;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 12, 16, 'nur das Blut dürft ihr nicht genießen: auf die Erde müßt ihr es wie Wasser schütten.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 12, 17, 'Du darfst nicht in deinen Wohnorten den Zehnten deines Getreides und Weins und Öls verzehren, auch nicht die Erstgeburten deiner Rinder und deines Kleinviehs und keins von deinen Gelübdeopfern, die du geloben wirst, auch nicht deine freiwilligen Gaben und die Hebeopfer, die du darbringen wirst;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 12, 18, 'sondern vor dem HERRN, deinem Gott, sollst du sie an der Stätte verzehren, die der HERR, dein Gott, erwählen wird, du und dein Sohn und deine Tochter, dein Knecht und deine Magd, auch die Leviten, die in deinen Wohnorten leben, und sollst dich vor dem HERRN, deinem Gott, an allem erfreuen, was du mit deiner Hände Arbeit beschafft hast.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 12, 19, 'Hüte dich, die Leviten unbeachtet zu lassen, solange du in deinem Lande lebst!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 12, 20, '»Wenn der HERR, dein Gott, dein Gebiet erweitert, wie er dir zugesagt hat, und du dann denkst: ›Ich möchte wohl Fleisch essen!‹, weil du Verlangen nach Fleisch trägst, so magst du ganz nach Herzenslust Fleisch essen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 12, 21, 'Wenn (in diesem Fall) die Stätte, die der HERR, dein Gott, erwählen wird, um seinen Namen dorthin zu versetzen, weit von dir entfernt ist, so schlachte von deinen Rindern und deinem Kleinvieh, die der HERR dir gegeben hat, wie ich dir geboten habe, und iß davon in deinen Wohnorten ganz nach Herzenslust.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 12, 22, 'Jedoch sollst du es so essen, wie man Fleisch von der Gazelle und vom Hirsch genießt: der Reine wie der Unreine darf es ohne Unterschied essen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 12, 23, 'Nur halte daran fest, kein Blut zu genießen; denn das Blut ist die Seele, und du darfst die Seele nicht zugleich mit dem Fleisch essen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 12, 24, 'Du darfst es nicht genießen: schütte es vielmehr wie Wasser auf die Erde.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 12, 25, 'Du darfst es nicht genießen, damit es dir und deinen Kindern nach dir gut ergeht, wenn du tust, was dem HERRN wohlgefällig ist.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 12, 26, 'Jedoch die heiligen Gaben, die dir obliegen, und deine Gelübdeopfer sollst du nehmen und dich mit ihnen an die Stätte begeben, die der HERR sich erwählen wird,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 12, 27, 'und du sollst deine Brandopfer, das Fleisch und das Blut, auf dem Altar des HERRN, deines Gottes, darbringen, und zwar soll das Blut deiner Schlachtopfer an den Altar des HERRN, deines Gottes, geschüttet werden, das Fleisch aber darf von dir gegessen werden.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 12, 28, 'Beachte und befolge alle diese Gebote, die ich dir zur Pflicht mache, damit es dir und deinen Kindern nach dir allezeit gut ergeht, wenn du tust, was in den Augen des HERRN, deines Gottes, gut und recht ist.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 12, 29, '»Wenn der HERR, dein Gott, die Völkerschaften, zu deren Vertreibung du ausziehst, vor dir her ausgerottet hat und du nach ihrer Vertreibung in ihrem Lande wohnst,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 12, 30, 'so hüte dich wohl, dich durch ihr Beispiel zur Nachahmung verführen zu lassen, nachdem sie vor dir vertilgt worden sind, und dich nach ihren Göttern zu erkundigen, indem du fragst: ›Wie haben diese Völkerschaften ihre Götter verehrt?‹ und dann sagst: ›Ich will es auch so machen!‹');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 12, 31, 'So darfst du gegen den HERRN, deinen Gott, nicht verfahren; denn alles Mögliche, was für den HERRN ein Greuel ist, den er verabscheut, haben sie bei ihrem Götterdienst verübt; sogar ihre Söhne und Töchter haben sie ja ihren Göttern zu Ehren im Feuer verbrannt!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 13, 1, '»Alle Gebote, die ich euch zur Pflicht mache, sollt ihr gewissenhaft beobachten, ohne etwas hinzuzufügen oder etwas davon wegzulassen.« –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 13, 2, '»Wenn in deiner Mitte ein Prophet oder ein Träumer auftritt und dir ein Zeichen oder Wunder angibt,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 13, 3, 'das dann auch wirklich seiner Ankündigung entsprechend eintrifft, und hierauf die Aufforderung an dich richtet: ›Laßt uns andere Götter verehren – die dir bisher unbekannt gewesen sind – und ihnen dienen!‹,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 13, 4, 'so sollst du den Worten eines solchen Propheten oder eines solchen Traumsehers kein Gehör schenken; denn der HERR, euer Gott, will euch damit nur auf die Probe stellen, um sich zu überzeugen, ob ihr wirklich den HERRN, euren Gott, von ganzem Herzen und mit ganzer Seele liebt.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 13, 5, 'Dem HERRN, eurem Gott, sollt ihr nachfolgen und ihn fürchten, seine Gebote sollt ihr beobachten und auf seine Weisungen hören, ihm dienen und ihm anhangen!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 13, 6, 'Jener Prophet aber oder jener Traumseher soll den Tod erleiden! Denn er hat Abfall gepredigt vom HERRN, eurem Gott, der euch aus dem Lande Ägypten herausgeführt und dich aus dem Hause der Knechtschaft erlöst hat, und ist darauf ausgegangen, dich von dem Wege abzubringen, auf dem du nach dem Gebot des HERRN, deines Gottes, wandeln sollst: schaffe das Böse aus deiner Mitte hinweg!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 13, 7, 'Wenn dein Bruder, sogar dein Vollbruder, oder dein Sohn oder deine Tochter oder das Weib an deinem Busen oder dein Freund, der dir so lieb ist wie dein eigenes Leben, dich insgeheim verleiten will, indem er dich auffordert: ›Laß uns hingehen und anderen Göttern dienen!‹ – solchen Göttern, die dir und deinen Vätern bisher unbekannt gewesen sind');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 13, 8, 'und die den Völkern rings um euch her angehören, mögen diese in deiner Nähe oder fern von dir wohnen, von dem einen Ende der Erde bis zum andern –:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 13, 9, 'so sollst du ihm nicht zu Willen sein und nicht auf ihn hören, sollst auch keinen Blick des Mitleids für ihn haben und keine Schonung gegen ihn üben oder seine Schuld verheimlichen,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 13, 10, 'sondern sollst ihn unbedingt ums Leben bringen: deine Hand soll die erste sein, die sich gegen ihn erhebt, um ihm den Tod zu geben, und danach die Hand des ganzen Volkes;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 13, 11, 'und zwar sollst du ihn zu Tode steinigen; denn er ist darauf ausgegangen, dich vom HERRN, deinem Gott, abwendig zu machen, der dich aus dem Lande Ägypten, aus dem Hause der Knechtschaft, herausgeführt hat;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 13, 12, 'und ganz Israel soll Kunde davon erhalten und sich fürchten, damit keiner wieder etwas so Böses in deiner Mitte verübt.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 13, 13, '»Wenn du von einer deiner Ortschaften, die der HERR, dein Gott, dir zu Wohnsitzen gibt, sagen hörst,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 13, 14, 'es seien dort nichtswürdige Leute aus deiner Mitte aufgetreten, die ihre Mitbürger mit der Aufforderung verführt hätten: ›Laßt uns hingehen und anderen Göttern dienen!‹ – solchen Göttern, die euch vorher unbekannt gewesen sind –,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 13, 15, 'so sollst du eine genaue Untersuchung und sorgfältige Nachforschung anstellen, und wenn die Sache sich dann in der Tat so verhält, wie dir berichtet ist, und ein solcher Greuel in deiner Mitte wirklich verübt worden ist,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 13, 16, 'so sollst du die Bewohner der betreffenden Ortschaft mit der Schärfe des Schwertes schlagen, indem du an ihr und an allem, was in ihr ist, auch an ihrem Vieh, den Bann mit der Schärfe des Schwertes vollstreckst.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 13, 17, 'Dann sollst du alles in ihr Erbeutete auf dem dortigen Marktplatz zusammenhäufen und die Ortschaft samt der gesamten Beute als ein Ganzopfer für den HERRN, deinen Gott, verbrennen, und sie soll für immer ein Schutthaufen bleiben: sie darf nie wieder aufgebaut werden,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 13, 18, 'und von dem Banngut darf nichts an deiner Hand hängen bleiben, damit der HERR von seiner Zornglut wieder abläßt und sich dir gnädig erweist und infolge seines Erbarmens dich zahlreich werden läßt, wie er deinen Vätern zugeschworen hat,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 13, 19, 'wenn du nämlich auf die Stimme des HERRN, deines Gottes, hörst, indem du alle seine Gebote hältst, die ich dir heute zu befolgen gebiete, und du das tust, was vor dem HERRN, deinem Gott, das Richtige ist.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 14, 1, '»Ihr seid Söhne für den HERRN, euren Gott; darum dürft ihr euch wegen eines Toten keine Einschnitte ins Fleisch machen und euch über der Stirn nicht kahlscheren;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 14, 2, 'denn du bist ein dem HERRN, deinem Gott, geheiligtes Volk, und dich hat der HERR, dein Gott, aus allen Völkern, die es auf dem ganzen Erdboden gibt, zu seinem Eigentumsvolk erwählt. –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 14, 3, 'Du sollst nichts Greuelhaftes essen!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 14, 4, 'Dies sind die Vierfüßler, die ihr essen dürft: Rind, Schaf und Ziege,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 14, 5, 'Hirsch, Gazelle, Damwild, Steinbock, Antilope, wilder Ochs und Bergziege');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 14, 6, 'und überhaupt alle Vierfüßler, die gespaltene Hufe haben, und zwar ganz durchgespaltene, also zwei Hufe, und die zugleich Wiederkäuer unter den Vierfüßlern sind: diese dürft ihr essen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 14, 7, 'Dagegen folgende dürft ihr von den Wiederkäuern und von denen, welche ganz durchgespaltene Hufe haben, nicht essen: das Kamel, den Hasen und den Klippdachs; denn sie sind zwar Wiederkäuer, haben aber keine gespaltenen Hufe: als unrein sollen sie euch gelten;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 14, 8, 'ferner das Schwein, denn es hat zwar gespaltene Klauen, ist aber kein Wiederkäuer: als unrein soll es euch gelten; vom Fleisch dieser Tiere dürft ihr nichts genießen und ihre toten Leiber nicht anrühren. –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 14, 9, 'Dies ist es, was ihr von allen im Wasser lebenden Tieren essen dürft: alles, was Flossen und Schuppen hat: diese dürft ihr essen;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 14, 10, 'aber alles, was keine Flossen und Schuppen hat, dürft ihr nicht genießen: als unrein soll es euch gelten. –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 14, 11, 'Alle reinen Vögel dürft ihr essen;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 14, 12, 'folgende aber sind es, von denen ihr nichts essen dürft: der Adler, der Lämmergeier, der Bartgeier,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 14, 13, 'die Weihe, der Habicht, die verschiedenen Falkenarten,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 14, 14, 'alle Arten von Raben,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 14, 15, 'der Strauß, die Schwalbe, die Möwe, alle Habichtarten,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 14, 16, 'das Käuzchen, der Uhu, die Eule,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 14, 17, 'der Pelikan, der Aasgeier, der Sturzpelikan,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 14, 18, 'der Storch, die verschiedenen Arten der Regenpfeifer, der Wiedehopf und die Fledermaus.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 14, 19, 'Auch alle geflügelten Insekten sollen euch als unrein gelten und dürfen nicht gegessen werden.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 14, 20, 'Alles reine Geflügel dürft ihr essen. –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 14, 21, 'Von gefallenen Tieren dürft ihr nichts genießen; dem Fremdling, der in deinen Ortschaften lebt, magst du sie zum Essen geben oder magst sie an einen Nichtisraeliten verkaufen; denn du bist ein dem HERRN, deinem Gott, geheiligtes Volk. – Ein Böckchen darfst du nicht in der Milch seiner Mutter kochen.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 14, 22, '»Den ganzen Ertrag deiner Aussaat, alles, was dir auf dem Felde wächst, sollst du Jahr für Jahr gewissenhaft verzehnten');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 14, 23, 'und sollst den Zehnten deines Getreides, deines Weins und deines Öls sowie die Erstgeburten deiner Rinder und deines Kleinviehs vor dem HERRN, deinem Gott, an der Stätte, die er erwählen wird, um seinen Namen dort wohnen zu lassen, verzehren, damit du den HERRN, deinen Gott, allezeit fürchten lernst.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 14, 24, 'Wenn dir aber der Weg zu weit ist, so daß du, wenn der HERR, dein Gott, dich gesegnet hat, den Zehnten nicht hinbringen kannst, weil die Stätte, die der HERR, dein Gott, erwählen wird, um seinen Namen dorthin zu versetzen, zu weit von dir entfernt liegt:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 14, 25, 'so mache den Zehnten zu Geld, nimm dann das Geld wohlbewahrt mit dir und begib dich an den Ort, den der HERR, dein Gott, erwählen wird.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 14, 26, 'Dort gib das Geld aus für alles, wonach dein Herz Verlangen tragen mag, für Rinder und Kleinvieh, für Wein und starke Getränke, kurz für alles, wonach dich gelüsten mag; halte dann dort vor dem HERRN, deinem Gott, ein Mahl und sei mit deinen Angehörigen fröhlich.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 14, 27, 'Dabei vergiß aber auch die Leviten nicht, die in deinen Wohnorten leben; denn sie haben keinen eigenen Landbesitz und kein Erbteil gleich dir.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 14, 28, 'Nach Verlauf von je drei Jahren sollst du den gesamten Zehnten deines Ertrags von jenem Jahre für sich besonders nehmen und ihn in deinen Wohnorten niederlegen;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 14, 29, 'dann sollen die Leviten, die ja keinen eigenen Landbesitz und kein Erbteil gleich dir haben, sowie die Fremdlinge, die Witwen und die Waisen, die in deinen Wohnorten leben, herbeikommen und sich satt essen, damit der HERR, dein Gott, dich segne bei aller Arbeit deiner Hände, bei allem, was du unternimmst.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 15, 1, '»Alle sieben Jahre sollst du einen Erlaß eintreten lassen;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 15, 2, 'und mit dem Erlaß soll es folgendermaßen gehalten werden: Jeder Gläubiger soll das Handdarlehen, das er seinem Nächsten gewährt hat, erlassen; er soll seinen Nächsten und besonders seinen Volksgenossen nicht drängen; denn man hat einen Erlaß zu Ehren des HERRN ausgerufen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 15, 3, 'Einen Nichtisraeliten magst du drängen; was du aber bei einem von deinen Volksgenossen ausstehen hast, das sollst du aus deinem Besitz fahren lassen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 15, 4, 'Es sollte zwar eigentlich keine Armen bei dir geben; denn der HERR wird dich in dem Lande, das er dir als Erbteil zum Besitz geben wird, reichlich segnen,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 15, 5, 'wenn du nur den Weisungen des HERRN, deines Gottes, willig gehorchst, indem du dieses ganze Gesetz genau beobachtest, das ich dir heute gebiete.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 15, 6, 'Denn der HERR, dein Gott, hat dir, wie er dir zugesagt hat, Segen verliehen, so daß du vielen Völkerschaften wirst leihen können, während du selbst nichts zu entleihen brauchst, und daß du über viele Völkerschaften herrschen wirst, während sie über dich nicht herrschen sollen.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 15, 7, '»Wenn sich bei dir ein Armer, irgendeiner von deinen Volksgenossen, in einer deiner Ortschaften in deinem Lande befindet, das der HERR, dein Gott, dir geben wird, so sollst du nicht hartherzig sein und deine Hand gegenüber deinem armen Volksgenossen nicht verschließen,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 15, 8, 'sondern sollst deine Hand für ihn weit auftun und ihm bereitwillig leihen nach Maßgabe des Bedürfnisses, soviel er nötig hat.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 15, 9, 'Hüte dich wohl, in deinem Herzen den nichtswürdigen Gedanken aufkommen zu lassen: ›Das siebte Jahr, das Erlaßjahr, steht nahe bevor!‹, und sieh deinen armen Volksgenossen nicht mit unfreundlichem Blick an, so daß du ihm nichts gibst und eine Sünde auf dir lastet, wenn er den HERRN gegen dich anruft!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 15, 10, 'Nein, du sollst ihm bereitwillig geben, und dein Herz soll nicht in verdrießlicher Stimmung sein, wenn du ihm gibst; denn um solcher Handlungsweise willen wird der HERR, dein Gott, dich in allem segnen, was du tust und unternimmst.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 15, 11, 'Weil es an Armen inmitten des Landes niemals fehlen wird, darum gebe ich dir das Gebot: ›Du sollst deine Hand für deinen dürftigen und armen Volksgenossen in deinem Lande weit auftun!‹«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 15, 12, '»Wenn einer deiner Volksgenossen, ein Hebräer oder eine Hebräerin, sich dir verkauft, so soll er dir sechs Jahre lang dienen, aber im siebten Jahre sollst du ihn als einen Freien von dir entlassen;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 15, 13, 'und wenn du ihn dann freiläßt, sollst du ihn nicht mit leeren Händen ziehen lassen,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 15, 14, 'sondern ihn gehörig ausstatten (mit Gaben) von deinem Kleinvieh, von deiner Tenne und von deiner Kelter: von dem, womit der HERR, dein Gott, dich gesegnet hat, sollst du ihm geben');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 15, 15, 'und sollst bedenken, daß du selbst einst ein Knecht im Lande Ägypten gewesen bist und daß der HERR, dein Gott, dich (aus der Knechtschaft) erlöst hat; deshalb gebe ich dir heute dieses Gebot.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 15, 16, 'Wenn er aber zu dir sagen sollte: ›Ich möchte nicht von dir weggehen!‹ – weil er dich und die Deinen liebgewonnen hat, da er sich bei dir wohl fühlt –,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 15, 17, 'so nimm eine Pfrieme und durchbohre ihm damit das Ohr in die Tür hinein: dann soll er für immer als Knecht in deinem Dienst bleiben; und auch mit deiner Magd sollst du es so machen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 15, 18, 'Du darfst keine Härte darin sehen, daß du ihn als einen Freien von dir fortlassen mußt; denn er hat dir sechs Jahre lang das Doppelte des Lohnes eines Taglöhners erarbeitet, und der HERR, dein Gott, wird dich dafür segnen in allem, was du unternimmst.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 15, 19, '»Jede männliche Erstgeburt, die unter deinem Rindvieh und deinem Kleinvieh zur Welt kommt, sollst du dem HERRN, deinem Gott, weihen: du darfst keines von deinen erstgeborenen Rindern zur Arbeit verwenden und die Erstgeborenen deines Kleinviehs nicht scheren:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 15, 20, 'vor dem HERRN, deinem Gott, sollst du und deine Familie es Jahr für Jahr an der Stätte verzehren, die der HERR erwählen wird.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 15, 21, 'Wenn sich jedoch ein Gebrechen an ihm findet, so daß es lahm oder blind ist oder sonst einen häßlichen Fehler an sich hat, so sollst du es dem HERRN, deinem Gott, nicht schlachten.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 15, 22, 'In deinen Wohnorten magst du es verzehren, der Unreine und der Reine ohne Unterschied, wie das Fleisch der Gazelle und des Hirsches.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 15, 23, 'Nur sein Blut darfst du nicht genießen: auf die Erde mußt du es wie Wasser schütten.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 16, 1, '»Beobachte den Monat Abib und feiere das Passah zu Ehren des HERRN, deines Gottes; denn im Monat Abib hat der HERR, dein Gott, dich bei Nacht aus Ägypten hinausgeführt.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 16, 2, 'Du sollst dann für den HERRN, deinen Gott, als Passahopfer Kleinvieh und Rinder an der Stätte schlachten, die der HERR erwählen wird, um seinen Namen dort wohnen zu lassen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 16, 3, 'Du darfst nichts Gesäuertes dazu essen: sieben Tage lang sollst du ungesäuertes Brot als ›Elendskost‹ dazu genießen – denn in ängstlicher Eile bist du aus dem Lande Ägypten weggezogen –, damit du an den Tag deines Auszugs aus dem Lande Ägypten zurückdenkst, solange du lebst.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 16, 4, 'Sieben Tage lang darf bei dir kein Sauerteig in deinem ganzen Gebiet zu finden sein, und von dem Fleisch, das du am Abend des ersten Tages schlachtest, darf nichts über Nacht bis zum folgenden Morgen übrigbleiben.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 16, 5, 'Du darfst das Passah nicht in irgendeinem deiner Wohnorte schlachten, die der HERR, dein Gott, dir gibt,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 16, 6, 'sondern an der Stätte, die der HERR, dein Gott, erwählen wird, um seinen Namen dort wohnen zu lassen: dort sollst du das Passah abends bei Sonnenuntergang zu der Zeit deines Auszugs aus Ägypten schlachten');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 16, 7, 'und sollst es kochen und essen an der Stätte, die der HERR, dein Gott, erwählen wird; am folgenden Morgen aber sollst du umkehren und zu deinen Zelten zurückkehren.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 16, 8, 'Nachdem du dann sechs Tage lang ungesäuerte Brote gegessen hast, findet am siebten Tage eine Festversammlung zu Ehren des HERRN, deines Gottes, statt; da darfst du keine Arbeit verrichten.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 16, 9, 'Sieben Wochen sollst du dir abzählen: von da an, wo man die Sichel zuerst an die Saat legt, sollst du anfangen, sieben Wochen zu zählen,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 16, 10, 'und sollst dann das Wochenfest zu Ehren des HERRN, deines Gottes, nach Maßgabe der freiwilligen Gaben feiern, die du von deinem Besitz darbringen wirst, je nachdem der HERR, dein Gott, dich segnet;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 16, 11, 'und du sollst mit deinen Söhnen und Töchtern, deinen Knechten und Mägden und den Leviten, die in deinen Wohnorten leben, und den Fremdlingen, den Waisen und Witwen, die bei dir wohnen, vor dem HERRN, deinem Gott, fröhlich sein an der Stätte, die der HERR, dein Gott, erwählen wird, um seinen Namen dort wohnen zu lassen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 16, 12, 'Dabei sollst du daran gedenken, daß du (einst) ein Knecht in Ägypten gewesen bist, und sollst diese Satzungen gewissenhaft beobachten.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 16, 13, 'Das Laubhüttenfest sollst du sieben Tage lang, wenn du die Obstlese hältst, von dem Ertrag deiner Tenne und Kelter feiern');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 16, 14, 'und sollst an diesem deinem Feste mit deinen Söhnen und Töchtern, deinen Knechten und Mägden und den Leviten, sowie mit den Fremdlingen, den Waisen und Witwen, die in deinen Wohnorten leben, fröhlich sein:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 16, 15, 'sieben Tage lang sollst du das Fest zu Ehren des HERRN, deines Gottes, an der Stätte feiern, die der HERR erwählen wird; denn der HERR wird dich bei deinem ganzen Ernteertrag und bei der ganzen Arbeit deiner Hände segnen; darum sollst du dich durchaus der Freude hingeben!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 16, 16, '»Dreimal im Jahr sollen alle Personen männlichen Geschlechts bei dir vor dem HERRN, deinem Gott, an der Stätte erscheinen, die er erwählen wird, nämlich am Fest der ungesäuerten Brote, am Wochenfest und am Laubhüttenfest. Man soll aber vor dem HERRN nicht mit leeren Händen erscheinen,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 16, 17, 'sondern jeder mit dem, was er zu geben vermag nach Maßgabe des Segens, den der HERR, dein Gott, dir beschert hat.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 16, 18, '»Richter und Obmänner sollst du dir in allen deinen Ortschaften, die der HERR, dein Gott, dir in jedem deiner Stämme gibt, einsetzen, damit sie dem Volke mit Gerechtigkeit Recht sprechen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 16, 19, 'Du darfst das Recht nicht beugen, darfst die Person nicht ansehen und Geschenke nicht annehmen; denn Geschenke machen die Augen der Weisesten blind und bringen die Sache derer, die im Recht sind, zu Fall.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 16, 20, 'Der Gerechtigkeit allein sollst du die Ehre geben, damit du am Leben bleibst und das Land im Besitz behältst, das der HERR, dein Gott, dir geben wird.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 16, 21, '»Du sollst dir neben dem Altar, den du dir für den HERRN, deinen Gott, errichten wirst, keinen Baumstamm irgendwelcher Art als Götzenbaum pflanzen');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 16, 22, 'und dir keinen Malstein aufstellen, weil der HERR, dein Gott, ihn haßt.-');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 17, 1, 'Du sollst dem HERRN, deinem Gott, kein Rind und kein Stück Kleinvieh opfern, das einen Fehler, irgend etwas Häßliches, an sich hat; denn das ist ein Greuel für den HERRN, deinen Gott.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 17, 2, '»Wenn in deiner Mitte, in einem deiner Wohnorte, die der HERR, dein Gott, dir geben wird, ein Mann oder eine Frau sich findet, die das tun, was dem HERRN, deinem Gott, mißfällt, indem sie seinen Bund übertreten,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 17, 3, 'so daß sie hingehen und anderen Göttern dienen und sich vor ihnen und besonders vor der Sonne oder vor dem Mond oder vor dem ganzen Sternenheere des Himmels niederwerfen, was ich verboten habe,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 17, 4, 'und es dir angezeigt wird und du es erfährst, so sollst du eine genaue Untersuchung anstellen. Wenn sich dann der Sachbericht als zutreffend herausstellt und solcher Greuel in Israel wirklich verübt worden ist,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 17, 5, 'so sollst du den betreffenden Mann oder jene Frau, die etwas so Schlimmes begangen haben, zu deinen Toren hinausführen, den Mann oder die Frau, und sie zu Tode steinigen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 17, 6, 'Auf die Aussage von zwei oder drei Zeugen hin soll ein solcher, der sterben muß, den Tod erleiden; auf die Aussage eines einzigen Zeugen hin darf er nicht getötet werden.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 17, 7, 'Die Hand des Zeugen soll die erste sein, die sich zu seiner Tötung erhebt, danach die Hand des ganzen übrigen Volkes: so sollst du das Böse aus deiner Mitte beseitigen!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 17, 8, '»Wenn die Entscheidung einer Rechtssache, bei der es sich um Blutvergießen, um Eigentumsfragen, um tödliche Mißhandlung, überhaupt um irgendwelche Streitsachen in deinen Wohnorten handelt, für dich zu schwierig ist, so sollst du dich aufmachen und dich an den Ort begeben, den der HERR, dein Gott, erwählen wird.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 17, 9, 'Wende dich dann dort an die levitischen Priester und an den Richter, der zu jener Zeit im Amt sein wird, und frage bei ihnen an: sie werden dir dann den Rechtsspruch kundtun.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 17, 10, 'Du sollst dich alsdann an den Spruch halten, den sie dir von jenem Orte aus, den der HERR erwählen wird, kundtun werden, und sollst genau nach ihrer Anweisung verfahren:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 17, 11, 'nach Maßgabe der Weisung, die sie dir geben, und nach der Rechtsentscheidung, die sie dir mitteilen werden, sollst du handeln, ohne von dem Wortlaut, den sie dir verkündigen werden, nach rechts oder links abzuweichen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 17, 12, 'Sollte aber jemand sich so vermessen benehmen, daß er auf den Priester, der im Amt ist, um den Dienst des HERRN, deines Gottes, daselbst zu verrichten, oder auf den Richter nicht hören will: ein solcher Mensch soll sterben! So sollst du das Böse aus Israel beseitigen;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 17, 13, 'das ganze Volk aber soll es erfahren, damit es sich fürchte und fernerhin nicht mehr vermessen handle.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 17, 14, '»Wenn du in das Land gekommen bist, das der HERR, dein Gott, dir geben wird, und es in Besitz genommen hast und darin wohnst und dann denkst: ›Ich will einen König über mich setzen, wie alle Völkerschaften rings um mich her‹,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 17, 15, 'so magst du immerhin einen solchen König über dich setzen, den der HERR, dein Gott, erwählen wird: aus der Mitte deiner Volksgenossen sollst du einen König über dich setzen; einen nichtisraelitischen Mann, der nicht dein Bruder ist, darfst du nicht über dich setzen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 17, 16, 'Nur darf er sich nicht viele Rosse anschaffen und darf das Volk nicht nach Ägypten zurückführen, um sich viele Rosse anzuschaffen; denn der HERR hat zu euch gesagt: ›Ihr dürft auf diesem Wege nie wieder zurückkehren!‹');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 17, 17, 'Auch soll er sich nicht viele Frauen nehmen, damit sein Herz sich nicht (vom HERRN) abwendet; auch Silber und Gold soll er sich nicht im Übermaß sammeln.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 17, 18, 'Und wenn er den Königsthron bestiegen hat, soll er sich eine Abschrift dieses Gesetzes aus dem Buche, das sich unter der Aufsicht der levitischen Priester befindet, in ein Buch schreiben.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 17, 19, 'Dieses soll er immer bei sich haben und soll täglich darin lesen, solange er lebt, um den HERRN, seinen Gott, fürchten zu lernen und alle Vorschriften dieses Gesetzes und diese Verordnungen gewissenhaft zu beobachten,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 17, 20, 'damit er sich in seinem Herzen nicht über seine Volksgenossen erhebt und damit er von dem Gebot weder nach rechts noch nach links abweicht, auf daß er samt seinen Söhnen lange Tage in seiner Königsherrschaft inmitten Israels verbleibt.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 18, 1, '»Die levitischen Priester, der ganze Stamm Levi, sollen keinen eigenen Landbesitz und kein Erbteil wie die übrigen Israeliten haben: von den Feueropfern des HERRN und den ihm als Gebühr zustehenden Abgaben sollen sie ihren Unterhalt haben.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 18, 2, 'Aber eigenen Erbbesitz soll dieser Stamm inmitten seiner Volksgenossen nicht haben: der HERR ist sein Erbbesitz, wie er ihm zugesagt hat.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 18, 3, 'Folgendes ist es aber, was der Priester vom Volk, nämlich von denen zu beanspruchen hat, die ein Schlachtopfer darbringen, sei es ein Rind oder ein Stück Kleinvieh: man soll davon dem Priester den Bug und die beiden Kinnbacken und den Magen geben.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 18, 4, 'Die Erstlinge von deinem Getreide, deinem Wein und deinem Öl und die Erstlinge von der Schur deines Kleinviehs sollst du ihm geben;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 18, 5, 'denn ihn hat der HERR, dein Gott, aus allen deinen Stämmen erwählt, damit er und seine Söhne allezeit zur Verfügung stehen, um den priesterlichen Dienst im Namen des HERRN zu verrichten. –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 18, 6, 'Und wenn ein Levit aus irgendeiner deiner Ortschaften, aus ganz Israel, wo er sich als Fremdling aufhält, an die Stätte kommt, die der HERR erwählen wird – es steht aber ganz in seinem Belieben, ob er kommen will –,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 18, 7, 'so darf er im Namen des HERRN, seines Gottes, den Dienst verrichten wie alle seine Brüder, die Leviten, die dort im Dienst des HERRN stehen;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 18, 8, 'den gleichen Anteil (wie diese) sollen sie (an den Einkünften) zu ihrem Unterhalt haben, abgesehen von dem Erlös aus seinem väterlichen Vermögen.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 18, 9, '»Wenn du in das Land kommst, das der HERR, dein Gott, dir geben wird, so sollst du dich nicht daran gewöhnen, die Greuel der dortigen Völkerschaften nachzuahmen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 18, 10, 'Es soll sich niemand in deiner Mitte finden, der seinen Sohn oder seine Tochter als Opfer verbrennen läßt, niemand, der Wahrsagerei, Zeichendeuterei oder Beschwörungskünste und Zauberei treibt,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 18, 11, 'niemand, der Geister bannt oder Totengeister beschwört, keiner, der einen Wahrsagegeist befragt oder sich an die Toten wendet;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 18, 12, 'denn ein jeder, der sich mit solchen Dingen befaßt, ist für den HERRN ein Greuel, und um dieser Greuel willen vertreibt der HERR, dein Gott, diese Völker vor dir her.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 18, 13, 'Du sollst dem HERRN, deinem Gott, gegenüber unsträflich dastehen!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 18, 14, 'Denn diese Völkerschaften, die du verdrängen wirst, hören auf Zeichendeuter und Wahrsager; dir aber erlaubt der HERR, dein Gott, etwas Derartiges nicht.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 18, 15, 'Einen Propheten gleich mir wird der HERR, dein Gott, dir (jeweils) aus deiner Mitte, aus deinen Volksgenossen, erstehen lassen: auf den sollt ihr hören!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 18, 16, 'ganz so, wie du den HERRN, deinen Gott, am Horeb am Tage der Versammlung gebeten hast, als du sagtest: ›Ich möchte die Stimme des HERRN, meines Gottes, nicht länger hören und dieses gewaltige Feuer nicht mehr sehen, damit ich nicht sterbe!‹');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 18, 17, 'Damals sagte der HERR zu mir: ›Sie haben mit ihrer Bitte recht!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 18, 18, 'Einen Propheten gleich dir will ich ihnen aus der Mitte ihrer Volksgenossen erstehen lassen und will ihm meine Worte in den Mund legen, und er soll ihnen alles verkünden, was ich ihm gebieten werde.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 18, 19, 'Wer alsdann meinen Worten, die er in meinem Namen verkünden wird, nicht gehorcht, den will ich selbst dafür zur Rechenschaft ziehen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 18, 20, 'Sollte sich aber ein Prophet vermessen, in meinem Namen etwas zu verkünden, dessen Verkündigung ich ihm nicht geboten habe, oder sollte er im Namen anderer Götter reden: ein solcher Prophet soll sterben!‹');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 18, 21, 'Solltest du aber bei dir denken: ›Woran sollen wir das Wort erkennen, das der HERR nicht geredet hat?‹,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 18, 22, 'so wisse: Wenn das, was ein Prophet im Namen des HERRN verkündet, nicht eintrifft und nicht in Erfüllung geht, so ist das ein Wort, das der HERR nicht geredet hat; in Vermessenheit hat der Prophet es ausgesprochen: dir braucht vor ihm nicht bange zu sein!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 19, 1, '»Wenn der HERR, dein Gott, die Völkerschaften ausrottet, deren Land der HERR, dein Gott, dir geben will, und du nach ihrer Vertreibung in ihren Städten und Häusern wohnst,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 19, 2, 'so sollst du dir in deinem Lande, das der HERR, dein Gott, dir zum Besitz gibt, drei Städte aussondern.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 19, 3, 'Du sollst dir die Wege dahin in guten Stand setzen und das Gebiet deines Landes, das der HERR, dein Gott, dir zu eigen geben wird, in drei Teile zerlegen; und das soll dazu dienen, daß jeder Totschläger sich dorthin flüchten kann.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 19, 4, 'Es soll aber für den Totschläger, der sich dorthin flüchten darf, um am Leben zu bleiben, folgende Bestimmung gelten: Wer einen andern unvorsätzlich erschlägt, ohne ihm von früher her feind gewesen zu sein –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 19, 5, 'wenn z.B. jemand mit einem andern in den Wald geht, um Holz zu fällen, und seine Hand holt mit der Axt aus, um einen Baum umzuhauen, und das Eisen fliegt vom Stiel ab und trifft den andern so, daß er stirbt –: ein solcher soll in eine dieser Städte fliehen, um sein Leben zu retten,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 19, 6, 'damit nicht der Bluträcher, wenn er in leidenschaftliche Erregung geraten ist, dem Totschläger nacheilt und ihn wegen der Länge des Weges einholt und totschlägt, wiewohl er des Todes nicht schuldig ist, weil er (dem andern) ja von früher her nicht feind gewesen war.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 19, 7, 'Darum gebiete ich dir so: Du sollst dir drei Städte aussondern.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 19, 8, 'Wenn aber der HERR, dein Gott, dein Gebiet erweitert, wie er deinen Vätern zugeschworen hat, und dir nach seiner deinen Vätern gegebenen Verheißung das ganze Land zu eigen gegeben hat');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 19, 9, '- sofern du nämlich auf die Beobachtung aller dieser Gebote, die ich dir heute zur Pflicht mache, bedacht bist, indem du den HERRN, deinen Gott, liebst und allezeit auf seinen Wegen wandelst –, so sollst du dir zu diesen drei Städten noch drei andere hinzufügen,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 19, 10, 'damit in deinem Lande, das der HERR, dein Gott, dir zu eigen geben wird, kein unschuldiges Blut vergossen wird und dadurch Blutschuld auf dich kommt. –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 19, 11, 'Wenn dagegen jemand einem andern feind ist und ihm auflauert, ihn überfällt und niederschlägt, so daß er stirbt, und er dann in eine dieser Städte flieht,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 19, 12, 'so sollen die Ältesten der Stadt, zu der er gehört, hinsenden und ihn von dort holen lassen und ihn dem Bluträcher ausliefern, damit er den Tod erleidet.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 19, 13, 'Du darfst keinen Blick des Mitleids für ihn haben, sondern sollst unschuldig vergossenes Blut aus Israel hinwegschaffen: dann wird es dir gut ergehen.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 19, 14, '»Du sollst nicht die Grenze deines Nachbars, welche die Vorfahren gezogen haben, in deinem Erbbesitz verrücken, den du in dem Lande erhalten wirst, das der HERR, dein Gott, dir zum Eigentum geben will. –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 19, 15, 'Es darf nicht ein einzelner Zeuge gegen jemand auftreten, wenn es sich um irgendein Verbrechen oder irgendeine Verschuldung, um irgendein Vergehen handelt, das jemand begehen kann; erst aufgrund der Aussage von zwei oder von drei Zeugen soll eine Sache endgültig entschieden werden. –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 19, 16, 'Wenn ein gewissenloser Zeuge gegen jemand auftritt, um ihn einer Übertretung des Gesetzes zu beschuldigen,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 19, 17, 'so sollen die beiden Männer, die den Rechtsstreit miteinander haben, vor den HERRN, vor die derzeitigen Priester und die Richter treten.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 19, 18, 'Dann sollen die Richter die Sache gründlich untersuchen, und wenn es sich herausstellt, daß der Zeuge ein lügnerischer Zeuge ist, daß er die Unwahrheit gegen seinen Volksgenossen ausgesagt hat,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 19, 19, 'so sollt ihr dieselbe Strafe über ihn verhängen, die er über seinen Volksgenossen zu bringen gedachte: so sollst du das Böse aus deiner Mitte beseitigen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 19, 20, 'Die Übrigen aber sollen es erfahren, damit sie in Furcht geraten und hinfort eine derartige Schlechtigkeit in deiner Mitte nicht wieder verüben.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 19, 21, 'Und du sollst keinen Blick des Mitleids (für den Betreffenden) haben: Leben um Leben, Auge um Auge, Zahn um Zahn, Hand um Hand, Fuß um Fuß!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 20, 1, '»Wenn du zum Krieg gegen deine Feinde ausziehst und Rosse und Kriegswagen, ein dir an Zahl überlegenes Heer erblickst, so fürchte dich nicht vor ihnen! Denn der HERR, dein Gott, der dich aus dem Lande Ägypten hergeführt hat, ist mit dir.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 20, 2, 'Und wenn ihr zum Kriege ausrückt, so soll der Priester vortreten und zum Volk so sprechen:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 20, 3, '›Höre, Israel! Ihr zieht heute in den Kampf gegen eure Feinde: euer Herz werde nicht verzagt! Fürchtet euch nicht und seid ohne Angst und erschreckt nicht vor ihnen!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 20, 4, 'Denn der HERR, euer Gott, ist es, der mit euch zieht, um für euch mit euren Feinden zu kämpfen und euch den Sieg zu verleihen!‹');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 20, 5, 'Hierauf sollen die Obmänner zu dem Kriegsvolk folgendes sagen: ›Ist jemand unter euch, der ein neues Haus gebaut und es noch nicht eingeweiht hat? Der trete ab und kehre zu seinem Hause heim, sonst könnte er im Kriege umkommen und ein anderer das Haus einweihen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 20, 6, 'Ist ferner jemand unter euch, der einen Weinberg angelegt und ihn noch nicht in Nutznießung genommen hat? Der trete ab und kehre zu seinem Hause heim, sonst könnte er im Kriege umkommen und ein anderer ihn in Nutznießung nehmen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 20, 7, 'Ist ferner jemand da, der sich mit einem Weibe verlobt, sie aber noch nicht geheiratet hat? Der trete ab und kehre zu seinem Hause heim, sonst könnte er im Kriege umkommen und ein anderer die Braut heimführen.‹');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 20, 8, 'Dann sollen die Obmänner weiter zu dem Kriegsvolk sagen: ›Ist jemand unter euch, der Angst hat und verzagten Herzens ist? Der trete ab und kehre zu seinem Hause heim, damit er seine Volksgenossen nicht ebenso mutlos macht, wie er selbst ist.‹');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 20, 9, 'Wenn dann die Obmänner mit ihrer Ansprache an das Kriegsvolk fertig sind, soll man Anführer an die Spitze des Kriegsvolkes stellen.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 20, 10, '»Wenn du gegen eine Stadt heranziehst, um sie zu belagern, so sollst du sie zu einem friedlichen Abkommen auffordern.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 20, 11, 'Antwortet sie dir dann in friedfertiger Weise und öffnet sie dir freiwillig die Tore, so soll die ganze Bevölkerung, die sich darin befindet, dir fronpflichtig und dienstbar werden.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 20, 12, 'Will sie aber auf ein friedliches Abkommen mit dir nicht eingehen, sondern Krieg mit dir führen, so sollst du sie belagern;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 20, 13, 'und wenn der HERR, dein Gott, sie in deine Gewalt gibt, so sollst du alle männlichen Personen in ihr mit der Schärfe des Schwerts niederhauen;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 20, 14, 'jedoch die Weiber und Kinder, das Vieh und alles, was sonst in der Stadt ist, ihre gesamte Beute, sollst du für dich als geraubtes Gut hinnehmen und über das bei deinen Feinden Erbeutete, das der HERR, dein Gott, dir gegeben hat, frei verfügen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 20, 15, 'So sollst du es mit allen Städten halten, die in sehr weiter Entfernung von dir liegen und die nicht zu den Städten der hiesigen Völkerschaften gehören.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 20, 16, 'Dagegen von den Städten der hiesigen Völker, die der HERR, dein Gott, dir zu eigen gibt, darfst du nichts, was Odem hat, am Leben lassen,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 20, 17, 'sondern mußt den Bann unerbittlich an ihnen vollstrecken, nämlich an den Hethitern und Amoritern, den Kanaanäern und Pherissitern, den Hewitern und Jebusitern, wie der HERR, dein Gott, dir geboten hat,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 20, 18, 'damit sie euch nicht zur Nachahmung all ihrer Greuel verleiten, die sie im Dienst ihrer Götter verübt haben, und ihr euch nicht gegen den HERRN, euren Gott, versündigt.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 20, 19, 'Wenn du eine Stadt lange Zeit belagern mußt, um sie mit Waffengewalt zu erobern, so sollst du die zu ihr gehörenden Bäume nicht verderben, indem du die Axt an sie legst; sondern genieße ihre Früchte, sie selbst aber sollst du nicht umhauen; denn sind etwa die Bäume des Feldes Menschen, daß sie durch dich in Belagerungszustand versetzt werden müßten?');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 20, 20, 'Nur solche Bäume, von denen du weißt, daß sie keine eßbaren Früchte tragen, die darfst du vernichten und umhauen und magst von ihnen gegen die Stadt, die mit dir im Kriege liegt, Belagerungswerke aufführen, bis sie gefallen ist.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 21, 1, '»Wenn man in dem Lande, das der HERR, dein Gott, dir zum Eigentum gibt, einen Erschlagenen auf dem Felde liegend findet, von dem nicht bekannt ist, wer ihn erschlagen hat,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 21, 2, 'so sollen deine Ältesten und deine Richter hinausgehen und die Entfernungen bis zu den Ortschaften abmessen, die rings um den Erschlagenen liegen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 21, 3, 'Dann sollen die Ältesten derjenigen Ortschaft, die dem Erschlagenen am nächsten liegt, eine junge Kuh nehmen, die noch nicht zur Arbeit benutzt und noch nie ins Joch gespannt worden ist,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 21, 4, 'und die Ältesten der betreffenden Ortschaft sollen die Kuh zu einem immerfließenden Bach hinführen, in dem nicht gearbeitet und an dem nicht gesät wird, und sollen der Kuh dort das Genick brechen, so daß das Blut in den Bach hineinfließt.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 21, 5, 'Hierauf sollen die Priester vom Stamm Levi herantreten; denn sie hat der HERR, dein Gott, erwählt, damit sie ihm dienen und im Namen des HERRN segnen, und nach ihrem Ausspruch soll bei jedem Rechtshandel und jedem Verbrechen verfahren werden.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 21, 6, 'Dann sollen alle Ältesten der betreffenden Ortschaft, weil sie dem Erschlagenen am nächsten wohnen, über der Kuh, der man das Genick in den Bach hinein gebrochen hat, ihre Hände waschen');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 21, 7, 'und mit erhobener Stimme aussagen: ›Unsere Hände haben dieses Blut nicht vergossen, und unsere Augen haben nichts von der Tat gesehen!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 21, 8, 'Vergib, o HERR, deinem Volke Israel, das du erlöst hast, und mache dein Volk Israel nicht für unschuldig in seiner Mitte vergossenes Blut verantwortlich!‹ Dann wird die Blutschuld für sie gesühnt sein!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 21, 9, 'So sollst du das unschuldig vergossene Blut aus deiner Mitte wegschaffen, indem du das tust, was in den Augen des HERRN das Richtige ist.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 21, 10, '»Wenn du zum Kriege gegen deine Feinde ausziehst und der HERR, dein Gott, sie in deine Gewalt gibt und du Gefangene von ihnen erbeutest');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 21, 11, 'und du unter den Gefangenen ein Weib von schöner Gestalt siehst und sie liebgewinnst, so daß du sie zur Frau nehmen möchtest,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 21, 12, 'so sollst du sie in dein Haus hineinführen; sie schere sich dann das Haupt, beschneide ihre Nägel,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 21, 13, 'lege die Kleidung ab, die sie als Gefangene getragen hat, bleibe in deinem Hause und betrauere ihre Eltern einen Monat lang; danach darfst du zu ihr eingehen und die Ehe mit ihr vollziehen, und sie darf als deine Frau gelten.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 21, 14, 'Wenn du dich aber nicht mehr zu ihr hingezogen fühlst, so hast du sie gehen zu lassen, wohin es ihr beliebt; aber für Geld darfst du sie keinesfalls verkaufen, darfst sie auch nicht gewalttätig (als Sklavin) behandeln, weil du ehelich mit ihr gelebt hast.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 21, 15, '»Wenn ein Mann zwei Frauen hat, von denen ihm die eine lieb, die andere ungeliebt ist, und sie beide ihm Söhne gebären, die geliebte wie die ungeliebte, und der erstgeborene Sohn von der ungeliebten Frau stammt,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 21, 16, 'so darf er an dem Tage, an welchem er sein Vermögen an seine Söhne als Erbgut verteilt, nicht dem Sohne der geliebten Frau die Rechte der Erstgeburt verleihen zum Schaden des Sohnes der ungeliebten, welcher doch tatsächlich der Erstgeborene ist;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 21, 17, 'sondern er muß den Erstgeborenen, den Sohn der ungeliebten Frau, als solchen anerkennen, indem er ihm zwei Teile von seinem gesamten Vermögen überweist; denn dieser ist der Erstling seiner Kraft: ihm steht das Erstgeburtsrecht zu.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 21, 18, '»Wenn jemand einen störrischen und widerspenstigen Sohn hat, der auf die Mahnungen seines Vaters und seiner Mutter nicht hört und ihnen trotz aller Zurechtweisungen nicht gehorcht,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 21, 19, 'so sollen seine Eltern ihn ergreifen und ihn vor die Ältesten der betreffenden Ortschaft und zwar an das Tor des betreffenden Ortes führen');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 21, 20, 'und sollen zu den Ältesten der Ortschaft sagen: ›Dieser unser Sohn ist störrisch und widerspenstig; er hört nicht auf unsere Mahnungen, ist ein Verschwender und Trinker!‹');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 21, 21, 'Dann sollen alle Männer der betreffenden Ortschaft ihn zu Tode steinigen. So sollst du das Böse aus deiner Mitte wegschaffen, und alle Israeliten sollen es erfahren und es sich zur Warnung dienen lassen.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 21, 22, '»Wenn jemand ein todeswürdiges Verbrechen begangen hat und man ihn nach seiner Tötung an einen Baum hängt,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 21, 23, 'so soll sein Leichnam nicht über Nacht an dem Baume hängen bleiben, sondern du sollst ihn unbedingt noch an demselben Tage begraben; denn ein Gehenkter ist von Gott verflucht, und du darfst dein Land, das der HERR, dein Gott, dir zum Eigentum geben will, nicht verunreinigen.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 22, 1, '»Wenn du siehst, daß das Rind eines deiner Volksgenossen oder ein Stück seines Kleinviehs sich verlaufen hat, so sollst du ihnen deine Hilfe nicht versagen, sollst sie vielmehr deinem Volksgenossen zurückbringen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 22, 2, 'Wenn aber dein Volksgenosse nicht in deiner Nähe wohnt oder du ihn nicht kennst, so sollst du das Tier in dein Haus aufnehmen, und es soll bei dir bleiben, bis dein Volksgenosse es sucht: dann gib es ihm zurück.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 22, 3, 'Ebenso sollst du es mit seinem Esel und ebenso mit einem Kleidungsstück von ihm machen, überhaupt mit allem, was einem von deinen Volksgenossen verlorengeht oder ihm abhanden kommt und was du findest: du darfst ihm deine Hilfe nicht versagen. –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 22, 4, 'Wenn du den Esel oder das Rind eines deiner Volksgenossen auf dem Wege zusammengebrochen daliegen siehst, sollst du ihm deine Hilfe nicht versagen, vielmehr sollst du das Tier mit ihm wieder auf die Beine bringen.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 22, 5, '»Eine Frau soll keine Männerkleider tragen und ein Mann keine Frauenkleider anziehen; denn wer dieses tut, ist für den HERRN, deinen Gott, ein Greuel. –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 22, 6, 'Wenn dir bei einer Wanderung ein Vogelnest auf irgendeinem Baum oder auf der Erde mit Jungen oder mit Eiern zu Gesicht kommt und die Vogelmutter auf den Jungen oder auf den Eiern sitzt, so sollst du nicht die Vogelmutter samt den Jungen nehmen;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 22, 7, 'laß vielmehr die Mutter fliegen und nimm dir nur die Jungen, damit es dir wohl ergeht und du lange lebst. –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 22, 8, 'Wenn du ein neues Haus baust, so sollst du ein Geländer an deinem Dach anbringen, damit du keine Blutschuld auf dein Haus bringst, wenn jemand von ihm abstürzen sollte. –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 22, 9, 'Du darfst deinen Weinberg nicht mit zweierlei Gewächsen bepflanzen, damit nicht der volle Weinbergertrag, sowohl die Anpflanzung, die du gemacht hast, als auch der Ertrag des Weinbergs, dem Heiligtum verfällt. –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 22, 10, 'Du sollst nicht mit einem Ochsen und einem Esel zusammen ackern. –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 22, 11, 'Du sollst kein Zeug von verschiedenartigen Stoffen anziehen, das aus Wolle und Leinen zusammen hergestellt ist. –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 22, 12, 'An den vier Zipfeln deines Obergewandes, mit dem du dich umhüllst, sollst du dir Quasten anbringen.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 22, 13, '»Wenn ein Mann eine Frau geheiratet und mit ihr ehelich gelebt hat, dann aber ihrer überdrüssig wird');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 22, 14, 'und ihr schandbare Dinge, die nur Gerede sind, zur Last legt und sie in üblen Ruf bringt, indem er sagt: ›Diese Frau habe ich geheiratet, aber als ich mich ihr nahte, habe ich die Zeichen der Jungfräulichkeit nicht an ihr gefunden‹,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 22, 15, 'so sollen die Eltern der jungen Frau die Zeichen der Jungfräulichkeit der jungen Frau nehmen und vor die Ältesten der Ortschaft an das Tor hinausbringen;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 22, 16, 'dann soll der Vater der jungen Frau zu den Ältesten sagen: ›Ich habe meine Tochter diesem Mann zur Frau gegeben, aber er ist ihrer überdrüssig geworden');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 22, 17, 'und legt ihr nun schandbare Dinge, die nichts als Gerede sind, zur Last, indem er behauptet: Ich habe an deiner Tochter die Zeichen der Jungfräulichkeit nicht gefunden –, und hier sind doch die Beweise für die Jungfräulichkeit meiner Tochter!‹ Und sie (die Eltern) sollen dabei das betreffende Stück Zeug vor den Ältesten der Ortschaft ausbreiten.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 22, 18, 'Hierauf sollen die Ältesten jener Ortschaft den Mann ergreifen und ihn züchtigen;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 22, 19, 'auch sollen sie ihm eine Geldstrafe von hundert Silberschekeln auferlegen und diese dem Vater der jungen Frau geben, weil er eine israelitische Jungfrau in üblen Ruf gebracht hat. Auch soll sie ihm dann als Frau angehören, die er zeitlebens nicht entlassen kann.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 22, 20, 'Wenn aber jene Behauptung: ›Es ist kein Zeichen der Jungfräulichkeit an der jungen Frau gefunden worden‹ auf Wahrheit beruht,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 22, 21, 'so soll man die junge Frau an den Eingang ihres Vaterhauses führen, und die Männer der betreffenden Ortschaft sollen sie zu Tode steinigen, weil sie eine Schandtat in Israel verübt hat, indem sie in ihrem Vaterhause Unzucht trieb. So sollst du das Böse aus deiner Mitte wegschaffen!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 22, 22, '»Wird ein Mann im Ehebruch mit der Ehefrau eines andern ertappt, so sollen sie alle beide sterben, der Mann, der sich mit der Frau vergangen hat, und die Frau. So sollst du das Böse aus Israel wegschaffen!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 22, 23, 'Wenn ein Mädchen, eine Jungfrau, einem Manne verlobt ist und jemand sie innerhalb der Ortschaft trifft und ihr beiwohnt,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 22, 24, 'so sollt ihr sie beide zum Tor der betreffenden Ortschaft hinausführen und sie zu Tode steinigen: das Mädchen deshalb, weil sie in der Ortschaft nicht um Hilfe geschrien hat, und den Mann deshalb, weil er die Braut eines andern entehrt hat. So sollst du das Böse aus deiner Mitte wegschaffen! –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 22, 25, 'Wenn aber der Mann das verlobte Mädchen auf dem Felde angetroffen und sie ergriffen und ihr beigewohnt hat, so soll der Mann, der ihr Gewalt angetan hat, allein sterben;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 22, 26, 'dem Mädchen aber soll man nichts tun: sie hat sich kein todeswürdiges Verbrechen zuschulden kommen lassen; denn es verhält sich in diesem Falle ebenso, wie wenn ein Mann einen andern überfällt und ihn ums Leben bringt.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 22, 27, 'Er hat sie ja auf dem Felde getroffen; und wenn das verlobte Mädchen auch geschrien hätte, so würde doch kein Retter für sie dagewesen sein. –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 22, 28, 'Wenn ein Mann ein Mädchen, eine Jungfrau, die nicht verlobt ist, antrifft und sie ergreift und ihr beiwohnt und man ihn ertappt,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 22, 29, 'so soll der Mann, der ihr beigewohnt hat, dem Vater des Mädchens fünfzig Schekel Silber geben, und sie soll ihm als Frau angehören; zur Strafe dafür, daß er sie entehrt hat, darf er sie zeitlebens nicht entlassen. –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 23, 1, 'Niemand darf die Frau seines Vaters zum Weibe nehmen und überhaupt nicht die Bettdecke seines Vaters aufdecken.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 23, 2, '»Keiner, dem die Hoden zerquetscht oder die Harnröhre abgeschnitten ist, darf in die Gemeinde des HERRN aufgenommen werden.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 23, 3, 'Kein Bastard darf in die Gemeinde des HERRN aufgenommen werden; nicht einmal das zehnte Geschlecht der Nachkommen des Betreffenden darf in die Gemeinde des HERRN aufgenommen werden. –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 23, 4, 'Kein Ammoniter und kein Moabiter darf in die Gemeinde des HERRN aufgenommen werden; nicht einmal das zehnte Geschlecht der Nachkommen von ihnen darf jemals in die Gemeinde des HERRN aufgenommen werden,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 23, 5, 'deshalb weil sie euch auf eurer Wanderung, als ihr aus Ägypten auszogt, nicht mit Brot und Wasser entgegengekommen sind und weil sie Bileam, den Sohn Beors, aus Pethor in Mesopotamien gegen dich in Sold genommen haben, damit er dich verfluche.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 23, 6, 'Aber der HERR, dein Gott, wollte Bileam nicht erhören, sondern der HERR, dein Gott, verwandelte dir den Fluch in Segen; denn der HERR, dein Gott, hat dich lieb.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 23, 7, 'Sei niemals, solange du lebst, darauf bedacht, ihnen etwas Gutes oder eine Liebe zu erweisen! –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 23, 8, 'Einen Edomiter sollst du nicht verabscheuen, denn er ist dein Bruder. – Einen Ägypter sollst du nicht verabscheuen, denn du hast als Gast in seinem Lande gewohnt.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 23, 9, 'Von den Kindern, die ihnen geboren werden, dürfen die zum dritten Geschlecht Gehörenden in die Gemeinde des HERRN aufgenommen werden.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 23, 10, '»Wenn du als Kriegsherr gegen deine Feinde ausziehst, so sollst du dich vor allem Ungehörigen hüten.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 23, 11, 'Ist ein Mann unter dir, der infolge eines nächtlichen Begegnisses unrein geworden ist, so soll er aus dem Lager hinausgehen: er darf nicht wieder in das Lager hineinkommen;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 23, 12, 'gegen Abend soll er dann eine Waschung an sich vornehmen und darf hierauf bei Sonnenuntergang ins Lager zurückkehren.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 23, 13, 'Auch sollst du außerhalb des Lagers einen Seitenplatz haben, wohin du austreten kannst;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 23, 14, 'und unter deinen Geräten sollst du einen Spaten haben, mit dem du, wenn du draußen deine Notdurft verrichtest, ein Loch graben und deinen Unrat wieder bedecken sollst.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 23, 15, 'Denn der HERR, dein Gott, zieht inmitten deines Lagers einher, um dich zu erretten und deine Feinde dir preiszugeben; darum soll dein Lager heilig sein, damit er nichts Häßliches bei dir wahrnimmt und sich nicht von dir abwendet.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 23, 16, '»Einen Knecht, der sich vor seinem Herrn zu dir geflüchtet hat, sollst du seinem Herrn nicht ausliefern:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 23, 17, 'er soll bei dir, in deiner Mitte, wohnen an dem Ort, den er in einer deiner Ortschaften erwählt, wo es ihm gut dünkt: du sollst ihm keine Schwierigkeiten machen! –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 23, 18, 'Unter den Töchtern der Israeliten soll es keine der Unzucht geweihte Dirne geben, und unter den Söhnen der Israeliten soll es keinen zur Unzucht bestimmten Buhler geben.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 23, 19, 'Du darfst keinen Hurenlohn und kein Hundegeld aus irgendeinem Gelübde in das Haus des HERRN, deines Gottes, bringen; denn ein Greuel für den HERRN, deinen Gott, sind sie alle beide. –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 23, 20, 'Du sollst von deinem Volksgenossen keinen Zins verlangen, weder für geliehenes Geld, noch für gelieferte Lebensmittel, noch für irgend etwas anderes, das man gegen Zinsen verleihen kann.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 23, 21, 'Von einem Ausländer magst du dir Zinsen zahlen lassen, nicht aber von einem deiner Volksgenossen, damit der HERR, dein Gott, dich bei allen deinen Unternehmungen segnet in dem Lande, in das du kommst, um es in Besitz zu nehmen. –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 23, 22, 'Wenn du dem HERRN, deinem Gott, ein Gelübde leistest, so säume nicht, es zu erfüllen! denn der HERR, dein Gott, wird es sicherlich von dir fordern, und du würdest dir eine Verschuldung aufgeladen haben.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 23, 23, 'Wenn du aber das Geloben unterläßt, so ziehst du dir dadurch keine Verschuldung zu;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 23, 24, 'nur was deine Lippen ausgesprochen haben, mußt du auch halten und ausführen, weil du dem HERRN, deinem Gott, freiwillig gelobt hast, was du mit deinem Munde ausgesprochen hast. –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 23, 25, 'Wenn du in den Weinberg eines deiner Volksgenossen kommst, so magst du Trauben nach deinem Begehren essen, bis du satt bist; aber in dein Gefäß darfst du keine tun.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 23, 26, 'Wenn du an das Kornfeld eines deiner Volksgenossen kommst, so magst du Ähren mit der Hand abpflücken; aber eine Sichel darfst du nicht an das Getreide eines deiner Volksgenossen legen. –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 24, 1, 'Wenn ein Mann eine Frau nimmt und die Ehe mit ihr vollzieht, später aber sich nicht mehr zu ihr hingezogen fühlt, weil er etwas Häßliches an ihr entdeckt hat, und er hat ihr einen Scheidebrief geschrieben und ihn ihr eingehändigt und sie aus seinem Hause entlassen, –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 24, 2, 'wenn sie also aus seinem Hause weggegangen ist und die Ehe mit einem andern Manne vollzogen hat');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 24, 3, 'und der zweite Mann ihr ebenfalls abgeneigt wird und ihr auch einen Scheidebrief schreibt und ihn ihr einhändigt und sie so aus seinem Hause entläßt, oder wenn der zweite Mann, der sie geheiratet hat, stirbt:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 24, 4, 'so darf ihr erster Mann, der sie verstoßen hatte, sie nicht nochmals zur Frau nehmen, nachdem sie verunreinigt worden ist; denn das würde ein Greuel in den Augen des HERRN sein, und du sollst das Land, das der HERR, dein Gott, dir zum Erbbesitz geben will, nicht mit Sünde beladen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 24, 5, 'Wenn jemand neuvermählt ist, so braucht er nicht mit dem Heere ins Feld zu ziehen, und keinerlei Verpflichtung soll ihm auferlegt werden: er soll ein Jahr lang für sein Haus frei sein und seine Frau erfreuen, die er geheiratet hat. –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 24, 6, 'Man darf nicht die Handmühle oder auch nur den oberen Mühlstein pfänden, denn damit würde man das Leben zum Pfande nehmen. –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 24, 7, 'Wird jemand dabei ertappt, daß er einen von seinen Volksgenossen, von den Israeliten, geraubt und ihn gewaltsam (als Sklaven) behandelt oder ihn verkauft hat, so soll ein solcher Menschendieb sterben: so sollst du das Böse aus deiner Mitte wegschaffen. –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 24, 8, 'Nimm dich bei der Erkrankung an Aussatz wohl in acht, daß du aufs sorgfältigste alle Weisungen befolgst, die euch die levitischen Priester erteilen werden: verfahrt genau so, wie ich ihnen geboten habe.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 24, 9, 'Denke daran, was der HERR, dein Gott, an Mirjam unterwegs bei eurem Auszug aus Ägypten getan hat! –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 24, 10, 'Wenn du deinem Nächsten ein Darlehn von irgendwelchem Betrage gewährst, so sollst du nicht in sein Haus hineingehen, um ihm ein Pfand abzunehmen;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 24, 11, 'nein, du sollst draußen auf der Straße stehen bleiben, und der Mann, dem du leihst, soll das Pfand zu dir herausbringen;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 24, 12, 'und wenn er ein dürftiger Mann ist, so sollst du dich mit seinem Pfand nicht schlafen legen,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 24, 13, 'sondern ihm vielmehr das Pfand bei Sonnenuntergang zurückgeben, damit er sich in seinem Mantel schlafen legen kann und dich segnet; dann wird dir das als Gerechtigkeit vor dem HERRN, deinem Gott, gelten. –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 24, 14, 'Bedrücke keinen dürftigen und armen Tagelöhner, der zu deinen Volksgenossen oder zu den Fremden gehört, die bei dir in deinem Lande, in deinen Ortschaften leben!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 24, 15, 'Noch an demselben Tage sollst du ihm seinen Lohn geben, ehe noch die Sonne darüber untergeht; denn er ist arm, und sein Herz sehnt sich danach; er würde sonst vielleicht den HERRN gegen dich anrufen, und du hättest eine Verschuldung auf dich geladen. –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 24, 16, 'Väter sollen nicht wegen (einer Verschuldung) ihrer Kinder mit dem Tode bestraft werden, und Kinder sollen nicht wegen (einer Verschuldung) ihrer Väter sterben; ein jeder soll nur wegen seines eigenen Vergehens mit dem Tode bestraft werden! –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 24, 17, 'Du sollst das Recht eines Nichtisraeliten und einer Waise nicht beugen und das Kleid einer Witwe nicht pfänden;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 24, 18, 'du sollst vielmehr daran gedenken, daß du selbst einst ein Knecht in Ägypten gewesen bist und daß der HERR, dein Gott, dich von dort erlöst hat. Darum gebiete ich dir, so zu verfahren. –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 24, 19, 'Wenn du beim Abernten deines Feldes eine Garbe auf dem Felde vergessen hast, so sollst du nicht umkehren, um sie zu holen: sie soll den Fremdlingen, den Waisen und den Witwen gehören, damit der HERR, dein Gott, dich bei allem, was du unternimmst, segnet.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 24, 20, 'Wenn du deine Ölbäume abklopfst, sollst du hinterher nicht noch Nachlese an den Zweigen halten: was an Früchten noch übrig ist, soll den Fremdlingen, den Waisen und den Witwen zugute kommen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 24, 21, 'Wenn du die Lese in deinem Weinberge hältst, sollst du hinterher nicht noch eine Nachlese vornehmen: was (an Trauben) noch übrig ist, soll den Fremdlingen, den Waisen und den Witwen zufallen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 24, 22, 'Denn du sollst daran gedenken, daß du selbst einst ein Knecht im Lande Ägypten gewesen bist; darum gebiete ich dir, so zu verfahren.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 25, 1, '»Wenn es zwischen Männern zu einem Rechtsstreit kommt und sie vor Gericht getreten sind und man das Urteil über sie gesprochen hat, indem man den Unschuldigen freigesprochen und den Schuldigen verurteilt hat,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 25, 2, 'so soll, wenn der Schuldige Prügelstrafe verdient hat, der Richter ihn sich hinlegen lassen, und man soll ihm in seiner Gegenwart eine bestimmte Anzahl von Schlägen nach Maßgabe seiner Verschuldung geben.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 25, 3, 'Vierzig Schläge darf er ihm geben lassen, aber nicht mehr, damit dein Volksgenosse nicht, wenn man fortführe, ihm eine noch größere Zahl von Schlägen zu versetzen, in deinen Augen verächtlich gemacht wird. –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 25, 4, 'Du sollst einem Ochsen, während er drischt, das Maul nicht verbinden.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 25, 5, '»Wenn Brüder beisammen wohnen und einer von ihnen stirbt, ohne einen Sohn zu hinterlassen, so soll sich die Ehefrau des Verstorbenen nicht nach auswärts an einen fremden Mann verheiraten, sondern ihr Schwager soll zu ihr eingehen und sie zu seiner Frau nehmen und die Schwagerehe mit ihr vollziehen;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 25, 6, 'der erste Sohn aber, den sie dann gebiert, soll auf den Namen seines verstorbenen Bruders (in die Geschlechtsregister) eingetragen werden, damit dessen Name in Israel nicht ausstirbt.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 25, 7, 'Wenn aber der Mann sich nicht dazu verstehen will, seine Schwägerin zu heiraten, so soll seine Schwägerin ans Tor zu den Ältesten hingehen und sagen: ›Mein Schwager weigert sich, den Namen seines Bruders in Israel fortzupflanzen: er will die Schwagerehe nicht mit mir eingehen!‹');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 25, 8, 'Dann sollen die Ältesten der betreffenden Ortschaft ihn rufen lassen und ihm Vorstellungen machen; und wenn er trotzdem darauf besteht und erklärt: ›Ich bin nicht geneigt, sie zu heiraten!‹,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 25, 9, 'so soll seine Schwägerin vor den Augen der Ältesten zu ihm hintreten, soll ihm den Schuh vom Fuß ziehen, ihm ins Angesicht speien und laut ausrufen: ›So soll es dem Mann ergehen, der das Haus seines Bruders nicht bauen will!‹');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 25, 10, 'Mit einem Spottnamen soll dann sein Haus in Israel die ›Barfüßerfamilie‹ heißen.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 25, 11, '»Wenn zwei Männer, Volksgenossen, miteinander handgemein werden und die Frau des einen, die herbeigeeilt ist, um ihren Mann aus den Händen dessen, der ihn schlägt, zu retten, jenen mit ihrer Hand bei den Geschlechtsteilen faßt,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 25, 12, 'so sollst du ihr die Hand abhauen, ohne einen Blick des Mitleids für sie zu haben! –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 25, 13, 'Du sollst in deinem Beutel nicht zweierlei Gewichtsteine, einen größeren und einen kleineren, haben;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 25, 14, 'du sollst in deinem Hause nicht zweierlei Hohlmaße, ein größeres und ein kleineres, haben:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 25, 15, 'volle und richtige Gewichte und volle und richtige Maße sollst du haben, damit du lange in dem Lande lebst, das der HERR, dein Gott, dir geben wird;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 25, 16, 'denn ein Greuel für den HERRN, deinen Gott, ist jeder, der solches tut, jeder, der Unredlichkeit übt.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 25, 17, '»Denke daran, was die Amalekiter dir unterwegs bei eurem Auszug aus Ägypten angetan haben:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 25, 18, 'daß sie dich, während du müde und matt warst, auf der Wanderung ohne Furcht vor Gott überfallen und alle die niedergehauen haben, welche bei dir vor Ermattung zurückgeblieben waren.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 25, 19, 'Wenn dir also der HERR, dein Gott, Ruhe vor allen deinen Feinden ringsum geschafft hat in dem Lande, das der HERR, dein Gott, dir als Erbgut zu seiner Besetzung geben wird, so sollst du das Andenken an die Amalekiter unter dem ganzen Himmel austilgen: vergiß es nicht!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 26, 1, '»Wenn du nun in das Land gekommen bist, das der HERR, dein Gott, dir zu eigen geben wird, und du es in Besitz genommen hast und in ihm wohnst,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 26, 2, 'so sollst du einen Teil von den Erstlingen aller Feldfrüchte, die du von deinem Lande, das der HERR, dein Gott, dir geben wird, geerntet hast, nehmen und sie in einen Korb legen und dich damit an die Stätte begeben, die der HERR, dein Gott, erwählen wird, um seinen Namen daselbst wohnen zu lassen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 26, 3, 'Dort sollst du dann zu dem Priester treten, der zu jener Zeit im Amt sein wird, und zu ihm sagen: ›Ich bezeuge heute dem HERRN, deinem Gott, daß ich wirklich in das Land gekommen bin, dessen Verleihung an uns der HERR unsern Vätern zugeschworen hat.‹');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 26, 4, 'Hierauf soll der Priester den Korb aus deiner Hand nehmen und ihn vor den Altar des HERRN, deines Gottes, hinstellen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 26, 5, 'Du aber sollst dann vor dem HERRN, deinem Gott, folgende Worte aussprechen: ›Ein umherirrender Aramäer war mein Stammvater; mit einer Mannschaft von wenigen Leuten zog er nach Ägypten hinab und lebte dort als Fremdling, wuchs dort aber zu einem großen, starken und zahlreichen Volk heran.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 26, 6, 'Weil aber die Ägypter uns mißhandelten und bedrückten und uns harte Zwangsarbeit auferlegten,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 26, 7, 'schrien wir zum HERRN, dem Gott unserer Väter, um Hilfe, und der HERR erhörte unser Flehen und sah unser Elend, unsere Mühsal und Bedrängnis;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 26, 8, 'und der HERR führte uns mit starker Hand und hocherhobenem Arm, mit schreckenerregender Macht und unter Zeichen und Wundern aus Ägypten hinaus;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 26, 9, 'er brachte uns an diesen Ort und gab uns dieses Land, ein Land, das von Milch und Honig überfließt.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 26, 10, 'Und nun bringe ich hier die Erstlinge von den Früchten des Feldes, das du, HERR, mir gegeben hast.‹ Dann stelle sie vor den HERRN, deinen Gott, hin, wirf dich vor dem HERRN, deinem Gott, anbetend nieder');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 26, 11, 'und erfreue dich mit den Leviten und den Fremdlingen, die in deiner Mitte wohnen, an all dem Guten, das der HERR, dein Gott, dir und deinem Hause gegeben hat.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 26, 12, '»Wenn du im dritten Jahre, dem Zehntjahr, den gesamten Zehnten von deinem Ernteertrag vollständig entrichtet und ihn den Leviten, den Fremdlingen, den Waisen und Witwen übergeben hast, damit sie ihn in deinen Ortschaften verzehren und sich satt essen,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 26, 13, 'so sollst du vor dem HERRN, deinem Gott, so sprechen: ›Ich habe die heilige Abgabe aus meinem Hause hinausgeschafft und sie den Leviten und Fremdlingen, den Waisen und Witwen genau so übergeben, wie du mir geboten hast: ich habe keines von deinen Geboten übertreten noch vergessen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 26, 14, 'Ich habe nichts davon gegessen in meiner Trauer und nichts davon weggeschafft, während ich unrein war, und habe nichts davon für eine Totenspeisung verwandt, nein, ich bin den Weisungen des HERRN, meines Gottes, nachgekommen und habe mich genau an seine Gebote gehalten.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 26, 15, 'Blicke von deiner heiligen Wohnung, vom Himmel, herab und segne dein Volk Israel und das Land, das du uns gegeben hast, wie du unsern Vätern zugeschworen hast, ein Land, das von Milch und Honig überfließt!‹«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 26, 16, '»Am heutigen Tage gebietet dir der HERR, dein Gott, diese Satzungen und Verordnungen zu befolgen: so beobachte und befolge sie denn von ganzem Herzen und mit ganzer Seele!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 26, 17, 'Du hast dir heute vom HERRN verkünden lassen, daß er dein Gott sein wolle und daß es dir zukomme, auf seinen Wegen zu wandeln, seine Satzungen, Vorschriften und Verordnungen zu beobachten und seinen Weisungen zu gehorchen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 26, 18, 'Der HERR aber hat dich heute die Erklärung aussprechen lassen, daß du sein Eigentumsvolk sein wollest, wie er dir geboten hat, und daß es dir zukomme, alle seine Gebote zu beobachten,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 26, 19, 'und daß er dich über alle Völker, die er geschaffen hat, zu Ruhm und Ehre und Ansehen erhöhen wolle und daß du ein dem HERRN, deinem Gott, geheiligtes Volk sein wollest, wie er dir geboten hat.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 27, 1, 'Weiter geboten Mose und die Ältesten der Israeliten dem Volke folgendes: »Beobachtet alle Gebote, die ich euch heute zur Pflicht mache!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 27, 2, 'Sobald ihr also über den Jordan in das Land gezogen seid, das der HERR, dein Gott, dir geben wird, so richte dir große Steine auf, überstreiche sie mit Tünchkalk');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 27, 3, 'und schreibe, sobald du hinübergezogen bist, alle Worte dieses Gesetzes auf sie, damit du in das Land hineinkommst, das der HERR, dein Gott, dir geben will, ein Land, das von Milch und Honig überfließt, wie der HERR, der Gott deiner Väter, dir verheißen hat.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 27, 4, 'Sobald ihr also über den Jordan gezogen seid, sollt ihr diese Steine, auf die sich mein heutiger Befehl bezieht, auf dem Berge Ebal aufrichten und sie mit Tünchkalk überstreichen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 27, 5, 'Auch sollst du dort dem HERRN, deinem Gott, einen Altar erbauen, und zwar einen Altar von Steinen, die du mit keinem eisernen Werkzeug bearbeiten darfst:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 27, 6, 'aus unbehauenen Steinen sollst du den Altar des HERRN, deines Gottes, erbauen und dem HERRN, deinem Gott, Brandopfer auf ihm darbringen;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 27, 7, 'und du sollst Dankopfer schlachten und ein Opfermahl dort halten und vor dem HERRN, deinem Gott, fröhlich sein.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 27, 8, 'Auf die Steine aber sollst du alle Worte dieses Gesetzes schreiben, indem du sie sorgfältig eingräbst.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 27, 9, 'Hierauf richteten Mose und die levitischen Priester folgende Worte an ganz Israel: »Beobachte Schweigen, Israel, und höre zu! Am heutigen Tage bist du zum Volk des HERRN, deines Gottes, geworden.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 27, 10, 'So gehorche denn den Weisungen des HERRN deines Gottes, und halte seine Gebote und seine Satzungen, die ich dir heute gebiete!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 27, 11, 'An demselben Tage erteilte Mose dem Volke folgenden Befehl:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 27, 12, '»Wenn ihr über den Jordan gezogen seid, so sollen die einen sich auf dem Berge Garizim aufstellen, um das Volk zu segnen, nämlich Simeon, Levi, Juda, Issaschar, Joseph und Benjamin;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 27, 13, 'die anderen aber sollen sich, um den Fluch auszusprechen, auf dem Berge Ebal aufstellen, nämlich Ruben, Gad und Asser und Sebulon, Dan und Naphthali.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 27, 14, 'Danach sollen die Leviten anheben und mit hocherhobener Stimme zu allen Männern Israels sagen:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 27, 15, '›Verflucht sei, wer ein geschnitztes oder gegossenes Bild, einen Greuel für den HERRN, ein Machwerk von Künstlerhand, anfertigt und es heimlich aufstellt!‹, und das ganze Volk soll antworten: ›So sei es!‹');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 27, 16, '›Verflucht sei, wer seinen Vater oder seine Mutter mißachtet!‹, und das ganze Volk soll sagen: ›So sei es!‹');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 27, 17, '›Verflucht sei, wer die Grenze seines Nächsten verrückt!‹, und das ganze Volk soll sagen: ›So sei es!‹');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 27, 18, '›Verflucht sei, wer einen Blinden auf dem Wege irreführt!‹, und das ganze Volk soll sagen: ›So sei es!‹');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 27, 19, '›Verflucht sei, wer das Recht von Fremdlingen, von Waisen und Witwen beugt!‹, und das ganze Volk soll sagen: ›So sei es!‹');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 27, 20, '›Verflucht sei, wer sich mit dem Weibe seines Vaters vergeht; denn er hat die Bettdecke seines Vaters aufgedeckt!‹, und das ganze Volk soll sagen: ›So sei es!‹');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 27, 21, '›Verflucht sei, wer irgendein Tier zur Unzucht mißbraucht!‹, und das ganze Volk soll sagen: ›So sei es!‹');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 27, 22, '›Verflucht sei, wer sich mit seiner Schwester, der Tochter seines Vaters oder der Tochter seiner Mutter, vergeht!‹, und das ganze Volk soll sagen: ›So sei es!‹');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 27, 23, '›Verflucht sei, wer sich mit seiner Schwägerin vergeht!‹, und das ganze Volk soll sagen: ›So sei es!‹');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 27, 24, '›Verflucht sei, wer seinen Nächsten heimlich erschlägt!‹, und das ganze Volk soll sagen: ›So sei es!‹');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 27, 25, '›Verflucht sei, wer sich durch Bestechung dazu bringen läßt, jemand zu erschlagen, unschuldiges Blut zu vergießen!‹, und das ganze Volk soll sagen: ›So sei es!‹');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 27, 26, '›Verflucht sei, wer nicht die Bestimmungen dieses Gesetzes durch ihre Erfüllung aufrechthält!‹, und das ganze Volk soll sagen: ›So sei es!‹«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 1, '»Wenn du aber den Weisungen des HERRN, deines Gottes, gewissenhaft nachkommst, indem du auf die Beobachtung aller seiner Gebote, die ich dir heute zur Pflicht mache, bedacht bist, so wird der HERR, dein Gott, dich über alle Völker der Erde erhöhen,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 2, 'und alle die folgenden Segnungen werden dir zuteil werden und bei dir eintreffen, wenn du den Weisungen des HERRN, deines Gottes, nachkommst:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 3, 'Gesegnet wirst du sein in der Stadt und gesegnet auf dem Felde.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 4, 'Gesegnet wird die Frucht deines Mutterleibes sein und die Frucht deines Ackers und die Frucht deines Viehs, der Wurf deiner Rinder und der Nachwuchs deines Kleinviehs.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 5, 'Gesegnet wird dein Fruchtkorb und dein Backtrog sein.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 6, 'Gesegnet wirst du bei deinem Eingang sein und gesegnet bei deinem Ausgang.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 7, 'Der HERR wird deine Feinde, die sich gegen dich erheben, niedergeworfen vor dir erliegen lassen; auf einem einzigen Wege werden sie gegen dich zu Felde ziehen, aber auf sieben Wegen vor dir fliehen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 8, 'Der Herr wird bei dir den Segen walten lassen in deinen Speichern und bei allen deinen Unternehmungen und dich in dem Lande segnen, das der HERR, dein Gott, dir geben wird.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 9, 'Der HERR wird dich zu einem ihm geheiligten Volke erheben, wie er dir zugeschworen hat, wenn du die Gebote des HERRN, deines Gottes, beobachtest und auf seinen Wegen wandelst;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 10, 'da werden denn alle Völker der Erde sehen, daß du mit Recht das Volk des HERRN genannt wirst, und werden sich vor dir fürchten.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 11, 'Und der HERR wird dich durch die Frucht deines Mutterleibes und durch die Frucht deines Viehs und die Frucht deines Feldes zum Überfluß an Gütern gelangen lassen in dem Lande, das der HERR, wie er deinen Vätern zugeschworen hat, dir geben wird.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 12, 'Der HERR wird dir seine reiche Schatzkammer, den Himmel, auftun, um deinem Lande zu rechter Zeit den Regen zu spenden und alle Arbeiten deiner Hand zu segnen, so daß du vielen Völkern wirst leihen können, ohne selbst etwas entlehnen zu müssen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 13, 'So wird der HERR dich zum Haupt und nicht zum Schwanz machen, und es wird mit dir immer nur aufwärts gehen und nicht abwärts, wenn du den Geboten des HERRN, deines Gottes, deren genaue Beobachtung ich dir heute zur Pflicht mache, gehorsam bleibst');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 14, 'und von allen Weisungen, die ich euch heute gebiete, weder nach rechts noch nach links abweichst, indem du anderen Göttern nachgehst, um ihnen zu dienen.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 15, '»Wenn du aber den Weisungen des HERRN, deines Gottes, nicht gehorchst, daß du auf die sorgfältige Beobachtung seiner Gebote und Satzungen, die ich dir heute zur Pflicht mache, bedacht sein sollst, so werden alle folgenden Flüche über dich kommen und dich treffen:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 16, 'Verflucht wirst du sein in der Stadt und verflucht auf dem Felde.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 17, 'Verflucht wird dein Fruchtkorb und dein Backtrog sein.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 18, 'Verflucht wird die Frucht deines Mutterleibes und die Frucht deines Ackers sein, der Wurf deiner Rinder und der Nachwuchs deines Kleinviehs.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 19, 'Verflucht wirst du bei deinem Eingang sein und verflucht bei deinem Ausgang. –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 20, 'Der HERR wird den Fluch, die Bestürzung und die Verwünschung gegen dich senden bei allen Geschäften, die du unternimmst, bis du wegen deines frevelhaften Tuns, weil du mich verlassen hast, vertilgt bist und schnellen Untergang gefunden hast.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 21, 'Der HERR wird die Pest an dir haften lassen, bis er dich aus dem Lande ausgerottet hat, in das du jetzt ziehst, um es in Besitz zu nehmen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 22, 'Der HERR wird dich mit Schwindsucht und Fieber, mit Entzündung und Hitze, mit Dürre, Kornbrand und Vergilbung des Getreides heimsuchen, und dies alles wird dich verfolgen, bis du zugrunde gegangen bist.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 23, 'Der Himmel über deinem Haupt wird zu Erz werden und die Erde unter deinen Füßen zu Eisen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 24, 'Der HERR wird als Regen für dein Land Flugsand und Staub geben: vom Himmel wird er auf dich herabfallen, bis du vertilgt bist.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 25, 'Der HERR wird dich niedergeworfen vor deinen Feinden erliegen lassen: auf einem einzigen Wege wirst du gegen sie ausziehen und auf sieben Wegen vor ihnen fliehen; und du wirst für alle Reiche der Erde ein Schreckbild sein.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 26, 'Deine Leichen werden allen Vögeln des Himmels und den wilden Tieren zum Fraß dienen, ohne daß jemand sie verscheucht.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 27, 'Der HERR wird dich mit den Geschwüren Ägyptens und mit Pocken, mit Aussatz und Grind schlagen, daß du nicht wirst geheilt werden können.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 28, 'Der HERR wird dich mit Wahnsinn, mit Blindheit und geistiger Zerrüttung schlagen,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 29, 'so daß du am hellen Mittag umhertappen mußt, wie der Blinde im Finstern tappt; und du wirst bei deinen Unternehmungen kein Gelingen haben, sondern allezeit nur vergewaltigt und beraubt sein, ohne daß jemand dir hilft.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 30, 'Mit einem Weibe wirst du dich verloben, aber ein anderer Mann wird bei ihr schlafen; ein Haus wirst du dir bauen, aber nicht in ihm wohnen; einen Weinberg wirst du anlegen, aber seine Früchte nicht genießen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 31, 'Dein Rind wird vor deinen Augen geschlachtet werden, ohne daß du von ihm zu essen bekommst; dein Esel wird dir vor deinen Augen geraubt werden und nicht wieder zu dir zurückkehren; dein Kleinvieh wird deinen Feinden gegeben werden, ohne daß dir ein Helfer erscheint.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 32, 'Deine Söhne und Töchter fallen einem anderen Volke (als Sklaven) in die Hände; deine Augen müssen es ansehen und den ganzen Tag vor Sehnsucht nach ihnen schmachten, du aber vermagst nichts dagegen zu tun.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 33, 'Die Früchte deines Feldes und den ganzen Ertrag deiner Arbeit wird ein Volk verzehren, das du bis dahin nicht gekannt hast, und du wirst allezeit nur der Vergewaltigte und Mißhandelte sein:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 34, 'wahnsinnig wirst du werden beim Anblick dessen, was deine Augen zu sehen bekommen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 35, 'Der HERR wird dich mit bösen Geschwüren an den Knien und Schenkeln schlagen, von denen du nicht wirst geheilt werden können, von der Fußsohle bis zum Scheitel.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 36, 'Der HERR wird dich und deinen König, den du über dich setzen wirst, zu einem Volke führen, das dir und deinen Vätern bis dahin unbekannt gewesen ist; dort wirst du anderen Göttern, Götzen von Holz und Stein, dienen müssen');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 37, 'und wirst ein Gegenstand des Entsetzens, des Spottes und Hohns bei allen Völkern werden, wohin der HERR dich führen wird.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 38, 'Aussaat wirst du in Menge aufs Feld hinausbringen, aber nur wenig einernten; denn die Heuschrecken werden es abfressen;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 39, 'Weinberge wirst du anpflanzen und bearbeiten, aber Wein weder trinken noch einkellern, denn der Wurm wird ihn abfressen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 40, 'Ölbäume wirst du überall in deinem Gebiet haben, aber dich nicht mit Öl salben; denn deine Ölbäume werden die Früchte abfallen lassen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 41, 'Söhne und Töchter wirst du zeugen, aber sie werden dir nicht verbleiben, denn sie müssen in die Gefangenschaft wandern.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 42, 'Alle deine Bäume und die Früchte deines Ackers wird das Ungeziefer aufzehren.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 43, 'Der Fremdling, der in deiner Mitte lebt, wird immer höher über dich emporsteigen, während du immer tiefer hinabsinkst:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 44, 'er wird dir leihen, du aber wirst ihm nichts zu leihen haben; er wird zum Haupt, du aber wirst zum Schwanz werden.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 45, 'Alle diese Flüche werden über dich kommen, dich verfolgen und dich treffen, bis du vernichtet bist, weil du den Weisungen des HERRN, deines Gottes, nicht gehorcht hast und seinen Geboten und Satzungen, die er dir zur Pflicht gemacht hat, nicht nachgekommen bist;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 46, 'und sie werden an dir und deinen Nachkommen als Zeichen und Wunder bis in Ewigkeit haften.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 47, '»Zur Strafe dafür, daß du dem HERRN, deinem Gott, trotz des Überflusses an allem nicht mit freudigem und bereitwilligem Herzen gedient hast,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 48, 'wirst du deinen Feinden, die der HERR gegen dich senden wird, dienen müssen bei Hunger und Durst, bei Mangel an Kleidung und bei völliger Verarmung; und er wird dir ein eisernes Joch auf den Nacken legen, bis er dich vertilgt hat.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 49, 'Der HERR wird gegen dich aus der Ferne, vom Ende der Erde her, ein Volk heranführen, das so schnell wie ein Adler daherfliegt, ein Volk, dessen Sprache du nicht verstehst,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 50, 'ein Volk mit wildtrotzigem Angesicht, das auch auf einen Greis keine Rücksicht nimmt und mit keinem Kinde Erbarmen hat.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 51, 'Es wird den Ertrag deines Viehstandes und den Ertrag deines Feldes verzehren, bis du vertilgt bist, da es dir vom Getreide, vom Wein und Öl, vom Wurf deiner Rinder und vom Nachwuchs deines Kleinviehs nichts übriglassen wird, bis es dich zugrunde gerichtet hat.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 52, 'Es wird dich in all deinen Städten belagern, bis deine hohen und starken Mauern, auf die du dein Vertrauen setzt, in deinem ganzen Lande gefallen sind, und es wird dich in all deinen Städten belagern, in deinem ganzen Lande, das der HERR, dein Gott, dir gegeben hat.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 53, 'Da wirst du dann in der Angst und Bedrängnis, in die dein Feind dich versetzen wird, deine leiblichen Kinder verzehren, das Fleisch deiner Söhne und Töchter, die der HERR, dein Gott, dir geschenkt hat.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 54, 'Sogar der an Wohlleben und die größte Üppigkeit gewöhnte Mann bei dir wird dann auf seinen Bruder und auf das Weib an seinem Busen und auf den Rest seiner Kinder, die er noch übrigbehalten hat, voll Mißgunst blicken,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 55, 'so daß er keinem von ihnen etwas von dem Fleisch seiner Kinder abgibt, die er, ohne sich irgendeins übrigzulassen, in der Angst und Bedrängnis verzehrt, in die dich dein Feind in all deinen Ortschaften versetzen wird.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 56, 'Sogar die an Wohlleben und die größte Üppigkeit gewöhnte Frau bei dir, die vor Verzärtelung und Verweichlichung noch nie versucht hat, ihre Fußsohle auf die Erde zu setzen – auch deren Auge wird auf den Mann an ihrem Busen und auf ihren Sohn und ihre Tochter voll Mißgunst blicken');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 57, 'und wird ihnen die Nachgeburt mißgönnen, die aus ihrem Schoß hervorgeht, und die Kinder, die sie zur Welt gebracht hat; denn bei dem Mangel an allem wird sie diese heimlich verzehren in der Angst und Bedrängnis, in die dich dein Feind in deinen Ortschaften versetzen wird.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 58, 'Wenn du nicht auf die Beobachtung aller Bestimmungen dieses Gesetzes, die in diesem Buch aufgezeichnet stehen, bedacht bist, indem du diesen ruhmvollen und furchtbaren Namen, den HERRN, deinen Gott, fürchtest,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 59, 'so wird der HERR über dich und deine Nachkommen außergewöhnliche Unglücksschläge verhängen, schwere und andauernde Unglücksschläge und bösartige und andauernde Krankheiten.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 60, 'Er wird dann alle Seuchen Ägyptens bei dir einkehren lassen, vor denen du einst Grauen empfunden hast, und sie werden an dir haften bleiben.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 61, 'Auch alle Krankheiten und alle Heimsuchungen, die in diesem Gesetzbuch nicht verzeichnet stehen – auch die wird der HERR über dich kommen lassen, bis du vertilgt bist;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 62, 'und es werden Männer von euch nur in geringer Anzahl übrigbleiben, statt daß ihr vorher den Sternen des Himmels an Menge gleichkamt, weil du den Weisungen des HERRN, deines Gottes, nicht nachgekommen bist.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 63, 'Und wie der HERR vorher seine Freude daran gehabt hatte, euch Gutes zu erweisen und euch zahlreich werden zu lassen, ebenso wird der HERR dann bei euch seine Freude daran haben, euch zugrunde zu richten und zu vertilgen, so daß ihr aus dem Lande herausgerissen werdet, in das du jetzt einziehst, um es in Besitz zu nehmen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 64, 'Der HERR wird dich alsdann unter alle Völker von einem Ende der Erde bis zum andern zerstreuen, und du wirst dort anderen Göttern dienen müssen, von denen ihr, du und deine Väter, nichts gewußt habt, Götzen von Holz und Stein.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 65, 'Und du wirst unter jenen Völkern zu keiner Ruhe kommen, und für deine Fußsohle wird es keine Stätte der Rast geben, sondern der HERR wird dir dort ein immer zitterndes Herz und vor Sehnsucht schmachtende Augen und eine verzweifelnde Seele geben.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 66, 'Dein Leben wird dir an einem Faden zu hangen scheinen, so daß du bei Tag und bei Nacht in Angst schwebst und dich deines Lebens niemals sicher fühlst,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 67, 'am Morgen wirst du sagen: ›Ach, wäre es doch erst Abend!‹, und am Abend wirst du wünschen: ›Ach, wäre es doch schon Morgen!‹ infolge der Angst deines Herzens, die du empfinden wirst, und infolge des Anblicks der Schrecknisse, die dir vor Augen stehen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 68, 'Und der HERR wird dich auf Schiffen nach Ägypten zurückkehren lassen auf dem Wege, von dem ich dir gesagt habe: ›Du sollst ihn nie mehr wiedersehen!‹ Dort werdet ihr euch dann euren Feinden zu Sklaven und Sklavinnen verkaufen wollen, aber es wird sich kein Käufer finden.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 69, 'Dies sind die Worte des Bundes, den Mose auf Befehl des HERRN mit den Israeliten im Lande der Moabiter geschlossen hat, außer dem Bunde, den er am Horeb mit ihnen geschlossen hatte.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 29, 1, 'Mose berief also alle Israeliten und sagte zu ihnen: »Ihr habt selbst alles gesehen, was der HERR vor euren Augen im Lande Ägypten dem Pharao und allen seinen Knechten und seinem ganzen Lande hat widerfahren lassen:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 29, 2, 'die großen Machterweise, die du mit eigenen Augen gesehen hast, jene großen Zeichen und Wunder.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 29, 3, 'Aber bis auf den heutigen Tag hat der HERR euch kein Herz zum Erkennen, keine Augen zum Sehen und keine Ohren zum Hören gegeben.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 29, 4, 'Und doch habe ich euch vierzig Jahre lang in der Wüste wandern lassen: eure Kleider sind euch dabei nicht am Leibe zerfallen, und deine Schuhe haben sich an deinen Füßen nicht abgenutzt;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 29, 5, 'ihr habt kein Brot zu essen gehabt und keinen Wein und kein starkes Getränk getrunken, weil ihr erkennen solltet, daß ich der HERR, euer Gott, bin.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 29, 6, 'Als ihr dann in diese Gegend gelangtet, zogen Sihon, der König von Hesbon, und Og, der König von Basan, uns zum Kampf entgegen, aber wir schlugen sie');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 29, 7, 'und eroberten ihr Land und gaben es den Stämmen Ruben und Gad und dem halben Stamm Manasse zum Erbbesitz.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 29, 8, 'So beobachtet denn die Bestimmungen dieses Bundes und befolgt sie, damit ihr bei allen euren Unternehmungen glücklichen Erfolg habet!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 29, 9, '»Ihr steht heute allesamt vor dem HERRN, eurem Gott: eure Stammeshäupter, eure Richter, eure Ältesten und Obmänner, alle Männer Israels,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 29, 10, 'eure Kinder, eure Weiber und die Nichtisraeliten, die sich bei dir inmitten deines Lagers befinden, von den Holzhauern an bis zu den Wasserträgern bei dir,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 29, 11, 'damit du in den Bund mit dem HERRN, deinem Gott, und zwar in seine Eidgemeinschaft eintretest, den der HERR, dein Gott, heute mit dir schließt,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 29, 12, 'weil er dich heute zu seinem Volk einsetzen und er dein Gott sein will, wie er dir zugesagt und wie er deinen Vätern Abraham, Isaak und Jakob zugeschworen hat.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 29, 13, 'Aber nicht mit euch allein schließe ich diesen Bund und diesen Fluchvertrag,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 29, 14, 'sondern sowohl mit denen, die heute hier mit uns vor dem HERRN, unserm Gott, stehen, als auch mit denen, die heute noch nicht mit uns hier zugegen sind.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 29, 15, '»Ihr wißt ja selbst, wie wir im Lande Ägypten gewohnt haben und wie wir mitten durch die Völker gezogen sind, die ihr durchzogen habt;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 29, 16, 'und ihr habt ihre Scheusale und Götzen von Holz und Stein, Silber und Gold gesehen, die es bei ihnen gibt.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 29, 17, 'Daß nur ja kein Mann oder Weib, kein Geschlecht oder Stamm sich unter euch befinde, dessen Herz sich heute vom HERRN, unserm Gott, abwendet, daß er hingeht, den Göttern jener Völker zu dienen! Daß sich unter euch nur ja keine Wurzel finde, die Schierling und Wermut als Frucht hervorbringt,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 29, 18, 'niemand, der, wenn er die Worte dieses Fluchvertrags vernimmt, dann sich in seinem Herzen glücklich preist, indem er denkt: ›Gut wird es mir ergehen, wenn ich auch in der Verstocktheit meines Herzens wandle!‹ Das würde zur Folge haben, daß alles, das bewässerte Land mitsamt dem trockenen, hinweggerafft würde.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 29, 19, 'Einem solchen Menschen wird der HERR nicht gewillt sein zu verzeihen, nein, lodern wird alsdann der Zorn und Eifer des HERRN gegen den betreffenden Mann, und alle Flüche, die in diesem Buch aufgezeichnet stehen, werden auf ihn einstürmen, und der HERR wird seinen Namen unter dem Himmel austilgen,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 29, 20, 'und der HERR wird ihn aus allen Stämmen Israels zum Unheil aussondern, wie es allen Flüchen des Bundes entspricht, der in diesem Gesetzbuch aufgezeichnet steht.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 29, 21, 'Die späteren Geschlechter aber, eure Kinder, die nach euch erstehen werden, und die Ausländer, die aus fernen Ländern kommen, werden fragen, wenn sie die Unglücksschläge und Krankheiten sehen, mit denen der HERR dieses Land heimgesucht hat,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 29, 22, 'den Schwefel und das Salz – eine Brandstätte wird sein ganzer Boden sein, so daß er nicht besät werden kann und nichts sprossen läßt und keine Pflanze in ihm aufkommt, eine Verwüstung wie die von Sodom und Gomorrha, Adama und Zeboim, die der HERR in seinem Zorn und Grimm dem Untergang preisgegeben hat –,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 29, 23, 'ja, alle Völker werden fragen: ›Warum hat der HERR diesem Lande solches Geschick widerfahren lassen? Welchen Grund hat diese schreckliche Zornesglut?‹');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 29, 24, 'Dann wird man antworten: ›Das ist die Strafe dafür, daß sie den Bund mit dem HERRN, dem Gott ihrer Väter, verlassen haben, den er mit ihnen geschlossen hatte, als er sie aus dem Lande Ägypten herausführte,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 29, 25, 'und daß sie dazu übergegangen sind, anderen Göttern zu dienen und sich vor ihnen niederzuwerfen, Göttern, die ihnen vorher unbekannt gewesen waren und die er ihnen nicht zugeteilt hatte:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 29, 26, 'darum ist der Zorn des HERRN gegen dieses Land entbrannt, so daß er den ganzen Fluch, der in diesem Buche aufgezeichnet steht, über das Land hat kommen lassen;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 29, 27, 'und darum hat der HERR sie im Zorn und Grimm und in gewaltiger Erbitterung aus ihrem Lande herausgerissen und sie in ein anderes Land geschleudert, wie es heutigentags der Fall ist.‹');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 29, 28, 'Das noch Verborgene steht beim HERRN, unserm Gott, aber das bereits offenbar Gewordene ist für uns und unsere Kinder für alle Ewigkeit bestimmt, damit wir alle Worte dieses Gesetzes erfüllen.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 30, 1, '»Wenn nun alle diese Worte, der Segen und der Fluch, die ich dir vorgetragen habe, (einst) bei dir eintreffen werden und du es unter allen Völkern, unter die der HERR, dein Gott, dich (alsdann) verstoßen hat, dir zu Herzen nehmen wirst');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 30, 2, 'und du samt deinen Kindern von ganzem Herzen und mit ganzer Seele zum HERRN, deinem Gott, zurückkehrst und seinen Weisungen in allem, was ich dir heute gebiete, gehorsam bist:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 30, 3, 'so wird der HERR, dein Gott, dein Geschick wenden und sich deiner erbarmen und wird dich wieder aus all den Völkern sammeln, unter die der HERR, dein Gott, dich zerstreut hat.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 30, 4, 'Wenn deine verstoßenen (Söhne) sich auch am Ende des Himmels befinden sollten, wird der HERR, dein Gott, dich doch von dort sammeln und von dort dich zurückholen;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 30, 5, 'und der HERR, dein Gott, wird dich in das Land zurückbringen, das deine Väter besessen hatten, damit du es wieder in Besitz nimmst, und er wird dich glücklicher und zahlreicher werden lassen, als deine Väter waren.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 30, 6, 'Und der HERR wird dir und deinen Nachkommen das Herz beschneiden, damit du den HERRN, deinen Gott, von ganzem Herzen und mit ganzer Seele liebst um deines Lebens willen;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 30, 7, 'und der HERR, dein Gott, wird alle jene Flüche über deine Feinde und über deine Widersacher hereinbrechen lassen, die dich verfolgt haben.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 30, 8, 'Du aber wirst wieder den Weisungen des HERRN gehorchen und alle seine Gebote befolgen, die ich dir heute zur Pflicht mache.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 30, 9, 'Alsdann wird der HERR, dein Gott, dir Überfluß an Glück bei allem, was du unternimmst, verleihen durch Kindersegen, durch reichen Viehbesitz und reichen Ertrag deiner Felder; denn der HERR wird zu deinem Heil wieder Freude an dir haben, wie er an deinen Vätern Freude gehabt hat,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 30, 10, 'wenn du nämlich den Weisungen des HERRN, deines Gottes, gehorchst, so daß du seine Gebote und Satzungen beobachtest, alles, was in diesem Gesetzbuch aufgezeichnet steht, wenn du dich von ganzem Herzen und mit ganzer Seele zum HERRN, deinem Gott, bekehrst.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 30, 11, '»Denn dieses Gesetz, das ich dir heute gebiete, ist für dich nicht zu schwer und nicht unerreichbar;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 30, 12, 'es ist nicht im Himmel, daß du sagen müßtest: ›Wer wird für uns in den Himmel hinaufsteigen, um es uns zu holen und es uns zu verkündigen, damit wir es befolgen können?‹');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 30, 13, 'Es ist auch nicht jenseits des Meeres, daß du sagen müßtest: ›Wer wird für uns über das Meer hinüberfahren, um es uns zu holen und es uns zu verkündigen, damit wir es befolgen können?‹');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 30, 14, 'Nein, ganz nahe ist dir das Wort: in deinem Munde und in deinem Herzen hast du es, so daß du es befolgen kannst.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 30, 15, '»Bedenke wohl: ich habe dir heute das Leben und das Glück und (andrerseits) den Tod und das Unglück zur Wahl vorgelegt.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 30, 16, 'Was ich dir heute gebiete, ist: den HERRN, deinen Gott, zu lieben, auf seinen Wegen zu wandeln und seine Gebote, seine Satzungen und Verordnungen zu beobachten, damit du am Leben bleibst und zahlreich wirst und der HERR, dein Gott, dich segnet in dem Lande, in das du jetzt einziehst, um es in Besitz zu nehmen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 30, 17, 'Wenn aber dein Herz sich abwendet und du nicht gehorsam bist, sondern dich dazu verführen läßt, andere Götter anzubeten und ihnen zu dienen,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 30, 18, 'so kündige ich euch heute schon an, daß ihr unfehlbar zugrunde gehen werdet: ihr werdet alsdann nicht lange in dem Lande wohnen bleiben, in das du jetzt über den Jordan ziehst, um es in Besitz zu nehmen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 30, 19, 'Ich rufe heute den Himmel und die Erde zu Zeugen gegen euch an: das Leben und den Tod habe ich euch vorgelegt, den Segen und den Fluch. So wähle denn das Leben, damit du am Leben bleibst, du und deine Nachkommen,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 30, 20, 'indem du den HERRN, deinen Gott, liebst, seinen Weisungen gehorchst und fest an ihm hältst; denn davon hängt dein Leben und die Dauer deiner Tage ab, während deren du in dem Lande wohnst, dessen Verleihung der HERR deinen Vätern Abraham, Isaak und Jakob zugeschworen hat.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 31, 1, 'Nun ging Mose daran, folgende Worte an ganz Israel zu richten;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 31, 2, 'er sagte zu ihnen: »Ich bin heute 120 Jahre alt: ich vermag nicht mehr den Anforderungen meines Amtes zu genügen; auch hat der HERR zu mir gesagt: ›Du sollst den Jordan da nicht überschreiten!‹');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 31, 3, 'Der HERR, dein Gott, wird selbst an deiner Spitze hinüberziehen: er selbst wird diese Völker vor dir her vernichten, daß du ihr Land in Besitz nehmen kannst. Josua wird an deiner Spitze hinüberziehen, wie der HERR geboten hat,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 31, 4, 'und der HERR wird mit ihnen verfahren, wie er mit Sihon und Og, den Königen der Amoriter, und mit ihrem Lande verfahren ist, die er vernichtet hat.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 31, 5, 'Wenn der HERR sie aber in eure Gewalt gibt, so sollt ihr mit ihnen genau nach der Weisung verfahren, die ich euch gegeben habe.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 31, 6, 'Seid mutig und stark! Fürchtet euch nicht und seid ohne Angst vor ihnen! Denn der HERR, dein Gott, zieht selbst mit dir: er wird dir seine Hilfe nicht versagen und dich nicht verlassen.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 31, 7, 'Hierauf berief Mose den Josua und sagte zu ihm in Gegenwart aller Israeliten: »Sei mutig und stark! Denn du sollst mit diesem Volk in das Land kommen, dessen Besitz der HERR ihren Vätern zugeschworen hat, und du sollst es als Erbbesitz unter sie verteilen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 31, 8, 'Der HERR selbst aber wird vor dir herziehen; er wird mit dir sein, wird dir seine Hilfe nicht versagen und dich nicht verlassen: fürchte dich nicht und sei ohne Angst!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 31, 9, 'Dann schrieb Mose dieses Gesetz nieder und übergab es den Priestern, den Leviten, welche die Lade mit dem Bundesgesetze des HERRN zu tragen hatten, und allen Ältesten Israels.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 31, 10, 'Mose gab ihnen dabei folgenden Befehl: »Alle sieben Jahre, zur festgesetzten Zeit des Erlaßjahres, am Laubhüttenfeste,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 31, 11, 'wenn ganz Israel sich einfindet, um vor dem HERRN, deinem Gott, an der Stätte zu erscheinen, die er erwählen wird, sollst du dieses Gesetz vor ganz Israel laut vorlesen, so daß alle es hören.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 31, 12, 'Laß das Volk, die Männer, die Frauen und die Kinder, auch die Fremdlinge, die bei dir in deinen Ortschaften wohnen, sich versammeln, damit sie es hören und kennenlernen und den HERRN, euren Gott, fürchten und alle Bestimmungen dieses Gesetzes gewissenhaft befolgen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 31, 13, 'Auch ihre Kinder, die es noch nicht kennen, sollen es hören, damit sie den HERRN, euren Gott, fürchten lernen während der ganzen Zeit, die ihr in dem Lande leben werdet, in das ihr jetzt über den Jordan zieht, um es in Besitz zu nehmen.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 31, 14, 'Hierauf sagte der HERR zu Mose: »Nun ist die Zeit für dich gekommen, daß du sterben mußt. Rufe Josua und tretet in das Offenbarungszelt, damit ich ihn zu seinem Amt bestelle!« Da gingen Mose und Josua hin und traten in das Offenbarungszelt;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 31, 15, 'der HERR aber erschien im Zelte in einer Wolkensäule, und die Wolkensäule blieb am Eingang des Zeltes stehen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 31, 16, 'Da sagte der HERR zu Mose: »Du bist nun im Begriff, dich zu deinen Vätern zu legen; dann wird dieses Volk sich daranmachen, mit den fremden Göttern inmitten des Landes, in das es jetzt einzieht, Abgötterei zu treiben; es wird mich dann verlassen und den Bund mit mir, den ich mit ihnen geschlossen habe, brechen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 31, 17, 'Da wird dann mein Zorn gegen sie zu jener Zeit entbrennen, und ich werde sie verlassen und mein Angesicht vor ihnen verbergen; dann wird es der Vertilgung anheimfallen, und viele Leiden und Drangsale werden es treffen. Da wird es dann zu jener Zeit sagen: ›Haben diese Leiden mich nicht deshalb getroffen, weil mein Gott nicht mehr in meiner Mitte ist?‹');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 31, 18, 'Ich aber will dann zu jener Zeit mein Angesicht gänzlich (vor ihm) verbergen wegen all des Bösen, das dieses Volk verübt hat, indem es sich anderen Göttern zuwandte.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 31, 19, '»Und nun schreibt euch das nachfolgende Lied auf und lehre es die Israeliten; lege es ihnen in den Mund, damit dieses Lied mir zum Zeugnis gegen die Israeliten diene.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 31, 20, 'Denn ich werde sie allerdings in das Land bringen, das ich ihren Vätern zugeschworen habe, (ein Land,) das von Milch und Honig überfließt; aber wenn sie dann essen und satt werden und fett geworden sind, werden sie sich anderen Göttern zuwenden und ihnen dienen, mich aber werden sie verwerfen und den Bund mit mir brechen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 31, 21, 'Wenn dann viele Leiden und Drangsale sie treffen, dann soll dieses Lied – denn es wird im Munde ihrer Nachkommen unvergessen fortleben – Zeugnis gegen sie ablegen, daß ich ihr Sinnen und Trachten, mit dem sie schon heute umgehen, gekannt habe, noch ehe ich sie in das Land habe gelangen lassen, das ich (ihnen) zugeschworen habe.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 31, 22, 'So schrieb denn Mose dieses Lied noch an demselben Tage auf und lehrte es die Israeliten;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 31, 23, 'dem Josua aber, dem Sohne Nuns, erteilte der HERR folgenden Auftrag: »Sei mutig und stark! Denn du sollst die Israeliten in das Land bringen, das ich ihnen zugeschworen habe, und ich selbst will mit dir sein.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 31, 24, 'Als nun Mose dieses Gesetz nach seinem Wortlaut vollständig bis zu Ende in ein Buch geschrieben hatte,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 31, 25, 'gab er den Leviten, welche die Lade mit dem Bundesgesetze des HERRN zu tragen hatten, folgenden Befehl:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 31, 26, '»Nehmt dieses Gesetzbuch und legt es neben die Bundeslade des HERRN, eures Gottes, damit es dort zum Zeugnis gegen euch dient.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 31, 27, 'Denn ich kenne deine Widerspenstigkeit und deine Halsstarrigkeit wohl. Wenn ihr schon jetzt, während ich noch als Lebender unter euch weile, widerspenstig gegen den HERRN gewesen seid: wieviel mehr wird es da nach meinem Tode so sein!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 31, 28, 'Beruft zu einer Versammlung bei mir alle Ältesten eurer Stämme und eure Obmänner, ich will ihnen diese Worte laut vorlesen und den Himmel und die Erde zu Zeugen gegen sie anrufen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 31, 29, 'Denn ich weiß, daß ihr nach meinem Tode ganz verwerflich handeln und von dem Wege abweichen werdet, den ich euch zur Pflicht gemacht habe. So wird denn schließlich das Unglück über euch hereinbrechen, weil ihr tun werdet, was dem HERRN mißfällt, indem ihr ihn durch euer ganzes Tun zum Zorn reizt.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 31, 30, 'Hierauf trug Mose der ganzen Gemeindeversammlung der Israeliten den Wortlaut des folgenden Liedes bis zu Ende vor:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 1, 'Horcht auf, ihr Himmel, denn ich will reden, und die Erde vernehme die Worte meines Mundes!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 2, 'Wie Regen ergieße sich meine Belehrung, wie Tau riesele meine Rede, wie Regenschauer auf junges Grün und wie Regentropfen auf Pflanzen!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 3, 'Denn den Namen des HERRN will ich verkünden: gebt unserm Gott die Ehre!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 4, 'Er ist ein Fels, vollkommen ist sein Tun, denn alle seine Wege sind recht; ein Gott der Treue und ohne Falsch, gerecht und wahrhaftig ist er.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 5, 'Übel haben an ihm gehandelt, die wegen ihrer Verworfenheit nicht seine Söhne sind, ein verderbtes und verkehrtes Geschlecht.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 6, 'Durftest du dem HERRN so vergelten, du törichtes und unverständiges Volk? Ist nicht er dein Vater, der dich geschaffen? Hat nicht er dich gemacht und bereitet?');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 7, 'Gedenke der Tage der Vorzeit, betrachte die Jahre von Geschlecht zu Geschlecht! Frag deinen Vater, der wird dir’s kundtun, deine Greise, die werden dir’s erzählen:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 8, 'Als der Höchste den Völkern ihren Erbbesitz zuteilte, als er die Menschenkinder voneinander schied, da setzte er die Gebiete der Stämme fest nach der Zahl der Kinder Israel.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 9, 'Denn der Anteil des HERRN ist sein Volk, Jakob der Bezirk seines Erbguts.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 10, 'Er fand es im Bereich der Wüste, in der Einöde voll Geheul der Wildnis; er umhegte es schützend, nahm sich seiner an, hütete es wie seinen Augapfel.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 11, 'Wie ein Adler, der seine Brut aus dem Nest hinausführt und über seinen Jungen flatternd schwebt, seine Fittiche über sie breitet, sie aufnimmt, sie trägt auf seinen Schwingen:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 12, 'so leitete der HERR allein das Volk, kein fremder Gott war mit ihm.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 13, 'Er ließ es auf den Höhen der Erde einherfahren, und es aß die Erträgnisse des Gefildes; er ließ es Honig aus Felsen schlürfen und Öl aus Kieselgestein,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 14, 'Sahne von Kühen und Milch vom Kleinvieh, dazu das Fett von Lämmern und Widdern, Sprößlinge von Basan und Böcke samt dem Nierenfett des Weizens; und Traubenblut trankst du, feurigen Wein.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 15, 'Da wurde Jeschurun fett und schlug aus ja, fett wurdest du, wurdest dick, wurdest feist! – und verwarf den Gott, der ihn geschaffen, und verachtete den Felsen seines Heils.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 16, 'Sie reizten ihn zur Eifersucht durch fremde Götter, erbitterten ihn durch greulichen Götzendienst:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 17, 'sie opferten den Dämonen, die nicht Gott sind, Göttern, die (vorher) ihnen unbekannt gewesen, neuen Göttern, die erst vor kurzem aufgekommen waren, die eure Väter nicht verehrt hatten.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 18, 'Des Felsens, der dir das Dasein gegeben, gedachtest du nicht mehr und vergaßest den Gott, dem du das Entstehn verdanktest.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 19, 'Der HERR sah es und verwarf sie voll Unmuts über seine Söhne und Töchter;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 20, 'er sprach: »Ich will mein Angesicht vor ihnen verbergen, will sehen, welches ihr Ausgang sein wird; denn ein Geschlecht voll Verkehrtheit sind sie, Kinder, in denen keine Treue wohnt.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 21, 'Sie haben mich zur Eifersucht gereizt durch Nicht-Götter, mich erbittert durch ihre nichtigen Götzen; so will auch ich sie zur Eifersucht reizen durch ein Nicht-Volk, durch einen unverständigen Volksstamm sie erbittern.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 22, 'Denn ein Feuer ist durch meinen Zorn entbrannt und hat bis in die Tiefen der Unterwelt gelodert; es hat die Erde samt ihrem Ertrag verzehrt und die Grundfesten der Berge in Flammen gesetzt.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 23, 'Ich will Leiden auf sie häufen, meine Pfeile gegen sie verbrauchen:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 24, 'sind sie vor Hunger verschmachtet und von Fieberglut und giftigen Seuchen verzehrt, so will ich den Zahn wilder Tiere gegen sie loslassen samt dem Gift der im Staube kriechenden Schlangen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 25, 'Draußen soll das Schwert sie (der Angehörigen) berauben und drinnen daheim der Schrecken (sie wegraffen), den Jüngling wie die Jungfrau, den Säugling mitsamt dem Graukopf.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 26, 'Ich hätte gesagt: »Zerstreuen will ich sie, ihr Gedächtnis unter den Menschen verschwinden lassen!«,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 27, 'wenn nicht Verdruß ich vom Feinde her fürchtete, daß nämlich ihre Widersacher es falsch deuteten, daß sie sagen möchten: »Unsere Hand hat obgesiegt, und nicht der HERR hat dies alles vollbracht!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 28, 'Denn ein Volk sind sie, dem alle Einsicht abgeht, und kein Verständnis findet sich bei ihnen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 29, 'Wären sie weise, daß sie dies begriffen, so würden sie bedenken, welches ihr Endgeschick sein wird.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 30, 'Wie könnte ein einziger Tausend vor sich hertreiben und zwei Zehntausend in die Flucht schlagen, hätte nicht ihr Fels sie verkauft und der HERR sie preisgegeben?');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 31, 'Denn nicht wie unser Fels ist ihr Fels; das müssen unsere Feinde selbst anerkennen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 32, 'Doch vom Weinstock Sodoms stammt ihr Weinstock und aus den Gefilden Gomorrhas: ihre Trauben sind Gifttrauben, gallenbittre Beeren haben sie;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 33, 'Schlangengeifer ist ihr Wein und grausiges Otterngift.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 34, '»Liegt das nicht bei mir aufbewahrt, versiegelt in meinen Schatzkammern?');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 35, 'Mir steht die Rache und Vergeltung zu für die Zeit, da ihr Fuß wanken wird; denn nahe ist der Tag ihres Verderbens, und eilends kommt das ihnen bestimmte Schicksal heran.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 36, 'Denn der HERR wird sein Volk richten, aber seiner Knechte sich erbarmen, wenn er sieht, daß jeder Halt geschwunden und daß dahin sind Hörige wie Freie.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 37, 'Da wird er sagen: »Wo sind nun ihre Götter, der Fels, auf den sie sich verließen?');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 38, 'Wo sind die, welche das Fett ihrer Schlachtopfer aßen, den Wein ihrer Gußopfer tranken? Sie mögen auftreten und euch helfen, damit sie euer Schirm sind!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 39, 'Erkennet jetzt, daß ich allein es bin und neben mir kein andrer Gott besteht! Ich bin’s, der tötet und lebendig macht, ich verwunde, aber heile auch wieder, und niemand kann aus meiner Hand erretten!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 40, 'Nun denn, ich erhebe meine Hand zum Himmel und gelobe: So wahr ich ewig lebe:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 41, 'Hab’ ich mein blitzendes Schwert geschärft und hat meine Hand zum Gericht gegriffen, so werde ich Rache an meinen Feinden nehmen und denen vergelten, die mich hassen!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 42, 'Meine Pfeile will ich mit Blut trunken machen und mein Schwert soll Fleisch fressen – mit dem Blut der Erschlagnen und Gefangnen, vom Haupt der Fürsten des Feindes!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 43, 'Jubelt, ihr Heidenvölker, über sein Volk! denn er wird das Blut seiner Knechte rächen und Rache an seinen Bedrängern nehmen und entsünd’gen sein Land, sein Volk.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 44, 'Mose ging dann hin und trug den ganzen Wortlaut dieses Liedes dem Volke laut vor, er und Hosea, der Sohn Nuns.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 45, 'Als Mose aber dieses ganze Lied allen Israeliten bis zu Ende vorgetragen hatte,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 46, 'sagte er zu ihnen: »Beherzigt all diese Worte, die ich euch heute feierlich ans Herz lege! Ihr sollt sie euren Kindern einprägen, damit sie auf die sorgfältige Beobachtung aller Bestimmungen dieses Gesetzes bedacht sind;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 47, 'denn es ist kein bedeutungsloses Wort für euch, sondern euer Leben hängt davon ab, und durch die Beobachtung dieses Wortes werdet ihr ein langes Bestehen in dem Lande gewinnen, in das ihr jetzt über den Jordan zieht, um es in Besitz zu nehmen.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 48, 'An demselben Tage aber sagte der HERR zu Mose:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 49, '»Steige auf das Gebirge Abarim hier, auf den Berg Nebo, der im Lande der Moabiter, Jericho gegenüber, liegt, und sieh dir das Land Kanaan an, das ich den Israeliten zum Eigentum geben will.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 50, 'Dann sollst du auf dem Berge, auf den du hinaufsteigen wirst, sterben und zu deinen Stammesgenossen versammelt werden, wie dein Bruder Aaron auf dem Berge Hor gestorben und zu seinen Stammesgenossen versammelt worden ist.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 51, 'Denn ihr habt euch inmitten der Israeliten am Haderwasser von Kades in der Wüste Zin treulos gegen mich erwiesen, weil ihr inmitten der Israeliten mir nicht als dem Heiligen die Ehre gegeben habt.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 52, 'Denn nur gegenüber sollst du in das Land, das ich den Israeliten geben will, hineinsehen, aber nicht in das Land selbst hineinkommen!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 33, 1, 'Dies ist der Segen, den Mose, der Mann Gottes, über die Israeliten vor seinem Tode ausgesprochen hat.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 33, 2, 'Er sprach (damals): »Der HERR kam vom Sinai her und erschien seinem Volk von Seir her in strahlendem Glanz; er ließ sein Licht vom Gebirge Paran leuchten und kam aus der Mitte heiliger Zehntausend-Scharen; zu seiner Rechten war loderndes Feuer für sie.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 33, 3, 'Ja, er umgab mit Liebe die Stämme; alle seine Heiligen sind in seiner Hand; sie waren gelagert längs deiner Bahn, so daß jeder etwas von deinen Aussprüchen empfing.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 33, 4, 'Das Gesetz hat Mose uns verordnet als Erbbesitz der Gemeinde Jakobs.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 33, 5, 'So ist er denn König in Jeschurun geworden, als die Häupter des Volks sich versammelten, die Stämme Israels allzumal.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 33, 6, '»Ruben lebe, er sterbe nicht, und seine Mannen seien eine Anzahl!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 33, 7, 'Und dies ist der Segen für Juda, und zwar sagte er: »Erhöre, HERR, die Stimme Judas und bring ihn zurück zu seinem Volk mit seinen Händen hat er ja für es gestritten – und sei ihm Hilfe wider seine Feinde!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 33, 8, 'Und von Levi sagte er: »Dein Recht-Orakel und dein Licht-Orakel gehört den Männern deines Getreuen, den du bei Massa versucht hast, für den du an den Wassern von Meriba gestritten hast,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 33, 9, 'jenen Männern, die von Vater und Mutter sagten: ›Ich kenne sie nicht!‹ und die ihre Brüder nicht ansahn, von ihren Kindern nichts wissen wollten; denn sie bewahrten dein Gebot und hielten an deinem Bunde fest.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 33, 10, 'Sie sollen Jakob deine Verordnungen lehren und Israel dein Gesetz; sie sollen Weihrauchduft zum Einatmen vor dich bringen und Ganzopfer auf deinen Altar.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 33, 11, 'Segne, HERR, seine Kraft und laß dir das Tun seiner Hände gefallen! Zerschmettre seinen Gegnern die Hüften und seinen Widersachern, daß sie nicht mehr aufstehn!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 33, 12, 'Von Benjamin sagte er: »Als Liebling des HERRN wird er in Ruhe bei ihm wohnen; er beschirmt ihn allezeit und wohnt zwischen seinen Schultern.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 33, 13, 'Und von Joseph sagte er: »Gesegnet vom HERRN ist sein Land mit der köstlichsten Himmelsgabe, mit Tau, und mit der Wasserflut, die drunten lagert;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 33, 14, 'mit dem Köstlichsten, was die Sonne hervorbringt, und dem Köstlichsten, was die Monde sprossen lassen;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 33, 15, 'mit dem Besten, was vom Gipfel der uralten Berge kommt, und dem Köstlichsten der ewigen Hügel;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 33, 16, 'mit dem Köstlichsten der Erde und ihrer Fülle! Und das Wohlgefallen dessen, der im Dornbusch wohnte, das möge kommen auf das Haupt Josephs und auf den Scheitel des Geweihten unter seinen Brüdern!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 33, 17, 'Ein erstgeborener Stier ist er – etwas Herrliches, und seine Hörner sind die eines Wildochsen; mit ihnen stößt er Völker nieder, allesamt die Enden der Erde. So sind die Zehntausende Ephraims und so die Tausende Manasses.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 33, 18, 'Und von Sebulon sagte er: »Freue dich, Sebulon, deiner Meerfahrten und du, Issaschar, deiner Zelte!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 33, 19, 'Sie laden Völker ein auf den Berg, dort opfern sie rechte Opfer; denn den Reichtum der Meere saugen sie ein und die verborgensten Schätze des Sandes.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 33, 20, 'Und von Gad sagte er: »Gepriesen sei der HERR, der Gad weiten Raum schafft! Wie eine Löwin hat er sich gelagert und zerfleischt Arm und Schädel.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 33, 21, 'Er hat sich das Erstlingsgebiet ersehen; denn dort ward ihm sein Anteil vom Anführer bestimmt. Doch ist er zu den Häuptern des Volks gekommen, hat die Gerechtigkeit des HERRN vollstreckt und seine Strafgerichte gemeinsam mit Israel.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 33, 22, 'Und von Dan sagte er: »Dan ist ein junger Löwe, der aus Basan hervorstürmt.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 33, 23, 'Und von Naphthali sagte er: »Naphthali ist gesättigt mit Glück und reichlich bedacht mit dem Segen des HERRN; Meer und Südland nimm in Besitz!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 33, 24, 'Und von Asser sagte er: »Der gesegnetste unter den Söhnen sei Asser! Er sei der Liebling seiner Brüder und tauche seinen Fuß in Öl!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 33, 25, 'Von Eisen und Erz seien deine Riegel, und solange du lebst, währe deine Ruhe!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 33, 26, '»Keiner ist dem Gott Jeschuruns gleich, der über den Himmel dahinfährt als dein Helfer und in seiner Hoheit auf den Wolken.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 33, 27, 'Eine Zuflucht für dich ist der Gott der Urzeit, und unter dir sind ewige Arme ausgebreitet; er hat den Feind vor dir her vertrieben und dir geboten: ›Vertilge!‹');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 33, 28, 'So wohnt denn Israel in Sicherheit, abgesondert für sich der Quell Jakobs in einem Land voll Korn und Wein, und sein Himmel träufelt Tau.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 33, 29, 'Heil dir, Israel! Wer ist dir gleich? Ein Volk, gerettet durch den HERRN! Er ist der Schild, der dich schirmt, und das Schwert, das dir Ruhm verschafft; deine Feinde müssen dir huldigen, du aber schreitest dahin auf ihren Höhen!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 34, 1, 'Als Mose dann aus den Steppen der Moabiter auf den Berg Nebo, den Gipfel des Pisga, der Jericho gegenüber liegt, gestiegen war, ließ der HERR ihn das ganze Land sehen: Gilead bis nach Dan');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 34, 2, 'und ganz Naphthali, das Land Ephraim und Manasse und die ganze Landschaft Juda bis an das westliche Meer');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 34, 3, 'sowie das Südland und die Jordan-Aue, die Tiefebene der Palmenstadt Jericho bis nach Zoar.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 34, 4, 'Hierauf sagte der HERR zu ihm: »Dies ist das Land, das ich Abraham, Isaak und Jakob zugeschworen habe mit den Worten: ›Deiner Nachkommenschaft will ich es geben!‹ Ich habe es dich mit eigenen Augen sehen lassen, aber hinüber sollst du nicht kommen!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 34, 5, 'So starb denn dort Mose, der Knecht des HERRN, im Lande der Moabiter nach dem Befehl des HERRN;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 34, 6, 'und er begrub ihn im Tal im Lande der Moabiter, Beth-Peor gegenüber; aber niemand kennt sein Grab bis auf den heutigen Tag.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 34, 7, 'Mose war bei seinem Tode hundertundzwanzig Jahre alt; seine Augen waren nicht schwach geworden, und seine Rüstigkeit war nicht geschwunden.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 34, 8, 'Die Israeliten beweinten Mose in den Steppen der Moabiter dreißig Tage lang, bis die Tage des Weinens in der Trauer um ihn zu Ende waren.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 34, 9, 'Josua aber, der Sohn Nuns, war mit dem Geist der Weisheit erfüllt, denn Mose hatte ihm die Hände fest aufgelegt; daher gehorchten ihm die Israeliten und taten, wie der HERR dem Mose geboten hatte.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 34, 10, 'Es ist aber hinfort kein Prophet mehr in Israel aufgestanden wie Mose, mit dem der HERR von Angesicht zu Angesicht verkehrt hätte;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 34, 11, '(keiner ist mit ihm zu vergleichen) hinsichtlich aller der Zeichen und Wunder, die der HERR ihn als seinen Gesandten in Ägypten am Pharao und all seinen Dienern und an seinem ganzen Lande hat vollführen lassen,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 34, 12, 'und hinsichtlich aller Erweise von gewaltiger Kraft und hinsichtlich aller erstaunlichen Großtaten, die Mose vor den Augen von ganz Israel vollbracht hat.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 1, 1, 'Nach dem Tode Moses, des Knechtes des HERRN, sagte der HERR zu Josua, dem Sohne Nuns, dem Diener Moses:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 1, 2, '»Mein Knecht Mose ist tot; so mache du dich nun auf und ziehe über den Jordan dort, du und das ganze Volk da, in das Land hinüber, das ich ihnen, den Israeliten, geben will.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 1, 3, 'Allen Grund und Boden, auf den eure Fußsohle treten wird, gebe ich euch, wie ich es Mose zugesagt habe.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 1, 4, 'Von der Wüste und dem Libanon dort bis an den großen Strom, den Euphratstrom, das ganze Land der Hethiter, bis zu dem großen Meer im Westen soll euer Gebiet reichen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 1, 5, 'Niemand soll vor dir standhalten können, solange du lebst: wie ich mit Mose gewesen bin, so will ich auch mit dir sein; ich will dir meine Hilfe nicht entziehen und dich nicht verlassen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 1, 6, 'Sei mutig und stark! Denn du sollst diesem Volk das Land als Erbe austeilen, dessen Verleihung ich ihren Vätern zugeschworen habe.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 1, 7, 'Nur sei stark und fest entschlossen, auf die Beobachtung aller Weisungen des Gesetzes bedacht zu sein, das mein Knecht Mose dir zur Pflicht gemacht hat; weiche davon weder nach rechts noch nach links ab, damit du bei allen deinen Unternehmungen glücklichen Erfolg hast.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 1, 8, 'Höre nicht auf, von diesem Gesetzbuch zu reden, und sinne Tag und Nacht darüber nach, damit du auf die Beobachtung alles dessen, was darin geschrieben steht, bedacht bist; denn alsdann wirst du glücklichen Erfolg bei deinen Unternehmungen haben, und alsdann wird dir alles gelingen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 1, 9, 'Ich habe dir also zur Pflicht gemacht: Sei stark und entschlossen! Habe keine Angst und verzage nicht! Denn mit dir ist der HERR, dein Gott, bei allem, was du unternimmst.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 1, 10, 'Da gab Josua den Obmännern des Volkes folgenden Befehl:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 1, 11, '»Geht hin und her im Lager und gebt dem Volke folgenden Befehl: ›Versorgt euch mit Lebensmitteln! Denn (schon) in drei Tagen werdet ihr über den Jordan dort ziehen, um in den Besitz des Landes zu kommen, das der HERR, euer Gott, euch zum Eigentum geben will.‹«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 1, 12, 'Zu den Stämmen Ruben und Gad und dem halben Stamm Manasse aber sagte Josua:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 1, 13, '»Denkt an das Wort, das Mose, der Knecht des HERRN, euch zur Pflicht gemacht hat, als er sagte: ›Der HERR, euer Gott, hat euch ans Ziel gelangen lassen und euch dieses Land gegeben.‹');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 1, 14, 'Eure Frauen, eure kleinen Kinder und euer Vieh mögen in dem Lande bleiben, das euch Mose auf dieser Seite des Jordans angewiesen hat; ihr aber, alle kriegstüchtigen Männer, müßt kampfgerüstet an der Spitze eurer Brüder hinüberziehen und ihnen Beistand leisten,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 1, 15, 'bis der HERR eure Brüder ebenso wie euch ans Ziel gebracht hat und auch sie das Land in Besitz genommen haben, das der HERR, euer Gott, ihnen geben will. Alsdann sollt ihr in euer eigenes Land zurückkehren und es als Besitz innehaben, das Mose, der Knecht des HERRN, euch im Ostjordanlande angewiesen hat.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 1, 16, 'Da gaben sie dem Josua folgende Antwort: »Alles, was du uns befohlen hast, wollen wir tun, und wohin du uns auch sendest, dahin wollen wir gehen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 1, 17, 'Ganz so, wie wir Mose gehorcht haben, wollen wir auch dir gehorchen. Nur möge der HERR, dein Gott, mit dir sein, wie er mit Mose gewesen ist!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 1, 18, 'Jeder, der sich deinen Befehlen widersetzt und deinen Anordnungen nicht gehorcht, sooft du uns etwas gebietest, soll mit dem Tode bestraft werden. Nur sei stark und entschlossen!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 2, 1, 'Hierauf sandte Josua, der Sohn Nuns, von Sittim aus heimlich zwei Männer als Kundschafter aus mit der Weisung: »Geht hin, seht euch das Land und besonders Jericho an!« Da machten sie sich auf den Weg und kamen in das Haus einer Dirne namens Rahab und legten sich dort schlafen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 2, 2, 'Als nun dem König von Jericho die Meldung zuging: »Wisse wohl: es sind heute abend einige Männer von den Israeliten hierher gekommen, um das ganze Land auszukundschaften«,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 2, 3, 'da sandte der König von Jericho zu Rahab und ließ ihr sagen: »Gib die Männer heraus, die zu dir gekommen und in deinem Hause eingekehrt sind; denn sie sind hergekommen, um das ganze Land auszukundschaften.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 2, 4, 'Das Weib aber hatte die beiden Männer genommen und sie versteckt und sagte nun: »Jawohl, die Männer sind bei mir gewesen, aber ich wußte nicht, woher sie waren;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 2, 5, 'und als nun das Stadttor beim Dunkelwerden geschlossen werden sollte, sind die Männer weggegangen; ich weiß nicht, wohin die Männer sich begeben haben. Jagt ihnen schnell nach; denn ihr könnt sie noch einholen.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 2, 6, 'Sie hatte sie jedoch auf das Dach hinaufgeführt und sie dort unter Flachsbündeln versteckt, die sie sich auf dem Dache aufgeschichtet hatte.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 2, 7, 'Die Männer verfolgten sie nun in der Richtung nach dem Jordan hin bis zu den Furten; das Stadttor aber schloß man, sobald die zur Verfolgung ausgesandten Leute draußen waren.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 2, 8, 'Bevor aber jene sich schlafen legten, stieg das Weib zu ihnen auf das Dach hinauf');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 2, 9, 'und sagte zu den Männern: »Ich weiß, daß der HERR euch das Land verliehen und daß uns ein Schrecken vor euch befallen hat, so daß alle Bewohner des Landes verzagt vor euch sind.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 2, 10, 'Denn wir haben davon gehört, daß der HERR bei eurem Auszug aus Ägypten das Wasser im Schilfmeer vor euch hat vertrocknen lassen und wie ihr mit den beiden Königen der Amoriter jenseits des Jordans, mit Sihon und Og, verfahren seid, an denen ihr den Bann vollstreckt habt.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 2, 11, 'Als wir das vernahmen, ist uns alles Vertrauen entschwunden, und niemand hat euch gegenüber noch Mut behalten; denn der HERR, euer Gott, ist Gott im Himmel oben und auf der Erde unten.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 2, 12, 'Und nun schwört mir doch beim HERRN, daß, weil ich euch Gutes erwiesen habe, auch ihr meines Vaters Hause Gutes erweisen wollt, und gebt mir ein sicheres Zeichen,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 2, 13, 'daß ihr meine Eltern und meine Geschwister samt allen ihren Angehörigen am Leben lassen und uns vor dem Tode retten wollt.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 2, 14, 'Da antworteten ihr die Männer: »Wir bürgen mit unserem Leben für das eurige! Wenn ihr an dieser unserer Verabredung nicht zu Verrätern werdet, so wollen wir, wenn der HERR uns das Land gibt, dir Liebe und Treue widerfahren lassen!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 2, 15, 'Hierauf ließ sie die beiden an einem Seil durch das Fenster hinunter; denn ihr Haus war an die Stadtmauer angebaut, weil sie an der Stadtmauer wohnte.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 2, 16, 'Dann sagte sie zu ihnen: »Geht ins Gebirge, sonst könnten die Verfolger euch begegnen, und haltet euch dort drei Tage lang verborgen, bis die Verfolger zurückgekehrt sind; alsdann könnt ihr eures Weges ziehen.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 2, 17, 'Da sagten die Männer zu ihr: »Wir werden uns dieses Eides entledigen, den du uns hast schwören lassen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 2, 18, 'Wisse wohl: wenn wir ins Land kommen, mußt du diese purpurrote Schnur am Fenster befestigen, durch das du uns hinuntergelassen hast, und mußt deine Eltern und Geschwister, überhaupt alle zu deines Vaters Haus Gehörenden bei dir in deinem Hause versammeln.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 2, 19, 'Jeder, der dann aus der Tür deines Hauses auf die Straße hinausgeht, ist selbst für sein Leben verantwortlich, während wir frei von Schuld sind; wer aber bei dir im Hause sein wird, für dessen Leben tragen wir die Verantwortung, wenn Hand an ihn gelegt wird.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 2, 20, 'Auch wenn du treulos gegen diese unsere Verabredung handelst, sind wir des dir geleisteten Eides ledig, den du uns hast schwören lassen.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 2, 21, 'Sie antwortete: »Wie ihr gesagt habt, so soll es abgemacht sein!« Dann ließ sie sie gehen, und sie entfernten sich; sie aber knüpfte die Purpurschnur an das Fenster.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 2, 22, 'Als jene nun weggegangen und in das Gebirge gekommen waren, blieben sie dort drei Tage, bis die Verfolger zurückgekehrt waren; diese hatten (nämlich) bei der Verfolgung überall auf dem Wege nach ihnen gesucht, aber sie nicht gefunden.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 2, 23, 'Nun traten die beiden Männer den Heimweg an, stiegen vom Gebirge hinab, setzten über den Jordan und begaben sich zu Josua, dem Sohne Nuns, dem sie alles erzählten, was ihnen begegnet war.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 2, 24, 'Sie berichteten aber dem Josua: »Der HERR hat das ganze Land in unsere Gewalt gegeben; auch sind alle Bewohner des Landes vor uns verzagt.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 3, 1, 'Darauf ließ Josua am andern Morgen früh aufbrechen, und sie kamen von Sittim an den Jordan, er mit allen Israeliten; und sie blieben dort über Nacht, ehe sie hinüberzogen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 3, 2, 'Nach drei Tagen aber gingen die Obmänner im ganzen Lager hin und her');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 3, 3, 'und gaben dem Volke folgenden Befehl: »Sobald ihr die Bundeslade des HERRN, eures Gottes, erblickt, wie sie von den levitischen Priestern aufgehoben wird, so brecht auch ihr von eurem Standort auf und zieht hinter ihr her;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 3, 4, 'doch muß zwischen euch und ihr ein Abstand von etwa zweitausend Ellen bleiben – ihr dürft ihr nicht zu nahe kommen –, damit ihr den Weg wisset, den ihr einzuschlagen habt; denn ihr seid bisher noch nie auf solchem Wege gezogen.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 3, 5, 'Weiter befahl Josua dem Volke: »Heiligt euch, denn morgen wird der HERR Wunder unter euch tun!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 3, 6, 'Dann gab Josua den Priestern die Weisung: »Hebt die Bundeslade auf und zieht vor dem Volke her hinüber!« Da hoben sie die Bundeslade auf und zogen vor dem Volke einher.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 3, 7, 'Der HERR aber sagte zu Josua: »Heute will ich anfangen, dich in den Augen von ganz Israel groß zu machen, damit sie erkennen, daß ich mit dir sein werde, wie ich mit Mose gewesen bin.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 3, 8, 'Gib du nun den Priestern, welche die Bundeslade tragen, folgenden Befehl: ›Wenn ihr beim Jordan an den Rand des Wassers gekommen seid, so bleibt am Jordan stehen!‹«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 3, 9, 'Dann sagte Josua zu den Israeliten: »Tretet herzu und vernehmt die Worte des HERRN, eures Gottes!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 3, 10, 'Dann hielt Josua folgende Ansprache: »Daran sollt ihr erkennen, daß ein lebendiger Gott in eurer Mitte ist und daß er die Kanaanäer, Hethiter, Hewiter, Pherissiter, Girgasiter, Amoriter und Jebusiter gewißlich vor euch her vertreiben wird:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 3, 11, 'sehet, die Bundeslade des Herrn der ganzen Erde wird vor euch her durch den Jordan ziehen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 3, 12, 'So wählt euch nun zwölf Männer aus den Stämmen Israels, aus jedem Stamm einen Mann.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 3, 13, 'Sobald dann die Fußsohlen der Priester, welche die Lade Gottes, des Herrn der ganzen Erde, tragen, in das Wasser des Jordans eintauchen, wird das Wasser des Jordans, nämlich das Wasser, das von oben her zufließt, auf einmal von dem übrigen Wasser abgeschnitten werden und wie ein einziger Damm stehenbleiben.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 3, 14, 'Als nun das Volk aus seinen Zelten aufbrach, um über den Jordan zu ziehen, indem die Priester die Bundeslade vor dem Volke her trugen,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 3, 15, 'und als die Träger der Lade an den Jordan kamen und die Füße der Priester, der Träger der Lade, in den Rand des Wassers eintauchten – der Jordan ist aber während der ganzen Erntezeit vollströmend bis über alle seine Ufer hinaus –,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 3, 16, 'da blieb das von oben her zufließende Wasser stehen: es erhob sich wie ein einziger Damm in weiter Entfernung bei der Ortschaft Adam, die seitwärts von Zarthan liegt; dagegen das nach dem Steppensee, dem Toten Meer, hinabfließende Wasser verlief sich völlig. So zog denn das Volk hindurch, Jericho gegenüber.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 3, 17, 'Die Priester aber, welche die Bundeslade des HERRN trugen, standen festen Fußes mitten im Jordan auf trockenem Boden, während ganz Israel trockenen Fußes hindurchzog, bis das ganze Volk den Übergang über den Jordan vollständig bewerkstelligt hatte.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 4, 1, 'Als nun das ganze Volk den Übergang über den Jordan vollständig bewerkstelligt hatte, gebot der HERR dem Josua folgendes:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 4, 2, '»Wählt euch aus dem Volke zwölf Männer, aus jedem Stamme einen Mann,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 4, 3, 'und erteilt ihnen folgenden Befehl: ›Nehmt euch von hier, aus der Mitte des Jordans, von der Stelle, wo die Füße der Priester festgestanden haben, zwölf Steine auf, schafft sie mit euch hinüber und legt sie auf dem Lagerplatz nieder, wo ihr diese Nacht zubringen werdet.‹«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 4, 4, 'Da berief Josua die zwölf Männer, die er aus den Israeliten hatte wählen lassen, aus jedem Stamme einen Mann,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 4, 5, 'und befahl ihnen: »Geht hin vor die Lade des HERRN, eures Gottes, mitten in den Jordan hinein und ladet euch ein jeder einen Stein auf seine Schulter, entsprechend der Zahl der israelitischen Stämme,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 4, 6, 'damit dies ein Wahrzeichen unter euch werde! Wenn dann eure Kinder euch künftig fragen: ›Was haben diese Steine für euch zu bedeuten?‹,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 4, 7, 'so sollt ihr ihnen antworten: ›Daß das Wasser des Jordans vor der Bundeslade des HERRN zu fließen aufgehört hat; als die durch den Jordan zog, hat das Wasser des Jordans zu fließen aufgehört; deshalb sollen diese Steine für die Israeliten ein ewiges Denkmal sein!‹«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 4, 8, 'Da taten die Israeliten so, wie Josua befohlen hatte: sie hoben zwölf Steine mitten aus dem Jordan auf, wie der HERR dem Josua geboten hatte, entsprechend der Zahl der israelitischen Stämme, nahmen sie mit sich nach dem Platze des Nachtlagers hinüber und legten sie dort nieder.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 4, 9, 'Zwölf andere Steine aber ließ Josua mitten im Jordan an der Stelle aufrichten, wo die Füße der Priester, welche die Bundeslade trugen, gestanden hatten; dort befinden sie sich noch heutigen Tages.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 4, 10, 'Die Priester aber, welche die Lade trugen, blieben mitten im Jordan stehen, bis alle Arbeit ausgeführt war, die Josua nach dem Befehl des HERRN dem Volk geboten hatte, genau so, wie Mose dem Josua geboten hatte; und das Volk zog eilends hinüber.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 4, 11, 'Als dann das ganze Volk den Übergang vollständig bewerkstelligt hatte, zog auch die Lade des HERRN hinüber und die Priester angesichts des Volkes.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 4, 12, 'Es waren aber die Stämme Ruben und Gad und der halbe Stamm Manasse kampfgerüstet an der Spitze der Israeliten hinübergezogen, wie Mose ihnen geboten hatte.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 4, 13, 'In der Zahl von etwa vierzigtausend kampfgerüsteten Männern waren sie vor dem HERRN her zum Kampf in die Steppen von Jericho hinübergezogen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 4, 14, 'An jenem Tage machte der HERR den Josua groß in den Augen von ganz Israel, so daß sie Ehrfurcht vor ihm hatten während seines ganzen Lebens, wie sie vor Mose Ehrfurcht gehabt hatten.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 4, 15, 'Hierauf gebot der HERR dem Josua folgendes:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 4, 16, '»Befiehl den Priestern, welche die Gesetzeslade tragen, aus dem Jordan heraufzusteigen.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 4, 17, 'Da gab Josua den Priestern den Befehl: »Steigt aus dem Jordan herauf!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 4, 18, 'Als nun die Priester, welche die Bundeslade des HERRN trugen, aus dem Jordan heraufgestiegen waren und die Fußsohlen der Priester kaum das trockene Ufer betreten hatten, da kehrte das Wasser des Jordans in sein Bett zurück und ergoß sich wie früher überall über seine Ufer.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 4, 19, 'Das Volk war aber aus dem Jordan am zehnten Tage des ersten Monats heraufgestiegen und lagerte in Gilgal an der Ostgrenze des Gebiets von Jericho.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 4, 20, 'Da ließ Josua jene zwölf Steine, die sie aus dem Jordan mitgebracht hatten, in Gilgal aufrichten');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 4, 21, 'und sagte dabei zu den Israeliten: »Wenn eure Kinder künftig an ihre Väter die Frage richten: ›Was haben diese Steine zu bedeuten?‹,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 4, 22, 'so gebt euren Kindern folgende Auskunft: ›Trockenen Fußes ist Israel hier durch den Jordan gezogen,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 4, 23, 'weil der HERR, euer Gott, das Wasser des Jordans vor euch her hat vertrocknen lassen, bis ihr hindurchgezogen wart, ebenso wie der HERR, euer Gott, es mit dem Schilfmeer gemacht hat, das er vor uns hat vertrocknen lassen, bis wir hindurchgezogen waren;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 4, 24, 'denn alle Völker der Erde sollten erkennen, daß die Hand des HERRN stark ist, damit ihr den HERRN, euren Gott, allezeit fürchtet.‹«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 5, 1, 'Als nun alle Könige der Amoriter, die jenseits des Jordans nach Westen hin wohnten, und alle Könige der Kanaanäer an der Meeresküste die Kunde erhielten, daß der HERR das Wasser des Jordans vor den Israeliten hatte vertrocknen lassen, bis sie hinübergezogen waren, da schwand ihnen alles Vertrauen, und sie hatten den Israeliten gegenüber keinen Mut mehr.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 5, 2, 'Damals gebot der HERR dem Josua: »Fertige dir Steinmesser an und beschneide wiederum die Israeliten zum zweitenmal!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 5, 3, 'Da machte sich Josua Steinmesser und beschnitt mit ihnen die Israeliten am Hügel Araloth.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 5, 4, 'Der Grund aber, weshalb Josua die Beschneidung vornahm, war folgender: Das gesamte Volk männlichen Geschlechts, das aus Ägypten ausgezogen war, alle Kriegsleute, waren nach ihrem Auszug aus Ägypten während der Wanderung in der Wüste gestorben.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 5, 5, 'Das ganze Volk nämlich, welches auszog, war beschnitten gewesen; aber das gesamte Volk, das nach dem Auszug aus Ägypten während der Wanderung in der Wüste geboren war, hatte die Beschneidung nicht empfangen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 5, 6, 'Denn vierzig Jahre lang waren die Israeliten in der Wüste gewandert, bis die Gesamtheit der Kriegsleute nach dem Auszug aus Ägypten weggestorben war, weil sie den Weisungen des HERRN nicht nachgekommen waren; deshalb hatte der HERR ihnen geschworen, er wolle sie das Land nicht sehen lassen, das er uns, wie er ihren Vätern zugeschworen hatte, geben wollte, ein Land, das von Milch und Honig überfließt.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 5, 7, 'Aber ihre Söhne, die der HERR an ihrer Statt hatte aufwachsen lassen, diese beschnitt jetzt Josua; denn sie waren unbeschnitten geblieben, weil man sie während der Wanderung nicht beschnitten hatte.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 5, 8, 'Als nun die Beschneidung am ganzen Volke vorgenommen worden war, blieben sie an Ort und Stelle gelagert, bis sie genesen waren.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 5, 9, 'Der HERR aber sagte zu Josua: »Heute habe ich die ägyptische Schmach von euch abgewälzt.« Daher heißt dieser Ort Gilgal bis auf den heutigen Tag.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 5, 10, 'Während nun die Israeliten in Gilgal gelagert waren, feierten sie das Passah am vierzehnten Tage des Monats am Abend in den Steppen von Jericho');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 5, 11, 'und aßen am anderen Tage nach dem Passah von den Erzeugnissen des Landes, nämlich ungesäuertes Brot und geröstetes Getreide, an eben diesem Tage.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 5, 12, 'Da hörte am folgenden Morgen das Manna auf, weil sie jetzt von den Erzeugnissen des Landes zu essen hatten, und es gab hinfort für die Israeliten kein Manna mehr, sondern sie nährten sich in jenem Jahre von den Erzeugnissen des Landes Kanaan.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 5, 13, 'Während sich nun Josua bei Jericho befand, begab es sich, daß er seine Augen aufschlug und einen Mann, der ein gezücktes Schwert in der Hand hatte, sich gegenüber stehen sah. Josua ging auf ihn zu und fragte ihn: »Gehörst du zu uns oder zu unsern Feinden?«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 5, 14, 'Da antwortete er: »Nein, sondern ich bin der Oberste des Heeres des HERRN; soeben bin ich gekommen.« Da warf sich Josua auf sein Angesicht nieder, um ihm zu huldigen, und fragte ihn dann: »Was hat mein Herr seinem Knecht zu sagen?«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 5, 15, 'Da antwortete der Heeresoberste des HERRN dem Josua: »Ziehe dir die Schuhe aus von deinen Füßen! Denn die Stätte, auf der du stehst, ist heilig.« Da tat Josua so.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 6, 1, 'Jericho aber hatte (seine Tore) geschlossen und blieb den Israeliten gegenüber verriegelt, so daß niemand aus- oder eingehen konnte.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 6, 2, 'Da sagte der HERR zu Josua: »Hiermit gebe ich Jericho und seinen König samt den streitbaren Männern in deine Gewalt.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 6, 3, 'So zieht denn um die Stadt herum, alle Kriegsleute, einmal rings um die Stadt her. So sollst du es sechs Tage lang tun;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 6, 4, 'dabei sollen sieben Priester sieben Lärmposaunen vor der Lade her tragen. Am siebten Tage aber sollt ihr siebenmal um die Stadt herumziehen, und die Priester sollen dabei in die Posaunen stoßen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 6, 5, 'Wenn man dann ein Zeichen mit dem Lärmhorn gibt, soll das gesamte Volk, sobald ihr den Posaunenschall hört, ein lautes Kriegsgeschrei erheben; dann wird die Stadtmauer von selbst in sich zusammenstürzen, und das Volk soll sie ersteigen, wo ein jeder gerade steht.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 6, 6, 'Darauf berief Josua, der Sohn Nuns, die Priester und befahl ihnen: »Hebt die Bundeslade auf, und sieben Priester sollen sieben Lärmposaunen vor der Lade des HERRN her tragen!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 6, 7, 'Hierauf befahl er dem Volk: »Zieht rings um die Stadt herum, und zwar sollen die Gewappneten vor der Lade des HERRN her ziehen!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 6, 8, 'Als nun Josua dem Volk diesen Befehl erteilt hatte, da setzten sich die sieben Priester in Bewegung, welche die sieben Lärmposaunen vor dem HERRN her trugen, und stießen in die Posaunen, während die Bundeslade des HERRN ihnen nachfolgte;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 6, 9, 'die Gewappneten aber zogen vor den Priestern einher, die in die Posaunen stießen, und die Nachhut zog hinter der Lade her, während man dabei fortwährend in die Posaunen stieß.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 6, 10, 'Dem Volk aber hatte Josua streng geboten: »Ihr dürft kein Kriegsgeschrei erheben und eure Stimme nicht hören lassen, und kein Wort darf aus eurem Munde kommen bis zu dem Tage, an dem ich euch zurufe: ›Laßt ein Geschrei erschallen!‹ Dann müßt ihr das Kriegsgeschrei erheben.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 6, 11, 'So ließ er denn die Lade des HERRN einmal den Umzug rings um die Stadt machen; hierauf begaben sie sich wieder ins Lager und blieben über Nacht im Lager. –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 6, 12, 'Am folgenden Morgen machte sich Josua früh auf, und die Priester trugen wiederum die Lade des HERRN;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 6, 13, 'und die sieben Priester, welche die sieben Lärmposaunen vor der Lade des HERRN her trugen, stießen beim Gehen fortwährend in die Posaunen, während die Gewappneten vor ihnen herzogen und die Nachhut hinter der Lade des HERRN folgte, indem man dabei immerfort in die Posaunen stieß.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 6, 14, 'So zogen sie am zweiten Tage einmal um die Stadt herum und kehrten dann wieder ins Lager zurück. So machten sie es sechs Tage lang.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 6, 15, 'Am siebten Tage aber machten sie sich früh beim Aufgang der Morgenröte auf und zogen in derselben Weise siebenmal um die Stadt herum; nur an diesem Tage umzogen sie die Stadt siebenmal.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 6, 16, 'Beim siebten Umzug aber, als die Priester in die Posaunen gestoßen hatten, rief Josua dem Volke zu: »Erhebt das Kriegsgeschrei! Denn der HERR hat die Stadt in eure Gewalt gegeben!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 6, 17, 'Aber die Stadt mit allem, was darin ist, soll dem Bann für den HERRN geweiht sein; nur die Dirne Rahab soll am Leben bleiben, sie nebst allen denen, die sich bei ihr im Hause befinden; denn sie hat die Kundschafter versteckt, die wir ausgesandt hatten.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 6, 18, 'Nehmt ihr euch aber ja vor dem gebannten Gut in acht, daß ihr nicht, obgleich ihr es dem Bann geweiht habt, euch doch etwas von dem gebannten Gut aneignet und dadurch das Lager der Israeliten dem Bannfluch überliefert und es ins Unglück stürzt!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 6, 19, 'Alles Silber und Gold nebst den kupfernen und eisernen Geräten soll dem HERRN geheiligt sein und in den Schatz des HERRN kommen!« –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 6, 20, 'Da erhob das Volk das Kriegsgeschrei, und die Posaunen ertönten; und als das Volk den Posaunenschall vernahm und ein lautes Kriegsgeschrei erhoben hatte, da stürzte die Mauer in sich zusammen, und das Volk drang in die Stadt ein, ein jeder da, wo er gerade stand. Als sie so die Stadt eingenommen hatten,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 6, 21, 'vollstreckten sie den Bann an allem, was sich in der Stadt befand, an Männern wie an Weibern, an jung und alt, an den Rindern wie am Kleinvieh und an den Eseln: alles wurde mit der Schärfe des Schwertes niedergemacht.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 6, 22, 'Den beiden Männern aber, die das Land ausgekundschaftet hatten, hatte Josua befohlen: »Geht in das Haus der Dirne und führt das Weib mit allen ihren Angehörigen von dort heraus, wie ihr es ihr zugeschworen habt!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 6, 23, 'Da gingen die jungen Männer, die beiden Kundschafter, hin und führten Rahab nebst ihren Eltern und Geschwistern und allen ihren Angehörigen hinaus: alle ihre Verwandten führten sie hinaus und brachten sie an einem Orte außerhalb des israelitischen Lagers unter.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 6, 24, 'Die Stadt aber mit allem, was darin war, ließen sie in Flammen aufgehen; nur das Silber und Gold sowie die kupfernen und eisernen Geräte taten sie in den Schatz im Hause des HERRN.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 6, 25, 'Die Dirne Rahab aber nebst ihrer Familie und allen ihren Angehörigen ließ Josua am Leben, und sie ist inmitten der Israeliten bis auf den heutigen Tag wohnen geblieben, weil sie die Boten versteckt hatte, die Josua zur Auskundschaftung Jerichos ausgesandt hatte.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 6, 26, 'Damals ließ Josua (das Volk) folgenden Eid schwören: »Verflucht vor dem HERRN sei der Mann, der es unternimmt, diese Stadt Jericho wieder aufzubauen! Um den Preis seines Erstgeborenen wird er ihren Grundstein legen und um den Preis seines jüngsten Sohnes ihre Tore einsetzen!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 6, 27, 'Der HERR aber war mit Josua, so daß sein Ruhm sich durch das Land verbreitete.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 7, 1, 'Die Israeliten hatten sich aber eine Veruntreuung an dem gebannten Gut zuschulden kommen lassen; denn Achan, der Sohn Karmis, des Sohnes Sabdis, des Sohnes Serahs, vom Stamme Juda, hatte sich etwas von dem gebannten Gut angeeignet. Darob entbrannte der Zorn des HERRN gegen die Israeliten. –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 7, 2, 'Nun sandte Josua einige Männer von Jericho aus nach Ai, das bei Beth-Awen östlich von Bethel liegt, mit der Weisung: »Geht hinauf und kundschaftet die Gegend aus!« Als nun die Männer hinaufgegangen waren und Ai ausgekundschaftet hatten,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 7, 3, 'berichteten sie dem Josua nach ihrer Rückkehr: »Nicht das gesamte Volk braucht hinaufzuziehen; zwei- bis dreitausend Mann genügen, um Ai zu erobern. Bemühe nicht das ganze Volk dorthin; denn die Zahl ihrer Leute ist gering.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 7, 4, 'So zogen denn von dem Volk etwa dreitausend Mann dorthin, wurden aber von den Aiten in die Flucht geschlagen,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 7, 5, 'und die Aiten erschlugen etwa sechsunddreißig Mann von ihnen, verfolgten sie dann von dem Stadttor bis an die Steinbrüche und schlugen sie am Bergabhang. Da schwand dem Volk aller Mut und schlug in Verzagtheit um;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 7, 6, 'Josua aber zerriß seine Kleider, warf sich vor der Lade des HERRN auf sein Angesicht zur Erde nieder bis zum Abend, er samt den Ältesten der Israeliten, und sie streuten sich Staub aufs Haupt.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 7, 7, 'Darauf betete Josua: »Ach, HERR, mein Gott! Warum hast du dieses Volk über den Jordan geführt? Um uns in die Hand der Amoriter fallen zu lassen, damit sie uns vernichten? O hätten wir uns doch daran genügen lassen, jenseits des Jordans wohnen zu bleiben!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 7, 8, 'Verzeihe, HERR! Was soll ich sagen, nachdem Israel sich vor seinen Feinden zur Flucht gewandt hat?');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 7, 9, 'Wenn das die Kanaanäer und alle übrigen Bewohner des Landes erfahren, so werden sie von allen Seiten über uns herfallen und unsern Namen von der Erde vertilgen! Was willst du nun für deinen großen Namen tun?«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 7, 10, 'Da antwortete der HERR dem Josua: »Stehe auf! Wozu liegst du da auf deinem Angesicht?');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 7, 11, 'Israel hat sich versündigt! Denn sie haben sowohl mein Bundesgebot übertreten, das ich ihnen zur Pflicht gemacht habe, als auch sich etwas von dem gebannten Gut angeeignet; so haben sie sowohl einen Diebstahl begangen als auch das Gestohlene versteckt und unter ihre eigenen Geräte getan.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 7, 12, 'Daher vermögen die Israeliten jetzt vor ihren Feinden nicht mehr standzuhalten, sondern müssen vor ihren Feinden die Flucht ergreifen; denn sie sind selbst dem Bann verfallen. Ich werde hinfort nicht mehr mit euch sein, wenn ihr das gebannte Gut nicht aus eurer Mitte wegschafft.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 7, 13, 'Stehe auf, laß das Volk sich heiligen und mache bekannt: ›Heiligt euch auf morgen!‹ Denn so hat der HERR, der Gott Israels, gesprochen: ›Gebanntes Gut befindet sich in deiner Mitte, Israel; du wirst deinen Feinden nicht eher zu widerstehen vermögen, als bis ihr das gebannte Gut aus eurer Mitte weggeschafft habt.‹');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 7, 14, 'Darum sollt ihr morgen früh antreten, Stamm für Stamm; und der Stamm, den der HERR durch das Los bezeichnet, soll herantreten, ein Geschlecht nach dem andern; und das Geschlecht, das der HERR durch das Los bezeichnet, soll herantreten, eine Familie nach der andern; und die Familie, die der HERR durch das Los bezeichnet, soll Mann für Mann herantreten.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 7, 15, 'Wer dann als dem Bann verfallen durch das Los bezeichnet wird, soll mit allem, was er besitzt, im Feuer verbrannt werden, weil er das Bundesgebot des HERRN übertreten und eine Schandtat in Israel begangen hat!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 7, 16, 'Da ließ Josua am andern Morgen in der Frühe die Israeliten antreten, Stamm für Stamm; da wurde der Stamm Juda durch das Los getroffen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 7, 17, 'Als er dann die Geschlechter von Juda herantreten ließ, wurde das Geschlecht der Sarchiten getroffen. Als er dann das Geschlecht der Sarchiten herantreten ließ, eine Familie nach der andern, wurde die Familie Sabdis getroffen;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 7, 18, 'und als er dessen Familie Mann für Mann herantreten ließ, wurde Achan getroffen, der Sohn Karmis, des Sohnes Sabdis, des Sohnes Serahs, vom Stamme Juda.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 7, 19, 'Da sagte Josua zu Achan: »Mein Sohn, gib doch dem HERRN, dem Gott Israels, die Ehre und lege ein offenes Bekenntnis vor ihm ab: gestehe mir, was du getan hast: verhehle mir nichts!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 7, 20, 'Da antwortete Achan dem Josua: »Fürwahr, ich habe mich am HERRN, dem Gott Israels, versündigt! So und so habe ich getan:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 7, 21, 'ich sah unter den Beutestücken einen schönen babylonischen Mantel, dazu zweihundert Schekel Silber und eine Goldstange, fünfzig Schekel an Gewicht; da gelüstete mich nach diesen Sachen, und ich eignete sie mir an; sie sind jetzt mitten in meinem Zelt im Boden vergraben, und das Silber liegt zuunterst.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 7, 22, 'Da sandte Josua Boten hin, die liefen zum Zelt, und man fand die Sachen wirklich in seinem Zelt vergraben, und das Silber lag zuunterst.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 7, 23, 'Da nahmen sie die Sachen aus dem Zelte mit, brachten sie zu Josua und zu allen Israeliten und legten sie vor den HERRN hin.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 7, 24, 'Nun nahm Josua, und ganz Israel mit ihm, Achan, den Sohn Serahs, und das Silber, den Mantel und die Goldstange, dazu seine Söhne und Töchter, auch seine Rinder, seine Esel und sein Kleinvieh, ferner sein Zelt und alles, was er sonst noch besaß, und brachten das alles in das Tal Achor hinauf.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 7, 25, 'Dort sagte Josua zu Achan: »Wie hast du uns ins Unglück gestürzt! Dafür möge der HERR auch dich heute ins Unglück stürzen!« Hierauf steinigten ihn alle Israeliten [und man verbrannte sie im Feuer und vollzog die Steinigung an ihnen];');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 7, 26, 'dann errichteten sie über ihm einen großen Steinhaufen, der noch heutigentags dort liegt. Da ließ der HERR von seiner Zornesglut ab. Daher heißt jener Ort bis auf den heutigen Tag das Tal Achor.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 8, 1, 'Hierauf sagte der HERR zu Josua: »Fürchte dich nicht und sei ohne Angst! Nimm das gesamte Kriegsvolk mit dir und mache dich auf, ziehe gegen Ai hinauf: hiermit gebe ich den König von Ai samt seinem Volk, seiner Stadt und seinem Lande in deine Gewalt.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 8, 2, 'Du sollst mit Ai und seinem König so verfahren, wie du mit Jericho und seinem König verfahren bist; jedoch die dortige Beute und das Vieh dürft ihr für euch behalten. Lege dir einen Hinterhalt gegen die Stadt auf ihrer Westseite!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 8, 3, 'Da machte sich Josua mit dem gesamten Kriegsvolk auf, um gegen Ai hinaufzuziehen. Er wählte aber 30000 Mann tapfere Krieger aus und sandte sie bei Nacht ab,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 8, 4, 'nachdem er ihnen folgenden Befehl gegeben hatte: »Wisset wohl: ihr sollt euch gegen die Stadt in den Hinterhalt legen, und zwar auf der Westseite der Stadt; entfernt euch nicht zu weit von der Stadt und haltet euch allesamt bereit!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 8, 5, 'Ich aber und das ganze Kriegsvolk, das bei mir ist, werden gegen die Stadt anrücken, und wenn sie dann wie das vorige Mal einen Ausfall gegen uns machen, wollen wir vor ihnen fliehen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 8, 6, 'Sie werden dann herauskommen, um uns zu verfolgen, bis wir sie von der Stadt ganz abgezogen haben; denn sie werden denken: ›Die fliehen vor uns wie das vorige Mal‹; und wir wollen ja auch wirklich vor ihnen fliehen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 8, 7, 'Dann müßt ihr aus dem Hinterhalt hervorbrechen und euch der Stadt bemächtigen; denn der HERR, euer Gott, wird sie in eure Gewalt geben.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 8, 8, 'Wenn ihr aber die Stadt eingenommen habt, so steckt sie in Brand: nach dem Gebot des HERRN sollt ihr verfahren! Das sind meine Befehle für euch.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 8, 9, 'Als Josua sie so entlassen hatte, zogen sie in den Hinterhalt und nahmen Stellung zwischen Bethel und Ai, und zwar auf der Westseite von Ai, während Josua jene Nacht inmitten des übrigen Kriegsvolkes verbrachte.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 8, 10, 'Josua machte sich dann am folgenden Morgen früh auf und zog, nachdem er das Kriegsvolk gemustert hatte, mit den Ältesten der Israeliten an der Spitze des Heeres gegen Ai hinauf.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 8, 11, 'Das gesamte Kriegsvolk, das bei ihm war, zog hinauf und rückte heran und kam vor der Stadt an; sie lagerten nördlich von Ai, so daß das Tal zwischen ihnen und Ai lag.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 8, 12, '[Er hatte aber etwa fünftausend Mann genommen und sie als Hinterhalt zwischen Bethel und Ai, auf der Westseite der Stadt, Stellung nehmen lassen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 8, 13, 'Dann stellten sie das Volk auf, das ganze Heer, das sich nördlich von der Stadt befand, und dessen Hinterhalt westlich von der Stadt; Josua aber begab sich in jener Nacht mitten in das Tal.]');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 8, 14, 'Als nun der König von Ai dies sah, machten sich die Männer der Stadt in der Frühe eilends auf und zogen aus, den Israeliten zum Kampf entgegen, er und sein ganzes Volk, an den bestimmten Ort vor der Steppe, ohne zu wissen, daß ihm auf der Westseite der Stadt ein Hinterhalt gelegt war.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 8, 15, 'Da ließen sich Josua und ganz Israel von ihnen schlagen und flohen in der Richtung nach der Steppe zu.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 8, 16, 'Darauf wurde das gesamte Volk, das noch in der Stadt war, zu ihrer Verfolgung aufgeboten, und sie verfolgten Josua und ließen sich so von der Stadt weglocken:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 8, 17, 'kein Mann blieb in Ai [und Bethel] zurück, der nicht zur Verfolgung der Israeliten ausgezogen wäre; die Stadt aber ließen sie hinter sich offen stehen und verfolgten die Israeliten.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 8, 18, 'Da sagte der HERR zu Josua: »Strecke die Lanze, die du in der Hand hast, gegen Ai aus, denn ich gebe es in deine Gewalt.« Da streckte Josua die Lanze, die er in der Hand hatte, gegen die Stadt aus.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 8, 19, 'Nun verließ der Hinterhalt in aller Eile seinen Standort und gelangte, als Josua seine Hand ausgestreckt hatte, im Lauf zur Stadt, die sie einnahmen und sofort in Brand steckten.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 8, 20, 'Als nun die Aiten sich umwandten und den Rauch von der Stadt zum Himmel aufsteigen sahen, hatten sie keine Möglichkeit mehr, hierhin oder dorthin zu fliehen; denn das israelitische Heer, das nach der Wüste hin geflohen war, wandte sich gegen seine Verfolger um.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 8, 21, 'Denn als Josua und alle Israeliten sahen, daß der Hinterhalt die Stadt eingenommen hatte und daß der Rauch von der Stadt aufstieg, machten sie kehrt und schlugen die Aiten.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 8, 22, 'Jene anderen aber waren ihnen aus der Stadt entgegengezogen, so daß sich die Aiten mitten zwischen den Israeliten befanden, da die einen von dieser, die anderen von jener Seite kamen; und sie machten sie nieder, bis kein einziger von ihnen übrig war, der sich hätte retten oder entfliehen können.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 8, 23, 'Den König von Ai aber nahmen sie lebendig gefangen und brachten ihn zu Josua.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 8, 24, 'Als nun die Israeliten alle Bewohner von Ai auf dem freien Felde und in der Wüste, wohin die sie verfolgt hatten, niedergemacht hatten und diese alle bis auf den letzten Mann durch das Schwert gefallen waren, da wandten sich alle Israeliten wieder gegen Ai und machten alle Einwohner ohne Gnade nieder.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 8, 25, 'Die Zahl aller, die an diesem Tage fielen, Männer und Weiber, betrug zwölftausend, die ganze Einwohnerschaft von Ai.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 8, 26, 'Josua hatte nämlich seine Hand, die er mit der Lanze ausgestreckt hatte, nicht eher zurückgezogen, als bis der Bann an allen Bewohnern von Ai vollstreckt war.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 8, 27, 'Nur das Vieh und die Beute dieser Stadt behielten die Israeliten für sich, nach der Weisung, die der HERR dem Josua erteilt hatte.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 8, 28, 'Josua verbrannte dann Ai und machte es für ewige Zeiten zu einem Schutthaufen, zu einer wüsten Stätte, bis auf den heutigen Tag.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 8, 29, 'Den König von Ai aber ließ er bis zur Abendzeit an einen Baum hängen; doch bei Sonnenuntergang nahm man seinen Leichnam auf Befehl Josuas von dem Baume ab und warf ihn an den Eingang des Stadttores, wo man über ihm einen großen Steinhaufen errichtete, der dort noch bis zum heutigen Tage vorhanden ist.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 8, 30, 'Damals baute Josua dem HERRN, dem Gott Israels, einen Altar auf dem Berge Ebal,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 8, 31, 'wie Mose, der Knecht des HERRN, den Israeliten geboten hatte, wie im Gesetzbuch Moses geschrieben steht, einen Altar aus unbehauenen Steinen, an die noch kein eisernes Werkzeug gekommen war; und sie brachten auf ihm dem HERRN Brandopfer dar und schlachteten Dankopfer.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 8, 32, 'Dann schrieb er dort auf Steine eine Abschrift des mosaischen Gesetzes, das (Mose) einst in Gegenwart der Israeliten geschrieben hatte.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 8, 33, 'Und ganz Israel mit seinen Ältesten und Obmännern und seinen Richtern stand zu beiden Seiten der Lade den levitischen Priestern gegenüber, welche die Bundeslade des HERRN zu tragen hatten, sowohl die Fremdlinge als auch die Einheimischen, die eine Hälfte von ihnen nach dem Berge Garizim zu, die andere Hälfte nach dem Berge Ebal hin, wie Mose, der Knecht des HERRN, einstmals geboten hatte, das Volk Israel zu segnen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 8, 34, 'Darnach las Josua alle Worte des Gesetzes laut vor, den Segen wie den Fluch, genau so, wie es im Gesetzbuch geschrieben steht:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 8, 35, 'es gab kein Wort von allem, was Mose geboten hatte, das Josua nicht vor der ganzen Versammlung der Israeliten, auch vor den Frauen und Kindern und den Fremdlingen, die unter ihnen mitzogen, laut vorgelesen hätte.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 9, 1, 'Als nun alle Könige dies vernahmen, die diesseits des Jordans im Berglande, in der Niederung und an der ganzen Küste des großen Meeres nach dem Libanon hin wohnten, nämlich die Hethiter und die Amoriter, die Kanaanäer, Pherissiter, Hewiter und Jebusiter,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 9, 2, 'da taten sie sich alle zusammen, um einmütig gegen Josua und die Israeliten zu kämpfen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 9, 3, 'Als aber die Einwohner von Gibeon vernahmen, wie Josua mit Jericho und Ai verfahren war,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 9, 4, 'gingen sie ihrerseits mit List zu Werke: sie machten sich auf den Weg, und zwar versorgten sie sich mit Lebensmitteln, nahmen alte Säcke für ihre Esel und alte, geborstene und geflickte Weinschläuche,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 9, 5, 'zogen alte, geflickte Schuhe und abgetragene Kleider an, und alles Brot, das sie als Mundvorrat bei sich hatten, war vertrocknet und zerbröckelt.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 9, 6, 'Als sie so zu Josua ins Lager nach Gilgal gekommen waren, sagten sie zu ihm und zu den Israeliten: »Aus einem fernen Lande sind wir gekommen; so schließt denn jetzt einen Vertrag mit uns.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 9, 7, 'Da antworteten die Israeliten den Hewitern: »Vielleicht wohnt ihr mitten unter uns: wie könnten wir da einen Vertrag mit euch schließen?«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 9, 8, 'Da sagten sie zu Josua: »Wir sind deine Knechte.« Als Josua sie nun fragte: »Wer seid ihr, und woher kommt ihr?«,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 9, 9, 'antworteten sie ihm: »Aus einem ganz fernen Lande sind deine Knechte infolge des Ruhmes des HERRN, deines Gottes, gekommen; denn wir haben die Kunde von ihm vernommen, sowohl alles, was er an Ägypten getan hat,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 9, 10, 'als auch alles, was er an den beiden Königen der Amoriter jenseits des Jordans getan hat, an Sihon, dem König von Hesbon, und an Og, dem König von Basan, der zu Astaroth wohnte.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 9, 11, 'Da haben unsere Ältesten und alle Bewohner unsers Landes zu uns gesagt: ›Nehmt Lebensmittel mit euch auf den Weg, geht ihnen entgegen und sagt zu ihnen: ›Wir sind eure Knechte; so schließt nun einen Vertrag mit uns!‹');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 9, 12, 'Hier ist unser Brot: es war noch warm, als wir es aus unseren Häusern als Reisekost mitnahmen an dem Tage, als wir aufbrachen, um zu euch zu ziehen; nun aber seht ihr, daß es vertrocknet und zerbröckelt geworden ist.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 9, 13, 'Und hier sind unsere Weinschläuche, die neu waren, als wir sie füllten; nun aber sind sie geborsten, wie ihr seht, und unsere Kleider und Schuhe hier sind von dem sehr weiten Wege ganz abgenutzt.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 9, 14, 'Da ließen sich die israelitischen Männer etwas von ihrem Mundvorrat geben, aber einen Ausspruch des HERRN holten sie nicht ein,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 9, 15, 'sondern Josua gewährte ihnen Frieden und schloß einen Vertrag mit ihnen, daß er sie am Leben lassen wolle; und die Fürsten der Gemeinde leisteten ihnen einen Eid.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 9, 16, 'Als aber nach Abschluß des Vertrags mit ihnen drei Tage vergangen waren, da erfuhr man, daß jene ganz aus der Nähe waren und mitten unter ihnen wohnten.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 9, 17, 'Denn als die Israeliten weiter zogen, kamen sie am dritten Tage zu ihren Städten, nämlich zu den Ortschaften Gibeon, Kephira, Beeroth und Kirjath-Jearim.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 9, 18, 'Die Israeliten taten ihnen aber nichts zuleide, weil die Fürsten der Gemeinde ihnen beim HERRN, dem Gott Israels, geschworen hatten. Als nun die ganze Gemeinde über die Fürsten murrte,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 9, 19, 'sagten diese alle zu der ganzen Gemeinde: »Wir haben ihnen beim HERRN, dem Gott Israels, einen Eid geleistet; darum dürfen wir uns jetzt nicht an ihnen vergreifen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 9, 20, 'Wir wollen so mit ihnen verfahren, daß wir sie am Leben lassen, damit kein Zorngericht über uns komme wegen des Eides, den wir ihnen geschworen haben.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 9, 21, 'Die Fürsten gaben also (vor dem Volk) die Erklärung ab: »Sie sollen am Leben bleiben, aber Holzhauer und Wasserträger für die ganze Gemeinde werden.« (Da taten die Israeliten,) wie die Fürsten ihnen vorgeschlagen hatten.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 9, 22, 'Hierauf ließ Josua sie rufen und sagte bei der Unterredung zu ihnen: »Warum habt ihr uns getäuscht, indem ihr vorgabt: ›Wir wohnen sehr weit von euch weg‹, während ihr doch mitten unter uns wohnt?');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 9, 23, 'Nun denn, so sollt ihr verflucht sein und in Zukunft immer Knechte, sowohl Holzhauer als Wasserträger, für das Haus meines Gottes sein!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 9, 24, 'Da gaben sie dem Josua zur Antwort: »Deinen Knechten wurde als gewiß mitgeteilt, daß der HERR, dein Gott, seinem Knechte Mose geboten hat, euch dies ganze Land zu geben, und ihr solltet alle Bewohner des Landes vor euch her vertilgen. Da gerieten wir vor euch in große Furcht für unser Leben und haben so gehandelt.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 9, 25, 'Und nun – wir sind ja in deiner Gewalt: verfahre mit uns so, wie es dich gut und recht dünkt!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 9, 26, 'Da verfuhr er in der angegebenen Weise mit ihnen und rettete sie aus der Hand der Israeliten, so daß diese sie nicht ums Leben brachten.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 9, 27, 'Josua machte sie also damals zu Holzhauern und Wasserträgern für die Gemeinde und für den Altar des HERRN an der Stätte, die der HERR erwählen würde; und so ist’s geblieben bis auf den heutigen Tag.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 1, 'Als nun Adoni-Zedek, der König von Jerusalem, die Kunde erhielt, daß Josua Ai erobert und den Bann an der Stadt vollstreckt habe, daß er mit Ai und seinem König ebenso wie mit Jericho und seinem König verfahren sei und daß die Bewohner von Gibeon Frieden mit den Israeliten geschlossen hätten und mitten unter ihnen wohnen geblieben seien,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 2, 'da fürchteten sie sich sehr; denn Gibeon war eine bedeutende Stadt, so groß wie irgendeine von den Königstädten und noch größer als Ai, und alle ihre Männer tapfere Krieger.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 3, 'Daher schickte Adoni-Zedek, der König von Jerusalem, Gesandte an Hoham, den König von Hebron, sowie an Piream, den König von Jarmuth, an Japhia, den König von Lachis, und an Debir, den König von Eglon, und ließ ihnen sagen:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 4, '»Zieht zu mir herauf und helft mir, Gibeon dafür zu strafen, daß es mit Josua und den Israeliten Frieden geschlossen hat.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 5, 'Da vereinigten sich und zogen hinauf die fünf Amoriterkönige: der König von Jerusalem, der König von Hebron, der König von Jarmuth, der König von Lachis und der König von Eglon mit allen ihren Heeren und belagerten Gibeon und bestürmten es.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 6, 'Da sandten die Gibeoniten Boten zu Josua in das Lager nach Gilgal und ließen ihm sagen: »Laß deine Knechte nicht im Stich! Komm eilends zu uns herauf, rette uns und hilf uns! Denn alle Könige der Amoriter, die das Bergland bewohnen, haben sich gegen uns verbündet.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 7, 'Da zog Josua mit seinem gesamten Kriegsvolk, lauter tapferen Männern, von Gilgal aus hinauf;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 8, 'und der HERR sagte zu ihm: »Fürchte dich nicht vor ihnen! Denn ich habe sie in deine Gewalt gegeben: kein einziger von ihnen soll vor dir standhalten können.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 9, 'Als Josua sie nun plötzlich überfiel – die ganze Nacht hindurch war er von Gilgal hinaufgezogen –,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 10, 'ließ der HERR unter ihnen einen plötzlichen Schrecken vor den Israeliten entstehen, so daß diese ihnen eine schwere Niederlage bei Gibeon beibrachten und sie in der Richtung nach dem Berghang von Beth-Horon verfolgten und sie bis Aseka und Makkeda schlugen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 11, 'Als sie sich nun auf der Flucht vor den Israeliten am Abhang von Beth-Horon befanden, ließ der HERR große Steine vom Himmel bis nach Aseka hin auf sie herabfallen, so daß sie dadurch den Tod fanden; die Zahl derer, welche durch den Steinhagel das Leben verloren, war größer als die Zahl derer, welche durch das Schwert der Israeliten gefallen waren.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 12, 'Damals betete Josua zum HERRN, an dem Tage, an dem der HERR die Amoriter den Israeliten preisgab, und zwar rief er angesichts der Israeliten aus: »Sonne, stehe still zu Gibeon und du, Mond, im Tal von Ajjalon!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 13, 'Da stand die Sonne still, und der Mond blieb stehen, bis das Volk Rache an seinen Feinden genommen hatte. Das steht bekanntlich im »Buch des Braven« geschrieben. Die Sonne blieb also mitten am Himmel stehen und eilte beinahe einen ganzen Tag lang nicht zum Untergang.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 14, 'Einen Tag wie diesen hat es weder vorher noch später gegeben, daß der HERR auf die Stimme eines Menschen gehört hätte; denn der HERR stritt für Israel.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 15, '[Hierauf kehrte Josua und ganz Israel mit ihm in das Lager nach Gilgal zurück.]');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 16, 'Jene fünf Könige aber waren geflohen und hatten sich in der Höhle bei Makkeda versteckt.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 17, 'Als nun Josua die Meldung erhielt, daß man die fünf Könige versteckt in der Höhle bei Makkeda gefunden habe,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 18, 'gab er den Befehl: »Wälzt große Steine vor den Eingang der Höhle und stellt Leute zu ihrer Bewachung daneben auf!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 19, 'Ihr anderen aber steht nicht still, sondern verfolgt eure Feinde und haut ihre Nachzügler nieder! Laßt sie nicht in ihre Städte entkommen; denn der HERR, euer Gott, hat sie in eure Gewalt gegeben.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 20, 'Als nun Josua und die Israeliten eine sehr schwere Niederlage unter ihnen bis zur völligen Vernichtung angerichtet hatten – diejenigen von ihnen, welche entkommen waren, hatten sich in die festen Plätze geflüchtet –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 21, 'und als das ganze Kriegsvolk unangefochten zu Josua in das Lager nach Makkeda zurückgekehrt war, ohne daß jemand den Israeliten auch nur das Geringste hatte anhaben können,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 22, 'da gab Josua den Befehl: »Macht den Eingang der Höhle frei und bringt jene fünf Könige aus der Höhle zu mir heraus!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 23, 'Man kam dem Befehle nach und brachte jene fünf Könige aus der Höhle zu ihm heraus, die Könige von Jerusalem, von Hebron, von Jarmuth, von Lachis und von Eglon.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 24, 'Als man diese Könige nun zu Josua herausgeführt hatte, rief Josua alle Israeliten herbei und sagte zu den Anführern der Kriegsleute, die mit ihm gezogen waren: »Tretet heran und setzt diesen Königen den Fuß auf den Nacken!« Da traten sie heran und setzten ihnen den Fuß auf den Nacken.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 25, 'Dann fuhr Josua fort: »Fürchtet euch nicht und habt keine Angst, seid mutig und stark! Denn ebenso wird der HERR es mit allen euren Feinden machen, mit denen ihr noch zu kämpfen habt.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 26, 'Hierauf ließ Josua sie totschlagen und an fünf Bäumen aufhängen; und sie blieben an den Bäumen bis zum Abend hängen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 27, 'Bei Sonnenuntergang aber nahm man sie auf Befehl Josuas von den Bäumen ab und warf sie in die Höhle, in der sie sich versteckt hatten, und legte große Steine an den Eingang der Höhle, die noch bis zum heutigen Tage dort liegen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 28, 'Josua eroberte dann an jenem Tage noch Makkeda und schlug es mit der Schärfe des Schwertes, indem er am dortigen König, an der Stadt und der gesamten Einwohnerschaft den Bann vollstreckte; er verschonte keinen einzigen von ihnen und verfuhr mit dem König von Makkeda, wie er mit dem König von Jericho verfahren war. –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 29, 'Hierauf zog Josua mit allen Israeliten von Makkeda weiter nach Libna und bestürmte es;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 30, 'und der HERR ließ auch diese Stadt in die Hand der Israeliten fallen samt ihrem König, und er schlug sie mit der Schärfe des Schwertes samt der ganzen Einwohnerschaft; er verschonte keinen einzigen von ihnen und verfuhr mit dem dortigen König, wie er mit dem König von Jericho verfahren war. –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 31, 'Dann zog Josua mit allen Israeliten von Libna weiter nach Lachis, das er belagerte und bestürmte.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 32, 'Und der HERR ließ auch Lachis in die Gewalt der Israeliten fallen, so daß Josua es am zweiten Tage eroberte und die Stadt samt der ganzen Einwohnerschaft mit der Schärfe des Schwertes schlug, genau so, wie er es mit Libna gemacht hatte.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 33, 'Damals zog Horam, der König von Geser, herauf, um Lachis Hilfe zu leisten; aber Josua schlug ihn und sein Kriegsvolk so, daß kein einziger von ihnen am Leben blieb. –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 34, 'Dann zog Josua mit allen Israeliten von Lachis weiter nach Eglon, das sie belagerten und bestürmten.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 35, 'Sie eroberten es noch an demselben Tage und schlugen es mit der Schärfe des Schwertes; an der ganzen Einwohnerschaft vollstreckte er an jenem Tage den Bann, genau so, wie er es mit Lachis gemacht hatte. –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 36, 'Hierauf zog Josua mit allen Israeliten von Eglon nach Hebron hinauf, das sie bestürmten;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 37, 'sie eroberten es und schlugen es mit der Schärfe des Schwertes samt seinem König und allen zugehörigen Ortschaften und deren gesamten Einwohnerschaft, ohne einen einzigen zu verschonen, genau so, wie er es mit Eglon gemacht hatte, indem er an der Stadt und allen ihren Einwohnern den Bann vollstreckte. –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 38, 'Dann wandte sich Josua mit allen Israeliten gegen Debir, das er bestürmte.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 39, 'Er nahm die Stadt ein samt ihrem König und allen zugehörigen Ortschaften; und sie schlugen sie mit der Schärfe des Schwertes und vollzogen an der gesamten Einwohnerschaft den Bann, ohne einen einzigen zu verschonen; wie er es mit Hebron gemacht hatte und wie er mit Libna und dem dortigen König verfahren war, ebenso machte er es auch mit Debir und dem dortigen König.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 40, 'So unterwarf Josua das ganze Land, nämlich das Bergland und das Südland, die Niederung und das Hügelland samt allen ihren Königen, ohne auch nur einen einzigen übrigzulassen; und an allem Lebenden vollstreckte er den Bann, wie der HERR, der Gott Israels, geboten hatte.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 41, 'Josua unterwarf sie von Kades-Barnea bis Gaza und das ganze Land Gosen bis Gibeon;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 42, 'und zwar brachte Josua alle diese Könige und ihr Land auf einmal in seine Gewalt, denn der HERR, der Gott Israels, stritt für Israel.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 43, 'Hierauf kehrte Josua mit allen Israeliten in das Lager nach Gilgal zurück.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 11, 1, 'Als nun Jabin, der König von Hazor, Kunde davon erhielt, schickte er Gesandte an Jobab, den König von Madon, sowie an den König von Simron und an den König von Achsaph');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 11, 2, 'und an die Könige, die im Norden im Berglande sowie in der Jordanebene südlich vom See Genezareth und in der Niederung und im Hügelgelände von Dor gegen Westen wohnten,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 11, 3, 'an die Kanaanäer gegen Osten und gegen Westen und an die Amoriter, Hethiter, Pherissiter und Jebusiter im Berglande und an die Hewiter am Fuß des Hermon in der Landschaft Mizpa.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 11, 4, 'So zogen sie denn mit allen ihren Heeren ins Feld, ein Kriegsvolk unzählig wie der Sand am Meeresufer, auch mit sehr vielen Rossen und Streitwagen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 11, 5, 'Alle diese Könige, die sich verbündet hatten, rückten ins Feld und schlugen gemeinsam ihr Lager am Wasser von Merom auf, um den Israeliten eine Schlacht zu liefern.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 11, 6, 'Da sagte der HERR zu Josua: »Fürchte dich nicht vor ihnen! Denn morgen um diese Zeit will ich es fügen, daß sie alle erschlagen vor den Israeliten daliegen; ihre Rosse aber sollst du lähmen und ihre Streitwagen im Feuer verbrennen.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 11, 7, 'Als dann Josua sie mit seiner ganzen Heeresmacht plötzlich am Wasser von Merom überfiel und sich auf sie warf,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 11, 8, 'gab der HERR sie in die Gewalt der Israeliten, so daß diese sie besiegten und bis Groß-Sidon und bis Misrephoth-Majim und bis in die Talebene von Mizpe gegen Osten verfolgten und ein Blutbad unter ihnen anrichteten, bis kein einziger von ihnen mehr übrig war.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 11, 9, 'Josua verfuhr dann mit ihnen, wie der HERR ihm geboten hatte: ihre Rosse lähmte er, und ihre Kriegswagen verbrannte er im Feuer.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 11, 10, 'Dann machte Josua wieder kehrt zu jener Zeit, eroberte Hazor und ließ den dortigen König mit dem Schwert erschlagen; Hazor war nämlich ehedem die Hauptstadt aller jener Reiche.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 11, 11, 'Sie machten dann die ganze dortige Einwohnerschaft mit der Schärfe des Schwertes nieder, indem sie den Bann an ihnen vollstreckten: nichts blieb übrig, was Odem hatte, und Hazor selbst ließ er in Flammen aufgehen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 11, 12, 'Alle Städte jener Könige samt allen ihren Königen brachte Josua in seine Gewalt; er schlug sie mit der Schärfe des Schwertes und vollstreckte den Bann an ihnen, wie Mose, der Knecht Gottes, geboten hatte.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 11, 13, 'Jedoch alle Städte, die auf den dortigen Anhöhen lagen, verbrannten die Israeliten nicht, mit alleiniger Ausnahme von Hazor, das Josua in Flammen aufgehen ließ.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 11, 14, 'Alle Beute aber aus diesen Ortschaften und das Vieh nahmen die Israeliten für sich hin, doch alle Menschen machten sie mit der Schärfe des Schwertes nieder bis zu völliger Vernichtung: sie verschonten nichts Lebendes.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 11, 15, 'Wie der HERR seinem Knecht Mose geboten hatte, so hatte Mose es dem Josua zur Pflicht gemacht, und so führte Josua es auch aus: er ließ nicht das Geringste unbefolgt von allem, was der HERR dem Mose geboten hatte.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 11, 16, 'So unterwarf Josua dieses ganze Land, nämlich das Bergland wie das ganze Südland, die ganze Landschaft Gosen, die Niederung, das Jordantal und das Bergland von Israel mit der dazugehörigen Niederung,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 11, 17, 'von dem kahlen Gebirge an, das sich nach Seir hin erhebt, bis nach Baal-Gad in der Talebene des Libanons am Fuße des Hermongebirges. Auch alle dortigen Könige bekam er in seine Gewalt: er schlug sie und ließ sie sterben.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 11, 18, 'Lange Zeit führte Josua mit allen diesen Königen Krieg.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 11, 19, 'Es gab keine Stadt, die sich freiwillig den Israeliten ergeben hätte, außer den Hewitern, die in Gibeon wohnten; alles andere mußten sie mit Waffengewalt erobern.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 11, 20, 'Denn vom HERRN geschah es, daß er ihr Herz zum Krieg mit den Israeliten verhärtete, damit der Bann an ihnen vollstreckt werden könnte, ohne daß ihnen Gnade gewährt würde, vielmehr damit sie ausgerottet würden, wie der HERR dem Mose geboten hatte.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 11, 21, 'Zu jener Zeit zog Josua hin und vernichtete die Enakiter im Gebirge: in Hebron, in Debir, in Anab sowie im ganzen Berglande Juda und im ganzen Berglande Israel; an ihnen wie an ihren Ortschaften vollstreckte Josua den Bann.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 11, 22, 'Es blieben keine Enakiter im Lande der Israeliten übrig; nur in Gaza, in Gath und in Asdod erhielten sich Reste von ihnen. –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 11, 23, 'So eroberte denn Josua das ganze Land genau so, wie der HERR dem Mose geboten hatte, und Josua gab es den Israeliten zum Erbbesitz nach ihren Abteilungen in den einzelnen Stämmen; das Land bekam dann Ruhe vom Kriege.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 12, 1, 'Dies sind die Könige des Landes, welche die Israeliten besiegt und deren Land sie in Besitz genommen haben: im Ostjordanlande (die Gebiete) vom Fluß Arnon an bis zum Hermongebirge nebst der ganzen Steppe östlich vom Jordan:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 12, 2, 'Sihon, der König der Amoriter, der in Hesbon seinen Sitz hatte; er herrschte von Aroer an, das am Ufer des Flusses Arnon liegt, und zwar von der Mitte des Flußtals an und über die Hälfte von Gilead bis zum Fluß Jabbok, der Grenze der Ammoniter,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 12, 3, 'und über das Jordantal bis an die Ostseite des Sees Genezareth und bis an die Ostseite des Meeres der Steppe, des Salzsees, nach Beth-Jesimoth hin und südwärts (über das Land) am Fuß der Abhänge des Pisgagebirges.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 12, 4, 'Sodann das Gebiet Ogs, des Königs von Basan, der zu den Überresten der Rephaiter gehörte und in Astaroth und Edrei seinen Sitz hatte;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 12, 5, 'er herrschte über das Hermongebirge, über Salcha und ganz Basan bis an die Grenze der Gesuriter und Maachathiter und über die Hälfte von Gilead bis an das Gebiet Sihons, des Königs von Hesbon.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 12, 6, 'Mose, der Knecht des HERRN, und die Israeliten hatten sie besiegt, und Mose, der Knecht des HERRN, hatte ihr Gebiet den beiden Stämmen Ruben und Gad und dem halben Stamm Manasse zum Besitz gegeben.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 12, 7, 'Und dies sind die Könige des Landes, welche Josua und die Israeliten im Westjordanlande besiegt haben, von Baal-Gad im Libanontal an bis zu dem kahlen Gebirge, das nach Seir hin ansteigt, und deren Land Josua den israelitischen Stämmen zum Besitz überwies, jedem Stamme einen Teil,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 12, 8, 'im Berglande wie in der Niederung und im Jordantal, an den Bergabhängen wie in der Wüste und im Südlande, die (Gebiete der) Hethiter, Amoriter, Kanaanäer, Pherissiter, Hewiter und Jebusiter:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 12, 9, 'der König von Jericho (war) einer; der König von Ai, das seitwärts von Bethel liegt, einer;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 12, 10, 'der König von Jerusalem einer; der König von Hebron einer;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 12, 11, 'der König von Jarmuth einer; der König von Lachis einer;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 12, 12, 'der König von Eglon einer; der König von Geser einer;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 12, 13, 'der König von Debir einer; der König von Geder einer;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 12, 14, 'der König von Horma einer; der König von Arad einer;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 12, 15, 'der König von Libna einer; der König von Adullam einer;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 12, 16, 'der König von Makkeda einer; der König von Bethel einer;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 12, 17, 'der König von Thappuah einer; der König von Hepher einer;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 12, 18, 'der König von Aphek einer; der König von Saron einer;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 12, 19, 'der König von Madon einer; der König von Hazor einer;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 12, 20, 'der König von Simron-Meron einer; der König von Achsaph einer;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 12, 21, 'der König von Thaanach einer; der König von Megiddo einer;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 12, 22, 'der König von Kedes einer; der König von Jokneam am Karmel einer;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 12, 23, 'der König von Dor in dem Hügelgelände von Dor einer; der König von Gojim in Gilgal einer;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 12, 24, 'der König von Thirza einer. Im ganzen waren es einunddreißig Könige.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 13, 1, 'Als nun Josua alt und hochbetagt geworden war, sagte der HERR zu ihm: »Du bist nun alt und hochbetagt, und von dem Lande sind sehr viele Teile bisher noch unerobert geblieben.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 13, 2, 'Dies ist das noch uneroberte Land: sämtliche Bezirke der Philister und das ganze Gesuriterland.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 13, 3, 'Vom Sihorbach an, der östlich von Ägypten fließt, bis an das Gebiet von Ekron im Norden – es wird zum Gebiet der Kanaanäer gerechnet –: die fünf Fürsten der Philister, nämlich der von Gaza, der von Asdod, der von Askalon, der von Gath und der von Ekron, sowie die Awwiter im Süden;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 13, 4, 'ferner das ganze Land der Kanaanäer und Meara, das den Sidoniern gehört, bis nach Aphek, bis an die Grenze der Amoriter;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 13, 5, 'sodann das Land der Gibliter und der ganze Libanon östlichen Teils, von Baal-Gad am Fuß des Hermongebirges bis dahin, wo man nach Hamath kommt.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 13, 6, 'Alle Gebirgsbewohner vom Libanon an bis Misrephoth-Majim, alle Sidonier, werde ich selbst vor den Israeliten her vertreiben; verlose es immerhin an Israel als Erbbesitz, wie ich dir geboten habe.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 13, 7, 'So verteile also jetzt dieses Land als Erbbesitz an die neun Stämme und an den halben Stamm Manasse.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 13, 8, 'Mit dem andern halben Stamm Manasse nämlich hatten die Stämme Ruben und Gad ihren Erbbesitz bereits empfangen, den ihnen Mose im Ostjordanlande angewiesen hatte, wie ihn Mose, der Knecht des HERRN, ihnen angewiesen hatte:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 13, 9, 'von Aroer an, das am Ufer des Flusses Arnon liegt, und überhaupt von den Städten an, die mitten im Flußtal liegen, dazu die ganze Hochebene von Medeba bis Dibon,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 13, 10, 'ferner sämtliche Städte des Amoriterkönigs Sihon, der in Hesbon geherrscht hatte, bis an das Gebiet der Ammoniter;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 13, 11, 'sodann Gilead und das Gebiet der Gesuriter und Maachathiter sowie das ganze Hermongebirge und ganz Basan bis nach Salcha,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 13, 12, 'das ganze Reich Ogs in Basan, der in Astharoth und Edrei geherrscht hatte – er war vom Überrest der Rephaiter noch übriggeblieben –: diese hatte Mose besiegt und aus ihrem Besitz vertrieben.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 13, 13, 'Die Israeliten dagegen haben die Gesuriter und Maachathiter nicht aus ihrem Besitz vertrieben, sondern diese beiden Völkerschaften sind mitten unter den Israeliten bis auf den heutigen Tag wohnen geblieben. –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 13, 14, 'Nur dem Stamme Levi hatte (Mose) keinen Erbbesitz verliehen: die Feueropfer des HERRN, des Gottes der Israeliten, die sind dessen Erbbesitz, wie er ihm zugesagt hat.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 13, 15, 'Mose hatte aber dem Stamme der Rubeniten Landbesitz nach ihren Geschlechtern angewiesen,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 13, 16, 'so daß ihnen folgendes Gebiet zuteil wurde: das Gebiet von Aroer an, das am Ufer des Flusses Arnon liegt, und überhaupt von den Städten an, die mitten im Flußtal liegen, dazu die ganze Hochebene bis Medeba;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 13, 17, 'Hesbon mit allen zugehörigen Ortschaften, die auf der Hochebene liegen, nämlich Dibon, Bamoth-Baal, Beth-Baal-Meon,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 13, 18, 'Jahza, Kedemoth, Mephaath,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 13, 19, 'Kirjathaim, Sibma, Zereth-Sahar auf dem Berge in der Talebene,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 13, 20, 'Beth-Peor, die Abhänge des Pisga, Beth-Jesimoth');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 13, 21, 'und alle übrigen Ortschaften der Hochebene; ferner das ganze Reich des Amoriterkönigs Sihon, der in Hesbon geherrscht hatte – Mose hatte ihn besiegt, ihn mitsamt den Fürsten der Midianiter, nämlich Ewi, Rekem, Zur, Hur und Reba, den Häuptlingen Sihons, die im Lande gewohnt hatten.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 13, 22, 'Auch den Wahrsager Bileam, den Sohn Beors, hatten die Israeliten mit dem Schwert getötet außer den anderen von ihnen Erschlagenen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 13, 23, 'Die (westliche) Grenze des Stammes Ruben aber bildete der Jordan und sein Uferland. Dies war der Erbbesitz der Rubeniten nach ihren Geschlechtern: die genannten Städte mit den zugehörigen Gehöften.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 13, 24, 'Sodann hatte Mose dem Stamme Gad, den Gaditen, Landbesitz nach ihren Geschlechtern angewiesen,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 13, 25, 'so daß ihnen folgendes Gebiet zuteil wurde: Jaser und sämtliche Ortschaften in Gilead und das halbe Ammoniterland bis Aroer, das östlich von Rabba liegt;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 13, 26, 'ferner das Land von Hesbon bis Ramath-Mizpe und Betonim und von Mahanaim bis an das Gebiet von Lidebir;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 13, 27, 'sodann in der Talebene: Beth-haram, Beth-Nimra, Sukkoth und Zaphon, der Rest vom Reiche Sihons, des Königs von Hesbon, der Jordan mit seinem Uferland bis an das Ende des Sees Genezareth auf der Ostseite des Jordans.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 13, 28, 'Das war der Erbbesitz der Gaditen nach ihren Geschlechtern, die genannten Städte mit den zugehörigen Dörfern.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 13, 29, 'Ferner hatte Mose dem halben Stamm Manasse Landbesitz angewiesen, so daß dem halben Stamme der Manassiten nach ihren Geschlechtern folgendes Gebiet zuteil wurde:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 13, 30, 'das Land von Mahanaim an, das ganze Basan, das ganze Reich Ogs, des Königs von Basan, und sämtliche Zeltdörfer Jairs, die in Basan liegen, sechzig Ortschaften;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 13, 31, 'ferner die Hälfte von Gilead sowie Astaroth und Edrei, die Hauptstädte des Reiches Ogs in Basan. Dies alles wurde den Nachkommen Machirs, des Sohnes Manasses, und zwar der Hälfte der Nachkommen Machirs, nach ihren Geschlechtern zuteil.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 13, 32, 'Diese Gebiete sind es, die Mose in den Steppen der Moabiter jenseits des Jordans, östlich von Jericho, ausgeteilt hatte.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 13, 33, 'Dem Stamme Levi aber hatte Mose keinen Erbbesitz gegeben: der HERR, der Gott Israels, der sollte ihr Erbbesitz sein, wie er ihnen zugesagt hatte.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 14, 1, 'Und dies sind die Gebiete, welche die Israeliten im Lande Kanaan als Erbbesitz empfangen haben, die ihnen der Priester Eleasar und Josua, der Sohn Nuns, und die Häupter der israelitischen Stämme');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 14, 2, 'als ihren Erbbesitz durch das Los zugeteilt haben, wie der HERR es durch Mose bezüglich der neuneinhalb Stämme verordnet hatte;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 14, 3, 'denn den zweieinhalb Stämmen hatte Mose ihren Erbbesitz jenseits des Jordans angewiesen, den Leviten aber keinen Erbbesitz unter den Israeliten verliehen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 14, 4, 'Die Nachkommen Josephs bildeten nämlich zwei Stämme, Manasse und Ephraim; den Leviten aber gab man keinen Anteil am Landbesitz, sondern nur einzelne Städte zum Bewohnen nebst den zugehörigen Weidetriften für ihr Vieh und ihre Habe.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 14, 5, 'Wie der HERR dem Mose geboten hatte, so verfuhren die Israeliten bei der Verteilung des Landes.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 14, 6, 'Da traten die Judäer vor Josua in Gilgal, und Kaleb, der Sohn Jephunnes, der Kenissite, sagte zu Josua: »Du weißt selbst, was der HERR zu Mose, dem Manne Gottes, in bezug auf mich und auf dich in Kades-Barnea gesagt hat.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 14, 7, 'Vierzig Jahre war ich alt, als Mose, der Knecht des HERRN, mich von Kades-Barnea zur Auskundschaftung des Landes aussandte, und ich erstattete ihm Bericht, wie ich in meinem Herzen wirklich dachte.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 14, 8, 'Meine Volksgenossen aber, die mit mir hinaufgezogen waren, machten dem Volk das Herz verzagt, während ich dem HERRN, meinem Gott, vollen Gehorsam bewies.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 14, 9, 'Da sprach Mose an jenem Tage folgenden Schwur aus: ›Fürwahr das Land, das dein Fuß betreten hat, soll dir und deinen Nachkommen auf ewige Zeiten als Erbbesitz zuteil werden, weil du dem HERRN, meinem Gott, vollkommen gehorsam gewesen bist!‹');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 14, 10, 'Und nun hat mich der HERR, wie du siehst, seiner Verheißung gemäß noch fünfundvierzig Jahre am Leben erhalten seit der Zeit, als der HERR jenes Wort zu Mose gesprochen hat und während die Israeliten in der Wüste umhergezogen sind; und so bin ich jetzt fünfundachtzig Jahre alt.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 14, 11, 'Ich bin heute noch so rüstig wie damals, als Mose mich aussandte; wie meine Kraft damals war, so ist sie jetzt noch zum Kriegsdienst, zum Ausmarsch und zur Heimkehr ausreichend.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 14, 12, 'So überweise mir nun dieses Bergland, von dem der HERR damals gesprochen hat; du selbst hast ja damals gehört, daß es dort noch Enakiter und große, feste Städte gibt; vielleicht ist der HERR mit mir, so daß ich sie nach der Verheißung des HERRN aus ihrem Besitz vertreiben kann.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 14, 13, 'Da segnete Josua den Kaleb, den Sohn Jephunnes, und verlieh ihm Hebron als Erbbesitz.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 14, 14, 'Auf diese Weise ist Hebron an Kaleb, den Sohn Jephunnes, den Kenissiten, als Erbbesitz bis auf den heutigen Tag gekommen, weil er nämlich dem HERRN, dem Gott Israels, vollen Gehorsam bewiesen hatte.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 14, 15, 'Hebron hieß aber ehemals Kirjath-Arba; Arba war der größte Mann unter den Enakitern gewesen. – Und das Land hatte Ruhe vom Kriege.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 1, 'Für die einzelnen Geschlechter des Stammes Juda aber fiel das Los südwärts nach dem Gebiet der Edomiter, nach der Wüste Zin hin im äußersten Süden des Landes;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 2, 'und zwar geht ihre Südgrenze vom Ende des Salzmeeres, von seiner Südspitze aus,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 3, 'läuft dann weiter gegen die Südseite der Skorpionenhöhe, dann nach Zin hinüber, steigt aufwärts südlich von Kades-Barnea, geht dann weiter nach Hezron, zieht sich aufwärts nach Addar, wendet sich herum nach Karka,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 4, 'geht dann nach Azmon hinüber und setzt sich fort bis an den Bach Ägyptens, bis sie nach dem Meere hin ihr Ende erreicht: dies soll eure Südgrenze sein. –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 5, 'Die Ostgrenze aber bildet das Salzmeer bis zur Jordanmündung – und die Nordgrenze geht vom Nordende des Salzmeeres, von der Jordanmündung aus;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 6, 'dann zieht sich die Grenze hinauf nach Beth-Holga und läuft weiter bis nördlich von Beth-Araba; dann zieht die Grenze sich aufwärts zum Felsen Bohans, des Sohnes Rubens,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 7, 'geht dann vom Tal Achor aufwärts nach Debir, läuft mit veränderter Richtung nordwärts nach Gilgal, das der Anhöhe Adummim gegenüber liegt, die sich südlich von dem Bache befindet; dann zieht sich die Grenze hinüber nach dem Wasser En-Semes und läuft weiter nach der Quelle Rogel;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 8, 'sodann geht sie im Tale Ben-Hinnom hinauf südlich vom Bergrücken der Jebusiter, das ist Jerusalem; weiter zieht die Grenze sich hinauf zu dem Gipfel des Berges, der westlich vor dem Tale Hinnom am Nordende der Talebene Rephaim liegt;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 9, 'dann biegt die Grenze vom Gipfel des Berges um nach der Quelle des Wassers Nephthoah, läuft weiter nach den Ortschaften des Ephrongebirges hin und zieht mit veränderter Richtung nach Baala, das ist Kirjath-Jearim;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 10, 'von Baala wendet sie sich dann westwärts nach dem Gebirge Seir, geht hierauf hinüber nach der Nordseite des Berges Jearim, das ist Kesalon, senkt sich hinab nach Beth-Semes und weiter nach Thimna;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 11, 'dann läuft die Grenze weiter an den Nordabhang des Berges Ekron und mit veränderter Richtung nach Sikkeron, geht dann hinüber nach dem Berge von Baala, läuft weiter bis Jabneel und erreicht schließlich ihr Ende am Meer. –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 12, 'Die Westgrenze aber bildet das große Meer und sein Küstenland. Das ist die Grenze des Stammes der Judäer ringsum für ihre Geschlechter.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 13, 'Kaleb aber, dem Sohne Jephunnes, gab Josua einen Landbesitz mitten im Stamme Juda nach dem Befehl des HERRN an Josua, nämlich die Stadt Arbas, des Stammvaters der Enakiter, das ist Hebron.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 14, 'Kaleb vertrieb dann von dort die drei Enakssöhne Sesai, Ahiman und Thalmai, die Abkömmlinge Enaks,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 15, 'und zog von dort weiter gegen die Bewohner von Debir, das ehemals Kirjath-Sepher geheißen hatte.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 16, 'Als nun Kaleb bekanntmachte: »Wer Kirjath-Sepher bezwingt und erobert, dem gebe ich meine Tochter Achsa zur Frau«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 17, 'und Othniel, der Sohn des Kenas, ein Bruder Kalebs, die Stadt eroberte, gab er ihm seine Tochter Achsa zur Frau.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 18, 'Als sie ihm nun zugeführt wurde, überredete sie ihn, ein Stück Ackerland von ihrem Vater erbitten zu dürfen, und als sie dann vom Esel herabsprang und Kaleb sie fragte: »Was wünschest du?«,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 19, 'antwortete sie: »Gib mir doch ein Abschiedsgeschenk! Weil du mich in das Südland verheiratet hast, so gib mir auch Wasserquellen!« Da gab er ihr die oberen und die unteren Brunnen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 20, 'Folgendes ist der Erbbesitz der einzelnen Geschlechter des Stammes Juda.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 21, 'Es liegen nämlich im südlichen Teil des Stammes Juda nach dem Gebiet der Edomiter hin die Ortschaften: Kabzeel, Eder, Jagur,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 22, 'Kina, Dimona, Adada,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 23, 'Kedes, Hazor und Jithnan;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 24, 'Siph, Telem, Bealoth,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 25, 'Hazor-Hadattha und Kerioth-Hezron, das ist Hazor;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 26, 'Amam, Sema, Molada,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 27, 'Hazar-Gadda, Hesmon, Beth-Pelet,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 28, 'Hazar-Sual, Beerseba, Bisjothja;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 29, 'Baala, Ijjim, Ezem,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 30, 'Eltholad, Kesil, Horma,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 31, 'Ziklag, Madmanna, Sansanna,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 32, 'Lebaoth, Silhim, Ain und Rimmon: im ganzen 29 Ortschaften nebst den zugehörigen Dörfern.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 33, 'In der Niederung: Esthaol, Zora, Asna,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 34, 'Sanoah und En-Gannim, Thappuah und Enam,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 35, 'Jarmuth und Adullam, Socho, Aseka,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 36, 'Saaraim, Adithaim, Gedera und Gederothaim: 14 Ortschaften nebst den zugehörigen Dörfern.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 37, 'Zenan, Hadasa, Migdal-Gad,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 38, 'Dilgan, Mizpe und Joktheel;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 39, 'Lachis, Bozkath, Eglon,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 40, 'Kabbon, Lahmas, Kithlis');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 41, 'und Gederoth, Beth-Dagon, Naama und Makkeda: 16 Ortschaften mit den zugehörigen Dörfern.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 42, 'Libna, Ether, Asan,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 43, 'Jiphthah, Asna, Nezib,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 44, 'Kegila, Achsib und Maresa: 9 Ortschaften mit den zugehörigen Dörfern.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 45, 'Ekron mit den zugehörigen Ortschaften und Dörfern.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 46, 'Von Ekron an, und zwar nach dem Meere zu, alles, was seitlich von Asdod und den zugehörigen Dörfern liegt:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 47, 'Asdod mit den zugehörigen Ortschaften und Dörfern; Gaza mit den zugehörigen Ortschaften und Dörfern bis an den Bach Ägyptens; die Westgrenze aber bildet das große Meer nebst seinem Küstenlande.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 48, 'Ferner im Berglande: Samir, Jatthir, Socho,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 49, 'Danna, Kirjath-Sanna, das ist Debir,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 50, 'Anab, Esthemo, Anim,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 51, 'Gosen, Holon und Gilo: 11 Ortschaften mit den zugehörigen Dörfern.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 52, 'Arab, Duma, Esgan,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 53, 'Janum, Beth-Thappuah, Apheka,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 54, 'Humta, Kirjath-Arba, das ist Hebron, und Zior: 9 Ortschaften mit den zugehörigen Dörfern.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 55, 'Maon, Karmel, Siph, Juta,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 56, 'Jesreel, Jokdeam, Sanoah,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 57, 'Kain, Gibea und Thimna: 10 Ortschaften mit den zugehörigen Dörfern.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 58, 'Halhul, Beth-Zur, Gedor,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 59, 'Maarath, Beth-Anoth und Elthekon: 6 Ortschaften mit den zugehörigen Dörfern.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 60, 'Kirjath-Baal, das ist Kirjath-Jearim, und Rabba: 2 Ortschaften mit den zugehörigen Dörfern.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 61, 'In der Steppe: Beth-Araba, Middin, Sechacha,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 62, 'Nibsan und die Salzstadt und Engedi: 6 Ortschaften mit den zugehörigen Dörfern.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 63, 'Was aber die Jebusiter, die Bewohner von Jerusalem, anbetrifft, so vermochte der Stamm Juda sie nicht zu vertreiben; daher sind die Jebusiter in Jerusalem neben den Judäern wohnen geblieben bis auf den heutigen Tag.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 16, 1, 'Sodann fiel den Nachkommen Josephs durch das Los ihr Anteil zu vom Jordan bei Jericho an und begriff im Osten das Uferland von Jericho, dann die Wüste, die sich von Jericho an aufsteigend im Gebirge nach Bethel erstreckt.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 16, 2, 'Die Grenze läuft dann von Bethel weiter nach Lus und zieht sich hinüber nach dem Gebiet der Arkiter, nach Atharoth,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 16, 3, 'läuft hierauf westwärts hinab zum Gebiet der Japhletiter bis zum Gebiet von Unter-Beth-Horon und bis Geser; ihr Endpunkt liegt dann am Meer.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 16, 4, 'Dies ist der Erbbesitz, den die Nachkommen Josephs, die Stämme Manasse und Ephraim, erhielten.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 16, 5, 'Dies aber ist das Gebiet der Geschlechter des Stammes Ephraim: Die Grenze ihres Erbteils geht nämlich im Osten von Ateroth-Addar bis Ober-Beth-Horon;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 16, 6, 'von da läuft die Grenze dem Meere zu. – Im Norden bildet Michmethath die Grenze, und zwar wendet sich die Grenze ostwärts nach Thaanath-Silo und geht daran östlich vorbei nach Janoha.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 16, 7, 'Von Janoha senkt sie sich nach Ataroth und Naarath hinab, berührt dann Jericho und endet am Jordan.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 16, 8, 'Von Thappuah aus geht die Grenze westwärts an den Bach Kana und erreicht ihr Ende am Meer. Dies ist der Erbbesitz des Stammes Ephraim, auf die einzelnen Geschlechter verteilt.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 16, 9, 'Dazu kommen noch die Städte, die für die Ephraimiten mitten im Erbteil der Manassiten abgesondert waren, sämtliche Städte mit den zugehörigen Dörfern.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 16, 10, 'Sie vertrieben aber die Kanaanäer nicht, die in Geser wohnten; daher sind die Kanaanäer mitten unter den Ephraimiten wohnen geblieben bis auf den heutigen Tag und sind nur fronpflichtig geworden.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 17, 1, 'Sodann fiel dem Stamm Manasse – dieser war nämlich der erstgeborene Sohn Josephs – sein Losanteil zu. Machir, dem erstgeborenen Sohne Manasses, dem Vater Gileads, wurde Gilead und Basan zuteil, denn er war ein Kriegsmann.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 17, 2, 'Sodann erhielten die übrigen Nachkommen Manasses, Geschlecht für Geschlecht, ihren Anteil, nämlich die Nachkommen Abiesers, die Nachkommen Heleks, die Nachkommen Asriels, die Nachkommen Sichems, die Nachkommen Hephers und die Nachkommen Semidas; dies waren die männlichen Nachkommen Manasses, des Sohnes Josephs, Geschlecht für Geschlecht.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 17, 3, 'Aber Zelophhad, der Sohn Hephers, des Sohnes Gileads, des Sohnes Machirs, des Sohnes Manasses, hatte keine Söhne, sondern nur Töchter; deren Namen waren Mahla, Noa, Hogla, Milka und Thirza.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 17, 4, 'Diese traten nun vor den Priester Eleasar und vor Josua, den Sohn Nuns, und vor die Fürsten und sagten: »Der HERR hat Mose geboten, uns ein Erbteil unter unsern Stammesgenossen zu geben.« Da überwies er ihnen nach dem Befehl des HERRN ein Erbteil unter den Stammesgenossen ihres Vaters;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 17, 5, 'und so fielen dem Stamm Manasse zehn Losanteile zu, abgesehen von der Landschaft Gilead und Basan, die jenseits des Jordans liegen;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 17, 6, 'denn die weiblichen Nachkommen Manasses erhielten ein Erbteil gerade wie seine männlichen Nachkommen; die Landschaft Gilead aber kam an die übrigen Nachkommen Manasses.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 17, 7, 'Es geht aber die Grenze des Stammes Manasse von Asser nach Michmethath, das östlich von Sichem liegt; dann geht die Grenze südwärts zu den Bewohnern von En-Thappuah hin.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 17, 8, 'Die Landschaft Thappuah gehört zum Stamm Manasse; die Stadt Thappuah selbst aber, an der Grenze von Manasse, gehört zum Stamme Ephraim.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 17, 9, 'Dann geht die Grenze hinab zum Bache Kana, südlich von dem Bache – die dort mitten unter den Städten Manasses liegenden Ortschaften gehören zum Stamm Ephraim –; alsdann aber läuft die Grenze nördlich vom Bache und endet am Meer;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 17, 10, 'die Südseite ist ephraimitisch, die Nordseite manassitisch, und das Meer bildet hier die Grenze; nordwärts aber stoßen sie an Asser, ostwärts an Issaschar.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 17, 11, 'Außerdem erhielt der Stamm Manasse in Issaschar und in Asser folgende Städte: Beth-Sean mit den zugehörigen Ortschaften, ferner Jibleam mit den zugehörigen Ortschaften sowie die Bewohner von Dor und von En-Dor mit den zugehörigen Ortschaften, die Bewohner von Thaanach mit den zugehörigen Ortschaften und die Bewohner von Megiddo mit den zugehörigen Ortschaften: das Dreihügelgebiet. –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 17, 12, 'Der Stamm Manasse vermochte jedoch nicht diese Städte zu erobern; daher gelang es den Kanaanäern, in dieser Gegend wohnen zu bleiben.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 17, 13, 'Als später aber die Israeliten erstarkten, machten sie die Kanaanäer fronpflichtig, ohne sie jedoch ganz vertreiben zu können.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 17, 14, 'Da wandten sich die beiden Josephstämme an Josua und trugen ihm folgendes vor: »Warum hast du mir nur ein Los und einen einzigen Anteil als Erbbesitz gegeben, obgleich ich doch ein zahlreiches Volk bin, da der HERR mich bisher gesegnet hat?«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 17, 15, 'Josua antwortete ihnen: »Wenn du ein zahlreiches Volk bist, so ziehe doch in den Wald hinauf und schaffe dir dort im Lande der Pherissiter und der Rephaiter durch Ausroden des Waldes Raum zum Wohnen, wenn dir das Bergland Ephraim zu enge ist.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 17, 16, 'Da entgegneten die Nachkommen Josephs: »Das Bergland reicht für uns nicht aus; alle Kanaanäer aber, die unten in der Ebene wohnen, haben eiserne Streitwagen, sowohl die, welche in Beth-Sean und den zugehörigen Ortschaften, als auch die, welche in der Ebene Jesreel wohnen.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 17, 17, 'Da antwortete Josua den beiden Josephstämmen Ephraim und Manasse: »Du bist ein sehr zahlreiches und sehr starkes Volk; so sollst du nicht nur ein Los erhalten;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 17, 18, 'denn ein Bergland wird dir zuteil werden. Da es Wald ist, mußt du ihn ausroden: dann werden auch die Ausläufer dir zuteil werden; denn du wirst die Kanaanäer vertreiben, wenn sie auch eiserne Wagen haben und wenn sie auch stark sind.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 18, 1, 'Hierauf versammelte sich die ganze Volksgemeinde der Israeliten in Silo und schlug dort das Offenbarungszelt auf; denn das Land lag unterworfen vor ihnen da.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 18, 2, 'Nun waren aber unter den Israeliten noch sieben Stämme übrig, deren Erbbesitz man noch nicht ausgeteilt hatte.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 18, 3, 'Da sagte Josua zu den Israeliten: »Wie lange wollt ihr noch lässig bleiben, statt hinzugehen, um das Land in Besitz zu nehmen, das der HERR, der Gott eurer Väter, euch gegeben hat?');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 18, 4, 'Bestimmt doch drei Männer aus jedem Stamm, so will ich sie aussenden, damit sie sich daranmachen, das Land zu durchwandern und es schriftlich aufzunehmen mit Rücksicht auf den für sie erforderlichen Erbbesitz. Wenn sie dann zu mir zurückgekommen sind,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 18, 5, 'mögen sie es in sieben Teile unter sich verteilen. Juda soll sein Gebiet im Süden behalten und das Haus Josephs auf seinem Gebiet im Norden bleiben;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 18, 6, 'ihr aber fertigt schriftlich eine Übersicht des Landes bei Zerlegung in sieben Teile an und bringt die Aufzeichnung mir hierher, so will ich das Los für euch werfen hier vor dem HERRN, unserm Gott.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 18, 7, 'Denn die Leviten erhalten keinen Landbesitz unter euch, weil das Priestertum des HERRN ihr Erbteil ist; Gad aber und Ruben und der halbe Stamm Manasse haben ihren Erbbesitz bereits im Ostjordanlande empfangen, den ihnen Mose, der Knecht Gottes, angewiesen hat.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 18, 8, 'Da machten sich die Männer auf den Weg, und Josua gab ihnen, als sie zur schriftlichen Aufnahme des Landes aufbrachen, die Weisung: »Geht hin, durchwandert das Land und nehmt es schriftlich auf; dann kommt wieder zu mir, so will ich hier zu Silo das Los für euch vor dem HERRN werfen.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 18, 9, 'So machten sich denn die Männer auf den Weg, zogen durch das Land und trugen es Stadt für Stadt unter Zerlegung in sieben Teile in ein Buch ein; dann kehrten sie zu Josua ins Lager nach Silo zurück.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 18, 10, 'Da warf Josua das Los für sie zu Silo vor dem HERRN, und Josua verteilte dort das Land unter die Israeliten, wie es ihren Anteilen entsprach.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 18, 11, 'So kam denn das Los für die Geschlechter des Stammes Benjamin heraus, und zwar kam das Gebiet, das ihnen durchs Los zufiel, zwischen die Stämme Juda und Joseph zu liegen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 18, 12, 'Ihre Nordgrenze begann aber am Jordan, zieht sich dann aufwärts nach dem Bergzuge nördlich von Jericho und von da auf das Gebirge nach Westen zu und endet nach der Wüste von Beth-Awen hin.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 18, 13, 'Von dort geht die Grenze dann nach Lus hinüber, nach dem Höhenzuge südlich von Lus, das ist Bethel; dann senkt sich die Grenze hinab nach Ateroth-Addar über den Berg, der südlich von Unter-Beth-Horon liegt.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 18, 14, 'Sodann zieht die Grenze in veränderter Richtung auf ihrer Westseite nach Süden von dem Berg an, der südlich Beth-Horon gegenüber liegt, und endet bei Kirjath-Baal, das ist die judäische Stadt Kirjath-Jearim. Dies ist die Westseite.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 18, 15, 'Die Südseite aber beginnt bei der Stadtgrenze von Kirjath-Jearim und setzt sich dann westwärts fort nach der Quelle des Wassers von Nephthoah;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 18, 16, 'dann läuft die Grenze hinab bis an das Ende des Berges, der östlich vom Tal Ben-Hinnom und nördlich von der Talebene Rephaim liegt, zieht dann in das Hinnomtal hinab südlich vom Bergrücken der Jebusiter und weiter hinab zur Quelle Rogel;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 18, 17, 'alsdann läuft sie mit veränderter Richtung nordwärts, und zwar nach En-Semes und weiter nach Geliloth hin, das der Anhöhe Adummim gegenüber liegt, senkt sich dann hinab zum Felsen Bohans, des Sohnes Rubens,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 18, 18, 'und geht hinüber zu dem Höhenzug, der nordwärts der Araba gegenüber liegt; hierauf senkt die Grenze sich in die Araba hinab,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 18, 19, 'läuft dann hinüber bis nördlich vom Bergrücken von Beth-Hogla und erreicht ihr Ende an der Nordspitze des Salzmeeres, am südlichen Ende des Jordans. Dies ist die Südgrenze.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 18, 20, 'Der Jordan aber bildet die Grenze auf der Ostseite. Dies ist der Erbbesitz der Geschlechter des Stammes Benjamin nach seinen Grenzen ringsum.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 18, 21, 'Die Städte der Geschlechter des Stammes Benjamin aber sind: Jericho, Beth-Hogla, Emek-Keziz,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 18, 22, 'Beth-Araba, Zemaraim, Bethel,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 18, 23, 'Awwim, Para, Ophra,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 18, 24, 'Kephar-Ammoni, Ophni und Geba: 12 Städte mit den zugehörigen Dörfern;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 18, 25, 'Gibeon, Rama, Beeroth,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 18, 26, 'Mizpe, Kephira, Moza,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 18, 27, 'Rekem, Jirpeel, Tharala,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 18, 28, 'Zela, Eleph und die Jebusiterstadt, das ist Jerusalem, Gibeath, Kirjath: 14 Städte mit den zugehörigen Dörfern. Das ist der Erbbesitz der Geschlechter des Stammes Benjamin.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 1, 'Dann kam das zweite Los heraus für Simeon, für die Geschlechter des Stammes der Simeoniten; und zwar lag ihr Erbteil mitten im Erbbesitz der Judäer.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 2, 'Es wurde ihnen aber als ihr Erbbesitz zuteil: Beerseba, Seba, Molada,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 3, 'Hazar-Sual, Bala, Ezem,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 4, 'Eltholad, Bethul, Horma,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 5, 'Ziklag, Beth-Markaboth, Hazar-Susa,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 6, 'Beth-Lebaoth und Saruhen: 13 Städte mit den zugehörigen Dörfern.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 7, 'Ferner Ain, Rimmon, Ether und Asan: 4 Städte mit den zugehörigen Dörfern;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 8, 'außerdem alle Dörfer, die rings um diese Städte liegen bis nach Baalath-Beer, dem Rama des Südlandes. Dies ist der Erbbesitz der Geschlechter des Stammes Simeon.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 9, 'Von dem Anteil der Judäer war der Erbbesitz der Simeoniten genommen; denn der Anteil der Judäer war für diese zu groß; daher erhielten die Simeoniten ihren Erbbesitz mitten in deren Besitztum.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 10, 'Hierauf kam das dritte Los heraus für die Geschlechter des Stammes Sebulon; und die Grenze ihres Erbbesitzes reichte bis Sarid.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 11, 'Ihre Grenze geht aber westwärts hinauf, und zwar nach Marala hin, berührt Dabbeseth und stößt an den Bach, der östlich von Jokneam fließt.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 12, 'Aber auf der östlichen Seite von Sarid, gegen Sonnenaufgang, wendet sie sich nach dem Gebiet von Kisloth-Thabor, geht weiter nach Daberath, zieht sich aufwärts nach Japhia,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 13, 'läuft von da ostwärts, gegen Sonnenaufgang, nach Gath-Hepher, nach Eth-Kazin hinüber, läuft aus bei Rimmon und erstreckt sich nach Nea hin;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 14, 'dann zieht sich die Grenze mit veränderter Richtung um dasselbe herum nördlich von Hannathon und erreicht ihr Ende im Tal von Jiphthah-El.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 15, '... und Kattath, Nahalal, Simron, Jidala und Bethlehem: 12 Städte mit den zugehörigen Dörfern.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 16, 'Dies war der Erbbesitz der Geschlechter des Stammes Sebulon: die genannten Städte mit den zugehörigen Dörfern.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 17, 'Für Issaschar kam das vierte Los heraus, für die Geschlechter der Issaschariten.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 18, 'Ihr Gebiet erstreckte sich über Jesreel, Kesulloth, Sunem,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 19, 'Hapharaim, Sion, Anaharath,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 20, 'Rabbith, Kisjon, Ebez,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 21, 'Remeth, En-Gannim, En-Hadda und Beth-Pazzez.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 22, 'Die Grenze berührt Thabor, Sahazima und Beth-Semes, und ihre Grenze endet am Jordan: 16 Städte mit den zugehörigen Dörfern.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 23, 'Dies war der Erbbesitz der Geschlechter des Stammes der Issaschariten: die Städte mit den zugehörigen Dörfern.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 24, 'Dann kam das fünfte Los heraus für die Geschlechter des Stammes Asser.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 25, 'Ihr Gebiet umfaßte Helkath, Hali, Beten, Achsaph,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 26, 'Allammelech, Amgad und Miseal und stößt westwärts an den Karmel und an den Sihor von Libnath.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 27, 'Sodann wendet sich die Grenze ostwärts nach Beth-Dagon, berührt Sebulon und das Tal Jiphthah-El im Norden, dann Beth-Emek und Negiel und setzt sich nordwärts fort nach Kabul,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 28, 'Ebron, Rehob, Hammon und Kana bis zu der großen Stadt Sidon;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 29, 'dann zieht die Grenze mit veränderter Richtung nach Rama und bis zu der festen Stadt Tyrus, sodann mit veränderter Richtung nach Hossa und endet am Meer. Mahaleb, Aksib,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 30, 'Umma, Aphek und Rehob: 22 Städte mit den zugehörigen Dörfern.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 31, 'Dies war der Erbbesitz der Geschlechter des Stammes Asser: die genannten Städte mit den zugehörigen Dörfern.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 32, 'Für den Stamm Naphthali kam das sechste Los heraus, für die Geschlechter der Naphthaliten.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 33, 'Ihre Grenze geht von Heleph, von der Eiche bei Zaanannim, über Adami-Nekeb und Jabneel bis Lakkum und endet am Jordan;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 34, 'dann geht die Grenze mit veränderter Richtung westwärts nach Asnoth-Thabor, setzt sich fort nach Hukkok hin, berührt dann im Süden Sebulon, stößt im Westen an Asser und im Osten an den Jordan.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 35, 'Die festen Städte waren: Ziddim, Zer und Hammath, Rakkath, Kinnereth,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 36, 'Adama, Rama, Hazor,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 37, 'Kedes, Edrei, En-Hazor,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 38, 'Jireon, Migdal-El, Horem, Beth-Anath und Beth-Semes: 19 Städte mit den zugehörigen Dörfern.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 39, 'Dies war der Erbbesitz der Geschlechter des Stammes der Naphthaliten: die Städte mit den zugehörigen Dörfern.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 40, 'Für die Geschlechter des Stammes Dan kam das siebte Los heraus.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 41, 'Das Gebiet ihres Erbteils umfaßte: Zorga, Esthaol, Ir-Semes,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 42, 'Saalabbin, Ajjalon, Jithla,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 43, 'Elon, Thimnath, Ekron,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 44, 'Eltheke, Gibbethon, Baalath,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 45, 'Jehud, Bene-Berak, Gath-Rimmon,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 46, 'Me-Jarkon und Rakkon samt dem Gebiete gegen Japho hin.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 47, 'Als das Gebiet den Daniten später zu enge wurde, zogen sie hinauf und bekriegten Lesem (Lais); und nachdem sie es erobert und die Einwohner mit der Schärfe des Schwertes niedergemacht hatten, nahmen sie es in Besitz, siedelten sich dort an und gaben Lesem den Namen »Dan« nach ihrem Stammvater Dan.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 48, 'Dies war der Erbbesitz der Geschlechter des Stammes Dan: die genannten Städte mit den zugehörigen Dörfern.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 49, 'Als nun die Israeliten mit der Verteilung des Landes nach seinem ganzen Umfang fertig waren, gaben sie Josua, dem Sohne Nuns, ein Besitztum in ihrer Mitte.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 50, 'Nach dem Befehl des HERRN gaben sie ihm die Stadt, die er sich erbeten hatte, nämlich Thimnath-Serah im Berglande Ephraim; er befestigte dann die Stadt und ließ sich in ihr nieder.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 51, 'Dies sind die Erbteile, die der Priester Eleasar und Josua, der Sohn Nuns, und die Stammeshäupter der Israeliten in Silo vor dem HERRN am Eingang des Offenbarungszeltes durch das Los verteilten. Als sie dann mit der Verteilung des Landes fertig waren,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 20, 1, 'gebot der HERR dem Josua folgendes:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 20, 2, '»Mache den Israeliten folgende Mitteilung: ›Bestimmt euch noch die Zufluchtsstädte, von denen ich zu euch durch Mose gesagt habe,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 20, 3, 'daß ein Totschläger dahin fliehen solle, der jemand aus Versehen, unvorsätzlich, getötet hat; die sollen euch als Zufluchtsstätten vor dem Bluträcher dienen.‹');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 20, 4, 'Flüchtet er sich dann in eine von diesen Städten und bleibt am Eingang des Stadttores stehen und trägt den Ältesten der betreffenden Stadt seine Sache vor, so sollen sie ihn bei sich in der Stadt aufnehmen und ihm einen Ort anweisen, daß er bei ihnen wohnen kann.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 20, 5, 'Wenn dann der Bluträcher ihn verfolgt, so dürfen sie ihm den Totschläger nicht ausliefern, weil er den andern unvorsätzlich getötet hat, ohne ihm schon früher feind gewesen zu sein.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 20, 6, 'Er soll vielmehr in der betreffenden Stadt wohnen bleiben, bis er vor der Gemeinde gestanden hat, um abgeurteilt zu werden, und dann bis zum Tode des derzeitigen Hohenpriesters; alsdann darf der Totschläger wieder in seine Ortschaft und in sein Haus zurückkehren, in die Ortschaft, aus der er geflohen war.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 20, 7, 'Da machten die Israeliten Kedes in Galiläa im Gebirge Naphthali und Sichem im Berglande auf dem Gebirge Ephraim und Kirjath-Arba, das ist Hebron, im Gebirge Juda zu geweihten Zufluchtsstätten.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 20, 8, 'Jenseits des Jordans aber, östlich von Jericho, bestimmten sie zu derartigen Städten Bezer in der Steppe, auf der Hochebene im Stamme Ruben, ferner Ramoth in Gilead im Stamme Gad, und Golan in Basan im Stamme Manasse.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 20, 9, 'Dies waren die Städte, die man für alle Israeliten und für die unter ihnen lebenden Fremdlinge dazu bestimmte, daß jeder, der einen andern unvorsätzlich getötet hätte, sich dorthin flüchten sollte, damit er nicht durch die Hand des Bluträchers den Tod fände, ehe er vor der Gemeinde gestanden hätte.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 1, 'Hierauf traten die Familienhäupter der Leviten zu dem Priester Eleasar und zu Josua, dem Sohne Nuns, und zu den Häuptern der israelitischen Stämme');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 2, 'und sagten zu ihnen in Silo im Lande Kanaan: »Der HERR hat durch Mose geboten, daß man uns Städte zu Wohnsitzen und die zugehörigen Weidetriften für unser Vieh anweise.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 3, 'So überwiesen denn die Israeliten von ihrem Erbbesitz den Leviten nach dem Gebot des HERRN folgende Städte nebst den zugehörigen Weidetriften:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 4, 'Als das Los für die Familien der Kahathiten herauskam, erhielten unter den Leviten die Nachkommen des Priesters Aaron von den Stämmen Juda, Simeon und Benjamin durch das Los dreizehn Städte;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 5, 'die übrigen Nachkommen Kahaths aber erhielten durch das Los zehn Städte von den Geschlechtern der Stämme Ephraim, Dan und halb Manasse. –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 6, 'Die Nachkommen Gersons erhielten durch das Los dreizehn Städte von den Geschlechtern der Stämme Issaschar, Asser, Naphthali und halb Manasse in Basan. –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 7, 'Die Familien der Nachkommen Meraris erhielten zwölf Städte von den Stämmen Ruben, Gad und Sebulon.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 8, 'Diese Städte also mit den zugehörigen Weidetriften wiesen die Israeliten den Leviten durch das Los zu, wie der HERR es durch Mose geboten hatte.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 9, 'Sie traten aber von seiten der Stämme Juda und Simeon folgende mit Namen bezeichnete Städte ab:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 10, 'den Nachkommen Aarons – denn auf sie fiel das erste Los – wurde von den Familien der Kahathiten unter den Leviten folgendes zuteil:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 11, 'man gab ihnen die Stadt Arbas, des Vaters Enaks, das ist Hebron, im Gebirge Juda, samt den zugehörigen Weidetriften rings um die Stadt her;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 12, 'aber das zur Stadt gehörige Ackerland nebst den zugehörigen Dörfern hatten sie Kaleb, dem Sohne Jephunnes, als seinen Besitz gegeben.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 13, 'Sie überwiesen also den Nachkommen des Priesters Aaron Hebron, die Zufluchtsstadt für Totschläger, nebst den zugehörigen Weidetriften, außerdem Libna nebst den zugehörigen Weidetriften,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 14, 'Jatthir nebst den zugehörigen Weidetriften, Esthemoa nebst den zugehörigen Weidetriften,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 15, 'Holon nebst den zugehörigen Weidetriften, Debir nebst den zugehörigen Weidetriften,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 16, 'Asan nebst den zugehörigen Weidetriften, Jutta nebst den zugehörigen Weidetriften, Beth-Semes nebst den zugehörigen Weidetriften: neun Städte von diesen beiden Stämmen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 17, 'Ferner vom Stamme Benjamin: Gibeon nebst den zugehörigen Weidetriften, Geba nebst den zugehörigen Weidetriften,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 18, 'Anathoth nebst den zugehörigen Weidetriften und Almon nebst den zugehörigen Weidetriften: vier Städte.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 19, 'Demnach erhielten die Nachkommen Aarons, die Priester, im ganzen dreizehn Städte nebst den zugehörigen Weidetriften.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 20, 'Was sodann die Familien der übrigen zu den Leviten gehörenden Nachkommen Kahaths betrifft, so waren die ihnen durch das Los zugefallenen Städte vom Gebiet des Stammes Ephraim genommen;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 21, 'und zwar überwies man ihnen Sichem, die Zufluchtsstadt für Totschläger, nebst den zugehörigen Weidetriften im Gebirge Ephraim; ferner Geser nebst den zugehörigen Weidetriften,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 22, 'Kibzaim nebst den zugehörigen Weidetriften und Beth-Horon nebst den zugehörigen Weidetriften: vier Städte.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 23, 'Ferner vom Stamme Dan: Eltheke nebst den zugehörigen Weidetriften, Gibbethon nebst den zugehörigen Weidetriften,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 24, 'Ajjalon nebst den zugehörigen Weidetriften, Gath-Rimmon nebst den zugehörigen Weidetriften: vier Städte.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 25, 'Sodann vom halben Stamme Manasse: Thaanach nebst den zugehörigen Weidetriften und Gath-Rimmon nebst den zugehörigen Weidetriften: zwei Städte.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 26, 'Demnach erhielten die Familien der übrigen Nachkommen Kahaths im ganzen zehn Städte nebst den zugehörigen Weidetriften.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 27, 'Weiter erhielten unter den Geschlechtern der Leviten die Nachkommen Gersons vom halben Stamm Manasse: Golan in Basan, die Zufluchtsstadt für Totschläger, nebst den zugehörigen Weidetriften, und Beesthera nebst den zugehörigen Weidetriften: zwei Städte.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 28, 'Ferner vom Stamme Issaschar: Kisjon nebst den zugehörigen Weidetriften, Daberath nebst den zugehörigen Weidetriften,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 29, 'Jarmuth nebst den zugehörigen Weidetriften und En-Gannim nebst den zugehörigen Weidetriften: vier Städte.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 30, 'Weiter vom Stamme Asser: Miseal nebst den zugehörigen Weidetriften, Abdon nebst den zugehörigen Weidetriften,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 31, 'Helkath nebst den zugehörigen Weidetriften und Rehob nebst den zugehörigen Weidetriften: vier Städte.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 32, 'Sodann vom Stamme Naphthali: Kedes in Galiläa, die Zufluchtsstadt für Totschläger, nebst den zugehörigen Weidetriften, Hammoth-Dor nebst den zugehörigen Weidetriften und Karthan nebst den zugehörigen Weidetriften: drei Städte.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 33, 'Demnach erhielten die Familien der Gersoniten im ganzen dreizehn Städte nebst den zugehörigen Weidetriften.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 34, 'Die Familien der Nachkommen Meraris aber, die noch übrigen Leviten, erhielten vom Stamme Sebulon: Jokneam nebst den zugehörigen Weidetriften, Kartha nebst den zugehörigen Weidetriften,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 35, 'Dimna nebst den zugehörigen Weidetriften und Nahalal nebst den zugehörigen Weidetriften: vier Städte.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 36, 'Ferner vom Stamme Ruben: Bezer, (die Zufluchtsstadt für Totschläger,) nebst den zugehörigen Weidetriften, Jahza nebst den zugehörigen Weidetriften,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 37, 'Kedemoth nebst den zugehörigen Weidetriften und Mephaath nebst den zugehörigen Weidetriften: vier Städte.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 38, 'Weiter vom Stamme Gad: Ramoth in Gilead, die Zufluchtsstadt für Totschläger, nebst den zugehörigen Weidetriften, Mahanaim nebst den zugehörigen Weidetriften,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 39, 'Hesbon nebst den zugehörigen Weidetriften, Jaser nebst den zugehörigen Weidetriften: im ganzen vier Städte.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 40, 'Demnach erhielten die Familien der Nachkommen Meraris, die von den Geschlechtern der Leviten noch übrig waren, als Losanteil zwölf Städte.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 41, 'Die Gesamtzahl der levitischen Städte inmitten des Erbbesitzes der Israeliten betrug achtundvierzig Städte nebst den zugehörigen Weidetriften.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 42, 'Diese Städte hatten ausnahmslos ihre Weidetriften rings um sich her: so verhielt es sich bei allen diesen Städten.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 43, 'So hatte also der HERR den Israeliten das ganze Land gegeben, dessen Verleihung er ihren Vätern zugeschworen hatte; sie hatten es in Besitz genommen und sich darin niedergelassen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 44, 'Und der HERR verschaffte ihnen Ruhe auf allen Seiten, ganz so, wie er es ihren Vätern zugeschworen hatte; denn keiner von all ihren Feinden hatte ihnen widerstehen können: alle ihre Feinde hatte der HERR in ihre Gewalt gegeben.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 45, 'Von allen Segensverheißungen, die der HERR dem Hause Israel gegeben hatte, war keine einzige unerfüllt geblieben: alle waren eingetroffen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 22, 1, 'Damals berief Josua die Stämme Ruben, Gad und halb Manasse');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 22, 2, 'und sagte zu ihnen: »Ihr habt alles erfüllt, was euch Mose, der Knecht des HERRN, geboten hat, und habt euch auch mir gegenüber in allem, was ich euch befohlen habe, gehorsam bewiesen:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 22, 3, 'ihr habt eure Volksgenossen diese lange Zeit hindurch bis auf den heutigen Tag nicht im Stich gelassen und das Gebot des HERRN, eures Gottes, treu erfüllt.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 22, 4, 'Da nun aber der HERR, euer Gott, euren Volksgenossen Ruhe verschafft hat, wie er ihnen verheißen hatte, so kehrt jetzt zu euren Zelten zurück, in das euch gehörige Land, das euch Mose, der Knecht des HERRN, jenseits des Jordans zugewiesen hat.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 22, 5, 'Nur seid auf die genaue Beobachtung des Gesetzes und der Gebote bedacht, die euch Mose, der Knecht des HERRN, zur Pflicht gemacht hat, daß ihr den HERRN, euren Gott, liebt und allezeit auf seinen Wegen wandelt, seine Gebote beobachtet und ihm treu bleibt und ihm von ganzem Herzen und mit ganzer Seele dient!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 22, 6, 'Als Josua sie dann mit Segenswünschen verabschiedet hatte, kehrten sie zu ihren Zelten zurück.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 22, 7, 'Der einen Hälfte des Stammes Manasse aber hatte Mose in Basan Landbesitz gegeben; der andern Hälfte dagegen hatte Josua bei ihren Volksgenossen im Westjordanlande ihren Erbbesitz angewiesen. Als Josua sie nun in ihre Heimat entließ, segnete er auch sie');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 22, 8, 'und sagte zu ihnen: »Kehrt zu euren Zelten zurück mit vielen Schätzen und mit einem sehr großen Viehbesitz, mit Silber und Gold, mit Kupfer, Eisen und Kleidern in großer Menge. Teilt das, was ihr von euren Feinden erbeutet habt, mit euren Brüdern!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 22, 9, 'So kehrten denn die Stämme Ruben, Gad und halb Manasse zurück und verließen die übrigen Israeliten in Silo, das im Lande Kanaan liegt, um in das ihnen gehörige Land Gilead heimzuziehen, wo sie sich nach dem durch Mose verkündigten Befehl des HERRN ansässig gemacht hatten.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 22, 10, 'Als sie nun an die Steinkreise am Jordan gekommen waren, die noch im Lande Kanaan liegen, da bauten die Stämme Ruben, Gad und halb Manasse dort einen Altar am Jordan, einen großen, weithin sichtbaren Altar.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 22, 11, 'Als aber die (übrigen) Israeliten die Kunde erhielten: »Die Stämme Ruben, Gad und halb Manasse haben den Altar gerade dem Lande Kanaan gegenüber bei den Steinkreisen am Jordan, auf der anderen Seite des Gebietes der Israeliten, gebaut« –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 22, 12, 'als die Israeliten das erfuhren, da versammelte sich die ganze Gemeinde der Israeliten in Silo, um gegen sie zu Felde zu ziehen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 22, 13, 'Da sandten die Israeliten an die Stämme Ruben, Gad und halb Manasse in das Land Gilead Pinehas, den Sohn des Priesters Eleasar,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 22, 14, 'und zehn Fürsten mit ihm, je einen Fürsten von jedem Stamme, von sämtlichen israelitischen Stämmen, von denen jeder das Oberhaupt der Familien seines Stammes unter den Tausendschaften Israels war.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 22, 15, 'Als diese zu den Stämmen Ruben, Gad und halb Manasse in das Land Gilead gekommen waren, besprachen sie sich mit ihnen und sagten:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 22, 16, '»Die ganze Gemeinde des HERRN läßt euch folgendes sagen: Was ist das für eine Treulosigkeit, die ihr euch gegen den Gott Israels habt zuschulden kommen lassen, daß ihr euch heute vom HERRN abwendet, indem ihr euch einen Altar baut und euch so gegen den HERRN auflehnt?');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 22, 17, 'Haben wir noch nicht genug an der Versündigung bezüglich Peors, von der wir uns bis auf den heutigen Tag noch nicht gereinigt haben und um deretwillen das Sterben über die Gemeinde des HERRN kam?');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 22, 18, 'Und ihr wollt euch dennoch heute vom HERRN lossagen? Die Folge davon wird sein: wenn ihr euch heute gegen den HERRN auflehnt, so wird er morgen seinen Zorn an der ganzen Gemeinde Israel auslassen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 22, 19, 'Wenn übrigens das Land, das ihr innehabt, nach eurer Ansicht unrein ist, so kommt doch in das Eigentumsland des HERRN herüber, wo sich die Wohnstätte des HERRN befindet, und macht euch mitten unter uns ansässig! Aber lehnt euch nicht gegen den HERRN auf und lehnt euch nicht gegen uns auf, indem ihr euch außer dem Altar des HERRN, unsres Gottes, noch einen besonderen Altar erbaut!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 22, 20, 'Ist nicht damals, als Achan, der Sohn Serahs, sich treuloserweise an dem gebannten Gut vergriffen hatte, ein Zorngericht über die ganze Gemeinde Israel ergangen, obgleich er nur ein einzelner Mann war? Hat er nicht sein Vergehen mit dem Tode büßen müssen?«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 22, 21, 'Da antworteten die Stämme Ruben, Gad und halb Manasse den Häuptern der Tausendschaften Israels folgendermaßen:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 22, 22, '»Der Starke, Gott der HERR, ja der Starke, Gott der HERR, der weiß es, und Israel soll es wissen: Wenn es aus Auflehnung und wenn es aus Treulosigkeit gegen den HERRN geschehen ist, so möge uns am heutigen Tage keine Rettung von dir (o Pinehas) zuteil werden!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 22, 23, 'Wenn wir uns einen Altar erbaut haben, um uns vom HERRN abzuwenden, oder wenn es zu dem Zweck geschehen ist, daß wir auf ihm Brandopfer und Speisopfer darbringen oder Heilsopfer auf ihm herrichten wollten, so möge der HERR selbst es ahnden!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 22, 24, 'Nein, nur aus Besorgnis vor einer gewissen Sache haben wir das getan, weil wir nämlich dachten, künftig würden eure Kinder zu unsern Kindern sagen: ›Was habt ihr mit dem HERRN, dem Gott Israels, gemein?');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 22, 25, 'Der HERR hat ja doch den Jordan zur Grenze zwischen uns und euch Rubeniten und Gaditen gemacht: ihr habt keinen Anteil am HERRN!‹ Dadurch würden eure Kinder dann die unsrigen davon abbringen, den HERRN zu fürchten.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 22, 26, 'Darum dachten wir: Wir wollen uns doch daranmachen, den Altar zu bauen, nicht für Brandopfer und nicht für Schlachtopfer;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 22, 27, 'sondern er soll zwischen uns und euch und zwischen unsern künftigen Geschlechtern ein Zeugnis sein, daß wir dem Dienst des HERRN vor ihm mit unsern Brandopfern, unsern Schlachtopfern und unsern Heilsopfern obliegen (wollen); sonst könnten eure Kinder künftig zu unsern Kindern sagen: ›Ihr habt keinen Anteil am HERRN!‹');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 22, 28, 'Wir dachten also: Wenn sie künftig zu uns oder unsern Nachkommen so sprechen sollten, dann wollen wir entgegnen: ›Seht euch doch die Bauart des Gottesaltars an, den unsere Väter errichtet haben, nicht für Brandopfer und nicht für Schlachtopfer, sondern zum Zeugnis zwischen uns und euch!‹');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 22, 29, 'Fern sei es von uns, daß wir uns gegen den HERRN auflehnen (wollen) und uns heute vom HERRN abwenden, indem wir für Brandopfer, für Speisopfer und für Schlachtopfer noch einen besonderen Altar bauen außer dem Altar des HERRN, unseres Gottes, der vor seiner Wohnung steht!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 22, 30, 'Als nun der Priester Pinehas und die Fürsten der Gemeinde, die Häupter der Tausendschaften Israels, die ihn begleiteten, diese Erklärung der Rubeniten, Gaditen und Manassiten vernommen hatten, waren sie dadurch zufriedengestellt.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 22, 31, 'Daher antwortete Pinehas, der Sohn des Priesters Eleasar, den Rubeniten, Gaditen und Manassiten: »Heute erkennen wir, daß der HERR wirklich in unserer Mitte ist, weil ihr euch eine solche Treulosigkeit gegen den HERRN nicht habt zuschulden kommen lassen. Dadurch habt ihr die Israeliten vor der Hand des HERRN behütet.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 22, 32, 'Als hierauf Pinehas, der Sohn des Priesters Eleasar, mit den Fürsten aus dem Lande Gilead von den Rubeniten und Gaditen ins Land Kanaan zu den Israeliten zurückgekehrt war und sie ihnen Bericht erstattet hatten,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 22, 33, 'waren die Israeliten dadurch zufriedengestellt; sie priesen Gott und dachten nicht mehr daran, gegen sie mit Heeresmacht auszuziehen, um das Land zu verwüsten, in welchem die Rubeniten und Gaditen wohnten.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 22, 34, 'Die Rubeniten und Gaditen aber gaben dem Altar den Namen ›Zeuge‹; denn (sie sagten): »Er soll als Zeuge zwischen uns dienen, daß der HERR (der wahre) Gott ist.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 23, 1, 'Geraume Zeit später, nachdem der HERR den Israeliten Ruhe vor allen ihren Feinden ringsum verschafft hatte und Josua alt und hochbetagt geworden war,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 23, 2, 'berief Josua das gesamte Israel, die Ältesten und die Oberhäupter des Volkes, seine Richter und Obmänner, und sprach zu ihnen: »Ich bin nun alt geworden und hochbetagt;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 23, 3, 'ihr aber habt alles gesehen, was der HERR, euer Gott, allen diesen Völkerschaften vor euch her hat widerfahren lassen; denn der HERR, euer Gott, ist es, der für euch gestritten hat.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 23, 4, 'Wisset wohl: ich habe diese Völkerschaften, die noch übriggeblieben sind, durch das Los euren einzelnen Stämmen als Erbteil zugewiesen, gerade so wie alle Völkerschaften, die ich ausgerottet habe, vom Jordan an bis an das große Meer gegen Sonnenuntergang;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 23, 5, 'und der HERR, euer Gott, selbst wird sie vor euch verjagen und vor euch her vertreiben, und ihr werdet ihr Land in Besitz nehmen, wie der HERR, euer Gott, es euch verheißen hat.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 23, 6, 'So haltet denn unerschütterlich fest daran, alles, was im Gesetzbuch Moses geschrieben steht, zu beobachten und zu befolgen, ohne nach rechts und nach links davon abzuweichen,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 23, 7, 'damit ihr euch mit diesen Völkerschaften, die bei euch noch übriggeblieben sind, nicht vermischt und den Namen ihrer Götter nicht anruft, auch bei ihnen nicht schwört und ihnen nicht dient und sie nicht anbetet;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 23, 8, 'sondern am HERRN, eurem Gott, sollt ihr festhalten, wie ihr es bis auf den heutigen Tag getan habt.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 23, 9, 'Der HERR hat ja große und mächtige Völkerschaften vor euch her vertrieben, und niemand hat vor euch bis auf den heutigen Tag standhalten können.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 23, 10, 'Ein einziger Mann von euch treibt tausend von ihnen in die Flucht; denn der HERR, euer Gott, ist es, der für euch streitet, wie er euch verheißen hat.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 23, 11, 'So seid denn um eures Lebens willen eifrig darauf bedacht, den HERRN, euren Gott, zu lieben!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 23, 12, 'Denn wenn ihr euch irgendwie von ihm abwendet und euch dem Überrest dieser Völkerschaften, die bei euch noch übriggeblieben sind, anschließt und Heiraten mit ihnen eingeht, so daß ihr euch mit ihnen vermischt und sie mit euch:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 23, 13, 'so sollt ihr bestimmt wissen, daß dann der HERR, euer Gott, diese Völkerschaften nicht länger vor euch her vertreiben wird, sondern sie werden für euch zur Schlinge und zum Fallstrick werden, zur Geißel in euren Seiten und zu Dornen in euren Augen, bis ihr aus diesem schönen Lande vertilgt seid, das der HERR, euer Gott, euch gegeben hat.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 23, 14, 'Seht, ich gehe jetzt den Weg alles Irdischen; so bedenkt denn mit ganzem Herzen und mit ganzer Seele, daß von all den Segensverheißungen, die der HERR, euer Gott, in bezug auf euch gegeben hat, keine einzige unerfüllt geblieben ist; nein, alle sind bei euch eingetroffen, keine einzige von ihnen ist unerfüllt geblieben.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 23, 15, 'Aber wie alle Segensverheißungen, die der HERR, euer Gott, euch gegeben hat, bei euch eingetroffen sind, ebenso wird der HERR auch alle Drohungen an euch in Erfüllung gehen lassen, bis er euch aus diesem schönen Lande vertilgt hat, das ihr vom HERRN, eurem Gott, empfangen habt.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 23, 16, 'Wenn ihr den Bund, zu dem der HERR, euer Gott, euch verpflichtet hat, übertretet und hingeht, um anderen Göttern zu dienen und sie anzubeten, so wird der Zorn des HERRN gegen euch entbrennen, und ihr werdet schnell aus dem schönen Lande verschwunden sein, das er euch gegeben hat.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 24, 1, 'Weiter versammelte Josua alle Stämme der Israeliten in Sichem und berief dorthin die Ältesten der Israeliten sowie ihre Oberhäupter, ihre Richter und Obmänner. Als sie sich dann vor Gott aufgestellt hatten,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 24, 2, 'sagte Josua zu dem ganzen Volke: »So spricht der HERR, der Gott Israels: ›Eure Väter haben vor alters jenseits des Euphratstromes gewohnt, nämlich Tharah, der Vater Abrahams und Nahors, und haben andere Götter verehrt.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 24, 3, 'Da holte ich euren Vater Abraham aus dem Lande jenseits des Euphratstromes und ließ ihn im ganzen Lande Kanaan umherwandern und gab ihm zahlreiche Nachkommenschaft, nachdem ich ihm Isaak geschenkt hatte.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 24, 4, 'Dem Isaak aber ließ ich Jakob und Esau geboren werden und gab dem Esau das Gebirge Seir zum Besitz, während Jakob und seine Söhne nach Ägypten hinabzogen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 24, 5, 'Dann sandte ich Mose und Aaron und suchte Ägypten heim mit den Wundertaten, die ich inmitten des Landes verrichtete, und führte euch danach von dort weg.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 24, 6, 'Als ich aber eure Väter aus Ägypten wegführte und ihr an das Meer gekommen wart, verfolgten die Ägypter eure Väter mit Kriegswagen und Reitern bis ans Schilfmeer.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 24, 7, 'Als sie nun zum HERRN um Hilfe schrien, ließ er dichte Finsternis zwischen euch und die Ägypter treten und ließ das Meer über sie hinströmen, so daß es sie überflutete; ihr habt ja mit eigenen Augen gesehen, was ich den Ägyptern habe widerfahren lassen. Dann habt ihr geraume Zeit in der Wüste zugebracht.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 24, 8, 'Hierauf führte ich euch in das Land der Amoriter, die jenseits des Jordans ansässig waren; und als sie gegen euch kämpften, gab ich sie in eure Gewalt, so daß ihr in den Besitz ihres Landes kamet, und ich vernichtete sie vor euch.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 24, 9, 'Als dann der Moabiterkönig Balak, der Sohn Zippors, sich erhob und gegen Israel kämpfen wollte und Bileam, den Sohn Beors, durch Gesandte rufen ließ, damit er euch verfluche,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 24, 10, 'war ich nicht gewillt, auf Bileam zu hören; er mußte euch vielmehr segnen, und so errettete ich euch aus seiner Gewalt.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 24, 11, 'Als ihr hierauf über den Jordan gezogen und nach Jericho gekommen wart und die Bürger von Jericho sowie die Amoriter, Pherissiter, Kanaanäer, Hethiter, Girgasiter, Hewiter und Jebusiter feindlich gegen euch auftraten, gab ich sie in eure Gewalt');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 24, 12, 'und sandte die Hornissen vor euch her: die trieben sie vor euch her in die Flucht, die beiden Amoriterkönige, ohne Zutun deines Schwertes und deines Bogens.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 24, 13, 'So habe ich euch ein Land gegeben, um das du dich nicht hast zu mühen brauchen, und Städte, in denen ihr jetzt wohnt, ohne sie gebaut zu haben; von Weinbergen und Ölbaumgärten, die ihr nicht angelegt habt, genießt ihr die Früchte.‹');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 24, 14, 'So fürchtet nun den HERRN und dient ihm aufrichtig und treu! Schafft die Götter weg, denen eure Väter jenseits des Euphratstromes und in Ägypten gedient haben, und dient dem HERRN!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 24, 15, 'Wollt ihr euch aber nicht dazu verstehen, dem HERRN zu dienen, so entscheidet euch heute, wem ihr dienen wollt, ob den Göttern, denen eure Väter jenseits des Euphratstromes gedient haben, oder den Göttern der Amoriter, in deren Lande ihr wohnt. Ich aber und mein Haus, wir wollen dem HERRN dienen!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 24, 16, 'Da gab das Volk die Erklärung ab: »Fern sei es von uns, den HERRN zu verlassen und anderen Göttern zu dienen!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 24, 17, 'Denn der HERR, unser Gott, ist es, der uns und unsere Väter aus dem Lande Ägypten, aus dem Hause der Knechtschaft, hergeführt und der vor unsern Augen jene großen Wunder verrichtet und uns auf dem ganzen Wege, den wir gezogen sind, und unter all den Völkerschaften, durch deren Land unsere Wanderung gegangen ist, behütet hat.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 24, 18, 'Ja, der HERR ist es, der alle Völker, auch die Amoriter, die Bewohner des Landes, vor uns her vertrieben hat. Auch wir wollen dem HERRN dienen, denn er ist unser Gott!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 24, 19, 'Da sagte Josua zum Volk: »Ihr seid nicht imstande, dem HERRN zu dienen; denn er ist ein heiliger Gott; ein eifersüchtiger Gott ist er, der euch eure Übertretungen und eure Sünden nicht vergeben wird.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 24, 20, 'Wenn ihr den HERRN verlaßt und fremden Göttern dient, so wird er sich (von euch) abwenden und euch Unheil widerfahren lassen und euch vernichten, nachdem er euch Gutes getan hat.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 24, 21, 'Das Volk aber erklärte dem Josua: »Nein, dem HERRN wollen wir dienen!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 24, 22, 'Da sagte Josua zum Volk: »Ihr seid Zeugen gegen euch selbst, daß ihr euch den HERRN erwählt habt, ihm zu dienen.« Sie antworteten: »Ja, wir sind Zeugen!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 24, 23, '»So schafft nun die fremden Götter weg, die noch unter euch sind, und neigt euer Herz dem HERRN, dem Gott Israels, zu!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 24, 24, 'Da erklärte das Volk dem Josua: »Dem HERRN, unserm Gott, wollen wir dienen und seinen Weisungen gehorchen!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 24, 25, 'So verpflichtete denn Josua das Volk an jenem Tage feierlich auf den Bund und setzte für die Israeliten in Sichem Gesetz und Recht fest.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 24, 26, 'Darauf trug Josua dies alles in das Gesetzbuch Gottes ein, nahm dann einen großen Stein und richtete ihn dort unter der Terebinthe auf, die im Heiligtum des HERRN stand.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 24, 27, 'Dann sagte Josua zu dem ganzen Volk: »Wisset wohl: dieser Stein da soll als Zeuge gegen uns dienen, denn er hat alle Worte gehört, die der HERR zu uns geredet hat; darum soll er Zeuge gegen euch sein, damit ihr gegen euren Gott nicht treulos handelt!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 24, 28, 'Hierauf entließ Josua das Volk, einen jeden in sein Besitztum.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 24, 29, 'Nach diesen Begebenheiten starb Josua, der Sohn Nuns, der Knecht des HERRN, im Alter von hundertundzehn Jahren;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 24, 30, 'und man begrub ihn im Bereich seines Erbbesitzes zu Thimnath-Serah auf dem Gebirge Ephraim nördlich vom Berge Gaas.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 24, 31, 'Die Israeliten aber dienten dem HERRN, solange Josua lebte und während der ganzen Lebenszeit der Ältesten, die Josua noch lange überlebten und die alle die Taten kannten, die der HERR an Israel vollbracht hatte.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 24, 32, 'Die Gebeine Josephs aber, welche die Israeliten aus Ägypten mitgebracht hatten, begrub man zu Sichem auf dem Stück Land, das Jakob einst von den Söhnen Hemors, des Vaters Sichems, um den Preis von hundert Kesita gekauft hatte und das dann in den Besitz der Nachkommen Josephs übergegangen war.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 24, 33, 'Als hierauf auch Eleasar, der Sohn Aarons, gestorben war, begrub man ihn in Gibea, der Stadt seines Sohnes Pinehas, die diesem auf dem Gebirge Ephraim zugewiesen worden war.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 1, 'Nach Josuas Tode aber fragten die Israeliten beim HERRN an: »Wer von uns soll zuerst gegen die Kanaanäer hinaufziehen, um mit ihnen zu kämpfen?«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 2, 'Der HERR antwortete: »Juda soll hinaufziehen; hiermit gebe ich das Land in seine Gewalt.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 3, 'Da richtete Juda die Aufforderung an seinen Bruderstamm Simeon: »Ziehe mit mir in das durchs Los mir zugeteilte Gebiet hinauf und laß uns die Kanaanäer gemeinsam bekriegen; dann will auch ich mit dir in deinen Losanteil ziehen.« So zog denn Simeon mit ihm.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 4, 'Als nun die Judäer hinaufgezogen waren, gab der HERR die Kanaanäer und Pherissiter in ihre Gewalt: sie schlugen sie bei Besek, zehntausend Mann.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 5, 'Als sie dann bei Besek auf Adoni-Besek stießen, griffen sie ihn an und besiegten die Kanaanäer und Pherissiter.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 6, 'Als dann Adoni-Besek die Flucht ergriff, verfolgten sie ihn, nahmen ihn gefangen und hieben ihm die Daumen an seinen Händen und die beiden großen Zehen ab.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 7, 'Da sagte Adoni-Besek: »Siebzig Könige, denen die Daumen an ihren Händen und die großen Zehen abgehauen waren, haben Brocken unter meinem Tische auflesen müssen: wie ich getan habe, so hat Gott mir wieder vergolten.« Man brachte ihn dann nach Jerusalem, wo er starb. –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 8, 'Die Judäer belagerten hierauf Jerusalem, eroberten es, machten die Einwohnerschaft mit dem Schwert nieder und steckten die Stadt in Brand.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 9, 'Darauf zogen die Judäer hinab, um die Kanaanäer zu bekriegen, die im Gebirge sowie im Südland und in der Niederung wohnten.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 10, 'Die Judäer zogen also gegen die Kanaanäer, die in Hebron wohnten – Hebron hieß aber früher Kirjath-Arba –, und besiegten den Sesai, den Ahiman und den Thalmai.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 11, 'Von dort zog er gegen die Einwohner von Debir – Debir hieß aber früher Kirjath-Sepher.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 12, 'Da machte Kaleb bekannt: »Wer Kirjath-Sepher bezwingt und erobert, dem gebe ich meine Tochter Achsa zur Frau.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 13, 'Als nun Othniel, der Sohn des Kenas, der jüngere Bruder Kalebs, die Stadt eroberte, gab er ihm seine Tochter Achsa zur Frau.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 14, 'Als sie ihm nun zugeführt wurde, überredete sie ihn, ein Stück Ackerland von ihrem Vater erbitten zu dürfen; und als sie dann vom Esel herabsprang und Kaleb sie fragte: »Was wünschest du?«,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 15, 'antwortete sie ihm: »Gib mir doch ein Abschiedsgeschenk! Denn da du mich in das Südland verheiratet hast, so gib mir auch Wasserquellen mit!« Da gab Kaleb ihr die oberen und die unteren Quellen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 16, 'Auch die Söhne des Keniters (Hobab), des Schwagers Moses, waren mit den Judäern aus der Palmenstadt in die Steppe Juda hinaufgezogen, die im Süden von Arad liegt; sie machten sich dann auf und siedelten sich unter dem Volke an.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 17, 'Darauf zogen die Judäer mit ihrem Bruderstamm Simeon zu Felde; sie besiegten die Kanaanäer, die in Zephath wohnten, vollstreckten den Bann an der Stadt und gaben ihr den Namen Horma. –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 18, 'Doch konnten die Judäer Gaza mit dem zugehörigen Gebiete sowie Askalon und sein Gebiet und Ekron nebst seinem Gebiet nicht erobern;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 19, 'doch war der HERR mit den Judäern, so daß sie das Bergland in Besitz nahmen; dagegen die Bewohner der Niederung vermochten sie nicht zu vertreiben, weil diese eiserne Streitwagen hatten.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 20, 'Hebron aber gaben sie, wie Mose bestimmt hatte, dem Kaleb, und dieser vertrieb dann von dort die drei Enaksöhne.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 21, 'Aber die Jebusiter, die Bewohner Jerusalems, konnten die Benjaminiten nicht vertreiben; daher sind die Jebusiter neben den Benjaminiten in Jerusalem wohnen geblieben bis auf den heutigen Tag.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 22, 'Die vom Hause Joseph aber zogen ebenfalls in den Streit, und zwar gegen Bethel, und der HERR war mit ihnen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 23, 'Das Haus Joseph ließ nämlich Bethel auskundschaften – die Stadt hieß vormals Lus –;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 24, 'und als die Späher einen Mann aus der Stadt herauskommen sahen, sagten sie zu ihm: »Zeige uns doch einen Zugang in die Stadt, wir wollen dich auch dafür belohnen.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 25, 'Als er ihnen nun eine Stelle gezeigt hatte, wo man in die Stadt eindringen konnte, eroberten sie den Ort und machten alle Einwohner mit dem Schwert nieder; den Mann aber und seine ganze Familie ließen sie frei abziehen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 26, 'Der Mann begab sich dann in das Land der Hethiter und gründete dort eine Stadt, die er Lus nannte; so heißt der Ort noch heutigen Tages.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 27, 'Der Stamm Manasse aber konnte die Bewohner von Beth-Sean nebst den zugehörigen Ortschaften nicht vertreiben, ebensowenig die Bewohner von Thaanach, von Dor, von Jibleam und von Megiddo nebst den zu ihnen gehörenden Ortschaften; daher gelang es den Kanaanäern, in dieser Gegend wohnen zu bleiben.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 28, 'Als später aber die Israeliten erstarkt waren, machten sie die Kanaanäer fronpflichtig, ohne sie jedoch völlig vertreiben zu können. –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 29, 'Ebensowenig vertrieb der Stamm Ephraim die Kanaanäer, die in Geser wohnten; daher blieben die Kanaanäer mitten unter ihnen in Geser wohnen. –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 30, 'Der Stamm Sebulon vertrieb nicht die Bewohner von Kitron und auch nicht die Bewohner von Nahalol; daher blieben die Kanaanäer mitten unter ihnen wohnen, wurden aber fronpflichtig. –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 31, 'Asser vertrieb nicht die Bewohner von Akko und die Bewohner von Sidon, sowie von Ahlab, von Achsib, von Helba, von Aphik und von Rehob;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 32, 'daher blieben die Asseriten mitten unter den einheimischen Kanaanäern wohnen, denn sie hatten sie nicht vertreiben können. –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 33, 'Der Stamm Naphthali vertrieb nicht die Bewohner von Beth-Semes und auch nicht die Bewohner von Beth-Anath. So blieb denn dieser Stamm mitten unter den einheimischen Kanaanäern wohnen; doch wurden die Bewohner von Beth-Semes und von Beth-Anath ihnen fronpflichtig. –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 34, 'Die Amoriter aber drängten den Stamm Dan ins Gebirge zurück und ließen ihn nicht in die Niederung herabkommen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 35, 'So gelang es denn den Amoritern, in Har-Heres, in Ajjalon und in Saalbim wohnen zu bleiben; doch lag die Hand des Stammes Joseph immer schwerer auf ihnen, so daß sie schließlich fronpflichtig wurden. –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 36, 'Das Gebiet der Amoriter aber erstreckte sich von der Skorpionenhöhe bis nach Sela hin und weiter hinauf.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 2, 1, 'Da kam der Engel des HERRN von Gilgal hinauf nach Bochim und sprach: »Ich habe euch aus Ägypten hergeführt und euch in das Land gebracht, das ich euren Vätern zugeschworen hatte mit der Verheißung: ›Ich werde meinen Bund mit euch in Ewigkeit nicht brechen!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 2, 2, 'Ihr aber dürft mit den Bewohnern dieses Landes keinen Vertrag schließen, sondern müßt ihre Altäre niederreißen!‹ Doch ihr seid meinem Befehl nicht nachgekommen: was habt ihr da getan?');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 2, 3, 'So sage auch ich euch nun: ›Ich werde sie nicht mehr vor euch vertreiben, damit sie euch zu Schlingen und ihre Götter euch zum Fallstrick werden!‹«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 2, 4, 'Als nun der Engel des HERRN diese Drohung gegen alle Israeliten ausgesprochen hatte, fing das Volk laut zu weinen an.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 2, 5, 'Daher nannte man jenen Ort Bochim; und sie brachten dort dem HERRN Schlachtopfer dar.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 2, 6, 'Als nun Josua das Volk entlassen hatte und die Israeliten weggegangen waren, ein jeder in sein Erbteil, um das Land in Besitz zu nehmen,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 2, 7, 'da diente das Volk dem HERRN, solange Josua lebte und während der ganzen Lebenszeit der Ältesten, welche Josua überlebten und all die großen Taten gesehen hatten, die der HERR an Israel vollbracht hatte.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 2, 8, 'Dann starb aber Josua, der Sohn Nuns, der Knecht des HERRN, im Alter von hundertundzehn Jahren,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 2, 9, 'und man begrub ihn im Bereich seines Erbbesitzes zu Thimnath-Heres im Gebirge Ephraim, nördlich vom Berge Gaas.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 2, 10, 'Als dann auch jenes ganze Geschlecht zu seinen Vätern versammelt war und ein anderes Geschlecht nach ihnen erstand, das vom HERRN und von den Taten, die er an Israel vollbracht hatte, nichts wußte,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 2, 11, 'da taten die Israeliten, was dem HERRN mißfiel, indem sie den Baalen dienten');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 2, 12, 'und den HERRN, den Gott ihrer Väter, verließen, der sie aus dem Land Ägypten herausgeführt hatte; sie gingen anderen Göttern nach, nämlich den Göttern der Nachbarvölker ringsumher; sie erwiesen ihnen Anbetung und reizten dadurch den HERRN zum Zorn.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 2, 13, 'Wenn sie nun so vom HERRN abfielen und dem Baal und den Astarten dienten,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 2, 14, 'dann entbrannte der Zorn des HERRN gegen die Israeliten, und er gab sie der Gewalt von Räubern preis, die sie ausplünderten, und ließ sie in die Hand ihrer Feinde ringsum fallen, so daß sie vor ihren Feinden nicht mehr standzuhalten vermochten.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 2, 15, 'Überall, wohin sie zogen, war die Hand des HERRN gegen sie zum Unheil, wie der HERR es angedroht und wie er ihnen zugeschworen hatte, so daß sie in sehr große Not gerieten.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 2, 16, 'Da ließ dann der HERR Richter (unter ihnen) erstehen, die sie aus der Gewalt ihrer Räuber befreiten.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 2, 17, 'Aber auch ihren Richtern gehorchten sie nicht, sondern wandten sich treulos anderen Göttern zu, denen sie Anbetung erwiesen; sie hatten gar schnell den Weg verlassen, den ihre Väter im Gehorsam gegen die Gebote des HERRN gewandelt waren: sie handelten nicht wie jene.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 2, 18, 'Sooft nun der HERR Richter unter ihnen erstehen ließ, war der HERR mit dem betreffenden Richter und errettete sie aus der Gewalt ihrer Feinde, solange der Richter lebte; denn der HERR hatte Mitleid mit ihnen, wenn sie über ihre Bedränger und Bedrücker wehklagten.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 2, 19, 'Sobald aber der Richter gestorben war, trieben sie es aufs neue ärger als ihre Väter, indem sie anderen Göttern nachgingen, um ihnen zu dienen und sie anzubeten: sie ließen von ihrem bösen Tun und ihrem verstockten Wandel nicht ab.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 2, 20, 'Da entbrannte der Zorn des HERRN gegen Israel, so daß er aussprach: »Zur Strafe dafür, daß dieses Volk die Verordnungen meines Bundes, den ich ihren Vätern zur Pflicht gemacht habe, übertreten und meine Weisungen nicht befolgt hat,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 2, 21, 'so will ich meinerseits hinfort keinen einzigen mehr aus den Völkern, die Josua bei seinem Tode übriggelassen hat, vor ihnen her vertreiben;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 2, 22, 'nein, ich will Israel durch sie auf die Probe stellen, ob sie den Weg des HERRN innehalten werden, um nach dem Vorgang ihrer Väter darauf zu wandeln, oder nicht.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 2, 23, 'Darum hatte also der HERR diese Völkerschaften weiter bestehen lassen, statt sie sogleich zu vertreiben, und hatte sie nicht in Josuas Hand fallen lassen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 3, 1, 'Folgendes sind aber die Völkerschaften, die der HERR hat weiter bestehen lassen, um durch sie die Israeliten auf die Probe zu stellen, nämlich alle die, welche die sämtlichen Kämpfe um Kanaan nicht mitgemacht hatten –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 3, 2, '[nur damit die Geschlechter der Israeliten Kenntnis von denselben erhielten, um sie die Kriegsführung zu lehren, und zwar nur die, welche von den früheren Kämpfen nichts erlebt] –:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 3, 3, 'die fünf Fürsten der Philister, alle Kanaanäer, die Sidonier und Hewiter, die im Libanongebirge wohnen, vom Berge Baal-Hermon an bis in die Gegend von Hamath.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 3, 4, 'Durch diese wollte er nämlich Israel auf die Probe stellen, damit es sich zeige, ob sie den Geboten des HERRN gehorchen würden, die er ihren Vätern durch Mose zur Pflicht gemacht hatte.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 3, 5, 'So hatten denn die Israeliten ihre Wohnsitze mitten unter den Kanaanäern, Hethitern, Amoritern, Pherissitern, Hewitern und Jebusitern;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 3, 6, 'sie nahmen sich deren Töchter zu Frauen und ließen ihre eigenen Töchter Ehen mit den Söhnen jener eingehen und verehrten die Götter jener.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 3, 7, 'Als nun die Israeliten taten, was dem HERRN mißfiel, und den HERRN, ihren Gott, vergaßen und den Baalen und den Astarten dienten,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 3, 8, 'da entbrannte der Zorn des HERRN gegen Israel, und er ließ sie in die Gewalt des Kusan-Risathaim, des Königs von Mesopotamien, fallen, so daß die Israeliten dem Kusan-Risathaim acht Jahre lang dienstbar wurden.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 3, 9, 'Als aber die Israeliten den HERRN laut um Hilfe anriefen, ließ der HERR ihnen einen Retter erstehen, der sie befreite, nämlich Othniel, den Sohn des Kenas, den jüngeren Bruder Kalebs.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 3, 10, 'Über diesen kam also der Geist des HERRN, und er verhalf den Israeliten zu ihrem Recht. Als er nämlich zum Kampf ausgezogen war, gab der HERR den Kusan-Risathaim, den König von Mesopotamien, in seine Gewalt, so daß er ihn völlig besiegte');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 3, 11, 'und das Land vierzig Jahre lang Ruhe hatte. – Als dann aber Othniel, der Sohn des Kenas, gestorben war,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 3, 12, 'taten die Israeliten wiederum, was dem HERRN mißfiel; da verlieh der HERR dem Eglon, dem Könige der Moabiter, Macht über die Israeliten, weil sie taten, was dem HERRN mißfiel.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 3, 13, 'Der verbündete sich nämlich mit den Ammonitern und Amalekitern, zog heran und besiegte die Israeliten, und sie bemächtigten sich der Palmenstadt (Jericho).');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 3, 14, 'So waren denn die Israeliten dem Moabiterkönig Eglon achtzehn Jahre lang untertan.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 3, 15, 'Da riefen die Israeliten den HERRN laut um Hilfe an, und der HERR ließ ihnen einen Retter erstehen, nämlich Ehud, den Sohn des Benjaminiten Gera, einen Mann, der linkshändig war. Durch diesen schickten nämlich die Israeliten die ihnen auferlegte Abgabe an den Moabiterkönig Eglon.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 3, 16, 'Ehud hatte sich aber ein zweischneidiges Schwert, eine Elle lang, machen lassen und es unter seinem Rock an seine rechte Hüfte gegürtet.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 3, 17, 'So überreichte er dem Moabiterkönig Eglon die Abgabe; Eglon war aber ein sehr beleibter Mann.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 3, 18, 'Als Ehud nun mit der Überreichung der Abgabe fertig war, ging er in Begleitung der Leute, welche die Abgabe getragen hatten, weg,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 3, 19, 'kehrte dann aber selbst bei den Götzenbildern in der Nähe von Gilgal wieder um und ließ (dem Eglon) sagen: »Ich habe einen geheimen Auftrag an dich, o König.« Als dieser ihm nun zu schweigen geboten hatte, bis alle, die um ihn her standen, hinausgegangen waren,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 3, 20, 'trat Ehud an ihn heran – er saß nämlich in dem kühlen Obergemach, das für ihn allein bestimmt war – und sagte zu ihm: »Ich habe einen Auftrag von Gott an dich!« Als jener nun vom Sessel aufgestanden war,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 3, 21, 'griff Ehud mit seiner linken Hand zu, nahm das Schwert von seiner rechten Hüfte und stieß es ihm in den Bauch,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 3, 22, 'so daß sogar der Griff hinter der Klinge noch eindrang und das Fett sich um die Klinge schloß; denn er hatte ihm das Schwert nicht wieder aus dem Leibe herausgezogen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 3, 23, 'Hierauf trat Ehud auf den Söller hinaus, nachdem er die Tür des Obergemachs hinter sich verschlossen und verriegelt hatte.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 3, 24, 'Kaum war er nun hinausgegangen, als Eglons Diener kamen und nachsahen; als sie aber die Tür des Obergemachs verriegelt fanden, dachten sie: »Er wird wohl gerade seine Notdurft in dem kühlen Gemach verrichten.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 3, 25, 'So warteten sie sich denn zuschanden; schließlich aber, als er die Tür des Obergemachs immer noch nicht öffnete, holten sie einen Schlüssel und öffneten, und siehe: da lag ihr Herr als Leiche am Boden.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 3, 26, 'Ehud aber war, während sie gezaudert hatten, entronnen; er war schon über die Götzenbilder hinausgelangt und nach Seira entkommen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 3, 27, 'Sobald er dann heimgekehrt war, stieß er im Gebirge Ephraim in die Posaune, und die Israeliten zogen mit ihm vom Gebirge hinab, er an ihrer Spitze;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 3, 28, 'und er rief ihnen zu: »Folgt mir eilends nach! Denn der HERR hat eure Feinde, die Moabiter, in eure Hand gegeben!« Da zogen sie unter seiner Führung hinab, besetzten die Jordanfurten, die nach Moab führten, und ließen niemand hinüber.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 3, 29, 'Und sie erschlugen damals den Moabitern gegen zehntausend Mann, lauter kräftige und streitbare Männer, und kein einziger entkam.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 3, 30, 'So mußten die Moabiter sich damals unter die Gewalt der Israeliten beugen, und das Land hatte achtzig Jahre lang Ruhe. –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 3, 31, 'Nach Ehud aber trat Samgar, der Sohn Anaths, auf und erschlug den Philistern sechshundert Mann mit einem Ochsentreiberstecken; und auch er brachte Israel Rettung.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 4, 1, 'Als aber die Israeliten nach Ehuds Tode aufs neue taten, was dem HERRN mißfiel,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 4, 2, 'ließ der HERR sie in die Gewalt des kanaanäischen Königs Jabin fallen, der in Hazor regierte; sein Feldhauptmann war Sisera, der in Haroseth-Goim wohnte.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 4, 3, 'Da riefen die Israeliten den HERRN laut um Hilfe an; denn Jabin besaß neunhundert eiserne Kriegswagen und bedrückte die Israeliten gewaltsam zwanzig Jahre lang.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 4, 4, 'Nun wirkte damals Debora, eine Prophetin, die Frau Lappidoths, als Richterin in Israel.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 4, 5, 'Sie hatte ihren Sitz unter der Debora-Palme zwischen Rama und Bethel im Gebirge Ephraim, und die Israeliten suchten sie dort oben auf, um sich von ihr Recht sprechen zu lassen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 4, 6, 'Diese nun schickte hin und ließ Barak, den Sohn Abinoams, aus Kedes im Stamme Naphthali rufen und sagte zu ihm: »Wisse wohl: der HERR, der Gott Israels, gebietet dir: ›Mache dich auf, ziehe auf den Berg Thabor und nimm zehntausend Mann mit dir aus den beiden Stämmen Naphthali und Sebulon.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 4, 7, 'Ich will dann Sisera, den Heerführer Jabins, samt seinen Wagen und seinen Heerscharen zu dir an den Bach Kison führen und ihn in deine Gewalt geben.‹«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 4, 8, 'Barak antwortete ihr: »Wenn du mit mir gehst, so will ich gehen; wenn du aber nicht mit mir gehst, so gehe auch ich nicht.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 4, 9, 'Da erwiderte sie: »Gewiß will ich mit dir gehen; doch wird alsdann der Ruhm des Zuges, den du unternimmst, nicht dir zuteil werden, denn der HERR wird den Sisera in die Hand eines Weibes fallen lassen.« So machte sich denn Debora auf den Weg und begab sich mit Barak nach Kedes.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 4, 10, 'Hierauf entbot Barak die Stämme Sebulon und Naphthali nach Kedes, und zehntausend Mann zogen unter seiner Führung (auf den Berg Thabor) hinauf; auch Debora zog mit ihm hinauf.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 4, 11, 'Der Keniter Heber aber hatte sich von den übrigen Kenitern, von der Familie Hobabs, des Schwagers Moses, getrennt und schlug seine Zelte bis zur Eiche bei Zaanannim in der Nähe von Kedes auf.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 4, 12, 'Als nun Sisera die Kunde erhielt, daß Barak, der Sohn Abinoams, auf den Berg Thabor hinaufgezogen sei,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 4, 13, 'entbot Sisera alle seine Wagen, neunhundert eiserne Streitwagen, und das gesamte Kriegsvolk, das unter seinem Befehl stand, aus Haroseth-Goim an den Bach Kison.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 4, 14, 'Da sagte Debora zu Barak: »Auf! Denn dies ist der Tag, an dem der HERR den Sisera in deine Hand gibt! Der HERR ist (selbst) schon vor dir her ausgezogen!« So stieg denn Barak an der Spitze seiner zehntausend Mann vom Berge Thabor hinab,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 4, 15, 'und der HERR setzte Sisera und alle seine Wagen und sein ganzes Heer durch die Ankunft und den wilden Schwertangriff Baraks in solche Verwirrung, daß Sisera vom Wagen stieg und zu Fuß floh.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 4, 16, 'Barak aber verfolgte die Wagen und das Heer bis Haroseth-Goim, und das ganze Heer Siseras wurde mit dem Schwert niedergemacht: auch nicht ein einziger blieb übrig.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 4, 17, 'Sisera aber war zu Fuß nach dem Zelte Jaels, der Frau des Keniters Heber, geflohen; denn zwischen Jabin, dem Könige von Hazor, und der Familie des Keniters Heber herrschte Friede.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 4, 18, 'Da trat Jael aus dem Zelte hinaus Sisera entgegen und sagte zu ihm: »Kehre ein, Herr, kehre ein bei mir: fürchte dich nicht!« Da trat er zu ihr ins Zelt, und sie deckte ihn mit einer Schlafdecke zu.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 4, 19, 'Dann bat er sie: »Gib mir doch ein wenig Wasser zu trinken, denn ich bin durstig!« Da öffnete sie den Milchschlauch, gab ihm zu trinken und deckte ihn wieder zu.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 4, 20, 'Darauf bat er sie: »Stelle dich in den Eingang des Zeltes, und wenn jemand kommt und dich fragt, ob jemand hier sei, so antworte: ›Nein, kein Mensch!‹«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 4, 21, 'Nun holte Jael, Hebers Frau, einen Zeltpflock, nahm einen Hammer in die Hand, trat leise an ihn heran, während er vor Erschöpfung eingeschlafen war, und schlug ihm den Pflock durch die Schläfe, so daß er noch in den Erdboden eindrang; so starb er.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 4, 22, 'In diesem Augenblick kam Barak, der den Sisera verfolgte; Jael trat hinaus ihm entgegen und rief ihm zu: »Komm, ich will dir den Mann zeigen, den du suchst!« Als er dann bei ihr eintrat, fand er wirklich Sisera als Leiche am Boden liegen, und der Pflock steckte ihm noch in der Schläfe.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 4, 23, 'So demütigte Gott an jenem Tage den Kanaanäerkönig Jabin vor den Israeliten,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 4, 24, 'deren Hand dann immer schwerer auf Jabin, dem Kanaanäerkönige, lastete, bis sie ihn völlig vernichtet hatten.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 5, 1, 'An jenem Tage sangen Debora und Barak, der Sohn Abinoams, folgendes Lied:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 5, 2, 'Daß Führer an der Spitze standen in Israel, daß das Volk sich willig zeigte: drob preiset den HERRN!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 5, 3, 'Hört zu, ihr Könige! Merkt auf, ihr Fürsten! Ich will, ja, ich will dem HERRN lobsingen, will spielen dem HERRN, dem Gott Israels!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 5, 4, 'HERR, als du auszogst von Seir, als du schrittest von Edoms Gefilden her, da bebte die Erde, es troffen die Himmel, ja, die Wolken troffen von Wasser;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 5, 5, 'die Berge wankten vor dem HERRN, der Sinai dort vor dem HERRN, dem Gott Israels.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 5, 6, 'In den Tagen Samgars, des Sohnes Anaths, in den Tagen Jaels waren öde die Straßen, und die Wegewandrer gingen auf krummen Pfaden;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 5, 7, 'es fehlte an Führern in Israel, gebrach, bis du auftratst, Debora, auftratst, eine Mutter in Israel.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 5, 8, 'Man wählte sich neue Götter; damals war Kampf schon vor den Toren, und weder Schild noch Lanze war zu sehn bei Vierzigtausenden in Israel.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 5, 9, 'Mein Herz gehört den Führern Israels, denen, die willig sich zeigten im Volk: – preiset den HERRN!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 5, 10, 'Die ihr reitet auf weißglänzenden Eselinnen, die ihr sitzet auf Teppichen und die zu Fuß ihr wandert: erzählt es euch!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 5, 11, 'Horch! ... zwischen den Tränkrinnen! Dort preist man die Heilstaten des HERRN, die Heilstaten seiner Führerschaft in Israel. Da zog das Volk des HERRN zu den Toren hinab.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 5, 12, 'Wach auf, erwache, Debora! Wach auf, erwache und stimme den Sang an! Erhebe dich, Barak, und fange deine Fänger, Sohn Abinoams!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 5, 13, 'Da zog Israel hinab samt seinen Edlen; das Volk des HERRN zog hinab als Heldenschar.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 5, 14, 'Aus Ephraim kamen die, deren Stammsitz unter Amalek ist, hinter ihnen Benjamin mit seinen Scharen; aus Machir zogen Gebieter hinab und aus Sebulon die Träger des Führerstabs,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 5, 15, 'und die Fürsten in Issaschar mit Debora und wie Issaschar so Barak: in die Ebene stürmte er hin zu Fuß. An Rubens Bächen fanden schwere Erwägungen statt:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 5, 16, '»Warum bliebst du zwischen den Hürden sitzen, um das Herdengeblök zu hören?« An Rubens Bächen fanden schwere Erwägungen statt.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 5, 17, 'Gliead blieb ruhig jenseits des Jordans, und Dan – warum weilte er bei den Schiffen? Asser saß still am Gestade des Meeres und blieb ruhig an seinen Buchten;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 5, 18, 'aber Sebulon ist ein Volk, das sein Leben dem Tode preisgibt, auch Naphthali auf den Höhen seines Gefildes.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 5, 19, 'Könige kamen und stritten; damals stritten die Könige Kanaans bei Thaanach an den Wassern Megiddos: Beute an Silber gewannen sie nicht.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 5, 20, 'Vom Himmel her stritten die Sterne, von ihren Bahnen her stritten sie gegen Sisera.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 5, 21, 'Der Kisonbach spülte sie weg, der alte Schlachtenbach, der Kisonbach: tritt sie nieder, meine Seele, mit aller Kraft!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 5, 22, 'Damals stampften die Hufe der Rosse vom Rennen, dem Rennen ihrer Helden.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 5, 23, '»Verfluchet Meros!« ruft der Engel des HERRN, »ja, fluchet seinen Bewohnern! Denn sie sind dem HERRN nicht zu Hilfe gekommen, dem HERRN nicht zu Hilfe unter den Helden!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 5, 24, 'Gepriesen vor allen Weibern sei Jael, das Weib des Keniters Heber, vor den Weibern im Zelt gepriesen!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 5, 25, 'Um Wasser bat er, Milch gab sie, im Ehrenbecher reichte sie Sahne.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 5, 26, 'Ihre Hand streckte sie aus nach dem Zeltpflock, ihre Rechte nach einem Arbeitshammer, hämmerte los auf Sisera, zermalmte sein Haupt, zerschmetterte und durchbohrte ihm die Schläfe;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 5, 27, 'zu ihren Füßen brach er zusammen, sank hin, lag da; zu ihren Füßen brach er zusammen, sank hin: wo er zusammenbrach, blieb entseelt er liegen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 5, 28, 'Durchs Fenster spähte sie aus und rief in Angst, Siseras Mutter, durchs Gitter hindurch: »Warum zaudert sein Wagen heimzukommen? Warum säumt der Hufschlag seiner Gespanne?«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 5, 29, 'Die klügste ihrer Edelfrauen erwidert ihr, und auch sie selbst gibt sich die Antwort:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 5, 30, '»Sicherlich haben sie Beute zu teilen gefunden, eine Dirne, zwei Dirnen für jeden Mann, Beute an bunten Stoffen für Sisera, Beute an buntgestickten Gewändern, farbiges Zeug, ein Paar gestickte Tücher für den Hals der Herrin.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 5, 31, 'So müssen umkommen alle deine Feinde, HERR! Doch die ihn lieben, sind wie der Sonne Aufgang in ihrer Kraft. – Darauf hatte das Land vierzig Jahre lang Ruhe.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 1, 'Als dann die Israeliten wiederum taten, was dem HERRN mißfiel, gab der HERR sie sieben Jahre lang in die Gewalt der Midianiter;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 2, 'und die Hand der Midianiter lag schwer auf Israel. Um sich der Midianiter zu erwehren, richteten die Israeliten sich die Schlupfwinkel ein, die sich in den Bergen befinden, und legten die Höhlen und die Bergfesten an.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 3, 'Denn sooft die Israeliten gesät hatten, zogen die Midianiter, die Amalekiter und die übrigen Horden des Ostens gegen sie heran,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 4, 'lagerten sich gegen sie im Lande und verwüsteten den Ertrag der Felder bis nach Gaza hin und ließen keine Lebensmittel in Israel übrig, auch kein Kleinvieh, keine Rinder und Esel;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 5, 'denn wenn sie mit ihren Herden und Zelten heranzogen, kamen sie so zahlreich wie Heuschreckenschwärme, so daß sie selbst und ihre Kamele nicht zu zählen waren; und wenn sie eingedrungen waren, verheerten sie das Land.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 6, 'Als Israel so von den Midianitern arg mitgenommen wurde, schrien die Israeliten zum HERRN um Hilfe.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 7, 'Als nun die Israeliten den HERRN um Hilfe gegen die Midianiter angerufen hatten,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 8, 'sandte der HERR einen Propheten zu den Israeliten, der zu ihnen sagte: »So hat der HERR, der Gott Israels, gesprochen: ›Ich selbst habe euch aus Ägypten hergebracht und euch aus dem Hause der Knechtschaft herausgeführt;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 9, 'ich habe euch aus der Hand der Ägypter und aus der Gewalt aller eurer Bedrücker errettet und sie vor euch her vertrieben und euch ihr Land gegeben');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 10, 'und habe zu euch gesagt: Ich, der HERR, bin euer Gott: ihr dürft die Götter der Amoriter, in deren Lande ihr wohnt, nicht verehren! Aber ihr habt nicht auf meine Mahnung gehört.‹«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 11, 'Da kam der Engel des HERRN und setzte sich unter die Terebinthe in Ophra, die dem Abiesriten Joas gehörte, während dessen Sohn Gideon gerade Weizen in der Kelter ausklopfte, um ihn vor den Midianitern in Sicherheit zu bringen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 12, 'Diesem erschien also der Engel des HERRN und redete ihn mit den Worten an: »Der HERR ist mit dir, du tapferer Held!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 13, 'Gideon antwortete ihm: »Mit Verlaub, mein Herr! Wenn der HERR wirklich mit uns wäre, wie hätte uns da dies alles widerfahren können? Und wo sind alle seine Wundertaten, von denen unsere Väter uns erzählt haben, indem sie sagten: ›Der HERR ist es gewesen, der uns aus Ägypten hergeführt hat!‹? Jetzt aber hat der HERR uns verstoßen und uns in die Hand der Midianiter fallen lassen!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 14, 'Da wandte der HERR sich ihm zu und sagte: »Gehe hin in dieser deiner Kraft und rette Israel aus der Gewalt der Midianiter! Ich sende dich ja!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 15, 'Er aber entgegnete ihm: »Mit Verlaub, mein Herr! Wie könnte ich Israel erretten, da doch mein Geschlecht das geringste in Manasse ist und ich der Jüngste in meines Vaters Hause bin?«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 16, 'Da antwortete ihm der HERR: »Ich werde ja mit dir sein, und du sollst die Midianiter schlagen wie einen einzelnen Mann.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 17, 'Da entgegnete er ihm: »Wenn du mir wirklich gnädig gesinnt bist, so gib mir ein Zeichen, daß du selbst es bist, der mit mir redet!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 18, 'Entferne dich doch nicht von hier, bis ich zu dir zurückkehre und eine Gabe von mir herausbringe und sie dir vorsetze!« Da antwortete er: »Ich will hier sitzen bleiben, bis du wiederkommst.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 19, 'Darauf ging Gideon ins Haus hinein und richtete ein Ziegenböckchen zu und ungesäuerte Kuchen von einem Epha Mehl; das Fleisch legte er in einen Korb, und die Brühe tat er in einen Topf und brachte es dann zu ihm hinaus unter die Terebinthe und setzte es ihm vor.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 20, 'Doch der Engel Gottes sagte zu ihm: »Nimm das Fleisch und die ungesäuerten Kuchen, lege sie auf den Felsen drüben und gieße die Brühe darüber aus!« Als er es getan hatte,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 21, 'streckte der Engel des HERRN den Stab aus, den er in der Hand hatte, und berührte mit der Spitze (des Stabes) das Fleisch und die ungesäuerten Kuchen; da schlug Feuer aus dem Gestein hervor und verzehrte das Fleisch und die Kuchen; der Engel des HERRN aber war vor seinen Augen verschwunden.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 22, 'Da erkannte Gideon, daß es der Engel des HERRN gewesen war, und er rief aus: »Wehe, HERR mein Gott! Ach, ich habe den Engel des HERRN von Angesicht zu Angesicht gesehen!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 23, 'Aber der HERR antwortete ihm: »Friede dir! Fürchte nichts! Du wirst nicht sterben!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 24, 'Darauf erbaute Gideon dort dem HERRN einen Altar und nannte ihn: »Der HERR ist Heil!« Bis auf den heutigen Tag steht er noch in Ophra, dem Wohnort der Abiesriten.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 25, 'In derselben Nacht gebot ihm dann der HERR: »Nimm den jungen Stier, den dein Vater hat, und außerdem den zweiten siebenjährigen Stier, reiße den Altar Baals, der deinem Vater gehört, nieder und haue den Götzenbaum um, der daneben steht!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 26, 'Dann baue dem HERRN, deinem Gott, auf der höchsten Stelle dieser Bergfeste einen Altar aus aufgeschichteten Steinen und nimm den Stier und bringe ihn als Brandopfer dar mit dem Holz des Götzenbaumes, den du umhauen sollst!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 27, 'Da nahm Gideon zehn Männer von seinen Knechten und tat, wie der HERR ihm befohlen hatte; weil er sich aber vor seiner Familie und vor den Leuten der Stadt fürchtete, es bei Tage zu tun, tat er es bei Nacht.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 28, 'Als nun die Männer der Stadt am nächsten Morgen aufstanden, fanden sie den Altar Baals niedergerissen und den Götzenbaum, der daneben gestanden hatte, umgehauen; der Stier aber war als Brandopfer auf dem neuerbauten Altar dargebracht worden.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 29, 'Da fragten sie einer den andern: »Wer hat das getan?«, und als sie dann nachforschten und sich erkundigten, hieß es: »Gideon, der Sohn des Joas, hat das getan.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 30, 'Da sagten die Männer der Stadt zu Joas: »Gib deinen Sohn heraus: er muß sterben, weil er den Altar Baals niedergerissen und den heiligen Baum, der danebenstand, umgehauen hat!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 31, 'Aber Joas entgegnete allen, die bei ihm standen: »Wollt ihr etwa für Baal streiten, oder wollt ihr für ihn eintreten? Wer für ihn streitet, soll noch diesen Morgen sterben! Wenn Baal ein Gott ist, so mag er für sich selbst eintreten, weil man seinen Altar niedergerissen hat!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 32, 'Daher gab man ihm an jenem Tage den Namen »Jerubbaal«, indem man sagte: »Baal möge gegen ihn streiten, weil er seinen Altar niedergerissen hat.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 33, 'Als sich nun alle Midianiter, dazu auch die Amalekiter und die Horden des Ostens insgesamt vereinigt und sich nach Überschreitung (des Jordans) in der Ebene Jesreel gelagert hatten,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 34, 'kam der Geist des HERRN über Gideon, so daß er in die Posaune stieß, worauf die Abiesriter seinem Aufgebot folgten.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 35, 'Er sandte dann Boten in ganz Manasse umher, und auch dieser Stamm folgte seinem Ruf; ebenso sandte er Boten durch Asser, durch Sebulon und durch Naphthali, und auch diese Stämme zogen zur Hilfeleistung heran.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 36, 'Nun sagte Gideon zu Gott: »Willst du wirklich Israel durch meine Hand erretten, wie du verheißen hast –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 37, 'gut, so will ich ein Schaffel auf der Tenne ausbreiten; wenn dann der Tau bloß auf dem Fell liegen wird, der ganze übrige Boden aber trocken bleibt, so will ich daran erkennen, daß du Israel durch meine Hand erretten willst, wie du verheißen hast.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 38, 'Und so geschah es: als er am andern Morgen früh das Fell ausdrückte, preßte er Tau aus dem Fell, eine ganze Schale voll Wasser.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 39, 'Darauf sagte Gideon zu Gott: »Gerate nicht in Zorn gegen mich, wenn ich nur diesmal noch rede! Laß mich nur noch diesmal einen Versuch mit dem Fell machen: das Fell allein möge trocken bleiben, auf dem ganzen übrigen Boden aber Tau liegen!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 40, 'Da ließ Gott es in jener Nacht so geschehen: das Fell allein blieb trocken, während sonst auf dem Boden überall Tau lag.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 7, 1, 'Da machte sich Jerubbaal, das ist Gideon, in der Frühe mit der gesamten Mannschaft, die bei ihm war, auf den Weg und lagerte sich bei der Quelle Harod, so daß sich das Lager der Midianiter nördlich von ihm in der Ebene nach dem Hügel More hin befand.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 7, 2, 'Da sagte der HERR zu Gideon: »Das Volk, das du bei dir hast, ist zu zahlreich, als daß ich die Midianiter in ihre Gewalt geben sollte; die Israeliten könnten sich sonst mir gegenüber rühmen und behaupten: ›Wir haben uns durch eigene Kraft gerettet!‹');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 7, 3, 'Darum laß vor dem Volk laut ausrufen: ›Wer sich fürchtet und Angst hat, der kehre um [und entferne sich vom Gebirge Gilead]!‹« Da zogen 22000 Mann von dem Kriegsvolk ab, und 10000 blieben zurück.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 7, 4, 'Der HERR aber sagte zu Gideon: »Das Volk ist immer noch zu zahlreich; führe sie hinab ans Wasser: dort will ich sie dir sichten; und von wem ich dir dann sagen werde: ›Dieser soll mit dir ziehen!‹, der soll dich begleiten; aber jeder, von dem ich dir sage: ›Dieser soll nicht mit dir ziehen!‹, der soll dich nicht begleiten!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 7, 5, 'Als nun Gideon die Leute an das Wasser hinabgeführt hatte, sagte der HERR zu ihm: »Jeden, der das Wasser mit der Zunge leckt, wie die Hunde es machen, den stelle besonders, und ebenso jeden, der niederkniet, um zu trinken.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 7, 6, 'Es belief sich aber die Zahl derer, die das Wasser [mit der Hand in den Mund] geleckt hatten, auf dreihundert Mann; alle übrigen hatten sich auf die Knie niedergelassen, um Wasser (mit der Hand in den Mund) zu trinken.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 7, 7, 'Darauf sagte der HERR zu Gideon: »Durch die dreihundert Mann, die (das Wasser) geleckt haben, will ich euch erretten und die Midianiter in deine Hand geben; alle übrigen Leute aber sollen ein jeder in seinen Wohnort zurückkehren!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 7, 8, 'Da behielten sie den Mundvorrat der Leute und deren Posaunen bei sich zurück, alle übrigen israelitischen Männer aber entließ er, einen jeden in seine Heimat; nur die dreihundert Mann behielt er bei sich. Das Lager der Midianiter aber befand sich unterhalb von ihm in der Ebene.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 7, 9, 'In derselben Nacht nun gebot ihm der HERR: »Mache dich auf, ziehe gegen das Lager hinab! Denn ich habe es in deine Hand gegeben.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 7, 10, 'Fürchtest du dich aber hinabzuziehen, so steige mit deinem Knappen Pura zum Lager hinab;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 7, 11, 'wenn du dann belauscht hast, was man dort redet, wirst du alsdann den Mut in dir fühlen, gegen das Lager hinabzuziehen.« Da begab er sich mit seinem Knappen Pura hinab bis zu den Kriegern am äußersten Rande des Lagers.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 7, 12, 'Die Midianiter aber sowie die Amalekiter und die sämtlichen Horden aus dem Osten hatten sich in der Ebene gelagert so zahllos wie Heuschreckenschwärme, und die Menge ihrer Kamele war unzählbar wie der Sand am Gestade des Meeres.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 7, 13, 'Als nun Gideon dort ankam, erzählte ein Mann gerade seinem Kameraden einen Traum mit den Worten: »Denke dir: ich habe einen Traum gehabt! Ich sah, wie ein hartgebackenes Gerstenbrot in das midianitische Lager rollte, bis es an ein Zelt kam und dieses so traf, daß es umfiel: es wurde umgestürzt, das Unterste zuoberst, und so lag das Zelt da.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 7, 14, 'Da antwortete der andere: »Das bedeutet nichts anderes als das Schwert des Israeliten Gideon, des Sohnes des Joas! Gott hat die Midianiter und unser ganzes Lager in seine Hand gegeben!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 7, 15, 'Als nun Gideon die Erzählung von dem Traum und seine Deutung gehört hatte, warf er sich danksagend auf die Knie nieder, kehrte dann ins israelitische Lager zurück und rief: »Auf! Der HERR hat das Lager der Midianiter in eure Hand gegeben!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 7, 16, 'Hierauf teilte er seine dreihundert Mann in drei Abteilungen und gab ihnen allen Posaunen in die Hand und leere Krüge, in denen sich aber Fackeln befanden.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 7, 17, 'Dann befahl er ihnen: »Achtet darauf, wie ich es mache, und macht es ebenso! Was ich tun werde, sobald ich unmittelbar vor dem Lager angekommen bin, das tut auch ihr!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 7, 18, 'Wenn ich also samt allen Leuten, die zu meiner Abteilung gehören, in die Posaune stoße, so stoßt auch ihr in die Posaunen rings um das ganze Lager und ruft: ›Für den HERRN und für Gideon!‹«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 7, 19, 'Als nun Gideon mit den hundert Mann, die seine Abteilung bildeten, bei Beginn der mittleren Nachtwache – soeben hatte man die Wachen aufgestellt – unmittelbar vor dem Lager angekommen war, stießen sie in die Posaunen und zerschlugen die Krüge, die sie in der Hand hatten;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 7, 20, 'und zwar stießen die drei Abteilungen gleichzeitig in die Posaunen und zerschlugen die Krüge, nahmen dann die Fackeln in die linke Hand und die Posaunen in die rechte, um hineinzustoßen, und schrien: »Schwert für den HERRN und für Gideon!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 7, 21, 'Dabei blieben sie ein jeder ruhig an seiner Stelle rings um das Lager herum stehen. Da geriet das ganze Lager in Bewegung, alles schrie und suchte zu fliehen;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 7, 22, 'als jene dann aber in die dreihundert Posaunen stießen, richtete der HERR das Schwert eines jeden gegen den andern, und zwar im ganzen Lager, und das Heerlager floh bis Beth-Sitta nach Zerera hin, bis an das (Jordan-) Ufer von Abel-Mehola bei Tabbath.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 7, 23, 'Nun wurden die Mannschaften der Israeliten aus den Stämmen Naphthali, Asser und ganz Manasse aufgeboten und verfolgten die Midianiter.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 7, 24, 'Auch hatte Gideon Boten im ganzen Berglande Ephraim umhergesandt mit der Aufforderung: »Kommt herab den Midianitern entgegen und schneidet ihnen das Wasser ab bis Beth-Bara und den Übergang über den Jordan!« Da folgten alle Männer vom Stamm Ephraim dem Rufe und schnitten ihnen das Wasser ab bis Beth-Bara und den Übergang über den Jordan.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 7, 25, 'Auch nahmen sie die beiden midianitischen Fürsten Oreb und Seeb gefangen und hieben Oreb am Rabenfelsen nieder und erschlugen Seeb bei der Wolfskelter. Nach der Verfolgung der Midianiter aber brachten sie die Köpfe Orebs und Seebs zu Gideon auf die andere Seite des Jordans.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 8, 1, 'Die Mannschaft der Ephraimiten aber sagte zu ihm: »Warum hast du uns das zuleide getan, daß du uns nicht gleich gerufen hast, als du zum Kampf gegen die Midianiter auszogst?« und machte ihm schwere Vorwürfe.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 8, 2, 'Doch er entgegnete ihnen: »Was habe ich denn jetzt geleistet im Vergleich mit euch? Ist nicht die Nachlese Ephraims ergiebiger als die Weinlese Abiesers?');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 8, 3, 'In eure Hand hat ja Gott die Häuptlinge der Midianiter, Oreb und Seeb, fallen lassen. Was habe ich also im Vergleich mit euch zu leisten vermocht?« Durch diese Worte, die er an sie richtete, wurde ihr Unwille gegen ihn beschwichtigt.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 8, 4, 'Als nun Gideon an den Jordan gekommen und mit seinen dreihundert Mann, erschöpft von der Verfolgung, übergesetzt war,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 8, 5, 'bat er die Einwohner von Sukkoth: »Gebt doch den Leuten, die mir folgen, einige Laibe Brot, denn sie sind erschöpft; und ich bin auf der Verfolgung der Midianiterkönige Sebah und Zalmunna.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 8, 6, 'Aber die Vorsteher von Sukkoth antworteten: »Hast du etwa die Faust Sebahs und Zalmunnas schon in deiner Hand, daß wir deiner Mannschaft Brot geben sollten?«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 8, 7, 'Da erwiderte Gideon: »Nun gut! Wenn der HERR den Sebah und Zalmunna in meine Gewalt gegeben hat, will ich euch den Leib mit Wüstendornen und Stechdisteln zerdreschen!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 8, 8, 'Er zog dann von dort weiter nach Pnuel hinauf und richtete an sie die gleiche Bitte; aber die Einwohner von Pnuel gaben ihm dieselbe Antwort wie die Leute von Sukkoth.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 8, 9, 'Da erklärte er auch den Einwohnern von Pnuel: »Wenn ich wohlbehalten zurückkomme, will ich den Turm hier niederreißen!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 8, 10, 'Sebah und Zalmunna aber befanden sich mit ihren Heeren in Karkor, etwa 15000 Mann, alle, die von dem gesamten Heere der Horden des Ostens übriggeblieben waren; denn 120000 Mann hatten den Tod gefunden, lauter schwertbewaffnete Männer.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 8, 11, 'Gideon zog nun auf der Karawanenstraße östlich von Nobah und Jogbeha heran und überfiel das Heer, das in seinem Lager keine Gefahr ahnte.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 8, 12, 'Sebah und Zalmunna flohen, er aber verfolgte sie und nahm die beiden midianitischen Könige Sebah und Zalmunna gefangen; das ganze Heer aber hatte er zersprengt.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 8, 13, 'Als dann Gideon, der Sohn des Joas, von der Anhöhe von Heres her aus dem Kampf zurückkehrte,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 8, 14, 'griff er einen jungen Mann auf, der in Sukkoth zu Hause war, und fragte ihn aus; dieser mußte ihm die Namen der Vorsteher von Sukkoth und der dortigen Ältesten aufschreiben, siebenundsiebzig Personen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 8, 15, 'Als er dann in Sukkoth ankam, sagte er zu den Männern dort: »Hier sind nun Sebah und Zalmunna, derentwegen ihr mich verhöhnt habt mit der Frage: ›Hast du etwa die Faust Sebahs und Zalmunnas schon in deiner Hand, daß wir deinen erschöpften Leuten Brot geben sollten?‹«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 8, 16, 'Darauf ließ er die Ältesten des Orts ergreifen, nahm Wüstendornen und Stechdisteln und ließ damit den Männern von Sukkoth einen Denkzettel geben.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 8, 17, 'Den Turm in Pnuel aber zerstörte er und ließ die Männer der Stadt niederhauen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 8, 18, 'Darauf fragte er Sebah und Zalmunna: »Wie sahen die Männer aus, die ihr am Thabor erschlagen habt?« Sie antworteten: »Ganz wie du, so sahen sie aus, ein jeder wie ein Königssohn an Wuchs.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 8, 19, 'Da rief (Gideon) aus: »Das waren meine Brüder, die Söhne meiner Mutter! So wahr der HERR lebt: hättet ihr sie am Leben gelassen, so wollte ich euch auch nicht ums Leben bringen!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 8, 20, 'Hierauf sagte er zu seinem erstgeborenen Sohne Jether: »Auf! Haue sie nieder!« Aber der Knabe zog sein Schwert nicht, denn er fürchtete sich, weil er noch zu jung war.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 8, 21, 'Da sagten Sebah und Zalmunna: »Stehe du auf und stoße uns nieder! Denn wie der Mann, so seine Kraft«. Da stand Gideon auf und hieb Sebah und Zalmunna nieder; die kleinen Monde aber, die ihre Kamele am Halse trugen, nahm er für sich.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 8, 22, 'Hierauf baten die Israeliten den Gideon: »Sei unser König, sowohl du als auch dein Sohn und deines Sohnes Sohn! Denn du hast uns aus der Gewalt der Midianiter befreit.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 8, 23, 'Aber Gideon antwortete ihnen: »Ich will nicht euer König sein, und mein Sohn soll auch nicht über euch herrschen: der HERR soll euer König sein!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 8, 24, 'Dann fuhr er fort: »Eine Bitte möchte ich an euch richten: gebt mir ein jeder die Ringe, die er erbeutet hat!« Die Midianiter hatten nämlich goldene Ringe getragen, weil sie Ismaeliter waren.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 8, 25, 'Da antworteten sie: »Gewiß, die wollen wir dir gern geben.« Da breiteten sie einen Mantel aus, und ein jeder warf die von ihm erbeuteten Ringe darauf.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 8, 26, 'Es betrug aber das Gewicht der goldenen Ringe, die er sich erbeten hatte, 1700 Schekel Gold, abgesehen von den kleinen Monden und den Ohrgehängen und den Purpurgewändern, welche die midianitischen Könige getragen hatten, und abgesehen von den Halsketten, die an den Hälsen ihrer Kamele gehangen hatten.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 8, 27, 'Gideon ließ dann daraus einen kostbaren Ephod anfertigen und stellte diesen in seinem Wohnort Ophra auf; und ganz Israel trieb dort Abgötterei mit ihm, so daß er für Gideon und sein Haus zum Fallstrick wurde. –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 8, 28, 'Die Midianiter aber waren von den Israeliten gedemütigt worden, so daß sie das Haupt nicht mehr hochtragen konnten; und das Land hatte vierzig Jahre lang Ruhe, solange Gideon lebte.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 8, 29, 'Hierauf ging Jerubbaal, der Sohn des Joas, hin und lebte ruhig in seinem Hause.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 8, 30, 'Gideon hatte aber siebzig vollbürtige Söhne, denn er hatte viele Frauen;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 8, 31, 'auch von seinem Nebenweibe, die in Sichem wohnte, hatte er einen Sohn, dem er den Namen Abimelech gab.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 8, 32, 'Gideon, der Sohn des Joas, starb dann in hohem Alter und wurde im Grabe seines Vaters Joas zu Ophra, dem Wohnort der Abiesriten, beigesetzt.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 8, 33, 'Nach Gideons Tode aber trieben die Israeliten wiederum Götzendienst mit den Baalen und machten den Bundesbaal zu ihrem Gott;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 8, 34, 'denn die Israeliten dachten nicht mehr an den HERRN, ihren Gott, der sie aus der Gewalt aller ihrer Feinde ringsum errettet hatte;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 8, 35, 'auch bewiesen sie sich nicht dankbar gegen das Haus Jerubbaal-Gideons für alles Gute, das er an Israel getan hatte.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 1, 'Abimelech aber, der Sohn Jerubbaals, begab sich nach Sichem zu den Brüdern seiner Mutter und stellte ihnen sowie allen, die zu der Familie des Vaters seiner Mutter gehörten, folgendes vor:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 2, '»Richtet doch an alle Bürger von Sichem laut die Frage: ›Was ist vorteilhafter für euch, wenn siebzig Männer, sämtliche Söhne Jerubbaals, über euch herrschen oder wenn ein einziger Mann euer Herrscher ist?‹ Bedenkt auch, daß ich von eurem Fleisch und Bein bin!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 3, 'Als nun die Brüder seiner Mutter alle diese Äußerungen vor den Bürgern von Sichem laut aussprachen und für ihn eintraten, da neigten sich ihre Herzen dem Abimelech zu; denn sie sagten: »Er ist unser Bruder.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 4, 'Sie gaben ihm also siebzig Schekel Silber aus dem Tempel des Bundesbaals, und mit diesem Gelde nahm Abimelech eine Anzahl nichtsnutziger und verwegener Leute in seinen Dienst: sie bildeten sein Gefolge.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 5, 'Er begab sich dann nach Ophra in das Haus seines Vaters und ermordete dort seine Brüder, die Söhne Jerubbaals, siebzig Männer, alle auf einem Steine; nur Jotham, der jüngste Sohn Jerubbaals, blieb am Leben, weil er sich versteckt hatte.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 6, 'Darauf versammelten sich alle Bürger von Sichem und alle Bewohner des Millo, begaben sich zu der Denkmalseiche, die in der Nähe von Sichem steht, und machten dort Abimelech zum König.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 7, 'Als man das dem Jotham hinterbrachte, machte er sich auf, trat auf den Gipfel des Berges Garizim und rief ihnen mit hocherhobener Stimme zu: »Hört mich an, ihr Bürger von Sichem, damit auch Gott euch anhöre!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 8, 'Einst gingen die Bäume hin, um einen König über sich zu salben, und sagten zum Ölbaum: ›Sei du unser König!‹');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 9, 'Aber der Ölbaum erwiderte ihnen: ›Soll ich etwa meine Fettigkeit aufgeben, um deretwillen Götter und Menschen mich preisen, und soll hingehen, um über den Bäumen zu schweben?‹');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 10, 'Da sagten die Bäume zum Feigenbaum: ›Komm du, sei unser König!‹');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 11, 'Aber der Feigenbaum erwiderte ihnen: ›Soll ich etwa meine Süßigkeit und meine köstlichen Früchte aufgeben und hingehen, um über den Bäumen zu schweben?‹');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 12, 'Da sagten die Bäume zum Weinstock: ›Komm du, sei unser König!‹');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 13, 'Aber der Weinstock erwiderte ihnen: ›Soll ich etwa meinen Wein aufgeben, der Götter und Menschen fröhlich macht, und hingehen, um über den Bäumen zu schweben?‹');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 14, 'Da sagten die Bäume alle zum Dornstrauch: ›Komm du, sei unser König!‹');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 15, 'Da antwortete der Dornstrauch den Bäumen: ›Wenn ihr mich wirklich zum König über euch salben wollt, so kommt: vertraut euch meinem Schatten an! Wo nicht, so soll Feuer vom Dornstrauch ausgehen und die Zedern des Libanons verzehren!‹');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 16, 'Und nun, wenn ihr treu und redlich gehandelt habt, daß ihr Abimelech zum König gemacht, und wenn ihr ehrenhaft an Jerubbaal und seinem Hause gehandelt und euch dankbar für seine Verdienste um euch bewiesen habt –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 17, 'denn mein Vater hat für euch gekämpft und sein Leben aufs Spiel gesetzt und euch aus der Gewalt der Midianiter errettet,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 18, 'während ihr euch jetzt gegen das Haus meines Vaters erhoben und seine Söhne ermordet habt, siebzig Männer, alle auf einmal, und habt Abimelech, den Sohn seiner Magd, zum König über die Bürger von Sichem gemacht, weil er euer Bruder ist –;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 19, 'wenn ihr also heute treu und ehrenhaft an Jerubbaal und seinem Hause gehandelt habt, so wünsche ich euch, Freude an Abimelech zu erleben, und auch er möge euer froh werden!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 20, 'Wenn aber nicht, so möge Feuer von Abimelech ausgehen und die Bürger von Sichem samt den Bewohnern der Burg verzehren, und ebenso möge Feuer von den Bürgern Sichems und von den Bewohnern der Burg ausgehen und den Abimelech verzehren!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 21, 'Darauf entfloh Jotham eilig und kam glücklich nach Beer, wo er sich in weiter Entfernung von seinem Bruder Abimelech niederließ.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 22, 'Als nun Abimelech drei Jahre über Israel geherrscht hatte,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 23, 'ließ Gott einen bösen Geist zwischen Abimelech und den Bürgern von Sichem entstehen, so daß die Bürger von Sichem von Abimelech abfielen –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 24, 'dies geschah nämlich, damit das an den siebzig Söhnen Jerubbaals begangene Verbrechen gerächt würde und Gott ihr Blut auf ihren Bruder Abimelech, der sie ermordet hatte, und auf die Bürger von Sichem kommen ließe, die ihm bei der Ermordung seiner Brüder behilflich gewesen waren.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 25, 'Die Bürger von Sichem legten also, um ihn verhaßt zu machen, auf den Bergeshöhen Wegelagerer in Hinterhalt; die mußten jeden ausplündern, der auf der Straße an ihnen vorüberzog. Das wurde dem Abimelech hinterbracht.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 26, 'Damals war nämlich Gaal, der Sohn Ebeds, mit seinen Brüdern gekommen und hatte sich in Sichem niedergelassen, und die Bürger von Sichem hatten Vertrauen zu ihm gewonnen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 27, 'Als sie nun einst aufs Feld hinausgezogen waren und die Weinlese gehalten und gekeltert hatten, veranstalteten sie ein Freudenfest, begaben sich in den Tempel ihres Gottes, aßen und tranken und stießen Verwünschungen gegen Abimelech aus.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 28, 'Da rief Gaal, der Sohn Ebeds, aus: »Wer ist Abimelech, und wer sind wir Sichemiten, daß wir seine Untertanen sein sollten? Ist er nicht ein Sohn Jerubbaals und Sebul sein Vogt? Müßte er nicht den Männern Hemors, des Stammvaters von Sichem, untertan sein? Warum sollen nun wir ihm dienen?');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 29, 'Hätte ich nur dies Volk unter meinem Befehl: ich wollte diesem Abimelech schon den Weg weisen und dem Abimelech sagen lassen: ›Verstärke dein Heer und rücke aus!‹«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 30, 'Als nun Sebul, der Stadthauptmann, Kunde von den Reden Gaals, des Sohnes Ebeds, erhielt, geriet er in Zorn;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 31, 'er sandte insgeheim Boten an Abimelech und ließ ihm sagen: »Wisse wohl: Gaal, der Sohn Ebeds, ist mit seinen Brüdern nach Sichem gekommen, und sie wiegeln nun die Stadt gegen dich auf.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 32, 'Mache dich also in der Nacht mit dem Kriegsvolk, das du bei dir hast, auf den Weg und lege dich draußen auf dem Felde in einen Hinterhalt.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 33, 'Frühmorgens aber, sobald die Sonne aufgeht, brich auf und überfalle die Stadt. Wenn er dann mit seinen Leuten gegen dich ausrückt, so verfahre mit ihm nach den Umständen.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 34, 'Da machte sich Abimelech mit allem Kriegsvolk, das er bei sich hatte, in der Nacht auf den Weg, und sie legten sich in vier Abteilungen in den Hinterhalt gegen Sichem.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 35, 'Als nun Gaal, der Sohn Ebeds, hinausging und an den Eingang des Stadttores trat, brach Abimelech mit seinen Leuten aus dem Hinterhalt hervor.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 36, 'Sobald Gaal die Leute erblickte, sagte er zu Sebul: »Da kommt ja Kriegsvolk von den Berghöhen herab!« Aber Sebul entgegnete ihm: »Den Schatten der Berge siehst du für Männer an.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 37, 'Doch Gaal blieb dabei: »Nein, es sind Krieger, die vom Nabel des Landes herabziehen, und dort ist noch eine Schar, die des Weges von der Wahrsager-Eiche her kommt«.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 38, 'Da rief Sebul ihm zu: »Wo ist denn nun dein großes Maul, mit dem du ausgerufen hast: ›Wer ist Abimelech, daß wir seine Untertanen sein sollten?‹ Das ist ja das Kriegsvolk, das du verachtet hast! So ziehe nun jetzt aus und kämpfe mit ihm!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 39, 'Da zog Gaal an der Spitze der Bürger von Sichem aus und wurde mit Abimelech handgemein;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 40, 'dieser aber schlug ihn zurück, und er mußte vor ihm fliehen, und viele blieben erschlagen liegen bis an den Eingang des Stadttores.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 41, 'Während Abimelech dann in Aruma blieb, vertrieb Sebul den Gaal und dessen Brüder, so daß sie nicht länger in Sichem bleiben konnten.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 42, 'Als dann am folgenden Morgen die Leute aufs Feld hinausgegangen waren, nahm Abimelech, der Kunde davon erhalten hatte,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 43, 'sein Kriegsvolk, teilte es in drei Abteilungen und legte sich draußen auf dem Felde in den Hinterhalt. Als er nun sah, wie die Leute aus der Stadt herauskamen, fiel er über sie her und machte sie nieder;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 44, 'dann stürmte er mit seiner Abteilung vor und nahm am Eingang des Stadttores Stellung, während die beiden anderen Abteilungen über alle die herfielen, welche auf dem Felde waren, und sie niederhieben.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 45, 'Abimelech bestürmte dann die Stadt jenen ganzen Tag hindurch, und als er sie erobert hatte, ließ er die Einwohner töten, zerstörte die Stadt und streute Salz über die ganze Stätte.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 46, 'Als die Bewohner der Burg von Sichem das vernahmen, begaben sie sich alle in den Keller des Tempels des Bundesgottes.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 47, 'Sobald nun dem Abimelech gemeldet wurde, daß alle Bewohner der Burg von Sichem dort beisammen seien,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 48, 'stieg er mit seiner gesamten Mannschaft auf den Berg Zalmon; dort nahm Abimelech seine Axt zur Hand, hieb einen Busch Holz ab, lud ihn sich auf die Schultern und befahl seinen Leuten: »Was ihr mich habt tun sehen, das tut auch ihr ohne Verzug!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 49, 'Da hieben auch sämtliche Krieger Mann für Mann einen Busch für sich ab, zogen dann hinter Abimelech her, warfen (das Holz) oben auf den Keller und setzten so den Keller von obenher in Brand, so daß nun auch alle Bewohner der Burg von Sichem ihren Tod fanden, ungefähr tausend Männer und Frauen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 50, 'Hierauf rückte Abimelech gegen Thebez, belagerte den Ort und eroberte ihn.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 51, 'Mitten im Ort stand aber ein fester Turm, in den sich alle Männer und Frauen, sämtliche Bürger des Orts, geflüchtet hatten; sie hatten sich daselbst eingeschlossen und waren auf das Dach des Turmes gestiegen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 52, 'Als nun Abimelech an den Turm herangerückt war und ihn bestürmte und dabei bis an den Eingang des Turmes heranging, um Feuer an ihn zu legen,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 53, 'schleuderte ihm eine Frau den oberen Stein einer Handmühle auf den Kopf und zerschmetterte ihm den Schädel.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 54, 'Da rief er schnell seinen Waffenträger herbei und befahl ihm: »Ziehe dein Schwert und töte mich vollends, damit man mir nicht nachsagen kann, ein Weib habe mich umgebracht!« Da durchbohrte ihn sein Waffenträger, und er starb.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 55, 'Als nun die Israeliten sahen, daß Abimelech tot war, kehrten sie ein jeder in seinen Wohnort zurück.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 56, 'So vergalt Gott dem Abimelech das Verbrechen, das er durch die Ermordung seiner siebzig Brüder an seinem Vater begangen hatte;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 57, 'und ebenso ließ Gott alle Freveltaten der Einwohner von Sichem auf ihr Haupt zurückfallen. So erfüllte sich an ihnen der Fluch Jothams, des Sohnes Jerubbaals.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 10, 1, 'Nach Abimelech trat dann zur Errettung Israels ein Mann aus dem Stamm Issaschar auf, nämlich Thola, der Sohn Puas, des Sohnes Dodos; er wohnte in Samir im Gebirge Ephraim');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 10, 2, 'und waltete als Richter in Israel dreiundzwanzig Jahre lang; dann starb er und wurde in Samir begraben.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 10, 3, 'Nach ihm trat Jair aus Gilead auf und richtete Israel zweiundzwanzig Jahre.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 10, 4, 'Er hatte dreißig Söhne, die auf dreißig Eselsfüllen ritten und dreißig Ortschaften besaßen, die man bis auf den heutigen Tag die ›Zeltdörfer Jairs‹ nennt; sie liegen in der Landschaft Gilead.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 10, 5, 'Dann starb Jair und wurde in Kamon begraben.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 10, 6, 'Aber die Israeliten taten wiederum, was dem HERRN mißfiel; denn sie dienten den Baalen und Astarten, den Göttern der Syrer und der Sidonier, den Göttern der Moabiter, der Ammoniter und der Philister; den HERRN aber verließen sie und dienten ihm nicht.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 10, 7, 'Da entbrannte der Zorn des HERRN gegen die Israeliten, so daß er sie in die Gewalt der Philister und in die Hand der Ammoniter fallen ließ;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 10, 8, 'die bedrückten und mißhandelten die Israeliten achtzehn Jahre lang, nämlich alle Israeliten jenseits des Jordans im Lande der Amoriter, die in Gilead wohnten.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 10, 9, 'Als nun die Ammoniter sogar über den Jordan zogen, um auch Juda, Benjamin und den Stamm Ephraim zu bekriegen, da gerieten die Israeliten in sehr große Angst.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 10, 10, 'Da riefen die Israeliten den HERRN laut um Hilfe an und bekannten: »Wir haben gegen dich gesündigt, und zwar dadurch, daß wir unsern Gott verlassen und den Baalen gedient haben!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 10, 11, 'Da antwortete der HERR den Israeliten: »Habe ich euch nicht von den Ägyptern und Amoritern, von den Ammonitern und Philistern errettet?');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 10, 12, 'Und als die Sidonier, die Amalekiter und die Midianiter euch bedrängten und ihr mich um Hilfe anrieft, habe ich euch da nicht aus ihrer Gewalt befreit?');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 10, 13, 'Ihr aber habt mich verlassen und anderen Göttern gedient; darum will ich euch hinfort nicht mehr erretten.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 10, 14, 'Geht hin und schreit um Hilfe zu den Göttern, die ihr euch erwählt habt: die mögen euch helfen, wenn ihr in Not seid!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 10, 15, 'Da beteten die Israeliten zum HERRN: »Wir haben gesündigt! Verfahre mit uns ganz so, wie es dir wohlgefällt, nur rette uns noch dies eine Mal!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 10, 16, 'Darauf entfernten sie die fremden Götter aus ihrer Mitte und verehrten den HERRN; da konnte er sein Erbarmen mit der Not Israels nicht länger zurückhalten.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 10, 17, 'Als nun die Ammoniter nach dem Aufgebot ihrer Kriegsmacht sich in Gilead lagerten und die Israeliten sich gesammelt und ein Lager bei Mizpa bezogen hatten,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 10, 18, 'da sagte das Volk, die Fürsten von Gilead, zueinander: »Wer ist der Mann, der zuerst den Angriff gegen die Ammoniter wagt? Er soll das Oberhaupt aller Bewohner Gileads sein!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 1, 'Nun war der Gileaditer Jephtha ein tapferer Held, obwohl der Sohn einer Dirne; sein Vater war irgendein Gileaditer.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 2, 'Als nun die (rechtmäßige) Frau des (betreffenden) Gileaditers ihm Söhne gebar und die Söhne dieser Frau herangewachsen waren, hatten sie Jephtha ausgestoßen und zu ihm gesagt: »Du sollst in unserer Familie nicht miterben!, denn du bist der Sohn einer fremden Frau!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 3, 'So war denn Jephtha vor seinen Brüdern geflohen und hatte sich in der Landschaft Tob niedergelassen, wo sich nichtsnutzige Leute um ihn sammelten, die mit ihm Raubzüge unternahmen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 4, 'Nun begab es sich nach einiger Zeit, daß die Ammoniter Krieg mit den Israeliten anfingen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 5, 'Als nun die Ammoniter gegen die Israeliten zu Felde zogen, machten sich die Ältesten der Gileaditer auf den Weg, um Jephtha aus der Landschaft Tob zu holen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 6, 'Sie baten ihn: »Komm und werde unser Anführer, damit wir gegen die Ammoniter kämpfen!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 7, 'Aber Jephtha antwortete den Ältesten der Gileaditer: »Seid ihr es nicht, die mich gehaßt und aus meines Vaters Hause vertrieben haben? Warum kommt ihr jetzt zu mir, wo ihr in Not seid?«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 8, 'Da erwiderten ihm die Ältesten der Gileaditer: »Eben deshalb sind wir jetzt wieder zu dir gekommen, und wenn du mit uns gehst und gegen die Ammoniter kämpfen willst, so sollst du bei uns das Oberhaupt aller Bewohner Gileads sein!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 9, 'Da antwortete Jephtha den Ältesten der Gileaditer: »Wenn ihr mich zurückholt, damit ich gegen die Ammoniter kämpfe, und der HERR sie von mir besiegt werden läßt, werde ich dann wirklich euer Oberhaupt sein?«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 10, 'Da erwiderten ihm die Ältesten von Gilead: »Der HERR sei Zeuge zwischen uns (und strafe uns), wenn wir nicht so tun, wie du es verlangst!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 11, 'So ging denn Jephtha mit den Ältesten von Gilead, und das Kriegsvolk machte ihn zu seinem Oberhaupt und zum Befehlshaber über sich [und Jephtha trug alles, was er zu sagen hatte, dem HERRN in Mizpa vor].');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 12, 'Hierauf sandte Jephtha Boten an den König der Ammoniter und ließ ihm sagen: »Was willst du von mir, daß du gegen mich herangezogen bist, um mein Land zu bekriegen?«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 13, 'Der König der Ammoniter antwortete den Boten Jephthas: »Israel hat mir, als es aus Ägypten heraufzog, mein Land weggenommen vom Arnon bis an den Jabbok und bis an den Jordan: gib es mir also jetzt gutwillig zurück!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 14, 'Darauf sandte Jephtha nochmals Boten an den König der Ammoniter');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 15, 'und ließ ihm sagen: »Jephtha macht dich auf folgendes aufmerksam: Die Israeliten haben den Moabitern und den Ammonitern ihr Land nicht weggenommen,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 16, 'sondern als die Israeliten beim Auszug aus Ägypten durch die Wüste bis ans Schilfmeer gewandert und in Kades angekommen waren,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 17, 'schickten sie Gesandte an den König der Edomiter und ließen ihn um freien Durchzug durch sein Land bitten; aber der König der Edomiter wollte davon nichts wissen. Darauf schickten sie auch an den König der Moabiter, aber auch der wollte es nicht bewilligen. So mußten denn die Israeliten in Kades bleiben,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 18, 'dann durch die Wüste ziehen, um das Land der Edomiter und das Land der Moabiter herumwandern und nach ihrer Ankunft auf der Ostseite des Landes der Moabiter jenseits des Arnons lagern, ohne das Gebiet der Moabiter betreten zu haben; denn der Arnon bildet die Grenze der Moabiter.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 19, 'Darauf schickten die Israeliten Gesandte an den Amoriterkönig Sihon, der in Hesbon seinen Wohnsitz hatte, und baten ihn um freien Durchzug durch sein Land, um an das Ziel ihrer Wanderung zu gelangen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 20, 'Aber Sihon wollte den Israeliten den Durchzug durch sein Gebiet aus Mißtrauen nicht gestatten, sondern bot sein gesamtes Kriegsvolk auf, bezog ein Lager bei Jahaz und griff die Israeliten an.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 21, 'Da ließ der HERR, der Gott Israels, Sihon mit seinem ganzen Heer in die Hand der Israeliten fallen, so daß diese sie besiegten. So nahmen die Israeliten das ganze Land der Amoriter, die in jenem Lande wohnten, in Besitz');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 22, 'und bemächtigten sich des ganzen Gebiets der Amoriter vom Arnon bis an den Jabbok und von der Wüste bis zum Jordan.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 23, 'Und jetzt, nachdem der HERR, der Gott Israels, die Amoriter vor seinem Volke Israel vertrieben hat, willst du uns aus ihrem Besitz verdrängen?');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 24, 'Nicht wahr? Was dein Gott Kamos dir zum Besitz gibt, das nimmst du in Besitz; und alles, was der HERR, unser Gott, vor uns vertrieben hat, in dessen Besitz treten wir ein!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 25, 'Und nun: bist du etwa besser als der Moabiterkönig Balak, der Sohn Zippors? Hat er etwa mit Israel gerechtet oder je Krieg gegen sie geführt,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 26, 'während Israel in Hesbon und den zugehörigen Ortschaften sowie in Aroer und den zugehörigen Ortschaften und in allen Städten, die auf beiden Seiten des Arnons liegen, dreihundert Jahre lang wohnte? Warum habt ihr sie denn in jener Zeit nicht wieder an euch gerissen?');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 27, 'Ich habe dir also nichts zuleide getan, du aber handelst unrecht gegen mich, indem du Krieg mit mir anfängst: der HERR, der Richter, möge heute zwischen den Israeliten und den Ammonitern richten!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 28, 'Aber der König der Ammoniter ließ die Vorstellungen unbeachtet, die Jephtha ihm hatte entbieten lassen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 29, 'Da kam der Geist des HERRN über Jephtha, und er zog durch Gilead und Manasse, zog dann weiter nach Mizpe in Gilead, und von Mizpe in Gilead zog er gegen die Ammoniter.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 30, 'Damals brachte er dem HERRN folgendes Gelübde dar: »Wenn du die Ammoniter wirklich in meine Gewalt gibst,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 31, 'so soll der, welcher mir (zuerst) aus der Tür meines Hauses entgegenkommt, wenn ich wohlbehalten aus dem Kriege mit den Ammonitern heimkehre, der soll dem HERRN gehören, und ich will ihn als Brandopfer darbringen!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 32, 'Hierauf zog Jephtha gegen die Ammoniter, um ihnen eine Schlacht zu liefern, und der HERR gab sie in seine Hand:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 33, 'er brachte ihnen eine schwere Niederlage bei, von Aroer an bis in die Gegend von Minnith [zwanzig Städte] und bis nach Abel-Keramim. So wurden die Ammoniter vor den Israeliten gedemütigt.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 34, 'Als nun Jephtha nach Mizpe in sein Haus zurückkehrte, siehe, da trat seine Tochter heraus ihm entgegen mit Handpauken und im Reigentanz; sie war sein einziges Kind: außer ihr hatte er weder Sohn noch Tochter.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 35, 'Bei ihrem Anblick zerriß er seine Kleider und rief aus: »Ach, meine Tochter! Du beugst mich tief darnieder! O daß gerade du mich in solches Leid bringen mußt! Ich habe mich ja gegen den HERRN verpflichtet und kann mein Gelübde nicht zurücknehmen!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 36, 'Da erwiderte sie ihm: »Lieber Vater, hast du dich durch ein Gelübde gegen den HERRN verpflichtet, so verfahre mit mir nach dem Gelübde, das du ausgesprochen hast, nachdem der HERR dich Rache an deinen Feinden, den Ammonitern, hat nehmen lassen!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 37, 'Dann bat sie ihren Vater: »Nur dies eine möge mir noch gewährt werden: laß mir noch zwei Monate Zeit, damit ich mich auf den Bergen ergehe und meine Jungfrauschaft mit meinen Freundinnen beweine!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 38, 'Da antwortete er ihr: »Ja, gehe hin!« und entließ sie auf zwei Monate; und sie ging mit ihren Freundinnen hin und beweinte ihre Jungfrauschaft auf den Bergen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 39, 'Aber nach Ablauf von zwei Monaten kehrte sie zu ihrem Vater zurück, und er vollzog an ihr das Gelübde, das er getan hatte; sie hatte aber nie mit einem Manne ein Verhältnis gehabt. Seitdem ist die Sitte in Israel aufgekommen:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 40, 'alljährlich ziehen die israelitischen Mädchen aus, um die Tochter des Gileaditers Jephtha in Liedern zu feiern, vier Tage im Jahr.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 12, 1, 'Es wurden aber die Ephraimiten aufgeboten; sie zogen nordwärts und ließen dem Jephtha sagen: »Warum bist du zum Krieg gegen die Ammoniter ausgezogen, ohne uns zur Teilnahme am Feldzuge aufzufordern? Nun wollen wir dir dein Haus über dem Kopf in Brand stecken!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 12, 2, 'Jephtha erwiderte ihnen: »Ich und mein Volk haben einen schweren Streit mit den Ammonitern gehabt, und ich habe euch um Hilfe angerufen, aber ihr habt mir keinen Beistand gegen sie geleistet.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 12, 3, 'Als ich nun sah, daß du mir nicht zu Hilfe kommen wolltest, setzte ich mein Leben aufs Spiel und zog gegen die Ammoniter zu Felde, und der HERR gab sie in meine Gewalt. Warum zieht ihr also jetzt gegen mich heran, um Händel mit mir anzufangen?«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 12, 4, 'Darauf bot Jephtha alle Männer von Gilead auf und griff die Ephraimiten an, und diese wurden von den Gileaditern geschlagen; sie hatten nämlich die Behauptung ausgesprochen: »Flüchtige Ephraimiten seid ihr; Gilead liegt nämlich in der Mitte von Ephraim und Manasse.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 12, 5, 'Die Gileaditer aber hatten die Jordanfurten nach Ephraim zu besetzt. Sooft nun flüchtige Ephraimiten baten: »Laßt mich hinüber!«, fragten die Männer von Gilead den Betreffenden, ob er ein Ephratiter sei; antwortete er dann mit nein,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 12, 6, 'so forderte man ihn auf, das Wort »Schibboleth« auszusprechen. Sagte er dann »Sibboleth«, weil ihm die richtige Aussprache unmöglich war, so ergriffen sie ihn und machten ihn an den Jordanfurten nieder. So kamen damals 42000 Ephraimiten ums Leben.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 12, 7, 'Jephtha aber war sechs Jahre lang Richter in Israel; dann starb Jephtha, der Gileaditer, und wurde in einer der Städte Gileads begraben.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 12, 8, 'Nach ihm war Ibzan aus Bethlehem Richter in Israel.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 12, 9, 'Er hatte dreißig Söhne, und dreißig Töchter verheiratete er nach auswärts, und dreißig Töchter führte er seinen Söhnen von auswärts als Gattinnen zu. Nachdem er sieben Jahre lang als Richter in Israel gewaltet hatte,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 12, 10, 'starb Ibzan und wurde in Bethlehem begraben.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 12, 11, 'Nach ihm war Elon aus dem Stamme Sebulon Richter in Israel und zwar zehn Jahre lang.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 12, 12, 'Als Elon aus Sebulon dann starb, wurde er in Ajjalon im Lande Sebulon begraben.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 12, 13, 'Nach ihm war Abdon aus Pirathon, der Sohn Hillels, Richter in Israel.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 12, 14, 'Er hatte vierzig Söhne und dreißig Enkel, die auf siebzig Eselsfüllen ritten. Nachdem er acht Jahre lang Richter in Israel gewesen war,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 12, 15, 'starb Abdon aus Pirathon, der Sohn Hillels, und wurde zu Pirathon im Lande Ephraim am Amalekiterberge begraben.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 13, 1, 'Als dann die Israeliten wiederum taten, was dem HERRN mißfiel, ließ der HERR sie in die Hand der Philister fallen, vierzig Jahre lang.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 13, 2, 'Nun war da ein Mann aus Zora vom Geschlecht der Daniten namens Manoah, dessen Frau unfruchtbar war und keine Kinder hatte.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 13, 3, 'Da erschien der Engel des HERRN der Frau und sagte zu ihr: »Du bist bis jetzt unfruchtbar gewesen und kinderlos geblieben, aber wisse wohl: du wirst guter Hoffnung und Mutter eines Sohnes werden.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 13, 4, 'So nimm dich nun fortan in acht, trinke keinen Wein und keine berauschenden Getränke und iß nichts Unreines.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 13, 5, 'Denn wisse wohl: wenn du guter Hoffnung und Mutter eines Sohnes geworden bist, so darf kein Schermesser auf sein Haupt kommen; denn der Knabe soll ein Gottgeweihter von Geburt an sein, und er wird den Anfang damit machen, Israel von der Herrschaft der Philister zu befreien.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 13, 6, 'Da ging die Frau hin und erzählte ihrem Manne: »Ein Gottesmann ist zu mir gekommen, der ganz wie ein Engel Gottes aussah, sehr furchterregend; ich habe ihn aber nicht gefragt, woher er sei, und seinen Namen hat er mir nicht angegeben.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 13, 7, 'Er hat mir aber gesagt: ›Du wirst alsbald guter Hoffnung und Mutter eines Sohnes werden. So trinke denn fortan keinen Wein und keine berauschenden Getränke und iß nichts Unreines; denn ein Gottgeweihter soll der Knabe von Geburt an bis zu seinem Todestage sein.‹«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 13, 8, 'Darauf betete Manoah zum HERRN folgendermaßen: »Ach, Allherr, laß doch den Gottesmann, den du gesandt hast, noch einmal zu uns kommen und uns darüber belehren, wie wir es mit dem Knaben, der geboren werden soll, zu halten haben!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 13, 9, 'Und Gott erhörte das Gebet Manoahs, so daß der Engel Gottes nochmals zu der Frau kam, während sie sich gerade auf dem Felde befand und ihr Mann Manoah nicht bei ihr war.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 13, 10, 'Da lief die Frau eiligst hin und berichtete es ihrem Manne mit den Worten: »Soeben ist mir der Mann wieder erschienen, der schon neulich zu mir gekommen ist!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 13, 11, 'Da machte sich Manoah auf, hinter seiner Frau her, und als er zu dem Manne gekommen war, fragte er ihn: »Bist du der Mann, der meiner Frau die Verheißung gegeben hat?«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 13, 12, 'Er antwortete: »Ja, ich bin es.« Da fragte Manoah weiter: »Wenn nun deine Verheißung eintrifft, wie soll es dann mit dem Knaben gehalten werden, und was hat er zu tun?«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 13, 13, 'Da antwortete der Engel des HERRN dem Manoah: »Die Frau muß sich vor dem Genuß alles dessen hüten, was ich ihr angegeben habe:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 13, 14, 'sie darf nichts genießen, was vom Weinstock kommt; Wein und berauschende Getränke darf sie nicht trinken und nichts Unreines essen; sie muß alles beobachten, was ich ihr geboten habe.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 13, 15, 'Da sagte Manoah zu dem Engel des HERRN: »Wir möchten dich gern noch länger bei uns behalten und dir ein Ziegenböckchen vorsetzen.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 13, 16, 'Aber der Engel des HERRN erwiderte dem Manoah: »Wenn du mich auch zum Bleiben veranlaßtest, würde ich doch von deinem Mahl nichts genießen; willst du aber ein Brandopfer zurüsten, so bringe es dem HERRN zu Ehren dar!« – Manoah wußte nämlich nicht, daß es der Engel des HERRN war.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 13, 17, 'Hierauf fragte Manoah den Engel des HERRN: »Wie heißt du? Wir möchten dir gern eine Ehre antun, wenn deine Verheißung eintrifft.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 13, 18, 'Aber der Engel des HERRN antwortete ihm: »Warum fragst du da nach meinem Namen, der doch geheimnisvoll ist?«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 13, 19, 'Da holte Manoah das Ziegenböckchen und das (zugehörige) Speisopfer und brachte es auf dem Felsen dem HERRN dar, wobei dieser ein Wunder geschehen ließ, während Manoah und seine Frau zusahen;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 13, 20, 'denn als die Flamme vom Altar gen Himmel aufschlug, fuhr der Engel des HERRN in der Flamme des Altars in die Höhe. Als Manoah und seine Frau das sahen, warfen sie sich auf ihr Angesicht zur Erde nieder;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 13, 21, 'der Engel des HERRN aber erschien dem Manoah und seiner Frau fortan nicht wieder. Doch Manoah hatte nun erkannt, daß es der Engel des HERRN gewesen war,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 13, 22, 'und sagte zu seiner Frau: »Wir müssen sicherlich sterben, denn wir haben Gott gesehen!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 13, 23, 'Aber seine Frau entgegnete ihm: »Wenn der HERR uns hätte töten wollen, so hätte er kein Brand- und Speisopfer von uns angenommen und hätte uns dies alles nicht sehen lassen und jetzt uns nicht solche Ankündigungen gemacht.« –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 13, 24, 'Die Frau aber gebar einen Sohn und nannte ihn Simson; und der Knabe wuchs heran, und der HERR segnete ihn.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 13, 25, 'Als dann der Geist des HERRN sich in ihm zu regen begann im Lager Dans zwischen Zora und Esthaol,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 14, 1, 'ging Simson nach Thimna hinab und lernte dort ein Mädchen unter den Töchtern der Philister kennen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 14, 2, 'Nach seiner Rückkehr erzählte er es seinen Eltern mit den Worten: »Ich habe in Thimna ein Mädchen unter den Töchtern der Philister kennengelernt: nehmt sie mir nun zur Frau!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 14, 3, 'Da erwiderten ihm seine Eltern: »Gibt’s denn unter den Töchtern deiner Stammesgenossen und in unserem ganzen Volke kein Weib mehr, daß du hingehen mußt, um dir eine Frau von den heidnischen Philistern zu holen?« Doch Simson erwiderte seinem Vater: »Diese nimm mir zur Frau! Denn gerade sie gefällt mir.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 14, 4, 'Seine Eltern wußten eben nicht, daß dies eine Fügung vom HERRN war, der nach einem Anlaß zum Vorgehen gegen die Philister suchte; denn damals waren die Philister Herren über Israel.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 14, 5, 'So ging denn Simson mit seinen Eltern nach Thimna hinab, und als sie bei den Weinbergen von Thimna angelangt waren, trat ihm plötzlich ein junger Löwe brüllend in den Weg.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 14, 6, 'Da kam der Geist des HERRN über ihn, so daß er den Löwen zerriß, wie man ein Böckchen zerreißt, ohne daß er irgend etwas in der Hand hatte; seinen Eltern erzählte er aber nichts von dem, was er getan hatte.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 14, 7, 'Dann ging er (nach Thimna) hinab und besprach sich mit dem Mädchen; denn sie gefiel ihm wohl.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 14, 8, 'Als er dann nach einiger Zeit wieder hinging, um Hochzeit mit ihr zu machen, und vom Wege abbog, um sich den toten Löwen noch einmal anzusehen, da befand sich im Körper des Löwen ein Bienenschwarm und Honig.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 14, 9, 'Diesen nahm er heraus in seine hohlen Hände und aß im Weitergehen davon; und als er dann zu seinen Eltern gekommen war, gab er auch ihnen davon zu essen, ohne ihnen jedoch mitzuteilen, daß er den Honig aus dem Körper des toten Löwen herausgenommen hatte.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 14, 10, 'Hierauf brachte sein Vater die Sache mit dem Mädchen in Ordnung, und Simson richtete daselbst ein Gelage her; denn so pflegten es die jungen Leute dort zu halten.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 14, 11, 'Als sie ihn nun sahen, holten sie dreißig Brautgesellen herbei, die um ihn sein sollten.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 14, 12, 'Zu diesen sagte Simson: »Ich will euch einmal ein Rätsel aufgeben! Wenn ihr es mir innerhalb der sieben Tage des Gelages erraten könnt und die Lösung findet, so gebe ich euch dreißig Unterkleider und dreißig Festgewänder;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 14, 13, 'könnt ihr mir aber die Lösung nicht angeben, so müßt ihr mir dreißig Unterkleider und dreißig Festgewänder geben.« Sie antworteten: »Gib uns dein Rätsel auf, daß wir es hören!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 14, 14, 'Da sagte er zu ihnen: »Fraß kam aus dem Fresser, und Süßigkeit kam aus dem Starken.« Drei Tage lang waren sie nicht imstande, das Rätsel zu lösen;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 14, 15, 'am vierten Tage aber sagten sie zu Simsons Frau: »Berede deinen Mann, daß er uns die Lösung des Rätsels angibt; sonst verbrennen wir dich samt deines Vaters Hause mit Feuer! Ihr habt uns wohl hierher eingeladen, um uns arm zu machen?«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 14, 16, 'Da brach die Frau Simsons in Tränen vor ihm aus und sagte: »Nur Haß hegst du gegen mich, aber keine Liebe! Du hast meinen Landsleuten das Rätsel aufgegeben und mir die Lösung nicht mitgeteilt!« Da erwiderte er ihr: »Bedenke doch: meinen eigenen Eltern habe ich die Lösung nicht verraten und sollte sie dir angeben?«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 14, 17, 'So weinte sie denn vor ihm die sieben Tage hindurch, solange sie das Gelage hielten; endlich am siebten Tage teilte er ihr die Lösung mit, weil sie ihm keine Ruhe ließ, sie aber verriet die Lösung ihren Landsleuten.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 14, 18, 'Da sagten denn die Männer der Stadt am siebten Tage zu ihm, ehe die Sonne unterging: »Was ist süßer als Honig, und was ist stärker als ein Löwe?« Er antwortete ihnen: »Hättet ihr nicht mit meinem Rinde gepflügt, so hättet ihr mein Rätsel nicht erraten!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 14, 19, 'Da kam der Geist des HERRN über ihn, so daß er nach Askalon hinabging und dort dreißig Mann von ihnen erschlug; diesen nahm er alles ab, was sie an sich hatten, und gab die Festgewänder denen, die das Rätsel gelöst hatten; dann kehrte er voller Zorn in das Haus seines Vaters zurück.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 14, 20, 'Simsons Frau aber wurde an einen von seinen Hochzeitsgenossen verheiratet, der sein Brautführer gewesen war.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 15, 1, 'Nach einiger Zeit aber, in den Tagen der Weizenernte, wollte Simson seine Frau besuchen, indem er ihr ein Ziegenböckchen mitbrachte; er dachte dabei: »Ich will zu meiner Frau in die Frauenwohnung gehen.« Doch ihr Vater gestattete ihm nicht hineinzugehen,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 15, 2, 'sondern sagte: »Ich mußte doch fest annehmen, daß du nichts mehr von ihr wissen wolltest; daher habe ich sie einem von deinen Hochzeitsgenossen zur Frau gegeben. Aber ihre jüngere Schwester ist noch schöner als sie: die soll deine Frau werden an ihrer Statt!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 15, 3, 'Da erwiderte ihnen Simson: »Diesmal haben mir die Philister nichts vorzuwerfen, wenn ich ihnen einen Denkzettel gebe!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 15, 4, 'Er ging also hin und fing dreihundert Füchse, nahm dann Feuerbrände, kehrte Schwanz gegen Schwanz und brachte einen Feuerbrand mitten zwischen je zwei Schwänzen an.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 15, 5, 'Hierauf zündete er die Feuerbrände an, jagte die Tiere in die Kornfelder der Philister und setzte dadurch sowohl die Garbenhaufen als auch das auf dem Halm stehende Getreide und selbst die Weinberge und Ölbaumgärten in Brand.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 15, 6, 'Als nun die Philister fragten: »Wer hat das getan?«, hieß es: »Simson, der Schwiegersohn des Thimniters, weil der ihm seine Frau genommen und sie einem von seinen Hochzeitsgenossen gegeben hat.« Da kamen die Philister herangezogen und verbrannten sie samt ihres Vaters Hause.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 15, 7, 'Simson aber sagte zu ihnen: »Wenn ihr es so treibt, will ich nicht eher ruhen, als bis ich mich an euch gerächt habe!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 15, 8, 'Hierauf richtete er sie mit Schlägen so zu, daß kein gesundes Glied an ihnen blieb; dann ging er hinab und nahm seinen Wohnsitz in der Felsenkluft von Etham.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 15, 9, 'Da zogen die Philister hinauf, lagerten sich in Juda und breiteten sich bei Lehi aus.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 15, 10, 'Als nun die Judäer fragten: »Warum seid ihr gegen uns heraufgezogen?«, antworteten sie: »Um Simson gefangenzunehmen, sind wir hergekommen; wir wollen ihm Gleiches mit Gleichem vergelten.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 15, 11, 'Da zogen dreitausend Mann aus Juda nach der Felsenkluft von Etham hinab und sagten zu Simson: »Weißt du nicht, daß die Philister Herren über uns sind? Was hast du uns da angerichtet!« Simson antwortete ihnen: »Wie sie mir getan, so habe ich ihnen wieder getan.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 15, 12, 'Da sagten sie zu ihm: »Wir sind hergekommen, um dich zu binden und dich den Philistern auszuliefern.« Simson entgegnete ihnen: »Leistet mir einen Schwur, daß ihr selbst mich nicht erschlagen wollt!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 15, 13, 'Sie antworteten ihm: »Nein, wir wollen dich nur binden und dich ihnen dann ausliefern; aber töten wollen wir dich nicht.« Darauf banden sie ihn mit zwei neuen Stricken und führten ihn aus der Felsenkluft weg hinauf.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 15, 14, 'Als er nun bis Lehi gekommen war und die Philister seine Ankunft mit Jubelgeschrei begrüßten, da kam der Geist des HERRN über ihn, so daß die Stricke an seinen Armen wie Flachsfäden wurden, die vom Feuer versengt sind, und seine Fesseln ihm an den Händen zergingen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 15, 15, 'Als er dann einen noch frischen Eselskinnbacken fand, streckte er seine Hand aus, ergriff ihn und erschlug damit tausend Mann.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 15, 16, 'Da rief Simson aus: »Mit dem Eselskinnbacken habe ich sie gründlich geschoren! Mit dem Eselskinnbacken habe ich tausend Mann erschlagen!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 15, 17, 'Als er diese Worte ausgerufen hatte, warf er den Kinnbacken weg; und man nannte jenen Ort seitdem »Kinnbackenhöhe«.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 15, 18, 'Nun aber dürstete ihn sehr; daher betete er laut zum HERRN: »Du hast durch die Hand deines Knechtes diesen großen Sieg herbeigeführt, und nun soll ich verdursten und den Heiden in die Hände fallen?«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 15, 19, 'Da spaltete Gott die Vertiefung in dem Kinnbacken, so daß Wasser daraus hervorfloß; und als er getrunken hatte, kehrten seine Lebensgeister zurück, und er erholte sich wieder; daher nannte man (jenen Ort) »Quelle des Rufers«; sie befindet sich bei Lehi noch heutigen Tages. –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 15, 20, 'Er war dann zwanzig Jahre lang Richter in Israel zur Zeit der Herrschaft der Philister.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 16, 1, 'Als Simson sich einst nach Gaza begeben hatte, sah er dort eine Dirne und kehrte bei ihr ein.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 16, 2, 'Als nun den Einwohnern von Gaza berichtet wurde, Simson sei dorthin gekommen, umstellten sie ihn und lauerten ihm die ganze Nacht am Stadttor auf, verhielten sich aber die ganze Nacht hindurch ruhig, weil sie dachten: »(Wir wollen warten), bis es am Morgen hell wird, dann wollen wir ihn erschlagen!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 16, 3, 'Simson aber blieb nur bis Mitternacht liegen; um Mitternacht aber stand er auf, faßte die beiden Flügel des Stadttors samt den beiden Pfosten, riß sie mitsamt dem Riegel heraus, lud sie sich auf die Schultern und trug sie auf den Gipfel des Berges, der gegen Hebron hin liegt.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 16, 4, 'Später gewann er ein Mädchen im Tale Sorek lieb, die hieß Delila.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 16, 5, 'Zu dieser kamen die Fürsten der Philister hinauf und sagten zu ihr: »Rede ihm zu und suche zu erfahren, woher seine große Kraft stammt und wie wir ihn überwältigen können, um ihn zu binden und unschädlich zu machen; wir würden dir dann auch jeder 1100 Silberstücke geben.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 16, 6, 'Da bat Delila den Simson: »Verrate mir doch, woher deine große Kraft kommt und womit man dich binden müßte, um dich zu überwältigen.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 16, 7, 'Simson antwortete ihr: »Wenn man mich mit sieben frischen, noch nicht ausgetrockneten Sehnen bände, so würde ich schwach sein und wie jeder andere Mensch werden.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 16, 8, 'Da brachten die Fürsten der Philister sieben frische, noch nicht ausgetrocknete Sehnen zu ihr hinauf, und sie band ihn damit,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 16, 9, 'während sich Leute, die ihn überfallen sollten, bei ihr im Frauengemach befanden. Als sie ihm nun zurief: »Die Philister überfallen dich, Simson!«, da zerriß er die Sehnen, wie ein Wergfaden zerreißt, wenn er Feuer riecht; und seine Kraft blieb unerklärt.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 16, 10, 'Da sagte Delila zu Simson: »Siehe, du hast mich betrogen und mir Lügen vorgeredet. Verrate mir jetzt doch, womit man dich binden kann!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 16, 11, 'Da antwortete er ihr: »Wenn man mich fest mit neuen Seilen bände, die noch zu keiner Arbeit benutzt sind, so würde ich schwach sein und wie jeder andere Mensch werden.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 16, 12, 'Da nahm Delila neue Seile und band ihn damit; dann rief sie ihm zu: »Die Philister überfallen dich, Simson!« – es befanden sich aber (auch diesmal) Leute, die ihn überfallen sollten, im Frauengemach –; da riß er die Stricke von seinen Armen ab wie einen Faden.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 16, 13, 'Nun sagte Delila zu Simson: »Bisher hast du mich betrogen und mir Lügen vorgeredet; verrate mir doch, womit man dich binden kann!« Da antwortete er ihr: »Wenn du die sieben Locken meines Kopfes in den Aufzug eines Gewebes hineinwebtest und sie mit dem Pflock festschlügest, so würde ich schwach sein und wie jeder andere Mensch werden.« Da ließ sie ihn einschlafen, webte die sieben Locken seines Kopfes in den Aufzug eines Gewebes hinein');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 16, 14, 'und schlug den Aufzug mit dem Pflock fest. Als sie ihm nun zurief: »Die Philister überfallen dich, Simson!« und er aus seinem Schlaf erwachte, riß er den Webepflock samt dem Aufzug heraus.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 16, 15, 'Da sagte sie zu ihm: »Wie kannst du behaupten, du habest mich lieb, während doch dein Herz mir gar nicht gehört? Du hast mich nun schon dreimal betrogen und mir nicht verraten, woher deine große Kraft rührt.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 16, 16, 'Als sie ihm nun alle Tage mit ihren Reden zusetzte und ihm keine Ruhe ließ, so daß er gar keine Freude mehr am Leben hatte,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 16, 17, 'schüttete er ihr sein ganzes Herz aus, so daß er zu ihr sagte: »Noch kein Schermesser ist auf mein Haupt gekommen; denn ich bin ein Gottgeweihter von meiner Geburt an; würde ich geschoren, so würde meine Kraft von mir weichen; ich würde dann schwach sein und wie alle anderen Menschen werden.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 16, 18, 'Da nun Delila erkannte, daß er ihr sein ganzes Herz ausgeschüttet hatte, ließ sie die Fürsten der Philister rufen und ihnen sagen: »Diesmal müßt ihr heraufkommen, denn er hat mir sein ganzes Herz entdeckt.« Da begaben sich die Fürsten der Philister zu ihr hinauf und brachten auch das Geld mit.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 16, 19, 'Als sie ihn dann auf ihrem Schoße hatte einschlafen lassen, rief sie einen Mann herbei, der die sieben Locken auf seinem Haupt abscheren mußte; da wurde er schwächer und schwächer, und seine Kraft wich von ihm.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 16, 20, 'Als sie nun rief: »Die Philister überfallen dich, Simson!« und er aus seinem Schlaf erwachte, dachte er: »Ich werde mich auch jetzt wie die vorigen Male frei machen und glücklich davonkommen!« Er wußte ja nicht, daß der HERR von ihm gewichen war.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 16, 21, 'Da ergriffen ihn die Philister, stachen ihm die Augen aus und führten ihn nach Gaza hinab; dort legten sie ihn in eherne Doppelketten, und er mußte im Gefängnis die Handmühle drehen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 16, 22, 'Allmählich wuchs ihm aber das Haupthaar wieder, nachdem es abgeschoren worden war.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 16, 23, 'Nun kamen einst die Fürsten der Philister zusammen, um ihrem Gott Dagon ein großes Schlachtopfer zu veranstalten und ein Freudenfest zu feiern; denn sie sagten: »Unser Gott hat unsern Feind Simson in unsere Hand gegeben!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 16, 24, 'Als ihn nun das Volk erblickte, priesen sie ihren Gott, indem sie ausriefen: »Unser Gott hat unsern Feind in unsere Hand gegeben, der unsere Felder verwüstet und viele von unsern Leuten erschlagen hat.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 16, 25, 'Als nun ihr Herz guter Dinge war, riefen sie: »Laßt Simson herkommen, damit er uns belustige!« So ließ man denn Simson aus dem Gefängnis holen, und er mußte vor ihnen spielen. Da man ihn nun zwischen die Säulen (der Halle) gestellt hatte,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 16, 26, 'bat Simson den Burschen, der ihn an der Hand gefaßt hielt: »Laß mich doch mal los, damit ich die Säulen betaste, auf denen das Haus ruht: ich möchte mich an sie anlehnen!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 16, 27, 'Das Haus war aber voll von Männern und Frauen; auch alle Fürsten der Philister waren dort anwesend, und auf dem Dache befanden sich gegen dreitausend Männer und Frauen, die dem Spiel Simsons zugesehen hatten.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 16, 28, 'Da betete Simson zum HERRN mit den Worten: »O HERR, mein Gott! Gedenke doch meiner und verleihe mir nur dies eine Mal noch Kraft, o Gott, damit ich Rache an den Philistern nehme für eins von meinen beiden Augen!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 16, 29, 'Darauf umfaßte Simson die beiden Mittelsäulen, auf denen das Haus ruhte, die eine mit seinem rechten, die andere mit seinem linken Arm, und stemmte sich gegen sie;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 16, 30, 'und indem er ausrief: »Nun will ich mit den Philistern sterben!«, neigte er sich mit aller Kraft vornüber. Da stürzte das Haus auf die Fürsten und auf alle Leute, die darin waren, und die Zahl der Toten, die er im Sterben tötete, war größer als die Zahl derer, die er während seines Lebens getötet hatte.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 16, 31, 'Darauf kamen seine Stammesgenossen und seine ganze Familie hinab und holten seinen Leichnam; sie brachten ihn dann hinauf und begruben ihn zwischen Zora und Esthaol im Grabe seines Vaters Manoah. Er war aber zwanzig Jahre lang Richter in Israel gewesen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 17, 1, 'Es war einst ein Mann vom Gebirge Ephraim mit Namen Micha;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 17, 2, 'der sagte zu seiner Mutter: »Die elfhundert Silberstücke, die dir entwendet worden sind und um derenwillen du einen Fluch ausgestoßen und ihn gar vor meinen Ohren ausgesprochen hast – wisse, das Geld ist in meinem Besitz: ich selbst habe es genommen; nun aber will ich es dir zurückgeben!« Da antwortete seine Mutter: »Gesegnet seist du vom HERRN, mein Sohn!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 17, 3, 'Als er nun die elfhundert Silberstücke seiner Mutter zurückgegeben hatte, sagte diese: »Ich will das Geld dem HERRN weihen (und es) aus meiner Hand zugunsten meines Sohnes (hingeben): es soll ein geschnitztes und gegossenes Gottesbild davon angefertigt werden.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 17, 4, 'Als er nun das Geld seiner Mutter zurückgegeben hatte, nahm diese zweihundert Silberstücke und gab sie einem Goldschmied, der davon ein geschnitztes und gegossenes Gottesbild anfertigte, das nun im Hause Michas aufgestellt wurde.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 17, 5, 'So besaß denn dieser Micha ein Gotteshaus; er ließ dann noch ein kostbares Schulterkleid und einen Hausgott anfertigen und stellte einen seiner Söhne an, daß er ihm (dem Micha) als Priester diente.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 17, 6, 'Zu jener Zeit gab es noch keinen König in Israel; ein jeder tat, was ihm beliebte.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 17, 7, 'Nun war da ein junger Mann aus Bethlehem in Juda aus dem Geschlecht Judas; der war ein Levit und hielt sich dort als Fremder auf.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 17, 8, 'Dieser Mann verließ die Stadt Bethlehem in Juda, um sich an irgendeinem anderen Orte, wo es sich gerade träfe, als Fremder niederzulassen, und kam bei seiner Wanderung im Gebirge Ephraim zum Hause Michas.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 17, 9, 'Dieser fragte ihn: »Woher kommst du?« Er antwortete ihm: »Ich bin ein Levit aus Bethlehem in Juda und bin unterwegs, um mich an irgendeinem Ort niederzulassen, wo ich etwas Geeignetes finde.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 17, 10, 'Da sagte Micha zu ihm: »Bleibe bei mir und sei mir ein Vater und Priester, so will ich dir jährlich zehn Silberstücke geben und für Kleidung und deinen Lebensunterhalt aufkommen.« Als er dann dem Leviten weiter zuredete,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 17, 11, 'erklärte dieser sich einverstanden, bei dem Manne zu bleiben; und der junge Mann galt ihm wie einer seiner Söhne.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 17, 12, 'Micha nahm also den Leviten in seinen Dienst, so daß der junge Mann sein Priester wurde und im Hause Michas blieb.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 17, 13, 'Micha aber dachte: »Jetzt bin ich gewiß, daß der HERR es mir wird glücken lassen, weil ich einen Leviten zum Priester (gewonnen) habe.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 18, 1, 'Zu jener Zeit gab es noch keinen König in Israel; und der Stamm der Daniten suchte sich damals gerade ein Gebiet zur Ansiedelung, denn es war ihm bis dahin inmitten der israelitischen Stämme noch kein Gebiet als Erbbesitz zugefallen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 18, 2, 'Daher schickten die Daniten fünf Männer aus der Gesamtheit ihrer Stammesgenossen ab, kriegstüchtige Männer aus Zora und Esthaol, um das Land auszukundschaften und zu erforschen, und gaben ihnen den Auftrag, sich zur Erforschung des Landes aufzumachen. So kamen diese denn auf das Gebirge Ephraim in den Wohnort Michas und übernachteten dort.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 18, 3, 'Als sie nun in der Nähe von Michas Hause waren und den jungen Mann, den Leviten, an seiner Sprache erkannten, kehrten sie dort ein und fragten ihn: »Wer hat dich hierher gebracht? Was tust du hier, und wie geht’s dir hier?«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 18, 4, 'Da antwortete er ihnen: »So und so hat Micha mit mir verhandelt und mich dann in seinen Dienst genommen, und ich bin sein Priester geworden.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 18, 5, 'Da baten sie ihn: »Befrage doch Gott, damit wir erfahren, ob das Unternehmen, für das wir jetzt unterwegs sind, glücklichen Erfolg haben wird.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 18, 6, 'Der Priester gab ihnen hierauf den Bescheid: »Zieht getrost hin: euer jetziges Unternehmen ist dem HERRN wohlgefällig!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 18, 7, 'Da zogen die fünf Männer weiter, gelangten nach Lais und sahen, daß die dortige Bevölkerung nach der Weise der Sidonier sorglos lebte, friedlich und in Sicherheit, und an nichts Mangel hatte, was es auf Erden gibt, vielmehr im Besitz von Reichtum war; daß sie auch von den Sidoniern entfernt wohnten und mit den Aramäern in keiner Verbindung standen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 18, 8, 'Als sie daher zu ihren Stammesgenossen nach Zora und Esthaol zurückgekehrt waren und diese sie fragten: »Welche Auskunft bringt ihr uns?«,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 18, 9, 'antworteten sie: »Auf! Laßt uns gegen sie zu Felde ziehen! Denn wir haben uns das Land angesehen und gefunden, daß es ganz vortrefflich ist. Und da sitzt ihr noch untätig da? Säumt nicht, euch aufzumachen und hinzuziehen, um das Land in Besitz zu nehmen!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 18, 10, 'Wenn ihr hinkommt, werdet ihr ein sorgloses Volk antreffen, dessen Land sich nach allen Seiten hin weit ausdehnt. Ja, Gott hat es in eure Hand gegeben, eine Gegend, die an nichts Mangel hat, was es auf Erden gibt.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 18, 11, 'Da brachen sechshundert wohlbewaffnete Männer von dort aus dem Stamme der Daniten, aus Zora und Esthaol, auf;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 18, 12, 'sie zogen hinauf und lagerten bei Kirjath-Jearim in Juda; daher führt der betreffende Platz den Namen ›Dans Lager‹ bis auf den heutigen Tag; er liegt bekanntlich westlich von Kirjath-Jearim.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 18, 13, 'Von dort zogen sie weiter in das Gebirge Ephraim und kamen in den Wohnort Michas.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 18, 14, 'Da machten die fünf Männer, die vordem zur Auskundschaftung des Gebietes der Stadt Lais ausgezogen waren, ihren Stammesgenossen die Mitteilung: »Wißt ihr wohl, daß sich in den Gehöften hier ein kostbares Priestergewand und ein Hausgott sowie ein geschnitztes und gegossenes Gottesbild befinden? Bedenkt also, was ihr zu tun habt!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 18, 15, 'Da bogen sie vom Wege dorthin ab, traten in die Wohnung des jungen Leviten, in das Haus Michas ein, und begrüßten ihn.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 18, 16, 'Während dann die sechshundert bewaffneten Männer, die zu den Daniten gehörten, draußen am Eingang des Tores blieben,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 18, 17, 'stiegen die fünf Männer, die vordem zur Auskundschaftung des Landes hergekommen waren, hinauf, gingen in das Haus hinein und nahmen das geschnitzte Bild sowie das Priestergewand, den Hausgott und das gegossene Bild an sich, während der Priester draußen am Toreingang bei den sechshundert bewaffneten Kriegern stand.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 18, 18, 'Als jene nämlich in das Haus Michas eingetreten waren und das Schnitzbild sowie das Priestergewand, den Hausgott und das Gußbild wegnahmen, sagte der Priester zu ihnen: »Was macht ihr da?«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 18, 19, 'Sie antworteten ihm: »Schweige still, lege dir die Hand auf den Mund, komm mit uns und werde unser Vater und Priester! Ist es besser für dich, Priester für das Haus eines einzelnen Mannes zu sein oder Priester für einen ganzen Stamm und für ein Geschlecht in Israel?«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 18, 20, 'Da erklärte sich der Priester mit Freuden einverstanden: er nahm das Priestergewand, den Hausgott und das geschnitzte Bild und trat mitten unter die Kriegsleute.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 18, 21, 'Darauf wandten sie sich zum Abzug, nachdem sie noch die Frauen mit den Kindern sowie das Herdenvieh und die wertvollen Gegenstände an ihre Spitze gestellt hatten.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 18, 22, 'Kaum hatten sie sich aber eine Strecke vom Hause Michas entfernt, als sich die Männer, die in den Gehöften beim Hause Michas wohnten, zusammenscharten und die Daniten einholten.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 18, 23, 'Als sie dann den Daniten zuriefen, wandten diese sich um und fragten Micha: »Was soll dieser Auflauf bedeuten?«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 18, 24, 'Er antwortete: »Meinen Gott, den ich mir gemacht habe, habt ihr mit euch genommen samt dem Priester und seid weggezogen: was bleibt mir da noch? Wie könnt ihr mich nur fragen, was ich hier will?«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 18, 25, 'Aber die Daniten erwiderten ihm: »Laß dein Geschrei uns hier nicht länger hören, sonst könnten erbitterte Männer über euch herfallen, und es könnte dich und deine Angehörigen das Leben kosten!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 18, 26, 'Darauf zogen die Daniten ihres Weges, und Micha, der wohl einsah, daß sie stärker waren als er, wandte sich um und kehrte nach Hause zurück.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 18, 27, 'Nachdem aber die Daniten das Gottesbild, das Micha sich angefertigt hatte, samt dem Priester, der bei ihm gewesen war, mitgenommen hatten, überfielen sie Lais, dessen Bevölkerung friedlich und sorglos war, machten alle Einwohner mit dem Schwert nieder und ließen die Stadt in Flammen aufgehen,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 18, 28, 'ohne daß ihr jemand zu Hilfe gekommen wäre; denn der Ort lag von Sidon weit entfernt und stand auch mit den Aramäern in keiner Verbindung; er lag nämlich in dem Tal, das sich nach Beth-Rehob hin erstreckt. Sie bauten dann die Stadt wieder auf und siedelten sich in ihr an,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 18, 29, 'nannten aber die Stadt ›Dan‹ nach dem Namen ihres Ahnherrn Dan, dem Sohne Israels, während der Ort früher Lais geheißen hatte.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 18, 30, 'Sodann stellten die Daniten das geschnitzte Gottesbild bei sich auf, und Jonathan, der Sohn Gersoms, des Sohnes Moses, er und seine Nachkommen, waren Priester bei dem Stamme der Daniten bis zu der Zeit, wo die Bevölkerung in die Verbannung ziehen mußte.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 18, 31, 'Das geschnitzte Bild aber, das Micha hatte anfertigen lassen, war bei ihnen aufgestellt die ganze Zeit hindurch, solange das Haus Gottes sich in Silo befand.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 19, 1, 'Zu jener Zeit, als es noch keinen König in Israel gab, begab es sich, daß ein Levit, der ganz hinten im Gebirge Ephraim als Fremdling wohnte, sich ein Mädchen aus Bethlehem in Juda zum Nebenweibe nahm.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 19, 2, 'Aber sein Nebenweib überwarf sich mit ihm, verließ ihn und kehrte in ihres Vaters Haus nach Bethlehem in Juda zurück; dort blieb sie vier Monate lang.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 19, 3, 'Da machte ihr Mann sich auf den Weg und zog ihr nach, um sie durch freundliches Zureden zur Rückkehr zu bewegen; seinen Diener und ein paar Esel hatte er bei sich. Sie führte ihn dann in das Haus ihres Vaters, und als dieser ihn sah, kam er ihm freundlich entgegen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 19, 4, 'Sein Schwiegervater, der Vater des jungen Weibes, hielt ihn dann zurück, so daß er drei Tage bei ihm blieb; sie aßen und tranken miteinander und übernachteten dort.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 19, 5, 'Am vierten Tage aber, als sie in der Frühe aufgestanden waren und er aufbrechen wollte, sagte der Vater des jungen Weibes zu seinem Schwiegersohn: »Stärke dich noch mit einem Imbiß, dann mögt ihr euch auf den Weg machen!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 19, 6, 'So setzten sie sich denn hin, und die beiden aßen und tranken zusammen; dann bat der Vater des jungen Weibes den Mann: »Entschließe dich doch, über Nacht noch hier zu bleiben, und sei guter Dinge!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 19, 7, 'Und als der Mann aufstand, um sich auf den Weg zu machen, nötigte ihn sein Schwiegervater, so daß er wiederum über Nacht dablieb.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 19, 8, 'Als er dann am fünften Tage frühmorgens aufbrechen wollte, sagte der Vater des jungen Weibes wiederum: »Stärke dich doch erst und wartet noch bis zum Nachmittag!«, und so aßen sie beide nochmals zusammen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 19, 9, 'Als dann der Mann aufstand, um mit seinem Nebenweibe und seinem Diener aufzubrechen, sagte sein Schwiegervater, der Vater des jungen Weibes, zu ihm: »Sieh doch, der Tag geht zu Ende, es will Abend werden: übernachtet doch hier! Sieh doch, wie der Tag schon zur Neige geht; bleibe über Nacht hier und laß dir’s bei mir gefallen! Morgen früh macht ihr euch dann auf euren Weg, und du kehrst nach Hause zurück.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 19, 10, 'Aber der Mann wollte nicht noch einmal über Nacht bleiben, sondern brach auf und zog fort und kam bis in die Gegend von Jebus, das ist Jerusalem; seine beiden gesattelten Esel, sein Nebenweib (und sein Diener) waren bei ihm.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 19, 11, 'Als sie nun bei Jebus waren und der Tag schon stark zu Ende ging, sagte der Diener zu seinem Herrn: »Komm, laß uns hier in der Jebusiterstadt einkehren und darin übernachten!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 19, 12, 'Aber sein Herr erwiderte ihm: »Nein, wir wollen in keiner Stadt von fremden Leuten einkehren, die nicht zu den Israeliten gehören, sondern wollen bis Gibea weiterziehen.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 19, 13, 'Weiter sagte er zu seinem Diener: »Komm, wir wollen eine von den Ortschaften dort zu erreichen suchen und in Gibea oder in Rama über Nacht bleiben!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 19, 14, 'Als sie nun eiligst weiterzogen, ging die Sonne ihnen unter, als sie nahe bei Gibea waren, das zu Benjamin gehört.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 19, 15, 'Da kehrten sie dort ein, um zu einem Nachtquartier in Gibea zu gelangen, und er machte nach seiner Ankunft auf dem Marktplatz der Stadt halt; aber da war niemand, der sie zum Übernachten ins Haus aufgenommen hätte.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 19, 16, 'Endlich kam ein alter Mann abends vom Felde von seiner Arbeit heim; der stammte vom Gebirge Ephraim und lebte als Fremdling in Gibea, während die Bewohner des Ortes Benjaminiten waren.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 19, 17, 'Als dieser nun sich umsah und den Wandersmann auf dem Marktplatz der Stadt erblickte, fragte er: »Wohin willst du, und woher kommst du?«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 19, 18, 'Der antwortete ihm: »Wir sind auf der Wanderung von Bethlehem in Juda nach dem äußersten Teil des Gebirges Ephraim, wo ich zu Hause bin. Ich war nach Bethlehem in Juda gereist und will jetzt nach meinem Wohnort zurückkehren; aber niemand nimmt mich in sein Haus auf,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 19, 19, 'obgleich wir sowohl Stroh als auch Futter für unsere Esel und auch Brot und Wein für mich und deine Magd und für den Burschen, der hier bei uns, deinen Knechten, ist, bei uns haben und nichts weiter bedürfen.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 19, 20, 'Da sagte der alte Mann: »Friede dir! Nur, was du bedarfst, laß meine Sorge sein! Doch auf dem Platz hier sollst du nicht übernachten!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 19, 21, 'Dann nahm er ihn in sein Haus mit und mengte Futter für die Esel; und als sie sich die Füße gewaschen hatten, aßen und tranken sie.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 19, 22, 'Während sie so sich gütlich taten, umringten die Männer der Stadt, nichtsnutzige Buben, das Haus, schlugen laut an die Tür und riefen dem alten Manne, dem das Haus gehörte, die Worte zu: »Gib den Mann heraus, der bei dir eingekehrt ist: wir wollen uns an ihn machen!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 19, 23, 'Da ging der Besitzer des Hauses zu ihnen hinaus und sagte zu ihnen: »Nicht doch, meine Brüder! Begeht doch nichts so Böses! Nachdem dieser Mann in mein Haus gekommen ist, dürft ihr eine solche Schandtat nimmermehr verüben.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 19, 24, 'Da ist meine Tochter, die Jungfrau, und das Nebenweib dieses Mannes: die will ich euch herausbringen; denen mögt ihr Gewalt antun und mit ihnen machen, was euch gefällt, aber an diesem Manne dürft ihr eine solche Schandtat nicht verüben!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 19, 25, 'Aber die Männer wollten nicht auf ihn hören. Da nahm der Mann sein Nebenweib und führte sie zu ihnen hinaus auf die Straße, und sie mißbrauchten sie und taten ihr Gewalt an die ganze Nacht hindurch bis zum Morgen; erst bei Tagesanbruch ließen sie sie gehen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 19, 26, 'Als nun der Morgen tagte, kam das Weib heim und fiel am Toreingang zum Hause des Mannes, woselbst ihr Herr war, nieder und blieb da liegen, bis es hell wurde.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 19, 27, 'Als nun ihr Herr am Morgen aufstand und die Haustür öffnete und hinaustrat, um seines Weges weiter zu ziehen, fand er das Weib, sein Nebenweib, am Toreingang zum Hause liegen mit den Händen auf der Schwelle.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 19, 28, 'Er rief ihr zu: »Stehe auf, wir wollen weiterziehen!«, aber es erfolgte keine Antwort. Da hob er sie auf den Esel, machte sich dann auf und zog nach seinem Wohnort.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 19, 29, 'Als er dort in sein Haus gekommen war, nahm er ein Messer, ergriff sein Nebenweib, zerschnitt sie Glied für Glied in zwölf Stücke und schickte diese im ganzen Gebiet Israels umher.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 19, 30, 'Da erklärte denn jeder, der das sah: »So etwas ist bisher noch nicht vorgekommen und noch nicht erlebt worden seit der Zeit, wo die Israeliten aus dem Lande Ägypten heraufgezogen sind, bis zum heutigen Tage. Nehmt es zu Herzen, beratet euch und redet!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 1, 'Da zogen alle Israeliten aus, und die Volksgemeinde versammelte sich wie ein Mann von Dan bis Beerseba, auch das Land Gilead, vor dem HERRN in Mizpa;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 2, 'und die Häupter des ganzen Volkes, der sämtlichen Stämme Israels, stellten sich in der Versammlung des Volkes Gottes ein, 400000 Mann Fußvolk, mit Schwertern bewaffnet.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 3, 'Und die Benjaminiten hörten, daß die Israeliten nach Mizpa hinaufgezogen seien. Nun fragten die Israeliten: »Sagt an, wie diese Untat vor sich gegangen ist.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 4, 'Da nahm der Levit, der Mann des ermordeten Weibes, das Wort und berichtete: »Ich war mit meinem Nebenweibe nach Gibea im Stamme Benjamin gekommen, um dort zu übernachten.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 5, 'Da erhoben sich die Bürger von Gibea gegen mich und umringten nachts das Haus in feindseliger Absicht gegen mich: mich gedachten sie umzubringen, meinem Nebenweibe aber haben sie Gewalt angetan, so daß sie gestorben ist.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 6, 'Da habe ich mein Nebenweib genommen, habe sie zerstückt und die Stücke in alle Teile des israelitischen Erbbesitzes gesandt; denn man hat ein Verbrechen und eine ruchlose Tat in Israel verübt.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 7, 'Ihr seid jetzt hier alle versammelt, ihr Israeliten: so beratet denn allhier die Sache und faßt einen Beschluß!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 8, 'Da erhob sich das ganze Volk wie ein Mann und rief: »Keiner von uns darf in seinen Wohnort zurückkehren und keiner sich nach seinem Hause begeben!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 9, 'Nein, so wollen wir jetzt mit Gibea verfahren: Wir wollen gegen die Stadt nach dem Lose vorgehen!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 10, 'und zwar wollen wir von allen Stämmen Israels je zehn Männer von hundert und je hundert von tausend und je tausend von zehntausend nehmen, die sollen Lebensmittel für das Kriegsvolk holen, damit wir dann nach ihrer Rückkehr mit Gibea im Stamme Benjamin ganz so verfahren, wie die Schandtat es verdient, die es in Israel verübt hat.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 11, 'So versammelte sich denn die gesamte Mannschaft der Israeliten gegen die Stadt, wie ein Mann verbündet.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 12, 'Hierauf sandten die israelitischen Stämme Männer durch den ganzen Stamm Benjamin mit der Botschaft: »Was ist das für eine Untat, die bei euch verübt worden ist!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 13, 'So gebt nun jetzt die Männer, die ruchlosen Buben, die sich in Gibea befinden, heraus, damit wir sie töten und das Böse aus Israel wegschaffen!« Aber die Benjaminiten wollten der Forderung ihrer Brüder, der Israeliten, nicht nachkommen,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 14, 'sie versammelten sich vielmehr aus ihren Ortschaften in Gibea, um zum Kampf mit den Israeliten auszurücken.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 15, 'Als man damals die Benjaminiten aus den Ortschaften musterte, belief sich ihre Zahl auf 26000 schwertbewaffnete Männer, abgesehen von den Bewohnern Gibeas selbst, die bei der Musterung 700 auserlesene Krieger stellten.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 16, 'Unter all diesen Leuten waren 700 auserlesene Männer linkshändig: ein jeder von ihnen schleuderte mit Steinen haarscharf, ohne zu fehlen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 17, 'Als man dann auch die Mannschaft der Israeliten außer dem Stamme Benjamin musterte, ergab sich bei ihnen die Zahl von 400000 schwertbewaffneten Männern, lauter kampffähige Krieger.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 18, 'Hierauf machten die Israeliten sich auf den Weg und zogen nach Bethel hinauf, um Gott zu befragen, wer von ihnen zuerst zum Kampf mit den Benjaminiten ausziehen solle. Der HERR antwortete ihnen: »Juda soll den Anfang machen!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 19, 'So brachen denn die Israeliten am folgenden Morgen früh auf und lagerten sich vor Gibea;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 20, 'dann zogen die Männer von Israel zum Kampf mit den Benjaminiten aus und stellten sich gegen sie in Schlachtordnung vor Gibea auf.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 21, 'Die Benjaminiten aber brachen aus Gibea hervor und streckten an diesem Tage 22000 Mann von Israel zu Boden.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 22, 'Doch das Kriegsvolk, die israelitische Mannschaft, ließ sich dadurch nicht entmutigen, sondern stellte sich noch einmal in Schlachtordnung auf an derselben Stelle, wo sie sich am ersten Tage aufgestellt hatten.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 23, 'Zuvor aber zogen die Israeliten (nach Bethel) hinauf und weinten vor dem HERRN bis zum Abend und befragten dann den HERRN, ob sie noch einmal zum Kampfe mit ihren Brüdern, den Benjaminiten, ausrücken sollten. Der HERR gab ihnen die Antwort: »Zieht gegen sie aus!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 24, 'Als nun die Israeliten an diesem zweiten Tage wieder gegen die Benjaminiten anrückten,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 25, 'zogen diese ihnen auch an diesem zweiten Tage aus Gibea entgegen und streckten von den Israeliten abermals 18000 Mann zu Boden, lauter Männer, die das Schwert führten.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 26, 'Da zogen die Israeliten allesamt, das ganze Kriegsvolk, nach Bethel hinauf, weinten dort ununterbrochen vor dem HERRN, fasteten während jenes Tages bis zum Abend und brachten Brand- und Heilsopfer vor dem HERRN dar.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 27, 'Als die Israeliten dann den HERRN befragten – dort befand sich nämlich zu jener Zeit die Bundeslade Gottes,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 28, 'und Pinehas, der Sohn Eleasars, des Sohnes Aarons, versah damals den Dienst vor ihm – und die Anfrage stellten: »Soll ich noch einmal zum Kampf gegen meine Brüder, die Benjaminiten, ausziehen oder davon abstehen?«, gab der HERR die Antwort: »Zieht hin, denn morgen will ich sie in eure Gewalt geben!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 29, 'Darauf legte Israel ringsum gegen Gibea Leute in den Hinterhalt.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 30, 'Als dann die Israeliten am dritten Tage wieder gegen die Benjaminiten heranzogen und sich wie die beiden vorigen Male in Schlachtordnung vor Gibea aufstellten,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 31, 'rückten die Benjaminiten heraus dem (feindlichen) Heere entgegen, ließen sich von der Stadt weglocken und begannen, wie die beiden vorigen Male, einige von dem Heere zu erschlagen auf den Landstraßen – von denen die eine nach Bethel hinaufgeht, die andere durch die Felder nach Gibeon führt –, etwa dreißig Mann von den Israeliten.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 32, 'Da dachten die Benjaminiten: »Sie sind von uns geschlagen wie früher«; die Israeliten dagegen hatten verabredet: »Wir wollen fliehen, um sie noch weiter von der Stadt wegzulocken nach den Landstraßen hin!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 33, 'Daher verließen sie, die gesamte Mannschaft der Israeliten, ihren Standort und stellten sich erst wieder bei Baal-Thamar auf, während die im Hinterhalt liegenden Israeliten aus ihrem Standort westlich von Gibea hervorbrachen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 34, 'So rückten denn 10000 Mann, eine aus ganz Israel erlesene Mannschaft, gegen Gibea heran, und ein wütender Kampf entstand; jene aber hatten keine Ahnung davon, daß das Verderben daran war, über sie hereinzubrechen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 35, 'Da ließ der HERR den Stamm Benjamin von Israel besiegt werden, so daß die Israeliten von den Benjaminiten 25100 Mann an diesem Tage niedermachten, lauter Männer, die das Schwert führten.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 36, 'Da sahen die Benjaminiten, daß sie geschlagen waren; die Israeliten hatten sich nämlich vor den Benjaminiten zurückgezogen, weil sie sich auf den Hinterhalt verließen, den sie gegen Gibea gelegt hatten.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 37, 'Die im Hinterhalt Liegenden warfen sich dann auch eiligst auf Gibea, drangen in die Stadt ein und machten die ganze Bevölkerung mit dem Schwerte nieder.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 38, 'Die Israeliten hatten aber mit den im Hinterhalt Liegenden verabredet, daß sie eine große Rauchwolke aus der Stadt aufsteigen lassen sollten.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 39, 'Als sich nun das israelitische Heer in der Schlacht zur Flucht gewandt und die Benjaminiten schon angefangen hatten, unter den Israeliten einige, etwa dreißig Mann, zu erschlagen, weil sie dachten, jene seien völlig von ihnen geschlagen wie beim früheren Kampf –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 40, 'da begann das verabredete Zeichen aus der Stadt aufzusteigen, die Rauchsäule; und als die Benjaminiten sich umwandten, sahen sie die Flammen der ganzen Stadt zum Himmel aufsteigen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 41, 'Nun machte das israelitische Heer kehrt, die Benjaminiten aber gerieten in Bestürzung, denn sie erkannten, daß das Unheil sie erreicht hatte.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 42, 'Sie zogen sich dann vor den Israeliten in der Richtung nach der Steppe hin zurück; aber das feindliche Heer folgte ihnen auf dem Fuße nach, und die aus der Stadt Kommenden vernichteten sie in ihrer Mitte.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 43, 'Sie umzingelten die Benjaminiten, verfolgten sie, holten sie ein, wo sie ausruhen wollten, bis in die Gegend östlich von Gibea;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 44, 'dabei fielen von den Benjaminiten 18000 Mann, lauter tapfere Krieger.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 45, 'Die anderen wandten sich zur Flucht gegen die Wüste, nach dem Felsen Rimmon hin, jene aber erschlugen von ihnen auf den Landstraßen nachträglich noch 5000 Mann und verfolgten sie weiter bis Gideom und machten von ihnen noch 2000 Mann nieder.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 46, 'So betrug die Gesamtzahl der an jenem Tage gefallenen Benjaminiten 25000 Mann, lauter schwertbewaffnete, tapfere Krieger.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 47, '600 Mann aber, die sich zur Flucht gewandt hatten, waren in die Wüste nach dem Felsen Rimmon entkommen und blieben dort am Felsen Rimmon vier Monate lang.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 48, 'Die israelitische Mannschaft aber kehrte ins Land der noch übrigen Benjaminiten zurück und machte mit dem Schwert alles nieder, was sich vorfand, die Menschen in den Ortschaften bis zum Vieh; auch alle Ortschaften, die sich da vorfanden, steckten sie in Brand.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 21, 1, 'Die Männer von Israel hatten aber in Mizpa folgenden feierlichen Schwur abgelegt: »Keiner von uns darf seine Tochter einem Benjaminiten zur Frau geben!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 21, 2, 'Als nun das Volk nach Bethel gezogen war und dort bis zum Abend vor Gott (beim Heiligtum) verweilte, fingen sie an, laut zu weinen,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 21, 3, 'und wehklagten: »Warum, o HERR, Gott Israels, ist dies in Israel geschehen, daß heute ein ganzer Stamm aus Israel fehlt!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 21, 4, 'Am folgenden Tage aber in der Frühe baute das Volk dort einen Altar und brachte Brand- und Heilsopfer dar.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 21, 5, 'Dann fragten die Israeliten: »Wer von allen Stämmen Israels ist nicht mit der Gemeinde zum HERRN hergekommen?« Man hatte nämlich in betreff eines jeden, der nicht zum HERRN nach Mizpa hinkommen würde, einen feierlichen Eid ausgesprochen des Inhalts: »Er muß unbedingt sterben.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 21, 6, 'Nun tat es aber den Israeliten um ihren Bruderstamm Benjamin leid, so daß sie klagten: »Heute ist ein ganzer Stamm von Israel abgehauen!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 21, 7, 'Wie können wir nun den Übriggebliebenen zu Frauen verhelfen, da wir doch beim HERRN geschworen haben, daß wir ihnen keine von unsern Töchtern zu Frauen geben wollen?«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 21, 8, 'Da fragten sie: »Ist etwa einer von den Stämmen Israels nicht zum HERRN nach Mizpa hinaufgekommen?« Da ergab es sich, daß aus Jabes in Gilead niemand ins Lager zur Versammlung gekommen war.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 21, 9, 'Man hatte nämlich das Volk gemustert, und da stellte es sich heraus, daß von den Einwohnern von Jabes in Gilead keiner anwesend war.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 21, 10, 'Nun sandte die Volksgemeinde 12000 Mann von den tapfersten Männern dorthin mit dem Befehl: »Geht hin und erschlagt die Einwohner von Jabes in Gilead mit dem Schwerte, auch die Weiber und die Kinder!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 21, 11, 'Verfahrt dabei aber so: an allen Männern sowie an allen weiblichen Personen, die schon mit Männern zu tun gehabt haben, sollt ihr den Blutbann vollstrecken (die Jungfrauen aber am Leben lassen und sie hierher ins Lager bringen)!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 21, 12, 'Sie fanden aber unter den Bewohnern von Jabes in Gilead vierhundert jungfräuliche Mädchen, die noch mit keinem Mann zu tun gehabt hatten; die brachten sie ins Lager nach Silo, das im Lande Kanaan liegt.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 21, 13, 'Hierauf sandte die ganze Volksgemeinde hin und verhandelte mit den Benjaminiten, die sich noch am Felsen Rimmon befanden, und ließ ihnen Sicherheit entbieten.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 21, 14, 'So kehrten denn die Benjaminiten damals zurück, und man gab ihnen die Mädchen, die man von den weiblichen Personen aus Jabes in Gilead am Leben gelassen hatte, zu Frauen; diese reichten jedoch für sie nicht aus.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 21, 15, 'Weil nun die Benjaminiten dem Volke leid taten, da der HERR einen Riß in den Stämmen Israels hatte entstehen lassen,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 21, 16, 'sagten die Ältesten der Gemeinde: »Wie können wir den Übriggebliebenen zu Frauen verhelfen, da ja die Frauen aus Benjamin ausgerottet sind?«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 21, 17, 'Da sagten sie: »Der Erbbesitz soll den Benjaminiten verbleiben, die mit dem Leben davongekommen sind, damit nicht ein Stamm aus Israel ausgetilgt wird.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 21, 18, 'Wir aber können ihnen keine von unsern Töchtern zu Frauen geben, denn die Israeliten haben feierlich geschworen: ›Verflucht sei, wer seine Tochter einem Benjaminiten zur Frau gibt!‹«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 21, 19, 'Da sagten sie: »Es findet bekanntlich alle Jahre ein Fest des HERRN in Silo statt (auf dem Platze) nördlich von Bethel, östlich von der Landstraße, die von Bethel nach Sichem hinaufführt, und südlich von Lebona.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 21, 20, 'Da gaben sie den Benjaminiten folgende Weisung: »Geht hin und versteckt euch in den Weinbergen!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 21, 21, 'Wenn ihr dann die Mädchen von Silo herauskommen seht, um Reigentänze aufzuführen, so brecht aus den Weinbergen hervor und erhascht euch ein jeder sein Weib aus den Mädchen von Silo und kehrt mit ihr ins Land Benjamin zurück.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 21, 22, 'Wenn dann ihre Väter oder Brüder kommen, um sich bei uns (über euch) zu beschweren, so wollen wir zu ihnen sagen: ›Vergönnt sie ihnen um unsertwillen! [Denn wir haben durch den Krieg (gegen Jabes) nicht für jeden eine Frau gewonnen.] Nicht ihr habt sie ihnen ja gegeben; denn in diesem Fall würdet ihr als schuldig dastehen.‹«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 21, 23, 'Die Benjaminiten befolgten die Weisung: sie holten sich die erforderliche Zahl von Frauen aus den tanzenden Mädchen, die sie raubten, kehrten dann in ihren Erbbesitz zurück, bauten die Ortschaften wieder auf und ließen sich darin nieder.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 21, 24, 'Nunmehr zogen auch die Israeliten von dort heim, ein jeder in seinen Stamm und zu seinem Geschlecht, und begaben sich von dort weg, ein jeder in seinen Erbbesitz.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 21, 25, 'Zu jener Zeit gab es noch keinen König in Israel; jeder tat, was ihm gut dünkte.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 1, 1, 'Zu der Zeit, als die Richter (in Israel) walteten, kam einmal eine Hungersnot über das Land. Da wanderte ein Mann aus Bethlehem in Juda mit seiner Frau und seinen beiden Söhnen aus, um eine Zeitlang im Gebiet der Moabiter als Fremdling zu leben.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 1, 2, 'Der Mann hieß Elimelech, seine Frau Noomi; und seine beiden Söhne hießen Machlon und Kiljon; sie waren Ephrathiter aus Bethlehem in Juda. Sie kamen auch glücklich im Gebiet der Moabiter an und blieben dort.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 1, 3, 'Da starb Elimelech, der Mann Noomis, so daß sie mit ihren beiden Söhnen allein zurückblieb.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 1, 4, 'Diese nahmen sich dann moabitische Frauen, von denen die eine Orpa, die andere Ruth hieß. So wohnten sie dort etwa zehn Jahre.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 1, 5, 'Als dann auch die beiden Söhne, Machlon und Kiljon, starben und die Frau, ihrer beiden Söhne und ihres Mannes beraubt, allein stand,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 1, 6, 'machte sie sich mit ihren beiden Schwiegertöchtern auf, um aus dem Gebiet der Moabiter in ihre Heimat zurückzukehren; denn sie hatte im Lande der Moabiter in Erfahrung gebracht, daß der HERR sich seines Volkes gnädig angenommen und ihm wieder Brot gegeben habe.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 1, 7, 'Sie verließ also in Begleitung ihrer beiden Schwiegertöchter den Ort, wo sie bis dahin gewohnt hatte. Als sie aber ihres Weges zogen, um ins Land Juda zurückzukehren,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 1, 8, 'sagte Noomi zu ihren beiden Schwiegertöchtern: »Kehrt jetzt wieder heim, eine jede ins Haus ihrer Mutter. Der HERR segne euch für die Liebe, die ihr den Verstorbenen und mir erwiesen habt!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 1, 9, 'Der HERR vergönne euch beiden, ein ruhiges Heim im Hause eines Gatten zu finden!« Als Noomi sie hierauf geküßt hatte, begannen jene laut zu weinen');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 1, 10, 'und sagten zu ihr: »Nein, wir wollen dich zu deinem Volke begleiten!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 1, 11, 'Aber Noomi entgegnete: »Kehrt um, liebe Töchter! Warum wollt ihr mit mir gehen? Darf ich etwa noch hoffen, Söhnen das Leben zu geben, daß sie eure Männer werden könnten?');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 1, 12, 'Nein, kehrt um, liebe Töchter! Geht heim! Ich bin ja zu alt, um mich nochmals zu verheiraten. Und wenn ich auch dächte, noch Aussicht auf eine neue Ehe zu haben, ja wenn ich noch in dieser Nacht das Weib eines Mannes und sogar Mutter von Söhnen würde:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 1, 13, 'wolltet ihr deshalb warten, bis sie erwachsen wären? Wolltet ihr euch deshalb bis dahin einschließen und unverheiratet bleiben? Nein, liebe Töchter! Ich bin ja euretwegen tief betrübt, daß die Hand des HERRN mich so schwer getroffen hat!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 1, 14, 'Da begannen sie von neuem laut zu weinen; dann küßte aber Orpa ihre Schwiegermutter und ging weg, Ruth aber schloß sie fest in ihre Arme.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 1, 15, 'Da sagte Noomi zu ihr: »Nachdem nun deine Schwägerin zu ihrem Volk und zu ihrem Gott zurückgekehrt ist, so kehre auch du um und folge deiner Schwägerin!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 1, 16, 'Aber Ruth erwiderte: »Dringe nicht in mich, dich zu verlassen und ohne dich umzukehren; Nein, wohin du gehst, dahin will auch ich gehen, und wo du bleibst, da bleibe ich auch: dein Volk ist mein Volk, und dein Gott ist mein Gott!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 1, 17, 'Wo du stirbst, da sterbe ich auch, und da will ich begraben sein. Der HERR mache mit mir, was er will: nur der Tod soll mich von dir scheiden!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 1, 18, 'Als Noomi nun sah, daß Ruth fest entschlossen war, mit ihr zu gehen, redete sie nicht weiter auf sie ein.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 1, 19, 'So gingen denn die beiden weiter, bis sie nach Bethlehem gelangten. Als sie aber dort ankamen, geriet der ganze Ort ihretwegen in Aufregung, und alle Frauen sagten: »Ist das nicht Noomi?«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 1, 20, 'Da antwortete sie ihnen: »Nennt mich nicht Noomi, nennt mich lieber Mara; denn der Allmächtige hat mich viel Bitteres erleben lassen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 1, 21, 'Voll bin ich weggegangen, und leer hat mich der HERR zurückkehren lassen. Warum nennt ihr mich Noomi? Hat sich doch der HERR selbst gegen mich erklärt und der Allmächtige mich in Leid gestürzt!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 1, 22, 'So kehrte Noomi und mit ihr Ruth, ihre Schwiegertochter, die Moabitin, aus dem Lande der Moabiter heim, und zwar kamen sie in Bethlehem an beim Beginn der Gerstenernte.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 2, 1, 'Nun besaß Noomi einen Verwandten von seiten ihres Mannes, einen sehr wohlhabenden Mann aus der Familie Elimelechs, namens Boas.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 2, 2, 'Als nun die Moabitin Ruth zu Noomi sagte: »Ich will doch aufs Feld gehen und Ähren lesen hinter einem her, der es mir erlauben wird«, erwiderte diese ihr: »Geh nur, meine Tochter!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 2, 3, 'So ging sie denn hin und las auf dem Felde hinter den Schnittern her auf, und der Zufall wollte es, daß das Grundstück dem Boas gehörte, der aus der Familie Elimelechs stammte.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 2, 4, 'Da kam Boas gerade aus Bethlehem und sagte zu den Schnittern: »Der HERR sei mit euch!«; sie antworteten ihm: »Der HERR segne dich!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 2, 5, 'Darauf fragte Boas den Großknecht bei seinen Schnittern: »Wem gehört das Mädchen da?«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 2, 6, 'Der Großknecht antwortete: »Es ist das moabitische Mädchen, das mit Noomi aus dem Lande der Moabiter heimgekehrt ist.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 2, 7, 'Sie hat uns gebeten: ›Laßt mich doch Ähren lesen und zwischen den Garben sammeln hinter den Schnittern her!‹ So ist sie denn gekommen und hat ausgehalten vom frühen Morgen an bis jetzt und sich keinen Augenblick Ruhe gegönnt.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 2, 8, 'Da sagte Boas zu Ruth: »Hörst du wohl, meine Tochter? Du brauchst auf kein anderes Feld zu gehen, um dort aufzulesen, und brauchst auch nicht von hier wegzugehen, sondern schließe dich hier an meine Mägde an!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 2, 9, 'Laß deine Augen immer auf das Feld gerichtet sein, wo sie schneiden, und gehe hinter ihnen her; ich habe auch den Knechten befohlen, dich nicht zu belästigen. Und wenn du Durst hast, so gehe nur zu den Gefäßen und trinke von dem Wasser, das die Knechte geholt haben!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 2, 10, 'Da warf sie sich mit dem Angesicht vor ihm auf die Erde nieder und sagte zu ihm: »Wie kommt’s doch, daß du so freundlich gegen mich bist und dich meiner annimmst, da ich doch eine Ausländerin bin?«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 2, 11, 'Boas antwortete ihr: »O es ist mir alles genau berichtet worden, was du an deiner Schwiegermutter nach dem Tode deines Mannes getan hast: Vater, Mutter und Heimatland hast du verlassen und bist zu einem Volk gezogen, das du früher nicht kanntest.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 2, 12, 'Der HERR vergelte dir dein Tun, und voller Lohn möge dir zuteil werden vom HERRN, dem Gott Israels, unter dessen Flügeln du Schutz zu suchen hergekommen bist!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 2, 13, 'Da antwortete sie: »Ich danke dir für deine Freundlichkeit, mein Herr! Denn du hast mich getröstet und deiner Magd mit Herzlichkeit zugesprochen, obgleich ich nicht einmal wie eine von deinen Mägden bin.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 2, 14, 'Zur Essenszeit sagte dann Boas zu ihr: »Komm hierher und iß mit von dem Brot und tunke deinen Bissen in den Essig!« Als sie sich nun neben die Schnitter gesetzt hatte, reichte er ihr geröstete Körner, und sie aß, bis sie satt war, und behielt noch einen Teil übrig.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 2, 15, 'Als sie dann aufstand, um wieder zu lesen, gab Boas seinen Knechten den Befehl: »Sie darf auch zwischen den Garben lesen, und ihr sollt ihr nichts zuleide tun!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 2, 16, 'Zieht vielmehr hin und wieder Halme für sie aus den Bündeln heraus und laßt sie liegen; sie mag sie dann auflesen, ohne daß ihr sie scheltet!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 2, 17, 'So las sie denn auf dem Felde bis zum Abend, und als sie dann das ausklopfte, was sie gesammelt hatte, war es beinahe ein Epha Gerste.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 2, 18, 'Sie hob es auf, ging in die Stadt und zeigte ihrer Schwiegermutter, was sie gelesen hatte; dann holte sie auch noch das hervor, was sie vom Essen übrigbehalten hatte, und gab es ihr.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 2, 19, 'Da sagte ihre Schwiegermutter zu ihr: »Wo hast du heute so fleißig gelesen? Gesegnet sei, der sich deiner so freundlich angenommen hat!« Nun erzählte sie ihrer Schwiegermutter, auf wessen Felde sie bei der Arbeit gewesen war, und sagte: »Der Mann, auf dessen Felde ich heute bei der Arbeit gewesen bin, heißt Boas.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 2, 20, 'Da erwiderte Noomi ihrer Schwiegertochter: »Gesegnet sei er vom HERRN, der seine Güte weder den noch Lebenden noch den schon Toten entzogen hat!« Dann fuhr Noomi fort: »Der Mann ist mit uns nahe verwandt; er ist einer von unsern Lösern.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 2, 21, 'Darauf sagte die Moabitin Ruth: »Er hat auch zu mir gesagt: ›Halte dich nur zu meinen Leuten, bis sie mit meiner ganzen Ernte fertig sind!‹«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 2, 22, 'Da antwortete Noomi ihrer Schwiegertochter Ruth: »Es ist gut, liebe Tochter, wenn du mit seinen Mägden hinausgehst: so kann man dir auf einem andern Felde nichts zuleide tun.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 2, 23, 'So hielt sie sich denn beim Ährenlesen zu den Mägden des Boas, bis die Gersten- und Weizenernte zu Ende war; dann blieb sie bei ihrer Schwiegermutter zu Hause.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 3, 1, 'Da sagte ihre Schwiegermutter Noomi zu ihr: »Liebe Tochter, ich muß dir doch ein sicheres Heim verschaffen, damit du gut versorgt bist.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 3, 2, 'Nun denn, Boas, dessen Mägden du dich angeschlossen hast, gehört zu unserer Verwandtschaft; der worfelt gerade diese Nacht die Gerste auf der Tenne.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 3, 3, 'So bade und salbe dich denn, lege deine besten Kleider an und gehe zur Tenne hinab, laß dich aber von dem Manne nicht eher bemerken, als bis er mit Essen und Trinken fertig ist.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 3, 4, 'Wenn er sich dann schlafen legt, so achte auf den Ort, wohin er sich legt; dann gehe hin, hebe die Decke zu seinen Füßen auf und lege dich dort nieder; er wird dir dann schon sagen, was du zu tun hast.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 3, 5, 'Sie antwortete ihr: »Ganz nach deiner Weisung will ich tun!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 3, 6, 'Sie ging also zur Tenne hinab und machte es genau so, wie ihre Schwiegermutter ihr angegeben hatte.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 3, 7, 'Als Boas nämlich gegessen und getrunken hatte und guter Dinge geworden war, legte er sich am Ende des Getreidehaufens schlafen; da kam sie leise heran, deckte den Platz zu seinen Füßen auf und legte sich dort nieder.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 3, 8, 'Da, um Mitternacht, fuhr der Mann aus dem Schlafe auf, und als er sich vorbeugte, sah er ein Weib zu seinen Füßen liegen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 3, 9, 'Als er nun fragte: »Wer bist du?«, antwortete sie: »Ich bin Ruth, deine Magd; breite also deinen Fittich über deine Magd aus; denn du bist Löser für mich!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 3, 10, 'Da erwiderte er: »Gesegnet seist du vom HERRN, meine Tochter! Du hast deine Liebe (zu Noomi) zuletzt noch schöner betätigt als früher, indem du nicht den jungen Männern nachgelaufen bist, sie seien arm oder reich.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 3, 11, 'Und nun, meine Tochter, sei ohne Angst! Alles, was du wünschest, will ich für dich tun; wissen doch alle Leute, die in unserm Ort auf dem Marktplatze am Stadttor zusammenkommen, daß du ein sittsames Weib bist.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 3, 12, 'Nun bin ich ja allerdings ein Löser für dich; aber es ist noch ein anderer Löser vorhanden, der näher mit dir verwandt ist als ich.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 3, 13, 'Bleibe über Nacht hier; morgen wird sich’s dann finden: wenn er dich lösen will, gut, so mag er es tun! Hat er aber keine Lust dazu, so will ich dich lösen, so wahr der HERR lebt! Bleibe nur liegen bis zum Morgen!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 3, 14, 'So blieb sie denn zu seinen Füßen liegen bis zum Morgen; dann stand sie auf, ehe noch ein Mensch den andern erkennen konnte; er dachte nämlich: »Es braucht nicht bekanntzuwerden, daß ein Weib auf die Tenne gekommen ist.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 3, 15, 'Dann sagte er: »Nimm den Überwurf, den du anhast, und halte ihn fest.« Als sie ihn nun hinhielt, maß er ihr sechs Maß Gerste ab und lud sie ihr auf. So ging sie in die Stadt.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 3, 16, 'Als sie nun zu ihrer Schwiegermutter heimkam, fragte diese: »Wie ist es dir ergangen, liebe Tochter?« Da erzählte sie ihr alles, wie der Mann sich gegen sie verhalten hatte,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 3, 17, 'und schloß mit den Worten: »Diese sechs Maß Gerste hat er mir gegeben; denn er sagte: ›Du sollst nicht mit leeren Händen zu deiner Schwiegermutter zurückkommen.‹«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 3, 18, 'Da sagte diese: »Warte nur ruhig ab, liebe Tochter, bis du erfährst, wie die Sache abläuft! Denn der Mann wird nicht ruhen, bis er die Sache heute noch zur Entscheidung gebracht hat.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 4, 1, 'Boas aber war zum Stadttor hinaufgegangen und hatte sich dort niedergesetzt. Als nun gerade der Löser vorüberging, von dem Boas geredet hatte, rief er: »Komm her und setze dich hierher, du Soundso!« Als er nun gekommen war und sich gesetzt hatte,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 4, 2, 'holte (Boas) zehn Männer von den Ältesten der Stadt und sagte zu ihnen: »Setzt euch hier nieder!« Als sie sich gesetzt hatten,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 4, 3, 'sagte er zu dem Löser: »Das Stück Land, das unserm Verwandten Elimelech gehört hat, will Noomi verkaufen, die aus dem Lande der Moabiter zurückgekehrt ist.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 4, 4, 'Nun habe ich gedacht, ich wollte dir einen Vorschlag machen, nämlich: Kaufe es in Gegenwart der hier Sitzenden und in Gegenwart der Ältesten meines Volkes! Willst du Löser sein, so sei Löser; wo nicht, so gib mir eine Erklärung ab, damit ich Bescheid weiß; denn außer dir ist kein Löser da, und ich komme erst nach dir.« Da erklärte jener: »Ja, ich will Löser sein.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 4, 5, 'Da fuhr Boas fort: »Sobald du das Stück Land von Noomi erwirbst, hast du auch die Moabitin Ruth, die Witwe des Verstorbenen, erkauft, um das Geschlecht des Verstorbenen auf seinem Erbbesitz fortzupflanzen.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 4, 6, 'Da antwortete der Löser: »In diesem Falle kann ich es nicht für mich einlösen; ich würde sonst mein eigenes Besitztum schädigen; löse du für dich, was ich lösen sollte, denn ich kann nicht Löser sein!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 4, 7, 'Nun bestand ehemals in Israel beim Lösen wie beim Tauschen der Brauch, daß, wenn man irgendeinen Handel fest abmachen wollte, der eine seinen Schuh auszog und ihn dem andern gab; dies galt als Beglaubigung in Israel.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 4, 8, 'Als daher der Löser zu Boas gesagt hatte: »Kaufe du es für dich!«, zog er seinen Schuh aus.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 4, 9, 'Darauf sagte Boas zu den Ältesten und zu allen anwesenden Leuten: »Ihr seid heute Zeugen, daß ich alles, was dem Elimelech, und alles, was dem Kiljon und Machlon gehört hat, von Noomi gekauft habe;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 4, 10, 'aber auch die Moabitin Ruth, die Witwe Machlons, habe ich mir zum Weibe erkauft, um den Namen des Verstorbenen auf seinem Erbbesitz fortzupflanzen, damit nicht der Name des Verstorbenen aus dem Kreise seiner Verwandten und aus dem Tor seines Heimatorts verschwindet: dafür seid ihr heute Zeugen!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 4, 11, 'Da erklärten alle im Stadttor Anwesenden und auch die Ältesten: »Ja, wir sind Zeugen! Der HERR gebe, daß die Frau, die in dein Haus einziehen soll, (so fruchtbar) werde wie Rahel und Lea, die beide das Haus Israel aufgebaut haben! Werde glücklich in Ephratha und schaffe dir einen Namen in Bethlehem!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 4, 12, 'Und dein Haus werde wie das Haus des Perez, den Thamar dem Juda geboren hat, durch die Nachkommenschaft, die der HERR dir von dieser jungen Frau bescheren wird!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 4, 13, 'So heiratete denn Boas die Ruth, und sie wurde sein Weib; und als er zu ihr eingegangen war, verlieh ihr der HERR Mutterglück durch die Geburt eines Sohnes.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 4, 14, 'Da sagten die Frauen zu Noomi: »Gepriesen sei der HERR, der es dir heute an einem Löser nicht hat fehlen lassen! Möge sein Name in Israel gefeiert werden,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 4, 15, 'und möge er ein Trost für dein Herz sein und dein Versorger im Alter! Denn deine Schwiegertochter, die dich liebhat, ist seine Mutter, sie, die dir mehr wert ist als sieben Söhne.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 4, 16, 'Da nahm Noomi das Kind, legte es auf ihren Schoß und wurde seine Wärterin.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 4, 17, 'Die Nachbarinnen aber legten ihm einen Namen bei, indem sie sagten: »Ein Sohn ist der Noomi geboren!«, und sie nannten ihn Obed. Der ist der Vater Isais, des Vaters Davids.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 4, 18, 'Dies ist der Stammbaum des Perez: Perez war der Vater Hezrons,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 4, 19, 'Hezron der Vater Rams, Ram der Vater Amminadabs,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 4, 20, 'Amminadab der Vater Nahassons, Nahasson der Vater Salmons,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 4, 21, 'Salmon der Vater des Boas, Boas der Vater Obeds,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 4, 22, 'Obed der Vater Isais und Isai der Vater Davids.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 1, 1, 'Es war einst ein Mann aus (den Bürgern von) Ramath, ein Zuphit vom Gebirge Ephraim, mit Namen Elkana, ein Sohn Jerohams, des Sohnes Elihus, des Sohnes Thohus, des Sohnes Zuphs, ein Ephrathiter.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 1, 2, 'Der hatte zwei Frauen: die eine hieß Hanna, die andere Peninna; und Peninna hatte Kinder, Hanna aber war kinderlos.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 1, 3, 'Dieser Mann zog Jahr für Jahr aus seinem Wohnort nach Silo hinauf, um Gott, den HERRN der Heerscharen, dort anzubeten und ihm zu opfern; dort waren die beiden Söhne Elis, Hophni und Pinehas, Priester des HERRN.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 1, 4, 'Sooft nun der Tag da war, an welchem Elkana opferte, gab er seiner Frau Peninna und all ihren Söhnen und Töchtern Anteile;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 1, 5, 'der Hanna aber gab er einen doppelten Anteil, denn er hatte Hanna lieber, obgleich der HERR ihr Kinder versagt hatte.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 1, 6, 'Dann kränkte aber ihre Nebenfrau sie mit lieblosen Reden, um sie zu ärgern, weil der HERR ihr Kindersegen versagt hatte.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 1, 7, 'So ging es Jahr für Jahr: so oft sie zum Hause des HERRN hinaufzog, kränkte jene sie so, daß sie weinte und nichts aß.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 1, 8, 'Elkana, ihr Gatte, fragte sie dann: »Hanna, warum weinst du, und warum issest du nicht, und warum bist du so betrübt? Bin ich dir nicht mehr wert als zehn Söhne?«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 1, 9, 'Als man nun einst wieder in Silo in der Halle gegessen und getrunken hatte, stand Hanna auf und trat vor den HERRN, während der Priester Eli gerade auf dem Stuhl an einem der Türpfosten des Tempels des HERRN saß.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 1, 10, 'In tiefer Bekümmernis und unter vielen Tränen betete sie zum HERRN');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 1, 11, 'und sprach folgendes Gelübde aus: »Gott, HERR der Heerscharen! Wenn du das Elend deiner Magd ansehen und meiner gedenken und deine Magd nicht vergessen willst und deiner Magd einen männlichen Sproß schenkst, so will ich ihn dir, HERR, für sein ganzes Leben weihen, und kein Schermesser soll an sein Haupt kommen.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 1, 12, 'Als sie nun lange Zeit so vor dem HERRN betete, stieg in Eli, der ihren Mund beobachtete –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 1, 13, 'Hanna redete nämlich leise für sich, nur ihre Lippen bewegten sich, während man ihre Stimme nicht hören konnte –, der Gedanke auf, sie sei trunken;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 1, 14, 'und er sagte zu ihr: »Wie lange willst du dich noch wie eine Trunkene benehmen? Werde endlich wieder nüchtern!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 1, 15, 'Da erwiderte ihm Hanna: »Ach nein, Herr, ich bin eine unglückliche Frau! Wein und berauschende Getränke habe ich nicht genossen, sondern mein Herz vor dem HERRN ausgeschüttet.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 1, 16, 'Halte deine Magd nicht für ein verworfenes Weib! Denn nur infolge meiner großen Bekümmernis und Traurigkeit habe ich so lange gebetet.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 1, 17, 'Da entgegnete ihr Eli: »Gehe hin in Frieden! Der Gott Israels möge dir die Bitte gewähren, die du an ihn gerichtet hast!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 1, 18, 'Sie erwiderte: »Laß deine Magd deiner Huld empfohlen sein!« Damit ging die Frau ihres Weges und aß, und ihr trauriges Aussehen war verschwunden.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 1, 19, 'Am andern Morgen machten sie sich früh auf und verrichteten ihre Andacht vor dem HERRN, und als sie dann in ihr Haus nach Rama zurückgekehrt waren und Elkana zu seiner Frau einging, da gedachte der HERR der Hanna:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 1, 20, 'sie wurde guter Hoffnung, und als die Zeit um war, gebar sie einen Sohn, dem sie den Namen Samuel gab; »denn«, sagte sie, »vom HERRN habe ich ihn erbeten.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 1, 21, 'Als dann ihr Mann Elkana mit seiner ganzen Familie wieder hinaufzog, um dem HERRN das jährliche Schlachtopfer und, was er gelobt hatte, darzubringen,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 1, 22, 'ging Hanna nicht mit hinauf; denn sie hatte zu ihrem Manne gesagt: »Der Knabe soll erst entwöhnt sein; dann will ich ihn hinbringen, damit er vor dem HERRN erscheint und für immer dort bleibt.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 1, 23, 'Da hatte Elkana, ihr Mann, ihr erwidert: »Mache es so, wie du es für gut hältst: bleibe daheim, bis du ihn entwöhnt hast! Nur möge der HERR seine Verheißung in Erfüllung gehen lassen!« So blieb denn die Frau daheim und nährte ihren Sohn bis zu seiner Entwöhnung.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 1, 24, 'Sobald sie ihn aber entwöhnt hatte, nahm sie ihn mit sich hinauf nebst einem dreijährigen Stier, einem Epha Mehl und einem Schlauch Wein: so brachte sie den Knaben, wiewohl er noch sehr jung war, in das Gotteshaus nach Silo.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 1, 25, 'Als sie dort den Stier geopfert hatten und sie den Knaben zu Eli brachten,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 1, 26, 'sagte die Mutter (zu Eli): »Verzeihe, mein Herr! So wahr du lebst, mein Herr: ich bin die Frau, die einst hier bei dir gestanden hat, um zum HERRN zu beten.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 1, 27, 'Um diesen Knaben habe ich damals gebetet; nun hat der HERR mir die Bitte gewährt, die ich ihm vorgetragen habe.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 1, 28, 'So habe denn auch ich ihn dem HERRN geweiht: solange er lebt, soll er dem HERRN geweiht sein!« Hierauf beteten sie dort den HERRN an.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 1, 'Hanna aber betete so: »Mein Herz frohlockt in dem HERRN, hoch ragt mein Horn durch den HERRN; mein Mund hat weit sich aufgetan gegen meine Feinde, denn ich freue mich deiner Hilfe.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 2, 'Niemand ist heilig wie der HERR, denn keiner ist da außer dir und keiner ein Fels wie unser Gott.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 3, 'Laßt euer ewiges stolzes Reden: kein vermessenes Wort entfahre eurem Munde! Denn ein allwissender Gott ist der HERR und ein Gott, von dem die Taten gewogen werden.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 4, 'Der Bogen der Starken wird zerbrochen, Strauchelnde aber gürten sich mit Kraft.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 5, 'Die da satt waren, müssen um Brot sich verdingen, aber die Hunger litten, hungern nicht mehr; sogar die Unfruchtbare wird Mutter von sieben, aber die Kinderreiche welkt dahin.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 6, 'Der HERR tötet und macht lebendig, er stößt ins Totenreich hinab und führt herauf;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 7, 'der HERR macht arm und macht reich, er erniedrigt und erhöht auch;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 8, 'er hebt den Geringen empor aus dem Staube, erhöht den Armen aus dem Kehricht, um sie neben den Fürsten sitzen zu lassen und den Ehrenstuhl ihnen anzuweisen. Denn in der Hand des HERRN sind die Säulen der Erde, und den Erdkreis hat er darauf gegründet.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 9, 'Die Schritte seiner Frommen behütet er, aber die Gottlosen verstummen in der Finsternis; denn nicht durch (eigene) Kraft gewinnt der Mensch den Sieg.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 10, 'Die Widersacher des HERRN werden zerschmettert, über ihnen donnert er im Himmel; der HERR richtet die Enden der Erde. Stärke verleiht er seinem König und erhöht das Horn seines Gesalbten.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 11, 'Darauf kehrte Elkana nach Rama in sein Haus zurück; der Knabe aber diente dem HERRN unter der Aufsicht des Priesters Eli.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 12, 'Die Söhne Elis aber waren nichtswürdige Buben, die sich weder um den HERRN');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 13, 'noch um das Recht der Priester gegenüber dem Volke kümmerten. Sooft nämlich jemand ein Schlachtopfer darbrachte, kam, während man das Fleisch noch kochte, der Diener des Priesters mit einer dreizinkigen Gabel in der Hand');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 14, 'und stieß damit in den Kessel oder den Topf, in die Pfanne oder den Tiegel, und alles, was die Gabel dann heraufbrachte, nahm der Priester für sich. So machten sie es in Silo bei allen Israeliten, die dorthin kamen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 15, 'Sogar noch ehe man das Fett in Rauch hatte aufgehen lassen, kam der Diener des Priesters und sagte zu dem, der das Opfer darbrachte: »Gib Fleisch her zum Braten für den Priester! Denn er will kein gekochtes Fleisch von dir haben, sondern rohes.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 16, 'Wenn dann der betreffende Mann ihm entgegnete: »Zuerst muß doch das Fett verbrannt werden, dann magst du dir nehmen, wie es dir beliebt!«, so antwortete er: »Nein, gleich jetzt sollst du es hergeben, sonst nehme ich es mit Gewalt!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 17, 'So war denn die Versündigung der beiden jungen Männer sehr schwer vor dem HERRN, weil sie das Opfer des HERRN geringschätzig behandelten.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 18, 'Samuel aber versah den Dienst vor dem HERRN als Tempelknabe, mit einem linnenen Schulterkleid umgürtet;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 19, 'dazu pflegte seine Mutter ihm ein kleines Obergewand anzufertigen und brachte es ihm jedes Jahr mit, wenn sie mit ihrem Manne hinaufzog, um das jährliche Schlachtopfer darzubringen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 20, 'Dann segnete Eli jedesmal den Elkana und seine Frau mit den Worten: »Der HERR wolle dir Kinder von dieser Frau schenken als Entgelt für das Darlehen, das sie dem HERRN geliehen hat!« Danach kehrten sie nach Hause zurück.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 21, 'Der HERR aber segnete Hanna, so daß sie wiederum guter Hoffnung wurde und noch drei Söhne und zwei Töchter gebar. Der junge Samuel aber wuchs heran beim HERRN.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 22, 'Wenn nun Eli, der ein sehr alter Mann war, von allem hörte, was seine Söhne an allen Israeliten verübten, auch daß sie sich mit den Weibern vergingen, die draußen vor dem Offenbarungszelt sich einfanden,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 23, 'dann sagte er zu ihnen: »Warum laßt ihr euch dergleichen zuschulden kommen? Denn ich höre diese üblen Reden über euch von allen Leuten hier.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 24, 'Nicht doch, meine Söhne! Denn das ist kein gutes Gerücht, das vom Volk des HERRN, wie ich höre, über euch verbreitet wird.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 25, 'Wenn sich ein Mensch gegen einen Menschen vergeht, so entscheidet die Gottheit als Richter über ihn; wenn sich aber ein Mensch gegen den HERRN vergeht, wer könnte da als Vermittler für ihn eintreten?« Doch sie hörten nicht auf die Mahnungen ihres Vaters, denn der HERR hatte ihren Tod beschlossen. –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 26, 'Der junge Samuel aber wuchs immer mehr heran und gewann an Liebe sowohl beim HERRN als auch bei den Menschen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 27, 'Da kam ein Gottesmann zu Eli und sagte zu ihm: »So hat der HERR gesprochen: ›Allerdings habe ich mich dem Hause deines Vaters (Aaron) geoffenbart, als sie noch in Ägypten (Knechte) des Hauses des Pharaos waren,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 28, 'und habe ihn mir aus allen Stämmen Israels zum Priester erwählt, damit er zu meinem Altar hinaufsteige und Räucherwerk anzünde und das Schulterkleid vor mir trage; und ich habe dem Hause deines Vaters alle Feueropfer der Israeliten zum Unterhalt zugewiesen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 29, 'Warum tretet ihr nun mit Füßen meine Schlachtopfer und meine Speisopfer, die ich für meine Wohnung angeordnet habe? Und warum ehrst du deine Söhne mehr als mich, so daß ihr euch von den Erstlingen aller Opfergaben meines Volkes Israel mästet?‹');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 30, 'Darum lautet der Ausspruch des HERRN, des Gottes Israels, so: ›Ich habe allerdings gesagt: Dein Haus und deines Vaters Haus sollen ewiglich vor mir einhergehen‹; jetzt aber lautet der Ausspruch des HERRN so: ›Fern sei das von mir! Nein, wer mich ehrt, den will ich wieder ehren, aber wer mich verachtet, der wird erniedrigt werden.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 31, 'Wisse wohl: es kommt die Zeit, da werde ich deinen Arm und den Arm deines ganzen Geschlechts abhauen, so daß es keinen Betagten mehr in deinem Hause geben soll.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 32, 'Dann wirst du neidisch auf alles Glück hinblicken, mit dem der HERR Israel segnen wird, während sich in deinem Hause nie mehr ein Betagter finden wird.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 33, 'Und gesetzt, ich tilge dir einmal einen nicht weg von meinem Altar, um deine Augen nicht verschmachten und dein Herz sich nicht abhärmen zu lassen, so soll doch aller Nachwuchs deines Hauses schon im Mannesalter sterben.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 34, 'Und das Schicksal, das deine beiden Söhne Hophni und Pinehas treffen wird, soll dir ein Zeichen sein: an einem Tage werden sie beide sterben!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 35, 'Mir aber will ich einen treuen Priester erstehen lassen, der nach meinem Herzen und nach meinem Sinn handelt; dem will ich ein Haus bauen, das Bestand hat, und er soll allezeit vor meinem Gesalbten einhergehen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 36, 'Dann wird es dahin kommen, daß jeder, der von deinem Hause noch übriggeblieben ist, herbeikommt und sich vor ihm niederwirft, um ein Geldstück als Almosen oder einen Laib Brot zu erbetteln, und die Bitte ausspricht: Bringe mich doch bei einer der Priesterschaften unter, damit ich ein Stück Brot zu essen habe!‹«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 3, 1, 'Zu der Zeit, wo der junge Samuel den Dienst des HERRN unter Elis Aufsicht versah, waren Offenbarungen des HERRN in Israel etwas Seltenes: Gesichte kamen nicht häufig vor.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 3, 2, 'Nun begab es sich zu jener Zeit, während Eli an seiner gewöhnlichen Stelle schlief – seine Augen waren aber allmählich schwach geworden, so daß er nicht mehr sehen konnte;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 3, 3, 'die Lampe Gottes war noch nicht erloschen, Samuel aber schlief im Tempel des HERRN da, wo die Lade Gottes stand –,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 3, 4, 'da rief der HERR: »Samuel!« Dieser antwortete: »Hier bin ich!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 3, 5, 'und lief dann zu Eli und sagte: »Hier bin ich! Du hast mich ja gerufen.« Jener aber erwiderte: »Ich habe nicht gerufen; lege dich wieder schlafen!« Da ging er hin und legte sich schlafen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 3, 6, 'Der HERR aber rief wiederum: »Samuel!« Dieser erhob sich, ging zu Eli und sagte: »Hier bin ich! Du hast mich ja gerufen.« Jener antwortete: »Ich habe nicht gerufen, mein Sohn; lege dich wieder schlafen!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 3, 7, 'Samuel hatte nämlich den HERRN noch nicht kennengelernt, und es war ihm noch keine Offenbarung des HERRN zuteil geworden.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 3, 8, 'Nun rief der HERR wiederum zum drittenmal: »Samuel!« Da stand er auf, ging zu Eli und sagte: »Hier bin ich! Du hast mich ja gerufen.« Jetzt erkannte Eli, daß der HERR es war, der den Jüngling gerufen hatte;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 3, 9, 'daher sagte Eli zu Samuel: »Gehe hin, lege dich schlafen! Doch wenn du wieder angerufen wirst, so antworte: ›Rede, HERR, denn dein Knecht hört!‹« So ging denn Samuel hin und legte sich auf seinem Platze schlafen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 3, 10, 'Da kam der HERR, trat vor ihn hin und rief wie die vorigen Male: »Samuel! Samuel!« Dieser antwortete: »Rede! Denn dein Knecht hört.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 3, 11, 'Da sagte der HERR zu Samuel: »Wisse wohl, ich will in Israel etwas vollführen, daß jedem, der es hört, beide Ohren gellen sollen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 3, 12, 'An jenem Tage will ich an Eli alles in Erfüllung gehen lassen, was ich seinem Hause angedroht habe, von Anfang bis zu Ende!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 3, 13, 'Denn ich habe ihm ankündigen lassen, daß ich sein Haus für alle Zeit richten will wegen seiner Verschuldung; denn er hat gewußt, daß seine Söhne Gott in Verachtung bringen, und er ist ihnen dennoch nicht entgegengetreten.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 3, 14, 'Darum habe ich dem Hause Elis geschworen: ›Wahrlich, die Verfehlung des Hauses Elis soll in Ewigkeit nicht, weder durch Schlachtopfer noch durch Speisopfer, gesühnt werden!‹«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 3, 15, 'Samuel blieb hierauf bis zum Morgen liegen; dann öffnete er die Türen des Hauses des HERRN, scheute sich jedoch, dem Eli etwas von dem Gesicht mitzuteilen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 3, 16, 'Aber Eli rief ihn zu sich und sagte: »Samuel, mein Sohn!« Dieser antwortete: »Hier bin ich!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 3, 17, 'Da fragte jener: »Was hat er zu dir gesagt? Verheimliche mir ja nichts! Gott möge dir’s jetzt und künftig vergelten, wenn du mir irgend etwas von allem verheimlichst, was er zu dir gesagt hat!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 3, 18, 'Da teilte ihm Samuel die ganze Offenbarung mit, ohne ihm etwas zu verschweigen; der aber erwiderte: »Er ist der HERR: er tue, was ihm wohlgefällt!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 3, 19, 'Samuel aber wuchs heran, und der HERR war mit ihm und ließ nichts unerfüllt von allem, was er angekündigt hatte;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 3, 20, 'und ganz Israel von Dan bis Beerseba erkannte, daß Samuel zum Propheten des HERRN bestellt worden war.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 3, 21, 'Der HERR aber erschien auch fernerhin in Silo; denn der HERR offenbarte sich dem Samuel [in Silo durch das Wort des HERRN], und Samuel teilte dann die Offenbarungen dem gesamten Israel mit.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 4, 1, 'Und die Israeliten zogen den Philistern zum Kampf entgegen und lagerten bei Eben-Eser, während die Philister ihr Lager bei Aphek aufgeschlagen hatten.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 4, 2, 'Als sich nun die Philister den Israeliten gegenüber in Schlachtordnung aufgestellt hatten und der Kampf sich weit ausbreitete, wurden die Israeliten von den Philistern besiegt, und diese erschlugen in der Schlacht auf offenem Felde gegen viertausend Mann.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 4, 3, 'Als dann das Heer ins Lager zurückgekehrt war, sagten die Ältesten der Israeliten: »Warum hat der HERR uns heute den Philistern unterliegen lassen? Wir wollen die Bundeslade des HERRN aus Silo zu uns holen, damit er in unsere Mitte kommt und uns aus der Hand unserer Feinde errettet.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 4, 4, 'So sandte denn das Volk nach Silo, und man holte von dort die Bundeslade Gottes, des HERRN der Heerscharen, der über den Cheruben thront; und die beiden Söhne Elis, Hophni und Pinehas, begleiteten die Bundeslade Gottes.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 4, 5, 'Als nun die Bundeslade des HERRN ins Lager kam, erhob ganz Israel ein so gewaltiges Jubelgeschrei, daß die Erde davon erdröhnte.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 4, 6, 'Als die Philister den lauten Jubel hörten, fragten sie: »Was hat dies laute Jubelgeschrei im Lager der Hebräer zu bedeuten?« Als sie dann erfuhren, daß die Lade des HERRN ins Lager gekommen sei,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 4, 7, 'gerieten die Philister in Angst, denn sie dachten: »Gott ist zu ihnen ins Lager gekommen!«, und sie riefen aus: »Wehe uns! Denn so etwas ist vordem nie geschehen!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 4, 8, 'Wehe uns! Wer wird uns aus der Hand dieser mächtigen Gottheit erretten? Das ist ja dieselbe Gottheit, welche die Ägypter in der Wüste mit allerlei Plagen geschlagen hat!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 4, 9, 'Haltet euch tapfer und zeigt euch als Männer, ihr Philister, sonst müßt ihr den Hebräern dienen, wie sie euch gedient haben; ja, seid Männer und kämpft!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 4, 10, 'Da kämpften denn die Philister, und die Israeliten wurden geschlagen, und sie flohen ein jeder zu seinen Zelten; und die Niederlage war sehr schwer: es fielen von den Israeliten dreißigtausend Mann Fußvolk.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 4, 11, 'Auch die Lade Gottes wurde (von den Feinden) erbeutet, und die beiden Söhne Elis, Hophni und Pinehas, fanden den Tod.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 4, 12, 'Ein Benjaminit nun war vom Schlachtfelde weggeeilt und noch an demselben Tage nach Silo gelangt mit zerrissenen Kleidern und mit Erde auf dem Haupt.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 4, 13, 'Als er dort ankam, saß Eli gerade auf einem Stuhle (neben dem Tor) und spähte die Straße entlang; denn sein Herz bangte um die Lade Gottes. Als nun der Mann ankam, um der Stadt die Nachricht zu bringen, erhob die ganze Stadt ein Wehgeschrei.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 4, 14, 'Als Eli das laute Geschrei hörte, fragte er: »Was bedeutet dieses gewaltige Geschrei?« Da kam der Mann herangeeilt und brachte dem Eli die Meldung.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 4, 15, 'Eli war aber achtundneunzig Jahre alt und hatte das Augenlicht verloren, so daß er nicht mehr sehen konnte.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 4, 16, 'Als nun der Mann zu Eli sagte: »Ich bin der Bote, der vom Schlachtfeld gekommen ist, und zwar bin ich heute vom Schlachtfeld geflohen«, da fragte Eli: »Wie ist es (denn dort) gegangen, mein Sohn?«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 4, 17, 'Der Bote antwortete: »Die Israeliten sind vor den Philistern geflohen; dazu hat unser Heer eine schwere Niederlage erlitten; auch deine beiden Söhne, Hophni und Pinehas, sind tot, und die Lade Gottes ist (von den Feinden) erbeutet.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 4, 18, 'Als er nun die Lade Gottes erwähnte, da fiel Eli rücklings vom Stuhl herab neben dem Tor, brach das Genick und war tot; denn er war alt und ein schwerer Mann. Vierzig Jahre lang war er Richter in Israel gewesen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 4, 19, 'Seine Schwiegertochter aber, die Frau des Pinehas, war hochschwanger; als sie nun die Kunde vom Verlust der Lade Gottes und vom Tode ihres Schwiegervaters und ihres Mannes vernahm, brach sie zusammen und gebar, da die Wehen sie plötzlich überfielen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 4, 20, 'Als es nun mit ihr zum Sterben ging und die Frauen, die um sie standen, zu ihr sagten: »Fürchte dich nicht; du hast einen Sohn geboren!«, gab sie keine Antwort und war ganz teilnahmslos;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 4, 21, 'doch nannte sie den Knaben Ikabod, womit sie sagen wollte: »Dahin ist die Herrlichkeit Israels!«, weil ja die Lade Gottes verlorengegangen war und wegen ihres Schwiegervaters und um ihres Mannes willen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 4, 22, 'Sie rief also aus: »Dahin ist die Herrlichkeit Israels, denn die Lade Gottes ist verlorengegangen!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 5, 1, 'Die Philister aber hatten die Lade Gottes erbeutet und brachten sie von Eben-Eser nach Asdod;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 5, 2, 'dort nahmen die Philister die Lade Gottes, brachten sie in den Tempel Dagons und stellten sie neben Dagon hin.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 5, 3, 'Als aber die Einwohner von Asdod am nächsten Morgen früh in den Tempel Dagons kamen, fanden sie Dagon vor der Lade des HERRN am Boden auf dem Angesicht liegen. Da nahmen sie Dagon und stellten ihn wieder an seinen Platz.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 5, 4, 'Als sie aber am folgenden Tage frühmorgens kamen, fanden sie Dagon wieder auf seinem Angesicht am Boden vor der Lade des HERRN liegen, und zwar lagen der Kopf Dagons und seine beiden Hände abgetrennt auf der Schwelle des Tempels; nur sein Fischrumpf war neben ihr noch übriggeblieben.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 5, 5, 'Daher treten in Asdod die Priester Dagons und alle, die in den Dagontempel hineingehen, nicht auf die Schwelle Dagons bis auf den heutigen Tag.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 5, 6, 'Hierauf legte sich die Hand des HERRN schwer auf die Einwohner von Asdod; er setzte sie in Schrecken und suchte die Stadt und ihr Gebiet mit Pestbeulen heim.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 5, 7, 'Als nun die Leute von Asdod diese ihre schlimme Lage erkannten, sagten sie: »Die Lade des Gottes Israels darf nicht bei uns bleiben! Denn seine Hand lastet schwer auf uns und unserm Gott Dagon.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 5, 8, 'Da beriefen sie durch Boten sämtliche Fürsten der Philister in ihre Stadt zusammen und fragten: »Was sollen wir mit der Lade des Gottes Israels machen?« Da antworteten jene: »Nach Gath soll die Lade des Gottes Israels überführt werden!«, und sie ließen sie auch wirklich dorthin bringen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 5, 9, 'Aber als sie dorthin geschafft worden war, kam die Hand des HERRN über die Stadt mit einer ganz gewaltigen Bestürzung, und er schlug auch hier die Leute der Stadt, junge und alte, so daß Pestbeulen an ihnen zum Ausbruch kamen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 5, 10, 'Als man dann die Lade Gottes nach Ekron gebracht hatte, schrien die Einwohner der Stadt nach Ankunft der Lade Gottes in Ekron: »Man hat die Lade des Gottes Israels zu uns hergebracht, um uns und unsere Einwohnerschaft umzubringen!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 5, 11, 'Da ließen sie wiederum alle Fürsten der Philister durch Boten zusammenrufen und baten: »Schickt die Lade des Gottes der Israeliten wieder zurück an den Ort, wohin sie gehört, damit sie nicht uns und unser Volk umbringt!« Denn es war ein tödlicher Schrecken über die ganze Stadt gekommen: überaus schwer lastete die Hand Gottes auf ihr;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 5, 12, 'denn die Leute, die nicht starben, litten qualvoll an Pestbeulen, und das Wehgeschrei der Stadt stieg zum Himmel empor.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 6, 1, 'Nachdem sich nun die Lade des HERRN sieben Monate lang im Gebiet der Philister befunden hatte,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 6, 2, 'beriefen die Philister ihre Priester und Wahrsager und fragten sie: »Was sollen wir mit der Lade des HERRN machen? Laßt uns wissen, auf welche Weise wir sie an den Ort, wohin sie gehört, zurückschicken sollen!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 6, 3, 'Jene antworteten: »Wollt ihr die Lade des Gottes Israels zurückschicken, so dürft ihr sie nicht ohne Geschenke ziehen lassen, sondern müßt ihr jedenfalls ein Sühnegeschenk zum Entgelt mitgeben; alsdann wird es euch wieder gutgehen, und ihr werdet auch in Erfahrung bringen, warum seine Hand nicht von euch abläßt.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 6, 4, 'Da fragten sie: »Worin soll das Sühnegeschenk bestehen, das wir ihm als Entgelt entrichten sollen?« Jene antworteten: »Entsprechend der Zahl der Fürsten der Philister: fünf goldene (Nachbildungen eurer) Pestbeulen und fünf goldene Mäuse; denn die gleiche Plage ist euch allen, auch euren Fürsten widerfahren.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 6, 5, 'Laßt also Nachbildungen eurer Pestbeulen und Nachbildungen von den Mäusen anfertigen, die euch das Land verwüsten, und erweist so dem Gott Israels eine Ehre; vielleicht läßt er dann seine Hand nicht mehr so schwer auf euch und eurem Gott und eurem Lande lasten.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 6, 6, 'Warum wollt ihr euer Herz verhärten, wie die Ägypter und der Pharao einst ihr Herz verhärtet haben? Nicht wahr: erst als er ihnen übel mitgespielt hatte, da ließen sie sie ziehen, und sie durften gehen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 6, 7, 'Laßt also jetzt einen neuen Wagen fertigen und nehmt ein Paar säugende Kühe, auf die noch nie ein Joch gekommen ist; spannt dann die Kühe an den Wagen, ihre Kälber aber treibt von ihnen weg nach Hause zurück.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 6, 8, 'Dann nehmt die Lade des HERRN, stellt sie auf den Wagen und tut die goldenen Kleinodien, die ihr ihm als Sühnegeschenk entrichten wollt, in ein Kästchen neben sie und laßt sie so ihres Weges ziehen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 6, 9, 'Gebt aber acht: wenn sie den Heimweg antritt hinauf nach Beth-Semes hin, so ist er es gewesen, der uns dieses große Unglück hat zustoßen lassen; andernfalls wissen wir, daß nicht seine Hand uns heimgesucht hat, sondern daß nur ein Zufall uns begegnet ist.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 6, 10, 'Da taten die Leute so: sie nahmen ein Paar säugende Kühe und spannten sie an den Wagen, während sie ihre Kälber zu Hause zurückbehielten.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 6, 11, 'Dann stellten sie die Lade des HERRN auf den Wagen samt dem Kästchen mit den goldenen Mäusen und den Nachbildungen ihrer Pestbeulen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 6, 12, 'Da gingen die Kühe geradeaus auf dem Wege nach Beth-Semes zu, verfolgten, unaufhörlich brüllend, dieselbe Straße, ohne nach rechts oder nach links abzubiegen; die Fürsten der Philister aber gingen hinter ihnen her bis an die Feldmark von Beth-Semes.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 6, 13, 'Die Einwohner von Beth-Semes aber waren gerade mit der Weizenernte in der Niederung beschäftigt. Als sie nun ihre Augen erhoben und die Lade erblickten, freuten sie sich, sie wiederzusehen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 6, 14, 'Als der Wagen dann auf dem Felde des Bethsemesiters Josua angekommen war, stand er daselbst still. Dort lag ein großer Stein. Sie spalteten nun das Holz des Wagens und brachten die beiden Kühe dem HERRN als Brandopfer dar.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 6, 15, 'Die Leviten hatten nämlich die Lade des HERRN herabgenommen und ebenso das neben ihr stehende Kästchen, in welchem sich die goldenen Kleinodien befanden, und hatten sie auf den großen Stein gestellt; hierauf brachten die Einwohner von Beth-Semes dem HERRN noch an demselben Tage Brand- und Schlachtopfer dar.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 6, 16, 'Nachdem dann die fünf Fürsten der Philister alles mit angesehen hatten, kehrten sie noch an demselben Tage nach Ekron zurück. –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 6, 17, 'Folgendes sind aber die goldenen Pestbeulen, welche die Philister dem HERRN als Sühnegeschenk erstattet haben: für Asdod eine, für Gaza eine, für Askalon eine, für Gath eine, für Ekron eine;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 6, 18, 'die goldenen Mäuse aber entsprachen der Zahl aller Ortschaften der Philister unter den fünf Fürsten, sowohl der befestigten Städte als auch der offenen Bauerndörfer. (Zeuge) hierfür ist der große Stein, auf den sie die Lade des HERRN niedergesetzt hatten, der bis auf den heutigen Tag auf dem Felde Josuas, des Bethsemesiters, liegt.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 6, 19, '(Der Herr) aber ließ unter den Einwohnern von Beth-Semes ein Sterben ausbrechen, weil sie in die Lade des HERRN hineingeschaut hatten, und ließ unter der Einwohnerschaft siebzig Personen sterben. Da trauerte die Einwohnerschaft darüber, daß der HERR ein so schreckliches Unglück über das Volk hatte kommen lassen;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 6, 20, 'und die Leute von Beth-Semes riefen aus: »Wer vermag zu bestehen vor dem HERRN, diesem heiligen Gott?!« und: »Zu wem soll er nun hingehen von uns weg?«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 6, 21, 'Sie sandten dann Boten zu den Einwohnern von Kirjath-Jearim und ließen ihnen sagen: »Die Philister haben die Lade des HERRN zurückgebracht; kommt herab und holt sie zu euch hinauf!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 7, 1, 'Da kamen die Männer von Kirjath-Jearim, holten die Lade des HERRN hinauf und brachten sie in das Haus Abinadabs auf der Anhöhe; seinen Sohn Eleasar aber weihten sie zum Hüter der Lade des HERRN.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 7, 2, 'Seit dem Tage nun, an welchem die Lade des HERRN in Kirjath-Jearim untergebracht war, verging eine lange Zeit, wohl zwanzig Jahre. Als sich dann das ganze Haus Israel mit Wehklagen an den HERRN wandte,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 7, 3, 'sagte Samuel zum ganzen Hause Israel: »Wenn ihr mit eurem ganzen Herzen zum HERRN umkehren wollt, so schafft die fremden Götter und besonders die Astartebilder aus eurer Mitte weg und richtet euer Herz auf den HERRN und dient ihm allein, dann wird er euch aus der Gewalt der Philister erretten.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 7, 4, 'Da entfernten die Israeliten die Bilder Baals und der Astarte und dienten dem HERRN allein.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 7, 5, 'Hierauf machte Samuel bekannt: »Laßt ganz Israel in Mizpa zusammenkommen, dann will ich Fürbitte für euch beim HERRN einlegen!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 7, 6, 'Als sie sich nun in Mizpa versammelt hatten, schöpften sie Wasser und gossen es vor dem HERRN aus; zugleich fasteten sie an jenem Tage und legten dort das Bekenntnis ab: »Wir haben gegen den HERRN gesündigt!« Sodann sprach Samuel den Israeliten in Mizpa Recht.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 7, 7, 'Als aber die Philister erfuhren, daß die Israeliten sich in Mizpa versammelt hatten, zogen die Fürsten der Philister gegen Israel hinauf. Als die Israeliten Kunde davon erhielten, gerieten sie in Furcht vor den Philistern');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 7, 8, 'und baten Samuel: »Laß nicht ab, für uns zum HERRN, unserm Gott, laut zu flehen, daß er uns aus der Gewalt der Philister errette!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 7, 9, 'Da nahm Samuel ein Milchlamm und brachte es dem HERRN als Ganzopfer dar; dabei flehte Samuel laut für Israel zum HERRN, und der HERR erhörte ihn.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 7, 10, 'Während nämlich Samuel an jenem Tage das Brandopfer darbrachte, waren die Philister zum Angriff gegen Israel herangerückt; aber der HERR ließ ein Gewitter mit furchtbarem Donner über den Philistern ausbrechen und versetzte sie dadurch in solche Bestürzung, daß sie von den Israeliten geschlagen wurden.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 7, 11, 'Da brachen die Israeliten aus Mizpa hervor, verfolgten die Philister und richteten ein Blutbad unter ihnen an bis unterhalb von Beth-Kar.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 7, 12, 'Darauf nahm Samuel einen Stein und stellte ihn zwischen Mizpa und Sen auf und gab ihm den Namen Eben-Eser und sagte: »Bis hierher hat der HERR uns geholfen!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 7, 13, 'So waren denn die Philister gedemütigt und fielen fortan nicht mehr in das Gebiet der Israeliten ein; denn solange Samuel lebte, lag die Hand des HERRN auf den Philistern.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 7, 14, 'Auch die Städte, welche die Philister den Israeliten abgenommen hatten, kamen wieder in den Besitz der Israeliten, von Ekron an bis Gath; auch das zu ihnen gehörige Gebiet machte Israel von der Herrschaft der Philister frei. Ebenso bestand Friede zwischen Israel und den Amoritern.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 7, 15, 'Samuel waltete dann als Richter in Israel während seines ganzen Lebens.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 7, 16, 'Er zog nämlich Jahr für Jahr umher und machte die Runde über Bethel, Gilgal und Mizpa; wenn er dann an allen diesen Orten Gericht in Israel gehalten hatte,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 7, 17, 'kehrte er nach Rama zurück; denn dort hatte er seinen Wohnsitz, und dort sprach er den Israeliten Recht; er baute dort dem HERRN auch einen Altar.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 8, 1, 'Als aber Samuel alt geworden war, bestellte er seine (beiden) Söhne zu Richtern über Israel.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 8, 2, 'Sein ältester Sohn hieß Joel, sein zweiter Abia; sie sprachen in Beerseba Recht.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 8, 3, 'Aber seine Söhne wandelten nicht in seinen Wegen, sondern gingen auf Gewinn aus, nahmen Bestechungsgeschenke an und beugten das Recht.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 8, 4, 'Da versammelten sich alle Ältesten der Israeliten, kamen zu Samuel nach Rama');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 8, 5, 'und sagten zu ihm: »Du bist nun alt geworden, und deine Söhne wandeln nicht in deinen Wegen; so setze nun einen König über uns ein, der uns richten soll, wie es bei allen anderen Völkern der Fall ist.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 8, 6, 'Samuel war zwar unzufrieden damit, daß sie von ihm die Einsetzung eines Königs verlangten, der über sie herrschen sollte; doch als er zum HERRN betete,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 8, 7, 'gab der HERR ihm die Antwort: »Komm der Forderung des Volkes in allem nach, was sie von dir verlangen! Denn nicht dich haben sie verworfen, sondern mich haben sie verworfen, daß ich nicht (länger) König über sie sein soll.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 8, 8, 'Sie machen es jetzt mit dir ebenso, wie sie es mit mir immer gemacht haben seit der Zeit, wo ich sie aus Ägypten hergeführt habe, bis auf diesen Tag, indem sie mich verlassen und anderen Göttern gedient haben.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 8, 9, 'So komm also ihrer Forderung nach; nur verwarne sie ernstlich und weise sie hin auf die Rechte des Königs, der über sie herrschen wird.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 8, 10, 'Hierauf teilte Samuel dem Volke, das einen König von ihm forderte, alles mit, was der HERR zu ihm gesagt hatte,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 8, 11, 'und fuhr dann fort: »Folgende Rechte wird der König haben, der über euch herrschen wird: Eure Söhne wird er nehmen, um sie für sich bei seinen Kriegswagen und seinen Reitern zu verwenden; er wird sie auch vor seinem Wagen herlaufen lassen');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 8, 12, 'und sie als Befehlshaber über Tausend und als Befehlshaber über Fünfzig für sich anstellen; sie werden ferner seine Äcker pflügen müssen und seine Ernte einbringen und ihm Kriegsgeräte und Wagengeschirr anzufertigen haben.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 8, 13, 'Eure Töchter aber wird er nehmen und sie zum Salbenbereiten, zum Kochen und zum Backen verwenden.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 8, 14, 'Von euren Äckern, euren Weinbergen und Ölbaumgärten wird er die besten nehmen und sie seinen Dienern geben;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 8, 15, 'und von euren Saatfeldern und Weinbergen wird er den Zehnten erheben und ihn seinen Hofleuten und Beamten geben.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 8, 16, 'Eure Knechte und Mägde, eure schönsten Rinder und Esel wird er nehmen und sie für seine Wirtschaft verwenden.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 8, 17, 'Von eurem Kleinvieh wird er den Zehnten erheben, und ihr selbst werdet ihm als Knechte dienen müssen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 8, 18, 'Und wenn ihr dann wegen eures Königs, den ihr euch erwählt habt, zum HERRN schreit, so wird der HERR euch alsdann nicht erhören.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 8, 19, 'Aber das Volk wollte auf Samuels Vorstellungen nicht hören, sondern erklärte: »Nein, es soll dennoch ein König an unserer Spitze stehen!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 8, 20, 'Wir wollen es ebenso haben wie alle anderen Völker: unser König soll uns Recht sprechen, soll unser Anführer sein und unsere Kriege führen.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 8, 21, 'Als nun Samuel alle Worte des Volkes angehört und sie dem HERRN vorgetragen hatte,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 8, 22, 'sagte der HERR zu Samuel: »Komm ihrer Forderung nach und setze einen König über sie ein!« Darauf sagte Samuel zu den Männern von Israel: »Geht heim, ein jeder in seinen Wohnort!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 9, 1, 'Es war aber ein Mann aus (Gibea im) Stamme Benjamin namens Kis, ein Sohn Abiels, des Sohnes Zerors, des Sohnes Bechoraths, des Sohnes Aphiahs, ein Benjaminit, ein wohlhabender Mann;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 9, 2, 'der hatte einen Sohn namens Saul, von ungewöhnlicher Schönheit, so daß es unter den Israeliten keinen schöneren Mann gab; alle anderen im Volk überragte er um eines Hauptes Länge.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 9, 3, 'Als nun Kis, dem Vater Sauls, einst die Eselinnen sich verlaufen hatten, sagte Kis zu seinem Sohne Saul: »Nimm einen von den Knechten mit dir und mache dich auf den Weg, um die Eselinnen zu suchen!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 9, 4, 'Da durchwanderte er das ephraimitische Bergland und durchzog die Landschaft Salisa, ohne die Tiere zu finden; weiter zogen sie durch die Landschaft Saalim, aber sie waren nicht da; dann ging’s durch das Gebiet von Benjamin, aber sie fanden sie auch hier nicht.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 9, 5, 'Als sie endlich in der Landschaft Zuph angelangt waren, sagte Saul zu seinem Knecht, der bei ihm war: »Komm, wir wollen umkehren; sonst könnte sich mein Vater um uns statt um die Eselinnen Sorge machen.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 9, 6, 'Doch jener entgegnete ihm: »In der Stadt dort wohnt ja ein Gottesmann, ein hochangesehener Mann; alles, was er sagt, trifft sicher ein. Laß uns also dorthin gehen! Vielleicht gibt er uns Auskunft in unserer Sache, deretwegen wir unterwegs sind.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 9, 7, 'Saul erwiderte seinem Knechte: »Wenn wir wirklich hingingen, ja was wollten wir dem Manne zukommen lassen? Das Brot in unseren Ranzen ist ausgegangen, und wir haben kein Geschenk, das wir dem Gottesmanne bringen könnten; was hätten wir noch bei uns?«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 9, 8, 'Da antwortete der Knecht dem Saul noch einmal: »Ich habe hier noch einen Viertelschekel Silber bei mir; den magst du dem Gottesmanne schenken, damit er uns Auskunft in unserer Sache gibt.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 9, 9, '[Ehedem gebrauchte man in Israel, wenn man zur Befragung Gottes ging, die Redensart: »Kommt, laßt uns zum Seher gehen!«; denn einen Mann, den man heutzutage Prophet heißt, nannte man ehedem Seher.]');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 9, 10, 'Da antwortete Saul seinem Knecht: »Dein Vorschlag ist gut! Komm, wir wollen (zum Seher) hingehen!« Als sie nun nach der Stadt hingingen, wo der Gottesmann war,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 9, 11, 'und gerade den Aufgang zur Stadt hinanstiegen, begegneten ihnen junge Mädchen, die herauskamen, um Wasser zu holen. Diese fragten sie: »Ist der Seher hier anwesend?«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 9, 12, 'Sie antworteten ihnen: »Jawohl, er ist da gerade vor dir; eile nun hin, denn er ist eben heute in die Stadt gekommen, weil das Volk heute ein Opferfest auf der Höhe hält.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 9, 13, 'Wenn ihr in die Stadt kommt, werdet ihr ihn gerade noch treffen, bevor er auf die Höhe zum Essen hinaufgeht; denn die Festgesellschaft ißt nicht eher, als bis er gekommen ist; er muß nämlich das Opfermahl segnen: erst dann essen die Geladenen. Geht also hinauf, denn eben jetzt werdet ihr ihn treffen!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 9, 14, 'So gingen sie denn zur Stadt hinauf; und als sie gerade in das Innere der Stadt getreten waren, kam Samuel heraus, ihnen entgegen, um zur Anhöhe hinaufzugehen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 9, 15, 'Nun hatte aber der HERR am Tage zuvor, ehe Saul kam, dem Samuel folgende Offenbarung zukommen lassen:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 9, 16, '»Morgen um diese Stunde werde ich einen Mann aus dem Stamme Benjamin zu dir kommen lassen: den salbe zum Fürsten über mein Volk Israel; er soll mein Volk aus der Gewalt der Philister erretten; denn ich habe das Elend meines Volkes angesehen, weil sein Hilferuf zu mir gedrungen ist.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 9, 17, 'Sobald nun Samuel den Saul erblickte, tat der HERR ihm kund: »Dies ist der Mann, von dem ich dir gesagt habe, daß er über mein Volk herrschen solle!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 9, 18, 'Da trat Saul innerhalb des Torplatzes auf Samuel zu mit der Bitte: »Sage mir doch, wo hier die Wohnung des Sehers ist.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 9, 19, 'Samuel antwortete dem Saul: »Ich bin der Seher: steige vor mir her die Höhe hinauf! Denn ihr müßt heute mit mir essen; morgen früh will ich dich dann ziehen lassen und dir Auskunft über alles geben, was dir auf dem Herzen liegt.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 9, 20, 'Um die Eselinnen aber, die dir heute vor drei Tagen abhanden gekommen sind, brauchst du dir keine Gedanken zu machen; denn sie haben sich wiedergefunden. Und wem gehört alles, was es Wertvolles in Israel gibt? Doch wohl dir und deines Vaters ganzem Hause?«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 9, 21, 'Da entgegnete Saul: »Ich bin doch nur ein Benjaminit, aus einem der kleinsten Stämme Israels, und mein Geschlecht ist das geringste unter allen Geschlechtern des Stammes Benjamin: warum redest du da solche Worte zu mir?«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 9, 22, 'Samuel aber nahm Saul samt seinem Knecht mit sich, führte sie in die Halle und wies ihnen einen Platz an zuoberst der Gäste, deren ungefähr dreißig anwesend waren.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 9, 23, 'Hierauf sagte Samuel zu dem Koch: »Bringe das Stück her, das ich dir übergeben und von dem ich dir gesagt habe, du möchtest es beiseite legen.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 9, 24, 'Da brachte der Koch die Keule mit dem Nierenstück herbei, Samuel aber setzte sie dem Saul vor und sagte: »Siehe, dies Ehrenstück ist für dich aufgehoben! Lege es dir vor und iß! Denn bis zur bestimmten Zeit ist es für dich aufbewahrt worden, schon als ich sagte, ich hätte die Gäste geladen.« So aß denn Saul mit Samuel an jenem Tage.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 9, 25, 'Als sie dann von der Anhöhe zur Stadt hinuntergegangen waren, bereitete man dem Saul das Lager auf dem Dach;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 9, 26, 'und er legte sich schlafen. Als dann die Morgenröte aufging, rief Samuel aufs Dach hinauf dem Saul die Worte zu: »Stehe auf! Ich will dich geleiten.« Da stand Saul auf, und sie gingen beide, er und Samuel, hinaus auf die Straße.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 9, 27, 'Während sie nun ans Ende der Stadt hinuntergingen, sagte Samuel zu Saul: »Laß den Knecht uns vorausgehen! Du selbst aber bleibe jetzt hier stehen: ich will dir ein Gotteswort kundtun!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 10, 1, 'Hierauf nahm Samuel die Ölflasche und goß sie ihm aufs Haupt, küßte ihn dann und sagte: »Hiermit hat der HERR dich zum Fürsten über sein Eigentumsvolk Israel gesalbt!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 10, 2, '»Wenn du jetzt von mir weggehst, wirst du beim Grabe der Rahel an der Grenze von Benjamin, in Zelzah, zwei Männer treffen, die zu dir sagen werden: ›Die Eselinnen, zu deren Aufsuchung du ausgezogen bist, haben sich wiedergefunden; dein Vater denkt jetzt nicht mehr an den Vorfall mit den Eselinnen, macht sich aber um euch Sorge und sagt: Was soll ich wegen meines Sohnes tun?‹');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 10, 3, 'Wenn du dann von dort weiterwanderst und zum Terebinthenhain von Thabor gekommen bist, so werden dir dort drei Männer begegnen, die zum Heiligtum Gottes nach Bethel hinaufgehen; der eine trägt drei Böckchen, der andere drei Laibe Brot und der dritte einen Schlauch Wein.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 10, 4, 'Sie werden dich begrüßen und dir zwei Brote anbieten, die du von ihnen annehmen sollst.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 10, 5, 'Hierauf wirst du nach Gibea-Elohim kommen, wo die Säule der Philister steht, und beim Eintritt in den Ort wirst du dort einer Schar Propheten begegnen, die von der Höhe herabkommen, und vor ihnen her erschallt Musik von Harfen, Pauken, Flöten und Zithern, während sie selbst sich in prophetischer Begeisterung befinden.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 10, 6, 'Da wird dann der Geist des HERRN auch über dich kommen, so daß du mit ihnen in Begeisterung gerätst und in einen anderen Menschen verwandelt wirst.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 10, 7, 'Wenn nun diese Zeichen bei dir eingetroffen sind, so tu, wozu du dich gerade getrieben fühlst, denn Gott ist mit dir!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 10, 8, 'Gehe vor mir nach Gilgal hinab; ich werde alsdann zu dir dorthin kommen, um Brandopfer darzubringen und Heilsopfer zu schlachten. Sieben Tage sollst du dort warten, bis ich zu dir komme und dir mitteile, was du zu tun hast.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 10, 9, 'Sobald nun Saul den Rücken gewandt hatte, um von Samuel wegzugehen, da verwandelte ihm Gott sein Herz; und alle diese Zeichen trafen an jenem Tage ein.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 10, 10, 'Denn als sie dorthin, nach Gibea, kamen und ihm die Prophetenschar begegnete, da kam plötzlich der Geist Gottes über ihn, so daß er mitten unter ihnen in prophetische Begeisterung geriet.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 10, 11, 'Als nun alle, die ihn von früher her kannten, sahen, wie er sich gleich den anderen als Prophet gebärdete, fragten die Leute sich untereinander: »Was ist denn mit dem Sohn des Kis vorgegangen? Gehört denn Saul auch zu den Propheten?«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 10, 12, 'Da antwortete ein Mann von dort: »Aber wer ist denn deren Vater?« Daher rührt das Sprichwort: »Gehört Saul auch zu den Propheten?«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 10, 13, 'Als dann seine prophetische Begeisterung vorüber war und er nach Hause gekommen war,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 10, 14, 'fragte sein Vetter ihn und seinen Knecht: »Wohin seid ihr gegangen?« Er antwortete: »Wir wollten die Eselinnen suchen, und als wir sahen, daß sie nirgends zu finden waren, sind wir zu Samuel gegangen.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 10, 15, 'Da bat ihn sein Vetter: »Teile mir doch mit, was Samuel euch gesagt hat!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 10, 16, 'Da erwiderte Saul seinem Vetter: »Nun, er hat uns mitgeteilt, daß die Eselinnen sich wiedergefunden hätten.« Was ihm aber Samuel in betreff des Königtums gesagt hatte, davon verriet er ihm nichts.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 10, 17, 'Hierauf berief Samuel das Volk zum (Heiligtum des) HERRN nach Mizpa');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 10, 18, 'und sagte zu den Israeliten: »So hat der HERR, der Gott Israels, gesprochen: ›Ich bin’s, der Israel aus Ägypten heraufgeführt und euch aus der Hand der Ägypter und aus der Gewalt aller Königreiche, die euch bedrängten, errettet hat.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 10, 19, 'Ihr aber habt jetzt euren Gott verworfen, der euch aus allen euren Nöten und Bedrängnissen errettet hat, und habt zu ihm gesagt: ›Nein, einen König sollst du über uns einsetzen!‹ Nun denn, so stellt euch vor dem HERRN nach euren Stämmen und nach euren Tausendschaften auf!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 10, 20, 'Als dann Samuel alle Stämme Israels hatte antreten lassen, wurde der Stamm Benjamin durchs Los getroffen;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 10, 21, 'und als er den Stamm Benjamin nach seinen Geschlechtern antreten ließ, wurde das Geschlecht der Matriten und aus diesem Saul, der Sohn des Kis, getroffen; als man aber nach ihm suchte, war er nicht zu finden.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 10, 22, 'Da fragte man nochmals beim HERRN an: »Ist der Mann überhaupt hergekommen?« Der HERR antwortete: »Jawohl, er hält sich beim Gepäck versteckt.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 10, 23, 'Da eilte man hin und holte ihn von dort; und als er dann mitten unter das Volk trat, überragte er alle anderen um eines Hauptes Länge.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 10, 24, 'Da sagte Samuel zu dem ganzen Volk: »Seht ihr wohl, wen der HERR sich erwählt hat? Diesem kommt keiner im ganzen Volke gleich!« Da erhob das ganze Volk ein Jubelgeschrei und rief: »Es lebe der König!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 10, 25, 'Darauf brachte Samuel die Rechte des Königtums zur Kenntnis des Volkes und trug sie in ein Buch ein, das er vor den HERRN niederlegte; danach entließ Samuel das ganze Volk, einen jeden in seine Heimat.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 10, 26, 'Auch Saul kehrte in seinen Wohnort nach Gibea zurück, und eine Kriegerschar der Tapferen, denen Gott das Herz gerührt hatte, gab ihm das Geleit.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 10, 27, 'Einige nichtswürdige Leute aber sagten: »Was wird der uns helfen können?« So verachteten sie ihn und ließen ihm kein Huldigungsgeschenk zukommen; doch er tat, als merkte er es nicht.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 11, 1, '(Nach ungefähr einem Monat aber) zog der Ammoniter Nahas heran und belagerte Jabes in Gilead. Da ließ die gesamte Bürgerschaft von Jabes dem Nahas sagen: »Schließe einen Vertrag mit uns, so wollen wir uns dir unterwerfen.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 11, 2, 'Aber der Ammoniter Nahas antwortete ihnen: »Nur unter der Bedingung will ich einen Vertrag mit euch schließen, daß ich jedem von euch das rechte Auge aussteche und dadurch ganz Israel beschimpfe.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 11, 3, 'Da ließen ihm die Ältesten von Jabes sagen: »Gewähre uns eine Frist von sieben Tagen, damit wir Boten in alle Teile Israels senden! Wenn dann niemand uns Hilfe leistet, so wollen wir uns dir ergeben.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 11, 4, 'Als nun die Boten nach Gibea kamen, wo Saul wohnte, und ihr Anliegen dem Volke vortrugen, brachen alle Leute in lautes Weinen aus.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 11, 5, 'Saul aber kam gerade hinter den Rindern her vom Felde heim und fragte: »Was hat das Volk, daß es weint?« Als man ihm dann mitteilte, was die Männer von Jabes berichtet hatten,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 11, 6, 'kam beim Vernehmen dieser Nachricht der Geist Gottes über ihn, und er geriet in heftigen Zorn.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 11, 7, 'Er nahm also ein Paar Rinder, zerstückte sie, sandte die Stücke durch Boten in alle Teile Israels und ließ bekanntmachen: »Wer nicht mit auszieht hinter Saul und Samuel her, dessen Rindern soll es ebenso ergehen!« Da fiel ein heiliger Schrecken auf das Volk, so daß sie auszogen wie ein Mann;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 11, 8, 'und als er sie bei Besek musterte, waren es 300000 Israeliten und 30000 Mann vom Stamme Juda.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 11, 9, 'Man sagte nun zu den Boten, die gekommen waren: »Meldet den Einwohnern von Jabes in Gilead folgendes: ›Morgen, wenn die Sonne heiß scheint, wird euch Hilfe werden!‹« Als nun die Boten bei ihrer Heimkehr dieses den Bürgern von Jabes berichteten, freuten diese sich');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 11, 10, 'und ließen den Ammonitern sagen: »Morgen wollen wir zu euch hinausziehen; dann mögt ihr mit uns verfahren, wie es euch beliebt!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 11, 11, 'Als Saul dann am andern Morgen seine Mannschaft in drei Heerhaufen geteilt hatte und diese in das feindliche Lager zur Zeit der Morgenwache eindrangen, richteten sie ein Blutbad unter den Ammonitern an, bis der Tag am heißesten wurde; und die Übriggebliebenen wurden so zersprengt, daß nicht zwei von ihnen beisammen blieben.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 11, 12, 'Da sagte das Volk zu Samuel: »Wer sind die, welche gesagt haben: ›Saul sollte König über uns sein?‹ Her mit diesen Männern, daß wir sie totschlagen!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 11, 13, 'Saul aber entgegnete: »Niemand soll heute den Tod erleiden, denn heute hat der HERR dem Volke Israel Rettung geschafft!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 11, 14, 'Samuel aber forderte das Volk auf: »Kommt, laßt uns nach Gilgal ziehen und dort das Königtum bestätigen!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 11, 15, 'Da zog das gesamte Volk nach Gilgal und setzte dort Saul vor dem HERRN in Gilgal zum König ein. Man schlachtete dort Heilsopfer vor dem HERRN, und Saul samt allen Israeliten feierten dort ein großes Freudenfest.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 12, 1, 'Darauf sagte Samuel zu ganz Israel: »Seht, ich bin in allem, was ihr mir vorgetragen habt, eurem Wunsche nachgekommen und habe einen König über euch eingesetzt.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 12, 2, 'So wird denn nunmehr der König an eurer Spitze einhergehen. Ich aber bin alt und grau geworden, so daß nun meine Söhne unter euch sind. Ich habe aber meinen Wandel von meiner Jugend an bis auf den heutigen Tag vor euren Augen geführt.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 12, 3, 'Hier stehe ich: tretet vor dem HERRN und seinem Gesalbten gegen mich auf! Wem habe ich seinen Ochsen, wem seinen Esel weggenommen? Wen habe ich übervorteilt, wem Gewalt angetan? Oder von wem habe ich ein Geschenk angenommen, daß ich mir dadurch die Augen hätte blenden lassen? – so will ich es euch zurückerstatten!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 12, 4, 'Da antworteten sie: »Du hast uns nicht übervorteilt und uns keine Gewalt angetan, hast auch von niemand irgend etwas angenommen.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 12, 5, 'Darauf fuhr er fort: »Der HERR ist heute mein Zeuge euch gegenüber, und ebenso ist auch sein Gesalbter Zeuge, daß ihr gar nichts (von unrechtem Gut) in meinem Besitz gefunden habt.« Sie riefen: »Ja, er ist Zeuge!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 12, 6, 'Hierauf sagte Samuel weiter zum Volke: »Ja, Zeuge ist der HERR, der Mose und Aaron geschaffen und der eure Väter aus dem Lande Ägypten hergeführt hat!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 12, 7, 'Jetzt aber tretet her, damit ich euch vor dem HERRN ins Gewissen rede und euch alle Wohltaten vorhalte, die der HERR euch und euren Vätern erwiesen hat!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 12, 8, 'Als Jakob nach Ägypten gekommen war und eure Väter zum HERRN um Hilfe schrien, da sandte der HERR Mose und Aaron, damit sie eure Väter aus Ägypten wegführten und ihnen Wohnsitze in diesem Lande gäben.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 12, 9, 'Als sie (eure Väter) aber den HERRN, ihren Gott, vergaßen, ließ er sie in die Gewalt Siseras, des Heerführers (des Königs Jabin) von Hazor, fallen und in die Gewalt der Philister und in die Gewalt des Königs der Moabiter; die fingen Kriege mit ihnen an.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 12, 10, 'Als sie nun zum HERRN um Hilfe schrien und bekannten: ›Wir haben gesündigt, daß wir den HERRN verlassen und den Baalen und Astarten gedient haben! Jetzt aber errette uns aus der Gewalt unserer Feinde, so wollen wir dir dienen!« –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 12, 11, 'da sandte der HERR Jerubbaal und Barak, Jephthah und Samuel und errettete euch aus der Gewalt eurer Feinde ringsum, so daß ihr in Sicherheit wohnen konntet.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 12, 12, '»Als ihr aber saht, daß Nahas, der König der Ammoniter, gegen euch heranrückte, da sagtet ihr zu mir: ›Nein, ein König soll über uns herrschen!‹, während doch der HERR, euer Gott, euer König ist.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 12, 13, 'Nun denn – da ist der König, den ihr erwählt, den ihr verlangt habt; ja, der HERR hat nun einen König über euch eingesetzt.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 12, 14, 'Werdet ihr nun den HERRN fürchten und ihm dienen, seinen Weisungen gehorchen und euch gegen die Befehle des HERRN nicht auflehnen, sondern ihr beide, sowohl ihr selbst als auch der König, der über euch herrscht, dem HERRN, eurem Gott, folgsam sein?');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 12, 15, 'Wenn ihr aber den Weisungen des HERRN nicht gehorcht, sondern euch gegen die Befehle des HERRN auflehnt, so wird die Hand des HERRN gegen euch sein, wie sie vormals gegen eure Väter gewesen ist.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 12, 16, 'Jetzt aber tretet her und achtet auf das große Ereignis, das der HERR vor euren Augen wird geschehen lassen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 12, 17, 'Es ist jetzt doch die Zeit der Weizenernte; ich will aber den HERRN anrufen, er möge Donnerschläge und Regen kommen lassen; dann werdet ihr erkennen und einsehen, ein wie großes Unrecht ihr vor den Augen des HERRN begangen habt, indem ihr einen König für euch verlangtet!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 12, 18, 'Als dann Samuel den HERRN anrief, ließ dieser an jenem Tage Donner und Regen kommen, so daß das ganze Volk in große Furcht vor dem HERRN und vor Samuel geriet.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 12, 19, 'Da richtete das ganze Volk die Aufforderung an Samuel: »Lege Fürbitte für deine Knechte bei dem HERRN, deinem Gott, ein, daß wir nicht zu sterben brauchen, weil wir zu allen unsern Sünden auch noch das Unrecht hinzugefügt haben, einen König für uns zu verlangen!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 12, 20, 'Samuel aber erwiderte dem Volke: »Fürchtet euch nicht! Ihr habt zwar all dieses Unrecht begangen; aber weicht nur nicht vom Gehorsam gegen den HERRN ab, sondern dient dem HERRN mit eurem ganzen Herzen');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 12, 21, 'und fallt nicht von ihm ab, daß ihr den Götzen nachgeht, die nicht helfen und nicht erretten können, weil sie ja nichts sind.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 12, 22, 'Der HERR dagegen wird um seines großen Namens willen sein Volk nicht verstoßen, weil es dem HERRN gefallen hat, euch zu seinem Volke zu machen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 12, 23, 'Auch von mir sei es fern, mich am HERRN zu versündigen, daß ich davon ablassen sollte, Fürbitte für euch einzulegen! Nein, ich will euch den guten und rechten Weg lehren.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 12, 24, 'Nur fürchtet den HERRN und dient ihm aufrichtig mit eurem ganzen Herzen; denn beachtet wohl, was er Großes an euch getan hat!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 12, 25, 'Wenn ihr aber dennoch böse handelt, so werdet ihr samt eurem König hinweggerafft werden.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 13, 1, 'Saul war ... Jahre alt, als er König wurde, und herrschte ... Jahre über Israel.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 13, 2, 'Er wählte sich dreitausend Mann aus Israel aus, von denen sich zweitausend bei ihm zu Michmas und im Gebirge von Bethel befanden, während tausend Mann unter Jonathan zu Gibea im Stamme Benjamin standen; das übrige Kriegsvolk hatte er entlassen, einen jeden zu seinen Zelten.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 13, 3, 'Da zertrümmerte Jonathan die Säule der Philister, die in Gibea stand. Das kam zur Kenntnis der Philister; Saul aber ließ die Posaune im ganzen Lande erschallen und sagte: »Die Hebräer sollen es hören!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 13, 4, 'Als nun ganz Israel die Kunde vernahm, Saul habe die Säule der Philister zertrümmert und Israel habe dadurch die Philister tödlich beleidigt, da wurde das Volk aufgeboten, dem Saul nach Gilgal zu folgen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 13, 5, 'Die Philister aber sammelten sich zum Kampf mit Israel: dreitausend Kriegswagen und sechstausend Reiter und Fußvolk so zahlreich wie der Sand am Ufer des Meeres; die zogen herauf und lagerten bei Michmas östlich von Beth-Awen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 13, 6, 'Als nun die Mannschaft der Israeliten sah, daß sie sich in einer schlimmen Lage und in arger Bedrängnis befand, versteckten sich die Leute in den Höhlen und Dickichten, in den Felsspalten, Gräbern und Zisternen;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 13, 7, 'manche begaben sich sogar (über die Jordanfurten) ins Land der Gaditen und nach Gilead. Saul aber befand sich immer noch in Gilgal, und das ganze Kriegsvolk folgte ihm zitternd.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 13, 8, 'Er wartete nun sieben Tage bis zu der von Samuel bestimmten Zeit; als Samuel aber nicht nach Gilgal kam und seine Leute ihn verließen und sich zerstreuten,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 13, 9, 'befahl Saul: »Bringt mir (die Tiere für) das Brandopfer und die Heilsopfer her!« Und er vollzog das Brandopfer.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 13, 10, 'Kaum war er aber mit der Darbringung des Brandopfers fertig, als Samuel erschien. Saul ging hinaus ihm entgegen, um ihn zu begrüßen;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 13, 11, 'Samuel aber fragte: »Was hast du getan?« Saul antwortete: »Weil ich sah, daß das Kriegsvolk mich verließ und sich zerstreute und du zur bestimmten Zeit nicht kamst, die Philister aber sich schon bei Michmas gesammelt haben,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 13, 12, 'da dachte ich: ›Jetzt werden die Philister gegen mich nach Gilgal herabziehen, ehe ich noch die Huld des HERRN für mich gewonnen habe‹; da habe ich mir denn ein Herz gefaßt und das Brandopfer dargebracht.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 13, 13, 'Da sagte Samuel zu Saul: »Du hast töricht gehandelt, daß du das Gebot, das der HERR, dein Gott, dir gegeben hat, nicht beobachtet hast, sonst hätte der HERR jetzt dein Königtum über Israel für immer bestätigt;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 13, 14, 'nun aber wird dein Königtum keinen Bestand haben. Der HERR hat sich einen Mann nach seinem Herzen gesucht, und der HERR hat ihn zum Fürsten über sein Volk bestellt; denn du hast nicht befolgt, was der HERR dir geboten hatte.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 13, 15, 'Hierauf machte Samuel sich auf, verließ Gilgal und ging seines Weges; der Rest des Heeres aber folgte dem Saul von Gilgal nach Gibea im Stamme Benjamin; dort musterte Saul das Kriegsvolk, das sich noch bei ihm befand, etwa sechshundert Mann,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 13, 16, 'und verblieb mit seinem Sohne Jonathan und der ihm zur Verfügung stehenden Mannschaft zu Geba im Stamme Benjamin, während die Philister sich bei Michmas gelagert hatten.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 13, 17, 'Da zog die plündernde Schar aus dem Lager der Philister in drei Abteilungen aus: die eine Abteilung wandte sich in der Richtung gegen Ophra in die Landschaft Sual,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 13, 18, 'die zweite Abteilung zog in der Richtung gegen Beth-Horon, und die dritte Abteilung schlug die Richtung nach dem Hügel ein, der über die Hyänenschlucht emporragt, nach der Wüste hin.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 13, 19, 'Es war aber kein Schmied im ganzen Lande Israel zu finden; denn die Philister hatten gedacht: »Die Hebräer sollen sich keine Schwerter und Spieße anfertigen dürfen!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 13, 20, 'Daher mußten alle Israeliten zu den Philistern hinabgehen, sooft jemand seine Pflugschar oder Hacke, seine Axt oder seine Sichel zu schärfen hatte');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 13, 21, 'und sooft die Schneiden an den Pflugscharen oder an den Spaten und Hacken und Äxten stumpf geworden waren und um die Ochsenstecken gerade zu richten.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 13, 22, 'So kam es denn, daß beim Ausbruch des Krieges kein Schwert und kein Spieß in der Hand des ganzen Kriegsvolks, das Saul und Jonathan bei sich hatten, zu finden war; nur Saul und sein Sohn Jonathan besaßen Waffen. –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 13, 23, 'Ein Posten der Philister aber war nach dem Paß von Michmas vorgerückt.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 1, 'Eines Tages nun sagte Jonathan, der Sohn Sauls, zu dem Burschen, der sein Waffenträger war: »Komm, wir wollen auf den Vorposten der Philister losgehen, der dort drüben steht!« Seinem Vater aber sagte er nichts davon;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 2, 'denn Saul befand sich gerade an der Grenze von Gibea unter dem Granatbaume, der bei Migron steht; und die Leute, die er bei sich hatte, machten ungefähr 600 Mann aus,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 3, 'und Ahia, der Sohn Ahitubs, des Bruders Ikabods, des Sohnes des Pinehas, des Sohnes Elis, des Priesters des HERRN zu Silo, trug damals das priesterliche Schulterkleid; auch das Kriegsvolk wußte nichts davon, daß Jonathan weggegangen war.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 4, 'Es lag aber an der Übergangsstelle, durch welche Jonathan an den Posten der Philister heranzukommen suchte, eine Felsspitze diesseits und eine Felsspitze jenseits; die eine hieß Bozez, die andere Sene.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 5, 'Die eine Felsspitze fiel steil nach Norden ab gegen Michmas, die andere nach Süden zu gegen Geba.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 6, 'Jonathan sagte also zu seinem Waffenträger: »Komm, wir wollen auf den Posten dieser Heiden drüben losgehen; vielleicht läßt der HERR uns etwas ausrichten; denn für den HERRN gibt es kein Hindernis, durch viele oder durch wenige (Leute) zu retten.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 7, 'Da antwortete ihm sein Waffenträger: »Mache es ganz so, wie du es beabsichtigst; ich bin mit allem einverstanden und zu allem bereit.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 8, 'Jonathan fuhr fort: »Gut! Wir gehen hinüber auf die Leute los und wollen uns ihnen zeigen;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 9, 'wenn sie uns dann zurufen: ›Steht still, bis wir zu euch hinkommen!‹, so wollen wir auf unserem Platze stehenbleiben und nicht zu ihnen hinaufsteigen;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 10, 'wenn sie uns aber so zurufen: ›Kommt nur zu uns herauf!‹, so wollen wir zu ihnen hinaufsteigen; denn dann hat der HERR sie in unsere Hand gegeben: dies soll uns als Zeichen dienen!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 11, 'Als nun die beiden dem Posten der Philister sichtbar wurden, sagten die Philister: »Seht, da kommen ja Hebräer aus den Löchern hervor, in die sie sich verkrochen haben!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 12, 'Hierauf riefen die Mannschaften, die dort auf Posten standen, dem Jonathan und seinem Waffenträger zu: »Kommt nur herauf zu uns! Wir wollen euch einen Denkzettel geben!« Da sagte Jonathan zu seinem Waffenträger: »Steige mir nach, denn der HERR hat sie in die Hand Israels gegeben!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 13, 'So kletterte denn Jonathan auf Händen und Füßen hinan und sein Waffenträger hinter ihm her. (Jene wollten sich zur Flucht vor Jonathan wenden, aber er hieb sie nieder), und sein Waffenträger tötete sie vollends hinter ihm her.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 14, 'So belief sich das erste Blutbad, das Jonathan mit seinem Waffenträger anrichtete, auf ungefähr zwanzig Mann, auf einer Strecke nicht größer als eine halbe Hufe Ackers.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 15, 'Da entstand ein Schrecken im Lager auf dem Felde und unter dem ganzen Kriegsvolk; auch die auf Posten Stehenden und die Plünderschar gerieten in Bestürzung; dazu bebte die Erde, und das rief einen Gottesschrecken hervor.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 16, 'Als nun die Späher Sauls, die sich zu Gibea im Stamm Benjamin befanden, ausschauten, da sahen sie, wie die Menge hin und her wogte.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 17, 'Nun befahl Saul den Leuten, die bei ihm waren: »Nehmt eine Musterung vor und seht zu, wer von uns weggegangen ist!« Als man nun die Musterung vornahm, stellte es sich heraus, daß Jonathan und sein Waffenträger fehlten.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 18, 'Da befahl Saul dem Ahia: »Bringe die Lade Gottes her!« Denn die Lade Gottes befand sich damals bei den Israeliten.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 19, 'Während aber Saul noch mit dem Priester redete, wurde das Getümmel im Lager der Philister immer größer; daher befahl Saul dem Priester: »Laß es sein!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 20, 'Darauf trat Saul mit der ganzen Mannschaft, die bei ihm war, zum Kampf an; doch als sie an das feindliche Lager kamen, fanden sie das Schwert des einen gegen den andern gekehrt, und es herrschte eine heillose Verwirrung.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 21, 'Auch die Hebräer, die es seit längerer Zeit mit den Philistern gehalten hatten und mit ihnen ins Feld gezogen waren, auch diese fielen jetzt ab, um sich den Israeliten unter Saul und Jonathan anzuschließen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 22, 'Als ferner alle Israeliten, die sich im Gebirge Ephraim versteckt hielten, von der Flucht der Philister hörten, setzten sie ihnen gleichfalls nach, um sie zu bekämpfen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 23, 'So verlieh der HERR den Israeliten an jenem Tage den Sieg. Als aber der Kampf sich bis über Beth-Awen hin ausbreitete,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 24, 'wurde die Mannschaft der Israeliten im Laufe jenes Tages sehr müde. Saul hatte nämlich seine Leute durch folgenden Fluch gebunden: »Verflucht ist jeder, der bis zum Abend etwas genießt, bis ich Rache an meinen Feinden genommen habe!« So nahm denn auch keiner von den Leuten Nahrung zu sich.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 25, 'Nun hatte sich damals die ganze Gegend mit Bienenwirtschaft befaßt, und die Bienenstöcke befanden sich auf freiem Felde.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 26, 'Als nun das Kriegsvolk zu den Stöcken kam, da flossen sie von Honig über; aber niemand führte seine Hand zum Munde, weil die Leute sich vor dem Fluch scheuten.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 27, 'Da Jonathan es aber nicht gehört hatte, als sein Vater das Kriegsvolk beschwor, streckte er seinen Stab aus, den er in der Hand hatte, tauchte seine Spitze in den Honigseim und führte seine Hand zum Munde: da wurden seine Augen leuchtend.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 28, 'Einer von den Mannschaften aber teilte ihm mit: »Dein Vater hat das Heer durch folgenden feierlichen Fluch gebunden: ›Verflucht ist jeder, der heute etwas genießt!‹« Das Heer war aber todmüde,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 29, 'und Jonathan antwortete: »Mein Vater stürzt das Land ins Unglück! Seht doch, wie leuchtend meine Augen geworden sind, weil ich ein wenig von diesem Honig genossen habe!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 30, 'Was wäre es erst gewesen, wenn die Leute von der feindlichen Beute, die sie vorgefunden haben, gehörig hätten essen dürfen! So aber ist die Niederlage unter den Philistern nicht groß geworden«.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 31, 'Sie hatten aber an jenem Tage ein Blutbad unter den Philistern von Michmas bis nach Ajjalon angerichtet, obgleich das Kriegsvolk sehr ermattet war.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 32, '(Am Abend) aber fielen die Leute über die Beute her, nahmen Kleinvieh, Rinder und Kälber und schlachteten sie zur Erde hin, und die Leute aßen das Fleisch samt dem Blut.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 33, 'Als man nun dem Saul meldete: »Die Leute versündigen sich ja gegen den HERRN, indem sie das Fleisch samt dem Blut essen«, rief er aus: »Ihr handelt gottlos! Wälzt mir einen großen Stein hierher!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 34, 'Dann befahl Saul: »Zerstreut euch unter die Leute und macht ihnen bekannt: ›Bringt ein jeder sein Rind und ein jeder sein Stück Kleinvieh zu mir her und schlachtet die Tiere hier und eßt dann erst! Sonst versündigt ihr euch gegen den HERRN, indem ihr das Fleisch samt dem Blute genießt.‹« So brachte denn jeder von den Leuten das Stück Vieh, das in seinem Besitz war, an jenem Abend herbei und schlachtete es dort.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 35, 'Dann baute Saul dem HERRN einen Altar; dies war der erste Altar, den er dem HERRN erbaute.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 36, 'Hierauf sagte Saul: »Laßt uns noch in der Nacht hinabziehen hinter den Philistern her, damit wir bis Tagesanbruch Beute unter ihnen machen und keinen von ihnen übriglassen!« Sie antworteten: »Tu ganz, wie es dir gut scheint!« Der Priester aber sagte: »Laßt uns zuerst hier vor Gott treten!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 37, 'Als nun Saul bei Gott anfragte: »Soll ich zur Verfolgung der Philister hinabziehen? Wirst du sie in die Hand Israels geben?«, erteilte ihm der HERR an jenem Tage keine Antwort.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 38, 'Da befahl Saul: »Tretet hierher, ihr Anführer des Heeres alle, und untersucht sorgfältig, durch wen diese Versündigung heute begangen worden ist!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 39, 'Denn so wahr der HERR lebt, der Israel den Sieg verliehen hat: selbst wenn die Schuld sich bei meinem Sohne Jonathan fände, so müßte er unfehlbar sterben!« Aber keiner von allen Leuten gab ihm eine Antwort.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 40, 'Hierauf befahl er dem gesamten Israel: »Ihr sollt auf der einen Seite stehen, ich aber und mein Sohn Jonathan wollen die andere Seite bilden.« Das Heer antwortete ihm: »Tu, was dir gut dünkt.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 41, 'Dann betete Saul zum HERRN: »Gott Israels, laß die Wahrheit zutage treten!« Da wurden Jonathan und Saul getroffen, das Heer aber ging frei aus.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 42, 'Darauf befahl Saul: »Werft das Los zwischen mir und meinem Sohne Jonathan!« Da wurde Jonathan getroffen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 43, 'Nun sagte Saul zu Jonathan: »Bekenne mir, was du getan hast!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 44, 'Da bekannte ihm Jonathan: »Ich habe nur ein wenig Honig mit der Spitze des Stabes gekostet, den ich in meiner Hand hatte: dafür soll ich jetzt sterben?« Saul erwiderte: »Gott tue mir jetzt und künftig an, was er will: ja, Jonathan, du mußt unbedingt sterben!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 45, 'Aber das Heer erklärte dem Saul: »Jonathan soll sterben, der diesen großen Sieg in Israel errungen hat? Das sei fern! So wahr der HERR lebt: kein Haar soll von seinem Haupt auf die Erde fallen! Denn mit Gott im Bunde hat er den Sieg heute errungen!« So machte das Heer den Jonathan frei, daß er nicht zu sterben brauchte.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 46, 'Hierauf stand Saul von der Verfolgung der Philister ab und zog heim, während die Philister in ihr Land zurückkehrten.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 47, 'Nachdem Saul das Königtum über Israel übernommen hatte, führte er Kriege gegen alle seine Feinde ringsum: gegen die Moabiter, die Ammoniter und die Edomiter, gegen die Könige von Zoba und gegen die Philister, und überall, wohin er sich wandte, war er siegreich.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 48, 'Er bewies sich als tapferen Mann, besiegte die Amalekiter und befreite Israel von denen, die es (bis dahin) ausgeplündert hatten. –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 49, 'Die Söhne Sauls waren: Jonathan, Jiswi und Malkisua; und von seinen zwei Töchtern hieß die ältere Merab und die jüngere Michal.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 50, 'Sauls Gattin hieß Ahinoam, sie war die Tochter des Ahimaaz; sein Heerführer hieß Abner und war der Sohn Ners, des Oheims Sauls;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 51, 'denn Kis, der Vater Sauls, und Ner, der Vater Abners, waren beide Söhne Abiels. –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 52, 'Mit den Philistern aber hatte Saul schwere Kämpfe zu bestehen, solange er lebte; wenn Saul daher irgendwo einen tapferen und kriegstüchtigen Mann sah, nahm er ihn in seine Dienste.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 15, 1, 'Samuel aber sagte zu Saul: »Mich hat der HERR (einst) gesandt, dich zum König über sein Volk Israel zu salben; so gehorche nun dem bestimmten Befehl des HERRN!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 15, 2, 'So hat Gott, der HERR der Heerscharen, gesprochen: ›Ich will das Unrecht ahnden, das die Amalekiter einst den Israeliten zugefügt haben, indem sie ihnen beim Auszug aus Ägypten den Weg verlegten.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 15, 3, 'Darum ziehe jetzt hin, schlage die Amalekiter und vollstrecke den Bann an ihnen und an allem, was sie besitzen! Übe keine Schonung an ihnen, sondern laß alles sterben, Männer wie Weiber, Kinder wie Säuglinge, Rinder wie Kleinvieh, Kamele wie Esel!‹«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 15, 4, 'Da bot Saul das Volk auf und musterte es in Telaim: 200000 Mann Fußvolk und 10000 Mann aus Juda.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 15, 5, 'Nachdem Saul dann vor die Hauptstadt der Amalekiter gerückt war, legte er einen Hinterhalt im Bachtal;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 15, 6, 'den Kenitern aber ließ er sagen: »Auf! Zieht euch zurück und entfernt euch aus der Mitte der Amalekiter, damit ich euch nicht zugleich mit ihnen vernichte! Denn ihr habt allen Israeliten bei ihrem Auszuge aus Ägypten Freundschaft erwiesen.« Da zogen die Keniter aus dem Gebiet der Amalekiter weg.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 15, 7, 'Hierauf besiegte Saul die Amalekiter (und richtete ein Blutbad unter ihnen an) von Hawila bis nach Sur, das östlich von Ägypten liegt.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 15, 8, 'Agag, den König der Amalekiter, nahm er lebendig gefangen und vollstreckte den Bann an dem ganzen Volk mit der Schärfe des Schwertes;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 15, 9, 'doch verschonte Saul und seine Leute den Agag und die besten Stücke des Kleinviehs und der Rinder, die feisten Tiere und die Lämmer und überhaupt alles Wertvolle, und sie wollten den Bann an ihnen nicht vollstrecken; nur was vom Vieh gering (und wertlos) war, an dem vollstreckten sie den Bann.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 15, 10, 'Da erging das Wort des HERRN an Samuel also:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 15, 11, '»Es reut mich, daß ich Saul zum König gemacht habe; denn er hat sich vom Gehorsam gegen mich abgewandt und meine Befehle nicht ausgerichtet.« Darüber geriet Samuel in schmerzliche Aufregung, so daß er die ganze Nacht hindurch zum HERRN schrie.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 15, 12, 'Am folgenden Morgen früh aber machte Samuel sich auf, um Saul entgegenzugehen; da wurde ihm die Botschaft gebracht, Saul habe sich nach Karmel begeben und sich dort ein Denkmal errichtet, sei dann aber umgekehrt und weiter nach Gilgal hinabgezogen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 15, 13, 'Als nun Samuel zu Saul kam, sagte Saul zu ihm: »Gesegnet seist du vom HERRN! Ich habe den Befehl des HERRN ausgeführt.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 15, 14, 'Da antwortete Samuel: »Was ist denn das für ein Blöken von Kleinvieh, das an meine Ohren dringt, und ein Gebrüll von Rindern, das ich höre?«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 15, 15, 'Saul erwiderte: »Von den Amalekitern haben unsere Leute sie mitgebracht, weil sie die besten Stücke von dem Kleinvieh und den Rindern verschont haben, um sie dem HERRN, deinem Gott, zu opfern; aber an dem Übrigen haben wir den Bann vollstreckt.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 15, 16, 'Da entgegnete Samuel dem Saul: »Halt ein! Ich will dir mitteilen, was der HERR in dieser Nacht zu mir gesagt hat.« Jener erwiderte ihm: »Rede!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 15, 17, 'Da sagte Samuel: »Nicht wahr? Obgleich du dir selbst klein vorkamst, bist du doch das Haupt der Stämme Israels geworden; denn der HERR hat dich zum König über Israel gesalbt.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 15, 18, 'Nun hat der HERR dich zu einem Kriegszuge ausgesandt und dir geboten: ›Ziehe hin, vollstrecke den Bann an den Frevlern, den Amalekitern, und bekriege sie, bis du sie vernichtet hast!‹');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 15, 19, 'Warum bist du nun der Weisung des HERRN nicht nachgekommen, sondern hast dich über die Beute hergemacht und das getan, was dem HERRN mißfällt?«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 15, 20, 'Saul antwortete dem Samuel: »Ich bin ja doch der Weisung des HERRN nachgekommen und habe den Kriegszug, zu dem der HERR mich ausgesandt hatte, ausgeführt und habe Agag, den König der Amalekiter, mitgebracht und an den Amalekitern den Bann vollstreckt.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 15, 21, 'Aber das Kriegsvolk hat von der Beute Kleinvieh und Rinder genommen, das Beste von dem Banngut, um es dem HERRN, deinem Gott, in Gilgal zu opfern.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 15, 22, 'Da antwortete Samuel: »Hat der HERR etwa an Brandopfern und Schlachtopfern das gleiche Wohlgefallen wie am Gehorsam gegen seine Befehle? Wisse wohl: Gehorsam ist besser als Schlachtopfer, Folgsamkeit besser als das Fett von Widdern;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 15, 23, 'denn Ungehorsam ist ebenso schlimm wie die Sünde der Zauberei, und Eigenwille ist wie Abgötterei und Götzendienst. Weil du den Befehl des HERRN verworfen hast, hat er dich auch verworfen, daß du nicht mehr König sein sollst!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 15, 24, 'Da sagte Saul zu Samuel: »Ich habe gesündigt, weil ich den Befehl des HERRN und deine Weisungen übertreten habe; denn ich habe mich vor dem Kriegsvolk gefürchtet und deshalb seiner Forderung nachgegeben.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 15, 25, 'Doch nun vergib mir meine Versündigung und kehre mit mir um, damit ich den HERRN anbete!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 15, 26, 'Aber Samuel erwiderte ihm: »Ich kehre nicht mit dir um; weil du den Befehl des HERRN verworfen hast, so hat der HERR dich auch verworfen, daß du nicht länger König über Israel sein sollst.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 15, 27, 'Als nun Samuel sich umwandte, um wegzugehen, erfaßte Saul den Zipfel seines Mantels, aber dieser riß ab.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 15, 28, 'Da sagte Samuel zu ihm: »Der HERR hat heute das Königtum über Israel von dir gerissen und gibt es einem andern, der besser ist als du.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 15, 29, 'Und niemals lügt der ruhmwürdige Gott Israels und empfindet keine Reue; denn er ist kein Mensch, daß ihn etwas gereuen müßte.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 15, 30, 'Saul antwortete: »Ich habe gesündigt; aber erweise mir doch jetzt vor den Ältesten meines Volkes und vor Israel die Ehre, mit mir umzukehren, damit ich den HERRN, deinen Gott, anbete!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 15, 31, 'Da kehrte Samuel um, und zwar hinter Saul her, und Saul verrichtete seine Anbetung vor dem HERRN.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 15, 32, 'Hierauf befahl Samuel: »Bringt Agag, den König der Amalekiter, zu mir her!« Da trat Agag wohlgemut vor ihn und sagte: »Fürwahr, der Tod hat seine Bitterkeit (für mich) verloren!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 15, 33, 'Samuel aber sagte: »Wie dein Schwert Frauen ihrer Kinder beraubt hat, so soll auch deine Mutter ihrer Kinder unter den Frauen beraubt sein!« Hierauf hieb Samuel den Agag in Stücke vor dem HERRN in Gilgal.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 15, 34, 'Samuel begab sich dann nach Rama, während Saul nach dem Gibea Sauls heimkehrte.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 15, 35, 'Samuel besuchte dann Saul bis zu seinem Todestage nicht wieder; denn Samuel trauerte um Saul, weil der HERR es bereut hatte, Saul zum König über Israel gemacht zu haben.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 16, 1, 'Da sagte der HERR zu Samuel: »Wie lange willst du noch um Saul trauern, da ich ihn doch für unwürdig erachtet habe, noch länger König über Israel zu sein? Fülle dein Horn mit Öl und mache dich auf den Weg: ich will dich nach Bethlehem zu Isai senden; denn unter seinen Söhnen habe ich mir einen König ersehen.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 16, 2, 'Samuel antwortete: »Wie kann ich hingehen? Wenn Saul davon hört, bringt er mich um!« Da antwortete der HERR: »Nimm eine junge Kuh mit dir und sage: ›Ich bin hergekommen, um dem HERRN ein Opfer zu bringen‹.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 16, 3, 'Wenn du dann Isai zum Opfermahl eingeladen hast, werde ich selbst dir kundtun, was du zu tun hast; denn du sollst mir den salben, den ich dir bezeichnen werde.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 16, 4, 'Samuel tat hierauf, was der HERR ihm geboten hatte, und begab sich nach Bethlehem. Da gingen ihm die Ältesten des Ortes ängstlich entgegen und fragten ihn: »Bedeutet dein Kommen etwas Gutes?«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 16, 5, 'Er antwortete: »Ja, Gutes! Ich bin gekommen, um dem HERRN ein Opfer zu bringen; heiligt euch also und kommt mit mir zum Opfermahl.« Hierauf ließ er auch Isai und seine Söhne sich heiligen und lud sie zum Opfermahl ein.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 16, 6, 'Als sie sich nun einfanden und er Eliab sah, dachte er: »Sicherlich (steht hier) vor dem HERRN der, den er zu seinem Gesalbten machen will.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 16, 7, 'Aber der HERR sagte zu Samuel: »Sieh nicht auf seine äußere Gestalt und seinen hohen Wuchs! Denn diesen habe ich nicht erkoren. Gott sieht ja nicht das an, worauf Menschen sehen; denn die Menschen sehen nach den Augen, der HERR aber sieht nach dem Herzen.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 16, 8, 'Da rief Isai den Abinadab und ließ ihn vor Samuel treten; doch der erklärte: »Auch diesen hat der HERR nicht erwählt.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 16, 9, 'Da ließ Isai den Samma vortreten, aber Samuel erklärte: »Auch diesen hat der HERR nicht erwählt.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 16, 10, 'So führte Isai dem Samuel sieben seiner Söhne vor, aber Samuel erklärte dem Isai: »Von diesen hat der HERR keinen erwählt.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 16, 11, 'Hierauf fragte Samuel den Isai: »Sind das die jungen Leute alle?« Jener erwiderte: »Es ist noch der jüngste übrig; der hütet eben das Kleinvieh.« Da sagte Samuel zu Isai: »Sende hin und laß ihn holen; denn wir werden uns nicht eher (zum Mahl) setzen, als bis er hergekommen ist.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 16, 12, 'Da sandte er hin und ließ ihn holen. (David) war aber bräunlich, hatte schöne Augen und eine kräftige Gestalt. Da sagte der HERR: »Auf! Salbe ihn, denn dieser ist es!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 16, 13, 'Da nahm Samuel das Ölhorn und salbte ihn inmitten seiner Brüder; da kam der Geist des HERRN über David von diesem Tage an und (blieb) auch späterhin (auf ihm). Samuel aber machte sich auf und kehrte nach Rama zurück.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 16, 14, 'Als nun der Geist des HERRN von Saul gewichen war und ihn ein vom HERRN gesandter böser Geist ängstigte,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 16, 15, 'sagten Sauls Diener zu ihm: »Du weißt, daß ein böser Geist Gottes dich ängstigt.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 16, 16, 'Unser Herr braucht nur zu gebieten: deine Knechte stehen dir zu Diensten und werden einen Mann suchen, der sich auf das Saitenspiel versteht; wenn dann der böse Geist von Gott über dich kommt, soll er die Saiten (vor dir) rühren, dann wird dir wohler werden.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 16, 17, 'Da befahl Saul seinen Dienern: »So seht euch für mich nach einem Manne um, der gut zu spielen versteht, und bringt ihn zu mir!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 16, 18, 'Da nahm einer von den Dienern das Wort und sagte: »Ja, ich habe einen Sohn Isais in Bethlehem kennengelernt, der sich auf das Saitenspiel versteht; er ist auch ein tapferer Mann und kriegsgeübt, dazu redegewandt und von schönem Äußeren, und der HERR ist mit ihm.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 16, 19, 'Da schickte Saul Boten zu Isai und ließ ihm sagen: »Schicke mir doch deinen Sohn David, der bei dem Kleinvieh ist.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 16, 20, 'Da nahm Isai einen mit Brot beladenen Esel, einen Schlauch Wein und ein Ziegenböckchen und sandte es durch seinen Sohn David an Saul.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 16, 21, 'So kam David zu Saul und trat in seine Dienste; und (Saul) gewann ihn sehr lieb, so daß er sein Waffenträger wurde');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 16, 22, 'und Saul dem Isai sagen ließ: »Laß doch David in meinem Dienste bleiben, denn er gefällt mir wohl.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 16, 23, 'Sooft nun der böse Geist Gottes über Saul kam, nahm David die Zither und spielte; dann fand Saul Erleichterung, so daß er sich wohler fühlte und der böse Geist von ihm wich.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 1, 'Da boten die Philister ihre Heere zum Kriege auf, sammelten sich bei Socho, das zu Juda gehört, und schlugen ein Lager zwischen Socho und Aseka bei Ephes-Dammim auf.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 2, 'Saul aber und die Israeliten sammelten sich und bezogen ein Lager im Terebinthental und rüsteten sich zum Kampf gegen die Philister;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 3, 'die Philister standen am Berge jenseits, die Israeliten am Berge diesseits, so daß das Tal zwischen ihnen lag.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 4, 'Da trat aus den Reihen der Philister der Vorkämpfer namens Goliath hervor, ein Gathiter, der sechs Ellen und eine Spanne hoch war;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 5, 'er trug einen ehernen Helm auf dem Kopfe und hatte einen Schuppenpanzer an, dessen Gewicht fünftausend Schekel Erz betrug.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 6, 'An den Beinen trug er eherne Schienen und zwischen den Schultern einen ehernen Wurfspieß;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 7, 'der Schaft seines Speeres war wie ein Weberbaum, und die Spitze seines Speeres bestand aus sechshundert Schekel Eisen; sein Schildträger ging vor ihm her.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 8, 'Er stellte sich hin und rief den in Reihen stehenden Israeliten die Worte zu: »Warum zieht ihr aus, euch in Schlachtordnung aufzustellen? Bin ich nicht da, der Philister, und ihr, die Knechte Sauls? Wählt euch einen Mann aus, der komme zu mir herab!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 9, 'Vermag er mich im Kampfe zu bestehen und erschlägt er mich, so wollen wir euch untertan sein; bin aber ich ihm überlegen und erschlage ich ihn, so sollt ihr uns untertan sein und müßt uns dienen!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 10, 'Dann fügte der Philister noch hinzu: »Heute habe ich den in Reihen stehenden Israeliten Hohn geboten: stellt mir einen Mann, daß wir miteinander kämpfen!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 11, 'Als Saul und alle Israeliten diese Worte des Philisters hörten, erschraken sie und fürchteten sich sehr.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 12, 'David aber war der Sohn jenes Ephrathiten aus Bethlehem in Juda, der Isai hieß und acht Söhne hatte und zur Zeit Sauls schon ein älterer, in den Jahren vorgerückter Mann war.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 13, 'Die drei ältesten Söhne Isais waren unter Saul in den Krieg gezogen; von diesen seinen drei Söhnen, die ins Feld gezogen waren, hieß der älteste Eliab, der zweite Abinadab, der dritte Samma;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 14, 'David aber war der jüngste. Da die drei ältesten unter Saul in den Krieg gezogen waren,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 15, 'ging David ab und zu von Sauls Hofe heim, um in Bethlehem das Kleinvieh seines Vaters zu hüten.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 16, 'Der Philister aber trat morgens und abends auf und stellte sich vierzig Tage lang (vor die Israeliten) hin. –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 17, 'Da sagte Isai (eines Tages) zu seinem Sohne David: »Nimm doch für deine Brüder ein Epha von diesem gerösteten Getreide und diese zehn Brote und bringe sie schnell zu deinen Brüdern ins Lager;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 18, 'diese zehn frischen Käse aber nimm für den Hauptmann der Tausendschaft mit und erkundige dich nach dem Befinden deiner Brüder und laß dir ein Pfand von ihnen mitgeben!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 19, 'Saul und sie und alle Israeliten befanden sich nämlich im Terebinthental im Kriege mit den Philistern.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 20, 'Da machte sich David am andern Morgen früh reisefertig, überließ das Kleinvieh einem Hüter, packte die Lebensmittel ein und begab sich auf den Weg, wie Isai ihm befohlen hatte. Er kam zur Wagenburg, als das Heer gerade in Schlachtordnung ausrückte und man das Kriegsgeschrei erhob;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 21, 'Israel und die Philister stellten sich zum Kampf auf, Schlachtreihe gegen Schlachtreihe.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 22, 'Da übergab David das Gepäck, das er mitgebracht hatte, dem Gepäckhüter, lief dann in die Schlachtreihe und erkundigte sich, als er hinkam, bei seinen Brüdern nach ihrem Ergehen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 23, 'Während er sich noch mit ihnen besprach, trat der Vorkämpfer – er hieß Goliath und war ein Philister aus Gath – aus den Reihen der Philister hervor und führte dieselben Reden wie früher, so daß David es hörte;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 24, 'alle Israeliten aber, die den Mann erblickten, flohen vor ihm und fürchteten sich sehr.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 25, 'Da sagte einer von den Israeliten: »Habt ihr diesen Mann gesehen, der da heraufkommt? Ja, um Israel zu verhöhnen, tritt er auf! Und wer ihn erschlägt, den will der König mit großem Reichtum belohnen und will ihm seine Tochter geben und seines Vaters Haus steuerfrei in Israel machen!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 26, 'Da fragte David die Männer, die bei ihm standen: »Wie soll der Mann belohnt werden, der diesen Philister da erschlägt und Israel von der Schande befreit? Wer ist denn dieser Philister, dieser Heide, daß er die Schlachtreihen des lebendigen Gottes beschimpfen darf?«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 27, 'Da wiederholten ihm die Leute die frühere Mitteilung: »So und so wird man den Mann belohnen, der ihn erschlägt!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 28, 'Als nun sein ältester Bruder Eliab hörte, wie er sich mit den Männern unterhielt, geriet er in Zorn über David und rief aus: »Wozu bist du eigentlich hergekommen, und wem hast du die paar Schafe dort in der Steppe überlassen? Ich kenne deinen vorwitzigen und boshaften Sinn wohl: du bist nur hergekommen, um dir den Krieg anzusehen!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 29, 'David entgegnete: »Nun, was habe ich denn jetzt getan? Es war ja nur eine Frage!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 30, 'Damit wandte er sich von ihm ab, einem andern zu, und wiederholte seine vorige Frage, und die Leute gaben ihm dieselbe Auskunft wie zuvor.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 31, 'Als man nun hörte, wie David sich ausgesprochen hatte, hinterbrachte man es dem Saul, und dieser ließ ihn zu sich kommen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 32, 'Da sagte David zu Saul: »Kein Mensch braucht um den da den Mut zu verlieren! Dein Knecht will hingehen und mit diesem Philister kämpfen.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 33, 'Saul aber antwortete ihm: »Du kannst diesem Philister nicht entgegentreten, um mit ihm zu kämpfen; denn du bist noch ein Jüngling, er aber ist ein Kriegsmann von Jugend auf!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 34, 'Da entgegnete David dem Saul: »Dein Knecht hat seinem Vater das Kleinvieh gehütet; wenn da ein Löwe oder ein Bär kam und ein Stück aus der Herde wegtrug,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 35, 'so lief ich ihm nach und erschlug ihn und riß es ihm aus dem Rachen; leistete er mir aber Widerstand, so packte ich ihn am Bart und schlug ihn tot.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 36, 'Löwen so gut wie Bären hat dein Knecht erschlagen, und diesem Philister, diesem Heiden, soll es ebenso ergehen wie jenen allen; denn er hat die Schlachtreihen des lebendigen Gottes verhöhnt!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 37, 'Dann fuhr David fort: »Der HERR, der mich aus den Krallen der Löwen und aus den Klauen der Bären errettet hat, der wird mich auch aus der Hand dieses Philisters erretten.« Da sagte Saul zu David: »So gehe hin! Der HERR wird mit dir sein!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 38, 'Hierauf legte Saul dem David seine Rüstung an: er setzte ihm einen ehernen Helm aufs Haupt und zog ihm einen Panzer an;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 39, 'weiter mußte David Sauls Schwert über seinen Waffenrock gürten und bemühte sich dann zu gehen; denn er hatte es noch nie versucht. Aber er sagte zu Saul: »Ich kann darin nicht gehen, denn ich bin nicht daran gewöhnt.« So legte David denn alles wieder ab,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 40, 'nahm nur seinen Stecken in die Hand, suchte sich aus dem Bach fünf glatte Kieselsteine aus und tat sie in die Hirtentasche, die ihm als Schleudertasche diente; dann nahm er seine Schleuder in die Hand und ging auf den Philister los.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 41, 'Der Philister aber kam immer näher an David heran, während sein Schildträger vor ihm herschritt.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 42, 'Als nun der Philister hinblickte und David sah, verachtete er ihn, weil er noch so jung war, ein bräunlicher Jüngling von schmuckem Aussehen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 43, 'Daher rief der Philister dem David zu: »Bin ich etwa ein Hund, daß du mit Stöcken zu mir kommst?« Hierauf fluchte der Philister dem David bei seinem Gott');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 44, 'und rief dem David zu: »Komm nur her zu mir, damit ich dein Fleisch den Vögeln des Himmels und den Tieren des Feldes gebe!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 45, 'David aber erwiderte ihm: »Du trittst mir mit Schwert und Lanze und Wurfspieß entgegen, ich aber trete dir entgegen mit dem Namen des HERRN der Heerscharen, des Gottes der Schlachtreihen Israels, die du verhöhnt hast.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 46, 'Am heutigen Tage wird dich der HERR in meine Hand fallen lassen, daß ich dich erschlage und dir den Kopf abhaue; und (deinen Leichnam und) die Leichen des Philisterheeres werde ich noch heute den Vögeln des Himmels und den wilden Tieren des Landes übergeben, damit alle Welt erkennt, daß Israel einen Gott hat!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 47, 'und alle, die hier versammelt sind, sollen erkennen, daß der HERR nicht Schwert und Spieß braucht, um den Sieg zu schaffen; denn der HERR hat die Entscheidung im Kampf, und er wird euch in unsere Hand geben!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 48, 'Als sich nun der Philister in Bewegung setzte und auf David losging, lief dieser eilends aus der Schlachtreihe, dem Philister entgegen;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 49, 'dabei griff er mit der Hand in die Tasche, nahm einen Stein heraus, schleuderte ihn und traf den Philister an die Stirn, so daß ihm der Stein in die Stirn eindrang und er vornüber zu Boden fiel.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 50, 'So überwältigte David den Philister mit der Schleuder und dem Stein, besiegte den Philister und tötete ihn, ohne ein Schwert in der Hand zu haben.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 51, 'Er lief nämlich hin, trat an den Philister heran, nahm dessen Schwert, zog es aus der Scheide und tötete ihn vollends, indem er ihm den Kopf damit abhieb. Als nun die Philister sahen, daß ihr stärkster Mann tot war, ergriffen sie die Flucht.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 52, 'Da machten sich die Männer von Israel und Juda auf, erhoben das Kriegsgeschrei und verfolgten die Philister bis nach Gath und bis an die Tore von Ekron, so daß die Leichen der erschlagenen Philister auf dem Wege von Saaraim bis nach Gath und Ekron lagen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 53, 'Als dann die Israeliten von der Verfolgung der Philister zurückkehrten, plünderten sie deren Lager.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 54, 'David aber nahm den Kopf des Philisters und brachte ihn nach Jerusalem; seine Rüstung dagegen legte er in seinem Zelte nieder.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 55, 'Als aber Saul sah, wie David dem Philister entgegenging, fragte er seinen Heerführer Abner: »Wessen Sohn ist denn der Jüngling, Abner?« Dieser antwortete: »Bei deinem Leben, o König: ich weiß es nicht!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 56, 'Da gab ihm der König den Auftrag: »Erkundige dich doch, wessen Sohn der junge Mann ist!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 57, 'Sobald nun David von dem Sieg über den Philister zurückkehrte, nahm ihn Abner mit sich und führte ihn vor Saul, während er den Kopf des Philisters noch in der Hand hatte.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 58, 'Da fragte ihn Saul: »Wessen Sohn bist du, junger Mann?«, und David antwortete: »Der Sohn deines Knechtes Isai aus Bethlehem.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 18, 1, 'Als nun David seine Unterredung mit Saul beendet hatte, da schloß Jonathan den David in sein Herz und gewann ihn lieb wie sein eigenes Leben.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 18, 2, 'Saul aber nahm David an jenem Tage zu sich und ließ ihn nicht wieder in das Haus seines Vaters zurückkehren.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 18, 3, 'Da schloß Jonathan einen Freundschaftsbund mit David, weil er ihn wie sich selbst liebte.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 18, 4, 'Dabei zog Jonathan den Mantel aus, den er anhatte, und gab ihn David, dazu auch seinen Waffenrock samt seinem Schwerte, seinem Bogen und seinem Gürtel.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 18, 5, 'Sooft nun David Kriegszüge unternahm, hatte er überall Glück, wohin Saul ihn sandte; daher übertrug Saul ihm die Stelle eines Anführers in seinem Heere; und er war beim ganzen Volk und auch bei den Hofleuten Sauls beliebt.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 18, 6, 'Es begab sich aber bei der Heimkehr Sauls und des Heeres, als David nach der Erschlagung des Philisters zurückkehrte: da zogen die Frauen aus allen Ortschaften Israels singend und tanzend, mit Handpauken, Jubelgeschrei und Zimbeln dem König Saul entgegen;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 18, 7, 'und die Frauen hoben im Wechselgesang an: »Saul hat seine Tausende geschlagen, David aber seine Zehntausende!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 18, 8, 'Da geriet Saul in heftigen Zorn, weil dieses Lied ihm durchaus mißfiel, und er sagte: »Dem David weisen sie zehntausend zu, mir aber nur tausend; nun fehlt ihm nur noch das Königtum!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 18, 9, 'So sah denn Saul den David seit jenem Tage und weiterhin mit Neid an.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 18, 10, 'Am folgenden Tage nun kam ein böser Geist Gottes über Saul, so daß er im Hause drinnen raste; David aber spielte die Zither, wie er dies alle Tage zu tun pflegte, während Saul den Speer in der Hand hatte.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 18, 11, 'Da zückte Saul den Speer, indem er dachte: »Ich will David an die Wand spießen!«, aber David wich ihm zweimal aus.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 18, 12, 'Da fürchtete sich Saul vor David, weil der HERR mit ihm war, während er von Saul gewichen war.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 18, 13, 'Darum entfernte ihn Saul aus seiner Nähe und machte ihn zum Hauptmann über tausend Mann. Er unternahm nun Kriegszüge an der Spitze seiner Leute');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 18, 14, 'und hatte bei allen seinen Unternehmungen Glück, weil der HERR mit ihm war.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 18, 15, 'Als nun Saul sah, daß er außerordentliches Glück hatte, geriet er in Angst vor ihm;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 18, 16, 'aber bei ganz Israel und Juda war David beliebt, weil er bei seinen Kriegszügen an ihrer Spitze aus- und einzog.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 18, 17, 'Da sagte Saul zu David: »Hier ist meine älteste Tochter Merab, die will ich dir zur Frau geben; nur mußt du dich mir als Held erweisen und die Kriege des HERRN führen.« Saul dachte nämlich: »Ich selbst will nicht Hand an ihn legen, sondern die Philister sollen ihn ums Leben bringen.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 18, 18, 'Da antwortete David dem Saul: »Wer bin ich, und was ist meine Familie, das Geschlecht meines Vaters, in Israel, daß ich des Königs Schwiegersohn werden sollte!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 18, 19, 'Als dann aber die Zeit kam, wo Merab, die Tochter Sauls, dem David gegeben werden sollte, wurde sie mit Adriel von Mehola verheiratet.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 18, 20, 'Aber Sauls Tochter Michal faßte Liebe zu David. Als Saul Kenntnis davon erhielt, fand die Sache seinen Beifall;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 18, 21, 'er dachte nämlich: »Ich will sie ihm zur Frau geben, damit sie für ihn zur Schlinge wird und er den Philistern in die Hände fällt.« So sagte denn Saul zu David: »Mit der zweiten sollst du jetzt mein Schwiegersohn werden.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 18, 22, 'Darauf gab er seinen Dienern die Weisung: »Redet vertraulich mit David und sagt ihm: ›Der König hat offenbar Wohlgefallen an dir, und alle seine Diener haben dich gern; so werde also nun der Schwiegersohn des Königs!‹«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 18, 23, 'Als nun die Diener Sauls in dieser Weise dem David zuredeten, entgegnete David: »Dünkt es euch etwas Leichtes, des Königs Schwiegersohn zu werden? Ich bin ja doch nur ein armer und geringer Mann.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 18, 24, 'Als nun die Diener Sauls diesem berichteten: »So und so hat David sich ausgesprochen«,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 18, 25, 'antwortete Saul: »Teilt dem David mit, der König begehre keine andere Heiratsgabe als hundert Vorhäute von Philistern, um Rache an den Feinden des Königs zu nehmen.« Saul gedachte nämlich, David durch die Hand der Philister aus der Welt zu schaffen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 18, 26, 'Als nun Sauls Diener dem David diese Äußerung hinterbrachten, war David damit einverstanden, des Königs Schwiegersohn zu werden; und ehe noch die Zeit um war,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 18, 27, 'machte David sich mit seinen Leuten auf den Weg und erschlug unter den Philistern zweihundert Mann. Er brachte dann ihre Vorhäute heim und lieferte sie dem Könige vollzählig ab, um des Königs Schwiegersohn zu werden. Da gab ihm Saul seine Tochter Michal zur Frau.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 18, 28, 'Als aber Saul immer klarer erkannte, daß der HERR mit David war und daß Michal, die Tochter Sauls, ihn liebte,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 18, 29, 'fürchtete Saul sich noch mehr vor David und wurde ihm für immer feind.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 18, 30, 'Sooft aber die Fürsten der Philister ins Feld zogen, hatte David allemal größeren Erfolg als alle anderen Heerführer Sauls, so daß sein Name in hohen Ehren stand.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 19, 1, 'Als nun Saul zu seinem Sohne Jonathan und seiner ganzen Umgebung davon redete, daß er David töten wolle,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 19, 2, 'hinterbrachte Jonathan, der Sohn Sauls, es dem David, den er sehr liebhatte, mit den Worten: »Mein Vater Saul trachtet dir nach dem Leben; nimm dich daher morgen früh in acht und halte dich sorgfältig verborgen!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 19, 3, 'Ich selbst aber will hinausgehen und auf dem Felde, wo du dich befinden mußt, neben meinen Vater treten; ich will dann mit meinem Vater von dir reden und sehen, wie die Sache steht, und es dir dann mitteilen.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 19, 4, 'Hierauf trat Jonathan bei der Unterredung mit seinem Vater Saul für David ein, indem er zu ihm sagte: »Der König versündige sich nicht an seinem Diener David; denn er hat sich dir gegenüber nichts zuschulden kommen lassen, sondern sich große Verdienste um dich erworben;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 19, 5, 'er hat sogar sein Leben aufs Spiel gesetzt und den Philister erschlagen, und so hat der HERR dem ganzen Volk Israel einen herrlichen Sieg verschafft. Du hast es mit angesehen und dich darüber gefreut: warum willst du dich also an unschuldigem Blut versündigen, indem du David ohne Grund tötest?«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 19, 6, 'Da schenkte Saul den Vorstellungen Jonathans Gehör und schwur: »So wahr der HERR lebt, er soll nicht sterben!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 19, 7, 'Nun rief Jonathan den David zu sich und teilte ihm diese ganze Unterredung mit; dann führte er David zu Saul, und er war wieder in der Umgebung des Königs wie früher.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 19, 8, 'Als dann aber der Krieg aufs neue ausbrach und David, der gegen die Philister ins Feld gezogen war, ihnen eine schwere Niederlage beigebracht und sie in die Flucht geschlagen hatte,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 19, 9, 'kam der böse Geist des HERRN wieder über Saul, als er in seinem Hause saß und seinen Speer in der Hand hatte, während David die Zither spielte.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 19, 10, 'Da gedachte Saul den David mit dem Speer an die Wand zu spießen; aber David wich dem Saul aus, so daß der Speer in die Wand fuhr und David sich durch die Flucht retten konnte.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 19, 11, 'In derselben Nacht nun sandte Saul Boten in Davids Haus, die ihn bewachen sollten, damit er ihn am andern Morgen töten könnte. Aber Davids Frau Michal verriet es ihm und sagte: »Wenn du dein Leben nicht noch in dieser Nacht in Sicherheit bringst, so bist du morgen des Todes!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 19, 12, 'Nachdem Michal ihn dann durchs Fenster hinabgelassen hatte, ergriff er die Flucht und entkam glücklich.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 19, 13, 'Hierauf nahm Michal den Hausgott, legte ihn aufs Bett, legte dann ein Geflecht von Ziegenhaaren zu seinen Häupten und deckte ihn mit der Decke zu.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 19, 14, 'Als nun Saul Boten sandte, um David festnehmen zu lassen, erklärte sie, er sei krank.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 19, 15, 'Da sandte Saul die Boten zurück, um nach David zu sehen, mit dem Befehl: »Bringt ihn mitsamt dem Bett zu mir her, damit ich ihn töte.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 19, 16, 'Als nun die Boten hinkamen, fanden sie den Hausgott im Bett liegen und das Geflecht von Ziegenhaaren zu seinen Häupten.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 19, 17, 'Da sagte Saul zu Michal: »Warum hast du mich so betrogen und meinen Feind entrinnen lassen, so daß er sich in Sicherheit gebracht hat?« Michal gab ihm zur Antwort: »Er sagte zu mir: ›Laß mich gehen, sonst muß ich dich töten!‹«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 19, 18, 'David also hatte sich glücklich durch die Flucht gerettet und war nach Rama zu Samuel gekommen, dem er alles mitteilte, was Saul ihm angetan hatte. Er ging dann mit Samuel hin, und (beide) wohnten im Prophetenhause bei Rama.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 19, 19, 'Als nun Saul die Kunde erhielt, David halte sich im Prophetenhause bei Rama auf,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 19, 20, 'sandte er Boten ab, die David festnehmen sollten. Als diese aber die Versammlung der Propheten sahen, die sich in Begeisterung befanden, und Samuel an ihrer Spitze stehend erblickten, kam der Geist Gottes über die Boten Sauls, so daß auch sie in prophetische Begeisterung gerieten.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 19, 21, 'Als man das dem Saul meldete, schickte er andere Boten ab, aber auch diese gerieten in Verzückung, und ebenso erging es den Boten, die Saul zum drittenmal sandte.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 19, 22, 'Nun ging er selbst nach Rama; und als er bei der großen Zisterne, die sich in Sechu befindet, angekommen war, fragte er: »Wo sind hier Samuel und David?« Man antwortete ihm: »Im Prophetenhause zu Rama.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 19, 23, 'Er ging also von dort nach dem Prophetenhause bei Rama; als er aber noch unterwegs war, kam auch über ihn der Geist Gottes, und er befand sich auf dem ganzen Wege in prophetischer Begeisterung bis zu seiner Ankunft im Prophetenhause bei Rama.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 19, 24, 'Dort zog auch er seine Oberkleider aus und war ebenfalls in Verzückung vor Samuel und lag (schließlich) in bloßen Unterkleidern während jenes ganzen Tages und der ganzen Nacht da. Daher pflegt man zu sagen: »Gehört auch Saul zu den Propheten?«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 1, 'David aber kam heimlich aus der Prophetenwohnung bei Rama zu Jonathan und sagte zu ihm: »Was habe ich verbrochen? Worin besteht meine Verschuldung und worin mein Vergehen gegen deinen Vater, daß er mir nach dem Leben trachtet?«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 2, 'Er antwortete ihm: »Behüte Gott! Du wirst nicht sterben! Du weißt, mein Vater tut nichts, es sei wichtig oder unbedeutend, ohne mir Mitteilung davon zu machen: warum sollte mein Vater also dies vor mir verheimlichen? Es ist nichts dran!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 3, 'Da entgegnete ihm David mit der bestimmten Versicherung: »Dein Vater weiß ganz genau, daß du mich liebgewonnen hast; darum wird er sich gesagt haben: ›Dies darf Jonathan nicht erfahren, damit er sich darüber nicht aufregt‹. Aber so wahr der HERR lebt und so wahr du selbst lebst: zwischen mir und dem Tode ist nur ein Schritt!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 4, 'Da antwortete Jonathan dem David: »Ich will dir jeden Wunsch erfüllen.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 5, 'Nun sagte David zu Jonathan: »Wie du weißt, ist morgen Neumondstag; da müßte ich eigentlich mit dem König zu Tisch sitzen; aber laß mich gehen: ich will mich auf dem Felde verbergen bis zum dritten Abend.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 6, 'Sollte dein Vater mich etwa vermissen, so sage ihm: ›David hat mich dringend um Urlaub gebeten, um nach seiner Vaterstadt Bethlehem zu eilen; denn dort findet das jährliche Opferfest für die ganze Familie statt‹.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 7, 'Wenn er dann sagt: ›Gut!‹, so droht deinem Knecht keine Gefahr; gerät er aber in Zorn, so wisse, daß das Unheil seinerseits beschlossene Sache ist.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 8, 'Gib also deinem Knecht einen Beweis deiner Liebe; du hast ja deinen Knecht in einen heiligen Freundschaftsbund mit dir treten lassen. Sollte aber eine Schuld bei mir liegen, so töte du mich; aber zu deinem Vater bringe mich nicht zurück!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 9, 'Da erwiderte Jonathan: »Behüte Gott! Nein, wenn ich erkennen sollte, daß von meinem Vater die Ausführung einer bösen Absicht gegen dich beschlossen ist, so würde ich es dir selbstverständlich mitteilen.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 10, 'David entgegnete dem Jonathan: »Wenn mir nur jemand eine Mitteilung machen wollte, ob dein Vater dir eine abweisende Antwort gegeben hat!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 11, 'Da sagte Jonathan zu David: »Komm, laß uns aufs Feld hinausgehen!« Als nun beide aufs Feld hinausgegangen waren,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 12, 'sagte Jonathan zu David: »Der HERR, der Gott Israels, ist Zeuge! Wenn ich morgen um diese Zeit oder übermorgen in sichere Erfahrung gebracht habe, daß mein Vater es gut mit David meint, und ich alsdann nicht zu dir sende und es dich wissen lasse,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 13, 'so möge der HERR den Jonathan jetzt und später dafür büßen lassen! Wenn aber mein Vater Böses gegen dich im Sinne hat, so will ich dir auch das mitteilen und dich ziehen lassen, daß du dich in Sicherheit bringen kannst. Der HERR möge dann mit dir sein, wie er mit meinem Vater gewesen ist!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 14, 'Und nicht nur, während ich noch lebe, und nicht nur an mir erweise du die Barmherzigkeit des HERRN, daß ich nicht sterbe,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 15, 'sondern auch meinem Hause entziehe niemals deine Güte, auch dann nicht, wenn der HERR die Feinde Davids allesamt vom Erdboden vertilgen wird!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 16, 'So schloß denn Jonathan einen Bund mit dem Hause Davids und sagte: »Der HERR möge Rache üben an den Feinden Davids!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 17, 'Dann schwur Jonathan dem David noch einmal bei seiner Liebe zu ihm; denn er liebte ihn wie sein eigenes Leben.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 18, 'Hierauf sagte Jonathan zu ihm: »Morgen ist Neumondstag; da wird man dich vermissen, wenn dein Platz bei Tisch leer bleibt.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 19, 'Übermorgen aber wird man dich erst recht vermissen; da begib dich an den Ort, wo du dich am Tage des (damaligen) Vorkommnisses verborgen hattest, und verstecke dich neben dem Steinhaufen dort.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 20, 'Ich will dann übermorgen in seiner Nähe drei Pfeile abschießen, als ob ich nach einem Ziele schösse.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 21, 'Dann werde ich den Burschen abschicken mit den Worten: ›Geh, suche die Pfeile!‹ Wenn ich dann dem Burschen zurufe: ›Die Pfeile liegen von dir ab herwärts, hole sie!‹, so komm; denn das bedeutet Gutes für dich, und du hast nichts zu fürchten, so wahr der HERR lebt!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 22, 'Rufe ich aber dem Jungen so zu: ›Die Pfeile liegen von dir ab hinwärts!‹, so gehe! Denn der HERR heißt dich weggehen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 23, 'Aber für das, was wir beide, ich und du, miteinander besprochen haben, dafür ist der HERR (Zeuge) zwischen mir und dir in Ewigkeit!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 24, 'Hierauf versteckte sich David auf dem Felde. Als nun der Neumondstag da war, setzte sich der König zu Tisch, um zu speisen,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 25, 'und zwar setzte sich der König auf seinen gewöhnlichen Platz, nämlich auf den Platz an der Wand; Jonathan setzte sich ihm gegenüber und Abner neben Saul, während Davids Platz leer blieb.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 26, 'Saul sagte an diesem Tage nichts, weil er dachte: »Es ist ein Zufall; David wird nicht rein sein, weil er sich noch nicht hat reinigen lassen.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 27, 'Als aber am anderen Tage, der auf den Neumond folgte, Davids Platz wieder leer blieb, fragte Saul seinen Sohn Jonathan: »Warum ist der Sohn Isais weder gestern noch heute zum Essen gekommen?«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 28, 'Jonathan antwortete dem Saul: »David hat sich dringend Urlaub von mir nach Bethlehem erbeten;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 29, 'er hat nämlich zu mir gesagt: ›Laß mich doch hingehen! Denn wir halten ein Familienopfer in der Stadt; mein Bruder selbst hat mich dazu eingeladen. Willst du mir also eine Liebe erweisen, so gib mir Urlaub, damit ich meine Angehörigen besuchen kann!‹ Darum ist er nicht an der Tafel des Königs erschienen.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 30, 'Da geriet Saul in Zorn über Jonathan und sagte zu ihm: »O du Sohn entarteter Widerspenstigkeit! Meinst du, ich wüßte nicht, daß du dir den Sohn Isais zum Freunde erwählt hast zu deiner Schande und zur Schande der Scham deiner Mutter?');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 31, 'Denn solange der Sohn Isais auf Erden lebt, wirst weder du noch dein Königtum festen Bestand haben. So schicke denn jetzt hin und laß ihn mir holen; denn er ist ein Kind des Todes!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 32, 'Da gab Jonathan seinem Vater Saul zur Antwort: »Warum soll er sterben? Was hat er verbrochen?«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 33, 'Da stieß Saul mit dem Speer nach ihm, um ihn zu durchbohren. Als nun Jonathan erkannte, daß der Tod Davids bei seinem Vater beschlossene Sache war,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 34, 'erhob er sich von der Tafel in glühendem Zorn, ohne an diesem zweiten Neumondstage etwas genossen zu haben; denn er trug um David Leid, weil sein Vater ihn beschimpft hatte.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 35, 'Am folgenden Morgen aber ging Jonathan, wie er mit David verabredet hatte, aufs Feld hinaus, und ein junger Bursche begleitete ihn.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 36, 'Diesem befahl er: »Lauf und suche mir die Pfeile, die ich abschieße!« Während nun der Bursche hinlief, schoß er den Pfeil über ihn hinaus;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 37, 'und als der Bursche an die Stelle kam, wo der von Jonathan abgeschossene Pfeil lag, rief Jonathan hinter dem Burschen her: »Der Pfeil liegt ja von dir hinwärts!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 38, 'Weiter rief er hinter dem Burschen her: »Mache schnell! Halte dich nicht auf!« Da las der Bursche Jonathans die Pfeile auf und kam zu seinem Herrn zurück,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 39, 'ohne etwas gemerkt zu haben; nur Jonathan und David wußten um die Sache.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 40, 'Dann übergab Jonathan sein Schießgerät seinem Burschen mit der Weisung: »Geh, trage das in die Stadt!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 41, 'Als nun der Bursche sich entfernt hatte, kam David hinter dem Steinhaufen hervor, warf sich mit dem Angesicht zur Erde nieder und verneigte sich dreimal; darauf küßten sie einander und weinten zusammen, bis David seine Fassung wiedergewann.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 42, 'Jonathan sagte dann zu David: »Gehe in Frieden! Was wir beide uns im Namen des HERRN zugeschworen haben, dafür wird der HERR zwischen mir und dir, zwischen meinen und deinen Nachkommen Zeuge sein in Ewigkeit!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 21, 1, 'Hierauf machte sich David auf und entfernte sich; Jonathan aber kehrte in die Stadt zurück.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 21, 2, 'David kam dann nach Nob zum Priester Ahimelech; dieser kam ihm ängstlich entgegen und fragte ihn: »Warum kommst du allein, ohne einen Begleiter bei dir zu haben?«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 21, 3, 'David antwortete dem Priester Ahimelech: »Der König hat mir einen Auftrag gegeben und zu mir gesagt: ›Niemand darf etwas von der Sache erfahren, deretwegen ich dich absende und die ich dir aufgetragen habe!‹ Darum habe ich auch meine Leute an einen bestimmten Ort bestellt.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 21, 4, 'Und nun, wenn du einige Lebensmittel zur Verfügung hast, etwa fünf Brote, so gib sie mir, oder was sonst vorhanden ist!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 21, 5, 'Der Priester antwortete David: »Gewöhnliches Brot ist nicht in meinem Besitz, sondern nur geweihtes Brot ist da; wenn sich die Leute nur von Weibern ferngehalten haben!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 21, 6, 'Da antwortete David dem Priester: »Gewiß! Weiber sind uns schon seit mehreren Tagen versagt gewesen; als ich auszog, waren die Leiber der Leute rein, obwohl es sich nur um ein gewöhnliches Unternehmen handelte; wieviel mehr werden sie heute am Leibe rein sein!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 21, 7, 'Da gab ihm der Priester geweihtes Brot, weil dort kein anderes Brot vorhanden war als nur die Schaubrote, die man vor dem Angesicht des HERRN wegnimmt, um neugebackene Brote am Tage ihrer Wegnahme dafür aufzulegen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 21, 8, 'Es war aber an jenem Tage ein Mann dort anwesend, im Heiligtum vor dem HERRN abgesondert, einer von Sauls Dienern, ein Edomiter namens Doeg, der Aufseher der Hirten Sauls.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 21, 9, 'David fragte dann Ahimelech: »Hast du hier nicht irgendeinen Speer oder ein Schwert zur Hand? Ich habe nämlich weder mein Schwert noch meine anderen Waffen mitgenommen, weil der Auftrag des Königs große Eile hatte.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 21, 10, 'Der Priester antwortete: »Das Schwert des Philisters Goliath, den du im Terebinthental erschlagen hast, das ist noch hier, eingewickelt in ein Tuch, hinter dem Priesterkleide; wenn du es für dich nehmen willst, so nimm es hin; denn ein anderes ist sonst nicht hier.« David erwiderte: »Seinesgleichen gibt es nicht: gib es mir her!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 21, 11, 'Hierauf machte sich David auf den Weg und floh an jenem Tage vor Saul und begab sich zu Achis, dem König von Gath.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 21, 12, 'Da sagten die Diener des Achis zu diesem: »Das ist ja David, der König des Landes; das ist ja der, zu dessen Ehren sie bei den Reigentänzen singen: ›Saul hat seine Tausende geschlagen, David aber seine Zehntausende.‹«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 21, 13, 'Diese Worte machten David überaus bedenklich, und er geriet in große Furcht vor Achis, dem König von Gath.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 21, 14, 'Daher stellte er sich wahnsinnig vor ihnen und gebärdete sich wie ein Rasender unter ihren Händen, trommelte an die Torflügel und ließ den Speichel in seinen Bart fließen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 21, 15, 'Da sagte Achis zu seinen Dienern: »Ihr seht doch, daß der Mann verrückt ist: warum bringt ihr ihn zu mir?');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 21, 16, 'Fehlt es mir hier etwa an verrückten Leuten, daß ihr mir auch diesen noch hergebracht habt, damit er den Verrückten bei mir spiele? Der sollte mir ins Haus kommen?«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 22, 1, 'Da ging David von dort weg und flüchtete sich in die Höhle von Adullam. Als nun seine Brüder und seine ganze Familie dies erfuhren, kamen sie dorthin zu ihm hinab.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 22, 2, 'Außerdem sammelten sich bei ihm allerlei Leute, die sich in bedrängter Lage befanden, und alle, die Schulden hatten, und allerlei mißvergnügte Leute, deren Anführer er wurde, so daß etwa vierhundert Mann bei ihm waren.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 22, 3, 'Von dort begab sich David nach Mizpe im Moabiterlande und bat den König der Moabiter: »Laß doch meinen Vater und meine Mutter bei euch wohnen, bis ich weiß, was Gott mit mir vorhat!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 22, 4, 'Da brachte er sie zu dem Moabiterkönig, und sie blieben bei diesem, solange David auf der Bergfeste war.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 22, 5, 'Als aber der Prophet Gad zu David sagte: »Bleibe nicht auf der Bergfeste, sondern begib dich ins Land Juda!«, da brach David auf und kam nach Jaar-Hereth.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 22, 6, 'Als nun Saul erfuhr, daß David mit seinen Leuten wieder zum Vorschein gekommen war – Saul saß aber gerade in Gibea unter der Tamariske auf der Anhöhe, mit dem Speer in der Hand, während alle seine Diener um ihn herum standen –,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 22, 7, 'da sagte Saul zu seinen Dienern, die ihn umgaben: »Hört doch, ihr Benjaminiten! Wird wohl der Sohn Isais euch allen auch Äcker und Weinberge schenken und euch alle zu Hauptleuten über Tausendschaften und zu Hauptleuten über hundert Mann machen,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 22, 8, 'daß ihr euch alle gegen mich verschworen habt und niemand mir eine Mitteilung gemacht hat, als mein Sohn einen Freundschaftsbund mit dem Sohne Isais schloß, und daß niemand von euch Mitgefühl mit mir gehabt und mir eine Mitteilung gemacht hat, als mein Sohn meinen Diener (David) zur Feindschaft gegen mich aufwiegelte, wie es jetzt klar zutage liegt?«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 22, 9, 'Da nahm der Edomiter Doeg, der neben den Dienern Sauls stand, das Wort und sagte: »Ich habe gesehen, wie der Sohn Isais nach Nob zu Ahimelech, dem Sohne Ahitubs, kam.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 22, 10, 'Da hat dieser den HERRN für ihn befragt und ihm auch Zehrung gegeben und ihm das Schwert des Philisters Goliath übergeben.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 22, 11, 'Da ließ der König den Priester Ahimelech, den Sohn Ahitubs, und sein ganzes Geschlecht, die Priesterschaft, die in Nob war, rufen; und als sie sich alle beim König eingestellt hatten,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 22, 12, 'sagte Saul: »Höre doch, Sohn Ahitubs!« Dieser antwortete: »Hier bin ich, Herr!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 22, 13, 'Da fuhr Saul fort: »Warum habt ihr euch gegen mich verschworen, du und der Sohn Isais, daß du ihm Brot und ein Schwert gegeben und Gott für ihn befragt hast, damit er sich gegen mich erhebe und auflehne, wie es jetzt klar zutage liegt?«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 22, 14, 'Ahimelech antwortete: »Aber wer unter allen deinen Dienern ist so treu wie David? Dazu ist er des Königs Schwiegersohn und Oberster über deine Leibwache und geehrt in deinem Hause.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 22, 15, 'Ist es denn jetzt das erste Mal gewesen, daß ich Gott für ihn befragt habe? Das sei fern von mir! Der König möge doch seinem Knecht und meinem ganzen Geschlecht so etwas nicht zur Last legen! Denn dein Knecht hat von allem diesem nicht das Geringste gewußt!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 22, 16, 'Doch der König entgegnete: »Ahimelech, du mußt ohne Gnade sterben, du selbst und dein ganzes Geschlecht!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 22, 17, 'Hierauf gab der König seinen Leibwächtern, die vor ihm standen, den Befehl: »Tretet herzu und tötet die Priester des HERRN! Denn auch sie halten es mit David, und obwohl sie wußten, daß er auf der Flucht war, haben sie mir keine Mitteilung gemacht!« Aber die Diener des Königs weigerten sich, Hand an die Priester des HERRN zu legen, um sie niederzustoßen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 22, 18, 'Da befahl der König dem Doeg: »Tritt du herzu und stoße die Priester nieder!« Da trat der Edomiter Doeg heran, und er stieß die Priester nieder; er tötete an jenem Tage fünfundachtzig Männer, die das leinene Priesterkleid trugen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 22, 19, 'Sodann ließ er in der Priesterstadt Nob alles Lebende mit dem Schwerte niedermachen, Männer wie Frauen, Kinder wie Säuglinge, Rinder, Esel und das Kleinvieh, alles ließ er mit dem Schwert niedermachen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 22, 20, 'Nur ein einziger Sohn Ahimelechs, des Sohnes Ahitubs, namens Abjathar, rettete sich durch die Flucht zu Davids Gefolgschaft');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 22, 21, 'und berichtete dem David, daß Saul die Priester des HERRN ermordet habe.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 22, 22, 'Da sagte David zu Abjathar: »Ich wußte schon damals, daß der Edomiter Doeg, der dort anwesend war, es Saul sicherlich verraten würde. Ich selbst trage die Schuld am Tode aller Angehörigen deines Geschlechts!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 22, 23, 'Bleibe bei mir und fürchte dich nicht! Denn nur wer mir nach dem Leben trachtet, wird auch dir nach dem Leben trachten können: du bist bei mir in voller Sicherheit!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 23, 1, 'Als dann die Meldung bei David einlief, daß die Philister Kegila belagerten und die Tennen plünderten,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 23, 2, 'befragte David den HERRN: »Soll ich hinziehen und die Philister dort schlagen?« Der HERR antwortete ihm: »Ziehe hin, schlage die Philister und entsetze Kegila!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 23, 3, 'Aber Davids Leute sagten zu ihm: »Wir müssen schon hier in Juda in ewiger Angst leben; wie erst, wenn wir nach Kegila gegen die Schlachtreihen der Philister ziehen!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 23, 4, 'Da befragte David den HERRN noch einmal und erhielt vom HERRN die Antwort: »Mache dich auf und ziehe nach Kegila hinab! Denn ich werde die Philister in deine Hand geben.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 23, 5, 'Da zog David mit seinen Leuten nach Kegila, griff die Philister an, erbeutete ihre Herden und brachte ihnen eine schwere Niederlage bei. So rettete David die Einwohner von Kegila. –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 23, 6, 'Als aber Abjathar, der Sohn Ahimelechs, zu David [nach Kegila] floh, hatte er ein Priesterkleid mitgebracht. –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 23, 7, 'Als nun Saul erfuhr, daß David nach Kegila gezogen sei, rief er aus: »Gott hat ihn mir in die Hände geliefert! Denn er hat sich selbst eingeschlossen, indem er sich in eine Stadt mit Toren und Riegeln begeben hat.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 23, 8, 'Saul bot also das ganze Volk zum Kriege auf, um nach Kegila zur Belagerung Davids und seiner Leute hinabzuziehen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 23, 9, 'Als nun David erkannte, daß Saul Böses gegen ihn im Schilde führte, befahl er dem Priester Abjathar: »Bringe das Priesterkleid herbei!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 23, 10, 'Dann betete David: »HERR, Gott Israels! Dein Knecht hat als gewiß gehört, daß Saul nach Kegila zu ziehen gedenkt, um die Stadt um meinetwillen zu vernichten.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 23, 11, 'Werden die Bürger von Kegila mich ihm ausliefern? Wird Saul wirklich herabkommen, wie dein Knecht vernommen hat? HERR, Gott Israels, tu das doch deinem Knechte kund!« Da antwortete der HERR: »Ja, er wird herabkommen.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 23, 12, 'Dann fragte David weiter: »Werden die Bürger von Kegila mich und meine Leute an Saul ausliefern?« Der HERR antwortete: »Ja, sie werden dich ausliefern.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 23, 13, 'Da machte sich David mit seinen Leuten, etwa sechshundert Mann, auf und zog aus Kegila ab, und sie streiften aufs Geratewohl umher. Als dann dem Saul gemeldet wurde, David sei aus Kegila entronnen, stand er vom Zug dorthin ab.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 23, 14, 'David hielt sich dann in der Wüste auf den Berghöhen auf, und zwar besonders im Gebirge in der Wüste Siph; und Saul suchte während der ganzen Zeit nach ihm, aber Gott ließ ihn nicht in seine Hände fallen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 23, 15, 'Als nun David sah, daß Saul ausgezogen war, um ihn ums Leben zu bringen – er befand sich gerade in Horesa in der Wüste Siph –,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 23, 16, 'da machte sich Jonathan, der Sohn Sauls, auf und begab sich zu David nach Horesa und weckte neues Vertrauen auf Gott in ihm,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 23, 17, 'indem er zu ihm sagte: »Fürchte dich nicht! Denn die Hand meines Vaters Saul wird dich nicht erreichen, sondern du wirst König über Israel werden, und ich werde der Zweite nach dir sein; auch mein Vater Saul weiß das wohl.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 23, 18, 'Dann schlossen beide einen Bund miteinander vor dem HERRN; und David blieb in Horesa, während Jonathan wieder heimkehrte.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 23, 19, 'Hierauf gingen einige Siphiter zu Saul nach Gibea hinauf und meldeten: »David hält sich bei uns auf den Berghöhen in Horesa verborgen, auf dem Höhenzuge Hachila, der südlich von der Öde liegt.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 23, 20, 'Nun denn, o König, komm zu uns herab, sobald es dir beliebt; unsere Sache soll es alsdann sein, ihn in die Gewalt des Königs zu bringen.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 23, 21, 'Da antwortete Saul: »Der HERR möge euch dafür segnen, daß ihr Teilnahme für mich bewiesen habt!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 23, 22, 'Geht nun hin, vergewissert euch noch mehr und gebt sorgsam acht, um seinen Aufenthaltsort zu erkunden und wer ihn daselbst gesehen hat; denn man hat mir gesagt, er sei ein sehr listiger Mann.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 23, 23, 'Wenn ihr alle Schlupfwinkel, wo er sich versteckt hält, sicher erkundet habt, so kommt wieder zu mir mit zuverlässiger Auskunft, dann will ich mit euch gehen; und wenn er wirklich im Lande ist, so will ich ihn schon unter allen Tausendschaften Judas aufspüren!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 23, 24, 'Da machten sich die Siphiter auf und gingen Saul voraus nach Siph; David aber befand sich damals mit seinen Leuten in der Wüste Maon, in der Steppe südlich von der Einöde.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 23, 25, 'Als nun Saul mit seinen Leuten hinzog, um ihn aufzusuchen, und man es David hinterbrachte, zog er nach dem Felsen hinab, der in der Wüste Maon liegt. Auf die Kunde hiervon folgte Saul dem David eiligst in die Wüste Maon nach.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 23, 26, 'Da zog nun Saul auf der einen Seite des Bergzuges und David mit seinen Leuten auf der anderen Seite. Als dann David sich beeilte, dem Saul zu entkommen, war Saul mit seinen Leuten gerade im Begriff, David und seine Leute zu umzingeln, um sie gefangenzunehmen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 23, 27, 'Da traf plötzlich ein Bote bei Saul ein mit der Meldung: »Mache dich schleunigst auf den Weg! Denn die Philister sind ins Land eingefallen.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 23, 28, 'Da mußte Saul die Verfolgung Davids aufgeben und den Philistern entgegenziehen; daher nennt man jenen Ort den ›Trennungsfelsen‹.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 24, 1, 'David zog dann von dort hinweg und setzte sich auf den Berghöhen von Engedi fest.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 24, 2, 'Als nun Saul von der Verfolgung der Philister zurückgekehrt war, meldete man ihm, David sei jetzt in der Wüste von Engedi.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 24, 3, 'Da nahm Saul dreitausend Mann, auserlesene Leute aus ganz Israel, und brach auf, um David und seine Leute auf der Ostseite der Steinbockfelsen zu suchen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 24, 4, 'Als er nun zu den Schafhürden am Wege kam, war dort eine Höhle, in die Saul hineinging, um seine Notdurft zu verrichten; David aber saß mit seinen Leuten hinten in der Höhle.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 24, 5, 'Da sagten Davids Leute zu ihm: »Wahrlich, dies ist der Tag, von dem der HERR zu dir gesagt hat: ›Fürwahr, ich will deinen Feind dir in die Hände liefern, so daß du mit ihm verfahren kannst, wie es dir beliebt.‹« Hierauf stand David auf und schnitt unbemerkt einen Zipfel von Sauls Mantel ab.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 24, 6, 'Hinterher aber schlug ihm doch das Gewissen, daß er den Zipfel von Sauls Mantel abgeschnitten hatte,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 24, 7, 'und er sagte zu seinen Leuten: »Der HERR bewahre mich davor, so etwas zu tun und mich an meinem Herrn, dem Gesalbten Gottes, zu vergreifen! Er ist ja der Gesalbte Gottes!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 24, 8, 'Mit diesen Worten trat David seinen Leuten entgegen und gestattete ihnen nicht, Saul ein Leid anzutun. Als dann Saul die Höhle verlassen hatte und seines Weges weiterzog,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 24, 9, 'machte sich auch David alsbald auf, trat aus der Höhle hinaus und rief hinter Saul her: »Mein Herr und König!« Als Saul sich nun umwandte, verneigte David sich mit dem Angesicht zur Erde nieder und brachte dem Könige seine Huldigung dar;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 24, 10, 'dann rief er dem Saul zu: »Warum hörst du auf das Gerede der Leute, die da sagen, David sinne auf dein Verderben?');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 24, 11, 'Siehe, am heutigen Tage hast du mit eigenen Augen sehen können, daß der HERR dich heute in der Höhle in meine Gewalt gegeben hatte; und obgleich man mir zuredete, ich möchte dich umbringen, habe ich dich doch verschont und habe gedacht: ›Ich will mich nicht an meinem Herrn vergreifen, weil er der Gesalbte Gottes ist.‹');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 24, 12, 'Und nun, mein Vater, sieh her! Ja, sieh hier den Zipfel deines Mantels in meiner Hand! Daran, daß ich den Zipfel von deinem Mantel abgeschnitten habe, ohne dich zu töten, daran kannst du mit Sicherheit erkennen, daß ich an nichts Böses und an keinen Verrat gegen dich gedacht und mich nicht an dir versündigt habe, während du mir nachstellst, um mich des Lebens zu berauben.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 24, 13, 'Der HERR möge Richter zwischen mir und dir sein, und der HERR möge mich an dir rächen! Aber meine Hand soll nicht gegen dich sein!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 24, 14, 'Schon das alte Sprichwort sagt: ›Von den Gottlosen mag Gottlosigkeit ausgehen!‹, aber meine Hand soll nicht gegen dich sein!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 24, 15, 'Hinter wem zieht denn der König von Israel her? Wen verfolgst du? Einen toten Hund! Einen einzelnen Floh!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 24, 16, 'So sei denn der HERR Richter und entscheide zwischen mir und dir! Er möge die Untersuchung in meiner Sache führen und mich vertreten und mir Recht gegen dich schaffen!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 24, 17, 'Als David diese Worte an Saul gerichtet hatte, antwortete dieser: »Ist das nicht deine Stimme, mein Sohn David?« Hierauf fing Saul an, laut zu weinen,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 24, 18, 'und rief dem David zu: »Du bist gerechter als ich; denn du hast mir Gutes erwiesen, während ich böse an dir gehandelt habe.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 24, 19, 'Und heute hast du mir deine Liebe in besonderem Maße dadurch bewiesen, daß du mich nicht getötet hast, als der HERR mich in deine Hand gegeben hatte.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 24, 20, 'Denn wenn jemand seinen Feind antrifft, läßt er ihn da wohl friedlich seines Weges ziehen? So möge denn der HERR dir mit Gutem vergelten, was du heute an mir getan hast!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 24, 21, 'Und nun, siehe, ich weiß gewiß, daß du König werden wirst und daß in deiner Hand das Königtum über Israel Bestand haben wird.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 24, 22, 'So schwöre mir denn jetzt beim HERRN, daß du meine Nachkommen nach meinem Tode nicht ausrotten und meinen Namen aus meinem Geschlecht nicht austilgen willst!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 24, 23, 'Da schwur David es dem Saul; dann zog Saul heim, während David sich mit seinen Leuten auf die Bergfeste begab.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 1, 'Da starb Samuel, und ganz Israel versammelte sich und hielt um ihn die Totenklage; man begrub ihn dann in seinem Hause zu Rama. David aber machte sich auf und zog in die Wüste Paran hinab.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 2, 'Nun lebte da in Maon ein Mann, der sein Anwesen in Karmel hatte, ein sehr begüterter Mann, der dreitausend Schafe und tausend Ziegen besaß; und er war gerade mit der Schur seiner Schafe in Karmel beschäftigt.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 3, 'Der Mann hieß Nabal und seine Frau Abigail; die Frau war klug und von großer Schönheit, der Mann dagegen roh und bösartig in all seinem Tun, ein echter Kalebiter.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 4, 'Als nun David in der Wüste hörte, daß Nabal eben Schafschur hielt,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 5, 'schickte er zehn von seinen Leuten ab mit dem Auftrage: »Geht nach Karmel hinauf, kehrt bei Nabal ein, grüßt ihn von mir');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 6, 'und sagt zu meinem Bruder: ›Heil dir und Heil deiner Familie und Heil allem, was du besitzest!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 7, 'Ich habe jetzt eben vernommen, daß die Schafschur bei dir stattfindet. Da nun deine Hirten sich bei uns hier aufgehalten haben, ohne daß wir ihnen etwas zuleide getan und ohne daß sie während der ganzen Zeit ihres Aufenthalts in Karmel das Geringste vermißt haben –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 8, 'frage nur deine Leute, sie werden es dir bestätigen! –, so erweise dich nun freundlich gegen die Leute, zumal da wir an einem Festtage zu dir kommen. Gib also deinen Knechten und deinem Sohne David, was dir gerade vor die Hand kommt!‹«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 9, 'Als nun Davids Leute hinkamen, richteten sie den Auftrag im Namen Davids bei Nabal genau aus und warteten dann schweigend.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 10, 'Nabal aber gab den Leuten Davids zur Antwort: »Wer ist David, und wer ist der Sohn Isais? Heutzutage gibt es Knechte genug, die ihren Herren entlaufen!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 11, 'Soll ich etwa mein Brot, mein Wasser und mein Geschlachtetes, das ich für meine Scherer geschlachtet habe, nehmen und es Leuten geben, von denen ich nicht einmal weiß, woher sie sind?«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 12, 'Darauf wandten sich Davids Leute um und zogen ihres Weges zurück und erstatteten David nach ihrer Rückkehr genauen Bericht über den Vorfall.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 13, 'Da befahl David seinen Leuten: »Jeder gürte sein Schwert um!« Nachdem nun alle dem Befehle nachgekommen waren und auch David sich sein Schwert umgegürtet hatte, zogen sie unter Davids Führung hinauf, etwa vierhundert Mann, während zweihundert beim Gepäck zurückblieben.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 14, 'Inzwischen hatte aber einer von den Knechten der Abigail, der Frau Nabals, berichtet: »David hat soeben Boten aus der Wüste hergeschickt, um unsern Herrn begrüßen zu lassen, der aber hat sie grob angefahren.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 15, 'Und doch sind die Männer sehr gut gegen uns gewesen; es ist uns von ihnen nichts zuleide geschehen, und wir haben nicht das Geringste vermißt während der ganzen Zeit, die wir bei ihnen auf dem Felde umhergezogen sind;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 16, 'nein, sie sind eine Mauer um uns bei Tag und bei Nacht gewesen, solange wir das Kleinvieh in ihrer Nähe gehütet haben.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 17, 'Überlege jetzt also und sieh zu, was du tun willst! Denn unserm Herrn und seinem ganzen Hause steht sicherlich ein Unglück bevor; er selbst aber ist ein zu bösartiger Mann, als daß man mit ihm reden könnte.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 18, 'Da nahm Abigail in aller Eile zweihundert Brote und zwei Schläuche Wein, fünf zubereitete Schafe, fünf Scheffel geröstetes Getreide, hundert Rosinentrauben und zweihundert Feigenkuchen, lud alles auf Esel');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 19, 'und befahl ihren Knechten: »Zieht mir voraus, ich komme sogleich hinter euch her!« Ihrem Manne Nabal aber sagte sie nichts davon.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 20, 'Während sie nun an einer durch den Berg verdeckten Stelle auf ihrem Esel abwärts ritt, kam gerade auch David mit seinen Leuten von der entgegengesetzten Seite herab, und sie traf mit ihnen zusammen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 21, 'Nun hatte David bei sich überlegt: »Rein umsonst habe ich diesem Menschen seine gesamte Habe in der Wüste beschützt, so daß ihm nie das Geringste von seinem gesamten Besitz verlorengegangen ist; er aber hat mir Gutes mit Bösem vergolten.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 22, 'Gott möge es den Feinden Davids jetzt und künftig gut ergehen lassen, wenn ich von allem, was ihm gehört, bis morgen früh ein einziges Mannesbild übriglasse!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 23, 'Als nun Abigail Davids ansichtig wurde, stieg sie schleunigst von ihrem Esel herab, warf sich vor David auf ihr Angesicht nieder, verneigte sich dann zur Erde');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 24, 'und rief kniefällig aus: »Auf mir allein, mein Herr, liegt die Schuld! Laß doch deine Magd vor dir reden und schenke den Worten deiner Magd Gehör!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 25, 'Mein Herr gebe doch nichts auf diesen nichtswürdigen Menschen, auf Nabal! Denn er ist wirklich so, wie sein Name besagt: er heißt Nabal und verübt nur Torheiten; ich aber, deine Magd, habe die Leute, die du, mein Herr, gesandt hast, nicht zu Gesicht bekommen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 26, 'Und nun, mein Herr, so wahr Gott lebt und so wahr du selbst lebst: Gott hat dich davor behütet, in Blutschuld zu geraten und dich mit eigener Hand zu rächen. So mögen nun deine Feinde und alle, die Böses gegen meinen Herrn sinnen, dem Nabal gleich werden!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 27, 'Und nun, dieses Geschenk hier, das deine Magd für meinen Herrn mitgebracht hat, ist für die Leute bestimmt, die meinem Herrn auf seinen Zügen folgen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 28, 'Vergib deiner Magd ihr Vergehen! Denn sicherlich wird Gott meinem Herrn ein Haus bauen, das Bestand hat, weil mein Herr im Dienste Gottes streitet und kein Unrecht sich an dir finden wird, solange du lebst.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 29, 'Und wenn ein Mensch sich erheben sollte, dich zu verfolgen und dir nach dem Leben zu trachten, so möge die Seele meines Herrn eingebunden sein im Bündel des Lebens beim HERRN, deinem Gott! die Seele deiner Feinde aber möge er wegschleudern in der Schleuderpfanne!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 30, 'Wenn Gott dann meinem Herrn all das Glück verleihen wird, das er dir verheißen hat, und dich zum Fürsten über Israel bestellt,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 31, 'so wirst du dich frei in deinem Inneren fühlen, und mein Herr braucht sich keine Vorwürfe zu machen, daß du, mein Herr, Blut ohne Ursache vergossen und dir mit eigener Hand Recht geschafft habest. Wenn aber Gott meinem Herrn Glück verleihen wird, so gedenke deiner Magd!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 32, 'Da antwortete David der Abigail: »Gepriesen sei der HERR, der Gott Israels, der dich mir heute hat entgegenkommen lassen!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 33, 'Und gepriesen sei deine Klugheit und gepriesen du selbst, daß du mich heute davon abgehalten hast, in Blutschuld zu geraten und mir mit eigener Hand Genugtuung zu verschaffen!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 34, 'Denn so wahr der HERR lebt, der Gott Israels, der mich davor behütet hat, dir ein Leid anzutun: wärst du mir nicht so schnell entgegengekommen, so wäre dem Nabal bis morgen früh kein einziges Mannesbild übriggeblieben!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 35, 'Darauf nahm David von ihr an, was sie ihm mitgebracht hatte; zu ihr selbst aber sagte er: »Kehre in Frieden in dein Haus zurück! Wisse wohl: ich habe dir Gehör geschenkt und Rücksicht auf dich genommen!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 36, 'Als dann Abigail zu Nabal zurückkehrte, hielt er gerade ein Gastmahl in seinem Hause, ein geradezu königliches Festgelage, und er befand sich in der fröhlichsten Stimmung. Da er schwer betrunken war, teilte sie ihm nicht das Geringste mit, bis der Morgen anbrach.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 37, 'Als er aber am folgenden Morgen seinen Rausch ausgeschlafen hatte, machte seine Frau ihm Mitteilung von allem, was vorgegangen war. Da erlitt er einen Schlaganfall und wurde wie ein Stein;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 38, 'und nach etwa zehn Tagen traf ihn die Hand des HERRN, daß er starb.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 39, 'Als nun David die Nachricht vom Tode Nabals erhielt, rief er aus: »Gepriesen sei der HERR, der die mir von Nabal zugefügte Schmach gerächt und mich, seinen Knecht, vom Bösestun zurückgehalten, die Bosheit Nabals aber auf ihn selbst hat zurückfallen lassen!« Darauf sandte David hin und warb um Abigail, um sie sich zum Weibe zu nehmen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 40, 'Als nun Davids Boten nach Karmel zu Abigail kamen und die Werbung anbrachten mit den Worten: »David hat uns zu dir gesandt: er wünscht dich als sein Weib heimzuführen«,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 41, 'da erhob sie sich, verneigte sich mit dem Antlitz bis zur Erde und sagte: »Ja, deine Magd ist bereit, als Dienerin den Knechten meines Herrn die Füße zu waschen!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 42, 'Sodann machte Abigail sich schleunigst auf und setzte sich auf ihren Esel; ebenso ihre fünf Dienerinnen, die ihre Begleitung bildeten. So folgte sie den Boten Davids und wurde sein Weib.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 43, 'David hatte sich aber auch Ahinoam aus Jesreel (in Juda) geholt; so wurden beide zumal seine Frauen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 44, 'Saul dagegen hatte seine Tochter Michal, die mit David verheiratet war, Palti, dem Sohne des Lais aus Gallim, zur Frau gegeben.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 26, 1, 'Da kamen die Siphiter zu Saul nach Gibea und meldeten: »Wisse, David hält sich auf dem Höhenzuge Hachila am Saume der Einöde verborgen.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 26, 2, 'Da machte sich Saul mit dreitausend Mann auserlesener Israeliten auf den Weg und zog in die Wüste Siph hinab, um David in der Wüste Siph zu suchen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 26, 3, 'Saul lagerte sich dann auf dem Höhenzuge Hachila, der am Saum der Einöde an der Straße liegt, während David sich in der Wüste aufhielt. Als dieser nun erfuhr, daß Saul zu seiner Verfolgung in die Wüste gekommen war,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 26, 4, 'sandte er Kundschafter aus und erhielt so die sichere Nachricht von der Ankunft Sauls.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 26, 5, 'Er machte sich also auf und kam an den Ort, wo Saul sich gelagert hatte. Als aber David den Platz sah, wo Saul mit seinem Heerführer Abner, dem Sohne Ners, lag – Saul lag nämlich innerhalb der Wagenburg, während das Kriegsvolk rings um ihn her gelagert war –,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 26, 6, 'da wandte sich David an den Hethiter Ahimelech und an Abisai, den Sohn der Zeruja, den Bruder Joabs, mit der Frage: »Wer geht mit mir zu Saul in das Lager hinab?« Abisai antwortete: »Ich gehe mit dir hinab!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 26, 7, 'Als nun David und Abisai nachts zu den Leuten gekommen waren, da fanden sie Saul schlafend innerhalb der Wagenburg liegen, und sein Speer steckte zu seinen Häupten im Boden; Abner aber und das Kriegsvolk lagen um ihn her.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 26, 8, 'Da sagte Abisai zu David: »Heute hat Gott deinen Feind dir in die Hände geliefert; und nun laß mich ihn doch mit seinem Speer an den Boden spießen mit einem Stoß: es soll kein zweiter Stoß für ihn nötig sein!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 26, 9, 'Aber David erwiderte dem Abisai: »Tu ihm nichts zuleide! Denn wer könnte Hand an den Gesalbten des HERRN legen und bliebe ungestraft?«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 26, 10, 'Dann fuhr David fort: »So wahr der HERR lebt, nein! Sicherlich wird die Hand des HERRN ihn treffen, sei es, daß der Tag eines natürlichen Todes für ihn kommt oder daß er in den Krieg zieht und hinweggerafft wird;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 26, 11, 'aber der HERR behüte mich davor, die Hand an den Gesalbten des HERRN zu legen! Nein, nimm jetzt den Speer, der zu seinen Häupten steht, und den Wasserkrug; dann wollen wir gehen!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 26, 12, 'Hierauf nahm David den Speer und den Wasserkrug, der zu Sauls Häupten stand, und sie entfernten sich, ohne daß jemand sie gesehen oder etwas gemerkt hätte, und niemand wachte auf; vielmehr schliefen sie allesamt, weil ein tiefer, vom HERRN gesandter Schlaf auf sie gefallen war.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 26, 13, 'Als dann David auf die gegenüberliegende Seite (des Tales) gekommen und in einiger Entfernung auf die Spitze des Berges getreten war, so daß ein großer Zwischenraum zwischen ihnen lag,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 26, 14, 'rief David dem Kriegsvolk und Abner, dem Sohne Ners, die Worte zu: »Gibst du keine Antwort, Abner?« Da erwiderte Abner: »Wer bist du, daß du dem Könige so zurufst?«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 26, 15, 'David antwortete dem Abner: »Du bist mir fürwahr ein rechter Mann, und deinesgleichen gibt es nicht in ganz Israel! Warum hast du auf deinen Herrn, den König, nicht achtgegeben? Es ist ja einer von den Leuten eingedrungen, um deinen Herrn, den König, zu ermorden!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 26, 16, 'Das bringt dir keine Ehre, was du da getan hast. So wahr der HERR lebt: den Tod habt ihr verdient, weil ihr auf euren Herrn, den Gesalbten Gottes, nicht achtgegeben habt! Und nun sieh doch mal nach, wo der Speer des Königs geblieben ist und wo der Wasserkrug, der zu seinen Häupten gestanden hat!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 26, 17, 'Da erkannte Saul die Stimme Davids und rief aus: »Ist das nicht deine Stimme, mein Sohn David?« David erwiderte: »Jawohl, mein Herr und König!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 26, 18, 'Dann fuhr er fort: »Warum verfolgt mein Herr seinen Knecht? Was habe ich denn verbrochen, und was für Böses klebt an meiner Hand?');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 26, 19, 'Möchte doch mein Herr, der König, jetzt den Worten seines Knechtes Gehör schenken! Wenn Gott es ist, der dich gegen mich erbittert hat, so möge er den Duft einer Opfergabe zu riechen bekommen; wenn es aber Menschen sind, so seien sie verflucht vor Gott, weil sie mich jetzt von der Teilnahme am Erbbesitz des HERRN ausgeschlossen haben, als wollten sie zu mir sagen: ›Hinweg mit dir! Diene anderen Göttern!‹');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 26, 20, 'So möge nun mein Blut nicht fern vom Angesicht Gottes zur Erde fallen! Denn der König von Israel ist ausgezogen, um mein Leben zu erjagen, wie der Habicht auf ein Rebhuhn in den Bergen Jagd macht.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 26, 21, 'Da antwortete Saul: »Ich habe unrecht getan: kehre zurück, mein Sohn David! Denn ich will dir fortan nichts mehr zuleide tun zum Lohn dafür, daß du mein Leben heute verschont hast. Ja, ich habe töricht gehandelt und mich schwer vergangen!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 26, 22, 'Darauf antwortete David: »Siehe, hier ist der Speer des Königs: so komme denn einer von den Leuten herüber und hole ihn!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 26, 23, 'Der HERR aber vergilt einem jeden seine Gerechtigkeit und seine Treue; denn der HERR hatte dich heute in meine Hand gegeben, ich aber habe mich nicht an dem Gesalbten des HERRN vergreifen wollen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 26, 24, 'So wertvoll aber dein Leben heute mir gewesen ist, ebenso wertvoll möge mein Leben dem HERRN sein, daß er mich aus aller Bedrängnis errette!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 26, 25, 'Da rief Saul dem David zu: »Gesegnet seist du, mein Sohn David! Du wirst deine Sache sicherlich durchführen und glücklich ans Ziel gelangen!« Hierauf ging David seines Weges, Saul aber kehrte nach Hause zurück.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 27, 1, 'David aber sagte zu sich selbst: »Eines Tages werde ich doch noch durch Sauls Hand weggerafft werden; es bleibt mir nichts Besseres übrig, als daß ich mich eilends im Lande der Philister in Sicherheit bringe; dann wird Saul davon abstehen, auf mich noch länger in allen Teilen Israels zu fahnden, und ich bin seinen Händen entronnen.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 27, 2, 'So machte David sich denn auf und zog mit den sechshundert Mann, die er bei sich hatte, zu Achis, dem Sohne Maochs, dem König von Gath, hinüber.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 27, 3, 'Er nahm bei diesem seinen Wohnsitz in Gath mit seinen Leuten, ein jeder mit seiner Familie, David selbst mit seinen beiden Frauen, Ahinoam aus Jesreel und Abigail, der Witwe Nabals, aus Karmel.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 27, 4, 'Als nun Saul die Nachricht erhielt, daß David nach Gath entwichen sei, gab er es auf, noch länger nach ihm zu suchen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 27, 5, 'David aber sagte zu Achis: »Wenn du mir eine Gnade erweisen willst, so laß mir einen Platz in einer der Ortschaften des offenen Landes zum Wohnsitz anweisen; denn warum soll dein Knecht bei dir in der Königsstadt wohnen?«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 27, 6, 'Da wies ihm Achis noch an demselben Tage Ziklag an. Infolgedessen hat Ziklag den Königen von Juda bis auf den heutigen Tag gehört.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 27, 7, 'Die ganze Zeit aber, die David im Lande der Philister zubrachte, betrug ein Jahr und vier Monate.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 27, 8, 'David unternahm nun mit seinen Leuten Raubzüge und machte Einfälle in das Gebiet der Gesuriter, der Girsiter und der Amalekiter; denn das sind die Bewohner des Landes von alters her bis nach Sur hin und bis nach Ägypten.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 27, 9, 'Sooft er aber in ihr Land einfiel, ließ er weder Männer noch Frauen am Leben und raubte Kleinvieh, Rinder, Esel, Kamele und Kleidungsstücke; darauf kehrte er wieder zu Achis zurück.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 27, 10, 'Wenn Achis ihn dann fragte: »Wo habt ihr diesmal einen Einfall gemacht?«, so antwortete David: »Im Südland von Juda« oder »im Südland der Jerahmeeliter« oder »im Südland der Keniter«.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 27, 11, 'Männer und Frauen aber ließ David deshalb nicht am Leben, um sie nicht nach Gath mitnehmen zu müssen; denn er dachte: »Sie könnten gegen uns aussagen und berichten: ›So und so ist David zu Werke gegangen.‹« Dieses Verfahren beobachtete David während der ganzen Zeit, die er im Lande der Philister zubrachte.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 27, 12, 'Achis aber schenkte dem David Vertrauen, weil er dachte: »Er hat sich bei seinem Volk, bei Israel, tödlich verhaßt gemacht; darum wird er für immer mein Dienstmann bleiben.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 28, 1, 'Als nun die Philister in jener Zeit ihre Heere zu einem Kriegszuge gegen die Israeliten sammelten, sagte Achis zu David: »Du sollst bestimmt wissen, daß du samt deinen Leuten mit mir im Heerbann ausziehen mußt.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 28, 2, 'David antwortete ihm: »Gut! Du wirst nun sehen, was dein Knecht zu leisten vermag.« Achis erwiderte dem David: »Gut! Ich ernenne dich auf Lebenszeit zum Hüter meines Hauptes.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 28, 3, 'Samuel aber war gestorben, und ganz Israel hatte die Totenklage um ihn gehalten und ihn in seiner Vaterstadt Rama begraben. Saul aber hatte die Totenbeschwörer und Wahrsager aus dem Lande vertrieben. –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 28, 4, 'Nachdem sich nun die Philister gesammelt hatten und ins Land eingefallen waren, lagerten sie sich bei Sunem, während Saul, der ganz Israel aufgeboten hatte, sein Lager auf dem (Gebirge) Gilboa aufschlug.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 28, 5, 'Als nun Saul das Heerlager der Philister erblickte, geriet er in Angst und erschrak im innersten Herzen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 28, 6, 'Er befragte daher den HERRN, aber der HERR gab ihm keine Antwort weder durch Träume, noch durch das Priester-Orakel, noch durch die Propheten.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 28, 7, 'Da gab Saul seinen Dienern den Befehl: »Macht mir eine Frau ausfindig, die sich auf Totenbeschwörung versteht: ich will zu ihr gehen und sie befragen.« Seine Diener antworteten ihm: »In Endor wohnt eine Frau, die Tote zu beschwören vermag.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 28, 8, 'Da machte sich Saul unkenntlich, legte andere Kleider an und begab sich mit zwei Begleitern auf den Weg. Als sie nachts bei der Frau angekommen waren, sagte er zu ihr: »Wahrsage mir durch Totenbeschwörung und laß mir aus der Unterwelt den erscheinen, den ich dir nennen werde.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 28, 9, 'Aber die Frau antwortete ihm: »Du weißt doch selbst, was Saul getan hat: daß er die Totenbeschwörer und Wahrsager im Lande ausgerottet hat; warum stellst du mir also eine Falle, um mich ums Leben zu bringen?«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 28, 10, 'Da schwur ihr Saul beim HERRN: »So wahr der HERR lebt, es soll dich in diesem Falle keine Schuld treffen!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 28, 11, 'Da fragte das Weib: »Wen soll ich dir heraufbringen?« Er antwortete: »Laß mir Samuel erscheinen!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 28, 12, 'Als nun die Frau Samuel anblickte, schrie sie laut auf und sagte zu Saul: »Warum hast du mich betrogen? Du bist ja Saul!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 28, 13, 'Der König erwiderte ihr: »Fürchte dich nicht! Sondern (sage): was siehst du?« Die Frau antwortete ihm: »Ein Götterwesen sehe ich aus der Erde aufsteigen.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 28, 14, 'Da fragte er sie: »Wie sieht es aus?« Sie antwortete: »Ein alter Mann steigt herauf, in einen Mantel eingehüllt.« Da erkannte Saul, daß es Samuel war; er neigte sich also mit dem Antlitz zur Erde und bezeugte ihm seine Ehrfurcht.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 28, 15, 'Samuel aber sprach zu Saul: »Warum störst du mich in meiner Ruhe, daß du mich heraufkommen läßt?« Saul erwiderte: »Ich befinde mich in großer Not; denn die Philister haben Krieg mit mir angefangen, Gott aber hat mich verlassen und gibt mir keine Antwort mehr weder durch die Propheten noch durch Träume; darum habe ich dich rufen lassen, um von dir zu erfahren, was ich tun soll.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 28, 16, 'Samuel antwortete: »Was fragst du mich denn, da doch der HERR dich verlassen hat und dein Feind geworden ist?');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 28, 17, 'Der HERR hat dir so getan, wie er dir durch mich hat ankündigen lassen: der HERR hat dir das Königtum entrissen und es einem andern, dem David, gegeben.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 28, 18, 'Weil du dem Befehl des HERRN nicht gehorcht und seinen lodernden Zorn an den Amalekitern nicht vollzogen hast, darum hat der HERR dich jetzt in diese Lage kommen lassen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 28, 19, 'Und der HERR wird auch die Israeliten zugleich mit dir in die Gewalt der Philister fallen lassen: morgen wirst du mitsamt deinen Söhnen bei mir sein, auch das Heer der Israeliten wird der HERR in die Gewalt der Philister fallen lassen!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 28, 20, 'Da fiel Saul voller Entsetzen seiner ganzen Länge nach zu Boden: solchen Eindruck hatten die Worte Samuels auf ihn gemacht; auch hatte er keine Kraft mehr in sich, weil er während des ganzen Tages und der ganzen Nacht keine Nahrung zu sich genommen hatte.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 28, 21, 'Als die Frau nun an ihn herantrat und bemerkte, daß er ganz fassungslos war, sagte sie zu ihm: »Siehe, deine Magd ist deiner Aufforderung nachgekommen, und ich habe mein Leben aufs Spiel gesetzt und deinen Wunsch erfüllt, den du gegen mich ausgesprochen hast.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 28, 22, 'So schenke nun auch du deiner Magd Gehör und laß mich dir ein wenig zu essen vorsetzen: iß nun, damit du die nötigen Kräfte für den Rückweg besitzest.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 28, 23, 'Er schlug aber alles ab und erklärte: »Ich mag nichts essen!« Als dann aber seine Begleiter und auch die Frau in ihn drangen, gab er ihrer Aufforderung nach; er stand vom Boden auf und setzte sich auf das Lager.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 28, 24, 'Die Frau aber hatte ein gemästetes Kalb im Hause, das sie in aller Eile schlachtete; weiter nahm sie Mehl, knetete es und buk Brotkuchen daraus;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 28, 25, 'das setzte sie Saul und seinen Begleitern vor. Nachdem sie dann gegessen hatten, machten sie sich noch in derselben Nacht auf den Rückweg.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 29, 1, 'Als nun die Philister ihre gesamte Heeresmacht bei Aphek gesammelt hatten – die Israeliten aber hatten sich an der Quelle bei Jesreel gelagert –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 29, 2, 'und die Fürsten der Philister nach ihren Hundertschaften und Tausendschaften aufzogen und zuletzt auch David und seine Leute mit Achis aufmarschierten,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 29, 3, 'da riefen die Fürsten der Philister: »Was sollen diese Hebräer da?« Achis erwiderte den Fürsten der Philister: »Das ist ja David, der Diener des Königs Saul von Israel, der schon seit Jahr und Tag bei mir gewesen ist, ohne daß ich an ihm, seitdem er zu mir übergetreten ist, bis heute etwas Verdächtiges bemerkt hätte.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 29, 4, 'Aber die Fürsten der Philister wurden ungehalten über ihn und sagten zu ihm: »Schicke den Mann zurück! Er soll wieder an den Ort zurückkehren, den du ihm angewiesen hast, und soll nicht mit uns in den Krieg ziehen, damit er nicht in der Schlacht zum Verräter an uns wird. Denn womit könnte der sich wohl besser in Gunst bei seinem Herrn setzen als auf Kosten der Köpfe unserer Leute?');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 29, 5, 'Das ist ja derselbe David, dem zu Ehren sie beim Reigentanz das Lied singen: ›Saul hat seine Tausende geschlagen, aber David seine Zehntausende.‹«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 29, 6, 'Da ließ Achis David rufen und sagte zu ihm: »So wahr Gott lebt! Du bist ein Ehrenmann, und mir würde es lieb sein, wenn du den Feldzug mit mir im Heere mitmachtest; denn ich habe an dir nichts zu tadeln gefunden, seitdem du zu mir gekommen bist, bis auf den heutigen Tag. Aber den übrigen Fürsten bist du nicht erwünscht.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 29, 7, 'Daher kehre jetzt zurück und ziehe in Frieden heim, damit du nichts tust, was den Fürsten der Philister mißfällt!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 29, 8, 'David antwortete dem Achis: »Was habe ich denn getan, und was hast du an deinem Knecht Verwerfliches gefunden, seitdem ich in deinen Dienst getreten bin, bis zum heutigen Tage, daß ich nicht mitziehen und kämpfen darf gegen die Feinde meines Herrn, des Königs?«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 29, 9, 'Da antwortete Achis dem David: »Ich weiß, daß du mir so lieb bist wie ein Engel Gottes; jedoch die (anderen) Fürsten der Philister haben erklärt, du dürfest nicht neben ihnen in den Krieg ziehen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 29, 10, 'Daher mache dich morgen früh auf den Weg, du und die Knechte deines Herrn, die mit dir hergekommen sind; brecht also in aller Frühe auf, sobald es Tag wird, und zieht ab!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 29, 11, 'So machte sich denn David mit seinen Leuten am nächsten Morgen in aller Frühe auf den Weg, um ins Land der Philister zurückzukehren; die Philister aber zogen hinauf nach Jesreel.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 30, 1, 'Als nun David mit seinen Leuten am dritten Tage in Ziklag ankam, hatten die Amalekiter einen Einfall in das Südland und in Ziklag gemacht und hatten Ziklag geplündert und niedergebrannt.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 30, 2, 'Die Frauen und alles, was im Orte anwesend war, klein und groß, hatten sie gefangengenommen, ohne jedoch jemand zu töten, hatten sie dann weggeführt und waren ihres Weges gezogen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 30, 3, 'Als nun David und seine Leute zu der Stadt zurückkamen und sie niedergebrannt und ihre Frauen, Söhne und Töchter in Gefangenschaft weggeführt fanden,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 30, 4, 'da erhoben David und seine Leute ein lautes Wehgeschrei und weinten, bis sie keine Kraft mehr zum Weinen hatten.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 30, 5, 'Auch die beiden Frauen Davids waren gefangen weggeführt worden, Ahinoam aus Jesreel und Abigail, die Witwe Nabals, aus Karmel.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 30, 6, 'David aber geriet persönlich in große Gefahr, weil seine Leute schon daran dachten, ihn zu steinigen; denn sie waren alle über den Verlust ihrer Söhne und Töchter ganz verzweifelt. David aber gewann neue Kraft durch sein Vertrauen auf den HERRN, seinen Gott,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 30, 7, 'und befahl dem Priester Abjathar, dem Sohne Ahimelechs: »Bringe mir das Priesterkleid her!« Als nun Abjathar das Priesterkleid zu David brachte,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 30, 8, 'richtete David die Frage an den HERRN: »Soll ich dieser Räuberschar nachsetzen? Werde ich sie einholen?« Da erhielt er die Antwort: »Ja, verfolge sie! Du wirst sie sicher einholen und (die Gefangenen) befreien.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 30, 9, 'Da machte sich David mit den sechshundert Mann, die er bei sich hatte, auf den Weg, und sie kamen an den Bach Besor (wo sie zweihundert Mann zurückließen).');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 30, 10, 'David aber setzte die Verfolgung mit vierhundert Mann fort, während zweihundert Mann, die zu ermüdet waren, um über den Bach Besor zu gehen, zurückbleiben mußten.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 30, 11, 'Da fanden sie einen Ägypter auf freiem Felde, den brachten sie zu David; und als sie ihm Brot zu essen und Wasser zu trinken gegeben');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 30, 12, 'und ihm auch ein Stück Feigenkuchen und zwei Rosinentrauben zu essen gegeben hatten, kam er wieder zu sich; denn er hatte seit drei Tagen und drei Nächten nichts gegessen und nichts getrunken.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 30, 13, 'David fragte ihn nun: »Wem gehörst du, und woher bist du?« Er antwortete: »Ich bin ein ägyptischer Bursche, der Sklave eines Amalekiters; mein Herr hat mich hier liegen lassen, weil ich heute vor drei Tagen krank geworden war.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 30, 14, 'Wir hatten einen Einfall gemacht ins Südland der Kreter und ins Gebiet von Juda und ins Südland von Kaleb und haben Ziklag niedergebrannt.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 30, 15, 'Da fragte ihn David: »Willst du mich zu dieser Räuberschar hinabführen?« Er erwiderte: »Schwöre mir bei Gott, daß du mich nicht töten und mich nicht meinem Herrn ausliefern willst, so will ich dich zu dieser Horde hinabführen.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 30, 16, 'Als er ihn nun hinabführte, hatten (die Amalekiter) sich weithin über die ganze Gegend zerstreut, aßen und tranken und feierten ein Freudenfest wegen all der großen Beute, die sie im Lande der Philister und im Lande Juda gewonnen hatten.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 30, 17, 'Da richtete David (am folgenden Tage) ein Blutbad unter ihnen an vom frühen Morgen bis zum Abend, und keiner von ihnen entkam außer vierhundert jungen Leuten, welche die Kamele bestiegen hatten und entflohen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 30, 18, 'So fiel dem David alles in die Hände, was die Amalekiter geraubt hatten; auch seine beiden Frauen gewann er wieder,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 30, 19, 'so daß von ihnen nicht das Geringste vermißt wurde, weder Söhne noch Töchter, auch nichts von der Beute; überhaupt alles, was sie mit sich genommen hatten, brachte David zurück.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 30, 20, 'David nahm dann alles Kleinvieh und die Rinder; die trieben sie vor der andern Herde her und riefen: »Das ist Davids Beute!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 30, 21, 'Als David dann zu den zweihundert Mann zurückkam, die zu ermattet gewesen waren, um mit David weiterzuziehen, und die man deshalb am Bache Besor zurückgelassen hatte, kamen diese ihm und seinen Leuten entgegengezogen; David ging auf die Leute zu und begrüßte sie freundlich.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 30, 22, 'Da ließen alle bösen und nichtswürdigen Leute unter der Mannschaft, die mit David gezogen waren, sich dahin vernehmen: »Weil sie nicht mit uns gezogen sind, wollen wir ihnen auch von der Beute, die wir wiedergewonnen haben, nichts abgeben als nur einem jeden seine Frau und seine Kinder; die mögen sie hinnehmen und dann ihres Weges ziehen!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 30, 23, 'Aber David sagte: »Verfahrt nicht so, meine Brüder, mit dem, was der HERR uns hat zuteil werden lassen! Er hat uns ja beschützt und die Räuberbande, die bei uns eingedrungen war, in unsere Hand fallen lassen:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 30, 24, 'wer könnte da in dieser Sache eurer Ansicht beitreten? Nein, der Anteil dessen, der beim Gepäck Wache gehalten hat, soll ebenso groß sein wie der Anteil dessen, der in den Kampf gezogen ist: gleichen Anteil sollen sie erhalten!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 30, 25, 'Und dabei ist es seit jenem Tage in der Folgezeit geblieben; man hat das zu einem feststehenden Grundsatz in Israel gemacht bis auf den heutigen Tag.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 30, 26, 'Als David dann nach Ziklag zurückkam, sandte er Teile der Beute an die ihm befreundeten Ältesten von Juda und ließ ihnen dabei sagen: »Hier habt ihr eine Begrüßungsgabe aus der Beute von den Feinden des HERRN!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 30, 27, 'Solche Geschenke sandte er an die Ältesten von Bethel und von Ramath im Südland sowie an die von Jatthir,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 30, 28, 'von Aroer, von Siphmoth, von Esthemoa,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 30, 29, 'von Rachal und von den Ortschaften der Jerahmeeliter und der Keniter;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 30, 30, 'ferner an die Ältesten von Horma, von Bor-Asan, von Athach,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 30, 31, 'von Hebron und an alle Ortschaften, wo David mit seinen Leuten umhergezogen war.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 31, 1, 'Als es aber zwischen den Philistern und Israeliten zur Schlacht kam, wurden die Israeliten von den Philistern in die Flucht geschlagen, und viele Erschlagene lagen auf dem Gebirge Gilboa umher.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 31, 2, 'Die Philister setzten Saul und seinen Söhnen hart zu und erschlugen Sauls Söhne Jonathan, Abinadab und Malchisua.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 31, 3, 'Als dann ein wilder Kampf um Saul her entstand und die Bogenschützen ihn ausfindig gemacht hatten, da ward er von den Bogenschützen in den Unterleib getroffen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 31, 4, 'Da befahl Saul seinem Waffenträger: »Ziehe dein Schwert und durchbohre mich damit, auf daß nicht diese Heiden kommen und ihren Mutwillen an mir auslassen!« Aber sein Waffenträger weigerte sich, weil er sich zu sehr fürchtete. Da nahm Saul das Schwert und stürzte sich hinein.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 31, 5, 'Als nun sein Waffenträger sah, daß Saul tot war, stürzte er sich gleichfalls in sein Schwert und starb neben ihm.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 31, 6, 'So fanden Saul, seine drei Söhne und sein Waffenträger an jenem Tage zusammen ihren Tod.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 31, 7, 'Als aber die Israeliten, die in den Städten der Ebene (Jesreel) und in den Städten am Jordan wohnten, sahen, daß die Israeliten geflohen und daß Saul samt seinen Söhnen gefallen war, verließen sie ihre Städte und ergriffen die Flucht; da kamen die Philister und setzten sich darin fest.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 31, 8, 'Als dann am nächsten Tage die Philister kamen, um die Gefallenen auszuplündern, fanden sie die Leichen Sauls und seiner drei Söhne auf dem Gebirge Gilboa liegen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 31, 9, 'Da hieben sie ihm den Kopf ab, zogen ihm seine Rüstung aus und sandten (Boten) in allen Teilen des Philisterlandes umher, um die Siegesbotschaft in ihren Götzentempeln und unter dem Volke zu verkünden.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 31, 10, 'Seine Waffen legten sie im Tempel der Astarte nieder, seine Leiche aber hängten sie an der Mauer von Beth-San auf.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 31, 11, 'Als aber die Einwohner von Jabes in Gilead erfuhren, was die Philister an Saul verübt hatten,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 31, 12, 'machten sich alle streitbaren Männer auf, marschierten die ganze Nacht hindurch und nahmen den Leichnam Sauls und die Leichen seiner Söhne von der Mauer von Beth-San herab, kehrten mit ihnen nach Jabes zurück und verbrannten sie dort.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 31, 13, 'Hierauf nahmen sie ihre Gebeine, begruben sie unter der Tamariske in Jabes und hielten sieben Tage lang ein Fasten.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 1, 1, 'Nach Sauls Tode nun, als David von dem Siege über die Amalekiter (nach Ziklag) zurückgekehrt war und zwei Tage in Ziklag zugebracht hatte,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 1, 2, 'da kam plötzlich am dritten Tage ein Mann aus dem Lager von Saul her mit zerrissenen Kleidern und mit Erde auf dem Haupt; und als er bei David angekommen war, warf er sich vor ihm zur Erde nieder und brachte ihm seine Huldigung dar.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 1, 3, 'Auf Davids Frage, woher er komme, gab er die Antwort: »Aus dem Lager der Israeliten bin ich entronnen.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 1, 4, 'Als David ihn dann aufforderte: »Erzähle mir doch, wie die Sache sich zugetragen hat!«, berichtete er: »Das Heer ist aus der Schlacht geflohen, und viele von den Leuten sind gefallen und ums Leben gekommen; auch Saul und sein Sohn Jonathan sind tot.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 1, 5, 'Als nun David den jungen Mann, der ihm die Meldung brachte, weiter fragte: »Woher weißt du, daß Saul und sein Sohn Jonathan tot sind?«,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 1, 6, 'berichtete ihm der junge Mann, der ihm die Meldung brachte: »Ich kam ganz zufällig auf das Gebirge Gilboa; da sah ich plötzlich Saul, der sich auf seinen Speer stützte, während die Wagen und Reiter ihn eingeholt hatten.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 1, 7, 'Als er sich nun umwandte und mich erblickte, rief er mich an, und ich antwortete: ›Hier bin ich!‹');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 1, 8, 'Er fragte mich dann, wer ich sei, und ich erwiderte ihm: ›Ich bin ein Amalekiter!‹');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 1, 9, 'Da befahl er mir: ›Tritt her zu mir und töte mich vollends! Denn ein Schwindel hat mich ergriffen, und doch bin ich noch bei vollem Bewußtsein.‹');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 1, 10, 'Da trat ich zu ihm und tötete ihn vollends; denn ich wußte, daß er seinen Fall nicht überleben würde. Dann nahm ich den Stirnreif von seinem Haupt und die Spange, die sich an seinem Arm befand, und überbringe sie hier meinem Herrn.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 1, 11, 'Da faßte David seine Kleider und zerriß sie; ebenso taten alle Männer, die bei ihm waren;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 1, 12, 'sie hielten die Totenklage und weinten und fasteten bis zum Abend um Saul und seinen Sohn Jonathan, um das Volk des HERRN und um das Haus Israel, weil sie durch das Schwert gefallen waren.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 1, 13, 'Hierauf fragte David den jungen Mann, der ihm die Meldung gebracht hatte: »Woher bist du?« Er antwortete: »Ich bin der Sohn eines amalekitischen Fremdlings.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 1, 14, 'Da rief David aus: »Wie? Du hast dich nicht gescheut, deine Hand zu erheben, um dem Gesalbten des HERRN das Leben zu nehmen?!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 1, 15, 'Hierauf rief David einen von seinen Leuten herbei und befahl ihm: »Tritt herzu! Stoß ihn nieder!« Der hieb ihn nieder, daß er starb,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 1, 16, 'während David ihm noch zurief: »Dein Blut komme über dein Haupt! Denn dein eigener Mund hat Zeugnis gegen dich abgelegt durch dein Bekenntnis: ›Ich habe den Gesalbten des HERRN getötet.‹«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 1, 17, 'David stimmte dann folgendes Klagelied auf Saul und dessen Sohn Jonathan an');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 1, 18, 'und befahl, man solle es [das Bogenlied] die Söhne Judas lehren; es steht bekanntlich aufgezeichnet im ›Buch des Braven‹:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 1, 19, 'Ach, (deine) Zier, o Israel, liegt erschlagen auf deinen Höhen wie sind die Helden gefallen!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 1, 20, 'Verkündet es nicht zu Gath, meldet es nicht auf Askalons Straßen, damit die Töchter der Philister sich nicht freun, die Töchter der Heiden nicht jubeln!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 1, 21, 'Ihr Berge Gilboas, kein Tau, kein Regen müsse noch auf euch fallen, kein Gefilde auf euch sein, von dem Erstlingsgaben kommen! Denn dort liegt der Schild der Helden weggeworfen, der Schild Sauls, den kein Öl mehr salben wird.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 1, 22, 'Ohne Blut der Durchbohrten, ohne Fett der Helden ist Jonathans Bogen nie zurückgekommen und Sauls Schwert nie ohne Beute heimgekehrt.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 1, 23, 'Saul und Jonathan, die Geliebten und Holden, im Leben und auch im Tod sind vereint sie geblieben; sie waren schneller als Adler, stärker als Löwen!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 1, 24, 'Ihr Töchter Israels, weinet um Saul, der in Purpur euch köstlich gekleidet, der Goldschmuck auf eure Gewänder geheftet!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 1, 25, 'Wie sind die Helden gefallen mitten im Kampf! Jonathan liegt durchbohrt auf deinen Höhen!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 1, 26, 'Wie ist mir leid um dich, mein Bruder Jonathan, wie warst du mir so lieb! Beseligend war mir deine Liebe, mehr als Frauenliebe!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 1, 27, 'Ach, wie sind die Helden gefallen, vernichtet die Rüstzeuge des Kampfes!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 2, 1, 'Hierauf fragte David beim HERRN an: »Soll ich in eine der Städte Judas hinaufziehen?« Der HERR antwortete ihm: »Ja, ziehe hinauf.« Als David weiter fragte: »Wohin soll ich ziehen?«, erhielt er die Antwort: »Nach Hebron.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 2, 2, 'So zog denn David dorthin samt seinen beiden Frauen Ahinoam aus Jesreel und Abigail, der Witwe Nabals, aus Karmel;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 2, 3, 'auch seine Kriegsleute, die bei ihm waren, ließ er alle samt ihren Familien hinaufziehen, und sie ließen sich in den zu Hebron gehörigen Ortschaften nieder.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 2, 4, 'Da kamen die Männer von Juda und salbten David dort zum König über den Stamm Juda. Als man dann David die Nachricht brachte, daß die Männer von Jabes in Gilead es seien, die Saul begraben hätten,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 2, 5, 'da sandte David Boten an die Einwohner von Jabes in Gilead und ließ ihnen sagen: »Der Segen des HERRN möge euch dafür zuteil werden, daß ihr Saul, eurem Herrn, diese Liebe erwiesen und ihn begraben habt!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 2, 6, 'So möge nun der HERR euch Güte und Treue erweisen! Und auch ich will euch dafür belohnen, daß ihr so gehandelt habt.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 2, 7, 'Jetzt aber seid guten Mutes und beweist euch als wackere Männer! Denn Saul, euer Herr, ist (zwar) tot, aber der Stamm Juda hat mich zum König über sich gesalbt.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 2, 8, 'Abner aber, der Sohn Ners, der Heerführer Sauls, nahm Sauls Sohn Isboseth, brachte ihn nach Mahanaim hinüber');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 2, 9, 'und machte ihn dort zum König über Gilead, über Asser, über Jesreel, Ephraim, Benjamin, überhaupt über ganz Israel.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 2, 10, 'Vierzig Jahre war Isboseth, der Sohn Sauls, alt, als er König über Israel wurde, und zwei Jahre lang hat er regiert; nur der Stamm Juda hielt zu David.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 2, 11, 'Die Zeit aber, die David als König über den Stamm Juda in Hebron regiert hat, betrug sieben Jahre und sechs Monate.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 2, 12, 'Einst zog Abner, der Sohn Ners, mit den Leuten Isboseths, des Sohnes Sauls, von Mahanaim nach Gibeon;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 2, 13, 'ebenso rückte Joab, der Sohn der Zeruja, mit den Leuten Davids (von Hebron) aus; beide Heere stießen dann am Teiche von Gibeon aufeinander und lagerten sich, das eine diesseits, das andere jenseits des Teiches.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 2, 14, 'Da ließ Abner dem Joab sagen: »Die jungen Leute könnten ja einmal auftreten und ein Kampfspiel vor unsern Augen aufführen!« Joab ließ antworten: »Gut! Es soll geschehen!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 2, 15, 'Da machten sie sich auf und traten einander abgezählt paarweise gegenüber: zwölf aus Benjamin für Isboseth, den Sohn Sauls, und zwölf von den Leuten Davids.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 2, 16, 'Da faßte jeder seinen Gegner beim Schopf und stieß ihm das Schwert in die Seite, so daß sie insgesamt fielen; daher nannte man jenen Ort ›Feld der Klingen‹; er liegt bei Gibeon.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 2, 17, 'Als sich darauf an diesem Tage ein überaus erbitterter Kampf entspann, wurde Abner und das Heer der Israeliten von den Leuten Davids in die Flucht geschlagen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 2, 18, 'Es befanden sich aber dort (im Heere Davids) die drei Söhne der Zeruja: Joab, Abisai und Asahel, von denen Asahel schnellfüßig war wie eine Gazelle auf dem Felde.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 2, 19, 'Als nun Asahel den Abner verfolgte, ohne weder nach rechts noch nach links bei der Verfolgung hinter Abner abzubiegen,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 2, 20, 'wandte Abner sich um und rief: »Bist du es, Asahel?« Er antwortete: »Jawohl.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 2, 21, 'Da rief Abner ihm zu: »Wende dich doch nach links oder nach rechts (von mir) ab und mache dich an einen von den Leuten und nimm dir seine Rüstung!« Aber Asahel wollte nicht von ihm ablassen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 2, 22, 'Da rief Abner ihm noch einmal zu: »Gehe hinter mir weg! Warum soll ich dich zu Boden schlagen? Wie könnte ich dann noch deinem Bruder Joab vor die Augen treten?«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 2, 23, 'Als er trotzdem die Verfolgung nicht aufgeben wollte, stieß ihn Abner mit dem unteren Ende seines Speeres in den Unterleib, so daß der Speer hinten herausdrang und er dort zu Boden stürzte und an jener Stelle starb. Alle aber, die zu der Stelle kamen, wo Asahel gefallen und gestorben war, blieben stehen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 2, 24, 'Joab aber und Abisai setzten die Verfolgung Abners fort und waren bei Sonnenuntergang bis zum Hügel Amma gelangt, der Giah gegenüber in der Richtung nach der Wüste Gibeon zu liegt.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 2, 25, 'Hier sammelten sich die Benjaminiten hinter Abner her, bildeten eine geschlossene Schar und setzten sich oben auf dem Hügel fest.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 2, 26, 'Nun rief Abner dem Joab die Worte zu: »Soll denn das Schwert ewig fressen? Siehst du nicht, daß ein Verzweiflungskampf das Ende sein wird? Wann wirst du endlich deinen Leuten befehlen, von der Verfolgung ihrer Brüder abzustehen?«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 2, 27, 'Joab erwiderte: »So wahr Gott lebt! Hättest du nicht geredet, so hätten die Leute insgesamt erst morgen früh von der Verfolgung ihrer Brüder abgelassen!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 2, 28, 'Hierauf ließ Joab ein Zeichen mit der Posaune geben, und sofort machte das ganze Heer halt, gab die weitere Verfolgung der Israeliten auf und setzte den Kampf nicht fort.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 2, 29, 'Abner marschierte nun mit seinen Leuten während der ganzen folgenden Nacht durch die Jordanebene, überschritt dann den Jordan, durchzog das ganze Tal Bithron und gelangte so nach Mahanaim. –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 2, 30, 'Als Joab aber die Verfolgung Abners aufgegeben und seine ganze Mannschaft wieder gesammelt hatte, wurden von den Leuten Davids außer Asahel nur neunzehn Mann vermißt,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 2, 31, 'während Davids Leute von den Benjaminiten und den übrigen Leuten Abners 360 Mann erschlagen hatten.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 2, 32, 'Den Asahel aber hob man auf und begrub ihn im Begräbnis seines Vaters zu Bethlehem. Joab aber und seine Leute marschierten die ganze Nacht hindurch, bis sie bei Tagesanbruch in Hebron ankamen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 1, 'Der Krieg zwischen dem Hause Sauls und dem Hause Davids zog sich dann in die Länge; aber Davids Macht nahm immerfort zu, während das Haus Sauls immer schwächer wurde.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 2, 'In Hebron wurden dem David folgende Söhne geboren: sein Erstgeborener war Amnon, von Ahinoam aus Jesreel;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 3, 'sein zweiter Sohn Kileab, von Abigail, der Witwe Nabals, aus Karmel; der dritte Absalom, der Sohn der Maacha, der Tochter Thalmais, des Königs von Gesur;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 4, 'der vierte Adonia, der Sohn der Haggith; der fünfte Sephatja, der Sohn der Abital;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 5, 'der sechste Jithream, von Davids Frau Egla. Diese wurden dem David in Hebron geboren.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 6, 'Solange nun der Krieg zwischen dem Hause Sauls und dem Hause Davids währte, hielt Abner treu zum Hause Sauls.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 7, 'Saul hatte aber ein Nebenweib gehabt namens Rizpa, eine Tochter Ajas. Nun richtete (Isboseth) eines Tages die Frage an Abner: »Warum hast du ein Verhältnis mit dem Nebenweibe meines Vaters gehabt?«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 8, 'Über diese Äußerung Isboseths geriet Abner in heftigen Zorn, so daß er ausrief: »Bin ich denn ein judäischer Hundskopf?! Bis heute habe ich dem Hause deines Vaters Saul und seinen Verwandten und Freunden treu gedient und dich nicht in Davids Hände fallen lassen, und doch wirfst du mir heute eine Verschuldung mit einem Weibe vor?');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 9, 'So möge denn Gott mich, Abner, jetzt und künftighin strafen, wenn ich nicht das, was der HERR dem David zugeschworen hat, jetzt für ihn verwirkliche,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 10, 'daß ich nämlich das Königtum dem Hause Sauls nehme und den Thron Davids über Israel und über Juda aufrichte von Dan bis Beerseba!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 11, 'Da vermochte jener dem Abner kein Wort mehr zu erwidern: so fürchtete er sich vor ihm.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 12, 'Darauf sandte Abner auf der Stelle Boten zu David und ließ (ihm) sagen: »Wem gehört das Land? Schließe einen Vertrag mit mir, dann stelle ich mich dir zur Verfügung, um ganz Israel auf deine Seite zu bringen.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 13, '(David) gab zur Antwort: »Gut! Ich will einen Vertrag mit dir schließen; doch fordere ich eins von dir, nämlich: du darfst mir nicht vor die Augen treten, es sei denn, daß du Sauls Tochter Michal mitbringst, wenn du herkommst, um vor mir zu erscheinen.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 14, 'Zugleich schickte David aber auch Gesandte an Isboseth, den Sohn Sauls, mit der Forderung: »Gib mir meine Gattin Michal zurück, die ich mir um den Preis von hundert Vorhäuten der Philister zur Frau gewonnen habe!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 15, 'Da sandte Isboseth hin und ließ sie ihrem Gatten Paltiel, dem Sohne des Lais, wegnehmen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 16, 'Ihr Gatte aber ging mit ihr und begleitete sie unter beständigem Weinen bis Bachurim; dann, als Abner ihn aufforderte, heimzugehen, kehrte er nach Hause zurück.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 17, 'Abner aber hatte mit den Ältesten von Israel Verhandlungen angeknüpft und ihnen vorgestellt: »Schon längst habt ihr David zum König über euch gewünscht:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 18, 'so führt es denn jetzt aus! Denn der HERR hat im Hinblick auf David verheißen: ›Durch die Hand meines Knechtes David will ich mein Volk Israel aus der Gewalt der Philister und aller seiner Feinde befreien.‹«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 19, 'Ebenso hatte Abner auch mit den Benjaminiten heimlich unterhandelt; und endlich machte er sich auf den Weg, um David in Hebron persönlich alles mitzuteilen, was Israel und der ganze Stamm Benjamin beschlossen hatten.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 20, 'Als nun Abner in Begleitung von zwanzig Männern zu David nach Hebron kam und David ihm und seinen Begleitern ein Festmahl hatte ausrichten lassen,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 21, 'sagte Abner zu David: »Ich will mich jetzt aufmachen und hingehen und ganz Israel um meinen Herrn, den König, sammeln, damit sie einen Vertrag mit dir schließen; dann kannst du als König ganz nach Herzenswunsch regieren!« Darauf entließ David den Abner, der sich in Frieden entfernte.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 22, 'Da aber kamen gerade Davids Leute und Joab von einem Streifzug zurück und brachten reiche Beute mit, als Abner sich bereits nicht mehr bei David in Hebron befand, sondern dieser ihn entlassen hatte, so daß er in Frieden heimzog.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 23, 'Als nun Joab mit der ganzen Mannschaft, die bei ihm war, heimkam und man ihm berichtete: »Abner, der Sohn Ners, ist zum König gekommen, und der hat ihn ruhig wieder ziehen lassen«,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 24, 'da ging Joab zum König hinein und sagte: »Was hast du da getan? Ich weiß, Abner ist bei dir gewesen: warum hast du ihn nun ungehindert wieder ziehen lassen?');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 25, 'Du mußt doch Abner, den Sohn Ners, so weit kennen, daß er nur gekommen ist, um dich zu überlisten! Er will nur all dein Tun und Lassen auskundschaften und alles, was du vorhast, erkunden.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 26, 'Als Joab dann David verlassen hatte, sandte er Boten hinter Abner her, die ihn von der Zisterne Sira wieder zurückholen mußten, ohne daß David etwas davon wußte.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 27, 'Als Abner nun nach Hebron zurückkam, führte Joab ihn abseits in das Innere des Tores, als wollte er vertraulich mit ihm reden; dort versetzte er ihm einen Stich in den Unterleib, daß er starb – um die Blutrache für seinen Bruder Asahel zu vollziehen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 28, 'Als David hernach die Sache erfuhr, rief er aus: »Ich und mein Königtum sind für immer schuldlos vor dem HERRN an der Ermordung Abners, des Sohnes Ners!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 29, '(Sein Blut) falle auf das Haupt Joabs und auf sein ganzes Geschlecht zurück! Möge es im Hause Joabs nie an Schwindsüchtigen und Aussätzigen fehlen, nie an solchen, die an Krücken gehen, die durchs Schwert fallen und denen es an Brot mangelt!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 30, 'Als nun Joab und sein Bruder Abisai Abner ermordet hatten, weil er ihren Bruder Asahel bei Gibeon im Kampf getötet hatte,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 31, 'befahl David dem Joab und allen Personen, die zu seiner Umgebung gehörten: »Zerreißt eure Kleider, legt Trauergewänder an und stimmt die Totenklage an vor Abners Bahre her!« Der König David aber ging hinter der Bahre her;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 32, 'und als man Abner in Hebron begrub, brach der König am Grabe Abners in lautes Weinen aus, und das ganze Volk weinte mit.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 33, 'Sodann stimmte der König ein Klagelied um Abner an, das da lautete: Mußte Abner sterben, wie ein Gottloser stirbt?');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 34, 'Deine Hände waren nicht gefesselt und deine Füße nicht in Ketten gelegt: nein, du bist gefallen, wie man vor Verbrechern fällt! Da weinte alles Volk noch mehr um ihn.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 35, 'Als dann alles Volk kam, um David zum Essen zu bewegen, solange es noch Tag war, schwur David: »Gott strafe mich jetzt und künftig, wenn ich vor Sonnenuntergang Brot oder irgend etwas anderes genieße!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 36, 'Als alles Volk dies wahrnahm, gefiel es ihnen wohl; überhaupt fand das ganze Verhalten des Königs beim gesamten Volke Beifall;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 37, 'und das ganze Volk, auch ganz Israel, kam an jenem Tage zu der Erkenntnis, daß die Ermordung Abners, des Sohnes Ners, nicht vom Könige ausgegangen war.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 38, 'Auch sagte der König zu seiner Umgebung: »Wißt ihr nicht, daß am heutigen Tage ein Fürst und Großer in Israel gefallen ist?');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 39, 'Ich aber, obgleich zum König gesalbt, bin jetzt noch zu machtlos, und diese Männer, die Söhne der Zeruja, sind zu hart für mich. Der HERR lasse den, der die Freveltat begangen hat, für seinen Frevel büßen!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 4, 1, 'Als nun Sauls Sohn (Isboseth) erfuhr, daß Abner in Hebron ums Leben gekommen war, entsank ihm der Mut, und ganz Israel geriet in Bestürzung.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 4, 2, 'Nun hatte Sauls Sohn Isboseth zwei Männer als Anführer von Streifscharen, der eine hieß Baana, der andere Rechab; beide waren Söhne des Benjaminiten Rimmon von Beeroth – auch Beeroth wird nämlich zu Benjamin gerechnet;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 4, 3, 'jedoch waren die Einwohner von Beeroth nach Gitthaim ausgewandert und sind dort als Schutzbürger bis auf den heutigen Tag seßhaft geblieben. –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 4, 4, 'Sauls Sohn Jonathan aber hatte einen Sohn, der an beiden Füßen lahm war; er war fünf Jahre alt gewesen, als die Nachricht vom Tode Sauls und Jonathans aus Jesreel anlangte; da hatte seine Wärterin ihn auf den Arm genommen und die Flucht ergriffen; aber infolge der Eile bei der Flucht war er ihr entfallen und dadurch lahm geworden; sein Name war Mephiboseth.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 4, 5, 'Die Söhne Rimmons von Beeroth also, Rechab und Baana, machten sich auf und begaben sich zur Zeit der Mittagshitze in das Haus Isboseths, der eben seine Mittagsruhe hielt.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 4, 6, 'Die Türhüterin des Hauses war nämlich gerade beim Reinigen von Weizen eingenickt und schlief; daher konnten sich die beiden Brüder in das Haus einschleichen,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 4, 7, 'drangen in das Schlafgemach ein, wo Isboseth auf seinem Bette lag; sie schlugen ihn tot und hieben ihm den Kopf ab. Dann nahmen sie seinen Kopf, eilten während der ganzen Nacht durch die Jordanebene,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 4, 8, 'kamen mit dem Kopfe Isboseths zu David nach Hebron und sagten zum König: »Hier hast du den Kopf Isboseths, des Sohnes Sauls, deines Feindes, der dir nach dem Leben getrachtet hat! Aber Gott, der HERR, hat heute meinem Herrn, dem König, Rache an Saul und seinen Nachkommen gewährt!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 4, 9, 'Da antwortete David dem Rechab und seinem Bruder Baana, den Söhnen Rimmons von Beeroth: »So wahr der HERR lebt, der mich aus aller Bedrängnis errettet hat:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 4, 10, 'ich habe den Mann, der mir die Nachricht von Sauls Tode brachte und sich für einen Glücksboten hielt, in Ziklag ergreifen und töten lassen und ihm so seinen Botenlohn gezahlt!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 4, 11, 'Wieviel mehr, wenn ruchlose Menschen einen unschuldigen Mann in seinem eigenen Hause auf seiner Lagerstätte ermordet haben: sollte ich da jetzt nicht sein Blut von euch fordern und euch vom Erdboden vertilgen?!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 4, 12, 'Hierauf gab David seinen Leibwächtern Befehl; die hieben sie nieder, schlugen ihnen die Hände und Füße ab und hängten sie am Teiche zu Hebron auf. Den Kopf Isboseths aber nahmen sie und begruben ihn in der Grabstätte Abners zu Hebron.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 5, 1, 'Hierauf fanden sich sämtliche Stämme der Israeliten bei David in Hebron ein und sagten: »Wir sind ja doch von deinem Gebein und Fleisch.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 5, 2, 'Schon früher, als Saul noch unser König war, bist du es gewesen, der Israel ins Feld und wieder heim geführt hat; dazu hat der HERR dir verheißen: ›Du sollst mein Volk Israel weiden, und du sollst Fürst über Israel sein.‹«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 5, 3, 'Als so alle Ältesten der Israeliten zum König nach Hebron gekommen waren, schloß der König David einen Vertrag mit ihnen in Hebron vor dem Angesicht des HERRN; dann salbten sie David zum König über Israel.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 5, 4, 'Dreißig Jahre war David alt, als er König wurde, und vierzig Jahre hat er regiert.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 5, 5, 'Zu Hebron hat er sieben Jahre und sechs Monate über Juda regiert, und in Jerusalem hat er dreiunddreißig Jahre über ganz Israel und Juda regiert.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 5, 6, 'Als hierauf der König mit seinem Heere vor Jerusalem gegen die Jebusiter zog, welche die dortige Gegend bewohnten, sagte man zu David: »Hier wirst du nicht eindringen, sondern die Blinden und Lahmen werden dich vertreiben«; damit wollte man sagen: »David wird hier nicht eindringen.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 5, 7, 'Aber David eroberte die Burg Zion [das ist die jetzige ›Davidsstadt‹].');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 5, 8, 'An jenem Tage sagte David: »Wer die Jebusiter schlägt, indem er den Schacht hinaufsteigt, und ›die Lahmen und die Blinden‹, denen die Seele Davids feind ist ...« Daher rührt das Sprichwort: »Ein Blinder und ein Lahmer darf uns nicht ins Haus kommen.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 5, 9, 'David nahm dann seinen Wohnsitz in der Burg und nannte sie ›Stadt Davids‹; auch führte David Bauten ringsum auf, von der Burg Millo an nach innen zu.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 5, 10, 'Seine Macht wuchs nun immer mehr, weil der HERR, der Gott der Heerscharen, mit ihm war.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 5, 11, 'Und Hiram, der König von Tyrus, schickte Gesandte an David mit Zedernstämmen, dazu Zimmerleute und Steinmetzen, damit sie David ein Haus bauten.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 5, 12, 'Daran erkannte David, daß der HERR ihn als König über Israel bestätigt und daß er sein Königtum zu Ansehen gebracht habe um seines Volkes Israel willen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 5, 13, 'Darauf nahm sich David noch mehr Nebenweiber und Frauen in Jerusalem, nachdem er von Hebron dorthin gekommen war, und es wurden ihm noch mehr Söhne und Töchter geboren.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 5, 14, 'Dies sind die Namen der Söhne, die ihm in Jerusalem geboren wurden: Sammua, Sobab, Nathan, Salomo,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 5, 15, 'Jibhar, Elisua, Nepheg, Japhia,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 5, 16, 'Elisama, Eljada und Eliphelet.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 5, 17, 'Als aber die Philister vernahmen, daß man David zum König über (ganz) Israel gesalbt hatte, zogen die Philister insgesamt heran, um seiner habhaft zu werden. Aber David erhielt Kunde davon und zog nach der Bergfeste (Adullam) hinab.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 5, 18, 'Als nun die Philister herankamen und sich in der Ebene Rephaim ausbreiteten,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 5, 19, 'richtete David die Anfrage an den HERRN: »Soll ich gegen die Philister hinaufziehen? Wirst du sie in meine Hand geben?« Der HERR antwortete ihm: »Ziehe hinauf, ich will die Philister unfehlbar in deine Hand geben.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 5, 20, 'Da zog David nach Baal-Perazim; und als er sie dort geschlagen hatte, rief er aus: »Der HERR hat meine Feinde vor mir her durchbrochen, wie das Wasser einen Damm durchbricht!« Darum hat man jenem Ort den Namen Baal-Perazim gegeben.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 5, 21, 'Da (die Philister) ihre Götzenbilder dort zurückgelassen hatten, nahmen David und seine Leute sie als Beute weg.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 5, 22, 'Die Philister zogen dann nochmals herauf und breiteten sich in der Ebene Rephaim aus.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 5, 23, 'Als David nun den HERRN befragte, antwortete dieser: »Du sollst nicht hinaufziehen ihnen entgegen, sondern umgehe sie, damit du ihnen in den Rücken fällst! Greife sie vom Baka-Gehölz her an!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 5, 24, 'Sobald du dann in den Wipfeln des Baka-Gehölzes das Geräusch von Schritten vernimmst, dann beeile dich! Denn alsdann ist der HERR vor dir her ausgezogen, um das Heer der Philister zu schlagen.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 5, 25, 'Da tat David so, wie der HERR ihm geboten hatte, und richtete ein Blutbad unter den Philistern an von Geba bis in die Gegend von Geser hin.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 6, 1, 'David ließ dann nochmals alle Auserlesenen in Israel zusammenkommen, 30000 Mann;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 6, 2, 'dann machte er sich auf und zog mit dem gesamten Volke, das bei ihm war, nach Baala in Juda, um von dort die Lade Gottes heraufzuholen, die den Namen führt nach Gott, dem HERRN der Heerscharen, der über den Cheruben thront.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 6, 3, 'Man lud die Lade Gottes auf einen neuen Wagen und brachte sie so hinweg aus dem Hause Abinadabs, das auf der Anhöhe lag; und zwar lenkten Ussa und Ahjo, die Söhne Abinadabs, den neuen Wagen');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 6, 4, 'und brachten die Lade weg aus dem Hause Abinadabs, das auf der Anhöhe lag, indem Ussa neben der Lade Gottes herging, während Ahjo vor der Lade einherschritt.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 6, 5, 'David aber und alle Israeliten tanzten vor dem HERRN her mit Aufbietung aller Kräfte und mit Liedern unter Begleitung von Zithern und Harfen, Handpauken, Schellen und Zimbeln.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 6, 6, 'Als sie nun so zur Tenne Nachons gekommen waren, griff Ussa mit der Hand nach der Lade Gottes und hielt sie fest, weil die Rinder zu Fall gekommen waren.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 6, 7, 'Da entbrannte der Zorn des HERRN gegen Ussa, und Gott schlug ihn dort wegen seiner Verfehlung, so daß er dort neben der Lade Gottes starb.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 6, 8, 'Da wurde David tief betrübt, daß der HERR einen solchen Schlag gegen Ussa geführt hatte; daher nannte man jenen Ort Perez-Ussa bis auf den heutigen Tag.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 6, 9, 'David aber geriet an jenem Tage in Furcht vor dem HERRN, so daß er ausrief: »Wie kann da die Lade des HERRN zu mir kommen?!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 6, 10, 'Weil David also die Lade des HERRN nicht zu sich in die Davidsstadt bringen wollte, ließ er sie abseits in das Haus des Gathiters Obed-Edom schaffen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 6, 11, 'So blieb denn die Lade des HERRN ein Vierteljahr lang im Hause des Gathiters Obed-Edom stehen; der HERR aber segnete Obed-Edom und sein ganzes Haus.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 6, 12, 'Als man nun dem König David berichtete, der HERR habe das Haus Obed-Edoms und sein ganzes Besitztum um der Lade Gottes willen gesegnet, da ging David hin und holte die Lade Gottes voller Freude aus dem Hause Obed-Edoms nach der Davidsstadt hinauf');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 6, 13, 'und opferte dabei, als die Träger der Lade des HERRN sechs Schritte gegangen waren, ein Rind und ein Mastkalb.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 6, 14, 'Auch tanzte David mit Aufbietung aller Kraft vor dem HERRN her, wobei er nur mit einem leinenen Schulterkleid umgürtet war.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 6, 15, 'So brachte David mit allen Israeliten die Lade des HERRN unter Jauchzen und Posaunenschall (nach Jerusalem) hinauf.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 6, 16, 'Da begab es sich, als die Lade des HERRN in die Davidsstadt einzog, daß Sauls Tochter Michal zum Fenster hinausschaute; als sie nun den König David so vor dem HERRN her hüpfen und tanzen sah, empfand sie Verachtung für ihn in ihrem Herzen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 6, 17, 'Nachdem man dann die Lade des HERRN hineingebracht und sie an ihren Platz inmitten des Zeltes, das von David für sie aufgeschlagen worden war, niedergesetzt hatte, brachte David Brand- und Heilsopfer vor dem HERRN dar,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 6, 18, 'segnete dann, als er mit der Darbringung der Brand- und Heilsopfer fertig war, das Volk im Namen des HERRN der Heerscharen');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 6, 19, 'und ließ unter das ganze Volk, an sämtliche Israeliten, sowohl an Männer wie an Frauen, an einen jeden einen Brotkuchen, ein Stück Fleisch und einen Rosinenkuchen austeilen. Darauf kehrte jedermann aus dem Volk nach Hause zurück.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 6, 20, 'Als nun David heimkehrte, um seine Familie zu begrüßen, trat Sauls Tochter Michal ihm mit den Worten entgegen: »Wie würdevoll hat sich heute der König von Israel benommen, indem er sich heute vor den Augen der Mägde seiner Untertanen entblößt hat, wie es sonst nur gemeine Leute tun!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 6, 21, 'Da erwiderte David der Michal: »Vor dem HERRN, der mich vor deinem Vater und vor dessen ganzem Hause erwählt hat, um mich zum Fürsten über das Volk des HERRN, über Israel, zu bestellen – ja vor dem HERRN will ich tanzen,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 6, 22, 'auch wenn ich mich dadurch noch tiefer erniedrige als diesmal, und will demütig von mir denken; aber bei den Mägden, von denen du redest – bei ihnen werde ich an Ehre gewinnen.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 6, 23, 'Michal aber, Sauls Tochter, blieb bis an ihren Todestag kinderlos.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 7, 1, 'Als nun der König in seinem Hause wohnte, nachdem der HERR ihm Ruhe vor all seinen Feinden ringsum verschafft hatte,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 7, 2, 'sagte der König (eines Tages) zu dem Propheten Nathan: »Bedenke doch, ich wohne hier in einem Zedernpalast, während die Lade Gottes hinter Zelttüchern steht!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 7, 3, 'Da antwortete Nathan dem König: »Wohlan, führe alles aus, was du im Sinn hast! Denn der HERR ist mit dir!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 7, 4, 'Aber noch in derselben Nacht erging das Wort des HERRN an Nathan folgendermaßen:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 7, 5, '»Gehe hin und sage zu meinem Knecht, zu David: ›So hat der HERR gesprochen: Solltest du mir ein Haus zu meiner Wohnung bauen?');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 7, 6, 'Ich habe ja doch in keinem Hause gewohnt seit der Zeit, als ich die Israeliten aus Ägypten hergeführt habe, bis auf den heutigen Tag, sondern bin in einer Zeltwohnung mit umhergewandert.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 7, 7, 'Habe ich etwa, solange ich unter allen Israeliten umhergezogen bin, zu einem von den Richtern Israels, denen ich mein Volk Israel zu weiden geboten hatte, jemals auch nur ein Wort gesagt: Warum habt ihr mir kein Zedernhaus gebaut?‹');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 7, 8, 'Darum sollst du jetzt zu meinem Knecht, zu David, folgendes sagen: ›So hat der HERR der Heerscharen gesprochen: Ich habe dich von der Weide hinter der Herde weggeholt, damit du Fürst über mein Volk, über Israel, sein solltest;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 7, 9, 'und ich bin bei allem, was du unternommen hast, mit dir gewesen und habe alle deine Feinde vor dir her ausgerottet und habe dir einen großen Namen geschaffen, wie ihn nur die Größten auf Erden haben;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 7, 10, 'und ich will meinem Volk Israel eine Stätte anweisen und es da fest einpflanzen, damit es an seiner Stätte ruhig wohnen kann und sich nicht mehr zu ängstigen braucht und gewalttätige Menschen es nicht mehr bedrücken wie früher,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 7, 11, 'seit der Zeit, wo ich Richter über mein Volk Israel bestellt habe; sondern ich will dir Ruhe vor allen deinen Feinden verschaffen; und der HERR verkündigt dir, daß der HERR dir ein Haus bauen wird.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 7, 12, 'Wenn einst deine Tage voll sind und du dich zu deinen Vätern gelegt hast, dann will ich nach deinem Tode deinen leiblichen Sohn zu deinem Nachfolger erheben und ihm sein Königtum bestätigen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 7, 13, 'Der soll dann meinem Namen ein haus bauen, und ich will seinen Königsthron feststellen für immer.‹«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 7, 14, '»Ich will ihm Vater sein, und er soll mir Sohn sein, so daß, wenn er sich verfehlt, ich ihn mit einer menschlichen Rute und mit menschlichen Schlägen züchtigen werde;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 7, 15, 'aber meine Gnade soll nicht von ihm weichen, wie ich sie von Saul, deinem Vorgänger, habe weichen lassen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 7, 16, 'Nein, dein Haus und dein Königtum sollen für immer Bestand vor mir haben: dein Thron soll feststehen für immer!‹«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 7, 17, 'Nachdem Nathan diesen Worten und dieser Offenbarung genau entsprechend zu David geredet hatte,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 7, 18, 'ging der König David (in das Gotteszelt) hinein, warf sich vor dem HERRN nieder und betete: »Wer bin ich, HERR mein Gott, und was ist mein Haus, daß du mich bis hierher gebracht hast!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 7, 19, 'Und dies hast du für noch nicht genügend gehalten, HERR mein Gott; denn jetzt hast du auch noch in bezug auf das Haus deines Knechtes Verheißungen für ferne Zeiten gegeben, und zwar nach Menschenweise, HERR mein Gott.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 7, 20, 'Was soll da David noch weiter zu dir sagen? Du selbst kennst ja deinen Knecht, HERR mein Gott.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 7, 21, 'Um deines Knechtes willen und nach deinem Herzen hast du gehandelt, indem du all dieses Große deinem Knecht kundgetan hast.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 7, 22, 'Darum bist du groß, HERR mein Gott; ja, niemand ist dir gleich, und es gibt keinen Gott außer dir nach allem, was wir mit unsern Ohren vernommen haben.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 7, 23, 'Und wo ist ein anderes Volk, das deinem Volk Israel gleicht? Es ist das einzige Volk auf Erden, um deswillen Gott hingegangen ist, es sich zum Eigentumsvolk zu erkaufen und ihm einen Namen zu schaffen und ihm zugut so große Dinge und wunderbare Taten zu vollführen, indem du vor deinem Volk, das du dir aus Ägypten befreit hast, Heidenvölker und ihre Götter vertrieben hast.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 7, 24, 'So hast du dir denn dein Volk Israel für alle Zeiten zum Volk bestätigt, und du, HERR, bist ihr Gott geworden.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 7, 25, 'Und nun, HERR mein Gott: mache die Verheißung, die du in betreff deines Knechtes und seines Hauses ausgesprochen hast, für alle Zeiten wahr und verfahre so, wie du zugesagt hast!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 7, 26, 'Dann wird dein Name für immer groß sein, daß man aussprechen wird: ›Der HERR der Heerscharen ist der Gott für Israel‹, und das Haus deines Knechtes David wird Bestand vor dir haben.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 7, 27, 'Denn du selbst, HERR der Heerscharen, Gott Israels, hast deinem Knecht die Offenbarung zuteil werden lassen: ›Ich will dir ein Haus bauen‹; darum hat dein Knecht den Mut gefunden, dieses Gebet an dich zu richten.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 7, 28, 'Nun denn, HERR mein Gott: du bist Gott, und deine Worte sind Wahrheit! Nachdem du deinem Knecht diese herrliche Zusage gemacht hast,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 7, 29, 'so möge es dir nun auch gefallen, das Haus deines Knechtes zu segnen, damit es immerdar vor dir bestehe! Denn du selbst, HERR mein Gott, hast es verheißen. So wird denn das Haus deines Knechtes durch deinen Segen auf ewig gesegnet sein!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 8, 1, 'Nachmals besiegte David die Philister und demütigte sie und machte so der Oberherrschaft der Philister ein Ende. –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 8, 2, 'Er besiegte auch die Moabiter und maß sie mit der Meßschnur ab, indem er sie auf die Erde niederlegen ließ; und zwar maß er zwei Schnurlängen ab, um (die betreffenden) zu töten, und eine volle Schnurlänge für die, welche am Leben bleiben sollten. So wurden die Moabiter Davids tributpflichtige Untertanen. –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 8, 3, 'Sodann besiegte David Hadad-Eser, den Sohn Rehobs, den König von Zoba, als dieser ausgezogen war, um seine Herrschaft am Euphrat wiederherzustellen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 8, 4, 'Dabei machte David 1700 Reiter von ihm und 20000 Mann Fußvolk zu Gefangenen und ließ die Gespanne sämtlich lähmen; nur hundert Wagenpferde behielt er von diesen für sich. –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 8, 5, 'Als dann die Syrer von Damaskus dem König Hadad-Eser von Zoba zu Hilfe kamen, erschlug David von den Syrern 22000 Mann');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 8, 6, 'und setzte dann Vögte im damascenischen Syrien ein, so daß die dortigen Syrer zu tributpflichtigen Untertanen Davids wurden. So verlieh der HERR dem David den Sieg auf allen Zügen, die er unternahm.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 8, 7, 'Auch erbeutete David die goldenen Schilde, welche die Dienstleute Hadad-Esers getragen hatten, und ließ sie nach Jerusalem bringen;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 8, 8, 'und in Betah und Berothai, den Städten Hadad-Esers, fiel dem König David sehr viel Kupfer in die Hände. –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 8, 9, 'Als aber Thoi, der König von Hamath, erfuhr, daß David die ganze Heeresmacht Hadad-Esers geschlagen hatte,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 8, 10, 'sandte er seinen Sohn Joram zum König David, um ihn zu begrüßen und ihm Glück zu wünschen, daß er aus dem Kriege mit Hadad-Eser als Sieger hervorgegangen war – Thoi hatte nämlich auf dem Kriegsfuß mit Hadad-Eser gestanden –; und jener brachte silberne, goldene und kupferne Geräte mit,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 8, 11, 'die der König David ebenfalls dem HERRN weihte, wie er es auch mit dem Silber und Gold machte, das ihm bei allen unterworfenen Völkern in die Hände gefallen war,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 8, 12, 'nämlich bei den Syrern, Moabitern, Ammonitern, Philistern und Amalekitern, sowie mit der Beute, die ihm bei Hadad-Eser, dem Sohne Rehobs, dem König von Zoba, in die Hände gefallen war.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 8, 13, 'Als David dann von dem Siege über die Syrer zurückkehrte, gewann er neuen Ruhm, indem er die Edomiter im Salztal besiegte und 18000 Mann von ihnen erschlug.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 8, 14, 'Auch über alle Teile des Landes der Edomiter setzte er Vögte ein, so daß das ganze Land Edom ihm untertan wurde. So verlieh der HERR dem David den Sieg überall, wohin er zog.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 8, 15, 'So herrschte denn David über ganz Israel und ließ Recht und Gerechtigkeit in seinem ganzen Volke walten. –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 8, 16, 'Joab, der Sohn der Zeruja, stand an der Spitze des Heeres; Josaphat, der Sohn Ahiluds, war Kanzler;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 8, 17, 'Zadok, der Sohn Ahitubs, und Abjathar, der Sohn Ahimelechs, waren Priester, Seraja Staatsschreiber,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 8, 18, 'Benaja, der Sohn Jojadas, Befehlshaber der (Leibwache der) Krethi und Plethi; Priesterrang hatten auch die Söhne Davids.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 9, 1, 'David fragte: »Ist noch jemand von Sauls Familie übriggeblieben? Ich will Barmherzigkeit an ihm üben um Jonathans willen.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 9, 2, 'Nun war im Hause Sauls ein Diener namens Ziba; den berief man zu David, und der König fragte ihn: »Bist du Ziba?« Er antwortete: »Ja, dein Knecht.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 9, 3, 'Der König fragte weiter: »Ist niemand mehr da von Sauls Familie, daß ich ihm Gottes Barmherzigkeit erweisen könnte?« Da antwortete Ziba dem König: »Doch, es lebt noch ein Sohn Jonathans, der an den Füßen lahm ist.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 9, 4, 'Als der König ihn nun fragte, wo dieser sich befinde, erwiderte Ziba dem König: »Er befindet sich zu Lodebar im Hause Machirs, des Sohnes Ammiels.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 9, 5, 'Da sandte der König David hin und ließ ihn aus Lodebar aus dem Hause Machirs, des Sohnes Ammiels, holen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 9, 6, 'Als nun Mephiboseth, der Sohn Jonathans, des Sohnes Sauls, zu David kam, warf er sich vor ihm auf sein Angesicht nieder und brachte ihm seine Huldigung dar. Da sagte David zu ihm: »Mephiboseth!« Er antwortete: »Hier ist dein Knecht!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 9, 7, 'Dann fuhr David fort: »Fürchte dich nicht! Denn ich will dir um deines Vaters Jonathan willen Barmherzigkeit erweisen und dir den ganzen Grundbesitz deines Großvaters Saul zurückgeben; du selbst aber sollst allezeit an meinem Tische speisen.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 9, 8, 'Da verneigte sich jener und sagte: »Was ist dein Knecht, daß du deine Gnade einem toten Hunde zuwendest, wie ich einer bin!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 9, 9, 'Darauf ließ der König den Diener Sauls, Ziba, kommen und sagte zu ihm: »Alles, was Saul und seinem ganzen Hause gehört hat, habe ich dem Sohne deines (früheren) Herrn zurückgegeben.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 9, 10, 'Du aber sollst ihm das Feld bestellen, du mit deinen Söhnen und Knechten, und sollst die Ernte einbringen, damit (das Haus) des Sohnes deines (früheren) Herrn zu leben hat; Mephiboseth aber, der Sohn deines (früheren) Herrn, wird regelmäßig an meinem Tische speisen.« Ziba hatte aber fünfzehn Söhne und zwanzig Knechte.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 9, 11, 'Da antwortete Ziba dem König: »Ganz so, wie mein Herr und König seinem Knechte befiehlt, wird dein Knecht es ausrichten.« So speiste denn Mephiboseth an Davids Tisch, als wäre er einer von den Königssöhnen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 9, 12, 'Mephiboseth aber hatte einen kleinen Sohn namens Micha, und alle, die im Hause Zibas wohnten, waren nun Knechte in Mephiboseths Diensten.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 9, 13, 'Mephiboseth selbst aber wohnte in Jerusalem, weil er regelmäßig an der Tafel des Königs speiste; er war aber an beiden Füßen lahm.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 10, 1, 'Danach begab es sich, daß (Nahas), der König der Ammoniter, starb und sein Sohn Hanun ihm in der Regierung nachfolgte.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 10, 2, 'Da dachte David: »Ich will mich freundlich gegen Hanun, den Sohn des Nahas, beweisen, wie sein Vater sich mir gegenüber freundlich gezeigt hat.« So schickte denn David hin, um ihm durch seine Diener sein Beileid zum Tode seines Vaters ausdrücken zu lassen. Als aber die Diener Davids im Lande der Ammoniter angekommen waren,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 10, 3, 'sagten die Fürsten der Ammoniter zu Hanun, ihrem Herrn: »Glaubst du etwa, daß David Beileidsgesandte deshalb geschickt hat, um deinem Vater eine Ehre zu erweisen? Nein, offenbar hat David seine Diener nur deshalb zu dir geschickt, um die Stadt zu erforschen und auszukundschaften und sie dann zu zerstören.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 10, 4, 'Da ließ Hanun die Gesandten Davids festnehmen, ließ ihnen den Bart halb abscheren und die Röcke halb abschneiden bis unter den Gürtel und entließ sie dann.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 10, 5, 'Als man dies dem David meldete, schickte er ihnen Boten entgegen – denn die Männer waren schwer beschimpft –; und der König ließ ihnen sagen: »Bleibt in Jericho, bis euch der Bart wieder gewachsen ist: dann kehrt heim!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 10, 6, 'Als nun die Ammoniter sahen, daß sie David tödlich beleidigt hatten, sandten sie hin und nahmen die Syrer von Beth-Rehob und die Syrer von Zoba in Sold, 20000 Mann Fußvolk, ebenso den König von Maacha mit 1000 Mann und 12000 Mann von Istob.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 10, 7, 'Sobald David Kunde davon erhielt, ließ er Joab mit dem ganzen Heer, auch den Helden, ausrücken.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 10, 8, 'Die Ammoniter zogen dann (aus der Stadt) hinaus und stellten sich vor dem Stadttor in Schlachtordnung auf, während die Syrer von Zoba und Rehob und die Mannschaften von Istob und Maacha für sich im freien Felde standen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 10, 9, 'Als nun Joab sah, daß ihm sowohl von vorn als auch im Rücken ein Angriff drohe, nahm er aus allen auserlesenen israelitischen Kriegern eine Auswahl vor und stellte sich mit ihnen den Syrern gegenüber auf;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 10, 10, 'den Rest des Heeres aber überwies er seinem Bruder Abisai, und dieser mußte sich mit ihnen den Ammonitern gegenüber aufstellen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 10, 11, 'Dann sagte er: »Wenn die Syrer mir überlegen sind, so kommst du mir zu Hilfe; und wenn die Ammoniter dir überlegen sind, so komme ich dir zu Hilfe.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 10, 12, 'Nur Mut! Wir wollen tapfer kämpfen für unser Volk und für die Städte unsers Gottes! Der HERR aber möge tun, was ihm wohlgefällt!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 10, 13, 'Darauf rückte Joab mit der Mannschaft, die unter seinem Befehl stand, zum Angriff gegen die Syrer vor, und diese wandten sich vor ihm zur Flucht;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 10, 14, 'und als die Ammoniter die Flucht der Syrer gewahrten, flohen auch sie vor Abisai und zogen sich in die Stadt zurück. Darauf ließ Joab vom Kampf gegen die Ammoniter ab und kehrte nach Jerusalem zurück.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 10, 15, 'Als sich nun die Syrer von den Israeliten geschlagen sahen, sammelten sie sich wieder in voller Zahl;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 10, 16, 'und Hadad-Eser sandte hin und ließ die Syrer von jenseits des Euphrats ins Feld rücken, und diese kamen unter Führung Sobachs, des Heerführers Hadad-Esers, nach Helam.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 10, 17, 'Auf die Kunde hiervon bot David ganz Israel zum Kriege auf, überschritt den Jordan und gelangte nach Helam, wo die Syrer sich ihm entgegenstellten und ihm eine Schlacht lieferten.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 10, 18, 'Aber die Syrer wurden von den Israeliten in die Flucht geschlagen, und David erschlug den Syrern die Bemannung von 700 Kriegswagen und 40000 Mann Fußvolk; auch ihren Heerführer Sobach verwundete er, so daß er dort starb.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 10, 19, 'Als nun sämtliche Könige, die dem Hadad-Eser Heerfolge leisteten, sich von den Israeliten besiegt sahen, schlossen sie Frieden mit den Israeliten und unterwarfen sich ihnen. Infolgedessen scheuten sich die Syrer, den Ammonitern fernerhin noch Hilfe zu leisten.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 11, 1, 'Im folgenden Jahre aber sandte David zu der Zeit, wo die Könige ins Feld zu ziehen pflegen, Joab samt seinen Hauptleuten und der Heeresmacht von ganz Israel aus. Sie verwüsteten das Land der Ammoniter und belagerten Rabba, während David in Jerusalem geblieben war.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 11, 2, 'Da begab es sich eines Abends, daß David sich von seinem Lager erhob und, als er auf dem Dache des königlichen Palastes umherging, vom Dache aus eine Frau sich baden sah; die Frau war von ungewöhnlicher Schönheit.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 11, 3, 'Als er sich nun durch Boten nach der Frau erkundigen ließ und man ihm berichtete, daß es Bathseba, die Tochter Eliams, die Frau des Hethiters Uria sei,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 11, 4, 'sandte David Boten hin und ließ sie holen. Sie kam zu ihm, und er wohnte ihr bei – sie hatte sich aber eben von ihrer Verunreinigung gereinigt –; darauf kehrte sie in ihre Wohnung zurück.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 11, 5, 'Als die Frau dann guter Hoffnung wurde und dem David Mitteilung von ihrem Zustande machte,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 11, 6, 'da ließ David dem Joab sagen: »Schicke mir den Hethiter Uria her!«, und Joab kam dem Befehle nach.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 11, 7, 'Als nun Uria zu David kam, erkundigte dieser sich nach dem Befinden Joabs, nach dem Ergehen des Heeres und nach dem Stande des Krieges.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 11, 8, 'Darauf sagte David zu Uria: »Gehe jetzt in dein Haus hinunter und nimm ein Fußbad«; und als Uria den Palast des Königs verließ, wurde eine königliche Ehrenmahlzeit hinter ihm hergetragen;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 11, 9, 'aber Uria legte sich am Eingang des Königspalastes bei allen übrigen Dienern seines Herrn nieder und ging nicht in sein Haus hinunter.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 11, 10, 'Als man nun dem König meldete, Uria sei nicht in sein Haus hinabgegangen, fragte ihn David: »Du bist doch von der Reise heimgekommen: warum gehst du nicht in deine Wohnung?«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 11, 11, 'Da antwortete Uria dem Könige: »Die Lade sowie Israel und Juda sind in Hütten untergebracht, und mein Herr Joab und die Diener meines Herrn müssen auf freiem Felde lagern, und da sollte ich in mein Haus gehen, um zu essen und zu trinken, und sollte es mir bei meiner Frau wohl sein lassen? So wahr der HERR lebt und so wahr du selbst lebst: das tue ich nicht!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 11, 12, 'Darauf sagte David zu Uria: »Du magst auch heute noch hier bleiben: morgen werde ich dich entlassen.« So blieb denn Uria an diesem Tage noch in Jerusalem.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 11, 13, 'Am folgenden Tage aber lud David ihn ein, bei ihm zu essen und zu trinken, und er machte ihn trunken; aber am Abend ging Uria wieder hin, um sich auf sein Lager bei den übrigen Leuten seines Herrn schlafen zu legen, und ging nicht in sein Haus hinunter.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 11, 14, 'Am nächsten Morgen aber schrieb David einen Brief an Joab und ließ ihn durch Uria überbringen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 11, 15, 'In dem Briefe hatte er folgendes geschrieben: »Stellt Uria vornhin, wo am hitzigsten gekämpft wird, und zieht euch dann hinter ihm zurück, damit er erschlagen wird und den Tod findet.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 11, 16, 'So stellte denn Joab bei der Belagerung der Stadt den Uria an eine Stelle, von der er wußte, daß dort tapfere Gegner standen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 11, 17, 'Als dann die Städter einen Ausfall machten und mit Joab handgemein wurden, fielen manche von der Mannschaft, von den Leuten Davids; und auch der Hethiter Uria fand dabei den Tod.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 11, 18, 'Als hierauf Joab an David einen Bericht über den ganzen Verlauf des Kampfes schickte,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 11, 19, 'gab er dem Boten den Befehl: »Wenn du dem König den ganzen Verlauf des Kampfes bis zu Ende berichtet hast');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 11, 20, 'und der König dann vor Zorn aufbraust und dich fragt: ›Warum seid ihr zum Angriff so nahe an die Stadt herangerückt? Wußtet ihr nicht, daß man von der Mauer herab schießen würde?');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 11, 21, 'Wer hat Abimelech, den Sohn Jerubbeseths, erschlagen? Hat nicht ein Weib den oberen Stein einer Handmühle von der Mauer auf ihn herabgeworfen, so daß er in Thebez den Tod fand? Warum seid ihr so nahe an die Mauer herangerückt?‹ – dann sage nur: ›Auch dein Knecht, der Hethiter Uria, ist ums Leben gekommen.‹«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 11, 22, 'Darauf ging der Bote hin und richtete nach seiner Ankunft den Auftrag Joabs bei David genau aus.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 11, 23, 'Er meldete dem Könige nämlich: »Weil die Feinde uns überlegen und bis aufs freie Feld gegen uns vorgedrungen waren, so mußten wir sie bis an den Eingang des Stadttors zurückdrängen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 11, 24, 'Da aber schossen die Schützen von der Mauer herab auf deine Leute, und dabei fielen einige von den Leuten des Königs; auch dein Knecht, der Hethiter Uria, fand den Tod.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 11, 25, 'Da sagte David zu dem Boten: »Melde dem Joab folgendes: ›Laß dir diesen Vorfall nicht leid sein! Denn das Schwert frißt eben bald diesen, bald jenen. Setze nur deine Belagerung der Stadt entschlossen fort und zerstöre sie!‹ So sollst du ihm Mut zusprechen!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 11, 26, 'Als nun die Frau Urias den Tod ihres Mannes erfuhr, hielt sie die Totenklage um ihren Gatten;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 11, 27, 'sobald aber die Trauerzeit vorüber war, ließ David sie in sein Haus holen. Sie wurde also seine Frau und gebar ihm einen Sohn. Aber die Tat, die David verübt hatte, erregte das Mißfallen des HERRN.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 12, 1, 'Hierauf sandte der HERR (den Propheten) Nathan zu David; als dieser zu ihm gekommen war, redete er so zu ihm: »Es lebten zwei Männer in derselben Stadt, ein reicher und ein armer.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 12, 2, 'Der Reiche besaß Kleinvieh und Rinder in großer Menge,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 12, 3, 'der Arme aber hatte gar nichts als ein einziges Lämmchen, das er sich gekauft und aufgezogen hatte und das bei ihm und zugleich mit seinen Kindern aufwuchs; es aß von seinem Bissen und trank aus seinem Becher, es schlief an seinem Busen und wurde von ihm wie eine Tochter gehalten.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 12, 4, 'Da kam eines Tages Besuch zu dem reichen Mann, und weil es ihm leid tat, ein Stück von seinem eigenen Kleinvieh oder von seinen Rindern zu nehmen, um es für den Besuch, der zu ihm gekommen war, als Mahl zuzubereiten, nahm er das Lämmchen des armen Mannes und richtete es für den Gast zu, der zu ihm gekommen war.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 12, 5, 'Da geriet David in heftigen Zorn gegen den Mann, so daß er zu Nathan sagte: »So wahr der HERR lebt: der Mann, der das getan hat, ist ein Kind des Todes!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 12, 6, 'Und das Lamm soll er vierfach erstatten zur Strafe dafür, daß er so gehandelt und weil er kein Mitleid bewiesen hat!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 12, 7, 'Da erwiderte Nathan dem David: »Du bist der Mann! So hat der HERR, der Gott Israels, gesprochen: ›Ich habe dich zum König über Israel gesalbt, und ich habe dich aus Sauls Händen errettet,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 12, 8, 'ich habe dir das Haus deines Herrn gegeben und die Frauen deines Herrn dir in den Schoß gelegt (zur Verfügung gestellt); ich habe dir das Haus Israel und Juda übergeben, und wenn dir das noch zu wenig war, so hätte ich dir noch dies und das hinzugefügt.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 12, 9, 'Warum hast du dich über das Gebot des HERRN hinweggesetzt und etwas getan, was ihm mißfällt? Den Hethiter Uria hast du mit dem Schwert erschlagen lassen und sein Weib dir zum Weibe genommen, nachdem du ihn selbst durch das Schwert der Ammoniter hast umbringen lassen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 12, 10, 'So soll denn nun das Schwert aus deinem Hause niemals weichen zur Strafe dafür, daß du mich mißachtet und das Weib des Hethiters Uria dir zum Weibe genommen hast!‹');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 12, 11, 'So hat der HERR gesprochen: ›Siehe, ich will Unheil über dich aus deinem eigenen Hause hervorgehen lassen und will dir deine Frauen vor deinen Augen wegnehmen und sie einem andern geben, daß er im Angesicht dieser Sonne deinen Frauen beiwohnen soll.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 12, 12, 'Denn du hast im geheimen gehandelt, ich aber will diese Drohung vor den Augen von ganz Israel und angesichts der Sonne zur Ausführung bringen!‹«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 12, 13, 'Da sagte David zu Nathan: »Ich habe gegen den HERRN gesündigt!« Nathan antwortete dem David: »So hat auch der HERR dir deine Sünde vergeben: du selbst wirst nicht sterben!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 12, 14, 'Doch weil du den Feinden des HERRN durch diese Tat Anlaß zur Lästerung gegeben hast, so soll auch der Sohn, der dir geboren ist, unrettbar sterben!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 12, 15, 'Als Nathan hierauf nach Hause gegangen war, schlug der HERR das Kind, welches die Frau Urias dem David geboren hatte, so daß es todkrank wurde.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 12, 16, 'Da suchte David Gott um des Knaben willen (im Heiligtum) auf, und David fastete und brachte, als er heimgekommen war, die ganze Nacht hindurch auf dem Erdboden liegend zu.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 12, 17, 'Obgleich nun die Ältesten seines Hauses zu ihm traten, um ihn zum Aufstehen von der Erde zu bewegen, weigerte er sich doch und speiste nicht mit ihnen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 12, 18, 'Als das Kind dann am siebten Tage starb, trugen die Hofleute Davids Bedenken, ihm den Tod des Kindes anzuzeigen; denn sie dachten: »Solange das Kind noch am Leben war, hat er unsere Vorstellungen, wenn wir ihm zuredeten, unbeachtet gelassen: wie können wir ihm da jetzt den Tod des Kindes anzeigen? Es gäbe ein Unglück ab!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 12, 19, 'Als David aber seine Hofleute miteinander flüstern sah und daran merkte, daß das Kind tot war, fragte er seine Hofleute: »Ist das Kind tot?« Sie antworteten ihm: »Ja, es ist tot.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 12, 20, 'Da stand David vom Boden auf, wusch und salbte sich und legte die Trauerkleider ab; darauf ging er in das Haus des HERRN und warf sich nieder. Als er dann in sein Haus zurückgekehrt war, ließ er sich eine Mahlzeit auftragen und aß.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 12, 21, 'Da sagten seine Hofleute zu ihm: »Wie unerklärlich ist dein Verhalten! Solange das Kind noch am Leben war, hast du um seinetwillen gefastet und geweint; und jetzt, da das Kind tot ist, stehst du auf und nimmst Nahrung zu dir.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 12, 22, 'Da antwortete er: »Solange das Kind noch lebte, habe ich gefastet und geweint, weil ich dachte: Wer weiß, vielleicht erbarmt der HERR sich meiner, daß das Kind am Leben bleibt?');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 12, 23, 'Nun es aber tot ist, wozu soll ich da fasten? Kann ich es etwa wieder ins Leben zurückrufen? Ich kann wohl zu ihm kommen, es aber kann nicht wieder zu mir zurückkehren.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 12, 24, 'Nachdem David dann seiner Gattin Bathseba Trost zugesprochen und sich ihr wieder in Liebe zugewandt hatte, wurde sie Mutter eines Sohnes, den er Salomo nannte und den der HERR liebhatte.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 12, 25, 'David übergab ihn der Fürsorge des Propheten Nathan, der ihm den Namen Jedidjah gab, um des HERRN willen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 12, 26, 'Joab aber bestürmte unterdessen Rabba, die Hauptstadt der Ammoniter, und eroberte die Königsstadt.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 12, 27, 'Hierauf sandte er Boten an David und ließ ihm sagen: »Ich habe Rabba bestürmt und die Wasserstadt auch erobert;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 12, 28, 'so biete jetzt nun den Rest des Kriegsvolkes auf, belagere die Stadt und erobere sie, damit nicht ich die Stadt einnehme und dann mein Name über ihr ausgerufen wird.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 12, 29, 'Da bot David seine ganze Heeresmacht auf, zog gegen Rabba, bestürmte die Stadt und eroberte sie.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 12, 30, 'Er nahm dann ihrem Götzen Milkom die Krone vom Haupt, die ein Talent Gold wog und mit einem kostbaren Edelstein besetzt war; der kam nunmehr an Davids Haupt. Und er führte aus der Stadt eine überaus reiche Beute weg.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 12, 31, 'Die Bevölkerung, die sich dort vorfand, ließ er wegführen und stellte sie als Fronarbeiter an bei den Sägen, bei den eisernen Picken und den eisernen Äxten und ließ sie an den Ziegelöfen arbeiten; ebenso verfuhr er mit allen übrigen Städten der Ammoniter. Dann kehrte David mit dem gesamten Heere nach Jerusalem zurück.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 1, 'Danach begab sich folgendes: Absalom, der Sohn Davids, hatte eine schöne Schwester namens Thamar; in diese verliebte sich Amnon, Davids Sohn,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 2, 'und härmte sich vor Liebe zu seiner Halbschwester Thamar so ab, daß er krank wurde; sie war nämlich noch Jungfrau, und es schien dem Amnon unmöglich, an sie heranzukommen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 3, 'Nun hatte Amnon einen Freund namens Jonadab, einen Sohn Simeas, des Bruders Davids; und dieser Jonadab war ein sehr kluger Mann.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 4, 'Der fragte ihn: »Warum siehst du jeden Morgen so elend aus, Königssohn? Willst du es mir nicht anvertrauen?« Amnon antwortete ihm: »Ich liebe Thamar, die Schwester meines Bruders Absalom.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 5, 'Da sagte Jonadab zu ihm: »Lege dich zu Bett und stelle dich krank. Wenn dann dein Vater kommt, um dich zu besuchen, so sage zu ihm: ›Wenn doch meine Schwester Thamar herkäme und mir etwas zu essen gäbe! Wenn sie das Essen vor meinen Augen zubereitete, so daß ich zusehen kann, würde ich das Essen von ihrer Hand annehmen.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 6, 'So legte sich denn Amnon zu Bett und stellte sich krank; und als der König kam, um ihn zu besuchen, sagte Amnon zum König: »Wenn doch meine Schwester Thamar herkäme und vor meinen Augen ein paar Pfannkuchen zubereitete, daß ich sie aus ihrer Hand essen könnte!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 7, 'Da sandte David zu Thamar ins Haus und ließ ihr sagen: »Gehe doch in die Wohnung deines Bruders Amnon und bereite ihm das Essen!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 8, 'So ging denn Thamar in die Wohnung ihres Bruders Amnon, während er zu Bett lag. Sie nahm den Teig, knetete ihn, formte Kuchen vor seinen Augen daraus und buk die Kuchen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 9, 'Dann nahm sie die Pfanne und schüttete sie vor seinen Augen (auf einen Teller) aus; er weigerte sich jedoch zu essen und befahl, jedermann solle aus dem Zimmer hinausgehen. Als nun alle hinausgegangen waren,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 10, 'sagte Amnon zu Thamar: »Bringe mir das Essen in die Kammer herein, dann will ich von deiner Hand das Essen annehmen.« Da nahm Thamar die Kuchen, die sie zubereitet hatte, und brachte sie ihrem Bruder Amnon in die Kammer hinein;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 11, 'aber als sie ihm diese zum Essen hinreichte, ergriff er sie und sagte zu ihr: »Komm, lege dich zu mir, liebe Schwester!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 12, 'Sie erwiderte ihm: »Nicht doch, mein Bruder! Entehre mich nicht! So etwas darf in Israel nicht geschehen! Begehe keine solche Schandtat!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 13, 'Wohin sollte ich denn meine Schande tragen? Und du selbst würdest in Israel als ein ehrloser Mann dastehen! Rede doch lieber mit dem König: er wird mich dir gewiß nicht versagen.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 14, 'Aber er wollte nicht auf ihre Vorstellungen hören, sondern überwältigte sie und tat ihr Gewalt an.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 15, 'Hierauf aber faßte Amnon eine überaus tiefe Abneigung gegen sie, so daß der Widerwille, den er gegen sie empfand, noch stärker war als seine frühere Liebe zu ihr. Daher rief er ihr zu: »Mach, daß du fortkommst!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 16, 'Sie antwortete ihm: »Nicht doch, mein Bruder! Denn dieses Unrecht, wenn du mich jetzt von dir stießest, wäre noch größer als das andere, das du mir angetan hast!« Er wollte aber nicht auf sie hören,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 17, 'sondern rief seinen Burschen her, der ihn zu bedienen hatte, und befahl ihm: »Schafft mir diese da hinaus auf die Straße und riegle die Tür hinter ihr zu!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 18, 'Sie trug aber ein Ärmelkleid; denn so kleideten sich ehemals die Töchter des Königs, solange sie unverheiratet waren. Als nun sein Leibdiener sie auf die Straße hinausgeschafft und die Tür hinter ihr verriegelt hatte,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 19, 'streute Thamar Staub auf ihr Haupt, zerriß das Ärmelkleid, das sie anhatte, legte sich die Hand aufs Haupt und ging laut schreiend davon.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 20, 'Da sagte ihr Bruder Absalom zu ihr: »Dein Bruder Amnon ist bei dir gewesen? Nun denn, liebe Schwester, schweige still! Er ist ja dein Bruder: nimm dir die Sache nicht zu Herzen!« So blieb denn Thamar einsam im Hause ihres Bruders Absalom wohnen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 21, 'Als dann der König David den ganzen Vorfall vernahm, geriet er in heftigen Zorn (tat aber seinem Sohne Amnon nichts zuleide; denn er hatte ihn lieb, weil er sein Erstgeborener war).');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 22, 'Absalom aber redete seitdem kein Wort mehr mit Amnon, weder im Bösen noch im Guten; denn Absalom haßte Amnon, weil er seine Schwester Thamar entehrt hatte.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 23, 'Nun begab es sich zwei volle Jahre später, daß Absalom in Baal-Hazor, das bei Ephraim liegt, Schafschur hielt und alle Söhne des Königs dazu einlud.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 24, 'Er ging auch zum König und sagte: »Du weißt, dein Knecht hält eben Schafschur; möchte doch der König samt seiner Umgebung deinen Knecht dorthin begleiten!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 25, 'Aber der König erwiderte dem Absalom: »Nicht doch, mein Sohn! Wir wollen nicht allesamt kommen, damit wir dir nicht zu viel Last machen.« Da drang er in ihn, aber er wollte nicht mitgehen, sondern schlug ihm seine Bitte ab.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 26, 'Da sagte Absalom: »Wenn also nicht, so laß wenigstens meinen Bruder Amnon mit uns gehen!« Der König antwortete ihm: »Wozu sollte er mit dir gehen?«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 27, 'Als Absalom jedoch auf seiner Bitte bestand, ließ er Amnon und alle Söhne des Königs mit ihm gehen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 28, '(Absalom veranstaltete nun ein Gelage gleich einem Königsgelage.) Dabei gab er seinen Dienern folgenden Befehl: »Gebt acht! Wenn Amnon vom Wein in fröhliche Stimmung versetzt ist und ich euch zurufe: ›Haut Amnon nieder!‹, so tötet ihn, fürchtet euch nicht! Ich bin’s ja, der es euch befohlen hat: seid mutig und zeigt euch mannhaft!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 29, 'Da verfuhren die Diener Absaloms mit Amnon so, wie Absalom ihnen befohlen hatte; darauf standen die Söhne des Königs alle auf, bestiegen ein jeder sein Maultier und ergriffen die Flucht.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 30, 'Während sie noch unterwegs waren, war schon das Gerücht zu David gedrungen, Absalom habe alle Söhne des Königs ermordet, so daß auch nicht einer von ihnen am Leben geblieben sei.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 31, 'Da stand der König auf, zerriß seine Kleider und warf sich auf die Erde nieder; auch alle seine Hofleute standen (um ihn her) mit zerrissenen Kleidern.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 32, 'Da nahm Jonadab, der Sohn Simeas, des Bruders Davids, das Wort und sagte: »Mein Herr denke doch nicht, daß man die jungen Leute, die Söhne des Königs, allesamt ums Leben gebracht habe! Nein, Amnon allein ist tot; man hat es dem Absalom ja ansehen können, daß das bei ihm beschlossene Sache war seit dem Tage, als jener seine Schwester Thamar entehrt hatte.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 33, 'Darum wolle jetzt mein Herr, der König, nicht den Gedanken hegen und nicht aussprechen, daß alle Königssöhne tot seien; nein, Amnon allein ist tot!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 34, '[Absalom aber hatte die Flucht ergriffen.] Als nun der Diener, der Wächter, Ausschau hielt, sah er viele Leute auf dem Wege nach Horonaim den Abhang herabkommen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 35, 'Da sagte Jonadab zum Könige: »Siehst du? Die Söhne des Königs kommen! Wie dein Knecht gesagt hat, so verhält es sich wirklich!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 36, 'Kaum hatte er ausgeredet, da kamen auch schon die Königssöhne und brachen in lautes Weinen aus; und auch der König und alle seine Hofleute erhoben eine überaus große Wehklage.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 37, 'Absalom aber war geflohen und hatte sich zu Thalmai, dem Sohne Ammihuds, dem Könige von Gesur, begeben. David aber trauerte um seinen Sohn Amnon die ganze Zeit hindurch.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 38, 'Nachdem Absalom aber geflohen war und sich nach Gesur begeben hatte, blieb er dort drei Jahre.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 39, 'Als dann der Zorn des Königs gegen Absalom allmählich milder geworden war, weil er sich über den Tod Amnons getröstet hatte,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 14, 1, 'und als Joab, der Sohn der Zeruja, erkannte, daß das Herz des Königs sich zu Absalom wieder hingewandt hatte,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 14, 2, 'sandte Joab nach Thekoa, ließ von dort eine kluge Frau holen und sagte zu ihr: »Stelle dich, als ob du in Trauer wärest, ziehe Trauerkleider an, salbe dich nicht mit Öl und benimm dich wie eine Frau, die schon lange Zeit um einen Toten trauert.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 14, 3, 'Dann begib dich zum König und rede zu ihm so und so«; und Joab gab ihr genau die Worte an, die sie sagen sollte.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 14, 4, 'Die Frau aus Thekoa ging also zum König hinein, warf sich vor ihm auf ihr Angesicht zu Boden, brachte ihre Huldigung dar und rief aus: »Hilf mir, o König!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 14, 5, 'Als nun der König sie fragte, was sie wünsche, antwortete sie: »Ach, ich bin eine Witwe, denn mein Mann ist tot!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 14, 6, 'Nun hatte deine Magd zwei Söhne, die gerieten auf dem Felde in Streit miteinander, und weil keiner da war, der sie auseinanderbrachte, schlug der eine auf den andern los und tötete ihn.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 14, 7, 'Und jetzt hat sich die ganze Verwandtschaft gegen deine Magd erhoben und sagt: ›Gib den Brudermörder heraus, damit wir ihn umbringen für das Leben seines Bruders, den er erschlagen hat, und damit wir auch den Erben ausrotten!‹ So wollen sie also die letzte Kohle, die mir noch geblieben ist, auslöschen, um meinem Manne weder Namen noch Nachkommen auf dem Erdboden zu lassen!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 14, 8, 'Da sagte der König zu der Frau: »Gehe heim, ich selber werde deinetwegen verfügen!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 14, 9, 'Die Frau aus Thekoa aber erwiderte dem König: »Auf mir, mein Herr und König, liege die Schuld (nämlich, daß keine Blutrache vollzogen wird) und auf meines Vaters Hause! Den König aber und seinen Thron trifft keine Verantwortung!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 14, 10, 'Da sagte der König: »Wer etwas von dir will, den bringe zu mir her: er soll dir nicht weiter zu schaffen machen!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 14, 11, 'Da entgegnete sie: »Der König wolle doch des HERRN, seines Gottes, gedenken, damit der Bluträcher nicht noch mehr Unglück anrichtet und sie meinen Sohn nicht auch noch vertilgen!« Da sagte er: »So wahr der HERR lebt, kein Haar soll deinem Sohne gekrümmt werden!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 14, 12, 'Nun fuhr die Frau fort: »Darf deine Magd ein Wort an meinen Herrn, den König, richten?« Er antwortete: »Rede!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 14, 13, 'Da sagte die Frau: »Und warum hegst du denn eine derartige Gesinnung gegen das Volk Gottes? Denn nachdem der König dies Urteil gefällt hat, hat er sich selbst gleichsam für schuldig erklärt, weil der König seinen verstoßenen Sohn nicht zurückkehren läßt.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 14, 14, 'Denn wir müssen zwar gewißlich sterben und sind wie Wasser, das auf die Erde ausgegossen ist und nicht wieder gesammelt werden kann; aber Gott wird das Leben dessen nicht dahinraffen, der ernstlich darauf sinnt, einen Verbannten nicht fern von sich in dauernder Verbannung zu belassen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 14, 15, 'Und nun, der Grund, weshalb ich hergekommen bin, um diese Sache meinem Herrn, dem Könige, vorzutragen, ist der, daß die Leute mir Angst gemacht haben. Da dachte aber deine Magd: ›Ich will es doch dem König vortragen; vielleicht erfüllt der König die Bitte seiner Magd.‹');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 14, 16, 'Ja, der König wird mich erhören, um seine Magd aus der Hand des Mannes zu erretten, der mich und zugleich meinen Sohn aus dem Erbe Gottes zu vertilgen sucht.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 14, 17, 'Daher dachte deine Magd: ›Das Wort meines Herrn, des Königs, wird mir eine Beruhigung sein‹; denn mein Herr, der König, ist wie der Engel Gottes, um Gutes und Böses zu unterscheiden; und der HERR, dein Gott, sei mit dir!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 14, 18, 'Da hub der König an und sagte zu der Frau: »Verheimliche mir nichts, wonach ich dich jetzt fragen werde!« Die Frau antwortete: »Mein Herr, der König, braucht nur zu reden!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 14, 19, 'Da fragte der König: »Hat nicht Joab die Hand bei dieser ganzen Sache im Spiel?« Da erwiderte die Frau: »So wahr du lebst, mein Herr und König! Es ist nicht möglich, bei allem, was mein Herr, der König, sagt, rechts oder links vorbeizukommen! Ja, dein Knecht Joab, er hat mir den Auftrag gegeben, und er selbst hat deiner Magd alle diese Worte in den Mund gelegt.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 14, 20, 'Um der Sache ein anderes Aussehen zu geben, ist dein Knecht Joab so zu Werke gegangen; aber mein Herr ist weise, ebenso weise wie der Engel Gottes, so daß er alles weiß, was auf Erden vorgeht.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 14, 21, 'Der König sagte dann zu Joab: »Nun gut! Ich will diese deine Bitte erfüllen! Gehe also hin und hole den jungen Mann, den Absalom, zurück!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 14, 22, 'Da warf sich Joab auf sein Angesicht zur Erde nieder, brachte seine Huldigung dar und beglückwünschte den König; dann rief Joab aus: »Heute erkennt dein Knecht, daß mein Herr, der König, mir in Gnaden zugetan ist, weil der König die Bitte seines Knechtes erfüllt hat!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 14, 23, 'Darauf machte Joab sich auf den Weg, begab sich nach Gesur und brachte Absalom nach Jerusalem zurück.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 14, 24, 'Der König aber befahl: »Er soll sich in seine Wohnung begeben, mir aber nicht vor die Augen treten!« So begab sich denn Absalom in seine Wohnung und durfte sich vor dem König nicht sehen lassen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 14, 25, 'In ganz Israel gab es aber keinen Mann, der wegen seiner Schönheit ebenso gefeiert gewesen wäre wie Absalom: von der Fußsohle bis zum Scheitel war kein Fehl an ihm;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 14, 26, 'und wenn er sich das Haupt(-haar) scheren ließ – das geschah nämlich nach Ablauf jeden Jahres, weil es ihm sonst zu beschwerlich geworden wäre –, so wog sein Haupthaar zweihundert Schekel nach königlichem Gewicht.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 14, 27, 'Es waren aber dem Absalom drei Söhne und eine Tochter namens Thamar geboren; die war ein Mädchen von großer Schönheit.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 14, 28, 'Als nun Absalom zwei volle Jahre in Jerusalem zugebracht hatte, ohne dem König vor die Augen zu treten,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 14, 29, 'schickte er zu Joab, um ihn zum König zu senden; aber der weigerte sich, zu ihm zu kommen; und als er noch ein zweites Mal hinschickte, weigerte er sich wieder, zu kommen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 14, 30, 'Da sagte Absalom zu seinen Knechten: »Ihr wißt, Joab hat da ein Ackerstück neben dem meinigen und hat Gerste darauf stehen; geht hin und zündet es an!« Als nun die Knechte Absaloms das Feld in Brand gesteckt hatten,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 14, 31, 'machte Joab sich auf, ging zu Absalom ins Haus und fragte ihn: »Warum haben deine Knechte mein Feld angezündet?«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 14, 32, 'Absalom antwortete dem Joab: »Du weißt, ich habe zu dir gesandt und dir sagen lassen: Komm her zu mir, ich will dich zum König senden und ihm sagen lassen: ›Wozu bin ich aus Gesur heimgekehrt? Es wäre besser für mich, ich wäre noch dort!‹ Jetzt aber werde ich dem König vor die Augen treten; und wenn eine Schuld auf mir liegt, so mag er mich töten!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 14, 33, 'Als Joab sich nun zum Könige begeben und ihm die Sache vorgetragen hatte, ließ dieser Absalom rufen. Als der zum König kam, warf er sich auf sein Angesicht vor ihm zur Erde nieder; der König aber küßte Absalom.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 1, 'Danach begab es sich, daß Absalom sich Wagen und Pferde anschaffte, dazu fünfzig Mann, die als Leibdiener vor ihm herliefen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 2, 'Auch pflegte Absalom sich alle Morgen früh neben dem Wege nach dem Ratstor aufzustellen; wenn dann jemand einen Rechtsstreit hatte und den König um Entscheidung angehen wollte, rief Absalom ihn an und fragte ihn: »Aus welcher Ortschaft bist du?« Wenn jener dann antwortete: »Dein Knecht kommt aus dem und dem Stamme Israels«,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 3, 'so sagte Absalom zu ihm: »Deine Sache ist allerdings gut und in Ordnung, aber beim König ist niemand, der dir Gehör schenkt!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 4, 'Dann fuhr Absalom fort: »Wenn man mich doch zum Richter im Lande bestellte, daß jeder, der eine Streitsache und einen Rechtshandel hat, zu mir käme: ich wollte ihm schon zu seinem Recht verhelfen!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 5, 'Und wenn jemand an ihn herantrat, um sich vor ihm huldigend zu verneigen, so streckte er seine Hand aus, umarmte ihn und küßte ihn.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 6, 'So machte es Absalom mit allen Israeliten, die zum König kamen, um sich Recht sprechen zu lassen; und so stahl Absalom sich die Herzen der Israeliten.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 7, 'Nach Verlauf von vier Jahren aber sagte Absalom zum König: »Ich möchte gern hingehen und in Hebron mein Gelübde einlösen, das ich dem HERRN dargebracht habe.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 8, 'Denn als ich mich zu Gesur in Syrien aufhielt, hat dein Knecht folgendes Gelübde getan: ›Wenn der HERR mich nach Jerusalem zurückkehren läßt, so will ich dem HERRN ein Dankopfer darbringen.‹«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 9, 'Der König antwortete ihm: »Gehe hin in Frieden!« So machte Absalom sich denn auf den Weg und ging nach Hebron.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 10, 'Er hatte aber heimlich Boten durch alle Stämme der Israeliten gesandt und sagen lassen: »Sobald ihr Posaunenschall hört, so ruft aus: ›Absalom ist in Hebron König geworden!‹«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 11, 'Mit Absalom gingen aber auch zweihundert Männer aus Jerusalem nach Hebron, die von ihm zum Opferfest eingeladen waren und arglos mitgingen, ohne von irgend etwas zu wissen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 12, 'Außerdem ließ Absalom, als das Opferfest schon im Gange war, den Giloniten Ahithophel, den Ratgeber Davids, aus seinem Wohnort Gilo holen. So gewann die Verschwörung immer weitere Verbreitung, und immer mehr Leute schlossen sich an Absalom an.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 13, 'Als nun ein Bote bei David eintraf mit der Meldung: »Das Herz der Israeliten hat sich Absalom zugewandt«,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 14, 'da befahl David allen seinen Dienern, die in Jerusalem bei ihm waren: »Auf! Wir müssen fliehen! Sonst gibt es für uns keine Rettung vor Absalom! Macht euch eilends auf den Weg, damit er uns nicht zuvorkommt und das Unheil über uns bringt und ein Blutbad in der Stadt anrichtet!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 15, 'Die Diener des Königs antworteten ihm: »Ganz wie unser königlicher Herr es für gut befindet: wir sind deine gehorsamen Diener!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 16, 'So zog denn der König aus, und sein ganzer Hof befand sich in seinem Gefolge; nur zehn Kebsweiber ließ der König zurück, um das Haus zu hüten.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 17, 'Als so der König auszog und das ganze Volk ihm auf dem Fuße folgte, machte er beim letzten Hause halt,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 18, 'während alle seine Diener neben ihm standen und seine gesamte Leibwache und alle Leute des Gathiters (Itthai), sechshundert Mann, die ihm von Gath her gefolgt waren, an dem Könige vorüberzogen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 19, 'Da sagte der König zu Itthai aus Gath: »Warum willst auch du mit uns ziehen? Kehre um und bleibe beim König (Absalom)! Du bist ja ein Ausländer und noch dazu aus deiner Heimat verbannt.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 20, 'Erst gestern bist du hergekommen, und heute soll ich dich schon mit uns auf die Irrfahrt nehmen, ohne selbst zu wissen, wohin ich gehe? Kehre um und nimm deine Landsleute mit dir zurück! Der HERR möge dir Güte und Treue erweisen!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 21, 'Itthai aber erwiderte dem König: »So wahr der HERR lebt, und so wahr mein Herr und König lebt, nein! An dem Orte, an dem mein Herr und König sein wird, es gehe zum Tode oder zum Leben, da wird auch dein Knecht zu finden sein!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 22, 'Da sagte David zu Itthai: »Gut denn, so ziehe vorüber!« Da zog Itthai aus Gath vorüber mit all seinen Leuten und dem ganzen Troß (von Kindern und Frauen), der bei ihm war.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 23, 'Die ganze Bevölkerung aber weinte laut, während das gesamte Kriegsvolk vorüberzog. Hierauf ging der König über den Bach Kidron, und auch das gesamte Volk zog hinüber in der Richtung nach der Wüste (Juda) hin.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 24, 'Da erschienen auch Zadok (und Abjathar) mit allen Leviten, die trugen die Bundeslade Gottes; sie setzten die Lade Gottes dort nieder, und Abjathar brachte Opfer dar, bis alles Volk aus der Stadt vollständig vorübergezogen war.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 25, 'Darauf sagte der König zu Zadok: »Bringe die Lade Gottes in die Stadt zurück! Finde ich Gnade in den Augen des HERRN, so wird er mich zurückführen und mich die Lade und seine Wohnung wiedersehen lassen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 26, 'Spricht er aber so zu mir: ›Ich habe kein Gefallen an dir‹ – nun, hier bin ich! Er tue mir, wie es ihm wohlgefällt!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 27, 'Dann sagte der König weiter zum Priester Zadok: »Du und Abjathar, kehrt ihr ruhig in die Stadt zurück und mit euch eure beiden Söhne, Ahimaaz, dein Sohn, und Jonathan, der Sohn Abjathars.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 28, 'Gebt wohl acht! Ich will in den Niederungen der Wüste verweilen, bis eine Botschaft von euch kommt und mir Nachricht gibt.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 29, 'So brachten denn Zadok und Abjathar die Lade Gottes nach Jerusalem zurück und blieben dort.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 30, 'David aber stieg die Anhöhe am Ölberg hinan, im Gehen weinend und mit verhülltem Haupt, und er ging barfuß; auch alles Volk, das ihn begleitete, hatte ein jeder das Haupt verhüllt und stieg unter fortwährendem Weinen den Berg hinan.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 31, 'Als man nun David meldete, daß auch Ahithophel unter den Verschworenen bei Absalom sei, rief David aus: »O HERR, mache doch die Ratschläge Ahithophels zur Torheit!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 32, 'Als David dann auf der Höhe angelangt war, wo man Gott anzubeten pflegt, kam ihm plötzlich der Arkiter Husai mit zerrissenem Gewand und mit Erde auf dem Haupt entgegen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 33, 'David sagte zu ihm: »Wenn du mit mir weiter zögest, würdest du mir nur zur Last fallen;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 34, 'wenn du aber in die Stadt zurückkehrst und zu Absalom sagst: ›O König, ich will dein Diener sein! Wie ich bisher deines Vaters Diener gewesen bin, so will ich jetzt dein Diener sein!‹ – so könntest du mir die Ratschläge Ahithophels vereiteln.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 35, 'Dort sind ja auch die Priester Zadok und Abjathar bei dir; teile also alles, was du aus dem Hause des Königs erfährst, sofort den Priestern Zadok und Abjathar mit!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 36, 'Sie haben dort ihre beiden Söhne bei sich, Zadok den Ahimaaz und Abjathar den Jonathan; durch diese laßt mir Nachricht von allem zukommen, was ihr in Erfahrung bringt.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 37, 'So begab sich denn Davids vertrauter Freund Husai nach Jerusalem zurück, als Absalom gerade in die Stadt einzog.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 16, 1, 'David aber hatte die Höhe des Ölberges kaum etwas überschritten, als ihm Ziba, der Diener Mephiboseths, mit einem Paar gesattelter Esel entgegenkam, welche zweihundert Brote, hundert Rosinentrauben, hundert Feigenkuchen und einen Schlauch Wein trugen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 16, 2, 'Als der König nun Ziba fragte: »Was willst du damit?«, antwortete Ziba: »Die Esel sind für die königliche Familie zum Reiten bestimmt, die Brote aber und das getrocknete Obst für die Dienerschaft zum Essen und der Wein zum Trinken für die in der Wüste Ermatteten.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 16, 3, 'Als der König dann weiter fragte: »Wo ist denn der Sohn deines (früheren) Herrn?«, erwiderte Ziba dem König: »Ja, der ist in Jerusalem geblieben; denn er denkt, jetzt werde ihm das Haus Israel das Königtum seines Großvaters (Saul) zurückgeben.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 16, 4, 'Da sagte der König zu Ziba: »So soll denn der gesamte Besitz Mephiboseths dir gehören!« Ziba antwortete: »Ich werfe mich huldigend nieder! Mögest du mir auch ferner gnädig gesinnt sein, mein Herr und König!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 16, 5, 'Als hierauf der König David bis Bahurim gekommen war, trat dort auf einmal ein Mann vom Geschlecht des Hauses Saul namens Simei, der Sohn Geras, (aus dem Orte) heraus. Unter unaufhörlichen Verwünschungen kam er heraus');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 16, 6, 'und warf mit Steinen nach David und allen Leuten des Königs David, obgleich das ganze Volk und die gesamte Leibwache zur Rechten und zur Linken des Königs gingen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 16, 7, 'Simei stieß aber schreiend folgende Flüche aus: »Hinweg, hinweg mit dir, du Blutmensch, Bösewicht!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 16, 8, 'Endlich läßt der HERR alle deine Blutschuld am Hause Sauls, an dessen Stelle du dich zum König gemacht hast, auf dich zurückfallen, und der HERR hat das Königtum deinem Sohne Absalom übergeben! Und siehe, nun bist du ins Unglück geraten, weil du ein Blutmensch bist!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 16, 9, 'Da sagte Abisai, der Sohn der Zeruja, zum König: »Warum soll dieser tote Hund meinem Herrn, dem König, fluchen dürfen? Laß mich doch hingehen und ihm den Kopf abhauen!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 16, 10, 'Aber der König erwiderte: »Ihr Söhne der Zeruja, was habe ich mit euch zu schaffen? Laßt ihn doch fluchen! Denn wenn der HERR es ihm eingegeben hat, dem David zu fluchen, wer darf dann fragen: ›Warum tust du so?‹«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 16, 11, 'Weiter sagte David zu Abisai und allen seinen Hofleuten: »Wenn mein eigener leiblicher Sohn mir nach dem Leben trachtet: wieviel mehr jetzt dieser Benjaminit! Laßt ihn fluchen, denn der HERR hat es ihm eingegeben!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 16, 12, 'Vielleicht sieht der HERR mein Elend an und vergilt mir Gutes dafür, daß mir heute hier geflucht wird.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 16, 13, 'So zog denn David mit seinen Leuten seines Weges weiter, während Simei am Abhang des Berges neben ihm herging, indem er unaufhörlich Flüche ausstieß, mit Steinen nach ihm warf und Staub aufwirbelte.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 16, 14, 'Endlich kam der König mit allem Volk, das ihn begleitete, ermattet (am Jordan) an; dort konnte er sich erholen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 16, 15, 'Absalom aber war unterdessen mit seinem ganzen Anhang der Israeliten nach Jerusalem gekommen; auch Ahithophel war bei ihm.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 16, 16, 'Als nun der Arkiter Husai, Davids vertrauter Freund, zu Absalom kam, rief Husai dem Absalom zu: »Es lebe der König! Es lebe der König!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 16, 17, 'Absalom entgegnete ihm: »Ist das deine Treue gegen deinen Freund? Warum bist du nicht mit deinem Freunde gezogen?«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 16, 18, 'Da antwortete Husai dem Absalom: »Nein! Sondern wen der HERR und das Volk hier und alle Männer von Israel erwählt haben, dem gehöre ich an, und bei dem will ich bleiben!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 16, 19, 'Und zweitens: Wem leiste ich denn Dienste? Doch wohl seinem Sohne? Wie ich deinem Vater gedient habe, so will ich auch dir zur Verfügung stehen!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 16, 20, 'Darauf sagte Absalom zu Ahithophel: »Erteilt mir euren Rat, was wir tun sollen!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 16, 21, 'Ahithophel antwortete ihm: »Gehe ein zu den Kebsweibern deines Vaters, die er hier zur Hut des Hauses zurückgelassen hat. Wenn dann ganz Israel erfährt, daß du unwiderruflich mit deinem Vater gebrochen hast, so werden alle, die es mit dir halten, dadurch ermutigt werden.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 16, 22, 'Da schlug man für Absalom ein Zelt auf dem Dache (des Palastes) auf, und Absalom ging zu den Kebsweibern seines Vaters vor den Augen von ganz Israel.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 16, 23, 'Zu jener Zeit aber galt ein Rat, den Ahithophel gab, so viel wie eine Offenbarung Gottes: so hoch galten alle Ratschläge Ahithophels sowohl bei David als auch bei Absalom.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 17, 1, 'Nun sagte Ahithophel zu Absalom: »Ich will mir 12000 Mann auswählen und mich noch in dieser Nacht aufmachen, um David zu verfolgen;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 17, 2, 'ich werde ihn dann überfallen, während er noch ermattet und mutlos ist, und werde ihn in solchen Schrecken versetzen, daß die gesamte Mannschaft, die er bei sich hat, die Flucht ergreift und ich den König allein erschlagen kann.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 17, 3, 'Dann will ich alles Volk zu dir zurückbringen, wie man eine junge Frau zu ihrem Gatten zurückholt. Du trachtest ja doch nur einem Manne nach dem Leben, während das ganze übrige Volk unversehrt bleiben soll.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 17, 4, 'Der Rat fand den Beifall Absaloms und aller Ältesten der Israeliten;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 17, 5, 'dennoch befahl Absalom: »Man rufe noch den Arkiter Husai! wir wollen doch auch seine Ansicht hören!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 17, 6, 'Als nun Husai zu Absalom gekommen war, sagte dieser zu ihm: »So und so hat Ahithophel geraten; sollen wir seinen Vorschlag ausführen? Wenn nicht, so rede du!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 17, 7, 'Da antwortete Husai dem Absalom: »Diesmal ist der Rat, den Ahithophel erteilt hat, nicht gut.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 17, 8, 'Er fuhr dann fort: »Du weißt wohl, daß dein Vater und seine Leute Helden sind und voll wilden Mutes wie eine Bärin auf dem Felde, der man die Jungen geraubt hat. Außerdem ist dein Vater ein Kriegsmann, der seine Leute nicht Nachtruhe halten läßt.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 17, 9, 'Gewiß hat er sich schon jetzt in irgendeiner Schlucht oder sonstwo versteckt. Sollten nun gleich im Anfang einige von unsern Leuten fallen, so wird jeder, der es hört, behaupten: ›Die Leute, die es mit Absalom halten, haben eine Niederlage erlitten!‹');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 17, 10, 'Da würde dann auch der Tapferste, der ein Herz wie ein Löwe hat, sicherlich den Mut sinken lassen; ganz Israel weiß ja, daß dein Vater ein Held ist und wie tapfer die Männer sind, die er bei sich hat.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 17, 11, 'Ich rate vielmehr: Laß ganz Israel von Dan bis Beerseba bei dir sich versammeln, so zahlreich wie der Sand am Meer, und ziehe dann persönlich in ihrer Mitte ins Feld.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 17, 12, 'Treffen wir ihn dann an irgendeinem Ort, wo er sich aufhält, so fallen wir über ihn her, wie der Tau auf den Erdboden fällt, und es soll von ihm und allen Männern, die er bei sich hat, auch nicht einer übrigbleiben!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 17, 13, 'Zieht er sich aber in eine Stadt zurück, so soll ganz Israel Seile an die betreffende Stadt legen, und wir schleifen sie ins Tal hinunter, bis auch nicht ein Steinchen mehr dort zu finden ist.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 17, 14, 'Da erklärten Absalom und alle Israeliten: »Der Rat des Arkiters Husai ist besser als der Rat Ahithophels!« Der HERR hatte es nämlich so gefügt, daß der gute Rat Ahithophels verworfen wurde, weil der HERR Unheil über Absalom bringen wollte.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 17, 15, 'Hierauf teilte Husai den Priestern Zadok und Abjathar mit: »So und so hat Ahithophel dem Absalom und den Ältesten der Israeliten geraten, und so und so habe ich geraten.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 17, 16, 'Laßt also jetzt in aller Eile folgende Botschaft an David gelangen: ›Bleibe über Nacht nicht mehr in den Niederungen der Wüste (Juda), sondern setze auf jeden Fall (über den Jordan) hinüber, damit der König nicht mit allen Leuten, die er bei sich hat, vom Verderben ereilt wird.‹«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 17, 17, 'Jonathan und Ahimaaz hatten aber ihren Standort bei der Quelle Rogel, und eine Magd mußte von Zeit zu Zeit hingehen und ihnen Nachricht bringen; dann gingen sie jedesmal hin und erstatteten dem König Bericht; denn sie durften sich nicht sehen lassen, daß sie in die Stadt hätten kommen können.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 17, 18, 'Aber ein Knabe bemerkte sie und teilte es Absalom mit. Da entfernten die beiden sich eiligst und begaben sich in das haus eines Mannes zu Bachurim. Dieser hatte in seinem Hofe eine Zisterne, in die sie sich hinabließen;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 17, 19, 'die Frau nahm dann eine Decke, breitete diese oben über die Zisterne aus und schüttete Grütze darüber, so daß man nichts bemerken konnte.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 17, 20, 'Als nun die Leute Absaloms zu der Frau ins Haus kamen und fragten, wo Ahimaaz und Jonathan seien, antwortete ihnen die Frau: »Sie sind von hier nach dem Wasser weitergegangen.« Als jene sie nun trotz alles Suchens nicht fanden, kehrten sie nach Jerusalem zurück.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 17, 21, 'Nach ihrem Weggang stiegen dann die beiden aus der Zisterne herauf, gingen weiter, erstatteten dem König David Bericht und sagten zu David: »Macht euch auf und setzt eilends über den Jordan! Denn so und so hat Ahithophel in bezug auf euch geraten.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 17, 22, 'Da machte sich David mit allen Leuten, die er bei sich hatte, auf den Weg, und sie setzten über den Jordan. Bis der Morgen tagte, befanden sich alle bis auf den letzten Mann auf der andern Seite des Jordans.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 17, 23, 'Als nun Ahithophel sah, daß sein Rat nicht ausgeführt wurde, ließ er seinen Esel satteln und machte sich auf den Heimweg nach seinem Wohnort. Nachdem er dort sein Haus bestellt hatte, erhängte er sich; seine Leiche wurde dann im Begräbnis seines Vaters beigesetzt.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 17, 24, 'David aber war bereits in Mahanaim angekommen, als Absalom mit allen Israeliten über den Jordan setzte.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 17, 25, 'An Stelle Joabs hatte Absalom dem Amasa den Oberbefehl über das Heer übertragen. Dieser Amasa war der Sohn eines gewissen Jithra, eines Ismaeliten, der mit Abigail, der Tochter des Nahas, der Halbschwester der Zeruja, der Mutter Joabs, ein Verhältnis gehabt hatte.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 17, 26, 'So lagerten sich denn die Israeliten unter Absalom in der Landschaft Gilead.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 17, 27, 'Als aber David in Mahanaim angekommen war, hatten Sobi, der Sohn des Nahas, aus Rabba, (der Hauptstadt) der Ammoniter, und Machir, der Sohn Ammiels, aus Lodebar, und der Gileaditer Barsillai aus Rogelim');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 17, 28, 'Ruhebetten, Becken und irdenes Geschirr, dazu Weizen, Gerste, Mehl, geröstetes Korn, Bohnen, Linsen,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 17, 29, 'Honig und Butter, Kleinvieh und Kuhkäse für David und seine Leute zur Nahrung gebracht; denn sie hatten gedacht: »Die Leute müssen in der Steppe hungrig, müde und durstig geworden sein.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 18, 1, 'Nun musterte David das Kriegsvolk, das bei ihm war, und setzte Anführer ein über je tausend und über je hundert Mann.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 18, 2, 'Dann ließ David das Heer ausrücken, ein Drittel unter dem Befehl Joabs, ein Drittel unter Abisai, dem Sohn der Zeruja, dem Bruder Joabs, und das letzte Drittel unter dem Befehl Itthais aus Gath. Dabei sagte der König zu der Mannschaft: »Ich will auch mit euch ausziehen!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 18, 3, 'Aber die Leute entgegneten: »Nein, du darfst nicht mitziehen! Denn wenn wir geschlagen werden, wird man sich um uns nicht kümmern; und wenn auch die Hälfte von uns fiele, würde man sich um uns nicht kümmern, du dagegen bist so viel wert wie zehntausend von uns. Außerdem ist es besser, wenn du uns jederzeit von der Stadt aus Hilfe leisten kannst.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 18, 4, 'Da antwortete ihnen der König: »Ich will eurem Wunsche nachkommen!« Hierauf trat der König neben das Tor, während das ganze Heer nach Hunderten und Tausenden auszog.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 18, 5, 'Dem Joab, Abisai und Itthai aber erteilte der König den Befehl: »Geht mir schonend mit dem jungen Mann, mit Absalom, um!« Und das gesamte Kriegsvolk hörte es mit an, wie der König allen Anführern diesen Befehl in betreff Absaloms erteilte.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 18, 6, 'Als so das Heer ins Feld gegen die Israeliten gezogen war und es im Walde Ephraim zur Schlacht kam,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 18, 7, 'wurde dort das Heer der Israeliten von den Leuten Davids besiegt, so daß sie an diesem Tage dort eine schwere Niederlage, einen Verlust von zwanzigtausend Mann, erlitten.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 18, 8, 'Der Kampf breitete sich dann über die ganze Gegend dort aus, und der Wald brachte an diesem Tage noch mehr Leuten den Tod, als das Schwert es getan hatte.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 18, 9, 'Da kam Absalom zufällig den Leuten Davids zu Gesicht. Er ritt nämlich auf einem Maultier, und als dieses unter die verschlungenen Zweige einer großen Terebinthe geraten war, blieb er mit dem Haupt (-haar) an der Terebinthe hangen, so daß er zwischen Himmel und Erde schwebte, nachdem das Maultier unter ihm davongelaufen war.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 18, 10, 'Als das ein Mann sah, erstattete er dem Joab die Meldung: »Ich habe soeben Absalom an einer Terebinthe hängen sehen.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 18, 11, 'Da erwiderte Joab dem Manne, der ihm die Mitteilung gemacht hatte: »Nun, wenn du ihn gesehen hast, warum hast du ihn dort nicht gleich zur Erde heruntergeschlagen? Ich wäre dann in der Lage gewesen, dir zehn Silberstücke und einen Gürtel zu geben!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 18, 12, 'Der Mann aber antwortete dem Joab: »Und wenn mir tausend Silberstücke in die Hand gezahlt würden, wollte ich mich doch nicht an dem Sohne des Königs vergreifen; wir haben ja mit eigenen Ohren gehört, wie der König dir und Abisai und Itthai den bestimmten Befehl gegeben hat: ›Verfahrt mir schonend mit dem jungen Manne, mit Absalom!‹');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 18, 13, 'Hätte ich mich nun frevelhaft an seinem Leben vergriffen, so wäre die ganze Sache dem König doch nicht verborgen geblieben, und du selbst würdest dich abseits stellen.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 18, 14, 'Da sagte Joab: »Ich mag hier bei dir keine Zeit verlieren!« Hierauf nahm er drei Speere in die Hand und stieß sie dem Absalom ins Herz, während er, noch lebend, in den Zweigen der Terebinthe hing.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 18, 15, 'Dann traten zehn Knappen, Joabs Waffenträger, rings hinzu, schlugen Absalom herunter und töteten ihn vollends.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 18, 16, 'Darauf ließ Joab ein Zeichen mit der Posaune geben, da standen die Leute Davids von der Verfolgung der Israeliten ab; denn dem Volk wollte Joab Schonung erweisen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 18, 17, 'Darauf nahmen sie Absalom, warfen ihn im Walde in eine große Grube und türmten einen gewaltigen Steinhaufen über ihm auf. Alle Israeliten aber flohen, ein jeder in seinen Wohnort. –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 18, 18, 'Absalom hatte aber schon bei seinen Lebzeiten den Denkstein, der im Königstal steht, genommen und ihn für sich aufgerichtet; er hatte nämlich gedacht: »Ich habe keinen Sohn, der meinen Namen in der Erinnerung erhalten könnte.« Er hatte also den Denkstein nach seinem Namen benannt; und darum heißt er bis auf den heutigen Tag ›Absaloms Denkmal‹.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 18, 19, 'Ahimaaz aber, der Sohn Zadoks, sagte (zu Joab): »Ich möchte gern hinlaufen und dem König die Botschaft bringen, daß der HERR ihm den Sieg über seine Feinde verliehen hat!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 18, 20, 'Aber Joab erwiderte ihm: »Du bist heute nicht der rechte Mann für diese Botschaft; ein andermal magst du Bote sein, aber heute darfst du die Botschaft nicht überbringen, weil ja der Sohn des Königs tot ist.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 18, 21, 'Hierauf befahl Joab seinem Mohren: »Gehe hin, melde dem König, was du gesehen hast!« Da warf sich der Mohr vor Joab nieder und eilte davon.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 18, 22, 'Aber Ahimaaz, der Sohn Zadoks, sagte nochmals zu Joab: »Mag kommen, was da will: laß doch auch mich hinter dem Mohren herlaufen!« Joab entgegnete: »Wozu willst du denn laufen, mein Sohn? Dir wird doch kein Botenlohn ausgezahlt werden.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 18, 23, 'Er antwortete: »Mag kommen, was da will: ich laufe!« Da sagte Joab zu ihm: »Nun, so laufe!« Da schlug Ahimaaz den Weg durch die Jordanaue ein und überholte den Mohren.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 18, 24, 'David aber saß gerade inmitten der beiden Torpforten, während der Späher auf der Mauer nach dem Tordach zu ging. Als dieser nun Ausschau hielt, sah er einen einzelnen Mann heranlaufen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 18, 25, 'Da meldete es der Späher dem König durch Zuruf. Der König sagte: »Wenn es nur einer ist, so hat er gute Nachricht zu überbringen.« Während nun jener immer näher kam,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 18, 26, 'sah der Späher noch einen zweiten Mann heranlaufen und rief ins Tor hinein: »Ich sehe noch einen zweiten Mann allein heranlaufen!« Da sagte der König: »Auch der bringt gute Botschaft.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 18, 27, 'Der Späher rief dann weiter: »Am Laufen des ersten glaube ich Ahimaaz, den Sohn Zadoks, zu erkennen!« Der König sagte: »Das ist ein braver Mann: der kommt gewiß mit guter Botschaft!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 18, 28, 'Ahimaaz aber rief dem König zu: »Sieg!« Dann warf er sich vor dem Könige mit dem Gesicht zur Erde nieder und rief aus: »Gepriesen sei der HERR, dein Gott, der die Männer dahingegeben hat, die ihre Hand gegen meinen Herrn, den König, erhoben haben!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 18, 29, 'Der König aber fragte: »Geht es dem jungen Manne, dem Absalom, gut?« Ahimaaz antwortete: »Ich sah ein großes Getümmel, als des Königs Diener Joab deinen Knecht absandte, weiß aber nicht, was da vorging.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 18, 30, 'Der König entgegnete: »Tritt ab und bleibe hier stehen!« Da trat er ab und stellte sich abseits,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 18, 31, 'als auch schon der Mohr ankam und ausrief: »Mein Herr, der König, lasse sich die Freudenbotschaft melden, daß der HERR dir heute den Sieg über alle verliehen hat, die sich gegen dich empört haben!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 18, 32, 'Da fragte der König den Mohren: »Geht es dem jungen Manne, dem Absalom, gut?« Der Mohr antwortete: »Wie dem jungen Manne, so möge es den Feinden des Königs, meines Herrn, und allen ergehen, die sich in böser Absicht gegen dich auflehnen!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 1, 'Da erbebte der König, stieg in das Obergemach des Torgebäudes hinauf und weinte; im Gehen aber rief er die Worte aus: »Mein Sohn Absalom! Mein Sohn! Mein Sohn Absalom! Wäre doch ich selber statt deiner gestorben! O Absalom, mein Sohn, mein Sohn!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 2, 'Als nun dem Joab berichtet wurde, daß der König um Absalom weine und trauere,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 3, 'da wurde der Sieg an diesem Tage zur Trauer für das ganze Volk, weil jedermann an diesem Tage erfuhr, daß der König um seinen Sohn Leid trage.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 4, 'So stahl sich denn das Heer an jenem Tage zum Einzug in die Stadt heran, wie sich ein Heer heranstiehlt, das sich mit Schmach bedeckt hat, weil es in der Schlacht geflohen ist.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 5, 'Der König aber hatte sich das Gesicht verhüllt und wehklagte laut: »Mein Sohn Absalom! Absalom, mein Sohn, mein Sohn!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 6, 'Da begab sich Joab zum König ins Haus und sagte: »Du hast heute alle deine Knechte offen beschimpft, obgleich sie heute dir sowie deinen Söhnen und Töchtern, deinen Frauen und Nebenweibern das Leben gerettet haben!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 7, 'Denn du hast denen, die dich hassen, Liebe und denen, die dich lieben, Haß erwiesen; du hast ja heute offen gezeigt, daß dir an deinen Heerführern und Knechten nichts gelegen ist; ja, jetzt weiß ich, daß, wenn nur Absalom noch lebte und wir anderen alle heute tot wären, dir das gerade recht sein würde.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 8, 'Nun aber stehe auf, laß dich öffentlich sehen und gönne deinen Knechten ein freundliches Wort! Denn ich schwöre dir beim HERRN: Wenn du dich nicht öffentlich sehen läßt, so bleibt kein Mann mehr diese Nacht bei dir, und das wäre für dich schlimmer als alles Unglück, das du von deiner Jugend an bis jetzt erlebt hast!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 9, 'Da stand der König auf und setzte sich ins Tor; und als es dem ganzen Volk bekannt wurde, daß der König (nunmehr) im Tor sitze, erschienen alle Leute vor dem Könige. Als nun die Israeliten geflohen waren, ein jeder in seinen Wohnort,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 10, 'erhob das ganze Volk in allen Stämmen der Israeliten Vorwürfe gegen sich selbst; überall hieß es: »Der König hat uns aus der Gewalt unserer Feinde errettet, er hat uns von der Herrschaft der Philister befreit, und jetzt hat er vor Absalom aus dem Lande fliehen müssen!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 11, 'Nun aber, da Absalom, den wir zum König über uns gesalbt hatten, in der Schlacht ums Leben gekommen ist: warum zögert ihr da noch, den König zurückzuholen?«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 12, '(Als diese Äußerungen des gesamten Volkes zum König drangen) sandte der König David zu den Priestern Zadok und Abjathar und ließ ihnen sagen: »Redet mit den Ältesten von Juda und gebt ihnen zu erwägen: ›Warum wollt ihr die Letzten sein, die den König in sein Haus zurückführen?');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 13, 'Ihr seid doch meine Stammesgenossen, seid von meinem Fleisch und Bein: warum wollt ihr also die Letzten sein, wo es gilt, den König heimzuholen?‹');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 14, 'Und zu Amasa sollt ihr sagen: ›Du bist ja doch von meinem Fleisch und Bein: Gott strafe mich jetzt und künftig, wenn du nicht oberster Heerführer bei mir auf Lebenszeit an Joabs Statt wirst!‹«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 15, 'So gewann er die Herzen aller Männer von Juda, so daß sie einmütig die Aufforderung an den König richteten: »Kehre du mit allen deinen Dienern zurück!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 16, 'So trat denn der König den Rückweg an, und als er an den Jordan gelangte, waren ihm die Judäer nach Gilgal entgegengekommen, um den König einzuholen und ihn über den Jordan zu geleiten.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 17, 'Auch der Benjaminit Simei, der Sohn Geras, war aus Bachurim mit der Mannschaft der Judäer dem König David entgegengeeilt');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 18, 'und mit ihm tausend Mann aus dem Stamme Benjamin; außerdem auch Ziba, der Hausverwalter Sauls, mit seinen fünfzehn Söhnen und seinen zwanzig Knechten; sie waren schon vor der Ankunft des Königs über den Jordan gesetzt.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 19, 'Als nun die Fähre hinübergefahren war, um die königliche Familie herüberzuholen und sich dem König zur Verfügung zu stellen, warf sich Simei, der Sohn Geras, vor dem König nieder, als dieser eben über den Jordan fahren wollte,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 20, 'und richtete an den König die Worte: »Mein Herr wolle mir keine Verschuldung anrechnen und nicht des Vergehens gedenken, das dein Knecht sich hat zuschulden kommen lassen an dem Tage, als mein Herr, der König, Jerusalem verließ! Der König wolle es mir nicht unversöhnlich nachtragen!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 21, 'Dein Knecht weiß ja, daß ich mich vergangen habe; doch, wie du siehst, bin ich heute als der erste vom ganzen Hause Joseph herabgekommen, um meinen Herrn, den König, einzuholen.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 22, 'Als nun Abisai, der Sohn der Zeruja, das Wort nahm und ausrief: »Sollte Simei nicht den Tod dafür erleiden, daß er dem Gesalbten des HERRN geflucht hat?«,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 23, 'entgegnete David: »Ihr Söhne der Zeruja, was habe ich mit euch zu tun, daß ihr mir heute zum Satan werden wollt? Heute soll niemand in Israel den Tod erleiden, da ich doch weiß, daß ich heute wieder König über Israel bin!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 24, 'Hierauf sagte der König zu Simei: »Du sollst nicht sterben!«, und der König bekräftigte es ihm mit einem Eide.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 25, 'Auch Mephiboseth, Sauls Enkel, war herabgekommen dem König entgegen; er hatte aber weder seine Füße gereinigt, noch seinen Bart gepflegt, noch seine Kleider gewaschen seit dem Tage, an dem der König weggezogen war, bis zu dem Tage, an dem er glücklich heimkehrte.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 26, 'Als er nun von Jerusalem her dem König entgegenkam, fragte der König ihn: »Mephiboseth, warum bist du nicht mit mir ausgezogen?«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 27, 'Da antwortete er: »Mein Herr und König! Mein Diener hat mich betrogen! Dein Knecht hatte sich nämlich vorgenommen: ›Ich will mir doch meinen Esel satteln lassen und darauf reiten, um mit dem König zu ziehen – dein Knecht ist ja lahm –;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 28, 'aber er hat deinen Knecht bei meinem Herrn, dem König, verleumdet. Jedoch mein Herr, der König, gleicht (an Weisheit) dem Engel Gottes; so tu nun, was dir gefällt!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 29, 'Denn da das ganze Haus meines Vaters nichts anderes von meinem Herrn und König hat erwarten dürfen als den Tod und du dennoch deinen Knecht unter deine Tischgenossen aufgenommen hast – welches Recht hätte ich da noch, und was hätte ich da noch vom König zu beanspruchen?«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 30, 'Der König antwortete ihm: »Was machst du da noch Worte? Ich bestimme hiermit: Du und Ziba sollt euch in den Grundbesitz teilen!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 31, 'Da sagte Mephiboseth zum König: »Er mag sogar das Ganze hinnehmen, nachdem mein Herr und König glücklich heimgekehrt ist!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 32, 'Auch der Gileaditer Barsillai war von Rogelim herabgekommen und mit dem König an den Jordan gezogen, doch nur um ihn den Jordan entlang zu geleiten.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 33, 'Barsillai war nämlich sehr alt, ein Mann von achtzig Jahren; und er war’s gewesen, der den König während seines Aufenthalts in Mahanaim (mit Lebensmitteln) versorgt hatte, weil er ein sehr reicher Mann war.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 34, 'Nun sagte der König zu Barsillai: »Du mußt mit mir hinüberfahren; ich will für deinen Unterhalt bei mir in deinen alten Tagen in Jerusalem sorgen.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 35, 'Aber Barsillai erwiderte dem König: »Wie viele sind noch der Tage meiner Lebensjahre, daß ich mit dem König nach Jerusalem hinaufziehen sollte?');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 36, 'Ich bin jetzt achtzig Jahre alt: wie könnte ich da noch zwischen Gutem und Schlechtem unterscheiden? Kann dein Knecht etwa noch schmecken, was ich esse und trinke? Oder kann ich noch der Stimme der Sänger und Sängerinnen lauschen? Wozu sollte also dein Knecht meinem Herrn, dem König, noch zur Last fallen?');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 37, 'Nein, nur eben über den Jordan möchte dein Knecht mit dem König fahren. Und warum will der König mir mit so reichem Lohn vergelten?');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 38, 'Laß doch deinen Knecht heimkehren, damit ich in meiner Vaterstadt beim Grabe meines Vaters und meiner Mutter sterbe! Aber siehe, hier ist (mein Sohn,) dein Knecht Kimham: der mag mit meinem Herrn, dem König, hinüberfahren, und tu an ihm, was du für gut hältst!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 39, 'Der König antwortete: »Ja, Kimham soll mit mir hinüberfahren, und ich will an ihm tun, was dir erfreulich ist, und will dir jeden Wunsch erfüllen!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 40, 'Als dann alles Kriegsvolk über den Jordan gesetzt und auch der König hinübergefahren war, küßte dieser den Barsillai und nahm mit Segenswünschen Abschied von ihm; darauf kehrte jener in seinen Wohnort zurück,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 41, 'während der König nach Gilgal weiterfuhr und Kimham ihn begleitete. Das gesamte Kriegsvolk von Juda aber und auch die Hälfte des Kriegsvolkes von Israel war mit dem König hinübergezogen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 42, 'Da kamen plötzlich alle Männer Israels zum König und fragten ihn: »Warum haben unsere Volksgenossen, die Judäer, dich entführt und haben den König mit seiner Familie und seinem ganzen Hofe über den Jordan gebracht?«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 43, 'Da antworteten alle Judäer den Israeliten: »Der König steht uns doch am nächsten! Warum regt ihr euch hierüber so auf? Haben wir etwa auf Kosten des Königs gelebt? Oder hat er uns irgendein Geschenk gemacht?«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 44, 'Aber die Israeliten entgegneten den Judäern: »Wir haben den zehnfachen Anteil am König, und somit haben wir auch an David mehr Anrecht als ihr: warum habt ihr uns also zurückgesetzt? Und haben wir nicht zuerst die Absicht ausgesprochen, unsern König zurückzuholen?« Die Worte der Judäer aber waren darauf noch leidenschaftlicher als die der Israeliten.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 20, 1, 'Nun befand sich dort zufällig ein nichtswürdiger Mensch namens Seba, der Sohn Bichris, ein Benjaminit; der stieß in die Posaune und rief aus: »Wir haben keinen Anteil an David und nichts zu schaffen mit dem Sohne Isais! Ein jeder begebe sich in seinen Wohnort, ihr Israeliten!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 20, 2, 'Da fielen die Israeliten insgesamt von David ab und schlossen sich an Seba, den Sohn Bichris, an; die Judäer aber blieben ihrem König treu (und geleiteten ihn) vom Jordan bis nach Jerusalem.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 20, 3, 'Als nun David in seinen Palast nach Jerusalem zurückgekommen war, ließ er die zehn Nebenweiber, die er zur Hut des Palastes zurückgelassen hatte, in ein besonderes Haus bringen und sorgte dort für ihren Unterhalt, hatte aber keinen Verkehr mehr mit ihnen; so lebten sie eingesperrt bis zu ihrem Todestag gleichsam als Witwen bei Lebzeiten (ihres Mannes).');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 20, 4, 'Darauf befahl der König dem Amasa: »Biete mir die Mannschaft von Juda binnen drei Tagen auf und sei du selbst dann hier zur Stelle!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 20, 5, 'Amasa machte sich nun daran, die Judäer aufzubieten; als er jedoch über die ihm genau bestimmte Zeit hinaus ausblieb,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 20, 6, 'sagte David zu Abisai: »Nun wird Seba, der Sohn Bichris, für uns noch gefährlicher werden als Absalom. Nimm du die Leute deines Herrn und verfolge ihn, damit er nicht etwa feste Städte für sich gewinnt und uns viel zu schaffen macht!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 20, 7, 'Da zogen denn unter Abisais Führung Joab mit seinen Leuten sowie die (Leibwache der) Krethi und Plethi und alle ›Kriegshelden‹ ins Feld; sie zogen aus Jerusalem aus, um Seba, den Sohn Bichris, zu verfolgen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 20, 8, 'Als sie nun bei dem großen Stein in Gibeon waren, kam Amasa ihnen zu Gesicht. Joab aber war mit seinem Waffenrock bekleidet und hatte sich darüber ein Schwert umgegürtet, das ihm in seiner Scheide an die Hüfte gekoppelt war und das er, als er vorging, aus der Scheide herausfallen ließ.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 20, 9, 'Darauf redete Joab den Amasa mit den Worten an: »Geht es dir gut, lieber Bruder?« Dabei faßte Joab mit der rechten Hand Amasa beim Bart, um ihn zu küssen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 20, 10, 'Amasa hatte aber nicht auf das Schwert geachtet, das Joab in der (linken) Hand hatte; so stieß Joab es ihm in den Leib, so daß ihm die Eingeweide auf die Erde herausfielen und er starb, ohne daß er ihm noch einen zweiten Stoß zu versetzen brauchte. Während dann Joab und sein Bruder Abisai die Verfolgung Sebas, des Sohnes Bichris, fortsetzten,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 20, 11, 'mußte einer von den Leuten Joabs bei Amasa stehen bleiben und ausrufen: »Wer es mit Joab hält und wer für David ist, folge Joab nach!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 20, 12, 'Amasa aber hatte sich in seinem Blute gewälzt und lag mitten auf der Straße. Als nun der Mann sah, daß die Leute alle stehenblieben, schaffte er Amasa von der Straße weg aufs Feld und warf einen Mantel über ihn, weil er sah, daß alle, die an ihn herankamen, stehenblieben.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 20, 13, 'Nachdem er ihn aber von der Straße weggeschafft hatte, zogen alle Leute vorüber hinter Joab her, um an der Verfolgung Sebas teilzunehmen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 20, 14, 'Dieser hatte aber alle Stämme Israels bis nach Abel-Beth-Maacha durchzogen (freilich mit geringem Erfolg); nur eben alle Bichrileute waren hinter ihm hergekommen, ebenfalls dorthin.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 20, 15, 'Nun kamen jene heran und belagerten ihn in Abel-Beth-Maacha; sie führten gegen die Stadt einen Wall auf, der an die Außenmauer stieß; und alle Leute Joabs unterwühlten die Mauer, um sie zum Einsturz zu bringen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 20, 16, 'Da (trat) eine kluge Frau (auf die Vormauer und) rief aus der Stadt heraus: »Hört, hört! Fordert doch Joab auf, hierher zu kommen: ich möchte mit ihm reden!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 20, 17, 'Als er nun nahe an sie herangekommen war, fragte die Frau: »Bist du Joab?« Er antwortete ihr: »Ja, ich bin’s.« Da sagte sie zu ihm: »Höre, was deine Magd dir zu sagen hat!« Er antwortete: »Ich höre!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 20, 18, 'Da fuhr sie fort: »Früher pflegte der Volksmund zu sagen: ›Fragt nur in Abel an!‹, und so kam man glücklich ans Ziel.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 20, 19, 'Wir gehören zu den friedlichsten, getreusten Leuten in Israel, und du suchst eine Stadt, eine Muttergemeinde in Israel zu zerstören? Warum willst du das Eigentum des HERRN zugrunde richten?«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 20, 20, 'Da antwortete Joab: »Ganz fern liegt es mir, daß ich zerstören und daß ich zugrunde richten will.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 20, 21, 'Die Sache liegt nicht so, sondern ein Mann vom Gebirge Ephraim namens Seba, der Sohn Bichris, hat sich gegen den König, gegen David, empört; liefert ihn aus, ihn allein, so ziehe ich von der Stadt ab!« Da erwiderte die Frau dem Joab: »Sein Kopf soll dir alsbald über die Mauer zugeworfen werden!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 20, 22, 'Hierauf redete die Frau (in der Stadt) mit ihrer Klugheit auf die ganze Einwohnerschaft so lange ein, bis sie Seba, dem Sohne Bichris, den Kopf abhieben und ihn dem Joab zuwarfen. Da ließ Joab mit der Posaune zum Abzug blasen, und seine Leute zogen von der Stadt ab und zerstreuten sich, ein jeder in seinen Wohnort; Joab aber kehrte nach Jerusalem zum König zurück.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 20, 23, 'Joab war oberster Heerführer in Israel; Benaja, der Sohn Jojadas, war Befehlshaber (der Leibwache) der Krethi und Plethi;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 20, 24, 'Adoram war Oberaufseher über die Fronarbeiten; Josaphat, der Sohn Ahiluds, war Kanzler;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 20, 25, 'Seja war Staatsschreiber; Zadok und Abjathar waren Priester,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 20, 26, 'und Ira, der Jairit, war ebenfalls ein Priester Davids.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 21, 1, 'Unter der Regierung Davids herrschte einst eine Hungersnot drei Jahre lang, Jahr für Jahr. Als sich David nun an den HERRN mit einer Anfrage wandte, antwortete der HERR, auf Saul und seinem Hause laste eine Blutschuld, weil er die Gibeoniten getötet habe.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 21, 2, 'Da ließ der König die Gibeoniten kommen und fragte sie – die Gibeoniten gehörten nämlich nicht zu den Israeliten, sondern zu dem Überrest der Amoriter; obgleich nun die Israeliten einen Vertrag (mit ihnen geschlossen und ihn) beschworen hatten, war Saul doch in seinem Eifer für die Israeliten und Judäer darauf ausgegangen, sie auszurotten. –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 21, 3, 'David fragte also die Gibeoniten: »Was soll ich für euch tun, und womit soll ich Sühne schaffen, damit ihr das Eigentumsvolk des HERRN (wieder) segnet?«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 21, 4, 'Die Gibeoniten antworteten ihm: »Es ist uns dem Saul und seinem Hause gegenüber nicht um Silber und Gold zu tun, auch kommt es uns nicht zu, jemand in Israel zu töten.« Da fragte er sie: »Was verlangt ihr, daß ich für euch tun soll?«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 21, 5, 'Da antworteten sie dem König: »Der Mann, der uns hat vernichten wollen und der darauf ausgegangen ist, uns auszurotten, damit in keinem Teil Israels unseres Bleibens mehr sein sollte: –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 21, 6, 'von dessen Nachkommen liefere man uns sieben Männer aus, daß wir sie vor dem HERRN aufhängen in Sauls-Gibea auf dem Berge des HERRN.« Da sagte der König: »Ich will sie euch geben.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 21, 7, 'Der König verschonte aber Mephiboseth, den Sohn Jonathans und Enkel Sauls, um des Schwures beim HERRN willen, der zwischen David und Jonathan, dem Sohne Sauls, bestand.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 21, 8, 'Der König nahm vielmehr die beiden Söhne, welche Rizpa, die Tochter Ajjas, dem Saul geboren hatte, Armoni und Mephiboseth, dazu die fünf Söhne, welche Merab, die Tochter Sauls, dem Adriel, dem Sohne des Meholathiters Barsillai, geboren hatte.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 21, 9, 'Er übergab sie den Gibeoniten, und diese hängten sie vor dem HERRN auf dem Berge auf. So kamen die sieben zu gleicher Zeit ums Leben, und zwar wurden sie in den ersten Tagen der Ernte, bei Beginn der Gerstenernte, getötet.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 21, 10, 'Da nahm Rizpa, die Tochter Ajjas, Sackleinwand und breitete es (als Lager) für sich auf dem Felsen aus, vom Beginn der Ernte an, bis der Herbstregen auf die Toten niederfiel; und sie sorgte dafür, daß bei Tage kein Raubvogel und während der Nacht kein wildes Tier an die Leichen herankam. –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 21, 11, 'Als man nun David berichtete, was Rizpa, das Nebenweib Sauls, die Tochter Ajjas, getan hatte,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 21, 12, 'ging er hin und ließ sich von den Bürgern der Stadt Jabes in Gilead die Gebeine Sauls und die Gebeine seines Sohnes Jonathan ausliefern, die sie einst vom Marktplatz in Beth-San heimlich weggeholt hatten, wo die Philister sie damals aufgehängt hatten, als die Philister Saul auf dem Gilboa geschlagen hatten.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 21, 13, 'Als nun David die Gebeine Sauls und die seines Sohnes Jonathan von dort hatte holen lassen, sammelte man auch die Gebeine der Gehenkten');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 21, 14, 'und begrub sie bei den Gebeinen Sauls und seines Sohnes Jonathan im Gebiet des Stammes Benjamin zu Zela im Begräbnis seines Vaters Kis. Als man so alles nach dem Befehl des Königs ausgeführt hatte, ließ Gott sich von da an für das Land wieder günstig stimmen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 21, 15, 'Als einst wieder einmal ein Krieg zwischen den Philistern und Israeliten ausgebrochen und David mit seinen Leuten hinabgezogen war (und sie sich in Gob festgesetzt hatten), um mit den Philistern zu kämpfen, und David ermüdet war,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 21, 16, 'da war da ein Mann namens Jisbi-Benob, einer von den Riesenkindern; der hatte einen Speer, dessen eherne Spitze dreihundert Schekel wog, und hatte eine neue Rüstung an und gedachte David zu erschlagen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 21, 17, 'Aber Abisai, der Sohn der Zeruja, kam ihm zu Hilfe und schlug den Philister tot. Damals beschworen Davids Leute ihn mit den Worten: »Du darfst nicht wieder mit uns in den Kampf ziehen, damit du die Leuchte Israels nicht auslöschest!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 21, 18, 'Später kam es dann nochmals zum Kampf mit den Philistern bei Gob. Damals erschlug der Husathiter Sibbechai den Saph, der auch zu den Riesenkindern gehörte.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 21, 19, 'Dann fand nochmals ein Kampf mit den Philistern bei Gob statt; und Elhanan aus Bethlehem, der Sohn Jaare-Orgims, erschlug den Goliath aus Gath, dessen Speerschaft wie ein Weberbaum war.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 21, 20, 'Als es dann wiederum zum Kampf und zwar bei Gath kam, war da ein Mann von riesiger Größe, der an jeder Hand sechs Finger und an jedem Fuß sechs Zehen hatte, im ganzen vierundzwanzig; auch dieser stammte aus dem Riesengeschlecht.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 21, 21, 'Er hatte die Israeliten verhöhnt; aber Jonathan, der Sohn Simeas, des Bruders Davids, erschlug ihn.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 21, 22, 'Diese vier stammten aus dem Riesengeschlecht in Gath, und sie fielen durch die Hand Davids und seiner Krieger.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 1, 'Das folgende Lied richtete David an den HERRN zu der Zeit, als der HERR ihn aus der Hand aller seiner Feinde und (besonders) aus der Hand Sauls errettet hatte. Er betete (damals):');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 2, 'Der HERR ist mein Fels, meine Burg und mein Erretter;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 3, 'Gott ist mein Fels, zu dem ich mich flüchte, mein Schild und das Horn meines Heils, mein fester Turm und meine Zuflucht, mein Erretter, der von Gewalttat mich rettet.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 4, 'Den Preiswürdigen rufe ich an, den HERRN: so werd’ ich von meinen Feinden errettet.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 5, 'Denn die Wogen des Todes hatten mich umringt, die Ströme des Unheils schreckten mich,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 6, 'die Netze des Totenreichs umfingen mich, die Schlingen des Todes fielen über mich.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 7, 'In meiner Angst rief ich zum HERRN und schrie um Hilfe zu meinem Gott; da vernahm er in seinem Palast mein Rufen, und mein Notschrei drang zu seinen Ohren.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 8, 'Da wankte und schwankte die Erde, des Himmels Grundfesten bebten und wankten hin und her, denn er war zornentbrannt;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 9, 'Rauch stieg auf aus seiner Nase, und fressendes Feuer drang aus seinem Munde, glühende Kohlen sprühten von ihm aus.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 10, 'Er neigte den Himmel und fuhr herab, Wolkennacht lag unter seinen Füßen;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 11, 'Er fuhr auf dem Cherub und flog daher und schoß herab auf den Fittichen des Sturms;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 12, 'Finsternis machte er rings um sich her zu seinem Gezelt, Regendunkel, dichtes Gewölk;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 13, 'aus dem Glanz vor ihm her brannten Feuerflammen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 14, 'Dann donnerte der HERR vom Himmel her, der Höchste ließ seine Stimme erschallen;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 15, 'er schoß seine Pfeile ab und zerstreute sie, schleuderte Blitze und schreckte sie.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 16, 'Da wurden sichtbar die Tiefen des Meeres und aufgedeckt die Grundfesten der Erde durch das Schelten des HERRN, von dem Zornesschnauben seiner Nase.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 17, 'Er streckte die Hand herab aus der Höhe, ergriff mich, zog mich heraus aus den großen Fluten,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 18, 'entriß mich meinem starken Feinde, meinen Widersachern, die zu stark mir waren.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 19, 'Sie hatten mich überfallen an meinem Unglückstage, doch der HERR ward mir zur Stütze;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 20, 'er führte mich heraus auf weiten Raum, riß mich heraus, weil er Wohlgefallen an mir hatte.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 21, 'Der HERR hat mir gelohnt nach meiner Gerechtigkeit, nach der Reinheit meiner Hände mir vergolten;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 22, 'denn ich habe innegehalten die Wege des HERRN und bin von meinem Gott nicht treulos abgefallen;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 23, 'nein, alle seine Rechte haben mir vor Augen gestanden, und von seinen Geboten bin ich nicht abgewichen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 24, 'So bin ich unsträflich vor ihm gewandelt und hab’ mich vor jeder Verschuldung gehütet;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 25, 'drum hat mir der HERR vergolten nach meiner Gerechtigkeit, nach meiner Reinheit, die seinen Augen sichtbar war.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 26, 'Gegen den Guten erweist du dich gütig, gegen den Redlichen zeigst du dich redlich,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 27, 'gegen den Reinen erweist du dich rein, doch gegen den Falschen zeigst du dich enttäuschend;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 28, 'denn du schaffst demütigen Leuten Hilfe, aber stolze Augen erniedrigst du.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 29, 'Ja, du bist meine Leuchte, o HERR; und mein Gott erhellt meine Finsternis.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 30, 'Denn mit dir überrenne ich Feindesscharen, mit meinem Gott überspringe ich Mauern.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 31, 'Dieser Gott – sein Walten ist vollkommen, die Worte des HERRN sind lauter, ein Schild ist er allen, die zu ihm sich flüchten.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 32, 'Denn wer ist Gott außer dem HERRN und wer ein Fels als nur unser Gott?,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 33, 'dieser Gott, der mit Kraft mich gegürtet und der meinen Weg ohn’ Anstoß gemacht;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 34, 'der mir Füße verliehen den Hirschen gleich und mich sicher auf Bergeshöhen gestellt;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 35, 'der meine Hände streiten gelehrt, daß meine Arme den ehernen Bogen spannten.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 36, 'Du reichtest mir deinen schützenden Schild, und deine Gnade machte mich groß.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 37, 'Du schafftest weiten Raum meinen Schritten unter mir, und meine Knöchel wankten nicht.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 38, 'Ich verfolgte meine Feinde, vertilgte sie und kehrte nicht um, bis ich sie vernichtet;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 39, 'ich vernichtete und zerschmetterte sie, daß sie nicht wieder aufstehn konnten: sie sanken unter meine Füße nieder.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 40, 'Und du gürtetest mich mit Kraft zum Streit, beugtest unter mich, die sich gegen mich erhoben;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 41, 'du triebst meine Feinde vor mir in die Flucht, und alle, die mich haßten, vernichtete ich.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 42, 'Sie blickten nach Hilfe umher – doch da war kein Helfer – zum HERRN – doch er hörte sie nicht;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 43, 'ich zermalmte sie wie Staub auf dem Boden, wie Kot auf den Gassen zertrat, zerstampfte ich sie.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 44, 'Du hast mich aus meines Volkes Fehden errettet, mich zum Oberhaupt von Völkern eingesetzt: Völker, die ich nicht kannte, dienen mir;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 45, 'die Söhne des Auslands huldigen mir, aufs bloße Wort gehorchen sie mir;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 46, 'die Söhne des Auslands sinken mutlos hin und kommen zitternd hervor aus ihren Schlössern.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 47, 'Der HERR lebt: gepriesen sei mein Hort!, und erhaben ist der Gott, der Fels meines Heils,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 48, 'der Gott, der mir Rache verliehen und die Völker unter meine Herrschaft gezwungen,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 49, 'der mich von meinen Feinden frei gemacht und über meine Widersacher mich erhöht, von dem Mann der Gewalttat mich befreit hat!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 50, 'Drum will ich dich preisen, HERR, unter den Völkern und deinem Namen lobsingen,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 51, 'dir, der seinem Könige großes Heil verleiht und Gnade an seinem Gesalbten übt, an David und seinem Hause ewiglich!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 1, 'Dies sind Davids letzte Worte: Ausspruch Davids, des Sohnes Isais, und Ausspruch des Mannes, der hoch erhoben ward, des Gesalbten des Gottes Jakobs und des Lieblings der Lieder Israels:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 2, 'Der Geist des HERRN redet in mir, und sein Wort liegt auf meiner Zunge.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 3, 'Es hat gesprochen der Gott Israels, der Fels Israels zu mir gesagt: Wer gerecht herrscht über die Menschen, wer da herrscht in der Furcht Gottes,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 4, 'der ist wie das Licht, das am Morgen aufstrahlt, wie die Sonne am Morgen ohne Gewölk: von ihrem Glanz nach dem Regen sproßt junges Grün aus der Erde hervor.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 5, 'Ja, steht nicht so mein Haus zu Gott? Hat er doch einen ewigen Bund mit mir geschlossen, der in allen Stücken gesichert und festgestellt ist. Ja, all mein Glück und all mein Verlangen, sollte er das nicht sprossen lassen?');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 6, 'Die Bösen aber sind allesamt wie Dornen, die man wegwirft; denn mit der Hand faßt man sie nicht an;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 7, 'nein, wer sich mit ihnen befaßt, bewehrt sich mit Eisen und Speerschaft, und im Feuer verbrennt man sie gänzlich an ihrer Stätte.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 8, 'Dies sind die Namen der Helden Davids: Joseb-Bassebeth, der Tahchemoniter, das Haupt der Drei; der schwang seinen Speer über achthundert (Feinden), die er auf einmal erschlagen hatte. –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 9, 'Nach ihm kam unter den drei (Rittern) Eleasar, der Sohn Dodos, der Ahohiter. Er war bei David in Pas-Dammim, als die Philister sich dort zur Schlacht versammelt hatten. Als nun die Israeliten sich vor ihnen zurückzogen,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 10, 'war er es, der standhielt und unter den Philistern ein Blutbad anrichtete, bis sein Arm erlahmt war und seine Hand am Schwert kleben blieb. So verlieh der HERR (den Israeliten) an jenem Tage einen herrlichen Sieg. Da kehrte das Heer unter seiner Führung wieder um, doch nur, um (die Erschlagenen) auszuplündern. –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 11, 'Nach ihm kam Samma, der Sohn des Harariters Age. Einst hatten sich nämlich die Philister in Lehi gesammelt, und es war dort ein Ackerstück mit Linsen; als nun das Heer vor den Philistern floh,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 12, 'trat er mitten auf das Feld, behauptete es und schlug die Philister; so verlieh (ihm) der HERR einen herrlichen Sieg.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 13, 'Einst kamen drei von den dreißig Rittern während der Erntezeit zu David in die Höhle von Adullam hinab, während die Schar der Philister sich in der Ebene Rephaim gelagert hatte.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 14, 'David befand sich aber damals in der Bergfeste, während eine Besatzung der Philister damals in Bethlehem lag.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 15, 'Nun verspürte David ein Gelüsten und rief aus: »Wer verschafft mir Wasser zu trinken aus dem Brunnen, der in Bethlehem am Stadttor liegt?«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 16, 'Da schlugen sich die drei Helden durch das Lager der Philister hindurch, schöpften Wasser aus dem Brunnen am Tor zu Bethlehem und brachten es glücklich zu David hin. Aber dieser wollte es nicht trinken, sondern goß es als Trankopfer für den HERRN aus');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 17, 'mit den Worten: »Der HERR behüte mich davor, daß ich so etwas tun sollte! Das ist ja das Blut der Männer, die unter Lebensgefahr dorthin gezogen sind!« Und er wollte es nicht trinken. Das hatten die drei Helden ausgeführt.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 18, 'Abisai aber, der Bruder Joabs, der Sohn der Zeruja, war das Haupt der Dreißig; der schwang seinen Speer über dreihundert (Feinden), die er erschlagen hatte, und besaß hohes Ansehen unter den Dreißig.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 19, 'Unter den Dreißig genoß er die höchste Ehre, so daß er auch ihr Oberster wurde; aber an die (ersten) drei Helden reichte er nicht heran. –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 20, 'Benaja, der Sohn Jojadas, (ein tapferer Mann), groß an Taten, stammte aus Kabzeel; er war es, der die beiden Söhne Ariels aus Moab erschlug. Auch stieg er einmal in eine Zisterne hinab und erschlug darin einen Löwen an einem Tage, an dem Schnee gefallen war.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 21, 'Auch erschlug er einen Ägypter von riesiger Größe, der einen Speer in der Hand hatte; er aber ging mit einem Stecken auf ihn los, riß dem Ägypter den Speer aus der Hand und tötete ihn mit seinem eigenen Speer.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 22, 'Das tat Benaja, der Sohn Jojadas; er besaß hohes Ansehen unter den dreißig Rittern');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 23, 'und war der geehrteste unter den Dreißig, aber an die (ersten) drei Helden reichte er nicht heran. David stellte ihn an die Spitze seiner Leibwache.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 24, 'Zu den dreißig (Rittern) gehörten: Asahel, der Bruder Joabs; Elhanan aus Bethlehem, der Sohn Dodos;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 25, 'Samma aus Harod; Elika aus Harod;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 26, 'Helez aus Pelet; Ira, der Sohn des Ikkes, aus Thekoa;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 27, 'Abieser aus Anathoth; Mebunnai aus Husa;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 28, 'Zalmon aus Ahoah; Maharai aus Netopha;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 29, 'Heleb, der Sohn Baanas, aus Netopha; Itthai, der Sohn Ribais, aus Gibea im Stamme Benjamin;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 30, 'Benaja aus Pirathon; Hiddai aus Nahale-Gaas;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 31, 'Abi-Albon aus Beth-Araba; Asmaweth aus Bahurim;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 32, 'Eljahba aus Saalbon; Jasen, der Gunit;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 33, 'Jonathan, der Sohn Sammas, aus Harar; Ahiam, der Sohn Sarars, aus Harar;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 34, 'Eliphelet, der Sohn Ahasbais, aus Beth-Maacha; Eliam, der Sohn Ahithophels, aus Gilo;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 35, 'Hezrai aus Karmel; Paarai, der Arkiter;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 36, 'Jigal, der Sohn Nathans, aus Zoba; Bani aus Gad;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 37, 'Zelek, der Ammoniter; Naharai aus Beeroth, der Waffenträger Joabs, des Sohnes der Zeruja;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 38, 'Ira aus Jatthir; Gareb aus Jatthir;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 39, 'Uria, der Hethiter: zusammen siebenunddreißig.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 24, 1, 'Der Zorn des HERRN aber entbrannte (einst) aufs neue gegen Israel, so daß er David gegen das Volk reizte durch die Aufforderung: »Auf! Nimm eine Zählung in Israel und Juda vor!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 24, 2, 'Da befahl der König seinem Heerführer Joab (und den Heeresobersten bei ihm): »Durchwandre alle Stammgebiete Israels von Dan bis Beerseba und nehmt eine Volkszählung vor, damit ich die Zahl des Volkes erfahre!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 24, 3, 'Joab antwortete dem König: »Der HERR, dein Gott, möge das Volk, so zahlreich es auch schon ist, noch hundertmal zahlreicher werden lassen, und mein Herr, der König, möge das selbst noch mit eigenen Augen schauen! Aber warum trägt mein Herr, der König, Verlangen nach einer derartigen Vornahme?«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 24, 4, 'Doch der Befehl des Königs blieb trotz den Vorstellungen Joabs und der Heeresobersten bestehen, und so machte sich denn Joab mit den Heeresobersten auf Geheiß des Königs daran, die Volkszählung in Israel vorzunehmen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 24, 5, 'Sie gingen also über den Jordan und lagerten sich bei Aroer rechts von der Stadt, die inmitten des Flußtales (des Arnon) liegt, in der Richtung nach Gad und nach Jaser hin.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 24, 6, 'Dann begaben sie sich nach Gilead und bis zum Lande der Hethiter gegen Kades hin; hierauf gelangten sie nach Dan, bogen hierauf um nach Sidon zu,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 24, 7, 'kamen alsdann zu der festen Stadt Tyrus und zu allen Ortschaften der Hewiter und Kanaanäer und begaben sich schließlich in das Südland von Juda, nach Beerseba.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 24, 8, 'Nachdem sie so das ganze Land durchzogen hatten, kehrten sie nach Verlauf von neun Monaten und zwanzig Tagen nach Jerusalem zurück.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 24, 9, 'Da teilte Joab dem König das Ergebnis der Volkszählung mit, und zwar belief sich die Zahl der kriegstüchtigen, schwertbewaffneten Männer in Israel auf 800000, in Juda auf 500000 Mann.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 24, 10, 'Nachdem aber David die Volkszählung hatte vornehmen lassen, schlug ihm das Gewissen; daher betete er zum HERRN: »Ich habe mich durch mein Tun schwer versündigt; doch laß nun, o HERR, deinem Knecht seine Verschuldung ungestraft hingehen, denn ich habe in großer Verblendung gehandelt!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 24, 11, 'Als aber David am folgenden Morgen aufstand, erging das Wort des HERRN an den Propheten Gad, den Seher Davids, folgendermaßen:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 24, 12, '»Gehe hin und sage zu David: ›So hat der HERR gesprochen: Dreierlei lege ich dir vor: wähle dir eins davon, damit ich es an dir zur Ausführung bringe!‹«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 24, 13, 'Da begab sich Gad zu David, teilte es ihm mit und sagte zu ihm: »Sollen dir zur Strafe drei Jahre Hungersnot über dein Land kommen? Oder willst du drei Monate lang vor deinen Feinden fliehen müssen und von ihnen verfolgt werden? Oder soll die Pest drei Tage lang in deinem Lande sein? Nun gehe mit dir zu Rat und überlege, welche Antwort ich dem bringen soll, der mich gesandt hat.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 24, 14, 'Da sagte David zu Gad: »Mir ist sehr bange! Wir wollen aber lieber in die Hand des HERRN fallen, denn sein Erbarmen ist groß; aber in die Hand von Menschen möchte ich nicht fallen!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 24, 15, 'Da ließ der HERR eine Pest über Israel kommen vom Morgen an bis zum Nachmittag, und es starben aus dem Volke von Dan bis Beerseba siebzigtausend Menschen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 24, 16, 'Als aber der Engel seine Hand gegen Jerusalem ausstreckte, um es zu vernichten, da gereute den HERRN das Unheil, und er gebot dem Engel, der das Unglück unter dem Volke anzurichten hatte: »Es ist genug so! Laß jetzt deine Hand ruhen!« Der Engel des HERRN befand sich aber gerade bei der Tenne des Jebusiters Arawna.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 24, 17, 'Als nun David den Engel sah, der das Sterben unter dem Volke anrichtete, rief er, zum HERRN betend, aus: »Ach, ich bin’s ja, der gesündigt hat, und ich habe mich vergangen! Diese Herde aber – was hat sie verschuldet? Laß doch deine Hand mich und meine Familie treffen!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 24, 18, 'An jenem Tage kam dann Gad zu David und sagte zu ihm: »Gehe hinauf und errichte dem HERRN einen Altar auf der Tenne des Jebusiters Arawna!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 24, 19, 'Da begab sich David nach der Aufforderung Gads, dem Befehl des HERRN gehorsam, hinauf.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 24, 20, 'Als nun Arawna von oben her ausschaute und den König mit seinen Dienern auf sich zukommen sah (Arawna war nämlich gerade mit dem Dreschen des Weizens beschäftigt), trat er hinaus und verneigte sich vor David mit dem Angesicht bis zur Erde.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 24, 21, 'Hierauf fragte Arawna: »Warum kommt mein Herr, der König, zu seinem Knecht?« David antwortete: »Um die Tenne von dir zu kaufen; ich will hier dem HERRN einen Altar errichten, damit dem Sterben unter dem Volk Einhalt getan wird.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 24, 22, 'Da sagte Arawna zu David: »Mein Herr, der König, nehme sie hin und opfere, was ihm beliebt! Die Rinder hier stehen als Brandopfer und die Dreschschlitten nebst den Geschirren der Rinder als Brennholz zu deiner Verfügung:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 24, 23, 'das alles, o König, macht Arawna dem Könige zum Geschenk.« Dann fuhr er fort: »Der HERR, dein Gott, wolle dir gnädig sein!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 24, 24, 'Aber der König erwiderte dem Arawna: »Nein! Käuflich will ich es von dir erwerben für den vollen Preis; denn ich mag dem HERRN, meinem Gott, keine Brandopfer darbringen, die mir geschenkt sind.« So kaufte denn David die Tenne und die Rinder für den Preis von fünfzig Schekeln Silber.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 24, 25, 'David erbaute alsdann dem HERRN dort einen Altar und brachte Brandopfer und Heilsopfer dar; hierauf wandte der HERR dem Lande seine Gnade wieder zu, und das Sterben unter den Israeliten erreichte sein Ende.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 1, 'Als nun der König David alt (und) hochbetagt geworden war, hüllte man ihn in Decken ein, aber er konnte trotzdem nicht warm werden.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 2, 'Da sagten seine Diener zu ihm: »Man muß sich für den König, unsern Herrn, nach einem jungfräulichen Mädchen umsehen, die ihn zu bedienen hat und als Pflegerin bei ihm ist; wenn die dann in seinen Armen ruht, wird der König, unser Herr, gewiß warm werden.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 3, 'Da suchte man denn im ganzen Bereiche Israels nach dem schönsten Mädchen; und man fand Abisag von Sunem und brachte sie zum König.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 4, 'Sie war ein Mädchen von außerordentlicher Schönheit und hatte nun den König zu bedienen und zu pflegen; aber der König hatte keinen ehelichen Umgang mit ihr.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 5, 'Adonia aber, der Sohn der Haggith, dachte voller Überhebung: »Ich bin’s, der König wird!« Daher schaffte er sich Wagen und Pferde an und fünfzig Mann, die als Leibdiener vor ihm herliefen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 6, 'Sein Vater hatte ihm darüber nie, solange er lebte, Vorstellungen gemacht, daß er zu ihm gesagt hätte: »Warum tust du so etwas?« Dazu war er ein Mann von großer Schönheit und war gleich nach Absalom geboren.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 7, 'So setzte er sich denn ins Einvernehmen mit Joab, dem Sohn der Zeruja, und mit dem Priester Abjathar, so daß diese auf der Seite Adonias standen,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 8, 'während der Priester Zadok und Benaja, der Sohn Jojadas, und der Prophet Nathan sowie Simei und Rei und die Helden Davids es nicht mit Adonia hielten.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 9, 'Als nun Adonia beim Schlangenstein, der neben der Walkerquelle liegt, Kleinvieh, Rinder und Mastkälber zu einem großen Opfermahl schlachtete, lud er alle seine Brüder, die Königssöhne (königlichen Prinzen), dazu ein, auch alle Männer von Juda, soweit sie im Dienste des Königs standen;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 10, 'aber den Propheten Nathan und Benaja sowie die Helden und seinen Bruder Salomo ließ er uneingeladen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 11, 'Da sagte Nathan zu Bathseba, der Mutter Salomos: »Hast du nicht gehört, daß Adonia, der Sohn der Haggith, sich zum König gemacht hat, ohne daß David, unser Herr, etwas davon weiß?');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 12, 'Nun denn, komm, ich will dir einen Rat geben, wie du dir und deinem Sohne Salomo das Leben retten kannst!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 13, 'Gehe sofort zum König David hinein und sage zu ihm: ›Du selbst hast ja doch, mein Herr und König, deiner Magd eidlich versprochen, daß mein Sohn Salomo König nach dir werden und er der Erbe deines Thrones sein solle. Wie kommt es denn, daß jetzt Adonia König geworden ist?‹');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 14, 'Während du dann dort noch mit dem Könige redest, werde ich selbst nach dir hineinkommen und deine Aussagen bestätigen.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 15, 'So ging denn Bathseba zum König in das Schlafgemach hinein; der König aber war schon sehr alt, und Abisag von Sunem war seine Pflegerin.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 16, 'Als Bathseba sich nun vor dem Könige verneigt und niedergeworfen hatte, fragte der König sie: »Was wünschest du?«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 17, 'Sie antwortete ihm: »Mein Herr, du selbst hast deiner Magd bei dem HERRN, deinem Gott, zugeschworen, daß mein Sohn Salomo König nach dir werden und er der Erbe deines Thrones sein solle.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 18, 'Aber nun hat sich ja doch Adonia zum König gemacht, ohne daß du, mein Herr und König, etwas davon weißt.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 19, 'Er hat nämlich Rinder, Mastkälber und Kleinvieh in Menge (zu einem großen Opfermahl) schlachten lassen und alle königlichen Prinzen, auch den Priester Abjathar, sowie den obersten Heerführer Joab dazu eingeladen; aber deinen Knecht Salomo hat er uneingeladen gelassen!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 20, 'Nun aber, mein Herr und König, sind die Augen aller Israeliten auf dich gerichtet, daß du ihnen kundgebest, wer auf dem Throne meines Herrn, des Königs, als sein Nachfolger sitzen soll.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 21, 'Sonst wird es dahin kommen, sobald mein Herr und König sich zu seinen Vätern (schlafen) gelegt hat, daß ich und mein Sohn Salomo als Schuldige dastehen.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 22, 'Während sie noch mit dem Könige redete, erschien der Prophet Nathan;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 23, 'man meldete also dem Könige: »Der Prophet Nathan ist da!« Und er trat vor den König, und als er sich vor ihm mit dem Angesicht zur Erde verneigt und sich niedergeworfen hatte,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 24, 'sagte Nathan: »Mein Herr und König! Du hast wohl selbst angeordnet, daß Adonia König nach dir sein und auf deinem Throne sitzen soll?');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 25, 'Denn er ist heute hinabgegangen und hat Rinder, Mastkälber und Kleinvieh in Menge schlachten lassen und hat alle königlichen Prinzen, außerdem die obersten Heerführer und den Priester Abjathar eingeladen; und nun essen und trinken sie vor ihm und rufen: ›Es lebe der König Adonia!‹');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 26, 'Aber mich, deinen Knecht, und den Priester Zadok sowie Benaja, den Sohn Jojadas, und deinen Knecht Salomo hat er nicht dazu eingeladen!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 27, 'Wenn dies alles mit Wissen und Willen meines Herrn, des Königs, geschehen ist, so hättest du also deine Diener nicht wissen lassen, wer auf dem Throne meines Herrn, des Königs, als sein Nachfolger sitzen soll?«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 28, 'Da antwortete der König David: »Ruft mir Bathseba (wieder)!« Als sie nun erschienen und vor den König getreten war,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 29, 'schwur der König mit den Worten: »So wahr der HERR lebt, der mich aus aller Not errettet hat!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 30, 'Wie ich dir beim HERRN, dem Gott Israels, geschworen und gelobt habe, daß nämlich dein Sohn Salomo König nach mir sein und als mein Nachfolger auf meinem Throne sitzen soll, so will ich es am heutigen Tage wahr machen!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 31, 'Da verneigte sich Bathseba mit dem Angesicht bis zum Boden, warf sich vor dem Könige nieder und rief aus: »Möge mein Herr, der König David, ewiglich leben!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 32, 'Hierauf befahl der König David: »Ruft mir den Priester Zadok, den Propheten Nathan und Benaja, den Sohn Jojadas!« Als sie vor dem Könige erschienen waren, befahl dieser ihnen:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 33, '»Nehmt die Knechte eures Herrn mit euch und laßt meinen Sohn Salomo mein eigenes Maultier besteigen und geleitet ihn hinab an den Gihon.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 34, 'Dort sollen der Priester Zadok und der Prophet Nathan ihn zum König über Israel salben; ihr aber laßt in die Posaune stoßen und ruft: ›Es lebe der König Salomo!‹');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 35, 'Alsdann zieht hinter ihm her wieder (zur Burg) herauf; und wenn er dort angekommen ist, soll er sich auf meinen Thron setzen, und dann soll er König sein an meiner Statt; denn ihn habe ich zum Fürsten über Israel und Juda bestellt!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 36, 'Da antwortete Benaja, der Sohn Jojadas, dem König mit den Worten: »So sei es! Möge der HERR, der Gott meines Herrn, des Königs, sein Amen dazu sprechen!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 37, 'Wie Gott der HERR mit meinem Herrn, dem König, gewesen ist, so möge er auch mit Salomo sein und möge seinen Thron noch mehr erhöhen als den Thron meines Herrn, des Königs David!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 38, 'So gingen denn der Priester Zadok, der Prophet Nathan und Benaja, der Sohn Jojadas, samt der Leibwache der Krethi und Plethi hinab, ließen Salomo das Maultier des Königs David besteigen und geleiteten ihn an den Gihon.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 39, 'Der Priester Zadok hatte aber das mit Öl gefüllte Horn aus dem (heiligen) Zelt mitgenommen und salbte nun Salomo; dann ließen sie in die Posaune stoßen, und alles Volk rief: »Es lebe der König Salomo!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 40, 'Hierauf geleitete ihn alles Volk (nach der Burg) hinauf, indem die Leute alle dabei auf Flöten bliesen und so laut und freudig jubelten, daß die Erde vor ihrem Geschrei schier bersten wollte.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 41, 'Das hörten Adonia und alle seine Gäste, als sie eben mit dem Mahl zu Ende waren. Als nun Joab den Posaunenschall vernahm, fragte er: »Was bedeutet das Geschrei und der Lärm in der Stadt?«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 42, 'Während er noch redete, kam Jonathan, der Sohn des Priesters Abjathar; und Adonia rief ihm zu: »Komm herein, du bist ein zuverlässiger Mann und bringst gewiß gute Botschaft!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 43, 'Aber Jonathan antwortete dem Adonia: »Im Gegenteil! Unser Herr, der König David, hat Salomo zum König gemacht!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 44, 'Der König hat nämlich den Priester Zadok, den Propheten Nathan und Benaja, den Sohn Jojadas, samt der Leibwache der Krethi und Plethi mit ihm entsandt; diese haben ihn das Maultier des Königs besteigen lassen,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 45, 'und der Priester Zadok und der Prophet Nathan haben ihn am Gihon zum König gesalbt und sind von dort jubelnd (auf die Burg) hinaufgezogen, und die ganze Stadt ist dadurch in Aufregung geraten; daher rührt das Geschrei, das ihr gehört habt.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 46, 'Salomo hat sich dann auch auf den Königsthron gesetzt;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 47, 'außerdem sind auch die Diener des Königs bereits hineingegangen, um unserm Herrn, dem König David, Glück zu wünschen mit den Worten: ›Dein Gott möge den Namen Salomos noch ruhmvoller machen als den deinigen und seinen Thron noch mehr erhöhen als den deinigen!‹ Dabei hat der König sich auf seinem Lager verneigt');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 48, 'und auch noch die Worte hinzugefügt: ›Gepriesen sei der HERR, der Gott Israels, der es heute so gefügt hat, daß ich einen Nachfolger (aus meinem Geschlecht) auf meinem Throne mit eigenen Augen sitzen sehe!‹«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 49, 'Da erschraken alle, die von Adonia eingeladen worden waren; sie brachen auf und gingen ein jeder seines Weges.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 50, 'Adonia selbst aber, der sich vor Salomo fürchtete, eilte sofort hin und umfaßte die Hörner des Altars.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 51, 'Als man dies dem Salomo meldete mit den Worten: »Adonia hat jetzt aus Furcht vor dem König Salomo die Hörner des Altars umfaßt und erklärt, der König Salomo möge ihm erst schwören, daß er seinen Knecht nicht hinrichten lassen wolle«,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 52, 'sagte Salomo: »Wenn er sich als ein ehrenhafter Mann erweist, so soll ihm kein Haar gekrümmt werden; läßt er sich aber Böses zuschulden kommen, dann ist er ein Kind des Todes!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 53, 'Darauf ließ ihn der König Salomo vom Altar wegholen; und als er kam und sich vor dem König Salomo niederwarf, sagte dieser zu ihm: »Gehe in dein Haus!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 1, 'Als es nun mit Davids Leben zu Ende ging, gab er seinem Sohne Salomo folgende Weisungen:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 2, '»Ich gehe jetzt den Weg alles Irdischen; so sei denn stark und zeige dich als Mann!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 3, 'Beobachte alles, was der HERR, dein Gott, von dir fordert, indem du auf seinen Wegen wandelst, seine Satzungen und Gebote, seine Rechte und Verordnungen so hältst, wie im Gesetz Moses geschrieben steht; dann wirst du Glück haben in allem, was du unternimmst, und überall, wohin du dich wendest;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 4, 'dann wird auch der HERR seine Verheißung in Erfüllung gehen lassen, die er mir gegeben hat mit den Worten: ›Wenn deine Söhne auf ihren Weg achthaben, so daß sie in Treue vor mir wandeln mit ihrem ganzen Herzen und mit ihrer ganzen Seele, so soll es dir nie an einem Manne auf dem Thron Israels fehlen.‹');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 5, 'Nun weißt du selbst ja auch, wie Joab, der Sohn der Zeruja, gegen mich gehandelt hat, wie er sich nämlich gegen die beiden obersten Heerführer Israels, gegen Abner, den Sohn Ners, und gegen Amasa, den Sohn Jethers, benommen hat, indem er sie ermordete und für das im Kriege vergossene Blut mitten im Frieden Rache nahm und unschuldiges Blut an den Gürtel um seine Hüften und an die Schuhe an seinen Füßen gebracht hat.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 6, 'So handle nun nach deiner Weisheit und laß sein graues Haar nicht in Frieden in das Totenreich hinabfahren!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 7, 'Dagegen sollst du den Söhnen des Gileaditers Barsillai Liebe erweisen: sie sollen zu denen gehören, die an deinem Tisch speisen; das haben sie durch ihr Entgegenkommen verdient, als ich vor deinem Bruder Absalom fliehen mußte.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 8, 'Ferner befindet sich in deiner Nähe der Benjaminit Simei, der Sohn Geras, aus Bahurim; der hat die frechsten Flüche gegen mich ausgestoßen an dem Tage, als ich mich nach Mahanaim begab. Aber er ist mir dann an den Jordan entgegengekommen, und ich habe ihm mit einem Schwur beim HERRN zugesagt: ›Ich will dich nicht hinrichten lassen.‹');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 9, 'Nunmehr aber laß du ihn nicht ungestraft! Du bist ja ein kluger Mann und wirst schon wissen, wie du mit ihm zu verfahren hast, um sein graues Haar blutbefleckt in das Totenreich hinabfahren zu lassen.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 10, 'Hierauf legte sich David zu seinen Vätern und wurde (zu Jerusalem) in der Davidsstadt begraben.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 11, 'Die Zeit aber, die David über Israel regiert hat, betrug vierzig Jahre: sieben Jahre hat er in Hebron und dreiunddreißig Jahre in Jerusalem regiert.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 12, 'Nunmehr saß Salomo auf dem Thron seines Vaters David, und sein Königtum erstarkte zu außerordentlicher Macht.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 13, 'Adonia aber, der Sohn der Haggith, begab sich zu Bathseba, der Mutter Salomos. Als diese ihn fragte: »Bedeutet dein Kommen Gutes?«, antwortete er: »Ja, etwas Gutes.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 14, 'Dann fuhr er fort: »Ich habe eine Bitte an dich.« Sie erwiderte: »Rede!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 15, 'Da sagte er: »Du weißt selbst, daß das Königtum (eigentlich) mir zukam und daß ganz Israel in mir den zukünftigen König sah; aber die Sache kam dann anders, und das Königtum ist meinem Bruder zugefallen, weil es vom HERRN für ihn bestimmt war.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 16, 'Nun aber habe ich eine einzige Bitte an dich; schlage sie mir nicht ab!« Sie entgegnete ihm: »Rede!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 17, 'Da fuhr er fort: »Bitte doch den König Salomo – denn dich wird er sicherlich nicht abweisen –, er möge mir Abisag von Sunem zur Frau geben.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 18, 'Bathseba erwiderte darauf: »Gut! Ich will deinethalben mit dem König reden.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 19, 'Als Bathseba sich nun zum König Salomo begab, um wegen Adonias mit ihm zu reden, erhob sich der König, ging ihr entgegen, verneigte sich vor ihr und setzte sich dann wieder auf seinen Stuhl; dann ließ er auch für die Königin-Mutter einen Stuhl hinstellen, und sie setzte sich zu seiner Rechten.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 20, 'Darauf sagte sie: »Ich habe eine kleine Bitte an dich: schlage sie mir nicht ab!« Der König erwiderte ihr: »Bitte nur, liebe Mutter! Denn ich werde dich nicht abweisen.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 21, 'Da sagte sie: »Möchte doch Abisag von Sunem deinem Bruder Adonia zur Frau gegeben werden!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 22, 'Da gab der König Salomo seiner Mutter folgende Antwort: »Warum bittest du für Adonia nur um Abisag von Sunem? Bitte für ihn doch lieber gleich um das Königtum! Er ist ja mein älterer Bruder, und auf seiner Seite stehen der Priester Abjathar und Joab, der Sohn der Zeruja!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 23, 'Hierauf schwur der König Salomo beim HERRN: »Gott strafe mich jetzt und künftig, wenn diese Bitte den Adonia nicht das Leben kostet!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 24, 'So wahr der HERR lebt, der mich (als König) eingesetzt und mich den Thron meines Vaters David hat besteigen lassen und der mir nach seiner Verheißung ein Haus gebaut hat: heute noch muß Adonia sterben!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 25, 'Hierauf beauftragte der König Salomo Benaja, den Sohn Jojadas; der stieß ihn nieder; so starb er.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 26, 'Dem Priester Abjathar aber befahl der König: »Begib dich nach Anathoth auf dein Landgut! Denn du hast eigentlich den Tod verdient; aber ich will dich heute nicht töten lassen, weil du die Lade Gottes des HERRN vor meinem Vater David getragen und weil du an allen Leiden, die meinen Vater betroffen haben, teilgenommen hast.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 27, 'So verstieß also Salomo den Abjathar, so daß er nicht mehr Priester des HERRN war; und damit ging die Drohung in Erfüllung, die der HERR einst gegen das Haus Elis in Silo ausgesprochen hatte.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 28, 'Als nun die Kunde von diesem allem zu Joab drang – Joab hatte nämlich zu Adonia gehalten, während er sich an Absalom nicht angeschlossen hatte –, da floh Joab in das Zelt des HERRN und umfaßte die Hörner des Altars.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 29, 'Als nun dem König Salomo gemeldet wurde, daß Joab in das Zelt des HERRN geflohen sei und dort neben dem Altar stehe, da sandte Salomo Benaja, den Sohn Jojadas, hin mit dem Befehl: »Gehe hin, stoße ihn nieder!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 30, 'Benaja begab sich also in das Zelt des HERRN und sagte zu Joab: »So lautet des Königs Befehl: ›Komm heraus!‹« Aber er antwortete: »Nein, hier will ich sterben!« Da meldete Benaja dies dem König mit den Worten: »So hat Joab gesprochen, und so hat er mir geantwortet.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 31, 'Da befahl ihm der König: »Tu ihm, wie er gesagt hat: stoße ihn nieder und begrabe ihn und schaffe so das Blut, das Joab ohne Grund vergossen hat, von mir und von meines Vaters Hause weg!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 32, 'Der HERR lasse ihm seine Blutschuld auf sein eigenes Haupt zurückfallen, weil er zwei Männer, die ehrenhafter und besser waren als er, niedergestoßen und mit dem Schwert ermordet hat, ohne daß mein Vater David etwas davon wußte, nämlich Abner, den Sohn Ners, den Heerführer der Israeliten, und Amasa, den Sohn Jethers, den Heerführer der Judäer:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 33, 'deren Blut möge auf das Haupt Joabs und auf das Haupt seiner Nachkommen für alle Zukunft zurückfallen! David aber und seinen Nachkommen, seinem Hause und seinem Thron möge für alle Zeiten Heil vom HERRN zuteil werden!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 34, 'Da ging Benaja, der Sohn Jojadas, hinauf und versetzte ihm den Todesstoß; er wurde alsdann bei seinem Hause in der Steppe (Juda) begraben.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 35, 'Der König machte hierauf Benaja, den Sohn Jojadas, an Joabs Statt zum obersten Heerführer und übertrug dem Priester Zadok die Stelle Abjathars.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 36, 'Weiter ließ der König den Simei rufen und sagte zu ihm: »Baue dir ein Haus in Jerusalem und bleibe dort wohnen! Du darfst von dort nicht weggehen, wohin es auch sei!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 37, 'Sobald du dich nämlich von da entfernst und auch nur über den Bach Kidron gehst, so kannst du dich darauf verlassen, daß du sterben mußt: dein Blut kommt dann über dein eigenes Haupt!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 38, 'Simei erwiderte dem König: »Gut so! Wie mein Herr, der König, befohlen hat, so wird dein Knecht tun.« So wohnte denn Simei lange Zeit in Jerusalem.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 39, 'Aber nach Ablauf von drei Jahren begab es sich, daß dem Simei zwei Sklaven zu Achis, dem König von Gath, dem Sohne Maachas, entliefen. Als man nun dem Simei mitteilte, daß seine Sklaven sich in Gath befänden,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 40, 'machte Simei sich auf, ließ seinen Esel satteln und begab sich nach Gath zu Achis, um seine Sklaven ausfindig zu machen; er zog also hin und holte seine Sklaven aus Gath zurück.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 41, 'Sobald nun Salomo erfuhr, daß Simei sich von Jerusalem nach Gath begeben habe und von dort wieder zurückgekommen sei,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 42, 'ließ der König den Simei vor sich kommen und sagte zu ihm: »Habe ich dich nicht beim HERRN schwören lassen und dir die bestimmte Versicherung gegeben: ›Sobald du dich von hier entfernst, wohin es auch sei, so kannst du dich darauf verlassen, daß du sterben mußt?‹ Damals erklärtest du mir: ›Gut so! Ich habe es gehört.‹');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 43, 'Warum hast du dich nun an den beim HERRN geschworenen Eid und an den von mir erteilten Befehl nicht gehalten?«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 44, 'Der König fügte dann noch hinzu: »Du weißt selbst, wie schwer du dich gegen meinen Vater David vergangen hast – du erinnerst dich dessen noch recht gut –; so läßt denn der HERR jetzt deine Bosheit auf dein Haupt zurückfallen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 45, 'Der König Salomo dagegen wird gesegnet sein und der Thron Davids immerdar feststehen vor dem HERRN!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 46, 'Darauf erteilte der König dem Benaja, dem Sohn Jojadas, Befehl; der ging hinaus und stieß ihn nieder: so starb er. Als nun das Königtum sich in Salomos Hand befestigt hatte,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 3, 1, 'verschwägerte sich Salomo mit dem Pharao, dem König von Ägypten; er heiratete nämlich eine Tochter des Pharaos und führte sie in die Davidsstadt, bis er mit dem Bau seines Palastes sowie mit dem Bau des Tempels des HERRN und der Ringmauer um Jerusalem fertig war.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 3, 2, 'Das Volk mußte damals leider noch auf den Höhen opfern, weil bis zu dieser Zeit dem Namen des HERRN noch kein eigenes Haus erbaut worden war.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 3, 3, 'Salomo hatte zwar den HERRN lieb, so daß er nach den Weisungen seines Vaters David wandelte, doch opferte und räucherte auch er noch auf den Höhen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 3, 4, 'So begab sich denn der König nach Gibeon, um dort zu opfern; denn dort befand sich das vornehmste Höhenheiligtum; tausend Brandopfer(-tiere) brachte Salomo auf dem dortigen Altar dar.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 3, 5, 'Da erschien der HERR dem Salomo zu Gibeon nachts im Traum, und Gott sagte: »Bitte, was ich dir geben soll!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 3, 6, 'Salomo antwortete: »Du hast deinem Knecht, meinem Vater David, große Huld erwiesen, weil er vor dir in Wahrheit und Gerechtigkeit und mit aufrichtigem Herzen gegen dich gewandelt ist, und du hast ihm auch diese große Huld bewahrt und ihm einen Sohn gegeben, der auf seinem Throne sitzt, wie dieser Tag beweist.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 3, 7, 'Nun denn, HERR, mein Gott, weil du selbst deinen Knecht an meines Vaters David Statt zum König gemacht hast, ich aber noch ein junger Mann bin, der weder aus noch ein weiß,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 3, 8, 'und weil dein Knecht in der Mitte deines Volkes steht, das du erwählt hast, eines so großen Volkes, daß man es vor Menge nicht zählen noch berechnen kann:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 3, 9, 'so wollest du deinem Knecht ein verständiges Herz geben, damit er dein Volk zu regieren versteht und zwischen gut und böse zu unterscheiden weiß; denn wer wäre sonst imstande, dieses dein so zahlreiches Volk zu regieren?«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 3, 10, 'Diese Rede gefiel dem HERRN wohl, daß Salomo nämlich eine solche Bitte ausgesprochen hatte;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 3, 11, 'darum antwortete Gott ihm: »Weil du diese Bitte ausgesprochen und dir nicht ein langes Leben oder Reichtum gewünscht oder auch um den Tod deiner Feinde gebeten, sondern dir Einsicht erbeten hast, um Verständnis für das Recht zu besitzen,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 3, 12, 'so will ich deine Bitte erfüllen: Siehe, ich will dir ein weises und einsichtsvolles Herz geben, so daß deinesgleichen nicht vor dir gewesen ist und deinesgleichen nach dir nicht erstehen wird.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 3, 13, 'Aber auch das will ich dir verleihen, was du dir nicht erbeten hast, sowohl Reichtum als auch Ehre, so daß kein anderer König dir gleich sein soll, solange du lebst.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 3, 14, 'Und wenn du auf meinen Wegen wandelst, indem du meine Satzungen und Gebote beobachtest, wie dein Vater David gewandelt ist, so will ich dir auch ein langes Leben verleihen.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 3, 15, 'Als nun Salomo erwachte, erkannte er, daß es ein bedeutungsvoller Traum gewesen war. Als er dann nach Jerusalem zurückgekehrt war, trat er vor die Bundeslade des HERRN, brachte Brandopfer dar und richtete Heilsopfer her und veranstaltete ein Festmahl für alle seine Diener.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 3, 16, 'Damals kamen zwei Dirnen zum König und traten vor ihn;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 3, 17, 'und das eine Weib sagte: »Mit Vergunst, Herr! Ich und dieses Weib wohnen in demselben Hause, und ich gebar ein Kind in ihrer Gegenwart im Hause.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 3, 18, 'Da geschah es zwei Tage nach meiner Niederkunft, daß auch dieses Weib ein Kind gebar, und wir beide waren allein, kein Fremder war sonst bei uns im Hause, nur wir beide befanden uns im Hause.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 3, 19, 'Da starb das Kind dieses Weibes in der Nacht, weil sie es im Schlaf erdrückt hatte.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 3, 20, 'Sie aber stand mitten in der Nacht auf, nahm mein Kind von meiner Seite weg, während deine Magd schlief, und legte es an ihre Brust, dagegen ihr totes Kind legte sie mir in den Arm.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 3, 21, 'Als ich nun gegen Morgen aufstand, um meinem Kinde die Brust zu geben, sah ich, daß es tot war; als ich es aber bei Tagesanbruch genau betrachtete, sah ich, daß es gar nicht mein Kind war, das ich geboren hatte.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 3, 22, 'Da sagte das andere Weib: »Nein, mein Kind ist das lebende, und dein Kind ist das tote!«, jene aber versicherte: »Nein, dein Kind ist das tote und mein Kind das lebende!« So stritten sie vor dem Könige.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 3, 23, 'Da sagte der König: »Die eine behauptet: ›Dieses, das lebende Kind, gehört mir, und dein Kind ist das tote‹; die andere behauptet: ›Nein, dein Kind ist das tote und mein Kind das lebende!‹«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 3, 24, 'Dann befahl der König: »Holt mir ein Schwert!« Als man nun das Schwert vor den König gebracht hatte,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 3, 25, 'befahl er: »Teilt das lebende Kind in zwei Teile und gebt dieser Frau die eine Hälfte und jener die andere Hälfte!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 3, 26, 'Da rief die Frau, der das lebende Kind gehörte – denn die mütterliche Liebe zu ihrem Kinde kam bei ihr zum Durchbruch –, dem König die Worte zu: »Mit Vergunst, Herr! Gebt ihr das lebende Kind und tötet es ja nicht!« Die andere aber rief: »Es soll weder mir noch dir gehören: zerteilt es!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 3, 27, 'Da entschied der König: »Die da, welche gerufen hat: ›Gebt ihr das lebende Kind und tötet es ja nicht!‹, die ist seine Mutter.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 3, 28, 'Als nun ganz Israel den Richterspruch vernahm, den der König gefällt hatte, fühlte man Ehrfurcht vor dem König, denn man erkannte, daß eine göttliche Weisheit in ihm wohnte, um Recht zu sprechen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 4, 1, 'So herrschte also Salomo als König über ganz Israel;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 4, 2, 'und dies waren seine Fürsten: Asarja, der Sohn Zadoks, war (Hoher-) Priester;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 4, 3, 'Elihoreph und Ahija, die Söhne Sisas, waren Staatsschreiber; Josaphat, der Sohn Ahiluds, war Kanzler;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 4, 4, 'Benaja, der Sohn Jojadas, war oberster Heerführer; [Zadok und Abjathar waren Priester;]');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 4, 5, 'Asarja, der Sohn Nathans, war über die Vögte gesetzt; Sabud, der Sohn Nathans, war der priesterliche Freund des Königs;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 4, 6, 'Ahisar war Palastoberster, und Adoniram, der Sohn Addas, hatte die Oberaufsicht über die Fronarbeiten.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 4, 7, 'Salomo hatte zwölf Vögte, die über ganz Israel gesetzt waren und den König und seinen Hof zu versorgen hatten, und zwar oblag jedem von ihnen die Versorgung einen Monat lang im Jahre.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 4, 8, 'Folgendes sind ihre Namen: Der Sohn Hurs, im Gebirge Ephraim;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 4, 9, 'der Sohn Dekers in Makaz; (ihm unterstand) Saalbim, Beth-Semes und Elon bis Beth-Hanan;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 4, 10, 'der Sohn Heseds in Arubboth; ihm war Socho und die ganze Landschaft Hepher überwiesen;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 4, 11, 'der Sohn Abinadabs, der das ganze Hügelland von Dor unter sich hatte; er war mit Salomos Tochter Taphath verheiratet worden;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 4, 12, 'Baana, der Sohn Ahiluds, in Thaanach, Megiddo und ganz Beth-Sean, das neben Zarthan liegt unterhalb Jesreels, von Beth-Sean bis nach Abel-Mehola, bis über Jokmeam hinaus;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 4, 13, 'der Sohn Gebers zu Ramoth in Gilead, dem die Zeltdörfer Jairs, des Sohnes Manasses, die in Gilead liegen, überwiesen waren; dazu gehörte auch der Landstrich Argob in Basan, sechzig große Städte mit Mauern und ehernen Riegeln;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 4, 14, 'Ahinadab, der Sohn Iddos, in Mahanaim;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 4, 15, 'Ahimaaz in Naphthali; auch er war mit einer Tochter Salomos, mit Basmath, verheiratet;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 4, 16, 'Baana, der Sohn Husais, in Asser und Bealoth;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 4, 17, 'Josaphat, der Sohn Pharuahs, in Issaschar;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 4, 18, 'Simei, der Sohn Elas, in Benjamin;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 4, 19, 'Geber, der Sohn Uris, im Lande Gilead, dem Lande Sihons, des Königs der Amoriter, und Ogs, des Königs von Basan; außerdem war noch ein Vogt über alle Vögte im Lande eingesetzt. –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 4, 20, '(Die Bewohner von) Juda und Israel waren so zahlreich wie der Sand am Meer an Menge; sie aßen und tranken und waren guter Dinge.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 5, 1, 'Salomo war aber Beherrscher aller Reiche vom Euphratstrom bis zum Philisterland und bis an die Grenze Ägyptens; sie zahlten Tribut und waren Salomo untertan, solange er lebte.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 5, 2, 'Der tägliche Speisebedarf Salomos betrug dreißig Kor Feinmehl und sechzig Kor gewöhnliches Mehl,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 5, 3, 'zehn gemästete Rinder, zwanzig Rinder von der Weide und hundert Stück Kleinvieh, ungerechnet die Hirsche, Gazellen, Damhirsche und das gemästete Geflügel.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 5, 4, 'Denn er herrschte über alle Länder diesseits des Euphrats von Thiphsah bis nach Gaza, über alle Könige diesseits des Euphrats, und lebte in Frieden mit allen Völkern ringsum,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 5, 5, 'so daß Juda und Israel von Dan bis Beerseba in Sicherheit wohnten, ein jeder unter seinem Weinstock und unter seinem Feigenbaum, solange Salomo lebte.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 5, 6, 'Salomo besaß auch viertausend Paar Pferde für seine Kriegswagen und zwölftausend Reitpferde,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 5, 7, 'und jene Vögte versorgten den König Salomo und alle, deren Unterhalt dem König Salomo oblag, ein jeder während seines Monats, und ließen es an nichts fehlen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 5, 8, 'Auch die Gerste und das Stroh für die Wagen- und die Reitpferde hatten sie an den Ort zu liefern, wo er sich gerade aufhielt, ein jeder, wie es ihn der Reihe nach traf.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 5, 9, 'Gott verlieh aber dem Salomo Weisheit und Einsicht in sehr hohem Maße und einen Verstand so weitreichend wie der Sand, der am Ufer des Meeres liegt,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 5, 10, 'so daß die Weisheit Salomos größer war als die Weisheit aller Bewohner des Morgenlandes und als alle Weisheit Ägyptens;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 5, 11, 'ja, er war weiser als alle Menschen, auch weiser als der Esrahiter Ethan und als Heman, Kalkol und Darda, die Söhne Mahols, und sein Ruhm war unter allen Völkern ringsum verbreitet.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 5, 12, 'Er verfaßte dreitausend Sprüche, und die Zahl seiner Lieder betrug tausend und fünf.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 5, 13, 'Er besang die Bäume von der Zeder auf dem Libanon an bis zum Ysop, der (aus den Fugen) an der Mauer hervorwächst; er besang auch die vierfüßigen Tiere und die Vögel, das Gewürm und die Fische;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 5, 14, 'und aus allen Völkern kamen die Leute, um die Weisheit Salomos zu hören, von allen Königen der Erde her Leute, die von seiner Weisheit gehört hatten.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 5, 15, 'Hiram aber, der König von Tyrus, schickte seine Knechte an Salomo; denn er hatte gehört, daß man ihn als Nachfolger seines Vaters zum König gesalbt hatte; Hiram war nämlich zeitlebens mit David befreundet gewesen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 5, 16, 'Da ließ auch Salomo dem Hiram durch eine Gesandtschaft sagen:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 5, 17, '»Du weißt selbst, daß mein Vater David dem Namen des HERRN, seines Gottes, keinen Tempel hat erbauen können wegen der Kriege, in die seine Feinde ihn rings verwickelten, bis der HERR sie ihm unter seine Fußsohlen legte.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 5, 18, 'Da mir jetzt aber der HERR, mein Gott, auf allen Seiten Ruhe verschafft hat, so daß kein Widersacher und keine Schwierigkeit mehr vorhanden ist,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 5, 19, 'so beabsichtige ich nun, dem Namen des HERRN, meines Gottes, einen Tempel zu erbauen, wie der HERR dies meinem Vater David verheißen hat mit den Worten: ›Dein Sohn, den ich als deinen Nachfolger auf deinen Thron setzen werde, der soll meinem Namen das Haus bauen.‹');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 5, 20, 'So gib nun Befehl, daß man mir Zedern auf dem Libanon fälle; meine Leute sollen dabei mit den deinigen zusammenarbeiten, und den Lohn für deine Leute will ich dir geben, ganz wie du es bestimmst. Du weißt ja selbst, daß es keinen bei uns gibt, der Bauholz so zu hauen verstände wie die Sidonier.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 5, 21, 'Als Hiram diese Botschaft Salomos vernahm, freute er sich außerordentlich und rief aus: »Gepriesen sei heute der HERR, der dem David einen weisen Sohn zum Herrscher über dies große Volk gegeben hat!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 5, 22, 'Hierauf ließ Hiram dem Salomo durch eine Gesandtschaft sagen: »Ich habe deine Botschaft an mich vernommen. Ich werde alle deine Wünsche bezüglich des Zedern- und Zypressenholzes erfüllen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 5, 23, 'Meine Leute sollen die Hölzer vom Libanon ans Meer hinabschaffen; dann will ich Flöße daraus auf dem Meer herstellen lassen und sie bis an den Ort schaffen, den du mir angeben wirst; dort lasse ich sie wieder auseinandernehmen, und du läßt sie dann abholen. Dafür mußt du aber auch meine Wünsche erfüllen, indem du meinen Hofhalt mit Speisebedarf versorgst.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 5, 24, 'So lieferte also Hiram dem Salomo Zedern- und Zypressenholz, soviel er wünschte;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 5, 25, 'Salomo dagegen lieferte dem Hiram 20000 Kor Weizen für den Unterhalt seines Hofes und 20000 Bath feinstes Öl von zerstoßenen Oliven; so viel hatte Salomo dem Hiram Jahr für Jahr zu liefern.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 5, 26, 'Der HERR aber verlieh dem Salomo Weisheit, wie er ihm verheißen hatte; und es bestand ein freundschaftliches Verhältnis zwischen Salomo und Hiram, denn sie hatten einen Bund miteinander geschlossen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 5, 27, 'Hierauf hob der König Salomo aus ganz Israel Fronarbeiter aus, so daß die Fronenden sich auf dreißigtausend Mann beliefen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 5, 28, 'Er schickte sie abwechselnd auf den Libanon, jeden Monat zehntausend, so daß sie einen Monat auf dem Libanon waren und zwei Monate jeder zu Hause blieb; Adoniram hatte die Oberaufsicht über die Fronarbeiter. –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 5, 29, 'Außerdem hatte Salomo 70000 Lastträger und 80000 Steinhauer im Gebirge (Juda),');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 5, 30, 'ungerechnet die 3300 von Salomo bestellten Werkführer, welche die Arbeiten zu leiten und die Leute, die mit der Arbeit beschäftigt waren, zu beaufsichtigen hatten.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 5, 31, 'Der König gab auch Befehl, große und schwere Steine zu brechen, um die Grundmauern des Tempels mit Quadersteinen zu legen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 5, 32, 'Die Bauleute Salomos und die Bauleute Hirams behieben sie dann gemeinsam und richteten die Hölzer und die Steine zum Bau des Tempels her.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 1, 'Im vierhundertachtzigsten Jahr nach dem Auszug der Israeliten aus Ägypten, im vierten Jahre der Regierung Salomos über Israel, im Monat Siw – das ist der zweite Monat –, da begann Salomo den Bau des Tempels für den HERRN.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 2, 'Der Tempel, den der König Salomo für den HERRN baute, war sechzig Ellen lang, zwanzig Ellen breit und dreißig Ellen hoch.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 3, 'Die Halle an der Vorderseite des Großraumes des Gebäudes war zwanzig Ellen breit, entsprechend der Breite des Gebäudes, und zehn Ellen tief in der Längsrichtung des Gebäudes.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 4, '(Salomo) ließ an dem Tempel Fenster mit unbeweglichem Gitterwerk anbringen');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 5, 'und führte an der Wand des Tempels ringsum, sowohl um den Großraum als auch um den Hinterraum, einen Anbau auf und richtete so ringsum Seitenräume ein.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 6, 'Das unterste Stockwerk (dieses Anbaus) war fünf Ellen breit, das mittlere sechs, das dritte sieben Ellen breit; denn Salomo hatte außen am Tempel ringsum Absätze anbringen lassen, damit die Querbalken nicht in die Mauern des Hauptgebäudes eingriffen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 7, 'Beim Bau des Tempels verwandte man aber nur Steine, die beim Brechen (im Steinbruch) schon fertig behauen waren, so daß man während der Errichtung des Gebäudes von Hämmern und Meißeln, überhaupt von eisernen Werkzeugen im Tempel nichts hörte.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 8, 'Der Eingang zum untersten Stockwerk des Anbaus befand sich an der Südseite des Gebäudes; und auf einer Wendeltreppe stieg man in das mittlere und vom mittleren in das dritte Stockwerk hinauf.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 9, 'Als er so den Bau des Tempels vollendet hatte, deckte er das Gebäude mit Balken und Bohlenreihen von Zedernholz.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 10, 'Den Anbau aber führte er um den ganzen Tempel her auf, jedes Stockwerk fünf Ellen hoch, und verband ihn mit dem Hauptgebäude durch Zedernbalken.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 11, 'Und es erging das Wort des HERRN an Salomo folgendermaßen:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 12, '»So steht es mit diesem Hause, das du eben erbaust: Wenn du nach meinen Satzungen wandelst und meinen Weisungen nachkommst, alle meine Gebote hältst, so daß du nach ihnen wandelst, so will ich die Verheißung an dir wahrmachen, die ich deinem Vater David gegeben habe:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 13, 'ich werde alsdann inmitten der Israeliten wohnen und mein Volk Israel nicht verlassen.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 14, 'Als nun Salomo mit dem Bau des Hauses fertig war,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 15, 'bekleidete er die Wände des Tempels im Inneren des Hauses mit Brettern von Zedernholz: vom Fußboden des Gebäudes bis zu den Balken der Decke täfelte er die inneren Wände mit Holz und belegte den Fußboden des Tempels mit Bohlen von Zypressenholz.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 16, 'Ebenso bekleidete er die zwanzig Ellen an der Hinterseite des Tempels mit Zedernbrettern vom Fußboden bis an die Decke und baute sich so im Inneren des Tempels den Hinterraum als das Allerheiligste aus.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 17, 'Aber das vordere Tempelhaus, das heißt der Großraum vorn vor dem Allerheiligsten, maß vierzig Ellen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 18, 'So bestand denn das ganze Haus im Inneren aus Zedernholz, verziert mit Schnitzwerk in Form von wilden Gurken und Blumengewinden, alles von Zedernholz, so daß kein Stein zu sehen war.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 19, 'Den Hinterraum aber im Inneren des Gebäudes richtete er so ein, daß er die Bundeslade des HERRN dort unterbringen konnte.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 20, 'Der Hinterraum war nämlich zwanzig Ellen lang, zwanzig Ellen breit und zwanzig Ellen hoch, und er ließ ihn mit feinem Gold überziehen; auch den Zedernholz-Altar vor dem Hinterraum überzog er damit.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 21, 'Weiter überzog Salomo das Gebäude im Inneren mit feinem Gold und zog vor dem Hinterraum goldene Ketten her und überzog auch ihn mit Gold.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 22, 'Den ganzen Tempel überzog er also im Inneren mit Gold, das ganze Gebäude vollständig; auch den Altar, der vor dem Allerheiligsten stand, überzog er ganz mit Gold.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 23, 'Weiter ließ er im Allerheiligsten zwei Cherube aus Ölbaumholz anfertigen, je zehn Ellen hoch.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 24, 'Jeder Flügel der beiden Cherube maß fünf Ellen, so daß von der einen Flügelspitze bis zu der andern ein Abstand von zehn Ellen war.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 25, 'Und zehn Ellen maß auch der andere Cherub: beide Cherube hatten dasselbe Maß und dieselbe Gestalt;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 26, 'die Höhe des einen Cherubs betrug zehn Ellen und ebenso die des anderen Cherubs.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 27, 'Er stellte die beiden Cherube dann in der Mitte des innersten Tempelraumes auf, und sie hielten ihre Flügel so ausgebreitet, daß der Flügel des einen Cherubs diese Wand des Allerheiligsten und der Flügel des andern Cherubs die andere Wand berührte, während ihre inneren Flügel in der Richtung nach der Mitte des Raumes aneinander stießen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 28, 'Auch die Cherube überzog er mit Gold.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 29, 'Weiter ließ er an allen Wänden des Gebäudes ringsum Schnitzwerk von Cheruben, Palmen und Blumengewinden anbringen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 30, 'Auch den Fußboden des Tempels ließ er mit Gold überziehen sowohl im Hinterraum als auch im Vorderraum.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 31, 'Und für den Eingang in den Hinterraum ließ er eine Türeinfassung von Ölbaumholz anfertigen; die Oberschwelle und die Pfosten bildeten ein Fünfeck.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 32, 'Auf den beiden Türflügeln von Ölbaumholz aber ließ er Schnitzwerk von Cheruben, Palmen und Blumengewinden anbringen und sie dann mit Gold überziehen, und zwar die Cherube und die Palmen mit breitgeschlagenem Gold.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 33, 'Ebenso ließ er auch für den Eingang zum Großraum eine Türeinfassung von Ölbaumholz anfertigen, die ein Viereck bildete,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 34, 'dazu zwei Türflügel von Zypressenholz, von denen jeder aus zwei drehbaren Blättern bestand.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 35, 'Er ließ dann Schnitzwerk darauf anbringen, nämlich Cherube, Palmen und Blumengewinde, und ließ sie mit Goldblech überziehen, das dem Schnitzwerk genau angepaßt war.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 36, 'Darauf ließ er den inneren Vorhof mit einer Mauer umziehen, die aus drei Lagen von Quadersteinen und einer Lage von Zedernbalken bestand.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 37, 'Im vierten Jahre (der Regierung Salomos), im Monat Siw, war der Grund zum Tempel des HERRN gelegt worden,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 38, 'und im elften Jahre, im Monat Bul – das ist der achte Monat –, war der Tempel vollendet in allen seinen Teilen und mit allem, was dazu gehörte; sieben Jahre also hatte man daran gebaut.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 1, 'Aber an seinem eigenen Hause baute Salomo dreizehn Jahre lang, bis er seinen Palast ganz vollendet hatte.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 2, 'Er erbaute nämlich das Libanonwaldhaus, das hundert Ellen lang, fünfzig Ellen breit und dreißig Ellen hoch war, auf vier Reihen von Zedernsäulen, und auf den Säulen ruhten Balken von Zedernholz.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 3, 'Eine Decke von Zedernholz befand sich über den Tragbalken, die auf den Säulen lagen, zusammen fünfundvierzig, fünfzehn in jeder Reihe.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 4, 'Und Durchblicke waren da in drei Reihen, und die Lichtöffnungen lagen einander gegenüber, dreimal.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 5, 'Alle Türen und Lichtöffnungen waren viereckig, im Durchblick; und die Lichtöffnungen lagen einander gegenüber, dreimal.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 6, 'Sodann erbaute er den Säulensaal, der fünfzig Ellen lang und dreißig Ellen breit war; eine Halle mit Säulen und eine Treppe befand sich davor. –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 7, 'Weiter erbaute er den Thronsaal, in dem er Recht sprach, den Gerichtssaal; der war mit Zedernholz getäfelt vom Fußboden bis an die Decke. –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 8, 'Sodann sein eigener Palast, in dem er wohnte, im zweiten Vorhof einwärts vom Thronsaal, war ein Bau von derselben Art. Auch für die Tochter des Pharaos, die Salomo geheiratet hatte, baute er einen Palast gleich jener Halle.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 9, 'Alle diese Bauten waren aus Prachtsteinen aufgeführt, die nach Quadermaß behauen und innen wie außen mit der Säge zugeschnitten waren, und zwar vom Grund an bis zu den Gesimsen und von außen bis zu dem großen Vorhof.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 10, 'Die Fundamente aber bestanden aus gewaltig großen Steinen, aus Blöcken von zehn Ellen und solchen von acht Ellen Länge;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 11, 'und darüber lagen Prachtsteine, die nach Quadermaß zugehauen waren, und Zedernbalken.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 12, 'Der große Vorhof aber war rings mit einer Mauer umgeben, die aus drei Lagen Quadersteinen und einer Lage Zedernbalken bestand; ebenso war es auch bei dem inneren Vorhof am Tempel des HERRN und bei dem Vorhof am Säulensaal des Palastes.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 13, 'Darauf sandte der König Salomo hin und ließ Hiram von Tyrus holen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 14, 'Dieser war der Sohn einer Witwe aus dem Stamme Naphthali, sein Vater aber war ein tyrischer Kupferschmied. Er war ein hochbegabter, einsichtsvoller und kunstsinniger Mann, der sich auf die Herstellung von Erzarbeiten jeder Art verstand. Dieser Mann kam also zum König Salomo und führte alle Erzarbeiten für ihn aus.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 15, 'So stellte er die beiden ehernen Säulen her: achtzehn Ellen war die eine Säule hoch, ein Faden von zwölf Ellen umspannte sie, und ihre Dicke betrug vier Finger; inwendig war sie hohl; und ebenso machte er die zweite Säule.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 16, 'Auch fertigte er zwei aus Erz gegossene Knäufe an, um sie oben auf die Säulen zu setzen; jedes dieser beiden Kapitelle hatte fünf Ellen Höhe.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 17, 'Zur Bekleidung der Kapitelle, die sich oben auf den Säulen befanden, dienten Flechtwerke von kettenartig gearbeiteten Schnüren.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 18, 'b und ebenso verfertigte er sie für das andere Kapitell. b und ebenso verfertigte er sie für das andere Kapitell.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 19, 'Die Kapitelle, die sich oben auf den Säulen befanden, waren in Form von Lilien gearbeitet, in der Vorhalle, vier Ellen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 20, 'a Und Kapitelle waren auf den beiden Säulen auch oberhalb nahe bei dem Wulst, der nach der Seite des Flechtwerks ging. a Und Kapitelle waren auf den beiden Säulen auch oberhalb nahe bei dem Wulst, der nach der Seite des Flechtwerks ging.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 21, 'Er stellte diese Säulen am Eingang zur Vorhalle des Tempels auf; die eine Säule, die er rechts aufstellte, nannte er Jachin, und der anderen, die er links aufstellte, gab er den Namen Boas.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 22, 'Oben auf den Säulen aber war ein lilienförmiges Gebilde; und damit war die Herstellung der Säulen vollendet.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 23, 'Hiram fertigte auch das aus Erz gegossene Meer, das von einem Rande bis zum andern zehn Ellen maß, ringsum gerundet und fünf Ellen hoch; eine Schnur von dreißig Ellen war erforderlich, um es ganz zu umspannen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 24, 'Unterhalb seines Randes waren Gebilde von wilden Gurken angebracht, die es rings umgaben, je zehn auf die Elle; sie bildeten einen Kranz um das Becken, zwei Reihen Gurken, die gleich beim Guß mitgegossen worden waren.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 25, 'Es ruhte auf zwölf Rindern, von denen drei nach Norden, drei nach Westen, drei nach Süden und drei nach Osten gewandt waren; das Becken aber lag oben auf ihnen, und die Hinterseite war bei allen Rindern nach innen gekehrt.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 26, 'Die Dicke (der Wand) des Beckens betrug eine Handbreite, und sein Rand war wie die Arbeit eines Becherrandes geformt, nach Art einer blühenden Lilie. Es faßte zweitausend Bath.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 27, 'Er fertigte auch die zehn Gestühle aus Erz; jedes dieser Gestühle war vier Ellen lang, vier Ellen breit und drei Ellen hoch.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 28, 'Die Gestühle waren aber folgendermaßen gearbeitet: sie hatten Stege, und zwar Stege auch zwischen den Leitersprossen;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 29, 'auf den Stegen aber, die zwischen den Leitersprossen waren, befanden sich Löwen, Rinder und Cherube, und ebenso an den Leitersprossen oben und unten; unterhalb der Löwen und Rinder waren Kränze in Form von Gewinden angebracht.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 30, 'Jedes Gestühl hatte vier eherne Räder und eherne Achsen, und an seinen vier Ecken befanden sich Aufsätze, die unterhalb des Beckens angegossen waren; jenseits eines jeden waren Gewinde.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 31, 'Sein Auflager befand sich innerhalb der Aufsätze und ragte eine Elle darüber hinaus; sein Auflager war rund, in Gestell-Arbeit, anderthalb Ellen im Durchmesser; und auch an dem Auflager war Bildwerk angebracht, seine Stege aber waren viereckig, nicht rund.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 32, 'Die vier Räder befanden sich unten an den Stegen, und die Halter der Räder waren an dem Gestühl befestigt, und jedes Rad war anderthalb Ellen hoch.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 33, 'Die Räder waren wie Wagenräder gearbeitet; ihre Halter und Felgen, ihre Speichen und Naben – alles war Gußwerk.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 34, 'An den vier Eckpfosten jedes Gestühls befanden sich vier Aufsätze, die aus einem Guß mit dem Gestühl waren.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 35, 'Oben auf dem Gestühl war eine Art Gestell, eine halbe Elle hoch, rund ringsum; und oben auf dem Gestühl war der Aufsatz mit seinen Haltern, die das Becken stützten, seine Halter und Stege aus einem Guß mit ihm.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 36, 'Auf die Tafeln und Stege grub er Bildwerk von Cheruben, Löwen und Palmen ein, soweit leerer Raum bei ihnen vorhanden war, und Gewinde ringsum.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 37, 'Auf diese Weise stellte er die zehn Gestühle her; alle hatten denselben Guß, dasselbe Maß und dieselbe Gestaltung. –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 38, 'Dann fertigte er zehn eherne Kessel, von denen jeder vierzig Bath faßte und jeder einen Durchmesser von vier Ellen hatte; auf jedes der zehn Gestühle kam ein solcher Kessel.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 39, 'Von den Gestühlen stellte er fünf auf der Südseite und fünf auf der Nordseite des Tempels auf; das große Wasserbecken aber erhielt seinen Platz auf der Südostseite des Tempels.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 40, 'Weiter fertigte Hiram die Töpfe, Schaufeln und Sprengschalen an und vollendete so alle Arbeiten, die er für den König Salomo am Gotteshause herzustellen hatte,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 41, 'nämlich zwei Säulen mit den beiden kugelförmigen Knäufen oben auf den Säulen sowie die zwei Geflechte zur Bekleidung der beiden kugelförmigen Kapitelle oben auf den Säulen;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 42, 'und die vierhundert Granatäpfel für die beiden Flechtwerke: zwei Reihen Granatäpfel für jedes Flechtwerk;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 43, 'ferner die zehn Gestühle nebst den zehn Kesseln auf den Gestühlen,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 44, 'und das eine große Wasserbecken mit den zwölf Rindern unter dem Becken;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 45, 'sodann die Töpfe, Schaufeln und Sprengschalen. Alle diese Kunstwerke, die Hiram dem König Salomo für den Tempel des HERRN fertigte, waren von geplättetem Erz.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 46, 'In der Jordanaue hatte der König sie gießen lassen an der Furt von Adama, zwischen Sukkoth und Zarethan.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 47, 'Salomo ließ aber alle diese Metallarbeiten ungewogen wegen ihrer übergroßen Menge; das Gewicht des Erzes wurde nicht festgestellt.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 48, 'Ferner ließ Salomo alle die Ausstattungsgegenstände und Geräte anfertigen, die zum Tempel des HERRN gehörten: den vergoldeten Altar und den vergoldeten Tisch, auf dem die Schaubrote lagen;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 49, 'weiter die Leuchter, nämlich fünf auf der rechten und fünf auf der linken Seite vor dem Allerheiligsten aus gediegenem Gold, dazu die Blüten, Lampen und Lichtscheren aus Gold;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 50, 'weiter die Becken, Messer, Sprengschalen, Schüsseln und Räucherpfannen aus gediegenem Gold. Was schließlich die Angeln an den Türflügeln im Innenraum des Tempels, des Allerheiligsten, sowie an den Türflügeln des Großraumes des Tempels betrifft, so waren sie von Gold.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 51, 'Als nun alle Arbeiten, die der König Salomo für den Tempel des HERRN hatte herstellen lassen, fertig waren, ließ Salomo auch die Weihgeschenke seines Vaters David hineinbringen; und zwar legte er das Silber, das Gold und die Geräte in die Schatzkammern des Tempels des HERRN.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 1, 'Damals ließ Salomo die Ältesten der Israeliten und (zwar besonders) alle Häupter der Stämme und die Obersten der israelitischen Geschlechter bei sich in Jerusalem zusammenkommen, um die Bundeslade des HERRN aus der Davidstadt, das ist Zion, hinaufzubringen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 2, 'So versammelten sich denn alle israelitischen Männer beim König Salomo am Fest im Monat Ethanim, das ist der siebte Monat.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 3, 'Als nun alle Ältesten der Israeliten sich eingefunden hatten, hoben die Priester die Lade des HERRN auf');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 4, 'und trugen sie hinauf, ebenso das Offenbarungszelt und alle heiligen Geräte, die sich im Zelt befanden: die Priester und Leviten trugen sie hinauf.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 5, 'Der König Salomo aber und die ganze Volksgemeinde Israel, die sich um ihn versammelt hatte, opferten vor der Lade so viele Stück Kleinvieh und Rinder, daß ihre Menge geradezu unzählbar war.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 6, 'Alsdann brachten die Priester die Lade mit dem Bundesgesetz des HERRN an die für sie bestimmte Stätte, nämlich in den Hinterraum des Tempels, in das Allerheiligste, unter die Flügel der Cherube;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 7, 'die Cherube hielten nämlich ihre Flügel ausgebreitet über die Stätte, wo die Lade stand, so daß die Cherube eine Decke oben über der Lade und deren Tragstangen bildeten.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 8, 'Die Tragstangen aber waren so lang, daß die Spitzen der Stangen im Heiligtum an der Vorderseite des Allerheiligsten eben noch sichtbar waren; weiter außen aber waren sie nicht zu sehen; und sie sind dort geblieben bis auf den heutigen Tag.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 9, 'In der Lade befand sich nichts als nur die beiden steinernen Tafeln, die Mose am Horeb hineingelegt hatte, die Tafeln des Bundes, den der HERR mit den Israeliten nach ihrem Auszug aus Ägypten geschlossen hatte.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 10, 'Als aber die Priester aus dem Heiligtum hinausgetreten waren, da erfüllte die Wolke den Tempel des HERRN,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 11, 'so daß die Priester wegen der Wolke nicht hintreten konnten, um ihren Dienst zu verrichten; denn die Herrlichkeit des HERRN erfüllte den Tempel des HERRN.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 12, 'Damals sprach Salomo: »Der HERR hat gesagt, er wolle im Dunkeln wohnen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 13, 'So habe ich dir nun ein Haus zur Wohnung gebaut, eine Stätte zum Wohnsitz für dich auf ewige Zeiten.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 14, 'Hierauf wandte der König sich um und segnete die ganze Volksgemeinde Israel, wobei die ganze Gemeinde Israel dastand.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 15, 'Dann sagte er: »Gepriesen sei der HERR, der Gott Israels, der die Verheißung, die er meinem Vater David mündlich gegeben, nun tatsächlich erfüllt hat, da er sagte:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 16, '›Seit der Zeit, wo ich mein Volk Israel aus Ägypten hinausgeführt, habe ich aus allen Stämmen Israels nie eine Stadt dazu erwählt, daß mir daselbst ein Haus gebaut würde, an dem mein Name haften sollte; David aber habe ich dazu ersehen, Herrscher über mein Volk Israel zu sein.‹');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 17, 'Nun hatte zwar mein Vater David den Wunsch, dem Namen des HERRN, des Gottes Israels, ein Haus zu bauen;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 18, 'aber der HERR ließ meinem Vater David verkünden: ›Daß du den Wunsch gehegt hast, meinem Namen ein Haus zu bauen, an diesem Vorhaben hast du wohl getan;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 19, 'jedoch nicht du sollst das Haus mir bauen, sondern dein leiblicher Sohn, der dir geboren werden wird, der soll meinem Namen das Haus bauen.‹');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 20, 'Nun hat der HERR diese Verheißung, die er gegeben hat, in Erfüllung gehen lassen; denn ich bin an die Stelle meines Vaters David getreten und habe den Thron Israels bestiegen, wie der HERR es verheißen hatte, und habe dem Namen des HERRN, des Gottes Israels, den Tempel erbaut,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 21, 'und ich habe darin eine Stätte geschaffen für die Lade, in der die Urkunde des Bundes liegt, den der HERR mit unsern Vätern geschlossen hat, als er sie aus dem Lande Ägypten hinausführte.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 22, 'Nunmehr trat Salomo angesichts der ganzen Gemeinde Israel vor den Altar des HERRN, breitete seine Hände gen Himmel aus');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 23, 'und betete: »HERR, du Gott Israels! Kein Gott weder im Himmel droben noch auf der Erde unten ist dir gleich, der du den Bund und die Gnade deinen Knechten bewahrst, die mit ihrem ganzen Herzen vor dir wandeln.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 24, 'Du hast deinem Knechte David, meinem Vater, das Versprechen gehalten, was du ihm gegeben hattest; ja, was du mündlich zugesagt hattest, das hast du tatsächlich erfüllt, wie es heute sichtbar zutage liegt.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 25, 'Und nun, HERR, du Gott Israels, halte deinem Knechte David, meinem Vater, auch die Verheißung, die du ihm gegeben hast mit den Worten: ›Es soll dir nie an einem (Nachkommen) fehlen, der vor meinem Angesicht auf dem Throne Israels sitze, wofern nur deine Söhne auf ihren Weg achthaben, daß sie vor meinen Augen wandeln, wie du vor mir gewandelt bist.‹');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 26, 'Nun also, Gott Israels, laß deine Verheißung, die du deinem Knecht David, meinem Vater, gegeben hast, in Erfüllung gehen!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 27, 'Wie aber? Sollte Gott wirklich auf der Erde Wohnung nehmen? Siehe, der Himmel und aller Himmel Himmel können dich nicht fassen: wieviel weniger dieses Haus, das ich gebaut habe!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 28, 'Und doch wende dich dem Gebet deines Knechtes und seinem Flehen zu, HERR, mein Gott, und höre auf das laute Rufen und das Gebet, das dein Knecht heute an dich richtet!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 29, 'Laß deine Augen bei Tag und bei Nacht offenstehen über diesem Hause, über der Stätte, von der du verheißen hast: ›Mein Name soll daselbst wohnen!‹, daß du auf das Gebet hörest, das dein Knecht an dieser Stätte verrichten wird.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 30, 'So höre denn auf das Flehen deines Knechtes und deines Volkes Israel, sooft sie an dieser Stätte beten werden! Ja, erhöre du es an der Stätte, wo du thronst, im Himmel, und wenn du es hörst, so vergib!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 31, 'Wenn sich jemand gegen seinen Nächsten vergeht und man ihm einen Eid auferlegt, den er schwören soll, und er kommt und schwört vor deinem Altar in diesem Hause:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 32, 'so wollest du es im Himmel hören und eingreifen und deinen Knechten Recht schaffen, indem du den Schuldigen dadurch für schuldig erklärst, daß du sein Tun auf sein Haupt zurückfallen läßt, dem Unschuldigen aber dadurch zu seinem Recht verhilfst, daß du ihm zuteil werden läßt nach seiner Gerechtigkeit!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 33, 'Wenn dein Volk Israel von einem Feinde geschlagen wird, weil es sich gegen dich versündigt hat, sich dann aber wieder zu dir bekehrt und deinen Namen bekennt und in diesem Hause zu dir betet und fleht:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 34, 'so wollest du es im Himmel hören und deinem Volk Israel die Sünde vergeben und sie in dem Lande wohnen lassen, das du ihren Vätern gegeben hast!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 35, 'Wenn der Himmel verschlossen bleibt und kein Regen fällt, weil sie gegen dich gesündigt haben, und sie dann an dieser Stätte beten und deinen Namen bekennen und sich von ihrer Sünde bekehren, weil du sie gedemütigt hast:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 36, 'so wollest du es im Himmel hören und deinen Knechten, deinem Volk Israel, die Sünde vergeben, indem du sie auf den rechten Weg weisest, auf dem sie wandeln sollen, und wollest Regen fallen lassen auf dein Land, das du deinem Volk zum Erbbesitz gegeben hast!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 37, 'Wenn eine Hungersnot im Lande herrscht, wenn die Pest ausbricht, wenn Getreidebrand oder Vergilben des Getreides, Heuschrecken oder Ungeziefer über das Land kommen, wenn seine Feinde es in einer seiner Ortschaften bedrängen oder sonst irgendeine Plage, irgendeine Krankheit sie heimsucht:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 38, 'was man alsdann bittet und fleht, es geschehe von einem einzelnen Menschen oder von deinem ganzen Volk Israel, wenn ein jeder sich in seinem Gewissen getroffen fühlt und er seine Hände nach diesem Hause hin ausstreckt:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 39, 'so wollest du es im Himmel hören an der Stätte, wo du thronst, und wollest Verzeihung gewähren und einem jeden ganz nach Verdienst vergelten, wie du sein Herz kennst – denn du allein kennst das Herz aller Menschenkinder –,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 40, 'damit sie dich allezeit fürchten, solange sie auf dem Boden des Landes leben, das du unsern Vätern gegeben hast!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 41, 'Aber auch den Fremdling, der nicht zu deinem Volk Israel gehört, sondern aus fernem Lande um deines Namens willen hergekommen ist –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 42, 'denn sie werden von deinem großen Namen, von deiner starken Hand und deinem hocherhobenen Arm hören –, wenn er also kommt und vor diesem Tempel betet:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 43, 'so wollest du ihn im Himmel hören an der Stätte, wo du thronst, und alles das tun, um was der Fremdling dich anruft, auf daß alle Völker der Erde deinen Namen kennenlernen, damit sie dich ebenso fürchten wie dein Volk Israel und damit sie innewerden, daß dieses Haus, das ich erbaut habe, deinem Namen als Besitz zugesprochen ist.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 44, 'Wenn dein Volk gegen seine Feinde zum Kampf auszieht auf dem Wege, auf den du sie senden wirst, und sie sich im Gebet zu dem HERRN nach der Stadt hin wenden, die du erwählt hast, und nach dem Tempel hin, den ich zu Ehren deines Namens erbaut habe:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 45, 'so wollest du ihr Gebet und Flehen im Himmel hören und ihnen zu ihrem Recht verhelfen!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 46, 'Wenn sie sich an dir versündigt haben – es gibt ja keinen Menschen, der nicht sündigt – und du ihnen zürnst und sie dem Feinde preisgibst, so daß ihre Besieger sie gefangen wegführen in Feindesland, es liege fern oder nahe,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 47, 'und sie dann in dem Lande, wohin sie in die Gefangenschaft geführt worden sind, in sich gehen und sich bekehren und dich im Lande ihrer Zwingherren mit dem Bekenntnis anrufen: ›Wir haben gesündigt und uns vergangen, wir haben gottlos gehandelt!‹,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 48, 'wenn sie sich also im Lande ihrer Feinde, die sie in Gefangenschaft halten, mit ganzem Herzen und mit ganzer Seele dir wieder zuwenden und zu dir beten in der Richtung nach ihrem Lande hin, das du ihren Vätern gegeben hast, und nach der Stadt hin, die du dir erwählt hast, und nach dem Tempel hin, den ich zu Ehren deines Namens erbaut habe:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 49, 'so wollest du ihr Gebet und Flehen im Himmel an der Stätte, wo du thronst, hören und ihnen zu ihrem Recht verhelfen');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 50, 'und wollest deinem Volke vergeben, was sie gegen dich gesündigt haben, und alle ihre Übertretungen, mit denen sie sich gegen dich vergangen haben, und wollest sie Barmherzigkeit finden lassen bei ihren Zwingherren, so daß diese Erbarmen mit ihnen haben!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 51, 'Denn sie sind dein Volk und dein Eigentum, das du aus Ägypten, mitten aus dem Eisen-Schmelzofen, weggeführt hast.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 52, 'So laß denn deine Augen offenstehen für das Flehen deines Knechtes und für das Flehen deines Volkes Israel, daß du sie erhörest, sooft sie dich anrufen!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 53, 'Denn du selbst hast sie dir zum Eigentum ausgesondert aus allen Völkern der Erde, wie du es durch den Mund deines Knechtes Mose ausgesprochen hast, als du unsere Väter aus Ägypten wegführtest, HERR, unser Gott!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 54, 'Als nun Salomo mit diesem ganzen Gebet und Flehen, das er an den HERRN gerichtet hatte, zu Ende war, erhob er sich von dem Platze vor dem Altar des HERRN, wo er mit zum Himmel ausgebreiteten Händen auf den Knien gelegen hatte;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 55, 'er trat dann hin und segnete die ganze Volksgemeinde Israel, indem er mit lauter Stimme ausrief:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 56, '»Gepriesen sei der HERR, der seinem Volk Israel Ruhe verschafft hat, ganz wie er es verheißen hat! Von all seinen herrlichen Verheißungen, die er durch den Mund seines Knechtes Mose gegeben hat, ist keine einzige unerfüllt geblieben.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 57, 'Der HERR, unser Gott, sei mit uns, wie er mit unsern Vätern gewesen ist! Er verlasse uns nicht und verwerfe uns nicht,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 58, 'sondern lasse unsere Herzen auf ihn gerichtet sein, damit wir allezeit auf seinen Wegen wandeln und seine Gebote, Satzungen und Rechte beobachten, zu denen er unsere Väter verpflichtet hat!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 59, 'Und diese meine Worte, mit denen ich den HERRN angefleht habe, mögen dem HERRN, unserm Gott, bei Tag und bei Nacht gegenwärtig sein, auf daß er seinem Knecht und seinem Volk Israel so, wie jeder Tag es erfordert, Recht schaffe,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 60, 'damit alle Völker der Erde erkennen, daß der HERR Gott ist und sonst keiner.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 61, 'Euer Herz aber möge dem HERRN, unserm Gott, ungeteilt ergeben sein, daß ihr nach seinen Satzungen wandelt und seine Gebote so haltet, wie es heute der Fall ist!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 62, 'Hierauf brachten der König und ganz Israel mit ihm Schlachtopfer vor dem HERRN dar,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 63, 'und zwar ließ Salomo als Heilsopfer, das er dem HERRN darbrachte, 22000 Rinder und 120000 Stück Kleinvieh schlachten: so weihten der König und alle Israeliten den Tempel des HERRN ein.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 64, 'An jenem Tage weihte der König den mittleren Teil des Vorhofes, der vor dem Tempel des HERRN liegt, zur Opferstätte; denn er brachte dort die Brandopfer, die Speisopfer und die Fettstücke der Heilsopfer dar, weil der eherne Altar, der vor dem Tempel des HERRN steht, zu klein war, um die Brand- und Speisopfer und die Fettstücke der Heilsopfer zu fassen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 65, 'Auch beging Salomo damals das (Laubhütten-) Fest und ganz Israel mit ihm – eine gewaltige Festgemeinde, die zusammengekommen war von der Gegend bei Hamath an bis an den Bach Ägyptens – vor dem HERRN, unserm Gott, sieben Tage lang [und noch einmal sieben Tage, im ganzen vierzehn Tage lang].');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 66, 'Am achten Tage aber entließ er das Volk; sie nahmen Abschied vom König und kehrten zu ihren Zelten zurück, fröhlich und wohlgemut wegen all des Guten, mit dem der HERR seinen Knecht David und sein Volk Israel gesegnet hatte.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 9, 1, 'Als nun Salomo den Bau des Tempels des HERRN und des königlichen Palastes vollendet hatte und mit allem, was er sonst noch auszuführen gewünscht hatte, fertig war,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 9, 2, 'da erschien ihm der HERR zum zweitenmal, wie er ihm vorher in Gibeon erschienen war;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 9, 3, 'und der HERR sagte zu ihm: »Ich habe dein Gebet und dein Flehen gehört, das du an mich gerichtet hast. Ich habe diesen Tempel, den du erbaut hast, dazu geweiht, meinen Namen für alle Zeiten daran haften zu lassen, und meine Augen und mein Herz sollen immerdar dort zugegen sein.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 9, 4, 'Wenn du nun vor mir ebenso wandelst, wie dein Vater David es getan hat, in Herzenseinfalt und Aufrichtigkeit, so daß du alles tust, was ich dir geboten habe, und meine Satzungen und Rechte beobachtest,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 9, 5, 'so will ich den Thron deines Königtums über Israel auf ewige Zeiten bestätigen, wie ich es deinem Vater David feierlich zugesagt habe mit den Worten: ›Es soll dir nie an einem Manne auf dem Throne Israels fehlen!‹');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 9, 6, 'Wenn ihr aber von mir abfallt, ihr oder eure Kinder, und meine Gebote und Satzungen, die ich euch zur Pflicht gemacht habe, nicht beobachtet, sondern anderen Göttern zu dienen und sie anzubeten anfangt,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 9, 7, 'so werde ich Israel aus dem Lande, das ich ihnen gegeben habe, ausrotten und den Tempel, den ich meinem Namen geheiligt habe, keines Blickes mehr würdigen, und Israel soll für alle Völker ein Gegenstand des Hohns und Spottes werden.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 9, 8, 'Und dieser Tempel soll zu einem Trümmerhaufen werden, so daß alle, die an ihm vorübergehen, sich entsetzen und zischeln; und wenn man dann fragt: ›Warum hat der HERR diesem Land und diesem Hause solches Geschick widerfahren lassen?‹,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 9, 9, 'so wird man antworten: ›Zur Strafe dafür, daß sie den HERRN, ihren Gott, der ihre Väter aus Ägypten herausgeführt hatte, verlassen und sich anderen Göttern zugewandt und sie angebetet und ihnen gedient haben; darum hat der HERR all dieses Unglück über sie kommen lassen.‹«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 9, 10, 'Nach Ablauf der zwanzig Jahre nun, während deren Salomo die beiden Bauwerke, den Tempel des HERRN und den königlichen Palast, erbaut hatte –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 9, 11, 'Hiram, der König von Tyrus, hatte nämlich dem König Salomo Zedern- und Zypressenholz sowie Gold geliefert, soviel er gewünscht hatte –, damals schenkte der König Salomo dem Hiram zwanzig Städte in der Landschaft Galiläa.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 9, 12, 'Als aber Hiram aus Tyrus herüberkam, um sich die Städte anzusehen, die Salomo ihm überwiesen hatte, gefielen sie ihm nicht,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 9, 13, 'und er sagte: »Was sind das für Städte, die du mir da abgetreten hast, mein Bruder!« Daher nennt man diese Landschaft »Kabul« bis auf den heutigen Tag.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 9, 14, 'Hiram hatte nämlich dem Könige hundertundzwanzig Talente Gold gesandt.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 9, 15, 'Folgendermaßen aber verhielt es sich mit den Fronarbeitern, die der König Salomo ausgehoben hatte, um den Tempel des HERRN und seinen eigenen Palast sowie die Burg Millo und die Mauer Jerusalems zu bauen und um Hazor, Megiddo und Geser zu befestigen:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 9, 16, 'Der Pharao nämlich, der König von Ägypten, war heraufgezogen, hatte Geser erobert und eingeäschert und die Kanaanäer, die in der Stadt wohnten, niedergemacht und dann (den Ort) seiner Tochter, der Gemahlin Salomos, als Mitgift geschenkt;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 9, 17, 'hierauf hatte Salomo Geser wieder aufgebaut, ebenso (baute er) auch das untere Beth-Horon,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 9, 18, 'Baalath, Thamar in der Steppe im Lande Juda,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 9, 19, 'dazu alle Vorratsstädte, die Salomo besaß, und die Ortschaften für die Kriegswagen und die Reitpferde und überhaupt alle Bauten, die Salomo in Jerusalem, auf dem Libanon und im ganzen Bereich seines Königreiches auszuführen wünschte.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 9, 20, 'Alles, was noch an Nachkommen von den Amoritern, Hethitern, Pherissitern, Hewitern und Jebusitern vorhanden war, die nicht zu den Israeliten gehörten –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 9, 21, 'deren Nachkommen, soweit sie im Lande noch übriggeblieben waren, weil die Israeliten den Blutbann an ihnen nicht hatten vollstrecken können, die hob Salomo zum Frondienst aus, und sie sind Fronarbeiter geblieben bis auf den heutigen Tag.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 9, 22, 'Von den Israeliten dagegen machte Salomo keinen zum Leibeigenen, sondern diese dienten ihm als Krieger und Hofbeamte, als hohe und niedere Offiziere und als Befehlshaber über seine Kriegswagen und seine Reiterei.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 9, 23, 'Die Zahl der Oberaufseher, die bei den Arbeiten Salomos beschäftigt waren, belief sich auf 550; sie hatten die bei den Arbeiten beschäftigten Leute zu beaufsichtigen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 9, 24, 'Sobald die Tochter des Pharaos aus der Davidstadt in ihren eigenen Palast eingezogen war, den Salomo für sie hatte bauen lassen, machte er sich an den Bau der Burg Millo. –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 9, 25, 'Dreimal jährlich pflegte Salomo Brand- und Heilsopfer auf dem Altar darzubringen, den er dem HERRN erbaut hatte, und ebenso auf dem (Altar) zu räuchern, der vor dem HERRN stand. Als er den Häuserbau vollendet hatte,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 9, 26, 'schuf König Salomo auch eine Flotte in Ezjon-Geber, das bei Elath am Ufer des Schilfmeeres im Lande der Edomiter liegt.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 9, 27, 'Hiram sandte dann auf dieser Flotte als Bemannung seine Leute – Seeleute, die mit dem Meer vertraut waren – zusammen mit den Leuten Salomos aus.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 9, 28, 'Sie fuhren bis nach Ophir und holten von dort Gold, 420 Talente, und brachten es dem König Salomo.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 10, 1, 'Als aber die Königin von Saba den Ruhm Salomos vernahm und von dem Tempel hörte, den er dem Namen des HERRN erbaut hatte, kam sie, um ihn mit Rätselfragen auf die Probe zu stellen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 10, 2, 'Sie kam also nach Jerusalem mit einem sehr großen Gefolge und mit Kamelen, welche Spezereien und Gold in sehr großer Menge und Edelsteine trugen. Als sie nun bei Salomo angekommen war, trug sie ihm alles vor, was sie sich vorgenommen hatte.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 10, 3, 'Salomo aber wußte ihr auf alle Fragen Antwort zu geben, und nichts war dem Könige verborgen, daß er ihr nicht hätte Auskunft geben können.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 10, 4, 'Als nun die Königin von Saba sich von der allseitigen Weisheit Salomos überzeugt hatte, dazu den Palast sah, den er erbaut hatte,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 10, 5, 'und die Speisen auf seiner Tafel und wie seine Hofleute dasaßen, ferner die Aufwartung seiner Dienerschaft und ihre Tracht, seine Mundschenken sowie seine Brandopfer, die er im Tempel des HERRN darzubringen pflegte, da geriet sie vor Erstaunen außer sich');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 10, 6, 'und sagte zum König: »Wahr ist das gewesen, was ich in meiner Heimat über dich und deine Weisheit gehört habe.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 10, 7, 'Ich wollte dem, was man mir erzählte, nicht glauben, bis ich jetzt hergekommen bin und mich mit eigenen Augen überzeugt habe. Und dabei hat man mir noch nicht einmal die Hälfte berichtet: deine Weisheit und deine Vorzüge übertreffen noch das Gerücht, das ich vernommen habe.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 10, 8, 'Beneidenswert sind deine Leute, beneidenswert diese deine Diener, die beständig um dich sind und deine Weisheit hören können!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 10, 9, 'Gepriesen sei der HERR, dein Gott, der Wohlgefallen an dir gehabt hat, so daß er dich auf den Thron Israels gesetzt hat! Weil der HERR Israel allezeit liebt, darum hat er dich zum König bestellt, damit du Recht und Gerechtigkeit übest.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 10, 10, 'Hierauf schenkte sie dem König hundertundzwanzig Talente Gold und Spezereien in sehr großer Menge, sowie Edelsteine; niemals wieder ist eine solche Fülle von Spezereien ins Land gekommen, wie die Königin von Saba sie damals dem König Salomo schenkte.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 10, 11, 'Allerdings brachten auch die Schiffe Hirams, die Gold aus Ophir geholt hatten, Sandelholz in sehr großer Menge und Edelsteine aus Ophir mit;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 10, 12, 'und der König ließ aus dem Sandelholz Geländer für den Tempel des HERRN und für den königlichen Palast herstellen sowie Zithern und Harfen für die Sänger. In solcher Menge ist Sandelholz nie wieder ins Land gekommen und dort zu sehen gewesen bis auf den heutigen Tag.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 10, 13, 'Der König Salomo aber schenkte der Königin von Saba alles, wonach sie Verlangen trug und was sie sich wünschte, abgesehen von den Geschenken, die er ihr aus freien Stücken mit königlicher Freigebigkeit gab. Hierauf trat sie mit ihrem Gefolge den Rückweg an und zog heim.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 10, 14, 'Das Gewicht des Goldes, das für Salomo in einem einzigen Jahre einging, betrug 666 Talente Gold,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 10, 15, 'ungerechnet die Abgaben der reisenden Großkaufleute und die Steuern der Kleinhändler sowie die Tribute aller Könige Arabiens und was von den Statthaltern des Landes einkam. –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 10, 16, 'Der König Salomo ließ auch zweihundert Langschilde von getriebenem Gold anfertigen: sechshundert Schekel Gold verwandte er auf jeden Schild;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 10, 17, 'ferner dreihundert Kleinschilde von getriebenem Gold; drei Minen Gold verwandte er auf jeden Schild. Der König brachte sie dann im Libanonwaldhause unter. –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 10, 18, 'Weiter ließ der König einen großen Thron von Elfenbein anfertigen und ihn mit feinem Gold überziehen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 10, 19, 'Der Thron hatte sechs Stufen, und das Kopfstück des Thrones hinten war gerundet; auf beiden Seiten des Sitzplatzes befanden sich Armlehnen, und neben den Armlehnen standen zwei Löwen;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 10, 20, 'außerdem standen zwölf Löwen auf den sechs Stufen zu beiden Seiten: ein derartiges Kunstwerk ist noch nie für ein Königreich hergestellt worden. –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 10, 21, 'Alle Trinkgefäße des Königs Salomo bestanden aus Gold; auch alle Geräte im Libanonwaldhause waren von feinem Gold, nichts von Silber, das man zu Salomos Lebzeiten für wertlos ansah.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 10, 22, 'Denn der König hatte Tharsisschiffe, die mit den Schiffen Hirams über Meer fuhren; alle drei Jahre einmal kamen die Tharsisschiffe heim und brachten Gold und Silber, Elfenbein, Affen und Pfauen mit.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 10, 23, 'So übertraf denn der König Salomo alle Könige der Erde an Reichtum und an Weisheit;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 10, 24, 'und alle Welt suchte Salomo zu sehen, um sich persönlich von seiner Weisheit zu überzeugen, die Gott ihm ins Herz gelegt hatte.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 10, 25, 'Dabei brachte jeder von ihnen ein entsprechendes Geschenk mit: silberne und goldene Kunstwerke, Gewänder, Waffen und Spezereien, Rosse und Maultiere, Jahr für Jahr. –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 10, 26, 'Salomo brachte auch zahlreiche Kriegswagen und Reitpferde zusammen, so daß er 1400 Wagen und 12000 Reitpferde besaß, die er in den Wagenstädten oder in seiner Nähe zu Jerusalem unterbrachte.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 10, 27, 'Und der König brachte es dahin, daß es in Jerusalem soviel Silber gab wie Steine und daß die Zedernstämme an Menge den Maulbeerfeigenbäumen in der Niederung gleichkamen. –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 10, 28, 'Der Bezug der Pferde für Salomo erfolgte aus Ägypten, und zwar aus Koa; die Händler des Königs kauften sie dort in Koa auf,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 10, 29, 'so daß ein Wagen bei der Ausfuhr aus Ägypten auf sechshundert Schekel Silber zu stehen kam und ein Pferd auf einhundertundfünfzig. Auf gleiche Weise wurden sie durch Vermittelung (seiner Händler) für alle Könige der Hethiter und für die Könige von Syrien bezogen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 1, 'Der König Salomo liebte aber zahlreiche ausländische Frauen, nämlich neben der Tochter des Pharaos auch moabitische, ammonitische, edomitische, phönizische und hethitische,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 2, 'also Frauen aus solchen Völkern, bezüglich deren der HERR den Israeliten geboten hatte: »Ihr sollt keinen ehelichen Verkehr mit ihnen haben, und sie sollen nicht mit euch verkehren, sie würden sonst sicherlich eure Herzen ihren Göttern zuwenden!« An diesen Frauen hing Salomo mit Vorliebe;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 3, 'und zwar hatte er siebenhundert fürstliche Frauen und dreihundert Nebenweiber, und seine Frauen zogen sein Herz von dem HERRN ab.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 4, 'Als Salomo nämlich alt geworden war, wandten seine Frauen sein Herz anderen Göttern zu, so daß sein Herz dem HERRN, seinem Gott, nicht mehr ungeteilt ergeben war wie das Herz seines Vaters David.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 5, 'So verehrte er z.B. die phönizische Göttin Astarte und den greulichen Götzen der Ammoniter, Milkom;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 6, 'und Salomo tat so, was dem HERRN mißfiel, indem er dem HERRN nicht volle Hingabe bewies wie sein Vater David.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 7, 'Damals baute Salomo für Kamos, den Götzen der Moabiter, ein Höhenheiligtum auf dem Berge östlich von Jerusalem, und ebenso für Moloch, den Götzen der Ammoniter;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 8, 'und dasselbe tat er für alle seine ausländischen Frauen, die ihren Göttern Rauch- und Schlachtopfer darbrachten.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 9, 'So wurde denn der HERR zornig auf Salomo, weil er sein Herz vom HERRN, dem Gott Israels, abgewandt hatte, der ihm doch zweimal erschienen war');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 10, 'und ihm gerade dieses Gebot gegeben hatte, keine fremden Götter zu verehren; trotzdem hatte er dieses Gebot des HERRN unbeachtet gelassen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 11, 'Darum sagte der HERR zu Salomo: »Weil es soweit mit dir gekommen ist, daß du meinen Bund und meine Satzungen, die ich dir zur Pflicht gemacht habe, nicht mehr beachtest, so will ich dir das Königtum entreißen und es einem deiner Knechte geben.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 12, 'Doch will ich es noch nicht bei deinen Lebzeiten tun um deines Vaters David willen; erst deinem Sohne will ich es entreißen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 13, 'Doch will ich ihm nicht das ganze Reich entreißen; nein, einen Stamm will ich deinem Sohne geben um meines Knechtes David willen und um Jerusalems willen, das ich erwählt habe.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 14, 'So ließ denn der HERR dem Salomo einen Widersacher erstehen in dem Edomiter Hadad, der aus dem Königsgeschlecht in Edom stammte.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 15, 'Als David nämlich die Edomiter besiegt hatte und der Feldhauptmann Joab hingezogen war, um die gefallenen Israeliten zu begraben, und er dabei alles, was männlichen Geschlechts in Edom war, niedermetzeln ließ –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 16, 'denn ein halbes Jahr lang war Joab mit dem ganzen Heer der Israeliten dort geblieben, bis er alles, was männlichen Geschlechts in Edom war, ausgerottet hatte –,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 17, 'da entfloh Hadad mit mehreren Edomitern, die zu den Dienern seines Vaters gehört hatten, um sich nach Ägypten zu begeben; Hadad war aber damals noch ein kleiner Knabe.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 18, 'Sie machten sich also aus Midian auf und gelangten nach Paran; aus Paran nahmen sie dann Leute mit sich und kamen so nach Ägypten zum Pharao, dem ägyptischen Könige. Dieser gab ihm ein Haus und wies ihm seinen Unterhalt an und schenkte ihm auch ein Landgut.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 19, 'Hadad gewann dann die Gunst des Pharaos in hohem Grade, so daß er ihm die Schwester seiner Gemahlin, die Schwester der Thachpenes, zur Frau gab.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 20, 'Diese Schwester der Thachpenes gebar ihm dann seinen Sohn Genubath, den sie im Palast des Pharaos erziehen ließ; und fortan lebte Genubath im Palast des Pharaos unter den Söhnen des Königs.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 21, 'Als Hadad dann in Ägypten erfuhr, daß David sich zu seinen Vätern gelegt habe und daß auch der Feldhauptmann Joab tot sei, bat Hadad den Pharao: »Laß mich gehen, daß ich in meine Heimat ziehe!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 22, 'Als ihn der Pharao fragte: »Was fehlt dir denn bei mir, daß du durchaus in deine Heimat ziehen willst?«, antwortete er: »Nichts! Doch du mußt mich ziehen lassen!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 23, 'Und Gott ließ dem Salomo noch einen andern Widersacher erstehen, nämlich Reson, den Sohn Eljadas, der aus der Umgebung Hadad-Esers, seines Herrn, des Königs von Zoba, entflohen war.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 24, 'Dieser sammelte Leute um sich und wurde der Führer einer Freibeuterschar damals, als David das Blutbad unter den Syrern anrichtete. Er zog dann nach Damaskus, setzte sich dort fest, machte sich zum König in Damaskus');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 25, 'a und war ein Widersacher Israels, solange Salomo lebte. a und war ein Widersacher Israels, solange Salomo lebte.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 26, 'Auch Jerobeam, der Sohn Nebats, ein Ephraimit aus Zereda, der Sohn einer Witwe namens Zerua, ein Beamter Salomos, empörte sich gegen den König;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 27, 'und zwar war er folgendermaßen dazu gekommen, sich gegen den König zu empören: Salomo baute die Burg Millo aus, um die Lücke zu schließen, die an der Davidsstadt seines Vaters noch geblieben war.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 28, 'Nun war jener Jerobeam ein tüchtiger Mann, und als Salomo sah, wie eifrig der junge Mann bei der Arbeit war, machte er ihn zum Aufseher über die gesamten Fronarbeiten des Hauses Joseph.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 29, 'Damals begab es sich nun, als Jerobeam eines Tages Jerusalem verlassen hatte, daß ihn der Prophet Ahia von Silo unterwegs traf, der gerade einen neuen Mantel umhatte; und sie beide waren allein auf freiem Felde.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 30, 'Da nahm Ahia den neuen Mantel, den er anhatte, zerriß ihn in zwölf Stücke');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 31, 'und sagte zu Jerobeam: »Nimm dir zehn Stücke davon; denn so hat der HERR, der Gott Israels, gesprochen: ›Siehe, ich will das Reich der Hand Salomos entreißen und will dir zehn Stämme geben –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 32, 'aber den einen Stamm soll er behalten um meines Knechtes David willen und um Jerusalems willen, der Stadt, die ich aus allen Stämmen Israels erwählt habe –,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 33, 'zur Strafe dafür, daß er mich verlassen und sich vor Astarte, der Gottheit der Phönizier, vor Kamos, dem Gott der Moabiter, und vor Milkom, dem Gott der Ammoniter, niedergeworfen hat und nicht auf meinen Wegen gewandelt ist, um das zu tun, was mir wohlgefällt, und meine Satzungen und Rechte zu beobachten, wie sein Vater David es getan hat.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 34, 'Doch will ich nicht ihm selbst die ganze Königsmacht entreißen, sondern will ihm, solange er lebt, die Herrschaft lassen um meines Knechtes David willen, den ich erwählt habe und der meine Gebote und Satzungen beobachtet hat.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 35, 'Aber seinem Sohne will ich das Königtum nehmen und es dir geben, nämlich zehn Stämme;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 36, 'seinem Sohne dagegen will ich nur einen einzigen Stamm geben, damit meinem Knecht David allezeit eine Leuchte vor mir verbleibe in Jerusalem, der Stadt, die ich mir erwählt habe, um meinen Namen daselbst dauernd wohnen zu lassen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 37, 'Dich aber will ich nehmen, damit du herrschest über alles, wonach du Verlangen trägst, und König über Israel seiest.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 38, 'Wenn du dann allen meinen Befehlen nachkommst und auf meinen Wegen wandelst und das tust, was mir wohlgefällt, indem du meine Satzungen und meine Gebote beobachtest, wie mein Knecht David es getan hat, so will ich mit dir sein und dir ein Haus bauen, das Bestand haben soll, wie ich David ein solches gebaut habe, und will dir Israel übergeben;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 39, 'die Nachkommenschaft Davids aber will ich um deswillen demütigen, doch nicht für alle Zeiten.‹« –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 40, 'Als Salomo dann dem Jerobeam nach dem Leben trachtete, machte dieser sich auf und floh nach Ägypten zu Sisak, dem König von Ägypten, und blieb in Ägypten bis zu Salomos Tode.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 41, 'Die übrige Geschichte Salomos aber und alle seine Taten und seine Weisheit, das findet sich bekanntlich schon aufgeschrieben im Buch der Denkwürdigkeiten Salomos.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 42, 'Die Zeit aber, während welcher Salomo in Jerusalem über ganz Israel geherrscht hat, betrug vierzig Jahre.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 43, 'Dann legte Salomo sich zu seinen Vätern und wurde in der Stadt Davids, seines Vaters, begraben. Sein Sohn Rehabeam folgte ihm in der Regierung nach.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 12, 1, 'Rehabeam begab sich nach Sichem; denn in Sichem hatten sich alle Israeliten eingefunden, um ihn zum König zu machen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 12, 2, 'Sobald nun Jerobeam, der Sohn Nebats, Kunde davon erhielt – er befand sich nämlich noch in Ägypten, wohin er vor dem König Salomo geflohen war –, da kehrte Jerobeam aus Ägypten zurück;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 12, 3, 'sie hatten nämlich hingesandt und ihn rufen lassen. So kamen denn Jerobeam und die ganze Volksgemeinde Israels (nach Sichem) und trugen dem Rehabeam folgendes vor:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 12, 4, '»Dein Vater hat uns ein hartes Joch auferlegt; so erleichtere du uns jetzt deines Vaters harten Dienst und das schwere Joch, das er uns aufgelegt hat, so wollen wir dir untertan sein.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 12, 5, 'Er antwortete ihnen: »Geduldet euch noch drei Tage, dann kommt wieder zu mir!« Nachdem sich nun das Volk entfernt hatte,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 12, 6, 'beriet sich der König Rehabeam mit den alten Räten, die seinem Vater Salomo während dessen Lebzeiten gedient hatten, und fragte sie: »Welche Antwort ratet ihr mir diesen Leuten zu erteilen?«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 12, 7, 'Sie gaben ihm folgende Antwort: »Wenn du heute diesen Leuten zu Willen bist, dich nachgiebig zeigst und auf sie hörst und ihnen eine freundliche Antwort gibst, so werden sie dir stets gehorsame Untertanen sein.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 12, 8, 'Aber er ließ den Rat, den ihm die Alten gegeben hatten, unbeachtet und beriet sich mit den jungen Männern, die mit ihm aufgewachsen waren und jetzt in seinen Diensten standen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 12, 9, 'Er fragte sie: »Welche Antwort müssen wir nach eurer Ansicht diesen Leuten geben, die von mir eine Erleichterung des Joches verlangen, das mein Vater ihnen aufgelegt hat?«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 12, 10, 'Da gaben ihm die jungen Männer, die mit ihm aufgewachsen waren, folgende Antwort: »So mußt du diesen Leuten antworten, die von dir eine Erleichterung des schweren Joches verlangen, das dein Vater ihnen aufgelegt hat – so mußt du ihnen antworten: ›Mein kleiner Finger ist dicker als meines Vaters Lenden.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 12, 11, 'Und nun: hat mein Vater euch ein schweres Joch aufgeladen, so will ich euer Joch noch schwerer machen; hat mein Vater euch mit Peitschen gezüchtigt, so will ich euch mit Skorpionen züchtigen.‹«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 12, 12, 'Als nun Jerobeam mit dem ganzen Volk am dritten Tage zu Rehabeam kam, wie der König ihnen befohlen hatte mit den Worten: »Kommt am dritten Tage wieder zu mir!«,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 12, 13, 'gab der König dem Volke eine harte Antwort und ließ den Rat außer acht, den die Alten ihm gegeben hatten;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 12, 14, 'er gab ihnen vielmehr nach dem Rat der jungen Männer folgende Antwort: »Hat mein Vater euch ein schweres Joch aufgelegt, so will ich euer Joch noch schwerer machen; hat mein Vater euch mit Peitschen gezüchtigt, so will ich euch mit Skorpionen züchtigen.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 12, 15, 'So schenkte also der König dem Volke kein Gehör; denn vom HERRN war es so gefügt worden, damit er seine Verheißung in Erfüllung gehen ließe, die der HERR durch den Mund Ahias von Silo dem Jerobeam, dem Sohne Nebats, gegeben hatte.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 12, 16, 'Als nun ganz Israel sah, daß der König ihnen kein Gehör schenkte, ließ das Volk dem König folgende Erklärung zugehen: »Was haben wir mit David zu schaffen? Wir haben nichts gemein mit dem Sohne Isais. Auf, ihr Israeliten, zu euren Zelten! Nun sorge (selbst) für dein Haus, David!« So begaben sich denn die Israeliten in ihre Heimat,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 12, 17, 'so daß Rehabeam nur über die Israeliten, die in den Ortschaften Judas wohnten, König blieb.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 12, 18, 'Als dann der König Rehabeam Adoram, den Oberaufseher über die Fronarbeiten, hinsandte, warf ihn ganz Israel mit Steinen zu Tode. Da hatte der König nichts Eiligeres zu tun, als seinen Wagen zu besteigen, um (aus Sichem) nach Jerusalem zu fliehen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 12, 19, 'So fiel Israel vom Hause Davids ab bis auf den heutigen Tag.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 12, 20, 'Als nun ganz Israel vernahm, daß Jerobeam zurückgekehrt sei, ließen sie ihn in die Gemeindeversammlung holen und machten ihn zum König über ganz Israel; dem Hause Davids blieb nur der eine Stamm Juda treu.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 12, 21, 'Als nun Rehabeam in Jerusalem angekommen war, bot er das ganze Haus Juda und den Stamm Benjamin, 180000 auserlesene Krieger, zum Kampf gegen das Haus Israel auf, um das Königtum für Rehabeam, den Sohn Salomos, wiederzugewinnen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 12, 22, 'Aber das Wort Gottes erging an den Gottesmann Semaja also:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 12, 23, '»Sage zu Rehabeam, dem Sohne Salomos, dem König von Juda, und zum ganzen Hause Juda und Benjamin und zu dem übrigen Volk:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 12, 24, 'So hat der HERR gesprochen: ›Ihr sollt nicht hinziehen, um mit euren Brüdern, den Israeliten, Krieg zu führen: kehrt allesamt nach Hause zurück! Denn von mir ist dieses alles so gefügt worden.‹« Da gehorchten sie dem Befehl des HERRN und machten sich auf den Heimweg, wie der HERR es geboten hatte.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 12, 25, 'Jerobeam aber befestigte Sichem im Gebirge Ephraim und machte es zu seiner Residenz; darauf zog er von dort aus und befestigte Pnuel.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 12, 26, 'Er dachte aber bei sich: »Das Königtum wird nun wohl an das Haus Davids zurückfallen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 12, 27, 'Wenn nämlich das Volk hier hinaufziehen muß, um im Tempel des HERRN zu Jerusalem Opfer darzubringen, so wird das Herz des Volkes hier sich wieder dem König Rehabeam von Juda als ihrem Herrn zuwenden; sie werden mich dann umbringen und dem König Rehabeam von Juda wieder zufallen.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 12, 28, 'Als der König dann mit sich zu Rate gegangen war, ließ er zwei goldene Stierbilder anfertigen und sagte zum Volk: »Ihr seid nun lange genug nach Jerusalem hinaufgezogen. Seht, dies hier ist euer Gott, Israeliten, der euch aus Ägypten hergeführt hat!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 12, 29, 'Das eine Stierbild stellte er dann in Bethel auf, das andere ließ er nach Dan bringen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 12, 30, 'Dies wurde aber eine Veranlassung zur Sünde; und das Volk ging zu dem einen hin (nach Bethel und zu dem andern) nach Dan.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 12, 31, 'Er richtete auch Opferstätten auf den Höhen ein und bestellte zu Priestern beliebige Leute aus dem Volk, die nicht zu den Leviten gehörten.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 12, 32, 'Ferner ordnete Jerobeam ein Fest an am fünfzehnten Tage des achten Monats, das dem Laubhüttenfest in Juda entsprach, und opferte selbst auf dem Altar. Ebenso machte er es zu Bethel, um den Stierbildern zu opfern, die er hatte anfertigen lassen, und er ließ in Bethel die Priester der Höhentempel, die er eingerichtet hatte, den heiligen Dienst verrichten.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 12, 33, 'Als er nun zu dem Altar hinaufgestiegen war, den er in Bethel errichtet hatte, am fünfzehnten Tage des achten Monats, in demselben Monat, den er willkürlich zu einem Festtag der Israeliten bestimmt hatte, – als er also zu dem Altar hinaufgestiegen war, um zu opfern,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 1, 'da kam plötzlich auf Geheiß des HERRN ein Gottesmann aus Juda nach Bethel, während Jerobeam gerade am Altar stand, um zu opfern.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 2, 'Dieser rief auf Geheiß des HERRN folgende Worte gegen den Altar aus: »Altar! Altar! So hat der HERR gesprochen: ›Einst wird dem Hause Davids ein Sohn geboren werden namens Josia; der wird auf dir die Höhenpriester schlachten, die auf dir opfern, und Menschengebeine wird man auf dir verbrennen!‹«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 3, 'Gleichzeitig kündigte er ein Wunderzeichen an mit den Worten: »Dies ist das Wahrzeichen dafür, daß der HERR es ist, der jetzt durch mich geredet hat: Der Altar da wird jetzt bersten und die Fettasche, die darauf liegt, verschüttet werden.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 4, 'Sobald nun der König die Worte hörte, die der Gottesmann gegen den Altar zu Bethel ausgerufen hatte, streckte Jerobeam seinen Arm aus vom Altar herab und rief: »Nehmt ihn fest!« Aber sein Arm, den er gegen ihn ausgestreckt hatte, erstarrte, so daß er ihn nicht wieder zurückziehen konnte.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 5, 'Der Altar aber barst, und die Fettasche, die darauf lag, wurde vom Altar herab verschüttet, wie der Gottesmann es als Wahrzeichen auf Geheiß des HERRN angekündigt hatte.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 6, 'Da richtete der König an den Gottesmann die Bitte: »Besänftige doch den HERRN, deinen Gott, und bitte für mich, daß ich meinen Arm wieder an mich ziehen kann!« Da legte der Gottesmann Fürsprache beim HERRN ein, so daß der König seinen Arm wieder an sich ziehen konnte und dieser wieder so wurde wie zuvor.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 7, 'Darauf sagte der König zu dem Gottesmann: »Komm mit mir ins Haus und erquicke dich! Ich will dir auch ein Geschenk geben.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 8, 'Aber der Gottesmann antwortete dem Könige: »Wenn du mir auch deinen halben Besitz gäbest, so würde ich doch nicht mit dir gehen, würde auch an diesem Ort weder Brot essen noch Wasser trinken.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 9, 'Denn so ist mir geboten worden durch das Wort des HERRN, das da lautete: ›Du darfst dort weder Brot essen noch Wasser trinken, darfst auch nicht auf dem Wege zurückkehren, auf dem du hingegangen bist!‹«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 10, 'Darauf zog er auf einem andern Wege von dannen und kehrte nicht auf dem Wege zurück, auf dem er nach Bethel gekommen war.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 11, 'Nun wohnte in Bethel ein alter Prophet; dessen Söhne kamen heim und erzählten ihm alles, was der Gottesmann an jenem Tage in Bethel getan, und die Worte, die er an den König gerichtet hatte. Als sie dies ihrem Vater erzählt hatten,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 12, 'fragte ihr Vater sie, auf welchem Wege er weggegangen sei. Als seine Söhne ihm den Weg bezeichnet hatten, den der Gottesmann, der aus Juda gekommen war, eingeschlagen hatte,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 13, 'befahl er seinen Söhnen: »Sattelt mir den Esel!«, und als sie ihm den Esel gesattelt hatten, bestieg er ihn');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 14, 'und ritt hinter dem Gottesmanne her. Er fand ihn unter der Terebinthe sitzen und fragte ihn: »Bist du der Gottesmann, der aus Juda gekommen ist?« Er antwortete: »Ja.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 15, 'Da bat er ihn: »Komm mit mir nach Hause und nimm einen Imbiß bei mir ein!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 16, 'Doch er entgegnete: »Ich darf nicht mit dir umkehren und bei dir einkehren, werde auch an diesem Ort kein Brot essen noch Wasser mit dir trinken;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 17, 'denn durch das Wort des HERRN ist mir der Befehl erteilt: ›Du darfst dort weder Brot essen noch Wasser trinken, darfst auch nicht auf dem Wege zurückkehren, auf dem du gekommen bist.‹«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 18, 'Aber jener entgegnete ihm: »Auch ich bin ein Prophet wie du, und ein Engel hat mir auf Geheiß des HERRN geboten: ›Bringe ihn mit dir in dein Haus zurück, auf daß er Brot esse und Wasser trinke!‹« Damit sagte er ihm aber die Unwahrheit.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 19, 'Da kehrte er mit ihm um und aß Brot in seinem Hause und trank Wasser.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 20, 'Während sie aber bei Tisch saßen, erging das Wort des HERRN an den Propheten, der ihn zurückgeholt hatte;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 21, 'und er rief dem Gottesmanne, der aus Juda gekommen war, die Worte zu: »So hat der HERR gesprochen: ›Zur Strafe dafür, daß du gegen den Befehl des HERRN ungehorsam gewesen bist und auf das Gebot, das der HERR, dein Gott, dir gegeben hat, nicht geachtet hast,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 22, 'sondern umgekehrt bist und Brot gegessen und Wasser getrunken hast an dem Ort, an welchem der HERR dir zu essen und zu trinken verboten hatte, wird deine Leiche nicht in das Grab deiner Väter kommen!‹«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 23, 'Nachdem er nun mit Essen und Trinken fertig war, sattelte er sich den Esel des Propheten, der ihn zurückgeholt hatte.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 24, 'Als er dann weggeritten war, stieß unterwegs ein Löwe auf ihn und tötete ihn, und sein Leichnam lag auf dem Wege hingestreckt, während der Esel neben ihm stehenblieb und auch der Löwe neben dem Toten stand.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 25, 'Als nun Leute, die dort vorübergingen, den Leichnam auf dem Wege hingestreckt und den Löwen neben dem Toten stehen sahen, gingen sie hin und erzählten es in der Stadt, in welcher der alte Prophet wohnte.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 26, 'Sobald nun der Prophet, der ihn von der Heimkehr zurückgeholt hatte, dies vernahm, sagte er: »Das ist der Gottesmann, der gegen den Befehl des HERRN ungehorsam gewesen ist; darum hat der HERR ihn dem Löwen preisgegeben; der hat ihn zerrissen und getötet, wie der HERR es ihm vorher angekündigt hatte.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 27, 'Sodann befahl er seinen Söhnen: »Sattelt mir den Esel!«, und als sie ihn gesattelt hatten,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 28, 'ritt er hin und fand seine Leiche auf dem Wege hingestreckt, während der Esel und der Löwe neben dem Toten standen: der Löwe hatte den Toten nicht gefressen und den Esel nicht zerrissen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 29, 'Der Prophet hob nun die Leiche des Gottesmannes auf, lud ihn auf den Esel und brachte ihn in den Wohnort des alten Propheten zurück, um ihm eine Totenfeier zu veranstalten und ihn zu begraben.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 30, 'Er ließ aber die Leiche in sein eigenes Grab legen, und man hielt ihm die Totenklage: »Ach, mein Bruder!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 31, 'Nachdem er ihn aber begraben hatte, sagte er zu seinen Söhnen: »Wenn ich einst gestorben bin, so begrabt mich in demselben Grabe, in welchem der Gottesmann begraben liegt; neben seine Gebeine legt auch die meinigen!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 32, 'Denn die Drohung, die er auf Befehl des HERRN gegen den Altar zu Bethel und gegen alle Höhentempel in den Ortschaften Samarias ausgestoßen hat, wird sicherlich in Erfüllung gehen.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 33, 'Auch nach dieser Begebenheit ließ Jerobeam von seinem bösen Wandel nicht ab, sondern fuhr fort, alle beliebigen Leute zu Höhenpriestern zu machen; wer nur immer Lust dazu hatte, den setzte er ein und bestellte ihn zum Höhenpriester.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 34, 'Dieses Verfahren führte aber beim Hause Jerobeams zur Versündigung und weiter zu seiner Vernichtung und Vertilgung vom Erdboden hinweg.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 14, 1, 'Zu jener Zeit wurde Abia, der Sohn Jerobeams, krank.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 14, 2, 'Da sagte Jerobeam zu seiner Gemahlin: »Mache dich auf, verkleide dich, damit man die Gemahlin Jerobeams in dir nicht erkenne, und begib dich nach Silo. Dort wohnt nämlich der Prophet Ahia, derselbe, der mir einst angekündigt hat, daß ich König über dieses Volk werden würde.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 14, 3, 'Nimm zehn Brote und Kuchen und einen Krug Honig mit und gehe zu ihm: er wird dir verkünden, wie es mit dem Knaben gehen wird.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 14, 4, 'Da tat die Gemahlin Jerobeams so; sie machte sich auf den Weg nach Silo und kam in das Haus Ahias. Ahia aber konnte nicht mehr sehen, denn seine Augen waren infolge seines hohen Alters erblindet.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 14, 5, 'Der HERR aber hatte zu Ahia gesagt: »Soeben kommt die Gemahlin Jerobeams, um von dir Auskunft über ihren Sohn zu erhalten, denn er ist krank. So und so sollst du zu ihr sagen.« Als sie nun in ihrer Verkleidung eintrat');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 14, 6, 'und Ahia, während sie zur Tür hereintrat, das Geräusch ihrer Schritte vernahm, rief er ihr zu: »Komm herein, Gattin Jerobeams! Warum doch verstellst du dich so? Mir ist eine harte Botschaft an dich aufgetragen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 14, 7, 'Gehe heim und sage zu Jerobeam: So hat der HERR, der Gott Israels, gesprochen: ›Ich habe dich mitten aus dem Volk emporgehoben und dich zum Fürsten über mein Volk Israel bestellt;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 14, 8, 'ich habe das Königtum dem Hause Davids entrissen und es dir gegeben; du aber bist nicht gewesen wie mein Knecht David, der meine Gebote beobachtet hat und mir von ganzem Herzen gehorsam gewesen ist, so daß er nur das tat, was mir wohlgefiel;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 14, 9, 'nein, du hast mehr Böses getan als alle deine Vorgänger; denn du bist hingegangen und hast dir andere Götter gemacht, nämlich Gußbilder, um mich zum Zorn zu reizen, mich aber hast du hinter deinen Rücken geworfen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 14, 10, 'Darum will ich nunmehr Unglück über das Haus Jerobeams kommen lassen und von den Angehörigen Jerobeams alles ausrotten, was männlichen Geschlechts ist, Unmündige und Mündige in Israel, und will das Haus Jerobeams wegfegen, wie man Unrat wegfegt, bis nichts mehr von ihm übrig ist.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 14, 11, 'Wer von Jerobeams Angehörigen in der Stadt stirbt, den sollen die Hunde fressen, und wer auf dem freien Felde stirbt, den sollen die Vögel des Himmels fressen; denn der HERR hat gesprochen!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 14, 12, 'Du aber mache dich auf und kehre heim: sowie deine Füße die Stadt betreten, wird der Knabe sterben.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 14, 13, 'Ganz Israel wird dann um ihn klagen, und man wird ihn begraben; denn von den Angehörigen Jerobeams wird dieser allein in ein Grab kommen, weil sich an ihm noch etwas Gutes vor dem HERRN, dem Gott Israels, im Hause Jerobeams gefunden hat.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 14, 14, 'Der HERR aber wird sich einen König über Israel erstehen lassen, der das Haus Jerobeams ausrotten soll an jenem Tage; und was geschieht schon jetzt?');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 14, 15, 'Und der HERR wird Israel schlagen, daß es schwankt, wie das Schilfrohr im Wasser schwankt; er wird Israel aus diesem schönen Lande verstoßen, das er ihren Vätern gegeben hat, und wird sie zerstreuen jenseits des Euphratstroms zur Strafe dafür, daß sie sich Götzenbilder angefertigt und den HERRN dadurch erzürnt haben.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 14, 16, 'Ja, er wird Israel dahingeben um der Sünden Jerobeams willen, die er selbst begangen und zu denen er Israel verführt hat!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 14, 17, 'Da machte sich die Gemahlin Jerobeams auf den Weg und kehrte nach Thirza zurück; kaum hatte sie dort die Schwelle des Königshauses betreten, als der Knabe starb.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 14, 18, 'Man begrub ihn, und ganz Israel hielt ihm die Totenklage, wie der HERR es durch seinen Knecht, den Propheten Ahia, hatte ankündigen lassen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 14, 19, 'Die übrige Geschichte Jerobeams aber, wie er Kriege geführt und wie er regiert hat, das findet sich bekanntlich bereits aufgezeichnet im Buch der Denkwürdigkeiten der Könige von Israel.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 14, 20, 'Die Dauer der Regierung Jerobeams betrug zweiundzwanzig Jahre; dann legte er sich zu seinen Vätern, und sein Sohn Nadab folgte ihm in der Regierung nach.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 14, 21, 'Rehabeam aber, der Sohn Salomos, war König über Juda; 41 Jahre war Rehabeam alt, als er König wurde, und 17 Jahre regierte er in Jerusalem, der Stadt, die der HERR aus allen Stämmen Israels erwählt hatte, um seinen Namen dort wohnen zu lassen. Seine Mutter hieß Naama und war eine Ammonitin.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 14, 22, 'Juda tat aber, was dem HERRN mißfiel, und sie reizten ihn durch die Sünden, die sie begingen, in noch höherem Grade zum Eifer, als er erregt worden war durch alles, was ihre Väter getan hatten;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 14, 23, 'denn auch sie errichteten sich Höhentempel, Malsteine und Götzenbilder auf jedem hohen Hügel und unter jedem dichtbelaubten Baume;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 14, 24, 'ja, auch Heiligtumsbuhler gab es im Lande, (kurz) sie taten es allen Greueln der Heidenvölker gleich, die der HERR vor den Israeliten vertrieben hatte.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 14, 25, 'Aber im fünften Regierungsjahre Rehabeams zog Sisak, der König von Ägypten, gegen Jerusalem heran');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 14, 26, 'und raubte die Schätze des Tempels des HERRN und die Schätze des königlichen Palastes, überhaupt alles raubte er; auch die goldenen Schilde nahm er weg, die Salomo hatte anfertigen lassen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 14, 27, 'An deren Stelle ließ der König Rehabeam eherne Schilde herstellen und übergab sie der Obhut der Befehlshaber seiner Leibwache, die am Eingang zum königlichen Palast die Wache hatte.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 14, 28, 'Sooft sich nun der König in den Tempel des HERRN begab, mußten die Leibwächter die Schilde tragen und brachten sie dann wieder in das Wachtzimmer der Leibwache zurück.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 14, 29, 'Die übrige Geschichte Rehabeams aber und alles, was er unternommen hat, findet sich bekanntlich aufgezeichnet im Buche der Denkwürdigkeiten der Könige von Juda.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 14, 30, 'Es bestand aber Krieg zwischen Rehabeam und Jerobeam, solange sie lebten.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 14, 31, 'Rehabeam legte sich dann zu seinen Vätern und wurde bei seinen Vätern in der Davidsstadt begraben [seine Mutter hieß Naama und war eine Ammonitin]; und sein Sohn Abia folgte ihm in der Regierung nach.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 1, 'Im achtzehnten Regierungsjahre Jerobeams, des Sohnes Nebats, wurde Abia König über Juda.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 2, 'Er regierte drei Jahre in Jerusalem; seine Mutter hieß Maacha und war eine Enkeltochter Absaloms.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 3, 'Abia wandelte in allen Sünden seines Vaters, die dieser vor ihm begangen hatte, und sein Herz war dem HERRN, seinem Gott, nicht ungeteilt ergeben wie das Herz seines Ahnherrn David.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 4, 'Doch um Davids willen hatte der HERR, sein Gott, ihm eine Leuchte in Jerusalem scheinen lassen, indem er seinen Sohn nach ihm (auf den Thron) erhob und Jerusalem bestehen ließ,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 5, 'weil David getan hatte, was dem HERRN wohlgefiel, und während seines ganzen Lebens von allem, was er ihm geboten, nicht abgewichen war, abgesehen von dem Vorkommnis mit dem Hethiter Uria.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 6, 'Es bestand aber Krieg zwischen Abia und Jerobeam, solange er lebte.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 7, 'Die übrige Geschichte Abias aber und alles, was er unternommen hat, findet sich bekanntlich aufgezeichnet in dem Buche der Denkwürdigkeiten der Könige von Juda. Es bestand aber Krieg zwischen Abia und Jerobeam.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 8, 'Als Abia sich dann zu seinen Vätern gelegt und man ihn in der Davidsstadt begraben hatte, folgte ihm sein Sohn Asa in der Regierung nach.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 9, 'Im zwanzigsten Jahre der Regierung Jerobeams, des Königs von Israel, wurde Asa König über Juda');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 10, 'und regierte 41 Jahre zu Jerusalem; seine Mutter hieß Maacha und war eine Tochter Absaloms.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 11, 'Asa tat, was dem HERRN wohlgefiel, wie sein Ahnherr David.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 12, 'So jagte er denn die Heiligtumsbuhler aus dem Lande und entfernte alle Götzenbilder, die seine Vorfahren hatten anfertigen lassen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 13, 'Sogar seiner Mutter Maacha entzog er den Rang der Königin-Mutter, weil sie der Aschera ein Schandmal hatte anfertigen lassen; Asa ließ ihr Schandmal umhauen und im Kidrontal verbrennen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 14, 'Der Höhendienst wurde allerdings nicht abgeschafft, doch war das Herz Asas dem HERRN zeitlebens ungeteilt ergeben.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 15, 'Er ließ auch die Geschenke, die sein Vater und die er selbst geweiht hatte, in den Tempel des HERRN bringen, Silber, Gold und Geräte.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 16, 'Es bestand aber zwischen Asa und dem König Baesa von Israel Krieg, solange sie lebten.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 17, 'Dabei zog Baesa, der König von Israel, gegen Juda hinauf und befestigte Rama, damit niemand mehr bei Asa, dem König von Juda, ungehindert aus- und eingehen könne.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 18, 'Da nahm Asa alles Silber und Gold, das noch in den Schatzkammern des Tempels des HERRN vorhanden war, und die Schätze des königlichen Palastes, übergab sie seinen Dienern und sandte sie an Benhadad, den Sohn Tabrimmons, den Enkel Hesjons, den König von Syrien, der in Damaskus seinen Sitz hatte, und ließ ihm sagen:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 19, '»Ein Bündnis besteht zwischen mir und dir, zwischen meinem Vater und deinem Vater. Hier übersende ich dir ein Geschenk an Silber und Gold. So löse denn dein Bündnis mit dem König Baesa von Israel, damit er aus meinem Lande abziehe!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 20, 'Benhadad schenkte der Aufforderung des Königs Asa Gehör, ließ seine Heerführer gegen die Städte Israels ziehen und eroberte Ijjon, Dan, Abel-Beth-Maacha und ganz Kinneroth nebst der ganzen Landschaft Naphthali.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 21, 'Sobald nun Baesa Kunde davon erhielt, gab er die Befestigung Ramas auf und kehrte nach Thirza zurück.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 22, 'Nun bot der König Asa ganz Juda auf bis auf den letzten Mann; die mußten die Steine und Balken wegschaffen, mit denen Baesa Rama hatte befestigen wollen; und der König Asa ließ damit Geba im Stamme Benjamin und Mizpa befestigen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 23, 'Die ganze übrige Geschichte Asas aber und alle seine tapferen Taten und alles, was er unternommen hat, sowie seine Festungsbauten, das findet sich bekanntlich aufgezeichnet im Buche der Denkwürdigkeiten der Könige von Juda. Doch hatte er in seinem Alter an einer Fußkrankheit zu leiden.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 24, 'Als Asa sich dann zu seinen Vätern gelegt und man ihn bei seinen Vätern in der Stadt Davids, seines Ahnherrn, begraben hatte, folgte ihm sein Sohn Josaphat in der Regierung nach.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 25, 'Nadab aber, der Sohn Jerobeams, wurde König über Israel im zweiten Jahre der Regierung Asas, des Königs von Juda, und regierte zwei Jahre über Israel.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 26, 'Er tat, was dem HERRN mißfiel, und wandelte auf dem Wege seines Vaters und in dessen Sünde, zu der er Israel verführt hatte.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 27, 'Aber Baesa, der Sohn Ahias, aus dem Hause Issaschar, zettelte eine Verschwörung gegen ihn an und ermordete ihn bei der Philisterstadt Gibbethon, während Nadab und ganz Israel Gibbethon gerade belagerten.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 28, 'Baesa brachte ihn also im dritten Regierungsjahre Asas, des Königs von Juda, ums Leben und wurde König an seiner Statt.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 29, 'Sobald er nun die Herrschaft erlangt hatte, rottete er das ganze Haus Jerobeams aus: er ließ von den Angehörigen Jerobeams keine lebende Seele übrig, bis er sie vertilgt hatte, wie der HERR es durch den Mund seines Knechtes Ahia von Silo hatte ankündigen lassen,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 30, 'zur Strafe für die Sünden, die Jerobeam selbst verübt und zu denen er die Israeliten verführt hatte, indem er den HERRN, den Gott Israels, zum Zorn reizte.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 31, 'Die übrige Geschichte Nadabs aber und alles, was er unternommen hat, findet sich bekanntlich aufgezeichnet im Buche der Denkwürdigkeiten der Könige von Israel.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 32, 'Es bestand aber Krieg zwischen Asa und dem König Baesa von Israel, solange sie lebten.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 33, 'Im dritten Regierungsjahre Asas, des Königs von Juda, wurde Baesa, der Sohn Ahias, König über ganz Israel und regierte in Thirza vierundzwanzig Jahre lang.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 34, 'Er tat, was dem HERRN mißfiel, und wandelte auf dem Wege Jerobeams und in dessen Sünde, zu der er Israel verführt hatte.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 1, 'Da erging das Wort des HERRN an Jehu, den Sohn Hananis, gegen Baesa also:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 2, '»Weil ich dich aus dem Staub erhoben und dich zum Fürsten über mein Volk Israel gemacht habe, du aber auf dem Wege Jerobeams gewandelt bist und mein Volk Israel zur Sünde verführt hast, so daß sie mich durch ihre Sünden zum Zorn reizen,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 3, 'so will ich nun Baesa und sein Haus wegfegen und will es mit deinem Hause machen wie mit dem Hause Jerobeams, des Sohnes Nebats.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 4, 'Wer von den Angehörigen Baesas in der Stadt stirbt, den sollen die Hunde fressen, und wer von ihnen auf dem freien Felde stirbt, den sollen die Vögel des Himmels fressen!« –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 5, 'Die übrige Geschichte Baesas aber und was er unternommen hat sowie seine tapferen Taten, das findet sich bekanntlich aufgezeichnet im Buch der Denkwürdigkeiten der Könige von Israel. –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 6, 'Als Baesa sich dann zu seinen Vätern gelegt und man ihn in Thirza begraben hatte, folgte ihm sein Sohn Ela in der Regierung nach.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 7, 'Übrigens war das Wort des HERRN gegen Baesa und dessen Haus durch den Mund des Propheten Jehu, des Sohnes Hananis, sowohl wegen alles des Bösen ergangen, durch das er sich gegen den HERRN versündigt hatte, um ihn durch sein ganzes Tun zum Zorn zu reizen, so daß er es dem Hause Jerobeams gleichtat, als auch deshalb, weil er dieses ausgerottet hatte.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 8, 'Im sechsundzwanzigsten Jahre der Regierung Asas, des Königs von Juda, wurde Ela, der Sohn Baesas, König über Israel und regierte in Thirza zwei Jahre.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 9, 'Gegen ihn verschwor sich sein Diener Simri, einer seiner Obersten, der über die Hälfte der Kriegswagen gesetzt war. Als sich Ela nun einst in Thirza bei einem Gelage im Hause Arzas, seines Haushofmeisters in Thirza, berauscht hatte,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 10, 'drang Simri dort ein und erschlug ihn im siebenundzwanzigsten Jahre der Regierung Asas, des Königs von Juda, und wurde König an seiner Statt.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 11, 'Als er nun König geworden war, ermordete er, sobald er auf seinem Throne saß, alle zum Hause Baesas Gehörigen; er ließ keinen von ihnen übrig, der männlichen Geschlechts war, weder seine Blutsverwandten noch seine Freunde.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 12, 'So rottete Simri das ganze Haus Baesas aus, gemäß der Drohung, die der HERR durch den Mund des Propheten Jehu gegen Baesa ausgesprochen hatte,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 13, 'wegen all der Sünden, die Baesa und sein Sohn Ela begangen und zu denen sie Israel verführt hatten, um den HERRN, den Gott Israels, durch ihren Götzendienst zum Zorn zu reizen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 14, 'Die übrige Geschichte Elas aber und alles, was er unternommen hat, findet sich bekanntlich aufgezeichnet im Buch der Denkwürdigkeiten der Könige von Israel.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 15, 'Im siebenundzwanzigsten Jahre der Regierung Asas, des Königs von Juda, wurde Simri König für sieben Tage in Thirza, während das Heer die Philisterstadt Gibbethon belagerte.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 16, 'Als nun das Heer im Lager die Kunde erhielt, Simri habe eine Verschwörung angestiftet und den König schon ermordet, da erhob das ganze israelitische Heer noch an demselben Tage Omri, den obersten Befehlshaber des israelitischen Heeres, im Lager zum König über Israel.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 17, 'Darauf zog Omri mit allen Israeliten von Gibbethon ab und belagerte Thirza.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 18, 'Als nun Simri sah, daß die Stadt erobert war, begab er sich in die Burg des königlichen Palastes, steckte den königlichen Palast über sich in Brand und fand so den Tod');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 19, 'um seiner Sünden willen, die er begangen hatte, indem er tat, was dem HERRN mißfiel, indem er auf dem Wege Jerobeams wandelte und in dessen Sünde, durch die er sich verschuldet hatte, indem er Israel zur Sünde verleitete.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 20, 'Die übrige Geschichte Simris aber und seine Verschwörung, die er angestiftet hatte, das findet sich bekanntlich aufgezeichnet im Buche der Denkwürdigkeiten der Könige von Israel.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 21, 'Damals spaltete sich das Volk Israel in zwei Parteien: die eine Hälfte des Volkes hielt es mit Thibni, dem Sohne Ginaths, um ihn zum König zu machen, die andere Hälfte dagegen war für Omri.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 22, 'Aber die Partei Omris gewann die Oberhand über die Anhänger Thibnis, des Sohnes Ginaths; und als Thibni starb, wurde Omri König.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 23, 'Im einunddreißigsten Jahre der Regierung Asas, des Königs von Juda, wurde Omri König über Israel und regierte zwölf Jahre. Als er in Thirza sechs Jahre regiert hatte,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 24, 'kaufte er den Berg Samaria von Semer für zwei Talente Silber, befestigte dann den Berg und nannte die Stadt, die er dort gründete, Samaria nach dem Namen Semers, des früheren Besitzers des Berges.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 25, 'Omri tat aber, was dem HERRN mißfiel, ja, er trieb es noch ärger als alle seine Vorgänger;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 26, 'er wandelte ganz auf dem Wege Jerobeams, des Sohnes Nebats, und in den Sünden, zu denen jener die Israeliten verführt hatte, so daß sie den HERRN, den Gott Israels, durch ihren Götzendienst erzürnten.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 27, 'Die übrige Geschichte Omris aber, seine Unternehmungen und die tapferen Taten, die er vollführt hat, das alles findet sich bekanntlich aufgezeichnet im Buch der Denkwürdigkeiten der Könige von Israel.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 28, 'Als Omri sich dann zu seinen Vätern gelegt und man ihn in Samaria begraben hatte, folgte ihm sein Sohn Ahab in der Regierung nach.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 29, 'Ahab, der Sohn Omris, wurde König über Israel im achtunddreißigsten Jahre der Regierung Asas, des Königs von Juda; und Ahab, der Sohn Omris, regierte über Israel zweiundzwanzig Jahre in Samaria.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 30, 'Er tat aber, was dem HERRN mißfiel, und trieb es noch ärger als alle seine Vorgänger.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 31, 'Und nicht genug, daß er in den Sünden Jerobeams, des Sohnes Nebats, wandelte, heiratete er auch noch Isebel, die Tochter des Sidonierkönigs Ethbaal, und wandte sich dann dem Dienste Baals zu und betete ihn an.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 32, 'Er errichtete dem Baal auch einen Altar in dem Baaltempel, den er in Samaria erbaut hatte,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 33, 'und ließ das Ascherabild anfertigen und verübte noch andere Greuel, um den HERRN, den Gott Israels, noch heftiger zu erzürnen als alle israelitischen Könige, die vor ihm geherrscht hatten.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 34, 'Während seiner Regierung baute Hiel von Bethel die Stadt Jericho wieder auf. Die Grundlegung kostete seinem ältesten Sohne Abiram das Leben, und die Einsetzung der Tore brachte seinem jüngsten Sohne Segub den Tod, wie der HERR es durch den Mund Josuas, des Sohnes Nuns, vorausgesagt hatte.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 17, 1, 'Da sagte Elia, der Thisbiter, aus Thisbe in Gilead, zu Ahab: »So wahr der HERR, der Gott Israels, lebt, in dessen Dienst ich stehe: es soll in den nächsten Jahren weder Tau noch Regen fallen, es sei denn auf mein Wort!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 17, 2, 'Hierauf erging das Wort des HERRN an ihn also:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 17, 3, '»Gehe weg von hier und wende dich ostwärts und verbirg dich am Bache Krith, der östlich vom Jordan fließt.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 17, 4, 'Aus dem Bache sollst du trinken, und den Raben habe ich geboten, dich dort mit Nahrung zu versorgen.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 17, 5, 'Da ging er weg und tat nach dem Befehl des HERRN: er ging hin und ließ sich am Bache Krith nieder, der auf der Ostseite des Jordans fließt;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 17, 6, 'und die Raben brachten ihm Brot und Fleisch am Morgen und ebenso am Abend, und er trank aus dem Bache.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 17, 7, 'Als dann aber der Bach nach einiger Zeit trocken wurde, weil kein Regen im Lande gefallen war,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 17, 8, 'erging das Wort des HERRN an ihn also:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 17, 9, '»Mache dich auf, begib dich nach Zarpath, das zu Sidon gehört, und bleibe daselbst! Ich habe einer Witwe dort geboten, für deinen Unterhalt zu sorgen.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 17, 10, 'Da machte er sich auf den Weg und begab sich nach Zarpath; und als er am Stadttor ankam, war dort eine Witwe gerade damit beschäftigt, Holz zusammenzulesen. Er rief sie an mit den Worten: »Hole mir doch ein wenig Wasser in einem Kruge, damit ich trinke!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 17, 11, 'Als sie nun hinging, um es zu holen, rief er ihr die Worte nach: »Bring mir doch auch einen Bissen Brot mit!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 17, 12, 'Aber sie antwortete: »So wahr der HERR, dein Gott, lebt! Ich besitze nichts Gebackenes; nur noch eine Handvoll Mehl ist im Topf und ein wenig Öl im Kruge. Eben lese ich ein paar Stücke Holz zusammen, dann will ich heimgehen und es für mich und meinen Sohn zubereiten, damit wir es essen und dann sterben.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 17, 13, 'Doch Elia antwortete ihr: »Fürchte dich nicht, gehe heim und tu, wie du gesagt hast; doch zuerst bereite mir davon einen kleinen Kuchen und bringe ihn mir her! Darnach magst du für dich und deinen Sohn auch etwas zubereiten.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 17, 14, 'Denn so hat der HERR, der Gott Israels, gesprochen: ›Das Mehl im Topf soll nicht ausgehen und das Öl im Kruge nicht abnehmen bis zu dem Tage, wo der HERR wieder Regen auf den Erdboden fallen läßt.‹«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 17, 15, 'Da ging sie hin und kam der Weisung Elias nach; und sie hatten lange Zeit zu essen, er und sie und ihr Sohn:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 17, 16, 'das Mehl im Topf ging nicht aus, und das Öl im Kruge nahm nicht ab, wie der HERR es durch den Mund Elias hatte ankündigen lassen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 17, 17, 'Nachmals aber begab es sich, daß der Sohn jener Frau, der das Haus gehörte, krank wurde, und seine Krankheit verschlimmerte sich so, daß kein Atem mehr in ihm blieb.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 17, 18, 'Da sagte sie zu Elia: »Was haben wir miteinander zu schaffen, du Mann Gottes? Du bist nur deshalb zu mir gekommen, um meine Verschuldung bei Gott in Erinnerung zu bringen und den Tod meines Sohnes herbeizuführen!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 17, 19, 'Er antwortete ihr: »Gib mir deinen Sohn her!« Er nahm ihn dann von ihrem Schoß, trug ihn in das Obergemach hinauf, wo er selbst wohnte, und legte ihn auf sein Bett;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 17, 20, 'dann rief er den HERRN an und betete: »HERR, mein Gott, hast du wirklich die Witwe, bei der ich zu Gast bin, so unglücklich gemacht, daß du ihren Sohn hast sterben lassen?«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 17, 21, 'Darauf streckte er sich dreimal über den Knaben hin und rief den HERRN mit den Worten an: »HERR, mein Gott, laß doch die Seele dieses Knaben wieder in ihn zurückkehren!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 17, 22, 'Da erhörte der HERR das Gebet Elias, und die Seele des Knaben kehrte in ihn zurück, so daß er wieder auflebte.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 17, 23, 'Elia aber nahm den Knaben, trug ihn aus dem Obergemach ins Haus hinunter und übergab ihn seiner Mutter mit den Worten: »Sieh her, dein Sohn lebt!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 17, 24, 'Da antwortete die Frau dem Elia: »Ja, nun weiß ich, daß du ein Mann Gottes bist und daß das Wort des HERRN in deinem Munde Wahrheit ist!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 1, 'Lange Zeit darauf aber erging das Wort des HERRN an Elia im dritten Jahr der Dürre also: »Gehe hin, zeige dich dem Ahab; denn ich will auf Erden regnen lassen«.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 2, 'Da machte sich Elia auf den Weg, um dem Ahab vor die Augen zu treten. Die Hungersnot war aber in Samaria immer drückender geworden;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 3, 'da hatte Ahab seinen Haushofmeister Obadja rufen lassen – dieser war ein treuer Verehrer des HERRN;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 4, 'als daher Isebel die Propheten des HERRN ausrottete, hatte Obadja hundert Propheten genommen und sie, je fünfzig Mann, in einer Höhle versteckt und sie mit Brot und Wasser versorgt.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 5, 'Ahab hatte also zu Obadja gesagt: »Komm, wir wollen durch das Land an alle Wasserquellen und an alle Bäche gehen; vielleicht finden wir noch Futter, so daß wir Pferde und Maultiere am Leben erhalten können und nicht einen Teil des Viehs eingehen zu lassen brauchen.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 6, 'Dann hatten sie das Land unter sich geteilt, um es zu durchwandern: Ahab war für sich allein in der einen Richtung gegangen und Obadja auch für sich allein in der anderen Richtung.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 7, 'Während nun Obadja unterwegs war, trat ihm plötzlich Elia entgegen. Als er ihn erkannte, warf er sich auf sein Angesicht nieder und rief aus: »Bist du es wirklich, mein Herr Elia?«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 8, 'Er antwortete ihm: »Jawohl! Gehe hin und sage deinem Herrn: ›Elia ist da!‹«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 9, 'Doch er erwiderte: »Womit habe ich es verdient, daß du deinen Knecht dem Ahab ausliefern willst, damit er mich umbringe?');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 10, 'So wahr der HERR, dein Gott, lebt: es gibt kein Volk und kein Königreich, wohin mein Herr nicht gesandt hätte, um dich zu suchen; sagte man dann: ›Er ist nicht hier‹, so ließ er das Königshaus und das Volk schwören, daß er dich wirklich nicht ausfindig machen würde.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 11, 'Und nun forderst du mich auf: ›Gehe hin und melde deinem Herrn: Elia ist da!‹');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 12, 'Wenn ich jetzt von dir weggehe und der Geist des HERRN dich an einen mir unbekannten Ort entführt und ich dann zu Ahab käme, um es ihm zu melden, und er dich dann nicht fände, so würde er mich hinrichten lassen! Und dein Knecht hat doch den HERRN von Jugend auf gefürchtet.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 13, 'Ist es denn meinem Herrn unbekannt geblieben, was ich getan habe, als Isebel die Propheten des HERRN ermorden ließ? Daß ich von den Propheten des HERRN hundert Mann, je fünfzig in einer Höhle versteckt und sie mit Speise und Trank versorgt habe?');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 14, 'Und jetzt forderst du mich auf: ›Gehe hin und sage deinem Herrn: Elia ist da!‹ Er würde mich ja umbringen!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 15, 'Aber Elia entgegnete: »So wahr Gott, der HERR der Heerscharen, lebt, in dessen Dienst ich stehe: noch heute will ich ihm vor die Augen treten!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 16, 'Da ging Obadja dem Ahab entgegen und berichtete es ihm, und Ahab machte sich auf, um mit Elia zusammenzutreffen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 17, 'Sobald nun Ahab den Elia erblickte, rief er ihm zu: »Bist du wirklich da, du Unglücksstifter für Israel?«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 18, 'Er antwortete: »Nicht ich bin es, der Israel ins Unglück gestürzt hat, sondern du und dein Haus, weil ihr die Gebote des HERRN verlassen habt und den Baalen nachgelaufen seid.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 19, 'Nun aber sende hin und laß ganz Israel bei mir auf dem Berge Karmel zusammenkommen, dazu die vierhundertfünfzig Propheten Baals und die vierhundert Propheten der Aschera, die vom Tisch der Isebel essen.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 20, 'Da sandte Ahab Boten in alle Teile Israels und ließ die Propheten auf dem Berge Karmel zusammenkommen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 21, 'Da trat Elia vor das gesamte Volk hin und sagte: »Wie lange wollt ihr nach beiden Seiten hinken? Wenn der HERR Gott ist, so haltet euch zu ihm; ist es aber der Baal, so folgt diesem nach!« Aber das Volk antwortete ihm kein Wort.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 22, 'Hierauf sagte Elia zum Volk: »Ich bin allein noch als Prophet des HERRN übriggeblieben, der Propheten Baals dagegen sind vierhundertfünfzig Mann.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 23, 'So gebe man uns nun zwei Stiere; sie mögen sich dann einen von den Stieren auswählen und ihn zerstücken und auf die Holzscheite legen, jedoch ohne Feuer daranzubringen. Ich aber will den andern Stier zurichten und ihn auf die Holzscheite legen, ebenfalls ohne Feuer daranzulegen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 24, 'Dann ruft ihr den Namen eures Gottes an, während ich den Namen des HERRN anrufen werde; und der Gott, der dann mit Feuer antwortet, der soll als Gott gelten!« Da rief das ganze Volk: »Der Vorschlag ist gut!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 25, 'Hierauf sagte Elia zu den Propheten Baals: »Wählt euch einen von den Stieren aus und richtet ihn zuerst zu; denn ihr seid in der Mehrzahl; ruft dann den Namen eures Gottes an, aber ihr dürft kein Feuer daranlegen.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 26, 'Da nahmen sie den Stier, dessen Wahl er ihnen freigestellt hatte, richteten ihn zu und riefen den Namen Baals vom Morgen bis zum Mittag an, indem sie riefen: »Baal, erhöre uns!«, aber es erfolgte kein Laut, und niemand antwortete. Dabei tanzten sie um den Altar herum, den sie errichtet hatten.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 27, 'Als es nun Mittag geworden war, da verhöhnte Elia sie mit den Worten: »Ruft recht laut, er ist ja doch ein Gott! Vielleicht ist er eben in Gedanken versunken oder ist beiseite gegangen oder befindet sich auf Reisen; vielleicht schläft er gar und muß erst aufwachen.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 28, 'Da riefen sie recht laut und brachten sich nach ihrem Brauch Wunden mit Schwertern und Spießen bei, bis das Blut an ihnen herabfloß.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 29, 'Als dann der Mittag vorüber war, gerieten sie ins Rasen bis zur Zeit, da man das Speisopfer darzubringen pflegt; aber kein Laut, keine Antwort und keine Erhörung war erfolgt.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 30, 'Nunmehr sagte Elia zu dem ganzen Volk: »Tretet zu mir heran!« Als nun das ganze Volk zu ihm getreten war, stellte er den Altar des HERRN, der niedergerissen worden war, wieder her;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 31, 'er nahm nämlich zwölf Steine nach der Zahl der Stämme der Söhne Jakobs – an den einst das Wort des HERRN also ergangen war: »Israel soll dein Name sein!« –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 32, 'und baute von den Steinen einen Altar im Namen des HERRN; alsdann zog er rings um den Altar einen Graben, der einen Umfang hatte wie ein Feld für zwei Maß Aussaat.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 33, 'Hierauf schichtete er die Holzscheite auf, zerstückte den Stier, legte ihn auf den Holzstoß');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 34, 'und sagte: »Füllet vier Krüge mit Wasser und gießt es über das Brandopfer und über das Holz!« Dann befahl er: »Wiederholt es noch einmal!« Da taten sie es noch einmal. Hierauf befahl er: »Tut es zum drittenmal!« Da taten sie es zum drittenmal,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 35, 'so daß das Wasser rings um den Altar herumlief; und auch den Graben ließ er mit Wasser füllen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 36, 'Als dann die Zeit da war, wo man das Speisopfer darzubringen pflegt, trat der Prophet Elia herzu und betete: »HERR, Gott Abrahams, Isaaks und Israels, laß es heute kund werden, daß du Gott in Israel bist und ich dein Knecht bin und daß ich dies alles nach deinem Befehl getan habe.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 37, 'Erhöre mich, HERR, erhöre mich, damit dieses Volk erkennt, daß du, HERR, der wahre Gott bist und du selbst ihre Herzen zur Umkehr gebracht hast!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 38, 'Da fiel das Feuwer des HERRN herab und verzehrte das Brandopfer und das Holz, die Steine und das Erdreich und leckte sogar das Wasser im Graben auf.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 39, 'Als das ganze Volk das sah, warfen sie sich auf ihr Angesicht nieder und riefen aus: »Der HERR, er ist der wahre Gott! Der HERR, er ist der wahre Gott!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 40, 'Elia aber befahl ihnen: »Ergreift die Propheten Baals, laßt keinen von ihnen entrinnen!« Als man sie nun ergriffen hatte, führte Elia sie an den Bach Kison hinab und ließ sie dort abschlachten.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 41, 'Hierauf sagte Elia zu Ahab: »Gehe hinauf, iß und trink! Denn ich höre schon das Rauschen des Regens.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 42, 'Während nun Ahab hinaufging, um zu essen und zu trinken, stieg Elia der Spitze des Karmels zu und kauerte sich tief zur Erde nieder, indem er sein Gesicht zwischen seine Knie legte.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 43, 'Dann befahl er seinem Diener: »Steige höher hinauf, schaue aus nach dem Meere hin!« Der ging hinauf und schaute aus und meldete: »Es ist nichts zu sehen.« Er antwortete: »Gehe wieder hin!«, und so siebenmal.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 44, 'Beim siebten Male aber meldete er: »Soeben steigt eine Wolke, so klein wie eines Mannes Hand, aus dem Meere auf!« Da befahl er ihm: »Gehe hin und sage zu Ahab: ›Laß anspannen und fahre hinab, damit dich der Regen nicht zurückhält!‹«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 45, 'Und es dauerte nicht lange, da wurde der Himmel schwarz von Wolken und Sturm, und es erfolgte ein gewaltiger Regen; Ahab aber bestieg den Wagen und fuhr nach Jesreel.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 46, 'Über Elia aber kam die Hand des HERRN, so daß er seine Lenden gürtete und vor Ahab herlief bis nach Jesreel hin.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 19, 1, 'Als nun Ahab der Isebel alles mitteilte, was Elia getan, und vor allem, wie er alle Propheten mit dem Schwert umgebracht hatte,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 19, 2, 'da schickte Isebel einen Boten an Elia und ließ ihm sagen: »Die Götter sollen mich jetzt und künftig strafen, wenn ich nicht morgen um diese Zeit mit deinem Leben ebenso verfahre, wie du mit dem Leben eines jeden von ihnen verfahren bist!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 19, 3, 'Da geriet er in Furcht und machte sich schnell auf den Weg, um sein Leben zu retten. Als er dann nach Beerseba, das schon zu Juda gehört, gekommen war, ließ er seinen Diener dort zurück;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 19, 4, 'er selbst aber ging eine Tagereise weit in die Wüste hinein; dort angekommen, setzte er sich unter einem Ginsterstrauch nieder. Da wünschte er sich den Tod und betete: »Es ist genug! Nimm nunmehr, HERR, mein Leben hin, denn ich bin nicht besser als meine Väter.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 19, 5, 'Hierauf legte er sich nieder und schlief unter dem Ginsterstrauch ein; aber plötzlich rührte ihn ein Engel an und sagte zu ihm:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 19, 6, '»Stehe auf, iß!« Als er nun hinblickte, sah er zu seinen Häupten einen auf heißen Steinen gerösteten Brotkuchen liegen, und daneben stand ein Krug mit Wasser. Er aß also und trank und legte sich wieder schlafen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 19, 7, 'Aber der Engel des HERRN kam zum zweitenmal wieder, rührte ihn an und sagte: »Stehe auf, iß! Sonst ist der Weg für dich zu weit.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 19, 8, 'Da stand er auf, aß und trank und wanderte, durch diese Speise gestärkt, vierzig Tage und vierzig Nächte lang bis zum Gottesberge Horeb,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 19, 9, 'wo er in eine Höhle ging und darin über Nacht blieb. Da nun erging an ihn das Wort des HERRN, der zu ihm sagte: »Was willst du hier, Elia?«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 19, 10, 'Er antwortete: »Ich habe für den HERRN, den Gott der Heerscharen, unerschrocken geeifert; denn die Israeliten haben deinen Bund verlassen, deine Altäre niedergerissen und deine Propheten mit dem Schwert getötet; ich allein bin übriggeblieben, und nun trachten sie auch mir nach dem Leben.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 19, 11, 'Da erwiderte er: »Gehe hinaus und tritt auf dem Berge vor den HERRN hin!« Und siehe, der HERR zog an ihm vorüber: ein Sturmwind, gewaltig und stark, der die Berge zerriß und die Felsen spaltete, ging vor dem HERRN her; aber der HERR war nicht in dem Sturme. Nach dem Sturm kam ein Erdbeben: aber der HERR war nicht in dem Erdbeben;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 19, 12, 'und nach dem Erdbeben kam ein Feuer: aber der HERR war nicht in dem Feuer. Nach dem Feuer aber kam ein leises, sanftes Säuseln.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 19, 13, 'Als Elia dieses hörte, verhüllte er sich das Antlitz mit seinem Mantel, ging hinaus und trat an den Eingang der Höhle. Da redete ihn eine Stimme an, die fragte: »Was willst du hier, Elia?«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 19, 14, 'Er antwortete: »Ich habe für den HERRN, den Gott der Heerscharen, unerschrocken geeifert; denn die Israeliten haben deinen Bund verlassen, deine Altäre niedergerissen und deine Propheten mit dem Schwert getötet; ich allein bin übriggeblieben, und nun trachten sie auch mir nach dem Leben.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 19, 15, 'Da sagte der HERR zu ihm: »Kehre jetzt auf demselben Wege nach der Steppe von Damaskus zurück, gehe in die Stadt hinein und salbe Hasael zum König über Syrien;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 19, 16, 'und Jehu, den Sohn Nimsis, sollst du zum König über Israel salben, und Elisa, den Sohn Saphats, aus Abel-Mehola, sollst du zum Propheten an deiner Statt salben.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 19, 17, 'Wer dann dem Schwert Hasaels entrinnt, den wird Jehu töten, und wer dem Schwert Jehus entrinnt, den wird Elisa töten.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 19, 18, 'Doch will ich in Israel siebentausend (Männer) übriglassen: alle, deren Knie sich vor dem Baal nicht gebeugt haben, und alle, deren Mund ihn nicht geküßt hat.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 19, 19, 'Als Elia nun von dort weggegangen war, traf er Elisa, den Sohn Saphats, der gerade pflügte; zwölf Joch Ochsen waren vor ihm her, er selbst aber befand sich bei dem zwölften. Während nun Elia an ihm vorüberschritt, warf er ihm sein Fell über.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 19, 20, 'Da verließ er die Rinder, eilte dem Elia nach und sagte: »Laß mich nur noch Abschied von meinem Vater und meiner Mutter nehmen; dann will ich dir nachfolgen.« Elia antwortete ihm: »Gehe immerhin noch einmal zurück; denn was habe ich dir getan?«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 19, 21, 'Da kehrte er von ihm zurück, nahm das eine Joch Rinder und schlachtete es, mit dem Geschirr der Rinder aber kochte er ihr Fleisch und gab es den Leuten zu essen; dann machte er sich auf den Weg, schloß sich an Elia an und wurde sein Diener.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 1, 'Benhadad aber, der König von Syrien, bot seine ganze Streitmacht auf, zweiunddreißig Könige leisteten ihm Heeresfolge mit Rossen und Wagen; so zog er heran, belagerte Samaria und bestürmte es.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 2, 'Dann schickte er Gesandte in die Stadt zu Ahab, dem König von Israel,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 3, 'und ließ ihm sagen: »So spricht Benhadad: ›Dein Silber und Gold gehört mir, und deine Frauen und deine [schönsten] Kinder gehören ebenfalls mir.‹«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 4, 'Der König von Israel gab ihm zur Antwort: »Wie du befiehlst, mein Herr und König: dein bin ich mit allem, was mir gehört.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 5, 'Darauf kamen die Gesandten noch einmal und sagten: »So spricht Benhadad: ›Ich habe zu dir gesandt und dir sagen lassen: Dein Silber und dein Gold, deine Frauen und deine Kinder sollst du mir geben;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 6, 'morgen also um diese Zeit werde ich meine Diener zu dir senden, damit sie deinen Palast und die Häuser deiner Diener durchsuchen; und sie sollen dann alles, was ihnen beachtenswert erscheint, mit Beschlag belegen und mitnehmen.‹«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 7, 'Da berief der König von Israel alle Ältesten des Landes und sagte: »Da könnt ihr nun klar erkennen, wie böse dieser Mensch es meint; denn als er zu mir sandte, um meine Frauen und meine Kinder, mein Silber und mein Gold zu fordern, habe ich es ihm nicht verweigert.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 8, 'Da antworteten ihm alle Ältesten und das gesamte Volk: »Da gehorchst du nicht und willigst nicht ein!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 9, 'So erwiderte er denn den Gesandten Benhadads: »Meldet meinem Herrn, dem Könige: ›Alles, was du von deinem Knecht zuerst verlangt hast, will ich tun, aber auf diese letzte Forderung kann ich nicht eingehen.‹« Als nun die Gesandten hingegangen waren und den Bescheid überbracht hatten,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 10, 'sandte Benhadad zu ihm und ließ ihm sagen: »Die Götter sollen mich jetzt und künftig strafen, wenn der Schutt von Samaria hinreicht, allen Kriegern, an deren Spitze ich stehe, die hohlen Hände zu füllen!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 11, 'Darauf gab ihm der König von Israel zur Antwort: »Sagt ihm nur: ›Wer sich das Schwert umgürtet, darf sich nicht brüsten, als ob er es schon wieder ablegte.‹«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 12, 'Als Benhadad diesen Bescheid vernahm, während er gerade mit den Königen in den Weinberglauben bei einem Trinkgelage zechte, rief er seinen Leuten zu: »Zum Angriff!«, und sie stellten sich zum Angriff gegen die Stadt auf.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 13, 'Da trat plötzlich ein Prophet zu Ahab, dem König von Israel, und sagte: »So hat der HERR gesprochen: ›Siehst du diesen ganzen gewaltigen Heerhaufen? Wisse wohl: ich gebe ihn dir heute in die Hand, damit du erkennst, daß ich der HERR bin!‹«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 14, 'Ahab fragte: »Durch wen?« Er antwortete: »So hat der HERR gesprochen: ›Durch die Leute der Landvögte.‹« Da fragte er weiter: »Wer soll den Kampf eröffnen?« Er erwiderte: »Du selbst.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 15, 'Darauf musterte Ahab die Leute der Landvögte: es waren ihrer 232 Mann. Nach ihnen musterte er das gesamte übrige Kriegsvolk, alle Israeliten: es waren 7000 Mann.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 16, 'Sie machten dann zur Mittagszeit einen Ausfall, als Benhadad sich gerade in den Lauben samt den zweiunddreißig mit ihm verbündeten Königen einen Rausch antrank.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 17, 'Als nun die Leute der Landvögte als Vortrab ausrückten und Benhadad durch Kundschafter, die er ausgesandt hatte, die Meldung erhielt, daß Leute aus Samaria ausgerückt seien,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 18, 'befahl er: »Mögen sie in friedlicher oder in feindlicher Absicht ausgerückt sein: nehmt sie lebendig gefangen!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 19, 'Sobald aber jene aus der Stadt ausgerückt waren, nämlich die Leute der Landvögte und das ihnen folgende Heer,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 20, 'schlugen sie wütend drein, so daß die Syrer flohen. Die Israeliten verfolgten sie, doch Benhadad, der König von Syrien, rettete sich zu Pferde mit einigen Reitern.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 21, 'Nun rückte auch der König von Israel selber aus, fiel über die Rosse und Wagen her und brachte den Syrern eine schwere Niederlage bei.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 22, 'Da trat der Prophet (wiederum) zum König von Israel und sagte zu ihm: »Wohlan, nimm dich zusammen und sieh wohl zu, was du zu tun hast! Denn übers Jahr wird der König von Syrien wieder gegen dich heranziehen.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 23, 'Die Heerführer des Königs von Syrien aber sagten zu ihm: »Ihr Gott ist ein Berggott, darum sind sie uns überlegen gewesen; wenn wir dagegen in der Ebene mit ihnen kämpfen könnten, würden wir sie gewiß besiegen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 24, 'Gehe also folgendermaßen zu Werke: Entferne die Könige sämtlich von ihren Stellen und ersetze sie durch Statthalter;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 25, 'sodann biete ein ebenso großes Heer auf, wie das vorige war, das dir verlorengegangen ist, ebenso Rosse und Wagen wie das vorige Mal; dann wollen wir mit ihnen in der Ebene kämpfen, so werden wir sie gewiß besiegen.« Benhadad ging auf ihren Vorschlag ein und verfuhr demgemäß.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 26, 'Als dann das Jahr um war, bot Benhadad die Syrer auf und zog nach Aphek, um dort den Israeliten eine Schlacht zu liefern.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 27, 'Nachdem auch die Israeliten gemustert worden waren und sich mit Mundvorrat versorgt hatten, zogen sie ihnen entgegen und lagerten sich ihnen gegenüber wie ein Paar kleine Ziegenherden, während die Syrer die ganze Gegend füllten.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 28, 'Da trat der Gottesmann abermals herzu und sagte zum König von Israel: »So hat der HERR gesprochen: ›Weil die Syrer gesagt haben, der HERR sei ein Gott der Berge, aber kein Gott der Ebenen, so will ich diesen ganzen gewaltigen Heerhaufen in deine Hand geben, damit ihr erkennt, daß ich der HERR bin.‹«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 29, 'So lagerten sie denn sieben Tage lang einander gegenüber; am siebten Tage aber kam es zur Schlacht, und die Israeliten erschlugen von den Syrern hunderttausend Mann Fußvolk an einem einzigen Tage;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 30, 'die Übriggebliebenen flüchteten sich in die Stadt Aphek. Da fiel die Stadtmauer über den 27000 Mann zusammen, die übriggeblieben waren. Auch Benhadad war geflohen und in die Stadt gekommen (und versteckte sich) von einem Gemach in das andere.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 31, 'Da sagten seine Diener zu ihm: »Wir haben oft genug gehört, daß die Könige der Israeliten großmütige Könige seien. So wollen wir uns denn Bußgewänder um unsere Lenden legen und Stricke um unseren Kopf und so zum König von Israel hinausgehen; vielleicht schenkt er dir das Leben.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 32, 'Sie gürteten sich also Bußgewänder um ihre Lenden und legten Stricke um ihren Kopf; und als sie zum König von Israel kamen, sagten sie: »Dein Knecht Benhadad läßt dich bitten, ihm das Leben zu schenken.« Er antwortete: »Lebt er noch? Er ist ja mein Bruder.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 33, 'Die Männer nahmen das als eine gute Vorbedeutung; darum beeilten sie sich, ihn beim Wort zu nehmen, und sagten: »Benhadad ist also dein Bruder?« Da antwortete er: »Geht, bringt ihn her!«, und als Benhadad dann zu ihm hinauskam, ließ er ihn zu sich auf den Wagen steigen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 34, 'Da sagte Benhadad zu ihm: »Die Städte, die mein Vater deinem Vater weggenommen hat, will ich dir zurückgeben; auch magst du dir Handelshäuser in Damaskus anlegen, wie mein Vater sich solche in Samaria angelegt hat.« »Und ich«, entgegnete Ahab, »will dich auf Grund dieses Abkommens freilassen.« Er schloß also einen Vertrag mit ihm und ließ ihn frei.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 35, 'Einer aber von den Prophetenschülern forderte auf Geheiß des HERRN seinen Genossen auf: »Bringe mir eine Wunde bei!« Als jener sich weigerte, ihn zu verwunden,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 36, 'sagte er zu ihm: »Zur Strafe dafür, daß du dem Befehl des HERRN nicht nachgekommen bist, wird dich, sobald du von mir weggegangen bist, ein Löwe töten.« Kaum war er dann von ihm weggegangen, da fiel ein Löwe ihn an und tötete ihn.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 37, 'Als jener hierauf einen anderen (Genossen) traf, forderte er ihn (wieder) auf: »Bringe mir eine Wunde bei!« Da verwundete ihn dieser durch einen Schlag.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 38, 'Nun ging der Prophet hin und stellte sich auf den Weg, den der König kommen mußte, machte sich aber durch eine Binde über seinen Augen unkenntlich.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 39, 'Als dann der König vorüberkam, rief er ihn laut an mit den Worten: »Dein Knecht war mit in die Schlacht gezogen; da trat plötzlich ein Mann, ein Oberer, an mich heran und brachte mir einen Gefangenen mit der Weisung: ›Bewache diesen Mann! Sollte er dir abhanden kommen, so haftest du mit deinem Leben für ihn, oder du hast ein Talent Silber zu bezahlen.‹');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 40, 'Während nun dein Knecht hier und da zu tun hatte, war der Mensch verschwunden.« Da sagte der König von Israel zu ihm: »Da hast du dein Urteil; du hast es dir selbst gesprochen.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 41, 'Da entfernte jener schnell die Binde von seinen Augen, und der König von Israel erkannte in ihm einen von den Propheten.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 42, 'Der aber sagte zu ihm: »So hat der HERR gesprochen: ›Weil du den Mann, der von mir dem Tode geweiht war, aus der Hand gelassen hast, mußt du mit deinem Leben für ihn haften und dein Volk für sein Volk.‹«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 43, 'Da zog der König von Israel mißmutig und verstört nach Hause und gelangte nach Samaria.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 21, 1, 'Nachmals aber begab sich folgendes: Naboth, (ein Bürger) von Jesreel, besaß einen Weinberg in Jesreel nahe bei dem Palaste Ahabs, des Königs von Samaria.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 21, 2, 'Ahab machte nun dem Naboth folgenden Vorschlag: »Tritt mir deinen Weinberg ab, damit ich mir einen Gemüsegarten daraus mache, weil er nahe bei meinem Palaste liegt; ich will dir einen besseren Weinberg dafür geben oder, wenn dir das lieber ist, dir den Preis bar bezahlen.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 21, 3, 'Aber Naboth erwiderte dem Ahab: »Der HERR bewahre mich davor, dir den Erbbesitz meiner Väter abzutreten!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 21, 4, 'Da kehrte Ahab in seinen Palast zurück, mißmutig und verstört über die Antwort, die Naboth, der Jesreeliter, ihm gegeben hatte mit den Worten: »Ich will dir den Erbbesitz meiner Väter nicht abtreten.« Er legte sich auf sein Bett, wandte das Gesicht gegen die Wand ab und wollte keine Nahrung zu sich nehmen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 21, 5, 'Da trat seine Gemahlin Isebel zu ihm und fragte ihn: »Warum bist du denn so mißmutig, daß du nichts essen willst?«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 21, 6, 'Er antwortete ihr: »Ich habe Naboth von Jesreel den Vorschlag gemacht: ›Tritt mir deinen Weinberg gegen Bezahlung ab, oder, wenn du das vorziehst, will ich dir einen anderen Weinberg dafür geben‹; aber er hat mir geantwortet: ›Ich will dir meinen Weinberg nicht abtreten.‹«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 21, 7, 'Da erwiderte ihm seine Gemahlin Isebel: »Jetzt mußt du zeigen, daß du König in Israel bist! Stehe auf, iß und sei guten Muts: ich will dir den Weinberg des Jesreeliters Naboth schon verschaffen.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 21, 8, 'Darauf schrieb sie einen Brief unter Ahabs Namen, versiegelte ihn mit seinem Siegel und schickte den Brief an die Ältesten und Obersten, die in seiner Stadt wohnten und Mitbeisitzer Naboths waren.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 21, 9, 'In dem Briefe schrieb sie folgendes: »Laßt ein Fasten ausrufen und setzt Naboth obenan unter dem Volke!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 21, 10, 'Dann setzt zwei nichtswürdige Menschen ihm gegenüber, die gegen ihn auftreten und das Zeugnis ablegen sollen, er habe Gott und den König gelästert; dann führt ihn vor die Stadt hinaus und steinigt ihn zu Tode!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 21, 11, 'Und die Männer seiner Stadt, die Ältesten und Vornehmen, die in seiner Stadt die Beisitzer waren, taten, wie Isebel ihnen in dem Briefe, den sie ihnen hatte zugehen lassen, aufgetragen hatte:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 21, 12, 'sie ließen ein Fasten ausrufen und setzten Naboth obenan unter dem Volke;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 21, 13, 'dann kamen die zwei nichtswürdigen Buben, setzten sich ihm gegenüber und legten vor dem Volke das Zeugnis gegen ihn ab: »Naboth hat Gott und den König gelästert!« Hierauf führte man ihn zur Stadt hinaus und steinigte ihn; so fand er seinen Tod.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 21, 14, 'Dann sandten sie zu Isebel und ließen ihr melden, Naboth sei gesteinigt worden und sei nun tot.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 21, 15, 'Sobald Isebel die Nachricht von Naboths Steinigung und Tod erhalten hatte, sagte sie zu Ahab: »Auf! Nimm den Weinberg des Jesreeliters Naboth, den er dir für Geld nicht hat überlassen wollen, in Besitz! Denn Naboth lebt nicht mehr, sondern ist tot.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 21, 16, 'Sobald nun Ahab den Tod Naboths erfuhr, machte er sich auf den Weg, um in den Weinberg Naboths hinabzugehen und ihn in Besitz zu nehmen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 21, 17, 'Da erging das Wort des HERRN an Elia, den Thisbiter, also:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 21, 18, '»Mache dich auf, gehe hinab und tritt vor Ahab, den König von Israel, der in Samaria wohnt; er befindet sich gerade im Weinberge Naboths, wohin er hinabgegangen ist, um ihn in Besitz zu nehmen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 21, 19, 'Sage dann zu ihm folgendes: ›So hat der HERR gesprochen: Du hast gemordet und hast nun auch schon die Erbschaft angetreten?‹ Sage dann weiter zu ihm: ›So hat der HERR gesprochen: An der Stelle, wo die Hunde das Blut Naboths geleckt haben, sollen die Hunde auch dein Blut lecken!‹«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 21, 20, 'Da sagte Ahab zu Elia: »Hast du mich wieder herausgefunden, mein Feind?« Er antwortete: »Ja, ich habe dich herausgefunden. Weil du dich so weit vergessen hast, zu tun, was dem HERRN mißfällt:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 21, 21, '›so will ich nunmehr Unglück über dich bringen und dich wegfegen und will von Ahabs Angehörigen alles ausrotten, was männlichen Geschlechts ist, Unmündige wie Mündige, in Israel;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 21, 22, 'und ich will es mit deinem Hause machen wie mit dem Hause Jerobeams, des Sohnes Nebats, und wie mit dem Hause Baesas, des Sohnes Ahias, weil du mich zum Zorn gereizt und Israel zur Sünde verführt hast!‹');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 21, 23, 'Auch in betreff Isebels hat der HERR geredet und angekündigt: ›Die Hunde sollen Isebel am Stadtgraben von Jesreel fressen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 21, 24, 'Wer von Ahabs Angehörigen in der Stadt stirbt, den sollen die Hunde fressen, und wer auf dem Felde stirbt, den sollen die Vögel des Himmels fressen!‹«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 21, 25, 'Es hat niemals einen Menschen gegeben, der sich so weit wie Ahab vergessen hätte, um das zu tun, was dem HERRN mißfällt, weil ihn sein Weib Isebel dazu verführte.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 21, 26, 'Er verübte zahllose Greuel, indem er den Götzen nachging, ganz wie die Amoriter es getan hatten, die der HERR vor den Israeliten vertrieben hatte.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 21, 27, 'Als nun Ahab diese Worte hörte, zerriß er seine Kleider, legte ein härenes Bußgewand um den bloßen Leib und fastete; er schlief sogar in dem Bußgewand und ging bekümmert einher.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 21, 28, 'Da erging das Wort des HERRN an Elia, den Thisbiter, also:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 21, 29, '»Hast du gesehen, wie Ahab sich vor mir gedemütigt hat? Weil er sich vor mir gedemütigt hat, will ich das Unglück nicht schon bei seinen Lebzeiten hereinbrechen lassen: erst unter der Regierung seines Sohnes will ich das Unglück über sein Haus kommen lassen.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 1, 'Drei Jahre vergingen ruhig, ohne daß Krieg zwischen Syrien und Israel stattfand.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 2, 'Im dritten Jahre aber, als Josaphat, der König von Juda, zum König von Israel (auf Besuch) gekommen war,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 3, 'sagte der König von Israel zu seinen Dienern: »Ihr wißt doch wohl, daß Ramoth in Gilead uns gehört? Wir aber sitzen hier müßig, anstatt es dem König von Syrien zu entreißen!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 4, 'Als er hierauf an Josaphat die Frage richtete: »Willst du mit mir gegen Ramoth in Gilead zu Felde ziehen?«, antwortete ihm Josaphat: »Ich will sein wie du: mein Volk wie dein Volk, meine Rosse wie deine Rosse!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 5, 'Als Josaphat dann dem König von Israel riet, zunächst doch den Willen des HERRN zu erforschen,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 6, 'ließ der König von Israel die Propheten zusammenkommen, ungefähr vierhundert Mann, und fragte sie: »Soll ich gegen Ramoth in Gilead zu Felde ziehen, oder soll ich es unterlassen?« Sie antworteten: »Ziehe hin, denn der HERR wird es dem König in die Hand geben.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 7, 'Da fragte Josaphat: »Gibt es hier sonst keinen Propheten des HERRN mehr, durch den wir Auskunft erhalten könnten?«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 8, 'Der König von Israel erwiderte dem Josaphat: »Es ist wohl noch einer da, durch den wir den HERRN befragen könnten, aber ich habe nicht gern mit ihm zu tun; denn er weissagt mir niemals Gutes, sondern immer nur Unglück: Micha, der Sohn Jimlas.« Aber Josaphat entgegnete: »Der König wolle nicht so reden!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 9, 'Da rief der König von Israel einen Kammerherrn und befahl ihm, schleunigst Micha, den Sohn Jimlas, zu holen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 10, 'Während nun der König von Israel und der König Josaphat von Juda ein jeder auf seinem Throne in ihren Königsgewändern auf dem Platz am Eingang des Stadttores von Samaria dasaßen und alle Propheten vor ihnen weissagten,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 11, 'machte sich Zedekia, der Sohn Kenaanas, eiserne Hörner und rief aus: »So spricht der HERR: ›Mit solchen (Hörnern) wirst du die Syrer niederstoßen, bis du sie vernichtet hast!‹«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 12, 'Ebenso weissagten auch alle anderen Propheten, indem sie riefen: »Ziehe hin gegen Ramoth in Gilead: du wirst Glück haben! Denn der HERR wird es dem König in die Hand fallen lassen.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 13, 'Der Bote aber, der hingegangen war, um Micha zu holen, sagte zu ihm: »Wisse: die (übrigen) Propheten haben dem Könige einstimmig Glück verheißen; schließe dich doch ihrem einmütigen Ausspruch an und prophezeie ebenfalls Glück!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 14, 'Micha aber antwortete: »So wahr der HERR lebt: nur was der HERR mir eingeben wird, das werde ich verkünden!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 15, 'Als er nun zum Könige kam, fragte dieser ihn: »Micha, sollen wir gegen Ramoth in Gilead zu Felde ziehen, oder sollen wir es unterlassen?« Er antwortete ihm: »Ziehe hin, du wirst Glück haben! Denn der HERR wird es dem Könige in die Hand fallen lassen.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 16, 'Da entgegnete ihm der König: »Wie oft soll ich dich noch beschwören, mir nichts zu verkünden als nur die reine Wahrheit im Namen des HERRN?«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 17, 'Da sagte Micha: »Ich habe ganz Israel zerstreut auf den Bergen gesehen wie Schafe, die keinen Hirten haben; der HERR aber sagte: ›Diese haben keinen Herrscher mehr: ein jeder von ihnen möge in Frieden nach Hause zurückkehren!‹«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 18, 'Da sagte der König von Israel zu Josaphat: »Habe ich dir nicht gesagt, daß er mir niemals Glück, sondern immer nur Unheil prophezeit?«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 19, 'Micha aber fuhr fort: »Darum vernimm das Wort des HERRN! Ich habe den HERRN auf seinem Throne sitzen sehen, während das ganze himmlische Heer zur Rechten und zur Linken neben ihm stand.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 20, 'Und der HERR fragte: ›Wer will Ahab betören, daß er zu Felde ziehe und bei Ramoth in Gilead falle?‹ Da erwiderte der eine dies, der andere das,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 21, 'bis endlich der Geist vortrat und sich vor den HERRN stellte und sagte: ›Ich will ihn betören.‹ Der HERR fragte ihn: ›Auf welche Weise?‹');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 22, 'Da antwortete er: ›Ich will hingehen und zum Lügengeist im Munde aller seiner Propheten werden.‹ Da sagte der HERR: ›Du sollst ihn betören, und es wird dir auch gelingen: gehe hin und mache es so.‹');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 23, 'Nun denn, siehe, der HERR hat allen diesen deinen Propheten einen Lügengeist in den Mund gelegt; denn der HERR hat Unglück für dich beschlossen.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 24, 'Da trat Zedekia, der Sohn Kenaanas, auf Micha zu und gab ihm einen Backenstreich mit den Worten: »Wie? Ist etwa der Geist des HERRN von mir gewichen, um mit dir zu reden?«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 25, 'Micha entgegnete: »Du wirst es an jenem Tage erfahren, an dem du dich aus einem Gemach in das andere begeben wirst, um dich zu verstecken.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 26, 'Hierauf befahl der König von Israel (dem Kammerherrn): »Nimm Micha fest und führe ihn zu dem Stadthauptmann Amon und zu dem königlichen Prinzen Joas zurück');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 27, 'und melde dort: ›So hat der König befohlen: Setzt diesen Menschen ins Gefängnis und erhaltet ihn notdürftig mit Brot und Wasser am Leben, bis ich wohlbehalten heimkehre!‹«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 28, 'Micha antwortete: »Wenn du wirklich wohlbehalten heimkehrst, dann hat der HERR nicht in mir geredet.« Er fügte dann noch hinzu: »Hört dies, ihr Völker alle!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 29, 'Als hierauf der König von Israel und der König Josaphat von Juda gegen Ramoth in Gilead zu Felde gezogen waren,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 30, 'sagte der König von Israel zu Josaphat: »Ich will mich verkleiden und so in die Schlacht gehen; du aber magst deine gewöhnliche Kleidung anbehalten.« So nahm denn der König von Israel verkleidet an der Schlacht teil.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 31, 'Der König von Syrien hatte aber den zweiunddreißig Befehlshabern seiner Kriegswagen den bestimmten Befehl erteilt: »Ihr sollt niemand angreifen, er sei gering oder vornehm, sondern nur den König von Israel!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 32, 'Als nun die Befehlshaber der Kriegswagen Josaphat zu Gesicht bekamen, dachten sie, daß es gewiß der König von Israel sei, und wandten sich gegen ihn, um ihn anzugreifen. Da erhob Josaphat ein Geschrei;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 33, 'und sobald die Befehlshaber der Wagen erkannt hatten, daß er nicht der König von Israel sei, wandten sie sich von ihm ab.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 34, 'Ein Mann aber spannte seinen Bogen aufs Geratewohl und traf den König von Israel zwischen dem Ringelgurt und dem Panzer. Da befahl er seinem Wagenlenker: »Wende um und bringe mich vom Schlachtfeld weg, denn ich bin verwundet!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 35, 'Da aber der Kampf an jenem Tage immer heftiger wurde, blieb der König dann doch den Syrern gegenüber aufrecht im Wagen stehen, bis er am Abend starb; das Blut war aus der Schußwunde ins Innere des Wagens geflossen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 36, 'Da erscholl gegen Sonnenuntergang der laute Ruf durch das Lager: »Jeder (kehre heim) in seine Stadt und jeder in sein Land! Denn der König ist tot!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 37, 'Als man dann nach Samaria gekommen war, begruben sie den König in Samaria;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 38, 'und als man den Wagen am Teich von Samaria abspülte, leckten die Hunde sein Blut [und die Dirnen wuschen sich damit], wie der HERR es zuvor angekündigt hatte.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 39, 'Die übrige Geschichte Ahabs aber sowie alle seine Taten und das Elfenbeinhaus, das er gebaut, und sämtliche Städte, die er befestigt hat, das findet sich bekanntlich aufgezeichnet im Buch der Denkwürdigkeiten der Könige von Israel. –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 40, 'Als Ahab sich aber zu seinen Vätern gelegt hatte, folgte ihm sein Sohn Ahasja in der Regierung nach.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 41, 'Josaphat, der Sohn Asas, wurde König über Juda im vierten Jahre der Regierung des Königs Ahab von Israel.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 42, 'Fünfunddreißig Jahre war Josaphat beim Regierungsantritt alt, und fünfundzwanzig Jahre regierte er in Jerusalem. Seine Mutter hieß Asuba und war eine Tochter Silhis.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 43, 'Er wandelte ganz auf dem Wege seines Vaters Asa, ohne davon abzuweichen, so daß er tat, was dem HERRN wohlgefiel.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 44, 'Nur der Höhendienst wurde nicht beseitigt: das Volk brachte immer noch Schlacht- und Rauchopfer auf den Höhen dar.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 45, 'Mit dem König von Israel aber lebte Josaphat in Frieden.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 46, 'Die übrige Geschichte Josaphats aber und seine tapferen Taten, die er ausgeführt, und wie er Krieg geführt hat, das findet sich bekanntlich bereits aufgezeichnet im Buche der Denkwürdigkeiten der Könige von Juda.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 47, 'Auch den Rest der Heiligtumsbuhler, der unter der Regierung seines Vaters Asa noch übriggeblieben war, schaffte er aus dem Lande weg.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 48, 'In Edom gab es damals keinen König; als König galt der (judäische) Statthalter.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 49, 'Josaphat hatte Tharsisschiffe bauen lassen, die nach Ophir fahren und Gold holen sollten; aber man fuhr nicht dahin, weil die Schiffe bei Ezjon-Geber scheiterten.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 50, 'Damals machte Ahasja, der Sohn Ahabs, dem Josaphat den Vorschlag: »Laß meine Leute die Fahrt zur See mit den deinigen mitmachen!«, aber Josaphat ging nicht darauf ein.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 51, 'Als Josaphat sich dann zu seinen Vätern gelegt und man ihn bei seinen Vätern in der Stadt seines Ahnherrn David begraben hatte, folgte ihm sein Sohn Joram in der Regierung nach.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 52, 'Ahasja, der Sohn Ahabs, wurde König über Israel zu Samaria im siebzehnten Jahre der Regierung des Königs Josaphat von Juda und regierte zwei Jahre über Israel.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 53, 'Er tat, was dem HERRN mißfiel, und wandelte auf dem Wege seines Vaters und seiner Mutter und auf dem Wege Jerobeams, des Sohnes Nebats, der Israel zur Sünde verführt hatte.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 54, 'Er diente dem Baal und betete ihn an und erzürnte dadurch den HERRN, den Gott Israels, ganz wie sein Vater getan hatte.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 1, 1, 'Nach dem Tode Ahabs fielen die Moabiter von Israel ab. –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 1, 2, 'Als Ahasja aber in Samaria durch das Gitterfenster in seinem Obergemach gefallen war und krank darniederlag, sandte er Boten ab mit dem Auftrag: »Geht hin und befragt Baal-Sebub, den Gott von Ekron, ob ich von dieser Krankheit genesen werde.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 1, 3, 'Der Engel des HERRN aber gebot dem Elia aus Thisbe: »Mache dich auf, gehe den Boten des Königs von Samaria entgegen und sage zu ihnen: ›Es gibt wohl keinen Gott in Israel, daß ihr hingehen müßt, um bei Baal-Sebub, dem Gott von Ekron, anzufragen?‹');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 1, 4, 'Darum hat der HERR so gesprochen: ›Von dem Lager, das du bestiegen hast, sollst du nicht wieder herunterkommen, sondern sollst unfehlbar sterben!‹« Darauf ging Elia von dannen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 1, 5, 'Als nun die Boten zum König zurückkehrten, fragte er sie: »Warum kommt ihr denn zurück?«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 1, 6, 'Sie antworteten ihm: »Ein Mann ist uns entgegengekommen, der zu uns sagte: ›Kehrt wieder zum König zurück, der euch entsandt hat, und sagt zu ihm: So hat der HERR gesprochen: Es gibt wohl keinen Gott in Israel, daß du hinsenden mußt, um bei Baal-Sebub, dem Gott von Ekron, anzufragen? Darum sollst du von dem Lager, das du bestiegen hast, nicht wieder herunterkommen, sondern sollst unfehlbar sterben.‹«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 1, 7, 'Da fragte er sie: »Wie sah der Mann aus, der euch entgegengekommen ist und diese Worte an euch gerichtet hat?«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 1, 8, 'Sie antworteten ihm: »Der Mann trug ein haariges Fell als Mantel und hatte sich einen ledernen Gürtel um die Hüften gebunden.« Da rief Ahasja aus: »Das ist Elia aus Thisbe!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 1, 9, 'Hierauf schickte er einen Hauptmann über eine Fünfzigschaft mit seinen fünfzig Leuten nach ihm aus. Als dieser zu ihm hinaufkam – Elia saß nämlich oben auf einem Berge –, sagte er zu ihm: »Mann Gottes, der König befiehlt dir herabzukommen!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 1, 10, 'Aber Elia antwortete dem Hauptmann: »Wenn ich denn ein Gottesmann bin, so falle Feuer vom Himmel herab und verzehre dich samt deinen fünfzig Leuten!« Da fiel Feuer vom Himmel herab und verzehrte ihn samt seinen fünfzig Leuten.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 1, 11, 'Hierauf sandte der König nochmals einen andern Hauptmann mit seinen fünfzig Leuten nach ihm aus; der redete ihn mit den Worten an: »Mann Gottes, so hat der König befohlen: ›Komm sofort herab!‹«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 1, 12, 'Aber Elia antwortete ihnen: »Wenn ich ein Gottesmann bin, so falle Feuer vom Himmel herab und verzehre dich samt deinen fünfzig Leuten!« Da fiel Feuer Gottes vom Himmel herab und verzehrte ihn samt seinen fünfzig Leuten.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 1, 13, 'Hierauf sandte der König nochmals einen dritten Hauptmann mit seinen fünfzig Leuten ab. Als dieser dritte Hauptmann zu ihm hinaufkam, fiel er vor Elia auf die Knie und flehte ihn an mit den Worten: »Mann Gottes, laß doch mein Leben und das Leben deiner Knechte, dieser Fünfzig, etwas bei dir gelten!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 1, 14, 'Du weißt: Feuer ist vom Himmel herabgefallen und hat die beiden ersten Hauptleute samt ihren fünfzig Leuten verzehrt; nun aber laß doch meinem Leben Schonung widerfahren!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 1, 15, 'Da sagte der Engel des HERRN zu Elia: »Gehe mit ihm hinab, fürchte dich nicht vor jenem!« Da stand Elia auf und ging mit ihm zum König hinab.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 1, 16, 'Zu diesem sagte er dann: »So hat der HERR gesprochen: ›Weil du Boten abgesandt hast, um Baal-Sebub, den Gott von Ekron, zu befragen – als ob es keinen Gott in Israel gäbe, dessen Ausspruch man einholen könnte –, darum wirst du von dem Lager, das du bestiegen hast, nicht wieder herunterkommen, sondern wirst unfehlbar sterben!‹«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 1, 17, 'So starb er denn, wie der HERR es durch den Mund Elias hatte verkündigen lassen; und sein Bruder Joram folgte ihm in der Regierung nach im zweiten Jahre der Regierung Jorams, des Sohnes Josaphats, des Königs von Juda; denn er hatte keinen Sohn hinterlassen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 1, 18, 'Die übrige Geschichte Ahasjas aber und alles, was er unternommen hat, das findet sich bekanntlich aufgezeichnet im Buch der Denkwürdigkeiten der Könige von Israel.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 2, 1, 'Als dann der HERR den Elia im Wettersturm zum Himmel auffahren lassen wollte, ging Elia mit Elisa aus Gilgal weg.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 2, 2, 'Da sagte Elia zu Elisa: »Bleibe doch hier! Denn der HERR hat mich nach Bethel gesandt.« Doch Elisa erwiderte: »So wahr der HERR lebt und so wahr du selbst lebst, ich verlasse dich nicht!« Als sie nun nach Bethel hinabwanderten,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 2, 3, 'kamen die Prophetenjünger, die in Bethel wohnten, zu Elisa hinaus und sagten zu ihm: »Weißt du wohl, daß Gott der HERR heute deinen Herrn über deinem Haupt entführen wird?« Er antwortete: »Auch ich weiß es: schweigt still!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 2, 4, 'Da sagte Elia zu ihm: »Elisa, bleibe doch hier! Denn der HERR hat mich nach Jericho gesandt.« Doch er entgegnete: »So wahr der HERR lebt und so wahr du selbst lebst, ich verlasse dich nicht!« Als sie nun nach Jericho gekommen waren,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 2, 5, 'traten die Prophetenjünger, die in Jericho wohnten, an Elisa heran und sagten zu ihm: »Weißt du wohl, daß Gott der HERR heute deinen Herrn über deinem Haupt entführen wird?« Er antwortete: »Auch ich weiß es: schweigt still!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 2, 6, 'Darauf sagte Elia zu ihm: »Bleibe doch hier! Denn der HERR hat mich an den Jordan gesandt.« Doch er entgegnete: »So wahr der HERR lebt und so wahr du selbst lebst, ich verlasse dich nicht!« So gingen sie denn beide miteinander weiter.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 2, 7, 'Auch fünfzig Mann von den Prophetenjüngern gingen mit, blieben aber abseits in einiger Entfernung stehen, während die beiden an den Jordan traten.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 2, 8, 'Da nahm Elia seinen Mantel, wickelte ihn zusammen und schlug damit auf das Wasser; da zerteilte es sich nach beiden Seiten hin, so daß sie beide trockenen Fußes hindurchgehen konnten.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 2, 9, 'Als sie nun drüben angekommen waren, sagte Elia zu Elisa: »Erbitte dir etwas, was ich dir tun soll, ehe ich von dir hinweggenommen werde.« Elisa antwortete: »Möchte mir doch ein doppelter Anteil von deinem Geist zufallen!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 2, 10, 'Elia entgegnete: »Du hast eine schwer zu erfüllende Bitte ausgesprochen. Wenn du mit ansehen darfst, wie ich von dir entrückt werde, so wird deine Bitte erfüllt werden, sonst nicht!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 2, 11, 'Während sie dann im Gespräch miteinander immer weiter gingen, erschien plötzlich ein feuriger Wagen mit feurigen Rossen und trennte beide voneinander; und Elia fuhr im Wettersturm zum Himmel empor.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 2, 12, 'Als Elisa das sah, rief er laut: »Mein Vater, mein Vater! Du Wagen Israels und seine Reiter!« Als er ihn dann nicht mehr sah, faßte er seine Kleider und zerriß sie in zwei Stücke.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 2, 13, 'Hierauf hob er den Mantel auf, der dem Elia entfallen war, kehrte um und trat an das Ufer des Jordans;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 2, 14, 'hier nahm er den Mantel Elias, der ihm entfallen war, schlug damit auf das Wasser und rief aus: »Wo ist der HERR, der Gott Elias?« Als auch er so auf das Wasser geschlagen hatte, zerteilte es sich nach beiden Seiten hin, so daß Elisa hindurchgehen konnte.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 2, 15, 'Als die Prophetenjünger, die aus Jericho waren, das von drüben her sahen, riefen sie aus: »Der Geist Elias ruht auf Elisa!« Sie gingen ihm dann entgegen, verneigten sich vor ihm bis zur Erde');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 2, 16, 'und sagten zu ihm: »Siehe, es befinden sich hier bei deinen Knechten fünfzig rüstige Männer; die sollen hingehen und deinen Herrn suchen, ob ihn nicht etwa der Geist des HERRN entführt und ihn auf irgendeinen Berg oder in irgendein Tal entrückt hat.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 2, 17, 'Aber er erwiderte: »Ihr braucht sie nicht auszuschicken!« Als sie jedoch bis aufs äußerste in ihn drangen, erklärte er schließlich: »Nun, so laßt sie abgehen!« Da schickten sie die fünfzig Männer aus, die suchten drei Tage lang, fanden ihn aber nicht.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 2, 18, 'Als sie dann zu ihm zurückkehrten, während er noch in Jericho weilte, sagte er zu ihnen: »Habe ich euch nicht gesagt, ihr möchtet nicht hingehen?«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 2, 19, 'Die Einwohner der Stadt (Jericho) aber sagten zu Elisa: »In unserer Stadt ist gewiß gut wohnen, wie du, Herr, selbst siehst; aber das Wasser ist ungesund, und die Gegend verursacht Fehlgeburten.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 2, 20, 'Da antwortete er: »Bringt mir eine neue Schüssel und tut Salz hinein.« Als man sie ihm gebracht hatte,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 2, 21, 'ging er an die Wasserquelle vor die Stadt hinaus, warf das Salz hinein und sagte: »So hat der HERR gesprochen: ›Ich habe dieses Wasser gesund gemacht; es soll hinfort weder Tod noch Fehlgeburt daher kommen!‹«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 2, 22, 'Da wurde das Wasser gesund bis auf den heutigen Tag infolge des Wortes, das Elisa ausgesprochen hatte.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 2, 23, 'Von dort ging er dann nach Bethel zurück; und als er so auf dem Wege hinaufging, kamen kleine Jungen aus dem Ort heraus, die ihn verspotteten, indem sie ihm zuriefen: »Komm herauf, Kahlkopf! Komm herauf, Kahlkopf!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 2, 24, 'Da wandte er sich um, und als er sie sah, verwünschte er sie im Namen des HERRN. Da kamen zwei Bären aus dem Walde heraus und zerrissen zweiundvierzig von den Knaben.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 2, 25, 'Von dort begab er sich nach dem Berge Karmel und kehrte von da nach Samaria zurück.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 3, 1, 'Joram, der Sohn Ahabs, wurde König über Israel zu Samaria im achtzehnten Jahre der Regierung des Königs Josaphat von Juda und regierte zwölf Jahre.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 3, 2, 'Er tat, was dem HERRN mißfiel, jedoch nicht so schlimm wie sein Vater und seine Mutter; denn er entfernte die Götzensäule Baals, die sein Vater hatte aufstellen lassen,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 3, 3, 'aber an dem sündhaften Stierdienst Jerobeams, des Sohnes Nebats, zu dem er Israel verführt hatte, hielt er fest und ließ nicht davon ab.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 3, 4, 'Da Mesa, der König der Moabiter, Schafzüchter war, hatte er dem König von Israel hunderttausend Lämmer und die Wolle von hunderttausend Widdern als regelmäßige Abgabe zu entrichten.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 3, 5, 'Aber nach Ahabs Tode fiel der König der Moabiter vom König von Israel ab.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 3, 6, 'Da zog der König Joram zu jener Zeit aus Samaria aus und bot ganz Israel zum Kriege auf;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 3, 7, 'gleichzeitig schickte er eine Gesandtschaft an den König Josaphat von Juda und ließ ihm sagen: »Der König der Moabiter ist von mir abgefallen: willst du nicht mit mir gegen die Moabiter zu Felde ziehen?« Er antwortete: »Ja, ich will mitziehen; ich will sein wie du: mein Volk wie dein Volk, meine Rosse wie deine Rosse!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 3, 8, 'Als er dann fragte: »Welchen Weg wollen wir einschlagen?«, erwiderte jener: »Den Weg durch die Steppe von Edom.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 3, 9, 'So zog denn der König von Israel mit dem König von Juda und dem König der Edomiter aus. Als sie aber sieben Tagemärsche zur Umgehung zurückgelegt hatten, fehlte es dem Heere und dem Vieh, das mit ihnen zog, an Wasser.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 3, 10, 'Da rief der König von Israel aus: »Wehe! So hat also der HERR diese drei Könige zum Kriege aufgeboten, um sie in die Hand der Moabiter fallen zu lassen!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 3, 11, 'Nun fragte Josaphat: »Ist denn hier kein Prophet des HERRN, durch den wir den HERRN befragen können?« Da antwortete einer von den Hofleuten des Königs von Israel: »Hier ist Elisa, der Sohn Saphats, der als Diener bei Elia gelebt hat.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 3, 12, 'Josaphat sagte: »Ja wirklich, bei dem ist das Wort des HERRN zu finden!« Als sich nun der König von Israel und Josaphat und der König der Edomiter zu ihm hinabbegeben hatten,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 3, 13, 'sagte Elisa zum König von Israel: »Was habe ich mit dir zu schaffen? Wende dich doch an die Propheten deines Vaters und an die Propheten deiner Mutter!« Aber der König von Israel entgegnete ihm: »Nicht doch! Hat etwa der HERR diese drei Könige zum Krieg aufgeboten, um sie in die Hand der Moabiter fallen zu lassen?«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 3, 14, 'Da sagte Elisa: »So wahr der HERR der Heerscharen lebt, in dessen Dienst ich stehe! Wenn ich nicht auf den König Josaphat von Juda Rücksicht nähme, so würde ich dich wahrlich nicht beachten und dich keines Blickes würdigen!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 3, 15, 'Nun aber schafft mir einen Saitenspieler her!« Als dann der Saitenspieler die Saiten rührte, kam die Hand des HERRN über ihn,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 3, 16, 'und er sagte: »So hat der HERR gesprochen: ›Macht in diesem Tal Grube an Grube!‹');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 3, 17, 'Denn so hat der HERR gesprochen: ›Ihr werdet keinen Wind wahrnehmen und keinen Regen sehen, und doch wird sich dieses Tal mit Wasser füllen, so daß ihr samt eurem Heer und eurem Vieh trinken könnt.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 3, 18, 'Aber dies genügt dem HERRN noch nicht: er wird euch auch noch die Moabiter in die Hände liefern,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 3, 19, 'so daß ihr alle festen Städte erobern, alle Fruchtbäume fällen, alle Wasserquellen verschütten und alles gute Ackerland mit Steinen verderben werdet.‹«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 3, 20, 'Und wirklich, am folgenden Morgen zu der Zeit, wo man das Speisopfer darbringt, kam plötzlich Wasser von Edom her geflossen, so daß die ganze Gegend überschwemmt wurde.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 3, 21, 'Als nun das ganze Volk der Moabiter hörte, daß die Könige herangezogen waren, um sie zu bekriegen, wurde alles, was die Waffen tragen konnte, aufgeboten, ja sogar die noch nicht Waffenfähigen, und sie stellten sich an der Grenze auf.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 3, 22, 'Als aber am folgenden Morgen früh die Sonne beim Aufgang über das Wasser hin strahlte, erschien den Moabitern das Wasser drüben rot wie Blut,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 3, 23, 'so daß sie ausriefen: »Das ist Blut! Gewiß sind die Könige mit dem Schwert aneinandergeraten und haben ein Blutbad unter sich angerichtet: jetzt an die Beute, Moabiter!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 3, 24, 'Als sie aber an das israelitische Lager herankamen, machten die Israeliten einen Ausfall und schlugen die Moabiter in die Flucht, drangen dann immer weiter ins Land ein und schlugen die Moabiter aufs neue.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 3, 25, 'Die Städte zerstörten sie, auf alles gute Ackerland warfen sie ein jeder seinen Stein, so daß es ganz damit bedeckt war, alle Wasserquellen verschütteten sie und hieben alle Fruchtbäume um, bis nichts mehr übrig war als (die Stadt) Kir-Hareseth mit ihrer festen Steinmauer. Als dann die Schleuderer die Stadt umzingelten und beschossen');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 3, 26, 'und der König der Moabiter einsah, daß er dem Angriff nicht gewachsen sei, nahm er siebenhundert mit Schwertern bewaffnete Krieger mit sich, um sich zum König der Edomiter durchzuschlagen; aber es gelang ihnen nicht.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 3, 27, 'Da nahm er seinen erstgeborenen Sohn, der ihm dereinst in der Regierung nachfolgen sollte, und brachte ihn auf der Mauer als Brandopfer dar. Da kam ein gewaltiger Zorn über Israel, so daß sie die Belagerung aufhoben und in ihr Land zurückkehrten.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 1, 'Eine Frau von den Ehefrauen der Prophetenjünger flehte einst Elisa laut mit den Worten an: »Mein Mann, dein Knecht, ist gestorben, und du weißt selbst, daß dein Knecht ein gottesfürchtiger Mann gewesen ist. Nun ist der Gläubiger gekommen und will sich meine beiden Söhne zu Sklaven nehmen!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 2, 'Elisa antwortete ihr: »Was soll ich für dich tun? Sage mir, was du im Hause hast!« Sie erwiderte: »Deine Magd hat gar nichts mehr im Hause als nur einen Krug mit etwas Öl.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 3, 'Da sagte er: »Gehe hin, borge dir Gefäße von allen deinen Nachbarn draußen, leere Gefäße, aber nimm nicht zu wenige;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 4, 'hierauf gehe heim, schließe die Tür hinter dir und deinen beiden Söhnen zu und gieße in alle jene Gefäße ein; und wenn eins voll ist, so setze es beiseite.««');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 5, 'Sie ging dann von ihm weg und schloß die Tür hinter sich und ihren Söhnen zu; diese reichten ihr (die Gefäße), und sie goß sie voll.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 6, 'Als nun die Gefäße gefüllt waren, sagte sie zu ihrem Sohn: »Reiche mir noch ein Gefäß!«, aber er antwortete ihr: »Es ist kein Gefäß mehr da«; da hörte das Öl auf zu fließen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 7, 'Als sie nun zu dem Gottesmann kam und es ihm berichtete, sagte er: »Gehe hin, verkaufe das Öl und bezahle deine Schuld; von dem, was dir dann noch übrigbleibt, kannst du mit deinen Söhnen leben.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 8, 'Eines Tages ging Elisa nach Sunem hinüber; dort wohnte eine reiche Frau, die ihn nötigte, bei ihr zu essen. Sooft er nun später an dem Ort vorüberkam, kehrte er dort zum Essen ein.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 9, 'Da sagte sie zu ihrem Manne: »Sieh doch, ich habe erkannt, daß dieser ein heiliger Gottesmann ist, der immer bei uns einkehrt;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 10, 'wir wollen ihm doch ein kleines Zimmer oben im Hause aufmauern lassen und ihm ein Bett, einen Tisch, einen Stuhl und einen Leuchter hineinstellen; dann kann er dort ein Unterkommen finden, sooft er zu uns kommt.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 11, 'Als er nun eines Tages wieder hinkam, kehrte er in dem Oberstübchen ein und schlief darin.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 12, 'Nachher befahl er seinem Diener Gehasi: »Rufe mir unsere Sunamitin!« Als er sie nun gerufen hatte und sie vor ihn getreten war,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 13, 'sagte Elisa zu dem Diener: »Sage ihr: ›Du hast dir unsertwegen alle diese Unruhe gemacht: was kann man für dich tun? Brauchst du Fürsprache beim König oder Feldhauptmann?‹« Sie antwortete: »Ich wohne hier ja sicher inmitten meines Volkes.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 14, 'Als er nun wieder fragte: »Was könnte man wohl für sie tun?«, antwortete Gehasi: »Ach, sie ist kinderlos, und ihr Mann ist schon alt.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 15, 'Darauf sagte Elisa: »Rufe sie her!« Als er sie nun gerufen hatte und sie in die Tür getreten war,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 16, 'sagte er: »Übers Jahr um diese Zeit wirst du einen Sohn herzen!« Aber sie entgegnete: »Ach nein, mein Herr, du Mann Gottes: täusche doch deine Magd nicht!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 17, 'Die Frau aber wurde wirklich guter Hoffnung und gebar um dieselbe Zeit im nächsten Jahre einen Sohn, wie Elisa ihr verheißen hatte.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 18, 'Als nun der Knabe herangewachsen war, begab es sich eines Tages, daß er zu seinem Vater zu den Schnittern hinausging.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 19, 'Da klagte er (plötzlich) seinem Vater: »Mein Kopf, mein Kopf!« Jener befahl einem Knecht: »Trage ihn heim zu seiner Mutter!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 20, 'Als dieser ihn auf den Arm genommen und zu seiner Mutter gebracht hatte, saß er bis zum Mittag auf ihrem Schoß; dann starb er.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 21, 'Da stieg sie hinauf, legte ihn auf das Bett des Gottesmannes, schloß hinter ihm zu und ging hinaus;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 22, 'dann ließ sie ihren Mann rufen und sagte zu ihm: »Schicke mir doch einen von den Knechten und eine Eselin; ich will zu dem Gottesmann eilen, komme aber schnell wieder zurück.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 23, 'Er entgegnete: »Warum willst du gerade heute zu ihm gehen? Es ist doch weder Neumond noch Sabbat!« Doch sie erwiderte: »Das schadet nichts.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 24, 'Hierauf ließ sie die Eselin satteln und befahl ihrem Knecht: »Treibe das Tier immerfort an und mache mir keinen Aufenthalt beim Reiten, es sei denn, daß ich es dir sage!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 25, 'So machte sie sich auf den Weg und gelangte zu dem Gottesmann auf den Berg Karmel. Als nun der Gottesmann sie in einiger Entfernung erblickte, sagte er zu seinem Diener Gehasi: »Da ist ja unsere Sunamitin!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 26, 'Wohlan, laufe ihr entgegen und frage sie, ob es ihr sowie ihrem Mann und dem Knaben gutgehe.« Sie antwortete: »Ja.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 27, 'Als sie aber zu dem Gottesmann auf den Berg gekommen war, umfaßte sie seine Füße; da trat Gehasi hinzu, um sie wegzustoßen; aber der Gottesmann sagte: »Laß sie! Denn sie ist tief betrübt, und Gott hat es mir verborgen und mir’s nicht geoffenbart.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 28, 'Sie sagte dann: »Bin ich es gewesen, die meinen Herrn um einen Sohn gebeten hat? Habe ich nicht vielmehr gesagt, du möchtest mich nicht täuschen?«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 29, 'Da befahl er Gehasi: »Gürte dir die Lenden, nimm meinen Stab in deine Hand und gehe hin! Wenn du jemand triffst, so grüße ihn nicht, und wenn dich jemand grüßt, so danke ihm nicht! Lege dann dem Knaben meinen Stab auf das Gesicht!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 30, 'Aber die Mutter des Knaben rief: »So wahr der HERR lebt und so wahr du selbst lebst: ich lasse nicht von dir!« Da machte er sich auf und folgte ihr.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 31, 'Gehasi war ihnen unterdessen vorausgeeilt und hatte dem Knaben den Stab auf das Gesicht gelegt, aber kein Laut und kein Lebenszeichen war erfolgt. Da kehrte er um, (seinem Herrn) entgegen, und berichtete ihm, der Knabe sei nicht aufgewacht;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 32, 'und als Elisa dann in das Haus kam, fand er den Knaben tot auf seinem eigenen Bette liegen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 33, 'Nun ging er hinein, schloß die Tür hinter sich zu und betete zum HERRN;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 34, 'dann stieg er auf das Bett, streckte sich über den Knaben hin und legte seinen Mund auf dessen Mund, seine Augen auf dessen Augen und seine Hände auf die Hände jenes. Als er sich so über ihn hinstreckte, erwärmte sich der Leib des Knaben.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 35, 'Dann stand er wieder auf und ging im Zimmer hin und her, stieg dann wieder hinauf und streckte sich über ihn hin. Da nieste der Knabe siebenmal und schlug die Augen hell auf.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 36, 'Nun rief er Gehasi und befahl ihm: »Rufe unsere Sunamitin!« Der rief sie herbei, und als sie zu ihm hereinkam, sagte er: »Nimm da deinen Sohn!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 37, 'Da trat sie heran, fiel ihm zu Füßen, verneigte sich tief bis zur Erde, nahm ihren Sohn auf den Arm und ging hinaus.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 38, 'Elisa kehrte dann nach Gilgal zurück, während eine Hungersnot im Lande herrschte. Als nun die Prophetenjünger vor ihm saßen, gab er seinem Diener den Auftrag, den größten Kochtopf aufs Feuer zu setzen und ein Gericht für die Prophetenjünger zu kochen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 39, 'Da ging einer von ihnen auf das Feld hinaus, um Kräuter zu sammeln, und als er ein wildes Schlinggewächs fand, pflückte er davon wilde Gurken ab, seinen ganzen Mantel voll; dann kehrte er heim und zerschnitt sie in den Kochtopf; denn er kannte sie nicht.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 40, 'Als man sie dann zum Essen für die Männer ausgeschüttet hatte und diese von dem Gericht aßen, schrien sie laut auf und riefen: »Der Tod ist im Topf, Mann Gottes!«, und sie konnten es nicht essen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 41, 'Da sagte er: »So bringt Mehl her!« Er warf es in den Topf und sagte dann: »Fülle es jetzt für die Leute aus, damit sie es essen.« Da war nichts Schädliches mehr im Topf.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 42, 'Hierauf kam ein Mann aus Baal-Salisa und brachte dem Gottesmann Erstlingsbrote, nämlich zwanzig Gerstenbrote, dazu Schrotkorn in seinem Sack. Da befahl er: »Gib es den Leuten zu essen!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 43, 'Sein Diener aber entgegnete: »Wie kann ich dies hundert Männern vorsetzen?« Doch er befahl: »Gib es den Leuten zu essen! Denn so hat der HERR gesprochen: ›Man wird essen und noch übriglassen‹«.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 44, 'Als er es ihnen nun vorsetzte, aßen sie und ließen noch davon übrig, wie der HERR es verheißen hatte.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 5, 1, 'Naeman, der Feldhauptmann des Königs von Syrien, galt bei seinem Herrn viel und stand in hohem Ansehen; denn durch ihn hatte Gott der HERR den Syrern den Sieg verliehen; aber dieser Mann, ein großer Kriegsheld, wurde aussätzig.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 5, 2, 'Nun hatten die Syrer einst auf einem Streifzuge ein junges Mädchen aus dem Lande Israel gefangen weggeführt; die war dann bei Naemans Gattin Dienerin geworden');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 5, 3, 'und sagte (eines Tages) zu ihrer Herrin: »Ach wenn mein Herr sich doch an den Propheten zu Samaria wendete! Dann würde der ihn von seinem Aussatz befreien.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 5, 4, 'Da ging Naeman zu seinem Herrn und teilte ihm mit: »So und so hat das Mädchen berichtet, das aus dem Lande Israel stammt.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 5, 5, 'Darauf entgegnete der König von Syrien: »Nun gut, ziehe hin! Ich will dir ein Schreiben an den König von Israel mitgeben.« Da machte er sich auf den Weg, nahm zehn Talente Silber, sechstausend Schekel Gold und zehn Festgewänder mit');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 5, 6, 'und überreichte dem König von Israel das Schreiben, das so lautete: »Wenn dieses Schreiben an dich gelangt, so wisse: ich habe meinen Diener Naeman zu dir gesandt, damit du ihn von seinem Aussatz befreist.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 5, 7, 'Als der König von Israel das Schreiben gelesen hatte, zerriß er seine Kleider und rief aus: »Bin ich etwa ein Gott, daß ich töten und lebendig machen kann?! Dieser verlangt ja von mir, daß ich einen Menschen von seinem Aussatz befreie! Da seht ihr nun deutlich, daß er nur einen Vorwand zum Streit mit mir sucht!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 5, 8, 'Als nun der Gottesmann Elisa erfuhr, daß der König von Israel seine Kleider zerrissen habe, sandte er zum König und ließ ihm sagen: »Warum hast du deine Kleider zerrissen? Laß ihn doch zu mir kommen: er soll erfahren, daß es wirklich noch einen Propheten in Israel gibt!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 5, 9, 'So kam denn Naeman mit seinen Rossen und seinem Wagen und hielt bei Elisa vor der Haustür an.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 5, 10, 'Da ließ ihm Elisa durch einen Boten sagen: »Gehe hin und bade dich siebenmal im Jordan, dann wird dir dein Leib wieder gesund werden, und du wirst rein sein.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 5, 11, 'Darüber wurde Naeman unwillig und fuhr auf seinem Wagen weg mit den Worten: »Ich hatte als sicher angenommen, er würde selbst zu mir herauskommen und vor mich hintreten und den Namen des HERRN, seines Gottes, anrufen und seine Hand nach der heiligen Stätte hin schwingen und so den Aussatz wegschaffen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 5, 12, 'Sind nicht der Amana und der Pharphar, die Flüsse von Damaskus, besser als alle Wasser in Israel? Kann ich mich nicht in ihnen baden, um rein zu werden?« Damit wandte er sich um und entfernte sich voller Zorn.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 5, 13, 'Da traten seine Diener an ihn heran und redeten ihm mit den Worten zu: »Mein Vater, wenn der Prophet etwas Schwieriges von dir verlangt hätte, so hättest du es sicherlich getan; wieviel mehr also jetzt, da er nur zu dir gesagt hat: ›Bade dich, so wirst du rein sein!‹«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 5, 14, 'Als er sich nun an den Jordan hatte hinabfahren lassen und sich nach der Weisung des Gottesmannes siebenmal darin untergetaucht hatte, wurde sein Leib wieder so rein wie der Leib eines kleinen Kindes.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 5, 15, 'Er kehrte nun mit seinem ganzen Gefolge zu dem Gottesmann zurück, trat nach seiner Ankunft vor ihn hin und sagte: »Wisse wohl: jetzt habe ich erkannt, daß es auf der ganzen Erde keinen Gott gibt als nur in Israel. Nimm nun doch ein Geschenk von deinem Diener an!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 5, 16, 'Doch Elisa entgegnete: »So wahr der HERR lebt, in dessen Dienst ich stehe: ich nehme nichts an!« Und wie er ihn auch zur Annahme drängte, er blieb doch bei seiner Weigerung.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 5, 17, 'Da sagte Naeman: »Wenn denn nicht, so möge doch deinem Diener wenigstens eine Last Erde, soviel ein Paar Maultiere tragen können, mitgegeben werden; denn dein Diener wird fortan keinem andern Gott Brand- und Schlachtopfer darbringen als dem HERRN allein.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 5, 18, 'Nur in diesem einen Stück wolle der HERR mit deinem Diener Nachsicht haben: Wenn mein königlicher Herr in den Tempel Rimmons geht, um daselbst anzubeten, und sich dabei auf meinen Arm stützt und sich im Tempel Rimmons niederwirft und ich mich dann ebenfalls im Tempel Rimmons niederwerfe, so möge Gott der HERR in diesem einen Fall deinem Diener Verzeihung zuteil werden lassen!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 5, 19, 'Er erwiderte ihm: »Ziehe hin in Frieden!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 5, 20, 'Als (Naeman) aber eine Strecke Weges von ihm weggezogen war, dachte Gehasi, der Diener des Gottesmannes Elisa: »Da hat nun mein Herr wahrhaftig diesen Syrer Naeman geschont, statt etwas von dem anzunehmen, was jener mitgebracht hatte! So wahr der HERR lebt: ich laufe hinter ihm her und lasse mir etwas von ihm geben!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 5, 21, 'So eilte denn Gehasi dem Naeman nach. Als dieser nun sah, daß einer hinter ihm herlief, sprang er vom Wagen herab, ging ihm entgegen und fragte: »Geht es dir wohl?«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 5, 22, 'Er antwortete: »Ja! Mein Herr schickt mich und läßt dir sagen: ›Jetzt eben sind vom Gebirge Ephraim zwei junge Leute von den Prophetenjüngern zu mir gekommen; gib mir doch für sie ein Talent Silber und zwei Festkleider!‹«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 5, 23, 'Naeman erwiderte: »Tu mir den Gefallen und nimm zwei Talente!« Er bat ihn dann dringend und ließ zwei Talente Silber in zwei Beutel schnüren, tat dazu zwei Festkleider und ließ sie durch zwei seiner Diener vor ihm her tragen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 5, 24, 'Als er aber bei dem Hügel ankam, nahm er sie ihnen ab, brachte sie im Hause unter und entließ dann die Leute, die nun zurückkehrten.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 5, 25, 'Als er aber hineingegangen und vor seinen Herrn getreten war, fragte ihn Elisa: »Woher kommst du, Gehasi?« Er antwortete: »Dein Knecht ist überhaupt nicht ausgegangen.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 5, 26, 'Da sagte (Elisa) zu ihm: »Bin ich nicht im Geist mit dir gegangen, als sich jemand von seinem Wagen aus nach dir umwandte? Ist es jetzt an der Zeit, Geld und Kleider anzunehmen und Ölbaumgärten und Weinberge, Kleinvieh und Rinder, Knechte und Mägde dafür (zu erwerben)?');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 5, 27, 'So soll denn der Aussatz Naemans an dir und deinen Nachkommen ewig haften!« Da ging (Gehasi) von ihm weg, vom Aussatz weiß wie Schnee.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 6, 1, 'Die Prophetenjünger sagten einst zu Elisa: »Sieh doch, der Raum, in dem wir hier beim Unterricht vor dir sitzen, ist zu eng für uns.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 6, 2, 'Wir wollen doch an den Jordan gehen und von dort ein jeder einen Balken holen, damit wir uns hier einen Raum herrichten, wo wir wohnen können.« Er antwortete: »Ja, geht hin!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 6, 3, 'Da bat einer: »Sei doch so freundlich, deine Knechte zu begleiten!« Er erwiderte: »Gut, ich will mitgehen.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 6, 4, 'So ging er denn mit ihnen, und als sie an den Jordan gekommen waren, hieben sie dort Bäume um.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 6, 5, 'Da begab es sich, daß einem, der einen Stamm fällte, das eiserne Beilblatt ins Wasser fiel; und er rief laut: »O weh, Herr! Und es ist noch dazu entlehnt!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 6, 6, 'Der Mann Gottes aber fragte: »Wohin ist es gefallen?« Als er ihm nun die Stelle gezeigt hatte, schnitt (Elisa) ein Stück Holz zurecht, warf es dorthin und brachte dadurch das Eisen zum Schwimmen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 6, 7, 'Dann forderte er ihn auf: »Hole es dir herauf!« Der faßte mit der Hand zu und ergriff es.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 6, 8, 'Als einst der König von Syrien Krieg mit Israel führte, traf er mit seinen Heerführern die Verabredung: »An dem und dem Ort soll mein Lager stehen.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 6, 9, 'Da sandte der Gottesmann (Elisa) zum König von Israel und ließ ihm sagen: »Hüte dich, an jenem Ort vorüberzuziehen; denn dort liegen die Syrer im Hinterhalt!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 6, 10, 'Darauf sandte der König von Israel an den Ort, den ihm der Gottesmann bezeichnet und vor dem er ihn gewarnt hatte, und er nahm sich dort in acht; und das geschah mehr als einmal oder zweimal.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 6, 11, 'Da geriet der König von Syrien in Erregung über dieses Vorkommnis, so daß er seine Heerführer berief und zu ihnen sagte: »Könnt ihr mir nicht angeben, wer von den Unsrigen im Bunde mit dem König von Israel steht?«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 6, 12, 'Da antwortete einer von seinen Heerführern: »Nicht doch, mein Herr und König! Sondern Elisa, der Prophet in Israel, teilt dem König von Israel die Worte mit, die du in deinem Schlafgemach redest.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 6, 13, 'Da befahl er: »Geht hin und bringt in Erfahrung, wo er sich befindet: ich will dann hinsenden und ihn festnehmen lassen.« Als man ihm nun meldete, (Elisa) befinde sich in Dothan,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 6, 14, 'sandte er Reiter, Wagen und ein starkes Heer dorthin, die bei Nacht dort ankamen und die Stadt umzingelten.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 6, 15, 'Als nun der Diener des Gottesmannes am Morgen früh aufstand und aus dem Hause hinaustrat, lag da ein Heer um die Stadt herum mit Rossen und Wagen, so daß sein Bursche ihm zurief: »O weh, Herr! Was sollen wir machen?«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 6, 16, 'Er aber erwiderte: »Fürchte dich nicht! Denn unsere Kriegsmacht ist stärker als die Macht jener.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 6, 17, 'Hierauf betete Elisa mit den Worten: »HERR, öffne ihm doch die Augen, damit er sehe!« Da öffnete der HERR dem Diener die Augen, und als er hinblickte, sah er, wie das Gebirge rings um Elisa her voll von feurigen Rossen und Wagen war.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 6, 18, 'Als nun (die Feinde) gegen ihn heranrückten, betete Elisa zum HERRN mit den Worten: »Schlage doch diese Leute mit Blindheit!« Da schlug er sie mit Blindheit, wie Elisa es gewünscht hatte.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 6, 19, 'Elisa sagte dann zu ihnen: »Dies ist nicht der rechte Weg und dies nicht die richtige Stadt; folgt mir, so will ich euch zu dem Manne führen, den ihr sucht!« Darauf führte er sie nach Samaria.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 6, 20, 'Sobald sie aber in Samaria angekommen waren, betete Elisa: »HERR, öffne diesen Leuten nun die Augen, damit sie sehen!« Da öffnete der HERR ihnen die Augen, und sie sahen, daß sie sich mitten in Samaria befanden.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 6, 21, 'Als nun der König von Samaria sie erblickte, fragte er Elisa: »Mein Vater, soll ich sie ohne Gnade niederhauen lassen?«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 6, 22, 'Doch er antwortete: »Nein, das darfst du nicht tun! Willst du denn Leute niederhauen lassen, die du nicht mit deinem Schwert und deinem Bogen gefangengenommen hast? Setze ihnen Speise und Trank vor; wenn sie dann gegessen und getrunken haben, laß sie wieder zu ihrem Herrn ziehen.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 6, 23, 'Da ließ er ihnen ein großes Mahl zurichten, und als sie gegessen und getrunken hatten, ließ er sie zu ihrem Herrn heimziehen. Seitdem fielen keine Streifscharen der Syrer mehr ins Land Israel ein.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 6, 24, 'Später begab es sich, daß Benhadad, der König von Syrien, seine ganze Heeresmacht zusammenzog, vor Samaria rückte und es belagerte.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 6, 25, 'Da entstand eine schreckliche Hungersnot in Samaria, und es kam während der Belagerung dahin, daß ein Eselskopf achtzig Schekel Silber und ein halbes Liter Taubenmist fünf Schekel Silber kostete.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 6, 26, 'Als nun der König von Israel einmal auf der Mauer einherging, rief ihm eine Frau laut die Worte zu: »Hilf mir, mein Herr und König!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 6, 27, 'Aber er antwortete: »Wenn dir Gott der HERR nicht hilft, wie sollte ich dir helfen? Etwa mit einer Gabe von der Tenne oder von der Kelter?«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 6, 28, 'Dann fuhr der König fort: »Was willst du denn?« Da antwortete sie: »Diese Frau da hatte zu mir gesagt: ›Gib deinen Sohn her, damit wir ihn heute essen; morgen wollen wir dann meinen Sohn verzehren!‹');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 6, 29, 'So haben wir denn meinen Sohn gekocht und gegessen; als ich aber am folgenden Tage zu ihr sagte: ›Gib jetzt deinen Sohn her, damit wir ihn verzehren!‹, da hatte sie ihren Sohn versteckt.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 6, 30, 'Als der König diese Worte der Frau hörte, zerriß er seine Kleider, während er auf der Mauer einherging; und dabei nahm das Volk wahr, daß er darunter ein härenes Trauergewand auf dem bloßen Leibe trug.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 6, 31, 'Und er rief aus: »Gott soll mich jetzt und künftig strafen, wenn heute der Kopf Elisas, des Sohnes Saphats, auf seinen Schultern sitzen bleibt!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 6, 32, 'Elisa aber saß unterdessen in seiner Wohnung, und die Ältesten waren bei ihm versammelt. Da sandte (der König) einen Mann vor sich her; aber ehe noch der Bote bei Elisa eintraf, hatte dieser zu den Ältesten gesagt: »Wißt ihr wohl, daß dieser Mordgeselle hergesandt hat, um mir den Kopf abschlagen zu lassen? Gebt wohl acht! Sobald der Bote kommt, verschließt die Tür und stemmt euch mit der Tür gegen ihn! Ist nicht schon der Schall der Schritte seines Herrn hinter ihm hörbar?«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 6, 33, 'Während er noch mit ihnen redete, trat auch schon der König bei ihm ein und sagte: »Siehe, dieses Unglück ist von Gott verhängt: was soll ich da noch ferner auf Gott hoffen?«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 7, 1, 'Da sagte Elisa: »Hört das Wort des HERRN! So hat der HERR gesprochen: ›Morgen um diese Zeit wird ein Maß Feinmehl einen Schekel kosten und zwei Maß Gerste auch einen Schekel im Tor von Samaria!‹«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 7, 2, 'Da antwortete der Ritter, auf dessen Arm der König sich stützte, dem Gottesmanne folgendermaßen: »Selbst wenn Gott der HERR Fenster am Himmel aufmachte: wie könnte so etwas möglich sein?« Elisa aber entgegnete: »Wisse wohl: du wirst es mit eigenen Augen sehen, aber nicht davon essen.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 7, 3, 'Nun befanden sich vier aussätzige Männer außerhalb des Stadttores, die sagten zueinander: »Wozu wollen wir hier bleiben, bis wir sterben?');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 7, 4, 'Wenn wir uns vornehmen, in die Stadt zu gehen, so herrscht die Hungersnot in der Stadt, und wir müssen dort sterben; bleiben wir aber hier, so müssen wir auch sterben. Darum kommt, wir wollen auf das Lager der Syrer losgehen! Lassen sie uns am Leben, so bleiben wir leben; töten sie uns aber, nun, so sterben wir!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 7, 5, 'So machten sie sich denn in der Abenddämmerung auf, um sich ins Lager der Syrer zu begeben. Als sie nun an den Rand des syrischen Lagers kamen, war dort kein Mensch zu sehen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 7, 6, 'Gott der HERR hatte nämlich das syrische Heer ein Getöse von Wagen und Rossen, das Getöse einer großen Heeresmacht, hören lassen, so daß einer zum andern sagte: »Gewiß hat der König von Israel die Könige der Hethiter und die Könige von Ägypten gegen uns gedungen, daß sie uns überfallen sollen!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 7, 7, 'So hatten sie sich also noch in der Abenddämmerung aufgemacht und die Flucht ergriffen, hatten ihre Zelte, ihre Pferde und Esel, kurz das ganze Lager, wie es war, im Stich gelassen und waren davongelaufen, um ihr Leben zu retten.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 7, 8, 'Als nun jene Aussätzigen an den vorderen Eingang des Lagers gekommen waren, gingen sie in ein Zelt, aßen und tranken, nahmen Silber, Gold und Kleider daraus weg und vergruben es anderswo; dann kehrten sie um und gingen in ein anderes Zelt, plünderten es aus und vergruben den Raub.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 7, 9, 'Darauf aber sagten sie zueinander: »Wir handeln nicht recht! Der heutige Tag ist ein Tag guter Botschaft; schweigen wir aber und warten wir, bis es morgen hell ist, so trifft uns eine Verschuldung. Wir wollen also jetzt hingehen und es im königlichen Palast melden!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 7, 10, 'Sie machten sich also auf, riefen die Wache am Stadttor an und meldeten dort: »Wir sind ins Lager der Syrer gekommen; aber da war kein Mensch zu sehen und keine Menschenstimme zu hören, sondern nur die Pferde und die Esel standen dort angebunden und die Zelte, wie sie gewesen waren.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 7, 11, 'Da riefen die Torwächter es in die Stadt hinein, und man ließ es drinnen im Palast des Königs melden.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 7, 12, 'Da stand der König noch in der Nacht auf und sagte zu seinen Dienern: »Ich will euch sagen, was die Syrer gegen uns im Schilde führen! Weil sie wissen, daß wir Hunger leiden, haben sie ihr Lager verlassen, um sich irgendwo in der Gegend zu verstecken, indem sie denken: ›Wenn die aus der Stadt herausgekommen sind, wollen wir sie lebendig gefangennehmen und dann in die Stadt eindringen.‹«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 7, 13, 'Da antwortete einer von seinen Dienern: »So nehme man doch fünf von den übriggebliebenen Pferden, die hier noch übrig sind – es wird ihnen ja doch nur ergehen wie der ganzen Menge, die bereits dahin ist –: die wollen wir ausschicken, um nachzusehen.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 7, 14, 'Da nahm man zwei Gespanne Rosse, die schickte der König hinter dem syrischen Heere her mit dem Befehl: »Geht hin und seht nach!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 7, 15, 'Als diese nun hinter ihnen her bis an den Jordan zogen, stellte es sich heraus, daß der ganze Weg mit Kleidern und Waffen bedeckt war, welche die Syrer auf ihrer eiligen Flucht weggeworfen hatten. Als dann die Boten zurückgekehrt waren und dem König Bericht erstattet hatten,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 7, 16, 'zog das Volk aus der Stadt hinaus und plünderte das syrische Lager; und nun kostete ein Maß Feinmehl einen Schekel und zwei Maß Gerste auch einen Schekel, wie der HERR es angekündigt hatte.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 7, 17, 'Der König hatte aber dem Ritter, auf dessen Arm er sich stützte, die Aufsicht über den Markt übertragen; dabei zertrat ihn das Volk auf dem Markt, so daß er starb, wie der Gottesmann es vorausgesagt hatte, als der König zu ihm ins Haus gekommen war.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 7, 18, 'Als nämlich der Gottesmann zum Könige gesagt hatte: »Zwei Maß Gerste werden morgen um diese Zeit auf dem Markt von Samaria einen Schekel kosten und ein Maß Feinmehl auch einen Schekel«,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 7, 19, 'da hatte der Ritter dem Gottesmann zur Antwort gegeben: »Selbst wenn Gott, der HERR, Fenster am Himmel aufmachte: wie könnte so etwas möglich sein?« (Elisa) aber hatte entgegnet: »Wisse wohl: du wirst es mit eigenen Augen sehen, aber nicht davon essen.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 7, 20, 'Und so erging es ihm jetzt wirklich: das Volk zertrat ihn auf dem Markt, so daß er den Tod fand.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 8, 1, 'Elisa hatte aber der Frau, deren Sohn er ins Leben zurückgerufen hatte, den Rat gegeben: »Mache dich auf, wandere mit deiner Familie aus und halte dich irgendwo in der Fremde auf; denn der HERR hat eine Hungersnot verhängt, die sieben Jahre lang im Lande herrschen wird.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 8, 2, 'Da machte sich die Frau auf und folgte der Aufforderung des Gottesmannes: sie wanderte mit ihrer Familie aus und hielt sich sieben Jahre lang im Lande der Philister auf.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 8, 3, 'Als dann nach Ablauf der sieben Jahre die Frau aus dem Philisterlande zurückgekehrt war, machte sie sich auf den Weg, um den König wegen ihres Hauses und ihrer Felder um Hilfe anzurufen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 8, 4, 'Der König aber besprach sich gerade mit Gehasi, dem Diener des Gottesmannes, und forderte ihn auf, ihm alle die Wundertaten zu erzählen, die Elisa verrichtet habe.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 8, 5, 'Während er nun dem Könige eben erzählte, wie Elisa den Toten lebendig gemacht hatte, da erschien die Frau, deren Sohn er ins Leben zurückgerufen hatte, um den König wegen ihres Hauses und ihrer Felder um Hilfe anzurufen. Da sagte Gehasi: »Mein Herr und König, dies ist die Frau und dies ihr Sohn, den Elisa lebendig gemacht hat!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 8, 6, 'Da erkundigte sich der König bei der Frau, und sie mußte ihm alles erzählen. Darauf gab der König ihr einen Kammerherrn mit, dem er auftrug: »Verschaffe ihr alles wieder, was ihr gehört, auch den gesamten Ertrag der Felder von dem Tage ab, an dem sie das Land verlassen hat, bis heute!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 8, 7, 'Einst kam Elisa nach Damaskus, wo Benhadad, der König von Syrien, krank lag. Als man diesem nun mitteilte, daß der Gottesmann dorthin komme,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 8, 8, 'befahl der König dem Hasael: »Nimm Geschenke mit dir und gehe dem Gottesmann entgegen und laß Gott den HERRN durch ihn befragen, ob ich von dieser meiner Krankheit genesen werde.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 8, 9, 'Da ging Hasael ihm entgegen und nahm Geschenke an sich, allerlei Kostbarkeiten von Damaskus, eine Last für vierzig Kamele. Als er nun hingekommen und vor ihn getreten war, sagte er: »Dein Sohn Benhadad, der König von Syrien, hat mich zu dir gesandt und läßt fragen, ob er von dieser seiner Krankheit genesen werde.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 8, 10, 'Da antwortete ihm Elisa: »Gehe hin und sage ihm, daß er gewißlich wieder gesund werden würde; aber Gott der HERR hat mir geoffenbart, daß er sterben muß.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 8, 11, 'Dabei starrte der Gottesmann unverwandt vor sich hin und war aufs äußerste entsetzt und brach dann in Tränen aus.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 8, 12, 'Als Hasael ihn nun fragte: »Warum weint mein Herr?«, antwortete er: »Weil ich weiß, wieviel Unheil du den Israeliten zufügen wirst: ihre festen Städte wirst du in Brand stecken, ihre jungen Männer mit dem Schwert umbringen, ihre kleinen Kinder zerschmettern und ihren schwangeren Frauen den Leib aufschlitzen.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 8, 13, 'Da erwiderte Hasael: »Was ist denn dein Knecht, der Hund, daß er solche großen Dinge tun sollte?« Elisa entgegnete ihm: »Gott der HERR hat dich mir als König über Syrien geoffenbart.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 8, 14, 'Darauf ging (Hasael) von Elisa weg, und als er zu seinem Herrn kam und dieser ihn fragte: »Was hat Elisa dir gesagt?«, antwortete er: »Er hat mir gesagt, du würdest gewißlich wieder gesund werden.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 8, 15, 'Am folgenden Tage aber nahm er die Bettdecke, tauchte sie in Wasser und breitete sie ihm über das Gesicht, so daß er starb. Hasael aber wurde König an seiner Statt.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 8, 16, 'Im fünften Jahre der Regierung Jorams, des Sohnes Ahabs, des Königs von Israel, kam Joram, der Sohn des Königs Josaphat von Juda, zur Regierung.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 8, 17, 'Er war zweiunddreißig Jahre alt, als er König wurde, und acht Jahre regierte er in Jerusalem.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 8, 18, 'Er wandelte auf dem Wege der Könige von Israel, wie es im Hause Ahabs durchweg der Fall war – er hatte sich nämlich mit einer Tochter Ahabs verheiratet –; so tat er, was dem HERRN mißfiel.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 8, 19, 'Aber der HERR wollte Juda nicht untergehen lassen um seines Knechtes David willen, weil er ihm zugesagt hatte, daß er ihm allezeit eine Leuchte vor seinem Angesicht verleihen wolle.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 8, 20, 'Unter seiner Regierung fielen die Edomiter von der Oberherrschaft Judas ab und setzten einen eigenen König über sich ein.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 8, 21, 'Da zog Joram mit all seinen Kriegswagen hinüber nach Zair; doch als er nachts aufgebrochen war, schlugen ihn die Edomiter, die ihn und die Befehlshaber der Wagen umzingelt hatten, das Kriegsvolk aber floh nach Hause.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 8, 22, 'So fielen die Edomiter von der Oberherrschaft Judas ab und sind unabhängig geblieben bis auf den heutigen Tag. Damals fiel auch Libna ab, zu derselben Zeit.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 8, 23, 'Die übrige Geschichte Jorams aber und alles, was er unternommen hat, das findet sich bekanntlich aufgezeichnet im Buch der Denkwürdigkeiten der Könige von Juda.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 8, 24, 'Als Joram sich dann zu seinen Vätern gelegt und man ihn bei seinen Vätern in der Davidsstadt begraben hatte, folgte ihm sein Sohn Ahasja in der Regierung nach.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 8, 25, 'Im zwölften Jahre der Regierung Jorams, des Sohnes Ahabs, des Königs von Israel, kam Ahasja, der Sohn des Königs Joram von Juda, zur Regierung.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 8, 26, 'Zweiundzwanzig Jahre war Ahasja alt, als er auf den Thron kam, und ein Jahr hat er in Jerusalem regiert; seine Mutter hieß Athalja und war die Enkelin des Königs Omri von Israel.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 8, 27, 'Er wandelte auf dem Wege des Hauses Ahabs und tat, was dem HERRN mißfiel, wie das Haus Ahabs, weil er mit dem Hause Ahabs verschwägert war.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 8, 28, 'Er zog mit Joram, dem Sohne Ahabs, gegen Hasael, den König von Syrien, zu Felde und kämpfte mit ihm bei Ramoth in Gilead. Als aber die Syrer dort den König Joram verwundet hatten,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 8, 29, 'kehrte der König Joram zurück, um sich in Jesreel von den Wunden heilen zu lassen, die ihm die Syrer bei Rama beigebracht hatten, als er gegen den König Hasael von Syrien Krieg führte. Darauf kam Ahasja, der Sohn Jorams, der König von Juda, um Joram, den Sohn Ahabs, in Jesreel zu besuchen, weil er dort krank lag.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 1, 'Der Prophet Elisa aber rief einen von den Prophetenjüngern zu sich und befahl ihm: »Gürte dir die Lenden, nimm dieses Ölfläschchen mit dir und begib dich nach Ramoth in Gilead.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 2, 'Wenn du dort angekommen bist, so sieh dich daselbst nach Jehu um, dem Sohne Josaphats, des Sohnes Nimsis. Gehe dann zu ihm ins Haus, fordere ihn auf, aus dem Kreise seiner Genossen herauszutreten, und führe ihn in das innerste Gemach.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 3, 'Dann nimm das Ölfläschchen und gieße es ihm aufs Haupt mit den Worten: ›So spricht der HERR: Ich salbe dich hiermit zum König über Israel!‹ Dann öffne die Tür und entfliehe unverzüglich!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 4, 'Als nun der junge Mann, der Diener des Propheten, nach Ramoth in Gilead gekommen');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 5, 'und in das Haus eingetreten war, saßen da die Hauptleute des Heeres gerade beisammen. Er sagte: »Ich habe einen Auftrag an dich, Hauptmann.« Als Jehu nun fragte: »An wen von uns allen?«, antwortete er: »An dich, Hauptmann.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 6, 'Da stand Jehu auf und ging (mit ihm) ins Haus hinein; jener aber goß ihm das Öl aufs Haupt und sagte zu ihm: »So spricht der HERR, der Gott Israels: ›Ich habe dich hiermit zum König über das Volk des HERRN, über Israel, gesalbt.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 7, 'Du sollst nun das Haus Ahabs, deines Herrn, ausrotten, damit ich das Blut der Propheten, meiner Knechte, und das Blut aller Knechte des HERRN an Isebel räche.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 8, 'Denn das ganze Haus Ahabs soll umkommen, und ich will von den Angehörigen Ahabs alles ausrotten, was männlichen Geschlechts ist, sowohl die Unmündigen als auch die Mündigen in Israel;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 9, 'und ich will mit dem Hause Ahabs verfahren wie mit dem Hause Jerobeams, des Sohnes Nebats, und wie mit dem Hause Baesas, des Sohnes Ahias.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 10, 'Isebel aber sollen die Hunde auf der Feldmark von Jesreel fressen, und niemand soll sie begraben!‹« Hierauf öffnete er die Tür und entfloh.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 11, 'Als nun Jehu wieder zu den anderen Hauptleuten seines Herrn hinauskam und sie ihn fragten: »Steht alles gut? Warum ist dieser Verrückte zu dir gekommen?«, antwortete er ihnen: »Ihr kennt ja den Mann und sein Geschwätz.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 12, 'Aber sie riefen: »Das sind Ausflüchte! Teile es uns nur mit!« Da sagte er: »So und so hat er zu mir gesagt, nämlich: ›So spricht der HERR: Ich habe dich zum König über Israel gesalbt.‹«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 13, 'Sofort nahmen sie alle ihre Mäntel, legten sie ihm zu Füßen auf die bloßen Stufen, ließen die Posaune blasen und riefen: »Jehu ist König!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 14, 'Auf diese Weise zettelte Jehu, der Sohn Josaphats, des Sohnes Nimsis, eine Verschwörung gegen Joram an. – Joram hatte nämlich mit ganz Israel Ramoth in Gilead gegen den syrischen König Hasael verteidigt,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 15, 'war dann aber zurückgekehrt, um sich in Jesreel von den Wunden heilen zu lassen, die ihm die Syrer im Kampfe mit dem syrischen Könige Hasael beigebracht hatten. – Jehu aber sagte: »Wenn ihr einverstanden seid, so darf niemand die Stadt verlassen, um hinzugehen und das Geschehene in Jesreel zu melden.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 16, 'Hierauf bestieg Jehu seinen Wagen und trat die Fahrt nach Jesreel an; denn dort lag Joram krank darnieder, und Ahasja, der König von Juda, war dorthin gekommen, um Joram zu besuchen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 17, 'Als nun der Wächter, der auf dem Turm zu Jesreel stand, die Kriegerschar Jehus herankommen sah, rief er: »Ich sehe eine Kriegerschar!« Da befahl Joram: »Man nehme einen Berittenen und schicke ihnen den entgegen, daß er frage, ob sie in friedlicher Absicht kommen!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 18, 'Der Reiter ritt ihm also entgegen und sagte: »Der König läßt fragen, ob ihr in friedlicher Absicht kommt.« Jehu antwortete: »Was geht dich der Friede an? Mache kehrt und reite hinter mir her!« Da meldete der Wächter: »Der Bote ist zu ihnen hingekommen, kehrt aber nicht zurück.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 19, 'Da schickte er einen zweiten Reiter ab; als der bei ihnen ankam und sagte: »Der König läßt fragen, ob ihr in friedlicher Absicht kommt«, antwortete Jehu wieder: »Was geht dich der Friede an? Mache kehrt und reite hinter mir her!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 20, 'Da meldete der Wächter: »Der ist auch zu ihnen hingekommen, kehrt aber nicht wieder zurück. Doch die Art, wie jener fährt, sieht so aus, als ob es Jehu, der Sohn Nimsis, wäre; denn er fährt wie wahnsinnig.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 21, 'Da befahl Joram anzuspannen; und als man seinen Wagen angespannt hatte, fuhren Joram, der König von Israel, und Ahasja, der König von Juda, hinaus, jeder auf seinem Wagen; sie fuhren Jehu entgegen und trafen bei dem Acker Naboths, des Jesreeliters, mit ihm zusammen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 22, 'Als nun Joram den Jehu sah und ihn fragte: »Kommst du in friedlicher Absicht, Jehu?«, antwortete dieser: »Was friedliche Absicht bei all dem Götzendienst deiner Mutter Isebel und all ihren Zaubereien!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 23, 'Da ließ Joram seinen Wagen zur Flucht umwenden und rief dem Ahasja zu: »Verrat, Ahasja!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 24, 'Jehu aber hatte seinen Bogen schon gespannt und traf Joram zwischen die Schulterblätter, so daß der Pfeil ihm durch das Herz fuhr und er in seinem Wagen niedersank.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 25, 'Dann befahl er Bidkar, seinem Ritter: »Nimm ihn und wirf ihn auf den Acker Naboths, des Jesreeliters! Denke daran, wie wir beide nebeneinander hinter seinem Vater Ahab herritten und Gott der HERR dieses Drohwort gegen ihn aussprach:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 26, '›So wahr ich gestern das Blut Naboths und das Blut seiner Söhne gesehen habe‹ – so lautet der Ausspruch des HERRN –, ›so gewiß will ich es dir auf diesem Acker vergelten!‹ – so lautet der Ausspruch des HERRN. So nimm ihn nun und wirf ihn auf den Acker nach dem Geheiß des HERRN!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 27, 'Als Ahasja, der König von Juda, das sah, floh er in der Richtung auf Beth-Haggan. Jehu aber jagte ihm nach und rief: »Schießt auch ihn nieder!« Da schoß man nach ihm auf dem Wagen und verwundete ihn auf der Anhöhe von Gur, die bei Jibleam liegt; er floh dann noch bis Megiddo und starb dort.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 28, 'Seine Diener brachten ihn dann zu Wagen nach Jerusalem, und man begrub ihn in seiner Grabstätte bei seinen Vätern in der Davidsstadt. –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 29, 'Ahasja war aber König von Juda geworden im elften Jahre der Regierung Jorams, des Sohnes Ahabs.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 30, 'Jehu aber war nach Jesreel gekommen; und sobald Isebel dies erfuhr, schminkte sie sich die Augen, schmückte sich das Haupt und schaute zum Fenster hinaus.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 31, 'Als nun Jehu ins Tor hereinkam, rief sie ihm zu: »Ist es Simri, dem Mörder seines Herrn, gut ergangen?«.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 32, 'Da blickte er nach dem Fenster hinauf und rief: »Wer hält es mit mir? Wer?« Als nun zwei oder drei Kammerherren zu ihm hinabschauten,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 33, 'rief er ihnen zu: »Stürzt sie herab!« Da stürzten sie sie hinab, so daß die Wand und die Rosse mit ihrem Blut bespritzt wurden und diese sie zerstampften.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 34, 'Als er dann in das Schloß eingetreten war und gegessen und getrunken hatte, befahl er: »Seht doch nach jenem verfluchten Weibe und begrabt sie! Denn sie ist eine Königstochter.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 35, 'Als man aber hinging, um sie zu begraben, fand man von ihr nichts mehr als den Schädel, die Füße und die Hände.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 36, 'Als sie nun zurückkamen und es dem Jehu meldeten, rief er aus: »So lautet das Wort des HERRN, das er durch den Mund seines Knechtes Elia, des Thisbiters, hat verkünden lassen: ›Auf der Feldmark von Jesreel sollen die Hunde das Fleisch Isebels fressen,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 37, 'und der Leichnam Isebels soll auf der Feldmark von Jesreel wie Dünger auf dem Felde liegen, so daß man nicht mehr wird sagen können: Das ist Isebel.‹«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 1, 'Nun befanden sich siebzig Söhne Ahabs in Samaria. Daher schrieb Jehu Briefe und sandte sie nach Samaria an die Befehlshaber der Stadt sowie an die Ältesten und an die Erzieher der königlichen Prinzen; die lauteten so:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 2, '»Und nun, wenn dieses Schreiben an euch gelangt – ihr seid ja über die Söhne eures Herrn sowie über die Wagen und Rosse, über die festen Plätze und Waffenvorräte bestellt –:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 3, 'so wählt euch den besten und tüchtigsten unter den Söhnen eures Herrn aus und setzt ihn auf den Thron seines Vaters und kämpft für das Haus eures Herrn!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 4, 'Aber sie fürchteten sich gar sehr und sagten: »Nachdem sich die beiden Könige gegen ihn nicht haben behaupten können, wie sollten wir da bestehen?«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 5, 'So ließen denn der Hausminister und der Stadtoberste sowie die Ältesten und die Erzieher folgende Botschaft an Jehu gelangen: »Wir sind deine Knechte und wollen allen deinen Befehlen nachkommen; wir wollen niemand zum König machen: tu, was dir beliebt!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 6, 'Da schrieb Jehu einen zweiten Brief an sie, der so lautete: »Wenn ihr es mit mir haltet und mir gehorsam sein wollt, so nehmt die Köpfe der Männer, der Söhne eures Herrn, und kommt damit morgen um diese Zeit zu mir nach Jesreel.« Die Söhne des Königs befanden sich nämlich, siebzig an der Zahl, bei den vornehmsten Männern der Stadt, die sie zu erziehen hatten.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 7, 'Sobald nun das Schreiben an sie gelangte, nahmen sie die Prinzen und ermordeten alle siebzig; ihre Köpfe legten sie dann in Körbe beisammen und sandten sie an ihn nach Jesreel.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 8, 'Als dann der Bote hinkam und ihm meldete, man habe die Köpfe der Söhne des Königs gebracht, befahl er: »Schichtet sie in zwei Haufen am Eingang des Tores bis morgen früh auf!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 9, 'Am folgenden Morgen aber ging er hinaus und trat vor das ganze Volk mit den Worten: »Ihr seid ohne Schuld! Ich bin es ja gewesen, der sich gegen meinen Herrn verschworen und ihn ums Leben gebracht hat; doch wer hat diese alle ermordet?');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 10, 'So erkennt denn hieraus, daß keine Drohung, die der HERR gegen das Haus Ahabs ausgesprochen hat, unerfüllt bleibt; nein, der HERR hat alles ausgeführt, was er durch den Mund seines Knechtes Elia angekündigt hat.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 11, 'Hierauf ließ Jehu alle, die in Jesreel vom Hause Ahabs noch übrig waren, umbringen, auch alle seine Großen, seine Vertrauten und seine Priester, bis er ihm keinen einzigen mehr am Leben übriggelassen hatte.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 12, 'Hierauf machte sich Jehu auf den Weg, um sich nach Samaria zu begeben. Als er unterwegs bei Beth-Eked-Haroim war,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 13, 'traf er die Brüder Ahasjas, des Königs von Juda, an, und fragte sie, wer sie seien. Sie antworteten: »Wir sind die Brüder Ahasjas und sind hergekommen, um die Söhne des Königs und die Söhne der Königin-Mutter zu besuchen.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 14, 'Da gab er den Befehl: »Ergreift sie lebendig!« Da ergriff man sie lebendig, ermordete sie (und warf sie) in die Zisterne von Beth-Eked, zweiundvierzig Mann; keinen einzigen von ihnen ließ er am Leben.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 15, 'Als er dann von dort weiterzog, traf er auf Jonadab, den Sohn Rechabs, der ihm entgegenkam. Der begrüßte ihn, er aber fragte ihn: »Bist du aufrichtig gegen mich gesinnt, wie ich gegen dich?« Als Jonadab mit »Ja« antwortete, sagte Jehu: »Wenn es wirklich so ist, so gib mir deine Hand!« Da reichte er ihm seine Hand, und Jehu ließ ihn zu sich in den Wagen steigen');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 16, 'und sagte: »Komm mit mir und sieh dir mit Freuden meinen Eifer für den HERRN an!« So nahm er ihn denn in seinem Wagen mit');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 17, 'und ließ nach seiner Ankunft in Samaria alle umbringen, die in Samaria von Angehörigen Ahabs noch übrig waren, bis er sie alle ausgerottet hatte, wie der HERR es dem Elia zuvor angekündigt hatte.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 18, 'Hierauf ließ Jehu das ganze Volk zusammenkommen und sagte zu ihnen: »Ahab hat dem Baal nur eine geringe Verehrung erwiesen, Jehu aber wird ihm eifriger dienen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 19, 'Daher laßt jetzt alle Propheten Baals, alle seine Diener und alle seine Priester zu mir kommen, keiner darf fehlen! Denn ich habe für Baal ein großes Opferfest im Sinn: jeder, der dabei fehlt, ist des Todes!« Jehu ging aber mit Hinterlist so zu Werke, um die Baalsdiener auszurotten.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 20, 'Dann befahl Jehu: »Kündigt eine Festversammlung zu Ehren Baals an!« Als man sie öffentlich bekanntgemacht hatte,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 21, 'sandte Jehu Boten in alle Teile Israels umher. Da fanden sich alle Verehrer Baals ein, kein einziger blieb übrig, der nicht erschienen wäre. Als sie sich dann in den Baalstempel begeben hatten, so daß der Tempel von einem Ende bis zum andern mit Menschen angefüllt war,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 22, 'gab er dem Aufseher über die Kleiderkammer den Befehl, allen Baalsverehrern Gewänder zu verabreichen. Als der die Gewänder für sie herausgegeben hatte,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 23, 'begab sich Jehu mit Jonadab, dem Sohne Rechabs, in den Baalstempel und sagte zu den Baalsverehrern: »Seht genau nach, daß sich hier unter euch ja kein Verehrer Gottes des HERRN befinde, sondern ausschließlich Verehrer Baals!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 24, 'Hierauf schickten sie sich an, die Schlacht- und Brandopfer darzubringen. Jehu hatte aber draußen achtzig Mann aufgestellt und zu ihnen gesagt: »Wer einen von den Männern, die ich euch in die Hände liefere, entkommen läßt, soll mit seinem eigenen Leben für ihn haften!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 25, 'Als man dann mit der Darbringung des Brandopfers fertig war, befahl Jehu den Leibwächtern und Rittern: »Geht hinein, haut sie nieder: keiner darf davonkommen!« Sie machten sie also mit dem Schwert nieder, warfen den Altar um und drangen in das Allerheiligste des Baalstempels ein;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 26, 'dann schafften sie die Götzensäulen aus dem Baalstempel hinaus und verbrannten sie,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 27, 'zertrümmerten das Standbild Baals, rissen den Baalstempel nieder und machten Aborte daraus, die bis auf den heutigen Tag geblieben sind.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 28, 'So rottete Jehu den Baalsdienst in Israel aus;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 29, 'jedoch von den Sünden, zu denen Jerobeam, der Sohn Nebats, die Israeliten verführt hatte, von diesen ließ auch Jehu nicht ab, nämlich von der Verehrung der goldenen Stierbilder, die in Bethel und Dan aufgestellt waren.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 30, 'Der HERR ließ zwar dem Jehu verkünden: »Weil du alles, was mir wohlgefällig war, eifrig ausgeführt und am Hause Ahabs ganz nach meinem Sinn gehandelt hast, so sollen Nachkommen von dir bis ins vierte Glied auf dem Throne von Israel sitzen«;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 31, 'aber Jehu ließ es sich nicht angelegen sein, mit ganzem Herzen nach der Weisung des HERRN, des Gottes Israels, zu wandeln; er ließ nicht ab von den Sünden, zu denen Jerobeam Israel verführt hatte.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 32, 'Zu jener Zeit begann der HERR Teile vom Gebiet Israels loszureißen; denn Hasael schlug sie in allen Grenzgebieten Israels:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 33, 'östlich vom Jordan die ganze Landschaft Gilead, die Stämme Gad, Ruben und Manasse, von Aroer an, das am Arnonflusse liegt, sowohl Gilead als auch Basan. –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 34, 'Die übrige Geschichte Jehus aber und alles, was er unternommen hat, sowie alle seine tapferen Taten, das findet sich bekanntlich aufgezeichnet im Buch der Denkwürdigkeiten der Könige von Israel.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 35, 'Als Jehu sich dann zu seinen Vätern gelegt und man ihn in Samaria begraben hatte, folgte ihm sein Sohn Joahas in der Regierung nach.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 36, 'Die Zeit aber, die Jehu in Samaria über Israel regiert hat, betrug achtundzwanzig Jahre.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 11, 1, 'Als aber Athalja, die Mutter Ahasjas, erfuhr, daß ihr Sohn tot sei, machte sie sich daran, alle, die zur königlichen Familie gehörten, umzubringen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 11, 2, 'Aber Joseba, die Tochter des Königs Joram, Ahasjas Schwester, nahm Joas, den Sohn Ahasjas, und schaffte ihn aus der Mitte der Königssöhne, die ermordet werden sollten, heimlich beiseite, indem sie ihn mit seiner Amme in die Bettzeugkammer brachte; sie verbarg ihn dort vor Athalja, so daß er der Ermordung entging.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 11, 3, 'Er blieb dann sechs Jahre lang bei ihr im Hause des HERRN versteckt, während Athalja das Land regierte.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 11, 4, 'Im siebten Jahre aber ließ Jojada die Hauptleute der Karer und der Läufer holen und zu sich in den Tempel des HERRN kommen; da schloß er ein feierliches Abkommen mit ihnen und ließ sie im Tempel einen Eid ablegen; dann zeigte er ihnen den Königssohn');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 11, 5, 'und gab ihnen die Weisung: »Folgendermaßen müßt ihr zu Werke gehen: Das eine Drittel von euch, das am Sabbat (aus dem Tempel) abzieht, um die Wache im königlichen Palast zu übernehmen,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 11, 6, 'und das (andere) Drittel am Tore Sur und das (letzte) Drittel am Tore hinter den Leibwächtern, die ihr die Wache beim Palast gehalten habt –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 11, 7, 'beide anderen Abteilungen, die am Sabbat aufziehen, sie alle sollen im Tempel des HERRN die Wache beim König übernehmen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 11, 8, 'Ihr müßt euch also rings um den König scharen, ein jeder mit seinen Waffen in der Hand; und wer in die Reihen eindringt, soll getötet werden; und ihr müßt dann beständig um den König sein, wenn er (aus dem Tempel) auszieht und wenn er (in den Palast) einzieht.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 11, 9, 'Die Hauptleute verfuhren dann genau nach der Anweisung des Priesters Jojada: jeder nahm seine Mannschaft zu sich, sowohl die, welche am Sabbat abzog, als auch die, welche am Sabbat aufzog, und so kamen sie zum Priester Jojada.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 11, 10, 'Dieser gab dann den Hauptleuten die Speere und die Schilde, die dem König David gehört hatten und die sich im Tempel des HERRN befanden.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 11, 11, 'Nachdem sich hierauf die Leibwächter, ein jeder mit seinen Waffen in der Hand, von der Südseite des Tempels bis an den Altar und von da wieder bis an die Nordseite des Tempels aufgestellt hatten,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 11, 12, 'führte er den Königssohn heraus und legte ihm die Königsbinde und die Armspangen an. So machten sie ihn zum König und salbten ihn, klatschten in die Hände und riefen: »Es lebe der König!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 11, 13, 'Als nun Athalja das Geschrei [der Leibwächter und] des Volkes vernahm, begab sie sich zum Volk in den Tempel des HERRN.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 11, 14, 'Hier sah sie dann den König an der Säule, wie es Brauch war, und die Hauptleute und die Trompeter neben dem Könige stehen, während das gesamte Volk des Landes voller Freude war und in die Trompeten stieß. Da zerriß Athalja ihre Kleider und rief: »Verrat, Verrat!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 11, 15, 'Aber der Priester Jojada gab den Hauptleuten [den Befehlshabern des Heeres] den Befehl: »Führt sie hinaus zwischen den Reihen hindurch, und wer ihr folgt, den haut mit dem Schwerte nieder!« Der Priester hatte nämlich befohlen, sie dürfe ja nicht im Tempel des HERRN getötet werden.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 11, 16, 'Da legte man Hand an sie, und als sie an dem Wege, der zum Eingang für die Pferde bestimmt war, beim königlichen Palast angelangt war, wurde sie dort getötet.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 11, 17, 'Darauf schloß Jojada zwischen dem HERRN und dem König und dem Volk das feierliche Abkommen, daß sie das Volk des HERRN sein sollten; [ebenso zwischen dem König und dem Volk].');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 11, 18, 'Darauf zog das ganze Volk des Landes nach dem Baalstempel und riß ihn nieder; seine Altäre und Götterbilder zerschlugen sie vollständig und töteten den Baalspriester Matthan vor den Altären. Nachdem der Priester dann Wachtposten am Tempel des HERRN aufgestellt hatte,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 11, 19, 'nahm er die Hauptleute und die Karer und Trabanten sowie alles Volk des Landes mit sich, und sie führten den König aus dem Tempel des HERRN hinab und zogen durch das Leibwächtertor in das königliche Schloß ein, wo er sich auf den königlichen Thron setzte.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 11, 20, 'Da war die gesamte Bevölkerung voller Freude, und die Stadt blieb ruhig; Athalja aber hatten sie im königlichen Schloß mit dem Schwert getötet.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 12, 1, 'Joas war beim Regierungsantritt sieben Jahre alt;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 12, 2, 'im siebten Jahre Jehus war er König geworden, vierzig Jahre regierte er in Jerusalem; seine Mutter hieß Zibja und stammte aus Beerseba.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 12, 3, 'Joas tat, was dem HERRN wohlgefiel, sein ganzes Leben lang, weil der Priester Jojada ihn beriet;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 12, 4, 'nur der Höhendienst wurde nicht beseitigt, sondern das Volk brachte immer noch Schlacht- und Rauchopfer auf den Höhen dar.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 12, 5, 'Joas ließ aber den Priestern die Weisung zugehen: »Alles Geld, das als Weihegabe in den Tempel des HERRN gebracht wird: das Geld, das jemand durch Schätzung auferlegt wird, ferner alles Geld, das jemand aus freien Stücken in den Tempel des HERRN bringt,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 12, 6, 'das sollen die Priester in Empfang nehmen, ein jeder von seinen Bekannten; aber sie sollen hinwieder davon alles ausbessern lassen, was am Tempel baufällig ist, wo immer ein Schaden daran sichtbar wird.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 12, 7, 'Da jedoch die Priester im dreiundzwanzigsten Jahre der Regierung des Joas die Schäden am Tempel noch nicht ausgebessert hatten,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 12, 8, 'ließ der König Joas den Priester Jojada und die übrigen Priester zu sich kommen und sagte zu ihnen: »Warum habt ihr die Schäden am Tempel nicht ausgebessert? Fortan sollt ihr kein Geld mehr von euren Bekannten in Empfang nehmen, sondern sollt es für die Ausbesserung der Schäden am Tempel abliefern.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 12, 9, 'Die Priester erklärten sich damit einverstanden, daß sie kein Geld mehr vom Volk in Empfang nehmen sollten, aber auch für die Ausbesserung der Schäden am Tempel nicht mehr zu sorgen brauchten.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 12, 10, 'Darauf nahm der Priester Jojada einen Kasten, ließ ein Loch in seinen Deckel bohren und ihn neben dem Malstein rechts vom Eingang in den Tempel des HERRN aufstellen; dahinein mußten die Priester, die an der Schwelle Wache hielten, alles Geld tun, das im Tempel des HERRN abgeliefert wurde.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 12, 11, 'Sooft sie nun wahrnahmen, daß viel Geld in dem Kasten war, kamen der Schreiber des Königs und der Hohepriester hinauf, banden das Geld, das sich im Tempel des HERRN vorfand, in einen Beutel zusammen und zählten es.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 12, 12, 'Dann händigten sie das abgezählte Geld den Werkführern ein, denen die Ausführung der Arbeiten am Tempel des HERRN übertragen war, und diese zahlten es an die Zimmerleute und an die übrigen Handwerker aus, die am Tempel des HERRN arbeiteten,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 12, 13, 'sowie an die Maurer und Steinmetzen und für den Ankauf von Hölzern und behauenen Steinen, um die Schäden am Tempel des HERRN auszubessern und überhaupt alle Kosten zu bestreiten, welche die Instandhaltung des Tempels verursachte.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 12, 14, 'Doch ließ man für den Tempel des HERRN keine silbernen Becken, Messer, Sprengschalen, Trompeten, kurz keinerlei goldene und silberne Geräte von dem Gelde anfertigen, das im Tempel des HERRN einging,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 12, 15, 'sondern man gab es den Werkleuten, damit sie dafür den Tempel des HERRN ausbesserten.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 12, 16, 'Dabei verlangte man von den Männern, denen man das Geld einhändigte, damit sie es an die Arbeiter auszahlten, keine Rechnungslegung, sondern sie handelten auf Treu und Glauben.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 12, 17, 'Das Geld von Schuld- und Sündopfern aber wurde nicht an den Tempel des HERRN abgeliefert, sondern es gehörte den Priestern.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 12, 18, 'Damals zog der syrische König Hasael heran, belagerte Gath und eroberte es. Als Hasael sich dann anschickte, auch gegen Jerusalem hinaufzuziehen,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 12, 19, 'nahm Joas, der König von Juda, alle Weihgeschenke, die von seinen Vorfahren, den judäischen Königen Josaphat, Joram und Ahasja herrührten, sowie seine eigenen Weihgeschenke, ferner alles Gold, das sich in den Schatzkammern des Tempels des HERRN und des königlichen Palastes vorfand, und sandte es an Hasael, den König von Syrien. Da stand dieser von dem Zuge gegen Jerusalem ab.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 12, 20, 'Die übrige Geschichte des Joas aber und alles, was er unternommen hat, das findet sich bekanntlich aufgezeichnet im Buch der Denkwürdigkeiten der Könige von Juda.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 12, 21, 'Es taten sich aber seine Diener zu einer Verschwörung gegen ihn zusammen und ermordeten Joas, als er in die Burg Millo hinabging;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 12, 22, 'und zwar waren es seine Diener Josachar, der Sohn Simeaths, und Josabad, der Sohn Somers, die ihn ermordeten. Man begrub ihn dann bei seinen Vätern in der Davidsstadt, und sein Sohn Amazja folgte ihm in der Regierung nach.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 13, 1, 'Im dreiundzwanzigsten Regierungsjahre des Joas, des Sohnes des Königs Ahasja von Juda, wurde Joahas, der Sohn Jehus, König über Israel und regierte siebzehn Jahre in Samaria.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 13, 2, 'Er tat, was dem HERRN mißfiel, und wandelte in den Sünden Jerobeams, des Sohnes Nebats, der Israel zur Sünde verführt hatte; er ließ nicht davon ab.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 13, 3, 'Da entbrannte der Zorn des HERRN gegen Israel, so daß er sie in die Gewalt Hasaels, des Königs von Syrien, und in die Gewalt Benhadads, des Sohnes Hasaels, die ganze Zeit hindurch fallen ließ.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 13, 4, 'Als Joahas dann aber den HERRN mit Gebeten anging, erhörte ihn der HERR; denn er sah die Bedrängnis der Israeliten, weil der syrische König sie hart bedrückte.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 13, 5, 'Daher ließ der HERR den Israeliten einen Retter erstehen, so daß sie sich von der Herrschaft der Syrer frei machten und die Israeliten wieder ruhig in ihren Zelten wohnen konnten wie ehedem.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 13, 6, 'Dennoch gaben sie die Sünde des Hauses Jerobeams nicht auf, wozu dieser die Israeliten verführt hatte: sie hielten daran fest; sogar die Bildsäule der Aschera blieb in Samaria stehen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 13, 7, 'Er (der HERR) hatte dem Joahas an Kriegsvolk nichts übriggelassen als fünfzig Reiter, zehn Kriegswagen und zehntausend Mann Fußvolk; denn der syrische König hatte sie vernichtet und sie dem Staub gleichgemacht, den man zertritt.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 13, 8, 'Die übrige Geschichte des Joahas aber sowie alles, was er unternommen hat, und seine tapferen Taten, das findet sich bekanntlich aufgezeichnet im Buch der Denkwürdigkeiten der Könige von Israel.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 13, 9, 'Als Joahas sich dann zu seinen Vätern gelegt und man ihn in Samaria begraben hatte, folgte ihm sein Sohn Joas in der Regierung nach.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 13, 10, 'Im siebenunddreißigsten Jahre der Regierung des Joas, des Königs von Juda, wurde Joas, der Sohn des Joahas, König über Israel und regierte sechzehn Jahre in Samaria.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 13, 11, 'Er tat, was dem HERRN mißfiel; er ließ in keinem Stück von den Sünden Jerobeams, des Sohnes Nebats, ab, der Israel zur Sünde verführt hatte; nein, er hielt daran fest. –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 13, 12, 'Die übrige Geschichte des Joas aber sowie alles, was er unternommen hat, seine tapferen Taten (und) wie er mit Amazja, dem Könige von Juda, Krieg geführt hat, das findet sich bekanntlich aufgezeichnet im Buch der Denkwürdigkeiten der Könige von Israel. –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 13, 13, 'Als Joas sich dann zu seinen Vätern gelegt und Jerobeam als sein Nachfolger den Thron bestiegen hatte, wurde Joas in Samaria bei den Königen von Israel begraben.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 13, 14, 'Als Elisa aber an der Krankheit darniederlag, an der er sterben sollte, kam Joas, der König von Israel, zu ihm hinab, weinte über ihm und rief aus: »Mein Vater, mein Vater! Du Wagen Israels und seine Reiter!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 13, 15, 'Da sagte Elisa zu ihm: »Hole einen Bogen und Pfeile!«, und als er ihm einen Bogen und Pfeile geholt hatte,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 13, 16, 'sagte er zum König von Israel: »Lege deine Hand auf den Bogen!« Als er es getan hatte, legte Elisa seine Hände auf die Hände des Königs');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 13, 17, 'und sagte: »Öffne das Fenster nach Osten zu!« Nachdem er es geöffnet hatte, forderte Elisa ihn auf zu schießen. Da schoß er, (Elisa) aber rief aus: »Ein Siegespfeil vom HERRN ist es, und zwar ein Siegespfeil gegen die Syrer! So wirst du die Syrer bei Aphek bis zur Vernichtung schlagen!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 13, 18, 'Dann fuhr er fort: »Nimm die Pfeile!« Als er sie genommen hatte, sagte er zum König von Israel: »Schlage damit auf die Erde!« Da schlug er dreimal und hielt dann inne.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 13, 19, 'Da wurde der Gottesmann unwillig über ihn und sagte: »Du hättest fünf- oder sechsmal schlagen sollen, dann hättest du die Syrer bis zur Vernichtung geschlagen; nun aber wirst du die Syrer nur dreimal schlagen!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 13, 20, 'Als Elisa dann gestorben war, begrub man ihn. Es pflegten aber moabitische Streifscharen Jahr für Jahr ins Land einzufallen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 13, 21, 'Nun begab es sich, als man gerade einen Mann begraben wollte, daß man plötzlich eine Streifschar herankommen sah; da warf man den Mann in das Grab Elisas und ging weg. Sobald aber der Mann hineinkam und mit den Gebeinen Elisas in Berührung kam, wurde er wieder lebendig und stellte sich aufrecht auf seine Füße.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 13, 22, 'Der König Hasael von Syrien aber hatte die Israeliten während der ganzen Regierung des Joahas bedrängt;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 13, 23, 'doch nun erwies der HERR ihnen Gnade, erbarmte sich ihrer und wandte sich ihnen wieder zu wegen seines Bundes mit Abraham, Isaak und Jakob; denn er wollte sie noch nicht zugrunde gehen lassen, hatte sie auch bis jetzt noch nicht von seinem Angesicht verworfen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 13, 24, 'Als daher Hasael, der König von Syrien, gestorben und sein Sohn Benhadad ihm in der Regierung nachgefolgt war,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 13, 25, 'entriß Joas, der Sohn des Joahas, dem Benhadad, dem Sohne Hasaels, die Städte wieder, die dieser seinem Vater Joahas im Kriege entrissen hatte. Dreimal schlug ihn Joas und gewann so die israelitischen Städte zurück.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 14, 1, 'Im zweiten Regierungsjahre des Joas, des Sohnes des Königs Joahas von Israel, wurde Amazja, der Sohn des Joas, König über Juda.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 14, 2, 'Im Alter von fünfundzwanzig Jahren kam er auf den Thron, und neunundzwanzig Jahre regierte er in Jerusalem; seine Mutter hieß Joaddan und stammte aus Jerusalem.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 14, 3, 'Er tat, was dem HERRN wohlgefiel, doch nicht so wie sein Ahnherr David, sondern ganz, wie sein Vater Joas getan hatte;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 14, 4, 'jedoch der Höhendienst wurde nicht abgeschafft, sondern das Volk brachte immer noch Schlacht- und Rauchopfer auf den Höhen dar. –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 14, 5, 'Sobald er nun die Herrschaft fest in Händen hatte, ließ er von seinen Dienern diejenigen hinrichten, die den König, seinen Vater, ermordet hatten.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 14, 6, 'Aber die Söhne der Mörder ließ er nicht hinrichten, sondern verfuhr so, wie im Gesetzbuch Moses geschrieben steht, wo der HERR ausdrücklich geboten hat: »Väter sollen nicht wegen einer Verschuldung ihrer Söhne getötet werden, und Söhne sollen nicht wegen einer Verschuldung ihrer Väter getötet werden, sondern ein jeder soll nur wegen seiner eigenen Sünde getötet werden.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 14, 7, 'Er war es auch, der die Edomiter im Salztal schlug, zehntausend Mann, und Sela im Sturm eroberte und dem Ort den Namen Joktheel beilegte, den er bis auf den heutigen Tag führt.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 14, 8, 'Damals schickte Amazja Gesandte an den König Joas von Israel, den Sohn des Joahas, des Sohnes Jehus, und ließ ihm sagen: »Komm, wir wollen unsere Kräfte miteinander messen!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 14, 9, 'Da ließ Joas, der König von Israel, dem König Amazja von Juda durch eine Gesandtschaft antworten: »Der Dornstrauch auf dem Libanon sandte (einst) zu der Zeder auf dem Libanon und ließ ihr sagen: ›Gib deine Tochter meinem Sohne zur Frau!‹, aber da liefen die wilden Tiere auf dem Libanon über den Dornstrauch hin und zertraten ihn.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 14, 10, 'Weil du die Edomiter glücklich besiegt hast, ist dir der Mut gewachsen. Begnüge dich mit dem Ruhme und bleibe zu Hause sitzen: warum willst du das Unglück herausfordern, daß du zu Fall kommst und Juda mit dir?«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 14, 11, 'Da aber Amazja nicht hören wollte, zog Joas, der König von Israel, heran, und beide maßen ihre Kräfte miteinander, er und der König Amazja von Juda, bei Beth-Semes, das zu Juda gehört.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 14, 12, 'Da wurden die Judäer von den Israeliten geschlagen, so daß ein jeder in seine Heimat floh.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 14, 13, 'Den Amazja selber aber, den König von Juda, den Sohn des Joas, des Sohnes Ahasjas, nahm Joas, der König von Israel, bei Beth-Semes gefangen und ließ, als er nach Jerusalem gekommen war, ein Stück der Mauer Jerusalems vom Ephraimstor bis zum Ecktor auf einer Strecke von vierhundert Ellen niederreißen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 14, 14, 'Außerdem nahm er alles Gold und Silber sowie alle Geräte, die sich im Tempel des HERRN und in den Schatzkammern des königlichen Palastes vorfanden, dazu Geiseln, und kehrte dann nach Samaria zurück.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 14, 15, 'Die übrige Geschichte des Joas aber, alles, was er unternommen hat, und seine tapferen Taten und wie er mit dem König Amazja von Juda Krieg geführt hat, das findet sich bekanntlich aufgezeichnet im Buch der Denkwürdigkeiten der Könige von Israel.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 14, 16, 'Als Joas sich dann zu seinen Vätern gelegt und man ihn in Samaria bei den Königen von Israel begraben hatte, folgte ihm sein Sohn Jerobeam in der Regierung nach.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 14, 17, 'Amazja aber, der Sohn des Joas, der König von Juda, überlebte den König Joas von Israel, den Sohn des Joahas, noch fünfzehn Jahre.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 14, 18, 'Die übrige Geschichte Amazjas aber findet sich bekanntlich aufgezeichnet im Buch der Denkwürdigkeiten der Könige von Juda. –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 14, 19, 'Als man aber in Jerusalem eine Verschwörung gegen ihn anstiftete, floh er nach Lachis; doch man sandte Leute nach Lachis hinter ihm her, die ihn dort ermordeten.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 14, 20, 'Dann lud man ihn auf Rosse, und er wurde in Jerusalem bei seinen Vätern in der Davidstadt begraben.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 14, 21, 'Hierauf nahm die ganze Bevölkerung von Juda den Asarja, der sechzehn Jahre alt war, und machte ihn zum König als Nachfolger seines Vaters Amazja.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 14, 22, 'Er befestigte Elath, das er an Juda zurückgebracht hatte, sogleich nachdem der König sich zu seinen Vätern gelegt hatte.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 14, 23, 'Im fünfzehnten Regierungsjahre des Königs Amazja von Juda, des Sohnes des Joas, wurde Jerobeam, der Sohn des Königs Joas von Israel, König zu Samaria und regierte einundvierzig Jahre.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 14, 24, 'Er tat, was dem HERRN mißfiel; er wich in keinem Stück von den Sünden Jerobeams, des Sohnes Nebats, der Israel zur Sünde verführt hatte.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 14, 25, 'Er stellte die Grenze Israels wieder her von der Gegend um Hamath an bis an den großen Steppensee (das Tote Meer), der Verheißung entsprechend, die der HERR, der Gott Israels, durch seinen Knecht, den Propheten Jona, den Sohn Amittais aus Gath-Hepher, gegeben hatte.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 14, 26, 'Denn der HERR hatte das gar bittere Elend Israels wahrgenommen und gesehen, daß Unmündige ebenso wie Mündige dahin waren und daß kein Helfer für Israel da war.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 14, 27, 'Auch hatte der HERR noch nicht die Drohung ausgesprochen, daß er den Namen Israels unter dem Himmel austilgen wolle; darum half er ihnen jetzt durch Jerobeam, den Sohn des Joas.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 14, 28, 'Die übrige Geschichte Jerobeams aber und alles, was er unternommen hat, und seine tapferen Taten, wie er Krieg geführt und wie er Damaskus und Hamath, die zu Juda gehört hatten, für Israel zurückerobert hat, das findet sich bekanntlich aufgezeichnet im Buch der Denkwürdigkeiten der Könige von Israel. –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 14, 29, 'Als Jerobeam sich dann zu seinen Vätern, den Königen von Israel, gelegt hatte, folgte ihm sein Sohn Sacharja in der Regierung nach.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 1, 'Im siebenundzwanzigsten Regierungsjahr Jerobeams, des Königs von Israel, wurde Asarja König, der Sohn des Königs Amazja von Juda.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 2, 'Im Alter von sechzehn Jahren bestieg er den Thron, und zweiundfünfzig Jahre regierte er in Jerusalem; seine Mutter hieß Jecholja und stammte aus Jerusalem.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 3, 'Er tat, was dem HERRN wohlgefiel, ganz so wie sein Vater Amazja getan hatte;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 4, 'jedoch der Höhendienst wurde nicht abgeschafft, das Volk brachte immer noch Schlacht- und Rauchopfer auf den Höhen dar.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 5, 'Der HERR aber suchte den König schwer heim, daß er bis zu seinem Todestage am Aussatz litt und in einem Hause abgesondert für sich wohnte. Jotham aber, der Sohn des Königs, waltete im königlichen Hause (oder Palaste) als Familienhaupt und versah die Regierungsgeschäfte für das Land. –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 6, 'Die übrige Geschichte Asarjas aber und alles, was er unternommen hat, findet sich bekanntlich aufgezeichnet im Buch der Denkwürdigkeiten der Könige von Juda.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 7, 'Als Asarja sich dann zu seinen Vätern gelegt und man ihn bei seinen Vätern in der Davidsstadt begraben hatte, folgte ihm sein Sohn Jotham in der Regierung nach.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 8, 'Im achtunddreißigsten Regierungsjahre des Königs Asarja von Juda wurde Sacharja, der Sohn Jerobeams, König über Israel in Samaria und regierte ein halbes Jahr.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 9, 'Er tat, was dem HERRN mißfiel, so wie seine Väter getan hatten; er ließ nicht ab von den Sünden Jerobeams, des Sohnes Nebats, der Israel zur Sünde verführt hatte.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 10, 'Da zettelte Sallum, der Sohn des Jabes, eine Verschwörung gegen ihn an, ermordete ihn in Jibleam und trat als König an seine Stelle.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 11, 'Die übrige Geschichte Sacharjas aber findet sich bereits aufgezeichnet im Buch der Denkwürdigkeiten der Könige von Israel.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 12, 'So erfüllte sich die Verheißung, die der HERR dem Jehu gegeben hatte mit den Worten: »Es sollen Nachkommen von dir bis ins vierte Glied auf dem Thron von Israel sitzen.« So ist es auch geschehen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 13, 'Sallum, der Sohn des Jabes, wurde König im neununddreißigsten Regierungsjahre des Königs Ussia von Juda und regierte einen Monat lang zu Samaria.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 14, 'Da zog Menahem, der Sohn Gadis, aus Thirza gegen ihn heran, drang in Samaria ein, brachte Sallum, den Sohn des Jabes, in Samaria ums Leben und trat als König an seine Stelle.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 15, 'Die übrige Geschichte Sallums aber und die Verschwörung, die er angezettelt hatte, das findet sich bereits aufgezeichnet im Buch der Denkwürdigkeiten der Könige von Israel.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 16, 'Damals verwüstete Menahem die Stadt Thappuah und alles, was darin war, sowie ihr ganzes Gebiet von Thirza an; weil man ihm die Tore nicht geöffnet hatte, verwüstete er es und ließ allen Frauen dort, die guter Hoffnung waren, den Leib aufschlitzen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 17, 'Im neununddreißigsten Regierungsjahre des Königs Asarja von Juda wurde Menahem, der Sohn Gadis, König über Israel und regierte zehn Jahre in Samaria.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 18, 'Er tat, was dem Herrn mißfiel; er ließ nicht ab von den Sünden Jerobeams, des Sohnes Nebats, der Israel zur Sünde verführt hatte. Unter seiner Regierung');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 19, 'fiel der assyrische König Phul in das Land ein, und Menahem gab dem Phul tausend Talente Silber, damit er ihm Beistand gewähre, um ihn im Besitz des Königtums zu sichern.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 20, 'Das Geld ließ Menahem dann von den Israeliten aufbringen, nämlich von allen wohlhabenden Leuten, um dem König von Assyrien Zahlung leisten zu können; fünfzig Schekel Silber kamen auf jeden Mann. Da zog der König von Assyrien wieder ab und blieb nicht länger dort im Lande. –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 21, 'Die übrige Geschichte Menahems aber und alles, was er unternommen hat, findet sich bekanntlich aufgezeichnet im Buch der Denkwürdigkeiten der Könige von Israel.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 22, 'Als Menahem sich dann zu seinen Vätern gelegt hatte, folgte ihm sein Sohn Pekahja in der Regierung nach.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 23, 'Im fünfzigsten Regierungsjahre des Königs Asarja von Juda wurde Pekahja, der Sohn Menahems, König über Israel in Samaria und regierte zwei Jahre.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 24, 'Er tat, was dem HERRN mißfiel; er ließ nicht ab von den Sünden Jerobeams, des Sohnes Nebats, der Israel zur Sünde verführt hatte.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 25, 'Da zettelte sein Ritter Pekah, der Sohn Remaljas, eine Verschwörung gegen ihn an und ermordete ihn zu Samaria in der Burg des königlichen Palastes [zugleich auch den Argob und den Arje], zur Seite standen ihm dabei fünfzig Mann von den Gileaditern. Nachdem er ihn getötet hatte, folgte er ihm als König in der Regierung nach. –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 26, 'Die übrige Geschichte Pekahjas aber und alles, was er unternommen hat, das findet sich bereits aufgezeichnet im Buch der Denkwürdigkeiten der Könige von Israel.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 27, 'Im zweiundfünfzigsten Regierungsjahre des Königs Asarja von Juda wurde Pekah, der Sohn Remaljas, König über Israel in Samaria und regierte zwanzig Jahre.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 28, 'Er tat, was dem HERRN mißfiel; er ließ nicht ab von den Sünden Jerobeams, des Sohnes Nebats, der Israel zur Sünde verführt hatte.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 29, 'Unter der Regierung Pekahs, des Königs von Israel, zog Thiglath-Pileser, der König von Assyrien, heran und eroberte Ijjon, Abel-Beth-Maacha, Janoah, Kedes und Hazor, Gilead und Galiläa, das ganze Land Naphthali, und führte die Bewohner in die Gefangenschaft nach Assyrien.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 30, 'Da zettelte Hosea, der Sohn Elas, eine Verschwörung gegen Pekah, den Sohn Remaljas an, brachte ihn ums Leben und trat dann als König an seine Stelle im zwanzigsten Regierungsjahre Jothams, des Sohnes Ussias. –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 31, 'Die übrige Geschichte Pekahs aber und alles, was er unternommen hat, das findet sich bereits aufgezeichnet im Buch der Denkwürdigkeiten der Könige von Israel.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 32, 'Im zweiten Regierungsjahre Pekahs, des Sohnes des Königs Remalja von Israel, wurde Jotham, der Sohn Ussias, König über Juda.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 33, 'Im Alter von fünfundzwanzig Jahren wurde er König, und sechzehn Jahre regierte er in Jerusalem; seine Mutter hieß Jerusa und war eine Tochter Zadoks.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 34, 'Er tat, was dem HERRN wohlgefiel, ganz wie sein Vater Ussia getan hatte;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 35, 'jedoch der Höhendienst wurde nicht abgeschafft; das Volk brachte immer noch Schlacht- und Rauchopfer auf den Höhen dar. Er baute das obere Tor am Tempel des HERRN.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 36, 'Die übrige Geschichte Jothams aber und alles, was er unternommen hat, das findet sich bekanntlich aufgezeichnet im Buch der Denkwürdigkeiten der Könige von Juda.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 37, 'Zu jener Zeit begann der HERR den König Rezin von Syrien und Pekah, den Sohn Remaljas, gegen Juda vorgehen zu lassen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 38, 'Als Jotham sich dann zu seinen Vätern gelegt und man ihn bei seinen Vätern in der Stadt seines Ahnherrn David begraben hatte, folgte ihm sein Sohn Ahas als König in der Regierung nach.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 39, '');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 16, 1, 'Im siebzehnten Regierungsjahre Pekahs, des Sohnes Remaljas, wurde Ahas König, der Sohn des Königs Jotham von Juda.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 16, 2, 'Im Alter von zwanzig Jahren wurde Ahas König, und sechzehn Jahre regierte er in Jerusalem. Er tat nicht, was dem HERRN, seinem Gott, wohlgefiel, wie sein Ahnherr David getan hatte,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 16, 3, 'sondern er wandelte auf dem Wege der Könige von Israel, ja, er ließ sogar seinen Sohn als Opfer verbrennen nach der grauenhaften Sitte der heidnischen Völker, die der HERR vor den Israeliten vertrieben hatte.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 16, 4, 'Er brachte auch Schlacht- und Rauchopfer dar auf den Höhen und auf den Hügeln und unter jedem dichtbelaubten Baum.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 16, 5, 'Damals zogen Rezin, der König von Syrien, und Pekah, der Sohn Remaljas, der König von Israel, zum Angriff gegen Jerusalem heran und belagerten (die Stadt), waren aber nicht imstande, sie zu erstürmen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 16, 6, 'Zu jener Zeit brachte der König von Edom Elath wieder an Edom und vertrieb die Judäer aus Elath; da kamen die Edomiter nach Elath zurück und sind dort wohnen geblieben bis auf den heutigen Tag.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 16, 7, 'Ahas aber schickte eine Gesandtschaft an Thiglath-Pileser, den König von Assyrien, und ließ ihm sagen: »Ich bin dein Knecht und dein Sohn: komm mir zu Hilfe und rette mich aus der Gewalt des Königs von Syrien und aus der Gewalt des Königs von Israel, die gegen mich zu Felde gezogen sind!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 16, 8, 'Zugleich nahm Ahas das Silber und Gold, das sich im Tempel des HERRN und in den Schatzkammern des königlichen Palastes vorfand, und sandte es an den König von Assyrien als Geschenk.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 16, 9, 'Der König von Assyrien kam dann auch seiner Aufforderung nach, rückte gegen Damaskus, eroberte es und führte (die Einwohner) gefangen nach Kir; den König Rezin aber ließ er hinrichten.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 16, 10, 'Als sich nun der König Ahas nach Damaskus begeben hatte, um dort mit Thiglath-Pileser, dem König von Assyrien, zusammenzutreffen, und den Altar sah, der in Damaskus stand, sandte der König Ahas dem Priester Uria die Maße des Altars und eine bis in alle Einzelheiten ausgeführte Nachbildung.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 16, 11, 'Da ließ der Priester Uria einen Altar genau nach dem Vorbild bauen, das ihm der König Ahas aus Damaskus hatte zugehen lassen; so ließ der Priester Uria ihn herstellen, ehe noch der König Ahas aus Damaskus zurückkehrte.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 16, 12, 'Als dann der König nach seiner Rückkehr aus Damaskus den Altar sah, trat der König an den Altar heran und stieg zu ihm hinauf,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 16, 13, 'ließ dann selber sein Brand- und Speisopfer in Rauch aufgehen, goß sein Trankopfer aus und sprengte das Blut seiner Heilsopfer an den Altar.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 16, 14, 'Den ehernen Altar aber, der vor dem (Tempel des) HERRN stand, den ließ er von der Vorderseite des Tempels, von der Stelle zwischen dem (neuen) Altar und dem Tempel des HERRN, entfernen und ihn auf die Nordseite des (neuen) Altars versetzen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 16, 15, 'Sodann erteilte der König Ahas dem Priester Uria folgenden Befehl: »Auf dem großen (neuen) Altar verbrenne das Morgenbrandopfer und das Abendspeisopfer sowie das Brandopfer des Königs nebst seinem Speisopfer, ebenso auch die Brandopfer aller Privatleute des Landes samt ihren Speis- und Trankopfern, und sprenge alles Blut der Brandopfer und alles Blut der Schlachtopfer an diesen Altar; in betreff des ehernen Altars aber will ich mich noch bedenken.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 16, 16, 'Da verfuhr der Priester Uria genau nach dem Befehl des Königs Ahas.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 16, 17, 'Sodann ließ der König Ahas die Beschläge an den Gestühlen herausbrechen und die Kessel von ihnen herunternehmen; auch das große Wasserbecken ließ er von den ehernen Rindern, auf denen es ruhte, herabnehmen und es auf eine Unterlage von Steinen setzen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 16, 18, 'Weiter ließ er den überdeckten Sabbat-Gang, den man im Tempel erbaut hatte, und den äußeren Königszugang am Tempel des HERRN beseitigen mit Rücksicht auf den König von Assyrien.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 16, 19, 'Die übrige Geschichte des Ahas aber und alles, was er unternommen hat, findet sich bekanntlich aufgezeichnet im Buch der Denkwürdigkeiten der Könige von Juda.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 16, 20, 'Als Ahas sich dann zu seinen Vätern gelegt und man ihn bei seinen Vätern in der Davidstadt begraben hatte, trat sein Sohn Hiskia als König an seine Stelle.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 1, 'Im zwölften Jahre des Königs Ahas von Juda wurde Hosea, der Sohn Elas, König über Israel in Samaria und regierte neun Jahre.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 2, 'Er tat, was dem HERRN mißfiel, wenn auch nicht so arg wie die Könige von Israel, die vor ihm regiert hatten.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 3, 'Gegen ihn zog Salmanassar, der König von Assyrien, heran; Hosea unterwarf sich ihm und wurde ihm tributpflichtig.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 4, 'Als aber der König von Assyrien eine Verschwörung Hoseas entdeckte – er hatte nämlich Gesandte an den König Sewe von Ägypten geschickt und dem Könige von Assyrien nicht mehr wie sonst alljährlich den Tribut entrichtet –, da ließ der König von Assyrien ihn festnehmen und gefesselt ins Gefängnis werfen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 5, 'Der König von Assyrien hatte nämlich das ganze Land mit Krieg überzogen, war vor Samaria gerückt und hatte es drei Jahre lang belagert.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 6, 'Als der König von Assyrien dann Samaria im neunten Regierungsjahre Hoseas erobert hatte, führte er die Israeliten in die Gefangenschaft nach Assyrien und wies ihnen Wohnsitze in Halah und am Habor, dem Flusse Gosans, sowie in den Ortschaften Mediens an.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 7, 'Das ist aber geschehen, weil die Israeliten sich am HERRN, ihrem Gott, versündigt hatten, der sie aus Ägypten aus der Gewalt des Pharaos, des ägyptischen Königs, weggeführt hatte, und weil sie andere Götter verehrt hatten');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 8, 'und nach den Satzungen der Heidenvölker gewandelt waren, die der HERR vor den Israeliten vertrieben hatte, und nach den Bräuchen, welche die Könige von Israel eingeführt hatten.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 9, 'So hatten denn die Israeliten gegen den Willen des HERRN, ihres Gottes, Dinge getrieben, die nicht recht waren; denn sie hatten sich Höhenheiligtümer in allen ihren Ortschaften erbaut, von den Wachttürmen an bis zu den festen Städten,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 10, 'und hatten sich Malsteine und Götzensäulen auf jedem hohen Hügel und unter jedem dichtbelaubten Baume errichtet');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 11, 'und dort auf allen Höhen geopfert wie die heidnischen Völkerschaften, die der HERR vor ihnen vertrieben hatte. Sie hatten also böse Dinge verübt, um den HERRN zum Zorn zu reizen,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 12, 'und den Götzen gedient, in betreff deren der HERR ihnen geboten hatte: »Ihr dürft so etwas nicht tun!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 13, 'Und der HERR hatte doch Israel und Juda durch den Mund aller Propheten, aller Seher warnen lassen, indem er ihnen vorhielt: »Kehrt von euren bösen Wegen um und haltet meine Gebote und meine Verordnungen genau nach der Weisung, die ich euren Vätern gegeben und die ich euch durch meine Knechte, die Propheten, habe zukommen lassen!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 14, 'Aber sie hatten nicht hören wollen, sondern sich halsstarrig gezeigt, wie auch ihre Väter, die dem HERRN, ihrem Gott, nicht vertraut hatten;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 15, 'sie mißachteten seine Satzungen und seinen Bund, den er mit ihren Vätern geschlossen, und seine Warnungen, die er an sie gerichtet hatte; sie liefen vielmehr hinter den nichtigen Götzen her und wandten sich einem nichtigen Treiben zu nach dem Vorbild der heidnischen Völkerschaften, die um sie her wohnten, bezüglich deren der HERR ihnen geboten hatte, es nicht so zu machen wie jene.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 16, 'Sie vernachlässigten alle Gebote des HERRN, ihres Gottes, und fertigten sich zwei gegossene Stierbilder an, verfertigten sich Götzensäulen, beteten das ganze Sternenheer des Himmels an und dienten dem Baal.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 17, 'Sie verbrannten auch ihre Söhne und Töchter als Opfer, trieben Wahrsagerei und Zauberei und gaben sich dazu her, das, was dem HERRN mißfiel, zu verüben, um ihn zu erbittern.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 18, 'Da geriet der HERR in heftigen Zorn gegen die Israeliten und verstieß sie von seinem Angesicht, so daß nichts übrigblieb als der Stamm Juda allein.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 19, 'Aber auch die dem Stamm Juda Angehörigen beobachteten die Gebote des HERRN, ihres Gottes, nicht, sondern wandelten in den Bräuchen, welche die Israeliten in Aufnahme gebracht hatten.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 20, 'Da verwarf denn der HERR die ganze Nachkommenschaft Israels, demütigte sie und ließ sie in die Gewalt von Räubern fallen, bis er sie ganz von seinem Angesicht verstoßen hatte.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 21, 'Als nämlich Israel sich vom Hause Davids losgerissen und sie Jerobeam, den Sohn Nebats, zum König gemacht hatten, da hatte Jerobeam die Israeliten zum Abfall vom HERRN veranlaßt und sie zu schwerer Sünde verführt.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 22, 'So waren denn die Israeliten in allen Sünden gewandelt, die Jerobeam begangen hatte; sie waren nicht davon abgegangen,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 23, 'bis der HERR die Israeliten von seinem Angesicht verstieß, wie er es durch den Mund aller seiner Knechte, der Propheten, angedroht hatte. So wurden also die Israeliten aus ihrem Lande nach Assyrien weggeführt, wo sie sich bis auf den heutigen Tag befinden.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 24, 'Der König von Assyrien aber ließ Leute aus Babylon, Kutha, Awwa, Hamath und Sepharwaim kommen und siedelte sie an Stelle der Israeliten in den Ortschaften Samarias an; die nahmen Besitz von Samaria und wohnten in den dortigen Ortschaften.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 25, 'Weil sie aber in der ersten Zeit ihrer Niederlassung daselbst den HERRN nicht verehrten, ließ der HERR Löwen gegen sie los, welche Verheerungen unter ihnen anrichteten.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 26, 'Da machte man dem König von Assyrien die Meldung: »Die Völkerschaften, die du aus ihrer Heimat hast auswandern lassen und in den Ortschaften Samarias angesiedelt hast, verstehen sich nicht auf die dem Landesgott gebührende Verehrung; daher hat er Löwen gegen sie losgelassen, die nun Verheerungen unter ihnen anrichten, weil sie sich nicht auf die dem Landesgott gebührende Verehrung verstehen.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 27, 'Da erließ der König von Assyrien folgenden Befehl: »Laßt einen von den Priestern, die ihr von dort weggeführt habt, dorthin zurückkehren; der soll sich dorthin begeben und dort wohnen und sie in der dem Landesgott gebührenden Verehrung unterweisen!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 28, 'So kam denn einer von den Priestern, die man aus Samaria weggeführt hatte, zurück, ließ sich in Bethel nieder und unterwies sie, wie sie den HERRN zu verehren hätten.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 29, 'Dabei machten sie sich aber, jede einzelne Völkerschaft, ihren besonderen Gott und stellten diesen in den Höhentempeln auf, welche die Samarier erbaut hatten, eine jede Völkerschaft in ihren Ortschaften, in denen sie angesiedelt waren.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 30, 'Die Leute von Babylon z.B. fertigten ein Bild des Sukkoth-Benoth an, die Leute aus Kuth ein Bild des Nergal, die Leute aus Hamath ein Bild des Asima;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 31, 'die Awwiter fertigten ein Bild des Nibhas und Tharthak an, und die Sepharwiter verbrannten ihre Kinder als Feueropfer zu Ehren Adrammelechs und Anammelechs, der Götter von Sepharwaim.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 32, 'Daneben verehrten sie (jetzt) aber auch Gott den HERRN und bestellten sich Leute aus ihrer Mitte zu Höhenpriestern, die für sie Opfer in den Höhenheiligtümern darbrachten.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 33, 'So waren sie zwar Verehrer des HERRN, blieben zugleich aber auch Diener ihrer Götter nach den Bräuchen der Völkerschaften, aus denen man sie weggeführt hatte.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 34, 'Bis auf den heutigen Tag verfahren sie nach den ursprünglichen Bräuchen: sie verehren den HERRN nicht in rechter Weise und verfahren nicht nach seinen Satzungen und seinen Verordnungen, nicht nach dem Gesetz und den Geboten, die der HERR den Nachkommen Jakobs geboten hat, dem er den Namen ›Israel‹ beilegte.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 35, 'Und doch hatte der HERR einen Bund mit ihnen geschlossen und ihnen ausdrücklich geboten: »Ihr dürft keine anderen Götter verehren und dürft sie nicht anbeten und ihnen nicht dienen noch opfern;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 36, 'sondern Gott den HERRN, der euch aus Ägypten mit großer Kraft und hocherhobenem Arm hergeführt hat, den sollt ihr verehren und den sollt ihr anbeten und ihm opfern!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 37, 'Die Satzungen und Verordnungen aber, das Gesetz und die Gebote, die er euch vorgeschrieben hat, müßt ihr beobachten, daß ihr allezeit danach tut, und dürft keine anderen Götter verehren!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 38, 'Und des Bundes, den ich mit euch geschlossen habe, dürft ihr nicht vergessen und dürft keine anderen Götter verehren;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 39, 'sondern den HERRN, euren Gott, sollt ihr verehren: er ist es, der euch aus der Gewalt aller eurer Feinde erretten wird.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 40, 'Aber sie wollten nicht darauf hören, sondern taten nach ihrer früheren Weise. –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 41, 'So waren also diese Völkerschaften zwar Verehrer des HERRN, zugleich aber Diener ihrer Götzenbilder; auch ihre Kinder und Kindeskinder halten es so, wie ihre Väter getan haben, bis auf den heutigen Tag.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 1, 'Darauf, im dritten Regierungsjahre Hoseas, des Sohnes Elas, des Königs von Israel, wurde Hiskia König, der Sohn des Königs Ahas von Juda.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 2, 'Im Alter von fünfundzwanzig Jahren wurde er König, und neunundzwanzig Jahre regierte er in Jerusalem; seine Mutter hieß Abi und war die Tochter Sacharjas.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 3, 'Er tat, was dem HERRN wohlgefiel, ganz so wie sein Ahnherr David getan hatte.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 4, 'Er war es, der den Höhendienst abschaffte, die Malsteine zertrümmerte, die Götzenbäume umhieb und die eherne Schlange zerschlug, die Mose angefertigt hatte; denn bis zu dieser Zeit hatten die Israeliten ihr immerfort geopfert, und man nannte sie Nehustan.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 5, 'Er setzte sein Vertrauen auf den HERRN, den Gott Israels, so daß unter allen Königen von Juda weder nach ihm noch unter denen, die vor ihm gewesen waren, irgendeiner ihm gleichgekommen ist.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 6, 'Er hielt am HERRN fest, ohne von ihm abzuweichen, und beobachtete seine Gebote, die der HERR dem Mose gegeben hatte.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 7, 'So war denn auch der HERR mit ihm, so daß er bei allen seinen Unternehmungen Glück hatte. Er fiel auch vom König von Assyrien ab und machte sich unabhängig von ihm.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 8, 'Er schlug auch die Philister bis nach Gaza hin, und zwar bis an die Grenze dieser Stadt, vom Wächterturm an bis zur befestigten Stadt.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 9, 'Im vierten Regierungsjahre des Königs Hiskia aber – das war das siebte Regierungsjahr des Königs Hosea von Israel, des Sohnes Elas – zog der assyrische König Salmanassar gegen Samaria heran, belagerte es');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 10, 'und nahm es nach Ablauf von drei Jahren ein; im sechsten Regierungsjahr Hiskias – das war das neunte Regierungsjahr des Königs Hosea von Israel – wurde Samaria erobert.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 11, 'Der König von Assyrien führte dann die Israeliten in die Gefangenschaft nach Assyrien und verpflanzte sie nach Halah und an den Habor, den Fluß Gosans, und in die Ortschaften der Meder,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 12, 'zur Strafe dafür, daß sie den Weisungen des HERRN, ihres Gottes, nicht nachgekommen waren und seinen Bund übertreten hatten, alles was Mose, der Knecht des HERRN, ihnen geboten hatte: sie hatten weder darauf gehört noch danach getan.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 13, 'Im vierzehnten Regierungsjahr des Königs Hiskia aber zog der assyrische König Sanherib gegen alle festen Städte Judas heran und eroberte sie.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 14, 'Da schickte der König Hiskia von Juda eine Gesandtschaft an den König von Assyrien nach Lachis und ließ ihm sagen: »Ich habe unrecht getan; ziehe aus meinem Lande wieder ab! Was du mir auferlegst, will ich tragen.« Da legte der König von Assyrien dem Könige Hiskia von Juda die Zahlung von dreihundert Talenten Silber und dreißig Talenten Gold auf;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 15, 'und Hiskia gab alles Silber hin, das sich im Tempel des HERRN und in den Schatzkammern des königlichen Palastes vorfand.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 16, 'Zu jener Zeit ließ Hiskia von den Türen im Tempel des HERRN und von den Pfeilern, die er selbst mit Goldblech hatte überziehen lassen, das Gold abnehmen und gab es dem König von Assyrien.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 17, 'Aber der assyrische König sandte seinen Großwesir und den Oberkämmerer und den Obermundschenk mit einem starken Heere von Lachis aus gegen den König Hiskia nach Jerusalem. Als diese hinaufgezogen und vor Jerusalem angekommen waren, stellten sie sich bei der Wasserleitung des oberen Teiches auf, der an der Straße nach dem Walkerfeld liegt.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 18, 'Als sie nun den König zu sprechen verlangten, ging der Hausminister Eljakim, der Sohn Hilkias, mit dem Staatsschreiber Sebna und dem Kanzler Joah, dem Sohne Asaphs, zu ihnen hinaus.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 19, 'Da sagte der Obermundschenk zu ihnen: »Berichtet dem Hiskia: So hat der Großkönig, der König von Assyrien, gesprochen: ›Worauf beruht denn das feste Vertrauen, das du hegst?');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 20, 'Meinst du etwa, der Verlauf und Ausgang eines Krieges hänge lediglich von Worten ab? Auf wen verläßt du dich eigentlich, daß du dich gegen mich empört hast?');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 21, 'Nun ja, du verläßt dich auf Ägypten, auf diesen eingeknickten Rohrstab, der jedem, welcher sich darauf stützt, in die Hand fährt und sie durchbohrt: so erweist sich nämlich der Pharao, der König von Ägypten, allen denen, die sich auf ihn verlassen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 22, 'Wenn ihr mir aber entgegnen wollt: Auf den HERRN, unsern Gott, verlassen wir uns! – ist das nicht derselbe, dessen Höhen(- dienst) und Altäre Hiskia beseitigt hat, als er in Juda und Jerusalem den Befehl erließ: Nur vor dem Altar hier in Jerusalem dürft ihr euch niederwerfen?');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 23, 'Und nun, gehe doch mit meinem Herrn, dem König von Assyrien, eine Wette ein: ich will dir zweitausend Pferde liefern, ob du wohl imstande bist, die Reiter für sie aufzubringen!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 24, 'Wie willst du da den Kampf mit einem einzigen Befehlshaber von den geringsten Dienern meines Herrn aufnehmen? Und doch verläßt du dich auf Ägypten um der Wagen und Reiter willen!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 25, 'Zudem: bin ich etwa ohne Zutun des HERRN, eures Gottes, gegen diesen Ort herangezogen, um ihn zu verheeren? Der HERR selbst hat mich aufgefordert, gegen dieses Land zu ziehen und es zu verheeren!‹«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 26, 'Hierauf sagten Eljakim, der Sohn Hilkias, und Sebna und Joah zu dem Obermundschenk: »Sprich doch aramäisch mit deinen Knechten, denn wir verstehen es, und sprich nicht judäisch mit uns vor den Ohren des Volkes, das auf der Mauer steht!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 27, 'Aber der Obermundschenk erwiderte ihnen: »Hat mich mein Herr etwa nur zu deinem Herrn und zu dir gesandt, um diese Verhandlungen zu führen, und nicht auch zu den Männern, die dort auf der Mauer sitzen, um schließlich mit euch zusammen ihren eigenen Kot zu verzehren und ihren Harn zu trinken?«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 28, 'Hierauf trat der Obermundschenk vor und rief mit gehobener Stimme auf judäisch die Worte aus: »Vernehmt die Botschaft des Großkönigs, des Königs von Assyrien!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 29, 'So läßt euch der König sagen: ›Laßt euch von Hiskia nicht täuschen! Denn er vermag euch nicht aus meiner Gewalt zu erretten;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 30, 'auch laßt euch von Hiskia nicht auf Gott den HERRN vertrösten, wenn er sagt: Gott der HERR wird uns sicherlich erretten, und unsere Stadt wird nicht in die Hand des Königs von Assyrien fallen!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 31, 'Hört nicht auf Hiskia! Denn so läßt euch der König von Assyrien sagen: Schließt Frieden mit mir und ergebt euch mir! Dann sollt ihr ein jeder von seinem eigenen Weinstock und seinem eigenen Feigenbaum essen und ein jeder das Wasser aus seiner eigenen Zisterne trinken,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 32, 'bis ich komme, um euch in ein Land mitzunehmen, das gleich dem eurigen ist, ein Land voll von Getreide und Most, ein Land voll von Brot und Weinbergen, ein Land voll von Ölbäumen und Honig, damit ihr am Leben bleibt und nicht zu sterben braucht. Aber hört nicht auf Hiskia! Denn er will euch nur betören, wenn er sagt: Gott der HERR wird uns erretten!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 33, 'Hat etwa von den Göttern der anderen Völker irgendeiner sein Land aus der Gewalt des Königs von Assyrien gerettet?');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 34, 'Wo sind die Götter von Hamath und Arpad? Wo die Götter von Sepharwaim, von Hena und Iwwa? Und ebensowenig haben sie Samaria aus meiner Gewalt gerettet.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 35, 'Wo ist unter allen Göttern der Länder ein einziger, der sein Land aus meiner Gewalt gerettet hätte, daß jetzt Gott der HERR Jerusalem aus meiner Gewalt erretten sollte?‹«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 36, 'Da schwieg das Volk still und antwortete ihm kein Wort; denn es lag ein Befehl des Königs vor, der geboten hatte: »Ihr sollt ihm nicht antworten!« –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 37, 'Hierauf kehrten der Hausminister Eljakim, der Sohn Hilkias, und der Staatsschreiber Sebna und der Kanzler Joah, der Sohn Asaphs, mit zerrissenen Kleidern zu Hiskia zurück und berichteten ihm, was der Obermundschenk gesagt hatte.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 1, 'Als nun der König Hiskia das vernommen hatte, zerriß er seine Kleider, hüllte sich in Sackleinen und begab sich in den Tempel des HERRN;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 2, 'seinen Hausminister Eljakim aber und den Staatsschreiber Sebna samt den vornehmsten Priestern sandte er, ebenfalls in Trauerkleider gehüllt, zu dem Propheten Jesaja, dem Sohne des Amoz.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 3, 'Diese sagten zu ihm: »So läßt Hiskia dir sagen: ›Ein Tag der Bedrängnis, der Züchtigung und Schmach ist der heutige Tag; denn die Kinder sind bis zum Muttermund gekommen, aber es fehlt an Kraft zum Gebären.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 4, 'Vielleicht aber wird der HERR, dein Gott, auf alle Worte des Großwesirs hören, den sein Herr, der König von Assyrien, hergesandt hat, um den lebendigen Gott zu verhöhnen, und wird ihn für die Worte strafen, die der HERR, dein Gott, gehört hat. So lege denn Fürbitte ein für den Rest, der noch vorhanden ist!‹«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 5, 'Als nun die Diener des Königs Hiskia zu Jesaja gekommen waren,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 6, 'sagte dieser zu ihnen: »Bringt eurem Herrn folgenden Bescheid: ›So hat der HERR gesprochen: Fürchte dich nicht vor den Reden, die du gehört hast, mit denen die Diener des Königs von Assyrien mich geschmäht haben!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 7, 'Wisse wohl: ich will ihm einen Geist eingeben, daß er, wenn er eine Kunde erhält, in sein Land zurückkehrt, und ich will ihn dann in seinem eigenen Lande durch das Schwert umkommen lassen.‹«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 8, 'Als hierauf der Großwesir zurückgekehrt war, fand er den König von Assyrien mit der Belagerung von Libna beschäftigt; er hatte nämlich erfahren, daß jener von Lachis abgezogen war.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 9, 'Als (Sanherib) sodann in betreff des äthiopischen Königs Thirhaka die Nachricht erhielt, dieser sei zum Kriege gegen ihn ausgezogen, sandte er nochmals Boten an Hiskia und ließ ihm sagen:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 10, '»Folgende Botschaft sollt ihr dem König Hiskia von Juda überbringen: Laß dich nicht von deinem Gott täuschen, auf den du dein Vertrauen setzt, indem du meinst: ›Jerusalem wird nicht in die Gewalt des Königs von Assyrien fallen!‹');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 11, 'Du hast doch selbst gehört, wie die Könige von Assyrien mit allen Ländern verfahren sind, indem sie den Bann an ihnen vollstreckten, und da solltest du gerettet werden?');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 12, 'Haben etwa die Götter der Völkerschaften, welche meine Väter vernichtet haben, diese Völker errettet: Gosan, Haran und Rezeph und die Bewohner von Eden in Thelassar?');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 13, 'Wo ist der König von Hamath, der König von Arpad und der König von Lair und Sepharwaim, von Hena und Iwwa?«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 14, 'Als nun Hiskia das Schreiben aus der Hand der Gesandten in Empfang genommen und es gelesen hatte, ging er in den Tempel des HERRN hinauf und breitete es dort vor dem HERRN aus.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 15, 'Alsdann betete Hiskia vor dem HERRN mit den Worten: »HERR, Gott Israels, der du über den Cheruben thronst! Du allein bist der Gott über alle Reiche auf Erden; du bist’s, der Himmel und Erde geschaffen hat!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 16, 'Neige, HERR, dein Ohr und höre! Öffne deine Augen, HERR, und blicke her! Ja, höre die Worte, die Sanherib hier hat sagen lassen, um den lebendigen Gott zu verhöhnen!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 17, 'Es ist allerdings wahr, HERR, daß die Könige von Assyrien die Völkerschaften und ihr Land verwüstet');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 18, 'und deren Götter ins Feuer geworfen haben; aber das waren auch keine Götter, sondern nur Machwerk von Menschenhänden, Holz und Stein: die konnten sie vernichten.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 19, 'Nun aber, HERR, unser Gott, rette uns doch aus seiner Hand, damit alle Reiche auf Erden erkennen, daß du, HERR, allein Gott bist!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 20, 'Da sandte Jesaja, der Sohn des Amoz, zu Hiskia und ließ ihm sagen: »So hat der HERR, der Gott Israels, gesprochen: ›Was das Gebet betrifft, das du wegen Sanheribs, des Königs von Assyrien, an mich gerichtet hast, so habe ich es gehört.‹');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 21, 'Folgenden Ausspruch hat der HERR über ihn getan: ›Es verachtet dich, es spottet deiner die jungfräuliche Tochter Zion; hinter dir her schüttelt das Haupt die Tochter Jerusalem!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 22, 'Wen hast du geschmäht und gelästert und gegen wen deine Stimme erhoben und deine Augen hochmütig emporgerichtet? Gegen den Heiligen Israels!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 23, 'Durch den Mund deiner Gesandten hast du den HERRN geschmäht und hast gesagt: Mit meiner Kriegswagen Menge ersteige ich die Höhen der Berge, den obersten Gipfel des Libanon; ich haue nieder den Hochwald seiner Zedern, die Auslese seiner Zypressen, und dringe vor bis zu seinem obersten Gipfel, in seinen dichtesten Baumgarten.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 24, 'Ich grabe den Erdboden auf und trinke Wasser und mache andrerseits mit der Sohle meiner Füße versiegen alle Nilarme Ägyptens! –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 25, 'Hast du es nicht gehört? Von lange her habe ich es festgesetzt und seit den Tagen der Vorzeit es vorbereitet, nunmehr aber es eintreten lassen, daß du feste Städte zu wüsten Steinhaufen verheeren solltest,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 26, 'und ihre Bewohner, deren Arm zu kurz war, sollten erschreckt dastehen und zuschanden werden, sollten wie Kraut des Feldes und grünender Rasen sein, wie Gras auf den Dächern und wie Getreide, das versengt ist, ehe es aufschießt.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 27, 'Mir ist dein Aufstehen und dein Sitzen offenbar, dein Gehen und Kommen kenne ich wohl, auch dein Toben wider mich.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 28, 'Weil du nun wider mich tobst und dein Großtun zu meinen Ohren aufgestiegen ist, will ich dir meinen Ring in die Nase legen und meinen Zaum an deine Lippen und will dich auf dem Wege zurückkehren lassen, auf dem du hergekommen bist.‹');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 29, 'Folgendes aber möge dir, Hiskia, als Wahrzeichen dienen: In diesem Jahr wird man den Brachwuchs essen und im nächsten Jahre den Wurzelwuchs; im dritten Jahre aber sollt ihr säen und ernten, sollt ihr Weinberge anlegen und ihren Ertrag genießen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 30, 'Was dann vom Hause Juda entronnen und als Rest übriggeblieben ist, wird aufs neue unten Wurzel treiben und oben Früchte tragen;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 31, 'denn von Jerusalem wird ein Überrest ausgehen und eine Schar Entronnener vom Berge Zion; der Eifer des HERRN der Heerscharen wird dies vollführen!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 32, 'Darum hat der HERR in bezug auf den König von Assyrien so gesprochen: ›Er soll nicht in diese Stadt hineinkommen und keinen Pfeil hineinschießen; er soll mit keinem Schild gegen sie anrücken und keinen Wall gegen sie aufführen!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 33, 'Nein, auf dem Wege, auf dem er gekommen ist, soll er zurückkehren und in diese Stadt nicht eindringen!‹ – so lautet der Ausspruch des HERRN.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 34, '›Ja, ich will diese Stadt beschirmen, um sie zu erretten, um meiner selbst willen und um meines Knechtes David willen!‹«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 35, 'In derselben Nacht aber ging der Engel des HERRN aus und ließ im Lager der Assyrer 185000 Mann sterben; und als man am Morgen früh aufstand, fand man sie alle tot als Leichen vor.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 36, 'Da brach Sanherib, der König von Assyrien, auf und zog ab; er kehrte nach Hause zurück und nahm seinen Wohnsitz in Ninive.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 37, 'Als er aber dort (einmal) im Tempel seines Gottes Nisroch anbetete, erschlugen ihn seine Söhne Adrammelech und Sarezer mit dem Schwert; sie entflohen dann ins Land Ararat, und sein Sohn Esarhaddon folgte ihm als König in der Regierung nach.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 20, 1, 'Als Hiskia in jenen Tagen auf den Tod erkrankte, begab sich der Prophet Jesaja, der Sohn des Amoz, zu ihm und sagte zu ihm: »So hat der HERR gesprochen: ›Bestelle dein Haus, denn du mußt sterben und wirst nicht wieder gesund werden!‹«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 20, 2, 'Da kehrte er sein Gesicht gegen die Wand hin und betete zum HERRN:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 20, 3, '»Ach, HERR! Denke doch daran, wie ich in Treue und mit ungeteiltem Herzen vor deinem Angesicht gewandelt bin und getan habe, was dir wohlgefällt!« Hierauf brach Hiskia in heftiges Weinen aus.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 20, 4, 'Als nun Jesaja den inneren Vorhof des Palastes noch nicht verlassen hatte, da erging das Wort des HERRN an ihn folgendermaßen:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 20, 5, '»Kehre um und sage zu Hiskia, dem Fürsten meines Volks: So hat der HERR, der Gott deines Ahnherrn David, gesprochen: ›Ich habe dein Gebet gehört und deine Tränen gesehen; so will ich dich denn wieder gesund werden lassen: schon übermorgen sollst du zum Tempel des HERRN hinaufgehen!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 20, 6, 'Ich will dann zu deinen Lebenstagen noch fünfzehn Jahre hinzufügen; dazu will ich dich und diese Stadt aus der Gewalt des Königs von Assyrien erretten und diese Stadt beschirmen um meinetwillen und um meines Knechtes David willen.‹«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 20, 7, 'Darauf sagte Jesaja: »Bringt ein Feigenpflaster her!« Da holten sie ein solches und legten es auf das Geschwür: da wurde er gesund.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 20, 8, 'Als Hiskia aber Jesaja fragte: »Welches ist das Wahrzeichen dafür, daß der HERR mich heilen wird und daß ich übermorgen zum Tempel des HERRN hinaufgehen kann?«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 20, 9, 'Da antwortete Jesaja: »Folgendes soll dir von seiten des HERRN als Wahrzeichen dafür dienen, daß der HERR die Verheißung erfüllen wird, die er gegeben hat: Soll der Schatten zehn Stufen vorwärts oder zehn Stufen rückwärts gehen?«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 20, 10, 'Hiskia antwortete: »Es wäre für den Schatten ein leichtes, zehn Stufen hinabzusteigen; nein, der Schatten soll zehn Stufen wieder rückwärts gehen!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 20, 11, 'Da rief der Prophet Jesaja den HERRN an, und dieser ließ den Schatten an den Stufen, welche (die Sonne) auf den Stufen des Sonnenzeigers des Ahas bereits hinabgestiegen war, um zehn Stufen rückwärts gehen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 20, 12, 'Zu jener Zeit sandte Merodach-Baladan, der Sohn Baladans, der König von Babylon, ein Schreiben und ein Geschenk an Hiskia; er hatte nämlich gehört, daß Hiskia krank gewesen war.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 20, 13, 'Hiskia hörte sie (die Gesandten) gern an und zeigte ihnen sein ganzes Schatzhaus: das Silber und das Gold, die Spezereien und das kostbare Öl, sein ganzes Zeughaus und überhaupt alles, was sich in seinen Schatzhäusern vorfand; es gab nichts in seinem Palast und im ganzen Bereich seiner Herrschaft, was Hiskia ihnen nicht gezeigt hätte.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 20, 14, 'Da begab sich der Prophet Jesaja zum König Hiskia und fragte ihn: »Was haben diese Männer gewollt, und woher sind sie gekommen?« Hiskia antwortete: »Aus einem fernen Lande sind sie gekommen, aus Babylon.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 20, 15, 'Darauf fragte jener: »Was haben sie in deinem Palast zu sehen bekommen?« Hiskia antwortete: »Alles, was in meinem Palast ist, haben sie zu sehen bekommen; es gibt in meinen Schatzhäusern nichts, was ich ihnen nicht gezeigt hätte.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 20, 16, 'Da sagte Jesaja zu Hiskia: »Vernimm das Wort des HERRN:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 20, 17, '›Wisse wohl: es kommt die Zeit, da wird alles, was in deinem Palast vorhanden ist und was an Schätzen deine Väter bis zum heutigen Tage aufgehäuft haben, nach Babylon weggebracht werden; nichts wird zurückbleiben!‹ – so hat der HERR gesprochen –;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 20, 18, '›und von deinen leiblichen Söhnen, die dir geboren werden, wird man einige nehmen, damit sie im Palast des Königs von Babylon als Kämmerlinge dienen.‹«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 20, 19, 'Da antwortete Hiskia dem Jesaja: »Gütig ist das Wort des HERRN, das du mir mitgeteilt hast!« Er dachte nämlich: »Nun gut: es wird ja doch Friede und Sicherheit herrschen, solange ich lebe.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 20, 20, 'Die übrige Geschichte Hiskias aber und alle seine Herrschermacht und wie er den Teich und die Wasserleitung angelegt und das Wasser in die Stadt geleitet hat, das findet sich bekanntlich aufgezeichnet im Buch der Denkwürdigkeiten der Könige von Juda.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 20, 21, 'Als Hiskia sich dann zu seinen Vätern gelegt hatte, folgte ihm sein Sohn Manasse als König in der Regierung nach.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 21, 1, 'Im Alter von zwölf Jahren wurde Manasse König und regierte fünfundfünfzig Jahre in Jerusalem; seine Mutter hieß Hephziba.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 21, 2, 'Er tat, was dem HERRN mißfiel, im Anschluß an den greuelhaften Götzendienst der heidnischen Völker, die der HERR vor den Israeliten vertrieben hatte.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 21, 3, 'Er baute die Höhen wieder auf, die sein Vater Hiskia zerstört hatte, errichtete dem Baal Altäre, ließ ein Standbild der Aschera herstellen, wie es der König Ahab von Israel getan hatte, betete das ganze Sternenheer des Himmels an und erwies ihnen Verehrung.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 21, 4, 'Er erbaute sogar Altäre im Tempel des HERRN, von dem doch der HERR gesagt hatte: »In Jerusalem will ich meinen Namen wohnen lassen«;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 21, 5, 'und zwar erbaute er dem ganzen Sternenheer des Himmels Altäre in den beiden Vorhöfen des Tempels des HERRN.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 21, 6, 'Auch ließ er seinen eigenen Sohn als Brandopfer verbrennen, trieb Zauberei und Wahrsagerei und bestellte Totenbeschwörer und Zeichendeuter: er tat gar vieles, was dem HERRN mißfiel und ihn zum Zorn reizen mußte.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 21, 7, 'Das geschnitzte Astartebild, das er hatte anfertigen lassen, stellte er sogar im Tempel auf, von dem doch der HERR zu David und dessen Sohne Salomo gesagt hatte: »In diesem Hause und in Jerusalem, das ich aus allen Stämmen Israels erwählt habe, will ich meinen Namen für ewige Zeiten wohnen lassen;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 21, 8, 'und ich will den Fuß Israels fortan nicht wieder wandern lassen aus dem Lande, das ich ihren Vätern gegeben habe, wofern sie nur darauf bedacht sind, alles zu tun, wie ich es ihnen geboten habe, nämlich ganz nach dem Gesetz (zu leben), das mein Knecht Mose ihnen geboten hat.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 21, 9, 'Aber sie gehorchten nicht; und Manasse verleitete sie dazu, es noch ärger zu treiben als die heidnischen Völker, welche der HERR vor den Israeliten vertilgt hatte.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 21, 10, 'Da ließ sich der HERR durch den Mund seiner Knechte, der Propheten, so vernehmen:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 21, 11, '»Weil Manasse, der König von Juda, diese Greuel verübt hat, die ärger sind als alles, was die Amoriter vordem getan haben; und weil er auch Juda durch seinen Götzendienst zur Sünde verführt hat,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 21, 12, 'darum hat der HERR, der Gott Israels, so gesprochen: ›Wisset wohl: ich will Unglück über Jerusalem und Juda kommen lassen, daß allen, die davon hören, beide Ohren gellen sollen!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 21, 13, 'Und zwar will ich über Jerusalem die Meßschnur ziehen wie (vordem) über Samaria und will die Setzwaage stellen wie beim Hause Ahabs, und ich will Jerusalem ausscheuern, wie man eine Schüssel ausscheuert und sie nach dem Ausscheuern auf ihre Oberseite umkehrt.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 21, 14, 'Und ich will den Überrest meines Eigentumsvolkes verstoßen und sie in die Gewalt ihrer Feinde fallen lassen, daß sie allen ihren Feinden zum Raub und zur Beute werden sollen,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 21, 15, 'zur Strafe dafür, daß sie getan haben, was mir mißfällt, und mich immerfort zum Zorn gereizt haben seit der Zeit, wo ihre Väter aus Ägypten ausgezogen sind, bis auf den heutigen Tag!‹«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 21, 16, 'Auch sehr viel unschuldiges Blut vergoß Manasse, so daß er Jerusalem damit bis oben an den Rand anfüllte, abgesehen von der Sünde, zu der er Juda verführte, das zu tun, was dem HERRN mißfiel.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 21, 17, 'Die übrige Geschichte Manasses aber und alles, was er unternommen, und seine Versündigung, die er begangen hat, das findet sich bekanntlich aufgezeichnet im Buch der Denkwürdigkeiten der Könige von Juda. –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 21, 18, 'Als Manasse sich dann zu seinen Vätern gelegt und man ihn im Garten seines Palastes, im Garten Ussas begraben hatte, folgte ihm sein Sohn Amon als König in der Regierung nach.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 21, 19, 'Im Alter von zweiundzwanzig Jahren wurde Amon König, und zwei Jahre regierte er in Jerusalem; seine Mutter hieß Mesullameth und war die Tochter des Haruz von Jotba.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 21, 20, 'Er tat, was dem HERRN mißfiel, wie sein Vater Manasse getan hatte,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 21, 21, 'und wandelte ganz auf dem Wege, den sein Vater gewandelt war: er verehrte die Götzen, die sein Vater verehrt hatte, und betete sie an;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 21, 22, 'aber vom HERRN, dem Gott seiner Väter, wandte er sich ab und wandelte nicht auf dem Wege des HERRN.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 21, 23, 'Da verschworen sich seine eigenen Diener gegen ihn und ermordeten den König in seinem Palaste;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 21, 24, 'die Landbevölkerung aber erschlug alle, die an der Verschwörung gegen den König Amon teilgenommen hatten, und erhob dann seinen Sohn Josia zu seinem Nachfolger auf dem Throne.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 21, 25, 'Die übrige Geschichte Amons aber, alles was er unternommen hat, findet sich bekanntlich aufgezeichnet im Buch der Denkwürdigkeiten der Könige von Juda.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 21, 26, 'Als man ihn aber in seinem Begräbnis im Garten Ussas begraben hatte, folgte ihm sein Sohn Josia als König in der Regierung nach.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 22, 1, 'Im Alter von acht Jahren wurde Josia König, und einunddreißig Jahre regierte er in Jerusalem; seine Mutter hieß Jedida und war die Tochter Adajas von Bozkath.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 22, 2, 'Er tat, was dem HERRN wohlgefiel, und wandelte ganz auf dem Wege seines Ahnherrn David, ohne nach rechts oder nach links davon abzuweichen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 22, 3, 'In seinem achtzehnten Regierungsjahre aber sandte der König Josia den Staatsschreiber Saphan, den Sohn Azaljas, des Sohnes Mesullams, in den Tempel des HERRN mit der Weisung:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 22, 4, '»Gehe zum Hohenpriester Hilkia hinauf, er soll das Geld ausschütten, das in den Tempel des HERRN gebracht worden ist und das die Schwellenhüter vom Volk eingesammelt haben;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 22, 5, 'man soll es dann den Werkführern einhändigen, die am Tempel des HERRN zu Aufsehern bestellt sind, damit diese es den Arbeitern auszahlen, die am Tempel des HERRN mit der Ausbesserung der Schäden des Tempels beschäftigt sind,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 22, 6, 'den Zimmerleuten, Bauleuten und Maurern sowie für den Ankauf von Hölzern und behauenen Steinen zur Instandsetzung des Tempels.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 22, 7, 'Doch soll über das Geld, das man ihnen einhändigt, keine Verrechnung mit ihnen stattfinden; denn sie handeln auf Treu und Glauben.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 22, 8, 'Da sagte dann der Hohepriester Hilkia zum Staatsschreiber Saphan: »Ich habe das Gesetzbuch im Tempel des HERRN gefunden«; damit übergab Hilkia dem Saphan das Buch, und er las es.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 22, 9, 'Als hierauf der Staatsschreiber Saphan zum Könige kam und diesem Bericht erstattet hatte mit den Worten: »Deine Knechte haben das Geld, das sich im Tempel vorfand, ausgeschüttet und es den Werkführern eingehändigt, die am Tempel des HERRN zu Aufsehern bestellt sind«,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 22, 10, 'machte der Staatsschreiber Saphan dem Könige noch die Mitteilung: »Der Priester Hilkia hat mir ein Buch übergeben«, und Saphan las es dem Könige vor.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 22, 11, 'Als nun der König den Inhalt des Gesetzbuches vernommen hatte, zerriß er seine Kleider');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 22, 12, 'und gab sodann dem Priester Hilkia und Ahikam, dem Sohne Saphans, und Achbor, dem Sohne Michajas, und dem Staatsschreiber Saphan und Asaja, dem Leibdiener des Königs, folgenden Befehl:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 22, 13, '»Geht hin und befragt den HERRN für mich und für das Volk und für ganz Juda in betreff des Inhalts dieses Buches, das man aufgefunden hat! Denn groß ist der Grimm des HERRN, der gegen uns entbrannt ist, weil unsere Väter den Weisungen dieses Buches nicht gehorcht haben, um das genau zu befolgen, was darin geschrieben steht.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 22, 14, 'Da begab sich der Priester Hilkia mit Ahikam, Achbor, Saphan und Asaja zu der Prophetin Hulda, der Frau des Kleiderhüters Sallum, des Sohnes Thikwas, des Sohnes Harhas; die wohnte zu Jerusalem im zweiten Bezirk. Als sie sich mit ihr besprachen,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 22, 15, 'sagte sie zu ihnen: »So hat der HERR, der Gott Israels, gesprochen: ›Sagt dem Mann, der euch zu mir gesandt hat:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 22, 16, 'So hat der HERR gesprochen: ›Wisset wohl: ich will Unglück über diesen Ort und seine Bewohner kommen lassen, nämlich alle Drohungen des Buches, das der König von Juda gelesen hat.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 22, 17, 'Zur Strafe dafür, daß sie mich verlassen und anderen Göttern geopfert haben, um mich mit all dem Machwerk ihrer Hände zum Zorn zu reizen, soll mein Grimm gegen diesen Ort entbrennen und nicht wieder erlöschen!‹');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 22, 18, 'Aber zum König von Juda, der euch gesandt hat, um den HERRN zu befragen, zu dem sollt ihr so sagen: ›So hat der HERR, der Gott Israels, gesprochen: Was die Drohungen betrifft, die du vernommen hast:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 22, 19, 'weil dein Herz weich geworden ist und du dich vor dem HERRN gedemütigt hast, als du vernahmst, was ich diesem Ort und seinen Bewohnern angedroht habe, daß sie nämlich zu einem abschreckenden Beispiel und zu einem Fluch werden sollen, und weil du deine Kleider zerrissen und vor mir geweint hast, so habe auch ich dir Gehör geschenkt‹ – so lautet der Ausspruch des HERRN.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 22, 20, '›Darum wisse wohl: ich will dich zu deinen Vätern versammeln, daß du in Frieden in deine Grabstätte gebracht wirst, und deine Augen sollen all das Unglück, das ich über diesen Ort bringen werde, nicht zu sehen bekommen!‹«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 1, 'Als sie nun dem König Bericht erstattet hatten, sandte der König Boten aus, daß sie alle Ältesten von Juda und Jerusalem bei ihm versammelten.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 2, 'Hierauf ging der König zum Tempel des HERRN hinauf und mit ihm alle Männer von Juda und alle Bewohner Jerusalems, auch die Priester und die Propheten, überhaupt das ganze Volk, klein und groß; und er las ihnen den ganzen Inhalt des Bundesbuches vor, das man im Tempel des HERRN gefunden hatte.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 3, 'Hierauf trat der König an die Säule und schloß den Bund vor dem HERRN, daß sie dem HERRN nachwandeln und seine Gebote, seine Verordnungen und seine Satzungen mit ganzem Herzen und mit ganzer Seele beobachten wollten, um so den Bestimmungen dieses Bundes, die in diesem Buche geschrieben standen, Geltung zu verschaffen. Und das gesamte Volk trat dem Bunde bei.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 4, 'Hierauf befahl der König dem Hohenpriester Hilkia und den Priestern zweiter Ordnung und den Schwellenhütern, alle Geräte, die für Baal und Astarte und für das ganze Sternenheer des Himmels angefertigt worden waren, aus dem Tempel des HERRN hinauszuschaffen; er ließ sie dann außerhalb Jerusalems auf den Feldern am Kidron verbrennen und ihre Asche nach Bethel bringen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 5, 'Sodann setzte er die Götzenpriester ab, welche die Könige von Juda eingesetzt hatten und die auf den Höhen in den Ortschaften Judas und in der Umgegend von Jerusalem geopfert, sowie die, welche dem Baal, der Sonne und dem Monde, den Bildern des Tierkreises und dem ganzen Sternenheer des Himmels Opfer dargebracht hatten.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 6, 'Ferner ließ er das Standbild der Aschera aus dem Tempel des HERRN hinaus vor die Tore Jerusalems in das Kidrontal schaffen und es dort verbrennen und zu Staub zerstampfen und den Staub davon auf die Gräber der gemeinen Leute werfen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 7, 'Sodann ließ er die Stuben der Heiligtumsbuhler niederreißen, die sich im Tempel des HERRN befanden und in denen die Weiber Hüllen für Astarte zu weben pflegten.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 8, 'Weiter ließ er alle Priester aus den Ortschaften Judas kommen und die Höhen entweihen, auf denen die Priester geopfert hatten, von Geba bis Beerseba; auch ließ er die Höhen der Bocksgestalten niederreißen, die am Eingang des Tores des Stadthauptmannes Josua auf der linken Seite standen, wenn man zum Stadttor hineinging.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 9, 'Doch durften die Höhenpriester nicht den Opferdienst auf dem Altar des HERRN in Jerusalem versehen, wohl aber aßen sie die ungesäuerten Brote inmitten ihrer Amtsbrüder.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 10, 'Auch die Greuelstätte, die im Tal Ben-Hinnom lag, ließ er entweihen, damit niemand mehr seinen Sohn oder seine Tochter dem Moloch als Brandopfer darbrächte.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 11, 'Ferner ließ er die Rosse beseitigen, welche die Könige von Juda zu Ehren des Sonnengottes am Eingang zum Tempel des HERRN in der Richtung nach der Zelle des Kämmerers Nethan-Melech, im Parwarim aufgestellt hatten, und ließ den Sonnenwagen im Feuer verbrennen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 12, 'Auch die Altäre, die auf dem Dach, dem Söller des Ahas, standen und von den Königen von Juda herrührten, sowie die Altäre, welche Manasse in den beiden Vorhöfen des Tempels des HERRN errichtet hatte, ließ der König niederreißen und zerschlagen und den Schutt von ihnen in das Kidrontal werfen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 13, 'Auch die Höhen, die östlich von Jerusalem, südlich vom Unheilsberge lagen, die der König Salomo von Israel zu Ehren der Astarte, des greulichen Götzen der Sidonier, und für Kamos, das Scheusal der Moabiter, und für Milkom, den greulichen Götzen der Ammoniter, errichtet hatte, ließ der König entweihen;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 14, 'ebenso zertrümmerte er die Malsteine und ließ die Götzenbäume umhauen und ihren Platz mit Menschengebeinen anfüllen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 15, 'Aber auch den Altar zu Bethel, die Höhe, welche Jerobeam, der Sohn Nebats, der Israel zur Sünde verführte, hergestellt hatte, auch diesen Altar samt der Höhe ließ er niederreißen; er verwüstete die Höhe mit Feuer, zermalmte sie zu Staub und verbrannte das Standbild der Aschera.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 16, 'Als Josia dabei umherblickte und die Gräber dort am Bergabhang wahrnahm, sandte er Leute hin, ließ die Gebeine aus den Gräbern herausnehmen und auf dem Altar verbrennen und entweihte ihn auf diese Weise gemäß der Drohung des HERRN, die der Gottesmann einst ausgesprochen hatte, der diese Dinge voraussagte.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 17, 'Als er dann fragte: »Was ist das für ein Grabmal, das ich dort sehe?«, antworteten ihm die Leute der Stadt: »Das ist das Grab des Gottesmannes, der aus Juda gekommen war und das angesagt hat, was du jetzt am Altar von Bethel getan hast.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 18, 'Da befahl er: »Laßt ihn liegen, niemand störe seine Gebeine in ihrer Ruhe!« So ließ man denn seine Gebeine unversehrt samt den Gebeinen des Propheten, der aus Samaria war. –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 19, 'Außerdem beseitigte Josia auch alle Höhenheiligtümer, die sich in den Ortschaften Samarias befanden und die von den israelitischen Königen angelegt waren, um (den HERRN) zum Zorn zu reizen; er verfuhr mit ihnen gerade so, wie er zu Bethel verfahren war.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 20, 'Alle Höhenpriester aber, die daselbst waren, ließ er auf den Altären schlachten und Menschengebeine darauf verbrennen; alsdann kehrte er nach Jerusalem zurück.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 21, 'Hierauf ließ der König folgenden Befehl an das ganze Volk ergehen: »Feiert das Passahfest zu Ehren des HERRN, eures Gottes, so wie es in diesem Bundesbuche geschrieben steht!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 22, 'Denn ein solches Passah wie dieses war nicht gefeiert worden seit der Zeit der Richter, die in Israel gewaltet hatten, und während der ganzen Zeit der Könige von Israel und der Könige von Juda;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 23, 'vielmehr erst im achtzehnten Regierungsjahre des Königs Josia wurde dieses Passah zu Ehren des HERRN in Jerusalem begangen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 24, 'Außerdem rottete Josia auch die Totenbeschwörer und Zeichendeuter, die Hausgötter und die Götzen, überhaupt alle Abgötter aus, die im Lande Juda und in Jerusalem zu sehen waren, um den Bestimmungen des Gesetzes nachzukommen, die in dem Buch, das der Priester Hilkia im Tempel des HERRN gefunden hatte, geschrieben standen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 25, 'Und seinesgleichen hat es vor ihm keinen König gegeben, der sich so von ganzem Herzen, von ganzer Seele und mit aller seiner Kraft dem HERRN ganz nach dem mosaischen Gesetze zugewandt hätte, und auch nach ihm ist keiner seinesgleichen erstanden.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 26, 'Gleichwohl ließ der HERR von der gewaltigen Glut seines Zornes nicht ab, weil sein Zorn einmal gegen Juda entbrannt war wegen all der Ärgernisse, durch die Manasse ihn erbittert hatte.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 27, 'Daher sprach der HERR: »Auch Juda will ich mir aus den Augen schaffen, wie ich Israel verstoßen habe, und will diese Stadt verwerfen, die ich einst erwählt hatte, Jerusalem, und das Haus, von dem ich einst gesagt hatte, mein Name solle daselbst wohnen.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 28, 'Die übrige Geschichte Josias aber und alles, was er unternommen hat, das findet sich bekanntlich aufgezeichnet im Buch der Denkwürdigkeiten der Könige von Juda.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 29, 'Während seiner Regierung zog der Pharao Necho, der König von Ägypten, gegen den König von Assyrien zu Felde an den Euphratstrom. Der König Josia zog ihm entgegen, aber (Necho) tötete ihn bei Megiddo, sobald er seiner ansichtig geworden war.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 30, 'Da fuhren seine Diener ihn zu Wagen tot von Megiddo hinweg, brachten ihn nach Jerusalem und setzten ihn in seiner Grabstätte bei. Die Landbevölkerung nahm dann Joahas, den Sohn Josias, salbte ihn und machte ihn zum König an seines Vaters Statt.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 31, 'Im Alter von dreiundzwanzig Jahren wurde Joahas König und regierte drei Monate in Jerusalem; seine Mutter hieß Hamutal und war die Tochter Jeremias von Libna.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 32, 'Er tat, was dem HERRN mißfiel, ganz so wie seine Väter getan hatten.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 33, 'Der Pharao Necho aber ließ ihn zu Ribla in der Landschaft Hamath ins Gefängnis werfen, damit er nicht länger König in Jerusalem wäre, und legte dem Lande eine Geldbuße von hundert Talenten Silber und einem Talent Gold auf.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 34, 'Sodann machte der Pharao Necho Eljakim, den Sohn Josias, zum König an Stelle seines Vaters Josia und änderte seinen Namen in Jojakim ab; den Joahas aber nahm er mit sich; so kam dieser nach Ägypten und starb daselbst.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 35, 'Das Silber und das Gold lieferte Jojakim dem Pharao ab, mußte jedoch seinem Lande eine besondere Steuer auferlegen, um das Geld nach der Forderung des Pharaos zahlen zu können: je nachdem ein jeder abgeschätzt worden war, trieb er das Silber und das Gold von der Bevölkerung des Landes ein, um es dann dem Pharao Necho zu übergeben.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 36, 'Im Alter von fünfundzwanzig Jahren wurde Jojakim König und regierte elf Jahre in Jerusalem; seine Mutter hieß Sebudda und war die Tochter Pedajas aus Ruma.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 37, 'Er tat, was dem HERRN mißfiel, ganz so wie seine Väter getan hatten.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 24, 1, 'Während seiner Regierung kam Nebukadnezar, der König von Babylon, herangezogen, und Jojakim wurde ihm drei Jahre lang untertan, fiel dann aber wieder von ihm ab.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 24, 2, 'Da ließ Gott der HERR die Kriegsscharen der Chaldäer und der Syrer sowie die Scharen der Moabiter und der Ammoniter gegen ihn heranziehen; die ließ er in Juda einfallen, um es zugrunde zu richten, gemäß der Drohung, die der HERR durch den Mund seiner Knechte, der Propheten, hatte aussprechen lassen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 24, 3, 'Nur nach dem Ausspruch des HERRN ist dies Unheil über Juda hereingebrochen, damit er es sich aus den Augen schaffte wegen der Sünden Manasses, infolge alles dessen, was er verübt hatte;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 24, 4, 'besonders auch das unschuldige Blut, das er vergossen hatte, so daß er Jerusalem mit unschuldigem Blut anfüllte, auch das wollte der HERR nicht vergeben.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 24, 5, 'Die übrige Geschichte Jojakims aber und alles, was er unternommen hat, das findet sich bekanntlich aufgezeichnet im Buch der Denkwürdigkeiten der Könige von Juda.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 24, 6, 'Als Jojakim sich dann zu seinen Vätern gelegt hatte, folgte ihm sein Sohn Jojachin als König in der Regierung nach.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 24, 7, 'Der König von Ägypten aber unternahm fortan keinen Kriegszug mehr aus seinem Lande; denn der König von Babylon hatte alles in Besitz genommen, was dem König von Ägypten gehört hatte, vom Bach Ägyptens an bis zum Euphratstrom.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 24, 8, 'Im Alter von achtzehn Jahren wurde Jojachin König und regierte drei Monate in Jerusalem; seine Mutter hieß Nehustha und war die Tochter Elnathans aus Jerusalem.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 24, 9, 'Er tat, was dem HERRN mißfiel, ganz so wie sein Vater getan hatte.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 24, 10, 'Zu jener Zeit zogen die Heerführer Nebukadnezars, des Königs von Babylon, gegen Jerusalem heran, und die Stadt wurde eingeschlossen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 24, 11, 'Als dann Nebukadnezar, der König von Babylon, selbst vor der Stadt ankam, während seine Heerführer sie belagerten,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 24, 12, 'ging Jojachin, der König von Juda, zum König von Babylon hinaus, er mit seiner Mutter, seinen Hofbeamten, seinen Heeresobersten und seinen Kämmerlingen, und der König von Babylon nahm ihn im achten Jahre seiner Regierung gefangen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 24, 13, 'Er ließ dann alle Schätze des Tempels des HERRN und die Schätze des königlichen Palastes von dort wegbringen und brach den Metallbeschlag von allen goldenen Geräten ab, die Salomo, der König von Israel, für den Tempel des HERRN hatte anfertigen lassen: wie der HERR es angekündigt hatte.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 24, 14, 'Ganz Jerusalem aber führte er in die Gefangenschaft: alle hohen Beamten und alle kriegstüchtigen Männer, zehntausend Gefangene, dazu alle Schmiede und Schlosser: nichts blieb zurück außer der niederen Bevölkerung des Landes.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 24, 15, 'Auch Jojachin führte er nach Babylon in die Gefangenschaft, ebenso die Mutter des Königs und die königlichen Frauen; auch seine Kämmerlinge und die vornehmsten Männer des Landes führte er als Gefangene von Jerusalem weg nach Babylon;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 24, 16, 'dazu alle kriegstüchtigen Männer, siebentausend an Zahl, ferner die Schmiede und Schlosser, tausend an Zahl, lauter kriegstüchtige, streitbare Männer; die brachte der König von Babylon als Gefangene nach Babylon.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 24, 17, 'Hierauf machte der König von Babylon Matthanja, den Oheim Jojachins, zum König an dessen Stelle und änderte seinen Namen in Zedekia ab.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 24, 18, 'Im Alter von einundzwanzig Jahren kam Zedekia auf den Thron und regierte elf Jahre in Jerusalem; seine Mutter hieß Hamutal und war die Tochter Jeremias aus Libna.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 24, 19, 'Er tat, was dem HERRN mißfiel, ganz wie Jojakim getan hatte.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 24, 20, 'Denn infolge des Zornes des HERRN kam es mit Jerusalem und Juda dahin, daß der HERR sie von seinem Angesicht verstieß.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 25, 1, 'Als Zedekia aber vom König von Babylon abgefallen war, da – es war im neunten Jahre seiner Regierung, am zehnten Tage des zehnten Monats – kam Nebukadnezar, der König von Babylon, in eigener Person mit seiner ganzen Heeresmacht gegen Jerusalem herangezogen und belagerte es. Man führte rings um die Stadt Belagerungswerke auf,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 25, 2, 'und die Stadt blieb dann eingeschlossen bis ins elfte Jahr der Regierung Zedekias.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 25, 3, 'Am neunten Tage des (vierten) Monats, als die Hungersnot in der Stadt übermächtig geworden war und die Landbevölkerung kein Brot mehr hatte,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 25, 4, 'da wurde die Stadtmauer durchbrochen, und alle Kriegsleute ergriffen nachts die Flucht auf dem Wege durch das Tor zwischen den beiden Mauern, das am Königsgarten liegt, während die Chaldäer noch rings um die Stadt her lagen; und man wandte sich dann der Jordanebene zu.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 25, 5, 'Aber das Heer der Chaldäer setzte dem Könige nach und holte ihn in den Steppen von Jericho ein, nachdem sein ganzes Heer sich zerstreut und ihn verlassen hatte.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 25, 6, 'So wurde denn der König gefangengenommen und zum König von Babylon nach Ribla hinaufgeführt, wo man Gericht über ihn hielt.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 25, 7, 'Die Söhne Zedekias ließ er vor dessen Augen grausam hinrichten; Zedekia aber ließ er blenden und in Ketten legen; dann brachte man ihn nach Babylon.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 25, 8, 'Am siebten Tage des fünften Monats aber – das war das neunzehnte Regierungsjahr des Königs Nebukadnezar, des Königs von Babylon – kam Nebusaradan, der Befehlshaber der Leibwache, der dem Könige von Babylon besonders nahe stand, nach Jerusalem');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 25, 9, 'und verbrannte den Tempel des HERRN sowie den königlichen Palast und alle Häuser in Jerusalem: alle größeren Häuser ließ er in Flammen aufgehen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 25, 10, 'Sodann mußte das ganze chaldäische Heer, welches der Befehlshaber der Leibwache bei sich hatte, die Mauern rings um Jerusalem niederreißen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 25, 11, 'Den Rest des Volkes aber, was an Einwohnern in der Stadt noch übriggeblieben war, und die Überläufer, die zum König von Babylon übergegangen waren, [sowie den Rest der Werkleute] ließ Nebusaradan, der Befehlshaber der Leibwache, in die Gefangenschaft nach Babylon führen;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 25, 12, 'von der niederen Bevölkerung des Landes aber ließ der Befehlshaber der Leibwache einen Teil als Weingärtner und Ackerleute zurück.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 25, 13, 'Aber die ehernen Säulen, die am Tempel des HERRN standen, sowie die Gestühle und das große eherne Wasserbecken, die beim Tempel des HERRN waren, zerschlugen die Chaldäer und nahmen das Erz davon mit sich nach Babylon.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 25, 14, 'Auch die Kessel, Schaufeln, Messer zum Lichtputzen, die Schalen und alle übrigen ehernen Geräte, die man beim Gottesdienst gebraucht hatte, nahmen sie weg;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 25, 15, 'ebenso die Kohlenpfannen und Sprengschalen, alles, was ganz aus Gold oder ganz aus Silber bestand, nahm der Befehlshaber der Leibwache weg.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 25, 16, 'Was die beiden Säulen sowie das eine große Wasserbecken und die Gestühle betrifft, die Salomo für den Tempel des HERRN hatte anfertigen lassen, so war es unmöglich, das Erz aller dieser Kunstwerke zu wägen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 25, 17, 'Achtzehn Ellen war die eine Säule hoch, und ein Knauf von Erz befand sich oben darauf; die Höhe des Knaufes betrug drei Ellen, und ein Flechtwerk und Granatäpfel waren ringsum an dem Knauf angebracht, alles von Erz; ebenso war auch die andere Säule beschaffen nebst dem Flechtwerk.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 25, 18, 'Weiter ließ der Befehlshaber der Leibwache den Oberpriester Seraja, den Unterpriester Zephanja und die drei Schwellenhüter verhaften;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 25, 19, 'ferner nahm er aus der Stadt den einen Kämmerer fest, der den Oberbefehl über das Kriegsvolk gehabt hatte, sowie fünf Männer von denen, die zu der ständigen Umgebung des Königs gehört hatten und die in der Stadt vorgefunden wurden, außerdem den Schreiber des Feldhauptmanns, der das Landvolk zum Heeresdienst ausgehoben hatte, außerdem sechzig Personen von der Landbevölkerung, die noch in der Stadt angetroffen worden waren.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 25, 20, 'Diese nahm Nebusaradan, der Befehlshaber der Leibwache, und brachte sie zum König von Babylon nach Ribla;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 25, 21, 'der König von Babylon aber ließ sie zu Ribla in der Landschaft Hamath grausam hinrichten. So wurde Juda von seinem heimischen Boden gefangen weggeführt.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 25, 22, 'Über das Volk aber, das im Lande Juda zurückgeblieben war, weil Nebukadnezar, der König von Babylon, es übriggelassen hatte, über diese setzte er Gedalja, den Sohn Ahikams, des Sohnes Saphans, als Statthalter ein.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 25, 23, 'Als nun alle Truppenführer samt ihren Leuten erfuhren, daß der König von Babylon Gedalja zum Statthalter bestellt habe, da begaben sie sich zu Gedalja nach Mizpa, nämlich Ismael, der Sohn Nethanjas, Johanan, der Sohn Kareahs, Seraja, der Sohn Thanhumeths aus Netopha, und Jaasanja, der Sohn eines Maachathiters, samt ihren Leuten.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 25, 24, 'Da richtete Gedalja an sie und ihre Leute unter feierlicher Anrufung Gottes folgende Ansprache: »Fürchtet euch nicht vor den Beamten der Chaldäer! Bleibt im Lande und seid dem König von Babylon untertan: ihr werdet euch gut dabei stehen!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 25, 25, 'Aber im siebenten Monat kam Ismael, der Sohn Nethanjas, des Sohnes Elisamas, ein Mann von königlicher Abkunft, und mit ihm zehn Männer; die erschlugen Gedalja samt den Judäern und Chaldäern, die bei ihm in Mizpa waren.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 25, 26, 'Da machte sich das ganze Volk, klein und groß, mitsamt den Truppenführern auf und zog nach Ägypten; denn sie fürchteten sich vor den Chaldäern.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 25, 27, 'Aber im siebenunddreißigsten Jahr der Wegführung Jojachins, des Königs von Juda, am siebenundzwanzigsten Tage des zwölften Monats, begnadigte Ewil-Merodach, der König von Babylon, – im Jahre seines Regierungsantritts – den König Jojachin von Juda und entließ ihn aus dem Gefängnis.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 25, 28, 'Er redete freundlich mit ihm und wies ihm seinen Sitz an über den Sitz der anderen Könige, die bei ihm in Babylon waren.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 25, 29, 'Da durfte er auch seine Gefangenenkleidung ablegen und speiste regelmäßig an der königlichen Tafel, solange er noch lebte.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 25, 30, 'Sein Unterhalt aber wurde ihm als ständiger Unterhalt, soviel er täglich bedurfte, von seiten des Königs bis zu seinem Todestage zugewiesen, solange er noch lebte.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 1, 'Adam, Seth, Enos,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 2, 'Kenan, Mahalaleel, Jared,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 3, 'Henoch, Methusalah, Lamech,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 4, 'Noah, Sem, Ham und Japheth.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 5, 'Die Söhne Japheths waren: Gomer, Magog, Madai, Jawan, Thubal, Mesech und Thiras.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 6, 'Und die Söhne Gomers: Askenas, Diphath und Thogarma.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 7, 'Und die Söhne Jawans: Elisa, Tharsis, die Kitthiter und die Rodaniter.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 8, 'Die Söhne Hams waren: Kusch und Mizraim, Put und Kanaan.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 9, 'Und die Söhne Kuschs: Seba, Hawila, Sabtha, Ragma und Sabthecha; und die Söhne Ragmas: Seba und Dedan.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 10, 'Kusch war der Vater Nimrods; dieser war der erste Gewaltherrscher auf der Erde.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 11, 'Und Mizraim war der Stammvater der Luditer, der Anamiter, der Lehabiter, der Naphthuhiter,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 12, 'der Pathrusiter, der Kasluhiter – von denen die Philister ausgegangen sind – und der Kaphthoriter.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 13, 'Kanaan aber hatte zu Söhnen: Sidon, seinen Erstgeborenen, und den Heth,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 14, 'ferner die Jebusiter, Amoriter, Girgasiter,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 15, 'Hewiter, Arkiter, Siniter,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 16, 'Arwaditer, Zemariter und Hamathiter.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 17, 'Die Söhne Sems waren: Elam, Assur, Arpachsad, Lud, Aram, Uz, Hul, Gether und Mesech.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 18, 'Arpachsad aber war der Vater Selahs, und Selah war der Vater Ebers.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 19, 'Und dem Eber wurden zwei Söhne geboren: der eine hieß Peleg, weil zu seiner Zeit die Bevölkerung der Erde sich teilte, und sein Bruder hieß Joktan.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 20, 'Und Joktan hatte zu Söhnen: Almodad, Seleph, Hazarmaweth, Jerah,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 21, 'Hadoram, Usal, Dikla,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 22, 'Ebal, Abimael, Seba,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 23, 'Ophir, Hawila und Jobab; diese alle waren Söhne Joktans.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 24, 'Sem, Arpachsad, Selah,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 25, 'Eber, Peleg, Regu,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 26, 'Serug, Nahor, Therah,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 27, 'Abram, das ist Abraham.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 28, 'Die Söhne Abrahams waren: Isaak und Ismael.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 29, 'Dies ist ihr Stammbaum: der Erstgeborene Ismaels Nebajoth; sodann Kedar, Adbeel, Mibsam,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 30, 'Misma, Duma, Massa, Hadad, Thema,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 31, 'Jetur, Naphis und Kedma; das sind die Söhne Ismaels.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 32, 'Und die Söhne der Ketura, der Nebenfrau Abrahams: sie gebar Simran, Joksan, Medan, Midian, Jisbak und Suah. Und die Söhne Joksans waren: Seba und Dedan.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 33, 'Und die Söhne Midians: Epha, Epher, Hanoch, Abida und Eldaa. Diese alle waren Söhne oder Enkel der Ketura.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 34, 'Abraham aber war der Vater Isaaks; die Söhne Isaaks waren: Esau und Israel.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 35, 'Die Söhne Esaus waren: Eliphas, Reguel, Jegus, Jaglam und Korah.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 36, 'Die Söhne des Eliphas waren: Theman, Omar, Zephi, Gaetham, Kenas, Thimna und Amalek.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 37, 'Die Söhne Reguels waren: Nahath, Serah, Samma und Missa. –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 38, 'Und die Söhne Seirs: Lotan, Sobal, Zibeon, Ana, Dison, Ezer und Disan.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 39, 'Und die Söhne Lotans: Hori und Homam; und die Schwester Lotans war Thimna.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 40, 'Die Söhne Sobals waren: Aljan, Manahath, Ebal, Sephi und Onam; und die Söhne Zibeons: Ajja und Ana.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 41, 'Die Söhne Anas waren: Dison; und die Söhne Disons: Hamran, Esban, Jithran und Cheran.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 42, 'Die Söhne Ezers waren: Bilhan, Saawan und Jaakan. Die Söhne Disans waren: Uz und Aran.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 43, 'Und dies sind die Könige, die im Lande Edom geherrscht haben, ehe ein König über die Israeliten herrschte: Bela, der Sohn Beors; seine Stadt hieß Dinhaba.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 44, 'Nach dem Tode Belas wurde Jobab, der Sohn Serahs, aus Bozra, König an seiner Statt.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 45, 'Nach dem Tode Jobabs wurde Husam aus dem Lande der Themaniter König an seiner Statt.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 46, 'Nach dem Tode Husams wurde Hadad, der Sohn Bedads, König an seiner Statt, derselbe, der die Midianiter auf der Hochebene der Moabiter schlug; seine Stadt hieß Awith.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 47, 'Nach dem Tode Hadads wurde Samla aus Masreka König an seiner Statt.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 48, 'Nach dem Tode Samlas wurde Saul aus Rehoboth am Euphratstrom König an seiner Statt.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 49, 'Nach dem Tode Sauls wurde Baal-Hanan, der Sohn Achbors, König an seiner Statt.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 50, 'Nach dem Tode Baal-Hanans wurde Hadad König an seiner Statt: seine Stadt hieß Pagi, und seine Frau hieß Mehetabeel, eine Tochter Matreds, eine Enkelin Mesahabs. –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 51, 'Nach dem Tode Hadads waren die Häuptlinge der Edomiter: der Häuptling Thimna, der Häuptling Alja, der Häuptling Jetheth,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 52, 'der Häuptling Oholibama, der Häuptling Ela, der Häuptling Pinon,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 53, 'der Häuptling Kenas, der Häuptling Theman, der Häuptling Mibzar,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 54, 'der Häuptling Magdiel, der Häuptling Iram. Dies sind die Häuptlinge der Edomiter.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 1, 'Dies sind die Söhne Israels: Ruben, Simeon, Levi und Juda, Issaschar und Sebulon,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 2, 'Dan, Joseph und Benjamin, Naphthali, Gad und Asser.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 3, 'Die Söhne Judas waren: Ger, Onan und Sela; diese drei wurden ihm von der Tochter der Kanaanitin Sua geboren. Ger aber, der erstgeborene Sohn Judas, machte sich dem HERRN verhaßt; darum ließ er ihn sterben.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 4, 'Thamar aber, seine Schwiegertochter, hatte ihm Perez und Serah geboren, so daß die Gesamtzahl der Söhne Judas fünf war.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 5, 'Die Söhne des Perez waren: Hezron und Hamul;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 6, 'und die Söhne Serahs: Simri, Ethan, Heman, Chalkol und Dara, im ganzen fünf. –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 7, 'Und die Söhne Karmis: Achar, der Israel ins Unglück stürzte, weil er sich an gebanntem Gut vergriff.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 8, 'Und die Söhne Ethans: Asarja.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 9, 'Und die Söhne Hezrons, die ihm geboren wurden: Jerahmeel, Ram und Kelubai.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 10, 'Ram aber zeugte Amminadab; und Amminadab zeugte Nahasson, den Fürsten der Judäer;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 11, 'und Nahasson zeugte Salma; Salma zeugte Boas,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 12, 'Boas zeugte Obed, Obed zeugte Isai;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 13, 'Isai zeugte Eliab, seinen Erstgeborenen, und Abinadab als zweiten, Simea als dritten,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 14, 'Nethaneel als vierten, Raddai als fünften,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 15, 'Ozem als sechsten, David als siebten.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 16, 'Und ihre Schwestern waren: Zeruja und Abigail; und die Söhne der Zeruja waren: Abisai, Joab und Asahel, die drei.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 17, 'Abigail aber gebar Amasa, und der Vater Amasas war der Ismaelit Jether.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 18, 'Kaleb aber, der Sohn Hezrons, hatte Kinder von seiner Frau Asuba und von Jerigoth; und dies sind deren Söhne: Jeser, Sobab und Ardon.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 19, 'Nach dem Tode der Asuba aber heiratete Kaleb die Ephrath; die gebar ihm den Hur.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 20, 'Hur aber zeugte Uri, und Uri zeugte Bezaleel. –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 21, 'Darnach verband sich Hezron mit der Tochter Machirs, des Vaters Gileads, und heiratete sie, als er sechzig Jahre alt war; die gebar ihm den Segub.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 22, 'Segub zeugte dann Jair; der besaß dreiundzwanzig Städte im Lande Gilead;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 23, 'aber die Gesuriter und Syrer nahmen ihnen die Jairdörfer weg, Kenath mit den zugehörigen Ortschaften, sechzig Städte. Diese alle waren Söhne Machirs, des Vaters Gileads.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 24, 'Und nach dem Tode Hezrons in Kaleb Ephratha gebar Abia, Hezrons Frau, ihm Ashur, den Stammvater von Thekoa.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 25, 'Die Söhne Jerahmeels, des ältesten Sohnes Hezrons, waren: der Erstgeborene Ram, sodann Buna, Oren und Ozem von Ahija.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 26, 'Jerahmeel hatte aber noch eine andere Frau namens Atara; diese war die Mutter Onams. –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 27, 'Die Söhne Rams, des erstgeborenen Sohnes Jerahmeels, waren: Maaz, Jamin und Eker. –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 28, 'Die Söhne Onams waren: Sammai und Jada; und die Söhne Sammais: Nadab und Abisur.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 29, 'Die Frau Abisurs aber hieß Abihail; die gebar ihm den Achban und Molid.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 30, 'Und die Söhne Nadabs waren: Seled und Appaim; Seled aber starb kinderlos. –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 31, 'Und die Söhne Appaims waren: Jisei; und die Söhne Jiseis: Sesan; und die Söhne Sesans: Achlai. –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 32, 'Die Söhne Jadas, des Bruders Sammais, waren: Jether und Jonathan; Jether aber starb kinderlos.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 33, 'Die Söhne Jonathans waren: Peleth und Sasa. Dies waren die Söhne Jerahmeels. –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 34, 'Sesan hatte keine Söhne, sondern nur Töchter; er hatte aber einen ägyptischen Knecht namens Jarha.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 35, 'Diesem gab Sesan seine Tochter zur Frau; die gebar ihm Atthai.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 36, 'Atthai zeugte dann Nathan, und Nathan zeugte Sabad;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 37, 'Sabad zeugte Ephlal, Ephlal zeugte Obed,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 38, 'Obed zeugte Jehu, Jehu zeugte Asarja,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 39, 'Asarja zeugte Helez, Helez zeugte Elasa,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 40, 'Elasa zeugte Sisemai, Sisemai zeugte Sallum,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 41, 'Sallum zeugte Jekamja, Jekamja zeugte Elisama.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 42, 'Die Söhne Kalebs, des Bruders Jerahmeels, waren: sein Erstgeborener Mesa – der ist der Vater Siphs – und die Söhne Maresas, des Vaters von Hebron.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 43, 'Die Söhne Hebrons waren: Korah, Thappuah, Rekem und Sema.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 44, 'Sema aber zeugte Raham, den Vater Jorkeams; und Rekem zeugte Sammai.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 45, 'Der Sohn Sammais war Maon, und Maon war der Vater Beth-Zurs. –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 46, 'Und Epha, das Nebenweib Kalebs, gebar Haran, Moza und Gases; Haran aber zeugte Gases. –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 47, 'Und die Söhne Jahdais waren: Regem, Jotham, Geesan, Pelet, Epha und Saaph. –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 48, 'Maacha, das Nebenweib Kalebs, gebar Seber und Thirhana;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 49, 'sie gebar auch Saaph, den Vater Madmannas, und Sewa, den Vater Machbenas und den Vater Gibeas; und die Tochter Kalebs war Achsa.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 50, 'Dies waren die Söhne Kalebs. Die Söhne Hurs, des Erstgeborenen von der Ephratha, waren: Sobal, der Stammvater von Kirjath-Jearim,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 51, 'Salma, der Stammvater von Bethlehem, Hareph, der Stammvater von Beth-Gader.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 52, 'Und Sobal, der Stammvater von Kirjath-Jearim, hatte als Söhne: Haroe, halb Menuhoth;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 53, 'und die Geschlechter von Kirjath-Jearim waren: die Jithriter, die Puthiter, die Sumathiter und die Misraiter; von diesen sind die Zorathiter und die Esthauliter ausgegangen. –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 54, 'Die Söhne Salmas waren: Bethlehem und die Netophathiter, Ateroth, Beth-Joab und die Hälfte der Manahthiter, die Zoreiter;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 55, 'und die Geschlechter der Schriftgelehrten, die in Jabez wohnten: die Thireathiter, die Simeathiter und die Suchathiter. Das sind die Kiniter, die von Hammath, dem Stammvater des Hauses Rechab, abstammen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 3, 1, 'Dies waren die Söhne Davids, die ihm in Hebron geboren wurden: Der Erstgeborene war Amnon, von der Jesreelitin Ahinoam; der zweite Daniel, von der Karmelitin Abigail;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 3, 2, 'der dritte Absalom, der Sohn der Maacha, der Tochter des Königs Thalmai von Gesur; der vierte Adonia, der Sohn der Haggith;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 3, 3, 'der fünfte Sephatja, von Abital; der sechste Jithream, von seiner Frau Egla.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 3, 4, 'Diese sechs wurden ihm in Hebron geboren; dort regierte er sieben Jahre und sechs Monate; aber in Jerusalem regierte er dreiunddreißig Jahre.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 3, 5, 'Folgende aber wurden ihm in Jerusalem geboren: Simea, Sobab, Nathan und Salomo, zusammen vier, von Bath-Sewa, der Tochter Ammiels;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 3, 6, 'ferner Jibhar, Elisua, Eliphelet,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 3, 7, 'Nogah, Nepheg, Japhia,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 3, 8, 'Elisama, Eljada und Eliphelet, zusammen neun.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 3, 9, 'Dies sind allesamt Söhne Davids, außer den Söhnen von Nebenweibern; und Thamar war ihre Schwester.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 3, 10, 'Salomos Sohn war Rehabeam; dessen Sohn war Abija, dessen Sohn Asa, dessen Sohn Josaphat,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 3, 11, 'dessen Sohn Joram, dessen Sohn Ahasja, dessen Sohn Joas,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 3, 12, 'dessen Sohn Amazja, dessen Sohn Asarja, dessen Sohn Jotham,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 3, 13, 'dessen Sohn Ahas, dessen Sohn Hiskia, dessen Sohn Manasse,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 3, 14, 'dessen Sohn Amon, dessen Sohn Josia. –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 3, 15, 'Und die Söhne Josias waren: der Erstgeborene Johanan, der zweite Jojakim, der dritte Zedekia, der vierte Sallum.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 3, 16, 'Die Söhne Jojakims waren: sein Sohn Jechonja; dessen Sohn war Zedekia.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 3, 17, 'Die Söhne Jechonjas, des Gefangenen, waren: sein Sohn Sealthiel,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 3, 18, 'Malchiram, Pedaja, Sena’azzar, Jekamja, Hosama und Nebadja.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 3, 19, 'Die Söhne Pedajas waren: Serubbabel und Simei; und die Söhne Serubbabels: Mesullam und Hananja, und deren Schwester war Selomith;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 3, 20, 'und (die Söhne Mesullams waren:) Hasuba, Ohel, Berechja, Hasadja, Jusab-Hesed, zusammen fünf.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 3, 21, 'Die Söhne Hananjas waren: Pelatja und Jesaja; die Söhne Rephajas, die Söhne Arnans, die Söhne Obadjas, die Söhne Sechanjas.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 3, 22, 'Die Söhne Sechanjas waren: Semaja; und die Söhne Semajas: Hattus, Jigeal, Bariah, Nearja und Saphat, zusammen sechs.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 3, 23, 'Die Söhne Nearjas waren: Eljoenai, Hiskia und Asrikam, zusammen drei.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 3, 24, 'Die Söhne Eljoenais aber waren: Hodawja, Eljasib, Pelaja, Akkub, Johanan, Delaja und Anani, zusammen sieben.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 1, 'Die Söhne Judas waren: Perez, Hezron, Karmi, Hur und Sobal.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 2, 'Reaja aber, der Sohn Sobals, zeugte Jahath; Jahath zeugte Ahumai und Lahad. Dies sind die Geschlechter der Zoreathiter. –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 3, 'Und dies sind die Söhne Hurs, des Vaters Etams: Jesreel, Jisma und Jidbas; und ihre Schwester hieß Hazlelponi;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 4, 'sodann Pnuel, der Vater Gedors, und Eser, der Vater Husas. Dies sind die Söhne Hurs, des erstgeborenen Sohnes der Ephratha, des Stammvaters von Bethlehem. –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 5, 'Ashur aber, der Stammvater von Thekoa, hatte zwei Frauen: Helea und Naara.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 6, 'Naara gebar ihm Ahussam, Hepher, Themni und die Ahasthariter. Dies sind die Söhne der Naara.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 7, 'Und die Söhne der Helea waren: Zereth, Zohar und Ethnan (und Koz). –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 8, 'Koz aber zeugte Anub, Zobeba und die Geschlechter Aharhels, des Sohnes Harums.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 9, 'Jaebez aber war angesehener als seine Brüder; seine Mutter hatte ihn Jaebez genannt, indem sie sagte: »Ich habe ihn mit Schmerzen geboren.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 10, 'Jaebez aber rief den Gott Israels an mit den Worten: »Ach, daß du mich segnetest und mein Gebiet erweitertest und deine Hand mit mir wäre und du mich vor Unglück behütetest, so daß mich kein Schmerz trifft!« Da erfüllte ihm Gott seine Bitte. –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 11, 'Kelub aber, der Bruder Suhas, zeugte Mehir; der ist der Vater Esthons.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 12, 'Esthon aber zeugte Beth-Rapha, Paseah und Thehinna, den Stammvater der Stadt Nahas; das sind die Männer von Recha. –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 13, 'Die Söhne des Kenas waren: Othniel und Seraja; und die Söhne Othniels: Hathath (und Meonothai).');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 14, 'Meonothai aber zeugte Ophra; und Seraja zeugte Joab, den Stammvater des Tals der Zimmerleute; sie waren nämlich Zimmerleute. –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 15, 'Die Söhne Kalebs, des Sohnes Jephunnes, waren: Iru, Ela und Naam; und der Sohn Elas: Kenas. –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 16, 'Die Söhne Jehallelels waren: Siph und Sipha, Thirja und Asareel. –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 17, 'Die Söhne Esras waren: Jether, Mered, Epher und Jalon. Und dies sind die Söhne der Bithja, der Tochter des Pharaos, die Mered geheiratet hatte: sie gebar Mirjam, Sammai und Jisbah, den Stammvater von Esthemoa.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 18, 'Seine Frau aber, die Judäerin, gebar Jered, den Stammvater von Gedor, und Heber, den Stammvater von Socho, und Jekuthiel, den Stammvater von Sanoah. –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 19, 'Die Söhne von Hodijas Frau, der Schwester Nahams, des Stammvaters von Kegila, waren: der Garmiter und Esthemoa, der Maachathiter. –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 20, 'Die Söhne Simons aber waren: Amnon und Rinna, Ben-Hanan und Thilon; – und die Söhne Jiseis waren: Soheth und der Sohn Soheths.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 21, 'Die Söhne Selas, des Sohnes Judas, waren: Ger, der Stammvater von Lecha, und Laheda, der Stammvater von Maresa, und die Geschlechter der Byssusarbeiter von Beth-Asbea;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 22, 'ferner Jokim und die Männer von Koseba und Joas und Saraph, die über Moab herrschten, und Jasubi-Lechem. Doch dies sind alte Geschichten.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 23, 'Dies sind die Töpfer und die Bewohner von Netaim und Gedera; sie hatten dort ihren Wohnsitz bei dem König, in seinem Dienste.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 24, 'Die Söhne Simeons waren: Nemuel und Jamin, Jarib, Serah, Saul;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 25, 'dessen Sohn war Sallum, dessen Sohn Mibsam, dessen Sohn Misma.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 26, 'Die Söhne Mismas waren: sein Sohn Hammuel, dessen Sohn Sakkur, dessen Sohn Simei.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 27, 'Simei aber hatte sechzehn Söhne und sechs Töchter, während seine Brüder nicht viele Kinder hatten, und ihr ganzes Geschlecht vermehrte sich nicht so stark wie die Judäer.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 28, 'Sie wohnten aber in Beerseba, Molada, Hazar-Sual,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 29, 'in Bilha, Ezem, Tholad,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 30, 'in Bethuel, Horma, Ziklag,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 31, 'in Beth-Markaboth, Hazar-Susim, Beth-Birei und Saaraim. Dies waren ihre Städte bis zur Regierung Davids.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 32, 'Ihre Dörfer aber waren Etam, Ain, Rimmon, Thochen und Asan, zusammen fünf Ortschaften.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 33, 'Dazu alle ihre Dörfer, die rings um diese Ortschaften her lagen bis nach Baal hin. Dies waren ihre Wohnsitze; und sie hatten ihr eigenes Geschlechtsverzeichnis.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 34, 'Ferner: Mesobab, Jamlech, Josa, der Sohn Amazjas,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 35, 'Joel und Jehu, der Sohn Josibjas, des Sohnes Serajas, des Sohnes Asiels;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 36, 'Eljoenai, Jaakoba, Jesohaja, Asaja, Adiel, Jesimiel und Benaja');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 37, 'und Sisa, der Sohn Sipheis, des Sohnes Allons, des Sohnes Jedajas, des Sohnes Simris, des Sohnes Semajas;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 38, 'diese hier mit Namen Angeführten waren Fürsten in ihren Geschlechtern, nachdem ihre Familien sich stark ausgebreitet hatten.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 39, 'So zogen sie denn bis in die Gegend von Gedor hin, bis an die Ostseite des Tales, um Weideplätze für ihre Herden zu suchen;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 40, 'und sie fanden dort fette und gute Weide, und das Land war nach allen Seiten hin geräumig, ruhig und friedlich; denn die früheren Bewohner waren Hamiten gewesen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 41, 'So kamen denn jene oben mit Namen Verzeichneten während der Regierung Hiskias, des Königs von Juda, überfielen deren Zelte und die Mehuniter, die sich dort vorfanden, vollzogen den Blutbann an ihnen bis auf den heutigen Tag und ließen sich an ihrer Statt nieder; denn es gab dort Weideplätze für ihre Herden. –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 42, 'Ein Teil aber von ihnen, den Simeoniten, zog in das Bergland Seir, fünfhundert Mann, an ihrer Spitze Pelatja, Neaja, Rephaja, und Ussiel, die Söhne Jiseis;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 43, 'sie erschlugen dann die letzten Überreste der Amalekiter und sind daselbst wohnen geblieben bis auf den heutigen Tag.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 5, 1, 'Die Söhne Rubens, des Erstgeborenen Israels – er war nämlich der Erstgeborene; weil er aber seines Vaters Lager entweiht hatte, wurde sein Erstgeburtsrecht den Söhnen Josephs, des Sohnes Israels, verliehen, nur daß dieser im Geschlechtsverzeichnis nicht als Erstgeborener verzeichnet wurde;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 5, 2, 'denn Juda hatte zwar die Obmacht unter seinen Brüdern, so daß einer aus ihm zum Fürsten gewählt wurde, aber das Erstgeburtsrecht wurde Joseph zuteil –,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 5, 3, 'die Söhne Rubens also, des erstgeborenen Sohnes Israels, waren: Hanoch und Pallu, Hezron und Karmi.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 5, 4, 'Die Söhne Joels waren: sein Sohn Semaja, dessen Sohn Gog, dessen Sohn Simei,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 5, 5, 'dessen Sohn Micha, dessen Sohn Reaja, dessen Sohn Baal,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 5, 6, 'dessen Sohn Beera, den Thilgath-Pilneser, der König von Assyrien, in die Gefangenschaft führte; er war ein Fürst der Rubeniten.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 5, 7, 'Seine Brüder aber nach ihren Familien, so wie sie nach ihrer Abstammung in ihr Geschlechtsverzeichnis eingetragen wurden, waren: der erste Jehiel, dann Sacharja,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 5, 8, 'dann Bela, der Sohn Asas, des Sohnes Semas, des Sohnes Joels. Dieser wohnte in Aroer und bis Nebo und Baal-Meon;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 5, 9, 'und nach Osten zu wohnte er bis an die Steppe hin, die sich vom Euphratstrom her erstreckt; denn ihre Herden waren zahlreich in der Landschaft Gilead.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 5, 10, 'Zur Zeit Sauls aber führten sie Krieg mit den Hagaritern; und als diese durch ihre Hand gefallen waren, wohnten sie in deren Zeltlagern auf der ganzen Ostseite von Gilead.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 5, 11, 'Die Gaditen wohnten ihnen gegenüber in der Landschaft Basan bis Salcha;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 5, 12, 'an der Spitze stand Joel, ihm zunächst Sapham, dann Jahenai und Saphat in Basan.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 5, 13, 'Ihre Brüder nach ihren Familien waren: Michael, Mesullam, Seba, Jorai, Jahekan, Sia und Eber, zusammen sieben.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 5, 14, 'Dies waren die Söhne Abihails, des Sohnes Huris, des Sohnes Jaroahs, des Sohnes Gileads, des Sohnes Michaels, des Sohnes Jesisais, des Sohnes Jahdos, des Sohnes des Bus.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 5, 15, 'Ahi, der Sohn Abdiels, des Sohnes Gunis, war das Haupt ihrer Familien.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 5, 16, 'Sie wohnten aber in Gilead, in Basan und den zugehörigen Ortschaften und auf allen Weidetriften Sarons bis an ihre Ausgänge.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 5, 17, 'Diese alle sind während der Regierung Jothams, des Königs von Juda, und während der Regierung Jerobeams, des Königs von Israel, im Geschlechtsverzeichnis aufgezeichnet worden.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 5, 18, 'Die Rubeniten, die Gaditen und der halbe Stamm Manasse, soweit sie tapfere Leute waren, Männer, die Schild und Schwert trugen und den Bogen spannten und kampfgeübt waren – 44760 kriegstüchtige Männer –,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 5, 19, 'die führten Krieg mit den Hagaritern und mit Jetur, Naphis und Nodab.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 5, 20, 'Und sie gewannen die Oberhand über sie, so daß die Hagariter samt allen, die mit ihnen verbündet waren, in ihre Hand gegeben wurden; denn als sie während des Kampfes zu Gott um Hilfe riefen, ließ er sich von ihnen erbitten, weil sie ihr Vertrauen auf ihn gesetzt hatten.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 5, 21, 'Sie führten dann das Vieh jener als Beute weg: 50000 Kamele, 250000 Stück Kleinvieh und 2000 Esel; dazu 100000 Menschen als Sklaven.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 5, 22, 'Denn viele waren gefallen, vom Schwert erschlagen, weil der Krieg von Gott verhängt war. Sie wohnten dann an ihrer Statt bis zur Wegführung in die Gefangenschaft.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 5, 23, 'Die zum halben Stamm Manasse Gehörigen wohnten im Lande von Basan bis Baal-Hermon und bis zum Senir und zum Hermongebirge. Sie waren zahlreich;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 5, 24, 'und dies waren ihre Familienhäupter: Epher, Jisei, Eliel, Asriel, Jeremia, Hodawja und Jahdiel, tapfere Krieger, berühmte Männer, Häupter in ihren Familien.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 5, 25, 'Da sie aber dem Gott ihrer Väter untreu wurden und mit den Göttern der im Lande wohnenden heidnischen Völker, die doch Gott vor ihnen her vertilgt hatte, Götzendienst trieben,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 5, 26, 'da erregte der Gott Israels den assyrischen König Pul und den assyrischen König Thilgath-Pilneser zur Wut, so daß er die Rubeniten, die Gaditen und den halben Stamm Manasse in die Gefangenschaft schleppte und sie nach Halah sowie an den Habor und nach Hara und an den Fluß Gosan bringen ließ, bis auf den heutigen Tag.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 5, 27, 'Die Söhne Levis waren: Gerson, Kehath und Merari;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 5, 28, 'und die Söhne Kehaths: Amram, Jizhar, Hebron und Ussiel.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 5, 29, 'Und die Söhne Amrams: Aaron und Mose, und (ihre Schwester) Mirjam. Und die Söhne Aarons: Nadab und Abihu, Eleasar und Ithamar.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 5, 30, 'Eleasar zeugte Pinehas, Pinehas zeugte Abisua,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 5, 31, 'Abisua zeugte Bukki, Bukki zeugte Ussi,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 5, 32, 'Ussi zeugte Serahja, Serahja zeugte Merajoth,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 5, 33, 'Merajoth zeugte Amarja, Amarja zeugte Ahitub,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 5, 34, 'Ahitub zeugte Zadok, Zadok zeugte Ahimaaz,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 5, 35, 'Ahimaaz zeugte Asarja, Asarja zeugte Johanan,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 5, 36, 'Johanan zeugte Asarja – das ist derselbe, der den Priesterdienst versah in dem Tempel, den Salomo in Jerusalem erbaut hatte –;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 5, 37, 'Asarja zeugte Amarja, Amarja zeugte Ahitub,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 5, 38, 'Ahitub zeugte Zadok, Zadok zeugte Sallum,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 5, 39, 'Sallum zeugte Hilkia, Hilkia zeugte Asarja,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 5, 40, 'Asarja zeugte Seraja, Seraja zeugte Jozadak;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 5, 41, 'Jozadak aber zog mit, als der HERR die Bewohner von Juda und Jerusalem durch Nebukadnezar in die Gefangenschaft führen ließ.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 1, 'Die Söhne Levis waren: Gersom, Kehath und Merari.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 2, 'Dies aber sind die Namen der Söhne Gersoms: Libni und Simei.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 3, 'Und die Söhne Kehaths waren: Amram, Jizhar, Hebron und Ussiel.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 4, 'Die Söhne Meraris waren: Mahli und Musi. – Dies aber sind die Geschlechter der Leviten nach ihren Familienvätern:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 5, 'Von Gersom stammten: sein Sohn Libni, dessen Sohn Jahath, dessen Sohn Simma,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 6, 'dessen Sohn Joah, dessen Sohn Iddo, dessen Sohn Serah, dessen Sohn Jeathrai. –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 7, 'Die Söhne Kehaths waren: sein Sohn Amminadab, dessen Sohn Korah, dessen Sohn Assir,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 8, 'dessen Sohn Elkana, dessen Sohn Ebjasaph, dessen Sohn Assir,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 9, 'dessen Sohn Thahath, dessen Sohn Uriel, dessen Sohn Ussia, dessen Sohn Saul.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 10, 'Und die Söhne Elkanas waren: Amasai und Ahimoth;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 11, 'dessen Sohn war Elkana, dessen Sohn Zophai, dessen Sohn Nahath,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 12, 'dessen Sohn Eliab, dessen Sohn Jeroham, dessen Sohn Elkana (dessen Sohn Samuel).');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 13, 'Und die Söhne Samuels waren: der Erstgeborene Joel und der zweite Abia. –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 14, 'Die Söhne Meraris waren: Mahli, dessen Sohn Libni, dessen Sohn Simei, dessen Sohn Ussa,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 15, 'dessen Sohn Simea, dessen Sohn Haggia, dessen Sohn Asaja.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 16, 'Die folgenden sind es, die David zur Leitung des Gesangs im Tempel des HERRN bestellte, nachdem die Lade dort einen festen Platz gefunden hatte;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 17, 'sie dienten aber als Sänger vor der Wohnung des Offenbarungszeltes, bis Salomo den Tempel des HERRN in Jerusalem erbaut hatte, und verrichteten ihr Amt nach den ihnen erteilten Weisungen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 18, 'Die folgenden sind es, die das Amt versahen, und ihre Nachkommen: Von den zu den Kehathiten Gehörigen: Heman, der Sänger, der Sohn Joels, des Sohnes Samuels,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 19, 'des Sohnes Elkanas, des Sohnes Jerohams, des Sohnes Eliels, des Sohnes Thoahs,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 20, 'des Sohnes Zuphs, des Sohnes Elkanas, des Sohnes Mahaths, des Sohnes Amasais,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 21, 'des Sohnes Elkanas, des Sohnes Joels, des Sohnes Asarjas, des Sohnes Zephanjas,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 22, 'des Sohnes Thahaths, des Sohnes Assirs, des Sohnes Ebjasaphs, des Sohnes Korahs,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 23, 'des Sohnes Jizhars, des Sohnes Kehaths, des Sohnes Levis, des Sohnes Israels.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 24, 'Und sein Geschlechtsgenosse war Asaph, der ihm zur Rechten stand: Asaph, der Sohn Berechjas, des Sohnes Simeas,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 25, 'des Sohnes Michaels, des Sohnes Baasejas, des Sohnes Malkias,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 26, 'des Sohnes Ethnis, des Sohnes Serahs, des Sohnes Adajas,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 27, 'des Sohnes Ethans, des Sohnes Simmas, des Sohnes Simeis,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 28, 'des Sohnes Jahaths, des Sohnes Gersoms, des Sohnes Levis.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 29, 'Und von den Nachkommen Meraris, ihren Geschlechtsgenossen, stand zur Linken: Ethan, der Sohn Kisis, des Sohnes Abdis, des Sohnes Malluchs,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 30, 'des Sohnes Hasabjas, des Sohnes Amazjas, des Sohnes Hilkias,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 31, 'des Sohnes Amzis, des Sohnes Banis, des Sohnes Semers,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 32, 'des Sohnes Mahlis, des Sohnes Musis, des Sohnes Meraris, des Sohnes Levis.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 33, 'Ihre Geschlechtsgenossen aber, die übrigen Leviten, waren für den gesamten Dienst an der Wohnung des Tempels Gottes bestellt;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 34, 'und zwar versahen Aaron und seine Nachkommen den Opferdienst auf dem Brandopferaltar und auf dem Räucheraltar und den gesamten Dienst am Allerheiligsten und was zur Versöhnung Israels diente, ganz so, wie Mose, der Knecht Gottes, geboten hatte.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 35, 'Dies waren aber die Nachkommen Aarons: sein Sohn Eleasar, dessen Sohn Pinehas, dessen Sohn Abisua,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 36, 'dessen Sohn Bukki, dessen Sohn Ussi, dessen Sohn Serahja,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 37, 'dessen Sohn Merajoth, dessen Sohn Amarja, dessen Sohn Ahitub,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 38, 'dessen Sohn Zadok, dessen Sohn Ahimaaz.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 39, 'Folgendes aber sind ihre Wohnsitze nach ihren Niederlassungen in ihrem Gebiet: Den Nachkommen Aarons von dem Geschlecht der Kehathiten – denn auf sie war das erste Los gefallen –,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 40, 'ihnen gab man Hebron im Lande Juda samt den zugehörigen Weidetriften rings um sie her;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 41, 'die zur Stadt gehörigen Felder aber und die zugehörigen Dörfer übergab man Kaleb, dem Sohne Jephunnes.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 42, 'Weiter übergab man den Nachkommen Aarons die Zufluchtstadt Hebron sowie Libna samt den zugehörigen Weidetriften, ferner Jatthir und Esthemoa samt den zugehörigen Weidetriften,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 43, 'Holon samt den zugehörigen Weidetriften, Debir samt den zugehörigen Weidetriften,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 44, 'Asan samt den zugehörigen Weidetriften und Beth-Semes samt den zugehörigen Weidetriften.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 45, 'Weiter vom Stamme Benjamin: Geba und Allemeth samt den zugehörigen Weidetriften und Anathoth samt den zugehörigen Weidetriften. Die Gesamtzahl ihrer Städte betrug dreizehn nach ihren Familien. –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 46, 'Die übrigen Nachkommen Kehaths aber erhielten nach ihren Geschlechtern vom Stamme Ephraim und vom Stamme Dan und vom halben Stamm Manasse durchs Los zehn Städte.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 47, 'Die Nachkommen Gersoms erhielten nach ihren Geschlechtern vom Stamme Issaschar, vom Stamme Asser, vom Stamme Naphthali und vom halben Stamm Manasse in Basan dreizehn Städte. –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 48, 'Die Nachkommen Meraris erhielten nach ihren Geschlechtern vom Stamme Ruben, vom Stamme Gad und vom Stamme Sebulon durchs Los zwölf Städte.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 49, 'So übergaben die Israeliten den Leviten die Städte samt den zugehörigen Weidetriften;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 50, 'und zwar übergaben sie durchs Los jene namentlich angeführten Städte aus den Stämmen Juda, Simeon und Benjamin.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 51, 'Was dann die übrigen Geschlechter der Nachkommen Kahaths anbetrifft, so erhielten sie die Städte, die ihnen durchs Los zufielen, vom Stamme Ephraim abgetreten;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 52, 'und zwar übergab man ihnen die Zufluchtstadt Sichem samt den zugehörigen Weidetriften auf dem Gebirge Ephraim; ferner Geser samt den zugehörigen Weidetriften,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 53, 'Jokmeam samt den zugehörigen Weidetriften, Beth-Horon samt den zugehörigen Weidetriften,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 54, 'Ajjalon samt den zugehörigen Weidetriften und Gath-Rimmon samt den zugehörigen Weidetriften;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 55, 'dazu vom halben Stamm Manasse: Aner samt den zugehörigen Weidetriften und Jibleam samt den zugehörigen Weidetriften – diese übergab man den Familien der übrigen Nachkommen Kahaths.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 56, 'Die Nachkommen Gersoms erhielten nach ihren Geschlechtern vom halben Stamm Manasse: Golan in Basan samt den zugehörigen Weidetriften und Astharoth samt den zugehörigen Weidetriften;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 57, 'ferner vom Stamme Issaschar: Kedes samt den zugehörigen Weidetriften, Daberath samt den zugehörigen Weidetriften,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 58, 'Ramoth samt den zugehörigen Weidetriften und Anem samt den zugehörigen Weidetriften;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 59, 'dazu vom Stamme Asser: Masal samt den zugehörigen Weidetriften, Abdon samt den zugehörigen Weidetriften,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 60, 'Hukok samt den zugehörigen Weidetriften und Rehob samt den zugehörigen Weidetriften;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 61, 'ferner vom Stamme Naphthali: Kedes in Galiläa samt den zugehörigen Weidetriften, Hammot samt den zugehörigen Weidetriften und Kirjathaim samt den zugehörigen Weidetriften.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 62, 'Die übrigen Nachkommen Meraris erhielten vom Stamme Sebulon: Rimmon samt den zugehörigen Weidetriften und Thabor samt den zugehörigen Weidetriften;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 63, 'und jenseits des Jordans gegenüber von Jericho, östlich vom Jordan, erhielten sie vom Stamme Ruben: Bezer in der Steppe samt den zugehörigen Weidetriften, Jahza samt den zugehörigen Weidetriften,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 64, 'Kedemoth samt den zugehörigen Weidetriften und Mephaath samt den zugehörigen Weidetriften;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 65, 'ferner vom Stamme Gad: Ramoth in Gilead samt den zugehörigen Weidetriften, Mahanaim samt den zugehörigen Weidetriften;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 66, 'Hesbon samt den zugehörigen Weidetriften und Jaser samt den zugehörigen Weidetriften.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 1, 'Die Söhne Issaschars waren: Thola und Pua, Jasub und Simron, zusammen vier.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 2, 'Die Söhne Tholas waren: Ussi, Rephaja, Jeriel, Jahmai, Jibsam und Samuel, Häupter ihrer Familien, von Thola, kriegstüchtige Männer, nach ihren Geschlechtern; ihre Zahl betrug zur Zeit Davids 22600.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 3, 'Die Söhne Ussis waren: Jisrahja; und die Söhne Jisrahjas: Michael, Obadja, Joel und Jissia, insgesamt fünf Familienhäupter.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 4, 'Zu ihnen gehörten nach ihren Geschlechtern, nach ihren Familien, Kriegerscharen: 36000 Mann; denn sie hatten viele Frauen und Kinder.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 5, 'Dazu ihre Stammesgenossen, sämtliche Geschlechter Issaschars, waren kriegstüchtige Männer; 87000 ergab ihr Verzeichnis im ganzen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 6, 'Die Söhne Benjamins waren: Bela, Becher und Jediael, zusammen drei.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 7, 'Die Söhne Belas waren: Ezbon, Ussi, Ussiel, Jerimoth und Iri, zusammen fünf, Familienhäupter, kriegstüchtige Männer; ihr Verzeichnis ergab 22034.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 8, 'Die Söhne Bechers waren: Semira, Joas, Elieser, Eljoenai, Omri, Jeremoth, Abia, Anathoth und Alemeth; alle diese waren Söhne Bechers,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 9, 'und ihr Verzeichnis nach ihren Geschlechtern, nach ihren Familienhäuptern ergab 20200 kriegstüchtige Männer.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 10, 'Die Söhne Jediaels waren: Bilhan; und die Söhne Bilhans: Jehus, Benjamin, Ehud, Kenaana, Sethan, Tharsis und Ahisahar;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 11, 'alle diese waren Söhne Jediaels, Familienhäupter, kriegstüchtige Männer, 17200, die kampfbereit ins Feld zogen. –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 12, 'Und Suppim und Huppim waren Söhne Irs; Husim die Söhne Ahers.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 13, 'Die Söhne Naphthalis waren: Jahziel, Guni, Jezer und Sallum, Nachkommen der Bilha.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 14, 'Die Söhne Manasses waren: Asriel, den sein syrisches Nebenweib gebar; sie gebar auch Machir, den Vater Gileads.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 15, 'Machir nahm dann [für Huppim und Suppim] eine Frau namens Maacha, und seine Schwester hieß Hammolecheth; sein Bruder hieß Zelophhad, und dieser hatte nur Töchter.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 16, 'Und Maacha, die Frau Machirs, gebar einen Sohn, den sie Peres nannte; sein Bruder aber hieß Seres, und dessen Söhne waren Ulam und Rekem.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 17, 'Die Söhne Ulams waren: Bedan. Dies sind die Söhne Gileads, des Sohnes Machirs, des Sohnes Manasses. –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 18, 'Seine Schwester Hammolecheth aber gebar Ishod, Abieser und Mahla. –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 19, 'Und die Söhne Semidas waren: Ahjan, Sichem, Likhi und Aniam.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 20, 'Die Söhne Ephraims waren: Suthelah; dessen Sohn war Bered, dessen Sohn Thahath, dessen Sohn Elada, dessen Sohn Thahath,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 21, 'dessen Sohn Sabad, dessen Sohn Suthelah und Eser und Elead. Die Bewohner von Gath aber, die Eingeborenen des Landes, erschlugen sie, weil sie hinabgezogen waren, um ihnen ihre Herden zu rauben.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 22, 'Da trauerte ihr Vater Ephraim lange Zeit, und seine Brüder kamen, um ihn zu trösten.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 23, 'Da wohnte er seiner Frau bei, und sie wurde guter Hoffnung und gebar einen Sohn, den er Beria nannte, weil sein Haus sich im Unglück befunden hatte.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 24, 'Seine Tochter aber war Seera; die erbaute das untere und das obere Beth-Horon und Ussen-Seera.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 25, 'Dessen Sohn war Rephah, dessen Sohn Reseph, dessen Sohn Thelah, dessen Sohn Thahan,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 26, 'dessen Sohn Laedan, dessen Sohn Ammihud, dessen Sohn Elisama,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 27, 'dessen Sohn Nun, dessen Sohn Josua.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 28, 'Ihr Erbbesitz aber und ihre Wohnsitze waren: Bethel samt den zugehörigen Ortschaften, und nach Osten hin Naaran und gegen Westen Geser samt den zugehörigen Ortschaften; sodann Sichem samt den zugehörigen Ortschaften bis nach Ajja samt den zugehörigen Ortschaften.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 29, 'Und im Besitz der Manassiten waren: Beth-Sean samt den zugehörigen Ortschaften, Thaanach samt den zugehörigen Ortschaften, Megiddo samt den zugehörigen Ortschaften, Dor samt den zugehörigen Ortschaften. In diesen wohnten die Nachkommen Josephs, des Sohnes Israels.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 30, 'Die Söhne Assers waren: Jimna, Jiswa, Jiswi und Beria; ihre Schwester war Serah.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 31, 'Die Söhne Berias waren: Heber und Malkiel, das ist der Stammvater von Birsajith.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 32, 'Heber zeugte Japhlet, Semer, Hotham und ihre Schwester Sua.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 33, 'Die Söhne Japhlets waren: Pasach, Bimhal und Aswath; dies waren die Söhne Japhlets;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 34, 'und die Söhne (seines Bruders) Semers: Ahi, Rohga, Hubba und Aram. –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 35, 'Die Söhne seines Bruders Hotham waren: Zophah, Jimna, Seles und Amal.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 36, 'Die Söhne Zophahs waren: Suah, Harnepher, Sual, Beri, Jimra,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 37, 'Bezer, Hod, Samma, Silsa, Jithran und Beera;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 38, 'und die Söhne Jethers: Jephunne, Pispa und Ara. –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 39, 'Die Söhne Ullas waren: Arah, Hanniel und Rizja.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 40, 'Diese alle waren Nachkommen Assers, Familienhäupter, auserlesene, kriegstüchtige Männer, Häupter unter den Fürsten; und die Zahl der aus ihnen für den Kriegsdienst Aufgezeichneten betrug 26000 Mann.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 1, 'Benjamin zeugte Bela als seinen Erstgeborenen, Asbel als den zweiten, Ahiram als den dritten,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 2, 'Noha als den vierten und Rapha als den fünften.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 3, 'Bela aber hatte folgende Söhne: Ard, Gera, Abihud,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 4, 'Abisua, Naaman, Ahoah,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 5, 'Gera, Sephuphan und Huram.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 6, 'Und dies waren die Söhne Ehuds: – sie waren Familienhäupter unter den Bewohnern von Geba, und man führte sie gefangen weg nach Manahath,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 7, 'nämlich Naaman, Ahia und Gera; dieser führte sie weg; – er zeugte aber Ussa und Ahihud.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 8, 'Saharaim aber zeugte (Söhne) im Gefilde der Moabiter, nachdem er seine Frauen Husim und Baara verstoßen hatte;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 9, 'da zeugte er mit seiner Frau Hodes: Jobab, Zibja, Mesa, Malkam,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 10, 'Jehuz, Sochja und Mirma; dies waren seine Söhne, Familienhäupter.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 11, 'Mit Husim aber hatte er Abitub und Elpaal gezeugt.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 12, 'Die Söhne Elpaals waren: Eber, Miseam und Semer; dieser erbaute Ono und Lod samt den zugehörigen Ortschaften.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 13, 'Weiter: Beria und Sema – das waren die Familienhäupter unter den Bewohnern von Ajjalon; sie hatten die Bewohner von Gath in die Flucht geschlagen –;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 14, '(und ihre Brüder waren Elpaal,) Sasak und Jeremoth.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 15, 'Sebadja aber und Arad, Eder,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 16, 'Michael, Jispa und Joha waren die Söhne Berias;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 17, 'und Sebadja, Mesullam, Hiski, Heber,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 18, 'Jismerai, Jislia und Jobab waren die Söhne Elpaals. –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 19, 'Jakim, Sichri, Sabdi,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 20, 'Eljoenai, Zillethai, Eliel,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 21, 'Adaja, Beraja und Simrath waren die Söhne Simeis. –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 22, 'Jispan, Eber, Eliel,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 23, 'Abdon, Sichri, Hanan,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 24, 'Hananja, Elam, Anthothija,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 25, 'Jiphdeja und Pnuel waren die Söhne Sasaks. –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 26, 'Samserai, Seharja, Athalja,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 27, 'Jaaresja, Elia und Sichri waren die Söhne Jerohams.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 28, 'Diese waren Familienhäupter in ihren Geschlechtern, Häupter; diese wohnten in Jerusalem.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 29, 'In Gibeon aber wohnten: Jehuel, der Stammvater von Gibeon, dessen Frau Maacha hieß.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 30, 'Sein erstgeborener Sohn war Abdon; außerdem Zur, Kis, Baal, Ner, Nadab,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 31, 'Gedor, Ahjo, Secher');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 32, 'und Mikloth, der Simea zeugte. Auch diese wohnten ihren Stammesgenossen gegenüber in Jerusalem bei ihren Stammesgenossen. –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 33, 'Ner aber zeugte Abner, und Kis zeugte Saul, Saul zeugte Jonathan, Malchisua, Abinadab und Esbaal.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 34, 'Der Sohn Jonathans war Merib-Baal, und dieser zeugte Micha.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 35, 'Die Söhne Michas waren: Pithon, Melech, Tharea und Ahas.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 36, 'Ahas zeugte Jehoadda, Jehoadda zeugte Alemeth, Asmaweth und Simri; Simri aber zeugte Moza,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 37, 'Moza zeugte Binea; dessen Sohn war Rapha, dessen Sohn Eleasa, dessen Sohn Azel.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 38, 'Azel aber hatte sechs Söhne, die hießen: Asrikam, Bochru, Ismael, Searja, Obadja und Hanan. Alle diese waren Söhne Azels. –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 39, 'Die Söhne seines Bruders Esek waren: Ulam, sein Erstgeborener, Jehus der zweite und Eliphelet der dritte.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 40, 'Die Söhne Ulams waren kriegstüchtige Männer, die den Bogen zu spannen wußten, und sie hatten zahlreiche Söhne und Enkel, hundertundfünfzig an der Zahl. Diese alle gehören zu den Nachkommen Benjamins.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 1, 'Alle Israeliten wurden nach den Geschlechtern in ein Verzeichnis eingetragen; sie finden sich bekanntlich im Buche der Könige von Israel aufgezeichnet. Die Judäer aber wurden wegen ihres treulosen Abfalls nach Babylon (in die Gefangenschaft) geführt.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 2, 'Die früheren Bewohner nun, die in ihrem Erbbesitz, in ihren Ortschaften lebten, waren: die (gemeinen) Israeliten, die Priester, die Leviten und die Tempelhörigen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 3, 'In Jerusalem aber wohnten von den Judäern und Benjaminiten sowie von den Ephraimiten und Manassiten folgende:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 4, 'Von den Judäern: Uthai, der Sohn Ammihuds, des Sohnes Omris, des Sohnes Imris, des Sohnes Banis, von den Nachkommen des Perez, des Sohnes Judas;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 5, 'und von den Siloniten: Asaja, der Erstgeborene, und seine Söhne;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 6, 'und von den Nachkommen Serahs: Jehuel und seine Geschlechtsgenossen, zusammen 690.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 7, 'Ferner von den Benjaminiten: Sallu, der Sohn Mesullams, des Sohnes Hodawjas, des Sohnes Hassenuas;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 8, 'sodann Jibneja, der Sohn Jerohams, und Ela, der Sohn Ussis, des Sohnes Michris; und Mesullam, der Sohn Sephatjas, des Sohnes Reguels, des Sohnes Jibnejas;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 9, 'dazu ihre Genossen nach ihren Geschlechtern, zusammen 956. Alle diese Männer waren Familienhäupter in ihren Familien.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 10, 'Ferner von den Priestern: Jedaja, Jojarib, Jachin');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 11, 'und Asarja, der Sohn Hilkias, des Sohnes Mesullams, des Sohnes Zadoks, des Sohnes Merajoths, des Sohnes Ahitubs, der Fürst des Tempels Gottes;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 12, 'sodann Adaja, der Sohn Jerohams, des Sohnes Pashurs, des Sohnes Malkias; und Maesai, der Sohn Adiels, des Sohnes Jahseras, des Sohnes Mesullams, des Sohnes Mesillemiths, des Sohnes Immers;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 13, 'dazu ihre Geschlechtsgenossen, Häupter ihrer Familien, zusammen 1760, tüchtige Männer zur Verrichtung des Dienstes im Tempel Gottes.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 14, 'Ferner von den Leviten: Semaja, der Sohn Hasubs, des Sohnes Asrikams, des Sohnes Hasabjas, von den Nachkommen Meraris;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 15, 'und Bakbakkar, Heres, Galal, Matthanja, der Sohn Michas, des Sohnes Sichris, des Sohnes Asaphs;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 16, 'und Obadja, der Sohn Semajas, des Sohnes Gallals, des Sohnes Jeduthuns; und Berechja, der Sohn Asas, des Sohnes Elkanas, der in den Dörfern der Netophathiter wohnte.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 17, 'Ferner die Torhüter: Sallum, Akkub, Talmon und Ahiman mit ihren Geschlechtsgenossen; Sallum war das Haupt');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 18, 'und hat bis heute die Wache am Königstor auf der Ostseite. Das sind die Torhüter im Lager der Leviten.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 19, 'Sallum aber, der Sohn Kores, des Sohnes Ebjasaphs, des Sohnes Korahs, und seine Geschlechtsgenossen aus seiner Familie, die Korahiten, waren mit der Dienstleistung als Schwellenhüter am heiligen Zelt betraut, wie auch schon ihre Vorfahren im Lager des HERRN als Hüter des Eingangs gedient hatten:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 20, 'Pinehas, der Sohn Eleasars, – der HERR sei mit ihm! – war vor Zeiten ihr Vorsteher gewesen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 21, 'Sacharja aber, der Sohn Meselemjas, war Torhüter am Eingang des Offenbarungszeltes.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 22, 'Die Gesamtzahl derer, die zu Torhütern an den Schwellen ausersehen waren, betrug 212; sie waren in ihren Dörfern in ein Verzeichnis eingetragen; David und Samuel, der Seher, hatten sie in ihr Amt eingesetzt.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 23, 'Sie selbst und ihre Nachkommen standen an den Toren des Hauses Gottes, der Zeltwohnung, um Wache zu halten.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 24, 'Nach den vier Weltgegenden sollten die Torhüter stehen, nach Osten, Westen, Norden und Süden.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 25, 'Ihre Geschlechtsgenossen aber in ihren Dörfern hatten sich von sieben zu sieben Tagen, von einem Zeitpunkte zum andern, zugleich mit jenen zum Dienst einzustellen;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 26, 'denn sie, die vier Vorsteher der Torhüter, standen dauernd in Ausübung ihres Amtes. Das sind die Leviten. Sie waren aber auch über die Zellen und Schatzkammern im Tempel Gottes gesetzt');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 27, 'und blieben auch über Nacht rings um das Gotteshaus her, weil ihnen die Bewachung oblag und sie das Aufschließen zu besorgen hatten, und zwar Morgen für Morgen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 28, 'Einige von ihnen hatten auch die Aufsicht über die gottesdienstlichen Geräte, die beim Hinein- wie beim Herausbringen allemal gezählt wurden.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 29, 'Ferner waren einige von ihnen für die Gerätschaften angestellt, und zwar für alle Gerätschaften des Heiligtums, sowie für das Feinmehl, den Wein, das Öl, den Weihrauch und die Spezereien.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 30, 'Einige von den Mitgliedern der Priesterschaft hatten die wohlriechenden Salb-Öle aus den Spezereien herzustellen;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 31, 'und Matthithja, einem der Leviten, dem Erstgeborenen des Korahiten Sallum, war die Pfannenbäckerei anvertraut.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 32, 'Ferner waren einige von den Kehathiten, ihren Geschlechtsgenossen, für die Schaubrote bestellt, die sie auf jeden Sabbat zuzurichten hatten.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 33, 'Das sind nun die Sänger, levitische Familienhäupter, die in den Zellen wohnten, von anderen Dienstleistungen befreit; denn Tag und Nacht waren sie in ihrem Amt beschäftigt.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 34, 'Das sind die levitischen Familienhäupter nach ihren Geschlechtern, die Häupter; diese wohnten in Jerusalem.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 35, 'In Gibeon aber wohnten: der Stammvater von Gibeon, Jehuel, dessen Frau Maacha hieß,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 36, 'und sein erstgeborener Sohn war Abdon; außerdem Zur, Kis, Baal, Ner, Nadab,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 37, 'Gedor, Ahjo, Sacharja und Mikloth;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 38, 'Mikloth aber zeugte Simeam. Auch diese wohnten ihren Stammesgenossen gegenüber in Jerusalem bei ihren Stammesgenossen. –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 39, 'Ner aber zeugte Abner, und Kis zeugte Saul, Saul zeugte Jonathan, Malchisua, Abinadab und Esbaal.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 40, 'Der Sohn Jonathans war Merib-Baal, und dieser zeugte Micha.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 41, 'Die Söhne Michas waren: Pithon, Melech, Thahrea und Ahas.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 42, 'Ahas zeugte Jara, Jara zeugte Alemeth, Asmaweth und Simri; Simri zeugte Moza,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 43, 'und Moza zeugte Binea; dessen Sohn war Rephaja, dessen Sohn Eleasa, dessen Sohn Azel.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 44, 'Azel aber hatte sechs Söhne, die hießen: Asrikam, Bochru, Ismael, Searja, Obadja und Hanan. Dies waren die Söhne Azels.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 10, 1, 'Als es aber zwischen den Philistern und Israeliten zur Schlacht kam, wurde die Mannschaft der Israeliten von den Philistern in die Flucht geschlagen, und (viele) Erschlagene lagen auf dem Gebirge Gilboa umher.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 10, 2, 'Die Philister setzten dem Saul und seinen Söhnen hart nach und erschlugen Sauls Söhne Jonathan, Abinadab und Malchisua.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 10, 3, 'Als dann ein wilder Kampf gegen Saul entstand und die Bogenschützen ihn entdeckt hatten, wurde er von Angst vor den Schützen ergriffen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 10, 4, 'Da befahl Saul seinem Waffenträger: »Ziehe dein Schwert und durchbohre mich, damit nicht diese Heiden kommen und ihren Mutwillen an mir auslassen!« Aber sein Waffenträger weigerte sich, weil er sich zu sehr fürchtete. Da nahm Saul sein Schwert und stürzte sich hinein.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 10, 5, 'Als nun sein Waffenträger sah, daß Saul tot war, stürzte er sich gleichfalls ins Schwert und starb.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 10, 6, 'So fanden Saul und seine drei Söhne den Tod: sein ganzes Haus kam gleichzeitig ums Leben.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 10, 7, 'Als aber die gesamte israelitische Bevölkerung, die in der Ebene wohnte, gewahrte, daß die Israeliten geflohen waren und daß Saul mit seinen Söhnen gefallen war, verließen sie ihre Ortschaften und ergriffen die Flucht; da kamen die Philister und setzten sich darin fest.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 10, 8, 'Als dann am folgenden Tage die Philister kamen, um die Gefallenen auszuplündern, fanden sie Saul und seine Söhne auf dem Gebirge Gilboa liegen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 10, 9, 'Da raubten sie ihn aus, nahmen seinen Kopf und seine Rüstung mit und sandten Boten in allen Teilen des Philisterlandes umher, um die Siegesbotschaft ihren Götzen und dem Volk zu verkünden.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 10, 10, 'Seine Waffen legten sie im Tempel ihres Gottes nieder und nagelten seinen Schädel im Tempel Dagons an.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 10, 11, 'Als aber die gesamte Einwohnerschaft von Jabes in Gilead alles erfuhr, was die Philister an Sauls Leichnam verübt hatten,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 10, 12, 'machten sich alle streitbaren Männer auf, nahmen den Leichnam Sauls und die Leichen seiner Söhne mit sich und brachten sie nach Jabes; dann begruben sie ihre Gebeine unter der Terebinthe in Jabes und fasteten sieben Tage lang.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 10, 13, 'So fand Saul den Tod infolge seiner Treulosigkeit, deren er sich gegen den HERRN schuldig gemacht hatte, weil er das Gebot des HERRN nicht beobachtet und auch, weil er eine Totenbeschwörerin aufgesucht hatte, um sie zu befragen,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 10, 14, 'statt sich an den HERRN um eine Offenbarung zu wenden. Darum ließ dieser ihn ums Leben kommen und wandte das Königtum David, dem Sohne Isais, zu.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 1, 'Nun fanden sich alle Israeliten bei David in Hebron ein und sagten: »Wir sind ja doch von deinem Fleisch und Bein!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 2, 'Schon früher, schon als Saul noch König war, bist du es gewesen, der Israel ins Feld und wieder heimgeführt hat; dazu hat der HERR, dein Gott, dir verheißen: ›Du sollst mein Volk Israel weiden, und du sollst Fürst über mein Volk Israel sein!‹«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 3, 'Als so alle Ältesten der Israeliten zum König nach Hebron gekommen waren, schloß David einen Vertrag mit ihnen in Hebron vor dem Angesicht des HERRN; dann salbten sie David zum König über Israel, entsprechend dem Wort des HERRN, das durch Samuel ergangen war.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 4, 'Als David dann mit ganz Israel gegen Jerusalem zog – das ist Jebus, und dort waren die Jebusiter, die das Land (noch) bewohnten –,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 5, 'da sagten die Bewohner von Jebus zu David: »Hier wirst du nicht eindringen!« Aber David eroberte die Burg Zion, das ist die (jetzige) Davidsstadt.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 6, 'Da sagte David: »Wer die Jebusiter zuerst schlägt, soll oberster Heerführer werden!« Da stieg Joab, der Sohn der Zeruja, zuerst hinauf und wurde dadurch Heerführer.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 7, 'David nahm dann seinen Wohnsitz auf der Burg; darum nannte man sie ›Davidsstadt‹;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 8, 'auch befestigte er die Stadt ringsum, von der Burg Millo an rund umher, während Joab die übrige Stadt wiederherstellte.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 9, 'Davids Macht wuchs nun immer mehr, weil der HERR der Heerscharen mit ihm war.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 10, 'Folgendes sind die vornehmsten Helden Davids, die sich im Verein mit ganz Israel bei seiner Erhebung zur Königswürde fest zu ihm hielten, um ihn zum König zu machen, wie der HERR den Israeliten geboten hatte.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 11, 'Folgendes ist also das Verzeichnis der Helden Davids: Isbaal, der Sohn Hachmonis, das Haupt der Ritter, der seinen Speer über dreihundert (Feinden) schwang, die er auf einmal erschlagen hatte.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 12, 'Nach ihm kam Eleasar, der Sohn Dodos, der Ahohiter, der zu den drei (vornehmsten) Helden gehörte.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 13, 'Er befand sich (einst) mit David in Pas-Dammim, als die Philister sich dort zur Schlacht versammelt hatten. Nun war da ein Ackerstück mit Gerste; und als das übrige Heer vor den Philistern floh,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 14, 'da trat er mitten auf das Feld, behauptete es und schlug die Philister; so verlieh der HERR ihnen einen herrlichen Sieg.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 15, 'Einst kamen die drei vornehmsten von den dreißig Rittern zu David nach dem Felsennest hinab, in die Höhle Adullam, während das Heer der Philister sich im Tale Rephaim gelagert hatte.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 16, 'David befand sich aber damals in der Bergfeste, während eine Besatzung der Philister damals in Bethlehem lag.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 17, 'Da verspürte David ein Gelüst und rief aus: »Wer verschafft mir Wasser zu trinken aus dem Brunnen, der in Bethlehem am Stadttor liegt?«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 18, 'Da schlugen sich die drei (Helden) durch das Lager der Philister hindurch, schöpften Wasser aus dem Brunnen am Tor von Bethlehem und brachten es glücklich zu David hin. Aber dieser wollte es nicht trinken, sondern goß es als Spende für den HERRN aus');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 19, 'mit den Worten: »Der HERR behüte mich davor, daß ich so etwas tun sollte! Ich sollte das Blut dieser Männer trinken, die unter Lebensgefahr hingezogen sind? Denn mit Daransetzung ihres Lebens haben sie es geholt!« Und er wollte es nicht trinken. Das hatten die drei Helden ausgeführt.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 20, 'Abisai aber, der Bruder Joabs, der war das Haupt der Dreißig; der schwang seinen Speer über dreihundert Feinden, die er erschlagen hatte, und besaß hohes Ansehen unter den Dreißig.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 21, 'Unter den Dreißig genoß er die höchste Ehre, so daß er auch ihr Oberster wurde; aber an die (ersten) drei Helden reichte er nicht heran. –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 22, 'Benaja, der Sohn Jojadas, ein tapferer Mann, groß an Taten, stammte aus Kabzeel; er war es, der die beiden Söhne Ariels aus Moab erschlug. Auch stieg er einmal in eine Zisterne hinab und erschlug drunten in der Grube einen Löwen an einem Tage, an dem Schnee gefallen war.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 23, 'Auch erschlug er den Ägypter, einen Riesen von fünf Ellen Länge, der einen Speer in der Hand hatte so dick wie ein Weberbaum; er aber ging mit einem Stecken auf ihn los, riß dem Ägypter den Speer aus der Hand und tötete ihn mit seinem eigenen Speer.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 24, 'Solche Taten vollführte Benaja, der Sohn Jojadas; er besaß hohes Ansehen unter den dreißig Rittern,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 25, 'ja, er war der geehrteste unter den Dreißig; aber an die (ersten) drei Helden reichte er nicht heran. David stellte ihn an die Spitze seiner Leibwache.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 26, 'Die (übrigen) ausgezeichnetsten Kriegshelden waren: Asahel, der Bruder Joabs; Elhanan aus Bethlehem, der Sohn Dodos;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 27, 'Sammoth aus Harod; Helez aus Pelet;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 28, 'Ira aus Thekoa, der Sohn des Ikkes; Abieser aus Anathoth;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 29, 'Sibbechai aus Husa; Ilai aus Ahoh;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 30, 'Maharai aus Netopha; Heled aus Netopha, der Sohn Baanas;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 31, 'Itthai, der Sohn Ribais, aus Gibea im Stamme Benjamin; Benaja aus Pirathon;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 32, 'Hiddai aus Nahale-Gaas; Abiel aus Araba;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 33, 'Asmaweth aus Bahurim; Eljahba aus Saalbon;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 34, 'Jasen aus Guni; Jonathan, der Sohn Sages, aus Harar;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 35, 'Ahiam, der Sohn Sachars, aus Harar; Elipheleth, der Sohn Urs;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 36, 'Hepher aus Mechera; Ahia aus Palon;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 37, 'Hezro aus Karmel; Naarai, der Sohn Esbais;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 38, 'Joel, der Bruder Nathans; Mibhar, der Sohn Hagris;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 39, 'Zelek, der Ammoniter; Nahrai aus Beeroth, der Waffenträger Joabs, des Sohnes der Zeruja;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 40, 'Ira aus Jattir; Gareb aus Jattir;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 41, 'Uria, der Hethiter; Sabad, der Sohn Ahlais;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 42, 'Adina, der Sohn Sisas, aus dem Stamme Ruben, ein Haupt der Rubeniten, und mit ihm dreißig Mann;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 43, 'Hanan, der Sohn Maachas, und Josaphat aus Methen;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 44, 'Ussia aus Asthera; Sama und Jehiel, die Söhne Hothams, aus Aroer;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 45, 'Jediael, der Sohn Simris, und sein Bruder Joha, der Thiziter;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 46, 'Eliel aus Mahanaim; Jeribai und Josawja, die Söhne Elnaams, und Jithma, der Moabiter;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 47, 'Eliel und Obed und Jaasiel aus Zoba.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 1, 'Und dies sind die Männer, die zu David nach Ziklag kamen, als er noch von Saul, dem Sohne des Kis, verbannt war; auch sie gehörten zu den Helden, die ihm im Kampf halfen,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 2, 'ausgerüstet mit Bogen und geübt, mit der Rechten und mit der Linken Steine zu schleudern und Pfeile mit dem Bogen zu schießen. Von den Stammesgenossen Sauls aus (dem Stamme) Benjamin waren da:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 3, 'der Oberste Ahieser und Joas, der Sohn Semaas aus Gibea; ferner Jesiel und Pelet, die Söhne Asmaweths, Beracha und Jehu aus Anathoth,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 4, 'Jismaja aus Gibeon, ein Held unter den Dreißig und der Anführer der Dreißig;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 5, 'ferner Jeremia, Jahasiel und Johanan; Josabad aus Gedera;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 6, 'Elusai, Jerimoth, Bealja und Semarja; Sephatja aus Hariph;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 7, 'Elkana, Jissija, Asarel, Joeser und Jasobam, die Korhiter;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 8, 'Joela und Sebadja, die Söhne Jerohams, aus Gedor.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 9, 'Von den Gaditen aber gingen tapfere Helden zu David nach der Bergfeste in der Wüste über, kampfgeübte Krieger, die Schild und Lanze zu führen wußten, die anzusehen waren wie Löwen und schnellfüßig wie Gazellen auf den Bergen:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 10, 'der Oberste war Eser, der zweite Obadja, der dritte Eliab,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 11, 'der vierte Mismanna, der fünfte Jeremia,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 12, 'der sechste Atthai, der siebte Eliel,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 13, 'der achte Johanan, der neunte Elsabad,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 14, 'der zehnte Jeremia, der elfte Machbannai.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 15, 'Diese, von den Gaditen, waren Heerführer, deren unbedeutendster es mit hundert, deren tüchtigster es mit tausend Mann aufnehmen konnte.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 16, 'Diese waren es, die (einst) im ersten Monat über den Jordan setzten, als er alle seine Ufer überflutet hatte, und alle Bewohner der Niederungen, im Osten wie im Westen, in die Flucht jagten.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 17, 'Als aber einmal auch von den Benjaminiten und Judäern Leute zu David nach der Bergfeste kamen,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 18, 'trat David draußen vor sie hin und redete sie mit folgenden Worten an: »Kommt ihr als Freunde zu mir, um mir zu helfen, so will ich mich zu herzlicher Gemeinschaft mit euch vereinigen; wollt ihr mich aber an meine Feinde verraten, wiewohl kein Unrecht an meinen Händen klebt, so möge der Gott unserer Väter dareinsehen und es strafen!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 19, 'Da rief Abisai, der (spätere) Hauptmann der Dreißig, von Begeisterung ergriffen, aus: »Dein sind wir, David, und mit dir halten wir es, Sohn Isais! Heil, Heil dir und Heil denen, die es mit dir halten! Denn dir hilft dein Gott!« Darauf nahm David sie an und machte sie zu Anführern von Kriegerscharen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 20, 'Auch von den Manassiten traten einige zu David über, als er mit den Philistern gegen Saul zu Felde zog – ohne ihnen jedoch Hilfe zu leisten; denn die Fürsten der Philister hatten ihn aus ihrem Heere entlassen, nachdem sie eine Beratung gehalten hatten, weil sie sich sagten: »Um den Preis unserer Köpfe könnte er zu Saul, seinem Herrn, übergehen« –;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 21, 'während er dann also (wieder) nach Ziklag zog, fielen ihm folgende Manassiten zu: Adnah, Josabad, Jediael, Michael, Josabad, Elihu und Zillethai, Häupter der Tausendschaften von Manasse.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 22, 'Diese leisteten dem David Beistand gegen die Streifschar; denn sie waren sämtlich tapfere Krieger und wurden Anführer im Heere.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 23, 'Denn Tag für Tag kamen Leute zu David, um Kriegsdienste bei ihm zu tun, bis es ein großes Heer geworden war wie ein Heer Gottes.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 24, 'Folgendes sind nun die Zahlen der zum Heeresdienst Gerüsteten, die sich bei David in Hebron einfanden, um ihm nach dem Befehl des HERRN das Königtum Sauls zu übertragen:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 25, 'Von den Judäern, die Schild und Lanze führten, waren es 6800 zum Kriegsdienst Gerüstete; –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 26, 'von den Simeoniten 7100 tapfere Krieger; –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 27, 'von den Leviten 4600;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 28, 'dazu Jojada, der Fürst über die zum Hause Aarons gehörigen Krieger, und mit ihm 3700 Mann;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 29, 'sodann Zadok, ein tapferer junger Held, dessen Familie 22 Hauptleute stellte; –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 30, 'von den Benjaminiten, Sauls Stammesgenossen, 3000 Mann; denn bis dahin hielt der größte Teil von ihnen noch treu zum Hause Sauls; –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 31, 'von den Ephraimiten 20800 tapfere, in ihren Familien hochangesehene Männer; –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 32, 'vom halben Stamm Manasse 18000, die mit Namen aufgeführt worden waren, daß sie hinziehen sollten, um David zum König zu machen; –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 33, 'von den Issaschariten, die sich auf die Zeitverhältnisse verstanden, um zu wissen, was Israel tun müsse: ihre 200 Häupter und unter deren Befehl ihre sämtlichen Stammesgenossen; –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 34, 'von Sebulon 50000 Mann, die zum Heeresdienst auszogen, in voller Kriegsrüstung und einmütig (zum Kampfe) sich ordnend; –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 35, 'von Naphthali 1000 Anführer und mit ihnen 37000 Mann mit Schild und Speer; –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 36, 'von den Daniten 28600 kampfgerüstete Leute; –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 37, 'von Asser 40000 Mann, die zum Heeresdienst auszogen, zum Kampfe bereit; –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 38, 'von jenseits des Jordans: von den Rubeniten, Gaditen und dem halben Stamm Manasse: 120000 Mann in voller feldmäßiger Kriegsrüstung.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 39, 'Alle diese Kriegsleute, zum Kampf in Schlachtreihen geordnet, kamen einmütigen Sinnes nach Hebron, um David zum König über ganz Israel zu machen; aber auch das ganze übrige Israel war einmütig in dem Entschluß, David zum König zu machen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 40, 'Drei Tage lang blieben sie dort bei David, aßen und tranken; denn ihre Volksgenossen hatten für ihren Unterhalt gesorgt;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 41, 'außerdem brachten die in ihrer Nähe bis nach Issaschar, Sebulon und Naphthali hin Wohnenden Lebensmittel auf Eseln, Kamelen, Maultieren und Rindern herbei: Mundvorrat von Mehl, Feigenkuchen und Rosinenkuchen, Wein und Öl, auch Rinder und Kleinvieh in Menge; denn es herrschte eine freudige Stimmung in Israel.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 13, 1, 'Als David sich dann mit den Anführern der Tausendschaften und der Hundertschaften, mit allen Fürsten beraten hatte,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 13, 2, 'sagte er zu der ganzen Volksgemeinde Israels: »Wenn es euch gut dünkt und es vom HERRN, unserm Gott, gebilligt wird, so wollen wir schleunigst zu unseren übrigen Volksgenossen, die in allen Gegenden Israels zurückgeblieben sind, sowie zu den Priestern und den Leviten, die bei ihnen in den Ortschaften ihrer Bezirke wohnen, Boten senden, damit sie insgesamt zu uns herkommen;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 13, 3, 'wir wollen dann die Lade unseres Gottes zu uns herüberholen; denn während der Regierung Sauls haben wir uns nicht um sie gekümmert.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 13, 4, 'Da erklärte sich die ganze Versammlung mit dem Vorschlage einverstanden; denn er hatte den Beifall des ganzen Volkes gefunden.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 13, 5, 'So ließ denn David alle Israeliten vom ägyptischen Flusse Sihor an bis in die Gegend von Hamath hin zusammenkommen, damit sie die Lade Gottes aus Kirjath-Jearim herbeiholten.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 13, 6, 'Darauf zog David mit ganz Israel hinauf nach Baala, das ist nach Kirjath-Jearim, welches zu Juda gehört, um von dort die Lade Gottes heraufzuholen, die nach dem Namen des HERRN benannt ist, der über den Cheruben thront.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 13, 7, 'Sie führten dann die Lade Gottes auf einem neuen Wagen aus dem Hause Abinadabs weg, indem Ussa und Ahjo den Wagen leiteten;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 13, 8, 'David aber und alle Israeliten tanzten vor Gott her mit Aufbietung aller Kräfte: mit Gesängen und unter Begleitung von Zithern und Harfen, Handpauken, Zimbeln und Trompeten.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 13, 9, 'Als sie nun so bis zur Tenne Kidons gekommen waren, streckte Ussa seine Hand aus, um die Lade festzuhalten, weil die Rinder ausgeglitten waren.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 13, 10, 'Da entbrannte der Zorn des HERRN gegen Ussa, und er schlug ihn zur Strafe dafür, daß er mit der Hand nach der Lade gegriffen hatte, so daß er dort vor den Augen Gottes starb.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 13, 11, 'Da wurde David tief betrübt darüber, daß der HERR einen solchen Schlag gegen Ussa geführt hatte; daher nannte man jenen Ort Perez-Ussa bis auf den heutigen Tag.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 13, 12, 'David aber geriet an jenem Tage in Furcht vor Gott, so daß er ausrief: »Wie kann ich da die Lade Gottes zu mir bringen?«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 13, 13, 'Weil David also die Lade des HERRN nicht zu sich in die Davidsstadt bringen lassen wollte, ließ er sie abseits in das Haus des Gathiters Obed-Edom setzen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 13, 14, 'So blieb denn die Lade Gottes ein Vierteljahr lang bei der Familie Obed-Edoms, in dessen Hause, stehen; der HERR aber segnete das Haus Obed-Edoms und seinen gesamten Besitz.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 14, 1, 'Nun schickte Hiram, der König von Tyrus, Gesandte an David mit Zedernstämmen, dazu Steinmetzen und Zimmerleute, damit sie ihm einen Palast bauten;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 14, 2, 'daran erkannte David, daß der HERR ihn als König über Israel bestätigt habe, weil sein Königtum zu hohem Ansehen erhoben worden war um seines Volkes Israel willen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 14, 3, 'In Jerusalem nahm sich David dann noch mehr Frauen und wurde Vater von noch mehr Söhnen und Töchtern.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 14, 4, 'Dies aber sind die Namen der Söhne, die ihm in Jerusalem geboren wurden: Sammua und Sobab, Nathan und Salomo,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 14, 5, 'Jibhar, Elisua, Elpelet,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 14, 6, 'Nogah, Nepheg, Japhia,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 14, 7, 'Elisama, Beeljada und Eliphelet.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 14, 8, 'Als aber die Philister vernahmen, daß David zum König über ganz Israel gesalbt worden war, zogen die Philister insgesamt heran, um seiner habhaft zu werden; aber David erhielt Kunde davon und zog ihnen entgegen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 14, 9, 'Als nun die Philister eingedrungen waren und sich in der Ebene Rephaim ausbreiteten,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 14, 10, 'richtete David die Anfrage an Gott: »Soll ich gegen die Philister hinaufziehen, und wirst du sie in meine Hand geben?« Da antwortete ihm der HERR: »Ziehe hin, ich will sie in deine Hand geben!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 14, 11, 'Als sie nun nach Baal-Perazim hinaufzogen und David sie dort geschlagen hatte, rief David aus: »Gott hat meine Feinde durch meine Hand durchbrochen, wie das Wasser einen Damm durchbricht!« Darum hat man jenem Ort den Namen Baal-Perazim gegeben.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 14, 12, 'Da (die Philister) ihre Götterbilder dort zurückgelassen hatten, gab David den Befehl, daß man sie verbrennen solle.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 14, 13, 'Die Philister zogen dann nochmals heran und breiteten sich in der Ebene (Rephaim) aus.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 14, 14, 'Als David nun Gott wiederum befragte, antwortete dieser ihm: »Du sollst nicht hinter ihnen her hinaufziehen, sondern umgehe sie, damit du sie vom Baka-Gehölz her überfällst!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 14, 15, 'Sobald du dann in den Wipfeln des Baka-Gehölzes das Geräusch von Schritten vernimmst, dann gehe zum Angriff über! Denn alsdann ist Gott vor dir her ausgezogen, um das Heer der Philister zu schlagen.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 14, 16, 'Da tat David, wie Gott ihm geboten hatte, und so schlugen sie das Heer der Philister von Gibeon bis nach Geser hin.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 14, 17, 'Hierauf verbreitete sich der Ruhm Davids in alle Lande, und der HERR flößte allen Völkern Furcht vor ihm ein.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 15, 1, 'Hierauf baute er sich Häuser in der Davidsstadt und richtete für die Lade Gottes eine Stätte her, indem er ein Zelt für sie aufschlug.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 15, 2, 'Damals ordnete David an: »Niemand darf die Lade Gottes tragen außer den Leviten! Denn diese hat der HERR dazu erwählt, die Lade Gottes zu tragen und ihm allezeit Dienste zu verrichten.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 15, 3, 'Dann entbot David das gesamte Israel nach Jerusalem, um die Lade des HERRN an die Stätte hinaufzuschaffen, die er für sie hatte herrichten lassen;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 15, 4, 'und zwar ließ David die Nachkommen Aarons sowie die Leviten zusammenkommen,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 15, 5, 'nämlich von den Nachkommen Kehaths: Uriel, den Obersten des Geschlechts, und seine Geschlechtsgenossen, hundertundzwanzig an der Zahl;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 15, 6, 'von den Nachkommen Meraris: Asaja, den Obersten des Geschlechts, und seine Geschlechtsgenossen, zweihundertundzwanzig;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 15, 7, 'von den Nachkommen Gersoms: Joel, den Obersten des Geschlechts, und seine Geschlechtsgenossen, hundertunddreißig;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 15, 8, 'von den Nachkommen Elizaphans: Semaja, den Obersten des Geschlechts, und seine Geschlechtsgenossen, zweihundert;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 15, 9, 'von den Nachkommen Hebrons: Eliel, den Obersten des Geschlechts, und seine Geschlechtsgenossen, achtzig;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 15, 10, 'von den Nachkommen Ussiels: Amminadab, den Obersten des Geschlechts, und seine Geschlechtsgenossen, hundertundzwölf. –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 15, 11, 'Darauf berief David die Priester Zadok und Abjathar und die Leviten Uriel, Asaja und Joel, Semaja und Eliel und Amminadab');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 15, 12, 'und richtete folgende Worte an sie: »Ihr seid die Familienhäupter der Leviten: so heiligt euch nun, ihr samt euren Geschlechtsgenossen! Denn ihr sollt die Lade des HERRN, des Gottes Israels, an die Stätte hinaufbringen, die ich für sie habe herrichten lassen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 15, 13, 'Weil ihr nämlich das vorige Mal nicht zugegen gewesen seid, hat der HERR, unser Gott, Unheil unter uns angerichtet, zur Strafe dafür, daß wir nicht in gebührender Weise Rücksicht auf ihn genommen hatten.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 15, 14, 'Da heiligten sich die Priester und die Leviten, um die Lade des HERRN, des Gottes Israels, hinaufzubringen;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 15, 15, 'sodann hoben die Leviten die Lade Gottes so, wie Mose es nach dem Befehl des HERRN geboten hatte, auf ihre Schultern, indem sie die Tragstangen auf sich legten.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 15, 16, 'Hierauf befahl David den Obersten der Leviten, ihre Geschlechtsgenossen, die Sänger, mit ihren Musikinstrumenten, den Harfen, Zithern und Zimbeln, antreten zu lassen, damit sie Musik und Gesang mit lautem Jubelschall ertönen ließen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 15, 17, 'Da stellten denn die Leviten Heman, den Sohn Joels, auf und von dessen Geschlechtsgenossen Asaph, den Sohn Berechjas, und von den Nachkommen Meraris, ihren Geschlechtsgenossen, Ethan, den Sohn Kusajas,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 15, 18, 'und mit ihnen ihre Amtsgenossen zweiten Ranges: Sacharja, [den Sohn,] sowie Jaasiel, Semiramoth, Jehiel, Unni, Eliab, Benaja, Maaseja, Matthithja, Eliphelehu, Mikneja, Obed-Edom und Jeiel, die Torhüter;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 15, 19, 'dazu die Sänger Heman, Asaph und Ethan mit kupfernen Zimbeln, um die Musik zu verstärken,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 15, 20, 'Sacharja dagegen nebst Ussiel, Semiramoth, Jehiel, Unni, Eliab, Maaseja und Benaja mit Leiern, zu denen sie in hoher Tonlage sangen;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 15, 21, 'ferner Matthithja, Eliphelehu, Mikneja, Obed-Edom, Jehiel und Asasja mit Harfen, zu denen sie mit Baßstimmen sangen und den Gesang leiteten.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 15, 22, 'Kenanja ferner, der Oberste der Leviten beim Tragen (der heiligen Geräte), führte die Aufsicht beim Tragen, denn er verstand sich darauf;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 15, 23, 'und Berechja und Elkana waren Torhüter bei der Lade;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 15, 24, 'Sebanja aber sowie Josaphat, Nethaneel, Amasai, Sacharja, Benaja und Elieser, die Priester, bliesen die Trompeten vor der Lade Gottes her, während Obed-Edom und Jehia Torhüter bei der Lade waren.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 15, 25, 'So zogen denn David und die Ältesten der Israeliten und die Befehlshaber der Tausendschaften hin, um die Lade mit dem Bundesgesetz des HERRN aus dem Hause Obed-Edoms voller Freude hinaufzubringen;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 15, 26, 'und da Gott sich den Leviten, welche die Lade mit dem Bundesgesetz des HERRN trugen, gnädig bewies, opferte man sieben Stiere und sieben Widder.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 15, 27, 'Dabei war David mit einem Überwurf von Byssus bekleidet, ebenso alle Leviten, welche die Lade trugen, sowie die Sänger und Kenanja, der das Tragen zu leiten hatte; David aber hatte ein linnenes Schulterkleid (darüber) angelegt.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 15, 28, 'So brachte denn ganz Israel die Lade mit dem Bundesgesetz des HERRN unter lautem Jubel und Posaunenschall, mit Trompeten- und Zimbelklang und unter Harfen- und Zitherspiel hinauf.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 15, 29, 'Da begab es sich, als die Lade mit dem Bundesgesetz des HERRN in die Davidsstadt einzog, daß Sauls Tochter Michal zum Fenster hinausschaute; als sie nun den König David so springen und tanzen sah, empfand sie Verachtung für ihn in ihrem Herzen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 1, 'Nachdem man dann die Lade Gottes hineingebracht und sie im Innern des Zeltes, das David für sie hatte aufschlagen lassen, niedergesetzt hatte, brachte man Brandopfer und Heilsopfer vor Gott dar;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 2, 'und als David mit der Darbringung der Brand- und Heilsopfer fertig war, segnete er das Volk im Namen des HERRN');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 3, 'und ließ dann unter sämtliche Israeliten, sowohl an Männer wie an Frauen, an einen jeden einen Brotkuchen, ein Stück Fleisch und einen Rosinenkuchen austeilen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 4, 'Hierauf bestellte er mehrere Leviten zu Dienern vor der Lade des HERRN, damit sie dem HERRN, dem Gott Israels, Preis, Dank und Lob darbrächten,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 5, 'nämlich Asaph als Vorsteher und Sacharja als zweiten im Range nach ihm, ferner Jeghiel, Semiramoth, Jehiel, Matthithja, Eliab, Benaja, Obed-Edom und Jehiel, mit Musikinstrumenten, Harfen und Zithern, während Asaph die Zimbeln');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 6, 'und die Priester Benaja und Jahasiel die Trompeten ständig vor der Lade mit dem Bundesgesetz Gottes erschallen ließen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 7, 'Damals, an jenem Tage, beauftragte David zum erstenmal Asaph und seine Amtsgenossen, das Danklied auf den HERRN zu singen:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 8, 'Preiset den HERRN, ruft seinen Namen an, macht seine Taten unter den Völkern bekannt!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 9, 'Singet ihm, spielet ihm, redet von all seinen Wundern!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 10, 'Rühmt euch seines heiligen Namens! Es mögen sich herzlich freuen, die da suchen den HERRN!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 11, 'Fragt nach dem HERRN und seiner Stärke, suchet sein Angesicht allezeit!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 12, 'Gedenkt seiner Wunder, die er getan, seiner Zeichen und der Urteilssprüche seines Mundes,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 13, 'ihr Kinder Israels, seine Knechte, ihr Söhne Jakobs, seine Erwählten!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 14, 'Er, der HERR, ist unser Gott, über die ganze Erde ergehen seine Gerichte.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 15, 'Er gedenkt seines Bundes auf ewig, des Wortes, das er geboten auf tausend Geschlechter,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 16, '(des Bundes) den er mit Abraham geschlossen, und des Eides, den er Isaak geschworen,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 17, 'den für Jakob er als Satzung bestätigt und für Israel als ewigen Bund,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 18, 'da er sprach: »Dir will ich Kanaan geben, das Land, das ich euch als Erbbesitztum zugeteilt!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 19, 'Damals wart ihr noch ein kleines Häuflein, gar wenige und nur Gäste im Land;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 20, 'sie mußten wandern von Volk zu Volk und von einem Reich zur anderen Völkerschaft;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 21, 'doch keinem gestattete er, sie zu bedrücken, ja, Könige strafte er um ihretwillen:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 22, '»Tastet meine Gesalbten nicht an und tut meinen Propheten nichts zuleide!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 23, 'Singet dem HERRN, alle Lande, verkündet Tag für Tag sein Heil!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 24, 'Erzählt von seiner Herrlichkeit unter den Heiden, unter allen Völkern von seinen Wundertaten!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 25, 'Denn groß ist der HERR und hoch zu preisen, und mehr zu fürchten als alle anderen Götter;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 26, 'denn alle Götter der Heiden sind nichtige Götzen, doch der HERR hat den Himmel geschaffen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 27, 'Hoheit und Pracht gehn vor ihm her, Macht und Wonne füllen seine Wohnstatt.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 28, 'Bringt dar dem HERRN, ihr Geschlechter der Völker, bringt dar dem HERRN Ehre und Preis!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 29, 'Bringt dar dem HERRN die Ehre seines Namens! Bringt Opfergaben und kommt vor sein Angesicht! Werft vor dem HERRN euch nieder in heiligem Schmuck!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 30, 'Erzittert vor ihm, alle Lande! Auch den Erdkreis hat er gefestigt, daß er nicht wankt.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 31, 'Des freue sich der Himmel, die Erde jauchze, und man sage unter den Heiden: »Der HERR ist König!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 32, 'Es brause das Meer und was darin wimmelt! Es jauchze die Flur und was auf ihr wächst!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 33, 'Dann werden auch jubeln die Bäume des Waldes vor dem HERRN, wenn er kommt, zu richten die Erde.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 34, 'Preiset den HERRN, denn er ist freundlich, ja, ewiglich währt seine Güte.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 35, 'Und betet: »Hilf uns, du Gott unsrer Hilfe! Bringe uns wieder zusammen und rette uns aus den Heiden, damit wir danken deinem heiligen Namen, uns deines Lobpreises rühmen!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 36, 'Gepriesen sei der HERR, der Gott Israels, von Ewigkeit zu Ewigkeit! Da rief alles Volk »Amen!« und »Preis sei dem HERRN!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 37, '(David) ließ dann Asaph und seine Geschlechtsgenossen dort vor der Bundeslade des HERRN verbleiben, damit sie den Dienst vor der Lade ständig so verrichteten, wie ein jeder Tag es erforderte;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 38, 'ebenso ließ er Obed-Edom, den Sohn Jeduthuns, und Hosa samt ihren Geschlechtsgenossen, achtundsechzig an der Zahl, als Torhüter dienen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 39, 'Den Priester Zadok aber nebst seinen Geschlechtsgenossen, den Priestern, ließ er vor der Wohnung des HERRN auf der Höhe zu Gibeon weiter verbleiben,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 40, 'damit sie dem HERRN regelmäßig, morgens und abends, Brandopfer auf dem Brandopferaltar darbrächten, und zwar genau so, wie es im Gesetz geschrieben steht, das der HERR den Israeliten geboten hat.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 41, 'Bei ihnen befanden sich auch Heman und Jeduthun nebst den übrigen, die auserwählt und mit Namen bezeichnet worden waren, um das »Danket dem HERRN, denn seine Güte währet ewiglich!« zu singen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 42, 'Dazu wurden ihnen Trompeten und Zimbeln gegeben zur Verwendung bei der Musik und Instrumente für die Gotteslieder; die Söhne Jeduthuns aber versahen den Dienst als Torhüter. –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 43, 'Darauf kehrte jedermann im Volk nach Hause zurück; David aber wandte sich dazu, seine Familie zu begrüßen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 17, 1, 'Als nun David in seinem Hause wohnte, sagte er (eines Tages) zu dem Propheten Nathan: »Bedenke doch: ich wohne hier in einem Zedernpalast, während die Lade mit dem Bundesgesetz des HERRN unter Zelttüchern steht.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 17, 2, 'Da antwortete Nathan dem David: »Führe alles aus, was du im Sinn hast, denn Gott ist mit dir!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 17, 3, 'Aber noch in derselben Nacht erging das Wort Gottes an Nathan folgendermaßen:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 17, 4, '»Gehe hin und sage meinem Knecht David: ›So hat der HERR gesprochen: Nicht du sollst mir das Haus zur Wohnung bauen;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 17, 5, 'ich habe ja doch in keinem Hause gewohnt seit der Zeit, da ich die Israeliten aus Ägypten hergeführt habe, bis auf den heutigen Tag, sondern ich habe mich auf der Wanderung von einem Zelt zum andern und von einer Wohnung zur andern befunden.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 17, 6, 'Habe ich etwa, solange ich unter allen Israeliten umherzog, zu einem von den Richtern Israels, die ich zu Hirten meines Volkes bestellt hatte, jemals auch nur ein Wort derart gesagt: ›Warum habt ihr mir kein Zedernhaus gebaut?‹');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 17, 7, 'Darum sollst du jetzt meinem Knecht David folgendes sagen: ›So hat der HERR der Heerscharen gesprochen: Ich habe dich von der Weide hinter der Herde weggeholt, damit du Fürst über mein Volk Israel würdest;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 17, 8, 'und ich bin bei allem, was du unternommen hast, mit dir gewesen und habe alle deine Feinde vor dir her ausgerottet und habe dir einen Namen geschaffen, wie ihn nur die Größten auf Erden haben.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 17, 9, 'Und ich will meinem Volke Israel eine Stätte anweisen und es daselbst einpflanzen, daß es an seiner Stätte ruhig wohnen kann und sich nicht mehr zu ängstigen braucht und daß gewalttätige Menschen es nicht mehr aufreiben wie früher,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 17, 10, 'seit der Zeit, wo ich Richter über mein Volk Israel bestellt habe; sondern ich will alle deine Feinde demütigen und verkündige dir, daß der HERR dir ein Haus bauen wird.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 17, 11, 'Und wenn einst deine Tage voll sind, so daß du zu deinen Vätern hingehst, dann will ich nach deinem Tode deine Nachkommenschaft, und zwar einen von deinen Söhnen, zu deinem Nachfolger erheben und ihm sein Königtum befestigen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 17, 12, 'Der soll mir dann ein Haus bauen, und ich will seinen Thron feststellen für immer.‹«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 17, 13, '»›Ich will ihm Vater sein, und er soll mir Sohn sein, und ich will ihm meine Gnade nicht entziehen, wie ich sie deinem Vorgänger entzogen habe,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 17, 14, 'sondern für immer will ich ihn über mein Haus und mein Königtum einsetzen, und sein Thron soll feststehen für immer!‹«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 17, 15, 'Nachdem Nathan diesen Worten und dieser Offenbarung genau entsprechend zu David geredet hatte,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 17, 16, 'ging der König David (in das Gotteszelt) hinein, setzte sich vor dem HERRN nieder und betete: »Wer bin ich, HERR, mein Gott, und was ist mein Haus, daß du mich bis hierher gebracht hast!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 17, 17, 'Und dies hast du für noch nicht genügend gehalten, o Gott, sondern jetzt hast du auch in bezug auf das Haus deines Knechtes noch Verheißungen für ferne Zeiten gegeben und hast mich schauen lassen Geschlechter der Menschen, HERR, mein Gott.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 17, 18, 'Was soll da David noch weiter zu dir sagen [von der Ehre an deinem Knechte]? Du selbst kennst ja deinen Knecht!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 17, 19, 'HERR, um deines Knechtes willen und nach deinem Wohlgefallen hast du all dieses Große getan, um alle diese Großtaten kundwerden zu lassen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 17, 20, 'HERR, niemand ist dir gleich, und es gibt keinen Gott außer dir nach allem, was wir mit eigenen Ohren vernommen haben.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 17, 21, 'Und wo ist ein anderes Volk, das deinem Volke Israel gliche? Es ist das einzige Volk auf Erden, um deswillen Gott hingegangen ist, es sich zum Eigentumsvolk zu erkaufen, um dir einen Namen zu schaffen durch große und wunderbare Taten, indem du vor deinem Volke, das du aus Ägypten erlöst hast, Heidenvölker vertriebst.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 17, 22, 'So hast du denn dein Volk Israel für alle Zeiten zu deinem Volk bestimmt, und du, HERR, bist ihr Gott geworden.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 17, 23, 'Und nun, HERR – die Verheißung, die du in betreff deines Knechtes und seines Hauses ausgesprochen hast, möge für alle Zeiten gültig bleiben, und verfahre du so, wie du zugesagt hast!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 17, 24, 'Dann wird dein Name sich als treu erweisen und für immer geehrt sein, wenn man sagt: ›Der HERR der Heerscharen, der Gott Israels, ist der Gott für Israel‹; und das Haus deines Knechtes David wird Bestand vor dir haben!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 17, 25, 'Denn du selbst, mein Gott, hast deinem Knechte die Offenbarung zuteil werden lassen, daß du ihm ein Haus bauen wollest; darum hat dein Knecht den Mut gefunden, dieses Gebet an dich zu richten.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 17, 26, 'Und nun, HERR, du bist Gott, und nachdem du deinem Knechte diese herrliche Zusage gemacht hast –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 17, 27, 'nun denn, so möge es dir auch gefallen, das Haus deines Knechtes zu segnen, damit es für immer vor dir bestehe! Denn was du, HERR, gesegnet hast, das ist gesegnet ewiglich!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 18, 1, 'Nachmals besiegte David die Philister und unterwarf sie und entriß der Gewalt der Philister Gath und die zugehörigen Ortschaften. –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 18, 2, 'Er besiegte auch die Moabiter, so daß sie ihm tributpflichtige Untertanen wurden.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 18, 3, 'Sodann besiegte David Hadareser, den König von Zoba, das nach Hamath zu liegt, als er ausgezogen war, um seine Herrschaft am Euphratstrom fest zu begründen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 18, 4, 'Dabei nahm David ihm 1000 Wagen, 7000 Reiter und 20000 Mann Fußvolk weg und ließ die Wagenpferde sämtlich lähmen; nur hundert Wagenpferde behielt er davon für sich.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 18, 5, 'Als dann die Syrer von Damaskus dem König Hadareser von Zoba zu Hilfe kamen, erschlug David von den Syrern 22000 Mann');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 18, 6, 'und setzte dann Vögte über das damascenische Syrien ein, so daß die dortigen Syrer zu tributpflichtigen Untertanen Davids wurden. So verlieh der HERR dem David den Sieg auf allen Zügen, die er unternahm.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 18, 7, 'Auch erbeutete David die goldenen Schilde, welche die Hofbeamten Hadaresers getragen hatten, und ließ sie nach Jerusalem bringen;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 18, 8, 'und in Tibhath und Kun, den Städten Hadaresers, fiel dem König David sehr viel Kupfer in die Hände, woraus Salomo später das große eherne Becken sowie die Säulen und die kupfernen Gerätschaften anfertigen ließ.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 18, 9, 'Als aber Thou, der König von Hamath, erfuhr, daß David die ganze Heeresmacht Hadaresers, des Königs von Zoba, geschlagen hatte,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 18, 10, 'sandte er seinen Sohn Hadoram zum König David, um ihn zu begrüßen und ihm Glück zu wünschen, daß er aus dem Kriege mit Hadareser als Sieger hervorgegangen sei – Thou hatte nämlich auf dem Kriegsfuß mit Hadareser gestanden –, dazu allerlei goldene, silberne und kupferne Kunstgegenstände,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 18, 11, 'die der König David ebenfalls dem HERRN weihte, wie er es auch mit dem Silber und Gold machte, das er von allen Völkern erhoben hatte, von den Edomitern, Moabitern, Ammonitern, Philistern und Amalekitern.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 18, 12, 'Abisai aber, der Sohn der Zeruja, besiegte die Edomiter im Salztal und erschlug von ihnen 18000 Mann,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 18, 13, 'worauf er Vögte über Edom einsetzte, so daß alle Edomiter Untertanen Davids wurden. So verlieh der HERR dem David den Sieg überall, wohin er zog.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 18, 14, 'So herrschte denn David über ganz Israel und ließ Recht und Gerechtigkeit in seinem ganzen Volke walten. –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 18, 15, 'Joab, der Sohn der Zeruja, stand an der Spitze des Heeres; Josaphat, der Sohn Ahiluds, war Kanzler;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 18, 16, 'Zadok, der Sohn Ahitubs, und Ahimelech, der Sohn Abjathars, waren Priester, Sawsa Staatsschreiber,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 18, 17, 'Benaja, der Sohn Jojadas, Befehlshaber (der Leibwache) der Krethi und Plethi; und die Söhne Davids waren die Ersten zur Seite des Königs.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 19, 1, 'Danach begab es sich, daß der Ammoniterkönig Nahas starb und sein Sohn (Hanun) ihm in der Regierung nachfolgte.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 19, 2, 'Da dachte David: »Ich will mich freundlich gegen Hanun, den Sohn des Nahas, beweisen, weil sein Vater sich mir gegenüber freundlich bewiesen hat.« So schickte denn David Gesandte hin, um ihm sein Beileid wegen (des Todes) seines Vaters ausdrücken zu lassen. Als aber die Gesandten Davids im Lande der Ammoniter bei Hanun angekommen waren, um ihm das Beileid zu bezeugen,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 19, 3, 'sagten die Fürsten der Ammoniter zu Hanun: »Meinst du etwa, daß David Beileidsgesandte an dich deshalb geschickt hat, um deinem Vater eine Ehre zu erweisen? Nein, offenbar sind seine Gesandten nur deshalb zu dir gekommen, um das Land gründlich auszukundschaften und um zu spionieren.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 19, 4, 'Da ließ Hanun die Gesandten Davids festnehmen, ließ sie scheren und ihnen die Röcke halb abschneiden bis unter den Gürtel und entließ sie dann.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 19, 5, 'So machten sie sich denn auf den Weg. Als man nun dem David meldete, was den Männern geschehen war, schickte er ihnen Boten entgegen – denn die Männer waren schwer beschimpft –; und der König ließ ihnen sagen: »Bleibt in Jericho, bis euch der Bart wieder gewachsen ist: dann kehrt zurück!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 19, 6, 'Als nun die Ammoniter einsahen, daß sie David tödlich beleidigt hatten, schickten Hanun und die Ammoniter tausend Talente Silber hin, um von den Syrern in Mesopotamien und von den Syrern in Maacha und in Zoba Kriegswagen und Reiter in Sold zu nehmen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 19, 7, 'So nahmen sie denn 32000 Wagen in ihren Dienst, dazu den König von Maacha mit seinem Heere; die kamen und lagerten sich vor Medeba; die Ammoniter aber sammelten sich auch aus ihren Ortschaften und rückten zum Kampf ins Feld.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 19, 8, 'Als David das erfuhr, ließ er Joab mit dem ganzen Heer, auch den Rittern, ausrücken.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 19, 9, 'Die Ammoniter zogen dann aus der Stadt hinaus und stellten sich vor dem Stadttor in Schlachtordnung auf, während die Könige, die herbeigekommen waren, für sich im freien Felde standen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 19, 10, 'Als nun Joab sah, daß ihm sowohl von vorn als auch im Rücken ein Angriff drohe, nahm er aus allen auserlesenen israelitischen Kriegern eine Auswahl vor und stellte sich mit ihnen den Syrern gegenüber auf;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 19, 11, 'den Rest des Heeres aber überwies er seinem Bruder Abisai, damit sie sich den Ammonitern gegenüber aufstellten.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 19, 12, 'Dann sagte er: »Wenn die Syrer mir zu stark sind, so kommst du mir zu Hilfe; und wenn die Ammoniter dir überlegen sind, so komme ich dir zu Hilfe.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 19, 13, 'Nur Mut! Wir wollen tapfer kämpfen für unser Volk und für die Städte unsers Gottes; der HERR aber möge tun, was ihm wohlgefällt!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 19, 14, 'Darauf rückte Joab mit der Mannschaft, die unter seinem Befehl stand, zum Angriff gegen die Syrer vor, und diese wandten sich vor ihm zur Flucht;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 19, 15, 'und als die Ammoniter die Flucht der Syrer (vor Joab) gewahrten, flohen auch sie vor seinem Bruder Abisai und zogen sich in die Stadt zurück. Joab aber kehrte nach Jerusalem zurück.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 19, 16, 'Als nun die Syrer sich von den Israeliten geschlagen sahen, sandten sie Boten hin und ließen die Syrer von jenseits des Euphrats ins Feld rücken, und zwar unter der Führung Sophachs, des Feldherrn Hadaresers.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 19, 17, 'Auf die Kunde hiervon bot David ganz Israel zum Kriege auf, überschritt den Jordan und gelangte (nach Helam). Als David sich dann den Syrern gegenüber in Schlachtordnung aufgestellt hatte und sie handgemein mit ihnen geworden waren,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 19, 18, 'wurden die Syrer von den Israeliten in die Flucht geschlagen, und David erschlug von den Syrern 7000 Wagenkämpfer und 40000 Mann Fußvolk; auch den Feldherrn Sophach tötete er.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 19, 19, 'Als sich nun die Leute Hadaresers von den Israeliten besiegt sahen, schlossen sie Frieden mit David und unterwarfen sich ihm. Infolgedessen hatten auch die Syrer keine Lust mehr, den Ammonitern noch Hilfe zu leisten.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 20, 1, 'Im folgenden Jahre aber führte Joab zu der Zeit, wo die Könige ins Feld zu ziehen pflegen, das Heer ins Feld und verwüstete das Land der Ammoniter; dann zog er hin und belagerte Rabba, während David in Jerusalem geblieben war. Als Joab dann Rabba erobert und zerstört hatte,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 20, 2, 'nahm David ihrem Götzen Milkom die Krone vom Haupt – diese wog, wie er feststellte, ein Talent Gold und war mit einem kostbaren Edelstein besetzt; der kam (nun) auf das Haupt Davids –; und er führte aus der Stadt eine überaus reiche Beute weg.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 20, 3, 'Die Bevölkerung aber, die sich dort vorfand, ließ er wegführen und stellte sie als Zwangsarbeiter an die Sägen, an die eisernen Picken und die Äxte. Ebenso verfuhr er mit allen übrigen Städten der Ammoniter. Dann kehrte David mit dem ganzen Heere nach Jerusalem zurück.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 20, 4, 'Später kam es dann nochmals zum Kampf mit den Philistern bei Geser. Damals erschlug der Husathiter Sibbechai den Sippai, einen von den Riesenkindern, und so wurden sie gedemütigt.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 20, 5, 'Als dann nochmals ein Kampf mit den Philistern stattfand, erschlug Elhanan, der Sohn Jairs, Lahmi, den Bruder Goliaths aus Gath, dessen Speerschaft wie ein Weberbaum war. –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 20, 6, 'Als es dann wiederum zum Kampf bei Gath kam, war da ein Mann von riesiger Größe, der je sechs Finger und sechs Zehen hatte, im ganzen vierundzwanzig; auch dieser stammte von dem Riesengeschlecht.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 20, 7, 'Er hatte die Israeliten verhöhnt; aber Jonathan, der Sohn Simeas, des Bruders Davids, erschlug ihn.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 20, 8, 'Diese drei stammten aus dem Riesengeschlecht in Gath und fielen durch die Hand Davids und seiner Krieger.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 21, 1, 'Es trat aber (der) Satan gegen Israel auf und verführte David dazu, eine Zählung der Israeliten vorzunehmen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 21, 2, 'So gebot denn David dem Joab und den Obersten des Volkes: »Geht hin und nehmt eine Zählung in Israel vor von Beerseba bis Dan und erstattet mir Bericht, damit ich die Zahl des Volkes erfahre!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 21, 3, 'Joab entgegnete: »Der HERR möge sein Volk, so zahlreich es auch jetzt schon ist, noch hundertmal zahlreicher werden lassen! Sie sind ja doch alle, mein Herr und König, gehorsame Untertanen meines Herrn. Warum hegt mein Herr solchen Wunsch? Warum soll Israel eine Verschuldung auf sich laden?«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 21, 4, 'Aber der Befehl des Königs blieb trotz der Vorstellungen Joabs bestehen; und so machte sich denn dieser auf den Weg und durchwanderte ganz Israel. Als er dann nach Jerusalem zurückgekehrt war,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 21, 5, 'teilte er David das Ergebnis der Volkszählung mit; da belief sich die Zahl der schwertbewaffneten Männer in ganz Israel auf 1 110000 und in Juda auf 470000 schwertbewaffnete Männer.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 21, 6, 'Die Stämme Levi und Benjamin aber hatte er nicht mit in die Zählung einbegriffen; denn der Befehl des Königs war für Joab ein Greuel.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 21, 7, 'Weil aber diese ganze Sache das Mißfallen Gottes erregte, so daß er Israel schwer heimsuchte,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 21, 8, 'betete David zu Gott: »Ich habe mich schwer dadurch versündigt, daß ich dies getan habe; nun aber, laß doch deinem Knecht seine Verschuldung ungestraft hingehen! Denn ich habe in großer Verblendung gehandelt.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 21, 9, 'Aber der HERR ließ Gad, dem Seher Davids, folgende Weisung zukommen:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 21, 10, '»Gehe hin und sage zu David: ›So hat der HERR gesprochen: Dreierlei lege ich dir vor! Wähle dir eines davon, damit ich es an dir zur Ausführung bringe!‹«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 21, 11, 'Da begab sich Gad zu David und sagte zu ihm: »So hat der HERR gesprochen: ›Wähle dir');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 21, 12, 'entweder drei Jahre Hungersnot oder daß du drei Monate vor deinen Widersachern fliehen mußt und das Schwert deiner Feinde dir zusetzt oder daß das Schwert des HERRN und die Pest drei Tage lang im Lande wütet, so daß der Engel des HERRN im ganzen Bereich Israels Verderben anrichtet.‹ Und nun überlege, welche Antwort ich dem bringen soll, der mich gesandt hat!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 21, 13, 'Da sagte David zu Gad: »Mir ist sehr bange! Ich will lieber in die Hand des HERRN fallen, denn seine Gnadenerweise sind sehr groß; aber in die Hand der Menschen möchte ich nicht fallen!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 21, 14, 'So ließ denn der HERR eine Pest über Israel kommen, so daß siebzigtausend Menschen in Israel den Tod fanden.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 21, 15, 'Dann sandte der HERR einen Engel nach Jerusalem, um es zu verheeren; doch als er Verheerungen darin anrichtete, sah der HERR darein, und es gereute ihn das Unheil, und er gebot dem Engel, der die Verheerung anzurichten hatte: »Es ist genug so: laß jetzt deine Hand ruhen!« Der Engel des HERRN stand aber gerade bei der Tenne des Jebusiters Ornan.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 21, 16, 'Als nun David aufblickte und den Engel des HERRN zwischen Erde und Himmel stehen sah, wie er das gezückte Schwert, das über Jerusalem ausgestreckt war, in der Hand hielt, da fielen David und die Ältesten, in Trauerkleider gehüllt, auf ihr Angesicht nieder,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 21, 17, 'und David betete zu Gott: »Ach, ich bin’s ja, der die Volkszählung veranlaßt hat, und ich bin es, der gesündigt und ein großes Unrecht begangen hat! Diese Herde aber, was hat sie verschuldet? HERR, mein Gott, laß doch deine Hand mich und das Haus meines Vaters treffen, aber nicht dein Volk zum Sterben!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 21, 18, 'Nun gebot der Engel des HERRN dem Gad, er möge David sagen, David solle hinaufgehen und dem HERRN einen Altar auf der Tenne des Jebusiters Ornan errichten.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 21, 19, 'Da begab sich David nach der Aufforderung, die Gad im Namen des HERRN an ihn gerichtet hatte, hinauf.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 21, 20, '[Als nun Ornan sich umwandte, sah er den Engel, während seine vier Söhne sich bei ihm versteckt hielten – Ornan drosch nämlich gerade Weizen –.]');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 21, 21, 'Als nun David zu Ornan kam und dieser aufblickte und David gewahrte, trat er aus der Tenne hinaus und verneigte sich vor David mit dem Angesicht bis zur Erde.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 21, 22, 'Da sagte David zu Ornan: »Überlaß mir den Platz der Tenne hier, damit ich dem HERRN einen Altar darauf erbaue; für den vollen Geldeswert überlaß ihn mir, damit dem Sterben unter dem Volke Einhalt getan wird.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 21, 23, 'Da antwortete Ornan dem David: »Nimm ihn hin: mein Herr und König wolle tun, was ihm beliebt! Siehe da, ich gebe dir die Rinder zu den Brandopfern und die Dreschschlitten als Brennholz und den Weizen zum Speisopfer: das alles gebe ich her!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 21, 24, 'Aber der König David erwiderte dem Ornan: »Nein, käuflich will ich es von dir erwerben zum vollen Wert; denn ich will dir nicht dein Eigentum für den HERRN wegnehmen und will keine Brandopfer darbringen, die mir geschenkt sind!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 21, 25, 'So gab denn David dem Ornan für den Platz Gold im Gewicht von sechshundert Schekeln.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 21, 26, 'David erbaute alsdann dem HERRN dort einen Altar und brachte Brandopfer und Heilsopfer dar; und als er den HERRN anrief, erhörte dieser ihn, indem er Feuer vom Himmel auf den Brandopferaltar fallen ließ.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 21, 27, 'Der HERR gebot alsdann dem Engel, und dieser steckte sein Schwert wieder in die Scheide.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 21, 28, 'Weil David damals die Erfahrung gemacht hatte, daß der HERR ihn auf der Tenne des Jebusiters Ornan erhört hatte, brachte er dort Opfer dar.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 21, 29, 'Aber die Wohnung des HERRN, die Mose in der Wüste hergestellt hatte, und der Brandopferaltar befanden sich zu jener Zeit auf der Höhe bei Gibeon.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 21, 30, 'Doch David gewann es nicht über sich, dort vor Gott zu treten, um ihn zu verehren, weil er durch das Schwert des Engels des HERRN in Schrecken versetzt worden war.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 22, 1, 'Und David erklärte: »Dies hier muß das Haus Gottes, des HERRN, werden und dies der Brandopferaltar für Israel!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 22, 2, 'Hierauf befahl David, man solle die Fremdlinge, die sich im Lande Israel befanden, zusammenbringen, und er beschäftigte sie als Steinmetzen, um Quadersteine zum Bau des Tempels Gottes zuzuhauen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 22, 3, 'Auch Eisen beschaffte David in Menge zu Nägeln für die Torflügel und zu Klammern, ebenso Kupfer in solcher Menge, daß man es nicht wägen konnte;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 22, 4, 'ferner zahllose Zedernstämme, denn die Sidonier und Tyrier brachten dem David Zedernholz in Menge.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 22, 5, 'David dachte nämlich: »Mein Sohn Salomo ist noch jung und zart, der Tempel aber, der dem HERRN erbaut werden soll, muß überaus großartig werden, damit er in der ganzen Welt berühmt und bewundert dasteht; darum will ich die zum Bau erforderlichen Vorbereitungen für ihn treffen.« So traf denn David vor seinem Tode Zurüstungen in Menge.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 22, 6, 'Sodann ließ er seinen Sohn Salomo zu sich kommen und machte es ihm zur Pflicht, dem HERRN, dem Gott Israels, einen Tempel zu erbauen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 22, 7, 'Dabei richtete David folgende Worte an Salomo: »Mein Sohn! Ich selbst hatte die Absicht, dem Namen des HERRN, meines Gottes, einen Tempel zu erbauen;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 22, 8, 'aber da erging das Wort des HERRN an mich folgendermaßen: ›Du hast Blut in Menge vergossen und schwere Kriege geführt; du darfst meinem Namen kein Haus erbauen, weil du viel Blut vor meinen Augen zur Erde hast fließen lassen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 22, 9, 'Doch wisse: ein Sohn wird dir geboren werden, der wird ein Mann der Ruhe sein, und ich will ihm Ruhe vor all seinen Feinden ringsum schaffen; denn Salomo soll sein Name sein, und Frieden und Ruhe will ich in Israel während seiner Regierung herrschen lassen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 22, 10, 'Der soll meinem Namen ein Haus erbauen; er soll mir als Sohn gelten und ich ihm als Vater, und seinen Königsthron über Israel will ich auf ewig feststellen.‹');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 22, 11, 'Nun denn, mein Sohn: der HERR wolle mit dir sein, damit es dir gelingt, den Tempel des HERRN, deines Gottes, zu erbauen, wie er es von dir verheißen hat!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 22, 12, 'Nur möge der HERR dir Klugheit und Einsicht verleihen, wenn er dich zum Herrscher über Israel bestellt, und (wolle geben,) daß du das Gesetz des HERRN, deines Gottes, beobachtest!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 22, 13, 'Dann wirst du Glück haben, wenn du die Satzungen und Verordnungen gewissenhaft befolgst, die der HERR den Israeliten durch Mose geboten hat. Sei fest und stark! Fürchte dich nicht und laß dir nicht bange sein!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 22, 14, 'Siehe, trotz meines mühseligen Lebens habe ich für den Tempel des HERRN hunderttausend Talente Gold und eine Million Talente Silber beschafft, ferner an Kupfer und Eisen so viel, daß es nicht zu wägen ist: in solcher Menge ist es vorhanden; auch Holzstämme und Steine habe ich beschafft, und du wirst noch mehr dazutun.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 22, 15, 'Auch Werkleute stehen dir in großer Zahl zur Verfügung: Steinmetzen, Maurer und Zimmerleute, kunstverständige Männer jeder Art für alle Arbeiten');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 22, 16, 'in Gold und Silber, in Kupfer und Eisen ohne Zahl. Wohlan, gehe ans Werk, und der HERR sei mit dir!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 22, 17, 'Hierauf forderte David alle Obersten Israels auf, seinem Sohne Salomo hilfreich zur Seite zu stehen, mit den Worten:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 22, 18, '»Ist nicht der HERR, euer Gott, mit euch gewesen, und hat er euch nicht ringsum Ruhe verschafft? Er hat ja die Bewohner des Landes in meine Gewalt gegeben, und das Land liegt unterworfen vor dem HERRN und seinem Volke da.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 22, 19, 'So richtet denn euer Herz und euren Sinn darauf, den HERRN, euren Gott, zu suchen, und macht euch daran, das Heiligtum Gottes, des HERRN, zu erbauen, damit ihr die Bundeslade des HERRN und die heiligen Geräte Gottes in den Tempel bringen könnt, der dem Namen des HERRN erbaut werden soll!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 23, 1, 'Als nun David alt und lebenssatt war, machte er seinen Sohn Salomo zum König über Israel.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 23, 2, 'Er ließ dabei alle Obersten Israels sowie die Priester und Leviten zusammenkommen;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 23, 3, 'und als man die Leviten im Alter von dreißig und mehr Jahren zählte, ergab sich bei ihnen eine Kopfzahl von 38000 Männern.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 23, 4, '»Von diesen«, gebot David, »sollen 24000 dem Dienst am Hause des HERRN vorstehen, 6000 sollen Amtleute und Richter sein,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 23, 5, '4000 Torhüter, und 4000 sollen zum Lobpreis des HERRN die Instrumente spielen, die ich zu diesem Zweck habe anfertigen lassen.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 23, 6, 'David teilte sie dann in Abteilungen nach den Söhnen Levis, nach Gerson, Kahath und Merari.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 23, 7, 'Zu den Gersoniten gehörten: Laedan und Simei.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 23, 8, 'Die Söhne Laedans waren: Jehiel, das Oberhaupt, ferner Setham und Joel, zusammen drei.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 23, 9, 'Die Söhne Simeis waren: Selomith, Hasiel und Haran, zusammen drei. Dies waren die Familienhäupter der Laedaniten.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 23, 10, 'Die Söhne Simeis waren: Jahath, Sisa, Jehus und Beria; dies waren Simeis Söhne, zusammen vier;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 23, 11, 'und zwar war Jahath das Oberhaupt und Sisa der zweite; Jehus und Beria aber hatten nicht viele Söhne; darum bildeten sie nur eine Familie, nur eine Klasse.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 23, 12, 'Die Söhne Kehaths waren: Amram, Jizhar, Hebron und Ussiel, zusammen vier.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 23, 13, 'Die Söhne Amrams waren: Aaron und Mose. Aaron aber wurde ausgesondert, damit er den Dienst für das Allerheiligste versehe, er und seine Nachkommen auf ewige Zeiten, um vor dem HERRN die Rauchopfer darzubringen, ihm zu dienen und in seinem Namen den Segen zu sprechen ewiglich.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 23, 14, 'Was aber Mose, den Mann Gottes, betrifft, so wurden seine Söhne einfach zum Stamme Levi gerechnet.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 23, 15, 'Die Söhne Moses waren: Gersom und Elieser;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 23, 16, 'die Söhne Gersoms: Sebuel, das Oberhaupt.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 23, 17, 'Und die Söhne Eliesers waren: Rehabja, das Oberhaupt; andere Söhne hatte Elieser nicht, während die Söhne Rehabjas überaus zahlreich waren. –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 23, 18, 'Die Söhne Jizhars waren: Selomith, das Oberhaupt;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 23, 19, 'die Söhne Hebrons: Jerija, das Oberhaupt, Amarja der zweite, Ussiel der dritte, Jekameam der vierte.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 23, 20, 'Die Söhne Ussiels waren: Micha, das Oberhaupt, und Jissia, der zweite.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 23, 21, 'Die Söhne Meraris waren: Mahli und Musi; die Söhne Mahlis: Eleasar und Kis.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 23, 22, 'Eleasar aber hinterließ bei seinem Tode keine Söhne, sondern nur Töchter, die sich mit ihren Vettern, den Söhnen des Kis, verheirateten.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 23, 23, 'Die Söhne Musis waren: Mahli, Eder und Jeremoth, zusammen drei.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 23, 24, 'Dies waren die Nachkommen Levis nach ihren Familien, die Familienhäupter, soviele ihrer gemustert wurden, nach Köpfen namentlich aufgezählt, die beim Dienst am Tempel des HERRN beschäftigt waren, von zwanzig Jahren an und darüber.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 23, 25, 'Denn David dachte: »Der HERR, der Gott Israels, hat seinem Volke Ruhe verschafft und wohnt nun für immer in Jerusalem;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 23, 26, 'so brauchen nun auch die Leviten das Zelt und alle zu seiner Bedienung erforderlichen Geräte nicht mehr zu tragen«;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 23, 27, 'denn nach den letzten Anordnungen Davids waren die Leviten im Alter von zwanzig Jahren und darüber gezählt worden.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 23, 28, 'Vielmehr dient nun ihre Amtstätigkeit zur Unterstützung der Nachkommen Aarons beim Dienst am Tempel des HERRN als Aufseher über die Vorhöfe und über die Zellen und über die Reinigung alles Heiligen, überhaupt für alles, was zu den Dienstleistungen am Tempel des HERRN gehört,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 23, 29, 'außerdem für die Besorgung der aufgeschichteten Schaubrote und des Feinmehls zu den Speisopfern, für die ungesäuerten Fladen, für das Pfannenbackwerk und das Eingerührte sowie für alles (Messen mit) Hohl- und Längenmaßen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 23, 30, 'Auch müssen sie alle Morgen antreten, um dem HERRN Lob- und Danklieder zu singen, ebenso auch am Abend.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 23, 31, 'Auch bei jeder Darbringung von Brandopfern für den HERRN haben sie an den Sabbaten, Neumonden und Festen Dienst zu tun, sooft Opfer nach der dafür feststehenden Ordnung regelmäßig dem HERRN darzubringen sind.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 23, 32, 'So haben sie also die Geschäfte am Offenbarungszelt und die Geschäfte am Heiligtum, überhaupt die Geschäfte zur Unterstützung der Nachkommen Aarons, ihrer Stammesgenossen, beim Dienst am Tempel des HERRN zu besorgen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 24, 1, 'Was sodann die Nachkommen Aarons betrifft, so waren ihre Abteilungen folgende: Die Söhne Aarons waren: Nadab und Abihu, Eleasar und Ithamar.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 24, 2, 'Nadab und Abihu starben jedoch vor ihrem Vater, ohne Söhne zu hinterlassen; daher übten Eleasar und Ithamar den Priesterdienst allein aus.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 24, 3, 'David teilte sie nun, im Einvernehmen mit Zadok von den Nachkommen Eleasars und mit Ahimelech von den Nachkommen Ithamars, in Klassen ein je nach ihrem Amt bei ihrer Dienstleistung.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 24, 4, 'Dabei stellte es sich nun heraus, daß die Nachkommen Eleasars an Familienhäuptern zahlreicher waren als die Nachkommen Ithamars; daher teilte man sie so ab, daß auf die Nachkommen Eleasars sechzehn, auf die Nachkommen Ithamars acht Familienhäupter kamen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 24, 5, 'Man teilte sie aber, die einen wie die anderen, durch Lose ab; denn sowohl unter Eleasars als auch unter Ithamars Nachkommen gab es ›Fürsten des Heiligtums‹ und ›Fürsten Gottes‹;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 24, 6, 'und Semaja, der Sohn Nethaneels, der Schriftführer unter den Leviten, schrieb sie in Gegenwart des Königs und der Fürsten sowie des Priesters Zadok und Ahimelechs, des Sohnes Abjathars, und der Familienhäupter der Priester und der Leviten auf: je eine Familie wurde für Ithamar ausgelost, und dann wurde je zweimal eine für Eleasar ausgelost.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 24, 7, 'Das erste Los fiel auf Jojarib, das zweite auf Jedaja,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 24, 8, 'das dritte auf Harim, das vierte auf Seorim,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 24, 9, 'das fünfte auf Malchia, das sechste auf Mijjamin,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 24, 10, 'das siebte auf Hakkoz, das achte auf Abia,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 24, 11, 'das neunte auf Jesua, das zehnte auf Sechanja,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 24, 12, 'das elfte auf Eljasib, das zwölfte auf Jakim,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 24, 13, 'das dreizehnte auf Huppa, das vierzehnte auf Jesebab,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 24, 14, 'das fünfzehnte auf Bilga, das sechzehnte auf Immer,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 24, 15, 'das siebzehnte auf Hesir, das achtzehnte auf Happizzez,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 24, 16, 'das neunzehnte auf Pethahja, das zwanzigste auf Jeheskel,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 24, 17, 'das einundzwanzigste auf Jachin, das zweiundzwanzigste auf Gamul,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 24, 18, 'das dreiundzwanzigste auf Delaja, das vierundzwanzigste auf Maasja.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 24, 19, 'Dies war ihre Klassenordnung für ihren Dienst, damit sie entsprechend der durch ihren Ahnherrn Aaron für sie bestimmten Verordnung in den Tempel des HERRN einträten, wie der HERR, der Gott Israels, ihm geboten hatte.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 24, 20, 'Was aber die übrigen Nachkommen Levis betrifft, so war von den Nachkommen Amrams Subael da, von den Nachkommen Subaels Jehdeja;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 24, 21, 'von den Nachkommen Rehabjas war Jissia das Oberhaupt. –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 24, 22, 'Von den Jizhariten: Selomoth, von den Nachkommen Selomoths: Jahath. –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 24, 23, 'Die Nachkommen Hebrons waren: Jerija das Oberhaupt, Amarja der zweite, Jahasiel der dritte, Jekameam der vierte. –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 24, 24, 'Die Nachkommen Ussiels waren: Micha; von den Nachkommen Michas: Samir.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 24, 25, 'Michas Bruder war Jissia; von den Nachkommen Jissias: Sacharja. –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 24, 26, 'Die Nachkommen Meraris waren: Mahli und Musi und die Nachkommen seines Sohnes Jaasia.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 24, 27, 'Die Nachkommen Meraris von seinem Sohne Ussia waren: Soham, Sakkur und Ibri;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 24, 28, 'von Mahli: Eleasar, der aber keine Söhne hatte, und Kis;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 24, 29, 'von Kis: die Söhne des Kis: Jerahmeel.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 24, 30, 'Die Nachkommen Musis waren: Mahli, Eder und Jerimoth. Dies waren die Nachkommen der Leviten nach ihren Familien. –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 24, 31, 'Auch sie wurden ausgelost ganz wie ihre Stammesgenossen, die Nachkommen Aarons, in Gegenwart des Königs David und Zadoks und Ahimelechs sowie der Familienhäupter der Priester und der Leviten, und zwar die Familienhäupter ganz ebenso wie ihre jüngsten Stammesgenossen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 25, 1, 'Weiter sonderte David mit den Heeresobersten von den Söhnen Asaphs, Hemans und Jeduthuns diejenigen aus, die auf Zithern, Harfen und mit Zimbeln als Leiter der geistlichen Kunstmusik für den heiligen Dienst tätig waren. Die Zahl der zu diesem Dienst bestellten Männer war folgende:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 25, 2, 'Von den Söhnen Asaphs: Sakkur, Joseph, Nethanja und Asarela, die Söhne Asaphs, unter der Leitung Asaphs, der nach Anweisung des Königs geistliche Kunstmusik darbot.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 25, 3, 'Von Jeduthun: Jeduthuns Söhne: Gedalja, Zeri, Jesaja, Hasabja, Matthithja und Simei, zusammen sechs, unter der Leitung ihres Vaters Jeduthun, der zum Lobpreis und zur Verherrlichung des HERRN geistliche Kunstmusik auf der Harfe darbot.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 25, 4, 'Von Heman: Hemans Söhne: Bukkia, Matthanja, Ussiel, Subael, Jerimoth, Hananja, Hanani, Eliatha, Giddalthi, Romamthi-Eser, Josbekasa, Mallothi, Hothir und Mahasioth.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 25, 5, 'Diese alle waren Söhne Hemans, des Sehers des Königs, nach der Verheißung Gottes, ihm das Horn zu erhöhen; denn Gott hatte dem Heman vierzehn Söhne und drei Töchter geschenkt.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 25, 6, 'Diese alle waren unter der Leitung ihres Vaters Asaph beim Gesang im Tempel des HERRN mit Zimbeln, Harfen und Zithern für den Gottesdienst im Tempel nach der Anweisung des Königs, Asaphs, Jeduthuns und Hemans tätig.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 25, 7, 'Ihre Anzahl, inbegriffen ihre Amtsgenossen, die im Gesang für den HERRN geübt waren, allesamt Künstler, betrug 288.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 25, 8, 'Als sie nun die Losung zur Feststellung der Reihenfolge ihres Dienstes vornahmen, die jüngeren ganz wie die älteren, die Meister samt den Schülern,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 25, 9, 'fiel das erste Los für Asaph auf Joseph nebst seinen Söhnen und Brüdern, zusammen zwölf; das zweite auf Gedalja nebst seinen Brüdern und Söhnen, zusammen zwölf;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 25, 10, 'das dritte auf Sakkur nebst seinen Söhnen und Brüdern, zusammen zwölf;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 25, 11, 'das vierte auf Jizri nebst seinen Söhnen und Brüdern, zusammen zwölf;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 25, 12, 'das fünfte auf Nethanja nebst seinen Söhnen und Brüdern, zusammen zwölf;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 25, 13, 'das sechste auf Bukkia nebst seinen Söhnen und Brüdern, zusammen zwölf;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 25, 14, 'das siebte auf Jesarela nebst seinen Söhnen und Brüdern, zusammen zwölf;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 25, 15, 'das achte auf Jesaja nebst seinen Söhnen und Brüdern, zusammen zwölf;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 25, 16, 'das neunte auf Matthanja nebst seinen Söhnen und Brüdern, zusammen zwölf;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 25, 17, 'das zehnte auf Simei nebst seinen Söhnen und Brüdern, zusammen zwölf;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 25, 18, 'das elfte auf Ussiel nebst seinen Söhnen und Brüdern, zusammen zwölf;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 25, 19, 'das zwölfte auf Hasabja nebst seinen Söhnen und Brüdern, zusammen zwölf;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 25, 20, 'das dreizehnte auf Subael nebst seinen Söhnen und Brüdern, zusammen zwölf;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 25, 21, 'das vierzehnte auf Matthitja nebst seinen Söhnen und Brüdern, zusammen zwölf;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 25, 22, 'das fünfzehnte auf Jeremoth nebst seinen Söhnen und Brüdern, zusammen zwölf;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 25, 23, 'das sechzehnte auf Hananja nebst seinen Söhnen und Brüdern, zusammen zwölf;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 25, 24, 'das siebzehnte auf Josbekasa nebst seinen Söhnen und Brüdern, zusammen zwölf;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 25, 25, 'das achtzehnte auf Hanani nebst seinen Söhnen und Brüdern, zusammen zwölf;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 25, 26, 'das neunzehnte auf Mallothi nebst seinen Söhnen und Brüdern, zusammen zwölf;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 25, 27, 'das zwanzigste auf Eliatha nebst seinen Söhnen und Brüdern, zusammen zwölf;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 25, 28, 'das einundzwanzigste auf Hothir nebst seinen Söhnen und Brüdern, zusammen zwölf;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 25, 29, 'das zweiundzwanzigste auf Giddalthi nebst seinen Söhnen und Brüdern, zusammen zwölf;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 25, 30, 'das dreiundzwanzigste auf Mahasioth nebst seinen Söhnen und Brüdern, zusammen zwölf;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 25, 31, 'das vierundzwanzigste auf Romamthi-Eser nebst seinen Söhnen und Brüdern, zusammen zwölf.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 26, 1, 'Was die Abteilungen der Torhüter betrifft, so gehörte von den Korahiten Meselemja, der Sohn Kores, zu den Nachkommen Ebjasaphs;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 26, 2, 'Meselemjas Söhne aber waren: Sacharja der erstgeborene, Jediael der zweite, Sebadja der dritte, Jathniel der vierte,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 26, 3, 'Elam der fünfte, Johanan der sechste, Eljehoenai der siebte. –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 26, 4, 'Die Söhne Obed-Edoms waren: Semaja der erstgeborene, Josabad der zweite, Joah der dritte, Sachar der vierte, Nethaneel der fünfte,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 26, 5, 'Ammiel der sechste, Issaschar der siebte, Pehullethai der achte; denn Gott hatte ihn gesegnet. –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 26, 6, 'Auch seinem Sohne Semaja waren Söhne geboren, welche in ihrer Familie eine leitende Stellung einnahmen, denn sie waren tüchtige Männer.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 26, 7, 'Die Söhne Semajas waren: Othni, Rephael, Obed, Elsabad und seine Brüder, Elihu und Semachja, wackere Männer.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 26, 8, 'Diese alle gehörten zu den Nachkommen Obed-Edoms, sie, ihre Söhne und ihre Brüder, tüchtige Männer, tauglich zu Dienstleistungen, zusammen zweiundsechzig von Obed-Edom. –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 26, 9, 'Auch Meselemja hatte Söhne und Brüder, tüchtige Männer, zusammen achtzehn. –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 26, 10, 'Die Söhne Hosas, der zu den Nachkommen Meraris gehörte, waren: Simri als Oberhaupt – obwohl er nicht der Erstgeborene war, hatte ihn sein Vater doch zum Oberhaupt eingesetzt –,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 26, 11, 'Hilkia der zweite Sohn, Tebalja der dritte, Sacharja der vierte; die Gesamtzahl aller Söhne und Brüder Hosas betrug dreizehn.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 26, 12, 'Diesen Abteilungen der Torhüter, und zwar den Familienhäuptern, fielen gerade wie ihren Stammesgenossen Amtsgeschäfte im Dienst am Tempel des HERRN zu.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 26, 13, 'Als man nämlich die Verlosung der einzelnen Tore nach den Familien, für die älteren wie für die jüngeren, vornahm,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 26, 14, 'fiel für die Ostseite das Los auf Selemja. Auch für seinen Sohn Sacharja, einen klugen Ratgeber, warf man Lose, und das Los fiel für ihn auf die Nordseite;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 26, 15, 'für Obed-Edom auf die Südseite und für seine Söhne auf das Vorratsgebäude;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 26, 16, 'für Hosa auf die Westseite beim Tor Sallecheth, da wo die Straße ansteigt, eine Wache neben der andern.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 26, 17, 'Auf der Ostseite waren täglich sechs Leviten auf Wache, nach Norden zu täglich vier, nach Süden zu täglich vier, und am Vorratsgebäude je zwei;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 26, 18, 'am Parbar auf der Westseite: vier an der Straße und zwei am Parbar.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 26, 19, 'Dies sind die Abteilungen der Torhüter von den Nachkommen der Korahiten und von den Nachkommen Meraris.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 26, 20, 'Ihre levitischen Stammesgenossen aber, welche die Aufsicht über die Schatzkammern des Hauses Gottes und über die Schätze an geweihten Gegenständen hatten, waren:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 26, 21, 'die Nachkommen Ladans, die Nachkommen des Gersoniten Ladan, die Familienhäupter vom Geschlecht des Gersoniten Ladan, die Jehieliten.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 26, 22, 'Die Nachkommen der Jehieliten waren: Setham und sein Bruder Joel, welche die Aufsicht über die Schätze des Gotteshauses hatten. –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 26, 23, 'Was sodann die Amramiten, Jizhariten, Hebroniten und Ussieliten betrifft,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 26, 24, 'so war Subael, ein Nachkomme Gersoms, des Sohnes Moses, Oberaufseher über die Schätze. –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 26, 25, 'Was ferner seine Stammesgenossen von Elieser her betrifft, so war dessen Sohn Rehabja, dessen Sohn Jesaja, dessen Sohn Joram, dessen Sohn Sichri, dessen Sohn Selomith.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 26, 26, 'Dieser Selomith und seine Brüder waren über alle Schätze an geweihten Gegenständen gesetzt, welche der König David und die Familienhäupter, ferner die Befehlshaber der Tausendschaften und der Hundertschaften sowie die Heerführer geweiht hatten, –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 26, 27, 'von der Beute aus den Kriegen hatten sie sie geweiht, um das Haus des HERRN damit auszustatten –;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 26, 28, 'auch alles, was der Seher Samuel und Saul, der Sohn des Kis, und Abner, der Sohn Ners, und Joab, der Sohn der Zeruja, geweiht hatten, überhaupt alle Weihgeschenke standen unter der Aufsicht Selomiths und seiner Geschlechtsgenossen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 26, 29, 'Aus (dem Geschlecht) der Jizhariten waren Kenanja und seine Söhne für die auswärtigen Geschäfte bezüglich Israels als Amtleute und Richter bestellt. –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 26, 30, 'Aus (dem Geschlecht) der Hebroniten waren Hasabja und seine Geschlechtsgenossen, tüchtige Männer, 1700 an der Zahl, über die Verwaltung Israels westlich vom Jordan für alle Angelegenheiten des HERRN und für den Dienst des Königs eingesetzt. –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 26, 31, 'Zu den Hebroniten gehörte Jerija, das Oberhaupt – was die Hebroniten betrifft, so forschte man nach ihren Geschlechtern und Familien im vierzigsten Regierungsjahre Davids, und es fanden sich unter ihnen tüchtige Männer zu Jaeser in Gilead –,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 26, 32, 'dazu seine Stammesgenossen, tüchtige Männer, zusammen 2700; denen übertrug der König David die Verwaltung der Stämme Ruben, Gad und halb Manasse für alle Angelegenheiten Gottes und für die Angelegenheiten des Königs.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 1, 'Und dies waren die Israeliten nach ihrer Zahl, die Familienhäupter und die Befehlshaber der Tausendschaften und der Hundertschaften sowie ihre Amtleute, die im Dienst des Königs standen, in allen Angelegenheiten der Abteilungen, welche Monat für Monat, alle Monate des Jahres hindurch, antraten und abtraten; eine jede Abteilung war 24000 Mann stark.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 2, 'An der Spitze der ersten Abteilung für den ersten Monat stand Jasobeam, der Sohn Sabdiels, und seine Abteilung belief sich auf 24000 Mann;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 3, 'er gehörte zu den Nachkommen des Perez und war das Oberhaupt aller Heerführer für den ersten Monat.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 4, 'An der Spitze der Abteilung für den zweiten Monat stand Eleasar, der Sohn Dodais, der Ahohiter, und von seiner Abteilung war Mikloth der Oberaufseher; seine Abteilung belief sich auf 24000.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 5, 'Der dritte Heerführer für den dritten Monat war Benaja, der Sohn des Priesters Jojada, als Oberhaupt; seine Abteilung belief sich auf 24000 Mann.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 6, 'Dieser Benaja war ein Held unter den Dreißig und war über die Dreißig gesetzt, und bei seiner Abteilung stand sein Sohn Ammisabad.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 7, 'Der vierte, für den vierten Monat, war Joabs Bruder Asahel und nach ihm sein Sohn Sebadja; seine Abteilung belief sich auf 24000.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 8, 'Der fünfte, für den fünften Monat, war der Fürst Samhuth, der Jisrahither; seine Abteilung belief sich auf 24000.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 9, 'Der sechste, für den sechsten Monat, war Ira, der Sohn des Ikkes, aus Thekoa; seine Abteilung belief sich auf 24000.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 10, 'Der siebte, für den siebten Monat, war Helez, der Pelonite, aus dem Stamme Ephraim; seine Abteilung belief sich auf 24000.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 11, 'Der achte, für den achten Monat, war Sibbechai, der Hussathiter, aus den Serahiten; seine Abteilung belief sich auf 24000.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 12, 'Der neunte, für den neunten Monat, war Abieser aus Anathoth, aus dem Stamme Benjamin; seine Abteilung belief sich auf 24000.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 13, 'Der zehnte, für den zehnten Monat, war Maharai, von Netopha, aus den Serahiten; seine Abteilung belief sich auf 24000.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 14, 'Der elfte, für den elften Monat, war Benaja aus Pirathon, aus dem Stamme Ephraim; seine Abteilung belief sich auf 24000.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 15, 'Der zwölfte, für den zwölften Monat, war Heldai aus Netopha, aus dem Geschlecht Othniels; seine Abteilung belief sich auf 24000.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 16, 'An der Spitze der Stämme Israels standen: von den Rubeniten als Fürst Elieser, der Sohn Sichris; von den Simeoniten Sephatja, der Sohn Maachas;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 17, 'von Levi Hasabja, der Sohn Kemuels; von Aaron Zadok;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 18, 'von Juda Elihu, einer der Brüder Davids; von Issaschar Omri, der Sohn Michaels;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 19, 'von Sebulon Jismaja, der Sohn Obadjas; von Naphthali Jerimoth, der Sohn Asriels;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 20, 'von den Ephraimiten Hosea, der Sohn Asasjas; vom halben Stamm Manasse Joel, der Sohn Pedajas;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 21, 'vom anderen halben Stamm Manasse in Gilead Iddo, der Sohn Sacharjas; von Benjamin Jaasiel, der Sohn Abners;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 22, 'von Dan Asareel, der Sohn Jerohams. Dies waren die Fürsten der israelitischen Stämme.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 23, 'David hatte aber die Zählung der Israeliten von zwanzig Jahren an und darunter nicht vornehmen lassen, weil der HERR verheißen hatte, er wolle Israel so zahlreich machen wie die Sterne am Himmel.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 24, 'Joab, der Sohn der Zeruja, hatte zwar die Zählung begonnen, sie aber nicht zu Ende geführt; es war nämlich um ihretwillen ein Zorngericht über Israel ergangen; daher ist die Zahl nicht unter die Zahlen in der Zeitgeschichte des Königs David aufgenommen worden.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 25, 'Und über die Schätze des Königs war Osmaweth, der Sohn Adiels, bestellt und als Rentmeister für die Besitzungen an Grundstücken in den Städten, Dörfern und Burgen Jonathan, der Sohn Ussias.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 26, 'Über die Feldarbeiter, die das Land zu bebauen hatten, war Esri, der Sohn Chelubs, gesetzt;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 27, 'über die Weinberge Simei aus Rama; über die Weinvorräte in den Weinkellern Sabdi, der Siphmite;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 28, 'über die Olivengärten und die Maulbeerfeigenbäume in der Niederung Baal-Hanan aus Gader; über die Ölvorräte Joas;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 29, 'über die Rinder, die in der Saron-Ebene weideten, Sitrai, der Saronite; über die Rinder in den Tälern Saphat, der Sohn Adlais;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 30, 'über die Kamele Obil, der Ismaelite; über die Eselinnen Jehdeja, der Meronothite;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 31, 'über das Kleinvieh Jasis, der Hagrite. Diese alle waren Verwalter des Vermögens, das der König David besaß.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 32, 'Jonathan, Davids Oheim, war Rat, ein einsichtiger und gelehrter Mann; Jehiel, der Sohn Hachmonis, war Erzieher der Söhne des Königs.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 33, 'Ahithophel war königlicher Rat, und Husai, der Arkiter, der Vertraute des Königs.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 34, 'Nach Ahithophel war es Jojada, der Sohn Benajas, und Abjathar; Joab aber war der Feldhauptmann des Königs.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 28, 1, 'David berief zu einer Versammlung nach Jerusalem alle höchststehenden Männer der Israeliten, nämlich die Stammesfürsten, die Obersten der Abteilungen, die im Dienst des Königs standen, die Befehlshaber der Tausendschaften und der Hundertschaften, die Verwalter der liegenden und beweglichen Güter des Königs und seiner Söhne, samt den Kämmerern und den Rittern und allen übrigen hervorragenden Männern.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 28, 2, 'Da erhob sich der König David (inmitten der Versammlung) von seinem Sitz und hielt folgende Ansprache: »Hört mich an, meine Brüder und mein Volk! Ich hatte selbst die Absicht, für die Lade mit dem Bundesgesetz des HERRN und für den Schemel der Füße unsers Gottes eine Unterkunftsstätte zu erbauen, und hatte schon Vorbereitungen für den Bau getroffen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 28, 3, 'Aber da sprach Gott zu mir: ›Du sollst meinem Namen kein Haus bauen; denn du bist ein Kriegsmann und hast Blut vergossen.‹');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 28, 4, 'Nun hat aber der HERR, der Gott Israels, mich aus dem ganzen Hause meines Vaters erwählt, daß ich König für immer über Israel sein soll; denn Juda hat er zum Fürsten ausersehen und im Stamme Juda das Haus meines Vaters; und unter den Söhnen meines Vaters bin ich es, an dem er Wohlgefallen gefunden, so daß er mich zum König über ganz Israel gemacht hat.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 28, 5, 'Von meinen sämtlichen Söhnen aber – der HERR hat mir ja viele Söhne geschenkt – hat er meinen Sohn Salomo dazu ersehen, auf dem Königsthrone des HERRN über Israel zu sitzen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 28, 6, 'Dabei hat er zu mir gesagt: ›Dein Sohn Salomo, der soll mein Haus und meine Vorhöfe bauen; denn ihn habe ich mir zum Sohn erwählt, und ich will ihm ein Vater sein;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 28, 7, 'und ich will sein Königtum für immer fest gründen, wenn er so, wie es heute der Fall ist, daran festhält, meine Gebote und Weisungen zu beobachten.‹');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 28, 8, 'Und nun – vor den Augen von ganz Israel, der Gemeinde des HERRN, und vor den Ohren unseres Gottes ermahne ich euch: Beobachtet gewissenhaft alle Gebote des HERRN, eures Gottes, damit ihr im Besitz dieses schönen Landes bleibt und es später euren Nachkommen als Erbe auf ewig hinterlaßt!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 28, 9, '»Du aber, mein Sohn Salomo, erkenne den Gott deines Vaters und diene ihm mit ungeteiltem Herzen und mit willigem Geiste; denn der HERR erforscht alle Herzen und weiß um jeden geheimen Gedanken; wenn du ihn suchst, wird er sich von dir finden lassen, wenn du ihn aber verläßt, wird er dich für immer verwerfen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 28, 10, 'So sieh nun wohl zu! Denn der HERR hat dich dazu ersehen, ihm ein Haus zum Heiligtum zu erbauen: mache dich mutig ans Werk!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 28, 11, 'Hierauf übergab David seinem Sohne Salomo das Modell der Vorhalle und des Tempelhauses, der Schatzkammern, Obergemächer und inneren Räume sowie des Raumes für die Sühnung;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 28, 12, 'dazu den Plan von allem, was seinem Geiste vorschwebte: hinsichtlich der Vorhöfe des Tempelhauses des HERRN und der ringsum laufenden Zellen sowie hinsichtlich der Vorratskammern des Gotteshauses und der Schatzkammern für die geweihten Gegenstände;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 28, 13, 'ferner (die Verordnungen) in betreff der Abteilungen der Priester und der Leviten sowie in betreff der ganzen Gestaltung der Dienstleistungen im Tempel des HERRN und bezüglich aller für den Tempeldienst erforderlichen Gerätschaften;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 28, 14, 'hinsichtlich des Goldes – nach dem Gewicht des Goldes für jedes einzelne gottesdienstliche Gerät; desgleichen hinsichtlich aller silbernen Geräte – nach dem Gewicht für jedes einzelne gottesdienstliche Gerät;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 28, 15, 'ebenso auch das Gewicht für die goldenen Leuchter und die zugehörigen goldenen Lampen – nach dem Gewicht eines jeden einzelnen Leuchters und der zugehörigen Lampen; auch für die silbernen Leuchter – nach dem Gewicht für jeden einzelnen Leuchter und die zugehörigen Lampen, wie es die Bestimmung jedes einzelnen Leuchters erforderte;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 28, 16, 'ferner das Gold nach dem Gewicht für die Schaubrottische, für jeden einzelnen Tisch, und das Silber für die silbernen Tische;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 28, 17, 'und für die Gabeln, Sprengschalen und Kannen – gediegenes Gold; ferner für die goldenen Krüge – nach dem Gewicht für jeden einzelnen Krug sowie für die silbernen Krüge – nach dem Gewicht für jeden einzelnen Krug;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 28, 18, 'ferner für den Räucheraltar – geläutertes Gold nach dem bestimmten Gewicht; auch das Modell des Wagens, nämlich der goldenen Cherube, die mit ausgebreiteten Flügeln die Bundeslade des HERRN überdecken sollten.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 28, 19, '»Über dies alles«, sagte David, »hat er mir Anweisung durch eine von der Hand des HERRN stammende Schrift gegeben, über alle zur Ausführung des Bauplanes erforderlichen Arbeiten.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 28, 20, 'Dann richtete David an seinen Sohn Salomo folgende Worte: »Sei stark und mutig und gehe ans Werk! Fürchte dich nicht und sei unverzagt! Denn Gott der HERR, mein Gott, wird mit dir sein: er wird dich nicht versäumen und dich nicht verlassen, bis alle Arbeiten für den Dienst am Hause des HERRN vollendet sind.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 28, 21, 'Schon sind hier die Abteilungen der Priester und der Leviten für den gesamten Dienst am Hause Gottes bereit, und zur Verfügung stehen dir für die Ausführung des ganzen Werkes Männer, die zu allen Verrichtungen willig und geschickt sind, dazu auch die Fürsten und das ganze Volk für alle deine Anordnungen.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 29, 1, 'Hierauf redete der König David die ganze Versammlung folgendermaßen an: »Mein Sohn Salomo, [der einzige,] den Gott erwählt hat, ist noch jung und zart, das Werk aber gewaltig; denn nicht für einen Menschen ist dieser Prachtbau bestimmt, sondern für Gott den HERRN.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 29, 2, 'Daher habe ich mit allen mir zu Gebote stehenden Kräften für das Haus meines Gottes Gold zu den goldenen, Silber zu den silbernen, Kupfer zu den kupfernen, Eisen zu den eisernen und Holz zu den hölzernen Geräten beschafft, außerdem Onyxsteine und Edelsteine zu Einfassungen, Steine zu Verzierungen, buntfarbige und kostbare Steine jeder Art und Marmorgestein in Menge.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 29, 3, 'Überdies will ich infolge meines Eifers für das Haus meines Gottes das, was ich als eigenes Gut an Gold und Silber besitze, für das Haus meines Gottes hingeben, zu allem dem noch hinzu, was ich bereits für das heilige Haus beschafft habe,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 29, 4, 'nämlich 3000 Talente Gold, Ophirgold, und 7000 Talente geläutertes Silber, um die Wände der heiligen Räume damit zu überziehen');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 29, 5, 'und für alle sonstigen Arbeiten, zu denen die Künstler Gold und Silber gebrauchen. Wer ist nun bereit, heute gleichfalls für den HERRN eine Gabe von seinem Vermögen beizusteuern?«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 29, 6, 'Da bewiesen die Familienhäupter und die Fürsten der Stämme Israels sowie die Befehlshaber der Tausendschaften und der Hundertschaften und die obersten Beamten im Dienst des Königs ihre Bereitwilligkeit');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 29, 7, 'und spendeten für den Bau des Gotteshauses 5000 Talente Gold und 10000 Goldstücke, 10000 Talente Silber, 18000 Talente Kupfer und 100000 Talente Eisen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 29, 8, 'Wer ferner Edelsteine besaß, gab sie für den Schatz des Hauses des HERRN an den Gersoniten Jehiel ab.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 29, 9, 'Da freute sich das Volk über ihre Freigebigkeit; denn mit ungeteiltem Herzen hatten sie freiwillig für den HERRN beigesteuert; auch der König David war hoch erfreut.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 29, 10, 'Da pries David den HERRN vor der ganzen Versammlung mit den Worten: »Gepriesen seist du, HERR, du Gott unsers Vaters Israel, von Ewigkeit zu Ewigkeit!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 29, 11, 'Dein, o HERR, ist die Hoheit und die Macht, die Herrlichkeit, der Ruhm und die Majestät; denn dein ist alles im Himmel und auf Erden. Dein, o HERR, ist die Herrschaft, und du bist als Haupt über alles erhaben.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 29, 12, 'Reichtum und Ehre kommen von dir, und du bist Herrscher über alles; in deiner Hand liegen Kraft und Stärke, und in deiner Hand steht es, jedermann groß und stark zu machen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 29, 13, 'Nun denn, unser Gott: wir danken dir und rühmen deinen herrlichen Namen;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 29, 14, 'denn wer bin ich, und was ist mein Volk, daß wir imstande sein sollten, freiwillige Gaben in solcher Weise darzubringen? Nein, von dir kommt dies alles, und aus deiner Hand haben wir dir gespendet.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 29, 15, 'Wir sind ja nur Gäste und Fremdlinge vor dir wie alle unsere Väter; wie ein Schatten sind unsere Lebenstage auf Erden und ohne Hoffnung, (hienieden zu bleiben).');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 29, 16, 'HERR, unser Gott, dieser ganze Reichtum, den wir bereitgestellt haben, um dir ein Haus für deinen heiligen Namen zu bauen, – aus deiner Hand kommt er, und dein ist das alles!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 29, 17, 'Ich weiß aber, mein Gott, daß du das Herz prüfst und an Aufrichtigkeit Wohlgefallen hast; – nun, ich habe dies alles mit aufrichtigem Herzen freiwillig gespendet und habe jetzt mit Freuden gesehen, daß auch dein Volk, das hier versammelt ist, dir bereitwillig Gaben dargebracht hat.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 29, 18, 'HERR, du Gott unserer Väter Abraham, Isaak und Israel, erhalte solche Gesinnung und Denkweise immerdar im Herzen deines Volkes und richte ihr Herz auf dich hin!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 29, 19, 'Meinem Sohne Salomo aber verleihe ein ungeteiltes Herz, daß er deine Gebote, deine Verordnungen und Weisungen beobachte und alles tue, um den Prachtbau aufzuführen, den ich vorbereitet habe!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 29, 20, 'Als David hierauf die ganze Versammlung aufforderte, den HERRN, ihren Gott, zu preisen, da priesen alle Versammelten den HERRN, den Gott ihrer Väter, verneigten sich und warfen sich vor dem HERRN und vor dem Könige nieder.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 29, 21, 'Am folgenden Tage aber opferten sie dem HERRN Schlachtopfer und brachten dem HERRN Brandopfer dar, nämlich tausend Stiere, tausend Widder und tausend Lämmer nebst den zugehörigen Trankspenden, außerdem Schlachtopfer in Menge für ganz Israel.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 29, 22, 'Dann aßen und tranken sie an jenem Tage vor dem HERRN voller Freude und machten Salomo, Davids Sohn, zum zweitenmal zum König und salbten ihn vor dem HERRN zum Fürsten und salbten Zadok zum Priester.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 29, 23, 'So saß denn Salomo auf dem Throne des HERRN als König an Stelle seines Vaters David und hatte das Glück, daß ganz Israel ihn anerkannte');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 29, 24, 'und alle Fürsten und die Ritter sowie alle Söhne des Königs David sich dem König Salomo unterwarfen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 29, 25, 'Der HERR aber ließ dann Salomo zu überhaus hohem Ansehen bei ganz Israel gelangen und verlieh seinem Königtum einen Glanz, wie ihn vor ihm kein König über Israel besessen hatte.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 29, 26, 'So hatte nun David, der Sohn Isais, über ganz Israel geherrscht,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 29, 27, 'und zwar betrug die Zeit seiner Regierung über Israel vierzig Jahre; in Hebron hatte er sieben Jahre geherrscht und in Jerusalem dreiunddreißig.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 29, 28, 'Er starb in hohem Alter, satt an Lebenstagen wie an Reichtum und Ehren, und sein Sohn Salomo folgte ihm in der Regierung nach.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 29, 29, 'Die Geschichte des Königs David aber findet sich bekanntlich von Anfang bis zu Ende aufgezeichnet in der Geschichte des Sehers Samuel sowie in der Geschichte des Propheten Nathan und in der Geschichte des Sehers Gad,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 29, 30, 'samt seiner ganzen machtvollen Regierung und seinen Siegen und den Schicksalen, die ihn und Israel und alle Reiche der Länder betroffen haben.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 1, 1, 'Als nun Salomo, der Sohn Davids, sich in seiner Herrschaft befestigt hatte – der HERR, sein Gott, war nämlich mit ihm und ließ ihn überaus mächtig werden –,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 1, 2, 'da ließ Salomo Befehl an ganz Israel ergehen, an die Befehlshaber der Tausendschaften und der Hundertschaften, an die Richter und alle Fürsten von ganz Israel, die Familienhäupter;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 1, 3, 'und dann begab sich Salomo mit der ganzen Volksgemeinde nach der Höhe bei Gibeon; denn dort befand sich das Offenbarungszelt Gottes, das Mose, der Knecht des HERRN, in der Wüste hergestellt hatte –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 1, 4, 'dagegen die Lade Gottes hatte David aus Kirjath-Jearim an den Platz hinaufgebracht, den David für sie hatte herrichten lassen; denn er hatte für sie in Jerusalem ein Zelt aufschlagen lassen –.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 1, 5, 'Auch der kupferne Altar, den Bezaleel, der Sohn Uris, des Sohnes Hurs, hergestellt hatte, stand dort (in Gibeon) vor der Wohnung des HERRN; und Salomo und die Volksgemeinde suchten ihn dort auf.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 1, 6, 'Salomo opferte dann dort vor dem HERRN auf dem kupfernen Altar, der zum Offenbarungszelt gehörte, und brachte tausend Brandopfer auf ihm dar.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 1, 7, 'In jener Nacht erschien Gott dem Salomo und sprach zu ihm: »Bitte, was ich dir geben soll!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 1, 8, 'Da antwortete Salomo dem HERRN: »Du hast meinem Vater David große Liebe erwiesen und hast mich zum König an seiner Statt gemacht.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 1, 9, 'So laß denn, HERR, mein Gott, deine Verheißung, die du meinem Vater David gegeben hast, in Erfüllung gehen! denn du hast mich zum König über ein Volk gemacht, das so zahlreich ist wie der Staub auf dem Erdboden.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 1, 10, 'So verleihe mir nun Weisheit und Einsicht, damit ich mich diesem Volk gegenüber in rechter Weise zu verhalten weiß; denn wer vermöchte sonst dieses dein großes Volk zu regieren?«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 1, 11, 'Darauf sagte Gott zu Salomo: »Weil du solche Gesinnung hegst und nicht um Reichtum, Schätze und Ehre oder um den Tod deiner Feinde, auch nicht um langes Leben gebeten, sondern dir Weisheit und Einsicht erbeten hast, um mein Volk, zu dessen König ich dich gemacht habe, regieren zu können:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 1, 12, 'so soll dir die (erbetene) Weisheit und Einsicht verliehen sein; aber auch Reichtum, Schätze und Ehre will ich dir schenken, wie keiner von den Königen vor dir sie besessen hat und wie sie keiner nach dir jemals besitzen wird.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 1, 13, 'Darauf kehrte Salomo von der Höhe bei Gibeon, von dem Platz vor dem Offenbarungszelt, nach Jerusalem zurück und herrschte über Israel.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 1, 14, 'Salomo brachte zahlreiche Kriegswagen und Reitpferde zusammen, so daß er 1400 Wagen und 12000 Reitpferde besaß, die er in den Wagenstädten oder in seiner Nähe zu Jerusalem unterbrachte.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 1, 15, 'Und der König brachte es dahin, daß es in Jerusalem so viel Silber und Gold gab wie Steine und daß die Zedernstämme den Maulbeerfeigenbäumen in der Niederung an Menge gleichkamen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 1, 16, 'Der Bezug der Pferde für Salomo erfolgte aus Ägypten, und zwar aus Koa; die Händler des Königs kauften sie nämlich dort in Koa auf,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 1, 17, 'so daß ein Wagen bei der Ausfuhr aus Ägypten auf sechshundert Schekel Silber zu stehen kam und ein Pferd auf einhundertundfünfzig. Ebenso wurden sie durch ihre Vermittlung an alle Könige der Hethiter und an die Könige von Syrien ausgeführt.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 1, 18, 'Darauf beschloß Salomo, dem Namen des HERRN einen Tempel und für sich selbst einen Königspalast zu bauen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 2, 1, 'So ließ er denn 70000 Lastträger und 80000 Steinhauer im Gebirge (Juda) und 3600 Aufseher über sie abzählen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 2, 2, 'Dann schickte Salomo eine Gesandtschaft an den König Huram von Tyrus und ließ ihm sagen: »Wie du es bei meinem Vater David gehalten hast, indem du ihm Zedern sandtest, damit er sich einen Palast zu seinem Wohnsitz erbauen könnte, so halte es auch mit mir!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 2, 3, 'Wisse wohl: ich bin im Begriff, dem Namen des HERRN, meines Gottes, ein Haus zu bauen und es ihm zu weihen, damit man wohlriechendes Räucherwerk vor ihm verbrennen und Schaubrote regelmäßig zurichten und Brandopfer an jedem Morgen und Abend, an den Sabbaten, sowie an den Neumonden und den (anderen) Festen des HERRN, unseres Gottes, darbringen kann, – das ist ja stehender Brauch in Israel.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 2, 4, 'Das Haus aber, das ich bauen will, muß groß sein; denn unser Gott ist größer als alle anderen Götter.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 2, 5, 'Freilich – wer vermöchte ihm ein Haus zu bauen, da doch der Himmel und aller Himmel Himmel ihn nicht fassen können? Und wer bin ich, daß ich ihm ein Haus bauen sollte? Es geschieht ja nur, um vor ihm (Opfer als) Räucherwerk zu verbrennen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 2, 6, 'So sende mir denn nun einen Mann, der sich auf Arbeiten in Gold und Silber, in Kupfer und Eisen, in rotem Purpur, karmesinfarbigen Stoffen und blauem Purpur versteht und geschickt ist, Steine zu schneiden, im Verein mit den Künstlern, die mir in Juda und Jerusalem zur Verfügung stehen und die mein Vater David schon beschafft hat.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 2, 7, 'Sende mir auch Zedernstämme, Zypressen und Sandelholz vom Libanon; denn ich weiß, daß deine Leute sich darauf verstehen, die Bäume auf dem Libanon zu fällen; dabei sollen dann meine Leute den deinen behilflich sein.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 2, 8, 'Es muß mir aber Holz in Menge beschafft werden; denn das Haus, das ich bauen will, soll von ungewöhnlicher Größe sein.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 2, 9, 'Ich bin übrigens bereit, für deine Leute, die Holzhauer, welche die Bäume fällen, zum Unterhalt 20000 Kor Weizen, 20000 Kor Gerste, 20000 Bath Wein und 20000 Bath Öl zu liefern.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 2, 10, 'Huram, der König von Tyrus, antwortete in einem Briefe, den er an Salomo sandte, folgendermaßen: »Weil der HERR sein Volk liebt, hat er dich zum König über sie gemacht.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 2, 11, 'Dann fuhr Huram fort: »Gepriesen sei der HERR, der Gott Israels, der den Himmel und die Erde geschaffen hat, daß er dem König David einen weisen Sohn geschenkt hat, der so klug und einsichtsvoll ist, daß er dem HERRN einen Tempel und sich selbst einen Königspalast erbauen will!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 2, 12, 'So sende ich dir denn einen kunstverständigen, einsichtsvollen Mann, nämlich Huram-Abi,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 2, 13, 'den Sohn einer Danitin, der aber einen Tyrer zum Vater hat. Er versteht sich auf Arbeiten in Gold und Silber, in Kupfer und Eisen, in Steinen und Holz, in rotem und blauem Purpur, in Byssus und karmesinfarbigen Stoffen; er kann auch Schnitzarbeit jeder Art und alle Kunstarbeiten, die ihm übertragen werden, im Verein mit deinen Künstlern und den Künstlern meines Herrn David, deines Vaters, ausführen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 2, 14, 'So möge denn mein Herr den Weizen und die Gerste, das Öl und den Wein seinen Knechten senden, wie mein Herr es versprochen hat;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 2, 15, 'wir aber wollen Bäume, soviele du überhaupt bedarfst, auf dem Libanon fällen und wollen sie dir als Flöße auf dem Meer nach Japho zuführen; du kannst sie dann von dort nach Jerusalem hinaufschaffen.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 2, 16, 'Nun ließ Salomo alle Fremdlinge, die sich im Lande Israel befanden, zählen nach der (früheren) Zählung, die sein Vater David mit ihnen vorgenommen hatte; da fanden sich deren 153600.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 2, 17, 'Von diesen machte er 70000 zu Lastträgern, 80000 zu Steinhauern im Gebirge (Juda) und 3600 zu Aufsehern, welche die Leute zur Arbeit anzuhalten hatten.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 3, 1, 'Hierauf begann Salomo den Tempel des HERRN in Jerusalem zu bauen auf dem Berge Morija, wo der HERR seinem Vater David erschienen war, auf dem Platze, den David dazu bestimmt hatte, nämlich auf der Tenne des Jebusiters Ornan;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 3, 2, 'und zwar begann er den Bau am zweiten (Tage) im zweiten Monat, im vierten Jahre seiner Regierung.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 3, 3, 'Folgendes sind aber die Grundmaße, an welche Salomo sich beim Bau des Hauses Gottes hielt: die Länge betrug sechzig Ellen nach dem alten Maß und die Breite zwanzig Ellen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 3, 4, 'Die Halle, die sich vor der Breitseite des Großraumes des Hauses befand, war 20 Ellen lang und 20 Ellen hoch; er ließ sie im Inneren mit reinem Golde überziehen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 3, 5, 'Den großen Tempelraum täfelte er mit Zypressenholz, überzog dieses sodann mit gediegenem Gold und brachte Palmen und Blumengewinde darauf an.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 3, 6, 'Weiter überzog er das Tempelhaus mit kostbaren Steinen zum Schmuck; das Gold aber war Parwaimgold.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 3, 7, 'Auch überkleidete er im Tempelhause die Balken (der Decke), die Schwellen, seine Wände und Türen mit Gold und ließ Cherube an den Wänden einschnitzen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 3, 8, 'Dann stellte er den Raum des Allerheiligsten her, dessen Länge entsprechend der Breite des Tempelhauses 20 Ellen betrug; die Breite war auch 20 Ellen, und er ließ es mit feinem Gold im Betrage von sechshundert Talenten überziehen;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 3, 9, 'das Gewicht der Nägel aber betrug fünfzig Schekel Gold. Auch die Obergemächer erhielten eine Bekleidung von Gold.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 3, 10, 'Sodann ließ er im Raum des Allerheiligsten zwei Cherube herstellen, ein Werk der Bildhauerkunst, und man überzog sie mit Gold.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 3, 11, 'Die Flügel der Cherube hatten eine Gesamtlänge von zwanzig Ellen; der fünf Ellen lange Flügel des einen Cherubs berührte die Wand des Raumes, während der andere, ebenfalls fünf Ellen lange Flügel an den Flügel des anderen Cherubs stieß.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 3, 12, 'Ebenso reichte der eine, fünf Ellen lange Flügel des zweiten Cherubs bis an die Wand des Raumes, während der andere, gleichfalls fünf Ellen lange Flügel an den Flügel des ersten Cherubs stieß,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 3, 13, 'so daß die Flügel dieser beiden Cherube ausgebreitet zwanzig Ellen maßen. Sie selbst aber standen aufrecht auf ihren Füßen, und ihre Gesichter waren dem Innenraum des Tempels zugewandt.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 3, 14, 'Weiter ließ er einen Vorhang von blauem und rotem Purpur, von karmesinfarbigem Stoff und Byssus herstellen und brachte Cherube darauf an.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 3, 15, 'Dann ließ er vor dem Tempelhause zwei Säulen herstellen; sie waren 35 Ellen lang, und der Knauf oben darauf maß 5 Ellen;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 3, 16, 'auch ließ er Kettenwerk für den unteren Saum der Knäufe anfertigen und es oben an den Säulen anbringen; an die Ketten aber tat er hundert kunstvoll gearbeitete Granatäpfel.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 3, 17, 'Die Säulen ließ er dann auf der Vorderseite des Tempels aufstellen, die eine rechts, die andere links; und die rechtsstehende nannte er Jachin, die linksstehende Boas.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 4, 1, 'Weiter ließ er einen kupfernen Altar von 20 Ellen Länge, 20 Ellen Breite und 10 Ellen Höhe herstellen. –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 4, 2, 'Auch fertigte er das aus Erz gegossene Meer an, das von einem Rande bis zum andern zehn Ellen maß, ringsum gerundet und fünf Ellen hoch; eine Schnur von dreißig Ellen war erforderlich, um es ganz zu umspannen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 4, 3, 'Unten an ihm waren Gebilde von wilden Gurken angebracht, die es rings umgaben, je zehn auf die Elle; sie bildeten einen Kranz um das Becken, zwei Reihen Gurken, die gleich bei seinem Guß mitgegossen worden waren.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 4, 4, 'Es ruhte auf zwölf Rindern, von denen drei nach Norden, drei nach Westen, drei nach Süden und drei nach Osten gewandt waren; das Becken aber lag oben auf ihnen, und die Hinterseite war bei allen Rindern nach innen gekehrt.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 4, 5, 'Die Dicke (der Wand) des Beckens betrug eine Handbreite, und sein Rand war wie ein Becherrand geformt, nach Art einer blühenden Lilie. An Inhalt faßte es dreitausend Bath.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 4, 6, 'Er ließ auch zehn Becken anfertigen und fünf von ihnen rechts und fünf links aufstellen, damit man Waschungen darin vornähme; man spülte in ihnen die Stücke ab, die zum Brandopfer gehörten; das große Wasserbecken dagegen diente den Priestern für ihre Waschungen. –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 4, 7, 'Weiter ließ er die goldenen Leuchter, zehn an der Zahl, so anfertigen, wie es der für sie geltenden Vorschrift entsprach, und stellte sie in den Tempel, fünf auf die rechte und fünf auf die linke Seite. –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 4, 8, 'Weiter ließ er zehn Tische anfertigen und stellte sie im Tempel auf, fünf auf der rechten und fünf auf der linken Seite; auch ließ er hundert goldene Sprengschalen anfertigen. –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 4, 9, 'Sodann stellte er den Vorhof der Priester und den großen Vorhof her und die Tore für den Vorhof; die dazugehörigen Torflügel überzog er mit Kupfer.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 4, 10, 'Das große Wasserbecken aber stellte er auf der Südseite (des Tempelhauses) nach Osten zu auf, an der Südostecke des Tempels.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 4, 11, 'Weiter fertigte Huram die Töpfe, die Schaufeln und die Sprengschalen an und vollendete so die Arbeiten, die er für den König Salomo im Gotteshause herzustellen hatte,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 4, 12, 'nämlich die zwei Säulen mit den beiden kugelförmigen Knäufen oben auf den Säulen; dazu die zwei Geflechte zur Bekleidung der beiden kugelförmigen Knäufe oben auf den Säulen;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 4, 13, 'ferner die vierhundert Granatäpfel für die beiden Flechtwerke; zwei Reihen Granatäpfel für jedes Flechtwerk [zur Bekleidung der beiden kugelförmigen Knäufe oben auf den Säulen].');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 4, 14, 'Auch fertigte er die (zehn) Gestühle nebst den (zehn) Kesseln auf den Gestühlen an');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 4, 15, 'sowie das eine große Wasserbecken mit den zwölf Rindern unter ihm;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 4, 16, 'auch die Töpfe, die Schaufeln und die Gabeln nebst allen anderen Geräten fertigte Huram-Abiw dem König Salomo für den Tempel des HERRN aus geglättetem Kupfer an.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 4, 17, 'In der Jordanaue hatte der König sie gießen lassen an der Furt von Adama, zwischen Sukkoth und Zereda.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 4, 18, 'Salomo ließ aber alle diese Geräte in sehr großer Anzahl herstellen; denn das Gewicht des Erzes wurde nicht festgestellt.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 4, 19, 'Weiter ließ Salomo alle die (Gold-) Geräte anfertigen, die zum Hause Gottes gehörten, nämlich den vergoldeten Altar und die Tische, auf denen die Schaubrote lagen;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 4, 20, 'weiter die Leuchter samt den zugehörigen Lampen, damit sie vorschriftsmäßig vor dem Allerheiligsten angezündet würden, aus gediegenem Golde,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 4, 21, 'dazu die Blüten und die Lampen und Lichtscheren aus Gold, und zwar aus lauterem Gold;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 4, 22, 'weiter die Messer, Sprengschalen, Schüsseln und Räucherpfannen aus gediegenem Gold. Was schließlich die Türen des Tempels betrifft, so waren die inneren Türflügel am Eingang zum Allerheiligsten sowie die Flügeltüren des Tempelhauses, die in den großen Raum führten, von Gold.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 5, 1, 'Als nun alle Arbeiten, die Salomo für den Tempel des HERRN hatte herstellen lassen, fertig waren, ließ Salomo die Weihgeschenke seines Vaters David hineinbringen und legte das Silber, das Gold und sämtliche Geräte in den Schatzkammern des Gotteshauses nieder.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 5, 2, 'Damals ließ Salomo die Ältesten der Israeliten und alle Häupter der Stämme, die Fürsten der israelitischen Geschlechter, in Jerusalem zusammenkommen, um die Bundeslade des HERRN aus der Davidsstadt, das ist Zion, hinaufzubringen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 5, 3, 'So versammelten sich denn alle Israeliten beim König zum Fest, nämlich im Monat Ethanim, das ist der siebte Monat.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 5, 4, 'Als nun alle Ältesten der Israeliten sich eingefunden hatten, hoben die Leviten die Lade auf');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 5, 5, 'und trugen sie hinauf, ebenso das Offenbarungszelt samt allen heiligen Geräten, die sich im Zelt befanden: die levitischen Priester trugen sie hinauf.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 5, 6, 'Der König Salomo aber und die ganze Volksgemeinde Israel, die bei ihm versammelt war, standen vor der Lade und opferten so viele Stück Kleinvieh und Rinder, daß ihre Menge geradezu unzählbar war.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 5, 7, 'Alsdann brachten die Priester die Lade mit dem Bundesgesetz des HERRN an den für sie bestimmten Platz, nämlich in den Hinterraum des Tempelhauses, in das Allerheiligste, unter die Flügel der Cherube;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 5, 8, 'die Cherube hielten nämlich die Flügel ausgebreitet über den Platz, wo die Lade stand, so daß die Cherube eine Decke oben über der Lade und deren Tragstangen bildeten.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 5, 9, 'Die Tragstangen aber waren so lang, daß die Spitzen der Stangen im Heiligtum an der Vorderseite des Allerheiligsten sichtbar waren; weiter draußen aber waren sie nicht zu sehen; und sie sind dort geblieben bis auf den heutigen Tag.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 5, 10, 'In der Lade befand sich nichts als nur die beiden Tafeln, die Mose am Horeb hineingelegt hatte, als der HERR mit den Israeliten nach ihrem Auszug aus Ägypten einen Bund schloß.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 5, 11, 'Als aber die Priester aus dem Heiligtum hinaustraten – alle Priester nämlich, die zugegen waren, hatten sich geheiligt, ohne daß man Rücksicht auf die (Reihenfolge der) Abteilungen genommen hatte,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 5, 12, 'und die levitischen Sänger standen insgesamt, nämlich Asaph, Heman, Jeduthun nebst ihren Söhnen und Amtsgenossen, in Byssus gekleidet, mit Zimbeln, Harfen und Zithern auf der Ostseite des Altars und bei ihnen an hundertundzwanzig Priester, die auf Trompeten bliesen;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 5, 13, 'es hatten aber die Trompeter und die Sänger wie ein Mann mit einer Stimme einzusetzen, um dem HERRN Lobpreis und Dank darzubringen –, sobald sich also der Schall der Trompeten und Zimbeln und der übrigen Musikinstrumente erhob und man das Loblied auf den HERRN anstimmte: »Denn er ist gütig, und seine Gnade währet ewiglich«: da wurde das Haus, der Tempel des HERRN, von einer Wolke erfüllt,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 5, 14, 'so daß die Priester wegen der Wolke nicht hintreten konnten, um ihren Dienst zu versehen; denn die Herrlichkeit des HERRN erfüllte das Gotteshaus.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 1, 'Damals sprach Salomo: »Der HERR hat erklärt, er wolle im Dunkel wohnen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 2, 'Ich aber habe dir ein Haus zur Wohnung gebaut, eine Stätte zum Wohnsitz für dich auf ewige Zeiten!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 3, 'Hierauf wandte der König sich um und sprach einen Segensspruch über die ganze Volksgemeinde Israel, wobei die ganze Gemeinde Israel stand.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 4, 'Dann sprach er: »Gepriesen sei der HERR, der Gott Israels, der die Verheißung, die er meinem Vater David mündlich gegeben, nun tatsächlich erfüllt hat, da er sagte:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 5, '›Seit der Zeit, da ich mein Volk (Israel) aus Ägypten hinausgeführt, habe ich aus allen Stämmen Israels nie eine Stadt dazu erwählt, daß mir daselbst ein Haus gebaut würde, an dem mein Name haften sollte; und ich habe auch niemand dazu erwählt, daß er Fürst über mein Volk Israel sein sollte.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 6, 'Dann aber habe ich Jerusalem erwählt, daß mein Name daselbst wohne, und ich habe David dazu ersehen, Herrscher über mein Volk Israel zu sein.‹');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 7, 'Nun hegte zwar mein Vater David den Wunsch, dem Namen des HERRN, des Gottes Israels, ein Haus zu bauen;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 8, 'aber der HERR ließ meinem Vater David verkünden: ›Daß du den Wunsch gehegt hast, meinem Namen ein Haus zu bauen, daran hast du wohlgetan;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 9, 'jedoch nicht du sollst das Haus bauen, sondern dein leiblicher Sohn, der dir geboren werden wird, der soll meinem Namen das Haus bauen.‹');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 10, 'Nun hat der HERR die Verheißung, die er gegeben, in Erfüllung gehen lassen; denn ich bin an die Stelle meines Vaters David getreten und habe den Thron Israels bestiegen, wie der HERR es verheißen hat, und ich habe dem Namen des HERRN, des Gottes Israels, den Tempel erbaut');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 11, 'und habe daselbst die Lade aufgestellt, in der sich die Urkunde des Bundes befindet, den der HERR mit den Israeliten geschlossen hat.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 12, 'Hierauf trat er angesichts der ganzen Gemeinde Israels vor den Altar des HERRN und breitete seine Hände aus –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 13, 'Salomo hatte nämlich eine Kanzel von Kupfer anfertigen und sie mitten auf dem Tempelhofe aufstellen lassen; sie war fünf Ellen lang, fünf Ellen breit und drei Ellen hoch; auf diese trat er nun, ließ sich angesichts der ganzen Versammlung der Israeliten auf seine Knie nieder, breitete seine Hände gen Himmel aus');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 14, 'und betete: »HERR, du Gott Israels! Kein Gott weder im Himmel noch auf der Erde ist dir gleich, der du den Bund und die Gnade deinen Knechten bewahrst, die mit ganzem Herzen vor dir wandeln.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 15, 'Du hast deinem Knechte David, meinem Vater, gehalten, was du ihm verheißen hattest; ja, was du mündlich zugesagt hattest, das hast du tatsächlich erfüllt, wie es heute sichtbar zu Tage liegt!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 16, 'Und nun, o HERR, Gott Israels! Halte deinem Knechte David, meinem Vater, die Verheißung, die du ihm gegeben hast mit den Worten: ›Es soll dir nie an einem (Nachkommen) fehlen, der vor meinem Angesicht auf dem Throne Israels sitze, wofern nur deine Nachkommen auf ihren Weg achthaben, daß sie nach meinem Gesetz wandeln, wie du vor mir gewandelt bist.‹');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 17, 'Nun also, o HERR, Gott Israels: laß deine Verheißung, die du deinem Knechte David gegeben hast, in Erfüllung gehen!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 18, 'Wie aber? Sollte Gott wirklich bei den Menschen auf der Erde Wohnung nehmen? Siehe, der Himmel und aller Himmel Himmel können dich nicht fassen: wieviel weniger dieses Haus, das ich gebaut habe!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 19, 'Und doch wende dich zu dem Gebet deines Knechtes und zu seinem Flehen, o HERR, mein Gott, daß du hörst auf das Rufen und das Gebet, das dein Knecht an dich richtet!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 20, 'Laß deine Augen bei Tag und bei Nacht offen stehen über diesem Hause, über der Stätte, von der du verheißen hast, du wollest deinen Namen daselbst wohnen lassen, daß du das Gebet erhörst, welches dein Knecht an dieser Stätte verrichten wird!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 21, 'So erhöre denn das Flehen deines Knechtes und deines Volkes Israel, sooft sie an dieser Stätte beten werden! Erhöre du es von der Stätte, wo du thronst, vom Himmel her, und wenn du es hörst, so vergib!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 22, 'Wenn sich jemand gegen seinen Nächsten vergeht und man ihm einen Eid auferlegt, den er schwören soll, und er kommt und schwört vor deinem Altar in diesem Hause:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 23, 'so wollest du es vom Himmel her hören und eingreifen und deinen Knechten Recht schaffen, indem du dem Schuldigen dadurch vergiltst, daß du sein Tun auf sein Haupt zurückfallen läßt, dem Unschuldigen aber dadurch zu seinem Recht verhilfst, daß du ihm zuteil werden läßt nach seiner Gerechtigkeit!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 24, 'Und wenn dein Volk Israel vom Feinde geschlagen wird, weil es sich an dir versündigt hat, sich dann aber bekehrt und deinen Namen bekennt und in diesem Hause zu dir betet und fleht:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 25, 'so wollest du es vom Himmel her hören und deinem Volke Israel die Sünde vergeben und sie in das Land zurückbringen, das du ihnen und ihren Vätern gegeben hast!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 26, 'Wenn der Himmel verschlossen bleibt und kein Regen fällt, weil sie sich an dir versündigt haben, und sie dann an dieser Stätte beten und deinen Namen bekennen und sich von ihrer Sünde abkehren, weil du sie demütigst:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 27, 'so wollest du es im Himmel hören und deinen Knechten und deinem Volke Israel die Sünde vergeben, indem du ihnen den rechten Weg weisest, auf dem sie wandeln sollen, und wollest Regen fallen lassen auf dein Land, das du deinem Volk zum Erbbesitz gegeben hast!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 28, 'Wenn eine Hungersnot im Lande herrscht, wenn die Pest ausbricht, wenn Getreidebrand oder Vergilben des Getreides, Heuschrecken oder Ungeziefer über das Land kommen, wenn seine Feinde es in einer seiner Ortschaften bedrängen oder sonst irgendeine Plage oder irgendeine Krankheit sie heimsucht:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 29, 'was man alsdann erbittet und erfleht, es geschehe von einem einzelnen Menschen oder von deinem ganzen Volke Israel, wenn ein jeder sich in seinem Gewissen getroffen und von Reue ergriffen fühlt und er seine Hände nach diesem Hause hin ausstreckt:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 30, 'so wollest du es vom Himmel her hören an der Stätte, wo du thronst, und wollest Verzeihung gewähren und einem jeden ganz nach Verdienst vergelten, wie du sein Herz kennst – denn du allein kennst das Herz der Menschenkinder –,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 31, 'damit sie dich fürchten und allezeit auf deinen Wegen wandeln, solange sie in dem Lande leben, das du unsern Vätern gegeben hast!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 32, 'Aber auch den Fremdling, der nicht zu deinem Volke Israel gehört, sondern aus fernem Lande um deines großen Namens willen und wegen deiner starken Hand und deines hocherhobenen Armes hergekommen ist und vor diesem Tempel betet,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 33, 'wollest du vom Himmel her erhören, von der Stätte her, wo du thronst, und alles das tun, um was der Fremdling dich anruft, auf daß alle Völker der Erde deinen Namen kennen lernen und damit sie dich ebenso fürchten wie dein Volk Israel und damit sie inne werden, daß dieses Haus, welches ich erbaut habe, nach deinem Namen genannt ist!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 34, 'Wenn dein Volk gegen seine Feinde in den Krieg zieht auf dem Wege, den du sie senden wirst, und sie sich im Gebet zu dir nach dieser Stadt hin wenden, die du erwählt hast, und nach dem Tempel hin, den ich zu Ehren deines Namens erbaut habe:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 35, 'so wollest du ihr Gebet und Flehen vom Himmel her hören und ihnen zu ihrem Recht verhelfen!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 36, 'Wenn sie sich an dir versündigt haben – es gibt ja keinen Menschen, der nicht sündigt – und du ihnen zürnst und sie dem Feinde preisgibst, so daß ihre Besieger sie gefangen in ein fernes oder in ein nahes Land wegführen,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 37, 'und sie dann in dem Lande, wohin sie in die Gefangenschaft geführt sind, in sich gehen und sich bekehren und dich im Lande ihrer Gefangenschaft mit dem Bekenntnis anrufen: ›Wir haben gesündigt, wir haben uns vergangen und gottlos gehandelt!‹,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 38, 'wenn sie sich also in dem Lande ihrer Gefangenschaft, wohin man sie geschleppt hat, mit ganzem Herzen und mit ganzer Seele dir wieder zuwenden und zu dir beten in der Richtung nach ihrem Lande hin, das du ihren Vätern gegeben hast, und nach der Stadt hin, die du erwählt hast, und nach dem Tempel hin, den ich zu Ehren deines Namens erbaut habe:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 39, 'so wollest du ihr Gebet und Flehen vom Himmel her, von der Stätte, wo du thronst, erhören und ihnen zu ihrem Recht verhelfen und wollest deinem Volke vergeben, was sie gegen dich gesündigt haben!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 40, 'Nun denn, mein Gott, laß doch deine Augen offenstehen und deine Ohren aufmerken auf das Gebet an dieser Stätte!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 41, 'Und nun, mache dich auf, HERR, mein Gott, zu deiner Ruhestätte, du selbst und deine machtvolle Lade! Laß deine Priester, HERR, mein Gott, in Heil sich kleiden und deine Frommen sich freuen des Glücks!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 42, 'O HERR, mein Gott, weise deinen Gesalbten nicht ab! Gedenke der Gnadenerweise, die du deinem Knechte David verheißen hast!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 7, 1, 'Als dann Salomo mit seinem Gebet zu Ende war, fuhr Feuer vom Himmel herab und verzehrte das Brandopfer und die Schlachtopfer, und die Herrlichkeit des HERRN erfüllte das Tempelhaus,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 7, 2, 'so daß die Priester nicht in den Tempel des HERRN hineingehen konnten, weil die Herrlichkeit des HERRN den Tempel des HERRN erfüllte.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 7, 3, 'Als nun alle Israeliten das Feuer herabfahren und die Herrlichkeit des HERRN über dem Tempel ausgebreitet sahen, knieten sie, das Angesicht zur Erde geneigt, auf das Steinpflaster nieder, vollzogen die Anbetung und priesen den HERRN, daß er gütig sei und daß seine Gnade ewig währe.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 7, 4, 'Hierauf brachten der König und das ganze Volk Schlachtopfer vor dem HERRN dar,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 7, 5, 'und zwar ließ Salomo als Schlachtopfer 22000 Rinder und 120000 Stück Kleinvieh schlachten: damit weihten der König und das ganze Volk den Tempel Gottes ein,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 7, 6, 'während die Priester ihres Amtes warteten und (ebenso) die Leviten mit den gottesdienstlichen Musikinstrumenten, die der König David hatte anfertigen lassen, den Lobgesang auf den HERRN vortrugen, daß seine Güte ewig währe, und die Priester ihnen gegenüber in die Trompeten stießen, während alle Israeliten dabeistanden. –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 7, 7, 'Damals weihte Salomo den mittleren Teil des Vorhofes, der vor dem Tempelhause des HERRN lag, zur Opferstätte; denn dort brachte er die Brandopfer und die Fettstücke der Heilsopfer dar, weil der kupferne Altar, den Salomo hatte herstellen lassen, die Brand- und Speiseopfer und die Fettstücke (der Heilsopfer) nicht fassen konnte.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 7, 8, 'Auf diese Weise beging Salomo damals das Fest sieben Tage lang und ganz Israel mit ihm, eine gewaltige Festgemeinde, die zusammengekommen war von der Gegend bei Hamath an bis an den Bach Ägyptens.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 7, 9, 'Am achten Tage aber hielten sie eine Festversammlung; denn die Einweihung des Altars hatte man sieben Tage lang gefeiert, und das Fest dauerte auch sieben Tage.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 7, 10, 'Am dreiundzwanzigsten Tage des siebten Monats aber entließ Salomo das Volk in ihre Heimat, fröhlich und wohlgemut wegen der Wohltaten, mit denen der HERR (seinen Knecht) David und Salomo und sein Volk Israel gesegnet hatte.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 7, 11, 'Als nun Salomo den Tempel des HERRN und den königlichen Palast vollendet und alles, was er im Tempel des HERRN und in seinem Palast hatte schaffen wollen, glücklich ausgeführt hatte,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 7, 12, 'da erschien der HERR dem Salomo nachts im Traume und sagte zu ihm: »Ich habe dein Gebet gehört und diesen Ort mir zur Opferstätte erkoren.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 7, 13, 'Wenn ich den Himmel verschließe, so daß kein Regen fällt, oder wenn ich den Heuschrecken gebiete, das Land abzufressen, oder wenn ich die Pest unter mein Volk sende');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 7, 14, 'und mein Volk, das nach meinem Namen genannt ist, sich dann demütigt und (zu mir) betet und mein Angesicht sucht und sich von seinem bösen Tun bekehrt: so will ich sie vom Himmel her erhören und ihnen ihre Sünden vergeben und ihrem Lande Rettung schaffen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 7, 15, 'Fortan sollen also meine Augen offenstehen und meine Ohren aufmerken auf die Gebete an dieser Stätte.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 7, 16, 'Und nunmehr habe ich dieses Haus erwählt und zu meinem Heiligtum gemacht, damit mein Name daselbst in Ewigkeit wohnt und meine Augen und mein Herz daselbst immerdar weilen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 7, 17, 'Wenn du nun vor mir ebenso wandelst, wie dein Vater David es getan hat, so daß du alles tust, was ich dir geboten habe, und meine Satzungen und Rechte beobachtest,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 7, 18, 'so will ich den Thron deines Königtums feststellen, wie ich es deinem Vater David feierlich zugesagt habe mit den Worten: ›Es soll dir nie an einem (Nachkommen) fehlen, der über Israel herrsche.‹');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 7, 19, 'Wenn ihr aber von mir abfallt und meine Satzungen und Gebote, die ich euch zur Pflicht gemacht habe, verlaßt und anderen Göttern zu dienen und sie anzubeten anfangt,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 7, 20, 'so werde ich die Israeliten aus meinem Lande, das ich ihnen gegeben habe, hinwegreißen und dieses Haus, das ich meinem Namen geheiligt habe, keines Blickes mehr würdigen und werde es für alle Völker zum Gegenstand des Hohnes und Spottes machen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 7, 21, 'Und so erhaben dieser Tempel auch gewesen sein mag, so sollen doch alle, die an ihm vorübergehen, sich entsetzen; und wenn sie fragen: ›Warum hat der HERR diesem Lande und diesem Hause solches Geschick widerfahren lassen?‹,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 7, 22, 'so wird man antworten: ›Zur Strafe dafür, daß sie den HERRN, den Gott ihrer Väter, der sie aus dem Lande Ägypten hinausgeführt hatte, verlassen und sich anderen Göttern zugewandt und sie angebetet und ihnen gedient haben: darum hat er all dieses Unglück über sie kommen lassen!‹«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 8, 1, 'Nach Ablauf der zwanzig Jahre aber, während deren Salomo den Tempel des HERRN und seinen Palast erbaut hatte,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 8, 2, 'da befestigte Salomo die Städte, die Huram ihm abgetreten hatte, und wies sie Israeliten zum Wohnsitz an.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 8, 3, 'Hierauf zog Salomo gegen Hamath-Zoba und unterwarf es.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 8, 4, 'Er befestigte auch Thadmor in der Wüste und alle Vorratsstädte, die er in Hamath angelegt hatte.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 8, 5, 'Weiter baute er das obere und das untere Beth-Horon zu festen Plätzen mit Mauern, Toren und Torriegeln aus;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 8, 6, 'ebenso Baalath und alle Vorratsstädte, die er besaß, sowie alle Ortschaften, in denen die Kriegswagen und die Reitpferde untergebracht wurden, überhaupt alle Bauten, die Salomo in Jerusalem, auf dem Libanon und im ganzen Bereich seiner Herrschaft auszuführen wünschte.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 8, 7, 'Alles, was noch an Nachkommen von den Hethitern, Amoritern, Perissitern, Hewitern und Jebusitern übrig war, die nicht zu den Israeliten gehörten –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 8, 8, 'die Nachkommen von ihnen, soweit sie im Lande noch übriggeblieben waren, weil die Israeliten sie nicht ausgerottet hatten –, die hob Salomo zum Frondienst aus, und sie sind Fronarbeiter geblieben bis auf den heutigen Tag.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 8, 9, 'Von den Israeliten dagegen machte Salomo keinen zum Leibeigenen für seine Arbeit, sondern sie dienten im Heer als Kriegsleute, als Befehlshaber und als Obere über seine Kriegswagen und über seine Reiterei. –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 8, 10, 'Die Zahl der Oberaufseher, die der König Salomo hatte, belief sich auf 250; sie hatten die Leute bei den Arbeiten zu beaufsichtigen. –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 8, 11, 'Die Tochter des Pharaos aber brachte Salomo aus der Davidsstadt in den Palast hinauf, den er für sie hatte erbauen lassen; denn er sagte: »Es soll keine meiner Frauen im Hause Davids, des Königs von Israel, wohnen; denn das sind heilige Stätten, seitdem die Lade des HERRN in sie eingezogen ist.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 8, 12, 'Damals brachte Salomo dem HERRN Brandopfer dar auf dem Altar, den er dem HERRN vor der Vorhalle errichtet hatte,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 8, 13, 'und zwar so, daß er daselbst das opferte, was nach dem Gebot Moses an jedem Tage erforderlich war: an den Sabbaten, an den Neumonden und dreimal im Jahr an den Festen, nämlich am Fest der ungesäuerten Brote und am Wochenfest und am Laubhüttenfest.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 8, 14, 'Auch bestellte er nach der Anordnung seines Vaters David die Abteilungen der Priester zu ihrem Dienst und die Leviten zu ihren Amtsverrichtungen, so daß sie die Lobgesänge anzustimmen hatten und den Priestern zur Hand gingen, wie jeder einzelne Tag es erforderte; ebenso die Torhüter nach ihren Abteilungen für die einzelnen Tore; denn so bestimmte es der Befehl Davids, des Mannes Gottes;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 8, 15, 'und man wich in keinem Punkt von dem Gebot des Königs in betreff der Priester und der Leviten ab, auch nicht in betreff der Schatzkammern. –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 8, 16, 'So wurde denn das ganze Werk Salomos vom Tage der Grundlegung des Tempels des HERRN an bis zu dessen Vollendung zur Ausführung gebracht, bis der Tempel des HERRN fertig dastand.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 8, 17, 'Damals begab sich Salomo nach Ezjon-Geber und nach Eloth an der Küste des (Roten) Meeres im Lande der Edomiter;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 8, 18, 'Huram aber sandte ihm durch seine Leute Schiffe und seekundige Leute, die zusammen mit Salomos Leuten nach Ophir fuhren und von dort 450 Talente Gold holten und es dem König Salomo überbrachten.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 9, 1, 'Als aber die Königin von Saba den Ruhm Salomos vernahm, kam sie, um Salomo mit Rätselfragen auf die Probe zu stellen, nach Jerusalem mit einem sehr großen Gefolge und mit Kamelen, die Spezereien und Gold in Menge und Edelsteine trugen. Als sie nun bei Salomo angekommen war, trug sie ihm alles vor, was sie sich vorgenommen hatte;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 9, 2, 'Salomo aber wußte ihr auf alle Fragen Antwort zu geben, und nichts war Salomo verborgen, worüber er ihr nicht hätte Auskunft geben können.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 9, 3, 'Als nun die Königin von Saba sich von der Weisheit Salomos überzeugt hatte und den Palast sah, den er erbaut hatte,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 9, 4, 'und die Speisen auf seiner Tafel und wie seine Hofleute dasaßen, ferner die Aufwartung seiner Dienerschaft und ihre Tracht, seine Mundschenken und deren Gewandung, dazu seine Brandopfer, die er im Tempel des HERRN darzubringen pflegte, da geriet sie vor Erstaunen ganz außer sich');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 9, 5, 'und sagte zum König: »Wahr ist das gewesen, was ich in meiner Heimat von dir und deiner Weisheit gehört habe.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 9, 6, 'Ich wollte dem, was man mir erzählte, nicht glauben, bis ich jetzt hergekommen bin und mich mit eigenen Augen überzeugt habe. Und dabei hat man mir noch nicht einmal die Hälfte von deiner außerordentlichen Weisheit berichtet: du übertriffst noch das Gerücht, das ich vernommen habe.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 9, 7, 'Beneidenswert sind deine Leute und beneidenswert diese deine Diener, die beständig vor dir stehen und deine Weisheit hören dürfen!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 9, 8, 'Gepriesen sei der HERR, dein Gott, der Wohlgefallen an dir gefunden hat, so daß er dich auf seinen Thron als König für den HERRN, deinen Gott, gesetzt hat! Weil dein Gott Israel liebt, darum hat er, um ihm für immer Bestand zu verleihen, dich zum König über sie bestellt, damit du Recht und Gerechtigkeit übest!« –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 9, 9, 'Hierauf schenkte sie dem König hundertundzwanzig Talente Gold und Spezereien in großer Menge sowie Edelsteine; niemals ist eine solche Menge von Spezereien beisammen gewesen, wie die Königin von Saba sie damals dem König Salomo schenkte.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 9, 10, '[Allerdings brachten auch die Leute Hurams und die Leute Salomos, wenn sie Gold aus Ophir geholt hatten, Sandelholz und Edelsteine mit;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 9, 11, 'und der König ließ von dem Sandelholz Treppen sowohl für den Tempel des HERRN als auch für den königlichen Palast herstellen sowie Zithern und Harfen für die Sänger; aber derartiges war zuvor im Lande Juda nicht zu sehen gewesen.]');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 9, 12, 'Der König Salomo aber schenkte der Königin von Saba alles, wonach sie Verlangen trug und was sie sich erbat, abgesehen von dem Gegengeschenk für das, was sie dem König gebracht hatte. Hierauf trat sie mit ihrem Gefolge den Rückweg an und zog wieder heim.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 9, 13, 'Das Gewicht des Goldes, das für Salomo in einem Jahre einging, betrug 666 Talente Gold,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 9, 14, 'ungerechnet die Einkünfte von den Karawanen und aus dem Handel der Kaufleute; dazu brachten auch alle Könige von Arabien und die Statthalter des Landes dem Salomo Gold und Silber. –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 9, 15, 'Der König Salomo ließ auch zweihundert Langschilde von getriebenem Golde anfertigen: mit sechshundert Schekel getriebenen Goldes überzog er jeden Schild;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 9, 16, 'ferner dreihundert Tartschen von getriebenem Golde: dreihundert Schekel Gold verwandte er auf den Überzug jeder Tartsche; der König brachte sie dann im Libanonwaldhause unter. –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 9, 17, 'Weiter ließ der König einen großen Thron von Elfenbein anfertigen und ihn mit feinem Gold überziehen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 9, 18, 'Der Thron hatte sechs Stufen, und ein goldener Fußschemel war an dem Throne befestigt; auf beiden Seiten des Sitzplatzes befanden sich Armlehnen, und neben den Armlehnen standen zwei Löwen;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 9, 19, 'außerdem standen zwölf Löwen auf den sechs Stufen zu beiden Seiten: ein derartiges Kunstwerk ist noch nie für irgendein Königreich hergestellt worden. –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 9, 20, 'Alle Trinkgefäße des Königs Salomo bestanden aus Gold; auch alle Geräte des Libanonwaldhauses waren von feinem Gold; Silber wurde zu Salomos Zeiten für wertlos geachtet.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 9, 21, 'Denn der König hatte Schiffe, die mit den Leuten Hurams nach Tharsis fuhren; einmal in drei Jahren kamen die Tharsisschiffe heim und brachten Gold und Silber, Elfenbein, Affen und Pfauen mit.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 9, 22, 'So übertraf denn der König Salomo alle Könige der Erde an Reichtum und Weisheit;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 9, 23, 'und alle Könige der Erde suchten Salomo zu sehen, um sich persönlich von seiner Weisheit zu überzeugen, die Gott ihm ins Herz gelegt hatte.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 9, 24, 'Dabei brachte jeder von ihnen sein Geschenk mit: silberne und goldene Geräte, Gewänder, Waffen und Spezereien, Rosse und Maultiere, Jahr für Jahr. –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 9, 25, 'Salomo besaß auch 4000 Gespanne Rosse und Wagen und 12000 Reitpferde, die er in den Wagenstädten oder in seiner Nähe zu Jerusalem untergebracht hatte.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 9, 26, 'Und er herrschte über alle Könige vom Euphratstrom an bis zum Philisterlande und bis an die Grenze Ägyptens.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 9, 27, 'Und der König brachte es dahin, daß es in Jerusalem soviel Silber gab wie Steine und daß die Zedernstämme an Menge den Maulbeerfeigenbäumen in der Niederung gleichkamen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 9, 28, 'Und man führte für Salomo Pferde aus Ägypten und aus allen übrigen Ländern ein.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 9, 29, 'Die übrige Geschichte Salomos aber, die frühere wie die spätere, findet sich bekanntlich schon aufgezeichnet in der Geschichte des Propheten Nathan sowie in der Weissagung Ahias von Silo und in den Gesichten des Sehers Iddo über Jerobeam, den Sohn Nebats.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 9, 30, 'Salomo hat aber vierzig Jahre lang in Jerusalem über ganz Israel geherrscht.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 9, 31, 'Dann legte Salomo sich zu seinen Vätern, und man begrub ihn in der Stadt seines Vaters David. Sein Sohn Rehabeam folgte ihm in der Regierung nach.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 10, 1, 'Rehabeam begab sich nun nach Sichem; denn in Sichem hatten sich alle Israeliten eingefunden, um ihn zum König zu machen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 10, 2, 'Sobald nun Jerobeam, der Sohn Nebats, Kunde davon erhielt – er befand sich nämlich in Ägypten, wohin er vor dem König Salomo geflohen war –, da kehrte Jerobeam aus Ägypten zurück;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 10, 3, 'man hatte nämlich hingesandt und ihn holen lassen. So kamen denn Jerobeam und das ganze Israel und trugen dem Rehabeam folgendes vor:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 10, 4, '»Dein Vater hat uns ein hartes Joch auferlegt; so erleichtere du uns jetzt deines Vaters harten Dienst und das schwere Joch, das er uns auferlegt hat, so wollen wir dir untertan sein!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 10, 5, 'Er antwortete ihnen: »Geduldet euch noch drei Tage, dann kommt wieder zu mir!« Nachdem sich nun das Volk entfernt hatte,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 10, 6, 'beriet sich der König Rehabeam mit den alten Räten, die seinem Vater Salomo bei dessen Lebzeiten gedient hatten, und fragte sie: »Welche Antwort ratet ihr mir diesen Leuten zu erteilen?«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 10, 7, 'Sie erwiderten ihm: »Wenn du dich heute diesen Leuten gegenüber freundlich zeigst und sie gnädig behandelst und ihnen eine gütige Antwort erteilst, so werden sie dir stets gehorsame Untertanen sein.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 10, 8, 'Aber er ließ den Rat, den ihm die Alten gegeben hatten, unbeachtet und beriet sich mit den jungen Männern, die mit ihm aufgewachsen waren und jetzt in seinen Diensten standen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 10, 9, 'Er fragte sie: »Welche Antwort müssen wir nach eurer Ansicht diesen Leuten geben, die von mir eine Erleichterung des Joches verlangen, das mein Vater ihnen auferlegt hat?«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 10, 10, 'Da gaben ihm die jungen Männer, die mit ihm aufgewachsen waren, folgende Antwort: »So mußt du den Leuten antworten, die von dir eine Erleichterung des schweren Joches verlangen, das dein Vater ihnen auferlegt hat, – so mußt du ihnen antworten: ›Mein kleiner Finger ist dicker als meines Vaters Lenden!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 10, 11, 'Und nun: hat mein Vater euch ein schweres Joch aufgeladen, so will ich euer Joch noch schwerer machen; hat mein Vater euch mit Peitschen gezüchtigt, so will ich euch mit Skorpionen züchtigen!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 10, 12, 'Als nun Jerobeam mit dem ganzen Volk am dritten Tage zu Rehabeam kam, wie der König ihnen befohlen hatte mit den Worten: »Kommt am dritten Tage wieder zu mir!«,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 10, 13, 'gab der König ihnen eine harte Antwort; denn der König Rehabeam ließ den Rat der Alten unbeachtet');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 10, 14, 'und gab ihnen nach dem Rat der jungen Männer folgende Antwort: »Hat mein Vater euch ein schweres Joch auferlegt, so will ich es noch schwerer machen; hat mein Vater euch mit Peitschen gezüchtigt, so will ich euch mit Skorpionen züchtigen.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 10, 15, 'So schenkte also der König dem Volke kein Gehör; denn von Gott war es so gefügt worden, damit der HERR seine Verheißung in Erfüllung gehen ließe, die er durch den Mund Ahias von Silo dem Jerobeam, dem Sohne Nebats, gegeben hatte.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 10, 16, 'Als nun ganz Israel sah, daß der König ihnen kein Gehör schenkte, ließ das Volk dem König folgende Erklärung zugehen: »Was haben wir mit David zu schaffen? Wir haben nichts gemein mit dem Sohne Isais. Ein jeder begebe sich in seine Heimat, ihr Israeliten! Nun sorge für dein eigenes Haus, David!« So begaben sich denn sämtliche Israeliten in ihre Heimat,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 10, 17, 'so daß Rehabeam nur über die Israeliten, die in den Ortschaften Judas wohnten, König blieb.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 10, 18, 'Als dann der König Rehabeam Hadoram, den Oberaufseher über die Fronarbeiter, hinsandte, warfen die Israeliten ihn mit Steinen zu Tode. Da hatte der König Rehabeam nichts Eiligeres zu tun, als in seinen Wagen zu springen, um nach Jerusalem zu fliehen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 10, 19, 'So fiel Israel vom Hause Davids ab bis auf den heutigen Tag.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 11, 1, 'Als aber Rehabeam in Jerusalem angekommen war, bot er den Stamm Juda und Benjamin, 180000 auserlesene Krieger, zum Kampf gegen Israel auf, um das Königtum für Rehabeam wiederzugewinnen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 11, 2, 'Aber das Wort des HERRN erging an den Gottesmann Semaja also:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 11, 3, '»Sage zu Rehabeam, dem Sohne Salomos, dem König von Juda, und zu sämtlichen Israeliten in Juda und Benjamin also:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 11, 4, '›So hat der HERR gesprochen: Ihr sollt nicht hinziehen, um mit euren Brüdern Krieg zu führen: kehrt allesamt nach Hause zurück! Denn von mir aus ist dies alles so gefügt worden.« Als sie die Weisung des HERRN vernahmen, kehrten sie um, ohne gegen Jerobeam zu ziehen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 11, 5, 'So blieb denn Rehabeam in Jerusalem und baute Ortschaften in Juda zu Festungen aus,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 11, 6, 'und zwar befestigte er Bethlehem, Etam, Thekoa,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 11, 7, 'Beth-Zur, Socho, Adullam,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 11, 8, 'Gath, Maresa, Siph,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 11, 9, 'Adoraim, Lachis, Aseka,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 11, 10, 'Zorea, Ajjalon und Hebron, die in Juda und Benjamin lagen; die baute er zu festen Plätzen aus.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 11, 11, 'Er machte aus ihnen starke Festungen, setzte Befehlshaber über sie und legte Vorräte von Lebensmitteln, von Öl und Wein hinein');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 11, 12, 'sowie in jeden Platz Schilde und Speere und setzte sie so in vorzüglich festen Stand. So waren denn Juda und Benjamin in seiner Gewalt.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 11, 13, 'Die Priester und Leviten aber im gesamten Israel stellten sich ihm aus allen ihren Bezirken zur Verfügung.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 11, 14, 'Die Leviten verließen nämlich ihre Wohnorte und ihr Besitztum und begaben sich nach Juda und Jerusalem, weil Jerobeam samt seinen Söhnen sie ihres Amtes als Priester des HERRN entsetzt');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 11, 15, 'und er sich eigene Priester für den Höhendienst sowie für die Feldteufel und die Stierbilder bestellt hatte, die er hatte anfertigen lassen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 11, 16, 'Ihrem Vorgange folgend, kamen dann aus allen Stämmen Israels diejenigen, welche aufrichtig darauf bedacht waren, den HERRN, den Gott Israels, zu suchen, nach Jerusalem, um dem HERRN, dem Gott ihrer Väter, zu opfern.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 11, 17, 'Diese stärkten das Reich Juda und befestigten Rehabeam, den Sohn Salomos, in der Herrschaft drei Jahre lang; denn drei Jahre lang wandelten sie auf dem Wege Davids und Salomos.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 11, 18, 'Rehabeam war aber mit Mahalath, einer Tochter Jerimoths, des Sohnes Davids, und der Abihail, der Tochter Eliabs, des Sohnes Isais, verheiratet;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 11, 19, 'die gebar ihm Söhne, nämlich Jehus, Semarja und Saham.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 11, 20, 'Nach ihr verheiratete er sich mit Maacha, der Tochter Absaloms, die ihm Abia, Atthai, Sisa und Selomith gebar.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 11, 21, 'Rehabeam hatte aber Maacha, die Tochter Absaloms, lieber als alle seine anderen Frauen und Nebenweiber; er hatte sich nämlich achtzehn Frauen und sechzig Nebenweiber genommen, von denen ihm achtundzwanzig Söhne und sechzig Töchter geboren wurden.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 11, 22, 'Rehabeam setzte dann Abia, den Sohn der Maacha, zum Familienhaupt, zum Fürsten unter seinen Brüdern, ein; denn es war seine Absicht, ihn zum König zu machen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 11, 23, 'Dabei ging er klug zu Werke, indem er alle seine Söhne auf die einzelnen Landesteile von Juda und Benjamin und auf alle festen Plätze verteilte und ihnen ein reichliches Auskommen zuwies und Frauen in Menge für sie warb.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 12, 1, 'Als Rehabeam sich aber auf dem Throne befestigt und seine Herrschaft gesichert hatte, fiel er und ganz Israel mit ihm vom Gesetz des HERRN ab.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 12, 2, 'Da zog im fünften Jahre der Regierung Rehabeams der König Sisak von Ägypten mit 1200 Wagen und 60000 Reitern gegen Jerusalem heran, weil sie treulos am HERRN gehandelt hatten;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 12, 3, 'und unzählbar war das Kriegsvolk, das mit ihm aus Ägypten kam: Libyer, Sukkiter und Äthiopier.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 12, 4, 'Er eroberte die festen Plätze, die zu Juda gehörten, und drang bis Jerusalem vor.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 12, 5, 'Da trat der Prophet Semaja vor Rehabeam und vor die Fürsten Judas, die sich vor Sisak nach Jerusalem zurückgezogen hatten, und sagte zu ihnen: »So hat der HERR gesprochen: ›Ihr habt mich verlassen; so habe denn auch ich euch verlassen und euch der Gewalt Sisaks preisgegeben!‹«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 12, 6, 'Da demütigten sich die Fürsten Judas mit dem Könige und bekannten: »Der HERR ist gerecht!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 12, 7, 'Als nun der HERR sah, daß sie sich gedemütigt hatten, erging das Wort des HERRN an Semaja folgendermaßen: »Sie haben sich gedemütigt: ich will sie (daher) nicht vernichten, sondern ihnen in kurzem Rettung zuteil werden lassen, und mein Grimm soll sich nicht durch Sisak über Jerusalem ergießen!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 12, 8, 'Doch sollen sie ihm dienstbar werden, damit sie den Unterschied zwischen meinem Dienste und dem Dienst der weltlichen Königreiche kennenlernen.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 12, 9, 'So zog denn Sisak, der König von Ägypten, gegen Jerusalem heran und raubte die Schätze des Tempels des HERRN und die Schätze des königlichen Palastes: alles raubte er, auch die goldenen Schilde nahm er weg, die Salomo hatte anfertigen lassen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 12, 10, 'An deren Stelle ließ der König Rehabeam kupferne Schilde herstellen und übergab sie der Obhut der Befehlshaber seiner Leibwache, die am Eingang zum königlichen Palast die Wache hatte.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 12, 11, 'Sooft sich nun der König in den Tempel des HERRN begab, kamen die Leibwächter und trugen die Schilde und brachten sie dann wieder in das Wachtzimmer der Leibwache zurück.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 12, 12, 'Weil er sich aber gedemütigt hatte, wandte sich der Zorn des HERRN von ihm ab, so daß er ihn nicht gänzlich zugrunde richtete; es fand sich ja damals auch in Juda noch manches Gute.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 12, 13, 'So befestigte sich denn der König Rehabeam zu Jerusalem wieder in der Herrschaft und regierte weiter; im Alter von einundvierzig Jahren nämlich hatte Rehabeam den Thron bestiegen, und siebzehn Jahre regierte er in Jerusalem, der Stadt, die der HERR aus allen Stämmen Israels erwählt hatte, um seinen Namen dort wohnen zu lassen. Seine Mutter hieß Naama und war eine Ammonitin.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 12, 14, 'Er hatte aber böse gehandelt, weil er nicht darauf bedacht gewesen war, den HERRN zu suchen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 12, 15, 'Die Geschichte Rehabeams aber, die frühere wie die spätere, findet sich bekanntlich aufgezeichnet in der Geschichte des Propheten Semaja und in der des Sehers Iddo. Die Kriege zwischen Rehabeam und Jerobeam aber gingen ohne Unterbrechung fort.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 12, 16, 'Als Rehabeam sich dann zu seinen Vätern gelegt hatte, wurde er in der Davidsstadt begraben, und sein Sohn Abia folgte ihm in der Regierung nach.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 13, 1, 'Im achtzehnten Jahre (der Regierung) des Königs Jerobeam wurde Abia König über Juda.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 13, 2, 'Er regierte drei Jahre in Jerusalem; seine Mutter hieß Michaja und war eine Tochter Uriels von Gibea. Es herrschte aber Krieg zwischen Abia und Jerobeam.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 13, 3, 'Und Abia eröffnete den Kampf mit einem kriegstüchtigen Heere von 400000 auserlesenen Kriegern, während Jerobeam 800000 Mann auserlesener Kerntruppen gegen ihn ins Feld stellte.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 13, 4, 'Da trat Abia oben auf den Berg Zemaraim, der im Berglande Ephraim liegt, und rief: »Hört mich an, Jerobeam und ihr Israeliten alle!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 13, 5, 'Solltet ihr wirklich nicht wissen, daß der HERR, der Gott Israels, das Königtum über Israel dem David auf ewig verliehen hat, ihm und seinen Nachkommen, und zwar auf Grund eines Salzbundes?');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 13, 6, 'Aber Jerobeam, der Sohn Nebats, ein Untertan Salomos, des Sohnes Davids, ist aufgetreten und hat sich gegen seinen Herrn empört;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 13, 7, 'und leichtfertige Männer, nichtswürdige Leute, haben sich um ihn geschart und die Oberhand über Rehabeam, den Sohn Salomos, gewonnen; denn Rehabeam war noch jung und unselbständig und zu schwach, um sich ihrem Einfluß zu entziehen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 13, 8, 'Und nun meint ihr dem Königtum des HERRN, das im Besitz der Nachkommen Davids ist, entgegentreten zu können, weil ihr ein großer Haufe seid und ihr die goldenen Stierbilder bei euch habt, die Jerobeam euch zu Göttern gemacht hat!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 13, 9, 'Habt ihr nicht die Priester des HERRN, die Nachkommen Aarons, und die Leviten vertrieben und euch eigene Priester gemacht wie die Heidenvölker? Wer irgend mit einem jungen Stiere und sieben Widdern gekommen ist, um sich für das Priestertum weihen zu lassen, der ist von euch zum Priester der Nichtgötter (oder Götzen) gemacht worden.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 13, 10, 'Unser Gott dagegen ist der HERR, und wir sind nicht von ihm abgefallen; und als Priester dienen dem HERRN die Nachkommen Aarons, und die Leviten verrichten ihre Amtsgeschäfte;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 13, 11, 'sie bringen dem HERRN an jedem Morgen und jedem Abend Brandopfer und wohlriechendes Räucherwerk dar und legen die Schaubrote auf dem Tische von reinem Gold aus und zünden den goldenen Leuchter mit seinen Lampen an jedem Abend an; denn wir beobachten die Vorschriften des HERRN, unsers Gottes, genau, während ihr ihn verlassen habt.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 13, 12, 'Bedenkt wohl: mit uns ist Gott, der an unserer Spitze steht, dazu seine Priester mit den Lärmtrompeten, um sie gegen euch erschallen zu lassen! O ihr Israeliten! Kämpft nicht gegen den HERRN, den Gott eurer Väter, denn damit werdet ihr kein Glück haben!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 13, 13, 'Jerobeam aber hatte die im Hinterhalt liegenden Mannschaften eine Schwenkung machen lassen, damit sie ihnen in den Rücken kämen; und so standen sie einesteils vorn den Judäern gegenüber, während andernteils die Mannschaften des Hinterhalts sich in ihrem Rücken befanden.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 13, 14, 'Als daher die Judäer sich umwandten, sahen sie sich von vorn und von hinten angegriffen. Da schrien sie zum HERRN, und die Priester stießen in die Trompeten,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 13, 15, 'und die Judäer erhoben das Kriegsgeschrei; und als sie das getan hatten, ließ Gott Jerobeam und ganz Israel die Flucht vor Abia und den Judäern ergreifen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 13, 16, 'Als nun die Israeliten vor den Judäern flohen, gab Gott sie ihnen preis,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 13, 17, 'so daß Abia und seine Leute ein furchtbares Blutbad unter ihnen anrichteten und von den Israeliten 500000 Mann auserlesener Mannschaften erschlagen liegen blieben.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 13, 18, 'So wurde damals die Macht der Israeliten gebrochen, während die Judäer die Oberhand gewannen, weil sie ihr Vertrauen auf den HERRN, den Gott ihrer Väter, gesetzt hatten.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 13, 19, 'Abia verfolgte dann Jerobeam und nahm ihm mehrere Städte weg, nämlich Bethel nebst den zugehörigen Ortschaften, Jesana nebst den zugehörigen Ortschaften und Ephron nebst den zugehörigen Ortschaften.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 13, 20, 'Jerobeam aber kam, solange Abia lebte, nicht wieder zu Kräften, und der HERR ließ ihn eines plötzlichen Todes sterben.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 13, 21, 'Abia aber wurde mächtig; er nahm sich vierzehn Frauen, die ihm zweiundzwanzig Söhne und sechzehn Töchter gebaren.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 13, 22, 'Die übrige Geschichte Abias aber, seine Taten und seine Reden, finden sich aufgezeichnet in dem erbaulichen Geschichtswerk des Propheten Iddo. –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 13, 23, 'Als Abia sich aber zu seinen Vätern gelegt und man ihn in der Davidsstadt begraben hatte, folgte ihm sein Sohn Asa auf dem Throne nach; unter dessen Regierung erfreute das Land sich zehn Jahre lang der Ruhe.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 14, 1, 'Asa tat, was in den Augen des HERRN, seines Gottes, gut und recht war;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 14, 2, 'denn er beseitigte die Altäre der fremden Götter und den Höhendienst, ließ die Malsteine zerschlagen und die Götzenpfähle umhauen');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 14, 3, 'und wies die Judäer darauf hin, den HERRN, den Gott ihrer Väter, zu suchen und das Gesetz und die Gebote zu erfüllen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 14, 4, 'In allen Ortschaften Judas beseitigte er den Höhendienst und die Sonnensäulen, und das Reich erfreute sich der Ruhe unter ihm.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 14, 5, 'Er legte sodann feste Plätze in Juda an; denn das Land hatte Ruhe, und niemand führte in jenen Jahren Krieg mit ihm, weil der HERR ihm Ruhe verschafft hatte.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 14, 6, 'Darum forderte er die Judäer auf: »Laßt uns diese Ortschaften ausbauen und sie mit Mauern und Türmen, Toren und Riegeln rings umgeben! Noch haben wir freie Hand im Lande, weil wir den HERRN, unsern Gott, gesucht haben; wir haben ihn gesucht, und er hat uns ringsum Ruhe geschafft.« So machten sie sich denn an die Bauten und führten sie glücklich aus.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 14, 7, 'Dazu besaß Asa ein Heer, das Schild und Speer führte: aus Juda 300000 und aus Benjamin 280000 Mann, welche Tartschen führten und den Bogen zu spannen wußten, durchweg tapfere Krieger.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 14, 8, 'Da zog der Kuschit Serah gegen sie heran mit einem Heere von einer Million Mann und mit dreihundert Kriegswagen und drang bis Maresa vor.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 14, 9, 'Asa zog ihm entgegen, und sie stellten sich im Tal Zephatha bei Maresa zur Schlacht auf.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 14, 10, 'Da rief Asa den HERRN, seinen Gott, an und betete: »HERR! Um zu helfen, ist bei dir kein Unterschied zwischen einem Starken und einem Schwachen. So hilf uns, HERR, unser Gott! Denn auf dich setzen wir unser Vertrauen und in deinem Namen sind wir gegen diese Übermacht ausgezogen. Du bist der HERR, unser Gott: kein Mensch soll dir gegenüber sich behaupten dürfen!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 14, 11, 'Da schlug der HERR die Kuschiten, so daß sie vor Asa und den Judäern die Flucht ergriffen;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 14, 12, 'Asa aber und das Heer, das bei ihm war, verfolgten sie bis Gerar, und es fielen von den Kuschiten so viele, daß keiner von ihnen mit dem Leben davonkam, sondern sie vor dem HERRN und seinem Heere völlig aufgerieben wurden. So machten die Judäer denn eine gewaltige Beute,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 14, 13, 'eroberten auch alle Städte rings um Gerar – es war nämlich ein Schrecken vom HERRN her über sie gekommen –, und sie plünderten alle Städte; denn es befand sich eine reiche Beute in ihnen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 14, 14, 'Auch der Zeltlager mit den Herden bemächtigten sie sich, trieben Kleinvieh in Menge und Kamele als Beute weg und kehrten dann nach Jerusalem zurück.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 15, 1, 'Da kam der Geist Gottes über Asarja, den Sohn Odeds,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 15, 2, 'so daß er hinausging, vor Asa hintrat und zu ihm sagte: »Hört mich an, Asa und ihr Judäer und Benjaminiten alle! Der HERR ist mit euch, solange ihr euch zu ihm haltet, und wenn ihr ihn sucht, läßt er sich von euch finden, wenn ihr ihn aber verlaßt, wird auch er euch verlassen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 15, 3, 'Lange Zeit ist Israel ohne den wahren Gott gewesen und ohne priesterliche Belehrung und ohne Gesetz;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 15, 4, 'dann aber, in seiner Bedrängnis, kehrte es zum HERRN, dem Gott Israels, zurück, und da sie ihn suchten, ließ er sich von ihnen finden.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 15, 5, 'Zu jenen Zeiten aber gab es keine Sicherheit für die Aus- und Eingehenden; denn beständige Unruhen herrschten bei allen Bewohnern der verschiedenen Landesteile:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 15, 6, 'ein Volk wurde von dem andern bedrängt und eine Stadt von der andern; denn Gott schreckte sie durch Leiden aller Art.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 15, 7, 'Ihr aber, seid stark und laßt eure Hände nicht erschlaffen, denn euer Tun wird belohnt werden!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 15, 8, 'Als Asa diese Worte und die Weissagung des Propheten Asarja, des Sohnes Odeds, vernahm, gewann er neuen Mut und schaffte die Greuel aus dem ganzen Lande Juda und Benjamin und aus den Ortschaften weg, die er im Berglande Ephraim erobert hatte, und erneuerte den Altar des HERRN, der vor der Vorhalle (des Tempels) des HERRN stand.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 15, 9, 'Dann versammelte er ganz Juda und Benjamin und diejenigen Ephraimiten, Manassiten und Simeoniten, die als Fremdlinge bei ihnen lebten; denn es waren ihm aus Israel Leute in großer Zahl zugefallen, als sie sahen, daß der HERR, sein Gott, mit ihm war.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 15, 10, 'Sie kamen also im dritten Monat des fünfzehnten Regierungsjahres Asas in Jerusalem zusammen');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 15, 11, 'und opferten dem HERRN an jenem Tage von der Beute, die sie heimgebracht hatten, siebenhundert Rinder und siebentausend Stück Kleinvieh.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 15, 12, 'Hierauf verpflichteten sie sich feierlich, den HERRN, den Gott ihrer Väter, mit ganzem Herzen und mit ganzer Seele zu suchen;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 15, 13, 'jeder aber, der sich nicht an den HERRN, den Gott Israels, halten würde, sollte mit dem Tode bestraft werden, er möchte vornehm oder gering, Mann oder Weib sein.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 15, 14, 'Diesen Eid leisteten sie dem HERRN mit lauter Stimme und mit Jubelgeschrei, unter Trompeten- und Posaunenschall;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 15, 15, 'und ganz Juda war voller Freude über den Schwur, denn sie hatten ihn mit ganzem Herzen geleistet; und weil sie den HERRN mit aller Aufrichtigkeit suchten, ließ er sich von ihnen finden, und der HERR verschaffte ihnen Ruhe ringsumher. –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 15, 16, 'Sogar seiner Mutter Maacha entzog der König Asa den Rang der Königin-Mutter, weil sie der Aschera ein Götzenbild hatte anfertigen lassen; Asa ließ ihr Götzenbild umhauen und zerschlagen und im Kidrontal verbrennen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 15, 17, 'Der Höhendienst wurde allerdings in Israel nicht abgeschafft, doch blieb das Herz Asas dem HERRN zeitlebens ungeteilt ergeben.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 15, 18, 'Er ließ auch die Geschenke, die sein Vater und die er selbst geweiht hatte, in den Tempel Gottes bringen: Silber, Gold und Geräte.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 15, 19, 'Bis zum fünfunddreißigsten Regierungsjahre Asas fand kein Krieg statt;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 16, 1, 'aber im sechsunddreißigsten Regierungsjahre Asas zog Baesa, der König von Israel, gegen Juda heran und befestigte Rama, damit niemand mehr bei Asa, dem Könige von Juda, ungehindert aus- und eingehen könne.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 16, 2, 'Da nahm Asa Silber und Gold aus den Schatzkammern des Tempels des HERRN und des königlichen Palastes, sandte es an Benhadad, den König von Syrien, der zu Damaskus wohnte, und ließ ihm sagen:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 16, 3, '»Ein Bündnis besteht zwischen mir und dir, zwischen meinem Vater und deinem Vater! Hier sende ich dir nun Silber und Gold. So löse denn dein Bündnis mit dem König Baesa von Israel auf, damit er aus meinem Lande abzieht!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 16, 4, 'Benhadad schenkte der Aufforderung des Königs Asa Gehör und ließ seine Heerführer gegen die Städte Israels ziehen; sie eroberten Ijjon, Dan, Abel-Majim und alle Vorratshäuser in den Ortschaften Naphthalis.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 16, 5, 'Sobald nun Baesa Kunde davon erhielt, gab er die Befestigung Ramas auf und stellte seine Arbeit dort ein.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 16, 6, 'Der König Asa aber bot ganz Juda auf; die mußten die Steine und Balken wegschaffen, mit denen Baesa Rama hatte befestigen wollen; und er ließ dann Geba und Mizpa damit befestigen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 16, 7, 'Zu jener Zeit aber kam der Seher Hanani zu Asa, dem König von Juda, und sagte zu ihm: »Weil du dein Vertrauen auf den König von Syrien gesetzt und dich nicht auf den HERRN, deinen Gott, verlassen hast, darum ist das Heer des Königs von Syrien der Vernichtung durch dich entgangen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 16, 8, 'Waren nicht die Kuschiten und Libyer eine gewaltige Heeresmacht mit Wagen und Reitern in großer Zahl? Aber weil du dein Vertrauen auf den HERRN setztest, ließ er sie in deine Gewalt fallen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 16, 9, 'Denn die Augen des HERRN überschauen die ganze Erde, damit er seine Macht zum Heil für die erweise, deren Herz ungeteilt auf ihn gerichtet ist. Du hast in diesem Fall töricht gehandelt; denn von nun an wirst du (unablässig) Kriege zu führen haben.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 16, 10, 'Asa wurde über den Seher unwillig und ließ ihn ins Stockhaus werfen; denn er war wegen seines Auftretens aufgebracht gegen ihn. Gleichzeitig ging Asa auch gegen einige Leute aus dem Volke gewalttätig vor.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 16, 11, 'Die Geschichte Asas aber von Anfang bis zu Ende findet sich bekanntlich bereits im Buch der Könige von Juda und Israel aufgezeichnet.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 16, 12, 'Im neununddreißigsten Jahre seiner Regierung erkrankte Asa an einem Fußleiden, und zwar in sehr ernster Weise; aber auch in (dieser) seiner Krankheit suchte er nicht beim HERRN Hilfe, sondern bei den Ärzten.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 16, 13, 'Als er sich dann zu seinen Vätern gelegt und im einundvierzigsten Jahre seiner Regierung gestorben war,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 16, 14, 'begrub man ihn in seiner Grabstätte, die er sich in der Davidsstadt hatte aushauen lassen. Man legte ihn auf ein Lager, das man mit Spezereien aller Art und mit Wohlgerüchen von kunstgerecht hergestellten Salben angefüllt hatte, und veranstaltete ihm zu Ehren einen überaus großartigen Leichenbrand.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 17, 1, 'Sein Nachfolger auf dem Throne wurde sein Sohn Josaphat, der mit Nachdruck gegen Israel auftrat.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 17, 2, 'Er legte Kriegsvolk in alle festen Plätze Judas und verteilte Besatzungen über das Land Juda und in die Städte von Ephraim, die sein Vater Asa erobert hatte.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 17, 3, 'Und der HERR war mit Josaphat, weil er auf den alten Wegen seines Ahnherrn David wandelte und nicht die Baale aufsuchte,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 17, 4, 'sondern sich an den Gott seines Ahnherrn hielt und nach dessen Geboten wandelte und es nicht wie die Israeliten machte.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 17, 5, 'Darum ließ der HERR das Königtum in seiner Hand erstarken, so daß alle Judäer ihm Geschenke brachten und ihm Reichtum und Ehre in hohem Maße zuteil wurde.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 17, 6, 'Weil ihm dann der Mut auf den Wegen des HERRN wuchs, beseitigte er auch noch den Höhendienst und die Götzenbäume in Juda.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 17, 7, 'In seinem dritten Regierungsjahr aber sandte er seine höchsten Beamten Ben-Hail, Obadja, Sacharja, Nethaneel und Michaja aus, damit sie den Städten Judas Unterweisung erteilten,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 17, 8, 'und mit ihnen die Leviten Semaja, Nethanja, Sebadja, Asahel, Semiramoth, Jonathan, Adonia, Tobia und Tob-Adonia [die Leviten], dazu mit ihnen die Priester Elisama und Joram.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 17, 9, 'Diese lehrten also in Juda, indem sie das Gesetzbuch des HERRN bei sich hatten und in allen Ortschaften Judas umherzogen und unter dem Volke lehrten.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 17, 10, 'Vom HERRN aber ging ein Schrecken über alle Königreiche in den Ländern aus, die rings um Juda her lagen, so daß sie keinen Krieg mit Josaphat anfingen;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 17, 11, 'ja sogar von den Philistern kamen Gesandte, die dem Josaphat Geschenke und Silber als die ihnen auferlegte Abgabe brachten; auch die Araber brachten ihm Kleinvieh, nämlich 7700 Widder und 7700 Böcke.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 17, 12, 'So wurde Josaphat allmählich immer größer und mächtiger und legte in Juda Burgen und Vorratsstädte an.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 17, 13, 'Er besaß auch bedeutende Vorräte in den Städten Judas, dazu in Jerusalem ein Heer tapferer Krieger,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 17, 14, 'das, nach Familien geordnet, folgende Zusammensetzung aufwies: Von Juda waren als Befehlshaber von Tausendschaften: Adna, der Heerführer, der 300000 tapfere Krieger unter sich hatte;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 17, 15, 'neben ihm Johanan, der Heerführer, der 280000 Mann befehligte;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 17, 16, 'neben ihm Amasja, der Sohn Sichris, der sich dem HERRN freiwillig zur Verfügung gestellt hatte und 200000 tapfere Krieger unter sich hatte.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 17, 17, 'Aus Benjamin aber waren: der tapfere Kriegsmann Eljada, der Befehlshaber über 200000 Mann, die mit Bogen und Schild bewaffnet waren;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 17, 18, 'und neben ihm Josabad, der 180000 kriegsgerüstete Leute befehligte.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 17, 19, 'Diese waren es, die im Dienst des Königs standen, abgesehen von jenen, welche der König in die festen Plätze von ganz Juda gelegt hatte.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 1, 'Als Josaphat aber Reichtum und Ehre in Fülle erlangt hatte, verschwägerte er sich mit Ahab');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 2, 'und begab sich dann einige Jahre später auf Besuch zu Ahab nach Samaria hinab. Da ließ Ahab für ihn und sein Gefolge Kleinvieh und Rinder in Menge schlachten und beredete ihn, am Feldzuge gegen Ramoth in Gilead teilzunehmen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 3, 'Der König Ahab von Israel richtete nämlich an den König Josaphat von Juda die Frage: »Willst du mit mir gegen Ramoth in Gilead ziehen?« Da erwiderte er ihm: »Ich will sein wie du: mein Volk (oder Heer) wie dein Volk (oder Heer); ja ich will mit dir zu Felde ziehen!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 4, 'Als Josaphat dann dem König von Israel riet, zunächst doch den Willen des HERRN zu erforschen,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 5, 'ließ der König von Israel die Propheten zusammenkommen, vierhundert Mann, und fragte sie: »Sollen wir gegen Ramoth in Gilead zu Felde ziehen, oder soll ich es unterlassen?« Sie antworteten: »Ziehe hin, denn Gott wird es dem König in die Hand geben!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 6, 'Da fragte Josaphat: »Ist hier sonst kein Prophet des HERRN mehr, durch den wir Auskunft erhalten könnten?«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 7, 'Der König von Israel erwiderte dem Josaphat: »Es ist wohl noch einer da, durch den wir den HERRN befragen könnten; aber ich habe nicht gern mit ihm zu tun, denn er weissagt mir niemals Gutes, sondern immer nur Unglück; das ist Micha, der Sohn Jimlas.« Aber Josaphat entgegnete: »Der König wolle nicht so reden!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 8, 'Da rief der König von Israel einen Kammerherrn und befahl ihm, schleunigst Micha, den Sohn Jimlas, zu holen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 9, 'Während nun der König von Israel und der König Josaphat von Juda ein jeder auf seinem Thron in ihren Königsgewändern auf dem freien Platz am Eingang des Stadttores von Samaria saßen und alle Propheten vor ihnen weissagten,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 10, 'machte sich Zedekia, der Sohn Kenaanas, eiserne Hörner und rief aus: »So spricht der HERR: ›Mit solchen Hörnern wirst du die Syrer niederstoßen, bis du sie vernichtet hast!‹«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 11, 'Ebenso weissagten auch alle anderen Propheten, indem sie riefen: »Ziehe hin nach Ramoth in Gilead: du wirst Glück haben, denn der HERR wird es dem König in die Hand fallen lassen.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 12, 'Der Bote aber, der hingegangen war, um Micha zu holen, sagte zu ihm: »Siehe, die (übrigen) Propheten haben dem König einstimmig Glück verheißen; so schließe du dich doch ihrem einmütigen Ausspruche an und prophezeie ebenfalls Glück!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 13, 'Micha aber antwortete: »So wahr der HERR lebt! Nur was mein Gott mir eingeben wird, das werde ich verkünden!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 14, 'Als er nun zum König kam, fragte dieser ihn: »Micha, sollen wir gegen Ramoth in Gilead zu Felde ziehen, oder soll ich es unterlassen?« Er antwortete: »Zieht hin, ihr werdet Glück haben, denn sie werden euch in die Hand geliefert werden!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 15, 'Da entgegnete ihm der König: »Wie oft soll ich dich beschwören, daß du mir nichts verkündest als die reine Wahrheit im Namen des HERRN?«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 16, 'Da sagte Micha: »Ich habe ganz Israel zerstreut auf den Bergen gesehen wie Schafe, die keinen Hirten haben; der HERR aber sagte: ›Diese haben keinen Herrscher mehr: ein jeder (von ihnen) möge in Frieden nach Hause zurückkehren!‹«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 17, 'Da sagte der König von Israel zu Josaphat: »Habe ich dir nicht gesagt, daß er mir niemals Glück, sondern nur Unheil prophezeit?«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 18, 'Micha aber fuhr fort: »Darum vernehmet das Wort des HERRN! Ich habe den HERRN auf seinem Throne sitzen sehen, während das ganze himmlische Heer ihm zur Rechten und zur Linken stand.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 19, 'Da fragte der HERR: ›Wer will Ahab, den König von Israel, betören, daß er zu Felde ziehe und bei Ramoth in Gilead falle?‹ Da erwiderte der eine dies, der andere das,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 20, 'bis endlich der (oder ein) Geist vortrat, sich vor den HERRN stellte und sagte: ›Ich will ihn betören!‹ Der HERR fragte ihn: ›Auf welche Weise?‹');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 21, 'Da antwortete er: ›Ich will hingehen und zum Lügengeist im Munde aller seiner Propheten werden.‹ Da sagte der HERR: ›Du sollst ihn betören, und es wird dir auch gelingen! Geh hin und tu so!‹');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 22, 'Nun denn, siehe! Der HERR hat diesen deinen Propheten einen Geist der Lüge in den Mund gelegt; denn der HERR hat Unglück für dich beschlossen.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 23, 'Da trat Zedekia, der Sohn Kenaanas, auf Micha zu und gab ihm einen Backenstreich mit den Worten: »Auf welchem Wege sollte denn der Geist des HERRN von mir gewichen sein, um mit dir zu reden?«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 24, 'Micha entgegnete: »Du wirst es an jenem Tage erfahren, an welchem du dich aus einem Gemach in das andere begeben wirst, um dich zu verstecken!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 25, 'Hierauf befahl der König von Israel: »Nehmt Micha und führt ihn zum Stadthauptmann Amon und zum königlichen Prinzen Joas zurück');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 26, 'und meldet dort: ›So hat der König befohlen: Werft diesen Menschen ins Gefängnis und erhaltet ihn notdürftig mit Brot und Wasser am Leben, bis ich wohlbehalten heimkehre!‹«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 27, 'Micha antwortete: »Wenn du wirklich wohlbehalten heimkehrst, so hat der HERR nicht durch mich geredet!« Er fügte dann noch hinzu: »Hört dies, ihr Völker alle!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 28, 'Als hierauf der König von Israel und Josaphat, der König von Juda, gegen Ramoth in Gilead zu Felde gezogen waren,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 29, 'sagte der König von Israel zu Josaphat: »Ich will mich verkleiden und so in die Schlacht gehen; du aber magst deine gewöhnliche Kleidung anbehalten.« So verkleidete sich denn der König von Israel, und sie zogen in die Schlacht.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 30, 'Der König von Syrien hatte aber den Befehlshabern seiner Kriegswagen den bestimmten Befehl erteilt: »Ihr sollt niemand angreifen, er sei gering oder vornehm, sondern nur den König von Israel!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 31, 'Als nun die Befehlshaber der Kriegswagen Josaphat zu Gesicht bekamen, dachten sie, daß er der König von Israel sei, und wandten sich von allen Seiten gegen ihn, um ihn anzugreifen. Da erhob Josaphat ein Geschrei, und der HERR half ihm, indem Gott sie von ihm weglockte.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 32, 'Sobald nämlich die Befehlshaber der Wagen erkannt hatten, daß er nicht der König von Israel sei, wandten sie sich von ihm ab.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 33, 'Ein Mann aber spannte seinen Bogen aufs Geratewohl und traf den König von Israel zwischen den Ringelgurt und den Panzer. Da befahl er seinem Wagenlenker: »Wende um und bringe mich vom Schlachtfelde weg, denn ich bin verwundet!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 34, 'Da aber der Kampf an jenem Tage immer heftiger entbrannte, blieb der König von Israel dann doch den Syrern gegenüber aufrecht im Wagen stehen bis zum Abend; um die Zeit des Sonnenuntergangs aber starb er.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 19, 1, 'Als dann Josaphat, der König von Juda, wohlbehalten nach Hause, nach Jerusalem, zurückgekehrt war,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 19, 2, 'trat der Seher Jehu, der Sohn Hananis, vor ihn hin und sagte zu ihm: »Darfst (oder mußtest) du einem Gottlosen Hilfe leisten, und willst du denen, die den HERRN hassen, Liebe erweisen? Aus diesem Grunde lastet nun der Zorn des HERRN auf dir.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 19, 3, 'Jedoch ist auch Gutes an dir gefunden worden, weil du die Astartebilder aus dem Lande weggeschafft hast und darauf bedacht gewesen bist, Gott zu suchen.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 19, 4, 'Nachdem Josaphat dann eine Zeitlang in Jerusalem geblieben war, zog er wiederum unter dem Volk umher von Beerseba bis zum Bergland Ephraim und führte sie zum HERRN, dem Gott ihrer Väter, zurück.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 19, 5, 'Auch bestellte er Richter im Lande, in allen festen Städten Judas, Stadt für Stadt,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 19, 6, 'und gab den Richtern die Weisung: »Seht wohl zu, was ihr tut! Denn nicht im Auftrage von Menschen sprecht ihr Recht, sondern im Auftrage des HERRN, der bei euch ist, wenn ihr Recht sprecht.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 19, 7, 'Darum möge ein Schrecken vor dem HERRN in euch wohnen! Gebt auf das, was ihr tut, wohl acht! Denn bei dem HERRN, unserm Gott, findet sich weder Ungerechtigkeit noch Ansehen der Person und keine Bestechlichkeit.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 19, 8, 'Auch in Jerusalem bestellte Josaphat einige Leviten und Priester und Familienhäupter Israels für das Gericht des HERRN und für die Rechtsstreitigkeiten der Bewohner Jerusalems.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 19, 9, 'Dabei gab er ihnen folgende Weisungen: »So sollt ihr verfahren in der Furcht vor dem HERRN, mit aller Treue und mit aufrichtigem Herzen!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 19, 10, 'In jedem Rechtsstreit, der euch von seiten eurer Volksgenossen, die in ihren Ortschaften wohnen, vorgelegt wird, er betreffe irgendeinen Fall von Blutschuld oder irgendein Gesetz und Gebot oder irgendwelche Satzungen und Rechte, sollt ihr die Leute belehren, damit sie sich nicht gegen den HERRN vergehen und kein Zorn über euch und eure Volksgenossen kommt. So müßt ihr verfahren, damit ihr euch nicht verschuldet.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 19, 11, 'Dabei soll der Oberpriester Amarja für alle Angelegenheiten des HERRN und Sebadja, der Sohn Ismaels, der Fürst des Hauses Juda, für alle königlichen Angelegenheiten euer Vorgesetzter sein; und als Beisitzer stehen euch die Leviten zur Verfügung. Geht mit Vertrauen ans Werk! Der HERR wird mit den Rechtschaffenen sein.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 1, 'Später begab es sich, daß die Moabiter und Ammoniter und mit ihnen ein Teil der Mehuniter heranzogen, um Josaphat zu bekriegen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 2, 'Als nun Boten kamen und dem Josaphat die Meldung brachten: »Ein großer Heerhaufe rückt von jenseits des (Toten) Meeres aus Syrien gegen dich heran, und sie stehen schon in Hazezon-Thamar, das ist Engedi«:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 3, 'da erschrak Josaphat und faßte den festen Entschluß, sich an den HERRN zu wenden; und er ließ in ganz Juda ein Fasten ausrufen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 4, 'Als nun die Judäer zusammengekommen waren, um den HERRN um Hilfe anzuflehen, und sie sich auch aus allen Städten Judas versammelt hatten, um Hilfe vom HERRN zu erbitten,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 5, 'da trat Josaphat in der Volksgemeinde Judas und Jerusalems im Tempel des HERRN vor dem neuen Vorhofe auf');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 6, 'und betete: »HERR, du Gott unserer Väter, bist du nicht der Gott im Himmel und du nicht der Herrscher über alle Königreiche der Heiden? Ja, in deiner Hand ist Kraft und Stärke, und niemand vermag dir zu widerstehen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 7, 'Hast nicht du, unser Gott, einst die Bewohner dieses Landes vor deinem Volk Israel vertrieben und dies Land den Nachkommen Abrahams, deines Freundes, für ewige Zeit gegeben?');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 8, 'So haben sie sich denn darin niedergelassen und dir ein Heiligtum darin für deinen Namen gebaut, indem sie dachten:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 9, '›Wenn Unglück über uns hereinbricht, Krieg als Strafgericht oder die Pest oder Hungersnot, und wir dann vor dieses Haus und vor dich hintreten – denn dein Name wohnt in diesem Hause! – und wir in unserer Bedrängnis zu dir schreien, so wirst du uns erhören und erretten.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 10, 'Und nun, siehe, die Ammoniter und Moabiter und die Bewohner des Gebirges Seir, deren Land du einst die Israeliten, als sie aus Ägypten kamen, nicht hast betreten lassen, sondern an denen sie vorübergezogen sind, ohne sie zu vernichten:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 11, 'siehe, die wollen uns das jetzt entgelten lassen, indem sie kommen, um uns aus deinem Eigentum zu vertreiben, das du uns zum Besitz verliehen hast.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 12, 'O unser Gott, willst du nicht strafend gegen sie vorgehen? Denn wir sind zu schwach gegenüber dieser gewaltigen Übermacht, die gegen uns heranzieht, und wir wissen nicht, was wir tun sollen, sondern auf dich sind unsere Augen gerichtet!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 13, 'So standen die Judäer insgesamt vor dem HERRN da samt ihren kleinen Kindern, ihren Frauen und Söhnen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 14, 'Da wurde Jahasiel, der Sohn Sacharjas, des Sohnes Benajas, des Sohnes Jehiels, des Sohnes Matthanjas, der Levit aus den Nachkommen Asaphs, inmitten der Volksgemeinde vom Geist des HERRN ergriffen,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 15, 'so daß er ausrief: »Merkt auf, ihr Judäer alle und ihr Bewohner Jerusalems und du, König Josaphat! So spricht der HERR zu euch: ›Ihr braucht euch nicht zu fürchten und nicht zu erschrecken vor diesem großen Haufen; denn nicht eure Sache ist der Kampf, sondern die Sache Gottes!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 16, 'Zieht morgen gegen sie hinab: sie werden dann gerade die Anhöhe Ziz heraufkommen, und ihr werdet am Ende der Schlucht vor der Steppe Jeruel auf sie stoßen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 17, 'Ihr sollt aber dabei nicht selbst zu kämpfen haben; nein, nehmt nur Aufstellung, bleibt ruhig stehen und seht die Rettung an, die der HERR euch widerfahren läßt, Juda und Jerusalem! Fürchtet euch nicht und seid nicht verzagt! Zieht ihnen morgen entgegen: der HERR wird mit euch sein!‹«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 18, 'Da verneigte sich Josaphat mit dem Gesicht bis zur Erde, und alle Judäer samt den Bewohnern Jerusalems warfen sich vor dem HERRN nieder, um den HERRN anzubeten.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 19, 'Alsdann traten die Leviten auf, die zum Geschlecht der Kahathiten und der Korahiten gehörten, um mit überaus lauter Stimme Loblieder auf den HERRN, den Gott Israels, zu singen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 20, 'Als sie dann am andern Morgen in aller Frühe nach der Steppe Thekoa aufbrachen, trat Josaphat bei ihrem Auszuge auf und sagte: »Hört mich an, ihr Judäer und ihr Bewohner Jersualems! Vertraut auf den HERRN, euren Gott, so werdet ihr gesichert sein! Vertraut auf seine Propheten, so werdet ihr siegen!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 21, 'Sodann traf er Verabredungen mit dem Kriegsvolk und ließ Sänger antreten, die zu Ehren des HERRN im heiligen Schmuck Loblieder anstimmen mußten, während sie an der Spitze der gerüsteten Krieger einherzogen und sangen: »Danket dem HERRN, denn seine Güte währet ewiglich!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 22, 'Sobald sie aber mit dem Jubelruf und Lobgesang begonnen hatten, ließ der HERR feindselige Mächte gegen die Ammoniter, Moabiter und die Bewohner des Gebirges Seir, die gegen Juda heranzogen, in Wirksamkeit treten, so daß sie sich selbst aufrieben.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 23, 'Denn die Ammoniter und Moabiter erhoben sich gegen die Bewohner des Gebirges Seir, um sie niederzumachen und zu vertilgen; und als sie mit den Bewohnern von Seir fertig waren, half einer dem andern zur gegenseitigen Vernichtung.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 24, 'Als nun die Judäer auf der Berghöhe ankamen, von wo man die Steppe übersehen konnte, und sie nach dem Heerhaufen ausschauten, sahen sie nur Leichen am Boden liegen: keiner war entronnen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 25, 'Da kam Josaphat mit seinem Heer heran, um zu plündern, was jene bei sich gehabt hatten, und sie fanden bei ihnen eine Menge Vieh und Habseligkeiten, Kleider und kostbare Sachen, und erbeuteten davon so viel, daß sie es nicht fortschaffen konnten; drei Tage lang plünderten sie: so groß war die Beute.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 26, 'Am vierten Tage aber versammelten sie sich im ›Lobpreistal‹; dort nämlich lobpriesen sie den HERRN; daher führt jener Ort den Namen ›Lobpreistal‹ bis auf den heutigen Tag.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 27, 'Hierauf kehrte die ganze Mannschaft Judas und Jerusalems wieder um, mit Josaphat an ihrer Spitze, um voller Freude nach Jerusalem zurückzukehren; denn der HERR hatte sie an ihren Feinden Freude erleben lassen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 28, 'So zogen sie denn in Jerusalem ein unter Harfen-, Zither- und Trompetenklang, zum Tempel des HERRN hin.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 29, 'Auf alle Reiche der (benachbarten) Länder aber fiel ein Schrecken Gottes, als sie vernahmen, daß der HERR selbst mit den Feinden Israels gestritten hatte.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 30, 'Daher verlief die weitere Regierung Josaphats in Frieden, da sein Gott ihm Ruhe ringsumher verschafft hatte.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 31, 'So regierte denn Josaphat über Juda; fünfunddreißig Jahre war er beim Regierungsantritt alt, und fünfundzwanzig Jahre regierte er in Jerusalem; seine Mutter hieß Asuba und war eine Tochter Silhis.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 32, 'Er wandelte auf dem Wege seines Vaters Asa, ohne davon abzuweichen, so daß er tat, was dem HERRN wohlgefiel.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 33, 'Nur der Höhendienst wurde nicht beseitigt, und das Volk hatte sein Herz immer noch nicht fest auf den Gott seiner Väter gerichtet. –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 34, 'Die übrige Geschichte Josaphats aber, von Anfang bis zu Ende, findet sich bekanntlich bereits aufgezeichnet in der Geschichte Jehus, des Sohnes Hananis, die in das Buch der Könige von Israel aufgenommen ist.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 35, 'Später verbündete sich Josaphat, der König von Juda, mit dem König Ahasja von Israel, der in seinem Tun gottlos war;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 36, 'und zwar schloß er einen Bund mit ihm, um Schiffe zu bauen, die nach Tharsis fahren sollten; und sie ließen wirklich Schiffe in Ezjon-Geber bauen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 37, 'Aber Elieser, der Sohn Dodawas, aus Maresa, sprach gegen Josaphat die Weissagung aus: »Weil du dich in ein Bündnis mit Ahasja eingelassen hast, wird der HERR dein Machwerk zerstören!« So scheiterten denn die Schiffe und kamen nicht dazu, nach Tharsis zu fahren.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 21, 1, 'Als Josaphat sich dann zu seinen Vätern gelegt und man ihn bei seinen Vätern in der Davidsstadt begraben hatte, folgte ihm sein Sohn Joram in der Regierung nach.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 21, 2, 'Joram hatte Brüder, die Söhne Josaphats, nämlich Asarja, Jehiel, Sacharja, Asarja, Michael und Sephatja; alle diese waren Söhne des Königs Josaphat von Juda.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 21, 3, 'Ihr Vater hatte ihnen reiche Geschenke an Silber, Gold und Kostbarkeiten gegeben, dazu noch feste Städte in Juda; aber die Königswürde hatte er dem Joram verliehen, weil dieser sein erstgeborener Sohn war.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 21, 4, 'Als nun Joram die Regierung von seinem Vater übernommen und sich auf dem Throne befestigt hatte, ließ er alle seine Brüder und auch einige von den höchststehenden Männern Judas hinrichten.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 21, 5, 'Zweiundreißig Jahre war Joram alt, als er König wurde, und acht Jahre regierte er in Jerusalem.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 21, 6, 'Er wandelte auf dem Wege der Könige von Israel, wie es im Hause Ahabs durchweg der Fall war – er hatte sich nämlich mit einer Tochter Ahabs verheiratet –, und er tat, was dem HERRN mißfiel.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 21, 7, 'Aber der HERR wollte das Haus Davids nicht untergehen lassen um des Bundes willen, den er mit David geschlossen, und weil er ihm ja verheißen hatte, daß er ihm [und seinen Nachkommen] allezeit eine Leuchte vor seinem Angesicht verleihen wolle.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 21, 8, 'Unter seiner Regierung fielen die Edomiter von der Oberherrschaft Judas ab und setzten einen eigenen König über sich ein.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 21, 9, 'Da zog Joram mit seinen Heerführern und allen Kriegswagen hinüber; und als er nachts aufgebrochen war, schlug er die Edomiter, die ihn und die Befehlshaber der Wagen umzingelt hatten.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 21, 10, 'Aber die Edomiter machten sich von der Oberherrschaft Judas frei (und sind unabhängig geblieben) bis auf den heutigen Tag. Damals machte sich zu derselben Zeit auch Libna von seiner Oberherrschaft los, weil er vom HERRN, dem Gott seiner Väter, abgefallen war.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 21, 11, 'Auch er richtete den Höhendienst auf den Bergen Judas ein und verleitete die Bewohner Jerusalems zum Götzendienst und führte Juda vom rechten Wege ab.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 21, 12, 'Da gelangte ein Schreiben vom Propheten Elia an ihn, das so lautete: »So hat der HERR, der Gott deines Vaters David, gesprochen: ›Zur Strafe dafür, daß du nicht auf den Wegen deines Vaters Josaphat und auf den Wegen Asas, des Königs von Juda, gewandelt bist,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 21, 13, 'sondern nach der Weise der Könige von Israel wandelst und Juda und die Bewohner Jerusalems nach dem Vorgange des Hauses Ahabs zum Götzendienst verleitet hast, außerdem auch deine Brüder, das ganze Haus deines Vaters, sie, die doch besser waren als du, hast ermorden lassen:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 21, 14, 'siehe, so wird der HERR eine schwere Heimsuchung über dein Volk und deine Söhne, über deine Frauen und deinen gesamten Besitz bringen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 21, 15, 'Du selbst aber wirst in eine qualvolle Krankheit verfallen durch Erkrankung deiner Eingeweide, bis nach Jahr und Tag deine Eingeweide infolge der Krankheit heraustreten werden.‹«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 21, 16, 'So erweckte denn der HERR gegen Joram die Wut der Philister und der Araber, die neben den Kuschiten wohnten,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 21, 17, 'so daß sie gegen Juda heranzogen, in das Land einbrachen und alles Hab und Gut, das sich im Palast des Königs vorfand, dazu auch seine Söhne und Frauen wegschleppten, so daß ihm kein Sohn übrigblieb als Joahas, der jüngste von seinen Söhnen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 21, 18, 'Nach allem diesem aber suchte ihn der HERR mit einer unheilbaren Krankheit in seinen Eingeweiden heim.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 21, 19, 'Das dauerte ununterbrochen lange Tage an, bis ihm schließlich am Ende des zweiten Jahres die Eingeweide infolge der Krankheit heraustraten und er unter schlimmen Schmerzen starb. Sein Volk aber veranstaltete ihm zu Ehren keinen solchen Leichenbrand, wie seine Väter ihn erhalten hatten.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 21, 20, 'Im Alter von zweiunddreißig Jahren war er König geworden, und acht Jahre hatte er in Jerusalem regiert; er ging dahin, von niemand zurückersehnt, und man begrub ihn in der Davidsstadt, aber nicht in den Gräbern der Könige.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 22, 1, 'Darauf machten die Bewohner Jerusalems seinen jüngsten Sohn Ahasja an seiner Statt zum König; denn alle älteren Söhne hatte die Streifschar ermordet, die mit den Arabern in das Lager eingedrungen war, und so wurde Ahasja König, der Sohn des Königs Joram von Juda.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 22, 2, 'Im Alter von zweiundzwanzig Jahren kam er auf den Thron und regierte ein Jahr in Jerusalem; seine Mutter hieß Athalja und war die Enkelin Omris.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 22, 3, 'Auch er wandelte auf den Wegen des Hauses Ahabs; denn seine Mutter war für ihn eine Beraterin zu gottlosem Handeln.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 22, 4, 'So tat er denn, was dem HERRN mißfiel, wie das Haus Ahabs; denn dessen Angehörige waren nach seines Vaters Tode seine Ratgeber, zum Unheil für ihn.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 22, 5, 'Auf ihren Rat hin unternahm er auch mit Joram, dem Sohne des Königs Ahab von Israel, einen Feldzug gegen den König Hasael von Syrien nach Ramoth in Gilead. Als aber die Syrer Joram verwundet hatten,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 22, 6, 'kehrte dieser zurück, um sich in Jesreel von den Wunden heilen zu lassen, die man ihm bei Rama beigebracht hatte, als er gegen Hasael, den König von Syrien, zu Felde gezogen war. Darauf kam Ahasja, der König von Juda, der Sohn Jorams (von Juda), um Joram, den Sohn Ahabs, in Jesreel zu besuchen, weil dieser dort krank lag.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 22, 7, 'Das war aber von Gott zum Untergang Ahasjas verhängt, daß er sich zu Joram begab. Denn als er nach seiner Ankunft dort mit Joram gegen Jehu, den Sohn Nimsis, zog, den der HERR hatte salben lassen, damit er das Haus Ahabs ausrotte,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 22, 8, 'da begab es sich, als Jehu das Strafgericht am Hause Ahabs vollzog, daß er die Fürsten von Juda und die Neffen Ahasjas, die in Ahasjas Diensten standen, antraf und sie niederhauen ließ.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 22, 9, 'Als er dann auch nach Ahasja suchen ließ, der sich in Samaria versteckt hielt, und man ihn nach seiner Festnahme zu Jehu brachte, ließ dieser ihn töten. Doch begrub man ihn alsdann, weil man bedachte, daß er ein Sohn Josaphats sei, der sich zum HERRN mit ganzem Herzen gehalten hatte. Aber in der Familie Ahasjas war niemand mehr vorhanden, der fähig gewesen wäre, den Thron zu besteigen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 22, 10, 'Als aber Athalja, die Mutter Ahasjas, erfuhr, daß ihr Sohn tot war, machte sie sich daran, alle, die zur königlichen Familie des Hauses Juda gehörten, umzubringen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 22, 11, 'Aber Josabath, die Tochter des Königs Joram, nahm Joas, den Sohn Ahasjas, und schaffte ihn aus der Mitte der Königssöhne, die getötet werden sollten, heimlich beiseite, indem sie ihn samt seiner Amme in die Bettzeugkammer brachte. So verbarg ihn Josabath, die Tochter des Königs Joram, die Frau des Priesters Jojada – sie war nämlich die Schwester Ahasjas – vor Athalja, so daß diese ihn nicht ermorden konnte.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 22, 12, 'Er blieb dann sechs Jahre lang bei ihnen im Hause Gottes versteckt, während Athalja das Land regierte.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 23, 1, 'Im siebten Jahre aber faßte Jojada einen kühnen Entschluß und setzte sich mit den Befehlshabern der Hundertschaften, nämlich mit Asarja, dem Sohne Jerohams, Ismael, dem Sohne Johanans, Asarja, dem Sohne Obeds, Maaseja, dem Sohne Adajas, und Elisaphat, dem Sohne Sichris, ins Einvernehmen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 23, 2, 'Die zogen dann in Juda umher, brachten die Leviten in allen Städten Judas und die israelitischen Familienhäupter auf ihre Seite, so daß sie nach Jerusalem kamen,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 23, 3, 'wo die ganze Versammlung im Hause Gottes einen Bund mit dem (jungen) Könige schloß. Dabei richtete (Jojada) folgende Worte an sie: »Hier der Königssohn soll König sein, wie der HERR es betreffs der Nachkommen Davids verheißen hat.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 23, 4, 'Folgendermaßen müßt ihr nun zu Werke gehen: das eine Drittel von euch, den Priestern und Leviten, die ihr am Sabbat (aus dem Tempel) abzieht, soll den Dienst als Torhüter an den Schwellen versehen;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 23, 5, 'ein anderes Drittel soll den königlichen Palast, das letzte Drittel das Tor Jesod, das gesamte Kriegsvolk endlich die Vorhöfe des Tempels des HERRN besetzen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 23, 6, 'Den Tempel des HERRN aber darf niemand betreten außer den Priestern und den diensttuenden Leviten: diese dürfen hineingehen, denn sie sind geheiligt; das gesamte übrige Volk aber soll die Vorschrift des HERRN beobachten.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 23, 7, 'Die Leviten sollen sich dann rings um den König scharen, ein jeder mit seinen Waffen in der Hand, und wer in den Tempel eindringt, soll getötet werden; ihr müßt beständig um den König sein, wenn er (aus dem Tempel) auszieht und wenn er (in den Palast) einzieht!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 23, 8, 'Die Leviten und alle Judäer verfuhren dann genau nach der Anweisung des Priesters Jojada: jeder nahm seine Leute zu sich, sowohl die, welche am Sabbat abtraten, als auch die, welche am Sabbat antraten; denn der Priester Jojada hatte die (dienstfreien) Abteilungen nicht entlassen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 23, 9, 'Der Priester Jojada gab dann den Hauptleuten der Hundertschaften die Speere, Tartschen und Großschilde, die dem König David gehört hatten und die sich im Tempel Gottes befanden.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 23, 10, 'Nachdem er dann das ganze Kriegsvolk, und zwar einen jeden mit der Lanze in der Hand, von der Südseite des Tempels bis zur Nordseite des Tempels, bis an den Altar und wieder bis an den Tempel aufgestellt hatte,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 23, 11, 'führten sie den Königssohn heraus, legten ihm den Stirnreif um und gaben ihm die Gesetzesrolle in die Hand. So machten sie ihn zum König; und Jojada samt seinen Söhnen salbten ihn und riefen: »Es lebe der König!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 23, 12, 'Als nun Athalja das Geschrei des Volkes hörte, das herbeigeströmt war und dem Könige zujubelte, begab sie sich zu dem Volk in den Tempel des HERRN.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 23, 13, 'Dort sah sie den König auf seinem Standort am Eingang stehen und die Hauptleute und die Trompeter neben dem König, während das gesamte Volk des Landes voller Freude war und in die Trompeten stieß und die Sänger mit den Musikinstrumenten da waren und das Zeichen zum Lobpreis gaben. Da zerriß Athalja ihre Kleider und rief: »Verrat, Verrat!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 23, 14, 'Aber der Priester Jojada ließ die Hauptleute der Hundertschaften, die Befehlshaber des Heeres, vortreten und gab ihnen den Befehl: »Führt sie hinaus zwischen den Reihen hindurch! Und wer ihr folgt, soll mit dem Schwert niedergehauen werden!« Der Priester hatte nämlich befohlen: »Ihr dürft sie nicht im Tempel des HERRN töten!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 23, 15, 'Da legte man Hand an sie, und als sie am Eingang des Roßtores am königlichen Palast angelangt war, tötete man sie dort.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 23, 16, 'Darauf schloß Jojada zwischen dem HERRN und dem gesamten Volk und dem König das feierliche Abkommen, daß sie das Volk des HERRN sein wollten.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 23, 17, 'Darauf zog das ganze Volk zum Baalstempel und riß ihn nieder: seine Altäre und Götterbilder zertrümmerten sie vollständig und erschlugen den Baalspriester Matthan vor den Altären.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 23, 18, 'Alsdann besetzte Jojada die Ämter am Tempel des HERRN mit den Priestern und den Leviten, die David für den Tempeldienst in Klassen abgeteilt hatte, damit sie dem HERRN die Brandopfer, wie es im mosaischen Gesetz vorgeschrieben ist, unter Freudenrufen und mit Gesängen nach der Anordnung Davids darbrächten.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 23, 19, 'Auch stellte er die Torhüter an den Toren des Hauses des HERRN auf, damit kein irgendwie Unreiner hereinkäme.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 23, 20, 'Dann nahm er die Hauptleute sowie die Vornehmen und die Männer, die eine leitende Stellung im Volke einnahmen, aber auch das gewöhnliche Volk des Landes mit sich und führte den König aus dem Tempel des HERRN hinab, und als sie durch das obere Tor in das königliche Schloß gezogen waren, setzten sie den König auf den königlichen Thron.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 23, 21, 'Da war alles Volk im Lande voller Freude, und die Stadt blieb ruhig; Athalja aber hatte man mit dem Schwert getötet.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 24, 1, 'Joas war beim Regierungsantritt sieben Jahre alt und regierte vierzig Jahre in Jerusalem; seine Mutter hieß Zibja und stammte aus Beerseba.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 24, 2, 'Joas tat, was dem HERRN wohlgefiel, solange der Priester Jojada lebte.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 24, 3, 'Dieser verheiratete ihn mit zwei Frauen, und er wurde Vater von Söhnen und Töchtern.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 24, 4, 'Späterhin entschloß sich Joas, den Tempel des HERRN wiederherzustellen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 24, 5, 'Er ließ also die Priester und Leviten zusammenkommen und befahl ihnen: »Begebt euch in die Ortschaften Judas und sammelt Geld von allen Israeliten ein, um das Haus eures Gottes Jahr für Jahr auszubessern, und zwar müßt ihr die Sache beschleunigen!« Doch die Leviten hatten es damit nicht eilig.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 24, 6, 'Da ließ der König den Oberpriester Jojada kommen und sagte zu ihm: »Warum hast du die Leviten nicht dazu angehalten, aus Juda und Jerusalem die Abgabe einzubringen, die Mose, der Knecht des HERRN, der israelitischen Volksgemeinde für das Gesetzeszelt auferlegt hat?');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 24, 7, 'Denn die ruchlose Athalja und ihre Söhne haben das Gotteshaus verfallen lassen und haben auch alle heiligen Gegenstände, die zum Hause des HERRN gehörten, für die Baale verwandt!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 24, 8, 'So fertigte man denn auf Befehl des Königs eine Lade an und stellte sie draußen vor dem Tempeltor auf.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 24, 9, 'Sodann ließ man in Juda und Jerusalem öffentlich bekanntmachen, man solle dem HERRN die Abgabe entrichten, die Mose, der Knecht Gottes, den Israeliten in der Wüste auferlegt hatte.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 24, 10, 'Da freuten sich alle Vornehmen und das ganze Volk und brachten ihren Beitrag und warfen ihn in die Lade, bis sie voll war.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 24, 11, 'Sooft man nun die Lade durch die Leviten zu der königlichen Aufsichtsbehörde bringen ließ – wenn man nämlich sah, daß viel Geld darin war –, so gingen der Schreiber des Königs und der vom Oberpriester Beauftragte hin, leerten die Lade und brachten sie dann wieder an ihren Platz zurück. So tat man Tag für Tag und brachte eine Menge Geld zusammen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 24, 12, 'Der König und Jojada übergaben dieses dann denen, die als Werkmeister am Tempel des HERRN tätig waren, und diese stellten Steinmetzen und Zimmerleute an, um den Tempel des HERRN wiederherzustellen, dazu auch Eisen- und Kupferschmiede für die Ausbesserung des Tempels.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 24, 13, 'So waren denn die Werkmeister tätig, und unter ihrer Hand nahm die Ausführung der Arbeiten guten Fortgang, so daß sie das Gotteshaus in allen seinen Teilen wiederherstellten und in guten Stand setzten.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 24, 14, 'Als sie damit fertig waren, lieferten sie das noch übrige Geld an den König und an Jojada ab, und man ließ davon Geräte für den Tempel des HERRN anfertigen, Geräte für den Gottesdienst und für die Opfer, nämlich Schalen und andere goldene und silberne Geräte. Man brachte aber, solange Jojada lebte, Brandopfer regelmäßig im Tempel des HERRN dar.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 24, 15, 'Als Jojada aber alt und lebenssatt geworden war, starb er; er war bei seinem Tode hundertunddreißig Jahre alt.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 24, 16, 'Man begrub ihn in der Davidsstadt bei den Königen, weil er sich um Israel und auch um Gott und seinen Tempel verdient gemacht hatte.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 24, 17, 'Nach dem Tode Jojadas aber kamen die Fürsten Judas und warfen sich vor dem Könige nieder; da schenkte dieser ihnen Gehör.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 24, 18, 'So verließen sie denn das Haus des HERRN, des Gottes ihrer Väter, und verehrten die Standbilder der Aschera und die Götzenbilder. Da brach der Zorn Gottes über Juda und Jerusalem infolge dieser ihrer Verschuldung herein.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 24, 19, 'Er sandte Propheten unter sie, um sie zum HERRN zurückzuführen; diese redeten ihnen ins Gewissen, doch sie schenkten ihnen kein Gehör.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 24, 20, 'Da kam der Geist Gottes über Sacharja, den Sohn des Priesters Jojada, so daß er vor das Volk hintrat und zu ihnen sagte: »So hat Gott gesprochen: ›Warum übertretet ihr die Gebote des HERRN? Ihr bringt euch dadurch nur um euer Glück! Weil ihr den HERRN verlassen habt, hat er euch auch verlassen!‹«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 24, 21, 'Aber sie stifteten eine Verschwörung gegen ihn an und steinigten ihn auf Befehl des Königs im Vorhof des Tempels des HERRN.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 24, 22, 'So wenig gedachte der König Joas der Liebe, die Jojada, der Vater jenes (Sacharja), ihm erwiesen hatte, daß er der Mörder seines Sohnes wurde. Dieser aber rief sterbend aus: »Der HERR möge es sehen und wird es rächen!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 24, 23, 'Und noch vor Ablauf des Jahres zog das Heer der Syrer gegen ihn heran. Als diese in Juda und Jerusalem eingedrungen waren, ließen sie alle Obersten des Volkes grausam hinrichten und sandten alle Beute, die sie bei ihnen gemacht hatten, an den König von Damaskus.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 24, 24, 'Obgleich nämlich das syrische Heer bei seinem Einfall verhältnismäßig klein war, hatte der HERR sie doch über ein sehr zahlreiches Heer der Judäer siegen lassen, weil diese den HERRN, den Gott ihrer Väter, verlassen hatten; so vollzogen die Syrer das Strafgericht an Joas.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 24, 25, 'Als sie dann von ihm weggezogen waren – sie ließen ihn nämlich schwer erkrankt zurück –, verschworen sich seine Hofleute gegen ihn wegen seiner Bluttat am Sohne des Priesters Jojada und ermordeten ihn auf seinem Bette. So fand er seinen Tod; und man begrub ihn in der Davidsstadt, jedoch nicht in den Gräbern der Könige.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 24, 26, 'Folgende (Hofleute) hatten aber die Verschwörung gegen ihn angestiftet: Sabad, der Sohn der Ammonitin Simeath, und Josabad, der Sohn der Moabitin Simrith.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 24, 27, 'Was aber seine Söhne betrifft und die vielen Prophetensprüche gegen ihn und den Neubau des Hauses Gottes: das alles findet sich bereits aufgezeichnet in der erbaulichen Auslegung des Buches der Könige. Sein Sohn Amazja folgte ihm dann in der Regierung nach.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 25, 1, 'Im Alter von fünfundzwanzig Jahren kam Amazja auf den Thron, und neunundzwanzig Jahre regierte er in Jerusalem; seine Mutter hieß Joaddan und stammte aus Jerusalem.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 25, 2, 'Er tat, was dem HERRN wohlgefiel, jedoch nicht mit ungeteiltem Herzen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 25, 3, 'Sobald er nun die Herrschaft fest in Händen hatte, ließ er von seinen Dienern diejenigen hinrichten, die den König, seinen Vater, ermordet hatten.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 25, 4, 'Aber ihre Söhne ließ er nicht hinrichten, sondern verfuhr so, wie im Gesetz, im Buch Moses, geschrieben steht, wo der HERR ausdrücklich geboten hat: »Väter sollen nicht wegen einer Verschuldung ihrer Kinder sterben, und Kinder sollen nicht wegen einer Verschuldung ihrer Väter sterben, sondern ein jeder soll nur wegen seines eigenen Vergehens sterben!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 25, 5, 'Hierauf bot Amazja die Judäer auf und ließ sie, nach Familien geordnet, unter den Befehlshabern über die Tausendschaften und unter den Befehlshabern über die Hundertschaften antreten, ganz Juda und Benjamin. Als er sie dann von den Zwanzigjährigen an und darüber aufschreiben ließ, stellte er für sie eine Gesamtzahl von 300000 auserlesenen, felddienstfähigen Kriegern fest, die Speer und Schild führten.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 25, 6, 'Dazu nahm er aus Israel 100000 kriegstüchtige Leute für hundert Talente Silber in Sold.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 25, 7, 'Da kam aber ein Gottesmann zu ihm und sagte: »O König! Laß die israelitische Mannschaft nicht mit dir ziehen! Denn der HERR ist nicht mit Israel, mit allen diesen Leuten aus Ephraim.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 25, 8, 'Sondern ziehe du (allein) und entschlossen in den Kampf: Gott wird dich sonst vor dem Feinde zu Fall bringen; denn Gott ist stark genug, sowohl den Sieg zu verleihen als auch zu Fall zu bringen.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 25, 9, 'Als nun Amazja den Gottesmann fragte: »Was soll dann aber aus den hundert Talenten werden, die ich der israelitischen Heerschar bereits gegeben habe?«, antwortete der Gottesmann: »Der HERR vermag dir mehr als das zu geben!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 25, 10, 'Da sonderte Amazja die Abteilung, die aus Ephraim zu ihm gekommen war, von seinem Heere ab, damit sie wieder in ihre Heimat zögen. Da gerieten diese aber in heftigen Zorn gegen die Judäer und kehrten in glühendem Zorn in ihre Heimat zurück.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 25, 11, 'Amazja aber führte sein Heer voller Mut ins Feld und zog in das Salztal, wo er zehntausend Seiriten erschlug;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 25, 12, 'zehntausend andere aber, welche die Judäer lebendig gefangen genommen hatten, führten sie auf eine Felsenspitze und stürzten sie von der Felsenspitze hinab, so daß sie allesamt zerschmettert wurden.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 25, 13, 'Aber die Leute der Heeresabteilung, die Amazja zurückgeschickt hatte, so daß sie an dem Feldzuge nicht hatten teilnehmen dürfen, waren in die Ortschaften Judas von Samaria bis Beth-Horon eingefallen, hatten dreitausend Menschen in ihnen erschlagen und reiche Beute gemacht.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 25, 14, 'Als aber Amazja nach dem Siege über die Edomiter heimgekehrt war, stellte er die Götterbilder der Seiriten, die er mitgebracht hatte, als Götter für sich auf, betete sie an und brachte ihnen Opfer dar.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 25, 15, 'Da entbrannte der Zorn des HERRN gegen Amazja, und er sandte einen Propheten zu ihm, der zu ihm sagte: »Warum hältst du dich an die Götter jenes Volkes, die doch ihr eigenes Volk nicht vor deiner Hand haben retten können?«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 25, 16, 'Als er aber so zu ihm redete, entgegnete ihm Amazja: »Haben wir dich etwa zum Ratgeber des Königs bestellt? Unterlaß das! Warum willst du geschlagen werden?« Da hörte der Prophet auf, sagte aber noch: »Ich merke wohl, daß Gott dein Verderben beschlossen hat, weil du so gehandelt und auf meinen Rat nicht hast hören wollen!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 25, 17, 'Nachdem hierauf Amazja, der König von Juda, mit sich zu Rate gegangen war, schickte er Gesandte an den König Joas von Israel, den Sohn des Joahas, des Sohnes Jehus, und ließ ihm sagen: »Komm, wir wollen unsere Kräfte miteinander messen!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 25, 18, 'Da ließ Joas, der König von Israel, dem König Amazja von Juda durch eine Gesandtschaft antworten: »Der Dornstrauch auf dem Libanon sandte zur Zeder auf dem Libanon und ließ ihr sagen: ›Gib deine Tochter meinem Sohne zur Frau!‹ Aber da liefen die wilden Tiere auf dem Libanon über den Dornstrauch hin und zertraten ihn.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 25, 19, 'Du denkst, du habest ja die Edomiter geschlagen, und da reißt dein Mut dich fort, dir noch mehr Ruhm zu erwerben. Bleibe nur (ruhig) zu Hause: warum willst du das Unglück herausfordern, daß du zu Fall kommst und Juda mit dir?«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 25, 20, 'Aber Amazja wollte sich nicht warnen lassen; denn es war von Gott so gefügt, damit er sie den Feinden preisgäbe, weil sie sich den Göttern der Edomiter zugewandt hatten.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 25, 21, 'So zog denn Joas, der König von Israel, heran, und beide maßen ihre Kräfte miteinander, er und Amazja, der König von Juda, bei Beth-Semes, das zu Juda gehört.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 25, 22, 'Da wurden die Judäer von den Israeliten geschlagen, und ein jeder floh in seine Heimat.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 25, 23, 'Amazja aber, den König von Juda, den Sohn des Joas, des Sohnes des Joahas, nahm Joas, der König von Israel, in Beth-Semes gefangen und ließ, als er ihn nach Jerusalem gebracht hatte, ein Stück der Mauer Jerusalems vom Ephraimstor bis zum Ecktor auf einer Strecke von vierhundert Ellen niederreißen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 25, 24, 'Außerdem nahm er alles Gold und Silber sowie alle Geräte, die sich im Hause Gottes bei Obed-Edom vorfanden, und die Schätze des königlichen Palastes, dazu auch Geiseln, und kehrte nach Samaria zurück.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 25, 25, 'Amazja, der Sohn des Joas, der König von Juda, überlebte dann den König Joas von Israel, den Sohn des Joahas, noch fünfzehn Jahre. –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 25, 26, 'Die übrige Geschichte Amazjas aber, von Anfang bis zu Ende, findet sich bekanntlich bereits aufgezeichnet im Buch der Könige von Juda und Israel.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 25, 27, 'Seit der Zeit, da Amazja treulos vom HERRN abgefallen war, bestand in Jerusalem eine Verschwörung gegen ihn. Er floh nach Lachis, doch man sandte Leute nach Lachis hinter ihm her und ließ ihn dort ermorden.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 25, 28, 'Dann lud man ihn auf Rosse und begrub ihn bei seinen Vätern in der Davidsstadt.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 26, 1, 'Hierauf nahm das ganze Volk von Juda den Ussia, obgleich er erst sechzehn Jahre alt war, und machte ihn zum König als Nachfolger seines Vaters Amazja.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 26, 2, 'Er befestigte Eloth, das er an Juda zurückgebracht hatte, nachdem der König sich zu seinen Vätern gelegt hatte.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 26, 3, 'Im Alter von sechzehn Jahren bestieg Ussia den Thron, und zweiundfünfzig Jahre regierte er in Jerusalem; seine Mutter hieß Jecholja und stammte aus Jerusalem.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 26, 4, 'Er tat, was dem HERRN wohlgefiel, ganz wie sein Vater Amazja getan hatte.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 26, 5, 'Er war darauf bedacht, sich an Gott zu halten, solange Sacharja lebte, der ihn zur Furcht Gottes anleitete; und solange er den HERRN suchte, gab Gott ihm Glück.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 26, 6, 'Denn als er einen Feldzug gegen die Philister unternahm, riß er die Mauern der Städte Gath, Jabne und Asdod nieder und legte feste Plätze um Asdod her und im (übrigen) Philisterlande an.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 26, 7, 'So half Gott ihm im Kampf gegen die Philister und ebenso gegen die Araber, die in Gur-Baal wohnten, und gegen die Mehuniter.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 26, 8, 'Auch die Ammoniter mußten Ussia Abgaben entrichten, und sein Ruhm verbreitete sich bis nach Ägypten hin; denn er war überaus mächtig geworden.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 26, 9, 'Auch baute Ussia in Jerusalem Türme am Ecktor, am Taltor und am Winkel und befestigte sie.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 26, 10, 'Weiter ließ er in der Steppe Türme erbauen und zahlreiche Zisternen anlegen; denn er besaß große Viehherden sowohl in der Niederung als auch in der Ebene, dazu Ackerleute und Weingärtner im Gebirge und im Gefilde; denn er war ein Freund der Landwirtschaft.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 26, 11, 'Ussia hatte aber auch ein kriegstüchtiges Heer, das, in Scharen gegliedert, zu Felde zog, soviele ihrer durch den Schreiber Jehiel und den Amtmann Maaseja unter der Aufsicht Hananjas, eines der Heerführer des Königs, gemustert worden waren.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 26, 12, 'Die Gesamtzahl der Familienhäupter der kriegstüchtigen Mannschaft betrug 2600,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 26, 13, 'unter deren Befehl eine Heeresmacht von 307500 kriegstüchtigen, vollkräftigen Männern stand, die dem König gegen die Feinde zu Gebote standen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 26, 14, 'Für dieses ganze Heer beschaffte Ussia Schilde, Lanzen, Helme, Panzer, Bogen und Schleudersteine.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 26, 15, 'Auch ließ er in Jerusalem kunstvoll gebaute Maschinen anfertigen, die auf den Türmen und Zinnen aufgestellt werden sollten, um mit ihnen Pfeile und große Steine zu schleudern. So drang sein Ruhm in weite Ferne; denn er erlangte wunderbare Erfolge, bis er (überaus) mächtig geworden war.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 26, 16, 'Als er aber zu Macht gelangt war, überhob sich sein Sinn zu gottlosem Handeln, so daß er sich gegen den HERRN, seinen Gott, versündigte, indem er in den Tempel des HERRN ging, um auf dem Räucheraltar Rauchopfer darzubringen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 26, 17, 'Da kam der Priester Asarja hinter ihm her, begleitet von achtzig Priestern des HERRN, vortrefflichen Männern;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 26, 18, 'die traten dem König Ussia mit den Worten entgegen: »Nicht dir, Ussia, steht das Recht zu, dem HERRN Rauchopfer darzubringen, sondern nur den Priestern, den Nachkommen Aarons, die zu diesem Dienst geweiht sind. Verlaß das Heiligtum, denn du hast dich vergangen, und das bringt dir vor Gott, dem HERRN, keine Ehre!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 26, 19, 'Da geriet Ussia in Zorn, während er noch das Räucherfaß in der Hand hielt, um zu räuchern; als er aber seinen Zorn gegen die Priester ausließ, kam der Aussatz an seiner Stirn vor den Augen der Priester im Tempel des HERRN neben dem Räucheraltar zum Ausbruch.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 26, 20, 'Als sich nun der Oberpriester Asarja und alle Priester zu ihm hinwandten, da war er in der Tat an der Stirn vom Aussatz befallen. Da brachten sie ihn schleunigst von dort weg, und auch er selbst beeilte sich hinauszukommen, weil der HERR ihn geschlagen hatte.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 26, 21, 'So war denn der König Ussia aussätzig bis zu seinem Todestage und wohnte als Aussätziger in einem Hause für sich; denn er war vom Tempel des HERRN ausgeschlossen. Jotham aber, sein Sohn, waltete im königlichen Hause als Familienhaupt und versah die Regierungsgeschäfte für das Land.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 26, 22, 'Die übrige Geschichte Ussias aber, von Anfang bis zu Ende, hat der Prophet Jesaja, der Sohn des Amoz, geschrieben.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 26, 23, 'Als Ussia sich dann zu seinen Vätern gelegt hatte, begrub man ihn [bei seinen Vätern] auf dem (freien) Felde bei der Begräbnisstätte der Könige; denn man sagte: »Er ist aussätzig!« Sein Sohn Jotham folgte ihm in der Regierung nach.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 27, 1, 'Im Alter von fündundzwanzig Jahren wurde Jotham König und regierte sechzehn Jahre in Jerusalem; seine Mutter hieß Jerusa und war eine Tochter Zadoks.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 27, 2, 'Er tat, was dem HERRN wohlgefiel, ganz wie sein Vater Ussia getan hatte; nur drang er nicht in den Tempel des HERRN ein; das Volk aber verhielt sich immer noch gottlos.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 27, 3, 'Er erbaute das obere Tor am Tempel des HERRN und ließ auch viel an der Mauer des Ophel bauen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 27, 4, 'Weiter befestigte er Ortschaften im Berglande Juda und legte in den waldigen Gegenden Burgen und Türme an.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 27, 5, 'Er führte auch Krieg mit dem König der Ammoniter und besiegte sie, so daß die Ammoniter ihm in jenem Jahre eine Abgabe von hundert Talenten Silber, zehntausend Kor Weizen und zehntausend Kor Gerste entrichteten. Dieselbe Abgabe mußten ihm die Ammoniter auch noch im zweiten und dritten Jahre entrichten.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 27, 6, 'So wurde Jotham immer mächtiger, weil er sich in seiner Lebensführung genau nach dem Willen des HERRN, seines Gottes, richtete.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 27, 7, 'Die übrige Geschichte Jothams aber sowie alle seine Kriege und Unternehmungen finden sich bereits im Buch der Könige von Israel und Juda aufgezeichnet.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 27, 8, 'Im Alter von fünfundzwanzig Jahren war er zur Regierung gekommen, und sechzehn Jahre hat er in Jerusalem regiert.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 27, 9, 'Als Jotham sich dann zu seinen Vätern gelegt und man ihn in der Davidsstadt begraben hatte, folgte ihm sein Sohn Ahas in der Regierung nach.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 28, 1, 'Im Alter von zwanzig Jahren wurde Ahas König und regierte sechzehn Jahre in Jerusalem. Er tat nicht, was dem HERRN, seinem Gott, wohlgefiel, wie sein Ahnherr David getan hatte,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 28, 2, 'sondern er wandelte auf den Wegen der Könige von Israel, ja er ließ sogar für die Baale gegossene Bilder anfertigen');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 28, 3, 'und brachte selbst Rauchopfer im Tal Ben-Hinnom dar und verbrannte seine Söhne als Opfer nach der greulichen Sitte der heidnischen Völker, die der HERR vor den Israeliten vertrieben hatte.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 28, 4, 'Er brachte auch Schlacht- und Rauchopfer auf den Höhen und Hügeln und unter jedem dichtbelaubten Baume dar.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 28, 5, 'So gab ihn denn der HERR, sein Gott, der Gewalt des Königs der Syrer preis, die ihn besiegten und eine große Menge seiner Leute als Gefangene wegführten und sie nach Damaskus brachten. Ebenso wurde er auch der Gewalt des Königs von Israel preisgegeben, der ihm eine schwere Niederlage beibrachte;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 28, 6, 'denn Pekah, der Sohn Remaljas, ließ in Juda an einem Tage 120000 Mann niederhauen, lauter tüchtige Krieger, weil sie den HERRN, den Gott ihrer Väter, verlassen hatten.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 28, 7, 'Außerdem erschlug Sichri, ein tapferer ephraimitischer Krieger, den königlichen Prinzen Maaseja, den Palastvorsteher Asrikam und Elkana, den höchststehenden Mann im Reiche nächst dem König.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 28, 8, 'Dann schleppten die Israeliten von ihren Volksgenossen 200000 Frauen, Knaben und Mädchen in die Gefangenschaft weg; dazu nahmen sie ihnen gewaltige Beute ab, die sie nach Samaria brachten.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 28, 9, 'Dort lebte aber ein Prophet des HERRN, namens Oded; der ging dem Heere, das nach Samaria heimkehrte, entgegen und sagte zu ihnen: »Bedenket wohl: nur deshalb, weil der HERR, der Gott eurer Väter, gegen die Judäer erzürnt ist, hat er sie euch in die Hände fallen lassen; ihr aber habt ein Blutbad unter ihnen angerichtet mit einer Wut, die bis an den Himmel reicht!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 28, 10, 'Und nun beabsichtigt ihr, diese Kinder Judas und Jerusalems in der Knechtschaft bei euch zu Sklaven und Sklavinnen zu erniedrigen! Aber habt ihr selbst keine Verschuldungen gegen den HERRN, euren Gott, auf euch lasten?');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 28, 11, 'So hört denn jetzt auf mich und schickt die Gefangenen wieder zurück, die ihr euren Brüdern geraubt habt: sonst bricht das schwere Zorngericht des HERRN über euch herein!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 28, 12, 'Da traten von den Häuptern der Ephraimiten einige Männer, nämlich Asarja, der Sohn Johanans, Berechja, der Sohn Mesillemoths, Hiskia, der Sohn Sallums, und Amasa, der Sohn Hadlais, vor die vom Feldzug Heimkehrenden hin');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 28, 13, 'und sagten zu ihnen: »Ihr dürft die Gefangenen nicht hierher bringen; denn dadurch würdet ihr eine Verschuldung gegen den HERRN auf uns laden! Ihr beabsichtigt ja, zu unseren Sünden und Verschuldungen noch neue hinzuzufügen, und doch ist unsere Schuld schon groß genug, und ein schweres Zorngericht droht über Israel hereinzubrechen!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 28, 14, 'Da gaben die Krieger die Gefangenen und die Beute in Gegenwart der Fürsten und der ganzen Volksgemeinde frei;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 28, 15, 'und die Männer, die mit Namen oben angegeben sind, machten sich daran, sich der Gefangenen anzunehmen: sie versahen alle, die unter ihnen ungenügend bekleidet waren, mit Kleidern aus der Beute; und nachdem sie sie mit Kleidung und Schuhen versehen hatten, gaben sie ihnen zu essen und zu trinken und Öl, um sich zu salben; hierauf setzten sie alle, die (zum Gehen) zu schwach waren, auf Esel und brachten sie nach der Palmenstadt Jericho in die Nähe ihrer Volksgenossen; alsdann kehrten sie nach Samaria zurück.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 28, 16, 'Zu jener Zeit schickte der König Ahas eine Gesandtschaft an den König von Assyrien, daß er ihm zu Hilfe kommen möchte.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 28, 17, 'Denn auch die Edomiter zogen aufs neue heran, besiegten die Judäer und schleppten Gefangene weg.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 28, 18, 'Dazu unternahmen die Philister Plünderungszüge gegen die Städte in der Niederung und im Südlande von Juda und eroberten Beth-Semes, Ajjalon, Gederoth, Socho nebst den zugehörigen Ortschaften, dazu Thimna nebst den zugehörigen Ortschaften und Gimso nebst den zugehörigen Ortschaften und setzten sich darin fest.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 28, 19, 'Denn der HERR demütigte Juda um des Königs Ahas von Juda willen, weil er es zügellos in Juda getrieben und ganz treulos gegen den HERRN gehandelt hatte.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 28, 20, 'Da rückte Thilgath-Pilneser, der König von Assyrien, gegen ihn heran und bedrängte ihn, statt ihm Beistand zu leisten;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 28, 21, 'denn Ahas hatte den Tempel des HERRN und den königlichen Palast und die Fürsten ausgeplündert und alles dem König von Assyrien gegeben, ohne daß dies ihm etwas genützt hätte.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 28, 22, 'Doch (selbst) während der Zeit seiner Bedrängnis versündigte er, der König Ahas, sich durch Treulosigkeit noch mehr gegen den HERRN.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 28, 23, 'Er opferte nämlich den Göttern von Damaskus, die ihn doch geschlagen hatten, und dachte dabei: »Weil die Götter der Könige von Syrien ihnen geholfen haben, so will ich ihnen opfern, damit sie auch mir helfen«; aber sie dienten ihm nur dazu, ihn selbst und ganz Israel ins Unglück zu stürzen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 28, 24, 'Auch ließ Ahas die Geräte des Hauses Gottes zusammenbringen und sie dann zerschlagen, verschloß hierauf die Tore des Tempels des HERRN und legte sich Altäre an allen Ecken in Jerusalem an.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 28, 25, 'Ebenso richtete er in jeder einzelnen Ortschaft von Juda Opferhöhen ein, um anderen Göttern Rauchopfer darzubringen, und reizte so den HERRN, den Gott seiner Väter, zum Zorn.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 28, 26, 'Seine übrige Geschichte aber und alle seine Unternehmungen, die früheren und die späteren, finden sich bereits aufgezeichnet im Buch der Könige von Juda und Israel.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 28, 27, 'Als Ahas sich dann zu seinen Vätern gelegt hatte, begrub man ihn in der Stadt, in Jerusalem; denn man setzte ihn nicht in den Gräbern der israelitischen Könige bei. Sein Sohn Hiskia aber folgte ihm in der Regierung nach.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 1, 'Hiskia wurde im Alter von fünfundzwanzig Jahren König und regierte neunundzwanzig Jahre in Jerusalem; seine Mutter hieß Abija und war eine Tochter Sacharjas.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 2, 'Er tat, was dem HERRN wohlgefiel, ganz wie sein Ahnherr David getan hatte.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 3, 'Gleich im ersten Monat des ersten Jahres seiner Regierung öffnete er die Tore des Tempels des HERRN und setzte sie wieder instand.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 4, 'Sodann ließ er die Priester und die Leviten kommen, versammelte sie auf dem freien Platz gegen Osten');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 5, 'und hielt folgende Ansprache an sie: »Hört mich an, ihr Nachkommen Levis! Heiligt euch jetzt und heiligt auch das Haus des HERRN, des Gottes eurer Väter, indem ihr den Schmutz (des Götzendienstes) aus dem Heiligtum wegschafft!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 6, 'Denn unsere Väter haben treulos gehandelt und haben getan, was dem HERRN, unserm Gott, mißfällt, indem sie von ihm abgefallen sind und ihre Blicke von der Wohnstätte des HERRN abgewandt und (ihr) den Rücken zugekehrt haben.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 7, 'Sie haben sogar die Türen der Vorhalle geschlossen und die Lampen ausgelöscht, haben kein Räucherwerk mehr verbrannt und dem Gott Israels kein Brandopfer mehr im Heiligtum dargebracht.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 8, 'Daher ist auch der Zorn des HERRN über Juda und Jerusalem hereingebrochen, und er hat sie zu einem abschreckenden Beispiel, zu einem Gegenstand des Entsetzens und der höchsten Verachtung gemacht, wie ihr es mit eigenen Augen seht.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 9, 'Ihr wißt ja: unsere Väter sind eben deswegen durch das Schwert gefallen, und unsere Söhne und unsere Töchter und Frauen befinden sich in der Gefangenschaft.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 10, 'Doch jetzt bin ich entschlossen, einen Bund mit dem HERRN, dem Gott Israels, zu schließen, damit die Glut seines Zornes sich von uns abwendet.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 11, 'So zeigt euch nun nicht lässig, meine Söhne! Denn euch hat der HERR dazu ausersehen, daß ihr vor ihm stehen sollt, um seinen Dienst zu verrichten; seine Diener sollt ihr sein und ihm Schlacht- und Rauchopfer darbringen.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 12, 'Da machten sich denn die Leviten ans Werk, nämlich Mahath, der Sohn Amasais, und Joel, der Sohn Asarjas, von den Nachkommen der Kahathiten; und von den Nachkommen Meraris: Kis, der Sohn Abdis, und Asarja, der Sohn Jehallelels; und von den Gersoniten: Joah, der Sohn Simmas, und Eden, der Sohn Joahs;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 13, 'und von den Nachkommen Elizaphans: Simri und Jegiel; und von den Nachkommen Asaphs: Sacharja und Matthanja;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 14, 'und von den Nachkommen Hemans: Jehiel und Simei; und von den Nachkommen Jeduthuns: Semaja und Ussiel.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 15, 'Diese versammelten ihre Stammesgenossen, und nachdem sie sich geheiligt hatten, machten sie sich nach dem Befehl des Königs daran, den Tempel des HERRN nach den Weisungen des HERRN zu reinigen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 16, 'Die Priester begaben sich also in das Innere des Tempels des HERRN, um es zu reinigen, und schafften alles Unreine, das sie im Tempel vorfanden, in den Vorhof am Hause des HERRN hinaus, wo die Leviten es in Empfang nahmen, um es an den Bach Kidron hinauszubringen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 17, 'Am ersten Tage des ersten Monats fingen sie mit der Reinigung an, und am achten Tage des Monats waren sie bis an die Vorhalle des Tempels gekommen; acht Tage verwandten sie dann noch darauf, den Tempel in heiligen Zustand zu setzen; und am sechzehnten Tage des ersten Monats waren sie fertig.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 18, 'Da begaben sie sich in den Palast des Königs Hiskia und meldeten: »Wir haben das ganze Haus des HERRN gereinigt, dazu auch den Brandopferaltar mit all seinen Geräten und den Schaubrottisch mit all seinen Geräten;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 19, 'auch alle Geräte, die der König Ahas während seiner Regierung infolge seines Abfalls entweiht hat, haben wir wieder hergerichtet und geheiligt: sie stehen jetzt vor dem Altar des HERRN!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 20, 'Da ließ der König Hiskia am andern Morgen früh die Stadtobersten zusammenkommen und ging zum Tempel des HERRN hinauf.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 21, 'Sie ließen dann sieben junge Stiere, sieben Widder, sieben Schafe und sieben Ziegenböcke zum Sündopfer für das Königshaus, für das Heiligtum und für Juda herbeibringen, und er befahl den Nachkommen Aarons, den Priestern, sie auf dem Altar des HERRN zu opfern.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 22, 'Da schlachteten sie die Rinder, und die Priester fingen das Blut auf und sprengten es an den Altar; sodann schlachteten sie die Widder und sprengten das Blut an den Altar; alsdann schlachteten sie die Schafe und sprengten das Blut an den Altar.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 23, 'Schließlich brachten sie die Böcke zum Sündopfer vor den König und vor die versammelte Volksgemeinde, und nachdem diese ihre Hände fest auf sie gelegt hatten,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 24, 'schlachteten die Priester sie und taten ihr Blut als Sündopfer an den Altar, um Sühne für ganz Israel zu erwirken; denn für ganz Israel hatte der König das Brandopfer und das Sündopfer angeordnet.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 25, 'Dabei hatte er die Leviten am Tempelhause des HERRN mit Zimbeln, Harfen und Zithern Aufstellung nehmen lassen, wie David und der königliche Seher Gad und der Prophet Nathan es angeordnet hatten; denn vom HERRN war die Anordnung ausgegangen durch den Mund seiner Propheten.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 26, 'So hatten sich also die Leviten mit den Musikinstrumenten Davids und die Priester mit den Trompeten aufgestellt.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 27, 'Da befahl Hiskia, das Brandopfer auf dem Altar darzubringen; und sobald das Brandopfer begann, fing auch der Gesang zu Ehren des HERRN an, und die Trompeten setzten ein, und zwar unter Begleitung der Instrumente Davids, des Königs von Israel.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 28, 'Die ganze Versammlung aber warf sich nieder, während die Lieder erklangen und die Trompeten schmetterten; das alles dauerte, bis das Brandopfer vollendet war.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 29, 'Als man aber mit dem Opfer zu Ende war, knieten der König und alle, die bei ihm anwesend waren, zum Gebet nieder.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 30, 'Hierauf geboten der König Hiskia und die Fürsten den Leviten, zu Ehren des HERRN den Lobgesang anzustimmen mit den Worten Davids und des Sehers Asaph. Da trugen sie denn das Loblied mit Freuden vor, verneigten sich und warfen sich nieder.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 31, 'Hierauf nahm Hiskia das Wort und sagte: »So habt ihr euch denn jetzt dem HERRN geweiht: tretet nun herzu und bringt Schlacht- und Dankopfer zum Tempel des HERRN!« Da brachten die Versammelten Schlacht- und Dankopfer dar, und jeder, der sich dazu getrieben fühlte, brachte Brandopfer.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 32, 'Die Zahl der Brandopfer, welche die Versammelten darbrachten, betrug 70 Rinder, 100 Widder, 200 Schafe, diese alle als Brandopfer für den HERRN;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 33, 'außerdem weihte man als Heilsopfer 600 Rinder und 3000 Stück Kleinvieh.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 34, 'Weil nun die Priester zu wenige waren, so daß sie nicht allen Brandopfern die Haut abzuziehen vermochten, halfen ihnen ihre Stammesgenossen, die Leviten, bis die Arbeit zu Ende gebracht war und bis die Priester sich geheiligt hatten; die Leviten waren nämlich mit größerem Eifer darauf bedacht gewesen, sich zu heiligen, als die Priester.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 35, 'Auch Brandopfer waren in Menge zu besorgen nebst den Fettstücken der Heilsopfer und nebst den zu den Brandopfern gehörenden Trankopfern. So war denn der Dienst am Tempel des HERRN wiederhergestellt;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 36, 'Hiskia aber und das ganze Volk freuten sich über das Glück, das der HERR dem Volke hatte zuteil werden lassen; denn die Sache war außerordentlich schnell vor sich gegangen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 30, 1, 'Hierauf sandte Hiskia Boten an ganz Israel und Juda und schrieb auch Briefe an Ephraim und Manasse, sie möchten zum Hause des HERRN in Jerusalem kommen, um dem HERRN, dem Gott Israels, eine Passahfeier zu veranstalten.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 30, 2, 'Der König und seine Fürsten nebst der ganzen Volksgemeinde in Jerusalem hatten sich aber entschlossen, das Passah erst im zweiten Monat zu feiern;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 30, 3, 'denn sie konnten es damals nicht sogleich feiern, weil die Priester sich noch nicht in hinreichender Anzahl dazu geheiligt hatten und das Volk noch nicht in Jerusalem versammelt war.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 30, 4, 'Als dieser Beschluß die Zustimmung des Königs und der ganzen Volksgemeinde gefunden hatte,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 30, 5, 'faßten sie weiter den Beschluß, einen Aufruf in ganz Israel von Beerseba bis Dan ergehen zu lassen, man möge kommen, um dem HERRN, dem Gott Israels, das Passah in Jerusalem zu feiern; denn man hatte es seit langer Zeit bei so zahlreicher Beteiligung nicht so gefeiert, wie es vorgeschrieben war.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 30, 6, 'So zogen denn die Eilboten mit den Briefen von der Hand des Königs und seiner höchsten Beamten in ganz Israel und Juda umher und verkündeten nach dem Befehle des Königs: »Ihr Israeliten! Kehrt zum HERRN, dem Gott Abrahams, Isaaks und Israels, zurück, damit er sich denen wieder zuwendet, die der Gewalt der Könige von Assyrien entronnen und euch noch übriggeblieben sind;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 30, 7, 'und macht es nicht wie eure Väter und eure Volksgenossen, die treulos gegen den HERRN, den Gott ihrer Väter, gehandelt haben, so daß er sie der Vernichtung preisgegeben hat, wie ihr es seht!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 30, 8, 'Zeigt euch also jetzt nicht halsstarrig wie eure Väter, sondern reicht dem HERRN die Hand und kommt zu seinem Heiligtum, das er auf ewig geheiligt hat, und dient dem HERRN, eurem Gott, damit die Glut seines Zornes sich von euch abwendet!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 30, 9, 'Denn wenn ihr zum HERRN umkehrt, so werden eure Brüder und eure Kinder Erbarmen bei denen finden, die sie in die Gefangenschaft weggeführt haben, so daß sie in dieses Land zurückkehren können; denn der HERR, euer Gott, ist gnädig und barmherzig und wird sein Angesicht nicht von euch wegwenden, wenn ihr zu ihm zurückkehrt!« –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 30, 10, 'So zogen denn die Eilboten von Stadt zu Stadt durch das Land Ephraim und Manasse und bis nach Sebulon, aber man verspottete und verhöhnte sie;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 30, 11, 'nur einige Männer aus Asser, Manasse und Sebulon gingen in sich und kamen nach Jerusalem.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 30, 12, 'Auch in Juda zeigte sich die Einwirkung Gottes dadurch, daß er ihnen einen einmütigen Sinn verlieh, um der Aufforderung des Königs und seiner obersten Beamten nach der Weisung des HERRN nachzukommen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 30, 13, 'So versammelte sich denn eine große Volksmenge in Jerusalem, um das Fest der ungesäuerten Brote im zweiten Monat zu feiern, eine überaus zahlreiche Volksgemeinde.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 30, 14, 'Sie machten sich zunächst daran, die Altäre, die sich in Jerusalem befanden, wegzuschaffen; ebenso beseitigten sie alle Rauchopferstätten und warfen sie in den Bach Kidron.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 30, 15, 'Sodann schlachteten sie das Passah am vierzehnten Tage des zweiten Monats; denn die Priester und die Leviten fühlten sich beschämt und hatten sich geheiligt und brachten nun Brandopfer zum Tempel des HERRN;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 30, 16, 'sie versahen ihre Amtsgeschäfte pflichtgemäß, wie es ihnen nach dem Gesetz Moses, des Mannes Gottes, oblag: die Priester sprengten das Blut, das sie aus der Hand der Leviten genommen hatten.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 30, 17, 'Es gab nämlich viele unter den Versammelten, die sich nicht geheiligt hatten; daher besorgten die Leviten das Schlachten der Passahlämmer für einen jeden, der nicht rein war, um sie dem HERRN zu weihen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 30, 18, 'Ja, die Mehrzahl des Volkes, viele aus Ephraim und Manasse, Issaschar und Sebulon, hatten sich nicht gereinigt, sondern aßen das Passah nicht in der vorgeschriebenen Weise. Doch Hiskia hatte für sie gebetet mit den Worten: »Der HERR, der Gütige, wolle einem jeden verzeihen,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 30, 19, 'der ernstlich darauf bedacht ist, Gott den HERRN, den Gott seiner Väter, zu suchen, wenn auch nicht gemäß der für das Heiligtum erforderlichen Reinheit!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 30, 20, 'Und der HERR erhörte Hiskia und ließ das Volk unversehrt.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 30, 21, 'So feierten denn die Israeliten, die sich in Jerusalem eingefunden hatten, das Fest der ungesäuerten Brote sieben Tage lang mit großer Freude, und die Leviten und die Priester sangen dem HERRN Tag für Tag Loblieder unter Begleitung der Musikinstrumente.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 30, 22, 'Dabei richtete Hiskia freundliche Worte an alle Leviten, welche richtiges Verständnis für den Dienst des HERRN bewiesen; und man hielt Festmahle die sieben Tage hindurch, indem sie Heilsopfer darbrachten und den HERRN, den Gott ihrer Väter, priesen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 30, 23, 'Darauf entschloß sich die ganze Volksgemeinde, noch weitere sieben Tage zu feiern; und so begingen sie noch sieben Tage lang ein Freudenfest.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 30, 24, 'Denn Hiskia, der König von Juda, hatte der Volksgemeinde tausend Stiere und siebentausend Stück Kleinvieh als Spende überwiesen, und die Fürsten hatten gleichfalls tausend Stiere und zehntausend Stück Kleinvieh gespendet; und die Priester hatten sich in großer Zahl geheiligt.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 30, 25, 'So überließ sich denn die ganze Volksgemeinde Judas der Fröhlichkeit und ebenso die Priester und die Leviten und die ganze Menge derer, die aus Israel gekommen waren, auch die Fremdlinge, die aus den verschiedensten Gegenden Israels gekommen waren oder in Juda wohnten.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 30, 26, 'Und es herrschte große Freude in Jerusalem; denn seit den Tagen Salomos, des Sohnes Davids, des Königs von Israel, war etwas Derartiges in Jerusalem nicht vorgekommen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 30, 27, 'Die levitischen Priester aber erhoben sich und segneten das Volk, und ihre laute Bitte fand Erhörung: ihr Gebet drang zu seiner heiligen Wohnung, in den Himmel.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 31, 1, 'Als nun alle diese (Festlichkeiten) zu Ende waren, zogen sämtliche Israeliten, die sich dazu eingefunden hatten, in die Ortschaften Judas hinaus, zertrümmerten die Malsteine, zerschlugen die Standbilder der Aschera und zerstörten die Opferhöhen und die Altäre in ganz Juda und Benjamin sowie in Ephraim und Manasse, bis sie sie gänzlich vernichtet hatten; darauf kehrten alle Israeliten in ihre Ortschaften zurück, ein jeder zu seinem Besitztum.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 31, 2, 'Hierauf bestellte Hiskia die verschiedenen Abteilungen der Priester und der Leviten, jeden einzelnen von den Priestern und den Leviten nach Maßgabe des ihm obliegenden Dienstes bei den Brandopfern und bei den Heilsopfern, um in den Toren des Lagers des HERRN Dienst zu tun und Danklieder oder Lobgesänge vorzutragen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 31, 3, 'Der Beitrag des Königs aus seinem Vermögen war für die Brandopfer bestimmt, und zwar für die Brandopfer sowohl an jedem Morgen und Abend als auch an den Sabbaten und Neumonden und an den Festen, wie es im Gesetz des HERRN vorgeschrieben ist.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 31, 4, 'Sodann machte er es dem Volke, das in Jerusalem wohnte, zur Pflicht, den Priestern und den Leviten die ihnen gebührenden Abgaben zukommen zu lassen, damit sie am Gesetz des HERRN festhalten könnten.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 31, 5, 'Sobald nun dieser Befehl bekannt wurde, brachten die Israeliten reichlich die Erstlinge vom Getreide, Most, Öl und Honig sowie von allen (übrigen) Erzeugnissen des Feldes dar und lieferten den Zehnten von allem in Menge ab;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 31, 6, 'und die Israeliten und Judäer, die in den Ortschaften Judas wohnten, brachten ebenfalls den Zehnten vom Groß- und Kleinvieh sowie den Zehnten von den Weihegaben, die dem HERRN, ihrem Gott, geweiht waren, und legten sie Haufen bei Haufen hin.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 31, 7, 'Im dritten Monat begannen sie die Haufen aufzuschichten, und im siebten Monat waren sie damit fertig.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 31, 8, 'Als dann Hiskia und die Fürsten kamen und die Haufen besichtigten, priesen sie den HERRN und sein Volk Israel;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 31, 9, 'und als Hiskia sich nun bei den Priestern und den Leviten in betreff der Haufen erkundigte,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 31, 10, 'antwortete ihm Asarja, der Oberpriester aus dem Hause Zadok: »Seitdem man angefangen hat, die Abgaben zum Tempel des HERRN zu bringen, haben wir gegessen und sind satt geworden und haben noch viel übrig behalten; denn der HERR hat sein Volk gesegnet; daher ist dieser große Vorrat da übriggeblieben.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 31, 11, 'Da befahl Hiskia, Zellen im Hause des HERRN herzurichten; und als dies geschehen war,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 31, 12, 'brachte man die Abgaben sowie die Zehnten und die Weihegaben gewissenhaft hinein. Zum Oberaufseher darüber wurde der Levit Chananja bestellt und sein Bruder Simei an zweiter Stelle;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 31, 13, 'Jehiel aber, Asasja, Nahath, Asahel, Jerimoth, Josabad, Eliel, Jismachja, Mahath und Benaja standen als Aufseher dem Chananja und seinem Bruder Simei zur Seite nach der Anordnung des Königs Hiskia und Asarjas, des Fürsten im Hause Gottes.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 31, 14, 'Weiter wurde der Levit Kore, der Sohn Jimnas, der Hüter des östlichen Tores, zum Aufseher über die Gaben bestellt, die Gott freiwillig dargebracht wurden, damit die dem HERRN gebührenden Hebopfer und die hochheiligen Gaben abgeliefert würden.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 31, 15, 'Ihm standen Eden, Minjamin, Jesua, Semaja, Amarja und Sechanja in den Priesterstädten getreulich zur Seite, um ihren Amtsbrüdern abteilungsweise, den alten wie den jungen, ihre Anteile zuzuweisen');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 31, 16, 'mit Ausnahme der in das Geschlechtsverzeichnis eingetragenen männlichen Personen im Alter von drei und mehr Jahren, d.h. aller, die zum Hause des HERRN kamen, wie es ein jeder Tag erforderte, um ihren Dienst nach ihren Obliegenheiten abteilungsweise auszurichten.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 31, 17, 'Was aber das Verzeichnis der Priester anbetrifft, so war es nach ihren Familien angelegt, und das der Leviten enthielt die Personen von zwanzig und mehr Jahren mit Rücksicht auf ihre amtlichen Obliegenheiten abteilungsweise,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 31, 18, 'und zwar waren sie in das Verzeichnis eingetragen samt all ihren kleinen Kindern, ihren Frauen, ihren Söhnen und ihren Töchtern, also der gesamte Stand; denn in ihrer Ehrenhaftigkeit hatten sie sich zu gewissenhafter Pflichterfüllung geheiligt.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 31, 19, 'Auch für die Nachkommen Aarons, die Priester, waren in den Bezirken der zu ihren Städten gehörenden Markung, in jeder einzelnen Stadt, Männer, die mit Namen angegeben waren, dazu bestellt, allen männlichen Personen unter den Priestern und allen in das Verzeichnis eingetragenen Leviten Anteile zukommen zu lassen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 31, 20, 'Auf diese Weise verfuhr Hiskia in ganz Juda und tat, was vor dem HERRN, seinem Gott, gut, recht und pflichtgemäß war;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 31, 21, 'und bei allem, was er in betreff des Dienstes am Hause Gottes und auf Grund des Gesetzes und des Gebotes, um seinen Gott zu suchen, vornahm, handelte er mit voller Aufrichtigkeit und hatte daher auch glücklichen Erfolg.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 32, 1, 'Nach diesen Begebenheiten und dieser von Hiskia bewiesenen Treue zog Sanherib, der König von Assyrien, heran, drang in Juda ein und belagerte die festen Plätze in der Absicht, sie für sich zu erobern.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 32, 2, 'Als nun Hiskia sah, daß Sanherib herangerückt war und sich zum Angriff auf Jerusalem anschickte,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 32, 3, 'entschloß er sich im Einvernehmen mit seinen höchsten Beamten und seinen Heerführern, die Wasserquellen außerhalb der Stadt zu verschütten, und sie waren ihm dabei behilflich.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 32, 4, 'Es wurden also Leute in großer Zahl aufgeboten, welche die sämtlichen Quellen und den Bach, der mitten durch das Land floß, verschütteten, indem sie sagten: »Warum sollen die Könige von Assyrien, wenn sie kommen, Wasser in Menge vorfinden?«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 32, 5, 'Alsdann machte er sich mit Entschlossenheit ans Werk und ließ die Stadtmauer überall, wo sie niedergerissen war, wiederherstellen und Türme auf ihr errichten und draußen noch eine zweite Mauer aufführen; auch befestigte er das Millo in der Davidsstadt und ließ Waffen und Schilde in Menge herstellen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 32, 6, 'Weiter setzte er kriegstüchtige Anführer über das Heer ein, versammelte diese um sich auf dem freien Platz am Stadttor und sprach ihnen Mut zu mit den Worten:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 32, 7, '»Seid mutig und entschlossen! Fürchtet euch nicht und seid unverzagt vor dem König von Assyrien und vor dem ganzen Haufen, der mit ihm zieht! Denn mit uns ist ein Stärkerer als mit ihm:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 32, 8, 'mit ihm ist nur ein Arm von Fleisch, mit uns aber ist der HERR, unser Gott, der wird uns helfen und unsere Kriege führen!« Und das Volk fühlte sich durch die Worte Hiskias, des Königs von Juda, ermutigt.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 32, 9, 'Darnach sandte Sanherib, der König von Assyrien, während er selbst mit seiner ganzen Heeresmacht vor Lachis stand, (einige von) seinen Dienern nach Jerusalem an Hiskia, den König von Juda, und an alle Judäer, die sich in Jerusalem befanden, mit der Botschaft:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 32, 10, '»So läßt Sanherib, der König von Assyrien, euch sagen: ›Worauf verlaßt ihr euch, daß ihr in Jerusalem eingeschlossen sitzen bleibt?');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 32, 11, 'Ja, Hiskia ist es, der euch irreführt, um euch dem Tode durch Hunger und Durst preiszugeben, indem er euch verheißt: Der HERR, unser Gott, wird uns aus der Gewalt des Königs von Assyrien erretten!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 32, 12, 'Ist das nicht derselbe Hiskia, der den Höhendienst und die Altäre eures Gottes weggeschafft und in Juda und Jerusalem das Gebot erlassen hat: Vor einem einzigen Altar sollt ihr anbeten, und nur auf ihm dürft ihr opfern?');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 32, 13, 'Wißt ihr nicht, wie ich und meine Väter mit allen Völkern der (anderen) Länder verfahren sind? Haben etwa die Götter der Völker in den (übrigen) Ländern ihr Land aus meiner Gewalt irgendwie zu erretten vermocht?');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 32, 14, 'Wo ist unter allen Göttern dieser Völker, die meine Väter dem Untergange geweiht haben, einer gewesen, der sein Volk aus meiner Gewalt hätte erretten können? Wie sollte euer Gott da euch aus meiner Gewalt zu erretten vermögen?');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 32, 15, 'So laßt euch denn jetzt nicht von Hiskia betören und euch nicht auf solche Weise irreführen und schenkt ihm keinen Glauben! Denn kein Gott irgendeines Volkes und irgendeines Reiches hat (bisher) sein Volk aus meiner und meiner Väter Gewalt zu erretten vermocht; geschweige denn, daß euer Gott euch aus meiner Gewalt sollte erretten können!‹«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 32, 16, 'Seine Gesandten redeten dann noch mehr gegen Gott den HERRN und gegen seinen Knecht Hiskia;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 32, 17, 'auch hatte er, um den HERRN, den Gott Israels, zu verhöhnen und zu lästern, einen Brief folgenden Inhalts geschrieben: »Sowenig die Götter der Völker in den (übrigen) Ländern ihr Volk aus meiner Gewalt errettet haben, ebensowenig wird der Gott Hiskias sein Volk aus meiner Gewalt erretten!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 32, 18, 'Sie riefen dies auch der Bevölkerung von Jerusalem, die auf der Mauer stand, mit lauter Stimme auf jüdisch zu, um sie zu schrecken und in Angst zu versetzen, damit sie so die Stadt in ihre Gewalt brächten,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 32, 19, 'und redeten von dem Gott Jerusalems wie von den Göttern der Heidenvölker der Erde, die doch nur Machwerke von Menschenhänden sind.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 32, 20, 'Als nun infolgedessen der König Hiskia und der Prophet Jesaja, der Sohn des Amoz, beteten und um Hilfe zum Himmel schrien,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 32, 21, 'da sandte der HERR einen Engel, der sämtliche Kriegsleute und Fürsten und Heerführer im Lager des Königs von Assyrien sterben ließ, so daß jener mit Schimpf und Schande in sein Land zurückkehrte; und als er sich dann in den Tempel seines Gottes begab, brachten ihn dort einige von seinen leiblichen Söhnen mit dem Schwerte um.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 32, 22, 'So rettete der HERR den Hiskia und die Bewohner Jerusalems aus der Gewalt des Königs Sanherib von Assyrien und aus der Gewalt aller (seiner übrigen Feinde) und verschaffte ihnen Ruhe auf allen Seiten.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 32, 23, 'Und viele brachten dem HERRN Gaben nach Jerusalem und dem König Hiskia kostbare Geschenke, so daß er fortan bei allen Völkern in hohem Ansehen stand.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 32, 24, 'Als Hiskia zu jener Zeit auf den Tod erkrankte, betete er zum HERRN, und dieser erhörte ihn und gab ihm ein Wunderzeichen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 32, 25, 'Aber Hiskia bewies sich für die ihm erwiesene Wohltat nicht dankbar, sondern sein Herz überhob sich; darum brach ein Zorngericht über ihn und über Juda und Jerusalem herein.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 32, 26, 'Weil aber Hiskia sich nunmehr wegen seines Hochmuts demütigte, er samt der Bevölkerung von Jerusalem, erging das Zorngericht des HERRN über sie nicht schon bei Lebzeiten Hiskias.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 32, 27, 'Hiskia besaß sehr großen Reichtum und bedeutende Macht und legte sich auch Schatzkammern an für Silber, Gold und Edelsteine, für Spezereien, Schilde und Kostbarkeiten aller Art,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 32, 28, 'auch Vorratshäuser für den Ertrag von Getreide, Wein und Öl und Stallungen für allerlei Arten von Vieh und Hürden für die Herden.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 32, 29, 'Auch Städte legte er sich an, und er besaß große Herden von Kleinvieh und Rindern; denn Gott hatte ihm ein sehr bedeutendes Vermögen verliehen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 32, 30, 'Hiskia ist es auch gewesen, der den oberen Ausfluß des Wassers des Gihon verschüttet und es nach der Westseite hinunter nach der Davidsstadt geleitet hat; und bei allen seinen Unternehmungen hatte er Glück.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 32, 31, 'Gleichwohl bei Gelegenheit der Gesandtschaft, welche die Fürsten von Babylon an ihn geschickt hatten, um Erkundigungen wegen des Wunderzeichens einzuziehen, das im Lande geschehen war, verließ ihn Gott, um ihn auf die Probe zu stellen, damit er seine Gesinnung völlig kennenlernte.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 32, 32, 'Die übrige Geschichte Hiskias aber und seine frommen Taten finden sich bekanntlich bereits aufgezeichnet in der Offenbarung des Propheten Jesaja, des Sohnes des Amoz, und im Buch der Könige von Juda und Israel.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 32, 33, 'Als Hiskia sich dann zu seinen Vätern gelegt hatte, begrub man ihn am Aufstieg zu den Gräbern der Nachkommen Davids; und ganz Juda und die Bevölkerung Jerusalems erzeigten ihm Ehre bei seinem Tode. Sein Sohn Manasse folgte ihm dann in der Regierung nach.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 33, 1, 'Im Alter von zwölf Jahren wurde Manasse König und regierte fünfundfünfzig Jahre in Jerusalem.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 33, 2, 'Er tat, was dem HERRN mißfiel, im Anschluß an den greuelhaften Götzendienst der (heidnischen) Völker, die der HERR vor den Israeliten vertrieben hatte.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 33, 3, 'Er baute die Höhenheiligtümer wieder auf, die sein Vater Hiskia zerstört hatte, errichtete den Baalen Altäre, ließ Standbilder der Aschera herstellen, betete das ganze Sternenheer des Himmels an und erwies ihnen Verehrung.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 33, 4, 'Er erbaute sogar Altäre im Tempel des HERRN, von dem doch der HERR gesagt hatte: »In Jerusalem soll mein Name für alle Zeiten wohnen!«,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 33, 5, 'und zwar erbaute er dem ganzen Sternenheer des Himmels Altäre in den beiden Vorhöfen beim Tempel des HERRN.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 33, 6, 'Ja er ließ sogar seine eigenen Söhne im Tale Ben-Hinnom als Brandopfer verbrennen, trieb Zauberei, Wahrsagerei und geheime Künste und bestellte Totenbeschwörer und Zeichendeuter: er tat vieles, was dem HERRN mißfiel und ihn zum Zorn reizen mußte.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 33, 7, 'Das geschnitzte Götzenbild, das er hatte anfertigen lassen, stellte er sogar im Hause Gottes auf, von dem doch Gott zu David und dessen Sohne Salomo gesagt hatte: »In diesem Hause und in Jerusalem, das ich aus allen Stämmen Israels erwählt habe, will ich meinen Namen für ewige Zeiten wohnen lassen;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 33, 8, 'und ich will den Fuß Israels fortan nicht wieder weichen lassen aus dem Lande, das ich ihren Vätern angewiesen habe, wofern sie nur darauf bedacht sind, alles zu tun, was ich ihnen geboten habe, nämlich ganz nach dem Gesetz und den Satzungen und Verordnungen (zu leben), die sie durch Mose erhalten haben.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 33, 9, 'Aber Manasse verleitete Juda und die Bewohner Jerusalems dazu, es noch ärger zu treiben, als die heidnischen Völker es getan hatten, die der HERR vor den Israeliten vertilgt hatte.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 33, 10, 'Zwar warnte der HERR den Manasse und sein Volk durch den Mund von Propheten, aber sie achteten nicht darauf.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 33, 11, 'Da ließ der HERR die Heerführer des Königs von Assyrien gegen sie anrücken; die führten Manasse mit Haken gefangen, legten ihm eherne Fesseln an und brachten ihn nach Babylon.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 33, 12, 'Als er sich nun in Not befand, flehte er zum HERRN, seinem Gott, um Gnade und demütigte sich tief vor dem Gott seiner Väter;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 33, 13, 'und als er nun zu ihm betete, ließ er sich von ihm erbitten, so daß er sein Flehen erhörte und ihn nach Jerusalem in seine königliche Stellung zurückbrachte. Da erkannte Manasse, daß der HERR (der wahre) Gott ist.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 33, 14, 'Später baute er noch eine äußere Mauer an der Davidsstadt, auf der Westseite nach dem Gihon hin, im (Kidron-) Tal und bis zum Eingang ins Fischtor, so daß er den Ophel umschloß; dabei erhöhte er sie beträchtlich. Auch setzte er Befehlshaber in sämtlichen festen Plätzen Judas ein.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 33, 15, 'Sodann schaffte er die fremden Götter und das Götzenbild aus dem Tempel des HERRN weg, ebenso alle Altäre, die er auf dem Tempelberge und in Jerusalem errichtet hatte, und ließ sie vor die Stadt hinauswerfen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 33, 16, 'Dagegen stellte er den Altar des HERRN wieder her und opferte auf ihm Heils- und Dankopfer und machte den Judäern die Verehrung des HERRN, des Gottes Israels, zur Pflicht.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 33, 17, 'Indessen opferte das Volk noch immer auf den Höhen, allerdings nur dem HERRN, ihrem Gott.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 33, 18, 'Die übrige Geschichte Manasses aber und sein Gebet zu seinem Gott sowie die Reden der Seher, die im Namen des HERRN, des Gottes Israels, zu ihm geredet haben, das alles steht bereits in der Geschichte der Könige von Israel geschrieben.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 33, 19, 'Sein Gebet aber und wie er bei Gott Erhörung fand, sowie alle seine Versündigungen und seine Untreue und die Orte, an denen er vor seiner Demütigung Höhenaltäre erbaut und Standbilder der Aschera und geschnitzte Götzenbilder aufgestellt hatte, das findet sich bekanntlich aufgezeichnet in der Geschichte Hosais. –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 33, 20, 'Als Manasse sich dann zu seinen Vätern gelegt und man ihn in seinem Hause begraben hatte, folgte ihm sein Sohn Amon in der Regierung nach.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 33, 21, 'Im Alter von zweiundzwanzig Jahren wurde Amon König und zwei Jahre regierte er in Jerusalem.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 33, 22, 'Er tat, was dem HERRN mißfiel, wie sein Vater Manasse getan hatte; und allen Götzenbildern, die sein Vater Manasse hatte anfertigen lassen, brachte Amon eifrig Opfer dar und verehrte sie.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 33, 23, 'Aber er demütigte sich nicht vor dem HERRN, wie sein Vater Manasse sich gedemütigt hatte, sondern er, Amon, lud große Schuld auf sich.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 33, 24, 'Da verschworen sich seine eigenen Diener gegen ihn und ermordeten ihn in seinem Palast.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 33, 25, 'Die Landbevölkerung aber erschlug alle, die an der Verschwörung gegen den König Amon teilgenommen hatten, und erhob dann seinen Sohn Josia zu seinem Nachfolger auf dem Throne.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 34, 1, 'Im Alter von acht Jahren wurde Josia König, und einunddreißig Jahre regierte er in Jerusalem.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 34, 2, 'Er tat, was dem HERRN wohlgefiel: er wandelte auf den Wegen seines Ahnherrn David, ohne nach rechts oder nach links davon abzuweichen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 34, 3, 'Im achten Jahre seiner Regierung, als er noch ein Jüngling war, fing er an, den Gott seines Ahnherrn David zu suchen, und im zwölften Jahr begann er, Juda und Jerusalem von dem Höhendienst und den Standbildern der Aschera und den geschnitzten und gegossenen Bildern zu reinigen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 34, 4, 'Vor seinen Augen riß man die Altäre der Baale nieder, und die Sonnensäulen, die oben auf ihnen standen, ließ er umhauen und die Standbilder der Aschera und die geschnitzten und gegossenen Bilder zertrümmern und zermalmen und den Staub von ihnen auf die Gräber derer streuen, die ihnen geopfert hatten;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 34, 5, 'die Gebeine der Priester ließ er auf ihren Altären verbrennen und reinigte auf diese Weise Juda und Jerusalem.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 34, 6, 'Auch in den Städten von Manasse und Ephraim, von Simeon und bis nach Naphthali hin – in den dortigen Trümmerstätten ringsum –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 34, 7, 'riß er die Altäre nieder, zertrümmerte und zermalmte die Standbilder der Aschera und die geschnitzten Bilder und ließ alle Sonnensäulen in allen Gegenden Israels umhauen; dann kehrte er nach Jerusalem zurück.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 34, 8, 'Im achtzehnten Jahre seiner Regierung aber, als er das Land und den Tempel gereinigt hatte, sandte er Saphan, den Sohn Azaljas, und den Stadthauptmann Maaseja und den Kanzler Joah, den Sohn des Joahas, um den Tempel des HERRN, seines Gottes, wieder instandsetzen zu lassen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 34, 9, 'Als diese nun zum Hohenpriester Hilkia kamen, übergaben sie das Geld, das im Hause Gottes eingegangen war und das die Leviten, die Schwellenhüter, von den Stämmen Manasse und Ephraim und von allen übrigen Israeliten sowie von ganz Juda und Benjamin und den Bewohnern Jerusalems eingesammelt hatten, –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 34, 10, 'und zwar händigten sie es den Werkführern ein, die für die Arbeit am Tempel des HERRN bestellt waren; diese übergaben es dann den Arbeitern, die am Tempel des HERRN tätig waren, um den Tempel herzustellen und auszubessern;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 34, 11, 'und zwar übergaben sie es den Zimmerleuten und Bauleuten zum Ankauf von behauenen Steinen und von Hölzern für die Decken und um die Baulichkeiten, welche die Könige von Juda hatten in Verfall geraten lassen, mit neuem Gebälk zu versehen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 34, 12, 'Diese Männer handelten bei ihrer Arbeit auf Treu und Glauben; und über sie waren gesetzt: die Leviten Jahath und Obadja aus den Nachkommen Meraris, und Sacharja und Mesullam aus den Nachkommen der Kahathiten, um die Aufsicht zu führen; und die Leviten, soweit sie sich auf Musikinstrumente verstanden,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 34, 13, 'waren über die Lastträger gesetzt und führten auch die Aufsicht über alle Arbeiter bei ihren verschiedenen Dienstleistungen; und andere von den Leviten waren auch Schreiber, Amtleute und Torhüter.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 34, 14, 'Als sie nun das Geld, das im Tempel des HERRN eingegangen war, herausnahmen, fand der Priester Hilkia das Buch mit dem von Mose herrührenden Gesetz des HERRN.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 34, 15, 'Da hob Hilkia an und sagte zum Staatsschreiber Saphan: »Ich habe das Gesetzbuch im Tempel des HERRN gefunden!« Damit übergab Hilkia das Buch dem Saphan.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 34, 16, 'Dieser überbrachte dann das Buch dem König und erstattete außerdem dem Könige folgenden Bericht: »Alles, was deinen Knechten aufgetragen war, haben sie ausgerichtet:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 34, 17, 'sie haben das Geld, das sich im Tempel des HERRN vorfand, ausgeschüttet und haben es den zur Aufsicht Bestellten und den Werkführern eingehändigt.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 34, 18, 'Weiter machte der Staatsschreiber Saphan dem Könige noch die Mitteilung: »Der Priester Hilkia hat mir ein Buch gegeben«; und Saphan las dem Könige daraus vor.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 34, 19, 'Als nun der König den Inhalt des Gesetzbuches vernahm, zerriß er seine Kleider');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 34, 20, 'und gab sodann dem Hilkia und Ahikam, dem Sohne Saphans, ferner Abdon, dem Sohne Michas, und dem Staatsschreiber Saphan und Asaja, dem Leibdiener des Königs, folgenden Befehl:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 34, 21, '»Geht hin und befragt den HERRN für mich und für die, welche in Israel und Juda noch übriggeblieben sind, in betreff des Wortlautes des Buches, das man aufgefunden hat; denn groß ist der Grimm des HERRN, der sich über uns ergossen hat, weil unsere Väter die Weisungen des HERRN nicht beachtet haben, um alles zu tun, was in diesem Buche geschrieben steht.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 34, 22, 'Da begab sich Hilkia mit den Männern, die der König bezeichnet hatte, zu der Prophetin Hulda, der Frau des Kleiderhüters Sallum, des Sohnes Thokhaths, des Sohnes Hasras; die wohnte in Jerusalem im zweiten Bezirk. Als sie sich nun mit ihr gemäß dem ihnen erteilten Auftrage besprachen,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 34, 23, 'sagte sie zu ihnen: »So hat der HERR, der Gott Israels, gesprochen: Sagt dem Manne, der euch zu mir gesandt hat:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 34, 24, 'So hat der HERR gesprochen: ›Wisse wohl: ich will Unglück über diesen Ort und seine Bewohner kommen lassen, nämlich alle die Flüche, die in dem Buche geschrieben stehen, das man dem König von Juda vorgelesen hat.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 34, 25, 'Zur Strafe dafür, daß sie mich verlassen und anderen Göttern geopfert haben, um mich mit all den Machwerken ihrer Hände zum Zorn zu reizen, daher hat sich mein Grimm über diesen Ort ergossen und wird nicht wieder erlöschen!‹');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 34, 26, 'Zum König von Juda aber, der euch gesandt hat, um den HERRN zu befragen, zu dem sollt ihr sagen: So hat der HERR, der Gott Israels, gesprochen: ›Was die Drohungen anbetrifft, die du vernommen hast:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 34, 27, 'weil dein Herz weich geworden ist und du dich vor Gott gedemütigt hast, als du seine Drohungen gegen diesen Ort und gegen seine Bewohner vernahmst, und du dich vor mir gedemütigt und deine Kleider zerrissen und vor mir geweint hast, so habe auch ich dir Gehör geschenkt‹ – so lautet der Ausspruch des HERRN.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 34, 28, '›Darum wisse wohl: wenn ich dich zu deinen Vätern versammle, sollst du in Frieden in deine Grabstätte eingebracht werden, und deine Augen sollen all das Unglück, das ich über diesen Ort und seine Bewohner bringen werde, nicht zu sehen bekommen!‹« Als sie nun dem Könige Bericht erstattet hatten,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 34, 29, 'sandte der König Boten aus und ließ alle Ältesten von Juda und Jerusalem zusammenkommen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 34, 30, 'Hierauf ging der König zum Tempel des HERRN hinauf und mit ihm alle Männer von Juda und die Bewohner Jerusalems, auch die Priester und die Leviten, kurz das ganze Volk, klein und groß; und er las ihnen den ganzen Inhalt des Bundesbuches vor, das im Tempel des HERRN gefunden worden war.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 34, 31, 'Hierauf trat der König an seinen Standort und schloß den Bund vor dem HERRN mit der Zusage ab, daß sie dem HERRN nachwandeln und seine Gebote, seine Verordnungen und seine Satzungen mit ganzem Herzen und mit ganzer Seele beobachten wollten, um so nach den Bestimmungen des Bundes zu handeln, die in diesem Buche geschrieben standen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 34, 32, 'Er ließ dann alle, die sich in Jerusalem und Benjamin befanden, dem Bunde beitreten, und die Einwohner von Jerusalem handelten so, wie es dem Bunde mit Gott, dem Gott ihrer Väter, entsprach.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 34, 33, 'So schaffte denn Josia alle Götzengreuel aus sämtlichen Landschaften der Israeliten weg und verpflichtete alle, die sich in Israel befanden, zur Verehrung des HERRN, ihres Gottes. Solange Josia lebte, wichen sie nicht von der Nachfolge des HERRN, des Gottes ihrer Väter, ab.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 35, 1, 'Hierauf feierte Josia dem HERRN ein Passah in Jerusalem; und zwar schlachtete man das Passah am vierzehnten Tage des ersten Monats.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 35, 2, 'Da bestellte er die Priester zu ihren Obliegenheiten und weckte in ihnen den Eifer für den Dienst im Hause des HERRN.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 35, 3, 'Den Leviten aber, die ganz Israel zu unterweisen hatten und die dem HERRN geheiligt waren, gebot er: »Bringt die heilige Lade in den Tempel, den Salomo, der Sohn Davids, der König von Israel, gebaut hat: ihr braucht sie nicht mehr auf der Schulter zu tragen. So dient nunmehr dem HERRN, eurem Gott, und seinem Volk Israel');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 35, 4, 'und haltet euch bereit nach euren Familien, in euren Abteilungen, wie David, der König von Israel, (es verordnet) und sein Sohn Salomo es vorgeschrieben hat.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 35, 5, 'Stellt euch also im Heiligtum entsprechend den Gruppen der Familien eurer Volksgenossen, der Laien, auf, und zwar (für jede Gruppe) eine Abteilung einer levitischen Familie.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 35, 6, 'Dann schlachtet das Passah und heiligt euch und richtet (die Opfertiere) für eure Volksgenossen zu, so daß ihr nach den Weisungen verfahrt, die der HERR durch Mose gegeben hat.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 35, 7, 'Hierauf machte Josia den Leuten aus dem Volke Kleinvieh zum Geschenk, nämlich Schaflämmer und junge Ziegenböcke, alles zu den Passahopfern für alle Anwesenden, dreißigtausend an der Zahl, dazu dreitausend Rinder, alles dies aus dem königlichen Besitz.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 35, 8, 'Auch seine Obersten spendeten dem Volke, den Priestern und den Leviten freiwillige Gaben; nämlich Hilkia, Sacharja und Jehiel, die Fürsten des Gotteshauses, schenkten den Priestern für die Passahopfer 2600 Stück Kleinvieh und 300 Rinder;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 35, 9, 'und Chananja nebst seinen Brüdern Semaja und Nethaneel sowie Hasabja, Jehiel und Josabad, die Obersten der Leviten, spendeten den Leviten als freiwillige Gabe zu den Passahopfern 5000 Stück Kleinvieh und 500 Rinder.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 35, 10, 'Nach diesen Vorbereitungen für den Gottesdienst traten die Priester an ihren Platz, ebenso die Leviten nach ihren Abteilungen, wie der König es befohlen hatte.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 35, 11, 'Dann schlachteten (die Leviten) das Passah, und die Priester nahmen die Besprengungen mit dem ihnen dargereichten Blut vor, während die Leviten (den Tieren) die Haut abzogen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 35, 12, 'Sie legten aber die Stücke beiseite, welche verbrannt werden sollten, um sie den einzelnen Gruppen der Laienfamilien zu geben, damit diese sie dem HERRN darbrächten, wie es im mosaischen Gesetzbuch vorgeschrieben ist; und ebenso machte man es mit den Rindern.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 35, 13, 'Dann brieten sie das Passah vorschriftsgemäß am Feuer, während sie die geweihten Gaben in Töpfen, Kesseln und Schüsseln kochten und sie eilends allen Leuten aus dem Volke hinbrachten.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 35, 14, 'Darnach richteten sie auch für sich und für die Priester zu; denn die Priester, die Nachkommen Aarons, hatten mit der Darbringung der Brandopfer und der Fettstücke bis in die Nacht hinein zu tun; darum mußten die Leviten für sich und für die Priester, die Nachkommen Aarons, zurichten.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 35, 15, 'Auch die Sänger, die Nachkommen Asaphs, waren auf ihrem Posten nach der Anordnung Davids, Asaphs, Hemans und Jeduthuns, des königlichen Sehers, und ebenso standen die Torhüter an den einzelnen Toren; sie hatten nicht nötig, ihren Dienst zu verlassen, weil ihre Stammesgenossen, die Leviten, für sie zurichteten.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 35, 16, 'So war der ganze Dienst des HERRN an jenem Tage geordnet, so daß man das Passah feierte und die Brandopfer auf dem Altar des HERRN nach der Anordnung des Königs Josia darbrachte.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 35, 17, 'So feierten also damals die Israeliten, die zugegen waren, das Passah und dann das Fest der ungesäuerten Brote sieben Tage lang.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 35, 18, 'Es war aber ein solches Passah wie dieses in Israel nicht gefeiert worden seit der Zeit des Propheten Samuel, und keiner von allen Königen Israels hatte ein solches Passah veranstaltet, wie Josia es feierte mit den Priestern und den Leviten und ganz Juda sowie mit den Israeliten, die sich dazu eingefunden hatten, und mit den Bewohnern Jerusalems.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 35, 19, 'Im achtzehnten Jahre der Regierung Josias ist dieses Passah gefeiert worden.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 35, 20, 'Nach allen diesen Begebenheiten, als Josia den Tempel wiederhergestellt hatte, zog Necho, der König von Ägypten, heran, um (dem König von Assyrien) bei Karchemis am Euphrat eine Schlacht zu liefern, und Josia zog ihm entgegen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 35, 21, 'Da sandte jener Boten an ihn und ließ ihm sagen: »Was haben wir miteinander zu schaffen, König von Juda? Nicht gegen dich ziehe ich diesmal, sondern gegen das Herrscherhaus (von Assyrien), mit dem ich Krieg führe, und Gott hat mir Eile geboten. Laß also ab von Gott, der mit mir ist, damit er dich nicht verderbe!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 35, 22, 'Aber Josia ließ sich nicht zum Rückzug vor ihm bewegen, sondern faßte den kühnen Entschluß, mit ihm zu kämpfen, ohne auf die Warnung Nechos zu hören, die doch aus dem Munde Gottes kam. Er rückte also zum Kampf in die Ebene von Megiddo.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 35, 23, 'Da schossen die Bogenschützen auf den König Josia, bis dieser seinen Dienern befahl: »Bringt mich hinweg, denn ich bin schwer verwundet!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 35, 24, 'Da hoben ihn seine Diener von dem Kriegswagen hinunter, setzten ihn auf den zweiten Wagen, den er bei sich hatte, und brachten ihn nach Jerusalem, wo er starb und in den Gräbern seiner Väter beigesetzt wurde. Ganz Juda und Jerusalem trauerten um Josia;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 35, 25, 'Jeremia aber dichtete ein Klagelied auf Josia, und alle Sänger und Sängerinnen haben (seitdem) in ihren Klageliedern von Josia gesungen bis auf den heutigen Tag; sie sind in Israel überall in Aufnahme gekommen und finden sich bekanntlich in den Klageliedern aufgezeichnet.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 35, 26, 'Die übrige Geschichte Josias aber und seine frommen, den Vorschriften im Gesetz des HERRN entsprechenden Taten,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 35, 27, 'überhaupt seine Geschichte von Anfang bis zu Ende, das findet sich bekanntlich schon aufgezeichnet im Buch der Könige von Israel und Juda.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 36, 1, 'Die Landbevölkerung nahm dann Joahas, den Sohn Josias, und machte ihn zum König in Jerusalem als Nachfolger seines Vaters.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 36, 2, 'Im Alter von dreiundzwanzig Jahren wurde Joahas König und regierte drei Monate in Jerusalem;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 36, 3, 'dann setzte ihn der König von Ägypten in Jerusalem ab und legte dem Lande eine Geldbuße von hundert Talenten Silber und einem Talent Gold auf.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 36, 4, 'Dann machte der König von Ägypten den Bruder des Joahas, nämlich Eljakim, zum König über Juda und Jerusalem und änderte seinen Namen in Jojakim ab; seinen Bruder Joahas aber nahm Necho mit sich und brachte ihn nach Ägypten.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 36, 5, 'Im Alter von fünfundzwanzig Jahren wurde Jojakim König und regierte elf Jahre in Jerusalem; er tat, was dem HERRN, seinem Gott, mißfiel.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 36, 6, 'Da zog Nebukadnezar, der König von Babylon, gegen ihn heran und legte ihn in Ketten, um ihn nach Babylon bringen zu lassen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 36, 7, 'Auch einen Teil der Geräte des Tempels des HERRN entführte Nebukadnezar nach Babylon und brachte sie in seinem Tempel zu Babylon unter. –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 36, 8, 'Die übrige Geschichte Jojakims aber und die Greueltaten, die er begangen hat, und was sonst noch Böses bei ihm vorgekommen ist, das findet sich bekanntlich bereits aufgezeichnet im Buch der Könige von Israel und Juda. Sein Sohn Jojachin folgte ihm dann in der Regierung nach.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 36, 9, 'Im Alter von achtzehn Jahren wurde Jojachin König und regierte drei Monate und zehn Tage in Jerusalem; er tat, was dem HERRN mißfiel.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 36, 10, 'Um die Jahreswende aber sandte der König Nebukadnezar hin und ließ ihn nach Babylon holen samt den kostbarsten Geräten des Tempels des HERRN und machte seinen Bruder Zedekia zum König über Juda und Jerusalem.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 36, 11, 'Im Alter von einundzwanzig Jahren wurde Zedekia König und regierte elf Jahre in Jerusalem.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 36, 12, 'Er tat, was dem HERRN, seinem Gott, mißfiel; er demütigte sich nicht vor Jeremia, der als Prophet auf Befehl des HERRN zu ihm redete.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 36, 13, 'Dazu empörte er sich gegen den König Nebukadnezar, der ihn doch einen Treueid bei Gott hatte schwören lassen, und machte seinen Nacken steif und sein Herz verstockt, so daß er sich nicht zum HERRN, dem Gott Israels, bekehrte.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 36, 14, 'Ebenso begingen alle höchstgestellten Priester und die Häupter des Volkes Sünden auf Sünden in der Weise der heidnischen Götzengreuel und entweihten das Haus, das der HERR in Jerusalem geheiligt hatte.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 36, 15, 'Zwar sandte der HERR, der Gott ihrer Väter, durch seine Boten unermüdlich immer wieder (Warnungen) an sie, weil er Erbarmen mit seinem Volke fühlte und seine Wohnstätte ihm leid tat;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 36, 16, 'aber sie verhöhnten die Boten Gottes und verachteten seine Drohungen und trieben ihren Spott mit seinen Propheten, bis der Grimm des HERRN gegen sein Volk so hoch stieg, daß keine Heilung mehr möglich war.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 36, 17, 'So ließ er denn den König der Chaldäer gegen sie heranziehen; der erschlug ihre junge Mannschaft mit dem Schwert in ihrem heiligen Tempel: er verschonte weder Jünglinge noch Jungfrauen, nicht Greise noch Hochbetagte: alles ließ Gott ihm in die Hände fallen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 36, 18, 'Auch sämtliche Geräte des Gotteshauses, die großen wie die kleinen, und die Schätze des Tempels des HERRN und die Schätze des Königs und seiner Würdenträger: alles entführte er nach Babylon.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 36, 19, 'Den Tempel aber verbrannten sie, die Mauern Jerusalems rissen sie nieder und ließen alle Paläste der Stadt in Flammen aufgehen, so daß alle kostbaren Geräte darin zugrunde gingen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 36, 20, 'Hierauf führte er alle, die dem Blutbad entgangen waren, gefangen nach Babylon, wo sie ihm und seinen Söhnen als Knechte dienstbar waren, bis das Perserreich zur Herrschaft gelangte.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 36, 21, 'So sollte das Wort des HERRN, das durch den Mund Jeremias ausgesprochen worden war, seine Erfüllung finden: »Bis das Land seine Sabbatjahre abgetragen hätte.« Während der ganzen Zeit seiner Verödung hatte es Ruhe, bis siebzig Jahre voll waren.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 36, 22, 'Aber im ersten Jahre der Regierung des Kores, des Königs von Persien – damit das durch den Mund Jeremias ergangene Wort des HERRN in Erfüllung ginge –, regte der HERR den Geist des Perserkönigs Kores dazu an, folgende Verfügung durch sein ganzes Reich hin ausrufen und auch durch schriftlichen Erlaß bekanntmachen zu lassen:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 36, 23, '»So spricht Kores, der König von Persien: Alle Reiche der Erde hat mir der HERR, der Gott des Himmels, gegeben, und er ist’s auch, der mir aufgetragen hat, ihm zu Jerusalem in Juda einen Tempel zu erbauen. Wer also unter euch allen zu seinem Volke gehört, mit dem sei sein Gott, und er ziehe hinauf!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 1, 1, 'Im ersten Regierungsjahre des Kores, des Königs von Persien – damit das durch den Mund Jeremias ergangene Wort des HERRN in Erfüllung ginge – regte der HERR den Geist des Perserkönigs Kores dazu an, folgende Verfügung in seinem ganzen Reiche ausrufen und auch durch schriftlichen Erlaß bekanntmachen zu lassen:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 1, 2, '»So spricht Kores, der König von Persien: Alle Reiche der Erde hat der HERR, der Gott des Himmels, mir übergeben, und er ist’s auch, der mir aufgetragen hat, ihm zu Jerusalem in Juda ein Haus zu erbauen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 1, 3, 'Wer also unter euch allen zu seinem Volke gehört, mit dem sei sein Gott, und er ziehe hinauf nach Jerusalem in Juda und baue dort das Haus des HERRN, des Gottes Israels; das ist der Gott, der in Jerusalem wohnt.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 1, 4, 'Und jeder, der noch übriggeblieben ist, den sollen an allen Orten, wo er sich als Fremdling aufhält, die betreffenden Ortsbewohner mit Silber und Gold, mit beweglicher Habe und Vieh sowie mit freiwilligen Gaben für das Gotteshaus in Jerusalem unterstützen.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 1, 5, 'Da machten sich die Familienhäupter von Juda und Benjamin sowie die Priester und die Leviten auf den Weg, alle, denen Gott es in den Sinn gegeben hatte, hinaufzuziehen, um den Tempel des HERRN in Jerusalem wieder aufzubauen;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 1, 6, 'und alle, die um sie her wohnten, unterstützten sie auf jede Weise mit Gaben, mit Silber und Gold, mit beweglicher Habe und Vieh und mit Kostbarkeiten, außerdem mit freiwilligen Gaben aller Art.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 1, 7, 'Auch gab der König Kores die Tempelgeräte wieder heraus, die Nebukadnezar einst aus Jerusalem weggeführt und im Tempel seines Gottes untergebracht hatte:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 1, 8, 'der König Kores von Persien ließ sie unter der Aufsicht des Schatzmeisters Mithredath hervorholen, und dieser zählte sie Sesbazzar, dem Fürsten von Juda, zu.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 1, 9, 'Ihre Zahl war folgende: 30 goldene und 1000 silberne Becken,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 1, 10, '30 goldene Becher, 2410 silberne Becher, 1000 andere Geräte,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 1, 11, 'im ganzen 5400 goldene und silberne Geräte. Das alles nahm Sesbazzar mit hinauf, als die in die Verbannung Weggeführten von Babylon nach Jerusalem hinaufgeführt wurden.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 1, 'Folgendes nun sind die Bewohner der Landschaft Juda, die aus der Gefangenschaft der in der Verbannung Lebenden, welche Nebukadnezar, der König von Babylon, (einst) nach Babylon weggeführt hatte, hinaufgezogen sind und (nun) nach Jerusalem und Juda zurückkehrten, ein jeder in seine Ortschaft.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 2, 'Sie sind dorthin gekommen zusammen mit Serubbabel, Jesua, Nehemia, Seraja, Reelaja, Mordochai, Bilsan, Mispar, Bigwai, Rehum und Baana. Die Zahl der Männer des Volkes Israel betrug:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 3, 'die Familie Parhos 2172;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 4, 'die Familie Sephatja 372;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 5, 'die Familie Arah 775;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 6, 'die Familie Pahath-Moab, nämlich die Familien Jesua und Joab, 2812;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 7, 'die Familie Elam 1254;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 8, 'die Familie Satthu 945;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 9, 'die Familie Sakkai 760;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 10, 'die Familie Bani 642;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 11, 'die Familie Bebai 623;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 12, 'die Familie Asgad 1222;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 13, 'die Familie Adonikam 666;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 14, 'die Familie Bigwai 2056;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 15, 'die Familie Adin 454;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 16, 'die Familie Ater, nämlich der Zweig Hiskia, 98;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 17, 'die Familie Bezai 323;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 18, 'die Familie Jora 112;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 19, 'die Familie Hasum 223;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 20, 'die Leute von Gibeon 95;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 21, 'die Leute von Bethlehem 123;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 22, 'die Männer von Netopha 56;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 23, 'die Männer von Anathoth 128;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 24, 'die Leute von Asmaweth 42;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 25, 'die Leute von Kirjath-Arim, Kephira und Beeroth 743;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 26, 'die Leute von Rama und Geba 621;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 27, 'die Männer von Michmas 122;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 28, 'die Männer von Bethel und Ai 223;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 29, 'die Familie Nebo 52;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 30, 'die Familie Magbis 156;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 31, 'die Familie des andern Elam 1254;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 32, 'die Familie Harim 320;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 33, 'die Leute von Lod, Hadid und Ono 725;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 34, 'die Leute von Jericho 345;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 35, 'die Familie Senaa 3630.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 36, 'Die Priester: die Familie Jedaja, nämlich das Haus Jesua 973;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 37, 'die Familie Immer 1052;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 38, 'die Familie Pashur 1247;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 39, 'die Familie Harim 1017.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 40, 'Die Leviten: die Familien Jesua und Kadmiel, Binnui und Hodawja 74; –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 41, 'die Sänger: die Familie Asaph 128; –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 42, 'die Familien der Torhüter: die Familien Sallum, Ater, Talmon, Akkub, Hatita und Sobai, im ganzen 139.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 43, 'Die Tempelhörigen: die Familie Ziha, die Familie Hasupha, die Familie Tabbaoth,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 44, 'die Familie Keros, die Familie Siaha, die Familie Padon,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 45, 'die Familie Lebana, die Familie Hagaba, die Familie Akkub,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 46, 'die Familie Hagab, die Familie Salmai, die Familie Hanan,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 47, 'die Familie Giddel, die Familie Gahar, die Familie Reaja,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 48, 'die Familie Rezin, die Familie Nekoda, die Familie Gassam,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 49, 'die Familie Ussa, die Familie Paseah, die Familie Besai,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 50, 'die Familie Asna, die Familie der Mehuniter, die Familie der Nephisiter,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 51, 'die Familie Bakbuk, die Familie Hakupha, die Familie Harhur,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 52, 'die Familie Bazluth, die Familie Mehida, die Familie Harsa,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 53, 'die Familie Barkos, die Familie Sisera, die Familie Themah,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 54, 'die Familie Neziah, die Familie Hatipha.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 55, 'Die Söhne der Sklaven Salomos: die Familie Sotai, die Familie Sophereth, die Familie Peruda,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 56, 'die Familie Jaala, die Familie Darkon, die Familie Giddel,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 57, 'die Familie Sephatja, die Familie Hattil, die Familie Pochereth-Hazzebaim, die Familie Ami.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 58, 'Die Gesamtzahl der Tempelhörigen und der Nachkommen der Sklaven Salomos betrug 392.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 59, 'Und dies sind die, welche aus Thel-Melah, Thel-Harsa, Cherub-Addan und Immer mit hinaufzogen, aber ihre Familie und ihre Herkunft nicht nachweisen konnten, ob sie nämlich aus Israel stammten:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 60, 'die Familie Delaja, die Familie Tobija, die Familie Nekoda, 652. –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 61, 'Sodann von den Priesterfamilien: die Familie Habaja, die Familie Hakkoz, die Familie jenes Barsillais, der eine Frau von den Töchtern des Gileaditen Barsillai geheiratet und deren Namen angenommen hatte.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 62, 'Diese hatten zwar nach ihrer Geschlechtsurkunde gesucht, aber diese hatte sich nicht finden lassen; infolgedessen wurden sie als unrein vom Priestertum ausgeschlossen,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 63, 'und der Statthalter hatte ihnen erklärt, daß sie von dem Hochheiligen nicht essen dürften, bis wieder ein Priester für die Befragung des Urim- und Thummimorakels da wäre.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 64, 'Die ganze Gemeinde insgesamt belief sich auf 42360 Seelen,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 65, 'ungerechnet ihre Sklaven und Sklavinnen, deren 7337 da waren. Dazu kamen noch 200 Sänger und Sängerinnen. –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 66, 'Die Zahl ihrer Pferde betrug 736, ihrer Maultiere 245,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 67, 'ihrer Kamele 435, der Esel 6720.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 68, 'Als sie dann beim Tempel des HERRN in Jerusalem angekommen waren, spendeten einige von den Familienhäuptern freiwillige Gaben für das Haus Gottes, damit man es an seiner früheren Stätte wieder aufrichten könne.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 69, 'Nach ihrem Vermögen gaben sie für den Bauschatz: an Gold 61000 Dariken, an Silber 5000 Minen und 100 Priestergewänder.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 70, 'Und es siedelten sich die Priester und die Leviten sowie ein Teil des Volkes in Jerusalem und dessen Gebieten an, die Sänger dagegen und die Torhüter und die Tempelhörigen in ihren Ortschaften, und alle übrigen Israeliten in ihren Ortschaften.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 3, 1, 'Als nun der siebte Monat herangekommen war – die Israeliten befanden sich bereits in ihren Ortschaften –, da kam das Volk wie ein Mann in Jerusalem zusammen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 3, 2, 'Da machten sich Jesua, der Sohn Jozadaks, mit seinen Genossen, den Priestern, und Serubbabel, der Sohn Sealthiels, mit seinen Genossen daran, den Altar des Gottes Israels wieder aufzubauen, um Brandopfer auf ihm darzubringen, wie es im Gesetz Moses, des Mannes Gottes, vorgeschrieben war;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 3, 3, 'und zwar errichteten sie den Altar auf seinem alten Unterbau; denn wenn sie auch in Angst vor den heidnischen Bewohnern der (umliegenden) Landschaften waren, brachten sie doch dem HERRN Brandopfer auf ihm dar, und zwar Brandopfer am Morgen und am Abend.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 3, 4, 'Dann begingen sie das Laubhüttenfest vorschriftsgemäß und brachten dabei Brandopfer Tag für Tag in richtiger Zahl nach der Verordnung der für jeden einzelnen Tag bestimmten Opfer dar,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 3, 5, 'danach auch das tägliche Brandopfer und die Opfer (für die Sabbate und) für die Neumonde und für alle heiligen Festzeiten des HERRN sowie für jeden, der dem HERRN eine freiwillige Gabe darbrachte.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 3, 6, 'Am ersten Tage des siebten Monats hatten sie angefangen, dem HERRN Brandopfer darzubringen, obgleich damals der Grundstein zum Tempel des HERRN noch nicht gelegt war.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 3, 7, 'Dann aber gaben sie den Steinhauern und Zimmerleuten Geld, außerdem Speise, Trank und Öl den Sidoniern und Tyriern, damit sie Zedernstämme vom Libanon auf dem Meere nach Japho brächten, wozu der König Kores von Persien ihnen die Erlaubnis erteilt hatte.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 3, 8, 'Im zweiten Jahre aber nach ihrer Rückkehr zum Gotteshause in Jerusalem, im zweiten Monat, machten Serubbabel, der Sohn Sealthiels, und Jesua, der Sohn Jozadaks, nebst ihren übrigen Genossen, den Priestern und den Leviten, überhaupt alle, die aus der Verbannung nach Jerusalem zurückgekehrt waren, den Anfang mit dem Bau und bestellten die Leviten von zwanzig Jahren an und darüber zu Aufsehern über die Arbeiten am Tempel des HERRN.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 3, 9, 'So standen denn Jesua nebst seinen Söhnen und Genossen, Kadmiel mit seinen Söhnen, die Söhne Hodawjas wie ein Mann da, um die Aufsicht über die Arbeiter am Hause Gottes zu führen, ebenso die Familie Henadad mit ihren Söhnen und Genossen, die Leviten.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 3, 10, 'Als nun die Bauleute den Grund zum Tempel des HERRN legten, nahmen die Priester in ihrer Amtstracht mit Trompeten und die Leviten, die Nachkommen Asaphs, mit Zimbeln Aufstellung, um dem HERRN nach der Anordnung Davids, des Königs von Israel, zu lobsingen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 3, 11, 'So stimmten sie denn zu Ehren des HERRN das Lob- und Danklied an: »Denn er ist freundlich, und seine Güte währet ewiglich über Israel.« Das ganze Volk erhob dann ein lautes Jubelgeschrei, während man den HERRN pries wegen der Grundsteinlegung zum Tempel des HERRN.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 3, 12, 'Viele aber von den Priestern, den Leviten und den Familienhäuptern, nämlich die alten Leute, die den früheren Tempel noch (mit eigenen Augen) gesehen hatten, begannen, als man den Grund zu diesem Hause legte, laut zu weinen, während die Menge ihre Stimmen zu freudigem Jubel erhob.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 3, 13, 'Man konnte aber den Schall des Freudengeschreis von dem lauten Weinen im Volke nicht unterscheiden, denn das Volk erhob ein gewaltiges Jubelgeschrei, so daß der Schall weithin zu hören war.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 4, 1, 'Als aber die Widersacher Judas und Benjamins vernahmen, daß die aus der Verbannung Zurückgekehrten dabei waren, dem HERRN, dem Gott Israels, einen Tempel zu bauen,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 4, 2, 'begaben sie sich zu Serubbabel und den Familienhäuptern und sagten zu ihnen: »Wir möchten zusammen mit euch bauen; denn wir verehren euren Gott ebenso wie ihr und wir opfern ihm seit der Zeit des Assyrerkönigs Assarhaddon, der uns hierhergebracht (hier angesiedelt) hat.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 4, 3, 'Aber Serubbabel und Jesua und die übrigen Familienhäupter der Israeliten antworteten ihnen: »Es geht nicht an, daß ihr und wir zusammen unserm Gott einen Tempel bauen, sondern wir wollen allein dem HERRN, dem Gott Israels, (einen Tempel) bauen, wie der König Kores, der König von Persien, uns geboten hat.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 4, 4, 'Da suchte die Bevölkerung des Landes dem jüdischen Volke Schwierigkeiten für sein Unternehmen zu schaffen und sie vom Bauen abzuschrecken;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 4, 5, 'auch gewannen sie durch Bestechung einflußreiche Männer (vom persischen Hofe) gegen sie, um ihr Vorhaben zu hintertreiben, solange der König Kores von Persien lebte und bis zur Regierung des Perserkönigs Darius.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 4, 6, 'Als aber Ahasveros zur Herrschaft gekommen war, verfaßten sie zu Anfang seiner Regierung eine Anklageschrift gegen die Bewohner von Juda und Jerusalem;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 4, 7, 'und unter der Regierung Arthasasthas richteten Bislam, Mithredath, Tabeel und alle seine Genossen an Arthasastha, den König von Persien, einen Bericht, der mit aramäischer Schrift geschrieben und ins Aramäische übersetzt war.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 4, 8, 'Der Statthalter Rehum und der Staatsschreiber Simsai verfaßten einen Bericht an den König Arthasastha gegen Jerusalem mit folgendem Wortlaut:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 4, 9, 'Der Statthalter Rehum und der Staatsschreiber Simsai und alle ihre Genossen, die Dinäer [und Apharsathchäer], die Tarpeläer, Apharsachäer, Arkewäer, Babylonier, Susaniter, Dehiter und Elamiter');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 4, 10, 'und alle übrigen Völkerschaften, die der große und erlauchte Osnappar weggeführt und in den Ortschaften Samarias und in den übrigen Gebieten jenseits des Euphrats angesiedelt hat, und so weiter: –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 4, 11, 'dies ist die Abschrift des Berichts, den sie an ihn sandten: »An den König Arthasastha: Deine Knechte, die Männer jenseits des Euphrats und so weiter.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 4, 12, 'Es sei dem König zu wissen getan, daß die Juden, die von dir zu uns heraufgezogen (und) nach Jerusalem gekommen sind, die aufrührerische und böse Stadt wieder aufbauen und ihre Mauern wieder herstellen und die Grundlagen ausbessern.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 4, 13, 'Darum sei dem Könige kundgetan, daß, wenn diese Stadt wieder aufgebaut wird und deren Mauern wiederhergestellt werden, sie keine Abgaben, keine Steuern und Zölle mehr entrichten werden, so daß schließlich das Königshaus Schaden davon haben wird.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 4, 14, 'Weil wir nun in Amt und Sold des königlichen Hofes stehen und es uns nicht geziemt, eine Schädigung des Königs ruhig mitanzusehen, deswegen senden wir diesen Bericht an den König,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 4, 15, 'damit man im Buche der Denkwürdigkeiten deiner Väter nachforsche. Du wirst dann im Buche der Denkwürdigkeiten finden und dich überzeugen, daß diese Stadt eine aufrührerische und für die Könige und Länder unheilvolle Stadt gewesen ist und daß seit den ältesten Zeiten Empörungen in ihr stattgefunden haben, weshalb diese Stadt ja auch zerstört worden ist.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 4, 16, 'Wir machen also den König darauf aufmerksam, daß, wenn diese Stadt wieder aufgebaut wird und ihre Mauern wiederhergestellt werden, du infolgedessen nicht im Besitz der Länder jenseits des Euphrats verbleiben wirst.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 4, 17, 'Da sandte der König folgende Antwort: »An den Statthalter Rehum und den Staatsschreiber Simsai und alle ihre Genossen, die in Samaria und den übrigen Gegenden jenseits des Euphrats ansässig sind: »Gruß euch! und so weiter.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 4, 18, 'Das Schreiben, das ihr uns habt zugehen lassen, ist mir Wort für Wort vorgelesen worden;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 4, 19, 'und nachdem Befehl von mir erteilt worden war, nachzuforschen, hat es sich herausgestellt, daß die betreffende Stadt sich seit den ältesten Zeiten gegen die Könige aufgelehnt hat und daß Aufruhr und Empörungen in ihr angestiftet worden sind.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 4, 20, 'Auch haben mächtige Könige in Jerusalem regiert und über alle Länder jenseits des Euphrats geherrscht, und Abgaben, Steuern und Zölle sind ihnen entrichtet worden.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 4, 21, 'So erlaßt nun den Befehl, daß jenen Männern der Wiederaufbau ihrer Stadt untersagt werde, bis von mir die Erlaubnis dazu erteilt wird;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 4, 22, 'und seid auf der Hut, eine Nachlässigkeit in dieser Sache vorkommen zu lassen, damit nicht große Schädigung zum Nachteil des Königshauses daraus erwächst!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 4, 23, 'Sobald hierauf die Abschrift des Erlasses des Königs Arthasastha vor Rehum und dem Staatsschreiber Simsai und ihren Genossen verlesen worden war, begaben sie sich eiligst nach Jerusalem zu den Juden und zwangen sie unter rücksichtsloser Anwendung von Gewalt zur Einstellung des Baues.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 4, 24, 'Damals hörte die Arbeit am Hause Gottes in Jerusalem auf und blieb eingestellt bis zum zweiten Regierungsjahr des Königs Darius von Persien.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 5, 1, 'Es weissagten aber der Prophet Haggai und der Prophet Sacharja, der Sohn Iddos, den Juden in Juda und Jerusalem im Namen des Gottes Israels, dessen Geist über ihnen war.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 5, 2, 'Daraufhin machten sich Serubbabel, der Sohn Sealthiels, und Jesua, der Sohn Jozadaks, daran, den Bau des Gotteshauses in Jerusalem aufs neue in Angriff zu nehmen, und mit ihnen waren die (beiden) Propheten Gottes, welche sie unterstützten.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 5, 3, 'Zu jener Zeit kamen Thathnai, der Statthalter der Provinz diesseits des Euphrats, und Sethar-Bosnai und deren Genossen zu ihnen und richteten die Frage an sie: »Wer hat euch die Erlaubnis gegeben, dieses Haus zu bauen und diese Mauer wiederherzustellen,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 5, 4, 'und welches sind die Namen der Männer, die diesen Bau betreiben?«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 5, 5, 'Aber das Auge ihres Gottes war auf die Ältesten der Juden gerichtet, so daß (jene) von ihnen nicht die Einstellung der Arbeit verlangten, bis ein Befehl des Darius vorläge und man ihnen dann einen schriftlichen Bescheid darüber zugehen ließe.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 5, 6, 'Abschrift des Berichts, den Thathnai, der Statthalter der Provinz diesseits des Euphrats, und Sethar-Bosnai und seine Genossen, die Apharsachäer, die in der Provinz diesseits des Euphrats wohnten, an den König Darius sandten.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 5, 7, 'Sie sandten nämlich einen Bericht an ihn, dessen Wortlaut folgender war: »Dem König Darius alles Heil!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 5, 8, 'Es sei dem Könige zu wissen getan, daß wir uns in die Landschaft Juda zum Hause des großen Gottes begeben haben; es wird aus Quadersteinen erbaut, und in die Wände werden Balken eingelegt; diese Arbeit wird eifrig betrieben und geht unter ihren Händen erfolgreich vonstatten.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 5, 9, 'Da haben wir an die Ältesten dort die Frage gerichtet: ›Wer hat euch den Befehl gegeben, dieses Haus zu bauen und diese Mauer wiederherzustellen?‹');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 5, 10, 'Und auch nach ihren Namen haben wir sie gefragt, um sie dir mitzuteilen, indem wir die Namen der Männer aufschrieben, die an ihrer Spitze stehen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 5, 11, 'Und folgendes ist die Auskunft, die sie uns gegeben haben: ›Wir sind die Knechte des Gottes des Himmels und der Erde und bauen das Haus wieder auf, das ehedem vor vielen Jahren hier gestanden hat und das ein großer israelitischer König erbaut und aufgeführt hatte.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 5, 12, 'Weil aber unsere Väter den Gott des Himmels erzürnt hatten, hat er sie der Gewalt des Königs Nebukadnezar von Babylon, des Chaldäers, preisgegeben; der hat dieses Haus zerstört und das Volk gefangen nach Babylon geführt.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 5, 13, 'Doch im ersten Jahre der Regierung des Königs Kores über Babylon hat der König Kores den Befehl gegeben, dieses Gotteshaus wieder aufzubauen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 5, 14, 'Auch die goldenen und silbernen Geräte des Gotteshauses, die Nebukadnezar aus dem Tempel zu Jerusalem weggenommen und in (seinen) Tempel zu Babylon gebracht hatte, hat der König Kores aus dem Tempel zu Babylon hervornehmen lassen und sie einem Manne namens Sesbazzar ausgeliefert, den er zum Statthalter (in Judäa) eingesetzt hatte,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 5, 15, 'indem er diesem auftrug: Nimm diese Geräte, gehe hin und lege sie im Tempel zu Jerusalem nieder; das Gotteshaus aber soll an seiner früheren Stelle wieder aufgebaut werden!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 5, 16, 'Daraufhin ist der betreffende Sesbazzar hergekommen und hat den Grundstein zum Gotteshause in Jerusalem gelegt; und seit jener Zeit wird bis heute daran gebaut, es ist aber noch nicht vollendet.‹');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 5, 17, 'Demnach möge man, wenn es dem Könige beliebt, im königlichen Schatzhause dort in Babylon nachforschen, ob es sich wirklich so verhält, daß vom Könige Kores der Befehl gegeben worden ist, dieses Gotteshaus in Jerusalem wieder aufzubauen. Der König wolle uns dann seine Entscheidung in dieser Sache zukommen lassen.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 6, 1, 'Als hierauf der König Darius anordnete, im Schatzhause, in welchem man auch die Urkunden in Babylon aufbewahrte, nachzusehen,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 6, 2, 'fand man in Ahmetha, in der Königsstadt, die in der Landschaft Medien liegt, eine Schriftrolle, in der folgendes geschrieben stand:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 6, 3, '»Urkunde: Im ersten Regierungsjahre des Königs Kores erließ der König Kores den Befehl: ›Was das Gotteshaus in Jerusalem betrifft, so soll dieses Haus wieder aufgebaut werden als eine Stätte, wo man Schlachtopfer schlachtet und Feueropfer darbringt; seine Höhe soll sechzig Ellen, seine Breite auch sechzig Ellen betragen;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 6, 4, 'Schichten von Quadersteinen sollen drei vorhanden sein und eine Schicht von Holzbalken; die Kosten aber sollen aus der königlichen Kasse bestritten werden.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 6, 5, 'Auch die goldenen und silbernen Geräte des Gotteshauses, die Nebukadnezar aus dem Tempel zu Jerusalem weggenommen und nach Babylon gebracht hat, sollen zurückgegeben werden, so daß jedes Stück wieder in den Tempel zu Jerusalem an seinen früheren Ort gelangt; und man soll sie in dem Gotteshause niederlegen!‹«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 6, 6, '»Nun denn, Thathnai, Statthalter der Provinz jenseits des Euphrats, und du, Sethar-Bosnai, und eure Genossen, die Apharsachäer, die ihr jenseits des Euphrats wohnt, haltet euch fern von dort!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 6, 7, 'Laßt die Arbeiten an diesem Gotteshause ungestört fortgehen: der Statthalter von Judäa und die Ältesten der Juden mögen dieses Gotteshaus an seiner alten Stelle wieder aufbauen!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 6, 8, 'Auch ist von mir eine Verfügung erlassen worden bezüglich der Leistungen, die ihr jenen Ältesten der Juden für den Bau dieses Gotteshauses zu gewähren habt, nämlich daß von den Steuererträgen des Königs aus der Provinz jenseits des Euphrats die Kosten jenen Männern genau erstattet werden, und zwar unverzüglich.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 6, 9, 'Und was (sonst) erforderlich ist sowohl an jungen Stieren als auch an Widdern und Lämmern zu Brandopfern für den Gott des Himmels sowie an Weizen, Salz, Wein und Öl, das soll ihnen nach der Anforderung der Priester zu Jerusalem Tag für Tag unweigerlich geliefert werden,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 6, 10, 'damit sie dem Gott des Himmels lieblichen Opferduft darbringen und für das Leben des Königs und seiner Söhne beten.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 6, 11, 'Weiter ist von mir verordnet worden, daß jedem, der an dieser Verfügung etwas ändern sollte, ein Pfosten aus seinem Hause herausgerissen und er selbst gepfählt daran aufgehängt und sein Haus wegen solchen Vergehens zu einem Schutthaufen gemacht werden soll.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 6, 12, 'Der Gott aber, der seinen Namen dort dauernd wohnen läßt, möge jeden König und jedes Volk stürzen, die es unternehmen sollten, diese Verfügung zu übertreten, um dieses Gotteshaus in Jerusalem zu zerstören. Ich, Darius, habe den Befehl erlassen: er soll genau vollzogen werden!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 6, 13, 'Darauf verfuhren Thathnai, der Statthalter der Provinz Syrien, und Sethar-Bosnai nebst ihren Genossen genau nach dem Befehl, den der König Darius ihnen hatte zugehen lassen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 6, 14, 'So konnten denn die Ältesten der Juden weiterbauen, und die Arbeit ging erfolgreich vonstatten gemäß der Weissagung der Propheten, nämlich Haggais und Sacharjas, des Sohnes Iddos, so daß sie den Bau zu Ende führten nach dem Befehl des Gottes Israels und nach dem Befehl des Kores und des Darius und des Königs Arthasastha von Persien.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 6, 15, 'Sie stellten aber dieses Haus fertig bis zum dritten Tage des Monats Adar, und zwar war es das sechste Regierungsjahr des Königs Darius.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 6, 16, 'Da feierten denn die Israeliten, die Priester, die Leviten und die übrigen aus der Gefangenschaft Zurückgekehrten die Einweihung dieses Gotteshauses mit einem Freudenfest');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 6, 17, 'und opferten zur Einweihung dieses Gotteshauses hundert Stiere, zweihundert Widder, vierhundert Lämmer als Brandopfer und als Sündopfer für ganz Israel zwölf Ziegenböcke nach der Zahl der israelitischen Stämme.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 6, 18, 'Sie setzten dann auch die Priester in ihr Amt ein nach ihren Abteilungen und die Leviten nach ihren Klassen für den Gottesdienst in Jerusalem, wie es im Buche Moses vorgeschrieben ist.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 6, 19, 'Hierauf begingen die aus der Gefangenschaft Zurückgekehrten das Passah am vierzehnten Tage des ersten Monats;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 6, 20, 'denn die Priester und die Leviten hatten sich ohne Ausnahme gereinigt; sie waren allesamt rein und schlachteten das Passah für alle aus der Gefangenschaft Zurückgekehrten und für ihre Geschlechtsgenossen, die Priester, und für sich selbst.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 6, 21, 'Es aßen aber (das Passah) sowohl die Israeliten, die aus der Gefangenschaft zurückgekehrt waren, als auch alle, die sich von der Unreinheit der (heidnischen) Bevölkerung des Landes losgesagt und sich ihnen angeschlossen hatten, um den HERRN, den Gott Israels, zu verehren.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 6, 22, 'Dann begingen sie das Fest der ungesäuerten Brote sieben Tage lang mit Freuden; denn der HERR hatte sie Freude erleben lassen, indem er ihnen das Herz des Königs von Assyrien zugewandt hatte, so daß er ihre Arbeit beim Bau des Hauses Gottes, des Gottes Israels, kräftig unterstützte.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 7, 1, 'Nach diesen Begebenheiten nun unter der Regierung des Perserkönigs Arthasastha zog Esra, der Sohn Serajas, des Sohnes Asarjas, des Sohnes Hilkias,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 7, 2, 'des Sohnes Sallums, des Sohnes Zadoks, des Sohnes Ahitubs,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 7, 3, 'des Sohnes Amarjas, des Sohnes Asarjas, des Sohnes Merajoths,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 7, 4, 'des Sohnes Serahjas, des Sohnes Ussis, des Sohnes Bukkis,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 7, 5, 'des Sohnes Abisuas, des Sohnes des Pinehas, des Sohnes Eleasars, des Sohnes des Oberpriesters Aaron –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 7, 6, 'eben dieser Esra zog von Babylon herauf. Er war ein Schriftgelehrter, wohlbewandert im mosaischen Gesetz, das der HERR, der Gott Israels, gegeben hatte; und weil die gütige Hand des HERRN, seines Gottes, über ihm waltete, hatte der König ihm alles bewilligt, um was er gebeten hatte.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 7, 7, 'So zog denn mit ihm ein Teil der Israeliten und der Priester, Leviten, Sänger, Torhüter und Tempelhörigen im siebten Regierungsjahre des Königs Arthasastha nach Jerusalem hinauf;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 7, 8, 'und er gelangte nach Jerusalem im fünften Monat dieses siebten Regierungsjahres des Königs.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 7, 9, 'Auf den ersten Tag des ersten Monats nämlich hatte Esra den Aufbruch von Babylon festgesetzt, und am ersten Tage des fünften Monats kam er in Jerusalem an, weil die gütige Hand seines Gottes über ihm waltete;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 7, 10, 'denn Esra hatte sein Streben fest darauf gerichtet, das Gesetz des HERRN zu erforschen und durchzuführen und in Israel Satzung und Recht zu lehren.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 7, 11, 'Folgendes ist nun die Abschrift des Schreibens, das der König Arthasastha dem schriftgelehrten Priester Esra, der ein Gelehrter in den Worten der Gebote des HERRN und seiner Satzungen für Israel war, mitgegeben hatte:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 7, 12, '»Arthasastha, der König der Könige, wünscht dem Priester Esra, der ein vollkommener Gelehrter im Gesetz des Himmelsgottes ist, Heil und so weiter.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 7, 13, 'Von mir ergeht hiermit der Befehl, daß ein jeder, der in meinem Reiche vom Volk Israel und von seinen Priestern und Leviten gewillt ist, nach Jerusalem zu ziehen, mit dir soll ziehen dürfen,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 7, 14, 'weil du ja doch vom Könige und seinen sieben Räten gesandt bist, um über die Verhältnisse in Juda und Jerusalem eine Untersuchung anzustellen auf Grund des Gesetzes deines Gottes, das du in deinen Händen hast,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 7, 15, 'und um das Silber und Gold dorthin zu bringen, welches der König und seine Räte dem Gott Israels, dessen Wohnsitz in Jerusalem ist, als Weihgeschenk gespendet haben');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 7, 16, 'sowie alles Silber und Gold, welches du in der ganzen Landschaft Babylon erhalten wirst, mitsamt den Weihgeschenken des Volkes und der Priester, welche freiwillige Gaben für das Haus ihres Gottes in Jerusalem spenden werden.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 7, 17, 'Dementsprechend sollst du für dieses Geld gewissenhaft Stiere, Widder und Lämmer nebst den zugehörigen Speisopfern und den erforderlichen Trankopfern kaufen und sollst sie auf dem Altar eures Gotteshauses in Jerusalem darbringen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 7, 18, 'Was dann dir und deinen Genossen mit dem übrigen Silber und Gold zu tun gut erscheint, das mögt ihr nach dem Willen eures Gottes tun.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 7, 19, 'Ferner sollst du die Geräte, die dir für den Dienst im Hause deines Gottes übergeben werden, vollzählig vor dem Gott zu Jerusalem abliefern.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 7, 20, 'Und den weiteren Bedarf des Hauses deines Gottes, alle Kosten, deren Bestreitung dir etwa obliegen wird, darfst du aus der königlichen Schatzkammer decken lassen;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 7, 21, 'es wird nämlich von mir, dem Könige Arthasastha, hiermit allen Schatzmeistern in der Provinz jenseits des Euphrats der Befehl erteilt: Alles, was der Priester Esra, der im Gesetz des Himmelsgottes gelehrte Mann, von euch verlangen wird, soll pünktlich geleistet werden,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 7, 22, 'bis zu hundert Talenten Silber und bis zu hundert Kor Weizen und bis zu hundert Bath Wein und hundert Bath Öl, dazu Salz in unbeschränkter Menge.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 7, 23, 'Alles, was nach dem Befehl des Himmelsgottes erforderlich ist, soll für das Haus des Himmelsgottes sorgfältig geleistet werden, damit nicht etwa ein Zorngericht das Reich des Königs und seiner Söhne trifft.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 7, 24, 'Weiter sei euch hiermit kundgetan, daß niemand berechtigt sein soll, irgendeinem Priester und Leviten, Sänger, Torhüter, Tempelhörigen, kurz irgendeinem Diener dieses Gotteshauses eine Geldabgabe, eine Steuer oder Zölle aufzuerlegen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 7, 25, 'Du aber, Esra, setze gemäß der Weisheit (des Gesetzes) deines Gottes, das in deinen Händen ist, Richter und Rechtspfleger ein, die dem gesamten Volke in der Provinz jenseits des Euphrats Recht sprechen sollen, nämlich allen denen, welche die Gesetze deines Gottes kennen, und wer sie noch nicht kennt, dem sollt ihr Belehrung zuteil werden lassen!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 7, 26, 'Jeder aber, der dem Gesetz deines Gottes und dem Gesetz des Königs nicht nachkommt, gegen den soll gerichtlich mit Strenge vorgegangen werden, es sei mit Todesstrafe oder Verbannung, mit Geldbuße oder Gefängnis!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 7, 27, '»Gepriesen sei der HERR, der Gott unserer Väter, der dem Könige den Entschluß ins Herz gegeben hat, das Haus des HERRN in Jerusalem zu verherrlichen,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 7, 28, 'und der mich Gnade bei dem Könige und seinen Räten und bei allen einflußreichen Würdenträgern des Königs hat finden lassen, so daß ich, weil die Hand des HERRN, meines Gottes, schützend über mir waltete, den Mut gewann, Familienhäupter aus Israel um mich zu sammeln, damit sie mit mir nach Jerusalem hinaufzögen!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 1, 'Folgendes ist das Verzeichnis der Familienhäupter nebst der Angabe ihrer Geschlechtszugehörigkeit, nämlich derer, die unter der Regierung des Königs Arthasastha mit mir von Babylon (nach Jerusalem) hinaufgezogen sind:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 2, 'Von den Nachkommen des Pinehas: Gersom; von den Nachkommen Ithamars: Daniel; von den Nachkommen Davids: Hattus,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 3, '(der Sohn) Sechanjas; von den Nachkommen des Parhos: Sacharja, und mit ihm waren aufgezeichnet an männlichen Personen 150;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 4, 'von den Nachkommen Pahath-Moabs: Eljehoenai, der Sohn Serahjas, und mit ihm 200 männliche Personen;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 5, 'von den Nachkommen Satthus: Sechanja, der Sohn Jahasiels, und mit ihm 300 männliche Personen;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 6, 'von den Nachkommen Adins: Ebed, der Sohn Jonathans, und mit ihm 50 männliche Personen;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 7, 'von den Nachkommen Elams: Jesaja, der Sohn Athaljas, und mit ihm 70 männliche Personen;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 8, 'von den Nachkommen Sephatjas: Sebadja, der Sohn Michaels, und mit ihm 80 männliche Personen;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 9, 'von den Nachkommen Joabs: Obadja, der Sohn Jehiels, und mit ihm 218 männliche Personen;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 10, 'von den Nachkommen (Banis): Selomith, der Sohn Josiphjas, und mit ihm 160 männliche Personen;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 11, 'von den Nachkommen Bebais: Sacharja, der Sohn Bebais, und mit ihm 28 männliche Personen;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 12, 'von den Nachkommen Asgads: Johanan, der Sohn Hakkatans, und mit ihm 110 männliche Personen;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 13, 'von den Nachkommen Adonikams: Spätlinge, und dies sind ihre Namen: Eliphelet, Jehiel und Semaja, und mit ihnen 60 männliche Personen;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 14, 'von den Nachkommen Bigwais: Uthai und Sabbud, und mit ihnen 70 männliche Personen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 15, 'Ich ließ sie dann an dem Flusse, der nach Ahawa fließt, zusammenkommen, und wir lagerten dort drei Tage lang. Als ich da nun wohl das Volk und die Priester wahrnahm, aber von den Leviten keinen einzigen dort fand,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 16, 'sandte ich Elieser, Ariel, Semaja, Elnathan, Jarib, Elnathan, Nathan, Sacharja und Mesullam, lauter Familienhäupter, sowie Jojarib und Elnathan, beides einsichtige Männer, ab');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 17, 'und beauftragte sie, sich zu Iddo, dem Vorsteher in der Ortschaft Kasiphja, zu begeben; dabei gab ich ihnen genau die Worte an, die sie an Iddo und seine Genossen in der Ortschaft Kasiphja richten sollten, nämlich daß sie uns Diener für das Haus unseres Gottes zuführen möchten.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 18, 'Da brachten sie uns, weil die gütige Hand unsers Gottes über uns waltete, einen einsichtsvollen Mann von den Nachkommen Mahlis, des Sohnes Levis, des Sohnes Israels, nämlich Serebja samt seinen Söhnen und Genossen, 18 an der Zahl,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 19, 'ferner Hasabja und mit ihm Jesaja von den Nachkommen Meraris samt ihren Genossen und deren Söhnen, 20 Mann;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 20, 'und von den Tempelhörigen, die David und die Fürsten den Leviten zu Dienstleistungen überwiesen hatten, 220 Mann; sie sind alle mit Namen verzeichnet.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 21, 'Ich ließ nun dort am Flusse Ahawa ein Fasten ausrufen, damit wir uns vor unserm Gott demütigten, um von ihm eine glückliche Reise für uns und unsere Familien und für alle unsere Habe zu erflehen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 22, 'Ich hatte mich nämlich geschämt, den König um eine bewaffnete Mannschaft und um Reiter zu bitten, die uns unterwegs gegen Feinde hätten schützen können; wir hatten vielmehr dem Könige erklärt: »Die Hand unsers Gottes waltet über allen, die ihn suchen, zu ihrem Heil, aber seine Macht und sein Zorn trifft alle, die ihn verlassen.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 23, 'So fasteten wir denn und flehten unsern Gott in dieser Sache um Hilfe an, und er ließ sich von uns erbitten.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 24, 'Hierauf wählte ich aus den obersten Priestern zwölf aus, ferner auch Serebja und Hasabja und mit ihnen zehn von ihren Genossen,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 25, 'und wog ihnen das Silber und das Gold und die Geräte dar, das Weihgeschenk für das Haus unsers Gottes, das der König samt seinen Räten und Würdenträgern sowie alle dort wohnhaften Israeliten gespendet hatten.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 26, 'Ich wog ihnen also in ihre Hand dar: an Silber 650 Talente, an silbernen Geräten 100 Talente, an Gold 100 Talente;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 27, 'ferner 20 goldene Becher im Werte von 1000 Goldstücken und zwei Gefäße von Golderz, kostbar wie Gold.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 28, 'Dabei sagte ich zu ihnen: »Ihr seid dem HERRN heilig, und die Geräte sind auch heilig, und das Silber und das Gold ist ein Weihgeschenk für den HERRN, den Gott eurer Väter.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 29, 'Seid also wachsam und hütet es, bis ihr es vor den obersten Priestern und Leviten und den obersten Familienhäuptern der Israeliten zu Jerusalem in den Zellen des Tempels des HERRN darwägen könnt!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 30, 'Darauf nahmen die Priester und die Leviten das ihnen zugewogene Silber und Gold und die Geräte in Empfang, um sie nach Jerusalem in das Haus unsers Gottes zu bringen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 31, 'Hierauf brachen wir am zwölften Tage des ersten Monats vom Flusse Ahawa auf, um nach Jerusalem zu ziehen; und die Hand unsers Gottes beschützte uns, und er behütete uns vor (Angriffen von) Feinden und Straßenräubern.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 32, 'So kamen wir denn in Jerusalem an und ruhten dort drei Tage lang aus.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 33, 'Am vierten Tage aber wurden das Silber und das Gold und die Geräte im Hause unsers Gottes dem Priester Meremoth, dem Sohne Urias, in die Hand dargewogen – außer diesem war noch Eleasar, der Sohn des Pinehas, zugegen und außer diesen beiden noch die Leviten Josabad, der Sohn Jesuas, und Noadja, der Sohn Binnuis –;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 34, 'alles wurde damals gezählt und nachgewogen und das Gesamtgewicht aufgeschrieben. –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 35, 'Als dann die aus der Gefangenschaft heimgekehrten Verbannten dem Gott Israels Brandopfer dargebracht hatten, nämlich 12 Stiere für ganz Israel, 96 Widder, 77 Lämmer und zum Sündopfer 12 Böcke, das alles als Brandopfer für den HERRN,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 36, 'übergaben sie die Befehle des Königs den königlichen Satrapen und Statthaltern der Provinz auf der Westseite des Euphrats, worauf diese das Volk und das Gotteshaus unterstützten.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 9, 1, 'Als nun dieses abgemacht war, traten die Obersten zu mir und sagten: »Das Volk Israel, auch die Priester und die Leviten haben sich von den Völkerschaften des Landes, trotz deren greulichem Götzendienst, nicht abgesondert gehalten, nämlich von den Kanaanäern, Hethitern, Pherissitern, Jebusitern, Ammonitern, Moabitern, Ägyptern und Amoritern;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 9, 2, 'sie haben vielmehr von deren Töchtern Frauen für sich und ihre Söhne genommen, und so hat sich der heilige Same mit den (heidnischen) Völkerschaften des Landes vermischt, und die Obersten und Vorsteher haben zu dieser Treulosigkeit zuerst die Hand geboten.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 9, 3, 'Als ich diese Mitteilung vernahm, zerriß ich mir das Gewand und den Mantel, raufte mir das Haar aus Kopf und Bart aus und setzte mich erstarrt nieder.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 9, 4, 'Da versammelten sich um mich alle, die in Angst waren vor den Worten des Gottes Israels wegen des Frevels der aus der Gefangenschaft Zurückgekehrten; ich aber saß erstarrt da bis zum Abendopfer.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 9, 5, 'Um die Zeit des Abendopfers aber erhob ich mich von meiner Selbstdemütigung, in der ich mein Gewand und meinen Mantel zerrissen hatte, warf mich auf die Knie nieder, breitete meine Hände zum HERRN, meinem Gott, aus');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 9, 6, 'und betete: »Mein Gott! Ich schäme mich und erröte, mein Angesicht zu dir, mein Gott, zu erheben; denn unsere Missetaten sind uns über das Haupt gewachsen, und unsere Schuld ist groß geworden bis an den Himmel!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 9, 7, 'Seit den Tagen unserer Väter stehen wir in großer Schuld bis auf den heutigen Tag, und um unserer Missetaten willen sind wir, unsere Könige und unsere Priester, der Gewalt der Könige der (heidnischen) Länder preisgegeben worden, dem Schwert, der Gefangenschaft, der Plünderung und schmachvollsten Entehrung, wie es noch heutigen Tages der Fall ist.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 9, 8, 'Jetzt ist uns zwar für einen kurzen Augenblick Gnade vom HERRN, unserm Gott, dadurch widerfahren, daß er uns einen Rest Geretteter übriggelassen und uns an der Stätte seines Heiligtums einen Zeltpflock geschenkt hat, damit unser Gott unsere Augen wieder leuchten mache und uns in unserer Knechtschaft ein wenig aufleben lasse.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 9, 9, 'Denn ob wir auch Knechte sind, hat unser Gott uns doch in unserer Knechtschaft nicht verlassen, sondern hat uns die Huld der Könige von Persien zugewandt, so daß er uns ein Aufleben vergönnt hat, um das Haus unsers Gottes wieder aufzubauen und es aus seinen Trümmern wieder erstehen zu lassen und uns eine Mauer in Juda und Jerusalem zu gewähren.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 9, 10, 'Jetzt aber, o unser Gott – was sollen wir nach solchen Vorkommnissen sagen? Wir haben ja deine Gebote unbeachtet gelassen,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 9, 11, 'die du uns durch deine Knechte, die Propheten, zur Pflicht gemacht hast mit den Worten: ›Das Land, in welches ihr zieht, um es in Besitz zu nehmen, ist ein Land, das infolge der Unreinheit der heidnischen Völkerschaften befleckt ist infolge ihrer Götzengreuel, mit denen sie es bei ihrer Unreinheit von einem Ende bis zum andern angefüllt haben.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 9, 12, 'So sollt ihr nun eure Töchter nicht ihren Söhnen zu Frauen geben und ihre Töchter nicht für eure Söhne zu Frauen nehmen und nun und nimmer auf ihre Wohlfahrt und ihr Wohlergehen bedacht sein, damit ihr stark bleibt und die Güter des Landes genießt und es auf eure Söhne für ewige Zeiten vererbt.‹');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 9, 13, 'Und nun nach allem Unheil, das uns infolge unserer bösen Taten und unserer großen Schuld widerfahren ist – wiewohl du, unser Gott, größere Schonung gegen uns geübt hast, als unsere Sünden verdient haben, und uns diesen geretteten Rest hier geschenkt hast –:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 9, 14, 'sollten wir da aufs neue deine Gebote übertreten und uns mit diesen Greuelvölkern verschwägern? Müßtest du uns da nicht bis zur Vernichtung zürnen, so daß niemand mehr (von uns) übrig bliebe noch entrinnen könnte?');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 9, 15, 'O HERR, Gott Israels! Du bist gerecht darin, daß wir nur noch als ein Rest von Geretteten übriggeblieben sind, wie es heutigentags der Fall ist: Ach, siehe, wir stehen hier vor dir in unserer Schuld! Bei solchem Verhalten kann unmöglich jemand vor dir bestehen!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 1, 'Während nun Esra so betete und weinend und vor dem Hause Gottes hingestreckt sein Bußbekenntnis ablegte, sammelte sich um ihn eine sehr große Schar von Israeliten, Männer, Frauen und Kinder; denn das Volk war in heftiges Weinen ausgebrochen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 2, 'Da nahm Sechanja, der Sohn Jehiels, aus der Familie Elam, das Wort und sagte zu Esra: »Wir haben uns an unserm Gott versündigt, daß wir fremde Frauen aus den Völkerschaften des Landes geheiratet haben; aber trotzdem ist auch jetzt noch Hoffnung für Israel vorhanden.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 3, 'Wir wollen uns jetzt unserm Gott gegenüber feierlich verpflichten, alle fremden Frauen und die von diesen geborenen Kinder aus dem Hause zu entfernen nach deinem Rat, o Herr, und nach dem Rat derer, die das Gebot unsers Gottes fürchten, damit nach dem Gesetz verfahren wird!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 4, 'Stehe auf, denn dir obliegt die Sache! Wir wollen zu dir halten: sei entschlossen und handle!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 5, 'Da stand Esra auf und ließ die Obersten der Priester und der Leviten und des gesamten Israels schwören, daß sie wirklich nach diesem Vorschlage verfahren wollten; und sie legten den Eid ab.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 6, 'Hierauf stand Esra von dem Platz vor dem Hause Gottes auf und begab sich in die Zelle Johanans, des Sohnes Eljasibs; er brachte dort die Nacht zu, ohne Speise und Trank zu sich zu nehmen; denn er war tief betrübt über den Frevel der aus der Gefangenschaft Zurückgekehrten.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 7, 'Hierauf ließ man in ganz Juda und Jerusalem durch Ausruf bekannt machen, alle aus der Gefangenschaft Zurückgekehrten sollten sich in Jerusalem versammeln;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 8, 'und jeder, der nicht binnen drei Tagen gemäß dem Beschluß der Obersten und Ältesten erschiene, dessen gesamtes Vermögen solle dem Bann verfallen und er selbst aus der Gemeinde der aus der Gefangenschaft Heimgekehrten ausgeschlossen werden.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 9, 'Da versammelten sich denn alle Männer von Juda und Benjamin in Jerusalem nach Ablauf dreier Tage, nämlich am zwanzigsten Tage des neunten Monats; und das ganze Volk saß auf dem freien Platze vor dem Hause Gottes, zitternd wegen der vorliegenden Angelegenheit und infolge des kalten Regenwetters.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 10, 'Da stand der Priester Esra auf und sprach zu ihnen: »Ihr habt euch schwer versündigt, indem ihr fremde Frauen ins Haus genommen und dadurch die Schuld Israels noch vergrößert habt!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 11, 'So legt nun ein Schuldbekenntnis vor dem HERRN, dem Gott eurer Väter, ab und tut, was ihm wohlgefällig ist! Sondert euch von den Völkerschaften des Landes und von den fremden Frauen ab!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 12, 'Da antwortete die ganze Versammlung und rief laut: »Ja, es ist unsere Pflicht, so zu tun, wie du gesagt hast!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 13, 'Aber das Volk ist zahlreich, und dazu ist jetzt die Regenzeit, so daß man sich unmöglich im Freien aufhalten kann; auch läßt sich die Sache nicht an einem oder zwei Tagen abmachen, denn wir haben uns allzu vielfacher Übertretungen in dieser Beziehung schuldig gemacht.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 14, 'So mögen denn unsere Obersten für die ganze Gemeinde eintreten, und dann sollen alle, die in unsern Ortschaften fremde Frauen heimgeführt haben, zu festzusetzenden Zeiten kommen und mit ihnen die Ältesten der betreffenden Ortschaften und deren Richter, bis die Zornglut unsers Gottes um dieser Sache willen von uns abgewandt ist.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 15, 'Nur Jonathan, der Sohn Asahels, und Jahseja, der Sohn Thikwas, traten gegen diesen Vorschlag auf, und Masullam und der Levit Sabbethai unterstützten sie;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 16, 'aber die übrigen aus der Gefangenschaft Zurückgekehrten verfuhren nach dem Vorschlage, und der Priester Esra erwählte sich Männer, nämlich Familienhäupter nach den einzelnen Familien – sie sind alle mit Namen aufgezeichnet. Diese hielten dann am ersten Tage des zehnten Monats (ihre erste) Sitzung ab, um die Sache zu untersuchen,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 17, 'und sie erledigten die ganze Angelegenheit bezüglich der Männer, welche fremde Frauen geheiratet hatten, bis zum ersten Tage des ersten Monats.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 18, 'Es hatten sich aber unter den zur Priesterschaft Gehörigen folgende gefunden, die fremde Frauen geheiratet hatten: aus der Familie Jesuas, des Sohnes Jozadaks, und von seinen Genossen: Maaseja, Elieser, Jarib und Gedalja;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 19, 'sie versprachen mit Handschlag, ihre Frauen entlassen zu wollen, und sie brachten als Schuldopfer einen Widder für ihre Verschuldung dar.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 20, 'Ferner aus der Familie Immer: Hanani und Sebadja;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 21, 'aus der Familie Harim: Maaseja, Elia, Semaja, Jehiel und Ussia;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 22, 'aus der Familie Pashur: Eljoenai, Maaseja, Ismael, Nethaneel, Josabad und Elasa. –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 23, 'Sodann von den Leviten: Josabad, Simei, Kelaja (das ist Kelita), Pethahja, Juda und Elieser. –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 24, 'Sodann von den Sängern: Eljasib; und von den Torhütern: Sallum, Telem und Uri. –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 25, 'Von den übrigen Israeliten aber: aus der Familie Parhos: Ramja, Jissia, Malkia, Mijamin, Eleasar, Malkia und Benaja;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 26, 'aus der Familie Elam: Matthanja, Sacharja, Jehiel, Abdi, Jeremoth und Elia;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 27, 'aus der Familie Satthu: Eljoenai, Eljasib, Matthanja, Jeremoth, Sabad und Asisa;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 28, 'aus der Familie Bebai: Johanan, Hananja, Sabbai und Athlai;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 29, 'aus der Familie Bani: Mesullam, Malluch und Adaja, Jasub und Seal, Jeremoth;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 30, 'aus der Familie Pahath-Moab: Adna, Kelal, Benaja, Maaseja, Matthanja, Bezaleel und Binnui und Manasse;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 31, 'aus der Familie Harim: Elieser, Jissia, Malkia, Semaja, Simeon,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 32, 'Benjamin, Malluch, Semarja;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 33, 'aus der Familie Hasum: Matthenai, Matthattha, Sabad, Eliphelet, Jeremai, Manasse, Simei;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 34, 'aus der Familie Bani: Maadai, Amram und Uel,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 35, 'Benaja, Bedja, Keluhi,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 36, 'Wanja, Meremoth, Eljasib,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 37, 'Matthanja, Matthenai, Jaasai,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 38, 'Bani, Binnui, Simei,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 39, 'Selemja, Nathan, Adaja,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 40, 'Machnadbai, Sasai, Sarai,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 41, 'Asrael und Selemja, Semarja,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 42, 'Sallum, Amarja, Joseph;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 43, 'aus der Familie Nebo: Jehiel, Matthithja, Sabad, Sebina, Jaddai und Jole, Benaja.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 44, 'Alle diese hatten fremde Frauen geheiratet, und es befanden sich unter ihnen Frauen, welche Kinder geboren hatten.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 1, 1, 'Die Worte Nehemias, des Sohnes Hachaljas. Es begab sich im Monat Kislew im zwanzigsten Regierungsjahre des Königs Arthasastha, als ich mich in der Königsstadt Susa befand,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 1, 2, 'daß Hanani, einer von meinen Brüdern, mit einigen Männern aus Juda (zu mir) kam. Als ich mich nun bei ihnen nach den Juden, die in der Heimat zurückgeblieben und der Wegführung entgangen waren, und nach (den Verhältnissen in) Jerusalem erkundigte,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 1, 3, 'teilten sie mir mit: »Die Übriggebliebenen, die dort in der Provinz der (Wegführung in die) Gefangenschaft entgangen sind, befinden sich in großem Elend und in schmachvoller Lage; die Mauern Jerusalems sind niedergerissen und die Tore der Stadt mit Feuer verbrannt.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 1, 4, 'Als ich diese Mitteilungen vernahm, setzte ich mich (auf den Boden) hin und fing an zu weinen und trug tagelang Trauer unter beständigem Fasten und Flehen und richtete an den Gott des Himmels folgendes Gebet:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 1, 5, '»Ach HERR, du Gott des Himmels, du großer und furchtbarer Gott, der du denen, die dich lieben und deine Gebote halten, Bundestreue und Gnade bewahrst:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 1, 6, 'laß doch deine Ohren aufmerken und deine Augen geöffnet sein, daß du das Gebet deines Knechtes vernimmst, welches ich jetzt Tag und Nacht für die Kinder Israel, deine Knechte, vor dir bete und in welchem ich die Sünden bekenne, die wir Israeliten gegen dich begangen haben! Denn auch ich und meines Vaters Haus haben gesündigt.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 1, 7, 'Gar verwerflich haben wir gegen dich gehandelt, daß wir die Gebote, Satzungen und Anordnungen, die du deinem Knechte Mose geboten hast, nicht befolgt haben.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 1, 8, 'Ach, gedenke doch der Verheißung, die du deinem Knechte Mose gegeben hast mit den Worten:: ›Wenn ihr treulos handelt, so werde ich euch unter die Völker zerstreuen;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 1, 9, 'wenn ihr aber zu mir umkehrt und meine Gebote beobachtet und danach tut, so will ich, wenn sich auch Versprengte von euch am Ende des Himmels befinden sollten, sie doch von dort sammeln und sie an die Stätte zurückbringen, die ich erwählt habe, um meinen Namen dort wohnen zu lassen!‹');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 1, 10, 'Sie sind ja doch deine Knechte und dein Volk, das du durch deine große Kraft und deinen starken Arm erlöst hast!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 1, 11, 'Ach, HERR, laß doch dein Ohr aufmerken auf das Gebet deines Knechtes und auf das Gebet deiner Knechte, die gewillt sind (ihre Freude daran haben), deinen Namen zu fürchten! Laß es doch heute deinem Knecht gelingen und laß ihn Erbarmen finden bei dem Manne hier!« Ich war nämlich Mundschenk beim König.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 2, 1, 'Nun begab es sich im Monat Nisan im zwanzigsten Regierungsjahre des Königs Arthasastha, als der Wein vor mir stand, da trug ich den Wein auf und reichte ihn dem Könige; ich hatte aber früher nie betrübt vor ihm ausgesehen,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 2, 2, 'und so fragte mich der König: »Warum siehst du so betrübt aus? Du bist doch nicht krank? Das kann nichts anderes als Herzenskummer sein!« Da geriet ich in große Furcht,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 2, 3, 'antwortete aber doch dem König: »Lang lebe der König! Wie sollte ich nicht traurig aussehen, da doch die Stadt, in der sich die Gräber meiner Väter befinden, in Trümmern liegt und ihre Tore vom Feuer verzehrt sind?«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 2, 4, 'Als der König mich nun fragte: »Um was bittest du denn (unter diesen Umständen)?«, da betete ich zum Gott des Himmels');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 2, 5, 'und sagte dann zum Könige: »Wenn es dem Könige gut dünkt und dein Knecht Gnade bei dir findet, so wollest du mich nach Juda senden zu der Stadt, wo meine Väter begraben liegen, damit ich sie wieder aufbaue.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 2, 6, 'Da erwiderte mir der König, während die Königin neben ihm saß: »Wie lange soll denn deine Reise dauern, und wann wirst du wieder zurückkommen?« Weil es also dem König genehm schien, mich hinreisen zu lassen, gab ich ihm eine bestimmte Frist an');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 2, 7, 'und sagte dann zum König: »Wenn es dem Könige beliebt, so möge man mir Geleitbriefe an die Statthalter der Provinz auf der Westseite des Euphrats mitgeben, damit sie mich durchreisen lassen, bis ich nach Juda gelange;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 2, 8, 'weiter ein Schreiben an Asaph, den königlichen Forstmeister, daß er mir Holz verabfolgen lasse, damit man die Tore der Burg, die zum Tempel gehört, aus Balken zimmern kann, sowie für die Mauer der Stadt und für das Haus, das ich selber beziehen werde.« Und der König bewilligte mir dies, weil die gütige Hand meines Gottes über mir waltete.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 2, 9, 'Als ich dann zu den Statthaltern (des Gebiets) auf der Westseite des Euphrats kam, übergab ich ihnen die königlichen Geleitbriefe; der König hatte mir aber Heeresoberste und Reiter als Bedeckung mitgegeben.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 2, 10, 'Als dies der Horoniter Sanballat und der ammonitische Knecht Tobija erfuhren, verdroß es sie gewaltig, daß jemand gekommen war, der für das Wohl der Israeliten sorgen wollte.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 2, 11, 'Als ich nun in Jerusalem angekommen war und drei Tage dort zugebracht hatte,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 2, 12, 'machte ich mich nachts in Begleitung einiger weniger von meinen Leuten auf, ohne jedoch jemandem mitgeteilt zu haben, was mein Gott mir in den Sinn gegeben hatte, für Jerusalem zu tun; ich hatte auch kein anderes Reittier bei mir als das Maultier, auf dem ich ritt.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 2, 13, 'So ritt ich denn bei Nacht durch das Taltor hinaus in der Richtung zur Drachenquelle und nach dem Misttor hin und besichtigte die Mauer Jerusalems, die zerrissen dastand, und die Tore der Stadt, die vom Feuer vernichtet dalagen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 2, 14, 'Dann ritt ich weiter zum Quellentor und zum Königsteich, und als dort für das Tier, auf dem ich saß, kein Raum mehr zum Durchkommen war,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 2, 15, 'stieg ich bei Nacht die Schlucht zu Fuß hinauf und besichtigte die Mauer; dann kehrte ich um und gelangte durch das Taltor wieder heim;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 2, 16, 'die Vorsteher aber wußten nicht, wohin ich gegangen war und was ich zu tun vorhatte, denn ich hatte den Juden bis dahin noch nichts mitgeteilt, weder den Priestern noch den Vornehmen, weder den Vorstehern noch den übrigen, die am Bau arbeiten sollten.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 2, 17, 'Nunmehr sagte ich zu ihnen: »Ihr seht das Elend, in dem wir uns befinden, daß Jerusalem nämlich in Trümmern liegt und seine Tore mit Feuer vernichtet sind. Kommt, laßt uns die Mauer Jerusalems wieder aufbauen, damit wir nicht länger ein Gegenstand des Spottes sind!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 2, 18, 'Hierauf teilte ich ihnen mit, wie gütig die Hand meines Gottes über mir gewaltet hatte, und auch die Worte, die der König an mich gerichtet hatte. Da erklärten sie: »Ja, wir wollen darangehen und bauen!« Und sie ermutigten sich gegenseitig dazu, das gute Werk in Angriff zu nehmen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 2, 19, 'Als aber der Horoniter Sanballat und der ammonitische Knecht Tobija und der Araber Gesem Kunde davon erhielten, verhöhnten und verspotteten sie uns und sagten: »Was ist denn das für eine Sache, die ihr da vornehmt? Ihr wollt euch wohl gegen den König empören?«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 2, 20, 'Da gab ich ihnen folgende Antwort: »Der Gott des Himmels, der wird es uns gelingen lassen; und wir wollen uns als seine Knechte an den Bau machen! Ihr aber sollt weder Anteil, noch Anrecht, noch ein Gedächtnis in Jerusalem haben!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 3, 1, 'Hierauf machte sich der Hohepriester Eljasib mit seinen Amtsgenossen, den Priestern, daran, das Schaftor neu zu bauen; das weihten sie und setzten seine Torflügel ein und führten dann den Bau weiter bis zum Turm Hammea, den sie weihten, und bis zum Turm Hananeel.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 3, 2, 'Neben ihnen bauten die Männer von Jericho; und neben ihnen baute Sakkur, der Sohn Imris.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 3, 3, 'Sodann das Fischtor baute die Familie Senaa; sie führten das Gebälk auf und setzten seine Torflügel, seine Klammern und Riegel ein.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 3, 4, 'Neben ihnen besserte Meremoth aus, der Sohn Urias, des Sohnes des Hakkoz; und neben ihm besserte Mesullam aus, der Sohn Berechjas, des Sohnes Mesesabeels; und neben ihm besserte Zadok aus, der Sohn Baanas.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 3, 5, 'Ihm zur Seite besorgten die Thekoiter die Ausbesserung, aber die Vornehmen unter ihnen hatten ihren Nacken nicht unter den Dienst ihres Herrn (Nehemia) gebeugt.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 3, 6, 'Das Tor der Altstadt besserten Jojada, der Sohn Paseahs, und Mesullam, der Sohn Besodjas aus; sie führten das Gebälk auf und setzten seine Torflügel, seine Klammern und seine Riegel ein.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 3, 7, 'Neben ihnen besserten der Gibeoniter Melatja und der Meronothiter Jadon aus samt den Leuten von Gibeon und Mizpa, die zum Gerichtsstuhl des Statthalters der Provinz auf der Westseite des Euphrats gehörten.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 3, 8, 'Neben ihnen besserte Ussiel aus, der Sohn Harhajas, und die Zunft der Goldschmiede; und ihnen zur Seite besserte Hananja, einer von der Zunft der Salbenhändler, Jerusalem bis an die breite Mauer aus.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 3, 9, 'Neben ihnen arbeitete Rephaja, der Sohn Hurs, der Vorsteher der einen Hälfte des Bezirks Jerusalem.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 3, 10, 'Neben ihnen besserte Jedaja aus, der Sohn Harumaphs, und zwar seinem Hause gegenüber; und neben ihm besserte Hattus aus, der Sohn Hasabnejas.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 3, 11, 'Eine zweite Strecke besserte Malkija, der Sohn Harims, und Hasub, der Sohn Pahath-Moabs, aus, auch den Ofenturm.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 3, 12, 'Neben ihnen besserte Sallum aus, der Sohn des Hallohes, der Vorsteher der andern Hälfte des Bezirks Jerusalem, er und seine Töchter.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 3, 13, 'Das Taltor besserten Hanun und die Bewohner von Sanoah aus; sie bauten es auf und setzten seine Türen, seine Klammern und Riegel ein und arbeiteten noch tausend Ellen weiter an der Mauer bis zum Misttor. –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 3, 14, 'Das Misttor selbst aber besserte Malkija aus, der Sohn Rechabs, der Vorsteher des Bezirks Beth-Cherem; er baute es auf und setzte seine Torflügel, seine Klammern und Riegel ein. –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 3, 15, 'Das Quellentor besserte Sallun aus, der Sohn Kol-Hoses, der Vorsteher des Bezirks Mizpa; er baute es auf, überdachte es und setzte seine Torflügel, seine Klammern und Riegel ein; dazu die Mauer am Teich der Wasserleitung beim Königsgarten und bis an die Stufen, die von der Davidsstadt herabführen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 3, 16, 'Nächst ihm besserte Nehemia aus, der Sohn Asbuks, der Vorsteher der einen Hälfte des Bezirks Beth-Zur, bis gegenüber den Davidsgräbern und weiter bis an den Teich, der dort angelegt worden war, und bis an die Kaserne. –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 3, 17, 'Nächst ihm besserten die Leviten aus: Rehum, der Sohn Banis. Neben ihm besserte Hasabja aus, der Vorsteher der einen Hälfte des Bezirks Kegila, für seinen Bezirk. –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 3, 18, 'Nächst ihm besserten deren Genossen aus: Binnui, der Sohn Henadads, der Vorsteher der andern Hälfte des Bezirks Kegila. –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 3, 19, 'Neben ihm besserte Eser aus, der Sohn Jesuas, der Vorsteher der anderen Hälfte von Mizpa, eine zweite Strecke gegenüber dem Aufstieg zum Zeughaus am Winkel. –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 3, 20, 'Nächst ihm bergaufwärts besserte Baruch, der Sohn Sabbais, eine zweite Strecke aus vom Winkel bis an den Eingang zum Hause des Hohenpriesters Eljasib. –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 3, 21, 'Nächst ihm besserte Meremoth, der Sohn Urias, des Sohnes des Hakkoz, eine zweite Strecke aus vom Eingang zum Hause Eljasibs bis ans Ende des Hauses Eljasibs. –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 3, 22, 'Nächst ihm besserten die Priester aus, die Männer aus dem Jordanbezirk. –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 3, 23, 'Nächst ihnen besserten Benjamin und Hassub ihrem Hause gegenüber aus; nächst ihnen Asarja, der Sohn Maasejas, des Sohnes Ananjas, neben seinem Hause. –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 3, 24, 'Nächst ihm besserte Binnui, der Sohn Henadads, eine zweite Strecke aus vom Hause Asarjas bis an den Winkel und bis an die Ecke.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 3, 25, 'Palal, der Sohn Usais, arbeitete gegenüber dem Winkel und dem oberen Turm, der am königlichen Palast beim Gefängnishof vorspringt. – Nächst ihm besserte Pedaja aus, der Sohn des Parhos,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 3, 26, '[die Tempelhörigen aber wohnten auf dem Ophel,] bis gegenüber dem Wassertor nach Osten zu und dem vorspringenden Turm. –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 3, 27, 'Nächst ihm besserten die Thekoiter eine zweite Strecke aus, dem großen vorspringenden Turm gegenüber und bis an die Mauer des Ophel.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 3, 28, 'Oberhalb des Roßtores besserten die Priester aus, ein jeder seinem Hause gegenüber. –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 3, 29, 'Nächst ihnen besserte Zadok, der Sohn Immers, seinem Hause gegenüber aus, und nächst ihm Semaja, der Sohn Sechanjas, der Hüter des Osttores. –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 3, 30, 'Nächst ihm besserten Hananja, der Sohn Selemjas, und Hanun, der sechste Sohn Zalaphs, eine zweite Strecke aus. – Nächst ihm besserte Mesullam, der Sohn Berechjas, seiner Wohnung gegenüber aus. –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 3, 31, 'Nächst ihm besserte Malkija, einer aus der Zunft der Goldschmiede, bis zum Hause der Tempelhörigen und der Krämer dem Wachttor gegenüber aus und bis zum Söller an der Ecke;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 3, 32, 'und zwischen dem Söller an der Ecke und dem Schaftor besserten die Goldschmiede und die Krämer aus.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 3, 33, 'Als nun Sanballat erfuhr, daß wir (wirklich) die Mauer wieder aufbauten, geriet er in Zorn und heftigen Ärger und spottete über die Juden,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 3, 34, 'indem er in Gegenwart seiner Stammesgenossen und der Kriegsleute von Samaria sagte: »Was machen die ohnmächtigen Juden da? Wird man sie gewähren lassen? Werden sie jemals (das Dank-) Opfer darbringen? Werden sie damit eines Tages zu Ende kommen? Werden sie die Steine, die doch verbrannt sind, aus den Schutthaufen lebendig machen?«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 3, 35, 'Und der Ammoniter Tobija, der neben ihm stand, sagte: »Was sie auch bauen mögen: springt nur ein Fuchs daran hinauf, so reißt er ihre Steinmauer auseinander!« –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 3, 36, 'Höre, unser Gott, wie wir zum Spott geworden sind! Laß ihre Schmähungen auf ihr Haupt zurückfallen und gib sie der Plünderung preis in einem Lande, wo man sie in Gefangenschaft hält!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 3, 37, 'Decke ihre Verschuldung nicht zu und laß ihre Sünde vor deinem Angesicht nicht ausgelöscht werden! Denn sie haben durch kränkende Reden gegen die am Bau Tätigen Ärgernis erregt. –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 3, 38, 'Wir aber bauten an der Mauer weiter; und als die ganze Mauer bis zur halben Höhe fertig war, gewann das Volk neuen Mut zur Arbeit.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 4, 1, 'Als aber Sanballat und Tobija sowie die Araber und Ammoniter und Asdoditer erfuhren, daß die Wiederherstellung der Mauern Jerusalems Fortschritte machte, und daß die Lücken sich zu schließen begannen, da gerieten sie in heftigen Zorn');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 4, 2, 'und verschworen sich alle zusammen, sie wollten hinziehen, um Jerusalem anzugreifen und Schaden darin anzurichten.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 4, 3, 'Da beteten wir zu unserm Gott und stellten aus Furcht vor ihnen bei Tag und Nacht Wachen gegen sie auf.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 4, 4, 'Aber die Judäer erklärten: »Die Kraft der Lastträger ist erschöpft, und des Schuttes ist zu viel: wir sind nicht mehr imstande, an der Mauer zu arbeiten!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 4, 5, 'Unsere Widersacher aber sagten: »Sie sollen nichts merken und nichts sehen, bis wir mitten unter sie kommen und sie totschlagen und so dem Bauen ein Ende machen!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 4, 6, 'Als nun die Juden, die in ihrer Nachbarschaft wohnten, herbeikamen und es uns wohl zehnmal sagten, aus allen Orten, von denen sie ab und zu gingen,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 4, 7, 'da stellte ich hinter der Mauer an den tieferen Stellen das Volk nach den Geschlechtern mit ihren Schwertern, Lanzen und Bogen auf.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 4, 8, 'Bei einer Besichtigung trat ich dann auf und sagte zu den Vornehmen und Vorstehern und zu dem übrigen Volke: »Fürchtet euch doch nicht vor ihnen! Denkt an den HERRN, den großen und furchtbaren Gott, und kämpft für eure Volksgenossen, eure Söhne und Töchter, eure Frauen und Häuser!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 4, 9, 'Als nun unsere Feinde erfuhren, daß die Sache zu unserer Kenntnis gekommen war und Gott ihren Anschlag vereitelt hatte, kehrten wir alle wieder zu der Mauer zurück, ein jeder an seine Arbeit.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 4, 10, 'Seit jenem Tage aber war nur die eine Hälfte meiner Leute am Bau tätig, während die andere Hälfte sich mit Lanzen, Schilden, Bogen und Panzern bereithielt und die Oberen hinter der ganzen jüdischen Bevölkerung standen,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 4, 11, 'die an der Mauer baute. Die Handlanger aber, welche Lasten trugen, arbeiteten in der Weise, daß sie mit der einen Hand die Arbeit verrichteten, in der andern aber die Waffe hielten;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 4, 12, 'und von den Bauleuten hatte jeder sein Schwert um die Hüften gegürtet und mauerte so; und der Trompeter stand neben mir.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 4, 13, 'Den Vornehmen aber und Vorstehern und dem übrigen Volk hatte ich die Weisung gegeben: »Das Werk ist groß und weit ausgedehnt, und wir sind auf der Mauer zerstreut, einer von dem andern weit entfernt.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 4, 14, 'An dem Punkte also, von dem her ihr den Schall der Trompete vernehmen werdet, da müßt ihr euch bei uns sammeln: unser Gott wird für uns kämpfen!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 4, 15, 'So waren wir an dem Werke tätig, und zwar so, daß die eine Hälfte der Leute die Lanzen vom Aufgang der Morgenröte bis zum Erscheinen der Sterne bereit hielt.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 4, 16, 'Auch befahl ich damals dem Volke: »Jeder soll mit seinen Leuten die Nacht über innerhalb Jerusalems verbleiben, damit sie uns nachts als Wachen und bei Tage als Arbeiter dienen.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 4, 17, 'Und weder ich, noch meine Brüder, noch meine Leute, noch die Wachmannschaften, die zu meinem Gefolge gehörten, keiner von uns kam jemals aus den Kleidern heraus: ein jeder hatte stets seine Waffe zur Hand.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 5, 1, 'Es erhob sich aber ein großes Klagegeschrei der Leute aus dem Volk und ihrer Frauen gegen ihre jüdischen Volksgenossen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 5, 2, 'Die einen sagten: »Wir müssen unsere Söhne und Töchter verpfänden, um Getreide zu erhalten, damit wir zu essen haben und am Leben bleiben!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 5, 3, 'Andere sagten: »Wir müssen unsere Felder, unsere Weinberge und Häuser verpfänden, um uns Getreide in der Teurung zu verschaffen!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 5, 4, 'Wieder andere sagten: »Wir haben Geld zur Bezahlung der Steuern für den König auf unsere Felder und Weinberge borgen müssen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 5, 5, 'Wir sind aber doch von demselben Fleisch und Blut wie unsere Volksgenossen, und unsere Kinder sind ebenso gut wie ihre Kinder; aber trotzdem müssen wir unsere Söhne und Töchter als Leibeigene hingeben, und manche von unsern Töchtern sind schon leibeigen geworden, und wir können nichts dagegen tun: unsere Felder und Weinberge gehören ja anderen Leuten!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 5, 6, 'Da geriet ich in heftigen Zorn, als ich ihre lauten Klagen und diese Reden vernahm.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 5, 7, 'Als ich dann mit mir zu Rate gegangen war, machte ich den Vornehmen und den Vorstehern Vorwürfe, indem ich zu ihnen sagte: »Wucher treibt ihr ja einer mit dem andern!« Dann veranstaltete ich eine große Volksversammlung gegen sie');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 5, 8, 'und sagte zu ihnen: »Wir haben unsere jüdischen Volksgenossen, die an die Heidenvölker verkauft waren, soweit es uns möglich war, losgekauft; ihr dagegen wollt nun gar eure eigenen Volksgenossen verkaufen, so daß sie dann wieder von uns gekauft werden müssen!« Als sie nun schwiegen und kein Wort der Entgegnung fanden,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 5, 9, 'fuhr ich fort: »Was ihr da tut, ist unwürdig! Ihr solltet doch in der Furcht unsers Gottes wandeln, damit wir unseren heidnischen Feinden keine Veranlassung zu Lästerungen geben!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 5, 10, 'Sowohl ich als auch meine Brüder und meine Diener haben ihnen Geld und Getreide geliehen: laßt uns ihnen doch dieses Darlehen erlassen!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 5, 11, 'Gebt ihnen doch gleich heute ihre Felder und Weinberge, ihre Ölgärten und Häuser zurück und (erlaßt ihnen), was ihr an Geld und Getreide, an Wein und Öl von ihnen zu fordern habt!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 5, 12, 'Da antworteten sie: »Ja, wir wollen es zurückgeben und nichts mehr von ihnen fordern: wir wollen so tun, wie du es verlangst!« Da rief ich die Priester herbei und ließ sie schwören, daß sie wirklich in dieser Weise verfahren wollten.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 5, 13, 'Dazu schüttelte ich den Bausch meines Gewandes aus mit den Worten: »Ebenso möge Gott jeden, der dieses sein Versprechen nicht hält, aus seinem Hause und seinem Besitz herausschütteln, damit er ebenso ausgeschüttelt und ausgeleert sei!« Da rief die ganze Versammlung: »Ja, so sei es!« und pries den HERRN; das Volk aber tat, wie abgemacht war.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 5, 14, 'Außerdem habe ich und meine Brüder von dem Tage an, wo (der König) mich zu ihrem Statthalter im Lande Juda bestellt hatte, d.h. vom zwanzigsten bis zum zweiunddreißigsten Jahre der Regierung des Königs Arthasastha, also zwölf Jahre lang, keinen Anspruch auf den Unterhalt des Statthalters gemacht,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 5, 15, 'während die früheren Statthalter, meine Vorgänger, dem Volke schwer zur Last gefallen waren; denn sie hatten für Speise und Wein täglich vierzig Schekel Silber von ihnen bezogen, und auch ihre Dienerschaft hatte über das Volk willkürlich geschaltet. Ich dagegen habe aus Gottesfurcht nicht so gehandelt.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 5, 16, 'Auch bei diesem Mauerbau habe ich mit Hand angelegt, ohne daß wir Grundbesitz erworben hatten; und auch meine ganze Dienerschaft ist dort zur Arbeit am Mauerbau versammelt gewesen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 5, 17, 'Dazu aßen die Juden, sowohl die Vorsteher, hundertundfünfzig Mann, als auch die, welche aus den umwohnenden heidnischen Völkerschaften zu uns auf Besuch kamen, an meinem Tisch;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 5, 18, 'und was täglich zubereitet wurde, nämlich ein Rind, sechs ausgesuchte Stück Kleinvieh sowie Geflügel, das wurde auf meine Kosten zubereitet; außerdem alle zehn Tage allerlei Wein in Menge. Trotzdem habe ich den Unterhalt des Statthalters nicht beansprucht, weil die Fronarbeit schon schwer genug auf diesem Volke lastete. –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 5, 19, 'Gedenke, mein Gott, mir zum Guten alles dessen, was ich für dieses Volk getan habe!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 6, 1, 'Als es nun dem Sanballat, dem Tobija und dem Araber Gesem sowie unseren übrigen Feinden bekannt wurde, daß ich die Mauer wieder aufgebaut hätte und daß keine Lücke mehr in ihr geblieben wäre – nur hatte ich bis dahin noch keine Türflügel in die Tore eingesetzt –,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 6, 2, 'da sandten Sanballat und Gesem zu mir und ließen mir sagen: »Komm, laß uns in Ha-Kaphirim in der Ebene Ono eine Zusammenkunft halten!« Sie hatten nämlich Böses gegen mich im Sinn.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 6, 3, 'Da schickte ich Boten zu ihnen und ließ ihnen antworten: »Ich bin mit einem bedeutenden Werke beschäftigt und kann deshalb nicht hinabkommen: das Werk würde sofort stille stehen, wenn ich es unterbräche und zu euch hinunterkäme.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 6, 4, 'Nun sandten sie auf dieselbe Weise viermal Botschaft zu mir, ich gab ihnen aber immer dieselbe Antwort.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 6, 5, 'Da sandte Sanballat auf dieselbe Weise noch zum fünftenmale seinen Burschen zu mir mit einem offenen Briefe in der Hand,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 6, 6, 'in welchem geschrieben stand: »Unter den Leuten geht das Gerücht um, und Gasmu sagt es auch, daß ihr, du und die Juden, an Empörung denkt; darum bauest du die Mauer wieder auf, und du selbst wollest dich zum König über sie machen und dergleichen mehr;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 6, 7, 'sogar Propheten habest du auftreten lassen, die dich in Jerusalem zum König von Juda ausrufen sollen. Nun werden solche Gerüchte aber dem Könige zu Ohren dringen; darum komm, laß uns zusammen ratschlagen!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 6, 8, 'Darauf sandte ich folgenden Bescheid an ihn: »Nichts von allem, was du behauptest, ist wirklich geschehen, sondern du hast das selbst frei erfunden!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 6, 9, 'Sie alle wollten uns nämlich nur bange machen, weil sie dachten: »Sie werden von der Arbeit schon ablassen, so daß das Werk nicht vollendet wird.« – Nun aber stärke meine Hände!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 6, 10, 'Als ich (einmal) in die Wohnung Semajas, des Sohnes Delajas, des Sohnes Mehetabeels, kam, der gerade durch Unreinheit verhindert war, sagte er: »Laß uns zusammen ins Haus Gottes gehen, in das Innerste des Tempels, und die Türen des Tempels verschließen! Denn es werden Leute kommen, um dich zu ermorden, und zwar werden sie bei Nacht kommen, um dich zu ermorden.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 6, 11, 'Doch ich entgegnete: »Ein Mann wie ich sollte fliehen? Und wie könnte jemand, wie ich bin, in den Tempel gehen und am Leben bleiben? Nein, ich gehe nicht hinein!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 6, 12, 'Ich hatte nämlich gemerkt, daß nicht Gott ihn gesandt hatte, sondern er hatte den Gottesspruch deshalb an mich gerichtet, weil Tobija und Sanballat ihn bestochen hatten;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 6, 13, 'und zwar war er zu dem Zweck bestochen worden, daß ich in Angst geraten und so handeln und mich dadurch versündigen sollte; das hätte ihnen dann zu übler Nachrede dienen können, um mich in Verruf zu bringen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 6, 14, 'Gedenke, mein Gott, dem Tobija und Sanballat diese ihre Handlungsweise und auch der Prophetin Noadja und den übrigen Propheten, die mich ängstlich zu machen suchten!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 6, 15, 'Die Mauer aber wurde am fünfundzwanzigsten Tage des Monats Elul nach Verlauf von zweiundfünfzig Tagen fertig.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 6, 16, 'Als nun alle unsere Feinde das erfuhren, erschraken alle heidnischen Völkerschaften rings um uns her, und es entfiel ihnen aller Mut; denn sie erkannten, daß dieses Werk unter der Mitwirkung unseres Gottes vollführt worden war. –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 6, 17, 'Auch ließen in jenen Tagen die vornehmen Juden zahlreiche Briefe an Tobija abgehen, wie solche auch von Tobija an sie ankamen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 6, 18, 'Es gab nämlich unter den Juden gar manche, die ihm eidlich zum Beistand verpflichtet waren; denn er war der Schwiegersohn Sechanjas, des Sohnes Arahs, und sein Sohn Johanan hatte die Tochter Mesullams, des Sohnes Berechjas, geheiratet.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 6, 19, 'Sie redeten sogar in meiner Gegenwart von seinen guten Eigenschaften und hinterbrachten ihm meine Äußerungen; auch sandte Tobija Briefe, um mich einzuschüchtern.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 1, 'Als nun die Mauer aufgebaut war und ich die Türflügel hatte einsetzen lassen, wurden die Torwächter angestellt.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 2, 'Dann übertrug ich den Oberbefehl über Jerusalem meinem Bruder Hanani und dem Burghauptmann Hananja; denn dieser war ein zuverlässiger und gottesfürchtiger Mann wie wenige.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 3, 'Ich gab ihnen die Weisung: »Die Tore Jerusalems dürfen nicht eher geöffnet werden, als bis die Sonne heiß scheint; und während (die Torwächter) noch dastehen, soll man die Torflügel schließen und verriegeln. Auch sollt ihr Wachen aus den Bürgern Jerusalems aufstellen, einen jeden auf seinem Posten und jeden vor seinem Hause.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 4, 'Die Stadt war nun zwar geräumig und groß, aber die Bevölkerung in ihr nur spärlich, und neugebaute Häuser waren nicht vorhanden.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 5, 'Da gab mein Gott mir den Gedanken ein, die Vornehmen und Vorsteher und das Volk zu versammeln, damit ein Geschlechtsverzeichnis von ihnen aufgenommen würde. Da fand ich das Geschlechtsverzeichnis derer, die zuerst (oder früher) aus der Gefangenschaft zurückgekehrt waren, und fand darin folgende Angaben:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 6, 'Folgendes sind die Bewohner des Bezirks, die aus der Gefangenschaft der in der Verbannung Lebenden, die Nebukadnezar, der König von Babylon, einst (nach Babylon) weggeführt hatte, hinaufgezogen und nach Jerusalem und Juda zurückgekehrt sind, ein jeder in seine Ortschaft,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 7, 'und zwar sind sie dorthin gekommen zusammen mit Serubbabel, Jesua, Nehemia, Asarja, Raamja, Nahamani, Mordechai, Bilsan, Mispereth, Bigwai, Nehum und Baana. Die Zahl der Männer des Volkes Israel betrug:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 8, 'die Familie Parhos 2172;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 9, 'die Familie Sephatja 372;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 10, 'die Familie Arah 652;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 11, 'die Familie Pahath-Moab, nämlich die Familien Jesua und Joab, 2818;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 12, 'die Familie Elam 1254;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 13, 'die Familie Satthu 845;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 14, 'die Familie Sakkai 760;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 15, 'die Familie Binnui 648;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 16, 'die Familie Bebai 628;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 17, 'die Familie Asgad 2322;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 18, 'die Familie Adonikam 667;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 19, 'die Familie Bigwai 2067;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 20, 'die Familie Adin 655;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 21, 'die Familie Ater, nämlich der Zweig Hiskia, 98;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 22, 'die Familie Hasum 328;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 23, 'die Familie Bezai 324;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 24, 'die Familie Hariph 112;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 25, 'die Familie Gibeon 95;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 26, 'die Männer von Bethlehem und Netopha 188;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 27, 'die Männer von Anathoth 128;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 28, 'die Männer von Beth-Asmaweth 42;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 29, 'die Männer von Kirjath-Jearim, Kephira und Beeroth 743;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 30, 'die Männer von Rama und Geba 621;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 31, 'die Männer von Michmas 122;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 32, 'die Männer von Bethel und Ai 123;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 33, 'die Männer von [dem andern] Nebo 52;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 34, 'die Familie des andern Elam 1254;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 35, 'die Familie Harim 320;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 36, 'die Leute von Jericho 345;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 37, 'die Leute von Lod, Hadid und Ono 721;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 38, 'die Familie Senaa 3930.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 39, 'Die Priester: die Familie Jedaja, nämlich des Hauses Jesua 973;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 40, 'die Familie Immer 1052;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 41, 'die Familie Pashur 1247;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 42, 'die Familie Harim 1017.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 43, 'Die Leviten: die Familie Jesua, nämlich die Familien Kadmiel, (Bani) und Hodawja 74; –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 44, 'die Sänger: die Familie Asaph 148; –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 45, 'die Torhüter: die Familien Sallum, Ater, Talmon, Akkub, Hatita und Sobai 138.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 46, 'Die Tempelhörigen: die Familie Ziha, die Familie Hasupha, die Familie Thabbaoth,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 47, 'die Familie Keros, die Familie Sia, die Familie Padon,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 48, 'die Familie Lebana, die Familie Hagaba, die Familie Salmai,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 49, 'die Familie Hanan, die Familie Giddel, die Familie Gahar,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 50, 'die Familie Reaja, die Familie Rezin, die Familie Nekoda,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 51, 'die Familie Gassam, die Familie Ussa, die Familie Paseah,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 52, 'die Familie Besai, die Familie der Mehuniter, die Familie der Nephisiter,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 53, 'die Familie Bakbuk, die Familie Hakupha, die Familie Harhur,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 54, 'die Familie Bazluth, die Familie Mehida, die Familie Harsa,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 55, 'die Familie Barkos, die Familie Sisera, die Familie Themah,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 56, 'die Familie Neziah, die Familie Hatipha. –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 57, 'Die Familien der Sklaven Salomos: die Familie Sotai, die Familie Sophereth, die Familie Perida,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 58, 'die Familie Jaala, die Familie Darkon, die Familie Giddel,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 59, 'die Familie Sephatja, die Familie Hattil, die Familie Pochereth-Hazzebaim, die Familie Amon.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 60, 'Die Gesamtzahl der Tempelhörigen und der Familien der Sklaven Salomos betrug 392.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 61, 'Und dies sind die, welche aus Thel-Melah, Thel-Harsa, Cherub-Addon und Immer mit hinaufgezogen sind, aber ihre Familie und ihre Abkunft nicht nachweisen konnten, ob sie nämlich aus Israel stammten:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 62, 'die Familie Delaja, die Familie Tobija und die Familie Nekoda: 642.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 63, 'Sodann von den Priestern: die Familie Habaja, die Familie Hakkoz, die Familie jenes Barsillais, der eine Frau von den Töchtern des Gileaditen Barsillai geheiratet und deren Namen angenommen hatte.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 64, 'Diese hatten zwar nach einer Geschlechtsurkunde gesucht, aber eine solche hatte sich nicht finden lassen; infolgedessen wurden sie als unrein vom Priestertum ausgeschlossen;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 65, 'und der Statthalter hatte ihnen erklärt, daß sie von dem Hochheiligen nicht essen dürften, bis wieder ein Priester für die Befragung des Urim- und Thummim-Orakels da wäre.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 66, 'Die ganze Gemeinde insgesamt belief sich auf 42360 Seelen,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 67, 'ungerechnet ihre Sklaven und Sklavinnen, deren 7337 da waren; außerdem hatten sie noch 245 Sänger und Sängerinnen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 68, 'Die Zahl ihrer Pferde betrug 736, ihrer Maultiere 245, ihrer Kamele 435 und ihrer Esel 6720.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 69, 'Manche von den Familienhäuptern spendeten Beiträge für den Gottesdienst. Der Statthalter schenkte für den Schatz: an Gold 1000 Dariken, 50 Sprengschalen, 30 Priestergewänder.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 70, 'Von den Familienhäuptern gaben einige für den Gottesdienst: an Gold 20000 Dariken und an Silber 2200 Minen;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 71, 'und was das übrige Volk gab, betrug an Gold 20000 Dariken und an Silber 2000 Minen und 67 Priestergewänder.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 72, 'So siedelten sich denn die Priester und die Leviten sowie die Torhüter, die Sänger und die Tempelhörigen in Jerusalem und dessen Gebiet an, alle übrigen Israeliten dagegen in ihren Ortschaften. Als nun der siebte Monat herankam, während die Israeliten sich in ihren Ortschaften befanden,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 73, '');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 8, 1, 'da versammelte sich das ganze Volk bis auf den letzten Mann auf dem Platze vor dem Wassertor und richtete an Esra, den Schriftgelehrten, die Bitte, er möchte das Buch des mosaischen Gesetzes herbringen, das der HERR den Israeliten geboten hatte.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 8, 2, 'Da brachte denn der Priester Esra das Gesetz vor die Versammlung sowohl der Männer als der Frauen, vor alle, die befähigt waren, es zu verstehen, am ersten Tage des siebten Monats,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 8, 3, 'und er las auf dem freien Platze vor dem Wassertor von Tagesanbruch bis Mittag den Männern und Frauen, überhaupt allen, die ein Verständnis dafür hatten, daraus vor; und das ganze Volk schenkte der Vorlesung aus dem Gesetzbuch aufmerksames Gehör.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 8, 4, 'Esra, der Schriftgelehrte, stand dabei auf einem hölzernen Gerüst, das man zu diesem Zweck hergestellt hatte, und neben ihm standen auf seiner rechten Seite Matthithja, Sema, Anaja, Urija, Hilkija und Maaseja, zu seiner Linken dagegen Pedaja, Misael, Malkija, Hasum, Hasbaddana, Sacharja und Mesullam.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 8, 5, 'Esra schlug dann das Buch vor den Augen des ganzen Volkes auf – er stand nämlich höher als das ganze Volk –; und als er es aufschlug, erhob sich die ganze Versammlung.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 8, 6, 'Danach pries Esra den HERRN, den großen Gott, und das ganze Volk antwortete: »Amen, Amen!« unter Emporheben der Hände; dann verneigten sie sich und warfen sich vor dem HERRN nieder, das Angesicht zur Erde gewandt.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 8, 7, 'Darauf erteilten die Leviten Jesua, Bani, Serebja, Jamin, Akkub, Sabbethai, Hodija, Maaseja, Kelita, Asarja, Josabad, Hanan und Pelaja dem Volke Belehrung über das Gesetz, während das Volk auf seiner Stelle stehen blieb.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 8, 8, 'So lasen sie denn aus dem Buche, dem Gesetz Gottes, abschnittweise vor und machten den Sinn klar, so daß sie (die Zuhörenden) das Verständnis des Vorgelesenen gewannen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 8, 9, 'Hierauf sagte Nehemia – dieser war nämlich Statthalter – und der Priester Esra, der Schriftgelehrte, nebst den Leviten, die das Volk unterwiesen, folgendes zu dem ganzen Volke: »Dieser Tag ist dem HERRN, eurem Gott, heilig; seid nicht traurig und weint nicht!« Das ganze Volk hatte nämlich beim Anhören der Worte des Gesetzes zu weinen begonnen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 8, 10, 'Dann fuhr er fort: »Geht hin, eßt fette Speisen und trinkt süße Getränke und laßt auch denen, für die nichts zubereitet ist, Anteile zukommen, denn der Tag ist unserm Herrn heilig! Darum seid nicht niedergeschlagen, denn die Freude am HERRN ist eure Stärke.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 8, 11, 'So beruhigten denn die Leviten das ganze Volk, indem sie sagten: »Seid still, denn der Tag ist heilig, und seid nicht niedergeschlagen!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 8, 12, 'Da ging das ganze Volk hin, um zu essen und zu trinken und (den Dürftigen) Anteile zukommen zu lassen und ein großes Freudenfest zu feiern; denn sie hatten die Worte verstanden, die man ihnen kundgetan hatte.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 8, 13, 'Am zweiten Tage aber versammelten sich die Familienhäupter des ganzen Volkes sowie die Priester und die Leviten bei Esra, dem Schriftgelehrten, und zwar um Kenntnis vom Wortlaut des Gesetzes zu erhalten.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 8, 14, 'Da fanden sie im Gesetz, das der HERR durch Mose geboten hatte, geschrieben, die Israeliten sollten während des Festes im siebten Monat in Laubhütten wohnen');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 8, 15, 'und sollten in allen ihren Ortschaften und in Jerusalem ausrufen und laut verkündigen lassen: »Zieht auf die Berge hinaus und holt Zweige vom edlen und vom wilden Ölbaum, Zweige von Myrten, Palmen und anderen dichtbelaubten Bäumen, um Laubhütten daraus zu bauen, wie geschrieben steht!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 8, 16, 'Da zog das Volk hinaus, holte (solche Laubzweige) und machte sich Hütten daraus, ein jeder auf seinem Dache oder in ihren Höfen sowie in den Höfen des Hauses Gottes und auf dem Platze am Wassertor und auf dem Platze am Ephraimtor.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 8, 17, 'So baute sich denn die ganze Gemeinde, alle, die aus der Gefangenschaft zurückgekehrt waren, solche Laubhütten und wohnten in den Hütten. Seit den Tagen Josuas, des Sohnes Nuns, nämlich bis auf jenen Tag hatten die Israeliten (das Fest) nicht in dieser Weise gefeiert; und es herrschte sehr große Freude.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 8, 18, 'Man las dann aber aus dem Gesetzbuche Gottes Tag für Tag vor, vom ersten bis zum letzten Tage; und sie feierten das Fest sieben Tage lang, und am achten Tage fand vorschriftgemäß eine Festversammlung statt.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 1, 'Am vierundzwanzigsten Tage desselben Monats aber versammelten sich die Israeliten unter Fasten, und zwar in Trauergewändern und mit Erde auf dem Haupte.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 2, 'Nachdem sich dann die Vollisraeliten von allen Fremden abgesondert hatten, traten sie hin und legten ein Bekenntnis ihrer Sünden und der Verschuldungen ihrer Väter ab.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 3, 'Hierauf erhoben sie sich auf der Stelle, wo sie sich befanden, und man las aus dem Gesetzbuche des HERRN, ihres Gottes, einen Vierteltag lang vor und sprach dann drei weitere Stunden lang Bußgebete, während sie sich vor dem HERRN, ihrem Gott, niedergeworfen hatten.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 4, 'Darauf traten Jesua und Bani, Kadmiel, Sebanja, Bunni, Serabja, Bani und Kenani auf den erhöhten Platz der Leviten hinauf und riefen den HERRN, ihren Gott, mit lauter Stimme an.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 5, 'Alsdann hielten die Leviten Jesua und Kadmiel, Bani, Hasabneja, Serebja, Hodija, Sebanja und Pethahja folgende Ansprache: »Ach! Preiset den HERRN, euren Gott, von Ewigkeit zu Ewigkeit! Und man preise deinen herrlichen Namen, der über allen Lobpreis und Ruhm erhaben ist!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 6, 'Du bist es, der da ist, HERR, du allein! Du bist es, der den Himmel und den obersten Himmel samt ihrem ganzen Heer geschaffen hat, die Erde mit allem, was auf ihr ist, die Meere mit allem, was in ihnen ist; und du bist es, der dies alles am Leben erhält und den das himmlische Heer anbetet.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 7, 'Du, HERR, bist der Gott, der Abram erwählt, der ihn aus Ur in Chaldäa hat auswandern lassen und ihm den Namen Abraham gegeben hat.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 8, 'Nachdem du sein Herz treu gegen dich erfunden hattest, hast du mit ihm den Bund geschlossen, das Land der Kanaanäer, Hethiter, Amoriter, Pherissiter, Jebusiter und Girgasiter, dies Land seinen Nachkommen geben zu wollen; und du hast dein Wort gehalten, denn du bist gerecht.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 9, 'Als du dann das Elend unserer Väter in Ägypten sahst und ihr Geschrei am Schilfmeere hörtest,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 10, 'hast du Zeichen und Wunder am Pharao, an allen seinen Dienern und an dem ganzen Volke seines Landes getan; denn du hattest erkannt, daß jene in Vermessenheit gegen sie gehandelt hatten, und du hast dir einen Namen gemacht, wie er heute noch groß dasteht.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 11, 'Das Meer hast du vor ihnen gespalten, so daß sie trockenen Fußes mitten durch das Meer ziehen konnten; ihre Verfolger aber hast du in die Tiefen geschleudert wie einen Stein in gewaltige Fluten.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 12, 'Durch eine Wolkensäule hast du sie bei Tage geleitet und durch eine Feuersäule bei Nacht, um ihnen den Weg zu erleuchten, auf dem sie ziehen sollten.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 13, 'Auf den Berg Sinai bist du hinabgestiegen und hast vom Himmel her mit ihnen geredet und ihnen richtige Weisungen und zuverlässige Gesetze, gute Satzungen und Gebote gegeben.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 14, 'Auch deinen heiligen Sabbat hast du ihnen kundgetan und ihnen Gebote, Satzungen und das Gesetz durch deinen Knecht Mose verordnet.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 15, 'Brot vom Himmel hast du ihnen für ihren Hunger gegeben und Wasser aus dem Felsen ihnen für ihren Durst hervorfließen lassen und hast ihnen geboten, in das Land einzuziehen, dessen Besitz du ihnen mit erhobener Hand zugeschworen hattest.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 16, '»Sie aber, unsere Väter, waren übermütig und halsstarrig, so daß sie auf deine Gebote nicht hörten;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 17, 'sie weigerten sich vielmehr zu gehorchen und gedachten deiner Wunder nicht mehr, die du an ihnen getan hattest: sie wurden halsstarrig und setzten es sich in ihrer Widerspenstigkeit in den Kopf, nach Ägypten zu ihrem Sklavendienst zurückzukehren. Doch du bist ein Gott der Vergebung, gnädig und barmherzig, langmütig und reich an Güte: du hast sie nicht verlassen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 18, 'Sogar als sie sich ein gegossenes Stierbild gemacht hatten und ausriefen: ›Dies ist dein Gott, der dich aus Ägypten geführt hat!‹, und als sie arge Lästerdinge verübten,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 19, 'hast du sie doch nach deiner großen Barmherzigkeit in der Wüste nicht verlassen; nein, die Wolkensäule wich nicht von ihnen bei Tage, die sie auf dem Wege führen sollte, und die Feuersäule nicht bei Nacht, um ihnen den Weg zu erleuchten, auf dem sie ziehen sollten.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 20, 'Du gabst ihnen auch deinen guten Geist, um sie zu unterweisen; du versagtest ihrem Munde dein Manna nicht und gabst ihnen Wasser für ihren Durst.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 21, 'Vierzig Jahre lang versorgtest du sie in der Wüste, so daß sie keinen Mangel litten; ihre Kleider nutzten sich nicht ab, und ihre Füße schwollen nicht an.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 22, 'Dazu gabst du ihnen Königreiche und Völker zum Besitz und teiltest ihnen Gebiet für Gebiet zu, so daß sie das Land Sihons, des Königs von Hesbon, und das Land Ogs, des Königs von Basan, in Besitz nahmen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 23, 'Ihre Söhne ließest du zahlreich werden wie die Sterne am Himmel und brachtest sie in das Land, in das sie, wie du ihren Vätern verheißen hattest, eindringen sollten, um es in Besitz zu nehmen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 24, 'So zogen denn ihre Söhne in das Land ein und nahmen es in Besitz, und du warfst die Bewohner des Landes, die Kanaanäer, vor ihnen nieder und ließest sie in ihre Gewalt fallen, sowohl ihre Könige als auch die Völkerschaften des Landes, damit sie mit ihnen nach Belieben verfahren könnten.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 25, 'So eroberten sie denn feste Städte und ein fruchtbares Land und nahmen Häuser in Besitz, die mit Gütern aller Art angefüllt waren, ausgehauene Brunnen, Weinberge und Ölbaumgärten und Obstbäume in Menge; und sie aßen und wurden satt und fett und ließen sich’s wohl sein im Genuß der Fülle deiner Güter.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 26, '»Aber sie wurden ungehorsam und lehnten sich gegen dich auf; sie kehrten deinem Gesetz den Rücken; sie ermordeten deine Propheten, die ihnen ins Gewissen redeten, um sie zu dir zurückzuführen, und verübten arge Lästerdinge.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 27, 'Darum gabst du sie der Gewalt ihrer Feinde preis, daß diese sie bedrängten. Wenn sie dann aber in ihrer Not zu dir schrien, erhörtest du sie vom Himmel her und ließest ihnen nach deiner großen Barmherzigkeit Retter erstehen, die sie aus der Gewalt ihrer Bedränger erretteten.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 28, 'Sobald sie aber Ruhe hatten, fingen sie wieder an, Böses vor dir zu tun; und wenn du sie dann wieder in die Gewalt ihrer Feinde fallen ließest, die sie unter ihre Herrschaft knechteten, und sie aufs neue zu dir schrien, erhörtest du sie vom Himmel her und errettetest sie oftmals in deiner großen Barmherzigkeit.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 29, 'Obgleich du sie aber ernstlich warnen ließest, um sie zu deinem Gesetz zurückzuführen, waren sie doch trotzig und gehorchten deinen Geboten nicht, sondern sündigten gegen deine Verordnungen, obwohl der Mensch doch durch deren Beobachtung sein Leben bewahrt; sie wollten sich kein Joch auf ihre Schulter legen lassen und waren halsstarrig, so daß sie nicht gehorchten.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 30, 'Obgleich du nun noch viele Jahre lang Geduld mit ihnen hattest und sie durch deinen Geist, durch deine Propheten, ernstlich warnen ließest, achteten sie doch nicht darauf. Da hast du sie in die Gewalt der Völker in den heidnischen Ländern fallen lassen,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 31, 'aber sie trotzdem in deiner großen Barmherzigkeit nicht völlig vernichtet und sie nicht verlassen; denn du bist ein gnädiger und barmherziger Gott.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 32, '»Und nun, unser Gott, du großer, starker und furchtbarer Gott, der du den Bund und die Gnade bewahrst: achte nicht gering alle die Leiden, die uns betroffen haben, unsere Könige und Obersten, unsere Priester und Propheten, unsere Väter und dein ganzes Volk seit der Zeit der Assyrerkönige bis auf diesen Tag!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 33, 'Du bist allerdings gerecht gewesen bei allem, was uns widerfahren ist; denn du hast stets Treue geübt, wir aber haben gottlos gehandelt.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 34, 'Auch unsere Könige und Obersten, unsere Priester und unsere Väter haben dein Gesetz nicht gehalten und deine Gebote und ernstlichen Warnungen, die du ihnen hast zukommen lassen, unbeachtet gelassen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 35, 'Weil sie trotz ihres Königtums und trotz der Fülle von Wohltaten, die du ihnen erwiesen, und trotz des weiten und fruchtbaren Landes, das du ihnen zugeteilt hattest, dir nicht gedient und sich nicht von ihrem bösen Tun bekehrt haben, –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 36, 'ja, ebendarum sind wir heute Knechte, und das Land, das du unsern Vätern geschenkt hast, damit sie seine Früchte und Güter genössen: ach, wir sind Knechte in ihm!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 37, 'Seinen reichen Ertrag liefert es den Königen, die du um unserer Sünden willen über uns gesetzt hast, und sie herrschen über unsere Leiber und über unser Vieh nach ihrem Gutdünken, so daß wir uns in großer Not befinden.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 1, 'Auf Grund aller dieser Umstände schließen wir einen festen Vertrag und fertigen ihn schriftlich aus; und auf der untersiegelten Urkunde stehen die Namen unserer Obersten, unserer Leviten und unserer Priester;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 2, 'und auf dem untersiegelten Schriftstück stehen die Namen: Nehemia, der Statthalter, der Sohn Hachaljas, und Zedekia,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 3, 'Seraja, Asarja, Jeremia,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 4, 'Pashur, Amarja, Malkija,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 5, 'Hattus, Sechanja, Malluch,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 6, 'Harim, Meremoth, Obadja,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 7, 'Daniel, Ginnethon, Baruch,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 8, 'Mesullam, Abija, Mijamin,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 9, 'Maasja, Bilgai, Semaja; dies waren die Priester.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 10, 'Sodann die Leviten: Jesua, der Sohn Asanjas, Binnui aus der Familie Henadad, Kadmiel;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 11, 'und ihre Genossen: Sebanja, Hodawja, Kelita, Pelaja, Hanan,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 12, 'Micha, Rehob, Hasabja,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 13, 'Sakkur, Serebja, Sebanja,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 14, 'Hodija, Bani, Beninu.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 15, 'Sodann die Häupter des Volkes: Parhos, Pahath-Moab, Elam, Satthu, Bani,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 16, 'Bunni, Asgad, Bebai,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 17, 'Adonija, Bigwai, Adin,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 18, 'Ater, Hiskia, Assur,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 19, 'Hodija, Hasum, Bezai,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 20, 'Hariph, Anathoth, Nobai,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 21, 'Magpias, Mesullam, Hesir,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 22, 'Mesesabeel, Zadok, Jaddua,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 23, 'Pelatja, Hanan, Anaja,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 24, 'Hosea, Hananja, Hassub,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 25, 'Hallohes, Pilha, Sobek,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 26, 'Rehum, Hasabna, Maaseja,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 27, 'und Ahija, Hanan, Anan,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 28, 'Malluch, Harim, Baana.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 29, 'Das übrige Volk aber, die Priester, Leviten, Torhüter, Sänger, Tempelhörigen und alle, die sich von der heidnischen Bevölkerung der Landesteile abgesondert haben und sich zum Gesetz Gottes halten, samt ihren Frauen, Söhnen und Töchtern, alle, welche Einsicht (und) Verständnis dafür haben,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 30, 'schließen sich hiermit ihren Volksgenossen, den Vornehmen unter ihnen, an und verpflichten sich durch einen Eid unwiderruflich, nach dem Gesetz Gottes, das durch Mose, den Knecht Gottes, gegeben worden ist, zu wandeln und alle Gebote Gottes, unseres HERRN, seine Verordnungen und Satzungen zu beobachten und zu erfüllen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 31, 'Wir wollen also weder unsere Töchter den heidnischen Landesbewohnern zu Frauen geben noch ihre Töchter für unsere Söhne zu Frauen nehmen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 32, 'Wenn ferner die heidnischen Landesbewohner am Sabbattage Waren und Getreide aller Art zum Verkauf herbringen, wollen wir ihnen am Sabbat und an einem (andern) heiligen Tage nichts abkaufen. Wir wollen ferner in jedem siebten Jahre die Felder unbestellt liegen lassen und auf jede Schuldforderung (in dem betreffenden Jahre) verzichten.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 33, 'Weiter verpflichten wir uns unwiderruflich dazu, ein Drittel Schekel jährlich als Steuer für den heiligen Dienst im Hause unsers Gottes zu entrichten,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 34, 'nämlich für die Schaubrote und für das tägliche Speisopfer, für das tägliche Brandopfer und für die Opfer an den Sabbaten, an den Neumonden und den Festen, für die Heilsopfer und für die Sündopfer, um Sühnung für Israel zu erwirken, überhaupt für den gesamten Dienst im Hause unsers Gottes.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 35, 'Ferner haben wir, die Priester, die Leviten und das Volk, durch das Los über die Holzlieferungen entscheiden lassen, damit wir diese familienweise zu bestimmten Zeiten Jahr für Jahr an das Haus unsers Gottes gelangen lassen, zur Feuerung auf dem Altar des HERRN, unsers Gottes, wie im Gesetz vorgeschrieben ist.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 36, 'Ebenso verpflichten wir uns, die Erstlinge unserer Felder und die Erstlinge aller Früchte von allen Bäumen Jahr für Jahr zum Hause des HERRN zu bringen,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 37, 'auch unsere erstgeborenen Söhne und die Erstlinge unsers Viehes, wie es im Gesetz vorgeschrieben ist, und zwar die Erstlinge unserer Rinder und unsers Kleinviehs in das Haus unsers Gottes für die Priester zu bringen, die den Dienst im Hause unsers Gottes verrichten.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 38, 'Ferner wollen wir das Beste von unserm Schrotmehl und von unseren Heilsopfern sowie von allen Baumfrüchten, von Wein und Öl den Priestern in die Zellen des Hauses unsers Gottes liefern und den Zehnten von unseren Feldern an die Leviten; denn die Leviten sind es, die den Zehnten in allen Ortschaften erheben, wo wir Ackerbau treiben.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 39, 'Und wenn die Leviten den Zehnten einfordern, soll der (betreffende) Priester, ein Nachkomme Aarons, die Leviten begleiten, und die Leviten sollen dann den Zehnten von ihrem Zehnten zum Hause unsers Gottes in die Zellen des Vorratshauses hinaufbringen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 40, 'Denn in die Zellen sollen sowohl die Israeliten als auch die Leviten die Abgaben vom Getreide, vom Most und vom Öl liefern; denn dort befinden sich auch die heiligen Geräte sowie die diensttuenden Priester, die Torhüter und die Sänger. Und so wollen wir es dem Hause unsers Gottes an nichts fehlen lassen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 11, 1, 'Hierauf nahmen die Obersten des Volkes ihren Wohnsitz in Jerusalem; das übrige Volk aber bestimmte durch das Los je den zehnten Mann dazu, sich in der heiligen Stadt Jerusalem anzusiedeln, während die übrigen neun Zehntel in den Ortschaften (des Landes) wohnen bleiben sollten.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 11, 2, 'Das Volk aber hieß alle Leute willkommen, die sich freiwillig zur Niederlassung in Jerusalem erboten.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 11, 3, 'Und dies sind die Häupter des Bezirks, die sich in Jerusalem und in den Ortschaften Judas niedergelassen haben, und zwar ein jeder auf seinem Besitztum in den dortigen Ortschaften: die (gewöhnlichen) Israeliten, die Priester und die Leviten, die Tempelhörigen und die Nachkommen der Leibeigenen Salomos.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 11, 4, 'In Jerusalem haben sich sowohl Judäer als auch Benjaminiten niedergelassen, und zwar von den Judäern: Athaja, der Sohn Ussijas, des Sohnes Sacharjas, des Sohnes Amarjas, des Sohnes Sephatjas, des Sohnes Mahalaleels, von den Nachkommen des Perez;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 11, 5, 'ferner Maaseja, der Sohn Baruchs, des Sohnes Kol-Hoses, des Sohnes Hasajas, des Sohnes Adajas, des Sohnes Jojaribs, des Sohnes Sacharjas, des Sohnes des Siloniten.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 11, 6, 'Die Gesamtzahl der Nachkommen des Perez, die in Jerusalem wohnten, betrug 468, tüchtige Männer. –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 11, 7, 'Und dies sind die Benjaminiten: Sallu, der Sohn Mesullams, des Sohnes Joeds, des Sohnes Pedajas, des Sohnes Kolajas, des Sohnes Maasejas, des Sohnes Ithiels, des Sohnes Jesajas,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 11, 8, 'und seine Genossen, wehrhafte Krieger, 928 an der Zahl. –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 11, 9, 'Joel aber, der Sohn Sichris, war ihr Vorsteher; und Juda, der Sohn Hassenuas, war zweiter Aufseher über die Stadt. –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 11, 10, 'Von den Priestern: Jedaja, der Sohn Jojaribs, Jachin,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 11, 11, 'Seraja, der Sohn Hilkijas, des Sohnes Mesullams, des Sohnes Zadoks, des Sohnes Merajoths, des Sohnes Ahitubs, der Fürst über das Haus Gottes,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 11, 12, 'und ihre Genossen, die den heiligen Dienst im Hause Gottes besorgten, 822 an Zahl; ferner Adaja, der Sohn Jerohams, des Sohnes Pelaljas, des Sohnes Amzis, des Sohnes Sacharjas, des Sohnes Pashurs, des Sohnes Malkijas,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 11, 13, 'und seine Genossen, 242, Familienhäupter; ferner Amassai, der Sohn Asareels, des Sohnes Ahsais, des Sohnes Mesillemoths, des Sohnes Immers,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 11, 14, 'und ihre Genossen, tüchtige Männer, 128 an der Zahl; ihr Vorsteher war Sabdiel, der Sohn Haggedolims. –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 11, 15, 'Ferner von den Leviten: Semaja, der Sohn Hassubs, des Sohnes Asrikams, des Sohnes Hasabjas, des Sohnes Bunnis;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 11, 16, 'ferner Sabbethai und Josabad, welche die weltlichen Geschäfte des Gotteshauses zu besorgen hatten;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 11, 17, 'und Matthanja, der Sohn Michas, des Sohnes Sabdis, des Sohnes Asaphs, der Leiter des Lobgesangs, der die Danksagung beim Gebet anstimmte; und Bakbukja, der zweite im Rang unter seinen Genossen, und Abda, der Sohn Sammuas, des Sohnes Galals, des Sohnes Jeduthuns.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 11, 18, 'Die Gesamtzahl der Leviten in der heiligen Stadt betrug 284. –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 11, 19, 'Die Torhüter aber waren: Akkub, Talmon und ihre Genossen, die an den Toren Wache hielten, 172 an der Zahl.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 11, 20, 'Die übrigen Israeliten aber, Priester und Leviten, wohnten in allen Ortschaften Judas zerstreut, ein jeder in seinem Besitztum.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 11, 21, 'Die Tempelhörigen aber wohnten auf dem Ophel; Ziha und Gispa waren die Aufseher über die Tempelhörigen. –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 11, 22, 'Der Vorsteher der Leviten in Jerusalem war Ussi, der Sohn Banis, des Sohnes Hasabjas, des Sohnes Matthanjas, des Sohnes Michas, einer von den Nachkommen Asaphs, den Sängern für den Dienst im Hause Gottes;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 11, 23, 'es lag nämlich eine königliche Verfügung in bezug auf sie vor und eine Verordnung für die Sänger bezüglich ihrer täglichen Amtsleistungen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 11, 24, 'Pethahja aber, der Sohn Mesesabeels, aus der Zahl der Nachkommen Serahs, des Sohnes Judas, war der königliche Beamte für alle Angelegenheiten, die das Volk betrafen,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 11, 25, 'und für die Dörfer auf ihren Feldmarken. Von den Judäern wohnte ein Teil in Kirjath-Arba nebst den zugehörigen Ortschaften sowie in Dibon nebst den zugehörigen Ortschaften und in Jekabzeel nebst den zugehörigen Gehöften;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 11, 26, 'ferner in Jesua, Molada, Beth-Pelet,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 11, 27, 'in Hazar-Sual und Beerseba nebst den zugehörigen Ortschaften,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 11, 28, 'in Ziklag und Mechona nebst den zugehörigen Ortschaften,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 11, 29, 'in En-Rimmon, Zora, Jarmuth,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 11, 30, 'Sanoah, Adullam nebst den zugehörigen Gehöften, Lachis und dessen Feldmarken und in Aseka nebst den zugehörigen Ortschaften; sie hatten sich also von Beerseba bis zum Tal Hinnom angesiedelt.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 11, 31, 'Die Benjaminiten aber wohnten von Geba an in Michmas, Ajja und Bethel nebst den zugehörigen Ortschaften,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 11, 32, 'in Anathoth, Nob, Ananja,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 11, 33, 'Hazor, Rama, Hitthaim,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 11, 34, 'Hadid, Zeboim, Neballat,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 11, 35, 'Lod und Ono (und) im Tal der Zimmerleute.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 11, 36, 'Von den Leviten aber gehörten einige judäische Abteilungen zu Benjamin.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 1, 'Folgende sind die Priester und die Leviten, die mit Serubbabel, dem Sohne Sealthiels, und mit Jesua (nach Jerusalem) hinaufgezogen waren: Seraja, Jeremia, Esra,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 2, 'Amarja, Malluch, Hattus,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 3, 'Sechanja, Harim, Meremoth,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 4, 'Iddo, Ginnethoi, Abia,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 5, 'Mijjamin, Maadja, Bilga,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 6, 'Semaja und Jojarib, Jedaja,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 7, 'Sallu, Amok, Hilkija, Jedaja. Das waren die Häupter der Priester und ihrer Genossen zur Zeit Jesuas. –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 8, 'Die Leviten aber waren: Jesua, Binnui, Kadmiel, Serebja, Juda, Matthanja; dieser und seine Genossen leiteten den Dankgesang,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 9, 'während ihre Genossen Bakbukja und Unni nach den Dienstabteilungen ihnen gegenüberstanden.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 10, 'Jesua war der Vater Jojakims, Jojakim der Vater Eljasibs, Eljasib der Vater Jojadas,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 11, 'Jojada der Vater Johanans, Johanan der Vater Jadduas.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 12, 'Zur Zeit Jojakims aber waren folgende Priester die Häupter der Familien: von der Familie Seraja: Meraja, von Jeremia: Hananja,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 13, 'von Esra: Mesullam, von Amarja: Johanan,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 14, 'von Malluch: Jonathan, von Sechanja: Joseph,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 15, 'von Harim: Adna, von Merajoth: Helkai,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 16, 'von Iddo: Sacharja, von Ginneton: Mesullam,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 17, 'von Abija: Sichri, von Minjamin: ..., von Moadja: Piltai,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 18, 'von Bilga: Sammua, von Semaja: Jonathan,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 19, 'von Jojarib: Matthenai, von Jedaja: Ussi,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 20, 'von Sallu: Kallai, von Amok: Eber,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 21, 'von Hilkija: Hasabja, von Jedaja: Nethaneel.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 22, 'Was die Leviten betrifft, so sind ihre Familienhäupter zur Zeit Eljasibs, Jojadas, Johanans und Jadduas aufgezeichnet worden, von den Priestern aber unter der Regierung des Perserkönigs Darius. –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 23, 'Von den Leviten sind die Familienhäupter im Buch der Chronik aufgezeichnet, und zwar bis auf die Zeit Johanans, des Sohnes Eljasibs.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 24, 'Die Häupter der Leviten waren: Hasabja, Serebja und Jesua, der Sohn Kadmiels, und ihre Genossen, die ihnen gegenüberstanden, um die Lob- und Danklieder zu singen nach der Anordnung Davids, des Mannes Gottes, eine Abteilung neben der andern.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 25, 'Matthanja und Bakbukja, Obadja, Mesullam, Talmon und Akkub hielten als Torhüter Wache bei den Vorratshäusern an den Toren.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 26, 'Diese waren Zeitgenossen Jojakims, des Sohnes Jesuas, des Sohnes Jozadaks, und Zeitgenossen des Statthalters Nehemia und des schriftgelehrten Priesters Esra.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 27, 'Bei Gelegenheit der Einweihung der Mauer Jerusalems aber suchte man die Leviten zu veranlassen, aus allen ihren Wohnorten nach Jerusalem zu kommen, damit die Einweihung durch ein Freudenfest begangen würde mit Dankliedern und Lobgesängen, mit Zimbeln, Harfen und Zithern.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 28, 'Da versammelten sich die zu den (Tempel-)- Sängern Gehörenden sowohl aus der ganzen Umgegend von Jerusalem als auch aus den Gehöften von Netopha');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 29, 'sowie aus Beth-Gilgal und aus den Feldmarken von Geba und Asmaweth; die Sänger hatten sich nämlich Gehöfte in der Umgegend von Jerusalem gebaut.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 30, 'Nachdem nun die Priester und die Leviten sich selbst gereinigt und dann auch das Volk sowie die Tore und die Mauer gereinigt hatten,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 31, 'ließ ich die Obersten Judas oben auf die Mauer steigen und stellte zwei große Dankchöre und Festzüge auf, von denen der eine oben auf der Mauer südwärts zum Misttor hin zog,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 32, 'und hinter ihnen her schritt Hosaja mit der einen Hälfte der Obersten von Juda,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 33, 'nämlich Asarja, Esra und Mesullam,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 34, 'Juda, Benjamin, Semaja und Jeremia;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 35, 'ferner einige Mitglieder der Priesterschaft mit Trompeten, nämlich Sacharja, der Sohn Jonathans, des Sohnes Semajas, des Sohnes Matthanjas, des Sohnes Michajas, des Sohnes Sakkurs, des Sohnes Asaphs,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 36, 'und seine Genossen Semaja und Asareel, Milalai, Gilalai, Maai, Nethaneel und Juda, Hanani, mit den Tonwerkzeugen Davids, des Mannes Gottes; und der Schriftgelehrte Esra ging an ihrer Spitze.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 37, 'Weiter zogen sie zum Quelltor hin, stiegen dann geradeaus auf den Stufen der Davidsstadt den Aufgang zur Mauer hinauf und dann oberhalb des Palastes Davids bis zum Wassertor im Osten.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 38, 'Der zweite Festchor aber zog nach der entgegengesetzten Seite, und ich selbst ging hinter ihm her mit der andern Hälfte (der Obersten) des Volkes oben auf der Mauer hin, am Ofenturm vorüber bis an die Breite Mauer,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 39, 'dann am Tor Ephraim und dem Tor der Altstadt, dem Fischtor, dem Turm Hananeel und dem Turm Mea vorüber bis an das Schaftor; am Gefängnistor machten sie Halt.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 40, 'Dann nahmen beide Festchöre beim Hause Gottes Aufstellung, auch ich und die eine Hälfte der Obersten mit mir.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 41, 'Hierauf bliesen die Priester Eljakim, Maaseja, Minjamin, Michaja, Eljoenai, Sacharja und Hananja mit Trompeten,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 42, 'und Maaseja, Semaja, Eleasar, Ussi, Johanan, Malkija, Elam und Eser, die Sänger, trugen unter Leitung Jisrahjas Lieder vor.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 43, 'Alsdann brachte man an diesem Tage große Schlachtopfer dar und gab sich der Freude hin, denn Gott der HERR hatte ihnen eine große Freude bereitet; und auch die Frauen und Kinder überließen sich der Freude, so daß man den Jubel Jerusalems bis in weite Ferne hörte.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 44, 'An jenem Tage bestellte man auch Männer zu Aufsehern über die Zellen, die zu Vorratskammern für die Abgaben, für die Erstlinge und die Zehnten, bestimmt waren, um in ihnen nach den Feldmarken der einzelnen Ortschaften die gesetzlichen Abgaben für die Priester und die Leviten einzusammeln; denn die Judäer hatten ihre Freude an den Priestern und Leviten, die für den heiligen Dienst bestellt waren;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 45, 'und diese besorgten in der Tat den Dienst ihres Gottes und die Beobachtung der Reinigungsvorschriften gewissenhaft, ebenso auch die Sänger und Torhüter, nach der Anordnung Davids und seines Sohnes Salomo.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 46, 'Denn schon vor alters, zur Zeit Davids und Asaphs, hatte es Vorsteher der Sänger sowie Lobgesänge und Danklieder für Gott gegeben.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 47, 'Ganz Israel aber entrichtete zur Zeit Serubbabels und zur Zeit Nehemias die Abgaben für die Sänger und die Torhüter, die diesen tagtäglich gebührten; sie lieferten aber die (vorgeschriebenen) heiligen Gaben an die Leviten ab, und die Leviten ließen die Weihegaben den Nachkommen Aarons zukommen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 13, 1, 'Als an jenem Tage dem Volke aus dem Buch des mosaischen Gesetzes laut vorgelesen wurde, fand sich darin geschrieben, daß kein Ammoniter und kein Moabiter jemals Aufnahme in die Gemeinde Gottes finden dürfe,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 13, 2, 'weil sie den Israeliten nicht mit Brot und Wasser entgegengekommen waren und (ihr König) den Bileam gegen sie in Sold genommen hatte, damit er sie verfluche; allerdings hatte unser Gott den Fluch in Segen verwandelt.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 13, 3, 'Als sie nun das Gesetz vernommen hatten, sonderten sie alles Mischvolk aus Israel aus.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 13, 4, 'Vordem aber hatte der Priester Eljasib, dem die Aufsicht über die Zellen des Hauses unsers Gottes übertragen war, ein Verwandter Tobijas,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 13, 5, 'diesem eine große Zelle eingeräumt, in der man früher die Speisopfer, den Weihrauch, die Geräte und den Zehnten vom Getreide, Wein und Öl untergebracht hatte, die Anteile, die den Leviten, den Sängern und den Torhütern zukamen, sowie die Abgaben an die Priester.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 13, 6, 'Während aber dies alles vor sich ging, war ich nicht in Jerusalem anwesend gewesen, sondern hatte mich im zweiunddreißigsten Regierungsjahre Arthasasthas, des Königs von Babylon, an den königlichen Hof begeben. Als ich mir dann nach einiger Zeit wieder Urlaub vom Könige erbeten hatte');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 13, 7, 'und wieder nach Jerusalem gekommen war, entdeckte ich den Unfug, den Eljasib dem Tobija zuliebe verübt hatte, indem er ihm eine Zelle in den Vorhöfen des Hauses Gottes eingeräumt hatte.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 13, 8, 'Dies erregte solchen Unwillen in mir, daß ich allen Hausrat Tobijas aus der Zelle hinauswerfen ließ');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 13, 9, 'und den Befehl gab, man solle die Zelle reinigen; darauf ließ ich dort wieder die Geräte des Hauses Gottes, das Speisopfer und den Weihrauch unterbringen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 13, 10, 'Als ich dann erfuhr, daß man den Leviten die ihnen zukommenden Anteile nicht geliefert hatte und daß infolgedessen die Leviten und die Sänger, die den heiligen Dienst zu verrichten hatten, sich alle auf ihre ländlichen Besitzungen entfernt hatten,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 13, 11, 'da stellte ich die Vorsteher zur Rede und fragte sie, warum das Haus Gottes so verwahrlost worden sei. Darauf ließ ich die betreffenden Leute wieder zusammenholen und stellte sie wieder auf ihre Posten.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 13, 12, 'Als dann ganz Juda die Zehnten vom Getreide, Wein und Öl in die Vorratskammern gebracht hatte,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 13, 13, 'übertrug ich die Aufsicht über die Vorräte dem Priester Selemja und dem Schriftgelehrten Zadok und von den Leviten dem Pedaja und bestellte zu ihrer Unterstützung Hanan, den Sohn Sakkurs, des Sohnes Matthanjas; denn sie galten als zuverlässige Männer, und ihnen oblag es nunmehr, die Austeilung an ihre Genossen vorzunehmen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 13, 14, 'Gedenke mir dies, mein Gott, und laß die Wohltaten, die ich dem Hause meines Gottes und seiner Dienerschaft erwiesen habe, nicht in Vergessenheit geraten!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 13, 15, 'Zu derselben Zeit sah ich in Juda Leute, die am Sabbat die Kelter traten und Getreide vom Felde einbrachten und Esel damit beluden, auch Wein, Trauben, Feigen und andere Ladungen aller Art aufpackten und sie am Sabbattage nach Jerusalem hereinbrachten. Ich verwarnte sie also an dem Tage, an welchem sie die Lebensmittel feilboten.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 13, 16, 'Auch die Tyrier, die im Lande wohnten, brachten Fische und allerlei andere Waren herein und verkauften sie am Sabbat an die Juden in Jerusalem.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 13, 17, 'Da stellte ich die vornehmen Juden zur Rede und hielt ihnen vor: »Was ist das für eine böse Sache, die ihr da tut, daß ihr den Sabbattag entheiligt!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 13, 18, 'Haben nicht eure Väter ebenso getan, und hat nicht unser Gott eben deswegen all dieses Unglück über uns und diese Stadt ergehen lassen? Wollt ihr denn noch größeren Zorn über Israel bringen, indem ihr den Sabbattag entweiht?«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 13, 19, 'Sobald es nun am Vorabend des Sabbats (auf den Marktplätzen) an den Toren Jerusalems dunkel wurde, ließ ich die Tore schließen und gab Befehl, sie erst nach Ablauf des Sabbats wieder zu öffnen; auch stellte ich einige von meinen Leuten an den Toren auf, damit keine Last am Sabbattag hereinkäme.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 13, 20, 'Nun mußten die Händler und Verkäufer von Waren aller Art die Nacht ein- oder zweimal draußen vor der Stadt zubringen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 13, 21, 'Darauf verwarnte ich sie mit den Worten: »Wozu haltet ihr euch während der Nacht vor der Mauer auf? Wenn ihr das noch einmal tut, werde ich euch festnehmen lassen!« Von dieser Zeit an kamen sie am Sabbat nicht wieder.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 13, 22, 'Darauf befahl ich den Leviten, sie sollten sich reinigen und die Bewachung der Tore übernehmen, damit der Sabbattag heilig gehalten würde. Auch das gedenke mir, mein Gott, und übe Gnade an mir nach deiner großen Güte!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 13, 23, 'Ebenfalls in jenen Tagen sah ich mich nach den Juden um, welche asdoditische, ammonitische und moabitische Frauen geheiratet hatten.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 13, 24, 'Deren Kinder redeten nämlich zur Hälfte asdoditisch und konnten nicht mehr jüdisch sprechen, sondern verstanden nur die Sprache des betreffenden Volkes.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 13, 25, 'Da machte ich den Männern schwere Vorwürfe, fluchte ihnen, schlug einige von ihnen, zauste sie am Bart und beschwor sie bei Gott: »Ihr dürft eure Töchter durchaus nicht den Söhnen jener zu Frauen geben und dürft von den Töchtern jener keine für eure Söhne oder für euch selbst zu Frauen nehmen!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 13, 26, 'Hat sich nicht Salomo, der König von Israel, gerade um solcher Frauen willen zur Sünde verleiten lassen? Zwar hat es unter den vielen Völkern keinen König wie ihn gegeben, und er war ein Liebling seines Gottes, so daß Gott ihn zum König über ganz Israel machte; aber sogar ihn haben die ausländischen Frauen zur Sünde verleitet.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 13, 27, 'Und nun müssen wir von euch hören, daß ihr all dieses große Unrecht begeht, durch Verheiratung mit ausländischen Frauen treulos gegen unsern Gott zu handeln!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 13, 28, 'Und einer von den Söhnen des Hohepriesters Jojada, des Sohnes Eljasibs, hatte sich mit einer Tochter des Horoniters Sanballat verheiratet; den entfernte ich aus meiner Umgebung.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 13, 29, 'Gedenke ihnen, mein Gott, ihre vielfache Entweihung des Priestertums und des Bundes, den du mit der Priesterschaft und mit den Leviten geschlossen hast!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 13, 30, 'So habe ich sie von allem ausländischen Wesen gereinigt und die Dienstleistungen der Priester und der Leviten fest geordnet, für jeden einzelnen bezüglich seiner Amtspflichten,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 13, 31, 'auch für die Lieferung von Brennholz zu den festgesetzten Zeiten und für die Erstlingsgaben (habe ich Sorge getragen). Gedenke mir das, mein Gott, (und rechne es mir an) zum Guten!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 1, 1, 'Es begab sich unter der Regierung des Ahasveros – desselben Ahasveros, der von Indien bis Äthiopien über hundertundsiebenundzwanzig Provinzen herrschte –,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 1, 2, 'zu jener Zeit also, als der König Ahasveros auf seinem Königsthron in der Burg Susa saß,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 1, 3, 'im dritten Jahre seiner Regierung: da veranstaltete er für alle seine Fürsten und Diener ein Festmahl, wobei die persischen und medischen Heerführer, die Edlen und die höchsten Beamten der Provinzen vor ihm versammelt waren,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 1, 4, 'indem er dabei den Reichtum seiner königlichen Herrlichkeit und die glanzvolle Pracht seiner Größe viele Tage lang, nämlich hundertundachtzig Tage, zur Schau stellte.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 1, 5, 'Als dann diese Tage zu Ende waren, veranstaltete der König für die gesamte Bewohnerschaft, die sich in der Residenz Susa befand, vom Größten bis zum Kleinsten, ein siebentägiges Festmahl auf dem Hofe vor dem königlichen Schloßgarten.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 1, 6, 'Weiße und purpurblaue Vorhänge von Baumwolle waren mit Schnüren von Byssus und rotem Purpur mittels silberner Ringe an Marmorsäulen aufgehängt; Ruhepolster von schwerem, mit Gold- und Silberfäden durchwirktem Seidenzeug standen auf einem Pflaster aus Einlegewerk von Alabaster, von weißem und dunkelfarbigem Marmor und Perlmutterstein.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 1, 7, 'Die Getränke reichte man in goldenen Gefäßen, die an Formen immer wieder verschieden waren; und Wein aus des Königs Kellern war reichlich vorhanden, wie es der Freigebigkeit eines Königs entspricht.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 1, 8, 'Das Trinken aber ging der Verordnung gemäß ohne jeden Zwang vor sich; denn der König hatte an alle seine Palastbeamten die Weisung ergehen lassen, man solle jedem gestatten, es beim Trinken nach seinem Belieben zu halten. –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 1, 9, 'Auch die Königin Wasthi veranstaltete ein Festmahl für die Frauen im Inneren des königlichen Palastes des Königs Ahasveros.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 1, 10, 'Am siebten Tage nun, als der König durch den Wein in fröhliche Stimmung versetzt war, befahl er Mehuman, Bistha, Harbona, Bigtha und Abagtha, Sethar und Karkas, den sieben Kammerherren, die den Dienst beim König Ahasveros versahen,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 1, 11, 'sie sollten die Königin Wasthi im Schmuck der Königskrone vor den König bringen, um den Völkern und Fürsten ihre Schönheit zu zeigen; denn sie war in der Tat eine schöne Frau.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 1, 12, 'Doch die Königin Wasthi weigerte sich, auf den Befehl, den der König ihr durch die Kammerherren hatte zugehen lassen, zu erscheinen. Darüber ärgerte sich der König sehr und geriet in glühenden Zorn,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 1, 13, 'so daß er den Weisen, die sich auf die Zeiten verstanden – denn so wurde jede den König betreffende Angelegenheit dem Rat der Gesetz- und Rechtskundigen vorgelegt;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 1, 14, 'unter diesen standen ihm Karsna, Sethar, Admatha, Tharsis, Meres, Marsna und Memuchan, die sieben persischen und medischen Fürsten, am nächsten, die jederzeit Zutritt zum Könige hatten und die erste Stelle im Reiche einnahmen –, die Frage vorlegte:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 1, 15, '»Wie ist nach dem Gesetz mit der Königin Wasthi zu verfahren dafür, daß sie dem Befehl, den der König Ahasveros ihr durch die Kammerherren hatte zugehen lassen, nicht nachgekommen ist?«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 1, 16, 'Da antwortete Memuchan vor dem Könige und den Fürsten: »Nicht gegen den König allein hat sich die Königin Wasthi vergangen, sondern zugleich gegen alle Fürsten und alle Völker, die in sämtlichen Provinzen des Königs Ahasveros wohnen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 1, 17, 'Denn die Kunde von dem Verhalten der Königin wird zu allen Frauen dringen, und es werden ihnen ihre Eheherren verächtlich erscheinen, da sie sagen werden: ›Der König Ahasveros befahl, man solle die Königin Wasthi vor ihn bringen, aber sie kam nicht!‹');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 1, 18, 'Schon heute werden die persischen und medischen Fürstinnen, die von dem Verhalten der Königin Kenntnis erhalten haben, allen Fürsten des Königs davon erzählen, woraus dann Verachtung und Verdruß genug entstehen wird.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 1, 19, 'Wenn es also dem König genehm ist, so möge eine königliche Verordnung von ihm ausgehen und unter die persischen und medischen Gesetze aufgenommen werden, und zwar mit unwiderruflicher Geltung, daß Wasthi vor dem König Ahasveros nicht mehr erscheinen dürfe, und der König möge ihre königliche Würde auf eine andere übertragen, die besser ist als sie.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 1, 20, 'Wenn dann die Verfügung, die der König erlassen wird, in seinem ganzen Reiche, das ja groß ist, zu allgemeiner Kenntnis gelangt, so werden alle Frauen ihren Eheherren, vom größten bis zum kleinsten, die schuldige Ehre erweisen.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 1, 21, 'Dieser Vorschlag fand den Beifall des Königs und der Fürsten, und der König ging auf den Rat Memuchans ein.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 1, 22, 'Er sandte also Erlasse in alle Provinzen des Königs, in jede Provinz nach ihrer Schrift und an jedes Volk in der betreffenden Sprache: jeder Mann solle Herr in seinem Hause sein und dürfe anordnen, was ihm beliebe.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 2, 1, 'Als nach diesen Vorkommnissen die Aufregung des Königs Ahasveros sich gelegt hatte und er an Wasthi und ihr Verhalten und an den gegen sie gefaßten Beschluß zurückdachte,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 2, 2, 'sagten die Höflinge, die den König persönlich zu bedienen hatten: »Man sollte für den König junge Mädchen, Jungfrauen von besonderer Schönheit, suchen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 2, 3, 'Der König möge also in allen Provinzen seines Reiches Beamte bestellen, welche alle jungen Mädchen, Jungfrauen von besonderer Schönheit, im Frauenhause der Residenz Susa zusammenbringen sollen unter die Obhut des königlichen Kammerherrn Hegai, des Aufsehers über die Frauen. Man lasse ihnen dann die zur Schönheitspflege erforderliche Behandlung zuteil werden,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 2, 4, 'und das Mädchen, das dem König am meisten gefällt, soll als Königin an Wasthis Stelle treten.« Dieser Vorschlag fand den Beifall des Königs, und er brachte ihn zur Ausführung.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 2, 5, 'Nun lebte in der Residenz Susa ein jüdischer Mann namens Mardochai, der Sohn Jairs, des Sohnes Simeis, des Sohnes des Kis, aus dem Stamme Benjamin;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 2, 6, 'er war aus Jerusalem mitweggeführt worden mit den Gefangenen, die zusammen mit dem jüdischen Könige Jechonja von Nebukadnezar, dem Babylonierkönige, in die Gefangenschaft geführt worden waren.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 2, 7, 'Er war der Pflegevater der Hadassa, das ist Esther, der Tochter seines Oheims; denn sie hatte weder Vater noch Mutter, war aber ein Mädchen von herrlicher Gestalt und außerordentlicher Schönheit; und nach dem Tode ihrer beiden Eltern hatte Mardochai sie als Tochter angenommen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 2, 8, 'Als nun der Erlaß und Befehl des Königs bekanntgemacht war und viele junge Mädchen in der Residenz Susa zusammengebracht und unter die Obhut Hegais gestellt wurden, da wurde auch Esther in den königlichen Palast aufgenommen und kam unter die Aufsicht Hegais, des Hüters der Frauen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 2, 9, 'Weil nun das junge Mädchen ihm gefiel und seine Gunst gewann, war er eifrig darauf bedacht, ihr die wirksamsten Schönheitsmittel und eine passende Kost zukommen zu lassen und ihr die sieben auserlesensten Dienerinnen aus dem königlichen Schlosse zu überweisen und sie mit ihren Dienerinnen im schönsten Teile des Frauenhauses unterzubringen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 2, 10, 'Esther teilte aber niemandem etwas von ihrer jüdischen Herkunft und ihren Familienverhältnissen mit, weil Mardochai ihr verboten hatte, etwas davon zu verraten.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 2, 11, 'Mardochai ging aber Tag für Tag vor dem Hofe am Frauenhause auf und ab, um sich zu erkundigen, ob es der Esther wohl erginge und was mit ihr geschähe.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 2, 12, 'Wenn aber die Reihe an irgendein junges Mädchen kam, sich zum König Ahasveros zu begeben, nachdem sie zwölf Monate lang nach den für die Frauen geltenden Verordnungen gelebt hatte – denn so lange Zeit erforderte ihre Schönheitspflege, nämlich sechs Monate lang eine Behandlung mit Myrrhenöl und sechs Monate mit Spezereien und anderen Schönheitsmitteln der Frauen –,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 2, 13, 'und wenn sich das junge Mädchen alsdann zum Könige hineinbegab, so wurde ihr alles, was sie verlangte, aus dem Frauenhause in den königlichen Palast mitgegeben;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 2, 14, 'am Abend ging sie hinein, und am Morgen kehrte sie zurück, und zwar in das zweite Frauenhaus unter die Aufsicht des königlichen Kammerherrn Saasgas, des Hüters der Nebenfrauen; sie durfte dann nicht wieder zum König kommen, außer wenn der König Gefallen an ihr gefunden hatte und sie ausdrücklich berufen wurde.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 2, 15, 'Als nun Esther, die Tochter Abihails, des Oheims Mardochais, der sie als Tochter angenommen hatte, an der Reihe war, sich zum König zu begeben, da verlangte sie nichts, als was Hegai, der königliche Kammerherr, der Hüter der Frauen, ihr riet; denn Esther hatte sich die Zuneigung aller erworben, die sie sahen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 2, 16, 'Als nun Esther zum König Ahasveros in seinen königlichen Palast im zehnten Monat – das ist der Monat Tebeth – im siebten Jahre seiner Regierung gebracht war,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 2, 17, 'gewann der König sie lieber als alle anderen Frauen, und sie erlangte seine Gunst und Zuneigung in höherem Grade als alle übrigen Jungfrauen, so daß er ihr die Königskrone aufs Haupt setzte und sie zur Königin an Wasthis Stelle erhob.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 2, 18, 'Darauf veranstaltete der König für alle seine Würdenträger und Beamten ein großes Festmahl zu Ehren der Esther, gewährte den Provinzen einen Steuererlaß und bewilligte eine Getreidespende mit königlicher Freigebigkeit.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 2, 19, 'Als dann zum zweitenmal Jungfrauen zusammengeholt wurden, während Mardochai sich gerade im Tor des Königs(palastes) aufhielt –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 2, 20, 'Esther hatte aber von ihrer Familie und ihrer jüdischen Herkunft nichts kundwerden lassen, wie Mardochai ihr geboten hatte; sie tat überhaupt alles, was Mardochai ihr auftrug, gerade wie früher, als sie noch in Pflege bei ihm war –,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 2, 21, 'in jenen Tagen also, während Mardochai sich gerade im Tor des Königs(palastes) aufhielt, gerieten Bigthan und Theres, zwei königliche Kammerherren aus der Zahl der Schwellenhüter, in solchen Zorn, daß sie dem König Ahasveros nach dem Leben trachteten.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 2, 22, 'Aber Mardochai erhielt Kunde von der Sache und machte der Königin Esther Mitteilung davon; Esther aber erstattete dem Könige Anzeige im Auftrage Mardochais.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 2, 23, 'Als nun die Sache untersucht wurde und sich als wahr herausstellte, wurden jene beiden ans Kreuz geschlagen und das Vorkommnis ins Buch der Zeitgeschichte für den König eingetragen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 3, 1, 'Nach diesen Begebenheiten erhob der König Ahasveros den Agagiten Haman, den Sohn Hammedathas, zu den höchsten Ehren und Würden und wies ihm seinen Stuhl über dem aller Fürsten in seiner Umgebung an.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 3, 2, 'So mußten denn alle Diener des Königs, die sich am königlichen Hofe befanden, die Knie vor Haman beugen und sich vor ihm niederwerfen; denn so hatte der König es ihm zu Ehren befohlen. Mardochai aber beugte die Knie nicht und warf sich auch nicht nieder.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 3, 3, 'Da fragten ihn die Diener des Königs, die am Hofe des Königs waren, warum er den Befehl des Königs unbeachtet lasse.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 3, 4, 'Als sie diese Frage Tag für Tag an ihn richteten, ohne daß er auf sie hörte, meldeten sie es dem Haman, um zu sehen, ob die Rechtfertigung Mardochais anerkannt werden würde; er hatte ihnen nämlich mitgeteilt, daß er ein Jude sei.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 3, 5, 'Als nun Haman selbst sah, daß Mardochai vor ihm die Knie nicht beugte und sich nicht niederwarf, geriet er in die höchste Wut;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 3, 6, 'doch da er es unter seiner Würde hielt, an Mardochai allein die Hand zu legen – man hatte ihm nämlich mitgeteilt, welchem Volke Mardochai angehöre –, so faßte er den Plan, alle Juden, die im ganzen Reiche des Ahasveros lebten, zugleich mit Mardochai auszurotten.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 3, 7, 'Im ersten Monat – das ist der Monat Nisan –, im zwölften Regierungsjahr des Königs Ahasveros, warf man das Pur, d.h. das Los, in Gegenwart Hamans von einem Tage zum andern und von einem Monat zum andern bis zum zwölften Monat, das ist der Monat Adar (und das Los fiel auf den dreizehnten Tag).');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 3, 8, 'Dann sagte Haman zum König Ahasveros: »Da ist ein einzigartiges Volk, das unter den Völkern in allen Provinzen deines Reiches zerstreut und abgesondert lebt und dessen Gesetze von denen aller anderen Völker abweichen; da sie sich nun nach den Gesetzen des Königs nicht richten, so ist es für den König nicht geziemend, sie ruhig gewähren zu lassen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 3, 9, 'Wenn es dem König genehm ist, so möge ihre Ausrottung durch einen schriftlichen Erlaß verfügt werden; ich werde dann auch zehntausend Talente Silber in die Hände der Schatzmeister darwägen können, damit diese sie in die königlichen Schatzhäuser abführen.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 3, 10, 'Da zog der König seinen Siegelring von der Hand und reichte ihn dem Agagiten Haman, dem Sohne Hammedathas, dem Judenfeinde,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 3, 11, 'indem er zu ihm sagte: »Das Geld sei dir überlassen und das Volk ebenso: du magst mit ihm nach deinem Belieben verfahren.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 3, 12, 'Da wurden die königlichen Staatsschreiber am dreizehnten Tage des ersten Monats berufen, und es wurde genau nach der Weisung Hamans an die königlichen Landpfleger und die Statthalter der einzelnen Provinzen und an die Fürsten eines jeden Volkes mit der Schrift jeder einzelnen Provinz und in der besonderen Sprache jedes Volkes eine schriftliche Verfügung im Namen des Königs Ahasveros erlassen und mit dem Siegelringe des Königs untersiegelt.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 3, 13, 'Die Schreiben wurden dann durch die Eilboten in alle Provinzen des Königs versandt, daß alle Juden, jung und alt, Kinder und Weiber, an einem Tage, nämlich am dreizehnten des zwölften Monats – das ist der Monat Adar –, ausgerottet, ermordet und umgebracht werden sollten; ihr Vermögen solle der Plünderung anheimfallen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 3, 14, 'Damit aber die Verfügung in jeder einzelnen Provinz erlassen würde, ward eine Abschrift des Schreibens allen Völkern bekanntgemacht, damit sie sich auf den genannten Tag bereithielten.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 3, 15, 'Die Eilboten machten sich nach dem Befehl des Königs eilends auf den Weg, während der Erlaß in der Residenz Susa veröffentlicht wurde. Der König und Haman aber setzten sich hin, um zu zechen, während in der Stadt Susa Bestürzung herrschte.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 4, 1, 'Als nun Mardochai alles erfuhr, was vorgegangen war, zerriß er seine Kleider, legte ein Trauergewand an und (streute sich) Asche (aufs Haupt), ging dann aus seinem Hause mitten in die Stadt hinein und wehklagte dabei laut und schmerzlich.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 4, 2, 'So kam er bis vor das Tor des Königs(palastes); denn in das Tor des Palastes selbst durfte man in einem Trauergewande nicht treten.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 4, 3, 'Auch in allen einzelnen Provinzen, überall, wohin die Verfügung und der Erlaß des Königs gelangte, herrschte bei den Juden große Trauer; man fastete, weinte und wehklagte; die meisten saßen in Sackleinen und auf Asche da.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 4, 4, 'Als nun die Dienerinnen der Esther und ihre Kammerherren kamen und es ihr meldeten, geriet die Königin in große Aufregung und sandte dem Mardochai Kleider, damit er sie anzöge und das Trauergewand ablegte; aber er nahm sie nicht an.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 4, 5, 'Da ließ Esther den Hathach kommen, einen von den Kammerherren, den der König zu ihrem Dienst bestellt hatte, und gab ihm den Auftrag, sich bei Mardochai zu erkundigen, was das zu bedeuten habe und warum es geschehe.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 4, 6, 'Als nun Hathach zu Mardochai hinauskam auf den öffentlichen Platz, der vor dem Tor des königlichen Palastes lag,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 4, 7, 'teilte Mardochai ihm alles mit, was ihn betroffen hatte, auch den bestimmten Betrag der Geldsumme, die Haman als Entgelt für die Ermordung der Juden an die königliche Schatzkammer zu zahlen versprochen hatte.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 4, 8, 'Außerdem übergab er ihm eine Abschrift der in Susa zu ihrer Niedermetzelung erlassenen schriftlichen Verordnung, damit er sie der Esther zeige und ihr alles mitteile und sie veranlasse, sich zum Könige zu begeben, um ihn um Gnade anzuflehen und bei ihm Fürbitte für ihr Volk einzulegen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 4, 9, 'Als Hathach nun zurückgekommen war und der Esther die Botschaft Mardochais mitgeteilt hatte,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 4, 10, 'sandte Esther den Hathach nochmals an Mardochai mit der Meldung:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 4, 11, '»Alle Diener des Königs und die Leute in den königlichen Provinzen wissen, daß für jedermann, es sei Mann oder Frau, der zum König in den inneren Hof eintritt, ohne gerufen zu sein, ein und dasselbe Gesetz gilt, nämlich daß er sterben muß, es sei denn, daß der König ihm sein goldenes Zepter entgegenstreckt, damit er am Leben bleibe. Ich aber bin seit nunmehr schon dreißig Tagen nicht zum König berufen worden.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 4, 12, 'Als man nun Mardochai die Meldung der Esther mitgeteilt hatte,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 4, 13, 'ließ dieser ihr folgende Antwort zukommen: »Bilde dir nicht ein, daß infolge deiner Zugehörigkeit zum königlichen Hofe du allein von allen Juden mit dem Leben davonkommen werdest!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 4, 14, 'Denn wenn du wirklich zu dieser Zeit stille sitzen wolltest, so wird den Juden Hilfe und Rettung von einer andern Seite her erstehen; du aber und deine ganze Familie, ihr werdet umkommen! Und wer weiß, ob du nicht gerade für eine Zeit, wie diese ist, zur königlichen Würde gelangt bist?«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 4, 15, 'Da ließ Esther dem Mardochai zurücksagen:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 4, 16, '»Gehe hin, versammle alle Juden, die sich in Susa befinden, und fastet um meinetwillen, und zwar drei Tage lang bei Tag und Nacht, ohne zu essen und zu trinken. Auch ich will mit meinen Dienerinnen ebenso fasten und mich alsdann zum König begeben, wenn es auch gegen das Gesetz ist. Muß ich dann sterben, nun, so sterbe ich!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 4, 17, 'Da ging Mardochai weg und tat ganz so, wie Esther ihm angegeben hatte.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 5, 1, 'Am dritten Tage nun legte Esther königliche Gewandung an und trat in den inneren Vorhof des königlichen Palastes, dem Palast des Königs gegenüber, während der König eben im königlichen Palast, dem Eingang zum Palast gegenüber, auf seinem Königsthrone saß.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 5, 2, 'Als nun der König die Königin Esther im Vorhofe stehen sah, fand sie Gnade vor ihm, so daß er ihr das goldene Zepter entgegenstreckte, das er in der Hand hielt. Da trat Esther hinzu und berührte die Spitze des Zepters.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 5, 3, 'Darauf sagte der König zu ihr: »Was ist mit dir, Königin Esther, und was ist dein Begehr? Wäre es auch die Hälfte des Königreichs – sie sollte dir gegeben werden!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 5, 4, 'Da antwortete Esther: »Wenn es dem König genehm ist, so wolle der König sich heute mit Haman zu dem Gastmahl einfinden, das ich für ihn bereitet habe!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 5, 5, 'Da befahl der König: »Ruft sofort Haman herbei, damit wir den Wunsch Esthers erfüllen!« Als dann der König sich mit Haman zu dem Mahl eingefunden hatte, das von Esther zugerichtet worden war,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 5, 6, 'sagte der König zu Esther beim Weintrinken: »Was ist deine Bitte? Sie soll dir gewährt werden! Und was ist dein Wunsch? Wäre es auch die Hälfte des Königreichs – es soll geschehen!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 5, 7, 'Da antwortete Esther mit den Worten: »Meine Bitte und mein Wunsch ist:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 5, 8, 'Wenn ich beim König Gnade gefunden habe und wenn es dem König genehm ist, mir meine Bitte zu gewähren und meinen Wunsch zu erfüllen, so wolle der König mit Haman (auch morgen) zu dem Gastmahl kommen, das ich für sie herrichten will: morgen werde ich dann der Aufforderung des Königs nachkommen.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 5, 9, 'Haman nun begab sich an diesem Tage in fröhlicher Stimmung und guten Mutes auf den Heimweg; als er aber Mardochai im Tor des Königs(palastes) erblickte und dieser sich weder erhob noch ihn überhaupt beachtete, geriet er in volle Wut über Mardochai;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 5, 10, 'doch er bezwang sich. Als er aber nach Hause gekommen war, ließ er seine Freunde und seine Gattin Seres holen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 5, 11, 'Diesen erzählte er von seinem großartigen Reichtum und von seinen vielen Söhnen und besonders davon, wie der König ihn ausgezeichnet und ihn über die Fürsten und Beamten des Königs erhoben habe.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 5, 12, 'Dann fuhr er fort: »Auch hat die Königin Esther zu dem Gastmahl, das sie ausgerichtet hatte, keinen mit dem König geladen als nur mich; und auch für morgen bin ich mit dem König von ihr eingeladen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 5, 13, 'Aber das alles befriedigt mich nicht, solange ich noch den Juden Mardochai im Tor des Königs(palastes) sitzen sehen muß!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 5, 14, 'Da sagten seine Frau Seres und alle seine Freunde zu ihm: »Man richte doch einen Pfahl von fünfzig Ellen Höhe auf; dann sprich morgen früh mit dem König, daß man Mardochai daran aufhängen möge; danach kannst du vergnügt mit dem König zum Gastmahl gehen.« Dieser Vorschlag gefiel dem Haman so, daß er den Pfahl aufrichten ließ.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 6, 1, 'Als in der folgenden Nacht der König nicht schlafen konnte, ließ er sich das Buch der Denkwürdigkeiten, die Reichschronik, holen; aus dieser wurde ihm dann vorgelesen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 6, 2, 'Da fand sich darin verzeichnet, daß Mardochai den Bigthana und Theres, die beiden königlichen Kammerherren aus der Zahl der Schwellenhüter, zur Anzeige gebracht hatte, weil sie mit dem Plan umgegangen waren, den König Ahasveros aus dem Wege zu räumen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 6, 3, 'Als nun der König fragte: »Welche Ehre und Auszeichnung ist dem Mardochai dafür zuteil geworden?« und die Leibdiener, die den Dienst beim Könige hatten, ihm die Antwort gaben, es sei ihm gar keine Belohnung zuteil geworden,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 6, 4, 'fragte der König weiter: »Wer ist im Vorhofe?« Nun war Haman gerade in den äußeren Vorhof des königlichen Palastes getreten, um beim König zu beantragen, man möge Mardochai an den Pfahl hängen, den er für ihn hatte aufrichten lassen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 6, 5, 'Als nun die Leibdiener dem König sagten, Haman sei es, der im Vorhof stehe, befahl der König, er solle eintreten.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 6, 6, 'Als nun Haman eingetreten war, fragte ihn der König: »Was kann man einem Manne tun, den der König auszuzeichnen wünscht?« Da dachte Haman bei sich: »Wen anders sollte der König eher auszuzeichnen wünschen als mich?«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 6, 7, 'Er antwortete also dem König: »Wenn der König jemanden auszuzeichnen wünscht,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 6, 8, 'so bringe man ein königliches Gewand herbei, das der König selbst bereits getragen, und ein Pferd, auf dem der König selbst schon geritten hat und auf dessen Kopfe die Königskrone angebracht ist;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 6, 9, 'man übergebe dann das Gewand und das Pferd einem der vornehmsten Fürsten des Königs, damit dieser den Mann, den der König auszuzeichnen wünscht, damit bekleide und ihn auf dem Pferde über den Hauptplatz der Stadt reiten lasse und dabei vor ihm her ausrufe: ›So tut man dem Manne, den der König auszuzeichnen wünscht!‹«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 6, 10, 'Da sagte der König zu Haman: »Nimm sofort ein solches Gewand und das Pferd, so wie du gesagt hast, und mache es so mit dem Juden Mardochai, der im Tor des Königs(palastes) sitzt! Unterlaß nichts von allem, was du vorgeschlagen hast!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 6, 11, 'Da holte Haman das erforderliche Kleid und das Pferd, bekleidete Mardochai (damit), ließ ihn auf dem Hauptplatz der Stadt umherreiten und rief vor ihm her aus: »So tut man dem Manne, den der König auszuzeichnen wünscht!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 6, 12, 'Hierauf kehrte Mardochai an das Tor des Königspalastes zurück; Haman aber eilte traurig und mit verhülltem Haupt nach Hause');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 6, 13, 'und erzählte seiner Gattin Seres und seinen sämtlichen Freunden alles, was ihm widerfahren war. Da sagten seine klugen Freunde und seine Frau Seres zu ihm: »Wenn Mardochai, vor dem du jetzt zum erstenmal den kürzeren gezogen hast, ein geborener Jude ist, so wirst du nichts gegen ihn ausrichten, sondern ihm gegenüber ganz den kürzeren ziehen!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 6, 14, 'Während sie so noch mit ihm sprachen, erschienen die Kammerherren des Königs und geleiteten Haman eiligst zu dem Mahl, das Esther zugerichtet hatte.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 7, 1, 'Als nun der König und Haman sich zum festlichen Mahl bei der Königin Esther begeben hatten,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 7, 2, 'sagte der König zu Esther auch am zweiten Tage beim Weintrinken: »Was ist deine Bitte, Königin Esther? Sie soll dir gewährt werden! Und was ist dein Wunsch? Wäre es auch die Hälfte des Königreichs – es soll geschehen!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 7, 3, 'Da antwortete die Königin Esther mit den Worten: »Wenn ich Gnade vor dir gefunden habe, o König, und wenn es dem König genehm ist, so möge mir geschenkt werden mein Leben: das ist meine Bitte, und mein Volk: das ist mein Wunsch!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 7, 4, 'Denn wir sind verkauft worden, ich und mein Volk, um ausgerottet, ermordet und umgebracht zu werden! Und wenn wir nur als Sklaven und Sklavinnen verkauft wären, so würde ich geschwiegen haben, denn unsere Bedrängnis wäre nicht hinreichend, um den König zu belästigen.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 7, 5, 'Da fragte der König Ahasveros die Königin Esther: »Wer ist der, und wo ist der, welcher es sich in den Sinn hat kommen lassen, so zu handeln?«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 7, 6, 'Esther erwiderte: »Der Widersacher und Feind ist der Bösewicht Haman da!« Da fuhr Haman vor dem König und der Königin erschreckt zusammen;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 7, 7, 'der König aber stand in höchster Erregung vom Weingelage auf und begab sich in den Garten am Palast, während Haman zurückblieb, um bei der Königin Esther um sein Leben zu flehen; denn er sah wohl ein, daß sein Verderben beim Könige fest beschlossene Sache war.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 7, 8, 'Als dann der König aus dem Schloßgarten wieder in den Saal, in dem das Gastmahl stattgefunden, zurückkehrte, hatte Haman sich gerade an dem Polster niedergeworfen, auf dem Esther lag. Da rief der König aus: »Will er etwa gar der Königin in meinem eigenen Hause Gewalt antun?« Das Wort war kaum dem Munde des Königs entfahren, als man auch schon dem Haman das Gesicht verhüllte.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 7, 9, 'Da sagte Harbona, einer von den Kammerherren, die den König zu bedienen hatten: »Es steht ja auch schon der Pfahl, den Haman für Mardochai, den Wohltäter des Königs, bei seinem Hause hat errichten lassen, fünfzig Ellen hoch!« Da befahl der König: »Hängt ihn daran!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 7, 10, 'So hängte man denn Haman an den Pfahl, den er für Mardochai hatte errichten lassen; darauf legte sich der Zorn des Königs.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 8, 1, 'An demselben Tage schenkte der König Ahasveros der Königin Esther das Haus des Judenfeindes Haman; Mardochai aber erhielt Zutritt beim König; denn Esther hatte dem König mitgeteilt, wie er mit ihr verwandt war.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 8, 2, 'Der König zog dann seinen Siegelring, den er dem Haman hatte abnehmen lassen, vom Finger ab und übergab ihn Mardochai; Esther aber übertrug dem Mardochai die Verwaltung des Hauses Hamans.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 8, 3, 'Hierauf verhandelte Esther nochmals mit dem Könige, indem sie sich ihm zu Füßen warf und ihn unter Tränen anflehte, er möge doch die Bosheit des Agagiters Haman und den Anschlag, den dieser gegen die Juden ins Werk gesetzt hatte, rückgängig machen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 8, 4, 'Als der König nun der Esther das goldene Zepter entgegenstreckte, stand Esther auf, trat vor den König');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 8, 5, 'und sagte: »Wenn es dem König genehm ist und ich Gnade vor ihm gefunden habe und es dem König gut erscheint und ich seine Zuneigung besitze, so möge durch einen schriftlichen Erlaß verordnet werden, daß die auf den Anschlag des Agagiters Haman, des Sohnes Hammedathas, bezüglichen Schreiben, in denen er die Ermordung der in allen Provinzen des Reiches lebenden Juden angeordnet hat, widerrufen werden.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 8, 6, 'Denn wie vermöchte ich das Unglück mit anzusehen, das meine Volksgenossen treffen soll? Und wie vermöchte ich den Untergang meines Geschlechts mit anzusehen?«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 8, 7, 'Da antwortete der König Ahasveros der Königin Esther und dem Juden Mardochai: »Wie ihr wißt, habe ich das Haus Hamans der Esther geschenkt, und ihn selbst hat man an den Pfahl gehängt zur Strafe dafür, daß er sich an den Juden hat vergreifen wollen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 8, 8, 'So mögt ihr nun im Namen des Königs in betreff der Juden schriftlich verfügen, wie ihr es für angemessen haltet, und es dann mit dem Siegelring des Königs untersiegeln; dagegen eine Verfügung, die schriftlich im Namen des Königs erlassen und mit dem Siegelring des Königs untersiegelt ist, kann nicht rückgängig gemacht werden.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 8, 9, 'So wurden denn damals – es war am dreiundzwanzigsten Tage des dritten Monats, d.h. des Monats Siwan – die königlichen Staatsschreiber berufen, und es wurde genau nach der Anweisung Mardochais in betreff der Juden an die Landpfleger und Statthalter und Fürsten der hundertundsiebenundzwanzig Provinzen von Indien bis Äthiopien, und zwar einer jeden Provinz mit ihrer Schrift und einem jeden Volke in seiner Sprache, geschrieben, auch an die Juden mit ihrer Schrift und in ihrer Sprache;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 8, 10, 'und zwar ließ er im Namen des Königs Ahasveros schreiben und mit dem Siegelring des Königs untersiegeln und sandte dann die Schreiben durch die reitenden Eilboten ab, die auf den vorzüglichsten, aus den Gestüten stammenden Rennpferden ritten.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 8, 11, 'In den Schreiben war verfügt, daß der König den Juden in allen einzelnen Städten gestatte, sich zusammenzutun und ihr Leben zu verteidigen, indem sie jedes Aufgebot eines Volkes oder einer Provinz, das sie angreifen würde, samt ihren Kindern und Frauen, vernichteten, ermordeten und umbrächten; auch sollten sie deren Vermögen plündern dürfen,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 8, 12, 'und zwar an ein und demselben Tage in allen Provinzen des Königs Ahasveros, nämlich am dreizehnten Tage des zwölften Monats, d.h. des Monats Adar.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 8, 13, 'Damit aber die Verfügung in jeder einzelnen Provinz erlassen würde, wurde eine Abschrift des Schreibens allen Völkern bekanntgemacht, damit die Juden an dem betreffenden Tage bereit wären, an ihren Feinden Rache zu nehmen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 8, 14, 'Die auf den vorzüglichsten Rennpferden reitenden Eilboten machten sich dann auf Befehl des Königs schleunigst und in aller Eile auf den Weg, während die Verfügung in der Residenz Susa veröffentlicht wurde.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 8, 15, 'Mardochai aber trat aus dem Palast des Königs hervor in königlicher Kleidung von purpurblauer und weißer Baumwolle, mit einem großen goldenen Stirnreif und einem Mantel von Byssus und rotem Purpur; und die Stadt Susa jauchzte und freute sich:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 8, 16, 'den Juden war Glück und Freude, Jubel und Ehre zuteil geworden.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 8, 17, 'Auch in allen Provinzen und in jeder Stadt, überall, wohin die Verfügung und der Erlaß des Königs gelangte, war bei den Juden Freude und Jubel, Festmahl und Feiertag; und viele von der heidnischen Bevölkerung des Landes traten zum Judentum über, weil Furcht vor den Juden über sie gekommen war.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 9, 1, 'Im zwölften Monat nun, d.h. im Monat Adar, am dreizehnten Tage dieses Monats, als die Verfügung und der Erlaß des Königs zur Ausführung kommen sollte, an eben dem Tage, an welchem die Feinde der Juden gehofft hatten, sie zu überwältigen – die Sache wandte sich aber so, daß die Juden ihrerseits ihre Feinde überwältigten –,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 9, 2, 'da taten sich die Juden in ihren Städten in allen Provinzen des Königs Ahasveros zusammen, um Hand an die zu legen, welche ihnen Unheil zuzufügen gedacht hatten; und niemand konnte ihnen Widerstand leisten, denn die Furcht vor ihnen hatte sich aller Völker bemächtigt.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 9, 3, 'Auch alle Fürsten in den Provinzen sowie die Landpfleger und Statthalter und Beamten des Königs gewährten den Juden Unterstützung, weil die Furcht vor Mardochai sie befallen hatte;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 9, 4, 'denn Mardochai stand am königlichen Hofe groß da, und sein Ruf war in alle Provinzen gedrungen; denn Mardochais Ansehen war unaufhaltsam im Steigen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 9, 5, 'So richteten denn die Juden unter allen ihren Feinden mit dem Schwerte, durch Morden und Niederhauen, ein Blutbad an und gingen gegen ihre Widersacher nach Herzenslust vor.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 9, 6, 'Auch in der Residenz Susa mordeten die Juden und brachten fünfhundert Mann ums Leben;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 9, 7, 'dazu töteten sie Parsandatha, Dalphon, Aspatha,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 9, 8, 'Poratha, Adalja, Aridatha,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 9, 9, 'Parmastha, Arisai, Aridai und Wajesatha,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 9, 10, 'die zehn Söhne Hamans, des Sohnes Hammedathas, des Judenverfolgers; aber fremdes Hab und Gut rührten sie nicht an.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 9, 11, 'An demselben Tage kam die Zahl der in der Residenz Susa Getöteten zur Kenntnis des Königs.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 9, 12, 'Da sagte der König zu der Königin Esther: »In der Residenz Susa haben die Juden gemordet und fünfhundert Mann ums Leben gebracht, auch die zehn Söhne Hamans; was mögen sie da wohl in den übrigen Provinzen des Reiches angerichtet haben? Doch was ist deine Bitte? Sie soll dir gewährt werden. Und was ist weiter noch dein Wunsch? Er soll erfüllt werden.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 9, 13, 'Da antwortete Esther: »Wenn es dem König genehm ist, so möge auch morgen noch den Juden in Susa gestattet sein, in derselben Weise wie heute zu verfahren; die zehn Söhne Hamans aber möge man an den Pfahl hängen.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 9, 14, 'Da gebot der König, daß so verfahren werden sollte; und der betreffende Befehl wurde in Susa erlassen, und die zehn Söhne Hamans wurden aufgehängt.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 9, 15, 'So taten sich denn die Juden in Susa auch am vierzehnten Tage des Monats Adar zusammen und brachten in Susa noch dreihundert Mann um; aber fremdes Hab und Gut rührten sie nicht an.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 9, 16, 'Auch die übrigen Juden, die in den Provinzen des Reiches wohnten, hatten sich zusammengetan, um ihr Leben zu verteidigen und sich Ruhe vor ihren Feinden zu verschaffen; sie hatten 75000 von ihren Feinden umgebracht, ohne jedoch fremdes Hab und Gut anzurühren.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 9, 17, 'Das war am dreizehnten Tage des Monats Adar geschehen, aber am vierzehnten Tage des Monats hatten sie sich ruhig verhalten und ihn zu einem Tage der Festgelage und der Freude gemacht.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 9, 18, 'In Susa dagegen hatten sich die Juden sowohl am dreizehnten als auch am vierzehnten Tage dieses Monats zusammengetan und erst am fünfzehnten Tage Ruhe gehalten und diesen Tag zu einem Tage der Festgelage und der Freude gemacht.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 9, 19, 'Darum feiern die Juden auf dem Lande, die in den offenen Ortschaften wohnen, den vierzehnten Tag des Monats Adar als einen Tag der Freude und der Schmausereien und als einen Festtag, an dem man sich gegenseitig (leckere) Gerichte zusendet.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 9, 20, 'Mardochai schrieb hierauf diese Begebenheiten auf und sandte Schreiben an alle Juden in allen Provinzen des Königs Ahasveros, die nahen und die fernen,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 9, 21, 'um sie zu dem Brauche zu verpflichten, daß sie sei es den vierzehnten, sei es den fünfzehnten Tag des Monats Adar Jahr für Jahr feierten');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 9, 22, 'als die Tage, an denen die Juden Ruhe vor ihren Feinden erlangt hatten, und als den Monat, in dem sich der Kummer für sie in Freude verwandelt hatte und die Trauer in einen Festtag, so daß sie diese (Tage) feierten als Tage der Festgelage und der Freude, an denen man sich gegenseitig (leckere) Gerichte zusendet und die Armen beschenkt.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 9, 23, 'So nahmen denn die Juden das, was sie damals zum erstenmal getan und was Mardochai ihnen brieflich geraten hatte, als stehenden Brauch an.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 9, 24, 'Weil der Agagiter Haman, der Sohn Hammedathas, der Feind aller Juden, den Plan gegen die Juden gefaßt hatte, sie zu vernichten, und weil er das Pur, d.h. das Los, hatte werfen lassen, um sie zu verderben und auszurotten,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 9, 25, 'der König aber, als Esther vor ihn getreten war, durch einen schriftlichen Erlaß angeordnet hatte, daß sein boshafter Anschlag, den er gegen die Juden ersonnen hatte, auf sein eigenes Haupt zurückfallen und daß man ihn und seine Söhne an den Pfahl hängen solle:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 9, 26, 'darum hat man diese Tage ›Purim‹ genannt nach dem Worte Pur. Aus diesen Gründen also – wegen des gesamten Inhalts dieses Briefes und wegen alles dessen, was sie selbst erlebt oder was durch andere zu ihrer Kenntnis gekommen war –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 9, 27, 'ordneten die Juden an und setzten für sich und ihre Nachkommen und für alle, die sich ihnen anschließen würden, als unumstößliche Satzung fest, diese beiden Tage in der für sie vorgeschriebenen Weise und zu der für sie bestimmten Zeit Jahr für Jahr festlich zu begehen;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 9, 28, 'und diese beiden Tage sollten im Gedächtnis festgehalten und von Geschlecht zu Geschlecht in allen Familien, Provinzen und Ortschaften gefeiert werden, so daß diese Purimtage unter den Juden niemals in Abgang kämen und die Erinnerung an sie bei ihren Nachkommen niemals verschwände.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 9, 29, 'Weiter schrieb die Königin Esther, die Tochter Abihails, mit allem Nachdruck, um dieses Purimschreiben zur Geltung zu bringen,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 9, 30, 'und sandte Briefe an alle Juden in die hundertundsiebenundzwanzig Provinzen, in das ganze Königreich des Ahasveros, freundliche und treugemeinte Worte,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 9, 31, 'um die Feier dieser Purimtage in betreff der für sie bestimmten Zeiten zur festen Satzung zu erheben, ganz so wie der Jude Mardochai und die Königin Esther es für sie angeordnet und wie sie es auch für sich selbst und für ihre Nachkommen festgesetzt hatten, nämlich die Vorschriften über die Fasten und ihre Wehklage.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 9, 32, 'Der Erlaß Esthers erhob diese Purimvorschriften zum Gesetz und wurde in einer Urkunde aufgezeichnet.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 10, 1, 'Der König Ahasveros legte dann dem Festlande und den Inseln des Meeres eine Abgabe auf.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 10, 2, 'Und alle Erweise seines gewaltigen und machtvollen Wirkens und die genaue Schilderung der hohen Stellung Mardochais, zu der ihn der König erhob, das alles findet sich bekanntlich aufgezeichnet im Buch der Denkwürdigkeiten der medischen und persischen Könige.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 10, 3, 'Denn der Jude Mardochai war der Erste im Range nach dem König Ahasveros und hochgeachtet bei den Juden und beliebt bei der Menge seiner Volksgenossen, weil er das Beste seines Volkes suchte und für das Wohl seines ganzen Stammes eintrat.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 1, 1, 'Es lebte einst ein Mann im Lande Uz, Hiob mit Namen, und dieser Mann war fromm und rechtschaffen, fürchtete Gott und mied das Böse.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 1, 2, 'Sieben Söhne und drei Töchter wurden ihm geboren;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 1, 3, 'dazu besaß er siebentausend Stück Kleinvieh und dreitausend Kamele, fünfhundert Joch Rinder, fünfhundert Eselinnen und ein sehr zahlreiches Gesinde, so daß dieser Mann unter allen Bewohnern des Ostlandes der angesehenste war.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 1, 4, 'Nun pflegten seine Söhne im Hause eines jeden von ihnen an seinem Tage ein festliches Mahl zu veranstalten und luden dann allemal auch ihre drei Schwestern ein, mit ihnen zu essen und zu trinken.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 1, 5, 'Wenn aber die Tage des betreffenden Gastmahls um waren, ließ Hiob ihnen sagen, sie möchten sich heiligen; er stand dann am andern Morgen früh auf und brachte für jeden von ihnen ein Brandopfer dar; denn Hiob dachte: »Vielleicht haben meine Kinder sich versündigt und in ihrem Herzen Gott verwünscht.« So machte es Hiob jedesmal.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 1, 6, 'Nun begab es sich eines Tages, daß die Gottessöhne kamen, um sich vor Gott, den HERRN, zu stellen; und unter ihnen erschien auch der Satan.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 1, 7, 'Da fragte der HERR den Satan: »Woher kommst du?« Der Satan gab dem HERRN zur Antwort: »Ich bin auf der Erde umhergestreift und habe eine Wanderung auf ihr vorgenommen.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 1, 8, 'Da sagte der HERR zum Satan: »Hast du wohl auf meinen Knecht Hiob achtgegeben? Denn so wie er ist kein Mensch auf der Erde, so fromm und rechtschaffen, so gottesfürchtig und dem Bösen feind.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 1, 9, 'Der Satan erwiderte dem HERRN: »Ist Hiob etwa umsonst so gottesfürchtig?');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 1, 10, 'Hast du nicht selbst ihn und sein Haus und seinen ganzen Besitz rings umhegt? Was seine Hände angreifen, das segnest du, so daß sein Herdenbesitz sich immer weiter im Lande ausgebreitet hat.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 1, 11, 'Aber strecke doch einmal deine Hand aus und lege sie an alles, was er besitzt: dann wird er sich schon offen von dir lossagen.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 1, 12, 'Da antwortete der HERR dem Satan: »Gut! alles, was ihm gehört, soll in deine Gewalt gegeben sein! Nur an ihn selbst darfst du die Hand nicht legen!« Da ging der Satan vom Angesicht des HERRN hinweg.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 1, 13, 'Während nun eines Tages Hiobs Söhne und Töchter im Hause ihres ältesten Bruders schmausten und Wein tranken,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 1, 14, 'kam plötzlich ein Bote zu Hiob und meldete: »Die Rinder pflügten gerade, und die Eselinnen befanden sich neben ihnen auf der Weide,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 1, 15, 'da machten die Sabäer einen Überfall und trieben sie weg und erschlugen die Knechte mit dem Schwert; ich bin der einzige, der entronnen ist, um es dir zu melden!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 1, 16, 'Während dieser noch redete, kam schon ein anderer und berichtete: »Feuer Gottes ist vom Himmel gefallen und hat das Kleinvieh und die Knechte vollständig verbrannt; ich bin der einzige, der entronnen ist, um es dir zu melden!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 1, 17, 'Während dieser noch redete, kam schon wieder ein anderer und berichtete: »Die Chaldäer sind in drei Heerhaufen, die sie aufgestellt hatten, über die Kamele hergefallen und haben sie weggetrieben; sie haben auch die Knechte mit dem Schwert niedergemacht; ich bin der einzige, der entronnen ist, um es dir zu melden!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 1, 18, 'Dieser hatte noch nicht ausgeredet, da kam wieder ein anderer und berichtete: »Deine Söhne und Töchter waren beim Essen und Weintrinken im Hause ihres ältesten Bruders,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 1, 19, 'da kam plötzlich ein gewaltiger Sturmwind über die Steppe herüber und faßte das Haus an seinen vier Ecken, so daß es auf die jungen Leute stürzte und sie ums Leben kamen; ich bin der einzige, der entronnen ist, um es dir zu melden!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 1, 20, 'Da stand Hiob auf, zerriß sein Gewand und schor sich das Haupt; dann warf er sich auf die Erde nieder, berührte den Boden mit der Stirn,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 1, 21, 'und sagte: »Nackt bin ich aus meiner Mutter Schoß gekommen, und nackt werde ich dorthin zurückkehren; der HERR hat’s gegeben, der HERR hat’s genommen: der Name des HERRN sei gepriesen!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 1, 22, 'Bei allen diesen Heimsuchungen versündigte sich Hiob nicht und tat nichts Ungebührliches vor Gott.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 2, 1, 'Da begab es sich eines Tages, daß die Gottessöhne wiederum kamen, um sich vor Gott den HERRN zu stellen; und unter ihnen erschien auch der Satan, um sich vor den HERRN zu stellen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 2, 2, 'Da fragte der HERR den Satan: »Woher kommst du?« Der Satan gab dem HERRN zur Antwort: »Ich bin auf der Erde umhergestreift und habe eine Wanderung auf ihr vorgenommen.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 2, 3, 'Da sagte der HERR zum Satan: »Hast du auch auf meinen Knecht Hiob achtgegeben? Denn so wie er ist kein Mensch auf der Erde, so fromm und rechtschaffen, so gottesfürchtig und dem Bösen feind; noch immer hält er an seiner Frömmigkeit fest, wiewohl du mich gegen ihn gereizt hast, ihn ohne Grund unglücklich zu machen.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 2, 4, 'Der Satan aber erwiderte dem HERRN: »Haut um Haut! Ja alles, was ein Mensch hat, gibt er für sein Leben hin.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 2, 5, 'Aber strecke nur einmal deine Hand aus und lege sie an sein Gebein und sein Fleisch, so wird er sich sicherlich offen von dir lossagen!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 2, 6, 'Da sagte der HERR zum Satan: »Gut! er soll in deine Gewalt gegeben sein: nur sein Leben sollst du schonen!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 2, 7, 'Da ging der Satan vom HERRN hinweg und schlug Hiob mit bösartigen Geschwüren von der Fußsohle bis zum Scheitel,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 2, 8, 'so daß er sich eine Scherbe nahm, um sich mit ihr zu schaben, während er mitten in der Asche saß.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 2, 9, 'Da sagte seine Frau zu ihm: »Hältst du denn immer noch an deiner Frömmigkeit fest? Sage dich los von Gott und stirb!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 2, 10, 'Er aber antwortete ihr: »Du redest, wie die erste beste Törin reden würde! Das Gute haben wir von Gott hingenommen und sollten das Schlimme nicht auch hinnehmen?« Bei allen diesen Heimsuchungen versündigte sich Hiob nicht mit seinen Lippen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 2, 11, 'Als nun die drei Freunde Hiobs von all diesem Unglück hörten, das ihn betroffen hatte, machten sie sich, ein jeder aus seinem Wohnort, auf den Weg, nämlich Eliphas aus Theman, Bildad aus Suah und Zophar aus Naama, und zwar verabredeten sie sich, miteinander hinzugehen, um ihm ihr Beileid auszudrücken und ihn zu trösten.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 2, 12, 'Als sie nun von ferne ihre Augen aufschlugen, erkannten sie ihn nicht mehr; da fingen sie an, laut zu weinen, zerrissen ein jeder sein Gewand und warfen Staub in die Luft auf ihre Häupter herab.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 2, 13, 'Dann saßen sie bei ihm auf dem Erdboden sieben Tage und sieben Nächte lang, ohne daß einer ein Wort zu ihm redete; denn sie sahen, daß sein Schmerz überaus groß war.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 3, 1, 'Endlich öffnete Hiob den Mund und verfluchte den Tag seiner Geburt,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 3, 2, 'indem er ausrief:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 3, 3, '»Vernichtet sei der Tag, an dem ich geboren wurde, und die Nacht, die da verkündete: ›Ein Mann ist empfangen worden!‹');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 3, 4, 'Jener Tag möge zu Finsternis werden! Nicht kümmere sich um ihn Gott in der Höhe, und kein Tageslicht möge über ihm erglänzen!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 3, 5, 'Nein, Finsternis und Todesschatten mögen ihn als ihr Eigentum zurückfordern, Wolkendunkel sich über ihm lagern, Verdüsterung des Tageslichts ihn schreckensvoll machen!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 3, 6, 'Jene Nacht – sie sei ein Raub des Dunkels! sie werde den Tagen des Jahres nicht beigesellt, in die Zahl der Monate nicht eingereiht!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 3, 7, 'Nein, jene Nacht bleibe unfruchtbar, kein Jubelruf sei ihr je beschieden!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 3, 8, 'Verwünschen mögen sie die Tagbeschwörer, die es verstehen, den Leviathan in Wut zu versetzen!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 3, 9, 'Finster müssen die Sterne ihrer Dämmerung bleiben: sie warte auf Licht, doch es bleibe aus, und niemals erblicke sie die Wimpern des Morgenrots!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 3, 10, 'Denn sie hat mir die Pforte des Mutterschoßes nicht verschlossen und das Unheil vor meinen Augen nicht verborgen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 3, 11, 'Warum bin ich nicht gleich vom Mutterleibe weg gestorben, nicht dem Tode verfallen, als ich aus dem Mutterschoß hervorgekommen war?');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 3, 12, 'Weshalb haben sich mir Knie liebreich dargeboten und wozu Brüste, daß ich an ihnen trinken konnte?');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 3, 13, 'Denn ich würde jetzt im Grabesfrieden liegen, würde schlafen: da hätte ich Ruhe');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 3, 14, 'mit Königen und Volksberatern der Erde, die sich Grabpaläste erbaut haben,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 3, 15, 'oder mit Fürsten, die reich an Gold waren und ihre Häuser mit Silber gefüllt hatten;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 3, 16, 'oder, einer verscharrten Fehlgeburt gleich, wäre ich nicht ins Dasein getreten, den Kindlein gleich, die das Licht nicht erblickt haben.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 3, 17, 'Dort haben die Frevler abgelassen vom Wüten, und dort ruhen die aus, deren Kraft erschöpft ist;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 3, 18, 'dort leben die Gefangenen allesamt in Frieden, hören nicht mehr die Stimme eines Treibers.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 3, 19, 'Niedrige und Hohe gelten dort gleich, und frei ist der Knecht von seinem Herrn.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 3, 20, 'Warum gibt er dem Mühseligen das Licht, und das Leben denen, die verzweifelten Herzens sind?');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 3, 21, 'Die sich nach dem Tode sehnen, ohne daß er kommt, und die nach ihm eifriger graben als nach Schätzen?');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 3, 22, 'Die sich bis zum Jubel freuen, ja aufjauchzen würden, wenn sie das Grab fänden?');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 3, 23, '(Warum gibt er’s nicht) dem Manne, dem sein Weg in Nacht verborgen ist und dem Gott jeden Ausweg versperrt hat?');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 3, 24, 'Denn Seufzen ist für mich das tägliche Brot, und gleich dem Wasser ergießt sich meine laute Klage.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 3, 25, 'Denn bebe ich vor etwas Furchtbarem, so trifft es bei mir ein, und wovor mir graut, das bricht über mich herein:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 3, 26, 'ich darf nicht aufatmen noch rasten noch ruhen, so stellt sich schon wieder eine Qual ein.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 4, 1, 'Da hob Eliphas von Theman an und sagte:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 4, 2, '»Wird es dich verdrießen, wenn man ein Wort an dich zu richten wagt? Doch wer vermöchte die Worte zurückzuhalten?');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 4, 3, 'Hast du doch selbst vielen (Leidenden) Mut zugesprochen und erschlaffte Hände gestärkt;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 4, 4, 'manchen Wankenden haben deine Worte aufrecht gehalten, und niedersinkenden Knien hast du neue Kraft verliehen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 4, 5, 'Nun aber, da die Reihe an dich gekommen, bist du verzagt; nun es dich selbst trifft, verlierst du den Halt!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 4, 6, '»Ist deine Gottesfurcht nicht deine Zuversicht und dein unsträflicher Wandel deine Hoffnung?');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 4, 7, 'Bedenke doch: Wo ist je ein Unschuldiger zugrunde gegangen, und wo sind Rechtschaffene vernichtet worden?');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 4, 8, 'Soweit meine Erfahrung reicht: die Unheil gepflügt und Frevel gesät hatten, die haben es auch geerntet.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 4, 9, 'Durch Gottes Odem kommen sie um, und durch den Hauch seines Zornes vergehen sie.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 4, 10, 'Des Löwen Gebrüll und die Stimme des Leuen (sind verstummt), und den jungen Löwen sind die Zähne ausgebrochen;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 4, 11, 'da kommt auch ein Löwe um aus Mangel an Raub, und die Jungen der Löwin müssen sich zerstreuen.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 4, 12, '»Zu mir ist aber ein Wort verstohlen gedrungen, und mein Ohr hat einen flüsternden Laut davon vernommen');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 4, 13, 'beim Spiel der durch Traumbilder erregten Gedanken, in der Zeit, wo tiefer Schlaf sich auf die Menschen senkt:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 4, 14, 'ein Grauen überfiel mich und ein Zittern, durch alle meine Gebeine ging ein Schauder;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 4, 15, 'ein Lufthauch strich leise an meinem Antlitz vorüber; es sträubte sich mir das Haar am Leibe empor!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 4, 16, 'Da stand – ihr Aussehen konnte ich nicht erkennen – eine Gestalt vor meinen Augen, und eine Stimme hörte ich flüstern:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 4, 17, '›Kann wohl ein Mensch gerecht vor Gott sein oder ein Sterblicher rein vor seinem Schöpfer?');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 4, 18, 'Bedenke: seinen Dienern kann er nicht trauen, und seinen Engeln legt er Mängel zur Last:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 4, 19, 'wieviel mehr denen, die Lehmhütten bewohnen, deren Grundbau im Staube liegt! Sie werden zerdrückt, als wären sie Motten;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 4, 20, 'vom Morgen bis zum Abend werden sie zerschmettert; unbeachtet vergehen sie auf ewig.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 4, 21, 'Nicht wahr, so ist es: wird das Haltseil ihres Zeltes bei ihnen ausgerissen, so sterben sie und wissen nicht wie.‹«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 5, 1, '»Ja, rufe nur! Ist jemand da, der dir Antwort gibt? Und an wen von den heiligen (Engeln) willst du dich wenden?');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 5, 2, 'Vielmehr den Toren bringt sein Unmut um, und den Einfältigen tötet sein Eifern.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 5, 3, 'Ich selbst habe einen Toren zwar Wurzel schlagen sehen, doch gar schnell hatte ich seine Wohnstätte zu verwünschen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 5, 4, 'Seinen Kindern blieb die Hilfe fern, und sie wurden im Tor zertreten, ohne daß ein Retter da war.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 5, 5, 'Seine Ernte verzehrte ein anderer, der danach hungerte und sie sogar hinter dem Dorngehege wegholte; und Durstige schnappten nach seinem Vermögen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 5, 6, 'Denn nicht aus dem Erdenstaube erwächst das Unheil, und das Leid sproßt nicht aus der Ackererde hervor,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 5, 7, 'sondern der Mensch erzeugt das Leid, wie die Kinder der Flamme einen hohen Flug zu nehmen pflegen.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 5, 8, '»Doch ich, an den Höchsten würde ich mich wenden und meine Sache Gott anheimstellen,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 5, 9, 'ihm, der große und unerforschliche Dinge tut, Wunderbares ohne Maß und Zahl –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 5, 10, 'ihm, der Regen über die Erde hin sendet und des Himmels Naß auf die Fluren fallen läßt –,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 5, 11, 'insofern er Niedrige emporhebt und Trauernde sich des höchsten Glücks erfreuen läßt;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 5, 12, 'ihm, der die Pläne der Listigen vereitelt, so daß ihre Hände nichts Erfolgreiches schaffen;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 5, 13, 'ihm, der die Klugen trotz ihrer Schlauheit fängt, so daß die Verschlagenen sich in ihren Anschlägen überstürzen:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 5, 14, 'am hellen Tage stoßen sie auf Finsternis, und am Mittag tappen sie im Dunkel wie bei Nacht.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 5, 15, 'So rettet er den Wehrlosen vor dem Schwert aus ihrem Rachen, und aus des Starken Faust den Geringen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 5, 16, 'So erblüht dem Schwachen neue Hoffnung, die Bosheit aber muß ihren Mund schließen.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 5, 17, '»O wohl dem Menschen, den Gott in Zucht nimmt! Darum verschmähe die Züchtigung des Allmächtigen nicht!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 5, 18, 'Denn er verwundet wohl, doch er verbindet auch; wenn er zerschlägt, so heilen seine Hände auch wieder.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 5, 19, 'In sechs Drangsalen errettet er dich, und in sieben wird kein Unheil dich treffen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 5, 20, 'In Hungersnot bewahrt er dich vor dem Tode und im Kriege vor der Gewalt des Schwertes.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 5, 21, 'Vor den Geißelhieben der Zunge wirst du geborgen sein und brauchst nicht vor der Verheerung zu bangen, daß sie dich erreicht.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 5, 22, 'Der Verwüstung und der Hungersnot darfst du lachen und hast von den wilden Tieren des Landes nichts zu befürchten;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 5, 23, 'denn mit den Steinen des Feldes stehst du im Bunde, und das Getier des Feldes lebt mit dir in Frieden.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 5, 24, 'So wirst du es denn erfahren, daß dein Zelt in Sicherheit ist, und überblickst du dein Gehöft, so wirst du nichts vermissen');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 5, 25, 'und wirst es erleben, daß deine Nachkommenschaft zahlreich ist und dein Nachwuchs gleich dem Gras der Flur.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 5, 26, 'In vollreifem Alter wirst du in die Gruft eingehen, wie der Garbenhaufen eingebracht wird zur rechten Zeit.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 5, 27, 'Siehe, dies ist es, was wir erforscht haben, so ist es: vernimm es und beherzige es zu deinem Heil!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 6, 1, 'Da antwortete Hiob folgendermaßen:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 6, 2, '»Ach, würde doch mein Unmut genau gewogen und legte man mein Unglück zugleich auf die Waage!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 6, 3, 'Denn dann würde es schwerer erfunden werden als der Sand am Meere; darum ist meine Rede irre gegangen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 6, 4, 'Denn die Pfeile des Allmächtigen stecken in mir, deren brennendes Gift mein Geist in sich einsaugt: Gottes Schrecknisse stellen sich in Schlachtordnung gegen mich auf.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 6, 5, 'Schreit etwa ein Wildesel auf grasiger Weide? Oder brüllt ein Rind bei seinem Futterkorn?');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 6, 6, 'Genießt man fade Speisen ohne Salz? Oder ist Wohlgeschmack im Schleim des Eidotters?');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 6, 7, 'Meine Seele sträubt sich dagegen, solche Sachen anzurühren, und ihnen gleicht die Ekelhaftigkeit meiner Speise.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 6, 8, '»O daß doch meine Bitte erfüllt würde und Gott mir meine Hoffnung gewährte!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 6, 9, 'Gefiele es doch Gott, mich zu zermalmen! Streckte er doch seine Hand aus und schnitte meinen Lebensfaden ab!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 6, 10, 'So würde doch das noch ein Trost für mich sein – ja aufhüpfen wollte ich trotz des schonungslosen Schmerzes –, daß ich die Gebote des Heiligen nie verleugnet habe.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 6, 11, 'Wie groß ist denn meine Kraft noch, daß ich ausharren könnte? Und welcher Ausgang wartet meiner, daß ich mich noch gedulden sollte?');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 6, 12, 'Ist meine Kraft etwa hart wie die Kraft der Steine oder mein Leib aus Erz gegossen?');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 6, 13, 'Ach, bin ich nicht ganz und gar hilflos? Und ist mir nicht alles entrissen, worauf ich mich stützen könnte?«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 6, 14, '»Dem Verzweifelnden gebührt Liebe von seinem Nächsten, selbst wenn er die Furcht vor dem Allmächtigen preisgibt.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 6, 15, 'Meine Freunde aber haben sich treulos bewiesen wie ein Wildbach, wie die Rinnsale von Wildbächen, die (in der Regenzeit) überströmen,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 6, 16, 'die trübe vom Eiswasser dahinfließen, wenn der (geschmolzene) Schnee sich in ihnen birgt;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 6, 17, 'doch zur Zeit, wo die Sonnenglut sie trifft, versiegen sie: wenn es heiß wird, sind sie spurlos verschwunden.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 6, 18, 'Da schlängeln sich die Pfade ihres Laufes, verdunsten in die leere Luft und verlieren sich.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 6, 19, 'Die Handelszüge von Thema schauen nach ihnen aus, die Wanderzüge der Sabäer setzen ihre Hoffnung auf sie,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 6, 20, 'werden jedoch in ihrem Vertrauen betrogen: sie kommen hin und sehen sich getäuscht.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 6, 21, 'So seid auch ihr jetzt ein Nichts für mich geworden: ihr seht das Schreckliche und seid fassungslos!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 6, 22, 'Habe ich etwa gebeten: ›Gebt mir etwas und macht mir ein Geschenk von eurem Vermögen;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 6, 23, 'rettet mich aus der Hand meines Bedrängers und kauft mich los aus der Gewalt unbarmherziger Gläubiger‹?«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 6, 24, '»Belehrt mich, so will ich schweigen, und macht mir klar, worin ich mich verfehlt habe!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 6, 25, 'Wie eindringlich sind Worte der Wahrheit! Aber was beweist der Tadel, den ihr aussprecht?');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 6, 26, 'Beabsichtigt ihr, Worte von mir richtigzustellen? Für den Wind sind ja doch die Worte eines Verzweifelnden!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 6, 27, 'Sogar über ein Waisenkind würdet ihr das Los werfen und euren eigenen Freund verschachern!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 6, 28, 'Nun aber – versteht euch doch dazu, mich anzublicken: ich werde euch doch wahrlich nicht ins Angesicht belügen!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 6, 29, 'O kehrt euch her zu mir: tut mir nicht unrecht! Nein, kehrt euch her zu mir; noch steht das Recht in dieser Sache auf meiner Seite!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 6, 30, 'Entsteht denn durch meine Zunge Unrecht? Oder fehlt mir das Vermögen, Unglücksschläge zu unterscheiden?«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 7, 1, '»Hat der Mensch nicht harten Kriegsdienst auf Erden zu leisten, und gleichen seine Lebenstage nicht den Tagen eines Tagelöhners?');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 7, 2, 'Gleich einem Sklaven, der nach Schatten lechzt, und wie ein Tagelöhner, der auf seinen Lohn harrt,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 7, 3, 'so habe auch ich Monate des Elends als Erbteil zugewiesen erhalten, und qualvolle Nächte sind mir zugeteilt worden.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 7, 4, 'Sobald ich mich niedergelegt habe, denke ich: ›Wann werde ich wieder aufstehen?‹ Dann dehnt sich die Nacht endlos aus, und ich werde des Hin- und Herwerfens (über)satt bis zum Morgengrauen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 7, 5, 'Mein Leib hat sich mit Gewürm und erdiger Kruste umkleidet; meine Haut ist zusammengeschrumpft, um eiternd wieder aufzubrechen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 7, 6, 'Meine Tage fliegen schneller dahin als ein Weberschiffchen und entschwinden hoffnungslos.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 7, 7, 'Bedenke, daß mein Leben nur ein Hauch ist! Mein Auge wird das Glück nie wieder zu sehen bekommen!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 7, 8, 'Das Auge dessen, der mich jetzt noch erblickt, wird mich bald nicht mehr schauen: suchen deine Augen nach mir, so bin ich nicht mehr da.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 7, 9, 'Wie eine Wolke sich auflöst und zergeht, so kommt auch, wer ins Totenreich hinabgefahren ist, nicht wieder herauf:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 7, 10, 'nie kehrt er wieder in sein Haus zurück, und seine Wohnstätte weiß nichts mehr von ihm!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 7, 11, '»So will nun auch ich meinem Munde nicht wehren, will in der Angst meines Herzens reden, in der Verzweiflung meiner Seele klagen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 7, 12, 'Bin ich etwa ein Meer oder ein Seeungeheuer, daß du eine Wache gegen mich aufstellst?');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 7, 13, 'Wenn ich denke: ›Trösten wird mich mein Lager, mein Bett wird mir meinen Jammer tragen helfen‹,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 7, 14, 'so ängstigst du mich durch Träume und schreckst mich durch Nachtgesichte auf,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 7, 15, 'so daß ich lieber erwürgt sein möchte, lieber den Tod sähe als dies mein Gerippe.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 7, 16, 'Nun habe ich’s satt, ich mag nicht ewig so leben: laß ab von mir, denn nur noch ein Hauch sind meine Tage.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 7, 17, 'Was ist der Mensch, daß du ihn so groß achtest und überhaupt dein Augenmerk auf ihn richtest?');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 7, 18, 'Daß du alle Morgen nach ihm ausschaust und ihn alle Augenblicke prüfst?');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 7, 19, 'Wann wirst du endlich deine Blicke von mir wegwenden und mir Ruhe gönnen, während ich nur meinen Speichel verschlucke?');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 7, 20, 'Habe ich gesündigt: was habe ich dir damit geschadet, du Menschenbeobachter? Warum hast du mich zur Zielscheibe deiner Angriffe hingestellt, so daß ich mir selbst zur Last bin?');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 7, 21, 'Und warum vergibst du mir meine Sünde nicht und schenkst meiner Schuld nicht Verzeihung? Denn jetzt werde ich mich in den Staub legen, und suchst du dann nach mir, so bin ich nicht mehr da.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 8, 1, 'Da nahm Bildad von Suah das Wort und sagte:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 8, 2, '»Wie lange noch willst du solche Reden führen, und wie lange noch sollen die Worte deines Mundes als Sturmwind daherfahren?');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 8, 3, 'Beugt Gott etwa das Recht, oder verdreht der Allmächtige die Gerechtigkeit?');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 8, 4, 'Nur wenn deine Kinder gegen ihn gesündigt hatten, hat er sie die Folge ihrer Übertretung tragen lassen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 8, 5, 'Wenn du aber Gott ernstlich suchst und zum Allmächtigen flehst,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 8, 6, 'wenn du dabei unsträflich und rechtschaffen bist: ja, dann wird er zu deinem Heil erwachen und deine Wohnung als eine Stätte der Gerechtigkeit wiederherstellen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 8, 7, 'Da wird dann dein vormaliger Glücksstand klein erscheinen gegenüber der Größe deiner nachmaligen Lage.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 8, 8, '»Denn befrage nur das frühere Geschlecht und achte auf das, was ihre Väter erforscht haben!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 8, 9, 'Denn wir sind nur von gestern her und wissen nichts, weil unsere Tage nur ein Schatten auf Erden sind;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 8, 10, 'sie aber werden dich sicherlich belehren, werden dir’s sagen und aus der Tiefe ihrer Einsicht die Worte hervorgehen lassen:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 8, 11, '›Schießt Schilfrohr auf, wo kein Sumpf ist? Wächst Riedgras ohne Wasser auf?');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 8, 12, 'Noch steht es in frischem Triebe, ist noch nicht reif zum Schnitt, da verdorrt es schon vor allem andern Gras.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 8, 13, 'So ergeht es auch allen, die Gott vergessen, und so wird die Hoffnung des Ruchlosen zunichte;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 8, 14, 'denn seine Zuversicht setzt er auf Sommerfäden, und das, worauf er vertraut, ist ein Spinngewebe.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 8, 15, 'Er lehnt sich an sein Haus, doch es hält nicht stand; er klammert sich fest daran, doch es bleibt nicht stehen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 8, 16, 'Er strotzt von Saft auch in der Sonnenglut, und seine Schößlinge breiten sich über seinen Garten aus;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 8, 17, '(sogar) um Steingeröll schlingen sich seine Wurzeln, und in Steingemäuer bohren sie sich hinein;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 8, 18, 'wenn aber er ihn von seiner Stätte wegreißt, so verleugnet diese ihn: Ich habe dich nie gesehen!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 8, 19, 'Siehe, das ist die Freude, die er von seinem Lebenswege hat, und aus dem Boden sprossen wieder andere auf.‹«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 8, 20, '»Nein, Gott verwirft den Frommen nicht und reicht keinem Frevler die Hand.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 8, 21, 'Während er dir den Mund wieder mit Lachen füllen wird und deine Lippen mit lautem Jubel,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 8, 22, 'werden deine Widersacher mit Schande bedeckt dastehen, und das Zelt der Frevler wird verschwunden sein.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 9, 1, 'Darauf antwortete Hiob folgendermaßen:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 9, 2, '»Gewiß, ich weiß, daß es sich so verhält, und wie könnte ein Mensch Gott gegenüber recht behalten?');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 9, 3, 'Wenn es ihn gelüstete, sich mit Gott in einen Rechtsstreit einzulassen, so könnte er ihm auf tausend Fragen keine einzige Antwort geben.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 9, 4, 'Ist einer auch reich an Klugheit und stark an Kraft: wer hat ihm (Gott) je getrotzt und ist heil davongekommen?');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 9, 5, 'Er ist es ja, der Berge versetzt, ohne daß sie es merken, der sie in seinem Zorn umkehrt;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 9, 6, 'er macht die Erde aufbeben von ihrer Stätte, daß ihre Säulen ins Wanken geraten;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 9, 7, 'er gebietet der Sonne, so geht sie nicht auf, und legt die Sterne unter Siegel;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 9, 8, 'er spannt das Himmelszelt aus, er allein, und schreitet hoch auf den Meereswogen einher;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 9, 9, 'er hat das Bärengestirn und den Orion geschaffen, das Siebengestirn und die Kammern des Südens;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 9, 10, 'er vollführt große Dinge, daß sie nicht zu erforschen sind, und Wunderwerke, daß man sie nicht zählen kann.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 9, 11, 'Siehe, er geht an mir vorüber, doch ich sehe ihn nicht; er schwebt dahin, doch ich nehme ihn nicht wahr.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 9, 12, 'Wenn er hinwegrafft – wer will’s ihm wehren? Wer darf zu ihm sagen: ›Was machst du da?‹«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 9, 13, '»Gott läßt von seinem Zorn nicht ab – unter ihn haben sich sogar die Helfer Rahabs beugen müssen –,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 9, 14, 'geschweige denn, daß ich ihm Rede stehen könnte und ihm gegenüber die rechten Worte zu wählen wüßte.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 9, 15, 'Wenn ich auch im Recht wäre, könnte ich ihm doch nicht antworten, sondern müßte ihn als meinen Richter noch anflehen!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 9, 16, 'Selbst wenn ich ihn vor Gericht zöge und er mir Rede stünde, würde ich doch nicht glauben, daß er meinen Aussagen Gehör schenkte;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 9, 17, 'nein, er würde im Sturmesbrausen mich zermalmen und meine Wunden ohne Ursache zahlreich machen;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 9, 18, 'er würde mich nicht zu Atem kommen lassen, sondern mich mit bitteren Leiden sättigen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 9, 19, 'Kommt es auf die Kraft des Starken an, so würde er sagen: ›Hier bin ich!‹, und handelt es sich um ein Rechtsverfahren: ›Wer will mich vorladen?‹');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 9, 20, 'Wäre ich auch im Recht, so müßte doch mein eigener Mund mich verdammen, und wäre ich schuldlos, so würde er mich doch als schuldig erscheinen lassen.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 9, 21, '»Schuldlos bin ich! Mir liegt nichts an meinem Leben; ich achte mein Dasein für nichts!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 9, 22, 'Es kommt auf eins heraus, darum spreche ich es frei aus: Den Unschuldigen vernichtet er wie den Bösewicht.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 9, 23, 'Wenn die Geißel (schwerer Volksplagen) jähen Tod bringt, so lacht er über die Verzweiflung der Unschuldigen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 9, 24, 'Ist ein Land in die Hand eines Frevlers gegeben, so verhüllt er die Augen seiner Richter; wenn er es nicht tut – wer denn sonst?');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 9, 25, 'Und meine Tage eilen schneller dahin als ein Läufer, sind entschwunden, ohne das Glück gesehen zu haben;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 9, 26, 'sie sind dahingeschossen wie Rohrkähne, wie ein Adler, der auf seine Beute stößt.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 9, 27, 'Wenn ich mir vornehme: ›Ich will meinen Jammer vergessen, will mein finsteres Aussehen abtun und heiter blicken!‹,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 9, 28, 'so faßt mich doch immer wieder ein Schauder vor allen meinen Schmerzen; ich weiß ja, daß du (o Gott) mich nicht für schuldlos erklären wirst.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 9, 29, '»Ich muß nun einmal als schuldig gelten: wozu soll ich mich da noch vergebens mühen?');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 9, 30, 'Wenn ich mich auch mit Schnee wüsche und meine Hände mit Lauge reinigte,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 9, 31, 'so würdest du mich doch in die schlammgefüllte Grube eintauchen, so daß meine eigenen Kleider sich vor mir ekelten.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 9, 32, 'Denn Gott ist nicht ein Mann wie ich, daß ich ihm Rede stünde, daß wir zusammen vor Gericht treten könnten;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 9, 33, 'es gibt zwischen uns keinen Schiedsmann, der seine Hand auf uns beide legen könnte.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 9, 34, 'Er nehme seine Rute von mir weg und lasse seinen Schrecken mich nicht mehr ängstigen:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 9, 35, 'so will ich reden, ohne mich vor ihm zu fürchten; denn nicht also bin ich’s mir bewußt (daß ich ihn fürchten müßte).«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 10, 1, '»Mir ekelt vor meinem Leben: so will ich denn meiner Klage über ihn freien Lauf lassen, will reden in der Verzweiflung meiner Seele!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 10, 2, 'Ich will zu Gott sagen: ›Behandle mich nicht als einen Frevler! Laß mich wissen, warum du gegen mich im Streite liegst!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 10, 3, 'Ist es wohlgetan von dir, daß du gewaltsam verfährst, daß du das Gebilde deiner Hände verwirfst, während du zu den Anschlägen der Frevler dein Licht leuchten läßt?');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 10, 4, 'Sind deine Augen von Fleisch, oder siehst du die Dinge so an, wie Menschen sie sehen?');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 10, 5, 'Gleichen deine Tage denen eines Sterblichen, oder sind deine Jahre wie die Lebenstage eines Mannes,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 10, 6, 'daß du nach einer Verschuldung bei mir suchst und nach einer Missetat bei mir forschest,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 10, 7, 'obgleich du weißt, daß es für mich keine Rettung gibt, und daß niemand da ist, der mich aus deiner Hand erretten kann?«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 10, 8, '»Deine Hände haben mich kunstvoll gebildet und sorgsam gestaltet, danach aber hast du dich dazu gewandt, mich zu vernichten.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 10, 9, 'Denke doch daran, daß du mich wie Ton geformt hast; und nun willst du mich wieder zu Staub machen?');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 10, 10, 'Hast du mich nicht einstmals wie Milch hingegossen und wie Molken mich gerinnen lassen?');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 10, 11, 'Mit Haut und Fleisch hast du mich umkleidet und mit Knochen und Sehnen mich durchflochten;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 10, 12, 'Leben und Huld hast du mir gewährt, und deine Obhut hat meinen Odem bewahrt.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 10, 13, 'Doch du hast dabei im geheimen den Gedanken gehegt – ich weiß, daß dies bei dir fest beschlossen gewesen ist –:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 10, 14, 'Sobald ich sündigte, wolltest du es mir gedenken und mich von meiner Verfehlung nicht freisprechen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 10, 15, 'Würde ich mich verschulden, dann wehe mir! Aber auch wenn ich schuldlos bliebe, sollte ich doch mein Haupt nicht erheben, sondern mit Schande gesättigt und mit Elend vollauf getränkt werden;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 10, 16, 'würde mein Haupt sich aber emporrichten: wie ein Löwe wolltest du mich jagen und immer wieder deine Wundermacht an mir erweisen;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 10, 17, 'wolltest immer neue Zeugen gegen mich auftreten lassen und deinen Zorn gegen mich noch steigern, ein immer neues Heer von Leiden gegen mich aufbieten.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 10, 18, '»Aber warum hast du mich aus dem Mutterschoß hervorgehen lassen? Ich hätte verscheiden sollen, noch ehe ein Auge mich sah,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 10, 19, 'hätte werden sollen, als wäre ich nie gewesen, vom Mutterschoß weg sogleich zum Grabe getragen!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 10, 20, 'Sind nicht meine Lebenstage nur noch wenige? So höre doch auf und laß ab von mir, damit ich noch ein wenig heiter blicken kann,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 10, 21, 'bevor ich, ohne zurückzukehren, dahinfahre in das Land der Finsternis und des Todesschattens,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 10, 22, 'in das Land, das düster ist wie tiefe Nacht, in das Land des Todesschattens und des Wustes, wo das Aufleuchten (des Tages) so hell ist wie Finsternis.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 11, 1, 'Da nahm Zophar von Naama das Wort und sagte:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 11, 2, '»Soll (dieser) Wortschwall ohne Antwort bleiben und dieser Zungenheld recht behalten?');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 11, 3, 'Dein Gerede sollte Männer zum Schweigen bringen, und du solltest höhnen dürfen, ohne von jemand widerlegt zu werden?!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 11, 4, 'Du hast ja doch behauptet: ›Meine Darlegung ist richtig‹, und: ›Ich stehe unsträflich in deinen Augen da!‹');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 11, 5, 'Ach, möchte Gott doch reden und seine Lippen gegen dich auftun');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 11, 6, 'und dir die verborgenen Tiefen der Weisheit offenbaren, daß sie allseitig an wahrem Wissen sind! Dann würdest du erkennen, daß Gott dir einen Teil deiner Sündenschuld noch zugute hält.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 11, 7, 'Kannst du den Urgrund der Gottheit erreichen oder bis zur Vollkommenheit des Allmächtigen vordringen?');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 11, 8, 'Himmelhoch ist sie – was kannst du denn erreichen? Tiefer als das Totenreich ist sie – wie weit reicht denn dein Wissen?');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 11, 9, 'Länger als die Erde ist ihr Maß und breiter als das Meer.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 11, 10, 'Wenn er daherfährt und in Verhaft nimmt und zur Gerichtsverhandlung ruft – wer will ihm da wehren?');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 11, 11, 'Denn er kennt die nichtswürdigen Leute und nimmt das Unrecht wahr, ohne besonderer Aufmerksamkeit zu bedürfen.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 11, 12, '»Da muß selbst ein Hohlkopf zu Verstand kommen und ein Wildeselfüllen zum Menschen umgeboren werden.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 11, 13, 'Wenn du nun dein Herz in die rechte Verfassung setzen und deine Hände zu ihm ausbreiten wolltest –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 11, 14, 'klebt eine Schuld an deiner Hand, so entferne sie und laß in deinen Zelten kein Unrecht wohnen! –:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 11, 15, 'ja, dann könntest du dein Angesicht vorwurfsfrei erheben und würdest wie aus Erz gegossen dastehen, frei von aller Furcht;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 11, 16, 'ja, dann würdest du dein Leiden vergessen, würdest daran zurückdenken wie an Wasser, das sich verlaufen hat.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 11, 17, 'Heller als der Mittag würde das Leben dir aufgehen; mag auch einmal Dunkel dich umgeben, wie lichter Morgen würde es werden.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 11, 18, 'Du würdest dich dessen getrösten, daß noch Hoffnung vorhanden sei, und wenn du Umschau hieltest, getrost dich zum Schlafen niederlegen;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 11, 19, 'du würdest dich lagern, ohne von jemand aufgeschreckt zu werden, und viele würden sich um deine Gunst bemühen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 11, 20, 'Dagegen die Augen der Frevler erlöschen: für sie ist jede Möglichkeit zum Entfliehen verloren, und ihre (einzige) Hoffnung ist – die Seele auszuhauchen!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 12, 1, 'Da antwortete Hiob folgendermaßen:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 12, 2, '»Wahrhaftig, ihr seid das Volk, und mit euch wird die Weisheit aussterben!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 12, 3, 'Ich besitze auch Verstand ebensogut wie ihr: ich stehe hinter euch nicht zurück; wem sollten auch derartige Dinge unbekannt sein?');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 12, 4, 'Dem eigenen Freunde muß ich zum Spott dienen, ich, der ich vordem Gott angerufen und auch Erhörung gefunden habe! Zum Spott muß der Gerechte, der Fromme dienen!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 12, 5, 'Dem Unglück gebührt Verachtung nach der Ansicht des sich sicher Fühlenden: ein Stoß noch denen, deren Fuß bereits wankt!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 12, 6, 'In Ruhe liegen die Zelte von Gewalttätigen da, und in Sicherheit leben die, welche Gott Trotz bieten, ein jeder, der seinen Gott in seiner Faust führt.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 12, 7, '»Aber frage doch das Vieh, das wird dich’s lehren, und die Vögel des Himmels, die werden dir’s kundtun;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 12, 8, 'oder betrachte (den Wurm auf der) Erde, er wird dich’s lehren, und die Fische des Meeres werden dir’s bezeugen:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 12, 9, 'wer von diesen allen wüßte nicht, daß die Hand des HERRN diese Welt geschaffen hat,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 12, 10, 'er, in dessen Hand die Seele aller lebenden Geschöpfe liegt und der Odem eines jeden Menschenwesens?');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 12, 11, 'Soll nicht das Ohr die Worte prüfen, gleichwie der Gaumen sich die Speisen kostend auswählt?');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 12, 12, '›Bei den Greisen soll die Weisheit wohnen, und langes Leben Einsicht verleihen?‹');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 12, 13, 'Nein, bei ihm wohnt Weisheit und Stärke, sein ist der Rat und die Einsicht!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 12, 14, '»Siehe, wenn er niederreißt, so wird nicht wieder aufgebaut; wen er einkerkert, dem wird nicht wieder aufgetan.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 12, 15, 'Siehe, wenn er die Wasser hemmt, so versiegen sie, und wenn er sie entfesselt, so wühlen sie die Erde um.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 12, 16, 'Bei ihm ist Kraft und vollkommenes Wissen: ihm fällt der Irrende wie der Irreführende in die Hände.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 12, 17, 'Er läßt Ratsherren als Barfüßige hinwegziehen und erweist Richter als Toren;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 12, 18, 'die Zwingherrschaft von Königen löst er auf und schlingt ihnen einen Strick um die eigenen Hüften;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 12, 19, 'Priester führt er als Barfüßige hinweg und bringt die im Amt Ergrauten zu Fall;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 12, 20, 'erprobten Wortführern entzieht er die Rede und benimmt den Greisen das gesunde Urteil;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 12, 21, 'über Edle gießt er Schande aus und löst den Schwertgurt von Gewalthabern;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 12, 22, 'Tiefverborgenes enthüllt er aus dem Dunkel heraus und zieht finstere Nacht ans Licht hervor;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 12, 23, 'er läßt Völker groß aufwachsen und vernichtet sie wieder; er breitet Völker weit aus und läßt sie dann verschleppen;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 12, 24, 'er raubt den Volkshäuptern des Landes den Verstand und läßt sie umherirren in pfadloser Einöde,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 12, 25, 'daß sie in lichtloser Finsternis tappen, und er läßt sie umherirren wie Trunkene.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 13, 1, '»Seht, dies alles hat mein Auge gesehen, hat mein Ohr gehört und es sich gemerkt.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 13, 2, 'Soviel ihr wißt, weiß ich auch: ich stehe hinter euch nicht zurück.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 13, 3, 'Doch ich will zum Allmächtigen reden und trage Verlangen, mich mit Gott auseinanderzusetzen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 13, 4, 'Ihr dagegen seid nur Lügenschmiede, Pfuscherärzte allesamt.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 13, 5, 'O wolltet ihr doch ganz stille schweigen: das würde euch als Weisheit angerechnet werden.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 13, 6, 'Hört doch meine Rechtfertigung an und achtet auf die Entgegnungen meiner Lippen!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 13, 7, 'Wollt ihr Gott zur Ehre Lügen reden und ihm zuliebe Trug vorbringen?');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 13, 8, 'Wollt ihr Parteilichkeit zu seinen Gunsten üben oder Gottes Sachwalter spielen?');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 13, 9, 'Würde es gut für euch ablaufen, wenn er euch ins Verhör nimmt, oder könnt ihr ihn narren, wie man Menschen narrt?');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 13, 10, 'Mit aller Strenge wird er euch strafen, wenn ihr im geheimen Partei (für ihn) ergreift.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 13, 11, 'Wird nicht sein bloßes Sich-Erheben euch fassungslos machen und Schrecken vor ihm euch befallen?');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 13, 12, 'Eure Denksprüche sind Sprüche so lose wie Asche, eure Schanzen erweisen sich als Schanzen von Lehm!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 13, 13, '»So schweigt denn vor mir still: ich will reden, es mag über mich hereinfahren, was da will!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 13, 14, 'Warum sollte ich mein Fleisch in meinen Zähnen forttragen und meine Seele in meine offene Hand legen?');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 13, 15, 'Er wird mich ja doch töten, ich habe auf nichts mehr zu hoffen; nur meinen bisherigen Wandel will ich offen vor ihm darlegen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 13, 16, 'Schon das muß mir zugute kommen, denn kein Heuchler darf ihm vor die Augen treten.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 13, 17, 'So hört denn meine Rede aufmerksam an und laßt meine Darlegung in euer Ohr dringen!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 13, 18, 'Seht doch: ich bin zum Rechtsstreit gerüstet! Ich weiß, daß ich, ja ich, recht behalten werde.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 13, 19, 'Wer ist es, der mit mir rechten dürfte? Denn in diesem Fall wollte ich lieber verstummen und den Tod erleiden!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 13, 20, 'Nur zweierlei tu mir dabei nicht an (o Gott), dann will ich mich vor deinem Angesicht nicht verbergen:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 13, 21, 'ziehe deine Hand von mir zurück und laß deine schreckliche Erscheinung mich nicht ängstigen!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 13, 22, 'Dann rufe mich, so will ich mich verantworten; oder ich will reden, und du entgegne mir!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 13, 23, '»Wie viele Übertretungen und Missetaten habe ich (begangen)? Meine Übertretung und meine Sünde laß mich wissen!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 13, 24, 'Warum verbirgst du dein Angesicht vor mir und siehst in mir deinen Feind?');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 13, 25, 'Willst du ein verwehtes Blatt noch aufschrecken und einem dürren Strohhalm noch nachjagen,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 13, 26, 'daß du mir so bittere Arzneien verschreibst und mich sogar die Verfehlungen meiner Jugend büßen läßt?');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 13, 27, 'Daß du meine Füße in den Block legst und alle meine Pfade überwachst, meinen Füßen jede freie Bewegung entziehst,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 13, 28, 'mir, einem Manne, der wie ein vom Wurm zerfressenes Gerät zerfällt, wie ein Kleid, das die Motten zernagt haben?«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 14, 1, '»Der Mensch, vom Weibe geboren, ist arm an Lebenszeit, aber überreich an Unruhe:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 14, 2, 'wie eine Blume sprießt er auf und verwelkt, er flieht wie ein Schatten dahin und hat keinen Bestand.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 14, 3, 'Dennoch hältst du über einem solchen (Wesen) deine Augen offen und ziehst ihn vor deinen Richterstuhl!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 14, 4, 'Wie könnte wohl ein Reiner von Unreinen herkommen? nein, nicht ein einziger.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 14, 5, 'Wenn denn seine Tage genau bemessen sind, wenn die Zahl seiner Monde bei dir feststeht und du ihm eine Grenze gesetzt hast, die er nicht überschreiten darf,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 14, 6, 'so wende doch deine Blicke von ihm weg, damit er Ruhe habe, bis er wie ein Tagelöhner mit Befriedigung auf seinen Tag hinblicken kann!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 14, 7, '»Denn für einen Baum bleibt eine Hoffnung bestehen: wird er abgehauen, so schlägt er von neuem aus, und seine Schößlinge hören nicht auf.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 14, 8, 'Wenn auch seine Wurzel in der Erde altert und sein Stumpf im Boden abstirbt,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 14, 9, 'so treibt er doch vom Duft des Wassers neue Sprossen und bringt Zweige hervor wie ein junges Reis.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 14, 10, 'Wenn aber ein Mann stirbt, so liegt er hingestreckt da, und wenn ein Mensch verscheidet, wo ist er dann?');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 14, 11, 'Wie das Wasser aus einem Teich verdunstet und ein Strom versiegt und austrocknet,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 14, 12, 'so legt der Mensch sich nieder und steht nicht wieder auf: bis der Himmel nicht mehr ist, erwachen sie nicht wieder und werden aus ihrem Schlaf nicht aufgerüttelt.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 14, 13, '»O wenn du mich doch im Totenreiche verwahrtest, mich dort verbergen wolltest, bis dein Zorn sich gelegt hätte, mir eine Frist bestimmtest und dann meiner gedächtest!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 14, 14, 'Doch wenn der Mensch gestorben ist – kann er wohl wieder aufleben? Dann wollte ich alle Tage meines Frondienstes harren, bis die Ablösung für mich käme:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 14, 15, 'dann würdest du rufen und ich gäbe dir Antwort; nach dem Werk deiner Hände würdest du Verlangen tragen;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 14, 16, 'ja, dann würdest du meine Schritte sorglich zählen, über einen Fehltritt von mir kein strenger Wächter sein;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 14, 17, 'nein, versiegelt würde meine Übertretung in einem Bündel liegen, und meine Schuld hättest du verklebt.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 14, 18, 'Doch nein – Berge stürzen in sich zusammen, und Felsen werden von ihrer Stelle weggerückt,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 14, 19, 'Steine höhlt das Wasser aus, und seine Güsse schwemmen das Erdreich weg: so machst du auch die Hoffnung des Menschen zunichte.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 14, 20, 'Du überwältigst ihn auf ewig, und er muß davon; sein Antlitz entstellend, läßt du ihn dahinfahren.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 14, 21, 'Gelangen seine Kinder zu Ehren – er weiß nichts davon; und sinken sie in Schande hinab – er achtet nicht auf sie.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 14, 22, 'Nur seines eigenen Leibes Schmerzen fühlt er, und nur um sich selbst empfindet seine Seele Trauer.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 15, 1, 'Da nahm Eliphas von Theman das Wort und sagte:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 15, 2, '»Wird wohl ein Weiser windiges Wissen als Antwort vortragen und seine Lunge mit (bloßem) Ostwind blähen,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 15, 3, 'um sich mit Reden zu verantworten, die nichts taugen, und mit Worten, durch die er nichts nützt?');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 15, 4, 'Dazu vernichtest du die fromme Scheu und tust der Andachtsstille Abbruch, die Gott gebührt;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 15, 5, 'denn dein Schuldbewußtsein macht deinen Mund beredt, und du wählst die Sprache der Verschmitzten.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 15, 6, 'Dein eigener Mund verurteilt dich, nicht ich, und deine eigenen Lippen zeugen gegen dich.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 15, 7, 'Bist du etwa als erster der Menschen geboren und noch vor den Bergen auf die Welt gekommen?');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 15, 8, 'Hast du im Rate Gottes als Zuhörer gelauscht und dort die Weisheit an dich gerissen?');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 15, 9, 'Was weißt du denn, das wir nicht auch wüßten? was verstehst du, das uns nicht auch bekannt wäre?');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 15, 10, 'Auch unter uns sind Ergraute, sind Weißköpfe, reicher noch als dein Vater an Lebenstagen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 15, 11, 'Sind dir die Tröstungen Gottes minderwertig, und gilt ein Wort der Sanftmut nichts bei dir?');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 15, 12, 'Was reißt deine Leidenschaft dich fort, und was rollen deine Augen,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 15, 13, 'daß du gegen Gott deine Wut richtest und (solche) Reden deinem Munde entfahren läßt?');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 15, 14, 'Was ist der Mensch, daß er rein sein könnte, und der vom Weibe Geborene, daß er als gerecht dastände?');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 15, 15, 'Bedenke doch: selbst seinen heiligen (Engeln) traut er nicht, und nicht einmal der Himmel ist rein in seinen Augen:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 15, 16, 'geschweige denn der Abscheuliche und Entartete, der Mensch, dem Unrechttun wie Wassertrinken ist!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 15, 17, '»Ich will dich unterweisen: höre mir zu; und was ich gesehen habe, will ich berichten,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 15, 18, 'was die Weisen von ihren Vätern überkommen und ohne Hehl verkündigt haben –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 15, 19, 'ihnen war noch allein das Land übergeben, und noch kein Fremder war unter ihnen umhergezogen –:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 15, 20, '›Sein ganzes Leben lang muß der Frevler sich ängstigen, und zwar alle die Jahre hindurch, die dem Gewalttätigen beschieden sind.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 15, 21, 'Schreckensrufe dringen ihm laut ins Ohr; mitten im ruhigen Glück überfällt ihn der Verderber;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 15, 22, 'er hegt keine Zuversicht, aus der Finsternis wieder herauszukommen, und ist (in seiner Angst) für das Schwert ausersehen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 15, 23, 'Er irrt nach Brot umher – wo findet er’s? Er weiß, daß durch ihn der Tag des Verderbens festgesetzt ist.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 15, 24, 'Angst und Bangigkeit schrecken ihn: sie überwältigen ihn wie ein König, der zum Sturm gerüstet ist.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 15, 25, 'Weil er seine Hand gegen Gott erhoben und dem Allmächtigen Trotz geboten hat –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 15, 26, 'er stürmte gegen ihn an mit emporgerecktem Halse, mit den dichten Buckeln seiner Schilde –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 15, 27, 'weil er sein Gesicht von Fett hatte strotzen lassen und Schmer an seinen Lenden angesetzt');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 15, 28, 'und sich in gebannten Städten angesiedelt hatte, in Häusern, die unbewohnt bleiben sollten, die zu Trümmerhaufen bestimmt waren:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 15, 29, 'so bringt er’s nicht zu Reichtum, und sein Wohlstand hat keinen Bestand, und seine Sichel neigt sich nicht zur Erde.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 15, 30, 'Er kommt nicht aus der Finsternis heraus; seine Schößlinge versengt die Gluthitze, und er selbst vergeht durch den Zornhauch des Mundes Gottes.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 15, 31, 'Er verlasse sich nicht auf Trug: er täuscht sich nur; denn Trug wird auch das sein, was er durch seinen eigenen (Trug) erzielt:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 15, 32, 'ehe noch seine Zeit da ist, erfüllt sich sein Geschick, während sein Wipfel noch nicht gegrünt hat.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 15, 33, 'Wie der Weinstock stößt er seine Beeren unreif ab und läßt wie der Ölbaum seine Blüten abfallen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 15, 34, 'Denn die Rotte des Frevlers bleibt ohne Frucht, und Feuer verzehrt die Zelte der Bestechung.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 15, 35, 'Mit Unheil gehen sie schwanger und gebären Frevel, und ihr Inneres bringt nur Selbsttäuschung zutage.‹«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 16, 1, 'Darauf antwortete Hiob folgendermaßen:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 16, 2, '»Dergleichen habe ich nun schon vieles gehört: leidige Tröster seid ihr allesamt!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 16, 3, 'Haben die windigen Reden nun ein Ende? Oder was drängt dich dazu, mir noch weiter zu erwidern?');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 16, 4, 'Auch ich könnte reden wie ihr – o wärt ihr nur an meiner Stelle! –, ich würde (aber) freundliche Worte gegen euch aufbringen und beifällig mit dem Kopfe euch zunicken;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 16, 5, 'ich wollte euch mit meinem Munde Mut zusprechen, und das Beileid meiner Lippen sollte euch Trost bringen!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 16, 6, '»Wenn ich rede, wird mein Schmerz nicht gelindert, und wenn ich’s unterlasse – um was werde ich erleichtert?');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 16, 7, 'Doch nunmehr hat er meine Kraft erschöpft! Verwüstet hast du meinen ganzen Hausstand');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 16, 8, 'und hast mich gepackt; das muß als Zeugnis gegen mich gelten, und mein Siechtum tritt gegen mich auf, klagt mich ins Angesicht an.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 16, 9, 'Sein Zorn hat mich zerfleischt und befeindet; er hat mit den Zähnen gegen mich geknirscht; als mein Gegner wirft er mir durchbohrende Blicke zu.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 16, 10, 'Ihr Maul haben sie gegen mich aufgerissen, unter Schmähung mir Faustschläge ins Gesicht versetzt; zusammen hat man sich vollzählig gegen mich aufgestellt.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 16, 11, 'Gott hat mich Bösewichten preisgegeben und mich in die Hände von Frevlern fallen lassen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 16, 12, 'In Frieden lebte ich, da schreckte er mich auf, faßte mich beim Genick und schmetterte mich nieder und ließ mich nur wieder aufstehen, damit ich ihm als Zielscheibe diente:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 16, 13, 'seine Pfeile umschwirren mich, er durchbohrt mir die Nieren erbarmungslos, läßt mein Herzblut zur Erde fließen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 16, 14, 'Er schlägt mir Wunde auf Wunde, stürmt gegen mich an wie ein wilder Krieger.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 16, 15, 'Das Trauergewand habe ich mir um den krustigen Leib geheftet und mein Horn tief in den Staub hineingebohrt.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 16, 16, 'Mein Gesicht ist vom Weinen hochgerötet, und auf meinen Augenlidern lagert Todesschatten,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 16, 17, 'obwohl keine Schuld an meinen Händen klebt und mein Gebet aufrichtig ist.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 16, 18, '»O Erde, decke mein Blut nicht zu, und mein Wehgeschrei finde keine Ruhestatt!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 16, 19, 'Schon jetzt – wisset es wohl! – ist ein Zeuge für mich im Himmel vorhanden und mein Bürge in der Höhe.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 16, 20, 'Meine Freunde verhöhnen mich – zu Gott blickt mein Auge tränenvoll empor,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 16, 21, 'daß er dem Manne Recht schaffe Gott gegenüber und zwischen dem Menschen und seinem Freunde entscheide.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 16, 22, 'Denn nur noch wenige Jahre werden kommen, dann werde ich den Pfad wandeln, auf dem es keine Rückkehr für mich gibt.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 17, 1, 'Meine Lebenskraft ist gebrochen, meine Tage sind erloschen; nur die Gräberstätte wartet meiner noch!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 17, 2, '»Wahrlich, der Spott treibt sein Spiel mit mir, und mein Auge muß auf ihren Beleidigungen weilen!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 17, 3, 'O setze doch das Pfand ein, verbürge dich doch für mich bei dir selbst! Wer sollte sonst als Bürge mir den Handschlag leisten?');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 17, 4, 'Denn ihr Herz hast du der Einsicht verschlossen; darum kannst du sie auch nicht obsiegen lassen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 17, 5, 'Wenn jemand seine Freunde verrät, um etwas von ihrem Besitz an sich zu bringen, so werden die Augen seiner Kinder dafür verschmachten.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 17, 6, 'Und mich hat er für alle Welt zum Gespött gemacht, und ich muß mir ins Angesicht speien lassen;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 17, 7, 'da ist mein Auge vor Gram erloschen, und alle meine Glieder sind nur noch wie ein Schatten.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 17, 8, 'Darüber entsetzen sich die Rechtschaffenen, und der Unschuldige gerät in Empörung über den Ruchlosen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 17, 9, 'Doch der Gerechte soll an seinem Wege festhalten, und wer reine Hände hat, soll an Kraft noch zunehmen.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 17, 10, '»Ihr alle aber, kommt immerhin aufs neue heran: ich werde doch keinen Weisen unter euch finden.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 17, 11, 'Meine Tage sind abgelaufen, meine Pläne vereitelt, die Bestrebungen meines Herzens!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 17, 12, 'Die Nacht wollen sie zum Tage machen: das Licht soll mir näher sein als die Finsternis!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 17, 13, 'Wenn ich schon das Totenreich als meine Behausung erwarte, in der Finsternis mir mein Lager schon ausgebreitet habe,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 17, 14, 'wenn ich dem Grabe bereits zugerufen habe: ›Mein Vater bist du!‹ und dem Gewürm: ›Meine Mutter und meine Schwester!‹ –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 17, 15, 'wo ist da noch eine Hoffnung für mich? Ja, eine Hoffnung für mich – wer mag sie erschauen?');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 17, 16, 'Zu den Riegeln des Totenreichs fährt sie (die Hoffnung) hinab, wenn zugleich (für den Leib) im Staube Ruhe sein wird.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 18, 1, 'Da nahm Bildad von Suah das Wort und sagte:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 18, 2, '»Wie lange wollt ihr noch Jagd auf (bloße) Worte machen? Nehmt Verstand an: dann wollen wir reden!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 18, 3, 'Warum werden wir den vernunftlosen Tieren gleichgeachtet, von euch als vernagelt angesehen?');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 18, 4, 'Du, der in seinem Zorn sich selbst zerfleischt – soll um deinetwillen die Erde menschenleer werden und der Fels von seiner Stelle wegrücken?«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 18, 5, '»Jawohl, das Licht des Frevlers wird erlöschen und die Flamme seines Herdfeuers nicht mehr leuchten;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 18, 6, 'das Licht wird dunkel werden in seinem Zelt, und seine Leuchte erlischt über ihm;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 18, 7, 'seine sonst so rüstigen Schritte werden kurz, und seine eigenen Anschläge bringen ihn zu Fall;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 18, 8, 'denn er wird von seinen eigenen Füßen ins Netz getrieben, und auf Fallgittern wandelt er dahin.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 18, 9, 'Die Schlinge erfaßt seine Ferse, der Fallstrick hält ihn fest;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 18, 10, 'am Boden liegt das Fanggarn für ihn verborgen, und die Falle wartet seiner auf dem Pfade.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 18, 11, 'Ringsum ängstigen ihn Schrecknisse und hetzen ihn auf Schritt und Tritt.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 18, 12, 'Das ihm bestimmte Unheil hungert nach ihm, und das Verderben steht zu seinem Sturz bereit.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 18, 13, 'Es frißt die Glieder seines Leibes, es frißt seine Glieder der erstgeborene Sohn des Todes.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 18, 14, 'Herausgerissen wird er aus seinem Zelt, wo er sich sicher fühlte, und es treibt ihn hin zum König der Schrecken.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 18, 15, 'In seinem Zelt haust eine Bewohnerschaft, die nicht zu ihm gehört; Schwefel wird auf seine Wohnstätte gestreut.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 18, 16, 'Unten verdorren seine Wurzeln, und oben verwelken seine Zweige.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 18, 17, 'Das Andenken an ihn verschwindet von der Erde, und kein Name verbleibt ihm draußen weit und breit;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 18, 18, 'er stößt ihn aus dem Licht in die Finsternis hinaus und verjagt ihn vom Erdenrund.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 18, 19, 'Nicht Sproß noch Schoß bleibt ihm in seinem Volk erhalten, und kein Überlebender findet sich in seinen Wohnsitzen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 18, 20, 'Ob seinem Gerichtstage schaudern die im Westen Wohnenden, und die Leute im Osten erfaßt Entsetzen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 18, 21, 'Ja, so ergeht es den Wohnungen des Frevlers und so der Stätte des Gottesverächters!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 19, 1, 'Da antwortete Hiob folgendermaßen:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 19, 2, '»Wie lange wollt ihr mein Herz noch betrüben und mich mit Reden martern?');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 19, 3, 'Schon zehnmal habt ihr mich geschmäht; ihr schämt euch nicht, mir wehzutun!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 19, 4, 'Und hätte ich mich wirklich verfehlt, so wäre doch meine Verfehlung meine eigene Sache.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 19, 5, 'Wollt ihr wirklich gegen mich großtun, so erbringt mir den Beweis für das mich Beschämende!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 19, 6, 'Erkennt doch, daß Gott mir unrecht getan und mich mit seinem Fangnetz rings umgarnt hat!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 19, 7, '»Seht: schreie ich über Gewalttat, so finde ich keine Erhörung; rufe ich um Hilfe, so gibt es keinen Rechtsspruch.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 19, 8, 'Den Weg hat er mir vermauert, so daß ich nicht weiterschreiten kann, und über meine Pfade hat er Finsternis ausgebreitet.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 19, 9, 'Meiner Ehre hat er mich entkleidet und die Krone mir vom Haupte weggenommen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 19, 10, 'Er hat mich niedergerissen um und um, so daß es aus mit mir ist, und hat meine Hoffnung ausgerissen wie einen Baum.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 19, 11, 'Er hat seinen Zorn gegen mich lodern lassen und mich seinen Feinden gleichgeachtet.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 19, 12, 'Allzumal sind seine Kriegerscharen herangerückt, haben sich einen Weg zum Angriff gegen mich aufgeschüttet und sich rings um mein Zelt her gelagert.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 19, 13, 'Meine Brüder haben sich fern von mir gehalten, und meine Bekannten sind mir ganz entfremdet;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 19, 14, 'meine Verwandten bleiben weg, und meine vertrauten Freunde haben mich vergessen;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 19, 15, 'meine Hausgenossen und selbst meine Mägde sehen in mir einen Fremden: ein Unbekannter bin ich in ihren Augen geworden.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 19, 16, 'Rufe ich meinen Knecht, so antwortet er mir nicht: ich muß ihn anflehen und ihm gute Worte geben.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 19, 17, 'Mein Atem ist meinem Weibe zuwider und mein übler Geruch meinen leiblichen Brüdern.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 19, 18, 'Selbst die Buben mißachten mich: mache ich (vergebliche) Versuche zum Aufstehen, so verspotten sie mich.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 19, 19, 'Allen meinen Vertrauten ekelt vor mir, und die ich liebgehabt habe, stehen mir feindlich gegenüber.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 19, 20, 'An meiner Haut und meinem Fleisch kleben meine Knochen, und von meinen Zähnen habe ich nur die Haut übrigbehalten.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 19, 21, '»Habt Mitleid, habt Mitleid mit mir, ihr meine Freunde! Denn Gottes Hand hat mich schwer getroffen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 19, 22, 'Warum verfolgt ihr mich ebenso wie Gott und werdet nicht satt, mich zu zerfleischen?');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 19, 23, 'O daß doch meine Worte aufgeschrieben, o daß sie in ein Buch eingetragen würden,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 19, 24, 'mit eisernem Griffel in Blei eingegraben, auf ewig in den Felsen eingehauen würden!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 19, 25, 'Ich aber, ich weiß, daß mein Löser lebt und als letzter auf dem Staube auftreten wird;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 19, 26, 'und danach werde ich, mag jetzt auch meine Haut so ganz zerfetzt und ich meines Fleisches ledig sein, Gott schauen,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 19, 27, 'den ich schauen werde mir zum Heil und den meine Augen sehen werden, und zwar nicht mehr als einen Entfremdeten, ihn, um den sich mir das Herz in der Brust abgehärmt hat.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 19, 28, 'Wenn ihr aber sagt: ›Wie wollen wir ihn verfolgen!‹ und ›der letzte Grund der Sache sei in mir selbst zu finden‹,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 19, 29, 'so fürchtet euch vor dem Schwert – denn derartige Verschuldungen verdienen die Strafe des Schwertes –, damit ihr erkennt, daß es noch ein Gericht gibt!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 20, 1, 'Nun nahm Zophar von Naama das Wort und sagte:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 20, 2, '»Eben darum veranlassen meine Gedanken mich zu einer Antwort, und eben deswegen bin ich innerlich erregt:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 20, 3, 'eine mich beschimpfende Zurechtweisung muß ich hören! Doch der Geist gibt mir eine Antwort aus meiner Einsicht ein.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 20, 4, '»Kennst du nicht die Wahrheit von alters her, seitdem der Mensch seinen Wohnsitz auf der Erde hat,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 20, 5, 'daß das Frohlocken der Frevler von kurzer Dauer ist und die Freude der Ruchlosen nur einen Augenblick währt?');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 20, 6, 'Sollte auch sein Dünkel sich bis zum Himmel erheben und sein Haupt bis an die Wolken reichen,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 20, 7, 'so vergeht er doch wie sein Unrat für immer, und die ihn gekannt haben, werden fragen: ›Wo ist er geblieben?‹');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 20, 8, 'Wie ein Traum verfliegt er, so daß man ihn nicht mehr findet, und er wird hinweggescheucht wie ein Nachtgesicht:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 20, 9, 'das Auge, das ihn gesehen, erblickt ihn nimmer wieder, und seine Stätte gewahrt ihn nicht mehr.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 20, 10, 'Seine Söhne müssen die (durch ihn) Verarmten mit Bitten beschwichtigen und seine eigenen Hände sein Vermögen wieder herausgeben.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 20, 11, 'Mögen auch seine Glieder von Jugendkraft strotzen: sie muß sich doch mit ihm in den Staub legen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 20, 12, 'Mag das Böse auch seinem Munde süß schmecken, so daß er es lange unter seiner Zunge birgt,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 20, 13, 'daß er es schonend hegt und es nicht fahren lassen will, sondern es an seinem Gaumen zurückhält,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 20, 14, 'so verwandelt sich doch seine Speise in seinen Eingeweiden: zu Otterngalle wird sie in seinem Leibe.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 20, 15, 'Den Reichtum, den er verschlungen hat, muß er wieder ausspeien: aus seinem Bauche treibt Gott ihn wieder heraus.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 20, 16, 'Otterngift hat er eingesogen: nun gibt ihm die Zunge der Viper den Tod.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 20, 17, 'Nicht darf er seine Lust mehr sehen an den Bächen, an den wogenden Strömen von Honig und Sahne.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 20, 18, 'Das Erraffte muß er wieder herausgeben, ohne es verschlucken zu können; wieviel Gut er auch erworben hat, er darf nicht frohlocken.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 20, 19, 'Denn er hat die Armen niedergeschlagen und hilflos verkommen lassen, hat Häuser an sich gerissen, wird sie aber nicht häuslich einrichten dürfen;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 20, 20, 'denn er kannte keine Befriedigung in seiner Gier: darum wird er auch von seinen Kostbarkeiten nichts davonbringen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 20, 21, 'Nichts entging seinem Fressen: darum hat sein Wohlstand keine Dauer.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 20, 22, 'In der Fülle seines Überflusses wird ihm enge: die ganze Gewalt des Unheils kommt über ihn.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 20, 23, 'Da entfesselt Gott dann, um ihm den Bauch zu füllen, seine Zornesglut gegen ihn und läßt sie als seine Speise auf ihn regnen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 20, 24, 'Flieht er vor der eisernen Rüstung, so durchbohrt ihn der eherne Bogen;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 20, 25, 'er zieht den Pfeil heraus, da fährt’s aus seinem Rücken hervor: ein Blutstrahl schießt aus seiner Galle, Todesschrecken brechen über ihn herein.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 20, 26, 'Alles Unheil ist seinen Schätzen aufgespart: ein Feuer, das nicht (von Menschen) angefacht ist, frißt sie und verzehrt, was in seinem Zelt noch übriggeblieben ist.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 20, 27, 'Der Himmel deckt Sündenschuld auf, und die Erde erhebt sich gegen ihn.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 20, 28, 'Was in seinem Hause zusammengescharrt liegt, wird weggeschleppt, zerrinnt (wie Wasser) am Tage des göttlichen Zorngerichts.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 20, 29, 'Das ist des ruchlosen Menschen Teil von seiten Gottes und das vom Allherrn ihm zugesprochene Erbe.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 21, 1, 'Darauf antwortete Hiob folgendermaßen:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 21, 2, '»Hört, o höret an, was ich zu sagen habe! Das soll mir eure Tröstungen ersetzen!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 21, 3, 'Erlaubt mir, daß ich rede, und nachdem ich gesprochen habe, magst du es bespötteln!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 21, 4, 'Richtet sich meine Klage etwa gegen Menschen? Oder warum sollte ich nicht ungeduldig werden?');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 21, 5, 'Wendet euch her zu mir, so werdet ihr euch entsetzen und euch die Hand auf den Mund legen!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 21, 6, 'Wenn ich bloß daran denke, gerate ich in Bestürzung, und ein Schauder überläuft meinen Leib!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 21, 7, '»Warum bleiben die Frevler am Leben, werden alt, nehmen sogar an Kraft zu?');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 21, 8, 'Ihr Nachwuchs steht bei fester Gesundheit vor ihnen, ja neben ihnen, und deren Sprößlinge vor ihren Augen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 21, 9, 'Ihre Häuser stehen ungefährdet da, ohne Furcht vor Schrecknis, und Gottes Zuchtrute fährt nicht auf sie nieder.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 21, 10, 'Sein Stier belegt und befruchtet sicher, seine Kuh kalbt leicht und tut keine Fehlgeburt.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 21, 11, 'Ihre Buben lassen sie wie eine Herde Lämmer ausziehen, und ihre kleineren Kinder hüpfen tanzend umher;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 21, 12, 'sie singen laut zur Pauke und Zither und sind vergnügt beim Klang der Schalmei.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 21, 13, 'Sie verbringen im Wohlergehen ihre Tage und fahren in Ruhe zum Totenreich hinab.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 21, 14, 'Und doch haben sie zu Gott gesagt: ›Bleibe fern von uns; denn nach der Erkenntnis deiner Wege tragen wir kein Verlangen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 21, 15, 'Was ist der Allmächtige, daß wir ihm dienen sollten? Und könnte es uns nützen, daß wir ihn mit Bitten angehen?‹«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 21, 16, '»Seht, ihr Wohlergehen liegt allerdings nicht in ihrer Hand – die Denkweise der Frevler steht mir fern! –,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 21, 17, 'aber wie oft kommt es denn vor, daß die Leuchte der Frevler erlischt und ihr Verderben über sie hereinbricht? Daß Gott ihnen die Lose gemäß seinem Zorn zuteilt?');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 21, 18, 'Daß es ihnen ergeht wie dem Strohhalm vor dem Wind und wie der Spreu, die der Sturm entführt hat?');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 21, 19, '›Gott spart‹, sagt ihr, ›sein Unheil für die Kinder des Frevlers auf‹ – doch ihm selber sollte er vergelten, daß er es fühlte!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 21, 20, 'Sehen müßten seine eigenen Augen das Verderben, und er selbst sollte von der Zornglut des Allmächtigen trinken!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 21, 21, 'Denn was wird er sich noch um seine Familie nach seinem Tode kümmern, nachdem die Zahl seiner Monde abgeschnitten ist?');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 21, 22, 'Doch – darf man Gott Erkenntnis lehren, ihn, der die himmlischen (Geister) richtet?');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 21, 23, 'Der eine stirbt im Vollbesitz des Glücks, ganz sorgenfrei und in Ruhe:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 21, 24, 'seine Kufen sind mit Milch gefüllt, und so ist das Mark in seinen Knochen wohlversorgt;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 21, 25, 'der andere aber stirbt in bitterem Herzeleid, ohne je vom Glück etwas geschmeckt zu haben:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 21, 26, 'gleicherweise liegen sie in der Erde, und Gewürm legt sich als Decke über beide.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 21, 27, '»Seht, ich kenne eure Gedanken wohl und die Anschläge, mit denen ihr mir Gewalt antut.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 21, 28, 'Wenn ihr sagt: ›Wo ist das Haus des Gewaltmenschen geblieben und wo das Zelt, in welchem die Frevler wohnten?‹ –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 21, 29, 'habt ihr euch denn noch nie bei den weitgereisten Leuten erkundigt, deren beweiskräftige Aussagen ihr doch nicht verwerfen könnt:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 21, 30, 'daß am Unglückstage der Böse verschont bleibt und am Tage des (göttlichen) Zorngerichts heil davonkommt?');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 21, 31, 'Wer hält ihm auch nur seinen Lebenswandel unverhohlen vor? Und hat er etwas verübt, wer vergilt es ihm?');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 21, 32, 'Nein, man gibt ihm noch das feierliche Geleit zur Gräberstätte und hält über seinem Grabhügel noch Wache.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 21, 33, 'Sanft liegen auf ihm die Schollen des Tales, und hinter ihm her zieht alle Welt, wie Unzählige ihm vorangegangen sind.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 21, 34, 'Wie mögt ihr mir da so nichtigen Trost bieten? Und eure Entgegnungen – von denen bleibt nur Treubruch übrig!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 22, 1, 'Da nahm Eliphas von Theman das Wort und sagte:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 22, 2, '»Kann wohl ein Mensch Gott Nutzen schaffen? Nein, nur sich selbst nützt der Fromme.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 22, 3, 'Hat der Allmächtige Vorteil davon, wenn du rechtschaffen bist? Oder bringt es ihm Gewinn, wenn du unsträflich wandelst?');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 22, 4, 'Meinst du, wegen deiner Gottesfurcht strafe er dich und gehe deshalb mit dir ins Gericht?');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 22, 5, 'Ist nicht vielmehr deine Bosheit groß, und sind nicht deine Verschuldungen ohne Ende?«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 22, 6, '»Denn oftmals hast du deine Volksgenossen ohne Grund gepfändet und den Halbnackten ihre Kleider ausziehen lassen;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 22, 7, 'dem vor Durst Lechzenden hast du keinen Trunk Wasser gereicht und dem Hungrigen ein Stück Brot versagt.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 22, 8, 'Dem Manne der Faust – ihm gehörte das Land, und nur die Hochangesehenen durften darin wohnen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 22, 9, 'Witwen ließest du mit leeren Händen gehen, und alles, was den Waisen zu Gebote stand, wurde zugrunde gerichtet.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 22, 10, 'Darum bist du jetzt rings von Schlingen umgeben, und jäher Schrecken versetzt dich in Angst;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 22, 11, 'dein Licht ist Finsternis geworden, so daß du nicht sehen kannst, und eine Wasserflut bedeckt dich.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 22, 12, '»Ist Gott nicht so hoch wie der Himmel? Und schaue den Gipfel der Sterne an, wie hoch sie ragen!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 22, 13, 'Und da sagst du: ›Was weiß denn Gott? Kann er durch Wolkendunkel hindurch Gericht halten?');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 22, 14, 'Dichte Wolken sind ihm eine Hülle, so daß er nichts sehen kann, und nur die Räume des Himmelsgewölbes durchwandelt er.‹');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 22, 15, 'Willst du die Bahn der Vorwelt innehalten, auf der die Männer des Frevels einst gewandelt sind?');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 22, 16, 'Sie, die vor der Zeit weggerafft wurden – der feste Boden unter ihnen zerfloß zu einem Strom –;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 22, 17, 'die zu Gott sagten: ›Bleibe fern von uns!‹ und ›was der Allmächtige ihnen antun könne?‹');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 22, 18, 'Und doch hatte er ihre Häuser mit Segen gefüllt. Aber die Denkweise der Frevler bleibe fern von mir!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 22, 19, 'Die Gerechten sehen es und freuen sich, und der Schuldlose ruft ihnen spottend zu:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 22, 20, '›Fürwahr, unsere Widersacher sind vernichtet, und ihre Hinterlassenschaft hat das Feuer verzehrt!‹«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 22, 21, '»Befreunde dich doch mit Gott und halte Frieden mit ihm! Dadurch wird dein Geschick sich heilsam gestalten.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 22, 22, 'Nimm doch Belehrung aus seinem Munde an und laß seine Worte in deinem Herzen wohnen!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 22, 23, 'Wenn du dich zum Allmächtigen bekehrst, so wirst du wieder aufgebaut werden; wenn du die Sünde aus deinen Zelten entfernst –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 22, 24, 'ja, wirf das Golderz von dir in den Staub und Ophirs Gold unter die Kiesel der Bäche,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 22, 25, 'daß der Allmächtige dein Golderz ist und Silber dir sein Gesetz –:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 22, 26, 'ja, dann wirst du dich auf den Allmächtigen getrost verlassen und zu Gott dein Angesicht vertrauensvoll erheben.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 22, 27, 'Flehst du zu ihm, so wird er dich erhören, und deine Gelübde wirst du bezahlen können;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 22, 28, 'nimmst du dir etwas vor, so wird es dir gelingen, und Licht wird über deinen Wegen strahlen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 22, 29, 'Wenn sie abwärts führen, so rufst du: ›Empor!‹, und dem Niedergeschlagenen hilft er auf.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 22, 30, 'Selbst den Nichtschuldlosen wird er entkommen lassen, und zwar wird er durch die Reinheit deiner Hände entkommen.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 23, 1, 'Da antwortete Hiob folgendermaßen:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 23, 2, '»Auch jetzt noch gilt meine Klage euch als Trotz: schwer lastet seine Hand auf meinem Seufzen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 23, 3, 'O daß ich ihn zu finden wüßte, daß ich gelangen könnte bis zu seiner Wohnstätte!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 23, 4, 'Ich wollte meine Sache vor ihm darlegen und meinen Mund mit Beweisgründen füllen;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 23, 5, 'ich erführe dann, was er mir entgegnete, und würde vernehmen, was er mir zu sagen hat.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 23, 6, 'Würde er dann wohl mit der ganzen Fülle seiner Macht mit mir streiten? Nein, nur seine Aufmerksamkeit würde er mir zuwenden.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 23, 7, 'Da würde sich dann ein Rechtschaffener vor ihm verantworten, und für immer würde ich von meinem Richter freikommen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 23, 8, 'Doch ach! Gehe ich nach Osten, so ist er nicht da, und gehe ich nach Westen, so gewahre ich ihn nicht;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 23, 9, 'wirkt er im Norden, so erblicke ich ihn nicht, biegt er nach Süden ab, so sehe ich ihn nicht.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 23, 10, 'Er kennt ja doch den von mir eingehaltenen Weg, und prüfte er mich – wie Gold aus der Schmelze würde ich hervorgehen!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 23, 11, 'Denn an seine Spur hat mein Fuß sich angeschlossen; den von ihm gewiesenen Weg habe ich eingehalten, ohne davon abzuweichen;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 23, 12, 'von dem Gebot seiner Lippen bin ich nicht abgegangen: in meinem Busen habe ich die Weisungen seines Mundes geborgen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 23, 13, 'Doch er bleibt sich immer gleich – wer kann ihm wehren? und was sein Sinn einmal will, das führt er auch aus.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 23, 14, 'So wird er denn auch vollführen, was er mir bestimmt hat, und dergleichen hat er noch vieles im Sinn.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 23, 15, 'Darum bebe ich vor seinem Anblick: überdenke ich’s, so graut mir vor ihm!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 23, 16, 'Ja, Gott hat mein Herz verzagt gemacht und der Allmächtige mich mit Angst erfüllt;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 23, 17, 'denn nicht wegen Finsternis fühle ich mich vernichtet und nicht wegen meiner Person, die er mit Dunkel umhüllt hat.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 24, 1, '»Warum sind vom Allmächtigen nicht Zeiten für Strafgerichte vorgesehen worden, und warum bekommen seine Getreuen nicht seine Gerichtstage zu sehen?');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 24, 2, 'Man verrückt die Grenzsteine, raubt Herden samt den Hirten;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 24, 3, 'den Esel der Verwaisten treibt man weg, nimmt die Kuh der Witwe als Pfand;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 24, 4, 'die Armen drängt man vom Wege ab; allesamt müssen die Elenden des Landes sich verkriechen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 24, 5, 'Seht nur! Wie Wildesel in der Wüste ziehen sie früh zu ihrem Tagewerk aus, nach Beute ausspähend; die Steppe liefert ihnen Brot für die Kinder;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 24, 6, 'auf dem Felde des Gottlosen müssen sie den Sauerampfer abernten und Nachlese in seinem Weinberge halten;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 24, 7, 'nackt bringen sie die Nacht zu, ohne Gewand, und haben keine Decke in der Kälte.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 24, 8, 'Von den Regengüssen der Berge triefen sie und schmiegen sich obdachlos an die Felsen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 24, 9, 'Man reißt die Waise von der Mutterbrust weg, und was der Elende an hat, nimmt man zum Pfande.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 24, 10, 'Nackt gehen sie einher, ohne Kleidung, und hungernd schleppen sie Garben (im Dienst der Reichen);');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 24, 11, 'innerhalb der Mauern der Gottlosen pressen sie Öl, treten die Keltern und leiden Durst dabei.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 24, 12, 'Aus den Städten heraus lassen Sterbende ihr Ächzen hören, und die Seele von Erschlagenen schreit um Rache; aber Gott rechnet es nicht als Ungebühr an!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 24, 13, 'Andere (Gottlose) gehören zu den Feinden des Tageslichts: sie wollen von Gottes Wegen nichts wissen und bleiben nicht auf seinen Pfaden.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 24, 14, 'Ehe es hell wird, steht der Mörder auf, tötet den Elenden und Armen; und in der Nacht treibt der Dieb sein Wesen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 24, 15, 'Das Auge des Ehebrechers aber lauert auf die Abenddämmerung, indem er denkt: ›Kein Auge soll mich erblicken!‹, und er legt sich eine Hülle vors Gesicht.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 24, 16, 'In der Finsternis bricht man in die Häuser ein, bei Tage halten sie sich eingeschlossen: sie wollen vom Licht nichts wissen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 24, 17, 'Denn als Morgenlicht gilt ihnen allesamt tiefe Nacht, weil sie mit den Schrecknissen der tiefen Nacht wohlvertraut sind.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 24, 18, 'Im Fluge fährt er über die Wasserfläche dahin; mit dem Fluch wird ihr Erbteil im Lande belegt; er schlägt nicht mehr den Weg zu den Weinbergen ein.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 24, 19, 'Wie Dürre und Sonnenglut die Schneewasser wegraffen, ebenso das Totenreich die, welche gesündigt haben.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 24, 20, 'Selbst der Mutterschoß vergißt ihn, das Gewürm labt sich an ihm; nicht mehr wird seiner gedacht, und wie ein Baum wird der Frevler abgehauen,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 24, 21, 'er, der die einsam dastehende, kinderlose Frau ausgeplündert und keiner Witwe Gutes getan hat.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 24, 22, 'Ebenso erhält Gott Gewalttätige lange Zeit durch seine Kraft: mancher steht wieder auf, der schon am Leben verzweifelte.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 24, 23, 'Er verleiht ihm Sicherheit, so daß er gestützt dasteht, und seine Augen wachen über ihren Wegen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 24, 24, 'Wenn sie hoch gestiegen sind – ein Augenblick nur, so sind sie nicht mehr da; sie sinken hin, werden hinweggerafft wie alle anderen auch; wie eine Ährenspitze werden sie abgeschnitten.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 24, 25, 'Ist’s etwa nicht so? Wer will mich Lügen strafen und meine Rede als nichtig erweisen?«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 25, 1, 'Da nahm Bildad von Suah das Wort und sagte:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 25, 2, '»Herrschergewalt und Schrecken sind bei ihm, der da Frieden schafft in seinen Höhen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 25, 3, 'Sind seine Heerscharen zu zählen? Und wo ist einer, über den sein Licht sich nicht erhöbe?');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 25, 4, 'Wie könnte da ein Mensch recht behalten Gott gegenüber und wie ein vom Weibe Geborener neben ihm rein erscheinen?');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 25, 5, 'Bedenke nur: sogar der Mond ist nicht hell, und die Sterne sind nicht rein in seinen Augen –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 25, 6, 'wieviel weniger der Sterbliche, die Made, und der Menschensohn, der Wurm!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 26, 1, 'Da antwortete Hiob folgendermaßen:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 26, 2, '»Wie hast du doch dem Schwachen beigestanden und den kraftlosen Arm gestützt!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 26, 3, 'Wie gut hast du doch den Unweisen beraten und tiefes Wissen in Fülle kundgetan!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 26, 4, 'Wem hast du einen Lehrvortrag gehalten, und wessen Odem ist dir entströmt?«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 26, 5, '»Die Schatten erzittern (vor Gott) tief unter den Wassern und deren Bewohnern;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 26, 6, 'nackt liegt das Totenreich vor ihm da und unverhüllt der Abgrund.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 26, 7, 'Er spannt den Norden (der Erde) über der Leere aus, hängt die Erde an dem Nichts auf.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 26, 8, 'Er bindet die Wasser in seine Wolken ein, ohne daß das Gewölk unter ihrer Last zerplatzt.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 26, 9, 'Er verhüllt den Anblick seines Thrones, indem er sein Gewölk über ihn ausbreitet.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 26, 10, 'Eine Grenzlinie hat er über den weiten Wassern abgezirkelt bis zur äußersten Grenze, wo das Licht mit der Finsternis zusammentrifft.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 26, 11, 'Die Säulen des Himmels geraten ins Wanken und beben infolge seines Scheltens.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 26, 12, 'Durch seine Kraft beruhigt er das Meer, und durch seine Klugheit hat er Rahab zerschmettert.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 26, 13, 'Durch seinen Hauch gewinnt der Himmel Heiterkeit; durchbohrt hat seine Hand den flüchtigen Drachen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 26, 14, 'Siehe, das sind nur die Säume seines Waltens, und welch ein leises Flüstern nur ist es, das wir von ihm vernehmen! Doch die Donnersprache seiner Machterweise – wer versteht diese?«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 27, 1, 'Hierauf fuhr Hiob nochmals in seiner Rede so fort:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 27, 2, '»So wahr Gott lebt, der mir mein Recht entzogen, und der Allmächtige, der mich in Verzweiflung gestürzt hat:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 27, 3, 'Solange irgend noch mein Lebensodem in mir ist und Gottes Hauch in meiner Nase –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 27, 4, 'nie sollen meine Lippen eine Unwahrheit reden und meine Zunge eine Täuschung aussprechen!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 27, 5, 'Fern sei es also von mir, euch recht zu geben, nein, bis zum letzten Atemzuge verleugne ich meine Unschuld nicht!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 27, 6, 'An meiner Gerechtigkeit halte ich fest und lasse sie nicht fahren: mein Gewissen straft mich wegen keines einzigen meiner Lebenstage!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 27, 7, '»Wie dem Frevler möge es meinem Feinde ergehen und meinem Widersacher wie dem Bösewicht!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 27, 8, 'Denn welche Hoffnung hat der Ruchlose noch, wenn Gott seinen Lebensfaden abschneidet, wenn er ihm seine Seele abfordert?');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 27, 9, 'Wird Gott wohl sein Schreien hören, wenn Drangsal über ihn hereinbricht?');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 27, 10, 'Oder darf er auf den Allmächtigen sich getrost verlassen, Gott anrufen zu jeder Zeit?«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 27, 11, '»Ich will euch über Gottes Tun belehren und, wie der Allmächtige es hält, euch nicht verhehlen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 27, 12, 'Seht doch, ihr alle habt euch selbst davon überzeugt: warum seid ihr gleichwohl in so eitlem Wahn befangen?');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 27, 13, 'Dies ist das Teil des frevelhaften Menschen bei Gott und das Erbe der Gewalttätigen, das sie vom Allmächtigen empfangen:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 27, 14, 'Wenn seine Kinder groß werden, so ist’s für das Schwert, und seine Sprößlinge haben nicht satt zu essen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 27, 15, 'Wer ihm dann von den Seinen noch übrigbleibt, wird durch die Pest ins Grab gebracht, und ihre Witwen stellen nicht einmal eine Totenklage an.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 27, 16, 'Wenn er Geld aufhäuft wie Staub und Gewänder ansammelt wie Gassenschmutz:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 27, 17, 'er sammelt sie wohl, aber ein Gerechter bekleidet sich mit ihnen, und das Geld wird ein Schuldloser in Besitz nehmen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 27, 18, 'Er hat sein Haus gebaut wie ein Spinngewebe und wie eine Hütte, die ein Feldhüter sich aufschlägt:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 27, 19, 'als reicher Mann legt er sich schlafen, ohne daß es schon weggerafft wäre – schlägt er die Augen auf, so ist nichts mehr da;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 27, 20, 'Schrecknisse überfallen ihn bei Tage, bei Nacht rafft der Sturmwind ihn hinweg;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 27, 21, 'der Ostwind hebt ihn empor, so daß er dahinfährt, und stürmt ihn hinweg von seiner Stätte.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 27, 22, 'Gott schleudert seine Geschosse erbarmungslos auf ihn; seiner Hand möchte er um jeden Preis entfliehen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 27, 23, 'Man klatscht über ihn in die Hände, und Zischen folgt ihm nach von seiner Wohnstätte her.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 28, 1, '»Denn wohl gibt es für das Silber einen Fundort und eine Stätte für das Golderz, wo man es auswäscht.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 28, 2, 'Eisen wird aus der Erde herausgeholt, und Gestein schmelzt man zu Kupfer um.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 28, 3, 'Der Finsternis hat (der Mensch) ein Ziel gesetzt, und bis in die äußersten Tiefen durchforscht das in Nacht und Grauen verborgene Gestein.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 28, 4, 'Man bricht einen Stollen fern von den im Licht Wohnenden; vergessen und fern vom Fuß der über ihnen Hinschreitenden hangen sie da (an Seilen), fern von den Menschen schweben sie.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 28, 5, 'Die Erde, aus welcher Brotkorn hervorwächst, wird in der Tiefe umgewühlt wie mit Feuer.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 28, 6, 'Man findet Saphir im Gestein und Staub, darin Gold ist.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 28, 7, 'Den Pfad dorthin kennt der Adler nicht, und das Auge des Falken hat ihn nicht erspäht;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 28, 8, 'nicht betreten ihn die stolzen Raubtiere, noch schreitet der Leu auf ihm einher.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 28, 9, 'An das harte Gestein legt (der Mensch) seine Hand, wühlt die Berge um von der Wurzel aus;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 28, 10, 'in die Felsen bricht er Schächte, und allerlei Kostbares erblickt sein Auge.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 28, 11, 'Die Wasseradern verbaut er, daß sie nicht durchsickern, und zieht so die verborgenen Schätze ans Licht hervor.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 28, 12, '»Die Weisheit aber – wo findet man diese? und wo ist die Fundstätte der Erkenntnis?');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 28, 13, 'Kein Mensch kennt den Weg zu ihr, und im Lande der Lebendigen ist sie nicht zu finden.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 28, 14, 'Die Flut der Tiefe sagt: ›In mir ist sie nicht‹; und das Meer erklärt: ›Bei mir weilt sie nicht‹.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 28, 15, 'Für geläutertes Gold ist sie nicht feil, und Silber kann nicht als Kaufpreis für sie dargewogen werden;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 28, 16, 'sie läßt sich nicht aufwägen mit Feingold von Ophir, mit kostbarem Onyx und Saphir.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 28, 17, 'Gold und Prachtglas kann man ihr nicht gleichstellen, noch sie eintauschen gegen Kunstwerke von gediegenem Gold;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 28, 18, 'Korallen und Kristall kommen (neben ihr) nicht in Betracht, und der Besitz der Weisheit ist mehr wert als Perlen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 28, 19, 'Äthiopiens Topas reicht nicht an sie heran, mit reinstem Feingold wird sie nicht aufgewogen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 28, 20, 'Die Weisheit also – woher kommt sie, und wo ist die Fundstätte der Erkenntnis?');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 28, 21, 'Verborgen ist sie vor den Augen aller lebenden Wesen und verhüllt sogar vor den Vögeln des Himmels.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 28, 22, 'Die Unterwelt und das Totenreich sagen von ihr: ›Nur ein Gerücht von ihr ist uns zu Ohren gedrungen.‹«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 28, 23, '»Gott hat den Weg zu ihr (allein) erschaut, und er kennt ihre Fundstätte;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 28, 24, 'denn er blickt bis zu den Enden der Erde und sieht, was unter dem ganzen Himmel ist.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 28, 25, 'Als er dem Winde seine Wucht bestimmte und die Wasser mit dem Maß abwog,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 28, 26, 'als er dem Regen sein Gesetz vorschrieb und dem Wetterstrahl die Bahn anwies:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 28, 27, 'da sah er sie und betätigte sie, setzte sie ein und erforschte sie auch.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 28, 28, 'Zu dem Menschen aber sprach er: ›Wisse wohl: die Furcht vor dem Allherrn – das ist Weisheit, und das Böse meiden – das ist Verstand!‹«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 29, 1, 'Hierauf fuhr Hiob in seiner Rede so fort:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 29, 2, '»O daß es mit mir noch so stände wie in den früheren Monden, wie in den Tagen, wo Gott mich behütete, –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 29, 3, 'als seine Leuchte noch über meinem Haupte strahlte und ich in seinem Licht durch das Dunkel wandelte,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 29, 4, 'so, wie es mit mir in den Tagen meines Herbstes stand, als Gottes Freundschaft über meinem Zelt waltete,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 29, 5, 'als der Allmächtige noch auf meiner Seite stand, meine Söhne noch rings um mich her waren,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 29, 6, 'als meiner Füße Tritte sich in Milch badeten und jeder Fels neben mir Bäche von Öl fließen ließ!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 29, 7, '»Wenn ich (damals) hinaufging zum Tor der Stadt und meinen Stuhl auf dem Marktplatz aufstellte,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 29, 8, 'da traten die jungen Männer zurück, sobald sie mich sahen, und die Greise erhoben sich und blieben stehen;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 29, 9, 'die Fürsten hielten an sich mit ihrem Reden und legten die Hand auf ihren Mund;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 29, 10, 'die Stimme der Edlen verstummte, und die Zunge blieb ihnen am Gaumen kleben.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 29, 11, 'Denn wessen Ohr mich hörte, der pries mich glücklich, und jedes Auge, das mich sah, legte Zeugnis für mich ab;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 29, 12, 'denn ich rettete den Elenden, der um Hilfe schrie, und die Waise, die sonst keinen Helfer hatte.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 29, 13, 'Der Segensspruch dessen, der verloren schien, erscholl über mich, und das Herz der Witwe machte ich jubeln.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 29, 14, 'In Gerechtigkeit kleidete ich mich, und sie war mein Ehrenkleid: wie ein Prachtgewand und Kopfbund schmückte mich mein Rechttun.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 29, 15, 'Für den Blinden war ich das Auge und für den Lahmen der Fuß;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 29, 16, 'ein Vater war ich für die Armen, und der Rechtssache des mir Unbekannten nahm ich mich gewissenhaft an;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 29, 17, 'dem Frevler zerschmetterte ich das Gebiß und riß ihm den Raub aus den Zähnen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 29, 18, 'So dachte ich denn: ›Im Besitz meines Nestes werde ich sterben und mein Leben werde ich lange wie der Phönix erhalten;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 29, 19, 'meine Wurzel wird am Wasser ausgebreitet liegen und der Tau auf meinen Zweigen nächtigen;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 29, 20, 'mein Ansehen wird unverändert mir verbleiben und mein Bogen sich in meiner Hand stets verjüngen.‹');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 29, 21, 'Mir hörten sie zu und warteten auf mich und lauschten schweigend auf meinen Rat.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 29, 22, 'Wenn ich gesprochen hatte, nahm keiner nochmals das Wort, sondern meine Rede träufelte auf sie herab.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 29, 23, 'Sie warteten auf meine Rede wie auf den Regen und sperrten den Mund nach mir auf wie nach Frühlingsregen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 29, 24, 'Ich lächelte ihnen zu, wenn sie mutlos waren, und das heitere Antlitz vermochten sie mir nicht zu trüben.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 29, 25, 'Sooft ich den Weg zu ihnen einschlug, saß ich als Haupt da und thronte wie ein König in der Kriegerschar, wie einer, der Leidtragenden Trost spendet.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 30, 1, '»Jetzt aber lachen über mich auch solche, die jünger an Jahren sind als ich, deren Väter ich nicht gewürdigt habe, sie neben den Wachhunden meines Kleinviehs anzustellen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 30, 2, 'Wozu hätte mir auch die Kraft ihrer Hände nützen können? Bei ihnen war ja die volle Rüstigkeit verlorengegangen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 30, 3, 'Durch Mangel und Hunger erschöpft, nagen sie das dürre Land ab, die unfruchtbare und öde Steppe;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 30, 4, 'sie pflücken sich Melde am Buschwerk ab, und die Ginsterwurzel ist ihr Brot.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 30, 5, 'Aus der Gemeinde werden sie ausgestoßen: man schreit über sie wie über Diebe.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 30, 6, 'In schauerlichen Klüften müssen sie wohnen, in Erdlöchern und Felshöhlen;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 30, 7, 'zwischen Sträuchern brüllen sie, unter Dorngestrüpp halten sie Zusammenkünfte:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 30, 8, 'verworfenes und ehrloses Gesindel, das man aus dem Lande hinausgepeitscht hat.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 30, 9, 'Und jetzt bin ich ihr Spottlied geworden und diene ihrem Gerede zur Kurzweil.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 30, 10, 'Mit Abscheu halten sie sich fern von mir und scheuen sich nicht, vor mir auszuspeien;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 30, 11, 'weil Gott meine Bogensehne abgespannt und mich niedergebeugt hat, lassen sie den Zügel vor mir schießen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 30, 12, 'Zu meiner Rechten erhebt sich die Brut; sie stoßen meine Füße weg und schütten ihre Unheilsstraßen gegen mich auf.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 30, 13, 'Meinen Pfad haben sie aufgerissen, auf meinen Sturz arbeiten sie hin, niemand tut ihnen Einhalt.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 30, 14, 'Wie durch einen breiten Mauerriß kommen sie heran, durch die Trümmer wälzen sie sich daher:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 30, 15, 'ein Schreckensheer hat sich gegen mich gekehrt; wie vom Sturmwind wird meine Ehre weggerafft, und wie eine Wolke ist mein Glück vorübergezogen!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 30, 16, '»So verblutet sich denn jetzt das Herz in mir: die Tage des Elends halten mich in ihrer Gewalt.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 30, 17, 'Die Nacht bohrt in meinen Gebeinen und löst sie von mir ab, und die an mir nagenden Schmerzen schlafen nicht.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 30, 18, 'Durch Allgewalt ist mein Gewand entstellt: so eng wie mein Unterkleid umschließt es mich.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 30, 19, 'Gott hat mich in den Kot geworfen, und ich bin (an Ansehen) dem Staub und der Asche gleichgestellt.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 30, 20, 'Schreie ich zu dir, so antwortest du mir nicht; trete ich vor dich hin, so achtest du nicht auf mich:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 30, 21, 'du hast dich mir in einen erbarmungslosen Feind verwandelt; mit deiner starken Hand bekämpfst du mich.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 30, 22, 'Du hebst mich auf (die Fittiche) des Sturmwindes empor, läßt mich dahinfahren und im Sturmestosen vergehen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 30, 23, 'Ja, ich weiß es: in den Tod willst du mich heimführen und in das Versammlungshaus aller Lebenden!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 30, 24, '»Doch streckt man nicht beim Ertrinken die Hand (nach Rettung) aus, und erhebt man beim Versinken nicht darob einen Hilferuf?');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 30, 25, 'Habe ich denn nicht um den geweint, der harte Tage durchzumachen hatte, und ist mein Herz nicht um den Armen bekümmert gewesen?');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 30, 26, 'Ja, auf Glück habe ich gewartet, aber Unheil kam; und ich harrte auf Licht, aber es kam Finsternis.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 30, 27, 'Mein Inneres ist in Aufruhr ohne Unterlaß, Leidenstage haben mich überfallen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 30, 28, 'In Trauer gehe ich einher ohne Sonne; ich stehe in der versammelten Gemeinde auf und schreie;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 30, 29, 'den (heulenden) Schakalen bin ich ein Bruder geworden und den (klagenden) Straußen ein Genosse.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 30, 30, 'Meine Haut löst sich, schwarz geworden, von mir ab, und mein Gebein ist von Fieberglut ausgedörrt.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 30, 31, 'So ist denn mein Zitherspiel zum Trauerlied geworden und meine Schalmei zu Tönen der Klage!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 31, 1, '»Mit meinen Augen habe ich einen Bund abgeschlossen, daß ich ja nicht lüstern nach einer Jungfrau blickte.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 31, 2, 'Denn was wäre der Lohn Gottes von oben gewesen und die Vergeltung des Allmächtigen aus Himmelshöhen?');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 31, 3, 'Trifft nicht Verderben den Frevler und Unglück die Überltäter?');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 31, 4, 'Sieht er nicht meine Wege, und zählt er nicht alle meine Schritte?');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 31, 5, 'Wenn ich mit Falschheit umgegangen bin und mein Fuß jemals der Täuschung zugeeilt ist:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 31, 6, 'Gott wäge mich auf gerechter Waage, so wird er meine Unschuld erkennen!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 31, 7, 'Wenn mein Schritt jemals vom rechten Wege abgewichen und mein Herz meinen Augen Folge geleistet hat und ein Flecken an meinen Händen kleben geblieben ist,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 31, 8, 'so will ich säen und ein anderer möge es verzehren, und alles, was mir sproßt, möge ausgerissen werden!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 31, 9, 'Wenn mein Herz sich um eines Weibes willen hat betören lassen und ich an der Tür meines Nächsten auf der Lauer gestanden habe,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 31, 10, 'so soll mein Weib für einen andern die Mühle drehen und andere mögen sich über sie hinstrecken!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 31, 11, 'Denn das wäre eine Schandtat gewesen und das ein Vergehen für den Strafrichter;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 31, 12, 'ja, ein Feuer wäre das gewesen, das bis zum Abgrund gefressen und meinen gesamten Besitz bis auf die Wurzel hätte vernichten müssen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 31, 13, 'Wenn ich das Recht meines Knechtes und meiner Magd mißachtet hätte, sooft sie im Streit mit mir lagen:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 31, 14, 'was hätte ich da tun sollen, wenn Gott aufgestanden wäre? Und was hätte ich ihm bei seiner Untersuchung erwidern können?');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 31, 15, 'Hat nicht mein Schöpfer auch ihn im Mutterleibe geschaffen und ein und derselbe uns im Mutterschoße gebildet?');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 31, 16, 'Wenn ich den Geringen ihr Begehren versagt und die Augen der Witwe habe schmachten lassen');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 31, 17, 'und meinen Bissen für mich allein verzehrt habe, ohne daß der Verwaiste sein Teil davon genossen hat –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 31, 18, 'nein, von meiner Jugend an ist er mir ja wie einem Vater aufgewachsen, und von meiner Mutter Leibe an bin ich ein Beschützer für jenen gewesen –;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 31, 19, 'wenn ich jemand habe verkommen sehen aus Mangel an Kleidung und daß ein Armer keine Schlafdecke hatte,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 31, 20, 'und dann seine Hüften mich nicht gesegnet haben und er sich nicht durch meiner Lämmer Wolle erwärmt hat;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 31, 21, 'wenn ich meine Faust jemals gegen eine Waise geschwungen habe, weil ich im Tor auf Beistand rechnen konnte:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 31, 22, 'so möge meine Schulter von ihrem Nacken fallen und mein Arm aus seiner Röhre ausgebrochen werden!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 31, 23, 'Denn als ein Schrecken wäre auf mich das Strafgericht Gottes eingedrungen, und vor seiner Erhabenheit hätte ich nicht zu bestehen vermocht.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 31, 24, 'Wenn ich je auf Gold mein Vertrauen gesetzt und zum Feingold gesagt habe: ›Du bist meine Zuversicht!‹;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 31, 25, 'wenn ich mich darüber gefreut habe, daß mein Vermögen groß war und daß meine Hand Ansehnliches erworben hatte;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 31, 26, 'wenn ich die Sonne angeschaut habe, wie hell sie strahlt, und den Mond, wie er in Pracht dahinwandelt,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 31, 27, 'und mein Herz sich insgeheim hat betören lassen, daß ich ihnen eine Kußhand zuwarf:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 31, 28, 'auch das wäre eine Verschuldung für den Strafrichter gewesen, denn damit hätte ich Gott in der Höhe die Treue gebrochen. –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 31, 29, 'Wenn ich mich je über das Unglück meines Feindes gefreut und darüber gejubelt habe, daß ein Mißgeschick ihm zugestoßen war –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 31, 30, 'nein, nie habe ich meiner Zunge zu sündigen gestattet, daß sie durch einen Fluch sein Leben gefordert hätte –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 31, 31, 'wenn meine Zeltgenossen nicht gesagt haben: ›Wo ist einer, der vom Fleisch seines Schlachtviehs nicht satt geworden wäre?‹ –;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 31, 32, 'nein, der Fremdling durfte nicht im Freien übernachten, und meine Tür hielt ich dem Wanderer offen –;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 31, 33, 'wenn ich meine Übertretungen, wie Menschen tun, verheimlicht habe, indem ich mein Vergehen in meinem Busen verbarg,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 31, 34, 'weil ich mich vor der großen Menge scheute und die Mißachtung der Geschlechter mich schreckte, so daß ich mich still verhielt, nicht vor die Tür hinaustrat;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 31, 35, '»O hätte ich doch einen, der mich anhören wollte! Siehe, hier ist meine Unterschrift! Der Allmächtige antworte mir! Und hätte ich doch die von meinem Gegner ausgefertigte Klageschrift!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 31, 36, 'Wahrlich, an meiner Schulter wollte ich sie zur Schau tragen, als Ehrenkranz sie mir um die Schläfe winden!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 31, 37, 'Denn über die Zahl meiner Schritte wollte ich ihm Rede stehen, wie zu einem Fürsten müßte er herannahen!« [Die Reden Hiobs sind zu Ende.]');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 31, 38, 'wenn mein Acker je über mich geschrien und seine Furchen allesamt geweint haben;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 31, 39, 'wenn ich seinen Ertrag ohne Zahlung verzehrt und seinen Besitzer ums Leben gebracht habe:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 31, 40, 'so sollen mir Disteln statt des Weizens aufgehen und Unkraut statt der Gerste!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 32, 1, 'Als nun jene drei Männer es aufgegeben hatten, dem Hiob (darauf) zu antworten, daß er sich selbst für gerecht hielt,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 32, 2, 'da entbrannte der Zorn des Busiters Elihu, des Sohnes Barachels, aus dem Geschlechte Ram. Gegen Hiob war er in Zorn geraten, weil dieser Gott gegenüber im Recht zu sein behauptete;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 32, 3, 'und gegen dessen drei Freunde war er deshalb in Zorn geraten, weil sie nicht die (rechte) Antwort gefunden hatten, um Hiob als schuldig zu erweisen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 32, 4, 'Elihu hatte aber mit einer Entgegnung an Hiob an sich gehalten, weil jene älter an Jahren waren als er.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 32, 5, 'Als Elihu aber sah, daß im Munde der drei Männer keine Widerlegung sich fand, geriet er in Zorn.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 32, 6, 'So nahm denn der Busiter Elihu, der Sohn Barachels, das Wort und sagte: »Noch jung bin ich an Tagen, und ihr seid Greise; darum habe ich mich gescheut und an mich gehalten, euch mein Wissen kundzutun.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 32, 7, 'Ich dachte: ›Das Alter mag reden und die Menge der Jahre Weisheit an den Tag legen!‹');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 32, 8, 'Jedoch der Geist ist es in den Menschen und der Hauch des Allmächtigen, der ihnen Einsicht verleiht.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 32, 9, 'Nicht die Bejahrten sind die weisesten, und nicht die Greise (an sich) verstehen sich auf das, was Recht ist.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 32, 10, 'Darum sage ich: ›Hört mir zu! Laßt auch mich mein Wissen euch kundtun.‹');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 32, 11, 'Seht, ich habe auf eure Reden geharrt, habe nach einsichtigen Darlegungen von euch hingehorcht, bis ihr die rechten Worte ausfindig machen würdet,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 32, 12, 'ja, ich habe aufmerksam auf euch achtgegeben; doch seht: keiner hat Hiob widerlegt, keiner von euch auf seine Reden die (rechte) Antwort gegeben.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 32, 13, 'Wendet nur nicht ein: ›Wir sind (bei ihm) auf Weisheit gestoßen: nur Gott kann ihn aus dem Felde schlagen, nicht ein Mensch!‹');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 32, 14, 'Gegen mich hat er ja noch keine Beweisgründe ins Treffen geführt, und nicht mit euren Reden werde ich ihm entgegentreten.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 32, 15, '»Bestürzt stehen sie da, finden keine Antwort mehr; die Worte sind ihnen ausgegangen!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 32, 16, 'Und da sollte ich warten, weil sie nicht mehr reden, weil sie dastehen, ohne zu antworten?');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 32, 17, 'Nein, auch ich will mein Teil erwidern, auch ich will mein Wissen kundtun!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 32, 18, 'Denn voll bin ich von Worten; der Geist drängt und beengt mich in meinem Inneren, zu reden.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 32, 19, 'Seht, meiner Brust geht es wie dem Wein, dem man nicht Luft schafft: sie droht zu bersten wie neugefüllte Schläuche.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 32, 20, 'Reden will ich, um mir Luft zu schaffen, will meine Lippen auftun und entgegnen!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 32, 21, 'Ich will dabei für niemand Partei nehmen und keinem Menschen zu Gefallen reden;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 32, 22, 'denn ich verstehe mich nicht darauf, zu Gefallen zu reden: gar bald würde mein Schöpfer mich sonst hinwegraffen.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 33, 1, '»Nun aber höre, Hiob, meine Reden und leihe dein Ohr allen meinen Worten!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 33, 2, 'Wisse wohl: wenn ich meinen Mund jetzt auftue und meine Zunge sich vernehmlich hören läßt,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 33, 3, 'so sind meine Worte aufrichtig wie mein Herz, und was meine Lippen wissen, sprechen sie unverfälscht aus.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 33, 4, 'Der Geist Gottes, der mich geschaffen hat, und der Hauch des Allmächtigen belebt mich.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 33, 5, 'Wenn du’s vermagst, so widerlege mich: rüste dich mit Beweisgründen gegen mich, tritt an zum Kampf!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 33, 6, 'Siehe, ich stehe zu Gott ebenso wie du: aus Ton bin auch ich gebildet.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 33, 7, 'Nein, Angst vor mir braucht dich nicht einzuschüchtern, und meine Wucht soll dich nicht niederdrücken!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 33, 8, '»Nun aber hast du vor meinen Ohren ausgesprochen, und deutlich habe ich deine Worte gehört:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 33, 9, '›Unschuldig bin ich, ohne Missetat, rein bin ich, und kein Vergehen haftet mir an!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 33, 10, 'Fürwahr, er (Gott) erfindet Feindseligkeiten gegen mich, sieht in mir einen Feind;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 33, 11, 'er legt meine Füße in den Block, überwacht alle meine Pfade.‹');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 33, 12, 'Sieh, darin hast du unrecht, entgegne ich dir; denn Gott ist größer als ein Mensch.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 33, 13, '»Warum hast du den Vorwurf gegen ihn erhoben, daß er dir auf alle deine Worte keine Antwort gebe?');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 33, 14, 'Vielmehr redet Gott einmal und zweimal, man achtet nur nicht darauf.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 33, 15, 'Im Traum, im Nachtgesicht, wenn tiefer Schlaf die Menschen befällt, im Schlummerzustand auf dem Lager:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 33, 16, 'da öffnet er den Menschen das Ohr und schreckt sie durch Verwarnung,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 33, 17, 'um den Menschen von seinem (bösen) Tun abzubringen und den Mann vor Überhebung zu behüten,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 33, 18, 'um seine Seele vor der Grube zu bewahren und sein Leben vor dem Geschoß des Todes.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 33, 19, 'Auch wird er durch Schmerzen auf seinem Lager in Zucht genommen und durch andauernden Leidenskampf in seinen Gliedern,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 33, 20, 'so daß für seinen Lebenstrieb alle Nahrung zum Ekel wird und für seine Eßlust sogar die Lieblingsspeise;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 33, 21, 'sein Fleisch schwindet dahin, daß es nicht mehr zu sehen ist, und seine vordem verborgenen Knochen treten zu Tage,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 33, 22, 'so daß seine Seele der Grube nahe kommt und sein Leben den Todesmächten.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 33, 23, '»Wenn dann ein Engel für ihn da ist, ein Fürsprecher, ein einziger aus den tausend, um für den Menschen Zeugnis von seiner Gerechtigkeit abzulegen,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 33, 24, 'und dieser sich seiner erbarmt und (zu Gott) spricht: ›Laß ihn frei, daß er nicht in die Grube hinabfährt! Ich habe eine Sühne gefunden‹,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 33, 25, 'so strotzt sein Leib wieder von Jugendkraft, so daß er in die Tage seines Jünglingsalters zurückversetzt wird.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 33, 26, 'Er betet zu Gott, und dieser nimmt ihn gnädig an, läßt ihn sein Angesicht unter Jauchzen schauen und gibt dem Menschen seine Gerechtigkeit zurück.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 33, 27, 'Er singt vor dem Volke und bekennt: ›Ich hatte gesündigt und das Recht verkehrt, aber es ist mir nicht vergolten worden!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 33, 28, 'Erlöst hat (Gott) meine Seele, daß sie nicht in die Grube gefahren ist, und mein Leben erfreut sich am Anblick des Lichts!‹«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 33, 29, '»Sieh, dies alles tut Gott zweimal, ja dreimal an dem Menschen,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 33, 30, 'um seine Seele von der Grube fernzuhalten und damit er vom Licht des Lebens umleuchtet werde.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 33, 31, 'Merke auf, Hiob, höre mir zu, schweige und laß mich reden!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 33, 32, 'Hast du etwas einzuwenden, so widerlege mich; sprich, denn ich möchte dich gern rechtfertigen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 33, 33, 'Hast du aber nichts, so höre mir zu; schweige, damit ich dich Weisheit lehre!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 34, 1, 'Elihu hob dann wieder an und sagte:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 34, 2, '»Vernehmt, ihr Weisen, meine Worte und, ihr Einsichtigen, schenkt mir Gehör!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 34, 3, 'denn das Ohr prüft die Worte, wie der Gaumen die Speisen kostet.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 34, 4, 'Wir wollen doch prüfend das Recht finden, wollen gemeinsam erforschen, was gut ist.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 34, 5, 'Denn Hiob hat behauptet: ›Ich bin gerecht, aber Gott hat mir mein Recht vorenthalten;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 34, 6, 'trotz meines Rechtes soll ich ein Lügner sein! Tödlich steckt sein Pfeil in mir, ohne daß ich mich verschuldet habe!‹«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 34, 7, '»Wo ist ein Mann wie Hiob, der Lästerrede trinkt wie Wasser');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 34, 8, 'und in Gemeinschaft mit Übeltätern getreten ist und mit Frevlern Umgang pflegt?');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 34, 9, 'Denn er hat behauptet: ›Der Mensch hat keinen Nutzen davon, daß er mit Gott die Freundschaft aufrecht hält.‹');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 34, 10, 'Darum hört mich an, ihr einsichtsvollen Männer! Fern bleibe der Vorwurf von Gott, daß er Frevel verübe, und vom Allmächtigen, daß er Unrecht tue!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 34, 11, 'Nein, was der Mensch tut, das vergilt er ihm und läßt es jedem nach seinem Lebenswandel ergehen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 34, 12, 'Ja wahrlich, Gott handelt nicht frevelhaft, und der Allmächtige beugt das Recht nicht.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 34, 13, 'Wer hat die Erde seiner Obhut anvertraut und wer den ganzen Erdkreis hergestellt?');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 34, 14, 'Wenn er nur an sich selbst dächte, seinen Geist und seinen Odem in sich zurückzöge,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 34, 15, 'so müßte alles Fleisch insgesamt verscheiden und der Mensch wieder zu Staub werden.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 34, 16, 'Wenn du also verständig bist, so höre dies und gib wohl acht, wie meine Worte lauten!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 34, 17, 'Kann auch, wer das Recht haßt, ein Gemeinwesen leiten? Oder willst du den Allgerechten verdammen,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 34, 18, 'ihn, der zum Könige sagt: ›Du Nichtswürdiger!‹ und zu den Hochgestellten: ›Du Bösewicht!‹,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 34, 19, 'ihn, der die Person der Fürsten nicht ansieht und den Vornehmen nicht vor dem Geringen bevorzugt, weil sie ja alle das Werk seiner Hände sind.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 34, 20, 'In einem Augenblick sterben sie, und mitten in der Nacht wird ein Volk erschüttert und muß dahinfahren, und Machthaber beseitigt er, ohne die Hand zu rühren.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 34, 21, 'Denn seine Augen sind auf die Wege eines jeden Menschen gerichtet, und er sieht alle seine Schritte:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 34, 22, 'da gibt es kein Dunkel und keine noch so dichte Finsternis, daß die Frevler sich darin verbergen könnten.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 34, 23, 'Denn er braucht einen Menschen nicht erst lange zu beobachten, damit er vor Gott zum Gericht erscheine:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 34, 24, 'nein, er zerschmettert Gewalthaber ohne Untersuchung und läßt andere an ihre Stelle treten.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 34, 25, 'Somit kennt er ihre Taten wohl und stürzt sie über Nacht, so daß sie zermalmt werden.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 34, 26, 'Als Frevler, die sie sind, geißelt er sie vor aller Augen');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 34, 27, 'zur Strafe dafür, daß sie von ihm abgefallen sind und alle seine Wege unbeachtet gelassen haben,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 34, 28, 'so daß sie den Hilferuf des Armen zu ihm hinaufdringen ließen und er den Notschrei der Bedrückten vernehmen mußte.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 34, 29, 'Verhält er sich aber ruhig, wer darf ihn verdammen? Und verhüllt er sein Angesicht, wer kann ihn schauen? So waltet er sowohl über Völkern als auch über einzelnen Menschen gleicherweise,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 34, 30, 'damit nicht ruchlose Menschen die Herrschaft führen, Leute, welche Fallstricke für das Volk sein würden.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 34, 31, '»Denn soll etwa Gott zu dir sagen: ›Ich habe mich geirrt; will (aber) nicht wieder verkehrt handeln?');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 34, 32, 'Über das, was ich nicht sehe, belehre du mich; wenn ich unrecht gehandelt habe, will ich es nicht wieder tun.‹');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 34, 33, 'Soll er nach deinem Sinn Vergeltung üben, weil du unzufrieden bist, und sagen: ›Du hast das Bessere zu bestimmen, nicht ich; was du also weißt, das sprich aus!‹?');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 34, 34, 'Verständige Leute werden mir zugestehen und jeder weise Mann, der mir zuhört:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 34, 35, '›Hiob redet ohne Einsicht, und seine Worte sind nicht wohlbedacht.‹');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 34, 36, 'O daß doch Hiob fort und fort geprüft würde wegen seiner Widerreden nach Art der Frevler!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 34, 37, 'Denn zu seiner Verfehlung fügt er noch den Abfall (von Gott) hinzu: er höhnt laut in unserer Mitte und macht viel Redens gegen Gott.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 35, 1, 'Elihu hob dann wieder an und sagte:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 35, 2, '»Hältst du das für recht, nennst du das ›meine Gerechtigkeit vor Gott‹,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 35, 3, 'daß du fragst: ›Was nützt sie mir?‹ und: ›Was habe ich mehr davon, als wenn ich sündigte?‹');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 35, 4, 'Ich will dir darauf die Antwort geben, dir und zugleich deinen Freunden neben dir.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 35, 5, 'Blicke zum Himmel empor und sieh ihn an und schaue zu den Wolken hinauf, die hoch über dir sind:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 35, 6, 'wenn du sündigst, was tust du ihm damit zuleide? Und sind deine Übertretungen zahlreich, welchen Schaden fügst du ihm damit zu?');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 35, 7, 'Und so auch: wenn du gerecht bist, welches Geschenk machst du ihm damit, oder was empfängt er aus deiner Hand?');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 35, 8, 'Nur den Menschen, wie du einer bist, geht dein Freveln an, und nur dir, dem Menschensohn, kommt dein Gerechtsein zugute.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 35, 9, '»Man schreit wohl über die Menge der Bedrückungen, klagt laut über die Gewalttätigkeit der Großen,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 35, 10, 'doch keiner sagt: ›Wo ist Gott, mein Schöpfer, der Lobgesänge schenkt in der Nacht,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 35, 11, 'der uns Belehrung verleiht wie keinem Tiere des Feldes und uns höhere Weisheit gewinnen läßt als die Vögel des Himmels?‹');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 35, 12, 'Da schreit man denn, ohne Erhörung bei ihm zu finden, wegen des Übermuts der Bösen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 35, 13, 'Jawohl: auf eitles Klagen hört Gott nicht, sondern der Allmächtige läßt es unbeachtet.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 35, 14, 'Nun sagst du aber gar, du sehest ihn nicht; deine Sache liege ihm vor, du wartest aber vergeblich auf seine Entscheidung!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 35, 15, 'Und nun, da sein Zorn noch nicht gestraft und er sich um Torheit nicht sonderlich gekümmert hat,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 35, 16, 'da reißt Hiob seinen Mund zu leerem Gerede auf und ergeht sich ohne Einsicht in vermessenen Worten!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 36, 1, 'Hierauf fuhr Elihu weiter fort zu reden:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 36, 2, '»Gedulde dich nur noch ein wenig, daß ich dich unterweise! Denn ich habe für Gottes Sache noch mehr zu sagen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 36, 3, 'Ich will mit meinem Wissen weit ausholen, um meinem Schöpfer zu seinem Recht zu verhelfen;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 36, 4, 'denn wahrlich, meine Worte sind kein Trug: ein Mann mit vollkommener Erkenntnis verhandelt mit dir.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 36, 5, '»Siehe, Gott ist gewaltig und doch nicht teilnahmslos, gewaltig an Kraft des Herzens.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 36, 6, 'Er erhält den Frevler nicht am Leben, läßt aber den Elenden ihr Recht zukommen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 36, 7, 'Er wendet seine Augen von dem Gerechten nicht ab, und Königen auf dem Thron verschafft er für immer einen festen Sitz, damit sie erhöht sind.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 36, 8, 'Wenn sie aber mit Ketten gefesselt sind und in Unglücksbanden gefangen liegen,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 36, 9, 'so hält er ihnen damit ihr Tun vor, ihre Übertretungen, daß sie sich nämlich überhoben haben;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 36, 10, 'da öffnet er ihnen das Ohr für Warnungen und mahnt sie, sich vom Frevel abzuwenden.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 36, 11, 'Wenn sie nun darauf hören und sich unterwerfen, so beenden sie ihre Tage im Glück und ihre Jahre in Wonne;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 36, 12, 'wollen sie aber nicht darauf hören, so fallen sie dem Todesgeschoß anheim und verscheiden in Unverstand.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 36, 13, 'Dann geraten aber solche ruchlos Gesinnte in Zorn: sie schreien nicht um Hilfe, obgleich er sie in Fesseln geschlagen hat.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 36, 14, 'So stirbt denn ihre Seele schon in der Jugendkraft dahin, und ihr Leben endet wie das der Lustknaben.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 36, 15, 'Die Dulder dagegen errettet er (gerade) durch ihr Dulden und öffnet ihnen durch die Leiden das Ohr.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 36, 16, '»So sucht er auch dich aus dem Rachen der Not auf weiten Raum zu führen, wo keine Enge mehr ist, und dein Tisch würde mit fettem Mahl reich besetzt sein;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 36, 17, 'du aber hast dich ganz dem frevelhaften Urteilen hingegeben, darum werden Urteil und Gericht dich treffen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 36, 18, 'Laß die Leidenschaft dich ja nicht zu Lästerungen verleiten und die Größe des Lösegeldes dich nicht beirren!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 36, 19, 'Wird etwa dein Geschrei dich aus der Bedrängnis herausbringen und alle noch so gewaltigen Anstrengungen?');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 36, 20, 'Sehne die Nacht nicht herbei, wo Völker an ihrer Stätte auffahren!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 36, 21, 'Hüte dich, wende dich nicht dem Frevel zu; denn dazu bist du eher geneigt als zum Leiden.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 36, 22, 'Bedenke wohl: Gott vollbringt erhabene Dinge durch seine Kraft: wer ist ein Lehrmeister wie er?');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 36, 23, 'Wer hat ihm sein Walten vorgeschrieben? Und wer hat je zu ihm sagen dürfen: ›Du hast unrecht gehandelt‹?');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 36, 24, 'Sei darauf bedacht, sein Tun zu erheben, das die Menschen in Liedern preisen!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 36, 25, 'Alle Menschen schauen es bewundernd an, und doch erblickt es der Sterbliche nur von ferne.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 36, 26, '»Bedenke wohl: Gott ist zu erhaben für unsere Erkenntnis; die Zahl seiner Jahre, sie ist unerforschlich.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 36, 27, 'Denn er zieht Tropfen aus dem Meer empor, daß sie von dem Dunst, den er bildet, als Regen niederträufeln,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 36, 28, 'von dem die Wolken triefen und den sie auf die Menschenmenge rieseln lassen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 36, 29, 'Wie kann man vollends die Ausbreitungen der Gewitterwolken verstehen, den Donnerschall seines Zeltes?');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 36, 30, 'Siehe, er breitet sein Licht darüber aus und bedeckt damit die tiefsten Tiefen des Meeres!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 36, 31, 'denn dadurch richtet er die Völker, spendet zugleich aber auch Nahrung in reicher Fülle.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 36, 32, 'Beide Hände hüllt er in den leuchtenden Blitz und entbietet ihn gegen den Angreifer.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 36, 33, 'Sein Donnergetöse kündigt ihn an als einen, der seinen Zorn gegen den Frevel eifern läßt.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 37, 1, 'Ja, darüber erzittert mein Herz und fährt stürmisch empor von seiner Stelle.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 37, 2, 'Hört, o hört auf das Donnern seiner Stimme und auf das Tosen, das seinem Munde entfährt!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 37, 3, 'Er entfesselt es unter dem ganzen Himmel hin und sein Blitzesleuchten bis an die Säume der Erde.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 37, 4, 'Hinter (dem Blitz) her brüllt der Donner; er dröhnt mit seiner hehren Stimme und hält (die Blitze) nicht zurück, sobald sein Donner sich vernehmen läßt.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 37, 5, 'Gott donnert mit seiner Stimme wunderbar, er, der große Dinge tut, die wir nicht begreifen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 37, 6, 'Denn dem Schnee gebietet er: ›Falle auf die Erde nieder!‹ und ebenso dem Regenguß: ›Falle als Dauerregen nieder!‹');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 37, 7, 'Dann zwingt er die Hände aller Menschen zur Untätigkeit, damit alle Menschen zur Erkenntnis seines Wirkens kommen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 37, 8, 'Da zieht sich das Wild in sein Versteck zurück und hält sich ruhig in seinen Schlupfwinkeln.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 37, 9, 'Aus der Kammer bricht der Sturm hervor und von den Nordwinden die Kälte:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 37, 10, 'durch den Hauch Gottes entsteht das Eis, und die weite Wasserfläche liegt in enger Haft.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 37, 11, 'Auch belastet er mit Wasserfülle das Gewölk, läßt seine Blitzwolken überströmen;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 37, 12, 'die wenden sich dann unter seiner Leitung hierhin und dorthin, um alles, was er ihnen gebietet, auszurichten auf dem ganzen weiten Erdkreise:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 37, 13, 'bald als Rute, wenn sie seinem Lande not tut, bald als Huldbeweis läßt er sie sich entladen.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 37, 14, '»Vernimm dies, Hiob! Stehe still und erwäge die Wunderwerke Gottes!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 37, 15, 'Begreifst du es, wie Gott ihnen Befehl erteilt und das Licht seines Gewölks aufleuchten läßt?');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 37, 16, 'Verstehst du dich auf das Schweben der Wolken, auf die Wundertaten des an Weisheit Vollkommenen,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 37, 17, 'du, dem die Kleider zu heiß werden, wenn das Land beim Südwind in schwüler Hitze daliegt?');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 37, 18, 'Kannst du gleich ihm das Himmelsgewölbe ausbreiten, das fest ist wie ein gegossener Spiegel?');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 37, 19, 'Laß uns wissen, was wir ihm sagen sollen! Wir können vor Finsternis nichts vorbringen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 37, 20, 'Soll ihm gemeldet werden, daß ich reden wolle? Hat wohl je ein Mensch gefordert, er wolle vernichtet sein?');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 37, 21, 'Und nun: in das Sonnenlicht kann man nicht blicken, wenn es am Himmelsgewölbe strahlt, nachdem der Wind darüber hingefahren ist und (den Himmel) geklärt hat.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 37, 22, 'Von Norden her kommt das Nordlicht: um Gott her liegt furchtbare Pracht.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 37, 23, 'Den Allmächtigen, wir erreichen ihn nicht, ihn, der an Kraft gewaltig ist; aber das Recht und die volle Gerechtigkeit beugt er nicht.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 37, 24, 'Darum sollen die Menschen ihn fürchten: er sieht keinen an, der sich selbst weise dünkt!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 1, 'Da antwortete der HERR dem Hiob aus dem Wettersturme heraus folgendermaßen:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 2, '»Wer ist’s, der da den Heilsplan Gottes verdunkelt mit Worten ohne Einsicht?');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 3, 'Auf! Gürte dir die Lenden wie ein Mann, so will ich dich fragen, und du belehre mich!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 4, '»Wo warst du, als ich die Erde baute? Sprich es aus, wenn du Einsicht besitzest!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 5, 'Wer hat ihre Maße bestimmt – du weißt es ja! –, oder wer hat die Meßschnur über sie ausgespannt?');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 6, 'Worauf sind ihre Grundpfeiler eingesenkt worden, oder wer hat ihren Eckstein gelegt,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 7, 'während die Morgensterne allesamt laut frohlockten und alle Gottessöhne jauchzten?');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 8, 'Und wer hat das Meer mit Toren verschlossen, als es hervorbrach, aus dem Mutterschoß heraustrat?');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 9, 'Als ich Gewölk zu seinem Kleide machte und dunkle Nebel zu seinen Windeln?');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 10, 'Als ich ihm das von mir bestimmte Gebiet absteckte und ihm Riegel und Tore herstellte');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 11, 'und sprach: ›Bis hierher darfst du kommen, aber nicht weiter, und hier soll sich der Stolz deiner Wellen brechen!‹');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 12, 'Hast du jemals, seitdem du lebst, das Morgenlicht bestellt? Hast du dem Frührot seine Stätte angewiesen,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 13, 'daß es die Säume der Erde erfasse und die Frevler von ihr verscheucht werden?');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 14, 'Sie (die Erde) verwandelt sich alsdann wie Wachs unter dem Siegel, und alles stellt sich dar wie ein Prachtgewand;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 15, 'den Frevlern aber wird ihr Licht entzogen, und der zum Schlagen schon erhobene Arm zerbricht.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 16, 'Bist du bis zu den Quellen des Meeres gekommen, und hast du die tiefsten Tiefen des Weltmeers durchwandelt?');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 17, 'Haben sich vor dir die Pforten des Todes aufgetan, und hast du die Pforten des Schattenreichs gesehen?');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 18, 'Hast du die weiten Flächen der Erde überschaut? Sage an, wenn du dies alles weißt!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 19, 'Wo geht denn der Weg nach der Wohnung des Lichts, und die Finsternis, wo hat sie ihre Heimstätte,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 20, 'daß du sie in ihr Gebiet hinbringen könntest und daß die Pfade zu ihrem Hause dir bekannt wären?');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 21, 'Du weißt es ja, denn damals wurdest du ja geboren, und die Zahl deiner Lebenstage ist groß!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 22, 'Bist du zu den Vorratskammern des Schnees gekommen, und hast du die Speicher des Hagels gesehen,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 23, 'den ich aufgespart habe für die Drangsalszeiten, für den Tag des Kampfes und des Krieges?');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 24, 'Wo ist der Weg dahin, wo das Licht sich teilt und von wo der Ostwind sich über die Erde verbreitet?');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 25, 'Wer hat der Regenflut Kanäle gespalten und einen Weg dem Donnerstrahl gebahnt,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 26, 'um regnen zu lassen auf menschenleeres Land, auf die Steppe, wo niemand wohnt,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 27, 'um die Einöde und Wildnis reichlich zu tränken und Pflanzengrün sprießen zu lassen?');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 28, 'Hat der Regen einen Vater, oder wer erzeugt die Tropfen des Taues?');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 29, 'Aus wessen Mutterschoße geht das Eis hervor, und wer läßt den Reif des Himmels entstehen?');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 30, 'Wie zu Stein verhärten sich die Wasser, und der Spiegel der Fluten schließt sich zur festen Decke zusammen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 31, 'Vermagst du die Bande des Siebengestirns zu knüpfen oder die Fesseln des Orion zu lösen?');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 32, 'Läßt du die Bilder des Tierkreises zur rechten Zeit hervortreten, und leitest du den Großen Bären samt seinen Jungen?');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 33, 'Kennst du die für den Himmel gültigen Gesetze, oder bestimmst du seine Herrschaft über die Erde?');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 34, 'Kannst du deine Stimme hoch zu den Wolken dringen lassen, daß strömender Regen dich bedecke?');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 35, 'Entsendest du die Blitze, daß sie hinfahren und zu dir sagen: ›Hier sind wir‹?');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 36, 'Wer hat Weisheit in die Wolkenschichten gelegt oder wer dem Luftgebilde Verstand verliehen?');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 37, 'Wer zählt die Federwolken mit Weisheit ab, und die Schläuche des Himmels, wer läßt sie sich ergießen,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 38, 'wenn das Erdreich sich zu Metallguß verhärtet hat und die Schollen sich fest zusammenballen?');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 39, 'Erjagst du für die Löwin die Beute, und stillst du die Gier der jungen Leuen,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 40, 'wenn sie in ihren Höhlen kauern, im Dickicht auf der Lauer liegen?');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 41, 'Wer verschafft dem Raben sein Futter, wenn seine Jungen zu Gott schreien und wegen Mangels an Nahrung umherirren?');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 39, 1, 'Kennst du die Zeit, wo die Felsgemsen werfen, und überwachst du das Kreißen der Hirschkühe?');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 39, 2, 'Zählst du die Monde, während derer sie trächtig sind, und weißt du die Zeit, wann sie gebären?');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 39, 3, 'Sie kauern nieder, lassen ihre Jungen zur Welt kommen, entledigen sich leicht ihrer Geburtsschmerzen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 39, 4, 'Ihre Jungen erstarken, werden im Freien groß; sie laufen davon und kehren nicht wieder zu ihnen zurück.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 39, 5, 'Wer hat den Wildesel frei laufen lassen und wer die Bande dieses Wildfangs gelöst,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 39, 6, 'dem ich die Steppe zur Heimat angewiesen habe und zur Wohnung die Salzgegend?');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 39, 7, 'Er lacht des Gewühls der Stadt, den lauten Zuruf des Treibers hört er nicht.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 39, 8, 'Was er auf den Bergen erspäht, ist seine Weide, und jedem grünen Halme spürt er nach.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 39, 9, 'Wird der Büffel Lust haben, dir zu dienen oder nachts an deiner Krippe zu lagern?');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 39, 10, 'Kannst du den Büffel mit seinem Leitseil an die Furche binden, oder wird er über Talgründe die Egge hinter dir herziehen?');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 39, 11, 'Darfst du ihm trauen, weil er große Kraft besitzt, und ihm deinen Ernteertrag überlassen?');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 39, 12, 'Darfst du ihm zutrauen, daß er deine Saat einbringen und sie auf deiner Tenne zusammenfahren werde?');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 39, 13, 'Die Straußenhenne schwingt fröhlich ihre Flügel: sind es aber des (liebevollen) Storches Schwingen und Gefieder?');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 39, 14, 'Nein, sie vertraut ihre Eier der Erde an und läßt sie auf dem Sande warm werden;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 39, 15, 'denn sie denkt nicht daran, daß ein Fuß sie dort zerdrücken und ein wildes Tier sie zertreten kann.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 39, 16, 'Hart behandelt sie ihre Jungen, als gehörten sie ihr nicht; ob ihre Mühe vergeblich ist, das kümmert sie nicht;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 39, 17, 'denn Gott hat ihr große Klugheit versagt und ihr keinen Verstand zugeteilt.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 39, 18, 'Doch sobald sie hoch auffährt zum Laufen, verlacht sie das Roß und seinen Reiter.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 39, 19, 'Gibst du dem Roß die gewaltige Stärke? Bekleidest du seinen Hals mit der wallenden Mähne?');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 39, 20, 'Machst du es springen wie die Heuschrecke? Sein stolzes Schnauben – wie erschreckend!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 39, 21, 'Es scharrt den Boden im Blachfeld und freut sich seiner Kraft, zieht der gewappneten Schar entgegen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 39, 22, 'Es lacht über Furcht und erschrickt nicht, macht nicht kehrt vor dem Schwert;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 39, 23, 'auf ihm klirrt ja der Köcher, blitzen der Speer und der Kurzspieß.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 39, 24, 'Mit Ungestüm und laut stampfend sprengt es im Fluge dahin und läßt sich nicht halten, wenn die Posaune erschallt;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 39, 25, 'bei jedem Trompetenstoß ruft es ›Hui!‹ und wittert den Kampf von fern, den Donnerruf der Heerführer und das Schlachtgetöse.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 39, 26, 'Hebt der Habicht dank deiner Einsicht die Schwingen, breitet seine Flügel aus nach dem Süden zu?');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 39, 27, 'Oder schwebt der Adler auf dein Geheiß empor und baut sein Nest in der Höhe?');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 39, 28, 'Auf Felsen wohnt er und horstet auf Felszacken und Bergspitzen;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 39, 29, 'von dort späht er nach Beute aus: in weite Ferne blicken seine Augen;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 39, 30, 'und seine Jungen schon verschlingen gierig das Blut, und wo Erschlagene liegen, da ist auch er.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 40, 1, 'Hierauf wandte sich der HERR weiter an Hiob mit der Frage:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 40, 2, '»Hadern will der Tadler mit dem Allmächtigen? Der Ankläger Gottes gebe Antwort darauf!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 40, 3, 'Da antwortete Hiob dem HERRN:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 40, 4, '»Ach, ich bin zu gering: was soll ich dir entgegnen? Ich lege meine Hand auf den Mund!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 40, 5, 'Einmal habe ich geredet, werde aber nichts mehr entgegnen; und noch ein zweites Mal habe ich es getan, doch niemals tue ich es wieder.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 40, 6, 'Weiter antwortete der HERR dem Hiob aus dem Wettersturm heraus folgendermaßen:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 40, 7, '»Auf! Gürte dir die Lenden wie ein Mann: ich will dich fragen, und du belehre mich!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 40, 8, 'Willst du wirklich mein Recht zunichte machen, mich schuldig sprechen, damit du als gerecht dastehst?«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 40, 9, '»Hast du etwa einen Arm wie Gott, und vermagst du den Donner so laut rollen zu lassen wie er?');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 40, 10, 'So schmücke dich doch mit Erhabenheit und Hoheit und kleide dich in Pracht und Herrlichkeit!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 40, 11, 'Laß die Ausbrüche deines Zorns sich ergießen! Und gewahrst du irgendeinen Hochmütigen, so wirf ihn nieder!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 40, 12, 'Ja, gewahrst du irgendeinen Hochmütigen, so demütige ihn und stürze die Frevler nieder, wo sie stehen!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 40, 13, 'Laß sie allesamt tief in den Staub sinken, laß ihr Angesicht erstarren in Todesgrauen!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 40, 14, 'Dann will auch ich dich lobend anerkennen, daß deine Rechte dir den Sieg verliehen hat.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 40, 15, '»Sieh doch das Nilpferd an, das ich geschaffen habe wie dich: von Pflanzen nährt es sich wie das Rind!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 40, 16, 'Sieh doch, welche Kraft bei ihm in den Lenden wohnt und welche Stärke in den Muskeln seines Leibes!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 40, 17, 'Es macht seinen Schwanz so starr wie eine Zeder; die Sehnen seiner Schenkel sind fest verflochten.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 40, 18, 'Seine Knochen sind Röhren von Erz, seine Gebeine gleich geschmiedeten Eisenstangen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 40, 19, 'Es ist der Erstling der schöpferischen Tätigkeit Gottes; sein Bildner hat ihm auch sein Schwert verliehen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 40, 20, 'Denn Futter liefern ihm die Anhöhen, wo alle wilden Landtiere spielen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 40, 21, 'Unter Lotusbüschen lagert es sich, im Versteck von Schilfrohr und Sumpf;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 40, 22, 'Lotusbüsche geben ihm Deckung mit ihrem Schattendach, und die Weiden des Baches umgeben es.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 40, 23, 'Selbst wenn der Strom mächtig anschwillt, gerät es nicht in Unruhe: es bleibt wohlgemut, wenn auch ein Jordan gegen seinen Rachen andringt.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 40, 24, 'Wer will es von vorn packen, wer mit einem Fangseil ihm die Nase durchbohren?');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 40, 25, 'Kannst du das Krokodil am Angelhaken heranziehen und ihm die Zunge mit der Schnur niederdrücken?');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 40, 26, 'Kannst du ihm einen Binsenring durch die Nase ziehen und einen Dorn durch seinen Kinnbacken bohren?');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 40, 27, 'Meinst du, es werde viele Bitten an dich richten oder dir gute Worte geben?');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 40, 28, 'Wird es einen Vertrag mit dir schließen, wonach du es für immer in deine Dienste nähmest?');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 40, 29, 'Wirst du mit ihm spielen wie mit einem Vöglein und es zur Kurzweil für deine Mägdlein anbinden?');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 40, 30, 'Treibt die Fischerzunft Handel mit ihm, daß sie es stückweise an die Händler abgibt?');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 40, 31, 'Kannst du ihm die Haut mit Spießen spicken und seinen Kopf mit Fischerhaken durchbohren?');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 40, 32, 'Vergreife dich nur einmal an ihm: mache dich auf Kampf gefaßt! Du wirst’s gewiß nicht wieder tun!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 41, 1, 'Ja, eine solche Hoffnung erweist sich als Trug: schon bei seinem Anblick bricht man zusammen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 41, 2, 'Niemand ist so tollkühn, daß er es aufstört; und wer ist es, der ihm entgegengetreten und heil davongekommen wäre?');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 41, 3, 'Wer unter dem ganzen Himmel ist es?');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 41, 4, 'Nicht schweigen will ich von seinen Gliedmaßen, weder von seiner Kraftfülle noch von der Schönheit seines Baues.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 41, 5, 'Wer hat je sein Panzerkleid oben aufgedeckt und wer sich in die Doppelreihe seines Gebisses hineingewagt?');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 41, 6, 'Wer hat je das Doppeltor seines Rachens geöffnet? Rings um seine Zähne herum lagert Schrecken.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 41, 7, 'Prachtvoll sind die Zeilen seiner Schilder, jede einzelne enganliegend wie durch ein festes Siegel:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 41, 8, 'eine schließt sich eng an die andere an, und kein Lüftchen dringt zwischen ihnen ein:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 41, 9, 'jede haftet fest an der andern, sie greifen untrennbar ineinander.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 41, 10, 'Sein Niesen läßt einen Lichtschein erglänzen, und seine Augen gleichen den Wimpern des Morgenrots.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 41, 11, 'Aus seinem Rachen schießen Flammen, sprühen Feuerfunken hervor.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 41, 12, 'Aus seinen Nüstern strömt Rauch heraus wie aus einem siedenden Topf und wie aus Binsenfeuer.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 41, 13, 'Sein Atem setzt Kohlen in Brand, und Flammen entfahren seinem Rachen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 41, 14, 'In seinem Nacken wohnt Kraft, und vor ihm her stürmt bange Furcht dahin.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 41, 15, 'Die Wampen seines Leibes haften fest zusammen, sind wie angegossen an ihm, unbeweglich.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 41, 16, 'Sein Herz ist hart wie ein Stein und unbeweglich wie ein unterer Mühlstein.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 41, 17, 'Wenn es auffährt, schaudern selbst Helden, geraten vor Entsetzen außer sich.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 41, 18, 'Trifft man es mit dem Schwert – das haftet ebensowenig wie Speer, Wurfspieß und Pfeil.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 41, 19, 'Eisen achtet es gleich Stroh, Erz gleich morschem Holz.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 41, 20, 'Kein Pfeil des Bogens bringt es zum Fliehen; Schleudersteine verwandeln sich ihm in Spreu.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 41, 21, 'Wie ein Strohhalm kommt ihm die Keule vor, und nur ein Lächeln hat es für den Anprall der Lanze.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 41, 22, 'Seine Unterseite bilden spitze Scherben; einen breiten Dreschschlitten drückt es in den Schlamm ein.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 41, 23, 'Es macht die tiefe Wasserflut wie einen Kochtopf sieden, rührt das Meer auf wie einen Salbenkessel.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 41, 24, 'Hinter ihm her leuchtet sein Pfad: man könnte die Schaumflut für Silberhaar halten.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 41, 25, 'Auf Erden gibt es nicht seinesgleichen; es ist dazu geschaffen, sich nie zu fürchten.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 41, 26, 'Auf alles Hohe sieht es mit Verachtung hin: der König ist es über alle stolzen Tiere.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 42, 1, 'Da antwortete Hiob dem HERRN folgendermaßen:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 42, 2, '»Ich habe anerkannt, daß du alles vermagst und kein Vorhaben dir unausführbar ist.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 42, 3, '[›Wer ist’s, der da den Ratschluß Gottes verdunkelt ohne Einsicht?‹] So habe ich denn in Unverstand geurteilt über Dinge, die zu wunderbar für mich waren und die ich nicht verstand.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 42, 4, '[›Höre doch und laß mich reden! Ich will dich fragen, und du belehre mich!‹]');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 42, 5, 'Nur durch Hörensagen hatte ich von dir vernommen, jetzt aber hat mein Auge dich geschaut.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 42, 6, 'Darum bekenne ich mich schuldig und bereue in Staub und Asche.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 42, 7, 'Darauf, nachdem der HERR so zu Hiob gesprochen hatte, sagte der HERR zu Eliphas von Theman: »Entbrannt ist mein Zorn gegen dich und gegen deine beiden Freunde; denn ihr habt nicht richtig von mir geredet wie mein Knecht Hiob.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 42, 8, 'Darum holt euch nun sieben junge Stiere und sieben Widder, begebt euch zu meinem Knecht Hiob und bringt ein Brandopfer für euch dar! Mein Knecht Hiob soll dann Fürbitte für euch einlegen; denn nur aus Rücksicht auf ihn will ich euch eure Torheit nicht entgelten lassen, weil ihr nicht richtig von mir geredet habt wie mein Knecht Hiob.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 42, 9, 'Da gingen Eliphas von Theman, Bildad von Suah und Zophar von Naama hin und taten, wie der HERR ihnen geboten hatte; und der HERR nahm Rücksicht auf Hiob.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 42, 10, 'Der HERR stellte dann Hiobs Glücksstand wieder her, als er Fürbitte für seine Freunde eingelegt hatte; und der HERR vermehrte den ganzen Besitz Hiobs so, daß er doppelt so groß war als früher.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 42, 11, 'Da kamen alle seine Brüder und Schwestern und alle seine früheren Bekannten zu ihm; sie aßen mit ihm in seinem Hause, bezeigten ihm ihr Beileid und trösteten ihn wegen all des Unglücks, mit dem der HERR ihn heimgesucht hatte; auch schenkten sie ihm ein jeder ein wertvolles Geldstück und jeder einen goldenen Ring.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 42, 12, 'Der HERR aber segnete die nachfolgende Lebenszeit Hiobs noch mehr als seine frühere, so daß er es auf 14000 Stück Kleinvieh, 6000 Kamele, 1000 Joch Rinder und 1000 Eselinnen brachte.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 42, 13, 'Auch wurden ihm wieder sieben Söhne und drei Töchter geboren;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 42, 14, 'die eine nannte er Jemima, die andere Kezia, die dritte Keren-Happuch;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 42, 15, 'und man fand im ganzen Lande keine so schönen Frauen wie die Töchter Hiobs; und ihr Vater gab ihnen ein Erbteil unter ihren Brüdern. –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 42, 16, 'Danach lebte Hiob noch hundertundvierzig Jahre und sah seine Kinder und Kindeskinder, vier Geschlechter;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 42, 17, 'dann starb Hiob alt und lebenssatt.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 1, 1, 'Wohl dem, der nicht wandelt im Rat der Gottlosen und nicht tritt auf den Weg der Sünder, noch sitzt im Kreise der Spötter,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 1, 2, 'vielmehr Gefallen hat am Gesetz des HERRN und sinnt über sein Gesetz bei Tag und bei Nacht!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 1, 3, 'Der gleicht einem Baum, gepflanzt an Wasserbächen, der seine Früchte bringt zu rechter Zeit und dessen Laub nicht welkt; und alles, was er beginnt, das gelingt.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 1, 4, 'Nicht also die Gottlosen: nein, sie gleichen der Spreu, die der Wind verweht.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 1, 5, 'Darum werden die Gottlosen nicht im Gericht bestehn und die Sünder nicht in der Gemeinde der Gerechten.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 1, 6, 'Denn es kennt der HERR den Weg der Gerechten; doch der Gottlosen Weg führt ins Verderben.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 2, 1, 'Was soll das Toben der Völker und das eitle Sinnen der Völkerschaften?');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 2, 2, 'Die Könige der Erde rotten sich zusammen, und die Fürsten halten Rat miteinander gegen den HERRN und den von ihm Gesalbten:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 2, 3, '»Laßt uns zerreißen ihre Bande und von uns werfen ihre Fesseln!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 2, 4, 'Der im Himmel thront, der lacht, der Allherr spottet ihrer.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 2, 5, 'Dann aber wird er zu ihnen reden in seinem Zorn und sie schrecken in seinem Ingrimm:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 2, 6, '»Habe ich doch meinen König eingesetzt auf dem Zion, meinem heiligen Berge!« –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 2, 7, 'Laßt mich kundtun den Ratschluß des HERRN! Er hat zu mir gesagt: »Mein Sohn bist du; ich selbst habe heute dich gezeugt.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 2, 8, 'Fordre von mir, so gebe ich dir die Völker zum Erbe und dir zum Besitz die Enden der Erde.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 2, 9, 'Du sollst sie mit eiserner Keule zerschmettern, wie Töpfergeschirr sie zerschlagen!« –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 2, 10, 'So nehmt denn Klugheit an, ihr Könige, laßt euch warnen, ihr Richter der Erde!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 2, 11, 'Dienet dem HERRN mit Furcht und jubelt ihm zu mit Zittern!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 2, 12, 'Küsset den Sohn, auf daß er nicht zürne und ihr zugrunde geht auf eurem Wege! denn leicht entbrennt sein Zorn. Wohl allen, die bei ihm sich bergen!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 3, 1, 'Ein Psalm Davids, als er vor seinem Sohne Absalom floh.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 3, 2, 'Ach HERR, wie sind doch meine Bedränger so zahlreich, wie viele erheben sich gegen mich!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 3, 3, 'Gar viele sagen von mir: »Es gibt keine Rettung für ihn bei Gott!« SELA.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 3, 4, 'Doch du, o HERR, bist ein Schild um mich her, meine Ehre und der mir das Haupt erhebt.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 3, 5, 'Laut ruf’ ich zum HERRN, und er erhört mich von seinem heiligen Berge. SELA.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 3, 6, 'Ich legte mich nieder, schlief ruhig ein: erwacht bin ich wieder, denn der HERR stützt mich.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 3, 7, 'Ich fürchte mich nicht vor vielen Tausenden Kriegsvolks, die rings um mich her sich gelagert haben.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 3, 8, 'Steh auf, o HERR! Hilf mir, mein Gott! Du hast ja all meinen Feinden Backenstreiche versetzt, den Gottlosen die Zähne zerschmettert.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 3, 9, 'Beim HERRN steht die Hilfe: über deinem Volke walte dein Segen! SELA.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 4, 1, 'Dem Musikmeister, mit Saitenspiel; ein Psalm von David.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 4, 2, 'Wenn ich rufe, erhöre mich, du Gott meiner Gerechtigkeit! In Bedrängnis hast du mir (immer) Raum geschafft: sei mir gnädig und höre mein Gebet!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 4, 3, 'Ihr Herrensöhne, wie lange noch soll meine Ehre geschändet werden? Wie lange noch wollt ihr an Eitlem hangen, auf Lügen ausgehn? SELA.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 4, 4, 'Erkennt doch, daß der HERR den ihm Getreuen sich auserkoren: der HERR vernimmt’s, wenn ich zu ihm rufe.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 4, 5, 'Seid zornerregt, doch versündigt euch nicht! Denkt nach im stillen auf eurem Lager und schweigt! SELA.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 4, 6, 'Bringt Opfer der Gerechtigkeit dar und vertraut auf den HERRN!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 4, 7, 'Es sagen gar viele: »Wer läßt Gutes uns schauen?« Erhebe über uns, o HERR, das Licht deines Angesichts!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 4, 8, 'Du hast mir größere Freude ins Herz gegeben als ihnen zur Zeit, wo sie Korn und Wein in Fülle haben.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 4, 9, 'In Frieden will ich beides, mich niederlegen und schlafen; denn du allein, HERR, läßt mich in Sicherheit wohnen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 5, 1, 'Dem Musikmeister, nach (der Singweise = Melodie) »die Erbschaften«; ein Psalm von David.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 5, 2, 'Vernimm meine Worte, o HERR, merke auf mein Seufzen!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 5, 3, 'Ach, hör’ auf mein lautes Flehen, mein König und mein Gott; denn zu dir geht mein Gebet!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 5, 4, 'O HERR, in der Frühe schon hörst du mein Rufen, in der Frühe schon richte ich dir (ein Opfer) zu und spähe aus (nach dir).');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 5, 5, 'Du bist ja nicht ein Gott, dem gottlos Wesen gefällt: kein Böser darf als Gast bei dir weilen;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 5, 6, 'Ruhmredige dürfen dir nicht vor die Augen treten: du hassest alle Übeltäter.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 5, 7, 'Du läßt die Lügner zugrunde gehn; wer mit Blutvergießen und Trug sich befaßt, den verabscheut der HERR.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 5, 8, 'Ich aber darf nach deiner großen Gnade dein Haus betreten, ich darf vor deinem heiligen Tempel in Ehrfurcht vor dir mich niederwerfen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 5, 9, 'HERR, leite mich in deiner Gerechtigkeit um meiner Feinde willen, ebne vor mir deinen Weg!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 5, 10, 'Denn in ihrem Mund ist keine Aufrichtigkeit, ihr Inneres ist Bosheit; ein offnes Grab ist ihre Kehle, mit ihrer Zunge reden sie glatte Worte.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 5, 11, 'Laß sie büßen, o Gott, daß zu Fall sie kommen durch ihre Anschläge! Stoße sie weg von dir ob der Menge ihrer Frevel, denn sie haben dir Trotz geboten!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 5, 12, 'Dann werden alle sich freun, die auf dich vertrauen: allzeit werden sie jubeln, daß du sie beschirmst; und frohlocken werden alle über dich, die deinen Namen lieben.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 5, 13, 'Denn du, HERR, segnest den Gerechten, schirmst ihn mit (deiner) Gnade wie mit einem Schilde.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 6, 1, 'Dem Musikmeister, mit Saitenspiel, im Basston; ein Psalm von David.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 6, 2, 'HERR, nicht in deinem Zorne strafe mich und nicht in deinem Ingrimm züchtige mich!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 6, 3, 'Sei mir gnädig, o HERR, denn ich bin am Verschmachten! Heile mich, HERR, denn meine Gebeine sind erschrocken,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 6, 4, 'und meine Seele ist voller Angst! Du aber, o HERR, – wie lange noch (willst du fern sein)?');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 6, 5, 'Kehre doch wieder, o HERR, errette meine Seele! Hilf mir um deiner Gnade willen!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 6, 6, 'Denn im Tode gedenkt man deiner nicht: im Totenreich – wer singt da dein Lob?');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 6, 7, 'Erschöpft bin ich von all meinem Seufzen; in jeder Nacht netz’ ich mein Bett (mit Zähren), mache mein Lager zu einer Tränenflut.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 6, 8, 'Geschwunden ist mein Augenlicht vor Gram, gealtert (vom Weinen) ob all meinen Feinden.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 6, 9, 'Hinweg von mir, ihr Übeltäter alle! Denn der HERR hat mein lautes Weinen gehört;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 6, 10, 'gehört hat der HERR mein Flehen: der HERR nimmt mein Gebet an.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 6, 11, 'Alle meine Feinde werden zuschanden werden und ganz bestürzt dastehn: mit Schanden müssen sie abziehn augenblicklich!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 7, 1, 'Ein Bittgebet Davids, das er dem Herrn wegen der Worte des Benjaminiten Kusch sang.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 7, 2, 'HERR, mein Gott, bei dir such’ ich Zuflucht: hilf mir von allen meinen Verfolgern und rette mich,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 7, 3, 'daß der Feind mich nicht wie ein Löwe zerreiße und zerfleische, weil kein Retter da ist!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 7, 4, 'O HERR mein Gott! Hab’ ich solches verübt, klebt Unrecht an meinen Händen,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 7, 5, 'hab’ ich dem, der in Frieden mit mir lebte, Böses getan – ach nein, ich rettete ja, die mich grundlos bedrängten –:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 7, 6, 'so möge der Feind mich verfolgen und einholen, möge mein Leben zu Boden niedertreten und strecke meine Ehre in den Staub! SELA.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 7, 7, 'Steh auf, o HERR, in deinem Zorn! Erhebe dich gegen die Wut meiner Dränger! Werde wach mir zum Heil, du hast ja Gericht verordnet!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 7, 8, 'Laß die ganze Versammlung der Völker dich umringen, und über ihr kehre zurück zur Höhe!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 7, 9, 'Der HERR ist Richter über die Völker: schaffe mir Recht, o HERR, nach meiner Gerechtigkeit und nach meines Herzens Unschuld!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 7, 10, 'Mache der Gottlosen Bosheit ein Ende und hilf dem Gerechten zu festem Stand, du Prüfer der Herzen und Nieren, gerechter Gott!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 7, 11, 'Meinen Schild hält Gott, der Helfer der in ihrem Herzen Redlichen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 7, 12, 'Gott ist ein gerechter Richter und ein Gott, der täglich droht.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 7, 13, 'Wahrlich, wiederum schärft er sein Schwert, hält seinen Bogen gespannt und zielt');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 7, 14, 'und richtet Todesgeschosse auf ihn, seine Pfeile, die er zu Brandpfeilen macht.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 7, 15, 'Seht: da brütet er über Trug, geht schwanger mit Unheil und gebiert Lüge;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 7, 16, 'eine Grube hat er gegraben und ausgescharrt, stürzt selbst aber in die Grube, die er angelegt.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 7, 17, 'Das Unheil, das er geplant, fällt ihm aufs eigne Haupt, sein Frevel fährt auf seinen eignen Scheitel nieder.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 7, 18, 'Preisen will ich den HERRN nach seiner Gerechtigkeit und lobsingen dem Namen des HERRN, des Höchsten.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 8, 1, 'Dem Musikmeister, nach der Keltertreterweise; ein Psalm von David.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 8, 2, 'HERR, unser Herrscher, wie herrlich ist dein Name auf der ganzen Erde, du, dessen Hoheit am Himmel sich kundtut!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 8, 3, 'Aus der Kinder und Säuglinge Mund hast du ein Bollwerk dir zugerichtet deinen Gegnern zum Trotz, um Feinde und Widersacher verstummen zu machen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 8, 4, 'Wenn ich anschau’ deinen Himmel, das Werk deiner Finger, den Mond und die Sterne, die du hergerichtet:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 8, 5, 'was ist der Mensch, daß du seiner gedenkst, und der Menschensohn, daß du ihn beachtest?!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 8, 6, 'Und doch hast du ihn nur wenig hinter die Gottheit gestellt, mit Herrlichkeit und Hoheit ihn gekrönt;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 8, 7, 'du hast ihm die Herrschaft verliehn über deiner Hände Werke, ja alles ihm unter die Füße gelegt:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 8, 8, 'Kleinvieh und Rinder allzumal, dazu auch die wilden Tiere des Feldes,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 8, 9, 'die Vögel des Himmels, die Fische im Meer, alles, was die Pfade der Meere durchzieht.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 8, 10, 'HERR, unser Herrscher, wie herrlich ist dein Name auf der ganzen Erde!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 9, 1, 'Dem Musikmeister, nach (der Singweise = Melodie) »stirb für den Sohn!«; ein Psalm von David.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 9, 2, 'Preisen will ich den HERRN von ganzem Herzen, verkünden all deine Wundertaten,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 9, 3, 'ich will deiner mich freun und frohlocken, will lobsingen deinem Namen, du Höchster,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 9, 4, 'weil meine Feinde haben rückwärts weichen müssen: sie sind gestrauchelt und umgekommen vor dir.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 9, 5, 'Denn du hast mein Recht und meine Sache geführt, hast auf dem Throne gesessen als gerechter Richter;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 9, 6, 'du hast die Heiden bedroht, die Frevler vernichtet, ihren Namen ausgelöscht für immer und ewig:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 9, 7, 'Der Feind ist dahin, zertrümmert für immer; auch Städte hast du zerstört, ihr Gedächtnis ist untergegangen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 9, 8, 'Der HERR aber thront in Ewigkeit; zum Gericht hat er aufgestellt seinen Stuhl;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 9, 9, 'und er, er richtet den Erdkreis mit Gerechtigkeit, spricht das Urteil den Völkern nach Gebühr.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 9, 10, 'So ist denn der HERR eine Burg den Bedrückten, eine Burg für die Zeiten der Drangsal.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 9, 11, 'Drum vertrauen auf dich, die deinen Namen kennen; denn du läßt nicht von denen, die dich, HERR, suchen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 9, 12, 'Lobsinget dem HERRN, der auf Zion thront, verkündet unter den Völkern seine Taten!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 9, 13, 'Denn als Rächer der Blutschuld hat er ihrer gedacht, hat das Schreien der Elenden nicht vergessen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 9, 14, 'Sei mir gnädig, o HERR, sieh an, was ich leide durch meine Feinde! Du bist’s, der den Pforten des Todes mich entreißt,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 9, 15, 'auf daß ich verkünde alle deine Ruhmestaten, in den Toren der Tochter Zion ob deiner Hilfe juble!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 9, 16, 'Versunken sind die Heiden in die Grube, die sie gegraben, im Netz, das sie heimlich gestellt, hat ihr eigner Fuß sich verstrickt.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 9, 17, 'Kundgetan hat sich der HERR, hat Gericht gehalten: durch das Eingreifen seiner Hände ist der Frevler gefangen. SAITENSPIEL. SELA.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 9, 18, 'Die Frevler fahren zur Unterwelt hinab, alle Heidenvölker, die Gottes vergessen;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 9, 19, 'denn nicht auf ewig bleibt der Arme vergessen, und der Elenden Hoffnung geht nicht für immer verloren.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 9, 20, 'Steh auf, o HERR! Laß Menschen nicht trotzig schalten, laß die Heiden gerichtet werden vor dir!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 9, 21, 'Lege doch, HERR, einen Schrecken auf sie! Laß die Heiden erkennen, daß Menschen sie sind! SELA.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 10, 1, 'Warum, o HERR, stehst du so fern, verhüllst dir (das Auge) in Zeiten der Not?');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 10, 2, 'Beim Hochmut der Gottlosen wird dem Bedrückten bange: möchten sie selbst sich fangen in den Anschlägen, die sie ersinnen!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 10, 3, 'Denn der Frevler rühmt sich jubelnd seiner frechen Gelüste, und der Wucherer gibt dem HERRN den Abschied, lästert ihn.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 10, 4, 'Der Frevler wähnt in seinem Stolz: »Gott fragt nicht danach!« »Es gibt keinen Gott!« – dahin geht all sein Denken.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 10, 5, 'Allezeit hat er ja Glück in seinem Tun, deine Strafgerichte bleiben himmelweit fern von ihm, alle seine Gegner – er bietet ihnen Hohn.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 10, 6, 'Er denkt im Herzen: »Nie komm’ ich zu Fall; nun und nimmer wird Unglück mich treffen!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 10, 7, 'Sein Mund ist voll Fluchens, voll Täuschung und Gewalttat; unter seiner Zunge birgt sich Unheil und Frevel.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 10, 8, 'In (abgelegnen) Gehöften liegt er im Hinterhalt, ermordet den Schuldlosen insgeheim, nach dem Hilflosen spähen seine Augen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 10, 9, 'Er lauert im Versteck wie der Löwe in seinem Dickicht, er lauert, den Elenden zu haschen; er hascht den Elenden, indem er ihn in sein Netz zieht;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 10, 10, 'er duckt sich, kauert nieder, und die Hilflosen fallen ihm in die Klauen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 10, 11, 'Er denkt in seinem Herzen: »Gott hat’s vergessen, hat sein Antlitz verhüllt: er sieht es nimmer!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 10, 12, 'Steh auf, o HERR, erhebe, o Gott, deinen Arm, vergiß die Elenden nicht!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 10, 13, 'Warum darf der Frevler Gott lästern, darf denken in seinem Herzen: »Du fragst nicht danach«?');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 10, 14, 'Du hast es wohl gesehn, denn auf Unheil und Herzeleid achtest du wohl, in deine Hand es zu nehmen; du bist’s, dem der Schwache es anheimstellt, der Waise bist du ein Helfer.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 10, 15, 'Zerschmettre den Arm des Frevlers und suche des Bösewichts gottloses Wesen heim, bis nichts mehr von ihm zu finden!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 10, 16, 'Der HERR ist König auf immer und ewig: verschwinden müssen die Heiden aus seinem Lande!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 10, 17, 'Das Verlangen der Elenden hörst du, o HERR; du stärkst ihren Mut, leihst ihnen dein Ohr,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 10, 18, 'um den Waisen und Bedrückten Recht zu schaffen: nicht soll ein Mensch, der zur Erde gehört, noch ferner schrecken.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 11, 1, 'Dem Musikmeister, von David. Der HERR ist meine Zuflucht; wie dürft ihr zu mir sagen: »Fliehet in euer Gebirge wie Vögel!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 11, 2, 'Denn seht, die Gottlosen spannen den Bogen, legen ihren Pfeil auf die Sehne, um im Dunkel zu schießen auf schuldlose Herzen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 11, 3, 'Wenn die Grundpfeiler niedergerissen werden, – was kann da der Gerechte noch leisten?«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 11, 4, 'Der HERR ist in seinem heiligen Palast, der HERR, dessen Thron im Himmel steht; seine Augen halten Ausschau, seine Blicke prüfen die Menschenkinder.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 11, 5, 'Es prüft der HERR den Gerechten und den Gottlosen, und wer Gewalttat liebt, den haßt seine Seele.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 11, 6, 'Er läßt auf die Gottlosen Schlingen regnen; Feuer und Schwefel und Glutwind sind ihres Bechers Teil (das ihnen zukommende Teil oder Los).');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 11, 7, 'Denn gerecht ist der HERR, ein Freund gerechten Tuns: die Redlichen werden sein Angesicht schauen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 12, 1, 'Dem Musikmeister, im Basston; ein Psalm von David.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 12, 2, 'Hilf doch, o HERR! Denn dahin sind die Frommen und die Treuen ausgestorben inmitten der Menschenwelt!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 12, 3, 'Falschheit reden sie jeder mit dem andern, mit glatten Lippen, mit doppeltem Herzen reden sie. –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 12, 4, 'O daß doch der HERR vertilgte alle glatten Lippen, die Zunge, die vermessen redet,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 12, 5, '(die Leute) die da sagen: »Durch unsre Zunge sind wir starke Helden, unser Mund steht uns zur Verfügung: wer will uns meistern?«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 12, 6, '»Ob der Knechtung der Niedrigen, ob dem Seufzen der Armen will jetzt ich mich erheben«, spricht der HERR, »will Rettung schaffen dem, der danach verlangt!« –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 12, 7, 'Die Worte des HERRN sind lautere Worte, sind Silber, im Schmelzofen siebenfältig geläutert.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 12, 8, 'Du, HERR, wirst treulich sie halten, wirst uns schirmen vor diesem Geschlecht zu jeder Zeit,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 12, 9, 'vor den Gottlosen, die ringsum stolzieren, weil Gemeinheit sich bläht inmitten der Menschheit.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 13, 1, 'Dem Musikmeister; ein Psalm Davids.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 13, 2, 'Wie lange noch, HERR, willst du mich ganz vergessen, wie lange dein Antlitz vor mir verhüllen?');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 13, 3, 'Wie lange noch soll ich Sorgen hegen in meiner Seele, Kummer im Herzen tragen Tag für Tag? Wie lange noch soll mein Feind sich gegen mich erheben?');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 13, 4, 'Blick her, erhöre mich, HERR, mein Gott, laß die Augen mir wieder leuchten, daß zum Tode ich nicht entschlafe!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 13, 5, 'Sonst rühmt sich mein Feind: »Ich habe ihn überwältigt!«, und meine Gegner jubeln, wenn ich wanke.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 13, 6, 'Doch nein, ich vertraue deiner Gnade: jauchzen soll mein Herz ob deiner Hilfe! Singen will ich dem HERRN, daß er Gutes an mir getan!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 14, 1, 'Dem Musikmeister, von David. Die Toren sprechen in ihrem Herzen: »Es gibt keinen Gott«; verderbt, abscheulich ist ihr Tun: da ist keiner, des Gutes täte.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 14, 2, 'Der HERR schaut hernieder vom Himmel aus nach den Menschenkindern, um zu sehn, ob da sei ein Verständiger, einer der nach Gott fragt.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 14, 3, 'Doch alle sind sie abgefallen, insgesamt entartet; da ist keiner, der Gutes tut, auch nicht einer.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 14, 4, 'Haben denn keinen Verstand die Übeltäter alle, die mein Volk verzehren – die das Brot des HERRN wohl essen, doch ohne ihn anzurufen?');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 14, 5, 'Damals gerieten sie in Angst und Schrecken, denn Gott war mit dem gerechten Geschlecht.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 14, 6, 'Beim Anschlag gegen den Elenden werdet zuschanden ihr werden, denn der HERR ist seine Zuflucht.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 14, 7, 'O daß doch aus Zion die Rettung Israels käme! Wenn der HERR einst wendet das Schicksal seines Volkes, wird Jakob jubeln, Israel sich freuen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 15, 1, 'Ein Psalm von David. HERR, wer darf Gast sein in deinem Zelte, wer wohnen auf deinem heiligen Berge?');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 15, 2, 'Wer unsträflich wandelt und Gerechtigkeit übt und die Wahrheit redet, wie’s ihm ums Herz ist;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 15, 3, 'wer keine Verleumdung mit seiner Zunge umherträgt, seinem Nächsten kein Unrecht zufügt und keine Schmähung ausspricht gegen Verwandte;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 15, 4, 'wer Verworfne als wirklich verächtlich ansieht, aber Gottesfürchtigen Ehre erweist; wer sich selbst zum Schaden schwört und den Eid doch hält;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 15, 5, 'wer sein Geld nicht ausleiht gegen Zins und Bestechung nicht annimmt gegen Schuldlose: wer solches tut, wird ewiglich nicht wanken.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 16, 1, 'Ein Lied von David. Behüte mich, Gott, denn bei dir such’ ich Zuflucht!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 16, 2, 'Ich sage zu Gott: »Mein Allherr bist du, es gibt nichts Gutes für mich außer dir«;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 16, 3, 'und von den Heiligen im Lande (sag ich): »Dies sind die Edlen, an denen mein ganzes Herz hängt.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 16, 4, 'Vielfaches Leid erwächst den Verehrern anderer (Götter): ich mag ihre Bluttrankopfer nicht spenden und ihre Namen nicht auf meine Lippen nehmen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 16, 5, 'Der HERR ist mein Erbgut und Becherteil; du bist’s, der mein Los mir sichert.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 16, 6, 'Die Meßschnur ist mir gefallen aufs lieblichste ja, mein Erbteil gefällt mir gar wohl.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 16, 7, 'Ich preise den HERRN, der mich freundlich beraten; auch nächtens mahnt mich mein Herz dazu.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 16, 8, 'Ich habe den HERRN mir beständig vor Augen gestellt: steht er mir zur Rechten, so wanke ich nicht.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 16, 9, 'Drum freut sich mein Herz, und meine Seele frohlockt: auch mein Leib wird sicher wohnen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 16, 10, 'Denn du gibst meine Seele dem Totenreich nicht preis, du läßt deinen Frommen nicht schaun die Vernichtung.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 16, 11, 'Du weisest mir den Weg des Lebens: vor deinem Angesicht sind Freuden in Fülle und Segensgaben in deiner Rechten ewiglich.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 17, 1, 'Ein Gebet Davids. Höre, o HERR, die gerechte Sache, merk’ auf mein lautes Rufen, vernimm mein Gebet von Lippen ohne Trug!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 17, 2, 'Von dir soll das Urteil über mich ergehn: deine Augen sehen untrüglich.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 17, 3, 'Prüfst du mein Herz, siehst du nach mir bei Nacht, durchforschest du mich: du findest nichts Böses; mein Mund macht sich keines Vergehens schuldig.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 17, 4, 'Beim Treiben der Menschen hab’ ich nach deiner Lippen Wort gemieden die Pfade der Gewalttätigen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 17, 5, 'Meine Schritte haben sich fest an deine Bahnen gehalten, meine Tritte haben nicht gewankt.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 17, 6, 'Ich rufe zu dir, denn du erhörst mich, o Gott: neige dein Ohr mir zu, vernimm meine Rede!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 17, 7, 'Erweise mir deine Wundergnade, du Retter derer, die vor Widersachern Zuflucht suchen bei deiner Rechten!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 17, 8, 'Behüte mich wie den Stern im Auge, birg mich im Schatten deiner Flügel');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 17, 9, 'vor den Frevlern, die mir Gewalt antun, vor meinen Feinden, die voll Gier mich umringen!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 17, 10, 'Ihr gefühlloses Herz halten sie verschlossen, ihr Mund stößt vermessene Reden aus.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 17, 11, 'Auf Schritt und Tritt lauern sie jetzt uns auf, richten ihr Trachten darauf, uns zu Boden zu werfen;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 17, 12, 'sie gleichen dem Löwen, der gierig ist zu rauben, und dem jungen Leu, der da lauert im Versteck.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 17, 13, 'Erhebe dich, HERR, tritt ihm entgegen, strecke ihn nieder! Errette mein Leben mit deinem Schwert vor dem Frevler,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 17, 14, 'mit deiner Hand, o HERR, vor den Menschen, vor den Leuten dieser Welt, deren Teil im Leben ist! Mit deinem Aufgesparten fülle ihren Bauch! Mögen ihre Söhne satt daran werden und ihren Überrest wieder ihren Kindern hinterlassen!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 17, 15, 'Doch ich in Gerechtigkeit darf dein Angesicht schauen, darf satt mich sehn beim Erwachen an deinem Bilde.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 1, 'Dem Musikmeister; vom Knecht des Herrn, von David, der dieses Lied an den Herrn richtete zu der Zeit, als der Herr ihn aus der Hand aller seiner Feinde, auch aus der Gewalt Sauls errettet hatte. Er betete (damals) so:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 2, 'Ich liebe dich, HERR, meine Stärke!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 3, 'Der HERR ist mein Fels, meine Burg und mein Erretter, mein Gott ist mein Hort, bei dem ich Zuflucht suche, mein Schild und das Horn meines Heils, meine Feste.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 4, 'Den Preiswürdigen rufe ich an, den HERRN: so werd’ ich von meinen Feinden errettet.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 5, 'Die Wogen des Todes hatten mich umringt, und die Ströme des Unheils schreckten mich;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 6, 'die Netze des Totenreichs umfingen mich schon, die Schlingen des Todes fielen über mich.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 7, 'In meiner Angst rief ich zum HERRN und schrie (um Hilfe) zu meinem Gott; da vernahm er in seinem Palast mein Rufen, und mein Notschrei drang ihm zu Ohren.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 8, 'Da wankte und schwankte die Erde, und der Berge Grundfesten bebten, sie wankten hin und her, denn er war zornentbrannt.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 9, 'Rauch stieg auf von seiner Nase, und fressendes Feuer drang aus seinem Munde, glühende Kohlen sprühten von ihm aus.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 10, 'Er neigte den Himmel und fuhr herab, Wolkennacht lag unter seinen Füßen;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 11, 'er fuhr auf dem Cherub und flog daher und schoß herab auf den Fittichen des Sturms;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 12, 'Finsternis machte er zu seiner Hülle, rings um sich her zu seinem Gezelt Regendunkel, dichtes Gewölk;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 13, 'aus dem Glanz vor ihm her brachen durch seine Wolken Hagel und feurige Kohlen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 14, 'Dann donnerte der HERR im Himmel, der Höchste ließ seine Stimme erschallen;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 15, 'er schoß seine Pfeile ab und zerstreute sie, schleuderte Blitze und schreckte sie.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 16, 'Da wurden sichtbar die Tiefen des Meeres und aufgedeckt die Grundfesten der Erde vor deinem Schelten, o HERR, vor dem Zornesschnauben deiner Nase.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 17, 'Er streckte die Hand herab aus der Höhe, erfaßte mich, zog mich heraus aus den großen Fluten,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 18, 'entriß mich meinem starken Feinde und meinen Widersachern, die zu stark mir waren.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 19, 'Sie hatten mich überfallen an meinem Unglückstage; doch der HERR ward mir zur Stütze;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 20, 'er führte mich heraus auf weiten Raum, riß mich heraus, weil er Wohlgefallen an mir hatte.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 21, 'Der HERR hat mir gelohnt nach meiner Gerechtigkeit, nach der Reinheit meiner Hände mir vergolten;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 22, 'denn ich habe eingehalten die Wege des HERRN und bin von meinem Gott nicht treulos abgefallen;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 23, 'nein, alle seine Rechte haben mir vor Augen gestanden, und seine Gebote hab’ ich nicht von mir gewiesen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 24, 'So bin ich unsträflich vor ihm gewandelt und hab’ mich vor jeder Verschuldung gehütet;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 25, 'drum hat mir der HERR vergolten nach meiner Gerechtigkeit, nach der Reinheit meiner Hände, die seinen Augen sichtbar war.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 26, 'Gegen den Guten erweist du dich gütig, gegen den Redlichen zeigst du dich redlich,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 27, 'gegen den Reinen erweist du dich rein, doch gegen den Falschen zeigst du dich enttäuschend;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 28, 'denn du schaffst demütigen Leuten Hilfe, aber stolze Augen erniedrigst du.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 29, 'Ja, du läßt meine Leuchte hell scheinen; der HERR, mein Gott, macht meine Finsternis licht.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 30, 'Denn mit dir überrenne ich Feindesscharen, und mit meinem Gott überspringe ich Mauern.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 31, 'Dieser Gott – sein Walten ist vollkommen; die Worte des HERRN sind lauter, ein Schild ist er allen, die zu ihm sich flüchten.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 32, 'Denn wer ist Gott außer dem HERRN und wer ein Fels als nur unser Gott?,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 33, 'dieser Gott, der mit Kraft mich gegürtet und meinen Weg ohn’ Anstoß gemacht;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 34, 'der mir Füße verliehen den Hirschen gleich und mich sicher auf Bergeshöhen gestellt;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 35, 'der meine Hände streiten gelehrt, daß meine Arme den ehernen Bogen spannten.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 36, 'Du reichtest mir deinen schützenden Schild, deine Rechte stützte mich, und deine Gnade machte mich groß.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 37, 'Du schafftest weiten Raum meinen Schritten unter mir, und meine Knöchel wankten nicht.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 38, 'Ich verfolgte meine Feinde, holte sie ein und kehrte nicht um, bis ich sie vernichtet;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 39, 'ich zerschmetterte sie, daß sie nicht wieder aufstehn konnten: sie sanken unter meine Füße nieder.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 40, 'Und du gürtetest mich mit Kraft zum Streit, beugtest unter mich alle, die sich gegen mich erhoben;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 41, 'du triebst meine Feinde vor mir in die Flucht, und alle, die mich haßten, vernichtete ich:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 42, 'sie schrien um Hilfe – doch da war kein Helfer – zum HERRN – doch er hörte sie nicht;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 43, 'ich zermalmte sie wie Staub vor dem Winde, wie Kot auf den Gassen schüttete ich sie hin.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 44, 'Du hast mich aus den Kämpfen für (mein) Volk errettet, mich zum Oberhaupt von Völkern eingesetzt: Völker, die ich nicht kannte, dienen mir;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 45, 'aufs bloße Wort gehorchen sie mir, die Söhne des Auslands huldigen mir;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 46, 'die Söhne des Auslands sinken mutlos hin und kommen zitternd hervor aus ihren Schlössern.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 47, 'Der HERR lebt: gepriesen sei mein Hort! und erhaben ist der Gott meines Heils,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 48, 'der Gott, der mir Rache verliehen und die Völker unter meine Herrschaft gezwungen,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 49, 'der von meinen grimmen Feinden mich gerettet und über meine Widersacher mich erhöht, von dem Mann der Gewalttat mich befreit hat!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 50, 'Drum will ich dich preisen, HERR, unter den Völkern und deinem Namen lobsingen,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 51, 'dir, der seinem Könige großes Heil verleiht und Gnade an seinem Gesalbten übt, an David und seinem Hause ewiglich!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 19, 1, 'Dem Musikmeister; ein Psalm von David.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 19, 2, 'Die Himmel verkünden Gottes Herrlichkeit, und vom Werk seiner Hände erzählt die Feste.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 19, 3, 'Ein Tag ruft dem andern die Botschaft zu, und eine Nacht vermeldet der andern die Kunde.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 19, 4, 'Da ist keine Sprache, da sind keine Worte, unhörbar ist ihre Stimme;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 19, 5, 'und doch: durch alle Lande dringt ihr Schall und ihre Rede bis ans Ende des Erdkreises; der Sonne hat er dort ein Zelt gesetzt.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 19, 6, 'Und sie – wie ein Bräutigam tritt sie hervor aus ihrem Gemach, sie freut sich wie ein Held, zu durchlaufen die Bahn.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 19, 7, 'Vom Ende des Himmels geht sie aus, und ihr Umlauf reicht wieder bis zu dessen Ende, und nichts bleibt verborgen vor ihrer Lichtglut. –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 19, 8, 'Das Gesetz des HERRN ist vollkommen: erquickt die Seele; das Zeugnis des HERRN ist zuverlässig: macht die Törichten weise;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 19, 9, 'die Befehle des HERRN sind richtig: erfreuen das Herz; das Gebot des HERRN ist lauter: erleuchtet die Augen;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 19, 10, 'die Furcht vor dem HERRN ist rein: bleibt ewig bestehn; die Gerichtsurteile des HERRN sind Wahrheit: sind allzumal gerecht;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 19, 11, 'sie sind köstlicher als Gold und als Feingold in Menge, sind süßer als Honig und Wabenseim.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 19, 12, 'Auch dein Knecht läßt durch sie sich warnen: in ihrer Befolgung liegt ein reicher Lohn.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 19, 13, 'Verfehlungen – ach, wer nimmt sie wahr? Von den unbewußten Fehlern sprich mich los!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 19, 14, 'Auch vor Hochmutssünden behüte deinen Knecht: laß sie nicht Macht über mich gewinnen! Dann steh’ ich unsträflich da und bleibe rein von schwerer Verschuldung.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 19, 15, 'Laß wohlgefällig dir sein die Worte meines Mundes und das Sinnen meines Herzens, o HERR, mein Fels und mein Erlöser!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 20, 1, 'Dem Musikmeister; ein Psalm von David.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 20, 2, 'Der HERR erhöre dich am Tage der Drangsal, es schütze dich der Name des Gottes Jakobs!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 20, 3, 'Er sende dir Hilfe vom Heiligtum her und leiste dir Beistand von Zion aus!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 20, 4, 'Er gedenke aller deiner Speisopfer und sehe dein Brandopfer wohlgefällig an! SELA.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 20, 5, 'Er gewähre dir, was dein Herz begehrt, und lasse all deine Pläne gelingen!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 20, 6, 'Dann wollen wir jubeln ob deinem Heil und im Namen unsers Gottes die Fahnen entfalten: der HERR erfülle dir all deine Wünsche! –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 20, 7, 'Jetzt weiß ich, der HERR hilft seinem Gesalbten: er erhört ihn aus seinem heiligen Himmel durch die hilfreichen Taten seiner Rechten.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 20, 8, 'Diese sind stark durch Wagen und jene durch Rosse, doch wir sind stark durch den Namen des HERRN, unsers Gottes.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 20, 9, 'Sie stürzen nieder und fallen, doch wir stehn fest und halten uns aufrecht.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 20, 10, 'O HERR, hilf dem König! Erhör’ uns, sooft wir (dich) anrufen!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 21, 1, 'Dem Musikmeister; ein Psalm von David.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 21, 2, 'O HERR, ob deiner Kraft freut sich der König, und ob deiner Hilfe – wie jauchzt er so laut!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 21, 3, 'Seines Herzens Verlangen hast du ihm erfüllt und den Wunsch seiner Lippen ihm nicht versagt; SELA.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 21, 4, 'denn mit Glück und Segen bist du ihm begegnet, hast aufs Haupt ihm gesetzt eine Krone von Feingold.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 21, 5, 'Leben erbat er von dir: du hast’s ihm gewährt, der Jahre Fülle auf endlose Zeit.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 21, 6, 'Groß ist sein Ruhm durch deine Hilfe, mit Glanz und Hoheit hast du ihn geschmückt;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 21, 7, 'für die Dauer hast du ihn zum Segen gemacht, ihn beglückt mit Freude vor deinem Angesicht.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 21, 8, 'Denn der König vertraut auf den HERRN und wird durch des Höchsten Gnade nicht wanken.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 21, 9, 'Deine Hand wird treffen alle deine Feinde, deine Rechte alle erreichen, die dich hassen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 21, 10, 'Du wirst sie wie einen Feuerofen machen, sobald du erscheinst; der HERR wird sie verschlingen in seinem Zorn, und Feuer wird sie verzehren.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 21, 11, 'Ihren Nachwuchs wirst du vom Erdboden tilgen und ihr Geschlecht aus der Menschenwelt.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 21, 12, 'Wenn Böses sie gegen dich planen, auf Arglist sinnen: sie werden nichts vermögen;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 21, 13, 'denn du wirst sie zwingen, die Flucht zu ergreifen, mit deinem Bogen auf ihr Antlitz zielen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 21, 14, 'Erhebe dich, HERR, in deiner Kraft: wir wollen dein Heldentum besingen und preisen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 22, 1, 'Dem Musikmeister, nach (der Singweise = Melodie) »Hirschkuh der Morgenröte«; ein Psalm von David.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 22, 2, 'Mein Gott, mein Gott, warum hast du mich verlassen? Ach, fern von meiner Rettung bleiben die Worte meiner Klage!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 22, 3, 'Mein Gott! Ich rufe bei Tage, doch du antwortest nicht, und bei Nacht, doch Ruhe wird mir nicht zuteil!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 22, 4, 'Und doch bist du der Heilige, der da thront über Israels Lobgesängen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 22, 5, 'Auf dich haben unsre Väter vertraut, sie haben vertraut, und du hast ihnen ausgeholfen;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 22, 6, 'zu dir haben sie geschrien und Rettung gefunden, auf dich haben sie vertraut und sind nicht enttäuscht worden.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 22, 7, 'Doch ich bin ein Wurm und kein Mensch mehr, bin der Leute Hohn und verachtet vom Volk;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 22, 8, 'alle, die mich sehen, spotten mein, reißen den Mund auf, schütteln den Kopf:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 22, 9, '»Er werf’s auf den HERRN: der möge ihn befreien, der möge ihn retten: er hat ja Wohlgefallen an ihm!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 22, 10, 'Ja du bist’s, der mich der Mutter gelegt in den Schoß, mich sicher geborgen an meiner Mutter Brust;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 22, 11, 'von Geburt an bin ich auf dich geworfen, vom Schoß meiner Mutter her bist du mein Gott.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 22, 12, 'O bleibe nicht fern von mir, denn die Drangsal ist nahe, und sonst ist kein Helfer zu sehen!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 22, 13, 'Mich umzingeln mächtige Stiere, Basans Riesenfarren halten mich umringt;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 22, 14, 'den Rachen sperren sie gegen mich auf – ein reißender, brüllender Löwe!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 22, 15, 'Wie Wasser bin ich ausgegossen, alle meine Glieder sind ausgerenkt; das Herz ist mir geworden wie Wachs, zerschmolzen in meinem Innern.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 22, 16, 'Vertrocknet wie eine Scherbe ist meine Kraft, und die Zunge klebt mir am Gaumen: in den Staub des Todes hast du mich gelegt.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 22, 17, 'Ach, Hunde umgeben mich rings, eine Rotte von Übeltätern umkreist mich; sie haben mir Hände und Füße durchbohrt.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 22, 18, 'Alle meine Gebeine kann ich zählen: sie aber blicken mich an und weiden sich an dem Anblick.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 22, 19, 'Sie teilen meine Kleider unter sich und werfen das Los um mein Gewand.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 22, 20, 'Doch du, HERR, bleibe nicht fern von mir, du, meine Stärke, eile mir zu Hilfe!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 22, 21, 'Errette vor dem Schwert mein Leben, mein einziges Gut aus der Hunde Gewalt!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 22, 22, 'Hilf mir aus dem Rachen des Löwen und bewahre mich vor den Hörnern der Büffel!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 22, 23, 'Dann will ich deinen Namen meinen Brüdern kundtun, inmitten der Gemeinde dich rühmen:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 22, 24, '»Die den HERRN ihr fürchtet, preiset ihn! Ihr alle vom Hause Jakobs, ehret ihn und scheut euch vor ihm, ihr alle von Israels Stamm!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 22, 25, 'Denn er hat nicht übersehen und nicht verabscheut das Elend des Dulders und sein Antlitz vor ihm nicht verborgen, nein, als er zu ihm schrie, auf ihn gehört.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 22, 26, 'Dir soll mein Loblied gelten in großer Gemeinde; meine Gelübde will ich erfüllen vor denen, die ihn fürchten.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 22, 27, 'Die Elenden sollen essen, daß sie satt werden, und die da suchen den HERRN, sollen ihn preisen: aufleben soll euer Herz für immer!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 22, 28, 'Daran werden gedenken und zum HERRN sich bekehren alle Enden der Erde, und vor dir werden sich niederwerfen alle Geschlechter der Heiden;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 22, 29, 'denn dem HERRN gehört die Herrschaft, und er ist der Völkergebieter.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 22, 30, 'Vor ihm werden niederfallen alle Großen der Erde, vor ihm die Knie beugen alle, die in den Erdstaub sinken und wer seine Seele nicht am Leben erhalten kann.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 22, 31, 'Die Nachwelt wird ihm dienen; vom Allherrn wird man erzählen dem künft’gen Geschlecht.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 22, 32, 'Sie werden kommen und seine Gerechtigkeit kundtun dem nachgeborenen Volk, daß Er es vollführt hat.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 23, 1, 'Ein Psalm von David. Der HERR ist mein Hirt: mir mangelt nichts.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 23, 2, 'Auf grünen Auen läßt er mich lagern, zum Lagerplatz am Bache führt er mich.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 23, 3, 'Er erquickt meine Seele; er leitet mich auf rechten Pfaden um seines Namens willen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 23, 4, 'Müßt’ ich auch wandern in finsterm Tal: ich fürchte kein Unglück, denn du bist bei mir: dein Hirtenstab und dein Stecken, die sind mein Trost.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 23, 5, 'Du deckst mir reichlich den Tisch vor den Augen meiner Feinde; du salbst mir das Haupt mit Öl und schenkst mir den Becher voll ein.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 23, 6, 'Nur Gutes und Liebes werden mich begleiten mein ganzes Leben hindurch, und heimkehren werd’ ich zum Hause des HERRN für eine lange Reihe von Tagen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 24, 1, 'Von David, ein Psalm. Dem HERRN gehört die Erde und ihre Fülle, der Erdkreis und seine Bewohner;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 24, 2, 'denn er hat auf Meeren sie gegründet und über Strömen sie festgestellt.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 24, 3, 'Wer darf hinaufgehn zum Berge des HERRN, wer stehen an seiner heiligen Stätte?');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 24, 4, 'Wer schuldlos ist an Händen und reinen Herzens, wer nie den Sinn auf Täuschung richtet, und wer nicht betrügerisch schwört:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 24, 5, 'der wird Segen empfangen vom HERRN und Gerechtigkeit vom Gott seines Heils.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 24, 6, 'Dies ist das Geschlecht, das nach ihm verlangt, die dein Angesicht suchen, Gott Jakobs. SELA.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 24, 7, 'Hebt hoch, ihr Tore, eure Häupter und öffnet euch weit, ihr uralten Pforten, daß der König der Herrlichkeit einziehe!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 24, 8, '»Wer ist denn der König der Herrlichkeit?« Der HERR, gar stark und ein Held, der HERR, ein Held in der Schlacht!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 24, 9, 'Hebt hoch, ihr Tore, eure Häupter und öffnet euch weit, ihr uralten Pforten, daß der König der Herrlichkeit einziehe!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 24, 10, '»Wer ist denn der König der Herrlichkeit?« Der HERR der Heerscharen, der ist der König der Herrlichkeit! SELA.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 25, 1, 'Von David. Zu dir, o HERR, erheb’ ich meine Seele,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 25, 2, 'mein Gott, auf dich vertraue ich: laß mich nicht enttäuscht werden, laß meine Feinde nicht über mich frohlocken!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 25, 3, 'Nein, keiner, der auf dich harrt, wird enttäuscht; enttäuscht wird nur, wer dich treulos verläßt. –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 25, 4, 'Tu mir kund, o HERR, deine Wege, deine Pfade lehre mich!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 25, 5, 'Laß mich wandeln in deiner Wahrheit und lehre mich, denn du bist der Gott meines Heils: deiner harre ich allezeit. –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 25, 6, 'Gedenke der Erweise deines Erbarmens, o HERR, und daß deine Gnadenverheiße aus der Urzeit stammen;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 25, 7, 'gedenke nicht der Sünden meiner Jugend und meiner Vergehen: nein, nach deiner Gnade gedenke meiner um deiner Güte willen!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 25, 8, 'Gütig und aufrichtig ist der HERR; darum weist er den Sündern den rechten Weg,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 25, 9, 'läßt Bedrückte wandeln in richtiger Weise und lehrt die Dulder seinen Weg.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 25, 10, 'Alle Pfade des HERRN sind Gnade und Treue denen, die seinen Bund und seine Gebote halten.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 25, 11, 'Um deines Namens willen, o HERR, vergib mir meine Schuld, denn sie ist groß! –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 25, 12, 'Wie steht’s mit dem Mann, der den HERRN fürchtet? Dem zeigt er den Weg, den er wählen soll.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 25, 13, 'Er selbst wird wohnen im Glück, und seine Kinder werden das Land besitzen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 25, 14, 'Freundschaft hält der HERR mit denen, die ihn fürchten, und sein Bund will zur Erkenntnis sie führen. –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 25, 15, 'Meine Augen sind stets auf den HERRN gerichtet, denn er wird meine Füße aus dem Netze ziehn.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 25, 16, 'Wende dich mir zu und sei mir gnädig! Denn einsam bin ich und elend.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 25, 17, 'Die Ängste meines Herzens sind schwer geworden: o führ’ mich heraus aus meinen Nöten!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 25, 18, 'Sieh mein Elend an und mein Ungemach und vergib mir alle meine Sünden! –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 25, 19, 'Sieh meine Feinde an, wie viele ihrer sind und wie sie mich hassen mit frevlem Haß.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 25, 20, 'Behüte meine Seele und rette mich, nicht enttäuscht laß mich werden: ich traue auf dich!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 25, 21, 'Unschuld und Redlichkeit mögen mich behüten, denn ich harre deiner, o HERR! –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 25, 22, 'O Gott, erlöse Israel aus allen seinen Nöten!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 26, 1, 'Von David. Schaffe mir Recht, o HERR, denn ich bin gewandelt in meiner Unschuld und habe vertraut auf den HERRN ohne Wanken!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 26, 2, 'Prüfe mich, HERR, und erprobe mich: meine Nieren und mein Herz sind geläutert!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 26, 3, 'Denn deine Gnade steht mir vor Augen, und ich wandle in deiner Wahrheit.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 26, 4, 'Ich sitze nicht bei falschen Menschen und verkehre nicht mit hinterlistigen Leuten;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 26, 5, 'ich meide die Versammlung der Missetäter und halte mich nicht zu den Gottlosen;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 26, 6, 'ich wasche in Unschuld meine Hände und schreite so um deinen Altar, o HERR,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 26, 7, 'daß ich laut ein Danklied erschallen lasse und alle deine Wundertaten verkünde.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 26, 8, 'O HERR, ich habe lieb die Stätte deines Hauses und den Ort, wo deine Herrlichkeit wohnt.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 26, 9, 'Raffe nicht weg meine Seele mit den (Seelen der) Sünder, noch mein Leben mit dem der Mordgesellen,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 26, 10, 'an deren Händen Verbrechen kleben und deren Rechte gefüllt ist mit Bestechung!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 26, 11, 'Ich aber wandle in meiner Unschuld: erlöse mich, HERR, und sei mir gnädig!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 26, 12, 'Mein Fuß steht fest auf ebenem Plan: in Versammlungen will ich preisen den HERRN.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 27, 1, 'Von David. Der HERR ist mein Licht und mein Heil: vor wem sollt’ ich mich fürchten? Der HERR ist meines Lebens Schutzwehr: vor wem sollte mir bangen?');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 27, 2, 'Wenn Übeltäter gegen mich anstürmen, mich zu zerfleischen, meine Widersacher und Feinde: sie straucheln und fallen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 27, 3, 'Mag ein Heer sich gegen mich lagern: mein Herz ist ohne Furcht; mag Krieg sich gegen mich erheben: trotzdem bleib’ ich getrost.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 27, 4, 'Nur eines erbitt’ ich vom HERRN, danach trag’ ich Verlangen: daß ich weilen möge im Hause des HERRN mein ganzes Leben hindurch, um anzuschauen die Huld des HERRN und der Andacht mich hinzugeben in seinem Tempel.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 27, 5, 'Denn er birgt mich in seiner Hütte am Tage des Unheils, beschirmt mich im Schirm seines Zeltes, hebt hoch mich auf einen Felsen empor.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 27, 6, 'So wird sich denn mein Haupt erheben über meine Feinde rings um mich her; und opfern will ich in seinem Zelte Schlachtopfer mit Jubelschall, will singen und spielen dem HERRN!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 27, 7, 'Höre mich, HERR, laut ruf’ ich zu dir! Ach sei mir gnädig, erhöre mich!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 27, 8, 'Mein Herz hält dein Gebot dir vor: »Ihr sollt mein Angesicht suchen!« Darum suche ich, o HERR, dein Angesicht.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 27, 9, 'Verbirg dein Angesicht nicht vor mir, weise nicht ab deinen Knecht im Zorn! Du bist meine Hilfe gewesen: verwirf mich nicht und verlaß mich nicht, du Gott meines Heils!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 27, 10, 'Wenn Vater und Mutter mich verlassen, so nimmt doch der HERR mich auf.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 27, 11, 'Lehre mich, HERR, deinen Weg und führe mich auf ebener Bahn um meiner Feinde willen!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 27, 12, 'Gib mich nicht preis der Gier meiner Dränger! Denn Lügenzeugen sind gegen mich aufgetreten und schnauben Gewalttat (gegen mich).');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 27, 13, 'Gott Lob! Ich bin gewiß, die Güte des HERRN zu schauen im Lande der Lebenden.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 27, 14, 'Harre des HERRN, sei getrost, und dein Herz sei unverzagt! Ja, harre des HERRN!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 28, 1, 'Von David. Zu dir, HERR, rufe ich: mein Fels, o wende dich nicht schweigend von mir ab, auf daß nicht, wenn du mir stumm bleibst, ich den ins Grab Gesunknen gleiche.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 28, 2, 'Höre mein lautes Flehen, wenn ich zu dir schreie, wenn ich meine Hände erhebe nach deinem Allerheiligsten!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 28, 3, 'Raffe mich nicht weg mit den Frevlern und den Übeltätern, die freundlich reden mit ihren Nächsten und dabei Arges im Herzen sinnen!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 28, 4, 'Vergilt du ihnen nach ihrem Tun, nach der Bosheit ihrer Handlungen, vergilt ihnen nach dem Werk ihrer Hände, zahl’ ihnen ihr Verhalten heim, wie sie’s verdienen!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 28, 5, 'Denn sie achten nicht auf das Walten des HERRN und das Werk seiner Hände; drum wird er sie niederreißen und nicht wieder aufbaun.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 28, 6, 'Gepriesen sei der HERR, denn er hat gehört meinen lauten Hilferuf!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 28, 7, 'Der HERR ist meine Stärke und mein Schild; auf ihn hat mein Herz vertraut, da ist mir Hilfe geworden. So frohlockt denn mein Herz, und mit meinem Liede will ich ihm danken.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 28, 8, 'Der HERR ist seines Volkes Stärke und seines Gesalbten rettende Zuflucht.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 28, 9, 'O hilf deinem Volk und segne dein Erbe, weide sie und trage sie ewiglich!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 29, 1, 'Ein Psalm von David. Bringt dar dem HERRN, ihr Gottessöhne, bringt dar dem HERRN Ehre und Preis!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 29, 2, 'Bringt dar dem HERRN die Ehre seines Namens, werft vor dem HERRN euch nieder in heiligem Schmuck!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 29, 3, 'Der Donner des HERRN rollt über dem Meer; der Gott der Herrlichkeit donnert, der HERR über weiter Meeresflut!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 29, 4, 'Der Donner des HERRN erschallt mit Macht, der Donner des HERRN in seiner Pracht!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 29, 5, 'Der Donner des HERRN zerschmettert die Zedern, ja der HERR zersplittert die Zedern des Libanons');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 29, 6, 'und läßt sie hüpfen wie Kälbchen, den Libanon und Sirjon wie junge Büffel.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 29, 7, 'Der Donner des HERRN läßt Feuerflammen sprühn;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 29, 8, 'der Donner des HERRN macht die Wüste erbeben, der HERR macht erbeben die Wüste Kades.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 29, 9, 'Der Donner des HERRN macht Hirschkühe kreißen, entästet die Wälder, und alles ruft in seinem Palast: »Ehre!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 29, 10, 'Der HERR hat über der Sintflut (einst) gethront, und als König thront der HERR in Ewigkeit.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 29, 11, 'Der HERR verleihe Kraft seinem Volk, der HERR wolle segnen sein Volk mit Frieden!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 30, 1, 'Ein Psalm, ein Lied zur Tempelweihe, von David.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 30, 2, 'Ich will dich erheben, o HERR, denn du hast aus der Tiefe mich gezogen und meinen Feinden die Freude über mich vereitelt.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 30, 3, 'O HERR, mein Gott, ich schrie zu dir (um Hilfe), da hast du mir Heilung geschafft.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 30, 4, 'O HERR, du hast meine Seele aus dem Totenreich heraufgeführt, hast mich am Leben erhalten, so daß ich nicht ins Grab bin gesunken.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 30, 5, 'Lobsinget dem HERRN, ihr seine Frommen, und preist seinen heiligen Namen!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 30, 6, 'Denn sein Zorn währt nur einen Augenblick, doch lebenslang seine Gnade: am Abend kehrt Weinen als Gast ein, doch am Morgen herrscht Jubel.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 30, 7, 'Ich aber dachte in meiner Sicherheit: »Ich werde nimmermehr wanken!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 30, 8, 'O HERR, nach deiner Gnade hattest du fest meinen Berg gegründet; dann aber verbargst du dein Antlitz, und ich erschrak.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 30, 9, 'Da rief ich zu dir, o HERR, und flehte zu meinem Gott:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 30, 10, '»Was hast du für Gewinn von meinem Blut, wenn zur Gruft ich fahre? Kann der Staub dich preisen und deine Treue verkünden?');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 30, 11, 'O höre mich, HERR, und erbarme dich mein, sei du, o HERR, ein Helfer!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 30, 12, 'Du hast mir meine Klage in Reigentanz verwandelt, das Trauerkleid mir gelöst und mit Freude mich gegürtet,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 30, 13, 'auf daß dir meine Seele lobsinge und nicht schweige: o HERR, mein Gott, in Ewigkeit will ich dir danken!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 31, 1, 'Dem Musikmeister; ein Psalm von David.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 31, 2, 'Bei dir, HERR, suche ich Zuflucht: laß mich nimmer enttäuscht werden! Nach deiner Gerechtigkeit errette mich!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 31, 3, 'Neige dein Ohr mir zu, eile zu meiner Rettung herbei, sei mir ein schützender Fels, eine feste Burg, mir zu helfen!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 31, 4, 'Du bist ja doch mein Fels und meine Burg, um deines Namens willen wirst du mich führen und leiten,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 31, 5, 'mich befrein aus dem Netz, das man heimlich mir gestellt; denn du bist meine Schutzwehr.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 31, 6, 'In deine Hand befehl’ ich meinen Geist: du wirst mich erlösen, o HERR, du treuer Gott.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 31, 7, 'Du hassest, die sich an nichtige Götzen halten, doch ich vertraue auf den HERRN.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 31, 8, 'Ich will jubeln und fröhlich sein ob deiner Gnade, daß du mein Elend hast angeschaut, auf die Angst meiner Seele geachtet');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 31, 9, 'und mich der Gewalt des Feindes nicht preisgegeben, nein, meine Füße gestellt hast auf weiten Raum.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 31, 10, 'Sei mir gnädig, o HERR, denn ich bin in Bedrängnis; getrübt vor Gram ist mir mein Auge, meine Seele und mein Leib;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 31, 11, 'denn in Kummer verzehrt sich mein Leben und meine Jahre in Seufzen; erschöpft durch mein Verschulden ist meine Kraft, und verfallen sind meine Gebeine.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 31, 12, 'Für alle meine Feinde bin ich zum Hohn geworden, von meinen Nachbarn gemieden und ein Schrecken für meine Bekannten: wer mich sieht auf der Straße, flieht scheu vor mir.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 31, 13, 'Entschwunden bin ich wie ein Toter dem Gedenken, bin geworden wie ein zerbrochnes Gefäß.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 31, 14, 'Ich habe ja viele zischeln gehört: »Grauen ringsum!« Wenn sie vereint sich gegen mich beraten, sinnen sie darauf, mir das Leben zu rauben.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 31, 15, 'Doch ich vertraue auf dich, o HERR; ich sage: »Nur du bist mein Gott.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 31, 16, 'In deiner Hand steht meine Zeit: rette mich aus der Hand meiner Feinde und meiner Verfolger!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 31, 17, 'Laß leuchten dein Angesicht über deinem Knecht, hilf mir durch deine Gnade!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 31, 18, 'HERR, laß mich nicht enttäuscht werden, denn ich rufe dich an! Laß die Frevler enttäuscht werden, laß sie, zum Schweigen gebracht, in die Unterwelt fahren!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 31, 19, 'Verstummen müssen die Lügenlippen, die Freches reden gegen den Gerechten in Hochmut und Verachtung!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 31, 20, 'Wie groß ist deine Güte, die du vorbehältst denen, die dich fürchten, die du denen erzeigst, die ihre Zuflucht offen vor aller Welt zu dir nehmen!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 31, 21, 'Du schirmst sie mit deines Angesichts Schirm vor den Bosheitsplänen der Menschen, birgst sie in einer Hütte vor der Anfeindung der Zungen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 31, 22, 'Gepriesen sei der HERR, daß er mir seine Gnade wunderbar hat erwiesen in einer festen Stadt!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 31, 23, 'Ich zwar hatte gedacht in meiner Verzagtheit, ich sei verstoßen fern von deinen Augen; doch du hast mein lautes Flehen gehört, als ich zu dir rief.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 31, 24, 'Liebet den HERRN, ihr seine Frommen alle! Die Treuen behütet der HERR, vergilt aber reichlich dem, der Hochmut übt.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 31, 25, 'Seid stark, und euer Herz sei unverzagt, ihr alle, die ihr harret des HERRN!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 32, 1, 'Von David; ein Lehrgedicht. Wohl dem, dessen Missetat vergeben und dessen Sünde zugedeckt ist!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 32, 2, 'Wohl dem Menschen, dem der HERR die Schuld nicht zurechnet und in dessen Geist kein Trug wohnt!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 32, 3, 'Solange ich Schweigen übte, verzehrte sich mein Leib, weil es unaufhörlich in mir schrie;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 32, 4, 'denn bei Tag und bei Nacht lag schwer auf mir deine Hand: mein Lebenssaft verdorrte wie durch Sommergluten. SELA.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 32, 5, 'Da bekannte ich dir meine Sünde und verhehlte meine Verschuldung nicht; ich sagte: »Bekennen will ich dem HERRN meine Missetaten!« Da hast du mir meine Sündenschuld vergeben. SELA.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 32, 6, 'Darum möge jeder Fromme zu dir beten, solange du dich finden läßt; wenn dann gewaltige Fluten daherstürzen – ihn werden sie nicht erreichen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 32, 7, 'Du bist mir ein Schirm, bewahrst mich vor Unheil: mit Rettungsjubel du wirst mich umgeben. SELA.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 32, 8, '»Ich will dich unterweisen und dich lehren den Weg, den du wandeln sollst; ich will dich beraten, mein Auge auf dich richten.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 32, 9, 'Seid nicht dem Roß, dem Maultier gleich, die keinen Verstand besitzen; mit Zaum und Gebiß mußt du brechen ihren Trotz, sonst kommen sie nicht zu dir.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 32, 10, 'Zahlreich sind die Leiden des Gottlosen; doch wer auf den HERRN vertraut, den wird er mit Gnade umgeben.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 32, 11, 'Freuet euch des HERRN und frohlockt, ihr Gerechten, und jubelt, ihr redlich Gesinnten alle!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 33, 1, 'Jubelt, ihr Gerechten, über den HERRN! Den Aufrichtigen ziemet Lobgesang.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 33, 2, 'Preiset den HERRN mit der Zither, spielt ihm auf zehnsaitiger Harfe!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 33, 3, 'Singt ihm ein neues Lied, laßt laut die Saiten erklingen mit Jubelschall!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 33, 4, 'Denn das Wort des HERRN ist wahrhaftig, und in all seinem Tun ist er treu;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 33, 5, 'er liebt Gerechtigkeit und Recht; von der Gnade des HERRN ist die Erde voll.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 33, 6, 'Durch das Wort des HERRN sind die Himmel geschaffen, und ihr ganzes Heer durch den Hauch seines Mundes.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 33, 7, 'Er türmt die Wasser des Meeres auf wie einen Wall und legt die Fluten in Vorratskammern.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 33, 8, 'Es fürchte den HERRN die ganze Erde, vor ihm müssen beben alle Erdenbewohner;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 33, 9, 'denn er sprach: da geschah’s; er gebot: da stand es da.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 33, 10, 'Der HERR hat den Ratschluß der Heiden zerschlagen, die Gedanken der Völker vereitelt.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 33, 11, 'Der Ratschluß des HERRN bleibt ewig bestehn, seines Herzens Gedanken von Geschlecht zu Geschlecht.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 33, 12, 'Wohl dem Volk, dessen Gott der HERR ist, dem Volk, das zum Eigentum er sich erwählt hat!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 33, 13, 'Vom Himmel blickt der HERR herab, sieht alle Menschenkinder;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 33, 14, 'von der Stätte, wo er wohnt, überschaut er alle Bewohner der Erde,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 33, 15, 'er, der allen ihr Herz gestaltet, der acht hat auf all ihr Tun.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 33, 16, 'Ein König ist nicht geschützt durch große Heeresmacht, ein Kriegsheld rettet sich nicht durch große Kraft;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 33, 17, 'betrogen ist, wer von Rossen die Rettung erhofft, denn trotz all ihrer Stärke vermögen sie nicht zu retten.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 33, 18, 'Bedenke: das Auge des HERRN ruht auf denen, die ihn fürchten, auf denen, die seiner Gnade harren,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 33, 19, 'auf daß er ihre Seele vom Tode errette und sie am Leben erhalte in Hungersnot.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 33, 20, 'Unsre Seele harret des HERRN: unsre Hilfe und unser Schild ist er.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 33, 21, 'Ja, seiner freut sich unser Herz, denn auf seinen heiligen Namen vertrauen wir.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 33, 22, 'Deine Gnade walte über uns, o HERR, gleichwie wir auf dich geharrt haben!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 34, 1, 'Von David, als er sich vor Abimelech irrsinnig stellte und dieser ihn von sich trieb, so daß er von dannen ging.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 34, 2, 'Ich will den HERRN allzeit preisen, immerdar soll sein Lob in meinem Munde sein.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 34, 3, 'Des HERRN soll meine Seele sich rühmen, die Demütigen sollen es hören und sich freuen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 34, 4, 'Verherrlicht mit mir den HERRN und laßt uns gemeinsam seinen Namen erheben!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 34, 5, 'Sooft den HERRN ich suchte, hat er mich erhört und aus allen meinen Ängsten mich befreit.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 34, 6, 'Wer auf ihn blickt, wird heiteren Sinnes, und sein Antlitz braucht nicht beschämt zu erröten.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 34, 7, 'Hier ist ein (solcher) Dulder, der rief: da hörte der HERR und half ihm aus all seinen Nöten.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 34, 8, 'Der Engel des HERRN lagert sich rings um die Gottesfürchtigen und rettet sie.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 34, 9, 'Schmecket und sehet, wie freundlich der HERR ist: wohl dem Manne, der auf ihn vertraut!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 34, 10, 'Fürchtet den HERRN, ihr seine Heiligen! denn die ihn fürchten, leiden keinen Mangel.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 34, 11, 'Junge Löwen müssen darben und leiden Hunger; doch wer den HERRN sucht, entbehrt nichts Gutes.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 34, 12, 'Kommt her, ihr Kinder, hört mir zu: die Furcht des HERRN will ich euch lehren!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 34, 13, 'Wer ist der Mann, der langes Leben begehrt, der viele Tage sich wünscht, um Glück zu genießen?');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 34, 14, 'Hüte deine Zunge vor Bösem und deine Lippen vor Worten des Trugs!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 34, 15, 'Halte dich fern vom Bösen und tu das Gute, suche den Frieden und jage ihm nach!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 34, 16, 'Die Augen des HERRN sind auf die Gerechten gerichtet und seine Ohren auf ihr Hilfsgeschrei.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 34, 17, 'Das Antlitz des HERRN steht gegen die Frevler, um ihr Gedächtnis auszutilgen von der Erde.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 34, 18, 'Wenn sie schreien, so hört es der HERR und rettet sie aus all ihren Nöten.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 34, 19, 'Der HERR ist nahe den zerbrochenen Herzen, hilft denen, die zerschlagenen Geistes sind.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 34, 20, 'Zahlreich sind die Leiden des Gerechten, doch aus allen rettet ihn der HERR.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 34, 21, 'Er behütet alle seine Gebeine, daß nicht eins von ihnen zerbrochen wird.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 34, 22, 'Den Gottlosen wird das Unglück töten, und wer den Gerechten haßt, muß es büßen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 34, 23, 'Der HERR erlöst die Seele seiner Knechte, und alle, die zu ihm sich flüchten, brauchen nicht zu büßen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 35, 1, 'Von David. Streite, HERR, mit denen, die mich bestreiten, kämpfe mit denen, die mich bekämpfen!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 35, 2, 'Ergreife Schild und Tartsche und stehe auf zur Hilfe für mich!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 35, 3, 'Zücke die Lanze und sperre meinen Verfolgern den Weg, sprich zu meiner Seele: »Deine Hilfe bin ich!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 35, 4, 'Laß in Schmach und Schande geraten, die mir nach dem Leben trachten; zurückweichen müssen und schamrot werden, die auf Unheil gegen mich sinnen!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 35, 5, 'Laß sie werden wie Spreu vor dem Winde, während der Engel des HERRN sie zurückstößt!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 35, 6, 'Ihr Weg müsse finster und schlüpfrig sein, während der Engel des HERRN sie verfolgt!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 35, 7, 'Denn ohn’ Ursach haben sie heimlich ihr Netz mir gestellt, meinem Leben ohn’ Ursach eine Grube gegraben.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 35, 8, 'Möge Verderben ihn unversehens treffen, und sein Netz, das er heimlich gestellt, das möge ihn fangen: zum Verderben gerate er selbst hinein!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 35, 9, 'Dann wird mein Herz frohlocken über den HERRN und sich freuen ob seiner Hilfe;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 35, 10, 'alle Glieder meines Leibes werden bekennen: »HERR, wer ist dir gleich? Du bist’s, der den Elenden rettet vor dem Überstarken und den Elenden und Armen vor dem Räuber.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 35, 11, 'Es treten Lügenzeugen (gegen mich) auf, befragen mich über Dinge, von denen ich nichts weiß;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 35, 12, 'sie vergelten mir Böses für Gutes, bringen Vereinsamung über mich.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 35, 13, 'Ich aber – als krank sie lagen, war ein Sack mein Gewand; ich kasteite mich mit Fasten, und mein Gebet kehrte sich gegen mich selbst;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 35, 14, 'als wär’s mein Freund, mein Bruder, so ging ich einher; wie einer, der Leid um die Mutter trägt, so senkte ich trauernd das Haupt.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 35, 15, 'Doch jetzt ob meinem Sturze frohlocken sie und tun sich zusammen, sie treten zu kränkendem Spott zusammen gegen mich, und Leute, die ich nicht kenne, lästern mich unaufhörlich,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 35, 16, 'die heuchlerischen Kuchenbettler, die doch mit den Zähnen gegen mich knirschen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 35, 17, 'O Allherr, wie lange noch willst du’s ansehn? Entreiß meine Seele ihren Lügenreden (oder Verwüstungen), mein Leben den jungen Löwen!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 35, 18, 'Dann will ich dir danken in großer Versammlung, vor zahlreichem Volke dich preisen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 35, 19, 'Laß sich nicht freun über mich, die ohn’ Ursach mir feind sind, laß nicht mit den Augen blinzeln, die ohne Grund mich hassen!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 35, 20, 'Sie reden ja nicht, was zum Frieden dient, nein, gegen die Stillen im Lande ersinnen sie Worte des Truges;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 35, 21, 'sie reißen den Mund weit auf gegen mich, sie rufen: »Haha, wir haben’s mit unsern eigenen Augen gesehn!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 35, 22, 'Du hast’s gesehn, HERR: bleibe nicht stumm, o Allherr, bleibe nicht fern von mir,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 35, 23, 'Erhebe dich doch, wache auf, mir Recht zu schaffen, mein Gott und Allherr, meine Sache zu führen!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 35, 24, 'Schaffe mir Recht nach deiner Gerechtigkeit, HERR mein Gott, laß sie sich über mich nicht freuen!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 35, 25, 'Laß sie in ihrem Herzen nicht sagen: »Haha! So wollten wir’s!« Laß sie nicht sagen: »Wir haben ihn verschlungen!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 35, 26, 'Laß sie alle enttäuscht und schamrot werden, die meines Unglücks sich freuen, laß in Schmach und Schande sich kleiden, die gegen mich großtun!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 35, 27, 'Laß jubeln und fröhlich sein, die mein Recht mir wünschen, und laß sie immer bekennen: »Groß ist der HERR, dem das Heil seines Knechtes am Herzen liegt!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 35, 28, 'Dann soll meine Zunge verkünden deine Gerechtigkeit (und) deinen Ruhm den ganzen Tag.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 36, 1, 'Dem Musikmeister; vom Knechte des Herrn, von David.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 36, 2, 'Eingebung der Sünde beherrscht den Frevler, so läßt es im Innern meines Herzens sich hören: kein Zagen vor Gott steht ihm vor Augen;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 36, 3, 'denn sie verblendet ihn mit Schmeichelreden, daß er in Verschuldung gerät, indem er Haß ausübt.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 36, 4, 'Was er ausspricht, ist Unheil und Trug; aufgehört hat er, verständig zu sein, um gut zu handeln.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 36, 5, 'Unheil sinnt er auf seinem Lager, tritt hin auf den Weg der Bosheit, das Schlechte verabscheut er nicht.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 36, 6, 'O HERR, bis zum Himmel reicht deine Gnade, deine Treue bis hin an die Wolken;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 36, 7, 'deine Gerechtigkeit steht fest wie die Gottesberge, deine Gerichte gleichen dem weiten Weltmeer; Menschen und Tieren hilfst du, o HERR.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 36, 8, 'Wie köstlich ist deine Gnade, o Gott, daß Menschenkinder sich bergen im Schatten deiner Flügel!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 36, 9, 'Sie laben sich an den reichen Gütern deines Hauses, und du tränkst sie mit dem Strom deiner Wonnen;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 36, 10, 'denn bei dir ist der Brunnquell des Lebens, und in deinem Lichte schauen wir Licht.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 36, 11, 'Erhalte deine Gnade denen, die dich kennen, und deine Gerechtigkeit den redlich Gesinnten!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 36, 12, 'Laß den Fuß des Hochmuts mich nicht treten und die Hand der Frevler mich nicht vertreiben!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 36, 13, 'Einst werden die Übeltäter gefallen sein, niedergestürzt und können nicht wieder aufstehn.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 1, 'Von David. Entrüste dich nicht über die Bösen und ereifre dich nicht über die Übeltäter!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 2, 'denn schnell wie das Gras verwelken sie und verdorren wie grünender Rasen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 3, 'Vertrau auf den HERRN und tu das Gute, bleib wohnen im Lande und übe Redlichkeit');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 4, 'und habe deine Lust am HERRN: so wird er dir geben, was dein Herz begehrt.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 5, 'Befiehl dem HERRN deine Wege und vertraue auf ihn: er wird’s wohl machen');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 6, 'und deine Gerechtigkeit strahlen lassen wie das Licht und dein Recht wie den hellen Mittag.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 7, 'Sei stille dem HERRN und harre auf ihn, entrüste dich nicht über den, der Glück hat bei seinem Tun, über den Mann, der Ränke übt!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 8, 'Steh ab vom Zorn und entsage dem Grimm, entrüste dich nicht: es führt nur zum Bösestun!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 9, 'Denn die Übeltäter werden ausgerottet, doch die da harren des HERRN, die werden das Land besitzen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 10, 'Nur noch ein Weilchen, so wird der Frevler nicht mehr sein, und siehst du dich um nach seiner Stätte, so ist er nicht mehr da;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 11, 'die stillen Dulder aber werden das Land besitzen und sich freun an der Fülle des Friedens.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 12, 'Böses sinnt der Frevler gegen den Gerechten und knirscht mit den Zähnen gegen ihn;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 13, 'der Allherr aber lacht über ihn, denn er sieht, daß sein Tag kommt.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 14, 'Die Frevler zücken das Schwert und spannen den Bogen, um den Dulder und Armen niederzustrecken und die redlich Wandelnden hinzumorden;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 15, 'doch ihr Schwert dringt ihnen ins eigne Herz, und ihre Bogen werden zerbrochen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 16, 'Das geringe Gut des Gerechten ist besser als der Überfluß vieler Gottlosen;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 17, 'denn die Arme der Gottlosen werden zerbrochen, die Gerechten aber stützt der HERR.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 18, 'Der HERR kennt wohl die Tage der Frommen, und ihr Besitz ist für immer gesichert;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 19, 'sie werden nicht zuschanden in böser Zeit, nein, in den Tagen des Hungers werden sie satt.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 20, 'Dagegen die Gottlosen gehen zugrunde, und die Feinde des HERRN sind wie die Pracht der Auen: sie vergehen wie Rauch, sie vergehen!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 21, 'Der Gottlose muß borgen und kann nicht zahlen, der Gerechte aber schenkt und gibt;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 22, 'denn die vom HERRN Gesegneten erben das Land, aber die von ihm Verfluchten werden vernichtet.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 23, 'Vom HERRN her werden die Schritte des Mannes gefestigt, und zwar wenn Gefallen er hat an seinem Wandel;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 24, 'wenn er strauchelt, stürzt er nicht völlig nieder, denn der HERR stützt ihm die Hand.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 25, 'Ich bin jung gewesen und alt geworden, doch hab’ ich nie den Gerechten verlassen gesehn, noch seine Kinder betteln um Brot.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 26, 'Allzeit kann er schenken und darleihn, und auch noch seine Kinder sind zum Segen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 27, 'Halte dich fern vom Bösen und tu das Gute, so wirst du für immer wohnen bleiben;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 28, 'Denn der HERR hat das Recht lieb und verläßt seine Frommen nicht: ewiglich werden sie behütet, doch der Gottlosen Nachwuchs wird ausgerottet.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 29, 'Die Gerechten werden das Land besitzen und bleiben in ihm wohnen für immer.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 30, 'Des Gerechten Mund läßt Weisheit hören, und seine Zunge redet Recht;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 31, 'das Gesetz seines Gottes wohnt ihm im Herzen, und seine Schritte wanken nicht.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 32, 'Der Gottlose lauert dem Gerechten auf und sucht ihn ums Leben zu bringen;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 33, 'doch der HERR läßt ihn nicht fallen in seine Hand und läßt ihn nicht verdammen vor Gericht.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 34, 'Harre des HERRN und halte dich an seinen Weg, so wird er dich erhöhn zum Besitz des Landes; an der Gottlosen Vernichtung wirst du deine Freude sehn.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 35, 'Ich hab’ einen Frevler gesehen, der trat gar trotzig auf und spreizte sich stolz wie ein grünender, ragender Baum;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 36, 'doch als ich (wieder) vorüberging, da war er verschwunden, und als ich ihn suchte, war er nicht mehr zu finden.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 37, 'Bleibe (also) fromm und halte dich recht, denn solchen wird es zuletzt wohl ergehn;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 38, 'die Frevler aber werden allesamt vertilgt, und der Gottlosen Nachwuchs wird ausgerottet.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 39, 'Die Hilfe der Gerechten kommt vom HERRN: er ist ihre Schutzwehr zur Zeit der Not;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 40, 'denn der HERR steht ihnen bei und rettet sie; er rettet sie von den Frevlern und bringt ihnen Hilfe, weil auf ihn sie ihr Vertrauen setzen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 38, 1, 'Ein Psalm von David, bei Darbringung des Duftopfers.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 38, 2, 'HERR, nicht in deinem Zorne strafe mich, und nicht in deinem Ingrimm züchtige mich!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 38, 3, 'Denn deine Pfeile sind in mich eingedrungen, und deine Hand liegt schwer auf mir:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 38, 4, 'nichts ist gesund an meinem Leib ob deinem Zürnen, nichts heil an meinen Gliedern ob meiner Sünde.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 38, 5, 'Denn meine Missetaten schlagen mir über dem Haupt zusammen; wie eine schwere Last sind sie mir zu schwer geworden.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 38, 6, 'Es faulen, es eitern meine Wunden infolge meiner Torheit.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 38, 7, 'Ich bin gekrümmt, tief niedergebeugt; den ganzen Tag geh’ ich trauernd einher;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 38, 8, 'denn meine Lenden sind voll von Entzündung, und nichts ist unversehrt an meinem Leibe.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 38, 9, 'Erschöpft bin ich und ganz zerschlagen, ich schreie auf infolge des Stöhnens meines Herzens.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 38, 10, 'O Allherr, all mein Verlangen ist dir bekannt, und meine Seufzer sind dir nicht verborgen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 38, 11, 'Mein Herz pocht stürmisch, meine Kraft hat mich verlassen, und das Licht meiner Augen, auch das ist dahin!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 38, 12, 'Meine Freunde und Genossen stehn abseits von meinem Elend, und meine nächsten Verwandten halten sich fern.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 38, 13, 'Die nach dem Leben mir trachten, legen mir Schlingen, und die mein Unglück suchen, verabreden Unheil und sinnen auf Trug den ganzen Tag.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 38, 14, 'Doch ich bin wie ein Tauber, höre es nicht, und bin wie ein Stummer, der den Mund nicht auftut;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 38, 15, 'ja, ich bin wie einer, der nicht hören kann und in dessen Mund keine Widerrede ist;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 38, 16, 'denn auf dich, HERR, warte ich: du wirst antworten, o Allherr, mein Gott;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 38, 17, 'denn ich sage: »Daß sie nur nicht über mich frohlocken, nur nicht beim Wanken meines Fußes gegen mich großtun!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 38, 18, 'Denn nahe bin ich am Zusammenbrechen, und mein Schmerz ist mir allezeit gegenwärtig.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 38, 19, 'Ach! Ich bekenne meine Schuld, bin bekümmert ob meiner Sünde!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 38, 20, 'Dagegen die ohne Grund mich befeinden, sind stark, und zahlreich sind, die ohn’ Ursach’ mich hassen,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 38, 21, 'und solche, die mir Gutes mit Bösem vergelten, sind meine Widersacher, weil fest am Guten ich halte.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 38, 22, 'Verlaß mich nicht, o HERR, mein Gott, sei nicht ferne von mir!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 38, 23, 'Eile zu meinem Schutz herbei, o Allherr, meine Rettung!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 39, 1, 'Dem Musikmeister Jeduthun; ein Psalm von David.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 39, 2, 'Ich dachte: »Achten will ich auf meine Wege, daß ich nicht sünd’ge mit meiner Zunge; ich will meinem Mund einen Zaum anlegen, solange noch der Frevler vor mir steht.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 39, 3, 'So ward ich denn stumm, ganz stumm, mit Gewalt schweigsam; doch es wühlte mein Schmerz noch wilder.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 39, 4, 'Das Herz ward mir heiß in der Brust, ob meinem Grübeln brannte ein Feuer in mir; da ließ ich meiner Zunge freien Lauf:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 39, 5, '»HERR, laß mein Ende mich wissen und welches das Maß meiner Tage ist! Laß mich erkennen, wie vergänglich ich bin!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 39, 6, 'Ach, spannenlang hast du mir die Tage gemacht, und meines Lebens Dauer ist wie nichts vor dir: ja, nur als ein Hauch steht jeglicher Mensch da!« SELA.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 39, 7, 'Fürwahr nur als Schattenbild wandelt der Mensch einher, nur um ein Nichts wird so viel Lärm gemacht; man häuft auf und weiß nicht, wer es einheimst.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 39, 8, 'Und nun, o Allherr, wes soll ich harren? Meine Hoffnung geht auf dich (allein).');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 39, 9, 'Errette mich von allen meinen Sünden, zum Spott der Toren laß mich nicht werden!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 39, 10, 'Ich schweige, tu meinen Mund nicht auf, denn du hast’s so gefügt.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 39, 11, 'Nimm deine Plage weg von mir: unter dem Druck deiner Hand erlieg’ ich.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 39, 12, 'Züchtigst du einen Menschen mit Strafen um der Sünde willen, so läßt du seine Schönheit vergehn wie die Motte: ach, nur ein Hauch ist jeglicher Mensch! SELA.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 39, 13, 'Höre, o HERR, mein Gebet und vernimm mein Schreien, bleib’ nicht stumm bei meinen Tränen! Denn ein Gast (nur) bin ich bei dir, ein Beisaß wie all meine Väter.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 39, 14, 'Blick weg von mir, daß mein Antlitz sich wieder erheitert, bevor ich dahinfahre und nicht mehr bin!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 40, 1, 'Dem Musikmeister; von David ein Psalm.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 40, 2, 'Geduldig hatte ich des HERRN geharrt: da neigte er sich zu mir und hörte mein Schreien;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 40, 3, 'er zog mich herauf aus der Grube des Unheils, aus dem schlammigen Sumpf, und stellte meine Füße auf Felsengrund, verlieh meinen Schritten Festigkeit;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 40, 4, 'er legte ein neues Lied mir in den Mund, einen Lobgesang auf unsern Gott. Das werden viele sehen und Ehrfurcht fühlen und Vertrauen fassen zum HERRN.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 40, 5, 'Glückselig der Mann, der sein Vertrauen setzt auf den HERRN, der’s nicht mit den Stolzen hält und nicht mit den treulosen Lügenfreunden!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 40, 6, 'Zahlreich sind die Wunder, die du getan hast, und deine Heilsgedanken mit uns, o HERR, mein Gott; dir ist nichts zu vergleichen; wollt’ ich von ihnen reden und sie verkünden – sie übersteigen jede Zahl.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 40, 7, 'An Schlacht- und Speisopfern hast du kein Gefallen, doch offne Ohren hast du mir gegeben; nach Brand- und Sündopfern trägst du kein Verlangen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 40, 8, 'Da hab’ ich gesagt: »Siehe, hier bin ich! In der Rolle des Buches, da steht für mich geschrieben:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 40, 9, 'Deinen Willen zu tun, mein Gott, ist meine Lust, und dein Gesetz ist tief mir ins Herz geschrieben.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 40, 10, 'Von (deiner) Gerechtigkeit hab’ ich in großer Versammlung gesprochen, siehe, meinen Lippen hab’ ich nicht Einhalt getan: du selbst, HERR, weißt es!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 40, 11, 'Deine Gerechtigkeit habe ich nicht verborgen in meinem Herzen, von deiner Treue und Hilfe laut geredet; ich habe deine Gnade und Wahrheit nicht verschwiegen, vor der großen Versammlung.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 40, 12, 'So wirst du, HERR, mir dein Erbarmen nicht versagen; deine Gnade und Wahrheit werden stets mich behüten.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 40, 13, 'Denn Leiden ohne Zahl umringen mich, meine Sünden haben mich ereilt, unübersehbar; zahlreicher sind sie als die Haare meines Hauptes, und der Mut ist mir entschwunden.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 40, 14, 'Laß dir’s wohlgefallen, o HERR, mich zu retten, eile, o HERR, zu meiner Hilfe herbei!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 40, 15, 'Laß sie allesamt beschämt und schamrot werden, die nach dem Leben mir stehn, um es wegzuraffen! Laß mit Schande beladen abziehn, die mein Unglück wünschen!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 40, 16, 'Erschaudern müssen ob ihrer Schmach, die über mich rufen: »Haha, haha!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 40, 17, 'Laß jubeln und deiner sich freuen alle, die dich suchen; laß alle, die nach deinem Heil verlangen, immerdar bekennen: »Groß ist der HERR.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 40, 18, 'Bin ich auch elend und arm – der Allherr wird für mich sorgen. Meine Hilfe und mein Retter bist du: mein Gott, säume nicht!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 41, 1, 'Dem Musikmeister; ein Psalm von David.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 41, 2, 'Wohl dem, der des Schwachen sich annimmt: am Tage des Unglücks wird der HERR ihn erretten!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 41, 3, 'Der HERR wird ihn behüten und am Leben erhalten, daß er glücklich gepriesen wird im Lande; und du gibst ihn nicht preis der Gier seiner Feinde.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 41, 4, 'Der HERR wird ihn auf dem Siechbett erquicken: sein ganzes Krankenlager machst du ihm leicht.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 41, 5, 'Ich sage: »O HERR, sei mir gnädig, ach, heile meine Seele, denn an dir hab’ ich gesündigt!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 41, 6, 'Meine Feinde reden Böses von mir: »Wann wird er sterben, daß sein Name verschwindet?«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 41, 7, 'Kommt jemand, mich zu besuchen, so redet er Falschheit; sein Herz sammelt Bosheit an; dann geht er hinaus, um draußen davon zu reden.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 41, 8, 'Alle, die mich hassen, zischeln vereint über mich, Unheil sinnen sie gegen mich:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 41, 9, '»Ein heilloses Übel haftet ihm an! Wer so sich gelegt hat, kommt nicht wieder hoch!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 41, 10, 'Sogar mein bester Freund, dem ich fest vertraute, der mein Brot aß, hat die Ferse gegen mich erhoben.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 41, 11, 'Du aber, HERR, sei mir gnädig und hilf mir wieder auf, so will ich’s ihnen vergelten!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 41, 12, 'Daran will ich erkennen, daß du Gefallen an mir hast, wenn mein Feind nicht über mich jubeln wird,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 41, 13, 'doch du mich ob meiner Unschuld aufrecht hältst und mich vor deinem Angesicht stehn läßt immerdar.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 41, 14, 'Gepriesen sei der HERR, der Gott Israels, von Ewigkeit zu Ewigkeit! Amen, ja Amen!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 42, 1, 'Dem Musikmeister; ein Lehrgedicht der Korahiten.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 42, 2, 'Wie der Hirsch lechzt nach Wasserbächen, so lechzt meine Seele nach dir, o Gott!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 42, 3, 'Meine Seele dürstet nach Gott, dem lebendigen Gott: wann werde ich dahin kommen, daß ich erscheine vor Gottes Angesicht?');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 42, 4, 'Meine Tränen sind meine Speise geworden bei Tag und bei Nacht, weil man den ganzen Tag zu mir sagt: »Wo ist nun dein Gott?«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 42, 5, 'Daran will ich gedenken – und meinem Schmerz freien Lauf in mir lassen –, wie einst ich dahinschritt in dichter Schar, mit ihnen wallte zum Hause Gottes, umbraust von lautem Jubel und Lobgesang inmitten der feiernden Menge.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 42, 6, 'Was betrübst du dich, meine Seele, und stürmst so ruhlos in mir? Harre auf Gott! Denn ich werde ihm noch danken, ihm, meines Angesichts Hilfe und meinem Gott.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 42, 7, 'Gebeugt ist meine Seele in mir: drum denk’ ich an dich im Lande des Jordans und der Hermongipfel, am Berge Mizar:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 42, 8, 'Flut ruft der Flut zu beim Tosen deiner Wasserstürze; alle, alle deine Wogen und Wellen sind über mich hingegangen!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 42, 9, 'Bei Tag seufz’ ich: »Es entbiete der HERR seine Gnade!«, und nachts ist sein Lied in meinem Munde, ein Gebet zum Gott meines Lebens.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 42, 10, 'Ich sage zu Gott, meinem Felsen: »Warum hast du mich vergessen? Warum muß ich trauernd einhergehn unter dem Druck des Feindes?«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 42, 11, 'Wie Zermalmung liegt mir in meinen Gebeinen der Hohn meiner Dränger, weil sie den ganzen Tag zu mir sagen: »Wo ist nun dein Gott?«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 42, 12, 'Was betrübst du dich, meine Seele, und stürmst so ruhlos in mir? Harre auf Gott! Denn ich werde ihm noch danken, ihm, meines Angesichts Hilfe und meinem Gott.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 43, 1, 'Schaffe mir Recht, o Gott, und führe meinen Rechtsstreit gegen ein liebloses Volk! Von Menschen des Trugs und der Bosheit errette mich, HERR!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 43, 2, 'Du bist ja der Gott, der mich schützt: warum hast du mich verstoßen? Warum muß ich trauernd einhergehn unter dem Druck des Feindes?');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 43, 3, 'Sende dein Licht und deine Treue! Die sollen mich leiten, mich bringen zu deinem heiligen Berge und deiner Wohnstatt,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 43, 4, 'damit ich zum Altar Gottes komme, zu dem Gott meines Freudenjubels, und unter Zitherklang dich preise, o Gott, mein Gott!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 43, 5, 'Was betrübst du dich, meine Seele, und stürmst so ruhlos in mir? Harre auf Gott! Denn ich werde ihm noch danken, ihm, meines Angesichts Hilfe und meinem Gott.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 44, 1, 'Dem Musikmeister; von den Korahiten ein Lehrgedicht.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 44, 2, 'O Gott, mit eignen Ohren haben wir’s gehört, unsre Väter haben’s uns erzählt, was du Großes in ihren Tagen vollführt hast, in den Tagen der Vorzeit.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 44, 3, 'Du hast Heidenvölker mit deiner Hand vertrieben und sie an deren Stelle eingepflanzt; Völker hast du vernichtet, sie aber ausgebreitet.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 44, 4, 'Denn nicht mit ihrem Schwerte haben sie das Land gewonnen, und nicht ihr Arm hat ihnen den Sieg verschafft, nein, deine Rechte und dein Arm und deines Angesichts Licht, denn du hattest Gefallen an ihnen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 44, 5, 'Nur du bist mein König, o Gott: entbiete Hilfe für Jakob!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 44, 6, 'Mit dir stoßen wir unsre Bedränger nieder, mit deinem Namen zertreten wir unsre Gegner.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 44, 7, 'Denn nicht auf meinen Bogen verlasse ich mich, und nicht mein Schwert verschafft mir den Sieg;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 44, 8, 'nein, du gewährst uns Hilfe gegen unsre Bedränger und machst zuschanden, die uns hassen:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 44, 9, 'Gottes rühmen wir uns allezeit und preisen deinen Namen ewiglich. SELA.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 44, 10, 'Und doch hast du uns verstoßen und Schmach uns angetan und ziehst nicht mehr aus mit unsern Heeren;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 44, 11, 'du hast vor dem Feinde uns weichen lassen, und die uns hassen, haben sich Beute geholt;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 44, 12, 'du hast uns hingegeben wie Schafe zur Schlachtung und unter die Heiden uns zerstreut;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 44, 13, 'du hast dein Volk verkauft um ein Spottgeld und den Preis für sie gar niedrig angesetzt;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 44, 14, 'du hast uns unsern Nachbarn zum Hohn gemacht, zum Spott und Gelächter rings umher;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 44, 15, 'hast gemacht, daß den Heiden zum Sprichwort wir dienen, daß den Kopf die Völker über uns schütteln.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 44, 16, 'Allzeit steht meine Schmach mir vor Augen, und die (Röte der) Scham bedeckt mir das Antlitz,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 44, 17, 'weil ich höre den lauten Hohn und die Lästerreden, weil den Feind und seine Rachgier ich sehn muß.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 44, 18, 'Dies alles hat uns getroffen, und wir hatten dich doch nicht vergessen und dem Bunde mit dir die Treue nicht gebrochen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 44, 19, 'Unser Herz ist nicht von dir abgefallen und unser Schritt nicht abgewichen von deinem Pfade,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 44, 20, 'daß du zermalmt uns hast an der Stätte der Schakale und mit Todesnacht uns umlagert hältst.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 44, 21, 'Hätten wir unsres Gottes Namen vergessen und unsre Hände erhoben zu einem fremden Gott:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 44, 22, 'würde Gott das nicht entdecken? Er kennt ja des Herzens geheimste Gedanken.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 44, 23, 'Nein, um deinetwillen werden wir täglich gemordet und werden dem Schlachtvieh gleich geachtet.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 44, 24, 'Wach auf! Warum schläfst du, o Allherr? Erwache! Verwirf nicht für immer!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 44, 25, 'Warum verbirgst du dein Angesicht, denkst nicht an unser Elend und unsre Bedrängnis?');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 44, 26, 'Ach, bis in den Staub ist unsre Seele gebeugt, unser Leib liegt da, am Erdboden klebend!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 44, 27, 'Steh auf, komm uns zu Hilfe und erlöse uns um deiner Gnade willen!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 45, 1, 'Dem Musikmeister, nach (der Singweise = Melodie) »Lilien«; von den Korahiten ein Lehrgedicht, ein Liebeslied.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 45, 2, 'Das Herz wallt mir auf von lieblichen Worten: dem Könige weihe ich meine Lieder; meine Zunge gleicht dem Griffel eines geübten Schreibers.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 45, 3, 'Du bist so schön wie sonst kein Mensch auf Erden: Anmut ist ausgegossen auf deine Lippen; darum hat Gott dich gesegnet für immer.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 45, 4, 'Gürte dein Schwert dir an die Seite, du Held, dazu deine herrlich schimmernde Wehr!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 45, 5, 'Glück auf! Fahre siegreich einher für die Sache der Wahrheit, zum Schutz des Rechts, und furchtbare Taten lasse dein Arm dich schauen!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 45, 6, 'Deine Pfeile sind scharf – Völker sinken unter dir hin –: sie dringen den Feinden des Königs ins Herz.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 45, 7, 'Dein Thron, ein Gottesthron, steht immer und ewig ein gerechtes Zepter ist dein Herrscherstab.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 45, 8, 'Du liebst Gerechtigkeit und hassest den Frevel; darum hat dich Gott, dein Gott, gesalbt mit Freudenöl wie keinen deinesgleichen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 45, 9, 'Von Myrrhe und Aloe duften, von Kassia alle deine Kleider; aus Elfenbeinpalästen erfreut dich Saitenspiel.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 45, 10, 'Königstöchter befinden sich unter deinen Geliebten; die Gattin steht dir zur Rechten im Goldschmuck von Ophir.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 45, 11, 'Höre, Tochter, blick her und neige dein Ohr: Vergiß dein Volk und deines Vaters Haus;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 45, 12, 'und trägt der König nach deiner Schönheit Verlangen er ist ja dein Herr –: so huldige ihm!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 45, 13, 'Die Bürgerschaft von Tyrus wird mit Gaben dir nahen, um deine Gunst mühen sich die Reichsten des Volkes.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 45, 14, 'Eitel Pracht ist die Königstochter drinnen, aus gewirktem Gold besteht ihr Gewand;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 45, 15, 'in buntgestickten Kleidern wird sie zum König geführt; Jungfraun, ihr Gefolge, ihre Gespielinnen, werden zu dir geleitet;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 45, 16, 'unter Freudenrufen und Jubel werden sie hingeführt, ziehen ein in den Palast des Königs.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 45, 17, 'An deiner Väter Stelle werden deine Söhne treten; du wirst sie zu Fürsten bestellen im ganzen Land.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 45, 18, 'Ich will ein Gedächtnis stiften deinem Namen bei allen kommenden Geschlechtern; darum werden die Völker dich preisen immer und ewig.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 46, 1, 'Dem Musikmeister, von den Korahiten, im Bass-Stimmsatz, ein Lied.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 46, 2, 'Gott ist uns Zuflucht und Stärke, als Hilfe in Nöten wohlbewährt befunden.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 46, 3, 'Darum bangen wir nicht, wenngleich die Erde vergeht, wenn Berge mitten im Meer versinken;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 46, 4, 'mögen tosen, mögen schäumen seine Wogen, mögen beben die Berge von seinem Ungestüm: der HERR der Heerscharen ist mit uns, ein’ feste Burg ist uns der Gott Jakobs! SELA.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 46, 5, 'Ein Strom ist da: seine Bäche erfreuen die Gottesstadt, das Heiligtum, die Wohnung des Höchsten.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 46, 6, 'Gott ist in ihrer Mitte: sie wird nicht wanken, Gott schützt sie, schon wenn der Morgen tagt.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 46, 7, 'Völker tobten, Königreiche wankten: er ließ seinen Donner dröhnen, da zerfloß die Erde.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 46, 8, 'Der HERR der Heerscharen ist mit uns, ein’ feste Burg ist uns der Gott Jakobs! SELA.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 46, 9, 'Kommt her und schauet die Taten des HERRN, der Wunderbares wirket auf Erden,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 46, 10, 'der den Kriegen ein Ziel setzt bis ans Ende der Erde, der Bogen zerbricht und Speere zerschlägt, Kriegswagen mit Feuer verbrennt!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 46, 11, '»Laßt ab und erkennt, daß ich (nur) Gott bin, erhaben unter den Völkern, erhaben auf Erden!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 46, 12, 'Der HERR der Heerscharen ist mit uns, ein’ feste Burg ist uns der Gott Jakobs! SELA.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 47, 1, 'Dem Musikmeister, von den Korahiten, ein Psalm.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 47, 2, 'Ihr Völker alle, klatscht in die Hände, jauchzet Gott mit Jubelrufen zu!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 47, 3, 'Denn der HERR, der Höchste, ist furchtbar, ein mächtiger König über die ganze Erde.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 47, 4, 'Er hat Völker unter unsre Herrschaft gebeugt und Völkerschaften unter unsre Füße;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 47, 5, 'er hat uns unser Erbteil auserwählt, den Stolz Jakobs, den er liebt. SELA.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 47, 6, 'Aufgefahren ist Gott unter Jauchzen, der HERR beim Schall der Posaunen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 47, 7, 'Lobsinget Gott, lobsinget, lobsingt unserm König, lobsinget!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 47, 8, 'Denn König der ganzen Erde ist Gott: so singt ihm denn ein kunstvolles Lied!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 47, 9, 'Gott ist König geworden über die Völker, Gott hat sich gesetzt auf seinen heiligen Thron.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 47, 10, 'Die Edlen der Völker haben sich versammelt als das Volk des Gottes Abrahams; denn Gott sind untertan die Schilde der Erde: hoch erhaben steht er da.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 48, 1, 'Ein Lied, ein Psalm von den Korahiten.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 48, 2, 'Groß ist der HERR und hoch zu preisen in unsers Gottes Stadt, auf seinem heiligen Berge.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 48, 3, 'Herrlich ragt empor, die Wonne der ganzen Erde, der Zionsberg, der wahre Götterberg, die Stadt eines großen Königs.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 48, 4, 'Gott hat in ihren Palästen sich kundgetan als eine feste Burg.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 48, 5, 'Denn siehe, die Könige hatten sich versammelt, waren vereint herangezogen;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 48, 6, 'doch als sie’s sahen, waren sie betroffen, erschraken, flohen bestürzt davon;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 48, 7, 'Zittern erfaßte sie dort, Angst wie ein Weib in Wehen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 48, 8, 'Durch einen Oststurm zertrümmertest du die stolzen Tharsisschiffe.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 48, 9, 'Wie wir’s gehört, so haben wir’s nun gesehen in der Stadt des HERRN der Heerscharen, unsres Gottes Stadt: Gott läßt sie auf ewig feststehn. SELA.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 48, 10, 'Wir gedenken, o Gott, deiner Gnade inmitten deines Tempels.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 48, 11, 'Wie dein Name, o Gott, so reicht auch dein Ruhm bis an die Enden der Erde; mit Gerechtigkeit ist deine Rechte gefüllt.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 48, 12, 'Des freue sich der Zionsberg, jubeln mögen die Töchter Judas um deiner Gerichte willen!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 48, 13, 'Umkreist den Zion, umwandelt ihn rings und zählt seine Türme;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 48, 14, 'betrachtet genau seine Bollwerke, mustert seine Paläste, damit ihr dem künftgen Geschlecht erzählet,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 48, 15, 'daß dies ist Gott, unser Gott: immer und ewig wird er uns führen [bis zum Tode].');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 49, 1, 'Dem Musikmeister, von den Korahiten, ein Psalm.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 49, 2, 'Höret dies, ihr Völker alle, merkt auf, ihr Bewohner der ganzen Welt,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 49, 3, 'sowohl ihr Söhne des Volks als ihr Herrensöhne, beide, so reich wie arm!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 49, 4, 'Mein Mund soll volle Weisheit reden, und meines Herzens Sinnen soll höchste Einsicht sein:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 49, 5, 'ich will mein Ohr einer Gleichnisrede leihen, will mein Rätsel eröffnen bei Saitenklang.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 49, 6, 'Warum sollt’ ich mich fürchten in bösen Tagen, wenn die Bosheit meiner Verfolger mich umgibt,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 49, 7, 'die auf ihr Vermögen vertrauen und mit ihrem großen Reichtum prahlen?');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 49, 8, 'Den Bruder loszukaufen vermag ja doch kein Mensch, noch an Gott das Lösegeld für ihn zu zahlen');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 49, 9, '- denn unerschwinglich hoch ist der Kaufpreis für ihr Leben: er muß davon Abstand nehmen für immer –,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 49, 10, 'damit er dauernd weiterlebe und die Grube nicht zu sehen bekomme.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 49, 11, 'Nein, er bekommt es zu sehen, daß sterben die Weisen, und Toren und Dumme gleicherweise umkommen und müssen andern ihr Gut hinterlassen:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 49, 12, 'Gräber sind ihre Behausung für immer, ihre Wohnungen von Geschlecht zu Geschlecht, ob sie auch Länder mit ihren Namen benannten.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 49, 13, 'Ja, der Mensch – in Herrlichkeit lebt er nicht fort: er gleicht den Tieren, die abgetan werden.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 49, 14, 'Dies ist das Schicksal derer, die voll Zuversicht sind, und der Ausgang derer, die ihren Reden Beifall schenken. SELA.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 49, 15, 'Wie Schafe werden sie ins Totenreich versetzt; der Tod weidet sie, und über sie herrschen die Frommen am Morgen; dem Totenreich zur Vernichtung fällt ihre Gestalt anheim, so daß ihr keine Wohnung bleibt.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 49, 16, 'Aber Gott wird meine Seele erlösen aus des Totenreichs Gewalt, denn er wird mich annehmen. SELA.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 49, 17, 'Drum rege dich nicht auf, wenn jemand reich wird, wenn seines Hauses Herrlichkeit sich mehrt;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 49, 18, 'denn im Tode nimmt er das alles nicht mit: seine Herrlichkeit fährt nicht mit ihm hinab.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 49, 19, 'Mag er sich auch im Leben glücklich preisen und mag man ihn rühmen, daß es ihm wohlergehe:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 49, 20, 'er wird doch eingehn zum Geschlecht seiner Väter, die das Tageslicht nimmermehr sehen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 49, 21, 'Der Mensch, in Herrlichkeit lebend, doch ohne Einsicht, gleicht den Tieren, die abgetan werden.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 50, 1, 'Ein Psalm von Asaph. Der Gott der Götter, der HERR, redet und ruft der Erde zu vom Aufgang der Sonne bis zu ihrem Niedergang;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 50, 2, 'aus Zion, der Krone der Schönheit, strahlt Gott in lichtem Glanz hervor:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 50, 3, 'unser Gott kommt und kann nicht schweigen, verzehrendes Feuer geht vor ihm her, und rings um ihn her stürmt es gewaltig.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 50, 4, 'Er ruft dem Himmel droben zu und der Erde, um sein Volk zu richten:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 50, 5, '»Versammelt mir meine Gesetzestreuen, die den Bund mit mir geschlossen beim Opfer!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 50, 6, 'Da taten die Himmel seine Gerechtigkeit kund; denn Gott selbst ist’s, der da Gericht hält. SELA.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 50, 7, '»Höre, mein Volk, und laß mich reden, Israel, daß ich dich ernstlich warne: Gott, dein Gott bin ich!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 50, 8, 'Nicht deiner Opfer wegen rüge ich dich, sind doch deine Brandopfer stets mir vor Augen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 50, 9, 'Doch ich mag nicht Stiere nehmen aus deinem Hause, nicht Böcke aus deinen Hürden;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 50, 10, 'denn mein ist alles Wild des Waldes, das Getier auf meinen Bergen zu Tausenden.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 50, 11, 'Ich kenne jeden Vogel auf den Bergen, und was auf dem Felde sich regt, steht mir zur Verfügung.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 50, 12, 'Hätte ich Hunger: ich brauchte es dir nicht zu sagen, denn mein ist der Erdkreis und all seine Fülle.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 50, 13, 'Esse ich etwa das Fleisch von Stieren, und soll ich das Blut von Böcken trinken?');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 50, 14, 'Bringe Dank dem HERRN als Opfer dar und bezahle so dem Höchsten deine Gelübde,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 50, 15, 'und rufe mich an am Tage der Not, so will ich dich retten, und du sollst mich preisen!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 50, 16, 'Zum Gottlosen aber spricht der Allherr: »Was hast du meine Satzungen aufzuzählen und meinen Bund im Munde zu führen,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 50, 17, 'da du selbst doch die Zucht mißachtest und meinen Worten den Rücken kehrst?');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 50, 18, 'Siehst du einen Dieb, so befreundest du dich mit ihm, und mit Ehebrechern hast du Gemeinschaft;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 50, 19, 'deinem Munde läßt du freien Lauf zur Bosheit, und deine Zunge zettelt Betrug an;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 50, 20, 'du sitzest da und redest (Böses) gegen deinen Bruder und bringst den Sohn deiner Mutter in Verruf!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 50, 21, 'Das (alles) hast du getan, und ich habe geschwiegen; da hast du gedacht, ich sei so wie du. Das mache ich dir zum Vorwurf und gebe dir’s zu bedenken.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 50, 22, 'O beherzigt das wohl, ihr Gottvergeßnen: sonst raffe ich euch hinweg ohne Rettung!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 50, 23, 'Wer Dank als Opfer darbringt, erweist mir Ehre, und wer unsträflich wandelt, den lasse ich schauen Gottes Heil.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 51, 1, 'Dem Musikmeister; ein Psalm von David,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 51, 2, 'als der Prophet Nathan zu ihm kam, nachdem er sich mit Bathseba vergangen hatte.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 51, 3, 'Sei mir gnädig, o Gott, nach deiner Güte! Nach deinem großen Erbarmen tilge meine Vergehen!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 51, 4, 'Wasche völlig mir ab meine Schuld und mache mich rein von meiner Missetat!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 51, 5, 'Ach, ich erkenne meine Vergehen wohl, und meine Missetat steht mir immerdar vor Augen!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 51, 6, 'Gegen dich allein hab’ ich gesündigt und habe getan, was böse ist in deinen Augen, auf daß du recht behältst mit deinen Urteilssprüchen und rein dastehst mit deinem Richten.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 51, 7, 'Ach, in Schuld bin ich geboren, und in Sünde hat meine Mutter mich empfangen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 51, 8, 'Du hast Gefallen an Wahrheit im innersten Herzen, und im Verborg’nen läßt du mich Weisheit erkennen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 51, 9, 'Entsündige mich mit Ysop, daß ich rein werde, wasche mich, daß ich weißer werde als Schnee.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 51, 10, 'Laß mich (wieder) Freude und Wonne empfinden, daß die Glieder frohlocken, die du zerschlagen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 51, 11, 'Verhülle dein Antlitz vor meinen Sünden und tilge alle meine Missetaten!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 51, 12, 'Schaffe mir, Gott, ein reines Herz und stell’ einen neuen, festen Geist in meinem Innern her!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 51, 13, 'Verwirf mich nicht von deinem Angesicht und nimm deinen heiligen Geist nicht weg von mir!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 51, 14, 'Gib, daß ich deiner Hilfe mich wieder freue, und rüste mich aus mit einem willigen Geist!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 51, 15, 'Dann will ich die Übertreter deine Wege lehren, und die Missetäter sollen zu dir sich bekehren.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 51, 16, 'Errette mich von Blutschuld, o Gott, du Gott meines Heils, damit meine Zunge deine Gerechtigkeit jubelnd preise!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 51, 17, 'O Allherr, tu mir die Lippen auf, damit mein Mund deinen Ruhm verkünde!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 51, 18, 'Denn an Schlachtopfern hast du kein Gefallen, und brächte ich Brandopfer dar: du möchtest sie nicht.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 51, 19, 'Opfer, die Gott gefallen, sind ein zerbrochner Geist; ein zerbrochnes und zerschlagnes Herz wirst du, o Gott, nicht verschmähen. –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 51, 20, 'Tu doch Gutes an Zion nach deiner Gnade: baue Jerusalems Mauern wieder auf!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 51, 21, 'Dann wirst du auch Wohlgefallen haben an richtigen Opfern, an Brand- und Ganzopfern; dann wird man Farren opfern auf deinem Altar.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 52, 1, 'Dem Musikmeister; ein Lehrgedicht Davids,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 52, 2, 'als der Edomiter Doeg kam und dem Saul die Meldung brachte, David sei in das Haus Ahimelechs gekommen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 52, 3, 'Was rühmst du dich der Bosheit, du Gewaltmensch? Gottes Gnade währet alle Zeit.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 52, 4, 'Auf Unheil sinnt deine Zunge wie ein scharfes Schermesser, du Ränkeschmied!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 52, 5, 'Du liebst das Böse mehr als das Gute, sprichst lieber Lügen als Gerechtigkeit. SELA.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 52, 6, 'Du liebst nur unheilvolle Reden, du trügerische Zunge!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 52, 7, 'So wird denn Gott dich auch vernichten für immer, dich wegraffen und herausreißen aus dem Zelt, dich entwurzeln aus der Lebenden Land! SELA.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 52, 8, 'Die Gerechten werden es sehn und sich fürchten, über ihn aber spotten:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 52, 9, '»Seht, das ist der Mann, der nicht Gott zu seiner Schutzwehr machte, vielmehr sich verließ auf seinen großen Reichtum und stark sich dünkte durch seine Bosheit!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 52, 10, 'Ich aber bin wie ein grünender Ölbaum im Hause Gottes, ich vertraue auf Gottes Gnade immer und ewig.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 52, 11, 'Preisen will ich dich immer, denn du hast’s vollführt, will rühmen deinen Namen, daß er so herrlich ist, vor deinen Frommen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 53, 1, 'Dem Musikmeister, nach (der Singweise = Melodie) »die Krankheit«; ein Lehrgedicht von David.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 53, 2, 'Die Toren sprechen in ihrem Herzen: »Es gibt keinen Gott«; verderbt ist ihr Tun, abscheulich ihr Freveln: da ist keiner, der Gutes täte.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 53, 3, 'Gott schaut hernieder vom Himmel aus nach den Menschenkindern, um zu sehn, ob da sei ein Verständiger, einer, der nach Gott fragt.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 53, 4, 'Doch alle sind sie abgefallen, insgesamt entartet; da ist keiner, der Gutes tut, auch nicht einer.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 53, 5, 'Haben denn keinen Verstand die Übeltäter, die mein Volk verzehren? Die Gottes Brot wohl essen, doch ohne ihn anzurufen?');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 53, 6, 'Damals gerieten sie in Angst und Schrecken, ohne daß Grund zum Erschrecken war; denn Gott zerstreute die Gebeine deiner Belagerer; du machtest sie zuschanden, denn Gott hatte sie verworfen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 53, 7, 'Ach, daß doch aus Zion die Rettung Israels käme! Wenn Gott einst wendet das Schicksal seines Volkes, wird Jakob jubeln, Israel sich freuen!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 54, 1, 'Dem Musikmeister, mit Saitenspiel; ein Lehrgedicht Davids,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 54, 2, 'als die Siphiter kamen und zu Saul sagten: »Weißt du nicht, daß David sich bei uns verborgen hält?«.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 54, 3, 'Hilf mir, o Gott, durch deinen Namen und schaffe mir Recht durch deine Kraft!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 54, 4, 'Höre, o Gott, mein Gebet, vernimm die Worte meines Mundes!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 54, 5, 'Denn Freche haben sich gegen mich erhoben, und Gewalttätige trachten mir nach dem Leben: sie haben Gott sich nicht vor Augen gestellt. SELA.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 54, 6, 'Ich weiß: Gott ist mir ein Helfer, der Allherr ist meiner Seele Stütze.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 54, 7, 'Das Böse wird auf meine Feinde zurückfallen: nach deiner Treue vernichte sie!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 54, 8, 'Dann will ich mit Freuden dir Opfer bringen, will preisen deinen Namen, o HERR, daß er gütig ist;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 54, 9, 'denn er hat mich aus aller Bedrängnis errettet, und an meinen Feinden hat mein Auge sich geweidet.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 55, 1, 'Dem Musikmeister, mit Saitenspiel, ein Lehrgedicht von David.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 55, 2, 'Vernimm, o Gott, mein Gebet und verbirg dich nicht vor meinem Flehen!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 55, 3, 'Merke auf mich und erhöre mich! Ich schwanke in meinem Kummer hin und her und stöhne');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 55, 4, 'ob dem Lärmen der Feinde, ob dem Toben der Frevler; denn sie wälzen Unheil auf mich und befehden mich wütend.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 55, 5, 'Das Herz ängstigt sich mir in der Brust, und die Schrecken des Todes haben mich befallen;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 55, 6, 'Furcht und Zittern kommt mich an, und ein Schauder überläuft mich.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 55, 7, 'So ruf ich denn aus: »O hätt’ ich doch Flügel wie die Taube! Ich wollte fliegen, bis ich irgendwo Ruhe fände.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 55, 8, 'Ja weithin wollt ich entfliehen, in der Wüste einen Rastort suchen; SELA.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 55, 9, 'nach einem Zufluchtsorte für mich wollt’ ich eilen schneller als reißender Wind, als Sturm!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 55, 10, 'Vernichte, Allherr, entzweie ihre Zungen! Denn ich sehe Gewalttat und Hader in der Stadt.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 55, 11, 'Man macht bei Tag und bei Nacht die Runde um sie auf ihren Mauern, Unheil und Elend herrschen in ihrer Mitte.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 55, 12, 'Heilloses Treiben besteht in ihrem Innern, und von ihrem Marktplatz weicht nicht Bedrückung und Trug.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 55, 13, 'Denn nicht ein Feind ist’s, der mich schmäht – das wollt’ ich ertragen; nicht einer, der mich haßt, tut groß gegen mich – ich würde vor ihm mich verbergen;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 55, 14, 'nein, du bist’s, ein Mann meinesgleichen, mein Freund und trauter Bekannter,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 55, 15, 'die wir innigen Verkehr miteinander pflegten, zum Hause Gottes schritten im Festgetümmel.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 55, 16, 'Möge der Tod sie ereilen, mögen sie lebend zur Unterwelt fahren! Denn Bosheit herrscht in ihrer Wohnstatt, in ihrem Herzen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 55, 17, 'Ich aber rufe zu Gott, und der HERR wird mir helfen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 55, 18, 'Abends und morgens und mittags will ich klagen und seufzen, so wird er mein Flehen vernehmen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 55, 19, 'Er wird meine Seele erlösen zum Frieden, so daß sie nicht an mich können; denn ihrer sind viele gegen mich.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 55, 20, 'Gott wird mich hören, wird sie demütigen (ihnen Antwort geben), er, der von alters her auf dem Throne sitzt; SELA. sie wollen sich ja nicht ändern und Gott nicht fürchten.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 55, 21, 'Er hat die Hand an seine Freunde gelegt, hat seinen Bund entweiht.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 55, 22, 'Glatt sind die Schmeichlerworte seines Mundes, aber Krieg ist sein Sinnen; linder sind seine Reden als Öl, und sind doch gezückte Schwerter.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 55, 23, 'Wirf auf den HERRN deine Bürde: er wird dich aufrecht erhalten; er läßt den Gerechten nicht ewig wanken.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 55, 24, 'Ja du, Gott, wirst sie stürzen in die Tiefe des Grabes; die Männer des Blutvergießens und des Truges werden ihre Tage nicht auf die Hälfte bringen. Ich aber vertraue auf dich!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 56, 1, 'Dem Musikmeister, nach (der Singweise = Melodie) »Die stumme Taube der Ferne«; ein Lied von David, als die Philister ihn in Gath festgenommen hatten.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 56, 2, 'Sei mir gnädig, o Gott, denn Menschen stellen mir nach! Immerfort bedrängen mich Krieger.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 56, 3, 'Meine Feinde stellen mir immerfort nach, ja viele sind’s, die in Hochmut mich befehden.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 56, 4, 'In Zeiten, da mir angst ist, vertrau ich auf dich!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 56, 5, 'Mit Gottes Hilfe werde sein Wort ich rühmen. Auf Gott vertrau’ ich, fürchte mich nicht; was können Menschen mir antun?');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 56, 6, 'Allzeit suchen sie meiner Sache zu schaden; gegen mich ist all ihr Sinnen gerichtet auf Böses.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 56, 7, 'Sie rotten sich zusammen, lauern auf meine Schritte, dieweil sie nach dem Leben mir trachten.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 56, 8, 'Ob der Bosheit zahle ihnen heim, im Zorn laß die Völker niedersinken, o Gott!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 56, 9, 'Meines Elends Tage hast du gezählt, meine Tränen in deinem Krüglein gesammelt; ja gewiß, sie stehen in deinem Buche verzeichnet.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 56, 10, 'So werden denn meine Feinde weichen, sobald (zu Gott) ich rufe; dessen bin ich gewiß, daß Gott mir beisteht.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 56, 11, 'Mit Gottes Hilfe werde sein Wort ich rühmen, mit Hilfe des HERRN werde sein Wort ich rühmen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 56, 12, 'Auf Gott vertrau’ ich, fürchte mich nicht: was können Menschen mir antun?');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 56, 13, 'Mir obliegt es, dir, Gott, zu erfüllen meine Gelübde: Dankopfer ich will dir entrichten;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 56, 14, 'denn du hast meine Seele vom Tode errettet, ja, meine Füße vom Straucheln, daß ich wandeln soll vor Gottes Angesicht im Lichte der Lebenden.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 57, 1, 'Dem Musikmeister, nach (der Singweise = Melodie) »Vertilge nicht«; ein Lied Davids, als er vor Saul in die Höhle floh.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 57, 2, 'Erbarme dich meiner, o Gott, erbarme dich meiner! Denn bei dir sucht meine Seele Zuflucht, und im Schatten deiner Flügel will ich mich bergen, bis das Verderben vorübergezogen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 57, 3, 'Ich rufe zu Gott, dem Höchsten, zum Allherrn, der meine Sache hinausführt.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 57, 4, 'Er sendet vom Himmel und hilft mir, da der gierige Verfolger mich geschmäht hat! SELA. Es sendet Gott seine Gnade und Treue!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 57, 5, 'Mit meinem Leben liege ich mitten unter Löwen, inmitten haßerfüllter Feinde, unter Menschen, deren Zähne Speere und Pfeile und deren Zunge ein scharfes Schwert ist.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 57, 6, 'Erhebe dich über den Himmel hinaus, o Gott, über die ganze Erde (verbreite sich) deine Herrlichkeit!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 57, 7, 'Sie haben meinen Füßen ein Netz gestellt: meine Seele ist gebeugt; eine Grube haben sie vor mir gegraben: sie selbst sind mitten hineingestürzt. SELA.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 57, 8, 'Mein Herz ist getrost, o Gott, mein Herz ist getrost; singen will ich und spielen!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 57, 9, 'Wach auf, meine Seele, wacht auf, Harfe und Zither: ich will das Morgenrot wecken!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 57, 10, 'Ich will dich preisen unter den Völkern, Allherr, ich will dir lobsingen unter den Völkerschaften!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 57, 11, 'Denn groß bis zum Himmel ist deine Gnade, und bis an die Wolken geht deine Treue.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 57, 12, 'Erhebe dich über den Himmel hinaus, o Gott, über die ganze Erde (verbreite sich) deine Herrlichkeit!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 58, 1, 'Dem Musikmeister, nach (der Singweise = Melodie) »Vertilge nicht«; von David ein Lied.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 58, 2, 'Sprecht in Wahrheit ihr Recht, ihr Götter? Richtet ihr die Menschen gerecht?');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 58, 3, 'Ach nein, im Herzen schmiedet ihr Frevel, im Lande wägen eure Hände Gewalttat dar.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 58, 4, 'Abtrünnig sind die Gottlosen schon von Geburt an, schon vom Mutterleib an gehn die Lügenredner irre.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 58, 5, 'Gift haben sie in sich wie Schlangengift, sie gleichen der tauben Otter, die ihr Ohr verstopft,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 58, 6, 'die nicht hört auf die Stimme der Beschwörer, (auf die Stimme) des kundigen Bannspruchredners.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 58, 7, 'Zerschmettre ihnen, Gott, die Zähne im Munde, den jungen Löwen brich aus das Gebiß, o HERR!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 58, 8, 'Laß sie vergehen wie Wasser, das sich verläuft! Schießt er seine Pfeile ab: sie seien wie ohne Spitze!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 58, 9, 'Wie die Schnecke beim Kriechen zerfließt, so muß er zergehn, wie die Fehlgeburt eines Weibes, die das Licht nicht geschaut!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 58, 10, 'Bevor noch eure Töpfe den (brennenden) Stechdorn spüren, wird ihn, noch unverbrannt, die Zornglut hinwegstürmen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 58, 11, 'Der Gerechte wird sich freun, daß er Rache erlebt, seine Füße wird er baden im Blute des Frevlers,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 58, 12, 'und die Menschen werden bekennen: »Fürwahr, der Gerechte erntet noch Lohn! Fürwahr, noch gibt’s einen Gott, der auf Erden richtet!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 59, 1, 'Dem Musikmeister, nach (der Singweise = Melodie) »Vertilge nicht«; ein Lied von David, als Saul das Haus bewachen ließ, um ihn zu töten.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 59, 2, 'Rette mich von meinen Feinden, mein Gott! Sei mir ein Schutz vor meinen Widersachern!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 59, 3, 'Rette mich von den Übeltätern und hilf mir gegen die Blutmenschen!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 59, 4, 'Denn siehe, sie trachten mir nach dem Leben; Starke rotten sich gegen mich zusammen ohne mein Verschulden, o HERR, und ohne daß ich gefehlt.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 59, 5, 'Gegen einen Schuldlosen stürmen sie an und stellen sich auf: erwache, komm mir zu Hilfe und sieh darein!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 59, 6, 'Ja, du, o HERR, Gott der Heerscharen, Israels Gott, wache auf, um alle Heiden zu strafen! Verschone keinen der treulosen Frevler! SELA.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 59, 7, 'Jeden Abend kommen sie wieder, heulen wie Hunde und streifen umher in der Stadt.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 59, 8, 'Siehe, sie geifern mit ihrem Munde, Schwerter stecken in ihren Lippen, denn (sie denken): »Wer hört es?«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 59, 9, 'Doch du, o HERR, du lachest ihrer, spottest aller Heiden.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 59, 10, 'Meine Stärke, deiner will ich harren, denn Gott ist meine feste Burg.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 59, 11, 'Mein Gott kommt mir entgegen mit seiner Gnade; Gott läßt meine Lust mich sehn an meinen Feinden.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 59, 12, 'Töte sie nicht, daß mein Volk sie nicht vergesse! Treibe sie in die Irre durch deine Macht und stürze sie nieder, du, unser Schild, o Allherr!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 59, 13, 'Sündhaft ist ihr Mund, das Wort ihrer Lippen; drum laß sie sich fangen in ihrem Hochmut wegen der Flüche und Lügen, die sie reden!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 59, 14, 'Vertilge sie im Zorn, vertilge sie, daß sie nicht mehr sind! Laß sie inne werden, daß Gott in Jakob herrscht, bis an die Enden der Erde! SELA.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 59, 15, 'Jeden Abend kommen sie wieder, heulen wie Hunde und streifen umher in der Stadt;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 59, 16, 'sie schweifen umher nach Fraß und knurren, sind sie nicht satt geworden.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 59, 17, 'Ich aber will deine Stärke besingen und am Morgen ob deiner Gnade jubeln; denn du bist eine feste Burg für mich gewesen, eine Zuflucht zur Zeit meiner Drangsal.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 59, 18, 'Meine Stärke, dir will ich lobsingen! Denn Gott ist meine feste Burg, der Gott, der mir Gnade erweist.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 60, 1, 'Dem Musikmeister, nach (der Singweise = Melodie) »Lilie des Zeugnisses«; ein Lied Davids zum Lehren,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 60, 2, 'als er mit den Syrern von Mesopotamien und mit den Syrern von Zoba Krieg führte und Joab zurückkehrte und die Edomiter im Salztal schlug, zwölftausend Mann..');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 60, 3, 'Gott, du hast uns verworfen, uns zersprengt, du hast (uns) gezürnt: stelle uns wieder her!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 60, 4, 'Du hast das Land erschüttert, hast es zerrissen: o heile seine Risse, denn es wankt!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 60, 5, 'Dein Volk hast du Hartes erleben lassen, hast Taumelwein uns zu trinken gegeben;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 60, 6, 'doch deinen Getreuen hast eine Flagge du wehen lassen, damit sie sich flüchten konnten vor dem Bogen (des Feindes). SELA.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 60, 7, 'Daß deine Geliebten gerettet werden, hilf uns mit deiner Rechten, erhöre uns!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 60, 8, 'Gott hat in seiner Heiligkeit gesprochen: »(Als Sieger) will ich frohlocken, will Sichem verteilen und das Tal von Sukkoth (als Beutestück) vermessen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 60, 9, 'Mein ist Gilead, mein auch Manasse, und Ephraim ist meines Hauptes Schutzwehr, Juda mein Herrscherstab.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 60, 10, 'Moab (dagegen) ist mein Waschbecken, auf Edom werfe ich meinen Schuh; jauchze mir zu, Philisterland!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 60, 11, 'Wer führt mich hin zur festen Stadt, wer geleitet mich bis Edom?');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 60, 12, 'Hast nicht du uns, o Gott, verworfen und ziehst nicht aus, o Gott, mit unsern Heeren?');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 60, 13, 'O schaff uns Hilfe gegen den Feind! denn nichtig ist Menschenhilfe.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 60, 14, 'Mit Gott werden wir Taten vollführen, und er wird unsre Bedränger zertreten.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 61, 1, 'Dem Musikmeister über das Saitenspiel; von David.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 61, 2, 'Höre, o Gott, mein lautes Rufen, achte auf mein Gebet!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 61, 3, 'Vom Ende der Erde ruf’ ich zu dir, da mein Herz verschmachtet. Auf einen Felsen, der mir zu hoch ist, wollest du mich führen!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 61, 4, 'Denn du bist mir stets eine Zuflucht gewesen, ein starker Turm vor dem Feinde.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 61, 5, 'Könnt’ ich doch allzeit weilen in deinem Zelt, im Schutze deiner Flügel mich bergen! SELA.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 61, 6, 'Denn du, Gott, hörst auf meine Gelübde, hast Besitz (mir) gewährt, wie die ihn erhalten, die deinen Namen fürchten.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 61, 7, 'Füge neue Tage den Tagen des Königs hinzu, laß seine Jahre dauern für und für!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 61, 8, 'Ewig möge er thronen vor Gottes Angesicht! Entbiete Gnade und Treue, daß sie ihn behüten!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 61, 9, 'Dafür will ich ewig deinem Namen lobsingen, auf daß ich meine Gelübde bezahle Tag für Tag.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 62, 1, 'Dem Musikmeister über die Jeduthuniden; ein Psalm Davids.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 62, 2, 'Nur (im Aufblick) zu Gott ist meine Seele still: von ihm kommt meine Hilfe;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 62, 3, 'nur er ist mein Fels und meine Hilfe, meine Burg: ich werde nicht allzusehr wanken.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 62, 4, 'Wie lange noch lauft ihr Sturm gegen einen Mann, wollt ihn niederschlagen allesamt wie eine sinkende Wand, eine dem Einsturz nahe Mauer?');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 62, 5, 'Ja, von seiner Höhe planen sie ihn zu stoßen; Lügen sind ihre Lust; mit dem Munde segnen sie, doch im Herzen fluchen sie. SELA.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 62, 6, 'Nur (im Aufblick) zu Gott sei still, meine Seele! Denn von ihm kommt meine Hoffnung;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 62, 7, 'nur er ist mein Fels und meine Hilfe, meine Burg: ich werde nicht wanken.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 62, 8, 'Auf Gott beruht mein Heil und meine Ehre; mein starker Fels, meine Zuflucht liegt in Gott.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 62, 9, 'Vertraut auf ihn zu aller Zeit, ihr Volksgenossen, schüttet vor ihm euer Herz aus: Gott ist unsere Zuflucht. SELA.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 62, 10, 'Nur ein Hauch sind Menschensöhne, ein Trug sind Herrensöhne; auf der Waage schnellen sie empor, sind allesamt leichter als ein Hauch.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 62, 11, 'Verlaßt euch nicht auf Erpressung und setzt nicht eitle Hoffnung auf Raub; wenn der Reichtum sich mehrt, so hängt das Herz nicht daran!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 62, 12, 'Eins ist’s, was Gott gesprochen, und zweierlei ist’s, was ich vernommen, daß die Macht bei Gott steht.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 62, 13, 'Und bei dir, o Allherr, steht auch die Gnade: ja, du vergiltst einem jeden nach seinem Tun.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 63, 1, 'Ein Psalm Davids, als er in der Wüste Juda war.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 63, 2, 'O Gott, du bist mein Gott: dich suche ich, es dürstet nach dir meine Seele; es lechzt nach dir mein Leib wie dürres, schmachtendes, wasserloses Land.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 63, 3, 'So hab’ ich nach dir im Heiligtum ausgeschaut, um deine Macht und Herrlichkeit zu erblicken;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 63, 4, 'denn deine Gnade ist besser als das Leben: meine Lippen sollen dich rühmen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 63, 5, 'So will ich dich preisen mein Leben lang, in deinem Namen meine Hände erheben.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 63, 6, 'Wie an Mark und Fett ersättigt sich meine Seele, und mit jubelnden Lippen lobpreist mein Mund,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 63, 7, 'so oft ich deiner gedenke auf meinem Lager, in den Stunden der Nacht über dich sinne;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 63, 8, 'denn du bist mir ein Helfer gewesen, und im Schatten deiner Flügel darf ich jubeln.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 63, 9, 'Meine Seele klammert sich an dich, aufrecht hält mich deine rechte Hand.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 63, 10, 'Doch sie, die nach dem Leben mir trachten, mich zu verderben, sie werden in der Erde unterste Tiefen fahren.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 63, 11, 'Man wird sie der Schärfe des Schwerts überliefern; die Beute der Schakale werden sie sein.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 63, 12, 'Der König dagegen wird Gottes sich freuen: Ruhm wird ernten ein jeder, der bei ihm schwört; den Lügnern dagegen wird der Mund gestopft werden.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 64, 1, 'Dem Musikmeister, ein Psalm Davids.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 64, 2, 'Höre, o Gott, meine Stimme, wenn ich klage, vor dem Feinde, der mich schreckt, behüte mein Leben!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 64, 3, 'Schirme mich vor den Plänen der bösen Buben, vor der lärmenden Rotte der Übeltäter,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 64, 4, 'die ihre Zunge schärfen wie ein Schwert, giftige Worte als ihre Pfeile auf den Bogen legen,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 64, 5, 'um im Versteck auf den Frommen zu schießen: unversehens schießen sie auf ihn ohne Scheu.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 64, 6, 'Sie ermutigen sich zu bösem Anschlag, verabreden, heimlich Schlingen zu legen; sie denken: »Wer wird sie sehen?«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 64, 7, 'Sie sinnen auf Freveltaten: »Wir sind fertig, der Plan ist fein erdacht!« Und das Innere jedes Menschen und das Herz sind unergründlich.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 64, 8, 'Da trifft sie Gott mit dem Pfeil, urplötzlich fühlen sie sich verwundet:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 64, 9, 'ihre eigene Zunge hat sie zu Fall gebracht; alle, die sie sehen, schütteln das Haupt.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 64, 10, 'Da fürchten sich alle Menschen und bekennen: »Das hat Gott getan!« und erwägen sein Walten.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 64, 11, 'Der Gerechte freut sich des HERRN und nimmt seine Zuflucht zu ihm, und alle redlichen Herzen preisen sich glücklich.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 65, 1, 'Dem Musikmeister; ein Psalm Davids, ein Lied.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 65, 2, 'Dir gebührt Lobpreis, o Gott, in Zion, und dir muß man Gelübde bezahlen,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 65, 3, 'der du Gebete erhörst: zu dir kommt alles Fleisch');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 65, 4, 'um der Verschuldungen willen. Wenn uns unsere Sünden zu drückend werden, du, HERR, vergibst sie.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 65, 5, 'Wohl dem, den du erwählst und zu dir nahen läßt, daß er in deinen Vorhöfen weilen darf! Wir wollen reichlich uns laben am Segen deines Hauses, deines heiligen Tempels!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 65, 6, 'Durch Wundertaten erhörst du uns in Gerechtigkeit, du Gott unsers Heils, du Zuversicht aller Enden der Erde und der fernsten Meere,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 65, 7, 'der da feststellt die Berge durch seine Kraft, umgürtet mit Stärke,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 65, 8, 'der da stillt das Brausen der Meere, das Brausen ihrer Wogen und das Toben der Völker,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 65, 9, 'so daß die Bewohner der Enden (des Erdrunds) sich fürchten vor deinen Zeichen; die fernsten Länder des Ostens und Westens bringst du zu lautem Jauchzen. –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 65, 10, 'Du hast das Land gesegnet, es strömt schier über; du hast es gar reich gemacht – der Gottesbach hat Wasser in Fülle gehabt –; du hast ihre Feldfrucht wohl geraten lassen, denn also hast du das Land instand gesetzt;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 65, 11, 'du hast seine Furchen getränkt, seine Schollen geebnet, durch Regen es weich gemacht, sein Gewächs gesegnet.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 65, 12, 'Du hast das Jahr gekrönt mit deiner Güte, und deine Spuren triefen von Fett.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 65, 13, 'Es triefen die Anger der Steppe, und mit Jubel umgürten sich die Hügel;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 65, 14, 'die Auen bekleiden sich mit Herden, und die Täler hüllen sich in Korn: man jauchzt einander zu und singt.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 66, 1, 'Dem Musikmeister; ein Lied, ein Psalm. Jauchzet Gott, ihr Lande alle!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 66, 2, 'Lobsinget der Ehre seines Namens, macht seinen Lobpreis herrlich!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 66, 3, 'Sprechet zu Gott: »Wie wunderbar ist dein Walten! Ob der Fülle deiner Macht huldigen dir sogar deine Feinde.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 66, 4, 'Alle Lande müssen vor dir sich niederwerfen und dir lobsingen, lobsingen deinem Namen!« SELA.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 66, 5, 'Kommt und schauet die Großtaten Gottes, der wunderbar ist im Walten über den Menschenkindern!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 66, 6, 'Er wandelte das Meer in trocknes Land, so daß man den Strom zu Fuß durchzog; drum wollen wir uns freun!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 66, 7, 'Ewig herrscht er in seiner Macht; seine Augen haben acht auf die Völker: die Widerspenstigen dürfen sich nicht stolz erheben. SELA.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 66, 8, 'Preiset, ihr Völker, unsern Gott, laßt laut seinen Ruhm erschallen,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 66, 9, 'ihn, der unsre Seele am Leben erhalten und unsern Fuß nicht hat wanken lassen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 66, 10, 'Wohl hast du uns geprüft, o Gott, uns geläutert, wie man Silber läutert;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 66, 11, 'du hast uns ins Netz geraten lassen, hast drückende Last auf unsern Rücken gelegt;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 66, 12, 'Menschen hast du hinfahren lassen über unser Haupt, durch Feuer und Wasser haben wir ziehen müssen: doch endlich hast du uns ins Freie hinausgeführt.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 66, 13, 'Ich komme mit Brandopfern in dein Haus, entrichte dir meine Gelübde,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 66, 14, 'zu denen meine Lippen sich verpflichtet haben, und die mein Mund verheißen in meiner Not.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 66, 15, 'Brandopfer von Mastvieh will ich dir bringen samt dem Opferduft von Widdern; Rinder samt Böcken will ich zubereiten. SELA.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 66, 16, 'Kommt her und höret, ihr Gottesfürchtigen alle: ich will erzählen, was er an meiner Seele getan!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 66, 17, 'Zu ihm hab’ ich laut mit meinem Munde gerufen, während Lobpreis schon auf meiner Zunge lag.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 66, 18, 'Wäre mein Sinn auf Böses gerichtet gewesen, so hätte der Allherr mich nicht erhört.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 66, 19, 'Aber Gott hat mich erhört, hat geachtet auf mein lautes Flehen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 66, 20, 'Gepriesen sei Gott, der mein Flehen nicht verworfen und seine Gnade mir nicht versagt hat!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 67, 1, 'Dem Musikmeister, mit Saitenspiel; ein Psalm, ein Lied.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 67, 2, 'Gott sei uns gnädig und segne uns! Er lasse sein Angesicht bei uns leuchten, SELA,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 67, 3, 'daß man auf Erden dein Walten erkenne, unter allen Heidenvölkern dein Heil!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 67, 4, 'Preisen müssen dich, Gott, die Völker, preisen die Völker allesamt;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 67, 5, 'sich freuen müssen die Völkerschaften und jubeln, weil du die Völker gerecht richtest und leitest die Völkerschaften auf Erden. SELA.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 67, 6, 'Preisen müssen dich, Gott, die Völker, preisen die Völker allesamt!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 67, 7, 'Das Land hat seinen Ertrag gespendet: gesegnet hat uns Gott, unser Gott.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 67, 8, 'Es segne uns Gott, und fürchten müssen ihn alle Enden der Erde!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 68, 1, 'Dem Musikmeister, von David ein Psalm, ein Lied.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 68, 2, 'Gott steht auf: da zerstieben seine Feinde, und die ihn hassen, fliehen vor seinem Angesicht.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 68, 3, 'Wie Rauch verweht, so verwehst du sie; wie Wachs zerschmilzt vor dem Feuer, so kommen die Gottlosen um vor Gottes Angesicht;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 68, 4, 'die Gerechten aber freuen sich, jubeln vor Gottes Angesicht und frohlocken voller Freude.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 68, 5, 'Singet Gott, lobsingt seinem Namen, machet Bahn ihm, der durch Wüsten einherfährt ›HERR‹ ist sein Name –, und jauchzet vor seinem Angesicht!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 68, 6, 'Ein Vater der Waisen, ein Richter der Witwen ist Gott in seiner heiligen Wohnstatt.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 68, 7, 'Gott verhilft den Vereinsamten zum Hausstand, führt Gefangne heraus zum Wohlergehn; doch Widerstrebende müssen wohnen in dürrem Land.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 68, 8, 'Als du auszogst, Gott, an der Spitze deines Volkes, einherschrittest durch die Wüste: (SELA)');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 68, 9, 'da bebte die Erde, da troffen die Himmel vor Gottes Angesicht, der Sinai dort vor dem Angesicht Gottes, des Gottes Israels.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 68, 10, 'Regen in Fülle ließest du strömen, o Gott; dein Eigentumsvolk, sooft ermattet es war: du machtest es wieder stark.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 68, 11, 'Deine Herde fand Wohnung darin, durch deine Güte stelltest du, Gott, die Schwachen wieder her.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 68, 12, 'Der Allherr ließ Siegesruf erschallen der Siegesbotinnen war eine große Schar –:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 68, 13, '»Die Könige der Heere fliehen, sie fliehn, und die Hausfrau teilt die Beute aus.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 68, 14, '»Wollt ihr zwischen den Hürden liegen bleiben?« – »Die Flügel der Tauben, mit Silber überzogen, und ihr Gefieder gelblich schimmernd von Gold.« –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 68, 15, '»Als Könige dort der Allmächtge zerstreute, da fand ein Schneegestöber statt auf dem Zalmon.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 68, 16, 'Du Gottesberg, Basansberg, du gipfelreicher Berg, Basansberg:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 68, 17, 'warum blickt ihr neidisch, ihr gipfelreichen Berge, auf den Berg, den Gott zum Wohnsitz erkoren? Ja, ewig wird der HERR dort wohnen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 68, 18, 'Der Kriegswagen Gottes sind vieltausendmal tausend; der Allherr ist unter ihnen, ein Sinai an Heiligkeit.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 68, 19, 'Du bist zur Höhe aufgefahren, hast Gefangene weggeführt, hast Gaben unter den Menschen angenommen; ja auch die Widerstrebenden müssen wohnen bei Gott dem HERRN.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 68, 20, 'Gepriesen sei der Allherr! Tag für Tag! Uns trägt der Gott, der unsre Hilfe ist. SELA.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 68, 21, 'Dieser Gott ist uns ein rettender Gott, und Gott der HERR weiß Rat auch gegen den Tod.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 68, 22, 'Ja, Gott zerschmettert das Haupt seiner Feinde, den Haarscheitel dessen, der in seinen Sünden einhergeht.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 68, 23, 'Der Allherr hat verheißen: »Aus Basan bring’ ich (sie) heim, ja bringe (sie) heim aus den Tiefen des Meeres,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 68, 24, 'auf daß du in Blut deine Füße badest und die Zunge deiner Hunde an den Feinden sich letze.« –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 68, 25, 'Man hat, o Gott, deinen Festzug gesehn, den Festzug meines Gottes, meines Königs, im Heiligtum:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 68, 26, 'An der Spitze zogen Sänger, dahinter Saitenspieler inmitten paukenschlagender Jungfrauen:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 68, 27, '»In Versammlungen preiset Gott, den Allherrn, ihr aus Israels Born!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 68, 28, 'Dort schritt Benjamin hin, der Jüngste, der sie doch beherrscht hat, die Fürsten Judas nach ihrer großen Menge, Sebulons Fürsten, die Fürsten von Naphthali.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 68, 29, 'Entbiete, o Gott, deine Macht, erhalte in Kraft, o Gott, was du uns erwirkt hast!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 68, 30, 'Um deines Tempels willen müssen Könige dir Geschenke hinauf nach Jerusalem bringen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 68, 31, 'Bedrohe das Tier des Schilfrohrs, die Rotte der Stiere samt den Völkerkälbern, die mit Silberbarren sich unterwerfen; zerstreue die Völker, die Freude an Kriegen haben!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 68, 32, 'Kommen werden die Edlen aus Ägypten, Äthiopien eilt mit vollen Händen Gott entgegen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 68, 33, 'Ihr Königreiche der Erde, singet Gott, lobsinget dem Allherrn, SELA,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 68, 34, 'ihm, der einherfährt im höchsten Himmel der Urzeit! Horch! Er läßt seine Stimme erschallen, den rollenden Donner!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 68, 35, 'Gebt Gott die Macht! Über Israel waltet seine Hoheit und seine Macht in den Wolken.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 68, 36, 'Furchtbar bist du, Gott, von deinem Heiligtum aus! Israels Gott, er ist’s, der Macht verleiht und Stärke seinem Volk: gepriesen sei Gott!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 69, 1, 'Dem Musikmeister, nach (der Singweise = Melodie) »Lilien«, von David.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 69, 2, 'Hilf mir, o Gott, denn die Wasser gehen mir bis ans Leben!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 69, 3, 'Ich versinke im tiefen Schlamm, wo kein Grund ist; in Wassertiefen bin ich geraten, und die Flut überströmt mich.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 69, 4, 'Müde bin ich von (allem) Schreien, meine Kehle ist heiser; erloschen sind mir die Augen, während ich harre auf meinen Gott.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 69, 5, 'Größer als die Zahl der Haare auf meinem Haupt ist die Zahl derer, die ohne Ursach’ mich hassen; mächtig sind meine Gegner, die ohne Grund mich befeinden: wo ich gar nicht geraubt, da soll Ersatz ich leisten!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 69, 6, 'Du, o Gott, du weißt um meine Torheit, und meine Vergehen sind dir nicht verborgen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 69, 7, 'Laß nicht enttäuscht an mir werden, die auf dich hoffen, o Gott, o HERR der Heerscharen! Laß nicht beschämt an mir werden, die dich, Gott Israels, suchen!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 69, 8, 'Denn um deinetwillen trage ich Schmach, (für dich) bedeckt Beschämung mein Antlitz;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 69, 9, 'ein Fremdling bin ich meinen Brüdern geworden und unbekannt den Söhnen meiner Mutter.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 69, 10, 'Denn der Eifer um dein Haus hat mich verzehrt, und die Schmähungen derer, die dich schmähen, haben mich getroffen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 69, 11, 'Ich weinte und kasteite mich durch Fasten, doch es brachte mir nur Beschimpfung ein;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 69, 12, 'als ein Trauergewand zu meinem Kleid ich machte, da wurde ich ihnen zum Spottlied;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 69, 13, 'es schwatzten von mir die Leute auf dem Markt, und Schmachlieder sangen von mir die Zecher beim Wein.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 69, 14, 'Ich aber richte mein Gebet an dich, o HERR, zur Zeit, da dir es wohlgefällig ist; o Gott, nach deiner großen Gnade erhöre mich, nach deiner heilspendenden Treue!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 69, 15, 'Zieh mich heraus aus dem Schlamm, daß ich nicht versinke, laß Rettung mich finden von meinen Hassern und aus den Wassertiefen!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 69, 16, 'Laß die Wasserflut mich nicht überströmen und die Tiefe mich nicht verschlingen und den Abgrund seinen Schlund nicht über mir schließen!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 69, 17, 'Erhöre mich, HERR, denn deine Güte ist köstlich! Nach deinem großen Erbarmen wende dich mir zu');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 69, 18, 'und verbirg dein Angesicht nicht vor deinem Knecht, denn ich bin in Not: erhöre mich eiligst!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 69, 19, 'Nahe dich meiner Seele, erlöse sie, um meiner Feinde willen mach mich frei!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 69, 20, 'Du weißt um meine Schmach, um meine Schande und Beschimpfung; meine Feinde sind alle dir wohlbekannt.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 69, 21, 'Die Schmach hat mir das Herz gebrochen, so daß ich verzweifle; ich hoffte auf Mitleid, aber vergebens, und auf Tröster, doch ich habe keine gefunden;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 69, 22, 'nein, sie haben mir Gift in die Speise getan und Essig mich trinken lassen für meinen Durst.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 69, 23, 'Möge ihr Tisch vor ihnen zum Fangnetz werden und ihnen, den Sichren, zum Fallstrick!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 69, 24, 'Laß ihre Augen dunkel werden, daß sie nicht sehen, und ihre Hüften laß immerdar wanken!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 69, 25, 'Gieße über sie deinen Grimm aus, und deines Zornes Glut erreiche sie!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 69, 26, 'Ihre Behausung müsse zur Öde werden, in ihren Zelten kein Bewohner sein!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 69, 27, 'Denn den du selbst geschlagen hast, verfolgen sie, und vom Weh der durch dich Verwundeten schwatzen sie.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 69, 28, 'Füge noch Schuld zu ihrer Verschuldung hinzu und laß sie nicht kommen zur Gerechtigkeit vor dir!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 69, 29, 'Sie müssen ausgelöscht werden aus dem Buche des Lebens und nicht eingeschrieben werden mit den Gerechten!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 69, 30, 'Doch ich bin elend und schmerzbeladen: deine Hilfe, Gott, möge mich sicherstellen!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 69, 31, 'Ich will den Namen Gottes preisen in Liedern, will hoch ihn rühmen mit Danksagung;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 69, 32, 'das wird dem HERRN willkommner sein als Rinder, als Farren mit Hörnern und gespaltnen Hufen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 69, 33, 'Wenn die Bedrückten es sehen, so werden sie sich freuen: ihr, die ihr Gott sucht: euer Herz lebe auf!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 69, 34, 'Denn der HERR erhört die Armen, und seine Gefangenen läßt er nicht unbeachtet.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 69, 35, 'Es mögen ihn preisen Himmel und Erde, die Meere und alles, was in ihnen sich regt!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 69, 36, 'Denn Gott wird Zion retten und Judas Städte wieder erbaun, daß man daselbst wohne und das Land besitze;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 69, 37, 'und der Nachwuchs seiner Knechte wird es erben, und die seinen Namen lieben, werden darin wohnen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 70, 1, 'Dem Musikmeister, von David; bei Darbringung des Duftopfers.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 70, 2, 'Gott, eile zu meiner Rettung, HERR, eile zu meiner Hilfe herbei!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 70, 3, 'Laß alle beschämt und schamrot werden, die nach dem Leben mir stehn (um es auszutilgen)! Laß mit Schande beladen abziehn, die mein Unglück wünschen!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 70, 4, 'Laß zurück sich wenden ob ihrer Schmach, die über mich rufen: »Haha, haha!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 70, 5, 'Laß jubeln und deiner sich freuen alle, die dich suchen! Laß alle, die nach deinem Heil verlangen, immerdar bekennen: »Groß ist Gott!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 70, 6, 'Doch ich bin elend und arm: o Gott, eile zu mir! Meine Hilfe und mein Retter bist du: o HERR, säume nicht!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 71, 1, 'Bei dir, HERR, suche ich Zuflucht: laß mich nimmermehr enttäuscht werden!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 71, 2, 'Nach deiner Gerechtigkeit rette und befreie mich, neige dein Ohr mir zu und hilf mir!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 71, 3, 'Sei mir ein schützender Fels, zu dem ich allzeit fliehen kann; du hast ja geboten, mich zu retten, denn mein Fels und meine Burg bist du.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 71, 4, 'Mein Gott, errette mich aus des Gottlosen Hand, aus der Faust des Frevlers und Gewaltmenschen!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 71, 5, 'Denn du bist meine Hoffnung, HERR, mein Gott, du meine Zuversicht von Jugend an.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 71, 6, 'Auf dich hab’ ich mich gestützt seit meiner Geburt; aus dem Mutterschoß hast du mich ans Licht gezogen: dir hat mein Lobpreis immer gegolten.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 71, 7, 'Wie ein Wunder komme ich vielen vor, doch du bist meine starke Zuflucht.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 71, 8, 'Mein Mund ist deines Ruhmes voll, allzeit voll von deiner Verherrlichung.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 71, 9, 'Verwirf mich nicht in den Tagen des Alters, beim Schwinden meiner Kraft verlaß mich nicht!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 71, 10, 'Denn schon verhandeln meine Feinde über mich, und die den Tod mir wünschen, beraten sich zusammen');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 71, 11, 'und sagen: »Gott hat ihn verlassen: verfolgt und ergreift ihn, denn er hat keinen Retter!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 71, 12, 'O Gott, bleib du nicht fern von mir, mein Gott, eil’ mir zu Hilfe!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 71, 13, 'Es müssen enttäuscht und vernichtet werden, die mich befeinden! Laß alle in Schmach und Schande sich hüllen, die mein Unglück suchen!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 71, 14, 'Ich aber will immerdar harren und all deinen Ruhm noch mehren.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 71, 15, 'Mein Mund soll deine Gerechtigkeit künden, allzeit deine Heilserweise, denn ich vermag sie nicht zu zählen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 71, 16, 'Kommen will ich mit den Machttaten Gottes des HERRN, will preisen deine Gerechtigkeit, dich allein.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 71, 17, 'Du hast mich, o Gott, von Jugend auf gelehrt, und bis hierher habe ich deine Wunder verkündet;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 71, 18, 'doch auch bis zum Greisenalter und grauen Haar verlaß mich nicht, o Gott, auf daß ich deinen Arm verkünde den Zeitgenossen und allen, die noch kommen werden, deine Macht.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 71, 19, 'Gott, deine Gerechtigkeit reicht bis hoch an den Himmel; der du große Dinge getan, o Gott, wer ist dir gleich?');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 71, 20, 'Du hast viel Not und Leid uns fühlen lassen: du wirst uns auch wieder beleben und aus den Tiefen der Erde empor uns führen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 71, 21, 'Du wirst mich um so höher erheben und mit Trost dich wieder zu mir wenden.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 71, 22, 'So will denn auch ich dich preisen mit Saitenspiel, für deine Treue dir danken, mein Gott; ich will auf der Zither dir spielen, du Heiliger Israels.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 71, 23, 'Jubeln sollen meine Lippen, wenn ich dir spiele, und zugleich meine Seele, die du erlöst hast;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 71, 24, 'auch meine Zunge soll allezeit von deiner Gerechtigkeit reden, denn enttäuscht, denn schamrot sind geworden, die mein Unglück suchten.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 72, 1, 'Von Salomo. Gott, dein richterlich Walten verleihe dem König und deine Gerechtigkeit dem Königssohn,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 72, 2, 'daß er dein Volk mit Gerechtigkeit richte und deine Elenden nach dem Recht!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 72, 3, 'Laß die Berge dem Volke Frieden tragen und die Hügel sich kleiden in Gerechtigkeit!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 72, 4, 'Er schaffe Recht den Elenden im Volk, er helfe den armen Leuten und zertrete den Bedrücker.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 72, 5, 'Möge er leben, solange die Sonne scheint und der Mond (uns leuchtet), von Geschlecht zu Geschlecht!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 72, 6, 'Er möge sein wie Regen für frischgemähte Wiesen, wie Regenschauer, die das Land besprengen!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 72, 7, 'In seinen Tagen möge der Gerechte blühen und Friede in Fülle bestehn, bis kein Mond mehr scheint.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 72, 8, 'Er herrsche von Meer zu Meer und vom Euphratstrom bis hin an die Enden der Erde!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 72, 9, 'Vor ihm müssen die Steppenvölker die Knie beugen und seine Feinde den Staub lecken;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 72, 10, 'die Könige von Tharsis und den Meeresländern müssen Geschenke ihm bringen, die Herrscher von Saba und Seba Abgaben entrichten;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 72, 11, 'ja huldigen müssen ihm alle Könige, die Völker alle ihm dienen!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 72, 12, 'Denn er wird den Armen retten, der um Hilfe schreit, den Leidenden und den, der keinen Helfer hat.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 72, 13, 'Er wird sich erbarmen des Schwachen und Armen und Hilfe gewähren den Seelen der Armen;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 72, 14, 'aus Bedrückung und Gewalttat wird er ihre Seelen erlösen, und ihr Blut wird kostbar sein in seinen Augen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 72, 15, 'So lebe er denn, und man gebe ihm vom Golde aus Saba, man bete immerdar für ihn und segne ihn allezeit!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 72, 16, 'Fülle von Korn möge sein im Lande bis auf die Gipfel der Berge, es rausche seine Frucht wie der Libanon! Und aus den Städten blühe das Volk hervor so zahlreich wie das Gras der Erde!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 72, 17, 'Sein Name möge ewig bestehn: solange die Sonne scheint, lebe sein Name fort, so daß man in ihm sich Segen wünscht und alle Völker ihn glücklich preisen!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 72, 18, 'Gepriesen sei Gott der HERR, der Gott Israels, der Wunder vollbringt, er allein!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 72, 19, 'Und gepriesen sei sein herrlicher Name in Ewigkeit, und die ganze Erde sei seiner Herrlichkeit voll! Amen, ja Amen! –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 72, 20, 'Zu Ende sind die Gebete Davids, des Sohnes Isais.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 73, 1, 'Ein Psalm von Asaph. Dennoch ist Gott voll Güte gegen den Frommen, der Herr gegen alle, die reinen Herzens sind.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 73, 2, 'Doch ich – fast wär’ ich gestrauchelt mit meinen Füßen, nichts fehlte, so wären meine Schritte ausgeglitten;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 73, 3, 'denn ich ereiferte mich über die Großsprecher, wenn ich sehen mußte der Gottlosen Wohlergehn.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 73, 4, 'Denn bis zu ihrem Tode leiden sie keine Schmerzen, und wohlgenährt ist ihr Leib;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 73, 5, 'Unglück trifft sie nicht wie andere Sterbliche, und sie werden nicht geplagt wie sonst die Menschen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 73, 6, 'Drum ist auch Hochmut ihr Halsgeschmeide, und Gewalttat ist das Kleid, das sie umhüllt.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 73, 7, 'Aus strotzendem Antlitz tritt ihr Auge hervor, die Gebilde ihres Herzens wallen über.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 73, 8, 'Sie höhnen und reden in Bosheit (nur) von Gewalttat, führen Reden von oben herab;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 73, 9, 'gegen den Himmel richten sie ihren Mund, und ihre Zunge ergeht sich frei auf Erden.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 73, 10, 'Darum wendet das Volk sich ihnen zu und schlürft das Wasser (ihrer Lehren) in vollen Zügen;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 73, 11, 'sie sagen: »Wie sollte Gott es wissen, und wie sollte der Höchste Kenntnis davon haben?«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 73, 12, 'Seht, so treiben’s die Gottlosen, und, immer in Sicherheit lebend, häufen sie Reichtum an.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 73, 13, 'Ach, ganz umsonst hab’ ich rein mein Herz erhalten und in Unschuld meine Hände gewaschen;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 73, 14, 'ich ward ja doch vom Unglück allzeit geplagt, und alle Morgen war meine Züchtigung da.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 73, 15, 'Doch hätt’ ich gesagt: »Ich will auch so reden!«, so hätt’ ich treulos verleugnet deiner Söhne Geschlecht.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 73, 16, 'So sann ich denn nach, um dies zu begreifen, doch es war zu schwer für mein Verständnis,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 73, 17, 'bis ich eindrang in die Heiligtümer Gottes und achtgab auf der Gottlosen Endgeschick.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 73, 18, 'Fürwahr, auf schlüpfrigen Boden stellst du sie, läßt sie fallen, daß sie in Trümmer zergehn.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 73, 19, 'Wie werden sie doch im Nu vernichtet, weggerafft, und nehmen ein Ende mit Schrecken!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 73, 20, 'Wie ein Traumbild gleich nach dem Erwachen verfliegt, so läßt du, o Allherr, beim Wachwerden ihr Bild verschwinden.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 73, 21, 'Wenn mein Herz sich nun noch verbitterte und ich in meinem Innern empört mich fühlte,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 73, 22, 'so wär’ ich ein ganzer Tor und bar der Einsicht, benähme mich wie ein vernunftloses Tier gegen dich.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 73, 23, 'Doch nein, ich bleibe stets mit dir verbunden, du hältst mich fest bei meiner rechten Hand;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 73, 24, 'du leitest mich nach deinem Ratschluß und nimmst mich endlich auf in die Herrlichkeit.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 73, 25, 'Wen hätt’ ich sonst noch im Himmel? Und außer dir erfreut mich nichts auf Erden.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 73, 26, 'Mag Leib und Seele mir verschmachten, bleibt Gott doch allzeit meines Herzens Fels und mein Teil.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 73, 27, 'Denn gewiß: wer von dir sich lossagt, der kommt um; du vernichtest alle, die treulos von dir abfallen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 73, 28, 'Mir aber ist Gottes Nähe beglückend: ich setze mein Vertrauen auf Gott den HERRN, um alle deine Werke zu verkünden.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 74, 1, 'Ein Lehrgedicht von Asaph. Warum hast du uns, o Gott, für immer verworfen, warum raucht dein Zorn gegen die Herde, die du weidest?');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 74, 2, 'Gedenke deiner Gemeinde, die vor alters du erworben, die zum Eigentumsvolk du dir erlöst hast! (Gedenke) des Berges Zion, auf dem du Wohnung genommen!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 74, 3, 'Lenk deine Schritte hinauf zu den ewigen Trümmern: ach, alles hat der Feind im Heiligtum zerstört!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 74, 4, 'Wild brüllen deine Feinde im Innern deiner Versammlungsstätte; haben dort ihre Fahnen als Siegeszeichen aufgestellt.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 74, 5, 'Es sieht sich an, als ob man die Äxte hoch geschwungen hätte im Dickicht des Waldes.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 74, 6, 'Und jetzt zerschlagen sie auch sein Schnitzwerk allzumal mit Beilen und Hämmern.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 74, 7, 'Sie haben dein Heiligtum in Brand gesteckt, bis zum Boden entweiht die Wohnung deines Namens.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 74, 8, 'Sie haben sich vorgenommen: »Wir rotten sie allesamt aus!« und haben alle Gottesstätten im Lande verbrannt.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 74, 9, 'Unsre (heiligen) Zeichen sehn wir nicht mehr, kein Prophet ist mehr da, und niemand weiß bei uns, wie lange das dauern soll.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 74, 10, 'Wie lange, o Gott, soll der Widersacher noch schmähen, der Feind deinen Namen immerfort lästern?');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 74, 11, 'Warum doch ziehst du deine Hand zurück? O zieh deine Rechte hervor aus dem Busen, mach ein Ende!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 74, 12, 'Gott ist ja doch mein König von alters her, Rettungstaten vollführt er inmitten des Landes.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 74, 13, 'Du hast das Meer durch deine Kraft gespalten, die Häupter der Drachen auf den Fluten zerschellt.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 74, 14, 'Du hast Leviathans Köpfe zermalmt, zum Fraß ihn hingegeben dem Volke der Wüstentiere.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 74, 15, 'Du hast Quellen und Bäche hervorbrechen lassen, du hast nieversiegende Ströme trocken gelegt.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 74, 16, 'Dein ist der Tag, dein auch die Nacht, du hast den Mond und die Sonne hingestellt.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 74, 17, 'Du hast der Erde rings die Grenzen festgesetzt, Sommer und Winter, du hast sie gebildet.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 74, 18, 'Denke daran: der Feind hat dich, o HERR, gehöhnt, und ein gottloses Volk deinen Namen gelästert!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 74, 19, 'Gib nicht den Raubtieren preis die Seele deiner Taube, vergiß nicht für immer das Leben deiner Dulder!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 74, 20, 'Blick hin auf den Bund! Denn angefüllt sind die Verstecke des Landes mit Stätten der Gewalttat.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 74, 21, 'Laß den Bedrängten nicht enttäuscht davongehn, der Arme und Bedrückte müsse deinen Namen rühmen!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 74, 22, 'Steh auf, Gott, verficht deine Sache! Gedenke der Schmach, die dich trifft von den Ruchlosen Tag für Tag!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 74, 23, 'Vergiß nicht das Geschrei deiner Feinde, das Toben deiner Gegner, das allzeit aufsteigt!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 75, 1, 'Dem Musikmeister, nach (der Singweise = Melodie) »Vertilge nicht«; ein Psalm von Asaph, ein Lied.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 75, 2, 'Wir preisen dich, Gott, wir preisen! Denn nahe ist uns dein Name: deine Wundertaten verkünden ihn.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 75, 3, '»Wenn ich die Zeit gekommen erachte, dann halte ich gerechtes Gericht.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 75, 4, 'Mag wanken die Erde mit allen ihren Bewohnern: ich bin’s, der ihre Säulen festgestellt. SELA.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 75, 5, 'Ich rufe den Stolzen zu: ›Seid nicht stolz!‹ und den Frevlern: ›Hebt den Kopf nicht hoch!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 75, 6, 'Hebt euren Kopf nicht gar so hoch, redet nicht vermessen mit gerecktem Hals!‹« –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 75, 7, 'Denn nicht vom Aufgang (der Sonne) noch vom Niedergang und nicht von der Wüste her kommt die Erhöhung;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 75, 8, 'nein, Gott ist’s, der da richtet: diesen erniedrigt und jenen erhöht er.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 75, 9, 'Denn ein Becher ist in der Hand des HERRN mit schäumendem Wein, voll von berauschender Mischung; und er schenkt daraus ein: sogar die Hefen davon müssen schlürfen und trinken alle Frevler der Erde.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 75, 10, 'Ich aber will das ewig verkünden, will lobsingen dem Gotte Jakobs;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 75, 11, 'und alle Hörner der Frevler will ich abhaun, doch die Hörner der Gerechten sollen erhöht sein.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 76, 1, 'Dem Musikmeister, mit Saitenspiel; ein Psalm von Asaph, ein Lied.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 76, 2, 'Allbekannt ist Gott in Juda, in Israel ist groß sein Name;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 76, 3, 'in Salem erstand seine Hütte und seine Wohnstatt in Zion.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 76, 4, 'Allda hat er zerbrochen des Bogens Blitze, Schild und Schwert und jegliche Kriegswehr. SELA.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 76, 5, 'Ruhmvoll bist du, herrlich von den ewigen Bergen her.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 76, 6, 'Ausgeplündert wurden die tapferen Streiter, sanken hin in ihren Todesschlaf, und all den Helden versagte der Arm:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 76, 7, 'vor deinem Drohruf, du Gott Jakobs, sanken in Betäubung so Wagen wie Rosse.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 76, 8, 'Ja du bist furchtbar, und wer kann bestehn vor dir, sobald dein Zorn entbrannt ist?');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 76, 9, 'Vom Himmel her kündigtest du das Gericht an: da erschrak die Erde und wurde still,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 76, 10, 'als Gott sich erhob zum Gerichtsvollzug, um allen Bedrückten auf Erden zu helfen. SELA.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 76, 11, 'Denn der Menschen Grimm wird dir zum Lobpreis, wenn zuletzt du dich gürtest mit Zornesflammen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 76, 12, 'Bringt Gelübde dar und erfüllt sie dem HERRN, eurem Gott: alle, die ihn rings umgeben, müssen Geschenke dem Schrecklichen bringen,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 76, 13, 'ihm, der den Hochmut der Fürsten dämpft und furchtbar ist den Königen der Erde.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 77, 1, 'Dem Musikmeister über die Jeduthuniden; von Asaph ein Psalm.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 77, 2, 'Laut ruf’ ich zu Gott, ja ich will schreien, laut ruf’ ich zu Gott: »Ach, höre mein Flehen!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 77, 3, 'Wenn Drangsalszeiten über mich kommen, such’ ich den Allherrn; meine Hand ist nachts ohn’ Ermatten ausgestreckt, meine Seele will sich nicht trösten lassen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 77, 4, 'Denk’ ich an Gott, so muß ich seufzen; sinne ich nach, so verzagt mein Geist. SELA.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 77, 5, 'Du hältst mir die Augenlider offen, ich bin voll Unruhe und kann nicht reden.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 77, 6, 'Ich überdenke die Tage der Vorzeit, die längst entschwundenen Jahre;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 77, 7, 'ich denke bei Nacht an mein Saitenspiel, ich sinne in meinem Herzen nach, und es grübelt mein Geist und fragt:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 77, 8, '»Wird der Allherr auf ewig verstoßen und niemals wieder Gnade üben?');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 77, 9, 'Ist seine Güte für immer erschöpft? sind seine Verheißungen abgetan für alle Zukunft?');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 77, 10, 'Hat Gott vergessen, gnädig zu sein, oder im Zorn sein Erbarmen verschlossen?« SELA.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 77, 11, 'Da sagte ich mir: »Das bekümmert mich schmerzlich, daß das Walten des Höchsten sich hat geändert.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 77, 12, 'Ich will gedenken der Taten des HERRN, will gedenken deiner Wunder von der Vorzeit her,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 77, 13, 'will sinnen über all dein Tun und deine großen Taten erwägen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 77, 14, 'O Gott, erhaben ist dein Weg: wo ist eine Gottheit so groß wie Gott?');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 77, 15, 'Du bist der Gott, der Wunder tut, du hast deine Macht an den Völkern bewiesen,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 77, 16, 'hast dein Volk erlöst mit starkem Arm, die Kinder Jakobs und Josephs. SELA.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 77, 17, 'Als die Wasser dich sahen, o Gott, als die Wasser dich sahen, erbebten sie, auch die Tiefen des Weltmeers zitterten;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 77, 18, 'die Wolken ergossen sich in strömenden Regen, das Gewölk ließ Donner erkrachen, und deine Pfeile fuhren einher;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 77, 19, 'deine Donnerstimme dröhnte am Himmelsgewölbe, Blitze erhellten den Erdkreis, es bebte und schwankte die Erde.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 77, 20, 'Durchs Meer ging dein Weg dahin und dein Pfad durch gewaltige Fluten; doch deine Spuren waren nicht zu erkennen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 77, 21, 'Du hast dein Volk geführt wie eine Herde unter Leitung von Mose und Aaron.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 1, 'Ein Lehrgedicht von Asaph. Gib acht, mein Volk, auf meine Belehrung, leiht euer Ohr den Worten meines Mundes!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 2, 'Ich will auftun meinen Mund zur Rede in Sprüchen, will Rätsel verkünden von der Vorzeit her.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 3, 'Was wir gehört und erfahren und unsere Väter uns erzählt haben,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 4, 'das wollen wir ihren Kindern nicht verschweigen, sondern dem künftgen Geschlecht verkünden die Ruhmestaten des HERRN und seine Stärke und die Wunder, die er getan hat.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 5, 'Denn er hat ein Zeugnis aufgerichtet in Jakob und festgestellt in Israel ein Gesetz, von dem er unsern Vätern gebot, es ihren Kindern kundzutun,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 6, 'auf daß die Nachwelt Kenntnis davon erhielte: die Kinder, die geboren würden, sollten aufstehn und ihren Kindern davon erzählen,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 7, 'daß sie auf Gott ihr Vertrauen setzten und die Taten Gottes nicht vergäßen und seine Gebote befolgten,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 8, 'daß sie nicht wie ihre Väter würden, ein trotziges und widerspenstiges Geschlecht, ein Geschlecht mit wankelmütigem Herzen, dessen Geist sich nicht zuverlässig zu Gott hielt.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 9, 'Ephraims Söhne, bogengerüstete Schützen, haben den Rücken gewandt am Tage des Kampfes.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 10, 'Sie hielten den gottgestifteten Bund nicht und wollten nicht wandeln in seinem Gesetz;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 11, 'nein, sie vergaßen seine Taten und seine Wunder, die er sie hatte sehen lassen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 12, 'Vor ihren Vätern hatte er Wunder getan im Lande Ägypten, im Gefilde von Zoan.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 13, 'Er spaltete das Meer und ließ sie hindurchziehn und türmte die Wasser auf wie einen Wall;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 14, 'er leitete sie bei Tag durch die Wolke und während der ganzen Nacht durch Feuerschein;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 15, 'er spaltete Felsen in der Wüste und tränkte sie reichlich wie mit Fluten;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 16, 'Bäche ließ er aus dem Felsen hervorgehn und Wasser gleich Strömen niederfließen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 17, 'Dennoch fuhren sie fort, gegen ihn zu sündigen, und widerstrebten dem Höchsten in der Wüste;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 18, 'ja, sie versuchten Gott in ihren Herzen, indem sie Speise verlangten für ihr Gelüst,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 19, 'und redeten gegen Gott mit den Worten: »Kann Gott wohl einen Tisch in der Wüste uns decken?');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 20, 'Wohl hat er den Felsen geschlagen, daß Wasser flossen heraus und Bäche sich ergossen; doch wird er auch vermögen Brot zu geben oder Fleisch seinem Volke zu schaffen?«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 21, 'Drum, als der HERR das hörte, ergrimmte er: Feuer entbrannte gegen Jakob, und Zorn stieg auf gegen Israel,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 22, 'weil sie an Gott nicht glaubten und auf seine Hilfe nicht vertrauten.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 23, 'Und doch gebot er den Wolken droben und tat die Türen des Himmels auf,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 24, 'ließ Manna auf sie regnen zum Essen und gab ihnen himmlisches Brotkorn:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 25, 'Engelspeise aßen sie allesamt, Reisekost sandte er ihnen zur Sättigung.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 26, 'Hinfahren ließ er den Ostwind am Himmel und führte durch seine Kraft den Südwind herbei;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 27, 'Fleisch ließ er auf sie regnen wie Staub und beschwingte Vögel wie Meeressand;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 28, 'mitten in ihr Lager ließ er sie fallen, rings um ihre Wohnungen her.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 29, 'Da aßen sie und wurden reichlich satt, und was sie gewünscht, gewährte er ihnen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 30, 'Noch hatten sie ihres Gelüsts sich nicht entschlagen, noch hatten sie ihre Speise in ihrem Munde,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 31, 'da stieg der Ingrimm Gottes gegen sie auf und erwürgte die kräftigen Männer unter ihnen und streckte Israels junge Mannschaft zu Boden.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 32, 'Trotz alledem sündigten sie weiter und glaubten nicht an seine Wunder.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 33, 'Drum ließ er ihre Tage vergehn wie einen Hauch und ihre Jahre in angstvoller Hast.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 34, 'Wenn er sie sterben ließ, dann fragten sie nach ihm und kehrten um und suchten Gott eifrig');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 35, 'und dachten daran, daß Gott ihr Fels sei und Gott, der Höchste, ihr Erlöser.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 36, 'Doch sie heuchelten ihm mit ihrem Munde und belogen ihn mit ihrer Zunge;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 37, 'denn ihr Herz hing nicht fest an ihm, und sie hielten nicht treu an seinem Bunde.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 38, 'Doch er war barmherzig, vergab die Schuld und vertilgte sie nicht, nein, immer wieder hielt er seinen Zorn zurück und ließ nicht seinen ganzen Grimm erwachen;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 39, 'denn er dachte daran, daß Fleisch sie waren, ein Windhauch, der hinfährt und nicht wiederkehrt.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 40, 'Wie oft widerstrebten sie ihm in der Wüste, kränkten sie ihn in der Öde!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 41, 'Und immer aufs neue versuchten sie Gott und betrübten den Heiligen Israels.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 42, 'Sie dachten nicht mehr an seine starke Hand, an den Tag, wo er sie vom Bedränger erlöste,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 43, 'als er seine Zeichen in Ägypten tat, seine Wunder im Gefilde von Zoan.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 44, 'Er verwandelte dort in Blut ihre Ströme, so daß man ihr fließendes Wasser nicht trinken konnte;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 45, 'er sandte unter sie Ungeziefer, das sie fraß, und Frösche, die ihnen Verderben brachten;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 46, 'er gab ihre Ernte den Freßgrillen preis und die Frucht ihrer Arbeit den Heuschrecken;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 47, 'er zerschlug ihre Reben mit Hagel, ihre Maulbeerfeigenbäume mit Schloßen;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 48, 'er gab ihr Vieh dem Hagel preis und ihren Besitz den Blitzen;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 49, 'er sandte gegen sie seines Zornes Glut, Wut und Grimm und Drangsal: eine Schar von Unglücksengeln;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 50, 'er ließ seinem Ingrimm freien Lauf, entzog ihre Seele nicht dem Tode, überließ vielmehr ihr Leben der Pest;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 51, 'er ließ alle Erstgeburt in Ägypten sterben, der Manneskraft Erstlinge in den Zelten Hams.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 52, 'Dann ließ er sein Volk ausziehn wie Schafe und leitete sie in der Wüste wie eine Herde');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 53, 'und führte sie sicher, so daß sie nicht bangten; ihre Feinde aber bedeckte das Meer.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 54, 'So brachte er sie nach seinem heiligen Gebiet, in das Bergland, das er mit seiner Rechten erworben,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 55, 'und vertrieb vor ihnen her die Völker, verloste ihr Gebiet als erblichen Besitz und ließ in ihren Zelten die Stämme Israels wohnen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 56, 'Doch sie versuchten und reizten Gott, den Höchsten, und hielten sich nicht an seine Gebote,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 57, 'sondern fielen ab und handelten treulos, ihren Vätern gleich; sie versagten wie ein trüglicher Bogen');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 58, 'und erbitterten ihn durch ihren Höhendienst und reizten ihn zum Eifer durch ihre Götzenbilder.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 59, 'Als Gott es vernahm, ergrimmte er und verwarf Israel ganz und gar:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 60, 'er gab seine Wohnung in Silo auf, das Zelt, das er aufgeschlagen unter den Menschen;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 61, 'er ließ seine Macht in Gefangenschaft fallen und seine Zier in die Hand des Feindes;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 62, 'er gab sein Volk dem Schwerte preis und war entrüstet über sein Erbteil;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 63, 'seine jungen Männer fraß das Feuer, und seine Jungfraun blieben ohne Brautlied;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 64, 'seine Priester fielen durchs Schwert, und seine Witwen konnten keine Totenklage halten.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 65, 'Da erwachte der Allherr wie ein Schlafender, wie ein vom Wein übermannter Kriegsheld;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 66, 'er schlug seine Feinde von hinten und gab sie ewiger Schande preis.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 67, 'Auch verwarf er das Zelt Josephs und erwählte nicht den Stamm Ephraim,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 68, 'sondern erwählte den Stamm Juda, den Berg Zion, den er liebgewonnen;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 69, 'und er baute den ragenden Bergen gleich sein Heiligtum, fest wie die Erde, die er auf ewig gegründet.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 70, 'Dann erwählte er David, seinen Knecht, den er wegnahm von den Hürden des Kleinviehs;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 71, 'von den Mutterschafen holte er ihn, daß er Jakob weide, sein Volk, und Israel, seinen Erbbesitz.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 72, 'Der weidete sie mit redlichem Herzen und leitete sie mit kundiger Hand.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 79, 1, 'Ein Psalm von Asaph. O Gott, in dein Eigentum sind Heiden eingedrungen, haben deinen heiligen Tempel entweiht, Jerusalem zu Trümmerhaufen gemacht!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 79, 2, 'Sie haben die Leichen deiner Knechte den Vögeln des Himmels zum Fraß gegeben, den wilden Tieren des Landes die Leiber deiner Frommen!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 79, 3, 'Sie haben deren Blut vergossen wie Wasser rings um Jerusalem her, und niemand hat sie begraben!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 79, 4, 'Wir sind unsern Nachbarn zur Schmähung geworden, ein Spott und Hohn den Völkern um uns her!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 79, 5, 'Wie lange, o HERR, willst du unversöhnlich zürnen? Bis wann soll lodern dein Eifer wie Feuer?');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 79, 6, 'Gieß deine Zornglut über die Heiden aus, die dich nicht kennen, auf die Reiche, die deinen Namen nicht anrufen!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 79, 7, 'Denn sie haben Jakob gefressen und seine Wohnstatt verwüstet.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 79, 8, 'Rechne uns nicht die Schuld der Väter an, laß eilends dein Erbarmen uns angedeihn! Denn gar schwach sind wir geworden.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 79, 9, 'Hilf uns, du Gott unsers Heils, um der Ehre deines Namens willen! Errette uns und vergib uns unsere Sünden um deines Namens willen!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 79, 10, 'Warum sollen die Heiden sagen: »Wo ist ihr Gott?« Laß kundwerden an den Heiden vor unsern Augen die Rache für das vergossne Blut deiner Knechte!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 79, 11, 'Laß vor dich kommen das Seufzen der Gefangenen; kraft deines starken Armes erhalte am Leben die dem Tode Geweihten!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 79, 12, 'Und zahle unsern Nachbarn siebenfach heim in ihren Busen den Hohn, mit dem sie dich, o Allherr, gehöhnt!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 79, 13, 'Wir aber, dein Volk und die Herde, die du weidest, wir wollen dir ewiglich danken, von Geschlecht zu Geschlecht verkünden deinen Ruhm!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 80, 1, 'Dem Musikmeister, nach (der Singweise = Melodie) »Lilien(rein) ist das Zeugnis«; von Asaph ein Psalm.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 80, 2, 'O Hirte Israels, merk auf, der du Joseph leitest wie eine Herde! Der du thronst über den Cheruben, erscheine!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 80, 3, 'Als Anführer Ephraims und Benjamins und Manasses biete deine Heldenkraft auf und komm uns zu Hilfe!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 80, 4, 'O Gott (der Heerscharen), stelle uns wieder her und laß dein Angesicht leuchten, damit uns Rettung widerfährt!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 80, 5, 'O HERR, Gott der Heerscharen, wie lange noch raucht dein Zorn trotz der Gebete deines Volkes?');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 80, 6, 'Du hast uns Tränenbrot essen lassen und uns eimerweise getränkt mit Tränen;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 80, 7, 'du hast uns gemacht zum Zankapfel unsern Nachbarn, und unsere Feinde spotten über uns.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 80, 8, 'O Gott der Heerscharen, stelle uns wieder her und laß dein Angesicht leuchten, damit uns Rettung widerfährt!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 80, 9, 'Einen Weinstock hast aus Ägypten du ausgehoben, hast Heidenvölker vertrieben, ihn eingepflanzt,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 80, 10, 'hast weiten Raum vor ihm her geschafft, daß er Wurzeln schlug und das Land erfüllte;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 80, 11, 'die Berge wurden von seinem Schatten bedeckt und von seinen Reben die Zedern Gottes;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 80, 12, 'er streckte seine Ranken aus bis ans Meer und seine Schößlinge bis zum Euphratstrom.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 80, 13, 'Warum hast du sein Gehege eingerissen, so daß alle ihn zerpflücken, die des Weges ziehn?');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 80, 14, 'Es zerwühlt ihn der Eber aus dem Walde, und die Tiere des Feldes fressen ihn kahl.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 80, 15, 'O Gott der Heerscharen, kehre doch zurück, schaue vom Himmel nieder und blicke her und nimm dich dieses Weinstocks an,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 80, 16, 'des Setzlings, den deine Rechte gepflanzt, und des Schößlings, den du dir großgezogen!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 80, 17, 'Er ist mit Feuer verbrannt, ist abgehauen: vor dem Zornblick deines Angesichts kommen sie um.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 80, 18, 'Halte schirmend die Hand über den Mann deiner Rechten, den Menschensohn, den du dir großgezogen:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 80, 19, 'so wollen wir nimmer von dir weichen! Schenke uns neues Leben, so wollen wir deinen Namen preisen!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 80, 20, 'O HERR, Gott der Heerscharen, stelle uns wieder her, laß dein Angesicht leuchten, damit uns Rettung widerfährt!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 81, 1, 'Dem Musikmeister, nach der Keltertreterweise; von Asaph.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 81, 2, 'Singt jubelnd dem Gott, der unsre Stärke ist, jauchzet dem Gott Jakobs!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 81, 3, 'Stimmt Lobgesang an und laßt die Pauken erschallen, die liebliche Zither mitsamt der Harfe!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 81, 4, 'Stoßt am Neumond in die Posaune, beim Vollmond zur Feier unsres Festes!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 81, 5, 'Denn so ist es Satzung für Israel, ein Gebot des Gottes Jakobs;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 81, 6, 'als Gesetz hat er’s für Joseph verordnet, als er auszog gegen Ägyptenland. – Eine Sprache, die ich bisher nicht gekannt, vernehme ich:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 81, 7, '»Ich hab’ seine Schulter der Last entzogen, seine Hände sind des Tragkorbs ledig geworden.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 81, 8, 'Als du riefst in der Drangsal, erlöste ich dich, erhörte dich in der Hülle der Donnerwolke, prüfte dich am Haderwasser. SELA.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 81, 9, '›Höre, mein Volk, ich will dich warnen! o Israel, möchtest du mir doch gehorchen!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 81, 10, 'Kein fremder Gott soll unter dir sein, vor keinem Gott des Auslands darfst du dich niederwerfen!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 81, 11, 'Ich, der HERR, bin dein Gott, der dich heraufgeführt aus Ägyptenland: tu deinen Mund weit auf, so will ich ihn füllen!‹');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 81, 12, 'Doch mein Volk hat nicht gehört auf meine Stimme, und Israel ist mir nicht zu Willen gewesen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 81, 13, 'Da hab ich sie preisgegeben dem Starrsinn ihres Herzens: sie sollten nach ihren eignen Gedanken wandeln.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 81, 14, 'O wollte mein Volk doch mir gehorchen, Israel doch wandeln auf meinen Wegen!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 81, 15, 'Wie bald würde ich ihre Feinde beugen und gegen ihre Dränger kehren meine Hand!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 81, 16, 'Die da hassen den HERRN, die müßten ihm schmeicheln, und ihre Gerichtszeit sollte ewig währen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 81, 17, 'Doch ihn wollt’ ich nähren mit dem Mark des Weizens, dich sättigen aus dem Felsen mit Honig.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 82, 1, 'Ein Psalm Asaphs. Gott steht da in der Gottesversammlung, hält inmitten der Götter Gericht:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 82, 2, '»Wie lange noch wollt ihr ungerecht richten und Partei für die Gottlosen nehmen? SELA.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 82, 3, 'Schafft Recht dem Geringen und Verwaisten, dem Bedrückten und Dürftigen verhelft zum Recht!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 82, 4, 'Rettet den Geringen und Armen, entreißt ihn der Hand der Gottlosen!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 82, 5, '»Doch sie sind ohne Einsicht und ohne Erkenntnis; in Finsternis gehn sie einher, mögen der Erde Pfeiler auch alle wanken.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 82, 6, 'Wohl hab’ ich selber gesagt, daß ihr Götter seid und Söhne des Höchsten allesamt;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 82, 7, 'dennoch wie (gewöhnliche) Menschen sollt ihr sterben. und fallen wie irgendeiner der Fürsten.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 82, 8, 'Erhebe dich, Gott, richte die Erde! Denn du bist der Erbherr über alle Völker.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 83, 1, 'Ein Lied, ein Psalm Asaphs.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 83, 2, 'O Gott, halte dich nicht zurück, verharre nicht im Schweigen und bleibe nicht ruhig, o Gott!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 83, 3, 'Denn siehe, deine Feinde toben, und die dich hassen, tragen das Haupt hoch!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 83, 4, 'Gegen dein Volk ersinnen sie einen Anschlag und beraten sich gegen deine Schutzbefohlnen;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 83, 5, 'sie sagen: »Kommt, wir wollen sie vertilgen als Volk: des Namens Israel soll man fürder nicht gedenken!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 83, 6, 'Ja, sie haben einmütigen Sinns sich beraten, ein Bündnis gegen dich geschlossen:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 83, 7, 'die Zelte Edoms und der Ismaeliter, Moab und die Hagriter,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 83, 8, 'Gebal und Ammon und Amalek, das Philisterland samt den Bewohnern von Tyrus.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 83, 9, 'Auch Assur hat sich zu ihnen gesellt, es leiht den Nachkommen Lots seinen Arm. SELA.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 83, 10, 'Verfahre mit ihnen wie einst mit Midian, wie mit Sisera, wie mit Jabin am Bache Kison,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 83, 11, 'die bei Endor den Untergang fanden, mit ihren Leibern das Erdreich düngten!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 83, 12, 'Mache sie, ihre Edlen, wie Oreb und Seeb, und wie Sebah und Zalmunna alle ihre Fürsten,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 83, 13, 'die gesprochen hatten: »Wir wollen für uns erobern die Fluren Gottes!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 83, 14, 'Mein Gott, mache sie gleich dem verwehten Laub, wie Spreu vor dem Winde!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 83, 15, 'Wie Feuer, das den Wald verzehrt, wie Flammen, welche die Berge versengen:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 83, 16, 'so verfolge sie mit deinem Sturm und schrecke sie mit deiner Windsbraut!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 83, 17, 'Laß Beschämung ihr Antlitz bedecken, auf daß sie nach deinem Namen fragen, o HERR!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 83, 18, 'Laß sie beschämt und erschreckt sein für immer, in Schande geraten und vergehn!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 83, 19, 'Sie müssen erkennen, daß du, dessen Name »HERR« ist, du allein der Höchste bist über die ganze Erde.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 84, 1, 'Dem Musikmeister, nach der Keltertreterweise; von den Korahiten ein Psalm.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 84, 2, 'Wie lieblich ist deine Wohnstatt, HERR der Heerscharen!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 84, 3, 'Meine Seele hat sich gesehnt, ja geschmachtet nach den Vorhöfen des HERRN; nun jubeln mein Herz und mein Leib dem lebendigen Gott entgegen!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 84, 4, 'Hat doch auch der Sperling ein Haus gefunden und die Schwalbe ein Nest für sich, woselbst sie ihre Jungen birgt: deine Altäre, o HERR der Heerscharen, mein König und mein Gott.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 84, 5, 'Wohl denen, die da wohnen in deinem Haus, dich allzeit preisen! SELA.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 84, 6, 'Wohl allen, die in dir ihre Stärke finden, wenn auf Pilgerfahrten sie sinnen!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 84, 7, 'Wenn sie wandern durchs Bakatal, machen sie’s zum Quellengrund, den auch der Frühregen kleidet in reichen Segen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 84, 8, 'Sie wandern dahin mit stets erneuter Kraft, bis vor Gott sie erscheinen in Zion.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 84, 9, 'O HERR, Gott der Heerscharen, höre mein Gebet, vernimm es, Gott Jakobs! SELA.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 84, 10, 'Du unser Schild, blick her, o Gott, und schau auf das Antlitz deines Gesalbten!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 84, 11, 'Denn ein einziger Tag in deinen Vorhöfen ist besser als tausend andere; lieber will ich stehn an der Schwelle im Hause meines Gottes, als wohnen in den Zelten der Frevler.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 84, 12, 'Denn Sonne und Schild ist Gott der HERR; Gnade und Ehre verleiht der HERR, nichts Gutes versagt er denen, die unsträflich wandeln.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 84, 13, 'O HERR der Heerscharen, wohl dem Menschen, der dir vertraut!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 85, 1, 'Dem Musikmeister; von den Korahiten ein Psalm.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 85, 2, 'Du hast zwar, HERR, deinem Lande Gnade gewährt, hast Jakobs Mißgeschick gewendet,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 85, 3, 'hast deinem Volke die Schuld vergeben und all seine Sünde zugedeckt, SELA;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 85, 4, 'hast deinem ganzen Groll entsagt, von der Glut deines Zorns dich abgewandt:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 85, 5, 'stell uns nun aber auch wieder her, du Gott unsers Heils, und laß deinen Unmut gegen uns schwinden!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 85, 6, 'Willst du denn unversöhnlich gegen uns zürnen und deinen Zorn fortdauern lassen für und für?');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 85, 7, 'Willst du uns nicht wieder neu beleben, daß dein Volk sich deiner mag freuen?');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 85, 8, 'Laß uns schauen, o HERR, deine Gnade und gewähre uns dein Heil!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 85, 9, 'Ich will doch hören, was Gott der HERR verkündet! – Fürwahr, er kündet Segen an seinem Volke und seinen Frommen; nur daß sie nicht wieder sich wenden zur Torheit!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 85, 10, 'Wahrlich, sein Heil ist denen nah, die ihn fürchten, daß Herrlichkeit in unserm Lande wohne,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 85, 11, 'daß Gnade und Treue einander begegnen, Gerechtigkeit und Friede sich küssen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 85, 12, 'Die Treue wird aus der Erde sprossen und Gerechtigkeit vom Himmel niederschauen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 85, 13, 'Dann wird uns der HERR auch Segen spenden, daß unser Land uns seinen Ertrag gewährt;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 85, 14, 'Gerechtigkeit wird vor ihm hergehn und achten auf den Weg seiner Schritte.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 86, 1, 'Ein Gebet Davids. Neige, o HERR, dein Ohr, erhöre mich, denn elend bin ich und arm!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 86, 2, 'Bewahre meine Seele, denn ich bin fromm; hilf du, mein Gott, deinem Knecht, der auf dich vertraut!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 86, 3, 'Sei mir gnädig, o Allherr, denn zu dir rufe ich allezeit.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 86, 4, 'Erfreue das Herz deines Knechtes, denn zu dir, o Allherr, erheb’ ich meine Seele.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 86, 5, 'Denn du, o Allherr, bist gütig und bereit zum Verzeihen, bist reich an Gnade für alle, die dich anrufen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 86, 6, 'Vernimm, o HERR, mein Gebet und merke auf mein lautes Flehen!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 86, 7, 'Bin ich in Not, so ruf’ ich zu dir, denn du erhörst mich.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 86, 8, 'Keiner kommt dir gleich unter den Göttern, o Allherr, und nichts ist deinen Werken vergleichbar.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 86, 9, 'Alle Völker, die du geschaffen, werden kommen und vor dir anbeten, o Allherr, und deinen Namen ehren;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 86, 10, 'denn du bist groß, und Wunder tust du: ja du, nur du bist Gott.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 86, 11, 'Lehre mich, HERR, deinen Weg, daß ich ihn wandle in deiner Wahrheit; richte mein Herz auf das Eine, daß es deinen Namen fürchte!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 86, 12, 'Preisen will ich dich, Allherr, mein Gott, von ganzem Herzen und deinen Namen ewiglich ehren;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 86, 13, 'denn deine Gnade ist groß gegen mich gewesen: du hast meine Seele errettet aus der Tiefe des Totenreichs.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 86, 14, 'O Gott! Vermessene haben sich gegen mich erhoben, eine Rotte von Schreckensmännern steht mir nach dem Leben; sie haben dich nicht vor Augen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 86, 15, 'Doch du, o Allherr, bist ein Gott voll Erbarmen und Gnade, langmütig und reich an Gnade und Treue.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 86, 16, 'Wende dich zu mir und sei mir gnädig; verleih deine Kraft deinem Knecht und hilf dem Sohne deiner Magd!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 86, 17, 'Tu ein Zeichen an mir zum Guten, daß meine Feinde es sehn und sich schämen müssen, weil du, o HERR, mein Helfer und Tröster gewesen!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 87, 1, 'Von den Korahiten ein Psalm, ein Lied. Seine Gründung liegt auf heiligen Bergen:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 87, 2, 'lieb hat der HERR die Tore Zions mehr als alle (anderen) Wohnstätten Jakobs.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 87, 3, 'Herrliches ist von dir berichtet, du Gottesstadt. SELA.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 87, 4, '»Ich nenne Ägypten und Babel als meine Bekenner, hier das Philisterland und Tyrus samt Äthiopien – nämlich wer dort seine Heimat hat.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 87, 5, 'Doch von Zion heißt es: »Mann für Mann hat dort seine Heimat, und er selbst, der Höchste, macht es stark.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 87, 6, 'Der HERR zählt, wenn er die Völker aufschreibt: »Dieser hat dort seine Heimat.« SELA.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 87, 7, 'Sie aber tanzen den Reigen und singen: »Alle meine Quellen sind in dir (o Zion)!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 88, 1, 'Ein Lied, ein Psalm von den Korahiten; dem Musikmeister, nach (der Singweise = Melodie) »die Krankheit«; ein Lehrgedicht von Heman, dem Esrahiten.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 88, 2, 'O HERR, du Gott meines Heils, ich rufe bei Tage und schreie nachts vor dir:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 88, 3, 'o laß mein Gebet vor dich kommen, neige dein Ohr meinem Flehen zu!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 88, 4, 'Denn meine Seele ist mit Leiden gesättigt, und mein Leben naht sich dem Totenreich.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 88, 5, 'Schon zählt man mich zu den ins Grab Gesunknen, ich bin wie ein Mann ohne Lebenskraft.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 88, 6, 'Unter den Toten hab’ ich mein Lager gleichwie Erschlagne, die im Grabe liegen, deren du nicht mehr gedenkst: sie sind ja deiner Hand entrückt.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 88, 7, 'Du hast mich in die Grube der Unterwelt versetzt, in finstre Nacht, in die Tiefe;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 88, 8, 'auf mir lastet schwer dein Grimm, und mit all deinen Wogen drückst du mich nieder. SELA.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 88, 9, 'Meine Bekannten hast du mir entfremdet, hast mich ihnen zum Abscheu gemacht; eingeschlossen bin ich und kann nicht hinaus:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 88, 10, 'mein Auge erlischt vor Elend. Ich rufe zu dir, o HERR, jeden Tag, ich breite zu dir meine Hände aus:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 88, 11, '»Kannst an den Toten du Wunder tun, oder werden Schatten aufstehn, um dich zu preisen? SELA.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 88, 12, 'Wird man im Grabe von deiner Gnade erzählen, von deiner Treue im Abgrund?');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 88, 13, 'Verkündet man dein Wunderwalten in der Finsternis und deine Gerechtigkeit im Lande des Vergessens?«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 88, 14, 'Ich dagegen rufe laut zu dir, o HERR, schon am Morgen tritt mein Gebet vor dich:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 88, 15, '»Warum, o HERR, verwirfst du mich, verbirgst du dein Antlitz vor mir?«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 88, 16, 'Elend bin ich und siech von Jugend auf, ich trage deine Schrecken und verzweifle.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 88, 17, 'Deine Zornesgluten sind über mich hingegangen, deine Schrecknisse haben mich vernichtet;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 88, 18, 'sie umgeben mich immerdar wie Wasserfluten, umringen mich allzumal.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 88, 19, 'Freunde und Gefährten hast du mir entfremdet: nur die Finsternis ist mir vertraut (geblieben).');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 1, 'Ein Lehrgedicht von Ethan, dem Esrahiten.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 2, 'Die Gnadenerweise des HERRN will ich allzeit besingen, bis zum fernsten Geschlecht deine Treue laut verkünden.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 3, 'Denn du, Herr, hast verheißen: »Auf ewig soll der Gnadenbund aufgebaut sein« fest wie den Himmel hast du deine Treue gegründet –:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 4, '»Ich habe einen Bund geschlossen mit meinem Erwählten, habe David, meinem Knecht, geschworen:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 5, '›Deinem Geschlecht will ich ewige Dauer verleihen und aufbaun deinen Thron für alle Zeiten.‹« SELA.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 6, 'Da priesen die Himmel deine Wundertat, o HERR, dazu deine Treue in der Versammlung der Heiligen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 7, 'Denn wer in der Wolkenhöhe kommt dem HERRN gleich, ist dem HERRN vergleichbar unter den Gottessöhnen,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 8, 'dem Gott, der gefürchtet ist im Kreise der Heiligen und furchtbar über alle um ihn her?');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 9, 'HERR, du Gott der Heerscharen, wer ist dir gleich? Stark bist du, HERR, und deine Treue ist rings um dich her.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 10, 'Du herrschest über das Ungestüm des Meeres: erheben sich seine Wogen – du besänftigst sie.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 11, 'Du hast Rahab zermalmt wie einen Durchbohrten, deine Feinde mit deinem starken Arm zerstreut.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 12, 'Dein ist der Himmel, dein auch die Erde, der Erdkreis und seine Fülle – du hast sie gegründet;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 13, 'Norden und Süden – du hast sie geschaffen, der Thabor und Hermon bejubeln deinen Namen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 14, 'Du hast einen Arm voll Heldenkraft: stark ist deine Hand, deine Rechte hoch erhoben.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 15, 'Gerechtigkeit und Recht sind deines Thrones Stützen, Gnade und Treue gehen vor dir her.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 16, 'Wohl dem Volk, das zu jubeln versteht, das, o HERR, im Licht deines Angesichts wandelt:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 17, 'ob deinem Namen frohlocken sie allezeit, ob deiner Gerechtigkeit sind sie hochgemut.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 18, 'Denn du bist ihr Ruhm und ihre Stärke, und durch deine Gnade ragt hoch unser Horn;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 19, 'denn dem HERRN gehört unser Schild und dem Heiligen Israels unser König.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 20, 'Damals hast du in einem Gesicht zu deinem Frommen gesprochen: »Ich habe die Hilfe einem Helden übertragen, einen Auserwählten über das Volk erhöht:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 21, 'ich habe David als meinen Knecht gefunden, mit meinem heiligen Öl ihn gesalbt,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 22, 'damit meine Hand beständig mit ihm sei und mein Arm ihm Stärke verleihe.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 23, 'Kein Feind soll ihn überlisten und kein Ruchloser ihn überwältigen;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 24, 'nein, seine Gegner will ich vor ihm zerschmettern, und die ihn hassen, will ich niederschlagen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 25, 'Doch mit ihm soll meine Treue und Gnade sein, durch meinen Namen soll sein Horn hoch ragen;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 26, 'ich will das Meer unter seine Hand tun und seine Rechte auf die Ströme legen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 27, 'Er soll zu mir rufen: ›Mein Vater bist du, mein Gott und der Fels meines Heils!‹');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 28, 'So will auch ich ihn zum Erstgeborenen machen, zum höchsten unter den Königen der Erde.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 29, 'Für immer will ich ihm meine Gnade bewahren, und mein Bund soll fest ihm bleiben;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 30, 'für immer will ich sein Geschlecht erhalten und seinen Thron, solange der Himmel steht.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 31, 'Wenn seine Söhne mein Gesetz verlassen und nicht in meinen Rechten wandeln,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 32, 'wenn sie meine Satzungen entweihen und meine Gebote nicht beachten:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 33, 'so werde ich zwar mit der Rute ihren Abfall strafen und ihre Übertretung mit Schlägen,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 34, 'doch meine Gnade will ich ihm nicht entziehen und meine Treue nimmer verleugnen;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 35, 'ich werde meinen Bund nicht entweihen und den Ausspruch meiner Lippen nicht ändern.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 36, 'Ein für allemal hab’ ich bei meiner Heiligkeit geschworen niemals werde ich David belügen –:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 37, '›Sein Geschlecht soll ewig bestehn, sein Thron wie die Sonne vor mir,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 38, 'wie der Mond soll für immer er bleiben‹: der Zeuge in Wolkenhöhen ist treu!« SELA.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 39, 'Und dennoch hast du verworfen und verstoßen, hast Zorn gegen deinen Gesalbten betätigt;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 40, 'du hast den Bund mit deinem Knecht gebrochen, seine Krone entweiht und zu Boden geschleudert;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 41, 'all seine Mauern hast du eingerissen, seine festen Plätze in Trümmer gelegt.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 42, 'Es plündern ihn alle, die des Weges ziehen, seinen Nachbarn ist er zum Spott geworden.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 43, 'Du hast den Arm seiner Dränger hoch erhoben und all seine Feinde mit Freude erfüllt;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 44, 'auch hast du rückwärts gewandt sein scharfes Schwert und im Krieg ihn nicht aufrecht gehalten (siegreich erhalten);');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 45, 'du hast seinem Glanz ein Ende gemacht und seinen Thron zu Boden gestürzt;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 46, 'du hast die Tage seiner Jugend verkürzt, hast ihn mit Schande bedeckt. SELA.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 47, 'Bis wann, HERR, willst du dich ganz verbergen? Bis wann soll lodern wie Feuer dein Zorn?');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 48, 'Bedenke, wie kurz meine Lebenszeit ist, wie vergänglich du alle Menschenkinder geschaffen!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 49, 'Wo ist ein Mensch, der leben bleibt und den Tod nicht sieht, seine Seele errettet vor des Totenreichs Macht?');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 50, 'Wo sind deine früheren Gnadenverheißungen, Allherr, die du David zugeschworen in deiner Treue?');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 51, 'Gedenke, Allherr, der Schmach deiner Knechte, daß ich tragen muß in meinem Busen den Hohn von all den vielen Völkern,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 52, 'womit deine Feinde, o HERR, geschmäht uns haben, womit geschmäht sie haben die Fußstapfen');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 53, 'Gepriesen sei der HERR in Ewigkeit! Amen, ja Amen!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 90, 1, 'Ein Gebet Moses, des Mannes Gottes. O Allherr, eine Zuflucht bist du uns gewesen von Geschlecht zu Geschlecht.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 90, 2, 'Ehe die Berge geboren waren und die Erde und die Welt von dir geschaffen wurden, ja von Ewigkeit zu Ewigkeit bist du, o Gott.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 90, 3, 'Du läßt die Menschen zum Staub zurückkehren und sprichst: »Kommt wieder, ihr Menschenkinder!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 90, 4, 'Denn tausend Jahre sind in deinen Augen wie der gestrige Tag, wenn er vergangen, und wie eine Wache in der Nacht.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 90, 5, 'Du schwemmst sie hinweg; sie sind wie ein Schlaf am Morgen, dem sprossenden Grase gleich:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 90, 6, 'am Morgen grünt es und sprießt, am Abend welkt es ab, und es verdorrt.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 90, 7, 'Denn wir vergehen durch deinen Zorn und werden hinweggerafft durch deinen Grimm.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 90, 8, 'Du hast unsre Sünden vor dich hingestellt, unser geheimstes Denken ins Licht vor deinem Angesicht.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 90, 9, 'Ach, alle unsre Tage fahren dahin durch deinen Grimm; wir lassen unsre Jahre entschwinden wie einen Gedanken.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 90, 10, 'Unsre Lebenszeit – sie währt nur siebzig Jahre, und, wenn’s hoch kommt, sind’s achtzig Jahre, und ihr Stolz ist Mühsal und Nichtigkeit; denn schnell ist sie enteilt, und wir fliegen davon.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 90, 11, 'Doch wer bedenkt die Stärke deines Zorns und deinen Grimm trotz deines furchtbaren Waltens?');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 90, 12, 'Unsre Tage zählen, das lehre uns, damit ein weises Herz wir gewinnen!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 90, 13, 'Kehre dich wieder zu uns, o HERR! Wie lange noch (willst du zürnen)? Erbarm dich deiner Knechte!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 90, 14, 'Sättige früh uns am Morgen mit deiner Gnade, daß wir jubeln und uns freun unser Leben lang!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 90, 15, 'Erfreue uns so viele Tage, wie du uns gebeugt hast, so viele Jahre, wie Unglück wir erlebten!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 90, 16, 'Laß deinen Knechten dein Walten sichtbar werden und ihren Kindern deine Herrlichkeit!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 90, 17, 'Und es ruhe auf uns die Huld des Allherrn, unsres Gottes, und das Werk unsrer Hände segne bei uns! Ja, das Werk unsrer Hände wollest du segnen!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 91, 1, 'Wer da wohnt im Schirm des Höchsten und im Schatten des Allmächtigen weilt,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 91, 2, 'der spricht zum HERRN: »Meine Zuflucht und meine Burg, mein Gott, auf den ich vertraue!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 91, 3, 'Denn er ist’s, der dich rettet aus den Voglers Schlinge, von der unheilvollen Pest.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 91, 4, 'Mit seinen Fittichen deckt er dich, und unter seinen Flügeln bist du geborgen, Schild und Panzer ist seine Treue.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 91, 5, 'Du brauchst dich nicht zu fürchten vor nächtlichem Schrecken, vor dem Pfeil, der bei Tage daherfliegt,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 91, 6, 'nicht vor der Pest, die im Finstern schleicht, vor der Seuche, die mittags wütet.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 91, 7, 'Ob tausend dir zur Seite fallen, zehntausend zu deiner Rechten: an dich kommt’s nicht heran;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 91, 8, 'nein, lediglich mit eignen Augen wirst du’s schauen und zusehn, wie den Frevlern vergolten wird.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 91, 9, 'Ja, du, o HERR, bist meine Zuflucht: den Höchsten hast du zum Schutz dir erwählt.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 91, 10, 'Kein Übel wird dir begegnen, kein Unheilsschlag deinem Zelte nahn;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 91, 11, 'denn seine Engel wird er für dich entbieten, daß sie dich behüten auf all deinen Wegen;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 91, 12, 'auf den Armen werden sie dich tragen, damit dein Fuß nicht stoße an einen Stein;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 91, 13, 'über Löwen und Ottern wirst du schreiten, wirst junge Löwen und Schlangen zertreten.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 91, 14, '»Weil er fest an mir hängt, so will ich ihn retten, will ihn schützen, denn er kennt meinen Namen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 91, 15, 'Ruft er mich an, so will ich ihn erhören; ich steh’ ihm bei in der Not, will frei ihn machen und geehrt.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 91, 16, 'Mit langem Leben will ich ihn sättigen und lasse ihn schauen mein Heil.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 92, 1, 'Ein Psalm; ein Lied für den Sabbattag.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 92, 2, 'Köstlich ist’s, dem HERRN zu danken, zu lobsingen deinem Namen, du Höchster,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 92, 3, 'am Morgen deine Gnade zu künden und deine Treue in den Nächten');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 92, 4, 'zum Klang zehnsaitigen Psalters und zur Harfe, zum Saitenspiel auf der Zither.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 92, 5, 'Denn du hast mich erfreut, o HERR, durch dein Tun, ob den Werken deiner Hände juble ich.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 92, 6, 'Wie groß sind deine Werke, o HERR, gewaltig tief sind deine Gedanken!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 92, 7, 'Nur ein unvernünft’ger Mensch erkennt das nicht, nur ein Tor sieht dies nicht ein.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 92, 8, 'Wenn die Gottlosen sprossen wie Gras und alle Übeltäter blühen, so ist’s doch nur dazu, damit sie für immer vertilgt werden.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 92, 9, 'Du aber thronst auf ewig in der Höhe, HERR!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 92, 10, 'Denn wahrlich deine Feinde, o HERR, ja wahrlich deine Feinde kommen um: alle Übeltäter werden zerstreut.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 92, 11, 'Doch mein Horn erhöhst du wie das eines Wildstiers, hast allzeit mich gesalbt mit frischem Öl;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 92, 12, 'mein Auge wird sich weiden an meinen Feinden; vom Geschick der Bösen, die sich gegen mich erheben, wird mein Ohr mit Freuden hören.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 92, 13, 'Der Gerechte sproßt gleich dem Palmbaum, er wächst wie auf dem Libanon die Zeder.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 92, 14, 'Gepflanzt im Hause des HERRN, sprossen sie reich in den Vorhöfen unsers Gottes,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 92, 15, 'tragen Frucht noch im Greisenalter, sind voller Saft und frischbelaubt,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 92, 16, 'um zu verkünden, daß der HERR gerecht ist, mein Fels, an dem kein Unrecht haftet.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 93, 1, 'Der HERR ist König! Er hat sich gekleidet in Hoheit; in Hoheit hat der HERR sich gekleidet, mit Kraft umgürtet, auch der Erdkreis steht fest, so daß er nicht wankt.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 93, 2, 'Fest steht dein Thron von Anbeginn, von Ewigkeit her bist du.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 93, 3, 'Fluten erhoben, o HERR, Fluten erhoben ihr Brausen, Fluten werden (auch weiter) ihr Tosen erheben –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 93, 4, 'mächtiger als das Brausen gewaltiger Wasser, mächtiger als die brandenden Meereswogen ist der HERR in der Himmelshöhe!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 93, 5, 'Was du verordnet hast, ist völlig zuverlässig, deinem Hause gebührt Heiligkeit, o HERR, für die Dauer der Zeiten.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 94, 1, 'Du Gott der Rache, o HERR, du Gott der Rache, erscheine!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 94, 2, 'Erhebe dich, Richter der Erde, vergilt den Stolzen nach ihrem Tun!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 94, 3, 'Wie lange noch sollen die Gottlosen, HERR, wie lange noch sollen die Gottlosen jubeln,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 94, 4, 'sollen sie geifern und trotzige Reden führen, alle Übeltäter stolz sich brüsten?');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 94, 5, 'Dein Volk, o HERR, zertreten sie und bedrücken dein Erbe;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 94, 6, 'sie erwürgen Witwe und Fremdling und morden die Waisen');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 94, 7, 'und sagen dabei: »Nicht sieht es der HERR« oder: »Nicht merkt es der Gott Jakobs.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 94, 8, 'Nehmt Verstand an, ihr Unvernünftigen im Volk, und ihr Toren: wann wollt ihr Einsicht gewinnen?');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 94, 9, 'Der das Ohr gepflanzt, der sollte nicht hören? Der das Auge gebildet, der sollte nicht sehn?');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 94, 10, 'Der die Völker erzieht, der sollte nicht strafen, er, der die Menschen Erkenntnis lehrt?');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 94, 11, 'Der HERR kennt wohl die Gedanken der Menschen, daß nur ein Hauch sie sind.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 94, 12, 'Wohl dem Manne, den du, HERR, in Zucht nimmst, und den du aus deinem Gesetz belehrst,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 94, 13, 'damit er sich Ruhe verschaffe vor Unglückstagen, bis dem Frevler die Grube man gräbt!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 94, 14, 'Denn der HERR wird sein Volk nicht verstoßen und sein Erbe nicht verlassen;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 94, 15, 'denn Recht muß doch Recht bleiben, und ihm werden alle redlich Gesinnten sich anschließen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 94, 16, 'Wer leistet mir Beistand gegen die Bösen? Wer tritt für mich ein gegen die Übeltäter?');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 94, 17, 'Wäre der HERR nicht mein Helfer gewesen, so wohnte meine Seele wohl schon im stillen Land.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 94, 18, 'Sooft ich dachte: »Mein Fuß will wanken«, hat deine Gnade, HERR, mich immer gestützt;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 94, 19, 'bei der Menge meiner Sorgen in meiner Brust haben deine Tröstungen mir das Herz erquickt.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 94, 20, 'Sollte verbündet dir sein der Richterstuhl des Unheils, der Verderben schafft durch Gesetzesverdrehung?');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 94, 21, 'Sie tun sich ja zusammen gegen das Leben des Gerechten und verurteilen unschuldig Blut.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 94, 22, 'Doch der HERR ist mir zur festen Burg geworden, mein Gott zu meinem Zufluchtsfelsen;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 94, 23, 'er läßt ihren Frevel auf sie selber fallen und wird sie ob ihrer Bosheit vertilgen: ja vertilgen wird sie der HERR, unser Gott.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 95, 1, 'Kommt, laßt uns dem HERRN zujubeln, jauchzen dem Felsen unsers Heils!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 95, 2, 'Laßt uns mit Dank vor sein Angesicht treten, mit Liedern ihm jauchzen!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 95, 3, 'Denn ein großer Gott ist der HERR und ein großer König über alle Götter,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 95, 4, 'er, in dessen Hand die Tiefen der Erde sind und dem auch die Gipfel der Berge gehören;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 95, 5, 'er, dem das Meer gehört: er hat’s ja geschaffen, und das Festland: seine Hände haben’s gebildet.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 95, 6, 'Kommt, laßt uns anbeten und niederfallen, die Knie beugen vor dem HERRN, unserm Schöpfer!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 95, 7, 'Denn er ist unser Gott, und wir das Volk seiner Weide, die Herde seiner Hand. Möchtet ihr heute doch hören auf seine Stimme:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 95, 8, '»Verstockt nicht euer Herz wie bei Meriba, wie am Tage von Massa in der Wüste,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 95, 9, 'woselbst eure Väter mich versuchten, mich prüften, obwohl sie doch sahen mein Tun.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 95, 10, 'Vierzig Jahre hegte ich Abscheu gegen dieses Geschlecht, und sagte: ›Sie sind ein Volk mit irrendem Herzen‹; sie aber wollten von meinen Wegen nichts wissen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 95, 11, 'So schwur ich denn in meinem Zorn: ›Sie sollen nicht eingehn in meine Ruhstatt!‹«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 96, 1, 'Singet dem HERRN ein neues Lied, singet dem HERRN, alle Lande!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 96, 2, 'Singt dem HERRN, preist seinen Namen, verkündet Tag für Tag sein Heil!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 96, 3, 'Erzählt von seiner Herrlichkeit unter den Heiden, unter allen Völkern seine Wundertaten!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 96, 4, 'Denn groß ist der HERR und hoch zu preisen, mehr zu fürchten als alle andern Götter;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 96, 5, 'denn alle Götter der Heiden sind nichtige Götzen, doch der HERR hat den Himmel geschaffen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 96, 6, 'Hoheit und Pracht gehn vor ihm her, Macht und Herrlichkeit füllen sein Heiligtum.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 96, 7, 'Bringt dar dem HERRN, ihr Geschlechter der Völker, bringt dar dem HERRN Ehre und Preis!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 96, 8, 'Bringt dar dem HERRN die Ehre seines Namens, bringt Opfergaben und kommt in seine Vorhöfe!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 96, 9, 'Werft vor dem HERRN euch nieder in heiligem Schmuck, erzittert vor ihm, alle Lande!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 96, 10, 'Verkündet unter den Heiden: »Der HERR ist König! Und feststehn wird der Erdkreis, daß er nicht wankt; richten wird er die Völker nach Gebühr.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 96, 11, 'Des freue sich der Himmel, die Erde jauchze, es brause das Meer und was darin wimmelt!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 96, 12, 'Es jauchze die Flur und was auf ihr wächst! Dann werden auch jubeln alle Bäume des Waldes');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 96, 13, 'vor dem HERRN, wenn er kommt, wenn er kommt, zu richten die Erde. Richten wird er den Erdkreis mit Gerechtigkeit und die Völker mit seiner Treue.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 97, 1, 'Der HERR ist König! Des juble die Erde, die Menge der Meeresländer möge sich freuen!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 97, 2, 'Gewölk und Dunkel umgibt ihn rings, Gerechtigkeit und Recht sind seines Throns Stützen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 97, 3, 'Feuer geht vor ihm her und rafft seine Feinde ringsum hinweg.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 97, 4, 'Seine Blitze erleuchten den Erdkreis: die Erde sieht’s und erbebt in Angst.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 97, 5, 'Die Berge zerschmelzen wie Wachs vor dem HERRN, vor dem Herrscher der ganzen Erde.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 97, 6, 'Die Himmel verkünden seine Gerechtigkeit und alle Völker sehn seine Herrlichkeit.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 97, 7, 'Zuschanden sollen werden alle Bilderverehrer, die der nichtigen Götzen sich rühmen: alle Götter werfen vor ihm sich nieder.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 97, 8, 'Zion vernimmt es mit Freuden, und die Töchter Judas jauchzen um deiner Gerichte willen, o HERR.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 97, 9, 'Denn du, HERR, bist der Höchste über die ganze Erde, hoch erhaben über alle Götter.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 97, 10, 'Die den HERRN ihr lieb habt, hasset das Böse! Er, der die Seelen seiner Frommen behütet, wird sie erretten aus der Gottlosen Hand.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 97, 11, 'Licht erstrahlt dem Gerechten und Freude den redlich Gesinnten.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 97, 12, 'Freut euch des HERRN, ihr Gerechten, und preist seinen heiligen Namen!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 98, 1, 'Ein Psalm. Singet dem HERRN ein neues Lied! Denn Wunderbares hat er vollbracht: den Sieg hat seine Rechte ihm verschafft und sein heiliger Arm.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 98, 2, 'Der HERR hat kundgetan sein hilfreiches Tun, vor den Augen der Völker seine Gerechtigkeit offenbart.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 98, 3, 'Er hat gedacht seiner Gnade und Treue gegenüber dem Hause Israel: alle Enden der Erde haben geschaut die Heilstat unsers Gottes.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 98, 4, 'Jauchzet dem HERRN, alle Lande, brecht in Jubel aus und spielt!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 98, 5, 'Spielet zu Ehren des HERRN auf der Zither, auf der Zither und mit lautem Gesang,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 98, 6, 'mit Trompeten und Posaunenschall! Jauchzt vor dem HERRN, dem König!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 98, 7, 'Es tose das Meer und was darin wimmelt, der Erdkreis und seine Bewohner!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 98, 8, 'Die Ströme sollen in die Hände klatschen, die Berge allesamt jubeln');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 98, 9, 'vor dem HERRN, wenn er kommt, zu richten die Erde. Richten wird er den Erdkreis mit Gerechtigkeit und die Völker nach Gebühr.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 99, 1, 'Der HERR ist König: es zittern die Völker; er thront über den Cheruben: es wankt die Erde.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 99, 2, 'Groß ist der HERR in Zion und hocherhaben über alle Völker.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 99, 3, 'Preisen sollen sie deinen Namen, den großen und hehren – heilig ist er –,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 99, 4, 'und preisen die Stärke des Königs, der da liebt das Recht. Du hast gerechte Ordnung fest gegründet, Recht und Gerechtigkeit hast du in Jakob hergestellt.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 99, 5, 'Erhebet den HERRN, unsern Gott, und werft euch nieder vor dem Schemel seiner Füße: heilig ist er!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 99, 6, 'Mose und Aaron waren unter seinen Priestern und Samuel unter denen, die seinen Namen anriefen: sie riefen zum HERRN, und er erhörte sie.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 99, 7, 'In der Wolkensäule redete er zu ihnen; sie wahrten seine Gebote, das Gesetz, das er ihnen gegeben.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 99, 8, 'O HERR, unser Gott, du hast sie erhört, ein verzeihender Gott bist du ihnen gewesen, doch auch ein strafender ob ihrer Vergehen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 99, 9, 'Erhebet den HERRN, unsern Gott, und werft euch nieder auf seinem heiligen Berge, denn heilig ist der HERR, unser Gott!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 100, 1, 'Ein Psalm als Dankbezeigung. Jauchzet dem HERRN, alle Lande,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 100, 2, 'dienet dem HERRN mit Freuden, kommt vor sein Angesicht mit Jubel!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 100, 3, 'Erkennt, daß der HERR Gott ist! Er hat uns geschaffen, und sein sind wir, sein Volk und die Herde, die er weidet.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 100, 4, 'Zieht ein durch seine Tore mit Danken, in seines Tempels Höfe mit Lobgesang, dankt ihm, preist seinen Namen!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 100, 5, 'Denn freundlich ist der HERR, seine Gnade währt ewig und seine Treue von Geschlecht zu Geschlecht.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 101, 1, 'Von David, ein Psalm. Von Gnade und Recht will ich singen, dir, o HERR, will ich spielen!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 101, 2, 'Achten will ich auf fehllosen Wandel wann wirst du zu mir kommen? In Herzensreinheit will ich wandeln im Innern meines Hauses.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 101, 3, 'Ich will nicht mein Auge gerichtet halten auf schandbare Dinge; das Tun der Abtrünnigen hasse ich: es soll mir nicht anhaften.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 101, 4, 'Ein falsches Herz soll fern von mir bleiben, einen Bösen will ich nicht kennen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 101, 5, 'Wer seinen Nächsten heimlich verleumdet, den will ich zum Schweigen bringen; wer stolze Augen hat und ein hoffärtig Herz, den werde ich nicht ertragen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 101, 6, 'Meine Augen sollen blicken auf die Treuen im Lande: die sollen bei mir wohnen; wer auf frommen Wege wandelt, der soll mir dienen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 101, 7, 'Nicht darf inmitten meines Hauses weilen, wer Trug verübt; wer Lügen redet, soll nicht bestehn vor meinen Augen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 101, 8, 'Jeden Morgen will ich unschädlich machen alle Frevler im Lande, um auszurotten aus der Stadt des HERRN alle Übeltäter.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 102, 1, 'Gebet eines Elenden, wenn er verzagt ist und seine Klage vor dem Herrn ausschüttet.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 102, 2, 'HERR, höre mein Gebet und laß mein Schreien zu dir dringen!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 102, 3, 'Verbirg dein Angesicht nicht vor mir am Tage, wo mir angst ist! Neige dein Ohr mir zu am Tage, wo ich rufe; erhöre mich eilends!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 102, 4, 'Ach, meine Tage sind wie Rauch entschwunden und meine Gebeine wie von Brand durchglüht;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 102, 5, 'mein Herz ist versengt und verdorrt wie Gras, so daß ich sogar vergesse, Speise zu genießen;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 102, 6, 'infolge meines Ächzens und Stöhnens klebt mein Gebein mir am Fleisch.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 102, 7, 'Ich gleiche dem Wasservogel in der Wüste, bin geworden wie ein Käuzlein in Trümmerstätten;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 102, 8, 'ich finde keinen Schlaf und klage wie ein einsamer Vogel auf dem Dache.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 102, 9, 'Tagtäglich schmähen mich meine Feinde; und die gegen mich toben, wünschen mir Unheil an.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 102, 10, 'Ach, Asche eß ich als Brot und mische meinen Trank mit Tränen');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 102, 11, 'ob deinem Zorn und deinem Grimm; denn du hast mich hochgehoben und niedergeschleudert.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 102, 12, 'Meine Tage sind wie ein langgestreckter Schatten, und ich selbst verdorre wie Gras!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 102, 13, 'Du aber, HERR, thronst ewiglich, und dein Gedächtnis bleibt von Geschlecht zu Geschlecht.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 102, 14, 'Du wirst dich erheben, dich Zions erbarmen, denn Zeit ist’s, Gnade an ihm zu üben: die Stunde ist da');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 102, 15, '- denn deine Knechte lieben Zions Steine, und Weh erfaßt sie um seinen Schutt –,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 102, 16, 'damit die Heiden fürchten lernen den Namen des HERRN und alle Könige der Erde deine Herrlichkeit.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 102, 17, 'Denn der HERR hat Zion wieder aufgebaut, ist in seiner Herrlichkeit dort erschienen,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 102, 18, 'hat dem Gebet der Verlass’nen sich zugewandt und ihr Flehen nicht verachtet.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 102, 19, 'Dies werde aufgeschrieben fürs kommende Geschlecht, damit das neugeschaffne Volk den HERRN lobpreise,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 102, 20, 'daß von seiner heiligen Höhe er herabgeschaut, daß der HERR geblickt hat vom Himmel zur Erde,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 102, 21, 'um das Seufzen der Gefangnen zu hören und die dem Tode Geweihten frei zu machen,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 102, 22, 'damit man verkünde in Zion den Namen des HERRN und seinen Ruhm in Jerusalem,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 102, 23, 'wenn die Völker sich allzumal versammeln und die Königreiche, um (Gott) dem HERRN zu dienen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 102, 24, 'Gelähmt hat er mir auf dem Wege die Kraft, hat verkürzt meine Lebenstage.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 102, 25, 'Nun fleh’ ich: »Mein Gott, raffe mich nicht hinweg in der Mitte meiner Tage, du, dessen Jahre währen für und für!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 102, 26, 'Vorzeiten hast du die Erde gegründet, und die Himmel sind deiner Hände Werk:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 102, 27, 'sie werden vergehen, du aber bleibst; sie werden alle zerfallen wie ein Gewand, wie ein Kleid wirst du sie verwandeln, und so werden sie sich wandeln.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 102, 28, 'Du aber bleibst derselbe, und deine Jahre nehmen kein Ende.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 102, 29, 'Die Kinder deiner Knechte werden (sicher) wohnen, und ihr Geschlecht wird fest bestehen vor dir.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 103, 1, 'Von David. Lobe den HERRN, meine Seele, und all mein Inneres seinen heiligen Namen!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 103, 2, 'Lobe den HERRN, meine Seele, und vergiß nicht, was er dir Gutes getan!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 103, 3, 'Der dir alle deine Schuld vergibt und alle deine Gebrechen heilt;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 103, 4, 'der dein Leben erlöst vom Verderben, der dich krönt mit Gnade und Erbarmen;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 103, 5, 'der dein Alter mit guten Gaben sättigt, daß, dem Adler gleich, sich erneut deine Jugend.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 103, 6, 'Gerechtigkeit übt der HERR, schafft allen Unterdrückten ihr Recht;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 103, 7, 'er hat Mose seine Wege kundgetan, den Kindern Israel seine Großtaten.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 103, 8, 'Barmherzig und gnädig ist der HERR, voller Langmut und reich an Güte;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 103, 9, 'er wird nicht ewig hadern und den Zorn nicht immerdar festhalten;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 103, 10, 'er handelt nicht mit uns nach unsern Sünden und vergilt uns nicht nach unsern Missetaten;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 103, 11, 'nein, so hoch der Himmel über der Erde ist, so groß ist seine Gnade über denen, die ihn fürchten;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 103, 12, 'so fern der Sonnenaufgang ist vom Niedergang, läßt er unsre Verschuldungen fern von uns sein;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 103, 13, 'wie ein Vater sich über die Kinder erbarmt, so erbarmt der HERR sich derer, die ihn fürchten.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 103, 14, 'Denn er weiß, welch ein Gebilde wir sind, er denkt daran, daß wir Staub sind.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 103, 15, 'Der Mensch – dem Grase gleicht seine Lebenszeit, wie die Blume des Feldes, so blüht er:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 103, 16, 'wenn ein Windstoß über sie hinfährt, ist sie dahin, und ihr Standort weiß nichts mehr von ihr.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 103, 17, 'Doch die Gnade des HERRN erweist sich von Ewigkeit zu Ewigkeit an denen, die ihn fürchten, und seine Gerechtigkeit besteht für Kindeskinder');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 103, 18, 'bei denen, die seinen Bund bewahren und seiner Gebote gedenken, um sie auszuführen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 103, 19, 'Der HERR hat seinen Thron im Himmel festgestellt, und seine Königsmacht umschließt das All.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 103, 20, 'Lobet den HERRN, ihr seine Engel, ihr starken Helden, die ihr sein Wort vollführt, gehorsam der Stimme seines Gebots!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 103, 21, 'Lobet den HERRN, alle seine Heerscharen, ihr seine Diener, Vollstrecker seines Willens!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 103, 22, 'Lobet den HERRN, alle seine Werke an allen Orten seiner Herrschaft! Lobe den HERRN, meine Seele!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 104, 1, 'Lobe den HERRN, meine Seele! O HERR, mein Gott, wie bist du so groß! In Erhabenheit und Pracht bist du gekleidet,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 104, 2, 'du, der in Licht sich hüllt wie in ein Gewand, der den Himmel ausspannt wie ein Zeltdach,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 104, 3, 'der die Balken seines Palastes im Wasser festlegt, der Wolken macht zu seinem Wagen, einherfährt auf den Flügeln des Windes;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 104, 4, 'der Winde zu seinen Boten bestellt, zu seinen Dienern lohendes Feuer.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 104, 5, 'Er hat die Erde gegründet auf ihre Pfeiler, so daß sie in alle Ewigkeit nicht wankt.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 104, 6, 'Mit der Urflut gleich einem Kleide bedecktest du sie: bis über die Berge standen die Wasser;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 104, 7, 'doch vor deinem Schelten flohen sie, vor der Stimme deines Donners wichen sie angstvoll zurück.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 104, 8, 'Da stiegen die Berge empor, und die Täler senkten sich an den Ort, den du ihnen verordnet.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 104, 9, 'Eine Grenze hast du gesetzt, die sie nicht überschreiten: sie dürfen die Erde nicht nochmals bedecken.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 104, 10, 'Quellen läßt er den Bächen zugehn: zwischen den Bergen rieseln sie dahin;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 104, 11, 'sie tränken alles Getier des Feldes, die Wildesel löschen ihren Durst;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 104, 12, 'an ihnen wohnen die Vögel des Himmels, lassen ihr Lied aus den Zweigen erschallen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 104, 13, 'Er tränkt die Berge aus seinem Himmelspalast: vom Segen deines Schaffens wird die Erde satt.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 104, 14, 'Gras läßt er sprossen für das Vieh und Pflanzen für den Bedarf der Menschen, um Brotkorn aus der Erde hervorgehn zu lassen und Wein, der des Menschen Herz erfreut;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 104, 15, 'um jedes Antlitz erglänzen zu lassen vom Öl und durch Brot das Herz des Menschen zu stärken.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 104, 16, 'Es trinken sich satt die Bäume des HERRN, die Zedern des Libanons, die er gepflanzt,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 104, 17, 'woselbst die Vögel ihre Nester bauen, der Storch, der Zypressen zur Wohnung wählt.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 104, 18, 'Die hohen Berge gehören den Gemsen, die Felsen sind der Klippdachse Zuflucht.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 104, 19, 'Er hat den Mond gemacht zur Bestimmung der Zeiten, die Sonne, die ihren Niedergang kennt.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 104, 20, 'Läßt du Finsternis entstehn, so wird es Nacht, da regt sich alles Getier des Waldes:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 104, 21, 'die jungen Löwen brüllen nach Raub, indem sie von Gott ihre Nahrung fordern.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 104, 22, 'Geht die Sonne auf, so ziehn sie sich zurück und kauern in ihren Höhlen;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 104, 23, 'dann geht der Mensch hinaus an seine Arbeit und an sein Tagwerk bis zum Abend.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 104, 24, 'Wie sind deiner Werke so viele, o HERR! Du hast sie alle mit Weisheit geschaffen, voll ist die Erde von deinen Geschöpfen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 104, 25, 'Da ist das Meer, so groß und weit nach allen Seiten: drin wimmelt es ohne Zahl von Tieren klein und groß.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 104, 26, 'Dort fahren die Schiffe einher; da ist der Walfisch, den du geschaffen, darin sich zu tummeln.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 104, 27, 'Sie alle schauen aus zu dir hin, daß du Speise ihnen gebest zu seiner Zeit;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 104, 28, 'gibst du sie ihnen, so lesen sie auf; tust deine Hand du auf, so werden sie satt des Guten;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 104, 29, 'doch verbirgst du dein Angesicht, so befällt sie Schrecken; nimmst du weg ihren Odem, so sterben sie und kehren zurück zum Staub, woher sie gekommen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 104, 30, 'Läßt du ausgehn deinen Odem, so werden sie geschaffen, und so erneust du das Antlitz der Erde.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 104, 31, 'Ewig bleibe die Ehre des HERRN bestehn, es freue der HERR sich seiner Werke!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 104, 32, 'Blickt er die Erde an, so erbebt sie; rührt er die Berge an, so stehn sie in Rauch.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 104, 33, 'Singen will ich dem HERRN mein Leben lang, will spielen meinem Gott, solange ich bin.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 104, 34, 'Möge mein Sinnen ihm wohlgefällig sein: ich will meine Freude haben am HERRN!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 104, 35, 'Möchten die Sünder verschwinden vom Erdboden und die Gottlosen nicht mehr sein! – Lobe den HERRN, meine Seele! Halleluja!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 1, 'Preiset den HERRN, ruft seinen Namen an, macht seine Taten unter den Völkern bekannt!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 2, 'Singt ihm, spielet ihm, redet von all seinen Wundern!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 3, 'Rühmt euch seines heiligen Namens! Es mögen herzlich sich freun, die da suchen den HERRN!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 4, 'Fragt nach dem HERRN und seiner Stärke, suchet sein Angesicht allezeit!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 5, 'Gedenkt seiner Wunder, die er getan, seiner Zeichen und der Urteilssprüche seines Mundes,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 6, 'ihr Kinder Abrahams, seines Knechtes, ihr Söhne Jakobs, seine Erwählten!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 7, 'Er, der HERR, ist unser Gott, über die ganze Erde ergehen seine Gerichte.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 8, 'Er gedenkt seines Bundes auf ewig, des Wortes, das er geboten auf tausend Geschlechter,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 9, '(des Bundes) den er mit Abraham geschlossen, und des Eides, den er Isaak geschworen,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 10, 'den für Jakob er als Satzung bestätigt und für Israel als ewigen Bund,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 11, 'da er sprach: »Dir will ich Kanaan geben, das Land, das ich euch als Erbbesitztum zugeteilt!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 12, 'Damals waren sie noch ein kleines Häuflein, gar wenige und nur Gäste im Lande;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 13, 'sie mußten wandern von Volk zu Volk, von einem Reich zur andern Völkerschaft;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 14, 'doch keinem gestattete er, sie zu bedrücken, ja Könige strafte er ihretwillen:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 15, '»Tastet meine Gesalbten nicht an und tut meinen Propheten nichts zuleide!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 16, 'Dann, als er Hunger ins Land ließ kommen und jegliche Stütze des Brotes zerbrach,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 17, 'da hatte er schon einen Mann vor ihnen her gesandt: Joseph, der als Sklave verkauft war.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 18, 'Man hatte seine Füße gezwängt in den Stock, in Eisen(-fesseln) war er gelegt,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 19, 'bis zu der Zeit, wo seine Weissagung eintraf und der Ausspruch des HERRN ihn als echt erwies.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 20, 'Da sandte der König und ließ ihn entfesseln, der Völkergebieter, und machte ihn frei;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 21, 'er bestellte ihn über sein Haus zum Herrn, zum Gebieter über sein ganzes Besitztum;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 22, 'er sollte über seine Fürsten schalten nach Belieben und seine höchsten Beamten Weisheit lehren.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 23, 'So kam denn Israel nach Ägypten, und Jakob weilte als Gast im Lande Hams.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 24, 'Da machte Gott sein Volk gar fruchtbar und ließ es stärker werden als seine Bedränger;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 25, 'er wandelte ihren Sinn, sein Volk zu hassen und Arglist an seinen Knechten zu üben.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 26, 'Dann sandte er Mose, seinen Knecht, und Aaron, den er erkoren;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 27, 'die richteten seine Zeichen unter ihnen aus und die Wunder im Lande Hams:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 28, 'Er sandte Finsternis und ließ es dunkel werden; doch sie achteten nicht auf seine Worte;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 29, 'er verwandelte ihre Gewässer in Blut und ließ ihre Fische sterben;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 30, 'es wimmelte ihr Land von Fröschen bis hinein in ihre Königsgemächer;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 31, 'er gebot, da kamen Bremsenschwärme, Stechfliegen über ihr ganzes Gebiet;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 32, 'er gab ihnen Hagelschauer als Regen, sandte flammendes Feuer in ihr Land;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 33, 'er schlug ihre Reben und Feigenbäume und zerbrach die Bäume in ihrem Gebiet;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 34, 'er gebot, da kamen die Heuschrecken und die Grillen in zahlloser Menge,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 35, 'die verzehrten alle Gewächse im Land und fraßen die Früchte ihrer Felder.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 36, 'Dann schlug er alle Erstgeburt im Lande, die Erstlinge all ihrer Manneskraft.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 37, 'Nun ließ er sie ausziehn mit Silber und Gold, und kein Strauchelnder war in seinen Stämmen;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 38, 'Ägypten war ihres Auszugs froh, denn Angst vor ihnen hatte sie befallen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 39, 'Er breitete Gewölk aus als Decke und Feuer, um ihnen die Nacht zu erhellen;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 40, 'auf Moses Bitte ließ er Wachteln kommen und sättigte sie mit Himmelsbrot;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 41, 'er spaltete einen Felsen: da rannen Wasser und flossen durch die Steppen als Strom;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 42, 'denn er gedachte seines heiligen Wortes, dachte an Abraham, seinen Knecht.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 43, 'So ließ er sein Volk in Freuden ausziehn, unter Jubel seine Erwählten;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 44, 'dann gab er ihnen die Länder der Heiden, und was die Völker erworben, das nahmen sie in Besitz,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 45, 'auf daß sie seine Gebote halten möchten und seine Gesetze bewahrten. Halleluja!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 1, 'Halleluja! Preiset den HERRN, denn er ist freundlich, ja ewiglich währt seine Gnade!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 2, 'Wer kann des HERRN Machttaten gebührend preisen und kundtun all seinen Ruhm?');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 3, 'Wohl denen, die am Recht festhalten, und dem, der Gerechtigkeit übt zu jeder Zeit!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 4, 'Gedenke meiner, o HERR, mit der Liebe zu deinem Volk, nimm dich meiner an mit deiner Hilfe,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 5, 'daß ich schau’ meine Lust am Glück deiner Erwählten, an der Freude deines Volkes Anteil habe und glücklich mich preise mit deinem Eigentumsvolke!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 6, 'Wir haben gesündigt gleich unsern Vätern, wir haben gefehlt und gottlos gehandelt.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 7, 'Unsre Väter in Ägypten achteten nicht auf deine Wunder, gedachten nicht der Fülle deiner Gnadenerweise, waren widerspenstig gegen den Höchsten schon am Schilfmeer;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 8, 'dennoch half er ihnen um seines Namens willen, um seine Heldenkraft zu erweisen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 9, 'Er schalt das Schilfmeer: da ward es trocken, und er ließ sie ziehn durch die Fluten wie über die Trift.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 10, 'So rettete er sie aus der Hand des Verfolgers und erlöste sie aus der Gewalt des Feindes:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 11, 'die Fluten bedeckten ihre Bedränger, nicht einer von ihnen blieb übrig.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 12, 'Da glaubten sie an seine Worte, besangen seinen Ruhm.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 13, 'Doch schnell vergaßen sie seine Taten und warteten seinen Ratschluß nicht ab;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 14, 'sie fröhnten ihrem Gelüst in der Wüste und versuchten Gott in der Einöde:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 15, 'da gewährte er ihnen ihr Verlangen, sandte aber die Seuche gegen ihr Leben.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 16, 'Dann wurden sie eifersüchtig auf Mose im Lager, auf Aaron, den Geweihten des HERRN:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 17, 'da tat die Erde sich auf und verschlang Dathan und begrub die ganze Rotte Abirams,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 18, 'Feuer verbrannte ihre Rotte, Flammen verzehrten die Frevler.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 19, 'Sie machten sich ein Kalb am Horeb und warfen vor einem Gußbild sich nieder');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 20, 'und vertauschten so die Herrlichkeit ihres Gottes mit dem Bildnis eines Stieres, der Gras frißt.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 21, 'Sie hatten Gott, ihren Retter, vergessen, der große Dinge getan in Ägypten,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 22, 'Wunderzeichen im Lande Hams, furchtbare Taten am Schilfmeer.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 23, 'Da gedachte er sie zu vertilgen, wenn nicht Mose, sein Auserwählter, mit Fürbitte vor ihn hingetreten wäre, um seinen Grimm vom Vernichten abzuwenden.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 24, 'Sodann verschmähten sie das herrliche Land und schenkten seiner Verheißung keinen Glauben,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 25, 'sondern murrten in ihren Zelten, gehorchten nicht der Weisung des HERRN.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 26, 'Da erhob er seine Hand gegen sie zum Schwur, sie in der Wüste niederzuschlagen,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 27, 'ihre Nachkommen unter die Heiden niederzuwerfen und sie rings zu zerstreuen in die Länder.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 28, 'Dann hängten sie sich an den Baal-Peor und aßen Opferfleisch der toten (Götzen)');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 29, 'und erbitterten ihn durch ihr ganzes Tun. Als nun ein Sterben unter ihnen ausbrach,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 30, 'trat Pinehas auf und hielt Gericht: da wurde dem Sterben Einhalt getan.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 31, 'Das wurde ihm angerechnet zur Gerechtigkeit von Geschlecht zu Geschlecht in Ewigkeit. –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 32, 'Dann erregten sie Gottes Zorn am Haderwasser, und Mose erging es übel um ihretwillen;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 33, 'denn weil sie dem Geiste Gottes widerstrebten, hatte er unbedacht mit seinen Lippen geredet.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 34, 'Sie vertilgten auch die Völker nicht, von denen der HERR es ihnen geboten,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 35, 'sondern traten mit den Heiden in Verkehr und gewöhnten sich an deren (böses) Tun');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 36, 'und dienten ihren Götzen: die wurden ihnen zum Fallstrick.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 37, 'Ja, sie opferten ihre Söhne und ihre Töchter den bösen Geistern');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 38, 'und vergossen unschuldig Blut [das Blut ihrer Söhne und Töchter, die sie den Götzen Kanaans opferten]: so wurde das Land durch Blutvergießen entweiht.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 39, 'Sie wurden unrein durch ihr Verhalten und verübten Abfall durch ihr Tun. –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 40, 'Da entbrannte der Zorn des HERRN gegen sein Volk, und Abscheu fühlte er gegen sein Erbe;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 41, 'er ließ sie in die Hand der Heiden fallen, so daß ihre Hasser über sie herrschten;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 42, 'ihre Feinde bedrängten sie hart, so daß sie sich beugen mußten unter deren Hand.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 43, 'Oftmals zwar befreite er sie, doch sie blieben widerspenstig gegen seinen Ratschluß und sanken immer tiefer durch ihre Schuld.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 44, 'Er aber nahm sich ihrer Drangsal an, sooft er ihr Wehgeschrei hörte,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 45, 'und gedachte seines Bundes ihnen zugut, fühlte Mitleid nach seiner großen Güte');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 46, 'und ließ sie Erbarmen finden bei allen, die sie gefangen hielten.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 47, 'O hilf uns, HERR, unser Gott, und bring uns wieder zusammen aus den Heiden, damit wir deinem heiligen Namen danken, uns glücklich preisen, deinen Ruhm zu künden!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 48, 'Gepriesen sei der HERR, der Gott Israels, von Ewigkeit zu Ewigkeit! Und alles Volk sage »Amen!« Halleluja!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 1, '»Danket dem HERRN, denn er ist freundlich, ja, ewiglich währt seine Gnade«:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 2, 'so sollen die vom HERRN Erlösten sprechen, die er befreit hat aus Drangsal');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 3, 'und die er gesammelt aus den Ländern vom Aufgang her und vom Niedergang, vom Norden her und vom Meer.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 4, 'Sie irrten umher in der Wüste, der Öde, und fanden den Weg nicht zu einer Wohnstatt;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 5, 'gequält vom Hunger und vom Durst, wollte ihre Seele in ihnen verschmachten.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 6, 'Da schrien sie zum HERRN in ihrer Not, und er rettete sie aus ihren Ängsten');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 7, 'und leitete sie auf richtigem Wege, daß sie kamen zu einer bewohnten Ortschaft: –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 8, 'die mögen danken dem HERRN für seine Güte und für seine Wundertaten an den Menschenkindern,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 9, 'daß er die lechzende Seele gesättigt und die hungernde Seele gefüllt hat mit Labung.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 10, 'Die da saßen in Finsternis und Todesnacht, gefangen in Elend und Eisenbanden –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 11, 'denn sie hatten Gottes Geboten getrotzt und den Ratschluß des Höchsten verachtet,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 12, 'so daß er ihren Sinn durch Leiden beugte, daß sie niedersanken und keinen Helfer hatten –;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 13, 'da schrien sie zum HERRN in ihrer Not, und er rettete sie aus ihren Ängsten;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 14, 'er führte sie heraus aus Finsternis und Todesnacht und zersprengte ihre Fesseln: –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 15, 'die mögen danken dem HERRN für seine Güte und für seine Wundertaten an den Menschenkindern,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 16, 'daß er eherne Türen zerbrochen und eiserne Riegel zerschlagen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 17, 'Die da krank waren infolge ihres Sündenlebens und wegen ihrer Verfehlungen leiden mußten –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 18, 'vor jeglicher Speise hatten sie Widerwillen, so daß sie den Pforten des Todes nahe waren –;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 19, 'da schrien sie zum HERRN in ihrer Not, und er rettete sie aus ihren Ängsten;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 20, 'er sandte sein Wort, sie gesund zu machen, und ließ sie aus ihren Gruben entrinnen: –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 21, 'die mögen danken dem HERRN für seine Güte und für seine Wundertaten an den Menschenkindern;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 22, 'sie mögen Opfer des Dankes bringen und seine Taten mit Jubel verkünden!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 23, 'Die aufs Meer gefahren waren in Schiffen, auf weiten Fluten Handelsgeschäfte trieben,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 24, 'die haben das Walten des HERRN geschaut und seine Wundertaten auf hoher See.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 25, 'Denn er gebot und ließ einen Sturm entstehn, der hoch die Wogen des Meeres türmte:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 26, 'sie stiegen empor zum Himmel und fuhren hinab in die Tiefen, so daß ihr Herz vor Angst verzagte;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 27, 'sie wurden schwindlig und schwankten wie Trunkne, und mit all ihrer Weisheit war’s zu Ende: –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 28, 'da schrien sie zum HERRN in ihrer Not, und er befreite sie aus ihren Ängsten;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 29, 'er stillte das Ungewitter zum Säuseln, und das Toben der Wogen verstummte;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 30, 'da wurden sie froh, daß es still geworden, und er führte sie zum ersehnten Hafen: –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 31, 'die mögen danken dem HERRN für seine Güte und für seine Wundertaten an den Menschenkindern;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 32, 'sie mögen ihn erheben in der Volksgemeinde und im Kreise der Alten ihn preisen!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 33, 'Er wandelte Ströme zur Wüste und Wasserquellen zu dürrem Land,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 34, 'fruchtbares Erdreich zu salziger Steppe wegen der Bosheit seiner Bewohner.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 35, 'Wiederum machte er wüstes Land zum Wasserteich und dürres Gebiet zu Wasserquellen');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 36, 'und ließ dort Hungrige seßhaft werden, so daß sie eine Stadt zum Wohnsitz bauten');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 37, 'und Felder besäten und Weinberge pflanzten, die reichen Ertrag an Früchten brachten;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 38, 'und er segnete sie, daß sie stark sich mehrten, und ließ ihres Viehs nicht wenig sein.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 39, 'Dann aber nahmen sie ab und wurden gebeugt durch den Druck des Unglücks und Kummers;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 40, '»über Edle goß er Verachtung aus und ließ sie irren in pfadloser Öde«.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 41, 'Den Armen aber hob er empor aus dem Elend und machte seine Geschlechter wie Kleinviehherden.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 42, '»Die Gerechten sehen’s und freuen sich, alle Bosheit aber muß schließen ihren Mund«.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 43, 'Wer ist weise? Der beachte dies und lerne die Gnadenerweise des HERRN verstehn!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 108, 1, 'Ein Lied, ein Psalm Davids.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 108, 2, 'Mein Herz ist getrost, o Gott: singen will ich und spielen! Wach auf, meine Seele!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 108, 3, 'Wacht auf, Harfe und Zither: ich will das Morgenrot wecken!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 108, 4, 'Ich will dich preisen unter den Völkern, o HERR, und dir lobsingen unter den Völkerschaften!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 108, 5, 'Denn groß bis über den Himmel hinaus ist deine Gnade, und bis an die Wolken geht deine Treue.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 108, 6, 'Erhebe dich über den Himmel hinaus, o Gott, und über die ganze Erde (verbreite sich) deine Herrlichkeit!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 108, 7, 'Daß deine Geliebten gerettet werden, hilf uns mit deiner Rechten, erhör’ uns!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 108, 8, 'Gott hat in seiner Heiligkeit gesprochen: »(Als Sieger) will ich frohlocken, will Sichem verteilen und das Tal von Sukkoth (als Beutestück) vermessen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 108, 9, 'Mein ist Gilead, mein auch Manasse, und Ephraim ist meines Hauptes Schutzwehr, Juda mein Herrscherstab.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 108, 10, 'Moab (dagegen) ist mein Waschbecken, auf Edom werf’ ich meinen Schuh; über das Philisterland will (als Sieger) ich jauchzen.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 108, 11, 'Wer führt mich hin zur festen Stadt, wer geleitet mich bis Edom?');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 108, 12, 'Hast nicht du uns, o Gott, verworfen und ziehst nicht aus, o Gott, mit unsern Heeren?');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 108, 13, 'O schaffe uns Hilfe gegen den Feind! Denn nichtig ist Menschenhilfe.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 108, 14, 'Mit Gott werden wir Taten vollführen, und er wird unsre Bedränger zertreten.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 109, 1, 'Dem Musikmeister; von David ein Psalm. Du Gott, dem mein Lobpreis gilt, bleibe nicht stumm!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 109, 2, 'Denn Frevlermund und Lügenmaul haben sich gegen mich aufgetan, mit trügerischer Zunge zu mir geredet;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 109, 3, 'mit Worten des Hasses haben sie mich umschwirrt und ohne Ursach’ mich angegriffen;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 109, 4, 'für meine Liebe befeinden sie mich, während ich doch (stets für sie) bete;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 109, 5, 'ja sie haben mir Böses für Gutes vergolten und Haß für meine Liebe erwiesen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 109, 6, 'Bestell’ einen Frevler zum Richter gegen ihn, und ein Ankläger steh’ ihm zur Rechten!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 109, 7, 'Als schuldig soll er hervorgehn aus dem Gericht und sogar sein Gebet ihm als Sünde gelten!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 109, 8, 'Seiner Lebenstage müssen nur wenige sein, und sein Amt ein andrer empfangen!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 109, 9, 'Seine Kinder müssen zu Waisen werden und seine Frau eine Witwe!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 109, 10, 'Seine Kinder müssen unstet umherziehn und betteln und vertrieben werden aus ihres Vaterhauses Trümmern!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 109, 11, 'Sein Gläubiger lege Beschlag auf alles, was er hat, und Fremde müssen seine Habe plündern!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 109, 12, 'Er finde keinen, der ihm Schonung gewährt, und niemand habe Erbarmen mit seinen Waisen!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 109, 13, 'Sein Nachwuchs müsse der Ausrottung verfallen: schon im zweiten Gliede müsse ihr Name erlöschen!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 109, 14, 'Der Verschuldung seiner Väter werde beim HERRN gedacht, und die Sünde seiner Mutter bleibe ungetilgt!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 109, 15, 'Sie müssen beständig dem HERRN vor Augen stehn, und er tilge ihr Gedächtnis aus von der Erde,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 109, 16, 'dieweil er nicht daran dachte, Liebe zu üben, vielmehr den Elenden und Armen verfolgte und den hoffnungslos Verzagten, ihn vollends zu töten.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 109, 17, 'Er liebte den Fluch: so treffe er ihn! Er hatte am Segen keine Freude: so bleib’ er ihm fern!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 109, 18, 'Er zog den Fluch an wie sein Kleid: so dringe er ihm in den Leib wie Wasser und wie Öl in seine Gebeine;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 109, 19, 'er werde ihm wie der Mantel, in den er sich hüllt, wie der Gürtel, den er sich ständig umlegt!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 109, 20, 'Dies sei meiner Widersacher Lohn von seiten des HERRN und derer, die Böses gegen mich reden!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 109, 21, 'Du aber, HERR, mein Gott, tritt für mich ein um deines Namens willen! Weil deine Gnade köstlich ist, errette mich!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 109, 22, 'Denn elend bin ich und arm, und mein Herz ist verwundet in meiner Brust.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 109, 23, 'Wie ein Schatten, wenn er sich dehnt, so schwinde ich hin, bin vom Sturm verweht einer Heuschrecke gleich;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 109, 24, 'meine Knie wanken vom Fasten, mein Leib ist abgemagert, ohne Fett;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 109, 25, 'und ich – den Leuten bin ich zum Hohn geworden: sehen sie mich, so schütteln sie höhnend den Kopf.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 109, 26, 'Stehe mir bei, o HERR, mein Gott, hilf mir nach deiner Gnade!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 109, 27, 'Laß sie erkennen, daß dies deine Hand ist, daß du, HERR, selbst es so gefügt hast!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 109, 28, 'Sie mögen fluchen, du aber wollest segnen; erheben sie sich, so laß sie zuschanden werden, dein Knecht aber müsse sich freuen!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 109, 29, 'Laß meine Widersacher in Schmach sich kleiden und ihre Schande umtun wie einen Mantel!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 109, 30, 'Laut soll mein Mund dem HERRN Dank sagen, und inmitten vieler will ich ihn preisen;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 109, 31, 'denn er steht dem Armen zur Rechten, um ihn zu retten vor denen, die ihn schuldig sprechen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 110, 1, 'Von David, ein Psalm. So lautet der Ausspruch des HERRN an meinen Herrn: »Setze dich zu meiner Rechten, bis ich deine Feinde hinlege zum Schemel für deine Füße!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 110, 2, 'Dein machtvolles Zepter wird der HERR von Zion hinausstrecken: herrsche inmitten deiner Feinde!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 110, 3, 'Dein Volk wird voller Willigkeit sein am Tage deines Heereszuges; in heiligem Schmuck, wie aus des Frührots Schoß der Tau, wird dir kommen deine junge Mannschaft.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 110, 4, 'Geschworen hat der HERR und wird sich’s nicht leid sein lassen: »Du sollst ein Priester in Ewigkeit sein nach der Weise Melchisedeks.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 110, 5, 'Der Allherr, der dir zur Rechten steht, wird Könige zerschmettern am Tage seines Zorns;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 110, 6, 'Gericht wird er unter den Völkern halten, füllt alles mit Leichen an, zerschmettert ein Haupt auf weitem Gefilde.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 110, 7, 'Aus dem Bach am Wege wird er trinken; darum wird er das Haupt hoch halten.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 111, 1, 'Halleluja! Preisen will ich den HERRN von ganzem Herzen im Kreise der Frommen und in der Gemeinde.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 111, 2, 'Groß sind die Werke des HERRN, erforschenswert für alle, die Gefallen an ihnen haben.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 111, 3, 'Ruhmvoll und herrlich ist sein Tun, und seine Gerechtigkeit bleibt ewig bestehn.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 111, 4, 'Er hat ein Gedächtnis seiner Wundertaten gestiftet; gnädig und barmherzig ist der HERR.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 111, 5, 'Speise hat er denen gegeben, die ihn fürchten; er gedenkt seines Bundes ewiglich.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 111, 6, 'Sein machtvolles Walten hat er kundgetan seinem Volk, indem er ihnen das Erbe der Heiden gab.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 111, 7, 'Die Werke seiner Hände sind Treue und Recht; unwandelbar sind alle seine Gebote,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 111, 8, 'festgestellt für immer, für ewig, gegeben mit Treue und Redlichkeit.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 111, 9, 'Erlösung hat er seinem Volk gesandt, seinen Bund auf ewig verordnet; heilig und furchtgebietend ist sein Name.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 111, 10, 'Die Furcht des HERRN ist der Weisheit Anfang, eine treffliche Einsicht für alle, die sie üben: sein Ruhm besteht in Ewigkeit.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 112, 1, 'Halleluja! Wohl dem Menschen, der den HERRN fürchtet, an seinen Geboten herzliche Freude hat!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 112, 2, 'Seine Nachkommen werden im Lande gewaltig sein, als ein Geschlecht von Frommen wird man sie segnen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 112, 3, 'Wohlstand und Fülle herrscht in seinem Hause, und seine Gerechtigkeit besteht für immer.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 112, 4, 'Den Frommen geht er auf wie ein Licht in der Finsternis, als gnädig, barmherzig und gerecht.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 112, 5, 'Glücklich der Mann, der Barmherzigkeit übt und darleiht! Er wird sein Recht behaupten vor Gericht;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 112, 6, 'denn nimmermehr wird er wanken: in ew’gem Gedächtnis bleibt der Gerechte.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 112, 7, 'Vor bösem Leumund braucht er sich nicht zu fürchten; sein Herz ist fest, voll Vertraun auf den HERRN.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 112, 8, 'Getrost ist sein Herz, er fürchtet sich nicht, bis er sieht seine Lust an seinen Bedrängern.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 112, 9, 'Reichlich teilt er aus und spendet den Armen; seine Gerechtigkeit besteht fest für immer, sein Horn ragt hoch empor in Ehren.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 112, 10, 'Der Gottlose sieht es und ärgert sich; er knirscht mit den Zähnen und vergeht; der Gottlosen Wünsche bleiben unerfüllt.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 113, 1, 'Halleluja! Lobet, ihr Knechte des HERRN, lobet den Namen des HERRN!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 113, 2, 'Gepriesen sei der Name des HERRN von nun an bis in Ewigkeit!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 113, 3, 'Vom Aufgang der Sonne bis zu ihrem Niedergang sei gelobt der Name des HERRN!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 113, 4, 'Erhaben über alle Völker ist der HERR, den Himmel überragt seine Herrlichkeit!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 113, 5, 'Wer ist dem HERRN gleich, unserm Gott, der da thront in der Höhe,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 113, 6, 'der niederschaut in die Tiefe, im Himmel und auf Erden?');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 113, 7, 'Er hebt aus dem Staub den Geringen empor und erhöht aus dem Schmutz den Armen,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 113, 8, 'um ihn sitzen zu lassen neben Edlen, neben den Edlen seines Volks.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 113, 9, 'Er verleiht der kinderlosen Gattin Hausrecht, macht sie zur fröhlichen Mutter von Kindern. Halleluja!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 114, 1, 'Halleluja! Als Israel aus Ägypten auszog, Jakobs Haus aus dem Volk fremder Sprache,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 114, 2, 'da ward Juda sein Heiligtum, Israel sein Herrschaftsgebiet.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 114, 3, 'Das Meer sah es und floh, der Jordan wandte sich rückwärts,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 114, 4, 'die Berge hüpften wie Widder, die Hügel gleichwie Lämmer.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 114, 5, 'Was war dir, o Meer, daß du flohest, dir, Jordan, daß du dich rückwärts wandtest?');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 114, 6, '(Was war euch) ihr Berge, daß ihr hüpftet wie Widder, ihr Hügel gleichwie Lämmer?');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 114, 7, 'Vor dem Anblick des Herrn erbebe, du Erde, vor dem Anblick des Gottes Jakobs,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 114, 8, 'der Felsen wandelt zum Wasserteich, Kieselgestein zum sprudelnden Quell!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 115, 1, 'Nicht uns, o HERR, nicht uns, nein, deinem Namen schaffe Ehre um deiner Gnade, um deiner Treue willen!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 115, 2, 'Warum sollen die Heiden sagen: »Wo ist denn ihr Gott?«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 115, 3, 'Unser Gott ist ja im Himmel: alles, was ihm gefällt, vollführt er.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 115, 4, 'Ihre Götzen sind Silber und Gold, Machwerk von Menschenhänden.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 115, 5, 'Sie haben einen Mund und können nicht reden, haben Augen und sehen nicht;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 115, 6, 'sie haben Ohren und können nicht hören, haben eine Nase und riechen nicht;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 115, 7, 'mit ihren Händen können sie nicht greifen, mit ihren Füßen nicht gehen; kein Laut dringt aus ihrer Kehle.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 115, 8, 'Ihnen gleich sind ihre Verfertiger, jeder, der auf sie vertraut.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 115, 9, 'Du, Israel, vertraue auf den HERRN! – Ihre Hilfe und ihr Schild ist er.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 115, 10, 'Ihr vom Hause Aarons, vertraut auf den HERRN! – Ihre Hilfe und ihr Schild ist er.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 115, 11, 'Ihr, die ihr fürchtet den HERRN, vertraut auf den HERRN! – Ihre Hilfe und ihr Schild ist er.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 115, 12, 'Der HERR hat unser gedacht: er wird segnen, segnen das Haus Israels, segnen das Haus Aarons;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 115, 13, 'er wird segnen, die den HERRN fürchten, die Kleinen samt den Großen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 115, 14, 'Der HERR wolle euch mehren, euch selbst und eure Kinder!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 115, 15, 'Gesegnet seid ihr vom HERRN, der Himmel und Erde geschaffen!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 115, 16, 'Der Himmel ist der Himmel des Allherrn, die Erde aber hat er den Menschen gegeben.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 115, 17, 'Nicht die Toten preisen den HERRN und keiner, der ins stille Land gefahren.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 115, 18, 'Doch wir, wir preisen den HERRN von nun an bis in Ewigkeit. Halleluja!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 116, 1, 'Ich liebe den HERRN, denn er hat erhört mein flehentlich Rufen;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 116, 2, 'ja, er hat sein Ohr mir zugeneigt: ich will zu ihm rufen mein Leben lang!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 116, 3, 'Umschlungen hatten mich des Todes Netze und die Ängste der Unterwelt mich befallen, in Drangsal und Kummer war ich geraten.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 116, 4, 'Da rief ich den Namen des HERRN an: »Ach, HERR, errette meine Seele!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 116, 5, 'Gnädig ist der HERR und gerecht, und unser Gott ist voll Erbarmens;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 116, 6, 'der HERR schützt den, der unbeirrt ihm traut: ich war schwach geworden, aber er half mir.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 116, 7, 'Kehre zurück, meine Seele, zu deiner Ruhe, denn der HERR hat Gutes an dir getan!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 116, 8, 'Ja, du hast mein Leben vom Tode errettet, meine Augen vom Weinen, meinen Fuß vom Anstoß;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 116, 9, 'ich werde noch wandeln vor dem HERRN in den Landen des Lebens.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 116, 10, 'Ich habe Glauben gehalten, wenn ich auch sagte: »Ich bin gar tief gebeugt«;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 116, 11, 'in meiner Verzagtheit hab’ ich gesagt: »Die Menschen sind Lügner allesamt.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 116, 12, 'Wie soll ich dem HERRN vergelten alles, was er mir Gutes getan?');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 116, 13, 'Den Becher des Heils will ich erheben und den Namen des HERRN anrufen;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 116, 14, 'meine Gelübde will ich bezahlen dem HERRN, ja angesichts seines ganzen Volkes.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 116, 15, 'Kostbar ist in den Augen des HERRN der Tod seiner Frommen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 116, 16, 'Ach, HERR, ich bin ja dein Knecht, ich bin dein Knecht, der Sohn deiner Magd; meine Bande hast du gelöst:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 116, 17, 'dir will ich Dankopfer bringen und den Namen des HERRN anrufen;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 116, 18, 'meine Gelübde will ich bezahlen dem HERRN, ja angesichts seines ganzen Volkes,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 116, 19, 'in den Vorhöfen am Hause des HERRN, in deiner Mitte, Jerusalem! Halleluja!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 117, 1, 'Lobet den HERRN, ihr Heiden alle! Preiset ihn, ihr Völker alle!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 117, 2, 'Denn machtvoll waltet über uns seine Gnade, und die Treue des HERRN währt ewiglich. Halleluja!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 118, 1, 'Danket dem HERRN, denn er ist freundlich, ja, ewiglich währt seine Gnade!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 118, 2, 'So bekenne denn Israel: »Ja, ewiglich währt seine Gnade!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 118, 3, 'So bekenne denn Aarons Haus: »Ja, ewiglich währt seine Gnade!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 118, 4, 'So mögen denn alle Gottesfürcht’gen bekennen: »Ja, ewiglich währt seine Gnade!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 118, 5, 'Aus meiner Bedrängnis rief ich zum HERRN: da hat der HERR mich erhört, mir weiten Raum geschafft.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 118, 6, 'Ist der HERR für mich, so fürchte ich nichts: was können Menschen mir tun?');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 118, 7, 'Tritt der HERR für mich zu meiner Hilfe ein, so werde ich siegreich jubeln über meine Feinde.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 118, 8, 'Besser ist’s auf den HERRN vertrauen als auf Menschen sich verlassen;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 118, 9, 'besser ist’s auf den HERRN vertrauen als auf Fürsten sich verlassen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 118, 10, 'Die Heidenvölker alle hatten mich umringt: im Namen des HERRN, so vertilgte ich sie;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 118, 11, 'sie hatten mich umringt, umzingelt: im Namen des HERRN, so vertilgte ich sie;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 118, 12, 'sie hatten mich umringt wie Bienenschwärme; schnell wie ein Dornenfeuer sind sie erloschen: im Namen des HERRN, so vertilgte ich sie.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 118, 13, 'Man hat mich hart gestoßen, damit ich fallen sollte, doch der HERR hat mir geholfen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 118, 14, 'Meine Stärke und mein Lobpreis ist der HERR, und er ist mein Retter geworden.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 118, 15, 'Jubel und Siegeslieder erschallen in den Zelten der Gerechten: »Die Hand des HERRN schafft mächtige Taten,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 118, 16, 'die Hand des HERRN erhöht, die Hand des HERRN schafft mächtige Taten!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 118, 17, 'Ich werde nicht sterben, nein, ich werde leben und die Taten des HERRN verkünden.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 118, 18, 'Der HERR hat mich hart gezüchtigt, doch dem Tode mich nicht preisgegeben.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 118, 19, 'Öffnet mir die Tore der Gerechtigkeit: ich will durch sie eingehn, dem HERRN zu danken. –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 118, 20, 'Dies ist das Tor des HERRN: Gerechte dürfen hier eingehn. –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 118, 21, 'Ich danke dir, daß du mich erhört hast und bist mir ein Retter geworden.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 118, 22, 'Der Stein, den die Bauleute verworfen haben, der ist zum Eckstein geworden;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 118, 23, 'vom HERRN ist dies geschehn, in unsern Augen ein Wunder!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 118, 24, 'Dies ist der Tag, den der HERR gemacht hat: laßt uns jubeln und fröhlich an ihm sein! –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 118, 25, 'Ach hilf doch, HERR, ach, HERR, laß wohl gelingen! –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 118, 26, 'Gesegnet sei, der da kommt im Namen des HERRN! Wir segnen euch vom Hause des HERRN aus.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 118, 27, 'Der HERR ist Gott, er hat uns Licht gegeben: schlinget den Reigen, mit Zweigen (geschmückt), bis an die Hörner des Altars!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 118, 28, 'Du bist mein Gott, ich will dir danken; mein Gott, ich will dich erheben!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 118, 29, 'Danket dem HERRN, denn er ist freundlich, ja, ewiglich währt seine Gnade.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 1, 'Wohl denen, deren Wandel unsträflich ist, die einhergehn im Gesetz des HERRN!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 2, 'Wohl denen, die seine Zeugnisse beobachten, die mit ganzem Herzen ihn suchen,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 3, 'die auch kein Unrecht verüben, sondern auf seinen Wegen gehen!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 4, 'Du selbst hast deine Befehle erlassen, daß man sie sorglich befolge.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 5, 'Ach möchte doch mein Wandel fest sein in der Befolgung deiner Satzungen!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 6, 'Dann werde ich nicht beschämt sein, wenn ich alle deine Gebote vor Augen habe.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 7, 'Ich will dir aufrichtigen Herzens danken, indem ich die Rechte deiner Gerechtigkeit lerne.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 8, 'Deine Satzungen will ich halten: verlaß mich nicht ganz und gar!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 9, 'Wie wird ein Jüngling seinen Wandel rein gestalten? Wenn er ihn führt nach deinem Wort.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 10, 'Mit ganzem Herzen suche ich dich: laß mich von deinen Geboten nicht abirren!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 11, 'In meinem Herzen wahre ich dein Wort, um mich nicht gegen dich zu verfehlen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 12, 'Gepriesen seist du, o HERR: lehre mich deine Satzungen!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 13, 'Mit meinen Lippen zähle ich her alle Rechte deines Mundes.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 14, 'An dem Wege deiner Zeugnisse habe ich Freude wie über irgendwelchen Reichtum.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 15, 'Über deine Befehle will ich sinnen und achten auf deine Pfade.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 16, 'An deinen Satzungen habe ich meine Lust, will deine Worte nicht vergessen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 17, 'Tu Gutes an deinem Knecht, auf daß ich leben bleibe, so will ich deine Worte befolgen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 18, 'Öffne mir die Augen, daß ich klar erkenne die Wunder in deinem Gesetz.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 19, 'Ich bin nur ein Gast auf Erden: verbirg deine Gebote nicht vor mir.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 20, 'Meine Seele verzehrt sich vor Sehnsucht nach deinen Rechten allezeit.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 21, 'Gedroht hast du den Stolzen; verflucht sind, die von deinen Geboten abweichen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 22, 'Wälze Schmach und Verachtung von mir ab, denn ich beobachte deine Zeugnisse.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 23, 'Mögen auch Fürsten sitzen und wider mich beraten: dein Knecht sinnt doch über deine Satzungen nach.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 24, 'Ja, deine Zeugnisse sind meine Freude, meine Ratgeber sind sie.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 25, 'Mein Mut ist in den Staub gesunken: belebe mich wieder nach deinem Wort.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 26, 'Ich habe dir meine Lage geschildert, da hast du mich erhört: lehre mich deine Satzungen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 27, 'Laß mich den Weg verstehn, den deine Befehle gebieten, so will ich sinnen über deine Wunder.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 28, 'Mein Herz zerfließt vor Kummer in Tränen; richte mich auf nach deinen Worten.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 29, 'Den Weg der Lüge halte fern von mir, doch begnade mich mit deinem Gesetz!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 30, 'Den Weg der Treue habe ich erwählt, deine Rechte unanstößig befunden.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 31, 'Ich halte fest an deinen Zeugnissen: HERR, laß mich nicht zuschanden werden!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 32, 'Den Weg deiner Gebote will ich laufen, denn du machst mir weit das Herz.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 33, 'Lehre mich, HERR, den Weg deiner Satzungen, so will ich ihn innehalten bis ans Ende.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 34, 'Verleihe mir Einsicht, damit ich deine Weisung beachte und sie mit ganzem Herzen befolge.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 35, 'Laß mich wandeln auf dem Pfade deiner Gebote, denn an diesem habe ich meine Freude.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 36, 'Neige mein Herz deinen Zeugnissen zu und nicht zur Gewinnsucht.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 37, 'Wende meine Augen ab, daß sie nicht nach Eitlem schauen; belebe mich auf deinen Wegen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 38, 'Erfülle an deinem Knechte deine Verheißung, die darauf abzielt, daß man dich fürchte.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 39, 'Wende ab meine Schmach, vor der mir graut; denn deine Rechte sind heilsam.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 40, 'Fürwahr, ich sehne mich nach deinen Befehlen: belebe mich durch deine Gerechtigkeit!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 41, 'Laß deine Gnadenerweise mir widerfahren, o HERR, deine Hilfe nach deinem Wort,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 42, 'daß ich dem, der mich schmäht, zu antworten weiß; denn ich verlasse mich auf dein Wort.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 43, 'Und entzieh meinem Munde nicht ganz das Wort der Wahrheit; denn ich harre auf deine Rechte.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 44, 'Und befolgen will ich dein Gesetz beständig, immer und ewiglich;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 45, 'so werde ich wandeln auf freier Bahn; denn ich habe mich stets um deine Befehle gekümmert;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 46, 'und ich will von deinen Zeugnissen reden vor Königen, ohne mich zu scheuen;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 47, 'denn ich habe meine Freude an deinen Geboten, die mir lieb sind,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 48, 'und hebe meine Hände auf zu deinen Geboten, [die mir lieb sind,] will über deine Satzungen sinnen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 49, 'Halte deinem Knecht getreulich dein Wort, auf das du mich hast hoffen lassen!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 50, 'Das ist mein Trost in meinem Elend, daß dein Wort mich neu belebt hat.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 51, 'Die Übermüt’gen verspotten mich maßlos, doch ich bin von deinem Gesetz nicht abgewichen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 52, 'Gedenke ich deiner Rechte aus der Vorzeit, so fühle ich mich, o HERR, getröstet.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 53, 'Heißer Zorn erfaßt mich wegen der Gottlosen, die dein Gesetz verlassen haben.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 54, 'Deine Satzungen sind mir zu Lobgesängen geworden im Hause meiner Pilgerschaft.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 55, 'In der Nacht sogar gedenke ich deines Namens, o HERR, und befolge dein Gesetz.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 56, 'Das ist mir zuteil geworden, daß ich deine Befehle befolgt habe.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 57, 'Meine Aufgabe ist, o HERR, ich bekenne es, deine Worte zu befolgen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 58, 'Von ganzem Herzen fleh’ ich dich an: »Sei mir gnädig nach deiner Verheißung!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 59, 'Ich habe über meine Wege nachgedacht und lenke (daher) meine Schritte zu deinen Zeugnissen zurück.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 60, 'Ich eile und säume nicht, deine Gebote zu befolgen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 61, 'Die Fallstricke der Gottlosen umringen mich; dennoch vergesse ich dein Gesetz nicht.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 62, 'In der Mitte der Nacht stehe ich auf, um dir zu danken für die Verordnungen deiner Gerechtigkeit.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 63, 'Befreundet bin ich mit allen, die dich fürchten, und mit denen, die deine Befehle befolgen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 64, 'Deiner Gnade, o HERR, ist die Erde voll: lehre mich deine Satzungen!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 65, 'Gutes hast du an deinem Knechte getan, o HERR, nach deiner Verheißung.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 66, 'Rechte Einsicht und Erkenntnis lehre mich, denn ich vertraue auf deine Gebote.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 67, 'Bevor ich gedemütigt wurde, ging ich irre; jetzt aber beobachte ich dein Wort.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 68, 'Du bist gütig und erweisest Gutes: lehre mich deine Satzungen!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 69, 'Lügen haben die Stolzen gegen mich erdichtet, ich aber befolge deine Befehle mit ganzem Herzen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 70, 'Unempfindlich wie von Fett ist ihr Herz, ich aber habe Freude an deinem Gesetz.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 71, 'Gut war’s für mich, daß ich gedemütigt wurde, damit ich deine Satzungen lernte.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 72, 'Die Weisung deines Mundes ist mir lieber als Tausende von Gold- und Silberstücken.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 73, 'Deine Hände haben mich geschaffen und gebildet: verleihe mir nun auch Einsicht, daß ich deine Gebote lerne!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 74, 'Die dich fürchten, werden mich sehen und sich freun; denn ich habe auf dein Wort geharrt.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 75, 'Ich weiß, o HERR, daß deine Gerichte gerecht sind und du mich in Treue gedemütigt hast.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 76, 'Laß doch deine Gnade mir Trost gewähren, wie du deinem Knechte verheißen hast!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 77, 'Laß mir dein Erbarmen widerfahren, daß ich auflebe, denn dein Gesetz ist meine Lust.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 78, 'Laß die Stolzen zuschanden werden, weil sie ohne Grund mich niederdrücken; ich aber sinne über deine Befehle.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 79, 'Laß mir sich zuwenden, die dich fürchten und die deine Zeugnisse anerkennen!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 80, 'Mein Herz halte treu an deinen Satzungen fest, auf daß ich nicht zuschanden werde.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 81, 'Meine Seele schmachtet nach deiner Hilfe: ich harre auf dein Wort.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 82, 'Meine Augen schmachten nach deiner Verheißung, indem ich frage: »Wann wirst du mich trösten?«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 83, 'Bin ich auch wie ein Schlauch im Rauch geworden, hab’ ich doch deine Satzungen nicht vergessen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 84, 'Wie viele sind noch der Lebenstage deines Knechts? Wann hältst du Gericht über meine Verfolger?');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 85, 'Übermütige haben mir Gruben gegraben, sie, die sich nicht nach deinem Gesetz verhalten.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 86, 'Alle deine Gebote sind Wahrheit; mit Lüge verfolgt man mich: so hilf mir!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 87, 'Fast hätten sie mich im Lande umgebracht; doch ich verlasse deine Befehle nicht.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 88, 'Nach deiner Gnade erhalte mich am Leben, so will ich das Zeugnis deines Mundes befolgen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 89, 'Auf ewige Zeit, o HERR, steht fest dein Wort im Himmel.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 90, 'Von Geschlecht zu Geschlecht währt deine Treue; du hast die Erde festgestellt, und sie steht;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 91, 'nach deinen Verordnungen stehn sie noch heute, denn alle Dinge sind dir dienstbar.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 92, 'Wäre dein Gesetz nicht meine Freude gewesen, so wär’ ich in meinem Elend vergangen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 93, 'Niemals will ich deine Befehle vergessen, denn durch sie hast du mich neu belebt.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 94, 'Dein bin ich: hilf mir! Denn ich beachte deine Verordnungen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 95, 'Gottlose lauern mir auf, um mich umzubringen, ich aber achte auf deine Zeugnisse.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 96, 'Von allem Vollkomm’nen habe ich eine Grenze gesehn; doch dein Gebot ist völlig unbeschränkt.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 97, 'Wie habe ich dein Gesetz so lieb! Den ganzen Tag ist es mein Sinnen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 98, 'Weiser, als meine Feinde sind, machen mich deine Gebote, denn mein sind sie für immer.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 99, 'Verständiger bin ich als alle meine Lehrer, denn deine Zeugnisse sind mein Sinnen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 100, 'Mehr Einsicht besitz’ ich als die Greise; denn ich beobachte deine Befehle.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 101, 'Von jedem bösen Pfade halte ich meinen Fuß fern, um dein Wort zu befolgen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 102, 'Von deinen Rechten weiche ich nicht ab, denn du hast mich belehrt.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 103, 'Wie süß sind deine Worte meinem Gaumen, süßer als Honig meinem Munde!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 104, 'Aus deinen Befehlen gewinne ich Einsicht; darum hasse ich jeglichen Lügenpfad.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 105, 'Dein Wort ist meines Fußes Leuchte und ein Licht auf meinem Wege.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 106, 'Ich habe geschworen und den Vorsatz gefaßt, den Verordnungen deiner Gerechtigkeit treu zu bleiben.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 107, 'Ich bin gar tief gebeugt: o HERR, belebe mich wieder nach deiner Verheißung!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 108, 'Laß, HERR, dir gefallen die willigen Opfer meines Mundes und lehre mich deine Rechte!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 109, 'Ich schwebe beständig in Todesgefahr, doch dein Gesetz vergesse ich nicht.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 110, 'Die Gottlosen haben mir Schlingen gelegt, aber von deinen Befehlen irre ich nicht ab.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 111, 'Deine Zeugnisse sind mein ewiger Erbbesitz, denn sie sind die Wonne meines Herzens.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 112, 'Ich neige mein Herz dazu, deine Satzungen zu erfüllen immerdar bis ans Ende.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 113, 'Die Doppelherzigen hasse ich, aber dein Gesetz ist mir lieb.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 114, 'Mein Schirm und Schild bist du; auf dein Wort harre ich.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 115, 'Weicht von mir, ihr Übeltäter! Ich will die Gebote meines Gottes halten.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 116, 'Stütze mich nach deiner Verheißung, daß ich lebe, und laß mich nicht in meiner Hoffnung getäuscht werden!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 117, 'Stärke mich, auf daß ich Heil erlange, und laß mich stets auf deine Satzungen achten!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 118, 'Du verwirfst alle, die von deinen Satzungen abirren; denn erfolglos ist ihre Täuschung.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 119, 'Wie Schlacken räumst du alle Gottlosen des Landes hinweg; darum liebe ich deine Zeugnisse.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 120, 'Aus Furcht vor dir schaudert mein Leib, und mir ist bange vor deinen Gerichten.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 121, 'Ich habe Recht und Gerechtigkeit geübt: gib mich nicht meinen Bedrückern preis!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 122, 'Tritt für deinen Knecht zu seinem Heile ein, laß die Stolzen mir nicht Gewalt antun!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 123, 'Meine Augen schmachten nach deiner Rettung und nach der Bestätigung deiner Gerechtigkeit.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 124, 'Verfahre mit deinem Knecht nach deiner Gnade und lehre mich deine Satzungen!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 125, 'Dein Knecht bin ich, verleihe mir Einsicht, damit ich deine Zeugnisse verstehen lerne.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 126, 'Zeit ist’s für den HERRN, zu handeln: sie haben ja dein Gesetz gebrochen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 127, 'Darum liebe ich deine Gebote mehr als Gold und als Feingold.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 128, 'Darum schätze ich alle deine Befehle als richtig; jeder Lügenpfad ist mir verhaßt.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 129, 'Wunderwerke sind deine Zeugnisse; darum hält mein Herz an ihnen fest.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 130, 'Die Erschließung deiner Worte erleuchtet, verleiht den Einfältigen Einsicht.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 131, 'Ich tue meinen Mund weit auf und lechze, denn mich verlangt nach deinen Geboten.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 132, 'Wende dich zu mir und sei mir gnädig, wie es recht ist bei denen, die deinen Namen lieben!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 133, 'Laß meine Schritte fest sein durch dein Wort und laß nichts Trügerisches über mich herrschen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 134, 'Erlöse mich von der Bedrückung der Menschen, so will ich deine Befehle befolgen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 135, 'Laß dein Angesicht leuchten gegen deinen Knecht und lehre mich deine Satzungen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 136, 'Tränenströme rinnen aus meinen Augen, weil viele dein Gesetz nicht befolgen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 137, 'Gerecht bist du, o HERR, und richtig sind deine Rechte.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 138, 'In Gerechtigkeit hast du deine Zeugnisse verordnet und in unerschütterlicher Treue.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 139, 'Mich verzehrt mein Eifer, weil meine Gegner deine Worte vergessen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 140, 'Dein Wort ist wohlgeläutert, und dein Knecht hat es lieb.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 141, 'Gering bin ich und verachtet, doch deine Befehle vergesse ich nicht.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 142, 'Deine Gerechtigkeit ist ewige Gerechtigkeit, und dein Gesetz ist Wahrheit.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 143, 'Wenn Leiden und Not mich getroffen haben, sind deine Gebote dennoch meine Freude.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 144, 'Deine Zeugnisse bleiben immerdar gerecht: verleihe mir Verständnis, so werde ich leben.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 145, 'Ich rufe von ganzem Herzen: »Erhöre mich, HERR!« Deine Satzungen will ich beobachten.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 146, 'Ich rufe zu dir: »Hilf mir! So will ich deine Zeugnisse beobachten.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 147, 'Früh bin ich auf vor Tagesanbruch und flehe laut; auf dein Wort harre ich.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 148, 'Meine Augen wachen die ganze Nacht hindurch, um über dein Wort nachzusinnen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 149, 'Höre meine Stimme nach deiner Gnade! O HERR, nach deinen Rechten laß mich aufleben!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 150, 'Mir haben sich Leute genaht, die der Arglist frönen: von deinem Gesetz sind sie fern;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 151, 'doch du bist mir nahe, o HERR, und alle deine Gebote sind Wahrheit.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 152, 'Längst weiß ich aus deinen Zeugnissen, daß du sie für ewig festgestellt hast.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 153, 'Sieh mein Elend an und errette mich! Denn dein Gesetz vergesse ich nicht.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 154, 'Führe meine Sache und erlöse mich, schenke mir neues Leben nach deiner Verheißung!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 155, 'Den Gottlosen bleibt die Hilfe fern, denn sie kümmern sich nicht um deine Satzungen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 156, 'Deine Barmherzigkeit ist groß, o HERR: nach deinen Rechten belebe mich wieder!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 157, 'Groß ist meiner Verfolger und Gegner Zahl, doch von deinen Zeugnissen geh’ ich nicht ab.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 158, 'Wenn ich Treulose sehe, so fühle ich Abscheu, weil sie dein Wort nicht befolgen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 159, 'Sieh her, ich liebe deine Befehle: HERR, schenke mir neues Leben nach deiner Gnade!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 160, 'Der ganze Inhalt deines Wortes ist Wahrheit, und ewig gilt jede Verordnung deiner Gerechtigkeit.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 161, 'Fürsten haben mich ohne Ursach’ verfolgt; doch nur vor deinen Worten erbebt mein Herz.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 162, 'Ich freue mich über dein Wort wie einer, der große Beute gewinnt.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 163, 'Lügen hasse und verabscheue ich, aber dein Gesetz ist mir lieb.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 164, 'Siebenmal täglich preise ich dich um der Verordnungen deiner Gerechtigkeit willen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 165, 'Frieden in Fülle erlangen die Freunde deines Gesetzes, denn es gibt für sie kein Straucheln.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 166, 'Ich hoffe auf deine Rettung, o HERR, denn ich habe deine Gebote gehalten.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 167, 'Mein Herz befolgt deine Zeugnisse, und ich habe sie aufrichtig lieb.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 168, 'Ich befolge deine Befehle und Zeugnisse; denn alle meine Wege sind dir bekannt.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 169, 'Laß mein lautes Flehen zu dir dringen, o HERR; verleih mir Verständnis für dein Wort!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 170, 'Laß mein Beten vor dich kommen: errette mich nach deiner Verheißung!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 171, 'Meine Lippen sollen Lobpreis sprudeln lassen, weil du mich deine Satzungen lehrst.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 172, 'Meine Zunge soll von deinem Worte singen; denn alle deine Gebote sind gerecht.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 173, 'Laß deine Hand bereit sein, mir zu helfen, denn deine Befehle hab’ ich (zu Führern) erwählt.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 174, 'Ich sehne mich nach deiner Hilfe, o HERR, und dein Gesetz ist meine Freude.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 175, 'Laß meine Seele leben, daß sie dich preise, und deine Rechte mögen mir helfen!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 176, 'Geh ich irre wie ein verlorenes Schaf, so suche deinen Knecht! Denn deine Gebote habe ich nicht vergessen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 120, 1, 'Ein Wallfahrtslied. Ich rief zum HERRN in meiner Not: da erhörte er mich.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 120, 2, 'O HERR, errette mich von der Lügenlippe, von der trügerischen Zunge!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 120, 3, 'Was wird Er dir jetzt und in Zukunft bescheren, du trügerische Zunge?');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 120, 4, 'Geschärfte Kriegerpfeile samt Kohlen vom Ginsterstrauch!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 120, 5, 'Wehe mir, daß ich als Fremdling in Mesech weile, daß ich wohne bei den Zelten von Kedar!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 120, 6, 'Lange genug schon weile ich hier bei Leuten, die den Frieden hassen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 120, 7, 'Ich bin ganz friedlich gestimmt, doch was ich auch rede: sie gehen auf Krieg aus.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 121, 1, 'Ein Lied für Wallfahrten. Ich hebe meine Augen auf zu den Bergen: von wo wird Hilfe mir kommen?');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 121, 2, 'Meine Hilfe kommt vom HERRN, der Himmel und Erde geschaffen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 121, 3, 'Er wird deinen Fuß nicht wanken lassen; nicht schlummert dein Hüter.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 121, 4, 'Nein, nicht schlummert und nicht schläft der Hüter Israels.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 121, 5, 'Der HERR ist dein Hüter, der HERR dein Schatten über deiner rechten Hand,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 121, 6, 'daß dich bei Tage die Sonne nicht sticht, noch der Mond in der Nacht.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 121, 7, 'Der HERR behütet dich vor allem Übel, er behütet deine Seele;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 121, 8, 'der HERR behütet deinen Ausgang und Eingang von nun an bis in Ewigkeit.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 122, 1, 'Ein Wallfahrtslied Davids. Ich freute mich, als man mir sagte: »Wir wollen pilgern zum Hause des HERRN!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 122, 2, 'So stehn denn nunmehr unsre Füße in deinen Toren, Jerusalem!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 122, 3, 'Jerusalem, du wiedererbaute als eine Stadt, die fest in sich geschlossen,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 122, 4, 'wohin die Stämme hinaufziehn, die Stämme des HERRN, nach der für Israel gültigen Weisung, dort den Namen des HERRN zu preisen;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 122, 5, 'denn dort waren einst aufgestellt die Stühle zum Gericht, die Stühle des Hauses Davids.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 122, 6, 'Bringet Jerusalem dar den Friedensgruß: »Heil denen, die dich lieben!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 122, 7, 'Friede herrsche vor deinen Mauern, sichere Ruhe in deinen Palästen!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 122, 8, 'Um meiner Brüder und Freunde willen will ich dir Frieden wünschen;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 122, 9, 'um des Hauses des HERRN, unsres Gottes, willen will ich Segen für dich erbitten.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 123, 1, 'Ein Wallfahrtslied. Zu dir erhebe ich meine Augen, der du thronst im Himmel.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 123, 2, 'Siehe, wie die Augen der Knechte auf die Hand ihrer Herren, wie die Augen der Magd auf ihrer Gebieterin Hand: so blicken unsre Augen hin auf den HERRN, unsern Gott, bis er sich unser erbarmt.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 123, 3, 'Erbarme dich, HERR, erbarme dich unser! Denn gründlich sind wir satt der Verachtung;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 123, 4, 'satt, ja übersatt ist uns die Seele des Hohns der Leichtfertigen, der Verachtung der Stolzen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 124, 1, 'Ein Wallfahrtslied von David. »Wäre der HERR nicht für uns gewesen« so bekenne Israel! –,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 124, 2, '»wäre der HERR nicht für uns gewesen, als Menschen sich gegen uns erhoben:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 124, 3, 'dann hätten sie uns lebendig verschlungen, als ihr Zorn gegen uns entbrannt war;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 124, 4, 'dann hätten die Wasser uns überflutet, ein Wildbach hätte sich über uns ergossen;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 124, 5, 'dann wären über uns hingegangen die wildwogenden Fluten.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 124, 6, 'Gepriesen sei der HERR, der uns nicht ihren Zähnen zum Raub hat preisgegeben!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 124, 7, 'Unsre Seele ist entschlüpft wie ein Vogel dem Netz der Vogelsteller: das Netz ist zerrissen, und wir sind frei geworden.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 124, 8, 'Unsre Hilfe steht im Namen des HERRN, der Himmel und Erde geschaffen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 125, 1, 'Ein Wallfahrtslied. Die auf den HERRN vertrauen, die gleichen dem Berge Zion, der nicht wankt, der in Ewigkeit feststeht.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 125, 2, 'Wie Berge Jerusalem rings umgeben, so umhegt der HERR sein Volk von nun an bis in Ewigkeit.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 125, 3, 'Denn der Gottlosen Zepter wird nicht lasten bleiben auf dem Erbteil der Gerechten, damit nicht auch die Gerechten ihre Hände ausstrecken zum Frevel.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 125, 4, 'Erweise deine Güte, HERR, den Guten und denen, die redlichen Herzens sind!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 125, 5, 'Doch die auf ihre krummen Wege abbiegen, die lasse der HERR hinfahren mitsamt den Übeltätern! Heil über Israel!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 126, 1, 'Ein Wallfahrtslied. Als der HERR einst Zions Mißgeschick wandte, da war’s uns, als träumten wir.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 126, 2, 'Damals war unser Mund voll Lachens und unsre Zunge voll Jubels; damals sagte man unter den Heiden: »Der HERR hat Großes an ihnen getan!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 126, 3, 'Ja, Großes hatte der HERR an uns getan: wie waren wir fröhlich!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 126, 4, 'Wende, o HERR, unser Mißgeschick gleich den Bächen im Mittagsland!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 126, 5, 'Die mit Tränen säen, werden mit Jubel ernten.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 126, 6, 'Wohl schreitet man weinend dahin, wenn man trägt den Samen zur Aussaat; doch jubelnd kehrt man heim, mit Garben beladen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 127, 1, 'Ein Wallfahrtslied Salomos. Wenn der HERR das Haus nicht baut, so arbeiten umsonst, die daran bauen; wenn der HERR nicht die Stadt behütet, so wacht der Wächter umsonst.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 127, 2, 'Vergebens ist’s für euch, daß früh ihr aufsteht und spät noch sitzt bei der Arbeit, um das Brot der Mühsal zu essen; ebenso (reichlich) gibt er’s seinen Freunden im Schlaf. –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 127, 3, 'Ja, Söhne sind ein Geschenk des HERRN, und Kindersegen ist eine Belohnung.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 127, 4, 'Wie Pfeile in der Hand eines Kriegers, so sind die Söhne der Jugendkraft:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 127, 5, 'wohl dem Manne, der mit ihnen seinen Köcher gefüllt hat! Die werden nicht zuschanden, wenn sie verhandeln mit Widersachern im Stadttor.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 128, 1, 'Ein Wallfahrtslied. Wohl jedem, der den HERRN fürchtet und auf seinen Wegen wandelt!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 128, 2, 'Deiner Hände Erwerb – du darfst ihn genießen: wohl dir, du hast es gut!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 128, 3, 'Dein Weib gleicht einem fruchtbaren Weinstock im Innern deines Hauses; deine Kinder sind wie Ölbaumschosse rings um deinen Tisch.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 128, 4, 'Ja wahrlich, so wird der Mann gesegnet, der da fürchtet den HERRN.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 128, 5, 'Dich segne der HERR von Zion her, daß du schauest deine Lust an Jerusalems Glück dein Leben lang');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 128, 6, 'und sehest Kinder von deinen Kindern! Heil über Israel!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 129, 1, 'Ein Wallfahrtslied. »Sie haben mich hart bedrängt von meiner Jugend an« so bekenne Israel –,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 129, 2, '»sie haben mich hart bedrängt von meiner Jugend an, aber doch mich nicht überwältigt.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 129, 3, 'Auf meinem Rücken haben die Pflüger gepflügt und lange Furchen gezogen;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 129, 4, 'doch der HERR ist gerecht: er hat zerhauen der Gottlosen Stricke.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 129, 5, 'Zuschanden müssen werden und rückwärts weichen alle, die Zion hassen!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 129, 6, 'Sie müssen gleichen dem Gras auf den Dächern, das dürr schon ist, bevor es in Halme schießt,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 129, 7, 'mit dem der Schnitter seine Hand nicht füllt, noch der Garbenbinder seinen Gewandbausch,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 129, 8, 'und bei dem, wer des Weges vorübergeht, nicht ruft: »Gottes Segen sei über euch! Wir segnen euch im Namen des HERRN!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 130, 1, 'Ein Wallfahrtslied. Aus der Tiefe rufe ich, HERR, zu dir:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 130, 2, '»Allherr, höre auf meine Stimme, laß deine Ohren merken auf mein lautes Flehen!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 130, 3, 'Wenn du, HERR, Sünden behalten willst, o Allherr, wer kann bestehn!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 130, 4, 'Doch bei dir ist die Vergebung, auf daß man dich fürchte.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 130, 5, 'Ich harre des HERRN, meine Seele harrt, und ich warte auf sein Wort;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 130, 6, 'meine Seele harrt auf den Allherrn sehnsuchtsvoller als Wächter auf den Morgen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 130, 7, 'Sehnsuchtsvoller als Wächter auf den Morgen harre, Israel, auf den HERRN! Denn beim HERRN ist die Gnade und Erlösung bei ihm in Fülle,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 130, 8, 'und er wird Israel erlösen von allen seinen Sünden.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 131, 1, 'Ein Wallfahrtslied Davids. HERR, mein Herz ist nicht hochfahrend, und meine Augen erheben sich nicht stolz; ich gehe nicht mit Dingen um, die vermessen sind und mir zu hoch.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 131, 2, 'Nein, ich habe mein Herz beruhigt und gestillt; wie ein entwöhntes Kind an der Mutter Brust, so ruht entwöhnt mein Herz in mir. –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 131, 3, 'Israel, harre des HERRN von nun an bis in Ewigkeit.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 132, 1, 'Ein Wallfahrtslied. Gedenke, HERR, dem David alle seine Mühsal,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 132, 2, 'ihm, der dem HERRN einst zuschwor und gelobte Jakobs mächtigem Gott:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 132, 3, '»Wahrlich, ich will mein Wohnzelt nicht betreten, nicht mein Ruhelager besteigen;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 132, 4, 'ich will meinen Augen den Schlaf nicht gönnen, nicht Schlummer meinen Augenlidern,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 132, 5, 'bis eine Stätte dem HERRN ich gefunden, eine Wohnung für Jakobs mächtigen Gott!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 132, 6, 'Ja, wir haben von ihr gehört in Ephrath, sie gefunden im Gefilde von Jaar:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 132, 7, '»Laßt uns in seine Wohnung treten, uns niederwerfen vor dem Schemel seiner Füße!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 132, 8, 'Brich auf, o HERR, zu deiner Ruhstatt, du und die Lade (das Sinnbild) deiner Macht!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 132, 9, 'Laß deine Priester sich kleiden in Gerechtigkeit, und deine Frommen mögen jubeln!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 132, 10, 'Um deines Knechtes David willen weise das Antlitz deines Gesalbten nicht ab!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 132, 11, 'Geschworen hat der HERR dem David einen Eid, einen wahren Eid, von dem er nicht abgeht: »Von deinen leiblichen Sprossen will einen ich setzen auf deinen Thron.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 132, 12, 'Wenn deine Söhne meinen Bund beachten und meine Zeugnisse, die ich sie lehren werde, so sollen auch ihre Söhne für und für sitzen auf deinem Thron.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 132, 13, 'Denn der HERR hat Zion erwählt, hat es zu seiner Wohnung begehrt:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 132, 14, '»Dies ist meine Ruhstatt für immer, hier will ich wohnen, weil ich’s so begehrt.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 132, 15, 'Zions Nahrung will ich reichlich segnen, seine Armen sättigen mit Brot;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 132, 16, 'seine Priester werde in Heil ich kleiden, seine Frommen sollen laut frohlocken.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 132, 17, 'Dort will ich Davids Macht erblühen lassen; eine Leuchte hab’ ich meinem Gesalbten bereitet.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 132, 18, 'Seine Feinde will ich kleiden in Schmach, doch ihm soll auf dem Haupt die Krone glänzen.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 133, 1, 'Ein Wallfahrtslied Davids. Seht, wie schön und wie lieblich ist’s, wenn Brüder auch (friedlich) beisammen wohnen!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 133, 2, 'Das gleicht dem köstlichen Öl auf dem Haupt, das herabtroff in den Bart, in Aarons Bart, der niederwallte auf den Saum seiner Gewandung.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 133, 3, 'Es gleicht dem Hermontau, der niederfällt auf die Berge Zions; denn dorthin hat der HERR den Segen entboten, Leben bis in Ewigkeit.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 134, 1, 'Ein Wallfahrtslied. Wohlan, preiset den HERRN, alle ihr Diener des HERRN, die ihr steht in den Nächten im Hause des HERRN!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 134, 2, 'Erhebt eure Hände zum Heiligtum hin und preiset den HERRN!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 134, 3, 'Dich segne der HERR von Zion her, der Schöpfer von Himmel und Erde!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 135, 1, 'Halleluja! Preiset den Namen des HERRN, preist ihn, ihr Diener des HERRN,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 135, 2, 'die ihr stehet im Hause des HERRN, in den Höfen am Haus unsers Gottes!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 135, 3, 'Preiset den HERRN, denn gütig ist der HERR; lobsingt seinem Namen, denn lieblich ist er!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 135, 4, 'Denn Jakob hat der HERR sich erwählt und Israel sich zum Eigentum erkoren.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 135, 5, 'Ja, ich weiß es: groß ist der HERR, und unser Gott steht über allen Göttern;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 135, 6, 'alles, was dem HERRN gefällt, das führt er aus im Himmel und auf Erden, in den Meeren und allen Tiefen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 135, 7, 'Er ist’s, der Wolken heraufführt vom Ende der Erde, der Blitze bei Gewitterregen schafft, der den Wind aus seinen Speichern herausläßt.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 135, 8, 'Er war’s, der Ägyptens Erstgeburten schlug unter Menschen wie beim Vieh;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 135, 9, 'der Zeichen und Wunder sandte in deine Mitte, Ägypten, gegen den Pharao und all seine Knechte.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 135, 10, 'Er war’s, der viele Völker schlug und mächtige Könige tötete:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 135, 11, 'Sihon, den König der Amoriter, und Og, den König von Basan, und alle Königreiche Kanaans,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 135, 12, 'und ihr Land als Erbbesitz hingab, als Erbe seinem Volke Israel.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 135, 13, 'O HERR, dein Name währt ewig, dein Gedächtnis, o HERR, von Geschlecht zu Geschlecht');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 135, 14, 'denn der HERR schafft Recht seinem Volk und erbarmt sich über seine Knechte.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 135, 15, 'Die Götzen der Heiden sind Silber und Gold, das Machwerk von Menschenhänden;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 135, 16, 'sie haben einen Mund und können nicht reden, haben Augen und sehen nicht;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 135, 17, 'sie haben Ohren und können nicht hören, auch ist kein Odem in ihrem Munde.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 135, 18, 'Ihnen gleich sind ihre Verfertiger, jeder, der auf sie vertraut.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 135, 19, 'Ihr vom Hause Israel, preiset den HERRN! Ihr vom Hause Aaron, preiset den HERRN!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 135, 20, 'Ihr vom Hause Levi, preiset den HERRN! Ihr, die ihr fürchtet den HERRN, preiset den HERRN!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 135, 21, 'Gepriesen sei der HERR von Zion aus, er, der da wohnt in Jerusalem! Halleluja!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 136, 1, 'Danket dem HERRN, denn er ist freundlich, ja, ewiglich währt seine Gnade!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 136, 2, 'Danket dem Gott der Götter – ja, ewiglich währt seine Gnade!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 136, 3, 'Danket dem Herrn der Herren – ja, ewiglich währt seine Gnade!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 136, 4, 'Ihm, der große Wunder tut, er allein: – ja, ewiglich währt seine Gnade!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 136, 5, 'der den Himmel mit Weisheit geschaffen: – ja, ewiglich währt seine Gnade!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 136, 6, 'der die Erde über den Wassern ausgebreitet: – ja, ewiglich währt seine Gnade!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 136, 7, 'der die großen Lichter geschaffen: – ja, ewiglich währt seine Gnade!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 136, 8, 'die Sonne zur Herrschaft am Tage: – ja, ewiglich währt seine Gnade!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 136, 9, 'den Mond und die Sterne zur Herrschaft bei Nacht: – ja, ewiglich währt seine Gnade!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 136, 10, 'Ihm, der Ägypten schlug an seinen Erstgeburten: – ja, ewiglich währt seine Gnade!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 136, 11, 'und Israel aus ihrer Mitte führte: – ja, ewiglich währt seine Gnade!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 136, 12, 'mit starker Hand und hocherhobnem Arm: – ja, ewiglich währt seine Gnade!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 136, 13, 'der das Schilfmeer in zwei Teile zerschnitt: – ja, ewiglich währt seine Gnade!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 136, 14, 'und Israel mitten hindurchziehen ließ: – ja, ewiglich währt seine Gnade!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 136, 15, 'und den Pharao und sein Heer ins Schilfmeer stürzte: – ja, ewiglich währt seine Gnade!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 136, 16, 'Ihm, der sein Volk durch die Wüste führte: – ja, ewiglich währt seine Gnade!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 136, 17, 'der große Könige schlug: – ja, ewiglich währt seine Gnade!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 136, 18, 'und mächtige Könige tötete: – ja, ewiglich währt seine Gnade!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 136, 19, 'Sihon, den König der Amoriter: – ja, ewiglich währt seine Gnade!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 136, 20, 'und Og, den König von Basan: – ja, ewiglich währt seine Gnade!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 136, 21, 'und ihr Land als Erbbesitz hingab: – ja, ewiglich währt seine Gnade!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 136, 22, 'als Erbbesitz seinem Knechte Israel: – ja, ewiglich währt seine Gnade!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 136, 23, 'ihm, der in unsrer Erniedrigung unser gedachte: – ja, ewiglich währt seine Gnade!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 136, 24, 'und uns von unsern Drängern befreite: – ja, ewiglich währt seine Gnade!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 136, 25, 'der Nahrung allen Geschöpfen gibt: – ja, ewiglich währt seine Gnade!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 136, 26, 'Danket dem Gott des Himmels: ja, ewiglich währt seine Gnade!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 137, 1, 'An Babels Strömen, da saßen wir und weinten, wenn Zions wir gedachten;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 137, 2, 'an die Weiden, die dort stehen, hängten wir unsre Harfen;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 137, 3, 'denn Lieder verlangten von uns dort unsre Zwingherrn, und unsre Peiniger hießen uns fröhlich sein: »Singt uns eins von euren Zionsliedern!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 137, 4, 'Wie sollten wir singen die Lieder des HERRN auf fremdem Boden?');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 137, 5, 'Vergesse ich dich, Jerusalem, so verdorre mir die rechte Hand!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 137, 6, 'Die Zunge bleibe mir am Gaumen kleben, wenn ich deiner nicht eingedenk bleibe, wenn ich Jerusalem nicht stelle über alles, was mir Freude macht!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 137, 7, 'Gedenke, HERR, den Söhnen Edoms den Unglückstag Jerusalems, wie sie riefen: »Reißt nieder, reißt nieder bis auf den Grund in ihm!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 137, 8, 'Bewohnerschaft Babels, Verwüsterin! Heil dem, der dir vergilt dasselbe, was du an uns verübt!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 137, 9, 'Heil dem, der deine Kindlein packt und am Felsen sie zerschmettert!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 138, 1, 'Von David. Danken will ich dir (HERR) von ganzem Herzen, vor den Göttern will ich dir lobsingen;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 138, 2, 'vor deinem heiligen Tempel will ich anbeten und deinen Namen preisen ob deiner Gnade und Treue; denn über deinen ganzen Namen hinaus hast dein Wort du groß gemacht.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 138, 3, 'Als ich rief zu dir, da hast du mich erhört, hast mir Mut verliehn: in mein Herz kam Kraft.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 138, 4, 'Danken werden dir, HERR, alle Könige der Erde, wenn sie hören die Worte deines Mundes,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 138, 5, 'und werden singen vom Walten des HERRN, denn groß ist die Herrlichkeit des HERRN.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 138, 6, 'Denn der HERR ist erhaben und sieht doch den Niedrigen, den Stolzen aber erkennt er schon von ferne.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 138, 7, 'Wenn ich auch mitten in Drangsal wandle, erhältst du mir dennoch das Leben; du streckst deine Hand aus gegen die Wut meiner Feinde, und deine Rechte hilft mir.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 138, 8, 'Der HERR wird’s mir zum Heil vollführen; o HERR, deine Gnade walte für immer: laß die Werke deiner Hände nicht fahren!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 139, 1, 'Dem Musikmeister, von David ein Psalm. HERR, du erforschest mich und kennst mich;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 139, 2, 'du weißt es, ob ich sitze oder aufstehe, du verstehst, was ich denke, von ferne;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 139, 3, 'ob ich wandre oder ruhe, du prüfst es und bist mit all meinen Wegen vertraut;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 139, 4, 'denn ehe ein Wort auf meiner Zunge liegt, kennst du, o HERR, es schon genau.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 139, 5, 'Du hältst mich von hinten und von vorne umschlossen und hast deine Hand auf mich gelegt.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 139, 6, 'Zu wunderbar ist solches Wissen für mich, zu hoch: ich vermag’s nicht zu begreifen!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 139, 7, 'Wohin soll ich gehn vor deinem Geist und wohin fliehn vor deinem Angesicht?');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 139, 8, 'Führe ich auf zum Himmel, so wärst du da, und lagert’ ich mich in der Unterwelt, so wärst du dort;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 139, 9, 'nähme ich Schwingen des Morgenrots zum Flug und ließe mich nieder am äußersten Westmeer,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 139, 10, 'so würde auch dort deine Hand mich führen und deine Rechte mich fassen;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 139, 11, 'und spräch’ ich: »Lauter Finsternis soll mich umhüllen und Nacht sei das Licht um mich her!« –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 139, 12, 'auch die Finsternis würde für dich nicht finster sein, vielmehr die Nacht dir leuchten wie der Tag: Finsternis wäre für dich wie das Licht.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 139, 13, 'Denn du bist’s, der meine Nieren gebildet, mich gewoben im Schoß meiner Mutter.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 139, 14, 'Ich danke dir, daß ich so überaus wunderbar bereitet bin: wunderbar sind deine Werke, und meine Seele erkennt das wohl.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 139, 15, 'Meine Wesensgestaltung war dir nicht verborgen, als im Dunkeln ich gebildet ward, kunstvoll gewirkt in den Tiefen der Erde.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 139, 16, 'Deine Augen sahen mich schon als formlosen Keim, und in deinem Buch standen eingeschrieben alle Tage, die vorbedacht waren, als noch keiner von ihnen da war.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 139, 17, 'Für mich nun – wie kostbar sind deine Gedanken, o Gott, wie gewaltig sind ihre Summen!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 139, 18, 'Wollt’ ich sie zählen: ihrer sind mehr als des Sandes; wenn ich erwache, bin ich noch immer bei dir.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 139, 19, 'Möchtest du doch die Frevler töten, o Gott! Und ihr Männer der Blutschuld, weichet von mir!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 139, 20, 'Sie, die von dir mit Arglist reden, mit Falschheit reden als deine Widersacher.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 139, 21, 'Sollt’ ich nicht hassen, die dich, HERR, hassen, nicht verabscheun, die sich erheben gegen dich?');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 139, 22, 'Ja, ich hasse sie mit tödlichem Haß: als Feinde gelten sie mir.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 139, 23, 'Erforsche mich, Gott, und erkenne mein Herz, prüfe mich und erkenne meine Gedanken!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 139, 24, 'Und sieh, ob ich wandle auf trüglichem Wege, und leite mich auf dem ewigen Wege!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 140, 1, 'Dem Musikmeister, ein Psalm von David.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 140, 2, 'Rette mich, HERR, von den bösen Menschen! Vor den Freunden der Gewalttat schütze mich,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 140, 3, 'die auf Böses im Herzen sinnen und allezeit Streit erregen!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 140, 4, 'Sie spitzen ihre Zungen der Schlange gleich, Otterngift ist hinter ihren Lippen. SELA.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 140, 5, 'Behüte mich, HERR, vor den Händen der Frevler! Vor den Freunden der Gewalttat schütze mich, die darauf sinnen, zu Fall mich zu bringen!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 140, 6, 'Die Frechen legen mir heimlich Schlingen und Fallstricke, spannen Netze aus zur Seite des Wegs und stellen mir Fallen. SELA.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 140, 7, 'Ich sage zum HERRN: »Du bist mein Gott, vernimm, o HERR, mein lautes Flehen!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 140, 8, 'O HERR, mein Gott, meine starke Hilfe, du hast mein Haupt beschirmt am Tage des Kampfes:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 140, 9, 'gewähre nicht, HERR, die Gelüste der Frevler, laß ihr böses Trachten nicht gelingen! SELA.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 140, 10, 'Erheben sie das Haupt rings um mich her, so falle das Unheil ihrer Lippen auf sie selbst!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 140, 11, 'Er lasse glühende Kohlen auf sie regnen, ins Feuer stürze er sie, in Wasserfluten, daß sie nicht aufstehn können!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 140, 12, 'Der Verleumder wird keinen Halt im Lande gewinnen; der Mann der Gewalttat jage das Unglück Stoß auf Stoß!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 140, 13, 'Ich weiß, der HERR wird führen des Elenden Sache, den Rechtsstreit der Armen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 140, 14, 'Ja, die Gerechten werden deinen Namen preisen, die Redlichen bleiben wohnen vor deinem Angesicht.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 141, 1, 'Ein Psalm Davids. HERR, ich rufe dich, eile mir zu Hilfe! Vernimm meine Stimme, wenn ich zu dir rufe!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 141, 2, 'Laß mein Gebet dir als Räucherwerk gelten, das Aufheben meiner Hände als Abendopfer!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 141, 3, 'Stelle, o HERR, eine Wache vor meinen Mund, behüte das Tor meiner Lippen!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 141, 4, 'Laß mein Herz sich nicht neigen zu bösem Tun, daß ich gottlose Taten verübe im Verein mit Männern, die Übeltäter sind: ich mag nicht essen von ihren Leckerbissen!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 141, 5, 'Schlägt mich ein Gerechter: das ist Liebe, und weist er mich zurecht: das ist Salbe fürs Haupt; nicht soll mein Haupt dagegen sich sträuben; denn noch ist’s der Fall, daß für ihre Bosheit mein Gebet erfolgt.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 141, 6, 'Sind ihre Richter eine Felswand hinabgestürzt worden, so wird man hören, daß meine Worte lieblich sind.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 141, 7, 'Wie einer das Erdreich furcht und aufreißt, so sind unsere Gebeine hingestreut für den Rachen der Unterwelt.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 141, 8, 'Denn auf dich, o Allherr, sind meine Augen gerichtet, bei dir such’ ich Zuflucht: gib mein Leben nicht hin in den Tod!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 141, 9, 'Behüte mich vor der Schlinge, die sie mir gelegt, und vor den Fallstricken der Übeltäter!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 141, 10, 'Laß die Frevler fallen in ihre eigenen Netze, während ich zugleich daran vorübergehe!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 142, 1, 'Ein Lehrgedicht Davids, als er sich in der Höhle befand, ein Gebet.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 142, 2, 'Laut schrei’ ich zum HERRN, laut fleh’ ich zum HERRN,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 142, 3, 'ich schütte meine Klage vor ihm aus, tue kund vor ihm meine Not.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 142, 4, 'Wenn mein Geist in mir verschmachtet, du kennst doch meinen Lebenspfad. Auf dem Wege, den ich wandeln will, hat man mir heimlich ein Fangnetz ausgespannt.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 142, 5, 'Blick’ ich nach rechts und halte Umschau: ach, da ist keiner, der mich versteht! Verschlossen ist mir jede Zuflucht: niemand fragt nach mir!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 142, 6, 'Ich schreie, HERR, zu dir, ich sage: »Du bist meine Zuflucht, mein Anteil im Lande der Lebenden!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 142, 7, 'Ach, merk’ auf mein Flehn, denn ich bin gar schwach geworden! Rette mich vor meinen Verfolgern, denn sie sind mir zu stark!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 142, 8, 'Führe mich aus der Umkreisung hinaus, damit ich deinen Namen preise! Die Gerechten werden bei mir erwarten, daß du mir wohltust.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 143, 1, 'Ein Psalm Davids. HERR, höre mein Gebet, vernimm mein Flehen um deiner Treue willen! Erhöre mich nach deiner Gerechtigkeit');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 143, 2, 'und geh nicht ins Gericht mit deinem Knecht! Denn vor dir ist kein Lebender gerecht.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 143, 3, 'Ach, der Feind verfolgt meine Seele, hat mein Leben zu Boden geschlagen, versetzt mich in Nacht wie die ewig Toten.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 143, 4, 'Nun will mein Geist in mir verzagen, mein Herz erstarrt mir in der Brust.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 143, 5, 'Ich gedenke der früheren Tage, rufe all deine Taten mir ins Gedächtnis, denke über dein ganzes Walten nach;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 143, 6, 'ich breite meine Hände aus nach dir: meine Seele dürstet nach dir wie lechzendes Land. SELA.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 143, 7, 'Eile, mich zu erhören, o HERR: mein Geist verzagt! Verhülle dein Angesicht nicht vor mir, sonst werde ich denen gleich, die ins Totenreich gefahren.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 143, 8, 'Laß schon früh am Morgen mich deine Gnade erfahren, denn auf dich vertraue ich! Tu mir kund den Weg, den ich gehn soll, denn zu dir erhebe ich meine Seele!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 143, 9, 'Rette mich, HERR, von meinen Feinden: zu dir nehme ich meine Zuflucht!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 143, 10, 'Lehre mich das dir Wohlgefällige tun, denn du bist mein Gott: dein guter Geist führe mich auf ebener Bahn!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 143, 11, 'Um deines Namens willen, HERR, erhalt’ mich am Leben, nach deiner Gerechtigkeit hilf mir aus der Not,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 143, 12, 'und nach deiner Gnade vertilge meine Feinde und vernichte alle, die meine Seele bedrängen; ich bin ja dein Knecht!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 144, 1, 'Von David. Gepriesen sei der HERR, mein Fels, der meine Hände tüchtig gemacht zum Kampf, meine Finger geschickt zum Kriege,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 144, 2, 'mein Wohltäter und meine Burg, meine Feste und mein Retter, mein Schild und der, auf den ich vertraue; Völker hat er mir unterworfen!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 144, 3, 'HERR, was ist der Mensch, daß du ihn beachtest, des Menschen Sohn, daß du seiner gedenkst?');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 144, 4, 'Der Mensch gleicht einem Hauch, seine Tage sind wie ein Schatten, der vorüberfliegt.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 144, 5, 'HERR, neige deinen Himmel und fahre herab, rühre die Berge an, daß sie rauchen!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 144, 6, 'Schleudre Blitze und zerstreue sie, schieß deine Pfeile ab und laß sie zerstieben!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 144, 7, 'Strecke deine Hände aus der Höhe herab, reiß mich heraus und rette mich aus gewaltigen Fluten, aus der Hand der Söhne der Fremde,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 144, 8, 'deren Lippen Lügen reden und deren Rechte mit Täuschung umgeht.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 144, 9, 'Gott, ein neues Lied will (alsdann) ich dir singen, auf zehnsaitiger Harfe dir spielen:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 144, 10, 'dir, der den Königen Sieg verleiht, der David, seinen Knecht, entrissen dem mörderischen Schwert.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 144, 11, 'Reiß mich heraus und rette mich aus der Hand der Söhne der Fremde, deren Lippen Lügen reden und deren Rechte mit Täuschung umgeht! –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 144, 12, 'O gib, daß unsere Söhne in ihrer Jugendkraft hochgewachsenen Setzlingen gleichen! Daß unsre Töchter seien wie schöngemeißelte Ecksäulen an prächtig gebauten Palästen!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 144, 13, 'Daß unsre Speicher, wohlgefüllt, spenden einen Vorrat nach dem andern! Daß unser Kleinvieh sich tausendfach mehre, zehntausendfach auf unsern Triften!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 144, 14, 'Daß unsre Rinder trächtig seien ohne Mißgeschick und ohne Fehlgeburt, keine Spaltung im Volk und kein Wehgeschrei auf unsern Straßen!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 144, 15, 'Glückselig das Volk, dem es so ergeht! Glückselig das Volk, dessen Gott der HERR ist!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 145, 1, 'Ein Loblied von David. Ich will dich erheben, mein Gott, du König, und deinen Namen preisen immer und ewig!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 145, 2, 'An jedem Tage will ich dich preisen und deinen Namen rühmen immer und ewig!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 145, 3, 'Groß ist der HERR und hoch zu rühmen, und seine Größe ist unausforschlich.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 145, 4, 'Ein Geschlecht wird dem andern rühmen deine Werke und kundtun deine gewaltigen Taten.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 145, 5, 'Von der herrlichen Pracht deiner Hoheit will ich reden, und von deinen Wundertaten (will ich singen).');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 145, 6, 'Von der Macht deines furchtbaren Waltens wird man reden, und deine Größe – davon will ich erzählen!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 145, 7, 'Den Ruhm deiner reichen Güte wird man verkünden und jubelnd preisen deine Gerechtigkeit.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 145, 8, 'Gnädig und barmherzig ist der HERR, langmütig und reich an Güte.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 145, 9, 'Der HERR ist gütig gegen alle, und sein Erbarmen umfaßt alle seine Werke.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 145, 10, 'Alle deine Werke werden dich loben, HERR, und deine Frommen dich preisen;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 145, 11, 'die Herrlichkeit deines Königtums werden sie rühmen und reden von deiner Macht,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 145, 12, 'um den Menschenkindern kundzutun seine mächtigen Taten und die herrliche Pracht seines Königtums.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 145, 13, 'Dein Reich ist ein Reich für alle Ewigkeiten, und deine Herrschaft besteht durch alle Geschlechter. Getreu ist der HERR in seinen Worten und heilig in all seinem Tun.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 145, 14, 'Der HERR stützt alle Fallenden und richtet alle Gebeugten auf.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 145, 15, 'Aller Augen warten auf dich, und du gibst ihnen ihre Speise zu seiner Zeit;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 145, 16, 'du tust deine Hand auf und sättigst alles, was lebt, mit Wohlgefallen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 145, 17, 'Gerecht ist der HERR in all seinem Walten und liebreich in all seinem Tun.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 145, 18, 'Der HERR ist nahe allen, die ihn anrufen, allen, die ihn in Treue anrufen;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 145, 19, 'er erfüllt das Begehren derer, die ihn fürchten, er hört ihr Schreien und hilft ihnen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 145, 20, 'Der HERR behütet alle, die ihn lieben, doch alle Frevler rottet er aus.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 145, 21, 'Mein Mund soll verkünden den Lobpreis des HERRN, und alles Fleisch soll preisen seinen heiligen Namen immer und ewig!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 146, 1, 'Halleluja! Lobe den HERRN, meine Seele!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 146, 2, 'Loben will ich den HERRN, solange ich lebe, will meinem Gott lobsingen, solange ich bin!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 146, 3, 'Verlaßt euch nicht auf Fürsten, nicht auf Menschen, die ja nicht helfen können!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 146, 4, 'Geht der Odem ihnen aus, so kehren sie zurück zum Staube; am gleichen Tage ist’s aus mit ihren Plänen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 146, 5, 'Wohl dem, dessen Hilfe der Gott Jakobs ist, dessen Hoffnung ruht auf dem HERRN, seinem Gott,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 146, 6, 'auf ihm, der Himmel und Erde geschaffen, das Meer mit allem, was in ihnen ist, der Treue ewiglich hält;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 146, 7, 'der Recht den Unterdrückten schafft und Brot den Hungrigen gibt. Der HERR macht die Gefangenen frei;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 146, 8, 'der HERR gibt Blinden das Augenlicht, der HERR richtet die Gebeugten auf, der HERR hat lieb die Gerechten;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 146, 9, 'der HERR behütet den Fremdling; Waisen und Witwen hält er aufrecht; doch den Weg der Gottlosen macht er zum Irrweg.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 146, 10, 'Der HERR wird König in Ewigkeit sein, dein Gott, o Zion, für und für! Halleluja!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 147, 1, 'Preiset den HERRN! Denn schön ist’s, unserm Gott zu lobsingen, ja lieblich und wohlgeziemend ist Lobgesang.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 147, 2, 'Der HERR baut Jerusalem wieder auf, er sammelt Israels zerstreute Söhne;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 147, 3, 'er heilt, die zerbrochnen Herzens sind, und verbindet ihre Wunden;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 147, 4, 'er bestimmt den Sternen ihre Zahl und ruft sie alle mit Namen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 147, 5, 'Groß ist unser Herr und allgewaltig, für seine Weisheit gibt’s kein Maß.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 147, 6, 'Der HERR hilft den Gebeugten auf, doch die Gottlosen stürzt er nieder zu Boden.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 147, 7, 'Stimmt für den HERRN ein Danklied an, spielt unserm Gott auf der Zither –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 147, 8, 'ihm, der den Himmel mit Wolken bedeckt und Regen schafft für die Erde, der Gras auf den Bergen sprießen läßt,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 147, 9, 'der den Tieren ihr Futter gibt, den jungen Raben, die zu ihm schreien!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 147, 10, 'Er hat nicht Lust an der Stärke des Rosses, nicht Gefallen an den Schenkeln des Mannes;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 147, 11, 'Gefallen hat der HERR an denen, die ihn fürchten, an denen, die auf seine Gnade harren.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 147, 12, 'Preise den HERRN, Jerusalem, lobsinge, Zion, deinem Gott!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 147, 13, 'Denn er hat die Riegel deiner Tore stark gemacht, gesegnet deine Kinder in deiner Mitte;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 147, 14, 'er schafft deinen Grenzen Sicherheit, sättigt dich mit dem Mark des Weizens.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 147, 15, 'Er läßt sein Machtwort nieder zur Erde gehn: gar eilig läuft sein Gebot dahin;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 147, 16, 'er sendet Schnee wie Wollflocken und streut den Reif wie Asche aus;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 147, 17, 'er wirft seinen Hagel wie Brocken herab: wer kann bestehn vor seiner Kälte?');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 147, 18, 'Doch läßt er sein Gebot ergehn, so macht er sie schmelzen; läßt er wehn seinen Tauwind, so rieseln die Wasser.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 147, 19, 'Er hat Jakob sein Wort verkündet, Israel sein Gesetz und seine Rechte.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 147, 20, 'Mit keinem (anderen) Volk ist so er verfahren, drum kennen sie seine Rechte nicht. Halleluja!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 148, 1, 'Halleluja! Lobet den HERRN vom Himmel her, lobet ihn in den Himmelshöhen!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 148, 2, 'Lobet ihn, alle seine Engel, lobet ihn, alle seine Heerscharen!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 148, 3, 'Lobet ihn, Sonne und Mond, lobet ihn, alle ihr leuchtenden Sterne!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 148, 4, 'Lobet ihn, ihr Himmel der Himmel, und ihr Wasser oberhalb des Himmels!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 148, 5, 'Loben sollen sie den Namen des HERRN, denn er gebot, da waren sie geschaffen,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 148, 6, 'und er hat sie hingestellt für immer und ewig und ihnen ein Gesetz gegeben, das übertreten sie nicht.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 148, 7, 'Lobet den HERRN von der Erde her, ihr Seeungeheuer und alle Meeresfluten,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 148, 8, 'du Feuer und Hagel, du Schnee und Nebel, du Sturmwind, der sein Gebot vollzieht;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 148, 9, 'ihr Berge und Hügel allesamt, ihr Fruchtbäume und Zedern allzumal,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 148, 10, 'ihr Tiere alle, wilde und zahme, du Gewürm und ihr beschwingte Vögel,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 148, 11, 'ihr Könige der Erde und alle Völkerschaften, ihr Fürsten und alle Richter auf Erden,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 148, 12, 'ihr Jünglinge mitsamt den Jungfrauen, ihr Greise samt den Jungen!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 148, 13, 'Sie alle sollen loben den Namen des HERRN, denn sein Name allein ist erhaben; seine Hoheit überragt die Erde und den Himmel.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 148, 14, 'Er hat sein Volk aufs neue zu Ehren gebracht: ein Ruhm ist das für alle seine Frommen, für Israels Söhne, das Volk, das am nächsten ihm steht. Halleluja!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 149, 1, 'Halleluja! Singet dem HERRN ein neues Lied, seinen Lobpreis in der Versammlung der Frommen!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 149, 2, 'Es freue sich Israel seines Schöpfers, Zions Söhne sollen jubeln ob ihrem König!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 149, 3, 'Sie sollen seinen Namen preisen im Reigentanz, mit Pauken und Zithern ihm spielen!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 149, 4, 'Denn der HERR hat Wohlgefallen an seinem Volk; er schmückt die Gebeugten mit Sieg.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 149, 5, 'Frohlocken sollen die Frommen mit Stolz, sollen jauchzen auf ihren Lagern,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 149, 6, 'Lobeserhebungen Gottes im Mund und ein doppelschneidiges Schwert in der Hand:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 149, 7, 'um Rache zu vollziehn an den Heiden, Vergeltung an den Völkern,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 149, 8, 'um ihre Könige mit Ketten zu binden und ihre Edlen mit eisernen Fesseln,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 149, 9, 'um das längst geschriebene Urteil an ihnen zu vollstrecken: eine Ehre ist dies für alle seine Frommen! Halleluja!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 150, 1, 'Halleluja! Lobt Gott in seinem (himmlischen) Heiligtum, lobt ihn in seiner starken Feste!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 150, 2, 'Lobt ihn ob seinen Wundertaten, lobt ihn nach seiner gewaltigen Größe!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 150, 3, 'Lobt ihn mit Posaunenschall, lobt ihn mit Harfe und Zither!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 150, 4, 'Lobt ihn mit Pauke und Reigentanz, lobt ihn mit Saitenspiel und Flöte!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 150, 5, 'Lobt ihn mit hellklingenden Zimbeln, lobt ihn mit lautschallenden Zimbeln!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 150, 6, 'Alles, was Odem hat, lobe den HERRN! Halleluja!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 1, 1, '(Dies sind) die Sprüche Salomos, des Sohnes Davids, des Königs von Israel:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 1, 2, 'damit man Weisheit und Zucht lernt, Verständnis gewinnt für verständige Reden,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 1, 3, 'damit man Zucht erlangt, welche Besonnenheit verleiht, Gerechtigkeit, Sittlichkeit und Ehrenhaftigkeit,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 1, 4, 'damit den Unerfahrenen Klugheit zuteil wird, den Jünglingen Erkenntnis und Lebenskunst.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 1, 5, 'Auch der Weise möge sie vernehmen, um an Wissen zuzunehmen, und der Verständige möge sich (durch sie) Lebensklugheit aneignen,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 1, 6, 'um Sinnsprüche und bildliche Rede zu verstehen, die Worte der Weisen und ihre Rätsel.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 1, 7, 'Die Furcht des HERRN ist der Anfang der Erkenntnis; die Toren verachten Weisheit und Zucht.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 1, 8, 'Höre, mein Sohn, auf die Belehrung deines Vaters und achte nicht gering die Unterweisung deiner Mutter!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 1, 9, 'Denn sie sind ein schöner Kranz für dein Haupt und eine Schmuckkette für deinen Hals.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 1, 10, 'Mein Sohn, wenn Sünder dich locken, so willige nicht ein.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 1, 11, 'Wenn sie zu dir sagen: »Komm mit uns! Wir wollen auf Bluttaten ausgehen, dem Unschuldigen ohne Ursache auflauern!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 1, 12, 'Wir wollen sie verschlingen wie das Totenreich, lebendig und mit Haut und Haaren, wie solche, die in die Grube hinabgefahren sind!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 1, 13, 'Allerlei kostbares Gut wollen wir gewinnen, wollen unsere Häuser mit Raub anfüllen!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 1, 14, 'Du sollst gleichen Anteil mit uns haben: wir wollen alle eine gemeinsame Kasse haben!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 1, 15, 'Mein Sohn, schließe dich ihnen auf ihren Wegen nicht an, halte deinen Fuß von ihrem Pfade zurück!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 1, 16, 'Denn ihre Füße laufen dem Bösen zu und haben Eile, Blut zu vergießen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 1, 17, 'Denn vergeblich ist das Netz ausgebreitet vor den Augen des gesamten Vogelvolkes;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 1, 18, 'vielmehr machen sie Anschläge gegen ihr eigenes Blut, stellen ihrem eigenen Leben nach.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 1, 19, 'So ergeht es (schließlich) allen, die nach unrechtem Gewinn trachten: dieses (Trachten) kostet seinem Besitzer das (eigene) Leben.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 1, 20, 'Die Weisheit erhebt ihren Ruf laut auf der Straße, läßt ihre Stimme auf den Märkten erschallen;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 1, 21, 'an der Ecke lärmerfüllter Straßen predigt sie; in den Eingängen der Stadttore, in der ganzen Stadt hält sie ihre Reden:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 1, 22, '»Wie lange noch wollt ihr Einfältigen die Einfältigkeit lieben und ihr Spötter Gefallen am Spotten finden und ihr Toren Erkenntnis hassen?');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 1, 23, 'Wendet euch meiner Zurechtweisung zu! Seht, ich will euch meinen Geist hervorströmen lassen, will euch meine Worte kundtun.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 1, 24, 'Weil ich gerufen habe und ihr mich abgewiesen habt, weil ich mit der Hand gewinkt habe und niemand darauf geachtet hat,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 1, 25, 'ihr vielmehr jeden Ratschlag von mir verworfen und auf meine Zurechtweisung nichts gegeben habt:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 1, 26, 'so will auch ich bei eurem Unglück lachen, will spotten, wenn der Schrecken über euch kommt,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 1, 27, 'wenn der Schrecken euch überfällt wie ein Unwetter und euer Verderben wie ein Sturmwind heranzieht, wenn Angst und Bedrängnis über euch hereinbrechen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 1, 28, 'Alsdann werden sie nach mir rufen, aber ich werde nicht antworten; sie werden mich eifrig suchen, aber mich nicht finden.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 1, 29, 'Weil sie die Erkenntnis gehaßt und sich der Gottesfurcht nicht zugewandt,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 1, 30, 'meinen Ratschlägen kein Gehör geschenkt, jede Zurechtweisung von mir verschmäht haben: –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 1, 31, 'darum sollen sie die Frucht ihres Tuns zu schmecken bekommen und sich an ihren eigenen Anschlägen satt essen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 1, 32, 'Denn den Einfältigen bringt ihr eigenes Widerstreben den Tod, und ihre eigene Sorglosigkeit stürzt die Toren ins Verderben;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 1, 33, 'wer aber auf mich hört, wird sicher wohnen und wohlgemut sein ohne Angst vor Unheil.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 2, 1, 'Mein Sohn, wenn du meine Lehren annimmst und meine Weisungen bei dir verwahrst,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 2, 2, 'indem du dein Ohr auf Weisheit lauschen läßt und dein Herz der Einsicht zuwendest,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 2, 3, 'ja, wenn du nach der Verständigkeit rufst und deine Stimme laut nach der Einsicht erschallen läßt,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 2, 4, 'wenn du nach ihr suchst wie nach Silber und ihr nachspürst wie verborgenen Schätzen:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 2, 5, 'dann wirst du die Furcht vor dem HERRN verstehen lernen und die Erkenntnis Gottes gewinnen –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 2, 6, 'denn der HERR ist’s, der Weisheit verleiht: aus seinem Munde kommt Erkenntnis und Einsicht;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 2, 7, 'er hält für die Rechtschaffenen Glück in Bereitschaft und ist ein Schild für die, welche unsträflich wandeln,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 2, 8, 'indem er die Pfade des Rechts behütet und über dem Ergehen seiner Frommen wacht –;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 2, 9, 'dann wirst du Verständnis gewinnen für Gerechtigkeit und Recht, für Rechtschaffenheit (und überhaupt) für jegliche Bahn des Guten.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 2, 10, 'Denn Weisheit wird in dein Herz einziehen und Erkenntnis deiner Seele erfreulich sein;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 2, 11, 'Besonnenheit wird über dich wachen und Einsicht dich behüten,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 2, 12, 'indem sie dich vor dem Wege der Bösen bewahrt, vor den Menschen, die Verkehrtes reden,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 2, 13, 'vor denen, welche die geraden Pfade verlassen, um auf den Wegen der Finsternis zu wandeln;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 2, 14, 'die ihre Freude daran haben, Böses zu verüben, und über boshafte Verkehrtheit frohlocken;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 2, 15, 'deren Pfade krumm sind und die in ihren Bahnen auf Abwege geraten –;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 2, 16, 'indem sie dich vom Eheweibe eines anderen fernhält, von der fremden Frau, die glatte Reden führt,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 2, 17, 'die den trauten Freund ihrer Jugend verlassen und den vor ihrem Gott geschlossenen Ehebund vergessen hat;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 2, 18, 'denn zum Tode sinkt ihr Pfad hinab, und zum Schattenreich (führen) ihre Bahnen;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 2, 19, 'keiner von denen, die zu ihr eingehen, kehrt zurück, und keiner erreicht die Pfade des Lebens –;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 2, 20, 'damit du auf dem Wege der Guten wandelst und die Pfade der Gerechten einhältst.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 2, 21, 'Denn die Rechtschaffenen werden das Land bewohnen und die Unsträflichen darin übrigbleiben;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 2, 22, 'die Gottlosen aber werden aus dem Lande ausgerottet und die Treulosen aus ihm entwurzelt.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 3, 1, 'Mein Sohn, vergiß meine Belehrung nicht und laß dein Herz meine Weisungen bewahren;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 3, 2, 'denn langes Leben und Jahre des Glücks und Wohlergehen werden sie dir in Fülle bringen. –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 3, 3, 'Liebe und Treue dürfen dich nicht verlassen: binde sie dir um den Hals, schreibe sie auf die Tafel deines Herzens,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 3, 4, 'so wirst du Gunst und Beifall gewinnen bei Gott und den Menschen. –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 3, 5, 'Vertraue auf den HERRN mit ganzem Herzen und verlaß dich nicht auf eigene Klugheit;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 3, 6, 'denke an ihn auf allen deinen Wegen, so wird er dir die Pfade ebnen. –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 3, 7, 'Halte dich nicht selbst für weise; fürchte den HERRN und halte dich fern vom Bösen:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 3, 8, 'das wird Arznei für deinen Leib sein und Labsal für deine Glieder. –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 3, 9, 'Ehre den HERRN mit (Gaben von) deinem Vermögen und mit den Erstlingen deines gesamten Feldertrags,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 3, 10, 'so werden deine Scheunen mit Überfluß sich füllen und deine Kufen von Most überfließen. –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 3, 11, 'Mein Sohn, verschmähe nicht die Zucht des HERRN und sei nicht unwillig über seine Strafe;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 3, 12, 'denn wen der HERR lieb hat, den züchtigt er, und zwar wie ein Vater den Sohn, mit dem er’s gut meint.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 3, 13, 'Wohl dem Menschen, der Weisheit erlangt hat, und wohl dem Manne, der Einsicht gewinnt!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 3, 14, 'Denn besser ist ihr Erwerb als der von Silber, und ihr Besitz ist mehr wert als Gold;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 3, 15, 'kostbarer ist sie als Perlen, und alle Kleinodien kommen ihr nicht gleich.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 3, 16, 'Langes Leben liegt in ihrer Rechten, in ihrer Linken Reichtum und Ehre.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 3, 17, 'Ihre Wege sind beglückende Wege, und alle ihre Pfade sind Wohlergehen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 3, 18, 'Ein Baum des Lebens ist sie denen, die sie ergriffen haben, und wer sie festhält, ist glücklich zu preisen. –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 3, 19, 'Der HERR hat durch Weisheit die Erde gegründet und den Himmel durch Einsicht festgestellt;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 3, 20, 'durch seine Erkenntnis sind die Fluten der Tiefe (als Quellen) hervorgebrochen, und die Wolken lassen den Tau herabträufeln. –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 3, 21, 'Mein Sohn, laß sie nicht aus deinen Augen entschwinden; halte fest an kluger Überlegung und Besonnenheit:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 3, 22, 'so werden sie Leben für deine Seele sein und ein schöner Schmuck für deinen Hals;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 3, 23, 'dann wirst du deinen Weg in Sicherheit wandeln und mit deinem Fuß nicht anstoßen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 3, 24, 'Wenn du dich schlafen legst, braucht dir nicht zu grauen; und legst du dich nieder, so wird dein Schlummer süß sein;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 3, 25, 'du brauchst dich nicht vor plötzlichem Schrecken zu fürchten, auch nicht vor der Vernichtung der Gottlosen, wenn sie hereinbricht;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 3, 26, 'denn der HERR wird deine Zuversicht sein und deinen Fuß vor dem Fallstrick behüten.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 3, 27, 'Versage keinem Bedürftigen eine Wohltat, wenn es in deiner Macht steht, sie zu erweisen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 3, 28, 'Sage nicht zu deinem Nächsten: »Geh (jetzt) und komm mal wieder!« und »Morgen will ich es dir geben«, während du es doch schon jetzt tun kannst. –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 3, 29, 'Ersinne nichts Böses gegen deinen Nächsten, während er arglos neben dir wohnt. –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 3, 30, 'Fange mit keinem Menschen Streit ohne Ursache an, wenn er dir nichts Böses zugefügt hat. –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 3, 31, 'Sei nicht neidisch auf gewalttätige Menschen und verstehe dich nicht zu einem von ihren Wegen!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 3, 32, 'Denn wer sich auf Abwege begibt, ist dem HERRN ein Greuel, aber mit den Redlichen hält er treue Freundschaft.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 3, 33, 'Der Fluch des HERRN (lastet) auf dem Hause des Gottlosen, aber die Wohnung der Gerechten segnet er;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 3, 34, 'für die Spötter wird er selbst ein Spötter, aber den Demütigen gibt er Gnade.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 3, 35, 'Zu Ehren gelangen die Weisen, aber den Toren verschafft die Schande einen Namen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 4, 1, 'Hört, ihr Kinder, die väterliche Unterweisung und merkt wohl auf, um Einsicht zu lernen!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 4, 2, 'Denn treffliche Lehre gebe ich euch: laßt meine Weisungen nicht unbeachtet!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 4, 3, 'Denn als ich noch als Sohn bei meinem Vater war, als zartes und einziges Kind unter der Obhut meiner Mutter,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 4, 4, 'da belehrte er mich und sagte zu mir: »Laß dein Herz meine Worte festhalten! Beobachte meine Weisungen, so wirst du leben.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 4, 5, 'Erwirb dir Weisheit, erwirb dir Einsicht, vergiß sie nicht und weiche nicht ab von den Worten meines Mundes!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 4, 6, 'Laß sie nicht außer acht, so wird sie dich behüten; gewinne sie lieb, so wird sie dich beschirmen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 4, 7, 'Mit dem besten Teil deiner Habe erwirb dir Weisheit, und um den Preis deines ganzen Vermögens verschaffe dir Einsicht!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 4, 8, 'Halte sie hoch, so wird sie dir Ansehen verleihen, wird dich zu Ehren bringen, wenn du sie mit Liebe umfängst;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 4, 9, 'sie wird dir einen schönen Kranz aufs Haupt setzen, eine herrliche Krone dir bescheren.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 4, 10, 'Höre, mein Sohn, und nimm meine Worte an, so werden dir viele Lebensjahre zuteil werden.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 4, 11, 'Über den Weg der Weisheit will ich dich belehren, will dich auf rechten Bahnen einhergehen lassen;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 4, 12, 'wenn du (auf ihnen) wandelst, wird dein Schritt nicht gehemmt sein, und wenn du läufst, wirst du nicht zu Fall kommen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 4, 13, 'Halte an der Zucht fest, laß sie nicht fahren! Bewahre sie, denn sie ist dein Leben.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 4, 14, 'Begib dich nicht auf den Pfad der Gottlosen und schreite nicht einher auf dem Wege der Bösen!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 4, 15, 'Meide ihn, gehe nicht auf ihn hinüber! Wende dich von ihm ab und gehe daran vorüber!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 4, 16, 'Denn sie können nicht schlafen, wenn sie nicht Böses (zuvor) getan haben; und der Schlaf ist ihnen geraubt, wenn sie nicht jemand verführt haben;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 4, 17, 'denn das Brot, das sie essen, ist Gottlosigkeit, und der Wein, den sie trinken, ist Gewalttätigkeit.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 4, 18, 'Aber der Pfad der Gerechten gleicht dem Glanz des Morgenlichts, das immer heller leuchtet bis zur vollen Tageshöhe.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 4, 19, 'Der Weg der Gottlosen ist wie dunkle Nacht; sie gewahren nicht, worüber sie straucheln.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 4, 20, 'Mein Sohn, merke auf meine Worte, leihe meinen Reden dein Ohr!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 4, 21, 'Laß sie deinen Augen nie entschwinden, bewahre sie im Innersten deines Herzens!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 4, 22, 'Denn Leben sind sie für jeden, der sie erfaßt, und heilsame Arznei für seinen ganzen Leib.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 4, 23, 'Mehr als alles, was man zu bewachen hat, behüte dein Herz; denn von ihm hängt das Leben ab.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 4, 24, 'Tu Falschheit des Mundes von dir ab und laß Lug und Trug fern von deinen Lippen sein!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 4, 25, 'Dann können deine Augen geradeaus schauen und deine Augenlider frei vor dich hinblicken.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 4, 26, 'Laß deinen Fuß auf gerader Bahn gehen und alle deine Wege fest gerichtet sein!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 4, 27, 'Weiche nicht nach rechts noch nach links ab; halte deinen Fuß vom Bösen fern!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 5, 1, 'Mein Sohn, merke auf meine Weisheit und leihe meiner Einsicht dein Ohr,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 5, 2, 'um Besonnenheit zu beobachten und damit deine Lippen Erkenntnis bewahren.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 5, 3, 'Denn von Honigseim triefen die Lippen der fremden Frau, und glätter als Öl ist ihr Gaumen;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 5, 4, 'aber zuletzt ist sie bitter wie Wermut, scharf wie ein zweischneidiges Schwert.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 5, 5, 'Ihre Füße steigen zum Tode hinab, ihre Schritte sind geradeswegs zur Unterwelt gerichtet.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 5, 6, 'Damit du nicht den Weg des Lebens einschlägst, sind ihre Bahnen unstet, ohne daß du es merkst.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 5, 7, 'Nun denn, mein Sohn, höre auf mich und weiche nicht ab von den Worten meines Mundes!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 5, 8, 'Halte deinen Weg fern von ihr und nahe dich nicht der Tür ihres Hauses,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 5, 9, 'damit du nicht anderen deine Ehre hingeben mußt und (den Ertrag) deiner Jahre einem unerbittlichen (Rächer);');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 5, 10, 'damit nicht Fremde sich an deinem Vermögen sättigen und dein mühsam Erworbenes nicht in das Haus eines andern kommt,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 5, 11, 'und du nicht schließlich seufzen mußt, wenn dir Leib und Fleisch dahingeschwunden ist,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 5, 12, 'und du klagen mußt: »Ach, warum habe ich die Zucht gehaßt, und warum hat mein Herz die Warnung mißachtet!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 5, 13, 'Warum habe ich nicht auf die Stimme meiner Lehrer gehört und meinen Erziehern kein Gehör geschenkt!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 5, 14, 'Beinahe wäre ich ganz ins Verderben geraten inmitten der Gerichtsversammlung und in der Gemeinde!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 5, 15, 'Trinke Wasser nur aus deiner eigenen Zisterne und Quellwasser aus deinem eigenen Born!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 5, 16, 'Sollen deine Quellen sich auf die Straße ergießen, deine Wasserbäche auf die freien Plätze?');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 5, 17, 'Nein, dir allein sollen sie angehören und keinem Fremden neben dir.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 5, 18, 'Dein Brunnquell möge gesegnet sein, daß du am Weibe deiner Jugend dich erfreust!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 5, 19, 'Das liebreizende Reh, die anmutige Gazelle – ihr Busen möge dich allezeit ergötzen, in ihrer Liebe sei immerdar trunken!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 5, 20, 'Denn warum wolltest du, mein Sohn, an einer Fremden dich ergötzen und den Busen einer anderen umarmen? –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 5, 21, 'Denn vor den Augen des HERRN liegen die Wege eines jeden offen da, und auf alle seine Pfade gibt er acht.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 5, 22, 'Die eigenen Verschuldungen fangen ihn, den Gottlosen, und durch die Bande seiner Sünde wird er festgehalten.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 5, 23, 'Sterben wird ein solcher infolge des Mangels an Zucht und ob seiner großen Torheit zum Sturz hintaumeln.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 6, 1, 'Mein Sohn, hast du dich für deinen Nächsten verbürgt, für einen andern dich durch Handschlag verpflichtet,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 6, 2, 'bist du durch ein mündliches Versprechen gebunden und hast du dich durch eine Zusage verstricken lassen,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 6, 3, 'so tu doch ja dies, mein Sohn, damit du wieder frei wirst – denn du bist in die Gewalt deines Nächsten gefallen –: Gehe hin, wirf dich vor ihm nieder und bestürme deinen Nächsten mit Bitten!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 6, 4, 'Gönne deinen Augen keinen Schlaf und deinen Augenlidern keinen Schlummer!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 6, 5, 'Mache dich frei von ihm wie eine Gazelle aus der Hand (des Jägers) und wie ein Vogel aus der Hand des Vogelstellers! –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 6, 6, 'Gehe hin zur Ameise, du Fauler, sieh ihr Tun an, damit du klug wirst.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 6, 7, 'Obgleich sie kein Oberhaupt, keinen Vorsteher und Gebieter hat,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 6, 8, 'sorgt sie doch im Sommer für ihren Unterhalt, sammelt in der Erntezeit ihre Nahrung ein.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 6, 9, 'Wie lange noch willst du liegen bleiben, du Fauler? Wann endlich willst du von deinem Schlaf dich erheben?');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 6, 10, '»Noch ein wenig Schlaf, ein wenig Schlummer, noch ein wenig die Hände falten, um auszuruhen!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 6, 11, 'So kommt denn die Verarmung an dich heran wie ein Schnellläufer und der Mangel wie ein gewappneter Mann. –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 6, 12, 'Ein nichtswürdiger Mensch, ein heilloser Mann ist, wer mit Lug und Trug des Mundes umhergeht,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 6, 13, 'wer mit den Augen blinzelt, mit den Füßen scharrt, mit den Fingern Zeichen gibt,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 6, 14, 'wer hinterlistige Pläne im Herzen ersinnt, allezeit böse Anschläge schmiedet und Händel anstiftet.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 6, 15, 'Darum wird ihn das Verderben plötzlich ereilen; unvermutet wird er zerschmettert werden unheilbar. –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 6, 16, 'Sechs Dinge sind es, die der HERR haßt, und sieben sind seinem Herzen ein Greuel:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 6, 17, 'hochmütige Augen, eine Lügenzunge und Hände, die unschuldiges Blut vergießen;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 6, 18, 'ein Herz, das tückische Anschläge schmiedet, Füße, die eilends zu bösem Tun laufen;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 6, 19, 'wer als falscher Zeuge Lügen aussagt und Hader anstiftet unter Brüdern.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 6, 20, 'Mein Sohn, halte das Gebot deines Vaters fest und laß nicht die Weisung deiner Mutter fahren!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 6, 21, 'Binde sie dir beständig aufs Herz, schlinge sie dir um den Hals!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 6, 22, 'Wenn du umhergehst, möge sie dich geleiten; wenn du dich niedergelegt hast, möge sie dich bewachen, und bist du aufgewacht, so möge sie sich mit dir unterreden.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 6, 23, 'Denn das Gebot ist eine Leuchte und die Weisung ein Licht; und die Zurechtweisungen der Zucht sind der Weg zum Leben(sglück):');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 6, 24, 'sie sollen dich bewahren vor dem bösen Weibe, vor der glatten Zunge einer fremden Frau.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 6, 25, 'Trage in deinem Herzen kein Verlangen nach ihrer Schönheit und laß dich nicht von ihr durch ihre Blicke fangen!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 6, 26, 'Denn der Preis für eine Buhldirne beträgt höchstens einen Laib Brot, aber eine verheiratete Frau macht Jagd auf die kostbare Seele.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 6, 27, 'Kann wohl jemand Feuer in den Bausch des Gewandes fassen, ohne daß seine Kleider in Brand geraten?');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 6, 28, 'Oder kann jemand über glühende Kohlen gehen, ohne sich die Füße zu verbrennen?');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 6, 29, 'Ebenso ergeht es dem, der sich mit der Ehefrau eines andern einläßt: keiner, der sie berührt, kommt ungestraft davon.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 6, 30, 'Man verachtet den Dieb nicht, wenn er stiehlt, um seine Gier zu stillen, wenn ihn hungert;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 6, 31, 'doch wenn er ertappt wird, mag (muß) er siebenfachen Ersatz leisten, (am Ende gar) das ganze Vermögen seines Hauses hingeben;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 6, 32, 'wer aber mit einem verheirateten Weibe Ehebruch begeht, ist von Sinnen; nur wer sich selbst zugrunde richten will, tut so etwas.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 6, 33, 'Schläge und Schmach trägt er als Lohn davon, und seine Schande ist unauslöschlich;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 6, 34, 'denn Eifersucht ist wilder Zorn eines Ehemannes, und am Tage der Rache übt er keine Schonung:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 6, 35, 'er läßt sich auf keinerlei Sühnegeld ein und bleibt unerbittlich, magst du ihm auch noch so viele Geschenke bieten.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 7, 1, 'Mein Sohn, bewahre meine Warnungen und halte meine Gebote im Gedächtnis fest!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 7, 2, 'Bewahre meine Gebote, so wirst du leben, und hüte meine Lehren wie deinen Augapfel!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 7, 3, 'Binde sie dir um die Finger, schreibe sie dir auf die Tafel deines Herzens!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 7, 4, 'Sage zur Weisheit: »Du bist meine Schwester«, und nenne die Einsicht deine vertraute Freundin,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 7, 5, 'damit sie dich von dem Eheweibe eines andern fernhält, von der fremden Frau, die glatte Reden führt.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 7, 6, 'Denn als ich (einmal) am Fenster meines Hauses durch mein Gitter hinausschaute,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 7, 7, 'da sah ich unter den Unerfahrenen, bemerkte ich unter den jungen Leuten einen unverständigen Jüngling,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 7, 8, 'der auf der Straße hin und her ging, in der Nähe ihrer Ecke, und in der Richtung nach ihrem Hause schritt,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 7, 9, 'in der Dämmerung, am Abend des Tages, tief in der Nacht und in der Finsternis.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 7, 10, 'Da kam ihm auf einmal eine Frau entgegen im Anzug einer Lustdirne und mit arglistigem Herzen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 7, 11, 'Sie ist in leidenschaftlicher Aufregung und wilder Unruhe, ihre Füße halten’s in ihrem Hause nicht aus;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 7, 12, 'bald ist sie auf der Straße, bald auf den freien Plätzen, und neben jeder Ecke lauert sie.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 7, 13, 'Nun hascht sie ihn, küßt ihn und sagt zu ihm mit frecher Miene:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 7, 14, '»Dankopfer war ich schuldig: heute habe ich meine Gelübde entrichtet;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 7, 15, 'darum bin ich ausgegangen dir entgegen, um dich aufzusuchen, und habe dich nun gefunden.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 7, 16, 'Mit Teppichen habe ich mein Lager hergerichtet, mit bunten Decken von ägyptischem Linnen;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 7, 17, 'ich habe mein Bett mit Myrrhe, Aloe und Zimt besprengt.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 7, 18, 'Komm, wir wollen uns an der Liebe berauschen, bis zum Morgen in Liebeslust schwelgen!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 7, 19, 'Denn der Mann ist nicht daheim, er ist weithin auf Reisen gegangen;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 7, 20, 'die Geldtasche hat er mit sich genommen: erst am Vollmondstage kommt er wieder heim.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 7, 21, 'Durch ihr eifriges Zureden verführte sie ihn, mit ihrem glatten Geschwätz riß sie ihn fort:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 7, 22, 'betört folgte er ihr wie ein Stier, der zur Schlachtung geht, und wie ein Hirsch, der ins Netz rennt,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 7, 23, 'bis ein Pfeil ihm das Herz durchbohrt; wie ein Vogel dem Fanggarn zueilt, ohne zu ahnen, daß es um sein Leben geht.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 7, 24, 'Nun denn, mein Sohn, so höre auf mich und achte auf die Mahnungen meines Mundes!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 7, 25, 'Laß dein Herz sich nicht auf ihre Wege locken, verirre dich nicht auf ihre Pfade!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 7, 26, 'denn viele Erschlagene hat sie zu Boden gestreckt, und zahlreich sind die, welche sie alle gemordet hat.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 7, 27, 'Ihr Haus bildet den Eingang zur Unterwelt, Wege, die zu den Kammern des Todes hinabführen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 8, 1, 'Horch! Die Weisheit ruft vernehmlich, und die Einsicht läßt ihre Stimme erschallen!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 8, 2, 'Oben auf den Höhen am Wege, da wo die Pfade zusammenlaufen, hat sie sich aufgestellt;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 8, 3, 'neben den Toren, am Ausgang der Stadt, am Eingang der Pforten ruft sie laut:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 8, 4, '»An euch, ihr Männer, richte ich meinen Ruf, und meine Stimme ergeht an die Menschenkinder.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 8, 5, 'Gewinnt, ihr Einfältigen, Einsicht in Klugheit, und ihr Toren, gewinnt Einsicht in Verständigkeit!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 8, 6, 'Hört zu! Denn ich habe Wertvolles zu sagen, und meine Lippen will ich auftun zu (auf-) richtiger Rede;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 8, 7, 'denn mein Mund spricht Wahrheit aus, und Unehrlichkeit ist ein Greuel für meine Lippen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 8, 8, 'Aufrichtig sind alle Reden meines Mundes: es ist nichts Hinterlistiges und Trügerisches in ihnen;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 8, 9, 'sie sind sämtlich klar für den Verständigen und richtig für die zur Erkenntnis Gelangten.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 8, 10, 'Nehmt Unterweisung lieber an als Silber, und Erkenntnis lieber als auserlesenes Gold!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 8, 11, 'Denn die Weisheit ist besser als Korallen, und alle Kleinode kommen ihr nicht gleich.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 8, 12, 'Ich, die Weisheit, stehe im Bunde mit der Klugheit und verfüge über Erkenntnis wohldurchdachter Pläne.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 8, 13, 'Die Furcht des HERRN besteht im Haß gegen das Böse; Hoffart, Hochmut und bösen Wandel sowie den Mund des Truges hasse ich.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 8, 14, 'Mir steht kluger Rat und Überlegung zu Gebot, ich verfüge über Einsicht, und ich besitze Tatkraft.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 8, 15, 'Durch mich üben die Könige ihre Königsmacht aus und erlassen die Machthaber gerechte Verordnungen;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 8, 16, 'durch mich betätigen sich die Herrscher als Herrscher und alle Richter auf Erden als Edle.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 8, 17, 'Ich liebe, die mich lieben, und wer mich eifrig sucht, der findet mich.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 8, 18, 'Reichtum und Ehre sind bei mir zu finden, bleibender Wohlstand und Gerechtigkeit;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 8, 19, 'was ich einbringe, ist wertvoller als feines, gediegenes Gold, und mein Ertrag kostbarer als auserlesenes Silber.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 8, 20, 'Ich wandle auf dem Pfade der Gerechtigkeit, mitten auf den Bahnen des Rechts,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 8, 21, 'um denen, die mich lieben, bleibenden Besitz zu verschaffen und ihre Schatzkammern zu füllen.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 8, 22, '»Der HERR hat mich geschaffen als den Erstling seiner Schöpfertätigkeit, als das früheste seiner Werke in der Urzeit.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 8, 23, 'Von Ewigkeit her bin ich gebildet, von Anbeginn an, vor den Uranfängen der Erde.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 8, 24, 'Als noch keine Fluten der Tiefe da waren, bin ich geboren worden, ehe es wasserreiche Quellen gab.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 8, 25, 'Bevor die Berge eingesenkt waren, vor den Hügeln bin ich geboren worden,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 8, 26, 'als er die Erde und die Fluren noch nicht geschaffen hatte und die ersten Schollen des Erdreichs.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 8, 27, 'Als er den Himmel baute, war ich dabei, als er das Himmelsgewölbe feststellte über der weiten Urflut;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 8, 28, 'als er die Wolken droben befestigte, als er die Quellen aus den Fluten der Tiefe mit Macht hervorbrechen ließ;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 8, 29, 'als er dem Meer seine Grenze setzte, damit die Wasser seine Schranke nicht überschritten, als er die Grundpfeiler der Erde feststellte:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 8, 30, 'da war ich als Künstlerin ihm zur Seite und war voller Entzücken Tag für Tag, indem ich vor seinen Augen allezeit spielte,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 8, 31, 'indem ich auf seiner weiten Erdenwelt mein Spiel trieb und mein Entzücken an den Menschenkindern hatte.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 8, 32, '»Nun denn, ihr Söhne, höret auf mich! Denn glückselig sind, die meine Wege einhalten.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 8, 33, 'Höret auf meine Unterweisung, damit ihr weise werdet, und verwerft sie nicht!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 8, 34, 'Wohl dem Menschen, der mir Gehör schenkt, indem er Tag für Tag an meiner Tür wacht und die Pfosten meiner Tore hütet!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 8, 35, 'Denn wer mich findet, der findet das Leben und erlangt Wohlgefallen beim HERRN;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 8, 36, 'wer mich aber verfehlt, der fügt seiner eigenen Seele Schaden zu: alle, die mich hassen, lieben den Tod.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 9, 1, 'Die Weisheit hat sich ihr Haus gebaut, hat ihre sieben Säulen aufgerichtet;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 9, 2, 'sie hat ihr Schlachtvieh geschlachtet, ihren Wein gemischt, auch ihre Tafel zugerüstet;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 9, 3, 'sie hat ihre Mägde ausgesandt und läßt oben auf den höchsten Punkten der Stadt die Einladung ergehen:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 9, 4, '»Wer einfältig ist, kehre hier ein!« Und den Unverständigen läßt sie sagen:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 9, 5, '»Kommt her, eßt von meinem Brot und trinkt von dem Wein, den ich gemischt habe!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 9, 6, 'Laßt die Torheit fahren, damit ihr lebt, und geht einher auf dem Wege der Einsicht!« –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 9, 7, 'Wer einen Spötter zurechtweist, zieht sich Beschimpfung zu, und wer einen Gottlosen tadelt, hat Schande davon.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 9, 8, 'Tadle den Spötter nicht, sonst wird er dich hassen; tadle den Weisen, so wird er dich liebgewinnen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 9, 9, 'Gib dem Weisen, so wird er noch weiser werden; belehre den Gerechten, so wird er an Wissen zunehmen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 9, 10, 'Die Furcht des HERRN ist der Anfang der Weisheit, und die Erkenntnis des heiligen (Gottes) ist Einsicht. –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 9, 11, '»Denn durch mich werden deiner Tage viele werden und die Jahre deines Lebens sich mehren.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 9, 12, 'Wenn du weise bist, so bist du es zu deinem eigenen Besten; bist du aber ein Spötter, so hast du es allein zu tragen.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 9, 13, 'Frau Torheit ist ein leidenschaftliches Geschöpf, die reine Beschränktheit und kennt keine Scham;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 9, 14, 'sie sitzt am Eingang ihres Hauses, auf einem Thron hoch oben in der Stadt,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 9, 15, 'um die des Weges Vorübergehenden einzuladen, alle, die auf ihren Pfaden geradeaus wandeln:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 9, 16, '»Wer einfältig ist, der kehre hier ein!« Und zu den Unverständigen sagt sie:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 9, 17, '»Gestohlenes Wasser ist süß, und heimlich verzehrtes Brot schmeckt köstlich!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 9, 18, 'Und er bedenkt nicht, daß die Totengeister dort hausen, daß in den Tiefen des Totenreichs die von ihr beherbergten Gäste weilen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 10, 1, 'Die Sprüche Salomos. Ein weiser Sohn macht seinem Vater Freude, aber ein törichter Sohn ist seiner Mutter Kummer. –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 10, 2, 'Ungerecht erworbene Schätze bringen keinen Segen, aber Gerechtigkeit errettet vom Tode. –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 10, 3, 'Den Hunger des Frommen läßt der HERR nicht ungestillt, aber die Gier der Gottlosen stößt er zurück. –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 10, 4, 'Wer mit lässiger Hand arbeitet, verarmt, aber die Hand der Fleißigen schafft Reichtum.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 10, 5, 'Wer im Sommer einsammelt, handelt verständig; wer aber in der Erntezeit schläft, handelt schändlich. –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 10, 6, 'Reicher Segen kommt auf das Haupt des Gerechten, aber der Mund der Gottlosen birgt Gewalttat. –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 10, 7, 'Das Andenken des Gerechten bleibt im Segen, aber der Name der Gottlosen vermodert. –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 10, 8, 'Wer weisen Sinnes ist, nimmt Ratschläge an, aber ein närrischer Schwätzer kommt zu Fall. –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 10, 9, 'Wer in Unschuld wandelt, der wandelt sicher; wer aber krumme Wege einschlägt, der wird durchschaut. –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 10, 10, 'Wer mit den Augen blinzelt, verursacht Kränkung, und ein närrischer Schwätzer kommt zu Fall. –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 10, 11, 'Der Mund des Gerechten ist ein Quell des Lebens, aber der Mund der Gottlosen birgt Gewalttat. –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 10, 12, 'Haß ruft Streit hervor, aber die Liebe deckt alle Verfehlungen zu. –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 10, 13, 'Auf den Lippen des Verständigen findet man Weisheit, aber auf den Rücken des Unverständigen gehört der Stock. –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 10, 14, 'Die Weisen halten mit ihrer Erkenntnis zurück, aber der Mund des Toren ist herannahendes Verderben. –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 10, 15, 'Des Reichen Besitz ist für ihn eine feste Burg, aber für die Dürftigen ist ihre Armut ein Unheil. –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 10, 16, 'Der Erwerb des Gerechten dient zum Leben, das Einkommen des Gottlosen zur Sünde. –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 10, 17, 'Wer Zurechtweisung beachtet, befindet sich auf dem Wege zum Leben; wer aber Warnungen unbeachtet läßt, geht irre. –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 10, 18, 'Wer Haß in sich verbirgt, hat Lügenlippen, und wer üble Nachrede verbreitet, ist ein Tor. –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 10, 19, 'Wo viele Worte sind, da geht es ohne Verfehlung nicht ab; wer aber seine Lippen im Zaume hält, handelt klug. –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 10, 20, 'Kostbares Silber ist die Zunge des Gerechten, der Verstand der Gottlosen (aber) ist wenig wert. –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 10, 21, 'Die Lippen des Gerechten schaffen vielen eine Erquickung, aber die Toren gehen durch Unverstand zugrunde. –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 10, 22, 'Der Segen des HERRN ist’s, der reich macht, und neben ihm fügt (eigene) Anstrengung nichts hinzu. –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 10, 23, 'Dem Toren machen Schandtaten Vergnügen, dem verständigen Manne aber die (Betätigung der) Weisheit. –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 10, 24, 'Wovor dem Gottlosen graut, das kommt über ihn; was aber die Gerechten sich wünschen, gewährt er ihnen. –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 10, 25, 'Sobald der Sturmwind daherfährt, ist der Gottlose nicht mehr da, der Gerechte aber ist für die Ewigkeit fest gegründet. –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 10, 26, 'Was der Essig für die Zähne und der Rauch für die Augen, das ist der Faule für den, der ihn ausgesandt hat. –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 10, 27, 'Die Furcht des HERRN verlängert die Lebenstage, aber die Jahre der Gottlosen werden verkürzt. –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 10, 28, 'Das Harren der Gerechten endet in Freude, aber die Hoffnung der Gottlosen wird vereitelt. –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 10, 29, 'Das Walten des HERRN ist eine Schutzwehr für den Unschuldigen, aber ein Schrecken für die Übeltäter. –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 10, 30, 'Der Gerechte wird nimmermehr wanken, aber die Gottlosen werden im Lande nicht wohnen bleiben. –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 10, 31, 'Der Mund des Gerechten läßt Weisheit sprießen, aber die falsche Zunge wird ausgerottet. –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 10, 32, 'Die Lippen des Gerechten verstehen sich auf das, was wohlgefällig ist, aber der Mund der Gottlosen nur auf Verkehrtes.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 11, 1, 'Falsche Waage ist dem HERRN ein Greuel, aber volles Gewicht ist ihm wohlgefällig. –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 11, 2, 'Kommt Übermut, so kommt auch Schande; bei den Bescheidenen aber ist Weisheit. –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 11, 3, 'Die Redlichen leitet ihre Unschuld (sicher), die Treulosen aber richtet ihre Falschheit zugrunde. –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 11, 4, 'Reichtum nützt nichts am Tage des Zorngerichts, Gerechtigkeit aber errettet vom Tode. –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 11, 5, 'Die Gerechtigkeit des Unschuldigen macht seinen Weg eben, doch der Gottlose kommt durch seinen Frevelmut zu Fall. –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 11, 6, 'Die Rechtschaffenen rettet ihre Gerechtigkeit, aber die Treulosen werden durch die eigene Gier gefangen. –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 11, 7, 'Mit dem Tode eines gottlosen Menschen geht jede Hoffnung (für ihn) verloren, und die Erwartung der Ruchlosen wird vereitelt. –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 11, 8, 'Der Gerechte wird aus der Not gerettet, und der Gottlose muß an dessen Platz treten. –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 11, 9, 'Mit dem Munde sucht der Ruchlose seinen Nächsten zugrunde zu richten, aber durch ihre Umsicht retten sich die Gerechten. –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 11, 10, 'Beim Wohlergehen der Gerechten frohlockt die Stadt, und beim Untergang der Gottlosen herrscht Jubel. –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 11, 11, 'Durch den Segen der Rechtschaffenen kommt eine Stadt empor, aber durch den Mund der Gottlosen wird sie niedergerissen. –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 11, 12, 'Wer seinen Nächsten geringschätzig behandelt, ist unverständig, aber ein einsichtsvoller Mann schweigt still. –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 11, 13, 'Wer als Verleumder umhergeht, deckt Geheimnisse auf; wer aber ein treues Herz besitzt, hält die Sache geheim. –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 11, 14, 'Wenn keine umsichtige Leitung da ist, kommt ein Volk zu Fall; gut aber steht’s, wenn Ratgeber in großer Zahl da sind. –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 11, 15, 'Ganz schlimm kann es gehen, wenn man für einen andern Bürgschaft leistet; wer aber Verpflichtungen durch Handschlag meidet, geht sicher. –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 11, 16, 'Ein liebenswürdiges Weib erlangt Ehre (ein häßlicher Schandfleck aber ist eine Frau, die Redlichkeit haßt. Die Faulen bringen es nicht zu Vermögen, die Fleißigen aber erlangen Reichtum). –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 11, 17, 'Ein liebevoller Mensch erweist sich selbst Gutes, der Hartherzige aber schneidet sich selbst ins Fleisch. –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 11, 18, 'Der Gottlose erwirbt nur trügerischen Gewinn, wer aber Gerechtigkeit sät, einen sicheren Lohn. –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 11, 19, 'So gewiß die Gerechtigkeit zum Leben führt, so sicher geht der, welcher dem Bösen nachjagt, zu seinem Tode.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 11, 20, 'Menschen mit falschem Herzen sind dem HERRN ein Greuel; wer aber unsträflich wandelt, gefällt ihm wohl. –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 11, 21, 'Die Hand darauf! Der Böse bleibt nicht ungestraft; aber die Nachkommenschaft der Gerechten kommt wohlbehalten davon. –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 11, 22, 'Ein goldener Ring am Rüssel einer Sau: so ist ein schönes Weib ohne Sittsamkeit. –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 11, 23, 'Das Streben der Gerechten führt zu lauter Glück, aber die Erwartung der Gottlosen zum Zorn. –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 11, 24, 'Mancher teilt mit vollen Händen aus und bekommt immer noch mehr; ein anderer spart über Gebühr und wird dabei nur ärmer. –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 11, 25, 'Eine wohltätige Seele wird reichlich gesättigt, und wer anderen zu trinken gibt, wird selbst getränkt. –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 11, 26, 'Wer Getreide zurückhält, den verfluchen die Leute; aber Segen kommt auf das Haupt dessen, der Getreide verkauft. –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 11, 27, 'Wer sich des Guten befleißigt, ist auf Wohlgefälliges bedacht; wenn aber jemand nach Bösem trachtet, wird es über ihn selbst kommen. –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 11, 28, 'Wer sich auf seinen Reichtum verläßt, der wird verwelken; die Gerechten aber werden grünen wie junges Laub. –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 11, 29, 'Wer sein eigenes Hauswesen vernachlässigt, wird Wind zum Besitz erhalten, und der Tor wird ein Knecht dessen, der weisen Sinnes ist. –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 11, 30, 'Die Frucht des Rechttuns ist ein Baum des Lebens, aber Gewalttätigkeit nimmt das Leben. –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 11, 31, 'Siehe, der Gerechte erhält schon auf Erden seinen Lohn: wieviel mehr der Gottlose und der Sünder!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 12, 1, 'Wer Zurechtweisung liebt, liebt Erkenntnis; wer aber die Rüge haßt, ist ein Dummkopf. –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 12, 2, 'Der Gute erlangt Wohlgefallen beim HERRN, aber einen tückischen Menschen verdammt er. –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 12, 3, 'Keiner gelangt durch Gottlosigkeit zu festem Bestand, aber die Wurzel der Frommen bleibt unerschüttert. –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 12, 4, 'Ein braves Weib ist ihres Gatten Krone, ein nichtsnutziges aber ist wie Wurmfraß in seinen Gebeinen. –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 12, 5, 'Die Gedanken der Gerechten gehen auf das, was recht ist, aber die Anschläge der Gottlosen auf Trug. –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 12, 6, 'Die Reden der Gottlosen sind ein Lauern auf Blutvergießen, aber der Mund der Rechtschaffenen errettet sie. –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 12, 7, 'Die Gottlosen werden umgestürzt und sind nicht mehr, aber das Haus der Gerechten bleibt bestehen. –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 12, 8, 'Nach dem Maß seiner Einsicht wird ein jeder gelobt; wer aber verkehrten Sinnes ist, fällt der Verachtung anheim. –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 12, 9, 'Besser gering sein und sich selbst bedienen, als vornehm tun und nichts zu essen haben. –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 12, 10, 'Der Gerechte weiß, wie seinem Vieh zumute ist; aber das Herz der Gottlosen ist gefühllos. –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 12, 11, 'Wer seinen Acker bestellt, wird satt zu essen haben; wer aber nichtigen Dingen nachjagt, ist unverständig. –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 12, 12, 'Es gelüstet den Gottlosen nach dem Raube der Bösen, aber die Wurzel der Gerechten schlägt aus. –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 12, 13, 'In der Verfehlung der Lippen liegt ein böser Fallstrick, der Gerechte aber entgeht dem Unheil. –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 12, 14, 'An den Folgen seiner Reden hat jeder sattsam zu kauen, und was die Hände eines Menschen schaffen, das wird ihm vergolten. –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 12, 15, 'Dem Toren dünkt sein Weg der richtige zu sein, aber der Weise hört auf Ratschläge. –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 12, 16, 'Ein Tor ist, wer seinen Ärger auf der Stelle merken läßt; der Kluge dagegen läßt die Schmähung unbeachtet. –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 12, 17, 'Wer die Wahrheit aussagt, tut Gerechtigkeit kund, ein falscher Zeuge aber Trug. –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 12, 18, 'Es gibt Menschen, deren Geschwätz wie Schwertstiche durchbohrt; aber die Zunge der Weisen schafft Heilung. –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 12, 19, 'Wahrhaftige Lippen bestehen ewiglich, aber Lügenzungen nur für einen Augenblick. –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 12, 20, 'Trug wohnt im Herzen derer, die auf Böses sinnen; die aber Heilsames planen, erleben Freude. –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 12, 21, 'Dem Gerechten widerfährt keinerlei Unheil, die Gottlosen aber trifft Unglück in Fülle. –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 12, 22, 'Lügenlippen sind dem HERRN ein Greuel; wer aber die Wahrheit übt, gefällt ihm wohl. –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 12, 23, 'Ein kluger Mensch hält mit seinem Wissen zurück, aber das Herz der Toren schreit Narrheit aus. –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 12, 24, 'Die Fleißigen werden als Meister tätig sein, die Trägen aber müssen Zwangsarbeit verrichten. –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 12, 25, 'Kummer im Herzen drückt einen Menschen nieder, aber ein freundliches Wort heitert ihn auf. –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 12, 26, 'Der Gerechte weist seinem Genossen den rechten Weg, aber die Gottlosen führt ihr Weg in die Irre. –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 12, 27, 'Nicht erjagt der Lässige sein Wild, aber einem fleißigen Menschen wird wertvolles Gut zuteil. –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 12, 28, 'Auf dem Pfade der Gerechtigkeit ist Leben, der Weg des Frevels aber führt zum Tode.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 13, 1, 'Ein weiser Sohn nimmt die Zurechtweisung des Vaters an, aber ein Spötter hört nicht auf Scheltreden. –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 13, 2, 'Die Frucht des Rechttuns bekommt der Gute zu genießen, das Verlangen der Treulosen aber ist auf Gewalttat gerichtet. –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 13, 3, 'Wer seinen Mund hütet, wahrt seine Seele; wer aber seine Lippen aufsperrt, dem schlägt es zum Verderben aus. –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 13, 4, 'Das Herz des Trägen hegt viele Wünsche, jedoch erfolglos; aber das Verlangen der Fleißigen wird reichlich befriedigt. –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 13, 5, 'Der Gerechte haßt Lug und Trug, aber der Gottlose handelt schändlich und nichtswürdig. –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 13, 6, 'Die Gerechtigkeit behütet die unsträflich Wandelnden, Gottlosigkeit aber bringt die Sünder zu Fall. –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 13, 7, 'Mancher stellt sich reich und hat doch gar nichts; mancher, der sich arm stellt, besitzt ein großes Vermögen. –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 13, 8, 'Lösegeld für das Leben ist manchem sein Reichtum, doch ein Armer bekommt keine Drohung zu hören. –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 13, 9, 'Das Licht der Gerechten brennt lustig, aber die Leuchte der Gottlosen erlischt. –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 13, 10, 'Bei Übermut gibt es nichts als Streit, aber bei denen, die sich raten lassen, ist Weisheit. –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 13, 11, 'Mühelos erlangtes Vermögen zerrinnt; wer aber händeweis sammelt, der gewinnt immer mehr. –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 13, 12, 'Lange hingezogene Hoffnung macht das Herz krank, ein erfüllter Wunsch aber ist ein Baum des Lebens. –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 13, 13, 'Wer das Wort (Gottes) verachtet, verschuldet sich ihm gegenüber; wer aber das Gebot (Gottes) in Ehren hält, dem wird’s vergolten. –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 13, 14, 'Die Belehrung des Weisen ist ein Born des Lebens, so daß man den Schlingen des Todes fern bleibt. –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 13, 15, 'Gute Einsicht verschafft Anerkennung, aber der Treulosen Weg ist steinhart. –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 13, 16, 'Alles vollführt der Kluge mit Überlegung, aber ein Tor kramt Dummheit aus. –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 13, 17, 'Ein gottloser Gesandter richtet Unheil an, aber ein treuer Bote bringt Heilung. –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 13, 18, 'Armut und Schande treffen den, der Zurechtweisung verschmäht; wer aber Zurechtweisung beachtet, kommt zu Ehren. –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 13, 19, 'Die Erfüllung eines Wunsches tut dem Herzen wohl, aber ein Greuel ist es den Toren, vom Bösen abzulassen. –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 13, 20, 'Wer mit Weisen umgeht, wird weise; wer sich aber zu den Toren gesellt, dem ergeht es übel. –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 13, 21, 'Die Sünder verfolgt das Unglück, aber die Gerechten belohnt (Gott) mit Gutem. –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 13, 22, 'Der Gute vererbt seinen Besitz auf Kindeskinder, aber der Reichtum des Sünders ist den Gerechten vorbehalten. –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 13, 23, 'Reichliche Nahrung gewährt der Neubruch der Armen; aber mancher (Besitz) geht durch Unredlichkeit verloren. –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 13, 24, 'Wer seine Rute schont, der haßt sein Kind; wer es aber lieb hat, läßt es früh die Züchtigung fühlen. –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 13, 25, 'Der Gerechte hat zu essen, bis er seinen Hunger gestillt hat; aber der Magen der Gottlosen muß darben.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 14, 1, 'Frau Weisheit baut ihr Haus auf, aber Frau Torheit reißt es mit eigenen Händen nieder. –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 14, 2, 'Wer in seiner Redlichkeit wandelt, fürchtet den HERRN; wer aber krumme Wege geht, verachtet ihn. –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 14, 3, 'Im Munde des Narren ist eine Rute für seinen Hochmut, aber dem Weisen dienen seine Lippen zum Schutz. –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 14, 4, 'Wo keine Ochsen sind, bleibt die Krippe rein, aber reicher Ertrag kommt durch die Kraft von Pflugstieren. –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 14, 5, 'Ein wahrhaftiger Zeuge lügt nicht, aber ein falscher Zeuge trägt Lügen vor. –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 14, 6, 'Der Spötter sucht Weisheit, ohne sie zu finden; aber für den Verständigen ist die Erkenntnis etwas Leichtes. –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 14, 7, 'Gehe von einem törichten Menschen weg, denn du lernst da nichts von einsichtsvollen Lippen kennen. –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 14, 8, 'Die Weisheit des Klugen besteht darin, daß er auf seinen Weg acht gibt; aber die Narrheit der Toren ist Enttäuschung für sie selbst. –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 14, 9, 'Der Toren spottet das Schuldopfer; aber unter Rechtschaffenen herrscht gutes Einvernehmen. –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 14, 10, 'Das Herz allein kennt seinen Kummer, und auch in seine Freude kann sich kein Fremder mischen. –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 14, 11, 'Das Haus der Gottlosen wird zerstört werden, das Zelt der Rechtschaffenen aber wird in Blüte stehen. –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 14, 12, 'Mancher Weg erscheint einem Menschen gerade, aber das Ende davon sind Wege des Todes. –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 14, 13, 'Sogar beim Lachen kann das Herz Kummer empfinden, und das Ende der Freude ist (oft) Traurigkeit. –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 14, 14, 'Den Lohn für seine Wege bekommt der zu schmecken, dessen Herz abtrünnig ist, und ebenso ein guter Mensch für seine Handlungen. –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 14, 15, 'Der Einfältige glaubt jedem Wort, der Kluge aber gibt auf seine Schritte acht. –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 14, 16, 'Der Weise ist vorsichtig und meidet das Böse, der Tor aber ereifert sich und ist sorglos. –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 14, 17, 'Der Jähzornige richtet Torheit an, ein besonnener Mensch aber bleibt ruhig. –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 14, 18, 'Die Einfältigen eignen sich Dummheit an, die Klugen aber werden mit Erfahrung gekrönt. –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 14, 19, 'Die Bösen müssen sich vor den Guten verneigen und die Gottlosen an den Türen des Gerechten stehen. –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 14, 20, 'Sogar seinem Freunde ist der Arme widerwärtig; aber derer, die den Reichen lieben, sind viele. –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 14, 21, 'Wer seinen Nächsten verächtlich behandelt, versündigt sich; wer sich aber der Unglücklichen erbarmt: Heil ihm! –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 14, 22, 'Wahrlich, wer auf Böses sinnt, wird irre gehen; aber Liebe und Vertrauen erntet, wer gute Absichten hegt. –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 14, 23, 'Bei jeder sauren Arbeit kommt ein Gewinn heraus, aber leeres Geschwätz bringt nur Verlust. –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 14, 24, 'Für weise Menschen ist ihr Reichtum eine Krone, der Kranz der Toren aber ist die Torheit. –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 14, 25, 'Ein wahrhaftiger Zeuge ist ein Lebensretter; wer aber Lügen ausspricht, ist ein falscher Zeuge. –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 14, 26, 'In der Gottesfurcht liegt eine starke Sicherheit, und auch die Kinder eines solchen haben darin eine Zuflucht. –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 14, 27, 'Die Gottesfurcht ist ein Born des Lebens, um den Schlingen des Todes zu entgehen. –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 14, 28, 'Auf der Menge des Kriegsvolks beruht das Ansehen eines Königs; aber der Mangel an Kriegsmannschaft führt den Sturz eines Fürsten herbei. –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 14, 29, 'Ein Geduldiger beweist viel Einsicht, aber ein Jähzorniger treibt die Torheit auf die Spitze. –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 14, 30, 'Ein gelassenes Herz ist des Leibes Leben, aber Leidenschaftlichkeit ist wie Wurmfraß in den Gebeinen. –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 14, 31, 'Wer den Geringen bedrückt, beschimpft den, der ihn geschaffen hat; wer sich aber des Armen erbarmt, erweist jenem Ehre. –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 14, 32, 'Durch seine Bosheit wird der Gottlose gestürzt; aber der Gerechte bleibt auch im Tode noch getrost. –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 14, 33, 'Im Herzen des Verständigen ruht die Weisheit verschlossen; was aber im Inneren der Toren ist, gibt sich kund. –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 14, 34, 'Gerechtigkeit erhöht ein Volk, aber die Sünde ist die Schmach der Völker. –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 14, 35, 'Des Königs Gunst wird dem klugen Diener zuteil, aber einen unbrauchbaren wird sein Ingrimm treffen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 15, 1, 'Eine sanfte Antwort beschwichtigt den Grimm, aber ein kränkendes Wort ruft Zorn hervor. –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 15, 2, 'Die Zunge der Weisen träufelt Erkenntnis (aus), aber der Mund der Toren sprudelt Dummheit hervor. –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 15, 3, 'An jedem Orte sind die Augen des HERRN, sie schauen auf die Bösen und auf die Guten. –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 15, 4, 'Sanftheit der Zunge ist ein Baum des Lebens, aber Verkehrtheit an ihr schlägt dem Herzen Wunden. –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 15, 5, 'Ein Tor verschmäht die Zucht seines Vaters; wer aber Zurechtweisung annimmt, wird klug. –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 15, 6, 'Das Haus des Gerechten ist eine große Schatzkammer, aber im Einkommen des Gottlosen herrscht Zerrüttung. –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 15, 7, 'Die Lippen der Weisen streuen Erkenntnis aus, aber der Toren Sinn ist verkehrt gerichtet. –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 15, 8, 'Das Opfer der Gottlosen ist dem HERRN ein Greuel, aber das Gebet der Aufrichtigen ist ihm wohlgefällig. –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 15, 9, 'Der Wandel des Gottlosen ist dem HERRN ein Greuel; wer aber der Gerechtigkeit nachjagt, den hat er lieb. –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 15, 10, 'Schwere Züchtigung erwartet den, der den rechten Weg verläßt; wer Zurechtweisung verschmäht, wird sterben. –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 15, 11, 'Unterwelt und Abgrund liegen offen vor dem HERRN: um wieviel mehr die Herzen der Menschenkinder! –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 15, 12, 'Der Spötter hat es nicht gern, daß man ihn zurechtweist; (darum) mag er sich nicht zu den Weisen gesellen. –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 15, 13, 'Ein fröhliches Herz macht das Angesicht heiter, aber bei Bekümmernis des Herzens ist der Mut gebrochen. –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 15, 14, 'Das Herz des Verständigen trachtet nach Erkenntnis, aber der Mund der Toren geht auf Dummheit aus. –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 15, 15, 'Alle Lebenstage sind für den Unglücklichen trübselig, aber ein wohlgemuter Sinn ist wie ein beständiges Festmahl. –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 15, 16, 'Besser wenig (Habe) bei Gottesfurcht, als reiche Schätze und Unruhe dabei. –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 15, 17, 'Besser ein Gericht Gemüse und Liebe dabei, als ein gemästeter Ochs und Haß dabei. –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 15, 18, 'Ein zornmütiger Mensch ruft Streit hervor, aber ein langmütiger beschwichtigt den Hader. –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 15, 19, 'Der Weg des Faulen ist wie mit Dornen verzäunt, aber der Pfad der Fleißigen ist ebene Bahn. –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 15, 20, 'Ein weiser Sohn ist seines Vaters Freude, aber ein törichter Mensch verachtet seine Mutter. –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 15, 21, 'Die Torheit ist dem Unverständigen eine Freude, ein verständiger Mensch aber geht seinen Weg geradeaus. –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 15, 22, 'Wo keine Beratung stattfindet, da mißlingen die Pläne; wo aber viele Ratgeber sind, da kommen sie zustande. –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 15, 23, 'Freude hat jeder an der (treffenden) Antwort seines Mundes, und ein Wort zu rechter Zeit – wie wertvoll ist das! –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 15, 24, 'Der Weg des Lebens geht für den Einsichtigen aufwärts, damit er dem Totenreich drunten fernbleibe. –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 15, 25, 'Das Haus der Hochmütigen reißt der HERR nieder, aber die Grenze der Witwe legt er fest. –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 15, 26, 'Boshafte Anschläge sind dem HERRN ein Greuel, aber leutselige Worte sind (ihm) rein. –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 15, 27, 'Wer unrechtmäßigen Gewinn macht, zerrüttet sein (eigenes) Haus; wer aber Bestechungsgeschenke haßt, wird leben. –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 15, 28, 'Das Herz des Gerechten überlegt, um eine Antwort zu geben; aber der Mund der Gottlosen sprudelt Bosheiten hervor. –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 15, 29, 'Von den Gottlosen bleibt der HERR fern, aber das Gebet der Gerechten vernimmt er. –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 15, 30, 'Ein freundlicher Blick erfreut das Herz; eine gute Botschaft erquickt Mark und Bein. –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 15, 31, 'Ein Ohr, das auf heilsame Zurechtweisung hört, weilt gern im Kreise der Weisen. –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 15, 32, 'Wer Unterweisung verschmäht, mißachtet (das Heil) seiner Seele; wer aber auf Zurechtweisung hört, erwirbt sich Einsicht. –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 15, 33, 'Die Furcht des HERRN ist Unterweisung zur Weisheit, und vor der Ehre geht die Demut her.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 16, 1, 'Dem Menschen gehören die Entwürfe des Herzens an, aber vom HERRN kommt das, was die Zunge ausspricht. –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 16, 2, 'Einem Menschen erscheint alles rein, was er unternimmt; aber der HERR wägt die Geister. –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 16, 3, 'Befiehl dem HERRN deine Werke, dann werden deine Pläne gelingen. –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 16, 4, 'Alles hat der HERR für einen bestimmten Zweck geschaffen, so auch den Gottlosen für den Tag des Unglücks. –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 16, 5, 'Jeder Hochmütige ist dem HERRN ein Greuel: die Hand darauf! Ein solcher wird nicht ungestraft bleiben. –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 16, 6, 'Durch Liebe und Treue wird Verschuldung gesühnt, aber durch Gottesfurcht hält man sich vom Bösen fern. –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 16, 7, 'Wenn das Verhalten jemandes dem HERRN wohlgefällt, so söhnt er sogar seine Feinde mit ihm aus. –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 16, 8, 'Besser wenig mit Gerechtigkeit, als ein großes Einkommen mit Unrecht. –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 16, 9, 'Des Menschen Herz erdenkt sich seinen Weg, der HERR aber lenkt seine Schritte. –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 16, 10, 'Ein Gottesurteil liegt auf den Lippen des Königs: beim Rechtsprechen verfehlt sich sein Mund nicht. –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 16, 11, '[Richtige] Waage und Waagschalen sind Gottes Sache; sein Werk sind alle Gewichtstücke im Beutel. –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 16, 12, 'Das Verüben von Freveltaten ist den Königen ein Greuel; denn nur durch Gerechtigkeit steht ein Thron fest. –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 16, 13, 'Wahrhaftige Lippen gefallen dem Könige wohl, und wer aufrichtig redet, den liebt er. –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 16, 14, 'Des Königs Zorn gleicht Todesboten, aber ein weiser Mann besänftigt diesen (Zorn). –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 16, 15, 'Im freundlichen Blick des Königs liegt Leben, und seine Huld ist wie eine Regenwolke des Spätregens. –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 16, 16, 'Weisheit zu erwerben ist viel besser als Gold, und Einsicht zu erwerben ist wertvoller als Silber. –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 16, 17, 'Die Bahn der Rechtschaffenen ist darauf gerichtet, sich vom Bösen fernzuhalten; wer auf seinen Wandel achtgibt, behütet seine Seele. –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 16, 18, 'Hochmut kommt vor dem Fall und hoffärtiger Sinn vor dem Sturz. –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 16, 19, 'Besser ist es, demütig zu sein mit den Niedrigen, als Beute zu teilen mit den Stolzen. –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 16, 20, 'Wer auf das Wort (Gottes) achtet, wird Segen davon haben, und wer auf den HERRN vertraut: wohl ihm! –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 16, 21, 'Wer weisen Herzens ist, der wird mit Recht verständig genannt, doch Süßigkeit der Lippen fördert noch die Belehrung. –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 16, 22, 'Ein Born des Lebens ist die Einsicht für ihren Besitzer; für die Toren aber ist die Torheit eine Strafe. –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 16, 23, 'Der Verstand des Weisen macht seinen Mund klug und mehrt auf seinen Lippen die Belehrung. –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 16, 24, 'Honigseim sind freundliche Worte, süß für die Seele und gesund für den Leib. –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 16, 25, 'Mancher Weg erscheint dem Menschen gerade und ist schließlich doch ein Weg zum Tode. –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 16, 26, 'Der Hunger des Arbeiters fördert seine Arbeit, denn sein (hungriger) Mund treibt ihn dazu an. –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 16, 27, 'Ein nichtswürdiger Mensch gräbt Unheilsgruben, und auf seinen Lippen ist’s wie brennendes Feuer. –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 16, 28, 'Ein ränkesüchtiger Mensch richtet Unfrieden an, und ein Ohrenbläser entzweit vertraute Freunde. –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 16, 29, 'Ein gewalttätiger Mensch beschwatzt seinen Genossen und führt ihn auf einen unheilvollen Weg. –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 16, 30, 'Wer seine Augen zukneift, will Arglist ersinnen; wer seine Lippen zusammenpreßt, hat Bosheit vollbracht. –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 16, 31, 'Graues Haar ist eine Ehrenkrone; auf dem Wege der Gerechtigkeit wird sie erlangt. –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 16, 32, 'Besser ein Langmütiger als ein Kriegsheld, und besser einer, der sich selbst beherrscht, als ein Städteeroberer. –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 16, 33, 'Im Bausch (des Gewandes) wirft man das Los, aber alle seine Entscheidung kommt vom HERRN.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 17, 1, 'Besser ein Stück trocknes Brot und Ruhe dabei, als ein Haus voll Fleisch mit Unfrieden. –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 17, 2, 'Ein kluger Knecht wird Herr über einen nichtsnutzigen Haussohn werden und sich inmitten der Brüder in die Erbschaft teilen. –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 17, 3, 'Der Schmelztiegel ist für das Silber und der Ofen für das Gold; der aber die Herzen prüft, ist der HERR. –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 17, 4, 'Ein Bösewicht horcht auf unheilstiftende Lippen, ein Betrüger leiht verderbenbringenden Zungen sein Ohr. –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 17, 5, 'Wer den Armen verspottet, schmäht dessen Schöpfer, und wer sich über Unglück freut, wird nicht ungestraft bleiben. –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 17, 6, 'Die Krone der Alten sind Kindeskinder, und der Kinder Stolz sind ihre Väter. –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 17, 7, 'Selbstbewußte Rede kommt einem Toren nicht zu, noch viel weniger einem Edlen Lügensprache. –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 17, 8, 'Ein Bestechungsgeschenk erscheint dem, der es empfängt, als ein Zauberstein: überall, wohin es gelangt, hat es Erfolg. –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 17, 9, 'Wer Liebe sucht, deckt Verfehlungen zu; wer aber eine Sache immer wieder aufrührt, entzweit vertraute Freunde. –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 17, 10, 'Ein Verweis macht bei einem Verständigen tieferen Eindruck als hundert Stockschläge bei einem Toren. –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 17, 11, 'Nur auf (eigenes) Unheil ist der Empörer bedacht, denn ein unbarmherziger Bote wird gegen ihn gesandt werden. –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 17, 12, 'Eine ihrer Jungen beraubte Bärin möge (immerhin) jemandem begegnen, aber nur nicht ein Tor mit seinem Unverstand! –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 17, 13, 'Wer Gutes mit Bösem vergilt, aus dessen Hause wird das Unglück nicht weichen. –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 17, 14, 'Der Anfang eines Zankes ist so, wie wenn man Wasser ausbrechen läßt; (darum) laß vom Streit ab, ehe er zum Ausbruch kommt! –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 17, 15, 'Wer den Schuldigen freispricht und wer den Unschuldigen verurteilt, die sind alle beide dem HERRN ein Greuel. –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 17, 16, 'Wozu doch Geld in der Hand des Toren? Er könnte Weisheit kaufen, doch ihm fehlt der Verstand dazu. –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 17, 17, 'Zu jeder Zeit beweist der (wahre) Freund Liebe und wird als Bruder für die Zeit der Not geboren. –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 17, 18, 'Ein unverständiger Mensch ist, wer durch Handschlag sich verpflichtet, wer einem andern gegenüber Bürgschaft leistet. –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 17, 19, 'Wer Streit liebt, liebt Versündigung; wer seine Tür hoch baut, will den Einsturz. –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 17, 20, 'Wer falschen Herzens ist, erlangt kein Glück; und wer eine verlogene Zunge hat, gerät ins Unglück. –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 17, 21, 'Wer einen Toren zum Sohn hat, der hat Kummer davon, und der Vater eines Narren erlebt keine Freude. –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 17, 22, 'Ein fröhlicher Sinn befördert die Genesung, aber ein bedrücktes Gemüt läßt die Gebeine verdorren. –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 17, 23, 'Der Gottlose nimmt Geschenke aus dem Bausch jemandes an, um den Gang des Rechts zu beugen. –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 17, 24, 'Der Verständige hat die Weisheit vor seinen Augen schweben, aber die Augen des Toren schweifen am Ende der Erde umher. –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 17, 25, 'Ein törichter Sohn ist ein Kummer für seinen Vater und ein bitteres Weh für die (Mutter), die ihn geboren. –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 17, 26, 'Schon eine Geldstrafe einem Unschuldigen aufzuerlegen ist vom Übel; Edle aber zu schlagen ist ganz ungebührlich. –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 17, 27, 'Wer mit seinen Worten an sich hält, besitzt Einsicht, und der Kaltblütige ist ein verständiger Mann. –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 17, 28, 'Selbst ein Tor kann, wenn er schweigt, als weise gelten und, wenn er seine Lippen verschließt, als einsichtsvoll.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 18, 1, 'Der Sonderling geht dem eigenen Gelüsten nach; er kämpft gegen alles an, was frommt. –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 18, 2, 'Dem Toren ist es nicht um Einsicht zu tun, sondern nur um die Kundmachung seiner Gedanken. –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 18, 3, 'Wo Gottlosigkeit verübt wird, da stellt sich auch Verachtung ein, und mit der Schandtat kommt die Schmach. –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 18, 4, 'Tiefe Wasser sind die Worte aus dem Munde manches Mannes, ein sprudelnder Bach, ein Born der Weisheit. –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 18, 5, 'Es ist ein übel Ding, Partei für den Schuldigen zu nehmen, so daß man den, der recht hat, im Gericht unterliegen läßt. –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 18, 6, 'Die Lippen des Toren führen Streit herbei, und sein Mund ruft nach Stockschlägen. –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 18, 7, 'Dem Toren bringt sein Mund Verderben, und seine Lippen werden zum Fallstrick für sein Leben. –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 18, 8, 'Die Worte des Ohrenbläsers sind wie Leckerbissen, die in das Innerste des Leibes hinabgleiten. –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 18, 9, 'Schon wer sich lässig bei seiner Arbeit zeigt, ist ein Bruder dessen, der (sein Vermögen) zugrunde richtet. –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 18, 10, 'Ein fester Turm ist der Name des HERRN; in diesen flüchtet sich der Gerechte und ist in Sicherheit. –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 18, 11, 'Das Vermögen des Reichen ist für ihn eine feste Burg und gleich einer hohen Mauer – in seiner Einbildung. –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 18, 12, 'Vor dem Sturz ist das Herz eines Menschen hochmütig, aber vor der Ehre schreitet die Demut einher. –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 18, 13, 'Wenn jemand Antwort gibt, ehe er (recht) gehört hat, so gilt ihm das als Unverstand und Schande. –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 18, 14, 'Ein männlicher Mut erträgt sein Leiden; aber ein bedrücktes Gemüt – wer kann das ertragen? –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 18, 15, 'Ein verständiges Herz erwirbt Weisheit, und das Ohr des Weisen trachtet nach Erkenntnis. –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 18, 16, 'Geschenke öffnen einem Menschen Tür und Tor und verschaffen ihm Zutritt zu den Großen. –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 18, 17, 'Recht hat, wer als der erste in einer Streitsache auftritt; wenn dann aber der andere kommt, so widerlegt er ihn. –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 18, 18, 'Das Los schlichtet Streitigkeiten und entscheidet zwischen Starken. –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 18, 19, 'Ein Bruder, gegen den man treulos gehandelt hat, leistet stärkeren Widerstand als eine feste Stadt, und Zerwürfnisse sind wie der Riegel einer Burg. –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 18, 20, 'Jeder bekommt die Frucht seines Mundes sattsam zu schmecken: den Ertrag seiner Lippen muß er auskosten. –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 18, 21, 'Tod und Leben stehen in der Gewalt der Zunge, und wer sie viel gebraucht, wird das, was sie anrichtet, zu schmecken bekommen. –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 18, 22, 'Wer ein (gutes) Eheweib gefunden, hat etwas Vortreffliches gefunden und ein Gnadengeschenk vom HERRN erhalten. –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 18, 23, 'Unterwürfige Bitten spricht der Arme aus, aber der Reiche antwortet mit Härte. –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 18, 24, 'Gar manche Freunde gereichen zum Verderben; doch mancher Freund ist anhänglicher als ein Bruder.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 19, 1, 'Besser ein Armer, der in seiner Unschuld wandelt, als wer unehrliche Lippen hat und dabei reich ist. –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 19, 2, 'Schon bei sich selbst gar nicht zu überlegen ist verfehlt; wer sich aber überstürzt, tritt fehl. –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 19, 3, 'Des Menschen eigene Torheit läßt seine Unternehmungen mißlingen; aber alsdann grollt sein Herz gegen den HERRN. –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 19, 4, 'Reichtum verschafft Freunde in großer Zahl; wer aber arm ist, sieht sich von seinem Freunde verlassen. –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 19, 5, 'Ein falscher Zeuge bleibt nicht ungestraft; und wer Lügen vorbringt, wird (der Strafe) nicht entrinnen. –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 19, 6, 'Viele umschmeicheln einen Vornehmen, und alle Welt ist einem freigebigen Menschen zugetan. –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 19, 7, 'Den Armen hassen alle seine Brüder; erst recht ziehen sich seine Freunde von ihm zurück. Wer Worten nachjagt, dem dienen sie zu nichts. –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 19, 8, 'Wer Verstand erwirbt, liebt sein Leben; wer Einsicht bewahrt, wird Segen davon haben. –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 19, 9, 'Ein falscher Zeuge bleibt nicht ungestraft, und wer Lügen vorbringt, geht zugrunde. –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 19, 10, 'Wohlleben kommt keinem Toren zu; geschweige denn einem Sklaven, über Fürsten zu herrschen. –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 19, 11, 'Die Einsicht eines Menschen zeigt sich in seiner Langmut, und ein Ruhm ist es für ihn, Verfehlungen zu verzeihen. –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 19, 12, 'Des Königs Groll ist wie das Knurren eines Löwen, dagegen seine Gunst wie Tau auf Pflanzen. –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 19, 13, 'Ein törichter Sohn ist ein Unglück für seinen Vater, und ein zänkisches Weib ist wie eine stets rinnende Dachtraufe. –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 19, 14, 'Haus und Habe erbt man von den Vätern, aber ein verständiges Weib ist eine Gabe vom HERRN. –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 19, 15, 'Faulheit versenkt in tiefen Schlaf, und ein lässiger Mensch muß Hunger leiden. –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 19, 16, 'Wer das Gebot (Gottes) beachtet, der bewahrt sein Leben; wer dagegen das Wort (Gottes) verachtet, wird sterben. –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 19, 17, 'Wer sich des Armen erbarmt, gibt dem HERRN ein Darlehen; und der wird ihm sein Wohltun vergelten. –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 19, 18, 'Züchtige deinen Sohn, weil noch Hoffnung (auf Besserung) vorhanden ist, und laß dir nicht in den Sinn kommen, ihn zu töten. –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 19, 19, 'Wer jähzornig ist, muß eine Geldbuße zahlen, denn greifst du auch wehrend ein, so machst du’s nur noch schlimmer. –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 19, 20, 'Höre auf guten Rat und nimm Zurechtweisung an, damit du in Zukunft klug wirst. –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 19, 21, 'Vielerlei Pläne sind im Herzen eines Menschen, aber der Ratschluß des HERRN, der wird zustande kommen. –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 19, 22, 'Die Bereitwilligkeit eines Menschen ist für seine Liebesbetätigung bestimmend, und besser ist ein Armer als ein Lügner. –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 19, 23, 'Die Gottesfurcht führt zum Leben; so kann man nachts gesättigt schlafen und wird von keinem Unglück heimgesucht. –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 19, 24, 'Hat der Faule seine Hand in die Eßschüssel gesteckt, so mag er sie nicht einmal zu seinem Munde zurückbringen. –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 19, 25, 'Schlägst du den Spötter, so wird der Unverständige dadurch klug; und weist man den Verständigen zurecht, so läßt er es sich zur Lehre dienen. –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 19, 26, 'Wer den Vater mißhandelt, die Mutter aus dem Hause jagt, ist ein schändlicher und nichtsnutziger Sohn. –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 19, 27, 'Laß ab, mein Sohn, auf Zurechtweisung zu hören, wenn du doch von den Lehren der Weisheit abweichen willst. –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 19, 28, 'Ein gewissenloser Zeuge verhöhnt das Recht, und der Mund der Gottlosen sprudelt Unheil hervor. –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 19, 29, 'Für die Spötter sind Strafgerichte bereit, und Schläge für den Rücken der Toren.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 20, 1, 'Der Wein ist ein Spötter, der Rauschtrank ein Lärmmacher, und keiner, der von ihm taumelt, ist weise. –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 20, 2, 'Des Königs Drohen ist wie das Knurren eines Löwen; wer ihn zum Zorn reizt, frevelt gegen sein Leben. –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 20, 3, 'Ehrenvoll ist es für den Mann, vom Streit fernzubleiben; jeder Narr aber fängt Händel an. –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 20, 4, 'Mit Eintritt des Herbstes mag der Faule nicht pflügen; wenn er dann in der Erntezeit (nach Früchten) verlangt, so ist nichts da. –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 20, 5, 'Ein tiefes Wasser sind die Pläne im Herzen eines Menschen, aber ein kluger Mann weiß sie doch zu schöpfen. –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 20, 6, 'Viele Menschen werden gütige Leute genannt, aber einen wirklich treuen Mann – wer findet den? –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 20, 7, 'Wer in seiner Unsträflichkeit als gerechter Mann wandelt: wohl seinen Kindern nach ihm! –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 20, 8, 'Ein König, der auf dem Richterstuhl sitzt, macht, mit seinen Augen sichtend, alles Böse ausfindig. –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 20, 9, 'Wer darf sagen: »Ich habe mein Herz unbefleckt erhalten, ich bin rein von Sünde geblieben«? –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 20, 10, 'Zweierlei Gewicht und zweierlei Maß, die sind alle beide dem HERRN ein Greuel. –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 20, 11, 'Schon ein Kind gibt durch sein Tun zu erkennen, ob seine Sinnesart lauter und aufrichtig ist. –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 20, 12, 'Ein hörendes Ohr und ein sehendes Auge, die hat der HERR alle beide geschaffen. –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 20, 13, 'Liebe den Schlaf nicht, sonst verarmst du; halte die Augen offen, so wirst du satt zu essen haben. –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 20, 14, '»Schlecht, schlecht!« sagt der Käufer; wenn er aber weggeht, dann lacht er sich ins Fäustchen. –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 20, 15, 'Mögen auch Gold und Korallen in Fülle vorhanden sein: das kostbarste Gerät sind doch einsichtsvolle Lippen. –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 20, 16, 'Nimm ihm seinen Rock, denn er hat für einen andern gebürgt; um fremder Leute willen pfände ihn aus. –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 20, 17, 'Süß schmeckt dem Menschen das durch Betrug erworbene Brot, hinterdrein aber hat er den Mund voll Kies. –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 20, 18, 'Pläne kommen durch Beratschlagung zustande; darum führe Krieg (nur) mit kluger Überlegung. –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 20, 19, 'Geheimnisse verrät, wer als Verleumder umhergeht; darum laß dich nicht ein mit einem, der seine Lippen aufsperrt. –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 20, 20, 'Wer seinem Vater und seiner Mutter flucht, dessen Leuchte wird zur Zeit tiefster Finsternis erlöschen. –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 20, 21, 'Ein Besitz, den man mit Überstürzung gleich im Anfang erlangt hat, wird schließlich ungesegnet sein. –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 20, 22, 'Sage nicht: »Ich will das Böse vergelten!« Harre auf den HERRN, so wird er dir helfen. –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 20, 23, 'Zweierlei Gewichtsteine sind dem HERRN ein Greuel, und falsche Waage ist ein übel Ding. –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 20, 24, 'Vom HERRN hängen die Schritte eines jeden ab; der Mensch aber – was versteht der von seinem Wege? –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 20, 25, 'Ein Fallstrick ist es für den Menschen, unbesonnen auszusprechen: »Geweiht!« und erst nach dem Geloben zu überlegen. –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 20, 26, 'Ein weiser König macht die Frevler ausfindig und läßt den Dreschwagen über sie hingehen. –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 20, 27, 'Eine vom HERRN verliehene Leuchte ist der Geist des Menschen: er durchforscht alle Kammern des Leibes. –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 20, 28, 'Liebe und Treue beschirmen den König, und durch Liebe stützt er seinen Thron. –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 20, 29, 'Der Jünglinge Ruhm ist ihre Kraft, und der Greise Schmuck ist das graue Haar. –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 20, 30, 'Blutige Striemen scheuern das Böse weg, und Schläge säubern die Kammern des Leibes.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 21, 1, 'Gleich Wasserbächen ist das Herz des Königs in der Hand des HERRN: wohin immer er will, leitet er es. –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 21, 2, 'Alle seine Wege mag ein Mensch für recht halten, aber der HERR wägt die Herzen. –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 21, 3, 'Recht und Gerechtigkeit üben ist dem HERRN wohlgefälliger als Schlachtopfer. –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 21, 4, 'Stolze Augen und ein aufgeblasenes Herz: das neue Leben der Gottlosen ist doch wieder Sünde. –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 21, 5, 'Die Bestrebungen des Fleißigen bringen nur Gewinn; wer sich aber überstürzt, hat nur Schaden davon. –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 21, 6, 'Erwerb von Schätzen durch lügnerische Zunge ist wie ein verwehender Hauch, Schlingen des Todes. –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 21, 7, 'Die Gottlosen rafft ihre Gewalttätigkeit hinweg, weil sie sich weigern zu tun, was recht ist. –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 21, 8, 'Vielgewunden ist der Weg eines schuldbeladenen Menschen; wer aber redlich ist, dessen Tun ist gerade. –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 21, 9, 'Besser ist es, auf dem Dach in einem Winkel zu wohnen, als mit einem zänkischen Weibe in gemeinsamem Haus. –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 21, 10, 'Der Sinn des Gottlosen trachtet nach Bösem; sein Nächster findet kein Erbarmen in seinen Augen. –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 21, 11, 'Durch Bestrafung des Spötters wird der Unverständige gewitzigt; und wenn man den Weisen belehrt, so nimmt er Einsicht an. –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 21, 12, 'Es ist ein Gerechter da, der auf das Haus des Gottlosen achtet und die Gottlosen ins Verderben stürzt. –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 21, 13, 'Wer sein Ohr vor dem Hilferuf des Armen verstopft, der wird ebenfalls, wenn er selber ruft, kein Gehör finden. –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 21, 14, 'Eine Gabe im geheimen beschwichtigt den Zorn und ein Geschenk im Busen den heftigsten Grimm. –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 21, 15, 'Für die Gerechten ist es eine Freude, wenn Recht geschafft wird, aber für die Übeltäter ein Entsetzen. –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 21, 16, 'Ein Mensch, der vom Wege der Einsicht abirrt, wird (bald) in der Versammlung der Schatten ruhen. –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 21, 17, 'Wer Lustbarkeiten liebt, wird Mangel leiden; wer Wein und Salböl liebt, wird nicht reich. –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 21, 18, 'Der Gottlose ist ein Lösegeld für den Gerechten, und der Betrüger tritt an die Stelle (des Unglücks) der Redlichen. –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 21, 19, 'Besser ist es, (einsam) in einem wüsten Lande zu wohnen als bei einem zänkischen und grämlichen Weibe. –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 21, 20, 'Kostbare Schätze sind in der Wohnung des Weisen, aber ein törichter Mensch vergeudet sie. –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 21, 21, 'Wer sich der Gerechtigkeit und Güte befleißigt, erlangt Leben, Heil und Ehre. –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 21, 22, 'Ein Weiser ersteigt die feste Stadt von Kriegshelden und bringt das Bollwerk, auf das sie sich verließ, zu Fall. –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 21, 23, 'Wer seinen Mund und seine Zunge hütet, behütet sein Leben vor Fährlichkeiten. –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 21, 24, 'Ein aufgeblasener und frecher Mensch – Spötter ist sein Name – handelt in vermessenem Übermut. –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 21, 25, 'Dem Faulen bringt sein Gelüsten den Tod, weil seine Hände sich vor der Arbeit scheuen. –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 21, 26, 'Unaufhörlich wird gebettelt und gebettelt; dennoch gibt der Gerechte, ohne zu geizen. –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 21, 27, 'Das Opfer der Gottlosen ist (dem HERRN) ein Greuel, zumal wenn sie es um einer Schandtat willen darbringen. –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 21, 28, 'Ein lügenhafter Zeuge geht zugrunde, aber ein Mann, der Ohrenzeuge gewesen, mag allezeit reden. –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 21, 29, 'Ein gottloser Mensch trägt ein freches Angesicht zur Schau, ein Rechtschaffener aber gibt seinem Wege eine feste Richtung. –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 21, 30, 'Es gibt weder Weisheit noch Einsicht noch einen klugen Anschlag gegenüber dem HERRN. –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 21, 31, 'Das Roß wird für den Tag der Schlacht gerüstet, aber der Sieg steht bei dem HERRN.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 22, 1, 'Ein guter Name ist wertvoller als großer Reichtum, Beliebtheit besser als Silber und Gold. –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 22, 2, 'Reiche und Arme sind aufeinander angewiesen: der HERR hat sie alle beide geschaffen. –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 22, 3, 'Der Kluge sieht das Unglück voraus und verbirgt sich; die Einfältigen aber gehen weiter und erleiden Schaden. –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 22, 4, 'Der Lohn der Demut (und) der Gottesfurcht ist Reichtum, Ehre und Leben. –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 22, 5, 'Fußangeln und Schlingen liegen auf dem Wege des Falschen; wer sein Leben bewahren will, hält sich fern von ihnen. –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 22, 6, 'Erziehe dein Kind angemessen für seinen Lebensweg; dann wird es auch im Alter nicht davon abweichen. –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 22, 7, 'Der Reiche ist ein Herr der Armen, und wer borgt, ist ein Knecht des Gläubigers. –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 22, 8, 'Wer Unrecht sät, wird Unheil ernten, und die Zuchtrute seines Grimmes wird ihn selbst treffen. –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 22, 9, 'Der Mildherzige wird gesegnet; denn er gibt dem Armen von seinem Brot ab. –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 22, 10, 'Treibe den Spötter weg, so geht der Streit mit hinaus, und das Zanken und Schmähen hat ein Ende. –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 22, 11, 'Wer reines Herzens ist, den liebt der HERR, und wessen Lippen herzgewinnend reden, dessen Freund ist der König. –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 22, 12, 'Die Augen des HERRN bewahren, was sie wahrgenommen, und er bringt die Worte des Treulosen zu Fall. –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 22, 13, 'Der Faule sagt: »Ein Löwe ist draußen; ich könnte mitten auf der Straße ums Leben kommen!« –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 22, 14, 'Eine tiefe Grube ist der Mund der fremden Weiber; wer dem HERRN verhaßt ist, fällt hinein. –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 22, 15, 'Steckt Torheit tief im Herzen eines Kindes, so wird die Zuchtrute sie ihm austreiben. –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 22, 16, 'Wer einen Armen bedrückt, verhilft ihm zur Bereicherung; wer einen Reichen beschenkt, tut’s nur zu dessen Verarmung.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 22, 17, 'Leihe mir dein Ohr und vernimm die Worte von Weisen und richte deine Aufmerksamkeit auf mein Wissen!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 22, 18, 'Denn schön ist’s, wenn du sie in deinem Inneren festhältst: möchten sie allesamt auf deinen Lippen verbleiben!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 22, 19, 'Damit dein Vertrauen auf dem HERRN ruhe, habe ich dich heute unterwiesen, ja dich.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 22, 20, 'Wahrlich ich habe dir Kernsprüche aufgeschrieben mit Ratschlägen und Lehren,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 22, 21, 'um dir kundzutun die Richtschnur von Wahrheitsworten, damit du denen, die dich fragen, richtige Antworten geben kannst.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 22, 22, 'Bringe den Geringen nicht um das Seine, weil er gering ist, und zertritt den Armen nicht im Tor,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 22, 23, 'denn der HERR wird ihre Sache führen und denen, die sie berauben, das Leben rauben.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 22, 24, 'Befreunde dich nicht mit einem Zornmütigen und habe keinen Umgang mit einem Hitzkopf,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 22, 25, 'damit du dich nicht an seine Pfade gewöhnst und dir einen Fallstrick für deine Seele zulegst.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 22, 26, 'Gehöre nicht zu denen, die Handschlag geben, zu denen, die für (fremde) Schulden Bürgschaft leisten;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 22, 27, 'denn wenn du nicht imstande bist zu zahlen: warum soll man dir das Bett unter dem Leibe wegnehmen?');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 22, 28, 'Verrücke nicht die uralten Grenzsteine, die deine Väter gesetzt haben. –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 22, 29, 'Siehst du einen Mann, der in seinem Geschäft tüchtig ist, so wisse: bei Königen kann er in Dienst treten; er braucht nicht niedrigen Leuten seine Dienste zu widmen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 23, 1, 'Wenn du mit einem Herrscher zu Tische sitzt, so beachte wohl, wen du vor dir hast,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 23, 2, 'und setze dir ein Messer an die Kehle, wenn du starke Eßlust hast!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 23, 3, 'Laß dich nicht nach seinen Leckerbissen gelüsten, denn sie sind eine trügliche Speise.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 23, 4, 'Mühe dich nicht, dir Reichtum zu erwerben: dazu biete deine Klugheit nicht auf!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 23, 5, 'Kaum hast du deine Blicke auf ihn gerichtet, so ist er schon verschwunden; denn sicherlich verschafft er sich Flügel wie ein Adler, der gen Himmel fliegt.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 23, 6, 'Speise nicht bei einem Mißgünstigen und laß dich nicht nach seinen Leckerbissen gelüsten!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 23, 7, 'Denn wie einer, der alles bei sich berechnet, so gibt er sich: »Iß und trink!« sagt er zu dir, ohne es dir jedoch im Herzen zu gönnen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 23, 8, 'So mußt du denn den Bissen, den du genossen hast, wieder ausspeien, und deine freundlichen Worte hast du verschwendet.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 23, 9, 'Rede nicht vor den Ohren eines Toren, denn er hat für deine verständigen Worte nur Verachtung. –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 23, 10, 'Verrücke die Grenzsteine der Witwe nicht und dringe nicht in den Ackerbesitz der Verwaisten ein!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 23, 11, 'Denn ihr Rechtsbeistand ist stark: der wird ihre Sache gegen dich führen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 23, 12, 'Bringe dein Herz der Unterweisung entgegen und deine Ohren einsichtsvollen Reden.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 23, 13, 'Erspare deinem Kinde die Züchtigung nicht! Denn schlägst du es mit der Rute, wird es nicht zu sterben brauchen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 23, 14, 'Du wirst es mit der Rute schlagen und dadurch sein Leben vor dem Totenreich bewahren.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 23, 15, 'Mein Sohn, wenn dein Herz weise wird, so wird das auch für mich eine herzliche Freude sein;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 23, 16, 'und mein Innerstes wird frohlocken, wenn deine Lippen reden, was recht ist.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 23, 17, 'Dein Herz ereifere sich nicht bezüglich der Sünder, wohl aber bezüglich der Furcht des HERRN allezeit:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 23, 18, 'denn es gibt (für dich) sicherlich noch eine Zukunft, und deine Hoffnung wird nicht zuschanden werden.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 23, 19, 'Höre du zu, mein Sohn, damit du weise wirst, und laß dein Herz geradeaus den rechten Weg gehen!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 23, 20, 'Gehöre nicht zu den Trunkenbolden, noch zu denen, die im Fleischgenuß schwelgen!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 23, 21, 'Denn Säufer und Schlemmer verarmen, und Schläfrigkeit gibt Lumpen zur Kleidung.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 23, 22, 'Gehorche deinem Vater, der dir das Leben gegeben hat, und verachte deine Mutter nicht, wenn sie alt geworden ist!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 23, 23, 'Kaufe dir Wahrheit und verkaufe sie nicht wieder, Weisheit und Zucht und Einsicht.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 23, 24, 'Laut frohlockt der Vater eines frommen (Sohnes); und die ein verständiges Kind geboren hat, darf sich seiner freuen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 23, 25, 'Mögen dein Vater und deine Mutter solche Freude haben und sie, die dir das Leben gegeben haben, (über dich) frohlocken!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 23, 26, 'Gib mir, mein Sohn, dein Herz und laß deinen Augen meine Wege wohlgefallen!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 23, 27, 'Denn eine tiefe Grube ist die Lustdirne und ein enger Brunnen die Buhlerin.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 23, 28, 'Überdies liegt sie auf der Lauer wie ein Räuber und vermehrt die (Zahl der) Treulosen unter den Menschen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 23, 29, 'Bei wem findet sich Ach? Bei wem Wehe? Bei wem Händel? Bei wem Klagen? Bei wem Wunden ohne Ursache? Bei wem trübe Augen?');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 23, 30, 'Bei denen, die noch spät beim Wein sitzen, die da einkehren, um den Mischtrank zu prüfen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 23, 31, 'Sieh den Wein nicht an, wie er rötlich schimmert, wie hell er im Becher funkelt und so sanft hinuntergleitet!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 23, 32, 'Aber hinterher beißt er wie eine Schlange und spritzt Gift wie eine Otter.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 23, 33, 'Deine Augen werden seltsame Dinge sehen, und dein Herz wird verkehrtes Zeug reden;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 23, 34, 'und du wirst sein wie einer, der tief unten im Meer liegt, und wie einer, der oben im Mastkorb liegt.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 23, 35, '»Man hat mich geschlagen, aber es hat mir nicht weh getan; man hat mich geprügelt, aber ich habe nichts davon gefühlt. Wann werde ich aufwachen? Dann will ich es wieder so machen, will ihn aufs neue aufsuchen.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 24, 1, 'Sei nicht neidisch auf böse Menschen und laß dich nicht gelüsten, ihr Genosse zu sein!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 24, 2, 'Denn ihr Herz sinnt auf Gewalttat, und ihre Lippen reden Unheil.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 24, 3, 'Durch Weisheit wird ein Haus gebaut und durch Einsicht fest gegründet;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 24, 4, 'und durch Klugheit füllen sich die Kammern mit allerlei kostbarem und herrlichem Besitz.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 24, 5, 'Ein weiser Mann ist einem starken überlegen und ein einsichtiger einem kraftvollen;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 24, 6, 'denn mit klugen Maßnahmen wirst du den Krieg glücklich führen, und der Sieg ist da, wo Ratgeber in großer Zahl vorhanden sind.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 24, 7, 'Unerschwinglich ist für den Toren die Weisheit; darum tut er am Tor den Mund nicht auf.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 24, 8, 'Wer darauf ausgeht, Böses zu tun, den nennt man einen Bösewicht.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 24, 9, 'Die Sünde ist ein Vorhaben des Unverstandes, und der Spötter ist ein Greuel für die Menschen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 24, 10, 'Hast du dich in der Zeit (des Glücks) schlaff gezeigt, so ist deine Kraft auch in der Zeit der Not schwach.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 24, 11, 'Rette die, welche (unschuldig) zum Tode geschleppt werden, und die zur Hinrichtung Wankenden – o befreie sie doch!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 24, 12, 'Wolltest du sagen: »Wir haben ja nichts davon gewußt«: wird nicht er, der die Herzen wägt, es durchschauen und er, der deine Seele beobachtet, es wissen? Ja, er wird jedem nach seinem Tun vergelten.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 24, 13, 'Iß Honig, mein Sohn, denn er ist gesund, und Honigseim schmeckt deinem Gaumen süß.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 24, 14, 'Ebenso heilsam erachte die Weisheit für deine Seele! Hast du sie erlangt, so ist eine Zukunft (für dich) vorhanden, und deine Hoffnung wird nicht zuschanden werden.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 24, 15, 'Belaure nicht, du Gottloser, die Wohnung des Gerechten und verstöre seine Lagerstätte nicht!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 24, 16, 'Denn siebenmal fällt der Gerechte und steht wieder auf, die Gottlosen aber stürzen nieder im Unglück.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 24, 17, 'Wenn dein Feind zu Fall kommt, so freue dich nicht, und wenn er strauchelt, so frohlocke dein Herz nicht,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 24, 18, 'damit der HERR es nicht sieht und Mißfallen empfindet und seinen Zorn von ihm weg (gegen dich) wendet.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 24, 19, 'Erhitze dich nicht über die Übeltäter, ereifere dich nicht über die Gottlosen!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 24, 20, 'Denn für den Bösen gibt es keine Zukunft, und die Leuchte der Gottlosen erlischt.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 24, 21, 'Mein Sohn, fürchte den HERRN und den König und laß dich nicht mit Mißvergnügten ein!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 24, 22, 'Denn plötzlich bricht das Verderben über sie herein, und der Untergang der Mißvergnügten kommt unvermutet.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 24, 23, 'Auch die folgenden Sprüche stammen von Weisen: In einer Rechtssache die Person ansehen, ist ein übel Ding.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 24, 24, 'Wer zu dem Schuldigen sagt: »Du bist im Recht«, den verwünschen die Völker, verfluchen die Völkerschaften;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 24, 25, 'aber denen, die gerecht entscheiden, ergeht es gut, und reicher Segen wird ihnen zuteil.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 24, 26, 'Wie ein Kuß auf die Lippen ist eine treffende Antwort.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 24, 27, 'Besorge (zunächst) deine Obliegenheiten draußen und verrichte deine Arbeit auf dem Felde; darnach magst du dir einen (eigenen) Hausstand gründen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 24, 28, 'Tritt nicht als falscher Zeuge gegen einen andern auf und richte keine Täuschung mit deinen Lippen an.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 24, 29, 'Sage nicht: »Wie er mir getan hat, so will ich ihm wieder tun: ich will dem Manne nach seinem Tun vergelten.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 24, 30, 'Am Acker eines faulen Mannes kam ich vorüber und am Weinberg eines unverständigen Menschen;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 24, 31, 'und siehe da: er war ganz mit Disteln überwachsen, seine Oberfläche mit Unkraut bedeckt und seine Steinmauer eingestürzt.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 24, 32, 'Als ich das sah, nahm ich es mir zu Herzen, ich beachtete es und ließ es mir zur Lehre dienen:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 24, 33, '»Noch ein wenig Schlaf, noch ein wenig Schlummer, noch ein wenig die Hände falten, um auszuruhen!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 24, 34, 'So kommt denn die Armut im Eilschritt über dich und der Mangel über dich wie ein gewappneter Mann.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 25, 1, 'Auch dies sind Sprüche von Salomo, welche die Männer Hiskias, des Königs von Juda, gesammelt haben.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 25, 2, 'Gottes Ehre ist es, eine Sache zu verbergen, aber der Könige Ehre ist es, eine Sache ans Licht zu bringen. –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 25, 3, 'Wie des Himmels Höhe und der Erde Tiefe, so ist auch das Herz der Könige unerforschlich. –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 25, 4, 'Nur wenn die Schlacken vom Silber geschieden werden, so kommt dem Goldschmied ein Gerät zustande.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 25, 5, 'Nur wenn die Gottlosen aus der Nähe des Königs entfernt werden, so wird sein Thron durch Gerechtigkeit feststehen. –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 25, 6, 'Brüste dich nicht vor dem König und stelle dich nicht an den Platz der Großen!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 25, 7, 'Denn besser ist’s, daß man zu dir sagt: »Rücke herauf, hierher«, als daß man dich vor einem Vornehmen herunterrücken läßt. –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 25, 8, 'Was du mit deinen Augen gesehen hast, mache nicht voreilig zum Gegenstand einer Anklage; denn was willst du hinterher anfangen, wenn dein Nächster dich schmählich widerlegt? –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 25, 9, 'Bringe deinen Rechtshandel mit deinem Gegner zum Austrag, aber verrate dabei kein fremdes Geheimnis,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 25, 10, 'damit, wer es hört, dich nicht schmäht und dein übler Ruf nicht wieder schwindet. –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 25, 11, 'Wie goldene Äpfel in silbernen Prunkschalen, so ist ein Wort, gesprochen zu rechter Zeit. –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 25, 12, 'Ein goldener Ring und ein Geschmeide von feinem Gold: so ist ein weiser Tadler für ein aufmerksames Ohr. –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 25, 13, 'Wie Kühlung durch Schnee an einem Erntetage, so ist ein treuer Bote für seinen Auftraggeber: er erquickt das Herz seines Herrn. –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 25, 14, 'Wie Gewölk und Wind und doch kein Regen: so ist ein Mann, der mit Geschenken prahlt, die er nie gibt. –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 25, 15, 'Durch leidenschaftslose Ruhe wird der Fürst gewonnen, und eine sanfte Zunge zerbricht Knochen. –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 25, 16, 'Hast du Honig gefunden, so genieße davon nur ein genügend Teil, damit du nicht übersatt wirst und ihn wieder ausspeien mußt. –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 25, 17, 'Setze deinen Fuß nur selten in das Haus deines Nächsten, damit er deiner nicht überdrüssig wird und dich dann haßt. –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 25, 18, 'Streithammer, Schwert und spitzer Pfeil: so ist ein Mann, der gegen einen andern als falscher Zeuge aussagt. –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 25, 19, 'Ein brüchiger Zahn und ein wankender Fuß: so ist ein treuloser Mensch in der Zeit der Not. –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 25, 20, 'Wie einer, der Essig auf eine Wunde gießt, so (verkehrt) ist jemand, der einem bekümmerten Herzen Lieder vorsingt. –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 25, 21, 'Wenn deinen Feind hungert, so speise ihn mit Brot, und wenn ihn dürstet, so gib ihm Wasser zu trinken;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 25, 22, 'denn damit häufst du glühende Kohlen auf sein Haupt, und der HERR wird dir’s vergelten. –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 25, 23, 'Nordwind bringt Regen herbei, und Ohrenbläserei verursacht verdrießliche Gesichter. –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 25, 24, 'Besser ist es, auf dem Dach in einem Winkel zu wohnen, als mit einem zänkischen Weibe in gemeinsamem Hause. –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 25, 25, 'Kühles Wasser für eine lechzende Seele: so ist eine gute Nachricht aus fernem Lande. –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 25, 26, 'Eine getrübte Quelle und ein verschütteter Brunnen: so ist ein Gerechter, der vor dem Gottlosen wankt. –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 25, 27, 'Zuviel Honig essen ist nicht heilsam, darum sei sparsam mit ehrenden Worten. –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 25, 28, 'Wie eine Stadt, deren Mauern niedergerissen sind, so ist ein Mann, dessen Geiste Selbstbeherrschung mangelt.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 26, 1, 'So wenig Schnee zum Sommer und so wenig Regen zur Erntezeit paßt, so ungehörig ist Ehre für den Toren. –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 26, 2, 'Wie ein Sperling, der davonflattert, und wie eine Schwalbe, die wegfliegt, so ist ein unverdienter Fluch: er trifft nicht ein.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 26, 3, 'Die Peitsche für das Pferd, der Zaum für den Esel und der Stock für den Rücken der Toren. –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 26, 4, 'Antworte dem Toren nicht im Anschluß an seine Narrheit, damit du selbst ihm nicht gleich wirst;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 26, 5, 'antworte dem Toren im Anschluß an seine Narrheit, damit er sich nicht selbst weise dünkt. –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 26, 6, 'Die Füße haut sich ab und Unheil bekommt zu schlucken, wer Aufträge durch einen Toren ausrichten läßt. –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 26, 7, 'Schlaff hängen die Beine an einem Lahmen herab; ebenso ist ein Weisheitsspruch im Munde der Toren. –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 26, 8, 'Wie wenn man einen Stein an einer Schleuder festbindet, so (sinnlos) ist es, wenn man einem Toren Ehre erweist. –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 26, 9, 'Ein Dornzweig, der einem Trunkenen in die Hand gerät: so ist ein Weisheitsspruch im Munde von Toren.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 26, 10, 'Wie ein Schütze, der alle Vorübergehenden verwundet: so ist, wer Toren oder Trunkene dingt. –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 26, 11, 'Wie ein Hund, der zu seinem Gespei zurückkehrt, so ist ein Tor, der seinen Unverstand wiederholt. –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 26, 12, 'Siehst du einen Mann, der sich selbst für weise hält: da ist für einen Toren mehr Hoffnung vorhanden als für ihn. –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 26, 13, 'Der Faule sagt: »Ein Leu ist auf dem Wege, ein Löwe innerhalb der Straßen.« –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 26, 14, 'Die Tür dreht sich in ihrer Angel und der Faule in seinem Bett. –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 26, 15, 'Hat der Faule seine Hand in die Eßschüssel gesteckt, so ist es ihm beschwerlich, sie zu seinem Munde zurückzubringen. –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 26, 16, 'Ein Fauler kommt sich selbst weiser vor als sieben (Weise), die verständig zu antworten verstehen. –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 26, 17, 'Wie einer, der einen vorüberlaufenden Hund bei den Ohren packt, so ist, wer sich in einen Streit einmischt, der ihn nichts angeht. –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 26, 18, 'Wie einer, der sich wahnsinnig stellt und dabei Brandpfeile und todbringende Geschosse schleudert,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 26, 19, 'so ist ein Mann, der einen andern betrogen hat und dann sagt: »Ich habe ja nur gescherzt.« –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 26, 20, 'Wo das Holz fehlt, erlischt das Feuer, und wo kein Ohrenbläser ist, da hört der Streit auf. –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 26, 21, 'Kohlen schüren die Glut und Holz das Feuer, und ein zanksüchtiger Mensch schürt den Streit. –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 26, 22, 'Die Worte des Ohrenbläsers sind wie Leckerbissen, die in das Innerste des Leibes hinabdringen. –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 26, 23, 'Blanke Glasur, mit der ein irdenes Gefäß überzogen ist: so sind liebeglühende Lippen und ein boshaftes Herz. –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 26, 24, 'Mit seinen Lippen verstellt sich der Hassende, aber in seinem Innern hegt er Trug;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 26, 25, 'wenn er freundliche Worte redet, so traue ihm nicht! Denn sieben Greuel hegt er in seinem Herzen. –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 26, 26, 'Mag Haß sich auch hinter Verstellung verbergen, so wird seine Bosheit doch in der Gerichtsversammlung offenbar werden. –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 26, 27, 'Wer (anderen) eine Grube gräbt, fällt (selbst) hinein; und wer einen Stein (auf andere) wälzt, auf den rollt er zurück. –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 26, 28, 'Eine Lügenzunge haßt die von ihr Vernichteten, und ein glatter Mund bringt zu Fall.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 27, 1, 'Rühme dich nicht des morgenden Tages, denn du weißt nicht, was ein Tag gebiert. –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 27, 2, 'Ein anderer rühme dich, aber nicht dein eigener Mund; ein Fremder, aber nicht deine eigenen Lippen. –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 27, 3, 'Schwer mag ein Stein sein und der Sand eine Last, aber Verdruß über einen Toren ist schwerer als beide. –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 27, 4, 'Die Wut mag grimmig sein und der Zorn überwallen, aber wer kann der Eifersucht Widerstand leisten? –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 27, 5, 'Besser ist ein offen ausgesprochener Tadel als eine Liebe, welche verschleiert. –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 27, 6, 'Treuer gemeint sind die von Freundes Hand versetzten Schläge als die überreichlichen Küsse des Hassenden. –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 27, 7, 'Wessen Hunger gestillt ist, der tritt Honigseim mit Füßen; aber einem Hungrigen schmeckt alles Bittere süß. –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 27, 8, 'Wie ein Vogel, der aus seinem Neste verscheucht ist, so ein Mann, der fern von seiner Heimat schweift. –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 27, 9, 'Salböl und Räucherwerk erfreuen das Herz, aber von Leiden wird die Seele zerrissen. –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 27, 10, 'Deinen Freund und deines Vaters Freund verlaß nicht und begib dich nicht in das Haus deines Bruders am Tage deines Unglücks; besser ist ein Nachbar in der Nähe als ein Bruder in der Ferne, (wenn du in Not bist). –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 27, 11, 'Sei weise, mein Sohn, und erfreue dadurch mein Herz, damit ich mich gegen den, der mich schmäht, verantworten kann. –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 27, 12, 'Der Kluge sieht die Gefahr und birgt sich; die Einfältigen aber gehen weiter und erleiden Schaden. –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 27, 13, 'Nimm ihm seinen Rock weg, denn er hat sich für einen andern verbürgt, und um fremder Leute willen pfände ihn aus! –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 27, 14, 'Wenn jemand seinen Nächsten am Morgen ganz früh mit lautem Segenswunsch begrüßt, so wird ihm das als (versteckte) Verwünschung ausgelegt. –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 27, 15, 'Eine bei Regenwetter stets rinnende Dachtraufe und ein zänkisches Weib gleichen sich;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 27, 16, 'wer dieses zur Ruhe bringt, kann auch den Wind zur Ruhe bringen und mit seiner Hand Öl festhalten. –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 27, 17, 'Eisen wird durch Eisen geschärft, und ein Mensch schärft das Gesicht des andern. –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 27, 18, 'Wer einen Feigenbaum pflegt, wird seine Früchte genießen; und wer seinem Herrn aufmerksam dient, wird geehrt werden. –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 27, 19, 'Wie das eine Gesicht neben dem andern, ebenso sind die Herzen der Menschen verschieden. –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 27, 20, 'Unterwelt und Abgrund sind unersättlich; ebenso werden auch die Augen des Menschen nicht satt. –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 27, 21, 'Der Schmelztiegel ist für das Silber und der Ofen für das Gold; ein Mann aber wird beurteilt nach Maßgabe seines Rufes. –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 27, 22, 'Wenn du auch den Toren im Mörser mitten unter der Grütze mit dem Stößel zerstießest, so würde doch seine Torheit nicht von ihm weichen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 27, 23, 'Gib auf das Aussehen deines Kleinviehs wohl acht und richte deine Aufmerksamkeit auf deine Herden;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 27, 24, 'denn Wohlstand dauert nicht ewig; und vererbt sich etwa eine Krone von Geschlecht auf Geschlecht?');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 27, 25, 'Ist das Gras geschwunden und das junge Grün abgeweidet und sind die Kräuter der Berge vernichtet,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 27, 26, 'so (liefern) die Lämmer dir Kleidung, und die Böcke (dienen dir als) Kaufgeld für einen Acker;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 27, 27, 'und Ziegenmilch ist reichlich da zu deiner Nahrung, zur Ernährung deiner Familie, und Lebensunterhalt für deine Mägde.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 28, 1, 'Die Gottlosen fliehen, ohne daß jemand sie verfolgt, die Gerechten aber sind unerschrocken wie ein junger Löwe. –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 28, 2, 'Durch die Sündhaftigkeit eines Landes tritt häufiger Fürstenwechsel ein; aber durch einen einsichtigen, erfahrenen Mann gewinnt der Rechtsstand lange Dauer. –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 28, 3, 'Ein Mann, der an der Spitze steht und die Geringen bedrückt, ist wie ein Regen, der (das Erdreich) wegschwemmt, ohne Brot zu bringen. –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 28, 4, 'Menschen, die das Gesetz (Gottes) verlassen, rühmen den Gottlosen; die aber das Gesetz beobachten, sind entrüstet über ihn. –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 28, 5, 'Böse Menschen verstehen sich nicht auf das, was recht ist; die aber den HERRN suchen, verstehen es in jeder Hinsicht. –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 28, 6, 'Besser ist ein Armer, der in seiner Unschuld wandelt, als ein Mensch, der auf krummen Wegen geht und dabei reich ist. –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 28, 7, 'Wer am Gesetz (Gottes) festhält, ist ein verständiger Sohn; wer sich aber zu Schlemmern gesellt, macht seinem Vater Schande. –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 28, 8, 'Wer sein Vermögen durch Zins und Wucher vermehrt, sammelt es für den, der sich der Armen erbarmt. –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 28, 9, 'Wer sein Ohr abwendet, um das Gesetz (Gottes) nicht zu hören, dessen Gebet sogar ist ein Greuel. –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 28, 10, 'Wer Rechtschaffene irreführt auf bösen Weg, wird in die eigene Grube fallen; die Unsträflichen aber werden Segen erlangen. –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 28, 11, 'Ein reicher Mann hält sich selbst für weise, aber ein Armer, der einsichtig ist, forscht ihn aus. –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 28, 12, 'Wenn die Gerechten frohlocken, ist die Herrlichkeit groß; wenn aber die Gottlosen hochkommen, halten sich die Menschen versteckt. –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 28, 13, 'Wer seine Übertretungen zu verheimlichen sucht, dem wird es nicht gelingen; wer sie aber bekennt und davon abläßt, wird Vergebung erlangen. –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 28, 14, 'Wohl dem, der beständig in der Furcht (Gottes) bleibt! Wer aber sein Herz verhärtet, wird in Unglück geraten. –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 28, 15, 'Ein brüllender Löwe und ein raubgieriger Bär: so ist ein gottloser Herrscher für ein armes Volk. –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 28, 16, 'Ein Fürst, arm an Einsicht, ist oft reich an Erpressungen; aber nur ein den unrechtmäßigen Gewinn hassender Fürst wird es zu langem Leben bringen. –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 28, 17, 'Ein Mensch, der Blutschuld auf dem Gewissen hat, ist bis zur Grube ein unsteter Flüchtling: niemand helfe ihm auf! –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 28, 18, 'Wer unsträflich wandelt, wird gerettet werden; wer aber krumme Wege einschlägt, fällt in die Grube. –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 28, 19, 'Wer seinen Acker bestellt, wird reichlich Brot haben; wer aber nichtigen Dingen nachjagt, wird reichlich Armut haben. –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 28, 20, 'Ein treuer Mann wird reich gesegnet; wer aber möglichst schnell reich werden will, wird nicht schuldlos bleiben. –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 28, 21, 'Parteiisch sein ist ein übel Ding, aber mancher läßt sich schon durch ein Stück Brot zum Bösen verführen. –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 28, 22, 'Ein scheelblickender Mensch trachtet gierig nach Reichtum und bedenkt nicht, daß Mangel über ihn kommen wird. –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 28, 23, 'Wer einen andern zurechtweist, wird schließlich mehr Dank ernten, als wer mit glatter Zunge schmeichelt. –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 28, 24, 'Wer seinem Vater und seiner Mutter das Ihre nimmt und behauptet, das sei keine Sünde, der ist ein Genosse des Verderbers. –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 28, 25, 'Der Habgierige erregt Streit; wer aber auf den HERRN vertraut, wird reichlich gesättigt. –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 28, 26, 'Wer sich auf seinen Verstand verläßt, der ist ein Tor; wer aber in Weisheit wandelt, der wird (dem Unglück) entrinnen. –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 28, 27, 'Wer dem Armen gibt, wird keinen Mangel leiden; wer aber seine Augen verhüllt, wird mit Flüchen überhäuft werden. –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 28, 28, 'Wenn die Gottlosen hochkommen, verbergen sich die Leute; wenn sie aber umkommen, werden die Gerechten mächtig.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 29, 1, 'Ein Mensch, der allen Warnungen gegenüber halsstarrig bleibt, wird plötzlich unheilbar zerschmettert werden. –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 29, 2, 'Wenn die Gerechten die Oberhand haben, so freut sich das Volk; wenn aber ein Gottloser herrscht, so seufzt das Volk. –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 29, 3, 'Wenn jemand die Weisheit liebt, macht er seinem Vater Freude; wer aber mit Dirnen umgeht, bringt sein Vermögen durch. –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 29, 4, 'Ein König verleiht durch Gerechtigkeit dem Lande Bestand; wer aber immer neue Abgaben erpreßt, richtet es zugrunde. –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 29, 5, 'Ein Mann, der seinem Nächsten schmeichelt, breitet ein Netz vor dessen Füßen aus. –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 29, 6, 'In der Übertretung eines bösen Menschen liegt ein Fallstrick für ihn; aber der Gerechte wird jubeln und fröhlich sein. –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 29, 7, 'Der Gerechte nimmt Kenntnis von der Rechtssache der Geringen, der Gottlose aber versteht sich nicht zu (solcher) Kenntnisnahme. –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 29, 8, 'Spötter versetzen die Stadt in Aufruhr, Weise aber beschwichtigen die Aufregung. –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 29, 9, 'Wenn ein weiser Mann einem törichten Menschen Vorstellungen macht, so braust der auf und lacht, aber es tritt keine Ruhe ein. –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 29, 10, 'Blutgierige Menschen hassen den Unschuldigen, die Rechtschaffenen aber nehmen sich seiner an. –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 29, 11, 'Der Tor macht seinem ganzen Unmut Luft, der Weise aber hält ihn beschwichtigend zurück. –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 29, 12, 'Wenn ein Herrscher auf Lügenworte horcht, so werden seine Diener alle gottlos. –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 29, 13, 'Der Arme und der gewalttätige (Reiche) leben beisammen; der HERR ist’s, der ihnen beiden das Augenlicht gibt. –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 29, 14, 'Ein König, der den Geringen gewissenhaft Recht schafft, dessen Thron wird immerdar feststehen. –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 29, 15, 'Rute und Zurechtweisung verleihen Weisheit; aber ein sich selbst überlassenes Kind bringt seiner Mutter Schande. –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 29, 16, 'Wenn die Gottlosen mächtig werden, mehren sich auch die Übertretungen; aber die Gerechten werden ihren Sturz mit Freuden sehen. –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 29, 17, 'Züchtige deinen Sohn, so wird er dir Behagen verschaffen und deinem Herzen Leckerbissen bereiten. –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 29, 18, 'Wenn keine prophetische Offenbarung da ist, wird das Volk zügellos; aber wohl ihm, wenn es das Gesetz (Gottes) beobachtet! –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 29, 19, 'Mit bloßen Worten läßt sich ein Knecht nicht zurechtbringen; denn er versteht sie wohl, richtet sich aber nicht danach. –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 29, 20, 'Siehst du einen Mann, der mit Worten schnell fertig ist, so ist für einen Toren mehr Hoffnung vorhanden als für ihn. –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 29, 21, 'Wenn einer seinen Knecht von Jugend auf verwöhnt, so will dieser schließlich Sohn im Hause sein. –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 29, 22, 'Ein zornmütiger Mensch ruft Streit hervor, und ein Hitzkopf richtet viel Unheil an. –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 29, 23, 'Hochmut wird einen Menschen erniedrigen; der Demütige dagegen wird Ehre erlangen. –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 29, 24, 'Wer mit Dieben gemeinsame Sache macht, haßt sein eigenes Leben: er hört die Verfluchung (des Richters) und erstattet doch keine Anzeige. –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 29, 25, 'Menschenfurcht legt Fallstricke; wer aber auf den HERRN vertraut, ist wohlgeborgen. –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 29, 26, 'Viele suchen Hilfe beim Herrscher; aber vom HERRN wird jedem sein Recht zuteil. –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 29, 27, 'Für die Gerechten ist ein Mensch, der unrecht tut, ein Greuel; und für den Gottlosen ist ein Greuel, wer rechtschaffen wandelt.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 30, 1, '(Dies sind) die Sprüche Agurs, des Sohnes Jakes, aus Massa. So lautet der Ausspruch des Mannes: »Ich habe mich abgemüht, o Gott, ich habe mich abgemüht, o Gott, und bin dahingeschwunden;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 30, 2, 'denn ich bin ein vernunftloses Geschöpf, kein Mensch, und besitze keinen Menschenverstand;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 30, 3, 'auch Weisheit habe ich nicht gelernt, daß ich die Erkenntnis des heiligen (Gottes) gewonnen hätte.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 30, 4, 'Wer ist in den Himmel emporgestiegen und wieder herabgekommen? Wer hat den Wind in seine Fäuste gesammelt, wer die Wasser in ein Gewand gebunden? Wer hat alle Enden der Erde festgestellt? Wie heißt er, und wie heißt sein Sohn? Weißt du es etwa?«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 30, 5, 'Jedes Wort Gottes ist lautere Wahrheit; ein Schild ist er denen, die Zuflucht bei ihm suchen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 30, 6, 'Füge nichts zu seinen Worten hinzu, damit er dich nicht zur Rechenschaft zieht und du als Lügner dastehst!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 30, 7, 'Um zweierlei bitte ich dich – versage es mir nicht, ehe ich sterbe –:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 30, 8, 'Falschheit und Lügenwort halte fern von mir! Armut und Reichtum gib mir nicht! Laß mich (aber) den mir zukommenden Teil von Nahrung verzehren,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 30, 9, 'damit ich nicht aus Übersättigung dich verleugne und sage: »Wer ist der HERR?«, aber auch nicht infolge der Armut zum Diebe werde und mich am Namen meines Gottes vergreife.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 30, 10, 'Verleumde einen Knecht nicht bei seinem Herrn, damit er dir nicht flucht und du es büßen mußt.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 30, 11, '(Ein Greuel für den HERRN ist) ein Geschlecht, das seinem Vater flucht und seine Mutter nicht segnet,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 30, 12, 'ein Geschlecht, das sich selbst für rein hält und doch von seiner Unreinheit sich nicht gesäubert hat,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 30, 13, 'ein Geschlecht, das den Kopf wunder wie hoch trägt und auf andere mit stolz erhobenen Augen herabblickt,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 30, 14, 'ein Geschlecht, dessen Zähne Schwerter sind und dessen Gebiß aus Messern besteht, um die Elenden aus dem Lande wegzufressen und die Armen aus der Mitte der Menschen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 30, 15, 'Aluka hat zwei Töchter: »Gib her! Gib her!« Drei gibt es, die nicht satt werden, und vier sagen niemals: »Genug!«,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 30, 16, 'nämlich das Totenreich und der unfruchtbare Mutterschoß, die Erde, die des Wassers nie satt wird, und das Feuer, das niemals sagt: »Genug!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 30, 17, 'Ein Auge, das den Vater verspottet und die greise Mutter verachtet, das müssen die Raben am Bach aushacken und die jungen Geier fressen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 30, 18, 'Drei Dinge sind es, die mir zu wunderbar erscheinen, und vier, die ich nicht begreife:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 30, 19, 'des Adlers Weg am Himmel, der Schlange Weg über den Felsen, des Schiffes Weg mitten auf dem Meer und des Mannes Weg bei einem Weibe. –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 30, 20, 'So ist das Verhalten eines ehebrecherischen Weibes: sie ißt und wischt sich den Mund ab und sagt: »Ich habe nichts Unrechtes getan.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 30, 21, 'Unter drei Dingen erzittert die Erde, und unter vieren kann sie es nicht aushalten:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 30, 22, 'unter einem Sklaven, wenn er König wird, und unter einem ruchlosen Menschen, wenn er Brot in Fülle hat;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 30, 23, 'unter einer unleidlichen Frau, wenn sie zur Ehe kommt, und unter einer Magd, wenn sie ihre Herrin verdrängt.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 30, 24, 'Vier Tiere gehören zu den kleinsten auf Erden und sind doch unglaublich klug:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 30, 25, 'die Ameisen, ein schwaches Volk, aber sie bereiten sich im Sommer ihren Speisebedarf;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 30, 26, 'die Klippdachse, ein Volk ohne Kraft, aber sie legen ihre Wohnung in den Felsen an;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 30, 27, 'die Heuschrecken, die keinen König haben, und doch zieht ihr ganzer Schwarm wohlgeordnet daher;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 30, 28, 'die Eidechsen, die du mit (bloßen) Händen fangen kannst und die sich doch in Königspalästen finden.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 30, 29, 'Drei sind es, die stattlich einherschreiten, und vier, die einen würdevollen Gang haben:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 30, 30, 'der Löwe, der Held unter den Tieren, der vor nichts kehrt macht;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 30, 31, '(der Hahn, der wohlgemut unter den Hennen einherschreitet, und der Bock, der die Ziegenherde anführt) und der König an der Spitze seines Heerbannes. –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 30, 32, 'Magst du töricht gewesen sein, indem du dich über den andern erhobst, oder magst du mit Überlegung gehandelt haben: lege die Hand auf den Mund!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 30, 33, 'Denn der Druck auf die Milch bringt Butter hervor, und Druck auf die Nase bringt Blut hervor, und Druck auf den Zorn bringt Streit hervor.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 31, 1, 'Sprüche für Lemuel, den König von Massa, mit denen seine Mutter ihn unterwiesen hat:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 31, 2, '»Was mein Sohn, (was, o Lemuel, mein Erstgeborener, was soll ich dir sagen)? Ja was (soll ich dir sagen), du Sohn meines Schoßes, und was dir, du Sohn meiner Gelübde?');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 31, 3, 'Gib nicht den Weibern deine Kraft preis und (folge nicht in deinem Tun) den Verderberinnen der Könige.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 31, 4, 'Es ziemt sich nicht für Könige, Lemuel, es ziemt sich nicht für Könige der Weingenuß noch für Fürsten das Verlangen nach berauschenden Getränken:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 31, 5, 'sie könnten sonst über dem Trinken das festgesetzte Recht außer acht lassen und der Rechtssache aller geringen Leute Eintrag tun.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 31, 6, 'Gebt berauschendes Getränk den Verzweifelnden und Wein denen, deren Herz bekümmert ist:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 31, 7, 'die mögen trinken, um ihre Armut zu vergessen und an ihr Elend nicht mehr zu denken. –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 31, 8, 'Tu deinen Mund auf für die Stummen, für die Sache aller Hilflosen!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 31, 9, 'Tu deinen Mund auf zu gerechtem Richterspruch und schaffe Recht dem Elenden und Armen!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 31, 10, 'Eine tüchtige Frau – wer mag sie finden? Weit über Korallen geht ihr Wert.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 31, 11, 'Das Herz ihres Gatten kann sich auf sie verlassen, und an Gewinn wird es (ihm) nicht fehlen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 31, 12, 'Sie erweist ihm Gutes und nichts Böses während ihrer ganzen Lebenszeit.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 31, 13, 'Sie trägt Sorge für Wolle und Flachs und schafft dann mit arbeitsfreudigen Händen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 31, 14, 'Sie gleicht den Schiffen eines Kaufmanns: von fernher beschafft sie den Bedarf für ihren Haushalt.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 31, 15, 'Sie steht auf, wenn es noch Nacht ist, und gibt Kost heraus für ihre Hausgenossen und weist den Mägden ihr Tagewerk an.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 31, 16, 'Sie faßt den Ankauf eines Ackers ins Auge und erwirbt ihn auch; vom Ertrag ihrer Handarbeit legt sie einen Weinberg an.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 31, 17, 'Sie gürtet ihre Hüften mit Kraft und regt die Arme, ohne zu ermatten.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 31, 18, 'Sie merkt, daß ihr Schaffen Segen bringt: auch nachts erlischt ihre Lampe nicht.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 31, 19, 'Sie legt ihre Hände an den Spinnrocken, und ihre Finger ergreifen die Spindel.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 31, 20, 'Dem Elenden bietet sie ihre Hand (schenkend) dar und streckt dem Dürftigen ihre Arme entgegen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 31, 21, 'Sie braucht für ihre Hausgenossen vom Schnee nichts zu fürchten; denn ihr ganzes Haus ist in Scharlachwolle gehüllt.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 31, 22, 'Sie fertigt sich Decken an; Linnen und Purpur bilden ihre Kleidung.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 31, 23, 'Hochgeachtet ist ihr Gatte in den Toren, wenn er mit den Ältesten des Landes Sitzung hält.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 31, 24, 'Feine Unterkleider fertigt sie an und verkauft sie, und Gürtel liefert sie dem Kaufmann.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 31, 25, 'Kraft und Würde sind ihr Gewand, und so sieht sie dem kommenden Tage unbesorgt entgegen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 31, 26, 'Den Mund öffnet sie zu einsichtsvoller Rede, und freundliche Unterweisung liegt auf ihrer Zunge.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 31, 27, 'Sie überwacht alle Vorgänge in ihrem Hause und ißt nie das Brot des Müßiggangs.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 31, 28, 'Ihre Söhne treten hin und preisen sie glücklich; ihr Gatte tritt hin und rühmt sie:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 31, 29, '»Es gibt wohl viele Frauen, die Tüchtiges geleistet haben, doch du übertriffst sie alle!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 31, 30, 'Anmut ist trügerisch, und Schönheit vergeht, aber ein gottesfürchtiges Weib ist des Lobes wert.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 31, 31, 'Laßt sie den Lohn ihres Schaffens genießen, und was sie geleistet hat, möge ihren Ruhm in den Toren verkünden!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 1, 1, '(Dies sind) die Worte des Predigers, des Sohnes Davids, des Königs in Jerusalem.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 1, 2, 'O Nichtigkeit der Nichtigkeiten! sagt der Prediger; o Nichtigkeit der Nichtigkeiten: alles ist nichtig!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 1, 3, 'Welchen Gewinn hat der Mensch von all seiner Mühe, mit der er sich unter der Sonne abmüht?');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 1, 4, 'Ein Geschlecht geht dahin, und ein anderes kommt, doch die Erde steht ewig unbewegt.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 1, 5, 'Die Sonne geht auf, und die Sonne geht unter und eilt an denselben Ort zurück, wo sie aufging.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 1, 6, 'Der Wind geht nach Süden und dreht sich nach Norden; immerfort kreisend weht der Wind, und zu seinen Kreisläufen kehrt der Wind zurück.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 1, 7, 'Alle Flüsse laufen ins Meer, und das Meer wird doch nicht voll; an den Ort, wohin die Flüsse einmal fließen, dahin fließen sie immer wieder.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 1, 8, 'Alle Dinge mühen sich ab: kein Mensch vermag es auszusprechen; das Auge wird des Sehens nicht satt und das Ohr nicht voll vom Hören.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 1, 9, 'Was gewesen ist, dasselbe wird wieder sein, und was geschehen ist, dasselbe wird wieder geschehen; es gibt nichts Neues unter der Sonne.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 1, 10, 'Kommt (einmal) etwas vor, von dem man sagen möchte: »Siehe, dies hier ist etwas Neues!«, so ist es doch längst dagewesen in den Zeitläuften, die vor uns waren:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 1, 11, 'es ist nur kein Andenken an die früheren Zeiten geblieben, und auch für die späteren, die künftig sein werden, wird kein Andenken übrigbleiben bei denen, die noch später kommen werden.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 1, 12, 'Ich, der Prediger, bin König über Israel in Jerusalem gewesen');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 1, 13, 'und habe es mir angelegen sein lassen, vermittels der Weisheit alles zu erforschen und zu ergründen, was unter dem Himmel geschieht: ein leidiges Geschäft, das Gott den Menschenkindern auferlegt hat, sich damit abzuquälen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 1, 14, 'Ich habe alles Arbeiten beobachtet, das unter der Sonne betrieben wird, und siehe da: alles war nichtig und ein Haschen nach Wind.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 1, 15, 'Krummes kann doch nicht als gerade gelten, und was lückenhaft ist, darf man nicht als voll rechnen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 1, 16, 'Ich dachte bei mir in meinem Herzen also: »Fürwahr, ich habe mir größere Schätze der Weisheit erworben als alle, die vor mir über Jerusalem gewesen sind, und mein Geist hat sich eine Fülle von Weisheit und Erkenntnis angeeignet!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 1, 17, 'Als ich mich aber daranmachte, zu erkennen, was Weisheit sei, und zu erkennen, was Torheit und Unverstand sei, da wurde es mir klar, daß auch dies nur ein Haschen nach Wind ist;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 1, 18, 'denn wo viel Weisheit ist, da ist auch viel Verdruß, und mit der Zunahme der Erkenntnis wächst auch der Schmerz.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 2, 1, 'Da dachte ich bei mir in meinem Herzen: »Wohlan denn, ich will es einmal mit der Freude und dem Lebensgenuß versuchen!« Aber siehe, auch das war nichtig.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 2, 2, 'Vom Lachen mußte ich sagen: »Unsinn ist das!« und von der Freude: »Wozu soll die dienen?«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 2, 3, 'Ich faßte den Entschluß, meinem Leibe mit Wein gütlich zu tun – allerdings so, daß mein Verstand die Leitung mit Besonnenheit behielte – und mich an die Torheit zu halten, bis ich sähe, was für die Menschenkinder das Beste sei, daß sie es täten unter dem Himmel während der ganzen Dauer ihres Lebens.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 2, 4, 'Ich unternahm große Werke: ich baute mir Häuser, pflanzte mir Weinberge,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 2, 5, 'legte mir Gärten und Parke an und pflanzte darin Fruchtbäume jeder Art;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 2, 6, 'ich legte mir Wasserteiche an, um aus ihnen den Wald mit seinem üppigen Baumwuchs zu bewässern;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 2, 7, 'ich kaufte Knechte und Mägde, hatte auch Gesinde, das in meinem Hause geboren war, und besaß auch große Herden von Rindern und Kleinvieh, größere als irgend jemand vor mir sie in Jerusalem besessen hatte.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 2, 8, 'Ich häufte mir auch Silber und Gold an, die Schätze von Königen und Ländern, schaffte mir Sänger und Sängerinnen an und, was die Hauptlust der Menschen ist: Frauen über Frauen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 2, 9, 'So stand ich groß da und tat es allen zuvor, die vor mir in Jersualem gelebt hatten; dabei war mir auch meine Weisheit verblieben.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 2, 10, 'Nichts von allem, wonach meine Augen Verlangen trugen, versagte ich ihnen, keinen Wunsch ließ ich meinem Herzen unerfüllt; denn mein Herz sollte Freude haben von all meinem Schaffen, und das sollte mir der Lohn für alle meine Mühe sein.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 2, 11, 'Doch als ich nun alle Werke prüfend betrachtete, die meine Hände geschaffen, und die Mühe erwog, die ich auf ihre Ausführung verwandt hatte: ach, da war das alles nichtig und ein Haschen nach Wind, und es kommt nirgends ein Gewinn heraus unter der Sonne.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 2, 12, 'b Denn was wird der Mensch tun, der nach mir, dem Könige, kommen wird? Dasselbe, was man immer schon getan hat. a Hierauf wandte ich mich dazu, den Wert der Weisheit neben der Torheit und dem Unverstand festzustellen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 2, 13, 'Da sah ich denn ein, daß die Weisheit einen Vorzug vor der Torheit hat, wie das Licht einen Vorzug vor der Finsternis besitzt;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 2, 14, 'der Weise hat ja Augen im Kopf, während der Tor im Finstern wandelt. Zugleich erkannte ich aber auch, daß das gleiche Geschick alle (beide) trifft.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 2, 15, 'Da dachte ich bei mir in meinem Herzen: »Wenn mich dasselbe Geschick trifft wie den Toren, wozu bin ich dann so besonders weise gewesen?« So mußte ich mir denn sagen, daß auch dies nichtig sei.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 2, 16, 'Denn der Weise hinterläßt ebensowenig wie der Tor ein ewiges Gedenken, weil ja in den künftigen Tagen alles längst vergessen sein wird; ach ja, wie stirbt doch der Weise samt dem Toren dahin!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 2, 17, 'So wurde mir denn das Leben verhaßt, denn mir mißfiel alles Tun, das unter der Sonne stattfindet; alles ist ja nichtig und ein Haschen nach Wind!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 2, 18, 'Da wurde mir alles Bemühen, das ich bis dahin unter der Sonne aufgewandt hatte, verleidet, weil ich ja das durch meine Mühe Geschaffene einem (andern) überlassen muß, der mein Nachfolger sein wird;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 2, 19, 'und wer kann wissen, ob der weise sein wird oder ein Tor? Und doch wird er schalten und walten über alle meine Mühe, über das, was ich durch meine Weisheit unter der Sonne zustande gebracht habe. Auch das ist nichtig.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 2, 20, 'So kam es denn mit mir dahin, daß ich mich der Verzweiflung überließ wegen all der Mühe, die ich unter der Sonne aufgewandt hatte.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 2, 21, 'Denn es kommt vor, daß ein Mensch sich mit Weisheit, Einsicht und Tüchtigkeit abgemüht hat und dann den Ertrag seiner Arbeit einem (andern) überlassen muß, der sich gar nicht darum gemüht hat. Auch das ist nichtig und ein großer Übelstand.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 2, 22, 'Denn welchen Nutzen hat der Mensch von all seiner Mühe und von dem Streben seines Geistes, womit er sich unter der Sonne abmüht,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 2, 23, 'wenn alle seine Tage leidvoll sind und Widerwärtigkeit sein ganzes Schaffen und nicht einmal bei Nacht sein Geist Ruhe findet? Auch das ist nichtig.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 2, 24, 'So gibt es denn für den Menschen nichts Besseres, als daß er ißt und trinkt und sein Herz bei seiner Mühsal guter Dinge sein läßt. Freilich habe ich erkannt, daß auch dies von der Hand Gottes abhängt;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 2, 25, 'denn wer kann essen und wer genießen ohne sein Zutun?');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 2, 26, 'Denn einem Menschen, der ihm wohlgefällt, gibt Gott Weisheit, Einsicht und Freude, dem Sünder aber gibt er das leidige Geschäft, zu sammeln und zusammenzuscharren, um es hernach dem zu überlassen, der Gott wohlgefällig ist. Auch das ist nichtig und ein Haschen nach Wind.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 3, 1, 'Jegliches Ding hat seine Zeit und alles Vornehmen unter dem Himmel seine Stunde.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 3, 2, 'Das Geborenwerden hat seine Zeit und ebenso das Sterben; das Pflanzen hat seine Zeit und ebenso das Ausraufen des Gepflanzten;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 3, 3, 'das Töten hat seine Zeit und ebenso das Heilen; das Einreißen hat seine Zeit und ebenso das Aufbauen;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 3, 4, 'das Weinen hat seine Zeit und ebenso das Lachen; das Klagen hat seine Zeit und ebenso das Tanzen;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 3, 5, 'das Hinwerfen von Steinen hat seine Zeit und ebenso das Sammeln von Steinen; das Liebkosen hat seine Zeit und ebenso das Meiden der Liebkosung;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 3, 6, 'das Suchen hat seine Zeit und ebenso das Verlieren; das Aufbewahren hat seine Zeit und ebenso das Wegwerfen;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 3, 7, 'das Zerreißen hat seine Zeit und ebenso das Zusammennähen; das Schweigen hat seine Zeit und ebenso das Reden;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 3, 8, 'das Lieben hat seine Zeit und ebenso das Hassen; der Krieg hat seine Zeit und ebenso der Friede.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 3, 9, 'Welchen Gewinn hat also der Tätige davon, daß er sich abmüht?');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 3, 10, 'Ich habe die (leidige) Aufgabe betrachtet, die Gott den Menschenkindern gestellt hat, sich damit abzuplagen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 3, 11, 'Alles hat Gott vortrefflich eingerichtet zu seiner Zeit, ja auch die Ewigkeit hat er ihnen ins Herz gelegt, nur daß der Mensch das Tun Gottes von Anfang bis zu Ende nicht zu durchschauen vermag.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 3, 12, 'So habe ich denn erkannt, daß es nichts Besseres für den Menschen gibt, als sich der Freude hinzugeben und sich gütlich zu tun in seinem Leben;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 3, 13, 'freilich auch, daß, sooft jemand ißt und trinkt und zum Genießen bei all seiner Mühsal kommt, daß das auch eine Gabe Gottes ist.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 3, 14, 'Ich habe erkannt, daß alles, was Gott tut, ewige Geltung hat: man kann da nichts hinzufügen und nichts davon wegnehmen; und das hat Gott so eingerichtet, damit man sich vor ihm fürchte.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 3, 15, 'Was da ist, das ist schon längst gewesen, und was geschehen wird, ist längst dagewesen; denn Gott sucht das Entschwundene wieder hervor.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 3, 16, 'Weiter aber habe ich unter der Sonne wahrgenommen: an der Stätte des Rechts, da herrschte das Unrecht, und an der Stätte der Gerechtigkeit, da herrschte die Gesetzlosigkeit.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 3, 17, 'Da dachte ich bei mir in meinem Sinn: »Den Gerechten wie den Gottlosen wird Gott richten; denn er hat für jedes Vorhaben und für alles Tun eine Zeit festgesetzt.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 3, 18, 'Da dachte ich bei mir selbst: »Um der Menschenkinder willen ist das so gefügt, damit Gott sie prüft und damit sie einsehen, daß sie an und für sich den Tieren gleichstehen.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 3, 19, 'Denn das Schicksal der Menschen und das Schicksal der Tiere ist ein und dasselbe: die einen sterben so gut wie die anderen, und sie haben alle den gleichen Odem, und einen Vorzug des Menschen vor den Tieren gibt es nicht:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 3, 20, 'alles geht an denselben Ort; alles ist vom Staube geworden, und alles kehrt zum Staube zurück.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 3, 21, 'Wer weiß denn vom Lebensodem des Menschen, ob er aufwärts in die Luft emporsteigt, und vom Lebensodem des Tieres, ob er nach unten zur Erde hinabfährt?');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 3, 22, 'So habe ich denn eingesehen, daß es für den Menschen nichts Besseres gibt, als daß er sich freue bei seinem Tun; ja das ist sein Teil; denn wer wird ihn dahin bringen, daß er Einsicht in das gewinnt, was nach ihm sein wird?');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 4, 1, 'Und wiederum betrachtete ich alle Bedrückungen, die unter der Sonne verübt werden; ich sah da die Tränen der Bedrückten, die keinen Tröster hatten und von seiten ihrer Bedrücker Gewalttat erlitten, ohne daß jemand Trost für sie hatte.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 4, 2, 'Da pries ich die Toten, die längst gestorben sind, glücklicher als die Lebenden, die jetzt noch am Leben sind;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 4, 3, 'aber glücklicher als beide pries ich den, der noch nicht ins Dasein getreten ist und deshalb das böse Treiben noch nicht gesehen hat, das unter der Sonne stattfindet.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 4, 4, 'Weiter habe ich eingesehen, daß alle Mühe und aller Erfolg, den man bei seiner Tätigkeit hat, nur eine Folge der Eifersucht des einen gegen den andern ist. Auch das ist nichtig und ein Haschen nach Wind.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 4, 5, 'Der Tor dagegen legt die Hände ineinander und zehrt von seinem eigenen Fleisch:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 4, 6, '»Besser ist eine Hand voll Ruhe als beide Fäuste voll Arbeit und Haschen nach Wind.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 4, 7, 'Ich habe auch noch ein anderes Beispiel eitlen Mühens unter der Sonne gesehen:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 4, 8, 'Da ist einer, der ganz allein steht ohne Freunde und Genossen; auch einen Sohn und Bruder hat er nicht; gleichwohl wird er nicht müde, sich zu plagen, und seine Augen sehen sich am Reichtum nicht satt (er müßte sich doch sagen): »Für wen mühe ich mich ab und versage mir jeden Genuß?« Auch das ist nichtig und ein verfehltes Tun.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 4, 9, 'Besser sind zwei daran als ein Einzelner, weil ihnen ein guter Lohn für ihre Mühe zuteil wird;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 4, 10, 'denn wenn sie fallen, so hilft der eine dem andern wieder auf. Wehe aber dem Einzelnen! Wenn er hinfällt, ist kein Zweiter da, um ihm wieder aufzuhelfen!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 4, 11, 'So auch, wenn zwei zusammen schlafen, so wärmen sie sich gegenseitig; aber ein Einzelner, wie soll dem warm werden?');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 4, 12, 'Und während jemand einen Einzelnen überwältigen mag, so werden sie zu zweit vor ihm standhalten, und (gar) eine dreifache Schnur wird nicht so bald zerreißen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 4, 13, 'Ein armer, aber weiser Jüngling ist mehr wert als ein alter, jedoch törichter König, der keine Belehrung mehr annimmt.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 4, 14, 'Denn aus dem Gefängnis gelangte er auf den Thron, obgleich er unter der Regierung jenes in Armut geboren war.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 4, 15, 'Ich sah alle Lebenden, die unter der Sonne wandelten, die Partei des Jünglings ergreifen, der an jenes Stelle treten sollte:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 4, 16, 'endlos war die Menge aller derer, die ihn sich zum Führer erkoren hatten. Gleichwohl freuten die Späteren sich seiner nicht mehr. So war denn auch dieses nichtig und ein Haschen nach Wind.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 4, 17, 'Gib acht auf deinen Fuß, wenn du zum Hause Gottes gehst; denn hintreten, um zu hören, ist besser, als wenn die Toren Opfer darbringen: sie wissen ja nichts weiter als Böses zu tun. –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 5, 1, 'Sei nicht vorschnell mit deinem Munde, und laß dich durch den Drang deines Herzens nicht dazu bringen, ein Wort vor Gott auszusprechen; denn Gott ist im Himmel, du aber bist auf der Erde; darum mache wenig Worte!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 5, 2, 'Denn wo Vielgeschäftigkeit ist, da kommen Träume; und wo viele Worte sind, da entsteht Torengeschwätz. –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 5, 3, 'Hast du Gott ein Gelübde dargebracht, so säume nicht, es zu erfüllen! Denn er hat kein Wohlgefallen an den Toren. Was du gelobt hast, das erfülle auch!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 5, 4, 'Besser ist es, kein Gelübde zu tun, als etwas zu geloben und es nicht zu erfüllen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 5, 5, 'Gestatte deinem Munde nicht, deine Person in Schuld zu bringen, und sage nicht vor dem Gottesdiener aus, daß eine Übereilung vorliege: warum soll Gott über etwas von dir Ausgesprochenes zürnen und das Werk deiner Hände mißlingen lassen?');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 5, 6, 'Denn wo viele Träume sind, da ist auch viel eitler Wortschwall. Vielmehr fürchte Gott!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 5, 7, 'Wenn du siehst, wie der Arme bedrückt wird und wie es mit Recht und Gerechtigkeit in der Landschaft übel bestellt ist, so rege dich darüber nicht auf; denn über dem Hohen steht ein noch Höherer auf der Lauer, und ein Allerhöchster hält Wacht über sie alle.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 5, 8, 'Doch ein Vorteil für ein Land ist jedenfalls dies: ein König über bebautes Land.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 5, 9, 'Wer das Geld liebt, wird des Geldes nie satt, und wer am Reichtum seine Freude hat, ist unersättlich nach Einkünften; auch das ist nichtig.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 5, 10, 'Wenn das Gut sich mehrt, so mehren sich auch die, welche davon zehren; und welchen Nutzen hat sein Besitzer davon, als daß er die Augen daran weidet?');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 5, 11, 'Süß ist der Schlaf des Arbeiters, mag er wenig oder viel zu essen haben; den Reichen aber läßt die Übersättigung nicht zum Schlaf kommen. –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 5, 12, 'Es gibt ein ganz schlimmes Übel, das ich unter der Sonne beobachtet habe: Reichtum, der von seinem Besitzer zu seinem eigenen Unheil gehütet wird.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 5, 13, 'Geht nämlich solcher Reichtum durch irgendeinen Unglücksfall verloren, so behält der Sohn, den er erzeugt hat, nichts mehr im Besitz.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 5, 14, 'Nackt, wie er aus dem Schoß seiner Mutter hervorgekommen ist, muß er wieder davon, wie er gekommen ist, und kann für seine Mühe nicht das Geringste mitnehmen, um es in seinem Besitz zu behalten.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 5, 15, 'Ja, das ist auch ein schlimmer Übelstand: ganz so, wie er gekommen ist, muß er wieder davon. Welchen Gewinn hat er nun davon, daß er sich für den Wind abgemüht hat?');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 5, 16, 'Dazu verlebt er alle seine Tage im Dunkel und trübselig, bei viel Verdruß, Krankheit und Aufregung.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 5, 17, '(Vernimm dagegen) was ich als gut, als schön befunden habe: daß der Mensch ißt und trinkt und es sich wohl sein läßt bei all seiner Mühe, mit der er sich unter der Sonne plagt während der geringen Zahl der Lebenstage, die Gott ihm beschieden hat; denn das ist sein Teil.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 5, 18, 'Allerdings, wenn Gott irgendeinem Menschen Reichtum und irdische Güter verliehen und ihn in die glückliche Lage versetzt hat, davon zu genießen und sein Teil hinzunehmen und sich bei seiner Mühsal zu freuen, so ist das eine Gnadengabe Gottes.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 5, 19, 'Denn ein solcher wird nicht viel an (die Kürze) seiner Lebenstage denken, weil Gott (ihm) sein Wohlgefallen an der Freude seines Herzens bezeigt.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 6, 1, 'Es gibt einen Übelstand, den ich unter der Sonne beobachtet habe und der schwer auf dem Menschen lastet:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 6, 2, 'Da verleiht Gott jemandem Reichtum, irdische Güter und Ehre, so daß ihm für seine Person nichts fehlt von allem, wonach er Verlangen trägt; aber Gott gestattet ihm nicht, es zu genießen, sondern ein Fremder hat den Genuß davon: das ist bedauerlich und ein schwerer Übelstand!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 6, 3, 'Wenn jemand Vater von hundert Kindern würde und viele Jahre lebte, so daß die Zahl seiner Lebenstage groß wäre, er aber nicht dazu käme, seines Lebens froh zu werden [und ihm sogar kein Begräbnis zuteil würde], so sage ich: Besser als er ist ein Totgeborener daran.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 6, 4, 'Denn ein solcher kommt als ein Nichts auf die Welt und geht im Dunkel hinweg, und sein Name bleibt mit Dunkel bedeckt;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 6, 5, 'auch hat er die Sonne nicht gesehen und weiß nichts von ihr; aber in Beziehung auf Ruhe hat er einen Vorzug vor jenem.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 6, 6, 'Ja, wenn jemand auch zweimal tausend Jahre lebte, ohne jedoch seines Lebens froh zu werden – fährt nicht alles dahin an denselben Ort?');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 6, 7, 'Alles Mühen des Menschen geschieht für den Mund, und dennoch wird dessen Begierde nicht gestillt.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 6, 8, 'Doch welchen Vorzug hat hierin der Weise vor dem Toren? Den des Armen, der sich auf die richtige Lebensführung versteht.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 6, 9, 'Besser ist das Anschauen mit den Augen als das Umherschweifen mit der Begierde. Auch das ist nichtig und ein Haschen nach Wind.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 6, 10, 'Alles, was geschieht, ist längst im voraus bestimmt, und von vornherein steht fest, wie es einem Menschen ergehen wird, und niemand vermag den zur Rechenschaft zu ziehen, der stärker ist als er.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 6, 11, 'Wohl findet da vieles Gerede statt, aber das schafft nur noch mehr Nichtigkeit: welchen Nutzen hat der Mensch davon?');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 6, 12, 'Denn wer weiß, was dem Menschen im Leben gut ist während der wenigen Tage seines nichtigen Lebens, die er dem Schatten vergleichbar verbringt? Denn wer tut dem Menschen kund, was nach ihm sein wird unter der Sonne?');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 7, 1, 'Besser ist ein guter Name als kostbares Salböl, und besser der Todestag als der Geburtstag. –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 7, 2, 'Besser ist es, in ein Trauerhaus zu gehen, als zu einem fröhlichen Gastmahl; denn jenes weist auf das Ende aller Menschen hin, und wer noch im Leben steht, möge sich das zu Herzen nehmen!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 7, 3, 'Besser Unmut als Lachen; denn bei ernstem Angesicht steht es gut um das Herz.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 7, 4, 'Das Herz der Weisen weilt im Trauerhause, aber das Herz der Toren im Hause der Freude. –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 7, 5, 'Besser ist es, auf das Schelten eines Weisen zu hören, als daß man die Lieder der Toren anhört;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 7, 6, 'denn wie das Knistern des Reisigs unter dem Kessel, so ist das Lachen des Toren. Auch das ist nichtig. –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 7, 7, 'Denn unredlicher Gewinn macht den Weisen zum Toren, und Bestechungsgeschenke verderben das Herz. –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 7, 8, 'Besser ist der Ausgang einer Sache als ihr Anfang, besser Langmut als Hochmut.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 7, 9, 'Übereile dich nicht, in ärgerliche Stimmung zu geraten; denn der Ärger hat seine Wohnung im Busen der Toren. –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 7, 10, 'Frage nicht, wie es komme, daß die früheren Zeiten besser waren als die jetzigen; denn nicht die Weisheit gibt dir diese Frage ein.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 7, 11, 'Weisheit ist so gut wie ein Erbbesitz, und Einsicht ein Gewinn für die, welche das Sonnenlicht sehen;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 7, 12, 'denn im Schatten der Weisheit ist man ebenso geborgen wie im Schatten des Geldes; aber der Vorzug der Erkenntnis besteht darin, daß die Weisheit ihrem Besitzer das Leben erhält. –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 7, 13, 'Betrachte das Walten Gottes; denn wer kann etwas gerade machen, was er gekrümmt hat?');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 7, 14, 'Am guten Tage sei guter Dinge, und am bösen Tage, da erwäge: auch diesen hat Gott ebenso wie jenen gemacht, damit der Mensch nicht ausfindig mache, was nach ihm geschieht.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 7, 15, 'Alles (beides) habe ich in den Tagen meines eitlen (Erdenlebens) gesehen: mancher Gerechte geht trotz seiner Gerechtigkeit zugrunde, und mancher Gottlose bringt es trotz seiner Bosheit zu langem Leben.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 7, 16, 'Verhalte dich nicht allzu gerecht und gebärde dich nicht übertrieben weise: warum willst du selbst Schaden nehmen?');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 7, 17, 'Handle aber auch nicht allzu gottlos und zu töricht: warum willst du vor der Zeit sterben?');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 7, 18, 'Es ist am besten, wenn du an dem einen festhältst und auch das andere nicht fahren läßt; denn der Gottesfürchtige entgeht allem beidem. –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 7, 19, 'Die Weisheit verleiht dem Weisen mehr Kraft als zehn Machthaber, die in der Stadt sind.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 7, 20, 'Denn kein Mensch auf Erden ist so gerecht, daß er nur Gutes täte und niemals sündigte.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 7, 21, 'Gib auch nicht auf alles Gerede acht, das man führt; du könntest sonst einmal deinen eigenen Knecht dich schmähen hören;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 7, 22, 'denn gar manchmal – du wirst dir dessen wohl bewußt sein – hast du selbst andere geschmäht.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 7, 23, 'Alles dies habe ich mit der Weisheit erprobt; ich dachte: »Ich will die Weisheit gewinnen!«, doch sie blieb fern von mir.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 7, 24, 'In weiter Ferne liegt der Grund aller Dinge und tief, ja tief verborgen: wer kann ihn ausfindig machen?');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 7, 25, 'Immer wieder, wenn ich mich dazu wandte und mein Streben darauf richtete, Erkenntnis und ein richtiges Urteil zu gewinnen und mit dem Suchen nach Weisheit zu einem Abschluß zu kommen und einzusehen, daß die Gottlosigkeit Torheit ist und die Torheit Wahnsinn,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 7, 26, 'da fand ich etwas, das bitterer ist als der Tod, nämlich das Weib, das einem Fangnetz gleicht und dessen Herz Schlingen, dessen Arme Fesseln sind. Wer Gott wohlgefällt, der entgeht ihr, doch wer sündigt, wird von ihr gefangen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 7, 27, '»Siehe, dies habe ich gefunden«, sagt der Prediger, »indem ich eine Erfahrung zu der andern fügte, um ein sicheres Urteil zu gewinnen;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 7, 28, 'was aber meine Seele immer noch sucht und was ich nicht gefunden habe, ist dies: Unter tausend habe ich wohl einen Mann gefunden, aber ein Weib habe ich unter ihnen allen nicht gefunden.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 7, 29, 'Allerdings, wisse wohl: dies habe ich gefunden, daß Gott die Menschen gerade geschaffen hat; sie selbst aber suchen viele verwerfliche Künste.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 8, 1, 'Wer ist wie der Weise und wer versteht sich auf die Deutung der Dinge? Die Weisheit erleuchtet das Angesicht eines Menschen, so daß die Härte seiner Gesichtszüge verwandelt wird.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 8, 2, 'Ich sage: Beobachte das Gebot des Königs, und zwar wegen des bei Gott geleisteten Treueides.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 8, 3, 'Übereile dich nicht, ihm aus den Augen zu gehen, und laß dich auf keine böse Sache ein; denn er setzt alles durch, was er will,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 8, 4, 'weil ja das Wort des Königs eine Macht ist; und wer darf zu ihm sagen: »Was tust du da?«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 8, 5, 'Wer das Gebot beobachtet, wird nichts Schlimmes erleben; wohl aber wird das Herz des Weisen die zur bestimmten Zeit eintretende richterliche Entscheidung erleben.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 8, 6, 'Denn für jede Sache gibt es eine zur bestimmten Zeit eintretende Entscheidung; doch der Übelstand lastet schwer auf dem Menschen,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 8, 7, 'daß er die Zukunft nicht kennt; denn wer könnte ihm ansagen, wie es in Zukunft sein wird?');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 8, 8, 'Kein Mensch hat Macht über den Wind, so daß er den Wind aufhalten könnte; ebensowenig ist jemand Herr über den Tag seines Todes; auch gibt es im Kriege keine Entlassung; und ebenso läßt die Gesetzesübertretung den nicht entkommen, der sie übt.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 8, 9, 'Alles dieses habe ich gesehen, indem ich mein Augenmerk auf alles Geschehen richtete, das unter der Sonne stattfindet, solange ein Mensch über andere herrscht zu ihrem Unglück.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 8, 10, 'Dabei habe ich auch gesehen, daß Gottlose begraben wurden und zur Ruhe eingingen, während Leute, die rechtschaffen gelebt hatten, von der heiligen Stätte wegziehen mußten und in der Stadt in Vergessenheit gerieten; auch das ist nichtig.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 8, 11, 'Weil der Urteilsspruch über böse Taten nicht schnell vollstreckt wird, darum ist das Herz der Menschen mit Mut erfüllt, Böses zu tun;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 8, 12, 'außerdem (auch aus dem Grunde), weil ein Sünder hundertmal Böses tut und doch lange am Leben bleibt – obgleich ich weiß, daß es den Gottesfürchtigen gutgehen wird, weil sie sich vor ihm fürchten,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 8, 13, 'während es dem Gottlosen nicht gutgehen und er seine Tage nicht wie ein Schatten in die Länge ziehen wird, weil er sich vor Gott nicht fürchtet.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 8, 14, 'Es gibt etwas Nichtiges, das auf Erden vorkommt, nämlich daß es Gerechte gibt, denen es so ergeht, wie es den Gottlosen nach ihrem Tun ergehen müßte, und daß es manchen Gottlosen so ergeht, wie es bei den Gerechten nach ihrem Tun der Fall sein müßte. Da habe ich mir gesagt, daß auch dies nichtig sei.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 8, 15, 'So lobe ich mir denn die Freude, weil es für den Menschen nichts Besseres unter der Sonne gibt als zu essen und zu trinken und guter Dinge zu sein; und dies möge ihn bei seiner Mühsal begleiten während der Tage seines Lebens, die Gott ihm unter der Sonne vergönnt.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 8, 16, 'Sooft ich mein Streben darauf richtete, zur Erkenntnis der Weisheit zu gelangen und alles Tun, das auf der Erde vor sich geht, zu beobachten,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 8, 17, 'habe ich bezüglich des ganzen göttlichen Waltens erkannt, daß der Mensch, mag er auch seinen Augen weder bei Tag noch bei Nacht Schlaf zu finden vergönnen, das Walten, das sich unter der Sonne vollzieht, nicht zu ergründen vermag [insofern der Mensch trotz aller Mühe, mit der er es zu erforschen sucht, es doch nicht ergründet]. Denn auch wenn der Weise es zu erkennen vermeint, vermag er es doch nicht zu ergründen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 9, 1, 'Ja, auf dies alles habe ich mein Augenmerk gerichtet und dies alles mir klar zu machen gesucht, daß nämlich die Gerechten und die Weisen mit ihrem ganzen Tun in der Hand Gottes sind. Der Mensch weiß weder, ob ihm Liebe oder Haß begegnen wird: alles ist vor ihm (in der Zukunft) verhüllt.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 9, 2, 'Dasselbe Geschick trifft alle ohne Unterschied: das gleiche Los wird allen zuteil, dem Gerechten wie dem Gottlosen, dem Reinen wie dem Unreinen, dem, der opfert, wie dem, der nicht opfert; dem Guten geht es wie dem Sünder und dem, der schwört, wie dem, der sich vor dem Schwören scheut.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 9, 3, 'Das ist ein Übelstand bei allem, was unter der Sonne geschieht, daß allen das gleiche Geschick beschieden ist und auch daß das Herz der Menschenkinder voll Bosheit ist und Unverstand in ihrem Herzen wohnt, solange sie leben; danach aber geht’s zu den Toten.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 9, 4, 'Denn solange einer überhaupt noch zu den Lebenden gehört, so lange hat er noch etwas zu hoffen; denn ein lebender Hund ist mehr wert als ein toter Löwe.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 9, 5, 'Die Lebenden wissen doch noch, daß sie sterben werden, die Toten aber wissen überhaupt nichts und haben auch keinen Lohn mehr zu erwarten; sogar ihr Andenken wird ja vergessen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 9, 6, 'Sowohl Lieben als Hassen und Eifern ist für sie längst vorbei, und sie nehmen in Ewigkeit keinen Anteil mehr an irgend etwas, das unter der Sonne vor sich geht.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 9, 7, 'Wohlan denn, iß dein Brot mit Freuden und trinke deinen Wein mit wohlgemutem Herzen! Denn Gott hat solches Tun bei dir von vornherein gutgeheißen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 9, 8, 'Trage allezeit weiße Kleider und laß das Salböl deinem Haupte nicht mangeln.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 9, 9, 'Genieße das Leben mit dem Weibe, das du liebgewonnen hast, an all deinen eitlen Lebenstagen, die Gott dir unter der Sonne vergönnt, alle deine eitlen Tage hindurch; denn das ist dein Anteil am Leben und (der Lohn) für die Mühe, mit der du dich unter der Sonne abmühst.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 9, 10, 'Alles, was deine Hand mit deiner Kraft zu leisten vermag, das tu; denn in der Unterwelt, wohin dein Weg geht, gibt es kein Schaffen und keine Überlegung mehr, weder Erkenntnis noch Weisheit.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 9, 11, 'Wiederum habe ich unter der Sonne gesehen, daß nicht dem Schnellsten der Sieg im Wettlauf und nicht dem Tapfersten der Sieg im Kriege zuteil wird, auch nicht den Weisen das Brot und nicht den Verständigen der Reichtum, auch nicht den Einsichtsvollen die Gunst, sondern sie sind alle von Zeit und Umständen abhängig.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 9, 12, 'Der Mensch kennt ja nicht einmal die ihm bestimmte Zeit; nein, wie die Fische, die im Unglücksnetz sich fangen, und wie die Vögel, die von der Schlinge erfaßt werden, ebenso werden auch die Menschenkinder zur Zeit des Unglücks umstrickt, wenn es plötzlich über sie hereinbricht.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 9, 13, 'Und doch habe ich folgenden Fall von Weisheit unter der Sonne erlebt, und er hat einen tiefen Eindruck auf mich gemacht:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 9, 14, 'Es war eine kleine Stadt, in der sich nur wenige Leute befanden; da zog ein mächtiger König gegen sie heran, schloß sie rings ein und ließ gewaltige Belagerungswerke gegen sie aufführen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 9, 15, 'Nun fand sich in ihr ein armer, aber weiser Mann, der die Stadt durch seine Weisheit rettete; aber kein Mensch denkt mehr an diesen armen Mann.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 9, 16, 'Da sagte ich mir: »Weisheit ist (zwar) besser als Stärke, aber die Weisheit des Armen wird verachtet, und seine Worte bleiben ungehört.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 9, 17, 'Worte der Weisen, die man in Ruhe anhört, sind mehr wert als das Brüllen eines Herrschers unter Toren.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 9, 18, 'Weisheit ist besser als Kriegsgerät; aber ein einziger Bösewicht kann viel Gutes verderben.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 10, 1, 'Tote Fliegen machen ranzig und trübe das Öl des Salbenmischers; so verderbt ein wenig Torheit den Wert der Weisheit. –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 10, 2, 'Der Sinn des Weisen ist auf das Rechte gerichtet und der Sinn des Toren auf das Verkehrte;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 10, 3, 'und wo der Tor auch gehen mag, auf Schritt und Tritt, versagt sein Verstand, so daß er sich allen Leuten als Toren zu erkennen gibt. –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 10, 4, 'Wenn der Unmut des Herrschers gegen dich aufsteigt, so verlaß darum deinen Platz nicht; denn Gelassenheit verhütet schwere Verfehlungen. –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 10, 5, 'Es gibt einen Übelstand, den ich unter der Sonne wahrgenommen habe, nämlich ein verfehltes Verfahren, das von einem Machthaber ausgeht:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 10, 6, 'Toren werden auf große Höhe gestellt, und Reiche müssen unten sitzen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 10, 7, 'Ich habe Sklaven hoch zu Roß gesehen und Fürsten wie Sklaven zu Fuß einhergehen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 10, 8, 'Wer eine Grube gräbt, fällt selbst hinein, und wer Gemäuer einreißt, den kann eine Schlange beißen;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 10, 9, 'wer Steine bricht, kann sich an ihnen verletzen, wer Holz spaltet, kann sich dabei wehetun. –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 10, 10, 'Wenn eine Axt stumpf geworden ist und man die Schneide nicht schärft, dann muß man seine Kräfte um so mehr anstrengen; aber der Vorteil des Instandsetzens ist Weisheit. –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 10, 11, 'Wenn die Schlange beißt, ehe die Beschwörung stattgefunden hat, so hat der Beschwörer keinen Nutzen (von seiner Kunst).');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 10, 12, 'Worte aus dem Munde eines Weisen sind herzgewinnend, aber den Toren richten die eigenen Lippen zugrunde.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 10, 13, 'Der Anfang der Worte seines Mundes ist Torheit und das Ende seines Redens schlimmer Unsinn.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 10, 14, 'Auch macht der Tor viele Worte, obgleich kein Mensch weiß, was geschehen wird, und niemand ihm ansagen kann, was die Zukunft bringt.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 10, 15, 'Die Mühe, die der Tor aufwendet, macht ihn müde, so daß er den Weg nach der Stadt nicht mehr kennt.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 10, 16, 'Wehe dir, Land, dessen König ein Knabe ist und dessen Fürsten schon am Morgen schmausen!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 10, 17, 'Heil dir, du Land, dessen König ein Sproß von edler Herkunft ist und dessen Fürsten zu rechter Zeit tafeln, und zwar als Männer und nicht als Zecher! –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 10, 18, 'Infolge von Faulheit senkt sich das Gebälk (eines Hauses), und infolge von Lässigkeit der Hände tropft das Haus. –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 10, 19, 'Zur Belustigung veranstaltet man Mahlzeiten, und der Wein erheitert das Leben, und für Geld kann man alles haben. –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 10, 20, 'Selbst auf deinem Lager fluche dem Könige nicht, und einen Hochgestellten schmähe auch in deinem Schlafgemach nicht; denn die Vögel des Himmels könnten den Laut weitertragen und ein geflügelter Bote das Wort verraten.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 11, 1, 'Laß dein Brot über das weite Meer fahren; denn nach Verlauf vieler Tage wirst du es wieder heimkommen sehen;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 11, 2, 'doch verteile es auf sieben, ja auf acht Fahrten; denn du weißt nicht, was für Unglück sich auf der Erde ereignen mag. –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 11, 3, 'Wenn die Wolken mit Regen gefüllt sind, lassen sie ihn auf die Erde strömen; und wenn ein Baum nach Süden oder nach Norden fällt, so bleibt er an der Stelle liegen, wohin er gefallen ist. –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 11, 4, 'Wer (immerfort) auf den Wind achtet, kommt nicht zum Säen, und wer (immerfort) nach den Wolken sieht, kommt nicht zum Ernten. –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 11, 5, 'Gleichwie du nicht weißt, welches der Weg des Windes ist oder wie die Gebeine im Schoße der Schwangeren sich bilden, ebensowenig kennst du das Walten Gottes, der alles wirkt. –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 11, 6, 'Am Morgen säe deinen Samen, und bis zum Abend laß deine Hände nicht ruhen; denn du weißt nicht, was gelingen wird, ob dieses oder jenes, oder ob gar beides zugleich gut geraten wird. –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 11, 7, 'Und köstlich ist das Licht, und wohltuend ist’s für die Augen, die Sonne zu sehen;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 11, 8, 'denn wenn jemand auch viele Jahre lebt, möge er sich doch in ihnen allen der Freude hingeben und an die Tage der Finsternis denken, daß ihrer viele sein werden: alles, was kommt, ist nichtig.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 11, 9, 'Freue dich, Jüngling, in deiner Jugend und laß dein Herz guter Dinge sein in den Tagen deiner Jugendzeit; wandle die Wege, zu denen dein Herz sich hingezogen fühlt, und gehe dem nach, was deine Augen erschaun; doch wisse wohl, daß Gott um dies alles Rechenschaft von dir fordern wird!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 11, 10, 'Schlage dir den Unmut aus dem Sinn und halte dir das Leid vom Leibe fern, denn Jugend und dunkles Haar sind schnell entschwunden.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 12, 1, 'Und bleibe deines Schöpfers eingedenk in den Tagen deiner Jugendzeit, ehe die bösen Tage kommen und die Jahre sich einstellen, von denen du sagen wirst: »Sie gefallen mir nicht«;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 12, 2, 'ehe noch die Sonne und das Tageslicht, der Mond und die Sterne sich verfinstern und die Wolken wiederkehren nach dem Regen,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 12, 3, 'in der Zeit, wo die Hüter des Hauses zittern und die starken Männer sich krümmen; wo die Müllerinnen die Arbeit einstellen, weil ihrer wenige geworden sind, und die Fensterguckerinnen trübe werden;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 12, 4, 'wo die beiden Pforten nach der Straße hin geschlossen stehen, weil die Mühle mit weniger Geräusch geht, und man beim Hahnenschrei aufsteht und aller Liederklang verstummt;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 12, 5, 'auch vor jeder Steigung fürchtet man sich und sieht Schrecknisse auf jedem Wege; der Mandelbaum steht in Blüte, und die Heuschrecke schleppt sich träge dahin, und die Kaperwürze versagt ihre Wirkung – denn der Mensch geht hin zu seiner ewigen Behausung, und die Klageleute ziehen auf der Straße umher –;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 12, 6, 'ehe noch der silberne Faden zerreißt und die goldene Schale zerbricht und der Krug an der Quelle in Scherben geht und das Schöpfrad zertrümmert in den Brunnen fällt');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 12, 7, 'und der Staub zur Erde zurückkehrt als das, was er vorher gewesen ist, und der Odem zu Gott zurückkehrt, der ihn gegeben hat.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 12, 8, '»O Nichtigkeit der Nichtigkeiten!« ruft der Prediger aus, »alles ist nichtig!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 12, 9, 'Abgesehen davon, daß der Prediger ein Weiser war, hat er das Volk auch Erkenntnis gelehrt und war ein Denker und Forscher, der zahlreiche Sprüche verfaßt hat.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 12, 10, 'Der Prediger war bemüht, ansprechende Worte zu finden und zutreffende Weisungen niederzuschreiben, Aussprüche der Wahrheit.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 12, 11, 'Die Aussprüche der Weisen sind wie Treibstachel, und wie eingeschlagene Pflöcke stehen die einzelnen Sprüche beisammen, die von einem einzigen Hirten herrühren.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 12, 12, 'Und ferner noch: laß dich warnen, mein Sohn; des vielen Bücherschreibens ist kein Ende, und das viele Studieren verursacht dem Leibe Ermüdung. –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 12, 13, 'Laßt uns das Endergebnis des Ganzen hören: Fürchte Gott und halte seine Gebote! Denn das kommt jedem Menschen zu.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 12, 14, 'Denn Gott wird in dem Gericht, das über alles Verborgene ergeht, das Urteil über alles Tun sprechen, es sei gut oder böse (gewesen).');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 1, 1, 'Das Lied der Lieder, von Salomo.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 1, 2, 'O möcht’ er mich küssen mit seines Mundes Küssen! Denn deine Liebe ist wonniger als Wein!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 1, 3, 'Köstlich ist der Duft deiner Salben; wie ausgegossenes Salböl ist dein Name: drum haben die Mädchen dich lieb.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 1, 4, 'Zieh mich dir nach, komm, laß uns eilen! Führe mich, König, in deine Gemächer! »Wir wollen jubeln und deiner uns freuen, wollen preisen deine Liebe mehr als Wein!« Ach, inniglich lieben sie dich.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 1, 5, 'Gebräunt bin ich, aber doch schön, ihr Töchter Jerusalems, wie die Zelte von Kedar, wie Salomos Teppiche.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 1, 6, 'Seht mich nicht an, daß so gebräunt ich bin, daß die Sonne mich so verbrannt hat! Meiner Mutter Söhne waren böse auf mich, bestellten mich zur Hüterin der Weinberge; meinen eignen Weinberg hab’ ich nicht gehütet.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 1, 7, 'Tu mir kund, du, den meine Seele liebt: wo weidest du, wo lagerst du zur Mittagszeit? Denn warum soll als Verirrte ich erscheinen bei den Herden deiner Genossen? –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 1, 8, '»Wenn du das nicht weißt, du schönste unter den Weibern, so geh nur hinaus, den Spuren der Herde nach, und weide deine Zicklein bei den Zelten der Hirten!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 1, 9, '»Einem Prachtroß an Pharaos Prunkwagen vergleiche ich dich, meine Freundin:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 1, 10, 'reizend sind deine Wangen im Schmuck der Kettchen, dein Hals in den Perlenschnüren!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 1, 11, 'Goldene Kettchen lassen wir dir machen mit Kügelchen von Silber.« –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 1, 12, 'Solange der König noch in seinem Kreise weilte, gab meine Narde ihren Duft.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 1, 13, 'Mein Geliebter ist mir wie ein Myrrhenbündlein, das am Busen mir ruht;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 1, 14, 'ein Cyprusgebinde ist mir mein Geliebter in den Weinbergen von Engedi. –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 1, 15, '»O schön bist du, meine Freundin, ja, du bist schön! Deine Augen sind Taubenaugen.« –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 1, 16, '»O schön bist du, mein Geliebter, ja holdselig! Sieh, unser Lager ist frisches Grün;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 1, 17, 'unsres Hauses Gebälk sind Zedern, unser Getäfel Zypressen.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 2, 1, 'Ich bin eine Narzisse in Saron, eine Lilie der Täler. –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 2, 2, '»Wie eine Lilie unter den Dornen, so ist meine Freundin inmitten der Mädchen.« –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 2, 3, 'Wie ein Apfelbaum unter den Bäumen des Waldes, so ist mein Geliebter inmitten der Burschen; in seinem Schatten begehr’ ich zu weilen: seine Frucht ist meinem Gaumen gar süß.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 2, 4, 'In ein Weinhaus hat er mich (jetzt) geführt, doch sein Panier über mir ist die Liebe.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 2, 5, 'Stärkt mich doch mit Traubenkuchen! Erquickt mich mit Äpfeln, denn ich bin liebeskrank!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 2, 6, 'Seine Linke liegt unter meinem Haupt, und seine Rechte umfängt mich.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 2, 7, 'O laßt euch beschwören, ihr Töchter Jerusalems, bei den Gazellen oder den Hinden der Flur: störet die Liebe nicht auf und wecket sie nicht, bis es ihr selber gefällt!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 2, 8, 'Horch! mein Geliebter! Siehe, da kommt er, springt daher über die Berge, hüpft über die Hügel!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 2, 9, 'Mein Geliebter gleicht einer Gazelle oder dem jungen Hirsch. Ach sieh, da steht er hinter unsrer Mauer! Ich schaue durchs Fenster, gucke durchs Gitter!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 2, 10, 'Mein Geliebter hebt an und ruft mir zu: »Steh auf, meine Freundin, meine Schöne, und komm!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 2, 11, 'Sieh nur: der Winter ist dahin, die Regenzeit vorüber, ist vergangen!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 2, 12, 'Die Blumen zeigen sich auf der Flur, die Zeit der Gesänge ist da, und der Turteltaube Ruf läßt sich im Land wieder hören;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 2, 13, 'der Feigenbaum setzt seine Knospen an, und der Reben Blüte spendet ihren Duft. Steh auf, meine Freundin, meine Schöne, und komm!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 2, 14, 'Mein Täubchen im Felsengeklüft, im Versteck der Felswand, laß mich schauen dein Antlitz, deine Stimme mich hören! Denn süß ist deine Stimme, dein Antlitz so lieblich!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 2, 15, 'Fangt uns die Füchse, die kleinen Füchse, die Weinbergverwüster! Unsre Reben stehn ja in Blüte! –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 2, 16, 'Mein Geliebter ist mein, und ich bin sein; er weidet auf der Lilienau.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 2, 17, 'Bis der Abendwind haucht und die Schatten fliehn, ergehe dich frei, mein Geliebter, der Gazelle gleich, oder wie der junge Hirsch auf zerklüfteten Bergen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 3, 1, 'Auf meinem Lager in den Nächten, da sucht ich ihn, den meine Seele liebt: ich suchte ihn und fand ihn nicht.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 3, 2, '»Ich will mich doch aufmachen und die Stadt durchstreifen, in den Straßen und auf den Plätzen will ich ihn suchen, den meine Seele liebt!« Ich suchte ihn und fand ihn nicht.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 3, 3, 'Mich trafen die Wächter, die in der Stadt umhergehn: »Habt ihr ihn nicht gesehn, den meine Seele liebt?«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 3, 4, 'Kaum war ich an ihnen vorüber, da fand ich ihn, den meine Seele liebt. Ich hielt ihn fest und ließ ihn nicht los, bis ich ihn gebracht ins Haus meiner Mutter und ins Gemach der Guten, die mir das Leben gegeben.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 3, 5, 'Ich beschwöre euch, ihr Töchter Jerusalems, bei den Gazellen oder den Hinden der Flur: störet die Liebe nicht auf und wecket sie nicht, bis es ihr selber gefällt!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 3, 6, 'Was ist’s, das da heraufkommt aus der Trift wie Säulen von Rauch, umduftet von Myrrhe und Weihrauch, von allem Gewürzstaub des Krämers?');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 3, 7, 'Siehe da, es ist Salomos Tragbett, rings umgeben von sechzig Helden aus Israels Kriegern,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 3, 8, 'schwertbewaffnet sie alle und kriegsgeübt, ein jeder mit seinem Schwert an der Seite zum Schutz gegen nächtliche Schrecken!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 3, 9, 'Eine Prachtsänfte hat der König [Salomo] sich fertigen lassen aus Holz vom Libanon;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 3, 10, 'ihre Säulen hat er von Silber machen lassen, ihre Lehne von Gold; ihr Sitz ist von Purpurzeug, das Innere kunstvoll gestickt, ein Liebesbeweis der Töchter Jerusalems.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 3, 11, 'Kommt heraus, ihr Töchter Zions, beschaut euch den König Salomo in der Krone, mit der seine Mutter ihn gekrönt am Tage seiner Hochzeit und am Tage seiner Herzensfreude!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 4, 1, 'O du bist schön, meine Freundin, ja schön bist du! Deine Augen sind Taubenaugen hinter deinem Schleier hervor; dein Haar gleicht einer Ziegenherde, die vom Gileadberge herabwallt.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 4, 2, 'Deine Zähne sind gleich einer Herde von Schafen, die frischgeschoren der Schwemme entsteigen, allesamt zwillingsträchtig und keins von ihnen kinderlos.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 4, 3, 'Deine Lippen gleichen einer Purpurschnur, und dein Mund ist voll Anmut; wie der Spalt eines Granatapfels schimmern die Schläfen dir hinter dem Schleier hervor.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 4, 4, 'Wie Davids Turm ragt dein Hals, zur Fernsicht gebaut: tausend Schilde hangen an ihm, lauter Wehren von Helden.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 4, 5, 'Deine Brüste sind gleich einem Zwillingspaar junger Gazellen, die unter den Lilien weiden.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 4, 6, 'Bis der Abendwind haucht und die Schatten entfliehn, will zum Myrrhenberge ich gehn und zum Weihrauchhügel.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 4, 7, 'Wunderschön bist du, meine Freundin; nichts, nichts fehlt deinen Reizen!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 4, 8, 'Komm mit mir vom Libanon, Braut, mit mir vom Libanon, o komm! Steig herab vom Gipfel des Amana, vom Gipfel des Senir und Hermon, von den Lagerstätten der Löwen, von den Bergen der Panther.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 4, 9, 'Du hast mich bezaubert, meine bräutliche Schwester, du hast mich bezaubert mit einem deiner Blicke, mit einem der Kettchen an deinem Halsschmuck!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 4, 10, 'Wie schön ist deine Liebe, meine bräutliche Schwester, viel süßer ist deine Liebe als Wein, und deiner Salben Duft geht über alle Wohlgerüche!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 4, 11, 'Von Honigseim triefen deine Lippen, meine Braut; Honig und Milch birgst du unter deiner Zunge, und deiner Gewänder Duft ist wie der Duft des Libanons!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 4, 12, 'Ein wohlverschloßner Garten ist meine bräutliche Schwester, ein verschloßner Born, ein versiegelter Quell.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 4, 13, 'Alles, was an dir sproßt, ist ein Lusthain von Granaten mit den köstlichsten Früchten, Zyperblumen samt Narden,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 4, 14, 'Narde und Safran, Würzrohr und Zimt samt allerlei Weihrauchstauden, Myrrhe und Aloe nebst allen edelsten Balsamgewächsen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 4, 15, 'Eine Quelle im Garten bist du, ein Born voll sprudelnden Wassers, und Bäche, die vom Libanon rieseln.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 4, 16, 'Erwache, du Nordwind, und komm, du Südwind! Durchhauche meinen Garten, daß seine Düfte zerfließen! Mein Geliebter komme in seinen Garten und genieße seine köstlichen Früchte! –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 5, 1, '»Ich komme in meinen Garten, meine bräutliche Schwester; ich pflücke meine Myrrhe samt meinem Balsam, koste meine Wabe samt meinem Honig, ich trinke meinen Wein samt meiner Milch. Esset, ihr Freunde, trinkt und sättiget euch an Liebe!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 5, 2, 'Ich schlief, doch mein Herz war wach. Horch! Da klopft mein Geliebter! »Mach mir auf, meine Schwester, meine Freundin, mein Täubchen, meine Reine! Ach, mein Haupthaar ist voll von Tau, meine Locken voll von den Tropfen der Nacht!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 5, 3, '»Ich habe mein Kleid schon ausgezogen: wie sollt’ ich’s wieder anziehn?! Ich habe mir schon die Füße gewaschen: wie sollt’ ich sie wieder beschmutzen?!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 5, 4, 'Da streckte mein Geliebter die Hand durch das Guckloch (der Tür), da wallte das Herz mir auf vor Sehnsucht nach ihm, und die Sinne vergingen mir ob seiner Rede;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 5, 5, 'ich stand auf, um meinem Geliebten zu öffnen: da troffen meine Hände von Myrrhe und meine Finger vom köstlichsten Öl am Griff des Riegels.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 5, 6, 'Ich öffnete meinem Geliebten, doch mein Geliebter war fort, war verschwunden. Ich suchte ihn und fand ihn nicht; ich rief nach ihm, doch er gab mir keine Antwort.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 5, 7, 'Es trafen mich die Wächter, die in der Stadt umhergehn; sie schlugen mich, verwundeten mich, rissen den Schleier mir ab, die Wächter der Stadtmauer!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 5, 8, 'O laßt euch beschwören, ihr Töchter Jerusalems: wenn ihr antrefft meinen Geliebten, was sollt ihr ihm sagen? Daß krank ich bin vor Liebe!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 5, 9, '»Was hat denn dein Geliebter vor andern Geliebten voraus, du Schönste unter den Weibern? Was hat dein Geliebter vor andern Geliebten voraus, daß du uns so beschwörst?«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 5, 10, 'Mein Geliebter ist blendend weiß und braun, kenntlich unter vielen Tausenden.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 5, 11, 'Sein Haupt ist geläutertes Feingold, seine Locken wallende Ranken, schwarz wie Raben;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 5, 12, 'seine Augen wie Tauben an Wasserbächen, die, milchweiß gebadet, am Teichesrand sitzen;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 5, 13, 'seine Wangen wie Balsambeete, Gelände duftender Kräuter; seine Lippen sind wie Lilien, triefend von köstlichster Myrrhe;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 5, 14, 'seine Arme goldene Walzen, mit Edelsteinen dicht besetzt; sein Leib ein Kunstwerk von Elfenbein, mit Saphiren übersät;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 5, 15, 'seine Beine Säulen von weißem Marmor, ruhend auf Sockeln von Feingold; seine Gestalt (ragend) wie der Libanon, großartig wie die Zedern;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 5, 16, 'sein Gaumen lauter Süße und alles an ihm entzückend! Das ist mein Geliebter und das mein Freund, ihr Töchter Jerusalems!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 6, 1, '»Wohin ist denn dein Geliebter gegangen, du Schönste unter den Weibern? Wohin hat dein Geliebter sich begeben, damit wir ihn mit dir suchen?«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 6, 2, 'Mein Geliebter ist in seinen Garten hinabgegangen zu den Balsambeeten, um sich in den Anlagen zu ergehen und Lilien zu pflücken.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 6, 3, 'Ich gehöre meinem Geliebten, und mein Geliebter gehört mir: er weidet auf der Lilienau.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 6, 4, 'Schön bist du, meine Freundin, wie Thirza, lieblich wie Jerusalem, doch furchtbar wie Kriegerscharen!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 6, 5, 'Wende deine Augen weg von mir, denn sie bringen mich von Sinnen! Dein Haar gleicht einer Ziegenherde, die vom Gileadberge herabwallt.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 6, 6, 'Deine Zähne sind wie eine Herde Mutterschafe, die der Schwemme entsteigen, allesamt zwillingsträchtig und keins von ihnen ist kinderlos.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 6, 7, 'Wie der Spalt eines Granatapfels schimmern die Schläfen dir hinter dem Schleier hervor.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 6, 8, 'Ihrer sechzig sind Königinnen (bei Salomo) und achtzig Nebenfrauen und zahllos die Jungfrauen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 6, 9, 'Eine einzige ist meine Taube, meine Reine, die einziggeliebte Tochter ihrer Mutter, das Herzblatt der Guten, die ihr das Leben gegeben. Wenn die Mädchen sie sehen, so preisen diese sie glücklich, Königinnen und Nebenfrauen, und künden ihren Ruhm.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 6, 10, 'Wer ist diese, die da hervorglänzt wie das Morgenrot, schön wie der Vollmond, strahlend wie die Sonne, furchtbar wie Kriegerscharen?');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 6, 11, 'In den Nußgarten war ich hinabgegangen, um mich zu erfreun am jungen Grün des Tales, um nachzusehn, wie der Weinstock gesproßt, ob die Granaten Blüten getrieben hätten.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 6, 12, 'Unvermutet hat mein Verlangen mich geführt zu der Tochter eines Edlen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 7, 1, 'Wende dich, wende dich, Sulammith! Wende dich, wende dich, daß wir dich beschauen! »Was wollt ihr schauen an Sulammith beim kriegerischen Tanz?«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 7, 2, 'Wie schön sind deine Füße in den Schuhen, du Fürstenkind! Die Wölbungen deiner Hüften sind wie Halsgeschmeide, ein Werk von Künstlerhand;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 7, 3, 'dein Schoß eine runde Schale, der nie der Mischtrank fehlen darf; dein Leib ein Weizenhaufen, umsäumt von Lilien.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 7, 4, 'Deine Brüste sind gleich einem Zwillingspaar junger Gazellen;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 7, 5, 'dein Hals wie ein Turm von Elfenbein, deine Augen wie die Teiche von Hesbon am volksbelebten Tor; deine Nase wie der Libanonturm, der nach Damaskus schaut;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 7, 6, 'dein Haupt droben wie der Karmel und das herabwallende Haar deines Hauptes wie dunkler Purpur: ein König liegt gefangen in den Locken!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 7, 7, 'Wie bist du so schön und so hold, du Geliebte, du Wonnevolle!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 7, 8, 'Dein Wuchs da gleicht einer Palme und deine Brüste den Datteltrauben.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 7, 9, 'Ich dachte: Ersteigen will ich die Palme, ihre Fruchtrispen ergreifen; dann sollen deine Brüste mir sein wie Trauben am Weinstock und dein Atem süß wie der Duft von Äpfeln');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 7, 10, 'und dein Mund wie der köstlichste Wein, der meinem Gaumen glatt eingeht und mir über die Lippen und Zähne sanft hinfließt.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 7, 11, 'Ich gehöre meinem Geliebten, und nach mir sehnt sich sein Herz!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 7, 12, 'Komm, mein Geliebter, laß uns aufs Feld hinausgehn, in den Dörfern übernachten!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 7, 13, 'Frühmorgens brechen wir nach den Weinbergen auf, wollen nachsehn, ob der Weinstock sproßt, ob die Blüten sich erschließen, die Granaten blühen: dort will ich dir meine Liebe schenken.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 7, 14, 'Die Liebesäpfel duften süß, und über unsrer Tür sind köstliche Früchte jeder Art, heurige und jährige: für dich, mein Geliebter, hab’ ich sie aufbewahrt.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 8, 1, 'Ach, wärst du doch mein Bruder, hättest die Brust meiner Mutter gesogen! Träf’ ich dich dann auf der Straße, so dürft’ ich dich küssen, ohne daß jemand mich deshalb mißachtete.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 8, 2, 'Ich nähme dich dann mit mir ins Haus meiner Mutter; du müßtest mich unterweisen, ich gäbe dir Würzwein zu trinken, den Most meiner Granaten. –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 8, 3, 'Seine Linke liegt unter meinem Haupt, und seine Rechte umfängt mich.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 8, 4, 'Ich beschwöre euch, ihr Töchter Jerusalems: was wollt ihr die Liebe aufstören und wecken, eh’ es ihr selber gefällt!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 8, 5, 'Wer ist’s, die da heraufkommt aus der Trift, gelehnt an ihren Geliebten? »Unter dem Apfelbaum hab’ ich dich aufgeweckt; dort hat deine Mutter dich mit Schmerzen geboren, dort dich mit Schmerzen ans Licht der Welt gebracht.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 8, 6, '»O lege mich an dein Herz wie einen Siegelring, wie einen Siegelring an deinen Arm! Denn stark wie der Tod ist die Liebe und ihre Leidenschaft hart wie die Unterwelt; ihre Gluten sind Feuergluten, ihre Flammen wie Flammen Gottes.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 8, 7, 'Die mächtigsten Fluten vermögen die Liebe nicht auszulöschen und Ströme sie nicht fortzuschwemmen; böt’ einer auch alles Gut seines Hauses (als Kaufpreis) für die Liebe: man würde sein nur spotten.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 8, 8, 'Ein Schwesterlein haben wir, die noch keine Brüste hat; was sollen wir nun mit unserer Schwester tun am Tage, wo man um sie freit?');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 8, 9, 'Ist sie eine Mauer, so bauen wir eine Krönung von Silber auf ihr; ist sie aber ein Tor, so verrammeln wir es mit Zederbohlen.« –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 8, 10, 'Ich bin eine Mauer, und meine Brüste sind wie Türme; doch ich habe mich ihm gezeigt als friedlich übergebene Burg.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 8, 11, 'Einen Weinberg besaß Salomo in Baal-Hamon; er übergab den Weinberg den Hütern; jeder hatte für seinen Ertrag tausend Silberstücke zu zahlen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 8, 12, 'Über meinen Weinberg verfüge ich allein. Die tausend Silberstücke gehören dir, (mein) Salomo, und dazu noch zweihundert den Hütern seiner Früchte.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 8, 13, 'Die du wohnst in den Gärten, die Freunde lauschen: deine Stimme laß mich hören!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 8, 14, '»Enteile, mein Geliebter, und mache es wie die Gazelle oder wie der junge Hirsch auf den balsamduftenden Bergen!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 1, 1, '(Dies ist) die Offenbarung, die Jesaja, der Sohn des Amoz, über Juda und (besonders) Jerusalem geschaut hat in den Tagen der judäischen Könige Ussia, Jotham, Ahas und Hiskia.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 1, 2, 'Höret, ihr Himmel, und horche auf, o Erde! Denn der HERR redet: »Söhne habe ich großgezogen und zu Ehren gebracht, doch sie sind mir untreu geworden!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 1, 3, 'Ein Rind kennt seinen Besitzer und ein Esel die Krippe seines Herrn; aber Israel hat keine Erkenntnis, mein Volk ist ohne Einsicht!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 1, 4, 'Wehe dem sündigen Geschlecht, dem schuldbeladenen Volk, der Brut von Missetätern, den entarteten Söhnen! Den HERRN haben sie verlassen, den Heiligen Israels verworfen, sich zur Abkehr von ihm gewandt!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 1, 5, 'Auf welche Stelle soll man euch noch schlagen, da ihr ja doch im Abfall verharret? Das ganze Haupt ist krank und das ganze Herz siech;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 1, 6, 'von der Fußsohle bis zum Scheitel ist nichts Unversehrtes mehr an ihm: nur Wunden und Striemen und frische Schläge, die nicht ausgedrückt und nicht verbunden, noch mit Öl erweicht sind.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 1, 7, 'Euer Land ist zu einer Wüste geworden: eure Städte sind mit Feuer verbrannt, euer Ackerland – Fremde verzehren seinen Ertrag vor euren Augen; ja, eine Wüstenei ist (alles), wie einst bei der Zerstörung Sodoms;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 1, 8, 'und übriggeblieben ist die Tochter Zion wie eine Hütte im Weinberg, wie ein Wächterhäuschen im Gurkenfeld, wie ein eingeschlossener Wachtturm.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 1, 9, 'Hätte der HERR der Heerscharen von uns nicht eben noch einen Rest übriggelassen: schier wie Sodom wären wir geworden und hätten gleiches Schicksal mit Gomorrha gehabt!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 1, 10, 'Höret das Wort des HERRN, ihr Sodomsfürsten! Merk auf die Weisung unsres Gottes, du Gomorrhavolk!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 1, 11, '»Wozu soll mir die Menge eurer Schlachtopfer dienen?« fragt der HERR; »überdrüssig bin ich der Brandopfer von Widdern und des Fettes der Mastkälber, und am Blut von Jungstieren, Lämmern und Böcken habe ich kein Wohlgefallen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 1, 12, 'Wenn ihr kommt, um vor meinem Angesicht euch sehen zu lassen – wer hat das von euch verlangt, meine Vorhöfe zu zertreten?');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 1, 13, 'Bringt mir keine heuchlerischen Speisopfer mehr dar: greuelhafter Opferrauch sind sie mir! Neumonde und Sabbate, die Berufung von Festversammlungen: ich kann Gottlosigkeit im Verein mit Festgepränge nicht ertragen!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 1, 14, 'Eure Neumonde und Festzeiten sind meinem Herzen verhaßt, sie sind mir zur Last geworden, und bin’s müde, sie zu ertragen!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 1, 15, 'Und wenn ihr eure Hände ausbreitet (beim Gebet), verhülle ich meine Augen vor euch; auch wenn ihr noch soviel betet, höre ich doch nicht darauf: eure Hände sind ja voll Blutschuld.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 1, 16, 'Wascht euch, reinigt euch, schafft eure bösen Taten mir aus den Augen! Hört auf, Böses zu tun,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 1, 17, 'lernt Gutes tun, kümmert euch um die Rechtspflege, tretet den Gewalttätigen entgegen, schafft den Waisen Recht und führt die Sache der Witwen!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 1, 18, '»So kommt denn her, wir wollen miteinander rechten!« spricht der HERR. »Wenn eure Sünden auch rot wie Scharlach sind, sollen sie doch weiß werden wie Schnee; und sind sie auch rot wie Purpur, sollen sie doch weiß wie Wolle werden.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 1, 19, 'Wenn ihr willig und gehorsam seid, sollt ihr die köstlichen Gaben des Landes genießen;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 1, 20, 'doch wenn ihr euch weigert und widerspenstig seid, sollt ihr vom Schwert gefressen werden; denn der Mund des HERRN hat gesprochen!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 1, 21, 'Ach wie ist doch die (einstmals) treue Stadt zur Ehebrecherin geworden, Zion, das (vordem) voll von Rechtspflege war! Die Gerechtigkeit hatte eine Wohnstätte in ihr, jetzt aber Mörder!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 1, 22, 'Dein Silber ist zu Schlacken geworden, dein edler Wein mit Wasser verschnitten.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 1, 23, 'Deine Oberen sind Aufrührer geworden und Diebsgesellen; sie sind alle in Geschenke verliebt und laufen hinter Bestechung her; den Waisen schaffen sie nicht Recht, und die Sache der Witwen gelangt nicht vor sie.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 1, 24, 'Darum lautet der Ausspruch des Höchsten, der HERRN der Heerscharen, des starken Helden Israels: »Ha! Ich will meinen Zorn an meinen Widersachern kühlen und Rache an meinen Feinden nehmen!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 1, 25, 'Ich will meine Hand gegen dich kehren und deine Schlacken wie mit Laugensalz ausschmelzen und all dein unedles Metall ausscheiden,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 1, 26, 'und will dir wieder Richter schaffen wie in der Vorzeit und Ratgeber wie zu Anfang: danach wird man dich nennen ›die Burg der Gerechtigkeit, die treue Stadt‹.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 1, 27, 'Zion wird durch Gericht erlöst werden, aber die sich in ihm Bekehrenden durch Gerechtigkeit.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 1, 28, 'Und zwar wird Vernichtung die Abtrünnigen und Sünder allesamt treffen, und die vom HERRN Abgefallenen werden umkommen!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 1, 29, 'Ja, ihr sollt zuschanden werden wegen der Terebinthen, die eure Lust sind, und vor Scham erröten wegen der Gärten, die ihr so gern habt!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 1, 30, 'Denn ihr sollt werden wie eine Terebinthe, deren Laub verwelkt, und einem Garten gleichen, der kein Wasser hat!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 1, 31, 'Und sogar der Mächtige soll zu (dürrem) Werg werden und sein Werk zum (zündenden) Funken, und sie sollen beide zusammen verbrennen, ohne daß jemand löschen kann!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 2, 1, '(Dies ist) die Offenbarung, die Jesaja, der Sohn des Amoz, über Juda und (besonders) Jerusalem geschaut hat.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 2, 2, 'In der Endzeit wird es geschehen, daß der Tempelberg des HERRN festgegründet dasteht an der Spitze der Berge und über die (anderen) Höhen erhaben; dann werden alle Heidenvölker zu ihm strömen');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 2, 3, 'und zahlreiche Völkerschaften hinwallen und sagen: »Kommt, laßt uns zum Berge des HERRN hinaufziehen, zum Hause des Gottes Jakobs, damit er uns über seine Wege belehre und wir auf seinen Pfaden wandeln!« Denn von Zion wird Belehrung ausgehen und das Wort des HERRN von Jerusalem.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 2, 4, 'Dann wird er zwischen den Völkern richten und vielen Völkerschaften Recht sprechen; und sie werden ihre Schwerter zu Pflugscharen umschmieden und ihre Lanzenspitzen zu Winzermessern; kein Volk wird noch gegen ein anderes Volk das Schwert erheben, und sie werden sich hinfort nicht mehr auf den Krieg einüben.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 2, 5, 'Haus Jakobs, auf! Laßt uns wandeln im Licht des HERRN!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 2, 6, 'Denn du hast dein Volk, das Haus Jakob, verworfen; denn sie sind voll geworden vom Unwesen des Morgenlandes, sind Zeichendeuter wie die Philister und gehen mit den Kindern des Auslands Hand in Hand.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 2, 7, 'Ihr Land hat sich mit Silber und Gold angefüllt, so daß ihrer Schätze kein Ende ist, und ihr Land ist voll von Rossen geworden, so daß ihrer Kriegswagen kein Ende ist;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 2, 8, 'ihr Land ist aber auch voll von Götzen geworden: vor dem Machwerk ihrer Hände werfen sie sich nieder, vor dem Gebilde ihrer Finger!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 2, 9, 'So hat sich denn der Mensch erniedrigt und auch die Männerwelt sich entehrt: du wirst es ihnen nicht vergeben.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 2, 10, 'Verkrieche dich in die Felsklüfte und verbirg dich in der Erde vor dem Schreckensanblick des HERRN und vor dem Glanz seiner Erhabenheit!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 2, 11, 'Die hoffärtigen Augen der Menschen werden gesenkt werden und der Hochmut der Männer gebeugt; und der HERR allein wird hocherhaben dastehen an jenem Tage.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 2, 12, 'Denn einen Gerichtstag wird der HERR der Heerscharen halten gegen alles Hohe und Stolze und gegen alles Erhabene, damit es erniedrigt werde:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 2, 13, 'sowohl gegen alle Zedern des Libanons, die hohen und ragenden, und gegen alle Eichen der Basanebene');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 2, 14, 'als auch gegen alle hohen Berge und alle ragenden Hügel,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 2, 15, 'sowohl gegen jeden hohen Turm und jede steile Mauer');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 2, 16, 'als auch gegen alle Tharsisschiffe und alle kostbaren Schaustücke.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 2, 17, 'Da wird dann der Stolz der Menschen gebeugt sein und der Hochmut der Männer gedemütigt, und der HERR allein wird hocherhaben dastehen an jenem Tage.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 2, 18, 'Mit den Götzen aber wird es ganz vorbei sein;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 2, 19, 'denn sie werden sich in Felshöhlen und Erdlöcher verkriechen vor dem Schreckensanblick des HERRN und vor dem Glanz seiner Erhabenheit, wenn er sich erhebt, um die Erde zu erschrecken.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 2, 20, 'An jenem Tage werden die Menschen ihre silbernen und goldenen Götzen, die sie sich ein jeder zur Anbetung gemacht haben, den Ratten und Fledermäusen hinwerfen,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 2, 21, 'um selbst sich in die Felsspalten und Steinklüfte zu verkriechen vor dem Schreckensanblick des HERRN und vor dem Glanz seiner Erhabenheit, wenn er sich erhebt, um die Erde zu erschrecken. –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 2, 22, 'Sagt euch doch los vom Menschen, in dessen Nase nur ein Hauch ist! Denn als was ist der zu achten?');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 3, 1, 'Denn wisset wohl: der Höchste, der HERR der Heerscharen, wird aus Jerusalem und (ganz) Juda so Stab wie Stütze hinwegnehmen, jegliche Stütze des Brotes und jegliche Stütze des Wassers:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 3, 2, 'die Helden und Kriegsleute, die Richter und Propheten, die Wahrsager und Ältesten,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 3, 3, 'die Hauptleute und hochangesehenen Männer und Ratsherren, die Meister in Künsten und die Zauberkundigen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 3, 4, 'Und »ich will ihnen Knaben zu Oberen geben, und Buben sollen über sie herrschen«;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 3, 5, 'und die Leute werden sich gegenseitig vergewaltigen, einer den andern, ein jeder seinen Nächsten: der Knabe wird gegen den Alten und der Lump gegen den Ehrenwerten frech auftreten.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 3, 6, 'Wenn dann jemand seinen Bruder in seines Vaters Hause ungestüm nötigt (mit den Worten): »Du hast noch ein Obergewand, du mußt unser Richter sein, und dieser Trümmerhaufe hier soll unter deiner Herrschaft stehen!«,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 3, 7, 'so wird jener an demselben Tage bestimmt erklären: »Nein, ich will nicht Wundarzt sein! Auch ist in meinem Hause weder Brot noch ein Obergewand: ihr könnt mich nicht zum Oberhaupt des Volkes machen!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 3, 8, 'Denn Jerusalem stürzt zu Boden, und Juda kommt zu Fall, weil ihre Zunge und ihr ganzes Tun gegen den HERRN gerichtet sind, um seinen hehren Augen zu trotzen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 3, 9, 'Der freche Ausdruck ihres Angesichts legt Zeugnis gegen sie ab, und von ihren Sünden reden sie ohne Hehl wie einst die Leute in Sodom. Wehe ihnen! Denn sich selbst schaffen sie Unheil.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 3, 10, 'Sagt vom Gerechten, daß er wohl daran sei; denn er wird den Lohn seiner Taten ernten.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 3, 11, 'Wehe dem Gottlosen: er ist übel daran! Denn was seine Hände verübt haben, wird ihm vergolten werden.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 3, 12, 'O über mein Volk! Seine Zwingherren sind Buben, und Weiber haben es beherrscht. O mein Volk! Deine Leiter sind Irreführer und haben den Weg ungangbar gemacht, den du gehen sollst.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 3, 13, 'Der HERR tritt auf, um Anklage zu erheben, und steht da, um Völker zu richten.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 3, 14, 'Der HERR geht ins Gericht mit den Ältesten seines Volkes und dessen Oberen: »Ihr da, ihr habt den Weinberg abgeweidet! Das den Armen geraubte Gut ist in euren Häusern!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 3, 15, 'Wie kommt ihr dazu, mein Volk zu zertreten und das Antlitz der Unterdrückten erbarmungslos zu zermalmen?« – so lautet der Ausspruch Gottes, des HERRN der Heerscharen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 3, 16, 'Weiter hat der HERR gesprochen: »Weil die Töchter Zions hoffärtig geworden sind und mit hochgerecktem Halse einhergehen und freche Blicke um sich werfen, immer tänzelnd einherschreiten und an ihren Füßen die Fußspangen klirren lassen,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 3, 17, 'so wird der Allherr den Scheitel der Töchter Zions kahl machen und der HERR ihre Scham entblößen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 3, 18, 'An jenem Tage wird der Herr ihnen den ganzen Prunk abreißen: die Fußspangen, Stirnreife und Halbmonde,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 3, 19, 'die Ohrgehänge, Armketten und Schleier,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 3, 20, 'die Kopftücher, Schrittkettchen und Prachtgürtel, die Duftfläschchen und Amulette,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 3, 21, 'die Fingerringe und Nasenreife,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 3, 22, 'die Prunkkleider und Mäntel, die Umschlagetücher und Täschchen,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 3, 23, 'die Handspiegel und feinen Hemdchen, die Hüte und Überwürfe.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 3, 24, 'Alsdann wird statt des Balsamdufts Modergeruch eintreten und statt des Gürtels ein Strick, statt des Lockengekräusels eine Glatze und statt des weiten Prachtgewandes ein enger Kittel von Sackleinen, ein Brandmal statt der Schönheit!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 3, 25, 'Deine Mannen werden durchs Schwert fallen und deine Helden im Kriege,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 3, 26, 'und ihre Tore werden ächzen und trauern, und entvölkert wird sie auf dem Erdboden sitzen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 4, 1, 'An jenem Tage werden sieben Frauen sich an einen Mann klammern und ausrufen: »Unser eigenes Brot wollen wir essen und uns in unsere eigenen Gewänder kleiden; nur laß uns deinen Namen führen: mache unserer Schande ein Ende!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 4, 2, 'An jenem Tage wird das Gesproß des HERRN für die, welche in Israel (dem Untergang) entronnen sind, eine Zierde und Ehre und die Frucht der Erde ein Stolz und Ruhm sein.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 4, 3, 'Wer dann in Zion noch übriggeblieben und in Jerusalem mit dem Leben davongekommen ist, wird heilig genannt werden: ein jeder, der in Jerusalem zum Leben eingeschrieben ist.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 4, 4, 'Wenn der Allherr den Schmutz der Töchter Zions abgewaschen und die vielfache Blutschuld Jerusalems aus dessen Mitte hinweggespült hat durch den Geist des Gerichts und durch den Geist der Läuterung,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 4, 5, 'dann wird der HERR über der ganzen Stätte des Berges Zion und über den Festversammlungen dort eine Wolke bei Tage mit Rauch schaffen und lichten Feuerschein bei Nacht; denn über allem wird die Herrlichkeit des HERRN ein Schutz und Schirm sein');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 4, 6, 'und wird zur Beschattung bei Tage vor der Sonnenglut dienen und als Zuflucht und Obdach vor Unwetter und vor Regen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 5, 1, 'Laßt mich doch einmal von meinem Herzensfreunde singen, nämlich das Lied meines Freundes von seinem Weinberg! Einen Weinberg hatte mein Herzensfreund an einer fruchtbaren Anhöhe.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 5, 2, 'Er grub ihn um, säuberte ihn von Steinen und bepflanzte ihn mit Edelreben; er baute einen Turm mitten in ihm, hieb auch gleich eine Kelterkufe in ihm aus und wartete dann darauf, daß er Trauben hervorbringe; doch er brachte nur Herlinge hervor.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 5, 3, 'Und nun, ihr Bewohner Jerusalems und ihr Männer von Juda, gebt doch ein Urteil ab in der Streitsache zwischen mir und meinem Weinberg!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 5, 4, 'Was hätte man noch mehr für meinen Weinberg tun können, das ich nicht an ihm getan hätte? Warum mußte ich erwarten, daß er Trauben bringen würde, während er doch Herlinge gebracht hat?');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 5, 5, 'So will ich euch denn jetzt kundtun, was ich mit meinem Weinberge machen will: die Umzäunung will ich von ihm wegnehmen, damit er abgefressen wird, und seine Mauer niederreißen, damit er zertreten wird.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 5, 6, 'Ich will ihn ganz wüst werden lassen: er soll nicht mehr beschnitten und nicht mehr behackt werden, sondern in Dornen und Disteln soll er aufschießen, und den Wolken will ich gebieten, keinen Regen mehr auf ihn fallen zu lassen. –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 5, 7, 'Denn der Weinberg des HERRN der Heerscharen ist das Haus Israel, und die Männer von Juda sind die Pflanzung, an der sein Herz hängt. Er wartete auf Rechtspflege, und siehe da: Blutvergießen! Auf Gerechtigkeit, und siehe da: Wehgeschrei!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 5, 8, 'Wehe denen, die ein Haus an das andere reihen, Acker an Acker fügen, bis kein Platz mehr übrig ist und ihr die alleinigen Besitzer innerhalb des Landes seid!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 5, 9, 'In meinen Ohren klingt das Wort des HERRN der Heerscharen: »Wahrlich, die vielen Häuser sollen öde werden und, so groß und schön sie sind, unbewohnt stehen!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 5, 10, 'Denn zehn Joch Rebland sollen einen einzigen Eimer geben und ein Malter Aussaat nur einen Scheffel hervorbringen!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 5, 11, 'Wehe denen, die sich schon frühmorgens aufmachen, um berauschenden Getränken nachzulaufen, die bis spät in die Nacht hinein sitzen bleiben und sich vom Wein erhitzen lassen!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 5, 12, 'Da gibt es Zithern und Harfen, Handpauken und Flöten und Wein bei ihren Trinkgelagen; aber auf das Walten des HERRN achten sie nicht, und für das Tun seiner Hände haben sie keine Augen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 5, 13, 'Darum muß mein Volk in die Verbannung wandern ahnungslos, und seine Edlen werden Hunger leiden und seine Volksmenge vor Durst lechzen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 5, 14, 'Darum öffnet das Totenreich seinen Schlund gar weit und sperrt seinen Rachen ins Maßlose auf, damit hinabfahre Jerusalems Herrlichkeit und sein Getümmel, sein Gewühl und wer lustig darin jubelt.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 5, 15, 'Da werden dann die (gewöhnlichen) Menschen gebeugt und die (vornehmen) Männer gedemütigt werden und die Augen der Hoffärtigen sich senken;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 5, 16, 'aber der HERR der Heerscharen wird durch das Gericht erhaben dastehen und Gott, der Heilige, sich durch Gerechtigkeit als heilig erweisen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 5, 17, 'Und Lämmer werden dort weiden, als wäre es ihre Trift, und von den Ödländereien der (ehemals) Reichen werden Ziegen sich nähren.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 5, 18, 'Wehe denen, welche die Sündenschuld an den Stricken des Trugs herbeiziehen und die Sündenstrafe wie an Wagenseilen, –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 5, 19, 'die da sagen: »Er beeile doch, er beschleunige sein Werk, damit wir es noch sehen, und es komme doch und verwirkliche sich der Ratschluß des Heiligen Israels, damit wir ihn kennenlernen!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 5, 20, 'Wehe denen, die das Böse gut und das Gute böse nennen, die Finsternis als Licht hinstellen und das Licht als Finsternis, die Bitteres für süß und Süßes für bitter ausgeben!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 5, 21, 'Wehe denen, die in ihren eigenen Augen weise sind und klug vor sich selbst!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 5, 22, 'Wehe denen, die Helden im Weintrinken sind und tüchtige Männer im Mischen berauschenden Getränks,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 5, 23, 'die um eines Geschenks willen den Schuldigen gerechtsprechen und dem Unschuldigen sein Recht vorenthalten!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 5, 24, 'Darum, wie des Feuers Zunge Stroh verzehrt und wie dürre Halme in der Flamme zusammensinken, so wird ihre Wurzel wie Moder werden und ihre Blüte wie Staub verfliegen; denn sie haben das Gesetz des HERRN der Heerscharen verworfen und das Wort des Heiligen Israels gelästert.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 5, 25, 'Darum ist der Zorn des HERRN gegen sein Volk entbrannt, und er hat seinen Arm gegen sie ausgestreckt und sie geschlagen, daß die Berge erbebten und ihre Leichen wie Kehricht auf den Straßen lagen. Trotz alledem hat sein Zorn noch nicht nachgelassen, und noch immer ist sein Arm hoch erhoben.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 5, 26, 'Und er wird den Völkerschaften in weite Ferne eine Signalstange aufpflanzen, und eine wird er vom Ende der Erde herbeilocken; und siehe, eilends, schnell kommt sie heran.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 5, 27, 'Kein Ermatteter und kein Wankender ist unter ihnen, keiner gönnt sich Schlummer noch Schlaf; keinem geht der Gurt an seinen Hüften auf, und keinem zerreißt der Riemen an seinen Schuhen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 5, 28, 'Ihre Pfeile sind geschärft und ihre Bogen sämtlich gespannt; die Hufe ihrer Rosse sind wie Kiesel zu achten und ihre Wagenräder wie der Wirbelwind.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 5, 29, 'Ihr Gebrüll ist wie das eines Löwen, und ihr Brüllen wie das der jungen Leuen, die da knurren und die Beute packen und in Sicherheit bringen – keiner ist da, der sie ihm entreißt!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 5, 30, 'Und es tost an jenem Tage über ihm wie tosende Meeresbrandung; und blickt man auf das Land hin, siehe, da ist angstvolle Finsternis, und das Licht ist Nacht geworden durch das Nebeldunkel darüber.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 6, 1, 'Im Todesjahre des Königs Ussia sah ich den Allherrn auf einem hohen und ragenden Throne sitzen, während seine Säume das Heiligtum füllten.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 6, 2, 'Seraphe standen über ihm; jeder von ihnen hatte sechs Flügel: mit zweien bedeckte er sein Antlitz, mit zweien bedeckte er seine Beine, und mit zweien flog er;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 6, 3, 'und der eine rief dem andern beständig die Worte zu: »Heilig, heilig, heilig ist der HERR der Heerscharen! Die ganze Erde ist seiner Herrlichkeit voll!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 6, 4, 'Dabei erbebten die Grundlagen der Schwellen von ihrem lauten Rufen, und das Haus füllte sich mit Rauch.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 6, 5, 'Da rief ich aus: »Wehe mir, ich bin verloren! Denn ich bin ein Mann mit unreinen Lippen und wohne inmitten eines Volkes mit unreinen Lippen; und nun habe ich den König, den HERRN der Heerscharen, mit meinen Augen gesehen!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 6, 6, 'Da flog aber einer von den Seraphen auf mich zu und hatte in der Hand eine glühende Kohle, die er mit einer Zange oben vom Altar genommen hatte.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 6, 7, 'Er berührte mit ihr meinen Mund und sagte: »Siehe, nachdem diese (Kohle) deine Lippen berührt hat, ist deine Schuld von dir gewichen und deine Sünde getilgt!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 6, 8, 'Darauf hörte ich die Stimme des Allherrn sagen: »Wen soll ich senden, und wer wird unser Bote sein?« Ich antwortete: »Hier bin ich, sende mich!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 6, 9, 'Da erwiderte er: »Gehe hin und sage zu diesem Volk: ›Ihr sollt immerfort hören und doch kein Verständnis haben, und ihr sollt immerfort sehen und doch nicht erkennen!‹');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 6, 10, 'Mache das Herz dieses Volkes verstockt und seine Ohren schwerhörig und bestreiche ihm die Augen, damit es mit seinen Augen nicht sieht und mit seinen Ohren nicht hört und sein Herz nicht zur Erkenntnis gelangt, und es sich nicht bekehrt und sich nicht Heilung verschafft.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 6, 11, 'Da fragte ich: »Wie lange, Allherr?« Er antwortete: »Bis die Städte verwüstet liegen ohne Bewohner, und die Häuser menschenleer dastehen, und das Land nur noch öde Wüste ist;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 6, 12, 'und bis der HERR die Einwohner weit weggeführt hat und die Verödung inmitten des Landes sich weithin erstreckt.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 6, 13, 'Und wenn dann nur noch ein Zehntel darin übrig ist, so soll dieses noch einmal der Vertilgung anheimfallen wie eine Terebinthe und wie eine Eiche, von denen nach dem Fällen nur noch ein Wurzelstock übrigbleibt: ein heiliger Same ist sein Wurzelstock.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 7, 1, 'Während der Regierung des judäischen Königs Ahas, des Sohnes Jothams, des Sohnes Ussias, begab es sich, daß Rezin, der König von Syrien, mit Pekah, dem Sohne Remaljas, dem König von Israel, zum Angriff gegen Jerusalem heranzog; doch war er nicht imstande, es erfolgreich zu belagern.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 7, 2, 'Als nun dem Hause Davids gemeldet wurde: »Die Syrer sind mit Heeresmacht in Ephraim eingerückt«, da bebte sein Herz und das Herz seines Volkes, wie die Waldbäume von dem Winde beben.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 7, 3, 'Der HERR aber gebot dem Jesaja: »Geh mit deinem Sohn Sear-Jasub hinaus, dem Ahas entgegen, an das Ende des Wasserabflusses des oberen Teiches, auf die Straße nach dem Walkerfeld hin,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 7, 4, 'und sage zu ihm: Sei voller Zuversicht und verhalte dich ruhig! Fürchte dich nicht und laß dein Herz nicht verzagen vor diesen beiden qualmenden Stummeln von Feuerbränden, trotz der Zornesglut Rezins und der Syrer und des Sohnes Remaljas!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 7, 5, 'Zur Strafe dafür, daß Syrien Böses gegen dich geplant hat samt Ephraim und dem Sohne Remaljas und sie gesagt haben:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 7, 6, '›Wir wollen gegen Juda hinaufziehen, wollen ihm ein Grauen einjagen und es für uns erobern und wollen den Sohn Tabeels zum König dort einsetzen!‹ –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 7, 7, 'so hat Gott der HERR gesprochen: ›Das soll nicht gelingen und nicht geschehen!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 7, 8, 'Denn das Haupt von Syrien ist Damaskus, und das Haupt von Damaskus ist Rezin; und in noch fünfundsechzig Jahren soll Ephraim zertrümmert werden, so daß es kein Volk mehr ist.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 7, 9, 'Und das Haupt von Ephraim ist Samaria, und das Haupt von Samaria ist der Sohn Remaljas. Doch habt ihr keinen Glauben, so werdet ihr keinen Bestand haben.‹«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 7, 10, 'Der HERR ließ dann weiter dem Ahas (durch Jesaja) folgendes sagen:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 7, 11, '»Erbitte dir ein Zeichen vom HERRN, deinem Gott: fordere es tief aus der Unterwelt drunten oder oben aus der Höhe!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 7, 12, 'Aber Ahas entgegnete: »Ich mag keines fordern und mag den HERRN nicht versuchen.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 7, 13, 'Da sagte Jesaja: »Hört doch, ihr vom Hause Davids! Genügt es euch nicht, die Geduld der Menschen zu ermüden, daß ihr sogar noch meinen Gott ermüdet?');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 7, 14, 'Darum wird der Allherr selbst euch ein Zeichen geben: Seht, die Jungfrau wird guter Hoffnung werden und einen Sohn gebären, dem sie den Namen Immanuel geben wird.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 7, 15, 'Von Dickmilch und Honig wird er leben zu der Zeit, wo er das Böse zu verwerfen und das Gute zu erwählen versteht;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 7, 16, 'denn ehe noch der Knabe das Böse zu verwerfen und das Gute zu erwählen versteht, wird zwar das Land verlassen sein, vor dessen beiden Königen du Grauen empfindest,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 7, 17, 'aber der HERR wird über dich und dein Volk und über das Haus deines Vaters Tage kommen lassen, wie sie nicht dagewesen sind seit dem Tage, wo Ephraim sich von Juda losgesagt hat: den König von Assyrien!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 7, 18, 'An jenem Tage wird der HERR die Stechfliege, die an der Mündung der Nilarme Ägyptens (zu Hause) ist, und die Biene, die im Lande Assyrien ist, herbeilocken;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 7, 19, 'die werden dann herbeikommen und sich allesamt niederlassen in den Talschluchten und in den Felsklüften, in allen Dornhecken und auf allen Weidetriften.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 7, 20, 'An jenem Tage wird der Allherr (euch) durch das auf der andern Seite des Euphrat gedungene Schermesser, nämlich durch den König von Assyrien, das Haupt und die Haare an den Beinen abscheren, ja sogar den Bart wird es wegraffen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 7, 21, 'In jener Zeit wird sich einer eine junge Kuh oder zwei Stück Kleinvieh halten;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 7, 22, 'und wegen der Menge Milch, die sie geben, wird er Dickmilch essen; denn von Dickmilch und Honig muß ein jeder leben, der innerhalb des Landes übriggeblieben ist.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 7, 23, 'In jener Zeit wird jeder Platz, wo jetzt tausend Weinstöcke im Wert von tausend Silberschekeln stehen, den Dornen und dem Gestrüpp anheimfallen:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 7, 24, 'nur mit Pfeilen und dem Bogen wird man dorthin gehen; denn zu Dornen und Gestrüpp wird das ganze Land geworden sein;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 7, 25, 'und alle Bergäcker, die sonst mit der hacke bearbeitet wurden – dahin wird man nicht mehr gehen aus Furcht vor Dornen und Gestrüpp, sondern dienen werden sie als Weideplatz für Rinder und als ein Ort, der vom Kleinvieh zertreten wird.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 8, 1, 'Weiter gebot der HERR mir folgendes: »Nimm dir eine große Tafel und schreibe auf sie mit Menschengriffel: ›Tafel des Raubebald-Schnellbeute‹;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 8, 2, 'und als vertrauenswürdige Zeugen will ich für mich den Priester Uria und Sacharja, den Sohn Jeberechjas, haben.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 8, 3, 'Danach nahte ich mich der Prophetin, und als sie guter Hoffnung geworden war und einen Sohn geboren hatte, sagte der HERR zu mir: »Gib ihm den Namen ›Raubebald-Schnellbeute‹!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 8, 4, 'Denn ehe noch der Knabe zu rufen vermag ›mein Vater‹ und ›meine Mutter‹, wird man den Reichtum von Damaskus und die Beute Samarias vor dem Könige von Assyrien hinwegtragen.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 8, 5, 'Danach redete der HERR noch weiter zu mir folgendermaßen:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 8, 6, '»Zur Strafe dafür, daß dieses Volk die sanftfließenden Wasser der Siloahleitung verachtet und zu Rezin und dem Sohne Remaljas sich freundschaftlich gestellt hat:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 8, 7, 'darum, siehe, läßt der Allherr die gewaltigen und starken Wasser des Euphratstroms über sie heraufsteigen, nämlich den König von Assyrien und seine ganze Herrlichkeit; der wird über alle seine Flußbetten emporsteigen und über alle seine Ufer daherströmen');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 8, 8, 'und wird in Juda einbrechen, alles überschwemmen und überfluten, so daß er bis an den Hals reicht; und seine ausgespannten Schwingen werden die ganze Breite deines Landes ausfüllen, o Immanuel!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 8, 9, 'Erbost euch immerhin, ihr Völker, und – seid verzagt! Horcht auf, alle ihr fernen Bewohner der Erde! Rüstet euch immerhin und – seid verzagt! Rüstet euch und – seid verzagt!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 8, 10, 'Schmiedet einen Plan: er soll vereitelt werden! Faßt einen Beschluß: er soll nicht zur Ausführung kommen, denn »mit uns ist Gott«!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 8, 11, 'Denn so hat der HERR zu mir gesprochen, indem seine Hand schwer auf mir lag und er mich ermahnte, nicht auf dem Wege dieses Volkes zu wandeln, mit den Worten:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 8, 12, '»Ihr sollt nicht alles das Verschwörung nennen, was dieses Volk da als Verschwörung bezeichnet, und vor dem, was sie fürchten, sollt ihr euch nicht fürchten und es nicht für schrecklich halten.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 8, 13, 'Nein, den HERRN der Heerscharen, den sollt ihr für heilig halten, und er soll eure Furcht sein, er euer Schrecken!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 8, 14, 'Dann wird er zum Anlaß der Heiligung werden und zu einem Stein des Anstoßes und zu einem Felsblock des Strauchelns für beide Häuser Israels, zu einer Schlinge und zum Fallstrick für die Bewohner Jerusalems,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 8, 15, 'so daß viele unter ihnen straucheln und zu Fall kommen und zerschmettert werden, sich darin verstricken und verfangen.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 8, 16, '(Ich will) die Offenbarung unter Verschluß legen, versiegeln die Weisung in meinen Jüngern!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 8, 17, 'Ich will harren auf den HERRN, der sein Angesicht vor dem Hause Jakobs verbirgt, und will auf ihn hoffen!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 8, 18, 'Wisset wohl: ich und die Kinder, die der HERR mir geschenkt hat, wir sind zu Sinnbildern und Vorbedeutungen in Israel vom HERRN der Heerscharen bestimmt, der da wohnt auf dem Berge Zion.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 8, 19, 'Wenn man aber zu euch sagt: »Ihr müßt die Totenbeschwörer und die Geisterkundigen befragen, die da flüstern und murmeln« (so entgegnet): »Soll nicht ein Volk bei seinem Gott anfragen? Soll es etwa betreffs der Lebenden bei den Toten anfragen?');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 8, 20, 'Nein, hin zur Weisung und hin zur Offenbarung! Wahrlich, derartige Reden führen nur die, denen kein Morgenrot mehr scheint.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 8, 21, 'Und es zieht dann, schwer geplagt und hungernd, im Lande umher; und wenn es Hunger leidet, wird es sich wütend gebärden und seinen König und seinen Gott verfluchen;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 8, 22, 'es wird in die Höhe schauen und wird zur Erde niederblicken, aber da ist nur Bedrängnis und Finsternis, angstvolles Dunkel zu sehen, und düstere Nacht ist überallhin zerstreut.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 8, 23, 'Doch das Land, wo jetzt Bedrängnis herrscht, wird nicht umnachtet bleiben. Wie die frühere Zeit Schmach über das Land Sebulon und über das Land Naphthali gebracht hat, so wird die Folgezeit die Straße am See, das Land jenseits des Jordans, den Bezirk der Heiden, zu Ehren bringen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 9, 1, 'Das Volk, das in Finsternis wandelt, wird ein großes Licht erblicken, über denen, die in umnachtetem Lande wohnen, wird Licht aufstrahlen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 9, 2, 'Du wirst des Jubels viel schaffen, wirst die Freude groß werden lassen; sie werden sich vor dir freuen, wie man sich in der Ernte freut, wie man jubelt beim Beuteverteilen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 9, 3, 'Denn das Joch, das schwer auf ihnen lastete, und die Stäbe auf ihrem Nacken, den Stecken ihres Treibers zerbrichst du wie einst am Tage der Midianiterschlacht.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 9, 4, 'Ja, alle Stiefel der dröhnend einherschreitenden Krieger und die blutgetränkten Mäntel werden verbrannt werden, ein Fraß des Feuers.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 9, 5, 'Denn ein Kind wird uns geboren, ein Sohn uns geschenkt werden, auf dessen Schulter die Herrschaft ruhen wird; und sein Name lautet »Wunderrat, Heldengott, Ewigvater, Friedefürst.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 9, 6, 'Seine Herrschaft wird weit reichen, und des Friedens wird kein Ende sein über dem Throne Davids und für seine Königsherrschaft, indem er sie festigt und stützt durch Recht und Gerechtigkeit von nun an bis in Ewigkeit: der Eifer des HERRN der Heerscharen wird dies vollführen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 9, 7, 'Ein Wort hat der Allherr gegen Jakob gesandt, und auf Israel ist es niedergefallen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 9, 8, 'Und das ganze Volk wird es zu fühlen bekommen, Ephraim und die Bewohner Samarias, die da in Hochmut und hoffärtigem Sinn gesagt haben:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 9, 9, '»Ziegelmauern sind eingestürzt, doch mit Quadersteinen führen wir den Bau wieder auf; Maulbeerbäume sind abgehauen worden, doch Zedern setzen wir an ihre Stelle!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 9, 10, 'So verlieh denn der HERR den Gegnern Rezins die Übermacht über sie und stachelte seine Feinde an,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 9, 11, 'nämlich die Syrer im Osten und die Philister im Westen, daß sie Israel mit vollem Munde fraßen. Trotz alledem ließ sein Zorn nicht nach, und sein Arm blieb noch immer hoch erhoben.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 9, 12, 'Aber das Volk kehrte nicht zu dem zurück, der es geschlagen hatte, und nach dem HERRN der Heerscharen fragten sie nicht.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 9, 13, 'Da hieb der HERR beides von Israel ab, Kopf und Schwanz, Palmzweig und Binse an einem Tage –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 9, 14, 'die Vornehmen und Hochangesehenen, die sind der Kopf, und die Propheten, welche Lügen lehren, die sind der Schwanz –;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 9, 15, 'und die Führer dieses Volkes waren Irreleiter, und die sich von ihnen führen ließen, wurden ins Verderben gestürzt.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 9, 16, 'Darum freute der Allherr sich nicht ihrer jungen Mannschaft und erbarmte sich nicht ihrer Waisen und Witwen; denn sie sind allesamt ruchlose Frevler, und jeder Mund redet Gottlosigkeit. Trotz alledem ließ sein Zorn nicht nach, und sein Arm blieb noch immer hoch erhoben.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 9, 17, 'Denn der Frevel brannte wie Feuer, das Dornen und Gestrüpp verzehrt und in den Dickichten des Waldes lodert, so daß sie als hohe Rauchsäulen aufwirbeln.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 9, 18, 'Durch den Grimm des HERRN der Heerscharen wurde das Land in Brand gesetzt, so daß das Volk wie zu einem Fraß der Flammen wurde: keiner übte Schonung gegen den andern.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 9, 19, 'Man verschlang zur Rechten und blieb doch hungrig; man fraß zur Linken und wurde doch nicht satt: jeder verzehrte das Fleisch seines eigenen Armes,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 9, 20, 'nämlich Manasse den Ephraim und Ephraim den Manasse; vereint fielen sie beide über Juda her. Trotz alledem ließ sein Zorn nicht nach, und sein Arm blieb noch immer hoch erhoben.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 10, 1, 'Wehe denen, die heillose Verordnungen aufsetzen, und den Schreibern, die nichts als unheilvolle Rechtssatzungen ausfertigen,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 10, 2, 'um die Niedrigen vom Rechtsweg abzudrängen und den Geringen meines Volkes ihr Recht vorzuenthalten, damit die Witwen ihre Beute werden und sie die Waisen ausplündern können!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 10, 3, 'Was wollt ihr nur tun am Tage der Heimsuchung und bei dem Sturm, der von fern heranzieht? Zu wem wollt ihr um Hilfe fliehen und wo euren Reichtum in Sicherheit bringen?');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 10, 4, 'Nichts anderes wird euch übrig bleiben, als unter den Gefangenen zusammenzusinken und unter die Erschlagenen niederzufallen. Trotz alledem hat sein Zorn nicht nachgelassen, und sein Arm ist noch immer hoch erhoben.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 10, 5, 'Wehe dem Assyrer, dem Stecken meines Zorns, (und) dem, in dessen Hand mein Grimm als Stecken war!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 10, 6, 'Gegen eine gottlose Völkerschaft sandte ich ihn, und gegen das Volk, dem ich zürnte, entbot ich ihn, damit er Raub gewinne und sich Beute hole und es zertrete wie Kot auf der Straße.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 10, 7, 'Er aber denkt es sich nicht so, und sein Herz ist nicht so gesonnen; nein, zu vertilgen hat er im Sinn und Völker auszurotten in nicht kleiner Zahl.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 10, 8, 'Denn er sagt: »Sind nicht meine Statthalter allesamt Könige?');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 10, 9, 'Ist es nicht Kalno ebenso ergangen wie Karchemis, nicht Hamath wie Arpad, nicht Samaria wie Damaskus?');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 10, 10, 'Wie meine Hand die Königreiche der Götzen erreicht hat, deren Götterbilder doch denen von Jerusalem und Samaria überlegen waren –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 10, 11, 'sollte ich da nicht, wie ich mit Samaria und seinen Göttern verfahren bin, ebenso auch mit Jerusalem und seinen Götterbildern verfahren?«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 10, 12, 'Doch wenn einst der Allherr sein ganzes Werk am Berge Zion und an Jerusalem zum Abschluß gebracht hat, wird er auch mit der Frucht des hochmütigen Sinnes des Königs von Assyrien und mit dem hochfahrenden Prahlen seiner Augen Abrechnung halten;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 10, 13, 'denn er hat gesagt: »Durch meines Armes Kraft habe ich es vollführt und durch meine Weisheit, weil ich klug bin; ich habe die Grenzen der Völker verschwinden lassen, habe ihre Schätze geplündert und wie ein Starker die Fürsten vom Thron gestürzt.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 10, 14, 'Meine Hand hat nach dem Reichtum der Völker gegriffen wie nach einem Vogelnest, und wie man verlassene Eier zusammenrafft, so habe ich die ganze Erde eingesackt, ohne daß einer die Flügel regte oder den Schnabel aufsperrte und auch nur zu piepen wagte.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 10, 15, 'Darf denn die Axt gegen den großtun, der mit ihr haut, oder darf die Säge sich brüsten gegen den, der sie zieht? Als ob der Stab den schwänge, welcher ihn erhebt, als ob der Stecken den aufhöbe, der nicht auch Holz ist!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 10, 16, 'Darum wird Gott, der HERR der Heerscharen, die Schwindsucht in Assyriens Wohlbeleibtheit senden, und unter seiner Herrlichkeit wird ein Brand auflodern wie eine Feuersbrunst;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 10, 17, 'und zwar wird das Licht Israels zur Lohe werden und sein Heiliger zu einer Flamme, die seine Dornen und sein Gestrüpp in Brand setzt und verzehrt an einem Tage;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 10, 18, 'und die Pracht seines Waldes und seines Baumgartens wird er vernichten mit Stumpf und Stiel, so daß es sein wird, wie wenn ein Schwerkranker dahinsiecht.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 10, 19, 'Dann wird der Rest seiner Waldbäume leicht zu zählen sein, so daß sogar ein Knabe sie aufschreiben kann.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 10, 20, 'An jenem Tage aber wird es geschehen: da wird der Rest Israels und was vom Hause Jakobs entronnen ist, sich nicht länger auf den stützen, der sie jetzt schlägt, sondern sie werden sich auf den HERRN, den Heiligen Israels, in Wahrheit stützen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 10, 21, 'Ein Rest wird sich bekehren, ein bloßer Rest von Jakob, zum Heldengott.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 10, 22, 'Denn wenn auch dein Volk, Israel, so zahlreich würde wie der Sand am Meer, so wird sich doch nur ein Rest in ihm bekehren: Vernichtung ist fest beschlossen, sie flutet wie ein Strom mit Gerechtigkeit daher;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 10, 23, 'denn Vernichtung, und zwar ein fest beschlossenes Strafgericht, wird Gott, der HERR der Heerscharen, inmitten der ganzen Erde vollziehen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 10, 24, 'Darum hat Gott, der HERR der Heerscharen, so gesprochen: »Fürchte dich nicht, mein Volk, das in Zion wohnt, vor dem Assyrer, wenn er dich mit dem Stock schlagen wird und seinen Stecken gegen dich erhebt wie einst die Ägypter!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 10, 25, 'Denn nur noch eine ganz kleine Weile, dann ist mein Grimm zu Ende, und mein Zorn wendet sich zu ihrer Vernichtung.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 10, 26, 'Dann wird der HERR der Heerscharen die Geißel gegen ihn schwingen, wie er einst die Midianiter am Rabenfelsen geschlagen hat, und wird seinen Stab über das Meer ausstrecken und ihn erheben wie einst gegen die Ägypter.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 10, 27, 'An jenem Tage wird dann die Last des Assyrers von deinem Rücken weichen und sein Joch von deinem Nacken verschwinden.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 10, 28, 'Er rückt heran von Rimmon her, zieht schon auf Ajjath los, kommt bei Migron vorüber, läßt sein Gepäck in Michmas.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 10, 29, 'Sie ziehen durch den Engpaß, in Geba nehmen sie Nachtherberge; Rama zittert, Sauls Gibea flieht.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 10, 30, 'Schreie laut auf, Bewohnerschaft von Gallim! Horche auf, Laisa! Armes Anathoth!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 10, 31, 'Madmena ist zerstoben, die Bewohner von Gebim sind geflüchtet.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 10, 32, 'Noch heute wird er Nob besetzen; er streckt schon seine Hand drohend aus gegen den Berg der Bewohnerschaft Zions, gegen den Hügel Jerusalems.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 10, 33, 'Siehe, da haut der Allherr, der HERR der Heerscharen, die Laubkronen mit Schreckensgewalt herunter: die hochgewachsenen werden abgeschlagen, und die hochragenden sinken zu Boden.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 10, 34, 'Dann wird das Dickicht des Waldes mit dem Eisen niedergehauen, und der Libanon (-wald) stürzt durch einen Gewaltigen zusammen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 11, 1, 'Sodann wird ein Reis aus dem Stumpfe Isais hervorgehen und ein Schößling aus seinen Wurzeln Frucht tragen;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 11, 2, 'und der Geist des HERRN wird auf ihm ruhen: der Geist der Weisheit und der Einsicht, der Geist des Rates und der Heldenkraft, der Geist der Erkenntnis und der Furcht des HERRN.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 11, 3, 'An der Furcht des HERRN wird er sein Wohlgefallen haben; und er wird nicht nach dem richten, was seine Augen sehen, und nicht Recht sprechen nach dem, was seine Ohren hören;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 11, 4, 'nein, er wird (auch) die Niedrigen richten mit Gerechtigkeit und den Gebeugten im Lande Recht sprechen mit Redlichkeit. Die Erde wird er mit dem Stabe seines Mundes schlagen und mit dem Hauch seiner Lippen den Gottlosen töten;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 11, 5, 'die Gerechtigkeit wird der Gurt seiner Hüften sein und die Treue der Gürtel seiner Lenden.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 11, 6, 'Dann wird der Wolf als Gast bei dem Lamm weilen und der Panther sich neben dem Böcklein lagern; das Kalb, der junge Löwe und der Mastochs werden vereint weiden, und ein kleiner Knabe wird Treiber bei ihnen sein;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 11, 7, 'Kuh und Bärin werden miteinander weiden, ihre Jungen sich zusammen lagern, und der Löwe wird Stroh fressen wie das Rind.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 11, 8, 'Der Säugling wird am Schlupfloch der Otter spielen und das eben entwöhnte Kind seine Hand nach dem Feuerauge des Basilisken ausstrecken.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 11, 9, 'Man wird nichts Böses mehr tun und nicht unrecht handeln auf meinem ganzen heiligen Berge; denn das Land wird voll von der Erkenntnis des HERRN sein gleich den Wassern, die den Meeresgrund bedecken.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 11, 10, 'Und an jenem Tage wird es geschehen: da werden die Heidenvölker den Wurzelsproß Isais aufsuchen, der als Banner für die Völker dasteht, und seine Ruhestätte wird voller Herrlichkeit sein.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 11, 11, 'Und an jenem Tage wird es geschehen: da wird der Allherr seine Hand zum zweitenmal ausstrecken, um den Rest seines Volkes, der noch übriggeblieben ist, loszukaufen aus Assyrien und Unterägypten, aus Oberägypten und Äthiopien, aus Persien und Babylonien, aus Hamath und den Küstenländern des Meeres.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 11, 12, 'Da wird er den Heidenvölkern ein Banner aufpflanzen und die verstoßenen Israeliten sammeln und das, was von Juda zerstreut ist, zusammenbringen von den vier Säumen der Erde.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 11, 13, 'Dann wird die Eifersucht Ephraims schwinden, und die, welche in Juda neidisch (auf Ephraim) sind, werden ausgerottet werden; Ephraim wird nicht mehr neidisch auf Juda sein, und Juda wird Ephraim nicht mehr eifersüchtig behandeln;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 11, 14, 'sondern sie werden den Philistern meerwärts auf die Schulter fliegen, werden vereint die Bewohner des Ostens plündern; von Edom und Moab werden sie Besitz ergreifen, und die Ammoniter werden ihnen untertan sein.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 11, 15, 'Auch wird der HERR die Meereszunge Ägyptens der Vernichtung weihen und seine Hand gegen (oder über) den Euphrat schwingen mit der Glut seines Hauches und ihn zu sieben Bächen zerschlagen, so daß man mit Sandalen hindurchgehen kann.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 11, 16, 'Und es wird dann eine Straße für den Rest seines Volkes, der übriggeblieben ist, von Assyrien her da sein, wie eine solche einst für Israel da war zur Zeit seines Auszugs aus Ägypten.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 12, 1, 'An jenem Tage aber wirst du beten: »Ich danke dir, HERR! Denn bist du auch erzürnt gegen mich gewesen, so hat dein Zorn sich doch wieder gelegt, und du hast mich wieder getröstet.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 12, 2, 'Fürwahr, Gott ist mein Heil: ich bin voller Zuversicht und fürchte mich nicht! Denn Gott, der HERR, ist meine Stärke und mein Lobgesang, und er ist mir ein Retter geworden!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 12, 3, 'Und ihr werdet mit Jubel Wasser aus den Quellen des Heils schöpfen');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 12, 4, 'und an jenem Tage sprechen: »Danket dem HERRN, ruft seinen Namen aus, macht unter den Völkern seine Großtaten bekannt, rühmet, daß sein Name erhaben ist!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 12, 5, 'Lobsinget dem HERRN, denn Herrliches hat er vollbracht: das muß auf der ganzen Erde kund werden!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 12, 6, 'Jauchzet und jubelt, ihr Bewohner Zions, denn groß ist in eurer Mitte der Heilige Israels!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 13, 1, 'Ausspruch über Babylon, den Jesaja, der Sohn des Amoz, geschaut hat:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 13, 2, 'Auf einem kahlen Berge pflanzt eine Signalstange auf, ruft ihnen mit lauter Stimme zu! Winkt mit der Hand, daß sie einziehen in die Tore der hohen Herren!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 13, 3, '»Ich selbst habe herbeschieden zu meinem Zorngericht meine geweihten Krieger, habe auch meine Helden dazu entboten, meine stolz Frohlockenden.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 13, 4, 'Horch, ein Getümmel schallt auf den Bergen wie von zahlreichem Kriegsvolk! Horch, ein Getöse von Königreichen sich versammelnder Völkerschaften: Gott, der HERR der Heerscharen, mustert das Kriegsheer!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 13, 5, 'Sie kommen aus fernem Lande, vom Ende des Himmels: der HERR und die Werkzeuge seines Zorns, um die ganze Erde zu verheeren!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 13, 6, 'Heulet! Denn nahe ist der Tag des HERRN! Wie ein Wetterschlag kommt er vom Allmächtigen!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 13, 7, 'Darum hängen alle Arme schlaff herab, und jedes Menschenherz verzagt;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 13, 8, 'sie geraten in Bestürzung; Krämpfe und Wehen befallen sie; wie ein Weib in Geburtsnöten winden sie sich! Einer starrt den andern an, ihre Gesichter glühen wie von Flammenröte übergossen!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 13, 9, 'Wisset wohl: der Tag des HERRN kommt, ein erbarmungsloser, voll von Grimm und Zornesglut, um die Erde zur Öde zu machen und die auf ihr lebenden Sünder von ihr zu vertilgen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 13, 10, 'Denn die Sterne des Himmels und die großen Sternbilder unter ihnen lassen ihr Licht nicht mehr leuchten; die Sonne verfinstert sich schon bei ihrem Aufgang, und der Mond läßt sein Licht nicht scheinen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 13, 11, '»Ja, heimsuchen will ich am Erdkreis jegliche Bosheit und an den Gottlosen ihre Verschuldung; dem Hochmut der Stolzen will ich ein Ende machen und den Hochmut der Gewalttätigen erniedrigen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 13, 12, 'Ich will die Männer seltener werden lassen als Feingold und die Sterblichen seltener als Golderz von Ophir.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 13, 13, 'Darum will ich den Himmel erzittern lassen, und die Erde soll von ihrer Stätte wegrücken beim Grimm des HERRN der Heerscharen, und zwar am Tage seines lodernden Zorns.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 13, 14, 'Da wird es ihnen dann ergehen wie aufgescheuchten Gazellen und wie einer Schafherde, die niemand zusammenhält: ein jeder wird sich zu seinem Volk wenden und jeder in sein Heimatland fliehen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 13, 15, 'Alle aber, die man (in Babylon) noch antrifft, werden durchbohrt werden, und wen man aufgreift, der fällt durchs Schwert;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 13, 16, 'ihre kleinen Kinder zerschmettert man vor ihren Augen, ihre Häuser werden geplündert und ihre Weiber geschändet.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 13, 17, 'Wisset wohl: ich rege gegen sie die Meder auf, die das Silber nicht achten und am Gold kein Gefallen haben;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 13, 18, 'aber ihre Bogen strecken Jünglinge nieder, und mit der Frucht im Mutterleibe haben sie kein Erbarmen; ihr Auge blickt nicht mitleidsvoll auf Kinder.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 13, 19, 'So wird denn Babylon, das Schmuckstück unter den Königreichen, die stolze Pracht der Chaldäer, das gleiche Schicksal haben wie Sodom und Gomorrha, die Gott von Grund auf zerstört hat.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 13, 20, 'Es wird in Ewigkeit nicht mehr bewohnt werden und menschenleer bleiben von Geschlecht zu Geschlecht; kein Steppenaraber wird dort sein Zelt aufschlagen und kein Hirt dort seine Herde lagern lassen;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 13, 21, 'nein, Wüstentiere werden dort lagern und die Häuser dort voll von Eulen sein; Strauße sollen dort hausen und Bocksgeister daselbst tanzen;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 13, 22, 'Wüstenwölfe sollen in den Palästen dort heulen und Schakale in den Lustschlössern; und zwar steht ihre Zeit nahe bevor, und ihre Tage werden sich nicht hinausziehen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 14, 1, 'Denn der HERR wird sich Jakobs erbarmen und Israel noch einmal erwählen und sie auf ihrem Heimatboden zur Ruhe bringen. Die Fremdlinge werden sich ihnen dabei anschließen und sich dem Hause Jakobs zugesellen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 14, 2, 'Und die Völker werden sie nehmen und sie an ihren Ort hinbringen, und das Haus Israel wird im Lande des HERRN Knechte und Mägde an ihnen besitzen, so daß sie die, von denen sie vordem in Gefangenschaft gehalten worden waren, selbst in Gefangenschaft halten und die Herrschaft über ihre früheren Zwingherren ausüben.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 14, 3, 'Sobald aber der HERR dir Ruhe verschafft hat von deiner Mühsal und deiner Unruhe und von dem harten Frondienst, mit dem du geknechtet wurdest,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 14, 4, 'sollst du dieses Spottlied auf den König von Babylon anstimmen und es so vortragen: O wie ist zur Ruhe gekommen der Zwingherr, zur Ruhe gekommen die Mißhandlung!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 14, 5, 'Zerbrochen hat der HERR den Stecken der Frevler, den Herrscherstab der Gewaltherren,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 14, 6, 'der da Völker im Grimm schlug mit Schlägen ohne Unterlaß, der im Zorn Völkerschaften niedertrat mit erbarmungsloser Knechtschaft.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 14, 7, 'Nun hat Ruhe, hat Rast die ganze Erdbevölkerung: alles bricht in Jubel aus!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 14, 8, 'Sogar die Zypressen freuen sich über dich, die Zedern des Libanons: »Seitdem du dich schlafen gelegt hast, steigt niemand mehr herauf zu uns, um uns abzuhauen!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 14, 9, 'Das Totenreich drunten gerät in Aufregung um deinetwillen, in Erwartung deiner Ankunft: es stört die Schatten deinetwegen auf, alle, die vordem die Häupter der Erde waren, und macht von ihren Thronsesseln aufstehen alle Könige der Völkerschaften.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 14, 10, 'Sie alle heben an und rufen dir zu: »Auch du bist todkrank geworden wie wir, bist uns gleichgemacht worden!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 14, 11, 'Hinabgestürzt ins Totenreich ist dein Prunk, das Getön deiner Harfen! Maden bilden das Lager unter dir, und Würmer sind deine Decke!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 14, 12, '»O wie bist du vom Himmel gefallen, du Glanzgestirn, Sohn der Morgenröte! Wie bist du zu Boden geschmettert, du Besieger der Völker,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 14, 13, 'der du dachtest in deinem Sinn: ›In den Himmel will ich hinaufsteigen, hoch über den Sternen Gottes meinen Thron aufrichten, will auf dem Berge der Zusammenkunft mich niederlassen im äußersten Norden!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 14, 14, 'Ich will über die Wolkenhöhen hinauffahren, will mich dem Höchsten gleich machen!‹');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 14, 15, 'Nun aber bist du ins Totenreich hinabgestürzt, in den hintersten Winkel der Grube!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 14, 16, 'Wer dich einst gesehen hat, betrachtet dich nun, schaut dich nachdenklich an: ›Ist dies der Mann, der die Erde in Beben versetzte und Königreiche zittern machte?');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 14, 17, 'Der den Erdkreis in eine Wüste verwandelte und die Städte darauf zerstörte? Der seine Gefangenen nie in die Heimat entließ?‹');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 14, 18, 'Alle Könige der Völkerschaften insgesamt ruhen in Ehren, ein jeder in seinem Hause;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 14, 19, 'du aber bist, fern von deiner Grabstätte, hingeworfen wie ein verabscheuter Sprößling, überdeckt mit Erschlagenen, vom Schwert Durchbohrten, die zu den Steinen der Grube hinabsteigen mußten, wie ein zertretenes Aas.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 14, 20, 'Nicht wirst du mit ihnen vereint sein im Grabe; denn du hast dein Land zugrunde gerichtet, dein Volk hingemordet. In Ewigkeit soll das Geschlecht des Übeltäters nicht mehr genannt werden:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 14, 21, 'stellt für seine Söhne die Schlachtbank bereit wegen der Schuld ihrer Väter, damit sie nie wieder auftreten und sich der Erde bemächtigen und den weiten Erdkreis mit Trümmern füllen!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 14, 22, '»Ja, ich will mich gegen sie erheben« – so lautet der Ausspruch des HERRN der Heerscharen – »und will Babylon ausrotten mit Stumpf und Stiel, mit Sproß und Schoß« – so lautet der Ausspruch des HERRN –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 14, 23, '»und will es zum Besitztum der Igel machen und zu Wassersümpfen und will es hinwegfegen mit dem Kehrbesen der Vernichtung!« – so lautet der Ausspruch des HERRN der Heerscharen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 14, 24, 'Geschworen hat der HERR der Heerscharen also: »Fürwahr, wie ich es vorbedacht habe, so soll es geschehen, und wie ich es beschlossen habe, so soll es zustande kommen:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 14, 25, 'zerschmettern will ich den Assyrer in meinem Lande und ihn auf meinen Bergen zertreten, damit sein Joch von ihnen genommen wird und seine Last von ihrem Rücken verschwindet.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 14, 26, 'Dies ist der Ratschluß, der über die ganze Erde beschlossen ist, und das bedeutet die Hand, die über alle Völkerschaften ausgestreckt ist.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 14, 27, 'Denn wenn der HERR der Heerscharen einen Plan gefaßt hat: wer will ihn vereiteln? Und seine ausgestreckte Hand: wer kann sie zurückbiegen?');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 14, 28, 'Im Todesjahre des Königs Ahas erging folgender Gottesspruch:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 14, 29, '»Freue dich nicht, gesamtes Philisterland, darüber, daß der Stecken (dessen), der dich schlug, zerbrochen ist! Denn aus der Wurzel der Schlange fährt eine Giftotter hervor, und deren Frucht ist ein geflügelter Drache.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 14, 30, 'Da werden dann die Ärmsten der Armen in Ruhe weiden und Dürftige in Sicherheit lagern, aber deinen Wurzelsprößling werde ich durch Hunger sterben lassen, und was von dir noch übrig ist, wird er umbringen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 14, 31, 'Heulet, ihr Tore, schreiet, ihr Städte! Verzage, gesamtes Philisterland! Denn von Norden her kommt Rauch, und keiner tritt aus Reih und Glied heraus in seinen Scharen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 14, 32, 'Und welche Antwort wird man den Gesandten der Heidenvölker geben? ›Daß der HERR Zion fest gegründet hat und daß die Elenden seines Volkes dort wohlgeborgen sein werden.‹«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 15, 1, 'Gottesspruch über die Moabiter: Ach! Über Nacht ist Ar zerstört, Moab vernichtet! Ach! Über Nacht ist Kir zerstört, Moab vernichtet!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 15, 2, 'Bajith und Dibon steigen zu den Opferhöhen hinauf, um zu weinen; auf dem Nebo und in Medeba wehklagt Moab; auf all ihren Häuptern ist eine Glatze, alle Bärte sind abgeschoren.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 15, 3, 'Auf ihren Gassen gürtet man sich Sackleinen um, auf ihren Dächern und ihren Marktplätzen jammert alles und zerfließt in Tränen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 15, 4, 'Hesbon und Eleale schreien: bis Jahaz hört man ihren Weheruf; darob erheben die gerüsteten Krieger Moabs Geschrei, ihr Mut verzagt in ihnen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 15, 5, 'Mein Herz jammert um Moab: seine Flüchtlinge erreichen schon Zoar, schon Eglath-Schelischija. Ach, die Steige nach Luhith steigt man unter Weinen hinan! Ach, auf dem Wege nach Horonaim erhebt man Geschrei über den Zusammenbruch!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 15, 6, 'Ach, die Wasser von Nimrim werden zu Wüsteneien! Denn verdorrt ist das Gras, der Rasen verwelkt, das Grün verschwunden.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 15, 7, 'Darum tragen sie den Besitz, der ihnen übriggeblieben ist, und ihre ersparte Habe über den Weidenbach hinüber.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 15, 8, 'Ach, das Wehgeschrei macht die Runde im ganzen Gebiet der Moabiter! Bis Eglaim dringt ihr Jammern und bis Beer-Elim ihre Wehklage!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 15, 9, 'Ach, die Wasser von Dimon sind voll Blut! Denn ich verhänge über Dimon noch weiteres Unheil: einen Löwen für die Flüchtlinge der Moabiter und für den im Lande gebliebenen Überrest!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 16, 1, '»Sendet den dem Landesherrn zukommenden Lämmerzins von Sela aus durch die Wüste zum Berge der Tochter Zion!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 16, 2, 'Da werden dann wie wegflatternde Vögel, wie eine aufgescheuchte Nestbrut sein die Töchter Moabs, an den Furten des Arnon:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 16, 3, '»Erteile uns Rat, schaffe Vermittlung! Mache der Nacht gleich deinen Schatten am hellen Mittag, verbirg die Vertriebenen, verrate die Flüchtlinge nicht!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 16, 4, 'Laß meine aus Moab Vertriebenen als Gäste bei dir weilen, sei ihnen eine Schutzwehr vor dem Verwüster! Denn wenn der Bedrücker ein Ende genommen hat, die Verwüstung vorüber ist und die Zertreter aus dem Lande verschwunden sind,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 16, 5, 'so wird der Thron durch die (geübte) Liebe befestigt sein, und auf ihm wird sitzen in Zuverlässigkeit im Zelte Davids ein Richter, der sich der Rechtspflege annimmt und auf Gerechtigkeit bedacht ist.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 16, 6, '»Wir haben gehört von Moabs Stolz, dem überaus hochfahrenden, von seinem Hochmut und seinem Stolz, von seinem Übermut und seinen eitlen Prahlereien.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 16, 7, 'So mögen denn die Moabiter um Moab jammern, mögen allesamt jammern, um die Traubenkuchen von Kir-Hareseth mögt ihr seufzen, tiefbetrübt!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 16, 8, 'Denn Hesbons Pflanzungen sind verwelkt, die Weinstöcke von Sibma, deren Edeltrauben die Herren der Völker bezwangen, die bis Jaeser reichten, bis in die Wüste schweiften; deren Schößlinge sich weit ausbreiteten, ja bis zum (Toten) Meere hinüberwanderten.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 16, 9, 'Darum weine ich im Verein mit Jaeser schmerzlich um Sibmas Weinstöcke, benetze dich, Hesbon und Eleale, mit meinen Tränen; denn in deine Obsternte und deine Weinlese ist ein Jauchzen hereingebrochen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 16, 10, 'So sind denn Freude und Frohlocken aus dem Fruchtgefilde verschwunden, und in den Weingärten wird nicht mehr gejubelt und gejauchzt; kein Kelterer tritt noch Wein in den Kufen: das Jauchzen (der Winzer) ist zum Verstummen gebracht.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 16, 11, 'Darum klagt’s in meinem Herzen um Moab wie Harfenton und in meiner Brust um Kir-Heres.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 16, 12, 'Und geschehen wird es: wenn Moab auf der Opferhöhe erscheint und sich (mit Opfern) abmüht und in sein Heiligtum eintritt, um zu beten, so wird es nichts ausrichten.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 16, 13, 'Dies ist das Wort, das der HERR einstmals über Moab ausgesprochen hat.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 16, 14, 'Jetzt aber lautet der Ausspruch des HERRN so: »In drei Jahren, gleich den Jahren eines Söldners, da wird die Herrlichkeit Moabs samt all der großen Volksmenge in Verachtung geraten sein, und nur ein ganz geringer, winziger Überrest wird bleiben.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 17, 1, 'Ausspruch über Damaskus: »Wisset wohl: Damaskus scheidet aus der Zahl der Städte aus und wird zu einem wüsten Trümmerhaufen werden,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 17, 2, 'verlassen für immer; seine Städte werden den Herden preisgegeben: die werden dort lagern, ohne daß jemand sie aufscheucht.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 17, 3, 'Zu Ende ist es mit dem Bollwerk für Ephraim und mit dem Königtum für Damaskus; und der Überrest von Syrien wird der Herrlichkeit der Söhne Israels gleichen« – so lautet der Ausspruch des HERRN der Heerscharen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 17, 4, 'An jenem Tage wird ja die Herrlichkeit Jakobs geringfügig sein und sein Fettleib abmagern;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 17, 5, 'und es wird zugehen, wie wenn ein Schnitter Getreidehalme zusammenrafft und sein Arm Ähren absichelt; und es wird zugehen, wie wenn man Ähren bei der Nachlese sammelt im Tale Rephaim (südlich von Jerusalem).');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 17, 6, '»Es wird ja nur eine Nachlese von ihm übrigbleiben wie beim Abklopfen der Oliven: zwei, drei Beeren ganz oben im Wipfel, vier oder fünf an seinen, des Fruchtbaums Zweigen« – so lautet der Ausspruch des HERRN, des Gottes Israels. –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 17, 7, 'An jenem Tage werden die Menschen zu ihrem Schöpfer hinschauen und ihre Blicke sich auf den Heiligen Israels richten;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 17, 8, 'sie werden dann nicht mehr hinschauen nach den Altären, dem Machwerk ihrer Hände, und nicht mehr hinblicken nach dem Gebilde ihrer Finger, nach den Götzenbildern und den Sonnensäulen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 17, 9, 'An jenem Tage werden ihre festen Städte sein wie die verlassenen Ortschaften in den Wäldern und auf den Berggipfeln, welche (die Hewiter und Amoriter) einstmals aus Furcht vor den Israeliten verlassen haben: es wird eine Wüstenei sein,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 17, 10, 'weil du den Gott deines Heils vergessen und an den Felsen deiner Zuflucht nicht gedacht hast. Darum lege immerhin liebliche Pflanzungen an und besetze sie mit ausländischen Absenkern;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 17, 11, 'laß sie sprossen sogleich an dem Tage, an welchem du sie gepflanzt hast, und bringe deine Pflänzlinge schon am folgenden Morgen zur Blüte: es fällt doch jegliche Ernte aus am Tage des Wehs und des unheilbaren Schmerzes.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 17, 12, 'Wehe, ein Getümmel vieler Völker, die wie das Brausen des Meeres brausen! Und ein Getöse von Völkerschaften, die wie mächtige Wasser im Aufruhr tosen!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 17, 13, 'Ja, die Völkerschaften tosen, wie gewaltige Wasser tosen; doch er bedroht sie scheltend: da fliehen sie weit weg und werden dahingejagt wie Spreu auf den Bergen vor dem Winde und wie wirbelnder Staub vor dem Sturm.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 17, 14, 'Zur Abendzeit, da bricht Schrecken herein, doch ehe der Morgen kommt, sind sie dahin. Das ist das Schicksal derer, die uns berauben, und das Los derer, die uns plündern!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 18, 1, 'Ha du Land des Flügelgeschwirrs jenseits der Ströme von Äthiopien,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 18, 2, 'das da Boten entsandt hat auf dem Strome und in Rohrkähnen über den Wasserspiegel: geht heim, ihr flinken Boten, zu eurem hochgewachsenen und blanken Volke, zu der Völkerschaft, die, seit sie besteht, gefürchtet ist, zu der Völkerschaft, die gewaltige Kraft besitzt und alles niedertritt, deren Land Ströme durchschneiden.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 18, 3, 'Ihr Bewohner des Erdkreises allesamt und ihr Insassen der Erde: Sobald man ein Panier auf den Bergen aufpflanzt, so sehet hin! Und sobald man in die Trompete stößt, so horchet auf!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 18, 4, 'Denn so hat der HERR zu mir gesprochen: »Ruhig will ich warten und zuschauen an meiner Stätte, wie wolkenlose Hitze bei Sonnenschein, wie Taugewölk in der Ernteglut.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 18, 5, 'Denn vor der Ernte, sobald die Blüte vorüber ist und der Beerenbüschel zur reifenden Traube wird, da schneidet er die Ranken mit Winzermessern ab und entfernt die Triebe, haut sie ab.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 18, 6, 'Sie werden dann allesamt den Raubvögeln der Berge und dem Getier des Landes überlassen, so daß die Raubvögel während des Sommers darauf verbleiben und alles Getier des Landes den Winter hindurch darauf zubringt.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 18, 7, 'Zu jener Zeit werden dem HERRN der Heerscharen Weihgeschenke dargebracht werden von dem hochgewachsenen und blanken Volk, von dem Volk, das, seit es besteht, gefürchtet ist, von der Völkerschaft, die gewaltige Kraft besitzt und alles niedertritt, deren Land Ströme durchschneiden, – hin zu der Stätte, wo der Name des HERRN der Heerscharen wohnt, zum Berge Zion.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 19, 1, 'Ausspruch über Ägypten: Seht, der HERR fährt auf einer schnellen Wolke einher und kommt nach Ägypten! Da wanken die Götzen Ägyptens vor ihm, und den Ägyptern verzagt das Herz in ihrer Brust.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 19, 2, '»Da werde ich Ägypter gegen Ägypter aufreizen, so daß sie gegeneinander kämpfen, Bruder gegen Bruder, Freund gegen Freund, Stadt gegen Stadt und Reich gegen Reich.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 19, 3, 'Da wird dann der Mut den Ägyptern in ihrer Brust ausgeleert werden, und ihre geistige Klarheit will ich trüben, daß sie sich um Rat an die Götzen und Zauberer, an die Totenbeschwörer und Wahrsagegeister wenden sollen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 19, 4, 'Und ich will Ägypten in die Hand eines harten Herrschers fallen lassen, und ein grausamer König soll über sie regieren« – so lautet der Ausspruch Gottes, des HERRN der Heerscharen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 19, 5, 'Und die Wasser werden versiegen im Nil, und der Strom wird austrocknen bis auf den Grund;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 19, 6, 'die Kanäle werden dann Gestank verbreiten, die Nilarme in Ägypten flach und wasserlos werden, Rohr und Schilf verwelken.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 19, 7, 'Die Auen am Nil, am Ufer des Nils, und alle Saatfelder am Nil werden verdorren, zu Staub zerstieben und verschwinden.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 19, 8, 'Da werden dann die Fischer klagen, und es trauern alle, die im Nil die Angel auswerfen; und die da Netze auf dem Wasser ausbreiten, werden in Verzweiflung sein.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 19, 9, 'Ratlos stehen alle da, welche gehechelten Flachs verarbeiten, und die Weber von baumwollenen Zeugen erbleichen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 19, 10, 'So werden denn die Säulen des Volkes zermalmt, und alle Lohnarbeiter sind tief bekümmert.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 19, 11, 'Eitel Toren sind die Fürsten von Zoan, die weisesten Ratgeber des Pharaos ein verdummter Rat. Wie könnt ihr nur zum Pharao sagen: »Ich stamme von den Weisen ab, bin ein Nachkomme von den Königen der Vorzeit«?');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 19, 12, 'Wo sind sie denn nun, deine Weisen? Mögen sie dir doch verkünden und offenbaren, was der HERR der Heerscharen über Ägypten beschlossen hat!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 19, 13, 'Als Narren stehen die Fürsten von Zoan da, getäuscht die Fürsten von Memphis; und irregeführt haben Ägypten die Vorsteher seiner Gaue.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 19, 14, 'Der HERR hat ihnen einen Geist des Schwindels eingegeben, so daß sie Ägypten bei allen seinen Unternehmungen taumeln machen, gleichwie ein Trunkener umhertaumelt, wenn Erbrechen bei ihm eingetreten ist;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 19, 15, 'und so wird es für Ägypten kein Werk mehr geben, das Kopf und Schwanz, Palmzweig und Binse auszuführen vermöchten.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 19, 16, 'An jenem Tage werden die Ägypter wie Weiber sein und werden zittern und beben vor der Hand, die der HERR der Heerscharen gegen sie schwingt;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 19, 17, 'und so wird das Land Juda für die Ägypter ein betäubender Schrecken sein: sooft man es vor ihnen erwähnt, werden sie in Angst geraten vor dem Ratschluß, den der HERR der Heerscharen in bezug auf sie gefaßt hat.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 19, 18, 'An jenem Tage wird es fünf Städte im Lande Ägypten geben, welche die Sprache Kanaans reden und dem HERRN der Heerscharen Treue schwören; eine von ihnen wird Ir-Heres heißen. –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 19, 19, 'An jenem Tage wird für den HERRN ein Altar mitten im Lande Ägypten und eine Denksäule nahe an dessen Grenze für den HERRN stehen;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 19, 20, 'beides wird ein Denkzeichen und Zeugnis für den HERRN der Heerscharen im Lande Ägypten sein: wenn sie zum HERRN wegen der Bedränger schreien, wird er ihnen einen Helfer senden, der für sie streiten und sie erretten wird.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 19, 21, 'So wird sich denn der HERR den Ägyptern zu erkennen geben, und die Ägypter werden an jenem Tage zur Erkenntnis des HERRN gelangen, so daß sie ihn mit Schlachtopfern und Speisopfern verehren und dem HERRN Gelübde darbringen und sie auch erfüllen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 19, 22, 'Wenn so der HERR den Ägyptern Wunden geschlagen, aber sie auch wieder geheilt hat, werden sie sich zum HERRN bekehren, und er wird sich von ihnen erbitten lassen und sie heilen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 19, 23, 'An jenem Tage wird eine gebahnte Straße von Ägypten nach Assyrien gehen, so daß die Assyrer Ägypten und die Ägypter Assyrien besuchen können, und die Ägypter werden dem HERRN im Verein mit den Assyrern dienen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 19, 24, 'An jenem Tage wird Israel als drittes Glied im Bunde mit Ägypten und Assyrien stehen als ein Segen inmitten der Erde,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 19, 25, 'wozu der HERR der Heerscharen es gesegnet hat mit den Worten: »Gesegnet sei mein Volk Ägypten und Assyrien, das Werk meiner Hände, und Israel, mein Erbbesitz!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 20, 1, 'In dem Jahre, in welchem Tartan, als ihn Sargon, der König von Assyrien, gesandt hatte, nach Asdod kam und diese Stadt belagerte und eroberte –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 20, 2, 'in jener Zeit hatte der HERR durch Jesaja, den Sohn des Amoz, folgende Weisung ausgesprochen: »Wohlan, lege das härene Gewand von deinen Hüften ab und binde dir die Sandalen von deinen Füßen ab!« Da tat er demgemäß, so daß er ohne Obergewand und barfuß einherging.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 20, 3, 'Darauf sagte der HERR: »Gleichwie mein Knecht Jesaja ohne Obergewand und barfuß drei Jahre lang einhergegangen ist als ein Wahrzeichen und eine Vorbedeutung für Ägypten und Äthiopien,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 20, 4, 'so wird der König von Assyrien die gefangenen Ägypter und die zur Wegführung bestimmten Äthiopier, Jünglinge und Greise, ohne Obergewand und barfuß und mit nacktem Gesäß – eine Schmach für Ägypten – dahinwandern lassen.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 20, 5, 'Da wird man denn (in Juda) bestürzt und enttäuscht sein wegen Äthiopiens, auf das man zuversichtlich gehofft, und wegen Ägyptens, mit dem man geprahlt hatte;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 20, 6, 'und die Bewohner dieses Küstenlandes werden zu jener Zeit sagen: »Ach, wenn es denen so ergangen ist, auf die wir zuversichtlich gehofft und zu denen wir unsere Zuflucht genommen hatten, um uns vor dem Könige von Assyrien zu retten: wie sollten wir da entrinnen?«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 21, 1, 'Ausspruch über die Meereswüste; Wie Stürme im Südland daherfahren, so kommt’s aus der Wüste, aus einem furchtbaren Lande.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 21, 2, 'Ein hartes Gesicht ist mir kundgetan worden: »Der Räuber raubt, und der Verwüster verwüstet! Ziehe heran, Elam! Unternimm die Belagerung, Medien! Allem Seufzen über sie mache ich nun ein Ende!« –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 21, 3, 'Darum sind meine Hüften voll Beben; Wehen haben mich erfaßt wie die Wehen einer Gebärenden; mir schwindelt, so daß ich nicht mehr höre; bestürzt bin ich, so daß ich nicht sehen kann;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 21, 4, 'die Sinne vergehen mir, Entsetzen betäubt mich, die mir sonst so liebe Dämmerstunde hat es mir zum Grauen gemacht!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 21, 5, 'Man rüstet die Tafel, man breitet die Teppiche hin, man ißt, man trinkt: – »Erhebt euch, ihr Fürsten, salbt den Schild!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 21, 6, 'Denn so hat der Allherr mir geboten: »Gehe, laß den Späher auf seinen Posten treten: Was er sehen wird, soll er ansagen!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 21, 7, 'Und erblickt er einen Zug Berittener, Paare von Reisigen, einen Zug von Eseln, einen Zug von Kamelen, so horche er scharf auf, mit gespannter Aufmerksamkeit,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 21, 8, 'und lasse den Löwenruf erschallen!« »Auf dem Wachtturm stehe ich, o Herr, beständig bei Tage, und auf meiner Warte stelle ich mich alle Nächte hindurch auf;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 21, 9, 'und siehe, da kommt ein Zug berittener Männer, Reisige paarweise!« Da hob er an und rief: »Gefallen, gefallen ist Babylon! Und alle Schnitzbilder der Götter der Stadt hat man in Trümmern zu Boden geschmettert!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 21, 10, 'O du mein zerdroschenes Volk und mein Tennenkind! Was ich vernommen habe vom HERRN der Heerscharen, dem Gott Israels, das habe ich euch angesagt!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 21, 11, 'Ausspruch (an die Edomiter) über Duma: Von Seir her ruft man mir zu: »Wächter, wie spät ist’s in der Nacht? Wächter, wie spät ist’s in der Nacht?«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 21, 12, 'Der Wächter antwortet: »Der Morgen kommt, aber es ist auch noch Nacht; wenn ihr mehr wissen wollt, so kommt ein andermal wieder und fragt!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 21, 13, 'Ausspruch (an die Dedaniter) über Arabien: Im Gebüsch, am Abend müßt ihr nächtigen, ihr Reisezüge der Dedaniter.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 21, 14, 'Bringt den Dürstenden Wasser entgegen, ihr Bewohner des Landes Thema! Bietet den Flüchtlingen das ihnen gebührende Brot an!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 21, 15, 'Denn vor Schwertern sind sie geflohen, vor dem gezückten Schwert, und vor dem gespannten Bogen und vor den Schrecken des Krieges.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 21, 16, 'Denn so hat der Allherr zu mir gesprochen: »Binnen Jahresfrist, wie die Jahre eines Söldners sind, da wird es mit der ganzen Herrlichkeit Kedars zu Ende sein.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 21, 17, 'Was dann von der Zahl der Bogenschützen der heldenmütigen Söhne Kedars noch übrig ist, wird gering sein; denn der HERR, der Gott Israels, hat es angesagt.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 22, 1, 'Ausspruch über das Schautal: Was ist dir denn, daß du insgesamt hinaufgestiegen bist auf die Dächer,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 22, 2, 'du lärmerfüllte, tosende Stadt, du frohlockende Festung? Deine Erschlagenen sind ja nicht vom Schwert erschlagen und nicht im Kriege gefallen;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 22, 3, 'nein, alle deine Heerführer sind ausnahmslos flüchtig geworden, haben sich ohne Bogen(-schuß) gefangennehmen lassen; ja dein ganzes Aufgebot ist insgesamt in Gefangenschaft geraten, wenn sie auch schon fernhin entflohen waren.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 22, 4, 'Darum sage ich: »Blickt weg von mir, laßt mich bitterlich weinen! Redet nicht auf mich ein, um mich zu trösten über die Vernichtung der Tochter meines Volks!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 22, 5, 'Denn ein Tag der Bestürzung und Zertretung und Verwirrung kommt von Gott, dem HERRN der Heerscharen, im Schautal, ein Tag, welcher Mauern zertrümmert und Wehgeschrei nach dem Berge hin erschallen läßt;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 22, 6, 'hat doch Elam den Köcher sich umgehängt als Zug von berittenen Mannen, und Kir hat den Schild enthüllt.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 22, 7, 'So haben sich denn deine herrlichsten Talgründe mit Kriegswagen gefüllt und die Reiter ihre Aufstellung gegen das Stadttor genommen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 22, 8, 'Da zog er die Binde von den Augen Judas weg, aber das blickte in jener Zeit nach dem Waffenvorrat im Waldhause,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 22, 9, 'und ihr saht nach den schadhaften Stellen in (der Mauer) der Davidsstadt, denn sie waren zahlreich, und ihr sammeltet die Wasser des unteren Teichs;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 22, 10, 'auch zähltet ihr die Häuser von Jerusalem und risset Gebäude nieder, um die Mauer stärker zu machen,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 22, 11, 'und legtet ein Sammelbecken an zwischen den beiden Mauern für die Wasser des alten Teichs; aber ihr saht euch nicht nach dem um, der es so gefügt hatte, und um den, der es seit langer Zeit so bestimmt hatte, kümmertet ihr euch nicht.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 22, 12, 'Wohl forderte euch Gott, der HERR der Heerscharen, damals zum Weinen und zur Wehklage, zum Kahlscheren und zum Anlegen von Sackleinen auf;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 22, 13, 'aber siehe da: es herrschte Lustbarkeit und Jubel, Rinderschächten und Schafeschlachten, Fleischessen und Weintrinken: »Laßt uns essen und trinken, denn morgen sind wir tot!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 22, 14, 'Darum hat der HERR der Heerscharen sich immer wieder in meinen Ohren (mit der Drohung) vernehmen lassen: »Wahrlich, diese Verschuldung soll euch nicht vergeben werden, bis ihr sterbt!« – Gott, der HERR der Heerscharen, hat es ausgesprochen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 22, 15, 'So hat Gott, der HERR der Heerscharen, gesprochen: »Gehe hin, tritt ein bei diesem Verwalter da, bei Sebna, dem Palastvorsteher, und sage zu ihm:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 22, 16, '›Was hast du hier und wen hast du hier, daß du dir hier ein Grab hast aushauen lassen? Du, der sich hier oben sein Grab hat aushauen, eine Ruhestätte sich in den Felsen hat meißeln lassen?!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 22, 17, 'Wisse wohl: der HERR wird dich mit Wucht weit wegschleudern, du Held, und dich mit aller Kraft packen;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 22, 18, 'er wird dich fest zusammenwickeln zu einem Knäuel und dich wie einen Ball in ein weit und breit offenes Land werfen: dort wirst du sterben, und dorthin sollen deine Prachtwagen kommen, du Schande für das Haus deines Gebieters!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 22, 19, 'Ja so will ich dich aus deinem Amt stoßen, und aus deiner Stellung wird man dich herunterreißen!‹«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 22, 20, '»An jenem Tage aber wird es geschehen, daß ich meinen Knecht Eljakim, den Sohn Hilkias, berufe.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 22, 21, 'Ihn will ich mit deinem Rock bekleiden und mit deinem Gurt ihn umgürten und deine Amtsgewalt in seine Hand legen, damit er den Bewohnern Jerusalems und dem (ganzen) Hause Juda ein Vater werde.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 22, 22, 'Ich will ihm den Schlüssel zum Hause Davids auf die Schulter legen, so daß, wenn er aufschließt, niemand zuschließen kann und, wenn er zuschließt, niemand öffnen darf.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 22, 23, 'Als einen Pflock will ich ihn an einer festen Stelle einschlagen, und er soll ein Ehrenstuhl für das Haus seines Vaters werden.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 22, 24, 'Aber wenn sich dann an ihn die ganze vielköpfige Menge seines Vaterhauses hängt: die Sprößlinge und Schößlinge, alle die kleinen Gefäße vom Beckengeschirr an bis zu sämtlichem Kruggeschirr:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 22, 25, '»An jenem Tage« – so lautet der Ausspruch des HERRN der Heerscharen – »wird der Pflock, der an fester Stelle eingeschlagen war, nachgeben, wird abgehackt werden und herunterfallen, und die Last, die an ihm hing, wird zerschellen; denn der HERR hat es ausgesprochen.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 23, 1, 'Ausspruch über Tyrus: Jammert, ihr Tharsisschiffe! Denn verwüstet ist sie: kein Haus ist mehr vorhanden, keine Einfahrt mehr möglich! Bei der Fahrt vom Lande der Kitthäer her ist ihnen die Kunde zugegangen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 23, 2, 'Verstummet, ihr Bewohner der Meeresgestade, Kaufleute von Sidon, Meerbefahrer, die dich bisher angefüllt haben!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 23, 3, 'Auf weiter Flut war das Getreide des Sichor, die Ernte des Nilflusses ihr Gewinn, und sie wurde zum Stapelplatz der Völker.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 23, 4, 'Schäme dich, Sidon! Denn das Meer, das Bollwerk am Meer, spricht klagend: »Ich bin nicht Mutter geworden und habe keine Kinder geboren, keine Jünglinge großgezogen, keine Jungfrauen hochgebracht!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 23, 5, 'Sobald die Kunde nach Ägypten dringt, werden sie in Zittern geraten (wie) bei der Kunde über Tyrus.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 23, 6, 'Fahrt nach Tharsis hinüber! Jammert, ihr Bewohner der Küste!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 23, 7, 'Ist dies eure freudenreiche Stadt, deren Ursprung in die Tage der Vorzeit reicht, deren Füße sie in die Ferne trugen, um sich dort anzusiedeln?');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 23, 8, 'Wer hat solches Geschick verhängt über Tyrus, die Kronenspenderin, deren Kaufleute Fürsten, deren Großhändler die Geehrtesten der Erde waren?');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 23, 9, 'Der HERR der Heerscharen hat es verhängt, um jegliche prunkende Hoffart zu entweihen, um zu verunehren alle Geehrtesten der Erde.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 23, 10, 'Überflute dein Land wie der Nilstrom, du Einwohnerschaft von Tharsis: es ist kein beengender Gürtel mehr da!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 23, 11, 'Er hat seine Hand über das Meer ausgestreckt, hat Königreiche in Zittern versetzt; der HERR hat gegen Phönizien den Befehl erteilt, die dortigen festen Plätze zu zerstören,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 23, 12, 'und hat geboten: »Du sollst hinfort nicht mehr frohlocken, du geschändete, jungfräuliche Bevölkerung von Sidon! Mache dich auf, ziehe zu den Kitthäern hinüber: auch dort wird dir keine Ruhe gewährt werden!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 23, 13, 'Siehe, das Land der Chaldäer – dies ist das Volk, das vormals noch gar nicht da war, Assyrien hat es für Wüstentiere bestimmt – errichtet seine Warttürme, zerstört die Paläste des Landes und macht es zu einem Trümmerhaufen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 23, 14, 'Jammert, ihr Tharsisschiffe, denn verwüstet ist euer Bollwerk!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 23, 15, 'Zu jener Zeit wird Tyrus in Vergessenheit geraten siebzig Jahre lang, als wäre es die Regierungszeit eines einzigen Königs; aber nach Ablauf von siebzig Jahren wird es Tyrus ergehen, wie es im Lied von der Lustdirne heißt:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 23, 16, '»Nimm die Harfe, ziehe in der Stadt umher, vergessene Dirne du! Spiele schön, singe Lied auf Lied, damit man sich deiner wieder erinnert!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 23, 17, 'Nach Ablauf von siebzig Jahren nämlich wird der HERR (die Stadt) Tyrus heimsuchen, und es wird zu seinem gewinnreichen Handel zurückkehren und mit allen Reichen der Erde, die auf dem weiten Erdboden sind, in Verkehr treten.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 23, 18, 'Aber sein Erwerb und Handelsgewinn wird (alsdann) dem HERRN geweiht sein: man wird ihn nicht ansammeln und nicht aufhäufen, sondern ihr Handelserwerb wird denen, die vor dem Angesicht des HERRN wohnen, zum Sattessen und zu prächtiger Kleidung dienen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 24, 1, 'Wisset wohl: der HERR entleert die Erde und verödet sie; er entstellt ihr Aussehen und zerstreut ihre Bewohner.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 24, 2, 'Da ergeht es dem Priester wie dem Mann des Volkes, dem Herrn wie seinem Knecht, der Herrin wie ihrer Magd, dem Verkäufer wie dem Käufer, dem Darleiher wie dem Entlehner, dem Gläubiger ebenso wie seinem Schuldner.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 24, 3, 'Gänzlich ausgeleert wird die Erde und völlig ausgeplündert; denn der HERR ist’s, der dieses Drohwort ausgesprochen hat.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 24, 4, 'Es trauert, es verwelkt die Erde, es verschmachtet, es verwelkt der Erdkreis; es verschmachten auch die Höchsten des Erdenvolkes!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 24, 5, 'Entweiht liegt ja die Erde da unter ihren Bewohnern; denn sie haben die Gebote übertreten, das Gesetz überschritten, den in der Urzeit geschlossenen Bund gebrochen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 24, 6, 'Darum verzehrt ein Fluch die Erde, und ihre Bewohner müssen ihre Verschuldung büßen; darum sterben die Bewohner der Erde aus, und von den Sterblichen bleiben nur wenige übrig.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 24, 7, 'Es trauert der Most, der Weinstock verschmachtet, es seufzen alle, die sonst frohgemut waren;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 24, 8, 'still geworden ist der lustige Paukenschlag, aufgehört hat das Lärmen der Jubelnden, es feiert der fröhliche Zitherklang;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 24, 9, 'man trinkt keinen Wein mehr bei Gesang, bitter schmeckt der Rauschtrank seinen Zechern.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 24, 10, 'In Trümmern liegt jede verödete Stadt, jedes Haus ist dem Eintritt verschlossen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 24, 11, 'Laute Klagen um den Wein erschallen auf den Straßen, verschwunden ist alle Freude, ausgewandert der Jubel der Erde.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 24, 12, 'Nur Verödung ist in der Stadt übriggeblieben, und in Trümmer sind die Tore zerschlagen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 24, 13, 'Denn so wird es sein inmitten der Erde, mitten unter den Völkern, wie beim Abklopfen der Oliven, wie bei der Nachlese, wenn die Obsternte zu Ende ist.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 24, 14, 'Jene erheben lauten Jubel, jauchzen über die Hoheit des HERRN vom Westmeer her:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 24, 15, '»Darum gebet dem HERRN die Ehre in den Ländern des Sonnenaufgangs (und) an den Gestaden des Meeres dem Namen des HERRN, des Gottes Israels!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 24, 16, 'Vom Saum der Erde her haben wir Lobgesänge vernommen: »Preis dem Gerechten!« Ich aber rufe aus: »Ach, ich Ärmster, ich Ärmster, wehe mir! Räuber rauben, ja räuberisch rauben Räuber!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 24, 17, 'Grauen und Grube und Garn kommen über euch, Bewohner der Erde,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 24, 18, 'und geschehen wird es: Wer da flieht vor dem grauenvollen Schrecknis, der stürzt in die Grube, und wer aus der Grube wieder heraufsteigt, der fängt sich im Garn; denn die Fenster in der Höhe droben tun sich auf, und es erbeben die Grundfesten der Erde.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 24, 19, 'In Trümmer wird die Erde zertrümmert, in Splitter wird die Erde zersplittert, in Wanken und Schwanken gerät die Erde;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 24, 20, 'hin und her taumelt die Erde wie ein Trunkener und schaukelt hin und her wie eine Hängematte, und schwer lastet ihr Frevel auf ihr: sie stürzt hin und steht nicht wieder auf.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 24, 21, 'An jenem Tage aber wird es geschehen: da wird der HERR zur Rechenschaft ziehen das Heer der Höhe in der Höhe und die Könige der Erde auf der Erde;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 24, 22, 'und sie werden zusammen eingesperrt, wie man Gefangene zusammenholt in eine Grube, und eingeschlossen in einen festverschlossenen Kerker und erst nach langer Zeit abgeurteilt werden.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 24, 23, 'Da wird dann der bleiche Mond erröten und die glühende Sonne erbleichen; denn der HERR der Heerscharen tritt alsdann die Königsherrschaft an auf dem Berge Zion und in Jerusalem, und angesichts seiner Ältesten wird strahlender Lichtglanz sein.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 25, 1, 'O HERR, du bist mein Gott: ich will dich erheben, will deinen Namen preisen; denn du hast Wunderbares vollbracht, Ratschlüsse, die von längst her gefaßt waren, ausgeführt, Treue in Wahrheit geübt.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 25, 2, 'Denn du hast die Stadt zu einem Steinhaufen gemacht, die feste Burg zu einer Trümmerstätte, die Paläste der Gottentfremdeten unbewohnt: niemals werden sie wieder aufgebaut werden.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 25, 3, 'Darum ehrt dich das starke Volk, fürchtet dich die Stadt der gewalttätigen Völkerschaften.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 25, 4, 'Denn du bist eine Zuflucht gewesen dem Schwachen, eine Zuflucht dem Armen in seiner Bedrängnis, ein Obdach vor dem Unwetter, ein Schatten vor der Sonnenglut; denn das Zornesschnauben der Gewalttätigen ist wie ein gegen eine Wand stürmendes Unwetter,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 25, 5, 'wie Sonnenglut in dürrer Heide. Du hast das Tosen der Gottentfremdeten zum Verstummen gebracht; wie Sonnenglut durch den Schatten des Gewölks, so ist der Siegesgesang der Gewalttätigen gedämpft worden.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 25, 6, 'Dann wird der HERR der Heerscharen allen Völkern auf diesem Berge ein Gastmahl von fetten Speisen bereiten, ein Mahl von abgelagerten Weinen, von markreichen Fettspeisen, von geläuterten abgelagerten Weinen;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 25, 7, 'und er wird auf diesem Berge die Schleierhülle hinwegziehen, die alle Völker umhüllt, und die Decke, die über alle Völkerschaften ausgebreitet ist.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 25, 8, 'Den Tod wird er auf ewig verschwinden lassen, die Tränen wird Gott der HERR von jedem Antlitz abwischen und die Schmach seines Volkes überall auf der Erde tilgen; denn der HERR hat es zugesagt.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 25, 9, 'Da wird man denn an jenem Tage sagen: »Seht, da ist unser Gott, auf den wir geharrt haben, daß er uns errette; da ist der HERR, auf den wir geharrt haben: laßt uns jubeln und uns freuen über seine Hilfe!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 25, 10, 'Denn die Hand des HERRN wird auf diesem Berge ruhen; Moab aber wird auf seinem Boden niedergetreten werden, wie ein Strohbündel in der Lache einer Düngerstätte niedergetreten wird;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 25, 11, 'und wenn es seine Arme darin ausbreitet, wie der Schwimmer ausgreift, um zu schwimmen, so wird der HERR sein Aufstreben niederdrücken trotz des geschickten Ruderns seiner Arme.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 25, 12, 'Und deine festen, hochragenden Mauern wird er niederwerfen, niederstürzen, zu Boden stoßen bis in den Staub hinein.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 26, 1, 'An jenem Tage wird man dieses Lied im Lande Juda singen: »Eine feste Stadt haben wir; zum Schutz hat er ihr Mauern und Außenwerk geschaffen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 26, 2, 'Öffnet die Tore, damit ein gerechtes Volk einziehe, das die Treue bewahrt!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 26, 3, 'Ein festes Herz segnest du mit Heil, mit Heil, weil es voll Vertrauen auf dich ist.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 26, 4, 'Vertrauet auf den HERRN für und für, denn an Gott dem HERRN habt ihr einen ewigen Felsen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 26, 5, 'Denn niedergeworfen hat er die, welche eine Hochburg bewohnten, eine hochragende Stadt; er hat sie erniedrigt, ja erniedrigt bis zum Erdboden, hat sie niedergestoßen bis in den Staub:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 26, 6, 'zertreten soll sie der Fuß, ja die Füße der Niedrigen, die Tritte der Geringen.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 26, 7, 'Der Pfad des Gerechten ist ebener Pfad, geradeaus geht die Bahn des Gerechten: du läßt sie eben sein.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 26, 8, 'Auch auf dem Wege deiner Gerichte, HERR, harren wir dein; nach deinem Namen und nach deinem Lobpreis steht das Verlangen unsers Herzens.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 26, 9, 'Mein Herz verlangt nach dir in der Nacht, auch sehnt sich mein Geist nach dir in meinem Inneren; denn sobald deine Gerichte die Erde treffen, lernen die Bewohner des Erdkreises Gerechtigkeit.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 26, 10, 'Wird dem Gottlosen Gnade zuteil, so lernt er nicht Gerechtigkeit; nein, in einem Lande, wo das Recht gilt, bleibt er doch ein Frevler und sieht nichts von der Erhabenheit des HERRN.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 26, 11, 'HERR, ist deine Hand auch hocherhoben: sie sehen es nicht; laß sie zu ihrer Beschämung deinen Eifer um dein Volk sehen! Ja, das Zornesfeuer, das deine Widersacher erwartet, möge sie verzehren!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 26, 12, 'HERR, du wirst uns Heil schaffen, denn du hast ja auch alle unsere Taten für uns vollbracht.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 26, 13, 'HERR, unser Gott, es haben zwar außer dir noch andere als Herren über uns geherrscht, aber dich allein preisen wir, deinen Namen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 26, 14, 'Tote leben nicht wieder auf, Unterweltsbewohner erstehen nicht wieder: zu dem Zwecke hast du sie ja heimgesucht und vernichtet und jede Erinnerung an sie ausgetilgt.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 26, 15, 'Gleichwohl hast du Zuwachs dem Volke verliehen, HERR, ja Zuwachs dem Volke; du hast dich verherrlicht, alle Grenzen des Landes weit hinausgerückt.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 26, 16, 'HERR, in der Bedrängnis haben sie dich gesucht; als deine Züchtigung sie traf, haben sie sich in flüsternde Gebete ergossen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 26, 17, 'Wie eine Schwangere, wenn ihre Stunde da ist, sich windet und aufschreit in ihren Wehen, so ist es auch uns, HERR, ergangen – von dir aus geschah es –:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 26, 18, 'wir gingen schwanger, wanden uns in Wehen; doch als wir gebaren, war es Wind: Rettung schafften wir dem Lande nicht, und Erdenbewohner kamen nicht ans Tageslicht.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 26, 19, 'Werden wohl deine Toten wieder aufleben? (Auch) meine Leichen? Ja, sie werden auferstehen! Wacht auf und jubelt, die ihr im Staube ruht! Denn ein Tau der Himmelslichter ist dein Tau, und so wird die Erde die Schatten wieder ans Tageslicht bringen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 26, 20, 'Wohlan, mein Volk, gehe in deine Kammern hinein und schließe deine Türen hinter dir zu! Verbirg dich einen kurzen Augenblick, bis das Zorngericht vorübergegangen ist.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 26, 21, 'Denn gar bald wird der HERR aus seiner Wohnstätte hervortreten, um die Erdbewohner zur Rechenschaft wegen ihrer Verschuldung zu ziehen; dann wird die Erde das von ihr verschluckte Blut wieder zum Vorschein bringen und die in ihr verscharrten Ermordeten nicht länger verbergen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 27, 1, 'An jenem Tage wird der HERR mit seinem harten, großen und starken Schwerte als Rächer kommen über den Drachen, die flüchtige Schlange, und über den Drachen, die geringelte Schlange, und wird das Ungeheuer am Nil töten.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 27, 2, 'An jenem Tage wird man sagen: »Lieblicher Weinberg, singt ihm zu!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 27, 3, 'Ich, der HERR, bin sein Hüter, alle Augenblicke bewässere ich ihn; damit sich niemand an ihm vergreife, hüte ich ihn bei Tag und Nacht.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 27, 4, 'Zorn hege ich keinen; fände ich nur Dornen und Gestrüpp darin: zum Kampfe wollte ich auf sie losgehen und sie verbrennen allzumal!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 27, 5, 'Es müßte sonst sein, daß man Schutz bei mir suchte und Frieden mit mir machte, ja Frieden machte mit mir!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 27, 6, 'In den kommenden Tagen wird Jakob Wurzel schlagen, wird Israel blühen und sprossen, und sie werden den ganzen Erdkreis mit Frucht erfüllen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 27, 7, 'Hat der HERR es etwa so geschlagen, wie er den schlug, der ihm Schläge versetzt hatte? Oder sind sie so hingemordet worden, wie er ihre Mörder umgebracht hat?');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 27, 8, 'Nein, nur durch ihre Verstoßung, durch ihre Wegführung hast du deine Sache mit ihnen geführt: durch seinen schweren Sturm hat er sie hinweggetrieben am Tage des Ostwindes.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 27, 9, 'Deshalb wird dadurch die Verschuldung Jakobs gesühnt, und darin soll die volle Frucht der Hinwegnahme seiner Versündigung bestehen, daß er alle Altarsteine zertrümmerten Kalksteinen gleich macht und keine Astartebilder und Sonnensäulen wieder aufgestellt werden.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 27, 10, 'Denn die feste Stadt liegt öde da, eine verlassene Wohnstätte und einsam wie die Wüste; daselbst weidet das Rind und lagert sich dort und frißt ihre Büsche ab.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 27, 11, 'Wenn deren Zweige dürr geworden sind, bricht man sie ab: Weiber kommen dann und heizen mit ihnen; denn es ist ein Volk ohne Einsicht. Darum erbarmt sich sein Schöpfer seiner nicht, und sein Bildner erweist sich ihm nicht gnädig.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 27, 12, 'Aber geschehen wird es an jenem Tage: da wird der HERR ein Getreidedreschen veranstalten von der Ähre des Euphratstromes bis zum Bach Ägyptens; und ihr werdet (wie bei der Nachlese) einzeln zusammengelesen werden, ihr Kinder Israel.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 27, 13, 'Und geschehen wird es an jenem Tage: da wird in eine große Posaune gestoßen; dann werden alle, die sich im Lande Assyrien (von der Herde) verloren haben, und die im Lande Ägypten Versprengten heimkehren und den HERRN anbeten auf dem heiligen Berge in Jerusalem.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 28, 1, 'Wehe der stolzen Krone der Trunkenbolde Ephraims und der welkenden Blüte seines prangenden Schmuckes auf dem Gipfel des fetten Talgeländes der vom Wein Überwältigten!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 28, 2, 'Schon hält der Allherr einen Starken und Gewaltigen in Bereitschaft: wie ein Hagelwetter, ein verheerender Sturm, wie ein Wolkenbruch gewaltiger, sich ergießender Wasser wird er sie unwiderstehlich zu Boden niederwerfen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 28, 3, 'Mit Füßen wird zertreten werden die stolze Krone der Trunkenbolde Ephraims,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 28, 4, 'und der welkenden Blüte seines prangenden Schmuckes auf dem Gipfel des fetten Talgeländes wird es ergehen wie einer Frühfeige vor der Obsternte: kaum erblickt sie jemand, noch ist sie in seiner Hand, so hat er sie schon verschlungen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 28, 5, 'An jenem Tage wird der HERR der Heerscharen für den Überrest seines Volkes zu einer zierenden Krone und zu einem herrlichen Stirnreif werden');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 28, 6, 'und den Geist der Rechtsprechung dem (verleihen), der zu Gericht sitzt, und Heldenkraft denen, die den Kampf zum Tore hinaus zurücktreiben.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 28, 7, 'Aber auch diese hier wanken infolge von Weingenuß und taumeln vom Rauschtrank: Priester und Propheten schwanken vom Rauschtrank, sind übermannt vom Wein, taumeln vom Rauschtrank, schwanken beim Schauen von Gesichten, wanken beim Rechtsprechen!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 28, 8, 'Denn alle Tische sind voll von Gespei, Unflat bis auf den letzten Platz!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 28, 9, '»Wem will der denn Erkenntnis beibringen und wem Offenbarungen deuten? Etwa Kindern, die eben von der Milch entwöhnt, eben von der Mutterbrust abgesetzt sind?');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 28, 10, 'Da heißt’s immer: ›Tu du dies, tu du das! Mach mal dies, mach mal das! Hier ein bißchen, da ein bißchen!‹«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 28, 11, '»Jawohl, durch Menschen mit stammelnden Lippen und mit fremder Zunge wird er zu diesem Volke reden,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 28, 12, 'er, der zu ihnen gesagt hat: ›Dies (Land der Verheißung) ist die Ruhestätte; schaffet (also) Ruhe den Müden, und dies ist der Rastort!‹ Doch sie haben nicht hören wollen.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 28, 13, 'So wird denn das Wort des HERRN an sie ergehen: »Tu du dies, tu du das! Mach mal dies, mach mal das! Hier ein bißchen, da ein bißchen!«, damit sie auf ihrem Wege rücklings hinstürzen und zerschmettert werden oder im Netz sich verstricken und gefangen werden.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 28, 14, 'Darum vernehmet das Wort des Herrn, ihr Spötter, ihr Herrscher über dieses Volk in Jerusalem!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 28, 15, 'Weil ihr gesagt habt: »Wir haben einen Bund mit dem Tode geschlossen und mit dem Totenreich ein Abkommen getroffen: wenn die Geißel mit ihrer Sturmflut hereinbricht, wird sie uns nicht erreichen; wir haben ja die Lüge zu unserm Schirmdach gemacht und uns in Trug geborgen« –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 28, 16, 'darum hat Gott der HERR so gesprochen: »Wisset wohl! Ich bin’s, der in Zion einen Grundstein legt, einen erprobten Stein, einen kostbaren Eckstein, der felsenfest gegründet ist: ›Wer da glaubt, wird nicht zuschanden‹.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 28, 17, 'Und ich mache das Recht zur Richtschnur und die Gerechtigkeit zur Setzwaage; und der Hagel wird das Schirmdach der Lüge wegreißen, und die Wasserfluten sollen die Bergungsstätte wegschwemmen.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 28, 18, 'Dann wird euer Bund mit dem Tode hinfällig werden und euer Abkommen mit dem Totenreich abgetan sein: wenn die Geißel mit ihrer Sturmflut hereinbricht, werdet ihr von ihr zermalmt werden.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 28, 19, 'Sooft sie daherfährt, wird sie euch fassen; denn Morgen für Morgen wird sie daherfahren, bei Tag und bei Nacht; und eitel Entsetzen wird es sein, eine Offenbarung zu vernehmen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 28, 20, 'Denn zu kurz ist das Bett, um sich darin auszustrecken, und die Decke zu knapp, um sich darin einzuwickeln.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 28, 21, 'Denn wie am Berge Perazim wird der HERR sich erheben, wie im Tal bei Gibeon wird er vor Zorn beben, um sein Werk zu vollführen – ein befremdliches Werk – und um seine Arbeit zu verrichten – eine ungewöhnliche Arbeit.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 28, 22, 'Nun laßt also euer Spotten, damit eure Fesseln nicht noch fester angezogen werden! Denn ein vernichtendes Strafgericht, so habe ich von Gott, dem HERRN der Heerscharen, vernommen, ist für die ganze Erde fest beschlossen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 28, 23, 'Merkt auf und höret meine Stimme! Gebt acht und vernehmet meine Rede!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 28, 24, 'Pflügt wohl der Landmann immerfort, um zu säen? Furcht er seinen Acker immerfort und egget ihn?');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 28, 25, 'Nicht wahr? Wenn er dessen Oberfläche geebnet hat, so streut er Dill aus und sät Kümmel und legt Weizen reihenweise und Gerste auf ein besonderes Stück und Spelt als Einfassung an seinen Rand.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 28, 26, 'So hat ihn sein Gott unterwiesen zum richtigen Verfahren und hat ihn belehrt.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 28, 27, 'Dill wird ja doch nicht mit dem Dreschschlitten ausgedroschen und das Wagenrad nicht über Kümmel gerollt, sondern Dill wird mit dem Stabe ausgeklopft und Kümmel mit dem Stecken.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 28, 28, 'Wird Brotkorn etwa zermalmt? O nein, nicht immerfort drischt man darauf los und treibt man das Rad seines Wagens und seine Pferde darüber hin: man zermalmt es nicht.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 28, 29, 'Auch dies ist vom HERRN der Heerscharen ausgegangen: wunderbar ist er an Rat, groß an Einsicht.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 29, 1, 'Wehe dir, Gottesherd, Gottesherd, du Stadt, wo David einst sein Lager aufgeschlagen hat! Füget Jahr zu Jahr, laßt die Feste ihren Kreislauf vollziehen:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 29, 2, 'dennoch will ich den Gottesherd bedrängen, daß Stöhnen und Wehklagen entstehen soll: dann wird es mir ein richtiger Gottesherd sein.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 29, 3, 'Ja ich will ein Lager rings um dich aufschlagen und dich mit einer Wagenburg eng einschließen und Belagerungswerke gegen dich aufführen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 29, 4, 'Dann wirst du, unten am Boden liegend, gedämpft reden und, in den Staub gesunken, eine bescheidene Sprache führen, deine Stimme wird wie die eines Totengeistes aus der Erde hervorkommen und deine Rede aus dem Staube heraus nur flüstern.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 29, 5, 'Aber die lärmende Menge deiner Feinde wird wie feiner Staub sein und wie zerstiebende Spreu die lärmende Menge der Gewalttätigen. Doch dann wird es geschehen urplötzlich, in einem Augenblick:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 29, 6, 'da wirst du vom HERRN der Heerscharen heimgesucht werden unter Donner und Erdbeben und mächtigem Krachen, unter Sturmwind und Unwetter und Flammen verzehrenden Feuers.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 29, 7, 'Und gleich einem Traum, einem Nachtgesicht wird die lärmende Menge aller der Völker sein, die gegen den Gottesherd zu Felde ziehen, und alle, die ihn und seine Bollwerke bestürmen und ihn bedrängen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 29, 8, 'Und es wird so sein, wie wenn ein Hungriger träumt, er esse, dann aber mit ungestilltem Verlangen erwacht; und wie wenn ein Durstiger träumt, er trinke, dann aber beim Erwachen sich noch vor Durst erschöpft fühlt und gierig lechzt: ebenso wird es der lärmenden Menge aller der Völker ergehen, die gegen den Berg Zion zu Felde ziehen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 29, 9, 'Starret nur, so daß ihr erstarrt! Lebt in Verblendung, so daß ihr blind werdet! Sie sind trunken, aber nicht vom Wein, sie taumeln, aber nicht vom Rauschtrank.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 29, 10, 'Denn der HERR hat einen Geist tiefen Schlafes über euch ausgegossen und hat eure Augen, die Propheten, verschlossen und eure Häupter, die Seher, umschleiert.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 29, 11, 'So ist denn die gesamte Offenbarung für euch geworden wie der Inhalt eines versiegelten Buches, das man einem, der lesen kann, mit den Worten reicht: »Lies doch dies einmal!«, doch er entgegnet dann: »Ich kann nicht, es ist ja versiegelt!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 29, 12, 'Reicht man aber das Buch einem, der sich nicht auf Geschriebenes versteht, mit den Worten: »Lies doch dies einmal!«, so entgegnet er: »Ich kann nicht lesen.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 29, 13, 'Weiter hat der Allherr gesagt: »Weil dieses Volk sich mir immer nur mit seinem Munde naht und mich nur mit seinen Lippen ehrt, während es sein Herz fern von mir hält und ihre Furcht vor mir nur in angelernten Menschengeboten besteht:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 29, 14, 'darum will ich fernerhin wunderlich mit diesem Volk verfahren, wunderlich und wundersam, so daß die Weisheit seiner Weisen zuschanden werden soll und von dem Verstande seiner Verständigen nichts zu sehen ist.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 29, 15, 'Wehe denen, die ihre Pläne vor dem HERRN tief geheim halten, damit ihr Tun im Finstern vor sich gehe, und die dabei denken: »Wer sieht uns, und wer kennt uns?«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 29, 16, 'O über eure Verkehrtheit! Ist etwa der Töpfer dem Ton gleichzuachten, so daß ein hergestelltes Werk von seinem Hersteller sagen könnte: »Er hat mich nicht geschaffen«, und ein Gebilde von seinem Bildner sagen dürfte: »Er versteht nichts«?');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 29, 17, 'Dauert es nicht nur noch eine ganz kleine Weile, daß der Libanon sich zu einem Fruchtgarten umwandelt und der Fruchtgarten nur als Wald geachtet werden wird?');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 29, 18, 'An jenem Tage werden die Tauben Worte der Schrift vernehmen und die Augen der Blinden aus Dunkel und Finsternis heraus sehen;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 29, 19, 'und die Demütigen werden sich des HERRN aufs neue freuen und die Armen unter den Menschen über den Heiligen Israels jubeln.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 29, 20, 'Denn die Gewalttätigen werden ein Ende genommen haben, und mit den Spöttern wird es aus sein, und alle, deren Gedanken auf Böses gerichtet sind, werden ausgerottet sein,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 29, 21, 'alle, die da Menschen in einer Rechtssache zur Sünde verleiteten und dem, der im Tor Recht spricht, Schlingen legten und den, der im Recht ist, auf nichtige Gründe hin ins Unrecht setzten.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 29, 22, 'Darum hat der HERR, der einst Abraham erlöst hat, so zum Hause Jakobs gesprochen: »Nunmehr soll Jakob nicht mehr enttäuscht werden, und nunmehr soll sein Angesicht nicht mehr erblassen;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 29, 23, 'sondern wenn er [d.h. seine Kinder] das Werk meiner Hände in seiner Mitte sieht, so werden sie meinen Namen heiligen und den Heiligen Jakobs als heilig anerkennen und vor dem Gott Israels Ehrfurcht haben;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 29, 24, 'und solche, die jetzt verkehrten Sinnes sind, werden Einsicht gewinnen, und die Murrenden werden Belehrung annehmen.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 30, 1, '»Wehe den Söhnen« – so lautet der Ausspruch des HERRN –, »die abtrünnig werden dadurch, daß sie einen Plan ins Werk setzen, der nicht von mir ausgeht, und ein Bündnis schließen ohne meine Billigung, um Sünde auf Sünde zu häufen!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 30, 2, 'Sie machen sich auf, um nach Ägypten hinabzuziehen, ohne meinen Mund befragt zu haben, um sich unter den Schutz des Pharaos zu begeben und im Schatten Ägyptens Zuflucht zu suchen!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 30, 3, 'Aber es wird euch der Schutz des Pharaos zur Schande ausschlagen und das Suchen von Zuflucht im Schatten Ägyptens zur Schmach!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 30, 4, 'Denn mögen auch seine Fürsten schon in Zoan eingetroffen sein und seine Gesandten schon Hanes erreicht haben,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 30, 5, 'so werden doch alle enttäuscht werden an einem Volke, das ihnen nichts nützen kann, das ihnen keine Hilfe und keinen Nutzen schafft, sondern nur Enttäuschung und Schimpf dazu.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 30, 6, 'Ausspruch über das Großtier des Südens: In einem Lande voll Drangsal und Bedrängnis – Löwen und Löwinnen, Ottern und geflügelte Giftschlangen gehören zu ihnen – schleppen sie ihre Schätze auf dem Rücken von Eseln und ihre Reichtümer auf den Höckern von Kamelen zu einem Volke, das ihnen nichts nützen kann.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 30, 7, 'Denn eitel und nichtig ist Ägyptens Hilfe; darum nenne ich dieses Volk »Großtuer, die still sitzen«.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 30, 8, '»Gehe jetzt hinein, schreibe es vor ihren Augen auf eine Tafel und trage es in ein Buch ein, damit es für künftige Zeiten als ein ewiges Zeugnis diene.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 30, 9, 'Denn ein widerspenstiges Volk ist es, mißratene Söhne, Söhne, die den Weisungen des HERRN nicht gehorchen wollen,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 30, 10, 'die zu den Sehern sagen: ›Ihr sollt nicht sehen!‹ und zu den Propheten: ›Ihr sollt uns nicht die Wahrheit prophezeien! Verkündet uns angenehme Dinge, prophezeiet uns Täuschungen!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 30, 11, 'Weicht vom rechten Wege ab, verlaßt den rechten Pfad! Laßt uns mit dem Heiligen Israels in Ruhe!‹«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 30, 12, 'Darum hat der Heilige Israels so gesprochen: »Weil ihr dies (mein) Wort verwerft und euer Vertrauen auf Gewalttätigkeit und Schleichwege setzt und euch darauf verlaßt,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 30, 13, 'darum soll euch diese Verschuldung gleich einem sturzdrohenden Riß sein, wie eine Ausbauchung an einer hochragenden Mauer, deren Einsturz plötzlich, in einem Augenblick erfolgt,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 30, 14, 'indem er sie zertrümmert, wie man einen Töpferkrug zertrümmert, den man schonungslos zusammenschlägt, so daß sich unter seinen Stücken keine Scherbe mehr findet, um in ihr etwas Glut vom Feuerherd zu holen oder etwas Wasser aus einer Wasserlache zu schöpfen.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 30, 15, 'Denn so hat Gott der HERR, der Heilige Israels, gesprochen: »Durch Umkehr und Ruhehalten werdet ihr gerettet werden, im Stillesein und Vertrauen besteht eure Kraft. Aber ihr habt nicht gewollt, sondern habt gesagt: ›Nein!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 30, 16, 'Vielmehr auf Rossen wollen wir dahinfliegen!‹ – nun, so sollt ihr dahinfliehen –, ›und auf Rennern wollen wir reiten!‹ – nun, so sollen eure Verfolger die Renner sein.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 30, 17, 'Euer tausend sollen vor dem Kriegsruf eines einzigen fliehen, und vor dem Kriegsruf von fünf Feinden sollt ihr insgesamt fliehen, bis ihr ein Rest geworden seid wie eine Signalstange auf einem Berggipfel und wie ein Banner auf einer Anhöhe.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 30, 18, 'Darum wird der HERR damit zögern, euch Gnade zu erweisen, und darum wird er davon absehen, sich euer zu erbarmen; denn ein Gott des Rechts ist der HERR: wohl allen, die auf ihn harren!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 30, 19, 'Ja du Volk in Zion, das in Jerusalem wohnt, du sollst nicht immerfort weinen! Gewißlich wird er sich dir gnädig erweisen auf deinen Hilferuf hin: sobald er ihn vernimmt, wird er dich erhören.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 30, 20, 'Und der Allherr wird euch zwar das Brot der Drangsal und das Wasser der Trübsal reichen, aber deine Lehrer werden sich nicht abermals verbergen (müssen), sondern deine Augen werden deine Lehrer erblicken');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 30, 21, 'und deine Ohren hinter dir den Zuruf vernehmen: »Dies ist der Weg, wandelt auf ihm!«, mögt ihr zur Rechten gehen oder zur Linken abbiegen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 30, 22, 'Da wirst du dann deine mit Silber überzogenen Schnitzbilder und deine mit Gold bekleideten Gußbilder als unrein ansehen: wie etwas Ekelhaftes wirst du sie wegwerfen mit dem Zuruf: »Hinaus mit euch!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 30, 23, 'Dann wird er dir Regen geben für deine Aussaat, mit der du den Acker bestellt hast, und Brot als Ertrag deines Feldes, und zwar wird es saftig und nahrhaft sein. Deine Herden werden zu jener Zeit auf weiter Flur weiden,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 30, 24, 'und die Ochsen und Esel, die das Ackerland bearbeiten, werden gesalzenes Mengfutter fressen, das mit der Wurfschaufel und der Gabel geworfelt ist.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 30, 25, 'Und auf jedem hohen Berge und auf jeder ragenden Anhöhe wird es Bäche sprudelnden Wassers geben am Tage des großen Blutbades, wenn die Türme fallen;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 30, 26, 'und das Licht des Mondes wird so hell sein wie das Sonnenlicht, und das Licht der Sonne wird siebenmal so hell scheinen wie das Licht der sieben Wochentage zu der Zeit, wo der HERR den Schaden seines Volkes verbindet und die ihm geschlagene Wunde heilt.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 30, 27, 'Sehet, der HERR kommt persönlich aus der Ferne daher: sein Zorn lodert, und gewaltig ist seine Erregung; seine Lippen sind voll Grimms, und seine Zunge ist wie fressendes Feuer;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 30, 28, 'sein Atem gleicht einem flutenden Wasserstrom, der bis an den Hals reicht; – um die Völker in der Schwinge der Vernichtung zu schwingen und den Völkerschaften einen irreleitenden Zaum an die Kinnbacken zu legen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 30, 29, 'Da werdet ihr Lieder anstimmen wie in der Nacht, in der man die Festfeier vollzieht, und euch von Herzen freuen wie die (Wallfahrer), die unter Flötenklang dahinziehen, um auf den Berg des HERRN zu gelangen, hin zum Felsen Israels.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 30, 30, 'Dann wird der HERR seine machtvolle (Donner-) Stimme hören lassen und seinen Arm zeigen, der niederfährt bei schnaubendem Zorn und mit verzehrender Feuerflamme, unter Wolkenbruch und Wetterguß und Hagelsteinen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 30, 31, 'Denn vor der (Donner-) Stimme des HERRN wird Assyrien erschrecken, wenn er es mit dem Stecken schlägt;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 30, 32, 'und sooft der Züchtigungsstab daherfährt, den der HERR auf ihn niederfallen läßt, wird es geschehen unter Paukenschall und Harfenklang; und mit geschwungenem Arm kämpfend wird er gegen sie streiten.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 30, 33, 'Denn längst ist eine Greuelbrandstätte hergerichtet: auch sie ist für den König bestimmt; tief und breit hat er ihren Scheiterhaufen angelegt, mit Feuerung und Holz in Menge: gleich einem Schwefelstrom setzt der Hauch des HERRN ihn in Brand.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 31, 1, 'Wehe denen, die nach Ägypten hinabziehen, um Hilfe (zu erlangen) und sich auf Kriegsrosse zu stützen! Die ihr Vertrauen auf Streitwagen setzen, weil ihrer so viele sind, und auf Rosse, weil ihre Zahl so groß ist, aber auf den Heiligen Israels nicht schauen und den HERRN nicht befragen!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 31, 2, 'Doch auch er ist weise und läßt Unheil kommen und nimmt seine Drohworte nicht zurück; nein, aufstehen wird er gegen das Haus der Frevler und gegen die Helferschaft von Übeltätern.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 31, 3, 'Denn die Ägypter sind Menschen und nicht Gott, und ihre Rosse sind Fleisch und nicht Geist; streckt der HERR seine Hand aus, so stürzt der Beschützer, und der Schützling kommt zu Fall, so daß sie alle miteinander vernichtet werden.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 31, 4, 'Denn so hat der HERR zu mir gesprochen: »Gleichwie der Löwe, der Jungleu, über seinem Raube brummt – die volle Zahl der Hirten hat man gegen ihn aufgeboten, aber vor ihrem Geschrei erschrickt er nicht, und trotz ihres Getümmels wird ihm nicht bange –, so wird der HERR der Heerscharen herabfahren zur Heerfahrt auf den Berg Zion und auf dessen Anhöhe.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 31, 5, 'Wie flatternde Vögel, so wird der HERR der Heerscharen Jerusalem beschirmen, ja beschirmen und erretten, verschonen und befreien.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 31, 6, 'Kehret doch zurück zu ihm, von dem ihr so tief abgefallen seid, ihr Kinder Israel!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 31, 7, 'Denn an jenem Tage wird ein jeder von ihnen seine silbernen und seine goldenen Götzen verabscheuen, die eure Hände euch zur Sünde angefertigt haben;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 31, 8, 'und Assyrien wird fallen durch das Schwert eines Nicht-Mannes, und das Schwert eines Nicht-Menschen wird es fressen; und ergreift es die Flucht vor dem Schwert, so werden seine Jünglinge der Knechtschaft verfallen;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 31, 9, 'sein Fels aber wird vor Grauen vergehen, und seine Fürsten werden von den Fahnen weggeschreckt werden« – so lautet der Ausspruch des HERRN, der einen Feuerherd in Zion hat und einen Ofen in Jerusalem.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 32, 1, 'Dereinst wird ein König mit Gerechtigkeit sein Königtum führen, und die Fürsten werden nach dem Recht ihr Amt verwalten;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 32, 2, 'ein jeder von ihnen wird wie ein Zufluchtsort vor dem Sturmwind sein und wie ein Schutzdach vor dem Unwetter, wie Wasserbäche in dürrer Steppe, wie der Schatten eines mächtigen Felsens in einer lechzenden Gegend.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 32, 3, 'Da werden die Augen der Sehenden nicht mehr starr blicken, und die Ohren der Hörenden werden aufmerken;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 32, 4, 'das Herz der Unbesonnenen wird Einsicht lernen und die Zunge der Stammelnden geläufig sein in deutlicher Rede.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 32, 5, 'Zu einem gemeinen Menschen wird man dann nicht mehr ›Edelmann‹ sagen und einen Schurken nicht mehr als ›gnädiger Herr‹ anreden.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 32, 6, 'Denn ein gemeiner Mensch redet Gemeinheit, und sein Sinn ist auf Arges gerichtet, indem er Ruchlosigkeit verübt und Verkehrtes gegen den HERRN redet, indem er das Verlangen des Hungrigen ungestillt läßt und dem Durstigen den Trank versagt.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 32, 7, 'Und der Schurke – seine Waffen sind böse; ein solcher entwirft arglistige Anschläge, um Elende durch Lügenreden zu verderben, selbst wenn der Arme sein Recht dartut.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 32, 8, 'Der Edle dagegen hegt edle Gedanken, und ein solcher beharrt auch bei edlem Tun.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 32, 9, 'Ihr sorglosen Frauen, auf, höret meine Stimme! Ihr zuversichtlichen Töchter, vernehmet meine Rede!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 32, 10, 'Nur wenige Tage auf ein Jahr, dann werdet ihr zittern, ihr Zuversichtlichen! Denn vernichtet wird dann die Weinlese sein, und auch keine Obsternte wird eingebracht werden.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 32, 11, 'Zittert, ihr Sorglosen! Erbebt, ihr Zuversichtlichen! Zieht euch doch aus, entkleidet euch und gürtet den Trauergurt um die Hüften!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 32, 12, 'Schlagt euch auf die Brüste wehklagend wegen der herrlichen Gefilde, wegen der fruchtreichen Reben,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 32, 13, 'wegen der Äcker meines Volkes, die in Dornen und Gestrüpp aufschießen, ach, wegen all der wonnigen Häuser in der freudenreichen Stadt!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 32, 14, 'Denn die Paläste stehen verlassen da, der Lärm der Stadt ist verstummt, der Burgberg und der Wartturm sind zu Höhlen geworden für immer, den Wildeseln zur Wonne, den Herden zum Weideplatz.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 32, 15, 'Doch endlich wird der Geist aus der Höhe über uns ausgegossen werden: dann wird die Steppe zum Fruchtgarten werden und der Fruchtgarten (wegen der Baumfülle) als Wald gelten.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 32, 16, 'Dann wird das Recht sogar in der (früheren) Steppe wohnen und die Gerechtigkeit eine Stätte im Fruchtgarten haben;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 32, 17, 'und die Wirkung der Gerechtigkeit wird Friede sein und das Ergebnis der Gerechtigkeit Ruhe und Sicherheit für immer.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 32, 18, 'Mein Volk wird dann an einer Stätte des Friedens wohnen, in sicheren Behausungen und an sorgenfreien Ruheplätzen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 32, 19, 'Aber hageln wird es, wenn der Wald niederstürzt und die Stadt in Niedrigkeit versinkt.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 32, 20, 'Wohl euch, die ihr dann überall an den Wassern säen dürft und den Fuß der Rinder und der Esel frei umherschweifen lassen könnt!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 33, 1, 'Wehe dir, Verwüster, der doch selbst keine Verwüstung erlitten hat! Und wehe dir, Räuber, der selbst von niemand beraubt worden ist! Sobald du mit Verwüsten fertig bist, wirst du selbst verwüstet werden; sobald du genug geraubt hast, wird man dich selbst berauben. –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 33, 2, 'HERR, erbarme dich unser; auf dich hoffen wir: sei unser Arm an jedem Morgen und unsere Hilfe in der Stunde der Not!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 33, 3, 'Vor dem donnernden Tosen (deines Nahens) fliehen die Völker, und wenn du dich erhebst, zerstieben die Heiden.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 33, 4, 'Dann wird eure Beute voll eingesammelt werden, wie ein Heuschreckenschwarm einsammelt, und wie Grashüpfer dahinrennen, so rennt man darauf los.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 33, 5, 'Erhaben ist der HERR, denn er wohnt in der Höhe: er wird Zion mit Recht und Gerechtigkeit füllen;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 33, 6, 'und er wird die feste Grundlage deiner Geschicke sein, eine Fülle von Heil, von Weisheit und Erkenntnis; die Furcht des HERRN ist sein Schatz.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 33, 7, 'Seht, ihre Gotteslöwen jammern auf der Straße, Gesandte, die um Frieden bitten, weinen bitterlich.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 33, 8, 'Verödet sind ja die Straßen, kein Wanderer zieht noch des Weges. Er hat den Vertrag gebrochen, die Städte geringgeschätzt, Menschen für nichts geachtet.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 33, 9, 'Trauernd liegt das Land da und stirbt ab; beschämt steht der Libanon da und verdorrt; die Saron-Aue ist der Jordan-Steppe gleich geworden, und die Basan-Ebene sowie das Karmelgebirge schütteln ihr Laub ab.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 33, 10, '»Jetzt will ich aufstehen!« spricht der HERR, »jetzt mich aufrichten, jetzt mich erheben!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 33, 11, 'Ihr geht schwanger mit Heu und werdet Stroh gebären; euer Zornesschnauben ist ein Feuer, das euch selbst verzehrt;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 33, 12, 'und die Völker sollen zu Kalk verbrannt werden (oder) wie abgehauene Dornen, die im Feuer verlodern.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 33, 13, 'Höret, ihr Fernen, was ich vollführt habe, und ihr Nahen erkennet meine Heldenkraft!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 33, 14, 'Da erschrecken in Zion die Sünder, Zittern erfaßt die Abtrünnigen. »Wer kann denn weilen bei dem verzehrenden Feuer? Wer kann denn weilen bei den ewigen Gluten?«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 33, 15, 'Wer in Gerechtigkeit wandelt und aufrichtig redet, wer den Gewinn durch Erpressungen verschmäht, wer die Annahme einer Bestechung weit von sich weist, wer seine Ohren verstopft, so daß sie nicht auf Mordpläne hören, und seine Augen verschließt, so daß sie nicht wohlgefällig nach Bösem ausschauen:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 33, 16, 'der wird seine Wohnung auf Höhen haben, Felsenburgen sind seine Zuflucht, sein Brot ist ihm ein für allemal gegeben, sein Wasser versiegt niemals.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 33, 17, 'Den König in seiner Schönheit werden deine Augen erblicken, werden ein weithin offenes Land schauen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 33, 18, 'Dein Herz wird an die frühere Schreckenszeit zurückdenken: »Wo ist nun, der (das Geld) zählte? Wo ist, der (den Zins) abwog? Wo ist, der die Türme abzählte?«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 33, 19, 'Das unverschämte Volk wirst du nicht mehr sehen, das Volk mit der dunklen, unverständlichen Sprache, das in sinnloser Rede stammelt.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 33, 20, 'Schaue Zion an, die Stadt unserer Festversammlungen! Deine Augen werden Jerusalem sehen als eine sichere Wohnstätte, als ein Zelt, das nicht zu wandern braucht, dessen Pflöcke niemals herausgezogen werden und dessen Seile alle unzerrissen bleiben.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 33, 21, 'Denn dort ist der HERR bei uns in seiner Herrlichkeit als ein Ersatz für Flüsse und breite Ströme; keine Ruderflotte fährt darauf, und kein stolzes Schiff gleitet dahin.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 33, 22, 'Denn der HERR ist unser Richter, der HERR unser Gesetzgeber, der HERR unser König: er wird uns retten.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 33, 23, 'Schlaff hängen jetzt zwar deine Taue herab, so daß sie das Gestell ihres Mastbaumes nicht aufrecht festhalten und kein Segel ausgebreitet halten. Dann aber wird Beute über Beute in Menge ausgeteilt werden, so daß selbst Lahme reichen Raub gewinnen;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 33, 24, 'und kein Einwohner wird noch sagen: »Ich leide«; dem Volk, das darin wohnt, ist Vergebung der Schuld zuteil geworden.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 34, 1, 'Kommt herbei, ihr Völkerschaften, um zu hören, und ihr Völker, merkt auf! Die Erde gebe acht und was sie füllt, der Erdkreis samt allem, was ihm entsproßt!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 34, 2, 'Denn ergrimmt ist der HERR gegen alle Völkerschaften und zornig gegen ihr gesamtes Heer; er hat sie dem Bann geweiht, hat sie zur Schlachtung bestimmt,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 34, 3, 'daß ihre Erschlagenen unbestattet hingeworfen werden und der Modergeruch von ihren Leichen aufsteigt, daß die Berge von ihrem Blut zerfließen (und alle Hügel zergehen).');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 34, 4, 'Auch das gesamte (Sternen-) Heer des Himmels wird sich auflösen und der Himmel sich zusammenrollen wie eine Schriftrolle, und sein ganzes Heer wird zerfallen, wie das Laub vom Weinstock abwelkt und wie dürre Blätter vom Feigenbaum abfallen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 34, 5, 'Wenn mein Schwert sich im Himmel berauscht hat, siehe, dann soll es auf Edom herabfahren und auf das von mir dem Untergang geweihte Volk zum Strafgericht.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 34, 6, 'Ein Schwert führt der HERR, das trieft von Blut, das ist gesättigt von Fett, vom Blut der Lämmer und Böcke, vom Nierenfett der Widder; denn ein Opferfest wird der HERR in Bozra abhalten und ein großes Schlachten im Lande Edom.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 34, 7, 'Da stürzen Wildochsen samt jenen nieder und Farren samt Maststieren; und ihr Land trinkt sich satt an Blut, und ihr Erdreich wird mit Fett gedüngt;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 34, 8, 'denn ein Tag der Rache ist für den HERRN da, ein Jahr der Vergeltung für den Streit mit Zion.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 34, 9, 'Da werden Edoms Bäche sich in Pech verwandeln und sein Staub in Schwefel, und sein Land soll zu brennendem Pech werden;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 34, 10, 'bei Tag und bei Nacht erlischt es nicht, in Ewigkeit steigt der Rauch von ihm auf, von Geschlecht zu Geschlecht bleibt es verödet liegen, in ewigen Zeiten soll niemand sein, der es durchwandert.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 34, 11, 'Vielmehr Pelikan und Igel werden es in Besitz nehmen, Eulen und Raben darin hausen; und der HERR wird darüber ausspannen die Meßschnur der Verödung und die Bleilote der Leere (aufhängen).');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 34, 12, 'Von seinen Alt-Adeligen wird keiner mehr das Königtum ausrufen, und alle seine Fürsten werden verschwunden sein.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 34, 13, 'In seinen Palästen werden Dornen aufschießen, Unkraut und Gestrüpp in seinen Burgen aufwachsen, und es wird eine Behausung für Schakale sein, ein Bezirk für Strauße;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 34, 14, 'Wüstenwölfe werden mit wilden Hunden zusammentreffen und Feldteufel einander begegnen; nur dort halten die Nachtgespenster Rast und machen sich’s dort behaglich.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 34, 15, 'Dorthin verlegt die Pfeilschlange ihr Nest und legt Eier, brütet sie aus und hegt die Brut im Schatten; nur dort versammeln sich die Geier, einer zum andern.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 34, 16, 'Forscht im Buch des HERRN nach und lest darin: kein einziger von diesen bleibt aus, keines vermißt seinen Genossen; denn der Mund des HERRN hat es geboten, und sein Wille hat sie zusammengebracht.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 34, 17, 'Er selbst hat ihnen das Los geworfen, und seine Hand hat ihnen das Land nach der Meßschnur zugeteilt: auf ewig sollen sie es inne haben, von Geschlecht zu Geschlecht darin hausen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 35, 1, 'Jauchzen sollen die Wüste und die Einöde, frohlocken soll die Steppe und aufsprossen wie ein Narzissenfeld!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 35, 2, 'Sie soll in voller Blüte stehen und frohlocken, ja mit Jubel und Frohlocken! Die Herrlichkeit des Libanons wird ihr verliehen, die Pracht des Karmelgebirges und der Saron-Ebene: sie dort sollen die Herrlichkeit des HERRN sehen, die Pracht unsers Gottes.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 35, 3, 'Stärkt die erschlafften Hände und festigt die wankenden Knie!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 35, 4, 'Sagt zu denen, die verzagten Herzens sind: »Seid getrost, fürchtet euch nicht! Seht, da ist euer Gott! Es kommt die Rache, die Vergeltung Gottes! Er selbst kommt und wird euch Heil spenden!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 35, 5, 'Alsdann werden die Augen der Blinden sich auftun und die Ohren der Tauben sich öffnen;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 35, 6, 'dann wird der Lahme springen wie ein Hirsch, und die Zunge des Stummen wird jauchzen; denn in der Wüste quellen Wasser hervor und Bäche in der Steppe;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 35, 7, 'der glühende Sand wird zum Teich und das durstige Land zu Wassersprudeln; wo zuvor Schakale wohnten und ihre Lagerstätte hatten, da wird ein Bezirk für Rohr und Schilf entstehen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 35, 8, 'Und es wird dort einen gebahnten Weg geben, die ›Heilige Straße‹ wird man ihn nennen: kein Unreiner wird auf ihr wandern, nein, sie ist für sein Volk allein bestimmt. Wer auf der Straße wandert – selbst Einfältige werden auf ihr nicht irregehen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 35, 9, 'Löwen wird es dort nicht geben, und kein reißendes Tier wird sie betreten, noch daselbst angetroffen werden; sondern nur die (aus der Gefangenschaft) Erlösten werden darauf wandern');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 35, 10, 'und die vom HERRN in Freiheit Losgekauften auf ihr heimkehren und mit Jubel nach Zion gelangen, und ewige Freude wird ihr Haupt umschweben; Wonne und Freude werden ihnen zuteil werden, aber Kummer und Seufzen müssen entfliehen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 36, 1, 'Es begab sich im vierzehnten Regierungsjahr des Königs Hiskia, daß der assyrische König Sanherib gegen alle festen Städte Judas heranzog und sie eroberte.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 36, 2, 'Da sandte der assyrische König seinen Großwesir mit einem starken Heere von Lachis aus nach Jerusalem zum König Hiskia; und der (Assyrer) stellte sich bei der Wasserleitung des oberen Teiches an der Straße nach dem Walkerfelde auf.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 36, 3, 'Als nun der Hausminister Eljakim, der Sohn Hilkias, mit dem Staatsschreiber Sebna und dem Kanzler Joah, dem Sohne Asaphs, zu ihm hinausgegangen war,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 36, 4, 'sagte der Großwesir zu ihnen: »Berichtet doch dem Hiskia: So hat der Großkönig, der König von Assyrien, gesprochen: ›Worauf beruht das feste Vertrauen, das du hegst?');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 36, 5, 'Meinst du etwa, der Verlauf und Ausgang eines Krieges hänge lediglich von Worten ab? Auf wen verläßt du dich eigentlich, daß du dich gegen mich empört hast?');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 36, 6, 'Nun ja, du verläßt dich auf Ägypten, diesen eingeknickten Rohrstab, der jedem, welcher sich darauf stützt, in die Hand fährt und sie durchbohrt: so erweist sich nämlich der Pharao, der König von Ägypten, allen denen, die sich auf ihn verlassen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 36, 7, 'Wenn du mir aber entgegnen willst: Auf den HERRN, unsern Gott, verlassen wir uns! – ist das nicht derselbe, dessen Höhendienst und Altäre Hiskia beseitigt hat, als er in Juda und Jerusalem gebot: Nur vor diesem Altar hier dürft ihr euch niederwerfen?');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 36, 8, 'Und nun, gehe doch mit meinem Herrn, dem König von Assyrien, eine Wette ein: Ich will dir zweitausend Pferde liefern: laß sehen, ob du wohl imstande bist, die Reiter dafür aufzubringen!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 36, 9, 'Wie willst du da den Kampf mit einem einzigen Befehlshaber von den geringsten Dienern meines Herrn aufnehmen? Und doch verläßt du dich auf Ägypten um der Wagen und Reiter willen!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 36, 10, 'Zudem: bin ich etwa ohne Zutun eures Gottes gegen dieses Land herangezogen, um es zu verheeren? Der HERR, euer Gott, selbst hat mich aufgefordert, gegen dieses Land zu ziehen und es zu verheeren!‹«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 36, 11, 'Hierauf sagten Eljakim, Sebna und Joah zu dem Großwesir: »Sprich doch aramäisch mit deinen Knechten, denn wir verstehen es, und sprich nicht judäisch mit uns vor den Ohren des Volkes, das auf der Mauer steht!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 36, 12, 'Aber der Großwesir erwiderte: »Hat mich mein Herr etwa nur zu deinem Herrn und zu dir gesandt, um diese Verhandlungen zu führen, und nicht auch zu den Männern, die dort auf der Mauer sitzen, um schließlich mit euch zusammen ihren eigenen Kot zu verzehren und ihren Harn zu trinken?«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 36, 13, 'Hierauf trat der Großwesir vor und rief mit gehobener Stimme auf judäisch die Worte aus: »Vernehmt die Botschaft des Großkönigs, des Königs von Assyrien!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 36, 14, 'So läßt euch der König sagen: Laßt euch von Hiskia nicht täuschen, denn er vermag euch nicht zu retten!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 36, 15, 'Auch laßt euch von Hiskia nicht auf Gott, den HERRN, vertrösten, wenn er sagt: ›Gott, der HERR, wird uns sicherlich erretten: unsere Stadt wird nicht in die Hand des Königs von Assyrien fallen!‹');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 36, 16, 'Hört nicht auf Hiskia! Denn so läßt euch der König von Assyrien sagen: ›Schließt Frieden mit mir und ergebt euch mir! Dann sollt ihr ein jeder von seinem eigenen Weinstock und seinem eigenen Feigenbaum essen und ein jeder das Wasser aus seiner eigenen Zisterne trinken,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 36, 17, 'bis ich komme und euch in ein Land hole, das gleich dem eurigen ist, ein Land voll von Getreide und Most, ein Land voll von Brot und Weinbergen!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 36, 18, 'Laßt euch nur nicht von Hiskia irreführen, wenn er sagt: Gott, der HERR, wird uns erretten! Hat etwa von den Göttern der anderen Völker irgendeiner sein Land aus der Gewalt des Königs von Assyrien gerettet?');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 36, 19, 'Wo sind die Götter von Hamath und Arpad? wo die Götter von Sepharwaim? Und noch weniger haben sie Samaria aus meiner Gewalt gerettet.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 36, 20, 'Wo ist unter allen Göttern dieser Länder ein einziger, der sein Land aus meiner Gewalt gerettet hätte, daß jetzt Gott, der HERR, Jerusalem aus meiner Gewalt erretten sollte?‹«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 36, 21, 'Da schwiegen sie still und antworteten ihm kein Wort; denn es lag ein Befehl des Königs vor, der geboten hatte: »Ihr sollt ihm nicht antworten.« –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 36, 22, 'Hierauf kehrten der Hausminister Eljakim, der Sohn Hilkias, und der Staatsschreiber Sebna und der Kanzler Joah, der Sohn Asaphs, mit zerrissenen Kleidern zu Hiskia zurück und berichteten ihm, was der Großwesir gesagt hatte.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 1, 'Als nun der König Hiskia das vernommen hatte, zerriß er seine Kleider, hüllte sich in ein grobes Trauergewand und begab sich in den Tempel des HERRN;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 2, 'seinen Hausminister Eljakim aber und den Staatsschreiber Sebna samt den vornehmsten Priestern sandte er, ebenfalls in Trauerkleider gehüllt, zu dem Propheten Jesaja, dem Sohn des Amoz.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 3, 'Diese sagten zu ihm: »So läßt Hiskia dir sagen: ›Ein Tag der Bedrängnis, der Züchtigung und Schmach ist der heutige Tag; denn Kinder sind bis zum Muttermund gekommen, aber es fehlt an Kraft zum Gebären.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 4, 'Vielleicht aber wird der HERR, dein Gott, auf die Worte des Großwesirs hören, den sein Herr, der König von Assyrien, hergesandt hat, um den lebendigen Gott zu verhöhnen, und wird ihn für die Worte strafen, die der HERR, dein Gott, gehört hat. So lege denn Fürbitte ein für den Rest, der noch vorhanden ist!‹«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 5, 'Als nun die Diener des Königs Hiskia zu Jesaja kamen,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 6, 'sagte dieser zu ihnen: »Bringt eurem Herrn folgenden Bescheid: ›So hat der HERR gesprochen: Fürchte dich nicht vor den Reden, die du gehört hast, mit denen die Buben des Königs von Assyrien mich geschmäht haben!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 7, 'Wisse wohl: ich will ihm den Entschluß eingeben, daß er, wenn er ein Gerücht vernimmt, in sein Land zurückkehrt, und ich will ihn dann in seinem eigenen Lande durch das Schwert umkommen lassen.‹«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 8, 'Als hierauf der Großwesir zurückgekehrt war, fand er den König von Assyrien mit der Belagerung von Libna beschäftigt; er hatte nämlich erfahren, daß er von Lachis abgezogen war.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 9, 'Als Sanherib sodann in betreff des äthiopischen Königs Thirhaka die Nachricht erhielt, dieser sei zum Kriege gegen ihn ausgezogen, sandte er infolge dieser Nachricht Boten an Hiskia und ließ ihm sagen:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 10, '»Folgende Botschaft sollt ihr dem König Hiskia von Juda überbringen: Laß dich nicht von deinem Gott täuschen, auf den du dein Vertrauen setzt, indem du denkst: ›Jerusalem wird nicht in die Gewalt des Königs von Assyrien fallen!‹');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 11, 'Du hast doch selbst gehört, wie die Könige von Assyrien mit allen Ländern verfahren sind, indem sie den Bann an ihnen vollstreckten, und da solltest du gerettet werden?');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 12, 'Haben etwa die Götter der Völkerschaften, welche meine Väter vernichtet haben, sie errettet: Gosan, Haran und Rezeph und die Bewohner von Eden in Thelassar?');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 13, 'Wo ist der König von Hamath und der König von Arpad und der König von Lair und Sepharwaim, von Hena und Iwwa?«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 14, 'Als nun Hiskia das Schreiben aus der Hand der Gesandten in Empfang genommen und es gelesen hatte, ging er in den Tempel des HERRN hinauf und breitete es dort vor dem HERRN aus.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 15, 'Alsdann richtete Hiskia an den HERRN folgendes Gebet:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 16, '»HERR der Heerscharen, Gott Israels, der du über den Cheruben thronst, du allein bist Gott über alle Reiche der Erde: du bist es, der Himmel und Erde geschaffen hat!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 17, 'Neige, HERR, dein Ohr und höre! Öffne deine Augen, HERR, und blicke her! Ja, höre alle die Worte, die Sanherib hier hat sagen lassen, um den lebendigen Gott zu verhöhnen!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 18, 'Es ist allerdings wahr, HERR, daß die Könige von Assyrien alle Völkerschaften [und ihr eigenes Land] verwüstet');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 19, 'und deren Götter ins Feuer geworfen haben; aber das waren auch keine Götter, sondern nur Machwerk von Menschenhänden, Holz und Stein, und darum konnten sie sie vernichten.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 20, 'Nun aber, HERR, unser Gott, rette uns aus seiner Hand, damit alle Reiche der Erde erkennen, daß du allein der HERR bist!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 21, 'Da sandte Jesaja, der Sohn des Amoz, zu Hiskia und ließ ihm sagen: »So hat der HERR, der Gott Israels, gesprochen: Was das Gebet betrifft, das du wegen Sanheribs, des Königs von Assyrien, an mich gerichtet hast,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 22, 'so hat der HERR folgenden Ausspruch über ihn getan: Es verachtet dich, es spottet deiner die jungfräuliche Tochter Zion; hinter dir her schüttelt das Haupt die Tochter Jerusalem!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 23, 'Wen hast du geschmäht und gelästert und gegen wen deine Stimme erhoben und deine Augen hochmütig emporgerichtet? Gegen den Heiligen Israels!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 24, 'Durch den Mund deiner Diener hast du den HERRN geschmäht und hast gesagt: ›Mit meiner Kriegswagen Menge ersteige ich die Höhen der Berge, den obersten Gipfel des Libanons; ich haue nieder den Hochwald seiner Zedern, die Auslese seiner Zypressen, und dringe vor bis zu seinem obersten Gipfel, in seinen dichtesten Baumgarten.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 25, 'Ich grabe den Erdboden auf und trinke Wasser und mache andrerseits mit der Sohle meiner Füße versiegen alle Nilarme Ägyptens!‹');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 26, 'Hast du es nicht gehört? Von lange her habe ich es festgesetzt und von den Tagen der Vorzeit her es vorbereitet, nunmehr aber habe ich es eintreten lassen, daß du feste Städte zu wüsten Steinhaufen verheeren solltest,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 27, 'und ihre Bewohner, deren Arm zu kurz war, sollten erschreckt dastehen und zuschanden werden, sollten wie Kraut des Feldes und grünender Rasen sein, wie Gras auf den Dächern und wie Getreide, das versengt ist, ehe es aufschießt.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 28, 'Mir ist dein Aufstehen und dein Sitzen offenbar, dein Gehen und dein Kommen kenne ich wohl, auch dein Toben gegen mich.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 29, 'Weil du nun gegen mich tobst und dein Großtun zu meinen Ohren aufgestiegen ist, will ich dir meinen Ring in die Nase legen und meinen Zaum an deine Lippen und will dich auf dem Wege zurückkehren lassen, auf dem du gekommen bist.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 30, 'Folgendes aber möge dir, Hiskia, als Wahrzeichen dienen: In diesem Jahre wird man den Brachwuchs essen und im nächsten Jahre den Wurzelwuchs; im dritten Jahre aber sollt ihr säen und ernten, sollt ihr Weinberge anlegen und ihren Ertrag genießen!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 31, 'Was dann vom Hause Juda entronnen und übriggeblieben ist, wird aufs neue nach unten hin Wurzel treiben und nach oben hin Früchte tragen;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 32, 'denn von Jerusalem wird ein Überrest ausgehen und eine Schar Entronnener vom Berge Zion; der Eifer des HERRN der Heerscharen wird dies vollführen!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 33, 'Darum hat der HERR in bezug auf den König von Assyrien so gesprochen: ›Er soll nicht in diese Stadt hineinkommen und keinen Pfeil hineinschießen; er soll mit keinem Schild gegen sie anrücken und keinen Wall gegen sie aufführen!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 34, 'Nein, auf dem Wege, auf dem er gekommen ist, soll er zurückkehren, in diese Stadt aber nicht eindringen!‹ – so lautet der Ausspruch des HERRN.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 35, '›Ja, ich will diese Stadt beschirmen, um sie zu erretten, um meiner selbst willen und um meines Knechtes David willen!‹«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 36, 'Da ging der Engel des HERRN aus und ließ im Lager der Assyrer 185000 Mann sterben; und als man am Morgen früh aufstand, fand man sie allesamt tot als Leichen vor.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 37, 'Da brach Sanherib, der König von Assyrien, auf und zog ab; er kehrte nach Hause zurück und nahm seinen Wohnsitz in Ninive.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 38, 'Als er aber dort einmal im Tempel seines Gottes Nisroch anbetete, erschlugen ihn seine Söhne Adrammelech und Sarezer mit dem Schwert; sie entflohen dann ins Land Armenien, und sein Sohn Esarhaddon folgte ihm als König in der Regierung nach.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 38, 1, 'Als Hiskia in jenen Tagen auf den Tod erkrankte, kam der Prophet Jesaja, der Sohn des Amoz, zu ihm und sagte zu ihm: »So hat der HERR gesprochen: ›Bestelle dein Haus, denn du wirst sterben und nicht wieder gesund werden!‹«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 38, 2, 'Da wandte Hiskia sein Gesicht gegen die Wand und betete zum HERRN mit den Worten:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 38, 3, '»Ach, HERR, denke doch daran, daß ich vor dir in Treue und mit ungeteiltem Herzen gewandelt bin und getan habe, was dir wohlgefällt!« Hierauf brach Hiskia in lautes Weinen aus.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 38, 4, 'Da erging das Wort des HERRN an Jesaja folgendermaßen:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 38, 5, '»Gehe hin und sage zu Hiskia: ›So hat der HERR, der Gott deines Ahnherrn David, gesprochen: Ich habe dein Gebet gehört und deine Tränen gesehen. So will ich denn zu deinen Lebenstagen noch fünfzehn Jahre hinzufügen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 38, 6, 'Dazu will ich dich und diese Stadt aus der Gewalt des Königs von Assyrien erretten und diese Stadt beschirmen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 38, 7, 'Und folgendes soll dir von seiten des HERRN als Wahrzeichen dafür dienen, daß der HERR diese Verheißung, die er gegeben hat, auch erfüllen wird:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 38, 8, 'Ich will jetzt den Schatten der Stufen, welche die Sonne auf den Stufen des Sonnenzeigers des Ahas bereits hinabgestiegen ist, um zehn Stufen wieder rückwärts gehen lassen.‹« Da kehrte die Sonne auf den Stufen des Sonnenzeigers die zehn Stufen zurück, die sie hinabgestiegen war.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 38, 9, 'Dies ist das Lied, das von Hiskia, dem judäischen Könige, aufgezeichnet ward, als er krank gewesen war und sich von seiner Krankheit erholt hatte:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 38, 10, '»Ich dachte schon: ›Im Mittag meines Lebens muß ich eingehen in die Pforten des Totenreiches, bin des Restes meiner Jahre beraubt.‹');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 38, 11, 'Ich dachte schon: ›Nicht werde ich mehr den HERRN schauen, den HERRN im Lande der Lebenden, werde keine Menschen mehr erblicken bei den Bewohnern der Totenwelt.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 38, 12, 'Meine Wohnung ist abgebrochen und wandert von mir weg wie ein Hirtenzelt; wie ein Weber habe ich mein Leben zusammengewickelt: vom Trummgarn schneidet er mich ab; ehe noch der Tag zum Abend wird, machst du es aus mit mir.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 38, 13, 'Beschwichtige ich mein Herz bis zum Morgen, so zermalmt er wie ein Löwe alle meine Gebeine; ja ehe noch der Tag zum Abend wird, machst du es aus mit mir.‹');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 38, 14, 'Wie eine Schwalbe, wie ein Kranich, so stöhnte ich, girrte wie eine Taube; schmachtend blickten meine Augen himmelwärts: ›O HERR, mir ist so bange! Nimm dich hilfreich meiner an!‹«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 38, 15, '»Was soll ich jetzt sagen, da er mir seine Verheißung gegeben und sie auch ausgeführt hat? Ruhig will ich dahinwandeln alle meine Jahre trotz der Bekümmernis meiner Seele.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 38, 16, 'O Allherr, davon lebt man, und ganz darin besteht das Leben meines Geistes: so wirst du mich denn wieder zu Kräften kommen und aufleben lassen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 38, 17, 'Wahrlich, zum Heil ist mir das bittere Leid geworden; du hast ja mein Leben von der Grube der Vernichtung ferngehalten; denn alle meine Sünden hast du hinter deinen Rücken geworfen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 38, 18, 'Denn nicht die Unterwelt preist dich, nicht der Tod verkündet dein Lob, nicht die in die Gruft Hinabgefahrenen hoffen auf deine Treue;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 38, 19, 'nein, der Lebende, der Lebende, der preist dich, wie ich es heute tue: der Vater gibt den Kindern Kunde von deiner Treue.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 38, 20, 'Der HERR ist bereit gewesen, mir zu helfen; so wollen wir denn mein Saitenspiel erklingen lassen alle Tage unseres Lebens gegenüber dem Hause des HERRN.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 38, 21, 'Hierauf ordnete Jesaja an, man solle einen Feigenkuchen (als Pflaster) nehmen und ihn fest auf das Geschwür legen, damit der Kranke genese.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 38, 22, 'Da fragte Hiskia: »Welches ist das Wahrzeichen dafür, daß ich wieder zum Tempel des HERRN werde hinaufgehen können?«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 39, 1, 'Zu jener Zeit sandte Merodach-Baladan, der Sohn Baladans, der König von Babylon, ein Schreiben und ein Geschenk an Hiskia; er hatte nämlich gehört, daß er krank gewesen und wieder gesund geworden sei.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 39, 2, 'Hiskia freute sich darüber und zeigte ihnen (den Boten) sein Schatzhaus: das Silber und das Gold, die Spezereien und das kostbare Öl, sein ganzes Zeughaus und überhaupt alles, was sich in seinen Schatzhäusern vorfand; es gab in seinem Palast und in seinem ganzen Königreiche nichts, was Hiskia ihnen nicht gezeigt hätte.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 39, 3, 'Da begab sich der Prophet Jesaja zum König Hiskia und fragte ihn: »Was haben diese Männer gewollt, und woher sind sie zu dir gekommen?« Hiskia antwortete: »Aus einem fernen Lande sind sie zu mir gekommen, aus Babylon.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 39, 4, 'Darauf fragte jener: »Was haben sie in deinem Palast zu sehen bekommen?« Hiskia erwiderte: »Alles, was in meinem Palast ist, haben sie zu sehen bekommen; es gibt in meinen Schatzhäusern nichts, was ich ihnen nicht gezeigt hätte.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 39, 5, 'Da sagte Jesaja zu Hiskia: »Vernimm das Wort des HERRN der Heerscharen:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 39, 6, '›Wisse wohl: es kommt die Zeit, da wird alles, was sich in deinem Palast vorfindet und was an Schätzen deine Väter bis zum heutigen Tage aufgehäuft haben, nach Babylon weggebracht werden: nichts wird zurückbleiben!‹ – so hat der HERR gesprochen –;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 39, 7, '›und von deinen leiblichen Söhnen, die dir geboren werden, wird man einige nehmen, damit sie im Palast des Königs von Babylon als Kämmerer dienen.‹«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 39, 8, 'Da antwortete Hiskia dem Jesaja: »Gut ist das Wort des HERRN, das du mir mitgeteilt hast!« Er dachte nämlich: »Es wird ja doch Friede und Sicherheit herrschen, solange ich lebe.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 40, 1, '»Tröstet, tröstet mein Volk!« spricht euer Gott;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 40, 2, '»redet herzlich zu (meiner Stadt) Jerusalem und ruft ihr zu, daß ihr Kriegsdienst ein Ende erreicht hat, weil ihre Schuld abgetragen ist, weil sie von der Hand des HERRN doppelte Strafe empfangen hat für alle ihre Sünden.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 40, 3, 'Horch! Ein Ruf erschallt: »In der Wüste bahnet dem HERRN einen Weg, ebnet in der Steppe eine Straße für unsern Gott!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 40, 4, 'Jede Vertiefung soll erhöht und jeder Berg und Hügel abgetragen werden; was uneben ist, soll zu glattem Weg und die Felsrücken zur Niederung werden,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 40, 5, 'damit die Herrlichkeit des HERRN sich offenbare und alles Fleisch insgesamt sie sehe; denn der Mund des HERRN hat gesprochen.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 40, 6, 'Horch! Eine Stimme erschallt: »Rufe!« Da fragte ich: »Was soll ich rufen?« »Alles Fleisch ist Gras und all seine Schönheit wie die Blume des Feldes:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 40, 7, 'das Gras verdorrt, die Blume verwelkt, wenn der Hauch des HERRN sie anweht – ja, Gras ist das Volk!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 40, 8, 'Das Gras verdorrt, die Blume verwelkt, aber das Wort unsers Gottes bleibt ewig bestehen.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 40, 9, 'Auf einen hohen Berg steige hinauf, Zion, als Freudenbotin! Erhebe deine Stimme mit aller Macht, Jerusalem, als Freudenbotin! Erhebe sie, fürchte dich nicht! Verkünde den Städten Judas: »Sehet da, euer Gott!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 40, 10, 'Sehet, Gott der HERR kommt als ein Starker, und sein Arm verleiht ihm den Sieg; sehet, sein Lohn kommt mit ihm, und sein Erwerb schreitet vor ihm her!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 40, 11, 'Wie ein Hirt wird seine Herde er weiden: die Lämmer wird er auf seinen Arm nehmen und sie im Busen seines Gewandes tragen, die Mutterschafe sanft leiten.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 40, 12, 'Wer hat mit seiner hohlen Hand die Wasser gemessen und des Himmels Maß mit der Spanne seiner Hand festgesetzt? Wer hat den Staub der Erde in den Scheffel gefaßt, wer die Berge mit der Brückenwaage gewogen und die Hügel mit der Handwaage?');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 40, 13, 'Wer hat das Maß des Geistes des HERRN festgestellt und wer als sein Ratgeber ihn unterwiesen?');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 40, 14, 'Mit wem hat er sich beraten, daß der ihm Einsicht verleihen möchte und ihn über den rechten Weg belehrte? Daß er ihm Erkenntnis beibrächte und ihm den Weg der vollen Einsicht wiese?');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 40, 15, 'Siehe, Völker sind wie ein Tropfen am Eimer und gelten ihm wie ein Stäubchen auf der Waagschale! Siehe, Meeresländer sind ihm wie ein Sandkorn, das er aufhebt,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 40, 16, 'und der Libanon reicht nicht hin zum Brennholz, und sein Getier genügt nicht zum Brandopfer (für ihn).');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 40, 17, 'Alle Völker sind wie ein Nichts vor ihm, als nicht vorhanden und als eine Null werden sie von ihm geachtet.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 40, 18, 'Mit wem wollt ihr also Gott vergleichen und was als Ebenbild ihm an die Seite stellen?');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 40, 19, 'Etwa ein Götzenbild, das ein Werkmeister gegossen und das ein Goldschmied mit Gold überzogen und Silberkettchen darangelötet hat?');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 40, 20, 'Wer für ein solches Weihgeschenk zu arm ist, wählt sich ein Stück Holz aus, das nicht morsch wird, sucht sich einen geschickten Künstler, damit er ihm ein Gottesbild anfertige, das nicht wackelt.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 40, 21, 'Wißt ihr’s denn nicht? Habt ihr nichts davon gehört? Ist es euch nicht von Anbeginn an verkündet worden? Habt ihr nicht begriffen, was die Grundfesten der Erde lehren?');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 40, 22, 'Er ist es, der da thront über dem Rund der Erde, während ihre Bewohner winzig wie Heuschrecken sind; er ist es, der den Himmel wie einen Schleier ausgespannt und ihn wie ein Zelt zum Wohnen ausgebreitet hat;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 40, 23, 'er ist es, der Fürsten in nichts verwandelt und Herrscher der Erde in Armseligkeit versetzt:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 40, 24, 'kaum sind sie gepflanzt, kaum sind sie gesät, kaum hat sich ihr Stamm in die Erde eingewurzelt, da bläst er sie an, daß sie verdorren, und ein Sturmwind rafft sie hinweg wie Spreu.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 40, 25, '»Wem wollt ihr mich also gleichstellen, daß ich ihm gleich wäre?« fragt der Heilige.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 40, 26, 'Hebt eure Augen zum Himmel empor und schauet: Wer hat diese da geschaffen? Er ist es, der ihr Heer nach der Zahl herausführt, der sie alle mit Namen ruft, vor dem wegen der Größe seiner Macht und der Stärke seiner Kraft kein einziges (Gestirn) ausbleibt.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 40, 27, 'Warum sagst du (also), Jakob, und warum behauptest du, Israel: »Verborgen ist dem HERRN mein Geschick, und mein Recht bleibt bei meinem Gott unbeachtet?«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 40, 28, 'Weißt du es denn nicht, oder hast du es nicht gehört? Ein ewiger Gott ist der HERR, der Schöpfer der Erde. Er wird nicht müde und wird nicht matt, unergründlich ist seine Einsicht.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 40, 29, 'Er verleiht dem Ermatteten Kraft und gewährt dem Ohnmächtigen Stärke in Fülle.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 40, 30, 'Mögen Jünglinge müde und matt werden und junge Männer strauchelnd zusammenbrechen –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 40, 31, 'die auf den HERRN harren, gewinnen neue Kraft, daß ihnen neue Schwingen wachsen wie den Adlern, daß sie laufen und nicht müde werden, daß sie wandern und nicht ermatten.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 41, 1, '»Höret mich schweigend an, ihr Meeresländer, und die Völker mögen neue Kraft gewinnen! Laßt sie herzutreten, alsdann mögen sie reden: vereint wollen wir in den Rechtsstreit eintreten!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 41, 2, 'Wer hat vom Sonnenaufgang her den (Mann) erweckt, dem der Sieg entgegenkommt auf Schritt und Tritt? Wer gibt Völker in seine Gewalt und läßt ihn Könige niedertreten, daß sein Schwert sie wie Staub macht und sein Bogen wie verwehte Spreu,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 41, 3, 'daß er hinter ihnen herjagt, unversehrt einherzieht, ohne den Pfad mit seinen Füßen zu berühren?');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 41, 4, 'Wer hat solches gewirkt und vollbracht? Er, der die Menschengeschlechter (ins Dasein) gerufen hat von Anbeginn an, ich, der HERR, der ich der Erste und bei den Letzten noch derselbe bin.« –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 41, 5, 'Die Meeresländer haben es gesehen und erschraken, es erbebten die Enden der Erde; sie näherten sich und kamen herbei;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 41, 6, 'ein jeder half dem andern und sagte zu seinem Genossen: »Sei stark!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 41, 7, 'Und es ermunterte der Bildgießer den Goldschmied und der mit dem Hammer glättende (Meister) den Klöpfelschläger und sagte von der Lötung: »Sie ist trefflich!« Darauf machte er es mit Nägeln fest, damit es nicht wackle.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 41, 8, '»Du aber, Israel, mein Knecht, du Jakob, den ich erwählt habe, Sprößling Abrahams, meines Freundes,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 41, 9, 'du, den ich von den Enden der Erde hergeholt und von ihren Säumen her berufen und zu dem ich gesagt habe: ›Mein Knecht bist du, ich habe dich erwählt und dich nicht verworfen‹:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 41, 10, 'Fürchte dich nicht, denn ich bin mit dir! Blicke nicht ängstlich umher, denn ich bin dein Gott! Ich stärke dich und helfe dir auch und halte dich aufrecht mit meiner heilverleihenden Rechten.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 41, 11, 'Siehe, es sollen beschämt und mit Schmach bedeckt dastehen alle, die (in Feindschaft) gegen dich entbrennen; es sollen zunichte werden und zugrunde gehen alle, die Streit mit dir anfangen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 41, 12, 'Du wirst sie suchen und nicht mehr finden, alle, die dich befehdet haben; wie nichts und gar nichts sollen alle werden, die Krieg mit dir führen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 41, 13, 'Denn ich, der HERR, dein Gott, werde deine Rechte stark machen, ich, der ich dir zurufe: ›Fürchte dich nicht: ich helfe dir!‹«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 41, 14, '»Fürchte dich nicht, du Würmlein Jakob, du winziges Israel! »Ich helfe dir« – so lautet der Ausspruch des HERRN –, »und dein Erlöser ist der Heilige Israels.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 41, 15, 'Siehe, ich mache dich zu einem scharfen Dreschschlitten, einem neuen, mit vielen Schneiden besetzten: du sollst Berge zerdreschen und zermalmen und Hügel der Spreu gleichmachen;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 41, 16, 'du sollst sie worfeln, daß der Wind sie verweht und der Sturm sie auseinander treibt; du aber sollst jubeln über den HERRN, sollst über den Heiligen Israels mit Stolz frohlocken!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 41, 17, 'Die Elenden und die Armen, die da nach Wasser suchen, und keines ist da, deren Zunge vor Durst lechzt, die will ich, der HERR, erhören: ich, der Gott Israels, werde sie nicht verlassen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 41, 18, 'Ich will Ströme auf kahlen Höhen entspringen lassen und Quellen inmitten der Talgründe; ich will die Wüste zum Wasserteich machen und dürres Land zu Wasserbrunnen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 41, 19, 'Ich will in der Wüste Zedern wachsen lassen, Akazien, Myrten und Ölbäume, will in der Steppe Zypressen pflanzen, Ulmen und Pinien allzumal,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 41, 20, 'damit sie sehen und erkennen, zu Herzen nehmen und innewerden allesamt, daß die Hand des HERRN dies vollführt und der Heilige Israels dies geschaffen hat.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 41, 21, '»Tragt eure Rechtssache vor!« spricht der HERR; »schafft eure Beweismittel herbei!« gebietet der König Jakobs.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 41, 22, '»Sie mögen sie herbeischaffen und uns das kundtun, was sich ereignen wird: Von dem Früheren berichtet uns, wie es damit gestanden hat, damit wir darauf achten und erfahren, wie es in Erfüllung gegangen ist. Oder laßt uns das Zukünftige vernehmen:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 41, 23, 'Gebt an, was späterhin eintreten wird, damit wir erkennen, daß ihr Götter seid! Ja, leistet irgend etwas Gutes oder Böses, damit wir staunen und es miteinander prüfend ansehen!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 41, 24, 'Seht, ihr seid nichts, und euer ganzes Tun ist nichtig: verabscheuenswert ist, wer euch erwählt!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 41, 25, 'Ich aber habe einen (Mann) vom Norden her erweckt – und er ist gekommen –, vom Aufgang der Sonne her, der meinen Namen anruft; und er hat Statthalter zertreten wie Lehm und wie ein Töpfer den Ton zerstampft.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 41, 26, 'Wer hat das von Anbeginn an verkündigt, damit wir es wüßten, und lange im voraus, damit wir sagen könnten: ›Er hat recht gehabt‹? Doch keiner ist dagewesen, der etwas verkündigt hätte, und keiner hat etwas angesagt, keiner hat eine Weissagung von euch zu hören bekommen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 41, 27, 'Ich bin der Erste, der zu Zion gesagt hat: ›Seht, hier sind sie!‹, und habe für Jerusalem einen Freudenboten bestellt.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 41, 28, 'Doch wenn ich hinblickte, so war da niemand, nämlich von diesen hier, und da war keiner, der Auskunft zu geben wußte, so daß ich sie hätte befragen können und sie mir Antwort gegeben hätten.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 41, 29, 'Seht, sie alle sind nichts: ihr ganzes Tun ist Nichtigkeit, leerer Wind ihre Gußbilder.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 42, 1, 'Siehe da, mein Knecht, an dem ich festhalte, mein Erwählter, an dem mein Herz Wohlgefallen hat: Ich habe meinen Geist auf ihn gelegt, damit er das Recht zu den Völkern hinaustrage.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 42, 2, 'Er wird nicht schreien noch lärmen und seine Stimme nicht auf der Straße hören lassen;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 42, 3, 'ein geknicktes Rohr wird er nicht abbrechen und einen glimmenden Docht nicht auslöschen; getreulich wird er das Recht kundtun.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 42, 4, 'Er selbst wird nicht verglimmen und nicht zusammenbrechen, bis er das Recht auf Erden fest begründet hat; die Meeresländer harren schon auf seine Weisung.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 42, 5, 'So hat Gott der HERR gesprochen, der die Himmel geschaffen und ausgespannt, der die Erde ausgebreitet hat mit allem, was auf ihr sproßt, der der Bevölkerung auf ihr den Odem gegeben hat und Lebensgeist denen, die auf ihr wandeln:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 42, 6, '»Ich, der HERR, habe dich berufen in Gerechtigkeit und dich bei der Hand gefaßt und habe dich behütet und dich zum Volksbund gemacht, zum Licht für die Völker,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 42, 7, 'um blinde Augen zu öffnen, um Gefangene aus dem Kerker hinauszuführen und aus dem Gefängnis die, welche in der Finsternis sitzen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 42, 8, 'Ich bin der HERR, das ist mein Name, und meine Ehre gebe ich keinem andern und meinen Ruhm nicht den Götzen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 42, 9, 'Die früheren Weissagungen, seht, sie sind eingetroffen, und Neues tue ich jetzt kund; ehe es noch sproßt, lasse ich’s euch hören.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 42, 10, 'Singet dem HERRN ein neues Lied, seinen Ruhm nach dem Ende der Erde hin, ihr, die ihr zum Meer hinabsteigt und seiner Fülle euch bemächtigt, ihr Meeresländer und deren Bewohner!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 42, 11, 'Lauten Gesang erhebe die Steppe mit ihren Ortschaften, die Zeltdörfer, wo Kedar wohnt; jubeln sollen die Bewohner der Felsengegenden, vom Gipfel der Berge herab sollen sie jauchzen!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 42, 12, 'Dem HERRN sollen sie Ehre zollen und seinen Ruhm in den Meeresländern verkünden!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 42, 13, 'Der HERR zieht aus wie ein Held, wie ein Kriegsmann facht er die Kampflust an; er läßt den Schlachtruf erschallen, ja gellendes Kriegsgeschrei, als Held erweist er sich an seinen Feinden:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 42, 14, '»Seit unendlich langer Zeit habe ich geschwiegen, bin stumm geblieben, habe an mich gehalten; jetzt aber will ich wie eine Gebärende aufschreien, will schnauben und schnaufen zugleich.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 42, 15, 'Berge und Hügel will ich verbrennen und all ihr Grün verwelken lassen, will Ströme zu Inseln machen und Seen trocken legen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 42, 16, 'Ich will machen, daß Blinde auf einem Wege gehen, den sie nicht kannten; auf Pfaden, die ihnen unbekannt waren, will ich sie wandern lassen, will das Dunkel vor ihnen her zu Licht machen und unwegsame Stellen zu ebener Bahn. Dies alles will ich ausführen und nicht davon abstehen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 42, 17, 'Zurückweichen müssen dann und tief beschämt sollen werden, die da auf Schnitzbilder vertrauen, alle, die zu Gußbildern sagen: ›Ihr seid unsere Götter!‹«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 42, 18, '»Ihr Tauben, höret! Und ihr Blinden, tut die Augen auf, daß ihr sehet!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 42, 19, 'Wer ist blind, wenn nicht mein Knecht, und taub wie mein Bote, den ich sende? Wer ist blind wie mein Vertrauter, und blind wie der Knecht des HERRN?');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 42, 20, 'Du hast vieles gesehen, aber es nicht beachtet, hast mit offenen Ohren nicht gehört.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 42, 21, 'Es hat dem HERRN um seiner Gerechtigkeit willen gefallen, das Gesetz groß und (ihn) herrlich zu machen;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 42, 22, 'aber trotzdem ist es ein geplündertes und ausgeraubtes Volk, allesamt gefangengesetzt in Löchern und in Gefängnissen versteckt gehalten, zur Beute geworden, ohne daß jemand sie rettete, der Plünderung preisgegeben, ohne daß jemand sagte: ›Gib wieder heraus!‹');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 42, 23, 'Wer unter euch vernimmt dies? Wer merkt darauf und beherzigt es für die Zukunft?«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 42, 24, 'Wer hat Jakob der Plünderung preisgegeben und Israel den Räubern? Ist’s nicht der HERR gewesen, gegen den wir gesündigt haben und auf dessen Wegen sie nicht haben wandeln wollen und gegen dessen Gesetz sie ungehorsam gewesen sind?');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 42, 25, 'Da hat er denn die Glut seines Zornes und die Schrecken des Krieges über ihn ausgegossen, daß sie ihn rings umloderten; doch er ist nicht zur Erkenntnis gekommen, und, obgleich sie ihn versengt haben, hat er es sich doch nicht zu Herzen genommen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 43, 1, 'Jetzt aber, so spricht der HERR, der dich geschaffen hat, Jakob, und der dich gebildet hat, Israel: »Fürchte dich nicht, denn ich habe dich erlöst; ich habe dich bei deinem Namen gerufen: du bist mein!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 43, 2, 'Sooft du durchs Wasser gehst: ich bin bei dir, und durch Ströme: sie sollen dich nicht überfluten! Sooft du durchs Feuer gehst: du sollst nicht versengt werden, und die Flamme soll dir nichts antun!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 43, 3, 'Denn ich, der HERR, bin dein Gott, ich, der Heilige Israels, bin dein Retter; ich gebe Ägypten als Lösegeld für dich hin, Äthiopien und Saba an deiner Statt.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 43, 4, 'Weil du kostbar bist in meinen Augen, wertvoll für mich, und ich dich liebgewonnen habe, darum gebe ich Länder als Lösegeld für dich hin und Völker für dein Leben.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 43, 5, 'Fürchte dich nicht, denn ich bin mit dir: vom Sonnenaufgang will ich deine Volksgenossen heimbringen und vom Sonnenniedergang dich sammeln;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 43, 6, 'ich will dem Norden gebieten: ›Gib sie heraus!‹ und dem Süden: ›Halte sie nicht zurück! Bringe meine Söhne aus der Ferne heim und meine Töchter vom Ende der Erde,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 43, 7, 'alle, die nach meinem Namen genannt sind und die ich zu meiner Ehre geschaffen, alle, die ich gebildet und hervorgebracht habe!‹«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 43, 8, '»Man lasse das Volk hinausgehen, das blind ist, wiewohl es Augen hat, und die taub sind, wiewohl sie Ohren haben!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 43, 9, 'Alle Völker haben sich schon versammelt zumal und die Völkerschaften sich zu einer Schar vereinigt; wer unter ihnen kann solches verkünden oder frühere Weissagungen uns vernehmen lassen? Sie mögen ihre Zeugen stellen, um gerechtfertigt dazustehen; und die sollen hören und sagen: ›Es ist wahr!‹');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 43, 10, 'Ihr seid meine Zeugen« – so lautet der Ausspruch des HERRN – »und seid mein Knecht, den ich erwählt habe, damit ihr zur Erkenntnis kommt und mir glaubt und einseht, daß ich es bin: vor mir ist kein Gott geschaffen worden, und nach mir wird keiner sein;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 43, 11, 'ich allein bin der HERR, und außer mir gibt es keinen Retter.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 43, 12, 'Ich habe die Verkündigungen gegeben und auch Rettung geschafft und habe es hören lassen, als noch kein fremder (Gott) bei euch war; und so seid ihr meine Zeugen« – so lautet der Ausspruch des HERRN –, »und ich nur bin Gott.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 43, 13, 'Auch fernerhin bin ich es, und es gibt keinen, der aus meiner Hand errettet. Wenn ich etwas ausführen will – wer kann es (ab)wenden?«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 43, 14, 'So hat der HERR gesprochen, euer Erlöser, der Heilige Israels: »Um euretwillen habe ich nach Babylon gesandt und will sie allesamt als Flüchtlinge hinabfahren lassen, auch die Chaldäer in den Schiffen, auf die sie so stolz sind:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 43, 15, 'ich, der HERR, bin euer Heiliger, ich, der Schöpfer Israels, euer König.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 43, 16, 'So hat der HERR gesprochen, der (einst) einen Weg durch das Meer gebahnt hat und einen Pfad durch mächtige Fluten,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 43, 17, 'der ins Feld ziehen ließ Kriegswagen und Rosse, Heerbann und Streitmacht – zusammen liegen sie da, stehen nicht wieder auf, sind erloschen, verglommen wie ein Docht –:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 43, 18, '»Denkt nicht mehr an die früheren Ereignisse zurück und beachtet das Vergangene nicht mehr!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 43, 19, 'Seht, ich vollbringe etwas Neues, schon tritt es in die Erscheinung: gewahrt ihr’s denn nicht? Auch in der Wüste lasse ich eine Straße entstehen, Ströme in der Einöde.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 43, 20, 'Die wilden Tiere werden es mir Dank wissen, die Schakale und Strauße, daß ich Wasser in der Wüste schaffe, Ströme in der Einöde, um mein Volk zu tränken, mein erwähltes;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 43, 21, 'dieses Volk, das ich mir zugerichtet habe, soll meinen Ruhm verkünden!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 43, 22, '»Und doch bin nicht ich es, den du angerufen hast, Jakob, und nicht um mich hast du dich gemüht, Israel;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 43, 23, 'nicht hast du mir deine Lämmer als Brandopfer dargebracht, noch mich mit deinen Schlachtopfern geehrt. Mit Speisopfern bin ich dir nicht zur Last gefallen und habe dir mit Weihrauchspenden nicht zu schaffen gemacht;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 43, 24, 'du hast mir kein Würzrohr für Geld gekauft und mich nicht mit dem Fett deiner Schlachtopfer gelabt; wohl aber hast du mir mit deinen Sünden zu schaffen gemacht und mit deinen Verschuldungen mir Beschwerde bereitet.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 43, 25, 'Ich, ich bin es, der deine Übertretungen tilgt um meinetwillen und der deiner Sünden nicht mehr gedenken will.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 43, 26, 'Rufe mir doch alles ins Gedächtnis zurück, laß uns miteinander rechten! Laß deinen Bericht hören, damit du gerechtfertigt dastehst!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 43, 27, 'Dein erster Vater schon hat gesündigt, und deine Vertreter sind mir untreu geworden;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 43, 28, 'da habe ich die Fürsten des Heiligtums ihrer Weihe entkleidet und Jakob dem Bann preisgegeben und Israel den Schmährenden.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 44, 1, '»Nun aber höre, Jakob, mein Knecht, und du, Israel, das ich erwählt habe!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 44, 2, 'So spricht der HERR, der dich geschaffen und dich vom Mutterleib an gebildet hat, dein Helfer: Fürchte dich nicht, mein Knecht Jakob, und du, geliebtes Israel, das ich erwählt habe!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 44, 3, 'Denn wie ich Wasser ausgieße auf das dürstende Land und Rieselfluten auf dürres Erdreich, so will ich meinen Geist auf deinen Samen ausgießen und meinen Segen auf deine Sprößlinge,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 44, 4, 'daß sie sprossen sollen wie Gras (zwischen Wassern), wie Weidenbäume an Wasserbächen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 44, 5, 'Der eine wird dann sagen: ›Ich gehöre dem HERRN an‹, ein anderer wird sich auf den Namen Jakobs berufen, und wieder ein anderer wird als seine Handmarke ›dem HERRN angehörig‹ schreiben und wird den Namen ›Israel‹ als Ehrennamen führen.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 44, 6, 'So hat der HERR gesprochen, der König Israels, und sein Erlöser, der HERR der Heerscharen: »Ich bin der Erste und ich der Letzte, und außer mir gibt es keinen Gott.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 44, 7, 'Und wer ist mir gleich? Er trete vor und rufe, tue es kund und lege es mir dar! Wer hat das Zukünftige von der Urzeit her verkündet und was noch kommen soll? Sie mögen es doch ansagen!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 44, 8, 'Erschreckt nicht und seid nicht verzagt! Habe ich es nicht schon längst dich hören lassen und es angesagt, so daß ihr meine Zeugen seid? Gibt es einen Gott außer mir? Nein, es gibt keinen Felsen sonst: ich kenne keinen.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 44, 9, 'Die Verfertiger von Götzenbildern sind allesamt nichts, und ihre allerliebsten Gebilde haben keinen Wert; ihre eigenen Zeugen sehen nichts und gewahren nichts, damit sie zuschanden werden.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 44, 10, 'Wer fertigt wohl einen Gott an und gießt ein Götterbild, das gar nichts nützen kann?');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 44, 11, 'Seht, alle seine Genossen stehen beschämt da, und die Werkmeister – die sind ja nur Menschen; mögen sie alle sich versammeln, alle hertreten: sie werden erschrecken müssen und allesamt beschämt dastehen!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 44, 12, 'Der Eisenschmied arbeitet mit seinem Werkzeug bei Kohlenglut; mit Hammerschlägen gestaltet er ein Bild und formt es mit seinem kräftigen Arm; wird er auch hungrig dabei, so geht ihm die Kraft aus; und trinkt er kein Wasser, so wird er matt.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 44, 13, 'Der Holzschnitzer spannt die Schnur aus, zeichnet das Bild mit dem Reißstift vor, führt es mit Schnitzmessern aus, zeichnet es mit dem Zirkel genau ab und führt es nach dem Vorbild eines Mannes aus zu einer schönen Menschengestalt, die in einem Hause ihren Platz bekommen soll.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 44, 14, 'Zunächst muß er Zedern fällen oder eine Fichte oder eine Eiche nehmen, oder eine Auswahl unter den Bäumen des Waldes treffen; er hatte Tannen gepflanzt, die der Regen wachsen ließ;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 44, 15, 'die dienen nun dem Menschen zur Feuerung, und er nimmt auch wirklich eine von ihnen, um sich zu erwärmen; auch heizt er damit den Ofen, um Brot zu backen. Aber auch einen Gott verfertigt er daraus und wirft sich vor ihm nieder: er verarbeitet es zu einem Götterbild und betet es an.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 44, 16, 'Die eine Hälfte davon hat er im Feuer verbrannt, über der andern Hälfte brät er Fleisch, verzehrt einen Braten und ißt sich satt; auch wärmt er sich daran und sagt: »Ei, ich bin schön warm geworden, ich spüre die Glut!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 44, 17, 'Von dem Rest aber verfertigt er sich einen Gott, sein Götzenbild, vor dem er sich niederwirft und sich verbeugt und an welches er das Gebet richtet: »Hilf mir, denn du bist mein Gott!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 44, 18, 'Sie haben keine Erkenntnis und keine Einsicht; denn verklebt sind ihre Augen, so daß sie nicht sehen, und ihre Herzen (verhärtet), so daß sie nicht zur Einsicht kommen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 44, 19, 'Daher stellt keiner eine Überlegung an, und keiner besitzt so viel Erkenntnis und Verstand, daß er dächte: »Die Hälfte davon habe ich im Feuer verbrannt, habe auch Brot auf seinen Glühkohlen gebacken, Fleisch gebraten und gegessen – und aus dem Rest sollte ich nun ein Greuelbild machen und vor einem Holzklotz niederknien?«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 44, 20, 'Wer Asche weidet, den hat ein betörter Sinn irregeführt, so daß er nicht zu geistiger Klarheit gelangt und sich nicht sagt: »Ist nicht Trug in meiner rechten Hand?«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 44, 21, '»Bedenke dies, Jakob, und du, Israel, denn du bist mein Knecht! Ich habe dich mir zum Knecht gebildet: Israel, du wirst von mir nicht vergessen werden!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 44, 22, 'Ich habe deine Übertretungen weggewischt wie eine Wolke und deine Sünden wie einen Nebel: kehre zurück zu mir, denn ich werde dich erlösen!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 44, 23, 'Jubelt, ihr Himmel, denn der HERR vollführt es! Jauchzet, ihr Tiefen der Erde! Brecht in Jubel aus, ihr Berge, du Wald mit allen Bäumen darin! Denn der HERR wird Jakob erlösen und an Israel sich verherrlichen!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 44, 24, 'So hat der HERR gesprochen, dein Erlöser, der dich von deiner Geburt an gebildet hat: »Ich bin der HERR, der alles wirkt, der ich den Himmel ausgespannt habe, ich allein, die Erde ausgebreitet – wer war bei mir? –;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 44, 25, 'der die Wunderzeichen der Schwätzer vereitelt und die Wahrsager als Narren hinstellt; der die Weisen beschämt abziehen läßt und ihr Wissen als Torheit erweist;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 44, 26, 'der das Wort seiner Knechte verwirklicht und den von seinen Boten verkündeten Ratschluß vollführt; der von Jerusalem verheißt: ›Es soll wieder bewohnt werden!‹ und von den Städten Judas: ›Sie sollen neu aufgebaut werden!‹ und ›Ich will ihre Trümmerstätten wieder aufrichten!‹;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 44, 27, 'der zur Meerestiefe spricht: ›Werde trocken!‹ und ›Ich will deine Fluten versiegen lassen‹;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 44, 28, 'der von Cyrus sagt: ›Er ist mein Hirt und soll all meinen Willen ausführen‹, indem er für Jerusalem gebietet: ›Es soll wieder aufgebaut werden!‹ und für den Tempel: ›Er werde neu gegründet!‹«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 45, 1, 'So hat der HERR zu seinem Gesalbten gesprochen, zu Cyrus, den ich bei seiner rechten Hand ergriffen habe, um Völker vor ihm niederzustrecken und den Gürtel von den Hüften der Könige zu lösen, um Türen vor ihm aufzutun und Tore, damit sie ihm nicht verschlossen bleiben:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 45, 2, '»Ich will selbst vor dir hergehen und das Unwegsame ebnen; eherne Pforten will ich sprengen und eiserne Riegel zerschlagen;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 45, 3, 'ich will dir die im Dunkel verborgenen Schätze übergeben und die wohlversteckten Kostbarkeiten, damit du erkennst, daß ich, der HERR, es bin, der dich bei deinem Namen gerufen hat, der Gott Israels.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 45, 4, 'Um meines Knechtes Jakob und um Israels, meines Erwählten, willen habe ich dich bei deinem Namen gerufen und dir Ehrennamen verliehen, ohne daß du mich kanntest.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 45, 5, 'Ich bin der HERR, und sonst ist keiner da: außer mir gibt’s keinen Gott. Ich habe dich gegürtet, ohne daß du mich kanntest,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 45, 6, 'damit man erkenne vom Aufgang der Sonne und von ihrem Niedergang her, daß es außer mir keinen Gott gibt. Ich bin der HERR, und sonst ist keiner!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 45, 7, 'Der ich das Licht bilde und die Finsternis schaffe, der ich Heil verleihe und Unglück schaffe: ich, der HERR, bin es, der dies alles wirkt!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 45, 8, '»Laßt rieseln von oben, ihr Himmel, Segen, und die Wolken mögen ihn herabströmen lassen! Die Erde tue (ihren Schoß) auf, damit Heil erblühe, und sie lasse Gerechtigkeit sprossen zugleich! Ich, der HERR, habe selbst es geschaffen.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 45, 9, '»Wehe dem, der mit seinem Bildner hadert, er, eine bloße Scherbe unter irdenen Scherben! Darf wohl der Ton zum Töpfer, der ihn formt, sagen: ›Was machst du da?‹ und ›Dein Werk hat keine Handhabe‹?');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 45, 10, 'Wehe dem, der zu einem Vater sagt: ›Warum setzest du Kinder in die Welt?‹ und zu einem Weibe: ›Warum wirst du Mutter?‹«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 45, 11, 'So hat der HERR gesprochen, der Heilige Israels und sein Bildner: »Über die kommenden Dinge befragt mich! Meine Söhne und das Werk meiner Hände laßt mir anbefohlen sein!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 45, 12, 'Ich bin es ja, der die Erde gemacht und die Menschen auf ihr geschaffen hat; ich bin es, dessen Hände den Himmel ausgespannt haben, und sein gesamtes Sternenheer habe ich bestellt.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 45, 13, 'Ich habe ihn erweckt in Gerechtigkeit und will alle seine Wege ebnen: er wird meine Stadt wieder aufbauen und meine Weggeführten freigeben weder um Lösegeld noch um Geschenke« – der HERR der Heerscharen hat es ausgesprochen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 45, 14, 'So hat der HERR gesprochen: »Der Reichtum Ägyptens und der Handelsgewinn Äthiopiens und der Sabäer, der hochgewachsenen Männer, werden auf dich überströmen und dir gehören; hinter dir her werden sie ziehen, in Ketten dahinschreiten und vor dir sich verbeugen, werden zu dir flehen: ›Nur bei dir ist Gott, und sonst gibt es keinen, überhaupt keinerlei Gottheit.‹«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 45, 15, 'Wahrlich, du bist ein sich verbergender Gott, du Gott Israels, ein Retter!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 45, 16, 'Zuschanden sollen sie alle werden und tief beschämt; allesamt sollen sie schmachbedeckt abziehen, die Götzenverfertiger!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 45, 17, 'Israel aber wird Rettung erlangen durch den HERRN, eine ewige Rettung; ihr sollt euch nicht zu schämen brauchen und nicht in Schmach geraten bis in alle Ewigkeit.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 45, 18, 'Denn so hat der HERR gesprochen, der Schöpfer des Himmels, er, der (wahre) Gott, der die Erde gebildet und gemacht hat – er hat sie hergerichtet; nicht zu einer Einöde hat er sie geschaffen, nein, um bewohnt zu werden, hat er sie gebildet –: »Ich bin der HERR und keiner sonst!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 45, 19, 'Nicht im Verborgenen habe ich geredet, nicht in einem dunklen Winkel der Erde; nicht habe ich zu den Nachkommen Jakobs gesagt: ›Vergebens sollt ihr mich suchen!‹ Nein, ich, der HERR, rede Gerechtigkeit und verkünde Aufrichtiges.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 45, 20, 'Versammelt euch und tretet herzu, nähert euch insgesamt, ihr Heidenvölker, die ihr (dem Untergang) entronnen seid! Unverständig sind die, welche ihr Götzenbild von geschnitztem Holz einhertragen und zu einem Gott beten, der nicht helfen kann.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 45, 21, 'Legt eure Sache dar und tragt sie vor! Mögen sie sich zusammen beraten! Wer hat dieses schon von alters her verlauten lassen, schon vor langer Zeit es angekündigt? Bin nicht ich es gewesen, der HERR, außer dem es keinen Gott weiter gibt? Außer mir gibt es keinen gerechten und rettenden Gott.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 45, 22, 'Wendet euch zu mir und laßt euch retten, alle ihr Enden der Erde! Denn ich bin Gott und keiner sonst!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 45, 23, 'Bei mir selbst habe ich geschworen, hervorgegangen ist aus meinem Munde Wahrheit und ein Wort, das unverbrüchlich ist: Vor mir soll jedes Knie sich beugen, mir jede Zunge schwören!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 45, 24, '›Im HERRN allein‹ – so wird man bekennen – ›habe ich volle Gerechtigkeit und Stärke‹; zu ihm werden kommen und sich dabei schämen alle, die ihm feindselig widerstrebt haben.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 45, 25, 'Im HERRN wird gerechtfertigt werden und seiner sich rühmen die gesamte Nachkommenschaft Israels.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 46, 1, 'Bel ist niedergesunken, es krümmt sich Nebo: ihre Götzenbilder werden den Saumtieren und dem Lastvieh zugewiesen, die Bilder, die ihr vordem umhertrugt, sind als Last dem müden Vieh aufgepackt!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 46, 2, 'Ja, sie krümmen sich, sind allesamt niedergesunken, haben die Last nicht in Sicherheit zu bringen vermocht; und sie selbst müssen mit in die Gefangenschaft wandern!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 46, 3, '»Höret mich an, ihr vom Hause Jakob und der gesamte Rest vom Hause Israel, die ihr vom Mutterleibe an mir aufgeladen, vom Mutterschoße an von mir getragen worden seid!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 46, 4, 'Auch bis in euer Greisenalter bleibe ich derselbe, und bis ihr grau geworden seid, will ich als Last euch tragen; ich habe es bisher getan, und ich will euch auch fernerhin tragen, ja ich will beladen bleiben und erretten.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 46, 5, 'Wem wollt ihr mich vergleichen und an die Seite stellen und wem mich ähnlich erklären, daß wir einander glichen?');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 46, 6, 'Da schütten sie Gold aus dem Beutel und wägen Silber mit der Waage ab, dingen sich einen Goldschmied, daß er einen Gott daraus mache, den sie dann verehren, ja vor dem sie sich niederwerfen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 46, 7, 'Sie heben ihn auf die Schulter, tragen ihn umher, stellen ihn dann an seinen Platz: da bleibt er stehen, ohne sich von seiner Stelle zu rühren; ruft man ihm auch zu, so antwortet er doch nicht, kann keinen aus seiner Not retten.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 46, 8, '»Bedenkt das wohl und zeigt euch festen Sinnes, nehmt es zu Herzen, ihr Abtrünnigen!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 46, 9, 'Denkt an die früheren Geschehnisse zurück von der Urzeit her, daß ich Gott bin und sonst keiner, eine Gottheit, der nichts vergleichbar ist!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 46, 10, 'Ich habe von Anfang an den Ausgang kundgetan und seit der Vorzeit das, was noch ungeschehen war; ich gebiete: ›Mein Ratschluß soll zustande kommen!‹, und alles, was mir beliebt, führe ich aus;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 46, 11, 'ich rufe von Osten her den Stoßvogel herbei, aus fernem Lande den Mann meiner Wahl; wie ich es ausgesprochen habe, so lasse ich es auch eintreten; wie ich es mir vorgenommen habe, so führe ich es auch aus.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 46, 12, 'Hört auf mich, ihr Starrsinnigen, die ihr fern seid von Gerechtigkeit!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 46, 13, 'Ich habe meinen Gerechtigkeitserweis nahe gebracht: er ist nicht mehr fern, und meine Rettung läßt nicht auf sich warten; nein, in Zion will ich Rettung erscheinen lassen und für Israel meine Herrlichkeit.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 47, 1, 'Herunter mit dir (vom Thron) und setze dich in den Staub, du jungfräuliche Tochter Babel! Setze dich auf den Erdboden ohne Thron nieder, du Tochter der Chaldäer! Denn in Zukunft wird man dich nicht mehr die Zarte und Feine nennen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 47, 2, 'Nimm eine Mühle und mahle Mehl, schlage deinen Schleier zurück, hebe die Schleppe hoch, entblöße die Beine, wate durch strömendes Wasser,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 47, 3, 'damit deine Blöße aufgedeckt wird und man auch deine Scham zu sehen bekommt! »Rache will ich nehmen und schonungslos gegen alle vorgehen!« spricht unser Erlöser:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 47, 4, 'HERR der Heerscharen ist sein Name, der Heilige Israels.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 47, 5, 'Setze dich schweigend nieder und tritt in die Dunkelheit ein, Tochter der Chaldäer! Denn in Zukunft wird man dich nicht mehr Herrin der Königreiche nennen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 47, 6, 'Als ich meinem Volke schwer zürnte, mein Eigentumsvolk in Unehre fallen ließ und es in deine Gewalt gab, da hast du ihnen kein Erbarmen erwiesen, nein, dein Joch überschwer sogar auf Greisen lasten lassen');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 47, 7, 'und hast gesagt: »Ewig werde ich fortbestehen, eine Gebieterin für immer!«, so daß du dir dies nicht zu Herzen genommen und an das Ende davon nicht gedacht hast.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 47, 8, 'Nun aber höre dieses, du an Üppigkeit Gewöhnte, die du in Sorglosigkeit wohnst, die da in ihrem Herzen sagt: »Meinesgleichen gibt es sonst nicht! Ich werde nicht als Witwe dasitzen und Kinderlosigkeit nicht kennen lernen.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 47, 9, 'Und doch wird dieses beides über dich kommen plötzlich, an einem Tage, Kinderlosigkeit und Witwenschaft; nach ihrem vollsten Maß werden sie über dich hereinbrechen trotz der Menge deiner Zauberkünste, trotz der gewaltigen Zahl deiner Bannsprüche.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 47, 10, 'Und du hast dich in deiner Bosheit sicher gefühlt, hast gedacht: »Niemand sieht mich.« Deine Weisheit und Wissenschaft, die hat dich irregeführt, so daß du bei dir dachtest: »Meinesgleichen gibt es sonst keine!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 47, 11, 'Und doch wird Unglück über dich hereinbrechen, das du nicht wegzuzaubern verstehen wirst, und Verderben wird dich überfallen, das du nicht zu beschwören vermagst, und unversehens wird Vernichtung über dich kommen, von der du nichts ahnst.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 47, 12, 'Versuche es nur mit deinen Bannsprüchen und mit deinen vielen Zauberkünsten, mit denen du dich von Jugend auf abgemüht hast: vielleicht vermagst du dir damit Hilfe zu schaffen, vielleicht jagst du (mir) Schrecken ein.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 47, 13, 'Du hast es dir sauer werden lassen mit deinen vielen Ratgebern: laß sie doch hertreten, daß sie dich retten, die Himmelsvermesser, die Sterngucker, die nach den einzelnen Neumonden feststellen werden, was dich treffen wird!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 47, 14, 'Fürwahr, sie werden der Spreu gleichen, die das Feuer verzehrt hat: sie werden nicht einmal ihr eigenes Leben aus der Gewalt der Flammen retten – es wird ja keine Kohlenglut sein, an der man sich wärmen kann, kein Herdfeuer, vor dem man sitzen kann.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 47, 15, 'So wird es dir mit denen ergehen, um die du dich gemüht hast, mit deinen Geschäftsfreunden seit deiner Jugend: sie werden auseinanderstieben, ein jeder nach seiner Richtung hin; keiner wird dir zu Hilfe kommen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 48, 1, 'Höret dies, ihr vom Hause Jakob, die ihr nach Israels Namen benannt und aus Judas Leibe hervorgegangen seid, die ihr schwört beim Namen des HERRN und euch zum Gott Israels bekennt – doch nicht in Wahrhaftigkeit und nicht in Gerechtigkeit –;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 48, 2, 'denn nach der heiligen Stadt haben sie sich den Namen beigelegt, und auf den Gott Israels stützen sie sich, dessen Name ›HERR der Heerscharen‹ ist:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 48, 3, '»Die früheren Weissagungen habe ich vordem verkündet, aus meinem Munde sind sie hervorgegangen, und ich habe sie kundgetan; plötzlich habe ich sie vollführt, so daß sie eingetroffen sind.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 48, 4, 'Weil ich wußte, daß du hart bist und daß dein Nacken eine Eisenspange und deine Stirn von Erz ist,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 48, 5, 'so habe ich es vordem dir kundgetan und es dich hören lassen, bevor es eintraf, damit du nicht sagen könntest: ›Mein Gottesbild hat sie vollbracht, und mein Schnitzbild sowie mein Gußbild hat sie geboten.‹');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 48, 6, 'Du hast es gehört: betrachte es nun alles! Und ihr – wollt ihr es nicht bezeugen? Von nun an aber lasse ich dich Neues hören, und zwar Geheimgehaltenes, wovon du nichts gewußt hast.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 48, 7, 'Jetzt erst kommt es zur Ausführung und nicht schon vordem, und vor dem heutigen Tage hast du nichts davon gehört, damit du nicht sagen könntest: ›Ich habe es ja schon gewußt!‹');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 48, 8, 'Nein, du hast es weder gehört noch gewußt, noch ist dein Ohr vordem dafür geöffnet gewesen; denn ich weiß, daß du gar treulos bist und daß man dich ›abtrünnig vom Mutterleibe an‹ genannt hat.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 48, 9, 'Um meines Namens willen halte ich meinen Zorn zurück, und um meiner Ehre willen übe ich Schonung dir zugute, daß ich dich nicht ausrotte.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 48, 10, 'Wisse wohl: ich habe dich (allerdings) geläutert, aber dich nicht als Silber erfunden; ich habe dich geprüft im Glutofen des Leides.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 48, 11, 'Um meinetwillen, um meinetwillen vollführe ich es – denn wie dürfte mein Name entweiht werden! –, und meine Ehre gebe ich keinem andern!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 48, 12, '»Höre auf mich, Jakob, und du, Israel, den ich berufen habe! Ich bin derselbe, ich der Erste und ich auch der Letzte.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 48, 13, 'Hat doch meine Hand die Erde gegründet und meine Rechte den Himmel ausgespannt: rufe ich ihnen zu, so stehen sie allesamt da.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 48, 14, 'Versammelt euch alle und hört! Wer unter ihnen hat dieses vorausgesagt: ›Er, den der HERR liebt, wird seinen Willen an Babylon vollstrecken und seinen Arm an den Chaldäern wirken lassen‹?');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 48, 15, 'Ich, ich habe es angekündigt, habe ihn auch berufen; ich habe ihn auftreten lassen, und er wird sein Unternehmen siegreich durchführen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 48, 16, 'Tretet heran zu mir, vernehmt dieses! Ich habe von Anfang an nicht im Verborgenen geredet; nein, seit der Zeit, wo es vor sich geht, bin ich dabei gewesen.« Jetzt aber hat Gott der HERR mich gesandt und seinen Geist.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 48, 17, 'So hat der HERR gesprochen, dein Erlöser, der Heilige Israels: »Ich, der HERR, dein Gott, bin es, der dich lehrt zu tun, was dir zum Heil dient, der dich auf dem Wege leitet, den du gehen sollst.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 48, 18, 'Ach, daß du auf meine Gebote geachtet hättest! Dann wäre deine Wohlfahrt geworden wie ein Strom und deine Gerechtigkeit wie die Wellen des Meeres;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 48, 19, 'dann würde deine Volksmenge dem Sande gleichen und deines Leibes Sprößlinge den Sandkörnern, und ihr Name würde nicht ausgerottet und nicht vertilgt werden vor meinem Angesicht hinweg.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 48, 20, 'Ziehet aus von Babylon hinweg, entflieht aus dem Chaldäerlande! Mit Jubelschall verkündet dies und laßt es laut werden! Laßt die Kunde dringen bis ans Ende der Erde! rufet aus: »Erlöst hat der HERR seinen Knecht Jakob!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 48, 21, 'Sie haben nicht Durst gelitten, als er sie durch Wüsten führte: Wasser aus dem Felsen ließ er ihnen rieseln und spaltete den Felsen, daß Wasser hervorsprudelte.« –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 48, 22, '»Keinen Frieden« – sagt der HERR – »gibt es für die Gottlosen!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 49, 1, 'Höret auf mich, ihr Meeresländer, und merkt auf, ihr Völker in der Ferne! Der HERR hat mich von Geburt an berufen, von meiner Mutter Schoß an meinen Namen in Erinnerung gebracht.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 49, 2, 'Und er hat meinen Mund einem scharfen Schwerte gleich gemacht, im Schatten seiner Hand mich geborgen und mich zu einem auserlesenen Pfeil gemacht, in seinem Köcher mich sicher verwahrt');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 49, 3, 'und zu mir gesagt: »Mein Knecht bist du, Israel, an dem ich mich verherrlichen will.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 49, 4, 'Ich aber sagte: »Umsonst habe ich mich gemüht, vergebens und erfolglos meine Kraft verbraucht; doch mein Recht steht bei dem HERRN und mein Lohn bei meinem Gott.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 49, 5, 'Nun aber hat der HERR gesagt, der mich von meiner Geburt an zu seinem Knecht gebildet hat, damit ich Jakob zu ihm zurückführe und damit Israel zu ihm gesammelt werde – denn ich bin geehrt in den Augen des HERRN, und mein Gott ist meine Stärke geworden –,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 49, 6, 'ja er hat gesagt: »Es genügt mir nicht, daß du mein Knecht sein sollst, nur damit ich die Stämme Jakobs wiederherstelle und die geretteten Angehörigen Israels zurückführe; nein, ich bestimme dich (auch) zum Licht der Heidenvölker, damit mein Heil bis ans Ende der Erde reiche.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 49, 7, 'So hat der HERR, der Erlöser Israels, sein Heiliger, zu dem gesprochen, den jedermann tief verachtet, den die Heidenwelt verabscheut, zu dem Knecht der Zwingherren: »Könige werden es sehen und (vor ihm) aufstehen, Fürsten (werden es sehen) und sich niederwerfen um des HERRN willen, weil er treu ist, um des Heiligen Israels willen, weil er dich erwählt hat.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 49, 8, 'Weiter hat der HERR so gesprochen: »In der Zeit des Wohlgefallens habe ich dich erhört und am Tage des Heils dir geholfen und habe dich behütet und dich zum Volksbund gemacht, um das Land wieder aufzurichten, um die verwüsteten Erblande wieder als Erbe auszuteilen,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 49, 9, 'um den Gefangenen zuzurufen: ›Tretet heraus!‹ und zu den in Finsternis Sitzenden: ›Kommt ans Licht!‹ Gleich an den Wegen sollen sie weiden und auf allen kahlen Höhen Weideplätze für sich finden;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 49, 10, 'sie sollen nicht hungern und nicht dürsten, und weder der Glutwind noch der Sonnenbrand soll sie treffen, denn ihr Erbarmer wird sie führen und sie an Wasserquellen ruhen lassen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 49, 11, 'Und alle meine Berge will ich zu Wegen machen, und meine Straßen sollen hoch gebaut sein.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 49, 12, 'Sehet, die einen werden aus weiter Ferne kommen, und jene dort von Norden und vom Westmeer her und wieder andere aus dem Lande der Siniter.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 49, 13, 'Jubelt, ihr Himmel, und jauchze, du Erde, und ihr Berge, brecht in Jubel aus! Denn der HERR hat sein Volk getröstet und seiner Gebeugten sich erbarmt.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 49, 14, 'Und trotzdem hat Zion geklagt: »Der HERR hat mich verlassen, und der Allherr hat meiner vergessen!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 49, 15, 'Wird wohl ein Weib ihres Kindleins vergessen, so daß sie sich nicht erbarmt über das Kind ihres Mutterleibes? Und sollten selbst Mütter seiner vergessen, so will ich doch deiner nicht vergessen;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 49, 16, 'siehe, auf meine beiden Handflächen habe ich dich gezeichnet: deine (neuzuerbauenden) Mauern stehen mir allezeit vor Augen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 49, 17, 'Deine Erbauer eilen schon herbei, deine Zerstörer und Verwüster aber ziehen weg aus dir.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 49, 18, 'Erhebe deine Augen und blicke rings um dich: sie haben sich alle schon versammelt und kommen zu dir! »So wahr ich lebe« – so lautet der Ausspruch des HERRN –, »wie einen Schmuck wirst du sie alle dir anlegen und sie dir wie eine Braut als Gürtel umbinden.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 49, 19, 'Denn deine Trümmerstätten und Einöden und dein verwüstetes Land – fortan wird es zu eng sein für die Bewohner, und die dich jetzt verheeren, werden fern sein.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 49, 20, 'Du wirst noch mit eigenen Ohren die aus der Zeit deiner Vereinsamung dir gebliebenen Söhne sagen hören: ›Der Raum ist mir zu eng: schaffe mir Platz, daß ich wohnen kann!‹');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 49, 21, 'Da wirst du denn dir selbst die Frage vorlegen: ›Wer hat diese da für mich erzeugt, während ich kinderlos und unfruchtbar war, in der Verbannung lebend und verstoßen? Und wer hat mir diese da großgezogen? Ich war ja doch allein übriggeblieben; diese also – wo waren sie?‹«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 49, 22, 'So hat Gott der HERR gesprochen: »Fürwahr, ich will mit der Hand den Heiden winken und mein Panier den Völkern sichtbar aufpflanzen; dann werden sie deine Söhne im Gewandbausch herbeitragen, und deine Töchter wird man auf den Schultern herbringen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 49, 23, 'Und Könige werden deine Kinderwärter sein und ihre fürstlichen Gemahlinnen deine Ammen; das Antlitz zur Erde gewandt, werden sie sich vor dir niederwerfen und den Staub an deinen Füßen lecken; und du sollst erkennen, daß ich, der HERR, es bin, an dem die, welche auf ihn harren, nicht enttäuscht werden.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 49, 24, 'Kann wohl einem Starken die Beute abgenommen werden, oder können die Gefangenen eines Mächtigen entrinnen?');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 49, 25, '»Ja«; so hat der HERR gesprochen: »Auch die Gefangenen eines Helden können ihm abgenommen werden, und die Beute eines Mächtigen kann entrinnen, und ich selbst will mit deinen Widersachern streiten, und deine Söhne will ich selbst retten;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 49, 26, 'deine Peiniger will ich ihr eigenes Fleisch verzehren lassen, und wie an Most sollen sie sich an ihrem eigenen Blute berauschen; dann wird alles Fleisch erkennen, daß ich, der HERR, dein Retter bin und ich dein Erlöser, der starke Gott Jakobs.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 50, 1, 'So hat der HERR gesprochen: »Wo ist denn der Scheidebrief eurer Mutter, durch den ich sie verstoßen hätte? Oder wo ist einer unter meinen Gläubigern, an den ich euch verkauft hätte? Nein, um eurer Verschuldungen willen seid ihr verkauft worden, und wegen eurer Übertretungen ist eure Mutter entlassen worden!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 50, 2, 'Warum war also kein Mensch da, wenn ich kam? Warum gab mir niemand Antwort, wenn ich rief? Ist mein Arm wirklich zu kurz, um zu erlösen? Oder besitze ich nicht Kraft genug, um zu erretten? Ich lege ja doch das Meer durch mein Schelten trocken und mache Ströme zur Wüste, so daß ihre Fischbrut vor Wassermangel verfault und (ihr Getier) vor Durst stirbt.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 50, 3, 'Ich kleide den Himmel in Schwarz und mache Sackleinen zur Hülle für ihn.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 50, 4, 'Gott der HERR hat mir die Zunge von Jüngern verliehen, damit ich den Müden durch Zuspruch aufzurichten wisse; er weckt mich alle Morgen, regt mir das Ohr an, damit ich aufmerke nach Jüngerweise.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 50, 5, 'Gott der HERR hat mir das Ohr geöffnet, und ich habe mich nicht gesträubt, bin nicht zurückgewichen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 50, 6, 'Meinen Rücken habe ich denen hingehalten, die mich schlugen; und meine Wangen denen, die mir den Bart rauften; mein Angesicht habe ich vor Beschimpfungen und Speichelwurf nicht verhüllt.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 50, 7, 'Doch Gott der HERR hilft mir: darum habe ich mich auch nicht entehrt gefühlt, darum hab ich mein Antlitz hart wie Kieselstein gemacht; ich wußte ja, daß ich nicht beschämt werden würde.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 50, 8, 'Ja, nahe ist er mir, der mich gerecht spricht: wer will mit mir rechten? Wir wollen zusammen hintreten! Wer will mir mein Recht streitig machen? Er trete zu mir heran!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 50, 9, 'Seht, Gott der HERR hilft mir: wer will mich für schuldig erklären? Fürwahr, sie werden allesamt zerfallen wie ein Kleid: die Motten werden sie fressen!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 50, 10, 'Wer unter euch fürchtet den HERRN? Er höre die Stimme seines Knechtes, der in tiefster Finsternis gewandelt ist und, während kein Lichtstrahl ihm glänzte, doch sein Vertrauen auf den Namen des HERRN gesetzt und sich auf seinen Gott gestützt hat.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 50, 11, 'Fürwahr, ihr alle seid Leute, die Feuer anfachen und Brandpfeile in Flammen setzen. Fahrt hin in die Flammenglut eures eigenen Feuers und in die Brandpfeile, die ihr in Flammen gesetzt habt! Von meiner Hand wird euch dies widerfahren, daß ihr zur Peinigung daliegen sollt.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 51, 1, 'Höret auf mich, die ihr der Gerechtigkeit nachjagt, ihr, die ihr den HERRN sucht! Blickt hin auf den Felsen, aus dem ihr gehauen, und auf die Brunnenhöhlung, aus der ihr ausgegraben seid!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 51, 2, 'Blickt hin auf Abraham, euren Vater, und auf Sara, die unter Schmerzen euch geboren hat! denn er war nur ein einzelner, als ich ihn berief, aber ich habe ihn gesegnet und zahlreich gemacht.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 51, 3, 'Denn Trost hat der HERR für Zion, Trost für alle seine Trümmerstätten und wird seine Wüstenei zu einem Paradies machen und seine Steppe zu einem Gottesgarten: Jubel und Freude wird sich in ihm einfinden, Danklied und Saitenspiel.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 51, 4, 'Horcht auf mich, du mein Volk, und schenkt mir Gehör, ihr meine Volksgemeinde! denn Belehrung wird von mir ausgehen, und mein Recht will ich zur Erleuchtung der Völker feststellen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 51, 5, 'Meine Gerechtigkeit ist nahe, mein Heil im Anzug, und meine Arme werden die Völker richten; auf mich geht das Hoffen der Meeresländer und auf meinen Arm ihr Harren.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 51, 6, 'Hebt eure Augen zum Himmel empor und blickt zur Erde unten! Denn der Himmel wird wie Rauch zergehen und die Erde wie ein Kleid zerfallen, und ihre Bewohner werden wie Mücken hinsterben; aber mein Heil wird ewig bestehen und meine Gerechtigkeit nicht hinfällig werden.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 51, 7, 'Höret auf mich, die ihr die Gerechtigkeit kennt und liebt, du Volk, in dessen Herzen mein Gesetz wohnt! Fürchtet euch nicht vor dem Hohn von Menschen und erschreckt nicht vor ihren Schmähreden!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 51, 8, 'Denn wie ein Kleid wird die Motte sie zerfressen und wie Wolle wird die Schabe sie verzehren; aber meine Gerechtigkeit wird ewig bestehen und mein Heil von Geschlecht zu Geschlecht.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 51, 9, 'Werde wach, werde wach, waffne dich mit Kraft, du Arm des HERRN! Werde wach wie in den Tagen der Vorzeit, in den längst vergangenen Zeitläufen! Bist du es nicht gewesen, der Rahab zerhauen, das Seeungeheuer durchbohrt hat?');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 51, 10, 'Bist du es nicht gewesen, der das Meer, die Gewässer der großen Urflut, trockengelegt und Meerestiefen wegsam gemacht hat, damit die Erlösten hindurchzögen?');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 51, 11, 'So werden denn die vom HERRN Erlösten heimkehren und mit Jubel nach Zion gelangen, und ewige Freude wird ihr Haupt umschweben: Frohlocken und Freude werden ihnen zuteil werden, Kummer und Seufzen entflohen sein.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 51, 12, 'Ich, ich bin es, der euch tröstet! Wer bist du gewesen, daß du dich vor Menschen gefürchtet hast, die doch sterblich sind, und vor Menschenkindern, die wie Gras vergehen,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 51, 13, 'und daß du den HERRN vergaßest, deinen Schöpfer, der den Himmel ausgespannt und die Erde gegründet hat? Und daß du immerfort, tagaus tagein, vor der Wut des Bedrängers bebtest, sooft er darauf ausging, dich zu verderben? Wo ist denn nun die Wut des Bedrängers?');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 51, 14, 'Gar bald wird der Geknebelte entfesselt werden und wird nicht sterben, um zur Unterwelt hinabzufahren, wird auch an dem erforderlichen Brot keinen Mangel mehr haben,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 51, 15, 'so wahr ich der HERR, dein Gott, es bin, der das Meer aufwühlt, daß seine Wogen brausen: HERR der Heerscharen ist sein Name –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 51, 16, 'und ich habe meine Worte dir in den Mund gelegt und dich im Schatten meiner Hand geborgen –, um den Himmel zu schaffen und die Erde zu gründen und zu Zion zu sagen: »Mein Volk bist du!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 51, 17, 'Erwache, erwache, stehe auf, Jerusalem, (du Stadt) die aus der Hand des HERRN den Becher seines Zornes getrunken, den Kelch des Taumeltranks bis zur Neige geleert hat!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 51, 18, 'Es war für sie von allen Söhnen, die sie geboren hatte, keiner da, der sie zum Ruheplatz führte, und keiner, der sie bei der Hand faßte von allen Söhnen, die sie großgezogen hatte.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 51, 19, 'Ein zwiefacher Schicksalsschlag ist es, der dich getroffen hat – wer bezeigt dir Beileid? –: Vergewaltigung und Verheerung, Hungersnot und das Schwert; wie könnte ich dich trösten?');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 51, 20, 'Deine Söhne haben ohnmächtig dagelegen, hingesunken an allen Straßenecken, wie eine ins Netz geratene Antilope, voll getroffen vom Zorn des HERRN, vom Schelten deines Gottes.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 51, 21, 'Darum höre doch dieses, du Unglückliche, die du trunken bist, doch nicht vom Wein!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 51, 22, 'So hat der HERR gesprochen, der Höchste und dein Gott, der seines Volkes Sache führt: »Siehe, ich nehme dir den Taumelbecher, den Kelch meines Grimmes, aus der Hand: du sollst nicht länger aus ihm trinken,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 51, 23, 'sondern ich gebe ihn deinen Peinigern in die Hand, die dir höhnisch zugerufen haben: ›Bücke dich, daß wir über dich hinschreiten!‹« Da mußtest du deinen Rücken dem Erdboden gleich machen und wie zu einer Straße für die darüber Hinschreitenden.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 52, 1, 'Werde wach, werde wach, kleide dich in deine Kraft, Zion! Lege deine Prachtgewänder an, Jerusalem, du heilige Stadt! Denn hinfort wird kein Unbeschnittener und kein Unreiner in dich eintreten!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 52, 2, 'Schüttle den Staub von dir ab, stehe auf, du Gefangenenschar Jerusalems! Entledige dich deiner Halsfesseln, du Gefangenenschar Tochter Zion!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 52, 3, 'Denn so hat der HERR gesprochen: »Ohne Entgelt seid ihr verkauft worden; so sollt ihr auch ohne Geld losgekauft werden!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 52, 4, 'Denn so hat Gott der HERR gesprochen: »Nach Ägypten ist mein Volk im Anfang hinabgezogen, um dort in der Fremde zu weilen; dann haben die Assyrer es ohne Grund vergewaltigt.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 52, 5, 'Nun aber, was geschieht mir denn hier« – so lautet der Ausspruch des HERRN –, »daß mein Volk mir ohne Entgelt weggenommen worden ist, daß seine Zwingherren laut jauchzen« – so lautet der Ausspruch des HERRN – »und mein Name immerfort, tagaus tagein, gelästert wird?');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 52, 6, 'Darum soll mein Volk meinen Namen kennenlernen, ja, darum an jenem Tage erkennen, daß ich es bin, der da spricht: ›Hier bin ich!‹«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 52, 7, 'Wie lieblich sind auf den Bergen die Füße des Freudenboten, der Glück verkündet, der Gutes als frohe Botschaft verkündet und Heil zu melden hat, der zu Zion sagt: »Dein Gott hat sein Königtum angetreten!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 52, 8, 'Horch! Deine Wächter lassen schon ihren Ruf erschallen und jubeln allesamt; denn Auge in Auge sehen sie voll Freude, wie der HERR nach Zion zurückkehrt.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 52, 9, 'Brecht in lauten Jubel aus insgesamt, ihr Trümmer (-stätten) Jerusalems! Denn der HERR tröstet sein Volk, hat Jerusalem erlöst!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 52, 10, 'Der HERR hat seinen heiligen Arm vor den Augen aller Völker entblößt, und alle Enden der Erde werden das von unserm Gott ausgehende Heil sehen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 52, 11, 'Brecht auf, brecht auf, zieht aus von dort, rührt nichts Unreines an! Zieht weg aus ihrer Mitte! Reinigt euch, die ihr die Geräte des HERRN tragt!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 52, 12, 'Denn nicht in ängstlicher Hast braucht ihr auszuziehen und nicht in eiliger Flucht zu wandern; denn der HERR zieht vor euch her, und die Nachhut eures Zuges bildet der Gott Israels.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 52, 13, 'Wisset wohl: mein Knecht wird Erfolg haben; er wird emporsteigen und erhöht werden und hocherhaben dastehen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 52, 14, 'Wie sich viele über dich entsetzt haben – so entstellt, nicht mehr einem Manne ähnlich war sein Aussehen und seine Gestalt nicht mehr wie die der Menschenkinder –,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 52, 15, 'ebenso wird er viele Völker in Erstaunen versetzen, und Könige werden über ihn den Mund verschließen; denn was ihnen nie erzählt worden war, das sehen sie (nun), und wovon sie nie etwas gehört hatten, das nehmen sie (nun) wahr.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 53, 1, 'Wer hat unserer Verkündigung Glauben geschenkt, und wem ist der Arm des HERRN offenbar geworden?');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 53, 2, 'Er wuchs ja vor ihm auf wie ein Schößling und wie ein Wurzelsproß aus dürrem Erdreich; er hatte keine Gestalt und keine Schönheit, daß wir ihn hätten ansehen mögen, und kein Aussehen, daß wir Gefallen an ihm gehabt hätten;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 53, 3, 'nein, er war verachtet und gemieden von den Männern, ein Mann der Schmerzen und mit Krankheit vertraut, ja wie einer, vor dem man das Angesicht verhüllt, verachtet, so daß wir ihn für nichts ansahen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 53, 4, 'Jedoch unsere Krankheiten waren es, die er getragen hat, und unsere Schmerzen hatte er sich aufgeladen, während wir ihn für einen Gestraften, von Gott Geschlagenen und Gemarterten hielten.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 53, 5, 'Und doch war er verwundet um unserer Übertretungen willen und zerschlagen infolge unserer Verschuldungen: die Strafe war auf ihn gelegt zu unserm Frieden, und durch seine Striemen ist uns Heilung zuteil geworden.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 53, 6, 'Wir gingen alle in der Irre wie Schafe, ein jeder wandte sich seinem eigenen Wege zu; der HERR aber hat unser aller Schuld auf ihn fallen lassen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 53, 7, 'Als er mißhandelt wurde, ergab er sich willig darein und tat seinen Mund nicht auf wie ein Lamm, das zur Schlachtung geführt wird, und wie ein Mutterschaf, das vor seinen Scherern stumm bleibt; er tat seinen Mund nicht auf.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 53, 8, 'Aus der Drangsal und dem Gericht ist er hinweggenommen worden, doch wer unter seinen Zeitgenossen bedachte es, daß er vom Lande der Lebenden abgeschnitten war? Wegen der Verschuldung meines Volkes hat die Strafe ihn getroffen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 53, 9, 'Und man wies ihm sein Grab bei Frevlern an und bei Missetätern seine Gruft, wiewohl er keine Gewalttat verübt hatte und kein Betrug in seinem Munde gewesen war.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 53, 10, 'Doch dem HERRN hatte es gefallen, ihn mit Krankheit zu zerschlagen; wenn er sein Leben als Sühne einsetzen wird, soll er Samen sehen und lange Tage leben und der Wille des HERRN durch ihn gedeihen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 53, 11, 'Infolge seiner Seelenqual wird er (Frucht erwachsen) sehen und satt werden; durch seine Erkenntnis wird als Gerechter mein Knecht den Vielen zur Gerechtigkeit verhelfen, indem er ihre Verschuldungen auf sich lädt.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 53, 12, 'Darum will ich ihm die Vielen zuteilen, und mit Starken soll er Beute teilen zum Lohn dafür, daß er sein Leben in den Tod hingegeben hat und unter die Übeltäter gezählt worden ist, während er doch die Sünde der Vielen getragen hat und für die Übeltäter fürbittend eingetreten ist.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 54, 1, 'Juble, du Kinderlose, die nicht Mutter geworden ist; brich in Jubel aus und jauchze, die du keine Geburtsschmerzen hast kennengelernt! Denn »die Kinder der Einsamen werden zahlreicher sein als die Kinder der Verehelichten«, ist der Ausspruch des HERRN.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 54, 2, 'Erweitere den Raum deines Zeltes, und man spanne die Decken deiner Wohnräume weit auseinander, ohne zu sparen! Mache deine Zeltseile lang und schlage deine Zeltpflöcke fest ein!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 54, 3, 'Denn nach rechts und nach links wirst du dich ausbreiten, und deine Nachkommenschaft wird ganze Völker beerben und verödete Städte neu bevölkern.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 54, 4, 'Fürchte dich nicht, denn du sollst nicht enttäuscht werden, und schäme dich nicht, denn du wirst nicht wieder zu erröten brauchen, sondern sollst die Schande deiner Jugendzeit vergessen und der Schmach deines Witwenstandes nicht länger gedenken müssen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 54, 5, 'Denn der dich geschaffen hat, ist dein Eheherr: ›HERR der Heerscharen‹ ist sein Name; und dein Erlöser ist der Heilige Israels: er heißt ›der Gott der ganzen Erde‹.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 54, 6, 'Denn als die verlassene und im Herzen tiefbekümmerte Gattin ruft dich der HERR zurück: »Wie könnte man auch die Jugendgeliebte verstoßen?« spricht dein Gott.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 54, 7, '»Nur einen kurzen Augenblick lang habe ich dich verlassen, aber mit herzlichem Erbarmen will ich dich wieder heimholen;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 54, 8, 'in überwallendem Zorn habe ich mein Angesicht einen Augenblick lang vor dir verhüllt, aber mit unendlicher Huld will ich mich deiner nun wieder erbarmen«, spricht der HERR, dein Erlöser.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 54, 9, '»Denn hierbei will ich’s halten wie einst bei der Flut Noahs: Wie ich (damals) geschworen habe, daß die Flut Noahs nie wieder die Erde überschwemmen solle, ebenso habe ich jetzt geschworen, daß ich nicht länger Zorn gegen dich hegen und dich nicht wieder schelten will.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 54, 10, 'Denn mögen auch die Berge weichen und die Hügel wanken, so soll doch meine Gnade nicht von dir weichen und mein Friedensbund nicht wanken«, spricht der HERR, dein Erbarmer.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 54, 11, '»Du Gebeugte, Sturmbewegte, nie Getröstete! Fürwahr, ich will deine Steine in Bleiglanz einlagern und dich mit Saphirsteinen gründen');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 54, 12, 'und will deine Mauerzinnen aus Rubinen herstellen und deine Tore aus Karfunkelsteinen und deine ganze Umfriedung aus Edelgestein.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 54, 13, 'Alle deine Söhne werden vom HERRN unterwiesen und das Wohlbefinden deiner Söhne wird reich gesegnet sein.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 54, 14, 'Durch Gerechtigkeit wirst du fest gegründet werden: entschlage dich der Angst, denn du hast nichts mehr zu fürchten, und halte dich fern von Schrecken, denn er soll an dich nicht herankommen!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 54, 15, 'Wisse wohl: wenn man Angriffe auf dich macht, so geht das nicht von mir aus; wer zum Angriff gegen dich vorgeht, soll um deinetwillen zu Fall kommen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 54, 16, 'Ich habe ja doch den Schmied geschaffen, der das Kohlenfeuer zur Glut entfacht und eine Waffe mit seiner Kunstfertigkeit herstellt; und ich bin es auch, der den Verderber geschaffen hat, um zu vernichten.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 54, 17, 'Keine Waffe, die gegen dich geschmiedet wird, soll etwas ausrichten, und jede Zunge, die zum Rechtsstreit gegen dich auftritt, wirst du Lügen strafen: dies ist das Erbteil der Knechte des HERRN und die Gerechtigkeit, die ihnen von mir zuteil wird« – so lautet der Ausspruch des HERRN.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 55, 1, 'Ach ihr Durstigen alle, kommt her zum Wasser, und ihr alle, die ihr kein Geld habt, kommt herbei, kauft (Brot) und eßt! Ja kommt, kauft ohne Zahlung und unentgeltlich Wein und Milch!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 55, 2, 'Warum wollt ihr Geld für das zahlen, was kein Brot ist, und euren sauren Verdienst für etwas, das nicht zur Sättigung dient? Hört doch auf mich, so sollt ihr Gutes zu essen haben, und laben soll sich eure Seele an fetter Speise!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 55, 3, 'Leiht mir euer Ohr und kommt her zu mir! Hört, auf daß eure Seele auflebt! Denn ich will mit euch einen ewigen Bund schließen, (will) die dem David gegebenen unverbrüchlichen Gnadenverheißungen (verwirklichen).');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 55, 4, 'Wisset wohl: ich habe ihn zum Zeugen für Völker bestellt, zum Fürsten und Gebieter von Völkerschaften.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 55, 5, 'Wisset wohl: Volksstämme, die du nicht kennst, wirst du herbeirufen, und Volksstämme, die auch dich nicht gekannt haben, werden zu dir herbeieilen um des HERRN, deines Gottes, willen und wegen des Heiligen Israels, weil er dich verherrlicht hat.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 55, 6, 'Suchet den HERRN, solange er sich finden läßt; ruft ihn an, solange er nahe ist!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 55, 7, 'Der Gottlose verlasse seinen Weg und der auf Frevel Bedachte seine Gedanken und kehre zum HERRN zurück, daß er sich seiner erbarme, und zu unserm Gott, denn er übt reichlich Vergebung.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 55, 8, 'Denn »meine Gedanken sind nicht eure Gedanken, und eure Wege sind nicht meine Wege« – so lautet der Ausspruch des HERRN –;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 55, 9, '»sondern soviel der Himmel höher als die Erde ist, soviel höher sind meine Wege als eure Wege und meine Gedanken höher als eure Gedanken.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 55, 10, 'Denn gleichwie der Regen und der Schnee vom Himmel herabfällt und nicht dorthin zurückkehrt, er habe denn die Erde getränkt und befruchtet und sie zum Grünen gebracht, so daß sie dem Sämann Samen und dem Essenden Brot gegeben hat –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 55, 11, 'ebenso verhält es sich auch mit meinem Wort, das aus meinem Munde hervorgeht: es kehrt nicht leer zu mir zurück, sondern erst dann, wenn es das ausgerichtet hat, was ich gewollt habe, und das zustande gebracht hat, wozu ich es gesandt habe.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 55, 12, 'Denn mit Freuden sollt ihr ausziehen und in Frieden geleitet werden; die Berge und Hügel werden vor euch her in Jubel ausbrechen und alle Bäume des Gefildes in die Hände klatschen;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 55, 13, 'statt des Dorngestrüpps werden Zypressen emporwachsen und statt der Nesseln Myrten sprießen; und das wird für den HERRN zum Ruhme dienen, zu einem ewigen Denkzeichen, das nicht ausgetilgt wird.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 56, 1, 'So hat der HERR gesprochen: »Beobachtet das Recht und übet Gerechtigkeit! Denn nahe ist mein Heil, um einzutreffen, und meine Gerechtigkeit, um offenbar zu werden.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 56, 2, 'Wohl dem Menschen, der solches tut, und dem Menschenkind, das hieran festhält: der den Sabbat beobachtet, so daß er ihn nicht entheiligt, und seine Hand von jeder bösen Tat fernhält!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 56, 3, 'Und der Fremdling, der sich an den HERRN angeschlossen hat, möge nicht sagen: »Der HERR wird mich sicherlich aus seinem Volk ausschließen!« Und der Verschnittene sage nicht: »Ach, ich bin nur ein dürrer Baum!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 56, 4, 'Vielmehr so hat der HERR gesprochen: »Den Verschnittenen, die meine Sabbate beobachten und das erwählen, woran ich Wohlgefallen habe, und meinem Bunde treu bleiben,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 56, 5, 'denen will ich in meinem Hause und in meinen Mauern einen Platz und einen Namen verleihen, der besser ist als Söhne und Töchter: einen ewigen Namen will ich ihnen verleihen, der nicht ausgetilgt werden soll!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 56, 6, 'Und die Fremdlinge, die sich an den HERRN anschließen, um ihm zu dienen und den Namen des HERRN zu lieben, um seine Knechte zu sein, alle, die den Sabbat unentweiht beobachten und meinem Bunde treu bleiben:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 56, 7, 'die will ich zu meinem heiligen Berge bringen und ihnen Freude gewähren in meinem Bethause, ihre Brandopfer und ihre Schlachtopfer sollen mir wohlgefällig sein auf meinem Altar; denn mein Haus soll ein Bethaus genannt werden für alle Völker.« –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 56, 8, 'So lautet der Ausspruch Gottes des HERRN, der die verstoßenen Angehörigen Israels sammelt: »Ich will ihm noch mehr hinzusammeln zu denen, die schon gesammelt sind.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 56, 9, 'Alle ihr Tiere des Feldes, kommt herbei zum Fressen, alle ihr Tiere im Walde!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 56, 10, 'Die Hüter meines Volkes sind blind, allesamt ohne Einsicht; alle sind sie stumme Hunde, die nicht bellen können; träumend liegen sie da und schlafen gern;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 56, 11, 'und dabei sind sie freßgierige Hunde, die keine Sättigung kennen. Und zugleich sind sie Hirten, die kein Verständnis und keine Einsicht zeigen: alle gehen ihrem eigenen Wege nach, jeder ist auf seinen Vorteil bedacht, einer wie der andere.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 56, 12, '»Kommt her« (sagen sie), »ich will Wein holen, und Rauschtrank wollen wir zechen! Und morgen soll es wieder so zugehen wie heute, herrlich über alle Maßen!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 57, 1, 'Der Gerechte kommt um, ohne daß jemand es sich zu Herzen nimmt, und die Frommen werden hinweggerafft, ohne daß jemand es beachtet; denn der Gerechte wird infolge der herrschenden Bosheit hinweggerafft;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 57, 2, 'es geht (aber) ein zum Frieden, es ruht auf seiner Lagerstätte aus ein jeder, der seinen Weg gerade vor sich hin gewandelt ist.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 57, 3, 'Ihr aber, tretet näher hierher, ihr Kinder der Zauberin, Brut, die du Ehebruch und Unzucht getrieben hast!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 57, 4, 'Über wen macht ihr euch lustig? Über wen reißt ihr den Mund weit auf und streckt die Zunge lang heraus? Seid ihr nicht Kinder treulosen Abfalls, eine Lügenbrut?');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 57, 5, 'Ihr, die ihr in Brunst glüht für die Götzen unter jedem dichtbelaubten Baum, die ihr Kinder in den Tälern schlachtet inmitten der Felsenklüfte!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 57, 6, 'Mit den glatten Steinen des Talbaches hast du dir zu schaffen gemacht, sie sind dein Los gewesen; auch ihnen hast du Trankopfer ausgegossen, Speisopfer dargebracht: soll ich mich mit solchen Dingen zufrieden geben?');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 57, 7, 'Auf jedem hohen und ragenden Berge hast du dein Lager aufgeschlagen; auch dort bist du hinaufgestiegen, um Schlachtopfer darzubringen;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 57, 8, 'und hinter der Tür und dem Türpfosten hast du deinen Hausgötzen untergebracht; denn mir untreu, hast du dein Lager aufgedeckt und bestiegen, hast es auch breit gemacht und dir den Buhlerlohn von ihnen ausbedungen, hast nach ihrer Umarmung Verlangen getragen und ihre Blöße geschaut.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 57, 9, 'Auch bist du mit Öl zum Moloch gezogen und hast wohlriechende Salben in Menge mitgenommen, hast deine Boten weithin gesandt und dich erniedrigt bis zur Unterwelt.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 57, 10, 'Wurdest du auch müde von deinem weiten Wandern, so hast du doch nicht gesagt: »Ich gebe es auf«; nein, du gewannest immer neue Kraft in deinen Gliedern; darum wurdest du nicht matt.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 57, 11, 'Und vor wem hast du dich gescheut und dich gefürchtet, so daß du die Treue brachest und meiner nicht mehr gedachtest und ich dir nicht in den Sinn kam? Nicht wahr? Weil ich mich schweigend verhielt, und zwar seit undenklicher Zeit, darum fürchtetest du dich nicht vor mir.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 57, 12, 'Aber ich will jetzt bekannt machen, wie es um deine Gerechtigkeit steht, und was deine Machwerke anlangt, so werden sie dir nichts nützen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 57, 13, 'Wenn du dann schreist, mögen deine Haufen von Götzen dir helfen! Doch ein Windstoß wird sie alle davontragen, ein Hauch sie hinwegraffen. Aber wer auf mich vertraut, der wird das Land erben und meinen heiligen Berg in Besitz nehmen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 57, 14, 'Und er (der HERR) wird gebieten: »Schafft Bahn, schafft Bahn, bereitet einen Weg! Räumt meinem Volke jeden Anstoß aus dem Wege!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 57, 15, 'Denn so hat der Hohe und Erhabene gesprochen, der da ewiglich thront und dessen Name ›der Heilige‹ ist: »In der Höhe und im Heiligtum wohne ich und bei denen, die zerschlagenen und gebeugten Geistes sind, um neu zu beleben den Geist der Gebeugten und zu erquicken das Herz der Zerschlagenen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 57, 16, 'Denn nicht ewiglich will ich hadern und nicht immerdar zürnen; es müßte sonst ja jeder Geist vor mir verschmachten und die Lebensgeister, die ich selbst geschaffen habe.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 57, 17, 'Nur wegen seiner sündhaften Habgier habe ich (dem Volk) gezürnt und es strafend heimgesucht, indem ich zornig mich verbarg, während es abtrünnig seinem selbstgewählten Wege nachging.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 57, 18, 'Seine Wege habe ich wohl gesehen, und doch will ich es heilen, will es leiten und ihm und zwar seinen Leidtragenden Trost als Vergeltung spenden,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 57, 19, 'indem ich als die Frucht der Lippen Frieden schaffe, nämlich Frieden den Fernen und den Nahen!« spricht der HERR, »und ich will es heilen!« –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 57, 20, 'Aber die Gottlosen gleichen dem aufgewühlten Meer, das nicht zur Ruhe kommen kann und dessen Wasser Schlamm und Schmutz aufwühlen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 57, 21, '»Keinen Frieden«, spricht mein Gott, »gibt es für die Gottlosen.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 58, 1, 'Rufe mit voller Kehle aus, ohne an dich zu halten, laß deine Stimme laut erschallen wie eine Posaune und halte meinem Volk seine Untreue vor und dem Hause Jakobs seine Sünden!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 58, 2, 'Zwar befragen sie mich Tag für Tag und tragen Verlangen nach der Kenntnis meiner Wege; als wären sie ein Volk, das Gerechtigkeit geübt und das Recht seines Gottes nicht verlassen hat, fordern sie Gerichte der Gerechtigkeit von mir, erwarten ungeduldig das Nahen Gottes.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 58, 3, '»Warum fasten wir« (sagen sie), »und du siehst es nicht? Warum kasteien wir uns, und du beachtest es nicht?« Bedenket wohl: am Tage, wo ihr fastet, geht ihr doch euren Geschäften nach und drängt alle eure Leute zur Arbeit.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 58, 4, 'Bedenket wohl: nur zur Erregung von Streit und Händeln haltet ihr Fasten und um mit roher Faust dreinzuschlagen; ihr fastet zur Zeit nicht so, daß ihr eurem Beten Erhörung in der Himmelshöhe verschaffen könntet.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 58, 5, 'Soll dergleichen etwa ein Fasten sein, an dem ich Gefallen habe, ein Tag, an dem der Mensch sich wirklich kasteit? Daß man den Kopf hängen läßt wie ein Binsenhalm und sich Sackleinen anlegt und sich auf Asche bettet: darfst du das ein Fasten nennen und einen dem HERRN wohlgefälligen Tag?');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 58, 6, 'Ist nicht vielmehr das ein Fasten, wie ich es liebe: daß man ungerechte Fesseln löst, daß man die Bande des Knechtschaftjoches sprengt, Vergewaltigte in Freiheit setzt und jegliches Joch zerbricht?');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 58, 7, 'Nicht wahr? Wenn du dem Hungrigen dein Brot brichst und unglückliche Obdachlose in dein Haus aufnimmst, wenn du einen Halbnackten siehst, ihn kleidest und dich deinem Volksgenossen nicht entziehst:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 58, 8, 'dann wird dein Licht wie das Morgenrot hervorbrechen und deine Heilung schnelle Fortschritte machen; und vor dir wird deine Gerechtigkeit hergehen und die Herrlichkeit des HERRN deine Nachhut bilden.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 58, 9, 'Wenn du dann rufst, wird der HERR dir antworten; und wenn du um Hilfe schreist, wird er sagen: »Siehe, hier bin ich!« Wenn du die Knechtung, das höhnische Fingerausstrecken und das Trugreden aus deiner Mitte wegschaffst');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 58, 10, 'und dem Hungrigen das darreichst, wonach du selbst Verlangen trägst, und dadurch eine verzagte Seele sättigst, dann wird dein Licht in der Finsternis erstrahlen und dein Dunkel wie der helle Mittag werden;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 58, 11, 'und der HERR wird dich allezeit geleiten und deine Seele auch in dürren Gegenden sich sättigen lassen und deine Glieder kräftig machen, so daß du einem wohlbewässerten Garten gleichst und einem Wasserquell, dessen Fluten nicht trügen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 58, 12, 'Und die Deinen sollen die uralten Trümmerstätten wieder aufbauen; die Grundmauern vieler früheren Geschlechter wirst du wieder aufrichten; und man wird dich den ›Vermaurer von Rissen‹ nennen, den ›Wiederhersteller bewohnbarer Straßen‹.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 58, 13, 'Wenn du deinen Fuß vom Sabbat zurückhältst, so daß du nicht deine Geschäfte an dem mir heiligen Tage betreibst, sondern den Sabbat eine Wonne und den heiligen Tag des HERRN verehrungswürdig nennst und ihn dadurch ehrst, daß du nicht deine Gänge an ihm abmachst, nicht deinen Geschäften nachgehst und leeres Geschwätz verführst:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 58, 14, 'dann wirst du deine Lust am HERRN haben, und ich werde dich auf den Höhen der Erde einherfahren lassen und will dir das Erbe deines Vaters Jakob zu verspeisen geben; denn der Mund des HERRN hat es gesprochen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 59, 1, 'Wisset wohl: der Arm des HERRN ist nicht zu kurz, daß er nicht helfen könnte, und sein Ohr ist nicht so taub, daß er nicht hörte;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 59, 2, 'nein, eure Verschuldungen bilden eine Scheidewand zwischen euch und eurem Gott, und eure Sünden haben sein Angesicht vor euch verhüllt, so daß er nicht hört;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 59, 3, 'denn eure Hände sind mit Blut befleckt und eure Finger mit Verschuldung; eure Lippen reden Lüge, und eure Zunge läßt Unwahrheit verlauten.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 59, 4, 'Keiner ladet den andern in Gerechtigkeit vor Gericht, und keiner führt einen Rechtsstreit in Treue; nein, man verläßt sich auf Trug und redet Täuschung, man geht schwanger mit Unheil und gebiert Verderben.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 59, 5, 'Basiliskeneier brüten sie aus, und Spinnefäden weben sie: wer eins von ihren Eiern ißt, muß sterben, und wenn eins zerdrückt wird, so fährt eine Otter heraus.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 59, 6, 'Ihre Spinngewebe taugen nicht zur Bekleidung, und in ihr Gewirk kann man sich nicht hüllen: ihre Werke sind Unheilswerke, und Gewalttätigkeit liegt in ihren Händen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 59, 7, 'Ihre Füße laufen zum Bösestun und haben es eilig, unschuldiges Blut zu vergießen; ihre Gedanken sind auf Unheil gerichtet, Verwüstung und Zerstörung bezeichnen ihre Bahnen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 59, 8, 'Den Weg des Friedens kennen sie nicht, und kein Recht gibt es in ihren Geleisen; sie schlagen krumme Pfade ein: wer immer sie betritt, lernt den Frieden nicht kennen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 59, 9, 'Darum ist der Rechtsspruch fern von uns geblieben, und die Gerechtigkeit erreicht uns nicht; wir harren auf das Licht, aber ach! es bleibt dunkel, auf Tageshelle, aber in finsterer Nacht müssen wir wandeln.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 59, 10, 'Wir tasten wie die Blinden an der Wand hin und tappen wie Augenlose umher; wir straucheln am hellen Mittag wie in der Dämmerung und sind unter den Wohlgenährten den Toten gleich.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 59, 11, 'Wir brummen alle wie die Bären und girren ohne Unterlaß wie die Tauben; wir harren auf den Rechtsspruch, aber sie kommt nicht, und auf Rettung, aber sie bleibt fern von uns.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 59, 12, 'Denn groß ist die Zahl unserer Übertretungen vor dir, und unsere Sünden zeugen gegen uns; denn unserer Übertretungen sind wir uns bewußt, und unsere Verschuldungen kennen wir:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 59, 13, 'Treubruch und Verleugnung dem HERRN gegenüber und Abkehr von der Anhänglichkeit an unsern Gott, Reden von Gewalttätigkeit und Abfall, Schwangergehn mit Lügenworten und sie gegen besseres Wissen aussprechen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 59, 14, 'So ist denn das Recht zurückgedrängt, und die Gerechtigkeit steht weitab; denn die Wahrheit wankt auf dem Markt, und die Redlichkeit findet keinen Einlaß.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 59, 15, 'So ist denn die Wahrheit verschwunden; und wer sich gegen das Böse auflehnt, muß sich ausplündern lassen. Als der HERR das sah, mißfiel es ihm sehr, daß nirgends Recht vorhanden war;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 59, 16, 'und weil er sah, daß kein Mann (zur Rettung) da war, und er sich verwunderte, daß niemand sich ins Mittel legte, da mußte sein eigener Arm ihm helfen, und seine Gerechtigkeit mußte seine Stütze werden.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 59, 17, 'Er legte also die Gerechtigkeit als einen Panzer an und setzte sich den Helm des Heils aufs Haupt; er zog Rachekleider als Waffenrock an und hüllte sich in Zorneseifer wie in einen Mantel.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 59, 18, 'Ganz den verübten Taten entsprechend wird er vergelten: Zornglut seinen Widersachern, Rache seinen Feinden; den Meeresländern wird er den verdienten Lohn zahlen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 59, 19, 'Dann wird man im Westen den Namen des HERRN fürchten und im Osten seine Herrlichkeit; denn er wird daherkommen wie ein eingezwängter Strom, gegen den der Hauch des HERRN anstürmt.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 59, 20, '»Aber für Zion wird er als Erlöser erscheinen, und zwar für die, welche in Jakob vom Treubruch sich bekehrt haben« – so lautet der Ausspruch des HERRN.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 59, 21, '»Was aber mich betrifft, so soll dies mein Bund mit ihnen sein« – so hat der HERR gesprochen –: »Mein Geist, der auf dir ruht, und meine Worte, die ich dir in den Mund gelegt habe, die sollen nicht aus deinem Munde weichen und auch nicht aus dem Munde deiner Kinder und nicht aus dem Munde deiner Kindeskinder« – so hat der HERR gesprochen – »von nun an bis in alle Ewigkeit.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 60, 1, 'Mache dich auf, werde licht! Denn dein Licht ist gekommen, und die Herrlichkeit des HERRN ist über dir erstrahlt.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 60, 2, 'Denn wohl bedeckt Finsternis die Erde und Dunkel die Völker, aber über dir strahlt der HERR wie eine Sonne auf, und seine Herrlichkeit wird sichtbar über dir.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 60, 3, 'Völker wallen zu deinem Licht hin und Könige zu dem Glanz, in dem du strahlst.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 60, 4, 'Hebe ringsum deine Augen empor und blicke hin! Sie alle haben sich versammelt und kommen zu dir: deine Söhne kommen aus der Ferne, und deine Töchter werden auf den Armen getragen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 60, 5, 'Da wirst du dann, sobald du das siehst, vor Freude strahlen, und dein Herz wird pochen und sich weit auftun; denn der Reichtum des Meeres wird sich dir zuwenden, die Schätze der Völker dir zuströmen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 60, 6, 'Ein Gewimmel von Dromedaren wird dich bedecken, die jungen Kamele von Midian und Epha; allesamt werden sie aus Saba herkommen, Gold und Weihrauch bringen und die Ruhmestaten des HERRN verkünden.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 60, 7, 'Alle Herden von Kedar werden sich für dich sammeln, die Widder von Nebajoth dir zu Diensten stehen: mir zum Wohlgefallen werden sie auf meinen Altar gebracht werden, und so mache ich meinen glanzvollen Tempel noch glänzender.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 60, 8, 'Wer sind diese da, die wie eine Wolke dahergeflogen kommen und wie Tauben zu ihren Schlägen?');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 60, 9, 'Ja, auf mich harren die Meeresländer, und die Tharsisschiffe segeln voran, um deine Söhne aus der Ferne herzubringen; ihr Silber und ihr Gold führen sie mit sich für den Namen des HERRN, deines Gottes, und für den Heiligen Israels, weil er dich zu hohen Ehren bringt.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 60, 10, 'Die Söhne fremden Stammes werden deine Mauern aufbauen und ihre Könige dir dienstbar sein; denn in meinem Grimm habe ich dich (allerdings) geschlagen, aber in meiner Gnade mich deiner wieder erbarmt.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 60, 11, 'Deine Tore werden beständig offen stehen, bei Tag und bei Nacht unverschlossen bleiben, um in dich einzulassen den Reichtum der Völker und ihre Könige, die im Triumph aufgeführt werden.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 60, 12, 'Denn jedes Volk und jedes Reich, die dir nicht dienen wollen, sollen untergehen, und die Heidenvölker überhaupt völliger Vernichtung anheimfallen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 60, 13, 'Die Prachtbäume des Libanons sollen zu dir gebracht werden, Zypressen, Platanen und Edeltannen zumal, um die Stätte meines Heiligtums zu zieren; denn ich will die Stätte ehren, wo meine Füße ruhen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 60, 14, 'Es sollen auch die Söhne deiner (früheren) Bedrücker tiefgebückt zu dir kommen, und alle deine Verächter sich zu deinen Fußsohlen niederwerfen und dich ›die Stadt des HERRN‹ nennen, ›das Zion des Heiligen Israels‹.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 60, 15, 'Statt daß du verlassen und verhaßt warst, so daß niemand dich aufsuchte, will ich dich zu ewigem Stolz machen, zum Entzücken für alle künftigen Geschlechter.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 60, 16, 'Und du wirst die Milch der Völker schlürfen und dich an der Brust der Könige nähren und sollst erkennen, daß ich, der HERR, dein Retter bin und daß dein Erlöser der starke Held Jakobs ist.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 60, 17, 'Anstatt des Kupfers will ich Gold herbringen und anstatt des Eisens Silber herbeischaffen, statt des Holzes Kupfer und statt der Steine Eisen. Und ich will zu deiner Obrigkeit den Frieden machen und zu deiner Regierung die Gerechtigkeit.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 60, 18, 'Nicht wird man künftig von Gewalttaten in deinem Lande hören, von Verheerung und Verwüstung innerhalb deiner Grenzen, sondern deine Mauern wirst du ›Heil‹ nennen und deine Tore als ›Ruhm‹ bezeichnen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 60, 19, 'Nicht mehr wird dir künftig am Tage die Sonne als Leuchte dienen, noch bei Nacht der Mond dir zur Erhellung scheinen; nein, der HERR wird dir zum ewigen Licht dienen und dein Gott zu deiner herrlichen Zier.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 60, 20, 'Nicht mehr wird künftig deine Sonne untergehen, noch dein Mond den Schein verlieren; denn der HERR wird dir zum ewigen Licht werden, und die Tage deiner Trauer sollen zu Ende sein.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 60, 21, 'Dann wird dein Volk in seiner Gesamtheit aus Gerechten bestehen; ewiglich werden sie das Land besitzen als der Sproß der von mir angelegten Pflanzung, als das Werk meiner Hände, zu meiner Verherrlichung:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 60, 22, 'der Kleinste wird zu einer Tausendschaft werden und der Geringste zu einem starken Stamm: ich, der HERR, habe es verheißen und werde es zu seiner Zeit eilends verwirklichen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 61, 1, 'Der Geist Gottes des HERRN ruht auf mir, weil der HERR mich gesalbt hat, um den Elenden frohe Botschaft zu bringen; er hat mich ja gesandt, um die, welche gebrochenen Herzens sind, zu verbinden, den Gefangenen die Freilassung anzukündigen und den Gebundenen die Entfesselung,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 61, 2, 'ein Gnadenjahr des HERRN und einen Tag der Rache unsers Gottes auszurufen, um allen Trauernden Trost zu bringen,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 61, 3, 'den um Zion Trauernden als Gnadengeschenk zu verleihen Kopfschmuck statt der schmutzigen Asche, Freudenöl statt des Trauergewandes, Lobgesang statt eines verzagten Geistes, damit man sie nenne ›Eichen der Gerechtigkeit‹, ›die Pflanzung des HERRN ihm zur Verherrlichung‹.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 61, 4, 'Dann werden sie die uralten Trümmerstätten wieder aufbauen und, was in früheren Zeiten zerstört worden ist, wieder aufrichten; sie werden die verödeten Städte wiederherstellen, Plätze, die wüst dagelegen haben von Geschlecht zu Geschlecht.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 61, 5, 'Und fremde Leute werden antreten, um eure Herden zu weiden, und Ausländer werden eure Ackerleute und Weingärtner sein;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 61, 6, 'ihr aber werdet ›Priester des HERRN‹ heißen, und ›Diener unsers Gottes‹ wird man euch nennen; den Reichtum der Heidenvölker werdet ihr genießen und in ihre Herrlichkeit eintreten.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 61, 7, 'Die erlittene Schmach wird euch doppelt ersetzt werden, und zum Entgelt für erfahrene Schmähung werden sie über ihren Anteil jubeln; daher sollen sie doppelten Besitz in ihrem Lande erhalten, und ewige Freude wird ihnen zuteil werden.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 61, 8, 'Denn ich, der HERR, liebe das Recht und hasse frevelhaften Raub; so will ich ihnen denn ihren Lohn getreulich geben und einen ewigen Bund mit ihnen schließen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 61, 9, 'Ihre Nachkommenschaft soll unter den Völkerschaften wohlbekannt sein und ihre Sprößlinge inmitten der Völker: alle, die sie sehen, werden sie anerkennen als ein vom HERRN gesegnetes Geschlecht.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 61, 10, '»Laut frohlocken will ich über den HERRN, jubeln soll meine Seele über meinen Gott! Denn er hat mich in Gewänder des Heils gekleidet, mir den Mantel der Gerechtigkeit umgelegt wie einem Bräutigam, der sich den Kopfschmuck nach Priesterart zurichtet, und wie eine Braut, die ihr Geschmeide anlegt.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 61, 11, 'Denn wie die Erde ihr Gesproß hervorbringt und wie ein Garten seine Aussaat sprossen läßt, so wird Gott der HERR Gerechtigkeit sprossen lassen und Ruhm angesichts aller Völker.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 62, 1, 'Um Zions willen darf ich nicht schweigen und um Jerusalems willen mir keine Ruhe gönnen, bis seine Gerechtigkeit aufgeht wie Lichtglanz und sein Heil wie eine brennende Fackel,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 62, 2, 'und bis die Völker deine Gerechtigkeit sehen und alle Könige deine Herrlichkeit und man dir einen neuen Namen beilegt, den der Mund des HERRN bestimmen wird.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 62, 3, 'Dann wirst du eine prachtvolle Krone in der Hand des HERRN sein und eine königliche Kopfbinde in der Hand deines Gottes;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 62, 4, 'und man wird dich nicht mehr ›die Verlassene‹ nennen und dein Land nicht mehr als ›Verödung‹ bezeichnen, sondern man wird dich ›Mein Wohlgefallen haftet an ihr‹ nennen und dein Land ›die Vermählte‹; denn der HERR hat Gefallen an dir, und dein Land stellt seine Gattin dar.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 62, 5, 'Denn wie der Jüngling sich mit der Jungfrau vermählt, so werden deine Söhne sich mit dir vermählen, und wie der Bräutigam seine Freude an der Braut hat, so wird dein Gott Freude über dich empfinden.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 62, 6, '»Über deine Mauern, Jerusalem, habe ich Wächter bestellt, die den ganzen Tag und die ganze Nacht hindurch keinen Augenblick schweigen sollen.« Ihr, die ihr den HERRN erinnern sollt: gönnt euch keine Ruhe');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 62, 7, 'und gewährt auch ihm keine Ruhe, bis er sich dazu bereit macht und Jerusalem zu einer Berühmtheit auf der Erde macht.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 62, 8, 'Geschworen hat der HERR bei seiner Rechten und bei seinem starken Arm: »Ich will fortan dein Getreide deinen Feinden nicht mehr zur Nahrung hingeben, und niemals wieder sollen Ausländer deinen Wein trinken, um den du dich gemüht hast;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 62, 9, 'nein, die (das Korn) eingeerntet haben, sollen es auch verzehren und den HERRN dabei preisen; und die (den Wein) gelesen haben, sollen ihn auch trinken in den Vorhöfen meines Heiligtums.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 62, 10, 'Zieht aus, zieht aus durch die Tore! Bereitet dem Volk den Weg! Bahnet, bahnet die Straße, räumt die Steine weg, pflanzt ein Panier für die Völker auf!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 62, 11, 'Sehet, der HERR hat den Befehl bis ans Ende der Erde erschallen lassen: »Sagt der Tochter Zion: ›Siehe, dein Heil kommt, siehe, sein Lohn kommt mit ihm, und seine Vergeltung geht vor ihm her!‹«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 62, 12, 'Und man wird sie nennen ›das heilige Volk‹, ›die durch den HERRN Erlösten‹; dich selbst aber wird man nennen ›die Vielbesuchte‹, ›die nicht (mehr) verlassene Stadt‹.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 63, 1, 'Wer ist es, der dort von Edom herkommt, von Bozra in hochroten Kleidern? Prächtig ist er in seinem Gewand, stolz schreitet er einher in der Fülle seiner Kraft. »Ich bin es, der mit Gerechtigkeit redet, der reiche Mittel hat zu retten.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 63, 2, '»Woher rührt das Rot an deinem Gewande, und warum sehen deine Kleider aus wie die eines Keltertreters?«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 63, 3, '»Die Kelter habe ich getreten, ich allein, denn von den Völkern stand niemand mir bei; da habe ich sie in meinem Zorn niedergetreten und in meinem Grimm zerstampft; dabei ist ihr Lebenssaft an meine Kleider gespritzt, so daß ich meine ganze Gewandung besudelt habe.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 63, 4, 'Denn ein Tag der Rache lag mir im Sinn, und das Jahr meiner Erlösung war gekommen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 63, 5, 'Ich schaute mich um, doch niemand war da, um zu helfen; ich blickte erstaunt umher, doch niemand war da, der mir beistand; da hat mein Arm mir geholfen, und mein Grimm, der hat mir Beistand geleistet.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 63, 6, 'So habe ich denn Völker in meinem Zorn niedergetreten und sie in meinem Grimm zerschmettert und habe ihren Lebenssaft zur Erde rinnen lassen.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 63, 7, 'Der Gnadenerweise des HERRN will ich gedenken, der Ruhmestaten des HERRN, wie sich’s gebührt nach allem, was der HERR an uns getan hat, und nach der großen Güte gegen das Haus Israel, dem er Gutes erwiesen hat nach seiner Barmherzigkeit und nach der großen Zahl seiner Gnadenverheißungen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 63, 8, 'Denn er sagte: »Sie sind ja doch mein Volk, Söhne, die nicht treulos sein werden«; so erwies er sich ihnen denn als Retter.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 63, 9, 'In allen ihren Bedrängnissen fühlte (auch) er sich bedrängt, und der Engel seines Angesichts rettete sie; in seiner Liebe und Milde erlöste er selbst sie und hob sie immer wieder empor und trug sie einher alle Tage der Vorzeit hindurch.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 63, 10, 'Sie aber waren widerspenstig und betrübten seinen heiligen Geist, so daß er sich ihnen in einen Feind verwandelte und selbst gegen sie stritt.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 63, 11, 'Da dachte sein Volk zurück an die Tage der Vorzeit, an Mose: »Wo ist der, welcher den Hirten seiner Herde aus dem Meer heraufgeholt hat? Wo ist der, welcher seinen heiligen Geist ihm ins Herz gab?');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 63, 12, 'Welcher seinen gewaltigen Arm zur Rechten Moses einhergehen ließ? Welcher die Wasser ihretwegen zerteilte, um sich einen ewigen Namen zu schaffen?');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 63, 13, 'Welcher sie durch die Fluten ziehen ließ wie Rosse in der Steppe, so daß sie nicht strauchelten?');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 63, 14, 'Gleich der Herde, die ins Tal hinabzieht, brachte der Geist des HERRN sie zur Ruhe.« So hast du dein Volk geleitet, um dir einen ruhmvollen Namen zu machen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 63, 15, 'Blicke vom Himmel hernieder und schaue von deiner heiligen und prächtigen Wohnung her! Wo ist dein Eifer und deine Heldenkraft, der Drang deines Herzens und dein Erbarmen? Halte dich doch nicht zurück (gegen mich)!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 63, 16, 'Denn du bist unser Vater. Abraham weiß ja nichts von uns, und Israel kennt uns nicht: du, HERR, bist unser Vater; ›unser Erlöser‹ ist von alters her dein Name.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 63, 17, 'Warum hast du uns abirren lassen, HERR, von deinen Wegen und unser Herz verhärtet, so daß es dich nicht mehr fürchtet? Kehre zurück um deiner Knechte willen, um der Stämme willen, die dein Eigentum sind!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 63, 18, 'Nur kurze Zeit ist das dir geheiligte Volk im Besitz seines Erbes gewesen, da haben unsere Widersacher dein Heiligtum zertreten.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 63, 19, 'a Es ist uns ergangen wie solchen, über die du nicht von alters her geherrscht hast und über denen dein Name niemals genannt worden ist. b O daß du doch den Himmel zerrissest, herabführest, so daß die Berge vor dir ins Wanken gerieten –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 64, 1, 'wie Feuer Reisig in Brand setzt und Feuer das Wasser in Sieden versetzt –, um deinen Namen deinen Widersachern kundzutun, damit die Völker vor dir erzitterten,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 64, 2, 'indem du furchtbare Taten vollführtest, die unsere Erwartung überstiegen! Ja, führest du herab, so daß die Berge vor dir ins Wanken gerieten!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 64, 3, 'Hat man doch von alters her nicht gehört noch vernommen, hat doch kein Auge es je gesehen, daß ein Gott außer dir für einen auf ihn Harrenden Taten vollbringt.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 64, 4, 'Du kommst dem entgegen, der Freude daran hat, Gerechtigkeit zu üben, denen, die auf deinen Wegen deiner gedenken. Doch ach, du bist in Zorn geraten, denn wir haben gesündigt durch unsere Untreue allezeit und unsern Abfall.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 64, 5, 'So sind wir denn allesamt einem Unreinen gleich geworden und alle unsere Gerechtigkeitserweise sind wie ein besudeltes Gewand; wir sind allesamt verwelkt wie Laub, und unsere Sünden haben uns mit sich fortgerissen wie der Wind;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 64, 6, 'und niemand ist da, der deinen Namen noch anruft, niemand, der sich aufrafft, um an dir festzuhalten; denn du hast dein Angesicht vor uns verborgen und läßt uns unter dem Druck unserer Sünden vergehen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 64, 7, 'Nun aber, HERR – du bist ja unser Vater; wir sind der Ton, und du bist unser Bildner, und das Werk deiner Hände sind wir alle –:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 64, 8, 'Zürne nicht unversöhnlich fort, o HERR, und gedenke nicht ewiglich unserer Schuld! Ach, blicke doch her: dein Volk sind wir alle!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 64, 9, 'Deine heiligen Städte sind zur Wüste geworden: Zion ist zur Wüste geworden, Jerusalem zur Trümmerstätte!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 64, 10, 'Unser heiliger und herrlicher Tempel, wo unsere Väter dir lobgesungen haben, ist in Flammen aufgegangen, und alle unsere Lieblingsstätten liegen in Trümmern!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 64, 11, 'Willst du trotz alledem an dich halten, HERR? Willst du schweigen und uns erniedrigen bis zur Vernichtung?');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 65, 1, '»Ich bin zu erkunden gewesen für die, welche nicht (nach mir) fragten, und ich bin zu finden gewesen für die, welche mich nicht suchten; ich habe ›Hier bin ich! Hier bin ich!‹ gesagt zu einem Volk, das meinen Namen nicht anrief.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 65, 2, 'Ich habe meine Arme den ganzen Tag ausgestreckt nach einem widerspenstigen Volk, das seinen eigenen Gedanken nachgeht auf unheilvollem Wege,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 65, 3, 'nach Leuten, die mich beständig in kränkender Weise erbittern, indem sie in den Gärten Schlachtopfer und auf (Altären von) Ziegelsteinen Rauchopfer darbringen,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 65, 4, 'die in den Gräbern sitzen und an geheimnisvollen Orten nächtigen; die Schweinefleisch essen und Brühe von unreinen Dingen in ihren Gefäßen haben;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 65, 5, 'die da sagen: ›Bleibe mir vom Leibe, komm mir nicht nahe, denn ich bin für dich heilig!‹ Solche Leute sind Rauch in meiner Nase, wie loderndes Feuer den ganzen Tag.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 65, 6, 'Wisset wohl: aufgeschrieben liegt das vor mir, und ich werde nicht schweigen, es sei denn, daß ich es vergolten habe; ja, vergelten will ich es und es in ihren Schoß heimzahlen,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 65, 7, 'eure Verschuldungen und die Verschuldungen eurer Väter zugleich!« – so hat der HERR gesprochen –, »weil sie auf den Bergen geopfert und mich auf den Hügeln entehrt haben; ja, ihnen will ich zuvörderst den verdienten Lohn in ihren Schoß hineinmessen!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 65, 8, 'So hat der HERR gesprochen: »Wie man von einer Traube sagt, solange sich noch Saft in ihr findet: ›Verderbe sie nicht, denn es ist ein Segen in ihr!‹, so will auch ich es halten um meiner Knechte willen, um nicht das Ganze zu verderben.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 65, 9, 'Darum will ich aus Jakob einen Samen hervorgehen lassen und aus Juda einen Erben meines Berglandes, damit meine Erwählten das Land ererben und meine Knechte daselbst wohnen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 65, 10, 'Da wird dann die Saronebene zu einer Trift für Schafherden werden und das Tal Achor zum Lagerplatz der Rinder für mein Volk, soviele ihrer mich gesucht haben.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 65, 11, 'Ihr aber, die ihr den HERRN verlassen, die ihr meinen heiligen Berg vergessen habt, die ihr dem Glücksgott den Tisch herrichtet und der Schicksalsgöttin Würzwein (als Trankopfer) einschenkt:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 65, 12, 'euch bestimme ich für das Schwert, und zwar sollt ihr allesamt zur Schlachtung niederknien, zur Strafe dafür, daß ihr, als ich gerufen hatte, nicht geantwortet habt, und als ich redete, nicht hören wolltet, sondern das getan habt, was böse ist in meinen Augen, und euch für das entschieden habt, woran ich kein Wohlgefallen finde.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 65, 13, 'Darum hat Gott der HERR so gesprochen: »Fürwahr, meine Knechte werden essen, ihr aber sollt hungern! Fürwahr, meine Knechte werden trinken, ihr aber sollt Durst leiden! Fürwahr, meine Knechte werden sich freuen, ihr aber sollt beschämt dastehen!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 65, 14, 'Fürwahr, meine Knechte werden jubeln vor Herzenslust, ihr aber sollt schreien vor Herzeleid und laut wehklagen in Verzweiflung!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 65, 15, 'Außerdem sollt ihr euren Namen meinen Erwählten zum Fluchwort hinterlassen: ›Gott der HERR möge so dich töten!‹ Seinen Knechten aber wird er einen andern Namen beilegen,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 65, 16, 'so daß, wer sich segnen will im Lande, sich mit dem Gott der Wahrhaftigkeit segnen wird, und wer im Lande schwört, beim Gott der Treue schwören wird; denn die früheren Drangsale werden vergessen sein und verborgen vor meinen Augen.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 65, 17, '»Denn wisset wohl: ich werde einen neuen Himmel und eine neue Erde schaffen, so daß man der früheren Zustände nicht mehr gedenken wird und sie keinem mehr in den Sinn kommen sollen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 65, 18, 'Nein, freuet euch und jubelt immerdar über das, was ich schaffe; denn wisset wohl: ich will Jerusalem umschaffen zum Jubel und das Volk darin zum Frohlocken;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 65, 19, 'und ich will selbst über Jerusalem jubeln und über mein Volk frohlocken, und es soll hinfort kein Laut des Weinens und kein Laut des Wehgeschreis in ihm vernommen werden.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 65, 20, 'Es soll dort alsdann keinen Säugling von nur wenigen Tagen und keinen Greis mehr geben, der seine Tage nicht voll auslebt; sondern als Jüngster wird der Hundertjährige sterben und wer nur hundert Jahre alt wird, als ein vom Fluch getroffener Sünder gelten.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 65, 21, 'Wenn sie Häuser bauen, werden sie auch darin wohnen und, wenn sie Weinberge anlegen, auch deren Ertrag genießen;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 65, 22, 'sie werden nicht bauen, daß ein anderer darin wohne, und werden nicht pflanzen, daß ein anderer die Früchte genieße; nein, gleich der Lebenszeit der Bäume soll auch die Lebenszeit meines Volkes sein, und was ihre Hände erarbeitet haben, sollen meine Erwählten auch selbst verbrauchen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 65, 23, 'Nicht vergeblich sollen sie sich abmühen und nicht Kinder für jähen Tod zeugen; nein, sie werden ein Geschlecht der vom HERRN Gesegneten sein und ihre Sprößlinge ihnen erhalten bleiben.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 65, 24, 'Und geschehen wird es: ehe sie rufen, will ich schon antworten, und während sie noch reden, will ich sie schon erhören.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 65, 25, 'Wolf und Lamm werden beisammen weiden, und der Löwe wird Stroh fressen wie ein Rind und die Schlange sich von Staub nähren: sie werden nichts Böses mehr verüben und kein Unheil mehr anrichten in meinem ganzen heiligen Berglande: der HERR hat es verheißen!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 66, 1, 'So hat der HERR weiter gesprochen: »Der Himmel ist mein Thron und die Erde der Schemel meiner Füße: was für ein Haus wäre es, das ihr mir bauen könntet, und welches wäre die Stätte, wo ich ruhen soll?');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 66, 2, 'Hat doch meine Hand dies ganze Weltall geschaffen, so daß dies alles entstanden ist« – so lautet der Ausspruch des HERRN. »Ich blicke aber nach dem hin, der demütig und zerschlagenen Geistes ist und der (in Ehrfurcht) bebt beim Gedanken an mein Wort.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 66, 3, 'Wer ein Rind schlachtet, zugleich aber ein Menschenmörder ist; wer ein Stück Kleinvieh opfert, zugleich aber einem Hund das Genick bricht; wer ein Speisopfer darbringt, aber Schweinsblut dazu verwendet; wer Weihrauch als Duftopfer anzündet, zugleich aber einen Götzen verehrt – nun, wie diese ihre eigenen Wege erwählt haben und ihr Herz Wohlgefallen an ihren Scheusalen hat,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 66, 4, 'ebenso will ich mir Qualen für sie erwählen und das, wovor ihnen graut, (als Vergeltung) über sie kommen lassen, weil niemand, als ich gerufen hatte, mir Antwort gegeben und niemand, als ich redete, auf mich gehört hat, sondern sie das getan haben, was böse ist in meinen Augen, und sich für das entschieden haben, woran ich kein Wohlgefallen habe.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 66, 5, 'Höret das Wort des HERRN, ihr, die ihr (in Ehrfurcht) bebt beim Gedanken an sein Wort: »Gesagt haben eure Brüder, die euch hassen, ja die euch ausstoßen um meines Namens willen: ›Der HERR möge doch seine Herrlichkeit sichtbar werden lassen, damit wir eure Freude zu sehen bekommen!‹ Aber die sollen enttäuscht werden.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 66, 6, 'Horch! Getöse erschallt von der Stadt her! Horch, vom Tempel her! Horch, der HERR zahlt seinen Feinden den gebührenden Lohn heim!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 66, 7, 'Ehe sich Wehen bei ihr einstellten, ist sie Mutter geworden; ehe Geburtsschmerzen sie ankamen, ist sie eines Knaben genesen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 66, 8, 'Wer hat so etwas je gehört, wer dergleichen je gesehen? Kann denn ein Land an einem einzigen Tage ins Dasein gerufen oder ein Volk mit einem Mal geboren werden? Und doch ist Zion in Wehen gekommen und hat zugleich auch ihre Kinder geboren.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 66, 9, '»Sollte ich es bis zum Durchbruch des Mutterschoßes kommen lassen, dann aber die Geburt nicht zu Ende führen?« spricht der HERR; »oder sollte ich, der ich gebären lasse, die Geburt verhindern?« spricht dein Gott.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 66, 10, 'Freuet euch mit Jerusalem und jubelt über sie, ihr alle, die ihr sie lieb habt! Seid mit ihr hocherfreut, ihr alle, die ihr Trauer um sie getragen habt,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 66, 11, 'auf daß ihr an ihrer trostspendenden Brust saugt und euch satt trinkt, auf daß ihr euch an der Fülle ihrer Herrlichkeit erlabt!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 66, 12, 'Denn so hat der HERR gesprochen: »Wisset wohl: ich leite das Heil zu ihr hin wie einen Strom und die Herrlichkeit der Völker wie einen flutenden Bach; da sollt ihr wie Säuglinge genährt, sollt auf den Armen getragen und auf den Knien gewiegt werden.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 66, 13, 'Wie einen seine Mutter tröstet, so will ich euch trösten; und zwar in Jerusalem sollt ihr Trost empfangen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 66, 14, 'Wenn ihr es seht, wird euer Herz frohlocken, und eure Leiber werden sprossen wie junges Grün; und die Hand des HERRN wird sich an seinen Knechten zu erkennen geben, sein Groll aber an seinen Feinden.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 66, 15, 'Denn wisset wohl: der HERR wird im Feuer daherkommen und seine Wagen wie der Sturmwind, um seinen Zorn sich auswirken zu lassen in Verderben und sein Schelten in Feuerflammen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 66, 16, 'Denn mit Feuer wird der HERR ein Strafgericht (an der ganzen Erde) vollziehen und mit seinem Schwert an allem Fleisch, und groß wird die Zahl der vom HERRN Erschlagenen sein:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 66, 17, '»Alle, die sich für die Gärten heiligen und sich reinigen hinter einem in der Mitte (dem Götzenpriester) her, alle, die Schweinefleisch, Mäuse und andere Greuel essen, die sollen allesamt ein Ende nehmen!« – so lautet der Ausspruch des HERRN.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 66, 18, '»Denn ich kenne ihr ganzes Tun und ihre Gedanken und werde kommen, um alle Völker und Sprachen zu versammeln; und sie werden kommen und meine Herrlichkeit sehen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 66, 19, 'Ich werde dann ein warnendes Beispiel an ihnen vollziehen und einige von ihnen Entronnene zu den Völkern senden: nach Tharsis, Put und Lud, die den Bogen spannen, nach Thubal und Jonien, nach den fernen Meeresländern, die von mir noch keine Kunde vernommen und von meiner Herrlichkeit noch nichts gesehen haben, damit sie meine Herrlichkeit unter den Völkern verkünden.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 66, 20, 'Sie werden dann alle eure Brüder aus allen Völkern als Weihgeschenk für den HERRN auf Rossen und auf Wagen, in Sänften und auf Maultieren und Dromedaren hinauf zu meinem heiligen Berge nach Jerusalem bringen« – so lautet der Ausspruch des HERRN –, »gleichwie die Israeliten das Speisopfer in reinem Gefäß in das Haus des HERRN bringen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 66, 21, 'Und auch aus ihnen werde ich mir einen Teil zu den levitischen Priestern hinzunehmen« – so hat der HERR gesprochen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 66, 22, '»Denn wie der neue Himmel und die neue Erde, die ich schaffen will, vor mir Bestand haben werden« – so lautet der Ausspruch des HERRN –, »so soll auch eure Nachkommenschaft und euer Name Bestand (vor mir) haben.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 66, 23, 'Und es soll dahin kommen, daß monatlich am Neumond und wöchentlich am Sabbat alles Fleisch sich einfindet, um vor meinem Angesicht anzubeten« – so hat der HERR gesprochen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 66, 24, '»Sie werden dann auch (aus der Stadt) hinausgehen und sich die Leichname der Menschen ansehen, die von mir abgefallen sind; denn ihr Wurm wird nicht sterben und ihr Feuer nicht erlöschen, und sie werden ein Abscheu sein für alles Fleisch.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 1, 1, '(Dies sind) die Reden Jeremias, des Sohnes Hilkias, der zu der Priesterschaft in Anathoth im Lande Benjamin gehörte;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 1, 2, 'an ihn erging das Wort des HERRN in den Tagen des jüdäischen Königs Josia, des Sohnes Amons, im dreizehnten Jahre seiner Regierung,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 1, 3, 'und erging dann auch noch weiter an ihn in den Tagen des judäischen Königs Jojakim, des Sohnes Josias, bis zum Ablauf des elften Regierungsjahres des judäischen Königs Zedekia, des Sohnes Josias, bis zur Wegführung (der Bewohner) Jerusalems im fünften Monat (des elften Regierungsjahres Zedekias).');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 1, 4, 'Es erging aber das Wort des HERRN an mich folgendermaßen:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 1, 5, '»Noch ehe ich dich im Mutterschoße bildete, habe ich dich erwählt, und ehe du das Licht der Welt erblicktest, habe ich dich geweiht: zum Propheten für die Völker habe ich dich bestimmt.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 1, 6, 'Da antwortete ich: »Ach, HERR, mein Gott, sieh doch: ich verstehe ja nicht zu reden, denn ich bin noch so jung!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 1, 7, 'Doch der HERR erwiderte mir: »Sage nicht, du seiest noch so jung! Denn zu allen, wohin ich dich senden werde, sollst du gehen, und alles, was ich dir auftragen werde, sollst du reden.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 1, 8, 'Fürchte dich nicht vor ihnen; denn ich bin mit dir, um dich zu behüten!« – so lautet der Ausspruch des HERRN.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 1, 9, 'Hierauf streckte der HERR seine Hand aus und berührte meinen Mund mit ihr; dann sagte der HERR zu mir: »Hiermit lege ich meine Worte in deinen Mund!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 1, 10, 'Wisse wohl: ich bestelle dich heute über die Völker und über die Königreiche, um auszureißen und niederzureißen, zu vernichten und zu zerstören, (aber auch) um aufzubauen und zu pflanzen.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 1, 11, 'Weiter erging das Wort des HERRN an mich folgendermaßen: »Was siehst du, Jeremia?« Ich antwortete: »Einen Zweig vom wachen Baum sehe ich.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 1, 12, 'Da sagte der HERR zu mir: »Du hast richtig gesehen: ja, ich wache über meinem Wort, um es in Erfüllung gehen zu lassen!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 1, 13, 'Hierauf erging das Wort des HERRN an mich noch einmal folgendermaßen: »Was siehst du?« Ich antwortete: »Einen siedenden Kessel sehe ich, dessen Vorderseite von Norden her (gegen Süden) gerichtet ist.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 1, 14, 'Da sagte der HERR zu mir: »Ja, von Norden her wird das Unglück sich siedend über alle Bewohner des Landes ergießen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 1, 15, 'Denn gib acht: ich will alle Völkerstämme der Reiche im Norden entbieten« – so lautet der Ausspruch des HERRN –, »daß sie heranziehen und ein jeder seinen Thron aufstellt an den Eingang der Tore Jerusalems und gegen alle Mauern der Stadt ringsum und gegen alle Städte Judas.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 1, 16, 'Dann will ich Abrechnung mit ihnen halten wegen all ihrer Bosheit, daß sie von mir abgefallen sind und anderen Göttern geopfert und die Machwerke ihrer Hände angebetet haben.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 1, 17, '»Du aber, gürte dir die Hüften, mache dich auf und verkünde ihnen alles, was ich dir gebieten werde! Erschrick nicht vor ihnen, sonst setze ich dich vor ihnen in Schrecken!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 1, 18, 'Denn wisse wohl: Ich selbst mache dich heute zu einer festen Burg, zu einer eisernen Säule und zu einer ehernen Mauer gegen das ganze Land, sowohl gegen die Könige von Juda als auch gegen dessen Fürsten, gegen dessen Priester und gegen die ganze Bevölkerung des Landes.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 1, 19, 'Wenn sie auch gegen dich anstürmen, sollen sie dich doch nicht bezwingen; denn ich bin mit dir« – so lautet der Ausspruch des HERRN –, »um dich zu behüten!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 2, 1, 'Nun erging das Wort des HERRN an mich folgendermaßen:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 2, 2, '»Gehe hin und rufe (dem Volk in) Jerusalem laut in die Ohren: ›So hat der HERR gesprochen: Ich gedenke an die Holdseligkeit deiner Jugend, deine bräutliche Liebe, wie du hinter mir herzogst in der Wüste, im unwirtlichen Lande.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 2, 3, 'Geheiligt war Israel (damals) dem HERRN, sein Erstlingsabhub von der Ernte; alle, die sich an ihm vergriffen, mußten es büßen: Unheil kam über sie‹« – so lautet der Ausspruch des HERRN.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 2, 4, 'Vernehmt das Wort des HERRN, ihr vom Hause Jakob und alle ihr Geschlechter des Hauses Israel!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 2, 5, 'So hat der HERR gesprochen: »Was haben eure Väter Unrechtes an mir gefunden, daß sie sich von mir losgesagt haben und der Nichtigkeit nachgelaufen und auf Nichtiges verfallen sind?');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 2, 6, 'Sie fragten nicht mehr: ›Wo ist der HERR, der uns aus Ägyptenland hergeführt, der uns durch die Wüste geleitet hat, durch ein Land der Steppen und Schluchten, durch ein Land der Dürre und des Dunkels, durch ein Land, das kein Wanderer durchzieht und in welchem kein Mensch Wohnung nimmt?‹');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 2, 7, 'Als ich euch dann in das Land der Fruchtgefilde gebracht hatte, damit ihr dessen Früchte und Segen genösset, da seid ihr hineingekommen und habt mein Land entweiht und mein Besitztum zu einer Greuelstätte gemacht!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 2, 8, 'Die Priester fragten nicht: ›Wo ist der HERR?‹, und die Hüter des Gesetzes kannten mich nicht, die Hirten des Volkes fielen von mir ab, und die Propheten weissagten durch den Baal und liefen den Götzen nach, die doch nicht zu helfen vermögen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 2, 9, 'Darum muß ich noch weiter mit euch ins Gericht gehen« – so lautet der Ausspruch des HERRN – »und werde noch mit euren Kindeskindern ins Gericht gehen!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 2, 10, '»Denn fahrt doch nach den Gestaden der Kitthäer hinüber und überzeugt euch dort, sendet nach Kedar, erkundigt euch genau und seht zu, ob so etwas jemals geschehen ist:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 2, 11, 'ob je ein Volk seine Götter umgetauscht hat – und die da sind nicht einmal Götter! Aber mein Volk hat seinen Ruhm vertauscht gegen ohnmächtige Götzen!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 2, 12, 'Entsetzt euch darüber, ihr Himmel, schaudert und werdet starr vor Erstaunen!« – so lautet der Ausspruch des HERRN.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 2, 13, '»Denn zwiefaches Unrecht hat mein Volk begangen: mich, den Born lebendigen Wassers, haben sie verlassen, um sich gegrabene Brunnen anzulegen, löcherige Brunnen, die das Wasser nicht halten!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 2, 14, '»Ist denn Israel ein Knecht oder ein Sklavensohn? Warum ist er denn der Plünderung preisgegeben worden?');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 2, 15, 'Löwen haben über ihm gebrüllt, haben ihr Geheul erschallen lassen und sein Land zur Wüste gemacht; seine Städte sind verbrannt, leer von Bewohnern;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 2, 16, 'auch die Ägypter von Noph und Thapanches haben dir den Scheitel abgeweidet.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 2, 17, 'Trägt nicht die Schuld daran deine Abkehr vom HERRN, deinem Gott, schon zur Zeit, wo er dich auf der Wanderung führte?');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 2, 18, 'Und jetzt – was hast du nach Ägypten zu laufen, um das Wasser des Nils zu trinken? Und was brauchst du nach Assyrien zu laufen, um das Wasser des Euphratstromes zu trinken?');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 2, 19, 'Deine Bosheit bringt dich ins Unglück, und dein treuloses Treiben führt die Strafe für dich herbei! So erkenne es denn und bedenke wohl, wie schlimm und unheilvoll es ist, daß du den HERRN, deinen Gott, verlassen hast und keine Furcht vor mir in dir wohnt!« – so lautet der Ausspruch Gottes, des HERRN der Heerscharen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 2, 20, '»Denn von alters her hast du dein Joch zerbrochen, deine Bande zerrissen und hast gesagt: ›Ich will nicht (länger) dienstbar sein!‹ Nein, auf jedem hohen Hügel und unter jedem dichtbelaubten Baum hast du dich als Buhlerin hingestreckt.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 2, 21, 'Und doch hatte ich dich als Edelrebe eingepflanzt, als ganz echtes Gewächs: ach, wie bist du mir in die wilden Schosse eines fremden Weinstocks ausgeartet!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 2, 22, 'Ja, wenn du dich auch mit Laugensalz wüschest und noch so viel Seife an dich wendetest: deine Schuld würde doch als Schmutzfleck vor mir bleiben!« – so lautet der Ausspruch Gottes des HERRN.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 2, 23, '»Wie kannst du nur behaupten: ›Ich habe mich nicht verunreinigt, bin den Baalen nicht nachgelaufen!‹ Sieh doch dein Treiben im Tal an, bedenke, was du dort verübt hast, du leichtfüßige Kamelin, die toll in die Kreuz und Quere rennt!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 2, 24, 'Eine Wildeselin, die, an die Steppe gewöhnt, in wilder Lustgier nach Luft schnappt: wer vermag ihre Brunst zu dämpfen? Wer immer sie begehrt, braucht sich nicht müde zu laufen: in ihrer Brunstzeit findet er sie mühelos.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 2, 25, 'Nimm deinen Fuß in acht, daß er sich nicht barfuß läuft, und deine Kehle, daß sie nicht vor Durst lechzt! Doch du entgegnest: ›Vergebliche Mühe, nein! Ich habe nun einmal die Fremden gern, und ihnen will ich nachlaufen!‹«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 2, 26, '»Wie ein Dieb beschämt dasteht, wenn er ertappt wird, so werden die zum Hause Israel Gehörigen sich schämen, sie samt ihren Königen und Fürsten, ihren Priestern und Propheten,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 2, 27, 'sie, die zu einem Stück Holz sagen: ›Mein Vater bist du!‹ und zu einem Stein: ›Dir verdanke ich mein Leben!‹ Dagegen mir haben sie den Rücken zugekehrt und nicht mehr das Angesicht. Wenn aber das Unglück über sie kommt, dann rufen sie: ›Stehe auf und hilf uns!‹');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 2, 28, 'Wo sind denn deine Götter, die du dir selbst angefertigt hast? Sie mögen doch aufstehen, ob sie dir helfen können zur Zeit deiner Not! Denn so zahlreich wie deine Städte sind auch deine Götter geworden, Juda.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 2, 29, 'Warum beklagt ihr euch über mich? Ihr seid ja allesamt treulos von mir abgefallen!« – so lautet der Ausspruch des HERRN.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 2, 30, '»Vergebens habe ich eure Söhne geschlagen: sie haben sich keine Lehre daraus gezogen; das Schwert hat eure Propheten gefressen wie ein reißender Löwe.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 2, 31, 'O (entartetes) Geschlecht, das ihr seid! Achtet doch auf das Wort des HERRN! Bin ich etwa eine Wüste für Israel gewesen oder ein Land tiefer Finsternis? Warum sagt denn mein Volk: ›Wir haben die Freiheit gewonnen! Wir kehren nicht wieder zu dir zurück!‹?');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 2, 32, 'Vergißt wohl eine Jungfrau ihren Schmuck, eine Braut ihren Gürtel? Mein Volk aber hat mich vergessen schon seit unzähligen Tagen!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 2, 33, '»Wie geschickt weißt du deinen Gang einzurichten, um Liebschaften anzuknüpfen! Darum hast du dich auch auf deinen Gängen sogar an Verbrechen gewöhnt:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 2, 34, 'auch an den Säumen deines Gewandes findet sich das Blut von schuldlosen unglücklichen Menschen, die du nicht bei einem Einbruch betroffen hast.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 2, 35, 'Und trotzdem behauptest du: ›Ich bin unschuldig: sein Zorn wendet sich von mir ab!‹ Wisse wohl: ich will mit dir ins Gericht gehen wegen dieses deines Wortes: ›Ich habe nichts Böses getan!‹«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 2, 36, '»Warum hast du es so eilig, in der Staatsleitung einen andern Weg einzuschlagen? Auch an Ägypten wirst du ebenso enttäuscht werden, wie du an Assyrien enttäuscht worden bist;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 2, 37, 'auch von dort wirst du abziehen, indem du die Hände über dem Kopfe zusammenschlägst; denn der HERR hat die verworfen, auf die du dein Vertrauen gesetzt hast, und so wirst du kein Glück mit ihnen haben.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 3, 1, 'Er fuhr dann fort: »Wenn ein Mann seine Ehefrau entläßt und diese von ihm weggegangen und die Frau eines andern Mannes geworden ist, darf sie dann wieder zu ihm zurückkehren? Würde nicht das betreffende Land dadurch ganz entweiht werden? Du aber hast schon mit vielen Liebhabern Ehebruch getrieben und solltest doch zu mir zurückkehren dürfen?« – so lautet der Ausspruch des HERRN.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 3, 2, '»Erhebe doch deine Augen zu den kahlen Höhen und halte Umschau: wo hast du dich nicht schänden lassen? An den Wegen hast du gesessen und ihnen aufgelauert wie ein Araber in der Wüste und hast das Land entweiht durch deine Buhlerei und deine Verworfenheit!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 3, 3, 'Und ob dir auch die Regenschauer (von mir) vorenthalten wurden und der Spätregen ausblieb, behieltest du doch die Stirn eines buhlerischen Weibes bei und wolltest nicht in dich gehen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 3, 4, 'Freilich, nunmehr rufst du mir zu: ›Mein Vater! Du bist ja der Vertraute meiner Jugend!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 3, 5, 'Wird er denn immerdar grollen, mir’s ewig nachtragen?‹ Ja, so hast du geredet, dabei aber das Böse verübt und es durchgesetzt.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 3, 6, 'Der HERR sprach weiter zu mir in den Tagen des Königs Josia folgendermaßen: »Hast du gesehen, wie Israel, das abtrünnige Weib, es getrieben hat? Sie ist auf jeden hohen Berg und unter jeden dichtbelaubten Baum gegangen und hat dort Ehebruch getrieben.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 3, 7, 'Zwar dachte ich: ›Sie wird zu mir zurückkehren, nachdem sie dies alles verübt‹; aber sie kehrte nicht zurück. Ihre treulose Schwester Juda sah das nun wohl;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 3, 8, 'doch obgleich sie gesehen hatte, daß ich das abtrünnige Weib Israel wegen ihres ehebrecherischen Treibens verstoßen und ihr den Scheidebrief gegeben hatte, nahm ihre treulose Schwester Juda es sich doch nicht zu Herzen, sondern ging hin und trieb ebenfalls Unzucht.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 3, 9, 'So kam es denn, daß sie durch ihre leichtfertige Unzucht das Land entweihte; denn sie trieb Ehebruch mit dem Stein und mit dem Holz.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 3, 10, 'Trotz alledem ist aber ihre treulose Schwester Juda nicht mit ihrem ganzen Herzen zu mir zurückgekehrt, sondern nur mit Heuchelei!« – so lautet der Ausspruch des HERRN.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 3, 11, 'Hierauf sagte der HERR weiter zu mir: »Israel, das abtrünnige Weib, steht weniger schuldig da als die treulose Juda.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 3, 12, 'Gehe hin und rufe diese Worte laut nach Norden hin: ›Kehre zurück (zu mir), Israel, du Abtrünnige!‹ – so lautet der Ausspruch des HERRN –; ›ich will euch nicht mehr zornig anblicken, denn ich bin liebevoll‹ – so lautet der Ausspruch des HERRN –; ›ich will (es dir) nicht ewig nachtragen!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 3, 13, 'Nur erkenne deine Verschuldung, daß du dem HERRN, deinem Gott, die Treue gebrochen und dich immer wieder den Fremden preisgegeben hast unter jedem dichtbelaubten Baum; aber auf meinen Ruf habt ihr nicht gehört!‹« – so lautet der Ausspruch des HERRN.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 3, 14, '»Kehrt um, ihr abtrünnigen Söhne!« – so lautet der Ausspruch des HERRN –; »denn ich habe Herrenrecht über euch und will euch holen, je einen aus jeder Ortschaft und je zwei aus jedem Geschlecht, und will euch nach Zion heimkehren lassen;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 3, 15, 'und ich will euch Hirten nach meinem Herzen geben, die euch mit Einsicht und Besonnenheit weiden sollen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 3, 16, 'Wenn ihr euch dann im Lande vermehrt habt und zahlreich geworden seid in jenen Tagen« – so lautet der Ausspruch des HERRN –, »so wird man nicht mehr sagen: ›O die Lade mit dem Bundesgesetz des HERRN!‹, denn sie wird keinem mehr in den Sinn kommen, und man wird ihrer nicht mehr gedenken und sie nicht mehr vermissen; auch wird niemals wieder eine solche angefertigt werden.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 3, 17, 'In jener Zeit wird man Jerusalem den Thron des HERRN nennen, und es werden dort alle Heidenvölker zusammenströmen um des Namens des HERRN willen [in Jerusalem] und in ihrem Wandel nicht länger dem Starrsinn ihres eigenen bösen Herzens folgen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 3, 18, 'In jenen Tagen wird das Haus Juda mit dem Hause Israel Hand in Hand gehen, und sie werden vereint aus dem Nordlande in das Land heimkehren, das ich euren Vätern zum Erbbesitz gegeben habe.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 3, 19, '»Zwar hatte ich gedacht: ›Wie will ich dich an Sohnes Statt halten und dir ein herrliches Land, den kostbarsten Besitz der ganzen Völkerwelt, verleihen!‹ Und weiter hatte ich gedacht, ihr würdet mich ›Vater‹ nennen und euch von meiner Nachfolge nicht mehr abkehren.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 3, 20, 'Aber ach! Wie ein Weib ihrem Genossen die Treue bricht, so habt auch ihr treulos an mir gehandelt, ihr vom Hause Israel!« – so lautet der Ausspruch des HERRN.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 3, 21, 'Horch! Auf den kahlen Höhen vernimmt man Weinen, das inständige Flehen der Kinder Israel, weil sie auf verkehrtem Wege gewandelt sind und den HERRN, ihren Gott, vergessen haben.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 3, 22, '»Kehrt um, ihr abtrünnigen Söhne: ich will euren Abfall wiedergutmachen!« – »Ja hier sind wir, wir kommen zu dir; denn du, HERR, bist unser Gott.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 3, 23, 'Wahrlich, nur Trug sind die Hügel, das Lärmen auf den Höhen! Wahrlich, nur beim HERRN, unserm Gott, steht das Heil für Israel!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 3, 24, 'Ach, der Schandgötze hat seit unserer Jugend das verschlungen, was unsere Väter erworben hatten, ihr Kleinvieh und ihre Rinder, ihre Söhne und ihre Töchter!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 3, 25, 'So müssen wir uns denn in unsere Schande betten, und unsere Schmach muß uns zudecken! Denn wir haben gegen den HERRN, unsern Gott, gesündigt, wir selbst und unsere Väter, von unserer Jugend an bis auf diesen Tag und haben auf die Stimme des HERRN, unsers Gottes, nicht gehört!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 4, 1, '»Wenn du umkehrst, Israel« – so lautet der Ausspruch des HERRN –, »sollst du zu mir zurückkehren dürfen; und wenn du deine greulichen Götzen mir aus den Augen schaffst, sollst du nicht verstoßen werden;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 4, 2, 'und wenn du ›So wahr der HERR lebt!‹ in Wahrheit, in Treue und Aufrichtigkeit schwörst, sollen die Heidenvölker mit deinem Namen sich segnen und dein Glück sich wünschen!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 4, 3, 'Denn so hat der HERR zu den Männern von Juda und zu den Bewohnern Jerusalems gesprochen: »Brecht euch einen Neubruch und säet nicht in die Dornen hinein!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 4, 4, 'Beschneidet euch für den HERRN und schafft die Vorhaut eurer Herzen weg, ihr Männer von Juda und ihr Bewohner Jerusalems, damit mein Zorn nicht ausbricht wie Feuer und unauslöschlich brennt wegen der Verworfenheit eures ganzen Tuns!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 4, 5, 'Verkündet es in Juda und laßt in Jerusalem die Botschaft ausrufen: »Stoßt in die Posaune im Lande umher! Ruft mit voller Kraft aus und macht bekannt: ›Schart euch zusammen und laßt uns in die festen Städte ziehen!‹');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 4, 6, 'Pflanzt ein Banner auf nach Zion hin, flüchtet euch, ohne Halt zu machen! Denn Unheil lasse ich von Norden her kommen und gewaltige Zerschmetterung.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 4, 7, 'Heraufgestiegen ist schon der Löwe aus seinem Dickicht, und der Völkerwürger ist aufgebrochen, ist ausgezogen aus seiner Wohnstätte, um dein Land zur Wüste zu machen, daß deine Städte in Trümmer sinken, menschenleer werden!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 4, 8, 'Darum gürtet euch Sackleinen um, wehklagt und jammert: »Ach, der lodernde Zorn des HERRN hat sich nicht von uns abgewandt!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 4, 9, '»An jenem Tage« – so lautet der Ausspruch des HERRN – »wird dem Könige und den Fürsten der Mut entschwinden, werden die Priester ratlos sein und die Propheten fassungslos dastehen.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 4, 10, 'Da sagte ich: »Ach, HERR, mein Gott! Wahrlich, arg hast du dieses Volk und Jerusalem getäuscht, als du verhießest: ›Heil soll euch widerfahren!‹, und nun ist das Schwert ihnen gedrungen bis ans Leben!« –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 4, 11, 'In jener Zeit wird man zu diesem Volk und zu Jerusalem sagen: »Ein Glutwind von den kahlen Höhen in der Wüste kommt dahergestürmt auf die Tochter meines Volkes zu, ungeeignet zum Worfeln und ungeeignet zum Sieben des Korns,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 4, 12, 'ein Wind zu scharf, als daß er dazu taugte, kommt, von mir bestellt: nun will ich selbst mit ihnen ins Gericht gehen!« –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 4, 13, 'Sehet, wie Wetterwolken zieht er herauf, und wie der Sturmwind sind seine Kriegswagen, schneller als Adler seine Rosse: wehe uns, wir sind verloren! –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 4, 14, 'Wasche dein Herz vom Bösen rein, Jerusalem, auf daß du Rettung erlangst! Wie lange soll noch dein unheilvolles Sinnen in deinem Inneren wohnen? –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 4, 15, 'Ach, horch! Eine Botschaft kommt von Dan her, eine Unglückskunde vom Gebirge Ephraim!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 4, 16, '»Verkündet es den Völkern, meldet es weiter nach Jerusalem: ›Belagerer kommen aus fernem Lande und erheben ihren Kriegsruf gegen die Städte Judas!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 4, 17, 'Wie Feldhüter stellen sie sich ringsum gegen Jerusalem auf, weil es widerspenstig gegen mich gewesen ist!‹« – so lautet der Ausspruch des HERRN. –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 4, 18, 'Dein Wandel und dein ganzes Tun haben dir solches Unheil eingetragen: deiner Verworfenheit verdankst du dies, daß es so bitterweh ist, ja daß es dir bis ans Leben geht. –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 4, 19, 'O meine Brust, meine Brust! Mir ist so angst! O ihr Wände meines Herzens! Mein Inneres ist mir in wildem Aufruhr: ich kann nicht schweigen! Denn Posaunenschall vernimmst du, meine Seele, das Getöse des Krieges.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 4, 20, 'Zerstörung über Zerstörung wird gemeldet, denn verheert ist das ganze Land! Urplötzlich sind meine Hütten zerstört, in einem Augenblick meine Zelte!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 4, 21, 'Wie lange noch soll ich Paniere sehen, Posaunenschall vernehmen? –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 4, 22, 'Ach, verblendet ist mein Volk: mich kennen sie nicht! Törichte Kinder sind sie und ohne Einsicht: klug sind sie zum Bösestun, aber auf das Tun des Guten verstehen sie sich nicht. –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 4, 23, 'Ich blicke die Erde an: ach, sie ist wüst und öde! und zum Himmel empor: sein Licht ist verschwunden!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 4, 24, 'Ich blicke die Berge an: ach, sie beben, und alle Hügel schwanken!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 4, 25, 'Ich blicke umher: ach, kein Mensch ist da, und alle Vögel des Himmels sind entflohen!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 4, 26, 'Ich blicke umher: ach, das Fruchtgefilde (Juda) ist eine Wüste, und alle seine Städte sind zerstört: nach dem Willen des HERRN, infolge der Glut seines Zorns! –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 4, 27, 'Denn so hat der HERR gesprochen: »Zur Wüste soll das ganze Land werden, doch seine völlige Vernichtung will ich nicht herbeiführen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 4, 28, 'Darob trauert die Erde, und der Himmel droben hüllt sich in Schwarz, weil ich (das) ausgesprochen und beschlossen habe; und ich lasse es mich nicht gereuen und gehe nicht davon ab.« –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 4, 29, 'Vor dem Ruf »Reiter und Bogenschützen!« ist das ganze Stadtvolk auf der Flucht; in die Dickichte haben sie sich begeben und die Felsen erklommen: jede Ortschaft steht verlassen da, und kein Mensch ist darin wohnen geblieben.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 4, 30, 'Du aber, vergewaltigte (Stadt), was willst du tun? Magst du dich auch in Purpur kleiden, magst du dich mit Goldgeschmeide putzen, magst du deine Augenränder mit Schminke umzeichnen: vergebens machst du dich schön! Die Liebhaber haben dich satt, trachten dir nach dem Leben!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 4, 31, 'Ach! Geschrei höre ich wie von einem Weibe in Kindesnöten, Angstrufe wie von einer Frau, die zum erstenmal Mutter wird: das Geschrei der Tochter Zion, die da aufstöhnt, ihre Hände flehend ausbreitet: »Wehe mir! Ach, erschöpft ist meine Seele, eine Beute der Mörder!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 5, 1, 'Streift in den Straßen Jerusalems umher und seht euch um! Erkundigt euch und sucht auf den Plätzen der Stadt, ob ihr jemand findet, ob einer da ist, der Recht übt, der auf Treue hält: dann will ich ihr vergeben.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 5, 2, 'Aber wenn sie auch sagen: »So wahr der HERR lebt!«, so schwören sie darum doch falsch.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 5, 3, 'Sind denn deine Augen, HERR, nicht auf Treue gerichtet? Du hast sie zwar geschlagen, aber es hat ihnen nicht wehe getan; du hast sie der Vernichtung preisgegeben, aber sie haben keine Zucht annehmen wollen: sie haben ihr Angesicht härter gemacht als Felsgestein und eine Umkehr von sich gewiesen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 5, 4, 'Da dachte ich: »Nur die kleinen Leute sind so; die benehmen sich töricht, weil sie den Weg des HERRN, das Recht ihres Gottes nicht kennen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 5, 5, 'Ich will doch einmal zu den Großen gehen und mit ihnen reden; denn die müssen doch den Weg des HERRN, das Recht ihres Gottes kennen.« Doch sie haben insgesamt das Joch zerbrochen, die Bande zerrissen!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 5, 6, 'Darum schlägt sie der Löwe aus dem Walde nieder, überwältigt sie der Steppenwolf; der Panther lauert ihnen auf vor ihren Städten: jeder, der aus ihnen hinausgeht, wird zerrissen; denn zahlreich sind ihre Übertretungen, vielfältig ihre Abfallsünden.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 5, 7, '»Weshalb sollte ich dir verzeihen? Deine Söhne haben mich verlassen und schwören bei Nichtgöttern; und obwohl ich sie den Bund hatte beschwören lassen, haben sie doch Ehebruch begangen und sind im Hurenhause heimisch geworden.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 5, 8, 'Wie wohlgenährte Rosse schweifen sie umher: ein jeder wiehert nach dem Eheweibe des andern.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 5, 9, 'Sollte ich so etwas ungestraft lassen?« – so lautet der Ausspruch des HERRN –, »oder sollte an einem solchen Volk meine Seele sich nicht rächen?«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 5, 10, 'Steigt auf ihre Mauern hinauf und richtet Verwüstungen an, doch vernichtet sie nicht völlig! Haut ihre Ranken ab; denn dem HERRN gehören sie nicht (mehr) an.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 5, 11, '»Ach, sie haben gar treulos an mir gehandelt, das Haus Israel und das Haus Juda!« – so lautet der Ausspruch des HERRN.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 5, 12, 'Sie haben den HERRN verleugnet und gesagt: »Es ist nichts mit ihm, und kein Unglück wird über uns kommen: weder Schwert noch Hungersnot werden wir zu sehen bekommen!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 5, 13, 'Und die Propheten? Die sind für den Wind; denn das Wort (des HERRN) ist nicht in ihnen: möge es ihnen selbst so ergehen!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 5, 14, 'Darum hat Gott, der HERR der Heerscharen, so gesprochen: »Weil ihr solche Reden führt, will ich nunmehr meine Worte in deinem Munde zu Feuer machen und dieses Volk zu Brennholz, daß es sie verzehren soll!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 5, 15, '»Wisset wohl: ich lasse ein Volk aus der Ferne über euch kommen, ihr vom Hause Israel!« – so lautet der Ausspruch des HERRN –; »ein Volk von unverwüstlicher Kraft ist es, ein Volk von uraltem Stamm, ein Volk, dessen Sprache du nicht kennst und dessen Rede du nicht verstehst.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 5, 16, 'Sein Köcher ist wie ein offenes Grab: allesamt sind sie Kriegshelden.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 5, 17, 'Es wird deine Ernte und dein Brotkorn verzehren, verzehren deine Söhne und Töchter, verzehren dein Kleinvieh und deine Rinder, verzehren deinen Weinstock und deinen Feigenbaum; deine festen Städte, auf die du dein Vertrauen setzt, wird es mit dem Schwert zerstören.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 5, 18, '»Doch auch in jenen Tagen« – so lautet der Ausspruch des HERRN – »will ich euch nicht völlig vernichten.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 5, 19, 'Aber wenn ihr alsdann fragt: ›Wofür hat der HERR, unser Gott, uns dies alles widerfahren lassen?‹, so sollst du ihnen antworten: ›Gleichwie ihr mich verlassen und fremden Göttern im eigenen Lande gedient habt, ebenso sollt ihr nun Fremden dienstbar sein in einem Lande, das nicht euch gehört!‹«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 5, 20, 'Verkündet dies im Hause Jakob und macht es in Juda bekannt mit den Worten:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 5, 21, '»Hört doch dies, ihr törichtes Volk voll Unverstand, die ihr Augen habt und nicht seht, die ihr Ohren habt und nicht hört!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 5, 22, 'Mich wollt ihr nicht fürchten« – so lautet der Ausspruch des HERRN – »und vor mir nicht zittern? der ich dem Meere den Sand zur Grenze gesetzt habe als ewige Schranke, die es nicht überschreiten darf, so daß seine Wogen, wenn sie auch branden, doch ohnmächtig sind und, wenn sie auch brausen, doch nicht ungebührlich vordringen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 5, 23, 'Aber dieses Volk besitzt ein trotziges und widerspenstiges Herz; sie sind abgefallen und davongegangen');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 5, 24, 'und haben niemals in ihrem Herzen gedacht: ›Laßt uns doch den HERRN, unsern Gott, fürchten, der den Regen spendet, Frühregen wie Spätregen zu rechter Zeit, der die festbestimmten Wochen der Erntezeit uns zugute einhält!‹');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 5, 25, 'Eure Verschuldungen haben das unmöglich gemacht und eure Sünden euch um den Segen gebracht.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 5, 26, 'Denn unter meinem Volke gibt es Gottlose, die auf der Lauer liegen, wie Vogelfänger sich ducken: sie stellen Fallen auf und treiben Menschenfang.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 5, 27, 'Wie ein Käfig sich mit Vögeln füllt, so füllen sich ihre Häuser mit ungerechtem Gut; auf solche Weise sind sie hoch gekommen und reich geworden;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 5, 28, 'fett sind sie geworden und feist, ja, ihre Verworfenheit überschreitet jedes Maß. An das Recht halten sie sich nicht; für die Sache der Waisen treten sie nicht ein, um sie zum Siege zu führen, und der Rechtssache der Armen nehmen sie sich nicht an.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 5, 29, 'Sollte ich so etwas ungestraft lassen?« – so lautet der Ausspruch des HERRN –, »oder sollte meine Seele sich an einem solchen Volk nicht rächen?«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 5, 30, 'Entsetzliche und greuliche Dinge haben sich im Lande zugetragen:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 5, 31, 'die Propheten prophezeien als Lügendiener, und die Priester schalten mit ihnen Hand in Hand, und mein Volk hat es gern so! Was werdet ihr aber tun, wenn es damit zu Ende geht?');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 6, 1, 'Flüchtet, ihr Benjaminiten, aus Jerusalem hinweg, stoßt zu Thekoa in die Trompete und richtet ein Sturmzeichen über Beth-Kerem auf! Denn Unheil droht von Norden her, und zwar eine gewaltige Zerschmetterung:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 6, 2, 'die Liebliche und Verwöhnte, die Tochter Zion, will ich vertilgen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 6, 3, 'Auf sie zu kommen Hirten gezogen mitsamt ihren Herden, schlagen Zelte ringsum gegen sie auf und weiden ein jeder sein Teil ab.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 6, 4, '»Weihet euch zum Kampf gegen sie! Auf, wir wollen noch am Mittag hinaufziehen! Wehe uns, der Tag neigt sich schon, denn die Abendschatten dehnen sich schon lang!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 6, 5, 'Auf, laßt uns bei Nacht hinaufziehen und ihre Paläste zerstören!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 6, 6, 'Denn so hat der HERR der Heerscharen gesprochen: ›Fället die Bäume dort und führt einen Wall gegen Jerusalem auf!‹« – »Das ist die Stadt, die gestraft werden soll: überall herrscht Gewalttat in ihrem Innern!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 6, 7, 'Wie ein Brunnen sein Wasser sprudeln läßt, so läßt sie ihre Bosheit sprudeln: von Frevel und Unrecht hört man in ihr; Wunden und Striemen treten mir allezeit (in ihr) vor Augen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 6, 8, 'Laß dich warnen, Jerusalem, damit mein Herz sich nicht von dir losreißt, damit ich dich nicht zur Wüste mache, zu einem unbewohnten Lande!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 6, 9, 'So hat der HERR der Heerscharen gesprochen: »Gründliche Nachlese wie am Weinstock wird man am Überrest Israels halten: lege deine Hand immer wieder an, wie der Weingärtner an die Ranken!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 6, 10, 'Ja, an wen soll ich meine Worte noch richten und wem ins Gewissen reden, daß sie darauf hören? Ach, ihr Ohr ist unbeschnitten, so daß sie nichts vernehmen können! Ach, das Wort des HERRN ist ihnen zum Spott geworden, so daß sie kein Gefallen daran haben!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 6, 11, 'Ja, ich bin mit der Zornglut des HERRN erfüllt, nur mit Mühe vermag ich sie zurückzuhalten! »So laß sie sich denn über die Kinder auf der Straße ergießen und über die Schar der Jünglinge allzumal! Denn Männer wie Weiber sollen von ihr getroffen werden, Alte mitsamt den Vollbetagten;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 6, 12, 'und ihre Häuser sollen an andere übergehen, die Äcker und die Weiber allesamt, wenn ich meine Hand ausstrecke gegen die Bewohner des Landes!« – so lautet der Ausspruch des HERRN.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 6, 13, 'Denn vom Jüngsten bis zum Ältesten sind sie alle gierig nach Gewinn, und vom Propheten bis zum Priester gehen sie alle mit Falschheit um;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 6, 14, 'die schwere Wunde meines Volkes wollen sie leichtfertig obenhin heilen, indem sie verheißen: »Heil, Heil!«, wo doch kein Heil vorhanden ist.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 6, 15, 'Beschämt werden sie dastehen müssen, weil sie Greuel verübt haben; und doch schämen sie sich keineswegs, und Erröten kennen sie nicht. »Darum werden sie fallen, wenn alles fällt: zur Zeit, wo ich sie zur Rechenschaft ziehe, werden sie stürzen!« – so hat der HERR gesprochen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 6, 16, 'So hat der HERR gesprochen: »Tretet hin an die Wege und haltet Umschau und forscht nach den Pfaden der Vorzeit, welches der Weg des Heils sei, und dann wandelt auf ihm, so werdet ihr Ruhe finden für eure Seelen!« Aber sie haben geantwortet: »Nein, wir wollen auf ihm nicht wandeln!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 6, 17, '»Dann habe ich Wächter über euch bestellt (und euch gemahnt): Merkt auf den Schall der Posaune! Aber sie haben geantwortet: ›Nein, wir wollen auf ihn nicht merken!‹');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 6, 18, 'Darum höret, ihr Völker, und gib wohl acht, du Gemeinde, was mit ihnen geschehen wird!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 6, 19, 'Vernimm du es, Erde! Jetzt will ich Unheil über dies Volk bringen, den Lohn ihrer (bösen) Anschläge! Denn auf meine Worte haben sie nicht geachtet, und meine Weisung – die haben sie verworfen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 6, 20, 'Wozu soll mir da der Weihrauch aus Saba dienen und das kostbare Würzrohr aus fernem Lande? Eure Brandopfer sind mir nicht wohlgefällig und eure Schlachtopfer mir nicht angenehm!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 6, 21, 'Darum hat der HERR so gesprochen: »Nunmehr lege ich diesem Volk Steine des Anstoßes in den Weg, daß Väter und Söhne zugleich darüber straucheln, daß ein Nachbar mit dem andern zugrunde geht!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 6, 22, 'So hat der HERR gesprochen: »Gebt acht! Es kommt ein Volk vom Nordlande her, und ein gewaltiges Heer setzt sich in Bewegung vom äußersten Ende der Erde her.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 6, 23, 'Bogen und Wurfspieß führen sie, grausam sind sie und ohne Erbarmen; ihr Lärmen ist wie Meeresbrausen, und auf Rossen reiten sie, gerüstet wie ein Mann zum Kampf gegen dich, Tochter Zion!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 6, 24, '»Wir haben die Kunde von ihm vernommen: die Hände sind uns schlaff herabgesunken, Angst hat uns erfaßt, Zittern wie ein Weib in Kindesnöten!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 6, 25, 'Geht nicht aufs Feld hinaus und wandert nicht auf der Landstraße; denn da droht euch das Schwert des Feindes – Grauen ringsum!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 6, 26, 'O Tochter meines Volkes, umgürte dich mit dem Sackleinen und wälze dich in der Asche! Stelle Trauer an wie um den einzigen Sohn, eine bittere Wehklage; denn jählings wird der Verwüster über uns kommen!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 6, 27, '»Zum Prüfer habe ich dich bei meinem Volk bestellt, zum Metallprüfer, damit du ihren Wandel erkennen lernst und prüfst.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 6, 28, 'Allesamt sind sie widerspenstige Empörer, gehen als Verleumder umher, sind gemeines Kupfer und Eisen, allesamt schändliche Bösewichter!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 6, 29, 'Der Blasebalg hat wohl geschnaubt, aber aus dem Feuer ist nur Blei herausgekommen: vergeblich ist alles Schmelzen gewesen, die Schlacken haben sich nicht ausscheiden lassen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 6, 30, '›Verworfenes Silber‹ nennt man sie nun, denn der HERR hat sie verworfen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 7, 1, 'Das Wort, das vom HERRN an Jeremia ergangen ist, lautet folgendermaßen:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 7, 2, '»Stelle dich auf im Tor des Hauses des HERRN und halte dort mit lauter Stimme folgende Ansprache: Vernehmt das Wort des HERRN, ihr Judäer alle, die ihr durch diese Tore eintretet, um den HERRN anzubeten!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 7, 3, 'So hat der HERR der Heerscharen, der Gott Israels, gesprochen: Bessert euren Wandel und euer ganzes Tun, so will ich euch an diesem Orte wohnen lassen!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 7, 4, 'Setzt euer Vertrauen nicht auf Trugworte, daß ihr sagt: ›Der Tempel des HERRN, der Tempel des HERRN, der Tempel des HERRN ist dies!‹');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 7, 5, 'Denn nur, wenn ihr ernstlich euren Wandel und euer ganzes Tun bessert, wenn ihr wirklich das Recht bei den Streitigkeiten des einen mit dem anderen gelten laßt,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 7, 6, 'wenn ihr Fremdlinge, Waisen und Witwen nicht bedrückt und kein unschuldiges Blut an diesem Orte vergießt und nicht anderen Göttern nachlauft zu eurem eigenen Schaden:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 7, 7, 'nur dann will ich euch an diesem Orte wohnen lassen, in diesem Lande, das ich euren Vätern gegeben habe, von Ewigkeit bis in Ewigkeit.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 7, 8, 'Aber seht: ihr verlaßt euch auf Trugworte, die keinen Wert haben!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 7, 9, 'Nicht wahr? Stehlen, morden und Ehebruch treiben, falsch schwören, dem Baal opfern und anderen Göttern nachlaufen, die euch nichts angehen!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 7, 10, 'Und dann kommt ihr her und tretet vor mein Angesicht in diesem Hause, das nach meinem Namen genannt ist, und sagt: ›Wir sind errettet!‹, um dann alle jene Greuel weiter zu verüben.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 7, 11, 'Ist denn dieses Haus, das meinen Namen trägt, in euren Augen zu einer Räuberhöhle geworden? Ja wahrlich, auch ich sehe es so an!« – so lautet der Ausspruch des HERRN.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 7, 12, '»Geht doch einmal nach meiner heiligen Stätte, die in Silo war, wo ich meinen Namen zu Anfang habe wohnen lassen, und seht, was ich aus ihr wegen der Bosheit meines Volkes Israel gemacht habe!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 7, 13, 'Nun aber, weil ihr ganz die gleichen Taten verübt habt« – so lautet der Ausspruch des HERRN – »und, wiewohl ich unaufhörlich und immer wieder zu euch geredet habe, dennoch nicht gehört und, obschon ich euch zugerufen, dennoch nicht geantwortet habt:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 7, 14, 'so will ich mit diesem Hause, das meinen Namen trägt und auf das ihr euer Vertrauen setzt, und mit der Wohnstätte, die ich euch und euren Vätern gegeben habe, ebenso verfahren, wie ich mit Silo verfahren bin:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 7, 15, 'verstoßen will ich euch von meinem Angesicht hinweg, wie ich alle eure Brüder, die gesamte Nachkommenschaft Ephraims, bereits verstoßen habe!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 7, 16, '»Du aber, lege keine Fürbitte für dieses Volk ein, laß kein Flehen und kein Gebet für sie laut werden und dringe nicht in mich; denn ich würde dich doch nicht erhören.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 7, 17, 'Siehst du denn nicht, was sie in den Ortschaften Judas und auf den Straßen Jerusalems treiben?');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 7, 18, 'Die Kinder lesen Holz zusammen, und die Väter zünden das Feuer an; die Frauen aber kneten den Teig, um Kuchen für die Himmelskönigin zu backen; und Trankopfer spenden sie fremden Göttern, um mir wehe zu tun.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 7, 19, 'Indes – tun sie mir damit wehe?« – so lautet der Ausspruch des HERRN –, »nicht vielmehr sich selbst zu ihrer offenkundigen Beschämung?«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 7, 20, 'Darum hat Gott der HERR so gesprochen: »Wahrlich, mein Zorn und mein Grimm wird sich über diesen Ort ergießen, über die Menschen und über das Vieh, über die Bäume des Feldes und die Früchte des Erdbodens, und er wird unauslöschlich brennen!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 7, 21, 'So hat der HERR der Heerscharen, der Gott Israels, gesprochen: »Fügt immerhin eure Brandopfer zu euren Schlachtopfern hinzu und eßt das Fleisch davon!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 7, 22, 'Denn ich habe euren Vätern damals, als ich sie aus Ägypten wegführte, nichts von Brandopfern und Schlachtopfern gesagt und geboten,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 7, 23, 'sondern habe ihnen dies Gebot gegeben: ›Gehorcht meinen Weisungen, so will ich euer Gott sein, und ihr sollt mein Volk sein; und haltet den ganzen Weg inne, den ich euch gebiete, damit es euch wohlergehe!‹');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 7, 24, 'Aber sie haben nicht gehorcht und mir kein Gehör geschenkt, sondern sind nach den Ratschlägen, nach dem Starrsinn ihres bösen Herzens gewandelt, indem sie mir den Rücken und nicht mehr das Angesicht zukehrten.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 7, 25, 'Wohl habe ich seit dem Tage, als eure Väter aus Ägypten auszogen, bis auf den heutigen Tag alle meine Knechte, die Propheten, tagtäglich unermüdlich früh und spät zu euch gesandt,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 7, 26, 'aber sie haben mir nicht gehorcht und mir kein Gehör geschenkt, sondern sich halsstarrig gezeigt und es noch ärger getrieben als ihre Väter.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 7, 27, 'Wenn du ihnen nun auch dies alles in deiner Rede vorhältst, so werden sie doch nicht auf dich hören; und wenn du ihnen zurufst, werden sie dir keine Antwort geben.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 7, 28, 'So sage denn zu ihnen: ›Dies ist das Volk, das auf die Stimme des HERRN, seines Gottes, nicht hört und sich nicht warnen läßt; dahin ist die Treue und verschwunden aus ihrem Munde!‹«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 7, 29, 'Schere deine Kopfzier ab, Tochter Zion, und wirf es weg, und stimme ein Klagelied auf den kahlen Höhen an! Denn verworfen hat der HERR und verstoßen das Geschlecht, dem er zürnt!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 7, 30, '»Denn die Kinder Juda haben getan, was mir mißfällt« – so lautet der Ausspruch des HERRN –: »sie haben ihre scheußlichen Götzen in dem Hause, das meinen Namen trägt, aufgestellt, um es zu entweihen,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 7, 31, 'und haben die Opferstätte des Thopheths im Tale Ben-Hinnom angelegt, um ihre Söhne und Töchter dort als Brandopfer darzubringen, was ich ihnen niemals geboten habe und was mir nie in den Sinn gekommen ist.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 7, 32, 'Darum gebt acht: es kommt die Zeit« – so lautet der Ausspruch des HERRN –, »da wird man nicht mehr vom Thopheth und vom Tal Ben-Hinnom reden, sondern vom Würgetal, und man wird im Thopheth begraben, weil sonst kein Platz mehr da ist.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 7, 33, 'Dann werden die Leichname dieses Volkes den Vögeln des Himmels und den Tieren des Feldes zum Fraß dienen, ohne daß jemand sie verscheucht;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 7, 34, 'und ich werde in den Ortschaften Judas und auf den Straßen Jerusalems aller lauten Freude und Fröhlichkeit, allem Jubel des Bräutigams und allem Brautgesang ein Ende machen; denn zur Wüste soll das Land werden!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 8, 1, '»Zu jener Zeit« – so lautet der Ausspruch des HERRN – »wird man die Gebeine der Könige von Juda und die Gebeine seiner Fürsten, die Gebeine der Priester und Propheten und (überhaupt) die Gebeine der Bewohner Jerusalems aus ihren Gräbern herausholen');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 8, 2, 'und wird sie hinbreiten vor der Sonne und dem Mond und vor dem ganzen Heer der Gestirne, welche sie geliebt und verehrt haben und denen sie nachgelaufen sind, die sie befragt und angebetet haben; man wird sie dann nicht wieder sammeln noch begraben, nein, zu Dünger sollen sie auf offenem Felde werden!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 8, 3, 'Und der ganze Rest, der von diesem bösen Geschlecht noch übriggeblieben ist, wird lieber sterben als leben wollen an allen Orten, wohin ich sie verstoßen haben werde« – so lautet der Ausspruch Gottes, des HERRN der Heerscharen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 8, 4, '»Sage zu ihnen auch: So hat der HERR gesprochen: Fällt jemand wohl hin und steht nicht wieder auf? Oder wendet sich jemand ab (auf einen falschen Weg) und kehrt nicht wieder um?');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 8, 5, 'Warum hat sich denn dieses Volk zu Jerusalem abgewandt in immerwährender Abkehr? Sie halten fest am Irrtum und wollen durchaus nicht umkehren.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 8, 6, 'Ich habe hingehorcht und gelauscht: sie reden die Unwahrheit; kein einziger bereut seine Schlechtigkeit, daß er sagte: ›Was habe ich getan!‹ Nein, jeder stürmt dahin in seinem Jagen wie ein in die Schlacht stürmendes Roß.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 8, 7, 'Sogar der Storch oben am Himmel kennt seine bestimmten Zeiten, auch die Turteltaube, die Schwalbe und der Kranich halten die Zeit ihrer Wiederkehr ein; aber mein Volk weiß nichts von der Rechtsordnung des HERRN!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 8, 8, 'Wie könnt ihr nur sagen: »Wir sind weise, wir sind ja im Besitz des göttlichen Gesetzes!« Ja freilich! Aber zur Lüge hat es der Lügengriffel der Schriftgelehrten gemacht.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 8, 9, 'Beschämt werden die Weisen dastehen, werden bestürzt sein und sich gefangen sehen; sie haben ja das Wort des HERRN verworfen: welcherlei Weisheit besitzen sie da noch?');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 8, 10, '»Darum will ich ihre Weiber anderen geben, ihre Äcker Eroberern; denn vom Jüngsten bis zum Ältesten sind sie alle gierig nach Gewinn, vom Propheten bis zum Priester gehen sie alle mit Lug und Trug um.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 8, 11, 'Die schwere Wunde der Tochter meines Volkes wollen sie leichtfertig obenhin heilen, indem sie verheißen: ›Heil, Heil!‹, wo doch kein Heil vorhanden ist.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 8, 12, 'Beschämt werden sie dastehen müssen, weil sie Greuel verübt haben; und doch schämen sie sich keineswegs und Erröten kennen sie nicht mehr. Darum werden sie fallen, wenn alles fällt: zur Zeit, da ich sie zur Rechenschaft ziehe, werden sie stürzen!« – so hat der HERR gesprochen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 8, 13, '»Will ich Lese bei ihnen halten« – so lautet der Ausspruch des HERRN –, »so sind keine Trauben am Weinstock und keine Feigen am Feigenbaum, und das Laub ist verwelkt. So will ich denn Leute für sie bestellen, die sie wegräumen sollen!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 8, 14, 'Wozu sitzen wir müßig da? Scharet euch zusammen und laßt uns in die festen Städte flüchten und dort umkommen! Denn der HERR, unser Gott, will unsern Untergang und hat uns Giftwasser zu trinken gegeben, weil wir gegen den HERRN gesündigt haben.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 8, 15, 'Wozu hoffen wir noch auf Rettung? Es wird ja doch nichts Gutes! Wozu auf eine Zeit der Heilung? Es gibt ja doch nur Schrecken!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 8, 16, 'Von Dan her vernimmt man schon das Schnauben seiner Rosse, vom lauten Gewieher seiner Hengste erbebt das ganze Land! Ja, sie kommen heran und verzehren das Land und seine Fülle, die Städte samt ihren Bewohnern.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 8, 17, '»Denn gebt acht: ich lasse Schlangen gegen euch los, Giftschlangen, gegen welche es keine Beschwörung gibt: die sollen euch stechen!« – so lautet der Ausspruch des HERRN.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 8, 18, 'Schwerer Kummer ist über mich gekommen, krank ist mein Herz in mir!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 8, 19, 'Horch! Laut erschallt das Wehgeschrei der Tochter meines Volkes aus fernem Lande: »Ist denn der HERR nicht in Zion? Ist sein König nicht drinnen?« »Warum haben sie mich erbittert durch ihren Bilderdienst, durch die nichtigen Götzen des Auslands?«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 8, 20, '»Vorüber ist die Ernte, zu Ende die Obstlese, doch wir haben keine Rettung erlangt!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 8, 21, 'Über den Zusammenbruch der Tochter meines Volkes bin ich gebrochen; ich gehe trauernd einher, Entsetzen hat mich ergriffen!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 8, 22, 'Gibt es denn keinen Balsam mehr in Gilead, und ist kein Arzt mehr dort? Ach, warum ist der Tochter meines Volkes noch keine Heilung zuteil geworden!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 8, 23, 'O daß doch mein Haupt zu Wasser würde und meine Augen zum Tränenquell! Dann wollte ich Tag und Nacht weinen um die Erschlagenen der Tochter meines Volkes!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 9, 1, 'O hätte ich doch eine Wanderer-Herberge fern in der Wüste, so wollte ich mein Volk verlassen und von ihnen weggehen! Denn sie sind allesamt Ehebrecher, eine Gesellschaft von Treulosen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 9, 2, '»Sie spannen ihre Zunge wie einen Bogen: mit Lüge und nicht durch Wahrhaftigkeit schalten sie als Herren im Lande; denn von einer Bosheit schreiten sie zur andern fort, mich aber kennen sie nicht!« – so lautet der Ausspruch des HERRN.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 9, 3, 'Seid auf der Hut, ein jeder vor seinem Freunde, und schenkt auch keinem Bruder Vertrauen! Denn jeder Bruder übt Lug und Trug, und jeder Freund geht auf Verleumdung aus;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 9, 4, 'sie hintergehen einer den andern, und keiner redet ein wahres Wort; sie haben ihre Zunge an Lügenreden gewöhnt und mühen sich ab, verkehrt zu handeln, können nicht anders:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 9, 5, '»Gewalttat über Gewalttat, Arglist über Arglist! Sie wollen mich nicht kennen!« – so lautet der Ausspruch des HERRN.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 9, 6, 'Darum hat der HERR der Heerscharen so gesprochen: »Gib acht: ich will sie schmelzen und läutern! Denn wie sollte ich anders mit der Tochter meines Volks verfahren?');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 9, 7, 'Ein todbringender Pfeil ist ihre Zunge, Trug sind die Worte ihres Mundes; man redet freundlich mit seinem Nächsten, aber im Herzen stellt man ihm eine Falle.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 9, 8, 'Sollte ich so etwas bei ihnen ungestraft lassen?« – so lautet der Ausspruch des HERRN –, »oder sollte ich mich an einem solchen Volk nicht rächen?«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 9, 9, 'Um die Berge will ich ein Weinen und eine Wehklage erheben und um die Auen der Trift ein Trauerlied! Denn sie sind verödet, so daß niemand sie durchwandert und man die Stimmen der Herden nicht mehr vernimmt; die Vögel des Himmels und das Wild – alles ist entflohen, ist weggezogen!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 9, 10, '»Auch Jerusalem will ich zu Steinhaufen machen, zur Behausung der Schakale; und die Ortschaften Judas verwandle ich in eine Einöde, in der kein Mensch mehr wohnt!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 9, 11, 'Wer ist ein so weiser Mann, daß er dies verstehen mag? Und zu wem hat der Mund des HERRN geredet, daß er es kundtue, warum das Land zugrunde gegangen ist und verödet daliegt wie die Wüste, so daß niemand es durchwandert?');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 9, 12, 'Der HERR hat gesagt: »Weil sie mein Gesetz, das ich ihnen vorgelegt hatte, unbeachtet gelassen und meinen Weisungen nicht gehorcht und nicht nach ihnen gelebt haben,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 9, 13, 'vielmehr dem Starrsinn ihres eigenen Herzens gefolgt und den Baalen nachgelaufen sind, wie sie es von ihren Vätern gelernt hatten;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 9, 14, 'darum« – so hat der HERR der Heerscharen, der Gott Israels, gesprochen: »Nunmehr will ich sie, dieses Volk da, mit Wermut speisen und ihnen Giftwasser zu trinken geben');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 9, 15, 'und will sie unter die Heidenvölker zerstreuen, die weder sie noch ihre Väter gekannt haben, und will das Schwert hinter ihnen her senden, bis ich sie vertilgt habe!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 9, 16, 'So hat der HERR der Heerscharen gesprochen: »Merkt auf und ruft die Klageweiber herbei, daß sie kommen, und schickt zu den weisen Frauen, daß sie herkommen');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 9, 17, 'und eilends ein Klagelied über uns anstimmen, damit unsere Augen in Tränen zerfließen und unsere Wimpern von Zähren triefen!« –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 9, 18, 'Ach horch! Eine Wehklage vernimmt man von Zion her: »Wehe, wie sind wir vergewaltigt und schmählich in Schande geraten! Ach, wir müssen das Land verlassen! Ach, man hat unsere Wohnungen niedergerissen!« –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 9, 19, 'Ach hört, ihr Frauen, das Wort des HERRN, und euer Ohr vernehme das Wort seines Mundes, und lehrt eure Töchter das Klagelied und eine jede die andere den Grabgesang:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 9, 20, '»Ach, der Tod ist in unsere Fenster eingestiegen, in unsere Paläste eingedrungen, hat die Kinder von der Straße weggerafft, die Jünglinge von den Marktplätzen!« –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 9, 21, 'Rede: »So lautet der Ausspruch des HERRN: Es liegen die Leichen der Menschen da wie Dünger auf dem Felde und wie Ährenbündel hinter dem Schnitter, ohne daß jemand sie aufliest!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 9, 22, 'So hat der HERR gesprochen: »Nicht rühme sich der Weise seiner Weisheit, und der Starke rühme sich nicht seiner Stärke, nicht rühme sich der Reiche seines Reichtums!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 9, 23, 'Sondern wer sich rühmen will, der rühme sich dessen, daß er Einsicht besitzt und von mir erkennt, daß ich, der HERR, es bin, der Gnade, Recht und Gerechtigkeit auf Erden übt; denn an solchen habe ich Wohlgefallen« – so lautet der Ausspruch des HERRN.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 9, 24, '»Gebt acht: es kommt die Zeit« – so lautet der Ausspruch des HERRN –, »da werde ich alle, die, obgleich beschnitten, doch unbeschnitten sind, zur Rechenschaft ziehen:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 9, 25, 'Ägypten und Juda, Edom, die Ammoniter und Moabiter und alle, die sich das Haar an den Schläfen stutzen, die in der Wüste wohnen. Denn wohl sind alle Heidenvölker unbeschnitten, aber das ganze Haus Israel ist unbeschnitten am Herzen!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 10, 1, 'Vernehmt das Wort, das der HERR euch verkünden läßt, ihr vom Hause Israel!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 10, 2, 'So hat der HERR gesprochen: »Gewöhnt euch nicht an den Weg der Heidenvölker und laßt euch nicht durch die Zeichen am Himmel erschrecken, weil die Heidenvölker vor ihnen erschrecken!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 10, 3, 'Denn der Gottesdienst der Heidenvölker ist nichts als Wahn: ein Stück Holz ist es ja, das man im Walde gehauen hat, ein Werk von Künstlerhänden, mit dem Schnitzmesser hergestellt.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 10, 4, 'Mit Silber und Gold verziert er es, mit Nägeln und Hämmern befestigt man es, damit es nicht wackelt.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 10, 5, 'Wie eine Vogelscheuche im Gemüsegarten stehen sie da und können nicht reden; man muß sie tragen, denn sie können nicht gehen. Fürchtet euch nicht vor ihnen, denn sie können kein Unheil anrichten, aber auch Gutes zu tun steht nicht in ihrer Macht.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 10, 6, 'Dir, o HERR, ist niemand gleich! Groß bist du, und groß ist dein Name ob deiner Kraft:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 10, 7, 'wer sollte dich nicht fürchten, du König der Völker? Ja, dir gebührt dies; denn unter allen Weisen der Heidenvölker und in all ihren Königreichen ist keiner dir gleich,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 10, 8, 'sondern allesamt sind sie dumm und töricht: die ganze Weisheit der Götzen ist – Holz,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 10, 9, 'dünngehämmertes Silber, das man aus Tharsis geholt hat, und Gold aus Uphas, eine Arbeit des Bildschnitzers und der Hände des Goldschmieds, blauer und roter Purpur ist ihr Gewand: Machwerke kunstfertiger Meister sind sie allesamt.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 10, 10, 'Aber der HERR ist Gott in Wahrheit, ist der lebendige Gott und ein ewiger König; vor seinem Zürnen erbebt die Erde, und seinen Grimm vermögen die Völker nicht zu ertragen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 10, 11, '[So sollt ihr von ihnen sagen: »Die Götter, die den Himmel und die Erde nicht geschaffen haben, diese werden von der Erde und unter diesem Himmel hinweg verschwinden.«]');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 10, 12, 'Der HERR ist es, der die Erde durch seine Kraft geschaffen, den Erdkreis durch seine Weisheit fest gegründet und durch seine Einsicht den Himmel ausgespannt hat.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 10, 13, 'Wenn er beim Schall des Donners Wasserrauschen am Himmel entstehen läßt und Gewölk vom Ende der Erde heraufführt, wenn er Blitze beim Regen schafft und den Sturmwind aus seinen Vorratskammern herausläßt –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 10, 14, 'starr steht alsdann jeder Mensch da, ohne es begreifen zu können, und schämen muß sich jeder Goldschmied seines Bildwerks; denn Trug ist sein gegossener Götze, kein Odem wohnt in ihm:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 10, 15, 'nichts als Wahn sind sie, lächerliche Gebilde; wenn die Zeit des Strafgerichts für sie kommt, ist es zu Ende mit ihnen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 10, 16, 'Aber nicht wie diese ist Jakobs Erbteil; nein, er ist es, der das All geschaffen hat, und Israel ist der Stamm seines Erbbesitzes: HERR der Heerscharen ist sein Name.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 10, 17, 'Raffe dein Bündel von der Erde zusammen, Tochter Zion, die du in Belagerungsnot sitzest!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 10, 18, 'Denn so hat der HERR gesprochen: »Wisse wohl: diesmal will ich die Bewohner des Landes hinwegschleudern und sie in Bedrängnis versetzen, damit sie endlich zur Erkenntnis kommen!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 10, 19, '»Wehe mir ob meiner Wunde: qualvoll ist der Schlag, der mich getroffen! Doch ich denke: ›Das ist nun einmal mein Leiden: so will ich es denn tragen!‹');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 10, 20, 'Mein Zelt ist zerstört, und alle meine Zeltstricke sind zerrissen; meine Kinder sind mir entführt, keines ist mehr da; niemand schlägt mir hinfort mein Zelt wieder auf und breitet meine Decken darüber aus!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 10, 21, 'Denn meine Hirten sind verdummt gewesen und haben nicht nach dem HERRN gefragt; darum haben sie kein Gelingen gehabt, und ihre ganze Herde ist zerstoben.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 10, 22, 'Horch, eine Kunde: siehe da, sie kommt, und ein gewaltiges Getöse vom Nordlande her, um die Städte Judas zur Wüste zu machen, zur Behausung der Schakale!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 10, 23, 'Ich weiß, HERR, daß des Menschen Schicksal nicht in seiner Hand liegt und daß ein Mann, der da wandelt, seinen Gang nicht fest zu richten vermag.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 10, 24, 'Züchtige mich, HERR, aber nach Billigkeit, nicht in deinem Zorn, auf daß du mich nicht ganz vernichtest!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 10, 25, 'Gieße deinen Grimm aus über die Heidenvölker, die dich nicht kennen, und über die Stämme, die deinen Namen nicht anrufen! Denn sie haben Jakob verschlungen, ja ganz und gar aufgezehrt und seine Aue zur Wüste gemacht!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 11, 1, 'Das Wort, das an Jeremia vom HERRN erging, lautete folgendermaßen:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 11, 2, '»Vernehmet die Worte dieses Bundes und verkündet sie den Männern von Juda und besonders den Bewohnern Jerusalems');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 11, 3, 'und sage du noch folgendes zu ihnen: So hat der HERR, der Gott Israels, gesprochen: ›Verflucht ist jeder, der den Bestimmungen dieses Bundes nicht nachkommt,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 11, 4, 'den ich euren Vätern zur Pflicht gemacht habe zu der Zeit, als ich sie aus dem Lande Ägypten, aus dem Eisen-Schmelzofen, wegführte, indem ich ihnen sagte: Gehorcht meinen Weisungen und handelt nach ihnen ganz so, wie ich euch gebiete, so sollt ihr mein Volk sein, und ich will euer Gott sein,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 11, 5, 'damit ich den Eid aufrechterhalten kann, den ich euren Vätern zugeschworen habe, nämlich ihnen ein Land zu geben, das von Milch und Honig überfließt, wie es heute noch der Fall ist!‹« Da antwortete ich mit den Worten: »Amen, HERR!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 11, 6, 'Darauf sagte der HERR zu mir: »Mache alle diese Worte in den Ortschaften Judas und auf den Straßen Jerusalems bekannt, indem du sagst: ›Vernehmet die Worte dieses Bundes und handelt nach ihnen!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 11, 7, 'Denn ich habe eure Väter zu der Zeit, als ich sie aus dem Lande Ägypten wegführte, und bis auf den heutigen Tag immer und immer wieder aufs ernstlichste ermahnt und sie aufgefordert, meinen Weisungen zu gehorchen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 11, 8, 'Aber sie haben nicht gehorcht und mir kein Gehör geschenkt, sondern sind ein jeder nach dem Starrsinn seines eigenen bösen Herzens gewandelt. Deshalb habe ich alle Drohworte dieses Bundes, dessen Beobachtung ich ihnen geboten hatte, an ihnen in Erfüllung gehen lassen, weil sie nicht danach gehandelt hatten.‹«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 11, 9, 'Weiter sagte der HERR zu mir: »Es besteht eine Verschwörung unter den Männern von Juda und den Bewohnern Jerusalems.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 11, 10, 'Sie sind in die Sünden ihrer Vorväter zurückgefallen, die meinen Weisungen den Gehorsam versagt haben; sind doch auch sie anderen Göttern nachgelaufen, um sie zu verehren: gebrochen haben die vom Hause Israel und vom Hause Juda meinen Bund, den ich mit ihren Vätern geschlossen habe!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 11, 11, 'Darum hat der HERR so gesprochen: »Nunmehr will ich ein Unheil über sie bringen, aus dem herauszukommen ihnen nicht möglich sein soll; und wenn sie dann zu mir um Hilfe schreien, will ich sie nicht erhören.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 11, 12, 'Wenn dann die Ortschaften Judas und die Bewohner Jerusalems hingehen und zu den Göttern, denen sie geopfert haben, um Hilfe schreien, so werden diese ihnen zur Zeit ihres Unglücks nimmermehr helfen können.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 11, 13, 'Denn so zahlreich, wie deine Städte sind, ebenso zahlreich sind auch deine Götter geworden, Juda; und so viele Straßen es in Jerusalem gibt, ebenso viele Altäre habt ihr dem Schandgötzen errichtet, Altäre, um dem Baal zu räuchern.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 11, 14, 'Du aber (Jeremia) sollst keine Fürbitte für dieses Volk einlegen und kein Flehen und kein Gebet für sie laut werden lassen! Denn ich würde doch nicht hören, wenn sie mich zur Zeit ihrer Not um Hilfe anriefen!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 11, 15, '»Was will mein Geliebter in meinem Hause? Etwa böse Anschläge ausführen? Werden Gelübde und Opferfleisch deine Bosheit von dir wegschaffen, daß du alsdann frohlocken dürftest?«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 11, 16, 'Einen ›immergrünen Ölbaum im Schmuck herrlicher Früchte‹ – so hat der HERR dich einst genannt; aber wegen seines gewaltig lauten Rauschens legt er jetzt Feuer an ihn, und es brechen seine Zweige.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 11, 17, 'Denn der HERR der Heerscharen, der dich gepflanzt, hat Unheil über dich beschlossen wegen der Bosheit, die das Haus Israel und das Haus Juda verübt haben, um mich zu erbittern, indem sie dem Baal opferten.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 11, 18, 'Der HERR hat es mich wissen lassen, da habe ich es erfahren; damals hast du mich ihr Treiben durchschauen lassen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 11, 19, 'Ich selbst war wie ein argloses Lamm, das zur Schlachtbank geführt wird, und ahnte nicht, daß sie böse Anschläge gegen mich schmiedeten: »Laßt uns den Baum samt seinen Früchten vernichten und ihn aus dem Lande der Lebenden ausrotten, daß seines Namens nicht mehr gedacht wird!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 11, 20, 'Und nun, HERR der Heerscharen, gerechter Richter, der du Nieren und Herz prüfst: laß mich deine Rache an ihnen sehen! Denn dir habe ich meine Sache anheimgestellt.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 11, 21, 'Darum hat der HERR so gesprochen in bezug auf die Männer von Anathoth, die dir nach dem Leben getrachtet und zu dir gesagt haben: »Du sollst nicht im Namen des HERRN weissagen, sonst mußt du durch unsere Hand sterben!« –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 11, 22, 'darum hat der HERR der Heerscharen so gesprochen: »Wisse wohl: ich will es sie büßen lassen! Ihre jungen Männer sollen durchs Schwert umkommen, ihre Söhne und Töchter Hungers sterben!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 11, 23, 'Kein Überrest soll ihnen verbleiben, denn ich will Unglück über die Männer von Anathoth bringen in dem Jahre, wo ich die Strafe an ihnen vollziehe!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 12, 1, '»Du behältst recht, HERR, wenn ich mit dir streite, und doch möchte ich über (dein) richterliches Walten mit dir reden: Warum ist das Tun und Lassen der Gottlosen erfolgreich, und warum bleiben alle, die treulos handeln, unangefochten?');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 12, 2, 'Du selbst pflanzest sie ein, sie schlagen auch Wurzel; sie gedeihen und bringen auch Frucht: nahe bist du ihnen ihrem Munde nach, doch fern von ihrem Herzen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 12, 3, 'Du aber, HERR, du kennst mich durch und durch und hast erprobt, wie mein Herz zu dir steht: raffe sie hinweg wie Schafe zur Schlachtung und weihe sie für den Tag, an dem sie abgetan werden!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 12, 4, 'Wie lange soll das Land noch trauern und die Gewächse auf der ganzen Flur verdorren? Wie lange noch sollen infolge der Bosheit seiner Bewohner Vieh und Vögel hinschwinden? Sie sagen ja doch: ›Er wird unser Ende nicht zu sehen bekommen!‹«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 12, 5, '»Wenn du mit Fußgängern wettläufst und die dich schon müde machen, wie willst du da mit Rossen um die Wette rennen? Und wenn du dich nur in einem friedlichen Lande sicher fühlst, wie willst du es da machen im hohen Dickicht des Jordans?');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 12, 6, 'Denn selbst deine Verwandten und deines Vaters Haus – sogar die sind treulos gegen dich, auch die haben hinter dir her geschrien aus voller Kehle; traue ihnen nicht, wenn sie auch freundlich mit dir reden!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 12, 7, '»Ich habe mich von meinem Hause losgesagt, meinen Erbbesitz hingegeben, habe den Liebling meines Herzens in die Gewalt seiner Feinde fallen lassen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 12, 8, 'Mein Erbteil ist mir geworden wie ein Löwe im Walde: es hat sein Gebrüll gegen mich erhoben, darum mußte es mir verhaßt werden.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 12, 9, 'Ist denn mein Erbbesitz für mich zu einem bunten Vogel geworden, daß die Vögel sich ringsum dawider sammeln? Auf! Laßt alle Tiere des Feldes zusammenkommen! Bringt sie zum Fressen herbei!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 12, 10, 'Viele Hirten haben meinen Weinberg verwüstet, meinen Grund und Boden zertreten; sie haben den Acker, der meine Lust war, zur öden Trift gemacht.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 12, 11, 'In eine Einöde haben sie ihn verwandelt, verödet trauert er um mich her; verwüstet ist das ganze Land, weil niemand es sich hat zu Herzen gehen lassen.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 12, 12, 'Über alle kahlen Höhen in der Trift sind Verwüster eingebrochen; denn ein Schwert hat der HERR, das von einem Ende des Landes bis zum andern frißt: da gibt es keine Rettung für alles Fleisch.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 12, 13, 'Sie haben Weizen gesät, aber Dornen geerntet, haben sich abgemüht, ohne etwas auszurichten. So werdet denn zuschanden an euren Ernteerträgen infolge des lodernden Zornes des HERRN!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 12, 14, 'So hat der HERR über alle meine bösen Nachbarn gesprochen, die den Erbbesitz angetastet haben, den ich meinem Volke Israel zu eigen gegeben habe: »Wisse wohl: ich will sie aus ihrem Boden herausreißen, wie ich das Haus Juda aus ihrer Mitte wegreiße!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 12, 15, 'Wenn ich sie aber herausgerissen habe, alsdann will ich mich ihrer wieder erbarmen und will sie zurückführen, einen jeden in seinen Erbbesitz und einen jeden in sein Land.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 12, 16, 'Wenn sie sich dann an die Wege meines Volkes fest gewöhnen, so daß sie bei meinem Namen schwören: ›So wahr der HERR lebt!‹, gleichwie sie mein Volk daran gewöhnt haben, beim Baal zu schwören, so sollen sie inmitten meines Volkes aufgebaut werden.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 12, 17, 'Wollen sie aber nicht gehorchen, so will ich ein solches Volk mit Stumpf und Stiel für immer ausreißen!« – so lautet der Ausspruch des HERRN.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 13, 1, 'So hat der HERR zu mir gesprochen: »Gehe hin und kaufe dir einen linnenen Gürtel und lege ihn dir um die Hüften, aber laß ihn nicht ins Wasser geraten!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 13, 2, 'Da kaufte ich den Gürtel nach dem Befehl des HERRN und legte ihn mir um die Hüften.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 13, 3, 'Hierauf erging das Wort des HERRN zum zweitenmal an mich folgendermaßen:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 13, 4, '»Nimm den Gürtel, den du dir gekauft hast und um deine Hüften trägst, und mache dich auf, gehe an den Euphrat und verstecke ihn dort in einer Felsspalte!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 13, 5, 'Da ging ich hin und versteckte ihn am Euphrat, wie der HERR mir geboten hatte.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 13, 6, 'Nach längerer Zeit aber sagte der HERR zu mir: »Mache dich auf, gehe an den Euphrat und hole von dort den Gürtel, den du dort auf meinen Befehl versteckt hast!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 13, 7, 'Da begab ich mich an den Euphrat, grub nach und nahm den Gürtel von der Stelle, wo ich ihn versteckt hatte; aber siehe da: der Gürtel war verdorben, war zu nichts mehr zu gebrauchen!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 13, 8, 'Da erging das Wort des HERRN an mich folgendermaßen:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 13, 9, '»So spricht der HERR: Ebenso will ich den Hochmut Judas und den Hochmut Jerusalems, der so gewaltig ist, ins Verderben stürzen!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 13, 10, 'Dieses böse Volk, das sich weigert, auf meine Worte zu hören, das da wandelt im Starrsinn seines Herzens und anderen Göttern nachläuft, um ihnen zu dienen und sie anzubeten: es soll ihm ebenso ergehen wie diesem Gürtel, der zu nichts mehr taugt.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 13, 11, 'Denn gleichwie der Gürtel sich eng an die Hüften eines Mannes anschließt, so hatte ich das ganze Haus Israel und das ganze Haus Juda sich eng an mich anschließen lassen« – so lautet der Ausspruch des HERRN –, »damit sie mein Volk würden, mir zum Ruhm und zum Lobpreis und zur Zierde; aber sie haben nicht gehorcht.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 13, 12, '»So richte denn folgende Worte an sie: ›So hat der HERR, der Gott Israels, gesprochen: Jeder Krug wird mit Wein gefüllt.‹ Wenn sie dann zu dir sagen: ›Sollten wir das wirklich nicht selbst wissen, daß jeder Krug mit Wein gefüllt wird?‹,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 13, 13, 'so erwidere ihnen: ›So hat der HERR gesprochen: Fürwahr, ich will alle Bewohner dieses Landes, sowohl die Könige, die auf dem Throne Davids sitzen, als auch die Priester und Propheten und alle Bewohner Jerusalems mit Trunkenheit füllen');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 13, 14, 'und sie sich dann einen an dem andern zerschmettern lassen, und zwar die Väter zugleich mit den Söhnen!‹ – so lautet der Ausspruch des HERRN –; ›ich will dabei keine Schonung üben und kein Mitleid haben, und kein Erbarmen soll mich abhalten, sie zu vernichten!‹«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 13, 15, 'Höret und merkt auf! Seid nicht hochmütig, denn der HERR ist’s, der geredet hat!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 13, 16, 'Gebt dem HERRN, eurem Gott, die Ehre, bevor es Nacht wird und bevor eure Füße sich an den Bergen in der Dunkelheit stoßen und ihr dann auf Licht wartet, er es aber zu tiefster Finsternis macht und es in Wolkendunkel verwandelt!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 13, 17, 'Wenn ihr aber nicht gehorcht, so muß ich vor Kummer im Verborgenen weinen ob eurem Hochmut, und mein Auge muß unaufhörlich in Tränen zerfließen, weil die Herde des HERRN gefangen weggeführt wird.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 13, 18, 'Sage zum König und zur Herrin: »Setzt euch tief herunter, denn vom Haupt ist euch eure herrliche Krone herabgefallen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 13, 19, 'Die Städte des Südlands sind verschlossen, und niemand ist da, der sie öffnet; in Gefangenschaft wird Juda weggeführt insgesamt, weggeführt in voller Zahl!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 13, 20, 'Hebe deine Augen auf, Jerusalem, und sieh, wie sie von Norden daherkommen! Wo ist die Herde, die dir anvertraut war, deine prächtigen Schafe?');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 13, 21, 'Was wirst du sagen, wenn er die, welche du selbst als vertraute Freunde an dich gewöhnt hast, zum Oberhaupt über dich bestellt? Werden dich da nicht Wehen erfassen wie ein Weib in Geburtsnöten?');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 13, 22, 'Und wenn du alsdann bei dir selber denkst: »Warum hat solches Leid mich getroffen?«, so wisse: Wegen deiner schweren Verschuldung wird dir die Schleppe aufgehoben, werden dir die Füße mit Gewalt entblößt.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 13, 23, 'Kann wohl ein Mohr seine Haut verwandeln und ein Pardel sein buntes Fell? Dann würdet auch ihr imstande sein gut zu handeln, die ihr an Bösestun gewöhnt seid.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 13, 24, '»Darum will ich sie zerstreuen wie Spreu, die vor dem Wüstenwinde verfliegt.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 13, 25, 'Das ist dein Los, dein Teil, das ich dir zugemessen habe« – so lautet der Ausspruch des HERRN –, »weil du mich vergessen und dein Vertrauen auf Trug gesetzt hast.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 13, 26, 'Darum will auch ich dir deine Schleppen vorn bis über das Gesicht hochziehen, damit deine Scham sichtbar wird.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 13, 27, 'Deine Ehebrecherei und dein brünstiges Wiehern, die Schmach deiner Buhlerei – auf den Hügeln wie im freien Felde habe ich deine Greuel gesehen! Wehe dir, Jerusalem, daß du dich nicht reinigst! Wie lange wird’s noch währen?«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 14, 1, '(Dies ist) das Wort des HERRN, das an Jeremia erging aus Anlaß der großen Dürre:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 14, 2, '»Juda trauert, und in seinen Toren verschmachten (die Menschen), liegen im Trauergewand am Boden, und Jerusalems Wehgeschrei steigt empor!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 14, 3, 'Die Vornehmen unter ihnen schicken ihre Diener nach Wasser aus; aber wenn diese an die Brunnen gekommen sind, finden sie kein Wasser und kehren mit leeren Gefäßen heim: enttäuscht und bestürzt sind sie und verhüllen ihr Haupt.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 14, 4, 'Wegen des Erdreichs, das unbestellt daliegt, weil kein Regen im Lande gefallen ist, sind die Ackerbauer (in ihrer Hoffnung) getäuscht und verhüllen sich das Haupt.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 14, 5, 'Ja, selbst die Hirschkuh auf dem Felde läßt ihr Junges, das sie eben geboren hat, im Stich, weil sie nichts Grünes mehr findet;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 14, 6, 'und die Wildesel stehen auf den kahlen Höhen, schnappen nach Luft wie die Schakale; ihre Augen verschmachten, denn nirgends ist grünes Futter.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 14, 7, '»Wenn unsere Sünden uns anklagen, HERR, so handle du uns zugut um deines Namens willen! Denn groß ist die Zahl unserer Treubrüche, mit denen wir gegen dich gesündigt haben.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 14, 8, 'O du Hoffnung Israels, du sein Retter zur Zeit der Not! Warum willst du sein wie ein Fremdling im Lande und wie ein Wanderer, der nur zum Übernachten Halt macht?');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 14, 9, 'Warum willst du sein wie ein verzagter Mann, wie ein Held, der nicht zu helfen vermag? Du bist ja doch in unserer Mitte, o HERR, und nach deinem Namen sind wir genannt: verlaß uns nicht!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 14, 10, 'So hat der HERR in bezug auf dieses Volk gesprochen: »So hin und her zu schweifen, das lieben sie: ihre Füße haben sie nie geschont; der HERR hat kein Wohlgefallen an ihnen gehabt; doch jetzt gedenkt er ihrer Schuld und straft sie für ihre Sünden.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 14, 11, 'Weiter hat der HERR zu mir gesagt: »Du sollst keine Fürbitte für dieses Volk einlegen, daß es ihm gut ergehen möge!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 14, 12, 'Wenn sie fasten, so höre ich nicht auf ihr Flehen, und wenn sie Brandopfer und Speisopfer darbringen, so nehme ich sie nicht wohlgefällig an, vielmehr will ich sie durch Schwert und Hungersnot und durch die Pest ausrotten!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 14, 13, 'Da sagte ich: »Ach, HERR, mein Gott, siehe, die Propheten sagen doch zu ihnen: ›Ihr werdet kein Schwert zu sehen bekommen, und Hungersnot wird euch nicht treffen; nein, dauerndes Heil will ich euch an dieser Stätte verleihen!‹«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 14, 14, 'Da antwortete mir der HERR: »Lüge weissagen die Propheten in meinem Namen; ich habe sie nicht gesandt und sie nicht entboten und ihnen keinen Auftrag erteilt; erlogene Gesichte und Trugweissagung und selbstersonnene Täuschung weissagen sie euch!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 14, 15, 'Darum hat der HERR so gesprochen: »Die Propheten, die in meinem Namen weissagen und die, obgleich ich sie nicht gesandt habe, dennoch verkünden: ›Weder Schwert noch Hungersnot wird dieses Land treffen‹ – durch das Schwert und durch Hungersnot sollen diese Propheten den Tod finden!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 14, 16, 'Das Volk aber, dem sie weissagen, wird auf den Straßen Jerusalems vom Hunger und Schwert niedergestreckt daliegen, ohne daß jemand sie zu Grabe trägt – sie selbst und ihre Frauen, ihre Söhne und ihre Töchter; so will ich die Strafe für ihre Bosheit über sie ausgießen!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 14, 17, '»Du aber richte dieses Wort an sie: ›Bei Tag und bei Nacht zerfließen meine Augen in Tränen und kommen nicht zur Ruhe! Denn einen furchtbaren Schlag hat die Jungfrau, die Tochter meines Volkes, erlitten, eine qualvolle Wunde.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 14, 18, 'Gehe ich aufs Feld hinaus, so erblicke ich dort vom Schwert Erschlagene, und komme ich in die Stadt zurück, so gewahre ich die Qualen des Hungers! Ja, auch die Propheten und auch die Priester müssen in ein Land ziehen, das sie nicht kennen.‹«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 14, 19, 'Hast du denn Juda ganz verworfen? Oder bist du Zions im Herzen überdrüssig geworden? Warum hast du uns so geschlagen, daß keine Heilung für uns mehr vorhanden ist? Wir warten auf Rettung, aber es kommt nichts Gutes, und auf die Stunde der Heilung, aber ach, da ist nichts als Schrecken!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 14, 20, 'O HERR, wir erkennen unsere Gottlosigkeit, auch die Schuld unserer Väter, daß wir gegen dich gesündigt haben.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 14, 21, 'Verwirf (uns) nicht um deines Namens willen! Laß den Thronsitz deiner Herrlichkeit nicht in Unehre fallen! Behalte im Gedächtnis, brich nicht deinen Bund mit uns!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 14, 22, 'Gibt es etwa unter den nichtigen Götzen der Heiden Regenspender? Oder schickt etwa der Himmel von selbst die Regengüsse? Bist du es nicht, HERR, unser Gott? So hoffen wir denn auf dich; denn du bist es, der dies alles tut.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 15, 1, 'Aber der HERR antwortete mir: »Wenn auch Mose und Samuel vor mich träten, würde mein Herz sich doch diesem Volke nicht zuwenden: schaffe sie mir aus den Augen, sie sollen weggehen!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 15, 2, 'Wenn sie dich dann fragen: ›Wohin sollen wir gehen?‹, so antworte ihnen: ›So hat der HERR gesprochen: Wer für den Tod bestimmt ist, gehe zum Tode! Wer für das Schwert (bestimmt ist), zum Schwerte! Wer für den Hunger, zum Hunger! Und wer für die Gefangenschaft, zur Gefangenschaft!‹');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 15, 3, 'Denn ich will vier Arten (von Verderbern) gegen sie aufbieten« – so lautet der Ausspruch des HERRN –: »das Schwert zum Morden, die Hunde zum Zerren, die Vögel des Himmels und die Tiere des Feldes zum Fressen und zum Vertilgen');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 15, 4, 'und will sie so zu einem abschreckenden Beispiel für alle Reiche der Erde machen um des judäischen Königs Manasse, des Sohnes Hiskias, willen, wegen alles dessen, was er in Jerusalem verübt hat.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 15, 5, 'Ach, wer wird Mitleid mit dir haben, Jerusalem, und wer dir Teilnahme bezeigen? Und wer wird bei dir einkehren, um sich nach deinem Ergehen zu erkundigen?');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 15, 6, '»Du selbst hast mich ja verworfen« – so lautet der Ausspruch des HERRN –, »hast mir den Rücken zugekehrt; darum habe ich meine Hand gegen dich erhoben und dich zerschmettert: ich war’s müde, mich erbitten zu lassen!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 15, 7, 'Ich habe sie mit der Worfschaufel hinausgeworfelt in den Toren des Landes, habe mein Volk seiner Kinder beraubt und es zugrunde gerichtet: sie sind von ihren bösen Wegen doch nicht umgekehrt!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 15, 8, 'Ihre Witwen sind mir zahlreicher geworden als der Sand am Meer; ich habe ihnen über die Mütter der jungen Männer den Würgengel am hellen Mittag gebracht, habe jählings Angst und Schrecken auf sie fallen lassen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 15, 9, 'Die Mutter, welche sieben Söhne geboren hat, vergeht nun vor Trauer, haucht ihr Leben aus: die Sonne ist ihr noch bei Tage untergegangen, fassungslos und gebrochen steht sie da! Was jetzt aber von ihnen noch übrig ist, will ich dem Schwert preisgeben (auf der Flucht) vor ihren Feinden!« – so lautet der Ausspruch des HERRN.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 15, 10, 'Wehe mir, meine Mutter, daß du mich geboren hast, einen Mann der Anfeindung und des Haders für das ganze Land! Ich habe kein Geld ausgeliehen, und niemand hat mir geborgt, und doch fluchen sie mir alle!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 15, 11, 'Der HERR hat verheißen: »Wahrlich, ich will dich zum Guten stärken, wahrlich, ich will es so fügen, daß zur Zeit des Unglücks, zur Zeit der Not, der Feind dich bittend angehen soll!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 15, 12, '[Kann man Eisen zerbrechen, Eisen aus dem Norden, und Erz?');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 15, 13, 'Dein Vermögen und deine Schätze will ich der Plünderung preisgeben ohne Entgelt, und zwar wegen aller Sünden, die du in allen Teilen deines Landes begangen hast;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 15, 14, 'und ich will dich deinen Feinden dienstbar machen in einem Lande, das du nicht kennst; denn ein Feuer ist entbrannt durch meinen Zorn und lodert gegen euch.]');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 15, 15, 'HERR, du selbst weißt es: gedenke mein und nimm dich meiner an und schaffe mir Rache an meinen Widersachern! Laß mich nicht infolge deiner Langmut (gegen sie) hinweggerafft werden! Bedenke, daß ich um deinetwillen Schmach erdulde!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 15, 16, 'Sooft deine Befehle erfolgten, habe ich sie meine Speise sein lassen, und deine Weisungen sind mir eine Wonne und Herzensfreude gewesen; ich bin ja nach deinem Namen genannt, HERR, du Gott der Heerscharen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 15, 17, 'Ich habe nie im Kreise der Scherzenden gesessen, um mich zu erlustigen; nein, von deiner Hand gebeugt, habe ich einsam gesessen, weil du mich mit Unwillen erfüllt hattest.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 15, 18, 'Warum ist mein Schmerz endlos geworden und meine Wunde tödlich, daß sie eine Heilung zurückweist? Willst du mir wirklich wie ein trügerischer Bach sein, wie ein Wasserlauf, auf den kein Verlaß ist?');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 15, 19, 'Darum hat der HERR so (zu mir) gesprochen: »Wenn du umkehrst, so will ich dich zurückkehren lassen, daß du mir aufs neue dienen darfst; und wenn du nur Edles, nichts Gemeines hören läßt, sollst du wieder wie mein Mund sein. Jene sollen sich dann zu dir umwenden, du aber sollst dich nicht zu ihnen umwenden.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 15, 20, 'Dann will ich dich diesem Volke gegenüber zu einer hochragenden Mauer von Erz machen, daß, wenn sie gegen dich anstürmen, sie dir doch nichts anhaben können; denn ich bin mit dir, um dir zu helfen und dir den Sieg zu verleihen« – so lautet der Ausspruch des HERRN –;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 15, 21, '»und ich will dich aus der Hand der Bösen erretten und dich aus der Faust der Gewalttätigen befreien!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 16, 1, 'Das Wort des HERRN erging dann an mich folgendermaßen:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 16, 2, '»Du sollst dir kein Weib nehmen und weder Söhne noch Töchter an diesem Orte haben!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 16, 3, 'Denn so hat der HERR gesprochen in betreff der Söhne und Töchter, die an diesem Orte geboren werden, und in betreff ihrer Mütter, die sie gebären, und in betreff ihrer Väter, die sie in diesem Lande zeugen:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 16, 4, '»An qualvollen Todesarten sollen sie sterben, ohne betrauert und bestattet zu werden! Zu Dünger auf offenem Felde sollen sie werden! Durch Schwert und Hunger sollen sie ums Leben kommen, und ihre Leichen sollen den Vögeln des Himmels und den Tieren des Feldes zum Fraß dienen!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 16, 5, 'Weiter gebot der HERR mir: »Du sollst in kein Trauerhaus eintreten und zu keiner Totenklage hingehen und keinem von ihnen Beileid bezeigen! Denn ich habe diesem Volke meine Freundschaft entzogen« – so lautet der Ausspruch des HERRN –, »die Liebe und das Erbarmen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 16, 6, 'So sollen sie denn in diesem Lande sterben, groß und klein, ohne bestattet zu werden, und niemand wird um sie trauern noch sich blutig ritzen oder sich ihretwegen kahl scheren.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 16, 7, 'Auch wird man keinem das Trauerbrot brechen, um ihn wegen eines Verstorbenen zu trösten, und wird keinem den Trostbecher zu trinken geben wegen seines Vaters oder seiner Mutter. –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 16, 8, 'Auch in ein Haus, wo man ein Gastmahl abhält, sollst du nicht eintreten, um dich zum Schmausen und Trinken mit ihnen niederzusetzen!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 16, 9, 'Denn so hat der HERR der Heerscharen, der Gott Israels, gesprochen: »Fürwahr, ich will an diesem Orte vor euren Augen und in euren Tagen aller lauten Freude und aller Fröhlichkeit, allem Jubel des Bräutigams und allem Brautgesang ein Ende machen!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 16, 10, '»Wenn du nun diesem Volk alle diese Worte verkündigst und sie dich dann fragen: ›Warum hat der HERR uns all dieses große Unheil angedroht? Und worin besteht unsere Verschuldung und worin unsere Sünde, die wir gegen den HERRN, unsern Gott, begangen haben?‹,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 16, 11, 'so antworte ihnen: ›Darin, daß eure Väter mich verlassen haben‹ – so lautet der Ausspruch des HERRN – ›und anderen Göttern nachgelaufen sind und ihnen gedient und sie angebetet, mich aber verlassen und mein Gesetz nicht beobachtet haben.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 16, 12, 'Und ihr habt es noch ärger getrieben als eure Väter; ihr geht ja ein jeder dem Starrsinn seines bösen Herzens nach, ohne auf mich zu hören!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 16, 13, 'So will ich euch denn aus diesem Lande wegschleudern in ein Land, das weder ihr noch eure Väter gekannt haben; dort sollt ihr dann anderen Göttern Tag und Nacht dienen, weil ich für euch kein Erbarmen mehr übrig habe!‹«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 16, 14, '»Darum wisset wohl: es kommt die Zeit« – so lautet der Ausspruch des HERRN –, »da wird man nicht mehr sagen: ›So wahr der HERR lebt, der die Kinder Israel aus dem Lande Ägypten hergeführt hat!‹,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 16, 15, 'sondern: ›So wahr der HERR lebt, der die Kinder Israel hergeführt hat aus dem Nordlande und aus all den Ländern, wohin er sie verstoßen hatte!‹ Denn ich werde sie in ihr Land zurückbringen, das ich ihren Vätern gegeben habe.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 16, 16, '»Wisset wohl: ich will zahlreiche Fischer entbieten« – so lautet der Ausspruch des HERRN –, »die sollen sie wie Fische fangen; und danach will ich zahlreiche Jäger entbieten, die sollen sie aufjagen von jedem Berge hinweg und von jedem Hügel weg und aus den Felsenklüften heraus;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 16, 17, 'denn meine Augen sind auf alle ihre Wege gerichtet: sie bleiben mir nicht verborgen, und ihre Schuld ist vor meinen Augen nicht verhüllt.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 16, 18, 'Zunächst also will ich ihnen ihre Schuld und ihre Sünde zwiefach vergelten, weil sie mein Land durch die Leichen ihrer scheußlichen Götzen entweiht und meinen Erbbesitz mit ihren Greueln erfüllt haben.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 16, 19, 'O HERR, du meine Stärke und meine Burg, meine Zuflucht in der Zeit der Not! Zu dir werden die Heidenvölker von den Enden der Erde her kommen und sagen: »Nichts als Trug haben unsere Väter zum Besitz gehabt, nichtige Götzen, von denen keiner zu helfen vermag!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 16, 20, 'Kann etwa ein Mensch sich Götter anfertigen? Das sind doch keine Götter!« –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 16, 21, '»Darum wisset wohl: diesmal will ich sie zur Erkenntnis führen, will sie meine Hand und meine Stärke fühlen lassen: dann werden sie erkennen, daß mein Name ist ›der HERR‹!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 17, 1, 'Die Sünde Judas ist aufgeschrieben mit eisernem Griffel, mit diamantener Spitze eingegraben in die Tafel ihres Herzens und an die Hörner ihrer Altäre.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 17, 2, 'Wie ihrer Kinder, so gedenken sie ihrer Altäre und ihrer Ascheren bei den dichtbelaubten Bäumen, auf den hohen Hügeln.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 17, 3, '»Meinen Berg im Gefilde, deine Habe, alle deine Schätze gebe ich der Plünderung preis, deine Höhen als Entgelt für deine Versündigung in allen Teilen deines Gebiets.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 17, 4, 'Da mußt du denn, und zwar durch eigene Schuld, deinen Erbbesitz fahren lassen, den ich dir verliehen habe, und ich will dich deinen Feinden zum Knecht machen in einem Lande, das du nicht kennst; denn ein Feuer habt ihr in meiner Nase angezündet, das bis in Ewigkeit brennen wird.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 17, 5, 'So hat der HERR gesprochen: »Verflucht ist der Mann, der sich auf Menschen verläßt und Fleisch zu seinem Arm macht und dessen Herz sich vom HERRN abkehrt!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 17, 6, 'Der gleicht einem kahlen Baume in der Steppe und wird nicht erleben, daß Gutes kommt; nein, er muß in dürren Wüstenstrichen wohnen, auf dem Salzboden der unwirtlichen Heide.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 17, 7, 'Gesegnet aber ist der Mann, der sich auf den HERRN verläßt und dessen Zuversicht der HERR ist!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 17, 8, 'Der gleicht einem Baume, der am Wasser gepflanzt ist und seine Wurzeln nach dem Bache hin ausstreckt; er hat nichts zu fürchten, wenn Hitze kommt, und sein Laub bleibt grün; auch in dürren Jahren ist ihm nicht bange, und ohne Aufhören trägt er Früchte.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 17, 9, 'Arglistig ist das Herz, mehr als alles andere, und verschlagen ist es: wer kann es ergründen?');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 17, 10, '»Ich, der HERR, erforsche das Herz und prüfe die Nieren, und zwar um einem jeden zu vergelten nach seinem Wandel, nach der Frucht seiner Taten.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 17, 11, 'Wie ein Rebhuhn, das Eier bebrütet, die es nicht gelegt hat, so ist ein Mensch, der Reichtum erwirbt, aber nicht auf rechtmäßige Weise: in der Mitte seiner Lebenstage muß er ihn wieder fahren lassen, und an seinem Ende steht er da als Narr.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 17, 12, 'O Thron der Herrlichkeit, hocherhaben von Anbeginn an, du Stätte unsers Heiligtums!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 17, 13, 'O Hoffnung Israels, HERR! Alle, die dich verlassen, werden zuschanden, und die von dir abfallen, deren Namen werden auf die Erde geschrieben; denn verlassen haben sie den Brunnquell lebendigen Wassers, den HERRN.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 17, 14, 'Heile mich, HERR, so werde ich heil, hilf mir, so ist mir geholfen! Denn mein Lobpreis bist du.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 17, 15, 'Siehe, jene sagen zu mir: »Wo bleibt denn das Drohwort des HERRN? Möge es doch eintreffen!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 17, 16, 'Ich aber habe mich nicht dem Hirtenamt in deinem Dienst entzogen und habe den Tag des Unheils nicht herbeigewünscht: du weißt es wohl! Was über meine Lippen gekommen ist, liegt offen vor deinen Augen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 17, 17, 'Mache mich nicht völlig hoffnungslos, du bist meine Zuflucht am Tage des Unheils!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 17, 18, 'Laß meine Verfolger zuschanden werden, aber nicht mich! Laß sie verzagt dastehen, aber nicht mich! Bringe über sie den Tag des Unheils und zerschmettere sie mit doppelter Vernichtung!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 17, 19, 'So hat der HERR mir geboten: »Gehe hin und stelle dich auf im Tor der Söhne des Volkes, durch das die Könige von Juda aus- und einziehen, und in allen übrigen Toren Jerusalems');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 17, 20, 'und sage zu ihnen: Vernehmt das Wort des HERRN, ihr Könige von Juda und ihr Judäer insgesamt und alle ihr Bewohner Jerusalems, die ihr durch diese Tore eingeht!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 17, 21, 'So hat der HERR gesprochen: ›Hütet euch um eures Lebens willen, am Sabbattage eine Last auf euch zu nehmen und sie in die Tore Jerusalems hineinzubringen!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 17, 22, 'Tragt am Sabbattage auch keine Last aus euren Häusern hinaus und verrichtet überhaupt keinerlei Arbeit, sondern haltet den Sabbattag heilig, wie ich euren Vätern geboten habe!‹');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 17, 23, 'Doch sie haben nicht gehorcht und mir kein Gehör geschenkt, sondern haben sich halsstarrig gezeigt, so daß sie nicht gehorsam gewesen sind und sich nicht haben warnen lassen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 17, 24, '›Wenn ihr nun willig auf mich hört‹ – so lautet der Ausspruch des HERRN –, ›daß ihr am Sabbattage keine Last durch die Tore dieser Stadt hereintragt, vielmehr den Sabbattag heilig haltet, indem ihr keinerlei Arbeit an ihm verrichtet,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 17, 25, 'so werden Könige [und Fürsten], die auf dem Throne Davids sitzen, durch die Tore dieser Stadt zu Wagen und zu Roß einziehen, sie samt ihren Fürsten, die Männer von Juda samt den Bewohnern Jerusalems, und diese Stadt wird ewig bewohnt bleiben.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 17, 26, 'Dazu werden aus den Ortschaften Judas und aus der Umgegend von Jerusalem sowie aus dem Stamme Benjamin und aus der Niederung, vom Bergland und aus dem Südgau Leute kommen, die Brand- und Schlachtopfer, Speisopfer und Weihrauch darbringen und mit Dankopfern im Tempel des HERRN erscheinen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 17, 27, 'Wenn ihr aber nicht auf mich hört, den Sabbattag heilig zu halten, so daß ihr am Sabbattage keinerlei Last tragt, noch mit einer solchen durch die Tore Jerusalems eingeht, so will ich Feuer an die Tore der Stadt legen, das soll die Paläste Jerusalems verzehren und nicht erlöschen!‹«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 18, 1, 'Das Wort, welches an Jeremia vom HERRN erging, lautete folgendermaßen:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 18, 2, '»Mache dich auf und gehe in das Haus des Töpfers hinab, denn dort will ich dir meine Weisungen kundtun!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 18, 3, 'So ging ich denn in das Haus des Töpfers hinab und fand ihn gerade mit einer Arbeit auf der Töpferscheibe beschäftigt;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 18, 4, 'und wenn das Gefäß, das er anfertigte, mißriet, wie das bei dem Ton unter der Hand des Töpfers vorkommt, so machte er wieder ein anderes Gefäß daraus, wie es dem Töpfer eben gut schien.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 18, 5, 'Da erging das Wort des HERRN an mich folgendermaßen:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 18, 6, '»Habe ich nicht das Recht, wie dieser Töpfer da mit euch zu verfahren, ihr vom Hause Israel?« – so lautet der Ausspruch des HERRN. »Wisset wohl: wie der Ton in der Hand des Töpfers, ebenso seid ihr in meiner Hand, ihr vom Hause Israel.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 18, 7, 'Einmal drohe ich einem Volke oder einem Königshause, daß ich es ausrotten, vernichten und vertilgen wolle;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 18, 8, 'wenn dann aber das betreffende Volk, gegen das meine Drohung gerichtet war, sich von seiner Bosheit bekehrt, so lasse ich mir das Unheil leid sein, das ich ihm zuzufügen beschlossen hatte.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 18, 9, 'Und ein andermal verheiße ich einem Volke oder einem Königshause, es aufbauen und einpflanzen zu wollen;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 18, 10, 'wenn es dann aber tut, was mir mißfällt, indem es meinen Weisungen nicht nachkommt, so lasse ich mir das Gute leid sein, das ich ihm zu erweisen gedacht hatte.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 18, 11, 'Darum verkünde nun den Männern von Juda und besonders den Bewohnern Jerusalems folgendes: ›So hat der HERR gesprochen: Wisset wohl: ich habe Böses gegen euch im Sinn und hege Unheilsgedanken gegen euch. Kehrt doch um, ein jeder von seinem bösen Wege, und bessert euren Wandel und euer ganzes Tun!‹');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 18, 12, 'Doch sie werden antworten: ›Vergebliche Mühe! Nein, wir wollen unsern eigenen Gedanken nachgehen und ein jeder nach dem Starrsinn seines bösen Herzens handeln!‹«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 18, 13, 'Darum hat der HERR so gesprochen: »Erkundigt euch doch bei den Heidenvölkern, ob jemand so etwas jemals gehört habe! Etwas ganz Abscheuliches hat die Jungfrau Israel verübt!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 18, 14, 'Verläßt wohl jemals der Schnee des Libanons den Felsen im Gefild? Oder versiegen jemals die weither kommenden Wasser, die kalten, rieselnden?');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 18, 15, 'Doch mich hat mein Volk vergessen: den nichtigen Götzen opfern sie, und diese haben sie zu Fall gebracht auf ihren Wegen, den Pfaden der Vorzeit, so daß sie wandeln auf den Steigen eines ungebahnten Weges,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 18, 16, 'um so ihr Land zu einem abschreckenden Beispiel zu machen, zu ewigem Hohn: jeder, der daran vorüberzieht, entsetzt sich und schüttelt den Kopf.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 18, 17, 'Wie der Ostwind werde ich sie (auf der Flucht) vor dem Feinde her zerstreuen, werde ihnen den Rücken, aber nicht mein Angesicht zukehren am Tage ihres Untergangs!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 18, 18, 'Sie haben gesagt: »Kommt, laßt uns Anschläge gegen Jeremia ersinnen! Denn noch fehlt es den Priestern nicht an Belehrung und den Weisen nicht an Rat, noch den Propheten an Wort. Kommt, wir wollen ihn mit (seiner eigenen) Zunge schlagen und alle seine Reden unbeachtet lassen!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 18, 19, 'Gib doch acht auf mich, HERR, und vernimm die Worte meiner Widersacher!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 18, 20, 'Soll denn Gutes mit Bösem vergolten werden? Sie haben ja meinem Leben eine Grube gegraben! Denke daran, wie ich vor dir gestanden habe, Fürbitte für sie einzulegen, um deinen Zorn von ihnen abzuwenden!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 18, 21, 'Darum gib ihre Kinder dem Hunger preis und überliefere sie der Gewalt des Schwertes! Laß ihre Weiber kinderlos und zu Witwen werden, wenn ihre Männer von der Pest hingerafft sind, und laß ihre Jünglinge vom Schwert erschlagen werden im Kriege!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 18, 22, 'Wehgeschrei möge aus ihren Häusern erschallen, wenn du unversehens Kriegerscharen über sie kommen läßt; denn sie haben eine Grube gegraben, um mich zu fangen, und meinen Füßen haben sie heimlich Schlingen gelegt.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 18, 23, 'Du aber, HERR, kennst alle ihre Mordanschläge gegen mich: vergib ihnen ihre Missetat nicht und tilge ihre Sünde nicht aus vor deinem Angesicht, sondern laß sie niedergestürzt vor deinen Augen liegen! Zur Zeit deines Zorngerichts rechne mit ihnen ab!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 19, 1, 'So hat der HERR zu mir gesprochen: »Gehe hin und kaufe dir beim Töpfer einen Krug, nimm dann einige von den Ältesten des Volkes und von den vornehmsten Priestern mit dir');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 19, 2, 'und gehe in das Tal Ben-Hinnom hinaus, das vor dem Eingang des Scherbentors liegt, und rufe dort laut die Worte aus, die ich dir sagen werde!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 19, 3, 'So sprich zu ihnen: Vernehmt das Wort des HERRN, ihr Könige von Juda und ihr Bewohner Jerusalems! So hat der HERR der Heerscharen, der Gott Israels, gesprochen: ›Wisset wohl: ich will Unheil über diesen Ort bringen, daß jedem, der davon hört, die Ohren gellen sollen!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 19, 4, 'Zur Strafe dafür, daß sie mich verlassen und diese Stätte entehrt und an ihr anderen Göttern geopfert haben, von denen weder sie noch ihre Väter noch die Könige von Juda etwas gewußt haben, und weil sie diese Stätte mit dem Blute Unschuldiger erfüllt');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 19, 5, 'und die Baalshöhen erbaut haben, um ihre Kinder als Brandopfer für den Baal zu verbrennen, was ich nie geboten noch angeordnet habe und was mir nie in den Sinn gekommen ist: –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 19, 6, 'darum wisset wohl: die Zeit kommt‹ – so lautet der Ausspruch des HERRN –, ›da wird dieser Ort nicht mehr Thopheth und dieses Tal nicht mehr Tal Ben-Hinnom, sondern Würgetal genannt werden.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 19, 7, 'Da will ich dann die Klugheit Judas und Jerusalems an diesem Orte ausschütten und will sie fallen lassen durch das Schwert (auf der Flucht) vor ihren Feinden her und durch die Hand derer, die ihnen nach dem Leben trachten, und will ihre Leichen den Vögeln des Himmels und den Tieren des Feldes zum Fraß geben.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 19, 8, 'Diese Stadt aber will ich zum abschreckenden Beispiel und zum Gespött machen, so daß jeder, der an ihr vorübergeht, sich entsetzen und wegen aller ihrer Leiden zischen soll.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 19, 9, 'Auch will ich sie das Fleisch ihrer Söhne und das Fleisch ihrer Töchter essen lassen, und sie sollen einer das Fleisch des andern verzehren infolge der Belagerung und Not, in die sie von ihren Feinden und von denen, die ihnen nach dem Leben trachten, versetzt werden.‹');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 19, 10, 'Hierauf sollst du den Krug vor den Augen der Männer, die mit dir gegangen sind, zerschlagen');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 19, 11, 'und zu ihnen sagen: ›So hat der HERR der Heerscharen gesprochen: Ebenso werde ich dieses Volk und diese Stadt zerschmettern, wie man Töpfergeschirr zerschmettert, das dann nicht wiederhergestellt werden kann; und im Thopheth wird man begraben, weil sonst kein Platz mehr zum Begraben vorhanden ist.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 19, 12, 'Auf diese Weise will ich mit diesem Ort verfahren‹ – so lautet der Ausspruch des HERRN – ›und mit seinen Bewohnern: ein Thopheth will ich aus dieser Stadt machen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 19, 13, 'Da sollen dann die Häuser Jerusalems und die Paläste der Könige von Juda ebenso unrein werden wie die Stätte des Thopheth: nämlich alle die Häuser, auf deren Dächern sie dem gesamten Sternenheer des Himmels geräuchert und fremden Göttern Trankspenden ausgegossen haben.‹«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 19, 14, 'Als Jeremia dann vom Thopheth, wohin der HERR ihn zur Verkündigung des Prophetenspruchs gesandt hatte, zurückkehrte, trat er in den Vorhof des Tempels des HERRN und sprach zum ganzen Volk:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 19, 15, '»So hat der HERR der Heerscharen, der Gott Israels, gesprochen: ›Wisset wohl: ich will über diese Stadt und über sämtliche Ortschaften, die zu ihr gehören, all das Unheil kommen lassen, das ich ihr angedroht habe! denn sie haben sich halsstarrig gezeigt, um auf meine Worte nicht zu hören.‹«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 20, 1, 'Als aber der Priester Pashur, der Sohn Immers, der damalige Oberaufseher im Tempel des HERRN, Jeremia diese Weissagung aussprechen hörte,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 20, 2, 'ließ er den Propheten Jeremia stäupen und ihn in den Block legen, der sich im Benjaminstor, dem oberen Tor am Tempel des HERRN, befand.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 20, 3, 'Am folgenden Morgen aber, als Pashur den Jeremia aus dem Block freigelassen hatte, sagte Jeremia zu ihm: »Nicht Pashur nennt der HERR hinfort deinen Namen, sondern ›Grauen ringsum‹!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 20, 4, 'Denn so hat der HERR gesprochen: ›Wisse wohl: ich mache dich zum Grauen für dich selbst und für alle deine Freunde! Denn sie werden durch das Schwert ihrer Feinde fallen, und zwar so, daß du es mit eigenen Augen ansiehst; und ganz Juda will ich der Gewalt des Königs von Babylon preisgeben, damit er sie gefangen nach Babylon wegführt und sie mit dem Schwert erschlägt.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 20, 5, 'Dazu will ich den ganzen Reichtum dieser Stadt, ihren gesamten Besitz samt allen ihren Kostbarkeiten, dahingeben, auch alle Schätze der Könige von Juda ihren Feinden zu eigen geben: die sollen sie plündern und mitnehmen und nach Babylon bringen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 20, 6, 'Du aber, Pashur, und alle deine Hausgenossen – ihr sollt in die Gefangenschaft wandern, und nach Babylon sollst du kommen und dort sterben und dort auch begraben werden, du und alle deine Freunde, denen du falsch geweissagt hast!‹«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 20, 7, 'Du hast mich betört, HERR, und ich habe mich betören lassen; du hast mich überwältigt und bist Sieger geblieben! Zum Gelächter bin ich geworden tagaus tagein, alle Welt verhöhnt mich!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 20, 8, 'Ach, sooft ich rede, muß ich aufschreien, muß ich »Unrecht und Vergewaltigung!« rufen; denn das Wort des HERRN hat mir Hohn und Schmach eingebracht den ganzen Tag!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 20, 9, 'Doch wenn ich mir vornehme: »Ich will seiner nicht mehr gedenken und in seinem Namen nicht mehr reden«, so ist es mir im Innern, als wäre ein loderndes Feuer in meinen Gebeinen eingeschlossen; und mühe ich mich ab, es auszuhalten, so vermag ich es nicht!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 20, 10, 'Ach, ich habe viele schon flüstern hören – Grauen ringsum! –: »Zeigt ihn an!« und »Wir wollen ihn anzeigen!« Alle, die zu meiner Freundschaft gehören, lauern auf einen Fehltritt von mir: »Vielleicht läßt er sich betören, daß wir ihn in der Gewalt haben und Rache an ihm nehmen können!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 20, 11, 'Aber der HERR steht mir bei wie ein gewaltiger Held; darum werden meine Verfolger zu Fall kommen und nichts ausrichten; sie werden sich ganz enttäuscht sehen, weil es ihnen nicht gelungen ist: eine ewige Schmach, die unvergeßlich bleiben wird!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 20, 12, 'Und nun, HERR der Heerscharen, der du den Gerechten prüfst, Nieren und Herz ansiehst: laß mich deine Rache an ihnen sehen, denn dir habe ich meine Sache anheimgestellt! –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 20, 13, 'Singet dem HERRN, preiset den HERRN, denn er errettet das Leben des Armen aus der Hand der Übeltäter!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 20, 14, 'Verflucht sei der Tag, an dem ich geboren ward! Der Tag, an dem meine Mutter mich geboren hat, bleibe ungesegnet!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 20, 15, 'Verflucht sei der Mann, der meinem Vater die frohe Botschaft brachte: »Ein Kind, ein Sohn ist dir geboren!« und ihn dadurch hoch erfreute!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 20, 16, 'Diesem Manne möge es ergehen wie den Städten, die der HERR erbarmungslos zerstört hat: er höre Wehgeschrei am Morgen und Kriegslärm zur Mittagszeit!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 20, 17, 'Warum hat er mich nicht schon im Mutterschoß sterben lassen, so daß meine Mutter mein Grab geworden wäre und ihr Schoß mich immerfort getragen hätte!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 20, 18, 'Warum nur bin ich aus dem Mutterschoß zur Welt gekommen? Doch nur, um Mühsal und Herzeleid zu erleben und damit meine Tage in Schande vergingen!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 21, 1, '(Dies ist) das Wort, das vom HERRN an Jeremia erging, als der König Zedekia Pashur, den Sohn Malkijas, und den Priester Zephanja, den Sohn Maasejas, zu ihm gesandt hatte mit dem Auftrage:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 21, 2, '»Befrage doch den HERRN für uns! Denn Nebukadnezar, der König von Babylon, führt Krieg mit uns; vielleicht tut der HERR wie schon oft ein Wunder an uns, daß jener von uns abziehen muß!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 21, 3, 'Da sagte Jeremia zu ihnen: »Bringt dem Zedekia folgende Antwort:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 21, 4, 'So hat der HERR, der Gott Israels, gesprochen: ›Wisset wohl: die Kriegswaffen in eurer Hand, mit denen ihr bisher gegen den König von Babylon und gegen die Chaldäer, die euch belagern, außerhalb der Stadtmauer gekämpft habt, die will ich umwenden und sie ins Innere dieser Stadt zuhauf hineinbringen;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 21, 5, 'und ich will selbst gegen euch kämpfen mit hocherhobener Hand und starkem Arm, mit Zorn und Grimm und voller Wut;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 21, 6, 'und ich will die Bewohner dieser Stadt niederschlagen, sowohl Menschen als Vieh: an einer verheerenden Seuche sollen sie sterben!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 21, 7, 'Hierauf aber‹ – so lautet der Ausspruch des HERRN – ›will ich Zedekia, den König von Juda, samt seinen Dienern und dem Volke, soweit sie in dieser Stadt von der Seuche, vom Schwert und vom Hunger verschont geblieben sind, in die Hand Nebukadnezars, des Königs von Babylon, und in die Hand ihrer Feinde und in die Hand derer, die ihnen nach dem Leben trachten, fallen lassen, damit er sie mit der Schärfe des Schwertes niederhaue, ohne Mitleid mit ihnen zu haben und ohne Schonung und Erbarmen zu üben!‹«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 21, 8, '»Zu dem Volke hier aber sollst du sagen: ›So hat der HERR gesprochen: Wisset wohl: ich lasse euch die Wahl zwischen dem Wege, der zum Leben führt, und dem Wege zum Tode:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 21, 9, 'Wer hier in der Stadt bleibt, der wird durch das Schwert, durch den Hunger oder durch die Pest ums Leben kommen; wer aber hinausgeht und sich den Chaldäern ergibt, die euch belagern, der wird erhalten bleiben und sein Leben in Sicherheit bringen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 21, 10, 'Denn ich habe mein Angesicht gegen diese Stadt gerichtet zum Unheil und nicht zum Segen‹ – so lautet der Ausspruch des HERRN –: ›sie soll in die Hand des Königs von Babylon gegeben werden, damit er sie in Flammen aufgehen läßt!‹«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 21, 11, '»Sodann sollst du zum Hause des Königs von Juda sagen: ›Vernehmt das Wort des HERRN, ihr vom Hause Davids!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 21, 12, 'So hat der HERR gesprochen: Haltet an jedem Morgen gerechtes Gericht und rettet den Bedrückten aus der Hand des Gewalttätigen, damit mein Zorn nicht wie Feuer hervorbricht und unauslöschlich brennt infolge der Bosheit eurer Taten!‹«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 21, 13, '»Wisse wohl: ich will an dich, Bewohnerin des Tals, du Fels in der Ebene!« – so lautet der Ausspruch des HERRN. »Ihr sagt: ›Wer sollte über uns herfallen und wer in unsere Wohnungen eindringen?‹');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 21, 14, 'Nun, ich will euch heimsuchen, wie eure Taten es verdienen« – so lautet der Ausspruch des HERRN –, »und will ein Feuer in ihrem Walde entfachen, das ihre ganze Umgebung verzehren soll!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 22, 1, 'So hat der HERR zu mir gesprochen: »Gehe zum Palast des Königs von Juda hinab und richte dort folgende Botschaft aus:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 22, 2, '›Vernimm das Wort des HERRN, König von Juda, der du auf dem Throne Davids sitzest, du samt deinen Dienern und deinen Untertanen, die ihr durch diese Tore (der Königsburg) eingeht!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 22, 3, 'So hat der HERR gesprochen: Laßt Recht und Gerechtigkeit walten, rettet den Beraubten aus der Hand des Gewalttätigen, bedrückt und vergewaltigt keinen Fremdling, keine Waise und Witwe und vergießt kein unschuldiges Blut an diesem Ort!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 22, 4, 'Denn nur, wenn ihr dieses Gebot wirklich befolgt, werden durch die Tore dieses Palastes Könige einziehen, die auf Davids Thron sitzen und auf Wagen einherfahren und auf Rossen reiten, er selbst und seine Diener und seine Untertanen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 22, 5, 'Wenn ihr aber diesen Weisungen nicht nachkommt, so habe ich bei mir selbst geschworen‹ – so lautet der Ausspruch des HERRN –, ›daß dieser Palast zu einer Trümmerstätte werden soll!‹«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 22, 6, 'Denn so hat der HERR in betreff des Palastes des Königs von Juda gesprochen: »Ein Gilead bist du mir, der Gipfel des Libanons; doch wahrlich, ich will dich zur Wüste machen, zu unbewohnten Städten,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 22, 7, 'und ich will Verwüster gegen dich in Dienst nehmen, einen jeden mit seinen Gerätschaften: die sollen deine prachtvollen Zedern umhauen und ins Feuer werfen!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 22, 8, 'Wenn dann viele Völkerschaften an dieser Stadt vorüberziehen und einer den andern fragt: ›Warum ist doch der HERR mit dieser großen Stadt so schlimm verfahren?‹,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 22, 9, 'so wird man antworten: ›Zur Strafe dafür, daß sie dem Bunde mit dem HERRN, ihrem Gott, untreu geworden sind und andere Götter angebetet und ihnen gedient haben.‹«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 22, 10, 'Weint nicht um den Toten und klagt nicht um ihn! Weint vielmehr um den, der weggezogen ist! Denn er kehrt nie wieder zurück und sieht das Land seiner Geburt nicht wieder.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 22, 11, 'Denn der HERR hat über Sallum, den Sohn Josias, des Königs von Juda, der seinem Vater Josia in der Regierung gefolgt war und aus diesem Ort weggezogen ist, folgendermaßen gesprochen: »Er wird nicht wieder hierher zurückkehren.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 22, 12, 'Nein, an dem Orte, wohin man ihn in die Gefangenschaft geführt hat, dort wird er sterben und dieses Land nicht wiedersehen.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 22, 13, 'Wehe dem, der sein Haus mit Ungerechtigkeit baut und seine Obergemächer mit Unrecht! Der seinen Nächsten ohne Entgelt arbeiten läßt und ihm seinen Lohn vorenthält!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 22, 14, 'Der da ausspricht: »Ich will mir ein geräumiges Haus bauen mit weitgedehnten Gemächern, von Fenstern durchbrochen und mit Zedernholz getäfelt und mit Zinnober rot gestrichen!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 22, 15, 'Siehst du dein Königtum darin bestehen, daß du dich für Zedernholz begeisterst? Dein Vater hat ja auch gegessen und getrunken, aber er hat Recht und Gerechtigkeit geübt: da erging es ihm gut;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 22, 16, 'er hat den Armen und Elenden zu ihrem Recht verholfen: da stand alles gut. »Heißt nicht das mich recht erkennen?« – so lautet der Ausspruch des HERRN.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 22, 17, 'Dagegen deine Augen und dein Herz sind nur auf Gewinn für dich gerichtet und auf das Blut Unschuldiger, um es zu vergießen, und auf Bedrückung und Erpressung, um sie zu verüben.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 22, 18, 'Darum hat der HERR über Jojakim, den Sohn Josias, den König von Juda, also gesprochen: »Man wird nicht um ihn klagen: ›Ach, mein Bruder!‹ und ›Ach, seine Bruderschaft!‹, man wird nicht um ihn klagen: ›Ach, Gebieter!‹ und ›Ach, seine Hoheit!‹');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 22, 19, 'Nein, eines Esels Bestattung wird man an ihm vollziehen, wird ihn hinausschleifen und hinwerfen weit außerhalb der Tore Jerusalems!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 22, 20, '»Steige (Volk von Jerusalem) auf den Libanon und schreie laut! Laß deinen Klageruf in Basan erschallen und schreie vom Berge Abarim herab! Denn zerschmettert sind alle deine Liebhaber.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 22, 21, 'Ich habe zu dir geredet zur Zeit deines ungetrübten Glücks, doch du antwortetest: ›Ich will nichts davon hören!‹ Das war so deine Art von Jugend auf, du wolltest auf mich nicht hören.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 22, 22, 'Alle deine Hirten wird nun der Sturmwind auf die Weide führen, und deine Liebhaber müssen in die Gefangenschaft wandern! Ja, alsdann wirst du beschämt und enttäuscht dastehen ob all deiner Bosheit!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 22, 23, 'Die du jetzt auf dem Libanon thronst, in Zedern eingenistet: wie wirst du stöhnen, wenn Wehen dich überfallen, Krämpfe wie ein Weib in Kindesnöten!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 22, 24, '»So wahr ich lebe!« – so lautet der Ausspruch des HERRN –: »wäre auch Konja, der Sohn Jojakims, der König von Juda, ein Siegelring an meiner rechten Hand, so wollte ich dich doch von da abreißen');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 22, 25, 'und dich in die Hand derer geben, die dir nach dem Leben trachten, und in die Hand derer, vor denen dir graut, und zwar in die Hand Nebukadnezars, des Königs von Babylon, und in die Hand der Chaldäer.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 22, 26, 'Und ich will dich samt deiner Mutter, die dich geboren hat, in ein fremdes Land schleudern, in dem ihr nicht geboren seid, und dort werdet ihr sterben!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 22, 27, 'In das Land aber, in das sie sich sehnen zurückzukehren, dahin werden sie nie zurückkehren!« –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 22, 28, 'Ist denn dieser Mann Konja ein verächtliches, zerschlagenes Gefäß oder ein Gerät, an dem niemand Gefallen findet? Warum sind sie weggeschleudert worden, er samt seinen Kindern, und in ein Land geworfen, das sie nicht kannten? –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 22, 29, 'O Land, Land, Land, vernimm das Wort des HERRN!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 22, 30, 'So hat der HERR gesprochen: »Schreibt diesen Mann in die Listen als kinderlos ein, als einen Mann, der in seinen Lebenstagen kein Gelingen haben wird! Denn keinem von seinen Nachkommen wird es gelingen, auf Davids Thron zu sitzen und noch einmal über Juda zu herrschen!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 1, '»Wehe den Hirten, welche die Schafe meiner Weide zugrunde richten und sich zerstreuen lassen!« – so lautet der Ausspruch des HERRN.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 2, 'Darum hat der HERR, der Gott Israels, in betreff der Hirten, die mein Volk weiden, so gesprochen: »Ihr seid es, die meine Schafe zerstreut und versprengt und nicht acht auf sie gegeben haben; darum will ich euch jetzt wegen der Bosheit eures ganzen Tuns zur Rechenschaft ziehen!« – so lautet der Ausspruch des HERRN.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 3, '»Ich selbst will aber auch den Überrest meiner Herde aus all den Ländern, wohin ich sie versprengt habe, sammeln und sie auf ihre Trift zurückführen: da werden sie fruchtbar sein und gedeihen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 4, 'Dann will ich Hirten über sie erstehen lassen, die sie weiden sollen, daß sie sich nicht weiterhin zu fürchten brauchen und nicht erschrecken müssen und daß keines vermißt wird!« – so lautet der Ausspruch des HERRN.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 5, '»Wisset wohl: es kommt die Zeit« – so lautet der Ausspruch des HERRN –, »da will ich dem David einen rechten Sproß erwecken: der wird als König herrschen und mit Weisheit handeln und Recht und Gerechtigkeit im Lande walten lassen!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 6, 'In seinen Tagen wird Juda gerettet werden und Israel in Sicherheit wohnen, und der Name, den man ihm beilegt, wird lauten: ›Der HERR unsere Gerechtigkeit‹.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 7, 'Darum wisset wohl: es kommt die Zeit« – so lautet der Ausspruch des HERRN –, »da wird man nicht mehr sagen: ›So wahr der HERR lebt, der die Kinder Israel aus dem Lande Ägypten hergeführt hat!‹,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 8, 'sondern: ›So wahr der HERR lebt, der die zum Hause Israel Gehörigen aus dem Nordland und aus all den Ländern, wohin ich sie versprengt hatte, hergeführt und heimgebracht hat, damit sie wieder auf ihrem Grund und Boden wohnten!‹«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 9, '[Über die Propheten:] Gebrochen ist mir das Herz in der Brust, es zittern mir alle Glieder; mir ist zu Sinn wie einem Trunkenen, wie einem Manne, den der Wein übermannt hat, vor dem HERRN und vor seinen heiligen Worten!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 10, 'Ach, das Land ist voll von Ehebrechern! Ach, unter dem Fluch liegt das Land in Trauer darnieder, sind die Auen der Trift verdorrt, weil ihr ganzes Trachten Bosheit ist und ihr Schalten Unredlichkeit.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 11, '»Denn beide, Propheten und Priester, sind ruchlos: sogar in meinem Tempel habe ich ihr böses Treiben angetroffen!« – so lautet der Ausspruch des HERRN.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 12, '»Darum soll ihr Weg für sie werden wie schlüpfriger Boden: in der Dunkelheit sollen sie anstoßen, daß sie auf ihm zu Fall kommen; denn ich will Unheil, will das Jahr ihrer Heimsuchung über sie bringen!« – so lautet der Ausspruch des HERRN.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 13, '»Schon an den Propheten Samarias habe ich Ärgerliches erlebt: sie weissagten im Namen des Baal und führten mein Volk Israel irre;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 14, 'aber an den Propheten Jerusalems habe ich Grauenvolles erlebt: Ehebruch und Wandel in der Lüge, und sie bestärken die Übeltäter in ihrem Tun, damit sich ja keiner von ihnen von seiner Bosheit bekehre. Ich achte sie allesamt den Leuten von Sodom gleich und die Bewohner ihrer Stadt den Leuten von Gomorrha!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 15, 'Darum hat der HERR der Heerscharen über die Propheten so gesprochen: »Fürwahr, ich will sie mit Wermut speisen und ihnen Giftwasser zu trinken geben; denn von den Propheten Jerusalems hat sich Verworfenheit über das ganze Land verbreitet!« –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 16, 'So hat der HERR der Heerscharen gesprochen: »Hört nicht auf die Worte der Propheten, die euch weissagen! Sie machen euch nur Wind vor: selbstersonnene Gesichte verkünden sie euch ohne den Auftrag des HERRN.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 17, 'Sie sagen immerdar zu denen, die mich verachten: ›Der HERR hat verheißen: Es wird euch wohl ergehen!‹, und zu allen, die im Starrsinn ihres Herzens dahinwandeln, sagen sie: ›Es wird euch kein Unheil widerfahren!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 18, 'Denn wer hat im Ratskreise des HERRN gestanden, daß er ihn gesehen und sein Wort gehört hätte? Wer hat sein Wort erlauscht und gehört?‹');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 19, 'Wisset wohl: ein Sturmwind des HERRN, sein Grimm, bricht los und wirbelnde Windsbraut, die auf das Haupt der Gottlosen niederfährt!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 20, 'Nicht nachlassen wird der lodernde Zorn des HERRN, bis er’s vollbracht und die Gedanken seines Herzens vollführt hat: am Ende der Tage werdet ihr das schon klar erkennen!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 21, 'Ich habe diese Propheten nicht gesandt, und doch haben sie es eilig! Ich habe ihnen keinen Auftrag gegeben, und doch weissagen sie!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 22, 'Hätten sie wirklich in meinem Ratskreise gestanden, so würden sie meinem Volk meine Worte verkünden und es von seinem bösen Wandel und seinem gottlosen Tun abbringen!« –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 23, '»Bin ich denn ein Gott, der nur in die Nähe sieht« – so lautet der Ausspruch des HERRN –, »und nicht ein Gott auch aus der Ferne?');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 24, 'Oder kann sich jemand in Schlupfwinkeln so verstecken, daß ich ihn nicht sähe?« – so lautet der Ausspruch des HERRN. »Bin ich es nicht, der den Himmel und die Erde erfüllt?« – so lautet der Ausspruch des HERRN.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 25, '»Ich habe wohl gehört, was die Propheten sagen, die in meinem Namen Lügen weissagen, wenn sie verkünden: ›Ich habe einen Traum gehabt, einen Traum!‹');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 26, 'Wie lange soll das bei ihnen noch so fortgehen? Haben etwa diese Lügenpropheten, die selbstersonnenen Trug weissagen, im Sinn,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 27, 'ja, haben sie die Absicht, durch ihre Träume, die sie einander erzählen, meinen Namen bei meinem Volke ebenso in Vergessenheit zu bringen, wie ihre Väter meinen Namen über dem Baal vergessen haben?');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 28, 'Der Prophet, dem (wirklich) ein Traum zuteil geworden ist, erzähle ihn als Traum, und wem mein Wort zuteil geworden ist, verkünde mein Wort der Wahrheit gemäß! Was hat das Stroh mit dem Korn gemein?« – so lautet der Ausspruch des HERRN.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 29, '»Ist mein Wort nicht also: wie Feuer?« – so lautet der Ausspruch des HERRN – »und wie ein Hammer, der Felsen zerschlägt?');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 30, 'Darum wisset wohl: ich will an die Propheten« – so lautet der Ausspruch des HERRN –, »die meine Worte einer dem andern stehlen!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 31, 'Ja, wisset wohl: ich will an die Propheten« – so lautet der Ausspruch des HERRN –, »die ihre Zunge dazu mißbrauchen, Gottessprüche zu verkünden!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 32, 'Ja, wisset wohl: ich will an die (Propheten), welche Lügenträume weissagen« – so lautet der Ausspruch des HERRN – »und sie anderen erzählen und mein Volk durch ihre Lügen und ihre Gaukelei irreführen, während ich sie doch nicht gesandt und ihnen keinen Auftrag gegeben habe und sie diesem Volke gar keinen Nutzen schaffen!« – so lautet der Ausspruch des HERRN.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 33, '»Wenn aber dieses Volk oder ein Prophet oder ein Priester dich fragen sollte: ›Was ist die Last des HERRN?‹, so antworte ihnen: ›Ihr seid die Last, und ich will euch abwerfen! – so lautet der Ausspruch des HERRN.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 34, 'Der Prophet aber und der Priester und wer vom Volk noch von der Last des HERRN redet – einen solchen Menschen will ich es büßen lassen samt seinem Hause!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 35, 'Ihr sollt vielmehr zueinander und untereinander so sagen: ›Was hat der HERR geantwortet?‹ und ›Was hat der HERR verkündigt?‹');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 36, 'Aber den Ausdruck ›Last des HERRN‹ sollt ihr nicht mehr gebrauchen, sonst soll einem jeden diese seine Redeweise zur Last werden! Denn ihr würdet damit die Worte des lebendigen Gottes, des HERRN der Heerscharen, unsers Gottes, verkehren.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 37, 'So sollst du den Propheten fragen: ›Was hat der HERR dir geantwortet?‹ oder ›Was hat der HERR verkündigt?‹');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 38, 'Wenn ihr aber den Ausdruck ›Last des HERRN‹ gebraucht – nun, so hat der HERR folgendermaßen gesprochen: Zur Strafe dafür, daß ihr diesen Ausdruck ›Last des HERRN‹ gebraucht, obgleich ich euch habe gebieten lassen, den Ausdruck ›Last des HERRN‹ nicht zu gebrauchen,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 39, 'darum wisset wohl: Ich will euch aufheben wie eine Last und wegwerfen euch samt der Stadt, die ich euch und euren Vätern gegeben habe, von meinem Angesicht hinweg,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 40, 'und will ewige Schmach über euch verhängen und ewige Schande, die nie vergessen werden soll!‹«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 24, 1, 'Der HERR hat mich (folgendes Gesicht) schauen lassen: Ich gewahrte zwei Körbe mit Feigen, die vor dem Tempel des HERRN aufgestellt waren – nachdem Nebukadnezar, der König von Babylon, Jechonja, den Sohn Jojakims, den König von Juda, und die Oberen von Juda samt den Schmieden und Schlossern aus Jerusalem in die Gefangenschaft geführt und sie nach Babylon gebracht hatte.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 24, 2, 'Der eine Korb enthielt sehr gute Feigen, wie Frühfeigen zu sein pflegen; in dem andern Korbe aber befanden sich sehr schlechte Feigen, die wegen ihrer schlechten Beschaffenheit ungenießbar waren.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 24, 3, 'Da fragte mich der HERR: »Was siehst du, Jeremia?« Ich antwortete: »Feigen! Die guten Feigen sind sehr gut, aber die schlechten ganz schlecht, so daß man sie vor Schlechtigkeit nicht genießen kann.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 24, 4, 'Da erging das Wort des HERRN an mich folgendermaßen:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 24, 5, '»So spricht der HERR, der Gott Israels: Wie diese guten Feigen hier, so will ich die gefangenen Judäer, die ich aus diesem Ort in das Land der Chaldäer habe wegführen lassen, freundlich ansehen:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 24, 6, 'ich will mein Auge zum Guten auf sie richten und sie in dieses Land zurückkehren lassen, um sie neu aufzubauen, ohne sie wieder niederzureißen, und um sie einzupflanzen, ohne sie wieder auszureißen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 24, 7, 'Und ich will ihnen ein Herz verleihen, mich zu erkennen, daß ich der HERR bin; und sie sollen mein Volk sein, und ich will ihr Gott sein, denn sie werden sich mit ihrem ganzen Herzen zu mir bekehren. –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 24, 8, 'Aber wie die schlechten Feigen, die so schlecht sind, daß man sie nicht genießen kann« – ja, so hat der HERR gesprochen –, »ebenso will ich Zedekia, den König von Juda, machen samt seinen Oberen und denen, die von den Bewohnern Jerusalems in diesem Lande zurückgeblieben sind, und auch denen, die sich in Ägypten niedergelassen haben:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 24, 9, 'ich will sie zum abschreckenden Beispiel des Unglücks für alle Reiche der Erde machen, zum Schimpf und zum Hohn, zur Spottrede und zum Fluchwort an allen Orten, wohin ich sie verstoßen werde;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 24, 10, 'und ich will das Schwert, den Hunger und die Pest gegen sie loslassen, bis sie ganz aus dem Lande vertilgt sind, das ich ihnen und ihren Vätern gegeben habe.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 25, 1, '(Dies ist) das Wort, das an Jeremia über das ganze Volk Juda ergangen ist im vierten Regierungsjahre Jojakims, des Sohnes Josias, des Königs von Juda – es war dies das erste Regierungsjahr Nebukadnezars, des Königs von Babylon –;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 25, 2, 'der Prophet Jeremia hat dies Wort an das ganze Volk von Juda und an alle Einwohner Jerusalems gerichtet, indem er sprach:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 25, 3, '»Seit dem dreizehnten Regierungsjahre Josias, des Sohnes Amons, des Königs von Juda, bis auf den heutigen Tag, nun schon dreiundzwanzig Jahre lang, ist das Wort des HERRN an mich ergangen, und ich habe unermüdlich früh und spät zu euch geredet, aber ihr habt nicht darauf gehört.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 25, 4, 'Dazu hat der HERR alle seine Knechte, die Propheten, unermüdlich früh und spät zu euch gesandt, aber ihr habt ihnen nicht gehorcht und ihnen kein Gehör geschenkt, um euch warnen zu lassen,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 25, 5, 'indem er euch sagen ließ: ›Kehrt doch um, ein jeder von seinem bösen Wandel und von seinem verwerflichen Tun, dann sollt ihr in dem Lande, das der HERR euch und euren Vätern gegeben hat, wohnen bleiben bis in alle Ewigkeit!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 25, 6, 'Lauft also nicht anderen Göttern nach, um ihnen zu dienen und sie anzubeten, und reizt mich nicht zum Zorn durch die Machwerke eurer Hände, damit ich kein Unglück über euch verhänge!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 25, 7, 'Aber ihr habt nicht auf mich gehört‹ – so lautet der Ausspruch des HERRN –, ›sondern habt mich geflissentlich zum Zorn gereizt durch die Machwerke eurer Hände, euch selbst zum Unheil.‹«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 25, 8, 'Darum hat der HERR der Heerscharen so gesprochen: »Zur Strafe dafür, daß ihr auf meine Worte nicht gehört habt,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 25, 9, 'will ich nunmehr alle Völkerschaften des Nordens herbeiholen« – so lautet der Ausspruch des HERRN – »und an meinen Knecht Nebukadnezar, den König von Babylon, Botschaft senden und sie gegen dies Land und seine Bewohner und gegen alle diese Völker ringsum hereinbrechen lassen; und ich will den Bann über sie verhängen und sie zum Gegenstand des Entsetzens und des Spottes und zu ewigen Einöden machen;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 25, 10, 'und will unter ihnen jeder lauten Freude und Fröhlichkeit, jedem Bräutigamsjubel und jedem Brautgesang, dem Schall der Handmühlen und dem Licht der Lampen ein Ende machen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 25, 11, 'Dieses ganze Land soll zur Einöde, zur Wüste werden, und diese Völkerschaften sollen dem Könige von Babylon dienstbar sein siebzig Jahre lang.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 25, 12, 'Wenn aber die siebzig Jahre um sind, dann will ich auch am König von Babylon und an jenem Volk« – so lautet der Ausspruch des HERRN – »das Strafgericht wegen ihrer Verschuldung vollziehen, auch am Lande der Chaldäer, und will es auf ewig zu Wüsteneien machen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 25, 13, 'Ich will dann an jenem Lande alle meine Drohungen, die ich gegen dasselbe ausgesprochen habe, in Erfüllung gehen lassen, alles, was in diesem Buche geschrieben steht, was Jeremia über alle Völker geweissagt hat.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 25, 14, 'Denn sie sollen gleichfalls mächtigen Völkern und gewaltigen Königen dienstbar werden, und ich werde ihnen nach Verdienst und nach ihrem ganzen Tun vergelten.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 25, 15, 'Denn so hat der HERR, der Gott Israels, zu mir gesprochen: »Nimm diesen Becher voll Zornweins aus meiner Hand und laß alle Völker, zu denen ich dich senden werde, daraus trinken!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 25, 16, 'Sie sollen trinken, daß sie hin und her taumeln und in Tollheit rasen ob dem Schwert, das ich unter sie sende!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 25, 17, 'Da nahm ich den Becher aus der Hand des HERRN und ließ alle Völker daraus trinken, zu denen der HERR mich gesandt hatte:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 25, 18, 'Jerusalem und die anderen Städte Judas, ihre Könige und ihre Fürsten, um sie zur Einöde, zum abschreckenden Beispiel, zum Gegenstand des Spottes und zum Fluchwort zu machen, wie es heutzutage der Fall ist;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 25, 19, 'sodann den Pharao, den König von Ägypten, samt seinen Dienern und obersten Beamten und seinem ganzen Volk');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 25, 20, 'und das gesamte Völkergemisch dort; sodann alle Könige des Landes Uz und alle Könige des Philisterlandes, nämlich Askalon, Gaza, Ekron und den Überrest von Asdod;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 25, 21, 'Edom, Moab und die Ammoniter;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 25, 22, 'alle Könige von Tyrus, alle Könige von Sidon und die Könige der Küstenländer jenseits des Meeres;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 25, 23, 'ferner Dedan, Thema, Bus und alle, die sich das Haar an den Schläfen stutzen;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 25, 24, 'sodann alle Könige von Arabien und alle Könige der Mischvölker, die in der Wüste wohnen;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 25, 25, 'ferner alle Könige von Simri und alle Könige von Elam und alle Könige von Medien;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 25, 26, 'sodann alle Könige des Nordens, die nahen wie die fernen, einen nach dem andern, überhaupt alle Königreiche der Welt, soviele ihrer auf dem ganzen Erdboden sind; der König von Sesach aber muß nach ihnen trinken.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 25, 27, '»Du sollst dabei zu ihnen sagen: ›So hat der HERR der Heerscharen, der Gott Israels, gesprochen: Trinkt, bis ihr trunken seid und euch erbrecht! Stürzt hin, ohne wieder aufzustehen – ob dem Schwert, das ich unter euch sende!‹');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 25, 28, 'Sollten sie sich aber weigern, den Becher aus deiner Hand zu nehmen, um aus ihm zu trinken, so sollst du zu ihnen sagen: ›So hat der HERR der Heerscharen gesprochen: Trinken müßt ihr dennoch!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 25, 29, 'Denn wisset wohl: Bei der Stadt, die nach meinem Namen genannt ist, habe ich mit dem Strafgericht den Anfang gemacht, und da solltet ihr frei ausgehen? Nein, ihr sollt nicht ungestraft bleiben; denn das Schwert biete ich gegen alle Bewohner der Erde auf!‹« – so lautet der Ausspruch des HERRN der Heerscharen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 25, 30, '»Du aber sollst bei der Verkündigung aller dieser Drohworte zu ihnen sagen: ›Der HERR brüllt aus der Höhe und läßt seine Stimme erschallen aus seiner heiligen Wohnstätte! Laut brüllt er über seine Aue hin, läßt ein Jauchzen erschallen wie die Keltertreter gegen alle Bewohner der Erde.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 25, 31, 'Bis ans Ende der Erde dringt der Schall; denn der HERR geht mit den Völkern ins Gericht; er bringt seine Sache mit der ganzen Menschheit zum Austrag: die Gottlosen gibt er dem Schwerte preis!‹« – so lautet der Ausspruch des HERRN.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 25, 32, 'So hat der HERR der Heerscharen gesprochen: »Fürwahr, Unheil schreitet von Volk zu Volk, und ein gewaltiger Sturm zieht heran von den Enden der Erde!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 25, 33, 'An jenem Tage werden die vom HERRN Erschlagenen von einem Ende der Erde bis zum andern daliegen, unbetrauert und ohne aufgehoben und begraben zu werden: zu Dünger müssen sie auf offenem Felde werden.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 25, 34, '»Heult, ihr Völkerhirten, und schreit! Und wälzt euch (in der Asche), ihr Führer der Herde! Denn eure Zeit ist erfüllt, daß man euch schlachte, und ich zerschmettere euch, daß ihr zu Boden fallen sollt wie kostbares Geschirr!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 25, 35, 'Da gibt es kein Entfliehen mehr für die Hirten und kein Entrinnen für die Führer der Herde.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 25, 36, 'Horch! Angstgeschrei der Hirten und Geheul der Führer der Herde! Denn der HERR verwüstet ihre Weide,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 25, 37, 'und verheert werden die friedlichen Auen vor dem lodernden Zorn des HERRN!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 25, 38, 'Wie ein Löwe hat er sein Dickicht verlassen: ach, ihr Land ist zur Wüste geworden vor dem verheerenden Schwert und vor seinem lodernden Zorn!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 26, 1, 'Im Anfang der Regierung Jojakims, des Sohnes Josias, des Königs von Juda, erging folgendes Wort des HERRN (an Jeremia):');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 26, 2, 'So spricht der HERR: »Stelle dich auf im Vorhof des Tempels des HERRN und verkünde denen, die aus allen Ortschaften Judas herkommen, um im Tempel des HERRN anzubeten, alle Worte, deren Verkündigung ich dir geboten habe: laß kein Wort davon weg!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 26, 3, 'Vielleicht hören sie darauf und bekehren sich, ein jeder von seinem bösen Wandel; dann würde ich mir auch das Unheil leid sein lassen, das ich ihnen wegen ihres bösen Tuns zuzufügen gedenke.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 26, 4, 'Und zwar sollst du zu ihnen sagen: ›So hat der HERR gesprochen: Wenn ihr mir nicht gehorcht und nicht nach meinem Gesetz wandelt, das ich euch vorgelegt habe,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 26, 5, 'und wenn ihr nicht auf die Worte meiner Knechte, der Propheten, hört, die ich früh und spät immer wieder zu euch sende, ohne daß ihr auf sie hört:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 26, 6, 'so will ich mit diesem Tempel hier verfahren wie einst mit dem zu Silo und will den Namen dieser Stadt zum Fluchwort für alle Völker der Erde machen!‹«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 26, 7, 'Als nun die Priester und Propheten und das gesamte Volk den Jeremia diese Worte im Tempel des HERRN verkündigen hörten');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 26, 8, 'und Jeremia mit der Verkündigung alles dessen, was er dem ganzen Volke nach dem Befehl des HERRN vorhalten sollte, zu Ende war, da ergriffen ihn die Priester, die Propheten und das gesamte Volk und riefen: »Jetzt mußt du sterben!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 26, 9, 'Warum hast du im Namen des HERRN die Weissagung ausgesprochen, es werde diesem Hause ergehen wie dem zu Silo und diese Stadt werde so wüst werden, daß niemand mehr darin wohne?« So rottete sich denn das gesamte Volk im Tempel des HERRN gegen Jeremia zusammen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 26, 10, 'Als nun die Fürsten von Juda von diesen Vorgängen Kunde erhielten, begaben sie sich aus dem Palast des Königs zum Tempel des HERRN hinauf und ließen sich zum Gericht nieder im Eingang des neuen Tores am Tempel des HERRN.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 26, 11, 'Hierauf gaben die Priester und die Propheten vor den Fürsten und dem gesamten Volke die Erklärung ab: »Dieser Mann ist des Todes schuldig; denn er hat gegen diese Stadt geweissagt, wie ihr mit eigenen Ohren gehört habt.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 26, 12, 'Jeremia aber richtete an alle Fürsten und an das gesamte Volk folgende Worte: »Der HERR hat mich gesandt, damit ich gegen diesen Tempel und gegen diese Stadt alle die Drohworte ausspreche, die ihr vernommen habt.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 26, 13, 'Und nun – bessert euren Wandel und euer ganzes Tun und gehorcht den Weisungen des HERRN, eures Gottes, damit der HERR sich das Unheil leid sein läßt, das er euch angedroht hat!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 26, 14, 'Was mich aber betrifft, so stehe ich hier in eurer Gewalt: verfahrt mit mir, wie es euch gut und recht dünkt!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 26, 15, 'Nur das sollt ihr bestimmt wissen: Wenn ihr mich tötet, werdet ihr unschuldiges Blut über euch, über diese Stadt und ihre Bewohner bringen; denn der HERR hat mich wahrhaftig zu euch gesandt, damit ich alle diese Worte laut an euch richte.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 26, 16, 'Da sagten die Fürsten und das gesamte Volk zu den Priestern und den Propheten: »Dieser Mann ist des Todes nicht schuldig, denn er hat im Auftrage des HERRN, unsers Gottes, zu uns geredet.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 26, 17, 'Hierauf traten auch Männer von den Ältesten des Landes auf und sagten zu der ganzen versammelten Volksmenge:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 26, 18, '»Micha aus Moreseth ist unter der Regierung Hiskias, des Königs von Juda, als Prophet aufgetreten und hat zum ganzen Volk von Juda gesagt: ›So hat der HERR der Heerscharen gesprochen: Zion wird zu Ackerland umgepflügt werden, und Jerusalem wird zu einem Trümmerhaufen und der Tempelberg zu einer bewaldeten Höhe werden!‹');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 26, 19, 'Haben nun etwa Hiskia, der König von Juda, und ganz Juda ihn dafür getötet? Hat Hiskia nicht vielmehr den HERRN gefürchtet und den HERRN zu versöhnen gewußt, so daß der HERR sich das Unheil leid sein ließ, das er ihnen angedroht hatte? Und wir wollen unser Gewissen mit einer so schweren Schuld beladen?«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 26, 20, 'Es war aber damals noch ein anderer Mann da, der im Namen des HERRN als Prophet wirkte, nämlich Uria, der Sohn Semajas, aus Kirjath-Jearim; und zwar weissagte er gegen diese Stadt und gegen dieses Land mit denselben Worten wie Jeremia.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 26, 21, 'Als nun der König Jojakim und alle seine Heerführer und alle obersten Beamten von seinen Reden hörten, suchte der König ihn zu töten; Uria aber erhielt Kunde davon, und da er sich fürchtete, ergriff er die Flucht und entkam nach Ägypten.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 26, 22, 'Da sandte der König Jojakim Männer nach Ägypten, nämlich Elnathan, den Sohn Achbors, und noch einige andere mit ihm;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 26, 23, 'die holten Uria aus Ägypten und brachten ihn zum König Jojakim, der ihn mit dem Schwert hinrichten und seinen Leichnam auf den Begräbnisplatz des gemeinen Volkes werfen ließ.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 26, 24, 'Aber Jeremias hatte sich (damals) Ahikam, der Sohn Saphans, tatkräftig angenommen, so daß man ihn dem Volk nicht zur Tötung preisgab.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 27, 1, 'Im Anfang der Regierung Zedekias, des Sohnes Josias, des Königs von Juda, erging folgendes Wort an Jeremia vom HERRN:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 27, 2, 'so gebot mir der HERR: »Mache dir Stricke und Jochstäbe und lege sie dir auf den Nacken');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 27, 3, 'und sende (Botschaft) an den König von Edom sowie an den König von Moab, an den König der Ammoniter, an den König von Tyrus und an den König von Sidon durch Vermittlung der Gesandten, die nach Jerusalem zu Zedekia, dem König von Juda, gekommen sind,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 27, 4, 'und trage ihnen folgende Botschaft an ihre Gebieter auf: ›So hat der HERR der Heerscharen, der Gott Israels, gesprochen: Berichtet euren Gebietern folgendes:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 27, 5, 'Ich habe die Erde, die Menschen und die Tiere, die es auf der ganzen Erde gibt, durch meine große Kraft und meinen ausgestreckten Arm geschaffen und gebe sie, wem es mir beliebt.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 27, 6, 'So habe ich nunmehr alle diese Länder der Gewalt meines Kneches Nebukadnezar, des Königs von Babylon, übergeben und sogar die Tiere des Feldes ihm gegeben, daß sie ihm dienstbar seien.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 27, 7, 'So sollen denn alle Völker ihm und seinem Sohne und seinem Enkel untertan sein, bis auch für sein Land die Zeit gekommen ist, wo mächtige Völker und große Könige ihn sich untertan machen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 27, 8, 'Dasjenige Volk und Reich aber, das ihm, dem babylonischen König Nebukadnezar, sich nicht unterwirft und seinen Nacken nicht in das Joch des babylonischen Königs stecken will, ein solches Volk‹ – so lautet der Ausspruch des HERRN – ›will ich mit dem Schwert, mit Hunger und mit der Pest heimsuchen, bis ich es durch seine Hand gänzlich vernichtet habe.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 27, 9, 'So hört ihr nun nicht auf eure Propheten und Wahrsager, auch nicht auf eure Träume, eure Zauberer und Beschwörer, wenn sie euch bestimmt versichern: Ihr werdet dem König von Babylon nicht untertan sein müssen;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 27, 10, 'denn eine Lüge ist es, die sie euch weissagen, um euch aus eurem Lande in die Verbannung zu bringen, weil ich euch alsdann verstoßen werde und ihr zugrunde geht.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 27, 11, 'Dasjenige Volk aber, das seinen Nacken in das Joch des babylonischen Königs steckt und ihm untertan ist, das will ich ruhig in seinem Lande belassen‹ – so lautet der Ausspruch des HERRN –, ›damit es dasselbe bebaut und darin wohnen bleibt.‹«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 27, 12, 'Hierauf richtete ich an Zedekia, den König von Juda, folgende Worte in ganz demselben Sinn: »Steckt euren Nacken in das Joch des Königs von Babylon und unterwerft euch ihm und seinem Volk, so werdet ihr am Leben bleiben!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 27, 13, 'Warum wollt ihr, du und dein Volk, durch das Schwert, durch den Hunger und durch die Pest zugrunde gehen, wie der HERR dem Volke angedroht hat, das sich dem Könige von Babylon nicht unterwerfen will?');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 27, 14, 'Hört nur nicht auf die Reden der Propheten, die euch bestimmt versichern: ›Ihr werdet dem König von Babylon nicht untertan sein müssen!‹, denn eine Lüge ist es, die sie euch weissagen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 27, 15, '›Denn ich habe sie nicht gesandt‹ – so lautet der Ausspruch des HERRN –, ›vielmehr weissagen sie Falsches in meinem Namen, damit ich euch verstoße und ihr elend zugrunde geht, ihr mitsamt den Propheten, die euch weissagen.‹«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 27, 16, 'Hierauf wandte ich mich an die Priester und an das ganze hiesige Volk mit folgenden Worten: »So hat der HERR gesprochen: Hört nicht auf die Reden eurer Propheten, die vor euch die Weissagung aussprechen: ›Fürwahr, die Tempelgeräte des HERRN werden nun gar bald aus Babylon zurückgebracht werden!‹, denn eine Lüge ist es, die sie euch weissagen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 27, 17, 'Hört nicht auf sie, werdet vielmehr dem König von Babylon untertan, so werdet ihr am Leben bleiben: warum soll diese Stadt zu einer Wüste werden?');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 27, 18, 'Sind sie aber wirklich Propheten und sind sie im Besitz des Wortes des HERRN, so mögen sie doch Fürbitte beim HERRN der Heerscharen einlegen, daß die Geräte, die noch im Tempel des HERRN und im Palast des Königs von Juda und in Jerusalem übriggeblieben sind, nicht auch noch nach Babylon kommen!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 27, 19, 'Denn so hat der HERR der Heerscharen bezüglich der Säulen und bezüglich des großen Wasserbeckens sowie bezüglich der Gestühle und der sonstigen Geräte gesprochen, die in dieser Stadt noch zurückgeblieben sind,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 27, 20, 'weil Nebukadnezar, der König von Babylon, sie nicht mitgenommen hat, als er Jechonja, den Sohn Jojakims, den König von Juda, aus Jerusalem nach Babylon in die Gefangenschaft wegführte samt allen vornehmen Männern Judas und Jerusalems –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 27, 21, 'ja, so hat der HERR der Heerscharen, der Gott Israels, bezüglich der Geräte gesprochen, die im Tempel des HERRN und im Palast des Königs von Juda und in Jerusalem noch zurückgeblieben sind:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 27, 22, '›Nach Babylon sollen sie gebracht werden und dort bleiben bis zu dem Tage, an dem ich wieder nach ihnen sehen werde‹ – so lautet der Ausspruch des HERRN – ›und ich sie wieder herschaffe und an diesen Ort zurückbringe.‹«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 28, 1, 'Es begab sich aber in demselben Jahre, im Anfang der Regierung Zedekias, des Königs von Juda, im fünften Monat des vierten Jahres, da sagte der Prophet Hananja, der Sohn Assurs aus Gibeon, im Tempel des HERRN in Gegenwart der Priester und des ganzen Volkes so zu mir:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 28, 2, '»So hat der HERR der Heerscharen, der Gott Israels, gesprochen: ›Ich zerbreche das Joch des Königs von Babylon!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 28, 3, 'Noch vor Ablauf von zwei Jahren will ich alle Tempelgeräte des HERRN, die Nebukadnezar, der König von Babylon, von dieser Stätte weggenommen und nach Babylon gebracht hat, wieder an diese Stätte zurückbringen;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 28, 4, 'auch Jechonja, den Sohn Jojakims, den König von Juda, samt allen Judäern, die nach Babylon in die Verbannung weggeführt sind, will ich an diesen Ort zurückbringen‹ – so lautet der Ausspruch des HERRN –; ›denn ich will das Joch des Königs von Babylon zerbrechen.‹«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 28, 5, 'Da gab der Prophet Jeremia dem Propheten Hananja in Gegenwart der Priester und des gesamten Volkes, das im Tempel des HERRN anwesend war,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 28, 6, 'folgende Antwort: »Ja, so sei es! Der HERR möge es so fügen! Der HERR möge deine Weissagung, die du ausgesprochen hast, in Erfüllung gehen lassen, daß er nämlich die Tempelgeräte des HERRN und alle in die Gefangenschaft Weggeführten aus Babylon an diesen Ort zurückbringt!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 28, 7, 'Jedoch vernimm folgendes Wort, das ich vor deinen Ohren und vor dem gesamten Volk hier laut ausspreche:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 28, 8, '›Die Propheten, die vor mir und vor dir seit den ältesten Zeiten aufgetreten sind, die haben über mächtige Länder und über große Reiche von Krieg, von Unheil und von Pest geweissagt;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 28, 9, 'der Prophet also, der eine Glücksverheißung ausspricht, wird erst dann, wenn seine Prophezeiung eingetroffen ist, als ein Prophet anerkannt werden, den der HERR wirklich gesandt hat!‹«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 28, 10, 'Da nahm der Prophet Hananja die Jochstäbe vom Nacken des Propheten Jeremia und zerbrach sie;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 28, 11, 'sodann sagte Hananja vor dem ganzen Volke: »So hat der HERR gesprochen: ›Ebenso will ich das Joch Nebukadnezars, des Königs von Babylon, noch vor Ablauf von zwei Jahren zerbrechen und es vom Nacken aller Völker wegnehmen!‹« Der Prophet Jeremia aber ging seines Weges.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 28, 12, 'Nachdem aber der Prophet Hananja die Jochstäbe vom Nacken des Propheten Jeremia (genommen und sie) zerbrochen hatte, erging das Wort des HERRN an Jeremia folgendermaßen:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 28, 13, '»Gehe hin und sage zu Hananja: So hat der HERR gesprochen: ›Jochstäbe von Holz hast du zerbrochen, aber Jochstäbe von Eisen an ihre Stelle gesetzt.‹');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 28, 14, 'Denn so hat der HERR der Heerscharen, der Gott Israels, gesprochen: ›Ein eisernes Joch lege ich allen diesen Völkern auf den Nacken, daß sie Nebukadnezar, dem König von Babylon, dienstbar sein müssen; ja, sie sollen ihm dienen, und sogar die wilden Tiere des Feldes habe ich ihm übergeben.‹«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 28, 15, 'Weiter sagte der Prophet Jeremia zu dem Propheten Hananja: »Höre doch, Hananja! Der HERR hat dich nicht gesandt, und doch hast du dieses Volk dazu verführt, sich auf eine Lüge zu verlassen!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 28, 16, 'Darum hat der HERR so gesprochen: ›Wisse wohl: ich will dich vom Erdboden wegschaffen; noch in diesem Jahre sollst du sterben, weil du zum Ungehorsam gegen den HERRN aufgefordert hast!‹«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 28, 17, 'Und der Prophet Hananja starb wirklich noch in demselben Jahre im siebten Monat.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 29, 1, 'Dies ist der Wortlaut des Schreibens, das der Prophet Jeremia von Jerusalem aus an die am Leben gebliebenen Ältesten unter den in die Gefangenschaft Weggeführten und an die Priester und Propheten und überhaupt an das gesamte Volk sandte, das Nebukadnezar von Jerusalem nach Babylon in die Gefangenschaft geführt hatte –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 29, 2, 'nachdem der König Jechonja und die Königin-Mutter nebst den Hofbeamten, den Fürsten von Juda und Jerusalem, den Schmieden und Schlossern aus Jerusalem weggezogen waren –,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 29, 3, 'und zwar durch Vermittlung Eleasas, des Sohnes Saphans, und Gemarjas, des Sohnes Hilkias, die Zedekia, der König von Juda, nach Babylon zu Nebukadnezar, dem König von Babylon, sandte.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 29, 4, '(Dies ist der Wortlaut des Schreibens:) »So spricht der HERR der Heerscharen, der Gott Israels, zu allen Verbannten, die ich aus Jerusalem nach Babylon habe wegführen lassen:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 29, 5, '›Baut Häuser und wohnt in ihnen! Legt Gärten an und genießt ihre Früchte!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 29, 6, 'Nehmt euch Frauen und zeugt Söhne und Töchter! Nehmt auch für eure Söhne Frauen und verheiratet eure Töchter an Männer, damit sie Mütter von Söhnen und Töchtern werden und ihr euch dort vermehrt und an Zahl nicht abnehmt!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 29, 7, 'Bemüht euch um die Wohlfahrt der Stadt, wohin ich euch in die Verbannung habe führen lassen, und betet für sie zum HERRN, denn auf seiner Wohlfahrt beruht euer eigenes Wohl.‹');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 29, 8, 'Denn so spricht der HERR der Heerscharen, der Gott Israels: ›Laßt euch von euren Propheten, die in eurer Mitte leben, und von euren Wahrsagern nicht täuschen und schenkt auch euren Träumen, die ihr euch träumen laßt, keinen Glauben!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 29, 9, 'Denn Lügen sind es, die sie euch in meinem Namen weissagen: ich habe sie nicht gesandt‹ – so lautet der Ausspruch des HERRN.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 29, 10, 'Vielmehr, so spricht der HERR: ›Erst wenn volle siebzig Jahre für Babylon vergangen sind, werde ich mich euer wieder annehmen und meine Glücksverheißung an euch in Erfüllung gehen lassen, daß ich euch an diesen Ort zurückbringe.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 29, 11, 'Denn ich weiß wohl, was für Gedanken ich gegen euch hege‹ – so lautet der Ausspruch des HERRN –, ›nämlich Gedanken des Heils und nicht des Leids, euch eine Zukunft und Hoffnung zu gewähren.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 29, 12, 'Wenn ihr mich alsdann anruft, so will ich euch antworten, und wenn ihr zu mir betet, will ich euch erhören,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 29, 13, 'und wenn ihr mich sucht, werdet ihr mich finden; ja, wenn ihr dann von ganzem Herzen Verlangen nach mir tragt,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 29, 14, 'so will ich mich von euch finden lassen‹ – so lautet der Ausspruch des HERRN – ›und will euer Schicksal wenden und euch aus allen Völkern und von allen Orten her sammeln, wohin ich euch verstoßen habe‹ – so lautet der Ausspruch des HERRN –, ›und will euch an den Ort zurückbringen, von wo ich euch habe wegführen lassen!‹«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 29, 15, '»Wenn ihr aber sagt: ›Der HERR hat uns (auch) in Babylon Propheten erstehen lassen‹ –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 29, 16, '[ja, so sagt der HERR in betreff des Königs gesprochen, der auf dem Throne Davids sitzt, und in betreff des gesamten Volkes, das in dieser Stadt hier wohnt, in betreff eurer Volksgenossen, die nicht mit euch in die Verbannung gezogen sind –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 29, 17, 'so spricht der HERR der Heerscharen: ›Wisset wohl: ich entbiete gegen sie das Schwert, den Hunger und die Pest und will sie machen wie ekelhafte Feigen, die so schlecht sind, daß man sie nicht genießen kann,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 29, 18, 'ich will sie mit dem Schwert, mit Hunger und mit der Pest verfolgen und sie zum abschreckenden Beispiel für alle Reiche der Erde machen, zum Fluchwort und zum Entsetzen, zum Spott und Hohn bei allen Völkern, unter die ich sie verstoßen habe,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 29, 19, 'zur Strafe dafür, daß sie auf meine Worte nicht gehört haben‹ – so lautet der Ausspruch des HERRN –, ›da ich doch meine Knechte, die Propheten, früh und spät immer wieder zu ihnen gesandt habe, ohne daß ihr auf sie gehört hättet‹ – so lautet der Ausspruch des HERRN.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 29, 20, '›So vernehmt nun doch ihr das Wort des HERRN, ihr Weggeführten alle, die ich aus Jerusalem nach Babylon in die Verbannung habe wegführen lassen.‹] –:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 29, 21, 'so hat der HERR der Heerscharen, der Gott Israels, in betreff Ahabs, des Sohnes Kolajas, und in betreff Zedekias, des Sohnes Maasejas, gesprochen, die euch Lügen weissagen in meinem Namen: ›Fürwahr, ich will sie in die Gewalt Nebukadnezars, des Königs von Babylon, geben, damit er sie vor euren Augen hinrichten läßt!‹ –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 29, 22, 'es wird dann bei allen in die Verbannung weggeführten Judäern, die in Babylon leben, infolge dieses Geschicks ein Fluchwort in Aufnahme kommen, daß man sagt: ›Der HERR lasse es dir ergehen wie dem Zedekia und dem Ahab, die der König von Babylon im Feuer hat rösten lassen!‹ –,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 29, 23, '›zur Strafe dafür, daß sie Gottlosigkeit in Israel verübt und mit den Frauen ihrer Volksgenossen Ehebruch getrieben und in meinem Namen Lügenworte verkündigt haben, wozu sie keinen Auftrag von mir hatten: mir selbst ist das wohlbekannt, und ich bin Zeuge dafür!‹ – so lautet der Ausspruch des HERRN.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 29, 24, '»Zu Semaja aus Nehalam aber sollst du folgendes sagen:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 29, 25, 'So hat der HERR der Heerscharen, der Gott Israels, gesprochen: Weil du in deinem eigenen Namen einen Brief an das gesamte Volk in Jerusalem und an den Priester Zephanja, den Sohn Maasejas, und an sämtliche Priester gerichtet hast folgenden Wortlauts:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 29, 26, '›Der HERR hat dich an Stelle des Priesters Jojada zum Priester bestellt, damit ein Aufseher im Tempel des HERRN für jeden Irrsinnigen, der als Weissager auftritt, vorhanden sei, damit du einen solchen Menschen in den Block und in Halseisen legest:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 29, 27, 'nun, warum bist du nicht gegen Jeremia aus Anathoth vorgegangen, der sich herausnimmt, bei euch als Prophet zu wirken?');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 29, 28, 'Er hat ja doch ein Schreiben an uns nach Babylon geschickt, worin er sagt: Es wird noch lange dauern; baut (euch also) Häuser und wohnt in ihnen! Legt Gärten an und genießt ihre Früchte!‹ ...«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 29, 29, 'Als nun der Priester Zephanja diesen Brief dem Propheten Jeremia persönlich vorgelesen hatte,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 29, 30, 'erging das Wort des HERRN an Jeremia folgendermaßen:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 29, 31, '»Laß allen in die Verbannung Weggeführten folgende Botschaft zugehen: ›So hat der HERR in betreff Semajas aus Nehalam gesprochen: Weil Semaja als Prophet bei euch aufgetreten ist, ohne daß ich ihn gesandt habe, und er euch dazu verführt hat, euch auf Lügen zu verlassen,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 29, 32, 'darum hat der HERR so gesprochen: Wisset wohl, ich will Semaja aus Nehalam und seine Nachkommen dafür büßen lassen: er soll keinen Nachkommen haben, der inmitten dieses Volkes wohnen bleibt, auch soll er das Glück nicht miterleben, das ich meinem Volke zugedacht habe!‹ – so lautet der Ausspruch des HERRN –; ›denn er hat zum Ungehorsam gegen den HERRN aufgefordert.‹«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 30, 1, 'Das Wort, das vom HERRN an Jeremia erging, lautete folgendermaßen:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 30, 2, 'So spricht der HERR, der Gott Israels: »Schreibe dir alle Worte, die ich zu dir geredet habe, in ein Buch!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 30, 3, 'Denn wisse wohl: es kommt die Zeit« – so lautet der Ausspruch des HERRN –, »da werde ich das Geschick meines Volkes Israel und Juda wenden« – so spricht der HERR – »und sie in das Land zurückführen, das ich ihren Vätern gegeben habe: sie sollen es (wieder) in Besitz nehmen.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 30, 4, 'Dies aber sind die Worte, die der HERR in betreff Israels und Judas ausgesprochen hat;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 30, 5, 'ja, so hat der HERR gesprochen: »Banges Geschrei vernehmen wir, Entsetzen voller Unheil!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 30, 6, 'Fragt doch nach und seht zu, ob auch ein Mannsbild in Kindesnöte kommen kann! Warum sehe ich denn alle Männer die Hände an die Hüften stemmen wie Frauen in Kindesnöten und alle Gesichter in Totenblässe verwandelt?');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 30, 7, 'Ach wehe! Gewaltig ist jener Tag, keiner ist ihm gleich! Und eine Zeit der Not ist’s für Jakob, doch er wird aus ihr gerettet werden!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 30, 8, '»An jenem Tage wird’s geschehen« – so lautet der Ausspruch des HERRN der Heerscharen –, »da werde ich sein Joch, das auf deinem Nacken liegt, zerbrechen und deine Fesseln zerreißen; und Fremde sollen sie nicht länger knechten,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 30, 9, 'sondern dem HERRN, ihrem Gott, werden sie dienen und ihrem König David, den ich ihnen erwecken will.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 30, 10, 'Du aber fürchte dich nicht, mein Knecht Jakob« – so lautet der Ausspruch des HERRN –, »und laß dir nicht bange sein, Israel! Denn wisse wohl: ich will dich erretten aus der Ferne und deine Kinder aus dem Lande ihrer Gefangenschaft; und Jakob soll heimkehren und in Ruhe und Sicherheit wohnen, ohne daß jemand ihn aufschreckt;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 30, 11, 'denn ich bin mit dir« – so lautet der Ausspruch des HERRN –, »um dir zu helfen. Denn über alle Völker, unter die ich dich zerstreut habe, will ich völlige Vernichtung bringen; dich allein will ich nicht völlig vernichten, sondern dich nur nach Gebühr züchtigen; denn ganz ungestraft will ich dich nicht lassen.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 30, 12, 'Ja, so hat der HERR gesprochen: »Tödlich ist deine Wunde, unheilbar der Schlag, der dich getroffen!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 30, 13, 'Niemand nimmt sich deiner Sache an, für dein Geschwür gibt es keine Heilmittel, kein Verband ist für dich da!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 30, 14, 'Alle deine Liebhaber haben dich vergessen und kümmern sich nicht um dich; denn wie ein Feind schlägt, so habe ich dich geschlagen mit erbarmungsloser Züchtigung wegen der Größe deiner Schuld und wegen der Menge deiner Sünden!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 30, 15, 'Was schreist du ob deiner Wunde, daß dein Schmerz unheilbar sei? Wegen der Größe deiner Schuld und wegen der Menge deiner Sünden habe ich dir dies Leid angetan!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 30, 16, '»Darum sollen alle, die dich gefressen haben, wieder gefressen werden und alle deine Bedränger insgesamt in die Gefangenschaft wandern; die dich ausgeplündert haben, sollen der Plünderung anheimfallen, und alle, die dich ausgeraubt haben, will ich der Beraubung preisgeben!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 30, 17, 'Denn ich will dir einen Verband anlegen und dich von deinen Wunden heilen« – so lautet der Ausspruch des HERRN –, »weil man dich, die du doch Zion bist, ›die Verstoßene‹ genannt hat, ›nach der niemand fragt‹.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 30, 18, 'So hat der HERR gesprochen: »Nunmehr will ich das Geschick der Zelte Jakobs wenden und mich seiner Wohnungen erbarmen: die Stadt soll auf ihrem Hügel wieder aufgebaut und die Königsburg in der alten Weise bewohnt werden!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 30, 19, 'Lobgesänge und der Jubel fröhlicher Menschen sollen wieder aus ihnen erschallen, und ich will sie mehren, daß ihre Zahl nicht klein bleibt, und ich will sie zu Ehren bringen, daß sie nicht länger verachtet sein sollen!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 30, 20, 'Jakobs Söhne sollen wieder zu mir stehen wie vordem, und seine Volksgemeinde wird festen Bestand vor mir haben; alle seine Bedränger aber werde ich zur Rechenschaft ziehen!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 30, 21, 'Sein Machthaber soll aus ihm selbst stammen und sein Herrscher aus seiner Mitte hervorgehen, und ich will ihm Zutritt zu mir gewähren, daß er mir nahen darf; denn wer würde sonst wohl sein Leben daransetzen, um mir zu nahen?« – so lautet der Ausspruch des HERRN.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 30, 22, '»So werdet ihr denn mein Volk sein, und ich will euer Gott sein.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 30, 23, 'Wisset wohl: ein Sturmwind des HERRN, sein Grimm, bricht los und wirbelnde Windsbraut, auf das Haupt der Gottlosen fährt sie nieder!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 30, 24, 'Nicht nachlassen wird der lodernde Zorn des HERRN, bis er’s vollbracht und die Gedanken seines Herzens ausgeführt hat: am Ende der Tage werdet ihr das schon erkennen!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 1, '»In jener Zeit« – so lautet der Ausspruch des HERRN – »will ich der Gott sein für alle Geschlechter Israels, und sie sollen mein Volk sein.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 2, 'So hat der HERR gesprochen: »Das Volk der dem Schwert Entronnenen hat Gnade gefunden in der Wüste: ich will hingehen, um Israel zu seiner Ruhestätte zu führen!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 3, 'Von fern her ist der HERR mir erschienen: »Ja, mit ewiger Liebe habe ich dich geliebt; darum habe ich dir meine Gnade so lange treu bewahrt.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 4, 'Ich will dich noch einmal aufbauen, daß du neuerbaut dastehst, Jungfrau Israel! Du sollst dich noch einmal mit deinen Handpauken schmücken und im Reigen der Tanzenden ausziehen!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 5, 'Du sollst noch einmal Weingärten auf den Bergen Samarias anlegen, und die sie angelegt haben, sollen auch die Früchte genießen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 6, 'Denn es kommt ein Tag, da werden die Wächter im Gebirge Ephraim rufen: ›Macht euch auf, laßt uns nach Zion hinaufziehen zum HERRN, unserm Gott!‹«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 7, 'Denn so hat der HERR gesprochen: »Erhebt ein Freudengeschrei über Jakob und jauchzt über das Haupt der Völker! Laßt Lobgesang erschallen und betet: ›Rette dein Volk, HERR, den Überrest Israels!‹');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 8, 'Seht, ich bringe sie heim aus dem Lande des Nordens und sammle sie von den Enden der Erde, unter ihnen Blinde und Lahme, Schwangere und Wöchnerinnen allzumal: als große Volksgemeinde kehren sie hierher zurück.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 9, 'Mit Weinen kommen sie, und unter flehentlichen Gebeten geleite ich sie; ich führe sie zu Wasserbächen auf ebenem Wege, auf dem sie nicht straucheln sollen; denn ich bin (jetzt wieder) Israels Vater geworden, und Ephraim ist mein erstgeborener Sohn!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 10, 'Vernehmt das Wort des HERRN, ihr Völker, und verkündet in den fernsten Meeresländern folgende Botschaft: »Er, der Israel zerstreut hat, sammelt es wieder und hütet es wie ein Hirt seine Herde!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 11, 'Denn der HERR hat Jakob losgekauft und ihn befreit aus der Gewalt dessen, der stärker war als er.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 12, 'So werden sie denn kommen und auf Zions Höhe jubeln und strahlen vor Freude über die Segensgaben des HERRN, über das Korn und den Most und das Öl, über die jungen Schafe und Rinder; und ihre Seele wird sein wie ein wohlbewässerter Garten, und sie werden fortan nicht mehr zu darben brauchen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 13, 'Alsdann wird die Jungfrau sich wieder am Reigentanz erfreuen, Jünglinge und Greise allzumal. »Ja, ich will ihre Trauer in Freude verwandeln und sie trösten und fröhlich machen nach ihrem Leid.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 14, 'Und ich will das Herz der Priester mit fetter Speise laben, und mein Volk soll sich an meinen Segensgaben sättigen!« – so lautet der Ausspruch des HERRN.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 15, 'So hat der HERR gesprochen: »Horch! In Rama wird Wehklage laut, bitterliches Weinen! Rahel weint um ihre Kinder, will sich nicht trösten lassen wegen ihrer Kinder: ach, sie sind nicht mehr da!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 16, 'Doch so hat der HERR gesprochen: »Wehre deiner Stimme das Klagen und deinen Augen die Tränen! Denn es gibt noch einen Lohn für deine Mühsal« – so lautet der Ausspruch des HERRN –; »denn sie sollen aus dem Lande des Feindes wieder heimkehren!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 17, 'Ja, es ist noch eine Hoffnung für deine Zukunft vorhanden« – so lautet der Ausspruch des HERRN –; »denn deine Kinder kehren in ihre Heimat zurück!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 18, '»Ich habe wohl gehört, wie Ephraim klagte: ›Du hast mich gezüchtigt, und ich habe Zucht gelernt wie ein nicht ans Joch gewöhnter Jungstier: o laß mich heimkehren, so will ich mich bekehren! Du bist ja doch der HERR, mein Gott!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 19, 'Denn seitdem ich mich von dir abgewandt habe, fühle ich Reue; und nachdem ich zur Erkenntnis gekommen bin, schlage ich mich auf die Hüften: ich schäme mich, stehe zerknirscht da, denn ich habe die Schmach meiner Jugend zu büßen!‹');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 20, 'Ist mir denn Ephraim ein so teurer Sohn oder mein Lieblingskind, daß, sooft ich ihm auch gedroht habe, ich seiner doch immer wieder freundlich gedenken muß? Darum schlägt mein Herz so warm für ihn: ich muß mich seiner erbarmen!« – so lautet der Ausspruch des HERRN.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 21, '»Stelle dir Wegweiser auf, setze dir Merksteine hin! Gib wohl acht auf die Straße, auf den Weg, den du einst gezogen bist! Kehre heim, Jungfrau Israel, kehre heim zu deinen Städten hier!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 22, 'Wie lange willst du dich noch hierhin und dorthin wenden, du abtrünnige Tochter? Der HERR schafft ja doch etwas Neues im Lande: das Weib umwirbt den Mann.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 23, 'So hat der HERR der Heerscharen, der Gott Israels, gesprochen: »Noch wird man im Lande Juda und in seinen Städten, wenn ich ihr Geschick gewandt habe, diesen Gruß aussprechen: ›Der HERR segne dich, du Gefilde der Gerechtigkeit, du heiliger Berg!‹');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 24, 'Und Juda wird darin wohnen samt allen seinen Städten ohne Ausnahme, die Ackerleute und solche, die mit der Herde umherziehen;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 25, 'denn ich will die lechzenden Seelen reichlich tränken und jegliche schmachtende Seele sättigen!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 26, 'Darüber erwachte ich und schaute mich um, und mein Schlaf war mir köstlich gewesen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 27, '»Wisset wohl: es kommt die Zeit« – so lautet der Ausspruch des HERRN –, »da will ich über das Haus Israel und über das Haus Juda eine Saat von Menschen und eine Saat von Vieh ausstreuen;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 28, 'und wie ich die Augen offen über ihnen gehalten habe, um auszureißen und zu zerstören, um niederzureißen und zu verderben und Unheil anzurichten, ebenso will ich alsdann über ihnen wachen, um aufzubauen und zu pflanzen!« – so lautet der Ausspruch des HERRN.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 29, 'In jenen Tagen wird man nicht mehr sagen: »Die Väter haben Herlinge gegessen, und den Kindern werden die Zähne stumpf davon«;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 30, 'sondern ein jeder wird um seiner eigenen Verschuldung willen sterben: nur wer Herlinge ißt, dem sollen die (eigenen) Zähne stumpf werden.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 31, '»Wisset wohl: es kommt die Zeit« – so lautet der Ausspruch des HERRN –, »da will ich mit dem Hause Israel und mit dem Hause Juda einen neuen Bund schließen,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 32, 'nicht einen solchen Bund, wie ich ihn mit ihren Vätern damals geschlossen habe, als ich sie bei der Hand nahm, um sie aus Ägyptenland wegzuführen, einen Bund, den sie gebrochen haben, wiewohl ich Herrenrecht über sie hatte!« – so lautet der Ausspruch des HERRN.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 33, '»Nein, darin soll der Bund bestehen, den ich mit dem Hause Israel nach dieser Zeit schließen werde« – so lautet der Ausspruch des HERRN –: »Ich will mein Gesetz in ihr Inneres hineinlegen und es ihnen ins Herz schreiben und will dann ihr Gott sein, und sie sollen mein Volk sein.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 34, 'Da braucht dann niemand mehr seinem Genossen und niemand seinem Bruder Belehrung zu erteilen und ihm vorzuhalten: ›Lernt den HERRN erkennen!‹, denn sie werden mich allesamt erkennen, die Kleinsten wie die Größten« – so lautet der Ausspruch des HERRN –; »denn ich will ihnen ihre Schuld vergeben und ihrer Sünde nicht mehr gedenken!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 35, 'So hat der HERR gesprochen, der die Sonne zur Leuchte am Tage bestellt hat, die Ordnungen des Mondes und der Sterne zur Erleuchtung bei Nacht, der das Meer aufwühlt, so daß seine Wogen brausen – HERR der Heerscharen ist sein Name –:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 36, '»Wenn diese festen Ordnungen jemals vor mir zu bestehen aufhören« – so lautet der Ausspruch des HERRN –, »dann (erst) soll auch die Nachkommenschaft Israels aufhören, ein Volk vor meinen Augen zu sein für alle Zeiten!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 37, 'So hat der HERR gesprochen: »So wenig der Himmel droben ausgemessen und die Grundfesten der Erde drunten durchspäht werden können, so wenig will ich auch die gesamte Nachkommenschaft Israels verwerfen wegen alles dessen, was sie begangen haben« – so lautet der Ausspruch des HERRN.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 38, '»Wisset wohl: es kommt die Zeit« – so lautet der Ausspruch des HERRN –, »da wird diese Stadt für den HERRN wieder aufgebaut werden vom Turm Hananeel bis zum Ecktor;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 39, 'und weiter wird die Meßschnur (von da) geradeaus über den Hügel Gareb fortlaufen und sich dann nach Goah wenden.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 40, 'Und das ganze Tal der Leichen und der Opferasche und das gesamte Feld bis an den Bach Kidron, bis an die Ecke des Roßtores gegen Osten, wird dem HERRN heilig sein; es wird dort alsdann nie wieder eingerissen und zerstört werden in Ewigkeit!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 1, '(Dies ist) das Wort, das vom HERRN an Jeremia erging im zehnten Regierungsjahr des judäischen Königs Zedekia – dieses Jahr war das achtzehnte Regierungsjahr Nebukadnezars.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 2, 'Damals belagerte nämlich das Heer des Königs von Babylon Jerusalem, und der Prophet Jeremia wurde im Wachthof, der zum Palast des Königs von Juda gehörte, in Haft gehalten.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 3, 'Denn Zedekia, der König von Juda, hatte ihn dort gefangengesetzt mit dem Vorhalt: »Warum trittst du als Prophet auf und sagst: ›So hat der HERR gesprochen: Fürwahr, ich will diese Stadt in die Gewalt des Königs von Babylon geben, daß er sie erobert;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 4, 'auch Zedekia, der König von Juda, wird den Händen der Chaldäer nicht entrinnen, sondern unfehlbar dem König von Babylon in die Hände übergeben werden und von Mund zu Mund mit ihm reden und ihm Auge in Auge gegenüberstehen;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 5, 'der wird Zedekia dann nach Babylon bringen lassen, und dort wird er bleiben, bis ich mich seiner wieder annehme – so lautet der Ausspruch des HERRN. Wenn ihr also mit den Chaldäern kämpft, werdet ihr kein Glück haben.‹«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 6, 'Da sagte Jeremia: »Das Wort des HERRN ist an mich folgendermaßen ergangen:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 7, 'Demnächst wird Hanamel, der Sohn deines Oheims Sallum, zu dir kommen mit der Aufforderung: ›Kaufe dir meinen Acker, der bei Anathoth liegt! Denn du hast das Löserecht und bist zum Kauf verpflichtet.‹«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 8, 'Und wirklich kam Hanamel, der Sohn meines Oheims, zu mir in den Wachthof, wie der HERR mir angekündigt hatte, und sagte zu mir: »Kaufe doch meinen Acker, der bei Anathoth im Stamm Benjamin liegt, denn dir steht das Besitz- und Vorkaufsrecht zu; kaufe ihn dir!« Da wurde mir klar, daß es eine Weisung vom HERRN gewesen war;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 9, 'und so kaufte ich denn den Acker, der bei Anathoth lag, von meinem Vetter Hanamel und wog ihm das Geld dar, siebzehn Schekel Silber.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 10, 'Hierauf brachte ich einen Kaufvertrag zu Papier, versah ihn mit einem Siegel, ließ ihn durch Zeugen beglaubigen und wog ihm das Geld auf der Waage dar.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 11, 'Hierauf nahm ich den Kaufvertrag, den versiegelten und mit der Abmachung und den Bedingungen versehenen und auch den offenen,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 12, 'und übergab den Kaufvertrag Baruch, dem Sohne Nerijas, des Sohnes Mahsejas, in Gegenwart meines Vetters Hanamel und in Gegenwart der Zeugen, die den Kaufvertrag unterschrieben hatten, und in Gegenwart aller Judäer, die im Wachthof anwesend waren.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 13, 'Hierauf erteilte ich dem Baruch in ihrer Gegenwart folgenden Auftrag:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 14, '»So hat der HERR der Heerscharen, der Gott Israels, gesprochen: ›Nimm diese Urkunden, und zwar sowohl diesen versiegelten Kaufvertrag als auch dieses offene Schriftstück, und lege sie in ein irdenes Gefäß, damit sie lange Zeit erhalten bleiben!‹');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 15, 'Denn so hat der HERR der Heerscharen, der Gott Israels, gesprochen: ›Man wird künftig wieder Häuser, Äcker und Weinberge in diesem Lande kaufen!‹«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 16, 'Nachdem ich so Baruch, dem Sohne Nerijas, den Kaufvertrag übergeben hatte, richtete ich folgendes Gebet an den HERRN:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 17, '»Ach HERR, mein Gott! Du bist’s, der den Himmel und die Erde durch deine große Kraft und deinen ausgestreckten Arm geschaffen hat: dir ist kein Ding unmöglich.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 18, 'Du übst Gnade an Tausenden und läßt die Strafe für die Schuld der Väter in den Schoß ihrer Kinder nach ihnen fallen, du großer, starker Gott, dessen Name ›HERR der Heerscharen‹ ist,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 19, 'groß an Rat und mächtig an Tat, du, dessen Augen offen stehen über allen Wegen der Menschenkinder, damit du einem jeden nach seinem Wandel und nach den Früchten seines Tuns vergiltst.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 20, 'Du hast Zeichen und Wunder im Lande Ägypten und bis auf diesen Tag sowohl an Israel als auch an den (anderen) Menschen gewirkt und dir dadurch einen Namen gemacht, wie es heute klar zu Tage liegt.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 21, 'Du hast dein Volk Israel aus dem Lande Ägypten ausziehen lassen unter Zeichen und Wundern, mit starker Hand, mit hocherhobenem Arm und großem Schrecken,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 22, 'und hast ihnen dies Land gegeben, dessen Besitz du ihren Vätern zugeschworen hattest, ein Land, das von Milch und Honig überfließt.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 23, 'Als sie aber hineingekommen waren und es in Besitz genommen hatten, hörten sie nicht auf deine Weisungen und lebten nicht nach deinem Gesetz und taten nichts von allem, was du ihnen zu tun geboten hattest; darum hast du ihnen all dies Unglück widerfahren lassen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 24, 'Ach, die Belagerungswälle sind schon bis an die Stadt herangekommen, um sie zu erobern, und die Stadt ist der Gewalt der Chaldäer, die sie belagern, durch das Schwert, durch den Hunger und die Pest preisgegeben, und was du angedroht hast, ist eingetreten: du siehst es ja selbst.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 25, 'Und doch hast du, HERR, mein Gott, mir geboten: ›Kaufe dir den Acker für Geld und ziehe Zeugen hinzu!‹, und dabei ist die Stadt schon der Gewalt der Chaldäer preisgegeben!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 26, 'Da erging das Wort des HERRN an Jeremia folgendermaßen:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 27, '»Fürwahr, ich bin der HERR, der Gott alles Fleisches: sollte mir irgend etwas unmöglich sein?');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 28, 'Darum spricht der HERR so: Allerdings lasse ich diese Stadt in die Gewalt der Chaldäer und zwar in die Gewalt des babylonischen Königs Nebukadnezar fallen, der sie erobern soll;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 29, 'und die Chaldäer, die diese Stadt belagern, werden in sie eindringen und Feuer an diese Stadt legen und sie einäschern, eben die Häuser, auf deren Dächern man dem Baal Rauchopfer dargebracht und fremden Göttern Trankspenden ausgegossen hat, um mich zu erbittern.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 30, 'Denn die Israeliten und die Judäer haben von ihrer Jugend an immer nur das getan, was mir mißfällt; ja, die Israeliten haben mich immer nur erbittert durch die Machwerke ihrer Hände!« – so lautet der Ausspruch des HERRN –;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 31, '»ja ein Gegenstand des Zornes und des Grimms ist diese Stadt für mich vom Tage ihrer Gründung an bis auf den heutigen Tag gewesen, so daß ich sie mir aus den Augen schaffen muß');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 32, 'wegen all des Bösen, das die Israeliten und die Judäer mir zum Ärgernis verübt haben, sie selbst, ihre Könige und ihre Fürsten, ihre Priester und ihre Propheten, sowohl die Männer von Juda als die Bewohner Jerusalems.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 33, 'Sie haben mir den Rücken zugekehrt, statt auf mich zu blicken; und obgleich ich sie früh und spät immer wieder habe belehren lassen, haben sie doch nicht darauf gehört und keine Zucht annehmen wollen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 34, 'Nein, sie haben ihre scheußlichen Götzen sogar in dem Hause, das meinen Namen trägt, aufgestellt, um es dadurch zu entweihen,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 35, 'und haben dem Baal die Opferstätten im Tal Ben-Hinnom erbaut, um ihre Söhne und Töchter dort dem Moloch als Opfer zu verbrennen, was ich ihnen niemals geboten habe und was mir nie in den Sinn gekommen ist, daß sie solche Greuel verüben sollten, um Juda zur Sünde zu verführen.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 36, 'Nun aber – trotz alledem spricht der HERR, der Gott Israels, in bezug auf diese Stadt, von der ihr sagt, sie sei der Gewalt des babylonischen Königs durch das Schwert, durch den Hunger und durch die Pest preisgegeben, folgendermaßen:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 37, '»Fürwahr, ich will sie aus allen Ländern, wohin ich sie in meinem Zorn und Grimm und in heftiger Ungnade verstoßen habe, wieder sammeln und sie an diesen Ort zurückbringen und sie hier in Sicherheit wohnen lassen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 38, 'Sie sollen dann mein Volk sein, und ich will ihr Gott sein');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 39, 'und ihnen einerlei Sinn und einerlei Wandel verleihen, auf daß sie mich allezeit fürchten, zu ihrem eigenen Heil und zum Segen ihrer Kinder nach ihnen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 40, 'Und ich will einen ewigen Bund mit ihnen schließen, daß ich niemals von ihnen ablassen will, ihnen Gutes zu erweisen, und ich will ihnen Furcht vor mir ins Herz legen, damit sie mir nie wieder untreu werden.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 41, 'Ich werde dann meine Freude an ihnen haben, so daß ich ihnen Liebe erweise, und will sie in dieses Land einpflanzen in Treue, mit ganzem Herzen und mit ganzer Seele.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 42, 'Denn so spricht der HERR: »Wie ich all dieses große Unheil über dieses Volk gebracht habe, ebenso will ich ihnen all das Gute widerfahren lassen, das ich ihnen jetzt verheiße.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 43, 'Denn es sollen wieder Äcker gekauft werden in diesem Lande, von dem ihr sagt, es sei eine Einöde ohne Menschen und ohne Vieh und sei der Gewalt der Chaldäer preisgegeben.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 44, 'Man wird wieder Äcker für Geld kaufen und Kaufverträge schreiben und versiegeln und sie durch Zeugen beglaubigen lassen im Stamm Benjamin wie im Bezirk Jerusalems und in den Ortschaften Judas, sowohl in den Ortschaften des Berglandes als auch in denen der Niederung und in den Ortschaften des Südlandes; denn ich werde ihr Geschick wenden!« – so lautet der Ausspruch des HERRN.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 33, 1, 'Hierauf erging das Wort des HERRN zum zweitenmal an Jeremia, während er noch im Wachthof eingeschlossen gehalten wurde, folgendermaßen:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 33, 2, '»So spricht der HERR, der (alles) ausführt, der HERR, der es ersinnt, um es auch zu verwirklichen, ›HERR‹ ist sein Name:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 33, 3, 'Rufe mich an, so will ich dich erhören und dir große und unglaubliche Dinge kundtun, von denen du bisher nichts gewußt hast.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 33, 4, 'Denn so spricht der HERR, der Gott Israels, in betreff der Häuser dieser Stadt und in betreff der Paläste der Könige von Juda, die niedergerissen worden sind, um gegen die Belagerungswälle und zu Kriegszwecken verwandt zu werden,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 33, 5, 'zum Kampf gegen die Chaldäer und um sie mit den Leichen der Menschen anzufüllen, die ich in meinem Zorn und Grimm erschlagen habe, weil ich mein Angesicht vor dieser Stadt um all ihrer Bosheit willen verhüllt hatte –:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 33, 6, 'Wisse wohl: ich will ihr einen Verband und Heilmittel auflegen und ihr Heilung verschaffen und ihnen eine Fülle von Glück und Sicherheit erscheinen lassen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 33, 7, 'Und ich will das Geschick Judas und das Geschick Israels wenden und sie wieder aufbauen wie vordem');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 33, 8, 'und will sie von all ihrer Verschuldung reinigen, mit der sie gegen mich gesündigt haben, und will ihnen alle Missetaten vergeben, die sie gegen mich begangen haben und durch die sie mir untreu geworden sind.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 33, 9, 'Dann wird Jerusalem für mich ein Freudenname werden, ein Ruhm und eine Verherrlichung bei allen Völkern der Erde, die, wenn sie von all dem Guten hören, das ich dieser Stadt erweise, erschrecken und erzittern werden über all das Gute und über all das Glück, das ich ihr erweisen werde!« –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 33, 10, 'So hat der HERR gesprochen: »An diesem Orte, von dem ihr sagt, er sei verödet, menschenleer und ohne Vieh in den Ortschaften Judas und auf den Straßen Jerusalems, die jetzt vereinsamt sind, menschenleer, ohne Bewohner und ohne Vieh,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 33, 11, 'da wird man künftig wieder Freudenrufe und laute Fröhlichkeit vernehmen, den Jubel des Bräutigams und den Jubel der Braut, den Jubel derer, die da rufen: ›Lobet den HERRN der Heerscharen! Denn gütig ist der HERR, und seine Gnade währet ewiglich!‹, und den Jubel derer, welche Dankopfer im Tempel des HERRN darbringen. Denn ich will das Geschick des Landes wenden, daß es wieder wird wie vordem!« – so hat der HERR gesprochen. –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 33, 12, 'So hat der HERR der Heerscharen gesprochen: »An diesem Ort, der jetzt verödet ist, menschenleer und ohne Vieh, und in allen seinen Ortschaften soll künftig wieder eine Trift für Hirten sein, die ihre Herden sich lagern lassen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 33, 13, 'In den Ortschaften des Berglandes und in denen der Niederung, in den Ortschaften des Südlandes und im Stamme Benjamin, im Bezirk Jerusalems und in den übrigen Ortschaften Judas sollen künftig die Herden wieder unter den Händen des (Hirten), der sie zählt, vorüberziehen!« – so hat der HERR gesprochen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 33, 14, '»Wisset wohl: es kommt die Zeit« – so lautet der Ausspruch des HERRN –, »da will ich die Segensverheißung, die ich über das Haus Israel und über das Haus Juda ausgesprochen habe, in Erfüllung gehen lassen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 33, 15, 'In jenen Tagen und zu jener Zeit will ich dem David einen Sproß der Gerechtigkeit ersprießen lassen, der Recht und Gerechtigkeit im Lande walten läßt.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 33, 16, 'In jenen Tagen wird Juda Rettung erlangen und Jerusalem in Sicherheit wohnen, und der Name, den man der Stadt beilegt, wird lauten: ›der HERR unsere Gerechtigkeit‹.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 33, 17, 'Denn so hat der HERR gesprochen: »Nie soll es dem David an einem (Nachkommen) fehlen, der auf dem Throne des Hauses Israel sitzt;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 33, 18, 'und auch den levitischen Priestern soll es vor meinem Angesicht nie an einem (Nachkommen) fehlen, der Brandopfer darbringt und Speisopfer in Rauch aufgehen läßt und Schlachtopfer zurichtet immerdar!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 33, 19, 'Darauf erging das Wort des HERRN an Jeremia folgendermaßen:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 33, 20, '»So spricht der HERR: So wenig ihr meinen Bund mit dem Tage und meinen Bund mit der Nacht aufheben könnt, so daß Tag und Nacht nicht mehr zu ihrer Zeit eintreten würden,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 33, 21, 'ebenso wenig wird auch mein Bund mit meinem Knecht David aufgehoben werden, daß er keinen Sohn mehr haben sollte, der als König auf seinem Throne säße, und ebenso wenig mein Bund mit meinen Dienern, den priesterlichen Leviten!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 33, 22, 'Wie das Sternenheer am Himmel nicht gezählt und der Sand am Meer nicht gemessen werden kann, ebenso unzählbar will ich die Nachkommenschaft meines Knechtes David und die Leviten machen, die meinen Dienst versehen.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 33, 23, 'Weiter erging das Wort des HERRN an Jeremia folgendermaßen:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 33, 24, '»Hast du nicht darauf geachtet, was diese Leute da behaupten, wenn sie sagen: ›Die beiden Geschlechter, die der HERR einst erwählt hatte, die hat er jetzt verworfen!‹, und wie sie mein Volk verachten, so daß es in ihren Augen gar kein Volk mehr ist?');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 33, 25, 'So spricht der HERR: So gewiß mein Bund mit Tag und Nacht besteht, so gewiß ich die Ordnungen des Himmels und der Erde festgesetzt habe,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 33, 26, 'ebenso gewiß will ich auch die Nachkommenschaft Jakobs und meines Knechtes David nicht verwerfen, daß ich aus seiner Nachkommenschaft keine Herrscher mehr für die Nachkommenschaft Abrahams, Isaaks und Jakobs entnehmen sollte; denn ich werde ihr Geschick wenden und mich ihrer erbarmen!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 34, 1, 'Das Wort, das vom HERRN an Jeremia erging, als Nebukadnezar, der König von Babylon, mit seiner ganzen Heeresmacht und allen Königreichen der Erde, soweit sie seiner Herrschaft unterworfen waren, und mit allen (übrigen) Völkern Jerusalem belagerte und alle zugehörigen Städte bekriegte, lautete folgendermaßen:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 34, 2, '»So spricht der HERR, der Gott Israels: Gehe hin und verkünde dem judäischen Könige Zedekia folgende Botschaft: ›So hat der HERR gesprochen: Wisse wohl: ich gebe diese Stadt in die Gewalt des Königs von Babylon, damit er sie in Flammen aufgehen läßt.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 34, 3, 'Und auch du wirst seiner Hand nicht entrinnen, sondern unfehlbar ergriffen und in seine Hand überliefert werden; du wirst dann dem Könige von Babylon Auge in Auge gegenüberstehen, und er wird Mund gegen Mund mit dir reden; darauf wirst du nach Babylon kommen.‹');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 34, 4, 'Vernimm jedoch das Wort des HERRN, Zedekia, König von Juda! Folgende Verheißung hat der HERR über dich ausgesprochen: ›Du sollst den Tod nicht durch das Schwert erleiden;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 34, 5, 'in Frieden sollst du sterben! Und wie man deinen Vätern, den früheren Königen, deinen Vorgängern, Leichenbrände veranstaltet hat, so wird man auch dir ein Totenfeuer anzünden und dich mit dem Klagerufe betrauern: Ach, Gebieter!, denn ich habe es so bestimmt! – so lautet der Ausspruch des HERRN.‹«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 34, 6, 'Alle diese Worte verkündete der Prophet Jeremia dem judäischen König Zedekia in Jerusalem,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 34, 7, 'während das Heer des Königs von Babylon Jerusalem und alle noch übriggebliebenen Städte von Juda, nämlich Lachis und Aseka, belagerte; denn diese waren die einzigen von den festen Plätzen Judas, die noch standhielten.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 34, 8, '(Dies ist) das Wort, das vom HERRN an Jeremia erging, nachdem der König Zedekia sich durch ein Abkommen mit dem gesamten Volk in Jerusalem dazu verpflichtet hatte, eine Freilassung für sie ausrufen zu lassen,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 34, 9, 'daß nämlich ein jeder seinen hebräischen Sklaven und ein jeder seine hebräische Sklavin frei ziehen lassen solle, so daß niemand künftig einen judäischen Volksgenossen zu Sklavendiensten zwingen dürfe.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 34, 10, 'Da hatten alle Fürsten und das gesamte Volk, die diesen Beschluß gemeinsam gefaßt hatten, ihre Sklaven und Sklavinnen freizulassen und sie nicht länger zu Sklavendiensten zu zwingen, den Beschluß auch pflichtgemäß ausgeführt und die Freilassung vollzogen;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 34, 11, 'nachher aber waren sie anderen Sinnes geworden und hatten die Sklaven und Sklavinnen, die sie bereits in Freiheit gesetzt hatten, zurückgeholt und zwangsweise wieder zu Sklaven und Sklavinnen gemacht.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 34, 12, 'Da erging das Wort des HERRN an Jeremia folgendermaßen:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 34, 13, '»So spricht der HERR, der Gott Israels: Ich selbst habe mit euren Vätern damals, als ich sie aus dem Lande Ägypten, dem Sklavenhause, wegführte, einen Bund geschlossen und geboten:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 34, 14, '›Nach Ablauf von sieben Jahren sollt ihr ein jeder seinen hebräischen Volksgenossen, der sich dir verkauft hat, in Freiheit setzen: sechs Jahre lang soll er dir Dienste leisten, dann aber sollst du ihn frei von dir ziehen lassen!‹ Aber eure Väter sind mir nicht gehorsam gewesen und haben mir kein Gehör geschenkt.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 34, 15, 'Nun wart ihr jetzt zwar umgekehrt und hattet getan, was in meinen Augen recht war, indem ihr ein jeder die Freilassung für seinen Volksgenossen ausrufen ließt und in dem Tempel, der meinen Namen trägt, vor meinem Angesicht einen gemeinsamen Beschluß faßtet.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 34, 16, 'Dann aber seid ihr wieder anderen Sinnes geworden und habt meinen Namen entehrt, indem ihr ein jeder seinen Sklaven und seine Sklavin, die ihr auf ihr Verlangen bereits freigelassen hattet, zurückgeholt und zwangsweise wieder zu euren Sklaven und Sklavinnen gemacht habt.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 34, 17, 'Darum spricht der HERR so: Ihr habt nicht auf mich gehört, daß ihr ein jeder für seinen Volks- und Stammesgenossen die Freilassung hättet ausrufen lassen: nun, so will ich jetzt über euch eine Freilassung ausrufen« – so lautet der Ausspruch des HERRN –, »nämlich für das Schwert, für die Pest und für den Hunger, und will euch zum abschreckenden Beispiel für alle Reiche der Erde machen');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 34, 18, 'und will die Männer, die das vor mir geschlossene Abkommen übertreten haben, indem sie den Bestimmungen des Beschlusses, den sie vor meinem Angesicht gefaßt hatten, nicht nachgekommen sind, dem Opferkalb gleich machen, das sie in zwei Hälften zerschnitten haben und zwischen dessen Stücken sie hindurchgeschritten sind:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 34, 19, 'die Fürsten von Juda und die Fürsten Jerusalems, die Kammerherren und die Priester und das gesamte Volk des Landes, die zwischen den Stücken des Kalbes hindurchgeschritten sind –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 34, 20, 'ja, die will ich der Gewalt ihrer Feinde preisgeben und sie in die Hand derer fallen lassen, die ihnen nach dem Leben trachten; und ihre Leichname sollen den Vögeln des Himmels und den Tieren des Feldes zum Fraß dienen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 34, 21, 'Auch Zedekia, den König von Juda, und seine Fürsten will ich der Gewalt ihrer Feinde preisgeben und sie in die Hand derer fallen lassen, die ihnen nach dem Leben trachten, nämlich in die Gewalt des Heeres des Königs von Babylon, das jetzt von euch abgezogen ist.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 34, 22, 'Wisset wohl: ich gebiete« – so lautet der Ausspruch des HERRN – »und bringe sie wieder zu dieser Stadt zurück, damit sie sie belagern und erobern und in Flammen aufgehen lassen! Und auch die (übrigen) Städte Judas will ich zu einer unbewohnten Einöde machen!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 35, 1, 'Das Wort, das vom HERRN unter der Regierung des judäischen Königs Jojakim, des Sohnes Josias, an Jeremia erging, lautete folgendermaßen:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 35, 2, '»Begib dich zur Genossenschaft der Rechabiten und lade sie ein; führe sie dann in den Tempel des HERRN in eine der Zellen und setze ihnen Wein zum Trinken vor!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 35, 3, 'Da holte ich Jaasanja, den Sohn Jeremias, des Sohnes Habazinjas, nebst seinen Brüdern und allen seinen Söhnen, überhaupt die ganze Genossenschaft der Rechabiten,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 35, 4, 'und führte sie zum Tempel des HERRN in die Zelle der Söhne des Gottesmannes Hanan, des Sohnes Jigdaljas, die neben der Zelle der Fürsten, oberhalb der Zelle des Schwellenhüters Maaseja, des Sohnes Sallums, lag.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 35, 5, 'Dort setzte ich den zur Familie der Rechabiten gehörenden Männern mit Wein gefüllte Krüge und Becher vor und forderte sie auf, Wein zu trinken.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 35, 6, 'Doch sie antworteten: »Wir trinken keinen Wein, denn unser Stammvater Jonadab, der Sohn Rechabs, hat uns das Gebot erteilt: ›Ihr dürft keinen Wein trinken, weder ihr noch euere Nachkommen, in alle Zukunft;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 35, 7, 'auch dürft ihr euch keine Häuser bauen, keine Saatfelder bestellen und keine Weinberge anlegen oder in Besitz haben, sondern sollt während eures ganzen Lebens in Zelten wohnen, damit ihr lange in dem Lande lebt, in welchem ihr euch als Fremdlinge aufhaltet.‹');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 35, 8, 'So sind wir denn dem Gebot unsers Stammvaters Jonadab, des Sohnes Rechabs, in allen Stücken genau nachgekommen, so daß wir zeitlebens keinen Wein trinken, weder wir noch unsere Frauen, noch unsere Söhne und Töchter,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 35, 9, 'und daß wir uns keine Häuser bauen, um darin zu wohnen, und weder Weinberge noch Äcker und Saatfelder besitzen;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 35, 10, 'vielmehr wohnen wir in Zelten und erfüllen gehorsam alles, was unser Stammvater Jonadab uns geboten hat.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 35, 11, 'Nur als Nebukadnezar, der König von Babylon, gegen dies Land herangezogen kam, da sagten wir: ›Kommt, wir wollen uns vor dem Heere der Chaldäer und vor dem Heere der Syrer nach Jerusalem zurückziehen!‹, und so haben wir jetzt in Jerusalem Wohnung genommen.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 35, 12, 'Da erging das Wort des HERRN an Jeremia folgendermaßen:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 35, 13, '»So spricht der HERR der Heerscharen, der Gott Israels: Gehe hin und sage zu den Männern von Juda und zu den Bewohnern Jerusalems: ›Wollt ihr denn keine Zucht annehmen, daß ihr meinen Weisungen gehorcht?‹ – so lautet der Ausspruch des HERRN.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 35, 14, '›Die Weisung, die Jonadab, der Sohn Rechabs, seinen Nachkommen gegeben hat, keinen Wein zu trinken, die ist befolgt worden: sie haben keinen Wein bis auf den heutigen Tag getrunken, weil sie dem Gebot ihres Stammvaters gehorsam gewesen sind. Ich aber habe früh und spät immer wieder zu euch geredet, doch ihr habt nicht auf mich gehört.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 35, 15, 'Und dabei habe ich alle meine Knechte, die Propheten, früh und spät immer wieder zu euch gesandt mit der Mahnung: Kehrt doch alle von euren bösen Wegen um, bessert euren Wandel und lauft nicht anderen Göttern nach, um ihnen zu dienen! Dann sollt ihr in dem Lande wohnen bleiben, das ich euch und euren Vätern gegeben habe; aber ihr habt nicht hören wollen und seid mir nicht gehorsam gewesen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 35, 16, 'Ja, die Nachkommen Jonadabs, des Sohnes Rechabs, sind dem Gebot nachgekommen, das ihr Stammvater ihnen gegeben hat; dieses Volk aber hat nicht auf mich gehört!‹');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 35, 17, 'Darum spricht der HERR, der Gott der Heerscharen, der Gott Israels, folgendermaßen: ›Fürwahr, ich will über Juda und über alle Bewohner Jerusalems all das Unheil kommen lassen, das ich ihnen angedroht habe, weil sie nicht haben hören wollen, als ich zu ihnen redete, und nicht geantwortet haben, als ich ihnen zurief.‹«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 35, 18, 'Zur Genossenschaft der Rechabiten aber sagte Jeremia: »So spricht der HERR der Heerscharen, der Gott Israels: ›Weil ihr dem Gebot eures Stammvaters Jonadab gehorsam gewesen seid, indem ihr alle seine Gebote beobachtet und alles getan habt, was er euch befohlen hat:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 35, 19, 'darum spricht der HERR der Heerscharen, der Gott Israels, also: Es soll Jonadab, dem Sohne Rechabs, in Zukunft niemals an einem (Nachkommen) fehlen, der in meinem Dienst vor mir steht!‹«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 36, 1, 'Im vierten Regierungsjahre des judäischen Königs Jojakim, des Sohnes Josias, erging folgendes Wort des HERRN an Jeremia:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 36, 2, '»Nimm dir eine Buchrolle und schreibe auf sie alle die Worte, die ich in betreff Israels und Judas und in betreff aller Völker zu dir gesprochen habe seit dem Tage, an dem ich dir Offenbarungen habe zuteil werden lassen, nämlich seit der Regierung Josias bis auf den heutigen Tag!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 36, 3, 'Vielleicht hören dann die vom Hause Juda auf all das Unheil, das ich über sie zu verhängen gedenke, und bekehren sich alle von ihrem bösen Wandel, so daß ich ihnen ihre Verschuldung und Sünde vergeben kann.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 36, 4, 'Da berief Jeremia den Baruch, den Sohn Nerijas, und dieser schrieb alle die Worte, welche der HERR zu ihm gesprochen hatte, so, wie Jeremia sie ihm vorsagte, auf eine Buchrolle.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 36, 5, 'Hierauf gab Jeremia dem Baruch folgenden Auftrag: »Mir ist’s verwehrt: ich darf nicht in den Tempel des HERRN gehen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 36, 6, 'So gehe denn du hin und lies aus der Rolle die Worte des HERRN, die du so, wie ich sie dir vorsagte, aufgeschrieben hast, dem Volke im Tempel des HERRN an einem Fasttage laut vor; auch allen Judäern, die aus ihren Ortschaften herkommen, sollst du sie laut vorlesen:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 36, 7, 'vielleicht dringt dann ihr Flehen zum HERRN empor, und sie bekehren sich alle von ihrem bösen Wandel; denn groß ist der Zorn und Grimm, mit dem der HERR diesem Volke gedroht hat.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 36, 8, 'Da tat Baruch, der Sohn Nerijas, genau so, wie der Prophet Jeremia ihm aufgetragen hatte, indem er aus dem Buche die Worte des HERRN im Tempel des HERRN vorlas.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 36, 9, 'Es begab sich nämlich im fünften Regierungsjahr des judäischen Königs Jojakim, des Sohnes Josias, im neunten Monat, daß man die ganze Bevölkerung Jerusalems und alles Volk, das aus den Ortschaften Judas nach Jerusalem gekommen war, zu einem Fasten vor dem HERRN aufrief.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 36, 10, 'Da las Baruch aus dem Buche die Worte Jeremias im Tempel des HERRN in der Zelle Gemarjas, des Sohnes des Staatsschreibers Saphan, im oberen Vorhof, am Eingang des neuen Tores am Tempel des HERRN dem ganzen Volke laut vor.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 36, 11, 'Als nun Michaja, der Sohn Gemarjas, des Sohnes Saphans, alle Worte des HERRN aus dem Buche hatte vorlesen hören,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 36, 12, 'begab er sich zum königlichen Palast hinab in das Zimmer des Staatsschreibers, wo gerade alle Fürsten eine Sitzung abhielten, nämlich der Staatsschreiber Elisama, Delaja, der Sohn Semajas, Elnathan, der Sohn Achbors, Gemarja, der Sohn Saphans, Zedekia, der Sohn Hananjas kurz alle Fürsten.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 36, 13, 'Als ihnen nun Michaja alle die Worte mitgeteilt hatte, die er Baruch dem Volk aus dem Buch hatte laut vorlesen hören,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 36, 14, 'sandten alle Fürsten Jehudi, den Sohn Nethanjas, des Sohnes Selemjas, des Sohnes Kusis, zu Baruch und ließen ihm sagen: »Nimm die Buchrolle, aus der du dem Volke laut vorgelesen hast, mit dir und komm hierher!« Da nahm Baruch, der Sohn Nerijas, die Rolle mit sich und kam zu ihnen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 36, 15, 'Nun sagten sie zu ihm: »Setze dich hin und lies sie auch uns laut vor!« Da las Baruch sie ihnen laut vor.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 36, 16, 'Als sie nun alle die Worte gehört hatten, sahen sie einander erschrocken an und sagten zu Baruch: »Wir müssen alle diese Worte unbedingt dem König berichten.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 36, 17, 'Hierauf wandten sie sich an Baruch mit der Frage: »Teile uns doch mit, wie du alle diese Worte, die er dir vorgesagt hat, niedergeschrieben hast.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 36, 18, 'Baruch antwortete ihnen: »Jeremia selber hat mir alle diese Worte vorgesprochen, und ich habe sie mit Tinte in das Buch eingetragen.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 36, 19, 'Da sagten die Fürsten zu Baruch: »Geh, verbirg dich, du selbst und Jeremia! Niemand darf wissen, wo ihr seid!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 36, 20, 'Hierauf begaben sie sich zum König in den Palasthof – die Buchrolle hatten sie im Zimmer des Staatsschreibers Elisama zurückgelassen – und erstatteten dem Könige Bericht über den ganzen Vorfall.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 36, 21, 'Da schickte der König den Jehudi hin, die Rolle zu holen, und dieser brachte sie aus dem Zimmer des Staatsschreibers Elisama herbei; sodann las Jehudi sie dem Könige und allen Fürsten vor, die um den König standen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 36, 22, 'Der König saß aber gerade in der Winterwohnung – es war nämlich der neunte Monat –, während das Feuer im Kohlenbecken vor ihm brannte.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 36, 23, 'Sooft nun Jehudi drei oder vier Spalten der Schriftrolle vorgelesen hatte, schnitt der König sie mit dem Federmesser ab und warf sie in das Feuer, das im Kohlenbecken brannte, bis die ganze Rolle im Feuer des Kohlenbeckens vernichtet war.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 36, 24, 'Der König aber und alle seine Diener, welche diese ganze Vorlesung anhörten, wurden nicht in Bestürzung versetzt und zerrissen ihre Kleider nicht;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 36, 25, 'ja sogar als Elnathan, Delaja und Gemarja den König dringend baten, die Rolle nicht zu verbrennen, hörte er doch nicht auf sie;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 36, 26, 'vielmehr gab der König dem Prinzen Jerahmeel sowie Seraja, dem Sohne Asriels, und Selemja, dem Sohne Abdeels, den Befehl, den Schreiber Baruch und den Propheten Jeremia zu verhaften; aber der HERR hielt sie verborgen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 36, 27, 'Da erging das Wort des HERRN an Jeremia, nachdem der König jene Rolle verbrannt hatte mitsamt den Worten, die Baruch so, wie Jeremia sie ihm vorsagte, aufgeschrieben hatte, folgendermaßen:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 36, 28, '»Nimm dir noch einmal eine andere Rolle und schreibe auf sie alle die vorigen Worte, welche auf der vorigen Rolle gestanden haben, die Jojakim, der König von Juda, verbrannt hat.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 36, 29, 'Gegen Jojakim aber, den König von Juda, sollst du folgende Drohung aussprechen: ›So hat der HERR gesprochen: Du hast jene Rolle verbrannt, indem du fragtest: Warum hast du auf sie (die Worte) geschrieben, der König von Babylon werde unfehlbar kommen und dieses Land verwüsten und Menschen und Vieh darin vertilgen?');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 36, 30, 'Darum bestimmt der HERR für Jojakim, den König von Juda, folgendes: Er soll keinen (Nachkommen) haben, der auf dem Throne Davids sitzt, und sein Leichnam soll hingeworfen daliegen, der Hitze bei Tage und der Kälte bei Nacht preisgegeben!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 36, 31, 'Und ich werde an ihm und seinen Nachkommen und seinen Dienern ihre Verschuldung heimsuchen und will über sie und über die Bewohner Jerusalems und über die Männer von Juda all das Unheil kommen lassen, das ich ihnen angedroht habe, ohne daß sie darauf hörten!‹«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 36, 32, 'So nahm denn Jeremia eine andere Buchrolle und gab sie dem Schreiber Baruch, dem Sohne Nerijas; dieser schrieb dann auf sie alle Worte, die in dem vom judäischen Könige Jojakim verbrannten Buche gestanden hatten, so, wie Jeremia sie ihm vorsagte; außerdem wurden auch noch viele andere gleichartige Worte hinzugefügt.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 37, 1, 'Zur Zeit, als Zedekia, der Sohn Josias, regierte, den Nebukadnezar, der König von Babylon, zum König über das Land Juda an Stelle Konjas, des Sohnes Jojakims, eingesetzt hatte,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 37, 2, 'hörte weder er noch seine Diener, noch die Bevölkerung des Landes auf die Worte, die der HERR durch den Propheten Jeremia an sie richtete.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 37, 3, 'Da sandte (einst) der König Zedekia den Juchal, den Sohn Selemjas, und den Priester Zephanja, den Sohn Maasejas, zum Propheten Jeremia und ließ ihm sagen: »Bete doch für uns zum HERRN, unserm Gott!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 37, 4, 'Jeremia bewegte sich aber damals noch in voller Freiheit inmitten des Volkes, da man ihn noch nicht ins Gefängnis geworfen hatte.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 37, 5, 'Das Heer des Pharaos war nämlich aus Ägypten aufgebrochen, und die Chaldäer, die Jerusalem belagerten, waren, als sie die Kunde davon erhielten, von Jerusalem abgezogen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 37, 6, 'Da erging das Wort des HERRN an den Propheten Jeremia folgendermaßen:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 37, 7, '»So spricht der HERR, der Gott Israels: Verkündet dem Könige von Juda, der euch zu mir gesandt hat, um mich zu befragen, folgende Botschaft: ›Wisse wohl: das Heer des Pharaos, das euch zur Hilfe ausgezogen ist, wird alsbald in sein Land Ägypten zurückkehren,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 37, 8, 'und zurückkehren werden die Chaldäer, um diese Stadt zu belagern, und werden sie erobern und in Flammen aufgehen lassen.‹');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 37, 9, 'So spricht der HERR: ›Täuscht euch nicht selbst mit der Meinung, daß die Chaldäer jetzt wirklich von euch abziehen werden; denn sie werden nicht abziehen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 37, 10, 'Nein, wenn ihr auch das ganze Heer der Chaldäer, die Krieg mit euch führen, besiegtet und nur einige schwerverwundete Männer von ihnen übrigblieben, so würden diese doch ein jeder in seinem Zelt aufstehen und diese Stadt in Flammen aufgehen lassen!‹«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 37, 11, 'Nun begab es sich, als das Heer der Chaldäer wegen des Heeres des Pharaos von Jerusalem abgezogen war,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 37, 12, 'daß Jeremia Jerusalem verlassen und sich in die Landschaft Benjamin begeben wollte, um dort eine Erbschaftssache im Kreise seiner Verwandten zu erledigen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 37, 13, 'Als er nun im Benjaminstor angelangt war, wo ein Mann namens Jirja, der Sohn Selemjas, des Sohnes Hananjas, als Hauptmann der Wache stand, hielt dieser den Propheten Jeremia an unter dem Vorwand: »Du willst zu den Chaldäern übergehen!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 37, 14, 'Jeremia entgegnete: »Das ist eine Lüge! Ich will nicht zu den Chaldäern übergehen!« und hörte nicht weiter nach ihm hin; aber Jirja ließ Jeremia festnehmen und vor die Fürsten führen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 37, 15, 'Diese waren Jeremia feindlich gesinnt, ließen ihn stäupen und im Hause des Staatsschreibers Jonathan, das man zum Gefängnis hergerichtet hatte, gefangensetzen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 37, 16, 'Als Jeremia so in das Brunnengebäude, und zwar in die unterirdischen Gewölbe gekommen war und dort lange Zeit zugebracht hatte,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 37, 17, 'sandte der König Zedekia (eines Tages) hin, ließ ihn holen und richtete in seinem Palast insgeheim die Frage an ihn: »Ist ein Wort vom HERRN ergangen?« Jeremia antwortete: »Jawohl! Nämlich der Gewalt des Königs von Babylon wirst du preisgegeben werden.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 37, 18, 'Weiter sagte Jeremia zum König Zedekia: »Was habe ich gegen dich und gegen deine Diener und gegen unser Volk verschuldet, daß ihr mich ins Gefängnis gesetzt habt?');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 37, 19, 'Wo sind denn jetzt eure Propheten, die euch mit Bestimmtheit geweissagt haben, der König von Babylon werde nicht gegen euch und gegen dieses Land heranziehen?');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 37, 20, 'Und nun – so höre doch, mein Herr und König, laß meine Bitte Gehör bei dir finden, laß mich nicht wieder in das Haus des Staatsschreibers Jonathan bringen, damit ich dort nicht sterben muß!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 37, 21, 'Da gab der König Zedekia Befehl, und man brachte Jeremia im Wachthof in Gewahrsam und gab ihm täglich einen Laib Brot aus der Bäckergasse, bis alles Brot in der Stadt aufgezehrt war. So blieb denn Jeremia im Wachthof.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 38, 1, 'Sephatja aber, der Sohn Matthans, und Gedalja, der Sohn Pashurs, und Juchal, der Sohn Selemjas, und Pashur, der Sohn Malkijas, hörten die Worte, die Jeremia an das ganze Volk richtete, daß er nämlich sagte:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 38, 2, '»So hat der HERR gesprochen: ›Wer hier in der Stadt verbleibt, wird durch das Schwert, durch den Hunger und die Pest ums Leben kommen; wer dagegen zu den Chaldäern hinausgeht, wird erhalten bleiben und sein Leben in Sicherheit bringen.‹');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 38, 3, 'Denn so hat der HERR gesprochen: ›Diese Stadt wird unfehlbar in die Gewalt des Heeres des Königs von Babylon gegeben werden, der sie erobern wird.‹«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 38, 4, 'Da sagten die Fürsten zum König: »Dieser Mensch sollte hingerichtet werden, er macht ja die Kriegsleute, die hier in der Stadt noch übriggeblieben sind, und die ganze Bevölkerung mutlos, indem er solche Worte vor ihnen ausspricht; denn dieser Mensch hat nicht das Wohl unsers Volkes im Auge, sondern dessen Unglück!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 38, 5, 'Da gab der König Zedekia ihnen zur Antwort: »Nun gut! Ihr habt freie Verfügung über ihn; der König ist ja euch gegenüber machtlos.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 38, 6, 'Da ließen sie Jeremia festnehmen und ihn in die Zisterne des Königssohnes Malkija werfen, die sich im Wachthof befand; in diese ließen sie Jeremia an Stricken hinab. In der Zisterne war aber kein Wasser, sondern nur Schlamm, in welchen Jeremia einsank.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 38, 7, 'Als aber der Äthiopier Ebedmelech, ein Beamter am königlichen Hof, erfuhr, daß man Jeremia in die Zisterne verbracht habe,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 38, 8, 'verließ er den königlichen Palast und machte dem König, der sich gerade im Benjaminstor aufhielt, folgende Meldung:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 38, 9, '»Mein Herr und König! Jene Männer haben in allem unrecht gehandelt, was sie dem Propheten Jeremia zugefügt haben, der von ihnen in die Zisterne geworfen worden ist; er muß ja da, wo er sich befindet, Hungers sterben!« Denn es war kein Brot mehr in der Stadt vorhanden.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 38, 10, 'Da erteilte der König dem Äthiopier Ebedmelech den Befehl: »Nimm von hier drei Männer mit dir und laß den Propheten Jeremia aus der Zisterne heraufziehen, ehe er stirbt!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 38, 11, 'Da nahm Ebedmelech die Männer mit sich, begab sich in den königlichen Palast in den Raum unter der Schatzkammer, nahm von dort Lappen von zerrissenen und abgetragenen Kleidungsstücken und ließ sie an Stricken zu Jeremia in die Zisterne hinab.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 38, 12, 'Alsdann rief er dem Jeremia zu, er möge diese Lappen von den zerrissenen und abgetragenen Kleidungsstücken sich unter die Achselhöhlen um die Stricke legen; und als Jeremia dies getan hatte,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 38, 13, 'zogen sie ihn an den Stricken aus der Zisterne herauf. Jeremia blieb dann im Wachthofe.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 38, 14, 'Hierauf sandte der König Zedekia hin und ließ den Propheten Jeremia zu sich holen in den dritten Eingang am Tempel des HERRN; und der König sagte zu Jeremia: »Ich habe eine Frage an dich zu richten: verschweige mir nichts!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 38, 15, 'Jeremia antwortete dem Zedekia: »Wenn ich es dir kundtue, wirst du mich sicherlich töten lassen, und wenn ich dir einen Rat gebe, wirst du doch nicht auf mich hören.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 38, 16, 'Da gab der König Zedekia dem Jeremia insgeheim die eidliche Zusicherung: »So wahr der HERR lebt, der uns diese Seele geschaffen hat: ich werde dich nicht töten lassen und werde dich nicht jenen Männern in die Hände liefern, die dir nach dem Leben trachten!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 38, 17, 'Da sagte Jeremia zu Zedekia: »So hat der HERR, der Gott der Heerscharen, der Gott Israels, gesprochen: ›Wenn du dich den Heeresobersten des Königs von Babylon ergibst, so wirst du am Leben bleiben, und diese Stadt wird nicht mit Feuer zerstört werden, und zwar wirst du samt deiner Familie das Leben behalten.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 38, 18, 'Wenn du dich aber den Heeresobersten des Königs von Babylon nicht ergibst, so wird diese Stadt in die Gewalt der Chaldäer gegeben, die sie mit Feuer verbrennen werden; und du selbst wirst ihrer Hand nicht entgehen.‹«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 38, 19, 'Da erwiderte der König Zedekia dem Jeremia: »Ich fürchte, daß man mich den Judäern, die schon zu den Chaldäern übergegangen sind, ausliefern wird und daß diese sich an mir vergreifen.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 38, 20, 'Jeremia aber entgegnete: »Man wird dich ihnen nicht ausliefern! Höre doch bei dem, was ich dir sage, auf die Weisung des HERRN, so wird es dir gut ergehen, und du wirst am Leben bleiben.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 38, 21, 'Weigerst du dich aber hinauszugehen, so ist dies das Wort, das der HERR mir geoffenbart hat:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 38, 22, 'Wisse wohl: alle Frauen, die im Palast des Königs von Juda noch übriggeblieben sind, werden zu den Heeresobersten des Königs von Babylon hinausgeführt werden und dabei ausrufen: ›Betrogen haben sie dich und überlistet, deine vertrauten Freunde! Nun deine Füße im Schlamm versinken, haben sie sich davongemacht!‹');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 38, 23, 'Alle deine Frauen aber samt deinen Kindern wird man zu den Chaldäern hinausführen, und du selbst wirst ihren Händen nicht entgehen, sondern von der Hand des Königs von Babylon ergriffen werden und die Verbrennung dieser Stadt herbeiführen!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 38, 24, 'Hierauf sagte Zedekia zu Jeremia: »Kein Mensch darf von dieser Unterredung etwas erfahren, sonst wärst du des Todes!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 38, 25, 'Wenn aber die Fürsten erfahren sollten, daß ich mich mit dir besprochen habe, und sie zu dir kommen und zu dir sagen: ›Teile uns doch mit, was du zum König gesagt hast, verschweige uns ja nichts, sonst lassen wir dich hinrichten! Und was hat der König zu dir gesagt?‹,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 38, 26, 'so antworte ihnen: ›Ich habe dem König meine inständige Bitte vorgetragen, er möge mich nicht wieder in das Haus Jonathans bringen lassen, damit ich dort nicht sterbe.‹«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 38, 27, 'Als nun wirklich alle Fürsten zu Jeremia kamen und ihn fragten, gab er ihnen genau nach jener Weisung des Königs Bescheid; da ließen sie ihn in Ruhe; denn von der Unterredung war nichts weiter in die Öffentlichkeit gedrungen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 38, 28, 'So verblieb denn Jeremia im Wachthof bis zu dem Tage, an dem Jerusalem erobert wurde.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 39, 1, 'Als aber Jerusalem erobert war – im neunten Regierungsjahre des judäischen Königs Zedekia, im zehnten Monat, war Nebukadnezar, der König von Babylon, mit seiner ganzen Heeresmacht vor Jerusalem gerückt und hatte die Belagerung begonnen;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 39, 2, 'im elften Regierungsjahre Zedekias aber, am neunten Tage des vierten Monats, wurde Bresche in die Stadtmauer gelegt –,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 39, 3, 'da kamen alle Fürsten des Königs von Babylon und ließen sich im Mitteltor nieder, nämlich [Nergal-Sarezer,] der Oberkämmerer Samgar-Nebusarsekim, der Obermagier Nergal-Sarezer und alle übrigen Fürsten des Königs von Babylon.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 39, 4, 'Als nun Zedekia, der König von Juda, und alle Kriegsleute das sahen, ergriffen sie die Flucht und verließen bei Nacht die Stadt auf dem Wege nach dem Königsgarten durch das Tor zwischen den beiden Mauern und zogen dann weiter der Jordan-Ebene zu.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 39, 5, 'Aber das Heer der Chaldäer setzte ihnen nach, und sie holten Zedekia in den Steppen von Jericho ein; sie nahmen ihn fest und brachten ihn zu Nebukadnezar, dem König von Babylon, nach Ribla in der Landschaft Hamath; der hielt dann Gericht über ihn.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 39, 6, 'Der König von Babylon ließ die Söhne Zedekias in Ribla vor dessen Augen schlachten, und ebenso verfuhr er mit allen vornehmen Judäern;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 39, 7, 'Zedekia aber ließ er blenden und in Ketten legen, um ihn nach Babylon zu bringen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 39, 8, 'Den königlichen Palast aber und die Häuser der Einwohnerschaft ließen die Chaldäer in Flammen aufgehen und rissen die Mauern Jerusalems nieder.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 39, 9, 'Den Rest des Volkes aber, sowohl die, welche in der Stadt übriggeblieben waren, als auch die Überläufer, die zu ihm übergegangen waren, und was vom Volk sonst noch am Leben war, ließ Nebusaradan, der Befehlshaber der Leibwache, nach Babylon führen;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 39, 10, 'von den geringen Leuten jedoch, die keinen Besitz hatten, ließ Nebusaradan, der Befehlshaber der Leibwache, einen Teil im Lande Juda zurück und wies ihnen an jenem Tage Weinberge und Äcker an.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 39, 11, 'In betreff Jeremias aber ließ Nebukadnezar, der König von Babylon, Nebusaradan, dem Befehlshaber der Leibwache, folgenden Befehl zugehen:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 39, 12, '»Nimm ihn, trage Sorge für ihn und tu ihm nichts zuleide, sondern verfahre mit ihm nach den Wünschen, die er gegen dich äußern wird!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 39, 13, 'Da sandten Nebusaradan, der Befehlshaber der Leibwache, und Nebusasban, der Oberkämmerer, und Nergal-Sarezer, der Obermagier, und alle übrigen Großen des Königs von Babylon hin,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 39, 14, 'ließen Jeremia aus dem Wachthofe holen und übergaben ihn Gedalja, dem Sohne Ahikams, des Sohnes Saphans, daß er ihn frei nach Hause gehen lasse; so blieb er denn inmitten des Volkes wohnen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 39, 15, 'An Jeremia war aber, als er noch im Wachthofe in Haft gehalten wurde, folgendes Wort des HERRN ergangen:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 39, 16, '»Gehe hin und sage zu dem Äthiopier Ebedmelech: ›So hat der HERR der Heerscharen, der Gott Israels, gesprochen: Nunmehr lasse ich meine Drohworte gegen diese Stadt in Erfüllung gehen zum Unheil, nicht zum Segen, und ihre Erfüllung wird dir an jenem Tage vor Augen treten.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 39, 17, 'Dich aber will ich an jenem Tage erretten‹ – so lautet der Ausspruch des HERRN –, ›und du sollst nicht den Männern in die Hände fallen, vor denen du in Angst bist;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 39, 18, 'vielmehr will ich dich entrinnen lassen, und du sollst nicht durch das Schwert umkommen, sondern sollst dein Leben in Sicherheit bringen, weil du auf mich vertraut hast!‹« – so lautet der Ausspruch des HERRN.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 40, 1, '(Dies ist) das Wort, das vom HERRN an Jeremia erging, nachdem Nebusaradan, der Befehlshaber der Leibwache, ihn von Rama aus entlassen hatte, wo er ihn, und zwar mit Ketten gefesselt, ausfindig gemacht hatte inmitten aller gefangenen Bewohner Jerusalems und Judas, die nach Babylon weggeführt werden sollten.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 40, 2, 'Als nämlich der Befehlshaber der Leibwache den Jeremia dort ausfindig gemacht hatte, sagte er zu ihm: »Der HERR, dein Gott, hatte diesem Ort dieses Unglück angedroht,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 40, 3, 'und der HERR hat es nun auch eintreten lassen und seine Drohung zur Ausführung gebracht: weil ihr gegen den HERRN gesündigt und auf seine Weisung nicht gehört habt, darum ist es euch so ergangen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 40, 4, 'Und nun, siehe: ich mache dich jetzt frei von den Ketten an deinen Händen. Gefällt es dir, mit mir nach Babylon zu gehen, so komm: ich werde Sorge für dich tragen; hast du aber keine Lust, mit mir nach Babylon zu gehen, so laß es! Wisse wohl: das ganze Land steht dir offen: du kannst gehen, wohin es dir beliebt und gut dünkt!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 40, 5, 'Als Jeremia sich dann nicht sofort entschließen konnte, fuhr er fort: »So kehre doch zurück zu Gedalja, dem Sohne Ahikams, des Sohnes Saphans, den der König von Babylon zum Statthalter über die Städte von Juda eingesetzt hat, und bleibe bei ihm inmitten des Volkes wohnen; oder gehe, wohin du sonst Lust hast!« Hierauf gab ihm der Befehlshaber der Leibwache Lebensmittel und ein Geschenk und entließ ihn.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 40, 6, 'Jeremia begab sich dann nach Mizpa zu Gedalja, dem Sohne Ahikams, und blieb dort bei ihm inmitten des Volkes, das im Lande übriggeblieben war.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 40, 7, 'Als nun alle Truppenführer, die sich mit ihren Mannschaften noch im offenen Lande befanden, erfuhren, daß der König von Babylon Gedalja, den Sohn Ahikams, zum Statthalter über das Land eingesetzt und ihm die Obhut über Männer, Frauen und Kinder und über die geringen Leute im Lande, die nicht nach Babylon weggeführt worden waren, anvertraut habe,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 40, 8, 'da kamen sie zu Gedalja nach Mizpa, nämlich Ismael, der Sohn Nethanjas, sowie Johanan und Jonathan, die Söhne Kareahs, ferner Seraja, der Sohn Thanhumeths, die Söhne Ophais aus Netopha, und Jesanja, der Sohn des Maachathiters, samt ihren Leuten.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 40, 9, 'Da richtete Gedalja, der Sohn Ahikams, des Sohnes Saphans, an sie und ihre Leute unter feierlicher Anrufung Gottes folgende Ansprache: »Fürchtet euch nicht davor, den Chaldäern untertan zu sein! Bleibt im Lande wohnen und unterwerft euch dem König von Babylon: ihr werdet euch gut dabei stehen!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 40, 10, 'Seht, ich selbst bleibe hier in Mizpa, um euch vor den Chaldäern, die zu uns kommen werden, zu vertreten; ihr aber mögt Wein, Obst und Öl sammeln und in euren Behältern einheimsen und könnt ruhig in euren Ortschaften wohnen, die ihr in Besitz genommen habt!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 40, 11, 'Ebenso erhielten alle Judäer, die sich in Moab und unter den Ammonitern sowie in Edom und in allen übrigen Ländern aufhielten, Kunde davon, daß der König von Babylon einen Rest (der Bevölkerung) in Juda übriggelassen und daß er Gedalja, den Sohn Ahikams, des Sohnes Saphans, über ihn als Statthalter eingesetzt habe.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 40, 12, 'Da kehrten alle diese Judäer aus allen Gegenden, wohin sie versprengt worden waren, zurück und kamen ins Land Juda zu Gedalja nach Mizpa; sie hatten dann eine reiche Wein- und Obsternte.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 40, 13, 'Als aber Johanan, der Sohn Kareahs, und alle Truppenführer, die noch im offenen Lande gestanden hatten, zu Gedalja nach Mizpa gekommen waren,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 40, 14, 'sagten sie zu ihm: »Weißt du wohl, daß Baalis, der König der Ammoniter, den Ismael, den Sohn Nethanjas, abgesandt hat, um dich zu ermorden?« Doch Gedalja, der Sohn Ahikams, schenkte ihnen keinen Glauben.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 40, 15, 'Darauf besprach sich Johanan, der Sohn Kareahs, heimlich mit Gedalja in Mizpa und sagte: »Laß mich doch hingehen und Ismael, den Sohn Nethanjas, erschlagen: kein Mensch soll etwas davon erfahren! Warum soll er dich ermorden, so daß alle Judäer, die sich hier bei dir gesammelt haben, wieder zerstreut werden und der letzte Rest von Juda zugrunde geht?«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 40, 16, 'Aber Gedalja, der Sohn Ahikams, antwortete Johanan, dem Sohne Kareahs: »Du darfst das nicht tun; denn was du da von Ismael sagst, ist nicht wahr!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 41, 1, 'Im siebten Monat aber kam Ismael, der Sohn Nethanjas, des Sohnes Elisamas, (ein Mann) von königlicher Abkunft und einer von den Großen des früheren Königs, in Begleitung von zehn Männern zu Gedalja, dem Sohne Ahikams, nach Mizpa. Als sie dort mit ihm zusammen beim Mahl saßen,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 41, 2, 'erhob sich Ismael, der Sohn Nethanjas, und die zehn Männer, die bei ihm waren, und erschlugen Gedalja, den Sohn Ahikams, des Sohnes Saphans, mit dem Schwert: so ermordete er den Mann, den der König von Babylon zum Statthalter über das Land eingesetzt hatte.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 41, 3, 'Auch alle Judäer, die bei Gedalja in Mizpa waren, sowie die chaldäischen Kriegsleute, die sich dort befanden, ließ Ismael niedermachen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 41, 4, 'Am anderen Tage nach der Ermordung Gedaljas aber, als noch niemand etwas von der Sache erfahren hatte,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 41, 5, 'kamen Männer aus Sichem, aus Silo und Samaria, achtzig an der Zahl, mit geschorenen Bärten, zerrissenen Kleidern und mit Schnittwunden am Leibe; sie hatten Opfergaben und Weihrauch bei sich, um diese (Gaben) in den Tempel des HERRN zu bringen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 41, 6, 'Da ging Ismael, der Sohn Nethanjas, von Mipza aus ihnen entgegen, indem er beim Gehen immerfort weinte; und als er mit ihnen zusammentraf, sagte er zu ihnen: »Kommt herein zu Gedalja, dem Sohne Ahikams!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 41, 7, 'Als sie dann aber ins Innere der Stadt gekommen waren, machte Ismael, der Sohn Nethanjas, sie nieder und warf sie in eine Zisterne hinein, er und die Leute, die bei ihm waren.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 41, 8, 'Es befanden sich aber unter ihnen zehn Männer, die zu Ismael sagten: »Töte uns nicht! Denn wir haben noch im Felde vergrabene Vorräte von Weizen, Gerste, Öl und Honig!« Da verschonte er sie und tötete sie nicht wie die anderen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 41, 9, 'Die Zisterne aber, in welche Ismael alle Leichen der ermordeten Männer werfen ließ, war eine große Zisterne, dieselbe, welche der König Asa zu Kriegszwecken gegen Baesa, den König von Israel, hatte anlegen lassen; diese füllte jetzt Ismael, der Sohn Nethanjas, mit den (Leichen der) Erschlagenen an');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 41, 10, 'und führte hierauf den gesamten Überrest der Bevölkerung, der sich in Mizpa befand, gefangen weg: die königlichen Frauen und alle in Mizpa übriggebliebenen Personen, die Nebusaradan, der Befehlshaber der Leibwache, der Obhut Gedaljas, des Sohnes Ahikams, überwiesen hatte – die führte Ismael, der Sohn Nethanjas, gefangen weg und machte sich auf den Weg, um zu den Ammonitern hinüberzuziehen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 41, 11, 'Als aber Johanan, der Sohn Kareahs, und alle Truppenführer, die sich bei ihm befanden, die ganze Freveltat erfuhren, die Ismael, der Sohn Nethanjas, verübt hatte,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 41, 12, 'boten sie alle ihre Leute auf und zogen zum Kampf gegen Ismael, den Sohn Nethanjas, aus, und sie trafen ihn am großen Teich bei Gibeon.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 41, 13, 'Als nun die ganze Volksmenge, die sich bei Ismael befand, Johanan, den Sohn Kareahs, und alle Truppenführer, die bei ihm waren, erblickten, freuten sie sich;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 41, 14, 'und die ganze Volksmenge, die Ismael gefangen aus Mizpa weggeführt hatte, machte kehrt und ging zu Johanan, dem Sohn Kareahs, über;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 41, 15, 'Ismael aber, der Sohn Nethanjas, ergriff mit acht Männern die Flucht vor Johanan und gelangte zu den Ammonitern.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 41, 16, 'Hierauf nahm Johanan, der Sohn Kareahs, samt allen Truppenführern, die bei ihm waren, den gesamten Rest des Volkes, den Ismael, der Sohn Nethanjas, nach der Ermordung Gedaljas, des Sohnes Ahikams, gefangen aus Mizpa weggeführt hatte, die Männer und Kriegsleute, die Weiber, Kinder und Hofbeamten, die er von Gibeon zurückgebracht hatte.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 41, 17, 'Sie machten sich dann auf den Weg und lagerten sich in der Herberge Kimhams, die in der Nähe von Bethlehem liegt, um von dort nach Ägypten zu ziehen');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 41, 18, '(aus Furcht) vor den Chaldäern, vor denen sie sich fürchteten, weil Ismael, der Sohn Nethanjas, Gedalja, den Sohn Ahikams, der vom Könige von Babylon zum Statthalter über das Land eingesetzt worden war, ermordet hatte.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 42, 1, 'Nun traten alle Truppenführer, auch Johanan, der Sohn Kareahs, und Asarja, der Sohn Hosajas, mit der gesamten Volksmenge, groß und klein, an den Propheten Jeremia heran');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 42, 2, 'und sagten zu ihm: »Schenke doch unserer inständigen Bitte Gehör und bete für uns zum HERRN, deinem Gott, für diesen ganzen Überrest! Wir sind ja nur als ein kleines Häuflein von der früheren großen Zahl übriggeblieben, wie du an uns mit eigenen Augen hier siehst.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 42, 3, 'Der HERR, dein Gott, wolle uns den Weg angeben, den wir einschlagen sollen, und wie wir uns zu verhalten haben!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 42, 4, 'Der Prophet Jeremia antwortete ihnen: »Ich bin einverstanden. Gut, ich will zum HERRN, eurem Gott, beten, wie ihr es wünscht, und will euch dann alles kundtun, was der HERR euch antworten wird: kein Wort will ich euch verschweigen.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 42, 5, 'Da sagten sie zu Jeremia: »Der HERR soll ein wahrhaftiger und zuverlässiger Zeuge gegen uns sein, wenn wir nicht genau der Weisung folgen werden, die der HERR, dein Gott, uns durch dich wird zukommen lassen!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 42, 6, 'Mag es uns erwünscht oder unerwünscht sein: – dem Gebot des HERRN, unsers Gottes, zu dem wir dich senden, wollen wir gehorchen, damit es uns gut ergehe, wenn wir der Weisung des HERRN, unsers Gottes, gehorsam sind!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 42, 7, 'Als dann nach Ablauf von zehn Tagen das Wort des HERRN an Jeremia ergangen war,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 42, 8, 'ließ er Johanan, den Sohn Kareahs, samt allen Truppenführern, die bei ihm waren, und das gesamte Volk, groß und klein, rufen');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 42, 9, 'und sagte zu ihnen: »So hat der HERR, der Gott Israels, zu dem ihr mich gesandt habt, um eure inständige Bitte vor ihn zu bringen, zu mir gesprochen:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 42, 10, '›Wenn ihr ruhig in diesem Lande wohnen bleibt, so will ich euch aufbauen, ohne wieder abzubrechen, und will euch einpflanzen, ohne wieder auszureißen; denn mir tut das Unheil leid, das ich euch habe widerfahren lassen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 42, 11, 'Fürchtet euch nicht vor dem Könige von Babylon, vor dem ihr jetzt in Angst seid! Fürchtet euch nicht vor ihm!‹ – so lautet der Ausspruch des HERRN –; ›denn ich bin mit euch, um euch zu helfen und euch aus seiner Hand zu erretten.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 42, 12, 'Ich will euch Gnade bei ihm finden lassen, daß er sich euer erbarmt und euch auf eurem Grund und Boden wohnen läßt!‹');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 42, 13, 'Wenn ihr aber sagt: ›Wir wollen nicht in diesem Lande bleiben‹, so daß ihr der Weisung des HERRN, eures Gottes, nicht gehorcht,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 42, 14, 'sondern sagt: ›Nein! Vielmehr nach Ägypten wollen wir ziehen, wo wir keinen Krieg mehr sehen und keinen Trompetenschall mehr hören und nicht mehr nach Brot zu hungern brauchen, und dort wollen wir uns niederlassen!‹ –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 42, 15, 'nun denn, so vernehmt das Wort des HERRN, ihr von Juda Übriggebliebenen! So hat der HERR der Heerscharen, der Gott Israels, gesprochen: ›Wenn ihr wirklich den Beschluß faßt, nach Ägypten zu ziehen, und euch dorthin begebt, um euch dort in fremdem Lande anzusiedeln,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 42, 16, 'so wird das Schwert, vor dem ihr euch jetzt fürchtet, euch dort im Lande Ägypten erreichen; und der Hunger, vor dem euch jetzt bange ist, wird sich euch dort in Ägypten an die Fersen heften, so daß ihr dort umkommen werdet!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 42, 17, 'Ja alle Männer, welche den Beschluß fassen, nach Ägypten zu ziehen, um dort in fremdem Lande zu leben, werden durch das Schwert, durch den Hunger und die Pest umkommen, und es soll keinen unter ihnen geben, der am Leben bleibt und dem Unheil entrinnt, das ich über sie verhängen werde!‹«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 42, 18, '»Denn so hat der HERR der Heerscharen, der Gott Israels, gesprochen: ›Wie mein Zorn und Grimm sich über die Bewohner Jerusalems ergossen hat, ebenso wird mein Grimm sich über euch ergießen, wenn ihr nach Ägypten zieht, und ihr sollt zur Verwünschung und zum abschreckenden Beispiel, zum Fluchwort und zur Beschimpfung werden und diese Stätte nicht wiedersehen!‹');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 42, 19, 'Dies ist es, was der HERR euch, den von Juda Übriggebliebenen, sagen läßt: ›Zieht nicht nach Ägypten!‹ Bedenkt wohl, daß ich euch heute ernstlich gewarnt habe!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 42, 20, 'Ihr habt euch ja selbst um den Preis des eigenen Lebens auf einen Irrweg begeben; denn ihr habt mich zum HERRN, eurem Gott, gesandt mit dem Auftrag: ›Bete für uns zum HERRN, unserm Gott! Und genau so, wie der HERR, unser Gott, es gebieten wird, so verkünde es uns, damit wir dann danach tun!‹');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 42, 21, 'Nun habe ich es euch heute verkündigt, aber ihr wollt der Weisung des HERRN, eures Gottes, nicht gehorchen, und zwar so, daß ihr alles zurückweist, was er mir an euch aufgetragen hat.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 42, 22, 'So wisset denn bestimmt, daß ihr durch das Schwert, durch den Hunger und die Pest den Tod finden werdet an dem Orte, wohin es euch zu ziehen gelüstet, um dort als Fremdlinge zu wohnen!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 43, 1, 'Als nun Jeremia dem ganzen Volk alle Worte, deren Verkündigung ihm vom HERRN, ihrem Gott, aufgetragen worden war, bis zu Ende mitgeteilt hatte, alle jene Worte,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 43, 2, 'da sagten Asarja, der Sohn Hosajas, und Johanan, der Sohn Kareahs, und alle übrigen widerspenstigen Männer, die mit Jeremia redeten: »Du redest die Unwahrheit! Der HERR, unser Gott, hat dich nicht gesandt, um (uns) zu gebieten: ›Ihr sollt nicht nach Ägypten ziehen, um dort in fremdem Lande zu wohnen!‹,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 43, 3, 'sondern Baruch, der Sohn Nerijas, hetzt dich gegen uns auf, in der Absicht, uns den Chaldäern in die Hände zu liefern, damit sie uns töten und uns nach Babylon in die Verbannung führen!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 43, 4, 'So kamen denn Johanan, der Sohn Kareahs, samt allen Truppenführern und das gesamte Volk der Weisung des HERRN, im Lande Juda zu bleiben, nicht nach;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 43, 5, 'vielmehr nahm Johanan, der Sohn Kareahs, samt allen Truppenführern den gesamten Überrest der Judäer, alle, die aus allen Völkerschaften, wohin sie sich zerstreut hatten, zurückgekehrt waren, um sich im Lande Juda niederzulassen,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 43, 6, 'die Männer samt den Weibern und Kindern, die königlichen Frauen, überhaupt alle die Personen, die Nebusaradan, der Befehlshaber der Leibwache, bei Gedalja, dem Sohne Ahikams, des Sohnes Saphans, zurückgelassen hatte, unter ihnen auch den Propheten Jeremia und Baruch, den Sohn Nerijas,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 43, 7, 'und zogen im Ungehorsam gegen die Weisung des HERRN nach Ägypten. Sie kamen dann nach Thachpanches.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 43, 8, 'Da erging das Wort des HERRN an Jeremia in Thachpanches folgendermaßen:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 43, 9, '»Hole große Steine herbei und grabe sie in den Lehmboden ein beim Ziegel-Ofen, der am Eingang zum Palast des Pharaos in Thachpanches steht, im Beisein judäischer Männer,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 43, 10, 'und sage zu ihnen: ›So hat der HERR der Heerscharen, der Gott Israels, gesprochen: Wisset wohl: ich will meinen Knecht Nebukadnezar, den König von Babylon, herkommen lassen und seinen Thron auf diesen Steinen, die du hier eingesenkt hast, aufstellen; er wird dann sein Thronzelt über ihnen ausspannen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 43, 11, 'Er wird herkommen und das Land Ägypten schlagen: was für den Tod bestimmt ist, verfällt dem Tode, was für die Gefangenschaft bestimmt ist, der Gefangenschaft, und was für das Schwert bestimmt ist, dem Schwert.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 43, 12, 'Dann wird er Feuer an die Tempel der Götter Ägyptens legen und sie verbrennen, und er wird sie wegführen und das Land Ägypten um sich wickeln, wie der Hirt seinen Mantel um sich wickelt, und dann unbehelligt wieder abziehen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 43, 13, 'Die Obelisken des Sonnentempels (von Heliopolis) im Lande Ägypten wird er zertrümmern und die Tempel der ägyptischen Götter in Flammen aufgehen lassen.‹«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 44, 1, '(Dies ist) das Wort, das an Jeremia erging in betreff aller in Ägypten wohnenden Judäer, die sich in Migdol und in Thachpanches, in Noph und im Gebiet von Pathros niedergelassen hatten; dasselbe lautet:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 44, 2, '»So hat der HERR der Heerscharen, der Gott Israels, gesprochen: ›Ihr selbst habt all das Unglück gesehen, das ich über Jerusalem und alle Städte Judas verhängt habe; ihr wißt, sie liegen heutigestags in Trümmern und sind unbewohnt');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 44, 3, 'infolge ihrer Bosheit, die sie verübt haben, um mich zu erbittern, indem sie hingingen, um anderen Göttern zu opfern und zu dienen, die sie nicht kannten, weder sie noch ihr, noch eure Väter.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 44, 4, 'Wohl hatte ich alle meine Knechte, die Propheten, früh und spät immer wieder zu euch gesandt mit der Mahnung: Verübt doch solchen Greuel nicht, den ich hasse!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 44, 5, 'Aber sie wollten nicht gehorchen und schenkten mir kein Gehör, daß sie von ihrem bösen Tun abgelassen und anderen Göttern nicht mehr geopfert hätten.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 44, 6, 'Da ergoß sich denn mein Grimm und mein Zorn und loderte in den Städten Judas und in den Straßen Jerusalems auf, so daß sie zu öden Trümmerstätten wurden, wie sie es heutigestags noch sind.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 44, 7, 'Und nun‹ – so hat der HERR der Heerscharen, der Gott Israels, gesprochen –: ›Warum richtet ihr ein so großes Unheil gegen euch selbst an, daß ihr bei euch Männer und Weiber, Kinder und Säuglinge aus Juda ausrottet, so daß ihr keinen Rest mehr für euch übriglaßt?');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 44, 8, 'Ihr reizt mich ja zum Zorn durch das Tun eurer Hände, indem ihr anderen Göttern in Ägypten opfert, wohin ihr euch begeben habt, um dort als Fremdlinge zu wohnen – (allerdings mit dem Ergebnis), daß ihr der Vernichtung verfallt und zu einem Fluchwort und zur Beschimpfung bei allen Völkern der Erde werdet.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 44, 9, 'Habt ihr die Übeltaten eurer Väter vergessen und die Übeltaten der Könige von Juda und die Übeltaten ihrer Weiber und eure eigenen Übeltaten und das viele Böse, das eure Weiber im Lande Juda und in den Straßen Jerusalems verübt haben?');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 44, 10, 'Noch heutigestags sind sie nicht zerknirscht und fürchten sich nicht und wandeln nicht nach meinem Gesetz und nach meinen Geboten, die ich euch und euren Vätern zur Pflicht gemacht habe.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 44, 11, 'Darum‹ – so hat der HERR der Heerscharen, der Gott Israels, gesprochen –: ›nunmehr will ich mein Angesicht gegen euch richten zum Unheil, und zwar um ganz Juda auszurotten;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 44, 12, 'und ich will den Überrest der Judäer hinwegraffen, deren Absicht darauf gerichtet (gewesen) ist, nach Ägypten zu ziehen, um dort als Fremdlinge zu wohnen: sie sollen alle vertilgt werden! in Ägypten sollen sie fallen, durch das Schwert und durch den Hunger sollen sie aufgerieben werden, klein und groß, durch das Schwert und durch den Hunger sollen sie umkommen und zu einem abschreckenden Beispiel, zu einem Fluchwort, zur Verwünschung und Beschimpfung werden!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 44, 13, 'Ja, heimsuchen will ich die, welche sich in Ägypten niedergelassen haben, wie ich Jerusalem heimgesucht habe, durchs Schwert, durch Hunger und durch die Pest;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 44, 14, 'und unter dem Überrest der Judäer, die hergekommen sind, um hier in Ägypten als Fremdlinge zu wohnen, soll es keinen geben, der seinem Geschick entgeht und am Leben bleibt, um ins Land Juda zurückzukehren, wohin sie sich zurücksehnen und wo sie gern wieder wohnen möchten; denn sie sollen nicht dorthin zurückkehren außer einigen Entronnenen!‹«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 44, 15, 'Da antworteten dem Jeremia alle Männer, welche wußten, daß ihre Frauen anderen Göttern räucherten, und alle Frauen, die in großer Schar dabei standen, und das gesamte Volk, das in Ägypten (und) Pathros wohnte, folgendermaßen:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 44, 16, '»Was die Forderung betrifft, die du im Namen des HERRN an uns gerichtet hast, so wisse, daß wir auf dich nicht hören!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 44, 17, 'Wir wollen vielmehr das Gelübde, das wir geleistet haben, nämlich der Himmelskönigin zu räuchern und ihr Trankopfer zu spenden, getreulich ausführen, ganz so wie wir und unsere Väter, unsere Könige und Fürsten es in den Ortschaften Judas und auf den Straßen Jerusalems getan haben! Damals hatten wir Brot in Fülle, befanden uns wohl und wußten nichts von Unglück.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 44, 18, 'Aber seitdem wir aufgehört haben, der Himmelskönigin zu räuchern und ihr Trankopfer zu spenden, haben wir Mangel an allem gelitten und sind durch das Schwert und durch den Hunger aufgerieben worden.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 44, 19, 'Und wenn wir der Himmelskönigin jetzt (wieder) Opfer verbrennen und ihr Trankopfer spenden – geschieht es etwa ohne die Zustimmung unserer Ehemänner, daß wir ihr zu Ehren Kuchen backen, indem wir ihre Gestalt darauf abbilden, und ihr Trankopfer spenden?«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 44, 20, 'Da gab Jeremia dem gesamten Volk, den Männern und Frauen und allen denen, die ihm mit solchen Reden entgegengetreten waren, folgende Antwort:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 44, 21, '»Jawohl, die Räucherei, die ihr in den Ortschaften Judas und in den Straßen Jerusalems getrieben habt, ihr und eure Väter, eure Könige und Fürsten und die Bevölkerung des Landes – hat der HERR ihrer etwa nicht gedacht und sie nicht in Erinnerung behalten?');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 44, 22, 'Ja, weil der HERR es wegen eures verwerflichen Treibens und wegen der Greuel, die ihr verübtet, nicht länger ertragen konnte, darum ist euer Land zur Einöde, zum abschreckenden Beispiel und zu einem Fluchwort geworden, leer von Bewohnern, wie es jetzt noch der Fall ist!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 44, 23, 'Eben zur Strafe dafür, daß ihr (den Götzen) Opfer verbrannt und dadurch gegen den HERRN gesündigt und auf die Weisungen des HERRN nicht gehört und nicht nach seinem Gesetz und seinen Geboten und Vorschriften gelebt habt: eben darum ist dieses Unglück, in dem ihr euch gegenwärtig befindet, über euch gekommen!« –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 44, 24, 'Weiter sagte Jeremia zu dem gesamten Volk und besonders zu allen Frauen: »Vernehmt das Wort des HERRN, ihr Judäer alle, die ihr in Ägypten wohnt!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 44, 25, 'So hat der HERR der Heerscharen, der Gott Israels, gesprochen: ›Ihr und eure Frauen, ihr habt es mit eurem Munde gelobt und führt es auch tatsächlich aus! Ihr sagt: Wir wollen unsere Gelübde, die wir geleistet haben, nämlich der Himmelskönigin Opfer zu verbrennen und ihr Trankopfer zu spenden, getreulich ausführen! So erfüllt denn ja eure Gelübde und führt getreulich das aus, was ihr gelobt habt!‹«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 44, 26, '»Darum vernehmt das Wort des HERRN, ihr Judäer alle, die ihr in Ägypten wohnt: ›Fürwahr, ich schwöre bei meinem großen Namen‹ – so hat der HERR gesprochen –: ›Niemals soll fortan noch mein Name in ganz Ägypten von irgend einem Judäer in den Mund genommen werden, daß er etwa sagte: So wahr Gott der HERR lebt!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 44, 27, 'Wisset wohl: ich will die Augen über ihnen offen halten zum Verderben, nicht zum Heil! Und es sollen alle Judäer, die im Lande Ägypten weilen, durch das Schwert und durch den Hunger umkommen, bis sie völlig vernichtet sind!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 44, 28, 'Ja die dem Schwert Entronnenen, die aus dem Lande Ägypten ins Land Juda heimkehren, sollen nur wenige an Zahl sein; dann wird der gesamte Überrest der Judäer, die nach Ägypten gezogen sind, um sich dort als Fremdlinge aufzuhalten, – der wird dann erkennen, wessen Wort sich verwirklicht, das meine oder das ihre!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 44, 29, 'Und dies soll für euch das Zeichen sein‹ – so lautet der Ausspruch des HERRN –, ›daß ich euch an diesem Orte heimsuchen werde – damit ihr erkennt, daß meine Unheilsdrohungen gegen euch unfehlbar in Erfüllung gehen werden‹:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 44, 30, 'so hat der HERR gesprochen: ›Fürwahr, ich will den Pharao Hophra, den König von Ägypten, in die Hand seiner Gegner und Todfeinde fallen lassen, so wie ich Zedekia, den König von Juda, in die Hand Nebukadnezars, des Königs von Babylon, seines Gegners und Todfeindes, habe fallen lassen.‹«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 45, 1, '(Dies ist) das Wort, das der Prophet Jeremia an Baruch, den Sohn Nerijas richtete, als dieser im vierten Regierungsjahre Jojakims, des Sohnes Josias, des Königs von Juda, die betreffenden Worte so, wie Jeremia sie ihm vorsagte, in ein Buch niedergeschrieben hatte; das Wort lautete:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 45, 2, '»So hat der HERR, der Gott Israels, in bezug auf dich, Baruch, gesprochen:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 45, 3, '›Du klagst: O wehe mir! Der HERR fügt noch Kummer zu meinem Schmerz hinzu! Müde bin ich von allem Seufzen und finde keine Ruhe!‹');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 45, 4, 'Sage zu ihm: ›So hat der HERR gesprochen: Wisse wohl: was ich selbst gebaut habe, das breche ich wieder ab, und was ich gepflanzt habe, das reiße ich wieder aus [und zwar betrifft dies die ganze Erde];');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 45, 5, 'und da willst du Großes für dich verlangen? Verlange es nicht! Denn bedenke wohl: ich verhänge Unglück über alles Fleisch‹, – so lautet der Ausspruch des HERRN –; ›dir aber gewähre ich, mit dem Leben davonzukommen an allen Orten, wohin du dich begeben wirst!‹«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 46, 1, 'Was als Wort des HERRN an den Propheten Jeremia in betreff der (heidnischen) Völker ergangen ist:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 46, 2, 'Über Ägypten: in betreff des Heeres des Pharaos Necho, des Königs von Ägypten, das am Euphratstrom bei Karchemisch stand und von Nebukadnezar, dem König von Babylon, im vierten Regierungsjahre des judäischen Königs Jojakim, des Sohnes Josias, geschlagen wurde:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 46, 3, 'Rüstet Schild und Tartsche und tretet an zum Kampf!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 46, 4, 'Schirret die Rosse an und sitzet auf, ihr Reiter! Stellt euch auf im Helmschmuck, macht die Lanzen scharf, legt euch die Panzer an!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 46, 5, 'Warum sehe ich sie verzagt zurückweichen? Warum sind ihre Mannen mutlos und ergreifen die Flucht, ohne sich umzuwenden? »Entsetzen ringsum!« – so lautet der Ausspruch des HERRN –;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 46, 6, '»der Behendeste kann nicht entfliehen und der Tapferste nicht entrinnen! Dort im Norden, am Ufer des Euphratstromes, sind sie gestrauchelt und zu Fall gekommen!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 46, 7, 'Wer war’s doch, der wie der Nil emporstieg, daß seine Fluten wie Ströme wogten?');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 46, 8, 'Ägypten stieg wie der Nil empor, daß seine Fluten wie Ströme wogten, und es drohte: »Ich will emporsteigen, das Land überschwemmen, will Städte vertilgen samt ihren Bewohnern!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 46, 9, 'Stürmt heran, ihr Rosse, und rast daher, ihr Wagen! Und die Mannen mögen ausrücken, die Äthiopier und die schildbewehrten Putäer und die Luditer, die den Bogen führen und spannen!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 46, 10, 'Ja, dieser Tag ist für Gott, den HERRN der Heerscharen, ein Tag der Rache, um seinen Widersachern zu vergelten: da frißt das Schwert, bis es satt ist, und berauscht sich an ihrem Blut, denn ein Schlachtfest hält Gott, der HERR der Heerscharen, im Nordland am Euphratstrom.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 46, 11, 'Gehe nach Gilead hinauf und hole Balsam, jungfräuliche Tochter Ägypten! Umsonst wendest du ein Heilmittel nach dem andern an: für dich gibt’s keine Heilung mehr!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 46, 12, 'Die Völker vernehmen deine Schande, und die Erde hallt von deinem Wehgeschrei wider; denn ein Krieger ist über den andern gefallen: miteinander sind beide niedergestürzt!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 46, 13, '(Dies ist) das Wort, das der HERR an den Propheten Jeremia gerichtet hat, als Nebukadnezar, der König von Babylon, kommen sollte, um das Land Ägypten niederzuwerfen:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 46, 14, 'Verkündet es in Ägypten und ruft es in Migdol aus, ruft es auch in Memphis und Daphne aus! Gebietet: Stelle dich auf (zur Wehr) und mache dich bereit, denn schon frißt das Schwert rings um dich her!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 46, 15, 'Warum sind deine Helden niedergeworfen? Sie haben nicht standgehalten, denn der HERR hat sie niedergestoßen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 46, 16, 'Er hat viele straucheln lassen; ja, einer stürzt über den andern, so daß sie ausrufen: »Auf! Laßt uns heimkehren zu unserm Volk und in unser Heimatland vor dem gewalttätigen Schwert!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 46, 17, 'Nennt den Namen des Pharaos, des Königs von Ägypten: ›Toben, das den richtigen Zeitpunkt versäumt hat‹.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 46, 18, '»So wahr ich lebe« – so lautet der Ausspruch des Königs, dessen Name ›HERR der Heerscharen‹ ist –: »Wie der Thabor unter den Bergen und wie der Karmel am Meer, so wird er heranziehen!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 46, 19, 'Setze dir die Geräte zur Auswanderung in Bereitschaft, du Einwohnerschaft, Tochter Ägypten! Denn Memphis wird zur Einöde werden, wird eingeäschert, menschenleer!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 46, 20, 'Eine wunderschöne junge Kuh ist Ägypten; aber es kommt, ja es kommt die Bremse von Norden her.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 46, 21, 'Auch seine Söldner, die es in seiner Mitte wie Mastkälber hat, ja, auch sie haben kehrt gemacht, haben sich insgesamt zur Flucht gewandt und nicht standgehalten, denn ihr Unglückstag ist über sie hereingebrochen, die Zeit ihrer Heimsuchung!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 46, 22, 'Man hört etwas daherkommen wie das Rascheln einer Schlange, die davoneilt; denn sie rücken mit Heeresmacht heran und fallen mit Äxten über das Land her wie Holzhauer.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 46, 23, '»Sie hauen seinen Wald um« – so lautet der Ausspruch des HERRN –, »der unübersehbar ist; denn ihrer sind mehr als der Heuschrecken, und unzählbar ist ihre Menge!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 46, 24, 'Zuschanden wird die Tochter Ägypten, der Gewalt des nordischen Volkes wird sie preisgegeben!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 46, 25, 'Gesprochen hat der HERR der Heerscharen, der Gott Israels: »Wisset wohl: ich halte (jetzt) Abrechnung mit dem Amon von No sowie mit dem Pharao und ganz Ägypten samt seinen Göttern und Königen, ja mit dem Pharao samt denen, die sich auf ihn verlassen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 46, 26, 'Und ich gebe sie in die Gewalt ihrer Todfeinde, und zwar in die Gewalt Nebukadnezars, des Königs von Babylon, und in die Gewalt seiner Knechte. Nachmals aber wird das Land wieder bewohnt sein wie in den Tagen der Vorzeit« – so lautet der Ausspruch des HERRN.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 46, 27, '»Du aber, fürchte dich nicht, mein Knecht Jakob, und laß dir nicht bange sein, Israel! Denn wisse wohl: ich will dich erretten aus fernen Landen und deine Kinder aus dem Lande ihrer Gefangenschaft, dann wird Jakob heimkehren und in Ruhe und Sicherheit leben, ohne daß jemand ihn aufschreckt.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 46, 28, 'Du also, fürchte dich nicht, mein Knecht Jakob!« – so lautet der Ausspruch des HERRN –, »ich bin ja mit dir; denn über alle Völker, unter die ich dich zerstreut habe, will ich völlige Vernichtung bringen; dich aber will ich nicht völlig vernichten, sondern dich mit Maßen züchtigen; denn ganz ungestraft kann ich dich nicht lassen.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 47, 1, '(Dies ist) das Wort des HERRN, das an den Propheten Jeremia in betreff der Philister ergangen ist, bevor der Pharao Gaza erobert hatte:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 47, 2, 'So hat der HERR gesprochen: Sehet, Wasser fluten heran von Norden her und werden zu einem überwallenden Wildbach! Sie überschwemmen das Land und alles, was darin ist, die Städte samt ihren Bewohnern, so daß die Menschen laut schreien und alle Bewohner des Landes heulen!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 47, 3, 'Vor dem dröhnenden Hufschlag seiner Hengste, vor dem Rasseln seiner Kriegswagen, dem Rollen seiner Räder wenden Väter sich nicht nach ihren Kindern um, weil die Angst ihre Arme lähmt;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 47, 4, 'denn der Tag ist gekommen, der allen Philistern den Untergang bringt und für Tyrus und Sidon den letzten Helfer ausrottet, der noch übriggeblieben ist; denn der HERR will die Philister vernichten, die Abkömmlinge der von der Insel Kaphtor Gekommenen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 47, 5, 'Gaza hat sich kahl geschoren, zerstört ist Askalon; o Überrest der Enakiter, wie lange wirst du dich noch blutig ritzen müssen!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 47, 6, 'Wehe, Schwert des HERRN! Wann wirst du endlich zur Ruhe kommen? Fahre in deine Scheide zurück, mache ein Ende und halte dich still!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 47, 7, 'Aber wie sollte es zur Ruhe kommen, da doch der HERR es entboten hat? Gegen Askalon und gegen das ganze Gestade des Meeres, dorthin hat er es beordert!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 1, 'Über Moab: So hat der HERR der Heerscharen, der Gott Israels, gesprochen: Wehe über Nebo, denn es ist verwüstet! Zuschanden geworden, erobert ist Kirjathaim: zuschanden geworden ist die hohe Feste und gestürzt!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 2, 'Dahin ist der Ruhm der Moabiter! In Hesbon sinnt man auf Unheil gegen sie: »Kommt, wir wollen sie ausrotten, daß sie kein Volk mehr sind!« Auch du, Madmen, wirst vernichtet werden: das Schwert fährt hinter dir her!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 3, 'Horch! Wehgeschrei schallt von Horonaim her: »Verwüstung und gewaltiger Zusammenbruch!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 4, 'Zertrümmert ist das Moabiterland: sein Wehgeschrei erschallt bis Zoar hin!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 5, 'Ach, die Anhöhe von Luhith steigt man unter Weinen hinan! Ach, am Abhang von Horonaim hört man Angstgeschrei über die Vernichtung:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 6, '»Fliehet, rettet euer Leben und fristet es gleich dem Wacholderstrauch in der Wüste!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 7, 'Denn weil du dich auf deine Machwerke und auf deine Schätze verlassen hast, sollst nun auch du erobert werden, und Kamos muß in die Verbannung wandern, seine Priester und Oberen allzumal;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 8, 'und es kommt der Verwüster über alle deine Städte; keine einzige wird verschont bleiben; auch das Tal unten geht zugrunde, und die Ebene oben wird verheert, wie der HERR angedroht hat.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 9, 'Gebt Moab Flügel, damit es auf und davon fliege! Und seine Städte werden zur Einöde werden, so daß niemand mehr darin wohnt.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 10, 'Verflucht sei, wer das Werk des HERRN lässig betreibt, und verflucht, wer sein Schwert vom Blutvergießen zurückhält!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 11, 'Sorglos hat Moab von Jugend auf gelebt und ungestört auf seinen Hefen geruht: es ist nie aus einem Faß in ein anderes umgegossen worden und niemals in Gefangenschaft gewandert; daher hat es auch seinen Geschmack beibehalten, und sein Duft ist unverändert geblieben.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 12, '»Darum, wisset wohl: es kommt die Zeit« – so lautet der Ausspruch des HERRN –, »da will ich ihm Küfer senden, die sollen es umschütten und seine Fässer entleeren und seine Krüge zerschlagen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 13, 'Da wird dann Moab am Kamos zuschanden werden, gleichwie die vom Hause Israel an Bethel, auf das sie ihre Zuversicht setzten, zuschanden geworden sind.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 14, 'Wie könnt ihr nur sagen: ›Wir sind tapfere Krieger und wehrhafte Männer zum Kampf!‹');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 15, 'Der Verwüster Moabs und seiner Städte ist im Anzug, und seine auserlesene junge Mannschaft sinkt hin zur Schlachtung« – so lautet der Ausspruch des Königs, dessen Name ›HERR der Heerscharen‹ ist –:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 16, '»Moabs Untergang steht nahe bevor, und sein Verderben eilt schnell herbei.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 17, 'Bezeugt ihm Beileid, ihr seine Umwohner insgesamt und alle, die ihr von seinem Ruhm gehört habt! Ruft aus: »Wie ist doch der starke Herrscherstab zerbrochen, das ruhmvolle Zepter!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 18, 'Steige von deinem Ehrenplatz herab und setze dich auf die nackte Erde, du Bewohnerschaft, Tochter Dibon! Denn der Verwüster Moabs ist im Anzug gegen dich und zerstört deine Burgen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 19, 'Tritt an die Straße und spähe aus, Bewohnerschaft von Aroer! Richte an die Flüchtlinge und an die Entronnenen die Frage: »Was ist geschehen?«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 20, 'Moab ist zuschanden geworden, ach, es ist in Verzweiflung: wehklagt und jammert! Verkündet am Arnon, daß Moab verwüstet ist!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 21, 'Ja, das Strafgericht ist ergangen über die weite Ebene, über Holon, über Jahza und Mephaath,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 22, 'über Dibon, Nebo und Beth-Diblathaim,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 23, 'über Kirjathaim, Beth-Gamul und Beth-Meon,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 24, 'über Kerioth, Bozra und alle (anderen) Ortschaften des Moabiterlandes, die fernen wie die nahen!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 25, '»Abgehauen ist Moabs Horn und sein Arm zerschmettert!« – so lautet der Ausspruch des HERRN.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 26, 'Macht Moab trunken! Denn gegen den HERRN hat es sich überhoben: möge es kopfüber in sein Gespei stürzen und selber auch zum Gespött werden!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 27, 'Oder ist dir etwa Israel nicht zum Gespött gewesen? Hat man es etwa unter Dieben ertappt, daß du, sooft du von ihm sprachst, höhnisch den Kopf schütteltest?');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 28, 'Verlaßt die Städte und macht euch in den Felsklüften heimisch, ihr Bewohner Moabs, und tut es der Wildtaube gleich, die an den Hängen der gähnenden Abgründe nistet!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 29, 'Wir haben von Moabs übergroßem Stolz gehört, von seinem Hochmut und seinem Stolz, von seinem Trotz und seinem hochfahrenden Sinn.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 30, '»Ich kenne wohl« – so lautet der Ausspruch des HERRN – »seinen Übermut und seine eitlen Prahlereien: ihr ganzes Tun ist unehrlich.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 31, 'Darum muß ich um Moab wehklagen und um ganz Moab jammern; über die Bewohner von Kir-Heres seufzt man.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 32, 'Mehr als man um Jaser geweint hat, muß ich um dich weinen, Weinstock von Sibma, um dich, dessen Ranken über den See hinüberwanderten, ja bis zum See von Jaser reichten: in deine Obsternte und deine Weinlese ist der Verwüster hereingebrochen,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 33, 'und verschwunden sind Freude und Jubel aus dem Fruchtgefilde und aus dem Lande Moab. Dem Wein in den Kufen mache ich ein Ende: man tritt die Kelter nicht mehr unter Jubelruf; der laute Ruf ist jetzt kein Jubelruf mehr!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 34, 'Vom wehklagenden Hesbon her lassen sie ihr Geschrei bis Eleale, bis Jahaz hin erschallen, von Zoar her bis Horonaim, bis Eglath-Schelischija hin; ja auch die Wasser von Nimrim sollen zu Wüsteneien werden.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 35, '»Und ich will dagegen einschreiten« – so lautet der Ausspruch des HERRN –, »daß man in Moab noch zur Opferhöhe hinaufsteigt und seinem Gott dort Opfer anzündet.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 36, 'Darum klagt mein Herz um Moab laut wie Flötenschall, und um die Einwohner von Kir-Heres klagt mein Herz laut wie Flötenschall darum, daß alles, was sie an Hab und Gut erworben hatten, verloren gegangen ist.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 37, 'Denn alle Häupter sind zur Glatze geschoren und alle Bärte abgeschnitten; an allen Händen sind Schnittwunden sichtbar und Sackleinen umgürtet die Hüften.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 38, 'Auf allen Dächern Moabs und auf seinen Straßen ist nichts als Trauerklage; denn »ich habe Moab zerschlagen wie ein Gefäß, an dem niemand Gefallen hat!« – so lautet der Ausspruch des HERRN.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 39, 'Wie ist es doch voller Verzweiflung! Wehklaget! wie hat doch Moab schmählich den Rücken gewandt! Ja, ein Gegenstand des Spottes und Entsetzens ist Moab für alle Nachbarvölker geworden!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 40, 'Denn so hat der HERR gesprochen: »Seht, einem Adler gleich fliegt (der Feind) heran und breitet seine Schwingen über Moab aus!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 41, 'Die Städte sind bezwungen und die Burgen erobert, und den moabitischen Kriegern wird an jenem Tage zumute sein wie einem Weibe in Kindesnöten.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 42, 'Vernichtet wird Moab, daß es kein Volk mehr ist; denn gegen den HERRN hat es sich überhoben.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 43, '»Grauen und Grube und Garn kommen über euch, Bewohner von Moab!« – so lautet der Ausspruch des HERRN.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 44, '»Wer dem Grauen entrinnt, stürzt in die Grube, und wer der Grube entstiegen ist, fängt sich im Garn, wenn ich diese Schrecken über die Moabiter hereinbrechen lasse im Jahre ihrer Heimsuchung!« – so lautet der Ausspruch des HERRN.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 45, 'Im Schatten Hesbons machen die Flüchtlinge erschöpft halt; doch Feuer bricht aus Hesbon hervor und eine Flamme mitten aus Sihons Palast: die versengt die Schläfen der Moabiter und den Scheitel der Söhne des Kampfgetümmels.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 46, 'Wehe dir, Moab! Verloren ist das Volk des Kamos!; denn deine Söhne sind in die Gefangenschaft weggeführt und deine Töchter in die Knechtschaft. –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 47, '»Doch ich will das Geschick Moabs am Ende der Tage wieder wenden!« – so lautet der Ausspruch des HERRN. Bis hierher geht der Gerichtsspruch über Moab.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 49, 1, 'Über die Ammoniter: So hat der HERR gesprochen: »Hat denn Israel keine Söhne mehr, oder hat es keinen Erben? Wie kommt es, daß Milkom die Erbschaft in Gad angetreten und sein Volk in den dortigen Städten Wohnung genommen hat?');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 49, 2, 'Darum wisset wohl: es kommt die Zeit« – so lautet der Ausspruch des HERRN –, »da lasse ich gegen die Ammoniterstadt Rabba Kriegsgeschrei erschallen; sie soll dann zum Schutthaufen werden, und ihre Tochterstädte sollen in Flammen aufgehen: da soll dann Israel seine Erben wieder beerben!« – so lautet der Ausspruch des HERRN.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 49, 3, 'Erhebe Wehgeschrei, Hesbon, denn Ai ist zerstört! Jammert, ihr Tochterstädte Rabbas, umgürtet euch mit Sackleinen, wehklagt und lauft in den Hürden hin und her! Denn Milkom muß in die Gefangenschaft wandern, seine Priester und Oberen allzumal!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 49, 4, 'Was prahlst du mit deinen Tälern? Dein Tal ist überströmt, du abtrünnige Tochter, die im Vertrauen auf ihre Schätze sich rühmt: »Wer sollte an mich herankommen?«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 49, 5, '»Wisse wohl: ich will Schrecken über dich hereinbrechen lassen von allen Seiten ringsum!« – so lautet der Ausspruch Gottes, des HERRN der Heerscharen –; »und ihr sollt weggetrieben werden, ein jeder, ohne daß er sich umzublicken vermag, und niemand soll die Flüchtigen wieder sammeln!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 49, 6, 'Doch nachmals will ich das Geschick der Ammoniter wieder wenden!« – so lautet der Ausspruch des HERRN.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 49, 7, 'Über Edom: So hat der HERR der Heerscharen gesprochen: »Gibt’s denn keine Weisheit mehr in Theman? Ist denn den Verständigen die Klugheit abhanden gekommen und ihnen die Weisheit ausgegangen?');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 49, 8, 'Fliehet, macht euch davon, verkriecht euch in tiefe Verstecke, ihr Bewohner Dedans! Denn den Untergang lasse ich über Esau hereinbrechen, die Zeit, wo ich mit ihm abrechne.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 49, 9, 'Wenn Weingärtner bei dir einbrechen, lassen sie da nicht eine Nachlese übrig? Wenn Diebe in der Nacht (kommen), rauben sie doch nur so viel, bis sie genug haben.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 49, 10, 'Doch ich selbst durchsuche Esau und decke seine Schlupfwinkel auf; und will er sich verstecken, so kann er es nicht: vernichtet wird seine Nachkommenschaft samt seinen Bruderstämmen und seinen Nachbarn, so daß nichts mehr von ihm vorhanden ist.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 49, 11, 'Überlaß mir deine Waisen: ich will sie am Leben erhalten, und deine Witwen mögen auf mich vertrauen!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 49, 12, 'Denn so hat der HERR gesprochen: »Fürwahr, solche, die es nicht verdienten, den Becher zu trinken, haben ihn trinken müssen, und du solltest frei ausgehen? Nein, du sollst nicht ungestraft bleiben, sondern mußt unweigerlich trinken!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 49, 13, 'Denn ich habe bei mir selbst geschworen« – so lautet der Ausspruch des HERRN –: »Bozra soll zum abschreckenden Beispiel, zum Gespött, zur Wüste und zum Fluchwort werden und alle zugehörigen Ortschaften zu Einöden auf ewig!« –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 49, 14, 'Eine Kunde habe ich vom HERRN her vernommen, und eine Botschaft ist unter die Völker gesandt worden: »Versammelt euch und zieht gegen Edom heran und macht euch auf zum Kampf!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 49, 15, 'Denn wisse wohl: klein mache ich dich unter den Völkern, verachtet unter den Menschen deine Furchtbarkeit!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 49, 16, 'Betört hat dich dein vermessener Sinn, weil du in Felsenklüften wohnst und Bergeshöhen besetzt hältst. »Wenn du auch dein Nest so hoch anlegst wie der Adler: ich stürze dich doch von dort hinab!« – so lautet der Ausspruch des HERRN.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 49, 17, '»Und Edom soll zum Gegenstand des Erstarrens werden: jeder, der an ihm vorüberwandert, soll sich entsetzen und über alle seine Leiden zischen!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 49, 18, 'Wie Sodom und Gomorrha und ihre Nachbarstädte einst von Grund aus zerstört worden sind« – so lautet der Ausspruch des HERRN –, »ebenso soll auch dort niemand mehr wohnen und kein Menschenkind sich darin aufhalten.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 49, 19, 'Fürwahr, wie ein Löwe aus dem Dickicht des Jordans zu der immergrünen Aue hinaufsteigt, so will ich Edom im Nu von dort vertreiben, und wer dazu ausersehen ist, den werde ich zum Herrn dort einsetzen. Denn wer ist mir gleich, und wer will mich zur Rechenschaft ziehen? Und wo wäre ein Völkerhirt, der es mit mir aufnehmen könnte?« –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 49, 20, 'Darum vernehmt den Ratschluß, den der HERR über Edom gefaßt hat, und die Absichten, mit denen er sich gegen die Bewohner von Theman trägt: Fürwahr, die Hirtenbuben werden sie wegschleppen! Fürwahr, ihre eigene Trift wird sich über sie entsetzen!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 49, 21, 'Vom Gedröhn ihres Sturzes erbebt die Erde; ihr Wehgeschrei – am Schilfmeer wird sein Schall vernommen!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 49, 22, 'Seht, einem Adler gleich steigt (der Feind) herauf und fliegt daher und breitet seine Schwingen über Bozra aus; da wird den edomitischen Kriegern an jenem Tage zumute sein wie einem Weibe in Kindesnöten.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 49, 23, 'Über Damaskus: Enttäuscht sind Hamath und Arpad, denn eine schlimme Kunde haben sie vernommen; sie sind verzagt, in ängstlicher Erregung wie das Meer, das nicht zur Ruhe kommen kann.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 49, 24, 'Damaskus ist mutlos geworden, hat sich zur Flucht gewandt, und Zittern hat es ergriffen; Angst und Krämpfe haben es erfaßt wie ein Weib in Kindesnöten.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 49, 25, 'Wie ist sie doch so ganz verlassen, die ruhmreiche Stadt, die Burg meiner Wonne!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 49, 26, '»Darum werden ihre jungen Männer auf ihren Straßen fallen und alle kriegstüchtigen Männer an jenem Tage umkommen!« – so lautet der Ausspruch des HERRN der Heerscharen –;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 49, 27, '»und ich werde Feuer an die Mauern von Damaskus legen, das die Paläste Benhadads verzehren soll!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 49, 28, 'Über Kedar und über die Königreiche von Hazor, die Nebukadnezar, der König von Babylon, besiegte, hat der HERR so gesprochen: »Auf! Zieht gegen Kedar zu Felde und überwältigt die Söhne des Ostens!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 49, 29, 'Ihre Zelte und ihre Herden raube man ihnen, ihre Zeltbehänge und ihren gesamten Hausrat, auch ihre Kamele nehme man ihnen weg und rufe über sie aus: ›Grauen ringsum!‹');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 49, 30, 'Fliehet, macht euch eilends davon, verkriecht euch in tiefe Verstecke, ihr Bewohner von Hazor!« – so lautet der Ausspruch des HERRN –; »denn Nebukadnezar, der König von Babylon, hat es auf euch abgesehen und einen Anschlag gegen euch ersonnen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 49, 31, 'Auf! Zieht zu Felde gegen das sorglose Volk, das in Sicherheit lebt!« – so lautet der Ausspruch des HERRN –, »das weder Tore noch Riegel hat: für sich allein wohnen sie.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 49, 32, 'Ihre Kamele sollen zur Beute und ihre vielen Herden zum Raube werden; und ich will sie, die sich das Haupthaar an der Schläfe stutzen, in alle Winde zerstreuen und von allen Seiten her Verderben über sie hereinbrechen lassen!« – so lautet der Ausspruch des HERRN.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 49, 33, '»Da wird dann Hazor eine Behausung für Schakale werden, eine Einöde für ewige Zeiten; niemand wird mehr dort wohnen und kein Menschenkind sich darin aufhalten!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 49, 34, 'Das Wort, das über Elam an den Propheten Jeremia im Anfang der Regierung des judäischen Königs Zedekia erging, lautet folgendermaßen:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 49, 35, 'So hat der HERR der Heerscharen gesprochen: »Fürwahr, ich zerbreche den Bogen Elams, den Hauptteil seiner Kraft,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 49, 36, 'und lasse die vier Winde von den vier Enden des Himmels über die Elamiter hereinbrechen und zerstreue sie nach allen diesen Windrichtungen hin, so daß es kein Volk geben soll, zu dem nicht elamitische Flüchtlinge gelangen werden!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 49, 37, 'Und ich will den Elamitern bange Angst vor ihren Feinden einflößen und vor denen, die ihnen ans Leben wollen, und verhänge Unglück über sie, die Glut meines Zorns!« – so lautet der Ausspruch des HERRN –, »und ich lasse das Schwert hinter ihnen herfahren, bis ich sie ausgerottet habe!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 49, 38, 'Dann will ich meinen Richterstuhl in Elam aufstellen und den König samt den Fürsten daraus vertilgen!« – so lautet der Ausspruch des HERRN.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 49, 39, '»Doch am Ende der Tage will ich das Geschick Elams wieder wenden!« – so lautet der Ausspruch des HERRN.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 1, '(Dies ist) das Wort, das der HERR über Babylon, über das Land der Chaldäer, durch den Mund des Propheten Jeremia ausgesprochen hat:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 2, '»Verkündigt es unter den Völkern und macht es bekannt und pflanzt ein Banner auf! Macht es bekannt und verheimlicht es nicht! Verkündigt: ›Erobert ist Babylon, zuschanden geworden Bel! Merodach steht fassungslos da! Ihre Bilder sind zuschanden geworden, ihre Götzen stehen fassungslos da!‹');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 3, 'Denn es zieht gegen Babylon von Norden her ein Volk heran: das wird sein Land zur Wüste machen, so daß kein Bewohner mehr darin zu finden ist: sowohl Menschen als Vieh sind entflohen, haben sich davongemacht! –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 4, 'In jenen Tagen und zu jener Zeit« – so lautet der Ausspruch des HERRN – »werden die Kinder Israel heimkehren, sie im Verein mit den Kindern Juda; unter unaufhörlichem Weinen werden sie daherkommen und den HERRN, ihren Gott, suchen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 5, 'Zum Zion erfragen sie den Weg, dorthin sind ihre Blicke gerichtet: ›Kommt und schließt euch an den HERRN an zu einem ewigen, unvergeßlichen Bunde!‹');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 6, 'Mein Volk war wie eine verlorene Schafherde; ihre Hirten hatten sie auf Abwege geleitet, auf den Bergen sie in der Irre umhergeführt; von Berg zu Hügel mußten sie ziehen und hatten ihre Lagerstätte vergessen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 7, 'Jeder, der auf sie stieß, fraß sie, und ihre Widersacher sagten: ›Wir tun kein Unrecht damit!‹ – zur Strafe dafür, daß sie sich am HERRN versündigt hatten, der Trift der Gerechtigkeit und der Hoffnung ihrer Väter. –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 8, 'Flieht aus dem Bereiche Babylons und verlaßt das Land der Chaldäer! Werdet den Widdern an der Spitze der Herde gleich!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 9, 'Denn wisset wohl: ich will gegen Babylon ein großes Völkerheer aufbieten und aus dem Nordland heranziehen lassen; die sollen sich gegen die Stadt aufstellen: von dorther wird sie erobert werden. Ihre Pfeile sind wie die eines tüchtigen Kriegshelden, der nie mit leeren Händen heimkehrt.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 10, 'So wird denn das Chaldäerland ausgeraubt werden: alle, die es plündern, sollen satt werden!« – so lautet der Ausspruch des HERRN. –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 11, '»Ja, freut euch nur, ja, jubelt nur, ihr Räuber meines Erbbesitzes! Ja, hüpft nur lustig wie Rinder beim Dreschen und wiehert gleich den Hengsten!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 12, 'Dennoch wird eure Mutter ganz zuschanden werden und die euch geboren hat, beschämt dastehen; ja, das letzte unter den Völkern soll jetzt zur Wüste und zu einer dürren Steppe werden!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 13, 'Infolge des Zorns des HERRN wird es unbewohnt sein und ganz zur Wüste werden, so daß jeder, der an Babylon vorüberzieht, sich entsetzen und über alle seine Leiden zischen soll!« –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 14, 'Stellt euch ringsum zum Kampf gegen Babylon auf, ihr Bogenschützen alle! Schießt nach ihm, spart die Pfeile nicht! Denn am HERRN hat es sich versündigt.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 15, 'Erhebt ringsum ein Jubelgeschrei über es: »Es hat sich ergeben! Gefallen sind seine Festungswerke, niedergerissen seine Mauern!« Weil dies die Rache des HERRN ist, nun, so vollzieht die Rache an ihm! Verfahret mit ihm, wie es selbst verfahren ist!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 16, 'Rottet aus Babylon jeden Sämann aus und jeden, der die Sichel in der Erntezeit ergreift! Vor dem gewalttätigen Schwert werden sie sich ein jeder zu seinem Volke wenden und ein jeder in seine Heimat fliehen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 17, 'Israel ist wie ein verscheuchtes Schaf, das Löwen verjagt haben: zuerst hat der König von Assyrien es angefressen, und nun zuletzt hat Nebukadnezar, der König von Babylon, ihm die Knochen abgenagt.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 18, 'Darum hat der HERR der Heerscharen, der Gott Israels, so gesprochen: »Fürwahr, ich will den König von Babylon und sein Land strafen, wie ich den König von Assyrien gestraft habe.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 19, 'Alsdann will ich Israel zu seiner Trift heimkehren lassen, damit es wieder auf dem Karmel und in Basan weide und auf dem Gebirge Ephraim und in Gilead seinen Hunger stille.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 20, 'In jenen Tagen und zu jener Zeit« – so lautet der Ausspruch des HERRN – »wird man nach der Verschuldung Israels suchen, aber sie wird nicht mehr vorhanden sein, und nach den Sünden Judas, aber sie werden nicht mehr zu finden sein; denn ich habe denen vergeben, die ich als Rest übrig lasse.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 21, '»Zieh heran gegen das Land ›Doppeltrotz‹ und gegen die Bewohner von Pekod! Morde und vollziehe den Bann hinter ihnen her« – so lautet der Ausspruch des HERRN – »und führe alles so aus, wie ich dir geboten habe!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 22, 'Horch! Krieg ist im Lande und gewaltiger Einsturz!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 23, 'Wie ist doch zerschlagen und zertrümmert der Hammer, der die ganze Erde schlug! Wie ist doch Babylon zum Schreckbild unter den Völkern geworden!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 24, '»Ich habe dir Schlingen gelegt, Babylon, und du bist auch gefangen worden, ohne daß du dich dessen versahst: du bist ertappt und auch gefaßt, denn mit dem HERRN hast du dich in Kampf eingelassen.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 25, 'Der HERR hat seine Rüstkammer aufgetan und die Waffen seines Zornes daraus hervorgeholt; denn Arbeit gibt es zu tun für Gott, den HERRN der Heerscharen, im Chaldäerlande.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 26, 'Rückt von allen Seiten gegen das Land heran, öffnet seine Speicher! Schüttet alles in ihm zu Haufen auf wie Garben und vollzieht den Bann an ihm, daß kein Rest von ihm übrig bleibt!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 27, 'Stecht alle seine Rinder nieder, laßt sie zur Schlachtung niedersinken! Wehe ihnen, denn ihr Tag ist gekommen, die Stunde ihrer Bestrafung!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 28, 'Horch! Flüchtlinge und Entronnene aus dem Lande Babylon rufen, um in Zion die Rache des HERRN, unsers Gottes, zu verkünden, die Rache für seinen Tempel! –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 29, 'Bietet Schützen gegen Babylon auf, alle, die den Bogen spannen! Lagert euch rings um die Stadt, laßt ihr kein Entrinnen zuteil werden! Zahlt ihr ihre Böstaten nach Gebühr heim, verfahrt mit ihr ganz so, wie sie selbst verfahren ist! Denn gegen den HERRN, den Heiligen Israels, hat sie sich vermessen aufgelehnt.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 30, '»Darum sollen ihre jungen Männer auf ihren Straßen fallen und alle ihre kriegstüchtigen Leute umkommen an jenem Tage!« – so lautet der Ausspruch des HERRN.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 31, '»Siehe, ich will an dich, du Freche!« – so lautet der Ausspruch Gottes, des HERRN der Heerscharen –; »denn dein Tag ist gekommen, die Stunde, da ich dich strafe:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 32, 'da soll die Freche straucheln und zu Fall kommen, ohne daß jemand ihr aufhilft; und ich will Feuer an ihre Städte legen, das soll alles rings um sie her verzehren!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 33, 'So hat der HERR der Heerscharen gesprochen: »Wohl leiden die Söhne Israels und die Söhne Judas insgesamt Gewalt, und alle, die sie in Gefangenschaft geschleppt haben, halten sie fest und wollen sie nicht wieder freigeben;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 34, 'doch ihr Erlöser ist stark, ›HERR der Heerscharen‹ ist sein Name; er wird ihre Sache mit Nachdruck führen, damit er der Erde Ruhe schaffe, aber Unruhe den Bewohnern Babylons.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 35, '»Das Schwert komme über die Chaldäer« – so lautet der Ausspruch des HERRN –, »über die Bewohner Babylons, über seine Fürsten und über seine Gelehrten!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 36, 'Das Schwert über die Schwätzer, daß sie als Narren dastehen! Das Schwert über seine tapferen Krieger, daß sie zu Feiglingen werden!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 37, 'Das Schwert über seine Rosse und Kriegswagen und über das ganze Völkergemisch innerhalb seines Bereichs, daß sie zu Weibern werden! Das Schwert über seine Schätze, daß sie der Plünderung anheimfallen!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 38, 'Das Schwert über seine Gewässer, daß sie vertrocknen! Denn es ist ein Land der Götzenbilder, und durch die Abgötter haben sie den Verstand verloren.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 39, 'Darum sollen Wildkatzen im Verein mit Schakalen dort hausen und Strauße darin wohnen, und niemals soll es wieder besiedelt werden, sondern unbewohnt bleiben von Geschlecht zu Geschlecht!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 40, '»Wie Gott einst Sodom und Gomorrha und ihre Nachbarstädte von Grund aus zerstört hat« – so lautet der Ausspruch des HERRN –, »ebenso soll auch dort niemand mehr wohnen und kein Menschenkind sich darin aufhalten!« –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 41, 'Gebt acht! Es kommt ein Volk von Norden her, und eine gewaltige Völkerschaft und viele Könige setzen sich in Bewegung von den Enden der Erde her.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 42, 'Bogen und Wurfspieß führen sie, grausam sind sie und ohne Erbarmen; ihr Lärmen ist wie Meeresbrausen, und auf Rossen reiten sie: gerüstet wie ein Kriegsmann zum Kampfe gegen dich, Tochter Babylon!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 43, 'Wenn der König von Babylon die Kunde von ihnen erhält, sinken ihm die Arme schlaff herab; Angst erfaßt ihn, Krampf wie ein Weib in Kindesnöten.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 44, '»Fürwahr, wie ein Löwe aus dem Dickicht des Jordans zu der immergrünen Aue hinaufsteigt, so will ich sie im Nu von dort vertreiben, und wer dazu ausersehen ist, den werde ich zum Herrn dort einsetzen. Denn wer ist mir gleich, und wer darf mich zur Rechenschaft ziehen? Und wo wäre ein Völkerhirt, der es mit mir aufnehmen könnte?«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 45, 'Darum vernehmt den Ratschluß, den der HERR gegen Babylon gefaßt hat, und die Absichten, mit denen er sich gegen das Land der Chaldäer trägt: Fürwahr, die Hirtenbuben werden sie wegschleppen! fürwahr, ihre eigene Trift wird sich über sie entsetzen!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 46, 'Von dem Rufe: »Babylon ist erobert!« erbebt die Erde, und Geschrei vernimmt man unter den Völkern.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 1, 'So hat der HERR gesprochen: »Fürwahr, ich lasse gegen Babylon und gegen die, welche im ›Herzen meiner Widersacher‹ wohnen, die Wut eines Verderbers losbrechen,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 2, 'und ich entsende Worfler nach Babylon, die sollen es worfeln und sein Land ausplündern!« Wenn die am Tage des Unglücks (die Stadt) von allen Seiten umzingeln,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 3, 'dann spanne kein Schütze seinen Bogen mehr, und niemand erhebe sich zum Widerstand in seinem Panzer! Doch schont ihre jungen Männer nicht, vollzieht den Bann an ihrem gesamten Heer,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 4, 'so daß Erschlagene daliegen im Lande der Chaldäer und Durchbohrte auf ihren Straßen!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 5, 'Denn weder Israel noch Juda ist als Witwe von seinem Gott, vom HERRN der Heerscharen, verlassen; dagegen das Land jener ist voll von Verschuldung gegen den Heiligen Israels.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 6, 'Fliehet aus dem Bereich Babylons hinweg und rettet ein jeder sein Leben, damit ihr nicht den Tod findet um seiner Verschuldung willen! Denn die Zeit der Rache ist dies für den HERRN: was es verübt hat, vergilt er ihm.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 7, 'Ein goldener Becher war Babylon in der Hand des HERRN, der die ganze Erde trunken machte; von seinem Wein haben die Völker getrunken, darum haben die Völker den Verstand verloren.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 8, 'Plötzlich ist Babylon gefallen und zerschmettert: »Wehklagt über die Stadt, holt Balsam für ihre Schmerzen: vielleicht ist noch Heilung möglich!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 9, '»Wir haben Babylon heilen wollen, aber es war nicht zu heilen: überlaßt es sich selbst! Laßt uns abziehen, ein jeder in sein Land! Denn bis an den Himmel reicht das Strafgericht über die Stadt und ragt bis zu den Wolken!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 10, '»Der HERR hat die Gerechtigkeit unserer Sache ans Licht gebracht: kommt, laßt uns in Zion das Walten des HERRN, unsers Gottes, verkündigen!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 11, 'Schärft die Pfeile, ergreift die Schilde! Der HERR hat die Wut der Könige von Medien erweckt, denn sein Absehen ist gegen Babylon gerichtet, es zu vernichten; denn die Rache des HERRN ist da, die Rache für seinen Tempel.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 12, 'Gegen die Mauern Babylons pflanzt ein Banner auf! Verschärft die Bewachung, stellt Wachtposten auf, legt Mannschaften in Hinterhalt! Denn wie der HERR es sich vorgenommen hat, so führt er es auch aus, was er den Bewohnern Babylons angedroht hat.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 13, 'O Stadt, die du wohnst an großen Wassern, reich an Schätzen: gekommen ist dein Ende, das Maß ist voll zum Abschneiden!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 14, 'Der HERR der Heerscharen hat bei sich selbst geschworen: »Habe ich dich auch mit Menschen angefüllt wie mit Heuschrecken, so wird man doch Siegesgeschrei über dich erheben!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 15, 'Er ist es, der die Erde durch seine Kraft geschaffen, den Erdkreis durch seine Weisheit fest gegründet und durch seine Einsicht den Himmel ausgespannt hat.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 16, 'Wenn er beim Schall des Donners Wasserrauschen am Himmel entstehen läßt und Gewölk vom Ende der Erde heraufführt, wenn er Blitze beim Regen schafft und den Sturmwind aus seinen Vorratskammern herausläßt –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 17, 'starr steht alsdann jeder Mensch da, ohne es begreifen zu können, und schämen muß sich jeder Goldschmied seines Bildwerks; denn Trug ist sein gegossener Götze, und kein Odem wohnt in ihm:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 18, 'nichts als Wahn sind sie, lächerliche Gebilde; wenn die Zeit des Strafgerichts für sie kommt, ist es zu Ende mit ihnen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 19, 'Aber nicht wie diese ist Jakobs Erbteil; nein, er ist es, der das All gebildet hat, und Israel ist der Stamm seines Erbbesitzes: HERR der Heerscharen ist sein Name!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 20, '»Ein Hammer bist du mir gewesen, eine Kriegswaffe; und ich habe mit dir Völker zerhämmert und Königreiche mit dir zertrümmert.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 21, 'Zerhämmert habe ich mit dir Rosse samt ihren Reitern, zerhämmert mit dir Kriegswagen samt den darauf Fahrenden;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 22, 'zerhämmert habe ich mit dir Männer und Weiber, zerhämmert mit dir Greise und Kinder, zerhämmert Jünglinge und Jungfrauen;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 23, 'zerhämmert habe ich mit dir Hirten samt ihren Herden, zerhämmert mit dir Ackerleute samt ihren Gespannen, zerhämmert Landpfleger und Statthalter.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 24, 'Aber jetzt will ich Babylon und allen Bewohnern des Chaldäerlandes alle ihre Bosheit, die sie an Zion verübt haben, vor euren Augen vergelten!« – so lautet der Ausspruch des HERRN. –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 25, '»Nunmehr will ich an dich« – so lautet der Ausspruch des HERRN –, »du Berg des Verderbens, der du über die ganze Erde Verderben gebracht hast! Ja, ich will meine Hand gegen dich ausstrecken und dich von der Felsenhöhe hinabwälzen und dich zu einem verbrannten Berge machen,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 26, 'so daß man von dir weder Ecksteine noch Grundsteine mehr nehmen kann; nein, eine öde Wüste sollst du sein auf ewige Zeit!« – so lautet der Ausspruch des HERRN.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 27, 'Pflanzt ein Panier auf der Erde auf, stoßt in die Posaune unter den Völkern, weiht Völker zum Kampf gegen Babylon, bietet gegen es die Königreiche von Ararat, Minni und Askenas auf, bestellt einen Heerführer gegen es, laßt Reiterei anrücken so zahlreich wie borstige Heuschrecken!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 28, 'Weiht Völker zum Kampf gegen es, die Könige von Medien, ihre Landpfleger und alle ihre Statthalter und das ganze Gebiet ihrer Herrschaft!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 29, 'Da erbebt und zittert die Erde; denn die Ratschlüsse des HERRN gehen an Babylon in Erfüllung, um das Land Babylon zu einer menschenleeren Einöde zu machen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 30, 'Babylons Mannen ziehen nicht mehr ins Feld, sitzen tatenlos in den Burgen; ihr Mut ist geschwunden, sie sind zu Weibern geworden; schon hat man die Wohnungen in der Stadt in Flammen aufgehen lassen, ihre Riegel sind zerbrochen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 31, 'Ein Läufer läuft dem andern entgegen und ein Bote dem andern, um dem König von Babylon zu melden, daß seine Stadt an allen Ecken erobert,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 32, 'daß die Furten besetzt seien und man die Sümpfe mit Feuer ausgebrannt habe und dem Kriegsvolk der Mut entsunken sei.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 33, 'Denn so hat der HERR der Heerscharen, der Gott Israels, gesprochen: »Die Tochter Babylon gleicht einer Tenne zur Zeit, da man sie feststampft: nur noch eine kleine Weile, so kommt für sie (für Babylon) die Zeit der Ernte!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 34, '»Nebukadnezar, der König von Babylon, hat mich gefressen, hat mich vernichtet, mich hingestellt als ein leeres Gefäß! Er hat mich verschlungen wie ein Drache und seinen Bauch mit mir gefüllt, hat mich aus meinem Paradies hinausgestoßen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 35, 'Die an mir verübte Gewalttätigkeit und meine Zerfleischung komme über Babylon« – so spreche die Bewohnerschaft Zions – »und mein Blut über die Bewohner des Chaldäerlandes!« – so spreche Jerusalem.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 36, 'Darum hat der HERR so gesprochen: »Wisse wohl: ich führe deine Sache und vollziehe die Rache für dich: ich trockne Babylons Strom aus und lasse seine Brunnen versiegen!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 37, 'Babylon soll zum Trümmerhaufen werden, zur Behausung der Schakale, zum abschreckenden Beispiel und Gespött, ohne Bewohner!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 38, 'Jetzt brüllen sie noch allesamt wie junge Löwen, knurren wie Löwenkätzchen;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 39, 'aber wenn sie (vor Gier) glühen, will ich ihnen ein Mahl herrichten und sie trunken machen, daß sie taumeln und einschlafen zu ewigem Schlaf, aus dem sie nicht wieder erwachen!« – so lautet der Ausspruch des HERRN.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 40, '»Ich lasse sie wie Lämmer zur Schlachtung niedersinken, wie Widder samt den Böcken!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 41, 'Ach, wie ist doch Sesach eingenommen und erobert der Stolz der ganzen Erde! Ach, wie ist doch Babylon zum Gegenstand des Entsetzens unter den Völkern geworden!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 42, 'Das Meer ist gegen Babylon heraufgestiegen, von seinen brausenden Wellen ist es überflutet;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 43, 'seine Städte sind zur Wüste geworden, zu dürrem Land und zur Steppe, zu einem Land, in welchem niemand wohnt und das kein Menschenkind durchwandert.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 44, 'Auch am Bel zu Babylon will ich das Strafgericht vollziehen und aus seinem Rachen das wieder herausholen, was er verschlungen hat, und nicht mehr sollen künftig die Völker zu ihm hinströmen! Auch die Mauer Babylons ist gefallen!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 45, 'Ziehet aus seinem Bereich hinweg, mein Volk, und rettet ein jeder sein Leben vor der Zornglut des HERRN!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 46, 'Doch laßt euer Herz nicht verzagen und geratet nicht in Angst bei den Gerüchten, die im Lande im Umlauf sind, wenn in dem einen Jahre dieses Gerücht sich verbreitet und im Jahre darauf jenes Gerücht, und Gewalttätigkeit im Lande herrscht, und ein Machthaber sich gegen den andern erhebt!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 47, '»Darum wisset wohl: es kommt die Zeit, da werde ich das Strafgericht an den Götzenbildern Babylons vollziehen! Da wird dann sein ganzes Land zuschanden werden und alle seine (Bewohner) erschlagen in seiner Mitte fallen!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 48, 'Dann werden Himmel und Erde samt allem, was in ihnen ist, über Babylon jubeln, denn von Norden her brechen ihm die Verwüster ins Land ein« – so lautet der Ausspruch des HERRN.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 49, 'Auch Babylon muß fallen um der erschlagenen Israeliten willen, wie um Babylons willen Erschlagene auf der ganzen Erde gefallen sind.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 50, 'Ihr, die ihr dem Schwert entronnen seid, ziehet ab und steht nicht still! Bleibt des HERRN auch in der Ferne eingedenk und haltet die Erinnerung an Jerusalem getreulich fest:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 51, '»Wir haben uns schämen müssen, denn wir haben Schmähreden zu hören bekommen; Schamröte hat unser Antlitz bedeckt, denn Fremde sind über die Heiligtümer im Tempel des HERRN hergefallen!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 52, '»Darum wisset wohl: es kommt die Zeit« – so lautet der Ausspruch des HERRN –, »da werde ich das Strafgericht an den Götzen Babylons vollziehen, und überall in seinem Lande werden dann tödlich Verwundete röcheln!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 53, 'Wenn Babylon auch bis zum Himmel emporstiege und seine Festung unersteiglich hoch baute, so werden ihm doch von mir her die Verwüster kommen!« – so lautet der Ausspruch des HERRN.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 54, 'Horch! Geschrei von Babylon her und ein gewaltiger Einsturz aus dem Lande der Chaldäer!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 55, 'Denn der HERR verwüstet Babylon und macht dem lauten Lärmen dort ein Ende: es brausen ihre Wogen wie gewaltige Fluten, laut erschallen ihre wilden Kriegsrufe.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 56, 'Denn der Verwüster bricht über die Stadt, über Babylon herein, und ihre Krieger werden gefangen, ihre Bogen sind zerbrochen; denn ein Gott der Vergeltung ist der HERR, er zahlt sicher heim.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 57, '»Ihre Oberen aber und Gelehrten, ihre Landpfleger, Statthalter und Krieger mache ich trunken, daß sie entschlafen zu ewigem Schlaf und nicht wieder erwachen« – so lautet der Ausspruch des Königs, dessen Name ›HERR der Heerscharen‹ ist. –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 58, 'So hat der HERR der Heerscharen gesprochen: »Babylons Mauern, so breit sie sind, sollen bis auf den Grund niedergerissen und seine Tore, so hoch sie sind, mit Feuer verbrannt werden!«, und so: »Völker mühen sich für nichts ab, und Völkerschaften arbeiten sich für das Feuer ab.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 59, '(Dies ist) der Auftrag, den der Prophet Jeremia Seraja, dem Sohne Nerijas, des Sohnes Mahsejas, erteilte, als dieser mit Zedekia, dem König von Juda, im vierten Jahre von dessen Regierung nach Babylon reiste; Seraja war damals Quartiermeister.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 60, 'Jeremia hatte aber alles Unglück, das über Babylon hereinbrechen sollte, nämlich alle Aussprüche, die hier über Babylon aufgezeichnet stehen, auf eine einzige Buchrolle geschrieben');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 61, 'und zu Seraja gesagt: »Wenn du nach Babylon kommst, so sieh dich nach einem passenden Orte um und verlies alle diese Worte laut');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 62, 'und sage dann: ›HERR, du selbst hast diesem Orte angedroht, ihn vernichten zu wollen, so daß kein Bewohner mehr in ihm sein solle, weder Menschen noch Vieh, sondern daß er zu einer Einöde für ewige Zeiten werden solle.‹');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 63, 'Wenn du dann diese Buchrolle zu Ende gelesen hast, so binde einen Stein daran und wirf sie mitten in den Euphrat hinein');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 64, 'und rufe aus: ›So soll auch Babylon versinken und nicht wieder hochkommen infolge des Unglücks, das ich über es verhänge!‹« Bis hierher gehen die Aussprüche Jeremias.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 52, 1, 'Im Alter von einundzwanzig Jahren kam Zedekia auf den Thron und regierte elf Jahre in Jerusalem; seine Mutter hieß Hamutal und war die Tochter Jeremias, aus Libna.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 52, 2, 'Er tat, was dem HERRN mißfiel, ganz wie Jojakim getan hatte.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 52, 3, 'Denn infolge des Zornes des HERRN kam es mit Jerusalem und Juda dahin, daß der HERR sie von seinem Angesicht verstieß. Als Zedekia aber vom König von Babylon abgefallen war,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 52, 4, 'da – es war im neunten Jahre seiner Regierung, am zehnten Tage des zehnten Monats – kam Nebukadnezar, der König von Babylon, in eigener Person mit seiner ganzen Heeresmacht gegen Jerusalem herangezogen, und man eröffnete die Belagerung der Stadt und führte rings um sie Belagerungswerke auf;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 52, 5, 'und die Stadt blieb dann eingeschlossen bis ins elfte Regierungsjahr Zedekias.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 52, 6, 'Am neunten Tage des vierten Monats, als die Hungersnot in der Stadt übermächtig geworden war und auch die Landbevölkerung kein Brot mehr hatte,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 52, 7, 'da wurde die Stadtmauer durchbrochen, und alle Kriegsleute ergriffen die Flucht und verließen die Stadt nachts auf dem Wege durch das Tor zwischen den beiden Mauern, das am Königsgarten lag, während die Chaldäer noch rings um die Stadt her lagen, und sie wandten sich dann der Jordan-Ebene zu.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 52, 8, 'Aber das Heer der Chaldäer setzte dem Könige nach und holte Zedekia in den Steppen von Jericho ein, nachdem sein ganzes Heer sich zerstreut und ihn verlassen hatte.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 52, 9, 'So wurde denn der König gefangengenommen und zum König von Babylon nach Ribla in der Landschaft Hamath hinaufgeführt; der hielt dann Gericht über ihn.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 52, 10, 'Der König von Babylon ließ die Söhne Zedekias vor dessen Augen schlachten, ebenso auch alle Fürsten von Juda in Ribla.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 52, 11, 'Zedekia aber ließ er blenden und in zwei Ketten legen und ihn dann nach Babylon bringen, wo er ihn bis zu seinem Todestage gefangenhielt.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 52, 12, 'Am zehnten Tage des fünften Monats aber – das war das neunzehnte Regierungsjahr Nebukadnezars, des Königs von Babylon – zog Nebusaradan, der Befehlshaber der Leibwache, der zur persönlichen Umgebung des Königs von Babylon gehörte, in Jerusalem ein');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 52, 13, 'und verbrannte den Tempel des HERRN sowie den königlichen Palast und alle anderen Häuser in Jerusalem: alle größeren Häuser ließ er in Flammen aufgehen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 52, 14, 'Sodann mußte das ganze chaldäische Heer, welches der Befehlshaber der Leibwache bei sich hatte, alle Mauern rings um Jerusalem niederreißen;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 52, 15, 'hierauf ließ Nebusaradan, der Befehlshaber der Leibwache, [einen Teil des niederen Volkes und] den Rest des Volkes, was an Einwohnern in der Stadt noch übriggeblieben war, ebenso die Überläufer, die zum König von Babylon übergegangen waren, [sowie den Rest der Werkleute] in die Verbannung nach Babylon führen;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 52, 16, 'von der niederen Bevölkerung des Landes aber ließ Nebusaradan, der Befehlshaber der Leibwache, einen Teil als Weingärtner und Ackerleute zurück.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 52, 17, 'Aber die ehernen Säulen, die am Tempel des HERRN standen, sowie die Gestühle und das große eherne Wasserbecken, die beim Tempel des HERRN waren, zerschlugen die Chaldäer und nahmen alles Erz davon mit sich nach Babylon.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 52, 18, 'Auch die Töpfe, Schaufeln, Messer zum Lichtputzen, Schöpfkellen, Schüsseln, überhaupt alle ehernen Geräte, die man beim Gottesdienst gebraucht hatte, nahmen sie weg;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 52, 19, 'auch die Becken, Kohlenpfannen, Sprengschalen, Töpfe, Leuchter, Schüsseln und Becher, alles, was ganz aus Gold oder ganz aus Silber bestand, nahm der Befehlshaber der Leibwache weg.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 52, 20, 'Was die beiden Säulen sowie das eine große Wasserbecken und die zwölf ehernen Rinder, die sich unter ihm befanden, und die Gestühle betrifft, die der König Salomo einst für den Tempel des HERRN hatte anfertigen lassen, so war es unmöglich, das Erz aller dieser Kunstwerke zu wägen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 52, 21, 'Was aber die Säulen betrifft, so war die eine Säule achtzehn Ellen hoch, und ein Faden von zwölf Ellen umspannte sie; ihre Dicke betrug vier Finger, inwendig war sie hohl.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 52, 22, 'Oben auf ihr befand sich ein eherner Knauf, dessen Höhe bei der einen Säule fünf Ellen betrug; und ein Flechtwerk und Granatäpfel waren ringsum an dem Knauf angebracht, alles von Erz; ebenso war auch die andere Säule beschaffen. Was aber die Granatäpfel betrifft,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 52, 23, 'so waren sechsundneunzig Granatäpfel da, die frei in der Luft hingen; die Zahl sämtlicher Granatäpfel an dem Flechtwerk ringsum betrug hundert.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 52, 24, 'Weiter ließ der Befehlshaber der Leibwache den Oberpriester Seraja, den Unterpriester Zephanja und die drei Schwellenhüter verhaften;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 52, 25, 'ferner nahm er aus der Stadt den einen Kämmerer fest, der den Oberbefehl über das Kriegsvolk gehabt hatte, sowie sieben Männer von denen, die zu der ständigen Umgebung des Königs gehört hatten und die in der Stadt vorgefunden waren, außerdem den Schreiber des Feldhauptmanns, der das Landvolk zum Heeresdienst ausgehoben hatte, außerdem sechzig Personen aus der Landbevölkerung, die noch in der Stadt angetroffen waren.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 52, 26, 'Diese also nahm Nebusaradan, der Befehlshaber der Leibwache, und brachte sie zum König von Babylon nach Ribla;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 52, 27, 'der König von Babylon ließ sie dann zu Ribla in der Landschaft Hamath grausam hinrichten. So wurde Juda von seinem heimischen Boden in die Gefangenschaft weggeführt.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 52, 28, 'Dies ist die Zahl der Personen, die Nebukadnezar in die Gefangenschaft hat wegführen lassen: im siebten Jahre seiner Regierung 3023 Judäer;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 52, 29, 'im achtzehnten Regierungsjahr Nebukadnezars 832 Personen aus Jerusalem;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 52, 30, 'im dreiundzwanzigsten Regierungsjahr Nebukadnezars führte Nebusaradan, der Befehlshaber der Leibwache, von den Judäern 745 Personen weg: im ganzen waren es 4600 Personen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 52, 31, 'Aber im siebenunddreißigsten Jahre nach der Wegführung Jojachins, des Königs von Juda, am fünfundzwanzigsten Tage des zwölften Monats, begnadigte Ewil-Merodach, der König von Babylon – im Jahre seines Regierungsantritts – den König Jojachin von Juda und entließ ihn aus dem Kerker.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 52, 32, 'Er redete freundlich mit ihm und wies ihm seinen Sitz an über den Sitzen der anderen Könige, die mit ihm in Babylon waren.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 52, 33, 'Er durfte nun auch seine Gefangenenkleidung ablegen und speiste regelmäßig an der königlichen Tafel, solange er noch lebte.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 52, 34, 'Sein Unterhalt wurde ihm als ständiger Unterhalt, soviel er täglich bedurfte, von seiten des Königs von Babylon bis zu seinem Todestage gewährt, solange er noch lebte.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 1, 1, 'Ach, wie liegt sie doch (jetzt) so einsam da, die (einst) volkreiche Stadt! Wie zu einer Witwe ist sie geworden, sie, die (vordem) groß war unter den Völkern: die Fürstin unter den Städten muß nun Frondienste leisten!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 1, 2, 'Bitterlich weint sie nachts, tränenbenetzt sind ihre Wangen; keiner ist da, sie zu trösten, von all ihren (früheren) Liebhabern: all ihre Freunde haben ihr die Treue gebrochen, sind ihr zu Feinden geworden!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 1, 3, 'In die Gefangenschaft ist Juda gewandert vor Elend und hartem Knechtsdienst; es weilt unter den Heiden, ohne Ruhe zu finden; alle seine Verfolger haben es in seiner Bedrängnis erhascht!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 1, 4, 'Die Straßen nach Zion trauern, weil niemand mehr zu den Festen kommt; alle Tore der Stadt sind verwüstet, ihre Priester seufzen; ihre Jungfraun sind tief betrübt, und sie selbst – ach, ihr ist bitter wehe!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 1, 5, 'Ihre Bedränger sind obenauf gekommen, ihre Feinde wohlgemut, denn der HERR hat sie in Trauer versetzt ob ihren vielen Sünden; ihre Kinder haben in die Gefangenschaft wandern müssen vor dem Bedränger her.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 1, 6, 'Geschwunden ist aus der Tochter Zion all ihre Herrlichkeit; ihre Fürsten sind den Hirschen gleich geworden, die keine Weide finden: kraftlos sind sie dahingezogen vor dem Treiber her.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 1, 7, 'Jerusalem denkt jetzt in den Tagen seines Elends und seiner Vereinsamung an all das Herrliche zurück, das es seit den Tagen der Vorzeit genossen hat: wie jetzt sein Volk in Feindeshand gefallen und niemand ihm zu Hilfe gekommen ist, während die Bedränger dabei zusahen und über seinen Untergang hohnlachten.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 1, 8, 'Jerusalem hat schwer gesündigt und ist darum zum Abscheu geworden: alle, welche die Stadt einst ehrten, verachten sie jetzt, weil sie ihre Blöße geschaut haben; auch sie selbst seufzt und wendet sich ab.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 1, 9, 'Ihre Schleppe ist schmählich besudelt, sie hatte ihr Ende nicht bedacht; darum ist sie so tief gesunken: sie hat keinen Tröster! »Ach, HERR, sieh mein Elend an, denn der Feind frohlockt!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 1, 10, 'Der Feind hat seine Hand ausgestreckt nach allen ihren Kostbarkeiten: ja, Heiden hat sie in ihr Heiligtum eindringen sehen, denen du doch den Zutritt zu deiner Gemeinde versagt hast!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 1, 11, 'Ihre gesamte Bewohnerschaft seufzt auf der Suche nach Brot; ihre Kostbarkeiten geben sie für Lebensmittel hin, um nur den Hunger zu stillen. »Ach, HERR, blicke her und sieh darein, wie verachtet ich bin!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 1, 12, 'Rührt es euch nicht, ihr alle, die ihr des Weges vorüberzieht? Blicket her und seht, ob einen Schmerz es gibt wie den Schmerz, der mich getroffen, mich, die der HERR heimgesucht hat am Tage seines lodernden Zorns!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 1, 13, 'Aus der Höhe hat er Feuer geschleudert in meine Gebeine, wo es vernichtend wütet; meinen Füßen hat er ein Netz gestellt und mich zu Fall gebracht, hat mich einsam gemacht, siech immerdar!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 1, 14, 'Fest geknüpft durch seine Hand ist das Joch meiner Übertretungen; ineinander verschlungen sind sie mir auf den Nacken gelegt: er hat meine Kraft gebrochen; der Herr hat mich in die Hände derer fallen lassen, gegen die ich nicht aufkommen konnte.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 1, 15, 'Der Herr hat alle meine tapferen Krieger in meiner Mitte weggerafft; er hat ein Opferfest gegen mich ausgerufen, um meine junge Mannschaft zu zerschmettern: der Herr hat der jungfräulichen Tochter Juda die Kelter getreten.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 1, 16, 'Darüber muß ich weinen, mein Auge zerfließt in Tränen; denn fern von mir ist ein Tröster, der mein Herz ermutigen könnte; meine Kinder sind vernichtet, denn der Feind ist übermächtig.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 1, 17, '(Die Tochter) Zion streckt ihre Hände aus, aber niemand ist da, sie zu trösten; der HERR hat gegen Jakob seine Nachbarn ringsum als Widersacher entboten: Jerusalem ist zum Abscheu unter ihnen geworden!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 1, 18, 'Der HERR ist gerecht, denn seinen Geboten habe ich widerstrebt! Hört es doch, ihr Völker alle, und seht meinen Schmerz: meine Jungfraun und meine Jünglinge sind in die Gefangenschaft gezogen!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 1, 19, 'Ich habe meine Liebhaber angerufen, doch sie haben mich betrogen; meine Priester und meine Ältesten sind in der Stadt verschmachtet, als sie sich Nahrung suchten, um ihren Hunger zu stillen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 1, 20, 'Ach, HERR, sieh, wie mir so angst ist! Mein Inneres glüht; das Herz kehrt sich mir in der Brust um, weil ich so ungehorsam gewesen! Draußen beraubt mich das Schwert meiner Kinder, drinnen ist’s wie der Tod!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 1, 21, 'Sie haben gehört, wie ich seufzte: »Ich habe keinen Tröster!« Alle meine Feinde haben von meinem Unglück gehört, haben sich gefreut, daß du selbst es getan, daß du den angedrohten Tag herbeigeführt hast – möge es ihnen ebenso ergehen wie mir!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 1, 22, 'Laß all ihre Bosheit dir vor Augen treten und tu ihnen, wie du mir getan hast wegen all meiner Verfehlungen! Ach, zahlreich sind meine Seufzer, und mein Herz ist krank!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 2, 1, 'Ach, wie hat doch der Herr in seinem Zorn die Tochter Zion umwölkt! Vom Himmel her hat er die Herrlichkeit Israels in den Staub geschleudert und des Schemels seiner Füße nicht gedacht am Tage seines Zorns!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 2, 2, 'Schonungslos hat der Herr verwüstet alle Fluren Jakobs, hat in seinem Grimm niedergerissen die Burgen der Tochter Juda, hat in den Staub geworfen und entweiht ihr Königtum und ihre Fürsten!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 2, 3, 'In Zornesglut hat er zerschlagen Israels ganze Kraft, hat seine Rechte vor dem Feinde zurückgezogen und Jakob in Brand gesetzt wie Feuerflammen, die ringsum alles verzehren.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 2, 4, 'Seinen Bogen hat er gespannt wie ein Feind, hat mit seiner Rechten Stellung genommen wie ein Gegner und alles, was das Auge erfreute, vertilgt im Zelt der Tochter Zion: ausgegossen hat er seinen Grimm wie Feuer.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 2, 5, 'Der Herr hat sich uns als Feind erwiesen, hat Israel vernichtet, vernichtet alle seine Paläste, zerstört seine Burgen und bei der Tochter Juda aufgehäuft Seufzen und Geseufze.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 2, 6, 'Er hat seinen Tempelplatz zerwühlt wie einen Garten, den Ort seiner Festversammlungen verwüstet. Der HERR hat in Zion Festfeiern und Sabbate in Vergessenheit gebracht und in seinem Zorneseifer verworfen den König und den Priester.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 2, 7, 'Verschmäht hat der Herr seinen Altar, sein Heiligtum verworfen, hat dahingegeben in Feindeshand die Mauern ihrer Paläste; sie haben im Hause des HERRN ein Geschrei erhoben wie an einem Festtage.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 2, 8, 'Der HERR hatte beschlossen, die Mauer der Tochter Zion zu zerstören: er hat die Meßschnur über sie gezogen, seine Hand vom Verderben nicht zurückgehalten und in Trauer versetzt Wall und Mauer: kläglich liegen sie zusammen da!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 2, 9, 'Zu Boden sind ihre Tore gesunken, ihre Riegel hat er zerbrochen und zerschlagen; ihr König und ihre Fürsten weilen jetzt unter den Heidenvölkern, die Rechtspflege ist dahin; auch ihre Propheten empfangen keine Offenbarung mehr vom HERRN.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 2, 10, 'Schweigend sitzen am Boden die Ältesten der Tochter Zion, haben Staub auf ihr Haupt gestreut, sich mit Sacktuch umgürtet; zu Boden haben ihr Haupt gesenkt die Jungfraun Jerusalems.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 2, 11, 'Ich habe mir die Augen ausgeweint, mein Inneres wallt, das Herz ist mir gebrochen über den Untergang der Tochter meines Volkes, weil Kinder und Säuglinge verschmachten auf den Straßen der Stadt.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 2, 12, 'Ihren Müttern rufen sie zu: »Wo ist Brot [und Wein]?« (und keins ist da:) Wie tödlich Verwundete verschmachten sie auf den Straßen der Stadt, während sie ihr Leben aushauchen an ihrer Mütter Brust.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 2, 13, 'Was soll ich dir zur Ermutigung vorhalten, womit dich vergleichen, Tochter Jerusalem? Was soll ich dir gleichstellen, um dich zu trösten, jungfräuliche Tochter Zion? Ach, groß wie das Meer ist dein Trümmerfeld: wer könnte dich heilen?');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 2, 14, 'Deine Propheten haben dir Lüge und Trug geweissagt; deine Schuld haben sie nicht aufgedeckt, um dadurch dein Geschick zu wenden, sondern haben dir Sprüche geweissagt, die dich täuschten und ins Unglück brachten.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 2, 15, 'Es schlagen über dich die Hände zusammen alle, die des Weges vorüberziehen; sie zischen und schütteln den Kopf über die Tochter Jerusalem: »Ist das die Stadt, die man nannte die Krone der Schönheit, die Wonne der ganzen Welt?«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 2, 16, 'Über dich reißen alle deine Feinde den Mund weit auf; sie zischen und knirschen mit den Zähnen, sie rufen aus: »Wir haben sie verschlungen! Ja, dies ist der Tag, den wir erhofften: wir haben ihn erreicht, erlebt!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 2, 17, 'Der HERR hat seinen Ratschluß ausgeführt, seine Drohung erfüllt, die er seit den Tagen der Vorzeit ausgesprochen hat: er hat niedergerissen ohne Erbarmen, hat den Feind über dich frohlocken lassen, den stolzen Sinn deiner Bedränger noch stolzer gemacht.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 2, 18, 'Schreie laut zum Herrn, du jungfräuliche Tochter Zion! Laß deine Tränen wie einen Bach rinnen bei Tag und bei Nacht! Gönne dir keine Ruhe, laß deinen Augenstern nicht rasten!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 2, 19, 'Auf, klage laut die Nacht hindurch beim Beginn jeder Nachtwache! Gieße dein Herz aus wie Wasser vor dem Angesicht des Herrn! Hebe deine Hände zu ihm empor für das Leben deiner Kindlein, die vor Hunger verschmachten an allen Straßenecken!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 2, 20, 'O HERR, schaue her und sieh darein: wem hast du je Gleiches getan? Dürfen Frauen ihre Leibesfrucht verzehren, die liebevoll gepflegten Kindlein? Dürfen im Heiligtum des Herrn gemordet werden Priester und Propheten?');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 2, 21, 'Am Boden hingestreckt liegen auf den Straßen Kinder und Greise; meine Jungfrauen und Jünglinge sind durchs Schwert gefallen: du hast sie am Tage deines Zornes niedermetzeln und ohne Erbarmen abschlachten lassen!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 2, 22, 'Wie zu einem Festtag hast du die Insassen meiner Dörfer ringsum herbeigerufen, und es hat am Zornestage des HERRN keinen Entronnenen und Geretteten gegeben: alle, die ich liebevoll gepflegt und großgezogen, die hat mein Feind vernichtet!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 1, 'Ich bin der Mann, der Elend erlebt hat durch die Rute seines Zornes;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 2, 'mich hat er geführt und getrieben in Finsternis und tiefes Dunkel;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 3, 'nur gegen mich kehrt er immer wieder seine Hand Tag für Tag!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 4, 'Mein Fleisch und meine Haut hat er hinschwinden lassen, meine Glieder zerschlagen;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 5, 'aufgetürmt hat er rings um mich Gift und Mühsal;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 6, 'in Finsternis hat er mich versenkt wie die ewig Toten.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 7, 'Er hat mich ummauert, daß ich keinen Ausweg habe, mich mit schweren Ketten beladen;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 8, 'ob ich auch schreie und rufe: er verschließt sich meinem Flehen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 9, 'Er hat meine Wege mit Quadersteinen vermauert, meine Pfade ungangbar gemacht.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 10, 'Ein lauernder Bär ist er mir gewesen, ein Löwe im Versteck.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 11, 'Er hat mich auf Irrwegen wandeln lassen und mich zerfleischt, mich verstört;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 12, 'er hat seinen Bogen gespannt und mich als Zielscheibe hingestellt für seine Pfeile,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 13, 'hat die Söhne seines Köchers mir ins Herz dringen lassen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 14, 'Meinem ganzen Volk bin ich zum Hohn geworden, ihr Spottlied den ganzen Tag;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 15, 'mit Bitternissen hat er mich gesättigt, mit Wermut mich getränkt.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 16, 'Meine Zähne hat er mich an Kieseln zerbeißen lassen, mich in den Staub niedergetreten.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 17, 'Du hast meiner Seele den Frieden entrissen, so daß ich verlernt habe, glücklich zu sein,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 18, 'und ausrufe: »Dahin ist meine Lebenskraft und verloren meine Hoffnung auf den HERRN!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 19, 'Gedenke meines Elends und meiner Irrsale, des Wermuts und des Gifts!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 20, 'Ohne Unterlaß denkt meine Seele daran und ist gebeugt in mir.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 21, 'Dies will ich mir zu Herzen nehmen und darum der Hoffnung leben:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 22, 'Die Gnadenerweisungen des HERRN sind noch nicht erschöpft, sein Erbarmen ist noch nicht zu Ende;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 23, 'alle Morgen sind sie neu, groß ist deine Treue.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 24, '»Der HERR ist mein Teil!« bekennt meine Seele; drum will ich auf ihn hoffen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 25, 'Gütig ist der HERR gegen die, welche auf ihn harren, gegen ein Herz, das ihn sucht.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 26, 'Gut ist es, geduldig zu sein und schweigend zu warten auf die Hilfe des HERRN.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 27, 'Gut ist es für jeden, das Joch schon in seiner Jugend tragen zu lernen;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 28, 'er sitze einsam und schweige, wenn der HERR es ihm auferlegt!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 29, 'Er neige seinen Mund in den Staub hinab: vielleicht ist noch Hoffnung vorhanden;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 30, 'er biete ihm, wenn er ihn schlägt, die Wange dar, lasse sich mit Schmach sättigen!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 31, 'Denn nicht auf ewig verstößt der HERR,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 32, 'sondern, wenn er Trübsal verhängt hat, erbarmt er sich auch wieder nach seiner großen Güte;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 33, 'denn nicht aus Lust plagt und betrübt er die Menschenkinder.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 34, 'Wenn man mit Füßen niedertritt alle Gefangenen der Erde,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 35, 'wenn man das Recht eines Mannes beugt vor den Augen des Höchsten,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 36, 'wenn man einen Menschen in seinem Rechtsstreit ins Unrecht setzt: sollte das der Herr nicht beachten?');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 37, 'Wer kann denn befehlen, daß etwas geschehe, ohne daß der Herr es geboten hat?');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 38, 'Geht nicht aus dem Munde des Höchsten das Glück wie das Unglück hervor?');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 39, 'Was klagt (also) der Mensch, solange er lebt? Ein jeder klage über seine Sünden!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 40, 'Laßt uns unsern Wandel prüfen und erforschen und zum HERRN umkehren!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 41, 'Laßt uns unser Herz mitsamt den Händen erheben zu Gott im Himmel!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 42, 'Wir sind es, die abtrünnig und ungehorsam gewesen sind; du aber hast nicht verziehen,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 43, 'hast dich in Zorn gehüllt und uns verfolgt, hingerafft ohne Schonung;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 44, 'du hast dich in Gewölk gehüllt, so daß kein Gebet hindurchdringen konnte;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 45, 'zu Kehricht und zum Abscheu hast du uns gemacht inmitten der Völker.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 46, 'Es haben den Mund gegen uns aufgerissen all unsere Feinde;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 47, 'Grauen und Grube sind uns zuteil geworden, Verwüstung und Untergang!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 48, 'Wasserbäche läßt mein Auge rinnen über die Zertrümmerung der Tochter meines Volkes.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 49, 'Mein Auge ergießt sich ruhelos in Tränen ohne Aufhören,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 50, 'bis der HERR vom Himmel herniederschaue und dareinsehe.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 51, 'Was ich sehen muß, versetzt mich in Trauer um aller Töchter meiner Stadt willen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 52, 'Ach! Wie einen Vogel haben die mich gejagt, die mir ohne Ursache feind sind;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 53, 'sie haben mich in die Grube gestoßen, um mein Leben zu vernichten, und haben Steine auf mich geworfen:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 54, 'die Wasser schlugen mir über dem Haupt zusammen; ich dachte: »Mit mir ist’s aus!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 55, 'Da rief ich deinen Namen an, HERR, tief unten aus der Grube,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 56, 'und du hast mich gehört, als ich zu dir flehte: »Verschließ dein Ohr nicht meinem Hilferuf!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 57, 'Du hast dich mir genaht, als ich dich anrief, hast mir zugerufen: »Fürchte dich nicht!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 58, 'Du, o HERR, hast meine Sache geführt, hast mein Leben gerettet;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 59, 'du, o HERR, hast meine Unbill gesehen: verhilf mir zu meinem Recht!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 60, 'Du hast all ihre Rachgier gesehen, all ihre Anschläge gegen mich,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 61, 'hast, o HERR, ihr Schmähen gehört, all ihre Anschläge gegen mich,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 62, 'das Gerede meiner Widersacher und ihre täglichen Ränke gegen mich.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 63, 'Gib acht auf ihr Sitzen und ihr Aufstehen: ihr Spottlied bin ich!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 64, 'Du wirst ihnen vergelten, HERR, wie ihre Taten es verdienen,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 65, 'wirst ihnen Verblendung ins Herz geben: dein Fluch komme über sie!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 66, 'Du wirst sie im Zorn verfolgen und sie vertilgen unter Gottes Himmel hinweg!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 4, 1, 'Ach, wie ist doch das Gold so glanzlos geworden, wertlos das Edelmetall! Hingeschüttet liegen die Edelsteine an allen Straßenecken!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 4, 2, 'Zions Söhne, die hochgeschätzten, die sonst mit gediegenem Gold aufgewogen wurden, o wie sind sie jetzt irdenem Geschirr gleichgeachtet, dem Machwerk von Töpfers Hand!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 4, 3, 'Selbst Schakale reichen die Brust dar, säugen ihre Jungen; doch die Töchter meines Volkes sind gefühllos geworden wie die Strauße in der Wüste.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 4, 4, 'Den Säuglingen klebt die Zunge am Gaumen vor Durst, die Kindlein flehen um Brot, aber niemand bricht es ihnen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 4, 5, 'Die sonst Leckerbissen aßen, verhungern auf den Straßen; die sich auf Purpurkissen hegen ließen, betten sich jetzt auf Düngerhaufen;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 4, 6, 'denn die Schuld der Tochter meines Volkes war größer geworden als die Sünde Sodoms, das in einem Augenblick zerstört wurde, ohne daß Menschenhände dabei mitwirkten.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 4, 7, 'Ihre Fürsten erglänzten reiner als Schnee, weißer als Milch; röter war ihr Leib als Korallen, wie Saphir ihre Gestalt geworden.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 4, 8, 'Jetzt aber ist ihr Aussehen schwärzer als Ruß geworden, man erkennt sie nicht mehr auf den Straßen; runzlig ist die Haut an ihrem Leibe, ausgedörrt wie ein Stück Holz.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 4, 9, 'Besser sind die vom Schwert Erschlagenen daran als die vom Hunger Getöteten, die da verschmachteten, zu Tode getroffen vom Mangel an Früchten des Feldes.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 4, 10, 'Haben doch weichherzige Frauen mit eigenen Händen ihre Kinder gekocht: die mußten ihnen zur Nahrung dienen beim Zusammenbruch der Tochter meines Volkes.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 4, 11, 'Der HERR hat seinen Grimm sich voll auswirken lassen, seine Zornesglut ausgegossen und in Zion ein Feuer entfacht, das seine Grundfesten verzehrt hat.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 4, 12, 'Sie hatten es nicht geglaubt, die Könige der Erde, auch kein Bewohner des Erdkreises, daß Belagerer und Feinde (jemals) einziehn würden in die Tore Jerusalems.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 4, 13, 'Das ist geschehen wegen der Sünden ihrer Propheten, wegen der Missetaten ihrer Priester, die in ihrer Mitte das Blut von Gerechten vergossen haben.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 4, 14, 'Sie irrten wie Blinde auf den Straßen umher, mit Blut besudelt, so daß man ihre Kleider nicht berühren mochte.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 4, 15, '»Aus dem Wege, ein Unreiner!« rief man vor ihnen aus; »aus dem Wege! Hinweg, berührt ihn nicht!« »Wenn sie noch Gefallen daran finden, sich umherzutreiben«, sagte man unter den Heiden, »so dürfen sie nicht länger (bei uns) bleiben!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 4, 16, 'Der Zornesblick des HERRN hat sie zerstreut, er mag nichts mehr von ihnen sehen. Man achtete der Priester nicht und ließ den Ältesten keine Schonung widerfahren.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 4, 17, 'Noch immer schmachteten unsere Augen nach Hilfe für uns, die nicht erschien; auf unserer Warte warteten wir auf ein Volk, das nicht zu Hilfe kam.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 4, 18, 'Schon stellte man uns auf Schritt und Tritt nach, so daß wir uns auf unsern Straßen nicht frei bewegen konnten; unser Ende nahte, unsere Tage waren abgelaufen, ja, unser Ende war gekommen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 4, 19, 'Schneller waren unsere Verfolger als die Adler des Himmels; auf den Bergen jagten sie uns nach, in der Wüste lauerten sie uns auf.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 4, 20, 'Unser Lebensodem, der Gesalbte des HERRN, wurde in ihren Gruben gefangen, er, von dem wir dachten: »In seinem Schatten werden wir leben unter den Völkern!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 4, 21, 'Frohlocke nur und freue dich, Tochter Edom, die du wohnst im Lande Uz! Auch an dich wird der Becher kommen: du wirst trunken werden und dich entblößen!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 4, 22, 'Abgetan ist deine Schuld, Tochter Zion: Gott wird dich nicht wieder in Gefangenschaft führen; doch deine Schuld wird er heimsuchen, Tochter Edom, und deine Sünden aufdecken!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 5, 1, 'Gedenke, HERR, dessen, was uns widerfahren ist! Blicke her und sieh unsere Schmach!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 5, 2, 'Unser Erbbesitz ist an Fremde übergegangen, unsere Häuser an Ausländer.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 5, 3, 'Waisen sind wir geworden, vaterlos, unsere Mütter sind wie Witwen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 5, 4, 'Unser Wasser trinken wir um Geld, nur gegen Zahlung erhalten wir unser eignes Holz.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 5, 5, 'Unsere Verfolger sitzen uns auf dem Nacken, und sind wir ermattet, gönnt man uns keine Ruhe.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 5, 6, 'Den Ägyptern haben wir die Hand gereicht und den Assyrern, um uns satt zu essen. –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 5, 7, 'Unsere Väter, die gesündigt haben, sind nicht mehr: wir müssen ihre Verschuldungen büßen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 5, 8, 'Knechte herrschen über uns: niemand entreißt uns ihrer Hand.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 5, 9, 'Mit Lebensgefahr schaffen wir unser Brot herein, in Angst vor dem Schwert der Wüstenbewohner.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 5, 10, 'Unsere Haut glüht wie ein Ofen von der Fieberglut des Hungers.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 5, 11, 'Ehefrauen haben sie in Zion geschändet, Jungfrauen in den Städten Judas.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 5, 12, 'Fürsten sind von ihrer Hand gehenkt worden, das Ansehn der Ältesten wird nicht geachtet.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 5, 13, 'Jünglinge müssen die Handmühle schleppen, und Knaben wanken unter Lasten von Holz.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 5, 14, 'Die Alten bleiben fern vom Stadttor, die Jungen von ihrem Saitenspiel.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 5, 15, 'Geschwunden ist die Freude unsers Herzens, unser Reigentanz hat sich in Trauer verwandelt.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 5, 16, 'Die Krone ist uns vom Haupt gefallen: wehe uns, daß wir gesündigt haben!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 5, 17, 'Darob ist unser Herz krank geworden, darüber sind unsere Augen umdüstert:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 5, 18, 'über den Zionsberg, der verödet daliegt, auf dem die Füchse ihr Wesen treiben.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 5, 19, 'Du aber, HERR, thronst in Ewigkeit, dein Herrscherstuhl steht fest von Geschlecht zu Geschlecht.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 5, 20, 'Warum willst du uns vergessen für immer, uns verlassen lebenslang?');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 5, 21, 'Führe uns, HERR, zu dir zurück, daß wir umkehren! Laß unsere Tage erneuert werden wie vor alters!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 5, 22, 'Oder hast du uns gänzlich verworfen? Zürnst du uns unversöhnlich?');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 1, 1, 'Und es begab sich im dreißigsten Jahre im vierten Monat, am fünften Tage des Monats, als ich mich unter den in die Verbannung Weggeführten am Flusse Kebar befand: da tat sich der Himmel auf, und ich sah göttliche Gesichte.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 1, 2, 'Am fünften Tage des Monats – es war das fünfte Jahr seit der Wegführung des Königs Jojachin –:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 1, 3, 'da erging das Wort des HERRN an den Priester Hesekiel, den Sohn Busis, im Lande der Chaldäer am Flusse Kebar; dort kam die Hand des HERRN über ihn.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 1, 4, 'Als ich nämlich hinblickte, sah ich plötzlich einen Sturmwind von Norden daherfahren und eine gewaltige Wolke und zusammengeballtes Feuer, von Lichtglanz rings umgeben, und mitten aus ihm blinkte etwas hervor wie der Schimmer von Glanzerz [aus der Mitte des Feuers].');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 1, 5, 'Mitten in ihm erschien dann etwas, das vier lebenden Wesen glich, deren Aussehen folgendes war: sie hatten Menschengestalt,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 1, 6, 'aber jedes hatte vier Gesichter und jedes von ihnen vier Flügel.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 1, 7, 'Ihre Beine standen gerade, aber ihre Fußsohlen waren (abgerundet) wie die Fußsohle eines Kalbes, und sie funkelten so hell wie geglättetes Kupfer.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 1, 8, 'Unter ihren Flügeln befanden sich Menschenhände an allen vier Seiten, und alle vier hatten Flügel,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 1, 9, 'von denen immer einer den des nächsten berührte; ihre Gesichter wandten sich nicht um, wenn sie gingen, sondern sie gingen ein jedes geradeaus vor sich hin.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 1, 10, 'Ihre Gesichter sahen aber so aus: (vorn war) ein Menschengesicht, rechts ein Löwengesicht bei allen vieren, links ein Stiergesicht bei allen vieren, und nach innen ein Adlergesicht bei allen vieren.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 1, 11, 'Ihre Flügel waren nach oben hin ausgebreitet, bei jedem zwei, die sich untereinander berührten, und zwei bedeckten ihre Leiber.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 1, 12, 'Sie gingen ein jedes geradeaus vor sich hin: wohin der Geist sie zu gehen trieb, dahin gingen sie, ohne beim Gehen eine Wendung vorzunehmen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 1, 13, 'Und mitten zwischen den lebenden Wesen war etwas, das wie brennende Feuerkohlen aussah, wie Fackeln, deren Feuer zwischen den Wesen beständig hin und her fuhr; und das Feuer hatte einen strahlenden Glanz, und Blitze gingen aus dem Feuer hervor;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 1, 14, 'und die lebenden Wesen liefen hin und her, so daß es aussah wie Blitzstrahlen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 1, 15, 'Als ich nun die lebenden Wesen näher betrachtete, sah ich je ein Rad auf dem Erdboden neben jedem der vier Wesen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 1, 16, 'Das Aussehen der Räder war wie der Schimmer von Chrysolith, und alle vier hatten die gleiche Gestalt, und sie waren so hergestellt, als ob ein Rad innerhalb des andern Rades wäre.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 1, 17, 'Nach allen vier Seiten hin liefen sie, wenn sie liefen, ohne beim Laufen eine Wendung vorzunehmen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 1, 18, 'Ihre Felgen aber – sie hatten eine gewaltige Höhe und Furchtbarkeit – waren bei allen vier Rädern ringsum voller Augen;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 1, 19, 'und wenn die lebenden Wesen sich in Bewegung setzten, so liefen auch die Räder neben ihnen; und wenn die lebenden Wesen sich vom Erdboden erhoben, dann erhoben sich auch die Räder:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 1, 20, 'wohin der Geist jene zu gehen trieb, dahin gingen die Räder ebenfalls und erhoben sich zugleich mit ihnen; denn der Geist der lebenden Wesen war in den Rädern:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 1, 21, 'wenn jene gingen, so gingen auch sie, und wenn jene stehen blieben, so blieben auch sie stehen, und wenn jene sich von der Erde erhoben, so erhoben sich auch die Räder zugleich mit ihnen; denn der Geist der lebenden Wesen war in den Rädern.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 1, 22, 'Über den Häuptern der lebenden Wesen aber war etwas, das sah aus wie ein Himmelsgewölbe, wie wundervoll glänzender Bergkristall; oben über ihren Häuptern war es ausgebreitet.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 1, 23, 'Unterhalb des Himmelsgewölbes aber waren ihre Flügel geradegerichtet, jeder nach dem andern hin, von jedem zwei; mit den beiden anderen bedeckten sie ihre Leiber.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 1, 24, 'Und ich hörte das Rauschen ihrer Flügel wie das Rauschen gewaltiger Wasser, wie den Donner des Allmächtigen. Wenn sie gingen, glich das tosende Rauschen dem Getöse eines Heerlagers; wenn sie aber stillstanden, ließen sie ihre Flügel schlaff herabhängen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 1, 25, '[Und es kam eine Stimme von oberhalb des Himmelsgewölbes, das über ihren Häuptern war; wenn sie stillstanden, ließen sie ihre Flügel schlaff herabhängen.]');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 1, 26, 'Oben über dem Himmelsgewölbe aber, das sich über ihren Häuptern befand, da war es anzusehen wie Saphirstein, etwas, das einem Thron glich; und auf diesem Throngebilde war eine Gestalt zu sehen, die wie eine Mann aussah, oben darauf.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 1, 27, 'Und ich sah etwas wie den Schimmer von Glanzerz, wie das Aussehen von Feuer, das ringsum ein Gehäuse hat; von dem Körperteile an, der wie seine Hüften aussah, nach oben zu, und von dem Körperteile an, der wie seine Hüften aussah, nach unten zu sah ich es – wie Feuer anzuschauen; und strahlendes Licht war rings um ihn her.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 1, 28, 'Wie der Bogen aussieht, der am Regentage in den Wolken erscheint, so war das strahlende Licht ringsum anzusehen. So war das Aussehen der Erscheinung der Herrlichkeit des HERRN; und als ich sie erblickte, warf ich mich auf mein Angesicht nieder und hörte die Stimme eines, der da redete.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 2, 1, 'Und er sagte zu mir: »Menschensohn, tritt auf deine Füße; denn ich will mit dir reden.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 2, 2, 'Als er so zu mir sprach, kam eine Gotteskraft in mich, die mich auf meine Füße treten ließ; und ich hörte den an, der mit mir redete.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 2, 3, 'Er sagte dann zu mir: »Menschensohn! Ich sende dich zu denen vom Hause Israel, zu den abtrünnigen Stämmen, die sich gegen mich aufgelehnt haben; sie und ihre Väter sind von mir abgefallen bis auf den heutigen Tag.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 2, 4, 'Und die Söhne haben ein trotziges Gesicht und ein hartes Herz; zu ihnen sende ich dich, und du sollst zu ihnen sagen: ›So hat Gott, der HERR gesprochen!‹');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 2, 5, 'Mögen sie dann darauf hören oder mögen sie es lassen – denn sie sind ein widerspenstiges Geschlecht –, so sollen sie doch erkennen, daß ein Prophet unter ihnen aufgetreten ist.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 2, 6, 'Du aber, Menschensohn, fürchte dich nicht vor ihnen und laß dich durch ihre Reden nicht einschüchtern, ob auch Disteln und Dornen um dich sind und du unter Skorpionen wohnst: fürchte dich nicht vor ihren Reden und erschrick nicht vor ihren Mienen! Denn sie sind ein widerspenstiges Geschlecht.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 2, 7, 'Vielmehr sollst du ihnen meine Worte verkündigen, mögen sie darauf hören oder mögen sie es lassen; denn sie sind widerspenstig!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 2, 8, '»Du aber, Menschensohn, höre, was ich dir sage: Sei du nicht widerspenstig wie das widerspenstige Geschlecht! Öffne deinen Mund und iß, was ich dir jetzt gebe!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 2, 9, 'Als ich nun hinblickte, sah ich eine Hand, die sich mir entgegenstreckte, und in ihr befand sich eine Schriftrolle.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 2, 10, 'Er breitete sie vor mir aus, und sie war auf der Vorderseite und auf der Rückseite beschrieben; und zwar standen Klagen, Seufzer und Wehe auf ihr geschrieben.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 3, 1, 'Dann sagte er zu mir: »Menschensohn, iß, was du da vor dir siehst! Iß diese Schriftrolle und gehe dann hin und rede zum Hause Israel!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 3, 2, 'Da öffnete ich meinen Mund, und er gab mir jene Rolle zu essen;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 3, 3, 'dabei sagte er zu mir: »Menschensohn, verschlucke diese Schriftrolle, die ich dir gebe, und fülle deinen Leib mit ihr!« Da aß ich sie, und sie schmeckte mir im Munde süß wie Honig.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 3, 4, 'Darauf sagte er zu mir: »Menschensohn, auf! Begib dich zum Hause Israel und rede in meinem Namen zu ihnen!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 3, 5, 'Denn nicht zu einem Volk mit dunkler Sprache und unverständlicher Rede wirst du gesandt, sondern zum Hause Israel;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 3, 6, 'auch nicht zu zahlreichen Völkern mit fremder Sprache und unverständlicher Rede, deren Worte du nicht verstehst – freilich, wenn ich dich zu diesen sendete, würden sie auf dich hören –;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 3, 7, 'aber das Haus Israel wird nicht auf dich hören wollen: sie wollen ja auch auf mich nicht hören; denn das ganze Haus Israel hat eine harte Stirn und ein verstocktes Herz.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 3, 8, 'Doch wisse: ich will auch dein Angesicht hart machen gleich dem ihrigen und deine Stirn hart gleich der ihrigen:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 3, 9, 'wie Diamant, härter als Kieselstein, will ich deine Stirn machen. Fürchte dich nicht vor ihnen und laß dich durch ihre Mienen nicht einschüchtern! Denn sie sind ein widerspenstiges Geschlecht.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 3, 10, 'Dann fuhr er fort: »Menschensohn, alle meine Worte, die ich zu dir reden werde, nimm dir zu Herzen und laß sie in deine Ohren eindringen!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 3, 11, 'Und nun mache dich auf und begib dich zu den in der Verbannung Lebenden, zu deinen Volksgenossen; rede zu ihnen und sage ihnen: ›So hat Gott der HERR gesprochen!‹ – mögen sie nun darauf hören, oder mögen sie es lassen!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 3, 12, 'Da hob die Gotteskraft mich empor, und ich vernahm hinter mir ein lautes, gewaltiges Getöse, als die Herrlichkeit des HERRN sich von ihrer Stelle erhob,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 3, 13, 'nämlich das Rauschen der sich gegenseitig berührenden Flügel der vier lebenden Wesen und das Gerassel der Räder neben ihnen, ein lautes gewaltiges Getöse.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 3, 14, 'Als mich nun die Gotteskraft emporhob und mich entrückte, ging ich dahin, tief betrübt in der Erregung meines Geistes, während die Hand des HERRN übermächtig auf mir lastete.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 3, 15, 'So kam ich denn zu den in der Verbannung Lebenden nach Thel-Abib, wo sie am Flusse Kebar wohnten, und weilte dort sieben Tage lang unter ihnen, in dumpfes Schweigen versunken.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 3, 16, 'Als aber die sieben Tage um waren, erging das Wort des HERRN an mich also:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 3, 17, '»Menschensohn, ich habe dich zum Wächter für das Haus Israel bestellt: wenn du ein Wort aus meinem Munde vernommen hast, sollst du sie in meinem Namen verwarnen!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 3, 18, 'Wenn ich also zum Gottlosen sage: ›Du mußt des Todes sterben!‹ und du verwarnst ihn nicht und sagst kein Wort, um den Gottlosen vor seinem bösen Wandel zu warnen, um ihn am Leben zu erhalten, so wird er als Gottloser um seiner Verschuldung willen sterben, aber für den Verlust seines Lebens werde ich dich verantwortlich machen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 3, 19, 'Hast du aber den Gottlosen gewarnt und hat er sich trotzdem von seiner Gottlosigkeit und seinem bösen Wandel nicht abgewandt, so wird er zwar um seiner Verschuldung willen sterben, du aber hast deine Seele gerettet.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 3, 20, 'Und wenn ein Gerechter sich von seiner Gerechtigkeit abkehrt und Böses tut und ich ihm dann entgegentrete, so daß er stirbt: wenn du ihn dann nicht gewarnt hast, so wird er zwar infolge seiner Sünde sterben, und der gerechten Werke, die er vollbracht hat, wird nicht mehr gedacht werden; aber für den Verlust seines Lebens werde ich dich verantwortlich machen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 3, 21, 'Wenn du ihn aber, den Gerechten, gewarnt hast, daß er keine Sünde begehen möge, und er dann auch keine Sünde begeht, so wird er am Leben bleiben, weil er sich hat warnen lassen, und du hast deine Seele gerettet.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 3, 22, 'Da kam dort die Hand des HERRN über mich, und er gebot mir: »Mache dich auf und gehe in die Tal-Ebene hinaus: dort will ich mit dir reden!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 3, 23, 'Da machte ich mich auf und ging in die Tal-Ebene hinaus; und siehe, dort stand die Herrlichkeit des HERRN gerade so, wie ich sie am Flusse Kebar geschaut hatte; da warf ich mich auf mein Angesicht nieder.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 3, 24, 'Aber die Gotteskraft kam in mich und ließ mich auf meine Füße treten; und er redete mich an mit den Worten: »Gehe heim und schließe dich in deinem Hause ein!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 3, 25, 'Und du, Menschensohn, wisse wohl: man wird dir Fesseln anlegen und dich mit ihnen binden, so daß du nicht unter sie wirst hinausgehen können.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 3, 26, 'Und ich werde dir die Zunge am Gaumen kleben lassen: stumm sollst du werden und kein Strafprediger mehr für sie sein; denn sie sind ein widerspenstiges Geschlecht.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 3, 27, 'Wenn ich aber mit dir rede, werde ich dir den Mund auftun, und du sollst zu ihnen sagen: ›So hat Gott der HERR gesprochen!‹ Wer dann hören will, mag hören, und wer es lassen will, der mag es lassen! Denn sie sind ein widerspenstiges Geschlecht.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 4, 1, '»Du aber, Menschensohn, nimm dir einen Ziegelstein, lege ihn vor dich hin und ritze auf ihm eine Stadt ein, nämlich Jerusalem.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 4, 2, 'Dann eröffne die Belagerung gegen sie: errichte Belagerungswerke gegen sie, schütte gegen sie einen Wall auf, schlage Heerlager gegen sie auf und stelle Sturmböcke ringsum gegen sie auf.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 4, 3, 'Darauf hole dir eine eiserne Platte und stelle sie als eiserne Mauer zwischen dich und die Stadt hin; dann richte deine Blicke unverwandt gegen sie: so soll sie sich im Belagerungszustand befinden, und du sollst sie belagern: ein Wahrzeichen soll dies für das Haus Israel sein!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 4, 4, '»Sodann lege du dich auf deine linke Seite und trage die Verschuldung des Hauses Israel auf ihr; nach der Zahl der Tage, die du auf ihr liegst, sollst du ihre Verschuldung tragen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 4, 5, 'Ich aber will dir die Jahre ihrer Verschuldung in einer gleichgroßen Anzahl von Tagen auflegen, nämlich 390 Tage: so lange sollst du die Verschuldung des Hauses Israel tragen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 4, 6, 'Wenn du dann mit diesen Tagen zu Ende bist, so lege dich zum zweitenmal auf deine rechte Seite und trage die Verschuldung des Hauses Juda vierzig Tage lang: für jedes Jahr lege ich dir einen Tag auf.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 4, 7, 'Dabei sollst du deine Blicke und deinen entblößten Arm unverwandt auf die Belagerung Jerusalems richten und gegen die Stadt weissagen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 4, 8, 'Und wisse wohl: ich will dir Fesseln anlegen, daß du dich nicht von einer Seite auf die andere umwenden kannst, bis du mit den Tagen deiner Belagerung zu Ende bist.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 4, 9, '»Du aber nimm dir Weizen und Gerste, Bohnen und Linsen, Hirse und Spelt, tu sie zusammen in ein einziges Gefäß und bereite dir Brot daraus nach der Zahl der Tage, während derer du auf deiner Seite liegen mußt: 390 Tage lang sollst du das essen;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 4, 10, 'und zwar soll die Speise, die du zu dir nimmst, abgewogen täglich zwanzig Schekel betragen, und du sollst sie auf mehrere Mahlzeiten verteilen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 4, 11, 'Auch das Wasser sollst du abgemessen trinken, jedesmal ein Sechstel Hin; auch dieses sollst du in Zwischenräumen genießen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 4, 12, 'Und zwar sollst du (das Brot) wie Gerstenbrotkuchen zubereitet essen und diese vor ihren Augen auf Ballen von Menschenkot backen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 4, 13, '(Und du sollst sagen:) ›So hat der HERR gesprochen: Ebenso sollen die Kinder Israel ihr Brot unrein essen unter den Heidenvölkern, unter die ich sie verstoßen werde.‹«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 4, 14, 'Da entgegnete ich: »Ach, HERR, mein Gott! Siehe, mein Inneres ist noch niemals durch Unreines befleckt worden, und von verendeten oder zerrissenen Tieren habe ich seit meiner Jugend bis jetzt niemals etwas genossen, und abscheuliches Fleisch ist noch nie in meinen Mund gekommen.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 4, 15, 'Da antwortete er mir: »Nun gut! Ich will dir Rindermist statt des Menschenkotes gestatten: auf diesem magst du das Brot für dich bereiten.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 4, 16, 'Dann fuhr er fort: »Menschensohn, wisse wohl: ich will den Stab des Brotes in Jerusalem zerbrechen, so daß sie das Brot abgewogen und mit Angst essen müssen und das Wasser abgemessen und mit Entsetzen trinken,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 4, 17, 'weil es ihnen an Brot und Wasser mangeln soll und damit sie einer wie der andere verzweifeln und infolge ihrer Verschuldung verschmachten.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 5, 1, '»Du aber, Menschensohn, nimm dir ein scharfes Schwert; als Schermesser sollst du es für dich benutzen und mit ihm über dein Haupt und deinen Bart fahren. Sodann nimm dir eine Waage zum Abwägen und teile (die Haare) mit ihr ab:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 5, 2, 'ein Drittel verbrenne im Feuer inmitten der Stadt, wenn die Tage der Belagerung voll sind; das zweite Drittel nimm und schlage es mit dem Schwert rings um die Stadt her; und das letzte Drittel verstreue in den Wind; ich will dann das Schwert hinter ihnen her zücken.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 5, 3, 'Doch nimm von diesen eine kleine Anzahl und binde sie in deinen Rockzipfel ein;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 5, 4, 'hierauf nimm auch von diesen nochmals einige, wirf sie mitten ins Feuer und laß sie im Feuer verbrennen: davon soll ein Feuer über das ganze Haus Israel ausgehen.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 5, 5, '»Alsdann sage zum ganzen Hause Israel: ›So hat Gott der HERR gesprochen: So steht’s mit Jerusalem! Mitten unter die Heiden habe ich die Stadt gestellt und (deren) Länder rings um sie her.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 5, 6, 'Aber sie ist gegen meine Gebote in gottloser Weise widerspenstig gewesen, ärger noch als die Heidenvölker, und gegen meine Satzungen ärger als die Länder rings um sie her; denn meine Gebote haben sie verachtet, und nach meinen Satzungen sind sie nicht gewandelt.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 5, 7, 'Darum hat Gott der HERR so gesprochen: Weil ihr trotziger gewesen seid als die Heidenvölker rings um euch her, weil ihr euch in eurem Wandel nach meinen Satzungen nicht gerichtet und meine Gebote nicht befolgt habt, vielmehr nach den Geboten der Heidenvölker rings um euch her gehandelt habt,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 5, 8, 'darum spricht Gott der HERR so: Fürwahr, auch ich will nun gegen dich vorgehen und will Gerichte in deiner Mitte vollstrecken vor den Augen der Heidenvölker!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 5, 9, 'Und ich will um all deiner Greuel willen an dir tun, was ich noch nie getan habe und was ich in gleicher Weise auch nie wieder tun werde.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 5, 10, 'Darum werden Väter in deiner Mitte ihre Kinder aufessen, und Kinder werden ihre Väter verzehren; und ich will Strafgerichte an dir vollstrecken und alles, was von dir noch übriggeblieben ist, in alle Winde zerstreuen!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 5, 11, 'Darum, so wahr ich lebe!‹ – so lautet der Ausspruch Gottes des HERRN –: ›fürwahr, weil du mein Heiligtum durch all deine scheußlichen Götzen und durch all deine Greuel verunreinigt hast, so will auch ich nun mein Auge von dir abwenden ohne Mitleid und will keine Schonung mehr üben!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 5, 12, 'Der dritte Teil von dir soll an der Pest sterben und durch Hunger umkommen in deiner Mitte; das zweite Drittel soll durchs Schwert fallen rings um dich her; und das letzte Drittel will ich in alle Winde zerstreuen und das Schwert hinter ihnen her zücken.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 5, 13, 'Wenn so mein Zorn sich voll ausgewirkt hat und ich meinen Grimm an ihnen gestillt und Rache genommen habe, dann werden sie erkennen, daß ich, der HERR, in meinem Eifer geredet habe, wenn ich meinen Grimm an ihnen voll auswirke.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 5, 14, 'Ja, ich will dich zur Einöde machen und zum Gegenstand des Hohnes unter den Heidenvölkern rings um dich her, vor den Augen aller Vorüberziehenden.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 5, 15, 'Und du sollst ein Gegenstand des Hohnes und der Schmach sein, eine Warnung und ein Entsetzen für die Heidenvölker rings um dich her, wenn ich Strafgerichte an dir vollziehe im Zorn und im Grimm und mit meinen grimmigen Heimsuchungen – ich, der HERR, habe es gesagt! –,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 5, 16, 'wenn ich die schlimmen, verderblichen Pfeile des Hungers gegen euch abschieße, die ich entsenden werde, um euch zu vernichten, und wenn ich die Hungersnot immer schrecklicher bei euch wirken lasse und ich euch den Stab des Brotes zerbreche.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 5, 17, 'Und außer der Hungersnot will ich auch böse Tiere gegen euch loslassen, damit sie dich deiner Kinder berauben; und Pest und Blutvergießen sollen bei dir umgehen, und auch das Schwert will ich über dich kommen lassen – ich, der HERR, habe es gesagt!‹«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 6, 1, 'Weiter erging das Wort des HERRN an mich so:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 6, 2, '»Menschensohn, richte deine Blicke gegen die Berge Israels und sprich folgende Weissagungen gegen sie aus:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 6, 3, '›Ihr Berge Israels, hört das Wort Gottes, des HERRN! So spricht Gott der HERR zu den Bergen und Hügeln, zu den Rinnsalen und Tälern: Fürwahr ich lasse das Schwert über euch kommen und mache eurem Höhendienst ein Ende!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 6, 4, 'Eure Altäre sollen zerstört und eure Sonnensäulen zertrümmert werden, und eure Erschlagenen will ich vor eure Götzen hinwerfen,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 6, 5, 'ja ich will die Leichen der Söhne Israels vor ihre Götzen hinwerfen und eure Gebeine rings um eure Altäre verstreuen!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 6, 6, 'Überall, wo ihr wohnt, sollen die Ortschaften verwüstet werden und die Opferhöhen verödet werden, damit eure Altäre verlassen und zerstört dastehen und eure Götzen zertrümmert werden und verschwinden, eure Sonnensäulen umgehauen und eure Machwerke vernichtet werden;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 6, 7, 'und Durchbohrte sollen in eurer Mitte zu Boden fallen, damit ihr erkennt, daß ich der HERR bin.‹«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 6, 8, '»›Doch will ich einige von euch übriglassen, indem von euch Schwertentronnene unter den Heidenvölkern leben werden, wenn ihr in die Länder zerstreut seid.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 6, 9, 'Diese von euch Entronnenen werden dann unter den Heidenvölkern, wohin sie als Gefangene weggeführt worden sind, meiner gedenken, wenn ich ihr Herz, das treulos von mir abgefallen war, und ihre Augen, die buhlerisch auf ihre Götzen gerichtet waren, zerbrochen habe. Dann werden sie vor sich selbst Abscheu empfinden wegen der Missetaten, die sie mit all ihren Greueln begangen haben,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 6, 10, 'und sie werden erkennen, daß ich, der HERR, nicht umsonst gedroht habe, ihnen solches Unheil widerfahren zu lassen.‹«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 6, 11, 'So hat Gott der HERR gesprochen: »Schlage die Hände zusammen und stampfe mit dem Fuße und rufe ›Wehe!‹ über all die schlimmen Greuel des Hauses Israel, deretwegen sie durch das Schwert, durch Hunger und durch Pest umkommen sollen!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 6, 12, 'Wer in der Ferne weilt, soll durch die Pest sterben, und wer in der Nähe ist, soll durch das Schwert fallen, und wer dann noch übriggeblieben und mit dem Leben davongekommen ist, soll Hungers sterben: so will ich meinen Grimm an ihnen voll auswirken!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 6, 13, 'Alsdann werdet ihr erkennen, daß ich der HERR bin, wenn ihre Erschlagenen inmitten ihrer Götzen rings um ihre Altäre daliegen auf jedem hohen Hügel und auf allen Berggipfeln, unter jedem grünenden Baume und unter jeder dichtbelaubten Terebinthe, an den Stätten, wo sie all ihren Götzen lieblichen Opferduft gespendet haben.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 6, 14, 'Ja, ich will meine Hand gegen sie ausstrecken und das Land zur Wüste und Wildnis machen von der Steppe an bis nach Ribla hin, überall, wo sie wohnen, damit sie erkennen, daß ich der HERR bin.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 7, 1, 'Weiter erging das Wort des HERRN an mich folgendermaßen:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 7, 2, '»Du, Menschensohn, so spricht Gott der HERR zum Lande Israel: ›Ein Ende kommt! Es kommt das Ende über alle vier Enden des Landes!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 7, 3, 'Jetzt kommt das Ende über dich; ich will meinen Zorn gegen dich loslassen und dich nach deinem ganzen Tun richten und dich für alle deine Greuel büßen lassen!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 7, 4, 'Mein Auge soll nicht mehr mitleidig nach dir blicken, und ich werde keine Schonung mehr üben, sondern ich will dich für dein ganzes Tun büßen lassen, und die Folgen deiner Greuel sollen sich bei dir fühlbar machen, damit ihr erkennt, daß ich der HERR bin!‹«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 7, 5, 'So hat Gott der HERR gesprochen: »Unglück über Unglück! Siehe da, es kommt!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 7, 6, 'Ein Ende kommt! Es kommt das Ende! Es erwacht gegen dich: siehe da, es kommt!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 7, 7, 'Das Verhängnis kommt über dich, Bewohnerschaft des Landes! Es kommt die Zeit, nahe ist der Tag, ein Tag der Bestürzung und nicht des Jauchzens auf den Bergen!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 7, 8, 'Nunmehr will ich gar bald meinen Grimm über dich ausgießen und meinen Zorn sich an dir erschöpfen lassen und will dich nach deinem ganzen Tun richten und dich für all deine Greuel büßen lassen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 7, 9, 'Mein Auge soll nicht mehr mitleidig nach dir blicken, und ich werde keine Schonung üben; nein, ich will dir nach deinem ganzen Tun vergelten, und die Folgen deiner Greuel sollen sich bei dir fühlbar machen, damit ihr erkennt, daß ich, der HERR, es bin, der da schlägt.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 7, 10, 'Siehe, da ist der Tag! Siehe, da kommt er! Das Verhängnis ist aufgesproßt, die Rute aufgewachsen, der Übermut steht in Blüte!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 7, 11, 'Die Gewalttätigkeit hat sich zur Rute des Frevels erhoben; nichts wird von ihnen übrigbleiben, nichts von ihrem Gepränge, nichts von ihrem Reichtum, nichts von ihrer Herrlichkeit!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 7, 12, 'Es kommt die Zeit, der Tag ist nahe! Der Käufer freue sich nicht, und der Verkäufer gräme sich nicht! Denn Zornglut ergeht über all ihr Gepränge.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 7, 13, 'Denn der Verkäufer wird nicht wieder zu dem verkauften Gut gelangen, wenn er auch noch so lange unter den Lebenden lebt; denn meine Zornglut gegen all ihr Gepränge kehrt nicht um, und keiner wird infolge seiner Verschuldung sein Leben in festem Besitz haben.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 7, 14, 'Stoßt immerhin in die Trompete und rüstet alles zu: es ist doch keiner da, der zum Kampf auszieht! Denn meine Zornglut ergeht über all ihr Gepränge:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 7, 15, 'das Schwert draußen, die Pest und die Hungersnot drinnen! Wer auf dem Felde ist, wird durchs Schwert den Tod finden; und wer in der Stadt ist, den werden Hunger und Pest ums Leben bringen;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 7, 16, 'und wenn Füchtlinge von ihnen entrinnen, so werden sie auf den Bergen sein wie die Tauben in den Schluchten, allesamt girrend, ein jeder um seiner Verschuldung willen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 7, 17, 'Alle Arme werden schlaff herabsinken und alle Knie wie Wasser zerfließen;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 7, 18, 'sie werden sich mit Sackleinen umgürten, und Schauder wird ihre Glieder durchrieseln; auf allen Gesichtern wird Schamröte liegen und auf all ihren Häuptern Kahlheit.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 7, 19, 'Ihr Silber werden sie auf die Straßen werfen, und ihr Gold wird ihnen als Unrat gelten; denn ihr Silber und ihr Gold vermag sie am Tage des göttlichen Zorns nicht zu retten: ihren Hunger werden sie damit nicht zu stillen und ihren Leib damit nicht zu füllen vermögen; denn es ist für sie der Anstoß zu ihrer Verschuldung gewesen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 7, 20, 'Der daraus verfertigte kostbare Schmuck hat sie zur Überhebung verführt, und sie haben ihre greulichen Götterbilder, ihre scheußlichen Götzen, daraus hergestellt; darum will ich es ihnen zum Unrat machen');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 7, 21, 'und will es den Fremden zum Raube und den Gottlosesten der Erde zur Plünderung preisgeben, damit sie es entweihen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 7, 22, 'Und ich will mein Angesicht von ihnen abwenden, damit sie mein Kleinod entweihen; Räuber sollen in dasselbe eindringen und es entweihen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 7, 23, 'Man verfertige die Kette! Denn das Land ist voll von Blutschuld und die Stadt voll von Verbrechen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 7, 24, 'So will ich denn die schlimmsten der Heidenvölker herbeiholen: die sollen ihre Häuser in Besitz nehmen; und ich will dem Hochmut der Mächtigen ein Ende machen, und ihre Heiligtümer sollen entweiht werden.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 7, 25, 'Angst kommt: da werden sie Rettung suchen, aber keine ist zu finden.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 7, 26, 'Unglück über Unglück kommt, und eine Schreckenskunde nach der andern trifft ein: da werden sie (vergeblich) eine Weissagung von Propheten verlangen, und den Priestern wird die Belehrung fehlen und den Ältesten der gute Rat.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 7, 27, 'Der König wird trauern und der Fürst sich in Entsetzen kleiden, und dem Volk im Lande werden die Arme vor Schrecken gelähmt sein. Nach ihrem ganzen Tun will ich mit ihnen verfahren und auf Grund ihrer eigenen Rechtsbestimmungen sie richten: dann werden sie erkennen, daß ich der HERR bin.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 8, 1, 'Es begab sich sodann im sechsten Jahre, am fünften Tage des sechsten Monats, während ich in meinem Hause saß und die Ältesten von Juda vor mir saßen, da fiel dort die Hand Gottes des HERRN auf mich;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 8, 2, 'ich hatte ein Gesicht: Ich sah plötzlich eine Gestalt, die wie ein Mann aussah; von dem Körperteile an, der wie seine Hüften aussah, nach unten zu war’s wie Feuer, und von seinen Hüften aufwärts sah es wie Lichtglanz aus, wie der Schimmer von Glanzerz.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 8, 3, 'Da streckte er etwas aus, das wie eine Hand gebildet war, und faßte mich bei den Locken meines Hauptes; dann hob die Gotteskraft mich zwischen Erde und Himmel empor und brachte mich im Zustand der Verzückung nach Jerusalem an den Eingang des Tores zum inneren Vorhof, das nach Norden zu liegt, woselbst das die Eifersucht des HERRN erregende Eiferbild seinen Standort hatte.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 8, 4, 'Und siehe, dort stand die Herrlichkeit des Gottes Israels in derselben Erscheinung, wie ich sie in der Tal-Ebene gesehen hatte.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 8, 5, 'Da sagte er zu mir: »Menschensohn, erhebe deine Augen in der Richtung nach Norden!« Als ich nun meine Augen nach Norden hin richtete, sah ich das betreffende Eiferbild nördlich vom Altartor am Eingang stehen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 8, 6, 'Da sagte er zu mir: »Menschensohn, siehst du wohl, was sie da treiben? Arge Greuel sind es, die das Haus Israel hier verübt, um mich von meinem Heiligtum weit wegzutreiben. Aber du wirst weiterhin noch ärgere Greuel zu sehen bekommen.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 8, 7, 'Darauf brachte er mich an den Eingang des Vorhofes; und als ich mich umsah, bemerkte ich ein Loch in der Wand.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 8, 8, 'Da sagte er zu mir: »Menschensohn, zwänge dich durch die Wand hindurch!« Als ich mich nun durch die Wand hindurchgezwängt hatte, kam dort eine Tür zum Vorschein.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 8, 9, 'Darauf sagte er zu mir: »Gehe hinein und sieh dir die schlimmen Greuel an, die sie hier verüben!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 8, 10, 'Als ich nun hineingegangen war und mich umsah, fanden sich da allerlei Abbildungen von scheußlichen kriechenden und vierfüßigen Tieren und allerlei Götzen des Hauses Israel, ringsherum auf die Wand gezeichnet.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 8, 11, 'Vor diesen standen siebzig Männer von den Ältesten des Hauses Israel, und mitten unter ihnen stand Jaasanja, der Sohn Saphans; ein jeder von ihnen hatte seine Räucherpfanne in der Hand, und der Duft der Weihrauchwolken stieg empor.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 8, 12, 'Da sagte er zu mir: »Hast du wohl gesehen, Menschensohn, was die Ältesten des Hauses Israel hier im Verborgenen treiben, ein jeder in seiner Bilderkammer? Denn sie sagen: ›Der HERR sieht uns nicht, der HERR hat ja das Land verlassen!‹«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 8, 13, 'Dann fuhr er fort: »Du wirst weiterhin noch ärgere Greuel sehen, die sie verüben.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 8, 14, 'Hierauf brachte er mich an den Eingang des nördlichen Tores am Tempel des HERRN; dort sah ich die Frauen sitzen, die den Thammus beweinten.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 8, 15, 'Da sagte er zu mir: »Siehst du es wohl, Menschensohn? Aber du wirst noch andere ärgere Greuel sehen als diese.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 8, 16, 'Darauf führte er mich in den inneren Vorhof beim Tempel des HERRN; dort sah ich am Eingang zum Tempelhause des HERRN, zwischen der Vorhalle und dem Altar, ungefähr fünfundzwanzig Männer stehen; die beteten, mit dem Rücken gegen den Tempel des HERRN und mit dem Gesicht gegen Osten gewandt, die Sonne nach Osten hin an.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 8, 17, 'Da sagte er zu mir: »Hast du das gesehen, Menschensohn? Genügt es dem Hause Juda nicht, die Greuel zu verüben, die sie hier treiben, daß sie auch noch das Land mit Gewalttat erfüllen und mich immer wieder zum Zorn reizen? Und nun siehe, da halten sie grüne Zweige an die Nase!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 8, 18, 'So will denn auch ich im Grimm gegen sie vorgehen: mein Auge soll nicht mehr mitleidig nach ihnen blicken, und ich will keine Schonung mehr üben! Und wenn sie mir noch so laut in die Ohren schreien, will ich doch nicht auf sie hören!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 9, 1, 'Hierauf hörte ich ihn mit lauter Stimme so rufen: »Es naht das Strafgericht über die Stadt! Ein jeder nehme jetzt also sein Zerstörungswerkzeug in die Hand!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 9, 2, 'Und siehe, da kamen sechs Männer des Weges vom oberen Tore her, das nach Norden zu liegt; ein jeder von ihnen hatte sein Werkzeug zum Zertrümmern in der Hand; einer aber befand sich unter ihnen, der in ein linnenes Gewand gekleidet war und ein Schreibzeug (am Gürtel) an seiner Hüfte hatte; die kamen und traten neben den ehernen Altar.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 9, 3, 'Die Herrlichkeit des Gottes Israels aber hatte sich inzwischen von dem Cherubwagen, auf dem sie sich befunden hatte, erhoben und war auf die Schwelle des Tempels getreten; dort rief er dem in Linnen gekleideten Manne, der das Schreibzeug an seiner Hüfte hatte,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 9, 4, 'die Worte zu: »Gehe mitten durch die Stadt, mitten durch Jerusalem, und bringe ein Zeichen auf der Stirn der Männer an, die da klagen und seufzen über all die Greuel, die innerhalb der Stadt verübt werden!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 9, 5, 'Zu den anderen aber sagte er so, daß ich es hörte: »Geht hinter diesem her durch die Stadt und schlagt darein! Eure Augen sollen kein Mitleid haben, und ihr dürft keine Schonung üben!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 9, 6, 'Greise, Jünglinge und Jungfrauen, Kinder und Frauen metzelt nieder, bis alles vernichtet ist! Aber alle, die das Zeichen an sich tragen, laßt unberührt! Und bei meinem Heiligtum hier macht den Anfang!« Da fingen sie bei jenen Ältesten an, die vor dem Tempelhause standen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 9, 7, 'Dann sagte er zu ihnen: »Verunreinigt das Tempelhaus und füllt die Vorhöfe mit Erschlagenen an! Zieht aus!« So zogen sie denn aus und schlugen in der Stadt nieder.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 9, 8, 'Als sie nun so mordeten und ich allein übriggeblieben war, da warf ich mich auf mein Angesicht nieder, schrie laut auf und rief: »Ach, HERR, mein Gott! Willst du denn alles umbringen, was von Israel noch übrig ist, indem du deinen Zorn über Jerusalem ausschüttest?«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 9, 9, 'Da antwortete er mir: »Die Schuld des Hauses Israel und Juda ist über alle Maßen groß: das Land ist voll von Bluttaten und die Stadt mit Verbrechen angefüllt! denn sie sagen: ›Der HERR hat das Land verlassen‹ und ›der HERR sieht es nicht!‹');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 9, 10, 'So soll denn auch mein Auge nicht mehr mitleidig blicken, und ich will keine Schonung mehr üben; nein, ich will die Strafe für ihr ganzes Tun auf ihr Haupt fallen lassen!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 9, 11, 'Da erstattete der in Linnen gekleidete Mann, an dessen Hüfte sich das Schreibzeug befand, Bericht mit den Worten: »Ich habe getan, wie du mir geboten hast!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 10, 1, 'Als ich nun hinschaute, sah ich auf dem Himmelsgewölbe, das sich über dem Haupt der Cherube befand, etwas, das wie Saphirstein aussah: etwas wie ein Thron Gestaltetes wurde über ihnen sichtbar.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 10, 2, 'Da gab er dem in Linnen gekleideten Manne den Befehl: »Tritt in den Raum zwischen dem Räderwerk unten am Cherubwagen hinein, fülle deine Hände mit glühenden Kohlen aus dem Raum zwischen den Cheruben und streue sie über die Stadt hin!« Da ging er vor meinen Augen hinein.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 10, 3, 'Der Cherubwagen stand aber an der Südseite des Tempelhauses, als der Mann hineinging, während die Wolke den inneren Vorhof erfüllte.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 10, 4, 'Da erhob sich die Herrlichkeit des HERRN von dem Cherubwagen nach der Schwelle des Tempels hin, so daß der Tempel mit der Wolke erfüllt wurde und der Vorhof voll vom Lichtglanz der Herrlichkeit des HERRN war;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 10, 5, 'und das Rauschen der Flügel der Cherube war bis in den äußeren Vorhof vernehmbar gleich der Stimme Gottes, des Allmächtigen, wenn er redete.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 10, 6, 'Als er nun dem in Linnen gekleideten Manne den Befehl erteilt hatte, Feuer aus dem Raum zwischen dem Räderwerk, aus dem Raum zwischen den Cheruben, zu nehmen, und dieser hineingegangen und neben das eine Rad getreten war,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 10, 7, 'da streckte einer der Cherube seine Hand aus dem zwischen den Cheruben befindlichen Raum hervor nach dem Feuer hin, das sich in dem Raum zwischen den Cheruben befand, und hob einen Teil davon ab und gab es dem in Linnen gekleideten Manne in die Hände; der nahm es und ging weg.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 10, 8, '[Es wurde aber an den Cheruben etwas, das wie eine Menschenhand gebildet war, unter ihren Flügeln sichtbar.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 10, 9, 'Als ich nämlich hinschaute, sah ich vier Räder, die neben den Cheruben waren, immer ein Rad neben jedem Cherub; die Räder aber waren wie glänzender Chrysolithstein anzusehen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 10, 10, 'Was aber ihr Aussehen betrifft, so hatten die vier alle dieselbe Gestalt, wie wenn ein Rad innerhalb des andern wäre.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 10, 11, 'Wenn sie sich in Bewegung setzten, konnten sie nach allen vier Seiten hin gehen: sie brauchten sich nicht zu wenden, wenn sie gingen; sie gingen vielmehr immer nach der Richtung, die der Vordere einschlug, hinter ihm her, ohne eine Wendung zu machen, wenn sie gingen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 10, 12, 'Der ganze Leib der Cherube aber, auch ihr Rücken, ihre Arme und Flügel und ebenso auch die Räder, waren bei allen vieren ringsum voll von Augen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 10, 13, 'Was aber die Räder betrifft, so führten sie, wie ich mit eigenen Ohren hörte, den Namen ›Wirbelwind‹.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 10, 14, 'Ein jeder von den Cheruben hatte vier Gesichter: das eine Gesicht war ein Stiergesicht, das zweite ein Menschengesicht, das dritte ein Löwengesicht und das vierte ein Adlergesicht.]');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 10, 15, 'Und die Cherube erhoben sich [es waren dies dieselben lebenden Wesen, die ich schon am Flusse Kebar gesehen hatte.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 10, 16, 'Wenn nämlich die Cherube sich in Bewegung setzten, so fingen auch die Räder neben ihnen an zu laufen; und wenn die Cherube ihre Flügel erhoben, um vom Erdboden emporzusteigen, so entfernten sich die Räder nicht von ihrer Seite:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 10, 17, 'wenn jene stehenblieben, so standen auch sie still, und wenn jene sich erhoben, so erhoben auch sie sich mit ihnen; denn der Geist der lebenden Wesen war in ihnen]. –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 10, 18, 'Darauf verließ die Herrlichkeit des HERRN die Schwelle des Tempelhauses und nahm ihren Stand wieder über den Cheruben.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 10, 19, 'Da schwangen die Cherube ihre Flügel und stiegen vor meinen Augen vom Erdboden empor, indem sie sich hinwegbegaben, und die Räder zugleich mit ihnen. Aber am Eingang des östlichen Tores des Tempels des HERRN machten sie wieder halt, während die Herrlichkeit des Gottes Israels sich oben über ihnen befand.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 10, 20, 'Es waren dies dieselben lebenden Wesen, die ich unterhalb des Gottes Israels schon am Flusse Kebar gesehen hatte; und ich erkannte, daß es Cherube waren.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 10, 21, 'Ein jeder hatte vier Gesichter und jeder vier Flügel; und etwas, das wie eine Menschenhand gebildet war, befand sich unter ihren Flügeln.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 10, 22, 'Was aber die äußere Erscheinung ihrer Gesichter betrifft, so waren es dieselben Gesichter, die ich schon am Flusse Kebar gesehen hatte; sie gingen ein jeder geradeaus vor sich hin.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 11, 1, 'Darauf hob die Gotteskraft mich empor und brachte mich an das östliche Tor am Tempel des HERRN, das nach Osten zu liegt; dort sah ich am Eingang des Tores fünfundzwanzig Männer stehen und erblickte in ihrer Mitte die Häupter des Volkes, Jaasanja, den Sohn Assurs, und Pelatja, den Sohn Benajas.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 11, 2, 'Da sagte er zu mir: »Menschensohn, das sind die Männer, die in dieser Stadt auf Unheil sinnen und böse Ratschläge erteilen,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 11, 3, 'die da sagen: ›Sind nicht erst kürzlich Häuser erbaut worden? Die Stadt ist der Kessel, und wir sind das Fleisch.‹');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 11, 4, 'Darum weissage gegen sie, ja weissage, Menschensohn!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 11, 5, 'Da fiel der Geist des HERRN auf mich und sagte zu mir: »Sprich: So hat Gott der HERR gesprochen: ›So redet ihr, Haus Israel, und die Gedanken, die in eurem Innern aufsteigen, kenne ich wohl.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 11, 6, 'Ihr habt die Zahl der von euch Erschlagenen in dieser Stadt groß gemacht und die Straßen hier mit Erschlagenen angefüllt.‹');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 11, 7, 'Darum hat Gott der HERR so gesprochen: ›Die von euch Erschlagenen, die ihr im Innern der Stadt hingestreckt habt, die sind das Fleisch, und sie ist der Kessel; euch aber werde ich aus ihrer Mitte hinausführen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 11, 8, 'Vor dem Schwert fürchtet ihr euch, das Schwert will ich über euch kommen lassen!‹ – so lautet der Ausspruch Gottes des HERRN.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 11, 9, '›Und ich will euch mitten aus dieser Stadt wegführen und euch in Feindeshand fallen lassen und Strafgerichte an euch vollziehen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 11, 10, 'Durch das Schwert sollt ihr fallen: an der Grenze Israels will ich Gericht über euch halten, damit ihr erkennt, daß ich der HERR bin!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 11, 11, 'Diese Stadt soll für euch nicht der Kessel sein, und ihr sollt nicht das Fleisch in ihr sein; an der Grenze Israels will ich Gericht über euch halten!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 11, 12, 'Dann werdet ihr erkennen, daß ich der HERR bin, ich, nach dessen Satzungen ihr nicht gewandelt und dessen Geboten ihr nicht nachgekommen seid; vielmehr habt ihr nach den Bräuchen der Heidenvölker gelebt, die rings um euch her wohnen!‹« –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 11, 13, 'Da begab es sich, während ich so als Prophet redete, daß Pelatja, der Sohn Benajas, tot niederstürzte. Da warf ich mich auf mein Angesicht nieder, schrie laut und rief aus: »Ach, HERR, mein Gott! willst du denn den letzten Rest Israels gänzlich vernichten?«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 11, 14, 'Hierauf erging das Wort des HERRN an mich folgendermaßen:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 11, 15, '»Menschensohn, deine Brüder, ja deine Brüder, deine Mitverbannten und das ganze Haus Israel, sie alle sind es, von denen die Bewohner Jerusalems sagen: ›Sie sind nun fern vom HERRN; uns ist das Land zu Besitz gegeben!‹');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 11, 16, 'Darum sage zu ihnen: ›So hat Gott der HERR gesprochen: Ich habe sie zwar in die Ferne unter die Heidenvölker gebracht und sie in die Länder zerstreut und bin ihnen nur wenig zum Heiligtum geworden in den Ländern, in die sie gekommen sind.‹');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 11, 17, 'Darum sage zu ihnen: ›So hat Gott der HERR gesprochen: Aber ich will sie aus den Völkern sammeln und sie aus den Ländern, in die sie zerstreut worden sind, wieder zusammenbringen und ihnen das Land Israel zurückgeben.‹');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 11, 18, 'Wenn sie dann dorthin zurückgekehrt sind und all seine scheußlichen Götzen und all seine Greuel aus ihm weggeschafft haben,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 11, 19, 'will ich ihnen ein anderes Herz verleihen und ihnen einen neuen Geist eingeben; ich will das steinerne Herz aus ihrer Brust herausnehmen und ihnen ein Herz von Fleisch einsetzen,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 11, 20, 'damit sie nach meinen Satzungen wandeln und meine Gebote beobachten und nach ihnen tun: alsdann sollen sie mein Volk sein, und ich will ihr Gott sein.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 11, 21, 'Die aber, deren Herz ihren scheußlichen Götzen anhängt und ihren Greueln zugewandt bleibt, die will ich für ihren Wandel büßen lassen!« – so lautet der Ausspruch Gottes des HERRN.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 11, 22, 'Darauf erhoben die Cherube ihre Flügel, und die Räder setzten sich zugleich mit ihnen in Bewegung, während die Herrlichkeit des Gottes Israels sich oben über ihnen befand.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 11, 23, 'Da stieg die Herrlichkeit des HERRN aus dem Bereich der Stadt empor und machte auf dem Berge halt, der östlich von der Stadt liegt.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 11, 24, 'Mich aber hob die Gotteskraft empor und brachte mich im Zustand der Verzückung zurück ins Chaldäerland zu den in der Verbannung Lebenden, und das Gesicht, das ich geschaut hatte, entschwand meinen Blicken.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 11, 25, 'Hierauf teilte ich den in der Gefangenschaft Lebenden alle Worte mit, die der HERR mich hatte schauen lassen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 12, 1, 'Hierauf erging das Wort des HERRN an mich folgendermaßen:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 12, 2, '»Menschensohn, du wohnst inmitten des widerspenstigen Geschlechts, das Augen hat zum Sehen und doch nicht sieht, das Ohren hat zum Hören und doch nicht hört; denn sie sind ein widerspenstiges Geschlecht.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 12, 3, 'Darum du, Menschensohn: mache dir Auswanderungsgeräte zurecht und ziehe bei Tage vor ihren Augen aus und wandere vor ihren Augen von deiner Wohnstätte weg nach einem andern Ort: vielleicht kommen sie dann zur Erkenntnis, daß sie ein widerspenstiges Geschlecht sind.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 12, 4, 'Schaffe also deine Geräte wie Auswanderungsgeräte bei Tage vor ihren Augen hinaus; du selbst aber sollst am Abend vor ihren Augen ausziehen, wie jemand auszieht, der auswandern will.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 12, 5, 'Vor ihren Augen brich dir ein Loch durch die Wand und gehe durch dieses hinaus.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 12, 6, 'Vor ihren Augen nimm (deine Geräte) auf die Schulter und in der Dunkelheit ziehe aus; das Gesicht verhülle dir, so daß du das Land nicht sehen kannst; denn ich habe dich zu einem Wahrzeichen für das Haus Israel bestimmt.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 12, 7, 'Da tat ich so, wie mir geboten worden war: meine Geräte trug ich wie Auswanderungsgeräte hinaus, und zwar bei Tage, am Abend aber brach ich mir ein Loch durch die Wand [mit der Hand]; in der Dunkelheit ging ich hinaus und trug meine Sachen vor ihren Augen auf der Schulter.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 12, 8, 'Am nächsten Morgen aber erging das Wort des HERRN an mich folgendermaßen:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 12, 9, '»Menschensohn, haben nicht die vom Hause Israel, das widerspenstige Geschlecht, dich gefragt: ›Was machst du da?‹');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 12, 10, 'Sage zu ihnen: ›So hat Gott der HERR gesprochen: Auf den Fürsten in Jerusalem bezieht sich dieser Gottesspruch und auf das ganze Haus Israel, das darin wohnt.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 12, 11, 'Sage zu ihnen: Ich bin ein Wahrzeichen für euch; wie ich es hier gemacht habe, so wird es auch ihnen ergehen: in die Verbannung werden sie als Gefangene ziehen müssen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 12, 12, 'Der Fürst aber, der sich mitten unter ihnen befindet, wird seine Sachen auf der Schulter tragen und sich im Finstern davonmachen; durch die Mauer wird er sich ein Loch brechen, um da hinauszuziehen; das Gesicht wird er sich verhüllen, damit er das Land mit seinen Augen nicht mehr sehe.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 12, 13, 'Ich werde aber mein Fangnetz über ihn ausbreiten, damit er in meinem Garn gefangen wird, und ich werde ihn nach Babylon bringen in das Land der Chaldäer, aber auch das wird er nicht sehen; und dort wird er sterben.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 12, 14, 'Und seine ganze Umgebung, seine Helfer und seine Kriegsscharen insgesamt, will ich in alle Winde zerstreuen und das Schwert hinter ihnen her zücken;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 12, 15, 'dann werden sie erkennen, daß ich der HERR bin, wenn ich sie unter die Heidenvölker zerstreue und sie in die Länder versprenge.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 12, 16, 'Nur einige wenige von ihnen will ich vom Schwert, vom Hunger und von der Pest verschont bleiben lassen, damit sie unter den Heidenvölkern, zu denen sie kommen werden, all ihre Greuel erzählen, und auch diese erkennen, daß ich der HERR bin.‹«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 12, 17, 'Weiter erging das Wort des HERRN an mich folgendermaßen:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 12, 18, '»Menschensohn, dein Brot sollst du mit Beben essen und dein Wasser mit Zittern und in Angst trinken');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 12, 19, 'und sollst zum Volk des Landes sagen: ›So hat Gott der HERR in betreff der Bewohner Jerusalems im Lande Israel gesprochen: Ihr Brot sollen sie in Angst essen und ihr Wasser mit Entsetzen trinken, weil ihr Land veröden soll, seiner Fülle beraubt wegen der Gottlosigkeit aller seiner Bewohner.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 12, 20, 'Ihre Städte, die jetzt noch bewohnt sind, sollen veröden, und das Land soll zur Wüste werden, damit ihr erkennt, daß ich der HERR bin.‹«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 12, 21, 'Hierauf erging das Wort des HERRN an mich folgendermaßen:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 12, 22, '»Menschensohn, was für eine Redensart ist da bei euch im Lande Israel im Gebrauch, daß man sagt: ›Die Zeit zieht sich Tag für Tag hin, und alle Weissagung wird hinfällig‹?');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 12, 23, 'Darum sage zu ihnen: ›So hat Gott der HERR gesprochen: Ich will dieser Redensart ein Ende machen; man soll sie in Israel nicht länger im Munde führen.‹ Sage ihnen vielmehr: ›Nahe herbeigekommen ist die Zeit und die Erfüllung aller Weissagungen!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 12, 24, 'Denn es wird hinfort keine täuschende Weissagung und keine trügerische Prophezeiung mehr im Hause Israel geben;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 12, 25, 'sondern ich, der HERR, werde reden, und was ich rede, das wird auch eintreffen, und zwar ohne längeren Verzug! Ja, noch in euren Tagen, du widerspenstiges Geschlecht, werde ich einen Ausspruch tun und ihn auch zur Ausführung bringen!‹« – so lautet der Ausspruch Gottes des HERRN.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 12, 26, 'Weiter erging das Wort des HERRN an mich folgendermaßen:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 12, 27, '»Menschensohn, wisse wohl: die vom Hause Israel sagen: ›Die Weissagungen, welche der da infolge von Offenbarungen ausspricht, gehen auf lange Zeit hinaus, und er prophezeit auf weite Zeiträume hinaus.‹');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 12, 28, 'Darum sage zu ihnen: ›So hat Gott der HERR gesprochen: Für keines meiner Worte soll es noch längeren Verzug geben; jedes Wort, das ich ausspreche, soll sich auch erfüllen!‹« – so lautet der Ausspruch Gottes des HERRN.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 13, 1, 'Weiter erging das Wort des HERRN an mich folgendermaßen:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 13, 2, '»Menschensohn, weissage gegen die Propheten Israels! Weissage und sprich zu denen, die nach eigener Eingebung weissagen: ›Hört das Wort des HERRN!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 13, 3, 'So hat Gott der HERR gesprochen: Wehe über die gewissenlosen Propheten, die ihrem eigenen Geist nachgehen und dem, was sie gar nicht gesehen haben!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 13, 4, 'Wie Füchse in den Trümmerstätten sind deine Propheten geworden, Israel.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 13, 5, 'Sie sind nicht in die Risse eingetreten und haben keine Mauer um das Haus Israel her aufgeführt, damit es feststehen möchte im Kampf am Tage des HERRN.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 13, 6, 'Ihr Prophezeien ist Lüge gewesen und ihr Wahrsagen Trug, sooft sie sagten: ›So lautet der Ausspruch des HERRN!‹, obwohl der HERR sie nicht gesandt hatte, und dann darauf warteten, daß er ihren Ausspruch in Erfüllung gehen ließe.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 13, 7, 'Habt ihr nicht nur Truggesichte geschaut und Lügenweissagungen ausgesprochen, sooft ihr sagtet: ›So lautet der Ausspruch des HERRN!‹, wiewohl ich nicht geredet hatte?‹«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 13, 8, 'Darum hat Gott der HERR so gesprochen: »Weil ihr Trug geredet und Lügen prophezeit habt, darum will ich nunmehr an euch« – so lautet der Ausspruch Gottes des HERRN.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 13, 9, '»Ja, meine Hand will ich ausstrecken gegen die Propheten, die Trug prophezeien und Lügen wahrsagen! Sie sollen mit meinem Volk in keiner Gemeinschaft mehr stehen und nicht in die Bürgerliste des Hauses Israel eingeschrieben werden, auch nicht mehr in das Land Israel zurückkommen, damit ihr erkennt, daß ich Gott der HERR bin.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 13, 10, 'Darum, ja darum, weil sie mein Volk irreführen, indem sie von Heil reden, wiewohl kein Heil da ist, und wenn (das Volk) sich eine Mauer baut, ihrerseits diese mit Kalk übertünchen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 13, 11, 'So sage denn zu diesen Tünchestreichern: ›(Die Mauer) soll einstürzen!‹ Wenn ein strömender Regen kommt und ich Hagelsteine fallen lasse und ein Sturmwind losbricht,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 13, 12, 'ja, dann fällt die Mauer zusammen, und man wird euch höhnisch fragen: ›Wo ist nun die Tünche geblieben, mit der ihr getüncht habt?‹«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 13, 13, 'Darum hat Gott der HERR so gesprochen: »So will ich denn einen Sturmwind losbrechen lassen in meinem Grimm, und ein strömender Regen soll kommen infolge meines Zornes und Hagelsteine sollen fallen infolge meines Grimms zur Vernichtung;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 13, 14, 'und ich will die Mauer niederreißen, die ihr mit Kalk übertüncht habt, und will sie zu Boden werfen, daß ihre Grundsteine bloßgelegt werden; und wenn sie einstürzt, sollt ihr in ihrer Mitte den Untergang finden, damit ihr erkennt, daß ich der HERR bin.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 13, 15, 'Wenn ich dann an der Mauer und an denen, die sie mit Tünche bestrichen haben, meinen Grimm sich voll habe auswirken lassen, wird man zu euch sagen: ›Verschwunden ist die Mauer, und die Leute, die sie getüncht haben, sind auch nicht mehr da,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 13, 16, 'die Propheten Israels, welche über Jerusalem weissagten und für die Stadt Gesichte des Heils schauten, wiewohl kein Heil da war‹« – so lautet der Ausspruch Gottes des HERRN.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 13, 17, '»Du aber, Menschensohn, tritt gegen die Töchter deines Volkes auf, die sich nach eigenem Gutdünken als Prophetinnen gebärden; sprich dich gegen sie aus');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 13, 18, 'und sage: ›So hat Gott der HERR gesprochen: Wehe den Weibern, die da Zauberbinden zusammennähen für alle Handgelenke und Hüllen anfertigen für Köpfe jedes Körperwuchses, um Seelen zu fangen! Seelen wollt ihr töten, die zu meinem Volke gehören, und Seelen erhaltet ihr euch zugute am Leben?!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 13, 19, 'Ihr entheiligt mich bei meinem Volk um ein paar Hände voll Gerste und um einiger Bissen Brotes willen, um Seelen zu töten, die nicht sterben sollen, und andere Seelen am Leben zu erhalten, die nicht am Leben bleiben sollen, wobei ihr mein Volk belügt, das gern auf Lügen hört.‹«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 13, 20, 'Darum hat Gott der HERR so gesprochen: »Wisset wohl: ich will nun gegen eure Zauberbinden vorgehen, mit denen ihr Seelen fangt, und will sie euch von den Armen abreißen und die Seelen, die ihr einfangt, frei fliegen lassen wie Vögel.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 13, 21, 'Auch eure Kopfhüllen will ich zerreißen und mein Volk aus eurer Hand befreien: sie sollen nicht länger als Beute in eurer Gewalt sein, und ihr sollt erkennen, daß ich der HERR bin.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 13, 22, 'Weil ihr den Herzen der Frommen durch Lügen wehegetan habt, denen ich keinen Schmerz zuzufügen gedachte, dagegen die Gottlosen in ihrem Tun bestärkt habt, so daß sie sich von ihrem bösen Wandel nicht abkehrten, um am Leben erhalten zu bleiben:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 13, 23, 'darum sollt ihr nicht länger erlogene Gesichte schauen und keine Wahrsagerei mehr treiben, sondern ich will mein Volk euch aus den Händen reißen, dann werdet ihr erkennen, daß ich der HERR bin.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 14, 1, 'Es kamen aber einige von den Ältesten Israels zu mir und ließen sich vor mir nieder.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 14, 2, 'Da erging das Wort des HERRN an mich folgendermaßen:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 14, 3, '»Menschensohn, diese Männer haben ihre Götzen in ihr Herz geschlossen und sie als Anstoß zu ihrer Verschuldung vor sich hingestellt: sollte ich mich da noch von ihnen befragen lassen?«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 14, 4, '»Darum rede mit ihnen und sage zu ihnen: ›So hat Gott der HERR gesprochen: Wenn irgend jemand aus dem Hause Israel seine Götzen in sein Herz geschlossen hat und sie als Anstoß zu seiner Verschuldung vor sich hinstellt und sich dennoch zu einem Propheten begibt: dem will ich, der HERR, persönlich die Antwort erteilen trotz der Menge seiner Götzen,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 14, 5, 'um die vom Hause Israel, die sich um all ihrer Götzen willen von mir abgewandt haben, am Herzen zu fassen.‹');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 14, 6, 'So sage denn zum Hause Israel: ›So hat Gott der HERR gesprochen: Kehrt um! Laßt euch von eurem Götzendienst bekehren und wendet eure Augen von all euren Greueln ab!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 14, 7, 'Denn wenn irgend jemand vom Hause Israel und von den Fremden, die in Israel wohnen, sich von mir lossagt und seine Götzen in sein Herz schließt und sie als Anstoß zu seiner Verschuldung vor sich hinstellt und sich trotzdem zu einem Propheten begibt, um mich für sich zu befragen, so will ich, der HERR, selbst ihm die Antwort erteilen;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 14, 8, 'und zwar will ich gegen den betreffenden Mann vorgehen und ihn zu einem warnenden Beispiel und zu einem Sprichwort machen: ich will ihn aus der Mitte meines Volkes ausrotten, damit ihr erkennet, daß ich der HERR bin.‹«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 14, 9, '»Wenn aber der Prophet sich dazu verleiten läßt, einen Ausspruch zu tun, dann habe ich, der HERR, diesen Propheten verleitet, und ich werde meine Hand gegen ihn ausstrecken und ihn aus der Mitte meines Volkes Israel ausrotten.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 14, 10, 'So sollen sie beide für ihre Verschuldung büßen: der Prophet soll ebenso schuldig sein wie der Befragende,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 14, 11, 'damit die vom Hause Israel fortan nicht mehr von mir abirren und sich nicht länger durch all ihre Abfallsünden beflecken; alsdann sollen sie mein Volk sein, und ich will ihr Gott sein« – so lautet der Ausspruch Gottes des HERRN.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 14, 12, 'Darauf erging das Wort des HERRN an mich folgendermaßen:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 14, 13, '»Menschensohn, wenn ein Land sich gegen mich versündigte, indem es Treubruch beginge, und ich dann meine Hand gegen dieses Volk ausstreckte und ihm den Stab des Brotes zerbräche und Hungersnot ihm zusendete und Menschen samt Vieh in ihm ausrottete,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 14, 14, 'und es befänden sich diese drei Männer in seiner Mitte, Noah, Daniel und Hiob: so würden nur diese drei ihr Leben infolge ihrer Gerechtigkeit retten« – so lautet der Ausspruch Gottes des HERRN.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 14, 15, '»Oder wenn ich wilde Tiere das Land durchstreifen ließe, damit sie es entvölkerten, auf daß es zu einer Einöde würde, die niemand mehr aus Furcht vor den wilden Tieren durchwanderte,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 14, 16, 'und jene drei Männer befänden sich in seiner Mitte: so wahr ich lebe!« – so lautet der Ausspruch Gottes des HERRN –, »sie würden weder Söhne noch Töchter retten: nein, sie allein würden gerettet, das Land aber würde zur Einöde werden.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 14, 17, 'Oder wenn ich das Schwert über das betreffende Land kommen ließe und dem Schwert geböte, durch das Land dahinzufahren, und wenn ich dann Menschen samt Vieh darin ausrottete');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 14, 18, 'und jene drei Männer befänden sich in seiner Mitte: so wahr ich lebe!« – so lautet der Ausspruch Gottes des HERRN –, »sie würden weder Söhne noch Töchter retten, sondern sie allein würden gerettet werden.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 14, 19, 'Oder wenn ich die Pest in das betreffende Land schickte und meinen Grimm als Blut(-regen) über das Land ausgösse, um Menschen samt Vieh in ihm auszurotten,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 14, 20, 'und Noah, Daniel und Hiob befänden sich in seiner Mitte: so wahr ich lebe!« – so lautet der Ausspruch Gottes des HERRN –, »sie würden weder Sohn noch Tochter retten, sondern durch ihre Gerechtigkeit nur ihr eigenes Leben retten.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 14, 21, 'Und doch hat Gott der HERR so gesprochen: »Trotz alledem, wenn ich meine vier schlimmen Strafgerichte: Schwert und Hunger, wilde Tiere und Pest, über Jerusalem hereinbrechen lasse, um Menschen samt Vieh darin auszurotten,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 14, 22, 'fürwahr, so soll doch eine Schar von Geretteten in der Stadt übrigbleiben, welche Söhne und Töchter aus ihr herausführen. Seht, wenn diese dann zu euch hierher kommen und ihr ihren Wandel und ihr ganzes Tun seht, so werdet ihr euch über das Unglück trösten, das ich über Jerusalem verhängt habe, über alle Leiden, die ich über die Stadt habe kommen lassen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 14, 23, 'Sie werden euch dann einen Trost gewähren, wenn ihr ihren Wandel und ihr ganzes Tun seht, und ihr werdet erkennen, daß ich alles, was ich ihr habe widerfahren lassen, nicht ohne Grund getan habe« – so lautet der Ausspruch Gottes des HERRN.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 15, 1, 'Weiter erging das Wort des HERRN an mich folgendermaßen:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 15, 2, '»Menschensohn, was hat das Holz der Rebe vor allem andern Holz voraus, die Weinranke, die sich unter den Bäumen des Waldes befindet?');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 15, 3, 'Nimmt man etwa Holz von ihr, um es zu einer Arbeit zu verwenden? Oder nimmt man auch nur einen Pflock von ihr, um irgendeinen Gegenstand daran aufzuhängen?');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 15, 4, 'Nicht wahr, man wirft es ins Feuer, damit es da verzehrt wird; hat das Feuer dann seine beiden Enden verzehrt und ist sein Mittelstück angebrannt, taugt es da noch zu irgend einer Arbeit?');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 15, 5, 'Nein, selbst wenn es noch unversehrt ist, kann man es zu keiner Arbeit verwenden; wieviel weniger läßt es sich dann, wenn es vom Feuer angefressen und versengt ist, zu irgend etwas verarbeiten!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 15, 6, '»Darum sprich: ›So hat Gott der HERR gesprochen: Wie das Holz der Rebe unter den Bäumen des Waldes ist, das ich dem Feuer zum Fraß bestimmt habe, ebenso halte ich es mit den Bewohnern Jerusalems.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 15, 7, 'Ich will gegen sie vorgehen: aus dem Feuer sind sie zwar herausgekommen, doch das Feuer soll sie verzehren, damit ihr erkennt, daß ich der HERR bin, wenn ich gegen sie vorgehe');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 15, 8, 'und das Land zur Wüste mache, weil sie Treubruch begangen haben‹« – so lautet der Ausspruch Gottes des HERRN.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 1, 'Weiter erging das Wort des HERRN an mich folgendermaßen:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 2, '»Menschensohn, halte der Stadt Jerusalem ihre Greuel vor');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 3, 'mit den Worten: ›So spricht Gott der HERR zu Jerusalem: Deiner Herkunft und Geburt nach stammst du aus dem Lande der Kanaanäer: dein Vater war ein Amoriter und deine Mutter eine Hethiterin.‹«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 4, '»›Und was deine Geburt betrifft, so wurde dir an dem Tage, als du zur Welt kamst, weder die Nabelschnur abgeschnitten, noch wurdest du in einem Wasserbade rein gewaschen, noch mit Salz eingerieben und nicht in Windeln gewickelt;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 5, 'kein Auge blickte mitleidig auf dich hin, um dir irgendeinen derartigen Liebesdienst zu erweisen und sich deiner zu erbarmen; sondern du wurdest aufs freie Feld hingeworfen: so wenig machte man sich aus deinem Leben am Tage deiner Geburt.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 6, 'Da kam ich an dir vorüber und sah dich in deinem Blut zappeln und sagte zu dir, als du in deinem Blut dalagst: Du sollst leben! Ja, ich sagte zu dir in deinem Blut: Bleibe leben');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 7, 'und wachse heran wie die Grashalme auf der Flur! Da wuchsest du heran und wurdest groß und gelangtest zu vollster Jugendblüte: die Brüste wölbten sich dir, dein Haar sproßte kräftig; doch du warst immer noch nackt und bloß.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 8, 'Als ich nun wieder an dir vorüberkam und dich sah, siehe, da war deine Zeit da, die Zeit der Liebe! Da breitete ich meinen Mantelzipfel über dich aus und bedeckte deine Blöße; ich schwur dir Treue und ging einen Bund mit dir ein‹ – so lautet der Ausspruch Gottes des HERRN –, ›und du wurdest mein.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 9, 'Dann wusch ich dich mit Wasser, spülte dein Blut von dir ab und salbte dich mit Öl;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 10, 'ich kleidete dich in bunte Gewänder, ließ dich Schuhe von Seekuhfell anziehen und einen Kopfbund von feiner Leinwand anlegen und hüllte dich in Seide;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 11, 'ich schmückte dich mit Geschmeide, ich legte dir Spangen an die Arme und eine Kette um den Hals,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 12, 'tat dir einen Ring an die Nase, Gehänge an die Ohren und eine prächtige Krone aufs Haupt.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 13, 'So warst du geschmückt mit Gold und Silber, deine Kleidung bestand aus feiner Leinwand, aus Seide und bunten Geweben; du nährtest dich von Semmel, von Honig und Öl, wurdest immer schöner und brachtest es bis zur Königswürde.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 14, 'Dein Ruhm erscholl unter den Völkern wegen deiner Schönheit; denn diese war vollkommen infolge des herrlichen Schmuckes, den ich dir angelegt hatte‹« – so lautet der Ausspruch Gottes des HERRN.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 15, '»›Aber da verließest du dich auf deine Schönheit und buhltest im Vertrauen auf deine Berühmtheit und warfst dich mit deiner buhlerischen Liebe an jeden Vorübergehenden weg, so daß du dich ihm preisgabst.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 16, 'Du nahmst von deinen Gewändern, machtest dir bunte Opferhöhen und triebst dort deine Unzucht [wie sie nie vorgekommen ist und nie wieder stattfinden wird].');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 17, 'Dann nahmst du auch deine prächtigen Geschmeide, die aus meinem Gold und meinem Silber, die ich dir geschenkt hatte, angefertigt waren, und machtest dir Mannsbilder daraus, mit denen du Buhlerei triebst;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 18, 'auch nahmst du deine bunten Gewänder und legtest sie ihnen an, und mein Öl und meinen Weihrauch brachtest du vor ihren Augen dar;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 19, 'und was ich dir als Speise gegeben hatte, Semmel, Öl und Honig, die ich dich hatte essen lassen, das setztest du ihnen als lieblich duftende Opfergabe vor. Ja, das alles ist geschehen!‹ – so lautet der Ausspruch Gottes des HERRN.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 20, '›Auch nahmst du deine Söhne und Töchter, die du mir geboren hattest, und schlachtetest sie ihnen zum Fraß. Genügte deine Buhlerei noch nicht,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 21, 'daß du auch noch meine Kinder schlachten mußtest und sie hingabst, indem du sie ihnen als Opfer verbranntest?');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 22, 'Und bei all deinen Greueln und deinen Buhlereien dachtest du nicht an die Tage deiner Jugend zurück, wie du damals nackt und bloß warst und zappelnd in deinem Blut dalagst!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 23, 'Und nach all deiner Bosheit – wehe, wehe dir!‹ – so lautet der Ausspruch Gottes des HERRN – ›kam es dahin,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 24, 'daß du dir erhöhte Opferplätze bautest und dir Götzenstätten auf jedem freien Platz anlegtest;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 25, 'an allen Straßenecken bautest du dir deine erhöhten Götzenstätten und schändetest deine Schönheit; denn für jeden Vorübergehenden spreiztest du deine Beine und triebst es mit deiner Unzucht immer ärger.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 26, 'Du buhltest mit den Ägyptern, deinen Nachbarn, den starkgliedrigen, und triebst es immer ärger mit deiner Unzucht, um mich zu erbittern.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 27, 'Da streckte ich denn meine Hand gegen dich aus und minderte den dir bestimmten Lebensunterhalt und gab dich der Gier deiner Feindinnen, der Töchter der Philister, preis, die sich ob deinem unzüchtigen Treiben schämten.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 28, 'Alsdann buhltest du auch mit den Assyrern, weil du nie satt wurdest; du buhltest mit ihnen, wurdest aber auch dadurch noch nicht gesättigt;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 29, 'vielmehr triebst du noch ärgere Buhlerei nach dem Krämerland Chaldäa hin; doch auch davon wurdest du nicht satt.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 30, 'Wie schmachtend war doch dein Herz‹ – so lautet der Ausspruch Gottes des HERRN –, ›daß du dies alles verübtest, wie es eine zügellose Erzbuhlerin zu tun pflegt!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 31, 'Daß du dir an jeder Straßenecke einen erhöhten Opferplatz anlegtest und dir Götzenstätten auf jedem freien Platze bautest! Und dabei warst du nicht einmal wie eine gewöhnliche Buhlerin, daß du Buhllohn eingesammelt hättest:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 32, 'du ehebrecherisches Weib, das statt ihres Ehemannes Fremde annahm!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 33, 'Sonst gibt man allen Dirnen Buhllohn; du aber gabst deinerseits allen deinen Liebhabern Geschenke und erkauftest sie, damit sie von allen Seiten zu dir eingingen, um Unzucht mit dir zu treiben.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 34, 'So war es bei dir in deiner Buhlerei umgekehrt wie sonst bei den Weibern: nicht dir stellte man buhlerisch nach, sondern, indem du Buhllohn gabst, während dir kein Lohn gegeben wurde, fand bei dir das Umgekehrte statt.‹«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 35, '»›Darum, du Buhlerin, vernimmt das Wort des HERRN!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 36, 'So spricht Gott der HERR: Weil deine Verworfenheit sich überallhin verbreitet hat, und du deine Blöße bei deinen Buhlereien vor deinen Liebhabern aufgedeckt hast, und wegen all deiner greulichen Götzen und um des Blutes deiner Kinder willen, die du ihnen hingegeben hast:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 37, 'darum will ich, wisse es wohl, alle deine Liebhaber, zu denen du in Liebe entbrannt warst, zusammenholen, und zwar alle, die du gern gehabt hast, samt allen denen, die dir zuwider geworden sind: die will ich von allen Seiten ringsum gegen dich zusammenholen und deine Blöße vor ihnen aufdecken, daß sie deine ganze Scham zu sehen bekommen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 38, 'Sodann will ich dir nach den für Ehebrecherinnen und Mörderinnen geltenden Rechtsbestimmungen das Urteil sprechen und meinen Grimm und meine Eifersucht an dir stillen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 39, 'Und ich will dich in ihre Gewalt geben, damit sie deine erhöhten Opferplätze niederreißen und deine Götzenstätten zerstören; und sie sollen dir deine Gewänder ausziehen und dir deine prächtigen Geschmeide wegnehmen und dich nackt und bloß hinstellen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 40, 'Dann werden sie eine Gemeindeversammlung gegen dich berufen und dich steinigen und dich mit ihren Schwertern in Stücke hauen;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 41, 'auch werden sie deine Häuser mit Feuer verbrennen und das Strafgericht an dir vollstrecken vor den Augen zahlreicher Frauen. So will ich deiner Buhlerei ein Ende machen, und du sollst fortan auch keinen Buhllohn mehr geben.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 42, 'Wenn ich so meinen Grimm an dir gestillt habe und meine Eifersucht gegen dich geschwunden ist, so werde ich mich beruhigt fühlen und mich nicht mehr zu entrüsten brauchen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 43, 'Weil du der Tage deiner Jugend nicht gedacht und mich durch dies alles zum Zorn gereizt hast, so will auch ich nunmehr die Strafe für dein Tun auf dein Haupt fallen lassen!‹ – so lautet der Ausspruch Gottes, des HERRN. ›Hast du etwa nicht Unzucht getrieben zu all deinen Greueln hinzu?‹«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 44, '»›Wahrlich, jeder, der sich der Sprichwörter bedient, wird auf dich den Spruch anwenden: Wie die Mutter, so die Tochter!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 45, 'Du bist wirklich die Tochter deiner Mutter, die ihres Mannes und ihrer Kinder überdrüssig geworden ist; und du bist wirklich die Schwester deiner Schwestern, die ihre Männer und ihre Kinder von sich gestoßen haben. Eure Mutter ist eine Hethiterin und euer Vater ein Amoriter gewesen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 46, 'Deine größere Schwester ist Samaria mit ihren Tochterstädten, die nördlich von dir wohnt; und deine kleinere Schwester, die südlich von dir wohnt, ist Sodom mit ihren Tochterstädten.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 47, 'Aber nicht auf ihren Wegen bist du gewandelt, und nicht Greuel wie sie hast du verübt; nein, nur ein kleines Weilchen hat es gedauert, da hast du es ärger als sie getrieben in all deinem Wandel.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 48, 'So wahr ich lebe!‹ – so lautet der Ausspruch Gottes des HERRN –, ›deine Schwester Sodom samt ihren Tochterstädten hat nicht so übel gehandelt, wie du es getan hast samt deinen Tochterstädten.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 49, 'Siehe, das war die Verschuldung deiner Schwester Sodom: Hoffart, Brot in Fülle und sorglose Ruhe war ihr samt ihren Tochterstädten eigen; aber den Armen und Notleidenden reichten sie niemals die Hand zur Hilfe,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 50, 'sondern sie wurden hochmütig und verübten Greuel vor meinen Augen; darum schaffte ich sie weg, sobald ich das sah.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 51, 'Auch Samaria hat nicht halb so viel gesündigt wie du, sondern du hast so viel mehr Greuel verübt als jene beiden, daß deine Schwestern dir gegenüber als gerecht erscheinen infolge all deiner Greuel, die du verübt hast.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 52, 'So trage nun auch du deine Schande, weil du für deine Schwestern ins Mittel getreten bist: infolge deiner Sünden, durch die du ärgere Greuel verübt hast als sie, stehen sie gerechter da als du. So schäme nun auch du dich und trage deine Schmach dafür, daß du deine Schwestern als gerecht hast erscheinen lassen.‹«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 53, '»›Ich werde aber ihr Schicksal wenden, das Schicksal Sodoms und ihrer Tochterstädte und das Schicksal Samarias und ihrer Tochterstädte, und dann auch dein eigenes Schicksal in ihrer Mitte,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 54, 'auf daß du deine Schmach trägst und dich alles dessen schämst, was du verübt hast, indem du ihnen dadurch Trost verschafftest.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 55, 'Wenn dann deine Schwester Sodom nebst ihren Tochterstädten und Samaria nebst ihren Tochterstädten wiederhergestellt worden sind, wie sie einst gewesen, so sollst auch du mit deinen Tochterstädten in den früheren Zustand zurückversetzt werden.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 56, 'War nicht der Name deiner Schwester Sodom als abschreckendes Beispiel in deinem Munde zur Zeit deines Hochmuts,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 57, 'ehe deine Blöße aufgedeckt wurde, wie (dies jetzt der Fall ist) jetzt, da die Töchter Syriens dich schmähen und alle Töchter der Philister dich ringsumher verachten?');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 58, 'Für deine Unzucht und deine Greuel mußt du nun die Strafe büßen!‹ – so lautet der Ausspruch Gottes des HERRN.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 59, '»Denn so spricht Gott der HERR: ›Ja, ich werde mit dir verfahren, wie du verfahren bist: du hast ja den Schwur mißachtet, indem du den Bund brachest.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 60, 'Doch ich will meines Bundes gedenken, den ich mit dir in den Tagen deiner Jugend geschlossen habe, und will einen ewigen Bund mit dir aufrichten.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 61, 'Da wirst du dann an dein ganzes Tun zurückdenken und dich seiner schämen, wenn ich deine Schwestern, sowohl die größeren als auch die kleineren, nehme und sie dir zu Töchtern gebe, allerdings nicht auf Grund des mit dir geschlossenen Bundes.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 62, 'Sondern ich will meinerseits einen Bund mit dir schließen, und du sollst erkennen, daß ich der HERR bin,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 63, 'damit du daran gedenkst und dich schämst und infolge deiner Schmach den Mund nicht mehr auftust, wenn ich dir alles vergeben habe, was du getan hast‹ – so lautet der Ausspruch Gottes des HERRN.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 17, 1, 'Weiter erging das Wort des HERRN an mich folgendermaßen:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 17, 2, '»Menschensohn, gib dem Hause Israel ein Rätsel auf und trage ihm ein Gleichnis vor!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 17, 3, 'Sage zu ihnen: ›So hat Gott der HERR gesprochen: Der große Adler mit großen Flügeln, mit langen Schwungfedern und voll schillernden Gefieders kam zum Libanon und nahm dort den Wipfel der Zeder weg:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 17, 4, 'den obersten ihrer Schosse riß er ab und brachte ihn ins Krämerland, versetzte ihn in eine Handelsstadt.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 17, 5, 'Dann nahm er einen von den Schößlingen des Landes, pflanzte ihn in ein Saatfeld, wo reichlich Wasser war, behandelte ihn wie ein Weidengewächs,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 17, 6, 'damit er dort wüchse und sich zu einem üppigen Weinstock von niedrigem Wuchs entwickelte; seine Ranken sollten sich zu ihm (dem Adler) hinkehren und seine Wurzeln ihm untertan sein. Und es wurde wirklich ein Weinstock daraus, der Ranken ansetzte und Zweige trieb.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 17, 7, 'Nun war da aber auch noch ein anderer großer Adler mit großen Flügeln und starkem Gefieder; und siehe da: jener Weinstock bog seine Wurzeln zu diesem hin und streckte seine Ranken zu ihm aus, damit er ihn noch besser tränken möchte, als das Beet es tat, auf das er gepflanzt war;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 17, 8, 'und er war doch auf guten Boden, an reichliches Wasser gepflanzt, um Ranken zu treiben und Früchte zu tragen und sich zu einem herrlichen Weinstock zu entwickeln.‹');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 17, 9, 'Sage nun zu ihnen: ›So hat Gott der HERR gesprochen: Wird das gut ablaufen? Wird jener (Adler) ihm nicht die Wurzeln ausreißen und seine Trauben abschneiden, so daß er verdorrt? Ja, alle seine frischsprossenden Triebe werden verdorren, und zwar wird kein gewaltiger Arm und keine große Anzahl von Leuten dazu erforderlich sein, um ihn aus seinem Wurzelboden herauszuheben.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 17, 10, 'Allerdings gepflanzt ist er: aber – wird es gut ablaufen? Wird er nicht, sobald der Ostwind ihn trifft, gänzlich verdorren? Ja, auf dem Beet, auf dem er herangewachsen ist, wird er verdorren.‹«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 17, 11, 'Alsdann erging das Wort des HERRN an mich folgendermaßen:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 17, 12, '»Sage doch dem widerspenstigen Geschlecht: ›Versteht ihr denn nicht, was dies bedeutet?‹ Sage ihnen: ›Seht, der König von Babylon ist nach Jerusalem gekommen, hat den dortigen König und die dortigen Oberen mitgenommen und sie zu sich nach Babylon gebracht.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 17, 13, 'Dann hat er einen Sprößling des Königshauses genommen und einen Vertrag mit ihm geschlossen und ihn durch einen Eid verpflichtet; die Vornehmsten des Landes aber hat er mit sich genommen,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 17, 14, 'damit die Königsmacht bescheiden bliebe und sich nicht wieder erhöbe und damit jener den geschlossenen Vertrag hielte, damit er Bestand habe.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 17, 15, 'Der aber fiel von ihm ab, indem er seine Gesandten nach Ägypten schickte, damit man ihm Rosse und viel Kriegsvolk gäbe. Wird er wohl Glück haben? Wird er, der so gehandelt hat, ungestraft davonkommen? Er hat den Vertrag gebrochen: sollte er der Strafe entgehen?');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 17, 16, 'So wahr ich lebe!‹ – so lautet der Ausspruch Gottes des HERRN –, ›an dem Wohnsitz des Königs, der ihn zum Herrscher gemacht, dem er den Eid nicht gehalten hat und gegen den er vertragsbrüchig geworden ist, bei diesem soll er sterben mitten in Babylon!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 17, 17, 'Der Pharao aber wird ihm nicht mit großer Heeresmacht und zahlreichem Aufgebot im Kriege Beistand leisten, wenn man einen Wall aufführt und Belagerungstürme baut, um viele Menschen ums Leben zu bringen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 17, 18, 'Denn weil er meineidig durch Vertragsbruch geworden ist und trotz des Handschlags, den er gegeben, alles dies getan hat, wird er nicht ungestraft davonkommen!‹«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 17, 19, 'Darum hat Gott der HERR so gesprochen: »So wahr ich lebe! Für den Eid, den er bei mir geschworen und mißachtet hat, und für den Vertrag, den er vor mir geschlossen und gebrochen hat, will ich ihn die Strafe büßen lassen');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 17, 20, 'und mein Fangnetz über ihn ausbreiten, so daß er in meinem Garn gefangen wird! Dann will ich ihn nach Babylon bringen und dort Abrechnung mit ihm halten wegen des Treubruchs, dessen er sich gegen mich schuldig gemacht hat.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 17, 21, 'Alle seine auserlesenen Krieger aber in allen seinen Heerscharen sollen durchs Schwert fallen und die Übriggebliebenen in alle Winde zerstreut werden, damit ihr erkennt, daß ich, der HERR, es angesagt habe.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 17, 22, 'So hat Gott der HERR gesprochen: »Ich selbst aber werde einen Zweig vom Wipfel der hohen Zeder nehmen und ihn einsetzen; von dem obersten ihrer Sprossen werde ich ein zartes Reis abbrechen, und ich selbst werde es auf einem hohen und ragenden Berge einpflanzen:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 17, 23, 'auf der Bergeshöhe Israels will ich es einpflanzen, damit es dort Zweige treibt und Früchte trägt und sich zu einer herrlichen Zeder entwickelt, unter welcher allerlei Wild lagert, allerlei Vögel jeglichen Gefieders wohnen und im Schatten ihrer Zweige nisten.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 17, 24, 'Dann werden alle Bäume des Feldes erkennen, daß ich, der HERR, den hohen Baum erniedrigt und den niedrigen Baum erhöht habe, daß ich den saftreichen Baum habe verdorren lassen und den dürren Baum zur Blüte gebracht habe. Ich, der HERR, habe es angesagt und es auch vollführt.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 18, 1, 'Weiter erging das Wort des HERRN an mich folgendermaßen:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 18, 2, '»Wie kommt ihr dazu, im Lande Israel diesen Spruch im Munde zu führen, daß ihr sagt: ›Die Väter haben saure Trauben gegessen, und den Söhnen werden die Zähne stumpf davon‹?');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 18, 3, 'So wahr ich lebe!« – so lautet der Ausspruch Gottes des HERRN –: »ihr sollt fortan diesen Spruch in Israel nicht mehr im Munde führen!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 18, 4, 'Bedenkt wohl: alle Seelen gehören mir, die Seele des Vaters so gut wie die des Sohnes – beide gehören mir: die Seele, die da sündigt, die soll sterben!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 18, 5, '»Wenn also jemand gerecht ist und Recht und Gerechtigkeit übt,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 18, 6, 'an den Opfermahlen auf den Bergen nicht teilnimmt und seine Augen nicht zu den Götzen des Hauses Israel erhebt, das Weib seines Nächsten nicht entehrt und einem Weibe zur Zeit ihrer Unreinheit nicht naht,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 18, 7, 'niemanden übervorteilt, dem Schuldner sein Pfand zurückgibt, sich keine Erpressung zuschulden kommen läßt, dem Hungrigen von seinem Brot abgibt und den Nackten mit Kleidung versieht,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 18, 8, 'kein Geld auf Wucher ausleiht und keine Zinsen nimmt, seine Hand vom Unrecht fernhält, in Streitsachen zwischen den Parteien der Wahrheit gemäß richtet,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 18, 9, 'nach meinen Satzungen wandelt und meine Gebote beobachtet, indem er sie getreulich erfüllt: der ist ein gerechter Mann, er soll gewißlich am Leben bleiben!« – so lautet der Ausspruch Gottes des HERRN.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 18, 10, '»Ist er nun aber Vater eines gewalttätigen Sohnes, der Blut vergießt und eine von jenen Sünden begeht –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 18, 11, 'während jener dies alles nicht getan hat –, wenn er sogar an den Opfermahlen auf den Bergen teilnimmt und das Weib seines Nächsten entehrt,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 18, 12, 'den Armen und Notleidenden übervorteilt, Erpressung verübt, Gepfändetes nicht zurückgibt und seine Augen zu den Götzen erhebt, Abscheuliches begeht,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 18, 13, 'Geld auf Wucher ausleiht und Zinsen nimmt: sollte ein solcher Mensch am Leben bleiben? Nein, er soll nicht am Leben bleiben! Weil er alle diese Abscheulichkeiten verübt hat, soll er unfehlbar den Tod erleiden: die Strafe für seine Blutschuld soll ihn treffen!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 18, 14, '»Wenn der nun aber Vater eines Sohnes ist, der alle Sünden sieht, die sein Vater begeht, und, obgleich er sie sieht, dennoch nicht ebenso handelt:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 18, 15, 'er nimmt nicht teil an den Opfermahlen auf den Bergen und erhebt seine Augen nicht zu den Götzen des Hauses Israel, er entehrt nicht das Weib seines Nächsten');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 18, 16, 'und übervorteilt niemand, er läßt sich kein Pfand geben und verübt keine Erpressung, er gibt dem Hungrigen von seinem Brot ab und versieht den Nackten mit Kleidung,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 18, 17, 'er hält seine Hand vom Unrecht fern, leiht kein Geld auf Wucher aus und nimmt keine Zinsen, er beobachtet meine Satzungen und wandelt nach meinen Geboten: der soll wegen der Verschuldung seines Vaters nicht sterben, sondern sicherlich am Leben bleiben.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 18, 18, 'Sein Vater aber, der Bedrückung verübt und Erpressung am Bruder begangen und inmitten seiner Volksgenossen nicht gut gehandelt hat: fürwahr, der soll wegen seiner Verschuldung sterben!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 18, 19, 'Wenn ihr aber fragt: ›Warum soll der Sohn die Schuld seines Vaters nicht mittragen?‹, so bedenkt wohl: Der Sohn hat doch Recht und Gerechtigkeit geübt, hat alle meine Satzungen beobachtet und nach ihnen gehandelt: darum soll er am Leben bleiben!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 18, 20, 'Ein jeder, der Sünde tut, der soll sterben; aber der Sohn soll die Schuld seines Vaters nicht mittragen und der Vater nicht die Schuld seines Sohnes; nein, dem Gerechten soll der Lohn für seine Gerechtigkeit zuteil werden und ebenso dem Gottlosen die Strafe für seine Gottlosigkeit!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 18, 21, '»Bekehrt sich jedoch der Gottlose von all seinen Sünden, die er begangen hat, und beobachtet er alle meine Satzungen und übt er Recht und Gerechtigkeit, so soll er gewißlich am Leben bleiben, soll nicht sterben!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 18, 22, 'Keine von allen Sünden, die er begangen hat, soll ihm noch angerechnet werden: um der Gerechtigkeit willen, die er geübt hat, soll er am Leben bleiben.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 18, 23, 'Habe ich etwa Wohlgefallen am Tode des Gottlosen?« – so lautet der Ausspruch Gottes des HERRN – »und nicht vielmehr daran, daß er sich von seinem bösen Wandel bekehrt und am Leben bleibt?');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 18, 24, 'Wenn aber ein Gerechter sich von seiner Gerechtigkeit abwendet und Böses verübt, alle die Abscheulichkeiten begeht, die der Gottlose zu verüben pflegt: sollte er da am Leben bleiben? Nein, keine von all seinen gerechten Taten, die er vollbracht hat, soll ihm angerechnet werden: um des Treubruchs willen, dessen er sich schuldig gemacht, und wegen der Sünde, die er begangen hat, ihretwegen soll er sterben!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 18, 25, 'Wenn ihr nun sagt: ›Das Verfahren des Herrn ist nicht das richtige!‹, so hört doch, ihr vom Hause Israel! Sollte wirklich mein Verfahren nicht das richtige sein? Ist nicht vielmehr euer Verfahren unrichtig?');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 18, 26, 'Wenn der Gerechte sich von seiner Gerechtigkeit abwendet und Böses verübt, so muß er deswegen sterben: wegen des Bösen, das er begangen hat, deswegen muß er sterben.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 18, 27, 'Wenn sich dagegen der Gottlose von der Gottlosigkeit, die er begangen hat, abwendet und Recht und Gerechtigkeit übt, so wird ein solcher Mensch seine Seele am Leben erhalten.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 18, 28, 'Wenn er zur Einsicht kommt und von allen Übertretungen, deren er sich schuldig gemacht hat, abläßt, so soll er gewißlich das Leben behalten und nicht sterben!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 18, 29, 'Wenn also das Haus Israel sagt: ›Das Verfahren des Herrn ist nicht das richtige‹ – sollte wirklich mein Verfahren nicht das richtige sein, Haus Israel? Ist nicht vielmehr euer Verfahren unrichtig?«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 18, 30, '»Darum werde ich einen jeden von euch, ihr vom Hause Israel, nach seinem Wandel richten« – so lautet der Ausspruch Gottes des HERRN. »Kehrt um und wendet euch von all euren Übertretungen ab, damit sie euch nicht weiter ein Anlaß zur Verschuldung werden!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 18, 31, 'Werft alle eure Übertretungen, durch die ihr euch gegen mich vergangen habt, von euch ab und schafft euch ein neues Herz und einen neuen Geist! Denn warum wollt ihr sterben, Haus Israel?');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 18, 32, 'Ich habe ja kein Wohlgefallen am Tode dessen, der sterben muß« – so lautet der Ausspruch Gottes des HERRN –; »darum bekehrt euch, so werdet ihr leben!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 19, 1, '»Du aber stimme ein Klagelied an über die Fürsten Israels');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 19, 2, 'und sprich: ›Wie war doch deine Mutter eine Löwin unter Löwen! Sie hatte ihr Lager inmitten von Jungleuen, zog ihre Jungen groß.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 19, 3, 'Eins von ihren Jungen brachte sie hoch, zum Jungleu wurde es; der lernte Raub erbeuten, Menschen fraß er.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 19, 4, 'Da erließen die Völker einen Aufruf gegen ihn: in ihrer Grube wurde er gefangen, und sie brachten ihn mit Ringen nach dem Lande Ägypten. –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 19, 5, 'Als nun seine Mutter sah, daß sie getäuscht, ihre Hoffnung vernichtet war, da nahm sie ein anderes von ihren Jungen und machte es zu einem Jungleu.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 19, 6, 'Der schritt stolz unter den Löwen einher, wurde ein Jungleu; er lernte Raub erbeuten, Menschen fraß er.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 19, 7, 'Er machte ihre Witwen zahlreich und entvölkerte ihre Städte, so daß das Land und alles, was darin war, sich vor seinem dröhnenden Gebrüll entsetzte.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 19, 8, 'Da stellten sich die Völker ringsum aus den Landschaften gegen ihn auf und breiteten ihr Netz über ihn aus: in ihrer Grube wurde er gefangen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 19, 9, 'Dann taten sie ihn an Nasenringen in einen Käfig und brachten ihn zum König von Babylon, brachten ihn in eine der Burgen, damit man sein Gebrüll auf den Bergen Israels nicht mehr höre.‹«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 19, 10, '»›Deine Mutter war wie ein Weinstock, im Weingarten am Wasser gepflanzt, reich an Früchten und voller Ranken infolge des reichlichen Wassers;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 19, 11, 'an ihm wuchs ein starker Schoß zum Herrscherstabe, und hoch ragte sein Wuchs empor zwischen dem dichten Laubwerk, und er war weithin sichtbar durch seine Höhe, durch die Fülle seiner Ranken.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 19, 12, 'Da wurde er im Grimm ausgerissen, auf die Erde geworfen, und der Ostwind dörrte seine Ranken aus; sein starker Schoß wurde abgerissen und verdorrte, Feuer hat ihn verzehrt.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 19, 13, 'Jetzt ist er in die Wüste verpflanzt, in dürres, lechzendes Land;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 19, 14, 'und Feuer ist von seinem Schoß ausgegangen, hat seine Ranken verzehrt; und es ist an ihm kein starker Schoß mehr geblieben, kein Stab zum Herrschen.‹« Ein Klagelied ist dies, und es ist zum Klagelied geworden.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 1, 'Im siebten Jahre, am zehnten Tage des fünften Monats, kamen einige von den Ältesten Israels, um den HERRN zu befragen, und sie ließen sich vor mir nieder.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 2, 'Da erging das Wort des HERRN an mich folgendermaßen:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 3, '»Menschensohn, sprich zu den Ältesten Israels und sage zu ihnen: ›So hat Gott der HERR gesprochen: Mich zu befragen seid ihr gekommen? So wahr ich lebe: ich lasse mich von euch nicht befragen!‹ – so lautet der Ausspruch Gottes des HERRN.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 4, 'Willst du ihnen nicht vielmehr das Urteil sprechen? Willst du mit ihnen nicht ins Gericht gehen, Menschensohn? Halte ihnen die Greueltaten ihrer Väter vor!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 5, '»Sage zu ihnen: ›So hat Gott der HERR gesprochen: An dem Tage, als ich Israel erwählte, erhob ich meine Hand für die Angehörigen des Hauses Jakob zum Schwur und gab mich ihnen im Lande Ägypten zu erkennen; ich erhob meine Hand für sie zum Schwur und sprach: Ich bin der HERR, euer Gott!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 6, 'An demselben Tage erhob ich meine Hand und schwur ihnen, daß ich sie aus dem Lande Ägypten in ein Land führen würde, das ich für sie ausersehen hätte, das von Milch und Honig überfließe und die Krone unter allen Ländern sei.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 7, 'Dabei gebot ich ihnen: Ein jeder von euch werfe die Scheusale weg, auf die er bisher seine Augen gerichtet hat, und verunreinigt euch nicht an den ägyptischen Götzen! Ich, der HERR, bin euer Gott!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 8, 'Aber sie waren widerspenstig gegen mich und wollten nicht auf mich hören; keiner von ihnen warf die Scheusale weg, auf die er bisher seine Augen gerichtet hatte, und die ägyptischen Götzen ließen sie nicht fahren. Da gedachte ich meinen Grimm über sie auszugießen, meinen ganzen Zorn mitten im Lande Ägypten an ihnen auszulassen;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 9, 'aber ich nahm Rücksicht auf meinen Namen, damit dieser nicht entehrt würde vor den Augen der Heidenvölker, unter denen sie wohnten und vor deren Augen ich mich ihnen geoffenbart hatte, um sie aus dem Lande Ägypten wegzuführen.‹«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 10, '»›So führte ich sie denn aus dem Lande Ägypten weg und brachte sie in die Wüste.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 11, 'Da gab ich ihnen meine Satzungen und lehrte sie meine Gebote kennen, durch deren Beobachtung der Mensch das Leben hat.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 12, 'Auch meine Sabbate gab ich ihnen, die ein Zeichen (des Bundes) zwischen mir und ihnen sein sollten, damit sie zur Erkenntnis kämen, daß ich, der HERR, es bin, der sie heiligt.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 13, 'Aber das Haus Israel war auch in der Wüste widerspenstig gegen mich: sie wandelten nicht nach meinen Satzungen und mißachteten meine Gebote, durch deren Beobachtung doch der Mensch das Leben hat; auch meine Sabbate hielten sie durchaus nicht heilig. Da gedachte ich meinen Grimm in der Wüste über sie auszugießen, um sie ganz auszurotten;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 14, 'aber ich nahm Rücksicht auf meinen Namen, damit er nicht entehrt würde vor den Augen der Heidenvölker, vor deren Augen ich sie weggeführt hatte.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 15, 'Doch erhob ich meine Hand in der Wüste und schwur ihnen, daß ich sie nicht in das verheißene Land bringen würde, ein Land, das von Milch und Honig überfließe und die Krone unter allen Ländern sei,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 16, 'weil sie meine Gebote mißachtet und nicht nach meinen Satzungen gewandelt und meine Sabbate entheiligt hätten; denn ihr Herz war immer nur hinter ihren Götzen her.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 17, 'Dennoch blickte mein Auge mitleidsvoll auf sie, so daß ich sie nicht vernichtete und sie in der Wüste nicht völlig ausrottete.‹«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 18, '»›Da gebot ich ihren Söhnen in der Wüste: Wandelt nicht nach den Gewohnheiten eurer Väter und beobachtet nicht die von ihnen geübten Bräuche und verunreinigt euch nicht an ihren Götzen!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 19, 'Ich, der HERR, bin euer Gott: wandelt nach meinen Satzungen, beobachtet meine Gebote und handelt nach ihnen!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 20, 'Haltet auch meine Sabbate heilig, damit sie ein Zeichen (des Bundes) zwischen mir und euch seien und damit man erkenne, daß ich der HERR, euer Gott, bin.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 21, 'Aber auch die Söhne waren widerspenstig gegen mich: sie wandelten nicht nach meinen Satzungen und befolgten meine Gebote nicht, daß sie nach ihnen gehandelt hätten, obgleich doch der Mensch durch ihre Beobachtung das Leben hat; auch meine Sabbate entheiligten sie. Da gedachte ich meinen Grimm über sie auszugießen und meinen Zorn in der Wüste an ihnen völlig auszuwirken;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 22, 'aber ich zog meine Hand wieder zurück und nahm Rücksicht auf meinen Namen, damit er nicht entehrt würde vor den Augen der Heidenvölker, vor deren Augen ich sie ausgeführt hatte.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 23, 'Doch erhob ich meine Hand in der Wüste und schwur ihnen, daß ich sie unter die Heidenvölker zerstreuen und sie in die Länder versprengen würde,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 24, 'weil sie nicht nach meinen Geboten lebten, meine Satzungen mißachteten, meine Sabbate nicht heilig hielten und weil ihre Augen auf die Götzen ihrer Väter gerichtet seien.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 25, 'So gab denn auch ich ihnen Satzungen, die nicht zum Guten waren, und Gebote, durch die sie nicht das Leben haben konnten;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 26, 'ich machte sie durch ihre Opfergaben unrein, dadurch daß sie jegliche Erstgeburt als Opfer verbrannten: ich wollte ihnen eben Entsetzen einflößen, damit sie erkennen möchten, daß ich der HERR bin.‹«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 27, '»Darum, Menschensohn, rede zum Hause Israel und sage zu ihnen: ›So hat Gott der HERR gesprochen: Auch noch dadurch haben eure Väter mich beschimpft, daß sie mir die Treue gebrochen haben.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 28, 'Nachdem ich sie nämlich in das Land gebracht hatte, dessen Verleihung ich ihnen zugeschworen hatte, da schlachteten sie, wo immer sie einen hohen Hügel und einen dichtbelaubten Baum erblickt hatten, daselbst ihre Opfertiere, brachten dort ihre Gaben zu meiner Kränkung dar, ließen daselbst ihre lieblichen Weihrauchdüfte aufsteigen und gossen dort ihre Trankopfer aus.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 29, '[Da fragte ich sie: Was ist das für eine Höhe, auf die ihr euch da begebt? Daher ist der Name ›Höhe‹ geblieben bis auf den heutigen Tag.]‹«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 30, '»Darum sage zum Hause Israel: ›So hat Gott der HERR gesprochen: Wie? Nach der Weise eurer Väter wollt auch ihr euch verunreinigen und mit ihren Scheusalen ebenfalls Buhlerei treiben?');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 31, 'Ja, dadurch, daß ihr eure Gaben darbringt, daß ihr eure Kinder als Opfer verbrennt, verunreinigt ihr euch an all euren Götzen bis auf den heutigen Tag; und da sollte ich mich von euch befragen lassen, Haus Israel? So wahr ich lebe!‹ – so lautet der Ausspruch Gottes des HERRN –: ›ich will mich von euch nicht befragen lassen!‹«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 32, '»›Und das, was euch in den Sinn gekommen ist, darf nimmermehr zur Ausführung gelangen, daß ihr sagt: Wir wollen es machen wie die Heiden, wie die Völker in den anderen Ländern, indem wir Holz und Stein anbeten!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 33, 'So wahr ich lebe!‹ – so lautet der Ausspruch Gottes des HERRN –: ›Mit starker Hand und hocherhobenem Arm und so, daß ich meinem Ingrimm freien Lauf lasse, will ich mich als König über euch erweisen!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 34, 'Ich will euch aus den Heidenvölkern herausführen und euch aus den Ländern sammeln, in die ihr zerstreut worden seid, mit starker Hand und hocherhobenem Arm und so, daß ich meinem Ingrimm freien Lauf lasse,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 35, 'und will euch in die Wüste inmitten der Völker bringen und dort ins Gericht mit euch gehen von Angesicht zu Angesicht!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 36, 'Wie ich einst in der Wüste des Landes Ägypten mit euren Vätern ins Gericht gegangen bin, ebenso will ich auch über euch Gericht halten!‹ – so lautet der Ausspruch Gottes des HERRN.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 37, '›Da will ich euch unter meinem Stabe an mir vorübergehen lassen und euch zur Erfüllung der Bundespflichten zwingen,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 38, 'und ich will die Ungehorsamen und die von mir Abgefallenen aus euch aussondern: aus dem Lande, in dem sie als Fremdlinge gelebt haben, will ich sie herausführen; aber auf Israels Boden soll keiner von ihnen zurückkehren, damit ihr erkennt, daß ich der HERR bin!‹«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 39, '»Was euch aber betrifft, ihr vom Hause Israel, so hat Gott der HERR folgendermaßen gesprochen: ›Geht nur hin und dient ein jeder seinen Götzen! Später aber werdet ihr sicherlich auf mich hören und meinen heiligen Namen nicht länger durch eure Opfergaben und durch eure Götzen entweihen,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 40, 'sondern auf meinem heiligen Berge, auf Israels Bergeshöhe‹ – so lautet der Ausspruch Gottes des HERRN –, ›dort wird mir das ganze Haus Israel dienen, alle, die sich im Lande befinden; dort will ich euch gnädig annehmen und dort eure Hebeopfer und eure Erstlingsgaben mir darbringen lassen, alles, was ihr an Weihegaben opfert.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 41, 'Beim lieblichen Opferduft will ich euch gnädig annehmen, wenn ich euch aus den Heidenvölkern herausführe und euch aus den Ländern sammle, in die ihr zerstreut worden seid, und ich will mich an euch vor den Augen der Heidenvölker als den Heiligen erweisen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 42, 'Da werdet ihr dann erkennen, daß ich der HERR bin, wenn ich euch in das Land Israel zurückführe, in das Land, dessen Verleihung ich euren Vätern einst durch einen Schwur zugesagt habe.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 43, 'Dort werdet ihr dann an euren Wandel und all eure Taten zurückdenken, durch die ihr euch verunreinigt habt, und werdet einen Abscheu vor euch selbst empfinden wegen all des Bösen, das ihr begangen habt.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 44, 'Dann werdet ihr auch erkennen, daß ich der HERR bin, wenn ich so mit euch verfahre um meines Namens willen und nicht nach eurem bösen Wandel und nach euren verwerflichen Taten, Haus Israel!‹ – so lautet der Ausspruch Gottes des HERRN.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 21, 1, 'Weiter erging das Wort des HERRN an mich folgendermaßen:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 21, 2, '»Menschensohn, richte deine Blicke nach Süden zu, predige gegen Mittag hin und weissage gegen den Wald, der im Gefilde des Südlandes liegt,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 21, 3, 'und sprich zu dem Walde im Südland: ›Höre das Wort des HERRN! So hat Gott der HERR gesprochen: Siehe, ich will ein Feuer in dir anzünden, das soll alle saftreichen und alle dürren Bäume in dir verzehren; die lodernde Flamme soll nicht erlöschen, und alle Gesichter vom Südland bis zum Norden sollen durch sie versengt werden!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 21, 4, 'Dann wird alles Fleisch einsehen, daß ich, der HERR, sie angezündet habe, indem sie nicht erlischt.‹«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 21, 5, 'Da entgegnete ich: »Ach, HERR, mein Gott! Die Leute sagen von mir: ›Trägt der nicht immer Rätselreden vor?‹«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 21, 6, 'Da erging das Wort des HERRN an mich folgendermaßen:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 21, 7, '»Menschensohn, richte deine Blicke auf Jerusalem, predige gegen ihr Heiligtum und weissage gegen das Land Israel!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 21, 8, 'Sage zum Lande Israel: ›So hat der HERR gesprochen: Siehe, ich will an dich! Ich will mein Schwert aus der Scheide ziehen und Gerechte wie Gottlose in dir ausrotten!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 21, 9, 'Weil ich beide, Gerechte wie Gottlose, in dir ausrotten will, darum soll mein Schwert aus der Scheide fahren gegen alles Fleisch vom Südland bis zum Norden.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 21, 10, 'Dann wird alle Welt erkennen, daß ich, der HERR, mein Schwert aus der Scheide habe herausfahren lassen, und es nicht wieder dahin zurückkehrt.‹«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 21, 11, '»Du aber, Menschensohn, seufze! Mit zusammenbrechenden Hüften und in bitterem Schmerz seufze vor ihren Augen!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 21, 12, 'Wenn sie dich dann fragen, worüber du seufzest, so antworte ihnen: ›Über eine Schreckenskunde! Bei ihrem Eintreffen werden alle Herzen verzagen und alle Arme schlaff herabhängen; aller Mut wird schwinden, und alle Knie werden wie Wasser zerfließen.‹ Fürwahr, es kommt und geht in Erfüllung!« – so lautet der Ausspruch Gottes des HERRN.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 21, 13, 'Hierauf erging das Wort des HERRN an mich folgendermaßen:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 21, 14, '»Menschensohn, verkünde folgende Weissagung: So hat der HERR gesprochen: Sprich zu ihnen: ›Ein Schwert, ein Schwert ist geschärft und auch gefegt;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 21, 15, 'um ein Schlachten anzurichten, dazu ist es geschärft: damit es blitzt und blinkt, dazu ist es gefegt. Oder sollen wir uns freuen? Die für meinen Sohn bestimmte Rute verachtet alles Holz.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 21, 16, 'Er hat es zum Fegen hingegeben, um es in die Hand zu nehmen; es ist geschärft worden, das Schwert, und gefegt, damit man es dem Würger in die Hand gebe.‹');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 21, 17, 'Schreie und wehklage, Menschensohn! Denn dieses Schwert richtet sich gegen mein Volk, richtet sich gegen alle Fürsten Israels: dem Schwert verfallen sind sie samt meinem Volk! Darum schlage dich auf die Hüften,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 21, 18, 'denn die Probe ist gemacht! Aber wie, wenn die Rute selber (das Dreinhauen) verschmäht? Es soll nicht geschehen!« – lautet der Ausspruch Gottes des HERRN.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 21, 19, '»Du aber, Menschensohn, weissage und schlage die Hände zusammen! Denn das Schwert wird zweifach, ja dreifach kommen. Ein Mordschwert ist es, ein großes Mordschwert, das sie umkreisen soll,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 21, 20, 'damit ihre Herzen verzagen und viele tot hinstürzen an all ihren Toren. Ich lasse blinken das Schwert. Wehe! Zum Blitzen ist es gefertigt, zum Schlachten geschärft!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 21, 21, 'Setze in Schrecken, fahre nach rechts, kehre dich nach links, wohin eben deine Schneide gerichtet ist!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 21, 22, 'So will denn auch ich meine Hände zusammenschlagen und meinem Zorn freien Lauf lassen: ich, der HERR, habe es gesprochen!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 21, 23, 'Darauf erging das Wort des HERRN an mich folgendermaßen:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 21, 24, '»Du aber, Menschensohn, stelle dir zwei Wege dar, auf denen das Schwert des Königs von Babylon kommen soll: von einem Lande sollen sie beide ausgehen. Dann stelle einen Wegweiser auf am Anfang des Weges nach der einen wie nach der anderen Stadt,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 21, 25, 'damit das Schwert sowohl über Rabbath im Ammoniterlande als auch über Juda und Jerusalem in dessen Mitte kommen kann.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 21, 26, 'Denn der König von Babylon steht am Scheidewege, am Anfang der beiden Wege, um eine Offenbarung zu erhalten: er schüttelt die Pfeile, befragt die Hausgötter und beschaut die Leber.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 21, 27, 'In seiner Rechten ist das Los ›Jerusalem‹, daß er den Mund auftue zum Kriegsgeschrei, lauten Schlachtruf erschallen lasse, Sturmböcke gegen die Tore aufstelle, einen Wall aufschütte und Belagerungstürme baue.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 21, 28, 'Freilich scheint das ihnen eine trügerische Wahrsagung zu sein, da sie ja die feierlichsten Eide geschworen haben; doch er bringt ihre Verschuldung (bei sich) in Erinnerung, damit sie gefangen werden.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 21, 29, 'Darum hat Gott der HERR so gesprochen: »Weil ihr mich an eure Verschuldung erinnert habt dadurch, daß eure Übertretungen aufgedeckt worden sind, so daß eure Sünden in all eurem Tun klar zu Tage liegen – ja, weil ihr euch so in Erinnerung gebracht habt, sollt ihr um ihretwillen ergriffen werden.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 21, 30, 'Du aber, verruchter Frevler, Fürst Israels, dessen Tag gekommen ist zur Zeit, wo seine Schuld endgültig gebüßt wird –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 21, 31, 'so hat Gott der HERR gesprochen: ›Hinweg mit der Königsbinde! Herunter mit der Krone! Das bleibt nicht so, wie es jetzt ist! Das Niedrige soll erhöht werden, und das Hohe muß herunter!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 21, 32, 'Zu Trümmern, Trümmern, Trümmern will ich (alles) machen! Wehe ihm! So soll es bleiben, bis der kommt, der das Anrecht darauf hat: dem will ich es übergeben.‹«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 21, 33, '»Du aber, Menschensohn, verkünde folgende Weissagung: So hat Gott der HERR in betreff der Ammoniter und in betreff ihrer Hohnreden gesprochen! Verkünde: ›Ein Schwert, ein Schwert ist gezückt zum Schlachten, ist gefegt zum Blinken, damit es blitze –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 21, 34, 'während man dich durch nichtige Gesichte getäuscht und dir Lügen gewahrsagt hat –, um es verruchten Frevlern an den Hals zu setzen, deren Tag kommt zu der Zeit, wo ihre Schuld endgültig gebüßt wird.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 21, 35, 'Stecke das Schwert wieder in seine Scheide! An dem Orte, wo du geschaffen bist, im Lande, aus dem du stammst, will ich dich richten');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 21, 36, 'und will meinen Zorn sich über dich ergießen lassen, das Feuer meines Ingrimms gegen dich anfachen und dich der Gewalt tierischer Menschen preisgeben, die Verderben (für dich) schmieden.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 21, 37, 'Dem Feuer sollst du zum Fraß dienen, dein Blut soll inmitten deines Landes vergossen liegen, deiner soll nicht mehr gedacht werden; denn ich, der HERR, habe gesprochen!‹«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 22, 1, 'Weiter erging das Wort des HERRN an mich folgendermaßen:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 22, 2, '»Du, Menschensohn, willst du nicht der blutbefleckten Stadt das Urteil sprechen? Willst du sie nicht richten? Halte ihr alle ihre Greuel vor');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 22, 3, 'mit den Worten: ›So hat Gott der HERR gesprochen: Wehe der Stadt, die Blut in ihrer Mitte vergossen hat, damit ihre Zeit herbeikomme, und die sich zu ihrem Unheil Götzen angefertigt hat, um sich zu verunreinigen!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 22, 4, 'Durch dein Blut, das du vergossen, hast du dich mit Schuld beladen, und durch deine Götzen, die du dir angefertigt hast, bist du unrein geworden; du hast die Tage deines Gerichts nahe herangebracht und bist zum Abschluß deiner Jahre gekommen. Darum mache ich dich zum Hohn für die Völker und zum Spott für alle Länder.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 22, 5, 'Mögen sie in deiner Nähe oder fern von dir wohnen, sie werden dich verspotten, weil dein Ruf befleckt ist und überall Verwirrung in dir herrscht.‹«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 22, 6, '»›Siehe, die Fürsten Israels in deiner Mitte sind alle, soviel ein jeder mit seiner Faust vermochte, beflissen gewesen, Blut zu vergießen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 22, 7, 'Vater und Mutter verachtet man in dir, den Fremdling behandelt man gewalttätig in deiner Mitte, Waisen und Witwen bedrückt man in dir.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 22, 8, 'Was mir heilig ist, mißachtest du, und meine Sabbate entweihst du.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 22, 9, 'Verleumder weilen in dir, die auf Blutvergießen ausgehen, und auf den Bergen hält man bei dir Opfermahle, Unzucht verübt man in deiner Mitte.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 22, 10, 'Man treibt Unzucht in dir mit dem Weibe des Vaters und mißbraucht in dir die vom Blutgang unreinen Frauen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 22, 11, 'Ein jeder treibt Ehebruch mit der Frau seines Nächsten; ein anderer lebt in Blutschande mit seiner Schwiegertochter, der andere schändet in dir seine Schwester, die Tochter seines Vaters.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 22, 12, 'Bestechungsgeschenke nimmt man in dir an, um Blut zu vergießen; du treibst Wucher und läßt dir Zinsen zahlen und übervorteilst deinen Nächsten durch Erpressung; mich aber hast du vergessen!‹ – so lautet der Ausspruch Gottes des HERRN.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 22, 13, '›Aber wisse wohl: ich schlage meine Hände zusammen über den unredlichen Gewinn, den du gemacht hast, und über deine Bluttaten, die in deiner Mitte begangen sind.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 22, 14, 'Wird wohl dein Herz standhalten, oder werden deine Hände stark bleiben zu der Zeit, wo ich mit dir ins Gericht gehen werde? Ich, der HERR, habe es angesagt und werde es auch vollführen!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 22, 15, 'Denn ich werde dich unter die Völker zerstreuen und dich in die Länder versprengen und deine Unreinheit gänzlich aus dir wegschaffen,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 22, 16, 'damit du durch eigene Schuld entehrt vor den Augen der Heidenvölker dastehst; dann wirst du zu der Erkenntnis kommen, daß ich der HERR bin.‹«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 22, 17, 'Weiter erging das Wort des HERRN an mich folgendermaßen:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 22, 18, '»Menschensohn, die vom Hause Israel sind für mich zu Schlacken geworden; sie sind alle wie Kupfer und Zinn, Eisen und Blei: Silberschlacken sind sie geworden!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 22, 19, 'Darum hat Gott der HERR so gesprochen: »Weil ihr alle zu Schlacken geworden seid, darum will ich euch nunmehr inmitten Jerusalems zusammenbringen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 22, 20, 'Wie man Silber und Kupfer, Eisen, Blei und Zinn im Schmelzofen zusammentut, um Feuer darunter anzufachen, damit es zum Schmelzen gebracht wird, so will ich euch in meinem Zorn und Grimm zusammentun und euch hineinlegen und zum Schmelzen bringen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 22, 21, 'Versammeln will ich euch und das Feuer meines Ingrimms gegen euch anfachen, daß ihr darin geschmolzen werden sollt.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 22, 22, 'Wie man Silber im Schmelzofen schmelzt, so sollt ihr in der Stadt geschmolzen werden, damit ihr erkennt, daß ich, der HERR, meinen Grimm über euch ausgegossen habe!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 22, 23, 'Weiter erging das Wort des HERRN an mich folgendermaßen:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 22, 24, '»Menschensohn, sage zu ihm: ›Du bist ein Land, das nicht benetzt, nicht beregnet worden ist in der Zeit des Grolls,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 22, 25, 'dessen Fürsten in ihm wie ein brüllender und beutegieriger Löwe gewesen sind: sie haben Menschenleben gefressen, Reichtum und Kostbarkeiten an sich gebracht, die Zahl der Witwen in ihm gemehrt.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 22, 26, 'Seine Priester haben meinem Gesetz Gewalt angetan und das, was mir heilig ist, entweiht; zwischen Heiligem und Unheiligem haben sie keinen Unterschied gemacht und das, was rein und unrein ist, nicht zu unterscheiden gelehrt; vor meinen Sabbaten aber haben sie ihre Augen geschlossen, so daß ich unter ihnen nicht mehr als heilig gelte.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 22, 27, 'Ihre Fürsten sind in ihrer Mitte wie beutegierige Wölfe: sie gehen darauf aus, Blut zu vergießen und Menschenleben zu vernichten, um Gewinn zu erraffen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 22, 28, 'Ihre Propheten aber überstreichen ihnen alles mit Tünche, indem sie erdichtete Gesichte schauen und ihnen Lügen wahrsagen mit der Versicherung: So hat Gott der HERR gesprochen!, während doch der HERR gar nicht geredet hat.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 22, 29, 'Das Volk im Lande verübt Gewalttätigkeit und begeht Raub, bedrückt die Armen und Elenden und übervorteilt die Fremdlinge gegen alles Recht.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 22, 30, 'Ich habe unter ihnen nach einem Manne gesucht, der eine Mauer aufführen könnte und vor mir für das Land in den Riß treten möchte, damit ich es nicht zu Grunde richtete, aber ich habe keinen gefunden.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 22, 31, 'Da habe ich denn meinen Zorn sich über sie ergießen lassen, habe sie durch das Feuer meines Grimms vernichtet und die Strafe für ihren Wandel auf ihr Haupt fallen lassen!‹« – so lautet der Ausspruch Gottes des HERRN.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 1, 'Hierauf erging das Wort des HERRN an mich folgendermaßen:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 2, '»Menschensohn, es waren zwei Frauen, Töchter derselben Mutter,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 3, 'die trieben Unzucht in Ägypten und buhlten schon in ihrer Jugend; sie ließen dort ihre Brüste drücken, und dort betastete man ihnen den jungfräulichen Busen:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 4, 'die ältere hieß Ohola und ihre Schwester Oholiba. Sie wurden beide mein und wurden Mütter von Söhnen und Töchtern; und was ihre Namen betrifft: Ohola ist Samaria, und Oholiba ist Jerusalem.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 5, '»Ohola aber trieb Buhlerei, obgleich sie mein Weib war, und entbrannte in Liebe zu ihren Liebhabern, zu den Assyrern, die zu ihr kamen,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 6, 'gekleidet in blauen Purpur, Statthalter und Befehlshaber, lauter schmucke Jünglinge, Reiter hoch zu Roß.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 7, 'An diese machte sie sich mit ihren Buhlkünsten, an alle auserlesenen Assyrer, und befleckte sich mit allen, für die sie in Liebe entbrannt war, mit deren gesamtem Götzendienst.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 8, 'Dabei gab sie aber auch ihr unzüchtiges Treiben mit den Ägyptern nicht auf; denn die hatten ihr schon in ihrer Jugend beigewohnt und ihren jungfräulichen Busen betastet und in Unzucht mit ihr gelebt.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 9, 'Darum gab ich sie der Gewalt ihrer Buhlen preis, der Gewalt der Assyrer, in die sie leidenschaftlich verliebt war.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 10, 'Die deckten ihre Blöße auf, nahmen ihre Söhne und Töchter mit sich weg und brachten sie selbst mit dem Schwerte um, so daß sie zum Gerede für die Frauen wurde, nachdem man das Strafgericht an ihr vollstreckt hatte.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 11, '»Ihre Schwester Oholiba hatte das zwar gesehen, trieb es aber trotzdem mit ihrer Verliebtheit noch ärger als jene und mit ihren Buhlereien noch heilloser, als ihre unsittliche Schwester es getan hatte.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 12, 'Sie entbrannte in Liebe zu den Assyrern, zu Statthaltern und Befehlshabern, die zu ihr kamen und gar prächtig gekleidet waren, Reiter hoch zu Roß, lauter schmucke Jünglinge.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 13, 'Da sah ich, daß auch sie sich befleckte: beide Schwestern trieben es in derselben Weise.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 14, 'Sie aber ging in ihrer Buhlerei noch weiter; und als sie Männer auf die Wand mit Rötel gemalt sah, Bilder von Chaldäern,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 15, 'die um die Hüften einen Gürtel trugen und deren Haupt mit überhängenden Kopfbünden bedeckt war und die allesamt wie vornehme Krieger aussahen, ähnlich den Babyloniern, deren Geburtsland Chaldäa ist,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 16, 'da entbrannte sie in Liebe zu ihnen, sobald sie ihrer ansichtig wurde, und sandte Boten an sie ins Land der Chaldäer.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 17, 'Da kamen denn die Babylonier zu ihr, um der Liebe mit ihr zu pflegen, und befleckten sie durch ihre Buhlerei; als sie sich aber an ihnen verunreinigt hatte, wurde sie ihrer überdrüssig.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 18, 'Da nun ihre Unzucht offenkundig geworden war [und sie ihre Blöße aufdeckte], da wurde ich ihrer überdrüssig, wie ich ihrer Schwester überdrüssig geworden war.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 19, 'Sie aber trieb es mit ihrer Buhlerei immer noch schlimmer, indem sie der Tage ihrer Jugendzeit gedachte, als sie in Ägypten gebuhlt hatte;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 20, 'und sie entbrannte in Liebe zu den dortigen Wollüstlingen, die Glieder hatten wie die Esel und Samenerguß wie die Hengste.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 21, 'Ja, du schautest dich um nach der Unzucht deiner Jugend, als die Ägypter dir den Busen betastet und deine jugendlichen Brüste gedrückt hatten.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 22, 'Darum, Oholiba, hat Gott der HERR so gesprochen: »Ich will nunmehr deine Buhlen gegen dich aufreizen, eben die, deren du überdrüssig geworden bist, und will sie von allen Seiten gegen dich herankommen lassen:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 23, 'die Babylonier und alle Chaldäer, die von Pekod und Schoa und Koa, auch alle Assyrer mit ihnen, schmucke Jünglinge, lauter Statthalter und Befehlshaber, vornehme Krieger und edle Herren, alle hoch zu Roß.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 24, 'Sie sollen (von Norden) gegen dich heranziehen, ein Getümmel von Rossen und Wagen, und mit Scharen von Völkern; mit großen und kleinen Schilden und Helmen werden sie ringsum gegen dich anrücken; ihnen will ich den Rechtsstreit vorlegen, damit sie dir nach ihren Rechtssatzungen das Urteil sprechen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 25, 'Dann will ich dich meine Eifersucht fühlen lassen, damit sie voll Ingrimms mit dir verfahren: Nase und Ohren werden sie dir abschneiden, und was von dir noch übriggeblieben ist, wird durch das Schwert fallen; deine Söhne und Töchter werden sie wegführen, und was von dir noch übrigbleibt, wird vom Feuer verzehrt werden.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 26, 'Sie werden dir die Kleider ausziehen und deine kostbaren Geschmeide mit fortnehmen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 27, 'So will ich deiner Buhlerei und deiner Unzucht von Ägypten her ein Ende machen, so daß du deine Augen nicht mehr zu ihnen erheben und an Ägypten nicht mehr zurückdenken wirst.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 28, 'Denn so hat Gott der HERR gesprochen: »Ich will dich nunmehr in die Gewalt derer fallen lassen, die du hassest, in die Gewalt derer, von denen dein Herz sich abgewandt hat.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 29, 'Sie werden dich ihren Haß fühlen lassen und dir alles wegnehmen, was du dir erworben hast, und dich nackt und bloß liegen lassen, so daß deine buhlerische Blöße aufgedeckt wird. Deine Unzucht und Ehebrecherei');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 30, 'haben dir dieses eingetragen, weil du den Heidenvölkern in deiner Gier nachgelaufen bist und zur Strafe dafür, daß du dich an ihren Götzen verunreinigt hast.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 31, 'Du bist denselben Weg gegangen wie deine Schwester; darum gebe ich auch dir jetzt ihren Becher zu trinken in die Hand.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 32, 'So hat Gott der HERR gesprochen: »Den Becher deiner Schwester sollst du trinken, den tiefen und weiten – zum Gelächter und Gespött sollst du werden –; er faßt reichlich viel,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 33, 'so daß du ganz trunken und des Jammers voll werden wirst: ein Becher des Schauders und Entsetzens ist der Becher deiner Schwester Samaria.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 34, 'Du sollst ihn trinken und leeren und seine Scherben noch ablecken und dir den Busen daran zerreißen; denn ich habe es gesagt!« – so lautet der Ausspruch Gottes des HERRN. –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 35, 'Darum hat Gott der HERR so gesprochen: »Weil du mich vergessen und mich hinter deinen Rücken geworfen hast, so trage auch du nun (die Strafe) für deine Unzucht und deine Buhlerei!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 36, 'Hierauf sagte der HERR zu mir: »Menschensohn, willst du nicht mit Ohola und Oholiba ins Gericht gehen? So halte ihnen denn ihre Greuel vor,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 37, 'daß sie Ehebruch getrieben haben und Blut an ihren Händen klebt; und zwar haben sie mit ihren Götzen Ehebruch getrieben und ihnen sogar ihre Kinder, die sie mir geboren hatten, als Opfer zum Fraß im Feuer dargebracht.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 38, 'Außerdem haben sie sich noch dadurch an mir vergangen, daß sie an demselben Tage mein Heiligtum verunreinigt und meine Sabbate entweiht haben.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 39, 'Denn wenn sie ihre Kinder ihren Götzen geschlachtet hatten, sind sie noch an demselben Tage in mein Heiligtum gekommen, um es zu entweihen: siehe, so haben sie es inmitten meines Hauses getrieben!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 40, 'Ja, sie haben sogar zu Männern gesandt, die von weither kommen sollten; und sobald ein Bote an sie gesandt worden war, stellten sie sich auch ein. Für diese hast du dich gebadet, hast dir die Augen geschminkt und dir Geschmeide angelegt;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 41, 'dann ließest du dich auf ein prächtiges Ruhebett nieder, vor dem ein Tisch zugerichtet war, auf den du meinen Weihrauch und mein Öl gestellt hattest.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 42, 'Dabei erscholl dann der laute Gesang einer frohgestimmten Menge; und zu Männern vom gemeinen Volk sandten sie, und Säufer aus der Wüste wurden herbeigebracht; denen legten sie Spangen an die Arme und setzten ihnen prachtvolle Kronen aufs Haupt.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 43, 'Da dachte ich von der durch Ehebruch Entkräfteten: ›Wird sie, ja sie, jetzt noch ihre Unzucht treiben?‹');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 44, 'Doch man kehrte bei ihr ein; wie man zu einer öffentlichen Dirne eingeht: ebenso kehrte man bei Ohola und Oholiba, den unzüchtigen Weibern, ein.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 45, 'Aber gerechte Männer, die sollen ihnen beiden das Urteil sprechen nach dem Recht, das für Ehebrecherinnen und Mörderinnen gültig ist; denn Ehebrecherinnen sind sie, und Blut klebt an ihren Händen.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 46, 'Denn so hat Gott der HERR gesprochen: »Man berufe eine Gemeindeversammlung gegen sie und gebe sie der Mißhandlung und Plünderung preis!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 47, 'Die Volksgemeinde soll sie dann steinigen und sie mit ihren Schwertern zerhauen; ihre Söhne und Töchter wird man umbringen und ihre Häuser in Flammen aufgehen lassen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 48, 'So will ich der Unzucht im Lande ein Ende machen, damit alle Weiber sich warnen lassen und nicht Unzucht treiben wie sie.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 49, 'So wird man euch für eure Verworfenheit büßen lassen, und ihr sollt die Strafe leiden für das, was ihr mit eurem Götzendienst verschuldet habt, damit ihr erkennt, daß ich Gott der HERR bin!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 24, 1, 'Im neunten Jahre, am zehnten Tage des zehnten Monats, erging das Wort des HERRN an mich folgendermaßen:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 24, 2, '»Menschensohn, schreibe dir den Namen des Tages auf, eben dieses heutigen Tages! Gerade am heutigen Tage ist der König von Babylon vor Jerusalem gerückt!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 24, 3, 'So trage denn dem widerspenstigen Geschlecht ein Gleichnis vor mit folgenden Worten: ›So hat Gott der HERR gesprochen: Setze den Kochtopf aufs Feuer, setze ihn auf und gieße auch Wasser hinein;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 24, 4, 'tu die Fleischstücke zusammen hinein, lauter gute Stücke, Lende und Schulter; fülle ihn mit auserlesenen Knochen;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 24, 5, 'nimm eins von den besten Schafen und schichte auch die Holzscheite darunter auf; laß es tüchtig sieden, damit auch seine Knochen in ihm kochen.‹«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 24, 6, 'Darum hat Gott der HERR so gesprochen: »Wehe über die blutbefleckte Stadt, über den Kochtopf, an dem der Rost sitzt und von dem sein Rost nicht abgeht! Hole die Fleischstücke einzeln aus ihm heraus, ohne eine Auswahl bei ihnen zu treffen!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 24, 7, 'Denn das von der Stadt vergossene Blut ist noch mitten in ihr: auf den nackten Felsen hat sie es fließen lassen, hat es nicht auf den Boden gegossen, daß man es mit Erde bedecken könnte.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 24, 8, 'Um den Zorn in mir aufsteigen zu lassen, um Rache üben zu können, habe ich das von ihr vergossene Blut auf den nackten Felsen fließen lassen, damit es nicht bedeckt werde.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 24, 9, 'Darum hat Gott der HERR so gesprochen: »Wehe über die blutbefleckte Stadt! Nun will ich selbst einen Holzstoß hoch aufschichten.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 24, 10, 'Bringe viel Holz herbei, zünde das Feuer an, koche das Fleisch gar, laß die Brühe einkochen und die Knochen anbrennen!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 24, 11, 'Dann stelle den Topf leer auf seine Kohlenglut, damit sein Erz glühend heiß wird und sein Schmutz in ihm zerschmilzt und sein Rost verschwindet.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 24, 12, 'Aber alle Mühe ist bei ihm verloren, denn der viele Rost geht doch nicht von ihm ab; auch im Feuer bleibt der Rost an ihm sitzen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 24, 13, 'Wegen deiner schandbaren Unreinheit, weil ich dich habe reinigen wollen und du doch von deinem Schmutz nicht rein geworden bist, sollst du auch ferner nicht rein werden, bis ich meinen Grimm an dir gestillt habe!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 24, 14, 'Ich, der HERR, habe es gesagt: es trifft ein, und ich führe es aus, ohne nachzulassen und Schonung zu üben oder Mitleid zu haben. Nach deinem Wandel und nach deinem ganzen Tun will ich dich richten!« – so lautet der Ausspruch Gottes des HERRN.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 24, 15, 'Weiter erging das Wort des HERRN an mich folgendermaßen:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 24, 16, '»Menschensohn, wisse wohl: ich will dir die Lust deiner Augen durch einen plötzlichen Schlag nehmen; aber du darfst dann weder klagen noch weinen, und keine Träne soll dir kommen!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 24, 17, 'Du magst im stillen seufzen, darfst aber keine Totentrauer anstellen; binde dir deinen Kopfbund um und ziehe deine Schuhe an deine Füße, lege dir keine Hülle um den Bart und genieße die Speisen nicht, welche die Leute dir schicken.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 24, 18, 'Nachdem ich hierauf am Morgen noch zum Volke geredet hatte, starb meine Frau am Abend, und ich tat am folgenden Morgen so, wie mir geboten war.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 24, 19, 'Als nun die Leute mich fragten: »Willst du uns nicht mitteilen, was das für uns bedeuten soll, daß du so verfährst?«,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 24, 20, 'antwortete ich ihnen: »Das Wort des HERRN ist folgendermaßen an mich ergangen:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 24, 21, '›Sage zum Hause Israel: So hat Gott der HERR gesprochen: Wisset wohl: ich will mein Heiligtum, den Gegenstand eures höchsten Stolzes, die Lust eurer Augen und die Sehnsucht eures Herzens, entweihen, und eure Söhne und Töchter, die ihr dort zurückgelassen habt, sollen durchs Schwert fallen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 24, 22, 'Da werdet ihr es dann so machen, wie ich jetzt getan habe: um den Bart werdet ihr euch keine Hülle legen und die Speisen nicht genießen, welche die Leute euch schicken;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 24, 23, 'euren Kopfbund werdet ihr auf dem Haupt und eure Schuhe an den Füßen behalten, werdet nicht klagen noch weinen, wohl aber im Bewußtsein eurer Verschuldung vergehen und einer gegen den andern seufzen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 24, 24, 'So wird euch also Hesekiel als Wahrzeichen dienen, so daß ihr, wenn es eintrifft, euch ganz so verhalten werdet, wie er sich verhalten hat; dann werdet ihr auch erkennen, daß ich Gott der HERR bin.‹«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 24, 25, '»Du aber, Menschensohn, wisse wohl: An dem Tage, wo ich ihnen ihr Bollwerk nehmen werde, ihren Stolz und ihre innige Freude, die Lust ihrer Augen und die Sehnsucht ihres Herzens, dazu auch ihre Söhne und Töchter:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 24, 26, 'an demselben Tage wird ein Flüchtling zu dir kommen, um es dir persönlich zu melden.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 24, 27, 'An jenem Tage wird dir der Mund zugleich mit dem Eintreffen des Flüchtlings aufgetan werden: du wirst dann wieder reden können und nicht länger stumm sein. So wirst du ihnen zum Wahrzeichen dienen, und sie werden erkennen, daß ich der HERR bin.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 25, 1, 'Hierauf erging das Wort des HERRN an mich folgendermaßen:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 25, 2, '»Menschensohn, richte deine Blicke gegen die Ammoniter und weissage gegen sie!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 25, 3, 'Sprich zu den Ammonitern: ›Hört das Wort Gottes, des HERRN! So hat Gott der HERR gesprochen: Weil du Haha! gerufen hast über mein Heiligtum, weil es entweiht wurde, und über das Land Israel, weil es verwüstet wurde, und über das Haus Juda, weil sie in die Verbannung wandern mußten:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 25, 4, 'darum, fürwahr, will ich dich den Söhnen des Ostens zum Besitztum geben, daß sie ihre Zeltlager in dir aufschlagen und ihre Wohnungen in dich verlegen; sie werden deine Früchte essen und sie deine Milch trinken.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 25, 5, 'Und ich will Rabba zu einer Weide für Kamele machen und die Ortschaften der Ammoniter zu einem Lagerplatz für Kleinvieh, damit ihr erkennt, daß ich der HERR bin.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 25, 6, 'Denn so hat Gott der HERR gesprochen: »Weil du in die Hände geklatscht und mit dem Fuß gestampft und dich gefühllos von ganzem Herzen über das Land Israel gefreut hast:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 25, 7, 'darum will ich nunmehr meine Hand gegen dich ausstrecken und dich den Völkern zur Plünderung preisgeben, ich will dich aus den Völkerschaften ausrotten und dich endgültig aus der Zahl der Länder verschwinden lassen, damit du erkennst, daß ich der HERR bin!« –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 25, 8, 'So hat Gott der HERR gesprochen: »Weil Moab und Seir sagen: ›Nunmehr ergeht es dem Hause Juda wie allen anderen Völkern!‹,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 25, 9, 'darum will ich jetzt die Abhänge Moabs entblößen, so daß es der Städte verlustig geht, seiner Städte verlustig ohne alle Ausnahme, der Zierde des Landes: Beth-Jesimoth, Baal-Meon und Kirjathaim.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 25, 10, 'Den Söhnen des Ostens will ich es samt dem Lande der Ammoniter zum Eigentum geben, damit der Ammoniter nicht mehr gedacht wird unter den Völkern.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 25, 11, 'An den Moabitern aber will ich (so) das Strafgericht vollstrecken, damit sie erkennen, daß ich der HERR bin!« –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 25, 12, 'So hat Gott der HERR gesprochen: »Weil Edom mit Rachgier am Hause Juda gehandelt und sich durch Vollziehung der Rache an ihnen schwer verschuldet hat,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 25, 13, 'darum hat Gott der HERR so gesprochen: ›Ich will meine Hand gegen Edom ausstrecken und Menschen samt Vieh in ihm ausrotten und will es zur Einöde machen; von Theman an, bis nach Dedan hin sollen sie durchs Schwert fallen!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 25, 14, 'Ich will aber die Vollstreckung meiner Rache an Edom in die Hand meines Volkes Israel legen, daß sie mit den Edomitern so verfahren, wie es meinem Zorn und meinem Grimm entspricht, und jene meine Rache fühlen!‹« – so lautet der Ausspruch Gottes des HERRN. –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 25, 15, 'So hat Gott der HERR gesprochen: »Weil die Philister mit Rachgier gehandelt und mit gefühllosem Herzen in nie endender Feindschaft Rache geübt haben, um Verderben anzurichten:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 25, 16, 'darum hat Gott der HERR so gesprochen: ›Nunmehr will ich meine Hand gegen die Philister ausstrecken und die Kreter ausrotten und, was von ihnen an der Meeresküste noch übrig ist, vertilgen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 25, 17, 'Ja, ich will schwere Rachetaten an ihnen vollziehen durch schonungslose Züchtigungen, damit sie erkennen, daß ich der HERR bin, wenn ich sie meine Rache fühlen lasse!‹«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 26, 1, 'Im elften Jahre, am ersten Tage des (elften) Monats, da erging das Wort des HERRN an mich folgendermaßen:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 26, 2, '»Menschensohn, weil Tyrus über Jerusalem ausgerufen hat: ›Haha! Zertrümmert ist das Tor der Völker, mir hat es sich aufgetan: ich werde nun alles vollauf haben, weil Jerusalem zerstört ist!‹ –,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 26, 3, 'darum spricht Gott der HERR so: ›Ich will nunmehr an dich, Tyrus, und will Völker in Menge gegen dich heranführen, wie das Meer seine Wogen heranfluten läßt!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 26, 4, 'Sie sollen die Mauern von Tyrus zerstören und seine Türme niederreißen; und ich will das Erdreich von ihm wegfegen und es zu einem nackten Felsen machen:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 26, 5, 'ein Trockenplatz für Fischernetze soll es werden inmitten des Meeres; denn ich habe es gesagt‹ – so lautet der Ausspruch Gottes des HERRN –, ›und es soll den Völkern zur Beute werden;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 26, 6, 'seine Tochterstädte aber, die auf dem Festlande liegen, sollen durch das Schwert vernichtet werden, damit sie erkennen, daß ich der HERR bin!‹«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 26, 7, 'Denn so hat Gott der HERR gesprochen: »Nunmehr will ich Nebukadnezar, den König von Babylon, den König der Könige, von Norden her gegen Tyrus heranziehen lassen mit Rossen, Kriegswagen und Reitern und mit der Heeresmacht vieler Völker.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 26, 8, 'Deine Tochterstädte auf dem Festland wird er mit dem Schwert vernichten; gegen dich aber wird er Belagerungstürme errichten und einen Damm gegen dich aufführen und Schilddächer gegen dich aufstellen;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 26, 9, 'den Stoß seiner Sturmböcke wird er gegen deine Mauern richten und deine Türme mit seinen Eisenhaken niederreißen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 26, 10, 'Infolge des Heranflutens seiner Rosse wird ihr Staub dich bedecken; vom Getöse seiner Reiter und der Räder seiner Streitwagen werden deine Mauern erbeben, wenn er in deine Tore einzieht, wie man in eine eroberte Stadt einzieht.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 26, 11, 'Mit den Hufen seiner Rosse wird er alle deine Straßen zerstampfen, wird dein Volk mit dem Schwert umbringen, und die Bildsäulen, auf die du dein Vertrauen setzst, wird er zu Boden stürzen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 26, 12, 'Sie werden deine Schätze rauben, deine Handelsgüter plündern, deine Mauern niederreißen, deine Prachtgebäude zerstören und deine Steine, deine Balken und den Schutt von dir ins Wasser werfen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 26, 13, 'So will ich dem Getön deiner Lieder ein Ende machen, und der Klang deiner Harfen soll nicht mehr vernommen werden.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 26, 14, 'Ich will dich zu einem kahlen Felsen machen: zu einem Trockenplatz für Fischernetze sollst du werden, und nie sollst du wieder aufgebaut werden, denn ich, der HERR, habe es gesagt!« – so lautet der Ausspruch Gottes des HERRN.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 26, 15, 'So hat Gott, der HERR, in bezug auf Tyrus gesprochen: »Fürwahr, vom Dröhnen deines Falles, wenn die Erschlagenen ächzen, wenn das Schwert in deiner Mitte mordet, werden die Meeresländer erbeben;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 26, 16, 'alle Fürsten des Meeres werden von ihren Thronen herabsteigen, ihre Prachtgewänder ablegen und ihre buntgestickten Kleider ausziehen; in Trauer werden sie sich kleiden, auf den Erdboden werden sie sich setzen und jeden Augenblick erzittern und deinethalben schaudern.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 26, 17, 'Da werden sie denn in Wehklagen über dich ausbrechen und zu dir sagen: ›Ach, wie bist du untergegangen, vom Meer verschwunden, du hochberühmte Stadt, die da mächtig auf dem Meere war, sie und ihre Bewohner, welche allen Anwohnern des Meeres Schrecken vor sich einflößten!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 26, 18, 'Jetzt erzittern die Meeresländer am Tage deines Falles, und die Inseln im Meer sind entsetzt über deinen Ausgang!‹«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 26, 19, 'Denn so hat Gott der HERR gesprochen: »Wenn ich dich zu einer verödeten Stadt mache wie andere Städte, die nicht mehr bewohnt werden; wenn ich die Meereswogen über dich heranfluten lasse, daß die weiten Wasser dich bedecken:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 26, 20, 'da will ich dich hinunterstoßen zu den in die Grube Hinabgefahrenen, zu dem Volk der Vorzeit, und dir deine Wohnung anweisen in den tiefsten Tiefen der Erde, in den uralten Trümmerstätten, bei denen, die in die Grube hinabgefahren sind, damit du nicht mehr bewohnt wirst und nicht mehr zur Schau dastehst im Lande der Lebenden!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 26, 21, 'Einem schreckensvollen Untergang will ich dich preisgeben, auf daß du nicht mehr da bist: man wird dich suchen, aber dich in Ewigkeit nicht mehr finden!« – so lautet der Ausspruch Gottes des HERRN.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 27, 1, 'Weiter erging das Wort des HERRN an mich folgendermaßen:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 27, 2, '»Du, Menschensohn, stimme ein Klagelied über Tyrus an');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 27, 3, 'und sprich zu Tyrus: ›(O Stadt), die du wohnst am Zugang zum Meer und Handel mit den Völkern treibst nach den vielen Meeresländern hin: so hat Gott der HERR gesprochen: Tyrus, du hast gedacht: Ich bin ein Schiff, vollkommen an Schönheit!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 27, 4, 'Dein Gebiet liegt im Herzen der Meere; deine Erbauer haben dich zu (einem Schiff von) vollendeter Schönheit gemacht.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 27, 5, 'Aus Zypressen vom Senir haben sie dir alles Plankenwerk gebaut und eine Zeder vom Libanon genommen, um den Mastbaum auf dir daraus zu fertigen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 27, 6, 'Aus Eichen von Basan haben sie deine Ruder hergestellt, dein Verdeck aus Edeltannenholz [mit Elfenbein ausgelegt] von den Eilanden der Kitthäer.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 27, 7, 'Feine Leinwand mit Buntstickerei aus Ägypten war dein Segel, um dir als Flagge zu dienen; blauer und roter Purpur von den Gestaden Elisas war deine Überdachung.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 27, 8, 'Die Einwohner von Sidon und Arwad dienten dir als Ruderer; die erfahrensten Männer aus deiner eigenen Mitte waren deine Steuerleute;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 27, 9, 'die Ältesten von Gebal und die dortigen Meister waren in dir als Ausbesserer deiner Lecke. Alle Seeschiffe samt ihrer Bemannung fanden sich bei dir ein, um Tauschhandel mit dir zu treiben.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 27, 10, 'Perser und Put und Lud dienten dir in deinem Heer als deine Kriegsleute; Schild und Helm hängten sie bei dir auf, die verliehen dir Glanz.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 27, 11, 'Männer aus Arwad und deine eigene Heeresmacht standen auf deinen Mauern ringsum und Gammadäer auf deinen Türmen; ihre Schilde hängten sie ringsum an deinen Mauern auf; sie machten deine Schönheit vollkommen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 27, 12, 'Tharsis trieb Handel mit dir wegen der Fülle an allerlei Gütern: mit Silber, Eisen, Zinn und Blei bezahlten sie deine Waren.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 27, 13, 'Die Jonier, Tibarener und Moscher machten Handelsgeschäfte mit dir: Sklaven und eherne Geräte gaben sie dir als Zahlung beim Tauschhandel.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 27, 14, 'Die vom Hause Thogarma bezahlten deine Waren mit Rossen, Reitpferden und Mauleseln.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 27, 15, 'Die Rhodier waren deine Kaufleute; zahlreiche Meeresländer standen im Verkehr mit dir: Elefantenzähne und Ebenholz lieferten sie dir als Zahlung.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 27, 16, 'Die Syrer schlossen Geschäfte mit dir ab wegen der Menge deiner Erzeugnisse: mit Karfunkel, rotem Purpur und bunten Geweben, mit feiner Leinwand, Korallen und Rubinen bezahlten sie deine Waren.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 27, 17, 'Juda und das Land Israel waren deine Kaufleute: Weizen von Minnith und Wachs, Honig, Öl und Balsam gaben sie dir als Zahlung beim Tauschhandel.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 27, 18, 'Damaskus trieb Handel mit dir ob der Menge deiner Erzeugnisse, wegen der Fülle an allerlei Gütern, mit Wein von Helbon und Wolle von Zahar.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 27, 19, 'Wedan und Jawan brachten aus Usal kunstvoll geschmiedetes Eisen auf deinen Markt; Kassia und Kalmus hatten sie für dich als Tauschwaren.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 27, 20, 'Dedan trieb Handel mit dir in Satteldecken zum Reiten.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 27, 21, 'Arabien und alle Häuptlinge Kedars standen in Verkehr mit dir: mit Lämmern, Widdern und Böcken trieben sie Handel mit dir.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 27, 22, 'Die Kaufleute von Saba und Ragma handelten mit dir: mit den köstlichsten Gewürzen, mit allerlei Edelsteinen und mit Gold bezahlten sie deine Waren.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 27, 23, 'Haran, Kanne und Eden handelten mit dir; Assur und ganz Medien waren deine Kunden;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 27, 24, 'sie handelten mit dir in Prachtgewändern, in Mänteln von blauem Purpur und buntgewirkten Stoffen, in farbenreichen Teppichen, in geflochtenen und fest gedrehten Tauen, gegen deine Waren.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 27, 25, 'Die Schiffe von Tharsis vertrieben deine Güter im Tauschhandel, und so wurdest du mit Reichtum angefüllt und kamst zu hoher Macht inmitten der Meere.‹«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 27, 26, '»›Deine Ruderer haben dich auf die hohe See hinausgeführt, doch der Ostwind bringt dich zum Scheitern inmitten des Meeres.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 27, 27, 'Deine Reichtümer und Waren, deine Handelsgüter, deine Matrosen und Steuerleute, deine Leckausbesserer, deine Tauschhändler und alle deine Kriegsleute, die sich auf dir befinden, mitsamt der ganzen Volksmenge auf dir werden in die Tiefe des Meeres sinken am Tage deines Untergangs.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 27, 28, 'Vom lauten Geschrei deiner Steuerleute wird die weite Meeresfläche erbeben.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 27, 29, 'Da werden dann alle, die das Ruder führen, die Seeleute und alle, die das Meer durchsteuern, aus ihren Schiffen steigen, werden ans Land treten');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 27, 30, 'und lauten Wehruf über dich erschallen lassen und kläglich schreien; sie werden sich Staub aufs Haupt streuen und sich in der Asche wälzen;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 27, 31, 'sie werden sich um deinetwillen kahl scheren, mit Sackleinen sich umgürten und mit bekümmertem Herzen um dich weinen in bitterer Klage.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 27, 32, 'In ihrem Schmerz werden sie ein Klagelied über dich anstimmen und über dich wehklagen: Welcher Ort ist so totenstill wie Tyrus inmitten des Meeres!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 27, 33, 'Solange deine Waren dem Meer entstiegen, hast du die Bedürfnisse vieler Völker befriedigt und durch die Fülle deiner Güter und Waren die Könige der Erde reich gemacht.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 27, 34, 'Jetzt aber, da du zertrümmert, vom Meere verschwunden, in Wassertiefen begraben bist und dein Handel und deine ganze Volksmenge mitten in dir versunken ist,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 27, 35, 'entsetzen sich alle Bewohner der Meeresländer über dich, ihre Könige sind von Schauder erfaßt, ihre Angesichter zucken schmerzlich.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 27, 36, 'Die Kaufleute in der ganzen Welt zischen über dich: ein Ende mit Schrecken hast du genommen; du bist dahin für immer!‹«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 28, 1, 'Weiter erging das Wort des HERRN an mich folgendermaßen:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 28, 2, '»Menschensohn, sage zum Fürsten von Tyrus: ›So hat Gott der HERR gesprochen: Weil dein Sinn hoch hinaus wollte und du gesagt hast: Ein Gott bin ich, einen Göttersitz bewohne ich mitten im Meer! – während du doch nur ein Mensch bist und kein Gott –, und weil du dich in deinem Herzen dünktest wie ein Gott –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 28, 3, 'natürlich bist du weiser als Daniel, nichts Verborgenes ist dunkel für dich!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 28, 4, 'Durch deine Weisheit und Einsicht hast du dir ja Reichtum erworben und Gold und Silber in deine Schatzkammern geschafft;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 28, 5, 'durch deine große Weisheit hast du bei deinem Handelsbetrieb deinen Reichtum gemehrt, und dein Sinn ging infolge deines Reichtums hoch hinaus –:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 28, 6, 'darum hat Gott der HERR so gesprochen: Weil dein Herz sich überhoben hat, als ob du ein Gott wärst,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 28, 7, 'darum will ich nunmehr Fremde gegen dich heranziehen lassen, die wildesten Völkerschaften; die werden deiner schönen Weisheit mit dem Schwert zu Leibe gehen und deinen Glanz trüben.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 28, 8, 'In die Grube werden sie dich hinabstoßen, und du wirst den Tod eines Erschlagenen sterben mitten im Meer!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 28, 9, 'Wirst du dann wohl angesichts deiner Mörder auch noch sagen: Ein Gott bin ich!, während du doch nur ein Mensch bist und kein Gott, in der Hand derer, die dich durchbohren?');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 28, 10, 'Den Tod von Unbeschnittenen wirst du erleiden durch die Hand von Fremden! Denn ich habe es gesagt!‹« – so lautet der Ausspruch Gottes des HERRN.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 28, 11, 'Weiter erging das Wort des HERRN an mich folgendermaßen:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 28, 12, '»Menschensohn, stimme ein Klagelied an über den König von Tyrus und sage zu ihm: ›So hat Gott der HERR gesprochen: Der du das Bild der Vollkommenheit warst, voll von Weisheit und von vollendeter Schönheit:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 28, 13, 'in Eden, dem Garten Gottes, befandest du dich, allerlei Edelsteine bedeckten deine Gewandung: Karneol, Topas und Jaspis, Chrysolith, Beryll und Onyx, Saphir, Rubin und Smaragd, und aus Gold waren deine Einfassungen und die Verzierungen an dir gearbeitet; am Tage deiner Erschaffung wurden sie eingesetzt.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 28, 14, 'Du warst ein gesalbter schirmender Cherub: ich hatte dich dazu bestellt; auf dem heiligen Götterberge weiltest du, inmitten feuriger Steine wandeltest du.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 28, 15, 'Unsträflich warst du in all deinem Tun vom Tage deiner Erschaffung an, bis Verschuldung an dir gefunden wurde.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 28, 16, 'Infolge deines ausgedehnten Handelsverkehrs füllte sich dein Inneres mit Frevel, und als du dich versündigt hattest, trieb ich dich vom Götterberge weg, und der schirmende Cherub verstieß dich aus der Mitte der feurigen Steine.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 28, 17, 'Dein Sinn war hochfahrend geworden infolge deiner Schönheit, und du hattest deine Weisheit außer acht gelassen um deines Glanzes willen; darum schleuderte ich dich auf die Erde hinab und gab dich vor Könige hin, damit sie eine Augenweide an dir hätten.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 28, 18, 'Infolge der Menge deiner Verschuldungen, durch die Unehrlichkeit deines Handelsbetriebes hattest du deine Heiligtümer entweiht; darum habe ich ein Feuer aus deiner Mitte hervorbrechen lassen, das dich verzehrt hat, und ich habe dich in Asche auf die Erde hingelegt vor den Augen aller, die dich sahen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 28, 19, 'Alle, die dich unter den Völkern gekannt haben, sind über dich entsetzt; ein Ende mit Schrecken hast du genommen: du bist dahin für immer!‹«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 28, 20, 'Weiter erging das Wort des HERRN an mich folgendermaßen:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 28, 21, '»Menschensohn, richte deine Blicke gegen Sidon und weissage gegen es');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 28, 22, 'mit folgenden Worten: ›So hat Gott der HERR gesprochen: Nunmehr will ich an dich, Sidon, und will meine Macht in deiner Mitte erweisen, damit sie erkennen, daß ich der HERR bin, wenn ich Strafgerichte an dir vollziehe und mich als den Heiligen an dir erweise.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 28, 23, 'Ich will die Pest in dich hineinsenden und Blutvergießen auf deine Straßen; und vom Schwert Erschlagene sollen in deiner Mitte ringsum hinsinken, damit sie erkennen, daß ich der HERR bin.‹«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 28, 24, '»Für das Haus Israel aber wird es alsdann keinen stechenden Dorn und keinen schmerzenden Stachel mehr geben von seiten aller umwohnenden Völker, die sie verächtlich behandelt haben, und sie werden erkennen, daß ich Gott, der HERR, bin.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 28, 25, 'So hat Gott der HERR gesprochen: »Wenn ich die vom Hause Israel aus den Völkern, unter die sie zerstreut worden sind, wieder sammle, dann will ich mich an ihnen vor den Augen der Heidenvölker als den Heiligen erweisen, und sie sollen in ihrem Lande wohnen, das ich meinem Knecht Jakob gegeben habe.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 28, 26, 'Und sie sollen in Sicherheit darin wohnen und Häuser bauen und Weinberge anlegen; ja in Sicherheit sollen sie wohnen, während ich Strafgerichte an allen umwohnenden Völkern vollstrecke, die sie verächtlich behandelt haben; dann werden sie erkennen, daß ich, der HERR, ihr Gott bin.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 29, 1, 'Im zehnten Jahre, am zwölften Tage des zehnten Monats, erging das Wort des HERRN an mich folgendermaßen:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 29, 2, '»Menschensohn, richte deine Blicke gegen den Pharao, den König von Ägypten, und sprich gegen ihn und gegen ganz Ägypten folgende Weissagungen aus.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 29, 3, '»So hat Gott der HERR gesprochen: ›Nunmehr will ich an dich, Pharao, König von Ägypten, du großes Krokodil, das inmitten seiner Ströme lagert, das da spricht: Mir gehört mein Strom, und ich habe ihn mir geschaffen!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 29, 4, 'So will ich dir nun Haken in die Kinnbacken legen und die Fische deiner Ströme an deinen Schuppen ankleben lassen und will dich mitten aus deinen Strömen heraufziehen samt allen Fischen deiner Ströme, die fest an deinen Schuppen hängen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 29, 5, 'Dann will ich dich in die Wüste hinwerfen, dich und alle Fische deiner Ströme; auf das freie Feld sollst du fallen, ohne aufgehoben und bestattet zu werden: den Tieren des Feldes und den Vögeln des Himmels will ich dich zum Fraß geben.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 29, 6, 'Da werden denn alle Bewohner Ägyptens erkennen, daß ich der HERR bin, weil du für das Haus Israel nur ein Rohrstab gewesen bist –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 29, 7, 'wenn sie dich in die Hand nahmen, knicktest du ein und rissest ihnen die ganze Hand auf; und wenn sie sich auf dich stützen wollten, zerbrachst du und machtest ihnen die ganzen Hüften wanken.‹«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 29, 8, '»Darum hat Gott der HERR so gesprochen: ›Nunmehr will ich das Schwert über dich kommen lassen und Menschen samt Vieh in dir ausrotten;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 29, 9, 'und Ägyptenland soll zur Wüste und Einöde werden, damit man erkennt, daß ich der HERR bin. Weil du gesagt hast: ›Mir gehört der Nilstrom, und ich habe ihn geschaffen!‹,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 29, 10, 'darum will ich nunmehr an dich und an deine Ströme und will das Land Ägypten zu Wüsteneien machen, zu wüsten Einöden von Migdol bis nach Syene, bis an die Grenze von Äthiopien.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 29, 11, 'Keines Menschen Fuß soll es durchwandern, und auch der Fuß keines Tieres soll es durchschreiten, und es soll vierzig Jahre lang unbewohnt bleiben.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 29, 12, 'Ja, ich will das Land Ägypten zu einer Wüste machen inmitten verwüsteter Länder, und seine Städte sollen inmitten verödeter Städte vierzig Jahre lang wüst daliegen; und die Ägypter werde ich unter die Völker zerstreuen und in die Länder versprengen.‹«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 29, 13, 'Doch so hat Gott der HERR gesprochen: »Nach Ablauf der vierzig Jahre will ich die Ägypter aus den Völkern, unter die sie versprengt waren, wieder sammeln');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 29, 14, 'und das Schicksal der Ägypter wenden und sie nach Oberägypten, in ihr Geburtsland, zurückbringen; dort werden sie dann ein bescheidenes Königreich bilden.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 29, 15, 'Dieses soll weniger mächtig sein als die anderen Königreiche und sich fernerhin nicht mehr über die anderen Völker erheben; und ich will sie wenig zahlreich werden lassen, so daß sie nicht mehr über die anderen Völker herrschen sollen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 29, 16, 'Dann wird dieses Reich für das Haus Israel nicht mehr den Gegenstand des Vertrauens bilden, was mich an ihre Verschuldung erinnern würde, wenn sie sich nach ihnen hinwendeten; und sie werden erkennen, daß ich Gott der HERR bin.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 29, 17, 'Hierauf begab es sich im siebenundzwanzigsten Jahre, am ersten Tage des ersten Monats, da erging das Wort des HERRN an mich folgendermaßen:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 29, 18, '»Menschensohn, Nebukadnezar, der König von Babylon, hat sein Heer schwere Arbeit verrichten lassen gegen Tyrus, so daß allen die Köpfe kahl geworden und die Schultern allen wund gerieben sind, aber Lohn ist weder ihm noch seinem Heere von Tyrus zuteil geworden für die Arbeit, die er gegen die Stadt geleistet hat.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 29, 19, 'Darum hat Gott der HERR so gesprochen: »Ich will nunmehr Nebukadnezar, dem Könige von Babylon, das Land Ägypten geben, damit er sich dessen Reichtum aneignet und es ausraubt und ausplündert: das soll seinem Heere als Lohn zuteil werden.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 29, 20, 'Als seinen Sold, um den er sich abgemüht hat, gebe ich ihm das Land Ägypten, weil sie für mich gearbeitet haben« – so lautet der Ausspruch Gottes des HERRN.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 29, 21, '»An jenem Tage will ich das Haus Israel zu neuer Macht erwachsen lassen und dir gewähren, den Mund in ihrer Mitte wieder frei aufzutun, damit sie erkennen, daß ich der HERR bin.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 30, 1, 'Weiter erging das Wort des HERRN an mich folgendermaßen:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 30, 2, '»Menschensohn, verkünde folgende Weissagungen: ›So hat Gott der HERR gesprochen: Wehklagt! O welch ein Tag!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 30, 3, 'Denn nahe ist der Tag, ja, nahe ist der Tag des HERRN, ein dunkelbewölkter Tag: die Endzeit für die Heidenvölker wird er sein!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 30, 4, 'Da wird ein Schwert nach Ägypten kommen und in Äthiopien große Angst herrschen, wenn Durchbohrte in Ägypten hinsinken und man seinen Reichtum wegschleppt und seine Grundfesten eingerissen werden.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 30, 5, 'Die Äthiopier, Put und Lud samt all dem Völkergemisch und Kub samt den Bewohnern der verbündeten Länder werden mit ihnen durch das Schwert fallen.‹«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 30, 6, 'So hat der HERR gesprochen: »Da werden dann die Stützen Ägyptens fallen und seine stolze Pracht dahinsinken; von Migdol bis nach Syene werden sie im Lande durch das Schwert fallen!« – so lautet der Ausspruch Gottes des HERRN.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 30, 7, '»Ihr Land soll verwüstet daliegen inmitten verwüsteter Länder und seine Städte zerstört sein inmitten zerstörter Städte.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 30, 8, 'Da werden sie denn erkennen, daß ich der HERR bin, wenn ich Feuer an Ägypten lege und alle, die ihnen helfen, zerschmettert werden.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 30, 9, 'An jenem Tage werden Boten von mir ausfahren auf Schiffen, um Äthiopien aus seiner Sicherheit aufzuschrecken, und große Angst wird unter ihnen herrschen wegen des Unglückstages Ägyptens; denn dieser kommt unfehlbar!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 30, 10, 'So hat Gott der HERR gesprochen: »So will ich denn dem Gepränge Ägyptens ein Ende machen durch die Hand Nebukadnezars, des Königs von Babylon.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 30, 11, 'Er und sein Kriegsvolk mit ihm, die wildesten der Heidenvölker, werden herbeigeholt werden, um das Land zu verheeren; sie werden ihre Schwerter gegen Ägypten zücken und das Land mit Erschlagenen füllen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 30, 12, 'Und ich will die Ströme trocken legen und das Land der Gewalt von Bösewichtern preisgeben und das Land samt allem, was darin ist, durch die Hand von Fremden verwüsten: ich, der HERR, habe es gesagt!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 30, 13, 'So hat Gott der HERR gesprochen: »Ja, ich will die Götzen vernichten und den falschen Göttern in Memphis ein Ende machen; es soll künftig auch keine Fürsten mehr im Lande Ägypten geben, und ich will das Land Ägypten in Furcht versetzen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 30, 14, 'Ich will Oberägypten verwüsten und Feuer an Zoan legen und Strafgerichte an Theben vollstrecken;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 30, 15, 'ich will meinen Zorn an Pelusium, dem Bollwerk Ägyptens, auslassen und das Gepränge von Theben vernichten;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 30, 16, 'und ich will Feuer an Ägypten legen: Pelusium soll zittern und beben, Theben wird erstürmt werden und Memphis Feinde am hellen Tage sehen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 30, 17, 'Die jungen Krieger von Heliopolis und Bubastis werden durch das Schwert fallen, die übrigen Bewohner aber in die Gefangenschaft wandern.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 30, 18, 'Und in Daphne soll sich der Tag in Finsternis verwandeln, wenn ich daselbst die Herrscherstäbe Ägyptens zerbreche und seiner stolzen Pracht dort ein Ende gemacht wird; es selbst – Gewölk wird es umhüllen, und seine Tochterstädte müssen in die Verbannung wandern.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 30, 19, 'So werde ich Strafgerichte an Ägypten vollziehen, damit sie erkennen, daß ich der HERR bin!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 30, 20, 'Im elften Jahre, am siebten Tage des ersten Monats, erging das Wort des HERRN an mich folgendermaßen:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 30, 21, '»Menschensohn, den (einen) Arm des Pharaos, des Königs von Ägypten, habe ich zerbrochen; und siehe, er ist nicht verbunden worden, daß man Heilmittel angewandt, daß man eine Binde als Verband angelegt hätte, damit er wieder stark genug würde, das Schwert zu führen.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 30, 22, 'Darum hat Gott der HERR so gesprochen: »Nunmehr will ich an den Pharao, den König von Ägypten, und will ihm beide Arme zerschmettern, den gesunden und den zerbrochenen, und ihm das Schwert aus der Hand schlagen;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 30, 23, 'dann will ich die Ägypter unter die Völker zerstreuen und sie in die Länder versprengen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 30, 24, 'Dagegen will ich dem König von Babylon die Arme stärken und ihm mein Schwert in die Hand geben; aber die Arme des Pharaos will ich zerbrechen, daß er vor ihm ächzen soll wie ein tödlich Verwundeter.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 30, 25, 'Ja, die Arme des Königs von Babylon will ich stärken, während die Arme des Pharaos herabsinken sollen, damit man erkennt, daß ich der HERR bin, wenn ich dem König von Babylon mein Schwert in die Hand gebe, damit er es gegen das Land Ägypten schwinge.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 30, 26, 'Alsdann werde ich die Ägypter unter die Völker zerstreuen und sie in die Länder versprengen, damit sie erkennen, daß ich der HERR bin.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 31, 1, 'Im elften Jahre, am ersten Tage des dritten Monats, erging das Wort des HERRN an mich folgendermaßen:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 31, 2, '»Menschensohn, richte an den Pharao, den König von Ägypten, und an sein Gepränge folgende Worte.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 31, 3, '»›Wem glichest du in deiner Größe? Ja, du warst einer Edeltanne gleich, einer Zeder auf dem Libanon, die schön von Geäst und mit beschattendem Laubwerk und hoch an Wuchs war, so daß ihr Wipfel bis in die Wolken hineinragte.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 31, 4, 'Das Wasser hatte sie groß wachsen lassen, die unterirdische Flut sie in die Höhe getrieben; denn deren Strömung ging rings um ihren Standort herum, während sie sonst nur Rinnsale an alle Bäume des Gefildes gelangen ließ.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 31, 5, 'Darum ragte ihr Wuchs über alle Bäume des Gefildes empor, und ihre Zweige wurden zahlreich und ihre Äste lang von der reichlichen Bewässerung, indem sie sich ausbreitete.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 31, 6, 'In ihren Zweigen nisteten alle Vögel des Himmels, unter ihrem Laubdach warfen alle wilden Tiere ihre Jungen, und in ihrem Schatten wohnten all die vielen Völker.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 31, 7, 'Schön war sie in ihrem hohen Wuchs, durch die Länge ihrer Zweige; denn ihre Wurzeln lagen an reichlichem Wasser.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 31, 8, 'Keine Zeder im Garten Gottes reichte an sie heran, die Zypressen kamen ihr nicht gleich mit ihren Zweigen, und die Platanen hatten nicht solche Äste wie sie: kein Baum im Garten Gottes konnte sich an Schönheit mit ihr vergleichen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 31, 9, 'Ich hatte sie durch die Menge ihrer Zweige so schön gemacht, daß alle Bäume Edens im Garten Gottes neidisch auf sie waren.‹«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 31, 10, 'Darum hat Gott der HERR so gesprochen: »Weil sie so hochragend an Wuchs geworden war und ihren Wipfel bis in die Wolken hatte hineinragen lassen und ihr Sinn infolge ihres hohen Wuches hochfahrend geworden war,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 31, 11, 'so habe ich sie der Gewalt eines Mächtigen unter den Völkern preisgegeben, der mit ihr nach ihrer Bosheit verfahren soll: infolge ihrer Verfehlung habe ich sie verstoßen.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 31, 12, 'Da haben Fremde sie umgehauen, die wildesten unter den Völkern, und haben sie hingeworfen; auf die Berge und in alle Täler sind ihre Zweige gefallen: ihre Äste lagen zerbrochen in allen Flußtälern des Landes, und alle Völker der Erde zogen aus ihrem Schatten hinweg und ließen sie unbeachtet liegen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 31, 13, 'Auf ihren umgefallenen Stamm setzten sich alle Vögel des Himmels nieder, und an ihre Zweige machten sich alle Tiere des Feldes,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 31, 14, 'damit keine Bäume am Wasser sich forthin wegen ihres hohen Wuchses überheben möchten und ihren Wipfel bis in die Wolken hineinragen ließen und die Gewaltigen unter ihnen sich nicht stolz hinstellten in ihrer Hoheit, alle, die vom Wasser getränkt werden; denn sie sind alle dem Tode geweiht und müssen in das unterirdische Land hinab, mitten unter die anderen Menschenkinder, zu denen hin, die in die Grube hinabgefahren sind.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 31, 15, 'So hat Gott der HERR gesprochen: »An dem Tage, als sie in das Totenreich hinabfuhr, ließ ich die unterirdische Flut sich in Trauer um sie hüllen und hielt ihre Strömung zurück, so daß die reichlichen Wasser gehemmt wurden; den Libanon hüllte ich ihretwegen in ein Trauergewand, und alle Bäume des Gefildes mußten ihretwegen verschmachten.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 31, 16, 'Durch das Gedröhn ihres Sturzes machte ich die Völker erzittern, als ich sie in das Totenreich hinabsinken ließ zu den in die Grube Hinabgefahrenen; da trösteten sich im unterirdischen Lande alle Bäume Edens, die erlesensten und schönsten auf dem Libanon, alle, die vom Wasser getränkt wurden.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 31, 17, 'Auch sie mußten mit ihr in das Totenreich hinabfahren zu den vom Schwert Durchbohrten, die vordem als ihre Helfer in ihrem Schatten gewohnt hatten inmitten der Völker.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 31, 18, 'Wem glichest du also an Herrlichkeit und Größe unter den Bäumen Edens? Und doch wirst du mit den Bäumen Edens in das unterirdische Land hinabgestoßen werden; inmitten Unbeschnittener wirst du da bei den vom Schwert Erschlagenen liegen: das ist der Pharao und all sein Gepränge!« – so lautet der Ausspruch Gottes des HERRN.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 32, 1, 'Im zwölften Jahre, am ersten Tage des zwölften Monats, erging das Wort des HERRN an mich folgendermaßen:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 32, 2, '»Menschensohn, stimme ein Klagelied an über den Pharao, den König von Ägypten, und sage zu ihm«: »›Einem jungen Löwen unter den Völkern wurdest du verglichen, und warst doch nur wie ein Krokodil im Nilstrom, spritztest mit deinen Nüstern, trübtest das Wasser mit deinen Füßen und wühltest seine Fluten auf.‹');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 32, 3, 'So hat Gott der HERR gesprochen: ›So will ich denn mein Netz über dich ausbreiten durch eine Schar vieler Völker, die sollen dich in meinem Fanggarn emporziehen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 32, 4, 'Dann will ich dich auf die Erde hinwerfen, dich auf das freie Feld schleudern und will machen, daß alle Vögel des Himmels sich auf dich niedersetzen und die wilden Tiere der ganzen Erde sich an dir sättigen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 32, 5, 'Dann will ich dein Fleisch auf die Berge verschleppen lassen und die Täler mit deinem Aas füllen');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 32, 6, 'und das Land mit deinem Ausfluß tränken von deinem Blut bis an die Berge, und die Rinnsale sollen voll von dir werden.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 32, 7, 'Alsdann will ich, wenn ich dich erlöschen lasse, den Himmel verschleiern und seine Sterne verdunkeln, will die Sonne in Gewölk hüllen, und der Mond soll sein Licht nicht leuchten lassen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 32, 8, 'Alle leuchtenden Himmelslichter will ich deinethalben verdunkeln und Finsternis über dein Land ausbreiten‹ – so lautet der Ausspruch Gottes des HERRN.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 32, 9, '›Da werde ich denn das Herz vieler Völker in Betrübnis versetzen, wenn ich die Kunde von deinem Untergang unter die Nationen gelangen lasse, in Länder, die du nicht gekannt hast;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 32, 10, 'und ich werde machen, daß viele Völker sich über dich entsetzen und ihre Könige über dein Geschick schaudern, wenn ich mein Schwert vor ihren Augen schwinge; und sie werden unaufhörlich zittern, ein jeder für sein Leben, am Tage deines Sturzes.‹«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 32, 11, '»Denn so hat Gott der HERR gesprochen: ›Das Schwert des Königs von Babylon soll über dich kommen!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 32, 12, 'Durch die Schwerter tapferer Krieger will ich dein Gepränge zu Fall bringen – die wildesten unter den Völkern sind sie allesamt –: die sollen die Herrlichkeit Ägyptens zerstören, daß all sein Gepränge vernichtet wird;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 32, 13, 'auch seine gesamte Tierwelt will ich zugrunde gehen lassen von den vielen Gewässern hinweg, so daß keines Menschen Fuß sie noch aufwühlen und keines Tieres Klaue sie noch trüben soll.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 32, 14, 'Alsdann will ich ihre Gewässer klären und ihre Ströme wie Öl dahingleiten lassen‹ – so lautet der Ausspruch Gottes, des HERRN –,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 32, 15, '›wenn ich das Land Ägypten zu einer Wüste mache und das Land öde wird, seiner Fülle beraubt, indem ich alle seine Bewohner sterben lasse, damit sie erkennen, daß ich der HERR bin.‹');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 32, 16, 'Ein Klagelied ist dies, das man klagend singen soll; die Töchter der Völker sollen es klagend singen; über Ägypten und all sein Gepränge sollen sie es klagend singen!« – so lautet der Ausspruch Gottes des HERRN.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 32, 17, 'Und im zwölften Jahre, am fünfzehnten Tage des (zwölften oder: ersten) Monats, erging das Wort des HERRN an mich folgendermaßen:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 32, 18, '»Menschensohn, stimme eine Totenklage an über das Gepränge Ägyptens und senke es hinab, du und die Töchter mächtiger Völker, in das unterirdische Land zu den in die Grube Hinabgefahrenen!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 32, 19, '»Vor wem hast du etwas voraus an Lieblichkeit? Fahre hinab und laß dich bei den Unbeschnittenen betten!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 32, 20, 'Mitten unter den vom Schwert Erschlagenen sollen sie hinsinken! Das Schwert ist schon dargereicht: schleppt Ägypten herbei und sein ganzes Gepränge!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 32, 21, 'Da werden die Vornehmsten unter den tapferen Kriegern mitten aus dem Totenreich heraus ihm samt seinen Helfern zurufen: Sie sind herabgekommen, sie liegen da, die Unbeschnittenen, vom Schwert erschlagen!‹«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 32, 22, '»›Dort ist Assur und sein ganzes Kriegsvolk; rings um ihn her liegen ihre Gräber: alle sind sie erschlagen, durch das Schwert gefallen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 32, 23, 'Seine Gräber sind im tiefsten Grunde der Grube untergebracht, und sein Kriegsvolk liegt rings um sein Grab herum; sie sind alle erschlagen, durch das Schwert gefallen, sie, die einstmals Schrecken verbreitet haben im Lande der Lebenden.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 32, 24, 'Dort ist Elam und alle seine Krieger rings um sein Grab her, lauter Erschlagene, durch das Schwert Gefallene, die als Unbeschnittene in das unterirdische Land hinabgefahren sind, sie, die einstmals Schrecken vor sich her im Lande der Lebenden verbreitet haben und jetzt ihre Schmach tragen müssen bei den in die Grube Hinabgefahrenen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 32, 25, 'Mitten unter Erschlagenen hat man ihm ein Lager angewiesen samt all seinen Kriegern, deren Gräber rings um ihn her liegen. Sie sind allesamt unbeschnitten, vom Schwert erschlagen, weil einstmals der Schrecken vor ihnen im Lande der Lebenden verbreitet war. So tragen sie nun ihre Schmach bei den in die Grube Hinabgefahrenen: mitten unter Erschlagene hat man sie hingelegt.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 32, 26, 'Dort sind Mesech und Thubal und alle ihre Krieger, deren Gräber rings um sie her liegen; sie sind allesamt unbeschnitten, vom Schwert erschlagen, sie, die einstmals Schrecken vor sich her im Lande der Lebenden verbreitet haben.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 32, 27, 'Sie liegen nicht bei den in der Vorzeit gefallenen Helden, die in ihrer vollen Kriegswehr in das Totenreich hinabgefahren sind, denen man ihre Schwerter unter das Haupt und ihre Schilde auf die Gebeine gelegt hat, weil einstmals ein Schrecken vor ihrer Heldenkraft im Lande der Lebenden geherrscht hat.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 32, 28, 'So wirst auch du (Ägypten) inmitten Unbeschnittener zerschmettert bei den vom Schwert Erschlagenen gebettet sein.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 32, 29, 'Dort ist Edom mit seinen Königen und all seinen Fürsten, die trotz ihres Heldentums den vom Schwert Erschlagenen beigesellt worden sind: sie müssen bei Unbeschnittenen liegen, bei den in die Grube Hinabgefahrenen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 32, 30, 'Dort sind die Herrscher des Nordens insgesamt und alle Sidonier, die als Erschlagene hinabgefahren und trotz ihrer Furchtbarkeit, trotz ihres Heldentums zuschanden geworden sind. Da liegen sie nun als Unbeschnittene bei den vom Schwert Erschlagenen und müssen ihre Schmach tragen mit den in die Grube Hinabgefahrenen.‹«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 32, 31, '»Wenn der Pharao diese alle erblickt, mag er sich über all seine Gepränge trösten; vom Schwert erschlagen ist der Pharao samt seiner ganzen Heeresmacht« – so lautet der Ausspruch Gottes des HERRN –,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 32, 32, '»denn er hat Schrecken vor sich her verbreitet im Lande der Lebenden; darum wird er inmitten Unbeschnittener bei den vom Schwert Erschlagenen gebettet liegen, der Pharao und all sein Gepränge!« – so lautet der Ausspruch Gottes des HERRN.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 33, 1, 'Das Wort des HERRN erging an mich folgendermaßen:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 33, 2, '»Menschensohn, rede zu deinen Volksgenossen und sage zu ihnen: Wenn ich das Schwert über ein Land kommen lasse und das Volk des Landes einen Mann aus seiner Gesamtheit wählt und ihn für sich zum Wächter bestellt,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 33, 3, 'und der sieht das Schwert in das Land einbrechen und stößt in die Trompete und warnt dadurch das Volk –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 33, 4, 'wenn dann einer zwar den Schall der Trompete hört, aber sich nicht warnen läßt, so daß der bewaffnete Feind kommt und ihn ums Leben bringt, so soll die Schuld an seinem Tode ihm selbst beigemessen werden;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 33, 5, 'er hat ja den Schall der Trompete gehört, aber sich nicht warnen lassen: er hat seinen Tod selbst verschuldet; denn hätte er sich warnen lassen, so würde er sein Leben gerettet haben.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 33, 6, 'Wenn aber der Wächter den bewaffneten Feind kommen sieht und nicht in die Trompete stößt, so daß das Volk ungewarnt bleibt, und der bewaffnete Feind kommt und bringt einen von ihnen ums Leben, so wird der Betreffende zwar infolge seiner Sündenschuld weggerafft, aber für den Verlust seines Lebens werde ich den Wächter verantwortlich machen.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 33, 7, '»Du nun, Menschensohn – dich habe ich zum Wächter für das Haus Israel bestellt, damit du sie, wenn du ein Wort aus meinem Munde vernommen hast, in meinem Namen warnst.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 33, 8, 'Wenn ich zu dem Gottlosen sage: ›Gottloser, du mußt des Todes sterben!‹, du aber nichts sagst, um den Gottlosen vor seinem bösen Wandel zu warnen, so wird er, der Gottlose, zwar sein Leben um seiner Verschuldung willen verlieren, aber für den Verlust seines Lebens werde ich dich verantwortlich machen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 33, 9, 'Wenn du aber deinerseits den Gottlosen vor seinem bösen Wandel gewarnt hast, damit er von ihm umkehre, er sich aber von seinem Wandel nicht abbringen läßt, so wird er zwar um seiner Verschuldung willen sterben, du aber hast dein Leben gerettet.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 33, 10, '»Und du nun, Menschensohn, sage zum Hause Israel: ›Folgendes Bekenntnis habt ihr abgelegt: Ja, unsere Übertretungen und Sünden lasten auf uns, und durch sie vergehen wir ganz: wie könnten wir denn am Leben bleiben?‹');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 33, 11, 'Sage zu ihnen: ›So wahr ich lebe!‹ – so lautet der Ausspruch Gottes des HERRN –: ›ich habe kein Wohlgefallen am Tode des Gottlosen, sondern daran, daß der Gottlose sich von seinem Wandel bekehrt und am Leben bleibt! Kehrt um, ja bekehrt euch von eurem bösen Wandel! Denn warum wollt ihr sterben, Haus Israel?‹ –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 33, 12, 'Du also, Menschensohn, sage zu deinen Volksgenossen: ›Den Gerechten wird seine Gerechtigkeit nicht retten an dem Tage, wo er in Sünde verfällt; und den Gottlosen wird seine Gottlosigkeit nicht zu Fall bringen an dem Tage, wo er von seiner Gottlosigkeit umkehrt; aber auch der Gerechte kann um seiner Gerechtigkeit willen nicht am Leben erhalten bleiben an dem Tage, wo er in Sünde verfällt.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 33, 13, 'Wenn ich dem Gerechten verheiße, er solle ganz gewiß das Leben behalten, und er sich auf seine (bisherige) Gerechtigkeit verläßt und Böses tut, so wird seines ganzen gerechten Tuns nicht mehr gedacht werden, sondern um des Bösen willen, das er verübt hat, um deswillen muß er sterben.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 33, 14, 'Und wenn ich dem Gottlosen androhe: ›Du mußt des Todes sterben!‹ und er sich von seiner Sünde abkehrt und nunmehr Recht und Gerechtigkeit übt, so daß er das ihm Verpfändete zurückgibt, Geraubtes wiedererstattet und nach den Satzungen wandelt, deren Beobachtung zum Leben führt, so daß er nichts Böses mehr tut, so soll er gewißlich das Leben behalten und nicht sterben:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 33, 15, 'so daß er das ihm Verpfändete zurückgibt, Geraubtes wiedererstattet und nach den Satzungen wandelt, deren Beobachtung zum Leben führt, so daß er nichts Böses mehr tut, so soll er gewißlich das Leben behalten und nicht sterben:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 33, 16, 'keine von allen Sünden, die er begangen hat, soll ihm noch angerechnet werden; Recht und Gerechtigkeit hat er geübt: er soll gewißlich das Leben behalten!‹');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 33, 17, 'Freilich sagen deine Volksgenossen: ›Das Verfahren des Herrn ist nicht das richtige!‹, während doch ihr eigenes Verfahren nicht das richtige ist.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 33, 18, 'Wenn ein Gerechter sich von seiner Gerechtigkeit abwendet und Unrecht tut, so muß er auf Grund davon sterben;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 33, 19, 'wenn dagegen ein Gottloser von seiner Gottlosigkeit abläßt und Recht und Gerechtigkeit übt, so soll er infolgedessen am Leben bleiben.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 33, 20, 'Und ob ihr auch behauptet, das Verfahren des Herrn sei nicht das richtige, so werde ich doch jeden von euch nach seinem Wandel richten, Haus Israel!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 33, 21, 'Es begab sich aber im zwölften Jahre unserer Verbannung, am fünften Tage des zehnten Monats, da kam ein Flüchtling aus Jerusalem zu mir mit der Nachricht: »Die Stadt ist erobert!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 33, 22, 'Die Hand des HERRN war aber schon am Abend vor der Ankunft des Flüchtlings über mich gekommen, und er hatte mir den Mund aufgetan, ehe jener am folgenden Morgen bei mir eintraf. So war mir denn der Mund aufgetan worden, und ich bin seitdem nie wieder stumm geworden.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 33, 23, 'Hierauf erging das Wort des HERRN an mich folgendermaßen:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 33, 24, '»Menschensohn, die Bewohner jener Trümmerstätten im Lande Israel sagen immer wieder: ›Abraham war nur ein einzelner Mann und hat doch das Land zum Besitz erhalten; unser aber sind viele: uns ist das Land als Besitz zugewiesen!‹');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 33, 25, 'Darum sage zu ihnen: ›So hat Gott der HERR gesprochen: Ihr genießt das Fleisch mitsamt dem Blut und erhebt eure Augen zu euren Götzen und vergießt Blut, und da solltet ihr das Land zum Besitz haben?');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 33, 26, 'Ihr verlaßt euch fest auf euer Schwert, verübt Greuel und entehrt ein jeder das Weib des andern, und da solltet ihr das Land im Besitz haben?‹«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 33, 27, '»Folgendermaßen sollst du zu ihnen sagen: ›So hat Gott der HERR gesprochen: So wahr ich lebe: die in den Trümmerstätten Wohnenden sollen durch das Schwert fallen, und wer sich auf freiem Felde aufhält, den will ich den wilden Tieren zum Fraß hingeben, und wer sich auf den Berghöhen und in den Höhlen befindet, soll an der Pest sterben!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 33, 28, 'Und ich will das Land zur Wüste und Einöde machen: seine stolze Pracht soll ein Ende haben, und das Bergland Israels soll wüst daliegen, so daß niemand es mehr durchwandert!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 33, 29, 'Dann werden sie erkennen, daß ich der HERR bin, wenn ich das Land zur Wüste und Einöde mache wegen all ihrer Greuel, die sie verübt haben.‹«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 33, 30, '»Du aber, Menschensohn – deine Volksgenossen unterhalten sich über dich an den Mauern und in den Toreingängen der Häuser und sagen einer zum andern: ›Kommt doch und hört, was für ein Ausspruch es ist, den der HERR ergehen läßt!‹');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 33, 31, 'Da kommen sie denn zu dir wie bei einem Volksauflauf und setzen sich vor dich hin als mein Volk und hören deine Worte an, handeln aber nicht danach, sondern sie tun liebevoll mit ihrem Munde, während ihr Herz hinter ihrem Gewinn herläuft.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 33, 32, 'Und wisse wohl: du bist ihnen wie ein Liebeslied, wie einer, der eine schöne Stimme hat und die Leier gut zu spielen versteht; und so hören sie denn deine Worte an, handeln aber nicht danach.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 33, 33, 'Wenn es aber eintrifft – und es trifft unfehlbar ein! –, dann werden sie erkennen, daß ein Prophet unter ihnen dagewesen ist.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 34, 1, 'Hierauf erging das Wort des HERRN an mich folgendermaßen:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 34, 2, '»Menschensohn, richte deine Weissagungen gegen die Hirten Israels und sage zu ihnen: ›Zu den Hirten spricht Gott der HERR also: Wehe den Hirten Israels, die sich selbst geweidet haben! Ist’s nicht die Herde, welche die Hirten weiden sollen?');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 34, 3, 'Die Milch habt ihr genossen, mit der Wolle euch bekleidet und die fetten Tiere geschlachtet, aber meine Herde nicht geweidet.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 34, 4, 'Die schwachen Tiere habt ihr nicht gestärkt und die kranken nicht geheilt, die verwundeten nicht verbunden, die versprengten nicht zurückgeholt und die verirrten nicht aufgesucht, sondern mit Gewalt und Härte über sie geschaltet.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 34, 5, 'So haben denn (meine Schafe) sich zerstreut, weil sie keinen Hirten hatten, und sind in ihrer Zerstreuung eine Beute aller wilden Tiere geworden.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 34, 6, 'Auf allen Bergen und auf jedem hohen Hügel sind meine Schafe umhergeirrt, und über das ganze Land hin haben meine Schafe sich zerstreut, ohne daß sich jemand um sie gekümmert oder auf sie geachtet hätte.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 34, 7, 'Darum, ihr Hirten, vernehmt das Wort des HERRN!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 34, 8, 'So wahr ich lebe!‹ – so lautet der Ausspruch Gottes des HERRN –: ›weil meine Schafe geraubt und meine Schafe von allen wilden Tieren des Feldes gefressen worden sind, ohne daß ein Hirt da war, und weil meine Hirten sich nicht um meine Schafe gekümmert, sondern nur sich selbst, aber nicht meine Schafe geweidet haben:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 34, 9, 'darum, ihr Hirten, vernehmt das Wort des HERRN!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 34, 10, 'So spricht Gott der HERR: Nunmehr will ich an die Hirten und will meine Schafe von ihnen zurückfordern und ihrem Hirtenamt ein Ende machen, damit die Hirten nicht mehr sich selbst weiden! Nein, ich will meine Schafe ihnen aus dem Rachen reißen, daß sie von ihnen nicht mehr gefressen werden!‹«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 34, 11, 'Denn so hat Gott der HERR gesprochen: »Wisset wohl, ich selbst will jetzt nach meinen Schafen sehen und mich ihrer annehmen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 34, 12, 'Wie ein Hirt sich seiner Herde annimmt, sobald einige von seinen Schafen sich abgesondert haben, so will auch ich mich meiner Schafe annehmen und sie aus all den Orten zurückholen, wohin sie zerstreut worden sind am Tage des Gewölks und des Wetterdunkels.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 34, 13, 'Herausführen will ich sie aus den Völkern und sie sammeln aus den Ländern und sie in ihr Heimatland zurückbringen; da will ich sie weiden auf den Bergen Israels, in den Talgründen und in allen bewohnten Gegenden des Landes.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 34, 14, 'Auf guter Weide will ich sie weiden, und auf den Bergeshöhen Israels soll ihre Trift sein; dort sollen sie sich auf guter Trift lagern und fette Weide haben auf den Bergen Israels.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 34, 15, 'Ich selbst will der Hirt meiner Schafe sein und ich selbst sie lagern lassen« – so lautet der Ausspruch Gottes des HERRN.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 34, 16, '»Die verirrten will ich aufsuchen und die versprengten zurückholen, die verwundeten Tiere verbinden und die kranken gesund machen; die fetten und starken will ich behüten; ich werde sie weiden, wie es recht ist.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 34, 17, '»Ihr aber, meine Herde« – so hat Gott der HERR gesprochen –: »ich will nunmehr Gericht halten zwischen den Schafen untereinander und gegenüber den Widdern und den Böcken.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 34, 18, 'Genügt es euch nicht, die beste Weide abzuweiden? Müßt ihr auch noch das übrige Weideland mit den Füßen zertreten? Ihr habt klares Wasser zu trinken: müßt ihr da noch das übriggebliebene mit euren Füßen aufwühlen,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 34, 19, 'so daß meine Schafe das abweiden, was ihr mit euren Füßen zerstampft habt, und das trinken, was ihr mit euren Füßen aufgewühlt habt?«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 34, 20, 'Darum spricht Gott der HERR so zu ihnen: »Seht, nunmehr will ich selbst Gericht zwischen den fetten und den mageren Schafen halten.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 34, 21, 'Weil ihr die schwachen Tiere alle mit der Seite und Schulter weggedrängt und mit euren Hörnern gestoßen habt, bis ihr sie hinausgetrieben hattet,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 34, 22, 'so will ich nun meinen Schafen zu Hilfe kommen, damit sie euch nicht mehr zur Beute werden, und ich will zwischen den einzelnen Schafen Gericht halten.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 34, 23, '»Ich will aber einen einzigen Hirten über sie bestellen, der sie weiden soll, meinen Knecht David: der soll sie weiden, und der soll ihr Hirt sein!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 34, 24, 'Und ich, der HERR, will ihr Gott sein, und mein Knecht David soll Fürst in ihrer Mitte sein: ich, der HERR, bestimme es so!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 34, 25, 'Und ich will einen Friedensbund mit ihnen schließen und die bösen Tiere aus dem Lande verschwinden lassen, so daß sie sogar in der Steppe sicher wohnen und in den Wäldern schlafen können.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 34, 26, 'Ich will ihnen und der ganzen Umgebung meines Hügels Segen verleihen und den Regen zu rechter Zeit fallen lassen: segenspendende Regengüsse sollen es sein.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 34, 27, 'Die Bäume des Feldes sollen ihre Früchte bringen und das Ackerland seinen Ertrag geben; und sie sollen auf ihrem Grund und Boden sicher wohnen und erkennen, daß ich der HERR bin, wenn ich die Stäbe ihres Joches zerbreche und sie aus der Gewalt derer errette, die sie knechten.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 34, 28, 'Sie sollen alsdann nicht mehr eine Beute der Heidenvölker sein, und die Raubtiere des Landes sollen sie nicht mehr fressen, sondern sie sollen in Sicherheit wohnen, ohne daß jemand sie aufschreckt.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 34, 29, 'Und ich will ihnen eine ruhmeswerte Pflanzung aufsprießen lassen, so daß sie nicht mehr vom Hunger im Lande weggerafft werden und den Hohn der Heidenvölker nicht mehr zu erdulden haben.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 34, 30, 'Dann werden sie erkennen, daß ich, der HERR, ihr Gott, mit ihnen bin und daß sie, das Haus Israel, mein Volk sind« – so lautet der Ausspruch Gottes des HERRN.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 34, 31, '»Denn ihr seid meine Schafe, die Herde meiner Weide, und ich bin euer Gott!« – so lautet der Ausspruch Gottes des HERRN.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 35, 1, 'Weiter erging das Wort des HERRN an mich folgendermaßen:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 35, 2, '»Menschensohn, richte deine Blicke gegen das Gebirge Seir und verkünde folgende Weissagungen gegen dasselbe:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 35, 3, '›So hat Gott der HERR gesprochen: Nunmehr will ich an dich, Gebirge Seir, ich will meine Hand gegen dich ausstrecken und dich zur Wüste und Einöde machen!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 35, 4, 'Deine Städte will ich in Trümmer legen, und du selbst sollst zur Wüste werden, damit du erkennst, daß ich der HERR bin!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 35, 5, 'Weil du immerfort Feindschaft gehegt und die Israeliten zur Zeit ihres Unglücks, zur Zeit, als sie ihre Schuld endgültig büßten, dem Schwert ausgeliefert hast:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 35, 6, 'darum, so wahr ich lebe!‹ – so lautet der Ausspruch Gottes des HERRN –: ›bluten will ich dich machen, und Blut soll dich verfolgen! Weil du dich durch Blutvergießen verschuldet hast, soll Blut dich verfolgen!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 35, 7, 'Ich will das Gebirge Seir zur Wüste und Einöde machen und alle in ihm ausrotten, die da hin- und herziehen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 35, 8, 'Und ich will seine Berge überall mit Erschlagenen bedecken: auf deinen Höhen, in deinen Tälern und in allen deinen Schluchten sollen vom Schwert Erschlagene niedersinken.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 35, 9, 'Zu ewigen Wüsteneien will ich dich machen, und deine Städte sollen unbewohnt sein, damit ihr erkennt, daß ich der HERR bin.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 35, 10, 'Weil du gesagt hast: Die beiden Völker und die beiden Länder müssen mein werden, und ich will sie in Besitz nehmen! – obwohl doch der HERR dort wohnt:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 35, 11, 'darum, so wahr ich lebe!‹ – so lautet der Ausspruch Gottes des HERRN –, ›will ich entsprechend deinem eigenen Zorn und Eifer mit dir verfahren, wie du infolge deines Hasses gegen sie verfahren bist, und ich will mich dir zu erkennen geben, wenn ich mit dir ins Gericht gehe.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 35, 12, 'Dann wirst du auch erkennen, daß ich, der HERR, alle deine Lästerungen gehört habe, die du gegen das Bergland Israel ausgestoßen hast, indem du sagtest: Wüst liegt es da: uns ist es zum Verspeisen gegeben!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 35, 13, 'So habt ihr den Mund voll gegen mich genommen und vermessene Reden gegen mich ausgestoßen; ich habe es wohl gehört!‹');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 35, 14, 'So hat Gott der HERR gesprochen: ›Zur Freude der ganzen Erde will ich Verwüstung über dich bringen!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 35, 15, 'Wie du dich darüber gefreut hast, daß der Erbbesitz des Hauses Israel verwüstet wurde, ebenso will ich es dir widerfahren lassen: zur Wüste sollst du werden, Gebirge Seir, und du, Edom, insgesamt, damit du zur Erkenntnis kommst, daß ich der HERR bin!‹«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 36, 1, '»Du aber, Menschensohn, sprich über das Bergland Israel folgende Weissagung aus: ›Ihr Berge Israels, vernehmt das Wort des HERRN!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 36, 2, 'So hat Gott der HERR gesprochen: Weil der Feind über euch ausgerufen hat: Haha! Die Höhen sind verwüstet auf ewig, als Eigentum uns zugefallen! –,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 36, 3, 'darum sprich folgende Weissagungen aus: So hat Gott der HERR gesprochen: Darum, ja eben darum, weil man euch angeschnaubt und von allen Seiten über euch gieriges Verlangen nach euch getragen hat, so daß ihr in den Besitz der noch übriggebliebenen Heidenvölker gekommen und ins Gerede der Zungen und in die üble Nachrede der Leute geraten seid –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 36, 4, 'darum, ihr Berge Israels, vernehmt das Wort Gottes des HERRN! So spricht Gott der HERR zu den Bergen und Hügeln, zu den Tälern und Schluchten, zu den öden Trümmerstätten und den verlassenen Städten, die den noch übriggebliebenen Heidenvölkern ringsum zur Beute und zum Gespött geworden sind –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 36, 5, 'darum spricht Gott der HERR also: Wahrlich, in glühendem Eifer rede ich gegen die noch übriggebliebenen Heidenvölker und gegen das gesamte Edom, weil sie mit schadenfrohen Herzen und völliger Gefühllosigkeit sich in den Besitz meines Landes gesetzt haben, um die Bewohner auszutreiben und auszuplündern.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 36, 6, 'Darum weissage über das Land Israel und richte an die Berge und Hügel, an die Täler und Schluchten die Worte: So hat Gott der HERR gesprochen: Fürwahr, in meinem Eifer und in meinem Grimm rede ich, weil ihr den Hohn der Heidenvölker habt tragen müssen!‹');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 36, 7, 'Darum spricht Gott der HERR also: Ich hebe meine Hand auf zum Schwur, daß die Völkerschaften, die um euch her wohnen, ihre Schmähung selbst tragen sollen!‹«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 36, 8, '»›Ihr aber, ihr Berge Israels, sollt eure Zweige sprossen lassen und eure Früchte tragen für mein Volk Israel, denn gar bald werden sie heimkehren!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 36, 9, 'Denn wisset wohl: ich werde zu euch kommen und mich euch wieder zuwenden, und ihr sollt wieder besät und bepflanzt werden.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 36, 10, 'Ich will die Menschen auf euch zahlreich werden lassen, das ganze Haus Israel insgesamt, die Städte sollen wieder bewohnt und die Trümmer neu aufgebaut werden.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 36, 11, 'Und ich werde Menschen und Vieh auf euch zahlreich machen: sie sollen sich mehren und fruchtbar sein; und ich will euch wieder bewohnt sein lassen wie in euren früheren Zeiten und euch noch mehr Gutes erweisen als je zuvor, damit ihr erkennt, daß ich der HERR bin!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 36, 12, 'Menschen will ich wieder auf euch wandeln lassen, nämlich mein Volk Israel: die sollen dich wieder in Besitz nehmen, und du sollst ihnen als Erbbesitz gehören und sie hinfort nicht mehr ihrer Kinder berauben!‹«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 36, 13, 'So hat Gott der HERR (zum Lande) gesprochen: »Weil man dir vorgeworfen hat, du seiest eine Menschenfresserin gewesen und eine Kindesmörderin für dein eigenes Volk,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 36, 14, 'darum sollst du hinfort keine Menschen mehr fressen und dein Volk nicht mehr kinderlos machen!« – so lautet der Ausspruch Gottes des HERRN.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 36, 15, '»Und ich will dich hinfort nicht länger die Schmähung der Heiden hören lassen, und den Hohn der Völker sollst du nicht mehr zu tragen haben und sollst deine Bevölkerung nicht mehr ihrer Kinder berauben!« – so lautet der Ausspruch Gottes des HERRN.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 36, 16, 'Weiter erging das Wort des HERRN an mich folgendermaßen:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 36, 17, '»Menschensohn, solange die vom Hause Israel in ihrem Lande wohnten, verunreinigten sie es durch ihren Wandel und ihr ganzes Tun; ihr Wandel war vor meinen Augen wie die Unreinheit einer Frau, die ihren Blutgang hat.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 36, 18, 'Da ließ ich denn meinem Zorn gegen sie freien Lauf wegen des Blutes, das sie im Lande vergossen hatten, und wegen ihres Götzendienstes, durch den sie es verunreinigt hatten.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 36, 19, 'Ich zerstreute sie also unter die Heidenvölker, und sie wurden in die Länder versprengt: nach ihrem Wandel und ihrem ganzen Tun ging ich mit ihnen ins Gericht.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 36, 20, 'Als sie nun unter die Heidenvölker kamen, da brachten sie, wohin sie kamen, meinen heiligen Namen in Unehre, indem man von ihnen sagte: ›Das Volk des HERRN sind diese, und doch haben sie aus seinem Lande wegziehen müssen!‹');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 36, 21, 'Da tat es mir leid um meinen heiligen Namen, weil das Haus Israel ihn unter den Heidenvölkern überall, wohin sie kamen, in Unehre brachte.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 36, 22, 'Darum sage zum Hause Israel: ›So hat Gott der HERR gesprochen: Nicht um euretwillen, Haus Israel, greife ich ein, sondern um meines heiligen Namens willen, den ihr unter den Heidenvölkern überall entehrt habt, wohin ihr gekommen seid.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 36, 23, 'So will ich denn meinen großen Namen, der unter den Heiden entheiligt worden ist, weil ihr ihn unter ihnen entheiligt habt, wieder zu Ehren bringen, damit die Heiden erkennen, daß ich der HERR bin‹ – so lautet der Ausspruch Gottes des HERRN –, ›wenn ich mich vor ihren Augen an euch als den Heiligen erweise.‹«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 36, 24, '»›Ich will euch also aus den Heidenvölkern herausholen und euch aus allen Ländern sammeln und euch in euer Land zurückbringen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 36, 25, 'Dann will ich reines Wasser über euch sprengen, damit ihr rein werdet: von all euren Befleckungen und von all eurem Götzendienst will ich euch reinigen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 36, 26, 'Und ich will euch ein neues Herz verleihen und euch einen neuen Geist eingeben: das steinerne Herz will ich aus eurer Brust herausnehmen und euch dafür ein Herz von Fleisch verleihen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 36, 27, 'Ich will meinen Geist in euer Inneres geben und will solche Leute aus euch machen, die nach meinen Satzungen wandeln und meine Weisungen beobachten und tatsächlich ausführen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 36, 28, 'Dann sollt ihr wohnen bleiben in dem Lande, das ich euren Vätern gegeben habe; ihr sollt mein Volk sein, und ich will euer Gott sein.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 36, 29, 'Wenn ich euch alsdann von all euren Befleckungen befreit habe, will ich den Getreidesegen herbeirufen und ihn mehren und keine Hungersnot mehr über euch verhängen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 36, 30, 'Auch die Früchte der Bäume und den Ertrag der Felder will ich mehren, damit ihr euch nicht noch einmal unter den Heidenvölkern wegen einer Hungersnot schmähen lassen müßt.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 36, 31, 'Wenn ihr alsdann an euren bösen Wandel zurückdenkt und an euer ganzes verwerfliches Tun, so werdet ihr vor euch selbst einen Abscheu empfinden wegen eurer Verschuldungen und eurer Greuel.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 36, 32, 'Nicht um euretwillen greife ich ein‹ – so lautet der Ausspruch Gottes des HERRN –: ›das sei euch kundgetan! Schämt euch vielmehr und errötet über euren Wandel, ihr vom Hause Israel!‹«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 36, 33, 'So hat Gott der HERR gesprochen: »Zu derselben Zeit, wo ich euch von all euren Verschuldungen reinige, will ich auch die Städte neu bevölkern, und die Trümmer sollen wieder aufgebaut werden;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 36, 34, 'das verödete Land soll aufs neue bestellt werden, während es zuvor als Wüste vor den Augen aller Vorüberziehenden dagelegen hat.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 36, 35, 'Dann wird man sagen: ›Dieses Land, das verödet dalag, ist wie der Garten Eden geworden, und die Städte, die in Trümmern lagen und verwüstet und zerstört waren, sind jetzt wohlbefestigt und volkreich.‹');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 36, 36, 'Da werden dann die Völkerschaften, die rings um euch her übriggeblieben sind, zu der Erkenntnis kommen, daß ich, der HERR, es bin, der das Zerstörte neu aufgebaut und das Verwüstete neu bepflanzt hat. Ich, der HERR, habe es verheißen und werde es auch vollführen!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 36, 37, 'So hat Gott der HERR gesprochen: »Auch darin will ich mich noch vom Hause Israel erbitten lassen, daß ich es ihnen gewähre: ich will sie an Menschen so zahlreich werden lassen wie eine Herde von Schafen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 36, 38, 'Wie der Tempel von Opferschafen, wie Jerusalem an seinen hohen Festen von Schafen, so sollen die jetzt verödeten Städte voll von Menschenherden sein, damit man erkennt, daß ich der HERR bin.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 37, 1, 'Die Hand des HERRN kam über mich: er führte mich im Zustande der Verzückung hinaus und ließ mich mitten in der Tal-Ebene nieder, die voll von Totengebeinen war.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 37, 2, 'Er führte mich ringsherum an diesen vorüber; und siehe, es lagen ihrer sehr viele über die ganze Tal-Ebene hin, aber alle waren ganz verdorrt.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 37, 3, 'Da fragte er mich: »Menschensohn, können wohl diese Gebeine wieder lebendig werden?« Ich antwortete: »HERR, mein Gott, du weißt es.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 37, 4, 'Hierauf gebot er mir: »Weissage über diese Gebeine und rufe ihnen zu: ›Ihr verdorrten Gebeine, vernehmt das Wort des HERRN!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 37, 5, 'So hat Gott der HERR zu diesen Gebeinen gesagt: Fürwahr, ich will Odem in euch kommen lassen, damit ihr wieder lebendig werdet,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 37, 6, 'und will Sehnen an euch schaffen und Fleisch über euch wachsen lassen, ich will euch mit Haut überziehen und euch Odem einflößen, damit ihr wieder lebendig werdet und erkennt, daß ich der HERR bin.‹«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 37, 7, 'Da weissagte ich, wie mir geboten war; und als ich geweissagt hatte, entstand plötzlich ein Rascheln, und die Gebeine fügten sich zusammen, eins an das andere.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 37, 8, 'Als ich nun hinschaute, nahm ich wohl Sehnen an ihnen wahr, und Fleisch war über sie gewachsen, und mit Haut waren sie oben überzogen, aber Odem war noch nicht in ihnen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 37, 9, 'Da sagte er zu mir: »Richte eine Weissagung an den Odem, ja weissage, Menschensohn, und sprich zu dem Lebensgeist: ›So hat Gott der HERR gesprochen: O Geist, komm von den vier Winden herbei und hauche diese Erschlagenen an, daß sie wieder lebendig werden!‹«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 37, 10, 'Als ich nun so weissagte, wie er mir geboten hatte, da kam der Lebensgeist in sie, so daß sie lebendig wurden und auf ihre Füße traten, eine gewaltig große Heerschar.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 37, 11, 'Hierauf sagte er zu mir: »Menschensohn, diese Gebeine hier sind das ganze Haus Israel. Siehe, sie sagen jetzt: ›Verdorrt sind unsere Gebeine, und geschwunden ist unsere Hoffnung: es ist aus mit uns!‹');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 37, 12, 'Darum weissage du und sage zu ihnen: ›So hat Gott der HERR gesprochen: Wisset wohl: ich will eure Gräber öffnen und euch, mein Volk, aus euren Gräbern hervorgehen lassen und euch in das Land Israel zurückbringen:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 37, 13, 'dann werdet ihr erkennen, daß ich der HERR bin, wenn ich eure Gräber öffne und euch, mein Volk, aus euren Gräbern hervorgehen lasse.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 37, 14, 'Ich will also meinen Geist in euch kommen lassen, daß ihr lebendig werdet, und will euch wieder in euer Land versetzen, damit ihr erkennt, daß ich, der HERR, es verheißen habe und es auch zur Ausführung bringe!‹ – so lautet der Ausspruch des HERRN.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 37, 15, 'Weiter erging das Wort des HERRN an mich folgendermaßen:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 37, 16, '»Du, Menschensohn, nimm dir einen Holzstab und schreibe darauf: ›Juda und die mit ihm vereinten Israeliten‹. Sodann nimm noch einen anderen Holzstab und schreibe darauf: ›Joseph, der Stab Ephraims und des ganzen mit ihm vereinten Hauses Israel‹.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 37, 17, 'Dann füge dir beide Holzstäbe zu einem einzigen Stabe zusammen, so daß sie ein Ganzes in deiner Hand bilden!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 37, 18, '»Wenn dann deine Volksgenossen zu dir sagen: ›Willst du uns nicht erklären, was dies bedeuten soll?‹,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 37, 19, 'so antworte ihnen: ›So hat Gott der HERR gesprochen: Seht, ich werde den Stab Josephs und der mit ihm vereinten Stämme Israels, der in der Hand Ephraims ist, nehmen und ihn zu dem Stabe Judas hinzutun und sie (beide) zu einem einzigen Stabe machen, so daß sie ein Ganzes in meiner Hand bilden.‹');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 37, 20, 'Wenn du dann die Stäbe, die du mit Inschriften versehen hast, vor ihren Augen in deiner Hand hältst,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 37, 21, 'so sage zu ihnen: ›So hat Gott der HERR gesprochen: Wisset wohl: ich will die Kinder Israels aus den Heidenvölkern, unter die sie haben ziehen müssen, herausholen und sie von allen Seiten her sammeln und sie in ihr Land zurückbringen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 37, 22, 'Ich will sie dann zu einem einzigen Volk machen in dem Lande, auf den Bergen Israels, so daß ein einziger König über sie alle herrscht; sie sollen alsdann nicht wieder zwei Völker bilden und nicht wieder in zwei Reiche geteilt sein.‹«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 37, 23, '»›Dann sollen sie sich nicht mehr an ihren Götzen und abscheulichen Abgöttern und durch all ihre Abfallssünden verunreinigen; nein, ich will sie frei machen von all ihren Treubrüchen, durch die sie sich versündigt haben, und will sie reinigen; dann sollen sie mein Volk werden, und ich will ihr Gott sein.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 37, 24, 'Mein Knecht David aber soll König über sie sein, und sie sollen alle einen einzigen Hirten haben; dann werden sie nach meinen Weisungen wandeln, meine Satzungen beobachten und nach ihnen handeln.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 37, 25, 'Sie sollen dann wieder in dem Lande wohnen, das ich meinem Knecht Jakob gegeben habe und in welchem ihre Väter gewohnt haben; auch sie sollen darin wohnen samt ihren Kindern und Kindeskindern bis in Ewigkeit; und mein Knecht David soll ihr Herrscher sein für immer.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 37, 26, 'Dann will ich auch einen Friedensbund mit ihnen schließen, ein ewiger Bund soll mit ihnen bestehen; und ich will sie seßhaft machen und mehren und mein Heiligtum in ihrer Mitte belassen ewiglich.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 37, 27, 'Meine Wohnung aber wird über ihnen sein; ich will ihr Gott sein, und sie sollen mein Volk sein.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 37, 28, 'Auch die Heidenvölker werden dann erkennen, daß ich der HERR bin, der Israel heiligt, wenn mein Heiligtum sich in ihrer Mitte befindet ewiglich!‹«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 38, 1, 'Das Wort des HERRN erging weiter an mich folgendermaßen:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 38, 2, '»Menschensohn, richte deine Blicke auf Gog im Lande Magog, den Fürsten von Ros, Mesech und Thubal, und sprich folgende Weissagungen über ihn aus:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 38, 3, '›So hat Gott der HERR gesprochen: Nunmehr will ich an dich, Gog, Fürst von Ros, Mesech und Thubal!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 38, 4, 'Ich will dich herbeilocken und dir Haken in die Kinnbacken legen und dich ins Feld ziehen lassen mit deiner ganzen Kriegsmacht, Rosse und Reiter, allesamt in voller Ausrüstung, ein gewaltiges Heer mit Schilden und Tartschen, durchweg mit Schwertern bewaffnet:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 38, 5, 'Perser, Äthiopier und Libyer befinden sich unter ihnen, allesamt mit Schild und Helm;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 38, 6, 'Kimmerier mit all ihren Scharen, das Haus Thogarma aus dem äußersten Norden mit all seinen Scharen: ja viele Völker sind mit dir.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 38, 7, 'Rüste dich und halte dich bereit, du mit all deinen Scharen, die sich bei dir gesammelt haben, und sei du ihr Anführer!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 38, 8, 'Nach geraumer Zeit sollst du Befehl erhalten: am Ende der Jahre sollst du über ein Land kommen, das sich vom Kriege erholt hat, (zu einem Volk) das aus vielen Völkern auf den Bergen Israels, die dauernd verödet lagen, gesammelt worden ist; jetzt aber ist es aus den Völkern zurückgeführt, und sie wohnen nun in Sicherheit allesamt.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 38, 9, 'Da wirst du dann heranziehen, wie ein Ungewitter daherkommen, wirst wie eine Wetterwolke sein, um das Land zu bedecken, du und alle deine Scharen und die Völkermenge mit dir.‹«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 38, 10, 'So hat Gott der HERR gesprochen: »Zu jener Zeit werden (böse) Gedanken in deinem Herzen aufsteigen, und du wirst einen schlimmen Anschlag ersinnen;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 38, 11, 'du wirst nämlich denken: ›Ich will zu Felde ziehen gegen ein Land von Bauernhöfen, will über friedliche Leute herfallen, die ruhig und sorglos leben; sie wohnen ja allesamt (in Ortschaften) ohne Mauern und haben keine Riegel und Tore.‹');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 38, 12, '(Gegen diese gedenkst du zu ziehen,) um schonungslos zu rauben und Beute zu machen, um deine Hand an wiederbewohnte Trümmerstätten zu legen und an ein Volk, das aus den Heidenländern gesammelt worden ist, das sich Hab und Gut erworben hat und auf dem Nabel der Erde wohnt.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 38, 13, 'Seba und Dedan und ihre Kaufleute, Tharsis und all seine raubgierigen Löwen werden zu dir sagen: ›Bist du gekommen, um Beute zu machen? Hast du deine Scharen aufgeboten, um zu plündern, um Silber und Gold zu rauben, um Hab und Gut wegzunehmen, um reiche Beute zu machen?‹');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 38, 14, 'Darum verkünde, Menschensohn, dem Gog folgende Weissagungen: ›So hat Gott der HERR gesprochen: Jawohl, zu jener Zeit, wo mein Volk Israel wieder in Sicherheit wohnt, wirst du aufbrechen');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 38, 15, 'und von deinem Wohnsitz, vom äußersten Norden her, kommen, du und viele Völker mit dir, allesamt hoch zu Roß, eine große Schar und ein gewaltiges Heer;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 38, 16, 'und du wirst gegen mein Volk Israel heranziehen wie eine Wetterwolke, um das Land zu bedecken. Am Ende der Tage wird es geschehen, daß ich dich gegen mein Land zu Felde ziehen lasse, damit die Heidenvölker mich kennenlernen, wenn ich mich vor ihren Augen an dir, Gog, als den Heiligen erweise.‹«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 38, 17, 'So hat Gott der HERR (zu Gog) gesprochen: »Bist du es nicht, auf den ich in früheren Tagen durch den Mund meiner Knechte, der Propheten Israels, hingewiesen habe, die zu jener Zeit jahrelang geweissagt haben, daß ich dich gegen sie heranführen würde?');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 38, 18, 'So wird denn an demselben Tage, an dem Gog in das Land Israel einrückt« – so lautet der Ausspruch Gottes des HERRN –, »da wird die Zornesglut in mir auflodern;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 38, 19, 'und in meinem Zorneseifer, im Feuer meines Ingrimms spreche ich es aus: ›Wahrlich, an jenem Tage wird ein großes Erdbeden im Lande Israel stattfinden!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 38, 20, 'Da sollen vor mir erbeben die Fische im Meer und die Vögel unter dem Himmel, die Tiere auf dem Felde und alles Gewürm, das auf dem Erdboden kriecht, und alle Menschen, die auf der ganzen Erde wohnen; die Berge sollen einstürzen und die Felswände umfallen und alle Mauern zu Boden stürzen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 38, 21, 'Dann werde ich in meinem ganzen Berglande das Schwert gegen ihn aufbieten‹ – so lautet der Ausspruch Gottes des HERRN –, ›so daß das Schwert eines jeden sich gegen den andern kehrt.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 38, 22, 'Und ich will das Strafgericht an ihm vollziehen durch Pest und Blutvergießen, durch Wolkenbrüche und Hagelsteine; Feuer und Schwefel will ich regnen lassen auf ihn und auf seine Kriegsscharen und auf die vielen Völker, die bei ihm sind.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 38, 23, 'So will ich meine Größe und meine Heiligkeit erweisen und mich vor den Augen vieler Völker kundtun, damit sie erkennen, daß ich der HERR bin!‹«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 39, 1, '»Du also, Menschensohn, sprich gegen Gog folgende Weissagungen aus: ›So hat Gott der HERR gesprochen: Wisse wohl: ich will an dich, Gog, Fürst von Ros, Mesech und Thubal!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 39, 2, 'Ich will dich herbeilocken und am Gängelbande führen und dich vom äußersten Norden heranziehen lassen und dich auf die Berge Israels kommen lassen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 39, 3, 'Aber (dort) will ich dir den Bogen aus der linken Hand schlagen und die Pfeile deiner rechten Hand entfallen lassen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 39, 4, 'Auf den Bergen Israels sollst du fallen, du selbst und alle deine Scharen und die Völker, die bei dir sind; den Raubvögeln, allem Getier, das Flügel hat, und den Raubtieren des Feldes überlasse ich dich zum Fraß:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 39, 5, 'auf freiem Felde sollst du fallen; denn ich habe es gesagt!‹ – so lautet der Ausspruch Gottes des HERRN.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 39, 6, '›Da will ich an Magog und an die in Sorglosigkeit lebenden Bewohner der Meeresländer Feuer legen, damit sie erkennen, daß ich der HERR bin.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 39, 7, 'Aber inmitten meines Volkes Israel will ich meinem heiligen Namen Anerkennung verschaffen und werde meinen heiligen Namen nicht länger entweihen lassen, damit die Heidenvölker erkennen, daß ich der HERR bin, der Heilige in Israel.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 39, 8, 'Wisse wohl: es kommt und geht in Erfüllung!‹ – so lautet der Ausspruch Gottes des HERRN –; ›das ist der Tag, auf den ich hingewiesen habe!‹«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 39, 9, '»Da werden denn die Bewohner der Städte Israels hinausziehen und Feuer anmachen und einheizen mit den Waffen, den Kurzschilden und Langschilden, mit den Bogen und Pfeilen, mit den Keulen und Lanzen, und werden sieben Jahre lang Feuer mit ihnen machen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 39, 10, 'Die brauchen dann kein Holz mehr vom Felde zu holen und keins in den Wäldern zu hauen, sondern werden die Waffen als Brennholz benutzen und Raub gewinnen von denen, welche sie beraubt hatten, und die plündern, welche sie geplündert hatten« – so lautet der Ausspruch Gottes des HERRN.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 39, 11, '»Und an jenem Tage werde ich dem Gog eine Grabstätte in Israel anweisen, nämlich das Tal der Wanderer auf der Ostseite des (Toten) Meeres: dies wird ihrem Wanderzuge ein Ende machen. Dort wird man Gog und seine gesamte Heeresmacht begraben und es das ›Tal der Heeresmacht Gogs‹ nennen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 39, 12, 'Das Haus Israel wird dann sieben Monate lang mit ihrem Begräbnis zu tun haben, um das Land zu reinigen;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 39, 13, 'und die gesamte Bevölkerung des Landes wird sich an dem Begräbnis beteiligen; und das wird ihnen zum Ruhm gereichen an dem Tage, wo ich mich verherrlichen werde« – so lautet der Ausspruch Gottes des HERRN.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 39, 14, '»Dann wird man Männer bestellen, die das ständige Geschäft haben, im Lande umherzuziehen, um die von dem Wandervolk im Lande noch liegengebliebenen Toten zu begraben und so (das ganze Land) zu reinigen; nach Ablauf der sieben Monate sollen sie die Durchsuchung vornehmen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 39, 15, 'Wenn sie dann auf ihrer Wanderung das Land durchziehen und einer von ihnen ein Menschengerippe erblickt, so soll er ein Mal daneben errichten, bis die Totengräber es im Tal der Heeresmacht Gogs begraben haben.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 39, 16, 'Auch wird es dort eine Stadt namens Hamona geben. So sollen sie das Land reinigen.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 39, 17, '»Du aber, Menschensohn« – so hat Gott der HERR gesprochen –, »sage zu den Vögeln, zu allem Getier, das Flügel hat, und zu allen Raubtieren des Feldes: ›Versammelt euch und kommt herbei! Schart euch von allen Seiten her zusammen zu meinem Opferschmaus, den ich euch veranstalte, zu dem großen Opferschmaus auf den Bergen Israels! Ihr sollt Fleisch fressen und Blut trinken!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 39, 18, 'Fleisch von Heerführern sollt ihr fressen und das Blut von Fürsten der Erde trinken: Widder und Lämmer, Böcke und Stiere, lauter Mastvieh aus Basan;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 39, 19, 'in Fett sollt ihr euch satt fressen und Blut bis zur Trunkenheit trinken von meinem Opferschmaus, den ich euch veranstalte.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 39, 20, 'An meiner Tafel sollt ihr euch sättigen an Rossen und Reitern, an Heerführern und Kriegsleuten aller Art!‹« – so lautet der Ausspruch Gottes des HERRN.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 39, 21, '»So will ich denn meine Herrlichkeit unter den Heidenvölkern offenbar werden lassen, und alle Heidenvölker sollen mein Strafgericht sehen, das ich vollzogen habe, und meine Hand, die ich sie habe fühlen lassen;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 39, 22, 'das Haus Israel aber wird erkennen, daß ich, der HERR, ihr Gott bin, von jenem Tage an und weiterhin;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 39, 23, 'und die Heidenvölker werden erkennen, daß das Haus Israel um seiner Verschuldung willen in die Verbannung hat wandern müssen zur Strafe dafür, daß sie treulos gegen mich geworden waren, und weil ich mein Angesicht vor ihnen verborgen und sie der Gewalt ihrer Feinde preisgegeben hatte, so daß sie allesamt durch das Schwert fallen mußten.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 39, 24, 'Wie ihre Unreinheit und ihre Treubrüche es verdienten, so bin ich mit ihnen verfahren und habe mein Angesicht vor ihnen verborgen.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 39, 25, 'Darum hat Gott der HERR so gesprochen: »Nunmehr will ich das Geschick Jakobs wenden und mich des gesamten Hauses Israel erbarmen und für meinen heiligen Namen eifern.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 39, 26, 'Dann sollen sie ihre Schmach und alle ihre Treulosigkeit, die sie sich gegen mich haben zuschulden kommen lassen, vergessen, wenn sie wieder sicher in ihrem Lande wohnen und niemand sie mehr aufschreckt.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 39, 27, 'Wenn ich sie aus den Völkern zurückgebracht und sie aus den Ländern ihrer Feinde gesammelt und mich vor den Augen der Heidenvölker als den Heiligen an ihnen erwiesen habe,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 39, 28, 'dann werden sie auch erkennen, daß ich, der HERR, ihr Gott bin, der ich sie zwar unter die Heidenvölker in die Gefangenschaft geführt habe, aber sie nun auch wieder in ihrem Lande versammle und fortan keinen von ihnen dort zurücklasse.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 39, 29, 'Und ich werde mein Angesicht nicht mehr vor ihnen verbergen, weil ich (alsdann) meinen Geist auf das Haus Israel ausgegossen habe«, – so lautet der Ausspruch Gottes des HERRN.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 1, 'Im fünfundzwanzigsten Jahre unserer Verbannung, im Anfang des Jahres, am zehnten Tage des Monats, im vierzehnten Jahre nach der Eroberung der Stadt (Jerusalem) – an eben diesem Tage kam die Hand des HERRN über mich und brachte mich dorthin;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 2, 'im Zustand der Verzückung führte er mich ins Land Israel und ließ mich auf einem sehr hohen Berge nieder, auf dessen Südseite sich ein Bauwerk nach Art einer Stadt befand.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 3, 'Als er mich dorthin gebracht hatte, da stand dort mit einemmal ein Mann, der sah aus, als wäre er von Erz; er hatte eine leinene Schnur und einen Meßstab in der Hand und stand im Tor.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 4, 'Dieser Mann redete mich so an: »Menschensohn, gib genau acht mit deinen Augen und mit deinen Ohren und richte deine Aufmerksamkeit auf alles, was ich dir zeigen werde; denn dazu bist du hierher gebracht worden, daß man es dir zeige. Berichte dem Hause Israel alles, was du hier zu sehen bekommst!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 5, 'Da sah ich eine Mauer, die außen den Tempel(-bezirk) rings umgab; der Meßstab aber, den der Mann in der Hand hielt, war sechs Ellen lang, jede Elle zu einer gewöhnlichen Elle und einer Handbreite gerechnet; mit diesem maß er die Breite des Mauerbaues: sie betrug eine Rute und die Höhe auch eine Rute.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 6, 'Nun trat er in den Torbau, dessen Vorderseite nach Osten zu lag; er stieg auf dessen (sieben) Stufen hinauf und maß die Schwelle des Tores: eine Rute breit;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 7, 'sodann die (erste) Wachtstube: eine Rute lang und eine Rute breit, und den Raum zwischen den Wachtstuben: fünf Ellen; und die Schwelle des Tores neben der Vorhalle des Tores auf der Innenseite: eine Rute.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 8, 'Dann maß er die Vorhalle des Tores:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 9, 'acht Ellen, und ihre Wandpfeiler: zwei Ellen; die Vorhalle des Tores lag aber nach innen zu.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 10, 'Von den Wachtstuben des Osttores lagen drei auf der einen und drei auf der andern Seite; alle drei waren gleich groß; und ebenso hatten auch die Wandpfeiler auf beiden Seiten einerlei Maß.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 11, 'Dann maß er die Breite des Toreingangs: zehn Ellen, und die Länge des Torweges: dreizehn Ellen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 12, 'An der Vorderseite der Wachtstuben befand sich eine Einfriedigung von je einer Elle Breite auf dieser wie auf jener Seite, während die Wachtstube selbst sechs Ellen im Geviert maß.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 13, 'Dann maß er das Torgebäude von der Hinterwand einer Wachtstube bis zu der Hinterwand der gegenüberliegenden Wachtstube: fünfundzwanzig Ellen Breite, Tür gegen Tür.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 14, 'Hierauf bestimmte er die Wandpfeiler zu sechzig Ellen, und an die Wandpfeiler stieß der Vorhof rings um das Torgebäude,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 15, 'und von der Vorderseite des Eingangstores bis an die Vorderseite der inneren Vorhalle des Tores waren es fünfzig Ellen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 16, 'Fenster, die nach den Wachtstuben und nach ihren Wandpfeilern nach innen zu schräg einfielen, befanden sich am Torgebäude ringsherum; und ebenso hatte auch die Vorhalle Fenster ringsherum nach innen zu; an den Wandpfeilern aber waren Palmenverzierungen (auf beiden Seiten) angebracht.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 17, 'Sodann führte er mich in den äußeren Vorhof, wo sich zunächst Zellen befanden, und ein Steinpflaster war im Vorhof ringsum hergestellt: dreißig Zellen lagen an dem Steinpflaster hin.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 18, 'Dieses Steinpflaster befand sich aber an der Seitenwand der Tore, entsprechend der Länge der Tore, nämlich das untere Steinpflaster.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 19, 'Dann maß er die Breite des Vorhofs von der inneren Vorderseite des unteren Tores bis zur Vorderseite des inneren Vorhofs nach außen zu: hundert Ellen [an der Ostseite und an der Nordseite].');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 20, '(Sodann führte er mich in der Richtung nach Norden; dort war) ein Tor, dessen Vorderseite nach Norden zu lag, am äußeren Vorhof; auch dessen Länge und Breite maß er.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 21, 'Von seinen Wachtstuben lagen drei auf der einen und drei auf der andern Seite; und seine Wandpfeiler und seine Vorhalle hatten dieselben Maße wie das erste Tor: fünfzig Ellen betrug seine Länge und fünfundzwanzig Ellen seine Breite.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 22, 'Auch seine Fenster und die Fenster seiner Vorhalle sowie seine Palmenverzierungen waren ebenso wie beim Osttor. Auf sieben Stufen stieg man zu ihm hinauf, und seine Vorhalle lag nach innen zu.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 23, 'Und ein Tor, das in den inneren Vorhof führte, und dem äußeren Nordtor gegenüber lag, entsprach dem Osttor; und er maß von Tor zu Tor hundert Ellen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 24, 'Hierauf führte er mich in der Richtung nach Süden; und da sah ich in der Richtung nach Süden ein Tor; er maß seine Wachtstuben, seine Wandpfeiler und die Vorhalle und fand bei diesen dieselben Maße.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 25, 'Es waren auch Fenster darin vorhanden, ebenso wie in seiner Vorhalle ringsum, deren Maße den schon erwähnten Fenstern gleich waren; die Länge betrug fünfzig, die Breite fünfundzwanzig Ellen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 26, 'Eine Treppe von sieben Stufen führte zu ihm hinauf; und seine Vorhalle lag nach der Innenseite zu und hatte Palmenverzierungen an ihren Wandpfeilern sowohl auf dieser wie auf jener Seite.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 27, 'Auch befand sich ein Tor zum inneren Vorhof in der Richtung nach Süden; und er maß von dem einen Tor zum andern in der Richtung nach Süden: hundert Ellen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 28, 'Darauf führte er mich durch das Südtor in den inneren Vorhof und maß das Südtor aus, das die gleichen Maße hatte wie die vorerwähnten;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 29, 'auch seine Wachtstuben, seine Wandpfeiler und seine Vorhalle wiesen die gleichen Maße auf; es besaß auch Fenster ebenso wie seine Vorhalle ringsherum; die Länge betrug fünfzig, die Breite fünfundzwanzig Ellen');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 30, '[und Vorhallen lagen ringsherum, fünfundzwanzig Ellen lang und fünf Ellen breit].');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 31, 'Seine Vorhalle aber lag nach dem äußeren Vorhof zu, und Palmenverzierungen waren an seinen Wandpfeilern angebracht; eine Treppe von acht Stufen führte zu ihm hinauf. –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 32, 'Sodann führte er mich [in den inneren Vorhof] zu dem Tor, das gegen Osten lag, und maß das Tor aus: es hatte dieselben Maße wie die anderen;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 33, 'auch seine Wachtstuben, seine Wandpfeiler und seine Vorhalle wiesen die gleichen Maße auf; es besaß auch Fenster ebenso wie seine Vorhalle ringsherum; die Länge betrug fünfzig, die Breite fünfundzwanzig Ellen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 34, 'Seine Vorhalle aber lag nach dem äußeren Vorhof zu; und Palmenverzierungen waren an seinen Wandpfeilern auf dieser wie auf jener Seite angebracht; eine Treppe von acht Stufen führte zu ihm hinauf. –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 35, 'Sodann führte er mich zu dem Nordtor und maß es aus: es hatte die gleichen Maße wie die vorerwähnten;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 36, 'auch seine Wachtstuben, seine Wandpfeiler und seine Vorhalle wiesen die gleichen Maße auf; es besaß auch Fenster ringsherum (ebenso wie seine Vorhalle); die Länge betrug fünfzig, die Breite fünfundzwanzig Ellen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 37, 'Seine Vorhalle lag nach dem äußeren Vorhof zu; und Palmenverzierungen waren an seinen Wandpfeilern auf dieser wie auf jener Seite angebracht; eine Treppe von acht Stufen führte zu ihm hinauf.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 38, 'Auch eine Zelle war da, deren Eingang sich an den Pfeilern des Tores befand; dort hatte man das Brandopfer abzuspülen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 39, 'In der Vorhalle des Tores aber waren zwei Tische auf der einen Seite und zwei Tische auf der andern Seite aufgestellt, um auf ihnen das Brandopfer, das Sünd- und Schuldopfer zu schlachten.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 40, 'Auch an der äußeren Seitenwand, an der Nordseite, wenn man zum Toreingang hinaufstieg, standen zwei Tische, und an der anderen Seitenwand der Vorhalle des Tores gleichfalls zwei Tische,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 41, 'also vier Tische auf der einen Seite und vier Tische auf der andern Seite an der Seitenwand des Tores, zusammen acht Tische, auf denen man die Schlachtopfer schlachten sollte.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 42, 'Weiter waren noch vier Tische für Brandopfer aus behauenen Steinen aufgestellt, anderthalb Ellen lang, anderthalb Ellen breit und eine Elle hoch; auf diese hatte man die Geräte zu legen, mit denen man die Brand- und Schlachtopfertiere schlachtete.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 43, 'Ringsherum an diesen Tischen, nach innen (geneigt), waren feste Leisten angebracht, eine Handbreite hoch; auf die Tische aber kam das Opferfleisch zu liegen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 44, 'Hierauf führte er mich aus dem Tor hinaus in den inneren Vorhof, woselbst ich zwei Zellen sah, von denen die eine an der Seitenwand des Nordtores lag und mit ihrer Vorderseite gegen Süden gerichtet war, während die andere an der Seitenwand des Südtores mit ihrer Vorderseite gegen Norden gerichtet lag.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 45, 'Da sagte er zu mir: »Diese Zelle da, deren Vorderseite gegen Süden liegt, ist für die Priester bestimmt, die den Dienst im Tempelhause verrichten;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 46, 'dagegen die Zelle, deren Vorderseite gegen Norden liegt, ist für die Priester bestimmt, die den Dienst am Altar zu verrichten haben« – das sind die Nachkommen Zadoks, die (allein) von den Nachkommen Levis dem HERRN nahen dürfen, um den Dienst vor ihm zu verrichten.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 47, 'Dann maß er den (inneren) Vorhof aus; dieser bildete ein Viereck von hundert Ellen Länge und hundert Ellen Breite; der Altar aber stand vor der Vorderseite des Tempelhauses.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 48, 'Hierauf führte er mich zur Vorhalle des Tempelhauses und maß die (beiden) Wandpfeiler der Vorhalle, von denen jeder hüben wie drüben fünf Ellen breit war; die Breite des Tores aber betrug vierzehn Ellen und die der Seitenwände des Tores drei Ellen auf beiden Seiten.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 49, 'Die Länge der Vorhalle betrug zwanzig Ellen und die Tiefe zwölf Ellen; und auf zehn Stufen stieg man zu ihr hinauf. An den Pfeilern aber standen Säulen, eine auf dieser und eine auf jener Seite.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 41, 1, 'Darauf führte er mich in die Tempelhalle hinein und maß die Pfeiler: sechs Ellen Breite auf der einen wie auf der andern Seite.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 41, 2, 'Die Breite des Eingangs betrug zehn Ellen und die der Seitenwände des Eingangs beiderseits fünf Ellen. Sodann maß er die Länge der Halle: vierzig Ellen, und die Breite: zwanzig Ellen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 41, 3, 'Hierauf trat er in den Innenraum hinein und maß den Pfeiler des Eingangs: zwei Ellen Breite; und die Breite des Eingangs: sechs Ellen; und die Seitenwände des Eingangs: sieben Ellen auf der einen wie auf der andern Seite.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 41, 4, 'Dann maß er die Länge des Raumes: zwanzig Ellen, und die Breite: zwanzig Ellen, entsprechend der Breite der Tempelhalle; und er sagte dann zu mir: »Dies ist das Allerheiligste.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 41, 5, 'Hierauf maß er die (Dicke der) Mauer des Tempelgebäudes: sechs Ellen, und die Dicke (der Mauer) des seitlichen Anbaues rings um den Tempel herum: vier Ellen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 41, 6, 'Die Seitengemächer aber waren, Gemach an Gemach, dreißig, und zwar in (allen) drei Stockwerken; und es waren Absätze an der Mauer des Tempelhauses für die Seitengemächer ringsum, um als Träger zu dienen, ohne daß sie jedoch in die Tempelmauer selbst eingelassen waren.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 41, 7, 'Und immer breiter wurden die Seitengemächer nach oben hin mehr und mehr, entsprechend der der Tempelmauer abgewonnenen Erweiterung nach oben hin rings um das Tempelhaus herum. Daher nahm die Breite des Anbaus nach oben hin zu. Man stieg aber vom unteren Stockwerk zum obersten durch das mittlere hinauf.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 41, 8, 'Und ich sah rings um das Tempelhaus ein erhöhtes Pflaster herumlaufen. Der Unterbau der Seitengemächer hatte die Höhe einer vollen Rute, sechs Ellen nach der Verbindung hin.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 41, 9, 'Die Dicke der Außenmauer des Anbaues betrug fünf Ellen; und was freigelassen war zwischen den Seitengemächern, die sich am Hause befanden,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 41, 10, 'und zwischen den Zellen, hatte eine Breite von zwanzig Ellen rings um das ganze Tempelhaus herum.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 41, 11, 'Von den zwei Türen des seitlichen Anbaues, die nach dem freigelassenen Raum hinausführten, ging die eine nach Norden, die andere nach Süden; die Breite des freigelassenen Platzes aber betrug fünf Ellen ringsherum. –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 41, 12, 'Das Hintergebäude aber, das längs der Einfriedigung an der Westseite lag, hatte eine Breite von siebzig Ellen; und die Wand des Gebäudes maß fünf Ellen an Dicke ringsherum, und seine Länge betrug neunzig Ellen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 41, 13, 'Hierauf maß er das Tempelhaus, dessen Länge hundert Ellen betrug; sodann den eingefriedigten Platz mit dem Hintergebäude und seinen Mauern: eine Länge von hundert Ellen;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 41, 14, 'dann die Breite der Vorderseite des Tempelhauses nebst dem eingefriedigten Platz nach Osten zu: hundert Ellen. –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 41, 15, 'Weiter maß er die Länge des Hintergebäudes längs der Einfriedigung, die sich auf seiner Hinterseite befand, sowie seine Galerien auf dieser wie auf jener Seite: hundert Ellen. Die Tempelhalle aber sowie das Allerheiligste und die äußere Vorhalle');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 41, 16, 'waren getäfelt, und schräg einfallende Fenster ließen Licht in die drei Räume ringsum eindringen; und die Wände drinnen waren ringsum mit Holz getäfelt vom Boden an bis zu den Fenstern und von den Seitenwänden.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 41, 17, 'Oberhalb der Tür des Tempelraumes inwendig und auswendig und auf allen Wänden ringsherum [innen und außen] waren Bildwerke angebracht,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 41, 18, 'nämlich Cherube und Palmen, und zwar je eine Palme zwischen zwei Cheruben. Jeder Cherub aber hatte zwei Gesichter,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 41, 19, 'nämlich auf der einen Seite ein Menschengesicht, das einer Palme zugekehrt war, und auf der andern Seite ein Löwengesicht, das gleichfalls einer Palme zugekehrt war: so war es im ganzen Tempelgebäude ringsherum gemacht:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 41, 20, 'vom Fußboden bis über die Tür hinauf waren die Cherube und die Palmen an den Tempelwänden angebracht.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 41, 21, 'Die Tempelhalle hatte vierkantige Türpfosten; und an der Vorderseite des Allerheiligsten stand ein Gegenstand, der aussah');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 41, 22, 'wie ein Altar von Holz, drei Ellen hoch, zwei Ellen lang und zwei Ellen breit; er hatte auch Hörner, und sein Fußgestell sowie seine Wände waren von Holz. Da sagte er zu mir: »Dies ist der Tisch, der vor dem HERRN steht.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 41, 23, 'Die Tempelhalle wie auch das Allerheiligste hatten zwei Flügeltüren,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 41, 24, 'von denen jede aus zwei Türblättern bestand, die beide drehbar waren, und zwar an beiden Türflügeln.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 41, 25, 'Auch an ihnen waren Cherube und Palmen angebracht, geradeso wie es an den Wänden der Fall war; und ein hölzernes Schutzdach befand sich draußen an der Vorderseite der Vorhalle.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 41, 26, 'Schräg einfallende Fenster und Palmenverzierungen befanden sich an beiden Seitenwänden der Vorhalle und an den Seitenzimmern des Tempelhauses und an den Schutzdächern.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 42, 1, 'Hierauf führte er mich hinaus, und zwar in den inneren Vorhof (und dann) in der Richtung nach Norden, und brachte mich zu den (beiden) Zellengebäuden, die dem eingefriedigten Platz gegenüber und dem Hintergebäude nach Norden gegenüber lagen, das eine auf dieser,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 42, 2, 'das andere auf der andern Seite. Die Länge (der Zellengebäude) betrug hundert Ellen und die Breite fünfzig Ellen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 42, 3, 'Gegenüber den zwanzig Ellen des inneren Vorhofs und gegenüber dem Steinpflaster des äußeren Vorhofs lief eine Galerie vor der andern hin in drei Stockwerken.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 42, 4, 'Vor den Zellen aber befand sich ein Gang von zehn Ellen Breite und hundert Ellen Länge; und ihre Türen lagen nach Norden zu.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 42, 5, 'Die obersten Zellen waren aber, weil die Galerien ihnen einen Teil des Raumes wegnahmen, schmaler als die untersten und die mittleren des Gebäudes;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 42, 6, 'denn sie waren dreistöckig, hatten aber keine Säulen wie die Säulen auf dem äußeren Vorhof; darum war von den untersten und mittleren Zellen Raum weggenommen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 42, 7, 'Eine Mauer aber war da, die an der Außenseite, den Zellen gleichlaufend, in der Richtung nach dem äußeren Vorhof hin lief; soweit sie den Zellen entlang lief, betrug ihre Länge fünfzig Ellen;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 42, 8, 'denn die Länge der Zellen, die nach dem äußeren Vorhof zu lagen, betrug fünfzig Ellen, während sie dem Tempel gegenüber hundert Ellen betrug.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 42, 9, 'Unterhalb dieser Zellen aber befand sich der Eingang von Osten her, wenn man zu ihnen vom äußeren Vorhof her kam,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 42, 10, 'am Anfang der Mauer des Vorhofs. (Als er mich dann) nach Süden zu (geführt hatte, sah ich, daß dort) vor dem eingefriedigten Platz und vor dem Hintergebäude ebenfalls Zellen lagen,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 42, 11, 'vor denen sich ein Gang befand und die dasselbe Aussehen hatten wie die Zellen auf der Nordseite, ebenso lang und ebenso breit wie jene; auch bezüglich ihrer Ausgänge und Einrichtungen waren sie völlig gleichartig; und wie ihre Eingänge,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 42, 12, 'so waren auch die Eingänge der Zellen, die nach Süden zu lagen: ein Eingang am Anfang des Weges, der nach dem äußeren Vorhof führte, gegen Osten, wo man hineinkam.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 42, 13, 'Da sagte er zu mir: »Die Zellen an der Nordseite und die Zellen an der Südseite, die vor dem eingefriedigten Platz liegen, das sind die heiligen Zellen, in denen die Priester, die dem HERRN nahen dürfen, die hochheiligen Gaben essen sollen; dort sollen sie das Hochheilige niederlegen, sowohl das Speisopfer als auch das Sünd- und das Schuldopfer, denn es ist eine heilige Stätte.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 42, 14, 'Wenn die Priester eintreten – sie dürfen aber nicht aus dem Heiligtum (unmittelbar) in den äußeren Vorhof hinaustreten –, so sollen sie dort ihre Gewänder niederlegen, in denen sie den Dienst verrichtet haben; denn diese sind heilig: sie sollen andere Kleider anziehen und dann erst sich nach dem für das Volk bestimmten Raume begeben.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 42, 15, 'Als er nun mit der Ausmessung der inneren Tempelbauten fertig war, führte er mich hinaus in der Richtung nach dem Tor zu, dessen Vorderseite gegen Osten lag, und maß den ganzen Umfang aus.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 42, 16, 'Er maß die Ostseite mit der Meßrute aus: fünfhundert Ruten Länge im ganzen;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 42, 17, 'dann wandte er sich nach Norden und maß die Nordseite: fünfhundert Ruten Länge im ganzen; dann ging er herum');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 42, 18, 'und maß die Südseite: fünfhundert Ruten Länge im ganzen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 42, 19, 'Dann ging er nach der Westseite herum und maß: fünfhundert Ruten nach der Meßrute;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 42, 20, 'auf allen vier Windrichtungen nahm er die Messung vor. Der ganze Tempelbezirk hatte ringsum eine Mauer von fünfhundert Ruten Länge und fünfhundert Ruten Breite, um den heiligen Raum von dem unheiligen zu scheiden.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 43, 1, 'Als er mich hierauf zum Tor, zu dem nach Osten gerichteten Tore, zurückgeführt hatte,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 43, 2, 'erschien plötzlich die Herrlichkeit des Gottes Israels von Osten her; ihr Rauschen schallte wie das Rauschen gewaltiger Wasserfluten, und die Erde leuchtete von seiner Herrlichkeit.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 43, 3, 'Die Erscheinung, die sich mir darbot, glich der Erscheinung, die ich geschaut hatte, als er gekommen war, um die Stadt zu vernichten, und die Erscheinung des Wagens, den ich erblickte, war dieselbe Erscheinung, die ich schon am Flusse Kebar gesehen hatte; und ich warf mich auf mein Angesicht nieder.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 43, 4, 'Als dann die Herrlichkeit des HERRN durch das nach Osten gerichtete Tor in den Tempelbezirk eingezogen war,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 43, 5, 'hob die Gotteskraft mich empor und brachte mich in den inneren Vorhof; und siehe da: der Tempel war von der Herrlichkeit des HERRN erfüllt.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 43, 6, 'Da hörte ich, wie jemand vom Tempel her mich anredete, während der Mann noch neben mir stand.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 43, 7, 'Und jener sagte zu mir: »Menschensohn, dies ist die Stätte meines Thrones und (dies) die Stätte meiner Fußsohlen, wo ich für immer inmitten der Kinder Israel wohnen will. Das Haus Israel wird aber hinfort meinen heiligen Namen nicht mehr entweihen, weder sie noch ihre Könige, durch ihre Abgötterei und durch die Leichen ihrer Könige bei deren Tode,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 43, 8, 'dadurch daß sie ihre Schwelle an meiner Schwelle und ihre Türpfosten neben den meinigen anbrachten, so daß sich nur die Wand zwischen mir und ihnen befand und sie so meinen heiligen Namen durch ihre Greuel entweihten, die sie verübten, so daß ich sie in meinem Zorn vernichtete.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 43, 9, 'Wenn sie nunmehr aber ihre Abgötterei und die Leichen ihrer Könige fern von mir halten, dann will ich für immer unter ihnen wohnen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 43, 10, 'Du aber, Menschensohn, erstatte dem Hause Israel Bericht über diesen Tempel, damit sie sich ihrer Verschuldungen schämen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 43, 11, 'Wenn sie sich dann alles dessen schämen, was sie begangen haben, dann laß sie den Bauplan des Tempels und seine Einrichtung, seine Aus- und Eingänge, seine ganze Gestalt und alle für ihn gültigen Satzungen und Bestimmungen wissen und schreibe es vor ihren Augen auf, damit sie auf seine ganze Gestaltung und alle für ihn gültigen Anordnungen achtgeben und sie zur Ausführung bringen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 43, 12, 'Dies ist die für den Tempel gültige Ordnung: ›Auf dem Gipfel des Berges soll er liegen und sein ganzer Bezirk ringsum hochheilig sein!‹ Siehe, dies ist die für den Tempel gültige Ordnung!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 43, 13, 'Dies nun waren die Maße des Altars nach Ellen, die Elle zu einer gewöhnlichen Elle und einer Handbreite gerechnet: seine Grundeinfassung war eine Elle hoch und eine Elle breit, und die Randleiste an ihrem Rande ringsum eine Spanne hoch. Und dies war die Höhe des Altars:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 43, 14, 'von der Grundeinfassung am Boden bis zu der unteren Umfriedigung zwei Ellen Höhe und eine Elle Breite; dann von der kleinen Umfriedigung bis zu der großen Umfriedigung vier Ellen Höhe und eine Elle Breite;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 43, 15, 'dann der Opferherd vier Ellen Höhe; und vom Opferherd ragten die vier Hörner (eine Elle) empor.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 43, 16, 'Der Opferherd war zwölf Ellen lang bei zwölf Ellen Breite, quadratförmig an seinen vier Seiten.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 43, 17, 'Die große Umfriedigung hatte vierzehn Ellen Länge bei vierzehn Ellen Breite, so daß ihre vier Seiten ein Quadrat bildeten; und die Randleiste rings um sie herum war eine halbe Elle breit und die Grundeinfassung an ihr eine Elle (breit) ringsum. Die Stufen des Altars aber befanden sich auf der Ostseite.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 43, 18, 'Hierauf sagte er zu mir: »Menschensohn, so spricht Gott der HERR: ›Dies sind die Satzungen, die für den Altar gültig sind an dem Tage, wo er hergestellt sein wird, daß man Brandopfer auf ihm darbringe und Blut auf ihn sprenge.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 43, 19, 'Da sollst du den levitischen Priestern, die zu den Nachkommen Zadoks gehören und die mir nahen dürfen‹ – so lautet der Ausspruch Gottes des HERRN –, ›um meinen Dienst zu versehen, einen jungen Stier zum Sündopfer geben,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 43, 20, 'und sie sollen etwas von seinem Blute nehmen und es an die vier Hörner des Altars tun und an die vier Ecken der Umfriedigung und an die Randleiste ringsum, um ihn so zu entsündigen und die Sühne für ihn zu vollziehen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 43, 21, 'Alsdann sollen sie den zum Sündopfer dienenden Stier nehmen, damit man ihn auf dem dazu bestimmten Platze des Tempelbezirks außerhalb des Heiligtums verbrenne.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 43, 22, 'Am zweiten Tage aber sollen sie einen fehllosen Ziegenbock als Sündopfer darbringen und mit ihm den Altar entsündigen, wie sie ihn mit dem Stier entsündigt haben.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 43, 23, 'Wenn sie dann mit der Entsündigung fertig sind, sollen sie einen fehllosen jungen Stier von den Rindern und einen fehllosen Widder vom Kleinvieh opfern;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 43, 24, 'die sollen sie vor den HERRN bringen und [die Priester sollen] Salz auf sie streuen und sie dem HERRN als Brandopfer darbringen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 43, 25, 'Sieben Tage lang sollen sie so täglich einen Bock als Sündopfer darbringen; auch einen jungen Stier von den Rindern und einen Widder vom Kleinvieh, fehllose Tiere, sollen sie opfern.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 43, 26, 'Sieben Tage lang sollen sie so die Entsündigung des Altars vornehmen und ihn reinigen und ihn so einweihen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 43, 27, 'Wenn man dann mit diesen Tagen zu Ende ist, sollen die Priester am achten Tage und weiterhin eure Brand- und Heilsopfer auf dem Altar darbringen, und ich werde euch gnädig annehmen!« – so lautet der Ausspruch Gottes des HERRN.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 44, 1, 'Hierauf führte er mich zurück in der Richtung nach dem äußeren gegen Osten gerichteten Tor des Heiligtums, das aber verschlossen war.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 44, 2, 'Da sagte der HERR zu mir: »Dieses Tor soll verschlossen bleiben, es darf nicht geöffnet werden, und niemand darf durch dasselbe eingehen; weil der HERR, der Gott Israels, hier eingezogen ist: darum soll es verschlossen bleiben!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 44, 3, 'Nur der Fürst darf sich, eben weil er Fürst ist, darin niedersetzen, um das Opfermahl vor dem HERRN zu halten; auf dem Wege durch die Vorhalle des Tores soll er eintreten und auf demselben Wege wieder hinausgehen!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 44, 4, 'Darauf führte er mich in der Richtung nach dem Nordtor an die Vorderseite des Tempelhauses; und als ich hinschaute, sah ich die Herrlichkeit des HERRN, die das Tempelhaus erfüllte. Als ich mich nun auf mein Angesicht niedergeworfen hatte,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 44, 5, 'sagte der HERR zu mir: »Menschensohn, gib genau acht und richte deine Augen und Ohren aufmerksam auf alles, was ich jetzt mit dir reden werde in bezug auf alle Verordnungen und Satzungen, die für den Tempel des HERRN Geltung haben sollen. Richte (zunächst) deine Aufmerksamkeit darauf, wie man in den Tempel an allen Ausgängen des Heiligtums eintreten soll.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 44, 6, 'Sage also zum Hause Israel, zu diesem widerspenstigen Geschlecht: ›So hat Gott der HERR gesprochen: Laßt es jetzt genug sein mit all euren Greueln, ihr vom Hause Israel!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 44, 7, 'Ihr habt Fremdlinge, an Herz und Leib unbeschnittene Leute, eintreten lassen, so daß sie in meinem Heiligtum waren und mein Haus durch ihre Anwesenheit entweihten, wenn ihr mir meine Speise, Fett und Blut, darbrachtet, und habt dadurch meinen Bund gebrochen zu all euren übrigen Greueln hinzu;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 44, 8, 'und statt selbst meines heiligen Dienstes zu warten, habt ihr sie an eurer Stelle zur Besorgung meines Dienstes in meinem Heiligtum bestellt.‹');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 44, 9, 'Darum hat Gott der HERR so gesprochen: ›Kein Ausländer, der an Herz und Leib unbeschnitten ist, darf in mein Heiligtum kommen, keiner von allen Ausländern, die unter den Israeliten leben.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 44, 10, 'Vielmehr die Leviten, die mir untreu geworden sind, als Israel abgeirrt war und nach seinem Abfall von mir hinter seinen Götzen herlief, die sollen ihre Schuld büßen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 44, 11, 'Sie sollen Dienste in meinem Heiligtum leisten als Wächter an den Tempeltoren und als Diener des Tempels; sie sollen die Brand- und Schlachtopfer für das Volk schlachten, und sie sollen ihnen (den Volksgenossen) zur Verfügung stehen, um ihnen Dienste zu leisten.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 44, 12, 'Weil sie ihnen vor ihren Götzen Dienste geleistet haben und dadurch dem Hause Israel ein Anlaß zur Verschuldung geworden sind, darum habe ich meine Hand zum Schwur gegen sie erhoben‹ – so lautet der Ausspruch Gottes des HERRN –, ›daß sie ihre Schuld büßen sollen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 44, 13, 'Sie dürfen mir nicht nahen, um Priesterdienste vor mir zu verrichten und um an alles, was mir heilig ist, an die hochheiligen Gegenstände, heranzutreten; sondern sie sollen ihre Schmach tragen und für die Greuel büßen, die sie verübt haben.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 44, 14, 'So will ich sie denn zu Wärtern für den Tempeldienst machen, zur Besorgung aller Obliegenheiten und alles dessen, was es in ihm zu tun gibt.‹«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 44, 15, '»›Aber die levitischen Priester, die Nachkommen Zadoks, die des Dienstes an meinem Heiligtum treu gewartet haben, als die Israeliten nach ihrem Abfall von mir irregingen, die sollen mir nahen, um mir zu dienen, und sollen vor mich hintreten, um mir Fett und Blut als Opfer darzubringen‹ – so lautet der Ausspruch Gottes des HERRN.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 44, 16, '›Sie sollen in mein Heiligtum hineingehen, und sie sollen meinem Tische nahen, um mir zu dienen, und sollen meinen Dienst besorgen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 44, 17, 'Wenn sie aber in die Tore des inneren Vorhofs eintreten, dann müssen sie leinene Gewänder anlegen; von Wolle dürfen sie nichts an sich haben, solange sie innerhalb der Tore des inneren Vorhofs und im Tempel Dienst tun.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 44, 18, 'Kopfbunde von Leinen sollen auf ihrem Haupt sein und Beinkleider von Leinen an ihren Schenkeln; in schweißerregende Stoffe dürfen sie sich nicht kleiden.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 44, 19, 'Wenn sie jedoch in den äußeren Vorhof zum Volk hinausgehen, sollen sie ihre Gewänder, in denen sie den Dienst verrichtet haben, ausziehen und sie in den heiligen Zellen niederlegen und sollen andere Kleider anziehen, um nicht dem Volk durch ihre Kleider eine Weihe mitzuteilen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 44, 20, 'Ihr Haupt sollen sie nicht kahl scheren, aber auch das Haar nicht lang herabhängen lassen, sondern sie sollen ihr Haupthaar geschnitten tragen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 44, 21, 'Wein darf kein Priester trinken, wenn sie in den inneren Vorhof hineingehen wollen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 44, 22, 'Mit einer Witwe oder einer entlassenen Frau dürfen sie sich nicht verheiraten, sondern nur mit Jungfrauen von israelitischer Herkunft; eine Witwe jedoch, die ein Priester als Witwe hinterlassen hat, dürfen sie heiraten.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 44, 23, 'Sie sollen mein Volk zwischen Heiligem und Unheiligem unterscheiden lehren und ihm den Unterschied von Unrein und Rein klarmachen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 44, 24, 'Bei Rechtshändeln sollen sie zu Gericht sitzen: auf Grund meiner Rechtsbestimmungen sollen sie entscheiden und meine Weisungen und Satzungen an allen meinen Festen beobachten und meine Sabbate heilig halten.‹«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 44, 25, '»An die Leiche eines Menschen dürfen sie nicht herantreten, weil sie sich dadurch verunreinigen würden; nur an der Leiche von Vater und Mutter, von Sohn und Tochter, von Bruder und Schwester, sofern diese unverheiratet geblieben ist, dürfen sie sich verunreinigen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 44, 26, 'Wenn der Betreffende dann wieder rein geworden ist, soll er sich noch sieben Tage abzählen;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 44, 27, 'und an dem Tage, an dem er das Heiligtum, nämlich den inneren Vorhof, wieder betritt, um im Heiligtum Dienst zu tun, soll er ein Sündopfer für sich darbringen‹« – so lautet der Ausspruch Gottes des HERRN.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 44, 28, '»›Erbbesitz sollen sie nicht haben: ich bin ihr Erbbesitz; und ein Besitztum sollt ihr ihnen in Israel nicht geben: ich bin ihr Besitztum!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 44, 29, 'Sie sind es, die das Speisopfer, das Sündopfer und das Schuldopfer verzehren sollen, und alles, was in Israel dem Bann verfällt, soll ihnen gehören.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 44, 30, 'Auch das Beste von allen Erstlingen jedweder Art und alle eure Hebopfer jedweder Art ohne Ausnahme sollen den Priestern zufallen; und auch das Beste von eurem Schrotmehl sollt ihr dem Priester geben, damit Segen auf euren Häusern ruht.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 44, 31, 'Fleisch von verendeten oder zerrissenen Tieren, seien es Vögel oder Vierfüßler, dürfen die Priester nicht essen.‹«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 45, 1, '»Wenn ihr dann das Land zum Erbbesitz verlost, sollt ihr für den HERRN ein Hebopfer vorwegnehmen, eine Weihegabe, nämlich einen Landstrich von 25000 Ellen Länge und 20000 Ellen Breite: das soll in seinem ganzen Umfange ein heiliger Bezirk sein.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 45, 2, 'Von diesem Gebiet soll auf den Tempel entfallen ein Geviert von 500 Ellen Seitenlänge; und rings um dieses soll ein freier Raum von fünfzig Ellen gelassen werden.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 45, 3, 'Weiter sollst du von jenem abgemessenen Bezirk ein Stück von 25000 Ellen Länge und 10000 Ellen Breite abmessen, auf welches das Heiligtum als Hochheiliges zu stehen kommt.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 45, 4, 'Dies soll der heilige Teil vom Lande sein: den Priestern, die den Dienst im Heiligtum zu verrichten haben und die dem HERRN nahen, um ihm zu dienen, soll er gehören und als Platz für Häuser von ihnen verwandt werden und als heiliger Raum zum Heiligtum gehören. –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 45, 5, 'Ferner soll ein Bezirk von 25000 Ellen Länge und 10000 Ellen Breite den Leviten, den Tempeldienern, als Eigentum überwiesen werden, für Ortschaften zum Bewohnen. –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 45, 6, 'Ferner sollt ihr der Stadt ein Gebiet von 5000 Ellen Breite und 25000 Ellen Länge als Eigentum überweisen; es soll sich zur Seite des heiligen Weihebezirks erstrecken und dem ganzen Hause Israel gehören. –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 45, 7, 'Dem Fürsten endlich sollt ihr Landbesitz zuweisen auf beiden Seiten des heiligen Weihebezirks und des Eigentums der Stadt, längs dieser beiden Bezirke sowohl auf der Westseite westwärts als auch auf der Ostseite ostwärts und in der Länge entsprechend jedem einzelnen der (Stammes-) Anteile von der Westgrenze bis zur Ostgrenze');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 45, 8, 'des Landes. Das soll ihm als Eigentum in Israel gehören, damit meine Fürsten hinfort mein Volk nicht mehr bedrücken, sondern das (übrige) Land dem Hause Israel nach seinen Stämmen überlassen.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 45, 9, 'So hat Gott der HERR gesprochen: »Laßt es nun genug sein, ihr Fürsten Israels! Steht ab von Gewalttätigkeit und Bedrückung, übt vielmehr Recht und Gerechtigkeit und laßt mein Volk nicht mehr unter euren Besitzräubereien leiden!« – so lautet der Ausspruch Gottes des HERRN.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 45, 10, '»Richtige Waage, richtiges Epha und richtiges Bath sollt ihr führen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 45, 11, 'Das Epha und das Bath sollen gleichen Gehalt haben, so daß das Bath den zehnten Teil eines Chomers beträgt und das Epha ebenfalls den zehnten Teil eines Chomers: nach dem Chomer soll ihre Maßbestimmung erfolgen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 45, 12, 'Weiter soll der Schekel zwanzig Gera betragen; fünf Schekel sollen fünf Schekel sein, und zehn Schekel sollen zehn Schekel sein, und fünfzig Schekel soll bei euch die Mine gelten.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 45, 13, '»Folgendes ist die Hebe, die ihr entrichten sollt: ein Sechstel Epha von jedem Chomer Weizen und ein Sechstel Epha von jedem Chomer Gerste.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 45, 14, 'Sodann soll die Gebühr beim Öl ein Zehntel Bath von jedem Kor betragen [denn zehn Bath machen ein Kor aus].');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 45, 15, 'Ferner: ein Stück Kleinvieh aus einer Herde von zweihundert Stück, als Hebe von allen Geschlechtern Israels zum Speis- und zum Brandopfer und zum Heilsopfer, um euch Sühne zu erwirken« – so lautet der Ausspruch Gottes des HERRN.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 45, 16, '»Das ganze Volk des Landes soll zu dieser Abgabe an den Fürsten in Israel verpflichtet sein.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 45, 17, 'Dem Fürsten dagegen sollen das Brandopfer, das Speis- und das Trankopfer an den Festen sowie an den Neumonden und Sabbaten (und) bei allen Festversammlungen des Hauses Israel obliegen. Er hat das Sündopfer, das Speis- und Brandopfer und die Heilsopfer auszurichten, um dem Hause Israel Sühne zu erwirken.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 45, 18, 'So hat Gott der HERR gesprochen: »Im ersten Monat, am ersten Tage des Monats, sollt ihr einen fehllosen jungen Stier zur Entsündigung des Heiligtums nehmen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 45, 19, 'Der Priester soll dann etwas von dem Blut des Sündopfers nehmen und es an die Türpfosten des Tempelhauses und an die vier Ecken der Umfriedigung des Altars und an die Pfosten des Tores zum inneren Vorhof tun;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 45, 20, 'und ebenso sollt ihr es am ersten Tage des siebten Monats machen mit Rücksicht auf die, welche sich unabsichtlich oder unwissentlich versündigt haben, und so sollt ihr Sühne für den Tempel erwirken.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 45, 21, 'Am vierzehnten Tage des ersten Monats sollt ihr das Passah feiern, das siebentägige Fest, während dessen Dauer ungesäuertes Brot gegessen werden soll.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 45, 22, 'Der Fürst aber hat an diesem Tage für sich selbst und für das gesamte Volk des Landes einen Stier als Sündopfer darzubringen');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 45, 23, 'und soll an den sieben Tagen des Festes dem HERRN sieben Stiere und sieben Widder, fehllose Tiere, täglich während der sieben Tage als Brandopfer darbringen, und als Sündopfer täglich einen Ziegenbock.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 45, 24, 'Als Speisopfer aber soll er je ein Epha Feinmehl zu jedem Stier und je ein Epha zu jedem Widder opfern und an Öl je ein Hin auf jedes Epha.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 45, 25, 'Am fünfzehnten Tage des siebten Monats, am Feste, soll er die sieben Tage hindurch die gleichen Opfergaben herrichten, sowohl Sündopfer als auch Brand- und Speisopfer und Öl.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 46, 1, 'So hat Gott der HERR gesprochen: »Das Tor des inneren Vorhofs, das nach Osten zu liegt, soll während der sechs Werktage geschlossen bleiben; aber am Sabbattage und ebenso am Neumondtage soll es geöffnet werden.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 46, 2, 'Wenn dann der Fürst durch die Vorhalle des Tores von außen her eingetreten und am Pfosten des Tores stehen geblieben ist, dann sollen die Priester sein Brandopfer und sein Heilsopfer darbringen; nachdem er dann auf der Schwelle des Tores die Anbetung verrichtet hat und wieder hinausgegangen ist, soll das Tor bis zum Abend unverschlossen bleiben;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 46, 3, 'und auch das Volk des Landes soll am Eingang dieses Tores an den Sabbaten und Neumonden vor dem HERRN anbeten. –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 46, 4, 'Das Brandopfer aber, das der Fürst dem HERRN am Sabbattage darzubringen hat, soll aus sechs Lämmern ohne Fehl und einem Widder ohne Fehl bestehen;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 46, 5, 'dazu kommt als Speisopfer ein Epha Feinmehl zu jedem Widder, und zu den Lämmern eine beliebig große Gabe von Mehl; außerdem ein Hin Öl zu jedem Epha.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 46, 6, 'Ferner soll er am Neumondstage einen fehllosen jungen Stier von den Rindern und sechs Lämmer sowie einen Widder opfern, lauter fehllose Tiere;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 46, 7, 'dazu als Speisopfer zu dem Stier und zu dem Widder je ein Epha Feinmehl; und zu den Lämmern eine beliebig große Gabe; an Öl aber ein Hin zu jedem Epha.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 46, 8, '»Wenn aber der Fürst sich einfindet, so soll er durch die Vorhalle des Tores eintreten und auf demselben Wege sich wieder entfernen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 46, 9, 'Wenn dagegen das Volk des Landes an den Festen vor dem HERRN erscheint, so soll, wer durch das Nordtor eingetreten ist, um anzubeten, durch das Südtor wieder hinausgehen, und wer durch das Südtor eingetreten ist, soll durch das Nordtor wieder hinausgehen: niemand soll durch dasselbe Tor zurückkehren, durch das er hereingekommen ist, sondern er soll durch das gegenüberliegende hinausgehen;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 46, 10, 'der Fürst aber soll, wenn sie eintreten, in ihrer Mitte eintreten; und wenn sie hinausgehen, sollen sie zusammen hinausgehen.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 46, 11, '»An den Festen aber und an den Feiertagen soll das Speisopfer ein Epha Feinmehl sowohl auf jeden Stier als auch auf jeden Widder betragen, und für die Lämmer eine beliebig große Gabe; an Öl aber ein Hin auf jedes Epha. –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 46, 12, 'Wenn ferner der Fürst dem HERRN ein Brandopfer oder Heilsopfer als freiwillige Gabe darbringen will, so soll man ihm das gegen Osten liegende Tor öffnen, und er bringe dann sein Brandopfer und sein Heilsopfer in derselben Weise dar, wie er es am Sabbattage zu tun pflegt; und wenn er dann hinausgegangen ist, soll man das Tor nach seinem Weggang wieder schließen. –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 46, 13, 'Ferner soll er dem HERRN täglich ein fehlloses einjähriges Lamm als Brandopfer darbringen; jeden Morgen soll er es herrichten,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 46, 14, 'und dazu als Speisopfer alle Morgen ein Sechstel Epha Feinmehl und an Öl ein Drittel Hin zur Befeuchtung des Feinmehls als Speisopfer dem HERRN darbringen: das ist eine ständige Satzung für alle Zukunft.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 46, 15, 'So habt ihr also das Lamm nebst dem Speisopfer und dem Öl alle Morgen als regelmäßiges Brandopfer darzubringen.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 46, 16, 'So hat Gott der HERR gesprochen: »Wenn der Fürst einem seiner Söhne ein Geschenk von seinem Erbbesitz macht, so soll dies seinen Söhnen als vererbliches Eigentum gehören.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 46, 17, 'Macht er aber einem seiner Diener ein Geschenk von seinem Erbbesitz, so soll es diesem nur bis zum Freijahr gehören, dann aber wieder an den Fürsten zurückfallen; nur seinen Söhnen soll es als Erbbesitz dauernd verbleiben.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 46, 18, 'Von dem Grundbesitz des Volkes aber darf der Fürst nichts wegnehmen, so daß er sie gewaltsam aus ihrem Eigentum verdrängt. Von seinem eigenen Besitz mag er seine Söhne mit vererblichem Grundbesitz ausstatten, damit niemand von den zu meinem Volk Gehörigen aus seinem Eigentum verdrängt wird.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 46, 19, 'Darauf führte er mich durch den Eingang, der an der Seitenwand des Tores lag, zu den heiligen, für die Priester bestimmten Zellen, die nach Norden zu gelegen waren; dort sah ich einen Raum ganz hinten in dem Winkel nach Westen zu.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 46, 20, 'Da sagte er zu mir: »Dies ist der Raum, in welchem die Priester das Schuld- und das Sündopfer kochen und wo sie das Speisopfer backen sollen; sonst müßten sie es in den äußeren Vorhof hinaustragen, wodurch sie dem Volk eine Weihe mitteilen würden.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 46, 21, 'Hierauf führte er mich in den äußeren Vorhof hinaus und ließ mich ihn nach seinen vier Ecken hin durchqueren; dabei bemerkte ich einen kleinen Hof in jeder Ecke des Vorhofs.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 46, 22, 'In allen vier Ecken des Vorhofs waren abgesonderte Höfe von vierzig Ellen Länge und dreißig Ellen Breite; alle vier Eckräume hatten die gleiche Größe;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 46, 23, 'und es lief eine gemauerte Steinwand rings um alle vier; und unten an den Steinwänden waren ringsum Kochherde angebracht.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 46, 24, 'Da sagte er zu mir: »Dies sind die Küchen, wo die Tempeldiener die Schlachtopfer des Volkes kochen müssen.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 47, 1, 'Als er mich hierauf an den Eingang des Tempelhauses zurückgeführt hatte, sah ich Wasser unter der Schwelle des Tempels hervorfließen nach Osten hin – die Vorderseite des Tempels lag ja nach Osten zu –; und das Wasser floß unterhalb der südlichen Seitenwand des Tempelhauses hinab, südlich vom Altar.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 47, 2, 'Als er mich dann durch das Nordtor hinausgeführt und mich auf dem Wege draußen zu dem äußeren, nach Osten gerichteten Tor hatte herumgehen lassen, sah ich dort Wasser von der südlichen Seitenwand herrieseln.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 47, 3, 'Indem dann der Mann mit einer Meßschnur in der Hand nach Osten zu weiterging und nach Abmessung von tausend Ellen mich durch das Wasser gehen ließ, ging mir das Wasser bis an die Knöchel;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 47, 4, 'als er dann nochmals tausend Ellen abgemessen hatte und mich durch das Wasser gehen hieß, ging mir das Wasser bis an die Knie; als er hierauf nochmals tausend Ellen abgemessen hatte und mich hindurchgehen hieß, ging mir das Wasser bis an die Hüften;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 47, 5, 'und nach nochmaliger Abmessung von tausend Ellen war es ein Fluß geworden, den man nicht mehr durchschreiten konnte; denn das Wasser war so tief geworden, daß man es hätte durchschwimmen müssen, ein Fluß, der sich nicht mehr durchschreiten ließ.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 47, 6, 'Da fragte er mich: »Hast du das wohl gesehen, Menschensohn?« Dann ließ er mich am Ufer des Flusses wieder zurückwandern.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 47, 7, 'Auf dem Rückwege sah ich nun am Ufer des Flusses auf beiden Seiten sehr viele Bäume stehen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 47, 8, 'Da sagte er zu mir: »Dieses Gewässer fließt in den östlichen Bezirk hinaus, strömt dann in die Jordan-Ebene hinab und mündet in das (Tote) Meer; und wo es sich dort hinein ergießt, da wird das Salzwasser des (Toten) Meeres gesund.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 47, 9, 'Und alle lebenden Wesen, alles, was dort wimmelt, wird, wohin immer (der Fluß) kommt, Leben gewinnen; und der Fischreichtum wird überaus groß sein; denn wenn dieses Gewässer dorthin kommt, so wird das Wasser (des Toten Meeres) gesund werden, und alles, wohin der Fluß kommt, wird Leben gewinnen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 47, 10, 'Auch Fischer werden an ihm stehen: von En-Gedi bis En-Eglaim wird es Plätze zum Auswerfen der Netze geben, und sein Fischreichtum wird wie der des großen Meeres überaus groß sein.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 47, 11, 'Aber seine Lachen und Tümpel werden nicht gesund werden: sie sind zur Salzgewinnung bestimmt.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 47, 12, 'An dem Flusse aber werden an seinem Ufer auf beiden Seiten allerlei Bäume mit eßbaren Früchten wachsen, Bäume, deren Laub nicht verwelkt und deren Früchte nicht ausgehen. Alle Monate werden sie reife Früchte tragen; denn das Wasser, an dem sie stehen, fließt aus dem Heiligtum hervor; daher werden ihre Früchte zur Nahrung dienen und ihre Blätter zu Heilzwecken.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 47, 13, 'So hat Gott der HERR gesprochen: »Dies ist die Grenze, innerhalb derer ihr das Land nach den zwölf Stämmen Israels als Erbbesitz zugeteilt erhalten sollt [– für Josef zwei Anteile –].');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 47, 14, 'Und zwar sollt ihr es zu gleichen Teilen als Erbbesitz erhalten, der eine wie der andere, weil ich einst meine Hand zum Schwur erhoben habe, es euren Vätern zu verleihen; daher soll dies Land euch als Erbbesitz zufallen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 47, 15, 'Dies soll aber die Grenze des Landes sein: Auf der Nordseite vom großen Meer an in der Richtung auf Hethlon zu bis wo es nach Hamath hineingeht, nach Zedad hin,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 47, 16, 'Berotha, Sibraim, das zwischen dem Gebiet von Damaskus und dem Gebiet von Hamath liegt, nach Hazar-Enon, das an der Grenze von Hauran liegt.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 47, 17, 'Die Grenze soll also vom Meer an bis Hazar-Enon laufen, so daß das Gebiet von Damaskus nördlich davon liegen bleibt und ebenso das Gebiet von Hamath: dies ist die Nordseite.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 47, 18, 'Was sodann die Ostseite betrifft, so läuft die Grenze von Hazar-Enon an, das zwischen Hauran und Damaskus liegt, und wird zwischen Gilead und dem Lande Israel durch den Jordan gebildet bis zum östlichen (Toten) Meer, bis nach Thamar hin: dies ist die Ostseite.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 47, 19, 'Sodann die Südseite gegen Mittag geht von Thamar bis zum Haderwasser bei Kades nach dem Bach (Ägyptens) hin (und diesen entlang) bis an das große Meer: dies ist die Südseite gegen Mittag.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 47, 20, 'Auf der Westseite aber bildet das große Meer die Grenze bis gerade gegenüber der Stelle, wo es nach Hamath hineingeht: dies ist die Westseite.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 47, 21, '»Dieses Land also sollt ihr unter euch verteilen nach den Stämmen Israels;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 47, 22, 'und zwar sollt ihr es als vererbliches Eigentum unter euch und die Fremdlinge, die unter euch wohnen und Familien unter euch gegründet haben, verlosen: sie sollen euch wie eingeborene Israeliten gelten: mit euch sollen sie um Erbbesitz inmitten der Stämme Israels losen;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 47, 23, 'und zwar sollt ihr jedem Fremdling seinen Erbbesitz in dem Stamme zuweisen, bei dem er wohnt« – so lautet der Ausspruch Gottes des HERRN.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 48, 1, '»Dies sind nun die Namen der Stämme: Im äußersten Norden, vom Meere an in der Richtung nach Hethlon bis dahin, wo es nach Hamath hineingeht, und bis hin nach Hazar-Enon – das Gebiet von Damaskus aber bleibt nordwärts liegen, seitwärts von Hamath –, von der Ostseite bis zur Westseite, erhält Dan ein Stammgebiet.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 48, 2, 'Neben dem Gebiet Dans, von der Ostseite bis zur Westseite, erhält Asser ein Stammgebiet.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 48, 3, 'Neben dem Gebiet Assers, von der Ostseite bis zur Westseite, erhält Naphthali ein Stammgebiet.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 48, 4, 'Neben dem Gebiete Naphthalis, von der Ostseite bis zur Westseite, erhält Manasse ein Stammgebiet.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 48, 5, 'Neben dem Gebiet Manasses, von der Ostseite bis zur Westseite, erhält Ephraim ein Stammgebiet.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 48, 6, 'Neben dem Gebiet Ephraims, von der Ostseite bis zur Westseite, erhält Ruben ein Stammgebiet.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 48, 7, 'Neben dem Gebiet Rubens, von der Ostseite bis zur Westseite, erhält Juda ein Stammgebiet.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 48, 8, '»Neben dem Gebiete Judas aber, von der Ostseite bis zur Westseite, soll der Weiheteil liegen, den ihr abzugeben habt. 25000 Ellen an Breite und so lang wie jeder Stammesanteil von der Ostseite bis zur Westseite; und das Heiligtum soll mitten darin liegen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 48, 9, 'Der Weiheteil, den ihr für den HERRN abzugeben habt, soll 25000 Ellen lang und 20000 Ellen breit sein;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 48, 10, 'und folgenden Besitzern soll der heilige Weihebezirk gehören: den Priestern ein Stück nach Norden 25000 (Ellen) an Länge, nach Westen 10000 Ellen an Breite, nach Osten 10000 Ellen an Breite und nach Süden 25000 Ellen an Länge; und das Heiligtum des HERRN soll mitten darin liegen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 48, 11, 'Den geweihten Priestern, den Nachkommen Zadoks, die meinen Dienst verrichtet haben und die nicht irregegangen sind, als die Israeliten zusammen mit den Leviten von mir abfielen,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 48, 12, 'ihnen soll es als ein geweihtes Stück von dem Weiheteil des Landes gehören, als Hochheiliges, neben dem Gebiet der Leviten.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 48, 13, 'Die Leviten aber sollen neben dem Gebiet der Priester ein Gebiet von 25000 Ellen Länge und 10000 Ellen Breite erhalten; im ganzen soll also die Länge 25000 und die Breite 20000 Ellen betragen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 48, 14, 'Davon dürfen sie jedoch nichts verkaufen und nichts vertauschen und den wertvollsten Teil des Landes nicht in fremden Besitz übergehen lassen, denn er ist dem HERRN heilig.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 48, 15, 'Die 5000 Ellen aber, die an der Breitseite längs der 25000 Ellen noch übrig sind, sollen nichtheiliger Gemeinbesitz der Stadt sein und zum Bewohnen und als Gemeindetrift dienen; und die Stadt soll mitten darin liegen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 48, 16, 'Deren Maße sollen folgende sein: die Nordseite 4500 Ellen, die Südseite 4500, die Ostseite 4500 und die Westseite 4500 Ellen;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 48, 17, 'und die Gemeindetrift der Stadt soll im Norden 250 Ellen, im Süden 250, im Osten 250 und im Westen 250 Ellen betragen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 48, 18, 'Was dann von der Länge noch übrig ist längs dem heiligen Weihebezirk, nämlich 10000 Ellen nach Osten und 10000 nach Westen, dessen Ertrag soll den Arbeitern der Stadt zur Ernährung dienen;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 48, 19, 'die Arbeiter der Stadt aber sollen Leute aus allen Stämmen Israels sein.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 48, 20, 'Insgesamt sollt ihr (also) als Weihegabe 25000 Ellen ins Geviert abgeben, nämlich den heiligen Weihebezirk nebst dem der Stadt gehörigen Grundbesitz.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 48, 21, 'Was dann noch übrig ist, soll dem Fürsten gehören, (nämlich das Gebiet) auf beiden Seiten des heiligen Weihebezirks und des der Stadt gehörigen Grundbesitzes (ostwärts) längs der 25000 Ellen bis zur Ostgrenze und westwärts längs der 25000 Ellen bis zur Westgrenze, entsprechend den Stammesanteilen: dem Fürsten soll es gehören, und der heilige Weihebezirk mit dem Tempelheiligtum soll mitten darin liegen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 48, 22, '');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 48, 23, '»Was sodann die übrigen Stämme betrifft, so erhält von der Ostseite bis zur Westseite Benjamin ein Stammgebiet.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 48, 24, 'Neben dem Gebiet Benjamins, von der Ostseite bis zur Westseite, erhält Simeon ein Stammgebiet.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 48, 25, 'Neben dem Gebiet Simeons, von der Ostseite bis zur Westseite, erhält Issaschar ein Stammgebiet.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 48, 26, 'Neben dem Gebiet Issaschars, von der Ostseite bis zur Westseite, erhält Sebulon ein Stammgebiet.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 48, 27, 'Neben dem Gebiet Sebulons, von der Ostseite bis zur Westseite, erhält Gad ein Stammgebiet.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 48, 28, 'Neben dem Gebiet Gads aber, auf der Südseite, nach Mittag zu, da soll die Grenze von Thamar an bis zum Haderwasser bei Kades nach dem Bach Ägyptens hin (und diesem entlang) bis an das große Meer gehen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 48, 29, 'Dies ist das Land, das ihr als Erbbesitz unter die Stämme Israels verlosen sollt, und dies sollen ihre Anteile sein« – so lautet der Ausspruch Gottes, des HERRN.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 48, 30, '»Dies sollen aber die Ausgänge der Stadt sein – und zwar sollen die Tore der Stadt nach den Stämmen Israels benannt sein –:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 48, 31, 'Auf der Nordseite, die eine Länge von 4500 Ellen hat, sollen drei Tore liegen: das Rubentor, das Judator, das Levitor;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 48, 32, 'auf der Ostseite, die eine Länge von 4500 Ellen hat, drei Tore: das Josephtor, das Benjamintor, das Dantor;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 48, 33, 'auf der Südseite, die eine Länge von 4500 Ellen hat, drei Tore: das Simeontor, das Issaschartor, das Sebulontor;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 48, 34, 'auf der Westseite, die 4500 Ellen lang ist, drei Tore: das Gadtor, das Assertor, das Naphthalitor.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 48, 35, 'Der ganze Umfang beträgt 18000 Ellen, und der Name der Stadt soll fortan lauten ›Gottesheim‹.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 1, 1, 'Im dritten Jahre der Regierung Jojakims, des Königs von Juda, zog Nebukadnezar, der König von Babylon, gegen Jerusalem und belagerte es.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 1, 2, 'Und der Herr ließ Jojakim, den König von Juda, und einen Teil der Geräte des Gotteshauses in seine Gewalt fallen, und er brachte sie nach dem Lande Sinear in den Tempel seines Gottes; die Geräte aber legte er im Schatzhause seines Gottes nieder.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 1, 3, 'Darauf befahl der König seinem obersten Kammerherrn Aspenas, er solle von den Israeliten, und zwar sowohl aus dem königlichen Geschlecht als auch aus den vornehmsten Familien, Knaben herbeischaffen,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 1, 4, 'die frei von jedem körperlichen Fehler wären und ein schönes Äußeres, eine reiche Begabung, eine gute Vorbildung und ein leichtes Fassungsvermögen besäßen und sich zum Dienst im königlichen Palast eigneten; diese sollten dann in den Schriften und der Sprache der Chaldäer ausgebildet werden.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 1, 5, 'Der König wies ihnen die tägliche Beköstigung von der königlichen Tafel und aus seinem Weinkeller zu und bestimmte für ihre Ausbildung drei Jahre, nach deren Ablauf sie in den königlichen Dienst treten sollten.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 1, 6, 'Unter ihnen befanden sich die Judäer Daniel, Hananja, Misael und Asarja;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 1, 7, 'der Oberkammerherr gab ihnen aber (andere) Namen und nannte den Daniel Beltsazar, den Hananja Sadrach, den Misael Mesach und den Asarja Abed-Nego.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 1, 8, 'Da nun Daniel sich fest vorgenommen hatte, sich nicht durch den Genuß der Tafelkost des Königs und des Weines, den jener trank, zu verunreinigen, bat er den Oberkammerherrn um die Erlaubnis, sich nicht verunreinigen zu müssen;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 1, 9, 'und Gott ließ Daniel Huld und Gnade bei dem Oberkammerherrn finden,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 1, 10, 'so daß dieser zu Daniel sagte: »Ich fürchte nur meinen Herrn, den König, der Speise und Trank für euch bestimmt hat. Wenn er nämlich wahrnähme, daß euer Aussehen nicht so gesund wäre wie das der anderen jungen Leute eures Alters, so hätte ich durch eure Schuld meinen Kopf beim König verwirkt.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 1, 11, 'Da entgegnete Daniel dem Oberkammerherrn, der zum Aufseher über Daniel, Hananja, Misael und Asarja bestellt war:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 1, 12, '»Mache doch einmal einen Versuch mit deinen Knechten zehn Tage lang, daß man uns Pflanzenkost zu essen und Wasser zu trinken gibt!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 1, 13, 'Dann möge unser Aussehen und das Aussehen der anderen jungen Leute, die von der königlichen Tafel zu essen bekommen, von dir besichtigt werden, und je nachdem du es dann befinden wirst, magst du mit deinen Knechten verfahren!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 1, 14, 'Da ging er auf diesen ihren Vorschlag ein und machte zehn Tage lang einen Versuch mit ihnen;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 1, 15, 'und nach Ablauf der zehn Tage sahen sie gesünder und besser genährt aus als alle die anderen jungen Leute, welche von der königlichen Tafel zu essen bekamen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 1, 16, 'Da ließ denn der Aufseher die Beköstigung von der königlichen Tafel und den Wein, den sie trinken sollten, wegfallen und ließ ihnen Pflanzenkost verabfolgen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 1, 17, 'Gott aber verlieh diesen vier Jünglingen Einsicht und Verständnis für alle Gelehrsamkeit und Wissenschaft; Daniel verstand sich außerdem auch auf Gesichte und Träume jeder Art.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 1, 18, 'Als nun die Zeit, nach deren Ablauf der König ihre Vorstellung befohlen hatte, abgelaufen war und der Oberkammerherr sie dem Nebukadnezar vorstellte');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 1, 19, 'und der König sich mit ihnen unterredete, erwies sich unter ihnen allen keiner wie Daniel, Hananja, Misael und Asarja; daher wurden sie unter die königlichen Hofbeamten aufgenommen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 1, 20, 'Und in allen Fällen, bei denen es sich um Einsicht und Scharfsinn handelte, fand der König sie, sooft er sie um ihre Ansicht befragte, allen Zauberern und Beschwörern in seinem ganzen Reich zehnfach überlegen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 1, 21, 'Daniel erlebte dann noch das erste Regierungsjahr des Königs Cyrus.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 1, 'Im zweiten Jahre seiner Regierung hatte Nebukadnezar einen bedeutungsvollen Traum, durch den er innerlich beunruhigt wurde, so daß es um seinen Schlaf geschehen war.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 2, 'Da befahl der König, man solle die Gelehrten und Beschwörer, die Zauberer und Chaldäer berufen, damit sie ihm Auskunft über sein Traumgesicht gäben. Als sie nun gekommen und vor den König getreten waren,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 3, 'sagte dieser zu ihnen: »Ich habe einen Traum gehabt und fühle mich nun beunruhigt durch das Verlangen, den Traum zu verstehen.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 4, 'Da antworteten die Chaldäer dem Könige auf Aramäisch: »O König, mögest du ewig leben! Teile deinen Knechten den Traum mit, dann wollen wir dir die Deutung angeben!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 5, 'Darauf gab der König den Chaldäern zur Antwort: »Mein Entschluß steht unwiderruflich fest: wenn ihr mir den Traum und seine Deutung nicht anzugeben wißt, so sollt ihr in Stücke zerhauen und eure Häuser sollen in Schutthaufen verwandelt werden;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 6, 'wenn ihr mir aber den Traum und seine Deutung kundtun könnt, so sollt ihr reiche Geschenke und große Ehre von mir erhalten. Tut mir also den Traum und seine Deutung kund!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 7, 'Da antworteten sie zum zweitenmal: »Der König wolle seinen Knechten den Traum mitteilen, dann werden wir die Deutung angeben.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 8, 'Darauf erwiderte der König: »Ich erkenne klar, daß ihr nur Zeit gewinnen wollt, weil ihr seht, daß mein Entschluß in dieser Sache feststeht:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 9, 'wenn ihr mir demnach den Traum nicht angeben könnt, so verbleibt es bei eurer Verurteilung; ihr habt euch nämlich verabredet, Lug und Trug vor mir zu reden, bis die Verhältnisse sich ändern. Darum gebt mir den Traum an, damit ich erkenne, daß ihr mir auch seine Deutung anzugeben vermögt!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 10, 'Da erwiderten die Chaldäer dem König: »Es gibt in der ganzen Welt keinen Menschen, der dem Verlangen des Königs nachkommen könnte, wie denn auch noch nie ein König, so groß und mächtig er sein mochte, ein derartiges Verlangen an irgendeinen Wahrsager oder Beschwörer oder Chaldäer gestellt hat.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 11, 'Was der König verlangt, ist zu schwer, und es gibt keinen anderen, der dem Könige Auskunft darüber zu geben vermöchte, außer den Göttern, die ja aber nicht bei den sterblichen Menschen wohnen.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 12, 'Hierüber wurde der König aufgebracht und geriet in solche Wut, daß er den Befehl gab, alle Weisen in Babylon hinzurichten.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 13, 'Als nun der Befehl ergangen war, die Weisen zu töten, sollten auch Daniel und seine Genossen ums Leben gebracht werden.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 14, 'Da wandte sich Daniel in kluger und verständiger Weise an Arioch, den Obersten der königlichen Leibwache, der zur Hinrichtung der Weisen in Babylon ausgezogen war;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 15, 'er richtete nämlich an Arioch, den Bevollmächtigten des Königs, die Frage: »Warum ist ein so strenger Befehl vom Könige erlassen?« Als Arioch hierauf dem Daniel den Sachverhalt mitgeteilt hatte,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 16, 'begab sich Daniel in den Palast und erbat sich vom Könige die Gewährung einer Frist, um dem Könige dann die Deutung zu geben.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 17, 'Hierauf begab sich Daniel in seine Wohnung und teilte seinen Freunden Hananja, Misael und Asarja die Sachlage mit,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 18, 'auf daß sie den Gott des Himmels um Erbarmen in betreff dieses Geheimnisses anflehen möchten, damit Daniel und seine Freunde nicht samt den übrigen Weisen von Babylon hingerichtet würden.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 19, 'Darauf wurde dem Daniel in einem Nachtgesicht das Geheimnis enthüllt. Da pries Daniel den Gott des Himmels,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 20, 'indem er so betete: »Gepriesen werde der Name Gottes von Ewigkeit zu Ewigkeit! Denn er besitzt beides, Weisheit und Macht.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 21, 'Er ist’s, der die Zeiten und Verhältnisse wechseln läßt, der Könige absetzt und Könige einsetzt, der den Weisen Weisheit verleiht und den Verständigen Verstand;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 22, 'er ist’s, der das Verborgene und Geheime enthüllt; er kennt, was im Finstern liegt, und das Licht wohnt bei ihm.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 23, 'Dich, den Gott meiner Väter, rühme und preise ich, daß du mir Weisheit und Tüchtigkeit verliehen und mir jetzt geoffenbart hast, was wir von dir erfleht haben; denn die Sache des Königs hast du uns kundgetan.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 24, 'Deshalb begab sich Daniel zu Arioch, den der König mit der Hinrichtung der Weisen in Babylon beauftragt hatte; er ging hin und sagte zu ihm: »Richte die Weisen von Babylon nicht hin! Führe mich hinein vor den König: ich will dem Könige die Deutung (des Traumes) kundtun!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 25, 'Da führte Arioch den Daniel eiligst hinein vor den König und sagte zu diesem: »Ich habe unter den in der Verbannung hier lebenden Judäern einen Mann gefunden, der dem Könige die Deutung geben will.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 26, 'Da antwortete der König und sagte zu Daniel, der den Namen Beltsazar führte: »Bist du wirklich imstande, mir den Traum, den ich gesehen habe, nebst seiner Deutung kundzutun?«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 27, 'Daniel gab dem Könige folgende Antwort: »Das Geheimnis, das der König zu wissen verlangt, können Weise und Beschwörer, Zauberer und Wahrsager dem Könige nicht kundtun;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 28, 'aber es gibt einen Gott im Himmel, welcher Geheimnisse enthüllt; und dieser hat dem Könige Nebukadnezar kundgetan, was in der Endzeit geschehen wird. Dein Traum und die Gesichte, die dir auf deinem Lager vor Augen gestanden haben, sind folgende gewesen:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 29, 'Dir, o König, stiegen auf deinem Lager Gedanken darüber auf, was wohl in der Zukunft geschehen würde; und da hat der, welcher die Geheimnisse enthüllt, dir kundgetan, was geschehen wird.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 30, 'Mir aber ist dieses Geheimnis nicht infolge eigener Weisheit, als ob diese bei mir in höherem Maße als bei allen anderen Lebenden vorhanden wäre, geoffenbart worden, sondern zu dem Zweck, daß dem Könige die Deutung kundgetan würde und du Aufschluß über die Gedanken deines Herzens erhieltest.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 31, 'Du, o König, hattest ein Gesicht und sahst eine Bildsäule; diese Bildsäule war gewaltig groß und von außerordentlichem Glanz; sie stand vor dir, und ihr Aussehen war erschrecklich.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 32, 'Das Haupt dieser Bildsäule war von feinem Gold, ihre Brust und ihre Arme von Silber, ihr Unterleib und ihre Hüften von Kupfer,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 33, 'ihre Beine von Eisen, ihre Füße teils von Eisen teils von Töpferton.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 34, 'Du warst im Anschauen versunken, bis ein Stein sich plötzlich vom Berge ohne Zutun einer Menschenhand loslöste; der traf die Bildsäule an ihre eisernen und tönernen Füße und zertrümmerte sie.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 35, 'Da wurden auf einen Schlag das Eisen und der Ton, das Kupfer, das Silber und das Gold zertrümmert und zerstoben wie die Spreu im Sommer auf den Tennen, und der Wind verwehte sie, so daß keine Spur mehr von ihnen zu finden war. Der Stein aber, der die Bildsäule zerschmettert hatte, wurde zu einem großen Berge, der die ganze Erde erfüllte.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 36, '»Das ist der Traum; nun wollen wir auch seine Deutung dem Könige vortragen:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 37, 'Du, o König, du König der Könige, dem der Gott des Himmels die königliche Herrschaft und die Macht, die Gewalt und die Ehre verliehen');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 38, 'und in dessen Hand er überall, wo Menschen wohnen, alle Menschen und Tiere des Feldes und Vögel des Himmels gegeben hat, so daß du als Herrscher über sie alle gebietest: du bist das goldene Haupt.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 39, 'Nach dir wird ein anderes Reich erstehen, das nicht so mächtig ist wie das deinige, und dann noch ein anderes drittes Reich von Kupfer, das über die ganze Erde herrschen wird.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 40, 'Darauf wird ein viertes Reich da sein, stark wie Eisen; und wie das Eisen alles zermalmt und zertrümmert, ebenso wird es wie zerschmetterndes Eisen jene alle zermalmen und zertrümmern.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 41, 'Daß du aber die Füße und Zehen teils aus Töpferton, teils aus Eisen bestehend gesehen hast, (dies zeigt an, daß) es ein Reich von ungleicher Beschaffenheit sein wird; einerseits wird es etwas von der Festigkeit des Eisens an sich haben, insofern du ja Eisen mit Tonerde vermischt geschaut hast;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 42, 'doch daß du die Zehen der Füße teils von Eisen, teils von Ton gesehen hast, (weist darauf hin, daß) das Reich zum Teil fest, zum Teil brüchig sein wird.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 43, 'Daß ferner das Eisen, wie du gesehen hast, mit Tonerde vermischt war, (bezieht sich darauf, daß) trotz der vielfachen Verbindungen durch Heiraten doch kein Teil an dem andern fest haften bleibt, gerade wie Eisen sich mit Ton nicht mischen läßt.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 44, 'Aber in den Tagen jener Könige wird der Gott des Himmels ein Reich erstehen lassen, das in Ewigkeit nicht zerstört werden wird und dessen Königtum auf kein anderes Volk übergehen wird. Es wird alle jene Reiche zerschmettern und vernichten, selbst aber ewig bestehen,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 45, 'entsprechend dem, was du gesehen hast, daß nämlich ein Stein sich von dem Berge ohne Zutun einer Menschenhand loslöste und das Eisen, das Kupfer, den Ton, das Silber und das Gold zerschmetterte. Ein großer Gott hat dem Könige kundgetan, was in der Zukunft sich ereignen wird: der Traum verdient vollen Glauben, und seine Deutung ist zuverlässig.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 46, 'Da warf der König Nebukadnezar sich auf sein Angesicht nieder, verneigte sich tief vor Daniel und ließ ihm Opfergaben und Räucherwerk darbringen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 47, 'Der König sprach dann vor Daniel offen aus: »Wahrlich, euer Gott ist der Gott der Götter und der Herr der Könige und der Offenbarer der Geheimnisse, weil du imstande gewesen bist, dieses Geheimnis zu offenbaren.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 48, 'Darauf erhob der König den Daniel zu hohen Ehren, gab ihm viele kostbare Geschenke und machte ihn zum Statthalter über die ganze Landschaft Babylon und zum Obervorsteher über alle Weisen Babylons.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 49, 'Auf Daniels Bitte übertrug der König dann dem Sadrach, Mesach und Abed-Nego die Verwaltung der Landschaft Babylon, während Daniel selbst am königlichen Hofe verblieb.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 3, 1, 'Der König Nebukadnezar ließ eine goldene Bildsäule von sechzig Ellen Höhe und sechs Ellen Breite anfertigen und sie in der Ebene Dura in der Provinz Babylon aufstellen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 3, 2, 'Hierauf sandte der König Nebukadnezar Boten aus, um die Satrapen, Statthalter und Befehlshaber, Oberrichter, Schatzmeister, Rechtsgelehrten, Ratsherren und alle anderen höheren Beamten der Provinz zu berufen, damit sie der Einweihung der Bildsäule beiwohnten, die der König Nebukadnezar hatte aufstellen lassen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 3, 3, 'Da versammelten sich die Satrapen, Statthalter und Befehlshaber, Oberrichter, Schatzmeister, Rechtsgelehrten, Ratsherren und alle anderen höheren Beamten der Provinz zur Einweihung der Bildsäule, die der König Nebukadnezar hatte aufrichten lassen, und nahmen Aufstellung vor der Bildsäule, die Nebukadnezar hatte aufrichten lassen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 3, 4, 'Dann machte der Herold mit lauter Stimme bekannt: »Ihr Völker, Stämme und Zungen! Euch wird hiermit befohlen:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 3, 5, 'Sobald ihr den Klang der Hörner, Flöten, Leiern, Harfen, Zithern, Sackpfeifen und aller anderen Arten von Musikinstrumenten vernehmt, sollt ihr euch niederwerfen und das goldene Bild anbeten, das der König Nebukadnezar hat aufstellen lassen!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 3, 6, 'Wer sich aber nicht niederwirft und anbetet, soll auf der Stelle in den brennenden Feuerofen geworfen werden!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 3, 7, 'Infolgedessen warfen sich in dem Augenblick, als alle Völker den Schall der Hörner, Flöten, Leiern, Harfen, Zithern und aller anderen Arten von Musikinstrumenten vernahmen, alle die Völker, Stämme und Zungen nieder, um das goldene Bild anzubeten, das der König Nebukadnezar hatte aufstellen lassen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 3, 8, 'Infolgedessen traten zu derselben Zeit chaldäische Männer auf und klagten die Juden an;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 3, 9, 'sie machten folgende Anzeige beim König Nebukadnezar: »O König, mögest du ewig leben!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 3, 10, 'Du hast, o König, den Befehl erlassen, daß jedermann, sobald er den Schall der Hörner, Flöten, Leiern, Harfen, Zithern, Sackpfeifen und aller anderen Arten von Musikinstrumenten vernehme, sich niederwerfen und das goldene Bild anbeten solle;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 3, 11, 'wer sich aber nicht niederwerfe und anbete, der solle in den brennenden Feuerofen geworfen werden.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 3, 12, 'Nun sind einige Juden da, die du mit der Verwaltung der Provinz Babylon betraut hast, nämlich Sadrach, Mesach und Abed-Nego; diese Männer haben sich um deinen Befehl, o König, nicht gekümmert: sie verehren deine Götter nicht und beten auch das goldene Bild nicht an, das du hast aufstellen lassen.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 3, 13, 'Da befahl Nebukadnezar in Zorn und Wut, Sadrach, Mesach und Abed-Nego herbeizuholen; und als diese Männer dem Könige vorgeführt waren,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 3, 14, 'richtete Nebukadnezar folgende Worte an sie: »Geschieht es absichtlich von euch, Sadrach, Mesach und Abed-Nego, daß ihr meine Götter nicht verehrt und das goldene Bild nicht anbetet, das ich habe aufstellen lassen?');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 3, 15, 'Nun wohl, wenn ihr bereit seid, in dem Augenblick, wenn ihr den Schall der Hörner, Flöten, Leiern, Harfen, Zithern, Sackpfeifen und aller anderen Arten von Musikinstrumenten vernehmt, euch niederzuwerfen und das Bild anzubeten, das ich habe anfertigen lassen – dann gut! Wenn ihr es aber nicht anbetet, sollt ihr auf der Stelle in den brennenden Feuerofen geworfen werden; und wo gäbe es einen Gott, der euch aus meiner Gewalt erretten könnte?«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 3, 16, 'Da gaben Sadrach, Mesach und Abed-Nego dem Könige folgende Antwort: »Nebukadnezar, wir haben nicht nötig, dir hierauf ein Wort zu erwidern!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 3, 17, 'Wird dein Befehl ausgeführt, so vermag unser Gott, den wir verehren, uns aus dem brennenden Feuerofen zu erretten, und er wird uns aus deiner Gewalt, o König, erretten.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 3, 18, 'Wenn er es aber nicht tut, so sei dir, o König, kundgetan, daß wir deinen Gott doch nicht verehren und das goldene Bild, das du hast aufstellen lassen, nicht anbeten werden!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 3, 19, 'Da geriet Nebukadnezar in volle Wut, so daß das Aussehen seines Gesichts gegen Sadrach, Mesach und Abed-Nego sich ganz entstellte. Er gab sofort den Befehl, man solle den Ofen siebenmal stärker heizen, als es hinreichend war;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 3, 20, 'ferner gebot er Männern, den stärksten Leuten in seinem Heer, Sadrach, Mesach und Abed-Nego zu fesseln und sie in den brennenden Feuerofen zu werfen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 3, 21, 'So wurden denn diese Männer in ihren Mänteln, Röcken, Hüten und sonstigen Kleidungsstücken gefesselt und in den brennenden Feuerofen geworfen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 3, 22, 'Weil man nun infolge des strengen Befehls des Königs den Ofen außergewöhnlich stark geheizt hatte, wurden jene Männer, die Sadrach, Mesach und Abed-Nego (an die Ofenöffnung) hinaufgetragen hatten, von der Flammenglut getötet;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 3, 23, 'jene drei Männer aber, Sadrach, Mesach und Abed-Nego, fielen gefesselt mitten in den brennenden Feuerofen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 3, 24, 'Da geriet der König Nebukadnezar in Staunen; er stand eilends auf und fragte seine Räte: »Haben wir nicht drei Männer gefesselt ins Feuer geworfen?« Sie antworteten dem König: »Gewiß, o König!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 3, 25, 'Da entgegnete er: »Ich sehe aber vier Männer ungefesselt im Feuer umhergehen, ohne daß eine Verletzung an ihnen zu bemerken ist, und der vierte sieht wie ein Göttersohn aus.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 3, 26, 'Darauf trat Nebukadnezar an die Öffnung des brennenden Feuerofens und rief: »Sadrach, Mesach und Abed-Nego, ihr Diener des höchsten Gottes, kommt heraus und tretet her!« Da kamen Sadrach, Mesach und Abed-Nego aus dem Feuer heraus;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 3, 27, 'und die Satrapen, Statthalter, Befehlshaber und Räte des Königs, die sich dort versammelt hatten, sahen jetzt, daß das Feuer jenen Männern an ihrem Leibe nichts hatte antun können: ihr Haupthaar war nicht versengt, und ihre Mäntel waren nicht beschädigt, und nicht einmal ein Brandgeruch war an sie gekommen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 3, 28, 'Da rief Nebukadnezar aus: »Gepriesen sei der Gott Sadrachs, Mesachs und Abed-Negos, daß er seinen Engel gesandt und seine Knechte errettet hat, die im Vertrauen auf ihn das Gebot des Königs übertreten und ihr Leben preisgegeben hatten, um keinen andern Gott verehren und anbeten zu müssen als nur ihren Gott!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 3, 29, 'So ergeht denn jetzt von mir der Befehl, daß unter allen Völkern, Volksstämmen und Zungen ein jeder, der gegen den Gott Sadrachs, Mesachs und Abed-Negos etwas Unehrerbietiges ausspricht, in Stücke gehauen und sein Haus in einen Schutthaufen verwandelt werden soll, weil es keinen andern Gott gibt, der auf solche Weise zu erretten vermag!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 3, 30, 'Darauf setzte der König den Sadrach, Mesach und Abed-Nego in ihre hohen Stellungen in der Landschaft Babylon wieder ein.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 3, 31, 'Erlaß des Königs Nebukadnezar an alle Völker, Völkerschaften und Zungen, die auf der ganzen Erde wohnen: »Heil möge euch reichlich zuteil werden!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 3, 32, 'Es hat mir beliebt, die Zeichen und Wunder, die der höchste Gott an mir getan hat, zu allgemeiner Kenntnis zu bringen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 3, 33, 'Wie sind doch seine Zeichen so groß und wie gewaltig seine Wunder! Sein Reich ist ein ewiges Reich, und seine Herrschaft währt von Geschlecht zu Geschlecht!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 4, 1, 'Ich, Nebukadnezar, lebte sorglos in meinem Hause und lebensfroh in meinem Palast.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 4, 2, 'Da hatte ich einen Traum, der mich erschreckte; und die Gedanken, die in mir auf meinem Lager aufstiegen, und die Erscheinungen, die mir vor die Augen traten, versetzten mich in Angst.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 4, 3, 'Ich erließ daher den Befehl, man solle alle Weisen Babylons vor mich führen, damit sie mir die Deutung des Traumes angäben.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 4, 4, 'Da kamen denn die Zeichendeuter und Beschwörer, die Chaldäer und Sterndeuter zu mir, und ich teilte ihnen den Traum mit; aber seine Deutung konnten sie mir nicht geben,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 4, 5, 'bis zuletzt Daniel vor mir erschien, der nach dem Namen meines Gottes Beltsazar genannt worden ist und in dem der Geist der heiligen Götter wohnt. Auch diesem trug ich den Traum folgendermaßen vor:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 4, 6, '›Beltsazar, du Oberster der Gelehrten! Ich weiß von dir, daß der Geist der heiligen Götter in dir wohnt und daß kein Geheimnis dir Schwierigkeiten verursacht: vernimm das Traumgesicht, das mir erschienen ist, und laß mich seine Deutung wissen!‹«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 4, 7, '»›Das Gesicht, das mir auf meinem Lager vor die Augen getreten ist, war folgendes: Ich sah deutlich einen Baum, der mitten auf der Erde stand und dessen Höhe gewaltig war.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 4, 8, 'Der Baum wurde immer größer und stärker, so daß seine Spitze bis an den Himmel reichte und er bis ans Ende der ganzen Erde zu sehen war;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 4, 9, 'sein Laubwerk war schön, Früchte trug er in reicher Fülle, und Nahrung befand sich an ihm für alle; die Tiere des Feldes suchten Schatten unter ihm, die Vögel des Himmels nisteten in seinen Zweigen, und alles, was lebte, nährte sich von ihm.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 4, 10, 'Da sah ich plötzlich in den Gesichten, die mir auf meinem Lager vor Augen traten, wie ein Wächter, nämlich ein heiliger (Engel), vom Himmel herabstieg.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 4, 11, 'Der rief mit lauter Stimme und gebot: Haut den Baum um und schlagt seine Zweige ab! Streift ihm das Laub ab und streut seine Früchte umher! Das Wild fliehe unter ihm weg und die Vögel aus seinen Zweigen!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 4, 12, 'Doch seinen Wurzelstock laßt in der Erde, und zwar in einer Fessel von Eisen und Erz auf der grünenden Flur, damit er vom Tau des Himmels benetzt wird und mit den wilden Tieren Anteil an den Kräutern der Erde hat.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 4, 13, 'Sein Menschenherz soll ihm genommen und das Herz eines Tieres ihm dafür gegeben werden; und so sollen sieben Zeiten über ihn dahingehen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 4, 14, 'Auf einem Beschluß der (himmlischen) Wächter beruht dieser Befehl, und eine Anordnung der heiligen Engel liegt in diesem Falle vor, damit die Lebenden erkennen, daß der Höchste Gewalt über das Königtum der Menschen hat und es verleihen kann, wem er will, und selbst den niedrigsten Sterblichen dazu erheben kann. –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 4, 15, 'Dies ist der Traum, den ich, der König Nebukadnezar, gehabt habe; du aber, Beltsazar, gib mir an, was er zu bedeuten hat, da ja alle Weisen meines Reiches mir die Deutung nicht zu geben vermögen. Du aber bist dazu imstande, weil der Geist der heiligen Götter in dir wohnt.‹«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 4, 16, 'Darauf stand Daniel, der den Namen Beltsazar führte, eine Zeitlang starr vor Entsetzen da, und seine Gedanken ängstigten ihn. Da sagte der König zu ihm: »Beltsazar, du brauchst dich über den Traum und seine Deutung nicht zu ängstigen!« Darauf antwortete Beltsazar: »O Herr, möchte doch der Traum denen gelten, die dich hassen, und seine Deutung deinen Feinden!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 4, 17, 'Der Baum, den du gesehen hast, der immer größer und stärker wurde, so daß seine Spitze bis an den Himmel reichte und er über die ganze Erde hin sichtbar war,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 4, 18, 'dessen Laubwerk schön war, der Früchte in reicher Fülle trug und an dem sich Nahrung für alle befand, unter dem die Tiere des Feldes lagerten und in dessen Zweigen die Vögel des Himmels nisteten:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 4, 19, 'das bist du, o König, der du groß und mächtig geworden bist, du, dessen Größe gewachsen ist und bis an den Himmel reicht und dessen Herrschaft sich bis ans Ende der Erde erstreckt.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 4, 20, 'Daß aber der König einen Wächter, nämlich einen heiligen (Engel), vom Himmel hat herabsteigen sehen, der da gebot: ›Haut den Baum um und vernichtet ihn, doch seinen Wurzelstock laßt in der Erde, und zwar in einer Fessel von Eisen und Erz auf der grünenden Flur, damit er vom Tau des Himmels benetzt wird und den Tieren des Feldes gleichgestellt ist, bis sieben Zeiten über ihn dahingegangen sind!‹,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 4, 21, 'so hat dies, o König, folgende Bedeutung, und zwar ist dies der Beschluß des Höchsten, der über meinen Herrn, den König, ergangen ist:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 4, 22, 'Man wird dich aus der Verbindung mit Menschen ausstoßen, und bei den Tieren des Feldes wird dein Aufenthalt sein; Gras wird man dir zur Nahrung geben wie den Rindern, und vom Tau des Himmels wirst du benetzt werden; und sieben Zeiten werden über dich dahingehen, bis du erkennst, daß der Höchste die Gewalt über das Königtum der Menschen hat, und daß er es verleihen kann, wem er will.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 4, 23, 'Daß aber der Befehl gegeben worden ist, der Wurzelstock des Baumes solle belassen bleiben, das hat folgende Bedeutung: dein Königtum wird dir wieder zuteil werden, sobald du erkannt hast, daß der Himmel Herr (über alles) ist.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 4, 24, 'Darum, o König, laß dir meinen Rat gefallen: Mache deine Sünden wieder gut durch Gerechtigkeit und deine Verschuldungen durch Barmherzigkeit gegen Unglückliche! Vielleicht ist dann deinem Wohlergehen lange Dauer beschieden.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 4, 25, 'Alles dies traf dann beim König Nebukadnezar ein.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 4, 26, 'Als er sich nämlich zwölf Monate später auf seinem königlichen Palast in Babylon erging,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 4, 27, 'sprach er die Worte aus: »Ist dies nicht das große Babylon, das ich zum königlichen Wohnsitz durch meine gewaltige Macht und zum Ruhm meiner Herrlichkeit erbaut habe?«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 4, 28, 'Noch war das Wort im Munde des Königs, da erscholl eine Stimme vom Himmel herab: »Dir, o König Nebukadnezar, wird hiermit kundgetan: die Königswürde ist dir genommen!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 4, 29, 'Aus der Verbindung mit Menschen wirst du ausgestoßen, und bei den Tieren des Feldes soll dein Aufenthalt sein; Gras wird man dir zur Nahrung geben wie den Rindern, und sieben Zeiten werden über dich dahingehen, bis du erkennst, daß der Höchste die Gewalt über das Königtum der Menschen hat und daß er es verleihen kann, wem er will.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 4, 30, 'Augenblicklich erfüllte sich das Wort an Nebukadnezar: er wurde aus der Verbindung mit Menschen ausgestoßen, nährte sich von Gras wie die Rinder, und sein Leib wurde vom Tau des Himmels benetzt, bis sein Haar so lang gewachsen war wie Adlerfedern und seine Nägel wie Vogelkrallen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 4, 31, '»Nach Verlauf der (festgesetzten) Zeit aber richtete ich, Nebukadnezar, meine Augen zum Himmel empor; und als ich wieder zu Verstand gekommen war, dankte ich dem Höchsten und pries und rühmte hoch den ewig Lebenden, dessen Herrschaft eine ewige Herrschaft ist und dessen Königtum von Geschlecht zu Geschlecht besteht.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 4, 32, 'Alle Bewohner der Erde verschwinden neben ihm wie nichts; nach seinem Gutdünken verfährt er sowohl mit dem Heere des Himmels als auch mit den Bewohnern der Erde, und niemand ist da, der seiner Hand wehren und zu ihm sagen dürfte: ›Was tust du da?‹');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 4, 33, 'Zu derselben Zeit kam mir mein Verstand wieder, und zum Ruhm meines Reiches kehrte meine Herrlichkeit und mein Glanz wieder zu mir zurück, und meine Räte und meine Großen suchten mich auf: ich wurde wieder in meine königliche Würde eingesetzt, und noch größere Macht wurde mir verliehen.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 4, 34, '»Nun preise und erhebe und verherrliche ich, Nebukadnezar, den König des Himmels; denn all sein Tun ist Wahrheit, und sein Walten ist Gerechtigkeit, und die in Hochmut Wandelnden vermag er zu demütigen.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 5, 1, 'Der König Belsazar veranstaltete für seine tausend Großen ein prächtiges Gastmahl und trank Wein, vor den Tausend sitzend.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 5, 2, 'In der Weinlaune befahl Belsazar dann, man solle die goldenen und silbernen Gefäße herbeibringen, die sein Vater Nebukadnezar aus dem Tempel zu Jerusalem weggenommen hatte, damit aus ihnen der König und seine Großen, seine Gemahlinnen und Nebenfrauen tränken.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 5, 3, 'So wurden denn die goldenen (und silbernen) Gefäße, die man aus dem Tempel des Hauses Gottes zu Jerusalem geraubt hatte, herbeigebracht; und der König und seine Großen, seine Gemahlinnen und Nebenfrauen tranken.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 5, 4, 'Sie tranken Wein und sangen dabei Loblieder auf ihre Götter von Gold und Silber, von Kupfer, Eisen, Holz und Stein.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 5, 5, 'In demselben Augenblick kamen die Finger einer Menschenhand zum Vorschein und schrieben, dem Kronleuchter gegenüber, auf die getünchte Wand des königlichen Saales, so daß der König den Rücken der schreibenden Hand sah.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 5, 6, 'Da entfärbte sich das Antlitz des Königs, beängstigende Gedanken überfielen ihn, und alle Kraft wich aus seinen Gliedern, so daß seine Knie schlotterten.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 5, 7, 'Der König rief laut, man solle die Beschwörer, die Chaldäer und die Wahrsager herbeiholen, und sagte zu den Weisen Babylons: »Wer die Schrift dort lesen kann und mir ihre Deutung zu geben weiß, der soll in Purpur gekleidet werden und eine goldene Kette am Halse tragen und der Dritte in der Regierung des Reiches sein.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 5, 8, 'Da traten denn alle Weisen des Königs heran, konnten aber weder die Schrift lesen noch ihre Deutung dem König angeben.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 5, 9, 'Als nun der König Belsazar in die höchste Angst geriet und sich im Gesicht verfärbte und seine Großen fassungslos waren,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 5, 10, 'begab sich die Königinmutter infolge der Aufforderungen des Königs und seiner Großen in den Speisesaal und richtete folgende Worte an den König: »O König, mögest du ewig leben! Du brauchst dich nicht ängstigenden Gedanken hinzugeben und dich im Gesicht nicht zu verfärben!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 5, 11, 'Es gibt in deinem Reiche einen Mann, in welchem der Geist der heiligen Götter wohnt und bei dem schon während der Regierung deines Vaters Erleuchtung, Scharfsinn und Weisheit von geradezu göttlicher Art gefunden worden sind, so daß dein Vater, der König Nebukadnezar, ihn zum Obersten der Gelehrten und Beschwörer, der Chaldäer und Wahrsager erhoben hat, dein eigener Vater, o König,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 5, 12, 'weil eben ein außergewöhnlicher Geist, Verstand und Scharfsinn in der Auslegung von Träumen und in der Lösung von Rätseln und in der Erklärung geheimnisvoller Dinge bei ihm zu finden waren, nämlich bei Daniel, dem der König den Namen Beltsazar gegeben hat. So lasse man also Daniel rufen: der wird die Deutung schon geben!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 5, 13, 'Als nun Daniel vor den König hereingeführt war, redete dieser ihn folgendermaßen an: »Du bist also Daniel, einer von den in die Verbannung geführten Judäern, die mein königlicher Vater aus Juda hergebracht hat?');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 5, 14, 'Ich habe von dir gehört, daß ein göttlicher Geist in dir wohnt und daß Erleuchtung, Scharfsinn und außergewöhnliche Weisheit bei dir gefunden werden.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 5, 15, 'Nun sind soeben die Weisen und Beschwörer vor mich geführt worden, um die Schrift dort zu lesen und mir ihren Sinn zu deuten; sie sind aber nicht imstande gewesen, mir die Deutung der Worte zu geben.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 5, 16, 'Von dir aber habe ich gehört, daß du Deutungen zu geben und geheimnisvolle Dinge zu erklären vermagst. Nun denn, wenn du die Schrift dort zu lesen und mir ihren Sinn anzugeben vermagst, so sollst du in Purpur gekleidet werden und eine goldene Kette am Halse tragen und der Dritte in der Regierung des Reiches sein!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 5, 17, 'Da gab Daniel dem König folgende Antwort: »Deine Geschenke magst du für dich behalten und deine Belohnungen einem andern geben; jedoch die Schrift will ich dem Könige lesen und ihren Sinn ihm angeben.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 5, 18, 'O König! Der höchste Gott hatte deinem Vater Nebukadnezar Herrschaft und Macht, Ruhm und Herrlichkeit verliehen;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 5, 19, 'und infolge der Macht, die er ihm verliehen hatte, zitterten und bebten vor ihm alle Völker, Stämme und Zungen. Er tötete, wen er wollte, und ließ am Leben, wen er wollte; er erhöhte, wen er wollte, und erniedrigte, wen er wollte.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 5, 20, 'Als aber sein Herz sich überhob und sein Sinn stolz wurde bis zur Vermessenheit, wurde er von seinem Königsthron herabgestürzt und seine Würde ihm genommen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 5, 21, 'Aus der Verbindung mit Menschen wurde er ausgestoßen, tierisches Wesen nahm von ihm Besitz, und bei den Wildeseln war sein Aufenthalt; man gab ihm Gras zur Nahrung wie den Rindern, und sein Leib wurde vom Tau des Himmels benetzt, bis er zur Erkenntnis kam, daß der höchste Gott über das Königtum der Menschen verfügt und in dieses einsetzen kann, wen er will.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 5, 22, 'Du aber, Belsazar, sein Sohn, hast dein Herz nicht demütig gemacht, wiewohl du dieses alles wußtest,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 5, 23, 'hast dich vielmehr über den Herrn des Himmels erhoben, so daß man die Gefäße seines Tempels vor dich hat bringen müssen, damit du mit deinen Großen, deinen Gemahlinnen und Nebenfrauen Wein aus ihnen tränkest; und auf die Götter von Silber und Gold, von Kupfer und Eisen, Holz und Stein, die weder sehen noch hören können und keinen Verstand besitzen, hast du Loblieder gesungen, dagegen dem Gott, in dessen Hand dein Lebensodem steht und von dem dein ganzes Schicksal abhängt, hast du keine Ehre erwiesen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 5, 24, 'Infolgedessen ist diese gewölbte Hand von ihm gesandt und die Schrift dort hingezeichnet worden.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 5, 25, 'Was dort aber geschrieben steht, lautet so: Mene, mene, tekel upharsin;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 5, 26, 'und dies ist die Deutung der Worte: Mene = gezählt hat Gott die Tage deines Königtums und ihm ein Ende bereitet;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 5, 27, 'Tekel = gewogen bist du auf der Waage und zu leicht erfunden;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 5, 28, 'Peres = zerteilt wird dein Reich und wird den Medern und Persern gegeben.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 5, 29, 'Hierauf gab Belsazar Befehl, und man kleidete Daniel in Purpur, legte ihm eine goldene Kette um den Hals und rief öffentlich von ihm aus, daß er als Dritter im Reiche herrschen solle. –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 5, 30, 'Noch in derselben Nacht wurde Belsazar, der Chaldäerkönig, ermordet,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 6, 1, 'und Darius, der Meder, erhielt die Herrschaft im Alter von zweiundsechzig Jahren.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 6, 2, 'Darius befand es für gut, hundertundzwanzig Satrapen über sein Reich einzusetzen, die im ganzen Reiche verteilt sein sollten,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 6, 3, 'über diese aber drei Minister zu bestellen, von denen Daniel einer war; diesen sollten jene Satrapen Rechenschaft ablegen, damit der König keinen Schaden erlitte.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 6, 4, 'Da überragte denn dieser Daniel wiederum die übrigen Minister und die Satrapen, weil ein außergewöhnlicher Geist in ihm wohnte; und der König ging mit dem Gedanken um, ihm die Verwaltung des ganzen Reiches zu übertragen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 6, 5, 'Da suchten die Minister und die Satrapen eine Anklage gegen Daniel auf Grund seiner Geschäftsführung ausfindig zu machen, konnten aber keinerlei Schuld und nichts Nachteiliges bei ihm entdecken, weil er treu war und ihm keinerlei Nachlässigkeit der Verfehlung nachzuweisen war.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 6, 6, 'Da sagten jene Männer: »Wir werden gegen diesen Daniel niemals einen Anklagegrund ausfindig machen, es sei denn in betreff seiner Gottesverehrung.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 6, 7, 'Hierauf begaben sich jene Minister und die Satrapen eilends zum König und sagten zu ihm: »König Darius, mögest du ewig leben!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 6, 8, 'Sämtliche Oberbeamte des Reiches, die Staatsräte und Satrapen, die Kronräte und Befehlshaber haben es für ratsam erachtet, daß eine königliche Verordnung zu erlassen und ein Verbot aufzustellen sei, wonach jeder, der im Verlauf von dreißig Tagen eine Bitte an irgendeinen Gott oder an einen Menschen richtet außer an dich, o König, in die Löwengrube geworfen werden soll.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 6, 9, 'Nun denn, o König, erlaß das Verbot und laß eine schriftliche Verordnung ergehen, die nach dem unwiderruflichen Gesetz der Meder und Perser nicht rückgängig gemacht werden darf!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 6, 10, 'Daraufhin ließ der König Darius die schriftliche Verordnung mit dem darin enthaltenen Verbot ausfertigen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 6, 11, 'Sobald nun Daniel erfuhr, daß die Verordnung ausgefertigt war, begab er sich in seine Wohnung, wo er in seinem Obergemach Fenster hatte, die nach Jerusalem hin offen standen; er warf sich dort täglich dreimal auf die Knie nieder, verrichtete sein Gebet und seine Lobpreisung vor seinem Gott ganz so, wie er es auch vordem regelmäßig getan hatte.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 6, 12, 'Da stürmten jene Männer herbei und fanden Daniel, wie er vor seinem Gott betete und flehte.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 6, 13, 'Darauf traten sie vor den König und fragten mit Bezug auf das königliche Verbot: »Hast du nicht ein Verbot ausfertigen lassen, wonach jeder, der innerhalb der nächsten dreißig Tage eine Bitte an irgendeinen Gott oder einen Menschen richten würde außer an dich, o König, in die Löwengrube geworfen werden soll?« Der König antwortete: »Die Sache steht fest nach dem unwiderruflichen Gesetz der Meder und Perser.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 6, 14, 'Darauf erwiderten sie dem König: »Daniel, einer von den in die Verbannung hergeführten Judäern, hat nicht auf dich, o König, geachtet, noch auf das Verbot, das du hast ausfertigen lassen, sondern verrichtet dreimal täglich sein Gebet.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 6, 15, 'Als der König das hörte, wurde er über die Mitteilung sehr betrübt und sann darüber nach, wie er Daniel retten könnte, und war bis Sonnenuntergang bemüht, ihn frei zu machen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 6, 16, 'Da stürmten aber jene Männer (wiederum) zum König und sagten zu ihm: »Bedenke, o König, daß bei den Medern und Persern ein Gesetz besteht, nach welchem kein vom König erlassenes Verbot oder Gebot rückgängig gemacht werden darf.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 6, 17, 'Da gab der König Befehl, worauf man Daniel herbeiholte und ihn in den Löwenzwinger warf. Dabei richtete der König an Daniel die Worte: »Dein Gott, dem du mit aller Ausdauer dienst, der möge dich retten!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 6, 18, 'Hierauf wurde ein Stein herbeigebracht und oben auf die Öffnung der Grube gelegt; der König aber versiegelte ihn mit seinem Siegelring und mit dem Siegel seiner obersten Beamten, damit kein unbefugtes Eingreifen in die Sache Daniels möglich sei.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 6, 19, 'Hierauf begab sich der König in seinen Palast zurück und verbrachte die Nacht, ohne etwas zu genießen; er ließ auch keine von seinen Frauen zu sich führen, doch kein Schlaf kam in seine Augen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 6, 20, 'Dann stand der König frühmorgens, sobald es hell wurde, auf und begab sich eiligst zu der Löwengrube;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 6, 21, 'und als er sich der Grube näherte, rief er dem Daniel mit angstvoller Stimme zu und richtete die Frage an ihn: »Daniel, Verehrer des lebendigen Gottes! Hat dein Gott, dem du mit aller Ausdauer dienst, dich vor den Löwen zu retten vermocht?«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 6, 22, 'Da antwortete Daniel dem König: »O König, mögest du ewig leben!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 6, 23, 'Mein Gott hat seinen Engel gesandt und den Löwen den Rachen verschlossen, so daß sie mir nichts zuleide getan haben, weil meine Unschuld ihm bekannt war; und auch dir gegenüber habe ich mir kein Unrecht zuschulden kommen lassen.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 6, 24, 'Da wurde der König hoch erfreut; er ließ Daniel aus der Grube heraufholen; und als man ihn heraufgezogen hatte, fand sich nicht die geringste Verletzung an ihm, weil er auf seinen Gott vertraut hatte.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 6, 25, 'Dann wurden auf Befehl des Königs jene Männer, die Daniel verleumdet hatten, herbeigeholt und samt ihren Kindern und Frauen in die Löwengrube geworfen; und ehe sie noch den Boden der Grube erreicht hatten, waren die Löwen schon über sie hergefallen und hatten ihnen alle Knochen zermalmt.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 6, 26, 'Hierauf schrieb der König Darius an alle Völker, Volksstämme und Zungen, die auf der ganzen Erde wohnten: »Heil möge euch in Fülle zuteil werden!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 6, 27, 'Hiermit ergeht der Befehl von mir, daß man im ganzen Bereich meiner königlichen Herrschaft vor dem Gott Daniels zittern und ihn fürchten soll; denn er ist der lebendige Gott, der in Ewigkeit bleibt; sein Reich ist unzerstörbar, und seine Herrschaft nimmt kein Ende.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 6, 28, 'Er errettet und befreit und vollführt Zeichen und Wunder am Himmel und auf Erden, er, der Daniel aus der Gewalt der Löwen errettet hat.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 6, 29, 'Und dieser Daniel war ein einflußreicher Mann während der Regierung des Darius und auch während der Regierung des Persers Cyrus.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 7, 1, 'Im ersten Regierungsjahre Belsazars, des Königs von Babylon, sah Daniel einen Traum, und Erscheinungen traten ihm auf seinem Lager vor die Augen. Darauf schrieb er den Traum nieder und berichtete die Hauptsachen,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 7, 2, 'mit folgenden Worten: »Ich, Daniel, hatte in meinem Nachtgesicht eine Erscheinung und sah, wie die vier Winde des Himmels das große Meer erregten.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 7, 3, 'Da stiegen vier gewaltige Tiere aus dem Meere hervor, jedes von dem andern verschieden.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 7, 4, 'Das erste sah aus wie ein Löwe, hatte aber Adlerflügel; ich betrachtete es, bis ihm die Flügel ausgerissen wurden und es von der Erde emporgehoben und wie ein Mensch aufrecht auf zwei Füße gestellt und ihm ein Menschenherz gegeben wurde. –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 7, 5, 'Darauf erschien ein anderes, zweites Tier, das einem Bären glich; es war nur auf der einen Seite aufgerichtet und hatte drei Rippen im Rachen zwischen seinen Zähnen, und es wurde ihm geboten: ›Auf! Friß viel Fleisch!‹ –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 7, 6, 'Als ich dann wieder hinblickte, sah ich ein anderes Tier, das einem Panther glich, aber vier Vogelflügel auf seinem Rücken hatte; auch vier Köpfe hatte das Tier, und ihm wurde Herrschermacht verliehen. –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 7, 7, 'Darauf erschien mir in meinen Nachtgesichten plötzlich ein viertes Tier, schrecklich und furchtbar und außerordentlich stark; es hatte gewaltige Zähne von Eisen (und Klauen von Erz); es fraß und zermalmte und zertrat das, was übriggeblieben war, mit seinen Füßen; es sah ganz anders aus als alle die vorigen Tiere und hatte auch noch zehn Hörner.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 7, 8, 'Während ich nun genau auf die Hörner achtgab, sah ich, wie ein anderes, kleines Horn zwischen ihnen hervorschoß, worauf drei von den ersten Hörnern vor ihm ausgerissen wurden; und jetzt sah ich, daß an diesem Horn Augen wie Menschenaugen saßen und ein Mund, der vermessene Reden führte.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 7, 9, '»Ich schaute zu, bis Stühle hingestellt wurden und ein ehrwürdiger Greis Platz nahm. Sein Gewand war weiß wie Schnee und sein Haupthaar wie reine Wolle; sein Thron bestand aus Feuerflammen und hatte Räder von loderndem Feuer.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 7, 10, 'Ein Feuerstrom ergoß sich und ging von ihm aus; tausendmal Tausende dienten ihm, und zehntausendmal Zehntausende standen dienstbereit vor ihm. Der Gerichtshof setzte sich, und (die) Bücher wurden aufgeschlagen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 7, 11, 'Ich schaute unverwandt hin wegen des Lärms der vermessenen Reden, die das Horn führte; ich schaute zu, bis das Tier getötet und sein Leib vernichtet und zum Verbrennen dem Feuer übergeben wurde.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 7, 12, 'Auch den übrigen Tieren wurde dann ihre Macht genommen und ihnen ihre Lebensdauer auf Jahr und Tag bestimmt. –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 7, 13, 'Während ich noch in das Anschauen der Nachtgesichte versunken war, sah ich, wie mit den Wolken des Himmels Einer kam, der wie eines Menschen Sohn aussah; dieser gelangte zu dem ehrwürdigen Greise und wurde vor ihn geführt.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 7, 14, 'Ihm wurde dann Macht, Ehre und Herrschaft verliehen, so daß alle Völker, Volksstämme und Zungen ihm untertan waren. Seine Macht sollte von ewiger Dauer und unvergänglich sein und sein Königreich ein solches, das niemals vernichtet werden kann.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 7, 15, '»Da ich, Daniel, mich infolgedessen in meinem Inneren beunruhigt fühlte und die Gesichte, die ich geschaut hatte, mir Angst verursachten,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 7, 16, 'näherte ich mich einem der Dastehenden und bat ihn um sichere Auskunft über dies alles. Da antwortete er mir, indem er mir Aufschluß über die Vorgänge gab:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 7, 17, '›Jene gewaltigen Tiere, vier an der Zahl, bedeuten vier Könige, die auf der Erde erstehen werden.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 7, 18, 'Aber die Heiligen des Höchsten werden die Herrschaft erhalten und werden die Herrschaft innehaben bis in Ewigkeit, ja bis in eine Ewigkeit von Ewigkeiten.‹');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 7, 19, 'Hierauf wünschte ich Sicheres über das vierte Tier zu erfahren, das sich von allen anderen unterschied und besonders furchtbar war, dessen Zähne von Eisen und dessen Klauen von Erz waren, das da fraß und zermalmte und, was übriggeblieben war, mit seinen Füßen zertrat;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 7, 20, 'auch über die zehn Hörner auf seinem Kopfe (wünschte ich sichere Auskunft) und über das andere (kleine) Horn, das hervorgeschossen und vor dem drei Hörner ausgefallen waren und das Augen hatte und einen Mund, der vermessene Reden führte, und das größer anzusehen war als die übrigen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 7, 21, 'Ich hatte auch gesehen, wie jenes Horn Krieg mit den Heiligen führte und sie überwältigte,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 7, 22, 'bis der ehrwürdige Greis kam und den Heiligen des Höchsten Recht geschafft wurde und die Zeit eintrat, wo die Heiligen die Herrschaft in dauernden Besitz nahmen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 7, 23, 'Er gab mir also folgende Auskunft: ›Das vierte Tier (bedeutet) ein viertes Reich, das auf Erden sein wird, verschieden von allen anderen Reichen; es wird die ganze Erde verschlingen und sie zertreten und zermalmen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 7, 24, 'Die zehn Hörner aber (bedeuten), daß aus eben diesem Reiche zehn Könige erstehen werden; und nach ihnen wird noch ein anderer auftreten, der von den früheren verschieden ist und drei Könige stürzen wird.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 7, 25, 'Er wird vermessene Reden gegen den Höchsten führen und die Heiligen des Höchsten mißhandeln und darauf ausgehen, die Festzeiten und das Gesetz (Gottes) zu ändern; und sie werden seiner Gewalt preisgegeben sein ein Jahr und zwei Jahre und ein halbes Jahr.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 7, 26, 'Dann aber wird der Gerichtshof Sitzung halten, und man wird ihm die Herrschaft entreißen, um sie endgültig zu vernichten und zu beseitigen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 7, 27, 'Alsdann wird das Königtum und die Herrschaft und die Macht über die Reiche unter dem ganzen Himmel dem Volke der Heiligen des Höchsten verliehen werden: sein Reich wird von ewiger Dauer sein, und alle anderen Mächte werden ihm dienen und untertan sein.‹«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 7, 28, 'Damit ist der Bericht zu Ende. Mich, Daniel, beunruhigten meine Gedanken sehr, so daß meine Gesichtsfarbe sich an mir veränderte; aber das Erlebnis habe ich in meiner Erinnerung festgehalten.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 8, 1, 'Im dritten Regierungsjahre des Königs Belsazar erschien mir, Daniel, ein Gesicht nach jenem, das mir als erstes erschienen war.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 8, 2, 'Als ich das Gesicht hatte, war es mir beim Anschauen, als ob ich mich in der Burg Susa, die in der Landschaft Elam liegt, befände; und ich sah mich in diesem Gesicht am Fluß Ulai.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 8, 3, 'Als ich nun meine Augen aufschlug und Umschau hielt, sah ich da einen Widder, der vor dem Fluß stand und zwei Hörner hatte; beide Hörner waren hoch, aber das eine war höher als das andere, und das höhere war zuletzt emporgewachsen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 8, 4, 'Ich sah nun, wie der Widder nach Westen und nach Norden und nach Süden stieß, und kein einziges Tier konnte ihm widerstehen und niemand vermochte aus seiner Gewalt zu erretten, und er tat, was ihm beliebte, und wurde immer stärker.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 8, 5, 'Während ich ihn noch aufmerksam betrachtete, sah ich einen Ziegenbock von Westen her über die ganze Erde weg kommen, ohne daß er den Boden (mit den Füßen) berührte, und der Bock hatte ein ansehnliches Horn zwischen seinen Augen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 8, 6, 'Als er nun bis zu dem Widder mit den zwei Hörnern, den ich vor dem Fluß hatte stehen sehen, gekommen war, rannte er wütend mit aller Kraft auf ihn los.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 8, 7, 'Ich sah dann, wie er nahe an den Widder herankam und sich erbittert auf ihn stürzte und den Widder stieß und ihm seine beiden Hörner zerbrach; und da der Widder nicht stark genug war, ihm zu widerstehen, schleuderte er ihn zu Boden und zertrat ihn, und niemand war da, der den Widder aus seiner Gewalt gerettet hätte.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 8, 8, 'Hierauf wurde der Ziegenbock überaus groß, als er aber am stärksten war, brach das große Horn ab, und vier andere ansehnliche Hörner wuchsen an seiner Stelle hervor nach den vier Himmelsgegenden hin.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 8, 9, 'Aus einem von ihnen aber kam ein anderes kleines Horn zum Vorschein, das dann über die Maßen groß wurde gegen Süden und gegen Osten und gegen das Prachtland der Erde.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 8, 10, 'Ja, es wuchs bis zum Heer des Himmels empor und warf einige von dem Heere und von den Sternen auf die Erde hinab und zertrat sie.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 8, 11, 'Sogar bis zu dem Fürsten des Heeres erhob es sich mit seiner Überhebung, so daß diesem das tägliche Opfer entzogen und die Stätte seines Heiligtums entehrt wurde;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 8, 12, 'und auf das tägliche Opfer wurde das Frevelopfer gelegt, und (das Horn) warf die Wahrheit zu Boden, und was es unternahm, das gelang ihm.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 8, 13, 'Da hörte ich einen Heiligen reden; es fragte nämlich ein Heiliger den betreffenden, der da redete: »Bis wann geht das Gesicht, daß das tägliche Opfer aufgehoben und der verwüstende Frevel aufgestellt und das Heiligtum zur Zertretung dahingegeben ist?«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 8, 14, 'Da antwortete er ihm: »Bis zu zweitausenddreihundert Abend-Morgen, dann wird das Heiligtum gerechtfertigt werden.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 8, 15, 'Als nun ich, Daniel, das Gesicht sah und es zu verstehen suchte, sah ich plötzlich Einen mir gegenüber stehen, der wie ein Mann aussah.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 8, 16, 'Dann hörte ich eine Menschenstimme über dem Ulai laut rufen: »Gabriel, erkläre diesem da das Gesicht!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 8, 17, 'Da kam er auf den Ort zu, wo ich stand; und als ich bei seiner Annäherung erschrak und mich auf mein Angesicht niederwarf, sagte er zu mir: »Gib acht, Menschenkind! Denn das Gesicht bezieht sich auf die Endzeit.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 8, 18, 'Als er aber so zu mir redete, wurde ich ohnmächtig und sank auf mein Angesicht zur Erde nieder; doch er faßte mich an und brachte mich wieder zu aufrechtem Stehen auf meinem Platze.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 8, 19, 'Dann sagte er: »Wisse wohl: ich will dir kundtun, was in der letzten Zeit des Zorns geschehen wird; denn das Gesicht bezieht sich auf die (von Gott) festgesetzte Endzeit.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 8, 20, 'Der zweihörnige Widder, den du gesehen hast, bedeutet die Könige von Medien und Persien;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 8, 21, 'der [zottige] Bock aber ist der König von Griechenland; und das große Horn, das sich auf seiner Stirn befindet, ist der erste König.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 8, 22, 'Daß dann, als es abbrach, vier andere Hörner an seiner Stelle hervorkamen (bedeutet): vier Reiche werden aus seinem Volk hervorgehen, aber ohne die Macht, wie jener sie besaß.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 8, 23, 'In der letzten Zeit ihrer Herrschaft aber, wenn die Frevler das Maß ihrer Sünden voll machen, wird ein König auftreten frechen Angesichts und ein Meister in Ränken.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 8, 24, 'Seine Macht wird gewaltig sein, aber nicht durch seine eigene Macht; er wird außerordentliches Unheil anrichten, und seine Unternehmungen werden Erfolg haben; er wird Mächtige und auch das Volk der Heiligen ins Verderben stürzen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 8, 25, 'Infolge seiner Klugheit wird ihm der Trug, mit dem er umgeht, gelingen, und er wird hochmütigen Sinnes werden und viele unversehens zugrunde richten; dann aber, wenn er sich gegen den Fürsten der Fürsten erhoben hat, wird er zerschmettert werden ohne Zutun von Menschenhand.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 8, 26, 'Und das Gesicht von den Abend-Morgen, das dir mitgeteilt worden ist, das ist zuverlässig; du aber verwahre das Gesicht unter Siegel, denn es bezieht sich auf eine ferne Zeit.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 8, 27, 'Hierauf war ich, Daniel, ganz erschöpft und lag einige Tage krank; dann stand ich zwar wieder auf und versah meinen Dienst beim König, befand mich aber wegen des Gesichts in entsetzlicher Aufregung; da ich es mir nicht erklären konnte.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 9, 1, 'Im ersten Regierungsjahre des Darius, des Sohnes des Ahasveros, der von medischer Herkunft war und die Herrschaft über das Reich der Chaldäer erlangt hatte,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 9, 2, 'im ersten Jahre seiner Regierung, richtete ich, Daniel, meine Aufmerksamkeit in den (heiligen) Schriften auf die Zahl der Jahre, in betreff derer das Wort des HERRN einst an den Propheten Jeremia ergangen war, daß nämlich über den Trümmern Jerusalems eine Zeit von siebzig Jahren hingehen sollte.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 9, 3, 'So richtete ich denn mein Angesicht zu Gott dem Herrn, um ihn mit Gebet und Flehen zu suchen unter Fasten und in Sack und Asche.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 9, 4, 'Ich betete also zum HERRN, meinem Gott, und legte mein Bekenntnis mit folgenden Worten ab: »Ach, Herr, du großer und furchtbarer Gott, der du deinen Bund und deine Gnade denen bewahrst, die dich lieben und deine Gebote halten!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 9, 5, 'Wir haben gesündigt und unrecht getan, wir sind gottlos und ungehorsam gewesen und von deinen Geboten und deinen Satzungen abgewichen;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 9, 6, 'wir haben auch nicht auf deine Knechte, die Propheten, gehört, die in deinem Namen zu unsern Königen und unsern Fürsten, zu unsern Vätern und dem ganzen Volk des Landes geredet haben.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 9, 7, 'Auf deiner Seite, Herr, ist die Gerechtigkeit, auf der unsrigen aber die Schamröte im Angesicht, wie es jetzt zu Tage liegt: für die Männer von Juda und die Bewohner Jerusalems und für alle Israeliten, sie seien nahe oder fern, in all den Ländern, wohin du sie verstoßen hast wegen der Untreue, die sie sich gegen dich haben zuschulden kommen lassen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 9, 8, 'Ja, HERR! Uns muß die Schamröte ins Angesicht steigen, unsern Königen, unsern Fürsten und unsern Vätern, weil wir gegen dich gesündigt haben.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 9, 9, 'Doch bei dem Herrn, unserm Gott, ist die Barmherzigkeit und die Vergebung, obschon wir uns gegen ihn aufgelehnt haben');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 9, 10, 'und der Stimme des HERRN, unsers Gottes, nicht gehorsam gewesen sind, um nach seinen Weisungen zu wandeln, die er uns durch seine Knechte, die Propheten, vorgelegt hat.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 9, 11, 'Ja, ganz Israel hat dein Gesetz übertreten und ist untreu gewesen, ohne deinen Weisungen Folge zu leisten. Darum ist auch der Fluch und Schwur über uns hereingebrochen, der im Gesetz Moses, des Knechtes Gottes, geschrieben steht, weil wir gegen Gott gesündigt haben;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 9, 12, 'und er hat nun an uns und an unseren Herrschern, die über uns regiert haben, seine Drohung in Erfüllung gehen lassen, die er ausgesprochen hat, daß er großes Unheil über uns verhängen wolle, so daß unter dem ganzen Himmel sich nirgends etwas so Schlimmes ereignet hat, wie es Jerusalem widerfahren ist.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 9, 13, 'Ja, wie es im Gesetz Moses geschrieben steht, so ist all dieses Unheil über uns hereingebrochen. Dennoch haben wir den HERRN, unsern Gott, nicht dadurch versöhnt, daß wir von unsern Sünden umgekehrt wären und auf deine Wahrheit geachtet hätten.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 9, 14, 'Darum ist der HERR auf das Unheil bedacht gewesen und hat es über uns kommen lassen; denn der HERR, unser Gott, ist gerecht in allen seinen Werken, die er vollführt; wir aber haben auf seine Stimme nicht geachtet.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 9, 15, 'Und nun, o Herr, unser Gott, der du dein Volk mit starker Hand aus Ägypten geführt und dir dadurch einen Namen gemacht hast bis auf den heutigen Tag: – wir haben gesündigt, haben gottlos gehandelt.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 9, 16, 'O Herr, laß doch nach allen Erweisen deiner Gerechtigkeit deinen Zorn und Grimm sich von deiner Stadt Jerusalem, von deinem heiligen Berge abwenden! Denn um unserer Sünden willen und wegen der Übertretungen unserer Väter ist Jerusalem und dein Volk für alle rings um uns wohnenden Völker ein Gegenstand des Hohns geworden.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 9, 17, 'Nun aber erhöre, unser Gott, das Gebet und Flehen deines Knechtes und laß dein Angesicht über dein verwüstetes Heiligtum leuchten um deinetwillen, o Herr!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 9, 18, 'Neige, mein Gott, dein Ohr und höre! Öffne deine Augen und sieh unsere Trümmer an und die Stadt, die nach deinem Namen genannt ist! Denn nicht auf Grund der Erweise unserer Gerechtigkeit bringen wir unser Flehen vor dich, nein, im Vertrauen auf deine große Barmherzigkeit.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 9, 19, 'O Herr, höre! Herr, vergib! Herr, merke auf und handle ohne Verzug um deiner selbst willen, du mein Gott! Denn deine Stadt und dein Volk tragen deinen Namen.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 9, 20, 'Während ich so noch redete und betete und meine Sünde sowie die Sünde meines Volkes Israel bekannte und mein Flehen für den heiligen Berg meines Gottes vor den HERRN, meinen Gott, brachte,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 9, 21, 'während ich also noch mein Gebet verrichtete, kam der Mann Gabriel, den ich früher schon in dem ersten Gesicht gesehen hatte, eilends auf mich zu geflogen um die Zeit des Abendopfers.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 9, 22, 'Er wollte mir Aufklärung geben und redete mich mit den Worten an: »Daniel, schon jetzt bin ich hergekommen, um dir zum richtigen Verständnis zu verhelfen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 9, 23, 'Als du zu beten begannst, erging ein Gotteswort, und ich bin gekommen, um dir Auskunft zu geben; denn du bist ein besonders geliebter Mann. So achte nun auf das Wort, damit du die Offenbarung genau verstehst!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 9, 24, 'Siebzig Wochen sind über dein Volk und über deine heilige Stadt bestimmt, um den Frevel zum Abschluß zu bringen und das Maß der Sünde voll zu machen, um die Verschuldung zu sühnen und ewige Gerechtigkeit herbeizuführen und das Gesicht und den (Ausspruch des) Propheten zu bestätigen und ein Hochheiliges zu salben.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 9, 25, 'Wisse also und verstehe: Vom Ausgang des Wortes in betreff der Wiederherstellung und Neugründung Jerusalems bis zu einem Gesalbten, einem Fürsten, sind sieben Jahrwochen, und innerhalb von zweiundsechzig Jahrwochen wird es wiederhergestellt und neuerbaut sein mit Marktplätzen und Gräben, allerdings in drangsalsreichen Zeiten.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 9, 26, 'Und nach den zweiundsechzig Jahrwochen wird ein Gesalbter ums Leben gebracht werden ohne Richterspruch; und die Stadt samt dem Heiligtum wird das Kriegsvolk eines Fürsten zerstören, der heranzieht, dessen Ende aber durch eine Sturmflut eintritt; und bis zum Ende wird Krieg stattfinden, festbeschlossene Verwüstungen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 9, 27, 'Und wird er einen festen Bund mit der Volksmenge eine Jahrwoche lang schließen und während der Hälfte der Jahrwoche Schlacht- und Speisopfer abschaffen; und an ihrer Stelle wird der Greuel der Verwüstung aufgestellt sein, und zwar so lange, bis die festbeschlossene Vernichtung sich über die Verwüstung ergießt.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 10, 1, 'Im dritten Regierungsjahre des Perserkönigs Cyrus wurde dem Daniel, der auch den Namen Beltsazar führte, ein Wort geoffenbart, und das Wort ist zuverlässig und (bezieht sich auf) große Trübsal; er aber achtete genau auf die Offenbarung und gab auf das Gesicht acht.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 10, 2, 'In jener Zeit stellte ich, Daniel, drei volle Wochen hindurch Trauer an:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 10, 3, 'leckere Speisen genoß ich nicht, und weder Fleisch noch Wein kam in meinen Mund; auch salbte ich mich nicht, bis drei volle Wochen vergangen waren.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 10, 4, 'Am vierundzwanzigsten Tage des ersten Monats nun befand ich mich am Ufer des großen Stromes, nämlich des Hiddekel;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 10, 5, 'und als ich dort meine Augen aufschlug und Umschau hielt, sah ich da einen Mann stehen, der in Linnen gekleidet war und um die Hüften einen Gürtel von feinem Uphasgold trug.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 10, 6, 'Sein Leib war wie Chrysolith, sein Gesicht leuchtete wie Blitzesschein und seine Augen wie Feuerflammen; seine Arme und Beine funkelten wie poliertes Erz; und wenn er redete, klang der Schall seiner Stimme wie das Tosen einer Volksmenge.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 10, 7, 'Ich, Daniel, war der einzige, der die Erscheinung sah, während die Männer, die bei mir waren, die Erscheinung nicht sahen; doch befiel sie ein solcher Schrecken, daß sie flohen, um sich zu verstecken.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 10, 8, 'So blieb ich denn allein zurück und sah diese gewaltige Erscheinung; doch alle Kraft entschwand mir: mein Gesicht entfärbte sich bis zur Unkenntlichkeit, und ich wurde völlig kraftlos.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 10, 9, 'Als er dann laut zu reden begann und ich den Schall seiner Worte vernahm, sank ich ohnmächtig auf mein Angesicht zur Erde nieder.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 10, 10, 'Da berührte mich plötzlich eine Hand und half mir, daß ich mich zitternd auf meine Knie und Hände erhob.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 10, 11, 'Dann sagte er zu mir: »Daniel, du vielgeliebter Mann! Gib auf die Worte acht, die ich an dich richte, und bleibe aufrecht auf deinem Platze stehen; denn ich bin jetzt eben zu dir gesandt worden.« Als er so zu mir sprach, erhob ich mich zitternd.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 10, 12, 'Dann fuhr er fort: »Fürchte dich nicht, Daniel! Denn gleich am ersten Tage, als du deinen Sinn darauf richtetest, Belehrung zu erlangen und dich vor deinem Gott zu demütigen, haben deine Worte Erhörung gefunden. Ich hatte mich um deines Gebets willen aufgemacht, um zu kommen;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 10, 13, 'aber der Schutzengel des Perserreichs stellte sich mir einundzwanzig Tage lang entgegen, bis mir endlich Michael, einer der obersten Engelfürsten, zu Hilfe kam, worauf ich ihn dort bei dem Schutzengel der Perserkönige allein gelassen habe');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 10, 14, 'und nun hergekommen bin, um dich wissen zu lassen, was deinem Volk am Ende der Tage widerfahren wird; denn das Gesicht bezieht sich wiederum auf (ferne) Tage.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 10, 15, 'Während er nun in dieser Weise zu mir redete, schlug ich die Augen zu Boden nieder und war sprachlos;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 10, 16, 'doch siehe, da berührte der, welcher wie ein Mensch gestaltet war, meine Lippen, so daß ich meinen Mund wieder öffnen und reden konnte; und ich sagte zu dem, der vor mir stand: »Mein Herr, bei dem, was ich zu sehen bekam, hat mich Todesangst befallen, so daß ich keine Kraft mehr behielt.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 10, 17, 'Und wie könnte auch ein so geringer Knecht meines Herrn (wie ich) mit einem so hohen Herrn reden? Ja, auch jetzt noch ist keine Kraft in mir geblieben, und selbst der Atem ist mir ausgegangen!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 10, 18, 'Da berührte der, welcher wie ein Mensch aussah, mich nochmals und verlieh mir neue Kraft');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 10, 19, 'und sagte zu mir: »Fürchte dich nicht, vielgeliebter Mann! Friede sei mit dir! Sei stark, ja sei stark!« Als er so zu mir sprach, fühlte ich mich gestärkt, so daß ich sagte: »Mein Herr möge nun reden, denn du hast mich gestärkt.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 10, 20, 'Da erwiderte er: »Weißt du, warum ich zu dir gekommen bin? Allerdings muß ich sogleich wieder umkehren, um mit dem Schutzengel Persiens zu kämpfen; und wenn ich mit ihm fertig bin, dann kommt sogleich der Schutzengel von Griechenland herbei,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 10, 21, 'b und kein einziger steht mir im Kampfe gegen jene (beiden) mit Entschiedenheit zur Seite außer eurem Schutzengel Michael.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 1, 'Aber auch ich habe ihm im ersten Regierungsjahre des Meders Darius als Helfer und Beschützer zur Seite gestanden.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 2, 'a Doch ich will dir nun verkünden, was im Buch der Wahrheit aufgezeichnet steht.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 3, 'Da wird dann ein Heldenkönig auftreten und über ein gewaltiges Reich herrschen und alles ausführen, was ihm beliebt. Da wird dann ein Heldenkönig auftreten und über ein gewaltiges Reich herrschen und alles ausführen, was ihm beliebt.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 4, 'Doch kaum ist er aufgetreten, so wird sein Reich zerbrechen und nach den vier Himmelsgegenden hin zerteilt werden, aber weder an seine Nachkommen gelangen noch bei der Macht verbleiben, mit der er geherrscht hat; vielmehr wird sein Reich zerschlagen werden und anderen zufallen mit Ausschluß von jenen.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 5, '»Hierauf wird der König des Südreichs erstarken, doch einer von seinen Feldherren wird ihn an Macht noch übertreffen und die Herrschaft gewinnen: weithin wird sein Reich sich erstrecken.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 6, 'Nach Verlauf von Jahren aber werden sie sich verbünden; und die Tochter des Königs des Südreichs wird zu dem Könige des Nordreichs ziehen, um ein friedliches Verhältnis zu schaffen; doch dies Hilfsmittel wird sich nicht als wirksam erweisen, und seine Arme werden nicht standhalten, sondern sie wird preisgegeben werden mitsamt ihrem Gefolge und ihrem Kinde und dem, der sie sich seinerzeit als Gattin zugesellt hatte.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 7, 'Doch einer von den Schößlingen aus der gleichen Wurzel, der sie entstammte, wird an der Stelle jenes (als Rächer) erstehen und gegen die Heeresmacht zu Felde ziehen und in eine Festung des nördlichen Königs eindringen; er wird mit ihnen (nach Gutdünken) verfahren und siegreich sein.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 8, 'Auch ihre Götter samt ihren Gußbildern und ihren kostbaren Geräten von Silber und Gold wird er als Beute nach Ägypten entführen und sich dann jahrelang von dem König des Nordreichs fernhalten;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 9, 'dieser wird dann in das Reich des südlichen Königs eindringen, doch in sein Land zurückkehren.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 10, 'Nun aber wird sein Sohn sich (zum Kriege) rüsten und eine Menge gewaltiger Streitkräfte zusammenbringen; er wird herankommen und (das Land) überschwemmen und überfluten und beim zweiten Zug im Kampf bis zu dessen Festung vordringen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 11, 'Da wird der König des Südreichs erbittert werden, wird ausziehen und mit ihm, dem König des Nordreichs, kämpfen; der wird zwar ein großes Heer aufstellen, aber dies Heer wird in die Gewalt jenes fallen');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 12, 'und trotz seiner Größe vernichtet werden. Dadurch wird sein Sinn stolz werden, und wenn er auch Zehntausende zu Boden streckt, wird er doch nicht die Oberhand behalten.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 13, 'Der König des Nordreichs wird nämlich nochmals ein Heer aufstellen, größer als das vorige, und nach Ablauf von Zeiten [von Jahren] mit starker und wohlgerüsteter Heeresmacht aufs neue kommen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 14, 'Zu derselben Zeit werden viele gegen den König des Südreichs aufstehen; auch aus deinem Volk werden sich gewalttätige Leute erheben, um die Weissagung in Erfüllung gehen zu lassen, werden aber zu Fall kommen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 15, 'Dann wird der König des Nordreichs heranziehen, wird einen Wall aufwerfen und eine starke Festung erobern; und die Streitkräfte des Südreichs werden nicht standhalten; sogar dessen auserlesene Mannschaft wird keine Kraft zum Widerstand haben,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 16, 'sondern der, welcher gegen ihn herangezogen ist, wird nach seinem Gutdünken schalten, ohne daß jemand ihm zu widerstehen vermag; und er wird im Prachtlande festen Fuß fassen, und Verwüstung wird von ihm ausgehen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 17, 'Dann wird er sein Augenmerk darauf richten, das ganze Reich jenes in seine Gewalt zu bringen, indem er einen Vertrag mit ihm schließt und ihm eine junge Tochter zur Frau gibt, um (das Land) zugrunde zu richten; aber es wird nicht zustande kommen und [ihm] nicht gelingen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 18, 'Da wird er denn sein Augenmerk auf die Küstenländer richten und viele erobern; aber ein Heerführer wird seinem Hohnlachen ein Ende machen und sein Höhnen ihm übel heimzahlen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 19, 'Hierauf wird er sein Augenmerk auf die Festungen seines Landes richten, dabei aber straucheln und zu Fall kommen und für immer verschwinden.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 20, 'An seine Stelle wird dann ein anderer treten, der einen Gelderpresser durch das Prachtland seines Reiches ziehen läßt; doch schon nach einigen Tagen wird er unschädlich gemacht, und zwar weder durch Zorn noch durch Krieg.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 21, '»An seiner Statt wird dann ein verworfener Mensch auftreten, dem die königliche Würde nicht zugedacht war; aber er wird unversehens kommen und sich der Herrschaft durch Ränke bemächtigen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 22, 'Die heranflutenden Heere werden vor ihm weggeschwemmt werden, und zerschmettert wird sogar der Bundesfürst;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 23, 'denn sogleich nach seiner Befreundung mit ihm wird er Trug üben und heranziehen und trotz seiner geringen Streitkräfte Macht gewinnen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 24, 'Unversehens wird er in die fettesten Gegenden einer Landschaft einfallen und Dinge verüben, die weder seine Väter noch die Väter seiner Väter verübt haben; Raub, Beute und Güter wird er verschwenderisch unter sie verteilen und gegen feste Plätze seine Anschläge richten, allerdings nur eine Zeitlang.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 25, 'Hierauf wird er seine Macht und seinen Mut gegen den König des Südreichs aufbieten mit einem großen Heer; und der König des Südreichs wird mit großer und überaus starker Heeresmacht in den Krieg ziehen, jedoch nicht standhalten; denn man wird Anschläge gegen ihn ersinnen,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 26, 'und die eigenen Tischgenossen werden seinen Untergang herbeiführen: sein Heer wird weggeschwemmt, und viele Erschlagene werden fallen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 27, 'Die beiden Könige aber werden im Herzen auf Arglist sinnen und an einem Tische (speisend oder: sitzend) sich gegenseitig belügen; doch wird es nicht gelingen, denn das Ende steht noch aus bis zu der (von Gott) bestimmten Zeit.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 28, 'Darauf wird er mit großem Reichtum in sein Land zurückkehren, sein Herz aber wird gegen den heiligen Bund gerichtet sein; er wird (den Plan) auch ausführen und dann in sein Land zurückkehren.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 29, 'Zur bestimmten Zeit wird er dann wieder gegen das Südreich ziehen, doch wird es dieses zweite Mal nicht so gehen wie zuerst;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 30, 'denn Schiffe aus Kitthim werden sich ihm entgegenstellen, so daß er den Mut verliert; da wird er umkehren und seinen Grimm an dem heiligen Bunde auslassen und nach der Heimkehr sein Augenmerk auf die richten, welche vom heiligen Bunde abfallen.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 31, '»Da werden dann Truppen von ihm (entsandt) dastehen und das Heiligtum, die Burg, entweihen; das tägliche Opfer werden sie abschaffen und den Greuel der Verwüstung aufstellen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 32, 'Durch verführerische Worte wird er die, welche am Bunde freveln, zum Treubruch verleiten; aber das Volk derer, die ihren Gott kennen, wird fest bleiben und danach handeln.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 33, 'Und die Verständigen unter dem Volk werden gar viele zum Aufmerken bringen, aber durch Schwert und Feuer, durch Gefängnis und Ausplünderung eine Zeitlang niedergehalten werden.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 34, 'Bei diesem ihrem Unterliegen wird ihnen zwar eine kleine Hilfe zuteil werden, aber viele werden sich ihnen nur aus Heuchelei anschließen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 35, 'Auch von den Einsichtigen werden manche den Untergang finden, damit eine Läuterung, eine Sichtung und Reinigung bei ihnen bewirkt werde bis zur Endzeit; denn die (von Gott) bestimmte Zeit steht immer noch aus.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 36, '»Der König wird alsdann nach seinem Gutdünken handeln, sich überheben und sich gegen jeden Gott groß dünken; er wird auch gegen den Gott der Götter unerhörte Reden führen und dabei Erfolg haben, bis das Maß des (göttlichen) Zornes voll ist; denn was beschlossen ist, kommt zur Ausführung.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 37, 'Auch um die Götter seiner Väter wird er sich nicht kümmern und weder dem Lieblingsgott der Frauen noch irgendeinem anderen Gott Beachtung schenken, sondern über alle sich erheben.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 38, 'An ihrer Stelle wird er den Gott der Burgen verehren, und einen Gott, den seine Väter nicht gekannt haben, wird er mit Gold und Silber, mit Edelsteinen und Kleinodien ehren.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 39, 'In die festen Plätze wird er Kriegsvolk des fremden Gottes legen; wer diesen anerkennt, den wird er mit Ehren überhäufen und ihnen Gewalt über viele verleihen und zur Belohnung Land unter sie verteilen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 40, 'In der Endzeit aber wird der König des Südreichs feindlich mit ihm zusammenstoßen. Da wird dann der König des Nordreichs mit Wagen und Reitern und vielen Schiffen gegen ihn anstürmen und in die Länder (des Südens) eindringen und sie überschwemmen und überfluten.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 41, 'Dabei wird er auch in das Prachtland einfallen, und Zehntausende werden ihren Untergang finden; folgende aber werden seiner Gewalt entgehen: Edom und Moab und der Hauptteil der Ammoniter.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 42, 'Dann wird er seine Hand weiter nach Ländern ausstrecken; auch das Land Ägypten wird ihm nicht entgehen,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 43, 'sondern er wird sich der Gold- und Silberschätze und überhaupt aller Kostbarkeiten Ägyptens bemächtigen, und Libyer und Äthiopier werden in seinem Gefolge sein.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 44, 'Aber Gerüchte aus dem Osten und aus dem Norden werden ihn erschrecken, und in höchster Wut wird er ausziehen, um viele zu vernichten und zu vertilgen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 45, 'Und er wird seine Palastgezelte zwischen dem großen Meere und dem Berge der heiligen Pracht aufschlagen; dann aber wird sein Ende ihn ereilen, ohne daß jemand ihm zu Hilfe kommt.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 12, 1, '»Zu jener Zeit nämlich wird Michael auftreten, der große Engelfürst, der deine Volksgenossen beschützt, und es wird eine Zeit der Bedrängnis eintreten, wie noch keine dagewesen ist, seitdem es Völker gibt, bis zu jener Zeit; aber dein Volk wird in jener Zeit gerettet werden, nämlich ein jeder, der sich im Buch (des Lebens) aufgezeichnet findet.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 12, 2, 'Und viele von denen, die im Staube der Erde schlafen, werden erwachen, die einen zu ewigem Leben, die anderen zu Schmach, zu ewigem Abscheu.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 12, 3, 'Die Verständigen aber werden leuchten wie der Glanz der Himmelsfeste, und die, welche viele zur Gerechtigkeit geführt haben, wie die Sterne in alle Ewigkeit.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 12, 4, '»Du aber, Daniel, halte das Gesagte unter Verschluß und versiegle das Buch bis zur Endzeit; viele werden es dann durchforschen, und so wird die Erkenntnis zunehmen.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 12, 5, 'Als ich, Daniel, mich nun umschaute, sah ich zwei andere (Engel) dastehen, den einen auf diesem, den andern auf jenem Ufer des Stromes;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 12, 6, 'und der eine sagte zu dem in Linnen gekleideten Manne, der (jetzt) über den Fluten des Stromes stand: »Wie lange (wird es noch dauern, bis) das Ende dieser wunderbaren Dinge (eintritt)?«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 12, 7, 'Da hörte ich den in Linnen gekleideten Mann, der über den Fluten des Stromes stand; er erhob seine rechte und seine linke Hand zum Himmel und schwur bei dem ewig Lebenden: »Noch eine Zeit, (zwei) Zeiten und eine halbe Zeit; und sobald die Macht des Zerstörers des heiligen Volkes ihr Ende erreicht hat, dann wird dies alles sich erfüllen!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 12, 8, 'Ich hörte dies wohl, verstand es aber nicht und fragte deshalb: »Mein Herr, was wird der Ausgang von diesen dingen sein?«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 12, 9, 'Da antwortete er: »Gehe, Daniel! Denn die Offenbarungen sollen verschlossen und versiegelt bleiben bis zur Endzeit.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 12, 10, 'Viele werden ausgesondert, gereinigt und geläutert werden, aber die Gottlosen werden gottlos handeln; und kein Gottloser wird Verständnis dafür haben, während die Verständigen es verstehen werden.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 12, 11, 'Und von der Zeit an, wo das tägliche Opfer abgeschafft und der Greuel der Verwüstung aufgestellt wird, sind es 1290 Tage.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 12, 12, 'Wohl dem, der da ausharrt und 1335 Tage erreicht!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 12, 13, 'Du aber gehe hin, dem Ende entgegen! Du darfst nun ruhen und wirst zu deinem Lose aufstehen am Ende der Tage.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 1, 1, '(Dies ist) das Wort des HERRN, das an Hosea, den Sohn Beeris, ergangen ist in den Tagen der judäischen Könige Ussia, Jotham, Ahas und Hiskia und in den Tagen des israelitischen Königs Jerobeam, des Sohnes des Joas.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 1, 2, 'Als der HERR zum erstenmal mit Hosea redete, sagte der HERR zu Hosea: »Gehe hin, nimm dir ein Dirnenweib und Dirnenkinder! Denn das Land ist ehebrecherisch vom HERRN abgefallen (und ganz zur Dirne geworden).«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 1, 3, 'Da ging (Hosea) hin und heiratete Gomer, die Tochter Diblaims; die wurde guter Hoffnung und gebar ihm einen Sohn.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 1, 4, 'Da sagte der HERR zu ihm: »Gib ihm den Namen ›Jesreel‹! Denn schon in nächster Zeit will ich für das zu Jesreel vergossene Blut das Strafgericht am Haus Jehus vollziehen und dem Königtum des Hauses Israel ein Ende machen,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 1, 5, 'auch will ich an jenem Tage den Bogen Israels zerbrechen in der Talebene Jesreel.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 1, 6, 'Hierauf wurde sie abermals guter Hoffnung und gebar eine Tochter; da sagte er zu ihm: »Gib ihr den Namen ›Ungeliebt‹! Denn ich will fortan dem Hause Israel keine Liebe mehr erweisen, daß ich ihnen immerfort Erbarmen gewähren sollte.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 1, 7, 'Aber dem Hause Juda will ich Erbarmen erweisen und ihnen Rettung schaffen durch (mich), den HERRN, ihren Gott; nicht aber will ich ihnen Rettung schaffen durch Bogen, Schwert und Krieg, auch nicht durch Rosse und Reiter.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 1, 8, 'Als sie dann die ›Ungeliebt‹ entwöhnt hatte, wurde sie nochmals guter Hoffnung und gebar einen Sohn.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 1, 9, 'Da sagte der HERR: »Gib ihm den Namen ›Nicht-mein-Volk‹, denn ihr seid nicht mein Volk, und ich gehöre nicht (mehr) zu euch.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 2, 1, '(Dereinst) jedoch wird die Zahl der Kinder Israel dem Sand am Meer gleichen, der sich nicht messen und nicht zählen läßt; und es wird geschehen: statt daß man jetzt zu ihnen sagt: »Ihr seid ›Nicht-mein-Volk‹«, werden sie »Söhne des lebendigen Gottes« genannt werden.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 2, 2, 'Dann werden die Kinder Juda und die Kinder Israel sich zusammentun und über sich ein Oberhaupt setzen und aus dem Lande hinaufziehen; denn groß ist der Tag von Jesreel.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 2, 3, 'Sagt zu eurem Bruder: »Mein Volk« und zu eurer Schwester »Gnadenreiche«!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 2, 4, '»Stellt eure Mutter zur Rede, ja, zur Rede – sie ist ja nicht mehr mein Weib, und ich bin nicht ihr Mann –, daß sie die (Zeichen ihrer) Buhlerei aus ihrem Gesicht und die (Zeichen ihrer) Ehebrecherei von ihrem Busen wegschaffe!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 2, 5, 'Sonst werde ich sie nackt ausziehen und sie so hinstellen, wie sie am Tage ihrer Geburt war, mache sie der Wüste gleich, lasse sie werden wie Ödland und lasse sie vor Durst sterben.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 2, 6, 'Auch ihren Kindern will ich keine Liebe mehr erweisen, weil sie Kinder einer Dirne sind;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 2, 7, 'denn ihre Mutter hat Ehebruch begangen, ihre Erzeugerin sich mit Schande bedeckt; sie hat ja doch gesagt: ›Ich will meinen Liebhabern nachgehen, die mir mein Brot und mein Wasser, meine Wolle und meinen Flachs, mein Öl und meine Getränke geben!‹');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 2, 8, 'Darum will ich ihr nunmehr den Weg mit Dornen verzäunen und eine Mauer vor ihr aufführen, daß sie ihre Pfade nicht mehr finden soll.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 2, 9, 'Wenn sie dann ihren Buhlen nachläuft, ohne sie zu erreichen, und wenn sie nach ihnen sucht, ohne sie zu finden, so wird sie sagen: ›Ich will mich (lieber) aufmachen und zu meinem ersten Manne zurückkehren; denn damals ging es mir besser als jetzt.‹');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 2, 10, 'Sie ist sich (aber) nicht bewußt geworden, daß ich es bin, der ihr das Getreide, den Wein und das Öl gegeben und ihr das viele Silber und Gold geschenkt hat, das sie für den Baalsdienst verwandt haben.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 2, 11, 'Darum will ich mein Getreide zu seiner Zeit und meinen Wein zur bestimmten Stunde zurückhalten und will ihr meine Wolle und meinen Flachs entziehen, die ihr zur Bekleidung dienen sollten.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 2, 12, 'Vielmehr will ich nunmehr ihre Blöße vor den Augen ihrer Buhlen aufdecken – niemand soll sie meiner Hand entreißen! –,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 2, 13, 'und ich will all ihrer Lust ein Ende machen, ihren Festen und Neumonden, ihren Sabbaten und all ihren Feiertagen,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 2, 14, 'und will ihre Weinstöcke und ihre Feigenbäume verwüsten, von denen sie gesagt hat: ›Diese sind mein Buhllohn, den meine Liebhaber mir gegeben haben.‹ Ich will sie in eine Wildnis verwandeln, daß die Tiere des Feldes sie abfressen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 2, 15, 'So will ich das Strafgericht für die Festtage der Baalgötzen an ihr vollziehen, an denen sie ihnen Rauchopfer dargebracht und sich mit ihren Ringen und Geschmeiden geschmückt hat und ihren Buhlen nachgelaufen ist, während sie mich vergaß!« – so lautet der Ausspruch des HERRN.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 2, 16, '»Darum wisse wohl: ich will sie locken und sie in die Wüste führen und ihr dort zu Herzen reden');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 2, 17, 'und will ihr von dort aus ihre Weinberge wieder zuweisen und das Tal Achor zur Pforte der Hoffnung machen. Dann wird sie dort willfährig werden wie in den Tagen ihrer Jugend, wie zu der Zeit, als sie aus dem Lande Ägypten heraufzog.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 2, 18, 'Alsdann, an jenem Tage« – so lautet der Ausspruch des HERRN – »wirst du mich ›mein Mann‹ nennen und mich nicht mehr ›mein Baal‹ nennen;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 2, 19, 'und ich will die Namen der Baalgötzen aus ihrem Munde verschwinden lassen, so daß sie fortan mit ihren Namen nicht mehr angerufen werden.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 2, 20, 'Ich will auch an jenem Tage einen Bund zu ihren Gunsten mit den Tieren des Feldes, mit den Vögeln des Himmels und mit dem Gewürm des Erdbodens schließen, will Bogen, Schwerter und alles Kriegsgerät zerbrechen und aus dem Lande wegschaffen und sie in Sicherheit sich niederlegen lassen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 2, 21, 'Und ich will dich mir verloben auf ewig, ja, ich will dich mir verloben auf Grund von Gerechtigkeit und Recht, in Liebe und Erbarmen,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 2, 22, 'und will dich mir verloben in Treue, und du sollst mich, den HERRN, erkennen lernen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 2, 23, 'Und dann, an jenem Tage, da werde ich willfährig sein« – so lautet der Ausspruch des HERRN –, »da werde ich dem Himmel zu Willen sein, und dieser wird der Erde zu Willen sein,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 2, 24, 'und die Erde wird dem Getreide, dem Most und dem Öl zu Willen sein, und diese werden Jesreel zu Willen sein.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 2, 25, 'Und ich will sie mir im Lande fest einpflanzen und der ›Ungeliebten‹ Liebe erweisen und will zum ›Nicht-mein-Volk‹ sagen: ›Mein Volk bist du!‹, und dieses wird rufen: ›Mein Gott (bist du)!‹«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 3, 1, 'Hierauf sagte der HERR zu mir: »Gehe noch einmal hin und liebe ein Weib, das sich von einem andern lieben läßt und Ehebruch treibt, gleichwie der HERR die Kinder Israel liebt, obwohl sie sich fremden Göttern zuwenden und Liebhaber von Traubenkuchen sind.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 3, 2, 'So erkaufte ich mir denn (ein Weib) um fünfzehn Silberstücke und um anderthalb Scheffel Gerste,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 3, 3, 'sagte aber zu ihr: »Viele Tage lang sollst du mir still dasitzen, ohne Untreue zu begehen und ohne einem (andern) Manne anzugehören; und auch ich selbst werde nicht zu dir kommen.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 3, 4, 'Denn lange Zeit sollen die Kinder Israel still dasitzen ohne König und ohne Fürsten, ohne Schlachtopfer und ohne Malstein, ohne priesterliches Schulterkleid und ohne Hausgötzen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 3, 5, 'Danach werden die Israeliten umkehren, werden den HERRN, ihren Gott, und David, ihren König, suchen und voll banger Furcht zum HERRN und zu seiner Güte hineilen in der Späte der Tage.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 4, 1, 'Vernehmt das Wort des HERRN, ihr Kinder Israel! Denn der HERR erhebt eine Anklage gegen die Bewohner des Landes, weil keine Treue, keine Liebe und keine Gotteserkenntnis im Lande mehr vorhanden ist:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 4, 2, 'man schwört (falsch) und lügt, man mordet und stiehlt, man treibt Ehebruch und verübt Gewalttaten, so daß Blutschuld sich an Blutschuld reiht.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 4, 3, 'Darob muß das Land trauern, und alles, was darin wohnt, welkt dahin bis zu den Tieren des Feldes und den Vögeln des Himmels; ja selbst die Fische im Meer vergehen!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 4, 4, '»Doch niemand möge Beschuldigungen erheben und niemand spreche Tadel aus! Dein (ganzes) Volk gleicht ja den Priestern, gegen die sie Beschuldigungen erheben.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 4, 5, 'So wirst du (Priester) denn zu Fall kommen am hellen Tage, und auch die Prophetenschaft wird mit dir zu Fall kommen bei Nacht, und ich will deine Mutter vernichten,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 4, 6, 'und mein Volk fällt mit ihnen der Vernichtung anheim aus Mangel an Erkenntnis. Weil du, Priester, die Erkenntnis verworfen hast, verwerfe auch ich dich, daß du mir nicht mehr als Priester dienen sollst; und weil du das Gesetz deines Gottes vergessen hast, will auch ich deine Kinder vergessen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 4, 7, 'Je mehr ihrer wurden, desto mehr haben sie gegen mich gesündigt; darum will ich ihre Ehre in Schande verwandeln.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 4, 8, 'Die Sündopfer meines Volkes verzehren sie, und nach seinen Schuldopfern steht ihr Verlangen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 4, 9, 'So soll es denn den Priestern ebenso ergehen wie dem Volke. Ich will sie für ihren Wandel büßen lassen und ihnen nach ihrem ganzen Tun vergelten:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 4, 10, 'wenn sie essen, sollen sie nicht satt werden; wenn sie der Wollust pflegen, sollen sie kinderlos bleiben; denn sie haben es aufgegeben, sich um den HERRN zu kümmern.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 4, 11, '»Unzucht, Wein und Most benehmen den Verstand.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 4, 12, 'Mein Volk befragt sein hölzernes Götzenbild, und sein Stab muß ihm Auskunft geben; denn der Geist der Abgötterei hat sie betört, daß sie ihren Gott treulos verlassen haben und Götzendienst treiben.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 4, 13, 'Auf den Höhen der Berge bringen sie Schlachtopfer dar und lassen Weihrauch aufsteigen auf den Hügeln, unter Eichen, Pappeln und Terebinthen, deren Schatten ja so lieblich ist! Daher kommt es, daß eure Töchter Unzucht treiben und eure jungen Frauen Ehebruch begehen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 4, 14, 'An euren Töchtern will ich es nicht ahnden, daß sie Unzucht treiben, auch nicht an euren jungen Frauen, daß sie Ehebruch begehen; denn sie selbst (die Priester) gehen ja mit den Buhldirnen abseits und bringen mit den Tempelbuhlerinnen Schlachtopfer dar; so kommt denn das Volk, dem es an Einsicht gebricht, zu Fall!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 4, 15, 'Magst du, Israel, auch Götzendienst treiben, so möge doch Juda sich nicht verschulden! Geht also nicht nach Gilgal und zieht nicht nach Beth-Awen hinauf und schwört nicht (in Beerseba): »So wahr der HERR lebt!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 4, 16, 'Wenn Israel widerspenstig geworden ist wie eine störrige Kuh, kann der HERR sie da so weiden lassen wie ein Lamm auf weiter Trift?');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 4, 17, 'Ein Götzengesell ist Ephraim, eine Gesellschaft von Zechern.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 4, 18, 'Ist ihr Zechgelage zu Ende, so geben sie sich der Unzucht hin: leidenschaftlich verliebt sind seine Schildträger in Schande.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 4, 19, 'Der Sturmwind soll sie in seine Fittiche wickeln, so daß sie zuschanden werden ob ihren Altären!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 5, 1, '»Vernehmt dieses, ihr Priester, und merkt auf, ihr vom Hause Israel! Und ihr (Herren) vom Hofe des Königs, gebt acht! Denn euch steht das Gericht bevor, weil ihr eine Schlinge für Mizpa geworden seid und ein ausgespanntes Fangnetz auf dem Thabor');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 5, 2, 'und eine tiefe Fallgrube zu Sittim; ich aber werde für sie alle eine Zuchtrute werden!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 5, 3, 'Ich kenne Ephraim wohl, und Israel ist mir nicht verborgen; denn soeben erst hast du Ehebruch getrieben, Ephraim, und Israel hat sich verunreinigt.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 5, 4, 'Ihr ganzes Tun gestattet ihnen nicht, zu ihrem Gott umzukehren; denn der Geist der Abgötterei wohnt in ihrem Herzen, und Erkenntnis des HERRN besitzen sie nicht.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 5, 5, 'So legt denn der Hochmut Israels offen Zeugnis gegen ihn ab, und Ephraim kommt durch seine Verschuldung zu Fall; es wird auch Juda mit ihnen zu Fall kommen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 5, 6, 'Mit ihrem Kleinvieh und ihren Rindern kommen sie zwar, um den HERRN zu suchen, werden ihn aber nicht finden: er hat sich von ihnen losgesagt.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 5, 7, 'Sie haben Treubruch gegen den HERRN begangen, denn sie haben ein Geschlecht von unechten Kindern gezeugt; nunmehr wird das Neumondsopferfest sie verzehren mitsamt ihrem Erbbesitz.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 5, 8, '»Stoßt in die Posaune zu Gibea, in die Trompete zu Rama! Schlagt Lärm in Beth-Awen, setzt Benjamin in Schrecken!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 5, 9, 'Ephraim wird zur Einöde werden am Tage des Strafgerichts; was ich den Stämmen Israels angekündigt habe, trifft unfehlbar ein!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 5, 10, 'Judas Fürsten sind wie Leute geworden, welche die Grenzsteine verrücken: über sie lasse ich meinen Zorn sich ergießen wie Wasser.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 5, 11, 'Unterdrückt ist Ephraim, zerschlagen vom Strafgericht, weil es ihm beliebte, hinter dem Nichtigen herzulaufen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 5, 12, 'Ich aber bin für Ephraim wie die Motte gewesen und für das Haus Juda wie Wurmfraß.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 5, 13, 'Als nun Ephraim seine Krankheit erkannte und Juda seine eiternde Wunde, da wandte Ephraim sich an Assyrien, und das Reich Juda sandte zum Großkönig; der aber vermag euch nicht gesund zu machen und wird eure eiternde Wunde nicht heilen;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 5, 14, 'denn ich trete gegen Ephraim auf wie ein Löwe und gegen das Haus Juda wie ein junger Leu: ich, ich zerreiße und gehe davon, trage (den Raub) hinweg, ohne daß jemand Rettung bringen kann.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 5, 15, '»Ich will davongehen, mich an meine Wohnstätte zurückbegeben, bis sie sich schuldig fühlen und mein Angesicht suchen; wenn sie in Not sind, werden sie ernstliches Verlangen nach mir tragen (und sprechen):');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 6, 1, '›Kommt, laßt uns zum HERRN umkehren! Denn er hat uns zerrissen und wird uns auch wieder heilen; er hat uns (blutig) geschlagen und wird uns auch verbinden;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 6, 2, 'schon nach zwei Tagen wird er uns genesen lassen, am dritten Tage uns wieder aufhelfen, daß wir vor seinen Augen leben.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 6, 3, 'So laßt uns denn zur Erkenntnis kommen, ja der Erkenntnis des HERRN nachtrachten! Er wird so sicher erscheinen wie das Morgenlicht und wird über uns kommen wie der Regen, wie der Spätregen, der das Land tränkt.‹');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 6, 4, 'Was soll ich dir tun, Ephraim? Was soll ich dir tun, Juda? Eure Liebe gleicht ja doch dem Morgengewölk und dem Tau, der gar bald vergeht.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 6, 5, 'Darum habe ich dreingeschlagen durch die Propheten, habe sie auf Grund der Drohworte meines Mundes erschlagen; und mein Strafgericht ist sichtbar geworden wie das Licht.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 6, 6, 'Denn an Liebe habe ich Wohlgefallen, aber nicht an Schlachtopfern, und an Gotteserkenntnis mehr als an Brandopfern.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 6, 7, '»Sie aber haben in Adam den Bund gebrochen, sind dort treulos von mir abgefallen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 6, 8, 'Gilead ist eine Stadt von Verbrechern, voll von Blutspuren;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 6, 9, 'und wie Straßenräuber auflauern, so mordet die Genossenschaft der Priester auf der Straße nach Sichem; ja, Schändliches haben sie verübt!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 6, 10, 'Im Hause Israel habe ich Grauenhaftes gesehen: dort hat Ephraim sich dem Götzendienst ergeben und Israel sich verunreinigt.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 6, 11, 'Auch dir, Juda, ist eine Ernte bereitet, wenn ich das Geschick meines Volkes wende!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 7, 1, '»Sooft ich Israel heilen will, treten die Verschuldung Ephraims und die Bosheit Samarias klar zutage; denn sie verüben Trug, brechen als Diebe (in die Häuser) ein, plündern draußen als Räuberbanden.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 7, 2, 'Sie sagen sich nicht in ihrem Herzen, daß ich all ihrer Bosheit eingedenk bin; nunmehr stehen ihre Missetaten rings um sie her und sind vor meinen Augen offenbar.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 7, 3, 'Mit ihrer Bosheit erfreuen sie den König und mit ihrer Falschheit die Fürsten.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 7, 4, 'Sie sind allesamt Ehebrecher, gleichen einem geheizten Backofen, den der Bäcker nur vom Anmengen des Teigs bis zu seiner Gärung zu schüren aufhört.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 7, 5, 'Am Geburtstag unsers Königs machen die Fürsten ihn krank mit der Glut des Weins; er wechselt Händedruck mit den Spöttern.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 7, 6, 'Denn es brennt wie ein Ofen ihr Herz in ihrer Arglist; die ganze Nacht hindurch schläft ihr Zorn, am Morgen aber brennt er wie loderndes Feuer.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 7, 7, 'Sie glühen allesamt wie ein Backofen und verzehren ihre Richter. Alle ihre Könige sind gefallen, ohne daß einer von ihnen mich angerufen hätte.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 7, 8, '»Ephraim tritt in Verkehr mit den Völkern; Ephraim ist wie ein Brotkuchen geworden, den man nicht umgewandt hat.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 7, 9, 'Ausländer haben seine Kraft verzehrt, ohne daß er es merkt; schon ist graues Haar auf sein Haupt gesprengt, ohne daß er es merkt.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 7, 10, 'Wiewohl aber der Stolz Israels offen Zeugnis gegen sie ablegt, sind sie doch nicht zum HERRN, ihrem Gott, umgekehrt und haben ihn trotz alledem nicht aufgesucht;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 7, 11, 'nein, Ephraim ist einer einfältigen Taube gleich geworden, ist ohne Verstand: Ägypten rufen sie an und laufen nach Assyrien!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 7, 12, 'Sobald sie hinlaufen, breite ich mein Fangnetz über sie aus, hole sie wie Vögel des Himmels herunter, züchtige sie, wie es ihrer Gemeinde angekündigt worden ist.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 7, 13, 'Wehe ihnen, daß sie von mir gewichen sind! Verderben über sie, daß sie treulos von mir abgefallen sind! Und ich sollte sie erlösen, da sie doch Lügen gegen mich reden');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 7, 14, 'und nicht von Herzen zu mir schreien, wenn sie auf ihren Lagern heulen? Um Getreide und Most ritzen sie sich blutig und verlassen mich treulos,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 7, 15, 'obwohl doch ich ihre Arme geübt und stark gemacht habe; aber gegen mich sind sie feindlich gesinnt.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 7, 16, 'Sie wenden sich zum Baal hin, sie sind wie ein Bogen mit schlaffer Sehne geworden. Ihre Fürsten sollen durchs Schwert fallen wegen des Trotzes ihrer Zunge: das wird Hohnlachen über sie hervorrufen im Lande Ägypten!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 8, 1, '»(Setze) die Posaune an den Mund! Ein dem Adler gleicher Feind stürzt sich auf das Haus des HERRN zur Strafe dafür, daß sie meinen Bund übertreten und gegen mein Gesetz sich aufgelehnt haben.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 8, 2, 'Sie werden mir nun laut zurufen: ›Mein Gott, wir kennen dich ja, wir Israeliten!‹');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 8, 3, 'Israel hat das Heil zurückgestoßen (oder verworfen) – der Feind soll es dafür verfolgen!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 8, 4, 'Sie haben Könige eingesetzt, aber ohne mein Geheiß, haben Fürsten bestellt, doch ohne daß ich darum wußte. Von ihrem Silber und Gold haben sie sich Götzenbilder gemacht, nur damit sie zerschlagen werden.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 8, 5, 'Verhaßt ist mir dein Stierdienst, Samaria: mein Zorn ist gegen sie entbrannt! Wie lange sollen sie sich noch der Straflosigkeit erfreuen?');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 8, 6, 'Denn aus Israel stammt dieses (Stierbild); ein Werkmeister hat es angefertigt; aber es ist kein Gott, sondern zu Splittern soll er zerschlagen werden, der Stier von Samaria!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 8, 7, 'Denn Wind säen sie, und Sturm ernten sie, eine Saat, die keine Halme treibt und kein Brotkorn gibt; sollte sich auch Brotkorn geben, so würden doch Fremde es verschlingen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 8, 8, 'Verschlungen ist Israel, vereinsamt ist Ephraim; schon stehen sie unter den Völkern da wie ein Gefäß, nach dem niemand Verlangen trägt.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 8, 9, 'Denn sie sind nach Assyrien gezogen – ein Wildesel, der einsam für sich läuft, ist Ephraim –: Liebesgeschenke haben sie dargebracht.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 8, 10, 'Mögen sie solche auch darbringen unter den Völkern: nunmehr will ich sie ins Gedränge bringen, und sie sollen bald aufhören, dem Könige unter den Fürsten Tribut darzubringen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 8, 11, 'Denn zahlreiche Altäre hat Ephraim sich zum Sündigen gebaut, und zur Versündigung sind ihm die Altäre auch geworden.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 8, 12, 'Mag ich ihm auch meine Weisungen tausendmal vorschreiben – sie werden von ihm als etwas Unbekanntes angesehen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 8, 13, 'Schlachtopfer lieben sie, so schlachten sie; Fleisch lieben sie, so essen sie es: der HERR hat kein Wohlgefallen an ihnen. Nunmehr wird er ihrer Schuld gedenken und sie für ihre Sünden strafen: nach Ägypten müssen sie zurückkehren!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 8, 14, 'Weil Israel den, der es geschaffen hat, vergessen und sich Paläste gebaut, und weil Juda feste Städte in großer Zahl angelegt hat, will ich Feuer gegen seine Städte senden: das soll seine Prachtbauten verzehren!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 9, 1, 'Freue dich nicht, Israel, (frohlocke) nicht wie die Heidenvölker, daß du von deinem Gott ehebrecherisch abgefallen bist und gern Buhlerlohn auf allen Getreidetennen angenommen hast!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 9, 2, 'denn Tenne und Kelter werden sie nicht nähren, und der Most wird ihre Hoffnung täuschen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 9, 3, 'Sie sollen im Lande des HERRN nicht wohnen bleiben, sondern Ephraim muß nach Ägypten zurückkehren, und in Assyrien werden sie unreine Speisen genießen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 9, 4, 'Dann werden sie dem HERRN keine Weinspenden mehr ausgießen, und ihre Schlachtopfer werden ihm nicht mehr wohlgefällig sein; nein, wie Trauerbrot wird ihre Speise sein: alle, die davon essen, verunreinigen sich dadurch; denn ihre Speise dient nur der Stillung ihres Hungers, ins Haus des HERRN gelangt sie nicht.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 9, 5, 'Was wollt ihr dann beginnen an Feiertagen und am Tage des Festes des HERRN?');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 9, 6, 'Denn ach! Sie müssen nach Assyrien wandern, Ägypten wird sie einheimsen und Moph ihnen die Grabstätte bauen; ihre Kostbarkeiten an Silber werden die Disteln in Besitz nehmen, und Dorngesträuch wird in ihren Zelten (wachsen).');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 9, 7, 'Es kommen die Tage der Heimsuchung, es kommen die Tage der Vergeltung: Israel wird erkennen, ob der Prophet ein Narr, der gottbegeisterte Mann wahnsinnig gewesen ist –, und zwar wegen der Menge deiner Verschuldungen und der Größe deiner Feindseligkeit! –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 9, 8, 'Ephraim liegt auf der Lauer gegenüber dem Propheten neben meinem Gott: Schlingen des Vogelstellers auf allen seinen Wegen, Anfeindung (sogar) im Hause seines Gottes!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 9, 9, 'In tiefe Verderbnis versunken, treiben sie es wie einstmals in Gibea: er wird ihrer Schuld gedenken, wird ihre Sünden strafen!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 9, 10, '»Wie Trauben in der Wüste, so fand ich Israel, wie eine Frühfrucht am Feigenbaum in seinem ersten Triebe sah ich eure Väter an; als sie aber nach Baal-Peor kamen, gaben sie sich dem Schandgott hin und wurden so greuelhaft wie ihr Geliebter.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 9, 11, 'Ephraims Volksmenge wird Vögeln gleich davonfliegen: keine Geburt mehr, keine Schwangerschaft, keine Empfängnis!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 9, 12, 'Ja, wenn sie auch ihre Kinder großziehen sollten, will ich sie doch kinderlos machen, so daß keine Menschen mehr bleiben; ja wehe auch ihnen selbst, wenn ich mich von ihnen lossage!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 9, 13, 'Ephraim, wie ich es erschaut habe, glich einer jungen Palme, auf der Flur gepflanzt; aber Ephraim muß seine Söhne dem Würger ausliefern.« –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 9, 14, 'Gib ihnen, HERR – was sollst du ihnen geben? Gib ihnen einen unfruchtbaren Mutterleib und welke Brüste! –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 9, 15, '»Alle ihre Bosheit ist in Gilgal zutage getreten: ja, dort habe ich sie hassen gelernt. Wegen der Bosheit ihres ganzen Tuns will ich sie aus meinem Hause vertreiben, will ihnen keine Liebe mehr erweisen: alle ihre Führer sind Abtrünnige!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 9, 16, 'Wurmstichig ist Ephraim, seine Wurzel verdorrt; sie werden keine Frucht mehr bringen! Selbst wenn sie Kinder erzeugen sollten, würde ich doch die Lieblinge ihres Leibes sterben lassen.« –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 9, 17, 'Mein Gott verwirft sie, weil sie ihm nicht gehorcht haben; so müssen sie denn unstet unter den Völkern umherirren.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 10, 1, 'Ein üppig rankender Weinstock war Israel, (ein Weinstock,) der auch Früchte ansetzte; aber wie seine Früchte sich mehrten, so mehrten sich bei ihm auch die Altäre; je reicher sein Land trug, desto schönere Malsteine fertigten sie an.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 10, 2, 'Untreu war ihr Herz: jetzt sollen sie es büßen! Ihre Altäre wird er zertrümmern, ihre Malsteine zerschlagen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 10, 3, 'Sie sagen jetzt ja bereits: »Wir haben keinen König mehr! Denn den HERRN haben wir nicht gefürchtet, und der König – was kann der für uns tun?«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 10, 4, 'Sie reden leere Worte, schwören trügliche Eide, schließen Bündnisse: so sproßt denn das Gericht auf wie Giftkraut in den Ackerfurchen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 10, 5, 'Um ihren Stier von Beth-Awen sind die Bewohner Samarias in Angst; ja, sein Volk trauert um ihn, und seine Pfaffen zittern für ihn, für seine Herrlichkeit, weil diese von ihm weggewandert ist.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 10, 6, 'Auch ihn selbst wird man nach Assyrien schleppen als Geschenk für den Großkönig; Schmach wird Ephraim sich holen und Israel zuschanden werden ob seiner Staatskunst.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 10, 7, 'Vernichtet wird Samaria: sein König gleicht dem Gischt auf weiter Wasserflut;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 10, 8, 'und verwüstet werden die Höhen von Awen, die Stätten der Versündigung Israels: Dornen und Disteln werden auf den Altären dort wuchern; da wird man denn den Bergen zurufen: »Bedeckt uns!« und den Hügeln: »Fallet über uns!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 10, 9, '»Seit den Tagen von Gibea hast du gesündigt, Israel; dort sind sie auch stehengeblieben; sollte sie zu Gibea der Krieg gegen die (Rotte der) Frevler nicht erreichen?');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 10, 10, 'Nach Herzenslust will ich sie züchtigen, und Völker werden gegen sie versammelt werden, wenn ich sie für ihre zwiefache Verschuldung büßen lasse.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 10, 11, 'Ephraim war ein angelerntes Rind, willig zum Dreschen; so habe denn ich selbst ihm das Joch auf den schönen Nacken gelegt und habe Ephraim eingespannt: Juda sollte pflügen, Jakob die Egge für sich ziehen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 10, 12, 'Macht Gerechtigkeit zu eurer Aussaat und erntet nach Maßgabe der Liebe! Brecht euch einen Neubruch (der Erkenntnis), da es noch Zeit ist, den HERRN zu suchen, damit er endlich kommt und Gerechtigkeit über euch regnen läßt!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 10, 13, 'Ihr aber habt Gottlosigkeit eingepflügt, Unheil geerntet, habt die Frucht der Treulosigkeit essen müssen. Weil du dein Vertrauen auf deine Kriegswagen, auf die Menge deiner Krieger gesetzt hast,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 10, 14, 'darum wird sich Kriegslärm in deinen Städten erheben, und alle deine festen Plätze werden zerstört werden, so wie Salman (jüngst die Stadt) Beth-Arbel am Tage der Schlacht zerstört hat: die Mutter wurde samt den Kindern zerschmettert.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 10, 15, 'Solches Geschick bringt Bethel über euch infolge eurer grenzenlosen Bosheit; wie das Morgenrot (verschwindet), so wird Israels König dahingerafft.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 11, 1, '»Als Israel jung war, gewann ich es lieb, und aus Ägypten habe ich meinen Sohn gerufen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 11, 2, 'Je öfter ich sie aber gerufen habe, desto weiter haben sie sich von mir entfernt, während sie den Baalen Schlachtopfer und den Schnitzbildern Weihrauch darbrachten.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 11, 3, 'Dennoch bin ich es gewesen, der Ephraim am Gängelbande geleitet und es auf die Arme genommen hat; aber sie haben nicht erkannt, daß ich ihr Arzt bin.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 11, 4, 'An Banden, wie sie für Menschen passen, habe ich sie an mich gezogen, an Seilen der Liebe, und mich so gegen sie verhalten, daß ich das Joch an ihren Kinnbacken hochhob und mich zu ihnen neigte, um ihnen Nahrung zu reichen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 11, 5, 'Jetzt müssen sie nach Ägypten zurückkehren, oder der Assyrer mag ihr König werden, denn sie haben sich geweigert, (zu mir) umzukehren.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 11, 6, 'So soll denn das Schwert in ihren Städten umgehen und ihre Großen vernichten und fressen um ihrer Ratschläge willen;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 11, 7, 'denn mein Volk hält den Hang zum Abfall von mir fest, und ruft man ihm ein Aufwärts zu, so richtet sich doch keiner von ihnen empor.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 11, 8, 'Wie könnte ich dich preisgeben, Ephraim, dich fahren lassen, Israel! Wie könnte ich mit dir verfahren wie einst mit Adama; ein Zeboim aus dir machen! Mein Herz kehrt sich in mir um, mein ganzes Mitleid gerät in Wallung!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 11, 9, 'Ich will meines Zornes Glut nicht auswirken, will Ephraim nicht nochmals vernichten; denn Gott bin ich und nicht ein Mensch: als der Heilige wohne ich in deiner Mitte, und ich will nicht in Zornesglut (zu dir) kommen.« –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 11, 10, 'Sie werden dem HERRN nachfolgen, der wird wie ein Löwe brüllen; ja, er wird brüllen, und die Kinder (Israel) werden vom Meer her zitternd herbeieilen;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 11, 11, 'wie Vögel werden sie aus Ägypten zitternd herbeieilen und wie Tauben aus dem Lande Assyrien. »Dann will ich sie wieder in ihren Wohnsitzen heimisch machen!« – so lautet der Ausspruch des HERRN.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 12, 1, '»Mit Treulosigkeit hat Ephraim mich umringt, mit Trug das Haus Israel«; auch Juda ist immer noch wankelmütig gegen Gott und gegen den Hochheiligen, der treu ist.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 12, 2, 'Ephraim hat seine Freude an windigem Treiben und jagt dem Ostwind nach: täglich wird es verlogener und eigenmächtiger; mit Assyrien schließen sie ein Bündnis, und nach Ägypten wird Öl gebracht.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 12, 3, 'Auch gegen Juda hat der HERR Anklage zu erheben, und er muß Jakob zur Rechenschaft ziehen wegen seines Verhaltens, nach seinem ganzen Tun ihm vergelten.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 12, 4, 'Schon im Mutterschoß hat er seines Bruders Ferse gefaßt und in seiner Manneskraft mit Gott gerungen;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 12, 5, 'er hat mit dem Engel gerungen und die Oberhand behalten, er hat geweint und ihn um Erbarmen angefleht; in Bethel hatte er ihn gefunden und daselbst mit ihm geredet –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 12, 6, 'nämlich der HERR, der Gott der Heerscharen, dessen Name ›der HERR‹ ist –:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 12, 7, '»Du wirst in deine Zelte heimkehren! Halte an Liebe und Recht fest und hoffe immerdar auf deinen Gott!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 12, 8, 'Als (echter) Kanaanäer führt er eine falsche Waage in der Hand: er liebt es zu betrügen;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 12, 9, 'aber Ephraim sagt: »Ich bin ja doch reich geworden, habe mir ein Vermögen erworben! Bei allem, was ich besitze, wird man mir kein Unrecht nachweisen, das Sünde wäre!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 12, 10, '»Ich aber, der HERR, dein Gott vom Lande Ägypten her, will dich noch einmal in Zelten wohnen lassen wie in den Tagen der Festfeier.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 12, 11, 'Ich habe doch zu den Propheten geredet, und ich bin es, der sich oftmals durch zahlreiche Gesichte kundgegeben und durch die Propheten in Gleichnissen geredet hat.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 12, 12, 'Wenn sie in Gilead nichtswürdig gewesen sind, so sollen sie auch vernichtet werden; haben sie in Gilgal Stiere geopfert, so sollen auch ihre Altäre (verwüstet und) wie Steinhaufen an den Rainen der Äcker werden!« –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 12, 13, 'Als Jakob einst ins Gefilde der Aramäer geflohen war, diente Israel als Knecht um ein Weib und hütete die Herden um ein (zweites) Weib;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 12, 14, 'und durch einen Propheten hat der HERR die Israeliten aus Ägypten heraufgeführt, und durch einen (anderen) Propheten ist es behütet worden.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 12, 15, 'Doch Ephraim hat ihm bittere Kränkung bereitet; so wird denn sein Herr seine Blutschuld an ihm haften lassen und die ihm zugefügte Schmach ihm vergelten!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 13, 1, 'Sooft Ephraim (nur) redete, herrschte Schrecken: hoch stand es in Israel da; als es sich aber durch den Baalsdienst versündigte, starb es hin.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 13, 2, 'Und jetzt sündigen sie immer aufs neue: sie fertigen sich Gußbilder aus ihrem Silber an, Götzen nach ihrem Geschmack, allesamt Machwerke von Handwerkern. »Ihnen«, sagen sie, »bringet Opfer dar!« Menschen sollen Stiere küssen!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 13, 3, '»Darum sollen sie dem Morgengewölk gleich werden und dem Tau, der gar bald verschwindet, wie Spreu, die von der Tenne verweht wird, und wie Rauch, der durch die Gitteröffnung abzieht.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 13, 4, 'Ich aber bin der HERR dein Gott vom Lande Ägypten her; einen Gott außer mir kennst du nicht, und einen Helfer außer mir gibt es nicht.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 13, 5, '»Ich habe mich deiner angenommen in der Wüste, (dich geweidet) im Lande der sengenden Gluten.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 13, 6, 'Als sie gute Weide hatten, wurden sie satt, und als sie satt geworden waren, überhob sich ihr Sinn; darum haben sie mich vergessen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 13, 7, 'Da bin ich ihnen denn wie ein Löwe geworden, liege wie ein Panther auf der Lauer am Wege;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 13, 8, 'ich falle sie an wie eine Bärin, der die Jungen geraubt sind, und zerreiße ihnen den Verschluß ihres Herzens; ich fresse sie dort wie eine Löwin; die wilden Tiere sollen sie zerfleischen!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 13, 9, 'Das ist dein Verderben gewesen, Israel, daß du von mir, deinem Helfer, nichts wissen willst.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 13, 10, 'Wo ist denn nun dein König, daß er dir in allen deinen Städten helfe? Und wo sind deine Richter (, daß sie dir Recht schaffen)? Du hast ja doch von ihnen gesagt: ›Gib mir einen König und Fürsten!‹');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 13, 11, 'Ich gebe dir einen König in meinem Zorn und nehme ihn wieder weg in meinem Grimm!« –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 13, 12, '»Wohlverwahrt ist Ephraims Schuld, wohlgeborgen seine Sünde.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 13, 13, 'Geburtswehen kommen ihn an, aber er ist ein unverständiges Kind; denn zur rechten Zeit tritt er nicht zum Durchbruch in den Muttermund ein.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 13, 14, 'Aus der Gewalt des Totenreiches sollte ich sie befreien, vom Tode sie loskaufen? Nein, wo sind deine Seuchen, o Tod? Wo ist deine Pest, o Unterwelt? Mitleid ist meinen Augen unbekannt!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 13, 15, 'Denn mag Ephraim auch wie Riedgras zwischen Wassern üppig sprossen – der Ostwind wird kommen, ein Sturm des HERRN aus der Steppe hereinbrechen; da wird sein Born versiegen und sein Quellgrund vertrocknen: der wird die Schatzkammer aller kostbaren Kleinodien berauben.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 14, 1, 'Samaria soll für seine Auflehnung gegen seinen Gott büßen: durch das Schwert sollen sie fallen, ihre jungen Kinder sollen zerschmettert und ihre schwangeren Weiber aufgeschlitzt werden!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 14, 2, 'Kehre um, Israel, zum HERRN, deinem Gott! Denn durch eigene Schuld bist du zu Fall gekommen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 14, 3, 'Nehmet Worte (der Reue) mit euch und kehret um zum HERRN! Sagt zu ihm: »Vergib uns alle Schuld und laß es dir gnädig gefallen, daß wir statt der Farren dir die Frucht unserer Lippen als Opfer darbringen!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 14, 4, 'Assyrien soll nicht mehr unser Helfer sein; auf Rossen wollen wir nicht mehr reiten und nicht mehr ›unser Gott!‹ sagen zum Machwerk unserer Hände; denn bei dir findet der Verwaiste Erbarmen.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 14, 5, '»Ich will ihren Abfall heilen, ihnen bereitwillig Liebe erweisen; denn mein Zorn hat sich von ihnen abgewandt.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 14, 6, 'Ich will für Israel werden wie der Tau: blühen soll es wie eine Lilie und Wurzeln schlagen wie die Zedern (des Libanons);');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 14, 7, 'seine Schößlinge sollen sich entfalten, seine Pracht soll wie die des Ölbaums werden und sein Duft dem des Libanons gleichen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 14, 8, 'Wiederum sollen die in seinem Schatten Wohnenden sprießen wie das Getreide und blühen wie der Weinstock, dessen Ruhm dem Wein des Libanons gleichkommt.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 14, 9, 'Was hat Ephraim in Zukunft noch mit den Götzen zu schaffen? Ich allein erhöre ihn und behalte ihn im Auge; ich bin (für ihn) wie eine immergrüne Zypresse; von mir her wird Frucht an dir zu finden sein.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 14, 10, 'Wer ist weise, daß er dies einsieht, wer einsichtsvoll, daß er es beherzigt? »Gerade sind die Wege des HERRN, und die Gerechten wandeln (sicher) auf ihnen; die Gottlosen aber kommen auf ihnen zu Fall.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 1, 1, '(Dies ist) das Wort des HERRN, das an Joel, den Sohn Pethuels, ergangen ist:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 1, 2, 'Hört dies, ihr Alten, und merkt auf, ihr Bewohner des Landes allesamt! Ist jemals etwas derartiges bei euren Lebzeiten oder in den Tagen eurer Väter vorgekommen?');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 1, 3, 'Davon sollt ihr euren Kindern erzählen und eure Kinder ihren Kindern und deren Kinder dem folgenden Geschlecht!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 1, 4, 'Was der Nager übriggelassen hatte, das fraß die Heuschrecke auf; und was die Heuschrecke übriggelassen, das verzehrte der Fresser; und was der Fresser übriggelassen, das verzehrte der Abschäler.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 1, 5, 'Wacht auf, ihr Trunkenen, und weint! Wehklagt, ihr Weinzecher alle, um den Most, weil er euch vom Munde weg entrissen ist!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 1, 6, 'Denn ein Volk ist über mein Land heraufgezogen, ein gewaltiges und zahlloses; seine Zähne sind Löwenzähne, und ein Gebiß hat es wie eine Löwin.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 1, 7, 'Es hat meine Weinstöcke verwüstet und meine Feigenbäume zerknickt, hat die Rinde rundum abgeschält und auf den Boden niedergeworfen, so daß ihre Schosse nackt starren.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 1, 8, 'Wehklage, (o Land,) wie eine Jungfrau, die das Trauergewand angelegt hat um den Verlobten ihrer Jugend!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 1, 9, 'Speisopfer und Trankspende bleiben dem Hause des HERRN fern; es trauern die Priester, die Diener des HERRN.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 1, 10, 'Verwüstet ist das Feld, es trauert die Flur; denn vernichtet ist das Getreide, vertrocknet der Most, verwelkt das Öl.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 1, 11, 'Bestürzt stehen die Ackerleute da – es jammern die Weingärtner – um den Weizen und die Gerste; denn der Ertrag des Feldes ist dahin.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 1, 12, 'Der Weinstock ist verdorrt und der Feigenbaum verwelkt; Granate, auch Dattelpalme und Apfelbaum, alle Bäume des Feldes sind dürr: ja, zuschanden geworden ist die Freude, den Menschenkindern entschwunden!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 1, 13, 'Legt Trauerkleidung an und wehklagt, ihr Priester! Jammert, ihr Diener des Altars! Kommt her, verbringt (auch) die Nacht im Bußgewand, ihr Diener meines Gottes! Denn Speisopfer und Trankspende bleiben dem Hause eures Gottes versagt.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 1, 14, 'Ordnet ein heiliges Fasten an, ruft einen allgemeinen Bettag aus! Versammelt die Ältesten, alle Landesbewohner, beim Hause des HERRN, eures Gottes, und schreiet zum HERRN:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 1, 15, '»Wehe über den Tag!« Denn nahe steht der Tag des HERRN bevor, und er kommt als eine Vergewaltigung vom Allgewaltigen her.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 1, 16, 'Ist nicht die Nahrung vor unsern Augen weggerafft, Freude und Jubel aus dem Hause unsers Gottes geschwunden?');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 1, 17, 'Verschrumpft liegen die Samenkörner unter ihren Schollen, leer stehen die Speicher, zerfallen die Scheunen: das Getreide ist ja dahin!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 1, 18, 'Wie kläglich brüllt das Vieh! In voller Unruhe sind die Rinderherden, weil sie nirgends Weide haben; auch die Kleinviehherden leiden schwer.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 1, 19, 'Zu dir, HERR, rufe ich; denn Gluthitze hat die Auen der Steppe verzehrt und Lohe allen Baumwuchs des Gefildes versengt.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 1, 20, 'Auch die wilden Tiere draußen schreien lechzend zu dir; denn die Wasserbäche sind ausgetrocknet, und Gluthitze hat die Auen der Steppe verzehrt!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 2, 1, 'Stoßt in die Posaune auf dem Zion und blast Lärm auf meinem heiligen Berge, daß alle Bewohner des Landes erzittern! Denn der Tag des HERRN kommt heran, ja, er steht nahe bevor,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 2, 2, 'ein Tag der Finsternis und des Dunkels, ein Tag des Gewölks und der Wolkennacht! Wie Morgengrauen liegt über die Berge ausgebreitet ein großes, starkes Kriegsvolk, wie seinesgleichen von Ewigkeit her nicht gewesen ist und in Zukunft keines wieder sein wird bis in die Jahre der fernsten Geschlechter.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 2, 3, 'Fressendes Feuer geht vor ihm her, und hinter ihm drein lodert Lohe; wie der Garten Eden liegt das Land vor ihm, und hinter ihm eine öde Wüste; und dabei ist ein Entrinnen vor ihm nicht möglich.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 2, 4, 'Sie sehen ganz so aus wie Rosse, und wie Rennpferde, so stürmen sie vorwärts.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 2, 5, 'Rasselnd wie Kriegswagen hüpfen sie über die Höhen der Berge, knisternd wie die Feuerflamme, welche Stoppeln verzehrt, wie ein gewaltiges, kampfgerüstetes Heer.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 2, 6, 'Vor ihm erzittern die Völker, alle Gesichter entfärben sich.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 2, 7, 'Wie Kriegshelden stürmen sie daher, wie geübte Streiter ersteigen sie Mauern; jeder zieht seines Weges geradeaus, ohne sich aus der Richtung bringen zu lassen;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 2, 8, 'keiner stößt den andern, ein jeder verfolgt seine Bahn für sich; auch durch Pfeilhagel hindurch dringen sie vor, ohne sich aufhalten zu lassen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 2, 9, 'Sie stürmen gegen die Stadt an, rennen auf die Mauer, klettern an den Häusern hinauf; durch die Fenster dringen sie ein wie der Dieb.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 2, 10, 'Vor ihnen her bebt die Erde, wankt der Himmel; Sonne und Mond verfinstern sich, und die Sterne verlieren ihren Glanz.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 2, 11, 'Und der HERR läßt vor seiner Kriegerschar her seine Stimme erschallen; denn gar gewaltig ist sein Kriegsvolk, zahlreich der Vollstrecker seines Befehls. Ja, groß ist der Tag des HERRN und gar furchtbar: wer mag ihn bestehen?');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 2, 12, '»Doch auch jetzt noch« – so lautet der Ausspruch des HERRN – »kehret um zu mir mit eurem ganzen Herzen, mit Fasten, Weinen und Klagen!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 2, 13, 'So zerreißt denn eure Herzen statt eurer Kleider und kehret zurück zum HERRN, eurem Gott! Denn er ist gnädig und barmherzig, langsam zum Zorn und reich an Güte, und er läßt sich das Unheil leid sein:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 2, 14, 'vielleicht läßt er es sich auch jetzt leid sein und läßt hinter sich noch einen Segen zurück; nämlich Speisopfer und Trankspende für den HERRN, euren Gott.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 2, 15, 'Stoßt in die Posaune auf dem Zion, ordnet ein heiliges Fasten an, ruft einen allgemeinen Bettag aus!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 2, 16, 'Versammelt das Volk, heiligt die Gemeinde, ruft die Greise herbei, laßt die Kinder und die Säuglinge zusammenkommen! Der Neuvermählte trete aus seiner Kammer hervor und das junge Weib aus ihrem Gemach!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 2, 17, 'Zwischen der Vorhalle und dem Altar sollen die Priester, die Diener des HERRN, weinen und so beten: »Verschone, HERR, dein Volk und gib dein Erbe nicht der Schande preis, daß sie den Heiden zum Spott dienen! Warum soll man unter den Heidenvölkern sagen: ›Wo ist nun ihr Gott?‹«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 2, 18, 'Da geriet der HERR in Eifer für sein Land und hatte Erbarmen mit seinem Volk;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 2, 19, 'so antwortete denn der HERR und sprach zu seinem Volk: »Fürwahr, ich lasse euch das (erforderliche) Getreide, den Most und das Öl zukommen, daß ihr satt davon werden sollt; auch will ich euch fernerhin nicht dem Hohn unter den Heiden preisgeben.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 2, 20, 'Den nordischen Feind aber will ich weit von euch entfernen und ihn in ein dürres und wüstes Land vertreiben, nämlich seinen Vortrab in das Ostmeer und seine Nachhut in das Westmeer, so daß der Gestank von ihm aufsteigen, daß der Modergeruch von ihm sich erheben soll, weil er gewaltsam aufgetreten ist.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 2, 21, 'Fürchte dich nicht, Ackerland, nein, juble und freue dich! Denn der HERR vollbringt etwas Großes.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 2, 22, 'Fürchtet euch nicht, ihr Tiere des Feldes! Denn die Auen der Steppe sollen aufs neue grünen, die Bäume wieder ihre Früchte tragen, der Feigenbaum und Weinstock den vollen Ertrag geben!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 2, 23, 'Auch ihr, Kinder Zions, jubelt und freut euch über den HERRN, euren Gott! Denn er gibt euch den Herbstregen nach rechtem Maß und läßt euch Regen niederströmen, Frühregen und Spätregen, wie ehemals.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 2, 24, 'Da werden die Tennen sich mit Korn füllen und die Kelterkufen von Most und Öl überfließen;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 2, 25, 'und ich will euch die Jahre ersetzen, deren Ertrag die Heuschrecken, der Nager, der Fresser und der Verwüster, verzehrt haben, mein großes Kriegsheer, das ich gegen euch gesandt hatte.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 2, 26, 'Da sollt ihr vollauf zu essen haben und satt werden und den Namen des HERRN, eures Gottes, preisen, der sich wunderbar an euch erwiesen hat; und mein Volk soll in Zukunft nimmermehr zuschanden werden;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 2, 27, 'und ihr sollt erkennen, daß ich in Israels Mitte bin und daß ich, der HERR, euer Gott bin und keiner sonst; und nimmer soll mein Volk in Zukunft zuschanden werden!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 3, 1, '»Und danach wird es geschehen, daß ich meinen Geist über alles Fleisch ausgieße, so daß eure Söhne und eure Töchter prophetisch reden, eure Greise Offenbarungen in Träumen empfangen, eure jungen Leute Gesichte schauen;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 3, 2, 'ja auch über die Knechte und Mägde will ich in jenen Tagen meinen Geist ausgießen;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 3, 3, 'und ich will Wunderzeichen am Himmel und auf der Erde erscheinen lassen; nämlich Blut, Feuer und Rauchsäulen:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 3, 4, 'die Sonne wird sich in Finsternis verwandeln und der Mond in Blut, ehe der Tag des HERRN kommt, der große und furchtbare.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 3, 5, 'Ein jeder aber, der den Namen des HERRN anruft, wird gerettet; denn auf dem Berge Zion und in Jerusalem wird Rettung sein, wie der HERR es verheißen hat; und zu den Entronnenen wird jeder gehören, den der HERR beruft.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 4, 1, '»Denn wisset wohl: in jenen Tagen und zu jener Zeit, wo ich das Geschick Judas und Jerusalems wenden werde,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 4, 2, 'da will ich alle Heidenvölker versammeln und sie in das Tal Josaphat hinabführen, um dort mit ihnen ins Gericht zu gehen wegen Israels, meines Volkes und meines Eigentums, weil sie es unter die Heiden zerstreut und mein Land aufgeteilt haben;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 4, 3, 'und über mein Volk haben sie das Los geworfen und Knaben als Preis für Lustdirnen hingegeben und die Mädchen um Wein verkauft, den sie vertrunken haben.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 4, 4, 'Und was habt auch ihr mit mir zu schaffen, Tyrus und Sidon und alle ihr Bezirke des Philisterlandes? Wollt ihr mir etwas vergelten, was ich euch angetan habe, oder wollt ihr selbst mir etwas antun? Schnell und unverzüglich will ich euer Tun auf euer Haupt zurückfallen lassen!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 4, 5, 'Ihr habt ja doch mein Silber und mein Gold geraubt und meine wertvollsten Kleinodien in eure Paläste gebracht;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 4, 6, 'und die Kinder Judas und die Kinder Jerusalems habt ihr an die Griechen verkauft, um sie weit von ihrer Heimat zu entfernen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 4, 7, 'Wisset wohl: ich will sie wieder aufbrechen lassen von dem Orte, wohin ihr sie verkauft habt, und will euer Tun auf euer Haupt zurückfallen lassen;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 4, 8, 'und ich will eure Söhne und Töchter an die Kinder Judas verkaufen, die werden sie dann wieder an die Sabäer verhandeln, an ein fernwohnendes Volk; denn der HERR hat’s geboten.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 4, 9, '»Macht dieses unter den Heidenvölkern bekannt: ›Rüstet euch zum heiligen Kriege! Bietet die geübten Streiter auf, laßt alle Kriegsleute aufmarschieren und anrücken!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 4, 10, 'Schmiedet eure Pflugscharen zu Schwertern um und eure Winzermesser zu Lanzen (-spitzen)! Der Feigling sage: Ich bin ein Held!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 4, 11, 'Eilt und kommt herbei, alle ihr Heidenvölker ringsum, und scharet euch zusammen!‹« – Dorthin, HERR, laß deine Streiter hinabziehen! –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 4, 12, '»Die Völker sollen sich aufmachen und in das Tal Josaphat hinabziehen; denn dort will ich zu Gericht sitzen über alle Heidenvölker ringsum.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 4, 13, 'Legt die Sichel an, denn die Ernte ist reif! Kommt und stampft, denn die Kelter ist voll, ja, die Kufen fließen über, denn ihre Gottlosigkeit ist groß!« –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 4, 14, 'Scharen über Scharen treffen im Tal der Entscheidung ein, denn nahe ist der Tag des HERRN im Tal der Entscheidung.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 4, 15, 'Sonne und Mond verfinstern sich, und die Sterne verlieren ihren Glanz;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 4, 16, 'der HERR brüllt vom Zion her und läßt seine Stimme aus Jerusalem erschallen, so daß Himmel und Erde erbeben; aber für sein Volk ist der HERR eine Zuflucht und eine feste Burg für die Kinder Israel.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 4, 17, '»Da werdet ihr denn erkennen, daß ich, der HERR, euer Gott bin, der ich auf dem Zion wohne, meinem heiligen Berge; und Jerusalem wird dann heiliges Gebiet sein, welches Ausländer nie wieder durchziehen werden.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 4, 18, '»Und dann, an jenem Tage, wird es geschehen: da werden die Berge von Most triefen und die Hügel von Milch überfließen und alle Rinnsale Judas voll Wassers strömen; und ein Quell wird aus dem Hause des HERRN hervorbrechen und das Akaziental bewässern.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 4, 19, 'Ägypten wird zur Wüste werden und Edom zur öden Steppe wegen der Freveltat an den Kindern Judas, weil sie unschuldiges Blut in deren Lande vergossen haben.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 4, 20, 'Juda aber wird ewig bewohnt bleiben und Jerusalem von Geschlecht zu Geschlecht;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 4, 21, 'und ich werde ihr Blut rächen, das ich (bisher) nicht gerächt habe; und der HERR wird auf dem Zion wohnen.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 1, 1, '(Dies sind) die Worte, welche Amos, einer von den Herdenbesitzern von Thekoa, über Israel geschaut hat zur Zeit des judäischen Königs Ussia und zur Zeit des israelitischen Königs Jerobeam, des Sohnes des Joas, zwei Jahre vor dem Erdbeben.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 1, 2, 'Es lauteten aber seine Worte so: »Wenn der HERR vom Zion her brüllt und aus Jerusalem seine Stimme erschallen läßt, da trauern die Auen der Hirten, und der Gipfel des Karmels verdorrt.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 1, 3, 'So hat der HERR gesprochen: »Wegen der drei, ja vier Freveltaten von Damaskus mache ich es nicht rückgängig! Weil sie Gilead mit eisenschneidigen Dreschwalzen gedroschen haben,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 1, 4, 'will ich Feuer in das Haus Hasaels schleudern: das soll die Paläste Ben-Hadads verzehren.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 1, 5, 'Und ich will den Riegel von Damaskus zerbrechen und die Bewohner ausrotten aus Bikath-Awen und den Zepterträger aus Beth-Eden; und das Syrervolk soll nach Kir zurückwandern« – der HERR hat es ausgesprochen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 1, 6, 'So hat der HERR gesprochen: »Wegen der drei, ja vier Freveltaten von Gaza mache ich es nicht rückgängig! Weil sie Gefangene, ganze Ortschaften weggeschleppt haben, um sie als Sklaven an die Edomiter auszuliefern,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 1, 7, 'will ich Feuer an die Ringmauer von Gaza schleudern: das soll die Paläste der Stadt verzehren;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 1, 8, 'auch will ich die Bewohner aus Asdod ausrotten und den Zepterträger auch aus Askalon, und ich will meine Hand gegen Ekron wenden, daß auch der letzte Rest der Philister umkommen soll« – Gott der HERR hat es ausgesprochen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 1, 9, 'So hat der HERR gesprochen: »Wegen der drei, ja vier Freveltaten von Tyrus mache ich es nicht rückgängig! Weil sie Gefangene, ganze Ortschaften, an die Edomiter ausgeliefert haben, ohne des Bruderbundes zu gedenken,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 1, 10, 'will ich Feuer an die Ringmauer von Tyrus schleudern: das soll die Paläste der Stadt verzehren.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 1, 11, 'So hat der HERR gesprochen: »Wegen der drei, ja vier Freveltaten der Edomiter mache ich es nicht rückgängig! Weil sie ihr Brudervolk mit dem Schwerte verfolgt und ihr Mitgefühl erstickt haben, weil sie ihrem Zorn immerfort freien Lauf gelassen und an ihrem Ingrimm beständig festgehalten haben,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 1, 12, 'will ich Feuer gegen Theman schleudern: das soll die Paläste von Bozra verzehren.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 1, 13, 'So hat der HERR gesprochen: »Wegen der drei, ja vier Freveltaten der Ammoniter mache ich es nicht rückgängig! Weil sie die schwangeren Frauen in Gilead aufgeschlitzt haben, um ihr Gebiet zu erweitern,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 1, 14, 'will ich Feuer an die Ringmauer von Rabba anlegen: das soll die Paläste der Stadt verzehren unter Kriegsgeschrei am Tage der Schlacht, beim Sturm am Tage des Unwetters;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 1, 15, 'und ihr König soll in die Verbannung wandern, er mitsamt seinen Fürsten« – der HERR hat es ausgesprochen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 2, 1, 'So hat der HERR gesprochen: »Wegen der drei, ja vier Freveltaten der Moabiter mache ich es nicht rückgängig! Weil sie die Gebeine des Königs von Edom zu Kalk verbrannt haben,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 2, 2, 'will ich Feuer gegen die Moabiter schleudern: das soll die Paläste von Kerioth verzehren; die Moabiter aber sollen im Getümmel umkommen beim Kriegsgeschrei, beim Schall der Posaune;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 2, 3, 'und ich will den Richter aus ihrer Mitte ausrotten und alle ihre Fürsten zugleich mit ihm umbringen« – der HERR hat es ausgesprochen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 2, 4, 'So hat der HERR gesprochen: »Wegen der drei, ja vier Freveltaten Judas mache ich es nicht rückgängig! Weil sie das Gesetz des HERRN verworfen und seine Gebote nicht beobachtet haben und sich von ihren Lügengötzen haben irreführen lassen, denen schon ihre Väter nachgelaufen sind,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 2, 5, 'will ich Feuer gegen Juda schleudern: das soll die Paläste Jerusalems verzehren.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 2, 6, 'So hat der HERR gesprochen: »Wegen der drei, ja vier Freveltaten Israels mache ich es nicht rückgängig: weil sie den Unschuldigen für Geld und den Armen um eines Paares Schuhe willen verkaufen,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 2, 7, 'sie, die den Kopf der Armen in den Erdenstaub treten und die Niedrigen vom Wege drängen! Vater und Sohn gehen zu (derselben) Dirne, um meinen heiligen Namen zu entweihen;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 2, 8, 'auf Gewändern, die sie zum Pfand genommen haben, strecken sie sich aus neben jedem Altar und trinken den Wein, der von Strafgeldern herrührt, im Hause ihres Gottes!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 2, 9, 'Und ich habe doch einst die Amoriter vor ihnen her vernichtet, deren Wuchs den Zedern an Höhe gleichkam und die stark wie die Eichen waren, und ich habe ihre Früchte oben (im Wipfel) und ihre Wurzeln unten (im Boden) vernichtet.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 2, 10, 'Und ich bin es doch gewesen, der euch aus dem Lande Ägypten hergeführt und euch vierzig Jahre lang in der Wüste hat wandern lassen, damit ihr das Land der Amoriter in Besitz nähmet.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 2, 11, 'Und ich habe von euren Söhnen manche als Propheten und von euren Jünglingen manche als Nasiräer auftreten lassen: oder ist’s etwa nicht so, ihr Kinder Israel?« – so lautet der Ausspruch des HERRN.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 2, 12, '»Ihr aber habt den Nasiräern Wein zu trinken gegeben und den Propheten streng geboten: ›Ihr dürft nicht prophetisch reden!‹');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 2, 13, 'Darum will ich euch den Boden unter den Füßen schwanken machen, wie der Wagen schwankt, der mit Garben beladen ist.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 2, 14, 'Da wird dann dem Schnellfüßigen das Fliehen vergehen und dem Starken die Kraft versagen; der Kriegsheld wird sein Leben nicht retten können');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 2, 15, 'und der Bogenschütze nicht standhalten; der Schnellfüßige wird nicht entrinnen und der Reiter hoch zu Roß sein Leben nicht retten;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 2, 16, 'auch der Beherzteste unter den Kriegshelden wird, seiner Waffen beraubt, die Flucht ergreifen an jenem Tage!« – so lautet der Ausspruch des HERRN.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 3, 1, 'Vernehmt dieses Wort, das der HERR gegen euch, ihr Israeliten, ausgesprochen hat, gegen das ganze Geschlecht, das ich aus Ägyptenland hergeführt habe! Es lautet so:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 3, 2, '»Euch allein habe ich mir aus allen Geschlechtern des Erdbodens erwählt; darum will ich euch für alle eure Verschuldungen büßen lassen!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 3, 3, 'Wandern wohl zwei Menschen miteinander, ohne daß sie sich verabredet haben?');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 3, 4, 'Brüllt wohl der Löwe im Walde, ohne Beute zu haben? Läßt der Jungleu seine Stimme aus seiner Höhle erschallen, ohne daß er einen Fang getan hat?');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 3, 5, 'Gerät wohl ein Vogel in die Falle am Boden, ohne daß ihm eine Schlinge gelegt ist? Schnellt wohl ein Fangnetz vom Erdboden empor, ohne daß es etwas gefangen hat?');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 3, 6, 'Wird die Posaune in einer Stadt geblasen, ohne daß die Leute erschrecken? Tritt ein Unglück in einer Stadt ein, ohne daß Gott der HERR es verursacht hat?');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 3, 7, 'Nein, Gott der HERR tut nichts, ohne zuvor seinen Ratschluß seinen Knechten, den Propheten, geoffenbart zu haben.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 3, 8, 'Der Löwe hat gebrüllt: wer sollte sich nicht fürchten? Gott der HERR hat geredet: wer sollte nicht als Prophet reden?');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 3, 9, 'Ruft es aus über die Paläste von Assyrien hin und über die Paläste des Landes Ägypten hin und macht bekannt: »Versammelt euch auf dem Berge von Samaria und seht euch das wilde Treiben in seinem Innern an und die Bedrückungen in seiner Mitte!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 3, 10, '»Sie verstehen nicht zu tun, was recht ist« – so lautet der Ausspruch des HERRN –, »sie, die da Frevel und Gewalttaten aufspeichern in ihren Palästen.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 3, 11, 'Darum hat Gott der HERR so gesprochen: »Der Feind wird dein Land ringsum bedrängen und deine starke Mauer von dir hinabstürzen, und deine Paläste sollen geplündert werden!« –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 3, 12, 'So hat der HERR gesprochen: »Gleichwie der Hirt nur zwei Beinchen oder ein Ohrläppchen aus dem Rachen des Löwen rettet, so werden auch die Israeliten, die in Samaria wohnen, sich nur mit dem Teppich des Diwans und mit dem Seidengewebe ihres Ruhebettes retten!« –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 3, 13, '»Hört und bezeugt es dem Hause Jakob« – so lautet der Ausspruch des HERRN, des Gottes der Heerscharen –:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 3, 14, '»An dem Tage, an dem ich die Freveltaten der Israeliten an ihnen heimsuche, da werde ich sie (auch) an den Altären von Bethel heimsuchen, so daß die Hörner des Altars abgehauen werden und zu Boden fallen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 3, 15, 'Da will ich das Winterhaus in Trümmer schlagen samt dem Sommerhaus, und die Elfenbeinsäle sollen zugrunde gehen und gar viele Häuser verschwinden!« – so lautet der Ausspruch des HERRN.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 4, 1, 'Vernehmt dies Wort, ihr Basankühe auf dem Berge Samarias, die ihr die Armen bedrückt, die Niedrigen mißhandelt, die ihr zu euren Ehemännern sagt: »Schaffe herbei, daß wir zechen!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 4, 2, 'Geschworen hat Gott der HERR bei seiner Heiligkeit: »Fürwahr, es sollen Tage über euch kommen, da wird man euch an Angeln wegschaffen und euren Nachwuchs an Fischerhaken.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 4, 3, 'Durch die Mauerspalten werdet ihr dann hinausziehen, eine jede vor sich hin (starrend), und werdet verstoßen werden zum Hermongebirge hin!« – so lautet der Ausspruch des HERRN.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 4, 4, '»Zieht immerhin nach Bethel, um zu sündigen, nach Gilgal, um noch mehr Sünden zu begehen! Bringt jeden Morgen eure Schlachtopfer dar, alle drei Tage eure Zehnten!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 4, 5, 'Verbrennt immerhin gesäuerte Brote als Dankopfer und kündigt recht laut freiwillige Gaben an! Denn so liebt ihr es ja, ihr Israeliten!« – so lautet der Ausspruch des HERRN.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 4, 6, '»Wohl habe ich euch reine Zähne gegeben in allen euren Städten und es euch an Brot mangeln lassen in allen euren Wohnsitzen, aber doch seid ihr nicht zu mir umgekehrt!« – so lautet der Ausspruch des HERRN.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 4, 7, '»Wohl habe ich euch den Regen versagt innerhalb der drei Monate bis zur Ernte und habe auf die eine Stadt Regen fallen lassen, auf die andere aber nicht: der eine Acker empfing Regen, während ein anderer, der keinen empfing, verdorrte;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 4, 8, 'und wohl wankte man aus zwei, drei Städten nach einer anderen Stadt, um Wasser dort zu trinken, und wurde nicht satt; aber doch seid ihr nicht zu mir umgekehrt!« – so lautet der Ausspruch des HERRN.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 4, 9, '»Ich habe euch mit Getreidebrand und mit Vergilben heimgesucht; oftmals habe ich eure Gärten und Weinberge (mit Unfruchtbarkeit) geschlagen, und eure Feigenbäume und Oliven haben die Heuschrecken gefressen; aber doch seid ihr nicht zu mir umgekehrt!« – so lautet der Ausspruch des HERRN.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 4, 10, '»Ich habe die Pest unter euch gesandt wie einst gegen Ägypten; ich habe eure jungen Männer mit dem Schwert erschlagen, indem zugleich eure Rosse als Beute weggeführt wurden, und habe euch den Gestank eurer Heerlager in die Nase steigen lassen; aber doch seid ihr nicht zu mir umgekehrt!« – so lautet der Ausspruch des HERRN.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 4, 11, '»Ich habe Zerstörungen um und um unter euch angerichtet, wie Sodom und Gomorrha einst von Gott völlig zerstört worden sind, so daß ihr einem aus dem Feuer geretteten Holzscheite glichet; aber doch seid ihr nicht zu mir umgekehrt!« – so lautet der Ausspruch des HERRN.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 4, 12, '»Darum will ich so mit dir verfahren, Israel! Und weil ich in dieser Weise mit dir verfahren will, so mache dich bereit, Israel, deinem Gott gegenüberzutreten!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 4, 13, 'Denn wisse wohl: Er ist es, der die Berge gebildet und den Wind geschaffen hat und der dem Menschen seine geheimen Gedanken offenbart, der die Morgenröte zur Dunkelheit macht und über die Höhen der Erde dahinschreitet: der HERR, Gott der Heerscharen, ist sein Name.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 5, 1, 'Vernehmt dieses Wort, das ich als Totenklage über euch anstimme, ihr vom Hause Israel!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 5, 2, 'Gefallen ist sie, die Jungfrau Israel, um nicht wieder aufzustehen; hingestreckt liegt sie auf ihrem eigenen Lande, niemand richtet sie wieder auf!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 5, 3, 'Denn so hat Gott der HERR zum Hause Israel gesprochen: »Die Stadt, die mit tausend (Kriegern) ins Feld zieht, soll nur hundert übrigbehalten, und die mit hundert Mann auszieht, soll nur zehn übrigbehalten!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 5, 4, 'Denn so spricht der HERR zum Hause Israel: »Suchet mich, so werdet ihr leben!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 5, 5, 'Aber suchet nicht Bethel auf, und nach Gilgal dürft ihr nicht gehen und nach Beerseba nicht hinüberziehen! denn Gilgal wird in die Gefangenschaft wandern und Bethel zum Hause des Unheils werden.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 5, 6, 'Suchet den HERRN, so werdet ihr leben! Sonst fährt er in das Haus Josephs wie Feuer hinein und verzehrt es, ohne daß es ein Löschen für Bethel gäbe.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 5, 7, 'Sie verkehren das Recht in Wermut und treten die Gerechtigkeit mit Füßen;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 5, 8, 'Er, der das Siebengestirn und den Orion geschaffen hat, der tiefes Dunkel in Morgenlicht verwandelt und den Tag zur Nacht verfinstert, der die Wasser des Meeres herbeiruft und sie weit über die Erde dahinfluten läßt – HERR (der Heerscharen) ist sein Name –:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 5, 9, 'er läßt Vernichtung über Mächtige aufblitzen und Verwüstung über feste Städte hereinbrechen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 5, 10, 'sie hassen den, der im Tor für das Recht eintritt, und verabscheuen den, der die Wahrheit redet.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 5, 11, 'Darum, weil ihr den Geringen niedertretet und Getreideabgaben von ihm erhebt: ihr mögt euch immerhin Häuser aus Quadersteinen bauen, ihr sollt aber nicht darin wohnen; herrliche Weinberge mögt ihr wohl anlegen, ihr sollt aber keinen Wein von ihnen trinken.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 5, 12, 'Denn ich weiß, eurer Freveltaten sind viele, und zahlreich sind eure Sünden: sie vergewaltigen den Unschuldigen, nehmen Bestechung an und beugen das Recht der Dürftigen im Tor.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 5, 13, 'Darum, wer klug ist in dieser Zeit, der schweigt, denn es ist eine böse Zeit.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 5, 14, 'Suchet das Gute und nicht das Böse, auf daß ihr lebt! Dann wird der HERR, der Gott der Heerscharen, so mit euch sein, wie ihr es immer behauptet.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 5, 15, 'Hasset das Böse und liebet das Gute und haltet das Recht im Tor aufrecht! Vielleicht wird dann der HERR, der Gott der Heerscharen, dem Überrest Josephs gnädig sein.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 5, 16, 'Darum hat Gott der HERR, der Gott der Heerscharen, so gesprochen: »Auf allen Plätzen wird Klaggeschrei erschallen, und auf allen Straßen wird man ›wehe, wehe!‹ rufen. Den Landmann wird man zur Trauer heimrufen und die des Klageliedes Kundigen zur Totenklage (bestellen);');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 5, 17, 'auch in allen Weinbergen wird Wehgeschrei erschallen, wenn ich mitten durch dich dahinschreite!« – der HERR hat es ausgesprochen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 5, 18, 'Wehe denen, die den Tag des HERRN herbeiwünschen! Was soll euch denn der Tag des HERRN bringen? Er ist ja Finsternis, nicht Licht!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 5, 19, '(Da wird es sein) wie wenn ein Mann, der einem Löwen entflohen ist, einem Bären in den Weg läuft und, wenn er glücklich ins Haus hineingekommen ist und sich mit der Hand gegen die Wand lehnt, von einer Schlange gebissen wird.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 5, 20, 'Ja, Finsternis wird der Tag des HERRN sein und nicht Licht, dunkel und ohne hellen Schein!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 5, 21, '»Ich hasse (eure Neumonde), ich verschmähe eure Feste und mag eure Festversammlungen nicht riechen!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 5, 22, 'Denn wenn ihr mir Brandopfer und eure Speisopfer darbringt, so habe ich kein Wohlgefallen daran, und die Dankopfer von euren Mastkälbern mag ich nicht ansehen!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 5, 23, 'Hinweg von mir mit dem Getön deiner Lieder! Dein Harfenspiel mag ich nicht hören!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 5, 24, 'Es möge lieber das Recht sprudeln wie ein Wasserquell und die Gerechtigkeit wie ein nie versiegender Bach!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 5, 25, 'Habt ihr mir etwa Schlachttiere und Speisopfer vierzig Jahre lang in der Wüste dargebracht, ihr vom Hause Israel?');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 5, 26, 'Nein, weil ihr euren König Sakkuth umhergetragen habt und den Kewan, eure Götzenbilder, das Sternbild eures Gottes, die ihr euch angefertigt habt,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 5, 27, 'so will ich euch in die Verbannung führen noch über Damaskus hinaus!« – der HERR hat es ausgesprochen: Gott der Heerscharen ist sein Name.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 6, 1, 'Wehe euch Sorglosen auf dem Zion und euch Zuversichtlichen auf dem Berge von Samaria, euch Adligen des Erstlings unter den Völkern, an welche das Haus Israel sich zu wenden pflegt!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 6, 2, 'Geht doch nach Kalne hinüber und seht es euch an, und wandert von dort weiter nach Groß-Hamath und steigt nach Gath im Philisterlande hinab: seid ihr besser als diese Reiche, oder ist euer Gebiet größer als das ihrige?');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 6, 3, '(Wehe denen,) die den Tag des Unheils fern wähnen und doch den Stuhl der Gewalttat nahe heranrücken!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 6, 4, 'Die da auf Lagern von Elfenbein liegen und auf ihren Ruhebetten sich ausstrecken! Die da Lämmer aus der Herde weg schmausen und Kälber mitten aus dem Maststall!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 6, 5, 'Die zum Klang der Harfe phantasieren und sich Musikinstrumente wie David erdenken!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 6, 6, 'Die den Wein aus Humpen trinken und mit den allerfeinsten Ölen sich salben! Die sich freuen über Lodabar, aber sich nicht härmen um den Untergang Josephs!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 6, 7, 'Darum werden sie nunmehr an der Spitze der Gefangenen in die Gefangenschaft wandern: da wird denn das Jauchzen der träge Hingelagerten ein Ende haben.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 6, 8, '»Geschworen hat Gott der HERR bei sich selbst« – so lautet der Ausspruch des HERRN, des Gottes der Heerscharen –: »Ich verabscheue Jakobs Prunk und hasse seine Paläste und gebe die Stadt preis samt allem, was in ihr ist.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 6, 9, 'Da wird es geschehen, wenn zehn Männer in einem Hause übriggeblieben sind, so sollen sie auch sterben.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 6, 10, 'Wenn dann einen (der Gestorbenen) sein nächster Verwandter, der ihn zu bestatten hat, aufhebt, um die Gebeine aus dem Hause hinauszuschaffen, und an den, der sich im hintersten Raume des Hauses befindet, die Frage richtet: »Ist noch jemand bei dir?«, so wird er antworten: »Niemand«, aber fortfahren: »Still! Denn der Name Gottes des HERRN darf nicht ausgesprochen werden.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 6, 11, 'Denn wisset wohl: der HERR gebietet, und er zerschlägt die großen Häuser in Trümmer und die kleinen Häuser in Stücke. –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 6, 12, 'Rennen wohl Rosse auf Felsen? Oder pflügt man darauf mit Rindern, daß ihr das Recht in Gift verwandelt und die Frucht der Gerechtigkeit in Wermut? –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 6, 13, 'Ihr frohlockt über (die Eroberung von) Lodabar und sagt: »Haben wir nicht durch eigene Kraft Karnaim uns wiedergewonnen?«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 6, 14, 'Doch »wisset wohl, ihr vom Hause Israel: Ich lasse gegen euch ein Volk aufstehen« – so lautet der Ausspruch des HERRN, des Gottes der Heerscharen –, »das soll euch bedrängen von da an, wo der Weg nach Hamath geht, bis an den Weidenbach!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 7, 1, 'Folgendes (Gesicht) hat Gott der HERR mich schauen lassen: Ich sah, wie er Heuschrecken entstehen ließ zur Zeit, als das Spätgras aufzugehen begann, und zwar war es das Spätgras nach der Mahd des Königs.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 7, 2, 'Als sie nun alles, was auf dem Felde gewachsen war, abfraßen, da bat ich: »HERR, mein Gott, vergib doch! Wie soll Jakob bestehen? Er ist ja schon so klein!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 7, 3, 'Da tat dem HERRN sein Vorhaben leid: »Es soll nicht geschehen!« sprach der HERR. –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 7, 4, 'Folgendes (Gesicht) hat Gott der HERR mich schauen lassen: Ich sah, wie Gott der HERR das Feuer zum Strafgericht herbeirief; und dieses verzehrte die große Flut des Grundwassers und wollte auch das Ackerland verzehren.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 7, 5, 'Da bat ich: »HERR, mein Gott, laß doch ab! Wie soll Jakob bestehen? Er ist ja schon so klein!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 7, 6, 'Da tat Gott dem HERRN sein Vorhaben leid: »Auch dies soll nicht geschehen!« sprach Gott der HERR. –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 7, 7, 'Folgendes (Gesicht) hat der HERR mich schauen lassen: Ich sah, wie der HERR auf einer senkrechten Mauer stand und ein Bleilot in der Hand hielt.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 7, 8, 'Da fragte mich der HERR: »Was siehst du, Amos?« Ich antwortete: »Ein Bleilot.« Da sagte der HERR: »Wisse wohl: ich lege das Bleilot an inmitten meines Volkes Israel; ich will fortan nicht mehr schonend an ihm vorübergehen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 7, 9, 'Nein, die Höhenaltäre Isaaks sollen verwüstet werden und die Heiligtümer Israels veröden, und gegen das Haus Jerobeams will ich mit dem Schwert vorgehen!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 7, 10, 'Da sandte Amazja, der Priester von Bethel, zu Jerobeam, dem Könige von Israel, und ließ ihm sagen: »Amos zettelt eine Verschwörung gegen dich an mitten im Hause Israel; das Land vermag alle seine Reden nicht länger zu ertragen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 7, 11, 'Denn folgende Worte hat Amos ausgesprochen: ›Durch das Schwert wird Jerobeam ums Leben kommen, und Israel muß aus seinem Lande in die Gefangenschaft wandern.‹«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 7, 12, 'Darauf sagte Amazja zu Amos: »Seher, mache dich auf, fliehe ins Land Juda! Iß dort dein Brot und weissage dort!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 7, 13, 'In Bethel aber darfst du nicht länger als Prophet auftreten; denn Bethel ist ein königliches Heiligtum und eine königliche Residenz!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 7, 14, 'Da gab Amos dem Amazja zur Antwort: »Ich bin kein Prophet und bin kein Mitglied einer Prophetenschule, sondern ein Hirt bin ich und züchte Maulbeerfeigen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 7, 15, 'Aber der HERR hat mich hinter der Herde weggeholt, und der HERR hat mir geboten: ›Gehe hin, tritt gegen mein Volk Israel als Prophet auf!‹');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 7, 16, 'Und nun vernimm das Wort des HERRN! Weil du sagst, ich dürfe nicht gegen Israel als Prophet auftreten und nicht gegen das Haus Isaak predigen,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 7, 17, 'darum hat der HERR (gegen dich) so gesprochen: ›Dein Weib wird zur Hure werden in der Stadt, deine Söhne und deine Töchter sollen durch das Schwert fallen, und dein Boden soll mit der Meßschnur verteilt werden; du selbst aber sollst in einem unreinen Lande sterben, und Israel muß aus seinem Lande in die Gefangenschaft wandern!‹«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 8, 1, 'Folgendes (Gesicht) hat Gott der HERR mich schauen lassen: Ich sah einen Korb mit reifem Obst dastehen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 8, 2, 'Da fragte er mich: »Was siehst du, Amos?« Ich antwortete: »Einen Korb mit reifem Obst.« Da sagte der HERR zu mir: »Gekommen ist das Ende für mein Volk Israel: ich will fortan nicht mehr schonend an ihm vorübergehen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 8, 3, 'Heulen werden die Lieder in den Palästen an jenem Tage« – so lautet der Ausspruch des HERRN –; »Leichen in Menge: an allen Orten wirft man sie hin! Still!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 8, 4, 'Höret dies, die ihr den Dürftigen gierig nachstellt und auf die Vernichtung der Notleidenden im Lande ausgeht!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 8, 5, 'Die ihr sagt: »Wann ist der Neumond vorüber, damit wir wieder Getreide verhandeln? Und wann der Sabbat, damit wir die Kornspeicher wieder auftun können, (nämlich) um das Getreidemaß zu verkleinern und den Geldpreis zu erhöhen und die Waage betrügerisch zu fälschen,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 8, 6, 'um die Armen für Geld und die Dürftigen für ein Paar Schuhe (als Sklaven) zu kaufen und auch den Abfall des Getreides zu verhandeln?«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 8, 7, 'Geschworen hat der HERR bei dem, auf welchen Jakob stolz ist: »Niemals will ich all ihr Tun vergessen!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 8, 8, 'Müßte nicht um solcher Dinge willen die Erde erbeben und alle ihre Bewohner in Trauer geraten, so daß sie überall sich emporhöbe wie der Nil und aufwogte und sich wieder senkte wie der Strom Ägyptens?');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 8, 9, '»Und geschehen wird es an jenem Tage« – so lautet der Ausspruch Gottes des HERRN –, »da lasse ich die Sonne schon am Mittag untergehen und werde Finsternis über die Erde kommen lassen am lichten Tage.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 8, 10, 'Und ich werde eure Feste in Trauer verwandeln und alle eure Lieder in Totenklage; da werde ich an alle Hüften das Trauergewand bringen und auf jedes Haupt die Glatze, und ich werde es dabei hergehen lassen wie bei der Trauer um den einzigen Sohn und will das Ende davon zu einem bitteren Unheilstage machen!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 8, 11, 'Wisset wohl: es werden Tage kommen« – so lautet der Ausspruch Gottes, des HERRN –, »da will ich einen Hunger (und Durst) ins Land senden (daß alle seine Bewohner vergehen), doch nicht einen Hunger nach Brot und nicht einen Durst nach Wasser, sondern danach, die Worte des HERRN zu hören.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 8, 12, 'Da werden sie von einem Meer zum andern wanken und vom Norden nach dem Osten schweifen, um das Wort des HERRN zu suchen, werden es aber nicht finden.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 8, 13, 'An jenem Tage werden die schönen Jungfrauen und die jungen Männer vor Durst ohnmächtig hinsinken,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 8, 14, 'sie, die jetzt bei der Schuld Samarias schwören mit den Worten: ›So wahr dein Gott lebt, Dan!‹ und ›So wahr dein Schutzgott lebt, Beerseba!‹ Sie sollen fallen und nicht wieder aufstehen.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 9, 1, 'Ich sah den Allherrn am Altar stehen (mit einem Hammer in der Hand), und er sprach: »»Schlage an den Säulenknauf, daß die Pfosten beben, und zerschmettere sie, daß die Trümmer ihnen allen auf den Kopf fallen! Was dann von ihnen noch übrig ist, will ich mit dem Schwert umbringen: nicht einer von ihnen soll entrinnen und kein Flüchtling von ihnen davonkommen!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 9, 2, 'Wenn sie in die Unterwelt einbrechen, wird meine Hand sie von dort zurückholen; und wenn sie in den Himmel hinaufsteigen, will ich sie auch von dort hinabstürzen;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 9, 3, 'wenn sie sich auf dem Gipfel des Karmels verstecken, will ich sie dort aufspüren und zurückholen; und wenn sie sich vor meinen Blicken auf dem Meeresgrunde verbergen, will ich dort der Seeschlange gebieten, sie zu beißen;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 9, 4, 'und wenn sie vor ihren Feinden her in die Gefangenschaft wandern, will ich auch dort dem Schwert gebieten, sie umzubringen; ja, ich will mein Auge auf sie richten zum Unheil und nicht zum Guten!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 9, 5, 'Und Gott, der HERR der Heerscharen, der die Erde anrührt, so daß sie zergeht und alle ihre Bewohner trauern, so daß die Erde überall sich emporhebt wie der Nil und sich wieder senkt wie der Strom Ägyptens;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 9, 6, 'Gott, der seine Obergemächer im Himmel gebaut und sein Gewölbe auf die Erde fest gegründet hat; der den Wassern des Meeres zuruft und sie weit über die Erde dahinfluten läßt, ›HERR‹ ist sein Name – so hat er gesprochen:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 9, 7, '»Geltet ihr mir nicht gleich dem Volk der Kuschiten, ihr vom Hause Israel?« – so lautet der Ausspruch des HERRN. »Wohl habe ich Israel aus dem Lande Ägypten geführt, aber auch die Philister aus Kaphthor und die Syrer aus Kir!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 9, 8, '»Wisset wohl: die Augen Gottes des HERRN sind gegen das sündige Königreich gerichtet, daß ich es von der Fläche des Erdbodens vertilge. Doch will ich das Haus Jakob nicht gänzlich vertilgen« – so lautet der Ausspruch des HERRN –;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 9, 9, '»nein, ich will Befehl erteilen und das Haus Israel unter alle Heidenvölker schütteln, wie man Getreide im Siebe schüttelt, ohne daß ein Körnlein zur Erde fällt.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 9, 10, 'Dann sollen durch das Schwert alle Sünder meines Volkes umkommen, die da sagen: ›Uns wird das Unheil nicht erreichen noch überraschen!‹');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 9, 11, 'An jenem Tage will ich die zerfallene Hütte Davids wieder aufrichten und ihre Risse vermauern, will ihre Trümmer wieder herstellen und sie neu erstehen lassen, wie sie in den Tagen der Vorzeit war,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 9, 12, 'damit sie in Besitz nehmen, was von Edom noch übrig ist und alle Völker, die jemals zu meinem Herrschaftsgebiet gehört haben!« – so lautet der Ausspruch des HERRN, der solches auch vollführt.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 9, 13, '»Wisset wohl: es kommen Tage« – so lautet der Ausspruch des HERRN –, »da wird der Pflüger sich unmittelbar an den Schnitter anschließen und der Traubenkelterer an den Sämann; da werden die Berge von Most triefen und alle Hügel zerfließen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 9, 14, 'Dann will ich auch das Geschick meines Volkes Israel wenden, daß sie die verwüsteten Städte wieder aufbauen und darin wohnen, daß sie Weinberge anpflanzen und den Wein von ihnen trinken, daß sie Gärten anlegen und deren Früchte genießen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 9, 15, 'Dann will ich sie in ihren Boden fest einpflanzen, und sie sollen nicht wieder ausgerissen werden aus ihrem Grund und Boden, den ich ihnen gegeben habe!« – der HERR, dein Gott, hat es verheißen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 1, 1, '(Dies ist) die Weissagung Obadjas. So hat Gott der HERR in bezug auf Edom gesprochen: Eine Kunde haben wir vom HERRN vernommen, und eine Botschaft ist an die Völker gesandt worden: »Auf! Wir wollen uns gegen ihn erheben zum Kriege!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 1, 2, '»Wisse wohl: klein mache ich dich unter den Völkern; ganz verachtet sollst du sein!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 1, 3, 'Dein hochfahrender Sinn hat dich betört, der du in Felsklüften auf hohem Sitze wohnst und in deinem Herzen denkst: ›Wer könnte mich zur Erde hinabstürzen?‹');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 1, 4, 'Wenn du auch hoch horstetest wie der Adler und dein Nest zwischen den Sternen gebaut wäre, würde ich dich doch von dort herabholen!« – so lautet der Ausspruch des HERRN.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 1, 5, 'Wenn Diebe bei dir eingebrochen wären oder nächtliche Räuber – ach, wie bist du zugrunde gerichtet! –, so würden sie doch nur soviel gestohlen haben, als sie bedurften; und wenn Weingärtner in deinen Weinberg eingebrochen wären, würden sie nicht eine Nachlese übriggelassen haben?');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 1, 6, 'Nun aber – wie ist Esau durchstöbert, wie sind seine verborgensten Schätze aufgewühlt worden!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 1, 7, 'Bis an die Landesgrenze haben dich alle deine Verbündeten getrieben; betrogen und vergewaltigt haben dich deine guten Freunde; die dein Brot aßen, legen dir Fallstricke.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 1, 8, '»Fürwahr, an jenem Tage« – so lautet der Ausspruch des HERRN – »werde ich die Weisen aus Edom verschwinden lassen und die Einsicht vom Berglande Esaus;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 1, 9, 'und deine tapferen Krieger, Theman, sollen verzagen, auf daß auch der letzte Mann aus dem Berglande Esaus ausgerottet wird!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 1, 10, 'Wegen des an deinem Bruder Jakob verübten Frevels lastet Schande auf dir, und du wirst auf ewig vernichtet.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 1, 11, 'Damals, als du dabeistandest, als Ausländer sein Hab und Gut wegschleppten und Fremde in seine Tore einzogen und das Los über Jerusalem warfen, da bist auch du wie einer von ihnen gewesen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 1, 12, 'Und doch hättest du deine Lust nicht sehen sollen am Tage deines Bruders, am Tage seines Mißgeschicks, und hättest keine Schadenfreude über die Kinder Juda am Tage ihres Untergangs empfinden und deinen Mund nicht weit aufreißen dürfen am Tage ihrer Not!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 1, 13, 'Du hättest nicht in das Tor meines Volkes einziehen sollen am Tage seines Unglücks und auch nicht deine Lust sehen am Tage seines Unglücks, noch deine Hand nach seinem Hab und Gut ausstrecken dürfen am Tage seines Unglücks!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 1, 14, 'Auch hättest du dich nicht an den Talspalten aufstellen sollen, um seine Flüchtlinge niederzumachen, und hättest seine Entronnenen nicht ausliefern dürfen am Tage der Drangsal!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 1, 15, 'b Wie du getan hast, wird dir wieder getan; was du verübt hast, fällt auf dein eigenes Haupt zurück! a Denn nahe ist der Tag des HERRN über alle Völker.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 1, 16, '»Denn wie ihr (Judäer) auf meinem heiligen Berge (den Zornesbecher) habt trinken müssen, so sollen alle Völker fort und fort (ihn) trinken; ja, sie sollen trinken und taumeln und sollen werden, als wären sie nie gewesen!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 1, 17, 'Aber auf dem Berge Zion wird eine Rettung sein, und er wird als heiliges Gebiet gelten, und die vom Hause Jakob werden ihren Besitz wieder einnehmen.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 1, 18, 'Und das Haus Jakob wird ein Feuer sein und das Haus Joseph eine Flamme; aber das Haus Esau wird zu einem Strohbündel werden, das von jenen angezündet und verzehrt wird, so daß vom Hause Esau nichts übrigbleibt; denn der HERR hat es ausgesprochen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 1, 19, 'Und die im Südland Wohnenden werden das Bergland Esaus in Besitz nehmen und die in der Niederung Wohnenden das Philisterland; auch das Gefilde Ephraims und das Gefilde Samarias werden sie einnehmen, und Benjamin wird Gilead besetzen;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 1, 20, 'und die in die Gefangenschaft Geführten, diese Heerschar der Kinder Israel, werden Phönizien bis Sarepta hin erobern; und die aus Jerusalem in die Gefangenschaft Geführten, die sich in Sepharad befinden, werden die Städte des Südlandes in Besitz nehmen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 1, 21, 'Dann werden sie als Befreier auf den Berg Zion hinaufziehen, um Richter im Berglande Esaus zu sein; das Königtum aber wird dem HERRN gehören.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 1, 1, 'Einst erging das Wort des HERRN an Jona, den Sohn Amitthais, folgendermaßen:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 1, 2, '»Mache dich auf, begib dich nach der großen Stadt Ninive und kündige ihr an, daß ihr böses Tun vor mich gekommen ist!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 1, 3, 'Aber Jona machte sich auf den Weg, um aus dem Angesicht des HERRN hinweg nach Tharsis zu fliehen; und als er nach Joppe hinabgegangen war und dort ein Schiff gefunden hatte, das nach Tharsis fahren wollte, bezahlte er das Fahrgeld und stieg ein, um mit ihnen nach Tharsis zu fahren und so dem HERRN aus den Augen zu kommen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 1, 4, 'Da ließ der HERR einen starken Wind auf das Meer hinabfahren, so daß sich ein gewaltiges Unwetter auf dem Meer erhob und das Schiff zu scheitern drohte.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 1, 5, 'Da gerieten die Leute auf dem Schiff in Angst und schrien ein jeder zu seinem Gott um Hilfe und warfen die Gerätschaften, die sich im Schiff befanden, ins Meer, um (das Schiff) dadurch zu erleichtern. Jona aber war in den Hinterraum des Schiffes hinabgestiegen, hatte sich dort niedergelegt und war fest eingeschlafen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 1, 6, 'Da trat der Schiffshauptmann zu ihm mit den Worten: »Wie kannst du nur schlafen?! Stehe auf, rufe deinen Gott an! Vielleicht nimmt sich dieser Gott unser an, daß wir nicht untergehen.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 1, 7, 'Dann sagten jene zueinander: »Kommt, wir wollen Lose werfen, um zu erfahren, durch wessen Schuld dieses Unglück uns trifft!« Als sie nun die Lose warfen, fiel das Los auf Jona.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 1, 8, 'Da sagten sie zu ihm: »Teile uns doch mit, du, um dessenwillen dies Unglück uns widerfährt: Welches ist dein Gewerbe, und woher kommst du? Wo bist du zu Haus, und was für ein Landsmann bist du?«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 1, 9, 'Da antwortete er ihnen: »Ich bin ein Hebräer und verehre den HERRN, den Gott des Himmels, der das Meer und das feste Land geschaffen hat.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 1, 10, 'Da gerieten die Männer in große Furcht und sagten zu ihm: »Was hast du nur getan?« Die Männer wußten nämlich bereits, daß er sich auf der Flucht vor dem HERRN befand; denn er hatte es ihnen mitgeteilt.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 1, 11, 'Dann fragten sie ihn: »Was sollen wir mit dir machen, damit das Meer sich beruhigt und uns nicht länger bedroht?« Denn das Meer wurde immer noch stürmischer.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 1, 12, 'Da erwiderte er ihnen: »Nehmt mich und werft mich ins Meer, damit das Meer sich beruhigt und euch nicht länger bedroht! Denn ich erkenne, daß dieser gewaltige Sturm durch meine Schuld über euch gekommen ist.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 1, 13, 'Nun strengten sich die Männer zwar an, das Schiff (durch Rudern) ans Land zu bringen, vermochten es aber nicht, weil das Meer immer ärger gegen sie tobte.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 1, 14, 'Da riefen sie den HERRN an mit den Worten: »Ach, HERR! Laß uns doch nicht untergehen, wenn wir diesen Mann ums Leben bringen, und rechne uns nicht unschuldig vergossenes Blut an! Denn du bist der HERR: du hast getan, wie es dir wohlgefallen hat.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 1, 15, 'Darauf ergriffen sie Jona und warfen ihn ins Meer, und sogleich legte sich das Toben des Meeres.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 1, 16, 'Da gerieten die Männer in große Furcht vor dem HERRN; sie brachten dem HERRN ein Schlachtopfer dar und taten Gelübde.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 2, 1, 'Der HERR aber ließ einen großen Fisch kommen, der Jona verschlingen sollte; und Jona befand sich im Bauche des Fisches drei Tage und drei Nächte lang.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 2, 2, 'Da richtete Jona aus dem Leibe des Fisches folgendes Gebet an den HERRN, seinen Gott:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 2, 3, '»Gerufen habe ich aus meiner Bedrängnis zum HERRN, da hat er mich erhört; aus dem Schoß der Unterwelt habe ich um Hilfe geschrien, da hast du mein Rufen vernommen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 2, 4, 'Denn du hattest mich in die Tiefe geschleudert, mitten ins Meer hinein, so daß die Fluten mich umschlossen; alle deine Wogen und Wellen fuhren über mich dahin.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 2, 5, 'Schon dachte ich: ›Verstoßen bin ich, hinweg von deinem Angesicht: wie könnte ich je wieder nach deinem heiligen Tempel schauen?‹');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 2, 6, 'Die Wasser umgaben mich und gingen mir bis an die Seele; die Tiefe umfing mich, Seegras hatte sich mir ums Haupt geschlungen;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 2, 7, 'zu den Wurzeln der Berge war ich hinabgefahren; die Riegel der Erde hatten sich auf ewig hinter mir geschlossen: – da hast du mein Leben aus der Grube heraufgeholt, HERR, mein Gott!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 2, 8, 'Als meine Seele in mir verzagte, da gedachte ich des HERRN, und zu dir drang mein Gebet, zu deinem heiligen Tempel.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 2, 9, 'Die sich an nichtige Götzen halten, verlassen den, bei welchem das Heil für sie liegt.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 2, 10, 'Ich aber will dir laute Danksagung als Opfer darbringen, will, was ich gelobt habe, bezahlen: die Rettung kommt vom HERRN!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 2, 11, 'Hierauf gebot der HERR dem Fisch, und dieser spie Jona ans Land aus.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 3, 1, 'Nun erging das Wort des HERRN an Jona zum zweitenmal folgendermaßen:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 3, 2, '»Mache dich auf, begib dich nach der großen Stadt Ninive und laß sie die Botschaft hören, die ich dir ansagen werde!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 3, 3, 'Da machte Jona sich auf den Weg und begab sich nach Ninive, wie der HERR ihm geboten hatte. Ninive war aber eine gewaltig große Stadt, deren Durchwanderung drei Tagereisen erforderte.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 3, 4, 'So begann denn Jona eine Tagereise weit in die Stadt hineinzugehen und predigte dabei mit den Worten: »Noch vierzig Tage, dann ist Ninive zerstört!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 3, 5, 'Da glaubten die Einwohner von Ninive an Gott, riefen ein Fasten aus und legten Sackleinen an, klein und groß;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 3, 6, 'und als die Kunde davon zum König von Ninive gelangte, erhob er sich von seinem Thron, legte seinen Mantel ab, hüllte sich in ein Trauergewand und setzte sich in die Asche.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 3, 7, 'Sodann ließ er in Ninive durch Ausruf bekanntmachen: »Auf Befehl des Königs und seiner Großen (wird folgende Verordnung erlassen): Menschen und Vieh, Rinder und Kleinvieh sollen durchaus nichts genießen; dürfen nicht auf die Weide gehen und kein Wasser trinken,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 3, 8, 'sondern sollen, sowohl Menschen als Vieh, in Sackleinen gekleidet sein und mit aller Macht zu Gott rufen und umkehren ein jeder von seinem bösen Wege und von dem Unrecht ablassen, das an seinen Händen klebt!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 3, 9, 'Vielleicht tut es Gott dann doch noch leid, und er läßt von seinem lodernden Zorn ab, so daß wir nicht untergehen!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 3, 10, 'Als nun Gott sah, was sie taten, daß sie nämlich von ihrem bösen Wege umkehrten, tat ihm das Unheil leid, das er ihnen angedroht hatte, und er ließ es nicht eintreten.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 4, 1, 'Das verursachte aber dem Jona großen Verdruß, und er geriet in Zorn,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 4, 2, 'so daß er folgendes Gebet an den HERRN richtete: »Ach, HERR, das ist es ja, was ich gedacht habe, als ich noch daheim war, und eben darum habe ich das vorige Mal die Flucht nach Tharsis ergriffen; denn ich wußte wohl, daß du ein gnädiger und barmherziger Gott bist, langsam zum Zorn und reich an Güte und geneigt, dich das Unheil gereuen zu lassen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 4, 3, 'Und nun, HERR, nimm doch mein Leben von mir! Denn es ist besser für mich, zu sterben als noch am Leben zu bleiben.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 4, 4, 'Aber der HERR erwiderte: »Ist es recht von dir, so zu zürnen?«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 4, 5, 'Hierauf ging Jona aus der Stadt hinaus und ließ sich östlich von der Stadt nieder; er baute sich dort eine Hütte und setzte sich unter ihr in den Schatten, um abzuwarten, wie es der Stadt ergehen würde.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 4, 6, 'Da ließ Gott der HERR eine Rizinusstaude aufschießen und über Jona emporwachsen, damit er seinem Haupte Schatten biete und ihn von seinem Unmut befreie; und Jona hatte große Freude an dem Rizinus.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 4, 7, 'Am andern Tage aber, als die Morgenröte aufging, ließ Gott einen Wurm entstehen, der fraß die Rizinusstaude an, so daß sie verdorrte;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 4, 8, 'und als die Sonne aufging, ließ Gott einen schwülen Ostwind kommen; und die Sonne stach Jona auf das Haupt, so daß er ganz ohnmächtig wurde und sich den Tod wünschte mit den Worten: »Es ist besser für mich, zu sterben als noch am Leben zu bleiben!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 4, 9, 'Da sagte Gott zu Jona: »Ist es wohl recht von dir, wegen der Rizinusstaude so zornig zu sein?« Er antwortete: »Ja, mit Recht bin ich erzürnt bis zum Sterben!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 4, 10, 'Der HERR aber entgegnete: »Dir tut der Rizinus leid, um den du dich doch nicht gemüht und den du nicht großgezogen hast, der in einer Nacht entstanden und in einer Nacht vergangen ist.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 4, 11, 'Und mir sollte die große Stadt Ninive nicht leid tun, in der mehr als hundertzwanzigtausend Menschen leben, die zwischen rechts und links noch nicht zu unterscheiden wissen, dazu auch eine Menge Tiere?«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 1, 1, '(Dies ist) das Wort des HERRN, das an Micha aus Moreseth in den Tagen der judäischen Könige Jotham, Ahas und Hiskia ergangen ist und das er über Samaria und Jerusalem geschaut hat.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 1, 2, 'Höret, ihr Völker allesamt; merke auf, o Erde und alles, was sie erfüllt! Und es sei Gott der HERR Zeuge gegen euch, der Allherr von seinem heiligen Tempel aus!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 1, 3, 'Denn sehet: der HERR verläßt seine Wohnstätte, er steigt herab und schreitet dahin über die Höhen der Erde.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 1, 4, 'Da zerfließen die Berge unter seinen Schritten, und die Täler spalten sich – wie Wachs vor dem Feuer, wie Wasser an einem Abhang hinabstürzt.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 1, 5, 'Dies alles (geschieht) wegen der Untreue Jakobs und wegen der Sünden des Hauses Israel! Wer ist es aber, der die Untreue Jakobs verübt? Doch wohl Samaria! Und wer vollführt die Sünde des Höhendienstes Judas? Doch wohl Jerusalem!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 1, 6, '»So will ich denn Samaria zu einem Steinhaufen im Felde machen, zum Gelände für Weinberge; ich will die Steine der Stadt ins Tal hinabstürzen und ihre Grundmauern bloßlegen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 1, 7, 'Alle ihre Schnitzbilder sollen zerschlagen und alle ihre buhlerischen Weihegaben im Feuer verbrannt werden, und alle ihre Götzenbilder will ich der Vernichtung preisgeben; denn vom Buhlerlohn sind sie zusammengebracht: so sollen sie auch wieder zu Buhlerlohn werden!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 1, 8, 'Darüber will ich wehklagen und jammern, will barfuß und ohne Obergewand einhergehen! Ich will eine Wehklage anstimmen wie die Schakale und ein Trauerlied wie die Strauße!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 1, 9, 'Denn unheilbar ist der Schlag (der Samaria getroffen hat): er dringt bis nach Juda, reicht bis an die Tore meines Volkes, bis nach Jerusalem.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 1, 10, 'In Gath tut es nicht kund! In Akko veranstaltet kein Weinen! In Beth-Leophra wälzt euch im Staube!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 1, 11, 'Mache dich auf den Weg, Einwohnerschaft von Saphir, in schimpflicher Entblößung! Die Bevölkerung von Zaanan zieht nicht mehr aus! Die Trauer Beth-Haezels nimmt euch die Lust, dort zu rasten.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 1, 12, 'Ach, es zittert um ihr Heil die Bevölkerung von Maroth, denn Unheil fährt vom HERRN her an die Tore Jerusalems herab!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 1, 13, 'Schirre die Renner an den Wagen, Einwohnerschaft von Lachis! Dort ist der Anfang der Versündigung für die Tochter Zion gewesen; denn bei dir (zuerst) haben sich die Missetaten Israels vorgefunden.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 1, 14, 'Darum mußt du das Entlassungsgeschenk geben an Moreseth-Gath. Die Häuser von Achsib werden für die Könige von Israel trüglich werden.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 1, 15, 'Einen neuen Besitzer bringe ich dir, Bewohnerschaft von Maresa. Auf ewig geht Adullam zugrunde (wie) die Herrlichkeit Israels.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 1, 16, 'Mache dir das Haupt kahl und schere dir den Bart ab um deine geliebten Kinder! Mache dir die Glatze so breit wie die eines Geiers! Denn sie müssen fort von dir (in die Gefangenschaft) wandern!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 2, 1, 'Wehe denen, die auf Frevel sinnen und Böses planen auf ihren Lagern und die es beim nächsten Morgenlicht ausführen, weil die Macht dazu in ihrer Hand liegt!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 2, 2, 'Gelüstet es sie nach Äckern, so bemächtigen sie sich ihrer mit Gewalt, oder nach Häusern, so nehmen sie sie weg: sie verüben Gewalttat an dem Besitzer und seinem Hause, an dem Eigentümer und seinem Erbgut.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 2, 3, 'Darum hat der HERR so gesprochen: »Wisset wohl: (auch) ich habe gegen dieses Geschlecht Unheil im Sinn, aus dem ihr eure Hälse nicht herausziehen und worin ihr nicht mehr aufrecht einhergehen könnt; denn es soll eine schlimme Zeit sein!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 2, 4, 'An jenem Tage wird man ein Spottlied auf euch anheben und ein Klagelied anstimmen, das so lautet: »Es ist aus! Völlig vernichtet sind wir! Das Erbteil meines Volkes gibt er in fremde Hände: ach, wie entzieht er es mir! An Abtrünnige teilt er unsere Felder aus!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 2, 5, 'Darum wirst du niemand haben, der dir die Meßschnur über ein Ackerlos wirft in der Gemeinde des HERRN.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 2, 6, '»Laßt das prophetische Predigen!« predigen sie; »derartige Dinge predigt man nicht! Nicht wird Schande uns alle treffen!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 2, 7, 'Ist das Haus Jakobs etwa verflucht? Ist der HERR etwa zornmütig, oder ist sein Tun von dieser Art? Meinen seine Worte es nicht gut mit dem, der rechtschaffen wandelt?«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 2, 8, 'Aber ihr seid es, die feindselig gegen mein Volk auftreten! Vom Rock herunter reißt ihr den Mantel denen ab, die arglos vorüberziehen, die von Streit nichts wissen wollen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 2, 9, 'Die Frauen meines Volkes vertreibt ihr aus ihrem beglückenden Heim und raubt ihren kleinen Kindern meinen Ehrenschmuck auf immer.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 2, 10, '»Packt euch!« (so sagt ihr) und »hinweg mit euch, denn hier ist eures Bleibens nicht!« Um einer geringen Kleinigkeit willen vollzieht ihr grausam Pfändung.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 2, 11, 'Ja, wenn jemand käme, der dem Winde nachliefe und euch Lug und Trug vortrüge: »Ich will dir von Wein und Würztrank predigen!« – der wäre ein Prediger für dieses Volk!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 2, 12, '»Sammeln, ja sammeln will ich dich, Jakob, insgesamt; zusammenbringen, ja zusammenbringen will ich, was von Israel noch übrig ist! Vereinigen will ich sie wie Schafe in der Hürde, wie eine Herde auf der Trift, so daß sie eine von Menschen wimmelnde Menge bilden.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 2, 13, 'An ihrer Spitze zieht dann der leitende Widder dahin, sie brechen durch, ziehen durch das Tor und gehen hinaus: ihr König schreitet vor ihnen her und der HERR selber an ihrer Spitze.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 3, 1, 'Da sagte ich: »Höret doch, ihr Häupter Jakobs und ihr Obersten des Hauses Israel! Kommt es euch nicht zu, das Recht zu kennen?');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 3, 2, 'Und doch haßt ihr das Gute und liebt das Böse; ihr reißt den Leuten die Haut vom Leibe und das Fleisch von den Knochen;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 3, 3, 'ihr haßt das Fleisch meines Volkes, zieht ihnen die Haut vom Leibe ab und zerschlagt ihnen die Knochen, ihr zerlegt sie wie (einen Braten) im Kochtopf und wie Fleischstücke im Kessel.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 3, 4, 'Dereinst werden sie zum HERRN schreien, doch er wird sie nicht erhören, sondern sein Angesicht zu jener Zeit vor ihnen verbergen, wie sie es mit ihrem bösen Tun verdient haben.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 3, 5, 'So hat der HERR gegen die Propheten gesprochen, die mein Volk irreführen, die, solange ihre Zähne etwas zu beißen haben, Frieden verkünden, aber dem, der ihnen nichts in den Mund steckt, den Krieg erklären.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 3, 6, '»Darum soll es Nacht für euch werden, so daß ihr keine Gesichte schaut, und Finsternis für euch eintreten, so daß keine Weissagung stattfindet; da soll die Sonne für die Propheten untergehen und der Tag über ihnen zu finsterer Nacht werden;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 3, 7, 'dann werden die Seher beschämt dastehen und die Wahrsager erröten müssen; und sie werden sich alle den Bart verhüllen, weil keine Antwort von Gott mehr erfolgt.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 3, 8, 'Ich dagegen bin mit Kraft erfüllt, mit dem Geist des HERRN und mit Rechtsgefühl und Mut, um Jakob seine Treulosigkeit vorzuhalten und Israel seine Sünde.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 3, 9, 'Höret doch dieses, ihr Häupter des Hauses Jakob und ihr Obersten des Hauses Israel, die ihr das Recht verabscheut und alles Gerade krumm macht,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 3, 10, 'die ihr Zion mit Blutvergießen aufbaut und Jerusalem mit Unrecht!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 3, 11, 'Seine Häupter sprechen Recht für Geschenke, seine Priester erteilen Rechtsbescheide für Bezahlung, und seine Propheten wahrsagen für Geld; und dabei verlassen sie sich auf den HERRN, daß sie sagen: »Ist nicht der HERR in unserer Mitte? Uns kann kein Unglück widerfahren!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 3, 12, 'Darum wird um euretwillen Zion zu Ackerland umgepflügt und Jerusalem zu einer Trümmerstätte werden und der Tempelberg zu einer bewaldeten Höhe!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 4, 1, 'Am Ende der Tage aber wird es geschehen, daß der Tempelberg des HERRN festgegründet dasteht an der Spitze der Berge und über die anderen Höhen erhaben; dann werden die Völker zu ihm strömen');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 4, 2, 'und zahlreiche Völkerschaften sich aufmachen und sagen: »Kommt, laßt uns zum Berge des HERRN hinaufziehen und zum Hause des Gottes Jakobs, damit er uns über seine Wege belehre und wir auf seinen Pfaden wandeln!« Denn von Zion wird Belehrung ausgehen und das Wort des HERRN von Jerusalem.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 4, 3, 'Dann wird er zwischen vielen Völkern richten und mächtigen Völkerschaften Recht sprechen bis in weite Ferne. Da werden sie ihre Schwerter zu Pflugscharen umschmieden und ihre Lanzenspitzen zu Winzermessern. Kein Volk wird noch das Schwert gegen ein anderes Volk erheben, noch sich hinfort auf den Krieg einüben;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 4, 4, 'sie werden ein jeder unter seinem Weinstock und unter seinem Feigenbaum sitzen, ohne daß jemand sie aufschreckt; denn der Mund des HERRN der Heerscharen hat es verheißen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 4, 5, 'Mögen alle Völker ein jedes im Namen seines Gottes wandeln – wir wollen im Namen des HERRN, unsers Gottes, wandeln immer und ewig!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 4, 6, '»An jenem Tage« – so lautet der Ausspruch des HERRN –, »da will ich sammeln, was hinkt, und zusammenbringen, was zerstreut ist, und alle, denen ich Unheil zugefügt habe.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 4, 7, 'Und ich will die Hinkenden zu einem Überrest machen und das Weitentfernte zu einem starken Volke; und als König wird der HERR über sie herrschen auf dem Berge Zion von nun an bis in Ewigkeit.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 4, 8, 'Du aber, Herdenturm, du Hügel der Tochter Zion, an dich wird gelangen und zu dir zurückkehren die vormalige Herrschaft, das Königtum der Tochter Jerusalem.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 4, 9, 'Nun aber, warum erhebst du ein solches Jammergeschrei? Darüber, daß es keinen König in dir gibt? Oder ist dein Berater umgekommen, daß Wehen dich ergriffen haben wie ein Weib in Kindesnöten?');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 4, 10, 'Ja, winde dich in Wehen und brich in Geschrei aus, Tochter Zion, wie ein Weib in Kindesnöten! Du mußt ja nun aus der Stadt hinausziehen, mußt auf freiem Felde lagern und bis Babylon wandern! Dort aber wirst du Rettung finden, dort wird der HERR dich aus der Hand deiner Feinde erlösen!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 4, 11, 'Jetzt freilich haben sich viele Völker gegen dich versammelt und rufen: »(Zion) soll entweiht werden, auf daß unser Auge sich an seinem Schicksal weide!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 4, 12, 'Aber sie kennen die Gedanken des HERRN nicht und wissen nichts von seinem Ratschluß, daß er sie nämlich zusammengebracht hat wie Garben auf der Tenne.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 4, 13, 'Steh auf, Tochter Zion, und drisch! Denn ich will dein Horn zu Eisen und deine Hufe zu Erz machen, auf daß du viele Völker zermalmst und ihren Raub dem HERRN weihst und ihren Reichtum dem Herrn der ganzen Erde.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 4, 14, 'Und nun laß dich zusammendrängen, Tochter der Bedrängnis! Einen Belagerungswall haben sie gegen uns aufgeworfen, und mit dem Stock schlagen sie den Richter Israels ins Gesicht.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 5, 1, 'Du aber, Bethlehem-Ephrath, bist zwar zu klein, als daß du zu den Gaustädten Judas gehörtest, aber aus dir wird mir der hervorgehen, der in Israel Herrscher sein soll und dessen Herkunft der Vergangenheit, den Tagen der Urzeit, angehört.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 5, 2, 'Darum wird er sie preisgeben bis zu der Zeit, wo sie, die gebären soll, geboren hat und der Rest seiner Volksgenossen zu den Kindern Israel zurückkehrt.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 5, 3, 'Dann wird er auftreten und (seine Herde) weiden in der Kraft des HERRN, im hoheitsvollen Namen des HERRN, seines Gottes, so daß sie sicher wohnen; denn nunmehr wird er groß dastehen bis an die Enden der Erde.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 5, 4, 'Und folgender Art wird der Friede (mit den Assyrern) sein: Wenn Assyrien in unser Land einrückt und unser Gebiet betritt, dann werden wir sieben Hirten und acht fürstliche Männer gegen sie aufstellen;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 5, 5, 'die werden das Land der Assyrer mit dem Schwert abweiden, das Land Nimrods mit der blanken Klinge. So wird er uns vor den Assyrern erretten, wenn sie in unser Land einrücken und unser Gebiet betreten.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 5, 6, 'Dann wird der Überrest Jakobs (unter den Heiden) inmitten der Völkermenge sein wie der Tau vom HERRN, wie Regenschauer auf Wiesengras, die auf Menschen nicht warten und auf Menschenkinder nicht harren.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 5, 7, 'Dann wird der Überrest Jakobs unter den Heiden inmitten der Völkermenge sein wie ein Löwe unter den Tieren des Waldes, wie ein junger Leu unter Schafherden, der, wenn er hindurchgeht, niedertritt und rettungslos zerreißt. –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 5, 8, 'Hoch erhoben soll dein Arm über deine Bedränger sein, und alle deine Feinde sollen ausgerottet werden!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 5, 9, '»Und dann, an jenem Tage« – so lautet der Ausspruch des HERRN –, »da werde ich deine Rosse aus deiner Mitte vertilgen und deine Kriegswagen vernichten;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 5, 10, 'da werde ich die Städte deines Landes zerstören und alle deine Festungen niederreißen;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 5, 11, 'da werde ich auch die Zaubermittel aus deiner Hand vernichten, und Beschwörer soll es bei dir nicht mehr geben;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 5, 12, 'da werde ich auch deine Götzenbilder vernichten und deine Malsteine aus deiner Mitte, damit du dich vor dem Machwerk deiner Hände nicht mehr niederwirfst;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 5, 13, 'da werde ich deine Götzenbäume aus deiner Mitte ausreißen und deine Haine vernichten');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 5, 14, 'und werde in Zorn und Ingrimm Rache an den Völkern nehmen, die nicht haben gehorchen wollen.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 6, 1, 'Höret doch, was der HERR gesprochen hat: »Auf! Erhebe die Anklage angesichts der Berge und laß die Anhöhen deine Stimme vernehmen!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 6, 2, 'Höret, ihr Berge, die Anklage des HERRN und merkt auf, ihr Grundfesten der Erde! Denn einen Rechtsstreit hat der HERR mit seinem Volke, und mit Israel will er sich auseinandersetzen:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 6, 3, '»Mein Volk, was habe ich dir zuleide getan und womit dich gekränkt? Lege Zeugnis gegen mich ab!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 6, 4, 'Ich habe dich doch aus dem Lande Ägypten hergeführt und dich aus dem Diensthause freigemacht, ich habe Mose, Aaron und Mirjam (als Führer) vor dir hergehen lassen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 6, 5, 'Mein Volk, denke doch daran, was Balak, der Moabiterkönig, im Sinn gehabt und was Bileam, der Sohn Beors, ihm geantwortet hat, und an die Ereignisse auf dem Zuge von Sittim bis Gilgal, damit du die Gnadenerweise des HERRN erkennst!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 6, 6, '»Womit soll ich vor den HERRN treten, mich beugen vor dem Gott der Höhe? Soll ich mit Brandopfertieren vor ihn treten, mit einjährigen Kälbern?');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 6, 7, 'Hat der HERR Wohlgefallen an Tausenden von Widdern, an Zehntausenden von Bächen Öls? Oder soll ich meinen Erstgeborenen als Schuldopfer für mich hingeben, die Frucht meines Leibes als Sündopfer für mein Leben?«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 6, 8, 'Er hat dir kundgetan, o Mensch, was gut ist; und was fordert der HERR anderes von dir, als Gerechtigkeit zu üben und dich der Liebe zu befleißigen und demütig zu wandeln mit deinem Gott?');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 6, 9, 'Horch! Der HERR ruft der Stadt zu – und Weisheit ist es, deinen Namen zu fürchten –; vernehmt (Landvolk und Stadtgemeinde) die Zuchtrute und den, der sie bestellt hat!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 6, 10, '»Ist immer noch unrecht erworbenes Gut im Hause des Gottlosen und das fluchwürdige, schwindsüchtige Getreidemaß?');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 6, 11, 'Kann ich Straflosigkeit üben bei unrichtiger Waage und bei einem Beutel mit falschen Gewichtstücken?');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 6, 12, 'Die Reichen in der Stadt sind voll von Gewalttätigkeit, ihre Bewohner reden Lügen, und ihre Zunge ist Trug in ihrem Munde.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 6, 13, 'So will denn auch ich dir unheilbar tiefe Wunden schlagen, dich vernichten um deiner Sünden willen:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 6, 14, 'du sollst essen, aber nicht satt werden, so daß dein Hunger ungestillt bleibt; schaffst du etwas beiseite, so sollst du es doch nicht retten, und was du gerettet hast, das will ich dem Schwerte preisgeben.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 6, 15, 'Du wirst säen, aber nicht ernten, wirst Oliven pressen, aber mit Öl dich nicht salben, und Trauben keltern, aber keinen Wein davon trinken.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 6, 16, 'Denn du hast die Lehren Omris befolgt und das ganze Treiben des Hauses Ahabs; und ihr seid nach ihren Ratschlägen gewandelt, damit ich dich zum abschreckenden Beispiel mache und deine Bewohnerschaft zum Gespött, und damit ihr den Hohn der Völker tragt!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 7, 1, 'Wehe mir! Denn es ergeht mir wie bei der Obstlese, wie bei der Nachlese in der Weinernte: nicht eine Traube ist mehr da zum Essen, nicht eine Frühfeige, nach der mein Herz verlangt!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 7, 2, 'Ausgestorben sind die Frommen im Lande, und es gibt keinen Ehrlichen mehr unter den Menschen; allesamt liegen sie auf der Lauer nach Bluttaten, jeder macht Jagd auf den andern mit dem Fangnetz.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 7, 3, 'Auf das Böse sind ihre Hände gerichtet, um es eifrig auszuführen: der Fürst fordert, und der Richter steht ihm gegen Bezahlung zu Diensten; der Mächtige spricht das aus, wonach ihn in seiner Gier gelüstet, und dann flechten sie es ineinander.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 7, 4, 'Der Beste unter ihnen ist wie ein Dornstrauch, der Rechtschaffenste noch schlimmer als eine Dornhecke. Aber der Tag, den deine Späher angekündigt haben, dein Strafgericht, kommt heran: da wird die Bestürzung bei ihnen anheben.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 7, 5, 'Trauet keinem Genossen mehr, verlaßt euch nicht auf den Freund! Vor dem Weibe, das an deiner Brust liegt, hüte die Pforten deines Mundes!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 7, 6, 'Denn der Sohn mißachtet den Vater, die Tochter lehnt sich gegen ihre Mutter auf, die Schwiegertochter gegen ihre Schwiegermutter, und eines jeden Feinde sind die eigenen Hausgenossen. –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 7, 7, 'Ich aber will nach dem HERRN ausschauen, will harren auf den Gott, der mir hilft: mein Gott wird mich erhören!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 7, 8, 'Freue dich nicht über mich, meine Feindin! Denn bin ich auch gefallen, so stehe ich doch wieder auf, und sitze ich auch in Finsternis, so ist doch der HERR mein Licht.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 7, 9, 'Den Zorn des HERRN will ich tragen – denn ich habe gegen ihn gesündigt –, bis er meine Sache in die Hand nimmt und mir Recht schafft: er wird mich ans Licht herausführen, daß ich seine Gerechtigkeit mit Freuden schaue.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 7, 10, 'Auch meine Feindin wird es sehen, und Beschämung wird sie bedecken, sie, die zu mir gesagt hat: »Wo ist nun der HERR, dein Gott?« Meine Augen werden sich an ihrem Anblick weiden, wenn sie alsdann zertreten wird wie Kot auf der Straße. –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 7, 11, '»Ein Tag kommt, wo deine Mauern wieder aufgebaut, der Tag, wo deine Grenzen hinausgerückt werden.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 7, 12, 'An jenem Tage wird man zu dir kommen von Assyrien bis Ägypten und von Ägypten bis zum Euphratstrom, von einem Meer bis zum anderen und von einem Gebirge bis zum anderen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 7, 13, 'Die Erde aber wird zur Wüste werden um ihrer Bewohner willen, zur Strafe für ihre Taten.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 7, 14, 'Weide dein Volk mit deinem Hirtenstabe, die Herde deines Erbteils, die da abgesondert für sich das Waldland bewohnt auf dem Karmel! Laß sie auch wieder in Basan und Gilead weiden wie in den Tagen der Vorzeit!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 7, 15, '»Wie einst in den Tagen, als du aus Ägyptenland zogest, will ich sie wieder Wundertaten schauen lassen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 7, 16, 'Die Heidenvölker werden es sehen und beschämt werden trotz all ihrer Macht; sie werden die Hand auf den Mund legen, und ihre Ohren werden taub sein;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 7, 17, 'sie werden Staub lecken wie die Schlangen, wie das Gewürm am Erdboden; zitternd werden sie aus ihren Burgen hervorkommen, bebend dem HERRN, unserm Gott, sich nahen und vor dir sich fürchten.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 7, 18, 'Wer ist ein Gott wie du, der Sündenschuld vergibt und an den Missetaten des Überrestes seines Eigentumsvolkes vorübergeht? Der nicht ewiglich an seinem Zorn festhält, sondern Freude an der Gnade hat?');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 7, 19, 'Er wird sich unser aufs neue erbarmen, wird unsere Verschuldungen niedertreten und alle unsere Missetaten in die Tiefen des Meeres versenken.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 7, 20, 'Du wirst an Jakob Treue, an Abraham Gnade erweisen, die du unsern Vätern zugeschworen hast in den Tagen der Vorzeit.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 1, 1, '(Dies ist) der Gottesspruch über Ninive, das Buch des Gesichts Nahums, des Elkositers.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 1, 2, 'Ein eifernder und rächender Gott ist der HERR, ja ein Rächer ist der HERR und voller Zornesglut; Rache übt der HERR an seinen Widersachern und trägt seinen Feinden (ihre Verschuldungen) nach.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 1, 3, 'Der HERR ist wohl langsam zum Zorn und groß an Gnade, läßt aber (den Schuldigen) keineswegs ungestraft. Durch Sturm und Ungewitter geht der Weg des HERRN, und Gewölk ist der Staub seiner Füße.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 1, 4, 'Er schilt das Meer und legt es trocken und läßt alle Ströme versiegen; Basan und der Karmel verdorren, und die Blüte des Libanons verwelkt.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 1, 5, 'Die Berge erbeben vor ihm, und die Hügel zerschmelzen; die Erde hebt sich bei seinem Anblick empor, der Erdkreis samt allen, die darauf wohnen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 1, 6, 'Wer kann vor seinem Groll bestehen und wer standhalten bei der Glut seines Zornes? Sein Grimm wirkt sich wie Feuer aus, und die Felsen zerspringen vor ihm.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 1, 7, 'Doch gütig ist der HERR (gegen die auf ihn Hoffenden), eine feste Burg am Tage der Drangsal, und er kennt die, welche bei ihm Zuflucht suchen;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 1, 8, 'aber mit überschwemmender Flut vernichtet er seine Widersacher, und Finsternis verfolgt seine Feinde.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 1, 9, 'Was ersinnt ihr Anschläge gegen den HERRN? Vernichtung wird er herbeiführen: nicht zum zweitenmal braucht die Drangsal sich zu erheben.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 1, 10, 'Denn wären sie gar wie Dornen dicht verflochten und wie von ihrem Trank durchtränkt, sollen sie doch völlig verzehrt werden wie dürre Stoppeln! –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 1, 11, 'Von dir (Ninive) ist der ausgegangen, der Böses gegen den HERRN ersann, der nichtswürdige Ränkeschmied.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 1, 12, 'So hat der HERR gesprochen: »Wenn sie auch wohlgemut und noch so zahlreich sind, sollen sie doch abgemäht werden und dahinfahren! Und habe ich dich (Juda) auch gedemütigt, so will ich dich doch fortan nicht mehr demütigen,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 1, 13, 'sondern will nunmehr sein Joch, das auf dir lastet, zerbrechen und deine Stricke zerreißen.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 1, 14, 'Über dich aber (Assyrien) hat der HERR bestimmt, daß von deinem Namen fernerhin kein Same kommen soll. »Aus dem Hause deines Gottes will ich Schnitzbild und Gußbild ausrotten, will dir dein Grab herrichten; denn zu leicht bist du erfunden worden.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 2, 1, 'Sehet da: auf den Bergen die Schritte eines Freudenboten, der Heil verkündigt! Feiere, Juda, deine Feste, erfülle deine Gelübde! Denn hinfort wird der Nichtswürdige dich nicht mehr durchziehen: er ist völlig vernichtet.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 2, 2, 'Es rückt gegen dich (Ninive) der Zerstörer heran: wahre die Festung, überwache die Straße, lege dir den Gurt fest um die Hüften, nimm alle Kraft zusammen!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 2, 3, 'Denn der HERR stellt den Weinstock Jakobs wieder her gleichwie den Weinstock Israels; denn Verwüster haben sie verwüstet und ihre Ranken vernichtet.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 2, 4, 'Die Schilde seiner Krieger sind rot gefärbt, die Mannen in Scharlach gekleidet; es funkelt der Stahl an den Kriegswagen, sooft er sie zurüstet, und die Lanzen werden geschwungen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 2, 5, 'Auf den Straßen rasen die Wagen einher, jagen auf den freien Plätzen dahin; wie Fackeln sind sie anzusehen, wie Blitze fahren sie hin und her.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 2, 6, 'Er bietet seine Edlen auf: strauchelnd kommen sie auf ihren Bahnen herbei; sie eilen hin zur Mauer der Stadt, doch schon ist das Schutzdach aufgestellt.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 2, 7, 'Die Tore an den Strömen werden erbrochen: da verzagt der Palast.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 2, 8, 'Die Königin wird entkleidet und weggeführt, während ihre Mägde wie girrende Tauben schluchzen und sich auf den Busen schlagen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 2, 9, 'Ninive ist wie ein Teich, dessen Wasser entweichen. (Wohl ruft man:) »Halt, halt!«, doch niemand wendet sich um.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 2, 10, '»Raubt Silber, raubt Gold!« Denn unermeßlich ist der Vorrat, die Fülle von Kostbarkeiten jeder Art.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 2, 11, 'O Öde, Verödung und Verheerung! Verzagte Herzen und schlotternde Knie, Zittern in allen Lenden und Totenblässe in allen Gesichtern!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 2, 12, 'Wo ist nun die Behausung der Löwen und die Lagerstätte der jungen Leuen, wo der Löwe, die Löwin umherstreifte und das Löwenjunge, von niemand aufgeschreckt?');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 2, 13, 'Der Löwe raubte, bis seine Jungen genug hatten, und mordete für seine Löwinnen; er füllte seine Höhlen mit Raub an und seine Schlupfwinkel mit zerrissenen (Beutetieren).');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 2, 14, '»Nunmehr will ich an dich« – so lautet der Ausspruch des HERRN der Heerscharen – »und will deine Kriegswagen in Rauch aufgehen lassen; deine jungen Leuen soll das Schwert fressen, und ich will deinem Rauben auf der Erde ein Ende machen, und die Stimme deiner Sendlinge soll man fortan nicht mehr vernehmen!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 3, 1, 'Wehe der blutbefleckten Stadt, die ganz angefüllt ist mit Trug und Gewalttat und die kein Ende des Raubens findet!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 3, 2, 'Horch Peitschenknall, horch Rädergerassel! Jagende Rosse und rollende Wagen,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 3, 3, 'heransprengende Reiter, funkelnde Schwerter und blitzende Speere! Durchbohrte in Menge, Haufen von Toten und zahllose Leichen – man strauchelt über die Leichen!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 3, 4, 'Und (das alles) wegen der vielen Buhlereien der holdseligen, verführerischen Buhlerin, die ganze Völker mit ihrer Buhlerei berückte und Völkerschaften mit ihren Zauberkünsten (umgarnte).');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 3, 5, '»Nunmehr will ich an dich« – so lautet der Ausspruch des HERRN der Heerscharen – »und will deine Schleppe dir übers Gesicht ziehen und den Völkern deine Blöße zeigen und den Königreichen deine Scham.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 3, 6, 'Ich will dich mit Unrat bewerfen und dich dadurch entehren und dich zu einem Schauspiel machen,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 3, 7, 'daß alle, die dich erblicken, vor dir fliehen und ausrufen: ›Zerstört ist Ninive! Wer möchte ihm Beileid bezeigen? Wo soll ich Tröster für dich ausfindig machen?‹«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 3, 8, 'Bist du etwa besser als No Ammon, die an den Nilarmen thronte, rings von Wasser umgeben? die Stadt, deren Außenwerk der Nilstrom bildete und deren Mauer aus Wasser bestand?');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 3, 9, 'Äthiopier waren ihre Stärke und Ägypter ohne Zahl; Put und die Libyer standen ihr zu Gebot.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 3, 10, 'Doch auch sie ist der Verbannung verfallen, ist in die Gefangenschaft gewandert, auch ihre Kinder sind an allen Straßenecken zerschmettert worden; über ihre Edlen warf man das Los, und alle ihre Großen wurden mit Ketten gefesselt.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 3, 11, 'So sollst auch du, Ninive, trunken werden, sollst umnachtet daliegen; auch du sollst Zuflucht vor dem Feinde suchen müssen!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 3, 12, 'Alle deine Festungen sind wie Feigenbäume mit Frühfeigen: werden sie geschüttelt, fallen sie dem, der essen will, in den Mund.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 3, 13, 'Wisse wohl: dein Kriegsvolk ist zu Weibern in deiner Mitte geworden; deinen Feinden stehen die Tore deines Landes weit offen, Feuer verzehrt deine Riegel.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 3, 14, 'Schöpfe dir Wasser für die (Zeit der) Belagerung, mache deine Festungswerke stärker! tritt in den Lehm und stampfe Ton, nimm die Ziegelform zur Hand!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 3, 15, 'Trotzdem wird das Feuer dich fressen, wird das Schwert dich vertilgen, dich verzehren wie die Freßgrillen verzehren. Magst du auch zahlreich sein wie ein Freßgrillenschwarm, zahllos wie ein Heuschreckenvolk,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 3, 16, 'magst du auch mehr Krämer haben, als Sterne am Himmel sind: – die Freßgrillen häuten sich und fliegen davon!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 3, 17, 'Deine Fürsten gleichen den Heuschrecken und deine Hofleute den Grillenschwärmen, die sich bei kaltem Wetter an den Mauern lagern; geht aber die Sonne auf, so fliegen sie davon, und niemand weiß, wo sie geblieben sind.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 3, 18, 'Entschlafen sind deine Hirten, König von Assyrien, entschlummert deine Großen! Dein Kriegsvolk hat sich auf den Bergen zerstreut, und niemand ist da, der es sammelt!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 3, 19, 'Keine Linderung gibt es für deine Wunde, unheilbar ist der Schlag, der dich getroffen! Alle, welche die Kunde von dir vernehmen, klatschen über dich in die Hände; denn über wen wäre nicht deine Bosheit ohne Unterlaß dahingegangen?');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 1, 1, '(Dies ist) der Gottesspruch, den der Prophet Habakuk geschaut hat.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 1, 2, 'Wie lange schon, HERR, rufe ich um Hilfe, ohne daß du es hörst! Wie lange schreie ich zu dir über Gewalttat, ohne daß du Hilfe bringst!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 1, 3, 'Warum läßt du mich Unheil schauen und muß ich Elend erblicken? Bedrückung und Gewalttat werden vor meinen Augen verübt, Streit entsteht, und Zwietracht erhebt sich!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 1, 4, 'Darum erstarrt das Gesetz, und das Recht tritt nimmermehr zutage; denn der Frevler umgarnt den Gerechten: darum tritt das Recht verdreht ans Licht.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 1, 5, 'Sehet euch um unter den Völkern und blickt umher: werdet starr und staunet! Denn ein Werk vollführt er in euren Tagen – ihr werdet es nicht glauben, wenn man es euch erzählt.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 1, 6, 'Denn wisset wohl: Ich bin es, der die Chaldäer auftreten läßt, das bitterböse und ungestüme Volk, das weit und breit die Lande durchzieht, um Wohnsitze zu erobern, die ihm nicht gehören.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 1, 7, 'Schrecklich und furchtbar ist es; sein Recht und seine Hoheit macht es überall zum Gesetz.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 1, 8, 'Schneller als die Panther sind ihre Rosse und kühner als Wölfe am Abend ihre Reiter: sie kommen aus weiter Ferne dahergesprengt, sie fliegen heran wie ein Adler, der sich auf den Fraß stürzt.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 1, 9, 'Sie gehen allesamt auf Gewalttat aus, das Streben ihres Angesichts ist nach vorwärts gerichtet, und Gefangene raffen sie zusammen wie Sand.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 1, 10, 'Der Könige spottet es, und Fürsten sind ihm ein Gelächter; ob jeder Festung lacht es, denn es schüttet einen Erdwall auf und erobert sie.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 1, 11, 'Dann wirbelt es davon wie der Wind und zieht weiter unter Freveltaten: diese seine Kraft gilt ihm als sein Gott.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 1, 12, 'Bist nicht du, HERR, von alters her mein Gott, mein Heiliger? Nein, wir werden nicht sterben! HERR, zum Gericht hast du ihn bestimmt und zum Boten der Züchtigung ihn bestellt.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 1, 13, 'Zu rein sind deine Augen, als daß du Böses ansehen könntest, und Gewalttat vermagst du nicht anzuschauen: warum siehst du denn den Ruchlosen ruhig zu und schweigst, wenn der Frevler den verschlingt, der besser ist als er?');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 1, 14, 'Du hast ja die Menschen so behandeln lassen wie die Fische im Meer, wie das Kriechgetier, das keinen Herrn über sich hat.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 1, 15, 'Sie alle hat er mit dem Hamen heraufgeholt, sie in sein Netz hineingerafft und in sein Garn eingefangen; darüber freut er sich und jubelt.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 1, 16, 'Darum opfert er seinem Netz und bringt seinem Garn Weihrauch dar, denn ihnen verdankt er seine reiche Beute und seine fette Speise.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 1, 17, 'Soll er aber deshalb sein Netz fort und fort entleeren und beständig Völker erbarmungslos morden?');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 2, 1, '»Auf meine Warte will ich treten und auf dem Wachtturm mich aufstellen und will Ausschau halten, um zu erfahren, was er mir sagen wird und welche Antwort ich auf meine Beschwerde erhalte.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 2, 2, 'Da antwortete mir der HERR folgendermaßen: »Schreibe die (folgende) Offenbarung nieder und grabe sie deutlich auf Tafeln ein, damit man sie mühelos lesen kann –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 2, 3, 'denn die (Erfüllung der) Offenbarung steht noch bis zu dem bestimmten Zeitpunkt aus, hastet jedoch dem Ziele zu und trügt nicht; wenn sie (mit ihrer Verwirklichung) auf sich warten läßt, so harre ihrer; denn sie trifft sicher ein und bleibt nicht aus.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 2, 4, '›Wisse wohl: vermessen, nicht aufrichtig ist er im Inneren gesinnt; der Gerechte aber wird infolge seines treuen Festhaltens das Leben haben.‹«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 2, 5, 'Und nunmehr – so steht’s: Der Wein trügt; der übermütige Mann, der ruht nicht, er, der seinen gierigen Rachen weit aufsperrt wie die Unterwelt und unersättlich ist wie der Tod, so daß er alle Völker an sich rafft und alle Völkerschaften in sich aufnimmt.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 2, 6, 'Werden diese nicht alle ein Spottlied über ihn anstimmen und eine Stichelrede anheben mit versteckten Anspielungen auf ihn und ausrufen: »Wehe dem, der da aufhäuft, was nicht ihm gehört – wie lange noch? –, und der Schuldenlast auf sich lädt!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 2, 7, 'Werden nicht plötzlich die von dir Mißhandelten sich erheben und die von dir Gepeinigten erwachen? Dann wirst du ihnen zur Plünderung werden!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 2, 8, 'Denn weil du viele Völker ausgeplündert hast, werden alle übrigen Völker dich wieder ausplündern wegen der Blutschuld an den Menschen und wegen deiner Gewalttaten an der Erde, an der Stadt und allen ihren Bewohnern!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 2, 9, 'Wehe dem, der unredlichen Gewinn einheimst in sein Haus, um sich ein Nest in der Höhe zu bauen, um gesichert zu sein gegen die Gewalt des Unglücks!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 2, 10, 'Du bist auf Schande für dein Haus bedacht gewesen, auf die Vertilgung vieler Völker, und hast Verschuldung auf dich selbst gebracht.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 2, 11, 'Denn die Steine werden aus der Mauer heraus schreien und die Balken aus dem Holzwerk in ihr Geschrei einstimmen!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 2, 12, 'Wehe dem, der Städte mit Blut baut und Burgen auf Ungerechtigkeit gründet!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 2, 13, 'Wisset wohl: vom HERRN der Heerscharen ist es so geordnet, daß Völker fürs Feuer sich mühen und Völkerschaften für nichts sich abarbeiten.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 2, 14, 'Denn die Erde wird voll werden von der Erkenntnis der Herrlichkeit des HERRN gleich den Wassern, die den Meeresgrund bedecken.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 2, 15, 'Wehe dem, der seine Genossen aus Schalen und Schläuchen trinken läßt und sie dadurch auch trunken macht, um sich am Anblick ihrer Nacktheit zu weiden!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 2, 16, 'Du hast dich an Schande gesättigt statt an Ehre: so trinke nun auch du, daß du taumelst! Der Becher in der Rechten des HERRN kommt jetzt an dich, so daß Schande auf deine Herrlichkeit fällt.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 2, 17, 'Denn der Frevel am Libanon wird auf dir lasten und das Gemetzel unter den Tieren dich in Schrecken setzen [wegen des vergossenen Menschenblutes und wegen deiner Gewalttaten an der Erde, an der Stadt und all ihren Bewohnern].');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 2, 18, 'Wehe dem, der zu einem Stück Holz sagt: ›Wache auf!‹ oder zu einem stummen Stein: ›Rege dich!‹ Kann solcher Götze Weisungen geben? Sieh doch: er ist mit Gold und Silber überzogen, und keine Spur von Odem findet sich in seinem Innern.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 2, 19, 'Was hat je ein Schnitzbild genützt, daß sein Bildner es geschnitzt hat? Was ein Gußbild und ein Lügengötze, daß sein Bildner Lust dazu gehabt hat, stumme Abgötter zu verfertigen? –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 2, 20, 'Aber der HERR ist in seinem heiligen Tempel: stille vor ihm, du ganze Erde!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 3, 1, 'Ein Gebet des Propheten Habakuk in bewegten Rhythmen:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 3, 2, 'HERR, ich habe deinen Ruf vernommen: ich bin voller Furcht! HERR, verwirkliche dein Werk inmitten der Jahre, mache es offenbar inmitten der Jahre! Im Zürnen bleibe des Erbarmens eingedenk!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 3, 3, 'Gott kommt von Theman her, der Heilige vom Gebirge Paran. (SELA.) Seine Erhabenheit breitet sich über den Himmel aus, und seine Herrlichkeit erfüllt die Erde.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 3, 4, 'Ein Glanz bricht hervor wie Sonnenlicht; Strahlen sprühen ihm zur Seite, und dort ist seine Kraft verborgen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 3, 5, 'Vor ihm her geht die Pest, und in seinem Gefolge zieht die Fieberglut einher.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 3, 6, 'Bleibt er stehen, so bringt er die Erde ins Wanken; schaut er aus, so schreckt er die Völker auf; es zerbersten die uralten Berge, die ewigen Hügel sinken zusammen: Bahnen wie einst in der Urzeit wandelt er.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 3, 7, 'Von Unheil bedrängt erblicke ich die Zelte Kusans; die Zeltbehänge im Lande Midian schwanken hin und her.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 3, 8, 'Ist denn der Grimm des HERRN gegen die Ströme entbrannt? Gilt etwa dein Zorn den Strömen oder dein Groll dem Meer, daß du (darüber) hinfährst auf deinem Gespann, deinem Siegeswagen?');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 3, 9, 'Blank entblößt ist dein Bogen, gesättigt mit Geschossen dein Köcher (SELA); du spaltest die Erde, daß Ströme hervorbrechen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 3, 10, 'Erblicken dich die Berge, so beben sie, Wasserfluten entströmen den Wolken; das Weltmeer läßt sein Tosen erschallen, hoch erhebt es seine Hände empor.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 3, 11, 'Sonne und Mond bleiben in ihrer Wohnung beim Leuchten deiner daherfliegenden Pfeile, beim Glanz deines blitzenden Speeres.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 3, 12, 'Im Zorn schreitest du über die Erde hin, im Grimm zerstampfst du die Heidenvölker.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 3, 13, 'Du ziehst aus, deinem Volk zu helfen, deinem Gesalbten Rettung zu bringen; du schlägst den Giebel ab vom Hause des Gottlosen und legst den Grund bloß bis an den Hals (SELA).');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 3, 14, 'Du durchbohrst mit deinen Geschossen das Haupt seiner Führer, die heranstürmen, um mich zu zerschmettern, die da ein Jubelgeschrei erheben, als wollten sie den Elenden im Verborgenen verschlingen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 3, 15, 'Du beschreitest das Meer mit deinen Rossen, da brausen die gewaltigen Wasser.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 3, 16, 'Vernommen habe ich’s, da erbebte mein Leib; ob der Kunde zitterten mir die Lippen; Todesangst drang mir in die Gebeine, und bis unten hin schauderte ich zusammen, weil ich ruhig warten soll auf den Tag der Drangsal, bis das Volk heranzieht, das uns angreifen soll. –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 3, 17, 'Denn wenn auch der Feigenbaum nicht zur Blüte kommt und die Reben keinen Ertrag geben, der Trieb des Ölbaums fehlschlägt und die Felder keine Nahrung liefern, das Kleinvieh aus den Hürden verschwunden ist und keine Rinder mehr in den Ställen stehen:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 3, 18, 'so will ich dennoch frohlocken im HERRN, will jubeln im Gott meines Heils!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 3, 19, 'Gott der HERR ist meine Kraft: er macht meine Füße (schnell) wie die der Hirsche und läßt mich einherschreiten auf meinen Höhen. Dem Musikmeister auf meinem Saitenspiel (vgl. Ps 4,1).');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 1, 1, '(Dies ist) das Wort des HERRN, das an Zephanja, den Sohn Kusis, des Sohnes Gedaljas, des Sohnes Amarjas, des Sohnes Hiskias, ergangen ist in den Tagen des judäischen Königs Josia, des Sohnes Amons.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 1, 2, '»Wegraffen, ja wegraffen will ich alles von der Oberfläche des Erdbodens hinweg!« – so lautet der Ausspruch des HERRN –;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 1, 3, '»wegraffen will ich Menschen und Vieh, wegraffen die Vögel des Himmels und die Fische des Meeres; ausrotten will ich die Gottlosen und die Menschen von der Oberfläche des Erdbodens vertilgen!« – so lautet der Ausspruch des HERRN.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 1, 4, '»Und ich will meine Hand ausstrecken gegen Juda und gegen alle Bewohner Jerusalems und will aus diesem Ort alles ausrotten, was vom Baalsdienst noch übrig ist, den Namen der Götzenpfaffen mitsamt den Priestern,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 1, 5, 'ebenso alle, die auf den Dächern das Heer des Himmels anbeten, und alle, die zwar den HERRN anbeten und bei ihm schwören, zugleich aber auch bei Milkom schwören;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 1, 6, 'und alle, die treulos vom HERRN abgefallen sind und die den HERRN nicht suchen und sich nicht um ihn kümmern!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 1, 7, '(Seid) still vor Gott dem HERRN! Denn nahe ist der Tag des HERRN; denn zugerichtet hat der HERR ein Opferfest, hat die von ihm Geladenen schon geweiht.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 1, 8, 'Am Tage des Opferfestes des HERRN aber wird es geschehen: »Da will ich ins Gericht gehen mit den Obersten und den Königssöhnen und mit allen, die sich in fremdländische Gewänder kleiden.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 1, 9, 'Auch will ich an jenem Tage mit allen denen ins Gericht gehen, die über die Schwelle hüpfen, mit allen, die das Haus ihres Herrn mit Gewalttat und Betrug anfüllen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 1, 10, 'An jenem Tage« – so lautet der Ausspruch des HERRN – »wird Wehgeschrei vom Fischtor her erschallen und Geheul aus der Neustadt und lautes Jammern von den Hügeln her.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 1, 11, 'Wehklagt, ihr Bewohner des Mörsertals! Denn zu Ende ist es mit der gesamten Kaufmannschaft, vernichtet sind alle Geldabwäger!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 1, 12, 'Und geschehen wird es zu jener Zeit, da will ich Jerusalem mit Leuchten absuchen und mit den Männern ins Gericht gehen, die sorglos auf ihren Hefen liegen, die da in ihrem Herzen denken: ›Der HERR tut weder Gutes noch Böses!‹');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 1, 13, 'Da werden dann ihre Güter der Plünderung und ihre Häuser der Verwüstung anheimfallen; und wenn sie sich (wieder) Häuser bauen, sollen sie nicht darin wohnen und, wenn sie Weinberge angelegt haben, keinen Wein davon trinken.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 1, 14, 'Nahe ist der große Tag des HERRN, nahe ist er und eilt gar schnell heran. Horch, der Tag des HERRN, der bittere: da schreit auch der tapferste Krieger auf!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 1, 15, 'Ein Tag des Zorns ist dieser Tag, ein Tag der Angst und Drangsal, ein Tag der Trümmer und der Zertrümmerung, ein Tag der Finsternis und tiefen Dunkels, ein Tag des Gewölks und der Wolkennacht,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 1, 16, 'ein Tag des Posaunenschalls und des Lärmblasens gegen die festen Städte und gegen die hochragenden Zinnen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 1, 17, 'Da will ich die Menschen ängstigen, daß sie einhergehen wie die Blinden, weil sie gegen den HERRN gesündigt haben: ihr Blut soll wie Staub hingeschüttet werden und ihr Fleisch wie Kot (zertreten werden).');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 1, 18, 'Weder ihr Silber noch ihr Gold wird sie am Tage des Zorns des HERRN zu retten vermögen, sondern vom Feuer seines Eifers soll die ganze Erde verzehrt werden; denn Vernichtung, ja jähen Untergang wird er allen Bewohnern der Erde bereiten.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 2, 1, 'Gehet in euch und nehmt euch zusammen, du schamloses Volk,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 2, 2, 'ehe der göttliche Ratschluß sich verwirklicht – wie Spreu fährt der Tag daher –, ehe die Zornglut des HERRN über euch hereinbricht, ehe der Tag des göttlichen Zorns euch ereilt!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 2, 3, 'Suchet den HERRN, alle ihr Demütigen im Lande, die ihr sein Recht geübt habt! Trachtet nach Gerechtigkeit, trachtet nach Demut: vielleicht werdet ihr Bergung finden am Zornestage des HERRN!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 2, 4, 'Denn Gaza wird öde werden und Askalon zur Wüste; Asdod wird am hellen Mittag entvölkert und Ekron von Grund aus zerstört werden.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 2, 5, 'Wehe den Bewohnern des Meeresstrandes, dem Kretervolk! Gegen euch lautet das Drohwort des HERRN: »Kanaan, Land der Philister! Ich will dich so zugrunde richten, daß kein Bewohner mehr in dir übrigbleibt!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 2, 6, 'Der Landstrich am Meer soll zu Triften für Hirten und zu Hürden für Kleinvieh werden;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 2, 7, 'und der Landstrich (am Meer) soll dem Überrest des Hauses Juda zufallen: die sollen auf ihm weiden und sich abends in den Häusern von Askalon lagern, wenn der HERR, ihr Gott, sich ihrer annehmen und ihr Schicksal wenden wird. –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 2, 8, '»Gehört habe ich die Schmähung der Moabiter und die Lästerreden der Ammoniter, wie sie mein Volk geschmäht und gegen dessen Gebiet großgetan haben.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 2, 9, 'Darum, so wahr ich lebe!« – so lautet der Ausspruch des HERRN der Heerscharen, des Gottes Israels –: »es soll den Moabitern ergehen wie Sodom und den Ammonitern wie Gomorrha! Ein Besitztum der Nesseln sollen sie werden und eine Salzgrube und eine Wüstenei für ewige Zeiten! Der Überrest meines Volkes soll sie ausplündern, und die von meinem Volk Übriggebliebenen sollen sie beerben!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 2, 10, 'So soll es ihnen ergehen für ihren Hochmut, weil sie das Volk des HERRN der Heerscharen geschmäht und ihm gegenüber großgetan haben.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 2, 11, 'Furchtbar wird sich der HERR an ihnen erweisen; denn er wird allen Göttern der Erde ein Ende machen, und alle Meeresländer der Heiden werden ihn anbeten, ein jeder von seiner Wohnstätte aus. –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 2, 12, '»Auch ihr Äthiopier werdet von seinem Schwert erschlagen werden!« –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 2, 13, 'Hierauf wird er seine Hand gegen Norden ausstrecken, wird Assyrien vernichten und Ninive zur Wüste machen, zu dürrem Lande wie die Steppe.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 2, 14, 'Alsdann werden Herden sich mitten darin lagern, Tiere von aller Art in Menge: Pelikane und Igel werden auf ihren Säulenknäufen Nachtruhe halten; das Käuzlein wird in der Fensterhöhle singen, Raben auf der Schwelle sitzen; denn Er hat das Zedergetäfel abgerissen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 2, 15, 'So wird es der fröhlichen Stadt ergehen, die in Sicherheit thronte, die da bei sich dachte: »Ich bin’s und keine andere sonst!« Wie ist sie nun zur Wüstenei geworden, zur Lagerstätte für wilde Tiere! Wer immer an ihr vorübergeht, zischt über sie und schüttelt seine Hand.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 3, 1, 'Wehe der ungehorsamen und beschmutzten, der gewalttätigen Stadt!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 3, 2, 'Sie hört auf keine Warnung, nimmt keine Zurechtweisung an; auf den HERRN vertraut sie nicht, und ihrem Gott naht sie sich nicht.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 3, 3, 'Ihre Fürsten in ihrer Mitte sind brüllende Löwen, ihre Richter Abendwölfe, die (von ihrem Raube) nichts für den Morgen übriglassen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 3, 4, 'Ihre Propheten sind leichtfertige, betrügerische Menschen; ihre Priester entweihen das Heilige, tun dem Gesetz Gewalt an.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 3, 5, 'Der HERR aber ist gerecht in ihrer Mitte, er tut nichts Unrechtes; Morgen für Morgen läßt er sein Recht ans Licht treten, ohne es an etwas fehlen zu lassen; aber der Ungerechte weiß nichts von Scham.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 3, 6, '»Ich habe Völker ausgerottet, zerstört sind ihre Mauerzinnen; ich habe ihre Landstraßen öde gemacht, so daß niemand mehr auf ihnen wandert; verheert sind ihre Städte, menschenleer, ohne Bewohner.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 3, 7, 'Ich dachte: ›Nun wird sie mich gewiß fürchten, wird Zurechtweisung annehmen, damit ihre Wohnstätte nicht verheert wird und nicht alles eintritt, was ich ihr angedroht habe‹; doch nur um so eifriger sind sie bemüht gewesen, in allen Stücken ihr böses Tun noch zu verschlimmern.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 3, 8, '»Darum harret meiner« – so lautet der Ausspruch des HERRN – »auf den Tag, an dem ich als Zeuge auftrete! Darin besteht nämlich mein Gericht, daß ich Völker versammle und Königreiche zusammenbringe, um meinen Grimm über sie auszugießen, die ganze Glut meines Zorns; denn durch das Feuer meines Eifers soll die ganze Erde verzehrt werden!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 3, 9, 'Ja, alsdann will ich den Völkern andere, reine Lippen schaffen, damit sie allesamt den Namen des HERRN anrufen und ihm einmütig dienen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 3, 10, 'Von jenseits der Ströme Äthiopiens werden sie, meine Anbeter, die Schar meiner Zerstreuten mir als Geschenk darbringen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 3, 11, 'An jenem Tage wirst du (Jerusalem) dich nicht mehr zu schämen brauchen wegen aller deiner Missetaten, durch die du dich gegen mich versündigt hast; denn alsdann werde ich aus deiner Mitte alle wegschaffen, die übermütig in dir frohlocken, und du wirst dich hinfort auf meinem heiligen Berge nicht mehr überheben.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 3, 12, 'Und ich werde in deiner Mitte ein demütiges und geringes Volk übriglassen, das sein Vertrauen auf den Namen des HERRN setzt.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 3, 13, 'Die dann von Israel noch übrig sind, werden nichts Unrechtes mehr tun und keine Lüge reden, und in ihrem Munde man wird keine trügerische Zunge mehr finden, sondern sie werden eine ruhig weidende und sich lagernde Herde bilden, die von niemand aufgeschreckt wird.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 3, 14, 'Juble, Tochter Zion! Jauchzet, ihr vom Hause Israel! Freue dich und frohlocke von ganzem Herzen, Tochter Jerusalem!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 3, 15, 'Aufgehoben hat der HERR die über dich verhängten Gerichte und deine Feinde hinweggefegt! Israels König, der HERR, weilt in deiner Mitte: du wirst hinfort kein Unheil mehr sehen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 3, 16, 'An jenem Tage wird man Jerusalem zurufen: »Fürchte dich nicht, Zion! Laß deine Hände nicht verzagt sinken!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 3, 17, 'Der HERR, dein Gott, ist in deiner Mitte, ein Held, der Rettung schafft; er hat seine Freude an dir mit Entzücken, erneuert dich in seiner Liebe, frohlockt über dich mit Jubel.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 3, 18, 'Die jetzt fern von der Festversammlung Trauernden will ich sammeln: sie stammen ja von dir, auf denen jetzt Schmach lastet.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 3, 19, 'Wisse wohl: ich will zu jener Zeit mit all deinen Bedrückern ins Gericht gehen, dagegen den Hinkenden helfen und die Zerstreuten sammeln und will sie zur Ehre und zum Ruhm machen in allen Ländern, wo sie jetzt verachtet sind.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 3, 20, 'Zu jener Zeit will ich euch heimführen und zu jener Zeit euch sammeln; denn ich will euch zum Ruhm und zur Ehre unter allen Völkern der Erde machen, wenn ich euer Geschick vor euren Augen wende: der HERR hat es verheißen.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 1, 1, 'Im zweiten Regierungsjahre des Königs Darius, am ersten Tage des sechsten Monats, erging das Wort des HERRN durch den Propheten Haggai an Serubbabel, den Sohn Sealthiels, den Statthalter von Juda, und an den Hohenpriester Josua, den Sohn Jozadaks, folgendermaßen:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 1, 2, '»So hat der HERR der Heerscharen gesprochen: Dieses Volk da sagt: ›Die Zeit, den Tempel des HERRN wieder aufzubauen, ist jetzt noch nicht gekommen!‹«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 1, 3, 'Daher erging das Wort des HERRN durch den Propheten Haggai folgendermaßen:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 1, 4, '»Ist es etwa für euch selbst an der Zeit, in euren getäfelten Häusern zu wohnen, während dieses Haus in Trümmern daliegt?«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 1, 5, '»Und nun« – so spricht der HERR der Heerscharen – »achtet wohl darauf, wie es euch bisher ergangen ist!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 1, 6, 'Ihr habt reichlich ausgesät, aber kärglich eingebracht; ihr habt wohl zu essen, aber es reicht nicht zum Sattwerden; ihr trinkt und stillt doch den Durst nicht; ihr habt wohl etwas zum Anziehen, aber keiner wird recht warm davon; und wer um Lohn arbeitet, der sammelt den Lohn in einen löcherigen Beutel.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 1, 7, 'So spricht der HERR der Heerscharen: »Achtet wohl darauf, wie es euch bisher ergangen ist!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 1, 8, 'Steigt ins Gebirge hinauf, schafft Holz herbei und bauet den Tempel wieder auf, damit ich meine Freude daran habe und mich in meiner Herrlichkeit zeige! – so spricht der HERR.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 1, 9, 'Ihr hattet auf viel gerechnet, aber es wurde wenig daraus; und wenn ihr das eingebracht hattet, so blies ich es weg. Warum das?« – so lautet der Ausspruch des HERRN der Heerscharen. »Um meines Hauses willen, das in Trümmern daliegt, während ein jeder von euch an seinem eigenen Hause seine Freude hat.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 1, 10, 'Darum hat der Himmel seinen Tau über euch zurückgehalten und die Erde euch ihren Ertrag versagt;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 1, 11, 'und ich habe Dürre über das Land kommen lassen und über die Berge, über das Getreide, den Most und das Öl, kurz über alles, was der Erdboden hervorbringt, auch über die Menschen und das Vieh und über allen Ertrag der Hände.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 1, 12, 'Da hörten Serubbabel, der Sohn Sealthiels, und der Hohepriester Josua, der Sohn Jozadaks, und alle, die vom Volk noch übrig waren, auf die Mahnung des HERRN, ihres Gottes, nämlich auf die Worte des Propheten Haggai, der, wie sie erkannten, vom HERRN, ihrem Gott, zu ihnen gesandt worden war; ja, das Volk geriet in Furcht vor dem HERRN.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 1, 13, 'Da machte aber Haggai, der Bote des HERRN, kraft göttlicher Botschaft dem Volk folgende Eröffnung: »›Ich bin mit euch!‹ – so lautet der Ausspruch des HERRN.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 1, 14, 'Hierauf erweckte der HERR den Geist Serubbabels, des Sohnes Sealthiels, des Statthalters von Juda, und den Eifer des Hohenpriesters Josua, des Sohnes Jozadaks, und den Eifer aller vom Volk Übriggebliebenen, so daß sie kamen und die Arbeit am Tempel des HERRN der Heerscharen, ihres Gottes, in Angriff nahmen');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 1, 15, 'am vierundzwanzigsten Tage des sechsten Monats. Im zweiten Regierungsjahr des Königs Darius,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 2, 1, 'am einundzwanzigsten Tage des siebten Monats erging das Wort des HERRN durch den Propheten Haggai folgendermaßen:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 2, 2, '»Sage doch zu Serubbabel, dem Sohne Sealthiels, dem Statthalter von Juda, und zu dem Hohenpriester Josua, dem Sohne Jozadaks, und zu allen vom Volk Übriggebliebenen folgendes:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 2, 3, '›Wer ist unter euch noch am Leben, der diesen Tempel in seiner früheren Herrlichkeit gesehen hat, und wie seht ihr ihn heute? Nicht wahr? Wie nichts kommt er euch vor.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 2, 4, 'Nun aber sei getrost, Serubbabel!‹ – so lautet der Ausspruch des HERRN – ›und sei getrost, Josua, Sohn Jozadaks, du Hoherpriester, und seid getrost ihr alle, die ihr das Volk des Landes bildet‹ – so lautet der Ausspruch des HERRN –, ›und arbeitet, denn ich bin mit euch!‹ – so lautet der Ausspruch des HERRN der Heerscharen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 2, 5, '›Die Verheißung, die ich euch bei eurem Auszug aus Ägypten feierlich gegeben habe, bleibt bestehen, und mein Geist waltet in eurer Mitte: fürchtet euch nicht!‹');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 2, 6, 'Denn so spricht der HERR der Heerscharen: ›Nur noch [einmal] eine kurze Zeit währt es; da werde ich den Himmel und die Erde, das Meer und das feste Land erschüttern,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 2, 7, 'und ich werde alle Völker in Bewegung setzen, daß die Kostbarkeiten aller Heidenvölker herbeigebracht werden; und ich will dieses Haus mit Herrlichkeit erfüllen!‹ – so spricht der HERR der Heerscharen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 2, 8, '›Mein ist das Silber und mein das Gold‹ – so lautet der Ausspruch des HERRN der Heerscharen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 2, 9, '›Größer wird die künftige Herrlichkeit dieses Tempels sein, als die des ersten gewesen ist‹ – so spricht der HERR der Heerscharen –, ›und an dieser Stätte will ich Frieden spenden‹ – so lautet der Ausspruch des HERRN der Heerscharen.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 2, 10, 'Am vierundzwanzigsten Tage des neunten Monats, im zweiten Regierungsjahre des Darius, erging das Wort des HERRN durch den Propheten Haggai folgendermaßen:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 2, 11, '»So spricht der HERR der Heerscharen: ›Erbitte dir doch von den Priestern Belehrung über folgende Frage:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 2, 12, 'Wenn jemand heiliges Fleisch im Zipfel seines Gewandes trägt und mit seinem Zipfel Brot oder Gekochtes, Wein, Öl oder sonst irgend etwas Genießbares berührt: wird dieses dadurch heilig?‹« Da gaben die Priester zur Antwort: »Nein!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 2, 13, 'Nun fragte Haggai weiter: »Wenn aber ein durch eine Leiche Verunreinigter irgendeins von derartigen Dingen berührt, wird es dadurch unrein?« Da gaben die Priester zur Antwort: »Ja, es wird unrein!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 2, 14, 'Da erklärte Haggai folgendes: »›Ebenso steht es um diese Leute, und ebenso ist dieses Volk da in meinen Augen beschaffen‹ – so lautet der Ausspruch des HERRN –, ›und ebenso steht es mit allem Tun ihrer Hände und mit dem, was sie mir dort als Opfer darbringen: es ist unrein!‹«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 2, 15, '»Nun aber richtet doch eure Aufmerksamkeit vom heutigen Tage an (auf die Zeit) rückwärts! Bevor man Stein auf Stein am Tempel des HERRN gelegt hat:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 2, 16, 'wie ist es euch da ergangen? Kam man damals zu einem Garbenhaufen von (vermutlich) zwanzig Scheffeln, so wurden es nur zehn; und kam einer zur Kelter in der Erwartung, fünfzig Eimer aus ihr zu schöpfen, so wurden es nur zwanzig.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 2, 17, '›Ich habe euch mit Getreidebrand und Vergilben geschlagen und mit Hagel den Ertrag aller eurer Feldarbeit, und doch seid ihr nicht zu mir umgekehrt!‹ – so lautet der Ausspruch des HERRN.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 2, 18, 'Nun aber gebt acht auf das, was in der Folgezeit vom heutigen Tage an geschehen wird, nämlich vom vierundzwanzigsten Tage des neunten Monats an, von dem Tage an, wo der Grundstein zum Tempel des HERRN gelegt worden ist. Gebt acht darauf,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 2, 19, 'ob die Aussaat noch weiterhin im Speicher liegen bleibt und ob der Weinstock und Feigenbaum, die Granate und der Ölbaum auch fürderhin nicht tragen! Von diesem Tage an werde ich segnen.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 2, 20, 'Hierauf erging das Wort des HERRN zum zweitenmal an Haggai am vierundzwanzigsten Tage des (gleichen) Monats folgendermaßen:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 2, 21, '»Sage zu Serubbabel, dem Statthalter von Juda, folgendes: ›Ich werde den Himmel und die Erde erschüttern');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 2, 22, 'und die Throne der Könige umstürzen und die Macht der heidnischen Königreiche vernichten, und zwar werde ich die Streitwagen umstürzen samt denen, die darauf fahren, und es sollen die Rosse samt ihren Reitern zu Boden stürzen, einer durch das Schwert des andern (fallen).');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 2, 23, 'An jenem Tage‹ – so lautet der Ausspruch des HERRN der Heerscharen – ›will ich dich, Serubbabel, Sohn Sealthiels, nehmen und dich zu meinem Knecht machen‹ – so lautet der Ausspruch des HERRN – ›und dich wie einen Siegelring halten; denn dich habe ich erwählt!‹ – so lautet der Ausspruch des HERRN der Heerscharen.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 1, 1, 'Im achten Monat, im zweiten Regierungsjahre des Darius, erging das Wort des HERRN an den Propheten Sacharja, den Sohn Berechjas, des Sohnes Iddos, folgendermaßen:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 1, 2, '»Der HERR ist gegen eure Väter schwer erzürnt gewesen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 1, 3, 'Nun aber sage zu ihnen: ›So hat der HERR der Heerscharen gesprochen: Kehrt um zu mir‹ – so lautet der Ausspruch des HERRN der Heerscharen –, ›so will auch ich wieder zu euch umkehren‹ – spricht der HERR der Heerscharen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 1, 4, '›Seid nicht wie eure Väter, denen die früheren Propheten zwar die Mahnung zugerufen haben: So hat der HERR der Heerscharen gesprochen: Kehrt doch um von eurem bösen Wandel und von eurem bösen Tun!, aber sie haben nicht gehorcht und nicht auf mich geachtet!‹ – so lautet der Ausspruch des HERRN.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 1, 5, '›Wo sind nun eure Väter? Und können die Propheten ewig leben?');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 1, 6, 'Doch meine Drohworte und meine Ratschlüsse, deren Verkündigung ich meinen Knechten, den Propheten, geboten hatte, sind die nicht bei euren Vätern eingetroffen, so daß sie in sich gingen und bekannten: ›Wie der HERR der Heerscharen sich vorgenommen hatte, mit uns nach unserm Wandel und nach unserm ganzen Tun zu verfahren, so ist er wirklich mit uns verfahren‹?«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 1, 7, 'Am vierundzwanzigsten Tage des elften Monats – das ist der Monat Sebat –, im zweiten Regierungsjahre des Darius, erging das Wort des HERRN an den Propheten Sacharja, den Sohn Berechjas, des Sohnes Iddos, folgendermaßen:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 1, 8, 'Ich hatte zur Nachtzeit ein Gesicht: ich sah einen Mann auf einem rotbraunen Roß reiten; der hielt zwischen den Myrten, die im Talgrund stehen, und hinter ihm befanden sich (noch andere) Rosse, rotbraune, fuchsrote, (schwarze) und weiße.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 1, 9, 'Als ich nun fragte: »Mein Herr, was bedeuten diese?«, antwortete mir der Engel, der mit mir redete: »Ich will dich schauen lassen, was diese da bedeuten.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 1, 10, 'Da nahm der Mann, der zwischen den Myrten hielt, das Wort und sagte: »Das sind die, welche der HERR ausgesandt hat, um die Erde zu durchstreifen.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 1, 11, 'Da erstatteten sie dem Engel des HERRN, der zwischen den Myrten hielt, Bericht mit den Worten: »Wir haben die Erde durchstreift und festgestellt, daß die ganze Erde sich in tiefster Ruhe befindet.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 1, 12, 'Da nahm der Engel des HERRN das Wort und fragte: »O HERR der Heerscharen, wann willst du dich endlich Jerusalems und der Städte Judas erbarmen, denen du nun schon siebzig Jahre lang gezürnt hast?«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 1, 13, 'Da antwortete der HERR dem Engel, der mit mir redete, freundliche, trostreiche Worte.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 1, 14, 'Hierauf sagte der Engel, der mit mir redete, zu mir: »Mache folgende Verkündigung bekannt: ›So hat der HERR der Heerscharen gesprochen: Ich bin mit großem Eifer für Jerusalem und für Zion erfüllt');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 1, 15, 'und hege heftigen Zorn gegen die sorglos dahinlebenden Heidenvölker, die, während ich (über: Israel) ein wenig erzürnt war, ihrerseits zum Unheil mitgeholfen haben.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 1, 16, 'Darum spricht der HERR also: Ich habe mich Jerusalem voll Erbarmens wieder zugewandt: mein Tempelhaus soll in ihm wieder aufgebaut werden‹ – so lautet der Ausspruch des HERRN der Heerscharen –, ›und die Meßschnur soll über Jerusalem ausgespannt werden.‹');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 1, 17, 'Weiter mache noch folgendes bekannt: ›So hat der HERR der Heerscharen gesprochen: Aufs neue sollen meine Städte von Gutem überfließen, und der HERR wird Zion aufs neue trösten und Jerusalem wiederum erwählen.‹«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 2, 1, 'Als ich dann aufblickte und hinschaute, sah ich vier Hörner.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 2, 2, 'Als ich nun den Engel, der mit mir redete, fragte: »Was haben diese zu bedeuten?«, antwortete er mir: »Das sind die Hörner, welche Juda, Israel und Jerusalem zerstreut haben.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 2, 3, 'Hierauf ließ der HERR mich vier Schmiede schauen,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 2, 4, 'und als ich fragte: »Was wollen diese hier tun?«, gab er mir zur Antwort: »Jenes sind die Hörner, welche Juda dermaßen zerstreut haben, daß es sein Haupt nicht mehr erheben konnte; nun aber sind diese gekommen, um sie in Schrecken zu setzen und die Hörner der Völker abzuschlagen, die ihr Horn gegen das Land Juda erhoben haben, um es zu zerstreuen.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 2, 5, 'Als ich dann (abermals) aufblickte und hinschaute, sah ich einen Mann, der eine Meßschnur in der Hand hielt.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 2, 6, 'Als ich ihn nun fragte: »Wohin gehst du?«, antwortete er mir: »Ich soll Jerusalem ausmessen, um festzustellen, wie groß seine Breite und wie groß seine Länge ist.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 2, 7, 'Da stand auf einmal der Engel da, der mit mir redete; und ein anderer Engel trat hervor, ihm entgegen,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 2, 8, 'und er sagte zu diesem: »Laufe hin und sage dem jungen Manne dort folgendes: ›Eine offene Stadt soll Jerusalem bilden wegen der Menge der Menschen und des Viehs in seinem Innern;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 2, 9, 'ich selbst aber‹ – so lautet der Ausspruch des HERRN – ›will ihm ringsum eine feurige Mauer sein und ihm zur Verherrlichung in seiner Mitte gereichen.‹«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 2, 10, '»Auf, auf! Fliehet aus dem Lande des Nordens!« – so lautet der Ausspruch des HERRN –; »denn nach allen vier Windrichtungen will ich euch zersprengen« – so lautet der Ausspruch des HERRN.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 2, 11, '»Auf! Nach Zion rettet euch, die ihr noch bei der Tochter Babel wohnt!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 2, 12, 'Denn so hat der HERR der Heerscharen gesprochen: »Nach Herrlichem hat er mich gesandt zu den Heidenvölkern, die euch geplündert haben; denn wer euch antastet, tastet seinen Augapfel an.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 2, 13, 'Denn wisset wohl: Ich werde meine Hand gegen sie schwingen, daß sie denen zur Beute werden sollen, die jetzt ihre Knechte sind«; dann werdet ihr auch erkennen, daß der HERR der Heerscharen es ist, der mich gesandt hat. –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 2, 14, '»Juble und freue dich, Tochter Zion! Denn wisse wohl: Ich komme und nehme Wohnung in deiner Mitte« – so lautet der Ausspruch des HERRN.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 2, 15, '»Da werden sich dann an jenem Tage viele Völker an den HERRN anschließen und mir als Volk angehören; und ich werde in deiner Mitte Wohnung nehmen«; dann wirst du auch erkennen, daß der HERR der Heerscharen es ist, der mich zu dir gesandt hat.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 2, 16, 'Der HERR aber wird Juda als sein Erbteil auf dem heiligen Boden in Besitz nehmen und Jerusalem wiederum erwählen. –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 2, 17, 'Stille sei alles Fleisch vor dem HERRN! Denn er hat sich (bereits) aufgemacht aus seiner heiligen (himmlischen) Wohnstätte.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 3, 1, 'Hierauf ließ er mich den Hohenpriester Josua schauen, wie er vor dem Engel des HERRN stand, während der Satan sich zu seiner Rechten stellte, um ihn anzuklagen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 3, 2, 'Da sagte der Engel des HERRN zum Satan: »Der HERR wolle dich schelten, Satan! Ja, der HERR, der sich Jerusalem erwählt hat, möge dir Schweigen gebieten! Ist dieser (Mann) nicht ein aus dem Feuer herausgerissenes Brandscheit?«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 3, 3, 'Josua war aber mit unsauberen Gewändern bekleidet, während er vor dem Engel stand.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 3, 4, 'Der nahm nun das Wort und gab den vor ihm stehenden (Dienern) die Weisung: »Ziehet ihm die schmutzigen Kleider aus!« Zu ihm aber sagte er: »Siehe, ich habe deine Verschuldung von dir weggenommen und lasse dir Prachtgewänder anlegen!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 3, 5, 'Hierauf befahl er: »Man setze ihm auch einen reinen Kopfbund aufs Haupt!« Da setzten sie ihm den reinen Kopfbund aufs Haupt und legten ihm die Prachtgewänder an, während der Engel des HERRN neben ihm stand.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 3, 6, 'Hierauf gab der Engel des HERRN vor Josua folgende feierliche Erklärung ab:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 3, 7, '»So spricht der HERR der Heerscharen: ›Wenn du auf meinen Wegen wandelst und meinen Dienst gewissenhaft versiehst, sollst du sowohl mein Haus verwalten als auch über meine Vorhöfe die Aufsicht führen, und ich will dir freien Zutritt zu mir gewähren unter diesen, die hier (als Diener vor mir) stehen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 3, 8, 'Vernimm es doch, Josua, du Hoherpriester! Du und deine Amtsbrüder, die vor dir ihre Sitze haben (im Priesterrat), ihr seid Männer, die ein Vorzeichen bedeuten; denn wisse wohl: Ich will meinen Knecht, ›Sproß‹ genannt, kommen lassen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 3, 9, 'Denn siehe, der Stein, den ich vor Josua hingestellt habe – auf diesen einen Stein sind sieben Augen gerichtet –: auf diesen Stein will ich selbst nunmehr seine Inschrift eingraben‹ – so lautet der Ausspruch des HERRN der Heerscharen – ›und will die Verschuldung dieses Landes an einem Tage hinwegschaffen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 3, 10, 'An jenem Tage‹ – so lautet der Ausspruch des HERRN der Heerscharen – ›werdet ihr einer den andern zu Gaste laden unter seinen Weinstock und unter seinen Feigenbaum.‹«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 4, 1, 'Da kam der Engel, der mit mir redete, zurück und weckte mich auf wie einen, der aus seinem Schlaf aufgeweckt wird,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 4, 2, 'und er fragte mich: »Was siehst du?« Ich antwortete: »Ich sehe, da steht ein Leuchter ganz von Gold, und ein Ölbehälter befindet sich oben darauf, und sieben Lampen sind an ihm und sieben Gießröhren für die Lampen, die sich an ihm befinden;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 4, 3, 'und neben ihm stehen zwei Ölbäume, einer zu seiner Rechten und einer links von ihm.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 4, 4, 'Da hob ich an und richtete an den Engel, der mit mir redete, die Frage: »Mein Herr, was soll dies alles bedeuten?«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 4, 5, 'Da gab mir der Engel, der mit mir redete, folgende Antwort: »Du weißt also nicht, was dies dort bedeutet?« Als ich nun antwortete: »Nein, mein Herr«,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 4, 6, 'gab er mir folgende Auskunft: »So lautet das Wort des HERRN an Serubbabel: ›Nicht durch Heeresmacht und nicht durch Gewalt (geschieht’s), sondern durch meinen Geist!‹ – so spricht der HERR der Heerscharen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 4, 7, '›Wer bist du, großer Berg? Vor Serubbabel sollst du zur Ebene werden! Er wird den Giebelstein an Ort und Stelle bringen unter dem Jubelruf: ›Heil, Heil sei ihm!‹«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 4, 8, 'Weiter erging das Wort des HERRN an mich folgendermaßen:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 4, 9, '»Die Hände Serubbabels haben den Grundstein zu diesem Hause gelegt, und seine Hände werden es auch vollenden; dann wirst du auch erkennen, daß der HERR der Heerscharen es ist, der mich zu euch gesandt hat.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 4, 10, 'Denn wer immer den Tag der geringen Anfänge verachtet hat, der wird mit Freuden den Bleistein in der Hand Serubbabels sehen. Diese sieben (Lampen) aber sind die Augen des HERRN, die über die ganze Erde schweifen.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 4, 11, 'Hierauf richtete ich die Frage an ihn: »Was bedeuten denn diese beiden Ölbäume rechts und links von dem Leuchter?«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 4, 12, 'Und noch eine andere Frage richtete ich an ihn, nämlich: »Was haben die beiden Olivenzweige zu bedeuten, die sich neben den beiden goldenen Röhren befinden, welche das Gold(öl) von oben herableiten?«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 4, 13, 'Da antwortete er mir: »Du weißt also nicht, was diese bedeuten?« Als ich ihm nun erwiderte: »Nein, mein Herr«,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 4, 14, 'sagte er: »Das sind die beiden Söhne des Öls, die (als Diener) vor dem Herrn der ganzen Erde stehen.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 5, 1, 'Als ich dann wieder aufblickte und hinschaute, sah ich, wie eine Schriftrolle geflogen kam,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 5, 2, 'und auf seine Frage: »Was siehst du?« antwortete ich: »Ich sehe eine Schriftrolle fliegen, zwanzig Ellen lang und zehn Ellen breit.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 5, 3, 'Da sagte er zu mir: »Das ist der Fluch, der über das ganze weite Land ergeht; denn jeder Dieb wird nach der Bestimmung, die auf der einen Seite der Rolle geschrieben steht, weggefegt werden, und jeder Meineidige wird nach der Bestimmung, die auf der andern Seite der Rolle geschrieben steht, weggefegt werden.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 5, 4, '›Ich habe den Fluch deshalb ausgehen lassen‹ – so lautet der Ausspruch des HERRN der Heerscharen –, ›damit er in das Haus des Diebes und in das Haus dessen, der bei meinem Namen falsch geschworen hat, eindringt und im Innern seines Hauses sich festsetzt, bis er es mitsamt seinem Holzwerk und seinen Steinen vernichtet hat.‹«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 5, 5, 'Hierauf trat der Engel, der mit mir redete, wieder hervor und sagte zu mir: »Blicke doch in die Höhe und sieh, was das ist, das dort zum Vorschein kommt!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 5, 6, 'Als ich nun fragte: »Was ist das?«, antwortete er: »Das ist das große Getreidemaß, das zum Vorschein kommt«; dann fuhr er fort: »Dies ist ihre Verschuldung im ganzen Lande!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 5, 7, 'Da hob sich auf einmal ein schwerer Bleideckel (von dem Getreidemaß) empor, und ein einzelnes Weib saß dort im Innern des Getreidemaßes.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 5, 8, 'Da sagte er: »Das ist die Gottlosigkeit!« Dann stieß er das Weib wieder in das Getreidemaß zurück und warf die Bleiplatte wieder auf ihre Öffnung.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 5, 9, 'Als ich dann wieder aufblickte und hinschaute, sah ich zwei Weiber zum Vorschein kommen, in deren Flügeln sich Wind befand; sie hatten nämlich Flügel wie Storchenflügel; die hoben das Getreidemaß empor (und trugen es) zwischen Erde und Himmel (davon).');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 5, 10, 'Als ich nun den Engel, der mit mir redete, fragte: »Wohin bringen diese das Getreidemaß?«,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 5, 11, 'antwortete er mir: »Es soll ihr ein Haus im Lande Babylonien gebaut werden, und, wenn dieses fertig ist, soll es dort auf dem ihr gebührenden Platz niedergesetzt werden.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 6, 1, 'Als ich dann abermals aufblickte und hinschaute, sah ich vier Wagen zwischen zwei Bergen hervorkommen; die Berge aber waren von Erz.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 6, 2, 'Am ersten Wagen waren rotbraune Rosse, am zweiten Wagen schwarze Rosse,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 6, 3, 'am dritten Wagen weiße Rosse und am vierten Wagen scheckige Rosse.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 6, 4, 'Als ich nun an den Engel, der mit mir redete, die Frage richtete: »Was haben diese da zu bedeuten, mein Herr?«,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 6, 5, 'gab mir der Engel zur Antwort: »Das sind die vier Winde des Himmels, die ausfahren, nachdem sie sich dem Herrn der ganzen Erde vorgestellt haben.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 6, 6, 'Der Wagen mit den schwarzen Rossen geht nach dem Lande im Norden, und das weiße Gespann fährt nach dem Osten; die scheckigen Rosse fahren nach dem Lande im Süden;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 6, 7, 'und die rotbraunen ziehen nach dem Lande im Westen aus und beabsichtigen auf ihrer Fahrt die Erde zu durchstreifen.« Als er ihnen dann zugerufen hatte: »Auf! Durchstreift die Erde!«, zogen sie auf der Erde umher.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 6, 8, 'Dann rief er mir noch laut die Worte zu: »Wisse wohl: die, welche nach dem Lande im Norden ausgezogen sind, lassen meinen Geist im Lande des Nordens Ruhe finden.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 6, 9, 'Darauf erging das Wort des HERRN an mich folgendermaßen:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 6, 10, '»Nimm von (dem Geschenk) der noch in der Verbannung Lebenden, von Heldai, von Tobija und Jedaja – und zwar gehe du selbst an dem betreffenden Tage hin und begib dich in das Haus Josijas, des Sohnes Zephanjas, wohin sie aus Babylon gekommen sind –,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 6, 11, 'nimm also davon Silber und Gold und laß daraus eine Krone anfertigen; setze sie dem Hohenpriester Josua, dem Sohne Jozadaks, aufs Haupt');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 6, 12, 'und richte dann an ihn folgende Worte: ›So hat der HERR der Heerscharen gesprochen: Siehe, da ist ein Mann, Sproß ist sein Name – denn unter seinen Füßen wird es sprossen –, der wird den Tempel des HERRN bauen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 6, 13, 'Ja, er ist’s, der den Tempel des HERRN aufbauen und Herrlichkeit gewinnen wird, und er wird auf seinem Throne sitzen und herrschen und ein Priester wird an seinem Throne stehen, und ein friedliches Einvernehmen wird zwischen beiden bestehen.‹');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 6, 14, 'Die Krone aber soll für Heldai, Tobija und Jedaja sowie für Chen, den Sohn Zephanjas, als Andenken im Tempel des HERRN verbleiben.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 6, 15, 'Und die in weiter Ferne Wohnenden werden kommen und am Tempel des HERRN bauen, und ihr werdet dann auch erkennen, daß der HERR der Heerscharen mich zu euch gesandt hat; und dies alles wird geschehen, wenn ihr der Stimme des HERRN, eures Gottes, willig gehorcht.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 7, 1, 'Im vierten Regierungsjahre des Königs Darius erging das Wort des HERRN an Sacharja am vierten Tage des neunten Monats, im Monat Kislew.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 7, 2, 'Es hatte nämlich Bethel den Sarezer und Regem-Melech samt seinen Leuten abgesandt, um den HERRN (durch Opfer) gnädig zu stimmen,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 7, 3, 'und zugleich, um an die Priester, die zum Tempel des HERRN der Heerscharen gehörten, und an die Propheten folgende Anfrage zu richten: »Sollen wir auch fernerhin im fünften Monat ein Trauerfest abhalten mit Fasten, wie wir es nun schon wer weiß wie viele Jahre getan haben?«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 7, 4, 'Da erging das Wort des HERRN der Heerscharen an mich folgendermaßen:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 7, 5, '»Verkünde dem gesamten Volke des Landes und den Priestern folgendes: ›Wenn ihr im fünften und siebten Monat, und zwar schon siebzig Jahre hindurch, gefastet und getrauert habt, bin ich es da, für den ihr gefastet habt?');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 7, 6, 'Und wenn ihr eßt und wenn ihr trinkt, seid dann nicht ihr die Essenden und ihr die Trinkenden?‹«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 7, 7, '»Sind nicht dies die Gebote, die der HERR schon durch die früheren Propheten hat verkünden lassen, als Jerusalem noch bewohnt war und in sicherer Ruhe bestand samt den dazugehörigen Ortschaften ringsum, und als auch das Südland und die Niederung noch bevölkert waren?«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 7, 8, 'Und weiter erging das Wort des HERRN an Sacharja folgendermaßen:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 7, 9, '»So spricht der HERR der Heerscharen: Übet wahrhaftiges Gericht und erweiset einer dem andern Liebe und Barmherzigkeit!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 7, 10, 'Witwen und Waisen, Fremdlinge und Arme bedrücket nicht, und sinnet nichts Böses gegeneinander in euren Herzen!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 7, 11, 'Aber sie weigerten sich, darauf zu achten, und wollten sich kein Joch auf den Nacken legen lassen; sie verstopften sich die Ohren, um nicht zu hören,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 7, 12, 'und machten ihre Herzen hart wie Kieselstein, um die Belehrung und die Weisungen nicht zu vernehmen, die der HERR der Heerscharen durch seinen Geist unter Vermittlung der früheren Propheten an sie richtete. Da erging denn ein gewaltiges Zorngericht über sie vom HERRN der Heerscharen;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 7, 13, 'und wie sie nicht hatten hören wollen, als er sie rief, »ebenso« – so hat der HERR der Heerscharen gesprochen – »mögen sie jetzt rufen, ohne daß ich auf sie höre!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 7, 14, 'So ließ ich sie denn unter alle Heidenvölker zerstieben, die sie vorher nicht gekannt hatten, und das Land verödete nach ihrem Weggang, so daß niemand mehr darin hin und her zog; und so haben sie das liebliche Land in eine Einöde verwandelt.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 8, 1, 'Weiter erging das Wort des HERRN der Heerscharen (an mich) folgendermaßen:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 8, 2, '»So spricht der HERR der Heerscharen: Ich bin mit großem Liebeseifer um Zion erfüllt und von heftigem Zorn um seinetwillen entbrannt!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 8, 3, 'So hat der HERR gesprochen: »Ich kehre nach Zion zurück und will wieder inmitten Jerusalems Wohnung nehmen, und Jerusalem soll ›die treue Stadt‹ heißen und der Berg des HERRN der Heerscharen ›der heilige Berg‹.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 8, 4, 'So hat der HERR der Heerscharen gesprochen: »Wiederum werden Greise und Greisinnen auf den Plätzen Jerusalems sitzen, ein jeder mit seinem Stabe in der Hand infolge der Fülle der Lebenstage;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 8, 5, 'und die Plätze der Stadt werden wieder angefüllt sein mit Knaben und Mädchen, die auf den Plätzen dort spielen.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 8, 6, 'So hat der HERR der Heerscharen gesprochen: »Wenn das dem Überrest dieses Volkes unmöglich erscheint in jenen Tagen, muß es da auch mir unmöglich erscheinen?« – so lautet der Ausspruch des HERRN der Heerscharen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 8, 7, 'So hat der HERR der Heerscharen gesprochen: »Wisset wohl: ich werde mein Volk erretten aus den Ländern des Sonnenaufgangs und aus den Ländern des Sonnenuntergangs');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 8, 8, 'und werde sie heimbringen, daß sie wieder inmitten Jerusalems wohnen; und sie sollen mein Volk sein, und ich will ihr Gott sein in Wahrheit und Gerechtigkeit.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 8, 9, 'So hat der HERR der Heerscharen gesprochen: »Faßt Mut, ihr, die ihr in diesen Tagen diese Verheißungen aus dem Munde der Propheten vernehmt, nämlich an dem Tage, wo der Grundstein zum Wiederaufbau des Hauses des HERRN der Heerscharen, des Tempels, gelegt wurde!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 8, 10, 'Denn vor dieser Zeit gab es keinen Lohn für die (Arbeit der) Menschen und keinen Ertrag (von der Arbeit) des Viehs, und wer aus- und einging, fühlte sich nicht sicher vor dem Feinde, und ich reizte alle Menschen zur Feindseligkeit gegeneinander.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 8, 11, 'Jetzt aber will ich mich zu dem Überrest dieses Volkes nicht mehr so stellen wie in den früheren Tagen« – so lautet der Ausspruch des HERRN der Heerscharen –,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 8, 12, '»sondern es wird eine Aussaat des Friedens stattfinden: der Weinstock wird seine Frucht bringen und die Erde ihren Ertrag liefern und der Himmel seinen Tau spenden: dies alles will ich dem Überrest dieses Volkes für immer zuteil werden lassen!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 8, 13, 'Und es soll geschehen: Wie ihr vordem den Völkern zum Fluchwort gedient habt, ihr vom Hause Juda und ihr vom Hause Israel, so will ich euch jetzt Heil verleihen, daß ihr zum Segenswunsch werden sollt: fürchtet euch nicht, habt guten Mut!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 8, 14, 'Denn so hat der HERR der Heerscharen gesprochen: »Gleichwie ich vordem beschlossen hatte, euch Böses zu tun, als eure Väter mich erbitterten« – so spricht der HERR der Heerscharen –, »und ich es mir nicht leid sein ließ,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 8, 15, 'ebenso habe ich nun umgekehrt in diesen Tagen beschlossen, Jerusalem und dem Hause Juda Gutes zu erweisen: fürchtet euch nicht!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 8, 16, 'Dies sind aber die Gebote, die ihr erfüllen sollt: Redet die Wahrheit treulich, jeder mit dem andern, und übt eine friedsame Rechtsprechung in euren Toren!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 8, 17, 'Keiner sinne in seinem Herzen auf Unheil gegen den andern, und keiner habe betrügliche Eide lieb! Denn alles dieses hasse ich« – so lautet der Ausspruch des HERRN.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 8, 18, 'Weiter erging das Wort des HERRN der Heerscharen an mich folgendermaßen:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 8, 19, '»So spricht der HERR der Heerscharen: Das Fasten im vierten und fünften, im siebten und zehnten Monat soll für das Haus Juda zu Tagen der Freude und Wonne und zu fröhlichen Festen werden! Nur habt die Wahrheit und den Frieden lieb!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 8, 20, 'So spricht der HERR der Heerscharen: Künftig werden noch Völker und die Bewohner vieler Städte kommen;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 8, 21, 'und die Bewohner der einen Stadt werden zu denen der andern gehen und sagen: ›Kommt, laßt uns hinziehen, um den HERRN (durch Opfer) gnädig zu stimmen und um den HERRN der Heerscharen aufzusuchen! Ja, auch ich will hingehen!‹');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 8, 22, 'So werden denn viele Völker und zahlreiche Völkerschaften kommen, um den HERRN der Heerscharen in Jerusalem aufzusuchen und um den HERRN (durch Opfer) gnädig zu stimmen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 8, 23, 'So spricht der HERR der Heerscharen: In jenen Tagen, da werden zehn Männer aus allen Sprachen der Völker einen jüdischen Mann beim Rockzipfel ergreifen und zu ihm sagen: ›Wir wollen mit euch gehen, denn wir haben vernommen, daß Gott mit euch ist.‹«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 9, 1, '(Dies ist) der Ausspruch des Wortes des HERRN, das gegen das Land Hadrach gerichtet ist und auf Damaskus sich niederläßt – denn dem HERRN gehört das Auge Arams sowie alle Stämme Israels –,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 9, 2, 'und auch gegen Hamath, das daran grenzt, gegen Tyrus und Sidon, weil sie so ausnehmend weise sind.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 9, 3, 'Wohl hat Tyrus sich eine Festung erbaut und Silber aufgehäuft wie Staub und Gold so viel wie Gassenkehricht,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 9, 4, 'doch der Herr wird es arm machen und seinen Besitz ins Meer stürzen, und es selbst wird vom Feuer verzehrt werden.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 9, 5, 'Askalon wird es sehen und schaudern, auch Gaza, und wird in Angst erzittern; ebenso Ekron, weil es sich in seiner Hoffnung (auf Tyrus) getäuscht sieht. Aus Gaza wird der König verschwinden, und Askalon wird nicht mehr bewohnt sein;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 9, 6, 'Gesindel wird in Asdod sich niederlassen, und dem Stolz der Philister will ich ein Ende machen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 9, 7, '»Wenn ich dann ihr blutiges Opferfleisch aus ihrem Munde entfernt und ihre greuelhaften Speisen ihnen zwischen den Zähnen weggeschafft habe, so werden auch sie unserm Gott verbleiben und als ein Stamm in Juda gelten und (die Bewohner von) Ekron den Jebusitern gleichstehen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 9, 8, 'Und ich will mein Lager aufschlagen um mein Haus her als Schutzwache, so daß keiner mehr hin und her hindurchzieht und kein Fronvogt mehr über sie hinwegschreitet; denn jetzt halte ich selbst Wache mit offenen Augen.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 9, 9, '»Frohlocke laut, Tochter Zion! Brich in Jubel aus, Tochter Jerusalem! Siehe, dein König kommt zu dir; gerecht und ein Retter ist er, demütig, und reitet auf einem Esel, auf einem Füllen, dem Jungen einer Eselin.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 9, 10, 'Dann werde ich die Kriegswagen aus Ephraim ausrotten und die Kriegsrosse aus Jerusalem; auch die Kriegsbogen werden ausgerottet werden. Und er wird den Völkern Frieden gebieten, und seine Herrschaft wird von Meer zu Meer, vom Euphratstrom bis an die Enden der Erde reichen.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 9, 11, '»Auch will ich, was dich betrifft, um des Blutbundes willen, den ich mit dir geschlossen habe, deine Gefangenen in Freiheit setzen aus der wasserleeren Grube.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 9, 12, 'Kehret zu einem festen Wohnsitz zurück, ihr Gefangenen, die ihr noch hoffen dürft! Schon heute ergeht die Verkündigung: ›Zwiefältigen Ersatz gebe ich dir!‹');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 9, 13, 'Denn ich spanne mir Juda als Bogen und lege Ephraim (als Pfeil) auf die Sehne; ich biete deine Söhne, Zion, gegen die Söhne Griechenlands auf und mache dich zu einem Heldenschwert!« –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 9, 14, 'Alsdann wird der HERR über ihnen erscheinen, und seine Pfeile werden ausfahren wie Blitze; und Gott der HERR wird in die Posaune (zum Angriff) stoßen und in den Stürmen des Südlandes daherfahren.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 9, 15, 'Der HERR der Heerscharen wird sie beschirmen, und sie werden die Schleuderer fressen und zertreten und ihr Blut wie Wein trinken und voll davon werden wie die Opferschalen, wie die Ecken des Altars.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 9, 16, 'Und den Sieg wird ihnen der HERR, ihr Gott, an jenem Tage verleihen, wie eine Herde wird er sein Volk weiden; denn als Edelsteine im Stirnband funkeln sie auf seinem Lande.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 9, 17, 'Denn wie gesegnet und wie schön wird das Land sein! Das Korn macht Jünglinge und der Most Jungfrauen sprossen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 10, 1, 'Bittet den HERRN um Regen zur Zeit des Spätregens und des Frühregens! Der HERR ist es, der Gewitterwolken schafft und ihnen Regengüsse verleiht für jeglichen Pflanzenwuchs auf dem Felde.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 10, 2, 'Dagegen die Hausgötzen reden Nichtiges, und die Wahrsager schauen Trug, verkünden eitle Träume und spenden windigen Trost. Darum haben (unsere Volksgenossen) fortwandern müssen wie eine Herde und leben im Elend, weil kein Hirt da ist.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 10, 3, '»Gegen die Hirten ist mein Zorn entbrannt, und die Leitböcke will ich heimsuchen; denn der HERR der Heerscharen nimmt sich seiner Herde, des Hauses Juda, fürsorglich an und macht sie zu seinem Prachtroß in der Schlacht.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 10, 4, 'Aus ihnen geht der Eckstein hervor, aus ihnen die Zeltpflöcke, aus ihnen die Kriegsbogen, aus ihnen alle Führer.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 10, 5, 'Insgesamt werden sie sein wie Helden, welche (die Feinde) in den Straßenkot niedertreten im Kampf, und werden (siegreich) streiten; denn der HERR ist mit ihnen, so daß die Reiter hoch zu Roß zuschanden werden.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 10, 6, 'Und ich will das Haus Juda heldenstark machen und auch dem Hause Joseph Hilfe gewähren und sie wiederherstellen; denn ich habe Erbarmen mit ihnen, und es soll ihnen sein, als hätte ich sie niemals verstoßen; denn ich bin der HERR, ihr Gott, und will sie erhören.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 10, 7, 'Da werden denn die Ephraimiten zu Helden werden, und ihr Herz wird frohen Mutes sein wie vom Wein; ihre Söhne werden es sehen und sich freuen: frohlocken wird ihr Herz über den HERRN!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 10, 8, '»Ich will sie durch Zuruf heranlocken und sammeln, denn ich habe sie erlöst; und sie sollen so zahlreich werden, wie sie einstmals gewesen sind.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 10, 9, 'Ich habe sie zwar unter die Völker zerstreut, doch sie haben in den fernen Ländern meiner gedacht, darum sollen sie mit ihren Kindern am Leben bleiben und heimkehren.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 10, 10, 'Ich will sie aus dem Lande Ägypten zurückführen und sie aus Assyrien sammeln und sie in das Land Gilead und an den Libanon heimbringen, und es wird nicht Raum genug für sie vorhanden sein.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 10, 11, 'Wenn sie durch ein gefahrvolles Meer ziehen, wird er im Meer die Wogen niederschlagen und alle Fluten des Nilstromes austrocknen; und der Hochmut Assyriens wird gedemütigt werden, und der Herrscherstab Ägyptens muß weichen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 10, 12, 'Und ich will sie heldenhaft machen im HERRN, daß sie in seinem Namen wandeln!« – so lautet der Ausspruch des HERRN.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 11, 1, 'Öffne, o Libanon, deine Tore, damit das Feuer deine Zedern verzehre!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 11, 2, 'Wehklaget, ihr Zypressen, daß die Zedern gefallen, daß die herrlichen Bäume verwüstet sind! Wehklaget, ihr Eichen Basans, daß der undurchdringliche Wald niedergeschlagen ist!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 11, 3, 'Horch! Die Hirten jammern, daß ihre herrliche Weide verwüstet ist! Horch! Die Löwen brüllen, daß die Pracht des Jordans verwüstet ist!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 11, 4, 'So hat der HERR, mein Gott, (einst zu mir) gesprochen: »Weide die Schlachtschafe,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 11, 5, 'deren Käufer sie abschlachten, ohne dafür büßen zu müssen, und deren Verkäufer sagen: ›Dank sei dem HERRN, daß ich reich geworden bin!‹, und die von ihren Hirten keine Schonung erfahren.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 11, 6, 'Denn ich selbst will hinfort die Bewohner des Landes nicht mehr schonen« – so lautet der Ausspruch des HERRN –; »nein, wisse wohl: Ich selbst will die Menschen einen jeden in die Gewalt des anderen und in die Gewalt seines Königs geraten lassen: die werden dann das Land zugrunde richten, ohne daß ich jemand aus ihrer Hand errette.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 11, 7, 'So weidete ich denn die Schlachtschafe für die Schafhändler und nahm mir dazu zwei Hirtenstäbe: den einen nannte ich ›Huld‹, den andern ›Eintracht‹. Als ich nun die Herde weidete');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 11, 8, 'und in einem Monat die drei Hirten beseitigt hatte, wurde meine Seele ihrer überdrüssig, und auch sie fühlten sich nicht wohl bei mir.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 11, 9, 'Da sagte ich: »Ich mag euch nicht länger weiden: was am Sterben ist, mag sterben, und was verkommen soll, mag verkommen, und die übrigbleibenden mögen einander auffressen!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 11, 10, 'Dann nahm ich meinen Stab ›Huld‹ und zerbrach ihn, um meinen Bund aufzuheben, den ich mit allen Völkern geschlossen hatte.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 11, 11, 'Als er nun an eben jenem Tage aufgehoben war, da erkannten die Schafhändler, die mich scharf beobachteten, daß es ein Wort des HERRN war,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 11, 12, 'als ich zu ihnen sagte: »Wenn es euch gut scheint, so gebt mir meinen Lohn, wo nicht, so laßt es bleiben!« Als sie mir nun dreißig Silberstücke als meinen Lohn dargewogen hatten,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 11, 13, 'gebot mir der HERR: »Wirf ihn in den Tempelschatz, den kostbaren Preis, dessen ich von ihnen wert geachtet worden bin!« Da nahm ich die dreißig Silberstücke und warf sie im Hause des HERRN in den Tempelschatz.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 11, 14, 'Hierauf zerbrach ich auch meinen zweiten Hirtenstab, nämlich ›Eintracht‹, in Stücke, um so den Bruderbund zwischen Juda und Israel aufzuheben.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 11, 15, 'Hierauf sagte der HERR zu mir: »Nimm dir noch einmal die Geräte eines törichten Hirten!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 11, 16, 'Denn wisse wohl: Ich selbst will einen Hirten im Lande erstehen lassen, der sich um die verkommenden Tiere nicht kümmert, die verirrten nicht aufsucht, die verwundeten nicht heilt, die gesunden nicht versorgt, aber das Fleisch der fetten Tiere verzehrt und ihnen sogar noch die Klauen abreißt.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 11, 17, 'Wehe über meinen nichtsnutzigen Hirten, der seine Herde im Stich läßt! Das Schwert komme über seinen Arm und über sein rechtes Auge! Sein Arm möge ganz absterben und sein rechtes Auge völlig erlöschen!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 12, 1, '(Dies ist) der Ausspruch des Wortes des HERRN über Israel; so lautet der Ausspruch des HERRN, der den Himmel ausgespannt und die Erde gegründet und den Geist des Menschen in dessen Innern gebildet hat:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 12, 2, '»Wisset wohl: ich mache Jerusalem zu einer Schale voll Taumeltranks für alle Völker ringsum; und auch an Juda wird die Reihe kommen bei der Belagerung Jerusalems.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 12, 3, 'An jenem Tage will ich Jerusalem zu einem Hebestein für alle Völker machen: alle, die ihn aufheben wollen, werden sich unfehlbar wund an ihm ritzen, wenn alle Völker der Erde sich gegen die Stadt versammeln.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 12, 4, 'An jenem Tage« – so lautet der Ausspruch des HERRN – »werde ich alle Rosse mit Scheuwerden schlagen und ihre Reiter mit Blindheit; aber über dem Hause Juda will ich meine Augen offenhalten, während ich alle Rosse der Völker mit Blindheit schlage.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 12, 5, 'Alsdann werden die Gaufürsten Judas bei sich denken: ›Erfunden wird die Kraft der Bewohner Jerusalems im HERRN der Heerscharen, ihrem Gott.‹');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 12, 6, 'An jenem Tage will ich die Fürsten Judas machen gleich einem Feuerbecken in einem Holzstoß und wie eine Feuerfackel in einem Garbenhaufen, so daß sie zur Rechten und zur Linken alle Völker ringsum verzehren; Jerusalem aber wird auch weiterhin an seiner Stätte in Jerusalem bestehen bleiben!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 12, 7, 'Zuerst aber wird der HERR den Zelten Judas Erfolge verleihen, damit der Stolz des Hauses Davids und der Stolz der Bewohner Jerusalems sich Juda gegenüber nicht überhebt.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 12, 8, 'An jenem Tage wird der HERR die Bewohner Jerusalems beschirmen, so daß der Kraftloseste unter ihnen an jenem Tage wie David sein wird und das Haus Davids wie das Haus Gottes, wie der Engel des HERRN an ihrer Spitze.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 12, 9, '»Und geschehen wird es an jenem Tage, da werde ich darauf bedacht sein, alle Völker zu vernichten, die gegen Jerusalem zu Felde gezogen sind.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 12, 10, 'Sodann will ich über das Haus Davids und über die Bewohner Jerusalems den Geist der Gnade und der Bitte um Gnade ausgießen, so daß sie auf den hinblicken werden, den sie durchbohrt haben, und um ihn wehklagen, wie man um den einzigen Sohn wehklagt, und bitterlich Leid um ihn tragen, wie man um den (Tod des) Erstgeborenen Leid trägt.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 12, 11, 'An jenem Tage wird die Trauer in Jerusalem so groß sein wie einst die Trauer um Hadad-Rimmon in der Ebene von Megiddo.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 12, 12, 'Da wird das Land wehklagen, jedes Geschlecht für sich besonders: das Geschlecht des Hauses Davids für sich, auch ihre Frauen für sich; das Geschlecht des Hauses Nathans für sich, auch ihre Frauen für sich;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 12, 13, 'das Geschlecht des Hauses Levis für sich, auch ihre Frauen für sich; das Geschlecht der Simeiten für sich, auch ihre Frauen für sich;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 12, 14, 'und ebenso alle übrigen Geschlechter, jedes Geschlecht für sich und auch ihre Frauen für sich.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 13, 1, 'An jenem Tage wird dem Hause Davids und den Bewohnern Jerusalems ein Quell erschlossen sein (als Mittel) gegen Sünde und Unreinheit.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 13, 2, '»Und geschehen wird es an jenem Tage« – so lautet der Ausspruch des HERRN der Heerscharen –, »da werde ich die Namen der Götzen aus dem Lande ausrotten, so daß ihrer nicht mehr gedacht wird; und auch die Propheten mitsamt dem unreinen Geist werde ich aus dem Lande wegschaffen.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 13, 3, 'Wenn dann jemand doch noch als Prophet auftritt, so werden sein Vater und seine Mutter, seine leiblichen Eltern, zu ihm sagen: »Du darfst nicht am Leben bleiben, denn du hast Lügen geredet im Namen des HERRN!«, und sein Vater und seine Mutter, seine leiblichen Eltern, werden ihn durchbohren, wenn er als Prophet aufgetreten ist.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 13, 4, 'Da wird es denn an jenem Tage dahin kommen, daß jeder (falsche) Prophet sich seiner Gesichte schämt, daß er geweissagt hat, und keiner wird noch den härenen Mantel anlegen, um zu betrügen,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 13, 5, 'sondern er wird sagen: »Ich bin kein Prophet, nein, ein Ackerknecht bin ich; denn schon in meiner Jugend hat mich einer (als Sklaven) gekauft.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 13, 6, 'Und fragt man ihn dann: »Was sind das für Narben vorn an deiner Brust?«, so wird er antworten: »Die hat man mir im Hause meiner Liebschaften beigebracht.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 13, 7, '»Schwert, mache dich auf gegen meinen Hirten und gegen meine Genossen!« – so lautet der Ausspruch des HERRN der Heerscharen. »Schlage den Hirten nieder, dann werden die Schafe sich zerstreuen, und ich will meine Hand auch gegen die Geringen wenden.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 13, 8, 'Dann sollen im ganzen Lande« – so lautet der Ausspruch des HERRN – »zwei Drittel darin ausgerottet werden und umkommen, der dritte Teil aber soll darin übrig bleiben.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 13, 9, 'Dieses letzte Drittel will ich dann ins Feuer bringen und sie schmelzen, wie man Silber schmelzt, und sie läutern, wie man Gold läutert. Dieses wird dann meinen Namen anrufen, und ich werde ihnen antworten und sagen: ›Dies ist mein Volk!‹, und es wird ausrufen: ›Der HERR ist mein Gott!‹«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 14, 1, 'Wisse wohl: es kommt ein Tag vom HERRN, da wird man die dir abgenommene Beute in deiner Mitte verteilen,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 14, 2, 'und zwar werde ich alle Völker zum Kriege gegen Jerusalem versammeln, und die Stadt wird erobert, die Häuser werden geplündert und die Weiber geschändet werden; die Hälfte der (Einwohnerschaft der) Stadt muß in die Gefangenschaft wandern, aber ein Rest der Bevölkerung wird nicht aus der Stadt ausgerottet werden.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 14, 3, 'Dann aber wird der HERR ausziehen und gegen jene Völker kämpfen, wie er jemals an Schlachttagen gekämpft hat.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 14, 4, 'Er wird an jenem Tage mit den Füßen auf den Ölberg treten, der vor Jerusalem gegen Osten liegt; und der Ölberg wird sich in der Mitte nach Osten und nach Westen hin zu einer überaus großen Schlucht spalten, so daß die eine Hälfte des Berges nach Norden, die andere Hälfte nach Süden zurückweicht.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 14, 5, 'Da werdet ihr dann in die Schlucht meiner Berge fliehen, denn die Bergschlucht wird bis Azel reichen; und zwar werdet ihr fliehen, wie ihr einst vor dem Erdbeben in den Tagen des judäischen Königs Ussia geflohen seid. Dann wird der HERR, mein Gott, kommen und alle heiligen (Engel) mit ihm.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 14, 6, 'An jenem Tage aber, da wird keine Kälte und kein Frost und Eis sein;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 14, 7, 'es wird ein einziger Tag sein – er ist dem HERRN wohlbekannt – ohne Wechsel von Tag und Nacht, und auch zur Abendzeit wird Licht sein.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 14, 8, 'Da wird dann an jenem Tage lebendiges Wasser von Jerusalem ausgehen, zur Hälfte nach dem östlichen Meer und zur Hälfte nach dem westlichen Meer; im Sommer wie im Winter wird das so sein.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 14, 9, 'Der HERR wird dann König sein über die ganze Erde; an jenem Tage wird der HERR der alleinige (Gott) sein und sein Name ›der einzige‹.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 14, 10, 'Das ganze Land wird sich zur Ebene umwandeln von Geba bis nach Rimmon südlich von Jerusalem; dieses aber wird hoch ragen und an seiner Stätte (bewohnt) bleiben vom Benjamintor an bis zu der Stelle des alten Tores, bis hin zum Ecktor, und vom Turm Hananel an bis zu den Königskeltern.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 14, 11, 'Man wird dann darin wohnen, ohne daß fortan ein Bannfluch verhängt wird, und Jerusalem wird in Sicherheit bewohnt werden.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 14, 12, 'Darin aber wird das Strafgericht bestehen, mit dem der HERR alle Völker heimsuchen wird, die gegen Jerusalem zu Felde gezogen sind: Er wird ihr Fleisch vermodern lassen, während sie noch auf ihren Füßen stehen; die Augen werden ihnen in ihren Höhlen vermodern und die Zunge ihnen im Munde verwesen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 14, 13, 'Weiter wird ein gewaltiger, vom HERRN gewirkter Schrecken an jenem Tage unter ihnen entstehen, so daß sie einander bei der Hand fassen und alle handgemein miteinander werden.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 14, 14, 'Und auch Juda wird am Kampf gegen Jerusalem teilnehmen, und der Reichtum aller Völker ringsum wird zusammengerafft werden, Gold, Silber und Kleider in überaus großer Menge.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 14, 15, 'Das gleiche Strafgericht wird aber auch die Rosse und Maultiere, die Kamele und Esel und überhaupt alles Vieh treffen, das in jenen Heerlagern sich vorfinden wird, ganz das gleiche Strafgericht.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 14, 16, 'Danach aber werden alle, so viele von sämtlichen Völkern, die gegen Jerusalem zu Felde gezogen waren, übriggeblieben sind, Jahr für Jahr hinaufziehen, um dort den König, den HERRN der Heerscharen, anzubeten und das Laubhüttenfest zu feiern.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 14, 17, 'Wenn aber eins von den Geschlechtern der Erde nicht nach Jerusalem hinaufziehen sollte, um den König, den HERRN der Heerscharen, anzubeten: auf diese wird kein Regen mehr fallen;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 14, 18, 'und wenn das Geschlecht der Ägypter nicht hinaufzieht und sich nicht einfindet, so wird sie dasselbe Strafgericht treffen, mit welchem der HERR die Völker heimsucht, die nicht zur Feier des Laubhüttenfestes hinaufziehen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 14, 19, 'Das wird die Strafe der Ägypter und die Strafe aller Völker sein, die nicht zur Feier des Laubhüttenfestes hinaufziehen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 14, 20, 'An jenem Tage wird auf den Schellen der Rosse die Aufschrift stehen: »Heilig dem HERRN!«, und die Kochtöpfe im Tempel des HERRN werden den Opferschalen vor dem Altar gleich sein,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 14, 21, 'ja, jeder Kochtopf in Jerusalem und in Juda wird dem HERRN der Heerscharen heilig sein, so daß alle, die zum Opfern kommen, beliebig einen von ihnen nehmen und (das Opferfleisch) darin kochen. Und kein Handelsmann wird mehr im Tempel des HERRN der Heerscharen zu finden sein an jenem Tage.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 1, 1, '(Dies ist) der Ausspruch des Wortes des HERRN an Israel durch den Mund Maleachis:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 1, 2, '»Ich habe euch geliebt«, spricht der HERR; »und da fragt ihr: ›Wieso hast du uns geliebt?‹ Nun, ist nicht Esau der Bruder Jakobs gewesen?« – so lautet der Ausspruch des HERRN –; »und doch habe ich Jakob geliebt,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 1, 3, 'Esau aber gehaßt, so daß ich sein Bergland zur Einöde gemacht habe und sein Erbteil zur wüsten Trift.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 1, 4, 'Wenn Edom sagt: ›Wir sind zwar zertrümmert, werden aber die Trümmer wieder aufbauen!‹, so spricht der HERR der Heerscharen: Sie mögen bauen, ich aber werde niederreißen, und ihr Name wird lauten ›das Land der Gottlosigkeit‹ und ›das Volk, dem der HERR grollt für ewig‹.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 1, 5, 'Mit eigenen Augen werdet ihr es sehen und selbst bekennen: ›Groß ist der HERR über Israels Grenzen hinaus!‹«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 1, 6, '»Ein Sohn ehrt seinen Vater, und ein Knecht (fürchtet) seinen Herrn. Wenn ich nun ein Vater bin, wo ist meine Ehre? und wenn ich ein Herr bin, wo ist die Furcht vor mir? – so spricht der HERR der Heerscharen zu euch Priestern, die ihr meinen Namen verachtet und doch fragt: ›Wieso haben wir deinen Namen verachtet?‹');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 1, 7, 'Ihr bringt ja auf meinem Altar verunreinigte Opferspeise dar; und da fragt ihr noch: ›Wieso haben wir sie verunreinigt?‹ Dadurch, daß ihr sagt: ›Der Tisch des HERRN ist verächtlich!‹');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 1, 8, 'Wenn ihr ein blindes Tier als Opfer darbringt: ist das etwa nichts Schlimmes? Und wenn ihr ein lahmes oder krankes opfert: ist das etwa auch nichts Schlimmes? Bringe (dergleichen) doch einmal deinem Statthalter hin: wird er wohl Freude daran haben oder dir seine Gunst zuwenden?« – so spricht der HERR der Heerscharen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 1, 9, '»Und nun, flehet doch Gott (auf solche Weise) um Gnade an! – Derartiges ist doch eurerseits geschehen –: wird er da noch einem von euch seine Gunst zuwenden?« – so spricht der HERR der Heerscharen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 1, 10, '»O schlösse doch lieber einer von euch gleich die Tore (des Tempels) zu, damit ihr nicht vergeblich Feuer auf meinem Altar anzündet! Ich habe kein Wohlgefallen an euch« – so spricht der HERR der Heerscharen –, »und Opfergaben mag ich von eurer Hand nicht annehmen!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 1, 11, 'Denn vom Aufgang der Sonne bis zu ihrem Niedergang ist mein Name groß unter den Völkern, und überall werden meinem Namen Weihrauch und Opfer dargebracht, und zwar reine Gaben; denn groß ist mein Name unter den Völkern« – so spricht der HERR der Heerscharen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 1, 12, '»Ihr aber entheiligt ihn dadurch, daß ihr sagt: ›Der Tisch des Herrn ist minderwertig, und was er einbringt, ist ein verächtlicher Ertrag!‹');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 1, 13, 'Wenn ihr ferner sagt: ›Ach, wie mühselig ist der Dienst!‹ und ihr ihn mit Geringschätzung behandelt« – so spricht der HERR der Heerscharen – »und Geraubtes oder lahme und kranke Tiere als Opfergabe darbringt: soll ich das mit Wohlgefallen aus eurer Hand annehmen?« – so spricht der HERR.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 1, 14, '»Nein, verflucht ist der Betrüger, der in seiner Herde männliche Tiere hat und, wenn er ein Gelübde getan hat, dem Herrn doch ein geringwertiges Tier opfert! Denn ich bin ein großer König« – so spricht der HERR der Heerscharen –, »und mein Name ist gefürchtet unter den Völkern!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 2, 1, '»Und nun ergeht über euch, ihr Priester, folgender Beschluß:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 2, 2, 'Wenn ihr nicht gehorchen wollt und ihr es euch nicht von Herzen angelegen sein laßt, meinem Namen Ehre zu erweisen« – so spricht der HERR der Heerscharen –, »so schleudere ich den Fluch gegen euch und mache eure Segenssprüche zu Flüchen; ja, ich habe sie schon in Flüche verwandelt, weil ihr (meine Worte) nicht zu Herzen genommen habt.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 2, 3, 'Wisset wohl: ich mache eurer Amtstätigkeit ein Ende und schleudere euch Mist ins Gesicht, den Mist eurer Festopfer, und man mag euch selbst zu ihm hinaustragen!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 2, 4, 'Dann werdet ihr auch zur Erkenntnis kommen, daß ich diesen Beschluß über euch habe ergehen lassen, damit mein Bund mit Levi bestehen bleibe« – so spricht der HERR der Heerscharen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 2, 5, '»Mein Bund mit ihm war ein Bund des Lebens und des Friedens; beides verlieh ich ihm, damit er Furcht vor mir hätte: und er fürchtete mich auch und beugte sich vor meinem Namen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 2, 6, 'Zuverlässige Unterweisung war in seinem Munde, kein Trug fand sich auf seinen Lippen; in Frieden und Aufrichtigkeit wandelte er mit mir und hielt viele von Versündigung zurück.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 2, 7, 'Denn eines Priesters Lippen müssen Erkenntnis bewahren, und Unterweisung erwartet man aus seinem Munde; denn ein Bote des HERRN der Heerscharen ist er.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 2, 8, 'Ihr dagegen seid vom rechten Wege abgewichen, habt viele durch eure Unterweisung zu Fall gebracht und den Bund mit Levi verderbt« – so spricht der HERR der Heerscharen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 2, 9, '»So habe denn auch ich euch beim ganzen Volk in Verachtung und Geringschätzung gebracht gerade so, wie ihr meine Wege nicht innehaltet und bei der Erteilung der Unterweisung die Person anseht.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 2, 10, 'Haben wir nicht alle einen Vater? Hat nicht ein Gott uns geschaffen? Warum handeln wir denn treulos gegeneinander und entweihen den Bund unserer Väter?');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 2, 11, 'Treubruch hat Juda begangen, und Greuel sind in Israel und in Jerusalem verübt worden; denn Juda hat das Heiligtum des HERRN, das er lieb hat, entweiht, indem es Ehen mit den Töchtern eines fremden Gottes geschlossen hat.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 2, 12, 'Ausrotten möge der HERR einem Manne, der solches tut, jeden Zeugen und Verteidiger aus den Zelten Jakobs sowie jeden, der dem HERRN der Heerscharen Opfergaben darbringt!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 2, 13, 'Und zweitens tut ihr auch dieses: Ihr bedeckt den Altar des HERRN mit Tränen, mit Weinen und Seufzen, so daß er nicht mehr gnädig auf ein Opfer hinblickt und keine Gabe mit Wohlgefallen aus eurer Hand mehr annehmen mag.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 2, 14, 'Da fragt ihr: ›Warum das?‹ Nun darum, weil der HERR Zeuge gewesen ist (bei dem Bunde) zwischen dir und dem Weibe deiner Jugend, dem du die Treue gebrochen hast, obschon sie deine Lebensgefährtin und durch feierlichen Bundesschluß deine Gattin war.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 2, 15, 'Darum hat kein einziger so gehandelt, der noch einen Rest des rechten Geistes besaß. Denn was verlangt der Eine? Gottessamen! So seid denn auf der Hut um eures Geistes willen, und handle du nicht treulos am Weibe deiner Jugend!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 2, 16, '»Denn ich hasse Entlassungen« – so spricht der HERR, der Gott Israels – »ebenso, wie wenn jemand sein Gewand mit Gewalttat bedeckt« – so spricht der HERR der Heerscharen. »So seid denn auf der Hut um eures Geistes willen, daß ihr nicht die Treue brecht!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 2, 17, 'Ihr habt dem HERRN durch eure Reden Verdruß bereitet und fragt doch: »Wieso haben wir ihm Verdruß bereitet?« Nun dadurch, daß ihr sagt: »Jeder Übeltäter ist doch gut in den Augen des HERRN, und an solchen Leuten hat er Wohlgefallen« oder: »Wo ist denn der Gott des Gerichts?«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 3, 1, '»Wisset wohl: ich sende meinen Engel, daß er den Weg vor mir her bahne, und unversehens wird zu seinem Tempel kommen der Herr, den ihr herbeiwünscht, und der Bundesengel, nach dem ihr Verlangen tragt, kommt unfehlbar!« – so spricht der HERR der Heerscharen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 3, 2, 'Doch wer vermag den Tag seines Kommens zu ertragen, und wer bleibt bei seinem Erscheinen bestehen? Denn er wird wie das Feuer eines Schmelzers sein und wie die Lauge von Walkern;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 3, 3, 'und dasitzen wird (er wie) einer, der das Silber schmelzt und reinigt, und er wird die Söhne Levis reinigen und sie läutern wie Gold und wie Silber, damit sie dem HERRN Opfergaben in Gerechtigkeit darbringen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 3, 4, 'Dann werden die Opfergaben Judas und Jerusalems dem HERRN (wieder) wohlgefällig sein wie in den Tagen der Vorzeit und wie in den vergangenen Jahren.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 3, 5, '»Da will ich mich bei euch einstellen zum Gericht und werde unverzüglich als Zeuge auftreten gegen die Zauberer und gegen die Ehebrecher, gegen die Meineidigen und gegen alle, die den Tagelöhnern (ihren Lohn vorenthalten), Witwen und Waisen bedrücken und das Recht der Fremdlinge beugen, ohne mich zu fürchten!« – so spricht der HERR der Heerscharen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 3, 6, '»Denn ich, der HERR, habe mich nicht geändert, und ihr habt nicht aufgehört, Jakobssöhne zu sein.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 3, 7, 'Seit den Tagen eurer Väter seid ihr von meinen Geboten abgewichen und habt sie nicht gehalten. Kehret um zu mir, so will ich mich wieder zu euch kehren!« – so spricht der HERR der Heerscharen. »Da fragt ihr: ›Inwiefern sollen wir umkehren?‹');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 3, 8, 'Darf wohl ein Mensch die Gottheit betrügen, daß ihr mich betrügt und noch fragt: ›Inwiefern haben wir dich betrogen?‹ Nun, mit dem Zehnten und mit dem Hebeopfer.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 3, 9, 'Mit dem Fluch seid ihr belastet, und doch betrügt ihr mich! Ein Betrüger ist das ganze Volk.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 3, 10, 'Bringet den Zehnten unverkürzt in das Vorratshaus, damit Zehrung in meinem Hause vorhanden sei, und stellet mich doch auf diese Weise einmal auf die Probe« – so spricht der HERR der Heerscharen –, »ob ich euch dann nicht die Fenster des Himmels auftue und Segen in überreicher Fülle über euch ausschütte!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 3, 11, 'Da will ich dann euch zugute den Freßheuschrecken Einhalt tun, daß sie euch den Ertrag des Feldes nicht mehr verwüsten, und der Weinstock soll euch auf der Flur nicht mehr fruchtlos bleiben!« – so spricht der HERR der Heerscharen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 3, 12, '»Da werden denn alle Heidenvölker euch glücklich preisen, weil ihr ein Land des Wohlgefallens sein werdet« – so spricht der HERR der Heerscharen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 3, 13, '»Trotzige Reden habt ihr gegen mich geführt«, spricht der HERR, »und da fragt ihr noch: ›Was haben wir denn untereinander gegen dich geredet?‹');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 3, 14, 'Nun, ihr sagt: ›Es bringt keinen Vorteil, Gott zu dienen, und welchen Gewinn haben wir davon gehabt, daß wir seine Gebote gehalten haben und in Trauerkleidern vor dem HERRN der Heerscharen einhergegangen sind?');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 3, 15, 'Darum preisen wir jetzt die Übermütigen glücklich: nicht nur ist es ihnen gut ergangen, als sie gesetzlos handelten, sondern sie sind auch straflos davongekommen, als sie Gott versuchten.‹« –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 3, 16, 'Als sich dann aber auch die Gottesfürchtigen miteinander besprachen, merkte der HERR auf und hörte ihnen zu; und es wurde ein Gedenkbuch vor ihm geschrieben für die, welche den HERRN fürchten und vor seinem Namen Hochachtung haben.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 3, 17, '»Sie sollen mir« – so hat der HERR der Heerscharen gesprochen – »an dem Tage, wo ich es vollführe, ein Sondereigentum sein, und ich will schonend mit ihnen verfahren, wie ein Mann schonend mit seinem Sohne verfährt, der ihm dient.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 3, 18, 'Da werdet ihr dann wieder den Unterschied wahrnehmen zwischen dem Gerechten und dem Gottlosen, zwischen dem, der Gott dient, und dem, der ihm nicht dient.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 3, 19, 'Denn wisset wohl: es kommt der Tag, brennend wie ein Ofen, da werden alle Übermütigen und alle, die gesetzlos handeln, wie Stoppeln sein, und verbrennen wird sie der Tag, der da kommt« – so hat der HERR der Heerscharen gesprochen –, »so daß von ihnen weder Wurzel noch Zweig übrigbleibt!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 3, 20, 'Euch aber, die ihr meinen Namen fürchtet, wird die Sonne der Gerechtigkeit aufgehen mit Heilung in ihren Flügeln; und ihr werdet ausziehen und hüpfen wie Jungvieh (aus dem Stall)');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 3, 21, 'und werdet die Gottlosen zertreten; denn sie sollen zu Staub werden unter euren Fußsohlen an dem Tage, wo ich es vollführe!« – so hat der HERR der Heerscharen gesprochen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 3, 22, '»Bleibet (also) eingedenk des Gesetzes meines Knechtes Mose, dem ich am Horeb Satzungen und Verordnungen für ganz Israel aufgetragen habe.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 3, 23, 'Wisset wohl: ich sende euch den Propheten Elia, ehe der große und furchtbare Tag des HERRN kommt;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 3, 24, 'der wird das Herz der Väter den Söhnen und das Herz der Söhne ihren Vätern wieder zuwenden, damit ich nicht kommen muß und das Land mit dem Bannfluch schlage!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 1, 1, 'Im zwölften Jahre der Regierung Nabuchodonosors, der als König über die Assyrer in der großen Stadt Ninive herrschte, in den Tagen Arphaxads, der über die Meder in Ekbatana herrschte, –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 1, 2, 'dieser hatte rings um Ekbatana Mauern von Quadersteinen, drei Ellen breit und sechs Ellen lang, erbaut und die Höhe der Mauer auf siebenzig und ihre Breite auf fünfzig Ellen bemessen;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 1, 3, 'ihre Türme hatte er auf den Stadttoren hundert Ellen hoch errichtet und sie am Grunde in einer Breite von sechzig Ellen aufgeführt;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 1, 4, 'ihre Tore hatte er zu einer Höhe von siebenzig Ellen und zu einer Breite von vierzig Ellen angelegt, damit seine gewaltige Heeresmacht und die Scharen seines Fußvolkes in geschlossenen Reihen hindurchziehen könnten –:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 1, 5, 'in jener Zeit zog der König Nabuchodonosor gegen den König Arphaxad zu Felde in der großen Ebene, die im Gebiete von Ragau liegt.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 1, 6, 'Da stießen zu ihm alle Bewohner des Berglandes und alle Anwohner des Euphrat, des Tigris und des Hydaspes und die Mannschaften aus der Tiefebene Ariochs, des Königs der Elymäer; so vereinigten sich denn viele Völker zum Kampfe gegen die Söhne Cheleuds.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 1, 7, 'Da sandte Nabuchodonosor, der König der Assyrer, Boten an alle Bewohner Persiens und an alle Bewohner der westlichen Länder, nämlich an die Bewohner von Cilicien und Damaskus, vom Libanon und Antilibanon und an die Bewohner der Meeresküste,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 1, 8, 'sowie an die Völker am Karmel und in Gilead, in Ober-Galiläa und in der großen Ebene Esdrelom,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 1, 9, 'sodann an alle in Samaria und den dortigen Städten und jenseits des Jordans bis nach Jerusalem und Betane, Chellus und Kades, bis an den Bach Ägyptens, nach Taphne, Ramesse und bis zum ganzen Lande Gesem,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 1, 10, 'bis über Tanis und Memphis hinaus, und an alle Bewohner Ägyptens bis an die Grenzen von Äthiopien.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 1, 11, 'Aber alle Bewohner aller dieser Länder ließen den Befehl des Assyrerkönigs Nabuchodonosor unbeachtet und leisteten ihm keine Heeresfolge, weil sie ihn nicht fürchteten, sondern in ihm nur einen gewöhnlichen Menschen ihresgleichen sahen; sie schickten also seine Gesandten unverrichteter Sache und unter schnöder Mißachtung zurück. Da ergrimmte Nabuchodonosor gewaltig gegen alle diese Länder und schwor bei seinem Throne und seiner Herrschaft, an allen Gebieten von Cilicien, Damaskus und Syrien Rache zu nehmen und mit seinem Schwert auch alle Bewohner des Landes Moab, sowie die Ammoniter und das ganze jüdische Land und alle Bewohner Ägyptens bis zum Gebiet der beiden Nilarme auszurotten. Er zog also mit seinem Heere gegen den König Arphaxad zu Felde im 17. Jahre seiner Regierung, besiegte ihn in der Schlacht und schlug die ganze Streitmacht Arphaxads, auch seine gesamte Reiterei und alle seine Kriegswagen in die Flucht; er eroberte dann seine Städte und zog bis vor Ekbatana, dessen Türme er in seine Gewalt brachte, dessen Straßen er verwüstete und dessen Herrlichkeit er ein schmähliches Ende bereitete. Hierauf nahm er den Arphaxad in den Bergen von Ragau gefangen, durchbohrte ihn mit seinen Wurfspießen und brachte ihn so noch an demselben Tage ums Leben. Schließlich kehrte er nach Ninive zurück, er und alle seine Hilfsvölker, eine gewaltige Menge von Kriegsvolk; er ließ es sich dort wohl sein und schmauste mit seinem Heere 120 Tage lang.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 2, 1, 'Im 18. Regierungsjahre, am 22. Tage des ersten Monats, entstand im Palast des Assyrerkönigs Nabuchodonosor das Gerücht, er wolle die Rache an dem ganzen Ländergebiet vollziehen, wie er es angekündigt hatte.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 2, 2, 'Er berief wirklich alle seine Beamten und alle seine Würdenträger zu sich, eröffnete ihnen seinen geheimen Plan und legte ihnen persönlich die ganze Bosheit jener Länder genau dar.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 2, 3, 'Da sprachen auch sie sich dahin aus, daß die gesamte Menschheit, die dem Gebote seines Mundes nicht gehorcht hätte, vertilgt werden sollte.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 2, 4, 'Als der König Nabuchodonosor nun seine Beratung zu Ende geführt hatte, berief er seinen obersten Heerführer Holofernes, der den zweiten Rang nach ihm innehatte, und sagte zu ihm:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 2, 5, '»So befiehlt der Großkönig, der Herr der ganzen Erde: Du sollst jetzt von mir ausziehen und mit dir nehmen an zuverlässigen Kriegern 120000 Mann zu Fuß und 12000 Reiter');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 2, 6, 'und sollt gegen alle Länder im Westen ausziehen, weil sie dem von mir ergangenen Befehl ungehorsam gewesen sind;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 2, 7, 'gebiete ihnen, Erde und Wasser bereit zu halten, denn ich will in meinem Zorn gegen sie ins Feld rücken und die ganze Oberfläche ihres Gebiets mit den Füßen meiner Kriegsleute bedecken und sie ihnen zur Plünderung preisgeben;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 2, 8, 'ihre Erschlagenen sollen ihre Schluchten und Bäche anfüllen, so daß die Gewässer wegen der Menge der Leichen austreten;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 2, 9, 'ihre Gefangenen aber will ich bis an die Enden der ganzen Erde wegführen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 2, 10, 'Du sollst vorausziehen, um mir alle ihre Gebiete zu unterwerfen; und wenn sie sich dir ergeben haben, sollst du sie mir aufbewahren auf den Tag, wo ich sie strafen werde.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 2, 11, 'Gegen die Ungehorsamen sollst du mitleidlos vorgehen, so daß du sie dem Tode und der Plünderung überall preisgibst, wo du dich befindest.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 2, 12, 'Denn, bei meinem Leben und bei meiner königlichen Macht: ich habe es ausgesprochen und werde es auch ausführen mit meiner Hand!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 2, 13, 'Du aber übertritt keinen der Befehle deines Herrn, sondern vollziehe sie genau, wie ich dir geboten habe, und zögere nicht mit ihrer Ausführung!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 2, 14, 'Da verabschiedete sich Holofernes von seinem Herrn und berief alle Fürsten, Heerführer und Hauptleute der assyrischen Heeresmacht');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 2, 15, 'und musterte die zum Kampf auserwählten Mannschaften, wie sein Herr ihm befohlen hatte, nämlich 120000 Mann zu Fuß und 12000 berittene Bogenschützen;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 2, 16, 'er ordnete sie dann, wie ein Kriegsheer geordnet zu werden pflegt,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 2, 17, 'und nahm Kamele, Esel und Maultiere für das Gepäck in gewaltiger Menge, ferner zahllose Schafe, Rinder und Ziegen als Mundvorrat,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 2, 18, 'auch sonstige Lebensmittel für jeden Mann in Fülle, dazu sehr viel Silber und Gold aus dem königlichen Palast. Hierauf brach er mit seinem ganzen Heere auf, um vor dem Könige Nabuchodonosor herzuziehen und alle Länder im Westen mit seinen Wagen, Reitern und auserlesenen Fußtruppen zu bedecken. Zahlreich wie ein Heuschreckenschwarm und wie der Sand auf dem Erdboden war auch der Troß von Leuten, die sich ihnen anschlossen, eine geradezu zahllose Menge. Nachdem sie Ninive verlassen hatten, zogen sie drei Tagemärsche weit nach der großen Ebene Baiktilaith und schlugen ein Lager auf von Baiktilaith an bis in die Nähe des Gebirges, das nördlich von Obercilicien liegt. Dann nahm er sein ganzes Heer, Fußvolk, Reiter und Wagen, und zog von dort in das Bergland. Er brach durch Phud und Lud, plünderte alle Rassiten und die Ismaeliten, die am Rande der Wüste südlich von den Theläern wohnen, ging dann über den Euphrat, durchzog Mesopotamien, zerstörte alle festen Städte am Flusse Abronas bis ans Meer, eroberte das Gebiet von Cilicien, schlug alle, die ihm entgegentraten, nieder und gelangte bis an das Gebiet Japheths südlich von Arabien. Er umzingelte alle Midianiter, verbrannte ihr Zeltlager und plünderte ihre Hürden. Dann stieg er in die Ebene von Damaskus hinab zur Zeit der Weizenernte, verbrannte alle ihre Äcker, vernichtete ihr Kleinvieh und die Rinderherden, plünderte ihre Städte, verwüstete ihre Felder und erschlug ihre gesamten jungen Männer mit der Schärfe des Schwertes. Da überfiel Angst und Zittern vor ihm die Bewohner der Meeresküste in Sidon und Tyrus und die Bewohner von Sur und Okina und Jamnia, und die Einwohnerschaft von Asdod und Askalon war in gewaltiger Furcht vor ihm.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 3, 1, 'Da schickten sie Gesandte an ihn mit Friedensworten und ließen ihm sagen:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 3, 2, '»Wisse wohl: wir liegen vor dir als die Knechte des Großkönigs Nabuchodonosor, verfahre mit uns nach deinem Belieben!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 3, 3, 'Wisse wohl: unsere Gehöfte und jeder Wohnort, alle unsere Weizenfelder, unser Kleinvieh und die Rinderherden und alle Hürden unserer Zelte sind in deiner Gewalt: verfahre damit nach deinem Belieben!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 3, 4, 'Wisse wohl: auch unsere Städte und deren Bewohner sind dir untertan; komm und behandle sie, wie es dir gut scheint!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 3, 5, 'Die Boten kamen zu Holofernes und überbrachten ihm diese Botschaft;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 3, 6, 'da zog er mit seinem Heere an die Küste hinab, legte Besatzungen in die festen Plätze und hob auserlesene Mannschaften aus ihnen zum Eintritt in sein Heer aus.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 3, 7, 'Die Bevölkerung und die ganze Umgegend hatte ihn mit Kränzen, Reigentänzen und Paukenschlag aufgenommen;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 3, 8, 'er aber verwüstete ihr ganzes Gebiet und ließ ihre Haine umhauen; denn es war sein fester Entschluß, alle Götter der Erde auszurotten, damit alle Völker den Nabuchodenosor allein anbeteten und alle ihre Zungen und Geschlechter ihn als Gott anriefen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 3, 9, 'So gelangte er nach Esdrelom in die Nähe von Dothea, das vor der großen Ebene von Judäa liegt;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 3, 10, 'er bezog ein Lager zwischen Gabä und Skythopolis und blieb dort einen ganzen Monat lang, um alles Gepäck seines Heeres an sich zu ziehen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 3, 11, '');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 3, 12, '');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 4, 1, 'Als nun die Israeliten, die in Judäa wohnten, alles erfuhren, was Holofernes, der oberste Heerführer des Assyrerkönigs Nabuchodonosor, den Völkern angetan und wie er alle ihre Heiligtümer geplündert und von Grund aus zerstört hatte,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 4, 2, 'da fürchteten sie sich gar sehr vor ihm und gerieten in Bestürzung im Hinblick auf Jerusalem und auf den Tempel ihres Gottes.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 4, 3, 'Denn sie waren erst vor kurzem aus der Gefangenschaft zurückgekehrt, und erst jüngst war das ganze jüdische Volk versammelt gewesen und die heiligen Geräte, sowie der Altar und der Tempel nach der Entweihung neu geheiligt worden.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 4, 4, 'So sandten sie denn Boten in die ganze Landschaft Samaria und in die Dörfer, sowie nach Bethoron, Belmain, Jericho, Choba, Esora und in das Tal Salem,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 4, 5, 'besetzten alle Gipfel der höheren Berge, befestigten die dortigen Ortschaften und versahen sie mit Lebensmitteln für den Kriegsbedarf; denn ihre Felder waren soeben abgeerntet.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 4, 6, 'Außerdem schrieb Jojakim, der damalige Hohepriester in Jerusalem, an die Bewohner von Betylua und Betomesthaim, das Esdrelom gegenüber vor der Ebene nahe bei Dothaim liegt,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 4, 7, 'und gebot ihnen, sie sollten die Zugänge zum Berglande besetzen, weil durch sie der Zugang zu Judäa führte und es leicht war, die Feinde, wenn sie heranzogen, aufzuhalten, da es ein Engpaß war für höchstens zwei Mann nebeneinander.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 4, 8, 'Da taten die Israeliten, wie ihnen der Hohepriester Jojakim und der Hohe Rat des ganzen israelitischen Volkes, die in Jerusalem saßen, geboten hatten.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 4, 9, 'Ganz Israel aber rief Gott mit großer Inbrunst an und kasteite sich in strengem Fasten.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 4, 10, 'Sie selbst und ihre Weiber und Kinder, auch ihr Vieh und alle bei ihnen lebenden Fremden, ihre Tagelöhner und die für Geld erkauften Sklaven legten Sacktuch an;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 4, 11, 'und ganz Israel, auch die Weiber und Kinder, die in Jerusalem wohnten, warfen sich vor dem Tempel nieder, streuten sich Asche aufs Haupt und breiteten ihre Sacktücher vor dem Herrn aus;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 4, 12, 'auch den Altar umhüllten sie mit einem Trauergewand und schrieen einmütig und inbrünstig zum Gott Israels, er möge nicht zulassen, daß ihre Kinder ihnen geraubt, ihre Weiber in die Gefangenschaft geschleppt, die Städte ihres Erbbesitzes zerstört und das Heiligtum entweiht und geschändet würde, zum Spott für die Heiden.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 4, 13, 'Der Herr aber vernahm ihren Hilferuf und sah ihre Bedrängnis an. Und das Volk fastete mehrere Tage in ganz Judäa und Jerusalem vor dem Heiligtum des allmächtigen Gottes;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 4, 14, 'Jojakim dagegen, der Hohepriester, und alle, die den heiligen Dienst vor dem Herrn versahen, Priester und Leviten, brachten, mit Trauergewändern angetan, das tägliche Brandopfer und die Gelübde und die freiwilligen Gaben des Volkes dar; Asche lag auf ihren Kopfbinden, und sie riefen den Herrn mit aller Kraft an, daß er das ganze Haus Israel in Gnaden ansehen wolle.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 1, 'Als nun dem assyrischen Oberfeldherrn Holofernes berichtet wurde, daß die Israeliten sich zum Kriege rüsteten und daß sie die Pässe im Bergland gesperrt und die Spitzen aller höheren Berge befestigt und in den Ebenen Verhaue errichtet hätten,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 2, 'da geriet er in großen Zorn und berief alle Fürsten der Moabiter und die Feldherren der Ammoniter und alle Statthalter des Küstenlandes');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 3, 'und sagte zu ihnen: »Tut mir doch kund, ihr Kanaaniter: was ist das für ein Volk, das da im Berglande sitzt, und welche Städte bewohnt es? und wie stark ist ihre Streitmacht, und worin besteht ihre Stärke und Kraft? und wer ist ihr König, der ihr Heer befehligt,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 4, 'und warum haben sie sich geweigert, mir entgegenzukommen, sie allein von allen Völkern hier im Westen?«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 5, 'Da antwortete ihm Achjor, der Anführer aller Ammoniter: »Mein Herr wolle anhören, was dein Knecht dir sagen will, so will ich dir die Wahrheit verkünden in betreff dieses Volkes, welches das Bergland hier in deiner Nähe bewohnt, und kein unwahres Wort soll aus dem Munde deines Knechts kommen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 6, 'Dieses Volk besteht aus Nachkommen der Chaldäer.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 7, 'Sie wohnten vordem in Mesopotamien. Weil sie nämlich den Göttern ihrer Väter, die im Lande der Chaldäer lebten, nicht folgen wollten,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 8, 'fielen sie vom Glauben ihrer Vorfahren ab und verehrten den Gott des Himmels, den Gott, den sie kennen gelernt hatten. Darum vertrieb man sie aus der Gemeinschaft mit ihren Göttern, und sie flohen nach Mesopotamien, wo sie lange Zeit wohnen blieben.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 9, 'Da gebot ihnen ihr Gott, diese Ansiedlung zu verlassen und in das Land Kanaan zu ziehen. Sie ließen sich dort nieder und wurden reich an Gold, Silber und sehr vielem Vieh.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 10, 'Dann zogen sie nach Ägypten hinab, weil eine Hungersnot das Land Kanaan schwer bedrückte, und blieben daselbst wohnen, solange sie dort zu leben hatten, und vermehrten sich dort zu einer geradezu unzählbaren Menge.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 11, 'Da trat der König von Ägypten gegen sie auf, man bedrückte sie arglistig mit Fronarbeit und Ziegelbrennen, mißhandelte sie und machte sie zu Sklaven.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 12, 'Als sie nun ihren Gott um Hilfe anriefen, schlug dieser das ganze Land Ägypten mit unheilbaren Plagen, bis die Ägypter sie zuletzt aus ihrem Lande ziehen ließen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 13, 'Gott trocknete dann das Rote Meer vor ihnen aus,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 14, 'ließ sie den Weg nach dem Sinai und Kades Barnea einschlagen, und sie vertrieben alle Völkerschaften, die in der Steppe wohnten.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 15, 'Dann setzten sie sich im Lande der Amoriter fest und vernichteten durch ihre Streitmacht die Bewohner von ganz Hesbon; und nachdem sie dann den Jordan überschritten hatten, nahmen sie das ganze Bergland in Besitz,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 16, 'vertrieben hierauf vor sich her die Kanaanäer, Pheresiter, Jebusiter, die Einwohner von Sichem und alle Girgasiter und blieben dort lange Zeit wohnen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 17, 'Und solange sie gegen ihren Gott nicht sündigten, ging es ihnen gut, denn ein Gott, der Unrecht haßt, ist mit ihnen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 18, 'Als sie aber von dem Wege, den er ihnen zur Pflicht gemacht hatte, abwichen, wurden sie in vielen Kriegen völlig zugrunde gerichtet und in ein fremdes Land in die Gefangenschaft weggeführt; der Tempel ihres Gottes wurde dem Boden gleichgemacht, und ihre Städte fielen den Feinden in die Hand.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 19, 'Jetzt aber, da sie sich ihrem Gott wieder zugewandt haben, sind sie aus den Ländern, in die sie zerstreut worden waren, heimgekehrt und haben Jerusalem, wo ihr Heiligtum ist, wieder in Besitz genommen und sich in dem Berglande seßhaft gemacht, weil es herrenlos war.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 20, 'Und nun, mein Herr und Gebieter, wenn dieses Volk sich etwas zu Schulden kommen läßt und sich an seinem Gott versündigt, so werden wir die Erfahrung machen, daß dies für sie den Untergang bedeutet, dann wollen wir hinaufziehen und sie unterwerfen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 21, 'Hat sich aber dieses Volk kein Unrecht zu Schulden kommen lassen, so möge mein Herr doch an ihnen vorüberziehen, sonst könnte ihr Herr und Gott sie in seinen Schutz nehmen und wir zum Spott der ganzen Welt werden«.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 22, 'Als nun Achjor mit diesem Vortrage zu Ende war, murrte die ganze Versammlung, die das Zelt im Kreise umgab, und die Großen des Holofernes und alle Bewohner der Seeküste und die Moabiter riefen, man solle ihn niederhauen,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 23, 'indem sie erklärten: »Wir haben keine Angst vor den Israeliten; sie sind ja ein Volk, das weder die Kraft noch den Mut zu einem nachdrücklichen Widerstand besitzt.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 24, 'Darum laß uns ja hinaufziehen, Gebieter Holofernes; dein ganzes Heer wird sie bald aufgefressen haben!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 25, '');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 26, '');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 6, 1, 'Nachdem sich dann der Lärm der Männer rings im Kriegsrate gelegt hatte, sagte Holofernes, der Oberfeldherr des assyrischen Heeres, zu Achjor vor der ganzen Versammlung der Fremden und zu allen Moabitern:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 6, 2, '»Wer bist denn du, Achjor, mit deinen ephraimitischen Mietlingen, daß du heute eine solche Prophezeiung unter uns aussprichst und uns rätst, die Israeliten nicht zu bekriegen, weil ihr Gott sie beschützen würde? Wer ist denn Gott außer Nabuchodonosor? Dieser wird seine Heeresmacht entsenden und sie vom Erdboden vertilgen, ohne daß ihr Gott sie zu retten vermag.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 6, 3, 'Nein, wir, seine Knechte, werden sie zusammenhauen wie einen Mann, und dem Ansturm unserer Reiter werden sie nicht standhalten können;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 6, 4, 'denn mit diesen werden wir sie überfluten, so daß ihre Berge sich an ihrem Blute berauschen und ihre Gefilde mit ihren Leichen angefüllt werden; ihre Füße werden bei unserm Anblick nicht stehen bleiben, nein, bis auf den letzten Mann sollen sie umkommen, spricht der König Nabuchodonosor, der Herr der ganzen Erde. Ja, er hat’s gesagt, und was er bestimmt ausgesprochen hat, soll nicht unerfüllt bleiben.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 6, 5, 'Du aber, Achjor, du Mietling Ammons, der du diese Worte heute frevelhafterweise gesprochen hast, du sollst mein Angesicht von heute an nicht mehr sehen, bis ich Rache genommen habe an diesem Volke, das aus Ägypten stammt.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 6, 6, 'Alsdann aber soll das Schwert meines Heeres und der Speer meiner Diener dir die Brust durchbohren, und und du sollst unter ihren Erschlagenen daliegen, wenn ich zurückkomme.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 6, 7, 'Meine Knechte sollen dich ins Bergland fortschaffen und dich in einer von den Städten oben auf den Höhen festsetzen,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 6, 8, 'und du sollst erst dann sterben, wenn du mit jenen zusammen den Untergang findest.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 6, 9, 'Hoffst du aber wirklich in deinem Herzen, daß sie nicht eingenommen werden, so magst du immerhin zuversichtlich um dich blicken: ich habe gesprochen, und keines meiner Worte wird unerfüllt bleiben«.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 6, 10, 'Darauf befahl Holofernes seinen Dienern, die in seinem Zelte gegenwärtig waren, den Achjor zu ergreifen, ihn nach Betylua zu schaffen und ihn den Israeliten auszuliefern.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 6, 11, 'Da ergriffen ihn die Diener, führten ihn zum Lager hinaus in die Ebene, brachten ihn von dort ins Gebirge und kamen mit ihm bis an die Quellen, die sich unterhalb Betyluas befanden.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 6, 12, 'Als nun die Männer in der Stadt sie erblickten, ergriffen sie ihre Waffen, zogen zur Stadt hinaus auf den Gipfel des Berges, und alle Schleuderer besetzten den Aufstieg zu ihnen und warfen mit Steinen nach ihnen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 6, 13, 'Da traten jene unter einen Vorsprung des Berges, banden den Achjor, ließen ihn am Fuße des Berges liegen und kehrten zu ihrem Herrn zurück.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 6, 14, 'Die Israeliten aber kamen aus ihrer Stadt hinab, traten an ihn heran, banden ihn los und führten ihn nach Betylua; dort stellten sie ihn vor die Vorsteher der Stadt.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 6, 15, 'Es waren dies damals Ozias, der Sohn Michas aus dem Stamme Simeon, Chabris, der Sohn Gothoniels, und Charmis, der Sohn Melchiels.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 6, 16, 'Darauf riefen sie alle Ältesten der Stadt zusammen, und auch die jungen Männer und die Weiber eilten allesamt herbei zur Gemeindeversammlung. Nachdem sie nun den Achjor in die Mitte ihres Volkes hatten treten lassen, befragte Ozias ihn über das, was geschehen war.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 6, 17, 'Da nahm jener das Wort und teilte ihnen alle Verhandlungen aus dem Kriegsrat des Holofernes mit und alles, was er selbst inmitten der assyrischen Heerführer gesagt und wie Holofernes gegen das Haus Israel geprahlt hatte.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 6, 18, 'Da warf sich das Volk nieder, betete Gott an und rief aus:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 6, 19, '»Herr, Gott des Himmels, beachte ihr übermütiges Verhalten und erbarme dich der Not unseres Volkes und blicke gnädig auf die hin, welche sich heute für dich geheiligt haben!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 6, 20, 'Dann sprachen sie dem Achjor Mut zu und lobten ihn sehr; Ozias aber nahm ihn aus der Versammlung mit in sein Haus und richtete den Ältesten ein Gastmahl zu; und man rief den Gott Israels jene ganze Nacht hindurch um Hilfe an.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 7, 1, 'Am folgenden Tage aber befahl Holofernes seinem ganzen Heere und allen mit ihm verbündeten Mannschaften, gegen Betylua aufzubrechen, die Zugänge zum Berglande zu besetzen und so den Krieg gegen die Israeliten zu eröffnen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 7, 2, 'So brachen denn an diesem Tage alle ihre Kriegsleute auf, und ihre Streitmacht betrug 120000 Mann zu Fuß und 12000 Reiter, ungerechnet den Troß und was an Leuten mit ihnen zog, eine ganz gewaltige Menge.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 7, 3, 'Sie lagerten sich dann in dem Tale unweit Betyluas an der Quelle und dehnten sich aus in die Breite bis Dothaim und Belbaim, und in die Länge von Betylua bis Kyamon, welches Esdrelom gegenüber liegt.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 7, 4, 'Als nun die Israeliten ihre große Zahl sahen, gerieten sie in gewaltige Bestürzung und sagten zueinander: »Nun werden diese das ganze Land auffressen, und weder die hohen Berge, noch die Schluchten, noch die Hügel werden ihre Last tragen können«.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 7, 5, 'Doch griffen sie alle zu den Waffen, zündeten Feuer auf ihren Türmen an und hielten Wache die ganze folgende Nacht hindurch.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 7, 6, 'Am nächsten Tage ließ Holofernes seine ganze Reiterei vor den Augen der Israeliten in Betylua ausziehen,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 7, 7, 'ließ die Zugänge zu ihrer Stadt auskundschaften und die dortigen Wasserquellen aufsuchen, nahm Besitz davon und stellte Abteilungen von Kriegsleuten bei ihnen auf; dann kehrte er persönlich zu seinem Kriegsvolke zurück.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 7, 8, 'Da traten zu ihm alle Obersten der Edomiter und alle Anführer der Moabiter und die Feldherren der Meeresküste und sagten zu ihm:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 7, 9, '»Unser Gebieter wolle doch einen Vorschlag von uns anhören, damit deiner Streitmacht kein Unfall widerfährt.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 7, 10, 'Dieses israelitische Volk setzt nämlich sein Vertrauen nicht auf seine Lanzen, sondern auf die Höhe seiner Berge, auf denen es wohnt, weil es nicht leicht ist, die Berggipfel hier zu erklimmen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 7, 11, 'So führe also jetzt, Gebieter, den Krieg gegen sie nicht so, wie sonst der Krieg in offener Feldschlacht geführt wird; dann wird kein einziger Mann von deinem Heere fallen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 7, 12, 'Bleibe ruhig in deinem Lager, halte alle Leute deines Heeres vom Kampfe zurück und laß deine Knechte nur die Wasserquelle besetzen, die am Fuße des Berges entspringt;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 7, 13, 'denn von dort holen alle Einwohner Betyluas ihr Wasser; der Durst wird sie alsdann umbringen, so daß sie ihre Stadt übergeben müssen. Wir aber und unsere Leute wollen auf die benachbarten Berggipfel hinaufziehen und uns dort lagern, um zu verhindern, daß jemand aus der Stadt entkomme,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 7, 14, 'Sie werden dann samt ihren Weibern und Kindern vor Hunger verschmachten und, ehe noch das Schwert über sie kommt, in den Straßen ihres Wohnorts am Boden liegen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 7, 15, 'Dann kannst du ihnen einen schlimmen Lohn dafür zahlen, daß sie dir Widerstand geleistet haben und dir nicht in Frieden entgegengekommen sind«.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 7, 16, 'Diese ihre Worte fanden den Beifall des Holofernes und aller seiner Diener, und man beschloß, nach diesem Vorschlage zu verfahren.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 7, 17, 'So machte sich denn die Heerschar der Ammoniter, verstärkt durch 5000 Assyrer, auf den Weg, lagerten sich im Tale und besetzten alle Gewässer und Quellen der Israeliten.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 7, 18, 'Ebenso zogen die Edomiter und Ammoniter hinauf und bezogen ein Lager auf den Anhöhen gegenüber Dothaim; eine Abteilung von ihren Leuten sandten sie nach Südosten in die Gegend gegenüber Ekrebel, das nahe bei dem am Bache Mochmur gelegenen Chus liegt. Das übrige Heer der Assyrer aber lagerte in der Ebene und bedeckte das ganze Land; ihre Zelte und das Gepäck bildeten ein Lager mit einer großen Menschenmenge, deren Zahl ganz gewaltig war.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 7, 19, 'Die Israeliten aber riefen den Herrn, ihren Gott, um Hilfe an, denn aller Mut war ihnen entschwunden, weil alle ihre Feinde sie umzingelt hatten und keine Möglichkeit da war, aus ihrer Umschließung zu entkommen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 7, 20, 'Das ganze assyrische Heer aber, Fußvolk, Wagen und Reiter, blieb rings um sie gelagert 34 Tage lang, so daß allen Einwohnern Betyluas alle ihre Wasservorräte ausgingen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 7, 21, 'Auch die Zisternen wurden leer, und sie hatten nicht mehr für einen Tag Wasser, um sich satt zu trinken, weil man ihnen das Wasser kärglich abgemessen zu trinken gab.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 7, 22, 'Da verloren ihre kleinen Kinder alle Lebenskraft, die Frauen und jungen Männer wurden vor Durst ohnmächtig und fielen auf den Straßen der Stadt und in den Durchgängen der Tore nieder und hatten keine Kraft mehr in sich.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 7, 23, 'Da lief die ganze Bevölkerung, Jünglinge, Weiber und Kinder, vor den Häusern des Ozias und der übrigen Vorsteher der Stadt zusammen und riefen allen Ältesten laut die Worte zu:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 7, 24, '»Gott sei Richter zwischen euch und uns! Ihr habt euch schwer an uns verschuldet, daß ihr euch nicht friedlich mit den Assyrern abgefunden habt. Jetzt gibt es keine Hilfe mehr für uns, sondern Gott hat uns in ihre Hände dahingegeben, daß wir vor Durst und großem Unheil vor ihnen hingestreckt am Boden liegen. Ruft sie nun herbei und übergebt die ganze Stadt den Leuten des Holofernes und seiner ganzen Heeresmacht zur Plünderung! Es ist ja das Beste für uns, ihre Beute zu werden; wir werden dann zwar Sklaven sein, aber doch das Leben behalten und brauchen nicht den Tod unserer Kleinen mit unsern Augen angesehen und wie unsere Frauen und Kinder verschmachten. Wir beschwören euch beim Himmel und bei der Erde, bei unserem Gott und dem Herrn unserer Väter, der uns für unsere Sünden und für die Übeltaten unserer Väter straft, daß er am heutigen Tage nicht das eintreten lasse, was wir da ausgesprochen haben!« Und es erhob sich ein lautes und allgemeines Wehklagen inmitten der Versammlung und sie schrieen zu Gott dem Herrn mit lauter Stimme. Da sprach Ozias zu ihnen: »Seid mutig, ihr Brüder! Laßt uns noch fünf Tage aushalten, in denen der Herr, unser Gott, sein Erbarmen uns zuwenden wird; denn er wird uns nicht gänzlich verlassen. Sind diese Tage vergangen, ohne daß uns Hilfe gekommen ist, so will ich eurem Verlangen nachkommen«. Hierauf entließ er die Männer in ihr Lager, und sie verfügten sich auf die Mauern und die Türme der Stadt; die Weiber und Kinder dagegen ließ er sich in ihre Häuser begeben. In der Stadt aber herrschte große Mutlosigkeit.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 8, 1, 'Dieses vernahm damals auch Judith, die Tochter Meraris, des Sohnes des Ox, des Sohnes Josephs, des Sohnes Oziels, des Sohnes Elkias, des Sohnes des Ananias, des Sohnes Gedeons, des Sohnes Raphains, des Sohnes Ahitobs, des Sohnes des Elias, des Sohnes des Helkias, des Sohnes Eliabs, des Sohnes Nathanaels, des Sohnes Salamiels, des Sohnes Sarasadais, des Sohnes Israels.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 8, 2, 'Ihr Gatte Manasse war aus demselben Stamm und Geschlecht gewesen wie sie, war aber in den Tagen der Gerstenernte gestorben.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 8, 3, 'Denn als er bei dem Garbenbinder auf dem Felde stand, hatte er bei dem Glutwind einen Sonnenstich erlitten, hatte sich zu Bett legen müssen und war in seiner Vaterstadt Betylua gestorben; man hatte ihn bei seinen Vätern auf dem Felde zwischen Dothaim und Balamon begraben.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 8, 4, 'Judith war dann als Witwe drei Jahre und vier Monate in ihrem Hause geblieben,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 8, 5, 'hatte sich auf dem Dache ihres Hauses eine Hütte eingerichtet, sich Sacktuch um ihre Hüfte gelegt und ihre Witwenkleidung ohne Unterbrechung beibehalten.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 8, 6, 'Sie fastete an allen Tagen ihrer Witwenschaft außer an den Tagen vor dem Sabbat und an den Sabbaten, an den Neumonden und dem Tage zuvor und an den großen Festen und den Freudentagen des Hauses Israel.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 8, 7, 'Sie war schön von Gestalt und eine reizende Erscheinung. Ihr Gatte Manasse hatte ihr Gold und Silber, Knechte und Mägde, Vieh und Äcker hinterlassen, in deren Besitz sie geblieben war.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 8, 8, 'Niemand konnte ihr etwas Böses nachsagen denn sie war überaus gottesfürchtig.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 8, 9, 'Judith hatte nun die bösen Reden des Volkes gegen den Vorsteher der Stadt vernommen, weil man wegen des Wassermangels mutlos geworden war; auch die ganze Antwort hatte sie gehört, die Ozias den Leuten gegeben hatte, wie er ihnen eidlich angekündigt hatte, er wolle die Stadt den Assyrern nach fünf Tagen übergeben.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 8, 10, 'Da sandte sie ihre Zofe, die über ihr ganzes Hauswesen gesetzt war, und ließ die drei Ältesten der Stadt, Ozias, Chabris und Charmis, zu sich rufen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 8, 11, 'Als sie zu ihr gekommen waren, sagte sie zu ihnen: »Hört mich an, ihr Vorsteher der Bewohner von Betylua! Nicht recht ist die Rede gewesen, die ihr heute an das Volk gerichtet habt, und nicht recht, daß ihr einen Eid zwischen Gott und euch errichtet und euch verpflichtet habt, die Stadt unsern Feinden zu übergeben, wenn der Herr sich nicht in dieser Zeit dazu hinwende, uns Hilfe zu leisten.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 8, 12, 'Ja, wer seid ihr denn, daß ihr am heutigen Tage Gott versucht habt und an Gottes Statt inmitten der Menschenkinder auftretet?');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 8, 13, 'Ja, erforscht nur den allmächtigen Herrn, ihr werdet doch in alle Ewigkeit nichts erkennen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 8, 14, 'Ihr könnt ja nicht einmal die Tiefe eines Menschenherzens ergründen und dessen geheime Gedanken erfassen: wie wollt ihr da Gott, den Schöpfer dieses ganzen Weltalls, erforschen und seinen Sinn erkennen und seine Gedanken verstehen? Nein, meine Brüder! reizt den Herrn, unsern Gott, nicht zum Zorn!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 8, 15, 'Denn wenn er uns in den fünf Tagen nicht helfen will, so hat er doch die Macht, uns zu beschützen, an welchem Tage immer er will, oder aber auch uns vor den Augen unserer Feinde zu vernichten.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 8, 16, 'Sucht ihr aber die Ratschläge des Herrn, unseres Gottes, nicht zu erzwingen; denn Gott läßt sich nicht drohen wie ein Mensch und ist nicht schwankend in seinen Entschlüssen wie ein Menschenkind.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 8, 17, 'Darum laßt uns die Rettung von ihm geduldig erwarten und ihn zu unserer Hilfe anrufen: er wird auf unsern Hilferuf hören, wenn es ihm gefällt.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 8, 18, 'Denn in unseren Geschlechtern ist es weder früher vorgekommen, noch ist es heutigestags der Fall, daß ein Stamm oder eine Familie, ein Gau oder eine Stadt Götter anbetet, die von Menschenhand gemacht sind, wie dies in früheren Zeiten geschehen ist,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 8, 19, 'wofür unsere Väter dem Schwert und der Plünderung preisgegeben und vor unsern Feinden so tief ins Unglück geschleudert worden sind.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 8, 20, 'Wir aber kennen keinen anderen Gott als ihn; darum hoffen wir auch, daß er uns und alle zu unserm Geschlecht Gehörigen nicht unbeachtet lassen wird.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 8, 21, 'Denn wenn unsere Stadt erobert wird, so ist es um ganz Judäa geschehen; dann wird unser Heiligtum geplündert werden, und der Herr wird uns für dessen Entweihung verantwortlich machen,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 8, 22, 'wird den Mord unserer Brüder und die Gefangenschaft der Landesbewohner und die Verwüstung unseres Erblandes uns zur Last legen unter den Völkern, wo immer wir ihnen als Knechte dienen müssen, und wir werden ein Gegenstand der Verachtung und der Schmach für die sein, die als Herren über uns schalten;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 8, 23, 'denn unsere Knechtschaft wird nicht zum Segen über uns ausschlagen, sondern der Herr, unser Gott, wird sie uns zur Schmach werden lassen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 8, 24, 'Nun also, ihr Brüder, laßt uns unsern Brüdern zeigen, daß ihr Leben von uns abhängt und daß das Heiligtum, sowohl der Tempel als auch der Altar, fest auf uns gegründet ist.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 8, 25, 'Im Hinblick auf dies alles laßt uns dem Herrn, unserem Gott, Dank sagen, der uns jetzt versucht, wie er’s auch bei unsern Vätern getan hat.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 8, 26, 'Denkt an alles, was er mit Abraham gemacht und wie er Isaak versucht hat und was alles dem Jakob im syrischen Mesopotamien widerfahren ist, als er die Herden seines Oheims Laban hütete.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 8, 27, 'Denn wie er jene ernstlich geprüft hat zur Erforschung ihres Herzens, so hat er auch uns jetzt nicht gestraft; sondern zur Warnung züchtigt der Herr die, welche ihm nahen«.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 8, 28, 'Da antwortete ihr Ozias: »Alles, was du gesagt hast, hast du mit aufrichtigem Herzen geredet, und niemand wird deinen Worten widersprechen; denn nicht heute erst ist deine Weisheit offenkundig, sondern vom Anfang deines Lebens an hat alles Volk deine Einsicht anerkannt, wie denn ja alles, was du sinnst und denkst, vortrefflich ist. Aber das Volk litt gar sehr unter dem Durst und hat uns gezwungen, so zu tun, wie wir ihnen versprochen haben, und uns durch einen Eid zu binden, den wir nicht brechen werden. Nun aber bete für uns, denn du bist eine fromme Frau, so wird der Herr den Regen senden, der zur Füllung unserer Zisternen nötig ist, damit wir nicht länger Mangel leiden«. Da erwiderte ihnen Judith: »Hört mich an! Eine Tat will ich vollführen, die bei den Angehörigen unsers Volks bis zu den spätesten Geschlechtern gelangen soll. Steht ihr diese Nacht hindurch am Tore; ich will dann mit meiner Zofe hinausgehen, und innerhalb der Tage, nach deren Ablauf ihr die Stadt den Feinden zu übergeben gelobt habt, wird der Herr durch mein Tun Israel gnädig heimsuchen. Fragt nicht, was ich zu tun gedenke; denn ich werde es euch nicht sagen, bis mein Vorhaben zur Ausführung gekommen ist«. Da sagten Ozias und die übrigen Vorsteher zu ihr: »Gehe hin in Frieden! und Gott der Herr sei mit dir, um Rache an unseren Feinden zu nehmen!« Hierauf verließen sie die Hütte (auf dem Dache) und begaben sich auf ihre Posten.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 1, 'Judith aber warf sich auf ihr Angesicht nieder, streute sich Asche aufs Haupt und legte das Sacktuch ab, das sie umgebunden zu tragen pflegte; es war gerade die Zeit, wo zu Jerusalem das Rauchopfer für diesen Abend in das Haus Gottes hineingebracht wurde. Da richtete Judith mit lauter Stimme folgendes Gebet an den Herrn:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 2, '»O Herr, du Gott meines Ahnen Simeon, dem du das Schwert in die Hand gabst, um die Heiden zu strafen, die den Schoß der Jungfrau zur Vergewaltigung aufgedeckt und ihren Schenkel zur Schändung entblößt und ihren Schoß zur Beschimpfung entweiht hatten.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 3, 'Denn obgleich du geboten hattest: ›Dergleichen darf nicht geschehen‹, hatten sie es doch getan; zur Strafe dafür hast du ihre Fürsten der Ermordung preisgegeben und ihr Lager, das sich ihrer Arglist schämte, zum Blutbad gemacht; du hast die Untertanen um der Herrscher willen geschlagen und die Herrscher auf ihren Thronen;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 4, 'du hast ihre Weiber dem Raube preisgegeben und ihre Töchter in Gefangenschaft fallen lassen und all ihr Hab und Gut zur Plünderung deinen geliebten Söhnen gegeben, weil sie ihren Eifer für dich betätigt und die Befleckung ihre Blutes verabscheut und dich um Hilfe angerufen hatten. O Gott, mein Gott, erhöre jetzt auch mich, die ich eine Witwe bin!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 5, 'Du hast ja getan, was vor jenen Begebenheiten geschehen ist, und ebenso, was damals und was später geschehen ist und was jetzt geschieht, und das Zukünftige hast du bedacht, und das du bedacht hast, das geschieht auch,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 6, 'und alle Dinge, die du beschlossen hast, treten auch ein und sprechen: ›Siehe, da sind wir!‹ Denn alle deine Wege sind in Bereitschaft, und dein Gericht ist vorhergesehen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 7, 'Ach! die Assyrer sind gar stark mit ihrer Kriegsmacht, sind stolz auf ihre Rosse und Reiter, trotzen auf die Kraft ihres Fußvolkes, setzen ihre Hoffnung auf Schild und Speer, auf Bogen und Schleuder und wissen nicht, daß du der Herr bist, der die Kriege entscheidet.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 8, '«Herr» ist dein Name: zerbrich ihre Stärke durch deine Macht und schlage ihre Kraft durch deinen Zorn nieder! Sie haben ja beschlossen, dein Heiligtum zu entweihen und das Zelt, da dein herrlicher Name wohnt, zu schänden und mit dem Schwert die Hörner deines Altars abzuschlagen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 9, 'Sieh ihren Übermut an, schleudere deinen Grimm auf ihre Häupter und verleihe meiner Hand, der Hand einer Witwe, Kraft zu meinem Vorhaben!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 10, 'Schlage durch meine trügerischen Lippen den Knecht samt dem Herrn und den Herrn samt seinem Diener, brich ihren Stolz durch die Hand eines Weibes!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 11, 'Denn nicht auf der Menge beruht deine Kraft, und deine Herrschaft nicht auf den Starken; sondern du bist der Gott der Demütigen, der Helfer der Geringen, der Beistand der Schwachen, der Beschützer der Verachteten, der Retter der Hoffnungslosen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 12, 'Ja, ja, du Gott meines Vaters und du Gott deines Eigentumsvolkes Israel, Herr des Himmels und der Erde, Schöpfer des Weltmeeres, König deiner ganzen Schöpfung, erhöre du mein Gebet!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 13, 'Laß meine trügerische Rede ihnen zum Verderben und Unheil werden, da sie ja gegen deinen Bund und dein heiliges Haus, gegen den Berg Zion und den Wohnsitz deiner Kinder Grausames beschlossen haben.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 14, 'Und mache, daß dein ganzes Volk und jeder Stamm zu der klaren Erkenntnis komme, daß du der Gott aller Macht und Stärke bist und daß es keinen andern Beschützer des Volkes Israel gibt als dich!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 15, '');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 1, 'Als sie nun mit ihrem lauten Hilferuf zum Gott Israels zu Ende war und dieses ihr Gebet vollendet hatte,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 2, 'stand sie vom Boden auf, rief ihre Zofe und stieg in das Gemach hinab, in welchem sie sich an den Sabbattagen und an ihren Festen aufzuhalten pflegte.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 3, 'Dort legte sie das Sacktuch ab, das sie sich umgebunden hatte, zog ihre Witwenkleider aus, nahm ein Wasserbad, salbte sich mit kostbarer Salbe, ordnete das Haar ihre Hauptes, setzte sich einen Kopfbund auf und legte ihre Festtagskleider an, die sie bei Lebzeiten ihres Gatten Manasse regelmäßig getragen hatte.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 4, 'Dann tat sie Sandalen an ihre Füße, legte die Schrittkettchen und Armbänder, die Fingerringe und Ohrringe, überhaupt ihren gesamten Schmuck an und machte sich sehr schön, um allen Männern, die sie sehen würden, in die Augen zu fallen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 5, 'Weiter gab sie ihrer Zofe einen Lederschlauch mit Wein und einen Krug mit Öl, füllte einen Beutel mit Mehl und Feigen und reinen Broten, umwickelte alle diese Gefäße sorgfältig und belud ihre Zofe damit.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 6, 'Hierauf gingen sie hinaus nach dem Tore der Stadt Betylua und fanden dort den Ozias und die Stadtältesten Chabris und Charmis stehen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 7, 'Als diese sie erblickten, und zwar so ganz verändert in der äußeren Erscheinung und Kleidung, verwunderten sie sich ob ihrer Schönheit über alle Maßen und sagten zu ihr:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 8, '»Der Gott unserer Väter möge dir vergönnen, Gnade zu finden und dein Vorhaben auszuführen zum Ruhme Israels und zur Verherrlichung Jerusalems!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 9, 'Darauf warf sie sich anbetend vor Gott nieder und sagte zu ihnen: »Laßt mir das Stadttor öffnen, dann will ich das vollführen, wovon ihr mit mir geredet habt«. Da befahlen sie den jungen Männern, ihr das Tor zu öffnen, wie sie begehrt hatte.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 10, 'Als das geschehen war, ging Judith hinaus, und zwar in Begleitung ihrer Dienerin; die Männer in der Stadt aber sahen ihr nach, bis sie den Berg hinabgestiegen war und das Tal durchschritten hatte und sie nicht mehr zu sehen war.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 11, 'Als die beiden nun im Tale geradeaus gingen, begegnete ihr die Vorhut der Assyrer;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 12, 'die hielten sie an und fragten sie: »Wer bist du? woher kommst du, und wohin willst du?« Da antwortete sie: »Ich bin ein hebräisches Weib und fliehe von ihnen weg, weil sie euch bald zum Fraß gegeben werden.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 13, 'Ich bin auf dem Wege zu Holofernes, dem obersten Befehlshaber eures Heeres, um ihm zuverlässigen Bericht zu erstatten und ihm die Möglichkeit anzugeben, wie er sich des ganzen Berglandes bemächtigen kann, ohne daß von seinen Leuten eine einzige lebende Seele verloren geht«.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 14, 'Als nun die Männer sie so reden hörten und ihr Angesicht erblickten, erschien sie ihnen geradezu als ein Wunder von Schönheit, und sie sagten zu ihr:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 15, '»Du hast dein Leben gerettet, indem du dich beeilt hast, zu unserm Herrn herabzukommen. So begib dich denn jetzt zu seinem Zelte; einige von unseren Leuten sollen dich geleiten, bis sie dich ihm persönlich übergeben haben.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 16, 'Wenn du aber vor ihm stehst, so fürchte dich nicht, sondern teile ihm mit, wie du soeben gesagt hast, und er wird dir’s lohnen«.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 17, 'Darauf wählten sie aus ihrer Abteilung hundert Mann zum Geleit für sie und ihre Zofe und führten sie so zum Zelte des Holofernes.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 18, 'Da entstand ein Zusammenlauf in dem ganzen Lager, denn das Gerücht von ihrer Ankunft war in die Zelte gedrungen; daher kam man herbei und umringte sie, während sie draußen vor dem Zelte des Holofernes stand, bis man sie bei ihm angemeldet hatte.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 19, 'Man war über ihre Schönheit erstaunt und war ihretwegen voller Bewunderung der Israeliten, so daß einer zum andern sagte: »Wer könnte dieses Volk verachten, das solche Weiber unter sich hat? Nein, es wäre nicht angebracht, daß auch nur ein einziger Mann von ihnen übrig bliebe; denn die, welche man übrig ließe, könnten die ganze Welt berücken«.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 20, 'Endlich kamen die Leibwächter des Holofernes und alle zu seiner Umgebung Gehörigen heraus und führten sie in das Zelt hinein;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 21, 'Holofernes ruhte gerade auf seinem Lager unter einem Mückennetz, das aus Purpur- und Goldfäden und aus eingewebten Smaragden und anderen kostbaren Edelsteinen bestand. Als man sie bei ihm angemeldet hatte, trat er in das Vorzelt hinaus, wobei silberne Leuchter vor ihm hergetragen wurden. Als dann Judith ihm und den zu seiner Umgebung Gehörigen zu Gesicht kam, verwunderten sich alle über ihre Schönheit. Sie warf sich auf ihr Angesicht nieder und brachte ihm ihre Huldigung dar; doch seine Diener hoben sie auf.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 11, 1, 'Darauf sagte Helofernes zu ihr: »Sei gutes Mutes, Weib, fürchte dich nicht! Ich tue keinem etwas zuleide, der bereit ist, sich Nabuchodonosor, dem Könige der ganzen Erde, zu unterwerfen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 11, 2, 'Ja, hätte dein Volk, das auf diesem Berglande wohnt, mich nicht mißachtet, so hätte ich meinen Speer nicht gegen sie erhoben; sie haben ihr jetziges Geschick sich selbst zuzuschreiben.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 11, 3, 'Aber nun sage mir: warum hast du sie durch die Flucht verlassen und bist zu uns gekommen? Es ist dein Glück, daß du gekommen bist. Sei gutes Mutes! du sollst dein Leben in dieser Nacht behalten und künftighin.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 11, 4, 'Niemand soll dir ein Leid zufügen, sondern man wird dir Gutes erweisen, wie das immer geschieht bei den Untertanen meines Herrn, des Königs Nabuchodonosor«.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 11, 5, 'Da erwiderte Judith ihm folgendermaßen: »Nimm die Worte deiner Magd gnädig an und gestatte deiner Dienerin vor dir zu reden: kein unwahres Wort werde ich meinem Herrn in dieser Nacht berichten;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 11, 6, 'und wenn du den Rat deiner Magd befolgen willst, so wird Gott das Werk im Verein mit dir zu Ende führen, und mein Herr wird sein Vorhaben nicht verfehlen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 11, 7, 'Denn so wahr Nabuchodonosor lebt, der König der ganzen Erde, und so wahr die Macht dessen Bestand hat, der dich entsandt hat, alles, was lebt, zur Ordnung zu bringen: nicht allein Menschen sind ihm durch dein Verdienst untertan, sondern auch die wilden Tiere und die Haustiere und die Vögel des Himmels werden durch deine Tatkraft leben unter Nabuchodonosor und seinem ganzen Hause.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 11, 8, 'Denn wir haben von deiner Weisheit gehört und von den klugen Anschlägen deines Geistes, und aller Welt ist kund geworden, daß du allein im ganzen Königreiche tüchtig bist und leistungsfähig durch deine Einsicht und bewundernswert in der Kriegführung.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 11, 9, 'Was nun die Rede betrifft, die Achjor in deiner Versammlung gehalten hat, so haben wir das, was er gesagt hat, vernommen; denn die Bewohner von Berylua haben ihn am Leben gelassen, und er hat ihnen alles mitgeteilt, was er vor dir geredet hat.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 11, 10, 'Darum, Herr und Gebieter, laß seine Rede nicht unbeachtet, sondern nimm sie dir zu Herzen, denn sie ist wahr. Unser Volk wird nämlich nicht gestraft, und das Schwert vermag nichts wider es, wenn es sich nicht gegen seinen Gott versündigt.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 11, 11, 'Doch jetzt, damit mein Herr nicht vertrieben werde und unverrichteter Sache abziehen müsse, sondern der Tod über sie hereinbreche, so hat die Sünde Macht über sie gewonnen, wodurch sie ihren Gott erzürnen werden, sobald sie etwas Unstatthaftes begehen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 11, 12, 'Nachdem ihnen nämlich die Lebensmittel ausgegangen und das Wasser sparsam geworden ist, haben sie beschlossen, Hand an ihre Haustiere zu legen, und haben den Entschluß gefaßt, alles zu verzehren, dessen Genuß Gott ihnen durch sein Gesetz verboten hat.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 11, 13, 'Auch die Erstlinge der Feldfrucht und die Zehnten von Wein und Öl, die sie den in Jerusalem vor dem Angesicht unseres Gottes stehenden Priestern geheiligt und aufbewahrt hatten, haben sie beschlossen aufzuzehren, lauter Dinge, die nicht einmal mit den Händen zu berühren irgend jemandem aus dem Volke gestattet ist.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 11, 14, 'Weil nun die Einwohner von Jerusalem dasselbe getan haben, so haben sie Männer dorthin gesandt, die ihnen von dem Hohen Rate die Erlaubnis dazu erwirken sollen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 11, 15, 'Sobald ihnen diese erteilt ist und sie danach getan haben, werden sie dir noch an demselben Tage zur Vernichtung preisgegeben werden.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 11, 16, 'Darum bin ich, deine Magd, nachdem ich dies alles erfahren habe, von ihnen weggeflohen, und Gott hat mich hergesandt, mit dir Taten zu vollbringen, über die alle Welt, wer davon hört, sich entsetzen wird.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 11, 17, 'Denn deine Magd ist gottesfürchtig und dient Tag und Nacht dem Gott des Himmels. Und zunächst werde ich bei dir bleiben, mein Herr, doch bei Nacht wird deine Magd in die Felsschlucht hinausgehen, um zu Gott zu beten; er wird mir dann kundtun, wann sie ihre Sünden begangen haben; dann will ich kommen und es dir anzeigen; und du wirst mit deiner ganzen Kriegsmacht ausziehen, und keiner von ihnen wird dir entgegentreten. Ich werde dich dann mitten durch Judäa führen bis vor Jerusalem und will deinen Stuhl mitten in der Stadt aufstellen, und du sollst sie wie Schafe treiben, die keinen Hirten haben, und kein Hund soll auch nur ein Knurren gegen dich hören lassen. Denn dies ist mir durch Offenbarung mitgeteilt und verkündigt worden, und ich bin hergesandt, es dir kundzutun«. Ihre Rede fand den Beifall des Holofernes und seiner ganzen Umgebung; sie bewunderten die Weisheit der Judith und sagten: »In der ganzen Welt, von einem Ende bis zum andern, gibt es kein Weib, das diesem gleichkommt an schönem Aussehen und verständiger Rede«. Holofernes aber sagte zu ihr: »Gott hat gut daran getan, daß er dich vor dem Volke hergesandt hat, damit der Sieg uns zuteil werde, dagegen denen, die meinen Zorn verachtet haben, die Vernichtung. Und nun: du bist schön von Gestalt und verstehst trefflich zu reden; wenn du nun deine Verheißung zur Ausführung bringst, so soll dein Gott auch der meine sein, und du sollst im Palast des Königs Nabuchodonosor wohnen und berühmt sein auf der ganzen Erde«.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 1, 'Darauf ließ er sie in den Raum führen, wo sein Silbergeschirr aufgestellt war, und ließ ihr von seinen eigenen Speisen eine Mahlzeit auftragen und von seinem eigenen Wein zu trinken reichen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 2, 'Doch Judith sagte: »Ich werde nichts davon genießen, damit ich mich nicht versündige; vielmehr soll mir von den Vorräten gereicht werden, die ich habe mitbringen lassen«.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 3, 'Da sagte Holofernes zu ihr: »Wenn aber deine mitgebrachten Vorräte aufgezehrt sind, woher sollen wir dir Gleiches beschaffen? Von deinem Volke ist ja niemand bei uns«.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 4, 'Da gab Judith ihm zur Antwort: »So wahr du lebst, mein Herr! deine Magd wird ihre Vorräte nicht aufgezehrt haben, bis der Herr seinen Beschluß durch mich zur Ausführung gebracht hat«.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 5, 'Hierauf führten die Diener des Holofernes sie in das für sie bestimmte Zelt, und sie schlief bis Mitternacht. Um die Zeit der Morgenwache aber stand sie auf,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 6, 'sandte zu Holofernes und ließ ihm sagen: »Mein Herr wolle Befehl geben, daß man mich, seine Magd, hinausgehen lasse, damit ich mein Gebet verrichte«.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 7, 'Da gebot Holofernes seinen Leibwächtern, sie nicht zu hindern. So blieb sie drei Tage lang im Lager und ging jede Nacht in das Tal von Betylua und nahm ihre Abwaschungen im Lager an der Wasserquelle vor.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 8, 'Wenn sie dann (aus dem Wasser) hinausgestiegen war, bat sie den Herrn, den Gott Israels, er möge ihr den Weg zur Rettung ihrer Volksgenossen bahnen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 9, 'So kehrte sie rein zurück und blieb in ihrem Zelte, bis sie gegen Abend ihre Speise zu sich nahm.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 10, 'Am vierten Tage aber gab Holofernes seinen Dienern allein ein Gastmahl und lud keinen von den diensttuenden Beamten zur Teilnahme ein.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 11, 'Dabei sagte er zu Bagoas, dem Verschnittenen, der sein ganzes Hauswesen zu verwalten hatte: »Geh doch hin und berede die Hebräerin, die bei dir ist, daß sie zu uns kommt und mit uns ißt und trinkt.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 12, 'Es würde ja doch schimpflich für uns sein, wenn wir ein solches Weib gehen ließen, ohne uns mit ihr eingelassen zu haben; sie würde uns geradezu auslachen, wenn wir sie nicht umarmten«.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 13, 'Da ging Bagoas aus dem Zelte des Holofernes zu ihr und sagte: »Es verschmähe das schöne Mädchen hier doch nicht, zu meinem Herrn zu kommen und sich von ihm Ehre antun zu lassen und mit uns in Fröhlichkeit ein Glas Wein zu trinken und es heute so zu machen wie alle anderen assyrischen Mädchen, die im Palast Nabuchodonosors anwesend sind«.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 14, 'Da antwortete ihm Judith: »Wie könnte ich die Aufforderung meines Herrn zurückweisen? Ja, alles, was meinem Herrn wohlgefällig ist, werde ich mich beeilen, zu tun; das soll mir eine Freude sein bis zu meinem Todestage«.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 15, 'Hierauf stand sie auf, legte ihre schönsten Gewänder an und schmückte sich mit allem Schmuck, den die Frauenwelt anwendet. Ihre Dienerin ging hin und breitete für sie dem Holofernes gegenüber auf dem Boden die Teppiche aus, die sie von Bagoas für ihren täglichen Gebrauch erhalten hatte, um auf ihnen liegend die Mahlzeit einzunehmen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 16, 'Als nun Judith hereinkam und sich zum Essen gelagert hatte, da geriet Holofernes bei ihrem Anblick in Entzücken, und seine Gefühle wurden stürmisch erregt; es hatte ihn auch früher schon leidenschaftlich gelüstet, mit ihr zusammen zu sein, und von dem Tage an, wo er sie zuerst gesehen, hatte er auf eine günstige Gelegenheit gelauert, sie zu verführen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 17, 'Nun sagte Holofernes zu ihr: »Trinke nun und sei lustig mit uns!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 18, 'Judith antwortete ihm: »Gewiß, trinken will ich, o Herr; denn heute hat mein Leben eine so hohe Ehrung erfahren wie noch nie zuvor seit dem Tage meiner Geburt«.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 19, 'Sie nahm dann die Speisen, die ihre Dienerin zubereitet hatte, und aß und trank vor seinen Augen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 20, 'Da wurde Holofernes durch ihr Verhalten hocherfreut und trank sehr vielen Wein, mehr als er jemals an einem Tage seit seiner Geburt getrunken hatte.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 21, '');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 1, 'Als es nun spät geworden war, beeilten sich seine Gäste, die Beamten, aufzubrechen. Bagoas schloß das Zelt von außen und entließ die Anwesenden aus dem Zusammensein mit seinem Herrn, und sie suchten ihre Nachtlager auf, denn sie waren alle infolge der langen Dauer des Mahles müde geworden.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 2, 'So blieb denn Judith allein im Zelte zurück mit Holofernes, der, vom Wein überwältigt, vornüber auf sein Lager gesunken war.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 3, 'Nun hatte Judith ihrer Magd befohlen, draußen vor ihrem Schlafgemach stehen zu bleiben und, wie täglich, auf ihr Herauskommen zu warten; sie hatte nämlich gesagt, sie würde zum Gebet herauskommen, und auch dem Bagoas hatte sie das Gleiche gesagt.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 4, 'Als nun alle von ihr weggegangen waren und niemand mehr im Schlafgemach anwesend war, weder groß noch klein, trat Judith an sein Lager heran und betete still in ihrem Herzen: »Herr, Gott aller Macht! blicke in dieser Stunde auf das, was meine Hände vornehmen zur Verherrlichung Jerusalems!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 5, 'Denn jetzt ist es an der Zeit, daß du dich deines Eigentumsvolkes annimmst und mein Vorhaben ausführst zum Verderben der Feinde, die sich gegen uns erhoben haben!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 6, 'Hierauf trat sie an die Säule des Bettes, die zu Häupten des Holofernes stand, nahm sein Schwert von dort herab,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 7, 'näherte sich dem Lager und faßte ihn bei den Haaren, indem sie betete: »Stärke mich, du Gott Israels, an diesem Tage!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 8, 'Hierauf schlug sie ihn zweimal mit aller ihrer Kraft in den Hals und hieb ihm den Kopf ab.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 9, 'Dann wälzte sie seinen Leib vom Bette herab, riß das Mückennetz von den Stangen, ging nach kurzer Weile hinaus und übergab den Kopf des Holofernes ihrer Zofe,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 10, 'die ihn in ihren Speisesack warf. Alsdann gingen sie beide nach ihrer Gewohnheit zusammen hinaus zum Gebet. Sie durchschritten das Lager, umwanderten das Tal dort, stiegen den Berg von Betylua hinauf und gelangten an das Stadttor.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 11, 'Von ferne schon rief Judith den Torwächtern zu: »Das Tor auf! das Tor auf! Mit uns ist Gott, unser Gott, der immer noch Kraft in Israel und Sieg über die Feinde zu wirken vermag, wie er es auch heute getan hat!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 12, 'Als nun die Männer der Stadt ihre Stimme vernahmen, stiegen sie in aller Eile zum Stadttor hinab und riefen die Ältesten der Stadt zusammen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 13, 'Da kam alles herzugelaufen, klein und groß; denn es schien ihnen unglaublich, daß sie wiedergekommen sei. Sie öffneten nun das Tor und ließen die beiden ein, zündeten dann ein Feuer an, um Helligkeit zu schaffen, und umringten sie.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 14, 'Sie aber rief ihnen mit lauter Stimme zu: »Lobt Gott, lobet! Lobt Gott, der dem Hause Israel sein Erbarmen nicht entzogen, sondern unsere Feinde in dieser Nacht durch meine Hand geschlagen hat!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 15, 'Hierauf zeigte sie ihnen den Kopf, den sie aus dem Sack hervorgeholt hatte, und sagte zu ihnen: »Seht, das ist der Kopf des Holofernes, des obersten Befehlshabers des assyrischen Heeres, und seht, das ist das Mückennetz, unter dem er in seiner Trunkenheit lag; der Herr hat ihn durch die Hand eines Weibes erschlagen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 16, 'So wahr der Herr lebt, der mich auf meinem Wege behütet hat: mein Gesicht hat ihn verführt zu seinem Verderben, aber er hat sich nicht an mir vergehen und keine Schmach und Schande über mich bringen können!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 17, 'Da geriet das ganze Volk in großes Erstaunen, sie knieten nieder, beteten Gott an und riefen einmütig aus: »Gepriesen seist du, unser Gott, der du heute die Feinde deines Volkes vernichtet hast!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 18, 'Ozias aber sagte zu ihr: »Gesegnet seist du, meine Tochter, vom höchsten Gott mehr als alle Weiber auf Erden, und gesegnet sei Gott der Herr, der Schöpfer des Himmels und der Erde, der es dir hat gelingen lassen, den Kopf des Anführers unserer Feinde abzuschlagen!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 19, 'Denn deine Hoffnung wird nicht schwinden aus den Herzen der Menschen, solange sie der Macht Gottes eingedenk bleiben in Ewigkeit.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 20, 'Möge Gott dir dieses zu ewigem Ruhme gedeihen lassen, daß er dich mit Wohltaten segne zum Lohn dafür, daß du dein Leben nicht geschont hast um der Erniedrigung deines Volkes willen, sondern unserm Fall dich entgegengestellt hast, indem du vor unserm Gott auf rechtem Wege wandeltest!« Und alles Volk rief: »So sie es! so sei es!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 21, '');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 22, '');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 23, '');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 24, '');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 25, '');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 26, '');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 27, '');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 28, '');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 29, '');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 30, '');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 31, '');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 14, 1, 'Darauf sagte Judith zu ihnen: Hört mich an, meine Brüder! Nehmt diesen Kopf und hängt ihn an die Brustwehr eurer Mauer.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 14, 2, 'Und wenn der Morgen anbricht und die Sonne über der Erde aufgeht, so nehmt allesamt eure Kriegswaffen und zieht, alle kriegstüchtigen Männer, aus der Stadt hinaus; setzt einen Anführer über sie, als ob ihr in die Ebene gegen die Vorhut der Assyrer hinabziehen wolltet. Doch ihr braucht nicht hinabzuziehen,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 14, 3, 'denn jene werden ihre Waffen ergreifen und in ihr Lager abmarschieren; dort werden sie die Feldherren des assyrischen Heeres wecken und zum Zelte des Holofernes laufen, ihn aber nicht finden; infolge davon werden sie erschrecken und die Flucht vor euch ergreifen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 14, 4, 'Dann verfolgt ihr sie im Verein mit allen Bewohnern des Landes Israel und haut sie auf allen Wegen nieder.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 14, 5, 'Bevor ihr aber dieses tut, ruft mir den Ammoniter Achjor; er soll den Mann sehen und erkennen, der das Haus Israel verachtet und ihn selbst zu uns als zum Tode geschickt hat».');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 14, 6, 'Man rief also den Achjor aus dem Hause des Ozias. Als er kam und den Kopf des Holofernes in der Hand eines Mannes unter dem versammelten Volke sah, fiel er vornüber zu Boden und verlor die Besinnung.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 14, 7, 'Als man ihn dann aufhob, warf er sich vor Judith nieder, bezeigte ihr seine Huldigung und rief aus: »Gepriesen seist du in allen Hütten Israels und unter allen Völkern, welche erschrecken werden, wenn sie deinen Namen hören.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 14, 8, 'Und nun erzähle mir doch alles, was du in diesen Tagen getan hast«. Da erzählte ihm Judith, mitten unter dem Volke stehend, alles was sie getan hatte seit dem Tage ihres Weggangs bis jetzt, wo sie mit ihnen redete.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 14, 9, 'Als sie ihren Bericht beendet hatte, brach das Volk in lauten Jubel aus und ließ ein Freudengeschrei in der ganzen Stadt erschallen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 14, 10, 'Als Achjor aber alles sah, was der Gott Israels vollbracht hatte, glaubte er fest an diesen Gott; er ließ sich beschneiden und wurde in das Haus Israel aufgenommen bis auf diesen Tag.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 14, 11, 'Als nun der Morgen anbrach, hängten sie den Kopf des Holofernes an die Mauer, ergriffen dann Mann für Mann ihre Waffen und zogen in Scharen nach den Zugängen zum Berge.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 14, 12, 'Als die Assyrer sie erblickten, schickten sie Boten an ihre Anführer; diese begaben sich zu den Feldherren und Obersten und zu allen ihren Hauptleuten.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 14, 13, 'Die verfügten sich zum Zelte des Holofernes und sagten zu dem Hausmarschall: »Wecke doch unsern Herrn, denn das Knechtsgesindel wagt es zum Kampfe mit uns herabzukommen, um völlig vernichtet zu werden«.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 14, 14, 'Bagoas ging also hinein und klopfte am Vorhang des Zeltes; er nahm nämlich an, Holofernes schlafe bei der Judith.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 14, 15, 'Da aber niemand sich hören ließ, schob er den Vorhang zurück, trat in das Schlafgemach und fand ihn tot am Fußschemel hingestreckt daliegend mit abgehauenem Kopfe.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 14, 16, 'Da erhob er ein lautes Geschrei mit Weinen und Wehklagen und Geheul und zerriß seine Kleider. Dann eilte er in das Zelt, wo Judith gewohnt hatte, und als er sie dort nicht fand, stürzte er unter das Kriegsvolk hinaus und schrie: »Dieses Knechtsgesindel hat Verrat geübt! Ein einziges hebräisches Weib hat Schande über das Haus des Königs Nabuchodonosor gebracht! Ach, da liegt Holofernes am Boden ohne Kopf!« Als die Anführer des assyrischen Heeres diese Worte vernahmen, zerrissen sie ihre Kleider und waren ganz fassungslos; Wehklagen und lautes Geschrei erscholl von ihnen inmitten des Lagers.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 1, 'Als nun die Kriegsleute in den Zelten das erfuhren, gerieten sie über das Geschehene in Entsetzen;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 2, 'Furcht und Zittern befiel sie; niemand blieb noch mit einem andern zusammen, sondern sie stoben allzumal auseinander und flohen auf allen Wegen in der Ebene und im Berglande.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 3, 'Auch die Mannschaften, die im Berglande rings um Betylua gelagert waren, ergriffen die Flucht. Da fielen die Israeliten, wer nur immer die Waffen führen konnte, überall über sie her,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 4, 'und Ozias schickte nach Betomasthaim, Chobai und Chola und in das ganze israelitische Gebiet Boten, um dort die bisher erlangten Erfolge zu melden und zu erreichen, daß alle sich auf die Feinde zu deren Vernichtung stürzten.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 5, 'Als die Israeliten das vernahmen, fielen sie allzumal über sie her und schlugen sie bis Choba. Ebenso stellten sich auch die Mannschaften aus Jerusalem und aus dem ganzen Berglande ein; denn man hatte ihnen Kunde von den Vorkommnissen im Lager ihrer Feinde gegeben, und auch die in Gilead und Galiläa überflügelten die Fliehenden und brachten ihnen schwere Verluste bei bis über Damaskus und dessen Gebiet hinaus.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 6, 'Was aber von Einwohnern in Betylua zurückgeblieben war, warf sich auf das assyrische Lager, plünderte es und machte reiche Beute;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 7, 'und als die Israeliten vom Kampfe heimkehrten, bemächtigten sie sich des Restes; und auch die Dörfer und Gehöfte im Berglande sowie in der Ebene gewannen reiche Beute, denn es war eine ungeheure Menge.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 8, 'Auch der Hohepriester Jojakim und der Hohe Rat der Israeliten, die in Jerusalem wohnten, kamen, um das Herrliche zu sehen, das der Herr an Israel getan hatte, und um Judith zu besuchen und freundlich zu begrüßen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 9, 'Als sie nun in ihr Haus eingetreten waren, sprachen sie allesamt ihre hohe Anerkennung gegen sie aus mit den Worten: »Du bist der Ruhm Jerusalems, du bist der hohe Stolz Israels, du bist die schöne Zierde unsers Volkes!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 10, 'Du hast dies alles mit eigener Hand vollbracht und dir hohe Verdienste um Israel erworben, an denen Gott sein Wohlgefallen haben möge! Gesegnet seist du von dem allmächtigen Herrn für alle Ewigkeit!« Und alles Volk rief: »So sei es!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 11, 'Dreißig Tage lang war das ganze Volk mit der Plünderung des Lagers beschäftigt, und man gab der Judith das Zelt des Holofernes mit dem gesamten Silbergeschirr, Bettwerk, Becken und allen sonstigen Geräten. Sie nahm die Sachen und belud ihr Maultier damit, ließ dann ihre Wagen anspannen und packte alles darauf.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 12, 'Und aus ganz Israel liefen die Frauen zusammen, um sie zu sehen; sie priesen sie und führten ihr zu Ehren Reigentänze auf. Da nahm Judith Laubzweige in die Hände und gab sie den Frauen, die bei ihr waren.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 13, 'Auch bekränzte sie sich mit Ölzweigen, sie und die Frauen, die bei ihr waren; dann schritt sie an der Spitze des ganzen Volkes als Führerin aller Frauen dahin, den Reigen tanzend, und alle israelitischen Männer folgten ihr in Waffen, bekränzt und mit Lobliedern im Munde.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 14, '');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 15, '');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 16, '');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 16, 1, 'Judith hob dann folgendes Dankgebet vor ganz Israel an, und das ganze Volk stimmte in dieses Loblied mit ein, Judith sprach:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 16, 2, 'Stimmt meinem Gott zu Ehren ein Lied an mit Pauken, singet meinem Herrn mit Zimbeln! Laßt ihm ein neues Lied ertönen, erhebt seinen Namen und ruft ihn an!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 16, 3, 'Denn der Herr ist ein Gott, der Kriegen ein Ende macht, denn in sein Lager inmitten seines Volkes hat er mich gerettet aus meiner Verfolger Hand.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 16, 4, 'Der Assyrer kam von den Bergen im Norden, er kam mit vielen Tausenden seiner Streitmacht; ihre Menge erschöpfte die Bäche, und ihre Rosse bedeckten die Hügel. Er gedachte, meine Gefilde zu verbrennen, meine jungen Männer mit dem Schwert zu töten, meine Säuglinge zu Boden zu schleudern, meine Kindlein als Beute hinzugeben und meine Jungfrauen wegzuschleppen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 16, 5, 'Aber der Herr, der Allgebieter, hat sie vernichtet durch eines Weibes Hand.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 16, 6, 'Denn nicht durch Jünglinge ist ihr Gebieter gefallen, auch nicht Söhne von Titanen haben ihn erschlagen, noch gewaltige Riesen ihn angegriffen; nein, Judith, die Tochter Meraris, hat ihn durch ihres Angesichts Schönheit bezwungen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 16, 7, 'Denn ihre Witwenkleider legte sie ab, um den Bedrängten Israels aufzuhelfen; sie salbte ihr Antlitz mit kostbarem Öl');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 16, 8, 'und flocht ihr Haar unter dem Kopfbund und legte ein leinenes Kleid an, um ihn zu berücken.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 16, 9, 'Ihre Sandalen entzückten seine Augen, ihre Schönheit nahm seine Sinne gefangen: – das Schwert durchschnitt ihm den Hals.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 16, 10, 'Es schauderte die Perser ob ihrer Kühnheit, und die Meder waren ob ihres Muts entsetzt.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 16, 11, 'Da frohlockten meine Verzagten, und meine Schwachen jauchzten laut. Sie aber wurden in Angst versetzt, erhoben lautes Wehgeschrei und flohen davon.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 16, 12, 'Die Söhne junger Weiber durchbohrten sie und schlugen sie nieder wie flüchtige Sklaven; sie fielen durch die Heerscharen meines Herrn.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 16, 13, 'Singen will ich meinem Gott ein neues Lied: Herr, groß bist du und ruhmreich, wunderbar an Kraft, unübertrefflich.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 16, 14, 'Dir muß dienen deine ganze Schöpfung, denn du gebotst, da trat sie ins Dasein; du sandtest deinen Geist aus, der bildete (alle Geschöpfe), und keines ist da, das deinem Geheiß widerstände.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 16, 15, 'Denn Berge werden auf ihrem Grunde wanken samt den Wassern, Felsen vor deinem Anblick zerschmelzen wie Wachs; aber denen, die dich fürchten, – ihnen bist du gnädig.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 16, 16, 'Denn geringen Wert hat jegliches Opfer lieblichen Wohlgeruchs und wertlos ist dir alles Fett des Brandopfers; doch wer den Herrn fürchtet, ist immerdar groß.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 16, 17, 'Wehe den Heiden, die sich wider mein Volk erheben! Der Herr, der Allgebieter, wird sie strafen am Tage des Gerichts; Feuer und Würmer wird er in ihre Leiber geben, daß sie heulen vor Schmerzen in Ewigkeit.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 16, 18, 'Als sie dann in Jerusalem angekommen waren, beteten sie Gott an, und nachdem das Volk sich gereinigt hatte, brachten sie ihre Brandopfer und ihre freiwilligen Gaben und Geschenke dar.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 16, 19, 'Judith legte alles, was das Volk ihr von den Gerätschaften des Holofernes geschenkt hatte, im Heiligtum nieder; auch das Mückennetz, das sie aus dem Schlafzimmer des Holofernes mitgenommen hatte, weihte sie Gott als Geschenk.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 16, 20, 'Das Volk aber überließ sich der Freude in Jerusalem vor dem Heiligtum drei Monate lang; und Judith blieb während dieser Zeit bei ihnen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 16, 21, 'Als dann nach diesen Tagen jeder in seiner Heimat zurückkehrte, begab sich auch Judith wieder nach Betylua und lebte dort auf ihrer Besitzung; sie blieb, solange sie lebte, berühmt im ganzen Lande.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 16, 22, 'Viele wünschten sie als Gattin zu besitzen, aber sie ging keine zweite Ehe ein, nachdem ihr Gatte Manasse gestorben und zu seinen Vätern versammelt war.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 16, 23, 'Sie lebte noch sehr lange und wurde im Hause ihres Mannes 105 Jahre alt. Ihrer Zofe schenkte sie die Freiheit. Sie starb in Betylua, und man begrub sie in dem Felsengrab ihres Mannes Manasse.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 16, 24, 'Das Haus Israel betrauerte sie sieben Tage lang. Vor ihrem Tode hatte sie ihre Habe unter die nächsten Verwandten ihres Mannes Manasse und ihre eigenen Angehörigen verteilt.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 16, 25, 'Und solange sie lebte und noch lange Zeit nach ihrem Tode gab es keinen mehr, der die Israeliten schreckte.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 16, 26, '');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 16, 27, '');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 16, 28, '');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 16, 29, '');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 16, 30, '');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 16, 31, '');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 1, 'Gewinnt die Gerechtigkeit lieb, ihr Herrscher auf Erden! denkt an den Herrn in Aufrichtigkeit und sucht ihn in Einfalt des Herzens!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 2, 'Denn er läßt sich finden von denen, die ihn nicht versuchen, und offenbart sich denen, die ihm nicht mißtrauen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 3, 'Denn verkehrte Gedanken führen von Gott ab, und seine Allmacht, wenn sie angezweifelt wird, straft die Toren');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 4, 'Denn in eine bösgesinnte Seele kehrt die Weisheit nicht ein und nimmt ihre Wohnung nicht in einem der Sünde dienstbaren Leibe.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 5, 'Denn der heilige Geist der Zucht meidet die Falschheit; er hält sich fern von törichten Gedanken und wird verscheucht, wenn Ungerechtigkeit aufkommt.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 6, 'Denn ein menschenfreundlicher Geist ist die Weisheit und läßt auch den Gotteslästerer nicht ungestraft ob der Schuld seiner Lippen; denn Gott ist Zeuge seiner Nieren, er ist der wahrhaftige Beobachter seines Herzens und der Hörer seiner Reden.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 7, 'Denn der Geist des Herrn erfüllt den Erdkreis, und er, der das All umfaßt, hat Kenntnis von jedem gesprochenen Wort.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 8, 'Darum bleibt keiner verborgen, der Unrechtes redet, und die strafende Gerechtigkeit geht an ihm nicht vorüber.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 9, 'Denn über die Anschläge des Gottlosen findet eine Untersuchung statt, und die Kunde von seinen Reden kommt vor den Herrn zur Bestrafung seiner Verfehlungen;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 10, 'denn sein eifersüchtiges Ohr hört alles, und auch das leiseste Murren bleibt ihm nicht verborgen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 11, 'Hütet euch also vor unnützem Murren und bewahrt die Zunge vor Lästerrede; denn auch heimliches Gerede geht nicht ungestraft hin, und ein lügnerischer Mund vernichtet die Seele.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 12, 'Trachtet nicht nach dem Tode durch die Verirrung eures Lebens und zieht nicht das Verderben durch euer eigenes Tun herbei;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 13, 'denn Gott hat den Tod nicht geschaffen und hat keine Freude am Untergang der Lebenden.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 14, 'Denn alle Dinge hat er zum Sein geschaffen, und alles in der Welt Erzeugte ist zum Heil da; in keinem findet sich das Gift des Verderbens, und das Totenreich hat nicht die Herrschaft auf Erden.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 15, 'Denn die Gerechtigkeit ist unsterblich, [die Ungerechtigkeit aber führt den Tod herbei].');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 16, 'Die Gottlosen aber rufen den Tod herbei durch ihre Taten und Reden; sie halten ihn für einen Freund und verzehren sich in Sehnsucht nach ihm, sie schließen einen Bund mit ihm, weil sie es wert sind, ihm als Beute zuzufallen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 2, 1, 'Sie sagen nämlich bei sich selbst (oder zueinander), indem sie verkehrt urteilen: »Kurz und mühselig ist unser Leben; wenn es mit dem Menschen zu Ende geht, gibt es kein Heilmittel, und bekannt ist uns keiner, der aus der Unterwelt gerettet hätte.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 2, 2, 'Denn durch Zufall sind wir entstanden, und nachher werden wir sein, als wären wir nie dagewesen; denn Dunst ist der Odem in unserer Nase und das Denken nur ein Funke, der durch die Bewegung unseres Herzens entsteht;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 2, 3, 'erlischt dieser Funke, so wird der Leib zu Asche, und der Geist verfliegt wie dünne Luft.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 2, 4, 'Selbst unser Name gerät mit der Zeit in Vergessenheit, und niemand gedenkt mehr unserer Taten; unser Leben geht vorüber wie die Spur einer Wolke und wird verweht wie Nebel, den die Strahlen der Sonne verscheuchen und den ihre Wärme zum Sinken bringt.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 2, 5, 'Ein Schatten, der vorüberzieht, das ist unser Leben, und eine Wiederkehr unseres Endes gibt es nicht; denn fest versiegelt ist’s, und zurück kommt keiner«.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 2, 6, '»So kommt denn und laßt uns die Güter genießen, die uns zu Gebote stehen, und laßt uns eifrig die Welt ausnützen, da wir noch jung sind!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 2, 7, 'Mit kostbarem Wein und mit Salben wollen wir uns reichlich bedenken, und keine Frühlingsblume soll ungepflückt bleiben;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 2, 8, 'mit Rosenknospen wollen wir uns bekränzen, ehe sie verblühen, [keine Aue soll es geben, die wir nicht schwelgend durchstreifen]!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 2, 9, 'Keiner von uns halte sich fern von unserem Wohlleben; überall sollen die Spuren unseres Frohsinns zurückbleiben; denn das ist unser Teil und unser Los.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 2, 10, 'Laßt uns gegen den armen Gerechten gewalttätig vorgehen, gegen keine Witwe Schonung üben und dem grauen Haar des hochbetagten Greises keine Achtung beweisen!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 2, 11, 'Nein, unsere Kraft soll der Maßstab für unser Rechtsverfahren sein, denn was schwach ist, erweist sich als wertlos.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 2, 12, 'Dem Gerechten wollen wir aufsässig sein, weil er uns unbequem ist und unserm Tun entgegentritt, weil er uns Übertretungen des Gesetzes vorhält und uns Verfehlungen gegen die Zucht zum Vorwurf macht.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 2, 13, 'Er rühmt sich, Gotteserkenntnis zu besitzen, und nennt sich selbst einen Gottesknecht.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 2, 14, 'Er ist für uns eine beständige Anklage unserer Denkweise geworden, lästig ist er uns schon durch seinen Anblick;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 2, 15, 'denn seine Lebensweise weicht von der aller anderen ab, und sein ganzes Verhalten ist völlig verschieden.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 2, 16, 'Wir gelten ihm als falsche Münze, und er hält sich fern von unserm Tun und Lassen wie von Schmutz. Er preist das Endlos der Gerechten glücklich und prahlt mit Gott als seinem Vater.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 2, 17, 'Nun, wir wollen sehen, ob er mit seinen Worten recht hat, und wollen abwarten, wie sein Ausgang sich gestalten wird.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 2, 18, 'Denn ist der Gerechte wirklich ein Kind Gottes, so wird der ihm Beistand leisten und ihn aus der Gewalt seiner Widersacher erretten.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 2, 19, 'Mit Hohn und Mißhandlung wollen wir ihn auf die Probe stellen, um seine Sanftmut kennen zu lernen und seine Standhaftigkeit in Leiden zu prüfen;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 2, 20, 'zu schmachvollem Tode wollen wir ihn verurteilen, denn Rettung wird ihm ja, wie er behauptet, zuteil werden«.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 2, 21, 'So denken sie und gehen daher irre, denn ihre Bosheit macht sie blind;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 2, 22, 'sie haben keine Kenntnis von Gottes Geheimnissen, haben keine Hoffnung auf einen Lohn für die Frömmigkeit und wollen nichts wissen von einem Ehrenpreis für unsträfliche Seelen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 2, 23, 'Denn Gott hat den Menschen zur Unvergänglichkeit geschaffen und ihn zum Abbild seines eigenen Wesens gemacht;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 2, 24, 'aber durch den Neid des Teufels ist der Tod in die Welt gekommen, den die zu schmecken bekommen, welche jenem angehören.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 2, 25, '');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 3, 1, 'Die Seelen der Gerechten aber sind in Gottes Hand, und keine Qual berührt sie;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 3, 2, 'sie scheinen tot zu sein nach der Meinung der Toren, ihr Dahingang wird als ein Unglück angesehen');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 3, 3, 'und ihre Trennung von uns als eine Vernichtung; sie aber sind im Frieden.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 3, 4, 'Denn wenn sie auch nach der Ansicht der Menschen gestraft wurden, so war doch ihre Hoffnung ganz vom Unsterblichkeitsglauben erfüllt;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 3, 5, 'und nachdem sie eine kurze Leidenszeit überstanden haben, werden sie mit hohem Glück gesegnet werden, denn Gott hat sie nur geprüft und sie seiner würdig erfunden.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 3, 6, 'Wie Gold im Schmelzofen hat er sie erprobt und wie die Gabe eines Ganzopfers sie angenommen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 3, 7, 'So werden sie denn zur Zeit ihrer Gnadenheimsuchung hell glänzen und wie Funken durch dürres Schilfrohr fahren;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 3, 8, 'sie werden die Heiden richten und über Völker herrschen, und der Herr wird ihr König sein ewiglich.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 3, 9, 'Die auf ihn vertraut haben, werden die Wahrheit erkennen, und die treu gewesen sind, werden in Liebe bei ihm verbleiben; denn Gnade und Erbarmen wird seinen Frommen zuteil und Schutz seinen Auserwählten.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 3, 10, 'Die Gottlosen aber werden ihrer Denkweise gemäß Strafe erleiden, sie, die den Gerechten verachtet haben und vom Herrn abgefallen sind;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 3, 11, 'denn wer Weisheit und Zucht mißachtet, ist elend; die Hoffnung solcher Menschen ist eitel, ihr Bemühen erfolglos und ihr ganzes Tun nutzlos.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 3, 12, 'Ihre Weiber sind Törinnen und ihre Kinder böse, verflucht ihre Nachkommenschaft.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 3, 13, 'Glücklich zu preisen ist eine kinderlose Ehefrau, die sich unsträflich erhalten, die kein sündenbeflecktes Lager kennen gelernt hat: sie wird ihren Lohn empfangen bei der Prüfung der Seelen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 3, 14, 'Glücklich auch der Entmannte, der nichts Gesetzwidriges in seinem Leben verübt und nichts Böses gegen den Herrn ersonnen hat; denn ihm wird ein herrlicher Gnadenlohn für seine Treue verliehen werden und ein herzerfreuender Besitzanteil im Tempel des Herrn.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 3, 15, 'Denn die Frucht edler Bestrebungen ist herrlich, und die Wurzel der Weisheit stirbt nicht ab.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 3, 16, 'Aber die Kinder von Ehebrechern gelangen nicht zur Vollendung, und alle, die aus gesetzwidrigem Ehebett hervorgegangen sind, gehen zugrunde.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 3, 17, 'Und sollten sie es auch zu einem längeren Leben bringen, so werden sie doch für nichts geachtet werden, und ihr Alter wird schließlich ungeehrt sein.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 3, 18, 'Sollten sie aber plötzlich sterben, so haben sie keine Hoffnung und am Tage der Entscheidung keinen Trost;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 3, 19, 'denn das Ende eines gottlosen Geschlechts ist schlimm.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 1, 'Besser ist Kinderlosigkeit im Verein mit Tugend; denn Unsterblichkeit wohnt ihrem Nachruhm bei, weil sie sowohl bei Gott als bei den Menschen bekannt ist.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 2, 'Solange sie da ist, eifert man ihr nach, und ist sie geschwunden, so sehnt man sich nach ihr, und in der Ewigkeit schreitet sie, mit dem Kranze auf dem Haupte, als Siegerin einher, nachdem sie im Wettkampfe fleckenloser Bestrebungen gesiegt hat.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 3, 'Aber die große Kinderschar der Gottlosen bringt ihnen keinen Gewinn; aus unechten Schößlingen bestehend, treibt sie keine Wurzel in die Tiefe und faßt keinen festen Stand im Erdgrunde.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 4, 'Denn wenn sie auch eine Zeit lang mit den Zweigen hoch emporschießt, so wird doch das täuschend zum Vorschein Gekommene vom Wind hin und her geschüttelt und von der Gewalt der Stürme entwurzelt.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 5, 'Ringsum werden die unentwickelten Zweige abgebrochen, ihre Früchte bleiben unbrauchbar, ungenießbar und zu nichts tauglich;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 6, 'denn Kinder, die aus gesetzwidrigem Beischlaf hervorgegangen sind, legen gegen ihre Eltern das Zeugnis der Schlechtigkeit ab, wenn’s zu deren Prüfung kommt.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 7, 'Der Gerechte dagegen, auch wenn er frühzeitig stirbt, ist in der Ruhe;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 8, 'denn nicht das langdauernde Alter ist der Ehre wert und wird nicht nach der Zahl der Jahre gemessen;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 9, 'nein, das wahre graue Haar ist für die Menschen die Einsicht und das wahre Greisenalter ein fleckenloses Leben.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 10, 'Weil er sich Gottes Wohlgefallen erworben hatte, wurde er entrückt;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 11, 'er wurde entführt, damit nicht die Schlechtigkeit seinen Sinn verdürbe und Arglist seine Seele verführte.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 12, 'Denn das Blendwerk der Schlechtigkeit verdunkelt das Gute, und der Taumel der Sinnenlust wandelt auch ein unschuldiges Herz um.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 13, 'Wer in kurzer Zeit zur Vollendung gelangt ist, hat lange Zeiten erfüllt;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 14, 'denn wohlgefällig war seine Seele dem Herrn, darum eilte sie hinweg aus der Mitte der Bösen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 15, 'Die Leute sahen es wohl, verstanden es aber nicht und nahmen die Tatsache nicht zu Herzen, daß Gnade und Erbarmen bei seinen Auserwählten ist und Hilfeleistung bei seinen Frommen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 16, 'Der Gerechte aber, der das Leiden bestanden hat, wird die Verurteilung der noch lebenden Gottlosen herbeiführen und ebenso die früh zur Vollendung gelangte Jugend die Verurteilung des an Jahren reichen Greisenalters der Ungerechten.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 17, 'Denn sie werden das Ende des Weisen wahrnehmen, doch nicht erkennen, was Gott über ihn beschlossen und warum der Herr ihn in Sicherheit gebracht hat.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 18, 'Sie werden es wahrnehmen, doch es unbeachtet lassen; sie selbst aber wird der Herr verlachen; und sie werden darnach zu einem verachteten Leichnam werden und zum Gegenstand des Spottes unter den Toten ewiglich.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 19, 'Denn er wird sie kopfüber hinabstürzen, während sie lautlos (vor Schrecken) dastehen, und sie von Grund aus erschüttern; sie werden völlig verwüstet werden und Qualen erleiden, und das Andenken an sie wird erlöschen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 20, 'Zitternd werden sie herankommen, wenn ihre Sünden zusammengerechnet werden, und ihre Missetaten werden als Ankläger sie unwiderleglich überführen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 1, 'Alsdann wird der Gerechte mit voller Zuversicht denen gegenübertreten, die ihn bedrängt und seine Leiden unbeachtet gelassen haben.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 2, 'Wenn sie ihn erblicken, werden sie von schrecklicher Furcht befallen werden und über seine unerwartete Rettung außer sich sein.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 3, 'Reuevoll werden sie zueinander sagen und, in ihrer Seelenangst seufzend, sprechen: »Dieser war es, den wir einst zum Gegenstand des Gelächters und zum Witzwort des Hohns gemacht haben!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 4, 'Wir Toren hielten seine Lebensweise für Wahnsinn und seinen Tod für ehrlos.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 5, 'Wie kommt’s denn, daß er nun den Kindern Gottes zugerechnet worden ist und seinen Erbbesitz unter den Heiligen hat?');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 6, 'Ja, wir sind abgeirrt vom Wege der Wahrheit; das Licht der Gerechtigkeit hat uns nicht geleuchtet, und die Sonne ist uns nicht aufgegangen!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 7, 'Wir fanden unsere Befriedigung auf den Pfaden der Gesetzwidrigkeit und des Verderbens und durchwanderten unwegsame Wüsten, aber den Weg des Herrn erkannten wir nicht.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 8, 'Was hat uns nun unser Übermut genützt, und wozu hat uns der Reichtum mitsamt der eitlen Prahlerei geholfen?');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 9, 'Das alles ist verschwunden wie ein Schatten und wie ein flüchtiges Gerücht;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 10, 'wie ein Schiff, das die wogende See durchfährt, von dem man, wenn es vorübergezogen ist, keine Spur mehr findet und bei dem die Bahn seines Kiels verschwunden ist.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 11, 'Oder wie von einem Vogel, der durch die Luft fliegt, keine Spur seines Flugs erhalten bleibt – durch den Flügelschlag wird wohl die leichte Luft in starke Bewegung gesetzt und wird durchzogen, indem die rauschende Kraft der geschwungenen Flügel sie durchschneidet, aber darnach ist keine Spur des Aufflugs mehr sichtbar –;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 12, 'oder wie, wenn ein Pfeil nach dem Ziel abgeschossen wird, die durchschnittene Luft sofort wieder zusammenfließt, so daß man von seiner Flugbahn nichts mehr erkennen kann:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 13, 'so sind auch wir nach der Geburt sogleich wieder gestorben und vermögen kein Zeichen von Tugend aufzuweisen, sondern haben uns in unserem bösen Lebenswandel aufgerieben«.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 14, 'Ja, die Hoffnung des Gottlosen gleicht der Spreu, die der Wind entführt, und dem feinen Reif, den der Sturm verweht, dem Rauche, den der Wind auseinandertreibt, und der schnell entschwindenden Erinnerung an einen Gast, der nur einen Tag verweilt hat.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 15, 'Die Gerechten aber leben in Ewigkeit; sie haben ihren Lohn im Herrn, und die Sorge für sie steht beim Höchsten.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 16, 'Darum werden sie das Reich der Herrlichkeit und die Krone der Schönheit aus der Hand des Herrn empfangen; denn mit seiner Rechten wird er sie beschützen und mit seinem Arme sie beschirmen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 17, 'Als Rüstung wird er seinen Eifer anlegen, und die ganze Schöpfung bewaffnen zur Abwehr der Feinde;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 18, 'als Harnisch wird er die Gerechtigkeit anziehen und als Helm aufsetzen streng aufrichtiges Gericht;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 19, 'als unüberwindlichen Schild wird er seine Heiligkeit nehmen');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 20, 'und jähen Zorn als Schwert schärfen, und die ganze Welt wird mit ihm den Kampf gegen die Toren führen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 21, 'Ausfahren werden wohlgezielte Blitzesgeschosse und aus den Wolken wie vom wohlgerundeten Bogen auf das Ziel hin fliegen;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 22, 'und von seiner Schleuder werden grimmerfüllte Hagelsteine geschleudert werden; die Fluten des Meeres werden gegen sie wüten, und Ströme werden ungestüm über ihnen zusammenschlagen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 23, 'Der Hauch der Allmacht wird sich gegen sie erheben und wie ein Wirbelsturm sie zerstreuen. So wird die Gottlosigkeit die ganze Erde verwüsten und die Übeltat die Throne der Machthaber umstürzen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 24, '');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 1, 'Hört also, ihr Könige, und seid verständig! nehmt Lehre an, ihr Herrscher der Enden der Erde!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 2, 'Horcht auf, die ihr die Menge regiert und stolz seid auf die große Zahl eurer Völker!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 3, 'Denn die Herrschaft ist euch vom Herrn verliehen und die Gewalt vom Höchsten,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 4, 'der eure Taten prüfen und eure Pläne erforschen wird.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 5, 'Denn obgleich ihr Diener seines Reiches seid, habt ihr ungerecht gerichtet und weder das Gesetz beobachtet, noch euren Wandel nach dem Willen Gottes geführt.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 6, 'Schrecklich und gar bald wird er über euch kommen, denn ein strenges Gericht findet bei den Machthabern statt.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 7, 'Denn der Geringe findet Verzeihung aus Erbarmen, aber die Gewaltigen werden gewaltig gezüchtigt werden;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 8, 'denn der Allherrscher nimmt auf niemand Rücksicht und scheut sich vor keiner Größe; denn klein und groß hat er geschaffen, und für alle sorgt er in gleicher Weise.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 9, 'Den Mächtigen aber steht eine strenge Untersuchung bevor.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 10, 'Euch also, ihr Fürsten, gelten meine Worte, damit ihr Weisheit lernt und euch nicht vergeht.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 11, 'Denn die, welche das Heilige heilig beobachten, werden selbst geheiligt werden, und die darin Belehrung erhalten haben, werden Rechtfertigung (oder Freisprechung) erlangen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 12, 'So seid also begierig nach meinem Unterricht, tragt Verlangen danach, so werdet ihr Belehrung gewinnen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 13, 'Strahlend und unverwelklich ist die Weisheit und läßt sich leicht erschauen von denen, die sie lieben, und leicht finden von denen, die sie suchen;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 14, 'ja, sie kommt denen zuvor, die nach ihr verlangen, um erkannt zu werden.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 15, 'Wer sich früh am Morgen nach ihr aufmacht, braucht sich nicht lange zu mühen, denn er findet sie schon an seiner Tür sitzend.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 16, 'Denn sich in Gedenken mit ihr beschäftigen ist der Höhepunkt der Einsicht, und wer um ihretwillen wacht, wird bald frei von Sorgen sein.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 17, 'Denn sie selbst geht umher und sucht die ihrer Würdigen auf; sie erscheint ihnen bereitwillig auf allen ihren Wegen und tritt ihnen bei jedem Gedanken entgegen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 18, 'Der Anfang zu ihr ist das völlig aufrichtige Verlangen nach Belehrung; Sorge um Belehrung aber ist Liebe zu ihr;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 19, 'Liebe zu ihr aber besteht in der Beobachtung ihrer Gebote; das Festhalten an ihren Geboten aber ist Sicherstellung der Unsterblichkeit;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 20, 'Unsterblichkeit aber bewirkt, daß man Gott nahe ist.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 21, 'So führt also das Verlangen nach Weisheit zur Herrschaft.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 22, 'Also, ihr Beherrscher der Völker: wenn ihr Freude an euren Thronen und Zeptern erleben wollt, so ehrt die Weisheit, damit ihr die Herrschaft für immer behaltet.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 23, 'Was aber die Weisheit ist und wie sie entstanden ist, will ich verkünden und nicht Geheimnisse vor euch verbergen, sondern vom Anfang der Schöpfung an will ich nachforschen und ihre Kenntnis offen darlegen, ohne an der Wahrheit vorbeizugehen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 24, 'Auch will ich nicht im Bunde mit dem hagern Neide kommen, denn dieser hat mit der Weisheit nichts gemein.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 25, 'Eine große Anzahl von Weisen ist aber ein Glück für die Welt, und ein verständiger König ist ein Segen für das Volk.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 26, 'Darum laßt euch durch meine Worte unterweisen: das wird euch Nutzen bringen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 27, '');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 1, 'Auch ich bin zwar ein sterblicher Mensch gleich allen anderen und ein Abkömmling des erdgeborenen Ersterschaffenen;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 2, 'dem Körper nach bin ich im Schoße meiner Mutter in zehnmonatlicher Frist gebildet, zusammengeronnen im Blut aus Mannessamen und der im Beischlaf sich zugesellenden Lust.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 3, 'Auch ich sog nach meiner Geburt die allen gemeinsame Luft ein und fiel auf die Erde, wie das alle Kinder tun, indem ich den ersten Schrei auf die allen gleiche Weise weinend ausstieß;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 4, 'in Windeln wurde ich aufgezogen und unter Sorgen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 5, 'Denn kein König hat einen andern Anfang seines Daseins gehabt: nein,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 6, 'alle treten in gleicher Weise ins Leben ein und aus dem Leben hinaus.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 7, 'Darum betete ich, da wurde mir Einsicht verliehen; ich rief Gott an, da zog der Geist der Weisheit in mich ein.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 8, 'Ich schätzte sie höher als Zepter und Thron und achtete den Reichtum für nichts im Vergleich mit ihr;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 9, 'keinen noch so unschätzbaren Edelstein stellte ich ihr gleich; denn alles Gold ist neben ihr nur ein bißchen Sand, und Silber wird im Vergleich mit ihr als Unrat angesehen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 10, 'Mehr als Gesundheit und Schönheit liebte ich sie und zog ihren Besitz sogar dem Lichte vor, weil die von ihr ausgehende Helligkeit nie erlischt.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 11, 'Es kamen aber zugleich mit ihr alle anderen Güter in meinen Besitz, und ungezählten Reichtum brachte sie mit.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 12, 'Ich freute mich aber aller dieser Dinge, weil die Weisheit ihre Führerin ist; ich wußte aber noch nicht, daß sie auch die Erzeugerin von ihnen allen ist.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 13, 'Ohne Hintergedanken habe ich sie kennen gelernt, und ohne Neid mache ich jetzt Mitteilung davon; ich will ihren Reichtum nicht für mich zurückbehalten;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 14, 'denn ein unerschöpflicher Schatz ist sie für die Menschen; alle, die ihn benutzen, verwenden ihn dazu, Freundschaft mit Gott zu schließen, dem sie sich durch die aus der Zucht stammenden Gaben empfohlen haben.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 15, 'Mir aber möge Gott verleihen, nach meinem Wunsche (oder der Einsicht gemäß?) zu reden und Erwägungen anzustellen, die der mir verliehenen Gabe würdig sind; denn er ist ebensowohl der Führer zur Weisheit als auch der Wegweiser der Weisen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 16, 'In seiner Hand sind ja sowohl wir als auch unsere Worte und jegliche Einsicht und jedes Geschick für geschäftliche Leistungen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 17, 'So hat er denn auch mir ein untrügliches Wissen von den Dingen verliehen, so daß ich mich auf den Bau der Welt und auf die Kraft der Elemente verstehe,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 18, 'auf den Anfang und das Ende und die Mitte der Zeiten, auf den Wandel der Sonnenwenden und den Wechsel der Jahreszeiten,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 19, 'auf den Kreislauf der Jahre und die Stellungen der Gestirne,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 20, 'auf die verschiedenartige Natur der Tiere und die wilden Triebe der Raubtiere, auf die gewaltigen Kräfte der Geister und die Gedanken der Menschen, auf die Verschiedenheiten der Pflanzen und die Heilkräfte der Wurzeln.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 21, 'Alles, was verborgen und offenbar ist, habe ich kennen gelernt; denn die Künstlerin von allen hat es mich gelehrt, die Weisheit.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 22, 'Denn in ihr wohnt ein Geist: denkend, heilig, eigenartig, vielteilig, fein, beweglich, durchsichtig, unbefleckbar, klar, unverletzlich, das Gute liebend, scharfsinnig, nicht zu hemmen, wohltätig, menschenfreundlich,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 23, 'fest ohne Fehl, sorgenfrei, allgewaltig, alles übersehend und alle denkenden, reinen und feinen Geister durchdringend.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 24, 'Denn die Weisheit ist beweglicher als alles andere, was sich bewegt; sie dringt und geht durch alles hindurch vermöge ihrer Reinheit.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 25, 'Denn sie ist ein Hauch der Kraft Gottes und ein lauterer Ausfluß aus der Herrlichkeit des Allmächtigen; darum gerät auch nichts Beflecktes in sie hinein.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 26, 'Denn sie ist ein Abglanz des ewigen Lichts und ein fleckenloser Spiegel des göttlichen Wirkens und ein Abbild seiner Güte.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 27, 'Obgleich sie nur eine ist, vermag sie doch alles, und obgleich sie immer dieselbe bleibt, erneuert sie doch alles; und indem sie von Geschlecht zu Geschlecht in heilige Seelen eingeht, rüstet sie diese zu Gottesfreunden und Propheten aus.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 28, 'Denn nichts liebt Gott als den, der mit der Weisheit in vertrauter Gemeinschaft lebt.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 29, 'Denn sie ist herrlicher als die Sonne und übertrifft jegliche feste Stellung der Gestirne und, mit dem Lichte verglichen, stellt sie sich als vorzüglicher heraus;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 30, 'denn auf dieses folgt die Nacht, aber gegen die Weisheit vermag die Bosheit nichts.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 1, 'Sie erstreckt sich aber machtvoll von dem einen Ende zum andern und ordnet alles in der Welt vortrefflich.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 2, 'Diese habe ich geliebt und erstrebt von meiner Jugend an; ich wünschte sehnlich, sie als meine Braut heimzuführen, und war in ihre Schönheit verliebt.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 3, 'Ihren edlen Ursprung verherrlicht sie dadurch, daß sie mit Gott zusammenlebt, und auch der Gebieter des Alls hat sie liebgewonnen;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 4, 'denn sie ist in Gottes Wissen eingeweiht und nimmt teil an seinem Wirken.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 5, 'Wenn aber Reichtum ein wünschenswerter Besitz im Leben ist, was kann es da Reicheres geben als die Weisheit, die alles erschafft?');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 6, 'Und wenn schon die Klugheit etwas zustande bringt, wo gibt es da in der ganzen Welt einen tüchtigeren Werkmeister als sie?');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 7, 'Und wenn jemand die Gerechtigkeit liebt, so ist sie es, welche die Tugenden hervorbringt; denn Maßhalten und Klugheit lehrt sie, Gerechtigkeit und Tapferkeit, die nützlichsten Besitztümer, die es für die Menschen in ihrem Leben gibt.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 8, 'Wenn ferner jemand Verlangen nach reicher Lebenserfahrung trägt, so ist sie es, die das Vergangene kennt und das Zukünftige erschließt; sie versteht sich auch auf künstlich geformte Aussprüche und auf die Lösung von Rätseln; Zeichen und Wunder erkennt sie im voraus und ebenso die Ausgänge der Zeiten und Zeiträume.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 9, 'So beschloß ich denn, diese als Lebensgenossin heimzuführen; ich wußte ja, daß sie mir im Glück eine Beraterin sein würde und eine Trösterin in Sorgen und Kümmernissen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 10, 'Um ihretwillen werde ich Ruhm bei der großen Menge haben und, obschon noch ein junger Mann, Ehre bei den Alten.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 11, 'Als scharfsinnig werde ich erfunden werden bei der Rechtsprechung und Bewunderung ernten durch die Beurteilung der (fremden) Herrscher.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 12, 'Wenn ich schweige, wird man auf mich warten, und wenn ich rede, wird man aufhorchen, und wenn ich länger rede, werden alle die Hand auf ihren Mund legen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 13, 'Durch ihr Verdienst werde ich Unsterblichkeit erlangen und ein ewiges Andenken bei der Nachwelt hinterlassen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 14, 'Völker werde ich regieren, und Völkerschaften werden mir untertan sein;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 15, 'schreckliche Gewaltherrscher werden in Furcht geraten, wenn sie von mir hören; bei der großen Menge werde ich als gütig gelten und im Kriege als tapfer.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 16, 'Bin ich nach Hause gekommen, so werde ich Erholung bei ihr finden; denn der Verkehr mit ihr hat nichts Bitteres und das Zusammenleben mit ihr nichts Betrübendes, sondern nur Frohsinn und Freude.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 17, 'Dieses bei mir bedenkend und in meinem Herzen erwägend, daß nämlich Unsterblichkeit durch das Zusammenleben mit der Weisheit gewonnen wird');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 18, 'und edle Ergötzung durch die Freundschaft mit ihr und durch ihr erfolgreiches Wirken ein unerschöpflicher Reichtum und durch die dauernde Pflege des Verkehrs mit ihr Einsicht und durch die Teilnahme an ihren Unterweisungen Berühmtheit: – da ging ich umher und suchte sie in meinen Besitz zu bringen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 19, 'Ich war aber ein wohlbeanlagter junger Mann, besaß auch ein gutes Gemüt,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 20, 'oder vielmehr, weil ich gutgeartet war, war ich in einen unbefleckten Leib gekommen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 21, 'Da ich aber erkannte, daß ich nur dann in ihren Besitz gelangen würde, wenn Gott sie mir verliehe, – und zwar war das schon ein Beweis von Einsicht, daß ich erkannte, von wem diese Gnadengabe komme, – da wandte ich mich an den Herrn und betete zu ihm und sprach aus ganzem Herzen:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 1, 'Du Gott meiner Väter und Herr der Barmherzigkeit, der du das All durch dein Wort geschaffen');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 2, 'und durch deine Weisheit den Menschen gebildet hast, damit er über die von dir erschaffenen Geschöpfe herrsche');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 3, 'und die Welt regiere mit Heiligkeit und Gerechtigkeit und in Lauterkeit des Herzens Gericht halte:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 4, 'verleihe mir die Weisheit, die Beisitzerin deines Thrones, und schließe mich nicht aus der Zahl deiner Kinder aus.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 5, 'Denn ich bin dein Knecht und der Sohn deiner Magd, ein schwacher Mensch von kurzer Lebensdauer und wenig tüchtig an Einsicht für Rechtspflege und Gesetzeskenntnis.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 6, 'Denn wäre jemand auch vollkommen unter den Menschenkindern, so müßte er doch, wenn ihm die von dir ausgehende Weisheit abginge, für nichts geachtet werden.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 7, 'Du hast mich zum König deines Volkes auserwählt und zum Richter über deine Söhne und Töchter.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 8, 'Du hast mir geboten, einen Tempel auf deinem heiligen Berge zu erbauen und einen Altar in der Stadt, wo du deine Wohnung hast, ein Abbild des heiligen Zeltes, das du von Anfang an zuvorbereitet hast.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 9, 'Bei dir ist ja die Weisheit, die deine Werke kennt und die zugegen war, als du die Welt schufst, und die weiß, was in deinen Augen wohlgefällig und was recht ist nach deinen Geboten.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 10, 'Entsende sie aus deinem heiligen Himmel und schicke sie vom Thron deiner Herrlichkeit, damit sie mir bei meiner Arbeit Beistand leiste und ich erkenne, was dir wohlgefällig ist.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 11, 'Denn sie weiß und versteht alles und wird mich bei meinen Unternehmungen mit Besonnenheit leiten und mich durch ihren Lichtglanz behüten.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 12, 'Alsdann wird mein ganzes Tun wohl aufgenommen werden, und ich werde dein Volk mit Gerechtigkeit regieren und des Thrones meines Vaters würdig sein.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 13, 'Denn wo ist ein Mensch, der den Willen Gottes zu erkennen vermöchte, oder wer wird ergründen, was der Herr verlangt?');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 14, 'Denn die Gedanken der Sterblichen sind unsicher und unsere Anschläge trügerisch;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 15, 'denn der vergängliche Leib beschwert die Seele, und die irdische Behausung belastet den denkeifrigen Geist.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 16, 'Kaum erraten wir, was auf der Erde ist, und nur mit Mühe machen wir ausfindig, was handgreiflich vor uns liegt: wer aber hat die himmlischen Dinge ergründet?');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 17, 'Und wer hat deinen Ratschluß erkannt, wenn du ihm nicht Weisheit verliehen und ihm deinen heiligen Geist von obenher gesandt hast?');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 18, 'Nur auf diese Weise werden die Pfade der Erdenbewohner gerade gerichtet und die Menschen über das dir Wohlgefällige belehrt; ja, nur durch die Weisheit werden sie gerettet.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 19, '');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 1, 'Sie ist es gewesen, die den erstgeschaffenen Vater der Menschheit, als er noch allein geschaffen war, behütet und ihn aus seinem Fall wieder errettet hat;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 2, 'sie verlieh ihm auch die Kraft, sich alles untertan zu machen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 3, 'Als aber der Gottlose in seinem Zorn von ihr abfiel, ging er durch seine brudermörderische Leidenschaft mit zugrunde.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 4, 'Die um seinetwillen überflutete Erde rettete wiederum die Weisheit, indem sie den Gerechten vermittelst eines geringen Holzes (durch die Flut) hindurchsteuerte.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 5, 'Sie war es auch, die, als die Völker sich einmütig in Verworfenheit zusammengetan hatten, den Gerechten ausfindig machte und ihn unsträflich vor Gott bewahrte und ihn trotz seiner herzlichen Liebe zu seinem Sohn stark erhielt.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 6, 'Sie rettete beim Untergang der Gottlosen den Gerechten, als er vor dem Feuer floh, das auf die fünf Städte herabfiel,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 7, 'für deren Bosheit noch jetzt als Zeugen da sind die verödete, stets rauchende Landschaft und Pflanzen, die vor der Zeit unreife Früchte tragen, und die Salzsäule, die als Denkmal einer ungläubigen Seele dasteht.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 8, 'Denn da sie an der Weisheit vorübergingen, erlitten sie nicht nur dadurch Schaden, daß sie das Gute nicht mehr kannten, sondern sie hinterließen auch der Nachwelt ein Denkmal ihrer Torheit, damit ihre Verfehlungen nicht verborgen bleiben könnten.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 9, 'Die Weisheit aber hat die, welche ihr dienten, aus den Notlagen errettet.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 10, 'Sie hat den Gerechten, der vor dem Zorn seines Bruders floh, auf ebenen Pfaden geleitet; sie zeigte ihm das Reich Gottes und gab ihm Kenntnis von den heiligen Dingen, verschaffte ihm Wohlstand unter mühseligen Dienstleistungen und lohnte seine Arbeit reichlich.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 11, 'Bei der Habgier seiner Bedränger stand sie ihm bei und ließ ihn reich werden;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 12, 'sie beschützte ihn vor seinen Feinden und stellte ihn sicher gegen die, welche ihm nachstellten; sie verlieh ihm den Sieg in dem schweren Kampfe, damit er zu der Erkenntnis käme, daß die Gottesfurcht stärker ist als alles andere. –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 13, 'Sie verließ den Gerechten auch nicht, als man ihn verkauft hatte, sondern bewahrte ihn vor der Sünde;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 14, 'sie stieg mit ihm in die Zisterne hinab und verließ ihn nicht in Fesseln, bis sie ihm das königliche Zepter verschafft hatte und die Herrschaft über seine Bedränger und seine Verleumder als Lügner erwiesen und ihm ewigen Ruhm verliehen hatte.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 15, 'Sie war es, die das heilige Volk und das untadlige Geschlecht von dem Volksstamm der Bedränger befreite;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 16, 'sie zog ein in die Seele des Dieners des Herrn und trat gegen furchtbare Könige mit Zeichen und Wundern auf.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 17, 'Sie verschaffte den Heiligen den Lohn für ihre Mühen, geleitete sie auf wunderbaren Wegen und diente ihnen am Tage als Schirmdecke und bei Nacht als Sternenleuchte.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 18, 'Sie brachte sie durch das Rote Meer und führte sie durch die gewaltige Wasserflut;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 19, 'ihre Feinde aber ließ sie in die Wogen versinken und schleuderte sie dann aus der Tiefe des Meeresgrundes wieder ans Land empor.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 20, 'So geschah es denn, daß die Gerechten den Gottlosen die Waffen abnahmen und deinem heiligen Namen, o Herr, lobsangen und einmütig deine schirmende Hand priesen;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 21, 'denn die Weisheit öffnete den Stummen den Mund und machte die Zungen der Unmündigen helltönend.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 11, 1, 'Sie ließ ihre Unternehmungen gelingen unter der Leitung des heiligen Propheten.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 11, 2, 'Sie durchwanderten eine unbewohnte Wüste und schlugen ihre Zelte an unwegsamen Orten auf;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 11, 3, 'sie hatten mit Feinden zu kämpfen und Angreifer zurückzuschlagen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 11, 4, 'Sie litten Durst: da riefen sie dich an, und es wurde ihnen Wasser gegeben aus schroffen Felsen und Linderung ihres Durstes aus hartem Gestein.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 11, 5, 'Denn das, wodurch ihre Feinde gestraft worden waren, ebendasselbe empfingen sie in ihrer Not als eine Wohltat.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 11, 6, 'Anstatt des immerfließenden Quellwassers des durch Mordblut getrübten Stromes,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 11, 7, 'zur Strafe für die Anordnung des Kindermordes, gabst du ihnen unverhofft Trinkwasser in Fülle,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 11, 8, 'indem du ihnen durch ihren damaligen Durst zeigtest, wie du ihre Widersacher gestraft hattest.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 11, 9, 'Denn als sie so geprüft wurden – obgleich sie doch nur gelinde gezüchtigt wurden –, konnten sie erkennen, wie die im Zorn gerichteten Gottlosen bestraft wurden.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 11, 10, 'Denn sie hast du wie ein Vater geprüft, der warnen will, jene aber hast du gezüchtigt wie ein strenger König, der das Verdammungsurteil ausspricht.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 11, 11, 'Sowohl fern von ihnen, wie nahe bei ihnen wurden sie in gleicher Weise geplagt;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 11, 12, 'denn eine zwiefache Trauer ergriff sie und ein Seufzen bei der Erinnerung an das, was vergangen war.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 11, 13, 'Denn als sie vernahmen, daß durch ihre Züchtigungen jenen eine Wohltat zuteil geworden war, merkten sie das Walten des Herrn;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 11, 14, 'denn ihn, den sie einst bei der Aussetzung weggeworfen und mit Hohn verworfen hatten, mußten sie am Ende seiner Erfolge bewundern, nachdem sie einen ganz andern Durst erlitten hatten als die Gerechten.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 11, 15, 'Zur Vergeltung für die unverständigen Gedanken ihrer Gottlosigkeit, durch die sie in ihrem Irrwahn vernunftloses Gewürm und elendes Getier verehrten, sandtest du ihnen, um sie zu strafen, eine Menge vernunftloser Tiere,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 11, 16, 'damit sie zu der Erkenntnis kämen, daß, wodurch man sich verfehlt, man eben dadurch auch gestraft wird.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 11, 17, 'Deine allmächtige Hand, welche die Welt aus ungeformtem Stoffe geschaffen hat, wäre ja wohl stark genug gewesen, eine Menge von Bären oder wilden Löwen gegen sie zu senden');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 11, 18, 'oder auch neugeschaffene, wuterfüllte, unbekannte Bestien, die entweder einen feuerspeienden Atem aushauchten oder stinkenden Qualm ausstießen oder schreckliche Funken aus den Augen sprühten,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 11, 19, 'von denen nicht nur der Gifthauch sie vernichten, sondern deren bloßer Anblick sie durch Schrecken ums Leben bringen konnte.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 11, 20, 'Ja, abgesehen hiervon hätten sie durch einen einzigen Hauch hinsinken können, von deiner Rache verfolgt und vom Hauche deiner Macht zerstreut; aber du hast alles nach Maß, Zahl und Gewicht geordnet.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 11, 21, 'Denn deine gewaltige Macht zu betätigen steht dir allezeit zu Gebote, und wer vermöchte der Kraft deines Armes zu widerstehen?');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 11, 22, 'Denn wie ein Stäubchen an der Waage ist die ganze Welt dir gegenüber und wie ein Tautröpfchen, das am Morgen auf die Erde fällt.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 11, 23, 'Aber du erbarmst dich aller, weil du alles vermagst, und läßt die Sünden der Menschen unbeachtet, damit sie sich bekehren;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 11, 24, 'denn du liebst alles, was da ist, und fühlst keinen Widerwillen gegen irgend etwas von dir Geschaffenes; denn hegtest du Haß gegen irgend etwas, so hättest du es nicht geschaffen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 11, 25, 'Wie hätte aber etwas bestehen bleiben können, wenn du es nicht gewollt hättest? oder wie wäre etwas erhalten geblieben, wenn es nicht von dir ins Dasein gerufen wäre?');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 11, 26, 'Du verfährst aber schonungsvoll gegen alles, weil es dein Eigentum ist, o Herr, du Freund alles Lebens;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 1, 'denn dein unvergänglicher Geist ist in allen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 2, 'Darum strafst du die Fehlenden mit Milde und warnst sie, indem du ihnen ihre Sünden vorhältst, damit sie sich von ihrer Schlechtigkeit frei machen und an dich glauben, o Herr.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 3, 'Denn du haßtest zwar die alten Bewohner deines heiligen Landes,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 4, 'weil sie die abscheulichsten Werke der Zauberei trieben und frevelhafte Götterdienste feierten');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 5, 'und mitleidlose Kindermorde vollzogen und Opferschmäuse von Menschenfleisch und Blut hielten und sich in greuelvolle Vereine einweihen ließen');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 6, 'und Eltern unter sich hatten, die mit eigener Hand Mörder hilfloser Kinderseelen waren, und hattest beschlossen, sie durch die Hände unserer Väter auszurotten,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 7, 'damit das bei dir vor allen andern hochgeehrte Land eine der Gotteskinder würdige Bevölkerung erhielte.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 8, 'Aber du bist auch mit diesen schonend verfahren, weil sie Menschen waren, und hast als Vortruppen deines Heeres Hornissen entsandt, die sie nach und nach vernichten sollten.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 9, 'Und dabei wärest du doch stark genug gewesen, die Gottlosen in einer Schlacht den Gerechten in die Hände zu geben oder sie durch wilde Tiere oder durch ein kurzes Wort mit einem Schlage zu vernichten.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 10, 'Aber indem du das Gericht nach und nach vollzogst, gabst du ihnen die Möglichkeit der Umkehr, obgleich du wohl wußtest, daß ihr Ursprung böse war und ihre Verworfenheit angeboren und daß ihre Sinnesart sich in Ewigkeit nicht ändern würde;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 11, 'denn ein verfluchtes Geschlecht waren sie von Anfang an. Auch gewährtest du ihnen nicht etwa aus Scheu vor irgend jemandem Straflosigkeit für ihre Sünden;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 12, 'denn wer darf zu dir sagen: »Was hast du da getan?« oder wer darf deinem Richterspruch entgegentreten? und wer will dich verklagen wegen der Vertilgung von Völkern, die du geschaffen hast? oder wer wollte gegen dich als Verteidiger gottloser Menschen auftreten?');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 13, 'Denn weder gibt es außer dir einen Gott, der für alles sorgt, so daß du ihm die Gerechtigkeit deines Gerichts nachweisen müßtest,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 14, 'noch wird ein König oder Gebieter dir Vorhalt zu machen vermögen wegen derer, die du Strafe hast leiden lassen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 15, 'Da du aber gerecht bist, ordnest du auch alles mit Gerechtigkeit und hältst es für unvereinbar mit deiner Macht, jemand zu verurteilen, der keine Bestrafung verdient.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 16, 'Denn deine Macht ist der Grund deiner Gerechtigkeit, und der Umstand, daß du der Herr aller bist, ist die Ursache, daß du gegen alle schonend verfährst.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 17, 'Denn Stärke zeigst du nur dann, wenn man an der Vollkommenheit deiner Macht zweifelt, und bei denen, die sie kennen, strafst du den frevlen Trotz.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 18, 'Du aber, obschon über Stärke gebietend, richtest doch mit Milde und herrschest über uns mit großer Schonung; denn sooft du willst, steht dir auch das Können zu Gebote.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 19, 'Durch eine solche Handlungsweise hast du dein Volk darauf hingewiesen, daß der Gerechte ein Menschenfreund sein muß, und hast deine Söhne mit der frohen Hoffnung erfüllt, daß du ihnen nach Versündigung Reue gestattest.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 20, 'Denn wenn du schon die Feinde deiner Kinder und solche, die den Tod verdient hatten, mit solcher Nachsicht und Schonung bestraft hast, indem du ihnen Zeit und die Möglichkeit gewährtest, sich von ihrer Verworfenheit frei zu machen,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 21, 'mit wie großer Achtsamkeit hast du da erst deine Söhne gerichtet, deren Vätern du Eidschwüre und Bündnisse mit herrlichen Verheißungen gewährt hast!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 22, 'Während du uns also züchtigst, geißelst du unsere Feinde tausendmal härter, damit, wenn wir selbst richten, wir deine Güte bedenken und, wenn wir gerichtet werden, auf Erbarmen hoffen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 23, 'Daher hast du auch die in der Torheit ihrer Lebensführung dahinlebenden Gottlosen durch ihre eigenen Greuel gestraft.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 24, 'Denn sie waren auf den Wegen des Irrwahns ungebührlich weit abgeirrt, indem sie Tiere, die sogar von ihren Feinden verachtet wurden, für Götter hielten, weil sie nach Art einfältiger Kinder getäuscht waren.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 25, 'Darum hast du über sie auch wie über törichte Kinder eine Strafe verhängt, die ihnen Hohn einbrachte.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 26, 'Diejenigen aber, welche sich durch eine verhöhnende Strafe nicht haben warnen lassen, müssen ein Gericht erfahren, das Gottes würdig ist.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 27, 'Denn durch eben die, über welche sie in ihrem Mißgeschick unwillig waren, durch eben die, welche sie für Götter hielten, gezüchtigt, erkannten sie deutlich, daß der Gott der wahre sei, den sie vorher nicht hatten anerkennen wollen. Darum kam auch das Äußerste der Bestrafung über sie.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 13, 1, 'Toren nämlich von Natur waren alle Menschen, die an Unkenntnis Gottes litten und nicht imstande waren, aus dem sichtbaren Guten den Seienden zu erkennen, und die bei der Betrachtung der Werke den Werkmeister nicht wahrnahmen,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 13, 2, 'sondern sei es das Feuer oder den Wind oder die flüchtige Luft oder den Kreis der Sterne oder das gewaltige Wasser oder die beiden großen Himmelsleuchten für weltregierende Götter hielten.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 13, 3, 'Wenn sie, durch die Schönheit dieser Dinge ergötzt, sie für Götter ansahen, so hätten sie einsehen sollen, um wieviel höher deren Gebieter dasteht; denn der Urheber aller Schönheit ist es ja, der sie geschaffen hat.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 13, 4, 'Und wenn sie durch deren Kraft und Wirksamkeit in Staunen versetzt waren, so hätten sie daraus einsehen müssen, um wie viel mächtiger noch der Schöpfer dieser Dinge sei;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 13, 5, 'denn aus der Größe und Schönheit der geschaffenen Werke wird vergleichsweise auch ihr Schöpfer wahrgenommen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 13, 6, 'Aber gleichwohl trifft diese nur ein geringer Tadel, insofern sie vielleicht nur irre gehen, während sie doch Gott wirklich suchen und ihn finden möchten.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 13, 7, 'Denn indem sie sich mit seinen Werken beschäftigen, durchforschen sie diese, lassen sich aber durch den Anblick beeinflussen, weil ja das, was sie sehen, so schön ist.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 13, 8, 'Trotzdem sind auch sie nicht zu entschuldigen;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 13, 9, 'denn wenn sie imstande waren, in ihrem Wissen dahin zu gelangen, daß sie die Welt zu durchforschen vermochten, – wie kam es denn, daß sie nicht viel schneller noch den Herrn dieser Dinge ausfindig machten?');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 13, 10, 'Beklagenswert aber – sie setzen ja ihre Hoffnung auf leblose Gegenstände – sind die, welche Werke von Menschenhand Götter genannt haben, Gold und Silber als Kunsterzeugnisse und Abbilder von Tieren, oder einen unnützen Stein, den eine Hand der Vorzeit geformt hat.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 13, 11, 'Oder wenn ein Holzschnitzer einen tauglichen Block von einem Baume abgesägt hat und dann sachkundig die ganze Rinde davon abgeschält und in kunstgerechter Bearbeitung ein brauchbares Gerät zur Benutzung im täglichen Gebrauch daraus angefertigt,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 13, 12, 'dann die Abfälle seiner Arbeit zur Zubereitung seiner Speisen verwandt und sich satt gegessen hat:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 13, 13, 'dann nimmt er das Stück, das noch übriggeblieben und zu nichts mehr tauglich ist, ein krummes und mit Knoten durchwachsenes Holzstück, schnitzt sorgfältig daran in seinen Mußestunden, gestaltet es mit einsichtsvollem Kunstgeschick und gibt ihm die Gestalt eines Menschen');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 13, 14, 'oder macht es einem gemeinen Tiere ähnlich; hierauf bestreicht er es mit Mennig, färbt seine Haut mit Schminke rot und übermalt jeden Flecken an ihm.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 13, 15, 'Nachdem er ihm dann eine seiner würdige Behausung geschaffen hat, stellt er es an der Wand auf und befestigt es mit Eisen;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 13, 16, 'er sorgt selbstverständlich dafür, daß es nicht umfalle, weil er wohl weiß, daß es sich nicht selbst helfen kann: es ist ja nur ein Bild und bedarf fremder Hilfe.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 13, 17, 'Er betet dann aber zu ihm für sein Hab und Gut, für seine Weiber und Kinder und schämt sich nicht, das leblose Bild anzureden;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 13, 18, 'er ruft das Kraftlose wegen seiner Leibesstärke an, bittet das Tote um sein Leben; um Hilfe fleht er das an, was gar keinen Rat zu geben vermag, verlangt Schutz für die Reise von dem, was seine eigenen Füße nicht gebrauchen kann;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 13, 19, 'für sein Geschäft, seine Arbeit und Hantierung erbittet er sich Kraft von dem, dessen Hände völlig kraftlos sind.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 1, 'Wiederum, wenn einer eine Seefahrt unternimmt und durch die wilden Fluten zu fahren gedenkt, ruft er ein Stück Holz an, das gebrechlicher ist, als das Fahrzeug, das ihn trägt.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 2, 'Zwar hat die Gewinnsucht dieses ersonnen und der Baumeister es mit seiner Kunst hergestellt;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 3, 'aber deine Fürsorge, o Vater, ist es, die es hindurchsteuert; denn du hast auch im Meer einen Weg geschaffen und in den Fluten einen sicheren Pfad;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 4, 'du wolltest eben zeigen, daß du aus jeder Lage retten kannst, damit man ein Schiff besteige, auch ohne ein kundiger Seemann zu sein.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 5, 'Du willst aber, daß die Werke deiner Weisheit nicht unbenutzt bleiben; darum vertrauen die Menschen auch einem ganz geringen Holze ihr Leben an und werden gerettet, wenn sie die Wogen auf einem Floß durchfahren.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 6, 'Denn auch im Anfang, als die übermütigen Riesen umkamen, ist auch die Hoffnung der Welt in der Arche glücklich entronnen und hat der Folgezeit den Samen eines neuen Geschlechts hinterlassen, da deine Hand die Fahrt lenkte;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 7, 'denn gesegnet ist das Holz, durch welches Gerechtigkeit (gewirkt) wird.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 8, 'Dagegen jedes von Menschenhand gefertigte Götzenbild ist verflucht und ebenso auch der, welcher es angefertigt hat, weil er es gearbeitet, das vergängliche Werk aber den Namen Gottes erhalten hat;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 9, 'denn in gleicher Weise sind sie beide gottverhaßt, der Gottlose und sein gottloses Werk;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 10, 'denn das Werk wird mit dem Verfertiger zugleich gestraft.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 11, 'Deshalb wird auch an den Götzenbildern der Heiden ein Strafgericht stattfinden, weil sie in der Schöpfung Gottes zu Greueln geworden sind und zum Ärgernis für die Seelen der Menschen und zum Fallstrick für die Füße der Unverständigen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 12, 'Denn der Anfang des Abfalls von Gott ist das Ersinnen von Götzenbildern; ihre Erfindung aber hat den Verderb des Lebens herbeigeführt.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 13, 'Denn weder sind sie von Anfang an dagewesen, noch werden sie ewiglich bleiben.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 14, 'Nein, durch den eitlen Wahn der Menschen sind sie in die Welt gekommen, und darum ist auch ein jähes Ende für sie beschlossen worden.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 15, 'Denn ein durch frühzeitige Trauer bekümmerter Vater ließ von seinem allzuschnell dahingerafften Kinde ein Bild anfertigen und ehrte den damals verstorbenen Menschen nunmehr wie einen Gott und ordnete auch für seine Untergebenen einen Geheimdienst und Weihen an.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 16, 'Darauf gewann dann die gottlose Sitte im Laufe der Zeit solche Macht, daß sie wie ein Gesetz beobachtet wurde und die geschnitzten Bilder (der Toten) auf Befehl der Gewalthaber göttlich verehrt wurden.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 17, 'Von solchen nun, welche die Menschen, weil sie weit weg wohnten, nicht unmittelbar durch Anschauen ehren konnten, bildeten sie die Gestalt aus der Ferne nach und stellten sich von dem verehrten Könige ein sichtbares Bild her, um dem Abwesenden, als wäre er gegenwärtig, mit allem Eifer zu huldigen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 18, 'Zur Steigerung der Verehrung aber trieb dann der Ehrgeiz des Künstlers auch diejenigen an, welche den betreffenden (König) gar nicht kannten.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 19, 'Denn dieser, der dem Herrscher alsbald zu gefallen wünschte, suchte unter Aufbietung seiner Kunst eine verschönerte Ähnlichkeit darzustellen;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 20, 'der große Haufe aber, durch die Anmut des Kunstwerks hingerissen, hielt nun den vor kurzem noch als Mensch Geehrten für einen Gegenstand der Anbetung.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 21, 'Dies wurde nun aber für das Leben ein Anlaß zur Sünde, daß nämlich die Menschen, sei es einem Trauerfalle, sei es der Herrschergewalt sich fügend, den Namen, der keinem andern beigelegt werden darf, Bildern von Stein und Holz beilegten.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 22, 'Weiterhin genügte es ihnen nicht mehr, in betreff der Gotteserkenntnis zu irren, sondern, wiewohl sie infolge ihrer Unwissenheit in großem Kampfe lebten, nennen sie doch so schlimme Übel Frieden.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 23, 'Denn indem sie bald kindermörderische Weihen oder verborgene Geheimkulte feiern, bald tolle Gelage nach fremden Bräuchen veranstalten,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 24, 'bewahren sie weder den Lebenswandel, noch die Ehen rein; nein, einer bringt den andern durch Meuchelmord um oder kränkt ihn durch Ehebruch.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 25, 'Bei allen ohne Unterschied herrscht Blutvergießen und Totschlag, Diebstahl und Betrug, Verführung und Treulosigkeit, Aufruhr und Meineid,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 26, 'Beunruhigung der Guten und Undankbarkeit, Befleckung der Seelen und unnatürlicher Geschlechtsverkehr, Zerrüttung der Ehen, Ehebruch und Unzucht.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 27, 'Denn die Verehrung der namenlosen Götzenbilder ist alles Unheils Anfang, Ursache und Ausgang;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 28, 'denn entweder rasen sie in ihren Lustbarkeiten oder weissagen Lügen, oder sie leben in Gottlosigkeit oder schwören ohne Scheu falsche Eide.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 29, 'Denn da sie auf leblose Götzen vertrauen, leben sie in dem Glauben, daß jenen, wenn man falsch schwöre, keine Beleidigung widerfahren sei.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 30, 'Aber für beides wird die gerechte Strafe sie treffen, nämlich dafür, daß sie sich gegen den wahren Gott ablehnend verhalten haben, indem sie sich zu den Götzen hielten, und dafür, daß sie in trügerischer Absicht falsch geschworen haben unter Mißachtung der Frömmigkeit.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 31, 'Denn nicht die Macht der Götter, bei denen man schwört, sondern die den Sündern gebührende Strafe folgt stets der Übertretung der Gottlosen nach.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 1, 'Du aber, unser Gott, bist gütig und wahrhaftig; mit Langmut und Barmherzigkeit regierst du das All.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 2, 'Denn wenn wir auch sündigen, gehören wir doch dir, da wir deine Macht kennen; wir wollen aber nicht sündigen, da wir wissen, daß wir dir zugeteilt sind.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 3, 'Denn dich erkennen ist vollkommene Gerechtigkeit, und deine Macht kennen ist die Wurzel der Unsterblichkeit.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 4, 'Denn uns hat weder die verderbliche, von Menschen erfundene Kunst irregeführt, noch die unnütze Arbeit der Maler: eine mit bunten Farben beschmierte Gestalt,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 5, 'deren Anblick die Toren in Leidenschaft versetzt, so daß sie nach der leblosen Gestalt eines toten Bildes sehnsüchtiges Verlangen tragen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 6, 'Liebhaber des Bösen und solcher Hoffnungen würdig sind sowohl ihre Verfertiger als auch die, welche Verlangen nach ihnen tragen und sie anbeten.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 7, 'Der Töpfer nämlich knetet mühsam weichen Ton und formt daraus jeden einzelnen Gegenstand für unseren Gebrauch; aber aus demselben Ton bildet er ebensowohl die Gefäße, die zu reinen Verrichtungen dienen, als auch die zu entgegengesetztem Zweck bestimmten, alle in gleicher Weise; wozu aber ein jedes von diesen beiden Arten gebraucht werden soll, darüber entscheidet der Tonarbeiter.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 8, 'Nun bildet er auch mit übel angewandter Mühe aus dem nämlichen Ton einen nichtigen Gott, er, der selbst erst vor kurzem aus Erde gebildet ist und bald wieder dahin zurückkehren muß, woher er gekommen ist, wenn nämlich die Seele, die ihm geliehen worden ist, von ihm zurückgefordert wird.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 9, 'Doch darüber macht er sich keine Sorge, daß er bald abscheiden muß und nur ein kurzes Leben vor sich hat; nein, er will es den Goldarbeitern und Silberschmieden gleichtun und ahmt den Erzgießern nach und bildet sich etwas darauf ein, daß er Trugbilder fertigt.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 10, 'Asche ist sein Erz und seine Hoffnung geringwertiger als Staub und sein Leben wertloser als sein Ton;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 11, 'er hat ja den nicht erkannt, der ihn selbst gebildet und ihm die schaffende Seele eingehaucht und ihm den Lebensodem eingeblasen hat.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 12, 'Er hat vielmehr unser Dasein nur als ein Spiel angesehen und unser Leben als einen gewinnbringenden Jahrmarkt; denn, sagt er, man müsse doch etwas zu verdienen suchen, woher es auch komme, selbst von etwas Schlechtem.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 13, 'Ein solcher Mensch weiß ja doch besser als jeder andere, daß er Unrecht tut, wenn er aus der Tonmasse leichtzerbrechliche Gefäße und Götterbilder verfertigt.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 14, 'Alle aber sind ganz unverständig und an Einsicht elender als ein unmündiges Kind, die Feinde deines Volkes, die es unterjocht haben,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 15, 'insofern sie auch alle Götzen der Heiden für Götter gehalten haben, wiewohl sie weder Augen besitzen, die sie zum Sehen gebrauchen könnten, noch Nasen, um Luft einzuatmen, noch Ohren zum Hören, noch Finger zum Tasten; und ihre Füße sind unbrauchbar zum Gehen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 16, 'Ein Mensch ist es ja, der sie gemacht hat, und einer, der selbst nur einen geliehenen Odem besitzt, hat sie gebildet; kein Mensch vermag ja einen auch nur ihm selbst gleichen Gott zu bilden;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 17, 'vielmehr als Sterblicher kann er nur etwas Totes mit seinen gottlosen Händen zustande bringen. Er selbst steht ja höher als die Gegenstände, die er anbetet, insofern er selbst Leben besitzt, jene aber niemals.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 18, 'Aber auch die feindseligsten Tiere betet man an, die doch durch ihre Dummheit, verglichen mit den anderen, noch unter diesen stehen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 19, 'Auch sind sie nicht schön, daß man Wohlgefallen an ihnen haben könnte, wie das sonst beim Anblick von Tieren der Fall ist. Sie sind aber auch des Lobes Gottes und seines Segens verlustig gegangen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 16, 1, 'Darum sind sie auch verdientermaßen durch ähnliche Tiere gestraft und durch eine Menge von Ungeziefer heimgesucht worden.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 16, 2, 'Anstatt einer solchen Züchtigung aber erwiesest du deinem Volke eine Wohltat und bereitetest ihnen für ihr lüsternes Verlangen eine wunderbare Kost, nämlich Wachteln als Nahrung,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 16, 3, 'damit jene, wenn sie nach Nahrung verlangten, infolge des widerlichen Aussehens der ihnen zugesandten Tiere auch die natürliche Eßlust sich vergehen ließen, diese dagegen nach einer kurzen Entbehrung sogar eine ganz wundersame Kost genossen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 16, 4, 'Denn es sollte über jene, die Unterdrücker, ein unabwendbarer Mangel hereinbrechen, während diesen nur gezeigt werden sollte, wie ihre Feinde heimgesucht wurden.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 16, 5, 'Dagegen als auch über sie die schreckliche Wut wilder Tiere kam und sie durch die Bisse der sich ringelnden Schlangen umkamen, dauerte doch dein Zorn nicht ohne Ende;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 16, 6, 'nein, nur auf kurze Zeit wurden sie zur Warnung in Schrecken gesetzt und erhielten ein Zeichen der Rettung zur Erinnerung an die Gebote deines Gesetzes.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 16, 7, 'Denn wer sich dahin wandte, wurde gerettet nicht durch das, was er anschaute, sondern durch dich, den Retter aller;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 16, 8, 'und dadurch brachtest du auch unsere Feinde zu der Überzeugung, daß du es bist, der aus jeder Not erretten kann.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 16, 9, 'Denn jene tötete der Biß der Heuschrecken und Stechfliegen, und es fand sich kein Heilmittel zur Rettung ihres Lebens, weil sie es verdient hatten, auf diese Weise bestraft zu werden.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 16, 10, 'Deine Kinder dagegen konnten auch die Zähne giftsprühender Schlangen nicht vernichten, denn dein Erbarmen erschien zu ihrer Rettung und heilte sie.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 16, 11, 'Denn nur, damit sie deiner Gebote gedächten, wurden sie gestochen und schnell wieder geheilt, damit sie nicht in tiefes Vergessen verfielen und für deine Wohltaten ganz umempfänglich würden.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 16, 12, 'Denn weder ein Kraut noch ein Pflaster machte sie gesund, sondern dein Wort, o Herr, das alles heilt.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 16, 13, 'Denn du hast Macht über Leben und Tod und führst zu den Pforten der Unterwelt hinab und wieder herauf.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 16, 14, 'Hat ein Mensch dagegen einen andern durch seine Bosheit getötet, so kann er den Lebensodem, der einmal entflohen ist, nicht wieder zurückbringen und die Seele, die hinweggenommen ist, nicht befreien.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 16, 15, 'Aber deiner Hand zu entrinnen ist unmöglich.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 16, 16, 'Denn jene Gottlosen, die da leugneten, dich zu kennen, wurden durch die Kraft deines Armes gezüchtigt; sie wurden von furchtbaren Regengüssen, von Hagelschlägen und Gewittern verfolgt und durch Feuer verzehrt.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 16, 17, 'Was aber das Wunderbarste dabei war: durch das Wasser, das doch sonst alles löscht, erhielt das Feuer noch stärkere Kraft; denn die Natur streitet für die Gerechten.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 16, 18, 'Zuweilen zwar ließ die Wut der Flammen nach, damit sie nicht auch die gegen die Gottlosen gesandten Tiere verzehrte, sondern damit sie selbst zu der klaren Erkenntnis kämen, daß sie von Gottes Strafgericht verfolgt würden.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 16, 19, 'Bisweilen brannte es aber auch mitten im Wasser stärker, als sonst das Feuer brennt, um die Erzeugnisse des sündigen Landes zu verzehren.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 16, 20, 'Dem gegenüber speistest du dein Volk mit Engelkost und botest ihnen vom Himmel herab Brot dar, das ohne ihre Arbeit hergestellt war, das allgemeine Freude hervorrief und dem Geschmack jedes einzelnen zusagte.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 16, 21, 'Denn die von dir gesandte Masse offenbarte deinen Kindern die Süßigkeit, die du gegen sie hegtest, und indem sie dem Begehren eines jeden, der davon genoß, entgegenkam, verwandelte sie sich in das, was jeder gerade wünschte.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 16, 22, 'Schnee und Eis widerstanden dem Feuer und schmolzen nicht, damit man zu der Erkenntnis käme, daß dasselbe Feuer, welches im Hagel brannte und in den Regengüssen blitzte und die Feldfrüchte der Feinde vernichtete,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 16, 23, 'in diesem Falle seine eigene Kraft vergessen habe, damit die Gerechten ernährt würden.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 16, 24, 'Denn die Natur, die dir, ihrem Schöpfer, dient, steigert ihre Kraft zur Züchtigung wider die Gottlosen und beruhigt sich wieder, um denen wohlzutun, die auf dich vertrauen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 16, 25, 'Darum hat sie auch damals deiner allnährenden Gabe gedient, indem sie sich in alles verwandelte je nach dem Wunsche derer, die ihrer bedurften;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 16, 26, 'deine Kinder, die du lieb hattest, o Herr, sollten eben die Erkenntnis gewinnen, daß nicht die gewachsenen Feldfrüchte den Menschen ernähren, sondern daß dein Wort es ist, welches die auf dich Vertrauenden erhält.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 16, 27, 'Denn was das Feuer nicht hatte verzehren können, das schmolz ohne weiteres, wenn ein flüchtiger Sonnenstrahl es erwärmte,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 16, 28, 'damit es bekannt würde, daß man schon vor Sonnenaufgang dir danken und am Morgen schon vor dem Hellwerden vor dir erscheinen müsse.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 16, 29, 'Denn die Hoffnung der Undankbaren schmilzt dahin wie winterlicher Reif und zerrinnt wie unbrauchbares Wasser.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 17, 1, 'Groß sind deine Gerichte und unerforschlich; darum sind unerleuchtete Seelen in Irrtum verfallen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 17, 2, 'Denn die Gottlosen, die da gedacht hatten, das heilige Volk in Knechtschaft halten zu können, mußten sich selbst in ihren Häusern einschließen, waren in Finsternis gefangen und von langer Nacht umstrickt und lagen da, von der ewigen Vorsehung ausgeschlossen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 17, 3, 'Während sie nämlich wähnten, bei ihren geheimen Sünden verborgen zu sein unter dem dunklen Schleier der Vergessenheit, wurden sie in der Finsternis entsetzlich geängstigt und durch Trugbilder erschreckt.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 17, 4, 'Denn nicht einmal der Winkel, der sie umfing, erhielt sie frei von Furcht; erschreckende Töne wurden ringsum sie laut, und düstere Gestalten mit scheußlichen Gesichtern erschienen ihnen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 17, 5, 'Keines Feuers Kraft war stark genug, Helligkeit zu schaffen, und auch die strahlenden Lichter der Sterne vermochten jene schaurige Nacht nicht zu erhellen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 17, 6, 'Es erschien ihnen nur eine selbstentzündete Feuerflamme voller Furchtbarkeit, und durch diesen noch niemals gesehenen Anblick mit Entsetzen erfüllt, hielten sie das Geschaute für noch schlimmer, als es war.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 17, 7, 'Die Gaukeleien ihrer Zauberkunst erwiesen sich als machtlos dagegen, und die Prüfung ihrer prahlerischen Weisheit fiel schmachvoll für sie aus;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 17, 8, 'denn sie, die da versprachen, die Schrecken und Ängste der kranken Seelen zu bannen, erkrankten selbst an lächerlicher Furcht.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 17, 9, 'Denn auch dann, wenn nichts Furchtbares sie schreckte, wurden sie doch durch das Vorüberkriechen des Gewürms und das Zischen der Schlangen aufgeschreckt und kamen vor Angst um; sie weigerten sich sogar, in die Luft zu schauen, der man sich doch nimmermehr entziehen kann.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 17, 10, 'Denn feige ist die durch ihr eigenes Zeugnis verurteilte Bosheit, und immer vom bösen Gewissen gedrängt, macht sie sich auf das Schlimmste gefaßt.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 17, 11, 'Denn die Furcht ist nichts anderes als ein Preisgeben der von der Überlegung dargebotenen Hilfsmittel;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 17, 12, 'und wenn die Zuversicht im Inneren geschwächt ist, so hält sie die Ratlosigkeit für ein größeres Übel als die Ursache, welche die Qual veranlaßt.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 17, 13, 'Als jene nun die an und für sich ohnmächtige Nacht, die aus den Tiefen der ebenfalls ohnmächtigen Unterwelt heraufgestiegen war, in dem gewöhnlichen Schlafe zubringen wollten,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 17, 14, 'wurden sie teils durch Gespenstererscheinungen umhergetrieben, teils durch das Aufgeben alles Selbstvertrauens gelähmt: denn eine plötzliche und unerwartete Furcht befiel sie.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 17, 15, 'So wurde also jeder, der sich dort befand, wenn er niederfiel, gefangen gehalten, indem er in einen Kerker ohne Eisenfesseln eingeschlossen war.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 17, 16, 'Mochte jemand ein Ackersmann sein oder ein Hirt oder ein mit mühsamer Arbeit in der Wüste beschäftigter Tagelöhner: von der Finsternis überrascht, mußte er die unentrinnbare Notlage über sich ergehen lassen; denn alle waren mit der nämlichen Kette der Dunkelheit gefesselt.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 17, 17, 'Ob säuselnder Windhauch es war, oder lieblicher Vogelsang in dichtbelaubten Zweigen, oder das Rauschen des mit Macht daherströmenden Wassers,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 17, 18, 'oder das schauerliche Krachen herabstürzender Felsen, oder das unsichtbare Laufen hüpfender Wesen, oder das Geheul der grausigsten Tiere, oder der aus den Höhlen des Gebirges zurückgeworfene Widerhall: – alle diese Schrecknisse lähmten sie.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 17, 19, 'Denn die ganze übrige Welt erglänzte in strahlendem Licht, und jeder konnte ungehindert seine Geschäfte betreiben;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 17, 20, 'nur über jene war tiefe Nacht ausgebreitet, ein Vorbild der Finsternis, die sie einst aufnehmen sollte; sich selber aber waren sie eine noch drückendere Last, als die Finsternis es war.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 17, 21, '');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 18, 1, 'Deine Heiligen befanden sich unterdessen im hellsten Licht; deren Stimmen hörten die Ägypter wohl, konnten sie aber persönlich nicht sehen; noch priesen sie jene glücklich, daß sie nicht ebenso hatten leiden müssen wie sie selbst.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 18, 2, 'Ja, sie waren dankbar, daß jene, obschon zuerst mißhandelt, ihnen nicht Schaden zugefügt hatten; sie baten sogar um Verzeihung für ihre Feindschaft.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 18, 3, 'Dagegen gabst du ihnen die feuerflammende Säule als Wegführerin auf der Wanderung durch unbekanntes Land und als unschädliche Sonne für die ruhmvolle Wanderung.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 18, 4, 'Jene dagegen hatten es verdient, des Lichts beraubt zu werden und in der Finsternis gefangen zu sein, weil sie deine Söhne in Gefangenschaft gehalten hatten, durch welche das unvergängliche Licht des Gesetzes der Welt mitgeteilt werden sollte.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 18, 5, 'Weil jene aber beschlossen hatten, die Kinder der Heiligen zu töten, und eins von den Kindern ausgesetzt, aber gerettet worden war, so nahmst du zur Strafe ihre Kinder in Menge hinweg und ließest sie alle bis auf den letzten Mann in gewaltiger Wasserflut umkommen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 18, 6, 'Jene Nacht wurde unseren Vätern im voraus angezeigt, damit sie sicher wüßten, auf welche Eidschwüre sie ihr Vertrauen setzten und gutes Mutes wären;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 18, 7, 'und so wurde von deinem Volke die Rettung der Gerechten und der Untergang seiner Feinde erwartet;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 18, 8, 'denn wodurch du die Gegner straftest, eben dadurch verherrlichtest du uns, indem du uns zu dir riefst.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 18, 9, 'Denn im Verborgenen brachten die heiligen Söhne trefflicher Eltern ihr Opfer dar und stellten die göttliche Satzung einmütig fest, daß die Heiligen in gleicher Weise an den Gütern und an den Gefahren teilnehmen sollten, nachdem sie zuvor bereits die Lobgesänge ihrer Väter angestimmt hatten.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 18, 10, 'Dagegen erscholl das mißtönende Geschrei der Feinde, und die Wehklage derer, die ihre Kinder beweinten, verbreitete sich überallhin;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 18, 11, 'denn mit gleicher Strafe wurde der Knecht zugleich mit seinem Herrn gezüchtigt, und der Untertan erlitt dasselbe wie der König.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 18, 12, 'Alle ohne Ausnahme aber hatten durch dieselbe Todesart zahllose Tote, und die Überlebenden genügten nicht, um sie zu begraben, weil in einem einzigen Augenblick der vornehmste Teil ihrer Nachkommenschaft hinweggerafft worden war.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 18, 13, 'Während sie also vorher infolge ihrer Zauberkünste völlig ungläubig geblieben waren, bekannten sie jetzt bei der Vernichtung ihrer Erstgeborenen, daß das Volk der Sohn Gottes sei.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 18, 14, 'Denn zu der Zeit, wo tiefes Schweigen alles umfangen hielt und die Nacht sich in der Mitte ihres Laufes befand,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 18, 15, 'da fuhr dein Allmachtswort vom Himmel her von deinem Königsthron wie ein unerbittlicher Krieger in das dem Verderben geweihte Land herab;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 18, 16, 'als scharfes Schwert trug er deinen unwiderruflichen Befehl; er trat hin und verbreitete den Tod im ganzen Lande; den Himmel berührte er und schritt doch auf der Erde dahin.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 18, 17, 'Da schreckten plötzlich furchtbare Traumbilder sie auf, und unerwartete Ängste befielen sie;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 18, 18, 'halbtot stürzten sie, der eine hier, der andere dort, zur Erde nieder und zeigten damit an, welches die Ursache ihres Todes sei;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 18, 19, 'denn die Träume, durch die sie beunruhigt worden waren, hatten dies ihnen zuvor kundgetan, damit sie nicht stürben, ohne zu wissen, warum sie solches Unheil erlitten.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 18, 20, 'Es hat freilich auch die Gerechten die Anfechtung des Todes getroffen: ein Sterben gar vieler von ihnen fand in der Wüste statt; doch das Zorngericht hielt nicht lange an;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 18, 21, 'denn ein unsträflicher Mann beeilte sich, als Vorkämpfer für sie aufzutreten. Indem er die Waffe seines heiligen Dienstes, nämlich Gebet und versöhnendes Räucherwerk, herbeibrachte, trat er dem Grimm entgegen und machte dem Unheil ein Ende; er zeigte so, daß er dein Diener war.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 18, 22, 'Er überwand aber den Zorn nicht durch Körperstärke, noch durch Waffengewalt, sondern durch das Wort bezwang er den Strafenden, indem er an die den Vätern geleisteten Eidschwüre und die mit ihnen geschlossenen Bündnisse erinnerte.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 18, 23, 'Denn als die Toten schon haufenweise übereinander dalagen, trat er dazwischen, brachte das Zorngericht zum Stillstand und schnitt ihm den Weg zu den noch Lebenden ab.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 18, 24, 'Denn auf seinem langwallenden Talar war die ganze Welt (abgebildet) und der Ruhm der Väter auf den vier Reihen geschnittener Steine (angebracht) und deine Herrlichkeit auf der Binde seines Hauptes.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 18, 25, 'Vor diesen Wahrzeichen wich der Verderber zurück, vor ihnen scheute er sich; denn die bloße Erprobung des (göttlichen) Zorns war ausreichend.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 19, 1, 'Die Gottlosen aber bedrängte der erbarmungslose Zorn bis ans Ende; denn Gott wußte auch ihr zukünftiges Verhalten im voraus,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 19, 2, 'daß sie nämlich, obgleich sie selbst zum Auszuge gedrängt und sie geradezu vertrieben hatten, doch andern Sinnes werden und sie verfolgen würden.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 19, 3, 'Und in der Tat: während sie sich noch mitten in der Trauerfeier befanden und noch an den Gräbern ihrer Toten wehklagten, faßten sie mit einemmal einen andern, ganz verfehlten Entschluß und verfolgten wie entlaufene Sklaven die, welche sie eben noch unter Bitten zum Weggehen gedrängt hatten.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 19, 4, 'Denn es zog sie zu diesem Ausgang das verdiente Verhängnis und flößte ihnen Vergessenheit alles dessen ein, was geschehen war, damit sie die an ihren Heimsuchungen noch fehlende Strafe vollends erlitten');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 19, 5, 'und damit dein Volk die wunderbare Wanderung ausführte, während jene einen ungewöhnlichen Tod erlitten.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 19, 6, 'Denn die ganze Schöpfung wurde in ihrer Eigentümlichkeit wiederum aufs neue umgeschaffen, indem sie ganz besonderen Befehlen gehorchte, damit deine Kinder unversehrt erhalten blieben.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 19, 7, 'Da sah man die Wolke, welche den Heereszug überschattete, und das Auftauchen trockenen Landes, wo vorher Wasser gestanden hatte: einen freien Weg aus dem Roten Meere hinaus und eine grünende Flur, die aus den reißenden Fluten emporgestiegen war.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 19, 8, 'Auf dieser zogen sie hindurch, das ganze Volk, von deiner Hand beschirmt, nachdem sie erstaunliche Wunder geschaut hatten.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 19, 9, 'Denn wie Rosse wurden sie geweidet, und wie Lämmer hüpften sie, indem sie dich, o Herr, als ihren Retter priesen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 19, 10, 'Denn sie gedachten noch alles dessen, was sie während ihres Aufenthaltes in dem fremden Lande erlebt hatten, wie die Erde, statt die gewöhnlichen Tiere hervorzubringen, nur Mücken erzeugt hatte, und wie der Nilstrom anstatt der Wassertiere die Unmenge von Fröschen ausgespieen hatte.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 19, 11, 'Später aber sahen sie auch noch eine neue Art Vögel, als sie, von Lüsternheit getrieben, um Leckerbissen gebeten hatten;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 19, 12, 'denn um ihnen Befriedigung zu gewähren, stieg aus dem Meere ein Wachtelschwarm herauf.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 19, 13, 'Jedoch kamen die Strafen über die Frevler nicht, ohne daß Warnungszeichen durch furchtbare Blitzschläge vorausgegangen wären; denn mit Recht litten sie für ihre Bosheitstaten; sie hatten ja einen ganz ungewöhnlichen Fremdenhaß an den Tag gelegt.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 19, 14, 'Jene (die Sodomiten) nämlich hatten nur Unbekannte, die zu ihnen gekommen waren, nicht aufnehmen wollen, diese (die Ägypter) dagegen suchten Gastfreunde, die ihnen Gutes erwiesen hatten, zu Knechten zu machen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 19, 15, 'Und nicht nur dieses, sondern – wofür noch die Strafe sie treffen wird – während jene die Fremden gleich anfangs feindselig aufgenommen hatten,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 19, 16, 'haben diese dagegen diejenigen, welche sie mit Festlichkeiten empfangen hatten und welche bereits zu voller Teilnahme an ihrem Bürgerrecht gelangt waren, mit schweren Fronarbeiten mißhandelt.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 19, 17, 'Sie wurden aber auch mit Blindheit geschlagen, wie einst jene an der Tür des Gerechten, als sie, von tiefer Finsternis umgeben, ein jeder den Eingang zu seiner Haustür suchten.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 19, 18, 'Denn die Elemente unterliegen durcheinander dem Wechsel, gerade wie auf einem Saiteninstrument die Töne der Melodie den Namen wechseln, während sie doch dem Klange nach stets dieselben bleiben, was sich aus der Betrachtung der damaligen Begebenheiten mit Sicherheit entnehmen läßt.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 19, 19, 'Denn Landtiere verwandelten sich in Wassertiere, und Schwimmtiere stiegen ans Land heraus;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 19, 20, 'das Feuer gewann im Wasser stärkere Kraft, und das Wasser vergaß im Feuer seine löschende Kraft.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 19, 21, 'Die Flammen hinwiederum verzehrten nicht das Fleisch leichtvergänglicher Geschöpfe, die in sie hineingerieten, und ließen nicht die eisähnliche leichtschmelzbare Art der himmlischen Nahrung schmelzen. Denn in allen Beziehungen hast du, o Herr, dein Volk geehrt und herrlich gemacht, hast es nie aus den Augen gelassen, sondern ihm allezeit und überall beigestanden.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 1, 'Das Buch der Geschichte Tobits, des Sohnes Tobiels, des Sohnes Ananiels, des Sohnes Aduels, des Sohnes Gabaels, des Sohnes Raphaels, des Sohnes Raguels, aus dem Geschlecht Asiels, vom Stamme Naphthali,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 2, 'welcher zur Zeit des assyrischen Königs Enemessar in die Gefangenschaft weggeführt worden war aus Thisbe, einer Ortschaft, die südlich von Kades-Naphthali in Galiläa oberhalb Aser liegt.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 3, 'Ich, Tobit, bin mein ganzes Leben hindurch auf den Wegen der Wahrheit und Gerechtigkeit gewandelt und habe meinen Brüdern und meinem Volke, die mit mir ins Land der Assyrer nach Ninive gezogen waren, viele Wohltaten erwiesen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 4, 'Als ich mich noch während meiner Jugendzeit in meiner Heimat, im Lande Israel, befand, hatte sich der ganze Stamm meines Ahnen Naphthali vom Hause Jerusalems losgesagt, welches unter allen israelitischen Stämmen auserwählt worden war, damit alle Stämme dort opferten, und der Tempel war dort der Wohnstätte des Höchsten geweiht und für alle zukünftigen Geschlechter erbaut worden.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 5, 'Und alle Stämme, die sich an dem Abfall beteiligt hatten, opferten der Baalskuh, auch das Haus meines Ahnen Naphthali.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 6, 'Ich allein zog oft an den großen Festen nach Jerusalem, wie dies allen Israeliten durch eine ewige Satzung vorgeschrieben ist; dabei nahm ich die Erstlinge und die Zehnten der Bodenerzeugnisse und die Erstlinge der Schafschur mit und übergab sie den Priestern, den Nachkommen Aarons, für den Altardienst.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 7, 'Ebenso gab ich von allen Bodenerzeugnissen den Zehnten an die Leviten ab, die in Jerusalem den heiligen Dienst versahen; den zweiten Zehnten aber verkaufte ich und verwandte ihn alljährlich bei meiner Reise in Jerusalem.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 8, 'Den dritten Zehnten aber gab ich denen, für die er bestimmt war, wie es mir Debora, die Mutter meines Vaters, geboten hatte; denn ich war als Waise von meinem Vater zurückgelassen worden.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 9, 'Als ich dann ins Mannesalter gekommen war, heiratete ich eine Verwandte namens Anna, und sie gebar mir einen Sohn Tobias.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 10, 'Als wir hierauf nach Ninive in die Gefangenschaft weggeführt waren, aßen alle meine Stammes- und Volksgenossen dieselben Speisen wie die Heiden;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 11, 'ich aber hütete mich gewissenhaft, davon zu essen,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 12, 'weil ich Gottes von ganzem Herzen eingedenk war.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 13, 'So verlieh mir denn der Höchste, Gnade und Gunst bei Enemessar zu finden, dessen Einkäufer ich wurde.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 14, 'Ich machte Reisen nach Medien und hinterlegte bei Gabael, dem Bruder des Gabrias zu Rages in Medien, zehn Talente Silber.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 15, 'Als dann Enemessar starb, wurde sein Sohn Sennacherim König an seiner Statt. Seine Regierung war eine sehr unruhige, und ich konnte nicht mehr nach Medien reisen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 16, 'Während der Regierung Enemessars hatte ich meinen Volksgenossen viele Wohltaten erwiesen;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 17, 'ich hatte mein Brot den Hungernden und Kleidung den Entblößten gegeben; und wenn ich einen aus meinem Volke sah, dessen Leiche man hinter die Mauer von Ninive geworfen hatte, so hatte ich ihn begraben.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 18, 'Und wenn der König Sennacherim, nachdem er als Flüchtling aus Judäa zurückgekehrt war, jemanden hatte töten lassen, begrub ich ihn heimlich; denn viele ließ er in seinem Zorn hinrichten, deren Leichen dann vom König gesucht und nicht gefunden wurden.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 19, 'Nun ging aber einer von den Niniviten hin und zeigte dem Könige an, daß ich es sei, der sie insgeheim begrübe, und ich mußte mich verbergen. Als ich aber erfuhr, daß man nach mir suchte, um mich zu töten, fürchtete ich mich und begab mich auf die Flucht.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 20, 'Da wurde mein ganzes Vermögen eingezogen, und mir blieb nichts übrig als meine Frau Anna und mein Sohn Tobias.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 21, 'Aber ehe noch fünfzig Tage vergangen waren, wurde der König von zweien seiner Söhne ermordet, die sich dann in das Bergland Ararat flüchteten. Sein Sohn Sacherdon wurde hierauf König an seiner Statt und setzte Achjachar, den Sohn meines Bruders Anael, über das ganze Geldwesen seines Reiches und über die ganze Verwaltung.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 22, 'Achjahar verwandte sich nun für mich, und so konnte ich wieder nach Ninive zurückkehren. Dieser Achjachar war aber Mundschenk, Siegelbewahrer, Kanzler und Finanzminister, und Sacherdon hatte ihm die höchste Stelle im Reiche übertragen; er war aber mein Neffe.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 23, '');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 24, '');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 25, '');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 1, 'Als ich nun in mein Haus zurückgekehrt und meine Frau Anna und mein Sohn Tobias mir zurückgegeben waren, da wurde am Pfingstfest, d.h. am heiligen Feste der sieben Wochen, ein schönes Mahl bei mir zubereitet, und ich ließ mich nieder, um zu essen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 2, 'Als ich nun die vielen Speisen sah, sagte ich zu meinem Sohne: »Geh, und wenn du unter unsern Volksgenossen irgend einen Notleidenden findest, der des Herrn eingedenk ist, so bringe ihn her: ich will unterdessen auf dich warten«.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 3, 'Bei seiner Rückkehr sagte er: »Vater, einer von unserm Volke liegt erdrosselt auf dem Marktplatze«.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 4, 'Sofort, ohne etwas genossen zu haben, sprang ich auf und brachte ihn in ein Gebäude, bis die Sonne untergegangen war.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 5, 'Nach meiner Rückkehr wusch ich mich und verzehrte mein Mahl in Trauer.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 6, 'Dabei fielen mir die prophetischen Worte des Amos ein, die da lauten: »Eure Feste sollen sich in Trauer verwandeln und all euer Frohlocken in Wehklagen«.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 7, 'Ich mußte weinen; und als die Sonne untergegangen war, ging ich hin, grub ein Grab und bestattete ihn.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 8, 'Meine Nachbarn verlachten mich und sagten: »Er fürchtet sich nicht mehr, wegen solcher Tat hingerichtet zu werden; er hat fliehen müssen und begräbt nun doch schon wieder die Toten«.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 9, 'In derselben Nacht schlief ich nach meiner Rückkehr vom Begräbnis, weil ich verunreinigt war, neben der Hofmauer, und zwar mit unbedecktem Gesicht.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 10, 'Ich wußte nicht, daß Sperlinge in der Mauer waren; und während meine Augen geöffnet waren, schmeißten die Sperlinge heiß in meine Augen. Als sich nun weiße Flecke darin gebildet hatten, wandte ich mich an die Ärzte, die mir aber nicht helfen konnten. Achjachar sorgte nun für meinen Unterhalt, bis er nach Elymais zog.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 11, 'Nun fertigte meine Frau Anna in ihrer Frauenwohnung Wollarbeiten an, die sie an die Kaufherren ablieferte;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 12, 'diese zahlten ihr den Lohn aus und schenkten ihr obendrein noch ein Böckchen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 13, 'Als sie nun zu mir heimgekehrt war, fing das Tier an zu schreien. Da fragte ich sie: »Woher kommt das Böckchen? Es ist doch nicht gestohlen? Gib es seinen Eigentümern zurück; denn es ist nicht recht, gestohlenes Gut zu essen«.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 14, 'Doch sie erwiderte: »Als Geschenk ist es mir zu dem Lohne hinzugegeben«. Da ich ihr aber nicht glaubte, befahl ich ihr, es den Eigentümern zurückzugeben, und errötete im Zorn vor ihr. Da antwortete sie mir mit den Worten: »Wo sind nun jetzt deine Almosen und deine Mildtätigkeit? Siehe, wie es mit dir steht, das liegt nun klar zu Tage!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 15, '');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 16, '');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 17, '');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 18, '');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 19, '');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 20, '');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 21, '');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 22, '');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 23, '');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 1, 'Da wurde ich tief betrübt und weinte, und in meinem Schmerz betete ich also:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 2, '»Gerecht bist du, o Herr! Alle deine Werke und alle deine Wege sind Erbarmen und Treue, und das Gericht, welches du übst, ist wahrhaftig und gerecht in Ewigkeit.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 3, 'Gedenke meiner und blicke gnädig auf mich her! Strafe mich nicht nach meinen Sünden und nach meinen Verfehlungen und nach den Vergehen, deren meine Väter sich vor dir schuldig gemacht haben.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 4, 'Denn sie haben deine Gebote übertreten, und so hast du uns zur Ausplünderung, zur Gefangenschaft und zum Tode hingegeben und uns zum Gegenstand des Spottes und Hohnes für alle Heiden gemacht, unter die wir zerstreut sind.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 5, 'Und nun sind auch deine vielen Gerichte wahrhaftig, die du an mir vollziehen willst wegen meiner und meiner Väter Sünden, weil wir deine Gebote nicht gehalten haben; denn wir sind nicht in Aufrichtigkeit vor dir gewandelt.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 6, 'Und nun verfahre mit mir nach deinem Wohlgefallen; gebiete, daß mein Geist von mir genommen werde, damit ich abscheide und Erde werde; denn für mich ist es besser zu sterben als zu leben. Ich habe ja lügnerische Schmähungen hören müssen, und tiefe Betrübnis ist in mir. Gebiete, daß ich aus dieser Notlage befreit werde und schon jetzt an die ewige Stätte gelange. Wende dein Angesicht nicht von mir ab!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 7, 'An demselben Tage begab es sich, daß auch Sara, die Tochter Raguels zu Ekbatana in Medien, von den Mägden ihres Vaters verhöhnt wurde.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 8, 'Sie war nämlich schon mit sieben Männern verheiratet gewesen, aber Asmodäus, der böse Geist, hatte sie alle sterben lassen, ehe sie die Ehe mit ihr vollzogen hatten. Sie sagten also zu ihr: »Du bist wohl nicht bei Sinnen, daß du deine Männer ums Leben bringst? Schon sieben hast du gehabt, aber den Namen keines von ihnen getragen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 9, 'Was schlägst du uns? Wenn sie gestorben sind, so folge ihnen nach! Wir möchten nun und nimmer einen Sohn oder eine Tochter von dir zu sehen bekommen!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 10, 'Als sie dies hörte, wurde sie tief betrübt, daß sie sich erhängen wollte; doch sie dachte: »Ich bin das einzige Kind meines Vaters. Tue ich dies so ist’s eine Schande für ihn, und ich bringe sein Greisenalter mit Herzeleid in die Unterwelt«.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 11, 'Dann betete sie an einem Fenster mit den Worten: »Gepriesen seist du, Herr, mein Gott, und gepriesen sei dein heiliger und ehrwürdiger Name in Ewigkeit! Preisen müssen dich alle deine Werke ewiglich!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 12, 'Jetzt aber, Herr, habe ich meine Augen und mein Antlitz auf dich gerichtet.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 13, 'Gebiete, daß ich von der Erde abberufen werde und keine Schmähung mehr anzuhören brauche.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 14, 'Du weißt, Herr, daß ich rein bin von jeder Sünde mit einem Mann');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 15, 'und daß ich meinen Namen und den Namen meines Vaters nicht entehrt habe in diesem Lande unserer Gefangenschaft. Ich bin die einzige Tochter meines Vaters, und er hat weiter kein Kind, das ihn beerben könnte; es ist auch kein naher Verwandter vorhanden und kein Sohn eines solchen, für den ich mich als Weib erhalten sollte. Schon sind mir sieben Männer gestorben; wozu noch länger leben? Gefällt es dir aber nicht, mich sterben zu lassen, so gebiete, daß man Rücksicht auf mich nehme und Mitleid mit mir habe, damit ich keine Schmähung mehr zu hören brauche«.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 16, 'Und das Gebet beider fand Erhörung vor der Herrlichkeit des großen Gottes,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 17, 'und Raphael wurde abgesandt, die beiden zu heilen, nämlich die weißen Flecken von Tobits Augen wegzuschaffen und Sara, die Tochter Raguels, mit Tobias, dem Sohne Tobits, zu vermählen und den bösen Geist Asmodäus zu fesseln, weil Tobias ein Recht habe, durch sie der Erbe zu werden. Zu gleicher Zeit kehrte Tobit in sein Haus zurück, und Raguels Tochter Sara stieg aus ihrem Obergemach hernieder.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 18, '');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 19, '');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 20, '');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 21, '');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 22, '');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 23, '');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 24, '');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 25, '');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 1, 'An diesem Tage erinnerte sich Tobit des Geldes, das er bei Gabael zu Rages in Medien hinterlegt hatte.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 2, 'Da dachte er bei sich: »Ich habe mir den Tod gewünscht; warum rufe ich nun nicht meinen Sohn Tobias, damit ich ihm Mitteilung von der Sache mache, ehe ich sterbe?«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 3, 'Nachdem er ihn also herbeigerufen hatte, sagte er zu ihm: »Mein Sohn, wenn ich sterbe, so begrabe mich und vernachlässige deine Mutter nicht; ehre sie dein Leben lang, tue, was ihr wohlgefällt, und betrübe sie nicht.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 4, 'Bedenke, mein Sohn, daß sie deinetwegen vielen Gefahren ausgesetzt gewesen ist, während sie dich unter dem Herzen trug; wenn sie stirbt, begrabe sie bei mir in demselben Grabe.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 5, 'Dein Leben lang, mein Sohn, bleibe des Herrn, deines Gottes eingedenk und hüte dich vor der Sünde und vor der Übertretung seiner Gebote. Übe Gerechtigkeit, solange du lebst, und wandle nicht auf den Wegen des Unrechts;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 6, 'denn wenn du ehrenhaft handelst, werden dir alle deine Unternehmungen gelingen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 7, 'Und allen denen, die redlich handeln, erweise Barmherzigkeit von deinem Vermögen und laß dein Auge nicht mißgünstig sein, wenn du Almosen spendest. Wende dein Angesicht von keinem Armen weg, so wird auch Gottes Angesicht sich nicht von dir wegwenden.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 8, 'Jenachdem dein Vermögen es gestattet, übe Mildtätigkeit; hast du nur wenig, so scheue dich nicht, dem Wenigen entsprechend Wohltaten zu erweisen;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 9, 'denn dadurch sammelst du dir einen reichen Schatz für die Zeit der Not;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 10, 'denn Almosengeben rettet vom Tode und verhütet, daß man in das Reich der Finsternis eingeht;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 11, 'denn Almosengeben ist ein treffliches Opfer für alle, die es vor dem Höchsten üben.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 12, 'Hüte dich, mein Sohn, vor aller Unzucht und nimm dir vor allen Dingen ein Weib aus den zum Volke deiner Väter Gehörigen; nimm dir kein fremdes Weib, das nicht zum Stamme deines Vaters gehört; denn wir sind Nachkommen von Propheten. Noah, Abraham, Isaak und Jakob, unsere Väter von der Urzeit her, – bedenke wohl, mein Sohn, daß sie alle Weiber aus ihren Volksgenossen genommen haben und in ihren Kindern gesegnet worden sind, und daß ihre Nachkommen das Land (Kanaan) besitzen sollen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 13, 'Und nun, mein Sohn, liebe deine Brüder und wende dich nicht hochmütigen Herzens von deinen Brüdern und von den Söhnen und Töchtern deines Volkes ab, daß du dir nicht ein Weib aus ihnen nehmen wolltest; denn im Hochmut liegt Unheil und viel Unruhe und in nichtsnutzigem Wesen Verarmung und großer Mangel; denn das nichtsnutzige Wesen ist die Mutter des Hungers.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 14, 'Laß den Lohn eines Menschen, der für dich arbeitet, nicht in deinem Hause übernachten, sondern zahle ihn sogleich aus. Wenn du so deinem Gott dienst, wirst du dafür belohnt werden. Habe acht auf dich, mein Sohn, in allem, was du tust, und benimm dich wohlerzogen in deinem ganzen Wandel.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 15, 'Tue niemandem, was dir selbst widerwärtig ist. Wein trinke nicht bis zur Trunkenheit, und laß die Trunksucht nicht deine Gefährtin auf dem Lebenswege sein.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 16, 'Von deinem Brote gib dem Hungrigen und von deinen Kleidern denen, die ungenügend gekleidet sind. Alles, was du übrig hast, verwende zur Wohltätigkeit und laß dein Auge nicht mißgünstig blicken, wenn du Wohltaten erweisest.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 17, 'Spende deine Brote reichlich beim Begräbnis der Gerechten, aber den Gottlosen gib nichts.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 18, 'Suche Rat bei jedem einsichtigen Manne und verschmähe keinen nützlichen Ratschlag.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 19, 'Allezeit preise Gott den Herrn und bitte ihn, daß deine Wege geebnet seien und alle deine Pfade und Pläne guten Erfolg haben mögen. Denn niemand hat Gewalt über seine Pläne, sondern der Herr ist’s der allen Segen verleiht und der auch erniedrigt, wen er will, nach seinem Belieben. Und nun, mein Sohn, bleibe meiner Ermahnungen eingedenk und laß sie aus deinem Herzen nicht entschwinden. –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 20, 'Jetzt aber mache ich dir noch Mitteilung von den zehn Talenten Silber, die ich bei Gabael, dem Sohn des Gabrias, zu Rages in Medien hinterlegt habe.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 21, 'Und laß dir nicht angst sein, mein Sohn, weil wir arm geworden sind. Du bist reich genug, wenn du Gott fürchtest und dich von aller Sünde fern hältst und das tust, was ihm wohlgefällt«.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 22, '');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 1, 'Darauf antwortete Tobias folgendermaßen: »Vater, ich will alles tun, was du mir geboten hast.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 2, 'Aber wie werde ich das Geld erhalten können, da ich den Mann gar nicht kenne?«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 3, 'Da gab er ihm den Schuldschein und sagte zu ihm: »Suche dir einen Mann als Reisegefährten; ich will ihm Lohn zahlen, solange ich lebe. Dann mache dich auf den Weg und nimm das Geld in Empfang«.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 4, 'Hierauf ging Tobias aus dem Hause, um einen Mann zu suchen, und fand den Raphael, – der ein Engel war, was er aber nicht wußte –;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 5, 'er sagte zu ihm: »Könnte ich wohl mit dir nach Rages in Medien reisen, und kennst du die Gegenden?«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 6, 'Der Engel antwortete ihm: »Ich will mit dir reisen, ich kenne den Weg gut; ich habe bei unserem Bruder Gabael gewohnt«.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 7, 'Da sagte Tobias zu ihm: »Warte auf mich, ich will’s meinem Vater mitteilen«.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 8, 'Er erwiderte ihm: »Geh nur, aber bleibe nicht zu lange aus«. – Er ging nach Hause und sagte zu seinem Vater: »Siehe, ich habe einen Reisegefährten gefunden«. Da sagte der Vater: »Rufe ihn her, damit ich erfahre von welchem Stamme er ist und ob man Vertrauen zu ihm haben kann, daß er dich auf der Reise begleite«.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 9, 'Er rief ihn also, und als er eingetreten war, begrüßten sie sich.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 10, 'Tobit fragte ihn dann: »Mein Bruder, aus welchem Stamme und aus welcher Familie bist du? Sage es mir«.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 11, 'Jener antwortete: »Willst du Stamm und Familie ausfindig machen oder einen Lohndiener, der deinen Sohn auf der Reise begleiten soll?« Tobit gab ihm zur Antwort: »Mein Bruder, ich möchte deine Herkunft und deinen Namen wissen«.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 12, 'Jener antwortete: »Ich bin Asarja, der Sohn des großen Ananja, von deinen Verwandten«.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 13, 'Da sagte Tobit zu ihm: »Sei willkommen, Bruder, und sei mir nicht böse, daß ich deinen Stamm und deine Familie habe erfahren wollen. Da bist du ja ein Verwandter von mir aus guter und trefflicher Familie. Ich habe ja den Ananja und Jonathan, die Söhne Simeis des Großen, kennen gelernt, als wir zusammen nach Jerusalem zogen, um dort anzubeten, und die Erstlinge und Zehnten des Feldertrags dahin zu bringen; ja, sie haben sich nicht fortreißen lassen zu den Verirrungen unserer Brüder; du bist von gutem Stamme, mein Bruder.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 14, 'Aber sage mir: welchen Lohn soll ich dir geben? Etwa eine Drachme täglich und was du für deinen Unterhalt brauchst, wie auch mein Sohn?');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 15, 'Ich will dir auch noch etwas zu dem Lohn hinzulegen, wenn ihr gesund heimkehrt«.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 16, 'Auf diese Bedingungen hin schlossen sie den Vertrag ab. Dann sagte er zu Tobias: »Mache dich reisefertig und zieht glücklich eures Weges!« Als dann der Sohn sich reisefertig gemacht hatte, sagte sein Vater zu ihm: »Ziehe hin mit diesem Manne! Gott aber, der im Himmel wohnt, möge eure Reise segnen, und sein Engel möge euch begleiten!« So machten sich denn beide auf den Weg, und der Hund des Jünglings lief mit ihnen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 17, 'Aber seine Mutter Anna fing an zu weinen und sagte zu Tobit: »Warum hast du unser Kind fortgeschickt? Ist er nicht die Stützte für unsere Hand, solange er vor unsern Augen aus- und eingeht?');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 18, 'Das Geld brauchte nicht zum Gelde hinzuzukommen, sondern hätte das Lösegeld für das Leben unseres Kindes darstellen sollen!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 19, 'Denn soviel uns vom Herrn zum Lebensunterhalt gegeben worden ist, das genügt für uns«.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 20, 'Doch Tobit antwortete ihr: »Rege dich nicht auf, meine Schwester! Er wird gesund heimkehren, und deine Augen werden ihn wiedersehen;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 21, 'denn ein guter Engel wird mit ihm ziehen; seine Reise wird glücklich verlaufen, und er wird gesund zurückkehren«. Da hörte sie auf zu weinen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 22, '');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 23, '');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 24, '');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 25, '');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 26, '');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 27, '');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 28, '');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 29, '');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 1, 'Die beiden Reisenden kamen nun abends an den Fluß Tigris und übernachteten dort.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 2, 'Als nun der junge Mann ins Wasser stieg, um sich zu baden, sprang ein Fisch aus dem Strom und wollte ihn verschlingen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 3, 'Der Engel aber rief ihm zu: »Fasse den Fisch!« Da ergriff der junge Mann den Fisch und warf ihn ans Land.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 4, 'Hierauf sagte der Engel zu ihm: »Schneide den Fisch auf, nimm Herz, Leber und Galle heraus und hebe sie sorgfältig auf!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 5, 'Der junge Mann tat, wie der Engel ihm geboten hatte; den Fisch aber brieten und aßen sie. Beide zogen dann weiter, bis sie in die Nähe von Ekbatana kamen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 6, 'Da fragte der junge Mann den Engel: »Bruder Asarja, was hat’s denn für eine Bewandtnis mit dem Herzen, der Leber und der Galle des Fisches?«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 7, 'Er antwortete ihm: »Was Herz und Leber betrifft, so muß man sie, wenn ein Dämon oder böser Geist jemanden plagt, sei es ein Mann oder eine Frau, vor ihnen in Rauch aufgehen lassen, so werden sie nicht mehr geplagt.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 8, 'Die Galle aber dient dazu, daß man einen Menschen damit bestreiche, der weiße Flecken in den Augen hat; er wird dadurch geheilt werden«.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 9, 'Als sie sich dann Ekbatana näherten, sagte der Engel zu Tobias:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 10, '»Bruder, heute werden wir bei Raguel übernachten; er ist dein Verwandter und hat eine Tochter namens Sara.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 11, 'Ich will ihretwegen mit ihm reden, daß sie dir zur Frau gegeben werde; denn ihr Erbteil kommt dir zu, weil du der einzige bist, der zu ihrer Familie gehört, und das Mädchen ist schön und klug.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 12, 'Und nun höre mich an! Ich will mit ihrem Vater reden, und wenn wir aus Rages zurückgekehrt sind, wollen wir die Hochzeit feiern. Ich weiß, daß Raguel sie nach dem mosaischen Gesetz keinem andern Manne verheiraten kann, ohne des Todes schuldig zu sein; denn dir kommt die Erbschaft vor jedem andern zu«.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 13, 'Darauf sagte der junge Mann zu dem Engel: »Bruder Asarja, ich habe gehört, daß das Mädchen schon an sieben Männer verheiratet gewesen ist und daß sie alle im Brautgemach ums Leben gekommen sind.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 14, 'Nun bin ich der einzige Sohn meines Vaters, und ich fürchte, wenn ich da hineingehe, daß ich auch sterben muß wie die früheren; denn es liebt sie ein Dämon, der keinem etwas zu leide tut außer denen, die sich ihr nahen. Und so fürchte ich auch sterben zu müssen und so das Leben meines Vaters und meiner Mutter mit Betrübnis über mich ins Grab zu bringen; und dann ist kein anderer Sohn für sie da, der sie begraben könnte«.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 15, 'Da antwortete ihm der Engel: »Denkst du denn nicht mehr an die Mahnung, die dein Vater an dich gerichtet hat, du möchtest eine Frau aus deiner Verwandtschaft nehmen? Höre mich nur an, mein Bruder: sie wird deine Frau werden. Um den Dämon mache dir keine Sorgen; noch heute Abend wird sie dir zur Frau gegeben werden.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 16, 'Wenn du dann ins Brautgemach eintrittst, nimmst du Glutasche von Räucherwerk, legst ein Stück von dem Herzen und von der Leber des Fisches darauf und räucherst damit.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 17, 'Sobald der Dämon das riecht, wird er die Flucht ergreifen und in alle Ewigkeit nicht wiederkommen. Wenn du dann zu ihr hingehst, so erhebt euch beide und ruft den barmherzigen Gott an; der wird euch bewahren und sich euer annehmen. Fürchte dich nicht, denn sie ist dir von jeher bestimmt gewesen, und du wirst sie retten. Sie wird dann mit dir ziehen, und ich zweifle nicht, daß du Kinder von ihr erhalten wirst«. Als Tobias dies vernahm, faßte er Liebe zu ihr und sein Herz neigte sich ihr innig zu.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 18, '');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 19, '');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 20, '');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 21, '');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 22, '');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 23, '');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 1, 'Als sie nun nach Ekbatana gekommen und in das Haus Raguels gelangt waren, kam Sara dem Tobias entgegen und begrüßte ihn. Nachdem er ihren Gruß erwidert hatte, führte sie beide ins Haus hinein.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 2, 'Da sagte Raguel zu seiner Frau Edna: »Wie ähnlich ist doch dieser junge Mann meinem Vetter Tobit!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 3, 'Raguel fragte sie dann: »Woher seid ihr, meine Brüder?« Sie antworteten ihm: »Wir sind Naphthaliter aus der Zahl der Kriegsgefangenen in Ninive«.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 4, 'Darauf fragte er sie: »Kennt ihr unsern Bruder Tobit?« Als sie mit »Ja« geantwortet hatten, fragte er sie: »Ist er gesund?«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 5, 'Sie sagten: »Er lebt und ist gesund«, und Tobias fuhr fort: »Er ist mein Vater«.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 6, 'Da sprang Raguel auf, küßte ihn und weinte;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 7, 'dann segnete er ihn und sagte: »O du Sohn des guten und wackeren Mannes!« Als er dann erfuhr, daß Tobit das Augenlicht verloren habe, wurde er betrübt und weinte;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 8, 'auch seine Frau Edna und seine Tochter weinten und nahmen sie herzlich auf;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 9, 'sie schlachteten einen Schafbock und setzten ihnen ein reichliches Mahl vor. Tobias aber sagte zu Raphael: »Bruder Asarja, rede doch von dem, was du unterwegs mit mir besprochen hast, damit die Sache abgemacht werde«.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 10, 'Als jener nun dem Raguel Mitteilung von der Sache gemacht hatte, sagte Raguel zu Tobias: »Iß und trink jetzt und sei guter Dinge; dir kommt es zu, meine Tochter zu erhalten; aber ich muß dir doch die Wahrheit sagen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 11, 'Ich habe mein Kind bereits sieben Männern gegeben, und allemal, wenn sie zu ihr eingingen, sind sie in derselben Nacht gestorben. Doch für jetzt laß dir’s wohl sein!« Tobias aber antwortete: »Ich genieße hier nichts, bis ihr sie zu mir geführt und sie mir feierlich verlobt habt«.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 12, 'Da sagte Raguel: »Nimm sie gleich jetzt hin, wie das (mosaische) Gesetz es bestimmt; du bist ja ihr Bruder, und sie gehört dir; der barmherzige Gott aber schenke euch seinen reichsten Segen!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 13, 'Hierauf rief er seine Tochter Sara, faßte sie bei der Hand, gab sie dem Tobias als Gattin und sagte: »Hier ist sie, nimm sie nach dem mosaischen Gesetz und führe sie zu deinem Vater!« Nachdem er sie hierauf gesegnet hatte,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 14, 'rief er seine Frau Edna, nahm dann ein Blatt Papier, schrieb den Ehevertrag darauf und versah ihn mit seinem Siegel.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 15, 'Darauf setzten sie sich zum Mahl nieder.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 16, 'Raguel aber rief seine Frau Edna und sagte zu ihr: »Liebe Schwester, setze das andere Zimmer in Bereitschaft und führe deine Tochter hinein«.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 17, 'Sie kam der Weisung nach und führte Sara hinein, welche weinte. Sie wischte ihrer Tochter die Tränen ab und sagte:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 18, '»Mut, mein Kind! Der Herr des Himmels und der Erde wolle dir Freude statt dieser deiner Trauer geben, fasse Mut, meine Tochter!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 19, '');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 20, '');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 1, 'Als sie nun fertig gespeist hatten, führten sie Tobias zu ihr hinein.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 2, 'Dieser war aber beim Eintreten der Mitteilungen Raphaels eingedenk, nahm Glutasche vom Räucherwerk, legte das Herz und die Leber des Fisches darauf und räucherte damit.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 3, 'Sobald der Dämon den Dunst roch, floh er in die fernsten Gegenden Oberägyptens, wo der Engel ihn in Fesseln legte.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 4, 'Als nun die beiden in dem Zimmer eingeschlossen waren, stand Tobias von seinem Lager auf und sagte: »Steh auf, liebe Schwester! wir wollen beten, daß der Herr uns gnädig sei«.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 5, 'Dann sprach Tobias folgendermaßen: »Gepriesen seist du, Gott unserer Väter, und gepriesen sei dein heiliger und ruhmvoller Name in alle Ewigkeit! Preisen müssen dich die Himmel und alle deine Geschöpfe!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 6, 'Du hast Adam geschaffen und ihm als Gehilfin und Stütze sein Weib Eva gegeben, von denen das Menschengeschlecht ausgegangen ist. Du hast gesagt: ›Es ist nicht gut, daß der Mensch allein sei; wir wollen ihm eine Gehilfin schaffen, die zu ihm paßt‹.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 7, 'Und nun, Herr, nehme ich diese meine Schwester hier nicht um der Fleischeslust willen, sondern aus wahrer Zuneigung. Laß mich Gnade finden und mit ihr alt werden!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 8, 'Darauf sprachen sie beide zusammen »Amen!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 9, 'und schliefen die Nacht über beieinander. Raguel aber war aufgestanden und hingegangen und hatte ein Grab gegraben,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 10, 'indem er dachte: »Wenn nur dieser nicht auch ums Leben kommt!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 11, 'Als er dann in sein Haus zurückgekehrt war,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 12, 'sagte er zu seiner Frau Edna: »Schicke doch eine von den Mägden hin, um zuzusehen, ob er noch lebt; wenn nicht, so wollen wir ihn begraben, ohne daß jemand etwas erfährt«.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 13, 'Als nun die Magd die Tür geöffnet hatte und hineingegangen war, fand sie beide schlafend;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 14, 'bei ihrer Rückkehr meldete sie ihnen also, daß er noch lebe.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 15, 'Da pries Raguel Gott mit den Worten: »Gepriesen seist du, Gott, mit jeglichem reinen und heiligen Lobpreis! Preisen müssen dich alle deine Heiligen und alle deine Geschöpfe, alle deine Engel und deine Auserwählten in alle Ewigkeit!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 16, 'Gepriesen seist du, daß du mich erfreut hast und daß mir das Unheil nicht widerfahren ist, das ich befürchtete, sondern daß du nach deiner großen Barmherzigkeit mit uns verfahren bist!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 17, 'Gepriesen seist du, daß du dich dieser beiden einzigen Kinder erbarmt hast! Erweise ihnen Gnade, Herr, und laß sie ihr Leben vollenden in Gesundheit mit Freude und Erbarmen!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 18, 'Dann befahl er seinen Knechten, das Grab wieder zuzuwerfen,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 19, 'und richtete ihnen eine Hochzeitsfeier her vierzehn Tage lang;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 20, 'und ehe die Tage der Hochzeit zu Ende waren, beschwor Raguel den Tobias, er möge nicht abreisen, bevor die vierzehn Hochzeitstage abgelaufen wären;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 21, 'alsdann solle er die Hälfte seines Vermögens in Empfang nehmen und wohlbehalten zu seinem Vater zurückkehren; die andere Hälfte solle er nach dem Tode seiner Schwiegereltern erhalten.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 22, '');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 23, '');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 1, 'Darauf rief Tobias den Raphael und sagte zu ihm:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 2, '»Bruder Asarja, nimm einen Knecht und zwei Kamele mit dir und ziehe nach Rages in Medien zu Gabael; hole mir das Geld und bringe ihn mir selbst zur Teilnahme an der Hochzeit her;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 3, 'denn Raguel hat mich beschworen, von hier nicht wegzugehen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 4, 'Mein Vater aber zählt die Tage, und wenn ich zu lange auf mich warten lasse, wird er sich sehr grämen«.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 5, 'Da reiste Raphael hin, kehrte bei Gabael ein und überreichte ihm den Schuldschein; der aber brachte die versiegelten Säckchen und übergab sie ihm.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 6, 'Dann machten sie sich zusammen am andern Morgen früh auf den Weg und kamen zur Hochzeit; und Gabael segnete den Tobias und seine Frau.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 7, '');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 8, '');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 9, '');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 10, '');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 11, '');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 12, '');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 1, 'Unterdessen rechnete sein Vater Tobit täglich die Zeit nach, und als die für die Reise bestimmten Tage vorüber waren und er nicht zurückkam,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 2, 'sagte er: »Sollte er etwa zurückgewiesen worden sein? oder sollte Gabael gestorben sein und niemand ihm das Geld geben wollen?«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 3, 'So war er tief bekümmert.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 4, 'Seine Frau aber sagte zu ihm: »Unser Sohn ist tot; deswegen bleibt er so lange aus«; und sie begann um ihn zu weinen und rief aus:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 5, '»Du machst mir Kummer, mein Kind, daß ich dich, das Licht meiner Augen, habe fortziehen lassen!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 6, 'Tobit aber sagte zu ihr: »Schweig und sorge dich nicht; er ist gesund!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 7, 'Doch sie erwiderte ihm: »Schweig und täusche mich nicht: mein Kind ist tot!« Und sie ging Tag für Tag an den Weg hinaus, auf dem er fortgegangen war; bei Tage nahm sie keine Nahrung zu sich, und nachts hörte sie nicht auf, ihren Sohn Tobias zu beweinen, bis die vierzehn Hochzeitstage vorüber waren, die er, wie Raguel ihn beschworen hatte, dort zubringen musste.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 8, 'Schließlich aber sagte Tobias zu Raguel: »Laß mich ziehen, denn mein Vater und meine Mutter haben gewiß schon keine Hoffnung mehr, mich wiederzusehen«.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 9, 'Da antwortete ihm sein Schwiegervater: »Bleibe bei mir, ich will zu deinem Vater schicken und ihm Nachricht über dein Ergehen geben lassen«.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 10, 'Doch Tobias entgegnete: »Nein, laß mich zu meinem Vater zurückkehren!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 11, 'Da stand Raguel auf, übergab ihm seine Frau Sara und die Hälfte seines Vermögens an Sklaven, Vieh und Geld,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 12, 'gab ihnen seinen Segen und entließ sie mit den Worten: »Der Gott des Himmels lasse es euch gut ergehen, bevor ich sterbe!« Weiter sagte er zu seiner Tochter: »Ehre deine Schwiegereltern, sie sind jetzt deine Eltern; möchte ich immer gute Kunde von dir vernehmen!« hierauf küßte er sie. Edna aber sagte zu Tobias: »Lieber Bruder! der Gott des Himmels wolle dich glücklich heimführen und mir vergönnen, noch Kinder von dir und meiner Tochter Sara zu sehen, damit ich mich freuen kann vor dem Herrn. Siehe, ich vertraue dir meine Tochter als ein Unterpfand an; betrübe sie nicht!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 13, 'Darauf zog Tobias weg, indem er Gott für den glücklichen Verlauf seiner Reise pries; unter Segenswünschen verabschiedete er sich dann von Raguel und dessen Frau Edna.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 1, 'Unterwegs, als sie schon in die Nähe von Ninive gekommen waren, sagte Raphael zu Tobias: »Du weißt doch, mein Bruder, in welchem Zustand du deinen Vater verlassen hast.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 2, 'Wir wollen vorauseilen und deine Frau zurücklassen und das Haus instand setzen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 3, 'Nimm aber die Galle des Fisches zur Hand«. So machten sie sich denn auf den Weg, und der Hund lief hinter ihnen her.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 4, 'Anna aber saß an der Straße und schaute nach ihrem Sohne aus.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 5, 'Als sie ihn nun kommen sah, rief sie seinem Vater zu: »Siehe, da kommt mein Sohn mit dem Manne, der ihn begleitet hat!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 6, 'Raphael hatte aber zu Tobias gesagt: »Ich weiß, daß dein Vater das Augenlicht wiedererhalten wird.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 7, 'Streiche du ihm also die Galle in die Augen, das wird ihn beißen und er wird sich die Augen reiben; dann werden die weißen Flecken abfallen, und er wird dich sehen«.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 8, 'Anna lief also auf ihren Sohn zu, fiel ihm um den Hals und sagte: »Ich habe dich wiedergesehen, mein Kind, nun will ich gern sterben!« und beide weinten.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 9, 'Tobit kam an die Tür hinaus, stieß sich aber dabei; doch sein Sohn eilte auf ihn zu,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 10, 'faßte seinen Vater und strich ihm die Galle in die Augen, indem er dabei sagte: »Sei ohne Angst, mein Vater!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 11, 'Als er aber Schmerz empfand, rieb er sich die Augen;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 12, 'da lösten sich die weißen Flecken wie Schuppen von seinen Augenwinkeln ab, und als er seinen Sohn sah, fiel er ihm um den Hals');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 13, 'und weinte und rief aus: »Gepriesen seist du, o Gott, und gepriesen sei dein Name ewiglich, und gepriesen seien alle deine heiligen Engel!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 14, 'Du hast mich gezüchtigt und dich meiner erbarmt. Da sehe ich ja meinen Sohn Tobias!« Hierauf trat sein Sohn voller Freude ins Haus und erzählte seinem Vater die großen Dinge, die er in Medien erlebt hatte.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 15, 'Tobit aber ging seiner Schwiegertochter freudig bis ans Tor von Ninive entgegen, indem er Gott pries; und alle, die ihn gehen sahen, waren verwundert darüber, daß er wieder sehen konnte;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 16, 'Tobit aber sprach offen vor ihnen aus, daß Gott sich seiner erbarmt habe. Und als er mit seiner Schwiegertochter Sara zusammengetroffen war, wünschte er ihr Gottes Segen mit den Worten: »Sei willkommen, meine Tochter! Gepriesen sei Gott, der dich zu uns geführt hat, und auch dein Vater und deine Mutter!« Und Freude herrschte bei allen seinen Volksgenossen in Ninive.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 17, 'Es stellte sich auch Achjachar mit seinem Neffen Nasbas ein,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 18, 'und man feierte die Hochzeit des Tobias sieben Tage lang mit Freuden.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 19, '');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 20, '');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 1, 'Hierauf rief Tobit seinen Sohn Tobias und sagte zu ihm: »Mein Sohn, denke an den Lohn für den Mann, der dich auf der Reise begleitet hat, und du mußt ihm auch etwas zulegen«.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 2, 'Er antwortete: »Mein Vater, ich leide keinen Schaden, wenn ich ihm die Hälfte von dem gebe, was ich mitgebracht habe.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 3, 'Er hat mich ja doch gesund zu dir zurückgebracht, hat meiner Frau Heilung verschafft, hat mir das Geld geholt und auch dich geheilt«.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 4, 'Da sagte der Alte: »Das gebührt ihm«.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 5, 'Er rief dann den Engel herbei und sagte zu ihm: »Nimm die Hälfte von allem, was ihr mitgebracht habt, und ziehe hin mit Frieden!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 6, 'Da rief jener die beiden beiseite und sagte zu ihnen: »Preist Gott und dankt ihm, gebt ihm die Ehre und dankt ihm vor allen Lebenden für das, was er an euch getan hat. Recht ist es, Gott zu preisen und seinen Namen zu verherrlichen, indem ihr die Werke Gottes mit Rühmen verkündet; ja, zögert nicht, ihm zu danken!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 7, 'Es gebührt sich, das Geheimnis eines Königs verborgen zu halten, aber die Werke Gottes mit Rühmen zu verkündigen. Tut Gutes, so wird euch nichts Böses widerfahren.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 8, 'Löblich ist Gebet in Verbindung mit Fasten und Almosengeben und Gerechtigkeit; besser ist ein kleiner Besitz mit Gerechtigkeit als ein großer mit Ungerechtigkeit; besser Almosen spenden als Gold aufhäufen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 9, 'Denn Wohltätigkeit errettet vom Tode, und diese ist es, die jede Sünde sühnt; wer da Barmherzigkeit und Gerechtigkeit übt, wird langes Leben erlangen;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 10, 'die Sünder aber sind Feinde ihres eigenen Lebens.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 11, 'Ich will nichts vor euch geheim halten. Ich habe soeben gesagt, es sei löblich, das Geheimnis eines Königs verborgen zu halten, aber die Werke Gottes mit Rühmen zu verkünden.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 12, 'Und nun als ihr euer Gebet darbrachtet, du und deine Schwiegertochter Sara, da war ich es, der euer Gebetsopfer vor den Heiligen brachte; und als du die Toten begrubest, da bin ich ebenso bei dir gewesen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 13, 'Und als du nicht zögertest aufzustehen und deine Mahlzeit zu verlassen, um hinzugehen und den Toten zu bestatten, da ist deine Liebestat mir nicht verborgen geblieben, sondern ich war bei dir.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 14, 'Und jetzt hat Gott mich abgesandt, dich und deine Schwiegertochter Sara zu heilen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 15, 'Ich bin Raphael, einer von den sieben heiligen Engeln, welche die Gebete der Heiligen hinaufbringen und Zutritt zu der Herrlichkeit des Heiligen haben«.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 16, 'Da erschraken die beiden und warfen sich auf ihr Angesicht nieder, denn sie fürchteten sich.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 17, 'Doch er sagte zu ihnen: »Fürchtet euch nicht, Friede sei mit euch! Preist aber Gott ewiglich!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 18, 'Denn ich bin nicht aus eigener Liebesbezeigung gekommen, sondern auf das Geheiß unsers Gottes; daher preist ihn ewiglich.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 19, 'Während der ganzen Zeit, da ich euch sichtbar gewesen bin, habe ich weder gegessen noch getrunken, sondern eine Erscheinung habt ihr gesehen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 20, 'Und jetzt preist Gott, denn ich gehe wieder zu dem hinauf, der mich abgesandt hat, und schreibt alles, was geschehen ist, in ein Buch«.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 21, 'Als sie nun aufstanden, sahen sie ihn nicht mehr;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 22, 'sie priesen aber die großen und wunderbaren Taten Gottes und verkündeten, daß ihnen der Engel des Herrn erschienen sei.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 13, 1, 'Darauf schrieb Tobit ein Freudengebet nieder, das folgendermaßen lautete: »Gepriesen sei Gott, der da ewiglich lebt, und sein Königtum!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 13, 2, 'Denn er züchtigt und erbarmt sich; er führt in die Unterwelt hinab und führt wieder herauf, und niemand kann seiner Hand entrinnen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 13, 3, 'Preist ihn, ihr Kinder Israel, vor den Heiden, denn er ist’s, der uns unter sie zerstreut hat.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 13, 4, 'Dort verkündet seine Herrlichkeit, erhebt ihn vor allen Lebenden! denn er ist unser Herr und Gott, er unser Vater in alle Ewigkeit.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 13, 5, 'Er wird uns züchtigen um unserer Vergehen willen, aber sich auch wieder erbarmen und uns sammeln aus allen Völkern, wohin immer ihr unter sie zerstreut worden seid.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 13, 6, 'Wenn ihr euch mit ganzem Herzen und mit ganzer Seele zu ihm hinwendet, um Treue vor ihm zu üben, so wird er sich wieder zu euch wenden und sein Angesicht nicht mehr vor euch verbergen. Wenn ihr dann schauen werdet, was er mit euch tut, so werdet ihr ihn mit vollem Munde preisen und den Herrn der Gerechtigkeit rühmen und den ewigen König erheben. Ich preise ihn hier im Lande meiner Gefangenschaft und verkünde seine Macht und Herrlichkeit einem Volke von Sündern. Bekehrt euch, ihr Sünder, und übt Gerechtigkeit vor ihm! Wer weiß, ob er euch nicht annimmt und euch Barmherzigkeit angedeihen läßt?');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 13, 7, 'Ich erhebe meinen Gott, und meine Seele gehört dem Könige des Himmels und soll ob seiner Herrlichkeit frohlocken.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 13, 8, 'Alle sollen sprechen und ihm danksagen in Jerusalem:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 13, 9, '›Jerusalem, du Stadt des Heiligen! er wird dich züchtigen wegen der Taten deiner Söhne, aber sich auch der Söhne der Gerechten erbarmen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 13, 10, 'Preise den Herrn, wie es recht ist und rühme den ewigen König, damit sein Zelt wieder in dir aufgerichtet werde mit Freuden und er in dir die Gefangenen beglücke und den Elenden in dir seine Liebe erweise von Geschlecht zu Geschlecht in alle Ewigkeit!‹');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 13, 11, 'Viele Völker werden aus der Ferne kommen, um den Namen Gottes des Herrn anzubeten, mit Geschenken in den Händen, mit Geschenken für den König des Himmels; die künftigen Geschlechter alle werden dir zujauchzen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 13, 12, 'Verflucht seien alle, die dich hassen! gesegnet werden alle sein, die dich lieben, in Ewigkeit.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 13, 13, 'Freue dich und frohlocke über die Söhne der Gerechten, denn sie werden versammelt werden und den Herrn der Gerechten preisen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 13, 14, 'O selig die, welche dich lieben! Sie werden sich deines Friedens freuen. Selig die, welche getrauert haben ob all deiner Züchtigungen! Denn sie werden sich deiner freuen, wenn sie alle deine Herrlichkeit schauen, und ihre Freude wird ewig währen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 13, 15, 'Meine Seele preise Gott, den großen König!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 13, 16, 'denn Jerusalem wird aufgebaut werden mit Saphiren und Smaragden, deine Mauern mit köstlichem Gestein, deine Türme und Befestigungswerke mit lauterem Golde;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 13, 17, 'und die Straßen Jerusalems werden gepflastert sein mit Beryll, Karfunkel und Steinen aus Ophir;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 13, 18, 'und alle ihre Gassen werden Halleluja rufen und Lobpreis darbringen mit den Worten: »Gepriesen sei Gott, der dich erhöht hat, für alle Ewigkeit!« Und Tobit endigte seinen Lobpreis.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 13, 19, '');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 13, 20, '');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 13, 21, '');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 13, 22, '');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 14, 1, 'Tobit war 58 Jahre alt, als er das Augenlicht verlor, und acht Jahre später wurde er wieder sehend.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 14, 2, 'Er spendete weiterhin Almosen und fuhr fort, Gott zu fürchten und ihn zu preisen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 14, 3, 'Als er nun ein hohes Alter erreicht hatte, rief er seinen Sohn und dessen Söhne und sagte zu ihm: »Mein Sohn, siehe, ich bin alt geworden und stehe im Begriff, aus dem Leben zu scheiden. So nimm denn deine Kinder');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 14, 4, 'und ziehe nach Medien, denn ich glaube an alles, was der Prophet Jona über Ninive gesagt hat, daß es nämlich zerstört werden wird, während in Medien bis zu einer gewissen Zeit mehr Friede herrschen wird, und daß unsere Brüder, die noch im Lande (Kanaan) sind, zerstreut werden weit hinweg von ihrer schönen Heimat; Jerusalem wird wüste liegen und das Haus Gottes in ihm verbrannt werden, und die Stadt wird eine Zeit lang verwüstet sein.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 14, 5, 'Aber Gott wird sich ihrer wieder erbarmen und sie in ihr Vaterland zurückkehren lassen. Sie werden dann den Tempel wieder aufbauen, aber nicht wie der frühere war, bis die Weltzeiten erfüllt sind. Darnach werden sie aus der Gefangenschaft heimkehren und Jerusalem prächtig aufbauen; auch das Haus Gottes wird darin als ein herrliches Bauwerk für alle Ewigkeit wiederhergestellt werden, wie die Propheten es angekündigt haben.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 14, 6, 'Und alle Völker werden sich dazu bekehren, Gott den Herrn aufrichtig zu fürchten, und werden ihre Götzenbilder vergraben.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 14, 7, 'Und alle Völker werden den Herrn preisen, und sein Volk wird Gott danken; und der Herr wird sein Volk zu Ehren bringen, und freuen werden sich alle, die Gott den Herrn aufrichtig und nach Gebühr lieben, indem sie unsern Brüdern Barmherzigkeit erweisen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 14, 8, 'Und nun, mein Sohn, ziehe von Ninive fort; denn sicherlich wird alles das eintreffen, was der Prophet Jona angekündigt hat«.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 14, 9, '»Du aber halte das Gesetz und die Gebote, beweise dich liebestätig und gerecht, auf daß es dir wohlgehe.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 14, 10, 'Begrabe mich anständig und deine Mutter neben mir, und bleibt dann nicht länger in Ninive. Mein Sohn, bedenke, wie Haman an seinem Erzieher Achjachar gehandelt hat, wie er ihn aus dem Licht in die Finsternis geführt und wie er ihm vergolten hat. Aber Achjachar ist gerettet worden, während jener seinen Lohn erhielt und selbst in die Finsternis hinabfuhr. Manasse übte Wohltätigkeit und wurde aus der Schlinge des Todes gerettet, die jener ihm gelegt hatte. Haman aber fiel in die Schlinge und kam um.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 14, 11, 'Und nun, meine Kinder, bedenkt wohl, was die Mildtätigkeit vermag und wie die Gerechtigkeit errettet«. Während er so noch redete, verschied er auf seinem Lager. Er war 158 Jahre alt, und man begrub ihn in allen Ehren.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 14, 12, 'Als dann auch Anna starb, begrub er sie neben seinem Vater. Tobias aber zog mit seiner Frau und seinen Kindern nach Ekbatana zu seinem Schwiegervater Raguel');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 14, 13, 'und wurde alt in Ehren. Er bestattete seine Schwiegereltern ehrenvoll und erbte deren Vermögen, sowie das seines Vaters Tobit.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 14, 14, 'Er starb im Alter von 127 Jahren zu Ekbatana in Medien.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 14, 15, 'Vor seinem Tode erhielt er noch die Kunde von der Zerstörung Ninives, welches Nabuchodonosor und Asverus erobert hatten. So konnte er sich noch vor seinem Tode über Ninive freuen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 14, 16, '');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 14, 17, '');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 1, 'Alle Weisheit kommt vom Herrn und ist bei ihm in Ewigkeit.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 2, 'Den Sand am Meer und die Tropfen des Regens und die Tage der Ewigkeit: – wer kann sie zählen?');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 3, 'Die Höhe des Himmels und die Breite der Erde und das Weltmeer und die Weisheit: – wer kann sie ergründen?');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 4, 'Früher als dieses alles ist die Weisheit geschaffen, und verständige Einsicht ist von Ewigkeit her. b [Die Quelle der Weisheit ist Gottes Wort in Himmelshöhen, und ihre Wege sind die ewigen Gebote.]');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 5, 'Die Wurzel der Weisheit, – wem war sie offenbart? und ihre geheimen Pläne, – wer hat sie erkannt? b [Die Erkenntnis der Weisheit, – wem wird sie kundgetan? und ihre reiche Erfahrung, – wer hat sie verstanden?]');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 6, 'Einer ist weise, furchtbar gar sehr, er, der auf seinem Throne sitzt, der Herr.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 7, 'Er ist’s, der sie geschaffen und geschaut und gezählt und sie ausgegossen hat über alle seine Werke');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 8, 'mit Einschluß alles Fleisches, soviel er ihm eben verlieh; doch reichlich hat er sie denen gewährt, die ihn lieben. b [Die Liebe zum Herrn ist herrliche Weisheit; denen er aber erscheint, denen teilt er sie zu, damit sie ihn schauen.]');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 9, 'Die Furcht des Herrn verleiht Ehre und Ruhm und Frohsinn und eine Freudenkrone.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 10, 'Die Furcht des Herrn erfreut das Herz und gibt Frohsinn, Fröhlichkeit und langes Leben. b [Die Furcht des Herrn ist ein Geschenk vom Herrn, denn sie stellt hin auf die Pfade der Liebe.]');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 11, 'Wer den Herrn fürchtet, dem wird es am Ende wohl ergehn, und am Tage seines Todes wird er gepriesen werden. b [Die Liebe zum Herrn ist herrliche Weisheit; denen er aber erscheint, denen teilt er sie zu, damit sie ihn schauen.]');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 12, 'Der Anfang der Weisheit ist die Furcht des Herrn; den Frommen ist sie im Mutterleibe anerschaffen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 13, 'Bei den Menschen hat sie sich einen ewigen Wohnsitz gegründet und bei deren Nachkommen wird sie beständig bleiben. b [Die Furcht des Herrn ist ein gottseliges Wissen; die Gottseligkeit behütet und macht rechtschaffen das Herz, Freude und Wonne verleiht sie. Dem Gottesfürchtigen wird es wohlergehen, und zur Zeit seines Endes wird er gesegnet sein.]');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 14, 'Das Vollmaß der Weisheit ist die Furcht des Herrn; sie macht die Menschen trunken von ihren Früchten.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 15, 'Ihr ganzes Haus füllt sie mit kostbaren Schätzen an und die Vorratskammern mit ihren Erzeugnissen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 16, 'Die Krone der Weisheit ist die Furcht des Herrn, die da erblühen macht Wohlfahrt und erquickende Gesundheit (und das Rühmen denen weit macht, die ihn lieben).');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 17, 'Und er sah sie und zählte sie aus; Erkenntnis und kluge Einsicht strömt sie aus und erhöht den Ruhm derer, die sie festhalten.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 18, 'Die Wurzel der Weisheit ist die Furcht des Herrn, und ihre Zweige sind langes Leben. b [Die Furcht des Herrn hält die Sünde fern; wer aber in ihr bleibt, wird allen Zorn von sich abwenden.]');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 19, 'Ungerechter Zorn kann nicht entschuldigt werden; denn der Ausbruch seines Zorns bringt ihn zum Fall.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 20, 'Bis zur rechten Zeit hält der Langmütige an sich, und nachher erwächst ihm daraus Freude.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 21, 'Bis zur rechten Zeit verbirgt er seine Worte, und die Lippen vieler werden seine Klugheit preisen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 22, 'In den Schatzkammern der Weisheit sind einsichtsvolle Sprüche vorhanden, aber dem Sünder ist die Gottesfurcht ein Greuel.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 23, 'Wünschest du dir Weisheit, so halte die Gebote, dann wird der Herr sie dir reichlich bescheren;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 24, 'denn Weisheit und Bildung besteht in der Furcht des Herrn; was ihm aber gefällt, ist die Treue und Sanftmut.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 25, 'Sei nicht ungehorsam gegen die Furcht des Herrn und nahe ihr nicht mit geteiltem Herzen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 26, 'Tue nicht groß mit ihr vor den Leuten und nimm dich in acht mit deinen Lippen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 27, 'Überhebe dich nicht, damit du nicht fallest und dir selbst Schande zuziehest und der Herr dein verborgenes Innere ans Licht bringe und dich inmitten der versammelten Gemeinde zu Boden werfe, weil du in Wirklichkeit dich nicht der Gottesfurcht genaht hattest und dein Herz voll Falschheit war.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 28, '');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 29, '');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 30, '');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 31, '');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 32, '');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 33, '');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 34, '');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 35, '');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 36, '');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 37, '');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 38, '');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 2, 1, 'Mein Sohn, wenn du dich entschließt, dem Herrn zu dienen, so mache dich auf Anfechtungen gefaßt.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 2, 2, 'Mache fest dein Herz und werde stark, damit du zur Zeit der Not nicht schnell versagest.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 2, 3, 'Hange ihm an und falle nicht ab von ihm, damit du am Ende groß dastehest.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 2, 4, 'Nimm alles an, was dir widerfahren mag, und sei geduldig in den Wechselfällen deiner Trübsal;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 2, 5, 'denn im Feuer wird das Gold erprobt und die gottgefälligen Menschen im Ofen des Leidens.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 2, 6, 'Vertraue auf den Herrn, so wird er sich deiner annehmen; hoffe auf ihn, so wird er deinen Weg ebnen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 2, 7, 'Die ihr den Herrn fürchtet, harret auf sein Erbarmen und weicht nicht ab zur Seite, damit ihr nicht fallet.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 2, 8, 'Die ihr den Herrn fürchtet, vertraut auf ihn, so wird euer Lohn nicht ausbleiben.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 2, 9, 'Die ihr den Herrn fürchtet, hofft auf Gutes, nämlich auf immer frohen Sinn und auf Erbarmen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 2, 10, 'Blickt hin auf die Geschlechter der Vorzeit und seht: wer hat dem Herrn vertraut und ist zu Schanden geworden? oder wer ist der Furcht vor ihm treu geblieben und doch von ihm verlassen worden? oder wer hat ihn angerufen und ist unbeachtet geblieben?');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 2, 11, 'Denn barmherzig und gnädig ist der Herr, er vergibt Sünden und rettet zur Zeit der Not.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 2, 12, 'Wehe den verzagten Herzen und den lässigen Händen und dem Sünder, der auf zweierlei Wegen geht!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 2, 13, 'Wehe dem erschlafften Herzen! Weil es kein Vertrauen hat, darum wird es auch nicht beschirmt werden.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 2, 14, 'Wehe euch, die ihr die Ausdauer verloren habt! Was wollt ihr machen, wenn der Herr euch heimsucht?');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 2, 15, 'Die den Herrn fürchten, sind seinen Worten nicht ungehorsam und die ihn lieben, halten seine Wege ein.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 2, 16, 'Die den Herrn fürchten, suchen ihm zu gefallen, und die ihn lieben, sind seines Gesetzes voll.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 2, 17, 'Die den Herrn fürchten, machen ihr Herz fest und demütigen vor ihm ihre Seele, (indem sie sagen):');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 2, 18, '»Wir wollen lieber in die Hände des Herrn fallen als in die Gewalt der Menschen; denn so groß seine Herrlichkeit ist, so groß ist auch sein Erbarmen, (und wie sein Name, so sind auch seine Werke)«.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 2, 19, '');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 2, 20, '');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 2, 21, '');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 2, 22, '');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 2, 23, '');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 1, 'Vernehmt von mir das Recht des Vaters, ihr Kinder, und handelt danach, damit es euch wohl ergehe;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 2, 'denn der Herr hat dem Vater Ehre verliehen über die Kinder und das Recht der Mutter festgestellt über die Söhne.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 3, 'Wer den Vater ehrt, sühnt Sünden,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 4, 'und einem, der sich Schätze sammelt, gleicht der, welcher seine Mutter werthält.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 5, 'Wer den Vater ehrt, wird Freude an den eigenen Kindern erleben, und so oft er betet, wird er Erhörung finden.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 6, 'Wer seinen Vater hochschätzt, wird lange leben, und wer dem Herrn gehorsam ist, wird seiner Mutter Liebe erweisen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 7, 'Wer den Herrn fürchtet, ehrt den Vater und dient seinen Eltern wie Herren.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 8, 'Mit Tat und Wort ehre deinen Vater, damit alle Segensverheißungen über dich kommen;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 9, 'denn des Vaters Segen stellt die Häuser der Kinder fest, aber der Mutter Fluch reißt sie nieder bis auf den Grund (h).');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 10, 'Suche nicht deine Ehre in der Verunehrung deines Vaters, denn in der Schande deines Vaters liegt keine Ehre, für dich;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 11, 'denn die Ehre eines Mannes hängt ab von der Ehre seines Vaters, und der üble Ruf einer Mutter ist eine Schande für die Kinder.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 12, 'Mein Sohn, sei deines Vaters Stütze, wenn er alt wird, und mache ihm keinen Kummer, solange er lebt;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 13, 'auch wenn seine Geisteskraft abnimmt, halte es ihm zugute, und mißachte ihn nicht im Vollbesitz deiner Kraft.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 14, 'Denn liebevolles Verhalten gegen den Vater wird dir nicht vergessen werden und dir für deine Sünden zugute kommen;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 15, 'am Tage der Not wird es dir gedacht werden, und wie Sonnenschein das Eis (wegschmilzt), so werden deine Sünden vergehen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 16, 'Einem Gotteslästerer gleicht, wer seinen Vater verläßt, und vom Herrn verflucht ist, wer seine Mutter in Zorn versetzt.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 17, 'Mein Sohn, in Demut vollbringe deine Geschäfte, so wirst du von gottwohlgefälligen Menschen geliebt werden (h).');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 18, 'Je größer du bist, desto mehr demütige dich, so wirst du vor dem Herrn Gnade finden; b [Manche sind in hoher Stellung und geehrt, aber den Demütigen werden die Geheimnisse Gottes geoffenbart.]');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 19, 'Denn groß ist die Macht des Herrn, und von den Demütigen wird er gepriesen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 20, 'Was dir zu schwer ist, untersuche nicht, und was über deine Kräfte geht, trachte nicht zu erforschen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 21, 'Was dir aufgetragen ist, darüber sinne nach, denn das Verborgene geht dich nichts an; (nicht hast du nötig, das Verborgene mit deinen Augen zu schauen).');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 22, 'Was über die dir obliegenden Geschäfte hinausgeht, damit befasse dich nicht vorwitzig; denn mehr, als die Menschen begreifen können, ist dir kundgetan worden;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 23, 'denn viele hat ihre zu hohe Meinung von sich irregeführt, und böser Dünkel hat ihre Gedanken getäuscht. b [Hast du keine Augen, so entbehrst du des Lichtes; mangelt dir aber die Einsicht, so rühme dich ihrer nicht.]');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 24, 'Einem trotzigen Herzen ergeht es zuletzt übel, und wer die Gefahren liebt, kommt darin um.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 25, 'Ein trotziges Herz belastet sich mit Schmerzen, und der Sünder häuft Sünde auf Sünde.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 26, 'Heimsuchung ist für den Hochmütigen kein Heilmittel; denn das Gewächs der Bosheit hat Wurzel in ihm geschlagen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 27, 'Das Herz des Einsichtigen durchdenkt die Sinnsprüche, und nach einem aufmerksamen Zuhörer steht das Verlangen des Weisen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 28, 'Wasser löscht ein loderndes Feuer aus, und Mitleid (oder Mildtätigkeit) tilgt Sünden.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 29, 'Wer Liebeserweise vergilt, ist auf die Zukunft bedacht und wir zu der Zeit, wo er zu Falle kommt, eine Stütze finden.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 30, '');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 31, '');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 32, '');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 33, '');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 34, '');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 1, 'Mein Sohn, entziehe dem Armen nicht den Lebensunterhalt und laß die Augen der Dürftigen nicht lange schmachten.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 2, 'Eine hungrige Seele fahre nicht an und kränke keinen Menschen in seiner Not.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 3, 'Ein verbittertes Herz reize nicht noch mehr und laß den Hilfsbedürftigen nicht auf deine Gabe warten.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 4, 'Einen Bittenden weise nicht ab in seiner Notlage und wende dein Antlitz nicht weg vom Armen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 5, 'Vom Bittenden wende dein Auge nicht ab und gib niemandem Anlaß, dir zu fluchen;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 6, 'denn wenn er dir flucht in seines Herzens Verbitterung, so wird sein Schöpfer sein Flehen erhören.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 7, 'Mache dich beliebt bei der Gemeinde und vor dem Hochstehenden beuge dein Haupt.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 8, 'Neige dem Armen dein Ohr zu und erwidere seinen Gruß freundlich.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 9, 'Rette den Bedrängten aus der Hand seiner Bedränger und sei nicht kleinmütig, wenn du ein Urteil abgeben mußt.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 10, 'Sei den Waisen wie ein Vater und ihrer Mutter anstatt des Gatten, so wirst du sein wie ein Sohn des Höchsten, und er wird dir mehr Liebe erweisen als deine eigene Mutter.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 11, 'Die Weisheit erhöht ihre Kinder und nimmt sich derer an, die sie suchen (h).');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 12, 'Wer sie liebt, liebt das Leben, und die ihr eifrig nachtrachten, haben Freude in Fülle.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 13, 'Wer sich in ihren Besitz setzt, gewinnt Ruhm, und wohin er geht, da segnet ihn der Herr (h).');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 14, 'Die ihr dienen, leisten dem Heiligen Dienst, und die sie lieben, die liebt auch der Herr.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 15, 'Wer auf sie hört, wird recht richten, und wer sich zu ihr hält, wird sicher wohnen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 16, 'Wer Vertrauen zu ihr hat, wird sie erwerben, und in ihrem Besitz werden auch seine Nachkommen bleiben;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 17, 'denn zuerst geht sie in Verstellung mit ihm um und erprobt ihn durch Versuchungen; Furcht und Zagen bringt sie über ihn und quält ihn mit ihrer Zucht, bis sie Vertrauen zu ihm gefaßt und ihn erprobt hat in der Beobachtung ihrer Vorschriften.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 18, 'Dann aber kommt sie umgekehrt auf geradem Wege zu ihm und erfreut ihn und offenbart ihm ihre Geheimnisse.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 19, 'Wenn er aber von ihr abfällt, so verläßt sie ihn und gibt ihn seinem Verderben preis.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 20, 'Mein Sohn, richte dich nach der Zeit und hüte dich vor dem Bösen und schäme dich deiner Überzeugung nicht;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 21, 'denn es gibt eine Scham, die zur Sünde führt, und es gibt eine Scham, die Ehre und Anerkennung verschafft.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 22, 'Nimm für niemand Partei gegen dein Gewissen und hege keine (falsche) Scheu zu deinem Verderben.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 23, 'Halte mit der Rede nicht zurück, wenn noch Zeit zur Rettung ist, und verbirg deine Weisheit nicht, (um Ruhm zu gewinnen);');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 24, 'denn durch die Rede wird die Weisheit erkannt und die Einsicht durch die Worte der Zunge.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 25, 'Widersprich nie der Wahrheit, schäme dich aber deiner mangelhaften Bildung.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 26, 'Schäme dich nicht, deine Sünden zu bekennen, und suche nicht die Strömung des Flusses zu bezwingen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 27, 'Stelle dich nicht einem törichten Menschen zur Verfügung und nimm keine Rücksicht auf den Mächtigen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 28, 'Bis zum Tode kämpfe für die Wahrheit, so wird auch Gott der Herr für dich streiten.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 29, 'Sei nicht großsprecherisch mit deiner Zunge und lässig und träge in deinem Tun.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 30, 'Sei nicht wie ein Löwe in deinem Hause und nicht argwöhnisch unter deinen Hausgenossen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 31, 'Laß deine Hand nicht ausgestreckt sein zum Nehmen und festgeschlossen beim Wiedererstatten.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 32, '');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 33, '');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 34, '');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 35, '');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 36, '');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 1, 'Verlaß dich nicht auf deinen Reichtum und sage nicht: »Ich habe genug.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 2, 'Folge nicht deinen Gelüsten und deiner Kraft, daß du nach den Begierden deines Herzens wandelst,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 3, 'und sage nicht: »Wer hat mir zu befehlen?«; denn der Herr, der Recht übt, wird dich büßen lassen (h).');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 4, 'Sage nicht: »Ich habe gesündigt, und was hat’s mir geschadet?« denn der Herr ist langmütig.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 5, 'In bezug auf Sühne sei nicht ohne Bangen, so daß du Sünde auf Sünden häufst.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 6, 'Und sage nicht: »Sein Erbarmen ist groß, er wird mir schon meine vielen Sünden vergeben«; denn bei ihm ist wohl Erbarmen, aber auch Zorn, und auf den Sündern lastet sein Grimm.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 7, 'Säume nicht, dich zum Herrn zu bekehren, und verschieb es nicht von einem Tag zum andern; den plötzlich kommt der Zorn des Herrn zum Ausbruch, und am Tage der Vergeltung würdest du umkommen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 8, 'Verlaß dich nicht auf unrechtes Gut, denn am Tage der Heimsuchung wird es dir nichts nützen. –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 9, 'Worfle nicht bei jedem Winde, und gehe nicht auf jeglichem Pfade! (So macht es der doppelzüngige Sünder.)');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 10, 'Bleibe fest bei deiner Überzeugung und laß deine Rede immer eine und dieselbe sein.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 11, 'Sei schnell bereit zum Hören, aber langsam laß die Antwort hören.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 12, 'Hast du Einsicht, so antworte dem andern; wo nicht, so laß deine Hand auf deinem Munde liegen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 13, 'Ehre und Schande liegen in der Rede und des Menschen Zunge kann ihn zu Fall bringen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 14, 'Laß dich nicht doppelzüngig nennen und gebrauche deine Zunge nicht zur Hinterlist; denn dem Diebe wird Schande zuteil und böser Schimpf dem Doppelzüngigen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 15, 'Verfehle dich nicht, weder im Großen noch im Kleinen, und statt eines Freundes beweise dich nicht als Feind;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 16, 'denn einen üblen Namen, Schimpf und Schande würdest du davontragen; so gebührt es dem doppelzüngigen Sünder.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 17, '');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 18, '');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 1, 'Gib dich nicht völlig dem Willen deiner Leidenschaft hin, damit sie nicht wie ein Stier deine Kraft abweide.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 2, 'Deine Blätter wird sie abfressen und deine Früchte verzehren und dich stehen lassen wie einen dürren Baum (g).');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 3, 'Böse Leidenschaft richtet ihren Besitzer zugrunde und macht ihn zur Schadenfreude (oder zum Gespött) seiner Feinde.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 4, 'Eine freundlich redende Kehle gewinnt viele Freunde, und eine wohlredende Zunge bekommt viele Heilsgrüße (oder Friedenswünsche).');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 5, 'Groß sei die Zahl derer, die in Frieden mit dir leben, aber dein Vertrauter sei nur einer von tausend.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 6, 'Erwirbst du dir einen Freund, so erwirb ihn unter Erprobung und schenke ihm nicht zu schnell dein Vertrauen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 7, 'Denn mancher ist ein Freund, solange es ihm zusagt, und bleibt es nicht zur Zeit deines Unglücks;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 8, 'und mancher Freund verwandelt sich in einen Feind und bringt den dich entehrenden Streit unter die Leute.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 9, 'Und mancher ist ein Freund als Tischgenosse, ist aber nicht zu finden zur Zeit deines Unglücks;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 10, 'solange es dir gut geht, stellt er sich dir völlig gleich und tritt deinem Gesinde gegenüber als Herr auf (h);');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 11, 'kommst du aber herunter, so tritt er gegen dich und läßt sich vor deinen Augen nicht mehr sehen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 12, 'Von deinen Feinden halte dich fern, und vor deinen Freunden sei auf der Hut.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 13, 'Ein treuer Freund ist ein starker Schutz; wer ihn gefunden, hat einen Schatz gefunden.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 14, 'Ein treuer Freund ist nicht zu bezahlen, und sein Wert läßt sich auf der Wage nicht feststellen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 15, 'Ein treuer Freund ist eine lebenspendende Arznei, und wer den Herrn fürchtet, erlangt ihn.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 16, 'Der Gottesfürchtige lenkt seine Freundschaft richtig, denn so, wie er selbst, ist auch sein Genosse.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 17, 'Mein Sohn, von Jugend auf erwähle dir Zucht, so wirst du bis ins Greisenalter die Weisheit gewinnen;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 18, 'wie der Pflüger und der Sämann tritt an sie heran, so darfst du auf ihre herrlichen Früchte hoffen; denn von der Beschäftigung mit ihr wirst du nur kurze Zeit Mühe haben und bald schon ihre Früchte genießen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 19, 'Wie so ganz ungangbar erscheint sie den Ungebildeten, und ein Unverständiger hält es bei ihr nicht aus;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 20, 'wie ein Übungsstein lastet sie schwer auf ihm und es währt nicht lange, so wirft er sie weg;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 21, 'denn die Weisheit ist, wie schon ihr Name besagt, und nicht vielen ist sie offenbar; (denen aber, die sie kennen, verbleibt sie, bis sie Gott schauen).');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 22, 'Höre, mein Sohn, und nimm meine Meinung an und weise meinen Rat nicht ab;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 23, 'und stecke deine Füße in ihre Fesseln hinein und deinen Hals in ihr Halseisen;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 24, 'beuge deinen Rücken unter sie und nimm sie auf dich und sträube dich nicht gegen ihre Bande.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 25, 'Mit ganzem Herzen tritt an sie heran und halte ihre Wege mit all deiner Kraft ein.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 26, 'Spüre ihr nach und suche sie, so wird sie dir bekannt werden, und hast du sie ergriffen, so laß sie nicht wieder los;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 27, 'denn zuletzt wirst du Erquickung (oder Ruhe) bei ihr finden, und sie wird sich dir in Freude verwandeln.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 28, 'Alsdann werden ihre Fesseln zum starken Schutz für dich werden und ihr Halseisen zu einem Prachtgewand (oder Ehrenkleid):');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 29, 'denn ein goldener Schmuck ist an ihr (oder auf ihrem Haupte?), und ihre Bande sind ein Purpurgewebe.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 30, 'Als Prachtgewand wirst du sie dir anlegen und als Freudenkrone sie dir aufs Haupt setzen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 31, 'Wenn du bereit bist, mein Sohn, so wirst du Unterweisung erhalten, und wenn du dein Herz darauf richtest, so wirst du klug werden;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 32, 'wenn du mit Lust und Liebe zuhörst, so wirst du es in dich aufnehmen, und wenn du dein Ohr hinkehrst, wirst du weise werden.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 33, 'Wo viele Greise versammelt sind, da stelle dich ein, und wer weise ist, dem schließe dich an;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 34, 'jeden Vortrag über göttliche Dinge höre gern an, und einsichtsvolle Sprüche laß dir nicht entgehen;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 35, 'siehst du einen verständigen Mann, so suche ihn schon frühmorgens auf, und dein Fuß betrete immer wieder die Schwellen seiner Türen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 36, 'Denke nach über die Verordnungen des Herrn, und über seine Gebote sinne allezeit nach; er ist’s der dein Herz fest machen wird, und dein Verlangen nach Weisheit wird dir gewährt werden (h).');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 37, '');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 1, 'Tue nichts Böses, so widerfährt dir nichts Böses,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 2, 'meide das Unrecht, so wird es fern von dir bleiben.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 3, 'Mein Sohn, säe nicht in die Furchen des Unrechts, so wirst du nicht siebenfältig von ihnen ernten.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 4, 'Erbitte dir von Gott keine Herrscherstellung und ebenso vom Könige keinen Ehrenstuhl.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 5, 'Stelle dich vor Gott nicht als gerecht hin und spiele vor dem König nicht den Weisen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 6, 'Trachte nicht danach, ein Richter zu werden, wenn du nicht imstande bist, dem Unrecht ein Ende zu machen; sonst würdest du dich vor der Person des Machthabers fürchten müssen und Anstoß trotz deiner Rechtschaffenheit erregen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 7, 'Verfehle dich nicht gegen die Stadtgemeinde und bringe dich nicht selbst in Mißachtung beim Volk. –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 8, 'Glaube nicht, zweimal ungestraft eine Sünde begehen zu können; denn schon bei einer einzigen wirst du nicht straflos ausgehen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 9, 'Denke nicht: »Der Herr wird die Menge meiner Opfergaben beachten, und wenn ich Gott, dem Höchsten, etwas darbringe, so wird er’s annehmen«.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 10, 'Sei nicht mutlos bei deinem Gebet und versäume nicht, Mildtätigkeit zu üben.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 11, 'Verlache keinen, dessen Gemüt tief bekümmert ist; denn es gibt einen, der da erniedrigt und erhöht. –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 12, 'Pflüge keine Lüge gegen deinen Bruder und tue das Gleiche auch deinem Freunde nicht an (h).');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 13, 'Wolle nie irgend eine Lüge aussprechen, denn die Gewöhnung daran schlägt nicht zum Guten aus. –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 14, 'Sei kein Schwätzer in der Versammlung der Alten und wiederhole kein Wort in deinem Gebet. –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 15, 'Hasse nicht die mühevolle Handarbeit, noch den Ackerbau, da der Höchste ihn verordnet hat.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 16, 'Rechne dich nicht selbst zu der großen Zahl der Sünder; bedenke wohl, daß der Zorn nicht lange auf sich warten läßt.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 17, 'Demütige tief deine Seele, denn die Strafe für den Gottlosen ist das Feuer und der Wurm.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 18, 'Einen Freund vertausche nicht um wertloses Geld, noch einen leiblichen Bruder um Ophirgold.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 19, 'Wende dich nicht ab von einer klugen und guten Ehefrau, denn ihre Anmut ist wertvoller als Gold.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 20, 'Behandle keinen Knecht übel, der treu arbeitet, und ebensowenig einen Tagelöhner, der dir von Herzen ergeben ist.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 21, 'Einen verständigen Dienstboten liebe aufrichtig und enthalte ihm die Freilassung nicht vor.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 22, 'Hast du Vieh, so sieh selbst nach ihm, und ist es dir nützlich, so behalte es. –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 23, 'Hast du Kinder, so halte sie in Zucht und beuge ihnen den Nacken von Jugend auf.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 24, 'Hast du Töchter, so gibt acht auf ihren Leib und zeige ihnen kein zu freundliches Gesicht.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 25, 'Verheiratest du eine Tochter, so hast du ein großes Werk fertig gebracht, aber gib sie einem verständigen Manne zur Frau.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 26, 'Hast du eine Frau nach deinem Herzen, so verstoße sie nicht (h); ist sie dir aber zuwider, so vertraue dich ihr nicht an.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 27, 'Von ganzem Herzen ehre deinen Vater und vergiß deine Mutter nicht, die dich mit Schmerzen geboren;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 28, 'bedenke wohl, daß du ihnen das Leben verdankst; wie kannst du ihnen vergelten, was sie an dir getan haben?');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 29, 'Mit deinem ganzen Herzen fürchte den Herrn und halte seine Priester in Ehren (oder heilig h).');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 30, 'Mit ganzer Kraft liebe deinen Schöpfer und laß seine Diener nicht im Stich.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 31, 'Fürchte den Herrn und ehre den Priester und gib ihm seinen Anteil, wie dir geboten ist: die Erstlinge und Schuldopfer und die Gabe des Bugs, das hochheilige Speisopfer und den Priesterzehnten (h).');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 32, 'Auch dem Armen strecke deine Hand hin, damit der Segen für dich vollkommen werde.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 33, 'Ein liebevolles Geschenk kommt jedem Lebenden zu, aber auch dem Toten versage deine Liebe nicht.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 34, 'Entziehe dich nicht den Weinenden und trauere mit den Trauernden.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 35, 'Sei nicht lässig, die Kraken zu besuchen, denn durch solches Verhalten wirst du Liebe ernten.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 36, 'Bei allem, was du vorhast, denke an dein Ende, so wirst du niemals böse handeln.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 37, '');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 38, '');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 39, '');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 40, '');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 1, 'Streite nicht mit einem mächtigen Herrn, damit du ihm nicht in die Hände fallest.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 2, 'Zanke nicht mit einem reichen Manne, damit er nicht das Gewicht seines Geldes gegen dich in die Wagschale lege; denn schon viele hat das Geld zur Schlechtigkeit verleitet und sogar die Herzen der Könige vom rechten Wege abgeführt.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 3, 'Streite nicht mit einem zungenfertigen Manne und häufe nicht noch mehr Holzscheite auf sein Feuer.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 4, 'Scherze nicht mit einem Ungebildeten, damit deine Vorfahren nicht beschimpft werden (h).');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 5, 'Mache keinem Menschen Vorwürfe, der sich von der Sünde abwendet; bedenke, daß wir alle in Schuld sind.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 6, 'Achte keinen Menschen gering wegen seines hohen Alters, denn auch von uns selbst werden manche alt.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 7, 'Freue dich nicht über jemandes Tod; bedenke wohl: wir alle müssen sterben.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 8, 'Vernachlässige nicht die Gespräche der Weisen und beschäftige dich mit ihren Sinnsprüchen; denn von ihnen kannst du Bildung lernen, um den Großen dienen zu können.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 9, 'Mißachte nicht die Gespräche der Greise, denn auch sie haben von ihren Vätern gelernt; denn von ihnen kannst du Einsicht lernen, um zur Zeit, wo es not tut, Antwort zu geben.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 10, 'Blase nicht die Kohlen des Sünders in Brand, damit du nicht von seiner Feuerflamme versengt werdest.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 11, 'Gerate nicht außer dir gegenüber einem frechen Menschen, damit er nicht wie ein Lauerposten deinem Munde nachstelle.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 12, 'Borge keinem Manne, der mächtiger ist als du; hast du ihm aber geborgt, so sieh es als verloren an.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 13, 'Leiste nicht Bürgschaft über dein Vermögen hinaus; hast du dich aber verbürgt, so mache dich aufs Bezahlen gefaßt.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 14, 'Rechte nicht mit einem Richter, denn nach seinem Belieben entscheidet er (g).');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 15, 'Mit einem Tollkühnen begib dich nicht auf die Reise, damit er nicht schweres Leid über dich bringe; denn er wird nach seinem Kopfe handeln, und du wirst durch seine Unbesonnenheit mit ins Unglück geraten.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 16, 'Mit einem Jähzornigen laß dich in keinen Streit ein und wandere mit ihm nicht durch die Wüste; denn Blut zu vergießen gilt ihm für nichts, und wo keine Hilfe da ist, streckt er dich zu Boden.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 17, 'Mit einem Toren schmiede keinen Plan, denn er vermag keine Sache geheimzuhalten.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 18, 'Vor den Augen eines Fremden tue nichts, was geheim bleiben soll; denn du weißt nicht, was er schließlich anstellen wird.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 19, 'Nicht jedem Menschen offenbare dein Herz, er möchte dir wohl schlechten Dank dafür abstatten (h).');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 20, '');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 21, '');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 22, '');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 1, 'Sei nicht eifersüchtig auf die Ehefrau an deinem Busen und bringe ihr nicht eine schlimme Lehre bei zu deinem eigenen Schaden.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 2, 'Gib deinen Willen nicht ganz und gar deiner Frau preis, so daß sie zu der dir gebührenden Herrschaft emporsteigt.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 3, 'Nähere dich keinem buhlerischen Weibe, damit du nicht in ihre Schlingen fallest.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 4, 'Bei einer Zitherspielerin verweile nicht lange, damit du nicht von ihren Künsten umstrickt werdest.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 5, 'Eine Jungfrau betrachte nicht genau, damit du nicht durch das zu zahlende Strafgeld in Schande geratest.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 6, 'Gib dein Herz nicht an Buhldirnen hin, damit du nicht um dein Hab und Gut kommest.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 7, 'Gaffe nicht in den Straßen der Stadt umher und schweife nicht durch ihre einsamen Gassen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 8, 'Wende deine Augen ab von einer schönen Frau und laß deine Blicke nicht ruhen auf einer fremden Schönheit; durch Weiberschönheit sind schon viele berückt worden, und an ihr entzündet die Liebe sich wie Feuer. b [Jede Frau, die der Unzucht sich preisgibt, wird wie Unrat auf der Erde zertreten. Viele sind durch eines fremden Weibes Schönheit auf Abwege geraten; denn die Unterhaltung mit ihnen brennt wie Feuer.]');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 9, 'Mit einer verheirateten Frau sitze überhaupt nicht zusammen (h) und schmause nicht mit ihr beim Wein, damit dein Herz sich ihr nicht zuneige und du durch deine Leidenschaft ins Verderben geratest (h).');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 10, 'Einen alten Freund laß nicht fahren, denn der neue kommt ihm nicht gleich; ein neuer Freund ist wie neuer Wein: erst wenn er alt geworden ist, trinkt man ihn mit Vergnügen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 11, 'Beneide keinen Sünder um seine Herrlichkeit, denn du weißt nicht, wie sein Ende sein wird.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 12, 'Habe kein Wohlgefallen an dem Wohlergehen der Gottlosen; bedenke wohl, daß sie nicht bis zum Tode ungestraft bleiben.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 13, 'Halte dich weit entfernt von einem Manne, der die Macht hat zu töten, damit du nicht in Todesfurcht zu schweben brauchst; wenn du aber mit ihm zu tun hast, so laß dir nichts zuschulden kommen, damit er dir nicht das Leben nehme. Bedenke wohl, daß du inmitten von Schlingen einhergehst und auf den Mauerzinnen einer Stadt wandelst.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 14, 'Soviel du vermagst, berate deinen Nächsten und besprich dich mit weisen Leuten.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 15, 'Mit den Einsichtsvollen halte deine Unterredungen ab, und den Gegenstand aller deiner Gespräche bilde das Gesetz des Höchsten.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 16, 'Rechtschaffene Männer seien deine Tischgenossen, und in der Gottesfurcht bestehe dein Ruhm.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 17, 'Durch die Hand kunstfertiger Meister erlangt ein Werk Lob, und der Führer eines Volkes ist der redefertige Weise.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 18, 'Gefürchtet in seiner Stadt ist der Schwätzer (oder Schreier, Zungenheld), und wer sich in seiner Rede überstürzt, erntet Haß.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 19, '');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 20, '');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 21, '');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 22, '');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 23, '');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 24, '');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 25, '');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 1, 'Ein weiser Herrscher (oder Fürst) hält sein Volk in Zucht, und die Regierung eines Einsichtsvollen ist wohlgeordnet.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 2, 'Wie der Herrscher seines Volkes, so sind auch seine Diener; und wie das Oberhaupt der Stadt, so sind auch (alle) ihre Einwohner.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 3, 'Ein zuchtloser König richtet sein Volk zugrunde, aber volkreich wird eine Stadt durch die Einsicht ihrer Obersten.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 4, 'In der Hand Gottes liegt die Herrschaft über die Erde, und zu rechter Zeit läßt er den Tüchtigen auf ihr erstehen;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 5, 'in der Hand Gottes liegt auch das Wohlergehen eines jeden, und der Person eines hohen Beamten verlieht er seine Würde.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 6, 'Aber keinerlei Unrecht grolle deinem Nächsten, und betätige dich niemals durch gewalttätiges Handeln;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 7, 'verhaßt beim Herrn und bei den Menschen ist der Übermut, und gegen beide versündigt sich die Gewalttat.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 8, 'Die Herrschaft geht von einem Volk auf das andere über infolge von Gewalttaten, Übermut und Geldgier. b [Denn es gibt nichts Gesetzwidrigeres als den Geldgierigen, der ja seine eigene Seele zum Verkauf stellt.]');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 9, 'Wie kommt Staub und Asche dazu, sich zu überheben? Denn bei lebendigem Leibe reiße ich ihm die Eingeweide aus!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 10, 'Eine leichte Krankheit – es scherzt der Arzt über sie – doch: Heute König und morgen ist er tot.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 11, 'Denn wenn der Mensch stirbt, erhält er Moder und Maden, Geschmeiß und Würmer als Besitz.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 12, 'Der Anfang des Hochmutes ist der Abfall des Menschen vom Herrn, wenn nämlich sein Herz sich von seinem Schöpfer abwendet.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 13, 'Denn der Anfang des Hochmuts ist die Sünde, und wer an ihm festhält, richtet viele Greuel an. Darum läßt der Herr wunderbare Heimsuchungen über ihn ergehen und vernichtet die Schuldigen schließlich völlig.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 14, 'Die Throne der Stolzen (g) stürzt der Herr um und setzt Sanftmütige an ihre Stelle;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 15, 'Völker rottet der Herr mit der Wurzel aus und pflanzt Demütige an ihre Stelle;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 16, 'Die Spuren der Stolzen verwischt der Herr und tilgt sie aus bis auf den Erdengrund (g);');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 17, 'er reißt sie weg aus der Erde und vernichtet sie und vertilgt ihr Gedächtnis von der Erde (g).');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 18, 'Nicht ist der Hochmut für die Menschen geschaffen, noch wütender Zorn für die von Weibern Geborenen. –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 19, 'Welches Geschlecht steht in Ehren? Das Geschlecht des Menschen. Welches Geschlecht steht in Ehren? Das Geschlecht der Gottesfürchtigen. Welches Geschlecht steht in Unehren? Das Geschlecht des Menschen; welches Geschlecht steht in Unehren? Das Geschlecht der die (göttlichen) Gebote Übertretenden.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 20, 'Im Kreise von Brüdern steht ihr Oberhaupt in Ehren, und ebenso die Gottesfürchtigen in den Augen des Herrn.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 21, 'Der Reiche und der Angesehene und der Arme – ihr Ruhm ist die Furcht des Herrn.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 22, 'Es ist nicht recht, einen verständigen Armen zu mißachten, und es ziemt sich nicht, einen sündigen Menschen zu ehren.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 23, 'Der Hochstehende und Herrscher und Gewalthaber stehen hoch in Ehren, und doch steht keiner von ihnen höher als der Gottesfürchtige.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 24, 'Einem umsichtigen Knechte leisten die Freien Dienste, und ein verständiger Mensch murrt nicht (wenn er zurechtgewiesen wird).');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 25, 'Tue nicht klug bei Verrichtung deiner Arbeit und tue nicht vornehm, wenn du Mangel leidest.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 26, 'Besser ist daran, wer arbeitet und Überfluß an allem hat, als wer groß tut und Mangel an Brot hat.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 27, 'Mein Sohn, in Demut zolle dir selbst Hochachtung und erweise dir Ehre, soweit du es wirklich verdienst.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 28, 'Wer wird dem Anerkennung gewähren, der gegen sich selbst sündigt? Und wer wird den ehren, der sich selbst verunehrt?');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 29, 'Mancher Arme wird geehrt um seiner Einsicht willen, und mancher Reiche wird nur um seines Reichtums willen geehrt.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 30, 'Wer aber trotz seiner Armut in Ehren steht, – wie erst, wenn er reich wäre! und wer trotz seines Reichtums ungeehrt ist, – wie erst, wenn er arm wäre!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 31, 'Die Weisheit des Niedrigen erhöht sein Haupt und weist ihm seinen Platz unter den Großen an.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 32, '');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 33, '');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 34, '');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 1, 'Lobe keinen Menschen um seiner Schönheit willen und verabscheue niemand um seines Aussehens willen:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 2, 'klein ist unter den Flugtieren die Biene, und doch steht, was sie schafft, unter den Süßigkeiten obenan.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 3, 'Rühme dich nicht der Kleider, die du anhast, und überhebe dich nicht am Tage, wo du in voller Pracht erscheinst; denn wunderbar sind die Werke des Herrn, und verborgen sind seine Werke vor den Menschen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 4, 'Viele Herrscher haben am Boden sitzen müssen, und der, an den niemand gedacht hatte, hat die Krone getragen;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 5, 'viele Machthaber sind schimpflich entehrt und Hochgestellte der Gewalt anderer preisgegeben worden.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 6, 'Tadle nicht, ehe du geprüft hast; untersuche zuerst und dann erkläre für falsch.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 7, 'Antworte nicht, ehe du gehört hast, und falle niemandem mitten in die Rede hinein.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 8, 'Über eine Sache, die dich nichts angeht, streite nicht, und wenn Sünder zu Gericht sitzen, so setze dich nicht mit hin.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 9, 'Mein Sohn, laß dich nicht auf vielerlei Geschäfte ein, denn wenn du vielerlei Dinge betreibst, wirst du nicht frei von Schuld bleiben; und wenn du ihnen nachjagst, wirst du doch nichts erreichen und, wenn du davonläufst, doch nicht entrinnen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 10, 'Mancher müht sich ab und plagt sich und hastet und bleibt nur umsomehr zurück;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 11, 'ein anderer ist langsam und bedarf der Beihilfe, hat Mangel an Kraft und Überfluß an Armut, aber die Augen des Herrn blicken gütig auf ihn, und er hebt ihn empor aus seiner Niedrigkeit (h)');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 12, 'und erhöht ihm das Haupt, so daß viele sich über ihn verwundern.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 13, 'Glück und Unglück, Leben und Tod, Armut und Reichtum kommen vom Herrn. b [Weisheit und Einsicht und Kenntnis des Gesetzes kommen vom Herrn; Liebe und die Wege guter Werke kommen von ihm. Irrtum und Finsternis sind mit den Sündern zugleich erschaffen; wer sich aber seiner Bosheit rühmt, mit dem zugleich altert das Böse].');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 14, 'Was der Herr gibt, verbleibt den Frommen, und sein Wohlgefallen verleiht immerdauerndes Wohlergehen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 15, 'Mancher wird reich durch sein Sparen und seine Knickerei, und folgender Lohn wird ihm dafür zuteil:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 16, 'er kann sagen: »Ich habe nun Ruhe erlangt, jetzt will ich meine Güter genießen«. Er weiß doch nicht, wie viel Zeit noch vergehen wird, bis er sein Gut anderen überlassen und sterben muß. –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 17, 'Mein Sohn, bleibe in deinem Berufe und laß ihn dir gefallen und werde alt in deinem Geschäft.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 18, 'Wundere dich nicht über die Erfolge der Sünder, vertraue vielmehr dem Herrn und harre in deiner Mühsal aus (h); denn ein leichtes ist es in den Augen des Herrn, einen Armen schnell und unvermutet reich zu machen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 19, 'Der Segen des Herrn ist der Lohn des Frommen, und in kurzer Frist läßt er seinen Segen erblühen (h).');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 20, 'Sage nicht: »Was habe ich noch nötig? und welche Glücksgüter können mir von nun an noch zuteil werden?«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 21, 'Sage auch nicht: »Ich habe genug, und welches Unglück kann mir von nun an noch widerfahren?«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 22, 'Zur Zeit des Glücks vergißt man das Unglück, und zur Zeit des Unglücks denkt man nicht mehr an das Glück;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 23, 'denn ein leichtes ist es dem Herrn, am Todestage einem jeden nach seinem Wandel zu vergelten.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 24, 'Böse Zeit bewirkt Vergessen des (früheren) Wohllebens, und beim Lebensabschluß eines Menschen werden seine Taten offenbar.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 25, 'Vor dem Tode preise niemand glücklich, und erst an seinem Ende wird der Mann erkannt.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 26, 'Nicht jeden Menschen führe in dein Haus, denn vielfältig sind die Nachstellungen des Betrügers.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 27, 'Wie ein zur Jagd abgerichtetes Rebhuhn im Korbe, so ist das Herz des Stolzen und wie ein Späher der nach einer Blöße ausspäht;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 28, 'denn hinterlistig lauernd, verkehrt er das Gute in Böses und hängt den trefflichsten Dingen einen Schandfleck an (h).');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 29, 'Von einem Feuerfunken entsteht ein großer Kohlenbrand; so lauert auch ein ruchloser Mensch auf Blutvergießen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 30, 'Sei auf der Hut vor dem Bösewicht, denn er schmiedet Unheil, damit er dir nicht einen unauslöschlichen Schandfleck anhänge (h).');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 31, 'Nimmst du einen Fremden in dein Haus auf, so wird er dich in Unruhe stürzen und dich deinen Angehörigen entfremden.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 32, '');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 33, '');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 34, '');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 35, '');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 1, 'Willst du wohltun, so achte darauf, wenn du Gutes erweisest, so wirst du für deine Wohltaten Dank ernten.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 2, 'Tue dem Frommen wohl, so wirst du Vergeltung erlangen, und zwar wenn nicht von ihm, so doch vom Höchsten.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 3, 'Nicht sind Wohltaten dem zu erweisen, der immerfort auf Böses sinnt, noch auch dem, der die Mildtätigkeit nicht mit Dank vergilt.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 4, 'Gib dem Frommen, des Sünders aber nimm dich nicht an.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 5, 'Tue dem Demütigen Gutes, aber dem Gottlosen gib nichts; versage ihm das Brot und gib es ihm nicht, damit er dich dadurch nicht in seine Gewalt bekomme; denn doppelt so viel Böses wirst du von ihm erhalten für alles Gute, das du ihm erweisest;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 6, 'denn auch der Höchste haßt die Sünder und vergilt den Gottlosen mit Strafe.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 7, 'Gib dem Guten, des Sünders aber nimm dich nicht an.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 8, 'Im Glück läßt sich der Freund nicht erkennen, aber im Unglück bleibt der Feind nicht verborgen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 9, 'Im Glück eines Menschen ist auch der Feind ein Freund (g), aber wenn es ihm unglücklich geht, trennt sich auch der Freund von ihm.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 10, 'Traue deinem Feinde niemals, denn wie das Eisen, so rostet auch seine Schlechtigkeit;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 11, 'auch wenn er sich demütig stellt und gebückt einhergeht, so gib acht und sei vor ihm auf der Hut; sei ihm gegenüber wie einer, der den Spiegel putzt, so wirst du erkennen, daß der Rost nicht für immer auf ihm festgesessen hat.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 12, 'Laß ihn nicht neben dir stehen, damit er dich nicht stürze und an deine Stelle trete; laß ihn nicht zu deiner Rechten sitzen, damit er nicht nach deinem Sitz trachte; du würdest sonst zuguterletzt erkennen, daß ich recht hatte, und über meine Warnungen seufzen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 13, 'Wer bedauert einen Beschwörer, der von seiner Schlange gebissen wird, und alle die, welche sich mit wilden Tieren zu schaffen machen?');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 14, 'Ebenso ergeht es dem, der mit einem Sünder umgeht und sich mit seinen Sünden befleckt:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 15, 'eine Zeitlang bleibt er bei dir, aber wenn du wankst, so hält er nicht stand.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 16, 'Auf seinen Lippen hat der Feind freundliche Worte, aber in seinem Herzen sinnt er darauf, dich in die Grube zu stoßen; mit seinen Augen vergießt der Feind Tränen, wenn er aber eine gute Gelegenheit findet, wird er des Blutvergießens nicht satt;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 17, 'wenn Unglück dir zustößt, so wirst du ihn noch früher als dich selbst an der Unglücksstätte antreffen, und als ob er dir helfen wollte, stellt er dir ein Bein;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 18, 'er schüttelt den Kopf und klatscht in die Hände, und mit vielem Zischeln verzieht er das Gesicht.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 19, '');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 1, 'Wer Pech angreift, besudelt sich, und wer mit dem Hochmütigen umgeht, wird ihm ähnlich.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 2, 'Eine Last, die über deine Kräfte geht, hebe nicht auf, und mit einem, der (mächtiger und) reicher ist als du, gehe nicht um; was hat der (irdene) Kochtopf mit dem (eisernen) Kessel zu tun? Dieser stößt an ihn und jener zerbricht.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 3, 'Der Reiche tut Unrecht und schilt noch dazu, der Arme erleidet Unrecht und muß obendrein noch um Verzeihung bitten.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 4, 'Wenn du für ihn brauchbar bist, bemüht er sich um dich, wenn du aber Mangel leidest, so läßt er dich im Stich;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 5, 'wenn du etwas hast, so lebt er mit dir zusammen und leert dich aus, ohne selbst sich zu mühen;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 6, 'hat er dich nötig, so täuscht er dich; er lächelt dir zu und macht dir Hoffnungen, [redet schöne Worte zu dir und fragt: »Womit kann ich dir dienen?«]');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 7, 'und beschämt dich durch seine Bewirtungen, bis er dich drei- oder viermal ausgebeutet hat, und schließlich verlacht er dich noch. Sieht er dich später einmal, so läßt er dich unbeachtet und schüttelt den Kopf über dich.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 8, 'Nimm dich in acht, daß du nicht betrogen werdest und nicht gedemütigt in deiner Freude.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 9, 'Lädt ein Mächtiger dich zu sich ein, so halte dich zurück: er wird dich um so dringender zu sich einladen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 10, 'Dränge dich nicht herzu, damit du nicht zurückgewiesen werdest, halte dich aber auch nicht fern, damit du nicht vergessen werdest.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 11, 'Trachte nicht danach, mit ihm wie mit deinesgleichen zu reden, und traue nicht seinem vielen Gerede; denn mit seinem vielen Geplauder will er dich in Versuchung führen und durch sein Anlächeln dich ausforschen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 12, 'Ohne Erbarmen ist der, welcher die Worte nicht bei sich behält, und wird sicherlich mit Mißhandlung und Banden nicht sparsam verfahren (? h).');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 13, 'Gib wohl acht und sei sorgsam auf der Hut, denn du wandelst in Begleitung deines Sturzes.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 14, 'Jedes Tier liebt seinesgleichen und jeder Mensch den, der ihm ähnlich ist (oder den ihm Gleichgestellten).');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 15, 'Jedes Geschöpf gesellt sich zu seiner Art, und so schließe sich auch der Mensch an seinesgleichen an.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 16, 'Welche Gemeinschaft hat der Wolf mit dem Lamm? Ebenso steht es mit dem Gottlosen gegenüber dem Frommen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 17, 'Wie kann Friede bestehen zwischen der Hyäne und dem Hunde? und welcher Friede herrscht zwischen dem Reichen und dem Armen?');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 18, 'Die Jagdbeute der Löwen sind die Wildesel der Steppe; ebenso bilden die Armen die Weide der Reichen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 19, 'Ein Greuel für den Hochmütigen ist die Demut; ebenso ist der Arme ein Greuel für den Reichen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 20, 'Gerät der Reiche ins Wanken, so wird er von Freunden gestützt; ist aber der Arme zu Fall gekommen, so wird er von Freunden vollends zur Seite gestoßen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 21, 'Hat ein Reicher sich verfehlt (h), so sind viele Verteidiger da; hat er Häßliches geredet, so rechtfertigt man es; hat aber ein Niedriger sich verfehlt (h), so macht man ihm obendrein Vorwürfe; auch wenn er Verständiges redet, schenkt man ihm keine Beachtung.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 22, 'Redet ein Reicher, so schweigen alle und erheben seine Worte bis an die Wolken; doch redet der Arme, so heißt’s:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 23, '»Wer ist der?« und stößt er an, so bringt man ihn vollends zu Fall.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 24, 'Gut ist der Reichtum, an dem keine Sünde klebt, und schlimm ist die Armut nach der Aussage des Gottlosen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 25, 'Das Herz des Menschen verändert sein Angesicht, bald zum Guten, bald zum Schlimmen;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 26, 'das Zeichen eines Herzens im Glück ist ein heiteres Angesicht, aber das Ersinnen von Denksprüchen erfordert mühsames Nachdenken.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 27, '');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 28, '');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 29, '');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 30, '');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 31, '');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 32, '');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 14, 1, 'Heil dem Manne, der sich nicht mit seinem Munde verfehlt und der nicht gequält wird vom Kummer über seine Sünden! Heil dem Manne, der sich nicht mit seinem Munde verfehlt und der nicht gequält wird vom Kummer über seine Sünden!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 14, 2, 'Heil dem, den sein Bewußtsein (oder Gewissen) nicht verurteilt und der seiner Hoffnung nicht verlustig gegangen ist! Heil dem, den sein Bewußtsein (oder Gewissen) nicht verurteilt und der seiner Hoffnung nicht verlustig gegangen ist!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 14, 3, 'Für einen knauserigen Menschen ist der Reichtum nicht gut, und wozu dient das Geld einem mißgünstigen Menschen? Für einen knauserigen Menschen ist der Reichtum nicht gut, und wozu dient das Geld einem mißgünstigen Menschen?');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 14, 4, 'Wer da sammelt und sichs abdarbt, sammelt für andere, und in seinen Gütern werden andere schwelgen (h). Wer da sammelt und sichs abdarbt, sammelt für andere, und in seinen Gütern werden andere schwelgen (h).');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 14, 5, 'Wer gegen sich selbst hartherzig ist, gegen wen sollte der gütig sein? Niemals wird ein solcher seines Geldes froh werden. Wer gegen sich selbst hartherzig ist, gegen wen sollte der gütig sein? Niemals wird ein solcher seines Geldes froh werden.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 14, 6, 'Kein Mensch ist bösartiger, als wer sich selbst nichts gönnt, und gerade dies ist der Lohn für seine Schlechtigkeit. Kein Mensch ist bösartiger, als wer sich selbst nichts gönnt, und gerade dies ist der Lohn für seine Schlechtigkeit.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 14, 7, 'Tut er wirklich einmal Gutes, so tut er’s aus Vergeßlichkeit, und zuletzt macht er doch seine Schlechtigkeit offenbar. Tut er wirklich einmal Gutes, so tut er’s aus Vergeßlichkeit, und zuletzt macht er doch seine Schlechtigkeit offenbar.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 14, 8, 'Schlecht ist der mißgünstig Blickende, der sein Angesicht wegwendet (h) und andere Seelen nicht beachtet. Schlecht ist der mißgünstig Blickende, der sein Angesicht wegwendet (h) und andere Seelen nicht beachtet.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 14, 9, 'Des Habgierigen Auge ist mit seinem Anteil nicht zufrieden, und seine böse Ungerechtigkeit trocknet ihm die Seele aus. Des Habgierigen Auge ist mit seinem Anteil nicht zufrieden, und seine böse Ungerechtigkeit trocknet ihm die Seele aus.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 14, 10, 'Ein böses Auge ist neidisch sogar beim Brot und leidet Mangel am eigenen Tisch. Ein böses Auge ist neidisch sogar beim Brot und leidet Mangel am eigenen Tisch.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 14, 11, 'Mein Sohn, tue dir gütlich nach deinem Vermögen und bringe dem Herrn in gebührender Weise Gaben dar.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 14, 12, 'Bedenke wohl, daß der Tod nicht säumt und daß der Beschluß der Unterwelt dir nicht kundgetan ist.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 14, 13, 'Bevor du stirbst, tue deinem Freunde Gutes, und nach deinem Vermögen reiche dar und gib ihm.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 14, 14, 'Laß keinen guten Tag unbenutzt entschwinden und laß deinen Anteil an einem erlaubten Genuß dir nicht verloren gehen;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 14, 15, 'mußt du nicht einem andern den Ertrag deiner mühsamen Arbeit hinterlassen und dein sauer Erworbenes der Verteilung durchs Los?');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 14, 16, 'Gib und nimm an und rede dir selbst zu; denn in der Unterwelt kann man keinem Wohlleben nachgehen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 14, 17, 'Alles Fleisch wird alt wie ein Gewand; denn von Ewigkeit her besteht das Gesetz: »Du mußt sterben«.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 14, 18, 'Wie die sprossenden Blätter am dichtbelaubten Baume – die einen fallen ab, andere wachsen hervor –: ebenso ist’s mit den Geschlechtern von Fleisch und Blut: das eine stirbt, und ein anderes wird geboren.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 14, 19, 'Jedes seiner Werke vermodert und nimmt ein Ende, und was seine Hände schaffen, folgt ihm nach (g).');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 14, 20, 'Heil dem Manne, der über die Weisheit nachsinnt und mit seiner Einsicht überlegt,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 14, 21, 'der die Wege zu ihr in seinem Herzen erwägt und über ihre Geheimnisse nachdenkt,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 14, 22, 'indem er ihr nachgeht wie ein Späher und an den Wegen lauert, auf denen sie geht,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 14, 23, 'der durch ihre Fenster hineinguckt und an ihren Türen horcht,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 14, 24, 'der ganz nahe bei ihrer Wohnung Rast hält und seinen Zeltpflock in ihre Wände einschlägt,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 14, 25, 'sein Zelt aufschlägt ihr zur Seite und so Einkehr hält in guter Herberge,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 14, 26, 'auch sein Nest in ihrem Laubdach baut (g) und unter ihren Zweigen dauernd weilt:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 14, 27, 'der wird durch sie vor der Sonnenglut beschirmt und herbergt bei ihr in Herrlichkeit (g).');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 15, 1, 'Wer den Herrn fürchtet, verfährt so, und wer sich an das Gesetz hält, wird sie erlangen;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 15, 2, 'und sie wird ihm entgegenkommen wie eine Mutter und wie ein Weib der Jugendliebe ihn aufnehmen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 15, 3, 'Sie wird ihn speisen mit dem Brot der Einsicht und das Wasser der Erkenntnis (g) ihm zu trinken geben.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 15, 4, 'Er wird sich auf sie stützen und nicht ins Wanken geraten, und er wird sich an sie halten und nicht enttäuscht werden;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 15, 5, 'sie wird ihn über seine Genossen erhöhen und ihm inmitten der Gemeinde den Mund auftun;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 15, 6, 'Frohsinn und eine Ruhmeskrone (h) und einen ewigen Namen wird er erlangen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 15, 7, 'Unverständige Menschen werden sie sich niemals aneignen und die Sünder (h) sie nicht zu sehen bekommen;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 15, 8, 'fern bleibt sie von den Übermütigen (h), und die Lügner denken nicht an sie.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 15, 9, 'Übel klingt ihr Lobpreis im Munde des Sünders, weil ihm ein solcher vom Herrn nicht eingegeben wird;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 15, 10, 'denn nur durch den Mund des Weisen soll ein Loblied gesprochen werden, und wer seiner mächtig ist, soll es lehren (g).');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 15, 11, 'Sage nicht: »Durch Gott bin ich zum Abfall (von ihm) gekommen«; denn er bewirkt nicht das, was er haßt (g).');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 15, 12, 'Sage nicht: »Er hat mich zu Fall gebracht«; denn er bedarf keines sündigen Menschen (h).');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 15, 13, 'Jeglichen Greuel haßt der Herr, und er läßt es nicht zustoßen denen, die ihn fürchten (g).');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 15, 14, 'Gott hat den Menschen im Anbeginn geschaffen und ihn seiner eigenen Willensentscheidung überlassen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 15, 15, 'Wenn du willst, kannst du die Gebote halten, und Treue zu beweisen hängt von deinem freien Willen ab.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 15, 16, 'Feuer und Wasser hat er dir vorgelegt: strecke deine Hand aus, wonach du willst.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 15, 17, 'Vor dem Menschen liegen Leben und Tod: was ihm beliebt, wird ihm gegeben.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 15, 18, 'Denn groß ist die Weisheit des Herrn; stark ist er an Macht und sieht alles;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 15, 19, 'und seine Augen sind auf die gerichtet, welche ihn fürchten, und er kennt alles Tun der Menschen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 15, 20, 'Keinem Menschen hat er geboten, gottlos zu sein, und keinem die Erlaubnis gegeben, zu sündigen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 15, 21, '');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 16, 1, 'Wünsche dir nicht eine Menge nichtsnutziger Kinder, und freue dich nicht über gottlose Söhne.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 16, 2, 'Wenn sie zahlreich werden, freue dich nicht über sie, wenn keine Gottesfurcht in ihnen wohnt.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 16, 3, 'Verlaß dich nicht auf ihr langes Leben und setze dein Vertrauen nicht auf ihre Wohnstätte; denn ein einziges kann besser sein als tausend, und kinderlos sterben ist besser als der Besitz gottloser Kinder.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 16, 4, 'Denn durch einen Gottesfürchtigen (g) wird eine Stadt bevölkert, aber durch ein Geschlecht von Gottlosen verödet sie.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 16, 5, 'Vieles derartige habe ich mit eigenen Augen gesehen, und noch Gewaltigeres hat mein Ohr vernommen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 16, 6, 'Gegen die Rotte der Gottlosen loderte das Feuer auf, und gegen ein ungehorsames Volk entbrannte der Zorn (Gottes) (g);');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 16, 7, 'er verzieh nicht den Riesen der Vorzeit, die im Gefühl ihrer Kraft sich empörten;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 16, 8, 'er verschonte auch nicht die Ortsgenossen Lots, die sicher waren in ihrem Übermut (g);');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 16, 9, 'nicht erbarmte er sich des dem Untergange geweihten Volkes, das wegen seiner Sünden vertilgt wurde.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 16, 10, 'Und ebenso erging es den sechsmalhunderttausend Mann Fußvolks, die allesamt hingerafft wurden wegen ihrer Verstocktheit.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 16, 11, 'Und nun gar der Einzelne, der halsstarrig ist: ein Wunder wäre es, wenn er ungestraft bliebe; denn wie Erbarmen, so ist auch Zorn bei ihm; er hat die Macht zu verzeihen und gießt auch seinen Zorn aus;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 16, 12, 'so groß wie seine Gnade, ebenso groß ist auch seine Züchtigung; jeden richtet er nach seinen Werken.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 16, 13, 'Nicht entkommt der Frevler mit seinem Raube, und niemals läßt er die Hoffnung des Frommen unerfüllt;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 16, 14, 'für jeden, der Wohltätigkeit übt, gibt es einen Lohn (g), ein jeder empfängt nach seinen Werken. b [Der Herr verhärtete den Pharao, so daß dieser ihn nicht erkannte, damit seine Machterweise dem Erdkreise unter dem ganzen Himmel kund würden; der ganzen Schöpfung ist sein Erbarmen offenbar, und sein Licht und seine Finsternis hat er den Menschen zugeteilt.]');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 16, 15, 'Sage nicht: »Ich bin vor Gott verborgen, und wer wird in der Höhe meiner gedenken? Unter den vielen Leuten bleibe ich unbemerkt, und was bin ich in der unermeßlichen Schöpfung«?');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 16, 16, 'Bedenke wohl: der Himmel und der Himmel des Himmels, das Weltmeer und die Erde erbeben, wenn er sie heimsucht;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 16, 17, 'die Berge allzumal und die Grundseiten der Erde erzittern vor Schrecken, wenn er sie anschaut.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 16, 18, 'Doch darauf achtet das Herz nicht, und wer bedenkt sein Walten?');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 16, 19, 'Ja, wie der Sturmwind, den der Mensch nicht sehen kann, so sind die meisten seiner Werke verborgen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 16, 20, '»Wer wird die Betätigungen seiner Gerechtigkeit verkündigen oder wer sie erwarten? In weiter Ferne liegt ja der Bund«.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 16, 21, 'Wer Mangel an Einsicht hat, denkt so, und nur ein unverständiger (und auf Irrwegen wandelnder) Mensch ist so törichter Ansicht.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 16, 22, 'Höre mir zu, mein Sohn, und lerne Einsicht und auf meine Worte richte deinen Sinn!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 16, 23, 'Ich will dir wohlabgewogene Lehre kundtun (h) und mit Genauigkeit meine Erkenntnis offenbaren.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 16, 24, 'Nach dem Ratschluß des Herrn sind seine Werke von Anfang an entstanden (h), und seit ihrer Erschaffung hat er ihre Teile geschieden.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 16, 25, 'Er ordnete seine Werke für ewige Zeiten und ihre Machtbereiche für ihre Geschlechter; nicht hungern sie und nicht ermüden sie und lassen von ihren Arbeiten nicht ab;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 16, 26, 'keines befeindet das andere, und bis in Ewigkeit sind sie seinem Gebot nicht ungehorsam.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 16, 27, 'Und hierauf blickte der Herr auf die Erde und füllte sie mit seinen Gütern an;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 16, 28, 'mit allerlei lebenden Wesen bedeckte er ihre Oberfläche, und zu ihr (oder in sie) kehren sie (im Tode) zurück.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 16, 29, '');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 16, 30, '');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 17, 1, 'Der Herr hat den Menschen aus Erde geschaffen und läßt ihn wieder zu ihr (oder in sie) zurückkehren.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 17, 2, 'Lebenstage von bestimmter Zahl und eine Frist teilte er ihnen zu und verlieh ihnen Gewalt über alles, was auf ihr ist;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 17, 3, 'ihm selbst ähnlich, rüstete er sie mit Kraft aus und gestaltete sie nach seinem Bilde.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 17, 4, 'Die Furcht vor ihnen legte er auf alles Fleisch, auf daß sie die Herrschaft über die Tiere und Vögel besäßen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 17, 5, 'Urteilskraft und Sprache und Augen, Ohren und ein Herz zum Denken gab er ihnen;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 17, 6, 'verständige Einsicht verlieh er ihnen reichlich und lehrte sie Gutes und Böses unterscheiden;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 17, 7, 'er richtete sein Auge auf ihre Herzen, um ihnen die Erhabenheit seiner Werke zu zeigen,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 17, 8, 'damit sie seinen heiligen Namen priesen und die Erhabenheit seiner Werke (oder die Großtaten seines Waltens) verkündigten.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 17, 9, 'Er teilte ihnen Einsicht zu und gab ihnen das lebenwirkende Gesetz zum Besitz;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 17, 10, 'einen ewigen Bund schloß er mit ihnen und tat ihnen seine Rechte kund;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 17, 11, 'die Erhabenheit seiner Majestät schauten ihre Augen, und die Herrlichkeit seiner Stimme vernahm ihr Ohr;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 17, 12, 'und er gebot ihnen; »Hütet euch vor jeglichem Unrecht!« und schrieb einem jeden von ihnen die Pflichten gegen den Nächsten vor.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 17, 13, 'Ihr Wandel liegt immerdar offen vor ihm, nicht können sie sich vor seinen Augen verbergen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 17, 14, 'Jedem Volk hat er einen Herrscher gesetzt, aber Israel ist der Anteil, den der Herr für sich genommen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 17, 15, 'Alle ihre Werke stehen vor ihm wie die Sonne, und seine Augen blicken beständig auf ihren Wandel;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 17, 16, 'nicht sind ihre Böstaten ihm verborgen, und alle ihre Sünden sind dem Herrn bekannt.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 17, 17, 'Die Mildtätigkeit eines Mannes ist bei ihm wie ein Siegelring, und die Liebestat eines Menschen hütet er wie den Augapfel.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 17, 18, 'Späterhin wird er sich erheben und ihnen vergelten und ihnen die Vergeltung auf ihr Haupt zurückzahlen;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 17, 19, 'jedoch denen, die sich bekehren, gestattet er die Rückkehr, und die, welchen das Vertrauen geschwunden ist, ermutigt er wieder.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 17, 20, 'Bekehre dich zum Herrn und laß ab von den Sünden, bete im Aufblick zu ihm und mindere die Zahl deiner Fehltritte;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 17, 21, 'kehre zum Höchsten zurück und wende dich ab vom Unrechttun und hasse aufrichtig den Sündengreuel.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 17, 22, 'Wer wird dem Höchsten in der Unterwelt lobsingen an Stelle derer, die da leben und ihm Lobpreis darbringen?');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 17, 23, 'Für den Toten, der ja nicht mehr ist, hat der Lobpreis ein Ende; nur wer lebt und gesund ist, kann den Herrn preisen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 17, 24, 'Wie groß ist die Barmherzigkeit des Herrn und seine Versöhnlichkeit für die, welche sich zu ihm bekehren!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 17, 25, 'Denn nicht kann die ganze Vollkommenheit in den Menschen vorhanden sein, weil ja die Menschenkinder nicht unsterblich sind.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 17, 26, 'Was ist heller als die Sonne? und sogar sie verfinstert sich; so richtet auch der Böse seinen Sinn auf Fleisch und Blut.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 17, 27, 'Die Heerscharen des Himmels droben mustert Gott, aber die Menschen allesamt sind Staub und Asche.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 17, 28, '');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 17, 29, '');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 17, 30, '');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 17, 31, '');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 1, 'Er, der in Ewigkeit Lebende, hat alles ohne Ausnahme geschaffen;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 2, 'der Herr allein bewährt sich als gerecht.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 3, 'Niemandem verleiht er die Fähigkeit, seine Werke zu verkünden, und wer vermag seine Großtaten zu erforschen?');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 4, 'Wer kann seine gewaltige Erhabenheit zutreffend ermessen und wer noch überdies seine Gnadenerweise aufzählen?');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 5, 'Es geht nicht an, etwas davon abzuziehen, noch etwas hinzuzufügen, und es ist unmöglich, die Wundertaten des Herrn zu erforschen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 6, 'Wenn der Mensch damit zu Ende ist, fängt er eben erst an, und wenn er aufhört, fühlt er sein Unvermögen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 7, 'Was ist der Mensch, und wozu ist er nütze? worin besteht sein Glück und worin sein Unglück?');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 8, 'Die Zahl der Lebenstage eines Menschen beträgt, wenn’s hoch kommt, hundert Jahre.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 9, 'Wie ein Wassertropfen aus dem Meer und wie ein Sandkorn (am Meer), so sind diese wenigen Jahre im Verhältnis zu einem Tage der Ewigkeit.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 10, 'Darum ist der Herr langmütig gegen sie und gießt seine Barmherzigkeit über sie aus;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 11, 'er sieht und erkennt, daß ihr Ende böse ist; darum gewährt er ihnen reichlich seine Vergebung.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 12, 'Das Erbarmen eines Menschen gilt seinem Nächsten, aber das Erbarmen des Herrn erstreckt sich über alles Fleisch; er weist zurecht, erzieht und belehrt und führt wie ein Hirt seine Herde zurück;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 13, 'er erbarmt sich derer, die seine Zucht annehmen, und derer, die zu seinem Erbarmen herzueilen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 14, 'Mein Sohn, beim Gutestun füge keinen Vorwurf hinzu und bei keiner Gabe verletzende Worte.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 15, 'Macht nicht der Tau der Hitze des Glutwindes ein Ende? So ist auch ein (beigefügtes gutes) Wort besser als die Gabe (selbst).');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 16, 'Bedenke wohl: ist nicht ein (gutes) Wort mehr wert als eine wohltätige Gabe? und beides steht einem freundlichen Manne zur Verfügung.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 17, 'Der Tor macht auf unliebenswürdige Weise Vorwürfe, und die Gabe des Mißgünstigen preßt den Augen Tränen aus.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 18, 'Ehe du redest, lerne, und ehe du krank wirst, sorge für deine Gesundheit;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 19, 'ehe das Gericht (Gottes) eintritt, prüfe dich selbst, so wirst du zur Zeit der Heimsuchung Verzeihung erlangen;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 20, 'ehe du in Krankheit verfällst, demütige dich, und in der Zeit deiner Verfehlungen lege Bekehrung an den Tag.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 21, 'Versäume nicht, ein Gelübde rechtzeitig zu erfüllen, und warte nicht bis zum Tode, um dich davon frei zu machen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 22, 'Ehe du ein Gelübde tust, stelle eine sorgfältige Überlegung an und sei nicht wie ein Mensch, der den Herrn versucht.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 23, 'Denke an den Zorn (Gottes) in den Tagen des Endes und an die Zeit der Vergeltung, wenn er sein Angesicht von dir abwendet.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 24, 'Denke an die Zeit des Hungers zur Zeit des Überflusses, an Armut und Mangel in den Tagen des Reichtums.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 25, 'Vom Morgen bis zum Abend kann die Zeit sich ändern, und alles verläuft schnell vor den Augen des Herrn.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 26, 'Der weise Mann ist in allen Stücken auf seiner Hut und hütet sich in den Tagen der Sünden vor Verfehlung.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 27, 'Jeder Verständige kennt die Weisheit und zollt dem, der sie erlangt hat, Anerkennung.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 28, 'Diejenigen, welche Verständnis für Spruchreden besitzen, beweisen sich auch selbst als weise und strömen zutreffende Sinnsprüche in Menge aus.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 29, 'Gehe nicht deinen Begierden nach und halte dich von deinen Lüsten zurück;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 30, 'denn wenn du deiner Seele das Wohlgefallen an den Lüsten gestattest, so wird sie dich zum Gespött deiner Feinde machen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 31, 'Habe keine Freude an häufiger Schwelgerei und beteilige dich nicht an üppigen Gelagen (h);');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 32, 'mache dich nicht arm, indem du Schmausereien mit geborgtem Gelde veranstaltest, während du nichts im eigenen Beutel hast.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 33, '');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 1, 'Ein dem Trunk ergebener Arbeiter wird nicht reich, und wer das Wenige nicht zu Rate hält, wird gar bald herunterkommen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 2, 'Wein und Weiber machen das Herz zuchtlos (g), und wer sich an Dirnen hängt, treibt’s noch toller (h).');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 3, 'Maden und Würmer nehmen ihn in Besitz, und wer toll daraufloslebt, wird hinweggerafft.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 4, 'Wer schnell Vertrauen schenkt, ist leichtsinnig, und wer sich dadurch vergeht, fügt sich selbst Schaden zu.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 5, 'Wer ein schadenfrohes Herz hat, wird Tadel erfahren,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 6, 'und wer Geschwätz weitersagt, beweist Mangel an Einsicht.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 7, 'Niemals erzähle ein Gerede weiter, so wird dir nimmermehr ein Nachteil erwachsen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 8, 'Bei Freund und bei Feind erzähle es nicht weiter, und wenn es dir keine Sünde ist, so spricht nicht darüber;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 9, 'denn hat man’s von dir gehört, so hütet man sich vor dir und erweist dir Haß zu geeigneter Zeit.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 10, 'Hast du ein Gerede gehört, so laß es mit dir sterben; sei ohne Sorge: du wirst nicht davon platzen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 11, 'Infolge eines (zu verschweigenden) Wortes leidet der Tor Geburtsschmerzen wie eine Gebärende infolge der Leibesfrucht;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 12, 'wie ein Pfeil, der im fleischigen Schenkel eines Mannes steckt, ebenso ist ein (zu verschweigendes) Wort im Inneren eines Toren.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 13, 'Stelle den Freund zur Rede, ob er es etwa gar nicht getan hat, und wenn er sich etwas hat zu Schulden kommen lassen, daß er es nicht wieder tue.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 14, 'Stelle den Nächsten zur Rede, ob er es etwa gar nicht gesagt hat, und wenn er’s gesagt hat, daß er es nicht nochmals sage.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 15, 'Stelle den Freund zur Rede, denn gar oft kommt Verleumdung vor, und glaube nicht jedem Gerede.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 16, 'Mancher verfehlt sich, aber nicht absichtlich, und wer hätte sich noch nie mit seiner Zunge vergangen?');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 17, 'Stelle deinen Nächsten zur Rede, ehe du Drohworte ausstößt, und laß das Gesetz des Höchsten zur Anwendung kommen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 18, 'b [Die Furcht des Herrn ist der Anfang des (göttlichen) Wohlwollens, die Weisheit aber gewinnt sich bei ihm Liebe. Die Kenntnis der Gebote des Herrn ist lebenspendende Bildung; die aber das tun, was ihm wohlgefällt, pflücken die Frucht vom Baume der Unsterblichkeit.] a Jegliche Weisheit ist Furcht des Herrn, und mit jeglicher Weisheit ist Erfüllung des Gesetzes verbunden;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 19, 'nicht aber ist Weisheit die Kenntnis der Schlechtigkeit, und keine Einsicht ist der Ratschlag der Sünder.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 20, 'Es gibt eine Schlauheit, und sie ist ein Greuel; und es gibt Unverständige, denen die Schlechtigkeit abgeht.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 21, 'Besser ist der Gottesfürchtige, dem es an Einsicht gebricht, als wer an Klugheit überreich, aber ein Gesetzesübertreter ist.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 22, 'Es gibt eine sorgfältig zu Werke gehende Schlauheit, und die ist ungerecht; und mancher verdreht das Recht, um einen Urteilsspruch herauszubringen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 23, 'Mancher geht gebückt einher in schwarzem Trauerkleid, aber in seinem Inneren ist er voller Tücke;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 24, 'er schlägt den Blick zur Erde nieder und stellt sich auf einem Ohre taub; wo er aber unbeobachtet ist, wird er über dich herfallen;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 25, 'und sieht er sich aus Mangel an Kraft gehindert, Böses zu tun, so wird er’s ausführen, sobald er Gelegenheit dazu findet.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 26, 'An der äußeren Erscheinung erkennt man den Mann, und an der Art seines Auftretens erkennt man den Einsichtigen;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 27, 'die Kleidung eines Mannes und das Lachen seines Mundes und der Gang eines Menschen verraten, was an ihm ist.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 20, 1, 'Es gibt eine Zurechtweisung, die zur Unzeit geschieht, und mancher schweigt, und der ist klug.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 20, 2, 'Wie viel besser ist’s, zur Rede zu stellen als (schweigend) zu grollen! und wer sein Unrecht offen zugesteht, entgeht dem Schaden. b [Wie schön ist’s, Reue an den Tag zu legen, wenn man zur Rede gestellt wird! Denn so meidet man freiwillige Verfehlungen.]');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 20, 3, 'Wie die Begierde des Entmannten, ein Mädchen zu entjungfern, so handelt der (verfehlt), welcher das Recht mit Gewalt durchsetzen will.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 20, 4, 'Mancher schweigt und wird als weise erfunden, und mancher ist verhaßt infolge seiner großen Geschwätzigkeit.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 20, 5, 'Mancher schweigt, weil er keine Antwort zur Hand hat, und mancher schweigt, weil er die rechte Zeit kennt.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 20, 6, 'Ein weiser Mann schweigt bis zur rechten Zeit, aber der Prahler und der Dumme läßt die rechte Zeit unbeachtet.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 20, 7, 'Wer viele Worte macht, erregt Abscheu, und wer hochmütig auftritt, macht sich verhaßt.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 20, 8, 'Zuweilen liegt Glück für einen Mann im Unglück, und ein Gewinn dient manchmal zum Verlust.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 20, 9, 'Es gibt Geschenke, die dir nichts nützen, und für manche Geschenke erhält man doppelte Vergeltung.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 20, 10, 'Erneidrigung kann eintreten infolge von glänzender Stellung, und mancher hebt sein Haupt aus der Niedrigkeit empor.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 20, 11, 'Mancher kauft viel um geringen Preis und muß es nachher siebenfach bezahlen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 20, 12, 'Der Weise macht sich durch seine Reden beliebt, aber die Gunstbeweise der Toren sind erfolglos verschwendet.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 20, 13, 'Die Gabe eines Toren nützt dir nichts, denn statt eines Auges hat er deren viele;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 20, 14, 'er gibt nur wenig und rückt dir viel vor und sperrt seinen Mund auf wie ein Ausrufer; heute gibt er ein Darlehen und fordert es morgen zurück: hassenswert ist solch ein Mensch!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 20, 15, 'Der Tor sagt: »Ich habe keinen Freund, und niemand dankt mir für meine Wohltaten; die mein Brot essen, sind lässig mit ihrer Zunge«:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 20, 16, 'wie oft und wie viele werden ihn auslachen!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 20, 17, 'Besser ein Fehltritt auf dem Fußboden als mit der Zunge; ebenso tritt der Sturz der Bösen gar schnell ein.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 20, 18, 'Wie ein widerwärtiger (oder unartiger) Mensch ist eine unzeitige Rede; im Munde der Ungebildeten findet sie sich allezeit.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 20, 19, 'Ein Sinnspruch, der aus dem Munde des Toren kommt, findet keinen Anklang, denn er spricht ihn nie zu rechter Zeit aus.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 20, 20, 'Mancher wird durch Armut vom Sündigen abgehalten; so hat er denn bei seinem ruhigen Leben keine Gewissensbisse.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 20, 21, 'Mancher richtet sich selbst zugrunde aus Schamgefühl und stürzt sich selbst infolge törichter Verstellung ins Verderben;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 20, 22, 'Mnacher gibt seinem Freunde aus Scham (leere) Versprechungen und macht ihn sich dadurch unnötigerweise zum Feinde.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 20, 23, 'Ein häßlicher Schandfleck am Menschen ist die Lüge; im Munde der Ungebildeten findet sie sich allezeit;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 20, 24, 'besser ist noch ein Dieb als ein immerfort Lügender; beide aber bringen Verderben über sich.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 20, 25, 'Das Ende eines lügenhaften Menschen ist ehrlos, und die Schande, die ihn trifft, bleibt für immer an ihm haften.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 20, 26, 'Der Weise bringt sich durch seine Reden zu Ehren, und ein kluger Mann gefällt den Großen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 20, 27, 'Wer den Acker bebaut, türmt seinen Garbenhaufen hoch empor; und wer den Großen gefällt, kann Verfehlungen gutmachen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 20, 28, 'Geschenke und Gaben machen die Augen (auch) der Weisen blind und hemmen, wie ein Knebel im Munde, die (gerechten) Vorwürfe.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 20, 29, 'Verborgene Weisheit und ein vergrabener Schatz – was nützen sie beide?');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 20, 30, 'Besser ein Mensch, der seine Torheit verbirgt, als ein Mensch, der seine Weisheit geheimhält. b [Besser ist unermüdliche Ausdauer im Suchen des Herrn als ein herrenloser Fuhrmann des eigenen Lebens.]');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 20, 31, '');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 20, 32, '');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 20, 33, '');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 21, 1, 'Mein Sohn, hast du gesündigt, so tu es nicht wieder, und wegen deiner früheren Sünden bitte um Vergebung.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 21, 2, 'Wie vor einer Schlange fliehe vor der Sünde; denn wenn du ihr nahe kommst, so beißt sie dich; Löwenzähne sind ihre Zähne, die die Menschen ums Leben bringen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 21, 3, 'Wie ein zweischneidiges Schwert ist jegliches Unrecht; für die Wunde, die es schlägt, gibt’s keine Heilung.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 21, 4, 'Gewalttätigkeit und Übermut verwüsten den Reichtum; ebenso wird das Haus des Übermütigen zerstört.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 21, 5, 'Das Gebot des Armen dringt aus seinem Munde bis zu den Ohren Gottes, dessen Strafgericht dann gar bald erfolgt.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 21, 6, 'Wer Zurechtweisung haßt, tritt in die Fußstapfen des Sünders; wer aber den Herrn fürchtet, nimmt sie zu Herzen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 21, 7, 'Schon von weitem her kenntlich ist der Zungenheld; der Verständige aber erkennt es, sobald er einen Fehler macht.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 21, 8, 'Wer sein Haus mit fremdem Gelde baut, ist wie einer, der Steine zu seinem eigenen Grabhügel sammelt.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 21, 9, 'Ein Haufen Werg ist die Rotte der Gottlosen, und ihr Ende ist die Feuerflamme.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 21, 10, 'Der Weg der Sünder ist mit Steinen gepflastert, aber an seinem Ende ist die Grube (oder Tiefe) der Unterwelt.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 21, 11, 'Wer das Gesetz beobachten will, bezähmt seine Gelüste, und die Vollendung der Gottesfurcht ist die Weisheit.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 21, 12, 'Wer nicht klug ist, nimmt keine Zucht an; es gibt aber auch eine Klugheit, die viel bitteren Verdruß schafft.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 21, 13, 'Die Erkenntnis des Weisen wächst an wie eine Wasserflut, und sein Ratschlag ist wie ein lebendiger Quell.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 21, 14, 'Das Innere des Toren ist wie eine zusammengestürzte Zisterne und keine Erkenntnis hält er dauernd fest.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 21, 15, 'Wenn der Verständige ein weises Wort hört, so lobt er es und fügt noch ein neues hinzu; hört es dagegen der Leichtfertige, so mißfällt es ihm und er wirft es hinter seinen Rücken.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 21, 16, 'Das Gespräch eines Toren ist wie eine Bürde auf der Reise (oder Wanderung); aber auf den Lippen des Verständigen ist Annehmlichkeit zu finden.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 21, 17, 'Nach dem Munde des Einsichtigen trägt man Verlangen in der Versammlung, und seine Worte erwägt man im Herzen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 21, 18, 'Wie ein Gefangenhaus, so ist dem Toren die Weisheit, und die Erkenntnis des Unverständigen besteht in unverständlichen Worten.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 21, 19, 'Wie Ketten an den Füßen ist für den Unverständigen die Zucht (oder die Unterweisung) und wie Handschellen am rechten Arm.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 21, 20, 'Der Tor läßt beim Lachen seine Stimme laut erschallen, aber ein kluger Mann lächelt kaum leise.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 21, 21, 'Wie Goldschmuck ist die Zucht (oder die Unterweisung) für den Klugen und wie eine Spange am rechten Arm.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 21, 22, 'Der Fuß des Toren stürmt in ein Haus hinein, aber ein welterfahrener Mann wartet draußen am Eingang.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 21, 23, 'Der Unverständige guckt schon von der Tür aus ins Haus hinein, aber der gebildete Mann bleibt draußen stehen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 21, 24, 'Es ist ein Ungezogenheit, an der Tür zu horchen; der Verständige fühlt sich dadurch mit Schimpf beladen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 21, 25, 'Die Lippen der Toren ergehen sich in Unbesonnenheit, aber die Worte der Klugen sind mit der Wage abgewogen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 21, 26, 'Im Munde der Toren ist ihr Herz, aber das Herz der Weisen ist ihr Mund.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 21, 27, 'Wenn der Gottlose den Satan verflucht, so verflucht er sich selbst.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 21, 28, 'Der Ohrenbläser macht sich selbst ehrlos und wird gehaßt, wo er auch weilt.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 21, 29, '');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 21, 30, '');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 21, 31, '');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 22, 1, 'Einem beschmutzten Steine gleicht der Faule; ein jeder zischt über ihn wegen seiner ekelhaften Beschaffenheit.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 22, 2, 'Einem Mistklumpen gleicht der Faule; jeder, der ihn aufhebt, schüttelt die Hand ab.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 22, 3, 'Eine Schande für einen Vater ist der Besitz eines zuchtlosen Sohnes; eine (derartige) Tochter aber wird ihm zum Schaden geboren.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 22, 4, 'Eine kluge Tochter wird schon ihren Mann bekommen, aber eine schandbare bringt Kummer über ihren Vater;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 22, 5, 'dem Vater und dem Manne schafft die Freche Schande und wird von beiden verachtet. –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 22, 6, 'Wie Musik in der Trauer ist eine unzeitige Unterhaltung, aber Züchtigungen und Zurechtweisungen sind zu jeder Zeit Weisheit.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 22, 7, 'Einen Toren belehren heißt Scherben zusammenleimen: er will einen Schlafenden aus tiefem Schlummer wecken.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 22, 8, 'Zu einem Schlummernden redet, wer zu einem Toren redet; der fragt am Schluß: »Was ist denn los?« –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 22, 9, 'Um einen Toten weine, denn das Lebenslicht ist ihm ausgegangen; und über einen Toren weine, denn die Einsicht ist ihm ausgegangen. Mäßiger weine um einen Toten, denn er ist zur Ruhe gegangen; das schlechte Leben des Toren aber ist schlimmer als der Tod.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 22, 10, 'Die Trauer um einen Toten dauert sieben Tage, aber um einen Toren und Gottlosen, solange er lebt.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 22, 11, 'Mit einem Unverständigen laß dich nicht auf lange Unterredungen ein, und zu einem Einsichtslosen gehe nicht hin; nimm dich vor ihm in acht, damit du keinen Verdruß habest und du durch sein Gespei nicht besudelt werdest; meide ihm, so wirst du Ruhe finden und durch seinen Unverstand nicht in Verlegenheit geraten.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 22, 12, 'Was ist schwerer als Blei, und welch anderen Namen kann es haben als »Tor«?');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 22, 13, 'Sand, Salz und Eisenklumpen sind leichter zu tragen als ein unverständiger Mensch.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 22, 14, 'Ein Gefüge von Balken, das zu einem Hausbau verbunden ist, wird durch keine Erschütterung auseinandergerissen; ebenso wird ein Herz, das durch wohlerwogene Überzeugung gefestigt ist, zu keiner Zeit verzagt sein.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 22, 15, 'Ein Herz, auf vernünftige Überlegung festgegründet, ist wie sandige Tünche an geglätteter Mauer.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 22, 16, 'Pfahlwerk, auf einer Anhöhe befindlich, hält dem Winde gegenüber nicht stand; ebenso hält ein furchtsames Herz bei törichter Überlegung keinem Schrecken gegenüber stand.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 22, 17, 'Ein Schlag auf das Auge bringt Tränen hervor, und ein Schlag auf das Herz verursacht Schmerzgefühl.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 22, 18, 'Wer einen Stein nach Vögeln wirft, verscheucht sie, und wer seinen Freund beschimpft, löst die Freundschaft auf.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 22, 19, 'Hast du gegen deinen Freund das Schwert gezogen, so gibt die Hoffnung nicht auf, denn es ist da eine Umkehr möglich;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 22, 20, 'und hast du den Mund gegen deinen Freund aufgetan, so sei ohne Sorgen, denn es ist da noch eine Versöhnung möglich; jedoch bei Schmähungen und Hochmut, bei Verrat von Geheimnissen und hinterlistiger Nachrede: – bei solchen Vorkommnissen macht sich jeder Freund davon.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 22, 21, 'Beweise deinem Freunde gegenüber Treue, wenn er in Armut lebt, damit du auch Freude erlebest, wenn es ihm wieder wohlgeht; zur Zeit der Not harre bei ihm aus, damit, wenn er wieder zu Wohlstand kommt, du Anteil daran erlangest.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 22, 22, 'Vor dem Feuer sind Ofendampf und Rauch da; ebenso vor dem Blutvergießen Schimpfworte.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 22, 23, 'Den Freund zu beschützen schäme ich mich nicht, und ich werde mich vor ihm nicht verstecken;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 22, 24, 'und wenn mir Unglück seinetwegen widerfährt, so wird jeder, der davon hört, sich vor ihm hüten.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 22, 25, 'Stellte man mir doch eine Wache vor meinen Mund und legte man doch an meine Lippen ein geschickt angefertigtes Siegel, damit ich durch sie nicht zu Fall komme und meine Zunge mich nicht zugrunde richte!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 22, 26, '');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 22, 27, '');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 22, 28, '');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 22, 29, '');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 22, 30, '');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 22, 31, '');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 22, 32, '');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 22, 33, '');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 23, 1, 'O Herr, mein Vater und Gebieter meines Lebens, überlaß mich nicht dem Belieben meiner Lippen und laß mich nicht durch sie zu Fall kommen!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 23, 2, 'Möchte doch jemand eine Geißel für meine Gedanken bestellen und für mein Herz einen Stecken zur Züchtigung, damit sie bei meinen Verfehlungen keine Schonung übten und keine Sünden von mir zu Tage träten!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 23, 3, 'auf daß meine Verfehlungen sich nicht noch mehren und meine Sünden noch zahlreicher werden und ich angesichts meiner Widersacher zu Fall komme und mein Feind Schadenfreude über mich empfinde.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 23, 4, 'O Herr, mein Vater und du Gott meines Lebens, gib mich nicht dahin in ihr Belieben!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 23, 5, 'Hoffart der Augen gib mir nicht und laß böse Lust fern von mir bleiben!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 23, 6, 'Gier des Bauches und Wollust mögen mich nicht erfassen, und der Schamlosigkeit laß mich nicht anheimfallen!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 23, 7, 'Auf die Zucht des Mundes laßt euch hinweisen, ihr Kinder! wer sie übt, wird nicht ins Verderben geraten.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 23, 8, 'Durch feine Lippen wird der Sünder ins Unglück gebracht, und der Schmähsüchtige und der Stolze kommen durch sie zu Fall.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 23, 9, 'Ans Schwören gewöhne deinen Mund nicht, und mache es dir nicht zur Gewohnheit, den Namen des Heiligen auszusprechen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 23, 10, 'Denn wie ein Sklave, der beständig verhört wird, von den Striemen nicht loskommt, so kann auch, wer immerfort schwört und den heiligen Namen ausspricht, von Sünden nicht rein bleiben.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 23, 11, 'Ein Mensch, der viel schwört, beladet sich mit Schuld, und die Zuchtrute weicht nicht von seinem Hause; hat er sich vergangen, so liegt die Sünde auf ihm, und läßt er es unbeachtet, so versündigt er sich doppelt; und wenn er unnötig schwört, wird er nicht gerechtfertigt dastehen, sondern sein Haus wird Heimsuchungen in Fülle erfahren.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 23, 12, 'Es gibt noch eine andere Redeweise, die dem Tode gleichkommt: möge sie nicht gefunden werden im Erbteil Jakobs! Denn von den Frommen bleiben alle diese Vergehen fern, und sie lassen sich nicht in solche Sünden verstricken.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 23, 13, 'An schmutzige Ungezogenheit darfst du deinen Mund nicht gewöhnen, denn dabei gibt es Worte der Sünde.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 23, 14, 'Denke an deinen Vater und deine Mutter, wenn du inmitten der Vornehmen verkehrst; vergiß sie ja nicht in der Gesellschaft jener und erweise dich nicht als Toren durch deine Gewohnheiten, so daß du gar wünschen müßtest, nicht geboren zu sein, und den Tag deiner Geburt verfluchst.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 23, 15, 'Ein Mensch, der sich an schandbare Reden gewöhnt hat, bleibt sein ganzes Leben hindurch ungebildet.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 23, 16, 'Zwei Arten von Menschen häufen die Sünden, und die dritte zieht sich Gottes Zorn zu: die heiße Begier ist wie ein loderndes Feuer und erlischt nicht, bis sie sich völlig verzehrt hat. Ein Mensch, der mit seinem eigenen Leibe Unzucht treibt, hört nicht eher auf, als bis das Feuer ausgebrannt ist;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 23, 17, 'einem hurerischen Menschen mundet jedes Brot: er hört nicht eher auf, als bis er tot ist.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 23, 18, 'Ein Mensch, der von seinem Lager weitergeht, sagt bei sich selbst: »Wer sieht mich? Dunkel umhüllt mich, und die Wände verbergen mich, und niemand sieht mich: was sollte ich mich scheuen? Meiner Sünden wird der Höchste nicht gedenken«.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 23, 19, 'Ja, nur die Augen der Menschen sind es, vor denen er sich fürchtet, und er weiß nicht, daß die Augen des Herrn tausendmal heller sind als die Sonne, daß sie auf alle Wege der Menschen blicken und in die verborgensten Winkel hineinschauen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 23, 20, 'Alle Dinge sind ihm bekannt gewesen, ehe sie geschaffen wurden, und ebenso ist es, nachdem sie vollendet sind.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 23, 21, 'Ein solcher Mensch wird in den Straßen der Stadt seine Strafe erleiden, und wo er’s nicht vermutet, wird man ihn ergreifen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 23, 22, 'Ebenso ergeht es einer Frau, die ihren Mann verlassen hat und von einem andern einen Erben zur Welt bringt.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 23, 23, 'Denn erstens ist sie dem Gesetz des Herrn ungehorsam gewesen, und zweitens hat sie sich gegen ihren Gatten verfehlt und drittens hurerischen Ehebruch verübt und von einem fremden Manne Kinder zur Welt gebracht.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 23, 24, 'Ein solches Weib wird vor die Gemeindeversammlung geführt werden, und auch über ihre Kinder wird Heimsuchung kommen:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 23, 25, 'nicht werden ihre Kinder Wurzel schlagen und ihre Zweige keine Frucht bringen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 23, 26, 'Sie wird ihr Gedächtnis zum Fluch hinterlassen, und ihre Schande wird nie ausgetilgt werden.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 23, 27, 'Da werden dann die sie Überlebenden erkennen, daß nichts besser ist als Gottesfurcht und nichts süßer als die Beobachtung der Gebote des Herrn.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 23, 28, '');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 23, 29, '');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 23, 30, '');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 23, 31, '');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 23, 32, '');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 23, 33, '');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 23, 34, '');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 23, 35, '');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 23, 36, '');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 23, 37, '');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 24, 1, 'Die Weisheit lobt sich selbst und rühmt sich inmitten ihres Volkes;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 24, 2, 'in der Gemeinde des Höchsten tut sie ihren Mund auf und rühmt sich vor seiner Heerschar:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 24, 3, '»Ich bin aus dem Munde des Höchsten hervorgegangen und habe wie ein Nebel die Erde bedeckt;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 24, 4, 'ich nahm meinen Wohnsitz in der Höhe, und mein Thron ruhte auf einer Wolkensäule.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 24, 5, 'Das Himmelsgewölbe umwandelte ich allein und ging in der Tiefe der Fluten einher;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 24, 6, 'in den Wogen des Meeres und auf der ganzen Erde, in jedem Volk und jedem Stamm habe ich mich betätigt');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 24, 7, 'Bei diesen allen suchte ich eine Heimstätte und in wessen Erbteil ich weilen könnte.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 24, 8, 'Da gebot mir der Schöpfer des Weltalls, und er, der mich geschaffen, wies mir eine feste Wohnung an mit den Worten: ›In Jakob nimm deinen Wohnsitz und in Israel sollst du deinen Erbbesitz erhalten!‹');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 24, 9, 'Vor aller Zeit, im Anfang, hat er mich geschaffen, und bis in Ewigkeit werde ich kein Ende nehmen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 24, 10, 'In der heiligen Hütte habe ich den Dienst vor ihm versehen und ebenso in Zion einen festen Sitz erhalten;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 24, 11, 'in der geliebten Stadt hat er mir gleichermaßen einen Sitz verliehen, und in Jerusalem war mein Machtbereich.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 24, 12, 'Und ich schlug Wurzel in dem gepriesenen Volk, im Erbteil des Herrn, seinem Eigentumsvolk.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 24, 13, 'Wie eine Zeder auf dem Libanon wuchs ich empor und wie eine Zypresse auf den Bergen des Hermon;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 24, 14, 'wie eine Palme in Engeddi wuchs ich empor und wie Rosenstöcke zu Jericho, wie ein prangender Ölbaum in der Ebene, und wie eine Platane (am Wasser) wuchs ich empor.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 24, 15, 'Wie Zimt und Gewürzstrauch hauchte ich Wohlgeruch aus, und wie eine köstliche Myrrhe verbreitete ich Duft, wie Galbanum, Räucherklaue und Stakte und wie Weihrauchdampf in der Stiftshütte.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 24, 16, 'Ich breitete wie eine Terebinthe meine Zweige aus, und meine Zweige waren voller Pracht und Lieblichkeit;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 24, 17, 'ich war wie ein herrlich sprossender Weinstock, und meine Blüten brachten prächtige und reiche Frucht.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 24, 18, 'Kommt her zu mir, die ihr Verlangen nach mir tragt, und sättigt euch an meinen Früchten!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 24, 19, 'denn schon der Gedanke an mich geht über süßen Honig, und mich zu besitzen ist süßer als Honigseim.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 24, 20, 'Die von mir essen, empfinden immer neuen Hunger (nach mir), und die von mir trinken, dürsten immer weiter (nach mir).');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 24, 21, 'Wer auf mich hört, wird sich nie zu schämen brauchen, und wer in meinem Dienste sich betätigt, wird nicht sündigen«.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 24, 22, 'Dies alles gilt vom Bundesbuch Gottes des Höchsten, vom Gesetz, das Mose uns verordnet hat als Besitztum für die Gemeinden Jakobs,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 24, 23, 'das Gesetz, das da Weisheit in Fülle besitzt wie der Pison und wie der Tigris in den Tagen der Erstlingsfrüchte;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 24, 24, 'das da flutet wie der Euphrat von Einsicht und wie der Jordan in den Tagen der Ernte;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 24, 25, 'das da Belehrung hervorströmen läßt wie der Nil und wie der Gihon in den Tagen der Weinlese.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 24, 26, 'Der erste ist mit der Erforschung seiner Weisheit nicht ans Ende gelangt, und ebenso wird der letzte sie nicht ergründen;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 24, 27, 'denn reichhaltiger als das Meer sind ihre Gedanken, und ihre Einsicht ist tiefer als die große Urflut.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 24, 28, 'Ich aber – wie ein Kanal von einem Flusse ausgeht und wie eine Wasserleitung in einen Lustgarten ausläuft –,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 24, 29, 'ich dachte: »Ich will meinen Garten bewässern und meine Beete tränken«; aber siehe da: mein Kanal wurde mir zu einem Strom, und mein Strom wurde mir zu einem Meer.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 24, 30, 'So will ich denn auch fernerhin Belehrung leuchten lassen wie die Morgenröte und sie kundtun bis in weite Ferne;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 24, 31, 'auch fernerhin will ich Belehrung wie Prophetenworte ausströmen und sie den spätesten Geschlechtern hinterlassen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 24, 32, 'Ihr sollt sehen, daß ich nicht für mich allein gearbeitet habe, sondern für alle, die nach der Weisheit Verlangen tragen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 24, 33, '');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 24, 34, '');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 24, 35, '');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 24, 36, '');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 24, 37, '');
