INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 24, 40, '');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 24, 41, '');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 24, 42, '');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 24, 43, '');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 24, 44, '');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 24, 45, '');
