INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 24, 47, '');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 25, 1, 'An drei Dingen habe ich Gefallen, und sie sind lieblich vor Gott und den Menschen: Eintracht unter Brüdern und Liebe unter Freunden und daß sich Ehefrau und Mann ineinander schicken.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 25, 2, 'Drei Arten von Leuten dagegen haßt meine Seele, und ich bedaure schmerzlich, daß sie leben: der hoffärtige Arme und der lügenhafte Reiche und der ehebrecherische Greis, dem es an Verstand gebricht.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 25, 3, 'Hast du in der Jugend nicht eingesammelt, wie kannst du da in deinem Alter etwas vorfinden?');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 25, 4, 'Wie schön steht einem grauen Haupte richtiges Urteil an und den Alten, daß sie guten Rat wissen!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 25, 5, 'Wie schön steht die Weisheit den Greisen an, und angesehenen Männern Überlegung und Rat!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 25, 6, 'Die Krone der Greise ist reiche Erfahrung, und ihren Ruhm bildet die Gottesfurcht.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 25, 7, 'Neun Dinge, die mir in den Sinn kommen, preise ich in meinem Herzen, und ein zehntes will ich mit meiner Zunge rühmend hervorheben: glücklich ein Mann, der Freude an seinen Kindern erlebt, und wer bei seinen Lebzeiten den Sturz seiner Feinde zu schauen bekommt.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 25, 8, 'Glücklich, wer mit einer verständigen Frau verheiratet ist, und wer sich mit seiner Zunge nicht verfehlt, und wer nicht einem unwürdigen Herrn dienen muß!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 25, 9, 'Glücklich, wer sich Klugheit angeeignet hat und wer sie willigen Zuhörern vortragen kann!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 25, 10, 'Wie groß steht der da, welcher Weisheit erlangt hat! aber keiner steht größer da als der Gottesfürchtige.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 25, 11, 'Die Gottesfurcht geht über alles; wer sie festhält, wenn könnte der gleichgestellt werden? b [Die Furcht des Herrn ist der Anfang der Liebe zu ihm, die Treue aber der Anfang der engen Zugehörigkeit zu ihm.]');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 25, 12, 'Jede Wunde, nur keine Herzenswunde, und jede Bosheit, nur keine Weiberbosheit!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 25, 13, 'Jede Heimsuchung, nur keine Heimsuchung durch Hasser, und jede Rache, nur keine Rache von Feinden!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 25, 14, 'Kein Gift ist schlimmer als Schlangengift, und keine Wut ist heftiger als Feindeswut.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 25, 15, 'Lieber will ich mit einem Löwen und Drachen zusammenleben als mit einem boshaften Weibe in einem Hause wohnen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 25, 16, 'Die Bosheit eines Weibes entstellt ihr Aussehen und macht ihr Gesicht finster wie das eines Bären.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 25, 17, 'Im Kreise seiner Freunde setzt sich ihr Mann zu Tisch, und wenn er sie hat reden hören, seufzt er bitterlich.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 25, 18, 'Gering ist jede Schlechtigkeit im Vergleich mit der eines Weibes; das Los des Sünders treffe sie!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 25, 19, 'Wie ein sandiger Aufstieg für die Füße eines Alten, so ist ein zungenfertiges Weib für einen ruhigen Mann.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 25, 20, 'Falle nicht herein auf die Schönheit einer Frau und trage kein Verlangen nach dem Vermögen, das sie hat:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 25, 21, 'schimpfliche Knechtschaft (g) und große Schande gibt es, wenn eine Frau ihren Mann unterhält.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 25, 22, 'Ein niedergeschlagenes Herz und ein finsteres Antlitz und Herzweh bringt ein böses Weib zustande; schlaffe Hände und schlotternde Kniee schafft ein Weib, das den Ehemann nicht glücklich macht.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 25, 23, 'Von einem Weibe ist der Anfang der Sünde gekommen, und um ihretwillen müssen wir alle sterben.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 25, 24, 'Überlaß dem Wasser keinen Abfluß und einem boshaften Weibe nicht die Herrschaft;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 25, 25, 'wenn sie nicht Hand in Hand mit dir geht, so schneide sie dir vom Leibe ab.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 25, 26, '');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 25, 27, '');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 25, 28, '');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 25, 29, '');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 25, 30, '');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 25, 31, '');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 25, 32, '');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 25, 33, '');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 25, 34, '');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 26, 1, 'Glücklich zu preisen ist der Mann einer guten Frau, und die Zahl seiner Lebenstage verdoppelt sich.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 26, 2, 'Eine tüchtige Frau ist die Freude ihres Mannes, und er erreicht die Vollzahl seiner Jahre in Frieden.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 26, 3, 'Eine gute Frau ist ein gutes Los; als Glückslos wird sie den Gottesfürchtigen beschieden.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 26, 4, 'Ob reich oder arm, sein Herz ist guter Dinge und sein Angesicht zu jeder Zeit heiter.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 26, 5, 'Vor drei Dingen scheut sich mein Herz, und vor dem vierten fürchte ich mich sehr: Stadtgeklatsch und Zusammenrottung des Volkes und Verleumdung, das alles ist widerwärtiger als der Tod.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 26, 6, 'Herzeleid und Kummer verursacht eine Frau, die auf eine andere eifersüchtig ist, und eine Zungengeißel für alle, denen sie Mitteilungen macht.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 26, 7, 'Wie ein Ochsengespann, das hin und her zerrt, ist eine böse Frau; wer sie nimmt, gleicht einem, der einen Skorpion anfaßt.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 26, 8, 'Großen Zorn erregt ein trunksüchtiges Weib; ihre Schamlosigkeit kann sie nicht verbergen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 26, 9, 'Daß ein Weib Unzucht treibt, erkennt man am Aufschlag ihrer Augen und an ihren Augenwimpern.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 26, 10, 'Über eine zuchtlose Tochter halte strenge Wacht, damit sie nicht, wenn sie ein Nachlassen bemerkt, es sich zunutze mache;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 26, 11, 'ihrem schamlosen Auge gehe sorgfältig nach und wundere dich nicht, wenn sie sich gegen dich vergeht.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 26, 12, 'Wie ein durstiger Wanderer den Mund aufsperrt, und von jedem Wasser trinkt, auf das er stößt, so setzt sie sich vor jedem Pfahle nieder und öffnet ihren Köcher vor dem Pfeile.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 26, 13, 'Die Anmut der Frau ergötzt ihren Gatten, und ihre Klugheit macht seine Glieder kräftig.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 26, 14, 'Eine Gabe des Herrn ist ein schweigsames Weib, und unbezahlbar ist eine wohlerzogene Seele.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 26, 15, 'Anmut über Anmut ist eine keusche Frau, und mit nichts aufzuwägen ist eine züchtige Seele.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 26, 16, 'Wie die Sonne, die da aufgeht am hohen Gotteshimmel, so ist die Schönheit einer guten Frau ein Schmuck seines Hauses.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 26, 17, 'Wie die Lampe hell strahlt auf dem heiligen Leuchter, so die Schönheit ihres Angesichts auf hoher Gestalt.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 26, 18, 'Wie goldene Säulen auf silbernem Untersatz, so sind schöne Füße auf wohlgeformten Fersen (oder Sohlen)..1 Mein Sohn, bewahre dir die Blüte deiner Jugend gesund und gib nicht Fremden deine Kraft hin..2 Suche dir aus der ganzen Feldmark ein fruchtbares Feld zum Besitz aus und säe deinen eigenen Samen aus, im Vertrauen auf deine edle Abkunft; so werden deine Sprößlinge am Leben bleiben und im Besitz des Freimuts edler Abkunft groß wachsen..3 Eine feile Dirne wird dem Speichel gleich geachtet, eine Ehefrau aber gilt für die, welche sich mit ihr einlassen, als ein todbringender Turm..4 Ein gottloses Weib wird dem Gesetzlosen als Anteil zugeteilt, ein frommes Weib dagegen dem Gottesfürchtigen..5 Ein schamloses Weib macht sich nichts aus der Schande, aber eine schamhafte Tochter wird sich sogar vor ihrem Manne schämen..6 Ein stets lüsternes Weib wird wie ein Hund geachtet, die schamhafte aber fürchtet den Herrn..7 Ein Weib, das ihren Ehemann in Ehren hält, erscheint allen als weise; wenn sie ihn aber mißachtet, wird sie bei ihrem Hochmut allen als gottlos gelten..8 Der Mann eines guten Weibes ist glücklich zu preisen, denn die Zahl seiner Lebensjahre verdoppelt sich..9 Ein kreischendes und zungenfertiges Weib erscheint wie eine Kriegstrompete, welche die Feinde in die Flucht treibt; bei jedem Manne aber wir die Seele, die darin gleichgeartet ist, sich auf ein unruhiges Kriegstreiben gefaßt machen müssen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 26, 19, 'Über zwei Dinge ist mein Herz betrübt, und beim dritten überkommt mich der Zorn: ein Kriegsmann, der verarmt ist und Mangel leidet und wenn einsichtsvolle Männer für nichts geachtet werden; wenn sich aber jemand von der Gerechtigkeit zur Sünde hinwendet, den hält der Herr fürs Schwert bereit.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 26, 20, 'Nur mit Mühe wird ein Kaufmann vor Verfehlungen bewahrt bleiben und ein Krämer sich frei von Schuld erhalten.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 26, 21, '');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 26, 22, '');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 26, 23, '');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 26, 24, '');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 26, 25, '');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 26, 26, '');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 26, 27, '');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 26, 28, '');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 27, 1, 'Um schnöden Geldes willen sündigen viele, und wer reich werden will, wendet das Auge (vom Rechten) ab.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 27, 2, 'Wie zwischen Steinfugen ein Pflock fest eingetrieben wird, so drängt sich die Sünde zwischen Kauf und Verkauf ein.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 27, 3, 'Wenn jemand nicht mit Eifer an der Gottesfurcht festhält, wird sein Haus gar bald zerstört werden.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 27, 4, 'Beim Schütteln des Siebes bleibt der grobe Unrat zurück, ebenso die Unlauterkeit des Menschen in seiner Gesinnung.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 27, 5, 'Die Töpfergefäße muß der Ofen prüfen, und die Erprobung eines Menschen erfolgt durch die Unterredung mit ihm.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 27, 6, 'Die Art eines Baumes erweist seine Frucht, ebenso auch die Vornahme einer Unterredung die ganze Denkweise eines Menschen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 27, 7, 'Lobe also niemand, ehe du dich mit ihm besprochen hast; denn dadurch erfolgt die Erprobung der Menschen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 27, 8, 'Wenn du nach der Gerechtigkeit trachtest, wirst du sie erlangen und sie dir anlegen wie ein Prachtgewand.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 27, 9, 'Wie die Vögel sich zu ihresgleichen gesellen, so wird auch die Wahrheit zu denen kommen, die sie üben.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 27, 10, 'Wie der Löwe seiner Beute auflauert, so die Sünde denen, die Unrecht tun.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 27, 11, 'Die Rede eines Frommen ist allezeit Weisheit, der Tor aber ist veränderlich wie der Mond.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 27, 12, 'Um inmitten der Unverständigen zu weilen, nimm die richtige Zeit wahr, aber im Kreise der Verständigen weile beständig.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 27, 13, 'Das Gespräch der Toren ist greuelhaft, und ihr Lachen erfolgt bei sündhafter Ausgelassenheit.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 27, 14, 'Das Geschwätz des viel Schwörenden macht die Haare sich sträuben, und vor ihrem Gezänk hält man sich die Ohren zu.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 27, 15, 'Zu Blutvergießen führt der Streit der Übermütigen und ihre Schmähreden sind widerwärtig anzuhören.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 27, 16, 'Wer Geheimnisse verrät, bricht die Treue und findet keinen Freund mehr nach seinem Herzen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 27, 17, 'Liebe deinen Freund und laß dich von ihm als treu erfinden; hast du aber seine Geheimnisse verraten, so laufe ihm nicht mehr nach.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 27, 18, 'Denn wie jemand seinen Feind zugrunde richtet, ebenso hast du die Freundschaft mit dem anderen zugrunde gerichtet;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 27, 19, 'und wie du einen Vogel aus der Hand hast fliegen lassen, ebenso hast du deinen Freund fahren lassen und wirst ihn nicht wieder einfangen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 27, 20, 'Jage ihm nicht mehr nach, denn er hält sich fern und ist entflohen wie eine Gazelle aus dem Netz.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 27, 21, 'Denn eine Wunde läßt sich verbinden, und für Scheltworte gibt’s Versöhnung; wer aber Geheimnisse verraten hat, für den gibt’s nichts mehr zu hoffen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 27, 22, 'Wer mit den Augen zwinkert, hat Böses im Sinn, und der Kluge hält sich fern von ihm.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 27, 23, 'Dir ins Angesicht läßt er seinen Mund angenehm reden und äußert Bewunderung über deine Worte; nachher aber ändert er seine Rede und dichtet dir anstößige Äußerungen an.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 27, 24, 'Vieles hasse ich, jedoch nichts so sehr wie ihn, und auch der Herr haßt ihn.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 27, 25, 'Wer einen Stein in die Höhe wirft, wirft ihn sich selbst auf den Kopf, und ein hinterlistiger Schlag versetzt beiden Teilen Wunden.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 27, 26, 'Wer eine Grube gräbt, fällt selbst hinein, und wer eine Schlinge legt, wird in ihr gefangen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 27, 27, 'Wer Böses anstiftet: auf ihn selbst fällt es zurück, ohne daß er weiß, woher es ihm kommt.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 27, 28, 'Höhnen und Spotten geht von den Übermütigen aus, aber die Rache (oder Strafe) lauert auf sie wie ein Löwe.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 27, 29, 'In der Schlinge werden die gefangen, welche sich über den Fall der Frommen freuen, und der Schmerz verzehrt sie, ehe sie sonst hätten sterben müssen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 27, 30, 'Groll und Zorn, auch diese sind greuelhaft, und nur ein sündiger Mensch hält an ihnen fest.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 27, 31, '');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 27, 32, '');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 27, 33, '');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 28, 1, 'Wer sich rächt, wird Rache vom Herrn erleiden, der ihm seine Sünden sicher vorbehalten wird.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 28, 2, 'Vergib deinem Nächsten sein Unrecht, dann werden, wenn du darum bittest, auch dir die Sünden vergeben werden.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 28, 3, 'Ein Mensch hält den Zorn gegen einen andern fest und will doch Heilung vom Herrn fordern?!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 28, 4, 'Mit einem Menschen seinesgleichen hat er kein Erbarmen und bittet doch für seine eigenen Sünden um Nachsicht?!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 28, 5, 'Er selbst, der doch Fleisch ist, hält den Groll fest: wer wird ihm da seine Sünden vergeben?');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 28, 6, 'Denke an das Ende, und laß ab von der Feindschaft, denke an Verwesung und Tod und bleibe den Geboten treu;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 28, 7, 'denke an die Gebote und grolle dem Nächsten nicht; denke an den Bund mit dem Höchsten und vergib die Verfehlung!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 28, 8, 'Halte dich fern von Streit, so wirst du weniger sündigen, denn ein zornmütiger Mensch facht Streit an,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 28, 9, 'und ein böser Mann entzweit Freunde und stiftet Zerwürfnis unter Friedfertigen an.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 28, 10, 'Ein Feuer brennt, jenachdem es Brennstoff hat, ebenso wird auch ein Streit entbrennen, jenachdem geschürt wird; je größer die Macht eines Menschen ist, desto stärker ist sein Groll, und je reicher er ist, desto höher läßt er seinen Zorn aufsteigen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 28, 11, 'Übereilter Zwist facht ein Feuer an, und ein übereilter Streit führt zu Blutvergießen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 28, 12, 'Wenn du einen Funken anbläst, so flammt er auf, und wenn du auf ihn speist, erlischt er, und beides kommt doch aus deinem Munde.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 28, 13, 'Den Ohrenbläser und den Doppelzüngigen verfluche, denn viele friedliebende Leute haben sie ins Verderben gebracht.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 28, 14, 'Eine verleumderische Zunge hat viele gestürzt und sie von Volk zu Volk getrieben, auch feste Städte zerstört und die Paläste von Machthabern niedergerissen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 28, 15, 'Eine verleumderische Zunge hat treffliche Frauen aus ihren Häusern gestoßen und sie des Ertrags ihrer Arbeit beraubt.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 28, 16, 'Wer auf sie hört, findet keine Ruhe und kann nicht in Frieden wohnen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 28, 17, 'Der Schlag der Geißel bringt Striemen hervor, aber der Schlag der Zunge zerschmettert die Gebeine.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 28, 18, 'Viele sind durch die Schneide des Schwertes gefallen, aber nicht so viele, wie durch die Zunge gefallen sind.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 28, 19, 'Wohl dem, der vor ihr geborgen bleibt und ihre Wut nicht an sich erfährt, der nicht an ihrem Joche zieht und mit ihren Banden nicht gefesselt wird!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 28, 20, 'denn ihr Joch ist ein eisernes Joch, und ihr Fesseln sind eherne Fesseln.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 28, 21, 'Der Tod durch sie ist ein schrecklicher Tod, und besser ist die Unterwelt als sie.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 28, 22, 'Über die Frommen hat sie keine Gewalt, und von ihrer Feuerflamme werden sie nicht versengt;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 28, 23, 'aber die den Herrn verlassen, fallen in sie hinein; an ihnen brennt sie, ohne zu erlöschen; sie wird auf sie losgelassen wie ein Löwe und wütet unter ihnen wie ein Panther.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 28, 24, 'Wohlan! umzäune dein Grundstück mit Dornen und lege dein Silber und Gold unter Verschluß;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 28, 25, 'aber auch für deine Worte bringe Waage und Gewichte in Anwendung und bringe auch an deinem Munde Tür und Riegel an.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 28, 26, 'Gib acht, daß du durch sie dich nicht verfehlest und zu Falle kommest vor den Augen dessen, der darauf lauert.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 28, 27, '');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 28, 28, '');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 28, 29, '');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 28, 30, '');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 29, 1, 'Wer Barmherzigkeit übt, leiht seinem Nächsten, und wer ihn mit seinen Mitteln unterstützt, beobachtet die Gebote.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 29, 2, 'Leihe dem Nächsten, wenn er in Not ist, und gibt du es deinem Nächsten zu rechter Zeit zurück.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 29, 3, 'Halte an deiner Zusage fest und beweise dich ihm als zuverlässig, so wirst du allezeit zur Verfügung haben, was du bedarfst.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 29, 4, 'Viele betrachten ein Darlehen als einen guten Fund und machen denen Verdruß, die ihnen geholfen haben;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 29, 5, 'bis er’s erhält, küßt er ihm die Hände und redet gar demütig um des Nächsten Geld; aber zur Zeit der Rückzahlung zieht er die Frist hin, gibt kummervolle Reden zur Antwort und klagt über schlechte Zeiten.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 29, 6, 'Wenn er zahlen kann, bringt er kaum die Hälfte wieder und rechnet es jenem noch als glücklichen Fund an; wenn aber nicht, so bringt er ihn um sein Geld und gewinnt obendrein an ihm einen Feind; mit Flüchen und Schimpfworten vergilt er ihm und zahlt ihm Schmach statt rühmlicher Anerkennung zurück.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 29, 7, 'So halten sich denn viele wegen solcher Schlechtigkeit zurück, sie fürchten ohne ihre Schuld Verluste zu erleiden.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 29, 8, 'Trotzdem habe mit dem Notleidenden Geduld und laß ihn nicht lange auf deine Mildtätigkeit warten;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 29, 9, 'um des Gebotes willen nimm dich des Armen an und laß ihn wegen seiner Bedürftigkeit nicht mit leeren Händen von dir gehen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 29, 10, 'Verliere immerhin dein Geld um eines Bruders oder Freundes willen und laß es nicht unter dem Steine rosten, so daß es wertlos wird.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 29, 11, 'Lege dir einen Schatz an nach den Geboten des Höchsten, der wird dir mehr Gewinn bringen als das Gold.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 29, 12, 'Verschließe die Mittel zu Almosen in deinen Vorratskammern, das wird dich aus aller Bedrängnis erretten;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 29, 13, 'besser als ein starker Schild und ein wuchtiger Speer wird es gegen den Feind für dich kämpfen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 29, 14, 'Ein braver Mann leistet Bürgschaft für seinen Nächsten, nur wer die Scham verloren hat, läßt ihn im Stich.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 29, 15, 'Den Liebesdienst eines Bürgen vergiß nicht; er hat sich ja selbst für dich geopfert.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 29, 16, 'Nur ein verworfener Mensch bringt den Bürgen um sein Vermögen, und nur ein durch und durch Undankbarer läßt den im Stich, der ihn gerettet hat.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 29, 17, 'Bürgschaft hat viele Wohlhabende zugrunde gerichtet und sie hin- und hergeschleudert wie die Meereswogen;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 29, 18, 'vermögende Männer hat sie von Haus und Hof getrieben, so daß sie unter fremden Völkern umherirren mußten.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 29, 19, 'Ein schlechter Mensch, der sich in Bürgschaft stürzt und ungerechtem Gewinn nachjagt, verfällt dem Gericht.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 29, 20, 'Nimm dich des Nächsten nach deinem Vermögen an, aber sieh dich vor, daß du dabei nicht selbst hineinfällst.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 29, 21, 'Die wichtigsten Lebensbedürfnisse sind Wasser und Brot, dazu Kleidung und Wohnung, um die Blöße zu bedecken.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 29, 22, 'Besser das Leben des Armen unter dem Bretterdach als köstliche Leckerbissen in fremden Häusern.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 29, 23, 'Bei kleinem und bei großem Besitz laß dir genügen, so wirst du nicht die Schmähung zu hören bekommen, daß du ein Fremder seist.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 29, 24, 'Ein schlimmes Leben ist’s, von Haus zu Haus zu ziehen; und wo du fremd bist, darfst du den Mund nicht auftun.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 29, 25, 'Du wirst ihnen zu essen und zu trinken geben, ohne Dank zu ernten, und wirst zu alledem noch bittere Worte zu hören bekommen:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 29, 26, '»Komm her, Fremdling, decke den Tisch, und wenn du etwas hast, so gib mir zu essen!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 29, 27, '»Zieh ab, Fremdling, mache dem Höherstehenden Platz! Mein Bruder ist als Gast bei mir eingekehrt: ich brauche das Haus«.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 29, 28, 'Hart ist solches für einen verständigen Mann: das Schelten des Hausherrn und das Schimpfen des Gläubigers.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 29, 29, '');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 29, 30, '');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 29, 31, '');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 29, 32, '');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 29, 33, '');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 29, 34, '');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 29, 35, '');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 30, 1, 'Wer seinen Sohn lieb hat, läßt ihn immerdar die Rute fühlen, damit er zuletzt Freude an ihm erlebe.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 30, 2, 'Wer seinen Sohn in Zucht hält, wird Freude an ihm haben und inmitten der Bekannten sich seiner rühmen können.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 30, 3, 'Wer seinem Sohn Belehrung erteilt, macht seinen Feind eifersüchtig und kann vor seinen Freunden über ihn frohlocken.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 30, 4, 'Stirbt sein Vater, so ist’s, als wäre er nicht gestorben, denn einen ihm Ähnlichen läßt er zurück;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 30, 5, 'solange er lebt, sieht er ihn mit Freuden an und bei seinem Tode tritt keine bange Sorge ein.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 30, 6, 'Den Feinden gegenüber hinterläßt er einen Rächer und seinen Freunden einen, der ihre Liebe vergilt.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 30, 7, 'Wer seinen Sohn verzärtelt, verbindet ihm die Wunden, und bei jedem Schrei gerät sein Herz in Angst.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 30, 8, 'Wie ein ungebändigtes Pferd störrisch wird, so wird ein Sohn, dem man die Zügel schießen läßt, widerspenstig.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 30, 9, 'Herze deinen Sohn, so wird er dich in Schrecken setzen, scherze mit ihm, so wird er dir Kummer bereiten.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 30, 10, 'Lache nicht mit ihm, damit du später nicht Schmerzen mit ihm zu leiden brauchst und schließlich mit den Zähnen knirschen mußt.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 30, 11, 'Gewähre ihm keine Freiheit in seiner Jugend und laß seine Verfehlungen nicht unbeachtet;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 30, 12, 'beuge ihm den Nacken in seiner Jugendzeit und bleue ihm den Rücken, solange er noch klein ist, damit er nicht störrisch und dir ungehorsam werde und dir Seelenkummer erwachse.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 30, 13, 'Halte deinen Sohn in Zucht und mache dir mit ihm zu schaffen, damit du nicht durch seine Torheit (g) Kummer erlebst (h).');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 30, 14, 'Besser ein Armer, der gesund und von kräftiger Leibesbeschaffenheit ist, als ein Reicher, dessen Körper mit Krankheit behaftet ist.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 30, 15, 'Gesundheit und Wohlbefinden ist besser als alles Gold, und ein kräftiger Leib besser als unermeßliches Vermögen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 30, 16, 'Kein Reichtum ist besser als leibliche Gesundheit, und kein Gut (g) geht über volles Wohlbehagen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 30, 17, 'Besser ist der Tod als ein qualvolles Leben und besser ewige Ruhe als immerwährende Krankheit.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 30, 18, 'Leckerbissen, einem verschlossenen Munde reichlich dargeboten, sind wie kostbare Speisen, die man auf ein Grab gestellt hat.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 30, 19, 'Was nützt das Opfer einem Götzenbilde? Es kann ja weder essen noch riechen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 30, 20, 'So ist es auch mit dem, der vom Herrn heimgesucht, d.h. mit Geld und Gut gesegnet) wird: er sieht’s mit den Augen und seufzt gleichwie ein Entmannter, der eine Jungfrau umarmt und seufzt.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 30, 21, 'Gib dich nicht dem Trübsinn hin und plage dich nicht mit sorgenvollen Gedanken.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 30, 22, 'Frohsinn im Herzen ist Leben für den Menschen, und die fröhliche Stimmung eines Mannes verlängert seine Lebenstage.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 30, 23, 'Rede deiner Seele zu (g) und sprich deinem Herzen Mut ein und halte Trübsinn fern von dir; denn schon viele hat die Traurigkeit ums Leben gebracht, und es wohnt kein Nutzen in ihr.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 30, 24, 'Neid und Zorn verkürzen die Tage, und Sorgen führen das Greisenalter vor der Zeit herbei.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 30, 25, 'Ein heiteres und fröhliches Herz wird sich bei Leckerbissen an die ihm zusagenden Speisen halten.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 30, 26, '');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 30, 27, '');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 31, 1, 'Die Schlaflosigkeit des Reichen (g) macht sein Fleisch schwinden, und seine Sorgen verscheuchen den Schlaf.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 31, 2, 'Sorgenvolles Wachen hält den Schlummer fern und macht wie eine schwere Krankheit den Schlaf unmöglich.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 31, 3, 'Der Reiche müht sich ab bei der Ansammlung von Vermögen, und wenn er ausruht, sättigt er sich an seinen Genüssen (oder Vergnügungen);');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 31, 4, 'der Arme dagegen bei kümmerlichem Lebensunterhalt, und wenn er ausruht, so leidet er Mangel.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 31, 5, 'Wer das Gold liebt, bleibt nicht schuldlos, und wer dem Gelde nachjagt, gerät dadurch in Sünden (g).');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 31, 6, 'Viele sind dem Untergang anheimgefallen aus Liebe zum Golde, und plötzlich stand das Verderben vor ihnen;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 31, 7, 'ein Stück Holz, über das man fällt, ist es für die Toren (g), und jeder Unverständige läßt sich dadurch fangen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 31, 8, 'Glücklich zu preisen ist der Reiche, der untadelig erfunden wird und hinter dem Golde nicht hergeht.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 31, 9, 'Wo ist ein solcher, daß wir ihn glücklich preisen? Denn Wundertaten hat er in seinem Volke vollbracht.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 31, 10, 'Wer ist durch den Besitz von Gold versucht worden und bis ans Ende unsträflich geblieben? es soll ihm zum Ruhm gereichen! Wer konnte das Gesetz übertreten und ließ sich doch keine Übertretung zu schulden kommen? wer konnte Böses tun und tat es doch nicht?');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 31, 11, 'Einem solchen ist sein Glück gesichert, und seine Gerechtigkeit preist die Gemeinde.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 31, 12, 'Wenn du an der Tafel eines Großen sitzest, so sperre an ihr nicht den Rachen auf und sage nicht: »Ei, da stehen ja viele Sachen aufgetragen!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 31, 13, 'Bedenke wohl, daß ein mißgünstiges Auge etwas Schlimmes ist: was ist mißgünstiger geschaffen als das Auge? Darum vergießt es Tränen über das ganze Gesicht herab.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 31, 14, 'Wohin der andere blickt, dahin strecke deine Hand nicht aus, damit du nicht zugleich mit ihm in der Schüssel zusammentreffest.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 31, 15, 'Beurteile die Wünsche des anderen von deinem eigenen Standpunkt aus und denke nach bei allem, was du tust (h).');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 31, 16, 'Iß, wie ein Mensch soll, das, was man dir vorgesetzt hat, und schmatze nicht beim Kauen, damit du keinen Anstoß erregest.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 31, 17, 'Höre mit Rücksicht auf den Anstand zuerst auf und sei nicht unersättlich, damit du nicht Ärgernis gebest.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 31, 18, 'Und wenn du inmitten vieler sitzest, so strecke deine Hand nicht früher aus als jene.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 31, 19, 'Wie wenig (Speise und Trank) genügt einem wohlerzogenen Menschen! und er braucht auf seinem Lager nicht zu stöhnen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 31, 20, 'Gesunder Schlaf stellt sich ein, wenn der Magen nicht zu voll ist; man steht morgens auf und hat einen klaren Kopf; Beschwerde der Schlaflosigkeit und des Erbrechens (h) und Leibschmerzen stellen sich bei einem unersättlichen Menschen ein.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 31, 21, 'Hast du dich aber beim Genuß der Gerichte übernommen, so stehe auf und geh umher, so wirst du wieder zur Ruhe kommen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 31, 22, 'Höre auf mich, mein Sohn, und schlage meine Worte nicht in den Wind! Du wirst schließlich finden, daß ich recht habe. Bei allem, was du tust, sei mäßig (g), so wird dich keinerlei Krankheit befallen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 31, 23, 'Bei wem die Tafel glänzend besetzt ist, den preisen alle Lippen, und das Rühmen seiner Anständigkeit tritt zuverlässig ein;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 31, 24, 'wer aber bei der Bewirtung knauserig ist, über den murrt die ganze Stadt, und der Ruf von seiner Knauserei tritt entschieden ein.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 31, 25, 'Beim Weintrinken suche kein Held zu sein, denn schon viele hat der Wein zugrunde gerichtet.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 31, 26, 'Wie der Ofen den Stahl erprobt, den man eingetaucht hat, so erprobt der Wein die Herzen, wenn Übermütige im Streit liegen (h).');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 31, 27, 'Ein Lebenswasser (g) ist der Wein für den Menschen, wenn man ihn mit Maßen trinkt. Was ist das Leben für den, der den Wein entbehren muß? Ja, er ist den Menschen zum Frohsinn geschaffen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 31, 28, 'Des Herzens Freude und der Seele Lust ist der Wein, wenn man ihn zu rechter Zeit mäßig trinkt;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 31, 29, 'aber Herzeleid (h) schafft der Wein, wenn er genossen wird bei Streit und im Zorn (g).');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 31, 30, 'Trunkenheit steigert die Wut des Unvernünftigen zu anstößigem Tun (h), schwächt die Körperkraft und fügt auch noch Wunden hinzu.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 31, 31, 'Beim Weingelage stelle den Nächsten nicht zur Rede und behandle ihn nicht geringschätzig in seiner Fröhlichkeit; sprich kein schmähendes Wort zu ihm und rege ihn nicht auf durch eine Schuldforderung.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 31, 32, '');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 31, 33, '');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 31, 34, '');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 31, 35, '');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 31, 36, '');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 31, 37, '');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 31, 38, '');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 31, 39, '');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 31, 40, '');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 32, 1, 'Macht man dich zum Trinkwart, so überhebe dich nicht, benimm dich unter ihnen wie einer ihresgleichen; sorge für sie, und dann erst setze dich.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 32, 2, 'Bist du allen deinen Obliegenheiten nachgekommen, dann laß dich nieder, damit du deine Freude an ihnen hast und als Lohn für dein treffliches Verhalten den Kranz erhältst.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 32, 3, 'Rede, du Alter, denn das kommt dir zu, mit gründlicher Sachkenntnis, doch hindere den Gesang (oder die Musik) nicht!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 32, 4, 'Wo es Gesang (oder Musik) zu hören gibt, da trage keine lange Rede vor und bringe deine Weisheit nicht zur Unzeit an.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 32, 5, 'Wie ein Siegelring von Karfunkel an goldener Halskette ist ein kunstgerechtes Konzert beim Weingelage;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 32, 6, 'ein Siegelring von Smaragd in goldener Einfassung ist melodischer Gesang bei lieblichem Wein.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 32, 7, 'Rede, du Jüngling, wenn’s durchaus nötig ist, aber nur, wenn man zwei- oder dreimal dich auffordert.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 32, 8, 'Fasse dich kurz, sage viel mit wenigen Worten; sei wie einer, der’s versteht und doch schweigen kann.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 32, 9, 'Unter Vornehmen stelle dich ihnen nicht gleich (h) und unter Greisen (g) schwatze nicht viel.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 32, 10, 'Wie der Blitz dem Donner vorauseilt, so geht vor dem Bescheidenen die Gunst einher.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 32, 11, 'Stehe beizeiten auf und halte dich nicht zum Nachtrab; begib dich schnell nach Hause und sei nicht leichtsinnig.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 32, 12, 'Dort sei vergnügt und führe deine Einfälle aus, doch in der Furcht Gottes und nicht in Unverstand (g);');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 32, 13, 'und außerdem preise deinen Schöpfer, der dich mit seinen Gütern überreich labt.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 32, 14, 'Wer den Herrn sucht (g), erhält Belehrung (oder Unterweisung), und die eifrig nach ihm trachten, erlangen sein Wohlgefallen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 32, 15, 'Wer das Gesetz erforscht, wird mit ihm ganz erfüllt; wer aber heuchelt, kommt an ihm zu Fall.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 32, 16, 'Die den Herrn fürchten, verstehen das Recht und lassen gerechte Aussprüche wie ein Licht leuchten (h).');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 32, 17, 'Ein sündiger Mensch lehnt die Belehrung ab und macht eine ihm genehme Auslegung ausfindig.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 32, 18, 'Ein Mann von Einsicht läßt die Ansicht eines Fremden nicht unbeachtet, aber der Hochmütige fügt sich keiner Rücksichtnahme, und nachdem er für sich allein gehandelt hat, ohne sich raten zu lassen, wird er seines Unverstandes überführt.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 32, 19, 'Ohne Rat tue nichts, so wirst du nach der Tat nichts zu bereuen haben.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 32, 20, 'Gehe nicht auf einem Wege, der Hindernisse darbietet, damit du nicht über Steine stolperst (h).');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 32, 21, 'Traue keinem Wege, der frei von Anstoß ist, und so sei auch vor deinen Kindern auf der Hut (h).');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 32, 22, 'Bei allem, was du tust, achte auf deine Seele (oder setze dein Vertrauen auf dich selbst), denn darin besteht die Beobachtung der Gebote (Gottes).');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 32, 23, 'Wer sein Vertrauen auf das Gesetz setzt, der bewahrt seine Seele (g), und wer auf den Herrn vertraut, wird nicht zu Schaden kommen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 32, 24, '');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 32, 25, '');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 32, 26, '');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 32, 27, '');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 32, 28, '');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 33, 1, 'Den Gottesfürchtigen trifft kein Übel, sondern in der Heimsuchung reißt der Herr ihn wieder heraus.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 33, 2, 'Nie wird weise, wer das Gesetz haßt (g), und er wird umhergeworfen (g) wie ein Schiff im Wirbelsturm.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 33, 3, 'Ein verständiger Mensch setzt sein Vertrauen auf das Wort Gottes, und das Gesetz ist für ihn zuverlässig wie eine Frage an das göttliche Orakel.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 33, 4, 'Bereite dich auf deine Rede vor und dann laß dich hören, nimm dein Wissen zusammen und dann antworte.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 33, 5, 'Wie ein Wagenrad ist das Innere des Toren und wie eine sich drehende Wagenachse sein Denken.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 33, 6, 'Ein geiler Hengst ist wie ein spottsüchtiger Freund; mag auf ihm sitzen, wer da will: – er wiehert.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 33, 7, 'Warum ragt mancher Tag vor dem andern hervor, obgleich doch alles Tageslicht im Jahre von derselben Sonne kommt?');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 33, 8, 'Durch die Weisheit Gottes sind sie unterschiedlich gestaltet, und er hat die Zeiten und Feste verschieden gemacht;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 33, 9, 'einige von ihnen hat er erhöht und geheiligt, während er manche von ihnen unter die Zahl der Alltage gesetzt hat.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 33, 10, 'Auch die Menschen bestehen allesamt aus Staub, und aus Erde wurde auch Adam erschaffen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 33, 11, 'Auf Grund seiner großen Weisheit hat der Herr Unterschiede zwischen ihnen gemacht und ihnen mannigfaltige Geschicke zugewiesen;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 33, 12, 'manche von ihnen hat er gesegnet und ausgezeichnet, ja einige von ihnen geheiligt und nahe zu sich gebracht; aber andere von ihnen hat er verflucht und erniedrigt und sie von ihrer Stelle hinabgestürzt.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 33, 13, 'Wie der Ton in der Gewalt des Töpfers ist, so daß seine Gestaltung ganz von seinem Belieben abhängt, so stehen die Menschen in der Gewalt ihres Schöpfers, so daß er ihnen nach seiner Entscheidung zuteilt.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 33, 14, 'Gegenüber dem Bösen steht das Gute und gegenüber dem Tode das Leben; so steht auch der Fromme dem Sünder gegenüber.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 33, 15, 'Und ebenso blicke auf alle Werke des Höchsten: immer sind es zwei und zwei, eins dem andern gegenüber.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 33, 16, 'Ich nun habe als ein Letzter rastlos gestrebt,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 33, 17, 'wie einer, der hinter den Weingärtnern her Nachlese hält; aber durch den Segen des Herrn bin ich vorangekommen und habe wie ein Weingärtner meine Kelter gefüllt.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 33, 18, 'Erkennet, daß ich nicht für mich allein gearbeitet habe, sondern für alle, die Belehrung suchen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 33, 19, 'Hört auf mich, ihr Häupter des Volks, und ihr Leiter der Gemeinde, merkt auf!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 33, 20, 'Dem Sohne und Weibe, dem Bruder und Freunde räume keine Gewalt über dich ein, solange du lebst; auch übergib keinem andern dein Vermögen, damit es dich nicht reue und du darum betteln mußt.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 33, 21, 'Solange du lebst und ein Atem in dir ist, gib keinem andern Menschen Gewalt über dich;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 33, 22, 'denn es ist besser, daß deine Kinder dich bitten, als daß du auf die Hände deiner Söhne blicken mußt.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 33, 23, 'Bei allem, was du unternimmst, behalte die Oberhand, damit du keinen Flecken auf deine Ehre fallen läßt.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 33, 24, 'Erst am Tage, wo es mit deinem Leben zu Ende geht, und in der Todesstunde verteile dein Erbe.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 33, 25, 'Wie Futter und Stock und Last dem Esel zukommen, so Brot und strenge Zucht und Arbeit dem Knecht.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 33, 26, 'Laß den Knecht für dich arbeiten, so wirst du Ruhe finden; laß seine Hände lässig sein, so wird er nach der Freiheit verlangen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 33, 27, 'Wie Joch und Riemen den Nacken (des Zugtieres) beugen, so gehören sich für einen boshaften Knecht Martern und Schläge.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 33, 28, 'Lege ihm reichliche Arbeit auf, damit er nicht müßig gehe; denn der Müßiggang lehrt viel Böses.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 33, 29, 'Stelle ihn zur Arbeit an, wie’s ihm zukommt, und wenn er ungehorsam ist, so lege ihm schwere Fesseln an;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 33, 30, 'aber überschreite das Maß bei keinem Menschen, und ohne daß du das Recht dazu hast, tue überhaupt nichts.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 33, 31, 'Hast du einen Knecht, so halte ihn wie dich selbst; denn du hast ihn mit Blut erworben.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 33, 32, 'Hast du einen Knecht, so behandle ihn wie einen Bruder, dann wirst du ihn an dich fesseln, als wäre es dein eigenes Leben. Wenn du ihn schlecht behandelst und er sich auf- und davonmacht: auf welchem Wege willst du ihn suchen?');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 34, 1, 'Eitle und trügerische Hoffnungen hegt der unverständige Mann, und Träume versetzen die Toren in Aufregung.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 34, 2, 'Wie einer, der nach dem Schatten greift und den Wind hascht, so ist der, welcher sich auf Träume verläßt.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 34, 3, 'Nur ein Spiegelbild ist das Traumgesicht, wie das Abbild des Antlitzes gegenüber dem Antlitz selbst.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 34, 4, 'Was kann vom Unreinen für rein erklärt werden? und welche Wahrheit kann von der Lüge kommen?');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 34, 5, 'Wahrsagungen, Zeichendeutungen und Träume sind nichtige Dinge, und wie bei einem Weibe in Kindesnöten phantasiert der Geist.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 34, 6, 'Sind sie nicht vom Höchsten gesandt zur Heimsuchung, so laß dein Herz nicht auf sie achten;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 34, 7, 'denn viele haben die Träume schon irregeführt, und gar mancher, der seine Hoffnung auf sie setzte, hat sich getäuscht gesehen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 34, 8, 'Ohne zu trügen, geht das Gesetz in Erfüllung, und die Weisheit gelangt durch einen zuverlässigen Mund zur Vollendung.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 34, 9, 'Ein unterrichteter Mann weiß viel, und der Vielerfahrene legt Einsicht an den Tag.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 34, 10, 'Wer keine Erfahrungen gemacht hat, weiß wenig; wer aber in der Welt umhergekommen ist, eignet sich viel Klugheit an.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 34, 11, 'Vieles habe ich auf meinen Reisen gesehen, und meine Einsicht ist größer als ich sagen kann.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 34, 12, 'Oftmals bin ich in Todesgefahr geraten, habe aber diesetwegen Rettung gefunden.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 34, 13, 'Der Geist, der Gottesfürchtigen bleibt am Leben, denn ihre Hoffnung beruht auf dem, der sie rettet.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 34, 14, 'Wer den Herrn fürchtet, braucht nichts zu fürchten und nicht zu verzagen, denn er ist seine Hoffnung.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 34, 15, 'Glücklich zu preisen ist die Seele des Gottesfürchtigen: auf wen vertraut er, und wer ist seine Stütze?');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 34, 16, 'Die Augen des Herrn ruhen auf denen, die ihn lieben; ein mächtiger Schirm und eine starke Stütze ist er, eine Schutzwehr gegen den Glutwind und eine Schutzwehr gegen die Mittagshitze, eine Hut vor dem Straucheln und eine Hilfe gegen das Fallen;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 34, 17, 'er hebt den Mut und macht die Augen hell, verleiht Heilung, Leben und Segen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 34, 18, 'Ein Opfer von ungerechtem Gut ist eine Gabe, die Gottes spottet, und die Spottgaben der Gottlosen sind nicht wohlgefällig.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 34, 19, 'Kein Wohlgefallen hat der Höchste an den Darbringungen der Gottlosen, und nicht um der Menge der Opfer willen vergibt er Sünden.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 34, 20, 'Wie einer, der den Sohn vor den Augen des Vaters schlachtet, ist der, welcher ein Opfer darbringt vom Gute der Armen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 34, 21, 'Ein kärgliches Brot ist der Lebensunterhalt der Armen, wer es ihnen raubt, ist ein Blutmensch;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 34, 22, 'den Nächsten mordet, wer ihm den Lebensunterhalt entzieht, und Blut vergießt, wer dem Lohnarbeiter den Lohn vorenthält.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 34, 23, 'Der eine baut auf, und der andere reißt nieder: welchen Gewinn haben sie davon als die Mühe?');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 34, 24, 'Der eine betet (oder segnet) und der andere flucht: auf wessen Stimme soll der Allherr hören?');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 34, 25, 'Wer sich nach Berührung einer Leiche wäscht und sie dann wieder berührt: welchen Nutzen hat der von seinem Waschen?');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 34, 26, 'Ebenso steht’s mit einem Menschen, der wegen seiner Sünden fastet und dann wieder hingeht und dasselbe tut: wer wird sein Gebet erhören, und welchen Nutzen hat er von seiner Kasteiung?');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 34, 27, '');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 34, 28, '');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 34, 29, '');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 34, 30, '');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 34, 31, '');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 35, 1, 'Wer das Gesetz beobachtet, bringt reichliche Opfergaben dar; ein Friedensopfer bringt dar, wer auf die Gebote achtet.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 35, 2, 'Wer sich dankbar beweist, bringt ein Speisopfer dar, und wer Mildtätigkeit übt, opfert ein Lobopfer.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 35, 3, 'Eine dem Herrn wohlgefällige Gabe ist es, wenn man vom Bösen absteht, und Versöhnung erlangt man, wenn man sich von der Ungerechtigkeit fernhält.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 35, 4, 'Erscheine vor dem Herrn nicht mit leeren Händen;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 35, 5, 'denn alles dieses muß geschehen, weil das Gesetz es gebietet.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 35, 6, 'Das Opfer des Gerechten macht den Altar fett, und sein Wohlgeruch steigt zum Höchsten empor;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 35, 7, 'das Schlachtopfer eines gerechten Mannes ist wohlgefällig, und das Andenken daran gerät nicht in Vergessenheit.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 35, 8, 'Mit gütigem Auge ehre den Herrn und laß die Erstlinge deiner Hände nicht kärglich ausfallen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 35, 9, 'Bei jeglicher Gabe zeige ein freundliches Gesicht und weihe den Zehnten mit frohem Sinn.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 35, 10, 'Gib dem Höchsten ebenso reichlich, wie er dir gegeben hat, und mit gütigem Auge, jenachdem deine Hand erworben hat;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 35, 11, 'denn er ist ein Gott, der Wiedervergeltung übt, und wird es dir siebenfältig erstatten.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 35, 12, 'Suche den Herrn durch deine Gabe nicht zu bestechen, denn er nimmt nichts an, und verlaß dich auf kein ungerechtes Opfer; denn der Herr sitzt zu Gericht, und bei ihm gibt es kein Ansehen der Person.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 35, 13, 'Er nimmt nicht Partei gegen den Armen, und das Gebet dessen, dem Unrecht geschehen ist, findet Gehör bei ihm;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 35, 14, 'nicht läßt er das Flehen der Waise unbeachtet, noch die Witwe, wenn sie ihre Klage ausschüttet.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 35, 15, 'Fließen nicht die Tränen der Witwe über die Wange hinab, und richtet sich ihr Hilferuf nicht gegen den, der sie hervorgepreßt hat?');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 35, 16, 'Wer dem Herrn wohlgefällig dient, wird angenommen, und sein Gebet dringt bis zu den Wolken empor.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 35, 17, 'Das Gebet des Elenden dringt durch die Wolken, und nicht beruhigt es sich, bis es (bei Gott) angelangt ist, und es gibt sich nicht zufrieden, bis der Höchste darauf achtet und gerecht richtet und Recht schafft.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 35, 18, 'Und der Herr wird nicht auf sich warten lassen und nicht Langmut gegen die Erbarmungslosen üben, bis er ihnen die Lenden zerschlagen und den Stolzen (g) mit Rache vergolten, bis er die Rotte der Gewalttätigen vernichtet und die Herrscherstäbe der Gottlosen zerbrochen hat.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 35, 19, 'bis er den Menschen nach ihrem Tun vergolten und den Werken der Menschen nach ihren Absichten gelohnt hat, bis er seinem Volke Recht schafft und es durch sein Erbarmen erfreut.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 35, 20, 'Köstlich ist sein Erbarmen zur Zeit der Bedrängnis, wie Regenwolken zur Zeit der Dürre.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 35, 21, '');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 35, 22, '');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 35, 23, '');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 35, 24, '');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 35, 25, '');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 35, 26, '');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 36, 1, 'Erbarme dich unser, o Herr, du Gott des Alls, und blicke auf uns her');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 36, 2, 'und schleudre deinen Schrecken auf alle Heiden!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 36, 3, 'Erhebe deine Hand gegen die fremden Völker, damit sie deine Macht erkennen!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 36, 4, 'Wie du dich einst vor ihren Augen an uns als der Heilige erwiesen hast, so erweise dich jetzt vor unsern Augen an ihnen als der Mächtige,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 36, 5, 'damit sie erkennen, wie wir es erkannt haben, daß es keinen Gott außer dir gibt, o Herr.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 36, 6, 'Erneuere die Zeichen und wiederhole die Wunder, verherrliche deine Hand und deinen rechten Arm!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 36, 7, 'Laß deinen Grimm erwachen und schütte deinen Zorn aus, vertilge den Widersacher und zermalme den Feind!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 36, 8, 'Beschleunige die Zeit und sei deines Schwures eingedenk, damit deine Großtaten laut verkündigt werden!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 36, 9, 'Vom Feuer deines Zornes müsse verzehrt werden, wer sich zu retten sucht, und die, welche dein Volk mißhandeln, müssen den Untergang finden!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 36, 10, 'Zerschmettere das Haupt der Fürsten unserer Feinde, das da sagt: »Neben mir gibt es keinen andern!« (g).');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 36, 11, 'Vereinige alle Stämme Jakobs wieder und setze sie wieder in ihren Erbbesitz ein, wie es im Anfang war.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 36, 12, 'Erbarme dich des Volkes, o Herr, das nach deinem Namen benannt ist, Israels, das du dem Erstgeborenen gleich geachtet hast!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 36, 13, 'Habe Mitleid mit der Stadt deines heiligen Tempels, mit Jerusalem, der Stätte deiner Wohnung!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 36, 14, 'Laß an Zion deine Verheißungen vollzählig in Erfüllung gehen und deine Herrlichkeit an deinem Volke reichlich zu Tage treten.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 36, 15, 'Lege Zeugnis ab für das in der Vorzeit von dir Geschaffene und mache die Weissagungen wahr, die in deinem Namen ergangen sind!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 36, 16, 'Gib den Lohn denen, die auf dich harren, damit deine Propheten als zuverlässig erfunden werden.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 36, 17, 'Erhöre, o Herr, das Gebet deiner Knechte (g) entsprechend dem Segen Aarons über dein Volk,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 36, 18, 'damit alle Bewohner der Erde (h) erkennen, daß du der Herr bist, der ewige Gott. b Allerlei Speise verzehrt der Magen, aber die eine Speise ist besser (oder angenehmer) als die andere.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 36, 19, 'Wie der Gaumen Gerichte von Wildbret herausschmeckt, so erkennt ein verständiger Geist lügnerische Worte.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 36, 20, 'Ein arglistiges Herz bereitet Kummer, aber ein vielerfahrener Mann zahlt’s ihm heim.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 36, 21, 'Ein Weib muß jeden Mann annehmen, es ist aber das eine Mädchen besser als das andere.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 36, 22, 'Die Schönheit der Frau macht das Angesicht (des Mannes) leuchten und geht über jedes andere Verlangen des Mannes hinaus;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 36, 23, 'ist aber auf ihrer Zunge noch Milde und Sanftmut, so zählt ihr Mann nicht zu den gewöhnlichen Menschenkindern.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 36, 24, 'Wer eine (solche) Frau erwirbt, gewinnt den besten Besitz, eine Gehilfin, die zu ihm paßt, und eine Säule, an die er sich lehnt.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 36, 25, 'Wo kein Zaun ist, wird das Grundstück geplündert; und wo keine Frau (im Hause) ist, da herrscht Seufzen und Verwirrung.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 36, 26, 'Denn wer traut einem leichtgeschürzten Räuber, der von einer Stadt in die andere hinstürmt? Ebenso ergeht es dem Manne, der kein Nest hat und der da nächtigt, wohin er gerade am Abend kommt.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 36, 27, '');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 36, 28, '');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 37, 1, 'Jeder Freund sagt: »Auch ich bin ein Freund!« aber mancher Freund ist nur dem Namen nach ein Freund.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 37, 2, 'Ist’s nicht ein Kummer, der dem Tode nahe bringt, wenn ein Genosse und Freund sich in einen Feind verwandelt?');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 37, 3, 'Böse Gesinnung, von wo bist du hereingebrochen (h), die Erde mit Falschheit zu bedecken?');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 37, 4, 'Ein Genosse freut sich, solange das Glück seines Freundes dauert, aber zur Zeit der Trübsal ist er gegen ihn.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 37, 5, 'Ein guter Freund kämpft mit dem Feinde und ergreift den Schild gegen den Widersacher (g).');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 37, 6, 'Vergiß den Freund nicht im Kampfe (g) und sei seiner nicht uneingedenk, wenn du Vermögen besitzt.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 37, 7, 'Jeder Ratgeber hält seinen Rat hoch, aber mancher rät zu seinem eigenen Nutzen».');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 37, 8, 'Vor einem Ratgeber nimm dich in acht und suche zunächst zu erfahren, in welcher äußeren Lage er sich befindet; denn er wird bei seinem Rate an sich selbst denken. Hüte dich, damit er dein Geschick nicht dem Zufall preisgibt');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 37, 9, 'und zu dir sagt: »Du bist auf dem rechten Wege«, dabei aber sich dir gegenüber hinstellt, um zu sehen, was dir zustoßen werde.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 37, 10, 'Berate dich nicht mit einem, der mißgünstig nach dir blickt, und verbirg deine Pläne vor deinen Neidern.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 37, 11, 'Berate dich nicht mit einer Frau über ihre Nebenbuhlerin, noch mit einem Feigling über den Krieg (h), nicht mit einem Kaufmann über den Umsatz, noch mit einem Verkäufer über die Ware, nicht mit einem Mißgünstigen über Dankbarkeit, noch mit einem Hartherzigen über Mildtätigkeit, nicht mit einem Faulen über seine Arbeit, noch mit einem ständigen Tagelöhner über den Feierabend (h), nicht mit einem faulen Knecht über viele Arbeit: auf diese Leute verlaß dich nicht bei irgend einem Ratschlag.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 37, 12, 'Vielmehr pflege beständig Verkehr mit einem frommen Mann, von dem du weißt, daß er die Gebote hält, der gleichen Sinnes ist wie du und um dich trauert, wenn du ins Unglück gerätst.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 37, 13, 'Aber auch auf den Rat des Gewissens gib acht, denn einen treueren Berater als dieses hast du nicht;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 37, 14, 'denn das Gewissen des Menschen pflegt [manchmal] besser Bescheid zu geben als sieben Wächter, die auf einer Anhöhe zur Ausschau sitzen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 37, 15, 'Bei alledem aber bete zum Höchsten, daß er nach seiner Treue deinen Weg ebnen (oder deine Schritte lenken) wolle.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 37, 16, 'Das Wort bilde den Anfang jedes Werkes, und Beratung gehe jedem Handeln voraus.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 37, 17, 'Als Spur veränderten Sinnes treten vier Stücke zu Tage:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 37, 18, 'Gutes und Böses, Leben und Tod, und ihre beständige Gebieterin ist die Zunge.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 37, 19, 'Mancher kluge Mann ist ein Lehrer für viele andere und weiß doch sich selbst nicht zu nützen (h).');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 37, 20, 'Mancher, der sich in seinen Worten als weise hinstellt, ist verhaßt, ein solcher leidet schließlich Mangel an allem Lebensunterhalt;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 37, 21, 'denn es ist ihm vom Herrn keine Liebenswürdigkeit verliehen, weil ihm die (wahre) Weisheit völlig abgeht.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 37, 22, 'Mancher ist nur für sich selbst weise, und die Früchte seiner Einsicht zeigen sich an seinem Leibe (g).');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 37, 23, 'Ein weiser Mann belehrt sein Volk, und die Früchte seiner Einsicht sind zuverlässig (oder ewig (g)).');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 37, 24, 'Ein weiser Mann trägt reichen Segen davon, und es preisen ihn glücklich alle, die ihn sehen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 37, 25, 'Das Leben eines Mannes besteht in einer Zahl von Tagen, aber die Tage Israels sind unzählbar.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 37, 26, 'Der Weise erwirbt sich bei seinem Volke Vertrauen (h), und sein Name lebt in Ewigkeit fort.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 37, 27, 'Mein Sohn, hinsichtlich deiner Lebensweise prüfe deine Natur und sieh zu, was ihr schädlich ist, und gib es ihr nicht;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 37, 28, 'denn nicht alles ist allen zuträglich, und nicht jeder Natur sagt alles zu.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 37, 29, 'Sei nicht unmäßig bei irgend einem Genuß und stürze dich nicht gierig auf leckere Speisen;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 37, 30, 'denn in vielem Essen nistet Krankheit, und die Unmäßigkeit führt bis zum Erbrechen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 37, 31, 'Infolge von Unmäßigkeit sind viele zu Tode gekommen; wer sich aber in acht nimmt, verlängert sein Leben.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 37, 32, '');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 37, 33, '');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 37, 34, '');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 38, 1, 'Ehre den Arzt, wenn du ihn nötig hast, mit gebührenden Ehren, denn auch ihn hat der Herr eingesetzt;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 38, 2, 'denn von Gott stammt die Heilkunst, und vom Könige empfängt er Geschenke;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 38, 3, 'das Wissen des Arztes läßt ihn sein Haupt hoch erheben, und vor den Großen findet er Bewunderung (h).');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 38, 4, 'Der Herr bringt die Heilmittel aus der Erde hervor, und ein verständiger Mensch verschmäht sie nicht.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 38, 5, 'Wurde nicht vom Holz das Wasser süß, damit dessen Kraft erkannt würde?.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 38, 6, 'Und er selbst ist’s, der den Menschen das Wissen verleiht, um sich durch seine wunderbaren Heilmittel zu verherrlichen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 38, 7, 'Durch sie heilt der Arzt und bringt den Schmerz zur Ruhe (g),');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 38, 8, 'und der Apotheker bereitet aus ihnen die Mischungen; Gottes Wirken soll eben kein Ende nehmen und ein von ihm ausgehendes Wohlbefinden auf der ganzen Erde herrschen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 38, 9, 'Mein Sohn, in Krankheit sei nicht lässig, sondern bete zum Herrn, so wird er dich heilen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 38, 10, 'Stehe ab von Versündigung und laß deine Hände rechtschaffen handeln und reinige dein Herz von aller Sünde.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 38, 11, 'Bringe Weihrauch dar und ein Gedenkopfer von Weizenmehl (h) und eine fette Opfergabe, als ob du schon nicht mehr am Leben wärst.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 38, 12, 'Aber auch dem Arzte gewähre Zutritt, denn auch ihn hat der Herr eingesetzt, und er darf dir nicht fern bleiben; denn auch ihn hast du nötig.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 38, 13, 'Bisweilen tritt auch durch seine Bemühung ein glücklicher Erfolg ein,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 38, 14, 'da ja auch er zu Gott betet, daß er ihm Linderung gelingen lasse und die Heilung zur Wiederherstellung.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 38, 15, 'Wer sich gegen seinen Schöpfer versündigt, möge in die Hände des Arztes fallen!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 38, 16, 'Mein Sohn, um einen Toten vergieße Tränen und stimme die Totenklage an als einer, der einen schweren Verlust erlitten hat. Wie es ihm zukommt, besorge seine Leiche und zeige dich bei seiner Bestattung nicht gleichgültig.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 38, 17, 'Laß dein Weinen bitterlich sein und heiß deine Klage und halte die Trauer um ihn, wie es seiner würdig ist, einen oder zwei Tage der üblen Nachrede wegen, und laß dich dann wieder trösten bezüglich deines Kummers.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 38, 18, 'Denn aus dem Kummer geht der Tod hervor, und Trauer im Herzen lähmt die Lebenskraft.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 38, 19, 'Mit dem Leichenzuge geht auch die Trauer vorüber, und die Lebensweise des Armen zehrt dauernd am Herzen');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 38, 20, 'Überlaß dein Herz nicht länger dem Kummer, entschlage dich seiner und denke an das Ende;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 38, 21, 'vergiß das nicht, denn da gibt’s keine Rückkehr; diesem nützest du nicht, und dir selbst schadest du.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 38, 22, 'Denke an sein Geschick, denn so ist auch das deine: gestern ihm und heute dir.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 38, 23, 'Ist es mit dem Toten zu Ende, so laß auch sein Andenken zu Ende sein und tröste dich über ihn, weil sein Geist von ihm geschieden ist.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 38, 24, 'Die Weisheit des Schriftgelehrten gedeiht in günstiger Mußezeit (h), und wer kein Geschäft hat, kann sich der Weisheit widmen (oder kann weise werden).');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 38, 25, 'Wie kann die Weisheit erlangen, wer den Pflug führt und seinen Ruhm findet in der Lanze des Ochsenstachels? wer Rinder antreibt und sich mit deren Arbeiten befaßt und mit den jungen Stieren seine Unterhaltung führt?');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 38, 26, 'wer seinen Sinn darauf richtet, Furchen zu ziehen, und dessen unablässige Sorge auf die Fütterung der Kühe geht? (h).');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 38, 27, 'Ebenso steht es mit jedem Handwerker und Baumeister, der bei Nacht wie bei Tage durcharbeitet, der da Schnitte auf Siegelringe eingräbt und beharrlich dabei ist, mannigfaltige Verzierungen anzubringen: er richtet seine Aufmerksamkeit darauf, die Zeichnung (oder das Gemälde) ähnlich zu machen, und seine Sorge geht auf die Vollendung des Werkes.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 38, 28, 'Ebenso auch der Schmied, der nahe beim Amboß sitzt und das rohe Eisen beschaut; die Flamme des Feuers bringt sein Fleisch zum Aufspringen, und von der Hitze des Ofens erglüht er; dem Schall des Hammers neigt er sein Ohr zu, und auf das Muster des Geräts sind seine Augen gerichtet; seine Gedanken beschäftigen sich nur mit der Vollendung seiner Arbeiten, und seine unablässige Sorge geht dahin, sie bei der Fertigstellung sauber zu putzen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 38, 29, 'Ebenso ist’s mit dem Töpfer, der an seiner Arbeit sitzt und mit den Füßen die Scheibe dreht, der immerfort in Unruhe lebt um seine Arbeit, denn seine ganze Leistung wird stückweise berechnet.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 38, 30, 'Mit seinem Arme formt er den Ton, und unter seinen Füßen macht er die zähe Masse geschmeidig; seine Aufmerksamkeit richtet er auf die Vollendung der Glasur, und seine Sorge geht auf die Reinigung des Ofens.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 38, 31, 'Alle diese verlassen sich auf ihre Hände, und jeder von ihnen versteht sich gut auf sein Geschäft.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 38, 32, 'Ohne sie wird keine Stadt gebaut, und wo sie als Fremdlinge wohnen, brauchen sie nicht zu hungern.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 38, 33, 'Doch bei der Beratung des Volkes werden sie nicht befragt, und in der Gemeindeversammlung spielen sie keine Rolle; auf dem Stuhl des Richters sitzen sie nicht, [und auf den Bund des Gesetzes verstehen sie sich nicht] und bringen Gerechtigkeit und Recht nicht an den Tag, und mit Weisheitssprüchen geben sie sich nicht ab.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 38, 34, 'Aber den Bestand der Welt stützen sie, und ihr Gebet geht auf die Ausübung ihres Gewerbes.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 38, 35, '');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 38, 36, '');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 38, 37, '');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 38, 38, '');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 38, 39, '');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 39, 1, 'Anders ist’s mit dem, der seinen Geist darauf gerichtet hat und nachsinnt über das Gesetz des Höchsten, der die Weisheit aller Altvordern ergründet und sich mit der Erforschung der Propheten beschäftigt.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 39, 2, 'Auf die Darlegungen berühmter Männer gibt er acht und in die Wendung der Weisheitssprüche dringt er ein;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 39, 3, 'den verborgenen Sinn der Sprichwörter ergründet er und beschäftigt sich mit den Rätseln der Sprüche;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 39, 4, 'im Kreise der Großen leistet er Dienste und erscheint vor den Fürsten; im Lande fremder Völker reist er umher, denn Gutes und Böses unter den Menschen sucht er kennen zu lernen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 39, 5, 'Er ist eifrig darauf bedacht, sich morgens an den Herrn, seinen Schöpfer, zu wenden und vor dem Höchsten um Erbarmen zu bitten; er tut seinen Mund auf zum Gebet und fleht wegen seiner Sünden um Gnade.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 39, 6, 'Gefällt es dem Herrn, dem großen Gott, so wird er mit dem Geiste der Einsicht erfüllt. Er selbst ist’s alsdann, der Aussprüche seiner Weisheit hervorströmen läßt und dem Herrn Bekenntnisse im Gebet ablegt.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 39, 7, 'Er ist’s, der seinem Wollen und Wissen die rechte Richtung gibt und über Gottes Geheimnisse nachsinnt;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 39, 8, 'er ist’s, der Unterweisung in der Lehre erteilt und sich des Bundesgesetzes des Herrn rühmt.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 39, 9, 'Gar viele loben seine Einsicht, und niemals geht sie verloren; sein Gedächtnis geht in Ewigkeit nicht unter, und sein Name lebt von Geschlecht zu Geschlecht;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 39, 10, 'seine Weisheit preisen die Völker, und sein Lob verkündet die Gemeinde.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 39, 11, 'Bleibt er am Leben, so wird sein Ruhm vor Tausenden gepriesen; und legt er sich zur Ruhe, so gewinnt er noch größeren.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 39, 12, 'Noch einmal will ich mit mir zu Rate gehen und mich aussprechen; denn wie der Vollmond bin ich voll (von Erkenntnis).');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 39, 13, 'Hört mich an, ihr frommen Söhne, und ihr werdet sprossen wie eine Rose, gepflanzt an Wasserbächen,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 39, 14, 'und wie der Weihrauch soll euer Wohlgeruch duften, und Blüten sollt ihr treiben wie die Lilie: verbreitet Wohlgeruch und singt ein Loblied! preist den Herrn wegen all seiner Werke!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 39, 15, 'Gebt seinem Namen Herrlichkeit und bekennt euch zu ihm unter Lobpreis, mit Liedern zur Harfe (g) und zum Saitenspiel; und also verkündet mit Jubelschall:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 39, 16, 'Die Werke des Herrn sind allzumal gut und genügen jedem Zweck zu seiner Zeit');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 39, 17, 'Man darf nicht fragen: »Was ist dies? wozu ist das?« (h); denn alles ist zweckmäßig zu seiner Zeit. Auf sein Wort stand das Wasser da wie ein Garbenhaufen, und durch das Gebot seines Mundes entstanden Sammelörter der Gewässer (h).');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 39, 18, 'Auf seinen Befehl geschieht alles ihm Wohlgefällige, und niemand kann ihn hindern, wenn er helfen will.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 39, 19, 'Das Tun aller Menschenkinder ist ihm bekannt, und nichts bleibt vor seinen Augen verborgen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 39, 20, 'Von einer Ewigkeit bis zu der andern reicht sein Blick, und nichts ist unbegreiflich für ihn (h).');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 39, 21, 'Man darf nicht fragen: »Was ist dies? wozu ist das?« denn alles ist zu einem bestimmten Zweck geschaffen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 39, 22, 'Sein Segen flutet über wie der Nil, und wie der Euphratstrom (g) tränkt er das Erdreich.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 39, 23, 'Ebenso treibt sein Zorn die Völker aus ihren Wohnsitzen und verwandelt wasserreiches Land in eine Salzwüste.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 39, 24, 'Seine Wege sind für die Frommen gerade (oder eben), hinwiederum für die Gottlosen voller Anstoß.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 39, 25, 'Gutes ist für die Guten von Anfang an bestimmt, ebenso Böses für die Sünder.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 39, 26, 'Die Hauptbedürfnisse für das menschliche Leben sind Wasser und Feuer, Eisen und Salz, das Mark (g) des Weizens, Honig und Milch, Traubenblut, Öl und Kleidung.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 39, 27, 'Alles das dient den Frommen zum Guten, ebenso verwandelt es sich für die Sünder in Böses.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 39, 28, 'Es gibt Winde, die zur Strafe geschaffen sind und in ihrem Wüten Berge von ihrer Stelle rücken (g); zur Zeit des Vollzugs lassen sie ihre Kraft los und besänftigen dadurch den Grimm ihres Schöpfers.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 39, 29, 'Feuer und Hagel, Hungersnot und Pest, auch diese sind zur Strafe geschaffen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 39, 30, 'Reißende Tiere (g), Skorpione und Schlangen und das Schwert, das an den Gottlosen Rache nimmt zum Verderben:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 39, 31, 'wenn er ihnen Befehl erteilt, so freuen sie sich und halten sich bereit, wenn er ihrer auf der Erde bedarf, und wenn ihre Zeit kommt, widerstreben sie seinem Befehle nicht.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 39, 32, 'Darum war ich von Anfang an fest überzeugt und erwog es und sprach es in einer Schrift aus:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 39, 33, '»Die Werke des Herrn sind allzumal gut und genügen jedem Zwecke zu seiner Zeit;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 39, 34, 'und man darf nicht sagen: »Dieses ist schlechter als jenes«, denn alles bewährt sich zu seiner Zeit.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 39, 35, 'Und nun jubelt mit ganzem Herzen und vollem Munde und preist den Namen des Herrn!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 39, 36, '');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 39, 37, '');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 39, 38, '');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 39, 39, '');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 39, 40, '');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 39, 41, '');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 40, 1, 'Große Mühsal hat Gott (g) jedem Menschen zugeteilt, und ein schweres Joch ist den Menschenkindern auferlegt von dem Tage an, wo sie aus dem Schoße ihrer Mutter hervorgehen, bis zu dem Tage, wo sie (im Grabe) zur Allmutter zurückkehren;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 40, 2, 'den Gegenstand ihrer Gedanken und die Furcht ihres Herzens, ihre sorgenvolle Erwägung (h) bildet der Tag ihres Todes.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 40, 3, 'Von dem an, der auf dem Throne sitzt in Herrlichkeit, bis zu dem, der in Staub und Asche erniedrigt daliegt,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 40, 4, 'von dem an, der den Purpur und die Krone trägt (h), bis zu dem, der sich in grobes Linnen hüllt: –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 40, 5, 'Zorn, Eifersucht, Sorge und Angst, Todesfurcht, Zank und Streit; und zur Zeit der Ruhe auf seinem Lager verwirrt der nächtliche Schlaf seine Gedanken.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 40, 6, 'Ruhe findet er nur eine Weile, so gut wie keine, und liegt dann ruhelos in Träumen wie am Tage der Wache (? h); geängstigt durch die Gesichte seines Geistes ist er wie ein Flüchtling, der vor dem Verfolger enteilt;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 40, 7, 'im Augenblick, wo es sich um seine Rettung handelt, erwacht er und wundert sich über seine grundlose Furcht.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 40, 8, 'Bei allen Geschöpfen vom Menschen bis zu den Tieren, und bei den Sündern obendrein siebenfach,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 40, 9, 'herrscht Pest und Blutvergießen, Fieber und Schwert, Hungersnot und Tod, Verwüstung und Plagen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 40, 10, 'Gegen die Gottlosen ist dies alles geschaffen worden, und um ihretwillen tritt die Vernichtung ein.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 40, 11, 'Alles, was von der Erde ist, kehrt zur Erde zurück, und was aus der Höhe stammt, zur Höhe (g).');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 40, 12, 'Alle Geschenke und Ungerechtigkeit vergehen, aber die Treue besteht ewiglich.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 40, 13, 'Der Reichtum der Gottlosen vertrocknet wie ein Bach und verhallt wie ein starker Donner bei Gewitter (h).');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 40, 14, 'Wenn der Fromme seine offene Hand betätigt, freut er sich; ebenso gehen aber die Übertreter zuletzt (oder völlig) zugrunde.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 40, 15, 'Die Nachkommen der Gottlosen treiben nicht viele Schößlinge und sind wie unreine Wurzeln auf schroffen Felsen,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 40, 16, 'wie Riedgras an jedem Gewässer und Bachufer, das eher als alles andere Gras ausgerauft wird.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 40, 17, 'Die Mildtätigkeit dagegen ist wie ein gesegneter Lustgarten, und Wohltätigkeit hat ewigen Bestand.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 40, 18, 'Köstlich ist das Leben dessen, der genügenden Lebensunterhalt und lohnende Arbeit hat (h), aber besser als beide ist der daran, der einen Schatz findet.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 40, 19, 'Besitz von Kindern und Erbauung einer Stadt schaffen einen dauernden Namen, aber mehr als sie beide, wer die Weisheit erlangt. Viehnachwuchs und Pflanzung lassen den Namen erblühen, aber höher als beides wird ein tadelloses Weib geschätzt.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 40, 20, 'Wein und Gesang (oder Musik) erfreuen das Herz, aber über beides geht die Liebe von Freunden (g).');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 40, 21, 'Flöte und Saitenspiel versüßen den Gesang, aber besser als beide ist liebliche Redegabe.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 40, 22, 'Nach Anmut und Schönheit trägt dein Auge Verlangen, aber in noch höherem Grade nach dem frischen Grün der Saat.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 40, 23, 'Köstlich sind ein Freund und ein Genosse, die sich zu guter Stunde einstellen, aber über beide geht die Ehefrau im Verein mit dem Gatten.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 40, 24, 'Brüder und Helfer sind für die Zeit der Not, aber besser als beide rettet die Wohltätigkeit.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 40, 25, 'Gold und Silber geben dem Fuße einen festen Stand, aber höher als beide wird ein guter Rat geschätzt.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 40, 26, 'Reichtum und Macht erhöhen das Selbstgefühl, doch über beide geht die Gottesfurcht. Die Gottesfurcht ist das vollkommene Gut, und wenn man sie besitzt, braucht man keine Hilfe (oder Stütze) zu suchen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 40, 27, 'Die Gottesfurcht ist wie ein gesegnetes Eden, und über alle Herrlichkeit ist sie als Baldachin gebreitet.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 40, 28, 'Mein Sohn, führe nie ein Bettlerleben: lieber sterben als betteln!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 40, 29, 'Ein Mensch, der nach einem fremden Tische hinblickt, dessen Leben kann nicht als Leben gelten; er besudelt sich selbst mit den Speisen fremder Leute (h); ein verständiger und gesitteter Mensch hütet sich davor.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 40, 30, 'Im Munde des Schamlosen klingt die Bettelei süß, aber in seinem Inneren brennt sie wie Feuer.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 40, 31, '');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 40, 32, '');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 41, 1, 'O Tod, wie bitter ist der Gedanke an dich für den Menschen, der in seinen Verhältnissen behaglich lebt, für den Mann, der ohne Sorgen ist und überall Glück hat und der noch imstande ist, Nahrung zu sich zu nehmen!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 41, 2, 'O Tod, wie willkommen ist dein Machtspruch einem Menschen, der Mangel leidet und keine Kraft mehr hat, für den Altersschwachen und mit Sorgen Überlasteten, auch für den, der in Verzweiflung ist und die Widerstandskraft verloren hat!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 41, 3, 'Fürchte dich nicht vor dem Machtspruche des Todes, denke an deine Vorfahren und Nachkommen: Dieser Machtspruch ergeht vom Herrn an die ganze Menschheit.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 41, 4, 'Warum sträubst du dich also gegen den Willen des Höchsten? Seien es zehn, seien es hundert oder tausend Jahre: – in der Unterwelt gibt es keine Klage über die Lebensdauer.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 41, 5, 'Abscheuliche Kinder werden die Kinder von Sündern, die da sich umhertreiben in den Wohnungen der Gottlosen (h).');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 41, 6, 'Den Kindern von Sündern geht ihr Erbe verloren, und bei ihren Nachkommen weilt immerdar die Schande.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 41, 7, 'Einen gottlosen Vater verfluchen seine Kinder, denn um seinetwillen werden sie verachtet.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 41, 8, 'Wehe euch, ihr gottlosen Männer, die ihr das Gesetz des Höchsten verlassen habt!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 41, 9, 'Wenn ihr geboren werdet, werdet ihr zum Fluch geboren, und wenn ihr sterbt, erlangt ihr den Fluch als euer Teil.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 41, 10, 'Alles, was von der Erde ist, kehrt zur Erde zurück, ebenso die Gottlosen vom Fluch ins Verderben (h).');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 41, 11, 'Die Trauer der Menschen bezieht sich auf ihren Leib, aber der schlechte Name der Sünder wird ausgetilgt.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 41, 12, 'Sei besorgt um deinen (guten) Namen, denn dieser bleibt dir sicherer als tausend kostbare Schätze Goldes.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 41, 13, 'Die Tage eines guten Lebens sind gezählt, aber ein guter Name bleibt ewiglich. (Abschluß der Darlegung:)');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 41, 14, 'Verborgene Weisheit und vergrabener Schatz – was nützen sie beide?');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 41, 15, 'Besser ein Mensch, der seine Torheit verbirgt, als ein Mensch, der seine Weisheit verbirgt (oder geheimhält).');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 41, 16, 'Vernehmt die Unterweisung über die Schamhaftigkeit, ihr Kinder, und schämt euch nach meiner Darlegung; denn nicht jegliches Schamgefühl ist lobenswert, und nicht jedes Sich-Schämen ist lobenswert.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 41, 17, 'Schämt euch vor Vater und Mutter der Unzucht, und der Lüge vor dem Fürsten und Gewalthaber,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 41, 18, 'vor dem Herrn und der Herrin des Betrugs (g) und vor der Gemeinde und dem Volke der Gesetzwidrigkeit, vor einem Gefährten und Freunde des Treubruchs,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 41, 19, 'und vor der Ortschaft, wo du als Fremdling wohnst, des Diebstahls. Schäme dich, einen Eid und Vertrag zu brechen, und davor, den Ellbogen auf das Brot aufzustemmen, vor schweren Vorwürfen in bezug auf Soll und Haben,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 41, 20, 'auch davor, einem Grüßenden mit Stillschweigen zu dienen, einer Dirne Blicke zuzuwerfen und eine verheiratete Frau anzusehen,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 41, 21, 'dich von einem Volksgenossen kalt abzuwenden, die Verteilung von Portionen und Gaben einzustellen');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 41, 22, 'und mit deiner Magd dich abzugeben – nein, tritt an ihr Bett nicht nahe heran! –. Schäme dich auch vor Freunden wegen schmähender Worte und führe keine kränkenden Reden, nachdem du sie beschenkt hast.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 41, 23, 'Schäme dich der Weitergabe eines Gerüchts, das du vernommen hast, und des Verrats geheimer Mitteilungen;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 41, 24, 'so wirst du in Wahrheit schamhaft sein und dich bei jedermann beliebt machen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 41, 25, '');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 41, 26, '');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 41, 27, '');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 41, 28, '');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 41, 29, '');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 42, 1, 'Jedoch wegen folgender Dinge sollst du dich nicht schämen und auf niemand Rücksicht nehmen dir zur Versündigung:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 42, 2, 'wegen des Gesetzes des Höchsten und seiner Satzungen (g) und wegen der Rechtsprechung, daß du den Gottlosen gerecht sprächest;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 42, 3, 'wegen der Rede mit Genossen und Reisegefährten und wegen der Auszahlung einer von Genossen herrührenden Erbschaft;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 42, 4, 'wegen der Richtigkeit von Waage und Gewichten [und wegen des Abstäubens der Waagschalen und der Schnellwaage und wegen des Abreibens des Epha und der Gewichtsteine]; und wegen des Erwerbs von vielem oder wenigem,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 42, 5, 'wegen des gleichmäßigen Preises beim Kauf und Verkauf und wegen strenger Kinderzucht und wegen Blutigschlagens des Rückens eines bösen Knechts.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 42, 6, 'Für ein böses Weib gehört sich die Verwendung eines Türschlosses, und wo viele Hände tätig sind, da schließe zu,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 42, 7, 'Was du herausgibst, sei gezählt und gewogen, und Ausgabe und Einnahme, alles sei schriftlich!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 42, 8, 'Schäme dich nicht wegen der Zurechtweisung eines Unverständigen und Toren und eines abgelebten Alten, der mit jungen Leuten im Wortwechsel liegt, so wirst du wahrhaft gebildet sein und bewährt nach dem Urteil aller Lebenden.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 42, 9, 'Eine Tochter ist für den Vater eine heimliche Beunruhigung, und die Sorge um sie verscheucht ihm den Schlaf: in ihrer Jugend, daß sie nicht verblühe, und ist sie verheiratet, daß sie nicht mißliebig werde;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 42, 10, 'in ihrer Mädchenzeit, daß sie sich nicht verführen lasse und im Vaterhause schwanger werde, wenn sie aber mit einem Gatten lebt, daß sie sich nicht vergehe, und verheiratet, daß sie nicht kinderlos bleibe.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 42, 11, 'Über eine leichtfertige Tochter halte strenge Wacht, daß sie dich nicht zur Schadenfreude deiner Feinde mache, zum Stadtgespräch und zum Verlästerten unter den Leuten und dich in Schande bringe in der Versammlung am Tore (g). [An dem Zimmer, wo sie wohnt, darf kein Fenster sein und zu dem Raume, wo sie übernachtet, kein Zugang ringsum].');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 42, 12, 'Vor keinem Manne darf sie sich sehen lassen (g), und im Kreise von Weibern soll sie nicht vertraulich schwatzen;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 42, 13, 'denn von den Kleidern kommt die Motte her, und von dem einen Weibe die Schlechtigkeit des andern.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 42, 14, 'Besser ist die Unliebenswürdigkeit des Mannes als ein schöntuendes Weib, und eine schandbare Tochter verursacht Schande über Schande.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 42, 15, 'Gedenken will ich nun der Werke des Herrn und darlegen, was ich gesehen habe. Durch das Wort des Herrn sind seine Werke (und die von ihm belebte Schöpfung nach seiner Bestimmung).');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 42, 16, 'Die helleuchtende Sonne strahlt über dem All und die Herrlichkeit des Herrn über allen seinen Werken.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 42, 17, 'Nicht hat der Herr den heiligen (Engeln) die Gabe verliehen, alle seine Wunderwerke aufzuzählen, die er, der allmächtige Herr, mit Kraft ausgestattet hat, daß das Weltall durch seine Herrlichkeit festen Bestand habe.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 42, 18, 'Den Abgrund und die Herzen erforscht er und durchschaut alle ihre Anschläge; denn der Höchste kennt alles Wissen und hat die Vorzeichen der Ewigkeit vor Augen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 42, 19, 'Das Vergangene und das Zukünftige tut er kund und enthüllt den Befund verborgener Dinge;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 42, 20, 'ihm entgeht kein Gedanke, und kein einziges Vorkommnis bleibt ihm verborgen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 42, 21, 'Die Wunderwerke seiner Weisheit hat er wohl geordnet (oder fest gegründet) und so, daß sie von Ewigkeit bis in Ewigkeit bestehen; nichts ist hinzugefügt worden und nichts hinweggenommen, und keines Ratgebers hat er bedurft.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 42, 22, 'Wie lieblich sind alle seine Werke! ja wie Blumen sind sie anzuschauen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 42, 23, 'Sie alle leben und sind von ewiger Dauer, und für jedweden Zweck steht ihm alles zu Diensten.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 42, 24, 'Alle Dinge sind verschieden, eines gegenüber dem andern, doch nichts Überflüssiges hat er geschaffen:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 42, 25, 'jedes bildet eine treffliche Ergänzung zum andern, und wer kann sich satt sehen an seiner Pracht?');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 42, 26, '');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 43, 1, 'Der Stolz (oder die Pracht) in der Höhe ist das durchsichtige Himmelsgewölbe, die Erscheinung des Himmels ein herrlicher Anblick.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 43, 2, 'Die Sonne strahlt beim Aufgang Wärme aus (g): wie wunderbar ist das Werk des Höchsten!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 43, 3, 'Durch ihre Mittagsglut trocknet sie den Erdkreis aus: wer vermag ihrer Hitze gegenüber standzuhalten?');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 43, 4, 'Den Schmelzofen bläst man an bei Werken der Feuerglut, aber dreimal mehr setzt die Sonne die Berge in Brand; feurige Dünste entfacht sie, und lichte Strahlen entsendend (h), blendet sie die Augen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 43, 5, 'Ja, groß ist der Herr, der sie geschaffen hat, und auf sein Geheiß durcheilt sie ihre Bahn.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 43, 6, 'Und auch der Mond erstrahlt immerdar zu seinen Zeiten zur Bestimmung der Zeiten und als ein ewiges Zeichen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 43, 7, 'Vom Monde kommt die Festsetzung der Festzeiten; eine Leuchte ist er, die abnimmt, wenn er voll geworden ist (h).');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 43, 8, 'Der Monat ist nach ihm benannt, er nimmt wunderbar zu in seinem Wechsel; als Feldzeichen für die Heerscharen in der Höhe erstrahlt er am festen Himmelsgewölbe.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 43, 9, 'Des Himmels Schönheit ist die Pracht der Sterne, ein strahlender Schmuck in den Himmelshöhen Gottes.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 43, 10, 'Nach dem Geheiß des Heiligen stehen sie da in fester Ordnung und werden nicht müde in ihrem Wachtdienst.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 43, 11, 'Schau den Regenbogen an und preise seinen Schöpfer! denn überaus herrlich ist er in seiner Farbenpracht;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 43, 12, 'das Himmelsgewölbe umzieht er mit seinem Strahlenkreise; die Hand des Höchsten hat ihn ausgespannt mit Allmacht.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 43, 13, 'Seine Allmacht entflammt Blitze (? g) und läßt Brandpfeile fliegen, wenn er richtet.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 43, 14, 'Für ihre Verwendung hat er eine Rüstkammer geschaffen, und die Wolken fliegen hervor wie Vögel.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 43, 15, 'Durch seine gewaltige Kraft verdichtet er das Gewölk, und Hagelsteine fallen zerbröckelt herab.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 43, 16, 'Der Hall seines Donners macht die Erde erbeben, und durch sein Erscheinen geraten die Berge ins Wanken.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 43, 17, 'Nach seinem Willen erbraust der Südwind und der Sturm aus dem Norden und der Wirbelwind; wie Vögel, die herniederfliegen, schüttelt er den Schnee hin, und wie Heuschrecken, die sich niederlassen, ist sein Herabfallen;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 43, 18, 'seine weiße Pracht blendet die Augen, und über sein Gestöber staunt das Herz.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 43, 19, 'Auch den Reif schüttet er wie Salz über die Erde aus, und gefroren wird er zu Nadelspitzen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 43, 20, 'Läßt er den kalten Nordwind wehen, so gefriert das Wasser zu Eis; über jedes stehende Gewässer zieht er eine Decke, und wie in einen Panzer hüllt sich der Teich.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 43, 21, 'Wiederum versengt er den Ertrag der Berge wie dörrende Hitze und die sprossenden Auen wie eine Feuerflamme (g).');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 43, 22, 'Heilung für alles bringt das Geträufel der Wolken (g); Tau tritt ein und schafft Erquickung nach dem Glutwind.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 43, 23, 'Durch seine Überlegung hat er das Weltmeer zur Ruhe gebracht und die Inseln in der Flut gegründet.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 43, 24, 'Die Seefahrer erzählen von der Ausdehnung des Meeres; da staunen wir über das, was wir zu hören bekommen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 43, 25, 'Dort sind auch die wundersamen und erstaunlichen Geschöpfe, Getier der mannigfachsten Art und die Ungeheuer der Walfische.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 43, 26, 'Für ihn bringen die Engel ihr Werk zustande, und nach seinem Geheiß vollführen sie seinen Willen (g).');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 43, 27, 'Noch vieles könnten wir anführen und würden doch nicht zu Ende kommen, und der Schluß der Rede würde immer sein: »Er ist alles!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 43, 28, 'Ihm zu preisen, wie vermöchten wir es (h)? er ist ja größer als alle seine Werke.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 43, 29, 'Verehrungswürdig ist der Herr über alle Maßen, und wunderbar ist seine Macht.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 43, 30, 'Erhebt den Herrn mit Lobpreis, so hoch ihr könnt: er ist doch immer noch erhabener! Bietet für euren Lobpreis immer neue Kraft auf und werdet nicht müde: ihr erreicht ihn doch nicht völlig.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 43, 31, 'Wer hat ihn gesehen, daß er davon erzählen könnte? und wer kann ihn preisen, wie er ist?');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 43, 32, 'Vieles gibt es, was noch wunderbarer und unbegreiflicher ist als dieses (g), denn nur weniges haben wir (h) von seinen Werken gesehen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 43, 33, 'Alles hat ja der Herr geschaffen, und den Frommen hat er Weisheit verliehen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 43, 34, '');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 43, 35, '');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 43, 36, '');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 43, 37, '');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 44, 1, 'Preisen will ich nun die frommen Männer (g), unsere Väter nach ihren Geschlechtern.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 44, 2, 'Viel Ehre hat der Herr ihnen zugeteilt, nämlich seine Herrlichkeit von der Urzeit her:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 44, 3, 'nämlich Beherrscher der Erde (g) in ihren Königreichen und Männer, berühmt durch ihre Macht, die Rat erteilten durch ihre Einsicht, die Auskunft gaben durch ihre Weissagungen,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 44, 4, 'Führer von Völkern (g) durch Ratschläge und Einsicht und Fürsten durch ihren Scharfblick,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 44, 5, 'die Lieder ersannen nach den Regeln und Sprüche schriftlich bekannt machten,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 44, 6, 'reiche Männer, ausgestattet mit Macht und ruhig in ihren Wohnstätten lebend:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 44, 7, 'alle diese waren zu ihrer Zeit hochgeehrt, und solange sie lebten, bestand ihr Ruhm.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 44, 8, 'Manche von ihnen haben einen Namen hinterlassen, so daß man ihre Ruhmestaten erzählt;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 44, 9, 'aber an manche von ihnen ist kein Andenken hinterblieben, sondern sie sind untergegangen, als wären sie nie gewesen; sie wurden, als wären sie nie geboren, und ebenso ihre Kinder nach ihnen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 44, 10, 'Aber dieses sind die frommen Männer (g), deren gerechtes Tun nicht in Vergessenheit geraten ist;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 44, 11, 'bei ihren Nachkommen verbleibt der Segen und ihr Erbe bei ihren Kindeskindern.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 44, 12, 'Im Bunde verharrt ihr Geschlecht und ihre Kinder um ihretwillen;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 44, 13, 'auf ewig bleibt ihr Gedächtnis bestehen (g), und ihr Ruhm wird nie vergessen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 44, 14, 'Ihre Leiber wurden in Frieden bestattet, aber ihr Name lebt fort bis in die fernsten Geschlechter.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 44, 15, 'Von ihrer Weisheit erzählt die Volksgemeinde, und ihr Lob verkündet die Versammlung.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 44, 16, 'Henoch wandelte mit Gott (g) und ward entrückt, ein Vorbild der Sinnesänderung für seine Zeitgenossen (h).');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 44, 17, 'Der gerechte Noah wurde als untadelig erfunden, zur Zeit des Zornes wurde er der Stammvater (g); um seinetwillen blieb ein Überrest, und infolge des Bundes mit ihm hörte die Flut auf (g).');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 44, 18, 'Ein ewiger Bund wurde mit ihm geschlossen, daß nicht (nochmals) alles Fleisch durch eine Flut vertilgt werden sollte.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 44, 19, 'Abraham wurde zum großen Vater einer Menge von Völkern, und niemals ist jemand an Ehre ihm gleich erfunden worden;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 44, 20, 'er war’s, der das Gebot des Höchsten hielt und in einen Bund mit ihm trat; an seinem Fleische bestätigte er den Bund, und in der Versuchung ward er treu erfunden.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 44, 21, 'Darum verhieß Gott ihm mit einem Eide, daß die Völker durch seine Nachkommenschaft gesegnet werden sollten, nämlich ihn zahlreich zu machen wie den Staub der Erde, und wie die Sterne seine Nachkommenschaft zu erhöhen und ihnen Landbesitz zu verleihen von einem Meer bis zum andern und vom Euphratstrom bis ans Ende der Erde.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 44, 22, 'Auch dem Isaak gab er dieselbe Verheißung um Abrahams, seines Vaters, willen, nämlich den Segen für alle Menschen und den Bund,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 44, 23, 'und ließ endlich den Segen ruhen auf dem Haupte Jakobs. Er erkannte ihn als einen Erstgeborenen an (g) und gab ihm (das Land) zum Erbbesitz; er sonderte es in seine Gebiete, die er unter die zwölf Stämme verteilte.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 44, 24, '');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 44, 25, '');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 44, 26, '');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 45, 1, 'Und er ließ aus ihm einen [frommen] Mann hervorgehen, der Gnade fand in den Augen aller Lebenden, geliebt von Gott und den Menschen, Mose, dessen Andenken gesegnet ist.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 45, 2, 'Er verherrlichte ihn wie einen Gott (g) und machte ihn groß durch furchtbare Taten [an den Feinden].');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 45, 3, 'Auf sein Geheiß ließ er schnell die Zeichen geschehen und machte ihn beherzt vor dem Könige (g). Befehle erteilte er ihm an das Volk und ließ ihn seine Herrlichkeit schauen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 45, 4, 'Wegen seiner Treue und seiner Sanftmut erwählte er ihn aus allen Menschenkindern;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 45, 5, 'er ließ ihn seine Stimme hören und ließ ihn in das Wolkendunkel treten und legte ihm [vor seinem Angesicht] die Gebote in die Hand (g), das Gesetz des Lebens und der Einsicht, daß er Jakob seinen Bund lehre und die Israeliten seine Rechte und Satzungen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 45, 6, 'Und ebenso wie ihn erhöhte er einen Heiligen, nämlich Aaron [seinen Bruder] aus dem Stamme Levi.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 45, 7, 'Er bestellte ihn zu einem Amte von ewiger Dauer (g) und verlieh ihm das Priestertum im Volk, daß er ihm in Segen diene (g). Er verherrlichte ihn mit seiner Pracht und umgürtete ihn mit herrlicher Pracht (h);');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 45, 8, 'er ließ ihn den ganzen Schmuck anlegen und zierte ihn mit der prächtigen Kleidung, mit den Beinkleidern, dem Leibrock und Schulterkleid.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 45, 9, 'Und er brachte daran rings Granatäpfel [aus Gold] an, Glöckchen in Menge ringsum, die einen lieblichen Klang erschallen ließen bei seinen Schritten, um ihren Ton im Tempel hören zu lassen, damit der Kinder seines Volkes gnädig gedacht würde,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 45, 10, 'mit der heiligen Gewandung aus Gold und Purpurblau und Purpurrot, in Kunstwirkarbeit, mit dem Brustschild des Urteilsspruches, den Urim und Thummim, mit dem gewobenen Karmesin (h), in Weberarbeit,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 45, 11, 'mit den Edelsteinen, graviert wie Siegelringe, in der Einfassung von Gold, der Arbeit des Steinschneiders, zur Erinnerung mit eingegrabener Schrift, entsprechend der Zahl der Stämme Israels;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 45, 12, 'dazu die goldene Krone oben am Kopfbund mit der eingeschnittenen Inschrift »dem Herrn geheiligt«, ein herrlicher Schmuck, ein Werk der Pracht, eine Wonne für die Augen und die vollkommenste Schönheit (g).');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 45, 13, 'Vorher gab es nichts derartiges, und bis in Ewigkeit darf kein anderer es anlegen, sondern nur einer von seinen Söhnen und dessen Nachkommen nach ihren Geschlechtern (g).');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 45, 14, 'Sein Speisopfer geht gänzlich in Rauch auf, alltäglich als ständiges zweimal.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 45, 15, 'Und Mose füllte seine Hand und salbte ihn mit dem heiligen Öl; und so wurde ihm eine Dienstleistung für alle Zukunft auferlegte und seinen Nachkommen, solange der Himmel steht, daß er ihm dienen und [zugleich] Priester sein solle und sein Volk in seinem Namen segnete.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 45, 16, 'Er erwählte ihn aus allen Lebenden, um [dem Herrn] das Brandopfer und die Fettsstücke (g) darzubringen, Rauchwerk und Wohlgeruch als Erinnerungsopfer, und Sühne für sein Volk zu erwirken.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 45, 17, 'Und er gab ihm seine Gebote und übertrug ihm die oberste Entscheidung über das Gesetz und das Recht (g), um Jakob seine Zeugnisse zu lehren und Israel in seinem Gesetz zu unterweisen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 45, 18, 'da traten Fremdlinge wider ihn auf und waren eifersüchtig auf ihn in der Wüste, die Anhänger Dathans und Abirams und die Rotte Korahs, in grimmigem Zorn.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 45, 19, 'Der Herr aber sah es und geriet in Zorn (g) und vertilgte sie in seines Zornes Glut; er vollbrachte an ihnen Wunderzeichen und verzehrte sie durch flammendes Feuer.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 45, 20, 'Dem Aaron aber mehrte er noch die Ehre und gab ihm seinen Erbbesitz: die Erstlinge der Felderzeugnisse teilte er ihm zur Nahrung zu und hieß ihn die Opfer des Herrn essen;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 45, 21, 'die Schaubrote sind sein Anteil und ein Geschenk für ihn und seine Nachkommen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 45, 22, 'Jedoch am Landbesitz des Volkes soll er kein Erbteil haben und inmitten des Volkes keinen Erbbesitz verteilen; denn der Herr selbst ist sein Anteil und sein Erbbesitz unter den Kindern Israel (g).');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 45, 23, 'Und auch Pinehas, der Sohn Eleasars, erlangte als dritter Ehre durch seine Tatkraft (g), weil er eiferte für den Gott des Alls und für sein Volk in den Riß trat, weil sein Herz ihn dazu antrieb und er Sühne für Israel erwirkte.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 45, 24, 'Darum setzte er auch für ihn eine Rechtsbestimmung fest, einen Friedensbund, daß er Vorsteher des Heiligtums [und seines Volkes] sein sollte, daß ihm und seinen Nachkommen das Hohepriestertum gehören sollte auf ewige Zeiten.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 45, 25, 'Es bestand aber auch eine Bundesverheißung mit David, dem Sohne Isais, aus dem Stamme Juda: das Erbe des Königs solle einem von seinen Söhnen allein zufallen, ebenso das Erbe Aarons ihm und seinen Nachkommen. [Darum preiset den gütigen Herrn, der euch mit Ehre bekleidet hat!]');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 45, 26, 'Er gebe euch Weisheit des Herzens, sein Volk mit Gerechtigkeit zu richten, damit euer Glück (g) nicht aufhöre und eure Herrschaft bis in die fernsten Zeiten bestehe (g).');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 45, 27, '');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 45, 28, '');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 45, 29, '');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 45, 30, '');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 45, 31, '');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 45, 32, '');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 46, 1, 'Ein Kriegsheld war Josua, der Sohn Nuns, der Diener (g) Mose’s im Prophetenamt, der geschaffen war, um seinem Namen Ehre zu machen als eine große Hilfe für seine Auserwählten, um Rache zu nehmen an den Feinden [die sich gegen ihn erhoben], und um Israel zu seinem Erbbesitz zu verhelfen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 46, 2, 'Wie herrlich war er, wenn er die Hand ausstreckte, wenn er die Lanze schwang wider eine Stadt! (g).');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 46, 3, 'Wer hätte jemals vor ihm standhalten können? er hat ja die Kriege Gottes geführt (g).');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 46, 4, 'Stand nicht auf seinen Wink die Sonne still, und wurde nicht ein Tag zu zweien?');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 46, 5, 'Er rief zu Gott, dem höchsten Herrscher, als die Feinde ihn ringsum bedrängten, und es erhörte ihn Gott, der Allerhöchste,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 46, 6, 'mit Hagelsteinen und Eisstücken (g), die er auf das feindliche Volk herabschleuderte; und an dem Abstiege vernichtete er die Gegner, damit alle dem Banne geweihten Völker die Erkenntnis erlangten, daß seine Kriegführung vor dem Herrn stattfinde (h), denn er leistete dem Herrn vollkommenen Gehorsam.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 46, 7, 'Auch schon in den Tagen Mose’s hatte er Frömmigkeit bewiesen, er und Kaleb, der Sohn Jephunnes, indem sie fest auftraten gegen die hadernde Gemeinde (g), um das Volk vor Versündigung zu behüten und das böse Gerede zu beschwichtigen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 46, 8, 'Darum wurden auch diese zwei am Leben erhalten von sechshunderttausend Mann zu Fuß, damit er sie in das Erbland hineinbrächte, in das Land, das von Milch und Honig fließt.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 46, 9, 'Und er verlieh dem Kaleb Stärke – und bis ins Greisenalter verblieb sie ihm –, um ihn auf die Höhen des Landes ziehen zu lassen; auch seine Nachkommen hatten das Erbe in Besitz.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 46, 10, 'Alle Israeliten sollten eben zu der Erkenntnis gelangen, daß es gut sei, dem Herrn Gehorsam zu leisten.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 46, 11, 'Und die Richter, ein jeder nach seinem Namen, sie alle, deren Herz nicht abtrünnig ward und die vom Herrn nicht abwichen: ihr Gedächtnis sei gepriesen!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 46, 12, 'Ihre Gebeine mögen von ihrer Stätte emporsprossen und ihr Name sich verjüngen in ihren [ruhmbedeckten] Söhnen!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 46, 13, 'Geehrt von seinem Volke und geliebt von seinem Schöpfer war der vom Mutterschoß an Erbetene, der dem Herrn Geweihte im Prophetenamt: Samuel, der als Richter und als Priester waltete. Auf Gottes Befehl richtete er das Königtum auf und salbte Fürsten über das Volk.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 46, 14, 'Nach dem Gebot des Herrn richtete er die Gemeinde, und der Herr suchte Jakob gnädig heim.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 46, 15, 'Wegen seiner Zuverlässigkeit bewährte er sich als Prophet, und durch seine Aussprüche erwies er sich als zuverlässiger Seher.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 46, 16, 'Auch er rief zum Herrn [dem Herrscher], als die Feinde ihn ringsum bedrängten, indem er ein Milchlamm darbrachte.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 46, 17, 'Da donnerte der Herr vom Himmel her und ließ seine Stimme mit gewaltigem Krachen erschallen;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 46, 18, 'er vernichtete die feindlichen Feldherren (g) und alle Fürsten der Philister.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 46, 19, 'Und zur Zeit, als er sich zur [ewigen] Ruhe auf sein Lager niederlegte, rief er den Herrn und seinen Gesalbten als Zeugen an: »Geld und auch nur ein Paar Schuhe habe ich von niemand angenommen«; und kein Mensch legte Zeugnis gegen ihn ab.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 46, 20, 'Ja, sogar nach seinem Entschlafen ließ er sich befragen und tat dem Könige sein Schicksal kund und erhob seine Stimme aus der Erde, um [durch Weissagung] die Sünde des Volkes zu tilgen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 46, 21, '');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 46, 22, '');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 46, 23, '');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 47, 1, 'Nach ihm trat auch Nathan auf, um zur Zeit Davids zu weissagen (h).');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 47, 2, 'Wie das Fett abgehoben wird vom Opfer, so war David abgesondert von den Israeliten.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 47, 3, 'Mit Löwen spielte er wie mit Böcklein und mit Bären wie mit Schaflämmern.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 47, 4, 'In seiner Jugend erschlug er den Riesen und entfernte die Schmach von seinem Volke, indem er seine Hand mit der Schleuder schwang (g) und den Hochmut Goliaths niederwarf.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 47, 5, 'Denn er hatte den Herrn, den Allerhöchsten, um Hilfe angerufen, und der hatte seiner Rechten Kraft verliehen, daß er den kriegserfahrenen Mann niederstreckte und das Horn seines Volkes erhöhte.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 47, 6, 'Darum sangen ihm zu Ehren die Mädchen und rühmten ihn um seiner Zehntausend willen; als er sich die Krone aufgesetzt hatte, führte er Kriege,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 47, 7, 'demütigte ringsum die Feinde und vernichtete die feindlichen Philister: bis auf den heutigen Tag zerbrach er ihr Horn.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 47, 8, 'Bei all seinem Tun brachte er Dank dar dem Heiligen; Gott dem Allerhöchsten lobsang er mit Ruhmesworten und liebte seinen Schöpfer mit ganzem Herzen (h) und pries ihn alle Tage in seinen Liedern (g).');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 47, 9, 'Auch ließ er Psalmensänger vor dem Altar Aufstellung nehmen und von ihren Stimmen liebliche Lieder ertönen; so lobten sie ihn tagtäglich mit ihren Gesängen (h).');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 47, 10, 'Er verlieh den Festen Glanz und stattete die Festzeiten mit voller Pracht aus, indem jene seinen heiligen Namen priesen und das Heiligtum vom frühen Morgen an davon widerhallte.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 47, 11, 'Da vergab ihm der Herr auch seine Sünde(n) und erhöhte sein Horn auf ewig; er verlieh ihm die Rechte des Königtums und stellte seinen Thron über Israel fest (g).');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 47, 12, 'Nach ihm trat ein weiser Sohn auf und wohnte um seinetwillen auf weitem Plane.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 47, 13, 'Salomo herrschte als König in Friedenszeiten, da Gott ihm Ruhe auf allen Seiten verschaffte, auf daß er seinem Namen ein Haus errichtete und für immer ein Heiligtum gründete.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 47, 14, 'Wie weise warst du schon in deiner Jugend und flossest von Einsicht über wie der Nilstrom!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 47, 15, 'Die Erde umspanntest du mit deinem Geiste und fülltest sie an mit Rätselsprüchen (h).');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 47, 16, 'Bis zu den fernsten Inseln drang dein Name, und du wurdest geschätzt ob deiner Friedensliebe (h).');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 47, 17, 'Durch Lieder, Sprüche, Gleichnisse und Deutungen setztest du die Länder in Staunen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 47, 18, 'Du wurdest benannt (g) nach dem Namen des Hochgepriesenen (g), der da heißt der Gott Israels, und häuftest Gold auf wie Eisen (oder Zinn) und erwarbst Silber in Menge wie Blei.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 47, 19, 'Doch du gabst deine Lenden den Weibern preis und ließest sie herrschen über deinen Leib;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 47, 20, 'so brachtest du einen Schandfleck auf deinen Ruhm und schändetest dein Lager, so daß du Zorn über deine Sprößlinge brachtest und Seufzen über dein Geschlecht (g),');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 47, 21, 'so daß die Herrschaft sich spaltete und aus Ephraim ein aufrührerisches Reich hervorging.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 47, 22, 'Aber Gott wird sein Erbarmen nicht aufgeben und keine von seinen Verheißungen unerfüllt lassen (g); er wird auch nicht die Sprossen seines Auserwählten vertilgen und das Geschlecht dessen, der ihn liebte, nicht ausrotten. Nein, er hat Jakob einen Rest gelassen und dem David von ihm her einen Wurzelschoß.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 47, 23, 'Als Salomo aber sich bei seinen Vätern zur Ruhe gelegt hatte (h), hinterließ er aus seinem Geschlecht einen Sohn, reich an Torheit und arm an Einsicht, Rehabeam, der durch seinen Entscheid das Volk zum Abfall brachte; und Jerobeam stand auf, der Sohn Nabats, der Israel zur Sünde verführte und Ephraim den Weg der Versündigung wies (h),');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 47, 24, 'so daß er ihre Wegführung aus ihrem Lande verschuldete und ihre Sünden sich gewaltig mehrten.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 47, 25, 'Jeglicher Bosheit gaben sie sich hin, [bis das Strafgericht über sie kam],');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 47, 26, '');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 47, 27, '');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 47, 28, '');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 47, 29, '');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 47, 30, '');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 47, 31, '');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 48, 1, 'bis ein Prophet wie Feuer auftrat und sein Wort wie eine Fackel brannte.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 48, 2, 'Er ließ eine Hungersnot über sie kommen (h) und minderte ihre Zahl durch seinen Eifer;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 48, 3, 'durch das Wort Gottes verschloß er den Himmel, und [ebenso] ließ er dreimal Feuer niederfallen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 48, 4, 'Wie herrlich warst du, Elia, [durch deine Wundertaten]! Ja, wer dir gleich ist, mag sich dessen rühmen, –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 48, 5, 'du hast ja einen Verstorbenen aus dem Tode auferweckt und aus der Unterwelt mit Einwilligung des Höchsten (g);');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 48, 6, 'du hast Könige in die Grube hinabgestürzt und Hochgeehrte von ihrem Krankenbett weggerafft;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 48, 7, 'du hast auf dem Sinai die Zurechtweisung vernommen und auf dem Horeb die Urteilssprüche der Rache;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 48, 8, 'du hast Könige gesalbt, um Vergeltung zu üben, und einen Propheten als Nachfolger für dich (g);');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 48, 9, 'du bist entführt worden im Gewitter nach oben auf einem Wagen mit Feuerrossen;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 48, 10, 'du bist, wie geschrieben steht, in Bereitschaft für die bestimmte Zeit (g), um den göttlichen Zorn zu beschwichtigen, bevor er entbrennt, um das Herz der Väter den Kindern wieder zuzuwenden und die Stämme Jakobs wiederherzustellen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 48, 11, 'Heil denen, die dich gesehen haben und mit Liebe geschmückt sind! denn wir, wir werden gewißlich leben.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 48, 12, 'Als Elia durch einen Sturm in den Himmel entrückt war, wurde Elisa mit seinem Geist erfüllt. Doppelt so viele Zeichen tat er, und lauter Wunder gingen aus seinem Munde hervor (g). Solange er lebte, zitterte er vor keinem (Fürsten), und kein Mensch hatte Gewalt über ihn.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 48, 13, 'Keine Sache war für ihn unmöglich, und noch von seiner Grabstätte aus weissagte sein Leichnam.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 48, 14, 'Bei seinen Lebzeiten vollbrachte er Wunder und bei seinem Tode die erstaunlichsten Taten.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 48, 15, 'Bei alledem bekehrte das Volk sich nicht, und sie ließen von ihren Sünden nicht ab, bis sie aus ihrem Lande herausgerissen und über die ganze Erde zerstreut wurden; und es blieb von Juda (g) nur ein wenig Volk übrig und ein Fürst vom Hause Davids.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 48, 16, 'Manche von ihnen handelten recht, andere aber verübten Treubruch.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 48, 17, 'Hiskia befestigte seine Stadt, indem er Wasser in sie hineinleitete, (g); er ließ die Felsen mit Erz durchhauen und legte Teiche für das Wasser an (h).');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 48, 18, 'Zu seiner Zeit zog Sanherib herauf und sandte den Rabsake ab; der kam und streckte seine Hand gegen Zion aus und lästerte Gott in seinem Übermut.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 48, 19, 'Damals erbebten ihre Herzen und ihre Hände, und sie wanden sich in Schmerzen wie Frauen in Geburtsnöten;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 48, 20, 'und sie riefen zu Gott, dem Erbarmer, und streckten die Hände zu ihm aus; da erhörte der Heilige vom Himmel her schnell ihr Gebet und errettete sie durch Jesaja.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 48, 21, 'Er schlug das Heerlager der Assyrer, und sein Engel vernichtete sie durch die Pest.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 48, 22, 'Denn Hiskia hatte getan, was dem Herrn wohlgefiel, und war unverrückt in den Wegen Davids gewandelt, die ihm Jesaja geboten hatte, der große Prophet und zuverlässige Seher.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 48, 23, 'In seinen Tagen ging die Sonne zurück, und er verlängerte dem Könige das Leben.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 48, 24, 'Gewaltigen Geistes schaute er die Endzeit und tröstete die Trauernden in Zion.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 48, 25, 'Bis in Ewigkeit verkündigte er das Künftige und das Verborgene, ehe es eintrat.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 48, 26, '');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 48, 27, '');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 48, 28, '');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 49, 1, 'Der Name Josias ist wie wohlriechender Weihrauch, der wohlgemischt ist (g), das Werk des Salbenbereiters; in jedermanns Munde ist er süß wie Honig und wie Musik (oder Gesang) beim Weingelage.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 49, 2, 'Denn er grämte sich über unsere Abtrünnigkeit (g) und machte den nichtigen Götzengreueln ein Ende;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 49, 3, 'er gab sein Herz völlig dem Herrn hin und festigte die Frömmigkeit in der Zeit der Gottlosigkeit.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 49, 4, 'Außer David und Hiskia und Josia haben sie alle verderbt gehandelt; sie haben alle das Gesetz des Höchsten verlassen, die Könige von Juda, bis es mit ihnen zu Ende war;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 49, 5, 'und sie hatten ihre Macht einem andern übergeben und ihre Ehre einem fremden Volke.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 49, 6, 'Die zündeten die [auserwählte] Stadt des Heiligtums an und machten die Straßen öde, die zu ihr hinführten,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 49, 7, 'um Jeremias willen; denn sie hatten ihn mißhandelt, und er war doch vom Mutterschoße an zum Propheten bestimmt, um auszureißen, zu verderben und zu vernichten, aber ebenso auch zu bauen, zu pflanzen und wiederherzustellen (g).');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 49, 8, 'Ezechiel sah ein Gesicht [der Herrlichkeit], das Gott ihn schauen ließ auf dem Wagen [der Kerube].');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 49, 9, 'Und ich will auch Hiobs gedenken, der alle Wege der Gerechtigkeit innehielt,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 49, 10, 'und auch der zwölf Propheten – mögen ihre Gebeine wieder Sprossen treiben an ihrer Stätte! –: sie, die Jakob wieder gesund gemacht und ihn wieder hergestellt haben durch feste Hoffnung.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 49, 11, 'Wie sollen wir Serubabel preisen, der da war wie ein Siegelring an der rechten Hand?');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 49, 12, 'Und ebenso Josua, den Sohn Jozadaks, die zu ihrer Zeit das Gotteshaus erbauten und dem Herrn den heiligen Tempel aufführten, der zu ewiger Herrlichkeit bestimmt ist.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 49, 13, 'Auch Nehemia – sein Gedächtnis stehe in Ehren! –, er, der uns die zerfallenen Mauern wiederhergestellt und Tore nebst Riegeln wiedereingesetzt hat.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 49, 14, 'Wenige sind auf Erden geschaffen worden wie Henoch, er war es ja auch, der von der Erde entrückt wurde.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 49, 15, 'Auch ist kein Mann geboren worden wie Joseph, der Fürst seiner Brüder, die Stütze seines Volkes, – sogar seine Gebeine wurden sorgfältig geborgen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 49, 16, 'Auch Sem und Seth und Enos haben unter den Menschen in Ehren gestanden; doch über allen, die je in der Welt gelebt haben, steht der Ruhm Adams.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 49, 17, '');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 49, 18, '');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 49, 19, '');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 49, 20, '');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 50, 1, 'Der größte unter seinen Brüdern und der Stolz seines Volkes war der Hohepriester Simon, der Sohn des Onias, der zu seiner Zeit das Gotteshaus ausbesserte und in seinen Tagen den Tempelplatz befestigte,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 50, 2, 'zu dessen Zeit die Mauer gebaut wurde (g), die Ecktürme und die Umfassungsmauer des Heiligtums;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 50, 3, 'in dessen Tagen der Teich gegraben wurde, ein Wasserbecken wie ein Meer mit seiner Fülle (g?);');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 50, 4, 'der für sein Volk sorgte gegen die Räuberei (g) und die Hauptstadt gegen Belagerung befestigte.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 50, 5, 'Wie herrlich war er beim Umzug des Volkes,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 50, 6, 'wenn er hinter dem Vorhang [des Tempels] hervortrat! wie der Morgenstern zwischen Wolken hervor und wie der Vollmond an den Tagen des Festes;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 50, 7, 'wie die Sonne, die auf den Tempel des Höchsten herabscheint, und wie der Regenbogen, der im Gewölk sichtbar wird;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 50, 8, 'wie eine Rosenblüte in der Frühlingszeit und wie Lilien an Wasserläufen; wie die Pflanzenpracht des Libanon zur Sommerzeit');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 50, 9, 'und wie das Weihrauchfeuer über der Räucherpfanne; wie ein goldenes Gefäß ganz in getriebener Arbeit, geziert mit allerlei Edelgestein;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 50, 10, 'wie ein Ölbaum, der mit Früchten prangt, und wie eine Zypresse, die zu den Wolken emporragt (h).');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 50, 11, 'Wenn er die Ehrengewänder anlegte und in den ganzen Schmuck sich kleidete; wenn er hinaufstieg zum heiligen Vater und den Vorhof des Heiligtums verherrlichte;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 50, 12, 'wenn er die Fleischstücke aus der Hand seiner Brüder (g) nahm und er selbst an der Feuerstelle des Altars stand (h), rings um ihn der Kranz seiner Söhne (g) wie Zedernschößlinge auf dem Libanon, und ihn umringten wie Weiden am Bach');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 50, 13, 'alle Söhne Aarons in ihrem Schmuck und die Feueropfer des Herrn waren in ihren Händen vor der ganzen Gemeinde Israel,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 50, 14, 'bis er den Dienst am Altar vollständig besorgt und die Holzstöße des Höchsten geschichtet hatte');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 50, 15, 'und er seine Hand nach der Opferschale ausstreckte und die Spende von Traubenblut darbrachte und sie an den Untersatz des Altars ausgoß zum lieblichen Wohlgeruch für den Höchsten, den Allkönig: –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 50, 16, 'dann stießen die Söhne Aarons in die Trompeten von getriebener Arbeit; sie bliesen und ließen einen gewaltigen Schall ertönen, um das Volk vor dem Höchsten in Erinnerung zu bringen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 50, 17, 'Dann beeilte sich das ganze Volk allzumal und fiel auf sein Angesicht zur Erde nieder, um anzubeten vor dem Herrn, dem allmächtigen Gott, dem Allerhöchsten (h).');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 50, 18, 'Und die Sänger ließen ihre Stimme erschallen, und im weiten Haus ertönte süß ihr Lied (h);');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 50, 19, 'und es jubelte das ganze Volk des Landes im Gebet vor dem Allerbarmer, bis er den Dienst des Herrn vollendet und, was ihm gebührte, dargebracht hatte (g).');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 50, 20, 'Dann stieg er herab und erhob seine Hände über die ganze Gemeinde der Israeliten, und der Segen des Herrn war auf seinen Lippen, und des Namens des Herrn rühmte er sich;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 50, 21, 'dann fielen sie zum zweitenmal nieder, um den Segen vom Höchsten zu empfangen (h).');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 50, 22, 'Und nun preist den Gott des Weltalls, der Großes vollbringt überall oder auf Erden (g), der unsere Tage beglückt vom Mutterleibe an und mit uns verfährt nach seiner Barmherzigkeit!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 50, 23, 'Er gebe uns Freude ins Herz (h) und lasse Frieden in unseren Tagen in Israel herrschen wie in den Tagen der Vorzeit (h).');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 50, 24, 'Möge seine Gnade beständig bei Simon bleiben [und er den Pinehasbund für ihn aufrecht halten, daß er weder ihm je gebrochen werde] noch seinen Nachkommen, solange der Himmel steht!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 50, 25, 'Gegen zwei Völker empfindet mein Herz Abscheu, und das dritte ist kein Volk:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 50, 26, 'die Bewohner des Gebirges Seir und die Philister und das törichte Volk, das in Sichem wohnt.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 50, 27, 'Einsichtsvolle und verständige Lehre habe ich in diesem Buche aufgezeichnet, ich Jesus, Sirachs Sohn von Jerusalem, der Weisheit aus seinem Herzen hervorströmen ließ (h).');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 50, 28, 'Heil dem Manne, der darüber nachdenkt! und wer’s zu Herzen nimmt; wird weise werden;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 50, 29, 'denn wenn er danach handelt, wird er Kraft zu allem haben, weil das Licht des Herrn seine Spur ist.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 50, 30, '');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 50, 31, '');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 51, 1, 'Preisen will ich dich, o Herr, du König, ich will dich loben, du Gott meines Heils! ich will deinen Namen preisen, [du Hort meines Lebens]!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 51, 2, 'denn Beschützer und Helfer bist du mir geworden und hast meinen Leib vor der Grube (g) bewahrt [und meinen Fuß der Gewalt der Unterwelt entrissen (g)] und mich aus der Schlinge der verleumderischen Zunge gerettet; vor den Lippen derer, die mit Lügen umgehen, hast du mich beschützt und bist mir ein Helfer gegen meine Widersacher gewesen;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 51, 3, 'und du hast mich gerettet nach der Fülle deines Erbarmens aus der Schlinge derer, die mich zu verschlingen gedachten, aus der Gewalt derer, die mir nach dem Leben trachteten, aus den vielen Nöten, die ich erlitt,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 51, 4, 'von der Erstickung durch den Brand rings um mich her und mitten aus dem Feuer, das ich nicht angezündet hatte,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 51, 5, 'aus der Tiefe des Schoßes der Unterwelt, von der unreinen Zunge und den lügnerischen Reden, von den Pfeilen (g) der falschen Zunge.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 51, 6, 'Meine Seele war bis in die Nähe des Todes gekommen, und mein Leben war dem Totenreich drunten nahe:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 51, 7, 'da wandte ich mich nach allen Seiten (g), doch da war kein Helfer, und ich blickte aus nach einer Stütze von Menschen, doch ich fand keine.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 51, 8, 'Da gedachte ich deiner Barmherzigkeit, o Herr, und deines Waltens von Ewigkeit her, daß du die rettest, die auf dich hoffen, und sie aus der Gewalt ihrer Feinde rettest.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 51, 9, 'Da ließ ich von der Erde mein Flehen aufsteigen und betete um Errettung vom Tode.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 51, 10, 'Ich rief den Herrn an, den Vater meines Herrn, daß er mich nicht verlasse in den Tagen der Trübsal, zur Zeit der Übermütigen in meiner Hilflosigkeit.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 51, 11, 'Loben will ich deinen Namen immerdar und dir lobsingen mit Danksagung. Da hörte der Herr auf meine Stimme und achtete auf mein Flehen (g);');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 51, 12, 'und er befreite mich aus allem Übel (g) und errettete mich zur Zeit der Not. Darum will ich dir danken und dir lobsingen und preisen den Namen des Herrn.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 51, 13, 'Als ich noch jung war, bevor ich auf Reisen ging, sucht ich die Weisheit sehnlich in meinem Gebet.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 51, 14, 'Vor dem Tempel bat ich um sie, und bis ans Ende will ich nach ihr trachten.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 51, 15, 'Sie erblühte gleich einer reifenden Traube, und mein Herz freute sich an ihr. Unter ihrer Leitung schritt mein Fuß auf gerader Bahn dahin; von meiner Jugendzeit an ging ich ihrer Spur nach.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 51, 16, 'Kaum hatte ich ihr mein Ohr geliehen, so nahm ich sie auf und gewann reiche Erkenntnis.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 51, 17, 'Fortschreiten ward mir durch sie zuteil; dem der mir Weisheit beibrachte, will ich Anerkennung zollen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 51, 18, 'Ich war dann darauf bedacht, sie zu betätigen; ich war eifrig bemüht, gut zu handeln, und wurde nicht zuschanden (g).');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 51, 19, 'Meine Seele hat um sie gerungen, und in meinem ganzen Tun verfuhr ich mit Sorgfalt (h); meine Hände streckte ich zum Himmel aus und trauerte über meine Verfehlungen gegen sie.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 51, 20, 'Ich richtete meinen Sinn auf sie und fand sie durch Reinheit (meines Herzens); Einsicht (g) gewann ich mit ihrer Unterstützung von Anfang an; darum will ich nie wieder von ihr lassen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 51, 21, 'Mein Inneres ward erregt, nach ihr zu trachten; darum habe ich in ihr einen schönen Besitz erworben.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 51, 22, 'Der Herr hat mir die Zunge als meinen Lohn verliehen; darum will ich ihn mit meinen Lippen preisen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 51, 23, 'Kehrt bei mir ein, ihr Unverständigen, und verweilt in meinem Hause der Belehrung!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 51, 24, 'wie lange noch (g) wollt ihr Mangel daran leiden und sollen eure Seelen heiß danach dürsten?');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 51, 25, 'Ich habe meinen Mund aufgetan und geredet: kommt, kauft, es kostet kein Geld!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 51, 26, 'Beugt euren Nacken unter das Joch, und eure Seele nehme Belehrung an; nahe ist sie denen, die sie suchen, und wer sich ihr hingibt, findet sie (g).');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 51, 27, 'Seht mit eigenen Augen, daß ich mich nur wenig bemüht und doch viele Ruhe für mich in ihr gefunden habe.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 51, 28, 'Nehmt an der Belehrung teil in großer Zahl und erwerbt euch Silber und Gold durch sie.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 51, 29, 'Eure Seele freue sich seiner Barmherzigkeit, und schämt euch seines Lobpreises nicht!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 51, 30, 'Verrichtet euer Werk vor der Zeit, so wird er euch euren Lohn geben zu seiner Zeit.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 51, 31, '');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 51, 32, '');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 51, 33, '');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 51, 34, '');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 51, 35, '');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 51, 36, '');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 51, 37, '');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 51, 38, '');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 1, 1, 'Dies sind die Worte des Schriftstücks, welches Baruch, der Sohn Nerijas, des Sohnes Maasejas, des Sohnes Zedekias, des Sohnes Asadjas, des Sohnes Hilkias, in Babylon abgefaßt hat');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 1, 2, 'im fünften Jahre, am siebenten Tage des Monats, zur Zeit, da die Chaldäer Jerusalem eingenommen und mit Feuer verbrannt hatten.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 1, 3, 'Baruch las die Worte dieses Schriftstücks vor in Gegenwart Jechonjas, des Sohnes Jojakims, des Königs von Juda, und in Gegenwart des ganzen Volks, das zum Anhören des Schriftstücks gekommen war,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 1, 4, 'und in Gegenwart der Vornehmen und der königlichen Prinzen und der Ältesten und des ganzen Volks, der Kleinen und der Großen, aller derer, die in Babylon wohnten am Flusse Sud.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 1, 5, 'Und sie weinten und fasteten und beteten vor dem Herrn');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 1, 6, 'und brachten Geld zusammen, ein jeder nach seinem Vermögen,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 1, 7, 'und schickten es nach Jerusalem an Jojakim, den Sohn Hilkias, des Sohnes Saloms, den Hohenpriester, und an die anderen Priester und an das ganze Volk, so viele sich bei ihm noch in Jerusalem befanden,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 1, 8, 'als er (Baruch) die Gefäße des Hauses Gottes, die aus dem Tempel weggenommen waren, in Empfang nahm, um sie ins Land Juda zurückzubringen, am zehnten Tage des Siwan, nämlich die silbernen Gefäße, die Zedekia, Josias Sohn, der König von Juda, hatte anfertigen lassen,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 1, 9, 'nachdem Nebukadnezar, der König von Babylon, den Jechonja und die Obersten und die Gefangenen und die Vornehmen und die Bevölkerung des Landes von Jerusalem weggeführt und ihn nach Babylon gebracht hatte.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 1, 10, 'Und sie ließen ihnen dabei sagen: »Seht, wir senden euch Geld; kauft also für das Geld Brandopfer, Sündopfer und Weihrauch, und richtet Speisopfer zu und bringt alles dies auf den Altar des Herrn, unseres Gottes,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 1, 11, 'und betet für das Leben Nebukadnezars, des Königs von Babylon, und für das Leben seines Sohnes Belsazar, daß ihre Tage auf Erden seien wie des Himmels Tage.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 1, 12, 'So wird der Herr uns Kraft verleihen und unsere Augen leuchten lassen, und wir werden leben unter dem Schatten Nebukadnezars, des Königs von Babylon, und unter dem Schatten seines Sohnes Belsazar und werden ihnen viele Tage dienen und Gnade vor ihnen finden.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 1, 13, 'Betet auch für uns zum Herrn, unserm Gott; denn wir haben gesündigt wider den Herrn, unsern Gott, und des Herrn Grimm und Zorn hat sich bis auf diesen Tag nicht von uns abgewandt.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 1, 14, 'Lest auch dies Schreiben, das wir euch senden, um es kundzutun im Hause des Herrn an einem Festtage und an Feiertagen vor');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 1, 15, 'und sprecht also:« Bei dem Herrn, unserm Gott, ist Gerechtigkeit; uns aber bedeckt heute die Schamröte das Angesicht, uns, den Männern von Juda und den Bewohnern Jerusalems,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 1, 16, 'unsern Königen und unsern Obersten, unsern Priestern, unsern Propheten und unsern Vätern,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 1, 17, 'darum daß wir gesündigt haben vor dem Herrn und ihm ungehorsam gewesen sind');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 1, 18, 'und nicht gehört haben auf die Stimme des Herrn, unsers Gottes, zu wandeln nach seinen Geboten, die er uns zur Pflicht gemacht hat.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 1, 19, 'Von dem Tage an, da der Herr unsere Väter aus Ägypten weggeführt hat, bis auf diesen Tag sind wir ungehorsam gewesen gegen den Herrn, unsern Gott, und säumig, auf seine Stimme zu hören.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 1, 20, 'So hat sich denn an uns das Unheil geheftet und der Fluch, den der Herr seinem Knechte Mose aufgetragen hat an dem Tage, da er unsere Väter aus Ägyptenland wegführte, um uns ein Land zu geben, wo Milch und Honig fließt, wie es noch heute der Fall ist.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 1, 21, 'Aber wir haben nicht gehört auf die Stimme des Herrn, unseres Gottes, trotz aller Mahnungen der Propheten, die er zu uns sandte,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 1, 22, 'sondern wir sind alle gewandelt nach dem Sinn unsers bösen Herzens, um fremden Göttern zu dienen und zu tun, was dem Herrn, unserm Gott, mißfiel.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 1, 'Nun aber hat der Herr sein Wort wahr gemacht, das er wieder uns und unsere Richter, die Israel gerichtet haben, und wider unsere Könige und Obersten und wider die Leute von Israel und Juda ausgesprochen hatte,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 2, 'daß er über uns großes Unheil kommen lassen wolle, wie solches noch nie unter dem ganzen Himmel geschehen sei, aber zu Jerusalem geschehen ist, wie es ja auch im Gesetz Mose’s geschrieben steht,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 3, 'daß wir essen sollten ein jeglicher seines Sohnes Fleisch und ein jeglicher seiner Tochter Fleisch.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 4, 'Und er gab sie in die Gewalt aller dieser Königreiche rings um uns her, zu einem Gegenstand der Schmach und des Abscheus unter allen Völkern im Umkreis, wohin der Herr sie zerstreute.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 5, 'So ging es denn mit ihnen abwärts und nicht aufwärts, weil wir gesündigt hatten wider den Herrn, unsern Gott, indem wir auf seine Stimme nicht hörten.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 6, 'Beim Herrn, unserm Gott, ist Gerechtigkeit; uns aber und unsern Vätern bedeckt heute die Schamröte das Angesicht.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 7, 'Was der Herr uns angedroht hat, all dieses Unheil ist über uns gekommen;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 8, 'und dennoch haben wir uns nicht an den Herrn mit der Bitte gewandt, er möge einen jeden von den Anschlägen seines bösen Herzens bekehren.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 9, 'Und so war denn der Herr auf das Unheil bedacht und hat es über uns kommen lassen; denn gerecht ist der Herr in all seinem Tun, das er uns anbefohlen hat.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 10, 'Doch wir haben nicht auf seine Stimme gehört, daß wir wandelten nach des Herrn Geboten, die er uns vorgelegt hat.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 11, 'Und nun, Herr, Gott Israels, der du dein Volk aus Ägyptenland herausgeführt hast mit starker Hand und unter Zeichen und Wundern und mit großer Kraft und erhobenem Arm und dir dadurch einen Namen bis auf den heutigen Tag gemacht hast:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 12, 'wir haben gesündigt, sind gottlos gewesen und haben Unrecht getan, Herr, unser Gott, in bezug auf alle deine gerechten Forderungen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 13, 'Es wende doch dein Zorn sich von uns ab! denn nur wenige sind von uns übriggeblieben unter den Völkern, wohin du uns zerstreut hast.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 14, 'Erhöre, Herr, unser Gebet und unser Flehen, errette uns um deinetwillen und laß uns Gnaden finden bei denen, die uns weggeführt haben,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 15, 'auf daß die ganze Erde erkenne, daß du der Herr, unser Gott, bist und daß Israel und sein Geschlecht nach deinem Namen benannt worden ist.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 16, 'Herr, blicke herab aus deiner heiligen Wohnung und richte auf uns dein Augenmerk! neige, Herr, dein Ohr und höre!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 17, 'Tue auf, o Herr, deine Augen und sieh! denn nicht die Gestorbenen in der Unterwelt, deren Geist aus ihrem Leibe entschwunden ist, werden dem Herrn die gebührende Ehre darbringen,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 18, 'sondern die tiefbetrübte Seele und was da gebückt und in Schwachheit einhergeht, und die verschmachtenden Augen und die hungernde Seele: – die werden dir die gebührende Ehre darbringen, o Herr.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 19, 'Denn nicht wegen des Rechttuns unserer Väter und unserer Könige schütten wir unser Flehen hin vor dein Angesicht, Herr, unser Gott;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 20, 'denn du hast deinen Grimm und Zorn wider uns losgelassen, wie du es angedroht hattest durch deine Knechte, die Propheten, mit den Worten:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 21, '»So spricht der Herr: Beugt euren Rücken, dem Könige von Babylon zu gehorchen, so werdet ihr wohnen bleiben in dem Lande, das ich euren Vätern gegeben habe!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 22, 'Wenn ihr aber nicht hören wollt auf die Stimme des Herrn, daß ihr dienet dem Könige von Babylon,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 23, 'so werde ich aufhören machen in den Städten Juda’s und in Jerusalem die Stimme der Freude und der Lust, die Stimme des Bräutigams und der Braut, und das ganze Land soll zur Wüstenei werden ohne Bewohner!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 24, 'Aber wir haben deiner Weisung, dem Könige von Babylon zu dienen, nicht gehorcht; darum hast du deine Drohung wahr gemacht, die du durch deine Knechte, die Propheten, ausgesprochen hattest, daß unserer Könige und unserer Väter Gebeine herausgeholt werden sollten aus ihrer Grabstätte.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 25, 'Und fürwahr, sie sind hingeworfen und preisgegeben worden der Hitze des Tages und dem Frost der Nacht; und (jene) sind in schweren Mühsalen umgekommen durch Hunger und Schwert und Verbannung.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 26, 'Und das Haus, wo dein Name angerufen wurde, hast du zu dem gemacht, was es heute ist, wegen der Bosheit des Hauses Israel und des Hauses Juda.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 27, 'An uns aber, Herr, unser Gott, hast du gehandelt nach deiner ganzen Milde und nach all deiner großen Barmherzigkeit,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 28, 'wie du es verheißen hast durch deinen Knecht Mose an dem Tag, da du ihm vor den Kindern Israel gebotest, dein Gesetz aufzuschreiben, indem du sprachst:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 29, '»Wenn ihr nicht auf meine Stimme hört, so wird fürwahr diese große, zahlreiche Volksmenge zu einem kleinen Häuflein werden unter den Heiden, wohin ich sie zerstreuen werde.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 30, 'Denn ich weiß, daß sie auf mich nicht hören werden; denn es ist ein halsstarriges Volk. Doch im Lande ihrer Verbannung werden sie sich bekehren in ihrem Herzen');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 31, 'und werden erkennen, daß ich der Herr, ihr Gott, bin, und dann werde ich ihnen ein Herz geben und Ohren, willig zu hören,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 32, 'und sie werden mich loben im Lande ihrer Verbannung und meines Namens gedenken');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 33, 'und sich bekehren von ihrer Halsstarrigkeit und von ihren bösen Taten; denn sie werden daran gedenken, wie es ihren Vätern ergangen ist, die vor dem Herrn sündigten.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 34, 'Und dann will ich sie zurückbringen in das Land, das ich ihren Vätern, dem Abraham, Isaak und Jakob, zugeschworen habe, und sie sollen es als Herren besitzen; und ich will sie mehren, und sie sollen nicht mehr vermindert werden.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 35, 'Und ich will einen ewigen Bund mit ihnen schließen, daß ich ihr Gott sei und sie mein Volk, und ich will mein Volk Israel nie wieder vertreiben aus dem Lande, das ich ihnen gegeben habe«.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 3, 1, 'Allmächtiger Herr, Gott Israels! Eine bedrängte Seele und ein bekümmerter Geist schreit zu dir!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 3, 2, 'Höre, Herr, und erbarme dich! denn wir haben gegen dich gesündigt.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 3, 3, 'Ja, du thronst auf ewig, wir aber, wir gehen auf ewig zugrunde.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 3, 4, 'Allmächtiger Herr, Gott Israels! Erhöre doch das Gebet der Erstorbenen Israels und der Söhne derer, die gegen dich gesündigt, die nicht auf deine, ihres Gottes, Stimme gehört haben und die darum das Unheil dauernd verfolgt hat.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 3, 5, 'Gedenke nicht der Missetat unserer Väter, gedenke vielmehr deines starken Armes und deines Namens zu dieser Zeit!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 3, 6, 'denn du bist der Herr, unser Gott, und wir wollen dich preisen, o Herr.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 3, 7, 'Denn darum hast du deine Furcht in unsre Herzen gegeben und uns dazu getrieben, deinen Namen anzurufen. Und wir wollen dich preisen in unserer Verbannung, weil wir aus unseren Herzen entfernt haben alles Unrecht unserer Väter, die wider dich gesündigt haben.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 3, 8, 'Siehe, wir sind heute noch im Lande unserer Verbannung, wohin du uns zerstreut hast zur Schmach und zum Fluch und zur Büßung für alle Missetaten unserer Väter, die vom Herrn, unserm Gott, abgefallen sind.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 3, 9, 'Höre, Israel, die Gebote des Lebens; merkt auf, damit ihr Einsicht lernt!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 3, 10, 'Wie ist’s, Israel? wie kommt’s, daß du im Lande der Feinde bist? Alt bist du geworden im fremden Lande, hast dich verunreinigt zusamt den Toten,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 3, 11, 'bist zugezählt den in die Unterwelt Gefahrenen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 3, 12, 'Du hast verlassen die Quelle der Weisheit.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 3, 13, 'Wärst du auf Gottes Wegen gewandelt, so würdest du daheim in Frieden wohnen für ewige Zeit.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 3, 14, 'Lerne, wo Weisheit, wo Stärke, wo Einsicht ist, um zugleich zu erkennen, wo langes Dasein und Leben ist, wo Erleuchtung der Augen und Frieden!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 3, 15, 'Wer hat ihre Wohnstätte gefunden, und wer ist zu ihren Schätzen gedrungen?');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 3, 16, 'Wo sind die Herrscher der Völker und die Herren der Tiere auf Erden?');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 3, 17, 'die da spielten mit den Vögeln des Himmels und das Silber und das Gold aufhäuften, worauf die Menschen ihr Vertrauen setzen und wonach sie ohne Ende trachten?');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 3, 18, 'Denn die da Gold aufschichten und darauf ihre Sorge richten und deren Werke unausforschlich sind: –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 3, 19, 'verschwunden sind sie und in die Unterwelt hinabgefahren, und andere sind an ihre Stelle getreten.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 3, 20, 'Jüngere sahen das Licht und bewohnten die Erde, aber den Weg zur Einsicht erkannten sie nicht,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 3, 21, 'noch verstanden sie ihre Pfade; auch ihre Söhne erfaßten sie nicht, sondern blieben fern von dem Wege zu ihr.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 3, 22, 'Auch in Kanaan hat man nicht von ihr gehört und in Theman sie nicht gesehen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 3, 23, 'Auch die Söhne Hagars, die weltliche Einsicht suchen, die Kaufleute von Meran und Theman, und die Erdichter von Fabeln und die nach Einsicht Strebenden: – den Weg zur Weisheit haben sie nicht gekannt und von ihren Pfaden keine Kunde gehabt.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 3, 24, 'O Israel, wie groß ist Gottes Haus und wie weit die Stätte seines Besitzes!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 3, 25, 'groß und ohne Ende, hoch und unermeßlich!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 3, 26, 'Dort wurden geboren die Riesen, die berühmten, die uralten, die hochgewachsenen, kriegskundigen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 3, 27, 'Nicht diese hat Gott erkoren, nicht ihnen den Weg zur Weisheit gezeigt;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 3, 28, 'nein, sie kamen um, weil sie keine Erkenntnis besaßen, sie kamen um durch ihre Torheit.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 3, 29, 'Wer ist zum Himmel hinaufgestiegen und hat sie geholt und sie herniedergebracht aus den Wolken?');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 3, 30, 'Wer ist über das Meer gefahren und hat sie gefunden, daß er sie herbeibringe für kostbares Gold?');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 3, 31, 'Da ist keiner, der den Weg zu ihr wüßte, keiner, der den Pfad zu ihr wahrnähme.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 3, 32, 'Nur der Allwissende kennt sie, durch seine Einsicht hat er sie gefunden, er, der die Erde geschaffen für ewige Zeit und sie bevölkert hat mit vierfüßigen Tieren;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 3, 33, 'der den Blitz entsendet, und er bricht hervor, der ihm ruft, und er gehorcht mit Zittern.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 3, 34, 'Die Sterne leuchteten auf ihren Wachtposten und waren fröhlich; er rief sie, und sie sagten: »Hier sind wir!«; mit Freuden leuchteten sie ihrem Schöpfer.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 3, 35, 'Das ist unser Gott; kein anderer gilt neben ihm.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 3, 36, 'Er hat jeglichen Weg zur Erkenntnis ausfindig gemacht und hat sie Jakob, seinem Knechte, und Israel, seinem Geliebten, verliehen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 3, 37, 'Seitdem ist sie auf Erden erschienen und unter den Menschen gewandelt.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 3, 38, '');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 1, 'Sie ist das Buch von Gottes Geboten und das Gesetz, das in Ewigkeit gilt: alle, die an ihr festhalten, kommen zum Leben, aber sterben werden die, welche sie verlassen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 2, 'Bekehre dich, Jakob, und ergreife sie! wandle zu dem Glanze, der vor ihrem Licht ist!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 3, 'Gib keinem anderen deine Ehre preis, noch was dir frommt, einem fremden Volke!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 4, 'Wohl uns Israeliten, daß uns bekannt ist, was Gott wohlgefällt!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 5, 'Fasse Mut, mein Volk, du Überrest Israels!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 6, 'Verkauft seid ihr an die Heiden, aber nicht zum Untergang; nein, weil ihr Gott erzürnt habt, seid ihr euren Widersachern preisgegeben worden;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 7, 'weil ihr den erbittert habt, der euch geschafft hat, weil ihr Dämonen geopfert habt und nicht Gott.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 8, 'Vergessen hattet ihr den ewigen Gott, der euch ernährte; aber auch Jerusalem habt ihr betrübt, das euch großgezogen hatte;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 9, 'denn es sah den von Gott auf euch herabkommenden Zorn und sprach klagend: »Hört ihr, die ihr um Zion wohnt! denn Gott hat großes Leid über mich gebracht;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 10, 'denn ich habe die Wegführung meiner Söhne und Töchter gesehen, die der Ewige über sie verhängt hat.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 11, 'Ach mit Freuden hatte ich sie großgezogen, aber mit Klage und Trauer habe ich sie wegziehen lassen!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 12, 'Niemand möge sich freuen über mich, die ich Witwe geworden und von so vielen verlassen bin! Ich bin einsam geworden wegen der Sünden meiner Kinder, weil sie abgewichen waren von Gottes Gesetz,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 13, 'und seiner Satzungen nicht achteten und auf den Wegen der Gebote Gottes nicht wandelten und die Pfade der Zucht nicht in seiner Gerechtigkeit betraten.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 14, 'Kommt, die ihr um Zion her wohnt, und gedenkt der Gefangenschaft meiner Söhne und Töchter, die der Ewige über sie verhängt hat.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 15, 'Denn er hat gegen sie ein Volk von fern hergeführt, ein freches Volk mit fremder Sprache, das weder Scheu vor Greisen noch Mitleid mit Kindern hatte;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 16, 'die haben die Lieblinge der Witwe weggeschleppt und die Vereinsamte ihrer Töchter beraubt!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 17, 'Ich aber, wie vermöchte ich euch zu helfen?');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 18, 'Denn nur er, der das Unheil herbeigeführt hat, wird euch aus der Hand eurer Feinde befreien.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 19, 'Zieht von dannen, ihr Kinder, zieht fort, denn ich muß vereinsamt hier zurückbleiben.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 20, 'Ausgezogen habe ich das Gewand des Friedens und angezogen das Trauerkleid meines Flehens. Schreien will ich zum Ewigen alle Tage!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 21, 'Habt Mut, Kinder! schreiet zu Gott, daß er euch errette aus der Gewaltherrschaft, aus der Hand der Feinde!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 22, 'Denn ich, ich erhoffe vom Ewigen euer Heil, und Freude ist mir vom Heiligen zuteil geworden ob der Erbarmung, die euch in Bälde widerfahren wird von eurem ewigen Erretter.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 23, 'Denn mit Weinen und Wehklagen habe ich euch ziehen lassen, aber Gott wird euch mir zurückgeben mit Wonne und Freude in Ewigkeit.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 24, 'Denn gleichwie jetzt die Nachbarstädte Zions eure Wegführung gesehen haben, so werden sie in Bälde eure Errettung durch Gott schauen, die euch zuteil werden wird mit großer Pracht und Herrlichkeit des Ewigen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 25, 'Kinder, ertragt mit Geduld den von Gott über euch gekommenen Zorn; verfolgt hat dich der Feind, aber du wirst seine Vernichtung in Kürze schauen und ihnen den Fuß auf den Nacken setzen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 26, 'Meine zarten Kindlein haben rauhe Wege wandeln müssen, sind weggeführt worden, gleich einer von Feinden geraubten Herde.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 27, 'Seid mutig, meine Kinder, und schreiet zu Gott! denn er, der dies über euch verhängt hat, wird euer gedenken.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 28, 'Jedoch wie euer Sinn darauf gerichtet gewesen ist, von Gott abzufallen, so seid jetzt zehnfach eifriger, ihn zu suchen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 29, 'Denn der das Unheil über euch verhängt hat, wird auch mit eurer Rettung ewige Freude über euch bringen«.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 30, 'Fasse Mut, Jerusalem! es wird dich trösten, der dir den Namen gegeben hat.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 31, 'Wehe denen, die dir Böses erwiesen und sich gefreut haben über deinen Fall!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 32, 'Wehe den Städten, denen deine Kinder als Sklaven haben dienen müssen! Wehe der Stadt, die deine Söhne aufgenommen hat!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 33, 'Denn wie sie ob deiner Niederlage sich gefreut und ob deines Falles frohlockt hat, also soll sie trauern müssen bei ihrer eigenen Verödung.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 34, 'Und wegnehmen will ich ihre Freude an ihrem zahlreichen Volke und will ihren Stolz in Trauer verwandeln.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 35, 'Denn Feuer wird über sie kommen vom Ewigen auf lange Tage hin, und sie soll von bösen Geistern bewohnt werden für lange Zeit.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 36, 'Schaue umher nach Osten, Jerusalem, und sieh die Freude, die von Gott zu dir kommt!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 37, 'Siehe, es kommen deine Kinder, die du hast ziehen lassen; sie kommen geschart vom Aufgang bis zum Niedergang auf das Geheiß des Heiligen und freuen sich der Herrlichkeit Gottes.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 1, 'Lege ab, Jerusalem, das Gewand deiner Trauer und deines Elends, und ziehe den Schmuck der Herrlichkeit an, die Gott dir verleiht für ewige Zeiten!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 2, 'Hülle dich in den Mantel der Gerechtigkeit, die Gott verleiht, setze auf dein Haupt den Kopfbund der Herrlichkeit des Ewigen!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 3, 'Denn Gott wird deinen Glanz offenbar machen der ganzen Erde unter dem Himmel;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 4, 'denn dein Name wird auf ewig von Gott genannt werden »Friede der Gerechtigkeit« und »Herrlichkeit der Gottesfurcht«.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 5, 'Erhebe dich, Jerusalem, und tritt auf die Höhe, und schaue umher nach Osten und sieh deine Kinder versammelt von Sonnenuntergang bis zum Aufgang auf das Geheiß des Heiligen, sich freuend, daß Gott ihrer gedacht hat!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 6, 'Denn zu Fuß sind sie von dir weggezogen, von Feinden getrieben; aber Gott führt sie zu dir zurück, wie einen Königsthron getragen mit Ehren!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 7, 'Denn Gott hat geboten, daß erniedrigt werde jeder hohe Berg und die ewigen Hügel, und daß die Schluchten ausgefüllt werden zu ebenem Lande, auf daß Israel sicher wandere in der Herrlichkeit Gottes.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 8, 'Es beschatteten aber Israel auch die Wälder und allerlei duftendes Gehölz auf Gottes Befehl.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 9, 'Denn Gott wird Israel geleiten mit Freude im Licht seiner Herrlichkeit, mit Gnade und Gerechtigkeit, die er verleiht.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 6, 1, 'Abschrift des Briefes, welchen Jeremia an die Gefangenen, die vom König der Babylonier nach Babylon geführt werden sollten, gesandt hat, ihnen zu verkünden, wie es ihm von Gott aufgetragen war.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 6, 2, 'Um der Sünden willen, die ihr gegen Gott begangen habt, werdet ihr gefangen nach Babylon geführt werden von Nebukadnezar, dem König der Babylonier.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 6, 3, 'Wenn ihr nun in Babylon angekommen seid, werdet ihr dort viele Jahre zubringen und eine lange Zeit, bis auf sieben Geschlechter. Darnach werde ich euch von dort wieder wegführen in Frieden.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 6, 4, 'Nun werdet ihr aber in Babylon Götzen von Silber, Gold und Holz sehen, die man auf den Schultern trägt und die den Heiden Furcht einflößen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 6, 5, 'Hütet euch also, daß nicht auch ihr den Fremden gleich werdet und auch euch Furcht vor jenen erfasse, wenn ihr das Volk sie von vorn und von hinten anbeten seht;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 6, 6, 'denkt vielmehr bei euch: »Dich muß man anbeten, o Herr!«.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 6, 7, 'Denn mein Engel ist bei euch und sucht euer Leben zu bewahren. ###Darlegung der Torheiten des Götzendienstes (V.8-73)');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 6, 8, 'Denn ihre Zunge ist vom Künstler geschnitzt; sie selbst aber, vergoldet und versilbert, sind Lügengebilde und können nicht reden.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 6, 9, 'Wie für eine putzsüchtige Jungfrau nehmen sie Gold und fertigen daraus Kränze für das Haupt ihren Götzen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 6, 10, 'Es kommt aber auch vor, daß die Priester ihren Götzen das Gold und Silber wegnehmen und es für sich selbst verwenden;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 6, 11, 'ja, sie geben davon auch den Huren im Hurenhause. Sie schmücken sie gleich Menschen mit Kleidern, die silbernen Götter und die goldenen und hölzernen Götter;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 6, 12, 'die lassen sich aber nicht vor Rost und Zerfressung bewahren; auch wenn sie mit Purpurgewändern umhüllt sind,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 6, 13, 'muß man ihnen doch das Gesicht abwischen wegen des Staubes im Hause, der dick auf ihnen liegt.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 6, 14, 'Mancher führt auch ein Zepter, als wäre er Regent im Lande, aber wenn jemand sich gegen ihn verfehlt, kann er ihm nichts anhaben.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 6, 15, 'Auch ein Schlachtschwert hält er in der Rechten oder ein Beil, und doch kann er sich weder des Krieges noch der Räuber erwehren.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 6, 16, 'Daher ist es offenbar, daß sie keine Götter sind: fürchtet euch also nicht vor ihnen!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 6, 17, 'Gerade wie das Gesäß eines Menschen, wenn es zerbrochen ist, unbrauchbar wird, so verhält es sich auch mit ihren Göttern. Sind sie in den Tempeln aufgestellt, so werden ihre Augen voll Staubs von den Füßen der Eintretenden.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 6, 18, 'Und wie für einen, der sich an einem Könige vergangen hat, die Höfe verschlossen sind, wie für einen zum Tode Abgeführten, so verwahren die Priester ihre Behausungen mit Toren, Schlössern und Riegeln, damit sie von den Räubern nicht geplündert werden.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 6, 19, 'Lichter zünden sie vor ihnen an, ja mehr als für sich selbst, von denen jene doch kein einziges zu sehen vermögen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 6, 20, 'Er ist wie einer der Balken am Hause; ihr Inneres, sagt man, wird zerfressen; vom Gewürm der Erde, das sie und ihre Kleider verzehrt, spüren sie nichts.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 6, 21, 'Geschwärzt ist ihr Angesicht vom Rauche im Tempel;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 6, 22, 'auf ihren Körper und Kopf fliegen Nachteulen, Schwalben und andere Vögel hinauf, desgleichen setzen sich auch Katzen darauf.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 6, 23, 'Daraus werdet ihr erkennen, daß sie keine Götter sind: fürchtet euch also nicht vor ihnen!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 6, 24, 'Ja, wenn man von dem Golde, mit dem sie zum Schmuck überzogen sind, den Rost nicht abwischt, so glänzen sie nicht; denn sie spürten es ja auch nicht, als sie gegossen wurden.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 6, 25, 'Um jeden Preis hat man sie gekauft, sie, in denen doch kein Lebenshauch wohnt!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 6, 26, 'Der Füße nicht mächtig, müssen sie auf den Schultern von Männern getragen werden, denen sie so ihre Nichtigkeit zeigen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 6, 27, 'Es schämen sich aber auch die, welche sie bedienen; denn wenn einmal einer von ihnen zu Boden fällt, kann er von selbst nicht wieder aufstehen; und stellt man ihn aufrecht, so bewegt er sich nimmer von selbst; gerät er in eine schiefe Lage, so kann er sich nicht wieder aufrichten; ja wie Toten legt man ihnen ihre Gaben vor.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 6, 28, 'Was geopfert wird, verbrauchen ihre Priester, indem sie es verkaufen; desgleichen salzen auch ihre Weiber davon ein, ohne Armen oder Kranken etwas abzugeben;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 6, 29, 'selbst unreine Frauen und Wöchnerinnen rühren ihre Opfer an. Habt ihr nun aus allem diesem erkannt, daß sie keine Götter sind, so fürchtet euch nicht vor ihnen!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 6, 30, 'Wie könnten sie denn auch Götter genannt werden? Es sind ja sogar Weiber, die den silbernen, goldenen und hölzernen Göttern die Speisen vorsetzen;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 6, 31, 'und in ihren Tempeln sitzen auf Stühlen die Priester mit zerrissenen Kleidern und geschorenen Köpfen und Bärten, und ihre Häupter sind dabei unbedeckt;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 6, 32, 'sie schreien und heulen vor ihren Göttern, wie man beim Leichenmahl zu tun pflegt.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 6, 33, 'Von ihren Gewändern nehmen sich die Priester und bekleiden damit ihre Weiber und Kinder.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 6, 34, 'Mögen sie Böses von jemandem erfahren oder Gutes: sie werden es nicht vergelten können; sie können einen König weder einsetzen noch absetzen;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 6, 35, 'desgleichen können sie weder Reichtum verleihen noch bares Geld schenken. Gelobt einer ihnen ein Gelübde und hält es nicht: sie werden es nimmer einfordern.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 6, 36, 'Vom Tode können sie keinen Menschen erretten, noch einen Schwächeren dem Stärkeren entreißen;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 6, 37, 'einem Blinden können sie das Gesicht nicht wiedergeben, auch einen in Not Befindlichen nicht erretten.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 6, 38, 'Einer Witwe können sie sich nicht erbarmen und einem Waisenkinde nicht wohltun.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 6, 39, 'Den roh aus dem Berge gebrochenen Steinen gleichen sie, die hölzernen, vergoldeten und versilberten Götzen, und ihre Diener müssen zu Schanden werden.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 6, 40, 'Wie kann man also glauben oder behaupten, daß sie wirklich Götter seien, da obendrein auch die Chaldäer selbst sie verunehren?');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 6, 41, 'Wenn diese einen Stummen sehen, der nicht reden kann, so bringe sie ihren Bel herbei und verlangen, daß jener rede, als ob er imstande wäre, sie zu vernehmen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 6, 42, 'Und obgleich sie dies selbst einsehen, sind sie doch nicht imstande, die Götzen fahren zu lassen, denn sie haben kein Verständnis.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 6, 43, 'Die Weiber, mit Binden umwunden, sitzen an den Wegen und räuchern mit Kleie; wird dann eine von ihnen von einem Vorbeigehenden mitgenommen und beschlafen, so verspottet sie ihre Nachbarin, weil diese noch nicht gleich ihr wert erfunden worden und ihre Binde unzerrissen geblieben ist.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 6, 44, 'Alles, was bei ihnen geschieht, ist Lügenwerk: wie kann man also glauben oder behaupten, daß dies Götter seien?');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 6, 45, 'Von Künstlern und Goldschmieden sind sie gearbeitet und können gar nichts anderes werden, als wozu die Werkleute sie bestimmt haben.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 6, 46, 'Nun sind die, welche sie verfertigt haben, selbst nicht von langer Lebensdauer: wie sollte es mit ihren Gebilden anders sein?');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 6, 47, 'Ja, nur Trug und Schmach hinterlassen sie ihren Nachkommen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 6, 48, 'Denn wenn Krieg oder sonst ein Unheil über sie kommt, beratschlagen die Priester untereinander, wo sie sich mit ihnen verstecken sollen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 6, 49, 'Wie kann man da nicht einsehen, daß sie keine Götter sind, sie, die nicht einmal sich selbst aus Krieg und Unheil erretten können?');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 6, 50, 'Denn da sie hölzern und vergoldet und versilbert sind, wird man schließlich erkennen, daß sie Lügengebilde sind.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 6, 51, 'Allen Heiden und Königen wird es klar werden, daß sie keine Götter sind, sondern nur Machwerke von Menschenhand, und daß nichts von Gotteswerk bei ihnen zu finden ist.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 6, 52, 'Wem wird da nicht offenbar, daß sie keine Götter sind?');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 6, 53, 'Denn weder vermögen sie einen König über ein Land einzusetzen, noch den Menschen Regen zu geben;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 6, 54, 'weder Recht zu sprechen vermögen sie in eigener Sache, noch jemand gegen eine Freveltat zu schützen in ihrer Ohnmacht; denn wie Krähen sind sie, die mitten zwischen Himmel und Erde fliegen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 6, 55, 'Ja, wenn einmal Feuer im Tempel der hölzernen, vergoldeten und versilberten Götter ausbricht, so ergreifen ihre Priester die Flucht und bringen sich in Sicherheit; sie selbst aber müssen wie Balken ganz und gar verbrennen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 6, 56, 'Einem Könige aber und Feinden leisten sie niemals Widerstand. Wie soll man da annehmen und glauben, daß sie Götter seien?');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 6, 57, 'Weder vor Dieben, noch vor Räubern vermögen diese hölzernen, versilberten und vergoldeten Götter sich zu schützen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 6, 58, 'Wenn diese sie in ihre Gewalt bekommen, nehmen sie ihnen das Silber und Gold und die Gewandung weg, womit sie bekleidet sind, und gehen damit auf und davon; sie selbst aber können sich nicht helfen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 6, 59, 'Darum ist ein König besser daran, der seine Tapferkeit beweist, oder ein dem Hausbesitzer nutzbringendes Hausgerät, als die Lügengötter; mehr wert ist auch die Tür am Hause, die das darin Befindliche verwahrt, als die Lügengötter; mehr auch eine hölzerne Säule im Königspalast als die Lügengötter.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 6, 60, 'Ja, Sonne, Mond und Sterne, die hell leuchten und dazu bestimmt sind, sich nützlich zu erweisen, leisten Gehorsam;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 6, 61, 'desgleichen ist auch der Blitz, wenn er aufleuchtet, schön anzusehen; und derselbe Wind weht in jedem Lande;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 6, 62, 'und die Wolken, wenn ihnen von Gott befohlen wird, über die ganze Erde hinzuziehen, vollbringen das ihnen Befohlene;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 6, 63, 'auch das Feuer, wenn es von oben entsandt wird, Berge und Wälder zu verzehren, vollführt das ihm Befohlene. Diese aber sind ihnen weder an Aussehen noch an Kräften vergleichbar.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 6, 64, 'Daher kann man weder glauben noch behaupten, daß sie Götter seien, weil sie weder Gericht zu halten noch den Menschen wohlzutun imstande sind.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 6, 65, 'Wenn ihr nun erkannt habt, daß sie keine Götter sind, so fürchtet euch nicht vor ihnen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 6, 66, 'Denn Königen vermögen sie weder zu fluchen noch sie zu segnen,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 6, 67, 'auch Zeichen am Himmel können sie unter den Heiden nicht sehen lassen; sie scheinen nicht wie die Sonne, noch leuchten sie wie der Mond.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 6, 68, 'Sogar die Tiere sind besser daran als sie, da sie an einen schützenden Ort fliehen und so sich sichern können.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 6, 69, 'In keinerlei Weise ist uns also offenbar, daß sie Götter sind: deshalb fürchtet euch nicht vor ihnen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 6, 70, 'Ja, wie eine Vogelscheuche im Gurkengarten, die keinen Schutz gewährt, ebenso sind ihre hölzernen, vergoldeten und versilberten Götter.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 6, 71, 'Ebenso gleichen sie auch dem Dornstrauch im Garten, auf den alle Vögel sich setzen; desgleichen auch einem ins Dunkle geworfenen Leichnam sind ähnlich ihre hölzernen, vergoldeten und versilberten Götter.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 6, 72, 'Auch am Purpur und am Marmor, der an ihnen verwittert, kann man erkennen, daß sie keine Götter sind: zuletzt werden sie selbst zerfressen, und im Lande wird Spott herrschen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 6, 73, 'Besser ist also ein gerechter Mann daran, der keine Götzenbilder hat; denn er wird fern bleiben von Verspottung.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 1, 1, 'Nachdem Alexander, der Sohn des Philippus, der Mazedonier, aus dem Lande Chittim ausgezogen war und Darius, den König der Perser und Meder, besiegt hatte, herrschte er als König an dessen Statt, während er vorher nur über Griechenland geherrscht hatte.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 1, 2, 'Er unternahm dann viele Kriege, eroberte zahlreiche Festungen und ließ Könige der Erde hinrichten.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 1, 3, 'Er drang bis an die Enden der Erde vor und plünderte eine Menge von Völkern aus. Als nun die ganze Erde unterworfen vor ihm lag, da wurde er übermütig und hochfahrenden Sinnes.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 1, 4, 'Er brachte eine überaus starke Heeresmacht zusammen und gewann die Herrschaft über Länder, Völker und Fürsten, die ihm tributpflichtig wurden.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 1, 5, 'Schließlich aber, als er aufs Krankenlager geworfen war und den Tod nahen fühlte,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 1, 6, 'berief er seine vornehmsten Diener, die seine Genossen von Jugend auf gewesen waren, und verteilte sein Reich unter sie noch bei seinen Lebzeiten.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 1, 7, 'Als Alexander dann nach zwölfjähriger Regierung gestorben war,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 1, 8, 'übernahmen seine Diener die Herrschaft, ein jeder an dem ihm zugewiesenen Platze;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 1, 9, 'sie setzten sich alle nach seinem Tode das Diadem auf und ebenso ihre Söhne nach ihnen, lange Jahre hindurch, und richteten viel Unheil auf der Erde an.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 1, 10, 'Aus ihnen ging nun ein gottloser Sproß hervor, nämlich Antiochus Epiphanes, der Sohn des Königs Antiochus; er war als Geisel in Rom gewesen und im 137. Jahre der griechischen Herrschaft zur Regierung gelangt.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 1, 11, 'Zu jener Zeit traten in Israel nichtswürdige Leute auf, die viele andere für sich gewannen, indem sie ihnen vorhielten: »Kommt, wir wollen uns ins Einvernehmen mit den Heiden setzen, die rings um uns her wohnen! Denn seitdem wir uns von ihnen abgesondert haben, ist uns viel Unheil zugestoßen«.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 1, 12, 'Dieser Vorschlag fand Beifall bei ihnen,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 1, 13, 'und einige aus dem Volke waren gleich bereit, sich zum Könige zu begeben, der ihnen denn auch die Erlaubnis gab, die Bräuche der Heiden einzuführen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 1, 14, 'So erbauten sie z.B. ein Gymnasium in Jerusalem nach heidnischem Brauch,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 1, 15, 'suchten die an ihnen vollzogene Beschneidung unkenntlich zu machen, fielen so vom heiligen Bunde ab, schlossen sich an die Heiden an und gaben sich dazu her, Böses zu tun.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 1, 16, 'Als sich nun Antiochus in der Herrschaft genügend befestigt sah, sann er darauf, auch Herr von Ägypten zu werden, um so beide Königreiche in seiner Gewalt zu haben.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 1, 17, 'Er zog also mit einem gewaltigen Heere nach Ägypten, mit Kriegswagen, Elefanten und Reiterei und mit einer starken Flotte.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 1, 18, 'Der ägyptische König Ptolemäus, mit dem er Krieg führte, geriet in Furcht vor ihm und ergriff die Flucht, und viele Leute fielen und wurden erschlagen;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 1, 19, 'die ägyptischen Festungen wurden erobert, und er plünderte das Land Ägypten aus.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 1, 20, 'Nachdem Antiochus so Ägypten schwer heimgesucht hatte, kehrte er im Jahre 143 um, zog gegen Israel und kam nach Jerusalem mit gewaltiger Heeresmacht.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 1, 21, 'Hier drang er in seinem Übermut in das Heiligtum ein, nahm den goldenen Altar und den Leuchter samt allen zugehörigen Geräten weg,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 1, 22, 'den Tisch für die Schaubrote, die Becher und Schalen, die goldenen Räuchergefäße, den Vorhang, die Kränze und die goldenen Zierate an der Vorderseite des Tempels und ließ von allen diesen Gegenständen den goldenen Überzug abreißen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 1, 23, 'Weiter nahm er auch das Silber und das Gold und die kostbaren Geräte und alles, was er an verborgenen Schätzen vorfand;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 1, 24, 'und nachdem er alles an sich genommen hatte, zog er ab in sein Land, wobei er noch ein Blutbad anrichtete und vermessene Lästerreden ausstieß.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 1, 25, 'Da entstand laute Wehklage in Israel in allen seinen Wohnsitzen:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 1, 26, 'Oberste und Vornehme jammerten, den Jungfrauen und Jünglingen verging die Jugendkraft, und die Schönheit der Frauen schwand dahin.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 1, 27, 'Jeglicher Bräutigam stimmte Trauerlieder an, die Neuvermählte im Brautgemach saß in Trauerkleidung da;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 1, 28, 'das Land erbebte ob seiner Bewohner, und das ganze Haus Jakobs war mit Schmach bedeckt.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 1, 29, 'Zwei Jahre später sandte der König einen Obersteuereinnehmer in die Städte von Juda. Der kam nach Jerusalem mit starker Heeresmacht,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 1, 30, 'ließ jedoch vor den Stadtbewohnern in hinterlistiger Weise friedliche Worte verlauten, so daß sie ihm Glauben schenkten. Plötzlich aber überfiel er die Stadt, richtete ein großes Blutbad in ihr an und brachte viele Israeliten im Lande um.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 1, 31, 'Dann ließ er die Stadt plündern und in Flammen aufgehen und ihre Häuser und die Mauern ringsum niederreißen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 1, 32, 'Weiter führte man die Weiber und Kinder als Gefangene weg und bemächtigte sich des Viehs.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 1, 33, 'Sodann befestigte man die Davidsstadt mit einer großen und starken Mauer und festen Türmen, damit sie ihnen als Burg diente.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 1, 34, 'In diese legten sie als Besatzung verbrecherisches Gesindel, nichtswürdige Leute, hinein, die sich darin festsetzten.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 1, 35, 'Auch schaffte man Waffen und Lebensmittel hinein und verwahrte daselbst die Beute, die man aus Jerusalem zusammengebracht hatte; so wurde die Burg zu einem schlimmen Unheil für die Stadt.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 1, 36, 'Ja, sie wurde zum Hinterhalt für das Heiligtum und zum schlimmen Widersacher für Israel allezeit.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 1, 37, 'Unschuldig Blut vergossen sie rings um das Heiligtum und entweihten dadurch das Heiligtum.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 1, 38, 'Darum flohen ihretwegen die Bewohner Jerusalems, und Ausländern diente die Stadt als Wohnsitz; den Eingeborenen wurde sie fremd, und ihre eigenen Kinder verließen sie.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 1, 39, 'Ihr Heiligtum ward öde wie die Wüste, ihre Feste wandelten sich zu Trauertagen; ihre Sabbate wurden geschändet, und ihre Ehre ward zur Verachtung.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 1, 40, 'So groß wie einst ihr Ruhm ward nun ihre Schmach, und ihre Hoheit versank in Trauer.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 1, 41, 'Nunmehr ließ der König Antiochus in sein ganzes Reich eine Verfügung ausgehen, daß alle seine Untertanen ein einziges Volk bilden sollten');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 1, 42, 'und jeder seine besonderen Gebräuche und Gesetze aufzugeben habe; und alle anderen Völker fügten sich dem Gebot des Königs.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 1, 43, 'Auch in Israel fanden viele Gefallen an der von ihm gebotenen Verehrung der Götter und opferten den Götzen und entweihten den Sabbat.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 1, 44, 'Nun schickte der König durch Boten den schriftlichen Befehl nach Jerusalem und in die Städte Juda’s, man solle fortan die ausländischen Satzungen und Bräuche beobachten;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 1, 45, 'Die Brand-, Schlacht- und Trankopfer sollten im Heiligtum in Wegfall kommen, Sabbate und Feste ungefeiert bleiben;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 1, 46, 'das Heiligtum und die Heiligen solle man verunreinigen,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 1, 47, 'Altäre, heilige Haine und Götzentempel errichten dürfen, Schweine und andere unreine Tiere schlachten;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 1, 48, 'ihre Söhne sollten sie unbeschnitten lassen und ihr Gewissen mit jeder Art von unreinen und greuelhaften Dingen beflecken,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 1, 49, 'so daß sie das (mosaische) Gesetz vergäßen und alle heiligen Ordnungen abschafften;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 1, 50, 'und wer dem Gebot des Königs nicht Folge leiste, der solle den Tod erleiden.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 1, 51, 'Alle diese Bestimmungen waren in der Verordnung enthalten, die er an sein ganzes Reich ergehen ließ. Dazu setzte er Aufseher über das ganze (jüdische) Volk und gebot den Städten Juda’s, Opfer in allen einzelnen Ortschaften darzubringen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 1, 52, 'Und viele aus dem Volke schlossen sich ihnen an, nämlich alle, die vom Gesetz treulos abfielen und nun Böses im Lande verübten');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 1, 53, 'und die Israeliten dazu nötigten, in Verstecken, in Schlupfwinkeln jeder Art, eine Zuflucht zu suchen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 1, 54, 'Am 15. Tage des Monats Kislev im Jahre 145 stellten sie einen »Greuel der Verwüstung« auf den Brandopferaltar und erbauten Altäre in den Ortschaften Juda’s ringsumher.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 1, 55, 'Sie brachten vor den Haustüren und auf den Straßen Rauchopfer dar,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 1, 56, 'und die Gesetzbücher, die sie fanden, zerrissen und verbrannten sie;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 1, 57, 'und wenn bei jemandem ein Bundesbuch gefunden wurde und wenn jemand dem mosaischen Gesetz treu bleiben wollte, so überlieferte ihn der Erlaß des Königs dem Tode.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 1, 58, 'So verfuhren sie in ihrer Gewalttätigkeit Monat für Monat mit den Israeliten, die sie in den Ortschaften betrafen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 1, 59, 'Am 25. Tage des Monats (Kislev) aber opferten sie auf dem Altar, der auf dem Brandopferaltar stand,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 1, 60, 'und ließen die Frauen, die ihre Kinder hatten beschneiden lassen, der königlichen Verordnung gemäß hinrichten,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 1, 61, 'wobei sie ihnen die Kinder an den Hals hängten; auch ihre Familien und die, welche die Beschneidung vollzogen hatten, töteten sie.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 1, 62, 'Indessen zeigten sich viele Israeliten standhaft und faßten den festen Entschluß, unreine Speisen nicht zu genießen;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 1, 63, 'sie wollten lieber sterben, um sich durch Speisen nicht zu verunreinigen und den heiligen Bund nicht zu brechen; daher erlitten sie den Tod.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 1, 64, 'So lag denn ein schlimmes Zorngericht Gottes überaus schwer auf Israel.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 1, 65, '');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 1, 66, '');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 1, 67, '');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 1, 68, '');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 2, 1, 'Zu jener Zeit trat Mattathias auf, ein Sohn des Johannes, des Sohnes Simeons, ein Priester aus der Familie Jojaribs von Jerusalem; er hatte seinen Wohnsicht in Modein genommen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 2, 2, 'Er hatte fünf Söhne: Johannes mit dem Beinamen Gaddis,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 2, 3, 'Simeon, genannt Thassis,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 2, 4, 'Judas, genannt Makkabäus,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 2, 5, 'Eleasar, genannt Awaran, und Jonathan, genannt Apphus.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 2, 6, 'Als er nun alle die Abscheulichkeiten sah, die in Juda und Jerusalem verübt wurden,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 2, 7, 'rief er aus: »Wehe mir! Warum bin ich dazu geboren worden, die Vernichtung meines Volks und die Vernichtung der heiligen Stadt zu sehen und müßig dazusitzen, während sie der Gewalt der Feinde und das Heiligtum der Gewalt von Ausländern preisgegeben ist!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 2, 8, 'Ihr Haus ist geworden, wie das eines entehrten Mannes,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 2, 9, 'ihre herrlichen Geräte sind als Raub hinweggeführt, ihre Kindlein liegen gemordet auf ihren Straßen, ihre jungen Männer sind durch das Schwert der Feinde gefallen!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 2, 10, 'Welches Volk hat sich nicht die Herrschaft in ihr angeeignet und sich nicht mit ihrer Beute bereichert?');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 2, 11, 'All ihr Schmuck ist weggenommen, aus einer Freien ist sie zur Magd geworden!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 2, 12, 'Ach ja, was uns heilig war, und unsere Schönheit und unsere Herrlichkeit ist verwüstet, und Heiden haben es entweiht!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 2, 13, 'Wozu nützt uns noch das Leben?');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 2, 14, 'Und Mattathias und seine Söhne zerrissen ihre Kleider, legten Trauergewänder an und trugen schweres Leid.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 2, 15, 'Da kamen die königlichen Beamten, die den Abfall erzwingen sollten, nach der Ortschaft Modein, um die Einwohner zum Opfern zu bringen,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 2, 16, 'und viele von den Israeliten schlossen sich ihnen an; auch Mattathias und seine Söhne gingen in die Versammlung.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 2, 17, 'Da nahmen die Beamten des Königs das Wort und richteten an Mattathias folgende Ansprache: »Du bist ein Oberster, angesehen und hochstehend in diesem Orte und einflußreich durch Söhne und Brüder.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 2, 18, 'So tritt du nun zuerst heran und komm der königlichen Verordnung nach, wie alle Völker es getan haben, auch die Männer von Juda und die in Jerusalem Zurückgebliebenen; so wirst du und dein ganzes Haus zu den Freunden des Königs gehören, und du und deine Söhne, ihr werdet mit Silber und Gold und vielen Geschenken geehrt werden«.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 2, 19, 'Mattathias aber gab mit lauter Stimme folgende Antwort: »Wenn auch alle Völker im ganzen Bereich der Herrschaft des Königs ihm Gehorsam leisten, so daß jeder vom Gottesglauben seiner Väter abfällt und sie sich willig seinen Geboten gefügt haben,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 2, 20, 'so wollen doch ich und meine Söhne und meine Brüder weiterhin im Bunde unserer Väter wandeln!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 2, 21, 'Gott behüte uns davor, daß wir unser Gesetz und die Satzungen fahren lassen sollten!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 2, 22, 'Den Geboten des Königs werden wir nicht gehorchen, daß wir von unserer Gottesverehrung nach rechts oder nach links abweichen sollten!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 2, 23, 'Kaum hatte er ausgeredet, da trat ein jüdischer Mann vor aller Augen herzu, um auf dem Altar in Modein nach dem Befehle des Königs zu opfern.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 2, 24, 'Als Mattathias das sah, geriet er in heiligen Eifer: er erbebte bis ins Innerste und ließ seinem Zorne freien Lauf, wie es recht war; er lief hin und erschlug den Mann am Altar.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 2, 25, 'Zugleich tötete er aber auch den königlichen Beamten, der das Opfer hatte erzwingen wollen, und riß den Altar nieder.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 2, 26, 'Er eiferte auf diese Weise für das Gesetz so, wie es einst Pinehas an Simbri, dem Sohne Saloms, getan hatte.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 2, 27, 'Hierauf ließ Mattathias in der Ortschaft den lauten Ruf erschallen: »Wer da für das Gesetz eifert und am Bunde festhalten will, der ziehe aus, mir nach!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 2, 28, 'So floh er denn mit seinen Söhnen ins Gebirge; all ihr Hab und Gut ließen sie im Orte zurück.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 2, 29, 'Damals zogen viele, denen Gerechtigkeit und Recht am Herzen lag, in die Wüste hinab, um dort ihren Wohnsitz zu nehmen,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 2, 30, 'sie selbst mit Weib und Kind und ihrem Vieh, weil die Mißhandlungen übergroß für sie geworden waren.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 2, 31, 'Als nun die königlichen Beamten und die Truppen, die sich zu Jerusalem in der Davidsstadt befanden, die Kunde erhielten, es seien Leute, die sich dem Gebot des Königs widersetzt hätten, in die Schlupfwinkel in der Wüste hinabgezogen,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 2, 32, 'eilten sie in einem starken Aufgebot hinter ihnen her, und als sie auf sie gestoßen waren, umlagerten sie sie und rüsteten sich zum Angriff gegen sie am Sabbattage.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 2, 33, 'Sie ließen ihnen dann sagen: »Nun ist’s genug! Kommt heraus und tut nach dem Gebot des Königs, so sollt ihr am Leben bleiben!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 2, 34, 'Doch sie antworteten: »Wir werden nicht herauskommen und dem Gebot des Königs nicht Folge leisten, daß wir den Sabbat entheiligen sollten!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 2, 35, 'Da gingen jene sofort zum Angriff gegen sie vor;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 2, 36, 'sie aber antworteten ihnen nicht weiter, schleuderten auch keine Steine gegen sie, noch verrammelten sie ihre Schlupfwinkel,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 2, 37, 'sondern sagten: »Wir wollen alle in unserer Einfalt sterben! Der Himmel und die Erde sind unsere Zeugen, daß ihr uns ungerechterweise ums Leben bringt!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 2, 38, 'So gingen jene also zum Angriff gegen sie am Sabbat vor, und so kamen diese ums Leben samt ihren Weibern und Kindern und ihrem Vieh, etwa tausend Menschenseelen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 2, 39, 'Als Mattathias und seine Freunde dies erfuhren, trauerten sie schmerzerfüllt um sie;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 2, 40, 'und sie sagten einer zum anderen: »Wenn wir alle es so machen, wie unsere Brüder getan haben, und nicht für unser Leben und unsere Satzungen gegen die Heiden kämpfen, so werden sie uns gar bald von der Erde vertilgen«.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 2, 41, 'So faßten sie denn an jenem Tage folgenden Beschluß: »Wenn irgend jemand uns am Sabbattage angreift, so wollen wir uns mit den Waffen zur Wehr setzen, damit wir nicht alle zugrunde gehen, wie unsere Brüder in ihren Verstecken umgekommen sind«.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 2, 42, 'Damals traf als Verstärkung eine Schar von Asidäern bei ihnen ein, tapfere Männer aus Israel, lauter solche, die sich willig in den Dienst des Gesetzes stellten;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 2, 43, 'und alle, die sich dem Unheil durch die Flucht zu entziehen suchten, schlossen sich an sie an und verstärkten sie.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 2, 44, 'So brachten sie ein Heer zusammen und schlugen die Sünder in ihrem Zorn und die gottlosen Männer in ihrem Grimm nieder; was von diesen übrig blieb, floh zu den Heiden, um sich in Sicherheit zu bringen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 2, 45, 'Mattathias aber und seine Genossen zogen rings umher, zerstörten die Altäre im Lande');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 2, 46, 'und beschnitten mit Gewalt die Kinder, die noch unbeschnitten waren, soviele sie deren im Gebiete Israels fanden;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 2, 47, 'sie setzten den übermütigen (Feinden) hart zu, und alles, was sie unternahmen, hatte guten Fortgang;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 2, 48, 'sie verteidigten das Gesetz erfolgreich gegen die Macht der Heiden und gegen die Macht des Königshauses und ließen die Sünder nicht hochkommen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 2, 49, 'Als es nun mit den Lebenstagen des Mattathias zu Ende ging, sprach er zu seinen Söhnen: »Jetzt herrscht rücksichtsloser Übermut und schwere Prüfung; es ist eine Zeit der Zerstörung und eines grimmigen Strafgerichts eingetreten.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 2, 50, 'So seid denn Eiferer, meine Söhne, für das Gesetz und gebt euer Leben hin für den Bund unserer Väter!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 2, 51, 'Bleibt der Taten unserer Väter eingedenk, alles dessen, was sie zu ihrer Zeit vollführt haben, so werdet ihr hohen Ruhm und einen unsterblichen Namen erlangen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 2, 52, 'Ist nicht Abraham in der Prüfung treu erfunden und dies ihm als Gerechtigkeit angerechnet worden?');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 2, 53, 'Joseph hielt zur Zeit seiner Bedrängnis am Gebote Gottes fest und wurde so der Gebieter Ägyptens.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 2, 54, 'Unser Ahnherr Pinehas empfing, weil er großen Eifer für Gott bewies, die Zusicherung eines ewigen Priestertums;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 2, 55, 'Josua wurde Richter in Israel, weil er den Auftrag Gottes erfüllte;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 2, 56, 'Kaleb empfing Landbesitz als Erbteil, weil er vor der Gemeinde Zeugnis (für Gott) abgelegt hatte;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 2, 57, 'David gewann durch seine Frömmigkeit einen Königsthron für ewige Zeiten;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 2, 58, 'Elias wurde wegen seines Eiferns für das Gesetz in den Himmel emporgehoben;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 2, 59, 'Ananias, Asarja und Michael wurden wegen ihres Gottvertrauens aus der Flammenglut errettet;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 2, 60, 'Daniel wurde um seiner Unschuld willen vor dem Rachen der Löwen behütet.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 2, 61, 'Und so könnt ihr es von Geschlecht zu Geschlecht bestätigt finden, daß alle, die ihre Hoffnung auf Gott setzen, nicht unterliegen werden.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 2, 62, 'Fürchtet euch also nicht vor den Drohworten eines sündigen Menschen! denn seine Herrlichkeit wird zu Kot werden und den Würmern zum Fraß dienen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 2, 63, 'Heute steigt er hoch empor, und morgen ist er nicht mehr zu finden; denn er ist wieder zu Staub geworden, und mit seinen Anschlägen ist’s vorbei.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 2, 64, 'Ihr aber, meine Söhne, seid stark und steht mannhaft für das Gesetz ein; denn dadurch werdet ihr Ruhm ernten.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 2, 65, 'Und seht: da ist euer Bruder Simeon; ich weiß, daß er ein kluger Mann ist; auf ihn hört allezeit: er soll Vaterstelle bei euch vertreten!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 2, 66, 'Judas der Makkabäer aber, der von Jugend auf ein tapferer Held gewesen ist, der soll euer Heerführer sein und den Krieg der Stämme (unseres Volkes) leiten.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 2, 67, 'Ihr aber, sammelt um euch alle, die dem Gesetz treu sind, und vollzieht die Rache für euer Volk!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 2, 68, 'Übt Vergeltung an den Heiden und haltet fest an den Geboten des Gesetzes!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 2, 69, 'Hierauf segnete er sie und wurde zu seinen Vätern versammelt;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 2, 70, 'er starb im Jahre 146, und seine Söhne begruben ihn in der Grabstätte seiner Väter in Modein, und ganz Israel betrauerte ihn mit tiefem Leid.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 3, 1, 'Als nun sein Sohn Judas mit dem Beinamen Makkabäus an seine Stelle getreten war,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 3, 2, 'leisteten ihm alle seien Brüder, sowie alle diejenigen Beistand, die es vorher mit seinem Vater gehalten hatten, und führten den Krieg für Israel mit Freuden.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 3, 3, 'Er verschaffte seinem Volke weithin Ruhm, legte den Harnisch an als ein Held und umgürtete sich mit seinen Kriegswaffen; er lieferte Schlachten, indem er das Heer mit dem Schwerte schützte.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 3, 4, 'Er glich einem Löwen in seinen Taten, einem jungen Leu, der nach Raub brüllt.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 3, 5, 'Er erspähte die Gottlosen und verfolgte sie, und die sein Volk zerrütteten, verbrannte er.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 3, 6, 'Die Gottlosen fuhren zusammen aus Furcht vor ihm, alle Übeltäter zitterten vor ihm, und die Rettung nahm guten Fortgang durch sein Verdienst.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 3, 7, 'Vielen Königen schaffte er bittere Schmerzen, aber Jakob erfreute er durch seine Taten: auf ewig bleibt sein Andenken in Segen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 3, 8, 'Er zog umher in den Städten Juda’s. vertilgte die Gottlosen aus dem Lande und wandte Gottes Zorn von Israel ab.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 3, 9, 'Sein Ruhm erscholl bis ans Ende der Erde, und er sammelte die dem Untergang Geweihten.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 3, 10, 'Nun brachte Apollonius ein Herr von Heiden und eine große Streitmacht aus Samaria zusammen, um Israel zu bekriegen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 3, 11, 'Als Judas dies erfuhr, zog er ihm entgegen, schlug ihn und tötete ihn; viele Erschlagene fielen, die Übriggebliebenen aber ergriffen die Flucht.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 3, 12, 'Man gewann reiche Beute von ihnen, und Judas nahm das Schwert des Apollonius an sich und gebrauchte es fortan beständig in allen Kämpfen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 3, 13, 'Als nun Seron, der Befehlshaber des syrischen Heeres, die Meldung erhielt, Judas habe einen Haufen um sich zusammengebracht und eine Schar von Getreuen, die mit ihm zum Kampfe auszögen,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 3, 14, 'da dachte er: »Ich will mir einen Namen machen und mir Ruhm im Reiche erwerben und will Judas mit seinen Leuten bekämpfen, die das Gebot des Königs mißachten«.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 3, 15, 'Er unternahm also einen neuen Feldzug, und unter seinem Befehl zog ein starkes Heer von Ungläubigen aus, um ihm Beistand zu leisten und die Rache an den Israeliten zu vollziehen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 3, 16, 'Als er nun in die Nähe der Steige von Beth-Horon gelangt war, zog ihm Judas mit geringer Mannschaft entgegen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 3, 17, 'Als diese jedoch das Heer erblickt hatten, das gegen sie heranzog, sagten sie zu Judas: »Wie können wir in so geringer Zahl den Kampf gegen eine so gewaltige Übermacht aufnehmen, zumal da wir erschöpft sind, weil wir heute noch nichts genossen haben?«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 3, 18, 'Judas aber antwortete ihnen: »Es ist leicht möglich, daß eine große Anzahl den Händen weniger (zur Überwältigung) preisgegeben wird; denn für den Gott des Himmels macht es keinen Unterschied, ob er durch viele oder durch wenige die Rettung schafft.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 3, 19, 'Der Sieg in der Schlacht hängt ja nicht von der Größe des Heeres ab, sondern vom Himmel kommt die Kraft.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 3, 20, 'Jene ziehen gegen uns heran voller Übermut und Gottlosigkeit, um uns und unsere Weiber und unsere Kinder zu vertilgen und um uns auszuplündern;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 3, 21, 'wir aber kämpfen für unser Leben und unsere Satzungen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 3, 22, 'So wird denn Gott selbst sie vor unseren Augen zermalmen; ihr aber fürchtet euch nicht vor ihnen!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 3, 23, 'Nach dieser Rede stürmte er unversehens auf sie ein, und Seron wurde mit seinem Heere vor ihm aufgerieben.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 3, 24, 'Sie verfolgten ihn auf der Steige von Beth-Horon hinab bis in die Ebene, und gegen 800 Mann fielen von ihnen; die Übriggebliebenen flohen ins Philisterland.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 3, 25, 'Da kam die Furcht vor Judas und seinen Brüdern zum Durchbruch, und Schrecken befiel die Heiden in der ganzen Gegend ringsum;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 3, 26, 'sein Name drang bis zu den Ohren des Königs, und alle Welt sprach von den Schlachten des Judas.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 3, 27, 'Als nun der König Antiochus von diesen Dingen Kunde erhielt, geriet er in gewaltigen Zorn; er ließ Befehl ergehen und bot alle Streitkräfte seines Reichs auf, ein überaus gewaltiges Heer.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 3, 28, 'Er öffnete seine Schatzkammern, ließ seinen Truppen den Sold für ein ganzes Jahr auszahlen und gebot ihnen, sich für alle Fälle bereit zu halten.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 3, 29, 'Da er aber sah, daß ihm das Geld in seinen Schatzkammern ausging, und daß der Ertrag der Steuern aus den Landen gering war infolge des Aufruhrs und wegen des Unheils, das er (selbst) im Lande angerichtet hatte, um die Gesetze und Bräuche abzuschaffen, die von den ältesten Zeiten her in Geltung gewesen waren: –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 3, 30, 'da geriet er in Besorgnis, es möchten ihm, wie das früher schon mehr als einmal der Fall gewesen war, die Mittel zur Bestreitung der Ausgaben fehlen, besonders für die Geschenke, die er bisher mit freigebiger Hand und reichlicher als die früheren Könige ausgeteilt hatte.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 3, 31, 'Weil er sich nun arg beunruhigt fühlte, beschloß er, nach Persien zu ziehen und die Steuern der Provinzen dort zu erheben und viel Geld zusammenzubringen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 3, 32, 'Er ließ also Lysias, einen hochangesehenen Mann aus königlichem Geschlecht, als Reichsverweser für die Länder vom Euphratstrom bis zu den Grenzen Ägyptens zurück;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 3, 33, 'dieser hatte auch den königlichen Prinzen Antiochus zu erziehen, bis er selbst zurückkehren würde.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 3, 34, 'Zugleich übergab er ihm die Hälfte des Kriegsheeres, sowie die Elefanten, und gab ihm Aufschluß über alle seine Pläne, und zwar besonders hinsichtlich der Bewohner Judäas und Jerusalems:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 3, 35, 'er solle ein Heer gegen sie entsenden, um die Macht der Israeliten und was von Jerusalem noch übrig war, völlig auszurotten, so daß selbst die Erinnerung an sie im Lande erlösche;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 3, 36, 'alsdann sollte er Ausländer in ihrem ganzen Gebiet sich ansiedeln lassen und ihr Land losweise unter diese verteilen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 3, 37, 'Der König selbst nahm hierauf die andere Hälfte des Heeres und brach von seiner Residenz Antiochien im Jahre 147 auf, ging über den Euphratstrom und durchzog die oberen Länder.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 3, 38, 'Lysias erwählte nun Ptolemäus, den Sohn des Dorymenes, sowie Nikanor und Gorgias, hochangesehene Männer aus der Zahl der Freunde des Königs,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 3, 39, 'und sandte mit ihnen 40000 Mann zu Fuß und 7000 Reiter; die sollten ins jüdische Land ziehen, um es nach dem Befehl des Königs zu verheeren.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 3, 40, 'Diese drei (Männer) brachen also mit ihrer gesamten Streitmacht auf und lagerten sich nach ihrer Ankunft nahe bei Emmaus in der Ebene.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 3, 41, 'Als nun die Handelsleute in der Gegend Kunde von ihrer Ankunft erhielten, versahen sie sich reichlich mit Silber und Gold und auch mit Stricken zum Fesseln und kamen ins Lager, um die Israeliten als Sklaven anzukaufen. Es stießen auch noch Truppen aus Syrien und dem Lande der Philister zu ihnen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 3, 42, 'Als nun Judas und seine Brüder sahen, daß das Unheil immer ärger wurde und die feindlichen Scharen innerhalb ihres Gebietes lagerten, und als sie auch Kunde von den Befehlen des Königs erhielten, der die völlige Vernichtung ihres Volkes geboten hatte,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 3, 43, 'da sagten sie einer zum andern: »Laßt uns das wiederherstellen, was in unserm Volke zerstört ist, und laßt uns für unser Volk und das Heiligtum kämpfen!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 3, 44, 'So versammelte sich denn die ganze Gemeinschaft, um zum Kampfe bereit zu sein und um zu beten und Gnade und Erbarmen zu erflehen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 3, 45, 'Jerusalem aber lag unbewohnt da wie eine Wüste, niemand ging mehr ein und aus von seinen Kindern; das Heiligtum war zertreten, Fremdlinge hausten in der Burg, eine Herberge der Heiden war (die Stadt) geworden; die Freude war verschwunden aus Jakob, es schwiegen Flöte und Zither.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 3, 46, 'Als sie sich nun versammelt hatten, zogen sie nach Massepha, Jerusalem gegenüber; denn dort war in früheren Zeiten eine Gebetsstätte für Israel gewesen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 3, 47, 'Dann fasteten sie an jenem Tage, hüllten sich in härene Gewänder, streuten sich Asche aufs Haupt und zerrissen ihre Kleider.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 3, 48, 'Sodann breiteten sie das Gesetzbuch aus (eines von denen), nach welchen die Heiden gesucht hatten, um ihre Götzenbilder darauf zu malen;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 3, 49, 'dann brachten sie auch die Priestergewänder herbei, sowie die Erstlinge und Zehnten, und ließen Nasiräer auftreten, deren Weihezeit abgelaufen war.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 3, 50, 'Dann ließen sie mit lauter Stimme den Ruf zum Himmel erschallen: »Was sollen wir mit allen diesen machen und wohin sie bringen?');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 3, 51, 'Dein Heiligtum ist ja zertreten und entweiht, und deine Priester sind in Trauer und Elend!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 3, 52, 'Und siehe, die Heiden haben sich gegen uns zusammengeschart, um uns auszurotten; du weißt ja, was sie gegen uns vorhaben!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 3, 53, 'Wie sollen wir ihnen widerstehen können, wenn du uns nicht zu Hilfe kommst?«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 3, 54, 'Dann stießen sie in die Trompeten und erhoben ein lautes Wehgeschrei.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 3, 55, 'Hierauf setzte Judas Anführer über das Kriegsvolk ein, Hauptleute über Tausend, über Hundert, über Fünfzig und über zehn Mann.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 3, 56, 'Sodann richteten sie an die, welche in letzter Zeit ein Haus gebaut oder sich verheiratet oder einen Weinberg angepflanzt hatten oder die furchtsam seien, die Aufforderung, sich in ihre Heimat zu begeben, wie das Gesetz es bestimmte.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 3, 57, 'Alsdann brach das Heer auf und lagerte sich südlich von Emmaus.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 3, 58, 'Judas aber gebot: »Macht euch fertig und zeigt euch als tapfere Männer! Haltet euch für morgen früh bereit zum Kampf mit diesen Heiden, die sich wider uns zusammengetan haben, um uns und unser Heiligtum zu vernichten!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 3, 59, 'Denn es ist besser für uns, im Kampfe zu fallen, als den Untergang unsers Volkes und des Heiligtums mit anzusehen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 3, 60, 'Übrigens – wie es im Himmel beschlossen ist, so möge er es fügen!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 4, 1, 'Gorgias nahm nun 5000 Mann zu Fuß und 1000 auserlesene Reiter, und diese Schar brach während der Nacht auf,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 4, 2, 'um das Lager der Juden zu überfallen und sie unvermutet zu schlagen; dabei dienten ihm die Leute aus der Burg als Wegweiser.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 4, 3, 'Als Judas dies erfuhr, brach er selbst mit seinen Kriegern auf, um das Heer des Königs bei Emmaus anzugreifen,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 4, 4, 'solange noch die Truppen außerhalb des Lagers zerstreut waren.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 4, 5, 'Als nun Gorgias bei Nacht an den Lagerplatz des Judas kam und dort niemand vorfand, suchte er sie in den Bergen auf und zwar in der Meinung: »Die laufen vor uns weg!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 4, 6, 'Aber bei Tagesanbruch kam Judas in der Ebene mit 3000 Mann zum Vorschein; nur hatten sie leider nicht Rüstungen und Schwerter, wie sie wohl gewünscht hätten.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 4, 7, 'Als sie nun das starkbefestigte Lager der Heiden und die Reiterei erblickten, die dem Lager ringsum als Schutz diente, lauter kriegsgeübte Leute,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 4, 8, 'da sagte Judas zu den Männern, die bei ihm waren: »Fürchtet euch nicht vor ihrer Menge und scheut euch nicht, zum Angriff auf sie vorzustürmen!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 4, 9, 'Denkt daran, wie unsere Väter im Roten Meer errettet wurden, als der Pharao sie mit Heeresmacht verfolgte!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 4, 10, 'Und nun laßt uns zum Himmel schreien, ob er wohl Erbarmen mit uns haben und des Bundes mit unseren Vätern gedenken und dieses Heer heute vor unseren Augen vernichten will,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 4, 11, 'damit alle Heiden erkennen, daß es für Israel noch einen Erlöser und Retter gibt!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 4, 12, 'Als nun die Heiden ihre Augen erhoben und sie gegen sich heranrücken sahen,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 4, 13, 'zogen sie aus dem Lager zum Kampfe heraus. Da stießen die Leute des Judas in die Trompeten;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 4, 14, 'und als sie handgemein geworden waren, wurden die Heiden völlig besiegt und flohen in die Ebene;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 4, 15, 'dabei wurden alle, die sich hintenan befanden, mit dem Schwerte niedergemacht, und man verfolgte sie dann bis Gasera und bis in die Ebene von Idumäa und bis Asotus und Jamnia, und es fielen von ihnen gegen 3000 Mann.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 4, 16, 'Als Judas dann mit seinem Heere von der Verfolgung zurückkehrte,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 4, 17, 'sagte er zu seinen Leuten: »Laßt euch jetzt nicht nach der Beute gelüsten, denn es steht uns noch weiterer Kampf bevor;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 4, 18, 'Gorgias steht ja noch mit seiner Mannschaft im Gebirge nicht fern von uns. Bleibt jetzt also unseren Feinden gegenüber stehen und kämpft mit ihnen; alsdann mögt ihr euch der Beute in aller Ruhe bemächtigen«.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 4, 19, 'Judas hatte noch nicht ausgeredet, da wurde eine Abteilung sichtbar, die aus dem Gebirge herauskam.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 4, 20, 'Diese bemerkte (sogleich), daß das syrische Heer in die Flucht geschlagen war und daß man das Lager in Brand gesteckt hatte; denn der Rauch, der zu sehen war, verriet ihnen, was geschehen war.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 4, 21, 'Bei diesem Anblick erschraken sie sehr; als sie aber auch noch das Heer des Judas in der Ebene zur Schlacht bereit gewahrten,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 4, 22, 'flohen sie allesamt ins Land der Philister.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 4, 23, 'Nun machte Judas sich an die Plünderung des Lagers, und man erbeutete viel Gold und Silber, blaue und rote Purpurstoffe und andere große Reichtümer.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 4, 24, 'Bei der Rückkehr sangen sie dann Lieder und ließen Lobgesänge zum Himmel emporsteigen, wie herrlich, wie ewigwährend seine Gnade sei.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 4, 25, 'Es war aber den Israeliten ein großer Sieg an jenem Tage zuteil geworden.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 4, 26, 'Diejenigen Heiden aber, die sich hatten retten können, begaben sich zu Lysias und berichteten ihm alles, was sich zugetragen hatte.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 4, 27, 'Durch diese Mitteilungen wurde er ganz bestürzt und entmutigt, weil es mit Israel nicht nach seinem Wunsch gegangen war und die vom König ihm erteilten Befehle nicht zur Ausführung gelangt waren.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 4, 28, 'Darum brachte er im folgenden Jahr ein Heer von 60000 Mann auserlesener Fußtruppen und 5000 Reitern zusammen, um sie niederzuwerfen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 4, 29, 'Als diese nun nach Idumäa gelangt waren und bei Bethsura ein Lager bezogen hatten, rückte Judas ihnen mit 10000 Mann entgegen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 4, 30, 'Als er nun das gewaltige Heer erblickte, richtete er folgendes Gebet an Gott: »Gepriesen seist du, o Retter Israels, der du einst den Ansturm des Riesen (Goliath) durch die Hand deines Knechtes David gebrochen und das Heer der Philister in die Gewalt Jonathans, des Sohnes Sauls, und seines Waffenträgers hast fallen lassen!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 4, 31, 'Gib nun auch dieses Heer deinem Volke Israel zur Vernichtung preis, daß sie mit ihrer Kriegsmacht und Reiterei zuschanden werden!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 4, 32, 'Jage ihnen Furcht ein und laß ihren trotzigen Mut zerrinnen, daß sie durch ihre Niederlage in Verzweiflung geraten!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 4, 33, 'Wirf sie nieder durch das Schwert derer, die dich lieben, damit alle, die deinen Namen kennen, dich mit Lobgesängen preisen!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 4, 34, 'Als es dann zum Kampfe kam, fielen vom Heere des Lysias gegen 5000 Mann, und zwar im Kampfe Mann gegen Mann.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 4, 35, 'Als Lysias aber die Niederlage seiner Mannschaft wahrnahm und andrerseits erkannte, daß den Leuten des Judas der Mut gewachsen sei und wie entschlossen sie waren, mit Ehren entweder zu leben oder zu sterben, kehrte er nach Antiochien zurück und warb fremde Söldner an, um, wenn sein Heer wieder vollzählig geworden sei, einen neuen Feldzug nach Judäa zu unternehmen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 4, 36, 'Judas aber und seine Brüder sagten: »Jetzt, da unsere Feinde geschlagen sind, wollen wir hinaufziehen, um das Heiligtum zu reinigen und neu zu weihen!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 4, 37, 'So versammelte sich denn das ganze Heer, und man zog auf den Berg Zion hinauf.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 4, 38, 'Als sie nun das Heiligtum verwüstet sahen, den Opferaltar entweiht, die Tore verbrannt, in den Vorhöfen Gesträuch, das aufgewachsen war wie in einem Walde oder auf irgend einem Berge, und die Zellen in den Vorhöfen zerstört:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 4, 39, 'da zerrissen sie ihre Kleider und stellten eine große Trauerfeier an, streuten sich Asche aufs Haupt,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 4, 40, 'warfen sich auf ihr Angesicht zur Erde nieder, ließen die Signaltrompeten erschallen und richteten laute Klagerufe gen Himmel.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 4, 41, 'Sodann stellte Judas eine Anzahl Männer an, um die Besatzung der Burg an der Vollführung von Feindseligkeiten zu hindern, bis er das Heiligtum gereinigt haben würde.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 4, 42, 'Weiter wählte er fehllose Priester aus, die dem Gesetz treu ergeben waren;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 4, 43, 'die reinigten das Heiligtum und schafften die Steine, die zur Entweihung gedient hatten, an einen unreinen Ort.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 4, 44, 'Alsdann berieten sie wegen des entweihten Brandopferaltars, wie sie mit ihm verfahren sollten;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 4, 45, 'und da verfielen sie auf den guten Gedanken, ihn abzubrechen, damit er ihnen nicht infolge der Entweihung durch die Heiden Schimpf und Schande einbrächte. So rissen sie also den Altar ein');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 4, 46, 'und legten die Steine an einem geeigneten Platze auf dem Tempelberge nieder, bis ein Prophet aufträte, der eine Entscheidung darüber abgäbe, was mit ihnen geschehen solle.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 4, 47, 'Dann nahmen sie unbehauene Steine nach der Vorschrift des Gesetzes und erbauten einen neuen Altar nach dem Muster des alten.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 4, 48, 'Auch stellen sie das Heiligtum (von außen) und auch die inneren Räume des Tempels wieder her und weihten die Vorhöfe,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 4, 49, 'ließen auch neue heilige Geräte anfertigen und brachten den Leuchter und den Rauchopferaltar und den Schaubrottisch in den Tempel hinein.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 4, 50, 'Alsdann räucherten sie auf dem Altar und zündeten die Lampen auf dem Leuchter an, daß sie den Tempel erleuchteten.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 4, 51, 'Schließlich legten sie Brote auf den Tisch und hängten die Vorhänge auf. Als sie nun so die begonnenen Arbeiten allesamt vollendet hatten,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 4, 52, 'brachten sie in der Morgenfrühe am 25. Tage des 9. Monats – es war der Monat Kislev des Jahres 148 –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 4, 53, 'ein Opfer nach der Vorschrift des Gesetzes auf dem neuen Brandopferaltar dar, den sie erbaut hatten.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 4, 54, 'In derselben Jahreszeit und an demselben Tage, an dem die Heiden ihn entweiht hatten, an demselben Tage wurde die Einweihung vollzogen mit Lobgesängen und unter dem Klange von Zithern, Harfen und Zimbeln.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 4, 55, 'Das ganze Volk warf sich dabei mit dem Angesicht zur Erde nieder, brachte seine Anbetung dar und pries, zum Himmel blickend, den, der ihnen Gelingen gewährt hatte.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 4, 56, 'Hierauf feierten sie das Fest der Einweihung des Altars acht Tage lang, brachten dabei Brandopfer mit Freuden dar und opferten Heils- und Lobopfer;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 4, 57, 'auch schmückten sie die Vorderseite des Tempels mit goldenen Kränzen und mit Schildchen, stellten die Tore und die Zellen wieder her und versahen diese mit Türen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 4, 58, 'Es herrschte überaus große Freude beim Volk, daß die Entehrung durch die Heiden wieder gutgemacht war.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 4, 59, 'Judas aber und seine Brüder, sowie die ganze israelitische Gemeinde setzten fest, daß das Fest der Altarweihe in der Folgezeit Jahr für Jahr acht Tage lang vom 25. Tage des Monats Kislev an mit Freude und Fröhlichkeit gefeiert werden sollte.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 4, 60, 'Ferner umbauten sie zu jener Zeit den Berg Zion ringsum mit hohen Mauern und festen Türmen, damit die Heiden nicht wiederkämen und alles niederträten wie zuvor.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 4, 61, 'Dann legte er eine Besatzung hinein, um ihn zu sichern; und man befestigte auch (um ihn zu sichern), Bethsura, damit das Volk eine Deckung gegen Idumäa habe.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 5, 1, 'Als nun die Heiden ringsum vernahmen, daß der Altar wiederhergestellt und das Heiligtum neu eingeweiht worden sei, gerieten sie in volle Wut');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 5, 2, 'und faßten den Entschluß, alle zum Geschlecht Jakobs Gehörigen, die in ihrer Mitte wohnten, auszurotten; und sie fingen auch wirklich an, einzelne von dem Volke zu ermorden und ums Leben zu bringen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 5, 3, 'Da griff Judas die Nachkommen Esaus in ihrem Lande Idumäa an, und zwar in der Landschaft Akrabattene, weil sie Israel durch ihre Einfälle belästigten; er brachte ihnen eine schwere Niederlage bei, durch die er sie demütigte, und nahm ihnen Beute ab.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 5, 4, 'Dann gedachte er auch der Bosheit der Bewohner von Bajan, die unserem Volke als Wegelagerer Schaden und schlimme Verluste zufügten.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 5, 5, 'Sie wurden von ihm in ihre festen Türme eingeschlossen und belagert, und er vollstreckte dann den Bann an ihnen, indem er die Türme in ihrem Lande in Brand steckte und mit allen ihren Insassen verbrannte.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 5, 6, 'Als er hierauf weiter gegen die Ammoniter gezogen war, stieß er dort auf eine starke Streitmacht und zahlreiches Kriegsvolk unter der Anführung des Timotheus.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 5, 7, 'Er lieferte diesen viele Gefechte; sie wurden von ihm niedergeworfen, und er besiegte sie.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 5, 8, 'Als er dann Jaser samt den zugehörigen Ortschaften eingenommen hatte, kehrte er nach Judäa zurück.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 5, 9, 'Nun taten sich auch die Heiden in Gilead gegen die Israeliten zusammen, die in ihrem Gebiete wohnten, um sie auszurotten. Diese flüchteten sich in den festen Platz Dathema');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 5, 10, 'und sandten an Judas und seine Brüder ein Schreiben, das folgenden Wortlaut hatte: »Die Heiden rings um uns her haben sich gegen uns zusammengetan, um uns zu vertilgen;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 5, 11, 'sie schicken sich an, heranzukommen und den festen Platz zu erobern, in den wir uns geflüchtet haben; Timotheus steht an der Spitze ihres Heeres.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 5, 12, 'So komm nun und rette uns aus ihrer Hand! Schon sind gar viele von unseren Leuten gefallen;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 5, 13, 'alle unsere Brüder im Lande Tob sind ums Leben gekommen; ihre Weiber und Kinder und alle ihre Habe hat man als Beute weggeführt und dort an 1000 Männer umgebracht«.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 5, 14, 'Während man dieses Schreiben noch vorlas, trafen andere Boten aus Galiläa mit zerrissenen Kleidern ein und meldeten ganz Ähnliches,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 5, 15, 'nämlich: es hätten Zusammenrottungen gegen sie aus Ptolemais, Tyrus und Sidon stattgefunden, und das ganze heidnische Galiläa (habe sich zusammengetan), um sie vollständig zu vertilgen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 5, 16, 'Als Judas und das Kriegsvolk diese Berichte vernommen hatten, wurde eine große Versammlung berufen, um zu beraten, was sie für ihre Brüder tun sollten, die sich in einer solchen Notlage befänden und von den Heiden angegriffen würden.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 5, 17, 'Da sagte Judas zu seinem Bruder Simon: »Wähle dir Männer aus und zieh hin, um deine Brüder in Galiläa zu retten; ich aber und mein Bruder Jonathan, wir wollen nach Gilead ziehen«.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 5, 18, 'Sodann ließ er Joseph, den Sohn Sacharjas, und Asarja als Hauptleute mit dem Rest des Heeres in Judäa zum Schutz des Landes zurück');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 5, 19, 'und gab ihnen die bestimmte Weisung: »Befehligt diesen Heeresteil, laßt euch aber auf keinen Kampf mit den Heiden ein, bis wir zurückgekehrt sind«.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 5, 20, 'Dem Simon wurden hierauf 3000 Mann für den Zug nach Galiläa zugeteilt und dem Judas 8000 Mann für Gilead.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 5, 21, 'Simon zog also nach Galiläa, wo er dann den Heiden viele Gefechte lieferte, und die Heiden wurden von ihm geschlagen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 5, 22, 'Er verfolgte sie bis an das Tor von Ptolemais; es fielen von diesen Heiden etwa 3000 Mann, und er gewann reiche Beute von ihnen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 5, 23, 'Alsdann nahm er die Juden, die er in Galiläa und (in der Landschaft) Arbatta vorgefunden hatte, mit sich samt ihren Frauen und Kindern und aller ihrer Habe und führte sie mit großer Freude nach Judäa.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 5, 24, 'Unterdessen hatte Judas, der Makkabäer, und sein Bruder Jonathan den Jordan überschritten und waren drei Tagereisen weit in die Wüste gezogen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 5, 25, 'Dort trafen sie auf die Nabatäer, die ihnen friedlich entgegenkamen und ihnen alles berichteten, was ihren Brüdern in Gilead widerfahren sei,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 5, 26, 'und daß viele von ihnen in Bosra, Bosor, Alama, Kasphor, Maked und Karnain, lauter festen und großen Städten, eingeschlossen seien;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 5, 27, 'auch in den übrigen Städten Gileads seien manche eingeschlossen, und man habe die Absicht, die festen Plätze am folgenden Tage zu bestürmen und zu erobern und die dort befindlichen Juden alle an einem Tage niederzumetzeln.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 5, 28, 'Da machte Judas mit seinem Heere unverweilt Kehrt und zog in die Wüste nach Bosor, nahm die Stadt ein und machte die ganze männliche Bevölkerung darin mit der Schärfe des Schwertes nieder; dann nahm er ihren ganzen Besitz als Beute hin und ließ die Stadt in Flammen aufgehen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 5, 29, 'Sodann brach er bei Nacht von dort auf und zog bis zur Festung (Dathema).');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 5, 30, 'Als nun der Morgen anbrach und sie Umschau hielten, gewahrten sie dort Kriegsvolk in unzählbarer Menge, das Sturmleitern und Maschinen trug, um die Festung zu erstürmen, und gerade im Kampfe mit den Belagerten begriffen war.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 5, 31, 'Als nun Judas sah, daß der Kampf begonnen hatte und der Lärm von der Stadt mit Trompetenschall und lautem Rufen bis zum Himmel empordrang,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 5, 32, 'da rief er seinen Kriegern zu: »Kämpft heute für eure Brüder!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 5, 33, 'Heriauf griff er sie mit drei Heerhaufen im Rücken an, wobei sie die Trompeten erschallen ließen und laute Gebetsrufe ausstießen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 5, 34, 'Da erkannte das Heer des Timotheus, daß es der Makkabäer sei, und ergriff die Flucht vor ihm; er brachte ihnen eine schwere Niederlage bei, und es fielen von ihnen an jenem Tage gegen 8000 Mann.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 5, 35, 'Nun wandte er sich gegen Mizpa, eroberte es im Sturm und machte die gesamte männliche Bevölkerung darin nieder; dann ließ er die Stadt plündern und in Flammen aufgehen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 5, 36, 'Von dort zog er weiter und eroberte Kasphor, Maked, Bosor und die übrigen Städte der Landschaft Gilead.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 5, 37, 'Nach diesen Begebenheiten brachte Timotheus ein anderes Heer zusammen und lagerte sich Raphon gegenüber, jenseits des Baches.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 5, 38, 'Als Judas nun das Heer auskundschaften ließ, erhielt er folgende Meldung: »Alle Heiden, die rings um uns her wohnen, sind dort bei ihnen zusammengekommen; es ist eine ganz gewaltige Heeresmacht.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 5, 39, 'Auch Araber haben sie als Hilfstruppen in Sold genommen; sie lagern jenseits des Baches und sind zum Angriff gegen dich bereit«. Darauf zog Judas ihnen entgegen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 5, 40, 'Als sich Judas nun mit seinem Heere dem strömenden Gießbache näherte, sagte Timotheus zu seinen Hauptleuten: »Kommt er zuerst zu uns herüber, so werden wir ihm nicht widerstehen können, weil er uns im Gefühl seiner Überlegenheit besiegen wird;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 5, 41, 'fürchtet er sich aber und lagert er sich jenseits des Flusses, so wollen wir gegen in hinübergehen und ihn überwältigen«.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 5, 42, 'Als nun Judas nahe an den strömenden Gießbach gekommen war, ließ er die geschäftsführenden Beamten des Heeres an den Gießbach herantreten und erteilte ihnen die Weisung: »Laßt niemand im Lager zurück: alle sollen am Angriff teilnehmen!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 5, 43, 'Hierauf ging er an der Spitze des Zuges hinüber auf sie los und das ganze Heer hinter ihm her. Da wurden alle Heiden von ihm zurückgeschlagen; sie warfen ihre Waffen weg und flüchteten sich in den Tempel zu Karnain.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 5, 44, 'Judas eroberte jedoch die Stadt und verbrannte den Tempel mit allen, die sich darin befanden. So wurde Karnain gedemütigt, und sie vermochten dem Judas nicht länger zu widerstehen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 5, 45, 'Hierauf ließ Judas alle in der Landschaft Gilead wohnenden Israeliten, klein und groß, samt ihren Weibern und Kindern und ihren Habseligkeiten zusammenkommen, einen gewaltig großen Heereszug, um sie ins jüdische Land abzuführen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 5, 46, 'So gelangten sie bis Ephron; das war eine große, sehr feste Stadt am Eingang des Passes, an der man weder rechts noch links vorbeikommen konnte, sondern man mußte mitten durch sie hindurchziehen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 5, 47, 'Die Bewohner der Stadt aber verweigerten ihnen den Durchzug und verrammelten die Tore mit Steinen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 5, 48, 'Judas sandte Boten an sie mit der friedlichen Botschaft: »Wir wollen nur durch dein Gebiet hindurchziehen, um in unser Vaterland zurückzukehren; niemand wird euch etwas zuleide tun; wir wollen lediglich hindurchziehen«; aber sie wollten ihm die Tore nicht auftun.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 5, 49, 'Da ließ Judas im Heere ausrufen, jeder solle sich an dem Orte lagern, wo er sich gerade befinde.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 5, 50, 'So machten denn die Kriegsleute Halt, bestürmten alsdann die Stadt während jenes Tages und die ganze Nacht hindurch, bis die Stadt in ihre Hände fiel.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 5, 51, 'Er ließ dann die gesamte männliche Bevölkerung mit der Schärfe des Schwertes niedermachen, ließ die Stadt plündern und von Grund aus zerstören und zog hierauf hindurch über die Leichen der Getöteten hinweg.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 5, 52, 'Darauf setzten sie über den Jordan und gelangten in die große Ebene Bethsean gegenüber.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 5, 53, 'Judas hatte aber unterwegs überall die Nachzügler zusammengehalten und den Leuten Mut zugesprochen, bis sie ins jüdische Land kamen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 5, 54, 'Hier zogen sie auf den Zionsberg mit Freude und Fröhlichkeit hinauf und brachten Brandopfer dar, weil kein einziger von ihnen ums Leben gekommen war bis zu ihrer glücklichen Heimkehr.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 5, 55, 'Während nun Judas und Jonathan in Gilead waren und ihr Bruder Simon in Galiläa vor Ptolemais,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 5, 56, 'erhielten Joseph, der Sohn Sacharjas, und Asarja, die Anführer der Streitkräfte (in Judäa), Kunde von den Heldentaten und Kämpfen, die jene vollführt hatten.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 5, 57, 'Da dachten sie: »Auch wir wollen uns einen Namen machen und zum Kampf mit den Heiden rings um uns her ausziehen!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 5, 58, 'So boten sie denn die Mannschaften auf, die unter ihrem Befehl standen, und zogen gegen Jamnia.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 5, 59, 'Aber Gorgias mit seinen Leuten zog aus der Stadt hinaus ihnen entgegen und griff sie an;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 5, 60, 'und Joseph und Asarja wurden geschlagen und bis an die Grenze des jüdischen Landes verfolgt, und es fielen an diesem Tage von dem israelitischen Kriegsvolk gegen 2000 Mann.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 5, 61, 'So hatte also das israelitische Heer eine schwere Niederlage erlitten, weil sie dem Befehle des Judas und seiner Brüder nicht gehorcht, sondern gemeint hatten, Heldentaten verrichten zu müssen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 5, 62, 'Sie stammten eben nicht aus dem Geschlecht jener Männer, durch deren Verdienst den Israeliten die Rettung zuteil geworden ist.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 5, 63, 'Der Held Judas aber und seine Brüder gewannen großen Ruhm bei allen Israeliten und selbst bei den Heiden, wo immer man auf sie zu sprechen kam;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 5, 64, 'und groß war die Zahl derer, welche zu ihnen kamen, um ihnen Glück zu wünschen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 5, 65, 'Judas zog dann mit seinen Brüdern ins Feld, um die Nachkommen Esaus im südlichen Teile des Landes zu bekriegen. Er nahm Hebron mit den zugehörigen Ortschaften ein, schleifte die Festungswerke der Stadt und verbrannte ihre Türme ringsum.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 5, 66, 'Sodann brach er auf zum Zuge ins Land der Philister und durchzog Samaria.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 5, 67, 'Bei dieser Gelegenheit kamen Priester im Kampfe ums Leben, die dort auch ihre Tapferkeit zeigen wollten, indem sie unbedachterweise am Kampfe teilnahmen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 5, 68, 'Judas wandte sich dann nach Asotus im Philisterlande, zerstörte die dortigen Altäre, verbrannte die Schnitzbilder ihrer Götter, plünderte die Städte und kehrte dann nach Judäa zurück.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 6, 1, 'Unterdessen durchzog der König Antiochus die oberen Länder. Als er nun vernahm, daß Elymais in Persien eine durch ihren Reichtum, durch Silber und Gold berühmte Stadt sei');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 6, 2, 'und daß sich dort ein überaus reicher Tempel mit goldenen Rüstungen und Panzern und anderen Waffen befinde, die der mazedonische König Alexander, der Sohn Philipps, der erste König von Griechenland, dort niedergelegt habe,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 6, 3, 'so zog er hin und suchte die Stadt zu erobern und zu plündern; aber es gelang ihm nicht, weil die Sache den Stadtbewohnern kund geworden war.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 6, 4, 'Sie traten ihm also mit den Waffen in der Hand entgegen, und er mußte die Flucht ergreifen und zu seinem großen Leidwesen von dort wieder abziehen, um nach Babylon zurückzukehren.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 6, 5, 'Da kam ein Bote zu ihm nach Persien mit der Meldung, daß seine Heere, die ins jüdische Land geschickt worden waren, in die Flucht geschlagen seien;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 6, 6, 'auch Lysias, der an der Spitze einer starken Heeresmacht ins Feld gezogen war, sei von ihnen geschlagen worden; die Juden aber seien durch die Waffen und den Kriegsbedarf und die reiche Beute, die sie den besiegten Heeren abgenommen hätten, stark geworden,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 6, 7, 'hätten auch den scheußlichen Greuel, den der König auf dem Altar in Jerusalem aufgestellt habe, wieder entfernt und das Heiligtum wie früher mit hohen Mauern umgeben, ebenso auch seine Stadt Bethsura.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 6, 8, 'Als der König diesen Bericht vernahm, erschrak er sehr und wurde tief erschüttert; er mußte sich zu Bett legen und verfiel vor Kummer in eine Krankheit, weil die Dinge nicht nach seinem Wunsch verlaufen waren.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 6, 9, 'Er blieb dort längere Zeit, weil tiefer Kummer ihn immer aufs neue überfiel. Da er nun sein Ende nahen fühlte,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 6, 10, 'ließ er alle seine Freunde zu sich rufen und richtete folgende Ansprache an sie: »Der Schlaf bleibt meinen Augen fern, und aller Mut ist mir vor Kummer entschwunden.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 6, 11, 'Ich sage zu mir selbst: In welche Trübsal bin ich geraten, und in welchem gewaltigen Unglücksstrudel befinde ich mich jetzt! Ich war ja doch menschenfreundlich und beliebt während meiner Regierung.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 6, 12, 'Jetzt aber denke ich an die Übeltaten zurück, die ich in Jerusalem verübt habe, wo ich alle goldenen und silbernen Geräte, die sich dort befanden, geraubt habe, und ich habe (Heere) hingeschickt, um die Bewohner des jüdischen Landes ohne Ursache auszurotten.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 6, 13, 'Ich sehe wohl ein, daß mich zur Strafe dafür dieses Unglück betroffen hat; und nun muß ich ach! in einem fremden Lande in tiefer Betrübnis sterben!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 6, 14, 'Hierauf berief er Philippus, einen seiner Freunde, setzte ihn zum Reichsverweser ein');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 6, 15, 'und übergab ihm sein Diadem, seinen Mantel und seinen Siegelring, damit er seinen Sohn Antiochus erziehe und zur Führung der Staatsgeschäfte fähig mache.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 6, 16, 'Hierauf starb der König Antiochus daselbst im Jahre 149.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 6, 17, 'Als nun Lysias den Tod des Königs erfuhr, setzte er dessen Sohn Antiochus, den er bisher erzogen hatte, als König ein und legte ihm den Beinamen Eupator bei.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 6, 18, 'Unterdessen machte die (syrische) Besatzung in der Burg den Israeliten rings um den Tempelbezirk in beängstigender Weise zu schaffen; sie war allezeit darauf bedacht, Unheil anzurichten, und bildete eine Stütze für die Heiden.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 6, 19, 'Daher entschloß Judas sich dazu, ihrem Treiben ein Ende zu machen; er bot also sein gesamtes Kriegsvolk auf, um sie zu belagern.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 6, 20, 'Als alle sich gesammelt hatten, eröffneten sie die Belagerung im Jahre 150, indem er Geschütztürme und Belagerungsmaschinen gegen sie aufstellte.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 6, 21, 'Es gelang aber einigen von ihnen, aus der Umschließung zu entkommen, und diesen schlossen sich etliche vom Glauben abgefallene Juden an;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 6, 22, 'diese begaben sich zum Könige und sagten zu ihm: »Wann wirst du endlich Recht schaffen und Rache für unsere Brüder nehmen?');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 6, 23, 'Wir haben deinem Vater willig gedient und nach seinen Geboten uns verhalten und sind seinen Befehlen nachgekommen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 6, 24, 'Eben deswegen haben nun unsere Volksgenossen die Burg zu belagern begonnen und sind uns feind geworden; ja, sie haben die von uns, deren sie habhaft werden konnten, ums Leben gebracht, und unser Hab und Gut ist geraubt worden.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 6, 25, 'Und nicht gegen uns allein haben sie ihre Hand ausgestreckt, sondern auch gegen alle angrenzenden Gebiete.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 6, 26, 'Und jetzt haben sie sich gar gegen die Burg in Jerusalem gelagert, um sich ihrer zu bemächtigen, und haben ihr Heiligtum und auch Bethsura befestigt.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 6, 27, 'Und wenn du ihnen nicht schnell zuvorkommst, so werden sie noch Schlimmeres als dies anrichten, und du wirst nicht mehr imstande sein, ihnen Einhalt zu tun!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 6, 28, 'Als der König dies hörte, geriet er in Zorn; er ließ alle seine Freunde zusammenkommen, auch seine Heeresobersten und die Befehlshaber der Reiterei;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 6, 29, 'auch aus anderen Reichen und von den Inseln des Mittelmeeres kamen Söldnerscharen zu ihm,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 6, 30, 'so daß sich seine Streitkräfte auf 100000 Mann zu Fuß und 20000 Reiter beliefen; außerdem waren noch 32 für den Krieg abgerichtete Elefanten da.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 6, 31, 'Diese zogen dann durch Idumäa, lagerten sich vor Bethsura und bestürmten es längere Zeit, wobei sie auch Belagerungsmaschinen in Anwendung brachten. Die Belagerten aber machten Ausfälle, verbrannten die Maschinen und wehrten sich mannhaft.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 6, 32, 'Judas zog nun von der Burg (in Jerusalem) ab und lagerte sich bei Beth-Sacharja dem königlichen Heere gegenüber.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 6, 33, 'Da ließ der König sein Heer früh am Morgen im Eilmarsch auf Beth-Sacharja zu vorrücken, seine Truppen stellten sich dann in Schlachtordnung auf, und man ließ Trompetensignale erschallen;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 6, 34, 'den Elefanten aber zeigte man Rotwein und (gegorenen) Maulbeersaft, um sie zum Kampfe zu reizen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 6, 35, 'Man verteilte die Tiere unter die einzelnen Abteilungen des Heeres und ordnete jedem Elefanten 1000 Mann zu, die mit Kettenpanzern gewappnet waren und eherne Helme auf dem Haupte trugen; auch waren jedem Tiere 500 auserlesene Reiter beigegeben;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 6, 36, 'diese waren auch früher schon immer mit dem (betreffenden) Tiere, wo es war, zusammengewesen und waren mit ihm gegangen, wohin es immer ging, ohne sich von ihm zu entfernen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 6, 37, 'Auf den Tieren aber waren feste Holztürme angebracht, die ein jedes Tier bedeckten und mit Gurten kunstvoll auf ihm festgemacht waren; und auf jedem Turme befanden sich 32 Krieger, die von oben her kämpften, und überdies der (das Tier lenkende) Inder.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 6, 38, 'Die übrige Reiterei aber stellte man hierhin und dorthin an die beiden Flügel des Heeres, um (die Feinde) zu beunruhigen und den Abteilungen als Deckung zu dienen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 6, 39, 'Als nun die Sonne auf die vergoldeten und mit Erz überzogenen Schilde schien, erglänzten die Anhöhen von ihnen und strahlten wie Feuerfackeln.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 6, 40, 'Ein Teil des königlichen Heeres breitete sich über die hohen Berge aus und ein anderer über die Niederungen, und sie zogen zuversichtlich und in guter Ordnung heran.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 6, 41, 'Da wurden alle bestürzt, die das Getöse von diesen Massen und den Anmarsch ihrer Menge und das Klirren ihrer Waffen vernahmen; denn es war ein gewaltig großes und starkes Heer.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 6, 42, 'Nun zog Judas mit seinem Heere zum Angriff heran, und es fielen vom königlichen Heer 600 Mann.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 6, 43, 'Als nun Eleasar (genannt) Awaran eines der Tiere mit königlichen Panzern gewappnet und alle die übrigen Tiere überragen sah, so daß es aussah, als ob sich der König auf ihm befände,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 6, 44, 'da opferte er sich auf, um sein Volk zu retten und sich ewigen Ruhm zu erwerben.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 6, 45, 'Er lief nämlich kühn auf das Tier zu mitten in die feindliche Abteilung hinein und teilte tödliche Hiebe nach rechts und nach links aus, so daß die Feinde hüben und drüben vor ihm zurückwichen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 6, 46, 'Sodann kroch er unter den Elefanten, stieß ihm das Schwert in den Leib und tötete ihn; da das Tier dann aber zur Erde auf ihn fiel, fand er dort seinen Tod.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 6, 47, 'Als sie aber die Überlegenheit der königlichen Streitmacht erkannten und den Andrang des Heeres gewahrten, wichen sie vor ihnen zurück.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 6, 48, 'Hierauf zogen die Mannschaften des königlichen Heeres zum Kampfe mit ihnen nach Jerusalem hinauf, und der König schlug ein Lager auf zur Unterwerfung des jüdischen Landes und zur Eroberung des Berges Zion.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 6, 49, 'Mit der Besatzung von Bethsura aber schloß er einen Vertrag, auf Grund dessen sie aus dem Orte abzogen; sie hatten sich dort infolge des Mangels an Lebensmitteln nicht länger halten können, weil für das Land ein Sabbatjahr bestand.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 6, 50, 'Der König gewann also Bethsura und legte eine Besatzung hinein, um es zu behaupten.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 6, 51, 'Das Heiligtum aber belagerte er lange Zeit und ließ dort Geschütztürme und andere Maschinen aufstellen, z.B. Feuerwerfer und Skorpione, um Pfeile zu schießen, auch Steinschleuderer.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 6, 52, 'Aber auch die Belagerten stellten Maschinen auf gegen die der Feinde und verteidigten sich lange Zeit.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 6, 53, 'Doch hatten sie keine Lebensmittel mehr im Heiligtum, weil es das siebente Jahr war, und die, welche vor den Heiden nach Judäa geflüchtet waren, hatten den Rest der Vorräte aufgezehrt.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 6, 54, 'So waren denn im Heiligtum nur wenige Männer zurückgeblieben, weil der Hunger für sie unerträglich geworden war; sie hatten sich vielmehr zerstreut, ein jeder nach seinem Wohnort.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 6, 55, 'Da erhielt Lysias die Nachricht, daß Philippus, den der König Antiochus kurz vor seinem Tode zum Vormund seines Sohnes Antiochus bestellt hatte, um ihn für die Regierung heranzubilden,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 6, 56, 'aus Persien und Medien zurückgekehrt sei, und zwar an der Spitze der Truppen, die mit dem Könige ausgezogen waren, und daß er darauf ausgehe, die Regierung des Reiches in seine Hand zu bringen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 6, 57, 'Da war er auf eiligen Abzug bedacht und sagte zum Könige, sowie zu den Heerführern und den Mannschaften: »Wir werden jeden Tag schwächer; auch haben wir nur noch wenig Proviant, und der Platz, den wir belagern, ist fest; dazu liegt uns die Sorge für das Reich ob.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 6, 58, 'So wollen wir denn jetzt diesen Leuten die Hand der Versöhnung bieten und Frieden mit ihnen und mit ihrem ganzen Volke schließen;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 6, 59, 'wir wollen ihnen also gestatten, nach ihren Gesetzen und Bräuchen zu leben wie früher; denn um ihrer Gesetze und Bräuche willen, die wir abgeschafft haben, sind sie in solchen Zorn geraten und haben dies alles getan«.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 6, 60, 'Dieser Vorschlag fand den Beifall des Königs und der Heerführer, und Lysias ließ ihnen Friedensvorschläge machen, die sie auch annahmen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 6, 61, 'Der König und die Heerführer beschworen diesen Vertrag, und die Belagerten zogen aus der Festung ab.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 6, 62, 'Als dann aber der König auf den Berg Zion gezogen war und die Festungswerke des Platzes in Augenschein genommen hatte, da brach er den Eid, den er geschworen hatte, und gab Befehl, die Mauer ringsum niederzureißen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 6, 63, 'Hierauf zog er in aller Eile ab und kehrte nach Antiochien zurück; dort fand er Philippus als Herrn der Stadt vor; er griff ihn an und bemächtigte sich der Stadt mit Gewalt.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 7, 1, 'Im Jahre 151 entwich Demetrius, der Sohn des Seleukus aus Rom und landete mit wenigen Begleitern in einer Seestadt und nahm den Königstitel an.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 7, 2, 'Als er sodann (in Antiochien) in den Königspalast seiner Väter einzog, ergriffen die Truppen den Antiochus und Lysias, um sie vor ihn zu bringen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 7, 3, 'Als er Kunde davon erhielt, erklärte er: »Sie dürfen mir nicht vor die Augen kommen!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 7, 4, 'Da wurden sie von den Truppen ermordet, und Demetrius bestieg den Königsthron.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 7, 5, 'Nun kamen zu ihm alle abtrünnigen und gottlosen Männer aus Israel unter Führung des Alkimus, der Hoherpriester sein wollte.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 7, 6, 'Diese erhoben bei dem Könige folgende Anklagen gegen das Volk: »Judas und seine Brüder haben alle deine Freunde ums Leben gebracht und uns aus unserem Vaterlande vertrieben.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 7, 7, 'Entsende daher jetzt einen Mann, der dein Vertrauen besitzt, daß er hingehe und sich all das Unheil ansehe, das jener über uns und das Land des Königs gebracht hat, und sie und alle ihre Helfershelfer bestrafe«.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 7, 8, 'Da erwählte der König aus der Zahl der königlichen Freunde den Bakchides, den Statthalter der Provinz jenseits des Euphrat, einen im Reiche hochangesehenen und dem Könige treu ergebenen Mann;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 7, 9, 'diesen entsandte er zusammen mit dem gottlosen Alkimus, dem er das Hohepriestertum zugesagt hatte, und erteilte ihm den Befehl, die Rache an den Israeliten zu vollziehen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 7, 10, 'So brachen sie denn auf und kamen mit starker Heeresmacht ins jüdische Land. Da sandte Bakchides Boten an Judas und seine Brüder mit friedlichen Worten, aber in hinterlistiger Absicht;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 7, 11, 'sie schenkten jedoch ihren Worten keine Beachtung, weil sie sahen, daß jene mit starker Heeresmacht gekommen waren.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 7, 12, 'Es kam aber bei Alkimus und Bakchides eine Schar von Schriftgelehrten zusammen, um berechtigte Wünsche vorzutragen;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 7, 13, 'und zwar waren die Asidäer die ersten unter den Israeliten, die in ein friedliches Verhältnis mit ihnen zu treten wünschten.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 7, 14, 'Sie dachten nämlich: »Ein Priester von Aarons Stamm ist mit diesem Heere gekommen; der wird uns nichts zuleide tun«.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 7, 15, 'Und er ließ auch friedliche Worte gegen sie verlauten und gab ihnen die eidliche Versicherung: »Wir werden niemals Böses gegen euch und eure Freunde im Schilde führen«.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 7, 16, 'Da schenkten sie ihm Vertrauen; doch er ließ sechzig Männer von ihnen festnehmen und an einem Tage hinrichten gemäß dem Worte der Heiligen Schrift:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 7, 17, '»Die Leiber deiner Heiligen haben sie hingestreckt und ihr Blut vergossen rings um Jerusalem her, und niemand war für sie da, sie zu begraben«.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 7, 18, 'Da befiel Furcht vor ihnen und Zittern die ganze Bevölkerung, denn man sagte: »Diese Menschen kennen keine Wahrheit und kein Recht, denn diese haben den Vertrag und den Eid gebrochen, den sie geschworen hatten«.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 7, 19, 'Hierauf zog Bakchides aus Jerusalem ab und lagerte sich bei Bezeth; von dort sandte er Mannschaften aus und ließ eine große Zahl von Männern festnehmen, die es mit ihm gehalten hatten, dann aber doch wieder abgefallen waren, auch einige aus dem Volke; er ließ sie grausam töten und ihre Leichen in die große Zisterne werfen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 7, 20, 'Sodann übergab er das Land dem Alkimus, ließ eine Abteilung Soldaten zu seinem Schutze bei ihm und kehrte zum Könige zurück.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 7, 21, 'Alkimus aber suchte nun das Hohepriestertum mit Gewalt an sich zu bringen,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 7, 22, 'wobei alle diejenigen es mit ihm hielten, die ihr Volk zu zerrütten suchten; sie bemächtigten sich der Herrschaft im jüdischen Lande und richteten entsetzliches Unheil in Israel an.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 7, 23, 'Als nun Judas all das Unheil sah, welches Alkimus und sein Anhang an den Israeliten verübten, noch schlimmer als die Heiden,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 7, 24, 'zog er im ganzen Gebiet von Judäa umher und nahm Rache an den Abtrünnigen, so daß diese verhindert wurden, Züge in das Land zu unternehmen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 7, 25, 'Als aber Alkimus sah, daß Judas und sein Anhang wieder an Macht gewachsen waren, und erkannte, daß er sich gegen sie nicht zu halten vermöge, kehrte er zum Könige zurück und führte schwere Klage gegen sie.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 7, 26, 'Der König sandte also Nikanor ab, einen seiner namhaftesten Feldherren, der die Israeliten tödlich haßte, und gab ihm den Befehl, das Volk auszurotten.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 7, 27, 'So kam denn Nikanor mit einem großen Heere und ließ an Judas und seine Brüder hinterlistigerweise eine friedliche Botschaft gelangen, die so lautete:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 7, 28, '»Es soll zwischen mir und euch kein Streit bestehen! Ich will mit einer kleinen Mannschaft kommen, um euch in Frieden zu begrüßen!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 7, 29, 'Er kam denn auch wirklich zu Judas, und sie begrüßten sich freundschaftlich, jedoch hatten die Feinde alles vorbereitet, um den Judas aufzugreifen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 7, 30, 'Als nun Judas Kunde davon erhielt, daß jener in böser Absicht zu ihm gekommen sei, zog er sich eilig vor ihm zurück und wollte nicht länger persönlich mit ihm zusammensein.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 7, 31, 'So erkannte denn Nikanor, daß sein Anschlag verraten war, und brach nun auf, dem Judas entgegen, um ihm bei Kapharsalama eine Schlacht zu liefern.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 7, 32, 'Dabei fielen von den Leuten Nikanors gegen 5000 Mann; die übrigen flohen in die Davidsstadt.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 7, 33, 'Später ging Nikanor auf den Zionsberg hinauf; da traten ihm einige von den Priestern und von den Vornehmsten des Volkes aus dem heiligen Bezirk entgegen, um ihn freundlich zu begrüßen und ihn auf das Brandopfer aufmerksam zu machen, das man gerade für das Wohl des Königs darbrachte.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 7, 34, 'Er aber verhöhnte und verlachte sie, ja er entehrte sie tätlich und führte hochfahrende Reden;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 7, 35, 'voller Zorn schwur er dann: »Wenn Judas und sein Heer mir jetzt nicht sofort ausgeliefert wird, so werde ich, wenn ich wohlbehalten hierher zurückgekehrt bin, dieses Haus verbrennen!« Hierauf ging er voller Zorn von dannen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 7, 36, 'Da gingen die Priester hinein, traten vor den Opferaltar und den Tempel, weinten und beteten:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 7, 37, '»Du, Herr, hast dieses Haus dir erwählt, daß es nach deinem Namen genannt werde und für dein Volk eine Stätte des Gebets und Flehens sei.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 7, 38, 'Nimm Rache an diesem Menschen und seinem Heere, daß sie durchs Schwert fallen! Gedenke ihrer Lästerreden und laß sie nicht länger hier im Lande bleiben!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 7, 39, 'Als Nikanor dann aus Jerusalem abgezogen war, und sich in Beth-Horon gelagert hatte, stieß noch ein syrisches Heer zu ihm,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 7, 40, 'Judas aber lagerte sich bei Adasa mit 3000 Mann. Da betete Judas folgendermaßen:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 7, 41, '»Als einst die Gesandten des Assyrerkönigs gelästert hatten, ging ein Engel von dir aus, o Herr, und erschlug von ihnen 185000 Mann.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 7, 42, 'Ebenso vernichte nun heute auch dieses Heer vor uns, damit die übrigen erkennen, daß er lästerlich wider dein Heiligtum geredet hat; ja, laß ihn büßen, wie seine Bosheit es verdient hat!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 7, 43, 'Es kam dann zur Schlacht zwischen den beiden Herren am 13. Tage des Monats Adar; da wurde das Heer Nikanors geschlagen, und er selbst fiel als erster in der Schlacht.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 7, 44, 'Als nun seine Mannschaften sahen, daß er gefallen war, warfen sie ihre Waffen weg und wandten sich zur Flucht.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 7, 45, 'Die Juden verfolgten sie eine Tagereise weit von Adasa bis in die Gegend von Gazera und ließen hinter ihnen her die Signaltrompeten erschallen;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 7, 46, 'da kamen die Leute aus allen jüdischen Dörfern ringsum heraus und überflügelten sie; da wandten die einen sich gegen die anderen, so daß sie alle durchs Schwert fielen; auch nicht einer von ihnen blieb am Leben.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 7, 47, 'Sie sammelten dann die Waffenbeute und nahmen auch das geraubte Gut an sich; dem Nikanor aber hieben sie den Kopf ab, sowie auch die rechte Hand, die er in seinem Hochmut erhoben hatte; die nahmen sie mit und hängten sie bei Jerusalem öffentlich auf.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 7, 48, 'Das Volk aber war hocherfreut und feierte jenen Tag als einen hohen Freudentag;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 7, 49, 'zugleich beschloß man, diesen Tag, den 13. Adar, alljährlich als Festtag zu begehen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 7, 50, 'Nun wurde dem jüdischen Lande eine kurze Ruhezeit zuteil.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 1, 'Damals erhielt Judas Kunde von dem Ruhm der Römer, daß sie stark und mächtig seien und allen denen, die sich an sie anschlössen, Wohlwollen bewiesen und Freundschaft mit allen ihren Bundesgenossen hielten,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 2, 'und daß sie stark und mächtig seien. Man erzählte ihm auch von ihren Kriegen und von den Heldentaten, die sie in den Kriegen mit den Galliern vollführt und daß sie diese bezwungen und tributpflichtig gemacht hätten;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 3, 'sodann, was sie alles im Lande Spanien vollbracht hätten, um sich der dortigen Silber- und Goldbergwerke zu bemächtigen;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 4, 'und wie sie dies ganze Land durch ihre Klugheit und Beharrlichkeit unterworfen hätten, obgleich dies Land sehr weit von ihnen entfernt war, und wie sie die Könige, die vom Ende der Erde gegen sie herangezogen seien, bekämpft hätten, bis sie ihrer Herr geworden wären und ihnen eine schwere Niederlage beigebracht hätten; und wie die übrigen ihnen nun jährlich Tribut entrichteten;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 5, 'ferner wie sie Philippus und den Griechenkönig Perseus geschlagen und alle, die sich wider sie aufgelehnt, im Kriege besiegt und unterjocht hätten;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 6, 'und wie Antiochus der Große, der König von Asien, der mit 120 Elefanten und einem riesigen Heere von Reitern, Kriegswagen und Fußvolk zum Kampf gegen sie ausgezogen war, von ihnen geschlagen worden sei,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 7, 'und zwar hätten sie ihn lebendig gefangen genommen und hätten ihnen, nämlich ihm und seinen Nachfolgern in der Regierung, die Zahlung eines hohen Tributs, sowie die Stellung von Geiseln und die Abtretung eines Teiles seines Reiches auferlegt,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 8, 'und zwar des indischen Landes und Mediens und Lydiens, also eines Teiles seiner schönsten Länder, die sie dann, nachdem sie sie von ihm erhalten hatten, dem König Eumenes geschenkt hätten.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 9, 'Und als dann die Bewohner Griechenlands den Beschluß gefaßt hätten, gegen sie zu ziehen und sie zu vernichten,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 10, 'dies aber zu ihrer Kenntnis gekommen sei, da hätten sie einen Feldherrn gegen sie entsandt und Krieg mit ihnen geführt, und es seien viele von ihnen auf den Schlachtfeldern gefallen; man habe dann ihre Weiber und Kinder in die Gefangenschaft geführt, sie ausgeplündert, ihr Land unterworfen, die Festungen geschleift und die Bevölkerung in Unterwürfigkeit versetzt bis zum heutigen Tage.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 11, 'Auch die übrigen Reiche und die Inseln, soviele ihnen jemals entgegengetreten seien, hätten sie vernichtet und sich dienstbar gemacht;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 12, 'mit ihren Freunden aber und mit denen, welche sich ihnen anvertrauten, hielten sie gute Freundschaft, während sie die Reiche nah und fern sich unterworfen hätten; und alle, die ihren Namen hörten, seien in Furcht vor ihnen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 13, 'Alle, denen sie Hilfe leisten wollten und deren Herrschaft ihnen erwünscht sei, behielten die Herrschaft dauernd; doch setzten sie auch nach Gutdünken ab und seien zu außerordentlicher Macht emporgestiegen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 14, 'Bei alledem aber habe sich keiner von ihnen die Krone aufgesetzt und sich mit dem Purpurmantel bekleidet, um darin zu prunken;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 15, 'sondern sie hätten sich eine Ratsversammlung geschaffen, in der sich täglich 320 Ratsherren fort und fort über das Wohl des Volkes berieten, damit es gut um sie stände;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 16, 'und sie vertrauten alljährlich einem einzigen Manne die Obergewalt über sich und die Regierung ihre ganzen Länderbesitzes an, und alle gehorchten diesem Einen, und Neid und Eifersucht gäbe es unter ihnen nicht.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 17, 'Judas erwählte also Eupolemus, den Sohn des Johannes, des Sohnes des Akkos, und Jason, den Sohn Eleasars, und sandte sie nach Rom, um Freundschaft und Bundesgenossenschaft mit ihnen zu schließen');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 18, 'und damit sie ihnen das Knechtsjoch abnähmen, weil ja, wie sie sähen, das griechische Königshaus die Israeliten in Knechtschaft hielte.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 19, 'So begaben sie sich denn nach Rom – es war das eine sehr weite Reise –, traten vor die Ratsversammlung, erhielten dort das Wort und sagten:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 20, '»Judas, der Makkabäer, und seine Brüder und das ganze jüdische Volk haben uns zu euch hergesandt, um ein Bündnis und Freundschaft mit euch abzuschließen und damit wir in die Zahl eurer Bundesgenossen und Freunde eingeschrieben werden«.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 21, 'Diese Rede wurde günstig von ihnen aufgenommen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 22, 'Folgendes ist die Abschrift der Urkunde, die sie auf eherne Tafeln aufzeichnen ließen und nach Jerusalem sandten, damit sie dort bei ihnen als ein Denkmal des Freundschaftsbundes und der Bundesgenossenschaft diene:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 23, '»Möge es den Römern und dem jüdischen Volke zu Wasser und zu Lande für alle Folgezeit wohlgehen und Schwert und Feinde ihnen fern bleiben!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 24, 'Wenn aber ein Krieg ausbricht zuerst für die Römer oder für irgend einen ihrer Bundesgenossen im ganzen Bereich ihrer Herrschaft,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 25, 'so soll das jüdische Volk ihnen mit ganzem Herzen Beistand leisten, wie die Umstände es ihnen zur Pflicht machen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 26, 'Doch sollen sie ihnen während des Krieges Lebensmittel, Waffen, Geld und Schiffe weder liefern noch verschaffen, nach dem Ermessen der Römer, sondern sollen ihren Verpflichtungen nachkommen, ohne Entgelt dafür zu empfangen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 27, 'Ebenso sollen aber auch, wenn dem Volke der Juden zuerst ein Krieg entstehen sollte, die Römer ihnen von Herzen Hilfe leisten, wie die Umstände es ihnen zur Pflicht machen;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 28, 'doch sollen ihnen, solange sie Hilfe leisten, Lebensmittel, Waffen, Geld und Schiffe nicht geliefert werden, nach dem Ermessen Roms; und sie sollen diesen Verpflichtungen nachkommen, und zwar ohne Trug«.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 29, 'Auf Grund dieser Bestimmungen also schlossen die Römer einen Vertrag mit dem jüdischen Volke.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 30, '»Wenn aber nachträglich der eine oder der andere Teil sich dazu entschließt, etwas hinzuzufügen oder wegzulassen, so sollen sie das nach ihrem Belieben tun dürfen, und was sie hinzufügen oder weglassen, soll gültig sein.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 31, 'Was sodann die Unbilden betrifft, die der König Demetrius ihnen zufügt, so haben wir ihm folgendes geschrieben: ›Warum hast du unseren Freunden und Bundesgenossen, den Juden, ein schweres Joch auferlegt?');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 32, 'Sollten sie also noch ferner Klage über dich führen, so werden wir ihnen zu ihrem Recht verhelfen und dich zu Wasser und zu Land bekriegen‹«.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 9, 1, 'Als aber (der König) Demetrius vernahm, daß Nikanor und sein Heer in der Schlacht gefallen seien, schickte der Bakchides und Alkimus noch zum zweitenmal ins jüdische Land und den rechten Flügel seiner Heeresmacht mit ihnen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 9, 2, 'Sie zogen in der Richtung nach Galgata, lagerten sich vor Massaloth im Gebiet von Arbela, eroberten den Platz und brachten viele Menschen ums Leben.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 9, 3, 'Sodann, im ersten Monat des Jahres 152 lagerten sie sich vor Jerusalem,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 9, 4, 'brachen aber bald wieder auf und zogen nach Berea mit 20000 Mann zu Fuß und 2000 Reitern.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 9, 5, 'Judas aber stand in einem Lager bei Elasa mit 3000 auserlesenen Kriegern.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 9, 6, 'Als diese nun die große Zahl der feindlichen Truppen sahen, gerieten sie in große Furcht, und viele verliefen sich aus dem Lager, so daß schließlich nur noch 800 Mann von ihnen übrig blieben.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 9, 7, 'Als Judas nun sah, daß sein Heer sich auflöste und der Kampf für ihn doch unvermeidlich sei, wurde er tief bekümmert, daß ihm die Zeit fehlte, seine Leute wieder zu sammeln;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 9, 8, 'und in seiner Verzweiflung sprach er zu denen, die ihm noch geblieben waren: »Auf! laßt uns auf unsere Feinde losgehen! Vielleicht können wir den Kampf mit ihnen bestehen«.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 9, 9, 'Sie suchten ihn nun davon abzubringen, indem sie ihm vorstellten: »Das ist unmöglich; wir wollen lieber für diesmal unser Leben retten und später mit unseren Brüdern wiederkommen und dann gegen sie kämpfen: wir sind unser zu wenige«.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 9, 10, 'Judas aber erwiderte: »Da sei Gott vor, daß ich das tue und vor ihnen fliehe! Wenn denn unsere Stunde gekommen ist, so wollen wir mannhaft für unsere Brüder sterben und auf unserer Ehre keinen Flecken hinterlassen!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 9, 11, 'Hierauf zog das (feindliche) Heer aus dem Lager hinaus und stellte sich ihnen entgegen. Die Reiterei war in zwei Abteilungen geteilt; die Schleuderer und die Bogenschützen zogen dem Heere voran, und das Vordertreffen bildeten durchweg tapfere Krieger;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 9, 12, 'Bakchides aber befand sich auf dem rechten Flügel, und die Schlachtreihe rückte von beiden Seiten heran, wobei man in die Trompeten stieß.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 9, 13, 'Auch die Leute des Judas ließen die Trompeten erschallen, so daß die Erde von dem Getöse der beiden Heere erbebte, und der Kampf währte vom Morgen bis zum Abend.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 9, 14, 'Als nun Judas sah, daß Bakchides mit dem Kern seines Heeres auf dem rechten Flügel stand, da schlossen sich ihm alle an, die Mut im Herzen hatten,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 9, 15, 'und der rechte Flügel wurde von ihnen geschlagen, und sie verfolgten die Fliehenden bis zum Berge Azotus.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 9, 16, 'Als aber die Leute auf dem linken Flügel sahen, daß der rechte Flügel geschlagen war, nahmen sie eine Schwenkung vor und kamen hinter Judas und seinen Leuten her, diesen in den Rücken.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 9, 17, 'Da entspann sich ein heißer Kampf, und es ab zahlreiche Tote auf beiden Seiten;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 9, 18, 'auch Judas fiel, und die Übriggebliebenen ergriffen die Flucht.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 9, 19, 'Jonathan aber und Simon hoben ihren Bruder Judas auf und begruben ihn in der Gruft seiner Väter in Modein;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 9, 20, 'sie beweinten ihn dort, und ganz Israel veranstaltete eine große Totenklage um ihn, ein mehrtägiges Trauerfest, wobei man ausrief:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 9, 21, '»Wie ist der Held gefallen, der Retter Israels!«. –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 9, 22, 'Was aber sonst noch von Judas zu berichten wäre, von den Kriegen und den Heldentaten, die er vollführt hat, und von seiner Größe, das ist nicht aufgezeichnet worden; und doch lag ein überaus reicher Stoff vor.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 9, 23, 'Nach dem Tode des Judas erhoben die Abtrünnigen im ganzen Lande Israel ihr Haupt, und alle Übeltäter kamen hoch.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 9, 24, 'Zugleich entstand in jener Zeit eine sehr große Hungersnot, so daß auch der Erdboden in treuloser Weise mit ihnen gemeinsame Sache machte.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 9, 25, 'Da traf Bakchides eine Auswahl unter den gottlosen Personen und setzte sie zu Herren im Lande ein.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 9, 26, 'Diese forschten nach den Anhängern des Judas und ließen sie aufspüren und vor Bakchides bringen, der sie dann zur Strafe zog und sie schmachvoll behandelte.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 9, 27, 'So herrschte denn in Israel eine große Trübsal, wie solche nie dagewesen war seit der Zeit, in der kein Prophet mehr unter ihnen aufgetreten war.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 9, 28, 'Da versammelten sich alle Anhänger des Judas und sagten zu Jonathan:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 9, 29, '»Seit dem Tode deines Bruders Judas gibt es keinen Mann mehr wie ihn, der fähig wäre, gegen die Feinde und Bakchides und überhaupt wider die Gegner unseres Volkes ins Feld zu ziehen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 9, 30, 'Daher wählen wir dich heute zu unserem Oberhaupt und zum Anführer in unseren Kriegen«.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 9, 31, 'Jonathan übernahm nunmehr die Führerschaft und trat an die Stelle seines Bruders Judas.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 9, 32, 'Als Bakchides Kunde davon erhielt, suchte er ihn zu töten;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 9, 33, 'aber Jonathan und sein Bruder Simon und alle ihre Anhänger erfuhren es und flohen in die Wüste von Thekoa und lagerten sich beim Wasser der Zisterne von Asphar.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 9, 34, 'Bakchides erfuhr dies an einem Sabbattage und ging persönlich mit seinem ganzen Heere über den Jordan.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 9, 35, 'Jonathan hatte nämlich seinen Bruder (Johannes) als Anführer des Trosses entsandt und die mit ihm befreundeten Nabatäer gebeten, seine und seiner Leute Fahrhabe, die bedeutenden Wert hatten, bei ihnen zur Aufbewahrung unterbringen zu dürfen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 9, 36, 'Aber die Ambritervon Medaba waren gekommen, hatten sich des Johannes mit allem, was er mit sich führte, bemächtigt und waren damit abgezogen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 9, 37, 'Einige Zeit später aber hatte man dem Jonathan und seinem Bruder Simon gemeldet, daß die Ambriter eine große Hochzeit feierten und daß sie die Braut, die Tochter eines der vornehmsten kanaanitischen Edlen, mit großem Gepränge von Nadabath abzuholen im Begriff seien.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 9, 38, 'Da hatten sie ihres Bruders Johannes gedacht, waren hinaufgezogen und hatten sich im Gebirge in einem Hinterhalt versteckt.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 9, 39, 'Als sie dann spähend Umschau hielten, war plötzlich Lärm erschollen und ein großer Troß sichtbar geworden, indem der Bräutigam mit seinen Freunden und Brüdern ihnen entgegenzog, mit Handpauken und Musik und vielen Waffen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 9, 40, 'Da hatten sie sich aus ihrem Hinterhalt auf sie gestürzt und sie niedergemacht, so daß viele Erschlagene dalagen; die Übriggebliebenen waren in die Berge geflohen, und jene hatten sich all ihrer Beute bemächtigt;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 9, 41, 'die Hochzeit aber war so in Trauer verwandelt und der Schall ihrer Musik in Wehklage.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 9, 42, 'Nachdem sie auf diese Weise Rache für das Blut ihres Bruders genommen hatten, waren sie in die Sumpfniederung am Jordan zurückgekehrt. –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 9, 43, 'Bakchides also hatte dies erfahren und war mit einem großen Heere bis an die Ufer des Jordans an einem Sabbattage gezogen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 9, 44, 'Da sagte Jonathan zu seinen Leuten: »Auf! laßt uns nun für unser Leben kämpfen! denn unsere Lage ist heute ernster als je.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 9, 45, 'Ihr seht ja: wir haben den Kampf vor uns und hinter uns; das Wasser des Jordans ist hüben und drüben, dazu Sumpf und dichtes Gebüsch, nirgends eine Möglichkeit auszuweichen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 9, 46, 'So schreit denn jetzt zum Himmel, damit ihr aus der Hand eurer Feinde gerettet werdet!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 9, 47, 'Die Schlacht begann, Jonathan erhob den Arm, um Bakchides zu erschlagen, doch dieser wich vor ihm zurück.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 9, 48, 'Da sprang Jonathan mit den Seinen in den Jordan, und sie schwammen hinüber ans jenseitige Ufer; die Feinde aber gingen nicht über den Jordan, um sie drüben anzugreifen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 9, 49, 'Es waren aber auf Seiten des Bakchides an jenem Tage gegen 1000 Mann gefallen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 9, 50, 'Hierauf kehrte Bakchides nach Jerusalem zurück und legte feste Plätze in Judäa an: die Festung bei Jericho, ferner Emmaus, Bethhoron, Bethel, Thamnatha, Pharathon und Tephon; er umgab sie mit hohen Mauern, mit Toren und Riegeln');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 9, 51, 'und legte Besatzungen hinein, um gegen Israel feindlich vorzugehen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 9, 52, 'Er befestigte auch die Ortschaft Bethsura und Gasara und die Burg (zu Jerusalem) und legte Truppen hinein und Vorräte von Lebensmitteln.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 9, 53, 'Außerdem nahm er die Söhne der vornehmsten Einwohner des Landes als Geiseln und hielt sie in der Burg zu Jerusalem in Gewahrsam.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 9, 54, 'Im zweiten Monat des Jahres 153 gebot Alkimus, die Mauer des inneren Tempelvorhofes niederzureißen; er wollte nämlich das, was die Propheten geschaffen hatten, vernichten; und er fing wirklich mit dem Niederreißen an.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 9, 55, 'Da wurde er gerade zu dieser Zeit vom Schlage gerührt und sein Unternehmen dadurch verhindert; er verlor die Sprache und wurde gelähmt, so daß er kein Wort mehr zu reden vermochte und in betreff seines Hauses keine Verfügungen mehr treffen konnte.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 9, 56, 'So starb damals Alkimus unter großen Qualen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 9, 57, 'Als Bakchides nun sah, daß Alkimus tot war, kehrte er zum Könige zurück, und so hatte das jüdische Land zwei Jahre lang Ruhe.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 9, 58, 'Nun berieten sich die Abtrünnigen allesamt und sagten: »Jonathan und seine Anhänger leben jetzt in Ruhe und Sicherheit; wir wollen also Bakchides herbeiholen, der soll sie dann alle in einer Nacht gefangen nehmen«.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 9, 59, 'Sie gingen also hin und besprachen sich mit ihm.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 9, 60, 'So brach er denn mit einer großen Mannschaft auf und ließ heimlich Briefe an alle seine Anhänger im jüdischen Lande gelangen, sie sollten Jonathan samt seinen Gesinnungsgenossen festnehmen; doch sie waren dazu nicht imstande, weil ihr Anschlag zur Kenntnis jener gekommen war.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 9, 61, 'Vielmehr waren sie es, die aus der Zahl der Landesbewohner, welche den boshaften Plan angestiftet hatten, gegen 50 Mann ergriffen und ums Leben brachten.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 9, 62, 'Hierauf entwich Jonathan mit Simon und seinen Anhängern nach Bethbasi in der Wüste, baute dort das, was von dem Orte zerstört war, wieder auf und machte ihn zu einem festen Platze.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 9, 63, 'Als Bakchides dies erfuhr, zog er seine ganze Mannschaft zusammen und bot auch die betreffenden Juden auf.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 9, 64, 'Dann zog er vor Bethbasi, belagerte und bestürmte es längere Zeit und stellte Maschinen auf.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 9, 65, 'Da ließ Jonathan seinen Bruder Simon an Ort und Stelle zurück und zog mit geringer Mannschaft ins offene Land hinaus.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 9, 66, 'Er schlug Odomera und seine Brüder und die Phasironiter in ihrem Zeltlager. Als er so begonnen hatte, Siege zu erringen und mit seiner Streitmacht zurückzukehren');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 9, 67, 'machte Simon mit seinen Leuten einen Ausfall aus der Stadt und verbrannte die Maschinen;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 9, 68, 'dann griff er den Bakchides an, der eine Niederlage erlitt, und verursachte ihm großen Kummer, weil sein Anschlag und sein Feldzug mißlungen war.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 9, 69, 'Er geriet in leidenschaftlichen Zorn gegen die abtrünnigen Männer, die ihm zum Zuge gegen das Land geraten hatten; er ließ viele von ihnen umbringen und beschloß dann, in sein Land heimzukehren.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 9, 70, 'Als Jonathan das erfuhr, schickte er Gesandte an ihn, um Frieden mit ihm zu schließen und die Zurückgabe der Gefangenen zu erwirken.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 9, 71, 'Bakchides ging auch darauf ein, nahm die ihm gestellten Bedingungen an und schwur, solange Jonathan lebe, ihm nichts Böses zufügen zu wollen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 9, 72, 'Er gab ihm auch wirklich die Gefangenen zurück, die er früher aus dem Lande Judäa weggeführt hatte; dann zog er in sein Land heim und kehrte fortan nie wieder in ihr Gebiet zurück.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 9, 73, 'So war denn der Krieg für die Israeliten zu Ende. Jonathan aber nahm seinen Wohnsitz in Machmas; er leitete von nun an die Staatsgeschäfte und erreichte es, daß die Abtrünnigen aus Israel verschwanden.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 10, 1, 'Im Jahre 160 trat Alexander, der Sohn des Antiochus, mit dem Beinamen Epiphanes auf und eroberte Ptolemais; man nahm ihn willig auf, und so machte er sich dort zum König.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 10, 2, 'Auf die Kunde hiervon sammelte der König Demetrius ein gewaltiges Heer und zog gegen ihn in den Krieg.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 10, 3, 'Er ließ auch dem Jonathan ein freundliches Schreiben zugehen, um ihn hoch zu ehren.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 10, 4, 'Er dachte nämlich: »Wir wollen schleunigst einen Friedensbund mit ihm schließen, ehe er einen solchen mit Alexander gegen uns abschließt;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 10, 5, 'er möchte sonst an all das Böse denken, das wir ihm und seinen Brüdern und seinem ganzen Volke zugefügt haben«.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 10, 6, 'So gab er ihm also Vollmacht, ein Heer zu halten und sich mit Waffen zum Kriege zu versehen; weiter sollte er sein Bundesgenosse sein; auch ließ er ihm die Geiseln zurückgeben, die sich in der Burg (zu Jerusalem) befanden.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 10, 7, 'Hierauf begab sich Jonathan nach Jerusalem und las das Schreiben dem ganzen Volke und der ganzen Besatzung der Burg vor.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 10, 8, 'Da geriet diese in große Bestürzung, als sie vernahm, daß der König ihm gestattet habe, Truppen zusammenzubringen;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 10, 9, 'doch lieferten die Leute in der Burg dem Jonathan die Geiseln aus, die er dann ihren Eltern zurückgab.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 10, 10, 'Jonathan nahm nunmehr seinen Wohnsitz in Jerusalem und begann die Stadt aufzubauen und wiederherzustellen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 10, 11, 'Dabei gebot er den Werkleuten, zu den Mauern und besonders zur Befestigung des Zionsberges ringsum Quadersteine zu verwenden, um das Mauerwerk recht stark zu machen; dies geschah denn auch.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 10, 12, 'Da machten sich die Ausländer, die sich in den von Bakchides angelegten festen Plätzen befanden, eiligst davon;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 10, 13, 'ein jeder verließ seinen Wohnort und kehrte in sein Heimatland zurück;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 10, 14, 'nur in Bethsura blieben einige von denen wohnen, die vom Gesetz und den Satzungen abgefallen waren; denn dieser Platz diente ihnen als Zufluchtsstätte.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 10, 15, 'Als aber der König Alexander von all den Versprechungen hörte, die Demetrius dem Jonathan schriftlich gemacht hatte, und man ihm von den Kämpfen und Heldentaten erzählte, die er und seine Brüder verrichtet, und von den Leiden, die sie erduldet hätten,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 10, 16, 'da sagte er: »Könnten wir wohl noch einen solchen Mann finden? So wollen wir ihn denn jetzt zu unserem Freund und Bundesgenossen machen!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 10, 17, 'Er schrieb also einen Brief und ließ diesen dem Jonathan zugehen, folgenden Wortlauts:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 10, 18, '»König Alexander entbietet seinem Bruder Jonathan seinen Gruß.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 10, 19, 'Wir haben vernommen, daß du ein tapferer Krieger bist und würdig, unser Freund zu sein.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 10, 20, 'So bestellen wir dich denn heute zum Hohenpriester deines Volkes und verleihen dir den Ehrennamen eines Freundes des Königs« – er schickte ihm aber zugleich ein Purpurgewand und eine goldene Krone –, »damit du unsere Partei ergreifst und Freundschaft mit uns hältst«.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 10, 21, 'So legte denn Jonathan die heilige Amtstracht im siebenten Monat des Jahres 160 am Laubhüttenfest an, sammelte auch ein Heer und versah sich reichlich mit Waffen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 10, 22, 'Als nun Demetrius Kunde davon erhielt, wurde er betrübt und sagte:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 10, 23, '»Warum haben wir das verschuldet, daß Alexander uns zuvorgekommen ist, Freundschaft mit den Juden zu schließen, um sich zu verstärken?');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 10, 24, 'Auch ich will ihnen schreiben und ihnen ermutigende Zusagen von hohen Würden und Geschenken machen, damit sie auf meine Seite treten und mir Beistand leisten«.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 10, 25, 'So ließ er denn folgende Botschaft an sie ergehen: »König Demetrius entbietet dem Volke der Juden seinen Gruß.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 10, 26, 'Daß ihr die mit uns geschlossenen Verträge gehalten habt und der Freundschaft mit uns treu geblieben und nicht auf die Seite unserer Feinde getreten seid, haben wir vernommen und uns darüber gefreut.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 10, 27, 'So fahrt nun auch fort, uns treu zu bleiben, so wollen wir euch belohnen für das, was ihr uns gegenüber tut.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 10, 28, 'Wir wollen euch nämlich von mancherlei lästigen Verpflichtungen befreien und euch Geschenke geben.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 10, 29, 'So befreie ich euch denn schon jetzt und gewähre allen Juden Erlaß der Kopfsteuer und der Salzsteuer und der Kronensteuer.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 10, 30, 'Ebenso erlasse ich von heute ab und weiterhin die Steuern für den dritten Teil des Saatenertrags und für die Hälfte der Baumfrüchte, deren Erhebung mir zusteht, und will sie hinfort nicht mehr einziehen lassen vom Lande Juda und von den drei dazu geschlagenen Bezirken Samarias (und Galiläas), und zwar vom heutigen Tage ab für alle Folgezeit.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 10, 31, 'Jerusalem ferner soll heilig und steuerfrei sein samt seinem Gebiet und ebenso die Zehnten und die anderen Abgaben.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 10, 32, 'Ich verzichte auch auf die Gewalt über die Burg in Jerusalem und übergebe sie dem Hohenpriester, damit er eine Besatzung, die er selbst ausgewählt hat, zu ihrer Bewachung hineinlege.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 10, 33, 'Alle Juden, die aus dem jüdischen Lande in irgend einen Teil meines Reiches als Gefangene weggeführt worden sind, gebe ich ohne Lösegeld frei; und jedermann soll ihnen die Abgaben, auch für ihre Tiere, erlassen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 10, 34, 'Und alle Feste, Sabbate, Neumonde und sonst geheiligte Tage, dazu drei Tage vor und nach jedem Feste – sie alle sollen für alle Zeit in meinem ganzen Reiche Tage der Steuerfreiheit und des Erlasses sein,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 10, 35, 'und niemand soll das Recht haben, einen von ihnen wegen irgend eines Rechtshandels zu belangen oder zu belästigen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 10, 36, 'Ferner sollen von den Juden 30000 Mann ausgehoben und dem Heere des Königs einverleibt werden, für deren Unterhalt gesorgt werden wird, wie dies allen Truppen des Königs zukommt.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 10, 37, 'Von diesen sollen dann Abteilungen in die großen Festungen des Königs verlegt werden, und aus diesen sollen Zugehörige in die Vertrauensämter des Reiches eingesetzt werden; ihre Vorgesetzten und Anführer aber sollen aus ihrer eigenen Mitte genommen werden und sollen nach ihren eigenen Satzungen und Bräuchen leben dürfen, wie der König es für das jüdische Land angeordnet hat.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 10, 38, 'Und die drei von der Landschaft Samarien zu Judäa geschlagenen Bezirke sollen so zu Judäa geschlagen sein, daß sie als unter der nämlichen Verwaltung stehend zu gelten haben und keiner anderen Gewalt untertan sind als der des Hohenpriesters.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 10, 39, 'Ptolemais und das zugehörige Gebiet schenke ich hiermit dem Heiligtum in Jerusalem zur Bestreitung der Kosten des Gottesdienstes;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 10, 40, 'ich selbst aber will jährlich 15000 Silberschekel beisteuern aus den königlichen Einkünften von den dazu geeigneten Orten.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 10, 41, 'Und alles übrige, was die Steuerbeamten noch nicht ausbezahlt haben, wie das in den früheren Jahren der Fall war, sollen sie von nun an für den Tempeldienst zahlen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 10, 42, 'Außerdem sollen die 5000 Silberschekel, die man bisher von den Einkünften des Tempels, von dem Betrage, jährlich erhoben hat, – auch diese sollen in Wegfall kommen, weil sie den diensttuenden Priestern gebühren.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 10, 43, 'Und alle, die in den Tempel zu Jerusalem oder in dessen ganzen Bereich fliehen, weil sie dem Könige gegenüber oder sonst in irgend einer Hinsicht Geldschulden haben, die sollen mit allem, was ihnen in meinem Reiche gehört, von der Schuld befreit sein.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 10, 44, 'Und für den Bau und die Wiederherstellung der Bauwerke des Heiligtums sollen die Kosten aus den königlichen Einkünften bestritten werden.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 10, 45, 'Ebenso sollen für den Bau der Mauern Jerusalems und für seine Befestigung ringsum die Kosten aus den königlichen Einkünften bestritten werden, wie auch für den Bau der übrigen Festungen Judäas«.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 10, 46, 'Als nun Jonathan und das Volk diese Zusagen vernahmen, schenkten sie ihnen keinen Glauben und nahmen sie nicht an; denn sie gedachten der argen Bosheit, die der König an Israel verübt und mit der er sie schwer heimgesucht hatte.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 10, 47, 'Sie zogen es vielmehr vor, sich an Alexander anzuschließen, weil dieser ihnen zuerst mit freundschaftlichen Worten entgegengekommen war; und sie blieben seine Bundesgenossen, solange er regierte.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 10, 48, 'Nun sammelte der König Alexander ein gewaltiges Heer und zog gegen Demetrius zu Felde.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 10, 49, 'Als es dann zwischen den beiden Königen zur Schlacht kam, wurde das Heer des Demetrius in die Flucht geschlagen, und Alexander verfolgte ihn und errang einen entscheidenden Sieg,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 10, 50, 'den er erfolgreich bis Sonnenuntergang ausnutzte; Demetrius aber fand an diesem Tage seinen Tod.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 10, 51, 'Hierauf schickte Alexander eine Gesandtschaft an Ptolemäus, den König von Ägypten, mit folgender Botschaft:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 10, 52, '»Ich bin in mein Reich zurückgekehrt, habe den Thron meiner Väter bestiegen und die Herrschaft angetreten; ich habe den Demetrius besiegt und unser Land in Besitz genommen');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 10, 53, 'und zwar ist er mit seinem Heere in einer Schlacht, die ich ihm lieferte, von uns besiegt worden, und so haben wir seinen königlichen Thron bestiegen –:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 10, 54, 'so wollen wir nun Freundschaft miteinander schließen. Gib mir jetzt deine Tochter zur Gemahlin und laß mich dein Schwiegersohn werden; ich will alsdann dir und ihr Geschenke geben, die deiner würdig sind«.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 10, 55, 'Hierauf antwortete der König Ptolemäus also: »Das war ein Glückstag, an dem du in das Land deiner Väter heimgekehrt bist und ihren Königsthron bestiegen hast!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 10, 56, 'So will ich nun auf das eingehen, was du in deinem Briefe vorschlägst. Komm mir also nach Ptolemais entgegen, damit wir zusammentreffen und ich mich mit dir verschwägere, wie du es wünschest«.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 10, 57, 'Ptolemäus verließ also Ägypten mit seiner Tochter Kleopatra und kam nach Ptolemais im Jahre 162.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 10, 58, 'Der König Alexander traf mit ihm zusammen, gab ihm seine Tochter Kleopatra zur Gemahlin und richtete ihre Hochzeit in Ptolemais mit großer Pracht aus, wie das bei Königen gewöhnlich der Fall ist.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 10, 59, 'Der König Alexander aber hatte an Jonathan geschrieben und ihn zu sich eingeladen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 10, 60, 'So zog dieser denn in glänzendem Aufzuge nach Ptolemais und traf dort mit den beiden Königen zusammen. Er gab ihnen und ihren Vertrauten Silber und Gold und viele Geschenke und gewann ihre Gunst.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 10, 61, 'Es taten sich zwar nichtswürdige Männer aus Israel, abtrünnige Menschen, gegen ihn zusammen, um Anklagen gegen ihn zu erheben; aber der König ließ sie unbeachtet;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 10, 62, 'er befahl sogar, dem Jonathan seine Gewänder abzunehmen und ihm ein Purpurgewand anzulegen, was dann auch geschah.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 10, 63, 'Hierauf ließ der König ihn neben sich Platz nehmen und gebot seinen obersten Beamten, mit ihm mitten in die Stadt zu gehen und laut bekannt zu machen, daß niemand wegen irgend einer Ursache eine Klage wider ihn vorbringen und niemand ihn aus irgend einem Grunde belästigen dürfe.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 10, 64, 'Als nun die, welche gegen ihn vorgehen wollten, die hohe Ehre sahen, die man ihm mit dieser öffentlichen Verkündung antat, und man ihn in Purpur gekleidet hatte, da ergriffen sie alle die Flucht.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 10, 65, 'Der König aber überhäufte ihn mit Ehren, ließ ihn in das Verzeichnis seiner ersten Freunde eintragen und ernannte ihn zum General und Mitfürsten.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 10, 66, 'So kehrte denn Jonathan wohlbehalten und hochbefriedigt nach Jerusalem zurück.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 10, 67, 'Im Jahre 165 aber kam Demetrius, der Sohn des Demetrius, aus Kreta in das Land seiner Väter.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 10, 68, 'Als der König Alexander dies erfuhr, erschrak er sehr und kehrte nach Antiochien zurück.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 10, 69, 'Demetrius ernannte nun den Apollonius, den Statthalter von Cölesyrien, zu seinem Heerführer; dieser brachte ein großes Heer zusammen und bezog ein Lager bei Jamnia; alsdann sandte er an den Hohenpriester Jonathan folgende Botschaft:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 10, 70, '»Du ganz allein lehnst dich wider uns auf, und ich bin durch deine Schuld zum Gelächter und zum Spott geworden! Und mit welchem Recht maßest du dir Gewalt im Berglande an?');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 10, 71, 'Nun wohlan, wenn du dich auf deine Streitkräfte verläßt, so komm zu uns in die Ebene herab, damit wir uns dort miteinander messen; denn auf meiner Seite steht die Macht der Städte.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 10, 72, 'Erkundige dich nur, so wirst du erfahren, wer ich bin und wer die anderen sind, meine Verbündeten; man wird dir schon sagen, daß es für euch unmöglich ist, vor uns standzuhalten; denn zweimal sind deine Väter in ihrem eigenen Lande von uns geschlagen worden.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 10, 73, 'So wirst du jetzt auch nicht imstande sein, es mit der Reiterei und einer so großen Heeresmacht in der Ebene aufzunehmen, wo es keinen Stein und keinen Felsen, überhaupt keinen Zufluchtsort gibt«.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 10, 74, 'Als Jonathan diese Botschaft des Apollonius vernahm, wurde er in tiefster Seele entrüstet; er sammelte 10000 Mann auserlesener Truppen und zog aus Jerusalem ab; sein Bruder Simon stieß dann noch zu ihm, um ihm Hilfe zu leisten.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 10, 75, 'Er lagerte sich vor Joppe, dessen Einwohner aber die Tore vor ihm schlossen, weil eine Besatzung des Apollonius in der Stadt lag. Als man dann aber die Stadt bestürmte,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 10, 76, 'gerieten die Stadtbewohner in Angst und öffneten die Tore, so daß Jonathan Joppe in seine Gewalt brachte.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 10, 77, 'Als Apollonius das vernahm, ließ er 3000 Reiter und eine starke Mannschaft von Fußvolk ins Feld rücken und marschierte auf Asotus, als wollte er dorthin ziehen, rückte aber gleichzeitig in die Ebene vor, weil er eine zahlreiche Reiterei besaß, auf die er sein Vertrauen gesetzt hatte.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 10, 78, 'Jonathan aber zog hinter ihm her auf Asotus zu, und so gerieten die beiden Heere in Kampf miteinander.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 10, 79, 'Apollonius hatte nun zwar 1000 Reiter hinter ihrem Rücken in einen Hinterhalt gelegt,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 10, 80, 'Jonathan aber hatte erfahren, daß ein Hinterhalt hinter ihm liege. Als die Feinde daher sein Heer umzingelten und seine Leute vom Morgen bis zum Spätnachmittage mit Pfeilen beschossen,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 10, 81, 'hielt seine Mannschaft unerschütterlich stand, wie Jonathan ihnen befohlen hatte, während die Reiterei der Feinde zuletzt ermattete.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 10, 82, 'Jetzt zog Simon seine Abteilung heran und griff das schwere Fußvolk an – die Reiterei war ja abgemattet –; da wurden sie von ihm geschlagen und wandten sich zur Flucht;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 10, 83, 'auch die Reiterei zerstreute sich in der Ebene; die Flüchtlinge aber warfen sich in die Stadt Asotus und begaben sich in den dortigen Götzentempel Dagons, um sich zu retten.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 10, 84, 'Jonathan aber ließ die Stadt Asotus und die umliegenden Ortschaften in Flammen aufgehen, nachdem er sie hatte plündern lassen; auch den Dagontempel verbrannte er mit allen, die sich in ihn geflüchtet hatten.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 10, 85, 'Es belief sich aber die Zahl der durchs Schwert Gefallenen und der Verbrannten auf etwa 8000 Mann.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 10, 86, 'Von dort zog Jonathan weiter und lagerte sich vor Askalon; da kamen die Bewohner der Stadt zu ihm hinaus mit großen Ehrenbezeigungen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 10, 87, 'Hierauf kehrte Jonathan mit seinen beutebeladenen Truppen nach Jerusalem zurück.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 10, 88, 'Als aber der König Alexander Kunde von allen diesen Begebenheiten erhielt, erwies er dem Jonathan noch größere Ehren.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 10, 89, 'Er übersandte ihm eine goldene Spange, wie sie den Verwandten der Könige gegeben zu werden pflegt, und verlieh ihm das ganze Gebiet von Akkaron als persönliches Eigentum.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 1, 'Der König von Ägypten aber brachte Truppenmassen zusammen so zahllos wie der Sand an der Meeresküste und viele Schiffe, in der Absicht, sich mit List des Reiches Alexanders zu bemächtigen und es zu seinem Reiche hinzuzufügen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 2, 'Er zog also in Syrien mit friedlichen Versicherungen ein, und die Einwohner der Städte öffneten ihm die Tore und kamen ihm mit Ehrenerweisungen entgegen, weil ein Befehl des Königs Alexander vorlag, man solle ihn ehrenvoll empfangen, weil er sein Schwiegervater war.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 3, 'Wenn aber Ptolemäus in die Städte eingezogen war, legte er sofort seine Truppen als Besatzung in jede Stadt.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 4, 'Als er nun in die Nähe von Asotus gekommen war, zeigte man ihm den verbrannten Dagontempel, sowie das in Trümmern liegende Asotus und die verwüsteten Orte der Umgegend, auch die umherliegenden Leichen und die Verbrannten, welche während des Kampfes durch Feuer umgekommen waren; denn man hatte sie in Haufen an seinem Wege aufgeschichtet.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 5, 'Auch berichteten sie dem Könige, was Jonathan getan habe; sie wollten ihn nämlich anschwärzen; doch der König schwieg dazu.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 6, 'Jonathan aber ging dem Könige nach Joppe entgegen mit Ehrenbezeigungen; sie begrüßten einander und blieben dort über Nacht.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 7, 'Sodann begleitete Jonathan den König bis an den Fluß Eleutherus und kehrte dann nach Jerusalem zurück.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 8, 'So bemächtige sich also der König Ptolemäus der Städte des Küstenlandes bis zu der Seestadt Seleucia und führte böse Pläne gegen Alexander im Schilde.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 9, 'Er schickte nämlich Gesandte an den König Demetrius und ließ ihm sagen: »Komm, wir wollen einen Bund miteinander schließen! Ich will dir meine Tochter, die Gemahlin Alexanders, zur Frau geben, und du sollst Herr deines väterlichen Reiches werden;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 10, 'denn es reut mich, daß ich ihm meine Tochter gegeben habe, weil er mir nach dem Leben getrachtet hat«.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 11, 'So verleumdete er ihn, weil ihn nach seinem Reiche gelüstete.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 12, 'Er nahm ihm auch wirklich seine Tochter und gab sie dem Demetrius; er brach mit Alexander, so daß ihre Feindschaft offen zu Tage trat.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 13, 'Ptolemäus zog nun in Antiochien ein und setzte sich die Krone von Asien aufs Haupt; er trug also zwei Kronen auf dem Haupte, die von Ägypten und die von Asien.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 14, 'Der König Alexander befand sich während dieser Zeit in Cilicien, weil die dortige Bevölkerung sich gegen ihn empört hatte.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 15, 'Als er nun Kunde von dem Vorgefallenen erhielt, zog er zum Kampfe gegen Ptolemäus ins Feld; dieser aber ging ihm mit überlegener Heeresmacht entgegen und schlug ihn in die Flucht.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 16, 'Alexander floh nun nach Arabien, um sich dort in Sicherheit zu bringen. Da aber der König Ptolemäus die Oberhand behalten hatte,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 17, 'ließ der Araber Sabdiel dem Alexander den Kopf abschlagen und schickte ihn dem Ptolemais zu.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 18, 'Aber auch der König Ptolemäus starb schon drei Tage nachher, und seine Besatzungen, die in den Festungen lagen, wurden von der Einwohnerschaft der Festungen niedergemacht;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 19, 'Demetrius aber wurde dann König im Jahre 167.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 20, 'Zu jener Zeit zog Jonathan seine Mannschaften aus Judäa zusammen, um sich der Burg in Jerusalem mit Gewalt zu bemächtigen, und stellte viele Belagerungsmaschinen gegen sie auf.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 21, 'Da machten sich einige abtrünnige Männer, die ihr Volk haßten, auf den Weg zum Könige Demetrius und meldeten ihm, daß Jonathan die Burg belagere.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 22, 'Als der König das vernahm, geriet er in Zorn; er brach sofort auf und begab sich nach Ptolemais, von wo er dem Jonathan schriftlich befahl, die Belagerung aufzugeben und sich unverzüglich zu ihm nach Ptolemäus zum Zweck einer Besprechung zu verfügen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 23, 'Als Jonathan diesen Befehl erhalten hatte, gebot er, die Belagerung fortzusetzen, erwählte dann aber einige von den vornehmsten Israeliten und von den Priestern zu Begleitern und trat die lebensgefährliche Reise an.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 24, 'Er nahm Silber, Gold, Prachtgewänder und andere Geschenke in großer Zahl mit sich, reiste zum Könige nach Ptolemais und gewann dort seine Gunst.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 25, 'Zwar traten einige Abtrünnige aus dem jüdischen Volke als Ankläger gegen ihn auf,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 26, 'aber der König behandelte ihn geradeso, wie seine Vorgänger getan hatten, und erhob ihn zu hohen Ehren in Gegenwart aller seiner Vertrauten.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 27, 'Er bestätigte ihm das Hohepriestertum und alle sonstigen Ehrenämter, die er bis dahin innegehabt hatte, und ließ ihn in die Zahl seiner ersten Vertrauten aufnehmen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 28, 'Jonathan bat nun den König, Judäa und die drei samaritischen Bezirke steuerfrei zu machen, und versprach ihm dafür die Zahlung von 300 Talenten.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 29, 'Der König willigte ein und ließ dem Jonathan über alle diese Angelegenheiten eine Urkunde ausfertigen, die folgenden Wortlaut hatte:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 30, '»König Demetrius entbietet seinem Bruder Jonathan und dem jüdischen Volke seinen Gruß.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 31, 'Wir lassen euch anbei eine Abschrift des Briefes zugehen, den wir euretwegen an unsern Vetter Lasthenes geschrieben haben, damit ihr davon Kenntnis nehmt.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 32, 'König Demetrius entbietet dem Vater Lasthenes seinen Gruß.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 33, 'Wir haben beschlossen, unseren Freunden und getreuen Bundesgenossen, dem Volke der Juden, Gutes zu erweisen zum Dank für ihre gute Gesinnung gegen uns.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 34, 'Wir überweisen ihnen also hiermit das Gebiet von Judäa und die drei Bezirke Apherema, Lydda und Ramathaim, die von Samarien abgetrennt und zu Judäa geschlagen sind, samt allem, was zu ihnen gehört. ... Allen, die in Jerusalem opfern, (erlassen wir) den Betrag der königlichen Gefälle, die der König früher alljährlich von ihnen eingezogen hat, (und zwar) von den Erzeugnissen des Bodens und der Fruchtbäume.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 35, 'Ebenso erlassen wir ihnen von jetzt ab unsere übrigen Gerechtsame, nämlich die Zehnten und Zölle, die uns zustehen, sowie die Salzlachen und die uns zustehenden Kronengelder: alles wollen wir ihnen erlassen,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 36, 'und es soll nichts von alledem widerrufen werden von jetzt an für ewige Zeiten.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 37, 'Tragt also Sorge dafür, eine Abschrift hiervon anfertigen zu lassen, die dem Jonathan zugestellt werden soll, damit sie auf dem heiligen Berge an einer geeigneten Stelle öffentlich ausgestellt werde«.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 38, 'Als nun der König Demetrius sah, daß in seinem Lande volle Ruhe herrschte und daß niemand ihm mehr Widerstand leistete, entließ er alle seine Truppen, einen jeden in seine Heimat, mit Ausnahme der fremden Truppen, die er von den Inseln der Heiden in Sold genommen hatte; infolgedessen wurden ihm alle (einheimischen) Truppen, die schon unter seinen Vätern gedient hatten, feindlich gesinnt.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 39, 'Da war nun ein gewisser Tryphon, der früher zu der Partei Alexanders gehört hatte. Als der wahrnahm, daß alle Truppen gegen Demetrius murrten, begab er sich zu dem Araber Jamliku, der Antiochus, den kleinen Sohn Alexanders, zu erziehen hatte;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 40, 'er machte diesem eindringliche Vorstellungen, daß er ihm den Knaben übergeben solle, damit dieser als König an die Stelle seines Vaters trete. Zugleich teilte er ihm alles mit, was Demetrius verübt hatte, und wie verhaßt er sich bei seinen Truppen gemacht habe; er verweilte dort längere Zeit.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 41, 'Nun schickte Jonathan Gesandte an den König Demetrius, um ihn zu veranlassen, die Besatzung aus der Burg in Jerusalem und die Truppen aus den anderen festen Plätzen zurückzuziehen, weil sie beständig Feindseligkeiten gegen Israel verübten.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 42, 'Darauf ließ Demetrius dem Jonathan folgende Botschaft zugehen: »Nicht nur dieses will ich dir und deinem Volke gewähren, sondern ich will dich und dein Volk auch sonst noch hoch ehren, wenn die Umstände es mir gestatten.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 43, 'Jetzt aber wirst du mich zu Dank verpflichten, wenn du mir ein Hilfskorps sendest, weil alle meine eigenen Truppen von mir abgefallen sind«.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 44, 'Da sandte Jonathan ihm (sofort) 3000 Mann Kerntruppen nach Antiochien, über deren Zuzug der König hocherfreut war.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 45, 'Nun rotteten sich aber die Bewohner der Stadt mitten in der Stadt zusammen, wohl 120000 Menschen, und wollten den König ermorden.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 46, 'Dieser flüchtete sich in den Palast; aber die Städter besetzten die Straßen der Stadt und fingen an zu stürmen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 47, 'Da rief der König die Juden zu Hilfe, und diese scharten sich allesamt um ihn und machten, nachdem die Empörer sich in der Stadt zerstreut hatten, an diesem Tage gegen 100000 von ihnen nieder.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 48, 'Dann steckten sie die Stadt in Brand, wobei sie auch reiche Beute machten; den König aber hatten sie an jenem Tage gerettet.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 49, 'Denn als die Bewohner der Stadt sahen, daß die Juden die unbeschränkte Herrschaft in der Stadt hatten, verloren sie den Mut und schrieen flehentlich zum Könige:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 50, '»Gewähre uns Frieden, damit die Juden aufhören, uns und die Stadt als Feinde zu behandeln!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 51, 'Sie warfen also die Waffen weg und schlossen Frieden; die Juden aber galten nun viel beim Könige und bei allen Bewohnern seines Reiches; mit Beute reich beladen, kehrten sie nach Jerusalem zurück.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 52, 'Als der König Demetrius jetzt aber wieder fest auf seinem Throne saß und sein Land ruhig zu seinen Füßen lag,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 53, 'da hielt er nichts von allen Versprechungen, die er gemacht hatte; er wurde vielmehr dem Jonathan feind, und statt ihm die Beweise freundschaftlicher Gesinnung, die er ihm gegeben hatte, zu vergelten, bedrückte er ihn hart.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 54, 'Hierauf kehrte Tryphon mit Antiochus, der noch ein ganz junger Knabe war, zurück, und dieser wurde zum König ausgerufen und setzte sich die Krone aufs Haupt.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 55, 'Da sammelten sich alle die Truppen, die Demetrius entlassen hatte, um ihn und eröffneten den Krieg gegen Demetrius, der dann auch geschlagen wurde und die Flucht ergreifen mußte.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 56, 'Tryphon aber bekam die Elefanten in seine Gewalt und bemächtigte sich Antiochiens.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 57, 'An Jonathan aber ließ der junge Antiochus schriftlich folgende Botschaft ergehen: »Ich bestätige dir das Hohepriestertum und mache dich zum Herrn über die vier Bezirke und nehme dich unter die Zahl der Vertrauten des Königs auf«.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 58, 'Zugleich übersandte er ihm goldene Tafelgeräte und erlaubte ihm, aus goldenen Bechern zu trinken, sich in Purpur zu kleiden und eine goldene Spange zu tragen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 59, 'Seinen Bruder Simon aber bestellte er zum obersten Heerführer für das Gebiet von der Tyrischen Leiter bis zur ägyptischen Grenze.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 60, 'Da machte Jonathan sich auf und durchzog das Land und die Städte diesseits des Euphratstroms, wo alle syrischen Streitkräfte als Hilfstruppen zu ihm stießen. Als er dann vor Askalon ankam, zogen ihm die Bewohner der Stadt mit großen Ehrenbezeigungen entgegen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 61, 'Von dort marschierte er nach Gaza, dessen Bewohner ihm jedoch die Tore verschlossen. Da belagerte er die Stadt, verbrannte und plünderte die Ortschaften der Umgebung.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 62, 'Nun baten die Bewohner von Gaza um Frieden, den Jonathan ihnen auch gewährte; er ließ sich die Söhne ihrer Vornehmsten als Geiseln geben und schickte sie nach Jerusalem; dann durchzog er das Land bis Damaskus.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 63, 'Als aber Jonathan dort vernahm, daß die Heerführer des Demetrius mit großer Heeresmacht zu Kedes in Galiläa ständen, um seinem ganzen Unternehmen ein Ende zu machen,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 64, 'zog er zum Kampfe gegen sie; seinen Bruder Simon aber hatte er im Lande (Judäa) zurückgelassen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 65, 'Dieser belagerte nun Bethsura mit seinen Truppen, bestürmte es längere Zeit und hielt es eingeschlossen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 66, 'Da baten die Belagerten ihn um ein friedliches Abkommen, das er ihnen auch bewilligte; er ließ sie von dort abziehen, nahm dann die Stadt in Besitz und legte eine Besatzung hinein.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 67, 'Jonathan aber lagerte sich mit seinem Heere am See Gennesar und machte sich früh am Morgen auf nach der Ebene von Asor.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 68, 'Da kam ihnen plötzlich ein Heer von Heiden in der Ebene entgegen, während sie zugleich einen Hinterhalt gegen ihn ins Gebirge gelegt hatten; sie selbst aber zogen ihm geradeswegs entgegen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 69, 'Als nun die Mannschaften des Hinterhalts plötzlich aus ihrem Versteck hervorbrachen und einen Angriff machten, ergriffen die Leute Jonathans allesamt die Flucht,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 70, 'nicht ein einziger von ihnen hielt stand außer Mattathias, dem Sohne Absaloms, und Judas, dem Sohne Chalphi’s, zwei Hauptleuten.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 71, 'Da zerriß Jonathan seine Kleider, streute Erde auf sein Haupt und betete;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 72, 'sodann wandte er sich zum Kampfe gegen sie und schlug sie, so daß sie flohen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 73, 'Als das die Leute sahen, die von ihm geflohen waren, kehrten sie zu ihm zurück und verfolgten die Fliehenden gemeinsam mit ihm bis Kedes bis vor deren Lager, wo sie Halt machten.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 74, 'Es waren aber an diesem Tage von den Heiden gegen 3000 Mann gefallen. Jonathan kehrte hierauf nach Jerusalem zurück.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 12, 1, 'Da Jonathan nun sah, daß die damaligen Verhältnisse ihm günstig waren, erwählte er Männer und sandte sie nach Rom, um den Freundschaftsbund mit ihnen zu befestigen und zu erneuern.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 12, 2, 'Auch an die Spartaner und an andere Orte sandte er Briefe gleichen Inhalts.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 12, 3, 'In Rom angekommen, traten jene vor die Ratsversammlung und sagten: »Der Hohepriester Jonathan und das Volk der Juden haben uns hergesandt, um den Freundschaftsbund mit ihnen und die Bundesgenossenschaft unter den früheren Bedingungen zu erneuern«.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 12, 4, 'Da gab man ihnen Briefe an die Behörden allerorten, daß man ihnen sicheres Geleit gäbe zur Rückkehr nach Judäa.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 12, 5, 'Und dies ist die Abschrift des Schreibens, das Jonathan an die Spartaner gerichtet hatte:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 12, 6, '»Jonathan, der Hohepriester des Volkes, und die Ältestenschaft nebst den Priestern und dem übrigen Volk der Juden entbieten ihren Brüdern, den Spartanern, ihren Gruß.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 12, 7, 'Schon früher ist ein Schreiben von eurem Könige Arius an den Hohenpriester Onias gesandt worden, welches besagt, daß ihr unsere Brüder seid; eine Abschrift davon liegt hier bei.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 12, 8, 'Onias hat damals den von euch abgesandten Mann ehrenvoll empfangen und den Brief entgegengenommen, in welchem ausdrücklich von einer Bundesgenossenschaft und Freundschaft die Rede war.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 12, 9, 'Wir nun – obschon wir auf diese Bündnisse nicht unbedingt angewiesen sind, da wir an den heiligen Schriften, die wir in Händen haben, einen Trost besitzen –,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 12, 10, 'haben es dennoch unternommen, eine Gesandtschaft an euch zu schicken, um die Verbrüderung und Freundschaft mit euch zu erneuern, damit wir euch nicht entfremdet werden; denn seit jener eurer Botschaft an uns ist eine lange Zeit verstrichen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 12, 11, 'Was nun uns betrifft, so halten wir zu jeder Zeit unablässig bei Gelegenheit unserer Feste und der übrigen geeigneten Tage, bei den Opfern, die wir darbringen, und in unseren Gebeten die Erinnerungen an euch fest, wie es denn recht und geziemend ist, der Brüder zu gedenken.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 12, 12, 'Wir freuen uns aber eures Ruhmes.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 12, 13, 'Uns freilich haben viele Trübsale und viele Kriege von allen Seiten her betroffen, da alle Könige rings um uns her uns angegriffen haben.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 12, 14, 'Wir haben jedoch um dieser Kriege willen weder euch noch unseren übrigen Bundesgenossen und Freunden beschwerlich fallen wollen;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 12, 15, 'denn wir erfreuen uns der Hilfe, die vom Himmel her sich für uns betätigt, so daß wir von unseren Feinden errettet und diese gedemütigt worden sind.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 12, 16, 'Nunmehr aber haben wir Numenius, den Sohn des Antiochus, und Antipater, den Sohn Jasons, erwählt und sie zu den Römern gesandt, um die frühere Freundschaft und Bundesgenossenschaft mit ihnen zu erneuern.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 12, 17, 'Zugleich haben wir sie beauftragt, sich auch zu euch zu begeben, euch zu begrüßen und euch unser Schreiben an euch in betreff der Erneuerung unserer Brüderschaft zu überreichen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 12, 18, 'Und nun werdet ihr uns zu Dank verpflichten, wenn ihr uns eine Antwort darauf erteilt«.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 12, 19, 'Folgendes ist die Abschrift des Briefes, den die Spartaner (einstmals) an Onias gerichtet hatten:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 12, 20, '»Arius, der König der Spartaner, entbietet dem Hohenpriester Onias seinen Gruß.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 12, 21, 'Es hat sich in einer die Spartaner und Juden betreffenden Urkunde die Angabe gefunden, daß sie Brüder sind und von Abraham abstammen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 12, 22, 'Da wir dieses nun erfahren haben, werdet ihr uns zu Dank verpflichten, wenn ihr uns berichtet, wie es euch ergeht;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 12, 23, 'wir aber werden euch wieder schreiben. Euer Vieh und eure Habe gehört uns, und unser Besitz gehört euch. So beauftragen wir also (die Sendboten), euch demgemäß zu berichten«.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 12, 24, 'Als nun Jonathan erfahren hatte, daß die Heerführer des Demetrius zum Kampfe gegen ihn mit einer noch weit größeren Kriegsmacht als vorher herangezogen kämen,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 12, 25, 'brach er von Jerusalem auf und zog ihnen entgegen ins Gebiet von Hamath, weil er ihnen nicht Zeit lassen wollte, in sein eigenes Land einzurücken.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 12, 26, 'Er schickte dann Kundschafter in ihr Lager, die ihm bei ihrer Rückkehr meldeten, daß jene sich dazu anschickten, ihn in der Nacht zu überfallen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 12, 27, 'Bei Sonnenuntergang befahl nun Jonathan seinen Leuten, wach und unter den Waffen zu bleiben und die ganze Nacht hindurch kampfbereit zu sein. Zugleich stellte er Wachtposten um das ganze Lager auf.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 12, 28, 'Als nun die Feinde hörten, daß Jonathan und seine Leute kampfbereit seien, gerieten sie in Furcht und wurden mutlos; sie zündeten also Wachtfeuer in ihrem Lager an und zogen ab.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 12, 29, 'Jonathan und seine Leute merkten bis zum Morgen nichts davon, weil sie die Wachtfeuer brennen sahen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 12, 30, 'Jonathan unternahm dann zwar ihre Verfolgung, konnte sie aber nicht mehr einholen; denn sie hatten bereits den Fluß Eleutherus überschritten.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 12, 31, 'Jonathan wandte sich darauf gegen den arabischen Stamm der Zabadäer, die er schlug und denen er Beute abnahm.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 12, 32, 'Sodann brach er wieder auf, kam nach Damaskus und durchzog die ganze Landschaft.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 12, 33, 'Auch Simon war ins Feld gerückt und hatte das Land bis nach Askalon und den benachbarten festen Plätzen durchzogen; dann wandte er sich gegen Joppe und bemächtigte sich der Stadt in aller Eile;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 12, 34, 'denn er hatte vernommen, daß man beabsichtigte, die Festung den Anhängern des Demetrius zu übergeben. Er legte daher eine Besatzung hinein, um ihren Besitz zu sichern.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 12, 35, 'Nach seiner Rückkehr aber berief Jonathan die Ältesten des Volkes zu einer Versammlung und beschloß mit ihnen die Erbauung von Festungen in Judäa');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 12, 36, 'und die Erhöhung der Mauern Jerusalems und die Aufführung einer hohen Mauer zwischen der Burg und der Stadt, um die Burg von der Stadt zu trennen, damit sie ganz abgesperrt würde, so daß kein Kaufen und Verkaufen mehr stattfinden könnte.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 12, 37, 'So versammelte man sich denn zur Ausführung der Bauten in der Stadt; ein Teil der Mauer am Kidronbache auf der Ostseite war eingestürzt; und man stellte auch das sogenannte Chaphenata wieder her.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 12, 38, 'Simon aber befestigte Adida in der Niederung und versah es mit starken Toren und Riegeln.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 12, 39, 'Tryphon aber trachtete danach, sich zum Könige von Asien zu machen und sich die Krone aufs Haupt zu setzen, nachdem er sich des (jungen) Königs Antiochus entledigt hätte.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 12, 40, 'Da er aber zu fürchten hatte, Jonathan würde ihm dazu nicht freie Hand lasen und könnte ihn angreifen, so suchte er Mittel und Wege, sich seiner Person zu bemächtigen und ihn ums Leben zu bringen. So brach er denn auf und zog nach Bethsan.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 12, 41, 'Jonathan aber zog ihm entgegen mit 40000 für den Kampf auserlesenen Kriegern und kam auch nach Bethsan.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 12, 42, 'Als nun Tryphon sah, daß er mit einer großen Heeresmacht an Ort und Stelle sei, wagte er es nicht, Hand an ihn zu legen;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 12, 43, 'er empfing ihn vielmehr mit Ehren, empfahl ihn allen seinen Freunden, gab ihm Geschenke und befahl seinen Truppen, ihm ebenso zu gehorchen wie ihm selbst.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 12, 44, 'Weiter sagte er zu Jonathan: »Warum hast du alle diese Krieger bemüht, da doch gar kein Krieg zwischen uns besteht?');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 12, 45, 'Entlaß sie nun doch in ihre Heimat; wähle dir eine kleine Zahl zu deiner Begleitung aus und komm mit mir nach Ptolemais; ich will dir dann die Stadt nebst den übrigen Festungen und den Streitkräften, die dort noch stehen, und alle Beamten überweisen und mich dann auf den Rückweg begeben; denn nur zu diesem Zweck bin ich hergekommen«.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 12, 46, 'Jonathan schenkte ihm Glauben und folgte seiner Aufforderung: er entließ seine Truppen, die ins Land Juda heimkehrten.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 12, 47, 'Nur 3000 Mann behielt er bei sich, von denen er noch 2000 in Galiläa zurückließ; nur 1000 begleiteten ihn.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 12, 48, 'Als aber Jonathan in Ptolemais eingezogen war, schlossen die Bewohner der Stadt die Tore, bemächtigten sich seiner Person und machten alle, die mit ihm in die Stadt gekommen waren, mit dem Schwerte nieder.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 12, 49, 'Hierauf entsandte Tryphon Fußtruppen und Reiterei nach Galiläa und in die große Ebene Jesreel, um alle Mannschaften, die Jonathan dort zurückgelassen hatte, zu vernichten.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 12, 50, 'Diese hatten jedoch Kunde von der Gefangennahme und Ermordung Jonathans und der ihn begleitenden Mannschaft erhalten; sie sprachen daher einander Mut zu und marschierten in fester Kriegsordnung kampfbereit einher.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 12, 51, 'Als nun die zu ihrer Verfolgung Ausgesandten erkannten, daß ihnen ein Kampf auf Leben und Tod bevorstehe, machten sie Kehrt.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 12, 52, 'So gelangten jene allesamt glücklich ins jüdische Land und betrauerten Jonathan und seine Begleiter und waren voller Besorgnis, auch ganz Israel stellte eine große Totenklage an.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 12, 53, 'Alle Heiden aber ringsum gingen darauf aus, sie völlig zu vernichten; sie dachten nämlich:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 12, 54, '»Sie haben keinen Führer mehr und nirgends einen Helfer! Wir wollen sie also jetzt angreifen und ihr Gedächtnis unter den Menschen austilgen!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 13, 1, 'Als nun Simon erfuhr, daß Tryphon eine große Streitmacht zusammenziehe, um ins jüdische Land einzufallen und es völlig zu vernichten,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 13, 2, 'und wahrnahm, daß das Volk vor Angst zitterte und zagte, ging er nach Jerusalem hinauf, berief das Volk zu einer Versammlung');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 13, 3, 'und richtete folgende ermutigende Ansprache an sie: »Ihr wißt selbst alles, was ich und meine Brüder und mein ganzes väterliches Haus für unsere Gesetze und das Heiligtum getan und welche Kriege und Drangsale wir durchgemacht haben.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 13, 4, 'Darum sind alle meine Brüder für Israel umgekommen; ich allein bin noch übrig geblieben.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 13, 5, 'Nun aber denke ich gar nicht daran, mein Leben in irgend einer Zeit der Leiden zu schonen; denn ich bin nicht besser als meine Brüder.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 13, 6, 'Nein, Rache will ich für mein Volk und das Heiligtum und für unsere Weiber und Kinder nehmen, weil sich alle Heiden, von Haß getrieben, zu unserer Vernichtung zusammengerottet haben«.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 13, 7, 'Als das Volk diese Worte vernahm, lebte der Mut in ihnen wieder auf,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 13, 8, 'und sie riefen ihm laut die Worte zu: »Du sollst unser Führer an Stelle deiner Brüder Judas und Jonathan sein!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 13, 9, 'Führe du uns im Kriege an! Alles, was du befiehlst, wollen wir tun!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 13, 10, 'Drauf hob er alle waffenfähigen Männer aus, beschleunigte die Vollendung des Mauerbaues in Jerusalem und befestigte die Stadt ringsum.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 13, 11, 'Außerdem schickte er Jonathan, den Sohn Absaloms, mit genügender Mannschaft nach Joppe; der zwang die Einwohner der Stadt zur Auswanderung und hielt die Stadt dauernd besetzt.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 13, 12, 'Tryphon aber brach dann mit einem großen Heere von Ptolemais auf, um in Judäa einzufallen, und führte dabei Jonathan gefangen mit sich.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 13, 13, 'Simon aber bezog ein Lager bei Adida angesichts der Ebene.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 13, 14, 'Als nun Tryphon erfuhr, daß Simon an die Stelle seines Bruders Jonathan getreten sei und den Kampf mit ihm aufnehmen wolle, schickte er Gesandte an ihn und ließ ihm sagen:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 13, 15, '»Wegen des Geldes, das dein Bruder Jonathan dem königlichen Schatze für die Ämter, die er bekleidete, schuldig geblieben ist, halten wir ihn gefangen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 13, 16, 'So schicke mir also 100 Talente Silbers und zwei von seinen Söhnen als Geiseln, damit er nicht nach erlangter Freiheit von uns abfalle, – so wollen wir ihn freilassen«.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 13, 17, 'Simon erkannte nun wohl, daß jene Lug und Trug zu ihm redeten, sandte aber doch das Geld und die Knaben hin, um sich nicht die bittere Feindschaft des Volkes zuzuziehen,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 13, 18, 'wenn man sagen könnte, wegen Nichtübersendung des Geldes und der Knaben sei Jonathan ums Leben gekommen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 13, 19, 'Er sandte also die Knaben und die 100 Talente hin, aber Tryphon betrog ihn und ließ Jonathan nicht frei.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 13, 20, 'Hierauf zog Tryphon heran, um in das Land einzurücken und es zu verheeren, und machte den Umweg in der Richtung nach Adora; Simon aber zog mit seinem Heere ihm zur Seite an jeden Ort, wohin jener marschierte.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 13, 21, 'Nun schickten die Leute der Besatzung (in Jerusalem) Boten an Tryphon, die ihn auffordern sollten, schleunigst durch die Wüste zu ihnen zu kommen und ihnen Lebensmittel zuzuführen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 13, 22, 'Tryphon machte auch wirklich seine ganze Reiterei zu dem Zuge bereit; aber in der nächsten Nacht fiel so gewaltig viel Schnee, daß er wegen des Schnees den Zug nicht unternehmen konnte; er brach vielmehr auf und zog in die Landschaft Gilead.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 13, 23, 'Als er dann in die Nähe von Baskama gekommen war, ließ er Jonathan hinrichten; er wurde dort auch begraben.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 13, 24, 'Tryphon aber kehrte um und begab sich nach Hause.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 13, 25, 'Simon aber sandte hin und ließ die Gebeine seines Bruders Jonathan holen; er bestattete ihn dann in Modein, der Stadt seiner Väter.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 13, 26, 'Ganz Israel hielt ein großes Klagefest um ihn ab und betrauerte ihn viele Tage lang.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 13, 27, 'Simon ließ dann über dem Grabe seines Vaters und seiner Brüder ein hohes, weithin sichtbares Bauwerk aufführen aus glattbehauenen Steinen an der Vorder- und Hinterseite.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 13, 28, 'Er stellte sieben Pyramiden oben darauf, je eine gegenüber der andern, für seinen Vater und seine Mutter und seine vier Brüder.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 13, 29, 'An diesen (Pyramiden) aber ließ er Kunstwerke anbringen, indem er ringsum große Säulen aufstellte, an denen er Waffenrüstungen zu ewigem Gedächtnis anbrachte; und neben den Waffenrüstungen waren Schiffe eingemeißelt, damit sie allen Seefahrern sichtbar wären.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 13, 30, 'Dies ist das Grabdenkmal, das er in Modein erbauen ließ; es steht dort bis auf den heutigen Tag.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 13, 31, 'Tryphon aber verfuhr hinterlistig mit dem jungen König Antiochus und ließ ihn töten;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 13, 32, 'er machte sich dann selbst zum König, setzte sich die Krone von Asien aufs Haupt und richtete großes Unheil im Lande an.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 13, 33, 'Simon aber baute die Festungen in Judäa neu aus, umgab sie ringsum mit hohen Türmen und starken Mauern, mit Toren und Riegeln und schaffte Mundvorrat in die festen Plätze.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 13, 34, 'Hierauf erwählte Simon Männer und sandte sie zum Könige Demetrius, um Erlaß (der Abgaben und verhängten Strafen) für das Land zu erwirken; denn alle Handlungen Tryphons hatten in Räubereien bestanden.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 13, 35, 'Der König Demetrius ging auf diese Bitten ein und sandte ihm als Antwort folgendes Schreiben:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 13, 36, '»König Demetrius entbietet dem Hohenpriester Simon, dem Freunde des Königshauses, sowie den Ältesten und dem ganzen Volke der Juden seinen Gruß.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 13, 37, 'Die goldene Krone und den Palmzweig, den ihr uns gesandt habt, haben wir erhalten und sind bereit, euch vollen Frieden zu gewähren und unseren Beamten zu schreiben, daß sie euch Erlaß der Abgaben gewähren;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 13, 38, 'und alles, was wir in bezug auf euch festgesetzt haben, bleibt fest bestehen, und die Festungen, die ihr erbaut habt, sollen euch gehören.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 13, 39, 'Wir gewähren euch Verzeihung für die Verfehlungen und Übertretungen bis auf den heutigen Tag, verzichten auch auf die Kronenabgabe, die ihr zu zahlen verpflichtet wart; und wenn sonst noch eine Abgabe in Jerusalem entrichtet wurde, soll sie von nun an in Wegfall kommen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 13, 40, 'Und wenn einige von euch zur Aufnahme in unsere Leibwache tauglich sind, sollen sie aufgenommen werden, und es soll Friede zwischen uns bestehen«.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 13, 41, 'So wurde im Jahre 170 das Joch der Heiden den Israeliten abgenommen,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 13, 42, 'und das Volk Israel begann, in den Urkunden und Verträgen zu schreiben: »Im ersten Jahre Simons, des großen Hohenpriesters und Feldherrn und Fürsten der Juden«.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 13, 43, 'Zu jener Zeit begann Simon die Belagerung von Gasera und schloß es ringsum mit Truppen ein; er erbaute eine gewaltige Sturmmaschine und brachte sie nahe an die Stadt heran, zertrümmerte damit einen Turm und nahm ihn ein.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 13, 44, 'Als dann die Mannschaften, die sich in dem Belagerungsturm befanden, in die Stadt hineinsprangen, entstand eine große Bestürzung in der Stadt;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 13, 45, 'die Einwohner stiegen mit ihren Frauen und Kindern in zerrissenen Kleidern auf die Mauer, schrieen laut und baten Simon, ihnen Frieden zu gewähren,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 13, 46, 'indem sie ausriefen: »Verfahre nicht mit uns nach unseren Missetaten, sondern nach deiner Barmherzigkeit!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 13, 47, 'Simon erwies sich auch versöhnlich gegen sie und setzte die Feindseligkeiten gegen sie nicht fort; doch zwang er sie, die Stadt zu verlassen, reinigte die Häuser, in denen sich die Götzenbilder befanden, und zog dann unter Lobgesängen und Dankliedern in die Stadt ein.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 13, 48, 'Alles Unreine entfernte er aus ihr und siedelte Leute in ihr an, die das Gesetz beobachteten; auch befestigte er sie noch stärker und baute auch für sich selbst eine Wohnung darin.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 13, 49, 'Unterdessen waren die Mannschaften in der Burg zu Jerusalem an jedem Verkehr mit der Außenwelt und an allem Kaufen und Verkaufen gehindert; sie litten daher argen Mangel an Lebensmitteln, so daß viele von ihnen Hungers starben.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 13, 50, 'Schließlich schrieen sie zu Simon um Gnade, die er ihnen auch gewährte; er ließ sie von dort abziehen und reinigte dann die Burg von den heidnischen Greueln.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 13, 51, 'Er hielt hierauf seinen Einzug in die Burg am 23. Tage des zweiten Monats im Jahre 171 mit Lobgesängen und Palmzweigen und unter dem Klange von Zithern, Zimpeln, Harfen und mit Psalmen und Gesängen, weil ein schlimmer Feind aus Israel beseitigt war;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 13, 52, 'und er ordnete an, daß dieser Tag alljährlich als Freudentag gefeiert werden solle. Den Tempelberg aber neben der Burg befestigte er noch stärker und wohnte daselbst mit seinen Angehörigen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 13, 53, 'Und da Simon sah, daß sein Sohn Johannes sich zu einem (tüchtigen) Manne entwickelt hatte, ernannte er ihn zum Befehlshaber aller Streitkräfte und nahm dann seinen Wohnsitz in Gasera.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 13, 54, '');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 14, 1, 'Im Jahre 172 sammelte der König Demetrius seine Streitkräfte und zog nach Medien, um Verstärkungen zum Kriege gegen Tryphon an sich zu ziehen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 14, 2, 'Als nun Arsakes, der König von Persien und Medien, vernahm, daß Demetrius in sein Gebet eingedrungen sei, schickte er einen seiner Heerführer ab, um ihn lebendig gefangen zu nehmen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 14, 3, 'Dieser zog ins Feld, besiegte das Heer des Demetrius, nahm ihn gefangen und brachte ihn zu Arsakes, der ihn ins Gefängnis werfen ließ.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 14, 4, 'Das Land Juda aber erfreute sich der Ruhe, solange Simon lebte. Er war darauf bedacht, das Wohl seines Volkes zu fördern, und dieses war mit seiner Regierung wohlzufrieden und hatte allezeit Wohlgefallen an seinem Ruhme.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 14, 5, 'Und zu all seinem Ruhme hinzu kam noch die Einnahme von Joppe, das er als Hafenort gewonnen hatte und zu einem Einfuhrplatze für die Inseln (und Küstenländer) des Mittelmeeres machte.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 14, 6, 'Er erweiterte seinem Volke, die Grenzen des Gebiets und war Herr im Lande;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 14, 7, 'er brachte viele aus der Gefangenschaft zurück und nahm Gasera, Bethsura und die Burg ein und beseitigte in ihnen alle heidnische Unreinigkeit, und niemand leistete ihm Widerstand.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 14, 8, 'Sie konnten ihr Land in Frieden bebauen; das Land gab seinen Ertrag und die Bäume auf den Feldern ihre Früchte.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 14, 9, 'Die Greise saßen auf den Straßen, besprachen alle das Wohl der Gemeinde, und die jungen Männer bekleideten sich mit dem Ehrenschmuck des Waffenrocks.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 14, 10, 'Die Städte versorgte er mit Lebensmitteln und rüstete sie aus mit Festungswerken, so daß sein Ruhm erscholl bis ans Ende der Erde.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 14, 11, 'Er schaffte sicheren Frieden im Lande, daß Israel hoher Freude sich hingeben konnte;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 14, 12, 'ein jeder saß unter seinem Weinstock und Feigenbaum, ohne daß jemand ihn aus seiner Ruhe aufschreckte.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 14, 13, 'Auf der Erde gab es keinen mehr, der sie bekriegte, und die Könige waren in jener Zeit gedemütigt.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 14, 14, 'Er half allen Elenden in seinem Volke auf; über dem Gesetz wachte er mit Eifer und vertilgte alle Gottlosen und Abtrünnigen;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 14, 15, 'das Heiligtum schmückte er herrlich aus und vermehrte die heiligen Geräte reichlich.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 14, 16, 'Als man nun zu Rom und bis Sparta hin Kunde vom Tode Jonathans erhielt, wurden alle tief betrübt;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 14, 17, 'als man aber erfuhr, daß sein Bruder Simon als Hoherpriester an seine Stelle getreten sei und die Regierung im Lande und in den Städten darin führe,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 14, 18, 'schrieben sie auf ehernen Tafeln an ihn, um die Freundschaft und Bundesgenossenschaft zu erneuern, die sie mit seinen Brüdern Judas und Jonathan geschlossen hatten.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 14, 19, 'Das betreffende Schreiben kam in der Gemeindeversammlung zu Jerusalem zur Verlesung;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 14, 20, 'und dies ist die Abschrift des Schreibens, das die Spartaner sandten: »Die Obersten und die Hauptstadt der Spartaner entbieten dem Hohenpriester Simon, sowie den Ältesten und Priestern und dem übrigen Volke der Juden, ihren Brüdern, ihren Gruß.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 14, 21, 'Die Gesandten, die von euch an unser Volk geschickt worden sind, haben uns Mitteilung von eurem Ruhm und eurer Ehre gemacht, und wir haben uns über ihr Kommen gefreut');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 14, 22, 'und haben das von ihnen Berichtete in die Volksbeschlüsse folgendermaßen eingetragen: »Numenius, der Sohn des Antiochus, und Antipater, der Sohn des Jason, sind als Gesandte der Juden zu uns gekommen, um den mit uns geschlossenen Freundschaftsbund zu erneuern.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 14, 23, 'Das Volk beschloß, diese Männer ehrenvoll zu empfangen und eine Abschrift ihrer Botschaft unter den Staatsurkunden des Volkes niederzulegen, damit das Volk der Spartaner ein Andenken habe. Eine Abschrift dieses Beschlusses aber haben wir dem Hohenpriester Simon ausgefertigt«.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 14, 24, 'Später sandte Simon den Numenius mit einem großen goldenen Schild im Gewicht von 1000 Minen nach Rom, um die Bundesgenossenschaft mit ihnen zu befestigen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 14, 25, 'Als nun das (jüdische) Volk dies alles erfuhr, sagte man: »Welchen Dank sollen wir Simon und seinen Söhnen erstatten?');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 14, 26, 'Denn er und seine Brüder und sein ganzes väterliches Haus haben feste Tatkraft bewiesen: sie haben die Feinde Israels mit den Waffen in der Hand abgewehrt und unserm Volke die Freiheit errungen«.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 14, 27, 'So brachten sie denn eine Inschrift auf ehernen Tafeln an und hängten diese an Säulen auf dem Zionsberge auf. Und dies ist der Wortlaut der Inschrift: Am 18. Elul des Jahres 172 – das ist das dritte Jahr – unter dem Hohenpriester Simon, dem Fürsten des Volkes Gottes, –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 14, 28, 'ist uns in einer großen Versammlung der Priester und des Volkes, der Obersten des Volkes und der Ältesten des Landes Folgendes kundgetan worden:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 14, 29, 'Da oft Kriege stattfanden, haben Simon, der Sohn des Mattathias, aus der Familie Joarib, und seine Brüder ihr Leben aufs Spiel gesetzt und den Feinden ihres Volkes Widerstand geleistet, damit ihr Heiligtum und das Gesetz erhalten bliebe, und haben ihrem Volke hohen Ruhm verschafft.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 14, 30, 'Denn als Jonathan ihr Volk geeinigt hatte und ihr Hoherpriester geworden und zu seinen Vätern versammelt worden war');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 14, 31, 'und ihre Feinde beschlossen hatten, in ihr Land einzudringen, um es zu verheeren und Hand an ihr Heiligtum zu legen,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 14, 32, 'da trat Simon auf und kämpfte für sein Volk. Er opferte einen großen Teil seines eigenen Vermögens, um die Mannschaften im Heere seines Volkes zu bewaffnen und ihnen Sold zu geben.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 14, 33, 'Er befestigte die Städte Judäas und Bethsura an der Grenze Judäas, das vordem ein Waffenplatz der Feinde gewesen war, und legte jüdische Krieger als Besatzung hinein.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 14, 34, 'Auch die Seestadt Joppe befestigte er, sowie Gasara an der Grenze des Gebietes von Asdod, wo die Feinde vorher sich festgesetzt hatten; er siedelte dort Juden an und versah diese Städte mit allem, was zu ihrer Instandhaltung erforderlich war.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 14, 35, 'Da nun das Volk die Treue Simons erkannte, sowie den Ruhm, den er seinem Volke zu verschaffen suchte, ernannte es ihn zu seinem Oberhaupt und Hohenpriester, weil er alles dieses vollführt hatte, und wegen der Gerechtigkeit und Treue, die er seinem Volke unverbrüchlich bewahrte, und weil er das Wohl seines Volkes auf jede Weise zu fördern gesucht hatte.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 14, 36, 'Solange er am Leben war, gelang es durch sein Wirken, daß die Heiden aus dem jüdischen Lande entfernt wurden, und ebenso die Heiden in der Davidstadt zu Jerusalem, die sich dort eine feste Burg errichtet hatten, aus der sie hervorbrachen und die Heiligkeit der ganzen Umgebung des Tempels entweihten und an der geweihten Stätte schlimmes Unheil anrichteten.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 14, 37, 'Er legte jüdische Krieger hinein und befestigte die Burg zur Sicherung des Landes und der Hauptstadt und erhöhte die Mauern Jerusalems.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 14, 38, 'Der König Demetrius bestätigte ihm demgemäß seine Hohepriesterwürde,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 14, 39, 'nahm ihn in die Zahl seiner Vertrauten auf und erwies ihm hohe Ehren;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 14, 40, 'denn er hatte vernommen, daß die Juden von den Römern den Ehrennamen Freunde, Bundesgenossen und Brüder erhalten und daß man (in Rom) die Gesandten Simons ehrenvoll empfangen hatte.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 14, 41, 'So haben denn die Juden und ihre Priester beschlossen, daß Simon ihr Oberhaupt und Hoherpriester für immer sein soll, bis ein glaubwürdiger Prophet erstehen würde,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 14, 42, 'und daß er auch ihr Feldhauptmann sein (und ihm die Sorge für das Heiligtum obliegen) soll, damit er Beamte bestelle für die öffentlichen Arbeiten und für die Verwaltung des Landes, für die Waffen und die Festungen;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 14, 43, 'und daß ihm die Sorge für das Heiligtum obliegen und ihm Gehorsam von allen geleistet werden soll; daß ferner in seinem Namen alle Erlasse im Lande ausgefertigt werden und er sich in Purpur kleiden und Goldschmuck tragen soll.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 14, 44, 'Auch soll es niemandem von dem Volk und von den Priestern gestattet sein, eine von diesen Bestimmungen aufzuheben und seinen Anordnungen zu widersprechen und ohne seine Erlaubnis eine Volksversammlung im Lande zu veranstalten und sich in Purpur zu kleiden oder eine Goldspange als Schmuck zu tragen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 14, 45, 'Wer sich aber gegen diese Bestimmungen vergeht oder eine von ihnen aufhebt, der soll straffällig sein«.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 14, 46, 'Das ganze Volk beschloß also, zu Gunsten Simons zu verfügen, daß nach diesen Bestimmungen verfahren werden solle;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 14, 47, 'Simon aber willigte ein und erklärte sich bereit, Hoherpriester und Feldhauptmann und Volksfürst der Juden und der Priester zu sein und dem Ganzen vorzustehen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 14, 48, 'Sodann bestimmte man, diese Verfügung solle auf ehernen Tafeln angebracht und diese im Vorhofe des Heiligtums an einem weithin sichtbaren Orte aufgestellt werden.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 14, 49, 'Eine Abschrift davon aber ließ man in der Schatzkammer niederlegen, damit sie dem Simon und seinen Söhnen zur Verfügung stände.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 15, 1, 'Hierauf sandte Antiochus, der Sohn des Königs Demetrius, ein Schreiben von den Inseln des Mittelmeeres aus an Simon, den Priester und Volksfürsten der Juden, und an das ganze Volk.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 15, 2, 'Das Schreiben hatte folgenden Wortlaut: »König Antiochus entbietet dem Hohenpriester und Volksfürsten Simon und dem Volke der Juden seinen Gruß.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 15, 3, 'Da nichtswürdige Menschen das Reich unserer Väter im Besitz genommen haben, ich aber willens bin, es wiederzugewinnen, um die früheren Verhältnisse darin wiederherzustellen, ich auch ein großes Heer angeworben und Kriegsschiffe ausgerüstet habe');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 15, 4, 'und entschlossen bin, dort zu landen und das Land zu durchziehen, um die Verderber unseres Landes und die Verwüster zahlreicher Städte im Reiche zu bestrafen:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 15, 5, 'so bestätigte ich dir nun alle Erlasse an Abgaben, die dir die Könige, meine Vorgänger, gewährt und was sie dir sonst noch an Geschenken nachgelassen haben.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 15, 6, 'Weiter gestatte ich dir, eigene Münzen für dein Land prägen zu lassen;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 15, 7, 'Jerusalem aber und das Heiligtum sollen frei sein, und alle Waffen, die du beschafft hast, und die von dir erbauten Festungen, die du innehast, sollen dir verbleiben;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 15, 8, 'und alle Verpflichtungen gegen die königliche Kasse, auch was du in Zukunft der Krone schuldig bleiben wirst, soll dir von jetzt an und für immer erlassen sein.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 15, 9, 'Sobald wir aber in den Besitz unseres Reiches gekommen sind, wollen wir dich und dein Volk und den Tempel mit hohen Ehren bedenken, so daß euer Ruhm auf der ganzen Erde bekannt werden soll«.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 15, 10, 'Im Jahre 174 zog Antiochus in das Land seiner Väter ein, und alle Truppen fielen ihm zu, so daß nur wenige dem Tryphon treu verblieben.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 15, 11, 'Vom Könige Antiochus verfolgt, gelangte Tryphon auf der Flucht nach der Seestadt Dora;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 15, 12, 'denn er erkannte wohl, daß seine Lage sich überaus gefahrvoll gestaltet hatte, da die Truppen ihm untreu geworden waren.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 15, 13, 'Antiochus belagerte nun Dora mit einem Heere von 120000 Mann zu Fuß und 8000 Reitern.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 15, 14, 'Er schloß die Stadt ringsum ein, während die Schiffe von der Seeseite her tätig waren, und so bedrängte er die Stadt zu Lande und zu Wasser und ließ niemand mehr aus- und eingehen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 15, 15, 'Nun kam Numenius mit seinen Begleitern aus Rom zurück mit Schreiben an die Könige und Länder folgenden Inhalts:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 15, 16, '»Der römische Konsul Lucius entbietet dem König Ptolemäus seinen Gruß.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 15, 17, 'Die Gesandten der Juden, abgesandt vom Hohenpriester Simon und vom Volke der Juden, sind als unsere Freunde und Bundesgenossen zu uns gekommen, um die von altersher bestehende Freundschaft und Bundesgenossenschaft zu erneuern;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 15, 18, 'sie haben uns einen Goldschild im Werte von 1000 Minen überbracht.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 15, 19, 'So haben wir denn beschlossen, den Königen und Ländern zu schreiben, daß sie nicht darauf ausgehen sollen, ihnen irgendwie Böses zuzufügen, und daß sie weder mit ihnen und ihren Städten und ihrem Lande Krieg führen, noch denen Beistand leisten sollen, die Krieg mit ihnen führen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 15, 20, 'Den Schild haben wir gern von ihnen angenommen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 15, 21, 'Sollten nun nichtswürdige Leute sich aus ihrem Lande zu euch flüchten, so liefert sie dem Hohenpriester Simon aus, damit er sie nach ihrem Gesetz bestrafe«.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 15, 22, 'Briefe des gleichen Inhalts ließ Lucius auch dem Könige Demetrius zugehen, sowie dem Attalus, dem Ariarathes und Arsakes,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 15, 23, 'außerdem in alle Länder, nämlich nach Sampsame, an die Spartaner, nach Delos, Myndos, Sicyon, Karien, Samos, Pamphylien, Lycien, Halikarnassus, Rhodus, Phaselis, Kos, Side, Aradus, Gortyna, Knidus, Cypern und Cyrene.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 15, 24, 'Eine Abschrift davon sandte man auch dem Hohenpriester Simon zu.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 15, 25, 'Der König Antiochus aber griff Dora gleich am zweiten Tage an, indem er seine Mannschaften die Stadt unablässig bestürmen ließ und Belagerungsmaschinen aufstellte, und schloß den Tryphon so eng ein, daß keine Verbindung mit der Außenwelt mehr stattfand.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 15, 26, 'Als ihm nun Simon 2000 auserlesene Krieger als Hilfstruppen zusandte, dazu Silber und Gold und Kriegsbedarf in Fülle,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 15, 27, 'wollte er nichts davon annehmen, sondern widerrief alles, was er ihm früher zugesagt hatte, und sagte sich ganz von ihm los.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 15, 28, 'Er sandte Athenobius, einen seiner Vertrauten, zu ihm, um mit ihm zu unterhandeln, und ließ ihm sagen: »Ihr haltet Joppe und Gasara und die Burg in Jerusalem besetzt, lauter Städte, die zu meinem Reiche gehören.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 15, 29, 'Ihr habt deren Gebiete verwüstet und dem Lande schweren Schaden zugefügt und euch zahlreiche Ortschaften in meinem Reiche angeeignet.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 15, 30, 'Gebt also die Städte wieder heraus, die ihr in Besitz genommen habt, und zahlt die Abgaben von den Orten, die ihr euch außerhalb des Gebietes von Judäa angeeignet habt.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 15, 31, 'Wenn ihr das nicht wollt, so zahlt dafür 500 Talente Silber und für die angerichtete Verwüstung und für die Steuern von den Städten weitere 500 Talente. Wo nicht, so werden wir kommen und euch mit Krieg überziehen«.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 15, 32, 'Athenobius, der Vertraute des Königs, kam also nach Jerusalem; als er aber die Pracht Simons sah und den Schenktisch mit den goldenen und silbernen Prunkgefäßen und die zahlreiche Dienerschaft, da geriet er vor Staunen ganz außer sich. Als er ihm aber die Botschaft des Königs mitgeteilt hatte,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 15, 33, 'gab ihm Simon zur Antwort: »Wir haben uns weder fremdes Land angeeignet, noch uns fremden Eigentums bemächtigt, sondern nur des Besitztums unserer Väter, das unsere Feinde ungerechterweise bei irgend einer günstigen Gelegenheit an sich gerissen hatten.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 15, 34, 'Wir aber halten, solange die Verhältnisse uns günstig sind, das Besitztum unserer Väter fest.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 15, 35, 'Was aber Joppe und Gasara betrifft, deren Zurückgabe du verlangst, so haben diese vielmehr unter unserem Volke großes Unheil in unserem Lande angerichtet; doch wollen wir für diese Plätze 100 Talente zahlen«. Athenobius erwiderte ihm darauf kein Wort,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 15, 36, 'sondern kehrte in leidenschaftlicher Erregung zum Könige zurück und machte ihm Mitteilung von dieser Erklärung Simons, sowie von seiner Pracht und von allem, was er gesehen hatte. Da geriet der König in heftigen Zorn.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 15, 37, 'Tryphon aber bestieg ein Schiff und entkam nach Orthosia.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 15, 38, 'Darauf ernannte der König den Kendebäus zum Befehlshaber über das Küstenland und übergab ihm Fußvolk und Reiterei;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 15, 39, 'zugleich befahl er ihm, zunächst Judäa gegenüber ein Lager zu beziehen, sodann Kedron zu befestigen und mit starken Toren zu versehen und das jüdische Volk zu bekriegen; der König selbst aber verfolgte den Tryphon.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 15, 40, 'So kam denn Kendebäus nach Jamnia und fing an, das Volk zu beunruhigen, Einfälle in Judäa zu machen, Gefangene wegzuführen und Leute zu töten.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 15, 41, 'Auch befestigte er Kedron und legte Reiter und Fußvolk hinein, die von dort Ausfälle machen und auf den nach Judäa führenden Landstraßen umherstreifen sollten, wie der König ihm befohlen hatte.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 16, 1, 'Darauf machte sich Johannes von Gasara auf den Weg und erstattete seinem Vater Simon Bericht über das Tun und Treiben des Kendebäus.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 16, 2, 'Da berief Simon seine beiden ältesten Söhne Judas und Johannes und sagte zu ihnen: »Ich und meine Brüder und das ganze Haus meines Vaters haben die Feinde Israels von Jugend an bis heute bekämpft, und es ist uns mehr als einmal gelungen, Israel durch unsere Taten zu retten.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 16, 3, 'Nun aber bin ich alt geworden, während ihr durch Gottes Gnade in den Jahren voller Tüchtigkeit steht. So tretet also an meine und meines Bruders Stelle, zieht ins Feld und kämpft für unser Volk; die Hilfe des Himmels aber sei mit euch!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 16, 4, 'Hierauf hob er im Lande 20000 Mann Fußvolk, sowie Reiterei aus, die zogen gegen Kendebäus ins Feld und verbrachten die Nacht in Modein.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 16, 5, 'Am anderen Morgen in der Frühe brachen sie auf und zogen in die Ebene hinab; da stand ihnen plötzlich ein großes Heer Fußvolk und Reiterei gegenüber, und nur ein Gießbach war zwischen ihnen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 16, 6, 'Er nahm nun mit seinen Leuten ihnen gegenüber Stellung; und da er erkannte, daß seine Leute sich scheuten, den Gießbach zu durchschreiten, ging er zuerst hinüber; als das die Männer sahen, folgten sie ihm nach.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 16, 7, 'Er teilte dann sein Fußvolk und stellte die Reiterei in die Mitte der Fußsoldaten; denn die feindliche Reiterei war überaus stark.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 16, 8, 'Als man dann das Trompetensignal gegeben hatte, wurde Kendebäus mit seinem Heere in die Flucht geschlagen, und viele von ihnen blieben erschlagen auf dem Platze; die übrigen retteten sich durch die Flucht in die Festung.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 16, 9, 'Damals wurde Judas, der Bruder des Johannes, verwundet; Johannes aber verfolgte die Flüchtigen bis Kedron, das Kendebäus hatte befestigen lassen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 16, 10, 'Die Feinde flohen dann noch weiter in die Burgen auf der Feldmark von Asotus. Er ließ diese Stadt in Flammen aufgehen, und es kamen dabei gegen 2000 Mann ums Leben. Hierauf kehrte er wohlbehalten nach Judäa zurück.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 16, 11, 'Ptolemäus aber, der Sohn des Abubus, war als Befehlshaber in der Ebene von Jericho eingesetzt und besaß viel Silber und Gold,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 16, 12, 'denn er war der Schwiegersohn des Hohenpriesters.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 16, 13, 'Da stieg der Hochmut in seinem Herzen auf, so daß er den Entschluß faßte, sich des Landes zu bemächtigen, und darauf ausging, Simon und seine Söhne hinterlistigerweise aus dem Wege zu räumen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 16, 14, 'Nun pflegte Simon die Städte im Lande zu bereisen, um für ihre Bedürfnisse Sorge zu tragen. So kam er denn auch nach Jericho mit seinen Söhnen Mattathias und Judas im Jahre 177 im elften Monat – das ist der Monat Sabat.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 16, 15, 'Da empfing sie der Sohn des Abubus hinterlistigerweise in der kleinen Festung Dok, die er hatte erbauen lassen, und veranstaltete ihnen zu Ehren ein großes Festmahl, nachdem er dort Männer versteckt hatte.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 16, 16, 'Als nun Simon und seine Söhne trunken waren, stand Ptolemäus mit seinen Helfershelfern auf, nahmen ihre Waffen, überfielen Simon im Speisezimmer und töteten ihn und seine beiden Söhne nebst einigen von seinen Dienern.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 16, 17, 'Er verübte so seine schwere Treulosigkeit und vergalt Gutes mit Bösem.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 16, 18, 'Hierauf sandte Ptolemäus einen schriftlichen Bericht über das Vorkommnis an den König mit dem Ersuchen, er möchte ihm Truppen zu Hilfe senden und ihm das jüdische Land und die Städte überweisen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 16, 19, 'Zugleich schickte er andere Leute nach Gasara, um Johannes aus dem Wege zu räumen; und an die Hauptleute richtete er Briefe mit der Aufforderung, sie möchten sich an ihn anschließen, damit er ihnen Silber, Gold und Geschenke gäbe.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 16, 20, 'Wieder andere schickte er nach Jerusalem, um sich der Stadt und des Tempelberges zu bemächtigen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 16, 21, 'Es war aber ein Mann vorausgeeilt und hatte dem Johannes in Gasara gemeldet, daß sein Vater und seine Brüder ermordet und daß Leute entsandt worden seien, um auch ihn zu ermorden.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 16, 22, 'Diese Nachricht versetzte ihn in die höchste Bestürzung; er nahm die Männer, die zu seiner Ermordung gekommen waren, gefangen und ließ sie hinrichten; denn er überzeugte sich davon, daß sie ihn hatten ermorden wollen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 16, 23, 'Die übrige Geschichte des Johannes und seiner Kriege und der Heldentaten, die er vollbracht hat, sowie des Mauerbaues, den er ausgeführt, kurz aller seiner Taten,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 16, 24, 'das findet sich bekanntlich aufgezeichnet im Buche der Geschichte seines Hohenpriestertums, von der Zeit ab, wo er Hoherpriester nach seinem Vater geworden war.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 1, 1, 'Den Brüdern, den Juden in Ägypten, unsern Gruß zuvor! Eure Brüder, die Juden in Jerusalem und in der Landschaft Judäa, wünschen euch Frieden und Heil.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 1, 2, 'Ja, Gott wolle es euch gut ergehen lassen und des Bundes gedenken, den er mit Abraham, Isaak und Jakob, seinen treuen Knechten, geschlossen hat;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 1, 3, 'er schenke euch allen ein Herz, das bereit ist, ihn zu verehren und seinen Willen zu tun mit starkem Mut und williger Seele!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 1, 4, 'Er schließe euch das Herz auf für sein Gesetz und seine Gebote und schaffe euch Frieden!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 1, 5, 'Er erhöre auch eure Gebete und wende euch seine Gnade zu und verlasse euch nicht in der Zeit der Not!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 1, 6, 'Das sind die Gebete, die wir auch jetzt für euch darbringen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 1, 7, 'Während der Regierung des Demetrius, im Jahre 169, haben wir Juden an euch geschrieben in der äußersten Trübsal, die in jenen Jahren über uns hereingebrochen war, seitdem Jason und sein Anhang vom heiligen Lande und vom Königreiche abgefallen waren');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 1, 8, 'und man das Tor verbrannt und unschuldiges Blut vergossen hatte. Da haben wir zum Herrn gebetet und haben auch Erhörung gefunden; wir haben Schlachtopfer und Speisopfer dargebracht und die Lampen angezündet und die Schaubrote aufgelegt.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 1, 9, 'Und nunmehr feiert ja die Tage des Laubhüttenfestes im Monat Kislev. Gegeben im Jahre 188.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 1, 10, 'Die zu Jerusalem in Judäa wohnenden Juden, sowie der Hohe Rat und Judas wünschen dem Aristobulus, dem Lehrer des Königs Ptolemäus, der vom Geschlecht der gesalbten Priester stammt, sowie den Juden in Ägypten Heil und Gesundheit.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 1, 11, 'Aus großen Gefahren durch Gottes Hilfe gerettet, sind wir ihm aufrichtig dankbar als solche, die zum Kampfe gegen den König (von Syrien) immer bereit sind;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 1, 12, 'er selbst hat ja die verjagt, die sich in der heiligen Stadt zum Kampfe bereit gemacht hatten.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 1, 13, 'Denn als der Fürst mit seinem für unüberwindlich gehaltenen Heere nach Persien gekommen war, wurden sie im Tempel der Nanäa erschlagen, indem die Priester der Nanäa sich einer List bedienten.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 1, 14, 'Antiochus war nämlich mit seinen Freunden an den Ort gekommen unter dem Vorwande, er wolle sich mit der Göttin vermählen, in der Tat aber zu dem Zweck, die reichen Schätze gleichsam als Mitgift hinzunehmen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 1, 15, 'Die Priester des Nanäatempels holten sie nun zwar hervor; da jener aber mit nur wenigen Begleitern in den Tempelbezirk gekommen war, schlossen sie, sobald Antiochus eingetreten war, das Heiligtum zu,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 1, 16, 'öffneten dann die in der Decke verborgene Tür, warfen Steine herab und zerschmetterten den Fürsten; denn zerstückten sie die Leichen, hieben ihnen die Köpfe ab und warfen sie den draußen Stehenden zu.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 1, 17, 'Gepriesen für alles sei unser Gott, der die Gottlosen so dahingegeben hat!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 1, 18, 'Da wir am 25. des Monats Kislev die Reinigung des Tempels zu feiern gedenken, haben wir es für unsere Pflicht gehalten, euch davon Kenntnis zu geben, damit auch ihr das Fest in der Weise der Laubhütten begehet und zur Erinnerung an das Feuer, (das uns gegeben wurde), als Nehemia nach Erbauung des Tempels und des Altars wieder ein Opfer darbrachte.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 1, 19, 'Als nämlich unsere Väter einst nach Persien weggeführt wurden, nahmen die damaligen frommen Priester heimlich etwas vom Feuer des Altars und verbargen es in der Höhlung einer Zisterne, die gerade wasserleer war; darin brachten sie es so sicher unter, daß kein Mensch den Ort kannte.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 1, 20, 'Als es nun nach Verlauf vieler Jahre Gott gefiel, schickte Nehemia, den der König von Persien hergesandt hatte, die Nachkommen jener Priester, die das Feuer versteckt hatten, mit der Weisung hin, das Feuer zu holen. Als sie uns aber berichteten, kein Feuer, sondern nur schlammiges Wasser gefunden zu haben, befahl er ihnen, davon zu schöpfen und es zu bringen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 1, 21, 'Da nun alles zu dem Opfer Erforderliche zugerichtet war, befahl Nehemia den Priestern, sie möchten mit dem Wasser die Holzscheite und die daraufliegenden Fleischstücke begießen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 1, 22, 'Als dies geschehen war und nach einiger Zeit die Sonne, die bis dahin hinter Wolken verborgen gewesen war, hell zu scheinen begann, flammte ein großes Feuer auf, so daß alle in Erstaunen gerieten.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 1, 23, 'Während nun das Opfer verzehrt wurde, verrichteten die Priester ein Gebet, die Priester und alle Anwesenden, indem Jonathan den Anfang machte und die übrigen, auch Nehemia, einstimmten.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 1, 24, 'Das Gebet lautete aber folgendermaßen: »Herr, Herr, Gott, Schöpfer aller Dinge, du Furchtbarer und Gewaltiger, du Gerechter und Barmherziger, du der alleinige König und Wohltäter,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 1, 25, 'der du allein gute Gaben verleihst, der du allein gerecht, allmächtig und ewig bist, der du Israel aus allem Unheil errettest, der du unsere Väter dir auserwählt und geheiligt hast:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 1, 26, 'nimm dieses Opfer an für dein ganzes Volk Israel und behüte und heilige dein Erbteil!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 1, 27, 'Bringe uns Zerstreute wieder zusammen, befreie die unter den Heiden in Knechtschaft Lebenden, blicke die Verachteten und Verabscheuten gnädig an und laß die Heiden erkennen, daß du unser Gott bist!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 1, 28, 'Strafe die, welche uns unterdrücken und im Übermut uns mißhandeln!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 1, 29, 'Pflanze dein Volk wieder ein an deiner heiligen Stätte, wie Mose es verheißen hat!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 1, 30, 'Die Priester sangen ihre Loblieder dazu.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 1, 31, 'Sobald nun die Fleischstücke des Opfers verbrannt waren, ließ Nehemia mit dem übrigen Wasser große Steine begießen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 1, 32, 'Sofort schlug da eine Flamme empor, die aber von dem auf dem Altar entgegenstrahlenden Lichte verdunkelt wurde.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 1, 33, 'Als aber die Sache bekannt wurde und man dem Könige von Persien berichtete, daß an der Stelle, wo die in Gefangenschaft weggeführten Priester das Feuer verborgen hatten, Wasser zum Vorschein gekommen sei, womit dann Nehemia und seine Genossen das Opfer geweiht hätten,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 1, 34, 'da ließ der König, nachdem er die Sache genau untersucht hatte, den Ort umzäunen und dadurch für heilig erklären.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 1, 35, 'Auch ließ der König denen, welchen er wohlwollte, reiche Geldgeschenke zukommen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 1, 36, 'Nehemia aber und die Seinigen nannten dies (schlammige Wasser) Nephthar, d.h. auf deutsch Reinigung; meistens aber wird es Nephtha genannt.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 2, 1, 'Man findet in den Urkunden nicht nur, daß der Prophet Jeremia den in die Gefangenschaft Ziehenden etwas von dem Feuer wegzunehmen befahl, wie soeben berichtet worden ist,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 2, 2, 'sondern auch, daß der Prophet nach Überreichung des Gesetzbuches die Weggeführten ermahnte, die Gebote des Herrn nicht zu vergessen und sich in ihrem Sinn nicht irremachen zu lassen beim Anblick der goldenen und silbernen Götzenbilder mit ihrem Schmuck.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 2, 3, 'Auch noch durch andere Reden dieser Art ermahnte er sie, das Gesetz nicht aus ihrem Herzen entschwinden zu lassen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 2, 4, 'In der Schrift stand auch geschrieben, daß der Prophet infolge einer göttlichen Weisung das Zelt und die Bundeslade sich nachtragen ließ und daß er nach dem Berge hinging, von dessen Höhe Mose einst das Erbland Gottes gesehen hatte.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 2, 5, 'Nach seiner Ankunft fand Jeremia dort eine geräumige Höhle, in die er das Zelt, die Lade und den Räucheraltar hineinbrachte und sodann den Eingang verstopfte.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 2, 6, 'Mehrere von denen, die ihn dort begleitet hatten, kamen hierauf, um sich den Weg zu merken, konnten ihn aber nicht wiederfinden.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 2, 7, 'Als Jeremia das erfuhr, machte er ihnen Vorwürfe und sagte ihnen, daß der Ort unbekannt bleiben solle, bis Gott sein Volk wieder zusammenbringen und sich ihm gnädig erweisen würde.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 2, 8, 'Dann erst würde der Herr diese Geräte wieder zum Vorschein kommen lassen, und die Herrlichkeit des Herrn würde in der Wolke erscheinen, wie sie sich zur Zeit Mose’s gezeigt habe und wie auch Salomo gebeten hätte, daß die (heilige) Stätte hoch verherrlicht werden möchte. –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 2, 9, 'Es war da auch berichtet, wie jener mit Weisheit begabte Salomo das Opfer zur Vollendung und Einweihung des Tempels darbrachte;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 2, 10, 'und ebenso, wie Mose einst zum Herrn gebetet hatte und Feuer vom Himmel herabgefallen war und die Opferstücke verzehrt hatte; ebenso betete auch Salomo, und das Feuer, welches herabfuhr, verzehrte die Brandopfer.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 2, 11, 'Mose hat ja einst gesagt: »Weil das Sündopfer nicht gegessen wurde, ist es (vom Feuer) verzehrt worden«.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 2, 12, 'Ebenso hat auch Salomo das achttägige Fest gefeiert.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 2, 13, 'Es fanden sich aber nicht nur gerade diese (soeben angeführten) Tatsachen in den Schriften, nämlich in den Denkwürdigkeiten Nehemias, berichtet, sondern auch, daß er als Stifter einer Bibliothek die Bücher über die Könige und Propheten, sowie die Schriftwerke Davids und Briefe von Königen über Weihgeschenke gesammelt habe.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 2, 14, 'Ebenso hat auch Judas die Schriften, wie wegen des Krieges, den wir zu führen hatten, zerstreut worden waren, vollständig wieder gesammelt, und wir besitzen sie noch.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 2, 15, 'Solltet ihr etwas davon nötig haben, so sendet Leute, die es euch von hier abholen. –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 2, 16, 'Da wir nun das Fest der Tempelweihe zu feiern gedenken, so lassen wir euch dies Schreiben zugehen; ihr werdet also wohl tun, diese Tage auch zu feiern.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 2, 17, 'Unser Gott aber, der sein ganzes Volk gerettet und ihnen allen das Erbteil und das Königtum, das Priestertum und die Heiligung verliehen hat,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 2, 18, 'wie er’s durch das Gesetz verheißen hat: dieser Gott, auf den wir unsere Hoffnung setzen, wird sich unser bald erbarmen und uns aus den Ländern, soweit der Himmel reicht, an der heiligen Stätte wieder vereinigen; er hat uns ja bereits aus großen Nöten befreit und die (heilige) Stätte gereinigt.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 2, 19, 'Was nun aber die Geschichte des Judas Makkabäus und seiner Brüder betrifft, sowie den Bericht über die Reinigung des großen Tempels und über die Einweihung des Altars,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 2, 20, 'ferner die Kriege gegen Antiochus Epiphanes und dessen Sohn Antiochus Eupator,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 2, 21, 'sowie die himmlischen Erscheinungen, die denen zuteil wurden, die für das Judentum ruhmvoll und als Helden stritten, so daß sie trotz ihrer geringen Zahl das ganze Land eroberten und die Horden der heidnischen Barbaren verjagten');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 2, 22, 'und den weltberühmten Tempel wiedergewannen, die Hauptstadt befreiten, die Gesetze, die abgeschafft werden sollten, wieder zur Geltung brachten, weil der Herr in aller Güte ihnen gnädig war: –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 2, 23, 'dies alles, was Jason von Cyrene in fünf Büchern berichtet hat, wollen wir versuchen, in ein einziges Buch zusammenzuziehen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 2, 24, 'Denn indem wir die Menge der Zahlen und die Schwierigkeit erwogen, die aus der Fülle des Stoffs denen erwächst, die sich in die geschichtlichen Berichte hineinarbeiten wollen,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 2, 25, 'so sind wir für solche, die zu lesen wünschen, auf angenehme Unterhaltung bedacht gewesen, dagegen für solche, welche die Tatsachen im Gedächtnis behalten möchten, auf Erleichterung, überhaupt aber auf den Nutzen aller, denen dies Buch in die Hände fallen sollte.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 2, 26, 'Für uns freilich, die wir die Mühe dieses Auszugs übernommen haben, ist die Sache nichts Leichtes, vielmehr ein Geschäft des Schweißes und der Nachtwachen,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 2, 27, 'gleichwie es auch nichts Bequemes ist, wenn man ein Gastmahl zurüstet und auf den Genuß anderer bedacht ist. Dennoch wollen wir die Mühe gern auf uns nehmen, weil viele uns dafür dankbar sein werden.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 2, 28, 'Dabei haben wir die genaue Ermittlung der einzelnen Tatsachen dem Geschichtschreiber anheimgestellt und lassen es uns lediglich angelegen sein, den an einen Auszug zu stellenden Forderungen zu genügen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 2, 29, 'Wie nämlich bei einem neuen Hause der Baumeister die Sorge für die ganze Ausführung des Baues zu tragen hat, während derjenige, welcher die Zeichnungen und Malereien ausführt, nur das für die Ausschmückung Erforderliche besorgen muß, so ist es, scheint mir’s, auch hier bei uns der Fall.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 2, 30, 'Das Eindringen in die Tiefe und das umfassende Berichterstatten und die sorgfältige Erforschung aller einzelnen Tatsachen, das ist Sache des eigentlichen Geschichtschreibers;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 2, 31, 'dagegen das Streben nach Kürze des Ausdrucks und der Verzicht auf ausführliche Darstellung ist dem zu gestatten, der nur eine Umformung des Stoffes vornimmt.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 2, 32, 'So wollen wir uns denn nunmehr, nachdem wir uns so lange mit der Vorrede beschäftigt haben, der Erzählung selbst zuwenden; denn es wäre ja töricht, in der Einleitung zu einem Geschichtswerk weitschweifig zu sein, nachher aber den geschichtlichen Bericht selbst kurz abzutun.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 2, 33, '');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 3, 1, 'Während also die heilige Stadt für ihre Bewohner in tiefem Frieden lag und die Gesetze aufs beste beobachtet wurden infolge der Frömmigkeit des Hohenpriesters Onias und um seines Hasses der Gottlosigkeit willen,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 3, 2, 'da kam es oftmals vor, daß selbst die Könige die heilige Stätte ehrten und den Tempel durch ihre reichsten Zuwendungen verherrlichten,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 3, 3, 'so daß unter anderen auch Seleukus, der König von Asien, aus seinen eigenen Einkünften alle Kosten bestritt, die der Opferdienst verursachte.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 3, 4, 'Ein gewisser Simon aber aus dem Stamme Benjamin, dem das Amt des Vorstehers der Tempelverwaltung übertragen war, geriet mit dem Hohenpriester in Streit wegen der städtischen Marktaufsicht;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 3, 5, 'und da er gegen Onias nicht Recht behalten konnte, begab er sich zu Apollonius, dem Sohne des Thrasäus, der damals Statthalter in Cölesyrien und Phönizien war,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 3, 6, 'und berichtete diesem, die Schatzkammer des Tempels in Jerusalem sie mit unermeßlichen Reichtümern angefüllt, so daß die Menge des Geldes unzählbar sei und in keinem Verhältnis zu den Kosten der Opfer stehe; es sei aber wohl möglich, daß dies alles dem Könige zur Verfügung gestellt würde.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 3, 7, 'Als nun Apollonius mit dem Könige zusammentraf, machte er ihm Mitteilung von dem Gelde, das zu seiner Kenntnis gekommen war; der König aber erwählte seinen Reichskanzler Heliodorus und entsandte ihn mit dem Befehl, er solle sich das vorbezeichnete Geld ausliefern lassen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 3, 8, 'Heliodorus machte sich sofort auf den Weg, und zwar unter dem Vorwande, die Städte in Cölesyrien und Phönizien bereisen zu wollen, in der Tat aber, um den Wunsch des Königs zur Ausführung zu bringen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 3, 9, 'In Jerusalem angekommen und von dem Hohenpriester und der Stadt freundlich aufgenommen, machte er Mitteilung von der ihm gemachten Anzeige, legte den Grund seines Kommens dar und erkundigte sich, ob die Sache sich wirklich so verhalte.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 3, 10, 'Da eröffnete ihm der Hohepriester, daß es sich um hinterlegte Gelder von Witwen und Waisen handle;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 3, 11, 'einiges gehöre auch dem Hyrkanus, dem Sohne des Tobias, einem hochangesehenen Manne; die Sache verhalte sich nicht so, wie der gottlose Simon verleumderisch angegeben habe; das Ganze betrage vielmehr nur 400 Talente Silber und 200 Talente Gold.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 3, 12, 'Es sei aber durchaus unzulässig, daß diejenigen geschädigt würden, welche ihr Vertrauen auf die Heiligkeit der Stätte und auf die Ehrwürdigkeit und Unverletzlichkeit des weltberühmten Tempels gesetzt hätten.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 3, 13, 'Heliodorus aber erklärte auf Grund des königlichen Befehls, den er in Händen hatte, mit aller Bestimmtheit, das Geld müsse in den königlichen Schatz abgeführt werden.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 3, 14, 'Er setzte also einen Tag fest und ging hinein, um die Besichtigung des Tempelschatzes vorzunehmen. Da geriet die ganze Stadt in eine gewaltige Bestürzung:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 3, 15, 'die Priester warfen sich in ihren Priestergewändern vor dem Altar nieder und riefen laut gen Himmel zu dem, der das Gesetz über die anvertrauten Gelder gegeben hatte, er möge die Gelder denen, die sie hinterlegt hätten, unberührt erhalten.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 3, 16, 'Wer die äußere Erscheinung des Hohenpriesters ansah, dem mußte das Herz bluten; denn sein Aussehen und seine veränderte Gesichtsfarbe verrieten die Bestürzung seines Inneren;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 3, 17, 'Furcht und Zittern des ganzen Leibes hatte den Mann ergriffen, wodurch denen, die ihn ansahen, der in seinem Herzen brennende Schmerz offenbar wurde.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 3, 18, 'Die Leute aber stürzten haufenweise aus den Häusern, um gemeinsam zu beten, weil die heilige Stätte in Verachtung zu geraten drohte.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 3, 19, 'Die Frauen füllten die Straßen an, mit Trauergewändern unter der Brust gegürtet; die Jungfrauen, die in den Häusern eingeschlossen waren, liefen teils an die Haustüren, teils auf die Mauern ihres Hofes, teils schauten sie zu den Fenstern hinaus;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 3, 20, 'alle aber sprachen mit zum Himmel erhobenen Händen Gebete aus.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 3, 21, 'Es war ein Jammer zu sehen, wie die ganze Volksmenge durcheinander gemischt sich auf die Kniee warf, und wie der Hohepriester, von gewaltigem Schmerz ergriffen, in banger Erwartung schwebte.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 3, 22, 'Während diese nun den allmächtigen Gott anflehten, daß er die anvertrauten Gelder den Eigentümern in aller Sicherheit unversehrt erhalten wolle,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 3, 23, 'suchte Heliodorus seinen Beschluß zur Ausführung zu bringen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 3, 24, 'Als er aber bereits mit seinem Gefolge an Ort und Stelle in der Schatzkammer stand, ließ der Herr der Väter und der Herrscher über alle Gewalt eine wunderbare Erscheinung eintreten, so daß alle, die sich dort zu versammeln gewagt hatten, von der Macht Gottes betroffen, in eine sie völlig lähmende Verzagtheit gerieten.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 3, 25, 'Es erschien ihnen nämlich ein Pferd, auf dem ein furchtbarer Reiter saß und das mit dem prächtigsten Geschirr geschmückt war; in vollem Lauf heranstürmend, schlug es mit den Vorderhufen auf Heliodorus ein; der auf ihm sitzende Reiter aber glänzte in goldener Rüstung.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 3, 26, 'Noch zwei andere Jünglinge erschienen vor Heliodorus von ausgezeichneter Stärke, in glänzender Schönheit und prächtiger Kleidung; diese traten von beiden Seiten an ihn heran und geißelten ihn unaufhörlich, indem sie ihm viele Schläge versetzten.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 3, 27, 'Da fiel er plötzlich zu Boden und verlor das Bewußtsein völlig; man ergriff ihn und legte ihn auf eine Tragbahre.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 3, 28, 'Denselben Mann, der eben noch mit zahlreichem Gefolge und allen seinen Trabanten in die vorgenannte Schatzkammer eingetreten war, trug man weg, da er sich selbst nicht helfen konnte; alle hatten die Machtbezeugung Gottes klar erkannt.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 3, 29, 'Er aber lag nun da, durch Gottes Eingreifen sprachlos geworden und jeder Hoffnung auf Rettung beraubt.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 3, 30, 'Die Juden aber priesen den Herrn, der seine Stätte so wunderbar verherrlicht hatte; und der Tempel, in dem kurz vorher noch Furcht und Bestürzung geherrscht hatte, war infolge der Erscheinung des allmächtigen Herrn mit Freude und Jubel erfüllt.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 3, 31, 'Sogleich baten nun einige von Heliodorus Freunden den Onias er möge doch den Höchsten anrufen und so dem in den letzten Zügen liegenden Manne das Leben retten.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 3, 32, 'Weil nun der Hohepriester in Besorgnis war, der König könne auf den Gedanken kommen, es sei von den Juden ein Verbrechen an Heliodorus begangen worden, brachte er ein Opfer für die Genesung des Mannes dar.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 3, 33, 'Während nun der Hohepriester das Sühnopfer vollzog, erschienen dem Heliodorus dieselben Jünglinge noch einmal in denselben Gewändern, traten vor ihn hin und sagten: »Statte dem Hohenpriester Onias vielen Dank ab, denn nur aus Rücksicht auf ihn hat der Herr dir das Leben geschenkt.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 3, 34, 'Du aber, der du vom Himmel her die Geißelhiebe erhalten hast, verkünde aller Welt die große Macht Gottes!« Nach diesen Worten verschwanden sie.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 3, 35, 'Heliodorus brachte nun seinerseits dem Herrn ein Opfer dar, verpflichtete sich gegen den Retter seines Lebens zu großen Gelübden, verabschiedete sich freundlich von Onias und kehrte mit seinem Gefolge zum Könige zurück;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 3, 36, 'er bezeugte allen unverhohlen die Wundertaten des höchsten Gottes, die er mit eigenen Augen gesehen habe.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 3, 37, 'Als aber der König ihn fragte, wer wohl dazu geeignet wäre, noch einmal nach Jerusalem gesandt zu werden, erklärte er:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 3, 38, '»Wenn du einen Feind oder einen Gegner deiner Regierung hast, so sende ihn dorthin; du wirst ihn dann mit Geißelhieben zerschlagen zurückerhalten, wenn er überhaupt mit dem Leben davonkommt; denn an jener Stätte waltet in Wahrheit eine göttliche Macht.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 3, 39, 'Denn er selbst, der seine Wohnung im Himmel hat, ist der Wächter und Beschützer jener Stätte, und wenn jemand in böser Absicht dahin kommt, so schlägt er ihn tot.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 3, 40, 'So ist die Sache mit Heliodorus und der Bewahrung des Tempelschatzes verlaufen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 4, 1, 'Der vorhin erwähnte Simon aber, der zum Verräter des Staatsschatzes und seines Vaterlandes geworden war, verleumdete den Onias, als sei er selbst es gewesen, der den Heliodorus tätlich angegriffen und das ganze Unheil angerichtet habe;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 4, 2, 'so erfrechte er sich, den Wohltäter der Stadt, den Fürsorger für seine Volksgenossen und den Eiferer für die Gesetze als Staatsverräter zu bezeichnen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 4, 3, 'Als nun die Feindschaft sich dermaßen steigerte, daß durch einen von Simons Parteigenossen sogar Mordtaten verübt wurden,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 4, 4, 'da erwog Onias das Gefährliche dieser Parteiungen; und da er erfuhr, daß Apollonius, der Statthalter von Cölesyrien und Phönizien, in seiner Wut die Bosheit Simons noch steigerte,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 4, 5, 'begab er sich zum Könige, nicht um seine Mitbürger zu verklagen, sondern weil er auf das Wohl seines Volkes im ganzen wie im einzelnen bedacht war.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 4, 6, 'Denn es war ihm klar, daß ohne Fürsorge der Staatsregierung die öffentliche Ruhe nicht wieder hergestellt werden könne, und daß Simon von seinem Unverstand nicht ablassen würde.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 4, 7, 'Als Seleukus aber mit Tode abgegangen war, und Antiochus mit dem Beinamen Epiphanes die Regierung angetreten hatte, erschlich sich Jason, der Bruder des Onias, die hohenpriesterliche Würde,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 4, 8, 'indem er dem Könige bei einer Unterredung 360 Talente Silber und von einer anderen Einnahme noch 80 Talente versprach.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 4, 9, 'Außerdem verhieß er, sich schriftlich noch für eine andere Summe, nämlich für 150 Talente, verbindlich zu machen, wenn es ihm gestattet würde, aus eigener Macht ein Gymnasium und einen Ringplatz für Jünglinge herzustellen und den Juden in Jerusalem das Bürgerrecht von Antiochien zu verleihen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 4, 10, 'Als nun der König ihm dies bewilligte und er so zur Herrschaft gelangt war, fing er sofort an, bei seinen Landsleuten griechische Sitten einzuführen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 4, 11, 'Er schaffte die für die Juden bestehenden menschenfreundlichen Vorrechte ab, welche die früheren Könige gewährt hatten, und zwar durch Vermittlung des Johannes, des Vaters jenes Eupolemus, der als Gesandter nach Rom geschickt worden war, um dort Freundschaft und ein Waffenbündnis zu schließen. Weiter hob er die gesetzmäßigen Staatseinrichtungen auf und ließ neue ungesetzliche Bräuche an ihre Stelle treten.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 4, 12, 'So erbaute er z.B. ohne Scheu gerade am Fuße der Burg ein Gymnasium und suchte die edelsten Jünglinge zum Tragen des griechischen Hutes zu verleiten.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 4, 13, 'So wurde denn die Vorliebe für die griechischen Sitten und der Übertritt zum ausländischen Wesen infolge der maßlosen Verruchtheit des gottlosen Jason, der gar nichts von einem Hohenpriester an sich hatte, so stark,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 4, 14, 'daß die Priester sich nicht mehr um den Altardienst kümmerten, sondern mit Verachtung des Tempels und unter Vernachlässigung der Opfer sich beeilten, an den gesetzwidrigen Aufführungen von Wettkämpfen auf dem Ringplatze nach der Aufforderung zum Diskuswerfen teilzunehmen;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 4, 15, 'sie achteten eben die Ehren, die bei den Vätern Wert gehabt hatten, für nichts und hielten das, was den Griechen als rühmlich galt, für das Schönste.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 4, 16, 'Darum gerieten sie auch in eine schlimme Lage; denn die, deren Lebensführung sie nacheiferten und denen sie in allen Stücken gleich werden wollten, eben diese bekamen sie zu Feinden und Zwingherren;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 4, 17, 'denn gegen die göttlichen Gesetze zu freveln ist nichts Geringes; das wird ja die Folgezeit klar herausstellen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 4, 18, 'Als man nun die fünfjährigen Kampfspiele zu Tyrus in Gegenwart des Königs feierte,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 4, 19, 'sandte der verruchte Jason Festgesandte, die das antiochische Bürgerrecht besaßen, als Vertreter Jerusalems dahin; diese hatten 300 Drachmen Silbers zu dem Opfer für Herkules zu überbringen. Die Überbringer sprachen jedoch die Bitte aus, man möge das Geld nicht für ein Opfer verwenden, weil sich das nicht schicke, sondern man möge es für einen anderen Zweck verwenden.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 4, 20, 'So war dies Geld also nach der Absicht des Übersenders zu dem Opfer für Herkules bestimmt; aber mit Rücksicht auf die Überbringer wurde es zum Bau von Kriegsschiffen verwendet.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 4, 21, 'Als aber Apollonius, der Sohn des Menestheus, bei Gelegenheit des Regierungsantritts des Königs Ptolemäus Philometor nach Ägypten gesandt worden war und Antiochus erfuhr, daß dieser eine ihm zuwiderlaufende Politik verfolge, so war er auf seine eigene Sicherheit bedacht; er begab sich deshalb nach Joppe und kam dann nach Jerusalem.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 4, 22, 'Hier wurde er von Jason und der Bürgerschaft glänzend empfangen und mit einem Fackelzug und Freudengeschrei bewillkommnet; darauf zog er mit seinem Heere nach Phönizien.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 4, 23, 'Nach Verlauf von drei Jahren entsandte Jason den Menelaus, den Bruder des schon erwähnten Simon, um dem Könige das Geld zu überbringen und mehrere dringende Angelegenheiten zu erledigen, inbetreff derer Mahnungen an ihn gerichtet worden waren.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 4, 24, 'Dieser wußte aber die Gunst des Königs zu gewinnen und verherrlichte ihn durch Lobpreisungen, wobei er sich die Miene eines einflußreichen Mannes gab; so verschaffte er sich denn das Hohepriestertum, indem er den Jason um 300 Talente Silber überbot.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 4, 25, 'Nachdem er nun die königliche Bestätigung erhalten hatte, kehrte er zurück, ohne irgend eine für das Hohepriestertum erforderliche Eigenschaft zu besitzen, und nur mit der Wut eines rohen Tyrannen und dem Grimm eines wilden Raubtieres ausgestattet.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 4, 26, 'So sah sich denn Jason, der einst seinen eigenen Bruder arglistig verdrängt hatte, jetzt ebenso von einem anderen verdrängt und als Flüchtling ins Land der Ammoniter vertrieben.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 4, 27, 'Menelaus befand sich nun zwar im Besitz der Herrschaft, aber von dem Gelde, das er dem Könige versprochen hatte, zahlte er nichts, obschon Sostrates, der Befehlshaber der Burg, ihn darum mahnte;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 4, 28, 'dieser hatte nämlich die Beitreibung der Gelder zu besorgen. Aus diesem Grunde wurden sie beide vom Könige vorgeladen,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 4, 29, 'und Menelaus ließ als seinen Stellvertreter im Hohenpriestertum seinen Bruder Lysimachus zurück, Sostrates aber den Krates, den Obersten der Cyprier.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 4, 30, 'Als die Dinge nun soweit gediehen waren, begab es sich, daß die Einwohner von Tarsus und Mallus sich empörten, weil sie der Antiochis, dem Kebsweibe des Königs, als Geschenk zugewiesen worden waren.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 4, 31, 'In aller Eile hatte sich nun der König an Ort und Stelle begeben, um die Dinge dort in Ordnung zu bringen, und hatte als seinen Stellvertreter den Andronikus zurückgelassen, einen seiner vornehmsten Würdenträger.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 4, 32, 'Da glaubte Menelaus, eine günstige Gelegenheit zu seiner Rettung gefunden zu haben. Er brachte also einige von den Goldgeräten des Tempels auf die Seite und schenkte sie dem Andronikus; bei anderen gelang es ihm, sie nach Tyrus und in die umliegenden Städte zu verkaufen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 4, 33, 'Als Onias dies sicher erfahren hatte, rügt er es scharf, nachdem er sich in eine Freistatt bei Daphne, einem Vorort von Antiochien, zurückgezogen hatte.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 4, 34, 'Daher nahm Menelaus den Andronikus beiseite und forderte ihn auf, den Onias umzubringen. Dieser begab sich also zu Onias, leistete ihm, da ihm die Anwendung einer List empfohlen war, unter Eidschwüren den Handschlag und überredete ihn, obgleich die Sache dem Onias verdächtig erschien, aus der Freistatt herauszukommen, worauf er ihn, ohne alle Scheu vor dem Recht, sofort erstach.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 4, 35, 'Über diese Tat waren nicht nur die Juden, sondern auch viele von den anderen Völkern aufgebracht und über die ruchlose Ermordung des Mannes entrüstet.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 4, 36, 'Als dann der König aus Cilicien zurückgekehrt war, brachten die Juden der Hauptstadt die Anklage bei ihm an, und auch die Griechen bezeugten ihrer Entrüstung über die rechtswidrige Tötung des Onias.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 4, 37, 'Antiochus war über das Geschehene herzlich betrübt; er vergoß Tränen des Mitleids im Hinblick auf die Besonnenheit und hohe Sittenreinheit des Hingeschiedenen;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 4, 38, 'und voller Zorn ließ er sofort dem Andronikus den Purpur abnehmen und die Kleider vom Leibe reißen und ihn dann in der ganzen Hauptstadt herumführen bis an die Stelle, wo er die Schandtat an Onias verübt hatte; dort ließ er den Meuchelmörder hinrichten. So hat der Herr ihm mit der verdienten Strafe vergolten.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 4, 39, 'Weil aber viele Beraubungen des Tempelschatzes in der Stadt (Jerusalem) von Lysimachus unter Mitwissen des Menelaus ausgeführt waren und das Gerücht davon sich auswärts verbreitet hatte, rottete sich das Volk gegen Lysimachus zusammen, nachdem schon viele Goldgeräte verschleppt worden waren.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 4, 40, 'Als nun die Volkshaufen in Aufregung und voller Wut waren, bewaffnete Lysimachus etwa 3000 Mann und fing an, mit Gewalt vorzugehen, wobei ein gewisser Tyrannus, ein Mann von vorgerücktem Alter, nicht minder aber auch von argem Unverstand, die Hauptrolle spielte.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 4, 41, 'Da sie aber sahen, daß Lysimachus sogar einen Angriff ins Werk setzte, griffen die einen nach Steinen, andere nach dicken Holzstangen, einige rafften auch von dem daliegenden Staube zusammen und schleuderten alles durcheinander auf Lysimachus und seine Leute,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 4, 42, 'wodurch sie viele von ihnen verwundeten, einige auch zu Boden schlugen, alle aber in die Flucht trieben und den Tempelräuber selbst bei der Schatzkammer totschlugen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 4, 43, 'Um dieser Vorkommnisse willen wurde eine gerichtliche Untersuchung gegen Menelaus eingeleitet;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 4, 44, 'und als der König nach Tyrus gekommen war, brachten drei Männer, die vom Hohen Rate abgeordnet waren, die Klage bei ihm an.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 4, 45, 'Als nun Menelaus sich bereits überführt sah, versprach er Ptolemäus, dem Sohne des Dorymenes, eine große Summe Geldes, damit er den König ihm günstig stimmen sollte.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 4, 46, 'So nahm denn Ptolemäus den König mit sich in einen Säulengang, als wollte er ihn frische Luft schöpfen lassen, und stimmte ihn um,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 4, 47, 'so daß er den Menelaus, der doch die Schuld an allem Unheil trug, von den Anklagen freisprach, dagegen jene (drei) Ärmsten, die sogar, wenn sie ihre Sache vor einem Gerichtshofe der Scythen geführt hätten, als unschuldig freigesprochen worden wären, zum Tode verurteilte.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 4, 48, 'So mußten denn die Männer, die für die Stadt und die judäischen Gemeinden und für die heiligen Geräte eingetreten waren, alsbald die ungerechte Strafe über sich ergehen lassen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 4, 49, 'Das war auch der Grund, weshalb einige Tyrier aus gerechtem Unwillen über das begangene Verbrechen die Kosten zu einem ehrenvollen Leichenbegängnis für sie hergaben.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 4, 50, 'Menelaus aber blieb infolge der Habgier der Machthaber im Besitz seiner Würde und erwies sich, da es mit seiner Bosheit immer schlimmer wurde, als ein arger Verräter an der Sache seiner Mitbürger.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 5, 1, 'Um diese Zeit nun unternahm Antiochus seinen zweiten Feldzug nach Ägypten.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 5, 2, 'Da begab es sich, daß man fast 40 Tage lang in der ganzen Stadt Reiter in golddurchwirkten Gewändern und mit Lanzen bewaffnet scharenweise durch die Luft stürmen sah;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 5, 3, 'auch ganze Reitergeschwader in Schlachtordnung, Angriffe und Gegenangriffe von beiden Seiten, Schilde, die geschwungen wurden, Lanzen in Menge, gezückte Schwerter, abgeschossene Pfeile waren sichtbar, funkelnde goldene Rüstungen und Harnische von mancherlei Art.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 5, 4, 'Daher beteten alle, daß diese Erscheinung etwas Gutes bedeuten möge.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 5, 5, 'Als sich nun ein falsches Gerücht verbreitete, daß Antiochus gestorben sei, raffte Jason eine Schar von mindestens 1000 Mann zusammen und überfiel die Stadt unversehens. Als die Mannschaften auf den Mauern vertrieben waren und die Einnahme der Stadt schließlich erfolgte, flüchtete sich Menelaus in die Burg;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 5, 6, 'Jason aber richtete erbarmungslos ein Blutbad unter seinen eigenen Mitbürgern an, ohne zu bedenken, daß ein Sieg über Mitbürger das größte Unglück sei; er wähnte vielmehr, Siegeszeichen über Feinde und nicht über Volksgenossen davonzutragen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 5, 7, 'Dennoch gewann er die Herrschaft nicht, sondern trug als Lohn für seinen Anschlag nur Schande davon und mußte als Flüchtling wieder ins Ammoniterland abziehen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 5, 8, 'Nun erreichte ihn das Ende seines frevelhaften Tuns. Bei Aretas, dem arabischen Häuptling, verklagt, floh er von Stadt zu Stadt, von allen verfolgt und als ein vom Gesetz Abtrünniger verabscheut und als Henker seines Vaterlandes und seiner Mitbürger verflucht. So wurde er nach Ägypten vertrieben,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 5, 9, 'und er, der so viele andere aus ihrem Vaterlande verjagt hatte, fand selbst in einem fremden Lande seinen Untergang. Er hatte sich nämlich zu den Lacedämoniern begeben in der Hoffnung, bei ihnen als bei Stammverwandten Schutz zu finden;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 5, 10, 'und er, der so viele unbegraben hatte hinwerfen lassen, blieb selbst unbetrauert und erhielt keinerlei liebevolle Bestattung und kein Grab bei seinen Vätern.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 5, 11, 'Als aber dem Könige die Kunde von dem, was (in Jerusalem) vorgegangen war, zu Ohren kam, meinte er, Judäa wolle abfallen. Er brach daher aus Ägypten auf mit tierischer Wut im Herzen, nahm die Stadt mit Waffengewalt ein');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 5, 12, 'und befahl seinen Kriegern, schonungslos alle niederzumachen, die ihnen in die Hände fielen, ja auch alle abzuschlachten, die in ihrem Hause auf das Dach hinaufgegangen seien.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 5, 13, 'So erfolge denn ein Gemetzel von Jünglingen und Greisen, ein Morden von Männern, Weibern und Kindern, ein Abschlachten von Jungfrauen und Säuglingen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 5, 14, '80000 Menschen gingen im Verlauf von nur drei Tagen zugrunde, nämlich 40000 durch Niedermetzelung, und ebensoviele wurden als Sklaven verkauft.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 5, 15, 'Und damit noch nicht zufrieden, hatte er die Frechheit, in den Tempel einzudringen, in diesen allerheiligsten Ort der Welt, wobei ihm Menelaus als Führer diente, der zum Verräter am Gesetz und am Vaterlande geworden war.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 5, 16, 'Er nahm dort mit seinen unreinen Händen die heiligen Geräte weg und raffte die Weihgeschenke, die von anderen Königen zur Verherrlichung und Ehre der Stätte gestiftet worden waren, mit seinen unheiligen Händen zusammen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 5, 17, 'In der Dünkelhaftigkeit seines Herzens bedachte Antiochus nicht, daß Gott, der Herr, den Bewohnern der Stadt wegen ihrer Sünden für kurze Zeit zürnte und nur deshalb der Stätte eine Entweihung widerfahren war.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 5, 18, 'Wäre es nämlich nicht der Fall gewesen, daß der Ort in vielen Übertretungen befangen war, so würde, ganz wie der vom Könige Seleukus zur Besichtigung der Schatzkammer entsandte Heliodorus, so jetzt auch Antiochus für sein Eindringen sofort mit Geißelhieben gezüchtigt und von seiner Vermessenheit abgebracht worden sein.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 5, 19, 'Aber nicht um des Ortes willen hatte der Herr das Volk, sondern um des Volkes willen hat er den Ort erwählt.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 5, 20, 'Deswegen hat auch der Ort selbst, nachdem er bei den Mißgeschicken des Volkes mitgelitten hatte, nachmals an den Segnungen des Herrn teilgenommen; und während er damals, solange der Zorn des Allmächtigen dauerte, verlassen war, wurde er, als der große Herrscher sich mit seinem Volke versöhnt hatte, wieder in voller Herrlichkeit zu Ehren gebracht.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 5, 21, 'Nachdem nun Antiochus 1800 Talente aus dem Tempel an sich genommen hatte, kehrte er in aller Eile nach Antiochien zurück und war in seinem Hochmut überzeugt, das Land schiffbar und das Meer gangbar machen zu können: solche Selbstüberhebung lebte in seinem Herzen!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 5, 22, 'Er ließ aber auch Aufseher zurück, die das Volk mißhandeln sollten, nämlich in Jerusalem den Philippus, der seiner Abkunft nach ein Phrygier war, aber seiner Sinnesart nach noch grausamer als sein Herr, der ihn eingesetzt hatte;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 5, 23, 'ferner in Garizim den Andronikus und neben diesen den Menelaus, der sich am schlimmsten, noch hochmütiger als die anderen, gegen die Bürger benahm und gegen seine jüdischen Mitbürger geradezu feindselig gesinnt war.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 5, 24, 'Er schickte auch den Erzbösewicht Apollonius (als Obersteuererheber) mit einem Heere von 22000 Mann ins Land, mit dem Befehl, alle Erwachsenen niederzumachen, die Weiber und Kinder aber als Sklaven zu verkaufen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 5, 25, 'Dieser Mann trug nach seiner Ankunft in Jerusalem die Miene des Friedfertigen zur Schau und hielt bis zum heiligen Sabbattage an sich, ließ dann aber, da er die Juden in der Feier des Ruhetages antraf, seine Leute unter die Waffen treten');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 5, 26, 'und alle, die zum Gottesdienst herausgekommen waren, zusammen niedermachen; darauf stürmte er mit den Waffen in die Stadt hinein und streckte eine große Menge Leute tot nieder.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 5, 27, 'Judas Makkabäus aber war mit neun anderen in die Wüste entwichen und lebte dort mit den Seinen nach Art der wilden Tiere in den Bergen; sie fristeten ihr Leben ununterbrochen mit Pflanzenkost, um sich nicht wie die anderen beflecken zu müssen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 6, 1, 'Nicht lange nachher sandte der König einen alten Athener, um die Juden zu zwingen, von den väterlichen Sitten abzufallen und nicht mehr nach den Gesetzen Gottes zu leben;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 6, 2, 'auch sollte er den Tempel zu Jerusalem entweihen und ihn nach dem Olympischen Zeus benennen, und ebenso den Tempel zu Garizim nach dem Gastlichen Zeus, wie das ja der gastfreundlichen Art der Ortsbewohner entspräche.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 6, 3, 'Diese Steigerung der Bosheit war selbst für das gewöhnliche Volk unerträglich und widerwärtig;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 6, 4, 'denn der Tempel war jetzt angefüllt mit Schwelgerei und Gelagen durch die Heiden, die dort mit Buhlerinnen Unzucht trieben und in den heiligen Vorhöfen sich mit Weibern abgaben, dazu auch vielerlei ungebührliche Dinge hineinschafften.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 6, 5, 'Der Brandopferaltar wurde mit unzulässigen, vom Gesetz verbotenen Opfern beladen,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 6, 6, 'und weder fand eine Sabbatfeier statt, noch die Beobachtung der herkömmlichen Feste; ja, es war sogar unstatthaft, sich äußerlich zum Judentum zu bekennen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 6, 7, 'Dagegen trieb man sie mit roher Gewalt alle Monate, wenn der Geburtstag des Königs gefeiert wurde, zum Opferschmause; und bei der Feier des Bakchusfestes sahen die Juden sich gezwungen, mit Epheu bekränzt am Festzuge zu Ehren des Bakchus teilzunehmen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 6, 8, 'Auf Betreiben des Ptolemäus erging auch ein Befehl an die benachbarten griechischen Städte, daß sie das gleiche Verfahren gegen die Juden beobachten und sie zur Teilnahme an den Opferschmäusen zwingen sollten;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 6, 9, 'alle aber, die den Übertritt zum Griechentum verweigerten, die solle man hinrichten. Da konnte man nun sehen, welch ein Elend damals herrschte.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 6, 10, 'Zwei Frauen z.B. wurden vorgeführt, die ihre Söhne beschnitten hatten; man hängte ihnen nun die Kindlein an die Brüste, führte sie dann öffentlich durch die Stadt und stürzte sie schließlich von der Mauer hinab.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 6, 11, 'Andere, die in nahe gelegene Höhlen zusammengelaufen waren, um den siebenten Tag heimlich zu begehen, wurden dem Philippus verraten und zusammen verbrannt; sie hatten Scheu gehegt, sich bei der Würde des hochheiligen Tages zu verteidigen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 6, 12, 'Ich ermahne nun alle, denen dies Buch in die Hände kommen mag, sich durch diese Unglücksfälle nicht erschrecken zu lassen, sondern diese Strafgerichte zu betrachten als Zuchtmittel für unser Volk, nicht als zu dessen Vernichtung bestimmt;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 6, 13, 'denn darin, daß die Gottlosen nicht lange Zeit ungestraft bleiben, sondern gar bald der Vergeltung anheimfallen, liegt für uns ein Zeichen großer (göttlicher) Gnade.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 6, 14, 'Denn nicht so, wie der Herr in seiner Langmut bei den anderen Völkern mit der Strafe so lange wartet, bis sie das Maß ihrer Sünden vollgemacht haben, hatte der Herr beschlossen, auch mit uns zu verfahren,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 6, 15, 'damit er nicht, wenn wir den Höhepunkt der Sündhaftigkeit erreicht hätten, dann zuletzt das Strafgericht an uns vollzöge.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 6, 16, 'Darum entzieht er uns niemals sein Erbarmen, und mag er uns auch durch Unglück züchtigen, so verläßt er doch sein Volk niemals.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 6, 17, 'Doch zur Ermahnung sei dies uns gesagt; und nun müssen wir nach dieser kurzen Abschweifung wieder zu unserer Erzählung zurückkehren.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 6, 18, 'Eleasar, einer der vornehmsten Schriftgelehrten, ein hochbejahrter, aber ungewöhnlich schöner Mann, wurde gezwungen, mit gewaltsam aufgesperrtem Munde Schweinefleisch zu essen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 6, 19, 'Da er aber einen rühmlichen Tod einem Leben in Schande vorzog, spie er das Fleisch wieder aus und schritt dann freiwillig zur Marterbank hin,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 6, 20, 'wie es allen denen zu tun geziemt, die den Mut besitzen, ohne Rücksicht auf ihre starke Liebe zum Leben sich des Genusses verbotener Kost zu enthalten.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 6, 21, 'Diejenigen aber, welche zu Aufsehern über den gottlosen Opferschmaus bestellt worden waren, nahmen diesen Mann, den sie seit langer Zeit kannten, beiseite und redeten ihm zu, er möge sich Fleisch bringen lassen, dessen Genuß ihm erlaubt sei und das er selbst sich zubereitet habe, indem er sich stellte, als äße er das vom Könige verordnete Opferfleisch,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 6, 22, 'damit er auf diese Weise dem Tode entginge und wegen der alten Freundschaft mit ihnen eine menschenfreundliche Behandlung erführe.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 6, 23, 'Er aber faßte einen edlen Entschluß, wie er seiner Jahre würdig war und der Würde seines hohen Alters und des herrlichen grauen Haares, das ihn schmückte, und des tugendhaften Wandels, den er von Jugend auf geführt hatte, vornehmlich aber in Übereinstimmung stand mit dem heiligen, von Gott gestifteten Gesetz, und gab sofort die Erklärung ab, man möge ihn in die Unterwelt schicken.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 6, 24, '»Denn«, sagte er, »es wäre meines Alters unwürdig zu heucheln, weil dadurch viele von den jüngeren Leuten, in der Meinung, der neunzigjährige Eleasar sei zum Heidentum übergetreten,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 6, 25, 'ebenfalls wegen meiner Heuchelei und im Hinblick auf die Kürze und Vergänglichkeit des Lebens durch meine Schuld verführt würden; ich würde ja dadurch meinem hohen Alter sicherlich Schimpf und Schande zuziehen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 6, 26, 'Denn wenn ich mich auch für den Augenblick der Bestrafung durch Menschen entzöge, so könnte ich doch den Händen des Allmächtigen weder lebend noch tot entgehen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 6, 27, 'Darum will ich jetzt mannhaft das Leben lassen und mich meines Alters würdig erweisen,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 6, 28, 'und will dadurch den jüngeren Leuten ein edles Beispiel hinterlassen, wie man freudig und hochherzig für die ehrwürdigen und heiligen Gesetze einen ehrenvollen Tod erleiden soll«. Nach diesen Worten schritt er sofort zu dem Marterwerkzeug hin.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 6, 29, 'Da nun die Männer, die ihn abführten, das eben noch ihm bewiesene Wohlwollen in Übelwollen umschlagen ließen, weil sie die soeben von ihm ausgesprochenen Worte für Torheit hielten,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 6, 30, 'sprach er, als er unter ihren Schlägen dem Tode nahe war, mit einem Seufzer noch die Worte aus: »Dem Herrn, der das heilige Wissen besitzt, dem ist es wohlbekannt, daß ich vom Tode hätte loskommen können und daß ich an meinem Leibe zwar die grausamen Schmerzen der Geißelung erdulde, in meinem Geiste aber dieses gern aus Ehrfurcht vor ihm ertrage«.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 6, 31, 'So starb dieser Mann, indem er nicht nur den jüngeren Leuten, sondern auch der Mehrzahl des Volkes seinen Tod als ein Beispiel edler Gesinnung und als ein Denkmal seiner Seelenstärke hinterließ.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 1, 'Es begab sich auch, daß sieben Brüder samt ihrer Mutter ergriffen wurden und vom Könige gezwungen werden sollten, von dem durch das Gesetz verbotenen Schweinefleisch zu essen, indem sie mit Geißeln und Riemen gepeitscht wurden.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 2, 'Der eine aber von ihnen nahm das Wort für die anderen und sagte: »Was willst du von uns erfragen und erfahren? Wir sind ja doch bereit, lieber zu sterben als die väterlichen Gesetze zu übertreten«.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 3, 'Da befahl der König, außer sich vor Zorn, Pfannen und Kessel glühend zu machen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 4, 'Als das geschehen war, ließ er sofort dem, der als ihr Wortführer aufgetreten war, die Zunge ausschneiden, ihm die Kopfhaut abziehen und die Hände und Füße abhauen, wobei die übrigen Brüder und die Mutter zusehen mußten.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 5, 'Den so ganz Verstümmelten, aber noch Lebenden, ließ er dann ans Glutfeuer bringen und in der Pfanne braten. Während aber der Dampf sich aus der Pfanne weithin verbreitete, ermahnten sie sich untereinander samt der Mutter, mutig zu sterben, indem sie sagten:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 6, '»Gott der Herr sieht es und erbarmt sich unser gewißlich, wie Mose es in seinem rückhaltlos gegen Israel gerichteten Liede klar mit den Worten ausgesprochen hat: ›Über seine Diener wird er sich erbarmen‹«.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 7, 'Als nun der erste auf diese Weise den Tod erlitten hatte, führte man den zweiten zur Marter, und nachdem man ihm die Haut samt den Haaren vom Kopfe abgerissen hatte, fragte man ihn: »Willst du essen, ehe dir der Leib Glied für Glied gemartert wird?«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 8, 'Als er in seiner Muttersprache mit »Nein!« geantwortet hatte, erlitt er die gleichen Qualen der Reihe nach wie der erste.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 9, 'Als er dann in den letzten Zügen lag, rief er: »Du, Verfluchter, nimmst uns jetzt zwar das zeitliche Leben, aber der König der Welt wird uns, die wir für sein Gesetz sterben, zu ewigem Leben wieder auferstehen lassen!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 10, 'Nach diesem wurde der dritte gemartert, und als man die Zunge von ihm verlangte, streckte er sie sogleich heraus und hielt die Hände mutig hin;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 11, 'darauf sagte er mannhaft: »Vom Himmel habe ich diese Glieder empfangen; ich gebe sie hin um seines Gesetzes willen, und vom Himmel hoffe ich sie wieder zu erhalten«,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 12, 'so daß selbst der König und seine Umgebung über den Mut dieses Jünglings staunten, der die Schmerzen für nichts achtete.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 13, 'Als dieser nun den Tod erlitten hatte, marterte und peinigte man den vierten auf dieselbe Weise.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 14, 'Als es dann mit ihm zum Sterben ging, rief er aus: »Es ist trostreich, wenn man durch die Hand der Menschen stirbt, sich an Gottes Verheißungen zu halten und zu hoffen, von ihm wieder auferweckt zu werden; dir jedoch wird keine Auferstehung zum Leben zuteil werden!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 15, 'Gleich darauf führten sie den fünften herbei und begannen ihn zu martern.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 16, 'Er aber blickte den König an und sagte: »Unter den Menschen besitzest du Macht, und obgleich sterblich, tust du, was du willst; bilde dir aber nicht ein, daß unser Volk von Gott verlassen sei.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 17, 'Warte nur! du wirst seine große Macht erfahren, wie er dich und dein Geschlecht strafen wird!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 18, 'Nach diesem führten sie den sechsten herbei, der sterbend ausrief: »Gib dich keinem eitlen Irrtum hin! Wir (Juden) leiden so durch eigene Schuld, weil wir gegen unsern Gott gesündigt haben; darum sind so befremdliche Dinge eingetreten.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 19, 'Rechne du aber nicht darauf, ungestraft zu bleiben, nachdem du gewagt hast, gegen Gott zu streiten!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 20, 'Ganz besonders bewundernswert aber und eines ruhmvollen Andenkens würdig war die Mutter, welche sieben Söhne an einem Tage sterben sehen mußte und diese Heimsuchung mutvoll ertrug, weil sie ihre ganze Hoffnung auf Gott setzte.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 21, 'Jedem von ihnen sprach sie in der Landessprache Mut zu, voll edler Gesinnung; und, indem sie weibliche Gemütsart durch männlichen Mut zu voller Wirkung brachte, sagte sie zu ihnen:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 22, '»Ich weiß nicht, wie ihr in meinem Leibe zur Entstehung gekommen seid, und nicht ich bin es gewesen, die euch den Odem und das Leben gegeben hat, und nicht ich habe die Bestandteile eines jeden von euch kunstvoll zusammengefügt.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 23, 'Darum wird auch der Schöpfer der Welt, der des Menschen Entstehung gewirkt und den Ursprung aller Dinge geschaffen hat, euch nach seiner Barmherzigkeit den Odem und das Leben wiedergeben, weil ihr euch heute opfert um seiner Gesetze willen«.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 24, 'Da nun Antiochus meinte, er werde von ihr verachtet, und den Argwohn hegte, sie schmähe ihn in ihrer Sprache, so redete er dem Jüngsten, der allein noch übrig war, nicht nur mit freundlichen Worten zu, sondern versicherte ihm sogar mit einem Eid, er wolle ihn reich und glücklich machen, wenn er vom Gesetz seiner Väter abfiele, ja, er wolle ihn unter die Zahl seiner Freunde aufnehmen und ihm Staatsämter anvertrauen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 25, 'Als aber der Jüngling darauf gar nicht achtete, ließ der König die Mutter rufen und forderte sie auf, ihrem Kinde einen guten Rat zu geben, damit er am Leben bliebe.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 26, 'Da er sehr in sie drang, versprach sie endlich, ihren Sohn zu überreden,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 27, 'neigte sich zu ihm und redete ihn in der Landessprache in der Weise an, daß sie den grausamen Tyrannen verhöhnte: »Mein Sohn, erbarme dich meiner! Ich habe dich neun Monate lang unter meinem Herzen getragen und dich drei Jahre lang gesäugt, habe dich dann ernährt, gepflegt und bis zu deinem jetzigen Alter auferzogen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 28, 'Ich bitte dich, mein Kind, erhebe deine Augen, schaue den Himmel an, die Erde und alles, was darauf ist, bedenke, daß Gott dies alles aus dem Nichts erschaffen hat und wie er dies auch mit dem Menschengeschlechte getan hat.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 29, 'Fürchte dich nicht vor diesem Henker, sondern erweise dich deiner Brüder würdig! Dulde den Tod, damit ich dich am Tage des Erbarmens mit deinen Brüdern wiedergewinne!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 30, 'Während sie noch zu ihm redete, sagte der Jüngling: »Worauf wartet ihr noch? Ich gehorche dem Befehle des Königs nicht; ich gehorche dem Gesetz, das unseren Vätern durch Mose gegeben worden ist.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 31, 'Du aber, der du alle diese Grausamkeiten gegen die Hebräer ausgedacht hast, wähne nicht, den Händen Gottes entrinnen zu können!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 32, 'Wir nämlich leiden um unserer eigenen Sünden willen;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 33, 'wenn nun auch der lebendige Gott, um uns zu strafen und zu bessern, uns für kurze Zeit zürnt, so wird er sich doch mit seinen Dienern wieder versöhnen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 34, 'Du aber, verruchter und abscheulichster aller Menschen, laß dich nicht in deinem Trotz durch eine eitle Hoffnung täuschen, wenn du deine Hand gegen die himmlischen Diener erhebst.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 35, 'Du bist der Rache des Allmächtigen noch nicht entgangen, der alles sieht.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 36, 'Denn unsere Brüder sind jetzt, nachdem sie eine kurze Qual erduldet haben, des ewigen Lebens, der Bundesverheißung Gottes, teilhaftig geworden; du aber wirst, von Gott gerichtet, durch gerechte Strafe für deinen Übermut büßen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 37, 'Ich gebe jetzt, ebenso wie meine Brüder, Leib und Leben für unsere väterlichen Gesetze dahin, indem ich Gott anrufe, er wolle sich bald seinem Volke wieder gnädig erweisen und dich durch Qualen und Martern zu dem Bekenntnis bringen, daß er allein Gott sei.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 38, 'Der Allmächtige wolle auch geben, daß sein Zorn, der über unser ganzes Volk mit Recht ergangen ist, bei mir und meinen Brüdern zur Ruhe komme!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 39, 'Außer sich vor Zorn, behandelte der König diesen noch grausamer als die anderen, weil er durch dessen Verhöhnung erbittert war;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 40, 'und so starb auch dieser im vollen Vertrauen auf den Herrn, ohne sich verunreinigt zu haben.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 41, 'Zuletzt, nach ihren Söhnen, wurde auch die Mutter hingerichtet. Soviel sei mitgeteilt über die Opferschmäuse und die greuelvollen Martern.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 42, '');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 8, 1, 'Judas Makkabäus aber und seine Genossen begaben sich auf Nebenwegen heimlich in die Ortschaften, ermutigten ihre Landsleute, nahmen diejenigen mit sich, welche dem Judentum treu geblieben waren, und brachten so ungefähr 6000 Mann zusammen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 8, 2, 'Sie riefen den Herrn an, er wolle sein von allen zertretenes Volk gnädig ansehen, sich des von den Heiden entweihten Tempels erbarmen;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 8, 3, 'auch der zugrunde gehenden Hauptstadt möge er sich annehmen, die bald gänzlich dem Erdboden gleichgemacht werden solle; er wolle auch das zu ihm schreiende Volk erhören');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 8, 4, 'und der ungerechten Ermordung unschuldiger Kinder gedenken, auch die gegen seinen Namen ausgestoßenen Lästerungen bestrafen und seinen Haß gegen alles Böse offen an den Tag legen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 8, 5, 'Sobald der Makkabäer seine Schar beisammen hatte, wurde er für die Heiden unüberwindlich, weil der Zorn des Herrn sich in Erbarmen verwandelt hatte.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 8, 6, 'Unversehens überfiel er Städte und Dörfer und zündete sie an; die Orte, die ihm gelegen in den Wurf kamen, nahm er ein, besiegte die Feinde in nicht geringer Zahl und trieb sie in die Flucht.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 8, 7, 'Er wählte hauptsächlich die Nächte zum Behuf solcher Unternehmungen, und der Ruf von seiner Tapferkeit verbreitete sich überallhin.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 8, 8, 'Als nun Philippus sah, daß der Mann in kurzer Zeit solche Fortschritte machte und daß seine Erfolge im Kriege immer größer wurden, schrieb er an Ptolemäus, den Statthalter von Cölesyrien und Phönizien, um ihn aufzufordern, für die Sache des Königs einzutreten.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 8, 9, 'Dieser wählte sofort den Nikanor des Patroklus Sohn, einen der vornehmsten Vertrauten des Königs, übergab ihm den Befehl über ein Heer von wenigstens 20000 Mann aus allen Volksstämmen, um das jüdische Volk auszurotten. Zum Gehilfen gab er ihm einen gewissen Gorgias, einen erprobten Kriegsobersten.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 8, 10, 'Nikanor gedachte nun aus dem Verkauf gefangener Juden den vollen Betrag von 2000 Talenten aufzubringen, die der König als Tribut den Römern zu zahlen hatte.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 8, 11, 'Er schickte daher ohne Verzug Boten in die Seestädte und ließ dort zum Ankauf jüdischer Sklaven auffordern, indem er versprach, je neunzig Stück für ein Talent abzugeben; er ahnte die Strafe nicht, die ihn bald vom Allmächtigen treffen sollte.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 8, 12, 'Als nun die Kunde vom Anmarsch Nikanors an Judas gelangte und er seinen Leuten Mitteilung vom Anzuge des Heeres gemacht hatte,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 8, 13, 'da liefen die Feigherzigen und diejenigen, denen das Vertrauen auf Gottes Gerechtigkeit fehlte, davon und brachten sich anderswo in Sicherheit.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 8, 14, 'Die anderen aber verkauften alles, was sie an Habe noch besaßen, und baten zugleich den Herrn, er möge sie retten, die der gottlose Nikanor schon vor dem Kampfe verkauft hätte;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 8, 15, 'und wenn er es nicht um ihretwillen tun wolle, so möge er es doch um der Bündnisse willen tun, die er mit ihren Vätern geschlossen hätte, und um seines ehrwürdigen und hochherrlichen Namens willen, nach dem sie genannt seien.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 8, 16, 'Als nun Makkabäus seine Leute versammelt hatte – es waren ihrer 6000 – ermahnte er sie, vor dem Feinde sich nicht zu fürchten und sich nicht erschrecken zu lassen durch die große Zahl der Heiden, die wider alles Recht gegen sie heranzögen, sondern tapfer zu kämpfen,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 8, 17, 'indem sie des frevelhaften Übermuts gedächten, der an der heiligen Stätte verübt worden sei, und der Mißhandlungen, welche die verhöhnte Stadt hätte erdulden müssen, und außerdem der Abschaffung ihrer von den Vorfahren überlieferten Verfassung.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 8, 18, '»Sie«, sagte er, »verlassen sich auf ihre Waffen und auch auf ihre Kühnheit, wir aber setzen unser Vertrauen auf den allmächtigen Gott, der die gegen uns Heranziehenden und die ganze Welt mit einem Winke vernichten kann«.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 8, 19, 'Er erinnerte sie auch an die wunderbaren Hilfeleistungen, die ihren Vorfahren zuteil geworden seien, und wie die 185000 Mann unter Sanherib zugrunde gegangen wären,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 8, 20, 'und an die Schlacht, die in Babylonien den Galliern geliefert worden sei, wo im ganzen nur 8000 Juden mit 4000 Mazedoniern gegen jene kämpften, und wo die 8000, als die Mazedonier in Bedrängnis waren, 120000 Feinde unter dem Beistand des Himmels erschlugen und reiche Beute machten.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 8, 21, 'Nachdem er ihnen so Mut gemacht hatte und sie bereit waren, für Gesetz und Vaterland zu sterben, teilte er seine Schar in vier Abteilungen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 8, 22, 'Er setzte auch seine Brüder Simon, Joseph und Jonathan zu Anführern je einer Abteilung ein, indem er jedem von ihnen 1500 Mann zuwies;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 8, 23, 'ferner ließ er den Eleasar die heilige Schrift vorlesen, gab die Losung aus: »Mit Gottes Hilfe!«, stellte sich dann selbst an die Spitze der ersten Abteilung und griff den Nikanor an.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 8, 24, 'Und da der Allmächtige mit seiner Hilfe bei ihnen war, machten sie von den Feinden mehr als 9000 nieder, verwundeten und verstümmelten den größten Teil der Leute Nikanors und zwangen sie alle zur Flucht.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 8, 25, 'Den Männern, die zum Ankauf der von ihnen in Gefangenschaft Geratenen gekommen waren, nahmen sie das Geld ab, verfolgten dann die Fliehenden weithin und standen erst davon ab, als die Stunde sie dazu zwang;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 8, 26, 'es war nämlich der Tag vor dem Sabbat; aus diesem Grunde setzten sie die Verfolgung der Fliehenden nicht länger fort.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 8, 27, 'Nachdem sie noch die Waffen aufgelesen und die Beute den Feinden abgenommen hatten, feierten sie den Sabbat, priesen und segneten den Herrn von ganzem Herzen, der sie diesen Tag hatte erleben lassen und wieder angefangen hatte, ihnen seine Gnade zuzuwenden.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 8, 28, 'Nach dem Sabbat teilten sie von der Beute den Geplünderten, sowie den Witwen und Waisen mit, das Übrige verteilten sie unter sich und ihre Kinder.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 8, 29, 'Nachdem sie dies zur Ausführung gebracht hatten, hielten sie ein gemeinsames Gebet ab und baten den barmherzigen Herrn, er wolle sich völlig mit seinen Knechten versöhnen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 8, 30, 'Auch im Kampfe mit den Heerscharen des Timotheus und Bakchides erschlugen sie mehr als 20000 Mann und bemächtigten sich auch überaus stark befestigter Plätze; sodann verteilten sie die ungewöhnlich reiche Beute, indem sie gleichgroße Teile für sich und für die durch die Verfolgung Geschädigten, sowie für die Witwen und Waisen, dazu auch noch für die alten Personen herstellten.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 8, 31, 'Die Waffen, welche sie zusammengelesen hatten, legten sie sorgfältig an geeigneten Orten nieder; die übrige Beute brachten sie nach Jerusalem.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 8, 32, 'Den Phylarches aber, einen Mann aus der Umgebung des Timotheus, töteten sie, einen ganz ruchlosen Mann, der den Juden viel Böses zugefügt hatte.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 8, 33, 'Als sie dann das Siegesfest in der Landeshauptstadt begingen, verbrannten sie den Kallisthenes und einige andere, die einst Feuer an die heiligen Tore gelegt und sich jetzt in ein kleines Haus geflüchtet hatten, so daß sie den wohlverdienten Lohn für ihre Gottlosigkeit empfingen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 8, 34, 'Der Erzbösewicht Nikanor aber, der die tausend Handelsleute herbeigeführt hatte, damit er ihnen die Juden verkaufe,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 8, 35, 'er wurde mit des Herrn Hilfe von denen gedemütigt, die er so gering geschätzt hatte. Er legte sein Prachtgewand ab und kam einsam wie ein entlaufener Sklave mitten durch das Land nach Antiochien, tief betrübt über die Vernichtung seines Heeres;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 8, 36, 'und er, der sich vermessen hatte, durch den Verkauf jüdischer Gefangener die Summe aufzubringen, welche nötig war, um den Tribut an die Römer zu zahlen, der mußte jetzt verkünden, daß die Juden einen Gott hätten, der für sie streite, und daß die Juden aus dem Grunde unüberwindlich seien, weil sie die ihnen verordneten Gesetze beobachteten.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 9, 1, 'Um diese Zeit begab es sich, daß Antiochus seinen unrühmlichen Rückzug aus den zu Persien gehörenden Ländern angetreten hatte.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 9, 2, 'Er war nämlich nach der Stadt namens Persepolis gezogen in der Absicht, den dortigen Tempel zu plündern und die Stadt zu behalten. Als nun infolgedessen die Einwohner sich in Menge erhoben und entschlossen zu den Waffen griffen, begab es sich, daß der König von den Eingeborenen geschlagen wurde und einen schimpflichen Rückzug antreten mußte.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 9, 3, 'Als er dann in Ekbatana war, traf die Meldung bei ihm ein, wie schlimm es dem Nikanor und dem Heere des Timotheus ergangen sei.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 9, 4, 'Dadurch in Wut versetzt, nahm er sich vor, die Juden den Schimpf, den sie ihm durch seine Besiegung angetan hatten, entgelten zu lassen, und befahl daher seinem Wagenlenker, ohne Rast zu jagen und die Fahrt zu Ende zu bringen, während doch das Strafgericht vom Himmel her bereits über seinem Haupte schwebte. Denn so hatte er in seinem Übermut gesprochen: »Zum Totenacker der Juden will ich Jerusalem machen, wenn ich dorthin komme!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 9, 5, 'Aber der Herr, der alles sieht, der Gott Israels, schlug ihn mit einer unsichtbaren und unheilbaren Krankheit. Kaum hatte er zu reden aufgehört, so wurde er von unerträglichen Schmerzen in den Gedärmen ergriffen und von grausamen Qualen im Leibe,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 9, 6, 'ganz mit Recht; er hatte ja andere Leute viele und unerhörte Martern im Inneren erdulden lassen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 9, 7, 'Dennoch ließ er seinen maßlosen Stolz keineswegs fahren, sondern war immer noch voller Hochmut und schnaubte Feuer und Flammen in seiner Wut gegen die Juden und befahl, die Fahrt zu beschleunigen. Da geschah es, daß sein Wagen, der sausend dahinrollte, umschlug, so daß er einen schweren Fall tat, durch den alle seine Glieder verrenkt wurden;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 9, 8, 'und der Mann, der soeben in seinem übermenschlichen Hochmut gemeint hatte, den Wellen des Meeres gebieten und die hohen Berge auf der Wagschale wägen zu können, war jetzt, zu Boden geworfen, in die Notlage versetzt, sich in einer Sänfte tragen zu lassen, für alle ein klarer Beweis der Macht Gottes.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 9, 9, 'Es kam so weit, daß aus dem Leibe dieses gottlosen Menschen Würmer in Menge hervorwuchsen und ihm bei lebendigem Leibe das Fleisch stückweise unter grausamen Schmerzen abfiel und das ganze Heer von dem unerträglichen Gestank der Fäulnis belästigt wurde.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 9, 10, 'Und ihn, der jüngst noch wähnte, die Sterne am Himmel erreichen zu können den konnte jetzt niemand mehr tragen wegen der unerträglichen Beschwerde des Gestanks.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 9, 11, 'Jetzt endlich fing der schwer Geplagte an, den größten Teil seines Hochmuts fahren zu lassen und zu richtiger Erkenntnis zu kommen, da er durch die Rute Gottes von Schmerzen gemartert wurde, die jeden Augenblick zunahmen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 9, 12, 'Und als er selbst den Gestank nicht mehr ertragen konnte, da erklärte er: »Es ist recht, daß man sich Gott unterwirft und als sterblicher Mensch sich nicht vermißt, Gott gleich zu stehen«.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 9, 13, 'Nun betete der Verruchte zu dem Herrn, der sich seiner nicht mehr erbarmen wollte, und gelobte,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 9, 14, 'er wolle die heilige Stadt, auf die er loseilte, um sie dem Erdboden gleich zu machen und in einen Totenacker für die Juden umzuwandeln, für frei erklären');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 9, 15, 'und wolle die Juden, die er doch nicht einmal eines Begräbnisses für wert gehalten, vielmehr samt ihren Kindern den wilden Tieren und Raubvögeln zum Fraß hinzuwerfen beschlossen hatte, ebenso frei machen wie die Bürger von Athen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 9, 16, 'Weiter gelobte er, den heiligen Tempel, den er doch vormals geplündert hatte, mit den schönsten Weihgeschenken zu schmücken und alle heiligen Gefäße vielfach vermehrt wiederzuerstatten und aus eigenen Mitteln die Kosten zu den Opfern herzugeben;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 9, 17, 'ja, er wolle selbst ein Jude werden und in der ganzen Welt herumreisen, um die Macht Gottes zu verkünden.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 9, 18, 'Da aber die Schmerzen durchaus nicht nachließen, weil das gerechte göttliche Strafgericht über ihn gekommen war, und er alle Hoffnung auf Genesung aufgab, schrieb er an die Juden den hier beigefügten Brief, der als eine Abbitte gelten kann und folgendermaßen lautete:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 9, 19, '»Der König und Kriegsherr Antiochus wünscht den wackeren Juden, seinen Mitbürgern, viel Heil, Gesundheit und Wohlergehen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 9, 20, 'Wenn ihr nebst euren Kindern euch wohl befindet und eure Angelegenheiten euch nach Wunsch gehen, so sage ich Gott den größten Dank dafür und setze meine Hoffnung auf den Himmel.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 9, 21, 'Was aber mich betrifft, so liege ich hier krank danieder; eurer Achtung und Zuneigung gedenke ich in Liebe. Da ich bei meiner Rückkehr aus den persischen Landen in eine schwere Krankheit gefallen bin, so halte ich es für notwendig, für die allgemeine Wohlfahrt zu sorgen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 9, 22, 'Zwar verzweifle ich noch nicht an meinem Aufkommen, ich habe vielmehr gute Hoffnung, von dieser Krankheit zu genesen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 9, 23, 'Indessen, da ich in Betracht ziehe, daß auch mein Vater, als er seinen Feldzug nach den oberen Gegenden unternahm, seinen Nachfolger bezeichnet hat,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 9, 24, 'damit im Falle eines unerwarteten Ereignisses oder bei einer schlimmen Nachricht die Einwohner wüßten, an wen die Regierung übergehen solle, und nicht in Unruhe gerieten,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 9, 25, 'und da ich auch bemerke, daß die benachbarten und an unser Reich angrenzenden Herrscher auf den günstigen Augenblick warten, bis sie erfahren, wie es mit mir abgelaufen sei, so bezeichne ich hiermit als König meinen Sohn Antiochus, den ich schon oft bei Gelegenheiten meiner Heerzüge in die oberen Provinzen den meisten von euch anvertraut und empfohlen habe. Ich habe an ihn den beigefügten Brief geschrieben.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 9, 26, 'Ich bitte euch also inständig, daß ihr euch der Wohltaten erinnern wollt, die ich euch sowohl im allgemeinen als im besonderen erwiesen habe, und daß ihr allesamt mir und meinem Sohne euer Wohlwollen weiterhin bewahrt;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 9, 27, 'denn ich bin überzeugt, daß er meine Grundsätze befolgen und mit euch gütige und freundliche Verhältnisse unterhalten wird«.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 9, 28, 'So endigte dieser Menschenmörder und Gotteslästerer sein Leben in schrecklichen Leiden, wie er selbst sie anderen zugefügt hatte, in einem fremden Lande, im Gebirge, durch einen jammervollen Tod.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 9, 29, 'Sein Jugendfreund Philippus besorgte seine Bestattung; da dieser aber den Sohn des Antiochus fürchtete, begab er sich nach Ägypten zu Ptolemäus Philometor.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 10, 1, 'Der Makkabäer aber und seine Genossen nahmen unter der hilfreichen Führung des Herrn die Hauptstadt und den Tempel wieder in Besitz');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 10, 2, 'und zerstörten die Altäre, welche die Heiden auf dem Marktplatze errichtet hatten, und beseitigten die Götzenhaine;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 10, 3, 'und nachdem sie den Tempel wieder geweiht hatten, erbauten sie einen anderen Altar; sie machten Steine glühend, denen sie Feuer entnahmen, und brachten ein Opfer dar, das erste nach einer Unterbrechung von zwei Jahren; auch richteten sie das Räucherwerk, den Leuchter und die Schaubrote wieder her.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 10, 4, 'Nachdem das alles geschehen war, warfen sie sich zur Erde nieder und baten den Herrn, er wolle sie nicht mehr in solches Unglück geraten lassen, sondern sie gelinde züchtigen, wenn sie etwa sündigen sollten, und möge sie nicht wieder gottlästernden und rohen Heiden preisgeben.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 10, 5, 'Es traf sich aber, daß der Tag, an dem man die Tempelweihe vornahm, derselbe war, an welchem er von den Heiden entweiht worden war, nämlich der 25. Tag des Monats Kislev.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 10, 6, 'Dann feierten sie ein achttägiges Freudenfest nach Art der Laubhütten, indem sie sich erinnerten, wie sie noch kurz zuvor während des Laubhüttenfestes auf den Bergen und in Höhen gehaust hatten gleich wilden Tieren.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 10, 7, 'Darum trugen sie Efeustäbe und schöne Zweige, auch Palmen, und sangen Loblieder zu Ehren dessen, der es ihnen möglich gemacht hatte, den heiligen Ort zu reinigen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 10, 8, 'Auch faßten sie den Beschluß und setzten namens der Gemeinde als Gesetz fest, daß das gesamte jüdische Volk jährlich diese Tage feiern solle. – –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 10, 9, 'Dies also war das Ende des Antiochus, der den Beinamen des Erlauchten führte.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 10, 10, 'Nunmehr aber wollen wir erzählen, was sich unter Antiochus Eupator dem Sohne jenes Gottlosen, zugetragen hat, doch so, daß wir die anhaltenden Leiden des Krieges kurz zusammenziehen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 10, 11, 'Als dieser nämlich die Regierung antrat, ernannte er einen gewissen Lysias zum Reichsverweser, sowie zum obersten militärischen Befehlshaber in Cölesyrien und Phönizien;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 10, 12, 'denn Ptolemäus mit dem Beinamen Makron, der das Beispiel einer billigen Verwaltung in seinem Verhalten gegen die Juden gegeben hatte angesichts der Ungerechtigkeiten, die man gegen sie begangen hatte, und der friedlich mit ihnen auszukommen suchte,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 10, 13, 'war darum bei Eupator von dessen Vertrauten verklagt worden; und da man ihn bei jeder Gelegenheit einen Verräter nannte, weil er den Dienst Philometors verlassen, der ihm die Regierung der Insel Cypern anvertraut hatte, und zu Antiochus Epiphanes übergegangen war, so konnte er seine Amtsführung trotz seines edlen Verfahrens nicht als eine edle erweisen und gab sich daher den Tod, indem er Gift nahm.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 10, 14, 'Georgias, der sodann militärischer Befehlshaber in dieser Gegend wurde, nahm fremde Truppen in Sold und hielt überall den Krieg gegen die Juden im Gange.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 10, 15, 'Gleichzeitig machten auch die Idumäer, welche günstig gelegene Festungen innehatten, den Juden viel zu schaffen; sie nahmen diejenigen auf, welche aus Jerusalem vertrieben worden waren, und fingen fortwährend Feindseligkeiten an.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 10, 16, 'Makkabäus aber und seine Leute hielten eine Gebetsversammlung ab und stürmten, nachdem sie Gott um seinen Beistand im Kampf angerufen hatten, auf die Festungen der Idumäer los,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 10, 17, 'griffen sie mutig an und bemächtigten sich der festen Plätze, nachdem sie alle zurückgeschlagen hatten, die auf den Mauern kämpften. Sie hieben alles nieder, was ihnen in die Hände fiel, und brachten so an 20000 Mann um.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 10, 18, 'Aber nicht weniger als 9000 Mann zogen sich in zwei außerordentlich starke Türme zurück, die mit allem versehen waren, was dazu diente, eine Belagerung auszuhalten.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 10, 19, 'Der Makkabäer ließ nun den Simon und Joseph zurück, sowie den Zachäus mit seiner Abteilung, in genügender Zahl, um die Belagerung fortzusetzen; er selbst wandte sich gegen Orte, wo seine Anwesenheit dringend nötig war.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 10, 20, 'Simons Leute aber ließen sich aus Liebe zum Gelde von einigen in den Türmen Belagerten bestechen, erhielten 70000 Drachmen und ließen eine Anzahl durchschlüpfen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 10, 21, 'Sobald der Makkabäer davon Kunde erhielt, versammelte er die Hauptleute und machte ihnen Vorwürfe, daß sie ihre Brüder um Geld verkauft hätten, indem sie die Feinde zum Schaden des eigenen Volkes durchließen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 10, 22, 'Er ließ diese also, die zu Verrätern geworden waren, hinrichten und hatte alsdann die beiden Türme bald in seiner Gewalt.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 10, 23, 'Überall glücklich, wo er die Waffen in die Hand nahm, erschlug er in diesen beiden Festungen mehr als 20000 Mann.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 10, 24, 'Timotheus aber, der früher von den Juden besiegt worden war, brachte ausländische Truppen in großer Zahl zusammen, auch Reiterei aus Asien in Menge, und rückte gegen Judäa, um es mit Waffengewalt zu erobern.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 10, 25, 'Als er heranzog, wandten sich die Leute des Makkabäus mit Gebet an Gott, streuten sich Staub auf das Haupt, gürteten Trauergewänder um die Hüften');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 10, 26, 'und warfen sich vor dem Altar nieder, um Gott zu bitten, er wolle ihnen gnädig sein als der Feind ihrer Feinde und als der Widersacher ihrer Gegner, wie das Gesetz es verheiße.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 10, 27, 'Nach dem Gebet ergriffen sie die Waffen, zogen zur Stadt hinaus eine weite Strecke und machten erst Halt, als sie den Feinden nahegekommen waren.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 10, 28, 'Bei Anbruch des Tages rückte man von beiden Seiten gegeneinander vor; die einen hatten als Bürgschaft für den Erfolg und den Sieg neben ihrem Mute noch ihr Gottvertrauen, die anderen dagegen ließen sich nur von ihrer Wut in den Kampf führen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 10, 29, 'Als nun der Streit gewaltig geworden war, erschienen den Feinden vom Himmel her auf goldbezäumten Rossen fünf glänzende Reiter, von denen zwei sich an die Spitze der Juden stellten');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 10, 30, 'und zwei den Makkabäer in die Mitte nahmen und ihn mit ihren Waffen deckten und vor jeder Verwundung schützten, während sie Pfeile und Blitze gegen die Feinde schleuderten, wodurch diese geblendet und verwirrt wurden und in Unordnung gerieten.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 10, 31, 'So wurden von ihnen 20500 Mann nebst 600 Reitern niedergehauen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 10, 32, 'Timotheus selbst flüchtete sich in einen sehr festen Ort namens Gasara, dessen Befehlshaber Chäreas war.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 10, 33, 'Die Leute des Makkabäus belagerten nun die Festung mutig vier Tage lang,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 10, 34, 'während die Belagerten, die den Platz für uneinnehmbar hielten, sie verhöhnten und maßlos gottlose Reden ausstießen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 10, 35, 'Aber bei Anbruch des fünften Tages stürzten zwanzig Jünglinge von den Leuten des Makkabäers, von Zorn wegen ihrer Lästerworte entbrannt, mannhaft auf die Mauer los und hieben mit Löwenmut alles nieder, was vor sie kam;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 10, 36, 'andere folgten ihnen, umgingen die Stadt und griffen die Belagerten von der anderen Seite an; sie legten Feuer an die Türme, zündeten Scheiterhaufen an und verbrannten die Lästerer lebendig; wieder andere schlugen die Tore ein, ließen das übrige Heer einziehen und eroberten so die Stadt.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 10, 37, 'Den Timotheus, der sich in einer Zisterne versteckt hatte, erschlugen sie samt seinem Bruder Chäreas und dem Apollophanes.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 10, 38, 'Als sie das alles vollbracht hatten, sangen sie Loblieder und Danklieder zu Ehren des Herrn, des großen Wohltäters Israels, der ihnen den Sieg verliehen hatte.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 11, 1, 'Ganz kurze Zeit nachher brachte Lysias, der Vormund und Vetter des Königs und Reichsverweser, voll Verdruß über das Vorgefallene');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 11, 2, 'ein Heer von ungefähr 80000 Mann zu Fuß nebst der ganzen Reiterei zusammen und zog zu Felde gegen die Juden in der Absicht, die Hauptstadt mit Griechen zu besiedeln,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 11, 3, 'den Tempel einer Abgabe zu unterwerfen, ganz wie die übrigen heidnischen Heiligtümer, und das Hohepriestertum zu einem jährlichen, käuflichen Amte zu machen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 11, 4, 'Er bedachte dabei ganz und gar nicht die Macht Gottes, sondern trotzte in unsinniger Weise auf seine Zehntausende Fußvolks und seine Tausende von Reitern und seine 80 Elefanten.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 11, 5, 'Er fiel also in Judäa ein und zog nahe an Bethsura heran, einen festen Ort, der 150 Stadien von Jerusalem entfernt war, und schloß ihn ein.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 11, 6, 'Als nun die Leute des Makkabäers erfuhren, daß er die Festungen belagerte, wandten sie sich mit ihrem ganzen Volke an den Herrn unter Tränen und Wehklagen und baten ihn, einen guten Engel zu entsenden, um Israel zu retten.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 11, 7, 'Dann ergriff der Makkabäer, selber allen voran, die Waffen und ermahnte die anderen, im Verein mit ihm den Gefahren zu trotzen und ihren Brüdern zu Hilfe zu eilen; und so brachen sie mutig auf.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 11, 8, 'Sie waren noch dort in der Nähe von Jerusalem, als ihnen ein Reiter in weißem Gewande erschien, der sich an ihre Spitze stellte, goldene Waffen schwingend.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 11, 9, 'Da priesen sie alle den barmherzigen Gott und fühlten sich ermutigt und waren bereit, nicht nur Menschen niederzurennen, sondern auch die wildesten Tiere und eiserne Mauern.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 11, 10, 'Sie marschierten also in guter Ordnung vorwärts mit ihrem himmlischen Mitstreiter, den ihnen die Gnade des Herrn zugeteilt hatte.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 11, 11, 'Mit Löwenmut stürzten sie sich auf die Feinde und streckten von ihnen 11000 nieder, sowie 1600 Reiter; alle anderen aber trieben sie in die Flucht.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 11, 12, 'Die meisten von ihnen retteten nur als Verwundete und ohne Waffen ihr Leben; Lysias selbst entkam nur durch schimpfliche Flucht.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 11, 13, 'Da er indessen nicht ohne Verstand war, dachte er über die erlittene Niederlage nach; er begriff, daß die Hebräer unüberwindlich waren, weil der allmächtige Gott für sie kämpfte. Darum schickte er Boten zu ihnen,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 11, 14, 'um sie zu bereden, auf billige Bedingungen mit ihm zu unterhandeln; er versprach, auch den König dahin zu bringen, daß er mit ihnen Freundschaft schlösse.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 11, 15, 'Der Makkabäuer ging auf alles ein, was Lysias vorschlug, indem er auf seinen Vorteil bedacht war; denn der König gestand alles zu, was der Makkabäer von Lysias in einer Denkschrift für die Juden gefordert hatte.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 11, 16, 'Es hatte nämlich der Brief, den Lysias an die Juden geschrieben hatte, folgenden Wortlaut: »Lysias entbietet dem Volke der Juden seinen Gruß.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 11, 17, 'Johannes und Absalom, eure Gesandten, haben das mit eurer Unterschrift versehene Schriftstück überreicht und in betreff der darin enthaltenen Vorschläge um Antwort ersucht.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 11, 18, 'Was nun auch dem Könige zur Bestätigung vorgelegt werden mußte, habe ich ihm berichtet, und was tunlich war, hat er zugestanden.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 11, 19, 'Wenn ihr nun eure gute Gesinnung gegen die Regierung ferner bewahrt, so werde ich meinerseits euch weitere Vorteile zuzuwenden suchen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 11, 20, 'Über einige besondere Dinge habe ich euren Gesandten und meinen Abgeordneten Auftrag gegeben, mit euch zu verhandeln.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 11, 21, 'Lebt wohl!« Am 24. Tage des Dioskorinthus im Jahre 148.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 11, 22, 'Der Brief des Königs aber lautete folgendermaßen: »König Antiochus entbietet seinem Bruder Lysias seinen Gruß.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 11, 23, 'Nachdem mein Vater unter die Götter versetzt worden ist, hege ich den Wunsch, daß die Bewohner unseres Reiches ungestört ihre Angelegenheiten besorgen mögen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 11, 24, 'Da wir nun in Erfahrung gebracht haben, daß die Juden nicht einwilligen, den von meinem Vater gewünschten Übergang zu griechischem Wesen vorzunehmen, sondern ihre eigene Lebensweise vorziehen und deswegen bitten, daß man ihnen ihre Gesetze lasse,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 11, 25, 'wir aber wollen, daß auch dieses Volk nicht beunruhigt werde, so befehlen wir, daß der Tempel ihnen zurückgegeben werde und sie nach den Sitten ihrer Vorfahren ihr Leben führen sollen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 11, 26, 'Du wirst also wohl daran tun, wenn du zu ihnen sendest und Frieden mit ihnen schließest, damit sie in Erkenntnis unseres Willens guten Mutes seien und sich getrost der Besorgung ihrer Angelegenheiten widmen.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 11, 27, 'An das (jüdische) Volk aber erging folgendes Schreiben des Königs: »König Antiochus entbietet dem Hohen Rate der Juden und dem übrigen Volke seinen Gruß.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 11, 28, 'Wenn ihr euch wohl befindet, so ist’s nach unserem Wunsch; wir selbst befinden uns wohl.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 11, 29, 'Menelaus hat uns berichtet, daß ihr (in eure Heimat) zurückzukehren und euch euren Angelegenheiten zu widmen wünscht.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 11, 30, 'Denjenigen nun, welche bis zum 30. Xanthikus heimkehren, wird hiermit versprochen und zugesichert,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 11, 31, 'daß den Juden der Genuß ihrer eigenen Speisen und der Gebrauch ihrer eigenen Gesetze zustehen soll ganz wie früher, und daß keiner von ihnen irgendwie wegen begangener Vergehen belästigt werden darf.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 11, 32, 'Zugleich schicke ich euch den Menelaus, der euch (weitere) Zusicherungen machen soll.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 11, 33, 'Gehabt euch wohl! Im Jahre 148 am 15. Tage des Xanthikus.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 11, 34, 'Auch die Römer schickten einen Brief, der folgendermaßen lautete: »Quintus Memmius und Titus Manlius, die römischen Gesandten, entbieten dem Volke der Juden ihren Gruß.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 11, 35, 'Was Lysias, der Vetter des Königs, euch zugestanden hat, dem stimmen auch wir zu.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 11, 36, 'In betreff dessen aber, was er dem König zur Entscheidung vorzulegen beschlossen hat, darüber schickt uns unverzüglich nach vorhergegangener Beratung jemanden, damit wir es so darlegen können, wie es zu euren Gunsten ist; wir sind nämlich auf dem Wege nach Antiochien.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 11, 37, 'Beeilt euch also, uns einige Leute zu schicken, damit wir eure Ansicht erfahren.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 11, 38, 'Lebt wohl!« Am 15. Tage des Xanthikus im Jahre 148.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 12, 1, 'Nachdem diese Verträge geschlossen waren, zog Lysias ab, um sich zum Könige zu verfügen; die Juden aber machten sich an ihren Ackerbau.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 12, 2, 'Aber die Befehlshaber in den betreffenden Gegenden, Timotheus und Apollonius, der Sohn des Gennäus, sowie Hieronymus und Demophon, außerdem noch Nikanor, der Statthalter von Cypern, ließen sie nicht in Ruhe und in Frieden leben.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 12, 3, 'Die Einwohner von Joppe aber begingen gegen sie folgende Niederträchtigkeit: Sie luden die Juden, die bei ihnen wohnten, ein, mit Weib und Kind in die von ihnen bereitgehaltenen Boote einzusteigen, als wenn sie nichts Feindseliges gegen sie im Sinne hätten,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 12, 4, 'sondern als wäre es eine vom gesamten Gemeinderat beschlossene Sache. Da jene die Einladung annahmen, weil sie mit ihnen in Frieden leben wollten und keinen Argwohn hegten, so fuhr man sie auf die hohe See hinaus und warf sie dort ins tiefe Wasser, wohl an 200 Personen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 12, 5, 'Als nun Judas die an seinen Landsleuten verübte Grausamkeit erfuhr, erteilte er seiner Mannschaft Befehl;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 12, 6, 'und nachdem er Gott, den gerechten Richter, gegen die Mörder seiner Brüder angerufen hatte, zündete er den Hafen bei Nacht an, verbrannte die Boote und hieb die dahin Geflüchteten nieder.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 12, 7, 'Da der Platz selbst geschlossen war, zog er ab, aber in der Absicht wiederzukommen, um die ganze Bürgerschaft von Joppe zu vertilgen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 12, 8, 'Und da er erfuhr, daß die Einwohner von Jamnia gegen die bei ihnen wohnenden Juden ein Gleiches im Schilde führten,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 12, 9, 'so überfiel er sie ebenfalls bei Nacht und zündete ihren Hafen an samt den Schiffen, so daß der Feuerschein bis Jerusalem leuchtete, 240 Stadien weit.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 12, 10, 'Als sie sich nun von dort zurückgezogen hatten, und ungefähr neun Stadien weit gekommen waren, um gegen Timotheus zu ziehen, wurden sie von Arabern angegriffen, von wenigstens 5000 Mann zu Fuß und 500 Reitern.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 12, 11, 'Nach einem hitzigen Gefecht behielten die Leute des Judas mit Gottes Hilfe die Oberhand, und die besiegten Beduinen baten Judas um Frieden und versprachen, sie wollten Vieh liefern und auch sonst sich nützlich machen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 12, 12, 'Judas, der die Ansicht hegte, daß sie sich in der Tat in manchen Stücken nützlich erweisen könnten, gestand ihnen den Frieden zu; und nachdem der Vertrag durch Handschlag abgeschlossen war, kehrten sie zu ihren Zelten zurück.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 12, 13, 'Er griff auch eine gewisse Stadt Kaspin an, die durch Brücken gesichert und mit Mauern umgeben war und eine gemischte heidnische Bevölkerung hatte.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 12, 14, 'Die Einwohner, die sich auf die Festigkeit ihrer Mauern und auf ihre reichlichen Vorräte verließen, verhöhnten in schamloser Weise den Judas und seine Leute und führten noch dazu lästerliche und gottlose Reden.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 12, 15, 'Die Mannschaften des Judas aber riefen den großen Herrn der Welt an, der einst zu Josuas Zeiten Jericho ohne die Hilfe von Sturmböcken und anderen Kriegsmaschinen niedergeworfen hatte, und stürmten wütend auf die Mauern los,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 12, 16, 'nahmen die Stadt mit Gottes Willen ein und richteten ein solch unsagbares Gemetzel darin an, daß der benachbarte, zwei Stadien breite See ganz mit Blut angefüllt zu fließen schien.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 12, 17, 'Von dort zogen sie ab, 750 Stadien weit, und gelangten endlich in die Gegend von Charax zu den Tubienischen Juden.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 12, 18, 'Den Timotheus fanden sie nicht mehr dort, er war unverrichteter Sache von dort abgezogen, nachdem er eine sehr starke Besatzung in einem festen Platze zurückgelassen hatte.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 12, 19, 'Da zogen zwei Hauptleute des Makkabäers, Dositheus und Sosipater, dorthin und töteten die von Timotheus in der Festung Zurückgelassenen, mehr als 10000 Mann.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 12, 20, 'Der Makkabäer selbst aber teilte jetzt sein Heer in mehrere Abteilungen, an deren Spitze er Befehlshaber stellte; dann zog er gegen Timotheus weiter, der 120000 Mann zu Fuß und 1500 Reiter bei sich hatte.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 12, 21, 'Als Timotheus erfuhr, daß Judas im Anzuge gegen ihn sei, schickte er die Weiber und Kinder und den übrigen Troß vom Heere weg nach dem sogenannten Karnion, einem festen Platze, der unzugänglich und schwer einzunehmen war wegen der überall vorhandenen Engpässe.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 12, 22, 'Kaum aber erschien die erste Abteilung des Judas, so ergriff Furcht und Schrecken die Feinde, wodurch sich der alles überschauende Gott wirksam zeigte; sie flohen nach allen Richtungen hin auseinander, so daß sie öfters sich gegenseitig verwundeten und einander mit ihren Schwertern durchbohrten.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 12, 23, 'Judas verfolgte sie nun mit Ungestüm, hieb die Bösewichter zusammen und machte von ihnen an 30000 Mann nieder.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 12, 24, 'Timotheus selbst fiel den Leuten des Dositheus und Sosipater in die Hände und bat sie inständig, ihn am Leben zu lassen, indem er ihnen vorspiegelte, daß er von vielen die Eltern und von anderen die Brüder in seiner Gewalt habe, denen es gewiß übel ergehen würde, wenn man ihn tötete.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 12, 25, 'Da er nun unter vielen Beteuerungen fest versprach, diese unversehrt zurückzuschicken, so ließen sie ihn frei, um ihre Brüder zu retten.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 12, 26, 'Dann zog Judas gegen Karnion und den Tempel der Atargatis und erschlug dort 25000 Menschen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 12, 27, 'Nach ihrer Besiegung und Vernichtung zog Judas mit dem Heere auch gegen die feste Stadt Ephron, in welcher Lysias und eine sehr gemischte Bevölkerung wohnte. Tapfere Jünglinge, vor den Mauern aufgestellt, verteidigten die Stadt mutig; auch waren dort Kriegsmaschinen und Geschosse in Menge vorhanden.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 12, 28, 'Aber nach Anrufung des Herrn, der durch seine gewaltige Kraft die Macht der Feinde zermalmt, nahmen sie die Stadt ein und erschlugen von denen, die darin waren, an 25000.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 12, 29, 'Von da zogen sie nach der Stadt Skythopolis weiter, die von Jerusalem 600 Stadien entfernt liegt.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 12, 30, 'Da aber die dort wohnenden Juden bezeugten, daß die Einwohner der Stadt ihnen immer mit Wohlwollen begegnet seien und in den unglücklichen Zeiten sich freundlich gegen sie verhalten hätten,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 12, 31, 'so sagten sie ihnen Dank dafür und ermahnten sie, auch fernerhin bei diesen Gesinnungen gegen ihr Volk zu beharren; dann zogen sie nach Jerusalem, da das Wochenfest nahe bevorstand.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 12, 32, 'Nach diesem – auch Pfingsten genannten – Feste zogen sie gegen Gorgias, den Statthalter von Idumäa.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 12, 33, 'Dieser kam ihnen entgegen mit 3000 Mann zu Fuß und 400 Reitern.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 12, 34, 'Als man nun handgemein wurde, begab es sich, daß einige Juden fielen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 12, 35, 'Ein gewisser Dositheus aber, einer von den Leuten Bakenors, ein tapferer Mann zu Pferde, packte den Gorgias fest am Mantel und zog ihn herzhaft fort, weil er den Verfluchten lebendig fangen wollte; aber ein thrakischer Reiter sprengte heran und hieb ihm den Arm ab, so daß Gorgias nach Maresa entfliehen konnte.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 12, 36, 'Da nun die Abteilung Esri’s infolge des langen Kampfes ermüdet war, erflehte Judas den Beistand des Herrn, daß er die Schlacht leiten und als Mitstreiter erscheinen möchte;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 12, 37, 'dann stimmte er in der vaterländischen Sprache ein Loblied an, ließ hierauf den Schlachtruf erschallen, stürzte sich unversehens auf die Truppen des Gorgias und trieb sie in die Flucht.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 12, 38, 'Judas führte darauf sein Heer nach der Stadt Adullam, und da gerade der siebente Tag anbrach, heiligten sie sich der Sitte gemäß und brachten dort den Sabbat zu.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 12, 39, 'Am folgenden Tage aber gingen die Leute des Judas hin, da es inzwischen hohe Zeit geworden war, um die Leichname der im Kampfe Gefallenen aufzuheben und sie im Verein mit ihren Verwandten in den väterlichen Gräbern zu bestatten.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 12, 40, 'Da fanden sie bei jedem der Toten unter dem Hemde geweihte Gegenstände (Kleinodien), die von den Götzen in Jamnia herrührten, deren Gebrauch den Juden durch das Gesetz verboten ist. Da wurde es allen klar, daß jene deswegen umgekommen waren.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 12, 41, 'Da priesen sie alle den Herrn, den gerechten Richter, der das Verborgene ans Licht bringt.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 12, 42, 'Dann beteten sie andächtig, daß die begangene Sünde gänzlich vergeben werden möchte; und der edle Judas ermahnte das Volk, sich vor solcher Sünde zu hüten, weil sie die Folgen der Übertretung an den in der Schlacht Gefallenen vor Augen hätten.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 12, 43, 'Dann veranstaltete er eine Sammlung unter seinen Leuten und brachte 2000 Drachmen Silber zusammen, die er nach Jerusalem schickte zur Darbringung eines Sühnopfers. Es war dies eine sehr schöne und löbliche Handlung, weil er an die Auferstehung dachte;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 12, 44, 'denn wenn er nicht an die Auferstehung der im Kampfe Gefallenen geglaubt hätte, so wäre es überflüssig und eine Torheit gewesen, für Tote zu beten.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 12, 45, 'So aber, weil er dachte, daß den fromm Entschlafenen der herrlichste Gnadenlohn vorbehalten sei, so war dies ein heiliger und frommer Gedanke. Daher veranstaltete er für die Gefallenen das Sühnopfer, damit ihnen ihre Sünde vergeben würde.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 12, 46, '');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 13, 1, 'Im Jahre 149 wurden Judas und seine Leute in Kenntnis gesetzt, daß Antiochus Eupator mit einem großen Heere gegen Judäa heranziehe');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 13, 2, 'und mit ihm sein Vormund Lysias, der Reichsverweser, jeder mit einem griechischen Heere von 110000 Mann Fußvolks und 5300 Reitern, 22 Elefanten und 300 Sichelwagen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 13, 3, 'Auch Menelaus gesellte sich zu ihnen und trieb den König zum Kriege an, wobei er sich verstellte, da er nicht das Wohl seines Vaterlandes im Auge hatte, sondern die Hoffnung hegte, wieder in sein Amt eingesetzt zu werden.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 13, 4, 'Aber der König aller Könige erweckte den Zorn des Antiochus gegen diesen Bösewicht; und da Lysias nachwies, daß dieser Mensch die Schuld an allen Unglücksfällen trage, befahl er, ihn nach Beröa zu bringen, um dort nach der Sitte des Ortes hingerichtet zu werden.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 13, 5, 'An diesem Orte befindet sich nämlich ein fünfzig Ellen hoher Turm, mit (glühender) Asche angefüllt. In diesem Turm ist eine Vorrichtung, die sich dreht und von allen Seiten in die Asche hineinschleudert.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 13, 6, 'Einen Tempelräuber oder sonstige große Verbrecher stürzt dort die ganze Bevölkerung hinunter, so daß sie elendiglich umkommen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 13, 7, 'Eines solchen Todes mußte der ruchlose Menelaus sterben, der nicht einmal ein Grab in der Erde fand, ganz wie er es verdient hatte;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 13, 8, 'denn nachdem er sich vielfach an dem Altar versündigt hatte, dessen Feuer samt der Asche heilig war, fand er in der Asche seinen Tod.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 13, 9, 'Der König aber zog in einer höchst feindseligen Stimmung heran und war entschlossen, den Juden das Schlimmste von dem anzutun, was sie schon von seinem Vater erlitten hatten.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 13, 10, 'Als Judas dies erfuhr, befahl er dem Volke, den Herrn bei Tag und Nacht anzurufen, daß er, wenn je zuvor, so auch jetzt denen zu Hilfe kommen wolle, die ihres Vaterlandes, ihres Gesetzes und des heiligen Tempels beraubt werden sollten,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 13, 11, 'auch nicht zugeben möge, daß das kaum ein wenig aufgelebte Volk wiederum in die Gewalt der abscheulichen Heiden gerate.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 13, 12, 'Nachdem sie dies alle einmütig getan und den allbarmherzigen Gott drei Tage lang ohne Unterbrechung mit Weinen und Fasten und Niederfallen angefleht hatten, hielt Judas eine Ansprache an sie und hieß sie sich bereit halten.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 13, 13, 'Nach einer geheimen Beratung mit den Ältesten beschloß er, bevor der König mit seinem Heere in Judäa einfiele und sich der Hauptstadt bemächtige, selbst auszuziehen und mit Gottes Hilfe die Sache abzumachen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 13, 14, 'Indem er so die Entscheidung dem Schöpfer der Welt anheimstellte, ermahnte er die Seinen, mutig zu streiten und das Leben einzusetzen für ihre Gesetze und ihren Tempel, für ihre Stadt, ihr Vaterland und ihre Verfassung, und schlug sein Lager bei Modein auf.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 13, 15, 'Nachdem er dann den Seinen die Losung »Sieg mit Gott!« gegeben hatte, griff er mit einer auserwählten Schar der tapfersten jungen Männer bei Nacht das Hauptquartier des Königs an, erschlug bei 2000 Mann im Lager und machte auch den vornehmsten Elefanten samt allen Leuten in dessen Turm nieder.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 13, 16, 'Schließlich, nachdem sie das ganze Lager mit Furcht und Schrecken erfüllt hatten, zogen sie sich als Sieger zurück;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 13, 17, 'das geschah aber erst, als schon der Tag anbrach, unter dem hilfreichen Schutze des Herrn.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 13, 18, 'Als der König diesen Vorschmack von der Kühnheit der Juden erhalten hatte, suchte er sich der festen Plätze durch List zu bemächtigen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 13, 19, 'So zog er gegen Bethsura, eine starke jüdische Festung, wurde zurückgeschlagen, berannte sie nochmals, wurde aber wieder besiegt;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 13, 20, 'denn Judas hatte den Belagerten Lebensmittel zuführen können.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 13, 21, 'Ein gewisser Rhodokus aber, ein Mann aus dem jüdischen Heere, verriet den Feinden die Geheimnisse, er wurde jedoch entdeckt, ergriffen und eingesperrt.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 13, 22, 'Nun unterhandelte der König zum zweiten Mal mit denen in Bethsura, bot Frieden an, schloß ab, zog weg, begegnete dem Heere des Judas, wurde geschlagen,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 13, 23, 'erfuhr nun, daß Philippus, den er in Antiochien als Reichsverweser zurückgelassen hatte, sich empört habe, geriet darüber in Bestürzung, machte den Juden freundliche Eröffnungen, gab nach, beschwor alle ihm gestellten Bedingungen, die er billig fand, versöhnte sich mit ihnen, brachte ein Opfer dar, ehrte den Tempel, bewies sich wohlwollend gegen die heilige Stätte,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 13, 24, 'nahm auch den Makkabäer freundlich auf und ließ den Hegemonides als Statthalter des Gebietes von Ptolemais bis Gerar zurück.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 13, 25, 'Er begab sich dann nach Ptolemais, dessen Einwohner aber über den Vertrag unwillig waren; sie waren aufgebracht über die Bestimmungen und hätten sie gern wieder umgestoßen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 13, 26, 'Aber Lysias trat auf die Rednerbühne, hielt eine nachdrückliche Verteidigungsrede, überzeugte, besänftigte, begütigte und kehrte dann nach Antiochien zurück. So ist der Feldzug und der Wiederheimzug des Königs Antiochus verlaufen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 1, 'Drei Jahre später erfuhr Judas, daß Demetrius, des Seleukus Sohn, im Hafen von Tripolis mit einer Flotte und starker Heeresmacht eingelaufen sei,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 2, 'und daß er sich des Landes bemächtigt und den Antiochus und dessen Vormund Lysias aus dem Wege geräumt habe.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 3, 'Nun war da ein gewisser Alkimus, der früher Hoherpriester gewesen war, aber sich in den Zeiten der Religionsmengerei freiwillig entehrt hatte; dieser sah ein, daß auf keinem anderen Wege für ihn etwas zu hoffen, auch kein Zutritt zum heiligen Altar zu erlangen sei.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 4, 'Er begab sich also zum Könige Demetrius im Jahre 150 und brachte ihm eine goldene Krone und einen Palmzweig, dazu Ölzweige, wie man solche im Namen des Tempels darzubringen pflegte, hielt sich aber damals noch zurück');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 5, 'und wartete auf eine günstige Gelegenheit zur Erreichung seiner schlimmen Absicht. Als er dann von Demetrius in eine Ratsversammlung berufen war und man ihn nach der Gesinnung und nach den Absichten der Juden befragte, gab er folgende Antwort:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 6, '»Diejenigen Juden, die den Namen Chasidäer führen und an deren Spitze Judas der Makkabäer steht, unterhalten dauernd den Sinn für Krieg und Aufruhr und lassen das Reich nicht zur Ruhe kommen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 7, 'Aus diesem Grunde bin ich ja auch meiner ererbten Würde, nämlich des Hohenpriestertums, beraubt worden und bin jetzt hierher gekommen,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 8, 'zunächst, weil ich in aufrichtiger Weise der Sache des Königs zugetan bin, sodann aber auch, weil ich meine eigenen Mitbürger berücksichtige; denn unser ganzes Volk leidet nicht wenig unter dem törichten Treiben der vorgenannten Leute.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 9, 'Laß alles dieses untersuchen, o König, und nimm dich unseres Landes und unseres bedrängten Volkes an, gemäß deiner Menschenfreundlichkeit, die du gegen alle hegst;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 10, 'denn solange dieser Judas noch im Lande ist, kann unmöglich Friede im Lande werden!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 11, 'Nachdem dieser Mensch solche Reden geführt hatte, beeilten sich auch die anderen Vertrauten des Königs, die dem Judas feindlich gesinnt waren, den Demetrius gegen ihn aufzureizen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 12, 'Dieser ließ sofort den Nikanor kommen, den früheren Anführer der Elefanten-Abteilung, ernannte ihn zum Befehlshaber über Judäa und schickte ihn dorthin');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 13, 'mit dem schriftlichen Befehl, den Judas aus dem Wege zu schaffen, dessen Truppen zu zersprengen und den Alkimus zum Hohenpriester des Hauptheiligtums einzusetzen. –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 14, 'Die Heiden, welche sich vor Judas aus ganz Judäa geflüchtet hatten, kamen nun scharenweise heran, sich an Nikanor anzuschließen, weil sie hofften, daß das Unglück und Mißgeschick der Juden für sie selbst ein Glück sein würde.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 15, 'Als die Juden nun erfuhren, daß Nikanor im Anzuge sei und die Heiden einen Angriff vorbereiteten, streuten sie sich Staub auf ihre Häupter und wandten sich mit Gebeten an den, welcher seinem Volke ewigen Beistand zugesichert hat und sich immerdar seines Eigentums sichtbarlich annimmt.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 16, 'Auf Befehl ihres Anführers brachen sie sogleich von dort auf und wurden mit den Feinden bei dem Dorfe Dessau handgemein.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 17, 'Simon, der Bruder des Judas, war nun zwar bei einem Zusammenstoß mit Nikanor wegen der durch die Feinde bewirkten plötzlichen Bestürzung für kurze Zeit ins Wanken geraten;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 18, 'trotzdem trug Nikanor, als er von der Tapferkeit der Truppen des Judas und von dem Mute hörte, mit dem sie für ihr Vaterland kämpften, nicht geringes Bedenken, eine Entscheidung durch Blutvergießen herbeizuführen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 19, 'Er entsandte daher den Posidonius und Theodotus und Mattathias, um über den Frieden zu unterhandeln.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 20, 'Nachdem nun eine längere Erwägung der Sache stattgefunden, auch der Anführer dem ganzen Heere Mitteilung gemacht hatte und man zu einem einmütigen Entschluß gekommen war, billigten sie den Abschluß des Friedens.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 21, 'Man bestimmte nun einen Tag für eine persönliche Zusammenkunft beider an demselben Orte; Judas ging auch hin, und man stellte auf jeder Seite einen Stuhl hin.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 22, 'Judas hatte aber an schicklichen Orten Bewaffnete aufgestellt für den Fall, daß die Feinde plötzlich einen tückischen Überfall unternehmen würden; doch die Unterredung verlief in aller Ordnung.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 23, 'Nikanor verweilte darauf einige Zeit in Jerusalem, ohne etwas Unrechtes zu tun, entließ vielmehr die Truppen, die er gesammelt hatte, scharenweise.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 24, 'Während der ganzen Zeit hatte er den Judas um sich und war dem Manne von Herzen zugetan;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 25, 'er empfahl ihm, zu heiraten und sich eine Familie zu gründen. Judas heiratete auch wirklich, lebte glücklich und genoß das Leben.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 26, 'Als Alkumus aber sah, wie beide in freundlichen Beziehungen zueinander standen und einen Vertrag abgeschlossen hatten, nahm er eine Abschrift davon mit sich und verfügte sich zu Demetrius und sagte zu diesem, Nikanor verfolge staatsfeindliche Absichten; er habe sogar den Verschwörer gegen das Reich, den Judas, zu seinem Nachfolger im Hohenpriestertum bestimmt.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 27, 'Der König geriet darüber in großen Zorn, und durch die Verleumdung des Bösewichts gereizt, schrieb er dem Nikanor, daß er mit dem Abschluß des Vertrages ganz unzufrieden sei, und befahl ihm, den Makkabäer unverzüglich gefesselt nach Antiochien zu schicken.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 28, 'Als dieser Befehl bei Nikanor eintraf, wurde er bestürzt und unwillig darüber, daß er den Vertrag rückgängig machen sollte, obgleich doch der Mann nichts Unrechtes begangen hatte.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 29, 'Da es aber nicht anging, dem Willen des Königs zuwiderzuhandeln, beschloß er, eine Gelegenheit abzuwarten, um die Sache mit List auszuführen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 30, 'Der Makkabäer aber, welcher merkte, daß Nikanor ihm weniger freundlich begegnete und sein sonstiges Verhalten in größere Kälte hatte umschlagen lassen, begriff wohl, daß diese Stimmung nichts Gutes bedeutete; er zog daher eine nicht geringe Anzahl seiner Leute zusammen und verbarg sich vor Nikanor.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 31, 'Da der andere sich nun von dem Manne tüchtig überlistet sah, begab er sich in den hochheiligen Tempel, gerade als die Priester die üblichen Opfer ausrichteten, und befahl ihnen, den Mann auszuliefern.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 32, 'Da diese aber eidlich versicherten, nicht zu wissen, wo der Gesuchte sich befinde,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 33, 'streckte er die rechte Hand gegen den Tempel aus und schwur: »Wenn ihr mir den Judas nicht gefesselt ausliefert, so mache ich dieses euer Gotteshaus dem Erdboden gleich, reiße den Altar nieder und errichte hier dem Bakchus einen prachtvollen Tempel!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 34, 'Nach diesen Worten ging er weg. Die Priester aber erhoben die Hände zum Himmel und riefen den an, der allezeit der Beschützer unseres Volkes ist, und beteten:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 35, '»Du, o Herr, der du keines Dinges bedarfst, du hast gewollt, daß ein Tempel als deine Wohnung in unserer Mitte sei.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 36, 'So bewahre nun, heiliger Herr, von dem alle Heiligung kommt, dieses vor kurzem erst neu geweihte Haus vor aller Befleckung immerdar (und stopfe jeden ruchlosen Mund)!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 37, 'Nun wurde dem Nikanor ein gewisser Razis angezeigt, einer von den Ältesten Jerusalems, ein Mann, der seine Mitbürger liebte und sich eines vorzüglichen Rufes erfreute und den man wegen seiner Wohltätigkeit den Judenvater nannte.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 38, 'Früher schon, in den Zeiten, als man sich von Vermengung mit heidnischem Wesen fernhielt, hatte er sich entschieden zum Judentum bekannt und Leib und Leben für seinen Glauben mit großer Standhaftigkeit eingesetzt.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 39, 'Da nun Nikanor seine feindliche Gesinnung gegen die Juden offen zeigen wollte, schickte er mehr als 500 Mann aus, um ihn gefangen zu nehmen;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 40, 'denn er dachte, wenn er diesen ergriffe, würde er den übrigen einen schweren Schlag versetzen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 41, 'Im Augenblick aber, als die Truppen den Turm (worin er sich befand) einzunehmen im Begriff waren und den Eingang zum Hofe erzwingen wollten und man nach Feuer rief, um die Tore in Brand zu stecken, stürzte sich Razis, der nicht mehr entfliehen konnte, in sein Schwert,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 42, 'weil er lieber edelmütig sterben als diesen Ruchlosen in die Hände fallen und auf eine seines edlen Sinnes unwürdige Weise mißhandelt werden wollte.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 43, 'Da er sich aber in der Hast nicht tödlich getroffen hatte und der Haufe schon ins Innere eindrang, lief er heldenmütig auf die Mauer und stürzte sich mannhaft auf die Menge hinab.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 44, 'Diese wich aber rasch zurück, und so entstand ein leerer Raum, in den er mitten hineinfiel.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 45, 'Er lebte aber noch, und obgleich das Blut stromweise floß und seine Wunden schwer waren, stand er, von Zorn entbrannt auf, lief rasch durch die Menge und trat auf einen steilen Felsen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 46, 'Hier riß er sich, nachdem er schon all sein Blut verloren hatte, mit beiden Händen die Eingeweide aus dem Leibe und schleuderte sie auf die Truppen, rief darauf den Herrn des Lebens und des Geistes an, daß er ihm beides einst wiedergeben wolle, und starb auf diese Weise.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 1, 'Als Nikanor aber erfuhr, daß Juda mit seinen Leuten sich in den Ortschaften von Samarien aufhalte, beschloß er, sie am Ruhetage in aller Sicherheit anzugreifen;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 2, 'und als die Juden, die zwangsweise ihm folgten, zu ihm sagten: »Bringe sie doch nicht so grausam und unmenschlich ums Leben, sondern halte den Tag in Ehren, den der Allwissende mit Heiligkeit ausgezeichnet hat«,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 3, 'da fragte sie dieser Erzschurke, ob denn im Himmel ein Herr sei, der den Sabbat zu feiern befohlen habe.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 4, 'Und als sie ihm offen erklärten, es sei der lebendige Gott selbst, der Herr im Himmel, der geboten habe, den siebenten Tag zu feiern,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 5, 'da antwortete jener: »Und ich bin der Herr auf Erden, und ich befehle euch, die Waffen zu ergreifen und den Dienst des Königs zu vollführen!« Gleichwohl gelang es ihm nicht, seinen schändlichen Vorsatz auszuführen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 6, 'Er hatte sich wohl in seinem übermütigen Trotze vorgesetzt, einen öffentlichen Triumph über Judas und dessen Truppen abzuhalten;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 7, 'aber der Makkabäer, unerschütterlich in seinem Vertrauen, hoffte fest auf die Hilfe des Herrn');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 8, 'und ermahnte die Seinen, sich durch das Anrücken der Heiden nicht einschüchtern zu lassen; vielmehr sollten sie in der Erinnerung an den Beistand, der ihnen früher oftmals vom Himmel her zuteil geworden sei, auch jetzt fest auf den Sieg hoffen, den der Allmächtige ihnen verleihen würde.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 9, 'Er ermutigte sie auf Grund des Gesetzes und der Propheten und erinnerte sie auch an die Kämpfe, die sie schon bestanden hatten, und stärkte so ihren Mut.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 10, 'Nachdem er sie so begeistert hatte, erteilte er seine Befehle, wobei er auch noch auf die Treulosigkeit der Heiden und ihre Wortbrüchigkeit hinwies.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 11, 'Nachdem er so jeden von ihnen gewappnet hatte nicht sowohl mit der Zuversicht auf Schild und Speer als vielmehr mit dem Zuspruch trefflicher Worte, stimmte er obendrein alle noch fröhlich durch die Erzählung eines überaus glaubhaften Traumes.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 12, 'Das darin zur Erscheinung gebrachte Gesicht war aber folgendes: Onias, der einstmalige Hohepriester, ein durchaus rechtschaffener Mann, bescheiden im Umgang, sanftmütig von Charakter, würdevoll in seiner Rede und von Jugend auf aller Tugenden beflissen, – den hatte er gesehen, wie er die Hände ausstreckte und für die gesamte Gemeinde der Juden betete;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 13, 'und darauf sei ein ebenso durch graues Haar und würdevolles Aussehen ausgezeichneter Mann erschienen, den eine ganz wunderbare, hochherrliche Majestät umgeben habe.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 14, 'Dann habe Onias das Wort ergriffen und (zu Judas) gesagt: »Dies ist der Freund seiner Brüder, der für das Volk und für die heilige Stadt viel betet, der Prophet Gottes, Jeremia.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 15, 'Jeremia aber habe die Hand ausgestreckt und dem Judas ein goldenes Schwert überreicht und dabei gesagt:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 16, '»Nimm hin das heilige Schwert als ein Geschenk Gottes; mit diesem wirst du die Feinde schlagen!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 17, 'Ermutigt durch diese herrlichen Worte des Judas, die ganz geeignet waren, zur Tapferkeit anzufeuern und den Jünglingsherzen Mannesmut einzuflößen, beschlossen sie, kein Lager zu beziehen, sondern tapfer anzugreifen und, mit voller Mannhaftigkeit kämpfend, die Entscheidung herbeizuführen, weil ja auch die Hauptstadt und der Gottesdienst und der Tempel in Gefahr schwebten.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 18, 'Denn die Sorge für ihre Weiber und Kinder, sowie für ihre Brüder und Verwandten lag ihnen weniger am Herzen: ihre erste und größte Sorge war die für das Heiligtum.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 19, 'Aber auch die in der Stadt Zurückgebliebenen hatten keine geringe Angst, da sie wegen der im freien Felde zu liefernden Schlacht beunruhigt waren.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 20, 'Als so alle schon der kommenden Entscheidung mit Spannung entgegensahen, die Feinde sich bereits vereinigt hatten und das Heer in Schlachtordnung aufgestellt war, auch die Elefanten an einem geeigneten Orte Stellung gefunden hatten und die Reiterei auf beiden Flügeln wohlgeordnet stand:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 21, 'da, angesichts der heranziehenden Heeresmassen und der verschiedenen Waffengattungen und der Wildheit der Elefanten, streckte der Makkabäer die Hände gegen den Himmel aus und rief den wundertätigen Herrn an, wohl wissend, daß der Sieg nicht durch Waffen erfochten wird, sondern daß Gott ihn denen verleiht, die er dessen würdig erachtet.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 22, 'Er betete aber folgendermaßen: »Du, Herr, hast deinen Engel gesandt zur Zeit Hiskias, des Königs von Juda, und er erschlug von dem Heere Sanheribs 185000 Mann.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 23, 'Sende auch jetzt, Herr des Himmels, einen guten Engel vor uns her, um jenen dort Furcht und Schrecken einzujagen!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 24, 'Laß sie durch die Kraft deines Armes niedergeschmettert werden, sie, die mit Lästerungen gegen dein heiliges Volk heranziehen!« Mehr sagte er damals nicht.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 25, 'Die Truppen Nikanors rückten unterdessen mit Trompetenschall und Kriegsgesängen heran;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 26, 'die des Judas dagegen wurden mit ihnen handgemein, indem sie Gott im Gebet anriefen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 27, 'Und so, mit den Händen kämpfend, mit den Herzen aber zu Gott betend, streckten sie nicht weniger als 35000 Mann nieder, hocherfreut durch Gottes offenbaren Beistand.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 28, 'Nach beendigtem Kampfe aber, als sie voller Freude zurückkehrten, erkannten sie den Nikanor, der in voller Rüstung gefallen war.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 29, 'Da erhoben sie ein großes Geschrei und Getümmel und priesen den Herrn in ihrer vaterländischen Sprache.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 30, 'Judas aber, der immer und überall mit Leib und Seele für seine Mitbürger an erster Stelle gekämpft und von Jugend an die Liebe zu seinen Volksgenossen treu bewahrt hatte, gab den Befehl, man solle dem Nikanor den Kopf und den Arm bis zur Schulter abhauen und beides nach Jerusalem bringen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 31, 'Als er selbst dahin gekommen war, rief er seine Landsleute und die Priester zusammen, ließ sie vor dem Altar Aufstellung nehmen und die Feinde aus der Burg herbeiholen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 32, 'Er zeigte ihnen nun den Kopf des verruchten Nikanor und die Hand des Lästerers, die er in seiner Prahlerei gegen das heilige Haus des Allmächtigen ausgestreckt hatte;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 33, 'dann ließ er dem gottlosen Nikanor die Zunge ausschneiden und stückweise den Vögeln hinwerfen, das übrige aber als Lohn seiner Verruchtheit dem Tempel gegenüber aufhängen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 34, 'Alle aber priesen, zum Himmel gewandt, den Herrn, der sich so offenbar hilfreich erwiesen hatte, und riefen aus: »Gelobt sei der, welcher seine Wohnstätte unbefleckt erhalten hat!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 35, 'Den Kopf Nikanors aber ließ er an der Burg aufhängen als ein deutliches und allen sichtbares Zeichen der Hilfe des Herrn;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 36, 'und durch einmütigen Beschluß der Gemeinde wurde festgesetzt, daß dieser Tag nicht ungefeiert bleiben, sondern festlich begangen werden solle, nämlich am 13. Tage des 12. Monats, der auf syrisch Adar heißt, einen Tag vor dem Mardochäustage.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 37, 'So ist die Geschichte mit Nikanor verlaufen; und da von dieser Zeit an die Hauptstadt in der Gewalt der Hebräer geblieben ist, so will auch ich meinen Bericht hier schließen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 38, 'Wenn ich ihn gut und geschickt abgefaßt habe, so ist das eingetreten, was ich selbst mir vorgenommen hatte; ist er aber schwach und mittelmäßig ausgefallen, so habe ich doch getan, was ich vermochte.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 39, 'Denn wie es unangenehm ist, den Wein allein zu trinken und ebenso auch das Wasser, während Wein mit Wasser vermischt wohlschmeckend ist und einen köstlichen Genuß gewährt, so dient auch die Art, wie man einen Bericht abfaßt, dazu, diejenigen zu ergötzen, denen das Dargestellte vorgetragen wird. Damit will ich schließen!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 40, '');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 1, 1, 'Im zweiten Regierungsjahre des mächtigen Königs Artaxerxes, am ersten Tage des Monats Nisan,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 1, 2, 'hatte Mardochai, der Sohn Jairs, des Sohnes Simeis, des Sohnes des Kis, einen Traum. Er war ein Jude aus dem Stamme Benjamin,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 1, 3, 'der in der Stadt Susa wohnte, ein angesehener Mann, der am königlichen Hofe Dienste leistete.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 1, 4, 'Er stammte von der Gefangenenschar ab, die der babylonische König Nebukadnezar aus Jerusalem zusammen mit Jechonja, dem Könige von Judäa, weggeführt hatte. Und dies war sein Traumgesicht: Siehe, es herrschte Geschrei und Lärm, Donnerschläge, Erdbeben und Schrecken auf der ganzen Erde. Da erschienen plötzlich zwei gewaltige Drachen, beide kampfbereit. Sie stießen ein lautes Gebrüll aus, und infolge ihres Brüllens rüsteten sich alle Völker zum Kampfe, um das Volk der Gerechten zu bekämpfen. Da kam denn ein Tag der Finsternis und des Dunkels, Drangsal und Beängstigung, Not und große Angst über die ganze Erde, und das gesamte gerechte Volk geriet in Angst aus Furcht vor dem drohenden Unheil; sie bereiteten sich auf den Tod vor und schrieen zu Gott um Hilfe. Da entstand infolge ihres Hilferufs wie aus einer kleinen Quelle ein mächtiger Strom, ein gewaltiges Gewässer. Da kam das Tageslicht und die Sonne wieder zum Vorschein, und die Niedergedrückten kamen wieder hoch und fraßen die Hochgeehrten auf. Nachdem nun Mardochai, der diesen Traum gehabt und das gesehen hatte, was Gott zu vollführen gedachte, erwacht war, hielt er das Geschaute in seiner Erinnerung fest und hegte den Wunsch, noch im Verlauf der Nacht zu völliger Klarheit darüber zu gelangen. Mardochai schlief aber im Palast zusammen mit Gabatha und Tharra, den beiden Eunuchen des Königs, die den Palast zu bewachen hatten. Da hörte er ihre Anschläge, bekam Kenntnis von ihren Befürchtungen und erfuhr, daß sie beabsichtigten, Hand an den König Artaxerxes zu legen. Dies zeigte er dem Könige an. Dieser ließ die beiden Eunuchen peinlich verhören, und nachdem sie gestanden hatten, wurden sie zum Tode abgeführt. Hierauf ließ der König diese Vorkommnisse zur Erinnerung aufschreiben, und auch Mardochai fertigte einen schriftlichen Bericht darüber an. Der König übertrug alsdann dem Mardochai die Dienstleistungen im Palast und beschenkte ihn für seine Tat. Es stand aber Haman, der Sohn Hamadathas, der Bugäer, beim Könige in hohen Ehren und ging darauf aus, dem Mardochai und seinem ganzen Volke Unheil zuzufügen wegen der beiden Eunuchen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 2, 1, 'Der Wortlaut dieses Schreibens aber ist folgender: Der Großkönig Artaxerxes läßt an die Statthalter und die ihnen unterstellten Landpfleger der hundertundsiebenundzwanzig Provinzen von Indien bis Äthiopien folgendes Schreiben ergehen:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 2, 2, 'Obgleich ich über viele Völker herrsche und den ganzen Erdkreis in meiner Gewalt habe, bin ich doch darauf bedacht gewesen, mich nicht durch die feste Zuversicht auf meine Macht hinreißen zu lassen, sondern stets mit möglichster Milde und Sanftmut zu regieren, die Lebensverhältnisse meiner Untertanen allezeit friedvoll zu gestalten, das Reich ruhig und bis an die äußersten Grenzen leicht zugänglich zu machen und den von aller Welt ersehnten Frieden immer aufs neue zu sichern.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 2, 3, 'Als ich nun meine Räte befragte, wie dies wohl zustande gebracht werden könnte, hat Haman, der den zweiten Rang im Reiche einnimmt, mein ebensowohl durch Besonnenheit ausgezeichneter als durch unwandelbare Ergebenheit und feste Treue bewährter Minister,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 2, 4, 'uns dargelegt, daß allen Volksstämmen auf der ganzen Erde ein gewisses feindseliges Volk beigemischt sei, das durch seine Gesetze und Bräuche im Gegensatz zu allen anderen Völkern stehe und die Befehle der Könige hartnäckig unbeachtet lasse, so daß die von uns tadellos gehandhabte Reichsregierung nicht zur Ruhe kommen könne.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 2, 5, 'Da wir nun in Betracht gezogen haben, daß einzig und allein dieses Volk allezeit gegen jedermann eine feindliche Stellung einnimmt, infolge seiner Gesetze und Bräuche eine fremdartige Lebensweise führt und in seiner Abneigung gegen unsere Verhältnisse die schlimmsten Übeltaten vollbringt, und zwar so, daß das Reich nicht zu gedeihlicher Ruhe gelangen kann:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 2, 6, 'so haben wir demgemäß angeordnet, daß die im Schreiben Hamans, unsers obersten Reichsbeamten und zweiten Vaters, euch Bezeichneten alle mit Weib und Kind durch das Schwert ihrer Feinde mit der Wurzel ohne alle Gnade und Schonung am vierzehnten Tage des zwölften Monats Adar des gegenwärtigen Jahres ausgerottet werden sollen,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 2, 7, 'damit diese schon längst und auch jetzt feindselig gesinnten Menschen an einem Tage gewaltsam in die Unterwelt hinabfahren und uns für die Zukunft in unsern Verhältnissen bis ans Ende ungestört und unbehelligt lassen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 2, 8, '');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 3, 1, 'In der Erinnerung an alles, was der Herr getan hatte, betete Mardochai folgendermaßen:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 3, 2, '»Herr, Herr, allmächtiger König! In deiner Gewalt steht ja das All, und niemand vermag sich gegen dich aufzulehnen, wenn du Israel retten willst;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 3, 3, 'denn du hast Himmel und Erde geschaffen und alles, was es unter dem Himmel Wunderbares gibt.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 3, 4, 'Du bist Herr über alles, und niemand kann dir, dem Herrn, widerstehen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 3, 5, 'Du weißt alles; du weißt, o Herr, daß ich nicht aus Übermut, nicht aus Überhebung oder Ruhmsucht so gehandelt habe, mich vor dem hochmütigen Haman nicht niederzuwerfen;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 3, 6, 'denn gern wollte ich seine Fußsohlen küssen, um Israel dadurch zu retten.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 3, 7, 'Nein, ich habe so gehandelt, um nicht die Ehre eines Menschen über die Ehre Gottes zu setzen. Ich will mich vor niemand niederwerfen als vor dir, meinem Herrn; und nicht aus Stolz will ich so handeln.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 3, 8, 'Und nun, Herr, mein Gott und König, du Gott Abrahams, schone deines Volkes! denn sie haben unsere Vernichtung im Auge und trachten danach, das dir von Anfang an zugehörige Eigentumsvolk zu vertilgen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 3, 9, 'Laß dein Eigentum nicht unbeachtet, das du dir aus Ägyptenland erkauft hast!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 3, 10, 'Erhöre mein Gebet und sei den dir Angehörigen gnädig! Verwandle unsere Trauer in Freude, damit wir am Leben bleiben und deinen Namen preisen, o Herr, und laß den Mund derer, die dich loben, nicht verstummen!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 3, 11, 'Und alle Israeliten erhoben ein Geschrei, so laut sie konnten; denn der Tod stand ihnen vor Augen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 3, 12, '');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 4, 1, 'Auch die Königin Esther nahm ihre Zuflucht zum Herrn, von Todesangst erfaßt;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 4, 2, 'sie legte ihre prächtigen Gewänder ab und zog Gewänder der Betrübnis und Trauer an, und statt der kostbaren Salben bedeckte sie ihr Haupt mit Asche und Schmutz; sie kasteite ihren Leib hart und bedeckte alle Stellen ihres Körpers, die sonst mit reizendem Schmuck geziert waren, mit ihren aufgelösten Haarflechten.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 4, 3, 'Dann richtete sie an den Herrn, den Gott Israels, folgendes Gebet:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 4, 4, '»O mein Herr, du allein bist unser König! komm mir zu Hilfe, ich bin verlassen und habe keinen Helfer als dich, und Gefahr steht unmittelbar vor mir.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 4, 5, 'Von Geburt an habe ich im Kreise meiner Familie gehört, daß du, Herr, Israel aus allen Völkern herausgenommen und unsere Väter aus allen ihren Vorfahren zum ewigen Eigentumsvolke erwählt und alle deine Verheißungen an ihnen erfüllt hast.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 4, 6, 'Jetzt aber haben wir vor dir gesündigt, und du hast uns der Gewalt unserer Feinde preisgegeben zur Strafe dafür, daß wir ihre Götter verehrt haben; du bist gerecht, o Herr!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 4, 7, 'Jetzt aber lassen sie sich nicht an dem bittern Lose unserer Knechtschaft genügen, sondern sie haben ihren Götzen in die Hände zugeschworen, die Bestimmung deines Mundes zu vereiteln, dein Eigentumsvolk auszurotten und den Mund derer, die dir lobsingen, verstummen zu machen, den Glanz deines Hauses und deines Altars auszutilgen, den Heiden den Mund zu öffnen zum Preise ihrer nichtigen Götzen und einem irdischen Könige Bewunderung auf ewig zu verschaffen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 4, 8, 'Überlaß, o Herr, dein Zepter nicht denen, die nichts sind, und laß sie über unsere Vernichtung nicht hohnlachen, sondern laß ihren Anschlag zu ihrem eigenen Verderben ausschlagen und mache den, der dies gegen uns ins Werk gesetzt hat, zu einem warnenden Beispiel!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 4, 9, 'Gedenke unser, o Herr! Gib dich uns zu erkennen zur Zeit unserer Not und verleihe mir Kraft, du König der Götter und Herr aller Gewalt!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 4, 10, 'Lege gewinnende Worte in meinen Mund angesichts des Löwen und wende sein Herz zum Haß gegen unsern Widersacher, zu seinem und seiner Gesinnungsgenossen Verderben!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 4, 11, 'Uns aber rette durch deine Hand und hilf mir, der Verlassenen, die niemand hat als dich, o Herr!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 4, 12, 'Du weißt alle Dinge, du weißt auch, daß ich die Herrlichkeit der Gottlosen hasse und daß ich das Lager der Unbeschnittenen und aller Fremden verabscheue. Du kennst den Zwang meiner Lage, daß ich das Zeichen der Hoffart verabscheue, das ich auf dem Haupte trage, wenn ich mich öffentlich zeigen muß. Ich verabscheue es wie ein blutbeflecktes Tuch, und ich trage es nicht an den Tagen, wo ich ruhig für mich bin. Auch hat deine Magd nie am Tische Hamans gegessen, und nie habe ich ein Trinkgelage des Königs verherrlichen helfen, auch nie Wein von Trankopfern genossen. Auch hat deine Magd keine Freude mehr gehabt seit dem Tage ihrer Lebensveränderung bis heute als nur an dir, o Herr, du Gott Abrahams. O Gott, der du gewaltig bist über alle, erhöre den Hilferuf der Verzweifelnden und rette uns aus der Hand der Übeltäter! Befreie auch mich von meiner Angst!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 5, 1, 'Am dritten Tage, als sie zu beten aufgehört hatte, legte sie die Kleider ihres Gottesdienstes ab und legte ihre Prachtgewandung an.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 5, 2, 'Nachdem sie sich so herrlich geschmückt und den alles erschauenden Gott und Retter angerufen hatte, nahm sie die beiden Zofen zu sich,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 5, 3, 'auf deren eine sie sich stützte als eine vornehme Frau,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 5, 4, 'während die andere hinter ihr herging und ihr die Schleppe trug.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 5, 5, 'Und sie selbst strahlte im vollen Glanz ihrer Schönheit, und ihr Antlitz war heiter und liebreizend, aber ihr Herz war beklommen vor Angst.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 5, 6, 'Nachdem sie nun alle Türen durchschritten hatte, trat sie vor den König. Dieser saß auf dem Throne seines Königreiches und war mit seiner ganzen Prachtgewandung angetan, ging mit Gold und Edelsteinen bedeckt und furchterweckend anzusehen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 5, 7, 'Als nun der König sein von Hoheit strahlendes Angesicht erhob, blickte er sie mit dem höchsten Zorn an. Da fiel die Königin zu Boden, verfärbte sich infolge einer Ohnmacht und lehnte sich auf den Kopf der Zofe, die vor ihr her ging.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 5, 8, 'Da wandelte Gott den Sinn des Königs zur Sanftmut um; von Angst befallen, sprang er von seinem Thron herab und nahm sie in seine Arme, bis sie wieder zu sich kam. Dabei redete er ihr freundlich zu mit den Worten:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 5, 9, '»Was ist dir, Esther? Ich bin dein Bruder; fasse Mut: du sollst nicht sterben!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 5, 10, 'Unsere Verordnung gilt ja nur im allgemeinen; komm her!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 5, 11, 'Hierauf erhob er seinen goldenen Stab, legte ihn ihr auf den Nacken, umarmte sie und sagte: »Sprich dich gegen mich aus!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 5, 12, 'Da sagte sie zu ihm: »Als ich dich erblickte, o Herr, warst du mir wie ein Engel Gottes, und mein Herz erschrak aus Furcht vor deiner Herrlichkeit; denn du bist bewundernswert, o Herr, und dein Angesicht ist voller Anmut!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 5, 13, 'Während sie aber so redete, fiel sie aufs neue ohnmächtig nieder.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 5, 14, 'Der König geriet in Aufregung, und seine ganze Dienerschaft sprach ihr zu.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 5, 15, '');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 5, 16, '');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 6, 1, 'Hier folgt die Abschrift des Schreibens: Großkönig Artaxerxes entbietet den hundertsiebenundzwanzig Statthaltern von Indien bis Äthiopien, den Verwaltern der Landschaften und allen, die uns wohlgesinnt sind, seinen Gruß.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 6, 2, 'Viele, die durch die übergroße Güte ihrer Wohltäter allzusehr geehrt werden, trachten nach noch Höherem');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 6, 3, 'und suchen nicht nur unseren Untertanen Schaden zuzufügen, sondern, weil sie das Übermaß ihres Glückes nicht zu ertragen vermögen, unternehmen sie es sogar, gegen ihre Wohltäter Anschläge ins Werk zusetzen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 6, 4, 'Indem sie nicht nur das Gefühl der Dankbarkeit in den Menschen zerstören, sondern sich auch durch das prahlerische Gerede derer, die keine Wohltaten empfangen, sich ermutigen lassen, wähnen sie, dem das Böse hassenden Strafgericht des allwissenden Gottes entrinnen zu können.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 6, 5, 'Oft hat aber auch böse Überredungskunst viele von den höheren Staatsbeamten, die doch mit der Sorge für die Angelegenheiten ihrer Freunde betraut worden sind, zu Mitschuldigen an unschuldig vergossenem Blute gemacht und in unheilbares Unglück verstrickt,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 6, 6, 'wenn jene durch die lügnerische Täuschung der sittlichen Schlechtigkeit das arglose Wohlwollen der Regierenden täuschend hintergehen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 6, 7, 'Zu ersehen ist das nicht sowohl aus den älteren Geschichten, für deren Überlieferung wir gesorgt haben, als vielmehr, indem ihr das, was ihr unmittelbar vor Augen habt, genau ins Auge faßt, nämlich die frevelhaften Taten, die durch die nichtswürdige Bosheit der höchsten Reichsbeamten verübt worden sind.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 6, 8, 'Und für die Folgezeit ist darauf zu achten, daß wir das Reich allen Menschen in festgeordnetem und friedlichem Zustande darbieten, indem wir die erforderlichen Veränderungen vornehmen und das, was uns vor die Augen kommt, immer mit möglichster Milde beurteilen und behandeln.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 6, 9, 'Wie denn auch Haman, der Sohn Hamadathas, ein Mazedonier, der tatsächlich dem Geblüt der Perser fernsteht und sich von unserer Ehrenhaftigkeit völlig losgesagt hat, gastlich von uns aufgenommen, – er hatte die Menschenfreundlichkeit, die wir gegen alle Völker hegen, in solchem Grade erfahren, daß er öffentlich als unser Vater bezeichnet und als die zweite Person nach dem königlichen Thron von allen immerfort durch Niederfallen geehrt wurde, – seinen Hochmut nicht hat zügeln können, sondern darauf ausgegangen ist, uns der Herrschaft und des Lebens zu berauben, und unsern Lebensretter und immerwährenden Wohltäter Mardochai und auch Esther, die unsträfliche Genossin des Königsthrones, samt allen ihren Volksgenossen durch arglistige Vorspiegelungen und Ränke in den gewaltsamen Tod hat bringen wollen. Denn durch diese Künste hoffte er, wenn er uns vereinsamt gemacht hätte, die Oberherrschaft der Perser auf die Mazedonier zu übertragen. Wir aber finden, daß die von dem Erzschurken der Vernichtung preisgegebenen Juden keine Verbrecher sind, sondern nach durchaus gerechten Gesetzen und Bräuchen im Staate leben und daß sie Kinder des höchsten, größten, lebendigen Gottes sind, der uns und unseren Vorfahren das Reich im schönsten Zustande erhalten hat. Ihr werdet also wohl tun, wenn ihr keinen Gebrauch von dem Schreiben macht, welches Haman, der Sohn Hamadathas, abgesandt hat, weil er um seiner Böstaten willen vor den Toren von Susa mit seiner ganzen Familie aufgehängt worden ist, indem der allwaltende Gott das wohlverdiente Gericht an ihm vollzogen hat. Eine Abschrift dieses Schreibens sollt ihr aber in allen Ortschaften öffentlich aushängen, daß man nämlich den Juden gestatte, nach ihren eigenen Gesetzen und Bräuchen zu leben, und daß man ihnen Beistand leiste, damit sie sich derer, die sie zur Zeit ihrer Bedrängnis am dreizehnten Tage des zwölften Monats Adar angreifen, an eben diesem Tage erwehren können; denn dieser Tag hat der über alles waltende Gott dem erwählten Volke statt zum Verderben zu einem Freudentage gemacht. So feiert ihr denn nun neben euren anerkannten Festen einen besonders ausgezeichneten Tag mit aller Fröhlichkeit, damit er sowohl jetzt als auch in der Folgezeit für euch und für die euch wohlgesinnten Perser ein Tag des Heils sei, für die aber, welche uns nachstellen, eine Erinnerung an das Verderben. Jede Stadt aber oder Landschaft ohne Ausnahme, die nicht nach diesem Erlaß verfährt, soll mit Waffengewalt und Feuer unnachsichtlich verheert werden, so daß sie nicht nur den Menschen unzugänglich, sondern auch den wilden Tieren und den Vögeln für alle Zeit zum Abscheu wird«. Abschriften (dieses Erlasses) sollen weithin sichtbar im ganzen Königreiche ausgehängt werden, und alle Juden sollen sich auf den genannten Tag zum Kampfe mit ihren Gegnern bereit halten«.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 7, 1, 'Und Mardochai sagte: »Von Gott ist dies geschehen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 7, 2, 'Ich gedenke des Traumbildes, das mir über diese Begebenheiten erschienen ist; denn keine einzige von ihnen ist unerfüllt geblieben.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 7, 3, 'Die kleine Quelle, die zu einem Strome wurde, und es war auch ein Licht und die Sonne und viel Wasser da: –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 7, 4, 'Esther ist der Strom, sie, die der König geehelicht und zur Königin gemacht hat. Die beiden Drachen aber – das bin ich und Haman.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 7, 5, 'Und die Völker – das sind die, welche sich versammelten, um den Namen der Juden auszutilgen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 7, 6, 'Mein Volk aber – das sind die Israeliten, die zu Gott schrieen und gerettet wurden. Ja, der Herr hat sein Volk gerettet und der Herr hat uns aus allen diesen Leiden erlöst; und Gott ist’s gewesen, der die Zeichen und die großen Wunder vollbracht hat, wie solche noch nie unter den Völkern geschehen sind.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 7, 7, 'Darum hat Gott zwei Lose gemacht, eines für das Volk Gottes und eines für alle anderen Völker.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 7, 8, 'Und diese beiden Lose sind zur festgesetzten Zeit und Stunde eingetroffen, und zwar auf den Tag des Gerichts vor Gott (für sein Volk) und für alle Völker. Und Gott hat seines Volkes gedacht und seinem Eigentumsvolke Gerechtigkeit zuteil werden lassen. Und es sollen von ihnen diese Tage im Monat Adar, am vierzehnten und am fünfzehnten Tage eben dieses Monats, mit Festversammlung und mit Freude und Fröhlichkeit vor Gott gefeiert werden von Geschlecht zu Geschlecht auf ewige Zeit in seinem Volke Israel.« Im vierten Regierungsjahre des Ptolemäus und der Kleopatra haben Dositheus, der sich für einen Priester und Leviten ausgab, und sein Sohn Ptolemäus das vorliegende Schreiben über das Purimfest (nach Ägypten) hergebracht; sie behaupteten, das Schreiben sei echt, und Lysimachus, der Sohn des Ptolemäus, der in Jerusalem wohne, habe es übersetzt.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 1, 1, 'Es wohnte ein Mann in Babylon namens Jojakim.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 1, 2, 'Er hatte eine Frau namens Susanna geheiratet, die Tochter Hilkias, die sehr schön war und den Herrn fürchtete;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 1, 3, 'auch ihre Eltern waren rechtschaffen und hatten ihre Tochter unterwiesen nach dem Gesetz Mose’s.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 1, 4, 'Jojakim war aber sehr reich, und ihm gehörte ein Lustgarten, der an sein Haus anstieß; und bei ihm kamen die Juden zusammen, weil er angesehener war als sie alle.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 1, 5, 'Und es wurden zwei Älteste aus dem Volk als Richter gewählt in jenem Jahre – von denen der Herr gesagt hat: »Gesetzlosigkeit ist von Babylon ausgegangen von seinen Ältesten (und) Richtern, die das Volk (wohl) zu regieren schienen« –:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 1, 6, 'die gingen aus und ein in Jojakims Hause, und es kamen zu ihnen alle, die einen Rechtshandel hatten.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 1, 7, 'Wenn dann das Volk um Mittag sich verlaufen hatte, ging Susanna hin und erging sich im Lustgarten ihres Mannes.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 1, 8, 'Da nun die beiden Ältesten sie täglich hingehen und lustwandeln sahen, entbrannten sie in Begierde nach ihr;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 1, 9, 'sie verkehrten ihren Sinn und lenkten ihre Augen ab, so daß sie nicht zum Himmel emporsahen und der gerechten Gerichte (Gottes) nicht gedachten.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 1, 10, 'Sie waren beide von Liebe zu ihr entbrannt, doch keiner teilte dem andern sein Liebesweh mit,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 1, 11, 'denn sie schämten sich, von ihrer Begierde, mit ihr zusammen zu sein, Mitteilung zu machen;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 1, 12, 'doch waren sie Tag für Tag eifrig bemüht, sie zu Gesicht zu bekommen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 1, 13, 'Da sagte (eines Tags) einer zum andern: »Laß uns nach Hause gehen, denn es ist Essens Zeit«. So trennten sie sich also beim Hinausgehen voneinander,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 1, 14, 'kehrten dann aber um und trafen an derselben Stelle wieder zusammen. Und da sie sich gegenseitig ausfragten, gestanden sie als Ursache ihre Begierde (nach ihr) ein. Hierauf setzten sie gemeinsam eine Zeit fest, wo sie sie allein treffen könnten.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 1, 15, 'Wie sie nun so einen günstigen Tag abpaßten, begab es sich, daß sie nach ihrer Gewohnheit in den Garten ging, nur mit zwei Mädchen, und sich dort zu baden wünschte, weil es sehr heiß war;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 1, 16, 'und es war dort niemand zugegen außer den beiden Ältesten, die sich versteckt hatten, um sie zu belauern.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 1, 17, 'Sie sagte dann zu den Mädchen: »Holt mir Öl und Salben und schließt die Türen des Gartens, damit ich mich baden kann«.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 1, 18, 'Sie taten nach ihrem Geheiß, verschlossen die Gartentüren und gingen durch die Hintertür hinaus, um das Verlangte zu holen; sie sahen aber die Ältesten nicht, denn die hielten sich versteckt.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 1, 19, 'Als nun die Mädchen hinausgegangen waren, erhoben sich die beiden Ältesten, liefen auf sie zu und sagten:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 1, 20, '»Siehe, die Türen des Gartens sind verschlossen und niemand sieht uns; wir sind in Liebe zu dir entbrannt; darum sei uns zu Willen und gib dich uns hin.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 1, 21, 'Wo nicht, so werden wir gegen dich bezeugen, daß ein junger Mann mit dir zusammen gewesen sei und du deshalb die Mädchen weggeschickt habest«.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 1, 22, 'Da seufzte Susanna und sagte: »Bedrängnis umgibt mich von allen Seiten! denn wenn ich das tue, steht der Tod mir bevor; und tue ich’s nicht, so werde ich euren Händen nicht entgehen;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 1, 23, 'aber besser ist es doch für mich, es nicht zu tun und in eure Hände zu fallen, als vor dem Herrn zu sündigen«.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 1, 24, 'Hierauf schrie Susanna mit lauter Stimme, aber auch die beiden Ältesten schrieen wider sie;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 1, 25, 'und einer von ihnen lief hin und öffnete die Tür des Gartens.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 1, 26, 'Als nun die Leute im Hause das Geschrei im Garten vernahmen, eilten sie durch die Hintertür hinein, um zu sehen, was ihr widerfahren sei.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 1, 27, 'Als aber die Ältesten ihre Aussage gemacht hatten, wurden die Diener sehr beschämt; denn noch niemals war so etwas der Susanna nachgesagt worden.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 1, 28, 'Als nun am andern Tage das Volk bei ihrem Manne Jojakim zusammenkam, stellten sich auch die beiden Ältesten ein, erfüllt mit dem ruchlosen Gedanken wider Susanna, sie ums Leben zu bringen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 1, 29, 'Sie sagten also vor dem Volke: »Laßt Susanna, Hilkias Tochter, die Frau Jojakims, herkommen!« Man holte sie herbei,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 1, 30, 'und sie kam mit ihren Eltern, ihren Kindern und allen ihren Verwandten;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 1, 31, 'Susanna aber war sehr üppigen Wuchses und schön von Angesicht.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 1, 32, 'Da befahlen die ruchlosen Männer, man solle ihr den Schleier abnehmen – denn sie war verschleiert –, damit sie sich an ihrer Schönheit weiden könnten.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 1, 33, 'Ihre Angehörigen aber weinten und alle, die sie sahen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 1, 34, 'Es erhoben sich aber die beiden Ältesten inmitten des Volkes und legten ihre Hände auf ihr Haupt;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 1, 35, 'sie aber schaute weinend zum Himmel empor, denn ihr Herz vertraute auf den Herrn.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 1, 36, 'Die Ältesten sagten sodann aus: »Während wir allein im Garten umhergingen, kam diese herein mit zwei Mädchen; sie ließ die Gartentüren schließen und schickte die Mädchen fort.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 1, 37, 'Da kam zu ihr ein junger Mann, der versteckt gewesen war, und legte sich zu ihr.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 1, 38, 'Wir aber, die wir uns in einem Winkel des Gartens befanden, liefen beim Anblick dieser Schandtat auf die beiden zu;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 1, 39, 'und nachdem wir ihr Zusammensein gesehen, konnten wir zwar jenes Menschen, weil er stärker als wir war und die Tür öffnete und hinaussprang, nicht habhaft werden;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 1, 40, 'diese aber ergriffen wir und fragten sie, wer der junge Mann wäre; doch sie wollte es uns nicht sagen. Solches bezeugen wir!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 1, 41, 'Und die Versammlung schenkte ihnen, als Ältesten des Volkes und als Richtern Glauben, und man verurteilte sie zum Tode.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 1, 42, 'Susanna aber brach in laute Wehklage aus und sagte: »O ewiger Gott, der du das Verborgene kennst und alles weißt, bevor es geschieht:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 1, 43, 'du weißt, daß sie falsches Zeugnis wider mich abgelegt haben; und nun muß ich sterben, ohne irgend etwas von dem getan zu haben, dessen jene mich böslich beschuldigen!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 1, 44, 'Und der Herr erhörte ihr Rufen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 1, 45, 'Denn als sie zur Hinrichtung abgeführt wurde, erweckte Gott den heiligen Geist eines ganz jungen Mannes namens Daniel;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 1, 46, 'der rief mit lauter Stimme aus: »Ich bin unschuldig an dem Blute dieser Frau!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 1, 47, 'Alles Volk wandte sich ihm zu und man fragte: »Was willst du mit diesem deinem Ausruf besagen?«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 1, 48, 'Er aber trat mitten unter sie und sagte: »Sind denn die Kinder Israel solche Toren? Ohne Untersuchung und ohne Gewißheit erlangt zu haben, verurteilt ihr eine Tochter Israels?');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 1, 49, 'Kehrt ins Gerichtshaus zurück, denn diese haben falsches Zeugnis wider sie abgelegt!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 1, 50, 'Da kehrte das ganze Volk eilig wieder um. Und die Ältesten sagten zu ihm: »Komm her, setze dich in unsre Mitte und berichte uns! Denn Gott selbst hat dir das Vorrecht des Alters verliehen!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 1, 51, 'Daniel aber sagte zu ihnen: »Trennt sie weit voneinander, dann will ich sie verhören«.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 1, 52, 'Nachdem sie nun voneinander getrennt waren, rief er den einen von ihnen und sagte zu ihm: »Du in einem gottlosen Leben Ergrauter! jetzt kommen deine vormals begangenen Sünden über dich,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 1, 53, 'da du ungerecht gerichtet, Unschuldige verurteilt und Schuldige freigesprochen hast, während doch Gott gebietet: ›Den Schuldlosen und Gerechten sollst du nicht umbringen!‹');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 1, 54, 'Nun denn, wenn du diese Frau wirklich gesehen hast, so sage doch: Unter was für einem Baume hast du sie beieinander gesehen?« Er antwortete: »Unter einem Mastixbaum«.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 1, 55, 'Daniel erwiderte ihm: »Richtig gelogen hast du wider dein eigenes Haupt; denn bereits hat der Engel Gottes Befehl von Gott erhalten und wird dich mitten durch zerhauen!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 1, 56, 'Nachdem er dann diesen hatte wegbringen lassen, hieß er den andern herbeiführen und sagte zu ihm: »Du Kanaaniter und Nichtjude! Die Schönheit hat dich betört, und die Sinnenlust hat dein Herz verkehrt.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 1, 57, 'So habt ihr’s überhaupt mit den Töchtern Israels gemacht, und sie sind euch aus Furcht zu Willen gewesen; aber eine Tochter Juda’s hat sich eurer Ruchlosigkeit nicht gefügt.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 1, 58, 'So sage mir nun: Unter was für einem Baume hast du sie beieinander gesehen?« Er antwortete: »Unter einer Eiche«.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 1, 59, 'Daniel sagte zu ihm: »Geradeswegs hast auch du wider dein eigenes Haupt gelogen; denn es steht schon der Engel Gottes bereit, mit dem Schwerte dich mittendurch zu zerhauen, damit er euch ausrotte!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 1, 60, 'Da brach die ganze Versammlung in laute Rufe aus und pries Gott, der die auf ihn Hoffenden rettet.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 1, 61, 'Und sie erhoben sich wider die zwei Ältesten, weil Daniel sie nach ihren eigenen Aussagen als falsche Zeugen erwiesen hatte;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 1, 62, 'und man verfuhr mit ihnen, wie sie dem Nächsten zu tun gedacht hatten, nach dem Gesetz Mose’s und tötete sie. So wurde unschuldiges Blut an jenem Tage gerettet.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 1, 63, 'Hilkia aber und sein Weib priesen Gott wegen ihrer Tochter, samt Jojakim, ihrem Manne, und allen ihren Verwandten, weil nichts Schandbares an ihr gefunden worden war.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 1, 64, 'Daniel aber stand in hohem Ansehen bei dem Volke von jenem Tage an und fernerhin.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 2, 1, 'Als der König Astyages zu seinen Vätern eingegangen war, hatte der Perser Cyrus sein Reich übernommen;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 2, 2, 'Daniel aber war der Tischgenosse des Königs und angesehener als alle übrigen seiner Freunde.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 2, 3, 'Nun hatten die Babylonier ein Götzenbild namens Bel, für welches täglich zwölf Scheffel Weizenmehl, vierzig Schafe und sechs Metreten Wein verwandt wurden.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 2, 4, 'Der König verehrte ihn und ging Tag für Tag hin, ihn anzubeten; Daniel aber betete seinen Gott an. Da fragte ihn der König: »Warum betest du den Bel nicht an?«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 2, 5, 'Er erwiderte: »Ich verehre keine von Händen gemachte Bildgötter, sondern nur den lebendigen Gott, der Himmel und Erde geschaffen hat und Herr über die ganze Menschheit ist«.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 2, 6, 'Da sagte der König zu ihm: »Du hältst also den Bel nicht für einen lebendigen Gott? Siehst du denn nicht, wie viel er täglich ißt und trinkt?«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 2, 7, 'Daniel aber lachte und sagte: »Laß dich nicht betören, o König! denn dieser da ist inwendig von Ton und auswendig von Erz und hat noch niemals etwas gegessen«.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 2, 8, 'Darüber geriet der König in Zorn, ließ seine Priester rufen und sagte zu ihnen: »Wenn ihr mir nicht sagt, wer diese Opfergaben verzehrt, so müßt ihr sterben;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 2, 9, 'beweist ihr mir aber, daß Bel sie verzehrt, so muß Daniel sterben, weil er eine Gotteslästerung gegen Bel ausgesprochen hat«. Und Daniel sagte zum Könige: »Es geschehe, wie du gesagt hast«.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 2, 10, 'Die Belspriester aber waren siebenzig an der Zahl, ohne die Weiber und Kinder. Hierauf begab sich der König mit Daniel in den Tempel Bels.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 2, 11, 'Da sagten die Belspriester: »Siehe, wir begeben uns hinaus; setze du nun selbst, o König, die Speisen vor, stelle den Wein, nachdem du ihn gemischt hast, hin, verschließe dann die Tür und versiegle sie mit deinem Ringe;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 2, 12, 'und wenn du frühmorgens kommst und nicht alles von Bel aufgezehrt findest, so wollen wir sterben, andernfalls aber Daniel, der wider uns gelogen hat«.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 2, 13, 'Sie waren aber ohne Sorge, weil sie unter dem Opfertische einen heimlichen Gang hergerichtet hatten, durch den sie regelmäßig einzugehen und dann alles zu verzehren pflegten.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 2, 14, 'Nachdem jene nun hinausgegangen waren, setzte der König dem Bel die Speisen vor. Daniel aber gab seinen Dienern Befehl, und sie brachten Asche herbei und bestreuten damit den ganzen Tempel vor den Augen des allein anwesenden Königs; dann gingen sie hinaus, verschlossen die Tür, versiegelten sie mit des Königs Ringe und gingen weg.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 2, 15, 'Die Priester aber kamen in der Nacht nach ihrer Gewohnheit mit ihren Weibern und Kindern und verzehrten und tranken alles.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 2, 16, 'Der König aber fand sich am andern Morgen früh ein, und Daniel war bei ihm.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 2, 17, 'Der König fragte nun: »Daniel, sind die Siegel unversehrt?« Er antwortete: »Jawohl, o König«.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 2, 18, 'Sodann warf der König gleich beim Öffnen der Tür einen Blick auf den Opfertisch und rief mit lauter Stimme: »Groß bist du, Bel, und kein Betrug ist bei dir zu finden!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 2, 19, 'Daniel aber lachte und hielt den König zurück, daß er nicht hineinginge, und sagte: »Sieh doch den Fußboden an und sieh zu, wessen Fußspuren das sind!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 2, 20, 'Der König sagte: »Ich sehe die Fußspuren von Männern, Weibern und Kindern«.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 2, 21, 'Da wurde der König zornig und ließ die Priester samt ihren Weibern und Kindern festnehmen, und sie zeigten ihm die verborgene Tür, durch die sie hineingegangen waren, um die auf dem Tische aufgelegten Gaben zu verzehren.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 2, 22, 'Der König ließ sie töten und gab den Bel dem Daniel preis, der ihn samt seinem Tempel zerstörte.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 2, 23, 'Es war da auch ein großer Drache, den verehrten die Babylonier als Gott.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 2, 24, 'Und der König sagte zu Daniel: »Wirst du etwa auch von diesem sagen, daß er Erz sei? Siehe, er lebt, frißt und trinkt; du kannst nicht behaupten, daß er kein lebendiger Gott sei. Bete ihn also an!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 2, 25, 'Doch Daniel antwortete: »Den Herrn, meinen Gott, will ich anbeten, denn er ist der lebendige Gott!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 2, 26, 'Du aber, o König, gib mir Erlaubnis, so will ich den Drachen ohne Schwert und Stock töten«. Der König sagte: »Ich gewähre es dir«.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 2, 27, 'Da nahm Daniel Pech, Fett und Haare, kochte dies zusammen, machte Kuchen daraus, warf sie dem Drachen ins Maul; und als der Drache sie gefressen hatte, zerbarst er. Dann rief er aus: »Seht, das sind eure Götter!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 2, 28, 'Als nun die Babylonier den Vorfall erfuhren, wurden sie sehr unwillig, verschworen sich gegen den König und sagten: »Ein Jude ist der König geworden: den Bel hat er zerstört, den Drachen getötet und die Priester umgebracht!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 2, 29, 'So kamen sie denn zum Könige und sagten: »Liefere uns den Daniel aus; wo nicht, so werden wir dich samt deinem Hause töten!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 2, 30, 'Da nun der König sah, daß sie ihn sehr bedrängten, lieferte er ihnen den Daniel notgedrungen aus.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 2, 31, 'Sie warfen ihn in die Löwengrube; und er blieb sechs Tag lang darin.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 2, 32, 'Es befanden sich aber in der Grube sieben Löwen, denen man täglich zwei Leichen und zwei Schafe gab; jetzt aber gab man ihnen nichts, damit sie den Daniel auffräßen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 2, 33, 'Nun lebte damals der Prophet Habakuk in Judäa; der hatte einen Brei gekocht und Brote in eine Schale eingebrockt und ging damit aufs Feld hinaus, um es den Schnittern zu bringen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 2, 34, 'Da sagte der Engel des Herrn zu Habakuk: »Bringe das Mahl, das du da hast, nach Babylon dem Daniel in die Löwengrube!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 2, 35, 'Habakuk antwortete: »Herr, Babylon habe ich nie gesehen, und von der (Löwen)grube weiß ich nichts.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 2, 36, 'Da ergriff der Engel des Herrn ihn am Kopfe, faßte ihn bei den Haaren und versetzte ihn mit der Schnelligkeit seines Hauches nach Babylon, oben an die Grube..');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 2, 37, 'Da rief Habakuk: »Daniel, Daniel, nimm das Mahl, das Gott dir sendet!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 2, 38, 'Da sagte Daniel: »Ja, du hast meiner gedacht, o Gott, und verläßt die nicht, welche dich lieben!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 2, 39, 'Und Daniel erhob sich und aß; der Engel Gottes aber brachte den Habakuk sofort wieder in seine Heimat zurück.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 2, 40, 'Am siebenten Tage kam der König, um Daniel zu betrauern; als er aber an die Grube trat und hineinschaute, sah er Daniel da sitzen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 2, 41, 'Da rief er mit lauter Stimme: »Groß bist du, Herr, du Gott Daniels, und es gibt außer dir keinen andern!« Und er ließ ihn herausziehen; diejenigen aber, welche ihn hatten umbringen wollen, ließ er in die Grube werfen, und sie wurden sofort vor seinen Augen aufgefressen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 3, 1, 'Asarja trat hin und betete also; er tat seinen Mund auf und dankte dem Herrn (zugleich mit seinen Genossen inmitten des Feuers) und sprach:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 3, 2, '»Gelobt und gepriesen seist du, Herr, du Gott unserer Väter, und verherrlicht sei dein Name in alle Ewigkeit!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 3, 3, 'Denn gerecht bist du in allem, was du an uns getan hast, und alle deine Werke sind wahrhaftig und deine Wege richtig und alle deine Gerichte wahrhaftig.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 3, 4, 'Gerichte der Wahrheit hast du ausgerichtet in allem, was du über uns hast kommen lassen und über Jerusalem, unsrer Väter heilige Stadt; denn in Wahrheit und mit Recht hast du das alles getan wegen unsrer Sünden.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 3, 5, 'Denn gesündigt haben wir in allem und übel getan damit, daß wir von dir abgefallen sind,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 3, 6, 'und haben uns in allem verfehlt und nicht gehört auf deines Gesetzes Gebote, noch sie gehalten, auch nicht getan, wie du uns befohlen hattest, damit es uns wohl ergehe.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 3, 7, 'Doch nun: alles, was du über uns hast kommen lassen, und alles, was du uns angetan hast, das hast du in wahrhaftem Gerichte getan;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 3, 8, 'und hast uns in die Hände unsrer Feinde gegeben, ruchloser und feindseligster Abtrünniger, und einem Könige, der ungerecht ist und schlimmer als die Herrscher auf der ganzen Erde.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 3, 9, 'Und nun dürfen wir unsren Mund nicht auftun; Schmach und Schimpf ist deinen Knechten und deinen Verehrern zuteil geworden.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 3, 10, 'Gib uns nicht auf immer preis um deines Namens willen und brich deinen Bund nicht!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 3, 11, 'Laß auch dein Erbarmen nicht von uns weichen, um Abrahams, deines Geliebten, und Isaaks, deines Knechts, und Israels, deines Heiligen, willen,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 3, 12, 'denen du ja verheißen hast, ihr Same solle gemehrt werden gleich den Sternen am Himmel und gleich dem Sand am Ufer des Meeres.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 3, 13, 'Denn wir sind, o Herrscher, klein geworden vor allen Völkern und sind heute niedrig auf der ganzen Erde um unsrer Sünden willen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 3, 14, 'Auch haben wir in dieser Zeit keinen Fürsten noch Propheten noch Anführer, weder Brandopfer noch Schlachtopfer noch Speisopfer, noch Räucherwerk, auch keinen Ort, dir die Erstlinge darzubringen und Gnade zu erlangen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 3, 15, 'Doch mit zerknirschtem Herzen und zerschlagenem Geist möchten wir von dir angenommen werden.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 3, 16, 'Als brächten wir Ganzopfer von Widdern und Stieren und Tausende von fetten Schafen dar, so laß heute unser Opfer vor dich kommen und Versöhnung stattfinden vor deinem Angesicht! denn die dir vertrauen, werden nicht zu Schanden.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 3, 17, 'Und nun sind wir dir von ganzem Herzen gehorsam und fürchten dich und suchen dein Angesicht.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 3, 18, 'Laß uns nicht zu Schanden werden, sondern verfahre mit uns nach deiner Milde und nach der Fülle deines Erbarmens,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 3, 19, 'und errette uns nach deinen Wundertaten und gib deinem Namen die Ehre, o Herr! Und schämen müssen sich alle, die deinen Knechten Übles zugefügt haben;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 3, 20, 'zu Schanden laß sie werden mit aller ihrer Herrschaft, und ihre Macht werde zertrümmert!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 3, 21, 'Erkennen müssen sie, daß du der alleinige Herr Gott bist und herrlich über den ganzen Erdkreis hin!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 3, 22, 'Die Diener des Königs aber, die sie hineingeworfen hatten, ließen nicht ab, den Ofen zu heizen mit Naphtha und Werg und Pech und Reisig;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 3, 23, 'und die Flamme schlug gegen 49 Ellen über den Ofen empor');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 3, 24, 'und fraß um sich und verbrannte um den Ofen her, wen sie von den Chaldäern erreichte.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 3, 25, 'Aber ein Engel des Herrn war zugleich mit Asarja und seinen Gefährten in den Ofen hinabgestiegen und hatte die Feuerflammen aus dem Ofen hinausgetrieben');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 3, 26, 'und bewirkt, daß der Innenraum des Ofens so war, wie wenn ein kühlender Tauwind ihn durchwehte. So berührte also das Feuer sie überhaupt nicht, tat ihnen auch nicht wehe und belästigte sie nicht.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 3, 27, 'Da hoben die drei wie mit einem Munde an zu singen; sie priesen und lobten Gott in dem Ofen mit den Worten:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 3, 28, '»Gelobt seist du, Herr, Gott unsrer Väter, gepriesen und hochgerühmt in Ewigkeit,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 3, 29, 'und gelobt sei dein herrlicher, heiliger Name, hocherhoben und hochgerühmt in alle Ewigkeit!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 3, 30, 'Gelobt seist du im Tempel deiner heiligen Herrlichkeit und hochgepriesen und hochverherrlicht in Ewigkeit!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 3, 31, 'Gelobt seist du auf dem Thron deines Königtums und gepriesen und hochgerühmt in Ewigkeit!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 3, 32, 'Gelobt seist du, der du die Tiefen schaust, sitzend auf den Keruben, gelobt und verherrlicht in Ewigkeit!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 3, 33, 'Gelobt seist du in der Himmelsfeste und gepriesen und verherrlicht in Ewigkeit!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 3, 34, 'Lobet den Herren, all ihr Werke des Herrn, preiset und rühmet ihn hoch in Ewigkeit!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 3, 35, 'Lobet den Herrn, ihr Engel des Herrn, preiset und rühmet ihn hoch in Ewigkeit!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 3, 36, 'Lobet den Herrn, ihr Himmel, preiset und rühmet ihn hoch in Ewigkeit!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 3, 37, 'Lobet den Herrn, alle ihr Wasser über dem Himmel, preiset und rühmet ihn hoch in Ewigkeit!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 3, 38, 'Lobet den Herrn, all ihr Mächte des Herrn, preiset und rühmet ihn hoch in Ewigkeit!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 3, 39, 'Lobet den Herrn, Sonne und Mond, preiset und rühmet ihn hoch in Ewigkeit!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 3, 40, 'Lobet den Herrn, ihr Sterne des Himmels, preiset und rühmet ihn hoch in Ewigkeit!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 3, 41, 'Lobet den Herrn, aller Regen und Tau, preiset und rühmet ihn hoch in Ewigkeit!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 3, 42, 'Lobet den Herrn, all ihr Winde, preiset und rühmet ihn hoch in Ewigkeit!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 3, 43, 'Lobet den Herrn, du Feuer und Hitze, preiset und rühmet ihn hoch in Ewigkeit!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 3, 44, 'Lobet den Herrn, Frost und Kälte, preiset und rühmet ihn hoch in Ewigkeit!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 3, 45, 'Lobet den Herrn, Tautropfen und Schneeflocken, preiset und rühmet ihn hoch in Ewigkeit!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 3, 46, 'Lobet den Herrn, Nächte und Tage, preiset und rühmet ihn hoch in Ewigkeit!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 3, 47, 'Lobet den Herrn, Licht und Finsternis, preiset und rühmet ihn hoch in Ewigkeit!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 3, 48, 'Lobet den Herrn, Eis und Kälte, preiset und rühmet ihn hoch in Ewigkeit!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 3, 49, 'Lobet den Herrn, Reif und Schneegestöber, preiset und rühmet ihn hoch in Ewigkeit!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 3, 50, 'Lobet den Herrn, ihr Blitze und Wolken, preiset und rühmet ihn hoch in Ewigkeit!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 3, 51, 'Es lobe den Herrn die Erde, preise und rühme ihn hoch in Ewigkeit!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 3, 52, 'Lobet den Herrn, ihr Berge und Hügel, preiset und rühmet ihn hoch in Ewigkeit!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 3, 53, 'Lobet den Herrn, all ihr Gewächse auf der Erde, preiset und rühmet ihn hoch in Ewigkeit!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 3, 54, 'Lobet den Herrn, ihr Quellen, preiset und rühmet ihn hoch in Ewigkeit!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 3, 55, 'Lobet den Herrn, ihr Meere und Flüsse, preiset und rühmet ihn hoch in Ewigkeit!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 3, 56, 'Lobet den Herrn, ihr Walfische und alles, was sich reget in den Wassern, preiset und rühmet ihn hoch in Ewigkeit!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 3, 57, 'Lobet den Herrn, all ihr Vögel des Himmels, preiset und rühmet ihn hoch in Ewigkeit!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 3, 58, 'Lobet den Herrn, all ihr wilden und zahmen Tiere, preiset und rühmet ihn hoch in Ewigkeit!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 3, 59, 'Lobet den Herrn, ihr Menschenkinder, preiset und rühmet ihn hoch in Ewigkeit!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 3, 60, 'Lobet den Herrn, ihr Israeliten, preiset und rühmet ihn hoch in Ewigkeit!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 3, 61, 'Lobet den Herrn, ihr Priester, preiset und rühmet ihn hoch in Ewigkeit!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 3, 62, 'Lobet den Herrn, ihr Knechte, preiset und rühmet ihn hoch in Ewigkeit!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 3, 63, 'Lobet den Herrn, ihr Geister und Seelen der Gerechten, preiset und rühmet ihn hoch in Ewigkeit!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 3, 64, 'Lobet den Herrn, ihr Frommen und die ihr zerschlagenen Herzens seid, preiset und rühmet ihn hoch in Ewigkeit!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 3, 65, 'Lobet den Herrn, Anania, Asarja und Misael, preiset und rühmet ihn hoch in Ewigkeit! Denn er hat uns der Unterwelt entrissen und uns aus des Todes Macht errettet; er hat uns herausgerissen mitten aus der lodernden Flamme und uns erlöst aus dem Feuer!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 3, 66, 'Danket dem Herrn, denn er ist freundlich, ja ewig währt sein Erbarmen! Lobet alle, die ihr den Herrn fürchtet, den Gott der Götter! Lobsinget und saget ihm Dank, denn sein Erbarmen währt in Ewigkeit.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 1, 1, 'Allmächtiger Herr, Gott unsrer Väter Abraham, Isaak und Jakob und ihrer gerechten Nachkommenschaft!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 1, 2, 'der du Himmel und Erde geschaffen mit allem, was sie schmückt;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 1, 3, 'der du durch das bestimmte Gebot deines Wortes das Meer gefesselt, der du die Tiefe verschlossen und versiegelt hast mit deinem furchtbaren und herrlichen Namen;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 1, 4, 'du, vor dem alles bebt und vor deiner Allmacht zittert –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 1, 5, 'denn unerträglich ist die Großartigkeit deines Glanzes und unwiderstehlich der Zorn, den du den Sündern angedroht hast –,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 1, 6, 'unermeßlich und unergründlich ist auch die Barmherzigkeit, die du verheißen hast.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 1, 7, 'Denn du bist der höchste Herr, voller Mitleid, langmütig und gnadenreich, dem die Leiden der Menschen wehe tun. Du, Herr, hast nach der Fülle deiner Güte denen, die sich gegen dich vergangen haben, Buße und Vergebung verheißen und nach deiner großen Gnade den Sündern Buße verordnet zu ihrem Heil.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 1, 8, 'Du nun, Herr, du Gott der Gerechten, hast Buße nicht den Gerechten auferlegt, nicht dem Abraham, Isaak und Jakob, die ja nicht wider dich gesündigt hatten; wohl aber hast du Buße auferlegt mir, der ich ein Sünder bin;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 1, 9, 'denn ich habe gesündigt über die Zahl des Meeressandes hinaus. Zahlreich sind meine Missetaten, o Herr, ja zahlreich, und ich bin nicht würdig, die Augen zu erheben und zum Himmel droben emporzuschauen wegen der Menge meiner Übertretungen;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 1, 10, 'ich werde niedergebeugt durch viele eiserne Fesseln, so daß ich mein Haupt nicht erheben kann, und ich habe keine Ruhe, weil ich deinen Grimm gereizt und Böses vor dir getan. Ich habe deinen Willen nicht befolgt und deine Gebote nicht gehalten, indem ich Greuelbilder aufstellte und die Zahl der Schandgötzen vermehrte.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 1, 11, 'Jetzt aber beuge ich das Knie meines Herzens, indem ich deine Gnade erflehe.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 1, 12, 'Ich habe gesündigt, Herr, ich habe gesündigt und kenne meine Missetaten;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 1, 13, 'aber ich bitte dich flehentlich: Vergib mir, Herr, vergib mir, und laß mich nicht durch meine Missetaten zugrunde gehen! Zürne mir nicht ewig und behalte mir meine Übeltaten nicht vor! Verdamme mich auch nicht in den tiefsten Tiefen der Erde! denn du, Gott, bist der Gott der Bußfertigen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 1, 14, 'So wirst du denn auch an mir alle deine Huld erweisen, denn mich Unwürdigen wirst du erretten nach deiner großen Barmherzigkeit.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 1, 15, 'Dann will ich dich immerfort preisen mein ganzes Leben lang; denn dir lobsingt das ganze himmlische Heer, und dein ist die Herrlichkeit in alle Ewigkeit! Amen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 1, 16, '');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 1, 'Stammbaum Jesu Christi, des Sohnes Davids, des Sohnes Abrahams:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 2, 'Abraham war der Vater Isaaks; Isaak der Vater Jakobs; Jakob der Vater Judas und seiner Brüder;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 3, 'Juda war der Vater des Phares und des Zara, deren Mutter Thamar war; Phares war der Vater Esroms; Esrom der Vater Arams;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 4, 'Aram der Vater Aminadabs; Aminadab der Vater Naassons; Naasson der Vater Salmons;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 5, 'Salmon der Vater des Boas, dessen Mutter Rahab war; Boas der Vater Obeds, dessen Mutter Ruth war; Obed war der Vater Isais;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 6, 'Isai war der Vater des Königs David. David war der Vater Salomos, dessen Mutter (Bathseba) die Frau Urias gewesen war;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 7, 'Salomo war der Vater Rehabeams; Rehabeam der Vater Abias; Abia der Vater Asas;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 8, 'Asa der Vater Josaphats; Josaphat der Vater Jorams; Joram der Vater Ussias;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 9, 'Ussia der Vater Jothams; Jotham der Vater des Ahas; Ahas der Vater Hiskias;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 10, 'Hiskia der Vater Manasses; Manasse der Vater des Amon; Amon der Vater Josias;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 11, 'Josia der Vater Jechonjas und seiner Brüder zur Zeit der Wegführung nach Babylon.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 12, 'Nach der babylonischen Gefangenschaft war Jechonja der Vater Salathiels; Salathiel der Vater Serubabels;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 13, 'Serubabel der Vater Abihuds; Abihud der Vater Eljakims; Eljakim der Vater Azors;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 14, 'Azor der Vater Sadoks; Sadok der Vater Achims; Achim der Vater Elihuds;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 15, 'Elihud der Vater Eleasars; Eleasar der Vater Matthans; Matthan der Vater Jakobs;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 16, 'Jakob der Vater Josephs, des Ehemannes der Maria, von welcher Jesus geboren ward, der da Christus genannt wird.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 17, 'Man sieht: von Abraham bis David sind es im ganzen vierzehn Geschlechter, von David bis zur babylonischen Gefangenschaft ebenfalls vierzehn Geschlechter, endlich von der babylonischen Gefangenschaft bis auf Christus nochmals vierzehn Geschlechter.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 18, 'Mit der Geburt Jesu Christi aber verhielt es sich so: Als seine Mutter Maria mit Joseph verlobt war, stellte es sich heraus, noch ehe sie zusammengekommen waren, daß sie vom heiligen Geist guter Hoffnung war.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 19, 'Da faßte Joseph, ihr Verlobter, der ein rechtschaffener Mann war und sie nicht in üblen Ruf bringen wollte, den Entschluß, sich ohne Aufsehen zu erregen von ihr loszusagen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 20, 'Doch als er sich mit solchen Gedanken trug, siehe, da erschien ihm ein Engel des Herrn im Traum und sagte zu ihm: »Joseph, Sohn Davids, trage keinerlei Bedenken, Maria, deine Verlobte, als Ehefrau zu dir zu nehmen! Denn das von ihr zu erwartende Kind stammt vom heiligen Geist.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 21, 'Sie wird Mutter eines Sohnes werden, dem du den Namen Jesus geben sollst; denn er ist es, der sein Volk von ihren Sünden erretten wird.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 22, 'Dies alles ist aber geschehen, damit das Wort erfüllt würde, das der Herr durch den Propheten gesprochen hat, der da sagt:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 23, '»Siehe, die Jungfrau wird guter Hoffnung und Mutter eines Sohnes werden, dem man den Namen Immanuel geben wird«, das heißt übersetzt: ›Mit uns ist Gott.‹ –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 24, 'Als Joseph dann aus dem Schlaf erwacht war, tat er, wie der Engel des Herrn ihm geboten hatte: er nahm seine Verlobte (als Gattin) zu sich,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 25, 'verkehrte aber nicht ehelich mit ihr, bis sie einen Sohn geboren hatte; dem gab er den Namen Jesus.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 2, 1, 'Als nun Jesus zu Bethlehem in Judäa in den Tagen des Königs Herodes geboren war, da kamen Weise aus dem Osten nach Jerusalem');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 2, 2, 'und fragten: »Wo ist der neugeborene König der Juden? Wir haben nämlich seinen Stern im Aufgehen gesehen und sind hergekommen, um ihm unsere Huldigung darzubringen.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 2, 3, 'Als der König Herodes das vernahm, erschrak er sehr und ganz Jerusalem mit ihm;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 2, 4, 'und er ließ alle Hohenpriester und Schriftgelehrten des Volks zusammenkommen und erkundigte sich bei ihnen, wo Christus geboren werden sollte.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 2, 5, 'Sie antworteten ihm: »Zu Bethlehem in Judäa; denn so steht bei dem Propheten geschrieben:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 2, 6, '›Du, Bethlehem im Lande Judas, du bist durchaus nicht die unbedeutendste unter den Fürstenstädten Judas; denn aus dir wird ein Führer hervorgehen, der mein Volk Israel weiden wird.‹«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 2, 7, 'Daraufhin berief Herodes die Weisen heimlich zu sich und ließ sich von ihnen genau die Zeit angeben, wann der Stern erschienen wäre;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 2, 8, 'dann wies er sie nach Bethlehem und sagte: »Zieht hin und stellt genaue Nachforschungen nach dem Kindlein an; und wenn ihr es gefunden habt, so teilt es mir mit, damit auch ich hingehe und ihm meine Huldigung darbringe.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 2, 9, 'Als sie das vom Könige gehört hatten, machten sie sich auf den Weg; und siehe da, der Stern, den sie im Osten gesehen hatten, ging vor ihnen her, bis er endlich über dem Ort stehen blieb, wo das Kindlein sich befand.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 2, 10, 'Als sie den Stern erblickten, wurden sie hoch erfreut.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 2, 11, 'Sie traten in das Haus ein und sahen das Kindlein bei seiner Mutter Maria, warfen sich vor ihm nieder und huldigten ihm; alsdann taten sie ihre Schatzbeutel auf und brachten ihm Geschenke dar: Gold, Weihrauch und Myrrhe.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 2, 12, 'Weil sie hierauf im Traume die göttliche Weisung erhielten, nicht wieder zu Herodes zurückzukehren, zogen sie auf einem anderen Wege in ihr Heimatland zurück.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 2, 13, 'Als sie nun weggezogen waren, da erschien ein Engel des Herrn dem Joseph im Traume und gebot ihm: »Steh auf, nimm das Kindlein und seine Mutter mit dir und fliehe nach Ägypten und bleibe so lange dort, bis ich’s dir sage! Denn Herodes geht damit um, nach dem Kindlein suchen zu lassen, um es umzubringen.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 2, 14, 'Da stand Joseph auf, nahm in der Nacht das Kindlein und seine Mutter mit sich und entwich nach Ägypten;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 2, 15, 'dort blieb er bis zum Tode des Herodes. So sollte sich das Wort erfüllen, das der Herr durch den Propheten gesprochen hat, der da sagt: »Aus Ägypten habe ich meinen Sohn gerufen.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 2, 16, 'Als Herodes sich nun von den Weisen hintergangen sah, geriet er in heftigen Zorn; er sandte (Diener) hin und ließ in Bethlehem und dem ganzen Umkreis des Ortes sämtliche Knaben im Alter von zwei und weniger Jahren töten, entsprechend der Zeit, die er sich von den Weisen genau hatte angeben lassen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 2, 17, 'Damals erfüllte sich, was durch den Propheten Jeremia gesagt ist, der spricht:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 2, 18, '»Ein Geschrei hat man in Rama vernommen, lautes Weinen und viel Wehklagen: Rahel weint um ihre Kinder und will sich nicht trösten lassen, daß sie nicht mehr da sind.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 2, 19, 'Als Herodes aber gestorben war, da erschien ein Engel des Herrn dem Joseph in Ägypten im Traum');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 2, 20, 'und gebot ihm: »Steh auf, nimm das Kindlein und seine Mutter mit dir und ziehe heim ins Land Israel; denn die sind gestorben, die dem Kindlein nach dem Leben getrachtet haben.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 2, 21, 'Da stand Joseph auf, nahm das Kindlein und seine Mutter mit sich und kehrte in das Land Israel zurück.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 2, 22, 'Als er aber vernahm, daß Archelaus an Stelle seines Vaters Herodes König über Judäa sei, trug er Bedenken, dorthin zu gehen. Vielmehr begab er sich infolge einer göttlichen Weisung, die er im Traum erhalten hatte, in die Landschaft Galiläa');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 2, 23, 'und ließ sich dort in einer Stadt namens Nazareth nieder. So ging das Prophetenwort in Erfüllung, daß er den Namen ›Nazarener‹ führen werde.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 3, 1, 'In jenen Tagen trat aber Johannes der Täufer öffentlich auf und predigte in der Wüste von Judäa:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 3, 2, '»Tut Buße, denn das Himmelreich ist nahe herbeigekommen!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 3, 3, 'Dieser (Johannes) ist nämlich der Mann, auf den sich das Wort des Propheten Jesaja bezieht, der da sagt: »Eine Stimme ruft laut in der Wüste: ›Bereitet den Weg des Herrn! Macht gerade seine Pfade!‹«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 3, 4, 'Johannes selbst aber trug ein Gewand von Kamelhaaren und einen Ledergurt um seine Hüften; seine Nahrung bestand in Heuschrecken und wildem Honig.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 3, 5, 'Da zog denn Jerusalem und ganz Judäa und die ganze Gegend am Jordan zu ihm hinaus');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 3, 6, 'und ließen sich im Jordanfluß von ihm taufen, indem sie ihre Sünden offen bekannten.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 3, 7, 'Als er aber einmal viele Pharisäer und Sadduzäer zu seiner Taufe kommen sah, sagte er zu ihnen: »Ihr Schlangenbrut! Wer hat euch auf den Gedanken gebracht, dem drohenden Zorngericht zu entfliehen?');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 3, 8, 'So schafft denn Früchte, die der Buße würdig sind,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 3, 9, 'und laßt euch nicht in den Sinn kommen, bei euch zu sagen: ›Wir haben ja Abraham zum Vater.‹ Denn ich sage euch: Gott vermag dem Abraham aus den Steinen hier Kinder zu erwecken.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 3, 10, 'Schon ist aber den Bäumen die Axt an die Wurzel gelegt, und jeder Baum, der nicht gute Früchte bringt, wird abgehauen und ins Feuer geworfen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 3, 11, 'Ich taufe euch nur mit Wasser zur Buße; der aber nach mir kommt, ist stärker als ich, und ich bin nicht gut genug, ihm seine Schuhe abzunehmen: der wird euch mit heiligem Geist und mit Feuer taufen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 3, 12, 'Er hat die Worfschaufel in seiner Hand und wird seine Tenne gründlich reinigen; seinen Weizen wird er in die Scheuer sammeln, die Spreu aber mit unlöschbarem Feuer verbrennen.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 3, 13, 'Damals kam Jesus von Galiläa her an den Jordan zu Johannes, um sich (auch) von ihm taufen zu lassen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 3, 14, 'Der wollte ihm aber nicht zu Willen sein und sagte: »Ich müßte von dir getauft werden, und du kommst zu mir?«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 3, 15, 'Doch Jesus gab ihm zur Antwort: »Laß es für diesmal geschehen, denn so gebührt es uns, alle Gerechtigkeit zu erfüllen.« Da gab Johannes ihm nach.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 3, 16, 'Als Jesus aber getauft und soeben aus dem Wasser gestiegen war, siehe, da taten sich ihm die Himmel auf, und er (Johannes oder Jesus) sah den Geist Gottes wie eine Taube herabschweben und auf ihn kommen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 3, 17, 'Und siehe, eine Stimme erscholl aus den Himmeln: »Dieser ist mein geliebter Sohn, an dem ich Wohlgefallen gefunden habe!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 4, 1, 'Hierauf wurde Jesus vom Geist in die Wüste hinaufgeführt, um vom Teufel versucht zu werden;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 4, 2, 'und als er vierzig Tage und vierzig Nächte gefastet hatte, hungerte ihn zuletzt.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 4, 3, 'Da trat der Versucher an ihn heran und sagte zu ihm: »Bist du Gottes Sohn, so gebiete, daß diese Steine zu Broten werden.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 4, 4, 'Er aber gab ihm zur Antwort: »Es steht geschrieben: ›Nicht vom Brot allein soll der Mensch leben, sondern von jedem Wort, das durch den Mund Gottes ergeht.‹«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 4, 5, 'Hierauf nahm ihn der Teufel mit sich in die heilige Stadt, stellte ihn dort auf die Zinne des Tempels');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 4, 6, 'und sagte zu ihm: »Bist du Gottes Sohn, so stürze dich hier hinab! Denn es steht geschrieben: ›Er wird seine Engel für dich entbieten, und sie werden dich auf den Armen tragen, damit du mit deinem Fuß an keinen Stein stoßest.‹«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 4, 7, 'Jesus antwortete ihm: »Es steht aber auch geschrieben: ›Du sollst den Herrn, deinen Gott, nicht versuchen!‹«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 4, 8, 'Nochmals nahm ihn der Teufel mit sich auf einen sehr hohen Berg, zeigte ihm alle Königreiche der Welt samt ihrer Herrlichkeit');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 4, 9, 'und sagte zu ihm: »Dies alles will ich dir geben, wenn du dich niederwirfst und mich anbetest.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 4, 10, 'Da antwortete ihm Jesus: »Weg mit dir, Satan! Denn es steht geschrieben: ›Den Herrn, deinen Gott, sollst du anbeten und ihm allein dienen!‹«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 4, 11, 'Nun ließ der Teufel von ihm ab, und siehe, Engel traten zu ihm und leisteten ihm Dienste.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 4, 12, 'Als Jesus aber von der Gefangennahme des Johannes Kunde erhielt, zog er sich nach Galiläa zurück;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 4, 13, 'er verließ jedoch Nazareth und verlegte seinen Wohnsitz nach Kapernaum, das am See (Genezaret) liegt im Gebiet von Sebulon und Naphthali,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 4, 14, 'damit das Wort des Propheten Jesaja erfüllt werde, das da lautet:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 4, 15, '»Das Land Sebulon und das Land Naphthali, das nach dem See zu liegt, das Land jenseits des Jordans, das Galiläa der Heiden,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 4, 16, 'das Volk, das im Finstern saß, hat ein großes Licht gesehen, und denen, die im Lande und Schatten des Todes saßen, ist ein Licht aufgegangen.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 4, 17, 'Von dieser Zeit an begann Jesus die Heilsbotschaft mit den Worten zu verkündigen: »Tut Buße, denn das Himmelreich ist nahe herbeigekommen!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 4, 18, 'Als er nun (eines Tages) am Ufer des Galiläischen Sees hinging, sah er zwei Brüder, Simon, der auch den Namen Petrus führt, und seinen Bruder Andreas, die ein Netz in den See auswarfen; sie waren nämlich Fischer.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 4, 19, 'Er sagte zu ihnen: »Kommt, folgt mir nach, so will ich euch zu Menschenfischern machen!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 4, 20, 'Da ließen sie sogleich ihre Netze liegen und folgten ihm nach.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 4, 21, 'Als er dann von dort weiterging, sah er ein anderes Brüderpaar, nämlich Jakobus, den Sohn des Zebedäus, und seinen Bruder Johannes, die im Boot mit ihrem Vater Zebedäus ihre Netze instand setzten; und er berief auch sie.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 4, 22, 'Da verließen sie sogleich das Boot und ihren Vater und folgten ihm nach.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 4, 23, 'Jesus zog dann in ganz Galiläa umher, indem er in ihren Synagogen lehrte, die Heilsbotschaft vom Reiche (Gottes) verkündigte und alle Krankheiten und alle Gebrechen im Volke heilte;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 4, 24, 'und der Ruf von ihm verbreitete sich durch ganz Syrien, und man brachte alle, die an den verschiedenartigsten Krankheiten litten und mit schmerzhaften Übeln behaftet waren, Besessene, Fallsüchtige und Gelähmte, und er heilte sie.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 4, 25, 'So begleiteten ihn denn große Volksscharen aus Galiläa und aus dem Gebiet der Zehn-Städte sowie aus Jerusalem und Judäa und aus dem Ostjordanland.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 5, 1, 'Als Jesus nun die Volksscharen sah, ging er ins Gebirge hinauf, und nachdem er sich dort gesetzt hatte, traten seine Jünger zu ihm.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 5, 2, 'Da tat er seinen Mund auf und lehrte sie mit den Worten:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 5, 3, '»Selig sind die geistlich Armen, denn ihnen wird das Himmelreich zuteil!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 5, 4, 'Selig sind die Bekümmerten, denn sie werden getröstet werden! –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 5, 5, 'Selig sind die Sanftmütigen, denn sie werden das Land ererben!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 5, 6, 'Selig sind, die nach der Gerechtigkeit hungern und dürsten, denn sie werden gesättigt werden! –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 5, 7, 'Selig sind die Barmherzigen, denn sie werden Barmherzigkeit erlangen!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 5, 8, 'Selig sind, die reinen Herzens sind, denn sie werden Gott schauen!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 5, 9, 'Selig sind die Friedfertigen, denn sie werden Söhne Gottes heißen! –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 5, 10, 'Selig sind, die um der Gerechtigkeit willen Verfolgung erleiden, denn ihnen wird das Himmelreich zuteil!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 5, 11, 'Selig seid ihr, wenn man euch um meinetwillen schmäht und verfolgt und euch lügnerisch alles Böse nachredet!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 5, 12, 'Freuet euch darüber und jubelt, denn euer Lohn ist groß im Himmel! Ebenso hat man ja auch die Propheten vor euch verfolgt.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 5, 13, '»Ihr seid das Salz der Erde! Wenn aber das Salz fade geworden ist, womit soll es wieder gesalzen werden? Es taugt zu nichts mehr, als aus dem Hause geworfen und von den Leuten zertreten zu werden. –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 5, 14, 'Ihr seid das Licht der Welt! Eine Stadt, die oben auf einem Berge liegt, kann nicht verborgen bleiben.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 5, 15, 'Man zündet auch nicht ein Licht an und stellt es unter den Scheffel, sondern auf den Leuchter: dann leuchtet es allen, die im Hause sind.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 5, 16, 'Ebenso soll auch euer Licht vor den Menschen leuchten, damit sie eure guten Werke sehen und euren Vater, der im Himmel ist, preisen.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 5, 17, '»Denkt nicht, daß ich gekommen sei, das Gesetz oder die Propheten aufzulösen! Ich bin nicht gekommen aufzulösen, sondern zu erfüllen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 5, 18, 'Denn wahrlich ich sage euch: Bis Himmel und Erde vergehen, wird vom Gesetz nicht ein einziges Jota und kein Strichlein vergehen, bis alles in Erfüllung gegangen ist.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 5, 19, 'Wer also ein einziges von diesen Geboten – und wäre es das geringste – auflöst und die Menschen demgemäß lehrt, der wird der Geringste im Himmelreich heißen; wer sie aber tut und (die Menschen) so lehrt, der wird groß im Himmelreich heißen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 5, 20, 'Denn ich sage euch: Wenn es mit eurer Gerechtigkeit nicht weit besser bestellt ist als bei den Schriftgelehrten und Pharisäern, so werdet ihr nimmermehr ins Himmelreich eingehen!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 5, 21, '»Ihr habt gehört, daß den Alten geboten worden ist: ›Du sollst nicht töten‹, wer aber tötet, soll dem Gericht verfallen sein.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 5, 22, 'Ich dagegen sage euch: Wer seinem Bruder auch nur zürnt, der soll dem Gericht verfallen sein; und wer zu seinem Bruder ›Dummkopf‹ sagt, soll dem Hohen Rat verfallen sein; und wer ›du Narr‹ zu ihm sagt, soll der Feuerhölle verfallen sein.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 5, 23, 'Wenn du also deine Opfergabe zum Altar bringst und dich dort erinnerst, daß dein Bruder etwas gegen dich hat,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 5, 24, 'so laß deine Gabe dort vor dem Altar und gehe zunächst hin und versöhne dich mit deinem Bruder; alsdann geh hin und opfere deine Gabe!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 5, 25, 'Sei zum Vergleich mit deinem Widersacher ohne Säumen bereit, solange du mit ihm noch auf dem Wege (zum Richter) bist, damit dein Widersacher dich nicht dem Richter übergibt und der Richter dich dem Gerichtsdiener (überantwortet) und du ins Gefängnis gesetzt wirst.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 5, 26, 'Wahrlich ich sage dir: Du wirst von dort sicherlich nicht herauskommen, bis du den letzten Pfennig bezahlt hast.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 5, 27, 'Ihr habt gehört, daß (den Alten) geboten worden ist: ›Du sollst nicht ehebrechen!‹');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 5, 28, 'Ich dagegen sage euch: Wer eine Ehefrau auch nur mit Begehrlichkeit anblickt, hat damit schon in seinem Herzen Ehebruch an ihr begangen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 5, 29, 'Wenn dich also dein rechtes Auge ärgert, so reiß es aus und wirf es weg von dir; denn es ist besser für dich, daß eines deiner Glieder (dir) verloren geht, als daß dein ganzer Leib in die Hölle geworfen wird.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 5, 30, 'Und wenn deine rechte Hand dich ärgert, so haue sie ab und wirf sie weg von dir; denn es ist besser für dich, daß eines deiner Glieder (dir) verloren geht, als daß dein ganzer Leib in die Hölle geworfen wird. –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 5, 31, 'Ferner ist (zu den Alten) gesagt worden: ›Wer seine Ehefrau entläßt, der soll ihr einen Scheidebrief geben!‹');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 5, 32, 'Ich dagegen sage euch: Wer sich von seiner Frau scheidet – außer auf Grund von Unzucht –, der verschuldet es, daß dann Ehebruch mit ihr verübt wird; und wer eine entlassene Frau heiratet, der begeht Ehebruch.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 5, 33, 'Ihr habt weiter gehört, daß den Alten geboten worden ist: ›Du sollst nicht falsch schwören‹, ›sollst aber dem Herrn deine Eide erfüllen!‹');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 5, 34, 'Ich dagegen sage euch: Ihr sollt überhaupt nicht schwören, weder beim Himmel, denn er ist Gottes Thron,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 5, 35, 'noch bei der Erde, denn sie ist der Schemel seiner Füße, noch bei Jerusalem, denn es ist die Stadt des großen Königs.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 5, 36, 'Auch bei deinem Haupte sollst du nicht schwören, denn du vermagst kein einziges Haar weiß oder schwarz zu machen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 5, 37, 'Eure Rede sei vielmehr ›ja ja – nein nein‹; jeder weitere Zusatz ist vom Übel.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 5, 38, 'Ihr habt gehört, daß (den Alten) geboten worden ist: ›Auge um Auge und Zahn um Zahn!‹');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 5, 39, 'Ich dagegen sage euch: Ihr sollt dem Bösen keinen Widerstand leisten; sondern wer dich auf die rechte Wange schlägt, dem halte auch die andere hin,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 5, 40, 'und wer mit dir einen Rechtsstreit anfangen und dir den Rock nehmen will, dem überlaß auch noch den Mantel,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 5, 41, 'und wer dich zu einer Meile Weges nötigt, mit dem gehe zwei.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 5, 42, 'Wer dich (um etwas) bittet, dem gib, und wer (Geld) von dir borgen will, den weise nicht ab!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 5, 43, 'Ihr habt gehört, daß (den Alten) geboten worden ist; ›Du sollst deinen Nächsten lieben, und deinen Feind hassen!‹');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 5, 44, 'Ich dagegen sage euch: Liebet eure Feinde und betet für eure Verfolger,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 5, 45, 'damit ihr euch als Söhne eures himmlischen Vaters erweist. Denn er läßt seine Sonne über Böse und Gute aufgehen und läßt regnen auf Gerechte und Ungerechte.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 5, 46, 'Denn wenn ihr (nur) die liebt, die euch lieben, welches Verdienst habt ihr da? Tun das nicht auch die Zöllner?');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 5, 47, 'Und wenn ihr nur eure Freunde grüßt, was tut ihr da Besonderes? Tun das nicht auch die Heiden?');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 5, 48, 'Darum sollt ihr vollkommen sein, wie euer himmlischer Vater vollkommen ist.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 6, 1, '»Gebt acht darauf, daß ihr eure Gerechtigkeit nicht vor den Leuten ausübt, um von ihnen gesehen zu werden: sonst habt ihr keinen Lohn (zu erwarten) bei eurem Vater im Himmel!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 6, 2, 'Wenn du also Almosen spenden willst, so laß nicht vor dir her posaunen, wie es die Heuchler in den Synagogen und auf den Straßen tun, um von den Leuten gerühmt zu werden. Wahrlich ich sage euch: Sie haben ihren Lohn dahin.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 6, 3, 'Nein, wenn du Almosen gibst, so laß deine linke Hand nicht wissen, was deine rechte tut,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 6, 4, 'damit deine Wohltätigkeit im Verborgenen geschehe; dein Vater aber, der auch ins Verborgene hineinsieht, wird es dir alsdann vergelten.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 6, 5, '»Auch wenn ihr betet, sollt ihr es nicht wie die Heuchler machen; denn sie stellen sich gern in den Synagogen und an den Straßenecken auf und beten dort, um den Leuten in die Augen zu fallen; wahrlich ich sage euch: Sie haben ihren Lohn dahin.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 6, 6, 'Du aber, wenn du beten willst, so geh in deine Kammer, schließe deine Tür zu und bete zu deinem Vater, der im Verborgenen ist; dein Vater aber, der auch ins Verborgene hineinsieht, wird es dir alsdann vergelten.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 6, 7, 'Und wenn ihr betet, sollt ihr nicht plappern wie die Heiden; denn sie meinen, Erhörung zu finden, wenn sie viele Worte machen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 6, 8, 'Darum macht es nicht wie sie; euer Vater weiß ja, was ihr bedürft, ehe ihr ihn bittet.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 6, 9, 'Darum sollt ihr so beten: ›Unser Vater, der du bist im Himmel: Geheiligt werde dein Name!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 6, 10, 'Dein Reich komme! Dein Wille geschehe wie im Himmel, so auch auf der Erde!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 6, 11, 'Unser auskömmliches Brot gib uns heute!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 6, 12, 'Und vergib uns unsere Schulden, wie auch wir sie unsern Schuldnern vergeben haben!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 6, 13, 'Und führe uns nicht in Versuchung, sondern erlöse uns von dem Bösen!‹');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 6, 14, 'Denn wenn ihr den Menschen ihre Verfehlungen vergebt, so wird euer himmlischer Vater sie auch euch vergeben;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 6, 15, 'wenn ihr sie aber den Menschen nicht vergebt, so wird euer Vater euch eure Verfehlungen auch nicht vergeben.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 6, 16, '»Weiter: Wenn ihr fastet, sollt ihr kein finsteres Gesicht machen wie die Heuchler; denn sie geben sich ein trübseliges Aussehen, um sich den Leuten mit ihrem Fasten zur Schau zu stellen. Wahrlich ich sage euch: Sie haben ihren Lohn dahin.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 6, 17, 'Du aber, wenn du fastest, salbe dir das Haupt und wasche dir das Gesicht,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 6, 18, 'um dich nicht mit deinem Fasten den Leuten zu zeigen, sondern deinem Vater, der im Verborgenen ist; dein Vater aber, der auch ins Verborgene hineinsieht, wird es dir alsdann vergelten.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 6, 19, '»Sammelt euch nicht Schätze hier auf der Erde, wo Motten und Rost sie vernichten und wo Diebe einbrechen und stehlen!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 6, 20, 'Sammelt euch vielmehr Schätze im Himmel, wo weder Motten noch Rost sie vernichten und wo keine Diebe einbrechen und stehlen!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 6, 21, 'Denn wo dein Schatz ist, da wird auch dein Herz sein. –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 6, 22, 'Die Leuchte des Leibes ist das Auge. Wenn nun dein Auge richtig ist, so wird dein ganzer Leib voll Licht sein;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 6, 23, 'wenn aber dein Auge nichts taugt, so wird dein ganzer Leib finster sein. Wenn also das in dir befindliche Licht Dunkelheit ist, wie groß muß dann die Dunkelheit sein! –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 6, 24, 'Niemand kann (gleichzeitig) zwei (sich widerstreitenden) Herren dienen; denn entweder wird er den einen hassen und den andern lieben, oder er wird dem einen ergeben sein und den andern mißachten: ihr könnt nicht (gleichzeitig) Gott und dem Mammon dienen.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 6, 25, '»Deswegen sage ich euch: Macht euch keine Sorgen um euer Leben, was ihr essen und was ihr trinken sollt, auch nicht um euren Leib, was ihr anziehen sollt. Ist nicht das Leben wertvoller als die Nahrung und der Leib wertvoller als die Kleidung?');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 6, 26, 'Sehet die Vögel des Himmels an: sie säen nicht und ernten nicht und sammeln nichts in Scheuern, und euer himmlischer Vater ernährt sie doch. Seid ihr denn nicht viel mehr wert als sie?');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 6, 27, 'Wer von euch vermöchte aber mit all seinem Sorgen der Länge seiner Lebenszeit auch nur eine einzige Spanne zuzusetzen?');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 6, 28, 'Und was macht ihr euch Sorge um die Kleidung? Betrachtet die Lilien auf dem Felde, wie sie wachsen! Sie arbeiten nicht und spinnen nicht;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 6, 29, 'und doch sage ich euch: Auch Salomo in aller seiner Pracht ist nicht so herrlich gekleidet gewesen wie eine von ihnen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 6, 30, 'Wenn nun Gott schon das Gras des Feldes, das heute steht und morgen in den Ofen geworfen wird, so kleidet: wird er das nicht viel mehr euch tun, ihr Kleingläubigen?');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 6, 31, 'Darum sollt ihr nicht sorgen und sagen: ›Was sollen wir essen, was trinken, womit sollen wir uns kleiden?‹');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 6, 32, 'Denn auf alles derartige sind die Heiden bedacht. Euer himmlischer Vater weiß ja, daß ihr dies alles bedürft.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 6, 33, 'Nein, trachtet zuerst nach dem Reiche Gottes und nach seiner Gerechtigkeit, dann wird euch all das andere obendrein gegeben werden.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 6, 34, 'Macht euch also keine Sorgen um den morgenden Tag! Denn der morgende Tag wird seine eigenen Sorgen haben; jeder Tag hat an seiner eigenen Mühsal genug.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 7, 1, '»Richtet nicht, damit ihr nicht gerichtet werdet!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 7, 2, 'Denn mit demselben Gericht, mit dem ihr richtet, werdet ihr wieder gerichtet werden, und mit demselben Maße, mit dem ihr meßt, wird euch wieder gemessen werden.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 7, 3, 'Was siehst du aber den Splitter im Auge deines Bruders, während du den Balken in deinem eigenen Auge nicht wahrnimmst?');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 7, 4, 'Oder wie darfst du zu deinem Bruder sagen: ›Laß mich den Splitter aus deinem Auge ziehen‹? Und dabei steckt der Balken in deinem Auge!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 7, 5, 'Du Heuchler, ziehe zuerst den Balken aus deinem Auge, dann magst du zusehen, wie du den Splitter aus deines Bruders Auge ziehst. –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 7, 6, 'Gebt das Heilige nicht den Hunden preis und werft eure Perlen nicht den Schweinen vor, damit diese sie nicht mit ihren Füßen zertreten und sich umwenden und euch zerreißen.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 7, 7, '»Bittet, so wird euch gegeben werden; suchet, so werdet ihr finden; klopfet an, so wird euch aufgetan werden!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 7, 8, 'Denn wer da bittet, der empfängt, und wer da sucht, der findet, und wer anklopft, dem wird aufgetan werden.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 7, 9, 'Oder wo wäre jemand unter euch, der seinem Sohne, wenn er ihn um Brot bittet, einen Stein reichte?');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 7, 10, 'Oder der, wenn er ihn um einen Fisch bittet, ihm eine Schlange gäbe?');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 7, 11, 'Wenn nun ihr, die ihr doch böse seid, euren Kindern gute Gaben zu geben versteht; wieviel mehr wird euer Vater im Himmel denen Gutes geben, die ihn bitten!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 7, 12, '»Alles nun, was ihr von den Menschen erwartet, das erweist auch ihr ihnen ebenso; denn darin besteht (die Erfüllung) des Gesetzes und der Propheten. –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 7, 13, 'Gehet (in das Reich Gottes) durch die enge Pforte ein; denn weit ist die Pforte und breit der Weg, der ins Verderben führt, und es sind ihrer viele, die auf ihm hineingehen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 7, 14, 'Eng ist dagegen die Pforte und schmal der Weg, der ins Leben führt, und nur wenige sind es, die ihn finden.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 7, 15, '»Hütet euch vor den falschen Propheten, die in Schafskleidern zu euch kommen, im Inneren aber räuberische Wölfe sind.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 7, 16, 'An ihren Früchten werdet ihr sie erkennen. Kann man etwa Trauben lesen von Dornbüschen oder Feigen von Disteln?');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 7, 17, 'So bringt jeder gute Baum gute Früchte, ein fauler Baum aber bringt schlechte Früchte;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 7, 18, 'ein guter Baum kann keine schlechten Früchte bringen, und ein fauler Baum kann keine guten Früchte bringen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 7, 19, 'Jeder Baum, der nicht gute Früchte bringt, wird abgehauen und ins Feuer geworfen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 7, 20, 'Also: an ihren Früchten werdet ihr sie erkennen.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 7, 21, '»Nicht alle, die ›Herr, Herr‹ zu mir sagen, werden (darum schon) ins Himmelreich eingehen, sondern nur, wer den Willen meines himmlischen Vaters tut.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 7, 22, 'Viele werden an jenem Tage zu mir sagen: ›Herr, Herr, haben wir nicht kraft deines Namens prophetisch geredet und kraft deines Namens böse Geister ausgetrieben und kraft deines Namens viele Wundertaten vollführt?‹');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 7, 23, 'Aber dann werde ich ihnen erklären: ›Niemals habe ich euch gekannt; hinweg von mir, ihr Täter der Gesetzlosigkeit!‹');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 7, 24, 'Darum wird jeder, der diese meine Worte hört und nach ihnen tut, einem klugen Manne gleichen, der sein Haus auf Felsengrund gebaut hat.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 7, 25, 'Da strömte der Platzregen herab, es kamen die Wasserströme, es wehten die Winde und stießen an jenes Haus; doch es stürzte nicht ein, denn es war auf den Felsen gegründet.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 7, 26, 'Wer jedoch diese meine Worte hört und nicht nach ihnen tut, der gleicht einem törichten Manne, der sein Haus auf den Sand gebaut hat.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 7, 27, 'Da strömte der Platzregen herab, es kamen die Wasserströme, es wehten die Winde und stürmten gegen jenes Haus: da stürzte es ein, und sein Zusammensturz war gewaltig.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 7, 28, 'Als Jesus diese Rede beendet hatte, waren die Volksscharen über seine Lehre ganz betroffen;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 7, 29, 'denn er lehrte sie wie einer, der (göttliche) Vollmacht hat, ganz anders als ihre Schriftgelehrten.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 8, 1, 'Als er dann vom Berge herabgestiegen war, folgten ihm große Volksscharen nach.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 8, 2, 'Da trat ein Aussätziger herzu, warf sich vor ihm nieder und sagte: »Herr, wenn du willst, kannst du mich reinigen.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 8, 3, 'Jesus streckte seine Hand aus, faßte ihn an und sagte: »Ich will’s, werde rein!« Da wurde er sogleich von seinem Aussatz rein.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 8, 4, 'Darauf sagte Jesus zu ihm: »Hüte dich, jemandem etwas davon zu sagen! Gehe vielmehr hin, zeige dich dem Priester und bringe die Opfergabe dar, die Mose geboten hat, zum Zeugnis für sie!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 8, 5, 'Als er hierauf nach Kapernaum hineinkam, trat ein Hauptmann zu ihm und bat ihn');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 8, 6, 'mit den Worten: »Herr, mein Diener liegt gelähmt bei mir zu Hause darnieder und leidet schreckliche Schmerzen.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 8, 7, 'Jesus antwortete ihm: »Ich will kommen und ihn heilen.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 8, 8, 'Der Hauptmann aber entgegnete: »Herr, ich bin nicht wert, daß du unter mein Dach trittst; nein, gebiete nur mit einem Wort, dann wird mein Diener gesund werden.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 8, 9, 'Ich bin ja auch ein Mann, der unter höherem Befehl steht, und habe Mannschaften unter mir, und wenn ich zu dem einen sage: ›Gehe!‹, so geht er, und zu dem andern: ›Komm!‹, so kommt er, und zu meinem Diener: ›Tu das!‹, so tut er’s.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 8, 10, 'Als Jesus das hörte, verwunderte er sich und sagte zu seinen Begleitern: »Wahrlich ich sage euch: In Israel habe ich bei niemand solchen Glauben gefunden.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 8, 11, 'Ich sage euch aber: Viele werden von Osten und Westen kommen und sich mit Abraham, Isaak und Jakob im Himmelreich zum Mahl niederlassen;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 8, 12, 'aber die Söhne des Reiches werden in die Finsternis draußen hinausgestoßen werden; dort wird lautes Weinen und Zähneknirschen sein.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 8, 13, 'Zu dem Hauptmann aber sagte Jesus: »Geh hin! Wie du geglaubt hast, so geschehe dir!« Und sein Diener wurde zur selben Stunde gesund.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 8, 14, 'Als Jesus dann in das Haus des Petrus gekommen war, sah er dessen Schwiegermutter fieberkrank zu Bett liegen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 8, 15, 'Er faßte sie bei der Hand, da wich das Fieber von ihr: sie stand auf und bediente ihn (bei der Mahlzeit).');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 8, 16, 'Als es dann Abend geworden war, brachte man viele Besessene zu ihm, und er trieb die bösen Geister durchs Wort aus und heilte alle, die ein Leiden hatten.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 8, 17, 'So sollte sich das Wort des Propheten Jesaja erfüllen, der da sagt: »Er hat unsere Gebrechen hinweggenommen und unsere Krankheiten getragen.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 8, 18, 'Als Jesus sich dann wieder von großen Volksscharen umgeben sah, befahl er, an das jenseitige Ufer des Sees hinüberzufahren.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 8, 19, 'Da trat ein Schriftgelehrter an ihn heran mit den Worten: »Meister, ich will dir folgen, wohin du auch gehst!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 8, 20, 'Jesus antwortete ihm: »Die Füchse haben Gruben und die Vögel des Himmels Nester; der Menschensohn aber hat keine Stätte, wo er sein Haupt hinlegen kann.« –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 8, 21, 'Ein anderer von seinen Jüngern sagte zu ihm: »Herr, erlaube mir, zuerst noch hinzugehen und meinen Vater zu begraben!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 8, 22, 'Jesus aber antwortete ihm: »Folge du mir nach, und überlaß es den Toten, ihre Toten zu begraben!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 8, 23, 'Jesus stieg dann ins Boot, und seine Jünger folgten ihm.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 8, 24, 'Da erhob sich (plötzlich) ein heftiger Sturm auf dem See, so daß das Boot von den Wellen bedeckt wurde; er selbst aber schlief.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 8, 25, 'Da traten sie an ihn heran und weckten ihn mit den Worten: »Herr, hilf uns: wir gehen unter!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 8, 26, 'Er aber antwortete ihnen: »Was seid ihr so furchtsam, ihr Kleingläubigen!« Dann stand er auf und bedrohte die Winde und den See; da trat völlige Windstille ein.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 8, 27, 'Die Leute aber verwunderten sich und sagten: »Was ist das für ein Mann, daß sogar die Winde und der See ihm gehorsam sind!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 8, 28, 'Als er hierauf an das jenseitige Ufer in das Gebiet der Gadarener gekommen war, traten ihm zwei von bösen Geistern besessene Männer entgegen, die aus den Gräbern hervorkamen und so gemeingefährliche Menschen waren, daß niemand auf der Straße dort an ihnen vorbeigehen konnte.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 8, 29, 'Kaum hatten sie ihn erblickt, da schrien sie laut: »Was hast du mit uns vor, du Sohn Gottes? Bist du hergekommen, um uns vor der Zeit zu quälen?«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 8, 30, 'Es befand sich aber in weiter Entfernung von ihnen eine große Herde Schweine auf der Weide.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 8, 31, 'Da baten ihn die bösen Geister: »Wenn du uns austreiben willst, so laß uns doch in die Schweineherde fahren!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 8, 32, 'Er antwortete ihnen: »Hinweg mit euch!« Da fuhren sie aus und fuhren in die Schweine hinein, und die ganze Herde stürmte infolgedessen den Abhang hinab in den See und ertrank in den Fluten.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 8, 33, 'Die Hirten aber ergriffen die Flucht und berichteten nach ihrer Ankunft in der Stadt den ganzen Vorfall, auch das, was mit den beiden Besessenen vorgegangen war.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 8, 34, 'Da zog die Einwohnerschaft der ganzen Stadt hinaus, Jesus entgegen, und als sie bei ihm eingetroffen waren, baten sie ihn, er möchte ihr Gebiet verlassen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 9, 1, 'Er stieg nun in ein Boot, fuhr über den See zurück und kam wieder in seine Stadt (Kapernaum).');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 9, 2, 'Dort brachte man ihm einen Gelähmten, der auf einem Tragbett lag. Weil nun Jesus ihren Glauben sah, sagte er zu dem Gelähmten: »Sei getrost, mein Sohn: deine Sünden sind (dir) vergeben!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 9, 3, 'Da dachten einige von den Schriftgelehrten bei sich: »Dieser lästert Gott!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 9, 4, 'Weil nun Jesus ihre Gedanken durchschaute, sagte er: »Warum denkt ihr Böses in euren Herzen?');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 9, 5, 'Was ist denn leichter, zu sagen: ›Deine Sünden sind (dir) vergeben‹ oder zu sagen: ›Stehe auf und gehe umher!‹?');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 9, 6, 'Damit ihr aber wißt, daß der Menschensohn die Vollmacht besitzt, Sünden auf der Erde zu vergeben« – hierauf sagte er zu dem Gelähmten: »Stehe auf, nimm dein Bett und gehe heim in dein Haus!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 9, 7, 'Da stand er auf und ging heim in sein Haus.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 9, 8, 'Als die Volksmenge das sah, gerieten sie in Furcht und priesen Gott, daß er den Menschen solche Macht gegeben habe.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 9, 9, 'Als Jesus dann von dort weiterging, sah er einen Mann namens Matthäus an der Zollstätte sitzen und sagte zu ihm: »Folge mir nach!« Da stand er auf und folgte ihm.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 9, 10, 'Als Jesus dann im Hause (des Matthäus) zu Tische saß, kamen viele Zöllner und Sünder und nahmen mit Jesus und seinen Jüngern am Mahle teil.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 9, 11, 'Als die Pharisäer das sahen, sagten sie zu seinen Jüngern: »Warum ißt euer Meister mit den Zöllnern und Sündern?«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 9, 12, 'Als Jesus es hörte, sagte er: »Die Gesunden haben keinen Arzt nötig, wohl aber die Kranken.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 9, 13, 'Geht aber hin und lernt das Wort verstehen: ›An Barmherzigkeit habe ich Wohlgefallen, nicht an Schlachtopfern‹; denn ich bin nicht gekommen, um Gerechte zu berufen, sondern Sünder.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 9, 14, 'Damals traten die Jünger des Johannes an ihn heran mit der Frage: »Warum fasten wir und die Pharisäer (zum Zeichen der Frömmigkeit), während deine Jünger es nicht tun?«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 9, 15, 'Jesus antwortete ihnen: »Können etwa die Hochzeitsgäste trauern, solange der Bräutigam noch in ihrer Mitte weilt? Es werden aber Tage kommen, wo der Bräutigam ihnen genommen ist: dann werden sie fasten.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 9, 16, 'Niemand setzt aber ein Stück ungewalkten Tuches auf ein altes Kleid; denn der eingesetzte Fleck reißt doch von dem Kleide wieder ab, und es entsteht ein noch schlimmerer Riß.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 9, 17, 'Auch füllt man neuen Wein nicht in alte Schläuche; sonst werden die Schläuche gesprengt, und der Wein läuft aus, und auch die Schläuche gehen verloren; nein, man füllt neuen Wein in neue Schläuche: dann bleiben beide erhalten.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 9, 18, 'Während Jesus noch so zu ihnen redete, trat ein Vorsteher (der Synagoge) herzu, warf sich vor ihm nieder und sagte: »Meine Tochter ist soeben gestorben; aber komm und lege ihr deine Hand auf, dann wird sie wieder zum Leben erwachen.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 9, 19, 'Da stand Jesus auf und folgte ihm samt seinen Jüngern.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 9, 20, 'Und siehe, eine Frau, die seit zwölf Jahren am Blutfluß litt, trat von hinten an ihn heran und faßte die Quaste seines Rockes an;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 9, 21, 'sie dachte nämlich bei sich: »Wenn ich nur seinen Rock anfasse, so wird mir geholfen sein.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 9, 22, 'Jesus aber wandte sich um, und als er sie sah, sagte er: »Sei getrost, meine Tochter, dein Glaube hat dir geholfen!« Und die Frau war von dieser Stunde an gesund.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 9, 23, 'Als Jesus dann in das Haus des Vorstehers kam und die Flötenbläser und das Getümmel der Volksmenge sah,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 9, 24, 'sagte er: »Entfernt euch! Das Mädchen ist nicht tot, sondern schläft nur.« Da verlachten sie ihn.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 9, 25, 'Als man aber die Volksmenge aus dem Hause entfernt hatte, ging er (zu der Toten) hinein und faßte sie bei der Hand: da erwachte das Mädchen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 9, 26, 'Die Kunde hiervon verbreitete sich in der ganzen dortigen Gegend.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 9, 27, 'Als Jesus hierauf von dort weiterging, folgten ihm zwei Blinde, die laut riefen: »Sohn Davids, erbarme dich unser!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 9, 28, 'Als er dann in das Haus gekommen war, traten die Blinden zu ihm heran, und Jesus fragte sie: »Glaubt ihr, daß ich (euch) dies zu tun vermag?« Sie antworteten ihm: »Ja, Herr!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 9, 29, 'Da rührte er ihre Augen an und sagte: »Nach eurem Glauben geschehe euch!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 9, 30, 'Da taten sich ihre Augen auf; Jesus aber gab ihnen die strenge Weisung: »Hütet euch! Niemand darf etwas davon erfahren!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 9, 31, 'Sobald sie aber hinausgegangen waren, verbreiteten sie die Kunde von ihm in jener ganzen Gegend.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 9, 32, 'Während diese hinausgingen, brachte man schon wieder einen stummen Besessenen zu ihm;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 9, 33, 'und als der böse Geist ausgetrieben war, konnte der Stumme reden. Da geriet die Volksmenge in Staunen und sagte: »Noch niemals hat man etwas Derartiges in Israel gesehen!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 9, 34, 'Die Pharisäer aber erklärten: »Im Bunde mit dem Obersten der bösen Geister treibt er die Geister aus.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 9, 35, 'So durchwanderte Jesus alle Städte und Dörfer, indem er in ihren Synagogen lehrte, die Heilsbotschaft vom Reiche (Gottes) verkündigte und alle Krankheiten und alle Gebrechen heilte.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 9, 36, 'Beim Anblick der Volksscharen aber erfaßte ihn tiefes Mitleid mit ihnen, denn sie waren abgehetzt und verwahrlost wie Schafe, die keinen Hirten haben.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 9, 37, 'Da sagte er zu seinen Jüngern: »Die Ernte ist groß, aber die Zahl der Arbeiter ist klein;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 9, 38, 'bittet daher den Herrn der Ernte, daß er Arbeiter auf sein Erntefeld sende!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 10, 1, 'Er rief dann seine zwölf Jünger herbei und verlieh ihnen Macht über die unreinen Geister, so daß sie diese auszutreiben und alle Krankheiten und jedes Gebrechen zu heilen vermochten.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 10, 2, 'Die Namen der zwölf Apostel aber sind folgende: Zuerst Simon, der auch Petrus heißt, und sein Bruder Andreas; sodann Jakobus, der Sohn des Zebedäus, und sein Bruder Johannes;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 10, 3, 'Philippus und Bartholomäus; Thomas und der Zöllner Matthäus; Jakobus, der Sohn des Alphäus, und Lebbäus (mit dem Beinamen Thaddäus);');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 10, 4, 'Simon, der Kananäer und Judas, der Iskariote, derselbe, der ihn verraten hat.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 10, 5, 'Diese Zwölf sandte Jesus aus, nachdem er ihnen folgende Weisungen gegeben hatte: »Den Weg zu den Heidenvölkern schlagt nicht ein und tretet auch in keine Samariterstadt ein,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 10, 6, 'geht vielmehr (nur) zu den verlorenen Schafen des Hauses Israel.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 10, 7, 'Auf eurer Wanderung predigt: ›Das Himmelreich ist nahe herbeigekommen!‹');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 10, 8, 'Heilt Kranke, weckt Tote auf, macht Aussätzige rein, treibt böse Geister aus: umsonst habt ihr’s empfangen, umsonst sollt ihr’s auch weitergeben!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 10, 9, 'Sucht euch kein Gold, kein Silber, kein Kupfergeld in eure Gürtel zu verschaffen,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 10, 10, 'nehmt keinen Ranzen mit auf den Weg, auch nicht zwei Röcke, keine Schuhe und keinen Stock, denn der Arbeiter ist seines Unterhalts wert.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 10, 11, 'Wo ihr in eine Stadt oder ein Dorf eintretet, da erkundigt euch, wer dort würdig sei (euch zu beherbergen), und bei dem bleibt, bis ihr weiterzieht.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 10, 12, 'Beim Eintritt in das Haus entbietet ihm den Friedensgruß,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 10, 13, 'und wenn das Haus es verdient, soll der Friede, den ihr ihm gewünscht habt, ihm auch zuteil werden; ist es dessen aber nicht würdig, so soll euer ihm gewünschter Friede zu euch zurückkehren.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 10, 14, 'Wo man euch nicht aufnimmt und euren Worten kein Gehör schenkt, da geht aus dem betreffenden Hause oder Orte hinaus und schüttelt den Staub von euren Füßen ab!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 10, 15, 'Wahrlich ich sage euch: Dem Lande Sodom und Gomorrha wird es am Tage des Gerichts erträglicher ergehen als einer solchen Stadt!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 10, 16, 'Bedenket wohl: ich sende euch wie Schafe mitten unter Wölfe; darum seid klug wie die Schlangen und ohne Falsch wie die Tauben!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 10, 17, '»Nehmt euch aber vor den Menschen in acht! Denn sie werden euch vor die Gerichtshöfe stellen und in ihren Synagogen euch geißeln;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 10, 18, 'auch vor Statthalter und Könige werdet ihr um meinetwillen geführt werden, um Zeugnis vor ihnen und den Heidenvölkern abzulegen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 10, 19, 'Wenn man euch nun (den Gerichten) überliefert, so macht euch keine Sorge darüber, wie oder was ihr reden sollt; denn es wird euch in jener Stunde eingegeben werden, was ihr reden sollt;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 10, 20, 'nicht ihr seid es ja, die dann reden, sondern der Geist eures Vaters ist es, der in euch redet.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 10, 21, 'Es wird aber ein Bruder den Bruder zum Tode überliefern und ein Vater den Sohn, und Kinder werden gegen ihre Eltern auftreten und sie zum Tode bringen,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 10, 22, 'und ihr werdet allen um meines Namens willen verhaßt sein; wer aber ausharrt bis ans Ende, der wird errettet werden.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 10, 23, 'Wenn man euch aber in der einen Stadt verfolgt, so flieht in eine andere; denn wahrlich ich sage euch: Ihr werdet mit den Städten Israels noch nicht zu Ende sein, bis der Menschensohn kommt. –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 10, 24, 'Ein Jünger steht nicht über seinem Meister und ein Knecht nicht über seinem Herrn;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 10, 25, 'ein Jünger muß zufrieden sein, wenn es ihm ergeht wie seinem Meister, und ein Knecht, (wenn es ihm ergeht) wie seinem Herrn. Haben sie den Hausherrn Beelzebul genannt, wieviel mehr werden sie das bei seinen Hausgenossen tun!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 10, 26, '»Fürchtet euch nicht vor ihnen! Denn nichts ist verhüllt, das nicht enthüllt werden wird, und nichts verborgen, das nicht bekannt werden wird.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 10, 27, 'Was ich euch im Dunkel sage, das sprecht im Licht aus, und was ihr (von mir) ins Ohr geflüstert hört, das ruft auf den Dächern aus!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 10, 28, 'Fürchtet euch dabei nicht vor denen, die wohl den Leib töten, aber die Seele nicht zu töten vermögen; fürchtet euch vielmehr vor dem, der die Macht hat, sowohl die Seele als den Leib in der Hölle zu verderben! –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 10, 29, 'Kosten nicht zwei Sperlinge beim Einkauf nur ein paar Pfennige? Und doch fällt keiner von ihnen auf die Erde ohne den Willen eures Vaters.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 10, 30, 'Bei euch aber sind auch die Haare auf dem Haupte alle gezählt.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 10, 31, 'Darum fürchtet euch nicht! Ihr seid mehr wert als viele Sperlinge. –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 10, 32, 'Jeder nun, der sich vor den Menschen zu mir bekennt, zu dem werde auch ich mich vor meinem himmlischen Vater bekennen;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 10, 33, 'wer mich aber vor den Menschen verleugnet, den werde auch ich vor meinem himmlischen Vater verleugnen.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 10, 34, '»Denkt nicht, ich sei gekommen, um Frieden auf die Erde zu bringen! Nein, ich bin nicht gekommen, um Frieden zu bringen, sondern das Schwert.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 10, 35, 'Denn ich bin gekommen, ›um den Sohn mit seinem Vater, die Tochter mit ihrer Mutter und die Schwiegertochter mit ihrer Schwiegermutter zu entzweien,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 10, 36, 'und die eigenen Hausgenossen werden einander feindselig gegenüberstehen‹.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 10, 37, 'Wer Vater oder Mutter mehr liebt als mich, ist meiner nicht wert, und wer Sohn oder Tochter mehr liebt als mich, ist meiner nicht wert;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 10, 38, 'und wer nicht sein Kreuz auf sich nimmt und mir nachfolgt, ist meiner nicht wert. –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 10, 39, 'Wer sein Leben findet, wird es verlieren, und wer sein Leben um meinetwillen verliert, der wird es finden.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 10, 40, '»Wer euch aufnimmt, nimmt mich auf, und wer mich aufnimmt, nimmt den auf, der mich gesandt hat.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 10, 41, 'Wer einen Propheten aufnimmt, eben weil er ein Prophet heißt, der wird dafür den Lohn eines Propheten empfangen; und wer einen Gerechten aufnimmt, eben weil er ein Gerechter heißt, der wird dafür den Lohn eines Gerechten empfangen;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 10, 42, 'und wer einem von diesen geringen Leuten seines Namens wegen, weil er ein Jünger heißt, auch nur einen Becher frischen Wassers zu trinken gibt – wahrlich ich sage euch: Es soll ihm nicht unbelohnt bleiben!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 11, 1, 'Als Jesus nun mit der Unterweisung seiner zwölf Jünger zu Ende gekommen war, zog er von dort weiter, um in ihren Städten zu lehren und zu predigen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 11, 2, 'Als aber Johannes im Gefängnis von dem Wirken Christi hörte, sandte er durch seine Jünger Botschaft an ihn');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 11, 3, 'und ließ ihn fragen: »Bist du es, der da kommen soll, oder sollen wir auf einen andern warten?«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 11, 4, 'Jesus gab ihnen zur Antwort: »Geht hin und berichtet dem Johannes, was ihr hört und seht:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 11, 5, 'Blinde werden sehend und Lahme gehen, Aussätzige werden rein und Taube hören, Tote werden auferweckt, und Armen wird die Heilsbotschaft verkündigt,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 11, 6, 'und selig ist, wer an mir keinen Anstoß nimmt!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 11, 7, 'Als diese nun den Rückweg antraten, begann Jesus zu den Volksscharen über Johannes zu reden: »Wozu seid ihr damals in die Wüste hinausgezogen? Wolltet ihr euch ein Schilfrohr ansehen, das vom Winde hin und her bewegt wird?');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 11, 8, 'Nein; aber wozu seid ihr hinausgezogen? Wolltet ihr einen Mann in weichen Gewändern sehen? Nein; die Leute, welche weiche Gewänder tragen, sind in den Königsschlössern zu finden.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 11, 9, 'Aber wozu seid ihr denn hinausgezogen? Wolltet ihr einen Propheten sehen? Ja, ich sage euch: einen Mann, der noch mehr ist als ein Prophet!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 11, 10, 'Denn dieser ist es, auf den sich das Schriftwort bezieht: ›Siehe, ich sende meinen Boten vor dir her, der dir den Weg vor dir her bereiten soll.‹');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 11, 11, 'Wahrlich ich sage euch: Unter den von Frauen Geborenen ist keiner aufgetreten, der größer wäre als Johannes der Täufer; doch der Kleinste im Himmelreich ist größer als er.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 11, 12, 'Aber seit den Tagen Johannes des Täufers bis jetzt bricht das Himmelreich sich mit Gewalt Bahn, und die, welche Gewalt anwenden, reißen es an sich.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 11, 13, 'Denn alle Propheten und das Gesetz haben bis auf Johannes geweissagt,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 11, 14, 'und wenn ihr es annehmen wollt: Er ist Elia, der da kommen soll.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 11, 15, 'Wer Ohren hat, der höre!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 11, 16, 'Mit wem soll ich aber das gegenwärtige Geschlecht vergleichen? Kindern gleicht es, die auf den öffentlichen Plätzen sitzen und ihren Gespielen zurufen:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 11, 17, '›Wir haben euch gepfiffen, doch ihr habt nicht getanzt; wir haben ein Klagelied angestimmt, doch ihr habt euch nicht an die Brust geschlagen!‹');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 11, 18, 'Denn Johannes ist gekommen, der nicht aß und nicht trank; da sagen sie: ›Er hat einen bösen Geist.‹');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 11, 19, 'Nun ist der Menschensohn gekommen, welcher ißt und trinkt; da sagen sie: ›Seht, der Schlemmer und Weintrinker, der Freund der Zöllner und Sünder!‹ Und doch ist die Weisheit (Gottes) gerechtfertigt worden durch ihre Werke.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 11, 20, 'Damals begann er gegen die Städte, in denen seine meisten Wunder geschehen waren, Drohworte zu richten, weil sie nicht Buße getan hatten:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 11, 21, '»Wehe dir, Chorazin! Wehe dir, Bethsaida! Denn wenn in Tyrus und Sidon die Wunder geschehen wären, die in euch geschehen sind, so hätten sie längst in Sack und Asche Buße getan.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 11, 22, 'Doch ich sage euch: Es wird Tyrus und Sidon am Tage des Gerichts erträglicher ergehen als euch!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 11, 23, 'Und du, Kapernaum, wirst doch nicht etwa bis zum Himmel erhöht werden? Nein, bis zur Totenwelt wirst du hinabgestoßen werden. Denn wenn in Sodom die Wunder geschehen wären, die in dir geschehen sind, so stände es noch heutigen Tages.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 11, 24, 'Doch ich sage euch: Dem Lande Sodom wird es am Tage des Gerichts erträglicher ergehen als dir!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 11, 25, 'Zu jener Zeit hob Jesus an und sagte: »Ich preise dich, Vater, Herr des Himmels und der Erde, daß du dies vor Weisen und Klugen verborgen und es Unmündigen geoffenbart hast;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 11, 26, 'ja, Vater, denn so ist es dir wohlgefällig gewesen! –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 11, 27, 'Alles ist mir von meinem Vater übergeben worden, und niemand erkennt den Sohn als nur der Vater, und niemand erkennt den Vater als nur der Sohn und der, welchem der Sohn ihn offenbaren will.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 11, 28, '»Kommt her zu mir alle, die ihr niedergedrückt und belastet seid: ich will euch Ruhe schaffen!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 11, 29, 'Nehmt mein Joch auf euch und lernt von mir; denn ich bin sanftmütig und von Herzen demütig: so werdet ihr Ruhe finden für eure Seelen;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 11, 30, 'denn mein Joch ist sanft, und meine Last ist leicht.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 12, 1, 'Zu jener Zeit wanderte Jesus an einem Sabbat durch die Kornfelder; seine Jünger aber hatten Hunger und begannen daher, Ähren abzupflücken und (die Körner) zu essen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 12, 2, 'Als die Pharisäer das wahrnahmen, sagten sie zu ihm: »Sieh doch! Deine Jünger tun da etwas, was man am Sabbat nicht tun darf!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 12, 3, 'Da antwortete er ihnen: »Habt ihr nicht gelesen, was David getan hat, als ihn samt seinen Begleitern hungerte?');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 12, 4, 'Wie er da ins Gotteshaus hineinging und sie die Schaubrote aßen, die doch er und seine Begleiter nicht essen durften, sondern nur die Priester?');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 12, 5, 'Oder habt ihr im Gesetz nicht gelesen, daß am Sabbat die Priester im Tempel den Sabbat entheiligen und sich dadurch doch nicht versündigen?');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 12, 6, 'Ich sage euch aber: Hier steht Größeres als der Tempel!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 12, 7, 'Wenn ihr aber erkannt hättet, was das Wort besagt: ›An Barmherzigkeit habe ich Wohlgefallen und nicht an Schlachtopfern‹, so hättet ihr die Unschuldigen nicht verurteilt;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 12, 8, 'denn der Menschensohn ist Herr über den Sabbat.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 12, 9, 'Er ging dann von dort weiter und kam in ihre Synagoge.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 12, 10, 'Da war ein Mann, der einen gelähmten Arm hatte; und sie richteten die Frage an ihn: »Darf man am Sabbat heilen?« – sie wollten nämlich einen Grund zu einer Anklage gegen ihn haben.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 12, 11, 'Er aber antwortete ihnen: »Wo wäre jemand unter euch, der ein einziges Schaf besitzt und, wenn dieses ihm am Sabbat in eine Grube fällt, es nicht ergriffe und herauszöge?');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 12, 12, 'Wieviel wertvoller ist nun aber ein Mensch als ein Schaf! Also darf man am Sabbat Gutes tun.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 12, 13, 'Hierauf sagte er zu dem Manne: »Strecke deinen Arm aus!« Er streckte ihn aus, und er wurde wiederhergestellt, gesund wie der andere.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 12, 14, 'Da gingen die Pharisäer hinaus und faßten einen Beschluß gegen ihn, um ihn umzubringen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 12, 15, 'Als Jesus das erfuhr, zog er sich von dort zurück; und es zogen ihm viele nach, die er alle heilte,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 12, 16, 'denen er aber die strenge Weisung gab, sie sollten Stillschweigen über ihn bewahren.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 12, 17, 'So sollte das Wort des Propheten Jesaja seine Erfüllung finden, der da sagt:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 12, 18, '»Siehe, mein Knecht, den ich erwählt habe, mein Geliebter, an dem mein Herz Wohlgefallen gefunden hat! Ich will meinen Geist auf ihn legen, und er soll den Heidenvölkern das Gericht ankündigen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 12, 19, 'Er wird nicht zanken noch schreien, und niemand wird seine Stimme auf den Straßen hören;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 12, 20, 'ein geknicktes Rohr wird er nicht zerbrechen und einen glimmenden Docht nicht auslöschen, bis er das Gericht siegreich durchgeführt hat;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 12, 21, 'und auf seinen Namen werden die Heidenvölker ihre Hoffnung setzen.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 12, 22, 'Damals brachte man einen Besessenen zu ihm, der blind und stumm war, und er heilte ihn, so daß der Stumme redete und sehen konnte.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 12, 23, 'Da geriet die ganze Volksmenge vor Staunen außer sich und sagte: »Sollte dieser nicht doch der Sohn Davids sein?«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 12, 24, 'Als die Pharisäer das hörten, erklärten sie: »Dieser treibt die bösen Geister nur im Bunde mit Beelzebul, dem Obersten der bösen Geister, aus.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 12, 25, 'Weil Jesus nun ihre Gedanken kannte, sagte er zu ihnen: »Jedes Reich, das in sich selbst uneinig ist, wird verwüstet, und keine Stadt, kein Haus, die in sich selbst uneinig sind, können Bestand haben.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 12, 26, 'Wenn nun der Satan den Satan austreibt, so ist er mit sich selbst in Zwiespalt geraten: wie kann da seine Herrschaft Bestand haben?');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 12, 27, 'Und wenn ich die bösen Geister im Bunde mit Beelzebul austreibe, mit wessen Hilfe treiben dann eure Söhne sie aus? Darum werden diese eure Richter sein!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 12, 28, 'Wenn ich aber die bösen Geister durch den Geist Gottes austreibe, so ist ja das Reich Gottes zu euch gekommen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 12, 29, 'Oder wie könnte jemand in das Haus des Starken eindringen und ihm sein Rüstzeug rauben, ohne zunächst den Starken gefesselt zu haben? Erst dann kann er ihm das Haus ausplündern. –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 12, 30, 'Wer nicht mit mir ist, der ist gegen mich, und wer nicht mit mir sammelt, der zerstreut.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 12, 31, '»Deshalb sage ich euch: Jede Sünde und Lästerung wird den Menschen vergeben werden, aber die Lästerung des Geistes wird nicht vergeben werden.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 12, 32, 'Auch wenn jemand ein Wort gegen den Menschensohn ausspricht, wird es ihm vergeben werden; wer aber gegen den heiligen Geist spricht, dem wird es weder in dieser Weltzeit noch in der künftigen vergeben werden.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 12, 33, 'Entweder macht den Baum gut, dann ist auch seine Frucht gut; oder macht den Baum faul, dann ist auch seine Frucht faul; denn an der Frucht erkennt man den Baum.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 12, 34, 'Ihr Schlangenbrut! Wie solltet ihr imstande sein, Gutes zu reden, da ihr doch böse seid? Denn wovon das Herz voll ist, davon redet der Mund.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 12, 35, 'Ein guter Mensch bringt aus der guten Schatzkammer (seines Herzens) Gutes hervor, während ein böser Mensch aus seiner bösen Schatzkammer Böses hervorbringt.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 12, 36, 'Ich sage euch aber: Von jedem unnützen Wort, das die Menschen reden, davon werden sie Rechenschaft am Tage des Gerichts zu geben haben;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 12, 37, 'denn nach deinen Worten wirst du gerechtgesprochen werden, und nach deinen Worten wirst du verurteilt werden.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 12, 38, 'Daraufhin entgegneten ihm einige von den Schriftgelehrten und Pharisäern: »Meister, wir möchten ein Wunderzeichen von dir sehen!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 12, 39, 'Er aber gab ihnen zur Antwort: »Ein böses und ehebrecherisches Geschlecht verlangt ein Zeichen; doch es wird ihm kein Zeichen gegeben werden als das Zeichen des Propheten Jona.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 12, 40, 'Denn wie Jona drei Tage und drei Nächte im Leibe des Riesenfisches gewesen ist, so wird der Menschensohn drei Tage und drei Nächte im Inneren der Erde sein.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 12, 41, 'Die Männer von Ninive werden beim Gericht mit diesem Geschlecht (als Zeugen) auftreten und seine Verurteilung herbeiführen; denn sie haben auf Jonas Predigt hin Buße getan, und hier steht doch Größeres als Jona!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 12, 42, 'Die Königin aus dem Südland wird beim Gericht mit diesem Geschlecht (als Zeugin) auftreten und seine Verurteilung herbeiführen; denn sie kam von den Enden der Erde, um die Weisheit Salomos zu hören, und hier steht doch Größeres als Salomo!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 12, 43, 'Wenn aber der unreine Geist von einem Menschen ausgefahren ist, so durchirrt er wüste Gegenden und sucht dort eine Ruhestätte, findet aber keine.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 12, 44, 'Da sagt er dann: ›Ich will in mein Haus zurückkehren, das ich verlassen habe!‹ Wenn er dann hinkommt, findet er es leer stehen, sauber gefegt und schön aufgeräumt.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 12, 45, 'Hierauf geht er hin und nimmt noch sieben andere Geister mit sich, die noch schlimmer sind als er selbst, und sie ziehen ein und nehmen dort Wohnung, und das Ende wird bei einem solchen Menschen schlimmer, als sein Anfang war. Ebenso wird es auch diesem bösen Geschlecht ergehen.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 12, 46, 'Während er noch zu den Volksscharen redete, siehe, da standen seine Mutter und seine Brüder draußen und wünschten ihn zu sprechen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 12, 47, 'Da sagte jemand zu ihm: »Deine Mutter und deine Brüder stehen draußen und wünschen dich zu sprechen.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 12, 48, 'Er aber gab dem, der es ihm meldete, zur Antwort: »Wer ist meine Mutter, und wer sind meine Brüder?«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 12, 49, 'Dann streckte er seine Hand aus zu seinen Jüngern hin und sagte: »Seht, diese hier sind meine Mutter und meine Brüder;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 12, 50, 'denn wer den Willen meines himmlischen Vaters tut, der ist mein Bruder und Schwester und Mutter!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 13, 1, 'An jenem Tage ging Jesus von Hause weg und setzte sich am See nieder;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 13, 2, 'und es versammelte sich eine große Volksmenge bei ihm, so daß er in ein Boot stieg und sich darin niedersetzte, während die ganze Volksmenge längs dem Ufer stand.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 13, 3, 'Da redete er mancherlei zu ihnen in Gleichnissen mit den Worten: »Seht, der Sämann ging aus, um zu säen;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 13, 4, 'und beim Säen fiel einiges (von dem Saatkorn) auf den Weg längshin; da kamen die Vögel und fraßen es auf.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 13, 5, 'Anderes fiel auf die felsigen Stellen, wo es nicht viel Erdreich hatte und bald aufschoß, weil es nicht tief in den Boden dringen konnte;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 13, 6, 'als dann aber die Sonne aufgegangen war, wurde es versengt, und weil es nicht Wurzel (geschlagen) hatte, verdorrte es.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 13, 7, 'Wieder anderes fiel unter die Dornen, und die Dornen wuchsen empor und erstickten es.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 13, 8, 'Anderes aber fiel auf den guten Boden und brachte Frucht, das eine hundertfältig, das andere sechzigfältig, das andere dreißigfältig.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 13, 9, 'Wer Ohren hat, der höre!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 13, 10, 'Da traten die Jünger an Jesus heran und fragten ihn: »Warum redest du in Gleichnissen zu ihnen?«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 13, 11, 'Er antwortete: »Euch ist es gegeben, die Geheimnisse des Himmelreichs zu erkennen, jenen aber ist es nicht gegeben.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 13, 12, 'Denn wer da hat, dem wird gegeben werden, so daß er Überfluß hat; wer aber nicht hat, dem wird auch das genommen werden, was er hat.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 13, 13, 'Deshalb rede ich in Gleichnissen zu ihnen, weil sie mit sehenden Augen doch nicht sehen und mit hörenden Ohren doch nicht hören und nicht verstehen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 13, 14, 'So geht an ihnen die Weissagung Jesajas in Erfüllung, die da lautet: ›Ihr werdet immerfort hören und doch nicht verstehen, und ihr werdet immerfort sehen und doch nicht wahrnehmen!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 13, 15, 'Denn das Herz dieses Volkes ist stumpf geworden: ihre Ohren sind schwerhörig geworden, und ihre Augen haben sie geschlossen, damit sie mit den Augen nicht sehen und mit den Ohren nicht hören und mit dem Herzen nicht zum Verständnis gelangen, und sie sich (nicht) bekehren, daß ich sie heilen könnte.‹');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 13, 16, 'Aber eure Augen sind selig (zu preisen), weil sie sehen, und eure Ohren, weil sie hören!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 13, 17, 'Denn wahrlich ich sage euch: Viele Propheten und Gerechte haben sehnlichst gewünscht, das zu sehen, was ihr seht, und haben es nicht gesehen, und hätten gerne das gehört, was ihr hört, und haben es nicht zu hören bekommen.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 13, 18, '»Ihr sollt also die Deutung des Gleichnisses vom Sämann zu hören bekommen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 13, 19, 'Bei jedem, der das Wort vom Reich (Gottes) hört und es nicht versteht, da kommt der Böse und reißt das aus, was in sein Herz gesät ist; bei diesem ist der Same auf den Weg längshin gefallen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 13, 20, 'Wo aber auf die felsigen Stellen gesät worden ist, das bedeutet einen solchen, der das Wort hört und es für den Augenblick mit Freuden annimmt;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 13, 21, 'er hat aber keine feste Wurzel in sich, sondern ist ein Kind des Augenblicks; wenn dann Bedrängnis oder Verfolgung um des Wortes willen eintritt, wird er sogleich irre.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 13, 22, 'Wo sodann unter die Dornen gesät worden ist, das bedeutet einen Menschen, der das Wort wohl hört, bei dem aber die weltlichen Sorgen und der Betrug des Reichtums das Wort ersticken, so daß es ohne Frucht bleibt.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 13, 23, 'Wo aber auf den guten Boden gesät worden ist, das bedeutet einen solchen, der das Wort hört und auch versteht; dieser bringt dann auch Frucht, und der eine trägt hundertfältig, der andere sechzigfältig, der andere dreißigfältig.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 13, 24, 'Ein anderes Gleichnis legte er ihnen so vor: »Mit dem Himmelreich verhält es sich wie mit einem Manne, der guten Samen auf seinem Acker ausgesät hatte.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 13, 25, 'Während aber die Leute schliefen, kam sein Feind, säte Unkraut zwischen den Weizen und entfernte sich dann wieder.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 13, 26, 'Als nun die Saat aufwuchs und Frucht ansetzte, da kam auch das Unkraut zum Vorschein.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 13, 27, 'Da traten die Knechte zu dem Hausherrn und sagten: ›Herr, hast du nicht guten Samen auf deinen Acker gesät? Woher hat er denn nun das Unkraut?‹');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 13, 28, 'Er antwortete ihnen: ›Das hat ein Feind getan.‹ Die Knechte fragten ihn weiter: ›Willst du nun, daß wir hingehen und es zusammenlesen?‹');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 13, 29, 'Doch er antwortete: ›Nein, ihr würdet sonst beim Sammeln des Unkrauts zugleich auch den Weizen ausreißen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 13, 30, 'Laßt beides zusammen bis zur Ernte wachsen; dann will ich zur Erntezeit den Schnittern sagen: Lest zuerst das Unkraut zusammen und bindet es in Bündel, damit man es verbrenne; den Weizen aber sammelt in meine Scheuer!‹«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 13, 31, 'Ein anderes Gleichnis legte er ihnen so vor: »Das Himmelreich ist einem Senfkorn vergleichbar, das ein Mann nahm und auf seinen Acker säte.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 13, 32, 'Dies ist das kleinste unter allen Samenarten; wenn es aber herangewachsen ist, dann ist es größer als die anderen Gartengewächse und wird zu einem Baum, so daß die Vögel des Himmels kommen und in seinen Zweigen nisten.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 13, 33, 'Noch ein anderes Gleichnis teilte er ihnen so mit: »Das Himmelreich gleicht dem Sauerteig, den eine Frau nahm und unter drei Scheffel Mehl mengte, bis der ganze Teig durchsäuert war.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 13, 34, 'Dies alles redete Jesus in Gleichnissen zu den Volksscharen, und ohne Gleichnisse redete er nichts zu ihnen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 13, 35, 'So sollte sich das Wort des Propheten erfüllen, der da sagt: »Ich will meinen Mund zu Gleichnissen auftun, ich will aussprechen, was seit Grundlegung der Welt verborgen gewesen ist.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 13, 36, 'Hierauf entließ er die Volksmenge und begab sich in seine Wohnung. Da traten seine Jünger zu ihm und baten ihn: »Erkläre uns das Gleichnis vom Unkraut auf dem Acker!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 13, 37, 'Er antwortete: »Der Mann, der den guten Samen sät, ist der Menschensohn;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 13, 38, 'der Acker ist die Welt; die gute Saat, das sind die Söhne des Reiches; das Unkraut dagegen sind die Söhne des Bösen;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 13, 39, 'der Feind ferner, der das Unkraut gesät hat, ist der Teufel; die Ernte ist das Ende dieser Weltzeit, und die Schnitter sind Engel.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 13, 40, 'Wie nun das Unkraut gesammelt und im Feuer verbrannt wird, so wird es auch am Ende der Weltzeit der Fall sein:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 13, 41, 'Der Menschensohn wird seine Engel aussenden; die werden aus seinem Reich alle Ärgernisse und alle die sammeln, welche die Gesetzlosigkeit üben,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 13, 42, 'und werden sie in den Feuerofen werfen: dort wird lautes Weinen und Zähneknirschen sein.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 13, 43, 'Alsdann werden die Gerechten im Reich ihres Vaters wie die Sonne leuchten. Wer Ohren hat, der höre!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 13, 44, '»Das Himmelreich ist einem im Acker vergrabenen Schatz gleich; den fand ein Mann und vergrub ihn (wieder); alsdann ging er in seiner Freude hin, verkaufte alles, was er besaß, und kaufte jenen Acker.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 13, 45, 'Wiederum gleicht das Himmelreich einem Kaufmann, der wertvolle Perlen suchte;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 13, 46, 'und als er eine besonders kostbare Perle gefunden hatte, ging er heim, verkaufte alles, was er besaß, und kaufte sie.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 13, 47, 'Weiter ist das Himmelreich einem Schleppnetz gleich, das ins Meer ausgeworfen wurde und in welchem sich Fische jeder Art in Menge fingen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 13, 48, 'Als es ganz gefüllt war, zog man es an den Strand, setzte sich nieder und sammelte das Gute in Gefäße, das Faule aber warf man weg.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 13, 49, 'So wird es auch am Ende der Weltzeit zugehen: Die Engel werden ausgehen und die Bösen aus der Mitte der Gerechten absondern');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 13, 50, 'und sie in den Feuerofen werfen: dort wird lautes Weinen und Zähneknirschen sein.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 13, 51, '»Habt ihr dies alles verstanden?« Sie antworteten ihm: »Ja.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 13, 52, 'Da sagte er zu ihnen: »Deshalb ist jeder Schriftgelehrte, der in der Schule des Himmelreichs ausgebildet ist, einem Hausherrn gleich, der aus seinem Schatze Neues und Altes hervorholt.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 13, 53, 'Als Jesus nun diese Gleichnisse beendigt hatte, brach er von dort auf;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 13, 54, 'und als er in seine Vaterstadt (Nazareth) gekommen war, machte er in ihrer Synagoge durch seine Lehre solchen Eindruck auf sie, daß sie in Erstaunen gerieten und fragten: »Woher hat dieser solche Weisheit und die Machttaten?');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 13, 55, 'Ist dieser nicht der Sohn des Zimmermanns? Heißt seine Mutter nicht Maria, und sind nicht Jakobus und Joseph, Simon und Judas seine Brüder?');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 13, 56, 'Wohnen nicht auch seine Schwestern alle hier bei uns? Woher hat dieser also dies alles?«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 13, 57, 'So nahmen sie Anstoß an ihm. Jesus aber sagte zu ihnen: »Ein Prophet gilt nirgends weniger als in seiner Vaterstadt und in seiner Familie.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 13, 58, 'So tat er denn dort infolge ihres Unglaubens nicht viele Wunder.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 14, 1, 'Zu jener Zeit erhielt der Vierfürst Herodes Kunde von Jesus');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 14, 2, 'und sagte zu seinen Dienern: »Das ist Johannes der Täufer; der ist von den Toten auferweckt worden; darum sind die Wunderkräfte in ihm wirksam.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 14, 3, 'Herodes hatte nämlich den Johannes festnehmen und in Fesseln und ins Gefängnis werfen lassen mit Rücksicht auf Herodias, die Gattin seines Bruders Philippus;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 14, 4, 'denn Johannes hatte ihm vorgehalten: »Du darfst sie nicht (zur Frau) haben.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 14, 5, 'Er hätte ihn nun am liebsten ums Leben bringen lassen, fürchtete sich aber vor dem Volk, weil dieses ihn für einen Propheten hielt.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 14, 6, 'Als aber der Geburtstag des Herodes gefeiert wurde, tanzte die Tochter der Herodias vor der Festgesellschaft und gefiel dem Herodes so sehr,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 14, 7, 'daß er ihr mit einem Eide zusagte, er wolle ihr jede Bitte gewähren.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 14, 8, 'Da sagte sie, schon vorher von ihrer Mutter dazu angestiftet: »Gib mir hier auf einer Schüssel den Kopf Johannes des Täufers!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 14, 9, 'Obgleich nun der König mißmutig darüber war, gab er doch wegen seiner Eide und mit Rücksicht auf seine Tischgäste den Befehl, man solle ihn ihr geben;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 14, 10, 'er schickte also (Diener) hin und ließ Johannes im Gefängnis enthaupten.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 14, 11, 'Sein Kopf wurde dann auf einer Schüssel gebracht und dem Mädchen gegeben; die brachte ihn ihrer Mutter.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 14, 12, 'Die Jünger des Johannes kamen hierauf, holten den Leichnam und bestatteten ihn; dann gingen sie hin und berichteten es Jesus.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 14, 13, 'Als Jesus dies hörte, entwich er von dort in einem Boote an einen einsamen Ort, um für sich allein zu sein; doch als die Volksmenge das erfuhr, folgte sie ihm zu Fuß aus den Städten nach.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 14, 14, 'Als er dann (aus der Einsamkeit) wieder hervorkam und eine große Volksmenge sah, ergriff ihn Mitleid mit ihnen, und er heilte ihre Kranken.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 14, 15, 'Als es aber Abend geworden war, traten seine Jünger zu ihm und sagten: »Die Gegend hier ist öde und die Zeit schon vorgerückt; laß daher das Volk ziehen, damit sie in die Ortschaften gehen und sich Lebensmittel kaufen!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 14, 16, 'Jesus aber erwiderte ihnen: »Sie brauchen nicht wegzugehen: gebt ihr ihnen zu essen!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 14, 17, 'Da antworteten sie ihm: »Wir haben hier nichts weiter als fünf Brote und zwei Fische.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 14, 18, 'Er aber sagte: »Bringt sie mir hierher!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 14, 19, 'Er ließ dann die Volksscharen sich auf dem Rasen lagern, nahm die fünf Brote und die beiden Fische, blickte zum Himmel empor, sprach den Lobpreis (Gottes) und brach die Brote; hierauf gab er sie den Jüngern, die Jünger aber teilten sie dem Volke zu.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 14, 20, 'Und sie aßen alle und wurden satt; dann sammelte man die Brocken, die übriggeblieben waren: zwölf Körbe voll.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 14, 21, 'Die Zahl derer aber, die gegessen hatten, betrug etwa fünftausend Männer, ungerechnet die Frauen und die Kinder.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 14, 22, 'Und sogleich nötigte Jesus seine Jünger, ins Boot zu steigen und vor ihm nach dem jenseitigen Ufer hinüberzufahren, damit er inzwischen die Volksscharen entließe.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 14, 23, 'Als er das getan hatte, stieg er für sich allein den Berg hinan, um zu beten; und als es Abend geworden war, befand er sich dort allein;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 14, 24, 'das Boot aber war schon mitten auf dem See und wurde von den Wellen hart bedrängt, denn der Wind stand ihnen entgegen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 14, 25, 'In der vierten Nachtwache aber kam Jesus auf sie zu, indem er über den See dahinging.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 14, 26, 'Als nun die Jünger ihn so auf dem See wandeln sahen, gerieten sie in Bestürzung, weil sie dachten, es sei ein Gespenst, und sie schrien vor Angst laut auf.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 14, 27, 'Doch Jesus redete sie sogleich mit den Worten an: »Seid getrost: ich bin es; fürchtet euch nicht!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 14, 28, 'Da antwortete ihm Petrus: »Herr, wenn du es bist, so laß mich über das Wasser zu dir kommen!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 14, 29, 'Er erwiderte: »So komm!« Da stieg Petrus aus dem Boot, ging über das Wasser hin und kam auf Jesus zu;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 14, 30, 'doch als er den Sturmwind wahrnahm, wurde ihm angst, und als er unterzusinken begann, rief er laut: »Herr, hilf mir!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 14, 31, 'Sogleich streckte Jesus die Hand aus, faßte ihn und sagte zu ihm: »Du Kleingläubiger! Warum hast du gezweifelt?«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 14, 32, 'Als sie dann in das Boot gestiegen waren, legte sich der Wind.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 14, 33, 'Die Männer im Boot aber warfen sich vor ihm nieder und sagten: »Du bist wahrhaftig Gottes Sohn!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 14, 34, 'Nachdem sie dann (über den See) hinübergefahren waren, kamen sie ans Land nach Gennesaret.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 14, 35, 'Sobald die Bewohner dieses Ortes ihn erkannt hatten, schickten sie Boten in die ganze dortige Umgegend, und man brachte alle Kranken zu ihm,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 14, 36, 'und (diese) baten ihn, nur die Quaste seines Rockes anfassen zu dürfen, und alle, die sie anfaßten, wurden völlig geheilt.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 15, 1, 'Damals kamen Pharisäer und Schriftgelehrte aus Jerusalem zu Jesus und fragten ihn:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 15, 2, '»Warum übertreten deine Jünger die Satzungen, welche uns die Alten überliefert haben? Sie waschen sich ja die Hände nicht, wenn sie Brot essen wollen.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 15, 3, 'Da antwortete er ihnen mit den Worten: »Warum übertretet auch ihr das Gebot Gottes euren überlieferten Satzungen zuliebe?');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 15, 4, 'Gott hat doch geboten: ›Ehre deinen Vater und deine Mutter‹ und: ›Wer Vater oder Mutter flucht, soll des Todes sterben!‹');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 15, 5, 'Ihr aber sagt: ›Wer zum Vater oder zur Mutter sagt: Ich will Gott als Opfergabe (für den Tempelschatz) das weihen, was du sonst als Unterstützung von mir empfangen hättest, –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 15, 6, 'der braucht seinen Vater oder seine Mutter nicht weiter zu ehren.‹ Damit habt ihr das Wort Gottes euren überlieferten Satzungen zulieb außer Kraft gesetzt!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 15, 7, 'Ihr Heuchler! Treffend hat Jesaja von euch geweissagt mit den Worten:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 15, 8, '›Dieses Volk ehrt mich nur mit den Lippen, ihr Herz aber ist weit entfernt von mir;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 15, 9, 'doch vergeblich verehren sie mich, weil sie Menschensatzungen als Lehren vortragen.‹«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 15, 10, 'Nachdem er dann die Volksmenge herbeigerufen hatte, sagte er zu ihnen: »Hört zu und sucht es zu verstehen!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 15, 11, 'Nicht das, was in den Mund hineingeht, verunreinigt den Menschen, sondern was aus dem Munde herauskommt, das macht den Menschen unrein.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 15, 12, 'Hierauf traten die Jünger an ihn heran und sagten zu ihm: »Weißt du, daß die Pharisäer an dem Wort, das sie von dir haben hören müssen, Anstoß genommen haben?«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 15, 13, 'Er aber antwortete: »Jede Pflanze, die nicht mein himmlischer Vater gepflanzt hat, wird mit der Wurzel ausgerissen werden.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 15, 14, 'Laßt sie nur: sie sind blinde Blindenführer! Wenn aber ein Blinder einem anderen Blinden Wegführer ist, werden beide in die Grube fallen.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 15, 15, 'Da nahm Petrus das Wort und sagte zu ihm: »Erkläre uns das Gleichnis (von vorhin)!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 15, 16, 'Da antwortete er: »Seid auch ihr immer noch ohne Verständnis?');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 15, 17, 'Begreift ihr nicht, daß alles, was in den Mund hineingeht, in den Leib gelangt und auf dem natürlichen Wege wieder ausgeschieden wird?');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 15, 18, 'Was dagegen aus dem Munde herauskommt, geht aus dem Herzen hervor, und das ist es, was den Menschen verunreinigt.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 15, 19, 'Denn aus dem Herzen kommen böse Gedanken hervor: Mordtaten, Ehebruch, Unzucht, Diebstahl, Verleumdungen und Lästerungen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 15, 20, 'Das sind die Dinge, die den Menschen verunreinigen; dagegen das Essen mit ungewaschenen Händen macht den Menschen nicht unrein.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 15, 21, 'Jesus ging dann von dort weg und zog sich in die Gegend von Tyrus und Sidon zurück.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 15, 22, 'Da kam eine kanaanäische Frau aus jenem Gebiet her und rief ihn laut an: »Erbarme dich meiner, Herr, du Sohn Davids! Meine Tochter wird von einem bösen Geist schlimm geplagt!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 15, 23, 'Er antwortete ihr aber kein Wort. Da traten seine Jünger zu ihm und baten ihn: »Fertige sie doch ab! Sie schreit ja hinter uns her!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 15, 24, 'Er aber antwortete: »Ich bin nur zu den verlorenen Schafen des Hauses Israel gesandt.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 15, 25, 'Sie aber kam, warf sich vor ihm nieder und bat: »Herr, hilf mir!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 15, 26, 'Doch er erwiderte: »Es ist nicht recht, den Kindern das Brot zu nehmen und es den Hündlein hinzuwerfen.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 15, 27, 'Darauf sagte sie: »O doch, Herr! Die Hündlein bekommen ja auch von den Brocken zu essen, die vom Tisch ihrer Herren fallen.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 15, 28, 'Da antwortete ihr Jesus: »O Frau, dein Glaube ist groß; dir geschehe, wie du es wünschest!« Und ihre Tochter wurde von dieser Stunde an gesund.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 15, 29, 'Jesus ging dann von dort wieder weg und kam an den Galiläischen See, und als er den Berg hinangestiegen war, setzte er sich dort nieder.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 15, 30, 'Da kamen große Scharen Volks zu ihm; sie brachten Lahme, Blinde, Krüppel, Stumme und viele andere Kranke mit sich, die sie ihm vor die Füße legten; und er heilte sie,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 15, 31, 'so daß die Volksmenge sich verwunderte, als sie sah, daß Stumme redeten, Krüppel gesund wurden, Lahme einhergehen konnten und Blinde sehend wurden; und sie priesen den Gott Israels.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 15, 32, 'Jesus aber rief seine Jünger zu sich und sagte: »Mich jammert des Volks, denn sie halten nun schon drei Tage bei mir aus, ohne daß sie etwas zu essen haben, und ich mag sie nicht von mir lassen, ehe sie gegessen haben: sie würden sonst unterwegs verschmachten.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 15, 33, 'Da erwiderten ihm die Jünger: »Woher sollen wir hier in der Einöde so viele Brote nehmen, daß wir eine solche Volksmenge sättigen könnten?«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 15, 34, 'Doch Jesus fragte sie: »Wie viele Brote habt ihr?« Sie antworteten: »Sieben und ein paar kleine Fische.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 15, 35, 'Da gebot er dem Volke, sich auf dem Erdboden zu lagern,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 15, 36, 'nahm dann die sieben Brote und die Fische, sprach den Lobpreis (Gottes), brach die Brote und gab sie seinen Jüngern, die Jünger aber teilten sie an die Volksmenge aus.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 15, 37, 'Und sie aßen alle und wurden satt; dann hob man die übriggebliebenen Brote (vom Boden) auf: sieben Körbe voll;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 15, 38, 'die Zahl derer aber, die gegessen hatten, betrug etwa viertausend Männer, ungerechnet die Frauen und Kinder.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 15, 39, 'Er ließ dann die Volksmenge gehen, stieg ins Boot und kam in die Gegend von Magadan.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 16, 1, 'Da traten die Pharisäer und Sadduzäer zu ihm heran, um ihn auf die Probe zu stellen, und sprachen den Wunsch gegen ihn aus, er möchte sie ein Wunderzeichen vom Himmel her sehen lassen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 16, 2, 'Er aber antwortete ihnen: »Am Abend sagt ihr: ›Es gibt schönes Wetter, denn der Himmel ist rot‹;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 16, 3, 'und frühmorgens: ›Heute gibt es Regenwetter, denn der Himmel ist rot und trübe.‹ Das Aussehen des Himmels versteht ihr zu beurteilen, die Wahrzeichen der Zeit aber nicht.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 16, 4, 'Ein böses und ehebrecherisches Geschlecht verlangt ein Zeichen; doch es wird ihm kein Zeichen gegeben werden als nur das Zeichen des (Propheten) Jona.« Mit diesen Worten ließ er sie stehen und ging weg.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 16, 5, 'Als die Jünger dann an das jenseitige Ufer des Sees kamen, hatten sie vergessen, Brote mitzunehmen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 16, 6, 'Da sagte Jesus zu ihnen: »Gebt acht und hütet euch vor dem Sauerteig der Pharisäer und Sadduzäer!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 16, 7, 'Sie erwogen nun im Gespräch untereinander: »(Das sagt er deshalb,) weil wir keine Brote mitgenommen haben.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 16, 8, 'Als Jesus das merkte, sagte er: »Ihr Kleingläubigen! Was macht ihr euch Gedanken darüber, daß ihr keine Brote (mitgenommen) habt?');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 16, 9, 'Besitzt ihr immer noch kein Verständnis, und denkt ihr nicht an die fünf Brote für die Fünftausend und wie viele Körbe voll ihr noch gesammelt habt?');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 16, 10, 'Auch nicht an die sieben Brote für die Viertausend und wie viele Körbchen voll ihr noch aufgelesen habt?');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 16, 11, 'Wie könnt ihr nur nicht begreifen, daß ich nicht von Broten zu euch geredet habe! Hütet euch aber vor dem Sauerteig der Pharisäer und Sadduzäer!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 16, 12, 'Nun verstanden sie, daß er nicht hatte sagen wollen, sie sollten sich vor dem bei Broten verwendeten Sauerteig hüten, sondern vor der Lehre der Pharisäer und Sadduzäer.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 16, 13, 'Als Jesus dann in die Gegend von Cäsarea Philippi gekommen war, fragte er seine Jünger: »Für wen halten die Leute den Menschensohn?«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 16, 14, 'Sie antworteten: »Die einen für Johannes den Täufer, andere für Elia, noch andere für Jeremia oder sonst einen von den Propheten.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 16, 15, 'Da fragte er sie weiter: »Ihr aber – für wen haltet ihr mich?«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 16, 16, 'Simon Petrus gab ihm zur Antwort: »Du bist Christus, der Sohn des lebendigen Gottes!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 16, 17, 'Da gab Jesus ihm zur Antwort: »Selig bist du (zu preisen), Simon, Sohn des Jona, denn nicht Fleisch und Blut haben dir das geoffenbart, sondern mein Vater droben im Himmel.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 16, 18, 'Und nun sage auch ich dir: Du bist Petrus (Fels, d.h. Felsenmann), und auf diesem Felsen will ich meine Gemeinde erbauen, und die Pforten des Totenreiches sollen sie nicht überwältigen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 16, 19, 'Ich will dir die Schlüssel des Himmelreiches geben, und was du auf der Erde bindest, das soll auch im Himmel gebunden sein, und was du auf der Erde lösest, das soll auch im Himmel gelöst sein!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 16, 20, 'Hierauf gab er den Jüngern die strenge Weisung, sie sollten es niemand sagen, daß er Christus sei.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 16, 21, 'Von da an begann Jesus seine Jünger darauf hinzuweisen, daß er nach Jerusalem gehen und von den Ältesten und Hohenpriestern und Schriftgelehrten vieles leiden müsse, und daß er getötet und am dritten Tage auferweckt werden müsse.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 16, 22, 'Da nahm Petrus ihn beiseite und begann auf ihn einzureden mit den Worten: »Herr, das verhüte Gott! Nimmermehr darf dir das widerfahren!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 16, 23, 'Er aber wandte sich um und sagte zu Petrus: »Mir aus den Augen, Satan! (Tritt) hinter mich! Ein Fallstrick bist du für mich, denn deine Gedanken sind nicht auf Gott, sondern auf die Menschen gerichtet.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 16, 24, 'Damals sagte Jesus zu seinen Jüngern: »Will jemand mein Nachfolger sein, so verleugne er sich selbst und nehme sein Kreuz auf sich: dann kann er mein Nachfolger sein.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 16, 25, 'Denn wer sein Leben retten will, der wird es verlieren; wer aber sein Leben um meinetwillen verliert, der wird es finden.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 16, 26, 'Denn was könnte es einem Menschen helfen, wenn er die ganze Welt gewönne, aber sein Leben einbüßte? Oder was könnte ein Mensch als Gegenwert für sein Leben geben?');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 16, 27, 'Denn der Menschensohn wird in der Herrlichkeit seines Vaters mit seinen Engeln kommen und dann einem jeden nach seinem Tun vergelten.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 16, 28, 'Wahrlich ich sage euch: Einige von denen, die hier stehen, werden den Tod nicht schmecken, bis sie den Menschensohn in seiner Königsherrschaft haben kommen sehen.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 17, 1, 'Sechs Tage später nahm Jesus den Petrus, Jakobus und dessen Bruder Johannes mit sich und führte sie abseits auf einen hohen Berg.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 17, 2, 'Da wurde er vor ihren Augen verwandelt: sein Antlitz leuchtete wie die Sonne, und seine Kleider wurden hellglänzend wie das Licht.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 17, 3, 'Und siehe, es erschienen ihnen Mose und Elia und besprachen sich mit ihm.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 17, 4, 'Da nahm Petrus das Wort und sagte zu Jesus: »Herr, hier sind wir gut aufgehoben! Willst du, so werde ich hier drei Hütten bauen, eine für dich, eine für Mose und eine für Elia.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 17, 5, 'Während er noch redete, überschattete sie plötzlich eine lichte Wolke, und eine Stimme erscholl aus der Wolke, die sprach: »Dies ist mein geliebter Sohn, an dem ich Wohlgefallen gefunden habe: höret auf ihn!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 17, 6, 'Als die Jünger das vernahmen, warfen sie sich auf ihr Angesicht nieder und gerieten in große Furcht;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 17, 7, 'doch Jesus trat herzu, faßte sie an und sagte: »Steht auf und fürchtet euch nicht!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 17, 8, 'Als sie aber ihre Augen aufschlugen, sahen sie niemand mehr als Jesus allein.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 17, 9, 'Als sie dann von dem Berge hinabstiegen, gebot ihnen Jesus: »Erzählt niemand etwas von der Erscheinung, die ihr gesehen habt, bis der Menschensohn von den Toten auferweckt worden ist.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 17, 10, 'Da fragten ihn die Jünger: »Wie können denn die Schriftgelehrten behaupten, Elia müsse zuerst kommen?«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 17, 11, 'Er gab ihnen zur Antwort: »Elia kommt allerdings und wird alles wieder in den rechten Stand bringen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 17, 12, 'Ich sage euch aber: Elia ist bereits gekommen, doch sie haben ihn nicht erkannt, sondern sind mit ihm verfahren, wie es ihnen beliebte. Ebenso wird auch der Menschensohn durch sie zu leiden haben.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 17, 13, 'Da verstanden die Jünger, daß er von Johannes dem Täufer zu ihnen gesprochen hatte.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 17, 14, 'Als sie dann zu der Volksmenge zurückgekommen waren, trat ein Mann an ihn heran, warf sich vor ihm auf die Knie nieder');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 17, 15, 'und sagte: »Herr, erbarme dich meines Sohnes! Er ist fallsüchtig und hat schwer zu leiden; denn oft fällt er ins Feuer und oft auch ins Wasser.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 17, 16, 'Ich habe ihn schon zu deinen Jüngern gebracht, doch sie haben ihn nicht heilen können.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 17, 17, 'Da antwortete Jesus: »O ihr ungläubige und verkehrte Art von Menschen! Wie lange soll ich noch bei euch sein, wie lange es noch mit euch aushalten? Bringt ihn mir hierher!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 17, 18, 'Jesus bedrohte alsdann den bösen Geist: da fuhr er von dem Knaben aus, so daß dieser von Stund an gesund war.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 17, 19, 'Hierauf traten die Jünger zu Jesus, als sie mit ihm allein waren, und fragten: »Warum haben wir den Geist nicht austreiben können?«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 17, 20, 'Er antwortete ihnen: »Wegen eures Kleinglaubens! Denn wahrlich ich sage euch: Wenn ihr Glauben wie ein Senfkorn habt und diesem Berge gebietet: ›Rücke von hier weg dorthin!‹, so wird er hinwegrücken, und nichts wird euch unmöglich sein.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 17, 21, '[Diese Art (von bösen Geistern) aber läßt sich nur durch Gebet und Fasten austreiben.]«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 17, 22, 'Während sie dann in Galiläa umherwanderten, sagte Jesus zu ihnen: »Der Menschensohn wird in die Hände der Menschen überliefert werden;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 17, 23, 'sie werden ihn töten, und am dritten Tage wird er auferweckt werden.« Da wurden sie tief betrübt.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 17, 24, 'Als sie dann nach Kapernaum zurückgekehrt waren, traten die Einsammler der Tempelsteuer an Petrus heran und fragten ihn: »Entrichtet euer Meister die Doppeldrachme nicht?«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 17, 25, 'Er antwortete: »Doch!« Als er dann ins Haus trat, kam ihm Jesus mit der Frage zuvor: »Was meinst du, Simon? Von wem lassen sich die Könige der Erde Zölle oder Steuern zahlen: von ihren Söhnen oder von Fremden?«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 17, 26, 'Als jener nun antwortete: »Von den Fremden«, sagte Jesus zu ihm: »So sind die Söhne steuerfrei.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 17, 27, 'Damit wir aber keinen Anstoß bei ihnen erregen, so geh an den See, wirf die Angel aus, und den ersten Fisch, den du heraufziehst, den nimm und öffne ihm das Maul; dann wirst du ein Silberstück finden; das nimm und gib es ihnen (als Abgabe) für mich und dich.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 18, 1, 'In jener Stunde traten die Jünger zu Jesus mit der Frage: »Wer ist denn der Größte im Himmelreich?«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 18, 2, 'Da rief er ein Kind herbei, stellte es mitten unter sie');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 18, 3, 'und sagte: »Wahrlich ich sage euch: Wenn ihr nicht umkehrt und wie die Kinder werdet, so werdet ihr nimmermehr ins Himmelreich eingehen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 18, 4, 'Wer sich demnach so erniedrigt wie dieses Kind hier, der ist der Größte im Himmelreich;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 18, 5, 'und wer ein einziges solches Kind auf meinen Namen hin aufnimmt, der nimmt mich auf.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 18, 6, '»Wer aber einen von diesen Kleinen, die an mich glauben, ärgert, für den wäre es das beste, daß ihm ein Mühlstein um den Hals gehängt und er ins Meer versenkt würde, wo es am tiefsten ist.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 18, 7, 'Wehe der Welt um der Ärgernisse willen! Wohl müssen die Verführungen kommen; doch wehe dem Menschen, durch den das Ärgernis kommt!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 18, 8, 'Wenn nun deine Hand oder dein Fuß dich ärgert, so haue sie ab und wirf sie von dir! Es ist besser für dich, verstümmelt oder lahm ins Leben einzugehen, als daß du beide Hände oder beide Füße hast und in das ewige Feuer geworfen wirst.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 18, 9, 'Und wenn dein Auge dich ärgert, so reiße es aus und wirf es von dir! Es ist besser für dich, einäugig ins Leben einzugehen, als daß du beide Augen hast und ins Feuer der Hölle geworfen wirst.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 18, 10, 'Sehet zu, daß ihr keinen von diesen Kleinen geringschätzt! Denn ich sage euch: Ihre Engel im Himmel schauen allezeit das Angesicht meines himmlischen Vaters.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 18, 11, '[Denn der Menschensohn ist gekommen, das Verlorene zu retten.]«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 18, 12, '»Was meint ihr wohl? Wenn jemand hundert Schafe besitzt und eins von ihnen sich verirrt: wird er da nicht die neunundneunzig auf den Bergen zurücklassen und hingehen, um das verirrte zu suchen?');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 18, 13, 'Und wenn es ihm gelingt, es zu finden, wahrlich ich sage euch: Er freut sich über dieses (eine) mehr als über die neunundneunzig, die sich nicht verirrt hatten.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 18, 14, 'Ebenso ist es auch der Wille eures himmlischen Vaters, daß keiner von diesen Kleinen verlorengehen soll.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 18, 15, '»Wenn dein Bruder sich verfehlt, so gehe hin und halte es ihm unter vier Augen vor. Hört er auf dich, so hast du deinen Bruder gewonnen;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 18, 16, 'hört er aber nicht, so nimm noch einen oder zwei (Brüder) mit dir, damit jede Sache auf Grund der Aussagen von zwei oder drei Zeugen festgestellt wird.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 18, 17, 'Will er auf diese (Brüder) nicht hören, so teile es der Gemeinde mit; will er auch auf die Gemeinde nicht hören, so gelte er dir wie ein Heide und ein Zöllner. –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 18, 18, 'Wahrlich ich sage euch: Alles, was ihr auf der Erde bindet, wird auch im Himmel gebunden sein; und was ihr auf der Erde löst, wird auch im Himmel gelöst sein. –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 18, 19, 'Weiter sage ich euch: Wenn zwei von euch auf Erden eins werden, um irgend etwas zu bitten, so wird es ihnen von meinem himmlischen Vater zuteil werden;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 18, 20, 'denn wo zwei oder drei auf meinen Namen hin versammelt sind, da bin ich mitten unter ihnen.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 18, 21, 'Hierauf trat Petrus an ihn heran und fragte ihn: »Herr, wie oft muß ich meinem Bruder vergeben, wenn er sich gegen mich vergeht? Bis zu siebenmal?«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 18, 22, 'Da antwortete ihm Jesus: »Ich sage dir: Nicht bis zu siebenmal, sondern bis siebenzigmal siebenmal.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 18, 23, 'Darum ist das Himmelreich einem Könige vergleichbar, der mit seinen Knechten abrechnen wollte.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 18, 24, 'Als er nun mit der Abrechnung begann, wurde ihm einer vorgeführt, der ihm zehntausend Talente schuldig war.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 18, 25, 'Weil er nun diese Schuld nicht bezahlen konnte, befahl der Herr, man solle ihn samt Weib und Kindern und seinem gesamten Besitz verkaufen und so Ersatz schaffen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 18, 26, 'Da warf sich der Knecht vor ihm zur Erde nieder und bat ihn mit den Worten: ›Habe Geduld mit mir: ich will dir alles bezahlen.‹');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 18, 27, 'Da hatte der Herr Erbarmen mit diesem Knecht; er gab ihn frei, und die Schuld erließ er ihm auch.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 18, 28, 'Als aber dieser Knecht (aus dem Hause des Herrn) hinausgegangen war, traf er einen seiner Mitknechte, der ihm hundert Denare schuldig war; den ergriff er, packte ihn an der Kehle und sagte zu ihm: ›Bezahle, wenn du etwas schuldig bist!‹');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 18, 29, 'Da warf sich sein Mitknecht vor ihm nieder und bat ihn mit den Worten: ›Habe Geduld mit mir: ich will dir’s bezahlen!‹');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 18, 30, 'Er wollte aber nicht, sondern ging hin und ließ ihn ins Gefängnis werfen, bis er die Schuld bezahlt hätte.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 18, 31, 'Als nun seine Mitknechte sahen, was da vorgegangen war, wurden sie sehr ungehalten; sie gingen hin und berichteten ihrem Herrn den ganzen Vorfall.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 18, 32, 'Da ließ sein Herr ihn vor sich rufen und sagte zu ihm: ›Du böser Knecht! Jene ganze Schuld habe ich dir erlassen, weil du mich darum batest;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 18, 33, 'hättest du da nicht auch Erbarmen mit deinem Mitknecht haben müssen, wie ich Erbarmen mit dir gehabt habe?‹');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 18, 34, 'Und voller Zorn übergab sein Herr ihn den Folterknechten, bis er ihm seine ganze Schuld bezahlt hätte.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 18, 35, 'Ebenso wird auch mein himmlischer Vater mit euch verfahren, wenn ihr nicht ein jeder seinem Bruder von Herzen vergebt.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 19, 1, 'Als Jesus nun diese Reden beendet hatte, brach er aus Galiläa auf und kam in das Gebiet von Judäa auf der anderen Seite des Jordans;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 19, 2, 'eine große Volksmenge begleitete ihn, und er heilte sie dort.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 19, 3, 'Da traten Pharisäer an ihn heran, die ihn auf die Probe stellen wollten, und legten ihm die Frage vor: »Darf man seine Frau aus jedem beliebigen Grunde entlassen?«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 19, 4, 'Er gab ihnen zur Antwort: »Habt ihr nicht gelesen, daß der Schöpfer die Menschen von Anfang an als Mann und Weib geschaffen');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 19, 5, 'und gesagt hat: ›Darum wird ein Mann seinen Vater und seine Mutter verlassen und an seinem Weibe hangen, und die beiden werden ein Fleisch sein‹?');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 19, 6, 'Also sind sie nicht mehr zwei, sondern ein Fleisch. Was somit Gott zusammengefügt hat, das soll der Mensch nicht scheiden.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 19, 7, 'Sie entgegneten ihm: »Warum hat denn Mose geboten, der Frau einen Scheidebrief auszustellen und sie dann zu entlassen?«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 19, 8, 'Er antwortete ihnen: »Mose hat euch (nur) mit Rücksicht auf eure Herzenshärte gestattet, eure Frauen zu entlassen; aber von Anfang an ist es nicht so gewesen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 19, 9, 'Ich sage euch aber: Wer sich von seiner Frau scheidet – außer wegen Unzucht – und eine andere heiratet, der begeht Ehebruch [und wer eine Entlassene heiratet, begeht auch Ehebruch].«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 19, 10, 'Da sagten die Jünger zu ihm: »Wenn es mit dem Rechtsverhältnis des Mannes gegenüber seiner Frau so steht, dann ist es nicht geraten, sich zu verheiraten.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 19, 11, 'Er aber antwortete ihnen: »Nicht alle fassen dieses Wort, sondern nur die, denen es gegeben ist.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 19, 12, 'Es gibt nämlich zur Ehe Untüchtige, die vom Mutterleibe her so geboren worden sind; und es gibt zur Ehe Untüchtige, die von Menschenhand zur Ehe untüchtig gemacht worden sind; und es gibt zur Ehe Untüchtige, die sich selbst um des Himmelreichs willen untüchtig gemacht haben. Wer es zu fassen vermag, der fasse es!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 19, 13, 'Hierauf brachte man kleine Kinder zu ihm, damit er ihnen die Hände auflegen und (für sie) beten möchte; die Jünger aber verwiesen es in barscher Weise (denen, die sie brachten).');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 19, 14, 'Doch Jesus sagte: »Laßt die Kinder (in Frieden) und hindert sie nicht, zu mir zu kommen! Denn für ihresgleichen ist das Himmelreich bestimmt.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 19, 15, 'Dann legte er ihnen die Hände auf und wanderte von dort weiter.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 19, 16, 'Da trat einer an ihn heran und fragte ihn: »Meister, was muß ich Gutes tun, um ewiges Leben zu erlangen?«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 19, 17, 'Er antwortete ihm: »Was fragst du mich über das Gute? (Nur) einer ist der Gute. Willst du aber ins Leben eingehen, so halte die Gebote.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 19, 18, '»Welche?« entgegnete er. Jesus antwortete: »Diese: ›Du sollst nicht töten, nicht ehebrechen, nicht stehlen, nicht falsches Zeugnis ablegen,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 19, 19, 'ehre deinen Vater und deine Mutter‹ und ›du sollst deinen Nächsten lieben wie dich selbst.‹«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 19, 20, 'Der Jüngling erwiderte ihm: »Dies alles habe ich beobachtet: was fehlt mir noch?«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 19, 21, 'Jesus antwortete ihm: »Willst du vollkommen sein, so gehe hin, verkaufe dein Hab und Gut und gib (den Erlös) den Armen, so wirst du einen Schatz im Himmel haben; dann komm und folge mir nach!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 19, 22, 'Als der Jüngling das Wort gehört hatte, ging er betrübt weg; denn er besaß ein großes Vermögen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 19, 23, 'Jesus aber sagte zu seinen Jüngern: »Wahrlich ich sage euch: Für einen Reichen wird es schwer sein, ins Himmelreich einzugehen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 19, 24, 'Nochmals sage ich euch: Es ist leichter, daß ein Kamel durch ein Nadelöhr hindurchgeht, als daß ein Reicher in das Reich Gottes eingeht.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 19, 25, 'Als die Jünger das hörten, wurden sie ganz bestürzt und sagten: »Ja, wer kann dann gerettet werden?«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 19, 26, 'Jesus aber blickte sie an und sagte zu ihnen: »Bei den Menschen ist dies unmöglich, aber bei Gott ist alles möglich.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 19, 27, 'Hierauf nahm Petrus das Wort und sagte zu ihm: »Siehe, wir haben alles verlassen und sind dir nachgefolgt: welcher Lohn wird uns also dafür zuteil werden?«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 19, 28, 'Jesus antwortete ihnen: »Wahrlich ich sage euch: Ihr, die ihr mir nachgefolgt seid, werdet bei der Wiedergeburt, wenn der Menschensohn auf dem Thron seiner Herrlichkeit sitzt, gleichfalls auf zwölf Thronen sitzen und die zwölf Stämme Israels richten.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 19, 29, 'Und jeder, der um meines Namens willen Brüder oder Schwestern, Vater oder Mutter, Weib oder Kinder, Äcker oder Häuser verlassen hat, wird vielmal Wertvolleres empfangen und ewiges Leben erben.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 19, 30, 'Viele Erste aber werden Letzte sein und viele Letzte die Ersten.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 20, 1, '»Denn das Himmelreich ist einem menschlichen Hausherrn gleich, der frühmorgens ausging, um Arbeiter für seinen Weinberg einzustellen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 20, 2, 'Nachdem er nun mit den Arbeitern einen Tagelohn von einem Denar vereinbart hatte, schickte er sie in seinen Weinberg.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 20, 3, 'Als er dann um die dritte Tagesstunde wieder ausging, sah er andere auf dem Marktplatz unbeschäftigt stehen');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 20, 4, 'und sagte zu ihnen: ›Geht auch ihr in meinen Weinberg, ich will euch geben, was recht ist‹;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 20, 5, 'und sie gingen hin. Wiederum ging er um die sechste und um die neunte Stunde aus und machte es ebenso;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 20, 6, 'und als er um die elfte Stunde wieder ausging, fand er noch andere dastehen und sagte zu ihnen: ›Was steht ihr hier den ganzen Tag müßig?‹');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 20, 7, 'Sie antworteten ihm: ›Niemand hat uns in Arbeit genommen.‹ Da sagte er zu ihnen: ›Geht auch ihr noch in den Weinberg!‹');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 20, 8, 'Als es dann Abend geworden war, sagte der Herr des Weinbergs zu seinem Verwalter: ›Rufe die Arbeiter und zahle ihnen den Lohn aus! Fange bei den letzten an (und weiter so) bis zu den ersten!‹');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 20, 9, 'Als nun die um die elfte Stunde Eingestellten kamen, erhielten sie jeder einen Denar.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 20, 10, 'Als dann die Ersten (an die Reihe) kamen, dachten sie, sie würden mehr erhalten; doch sie erhielten gleichfalls jeder nur einen Denar.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 20, 11, 'Als sie ihn empfangen hatten, murrten sie gegen den Hausherrn');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 20, 12, 'und sagten: ›Diese Letzten haben nur eine einzige Stunde gearbeitet, und du hast sie uns gleichgestellt, die wir des (ganzen) Tages Last und Hitze getragen haben!‹');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 20, 13, 'Er aber entgegnete einem von ihnen: ›Freund, ich tue dir nicht unrecht; bist du nicht um einen Denar mit mir eins geworden?');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 20, 14, 'Nimm dein Geld und gehe! Es gefällt mir nun einmal, diesem Letzten ebensoviel zu geben wie dir.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 20, 15, 'Habe ich etwa nicht das Recht, mit dem, was mein ist, zu machen, was ich will? Oder siehst du neidisch dazu, daß ich wohlwollend bin?‹');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 20, 16, 'Ebenso werden die Letzten Erste und die Ersten Letzte sein. [Denn viele sind berufen, aber wenige auserwählt.]«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 20, 17, 'Als nun Jesus vorhatte, nach Jerusalem hinaufzuziehen, nahm er die zwölf Jünger (vom Volk) gesondert zu sich und sagte unterwegs zu ihnen:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 20, 18, '»Seht, wir ziehen jetzt nach Jerusalem hinauf: dort wird der Menschensohn den Hohenpriestern und Schriftgelehrten überantwortet werden; die werden ihn zum Tode verurteilen');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 20, 19, 'und ihn den Heiden zur Verspottung, zur Geißelung und zur Kreuzigung überliefern; und am dritten Tage wird er auferweckt werden.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 20, 20, 'Damals trat die Mutter der Söhne des Zebedäus mit ihren (beiden) Söhnen zu ihm, fiel vor ihm nieder und wollte ihn um etwas bitten.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 20, 21, 'Er fragte sie: »Was wünschest du?« Sie antwortete ihm: »Bestimme, daß diese meine beiden Söhne dereinst in deinem Königreich einer zu deiner Rechten und einer zu deiner Linken sitzen sollen.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 20, 22, 'Da antwortete Jesus: »Ihr wißt nicht, um was ihr bittet. Könnt ihr den Kelch trinken, den ich trinken werde?« Sie antworteten ihm: »Ja, wir können es.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 20, 23, 'Er erwiderte ihnen: »Meinen Kelch werdet ihr zwar trinken (müssen), aber die Plätze zu meiner Rechten und zu meiner Linken habe nicht ich zu verleihen, sondern sie werden denen zuteil, für die sie von meinem Vater bestimmt sind.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 20, 24, 'Als die (übrigen) zehn Jünger das hörten, wurden sie über die beiden Brüder unwillig;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 20, 25, 'Jesus aber rief sie zu sich und sagte: »Ihr wißt, daß die weltlichen Herrscher sich als Herren gegen ihre Völker benehmen und daß ihre Großen sie vergewaltigen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 20, 26, 'Bei euch aber darf es nicht so sein; wer unter euch als Großer dastehen möchte, der muß euer Diener sein,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 20, 27, 'und wer bei euch der Erste sein möchte, der muß euer Knecht sein,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 20, 28, 'wie ja auch der Menschensohn nicht gekommen ist, sich bedienen zu lassen, sondern zu dienen und sein Leben als Lösegeld hinzugeben für viele.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 20, 29, 'Als sie dann aus Jericho hinauszogen, folgte ihm eine große Volksmenge nach.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 20, 30, 'Da saßen dort zwei Blinde am Wege; als diese hörten, daß Jesus vorüberziehe, riefen sie laut: »Herr, erbarme dich unser, Sohn Davids!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 20, 31, 'Die Volksmenge rief ihnen drohend zu, sie sollten still sein; sie aber schrien nur noch lauter: »Herr, erbarme dich unser, Sohn Davids!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 20, 32, 'Da blieb Jesus stehen, rief sie herbei und fragte sie: »Was wünscht ihr von mir?«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 20, 33, 'Sie antworteten ihm: »Herr, daß unsere Augen aufgetan werden!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 20, 34, 'Da fühlte Jesus Mitleid mit ihnen; er berührte ihre Augen, und sogleich konnten sie sehen und schlossen sich ihm an.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 21, 1, 'Als sie sich dann Jerusalem näherten und nach Bethphage an den Ölberg gekommen waren, da sandte Jesus zwei von seinen Jüngern ab');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 21, 2, 'mit der Weisung: »Geht in das Dorf, das vor euch liegt! Ihr werdet dort sogleich (am Eingang) eine Eselin angebunden finden und ein Füllen bei ihr; bindet sie los und bringt sie mir her!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 21, 3, 'Und wenn euch jemand etwas sagen sollte, so antwortet ihm: ›Der Herr hat sie nötig, wird sie aber sofort zurückschicken.‹«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 21, 4, 'Dies ist aber geschehen, damit das Wort des Propheten erfüllt werde, das da lautet:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 21, 5, '»Sagt der Tochter Zion: Siehe, dein König kommt zu dir sanftmütig und auf einem Esel reitend, und zwar auf einem Füllen, dem Jungen des Lasttiers.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 21, 6, 'Als nun die Jünger hingegangen waren und den Auftrag Jesu ausgerichtet hatten,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 21, 7, 'führten sie die Eselin mit dem Füllen herbei, legten ihre Mäntel auf sie, und er setzte sich darauf.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 21, 8, 'Die überaus zahlreiche Volksmenge aber breitete ihre Mäntel auf den Weg aus, andere hieben Zweige von den Bäumen ab und streuten sie auf den Weg;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 21, 9, 'und die Scharen, die im Zuge vor ihm her gingen und die, welche ihm nachfolgten, riefen laut: »Hosianna dem Sohne Davids! Gepriesen sei, der da kommt im Namen des Herrn! Hosianna in den Himmelshöhen!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 21, 10, 'Als er dann in Jerusalem eingezogen war, geriet die ganze Stadt in Bewegung, und zwar fragte man: »Wer ist dieser?«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 21, 11, 'Da sagte die Volksmenge: »Dies ist der Prophet Jesus aus Nazareth in Galiläa!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 21, 12, 'Jesus ging dann in den Tempel Gottes, trieb alle hinaus, die im Tempel verkauften und kauften, warf die Tische der Geldwechsler und die Sitze der Taubenverkäufer um');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 21, 13, 'und sagte zu ihnen: »Es steht geschrieben: ›Mein Haus soll ein Bethaus heißen!‹ Ihr aber macht es zu einer ›Räuberhöhle‹!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 21, 14, 'Es kamen auch Blinde und Lahme im Tempel zu ihm, und er heilte sie.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 21, 15, 'Als aber die Hohenpriester und Schriftgelehrten die Wunder sahen, die er tat, und (hörten) wie die Kinder im Tempel laut riefen: »Hosianna dem Sohne Davids!«, wurden sie unwillig');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 21, 16, 'und sagten zu ihm: »Hörst du nicht, was diese hier rufen?« Da antwortete Jesus ihnen: »Jawohl! Habt ihr noch niemals (das Schriftwort) gelesen: ›Aus dem Munde von Unmündigen und Säuglingen hast du (dir) Lobpreis bereitet‹?«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 21, 17, 'Mit diesen Worten ließ er sie stehen, ging aus der Stadt hinaus nach Bethanien und blieb über Nacht dort.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 21, 18, 'Als er dann frühmorgens in die Stadt zurückkehrte, hungerte ihn,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 21, 19, 'und als er einen einzelnen Feigenbaum am Wege stehen sah, ging er zu ihm hin, fand aber nichts anderes an ihm als Blätter. Da sagte er zu ihm: »Nie mehr soll noch Frucht von dir kommen in Ewigkeit!«, und der Feigenbaum verdorrte sofort.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 21, 20, 'Als die Jünger das sahen, verwunderten sie sich und sagten: »Wie kommt es, daß der Feigenbaum sofort verdorrt ist?«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 21, 21, 'Da antwortete ihnen Jesus: »Wahrlich ich sage euch: Wenn ihr Glauben habt und keinen Zweifel hegt, so werdet ihr nicht nur das, was hier mit dem Feigenbaume geschehen ist, tun können, sondern auch, wenn ihr zu dem Berge hier sagtet: ›Hebe dich empor und stürze dich ins Meer!‹, so würde es geschehen;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 21, 22, 'und alles, um was ihr im Gebet bittet, werdet ihr empfangen, wenn ihr Glauben habt.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 21, 23, 'Als er dann in den Tempel gekommen war, traten die Hohenpriester und die Ältesten des Volkes zu ihm, während er lehrte, und fragten ihn: »Auf Grund welcher Vollmacht trittst du in dieser Weise hier auf, und wer hat dir die Vollmacht dazu gegeben?«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 21, 24, 'Jesus gab ihnen zur Antwort: »Auch ich will euch eine einzige Frage vorlegen; wenn ihr sie mir beantwortet, so will auch ich euch sagen, auf Grund welcher Vollmacht ich hier so auftrete:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 21, 25, 'Woher stammte die Taufe des Johannes? Vom Himmel oder von den Menschen?« Da überlegten sie bei sich folgendermaßen:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 21, 26, '»Sagen wir: ›Vom Himmel‹, so wird er uns vorhalten: ›Warum habt ihr ihm dann keinen Glauben geschenkt?‹ Sagen wir aber: ›Von den Menschen‹, so haben wir das Volk zu fürchten; denn alle halten Johannes für einen Propheten.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 21, 27, 'So gaben sie denn Jesus zur Antwort: »Wir wissen es nicht.« Da antwortete auch er ihnen: »Dann sage auch ich euch nicht, auf Grund welcher Vollmacht ich hier so auftrete.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 21, 28, '»Was meint ihr aber (über folgendes)? Ein Mann hatte zwei Söhne. Er ging nun zu dem ersten und sagte: ›Mein Sohn, gehe hin und arbeite heute im Weinberge.‹');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 21, 29, 'Der antwortete: ›Ja, Herr‹, ging aber nicht hin.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 21, 30, 'Dann ging er zu dem zweiten und sagte zu ihm das gleiche. Der gab zur Antwort: ›Ich will nicht!‹ Später aber besann er sich eines Besseren und ging hin.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 21, 31, 'Wer von den beiden hat nun den Willen des Vaters getan?« Sie antworteten: »Der zweite.« Da sagte Jesus zu ihnen: »Wahrlich ich sage euch: Die Zöllner und die Dirnen kommen vor euch in das Reich Gottes.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 21, 32, 'Denn Johannes ist mit der Lehre von der Gerechtigkeit zu euch gekommen, und ihr habt ihm nicht geglaubt, während die Zöllner und die Dirnen ihm Glauben geschenkt haben. Ihr dagegen seid, obgleich ihr das sahet, auch hinterher nicht in euch gegangen, daß ihr ihm geglaubt hättet.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 21, 33, '»Vernehmt noch ein anderes Gleichnis: Es war ein Hausherr, der legte einen Weinberg an, umgab ihn mit einem Zaun, grub in ihm eine Kelter, baute einen Wachtturm, verpachtete ihn an Weingärtner und ging dann außer Landes.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 21, 34, 'Als dann die Zeit der Früchte kam, sandte er seine Knechte zu den Weingärtnern, damit sie die ihm zukommenden Früchte in Empfang nähmen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 21, 35, 'Da ergriffen die Weingärtner seine Knechte: den einen mißhandelten sie, den andern erschlugen sie, den dritten steinigten sie.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 21, 36, 'Wiederum sandte er andere Knechte in noch größerer Zahl als die ersten, doch sie machten es mit ihnen ebenso.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 21, 37, 'Zuletzt sandte er seinen Sohn zu ihnen, weil er dachte: ›Sie werden sich doch vor meinem Sohne scheuen!‹');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 21, 38, 'Als aber die Weingärtner den Sohn sahen, sagten sie unter sich: ›Dieser ist der Erbe: kommt, wir wollen ihn töten, dann können wir sein Erbgut in Besitz nehmen!‹');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 21, 39, 'So ergriffen sie ihn denn, stießen ihn zum Weinberg hinaus und schlugen ihn tot.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 21, 40, 'Wenn nun der Herr des Weinbergs kommt, was wird er mit diesen Weingärtnern machen?«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 21, 41, 'Sie antworteten ihm: »Er wird die Elenden elendiglich umbringen und den Weinberg an andere Weingärtner verpachten, die ihm die Früchte zu rechter Zeit abliefern werden.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 21, 42, 'Jesus fuhr fort: »Habt ihr noch niemals in den (heiligen) Schriften das Wort gelesen: ›Der Stein, den die Bauleute verworfen hatten, der ist zum Eckstein geworden; durch den Herrn ist er das geworden, und ein Wunder ist er in unsern Augen‹?');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 21, 43, 'Deshalb sage ich euch: Das Reich Gottes wird euch genommen und einem Volke gegeben werden, das dessen Früchte bringt.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 21, 44, '[Und wer auf diesen Stein fällt, wird zerschmettert werden; auf wen aber (der Stein) fällt, den wird er zermalmen.]«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 21, 45, 'Als die Hohenpriester und Pharisäer seine Gleichnisse hörten, merkten sie, daß er von ihnen redete;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 21, 46, 'darum hätten sie ihn am liebsten festgenommen, fürchteten sich aber vor der Volksmenge, weil die ihn für einen Propheten hielt.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 22, 1, 'Und Jesus hob an und redete noch einmal in Gleichnissen zu ihnen folgendermaßen:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 22, 2, '»Das Himmelreich ist einem König vergleichbar, der seinem Sohne die Hochzeit ausrichten wollte.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 22, 3, 'Er sandte also seine Knechte aus, um die geladenen Gäste zum Hochzeitsmahl zu bitten; doch sie wollten nicht kommen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 22, 4, 'Nochmals sandte er andere Knechte aus, denen er die Weisung gab: ›Sagt den Geladenen: Seht, mein Festmahl habe ich zugerichtet; meine Ochsen und das Mastvieh sind geschlachtet, und alles ist bereit: kommt zum Hochzeitsmahl!‹');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 22, 5, 'Die aber beachteten es nicht und gingen hin, der eine auf seinen Acker, der andere an sein Handelsgeschäft;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 22, 6, 'die übrigen ergriffen seine Knechte, mißhandelten und töteten sie.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 22, 7, 'Da wurde der König zornig; er entsandte seine Heere, ließ jene Mörder umbringen und ihre Stadt verbrennen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 22, 8, 'Hierauf sagte er zu seinen Knechten: ›Das Hochzeitsmahl ist zwar bereitet, aber die Geladenen waren unwürdig (daran teilzunehmen).');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 22, 9, 'Geht darum an die Straßenecken hinaus und ladet alle zum Hochzeitsmahl ein, soviele ihr antrefft!‹');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 22, 10, 'So gingen denn jene Knechte auf die Straßen hinaus und brachten alle, die sie trafen, zusammen, Böse wie Gute, und der Hochzeitssaal füllte sich mit Gästen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 22, 11, 'Als aber der König hineinging, um sich die Gäste anzusehen, bemerkte er dort einen Mann, der kein Hochzeitsgewand angelegt hatte.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 22, 12, 'Da sagte er zu ihm: ›Freund, wie hast du hierher kommen können, ohne ein Hochzeitsgewand anzuhaben?‹ Jener verstummte.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 22, 13, 'Hierauf befahl der König seinen Dienern: ›Faßt ihn an Händen und Füßen und werft ihn hinaus in die Finsternis draußen! Dort wird lautes Weinen und Zähneknirschen sein.‹');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 22, 14, 'Denn viele sind berufen, aber wenige auserwählt.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 22, 15, 'Hierauf gingen die Pharisäer hin und stellten eine Beratung an, wie sie ihn durch einen Ausspruch (wie in einer Schlinge) fangen könnten.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 22, 16, 'Sie sandten also ihre Jünger nebst den Anhängern des Herodes zu ihm, die mußten sagen: »Meister, wir wissen, daß du wahrhaftig bist und den Weg Gottes mit Wahrhaftigkeit lehrst; auch nimmst du auf niemand Rücksicht, denn du siehst die Person der Menschen nicht an.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 22, 17, 'So sage uns denn deine Meinung: ›Ist es recht, daß man dem Kaiser Steuer entrichtet, oder nicht?‹«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 22, 18, 'Da Jesus nun ihre böse Absicht durchschaute, antwortete er: »Was versucht ihr mich, ihr Heuchler?');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 22, 19, 'Zeigt mir die Steuermünze!« Als sie ihm nun einen Denar gereicht hatten,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 22, 20, 'fragte er sie: »Wessen Bild und Aufschrift ist das hier?«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 22, 21, 'Sie antworteten: »Des Kaisers.« Da sagte er zu ihnen: »So gebt dem Kaiser, was dem Kaiser zusteht, und Gott, was Gott zusteht!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 22, 22, 'Als sie das hörten, verwunderten sie sich, ließen von ihm ab und entfernten sich.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 22, 23, 'An demselben Tage traten Sadduzäer an ihn heran, die da behaupten, es gebe keine Auferstehung, und fragten ihn:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 22, 24, '»Meister, Mose hat geboten: ›Wenn jemand kinderlos stirbt, so soll sein Bruder (als Schwager) dessen Frau heiraten und für seinen Bruder das Geschlecht fortpflanzen.‹');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 22, 25, 'Nun lebten sieben Brüder bei uns; der erste, der sich verheiratet hatte, starb und hinterließ, weil er keine Kinder hatte, seine Frau seinem Bruder;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 22, 26, 'ebenso auch der zweite und der dritte, schließlich alle sieben;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 22, 27, 'zuletzt nach allen starb auch die Frau.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 22, 28, 'Wem von den Sieben wird sie nun in der Auferstehung als Frau angehören? Alle haben sie ja zur Frau gehabt.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 22, 29, 'Jesus antwortete ihnen: »Ihr seid im Irrtum, weil ihr weder die (heiligen) Schriften noch die Kraft Gottes kennt.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 22, 30, 'Denn in der Auferstehung heiraten sie weder, noch werden sie verheiratet, sondern sie sind wie Engel im Himmel.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 22, 31, 'Was aber die Auferstehung der Toten betrifft: habt ihr nicht gelesen, was euch darüber von Gott gesagt worden ist, wenn er spricht:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 22, 32, '›Ich bin der Gott Abrahams, der Gott Isaaks und der Gott Jakobs‹? Gott ist doch nicht ein Gott von Toten, sondern von Lebenden.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 22, 33, 'Als die Volksmenge das hörte, staunte sie über seine Lehre.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 22, 34, 'Als aber die Pharisäer vernahmen, daß er die Sadduzäer zum Schweigen gebracht hatte, versammelten sie sich (um ihn);');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 22, 35, 'und einer von ihnen, ein Gesetzeslehrer, versuchte ihn mit der Frage:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 22, 36, '»Meister, was ist ein Hauptgebot im Gesetz?«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 22, 37, 'Er antwortete ihm: »Du sollst den Herrn, deinen Gott, lieben mit deinem ganzen Herzen, mit deiner ganzen Seele und mit deinem ganzen Denken.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 22, 38, 'Dies ist das Hauptgebot, das obenan steht.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 22, 39, 'Ein zweites aber steht ihm gleich: ›Du sollst deinen Nächsten lieben wie dich selbst!‹');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 22, 40, 'In diesen beiden Geboten hängt das ganze Gesetz und die Propheten.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 22, 41, 'Da aber die Pharisäer beisammen waren, legte Jesus ihnen die Frage vor:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 22, 42, '»Wie denkt ihr über Christus? Wessen Sohn ist er?« Sie antworteten ihm: »Er ist Davids Sohn.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 22, 43, 'Da erwiderte Jesus ihnen: »Wie kann ihn dann aber David im Geist ›Herr‹ nennen, indem er sagt:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 22, 44, '›Der Herr hat zu meinem Herrn gesagt: Setze dich zu meiner Rechten, bis ich deine Feinde hinlege zum Schemel deiner Füße‹?');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 22, 45, 'Wenn David ihn also ›Herr‹ nennt, wie kann er da sein Sohn sein?«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 22, 46, 'Und niemand konnte ihm hierauf eine Antwort geben; auch wagte von diesem Tage an niemand mehr, ihm eine Frage vorzulegen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 23, 1, 'Damals richtete Jesus an das Volk und an seine Jünger folgende Worte:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 23, 2, '»Auf den Lehrstuhl Moses haben sich die Schriftgelehrten und die Pharisäer gesetzt.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 23, 3, 'Alles nun, was sie euch sagen, das tut und befolgt, aber nach ihren Werken richtet euch nicht; denn sie sagen es nur, tun es aber nicht.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 23, 4, 'Sie binden schwere Lasten zusammen und legen sie den Menschen auf die Schultern, sie selbst aber wollen sie mit keinem Finger anrühren.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 23, 5, 'Alle ihre Werke tun sie in der Absicht, von den Leuten gesehen zu werden; denn sie machen ihre Gebetsriemen breit und ihre Mantelquasten lang;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 23, 6, 'sie lieben den ersten Platz bei den Gastmählern und die Ehrensitze in den Synagogen;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 23, 7, 'sie wollen auf den Märkten gegrüßt sein und lassen sich von den Leuten gern ›Rabbi‹ nennen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 23, 8, 'Ihr aber sollt euch nicht ›Meister‹ nennen lassen; denn einer ist euer Meister, ihr alle aber seid Brüder.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 23, 9, 'Und niemand auf Erden sollt ihr euren ›Vater‹ nennen; denn einer ist euer Vater, der im Himmel.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 23, 10, 'Auch ›Lehrer‹ sollt ihr euch nicht nennen lassen; denn einer ist euer Lehrer, nämlich Christus.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 23, 11, 'Der Größte unter euch soll euer Diener sein.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 23, 12, 'Wer sich aber selbst erhöht, wird erniedrigt werden, und wer sich selbst erniedrigt, wird erhöht werden.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 23, 13, '»Wehe euch, Schriftgelehrte und Pharisäer, ihr Heuchler! Denn ihr verschließt das Himmelreich vor den Menschen. Ihr selbst geht ja nicht hinein, laßt aber auch die nicht hinein, welche hineingehen wollen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 23, 14, '[Wehe euch, Schriftgelehrte und Pharisäer, ihr Heuchler! Denn ihr bringt die Häuser der Witwen gierig an euch und verrichtet zum Schein lange Gebete. Darum werdet ihr ein um so strengeres Gericht erfahren.]');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 23, 15, 'Wehe euch, Schriftgelehrte und Pharisäer, ihr Heuchler! Denn ihr durchreist Land und Meer, um einen einzigen Glaubensgenossen zu gewinnen; und wenn er es geworden ist, macht ihr aus ihm ein Kind der Hölle, das doppelt so schlimm ist als ihr selbst.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 23, 16, 'Wehe euch, ihr blinden Führer, die ihr sagt: ›Wenn einer beim Tempel schwört, so hat das nichts zu bedeuten; wer aber beim Gold des Tempels schwört, der ist gebunden.‹');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 23, 17, 'Ihr Toren und Blinde! Was steht denn höher: das Gold oder der Tempel, der das Gold erst heilig gemacht hat?');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 23, 18, 'Ferner (sagt ihr): ›Wenn einer beim Altar schwört, so hat das nichts zu bedeuten; wer aber bei der Opfergabe schwört, die auf dem Altar liegt, der ist gebunden.‹');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 23, 19, 'Ihr Blinden! Was steht denn höher, die Opfergabe oder der Altar, der die Gabe erst heilig macht?');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 23, 20, 'Wer also beim Altar schwört, der schwört bei ihm und bei allem, was auf ihm liegt;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 23, 21, 'und wer beim Tempel schwört, der schwört bei ihm und bei dem, der in ihm wohnt;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 23, 22, 'und wer beim Himmel schwört, der schwört bei Gottes Thron und bei dem, der auf ihm sitzt.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 23, 23, 'Wehe euch, Schriftgelehrte und Pharisäer, ihr Heuchler! Ihr entrichtet den Zehnten von Minze, von Anis und Kümmel, laßt aber das Schwierigere im Gesetz außer acht, nämlich das Gericht, die Barmherzigkeit und die Treue. Diese sollte man üben und jenes nicht außer acht lassen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 23, 24, 'Ihr blinden Führer, die ihr die Mücke seihet, aber das Kamel hinuntertrinkt!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 23, 25, 'Wehe euch, Schriftgelehrte und Pharisäer, ihr Heuchler! Denn ihr haltet die Außenseite des Bechers und der Schüssel rein, inwendig aber sind sie gefüllt mit Raub und Unmäßigkeit.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 23, 26, 'Du blinder Pharisäer! Mache zuerst das rein, was den Inhalt des Bechers bildet, dann wird auch seine Außenseite rein werden (können).');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 23, 27, 'Wehe euch, Schriftgelehrte und Pharisäer, ihr Heuchler! Denn ihr gleicht frischgetünchten Gräbern, die von außen schön aussehen, im Innern aber voll von Totengebeinen und lauter Verwesung sind.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 23, 28, 'Ebenso zeigt auch ihr euch den Menschen von außen gerecht, inwendig aber seid ihr voll von Heuchelei und Gesetzlosigkeit.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 23, 29, 'Wehe euch, Schriftgelehrte und Pharisäer, ihr Heuchler! Denn ihr baut die Grabstätten der Propheten aus und schmückt die Grabdenkmäler der Gerechten');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 23, 30, 'und sagt: ›Hätten wir zur Zeit unserer Väter gelebt, wir hätten uns nicht mit ihnen am Blut der Propheten schuldig gemacht!‹');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 23, 31, 'Damit stellt ihr euch selbst das Zeugnis aus, daß ihr die Söhne der Prophetenmörder seid.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 23, 32, 'So macht denn ihr das Maß (der Schuld) eurer Väter voll!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 23, 33, 'Ihr Schlangen, ihr Otternbrut! Wie wollt ihr dem Strafgericht der Hölle entrinnen?!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 23, 34, '»Deshalb seht: ich sende zu euch Propheten und Weise und Schriftgelehrte; von diesen werdet ihr die einen töten und kreuzigen, die anderen in euren Synagogen geißeln und von Stadt zu Stadt verfolgen,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 23, 35, 'damit über euch alles gerechte Blut komme, das auf der Erde vergossen worden ist, vom Blut des gerechten Abel an bis zum Blut Sacharjas, des Sohnes Berechjas, den ihr zwischen dem Tempelhause und dem Brandopferaltar ermordet habt.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 23, 36, 'Wahrlich ich sage euch: (Die Strafe für) dies alles wird über dieses Geschlecht kommen!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 23, 37, '»Jerusalem, Jerusalem, das du die Propheten tötest und die zu dir Gesandten steinigst! Wie oft habe ich deine Kinder um mich sammeln wollen, wie eine Henne ihre Küchlein unter ihre Flügel sammelt; doch ihr habt nicht gewollt.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 23, 38, 'Nunmehr wird euer Haus euch verödet überlassen;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 23, 39, 'denn ich sage euch: Ihr werdet mich von jetzt an nicht (mehr) sehen, bis ihr (einst bei meiner Wiederkunft) ausruft: ›Gepriesen sei, der da kommt im Namen des Herrn!‹«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 24, 1, 'Jesus verließ dann den Tempel und wollte weitergehen; da traten seine Jünger zu ihm heran, um ihn auf den Prachtbau des Tempels aufmerksam zu machen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 24, 2, 'Er aber antwortete ihnen mit den Worten: »Ja, jetzt seht ihr dies alles noch. Wahrlich ich sage euch: Es wird hier kein Stein auf dem andern bleiben, der nicht niedergerissen wird!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 24, 3, 'Als er sich dann auf dem Ölberg niedergesetzt hatte, traten die Jünger, als sie für sich allein waren, an ihn mit der Bitte heran: »Sage uns doch: wann wird dies geschehen? Und welches ist das Zeichen deiner Ankunft und der Vollendung der Weltzeit?«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 24, 4, 'Jesus antwortete ihnen: »Sehet euch vor, daß niemand euch irreführe!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 24, 5, 'Denn viele werden unter meinem Namen kommen und behaupten: ›Ich bin der (wiederkehrende) Christus‹, und werden viele irreführen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 24, 6, 'Ihr werdet ferner von Kriegen und Kriegsgerüchten hören: gebt acht, laßt euch dadurch nicht erschrecken! Denn das muß so kommen, ist aber noch nicht das Ende.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 24, 7, 'Denn ein Volk wird sich gegen das andere erheben und ein Reich gegen das andere; auch Hungersnöte werden eintreten und Erdbeben hier und da stattfinden;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 24, 8, 'dies alles ist aber erst der Anfang der Wehen.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 24, 9, '»Hierauf wird man schwere Drangsale über euch bringen und euch töten, und ihr werdet allen Völkern um meines Namens willen verhaßt sein.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 24, 10, 'Alsdann werden viele Anstoß nehmen und sich einander ausliefern und einander hassen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 24, 11, 'Auch falsche Propheten werden in großer Zahl auftreten und viele irreführen;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 24, 12, 'und weil die Gesetzlosigkeit überhand nimmt, wird die Liebe in den meisten erkalten;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 24, 13, 'wer jedoch bis ans Ende ausharrt, der wird gerettet werden.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 24, 14, 'Und diese Heilsbotschaft vom Reich wird auf dem ganzen Erdkreis allen Völkern zum Zeugnis gepredigt werden, und dann wird das Ende kommen.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 24, 15, '»Wenn ihr nun den Greuel der Verwüstung, der vom Propheten Daniel angesagt worden ist, an heiliger Stätte stehen seht – der Leser merke auf! –,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 24, 16, 'dann sollen die (Gläubigen), die in Judäa sind, ins Gebirge fliehen!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 24, 17, 'Wer sich alsdann auf dem Dache befindet, steige nicht erst noch hinab (ins Haus), um seine Habseligkeiten aus dem Hause zu holen;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 24, 18, 'und wer auf dem Felde weilt, kehre nicht zurück, um sich noch seinen Mantel zu holen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 24, 19, 'Wehe aber den Frauen, die guter Hoffnung sind, und denen, die ein Kind in jenen Tagen zu nähren haben!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 24, 20, 'Betet nur, daß eure Flucht nicht in den Winter oder auf den Sabbat falle!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 24, 21, 'Denn es wird alsdann eine schlimme Drangsalszeit eintreten, wie noch keine seit Anfang der Welt bis jetzt dagewesen ist und wie auch keine wieder kommen wird;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 24, 22, 'und wenn jene Tage nicht verkürzt würden, so würde kein Fleisch gerettet werden; aber um der Auserwählten willen werden jene Tage verkürzt werden.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 24, 23, '»Wenn dann jemand zu euch sagt: ›Seht, hier ist Christus!‹ oder: ›Dort (ist er)!‹, so glaubt es nicht!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 24, 24, 'Denn es werden falsche Christusse und falsche Propheten auftreten und werden große Zeichen und Wunder verrichten, um womöglich auch die Auserwählten irrezuführen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 24, 25, 'Seht, ich habe es euch vorhergesagt. Wenn man also zu euch sagt:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 24, 26, '›Seht, er ist in der Wüste!‹, so geht nicht hinaus; und (sagt man:) ›Seht, er ist in den Gemächern (dieses oder jenes Hauses)!‹, so glaubt es nicht!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 24, 27, 'Denn wie der Blitz vom Osten ausgeht und bis zum Westen leuchtet, so wird es auch mit der Ankunft des Menschensohnes sein;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 24, 28, 'denn wo das Aas liegt, da sammeln sich die Geier.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 24, 29, '»Sogleich aber nach jener Drangsalszeit wird die Sonne sich verfinstern und der Mond seinen Schein verlieren; die Sterne werden vom Himmel fallen und die Kräfte des Himmels in Erschütterung geraten.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 24, 30, 'Und dann wird das Zeichen des Menschensohnes am Himmel erscheinen, und dann werden alle Geschlechter der Erde wehklagen und werden den Menschensohn auf den Wolken des Himmels mit großer Macht und Herrlichkeit kommen sehen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 24, 31, 'Und er wird seine Engel unter lautem Posaunenschall aussenden, und sie werden seine Auserwählten von den vier Windrichtungen her versammeln, von dem einen Himmelsende bis zum andern.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 24, 32, 'Vom Feigenbaum aber mögt ihr das Gleichnis lernen: Sobald seine Zweige saftig werden und Blätter hervorwachsen, so erkennt ihr daran, daß der Sommer nahe ist.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 24, 33, 'So auch ihr: wenn ihr dies alles seht, so erkennet daran, daß es nahe vor der Tür steht.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 24, 34, 'Wahrlich ich sage euch: Dieses Geschlecht wird nicht vergehen, bis dies alles geschieht.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 24, 35, 'Himmel und Erde werden vergehen, meine Worte aber werden nimmermehr vergehen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 24, 36, 'Von jenem Tage aber und von jener Stunde hat niemand Kenntnis, auch die Engel im Himmel nicht, auch der Sohn nicht, sondern ganz allein der Vater.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 24, 37, 'Denn wie es einst mit den Tagen Noahs gewesen ist, so wird es auch mit der Wiederkunft des Menschensohnes sein.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 24, 38, 'Denn wie sie es in den Tagen vor der Sintflut gehalten haben: sie aßen und tranken, sie heirateten und verheirateten (ihre Töchter) bis zu dem Tage, als Noah in die Arche ging,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 24, 39, 'und wie sie nichts merkten, bis die Sintflut kam und alle hinwegraffte, ebenso wird es auch mit der Zeit der Ankunft des Menschensohnes der Fall sein.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 24, 40, 'Da werden zwei (Männer zusammen) auf dem Felde sein: der eine wird angenommen, der andere zurückgelassen;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 24, 41, 'zwei (Frauen) werden (zusammen) an der Handmühle mahlen: die eine wird angenommen, die andere zurückgelassen.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 24, 42, '»Seid also wachsam, denn ihr wißt nicht, an welchem Tage der Herr kommt.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 24, 43, 'Das aber seht ihr ein: Wenn der Hausherr wüßte, in welcher Stunde der Nacht der Dieb kommt, so würde er wach bleiben und keinen Einbruch in sein Haus zulassen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 24, 44, 'Deshalb haltet auch ihr euch bereit; denn der Menschensohn kommt zu einer Stunde, wo ihr es nicht vermutet.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 24, 45, '»Wer ist demnach der treue und kluge Knecht, den sein Herr über seine Dienerschaft gesetzt hat, damit er ihnen die Speise zu rechter Zeit gebe?');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 24, 46, 'Selig ist ein solcher Knecht (zu preisen), den sein Herr bei seiner Rückkehr in solcher Tätigkeit antrifft.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 24, 47, 'Wahrlich ich sage euch: Er wird ihn über seine sämtlichen Güter setzen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 24, 48, 'Wenn aber ein solcher Knecht schlecht ist und in seinem Herzen denkt: ›Mein Herr kommt noch lange nicht!‹,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 24, 49, 'und wenn er seine Mitknechte zu schlagen beginnt und mit den Trunkenen ißt und trinkt,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 24, 50, 'so wird der Herr eines solchen Knechts an einem Tage kommen, an dem er es nicht erwartet, und zu einer Stunde, die er nicht kennt,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 24, 51, 'und er wird ihn zerhauen lassen und ihm seinen Platz bei den Heuchlern anweisen: dort wird lautes Weinen und Zähneknirschen sein.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 25, 1, '»Alsdann wird das Himmelreich zehn Jungfrauen gleichen, die sich mit ihren Lampen in der Hand zur Einholung des Bräutigams aufmachten.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 25, 2, 'Fünf von ihnen waren töricht und fünf klug;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 25, 3, 'denn die törichten nahmen wohl ihre Lampen, nahmen aber kein Öl mit;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 25, 4, 'die klugen dagegen nahmen außer ihren Lampen auch noch Öl in den Gefäßen mit sich.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 25, 5, 'Als nun der Bräutigam auf sich warten ließ, wurden sie alle müde und schliefen ein.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 25, 6, 'Um Mitternacht aber erscholl ein Geschrei: ›Der Bräutigam ist da! Macht euch auf, ihn zu empfangen!‹');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 25, 7, 'Da erhoben sich jene Jungfrauen alle vom Schlaf und brachten ihre Lampen in Ordnung;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 25, 8, 'die törichten aber sagten zu den klugen: ›Gebt uns von eurem Öl, denn unsere Lampen wollen ausgehen!‹');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 25, 9, 'Da antworteten die klugen: ›Nein, es würde für uns und euch nicht reichen; geht lieber zu den Krämern und kauft euch welches!‹');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 25, 10, 'Während sie nun hingingen, um Öl einzukaufen, kam der Bräutigam, und die Jungfrauen, welche in Bereitschaft waren, gingen mit ihm zum Hochzeitsmahl hinein, und die Tür wurde verschlossen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 25, 11, 'Später kamen dann auch noch die übrigen Jungfrauen und riefen: ›Herr, Herr, öffne uns doch!‹');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 25, 12, 'Er aber gab ihnen zur Antwort: ›Wahrlich ich sage euch: Ich kenne euch nicht!‹');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 25, 13, 'Darum seid wachsam, denn Tag und Stunde sind euch unbekannt.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 25, 14, '»Es wird so sein wie bei einem Manne, der vor Antritt einer Reise ins Ausland seine Knechte rief und ihnen sein Vermögen (zur Verwaltung) übergab;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 25, 15, 'dem einen gab er fünf Talente, dem andern zwei, dem dritten eins, einem jeden nach seiner Tüchtigkeit; dann reiste er ab.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 25, 16, 'Da ging der, welcher die fünf Talente empfangen hatte, sogleich ans Werk, machte Geschäfte mit dem Geld und gewann andere fünf Talente;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 25, 17, 'ebenso gewann der, welcher die zwei Talente (empfangen hatte), zwei andere dazu.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 25, 18, 'Der (Knecht) aber, welcher das eine Talent erhalten hatte, ging hin, grub ein Loch in die Erde und verbarg darin das Geld seines Herrn.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 25, 19, 'Nach längerer Zeit kam der Herr dieser Knechte zurück und rechnete mit ihnen ab.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 25, 20, 'Da trat der herzu, welcher die fünf Talente empfangen hatte, brachte noch fünf andere Talente mit und sagte: ›Herr, fünf Talente hast du mir übergeben; hier sind noch andere fünf Talente, die ich dazugewonnen habe.‹');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 25, 21, 'Da sagte sein Herr zu ihm: ›Schön, du guter und treuer Knecht! Du bist über Wenigem treu gewesen, ich will dich über Vieles setzen: gehe ein zum Freudenmahl deines Herrn!‹');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 25, 22, 'Dann kam auch der (Knecht) herbei, der die zwei Talente (empfangen hatte), und sagte: ›Herr, zwei Talente hast du mir übergeben; hier sind noch zwei andere Talente, die ich dazugewonnen habe.‹');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 25, 23, 'Da sagte sein Herr zu ihm: ›Schön, du guter und treuer Knecht! Du bist über Wenigem treu gewesen, ich will dich über Vieles setzen: gehe ein zum Freudenmahl deines Herrn!‹');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 25, 24, 'Da trat auch der herzu, welcher das eine Talent empfangen hatte, und sagte: ›Herr, ich wußte von dir, daß du ein harter Mann bist: du erntest, wo du nicht gesät hast, und sammelst ein, wo du nicht ausgestreut hast.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 25, 25, 'Da bin ich aus Furcht hingegangen und habe dein Talent in der Erde verborgen: hier hast du dein Geld wieder!‹');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 25, 26, 'Da antwortete ihm sein Herr: ›Du böser und träger Knecht! Du wußtest, daß ich ernte, wo ich nicht gesät habe, und einsammle, wo ich nicht ausgestreut habe?');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 25, 27, 'Nun, so hättest du mein Geld bei den Bankhaltern anlegen sollen; dann hätte ich bei meiner Rückkehr mein Geld mit Zinsen zurückerhalten.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 25, 28, 'So nehmt ihm nun das Talent ab und gebt es dem, der die zehn Talente hat.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 25, 29, 'Denn jedem, der da hat, wird noch hinzugegeben werden, so daß er Überfluß hat; wer aber nicht hat, dem wird auch noch das genommen werden, was er hat.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 25, 30, 'Den unnützen Knecht jedoch werft hinaus in die Finsternis draußen! Dort wird lautes Weinen und Zähneknirschen sein.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 25, 31, '»Wenn aber der Menschensohn in seiner Herrlichkeit kommt und alle Engel mit ihm, dann wird er sich auf den Thron seiner Herrlichkeit setzen;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 25, 32, 'alle Völker werden alsdann vor ihm versammelt werden, und er wird sie voneinander scheiden, wie der Hirt die Schafe von den Böcken scheidet;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 25, 33, 'und er wird die Schafe zu seiner Rechten, die Böcke aber zu seiner Linken stellen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 25, 34, 'Dann wird der König zu denen auf seiner rechten Seite sagen: ›Kommt her, ihr von meinem Vater Gesegneten! Empfangt als euer Erbe das Königtum, das für euch seit Grundlegung der Welt bereitgehalten ist.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 25, 35, 'Denn ich bin hungrig gewesen, und ihr habt mir zu essen gegeben; ich bin durstig gewesen, und ihr habt mir zu trinken gereicht; ich bin ein Fremdling gewesen, und ihr habt mich beherbergt;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 25, 36, 'ich bin ohne Kleidung gewesen, und ihr habt mich gekleidet; ich bin krank gewesen, und ihr habt mich besucht; ich habe im Gefängnis gelegen, und ihr seid zu mir gekommen.‹');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 25, 37, 'Dann werden ihm die Gerechten antworten: ›Herr, wann haben wir dich hungrig gesehen und haben dich gespeist? Oder durstig und haben dir zu trinken gereicht?');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 25, 38, 'Wann haben wir dich als Fremdling gesehen und haben dich beherbergt? Oder ohne Kleidung und haben dich bekleidet?');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 25, 39, 'Wann haben wir dich krank oder im Gefängnis gesehen und sind zu dir gekommen?‹');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 25, 40, 'Dann wird der König ihnen antworten: ›Wahrlich ich sage euch: Alles, was ihr einem von diesen meinen geringsten Brüdern getan habt, das habt ihr mir getan.‹');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 25, 41, 'Alsdann wird er auch zu denen auf seiner linken Seite sagen: ›Hinweg von mir, ihr Verfluchten, in das ewige Feuer, das für den Teufel und seine Engel bereitet ist!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 25, 42, 'Denn ich bin hungrig gewesen, aber ihr habt mir nichts zu essen gegeben; ich bin durstig gewesen, aber ihr habt mir nichts zu trinken gereicht;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 25, 43, 'ich bin ein Fremdling gewesen, aber ihr habt mich nicht beherbergt; ohne Kleidung, aber ihr habt mich nicht bekleidet; krank und im Gefängnis (habe ich gelegen), aber ihr habt mich nicht besucht.‹');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 25, 44, 'Dann werden auch diese antworten: ›Herr, wann haben wir dich hungrig oder durstig, als einen Fremdling oder ohne Kleidung, wann krank oder im Gefängnis gesehen und haben dir nicht gedient?‹');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 25, 45, 'Dann wird er ihnen zur Antwort geben: ›Wahrlich ich sage euch: Alles, was ihr einem von diesen Geringsten nicht getan habt, das habt ihr auch mir nicht getan.‹');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 25, 46, 'Und diese werden in die ewige Strafe gehen, die Gerechten aber in das ewige Leben.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 26, 1, 'Als nun Jesus alle diese Reden beendet hatte, sagte er zu seinen Jüngern:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 26, 2, '»Ihr wißt, daß übermorgen das Passah stattfindet; da wird der Menschensohn zur Kreuzigung überliefert.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 26, 3, 'Damals kamen die Hohenpriester und die Ältesten des Volkes im Palaste des Hohenpriesters namens Kaiphas zusammen');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 26, 4, 'und berieten sich in der Absicht, Jesus mit List festzunehmen und zu töten.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 26, 5, 'Dabei sagten sie aber: »Nur nicht während des Festes, damit keine Unruhen unter dem Volk entstehen!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 26, 6, 'Als Jesus sich aber in Bethanien im Hause Simons des (einstmals) Aussätzigen befand,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 26, 7, 'trat eine Frau mit einem Alabastergefäß voll kostbaren Salböls an ihn heran und goß es ihm über das Haupt, während er bei Tische saß.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 26, 8, 'Als die Jünger das sahen, wurden sie unwillig und sagten: »Wozu diese Verschwendung?');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 26, 9, 'Dieses (Salböl) hätte man doch teuer verkaufen und den Erlös den Armen geben können.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 26, 10, 'Als Jesus es merkte, sagte er zu ihnen: »Warum macht ihr der Frau Vorwürfe? Sie hat ja doch ein gutes Werk an mir getan!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 26, 11, 'Denn die Armen habt ihr allezeit bei euch, mich aber habt ihr nicht allezeit.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 26, 12, 'Daß sie dieses Öl auf meinen Leib gegossen hat, das hat sie für mein Begräbnis getan.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 26, 13, 'Wahrlich ich sage euch: Wo immer diese Heilsbotschaft in der ganzen Welt verkündet wird, da wird man auch von dem, was diese Frau getan hat, zum ehrenden Gedächtnis für sie erzählen.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 26, 14, 'Hierauf ging einer von den Zwölfen namens Judas Iskariot zu den Hohenpriestern');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 26, 15, 'und sagte: »Was wollt ihr mir geben, daß ich ihn euch in die Hände liefere?« Da zahlten sie ihm dreißig Silberstücke aus.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 26, 16, 'Von da an suchte er nach einer guten Gelegenheit, um ihn zu überliefern.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 26, 17, 'Am ersten Tage der ungesäuerten Brote aber traten die Jünger zu Jesus und fragten ihn: »Wo sollen wir dir alles vorbereiten, damit du das Passahmahl halten kannst?«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 26, 18, 'Er antwortete: »Geht in die Stadt zu dem und dem und sagt zu ihm: ›Der Meister läßt dir sagen: Meine Zeit ist nahe; bei dir will ich das Passahmahl mit meinen Jüngern halten.‹«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 26, 19, 'Die Jünger taten, wie Jesus ihnen aufgetragen hatte, und richteten das Passahmahl zu.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 26, 20, 'Als es dann Abend geworden war, setzte er sich mit den zwölf Jüngern zu Tisch;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 26, 21, 'und während des Essens sagte er: »Wahrlich ich sage euch: Einer von euch wird mich ausliefern!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 26, 22, 'Da wurden sie tief betrübt und fragten ihn, einer nach dem andern: »Ich bin es doch nicht etwa, Herr?«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 26, 23, 'Er antwortete: »Der die Hand zusammen mit mir in die Schüssel getaucht hat, der wird mich ausliefern.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 26, 24, 'Der Menschensohn geht zwar dahin, wie über ihn in der Schrift steht; doch wehe dem Menschen, durch den der Menschensohn verraten wird! Für diesen Menschen wäre es besser, er wäre nicht geboren!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 26, 25, 'Da nahm Judas, der ihn verraten wollte, das Wort und fragte: »Ich bin es doch nicht etwa, Rabbi?« Er erwiderte ihm: »Doch, du bist es.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 26, 26, 'Während des Essens aber nahm Jesus das Brot, sprach den Lobpreis (Gottes), brach das Brot und gab es den Jüngern mit den Worten: »Nehmt, esset! Dies ist mein Leib.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 26, 27, 'Dann nahm er einen Becher, sprach das Dankgebet und gab ihnen den mit den Worten: »Trinkt alle daraus!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 26, 28, 'Denn dies ist mein Blut, das Blut des (neuen) Bundes, das für viele vergossen wird zur Vergebung der Sünden.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 26, 29, 'Ich sage euch aber: Ich werde von nun an von diesem Erzeugnis des Weinstocks nicht mehr trinken bis zu jenem Tage, an dem ich es mit euch neu trinken werde im Reiche meines Vaters.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 26, 30, 'Nachdem sie dann den Lobpreis (Ps 115-118) gesungen hatten, gingen sie (aus der Stadt) hinaus an den Ölberg.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 26, 31, 'Dabei sagte Jesus zu ihnen: »Ihr werdet alle in dieser Nacht an mir Anstoß nehmen; denn es steht geschrieben: ›Ich werde den Hirten niederschlagen, dann werden die Schafe der Herde sich zerstreuen.‹');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 26, 32, 'Nach meiner Auferweckung aber werde ich euch voraus nach Galiläa gehen.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 26, 33, 'Da antwortete ihm Petrus: »Mögen auch alle an dir Anstoß nehmen: ich werde niemals an dir Anstoß nehmen!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 26, 34, 'Jesus erwiderte ihm: »Wahrlich ich sage dir: Noch in dieser Nacht, ehe der Hahn kräht, wirst du mich dreimal verleugnen.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 26, 35, 'Petrus antwortete ihm: »Wenn ich auch mit dir sterben müßte, werde ich dich doch niemals verleugnen!« Das gleiche versicherten auch die anderen Jünger alle.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 26, 36, 'Hierauf kam Jesus mit ihnen an einen Ort namens Gethsemane und sagte zu den Jüngern: »Setzt euch hier nieder, während ich dorthin gehe und bete!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 26, 37, 'Dann nahm er Petrus und die beiden Söhne des Zebedäus mit sich und fing an zu trauern und zu zagen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 26, 38, 'Da sagte er zu ihnen: »Tiefbetrübt ist meine Seele bis zum Tode; bleibt hier und haltet euch wach mit mir!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 26, 39, 'Nachdem er dann ein wenig weitergegangen war, warf er sich auf sein Angesicht nieder und betete mit den Worten: »Mein Vater, wenn es möglich ist, so laß diesen Kelch an mir vorübergehen! Doch nicht wie ich will, sondern wie du willst!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 26, 40, 'Hierauf ging er zu den Jüngern zurück und fand sie schlafend und sagte zu Petrus: »So wenig seid ihr imstande gewesen, eine einzige Stunde mit mir zu wachen?');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 26, 41, 'Wachet, und betet, damit ihr nicht in Versuchung geratet! Der Geist ist willig, das Fleisch aber ist schwach.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 26, 42, 'Wiederum ging er zum zweitenmal weg und betete mit den Worten: »Mein Vater, wenn dieser Kelch nicht (an mir) vorübergehen kann, ohne daß ich ihn trinke, so geschehe dein Wille!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 26, 43, 'Als er dann zurückkam, fand er sie (wieder) schlafend, denn die Augen fielen ihnen vor Müdigkeit zu.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 26, 44, 'Da verließ er sie, ging wieder weg und betete zum drittenmal, wieder mit denselben Worten.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 26, 45, 'Hierauf kehrte er zu den Jüngern zurück und sagte zu ihnen: »Schlaft ein andermal und ruht euch aus! Doch jetzt ist die Stunde gekommen, daß der Menschensohn Sündern in die Hände geliefert wird!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 26, 46, 'Steht auf, wir wollen gehen! Seht, mein Verräter ist nahe gekommen!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 26, 47, 'Während er noch redete, da kam plötzlich Judas, einer von den Zwölfen, und mit ihm eine große Schar mit Schwertern und Knütteln, von den Hohenpriestern und Ältesten des Volkes her.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 26, 48, 'Sein Verräter hatte aber ein Zeichen mit ihnen verabredet, nämlich: »Der, den ich küssen werde, der ist’s; den nehmt fest!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 26, 49, 'Er trat also sogleich auf Jesus zu mit den Worten: »Sei gegrüßt, Rabbi!« und küßte ihn.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 26, 50, 'Jesus aber sagte zu ihm: »Freund, (tu das) wozu du hergekommen bist!« Hierauf traten sie herzu, legten Hand an Jesus und nahmen ihn fest.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 26, 51, 'Einer jedoch von den Begleitern Jesu streckte die Hand aus, zog sein Schwert, schlug damit nach dem Knechte des Hohenpriesters und hieb ihm das Ohr ab.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 26, 52, 'Da sagte Jesus zu ihm: »Stecke dein Schwert wieder an seinen Ort! Denn wer zum Schwerte greift, wird durchs Schwert umkommen!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 26, 53, 'Oder meinst du, ich könnte meinen Vater nicht bitten, und er würde mir nicht sogleich mehr als zwölf Legionen Engel zu Hilfe senden?');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 26, 54, 'Wie sollten dann aber die Aussprüche der Schrift erfüllt werden, daß es so geschehen muß?«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 26, 55, 'In jener Stunde sagte Jesus zu den Haufen: »Wie gegen einen Räuber seid ihr mit Schwertern und Knütteln ausgezogen, um mich gefangen zu nehmen. Täglich habe ich im Tempel gesessen und gelehrt, und ihr habt mich nicht festgenommen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 26, 56, 'Dies alles ist aber geschehen, damit die Schriften der Propheten erfüllt werden!« Hierauf verließen ihn die Jünger alle und ergriffen die Flucht.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 26, 57, 'Die Männer aber, die Jesus festgenommen hatten, führten ihn zu dem Hohenpriester Kaiphas ab, wo die Schriftgelehrten und die Ältesten sich versammelten.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 26, 58, 'Petrus aber folgte ihm von fern bis zum Palast des Hohenpriesters, ging hinein und setzte sich dort unter den Dienern hin, um den Ausgang der Sache abzuwarten.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 26, 59, 'Die Hohenpriester aber und der gesamte Hohe Rat suchten nach einer falschen Zeugenaussage gegen Jesus, um ihn zum Tode verurteilen zu können;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 26, 60, 'doch sie fanden keine, obgleich viele falsche Zeugen herzutraten. Zuletzt aber traten zwei auf');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 26, 61, 'und sagten aus: »Dieser Mensch hat behauptet: ›Ich kann den Tempel Gottes abbrechen und ihn in drei Tagen wieder aufbauen.‹«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 26, 62, 'Da stand der Hohepriester auf und fragte ihn: »Entgegnest du nichts auf das, was diese Zeugen gegen dich aussagen?« Jesus aber schwieg.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 26, 63, 'Da sagte der Hohepriester zu ihm: »Ich beschwöre dich bei dem lebendigen Gott: Sage uns, bist du Christus, der Sohn Gottes?«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 26, 64, 'Da gab Jesus ihm zur Antwort: »Ja, ich bin es! Doch ich tue euch kund: Von jetzt an werdet ihr den Menschensohn sitzen sehen zur Rechten der Macht und kommen auf den Wolken des Himmels.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 26, 65, 'Da zerriß der Hohepriester seine Kleider und sagte: »Er hat Gott gelästert! Wozu brauchen wir noch Zeugen? Jetzt habt ihr selbst die Gotteslästerung gehört! Was urteilt ihr?«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 26, 66, 'Sie gaben die Erklärung ab: »Er ist des Todes schuldig!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 26, 67, 'Hierauf spien sie ihm ins Gesicht und schlugen ihn mit den Fäusten; andere gaben ihm Backenstreiche');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 26, 68, 'und sagten: »Weissage uns, Christus! Wer ist es, der dich geschlagen hat?«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 26, 69, 'Petrus aber saß (unterdessen) draußen im Hof. Da trat eine Magd auf ihn zu und sagte: »Du bist auch bei Jesus, dem Galiläer, gewesen!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 26, 70, 'Er aber leugnete vor allen und sagte: »Ich verstehe nicht, was du da sagst!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 26, 71, 'Als er dann in die Torhalle hinausgegangen war, bemerkte ihn eine andere Magd und sagte zu den Leuten dort: »Dieser ist auch mit Jesus, dem Nazoräer, zusammen gewesen!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 26, 72, 'Da leugnete er wieder, (diesmal) mit einem Eid: »ich kenne den Menschen nicht!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 26, 73, 'Nach einer kleinen Weile aber traten die Leute, die dort standen, hinzu und sagten zu Petrus: »Wahrhaftig, du gehörst auch zu ihnen: schon deine Sprache verrät dich!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 26, 74, 'Da fing er an, sich zu verfluchen und zu schwören: »Ich kenne den Menschen nicht!«, und sogleich darauf krähte der Hahn.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 26, 75, 'Da dachte Petrus an das Wort Jesu, der ihm gesagt hatte: »Noch ehe der Hahn kräht, wirst du mich dreimal verleugnen.« Und er ging hinaus und weinte bitterlich.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 27, 1, 'Als es hierauf Tag geworden war, faßten alle Hohenpriester und die Ältesten des Volkes einen Beschluß gegen Jesus, um seine Hinrichtung zu erreichen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 27, 2, 'Sie ließen ihn dann fesseln und abführen und übergaben ihn dem Statthalter Pontius Pilatus.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 27, 3, 'Als jetzt Judas, sein Verräter, erkannte, daß er (Jesus) verurteilt worden war, bereute er seine Tat. Und er brachte die dreißig Silberstücke den Hohenpriestern und Ältesten zurück');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 27, 4, 'mit den Worten: »Ich habe unrecht getan, daß ich unschuldiges Blut überantwortet habe!« Sie aber erwiderten: »Was geht das uns an? Da sich du selber zu!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 27, 5, 'Da warf er das Geld in das Tempelhaus und machte sich davon, ging hin und erhängte sich.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 27, 6, 'Die Hohenpriester aber nahmen das Geld und sagten: »Es geht nicht an, daß wir es in den Tempelschatz tun, denn es ist Blutgeld.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 27, 7, 'Nachdem sie dann einen Beschluß gefaßt hatten, kauften sie für das Geld den ›Töpferacker‹ zum Begräbnisplatz für die Fremden;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 27, 8, 'daher führt jener Acker den Namen ›Blutacker‹ (hebräisch Hakeldama) bis auf den heutigen Tag.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 27, 9, 'Damals erfüllte sich das Wort des Propheten Jeremia: »Sie nahmen die dreißig Silberstücke, den Geldbetrag für den so Gewerteten, auf den man von seiten der Israeliten einen solchen Preis ausgesetzt hatte,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 27, 10, 'und gaben sie für den Töpferacker, wie der Herr es mir geboten hatte.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 27, 11, 'Jesus aber wurde dem Statthalter vorgeführt, und dieser befragte ihn mit den Worten: »Bist du der König der Juden?« Jesus antwortete: »Ja, ich bin es.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 27, 12, 'Während er dann von den Hohenpriestern und Ältesten angeklagt wurde, gab er keine Antwort.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 27, 13, 'Da fragte ihn Pilatus: »Hörst du nicht, was sie alles gegen dich aussagen?«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 27, 14, 'Doch er antwortete ihm auf keine einzige Frage, so daß der Statthalter sich sehr verwunderte.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 27, 15, 'An jedem (Passah-) Fest aber pflegte der Statthalter dem Volke einen Gefangenen nach ihrer Wahl freizugeben.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 27, 16, 'Man hatte aber damals einen berüchtigten Gefangenen namens Barabbas (in Haft).');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 27, 17, 'Als die Menge nun versammelt war, fragte Pilatus sie: »Wen soll ich euch freigeben, Barabbas oder Jesus, den man Christus nennt?«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 27, 18, 'Er wußte nämlich wohl, daß sie ihn aus Neid überantwortet hatten.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 27, 19, 'Während er aber auf dem Richterstuhl saß, schickte seine Frau zu ihm und ließ ihm sagen: »Habe du mit diesem Gerechten nichts zu schaffen! Denn ich habe heute nacht im Traum viel um seinetwillen ausgestanden.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 27, 20, 'Die Hohenpriester und Ältesten aber redeten auf das Volk ein, sie möchten sich den Barabbas erbitten, Jesus dagegen hinrichten lassen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 27, 21, 'Da richtete der Statthalter (nochmals) die Frage an sie: »Wen von den beiden soll ich euch freigeben?« Sie riefen: »Barabbas!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 27, 22, 'Pilatus fragte sie weiter: »Was soll ich denn mit Jesus machen, den man Christus nennt?« Sie riefen alle: »Ans Kreuz mit ihm!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 27, 23, 'Der Statthalter entgegnete ihnen: »Was hat er denn Böses getan?« Sie schrien nur noch lauter: »Ans Kreuz mit ihm!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 27, 24, 'Als nun Pilatus einsah, daß er nichts erreichte, der Lärm vielmehr immer größer wurde, ließ er sich Wasser reichen, wusch sich vor dem Volk die Hände und sagte: »Ich bin am Blut dieses Gerechten unschuldig; seht ihr zu!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 27, 25, 'Da antwortete das gesamte Volk mit dem Ruf: »Sein Blut (komme) über uns und über unsere Kinder!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 27, 26, 'Daraufhin gab er ihnen den Barabbas frei, Jesus aber ließ er geißeln und überwies ihn dann (den Soldaten) zur Kreuzigung.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 27, 27, 'Hierauf nahmen die Soldaten des Statthalters Jesus mit sich in die Statthalterei und riefen dort die ganze Kohorte gegen ihn zusammen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 27, 28, 'Dann entkleideten sie ihn und legten ihm einen scharlachroten Mantel um,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 27, 29, 'flochten aus Dornen eine Krone, die sie ihm aufs Haupt setzten, und (gaben) ihm ein Rohr in die rechte Hand; darauf warfen sie sich vor ihm auf die Knie nieder und verhöhnten ihn mit den Worten: »Sei gegrüßt, Judenkönig!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 27, 30, 'Auch spien sie ihn an, nahmen das Rohr und schlugen ihn damit aufs Haupt.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 27, 31, 'Nachdem sie ihn so verspottet hatten, nahmen sie ihm den Mantel wieder ab und legten ihm seine eigenen Kleider an; dann führten sie ihn zur Kreuzigung ab.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 27, 32, 'Während sie aber (zur Stadt) hinauszogen, trafen sie einen Mann aus Cyrene namens Simon an; diesen zwangen sie, ihm das Kreuz zu tragen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 27, 33, 'Als sie dann auf einem Platz namens Golgatha, das bedeutet Schädelstätte, angekommen waren,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 27, 34, 'gaben sie ihm Wein zu trinken, der mit Galle vermischt war; doch als er ihn gekostet hatte, wollte er ihn nicht trinken.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 27, 35, 'Nachdem sie ihn dann gekreuzigt hatten, verteilten sie seine Kleidungsstücke unter sich, indem sie das Los um sie warfen,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 27, 36, 'setzten sich hierauf nieder und bewachten ihn dort.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 27, 37, 'Über seinem Haupt hatten sie eine Inschrift angebracht, die seine Schuld angeben sollte; sie lautete: »Dieser ist Jesus, der König der Juden.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 27, 38, 'Sodann wurden zwei Räuber mit ihm gekreuzigt, der eine zu seiner Rechten, der andere zu seiner Linken.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 27, 39, 'Die Vorübergehenden aber schmähten ihn, wobei sie den Kopf schüttelten');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 27, 40, 'und ausriefen: »Du wolltest ja den Tempel abbrechen und ihn in drei Tagen wieder aufbauen! Hilf dir nun selbst, wenn du Gottes Sohn bist, und steige vom Kreuz herab!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 27, 41, 'Ebenso verhöhnten ihn auch die Hohenpriester samt den Schriftgelehrten und Ältesten mit den Worten:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 27, 42, '»Anderen hat er geholfen, sich selber kann er nicht helfen! Er ist der König von Israel: so steige er jetzt vom Kreuz herab, dann wollen wir an ihn glauben!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 27, 43, 'Er hat auf Gott vertraut: der rette ihn jetzt, wenn er ihm wohlwill! Er hat ja doch behauptet: ›Ich bin Gottes Sohn.‹«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 27, 44, 'In der gleichen Weise schmähten ihn auch die Räuber, die mit ihm gekreuzigt waren.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 27, 45, 'Aber von der sechsten Stunde an trat eine Finsternis über das ganze Land ein bis zur neunten Stunde.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 27, 46, 'Um die neunte Stunde aber rief Jesus mit lauter Stimme aus: »Eli, Eli, lema sabachthani?«, das heißt: »Mein Gott, mein Gott, warum hast du mich verlassen?«.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 27, 47, 'Als einige von den dort Stehenden dies hörten, sagten sie: »Der ruft den Elia!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 27, 48, 'Und sogleich lief einer von ihnen hin, nahm einen Schwamm, tränkte ihn mit Essig, steckte ihn an ein Rohr und wollte Jesus trinken lassen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 27, 49, 'Die anderen aber sagten: »Laß das! Wir wollen doch sehen, ob Elia wirklich kommt, um ihm zu helfen.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 27, 50, 'Jesus aber stieß noch einmal einen lauten Schrei aus und gab dann seinen Geist auf.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 27, 51, 'Da zerriß der Vorhang im Tempel von oben bis unten in zwei Stücke, die Erde erbebte und die Felsen zersprangen,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 27, 52, 'die Gräber taten sich auf, und viele Leiber der entschlafenen Heiligen wurden auferweckt,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 27, 53, 'kamen nach seiner Auferstehung aus ihren Gräbern hervor, gingen in die heilige Stadt hinein und erschienen vielen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 27, 54, 'Als aber der Hauptmann und seine Leute, die Jesus zu bewachen hatten, das Erdbeben und was (sonst noch) geschah, sahen, gerieten sie in große Furcht und sagten: »Dieser ist wirklich Gottes Sohn gewesen!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 27, 55, 'Es waren dort aber auch viele Frauen zugegen, die von weitem zuschauten; sie waren Jesus aus Galiläa nachgefolgt und hatten ihm Dienste geleistet.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 27, 56, 'Unter ihnen befanden sich Maria von Magdala und Maria, die Mutter des Jakobus und des Joseph, und die Mutter der Söhne des Zebedäus.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 27, 57, 'Als es dann Spätnachmittag geworden war, kam ein reicher Mann von Arimathäa namens Joseph, der gleichfalls ein Jünger Jesu geworden war;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 27, 58, 'dieser begab sich zu Pilatus und bat ihn um den Leichnam Jesu. Da gab Pilatus den Befehl, man solle ihm den Leichnam übergeben.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 27, 59, 'Joseph nahm nun den Leichnam, wickelte ihn in reine Leinwand');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 27, 60, 'und legte ihn in das neue Grab, das er für sich selbst im Felsen hatte aushauen lassen; dann wälzte er einen großen Stein vor den Eingang des Grabes und entfernte sich.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 27, 61, 'Es waren aber dort Maria von Magdala und die andere Maria zugegen; die saßen dem Grabe gegenüber. –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 27, 62, 'Am nächsten Tage aber, der auf den Rüsttag folgte, versammelten sich die Hohenpriester und Pharisäer bei Pilatus');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 27, 63, 'und sagten: »Herr, es ist uns eingefallen, daß jener Betrüger bei seinen Lebzeiten angekündigt hat: ›Nach drei Tagen werde ich auferweckt.‹');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 27, 64, 'Gib also Befehl, daß das Grab bis zum dritten Tag sicher bewacht wird; sonst könnten seine Jünger kommen, könnten ihn stehlen und dann zum Volke sagen: ›Er ist von den Toten auferweckt worden‹; dann würde der letzte Betrug noch schlimmer sein als der erste.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 27, 65, 'Pilatus antwortete ihnen: »Ihr sollt eine Wachmannschaft haben; geht hin und verwahrt (das Grab) sicher, so gut ihr könnt!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 27, 66, 'Da gingen sie hin und sicherten das Grab unter Hinzuziehung der Wachmannschaft, nachdem sie den Stein versiegelt hatten.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 28, 1, 'Nach Ablauf des Sabbats aber, als der erste Tag nach dem Sabbat anbrechen wollte, gingen Maria von Magdala und die andere Maria hin, um nach dem Grabe zu sehen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 28, 2, 'Da entstand plötzlich ein starkes Erdbeben; denn ein Engel des Herrn, der vom Himmel herabgekommen und herangetreten war, wälzte den Stein weg und setzte sich oben darauf.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 28, 3, 'Sein Aussehen war (leuchtend) wie der Blitz und sein Gewand weiß wie der Schnee.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 28, 4, 'Aus Furcht vor ihm zitterten die Wächter und wurden wie tot.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 28, 5, 'Der Engel aber wandte sich an die Frauen mit den Worten: »Fürchtet ihr euch nicht! Denn ich weiß, daß ihr Jesus, den Gekreuzigten, sucht.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 28, 6, 'Er ist nicht (mehr) hier, denn er ist auferweckt worden, wie er es vorausgesagt hat. Kommt her, seht euch die Stelle an, wo er gelegen hat.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 28, 7, 'Geht nun eilends hin und sagt seinen Jüngern: »Er ist von den Toten auferweckt worden und geht euch voran nach Galiläa; dort werdet ihr ihn wiedersehen; beachtet wohl, was ich euch gesagt habe!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 28, 8, 'Da gingen sie eilends vom Grabe weg voller Furcht und (zugleich) voll großer Freude und eilten davon, um seinen Jüngern die Botschaft zu bringen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 28, 9, 'Und siehe! Jesus kam ihnen entgegen mit den Worten: »Seid gegrüßt!« Da gingen sie auf ihn zu, umfaßten seine Füße und warfen sich anbetend vor ihm nieder.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 28, 10, 'Hierauf sagte Jesus zu ihnen: »Fürchtet euch nicht! Geht hin und verkündigt meinen Brüdern, daß sie nach Galiläa gehen sollen: dort werden sie mich wiedersehen.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 28, 11, 'Während sie nun hingingen, begaben sich einige von der Wachmannschaft (des Grabes) in die Stadt und meldeten den Hohenpriestern alles, was sich zugetragen hatte.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 28, 12, 'Nachdem diese sich mit den Ältesten versammelt und sich beraten hatten, gaben sie den Soldaten reichlich Geld');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 28, 13, 'und sagten: »Macht folgende Aussagen: ›Seine Jünger sind bei Nacht gekommen und haben ihn gestohlen, während wir schliefen.‹');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 28, 14, 'Und wenn dies dem Statthalter zu Ohren kommen sollte, wollen wir ihn schon beschwichtigen und dafür sorgen, daß ihr keine Angst zu haben braucht.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 28, 15, 'Da nahmen sie (die Soldaten) das Geld und verfuhren nach der empfangenen Weisung; und so ist dieses Gerede bei den Juden in Umlauf gekommen bis zum heutigen Tag.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 28, 16, 'Die elf Jünger aber begaben sich nach Galiläa auf den Berg, wohin Jesus sie beschieden hatte;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 28, 17, 'und als sie ihn erblickten, warfen sie sich vor ihm nieder; einige aber hegten Zweifel.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 28, 18, 'Da trat Jesus herzu und redete sie mit den Worten an: »Mir ist alle Gewalt im Himmel und auf Erden verliehen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 28, 19, 'Darum gehet hin und macht alle Völker zu (meinen) Jüngern: tauft sie auf den Namen des Vaters, des Sohnes und des heiligen Geistes');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 28, 20, 'und lehrt sie alles halten, was ich euch geboten habe. Und wisset wohl: Ich bin bei euch alle Tage bis ans Ende der Weltzeit!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 1, 1, 'Die Heilsbotschaft von Jesus Christus, dem Sohne Gottes, hat folgenden Anfang:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 1, 2, 'Wie beim Propheten Jesaja geschrieben steht: »Siehe, ich sende meinen Boten vor dir her, der dir den Weg herrichten soll«;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 1, 3, '»eine Stimme ruft in der Wüste: ›Bereitet den Weg des Herrn, macht gerade seine Pfade!‹« –:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 1, 4, 'so trat Johannes der Täufer in der Wüste auf, indem er eine Taufe der Buße predigte zur Vergebung der Sünden.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 1, 5, 'Da zog das ganze jüdische Land und auch alle Einwohner Jerusalems zu ihm hinaus und ließen sich von ihm im Jordanfluß taufen, indem sie ihre Sünden bekannten.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 1, 6, 'Johannes trug aber ein Fell von Kamelhaaren und einen ledernen Gurt um seine Hüften; er nährte sich von Heuschrecken und wildem Honig,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 1, 7, 'und seine Predigt lautete: »Nach mir kommt der, welcher stärker ist als ich, für den ich nicht gut genug bin, ihm gebückt seine Schuhriemen aufzulösen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 1, 8, 'Ich habe euch (nur) mit Wasser getauft, er aber wird euch mit heiligem Geiste taufen.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 1, 9, 'In jenen Tagen begab es sich nun auch, daß Jesus aus Nazareth in Galiläa kam und sich von Johannes im Jordan taufen ließ.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 1, 10, 'Da, als er gerade aus dem Wasser heraufstieg, sah er (Johannes oder Jesus) den Himmel sich spalten und den Geist wie eine Taube auf ihn herabschweben;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 1, 11, 'und eine Stimme erscholl aus den Himmeln: »Du bist mein geliebter Sohn; an dir habe ich Wohlgefallen gefunden!« –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 1, 12, 'Und sogleich trieb der Geist ihn in die Wüste hinaus;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 1, 13, 'und er war vierzig Tage lang in der Wüste und wurde vom Satan versucht; er weilte dort bei den wilden Tieren, und die Engel leisteten ihm Dienste.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 1, 14, 'Nachdem dann Johannes ins Gefängnis gesetzt war, begab Jesus sich nach Galiläa und verkündete dort die Heilsbotschaft Gottes');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 1, 15, 'mit den Worten: »Die Zeit ist erfüllt und das Reich Gottes nahe herbeigekommen; tut Buße und glaubt an die Heilsbotschaft!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 1, 16, 'Als Jesus nun (eines Tages) am Ufer des Galiläischen Sees hinging, sah er Simon und Andreas, den Bruder Simons, die Netze im See auswerfen; sie waren nämlich Fischer.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 1, 17, 'Da sagte Jesus zu ihnen: »Kommt, folgt mir nach, ich will euch zu Menschenfischern machen!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 1, 18, 'Sogleich ließen sie ihre Netze liegen und folgten ihm nach.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 1, 19, 'Als er dann ein wenig weitergegangen war, sah er Jakobus, den Sohn des Zebedäus, und seinen Bruder Johannes, die, ebenfalls im Boot, ihre Netze instand setzten.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 1, 20, 'Sogleich berief er sie; da ließen sie ihren Vater Zebedäus mit den Lohnknechten im Boot und folgten ihm nach.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 1, 21, 'Sie begaben sich dann nach Kapernaum hinein; und sogleich am (nächsten) Sabbat ging er in die Synagoge und lehrte.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 1, 22, 'Da waren sie über seine Lehre betroffen; denn er lehrte sie wie einer, der Vollmacht hat, ganz anders als die Schriftgelehrten.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 1, 23, 'Nun war da gerade in ihrer Synagoge ein Mann mit einem unreinen Geist behaftet; der schrie auf');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 1, 24, 'und rief: »Was willst du von uns, Jesus von Nazareth? Du bist gekommen, um uns zu verderben! Ich weiß von dir, wer du bist: der Heilige Gottes!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 1, 25, 'Jesus bedrohte ihn mit den Worten: »Verstumme und fahre aus von ihm!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 1, 26, 'Da riß der unreine Geist den Mann (in Krämpfen) hin und her und fuhr dann mit einem lauten Schrei von ihm aus.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 1, 27, 'Da gerieten sie allesamt in Staunen, so daß sie sich miteinander besprachen und sich befragten: »Was ist dies? Eine neue Lehre mit (göttlicher) Vollmacht! Auch den unreinen Geistern gebietet er, und sie gehorchen ihm!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 1, 28, 'Und der Ruf von ihm verbreitete sich alsbald überall in der ganzen umliegenden Landschaft Galiläa.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 1, 29, 'Sobald sie dann die Synagoge verlassen hatten, begaben sie sich in Begleitung des Jakobus und Johannes in das Haus des Simon und Andreas.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 1, 30, 'Die Schwiegermutter Simons aber lag dort fieberkrank zu Bett, was man ihm sogleich von ihr mitteilte.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 1, 31, 'Er trat nun zu ihr, faßte sie bei der Hand und richtete sie auf; da wich das Fieber sogleich von ihr, und sie wartete ihnen (bei der Mahlzeit) auf.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 1, 32, 'Als es dann Abend geworden und die Sonne untergegangen war, brachte man alle Kranken und Besessenen zu ihm,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 1, 33, 'und die ganze Stadt war an der Tür versammelt.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 1, 34, 'Und er heilte viele, die an Krankheiten aller Art litten, und trieb viele böse Geister aus, ließ dabei aber die Geister nicht reden, weil sie ihn kannten.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 1, 35, 'Frühmorgens aber, als es noch ganz dunkel war, stand er auf, verließ das Haus und begab sich an einen einsamen Ort, wo er betete.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 1, 36, 'Simon jedoch und seine Genossen eilten ihm nach,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 1, 37, 'und als sie ihn gefunden hatten, sagten sie zu ihm: »Alle suchen dich!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 1, 38, 'Er aber antwortete ihnen: »Wir wollen anderswohin in die benachbarten Ortschaften gehen, damit ich auch dort die Botschaft ausrichte; denn dazu bin ich ausgezogen.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 1, 39, 'So wanderte er denn in ganz Galiläa umher, indem er in ihren Synagogen predigte und die bösen Geister austrieb.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 1, 40, 'Da kam ein Aussätziger zu ihm, fiel vor ihm auf die Knie nieder und bat ihn flehentlich mit den Worten: »Wenn du willst, kannst du mich reinigen.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 1, 41, 'Jesus hatte Mitleid mit ihm, streckte seine Hand aus, faßte ihn an und sagte zu ihm: »Ich will’s: werde rein!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 1, 42, 'Da verschwand der Aussatz sogleich von ihm, und er wurde rein.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 1, 43, 'Jesus aber gab ihm strenge Weisung, hieß ihn auf der Stelle weggehen');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 1, 44, 'und sagte zu ihm: »Hüte dich, jemandem etwas davon zu sagen! Gehe vielmehr hin, zeige dich dem Priester und bringe für deine Reinigung das Opfer dar, das Mose geboten hat, zum Zeugnis für sie!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 1, 45, 'Als jener aber weggegangen war, fing er an, vielfach davon zu erzählen und die Sache überall bekannt zu machen, so daß Jesus nicht mehr offen in eine Stadt hineingehen konnte, sondern sich draußen an einsamen Orten aufhalten mußte; und doch kamen die Leute von allen Seiten her zu ihm.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 2, 1, 'Als er dann nach einiger Zeit wieder nach Kapernaum heimgekommen war und die Kunde sich verbreitet hatte, daß er im Hause sei,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 2, 2, 'da versammelten sich alsbald so viele Leute, daß selbst der Platz vor der Tür für sie nicht mehr ausreichte; und er verkündigte ihnen das Wort.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 2, 3, 'Da kamen Leute zu ihm, die einen Gelähmten brachten, der von vier Männern getragen wurde.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 2, 4, 'Weil sie nun mit ihm wegen der Volksmenge nicht an ihn herankommen konnten, deckten sie über der Stelle, wo Jesus sich befand, das Hausdach ab und ließen das Tragbett, auf dem der Gelähmte lag, durch eine Öffnung, die sie hindurchgebrochen hatten, hinab.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 2, 5, 'Als Jesus nun ihren Glauben erkannte, sagte er zu dem Gelähmten: »Mein Sohn, deine Sünden sind (dir) vergeben!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 2, 6, 'Es saßen dort aber einige Schriftgelehrte, die machten sich in ihrem Herzen Gedanken:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 2, 7, '»Wie kann dieser so reden? Er lästert ja Gott! Wer kann Sünden vergeben außer Gott allein?«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 2, 8, 'Da nun Jesus in seinem Geiste sogleich erkannte, daß sie so bei sich dachten, sagte er zu ihnen: »Warum denkt ihr so in euren Herzen?');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 2, 9, 'Was ist leichter, zu dem Gelähmten zu sagen: ›Deine Sünden sind (dir) vergeben‹, oder zu sagen: ›Stehe auf, nimm dein Tragbett und gehe umher‹?');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 2, 10, 'Damit ihr aber wißt, daß der Menschensohn Vollmacht hat, Sünden auf Erden zu vergeben« – hierauf sagte er zu dem Gelähmten:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 2, 11, '»Ich sage dir: Stehe auf, nimm dein Bett und gehe heim in dein Haus!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 2, 12, 'Da stand er auf, nahm sogleich das Tragbett und ging vor aller Augen hinaus, so daß alle vor Staunen außer sich gerieten und Gott priesen, indem sie erklärten: »So etwas haben wir noch nie gesehen!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 2, 13, 'Er ging hierauf wieder hinaus an den See, und die ganze Volksmenge kam zu ihm, und er lehrte sie.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 2, 14, 'Im Vorübergehen sah er dann Levi, den Sohn des Alphäus, an der Zollstätte sitzen und sagte zu ihm: »Folge mir nach!« Da stand er auf und folgte ihm nach.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 2, 15, 'Nun begab es sich, als Jesus in Levis Hause zu Tische saß, daß viele Zöllner und Sünder mit Jesus und seinen Jüngern am Mahl teilnahmen; denn es waren ihrer viele, die ihm (beständig) nachfolgten.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 2, 16, 'Als nun die Schriftgelehrten, die zu den Pharisäern gehörten, ihn mit den Zöllnern und Sündern zusammen essen sahen, sagten sie zu seinen Jüngern: »Wie (ist’s nur möglich), daß er mit den Zöllnern und Sündern ißt und trinkt?«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 2, 17, 'Als Jesus das hörte, sagte er zu ihnen: »Die Gesunden haben keinen Arzt nötig, wohl aber die Kranken. Ich bin nicht gekommen, Gerechte zu berufen, sondern Sünder.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 2, 18, 'Die Jünger des Johannes und die Pharisäer fasteten gerade. Da kamen Leute zu Jesus mit der Frage: »Warum fasten die Jünger des Johannes und die Schüler der Pharisäer, während deine Jünger es nicht tun?«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 2, 19, 'Jesus antwortete ihnen: »Können etwa die Hochzeitsgäste fasten, solange der Bräutigam noch bei ihnen weilt? Nein, solange sie den Bräutigam noch bei sich haben, können sie nicht fasten.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 2, 20, 'Es werden aber Tage kommen, wo der Bräutigam ihnen genommen sein wird; dann, an jenem Tage, werden sie fasten. –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 2, 21, 'Niemand setzt ein Stück von ungewalktem Tuch auf ein altes Kleid; sonst reißt der eingesetzte neue Fleck von dem alten Kleide wieder ab, und es entsteht ein noch schlimmerer Riß.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 2, 22, 'Auch füllt niemand neuen Wein in alte Schläuche; sonst sprengt der Wein die Schläuche, und der Wein geht samt den Schläuchen verloren. Nein, neuer Wein gehört in neue Schläuche.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 2, 23, '(Einst) begab es sich, daß Jesus am Sabbat durch die Kornfelder wanderte, und seine Jünger begannen im Dahingehen Ähren abzupflücken.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 2, 24, 'Da sagten die Pharisäer zu ihm: »Sieh, was sie da am Sabbat Unerlaubtes tun!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 2, 25, 'Er antwortete ihnen: »Habt ihr noch niemals gelesen, was David getan hat, als er Mangel litt und ihn samt seinen Begleitern hungerte?');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 2, 26, 'Wie er da ins Gotteshaus ging zur Zeit des Hohenpriesters Abjathar und die Schaubrote aß, die doch niemand außer den Priestern essen darf, und wie er auch seinen Begleitern davon gab?«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 2, 27, 'Dann fuhr er fort: »Der Sabbat ist um des Menschen willen da und nicht der Mensch um des Sabbats willen;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 2, 28, 'somit ist der Menschensohn Herr auch über den Sabbat.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 3, 1, 'Als er dann wieder einmal in eine Synagoge gegangen war, befand sich dort ein Mann, der einen gelähmten Arm hatte;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 3, 2, 'und sie lauerten ihm auf, ob er ihn am Sabbat heilen würde, um dann eine Anklage gegen ihn zu erheben.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 3, 3, 'Da sagte er zu dem Manne, der den gelähmten Arm hatte: »Stehe auf (und tritt vor) in die Mitte!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 3, 4, 'Dann fragte er sie: »Darf man am Sabbat Gutes tun, oder (soll man) Böses tun? Darf man ein Leben retten oder soll man es töten?« Sie aber schwiegen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 3, 5, 'Da blickte er sie ringsum voll Zorn an, betrübt über die Verstocktheit ihres Herzens, und sagte zu dem Manne: »Strecke deinen Arm aus!« Er streckte ihn aus, und sein Arm wurde wiederhergestellt.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 3, 6, 'Da gingen die Pharisäer sogleich hinaus und berieten sich mit den Anhängern des Herodes über ihn, wie sie ihn umbringen könnten.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 3, 7, 'Jesus zog sich dann mit seinen Jüngern an den See zurück, und eine große Volksmenge aus Galiläa begleitete ihn; auch aus Judäa');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 3, 8, 'und Jerusalem, aus Idumäa und dem Ostjordanlande und aus der Gegend von Tyrus und Sidon kamen die Leute auf die Kunde von allen seinen Taten in großen Scharen zu ihm.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 3, 9, 'So befahl er denn seinen Jüngern, ein Boot solle wegen der Volksmenge beständig für ihn bereitgehalten werden, damit man ihn nicht zu arg dränge;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 3, 10, 'denn weil er viele heilte, so suchten alle, die ein Leiden hatten, mit Gewalt an ihn heranzukommen, um ihn anrühren zu können;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 3, 11, 'und sooft die unreinen Geister ihn erblickten, warfen sie sich vor ihm nieder und riefen laut: »Du bist der Sohn Gottes!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 3, 12, 'Er gab ihnen dann allemal die strenge Weisung, sie sollten ihn nicht (als Messias) offenbar machen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 3, 13, 'Da stieg er auf den Berg hinauf und rief die zu sich, die er selbst (bei sich zu haben) wünschte; und sie traten zu ihm heran.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 3, 14, 'So bestellte er denn zwölf [die er auch Apostel nannte]; diese sollten beständig bei ihm sein, und er wollte sie auch aussenden, damit sie (die Heilsbotschaft) verkündigten;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 3, 15, 'sie sollten auch Vollmacht zur Austreibung der bösen Geister haben.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 3, 16, 'So setzte er die Zwölf ein und legte dem Simon den Namen Petrus bei;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 3, 17, 'ferner Jakobus, den Sohn des Zebedäus, und Johannes, den Bruder des Jakobus, denen er den Namen Boanerges, das heißt ›Donnersöhne‹, beilegte;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 3, 18, 'ferner Andreas, Philippus, Bartholomäus, Matthäus, Thomas, Jakobus, den Sohn des Alphäus, Thaddäus, Simon den Kananäer');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 3, 19, 'und Judas Iskariot, denselben, der ihn (später) überantwortet hat.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 3, 20, 'Er ging dann in ein Haus; da sammelte sich wieder eine solche Volksmenge an, daß sie nicht einmal Zeit zum Essen hatten.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 3, 21, 'Als seine Angehörigen Kunde davon erhielten, machten sie sich auf den Weg, um sich seiner zu bemächtigen; denn sie sagten, er sei von Sinnen gekommen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 3, 22, 'Auch die Schriftgelehrten, die von Jerusalem herabgekommen waren, sagten: »Er ist von Beelzebul besessen«, und: »Im Bunde mit dem Obersten der bösen Geister treibt er die Geister aus.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 3, 23, 'Da rief Jesus sie zu sich und redete in Gleichnissen zu ihnen: »Wie kann der Satan den Satan austreiben?');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 3, 24, 'Und wenn ein Reich in sich selbst uneinig ist, so kann ein solches Reich keinen Bestand haben;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 3, 25, 'und wenn ein Haus in sich selbst uneinig ist, so wird ein solches Haus keinen Bestand haben können;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 3, 26, 'und wenn der Satan sich gegen sich selbst erhebt und mit sich selbst in Zwiespalt gerät, so kann er nicht bestehen, sondern es ist zu Ende mit ihm.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 3, 27, 'Niemand kann aber in das Haus des Starken eintreten und ihm sein Rüstzeug rauben, ohne zuvor den Starken gefesselt zu haben: erst dann kann er sein Haus ausplündern.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 3, 28, 'Wahrlich ich sage euch: Alle Sünden werden den Menschenkindern vergeben werden, auch die Lästerungen, so viele sie deren aussprechen mögen;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 3, 29, 'wer sich aber gegen den heiligen Geist der Lästerung schuldig macht, der erlangt in Ewigkeit keine Vergebung, sondern ist einer ewigen Sünde schuldig« –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 3, 30, '(das sagte Jesus) weil sie behaupteten, er sei von einem unreinen Geist besessen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 3, 31, 'Da kamen seine Mutter und seine Brüder; sie blieben draußen stehen, schickten zu ihm und ließen ihn rufen,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 3, 32, 'während gerade eine große Volksmenge um ihn herum saß. Als man ihm nun meldete: »Deine Mutter und deine Brüder [und deine Schwestern] sind draußen und fragen nach dir«,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 3, 33, 'gab er ihnen zur Antwort: »Wer ist meine Mutter, und wer sind meine Brüder?«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 3, 34, 'Und indem er auf die blickte, welche rings im Kreise um ihn saßen, sagte er: »Seht, diese hier sind meine Mutter und meine Brüder!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 3, 35, 'Jeder, der den Willen Gottes tut, der ist mir Bruder und Schwester und Mutter.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 4, 1, 'Und wieder einmal begann er am See zu lehren; und es sammelte sich eine sehr große Volksmenge bei ihm, so daß er in ein Boot stieg und sich darin auf dem See niedersetzte, während das gesamte Volk sich auf dem Lande am Ufer des Sees befand.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 4, 2, 'Da trug er ihnen vielerlei Lehren in Gleichnissen vor und sagte zu ihnen in seiner Belehrung:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 4, 3, '»Hört zu! Seht, der Sämann ging aus, um zu säen;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 4, 4, 'und beim Säen fiel einiges (vom Saatkorn) auf den Weg längshin; da kamen die Vögel und fraßen es auf.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 4, 5, 'Anderes fiel auf felsigen Boden, wo es nicht viel Erdreich hatte und bald aufschoß, weil es nicht tief in den Boden dringen konnte;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 4, 6, 'als dann die Sonne aufgegangen war, wurde es versengt und verdorrte, weil es keine Wurzel (geschlagen) hatte.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 4, 7, 'Wieder anderes fiel unter die Dornen; und die Dornen wuchsen auf und erstickten es, und es brachte keine Frucht.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 4, 8, 'Anderes aber fiel auf den guten Boden und brachte Frucht, indem es aufging und wuchs; und das eine trug dreißigfältig, das andere sechzigfältig, noch anderes hundertfältig.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 4, 9, 'Er schloß mit den Worten: »Wer Ohren hat zu hören, der höre!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 4, 10, 'Als er dann allein war, fragten ihn die, welche samt den Zwölfen bei ihm waren, um das Gleichnis.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 4, 11, 'Da antwortete er ihnen: »Euch ist es gegeben, das Geheimnis des Reiches Gottes (zu erkennen); den Außenstehenden aber wird alles nur in Gleichnissen zuteil,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 4, 12, '›damit sie immerfort sehen und doch nicht wahrnehmen, und immerfort hören und doch kein Verständnis haben, auf daß sie sich nicht bekehren und ihnen nicht Vergebung zuteil werde‹.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 4, 13, 'Dann fuhr er fort: »Ihr versteht dieses Gleichnis nicht? Ja, wie wollt ihr da die Gleichnisse überhaupt verstehen?«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 4, 14, '»Der Sämann sät das Wort.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 4, 15, 'Die aber, bei denen der Same auf den Weg längshin fällt, sind solche: da wird das Wort (wohl) gesät, doch wenn sie es gehört haben, kommt sogleich der Satan und nimmt das Wort weg, das in sie gesät war.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 4, 16, 'Ebenso die, bei denen der Same auf felsiges Land fällt, das sind solche: wenn sie das Wort hören, nehmen sie es für den Augenblick mit Freuden an;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 4, 17, 'doch sie haben keine Wurzel in sich, sondern sind Kinder des Augenblicks; wenn nachher Drangsal oder Verfolgung um des Wortes willen kommt, werden sie sogleich (am Glauben) irre.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 4, 18, 'Bei anderen fällt der Same unter die Dornen; das sind solche, die das Wort wohl gehört haben,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 4, 19, 'doch die weltlichen Sorgen und der Betrug des Reichtums und die sonstigen Gelüste dringen in sie ein und ersticken das Wort: so bleibt es ohne Frucht.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 4, 20, 'Wo aber auf den guten Boden gesät ist, das sind solche, die das Wort hören und aufnehmen und Frucht bringen, dreißigfältig und sechzigfältig und hundertfältig.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 4, 21, 'Weiter sagte er zu ihnen: »Kommt etwa die Lampe (in das Zimmer), damit man sie unter den Scheffel oder unter das Bett stelle? Nein, damit sie auf den Leuchter gestellt werde.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 4, 22, 'Denn es gibt nichts Verborgenes, außer damit es offenbart werde, und nichts ist in Geheimnis gehüllt worden, außer damit es ans Tageslicht komme.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 4, 23, 'Wer Ohren hat zu hören, der höre!« –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 4, 24, 'Dann fuhr er fort: »Seid achtsam auf das, was ihr hört! Mit demselben Maß, mit dem ihr meßt, wird euch wieder gemessen werden, und es wird euch noch hinzugetan werden.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 4, 25, 'Denn wer da hat, dem wird noch dazugegeben werden; und wer nicht hat, dem wird auch das genommen werden, was er hat.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 4, 26, 'Er fuhr dann fort: »Mit dem Reiche Gottes verhält es sich so, wie wenn jemand den Samen auf das Land wirft');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 4, 27, 'und dann schläft und aufsteht in der Nacht und bei Tag; und der Same sproßt und wächst hoch, ohne daß er selbst etwas davon weiß.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 4, 28, 'Von selbst bringt die Erde Frucht hervor, zuerst die grünen Halme, dann die Ähren, dann den vollen Weizen in den Ähren.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 4, 29, 'Wenn aber die Frucht es zuläßt, legt er sofort die Sichel an; denn die Ernte ist da.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 4, 30, 'Weiter sagte er: »Wie sollen wir ein Bild vom Reiche Gottes entwerfen oder in welchem Gleichnis es darstellen?');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 4, 31, 'Es gleicht einem Senfkorn, das, wenn man es in den Erdboden sät, kleiner ist als alle anderen Samenarten auf der Erde;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 4, 32, 'doch wenn es gesät ist, geht es auf und wird größer als alle anderen Gartengewächse und treibt große Zweige, so daß unter seinem Schatten die Vögel des Himmels nisten können.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 4, 33, 'In vielen derartigen Gleichnissen verkündete Jesus ihnen das Wort, je nach dem sie es zu verstehen vermochten;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 4, 34, 'aber ohne Gleichnis redete er nicht zu ihnen; wenn er dann mit seinen Jüngern allein war, so gab er ihnen die Auslegung von allem.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 4, 35, 'Er sagte dann zu ihnen an jenem Tage, als es Abend geworden war: »Wir wollen ans andere Ufer (des Sees) hinüberfahren!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 4, 36, 'So ließen sie denn die Volksmenge gehen und nahmen ihn, wie er war, im Boote mit; doch auch noch andere Boote begleiteten ihn.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 4, 37, 'Da erhob sich ein gewaltiger Sturmwind, und die Wellen schlugen in das Boot, so daß das Boot sich schon mit Wasser zu füllen begann;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 4, 38, 'er selbst aber lag am hinteren Teil des Bootes und schlief auf dem Kissen. Sie weckten ihn nun und sagten zu ihm: »Meister, liegt dir nichts daran, daß wir untergehen?«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 4, 39, 'Da stand er auf, bedrohte den Wind und gebot dem See: »Schweige! Werde still!« Da legte sich der Wind, und es trat völlige Windstille ein.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 4, 40, 'Hierauf sagte er zu ihnen: »Was seid ihr so furchtsam? Habt ihr immer noch keinen Glauben?«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 4, 41, 'Da gerieten sie in große Furcht und sagten zueinander: »Wer ist denn dieser, daß auch der Wind und der See ihm gehorsam sind?«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 5, 1, 'Sie kamen dann an das jenseitige Ufer des Sees in das Gebiet der Gerasener.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 5, 2, 'Als er dort aus dem Boot gestiegen war, lief ihm sogleich von den Gräbern her ein Mann entgegen, der von einem unreinen Geist besessen war.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 5, 3, 'Er hatte seinen Aufenthalt in den Gräbern, und niemand vermochte ihn zu fesseln, auch nicht mit einer Kette;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 5, 4, 'denn man hatte ihn schon oft mit Fußfesseln und Ketten gebunden, aber er hatte die Ketten immer wieder zerrissen und die Fußfesseln zerrieben, und niemand war stark genug, ihn zu überwältigen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 5, 5, 'Er hielt sich allezeit, bei Tag und bei Nacht, in den Gräbern und auf den Bergen auf, schrie laut und zerschlug sich mit Steinen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 5, 6, 'Als er nun Jesus von weitem sah, kam er herzugelaufen, warf sich vor ihm nieder');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 5, 7, 'und stieß laut schreiend die Worte aus: »Was willst du von mir, Jesus, du Sohn Gottes, des Höchsten? Ich beschwöre dich bei Gott: quäle mich nicht!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 5, 8, 'Jesus war nämlich im Begriff, ihm zu gebieten: »Fahre aus, du unreiner Geist, aus dem Manne!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 5, 9, 'Da fragte Jesus ihn: »Wie heißt du?« Er antwortete ihm: »Legion heiße ich, denn wir sind unser viele.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 5, 10, 'Dann bat er ihn inständig, er möchte sie nicht aus der Gegend verweisen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 5, 11, 'Nun befand sich dort am Berge eine große Herde Schweine auf der Weide.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 5, 12, 'Da baten sie ihn: »Schicke uns in die Schweine! Laß uns in sie fahren!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 5, 13, 'Das erlaubte Jesus ihnen auch, und so fuhren denn die unreinen Geister aus und fuhren in die Schweine hinein; und die Herde stürmte den Abhang hinab in den See hinein, etwa zweitausend Tiere, und sie ertranken im See.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 5, 14, 'Ihre Hirten aber ergriffen die Flucht und berichteten den Vorfall in der Stadt und in den Gehöften; da kamen die Leute, um zu sehen, was geschehen war.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 5, 15, 'Als sie nun zu Jesus gekommen waren, sahen sie den (früher) Besessenen ruhig dasitzen, bekleidet und ganz vernünftig, ihn, der die Legion (unreiner Geister) in sich gehabt hatte, und sie gerieten darüber in Furcht.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 5, 16, 'Die Augenzeugen erzählten ihnen nun, was mit dem Besessenen vorgegangen war, und auch die Begebenheit mit den Schweinen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 5, 17, 'Da verlegten sie sich aufs Bitten, er möchte ihr Gebiet verlassen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 5, 18, 'Als er dann ins Boot steigen wollte, bat ihn der (früher) Besessene, bei ihm bleiben zu dürfen;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 5, 19, 'doch Jesus gestattete es ihm nicht, sondern sagte zu ihm: »Gehe heim in dein Haus zu deinen Angehörigen und berichte ihnen, wie Großes der Herr an dir getan und wie er sich deiner erbarmt hat!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 5, 20, 'Da ging er weg und begann in der Landschaft der Zehn-Städte zu verkündigen, wie Großes Jesus an ihm getan hatte; und alle verwunderten sich darüber.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 5, 21, 'Als Jesus dann im Boot wieder an das jenseitige Ufer hinübergefahren war, sammelte sich eine große Volksmenge bei ihm, während er sich noch am See befand.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 5, 22, 'Da kam einer von den Vorstehern der Synagoge namens Jairus, und als er Jesus erblickte, warf er sich vor ihm nieder');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 5, 23, 'und bat ihn inständig mit den Worten: »Mein Töchterlein ist todkrank; komm doch und lege ihr die Hände auf, damit sie gerettet wird und am Leben bleibt!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 5, 24, 'Da ging Jesus mit ihm; es folgte ihm aber eine große Volksmenge und umdrängte ihn.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 5, 25, 'Nun war da eine Frau, die schon zwölf Jahre lang am Blutfluß gelitten');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 5, 26, 'und mit vielen Ärzten viel durchgemacht und ihr ganzes Vermögen dabei zugesetzt hatte, ohne Nutzen davon gehabt zu haben – es war vielmehr immer noch schlimmer mit ihr geworden –;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 5, 27, 'die hatte von Jesus gehört und kam nun in der Volksmenge von hinten herzu und faßte seinen Rock;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 5, 28, 'sie dachte nämlich: »Wenn ich auch nur seine Kleider anfasse, so wird mir geholfen sein.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 5, 29, 'Und sogleich hörte ihr Blutfluß auf, und sie spürte in ihrem Körper, daß sie von ihrem Leiden geheilt war.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 5, 30, 'Da nun auch Jesus sogleich die Empfindung in sich hatte, daß die Heilungskraft von ihm ausgegangen war, wandte er sich in der Volksmenge um und fragte: »Wer hat meine Kleider angefaßt?«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 5, 31, 'Da sagten seine Jünger zu ihm: »Du siehst doch, wie sehr die Volksmenge dich umdrängt, und da fragst du: ›Wer hat mich angefaßt?‹«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 5, 32, 'Doch er blickte rings um sich nach der, die es getan hatte.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 5, 33, 'Da kam die Frau voller Angst und zitternd herbei, weil sie wohl wußte, was mit ihr vorgegangen war, warf sich vor ihm nieder und bekannte ihm die ganze Wahrheit.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 5, 34, 'Er aber sagte zu ihr: »Meine Tochter, dein Glaube hat dich gerettet: gehe hin in Frieden und sei von deinem Leiden geheilt!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 5, 35, 'Während er noch redete, kamen Leute aus dem Hause des Synagogenvorstehers mit der Meldung: »Deine Tochter ist gestorben: was bemühst du den Meister noch?«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 5, 36, 'Jesus aber ließ die Nachricht, die da gemeldet wurde, unbeachtet und sagte zu dem Synagogenvorsteher: »Fürchte dich nicht, glaube nur!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 5, 37, 'Und er ließ niemand mit sich gehen außer Petrus, Jakobus und Johannes, den Bruders des Jakobus.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 5, 38, 'So kamen sie zum Hause des Synagogenvorstehers, wo er das Getümmel wahrnahm und wie sie weinten und laut wehklagten.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 5, 39, 'Als er dann eingetreten war, sagte er zu den Leuten: »Wozu lärmt und weint ihr? Das Kind ist nicht tot, sondern schläft nur!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 5, 40, 'Da verlachten sie ihn. Er aber entfernte alle aus dem Hause, nahm nur den Vater des Kindes nebst der Mutter und seine Jünger, die ihn begleiteten, mit sich und ging (in das Zimmer) hinein, wo das Kind lag.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 5, 41, 'Dann faßte er das Kind bei der Hand und sagte zu ihm: »Talitha kumi!«, was übersetzt heißt: »Mädchen, ich sage dir: stehe auf!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 5, 42, 'Da stand das Mädchen sogleich auf und ging umher; denn sie war zwölf Jahre alt. Da gerieten sie sofort vor Staunen ganz außer sich.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 5, 43, 'Er gebot ihnen dann ernstlich, niemand solle etwas von dem Geschehenen erfahren, und ordnete an, man möge ihr zu essen geben.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 6, 1, 'Er zog dann von dort weiter und kam in seine Vaterstadt (Nazareth), und seine Jünger begleiteten ihn.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 6, 2, 'Als nun der Sabbat gekommen war, fing er an, in der Synagoge zu lehren; und die vielen, die ihm zuhörten, gerieten in Staunen und sagten: »Woher hat er das? Und was ist das für eine Weisheit, die diesem verliehen ist? Und solche Wundertaten geschehen durch seine Hände!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 6, 3, 'Ist dieser nicht der Zimmermann, der Sohn der Maria und der Bruder des Jakobus, des Joses, des Judas und des Simon? Und leben nicht auch seine Schwestern bei uns?« So wurden sie irre an ihm.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 6, 4, 'Da sagte Jesus zu ihnen: »Ein Prophet gilt nirgends weniger als in seiner Vaterstadt und bei seinen Verwandten und in seiner Familie.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 6, 5, 'Er konnte dort auch kein Wunder vollbringen, außer daß er einige Kranke durch Handauflegen heilte.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 6, 6, 'Und er verwunderte sich über ihren Unglauben. Er zog dann in den umliegenden Ortschaften umher und lehrte dort.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 6, 7, 'Darauf rief er die Zwölf zu sich und begann sie paarweise auszusenden; dabei gab er ihnen Macht über die unreinen Geister');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 6, 8, 'und gebot ihnen, nichts auf den Weg mitzunehmen als nur einen Stock, kein Brot, keinen Ranzen und kein Geld im Gürtel;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 6, 9, 'jedoch Sandalen sollten sie sich unterbinden, aber nicht zwei Röcke anziehen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 6, 10, 'Weiter gab er ihnen die Weisung: »Wo ihr in ein Haus eingetreten seid, da bleibt, bis ihr von dort weiterzieht;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 6, 11, 'und wenn ein Ort euch nicht aufnimmt und man euch nicht hören will, so geht von dort weg und schüttelt den Staub von euren Fußsohlen ab zum Zeugnis für sie!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 6, 12, 'So machten sie sich denn auf den Weg und predigten, man solle Buße tun;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 6, 13, 'sie trieben auch viele böse Geister aus, salbten viele Kranke mit Öl und heilten sie.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 6, 14, 'Auch der König Herodes hörte davon; denn sein Name war bekannt geworden, und man sagte: »Johannes der Täufer ist von den Toten auferweckt worden, darum sind die Wunderkräfte in ihm wirksam.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 6, 15, 'Andere aber sagten, er sei Elia; noch andere behaupteten, er sei ein Prophet wie einer der (alten) Propheten.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 6, 16, 'Als aber Herodes davon hörte, sagte er: »Johannes, den ich habe enthaupten lassen, der ist wieder auferweckt worden.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 6, 17, 'Eben dieser Herodes nämlich hatte (Diener) ausgesandt und Johannes festnehmen und ihn gefesselt ins Gefängnis werfen lassen um der Herodias willen, der Gattin seines Bruders Philippus, weil er sie geheiratet hatte;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 6, 18, 'denn Johannes hatte dem Herodes vorgehalten: »Du darfst die Frau deines Bruders nicht (zur Frau) haben.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 6, 19, 'Das trug Herodias ihm nach und hätte ihn am liebsten ums Leben gebracht, vermochte es aber nicht;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 6, 20, 'denn Herodes hatte Scheu vor Johannes, weil er ihn als einen gerechten und heiligen Mann kannte, und er nahm ihn in seinen Schutz; und oftmals, wenn er ihn gehört hatte, war er schwer betroffen, hörte ihn aber dennoch gern.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 6, 21, 'Da kam ein (für Herodias) gelegener Tag, als nämlich Herodes an seinem Geburtstage seinen Würdenträgern und Heeresobersten sowie den vornehmsten Männern von Galiläa ein Festmahl veranstaltete.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 6, 22, 'Als dabei die Tochter eben jener Herodias (in den Saal) eintrat und einen Tanz aufführte, gefiel sie dem Herodes und seinen Tischgästen wohl. Da sagte der König zu dem Mädchen: »Erbitte dir von mir, was du willst: ich will es dir geben!«,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 6, 23, 'und er schwur ihr: »Was du dir auch von mir erbitten magst, das will ich dir geben bis zur Hälfte meines Reiches!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 6, 24, 'Da ging sie hinaus und fragte ihre Mutter: »Was soll ich mir erbitten?« Die antwortete: »Den Kopf Johannes des Täufers!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 6, 25, 'Sogleich ging sie in Eile zum König hinein und sprach die Bitte aus: »Ich möchte, du gäbest mir gleich jetzt auf einer Schüssel den Kopf Johannes des Täufers!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 6, 26, 'Obgleich nun der König sehr betrübt darüber wurde, mochte er sie doch mit Rücksicht auf seine Eide und auf seine Tischgäste keine Fehlbitte tun lassen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 6, 27, 'So schickte denn der König sogleich einen von seinen Leibwächtern ab mit dem Befehl, den Kopf des Johannes zu bringen. Der ging hin, enthauptete ihn im Gefängnis,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 6, 28, 'brachte seinen Kopf auf einer Schüssel und gab ihn dem Mädchen, und das Mädchen gab ihn seiner Mutter.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 6, 29, 'Als die Jünger des Johannes Kunde davon erhielten, kamen sie, nahmen seinen Leichnam und bestatteten ihn in einem Grabe.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 6, 30, 'Die Apostel versammelten sich dann wieder bei Jesus und berichteten ihm alles, was sie getan und was sie gelehrt hatten.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 6, 31, 'Da sagte er zu ihnen: »Kommt ihr für euch allein (mit mir) abseits an einen einsamen Ort und ruht dort ein wenig aus!« Denn die Zahl der Leute, die da kamen und gingen, war groß, so daß sie nicht einmal Zeit zum Essen hatten.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 6, 32, 'So fuhren sie denn im Boot in eine einsame Gegend, um für sich allein zu sein;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 6, 33, 'doch man hatte sie abfahren sehen, und viele hatten ihre Absicht gemerkt; sie eilten daher aus allen Ortschaften zu Fuß dort zusammen und kamen noch vor ihnen an.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 6, 34, 'Als Jesus nun (aus dem Boote) ausstieg und eine große Menge Volks versammelt sah, ergriff ihn tiefes Mitleid mit ihnen, denn sie waren wie Schafe, die keinen Hirten haben; und er fing an, sie vieles zu lehren.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 6, 35, 'Als dann die Zeit schon weit vorgerückt war, traten seine Jünger zu ihm und sagten: »Die Gegend hier ist öde und die Zeit schon weit vorgerückt;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 6, 36, 'laß die Leute ziehen, damit sie in die umliegenden Gehöfte und in die Ortschaften gehen und sich dort etwas zu essen kaufen können.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 6, 37, 'Er aber antwortete ihnen: »Gebt ihr ihnen zu essen!« Da sagten sie zu ihm: »Sollen wir hingehen und für zweihundert Denar Brot kaufen, um ihnen zu essen zu geben?«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 6, 38, 'Er aber antwortete ihnen: »Wie viele Brote habt ihr? Geht hin, seht nach!« Als sie nun nachgesehen hatten, meldeten sie ihm: »Fünf (Brote) und zwei Fische.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 6, 39, 'Da gab er ihnen die Weisung, sie sollten alle sich zu einzelnen Tischgenossenschaften auf dem grünen Rasen lagern;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 6, 40, 'so ließen sie sich denn gruppenweise zu hundert und zu fünfzig nieder.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 6, 41, 'Hierauf nahm er die fünf Brote und die beiden Fische, blickte zum Himmel auf, sprach den Lobpreis (Gottes), brach die Brote und gab sie seinen Jüngern, damit diese sie dem Volk vorlegten; auch die beiden Fische teilte er für alle aus.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 6, 42, 'Und sie aßen alle und wurden satt;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 6, 43, 'dann hob man an Brocken noch zwölf Körbe voll (vom Boden) auf, dazu auch Überbleibsel von den Fischen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 6, 44, 'Und die Zahl derer, die von den Broten gegessen hatten, betrug fünftausend Männer.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 6, 45, 'Und sogleich nötigte er seine Jünger, in das Boot zu steigen und ihm an das jenseitige Ufer nach Bethsaida vorauszufahren, während er selbst die Volksmenge entlassen wollte.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 6, 46, 'Nachdem er sie dann verabschiedet hatte, ging er auf den Berg hinauf, um zu beten.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 6, 47, 'Als es so Abend geworden war, befand sich das Boot mitten auf dem See, während er selbst allein noch auf dem Lande war.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 6, 48, 'Als er nun sah, wie sie sich (auf der Fahrt) beim Rudern abmühten – denn der Wind stand ihnen entgegen –, kam er um die vierte Nachtwache auf sie zu, indem er auf dem See dahinging, und wollte an ihnen vorübergehen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 6, 49, 'Als sie ihn aber so auf dem See wandeln sahen, dachten sie, es sei ein Gespenst, und schrien auf;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 6, 50, 'denn alle sahen ihn und waren in Angst geraten. Er aber redete sie sogleich an und sagte zu ihnen: »Seid getrost, ich bin’s: fürchtet euch nicht!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 6, 51, 'Er stieg darauf zu ihnen ins Boot: da legte sich der Wind. Nun gerieten sie vollends vor Erstaunen ganz außer sich;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 6, 52, 'denn bei der Brotspeisung war ihnen noch kein Verständnis gekommen, sondern ihr Herz war verhärtet.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 6, 53, 'Als sie dann ans Land hinübergefahren waren, kamen sie nach Gennesaret und legten dort an.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 6, 54, 'Als sie aus dem Boot gestiegen waren, erkannten die Leute dort ihn sogleich,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 6, 55, 'liefen in jener ganzen Gegend umher und begannen die Kranken auf den Bahren umherzutragen (und dahin zu bringen), wo er, dem Vernehmen nach, sich gerade aufhielt.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 6, 56, 'Und wo er in Dörfern oder Städten oder Gehöften einkehrte, legten sie die Kranken auf den freien Plätzen nieder und baten ihn, daß sie auch nur die Quaste seines Rockes anfassen dürften; und alle, die ihn anfaßten, wurden gesund.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 7, 1, 'Da versammelten sich bei ihm die Pharisäer und einige Schriftgelehrte, die von Jerusalem gekommen waren;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 7, 2, 'und als sie einige seiner Jünger die Brote mit unreinen, das heißt ungewaschenen Händen zu sich nehmen sahen –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 7, 3, 'die Pharisäer nämlich und die Juden überhaupt essen nur, wenn sie sich die Hände mit der Faust gewaschen haben, weil sie an den von den Alten überlieferten Satzungen festhalten;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 7, 4, 'und auch wenn sie vom Markt heimkommen, essen sie nicht, ohne sich zunächst (die Hände) abgespült zu haben; und noch viele andere Vorschriften gibt es, deren strenge Beobachtung sie überkommen haben, z.B. das Eintauchen von Bechern, Krügen und Kupfergeschirr –,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 7, 5, 'da fragten ihn die Pharisäer und Schriftgelehrten: »Warum halten sich deine Jünger in ihrer Lebensweise nicht an die Überlieferung der Alten, sondern nehmen die Speisen mit unreinen Händen zu sich?«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 7, 6, 'Er antwortete ihnen: »Treffend hat Jesaja von euch Heuchlern geweissagt, wie geschrieben steht: ›Dieses Volk ehrt mich (nur) mit den Lippen, ihr Herz aber ist weit entfernt von mir;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 7, 7, 'doch vergeblich verehren sie mich, weil sie Menschengebote zu ihren Lehren machen.‹');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 7, 8, 'Das Gebot Gottes laßt ihr außer acht und haltet an den euch überlieferten Satzungen der Menschen fest [ihr nehmt Abwaschungen von Krügen und Bechern vor und tut Ähnliches derart noch vielfach].«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 7, 9, 'Dann fuhr er fort: »Trefflich versteht ihr es, das Gebot Gottes aufzuheben, um die euch überlieferten Satzungen festzuhalten.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 7, 10, 'Mose hat z.B. geboten: ›Ehre deinen Vater und deine Mutter‹ und: ›Wer den Vater oder die Mutter schmäht, soll des Todes sterben.‹');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 7, 11, 'Ihr aber sagt: ›Wenn jemand zu seinem Vater oder zu seiner Mutter sagt: Korban, das heißt: eine Gabe für den Tempelschatz soll das sein, was dir sonst als Unterstützung von mir zugute gekommen wäre‹,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 7, 12, 'so laßt ihr ihn für seinen Vater oder seine Mutter nichts mehr tun');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 7, 13, 'und hebt damit das Wort Gottes durch eure Überlieferung auf, die ihr weitergegeben habt; und Ähnliches derart tut ihr vielfach.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 7, 14, 'Nachdem er dann die Volksmenge wieder herbeigerufen hatte, sagte er zu ihnen: »Hört mir alle zu und sucht es zu verstehen!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 7, 15, 'Nichts geht von außen in den Menschen hinein, was ihn zu verunreinigen vermag, sondern was aus dem Menschen herauskommt, das ist es, was den Menschen verunreinigt.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 7, 16, '[Wer Ohren hat zu hören, der höre!]«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 7, 17, 'Als er dann vom Volk weggegangen und ins Haus gekommen war, befragten ihn seine Jünger über das Gleichnis.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 7, 18, 'Da sagte er zu ihnen: »So seid auch ihr immer noch ohne Verständnis? Begreift ihr nicht, daß alles, was von außen her in den Menschen hineingeht, ihn nicht zu verunreinigen vermag,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 7, 19, 'weil es ihm nicht ins Herz hineingeht, sondern in den Leib und auf dem natürlichen Wege, der alle Speisen reinigt, wieder ausgeschieden wird?«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 7, 20, 'Dann fuhr er fort: »Was dagegen aus dem Menschen herauskommt, das verunreinigt den Menschen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 7, 21, 'Denn von innen her, aus dem Herzen der Menschen, kommen die bösen Gedanken hervor: Unzucht, Diebstahl, Mordtaten,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 7, 22, 'Ehebruch, Habsucht, Bosheit, Arglist, Ausschweifung, Scheelsucht, Lästerung, Hochmut, Unverstand.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 7, 23, 'Alles Böse dieser Art kommt von innen heraus und verunreinigt den Menschen.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 7, 24, 'Er brach dann von dort auf und begab sich in das Gebiet von Tyrus. Als er dort in einem Hause Aufnahme gefunden hatte, wünschte er, daß niemand es erführe; doch er konnte nicht verborgen bleiben,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 7, 25, 'sondern alsbald hörte eine Frau von ihm, deren Töchterlein von einem unreinen Geist besessen war; sie kam also und warf sich vor ihm nieder –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 7, 26, 'die Frau war aber eine Griechin, ihrer Herkunft nach eine Syrophönizierin – und bat ihn, er möchte den bösen Geist aus ihrer Tochter austreiben.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 7, 27, 'Da entgegnete er ihr: »Laß zuerst die Kinder satt werden; denn es ist nicht recht, das den Kindern zukommende Brot zu nehmen und es den Hündlein hinzuwerfen.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 7, 28, 'Sie aber gab ihm zur Antwort: »O doch, Herr! Auch die Hündlein bekommen ja unter dem Tisch von den Brocken der Kinder zu essen.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 7, 29, 'Da sagte er zu ihr: »Um dieses Wortes willen gehe heim: der böse Geist ist aus deiner Tochter ausgefahren.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 7, 30, 'Als sie nun in ihr Haus zurückkam, traf sie ihr Kind an, wie es ruhig auf dem Bett lag, und der böse Geist war ausgefahren.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 7, 31, 'Nachdem er dann das Gebiet von Tyrus wieder verlassen hatte, kam er über Sidon an den Galiläischen See (und zwar) mitten in das Gebiet der Zehn-Städte.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 7, 32, 'Da brachten sie einen Tauben zu ihm, der kaum lallen konnte, und baten ihn, er möchte ihm die Hand auflegen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 7, 33, 'So nahm er ihn denn von der Volksmenge weg abseits, legte ihm, als er mit ihm allein war, seine Finger in die Ohren, benetzte sie mit Speichel und berührte ihm die Zunge;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 7, 34, 'nachdem er dann zum Himmel aufgeblickt hatte, seufzte er und sagte zu ihm: »Effatha!«, das heißt (übersetzt) »Tu dich auf!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 7, 35, 'Da taten sich seine Ohren auf, die Gebundenheit seiner Zunge löste sich, und er redete richtig.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 7, 36, 'Jesus gebot ihnen dann ernstlich, daß sie niemand etwas davon sagen sollten; aber je mehr er es ihnen gebot, um so mehr und um so eifriger verbreiteten sie die Kunde;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 7, 37, 'und sie gerieten vor Staunen ganz außer sich und sagten: »Er hat alles wohl gemacht, auch die Tauben macht er hören und die Sprachlosen reden!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 8, 1, 'Als in jenen Tagen wieder einmal eine große Volksmenge zugegen war und sie nichts zu essen hatten, rief Jesus seine Jünger herbei und sagte zu ihnen:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 8, 2, '»Mich jammert des Volkes; denn sie halten nun schon drei Tage bei mir aus und haben nichts zu essen;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 8, 3, 'und wenn ich sie nach Hause gehen lasse, ohne daß sie gegessen haben, so werden sie unterwegs verschmachten; sie sind ja auch zum Teil von weit her gekommen.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 8, 4, 'Da erwiderten ihm seine Jünger: »Woher sollte man diese hier in einer so öden Gegend mit Brot sättigen können?«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 8, 5, 'Er fragte sie: »Wie viele Brote habt ihr?« Sie antworteten: »Sieben.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 8, 6, 'Da gebot er der Volksmenge, sich auf der Erde zu lagern; dann nahm er die sieben Brote, sprach den Lobpreis (Gottes), brach die Brote und gab (die Stücke) seinen Jüngern, damit diese sie austeilten; die legten sie dann der Volksmenge vor.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 8, 7, 'Sie hatten auch noch ein paar kleine Fische; er sprach den Segen über sie und ließ auch diese austeilen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 8, 8, 'So aßen sie denn und wurden satt; dann sammelten sie die übriggebliebenen Stücke, sieben Körbe voll.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 8, 9, 'Es waren aber gegen viertausend Menschen, (die gegessen hatten und) die er nun gehen ließ.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 8, 10, 'Er stieg hierauf sogleich mit seinen Jüngern in das Boot ein und gelangte in die Gegend von Dalmanutha.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 8, 11, 'Da kamen die Pharisäer zu ihm hinaus, begannen mit ihm zu verhandeln und verlangten von ihm ein Wunderzeichen vom Himmel her, weil sie ihn auf die Probe stellen wollten.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 8, 12, 'Da seufzte er in seinem Geiste tief auf und sagte: »Wozu verlangt dieses Geschlecht ein Zeichen? Wahrlich ich sage euch: Nimmermehr wird diesem Geschlecht ein Zeichen gegeben werden!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 8, 13, 'Mit diesen Worten ließ er sie stehen, stieg wieder in das Boot ein und fuhr an das jenseitige Ufer hinüber.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 8, 14, 'Sie hatten aber vergessen, Brote mitzunehmen, und hatten nur ein einziges Brot bei sich im Boot.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 8, 15, 'Da sagte er warnend zu ihnen: »Gebt acht, hütet euch vor dem Sauerteig der Pharisäer und vor dem Sauerteig des Herodes!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 8, 16, 'Da erwogen sie im Gespräch miteinander: »(Das sagt er deshalb) weil wir keine Brote haben.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 8, 17, 'Als Jesus das merkte, sagte er zu ihnen: »Was macht ihr euch Gedanken darüber, daß ihr keine Brote (mitgenommen) habt? Begreift und versteht ihr denn immer noch nicht? Habt ihr auch jetzt noch ein Herz, das verhärtet ist?');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 8, 18, 'Ihr habt Augen und seht nicht, habt Ohren und hört nicht? Denkt ihr denn nicht daran:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 8, 19, 'Als ich die fünf Brote für die Fünftausend brach, wie viele Körbe voll Brocken habt ihr da aufgelesen?« Sie antworteten ihm: »Zwölf.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 8, 20, '»Und damals als ich die sieben (Brote) für die Viertausend (brach), wie viele Körbchen habt ihr da mit den Brocken gefüllt, die ihr aufgelesen hattet?« Sie antworteten: »Sieben.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 8, 21, 'Da sagte er zu ihnen: »Habt ihr immer noch kein Verständnis?«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 8, 22, 'Sie kamen dann nach Bethsaida. Dort brachte man einen Blinden zu ihm und bat ihn, er möchte ihn anrühren.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 8, 23, 'Er faßte denn auch den Blinden bei der Hand und führte ihn vor das Dorf hinaus; dann tat er ihm Speichel in die Augen, legte ihm die Hände auf und fragte ihn, ob er etwas sähe.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 8, 24, 'Jener schlug die Augen auf und antwortete: »Ich nehme die Menschen wahr: sie kommen mir bei ihrem Umhergehen wie Bäume vor.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 8, 25, 'Darauf legte er ihm die Hände nochmals auf die Augen; da konnte er deutlich sehen und war geheilt, so daß er auch in der Ferne alles scharf sah.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 8, 26, 'Nun schickte Jesus ihn heim in sein Haus mit der Weisung: »Gehe auch nicht (erst wieder) in das Dorf hinein!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 8, 27, 'Jesus zog dann mit seinen Jüngern weiter in die Ortschaften bei Cäsarea Philippi. Unterwegs richtete er an seine Jünger die Frage: »Für wen halten mich die Leute?«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 8, 28, 'Sie antworteten ihm: »Für Johannes den Täufer, andere für Elia, noch andere für sonst einen von den (alten) Propheten.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 8, 29, 'Nun fragte er sie weiter: »Ihr aber – für wen haltet ihr mich?« Petrus gab ihm zur Antwort: »Du bist Christus!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 8, 30, 'Da gab er ihnen die strenge Weisung, sie sollten das zu niemand von ihm sagen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 8, 31, 'Hierauf begann er sie darauf hinzuweisen, der Menschensohn müsse vieles leiden und von den Ältesten, den Hohenpriestern und den Schriftgelehrten verworfen und getötet werden und nach drei Tagen auferstehen;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 8, 32, 'und er sprach das ganz offen aus. Da nahm Petrus ihn beiseite und begann auf ihn einzureden;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 8, 33, 'er aber wandte sich um, blickte seine Jünger an und wies Petrus scharf ab mit den Worten: »Hinweg von mir, Satan! (Tritt) hinter mich! Deine Gedanken sind nicht die Gedanken Gottes, sondern sind Menschengedanken.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 8, 34, 'Dann rief er die Volksmenge samt seinen Jüngern herbei und sagte zu ihnen: »Will jemand mir nachfolgen, so verleugne er sich selbst und nehme sein Kreuz auf sich, und so werde er mein Nachfolger.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 8, 35, 'Denn wer sein Leben retten will, der wird es verlieren; wer aber sein Leben um meinetwillen und um der Heilsbotschaft willen verliert, der wird es retten.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 8, 36, 'Denn was hülfe es einem Menschen, wenn er die ganze Welt gewönne und doch sein Leben einbüßte?');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 8, 37, 'Denn was könnte ein Mensch als Gegenwert für sein Leben geben?');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 8, 38, 'Denn wer sich meiner und meiner Worte unter diesem ehebrecherischen und sündigen Geschlecht schämt, dessen wird sich auch der Menschensohn schämen, wenn er in der Herrlichkeit seines Vaters mit den heiligen Engeln kommt.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 9, 1, 'Dann fuhr er fort: »Wahrlich ich sage euch: Einige von denen, die hier stehen, werden den Tod nicht schmecken, bis sie das Reich Gottes mit Macht haben kommen sehen.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 9, 2, 'Sechs Tage später nahm Jesus den Petrus, Jakobus und Johannes mit sich und führte sie abseits auf einen hohen Berg hinauf, wo sie allein waren. Da wurde er vor ihren Augen verwandelt,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 9, 3, 'und seine Kleider wurden glänzend, ganz weiß, wie sie kein Walker auf Erden so weiß machen kann.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 9, 4, 'Und es erschien ihnen Elia mit Mose; die besprachen sich mit Jesus.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 9, 5, 'Da sagte Petrus zu Jesus: »Rabbi, hier sind wir gut aufgehoben! Wir wollen hier drei Hütten bauen, eine für dich, eine für Mose und eine für Elia« –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 9, 6, 'er wußte nämlich nicht, was er sagen sollte; in solche Furcht waren sie geraten.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 9, 7, 'Dann kam eine Wolke, die sie überschattete, und eine Stimme erscholl aus der Wolke: »Dieser ist mein geliebter Sohn: höret auf ihn!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 9, 8, 'Und mit einemmal, als sie um sich blickten, sahen sie niemand mehr bei sich als Jesus allein.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 9, 9, 'Als sie dann von dem Berge hinabstiegen, gebot er ihnen, sie sollten von dem, was sie gesehen hätten, niemand etwas erzählen, ehe nicht der Menschensohn von den Toten auferstanden wäre.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 9, 10, 'Dies Gebot hielten sie dann auch fest, besprachen sich jedoch untereinander darüber, was wohl mit der Auferstehung von den Toten gemeint sei.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 9, 11, 'Hierauf befragten sie ihn: »Die Schriftgelehrten behaupten ja, Elia müsse zuerst kommen.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 9, 12, 'Er antwortete ihnen: »Ja, Elia kommt allerdings zuerst und bringt alles wieder in den rechten Stand. Doch wie kann denn über den Menschensohn geschrieben stehen, daß er vieles leiden und daß er verworfen werden müsse?');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 9, 13, 'Aber ich sage euch: Elia ist wirklich gekommen; doch sie haben ihm angetan, was ihnen beliebte, wie über ihn geschrieben steht.«.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 9, 14, 'Als sie dann zu den (anderen) Jüngern zurückkamen, sahen sie eine große Volksmenge um sie versammelt, auch Schriftgelehrte, die sich mit ihnen besprachen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 9, 15, 'Sobald nun die Menge ihn erblickte, gerieten alle in freudige Erregung; sie eilten auf ihn zu und begrüßten ihn.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 9, 16, 'Er fragte sie nun: »Was habt ihr mit ihnen zu verhandeln?«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 9, 17, 'Da antwortete ihm einer aus der Menge: »Meister, ich habe meinen Sohn zu dir gebracht, der von einem sprachlosen Geist besessen ist;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 9, 18, 'sooft der ihn packt, reißt er ihn hin und her; dann tritt ihm der Schaum vor den Mund, und er knirscht mit den Zähnen und wird ganz kraftlos. Ich habe deine Jünger gebeten, sie möchten ihn austreiben, doch sie haben es nicht gekonnt.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 9, 19, 'Jesus antwortete ihnen mit den Worten: »O ihr ungläubige Art von Menschen! Wie lange soll ich noch bei euch sein? Wie lange soll ich es noch mit euch aushalten? Bringt ihn her zu mir!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 9, 20, 'Da brachten sie ihn zu ihm. Als nun der Geist ihn erblickte, zog er den Knaben sogleich krampfhaft zusammen, so daß er auf den Boden fiel und sich mit Schaum vor dem Munde wälzte.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 9, 21, 'Da fragte Jesus den Vater des Knaben: »Wie lange hat er dies Leiden schon?« Er antwortete: »Von Kindheit an;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 9, 22, 'und oft hat der Geist ihn sogar ins Feuer und ins Wasser gestürzt, um ihn umzubringen. Wenn du es jedoch irgend vermagst, so hilf uns und habe Erbarmen mit uns!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 9, 23, 'Jesus antwortete ihm: »Was dein ›Wenn du es vermagst‹ betrifft, so wisse: Alles ist dem möglich, der Glauben hat.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 9, 24, 'Sogleich rief der Vater des Knaben laut aus: »Ich glaube: hilf meinem Unglauben!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 9, 25, 'Als Jesus nun sah, daß immer mehr Leute zusammenliefen, bedrohte er den unreinen Geist mit den Worten: »Du sprachloser und tauber Geist, ich gebiete dir: Fahre von ihm aus und fahre nicht wieder in ihn hinein!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 9, 26, 'Da schrie er laut auf und fuhr unter heftigen Krämpfen aus; und der Knabe lag wie tot da, so daß die meisten sagten: »Er ist gestorben!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 9, 27, 'Jesus aber faßte ihn bei der Hand und richtete ihn in die Höhe: da stand er auf. –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 9, 28, 'Als Jesus dann in ein Haus eingetreten war, fragten ihn seine Jünger, während sie mit ihm allein waren: »Warum haben wir den Geist nicht austreiben können?«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 9, 29, 'Er antwortete ihnen: »Diese Art (von bösen Geistern) läßt sich nur durch Gebet austreiben.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 9, 30, 'Sie zogen dann von dort weiter und wanderten durch Galiläa hin, und er wünschte, daß niemand es erfahren möchte;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 9, 31, 'denn er erteilte seinen Jüngern Unterricht und sagte zu ihnen: »Der Menschensohn wird in die Hände der Menschen überliefert; sie werden ihn töten, und drei Tage nach seiner Tötung wird er auferstehen.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 9, 32, 'Sie aber verstanden den Ausspruch nicht, scheuten sich jedoch, ihn deswegen zu befragen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 9, 33, 'So kamen sie nach Kapernaum; und als er zu Hause (angelangt) war, fragte er sie: »Worüber habt ihr unterwegs gesprochen?«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 9, 34, 'Sie aber schwiegen; denn sie hatten unterwegs miteinander darüber gesprochen, wer (von ihnen) der Größte sei.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 9, 35, 'Da setzte er sich, rief die Zwölf herbei und sagte zu ihnen: »Wenn jemand der Erste sein will, muß er von allen der Letzte und der Diener aller sein!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 9, 36, 'Dann nahm er ein Kind, stellte es mitten unter sie, schloß es in seine Arme und sagte zu ihnen:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 9, 37, '»Wer eins von solchen Kindern auf meinen Namen hin aufnimmt, der nimmt mich auf; und wer mich aufnimmt, der nimmt nicht mich auf, sondern den, der mich gesandt hat.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 9, 38, 'Da sagte Johannes zu ihm: »Meister, wir haben einen, der nicht mit uns dir nachfolgt, unter Anwendung deines Namens böse Geister austreiben sehen und haben es ihm untersagt, weil er uns nicht nachfolgt.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 9, 39, 'Jesus aber erwiderte ihm: »Untersagt es ihm nicht; denn so leicht wird niemand, der ein Wunder unter Benutzung meines Namens vollführt, dazu kommen, Böses von mir zu reden.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 9, 40, 'Denn wer nicht gegen uns ist, der ist für uns. –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 9, 41, 'Denn wenn jemand euch im Hinblick darauf, daß ihr Christus angehört, auch nur einen Becher Wasser zu trinken gibt, – wahrlich ich sage euch: Es wird ihm nicht unbelohnt bleiben!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 9, 42, '»Und wer einen von diesen Kleinen, die (an mich) glauben, ärgert, für den wäre es das beste, wenn ihm ein Mühlstein um den Hals gehängt und er ins Meer geworfen wäre.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 9, 43, 'Und wenn deine Hand dich ärgert, so haue sie ab! Es ist besser für dich, verstümmelt in das Leben einzugehen, als daß du deine beiden Hände hast und in die Hölle kommst, in das unauslöschliche Feuer.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 9, 44, '');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 9, 45, 'Und wenn dein Fuß dich ärgert, so haue ihn ab! Es ist besser für dich, als Lahmer in das Leben einzugehen, als daß du deine beiden Füße hast und in die Hölle geworfen wirst.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 9, 46, '');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 9, 47, 'Und wenn dein Auge dich ärgert, so reiße es aus! Es ist besser für dich, einäugig in das Reich Gottes einzugehen, als daß du beide Augen hast und in die Hölle geworfen wirst,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 9, 48, 'wo ihr Wurm nicht stirbt und das Feuer nicht erlischt. –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 9, 49, 'Denn jeder wird mit Feuer gesalzen werden [wie jedes Schlachtopfer mit Salz gewürzt wird].');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 9, 50, 'Das Salz ist etwas Gutes; wenn aber das Salz fade geworden ist, wodurch wollt ihr ihm die Würzkraft wiedergeben? Habt Salz in euch und haltet Frieden untereinander.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 10, 1, 'Jesus brach dann von dort auf und kam in das Gebiet von Judäa, und zwar in das Ostjordanland; und wieder strömte das Volk in Scharen bei ihm zusammen, und wieder lehrte er sie, wie es seine Gewohnheit war.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 10, 2, 'Da traten Pharisäer an ihn heran und fragten ihn, ob ein Ehemann seine Frau entlassen dürfe; sie wollten ihn nämlich versuchen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 10, 3, 'Er aber gab ihnen zur Antwort: »Was hat Mose euch geboten?«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 10, 4, 'Sie sagten: »Mose hat gestattet, einen Scheidebrief auszustellen und dann (die Frau) zu entlassen.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 10, 5, 'Jesus aber sagte zu ihnen: »Mit Rücksicht auf eure Herzenshärte hat er euch dieses Gebot vorgeschrieben;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 10, 6, 'aber vom Anfang der Schöpfung an hat Gott die Menschen als Mann und Weib geschaffen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 10, 7, 'Darum wird ein Mann seinen Vater und seine Mutter verlassen und seinem Weibe anhangen,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 10, 8, 'und die beiden werden zu einem Leibe werden, so daß sie nicht mehr zwei sind, sondern ein Leib.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 10, 9, 'Was nun Gott zusammengefügt hat, das soll der Mensch nicht scheiden.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 10, 10, 'Zu Hause befragten ihn dann seine Jünger nochmals hierüber,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 10, 11, 'und er erklärte ihnen: »Wer seine Frau entläßt und eine andere heiratet, begeht ihr gegenüber Ehebruch,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 10, 12, 'und (ebenso) wenn sie sich von ihrem Manne scheidet und einen andern heiratet, so begeht sie Ehebruch.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 10, 13, 'Und man brachte Kinder zu ihm, damit er sie anrühre; die Jünger aber verwiesen es ihnen in barscher Weise.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 10, 14, 'Als Jesus das sah, wurde er unwillig und sagte zu seinen Jüngern: »Laßt die Kinder zu mir kommen, hindert sie nicht daran! Denn für ihresgleichen ist das Reich Gottes bestimmt.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 10, 15, 'Wahrlich ich sage euch: Wer das Reich Gottes nicht annimmt wie ein Kind, wird sicherlich nicht hineinkommen!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 10, 16, 'Dann schloß er sie in seine Arme und segnete sie, indem er ihnen die Hände auflegte.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 10, 17, 'Als er dann (wieder) aufbrach, um weiterzuwandern, lief einer auf ihn zu, warf sich vor ihm auf die Knie nieder und fragte ihn: »Guter Meister, was muß ich tun, um ewiges Leben zu erben?«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 10, 18, 'Jesus antwortete ihm: »Was nennst du mich gut? Niemand ist gut als Gott allein.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 10, 19, 'Du kennst die Gebote: ›Du sollst nicht töten, nicht ehebrechen, nicht stehlen, nicht falsches Zeugnis ablegen, keinem das ihm Zukommende vorenthalten, ehre deinen Vater und deine Mutter!‹«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 10, 20, 'Jener erwiderte ihm: »Meister, dies alles habe ich von meiner Jugend an gehalten.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 10, 21, 'Jesus blickte ihn an, gewann ihn lieb und sagte zu ihm: »Eins fehlt dir noch: gehe hin, verkaufe alles, was du besitzest, und gib (den Erlös) den Armen: so wirst du einen Schatz im Himmel haben; dann komm und folge mir nach!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 10, 22, 'Er aber wurde über dies Wort unmutig und ging betrübt weg; denn er besaß ein großes Vermögen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 10, 23, 'Da blickte Jesus rings um sich und sagte zu seinen Jüngern: »Wie schwer wird es doch für die Begüterten sein, in das Reich Gottes einzugehen!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 10, 24, 'Die Jünger waren über diese seine Worte betroffen, Jesus aber wiederholte seinen Ausspruch nochmals mit den Worten: »Kinder, wie schwer ist es doch [für Menschen, die sich auf Geld und Gut verlassen], in das Reich Gottes einzugehen!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 10, 25, 'Es ist leichter, daß ein Kamel durch ein Nadelöhr hindurchgeht, als daß ein Reicher in das Reich Gottes eingeht.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 10, 26, 'Da erschraken sie noch weit mehr und sagten zueinander: »Ja, wer kann dann gerettet werden?«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 10, 27, 'Jesus blickte sie an und sagte: »Bei den Menschen ist es unmöglich, nicht aber bei Gott; denn bei Gott ist alles möglich.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 10, 28, 'Da nahm Petrus das Wort und sagte zu ihm: »Siehe, wir haben alles verlassen und sind dir nachgefolgt.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 10, 29, 'Jesus erwiderte: »Wahrlich ich sage euch: Niemand hat Haus oder Brüder und Schwestern oder Mutter, Vater und Kinder oder Äcker um meinetwillen und um der Heilsbotschaft willen verlassen,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 10, 30, 'ohne daß er hundertmal Wertvolleres (wieder) empfängt, nämlich schon jetzt in dieser Zeitlichkeit Häuser, Brüder und Schwestern, Mütter, Kinder und Äcker (wenn auch) inmitten von Verfolgungen und in der künftigen Weltzeit ewiges Leben.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 10, 31, 'Viele Erste aber werden Letzte sein und die Letzten Erste.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 10, 32, 'Sie waren aber auf der Wanderung begriffen, um nach Jerusalem hinaufzuziehen; Jesus ging ihnen (dabei) voran, und sie waren darüber erstaunt; die ihm Nachfolgenden aber waren voll Furcht. Da nahm er die Zwölf nochmals (allein) zu sich und begann mit ihnen von dem Geschick zu sprechen, das ihm bevorstände:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 10, 33, '»Seht, wir ziehen jetzt nach Jerusalem hinauf, und der Menschensohn wird den Hohenpriestern und Schriftgelehrten ausgeliefert werden; sie werden ihn zum Tode verurteilen und ihn den Heiden ausliefern;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 10, 34, 'die werden ihn dann verspotten und anspeien, geißeln und töten; und nach drei Tagen wird er auferstehen.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 10, 35, 'Da traten Jakobus und Johannes, die Söhne des Zebedäus, an ihn heran und sagten zu ihm: »Meister, wir möchten, daß du uns eine Bitte erfüllst.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 10, 36, 'Er fragte sie: »Was wünscht ihr von mir?«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 10, 37, 'Sie antworteten ihm: »Gewähre uns, daß wir in deiner Herrlichkeit einer zu deiner Rechten und einer zu deiner Linken sitzen dürfen!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 10, 38, 'Da sagte Jesus zu ihnen: »Ihr wißt nicht, um was ihr da bittet. Könnt ihr den Kelch trinken, den ich zu trinken habe, oder die Taufe erleiden, mit der ich getauft werde?«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 10, 39, 'Sie antworteten ihm: »Ja, wir können es.« Da sagte Jesus zu ihnen: »Den Kelch, den ich zu trinken habe, werdet (auch) ihr trinken, und mit der Taufe, mit der ich getauft werde, werdet ihr auch getauft werden;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 10, 40, 'aber den Sitz zu meiner Rechten oder zu meiner Linken habe nicht ich zu verleihen, sondern er wird denen zuteil, für die er bestimmt ist.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 10, 41, 'Als nun die zehn (übrigen Jünger) dies hörten, begann sich der Unwille über Jakobus und Johannes in ihnen zu regen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 10, 42, 'Da rief Jesus sie zu sich und sagte zu ihnen: »Ihr wißt, daß die, welche als Herrscher der Völker gelten, sich als Herren gegen sie benehmen und daß ihre Großen sie vergewaltigen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 10, 43, 'Bei euch aber darf es nicht so sein, sondern wer unter euch groß werden möchte, muß euer Diener sein,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 10, 44, 'und wer unter euch der Erste sein möchte, muß der Knecht aller sein;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 10, 45, 'denn auch der Menschensohn ist nicht (dazu) gekommen, um sich bedienen zu lassen, sondern um selbst zu dienen und sein Leben als Lösegeld für viele hinzugeben.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 10, 46, 'Sie kamen dann nach Jericho; und als er mit seinen Jüngern und einer großen Volksmenge aus Jericho hinauszog, saß der Sohn des Timäus, Bartimäus, ein blinder Bettler, am Wege.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 10, 47, 'Als dieser hörte, es sei Jesus von Nazareth, begann er laut zu rufen: »Sohn Davids, Jesus, erbarme dich meiner!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 10, 48, 'Viele riefen ihm drohend zu, er solle still sein; doch er rief nur noch lauter: »Sohn Davids, erbarme dich meiner!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 10, 49, 'Da blieb Jesus stehen und sagte: »Ruft ihn her!« So riefen sie denn den Blinden und sagten zu ihm: »Sei guten Mutes, stehe auf: er ruft dich!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 10, 50, 'Da warf er seinen Mantel ab, sprang auf und kam zu Jesus.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 10, 51, 'Dieser redete ihn mit den Worten an: »Was wünschest du von mir?« Der Blinde antwortete ihm: »Rabbuni, ich möchte sehen können!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 10, 52, 'Jesus sagte zu ihm: »Gehe hin, dein Glaube hat dich gerettet.« Da konnte er augenblicklich sehen und schloß sich an Jesus auf der Wanderung an.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 11, 1, 'Als sie dann in die Nähe von Jerusalem nach [Bethphage und] Bethanien an den Ölberg gekommen waren, sandte er zwei von seinen Jüngern ab');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 11, 2, 'mit der Weisung: »Geht in das Dorf, das dort vor euch liegt; und sogleich, wenn ihr hineinkommt, werdet ihr ein Eselsfüllen angebunden finden, auf dem noch nie ein Mensch gesessen hat; bindet es los und bringt es her!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 11, 3, 'Und wenn jemand euch fragen sollte: ›Was macht ihr da?‹, so antwortet: ›Der Herr bedarf seiner und schickt es sogleich wieder her.‹«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 11, 4, 'Da gingen sie hin und fanden ein Eselsfüllen angebunden am Haustor draußen nach der Dorfstraße zu und banden es los.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 11, 5, 'Und einige von den Leuten, die dort standen, sagten zu ihnen: »Was macht ihr da, daß ihr das Füllen losbindet?«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 11, 6, 'Sie antworteten ihnen, wie Jesus ihnen geboten hatte, da ließ man sie gewähren.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 11, 7, 'Sie brachten nun das Füllen zu Jesus und legten ihre Mäntel auf das Tier, und er setzte sich darauf.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 11, 8, 'Viele breiteten sodann ihre Mäntel auf den Weg, andere streuten Laubzweige aus, die sie auf den Feldern abgeschnitten hatten.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 11, 9, 'Und die, welche vorn im Zuge gingen, und die, welche nachfolgten, riefen laut: »Hosianna! Gepriesen sei, der da kommt im Namen des Herrn!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 11, 10, 'Gepriesen sei das Königtum unsers Vaters David, das da kommt! Hosianna in den Himmelshöhen!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 11, 11, 'So zog er in Jerusalem ein (und begab sich) in den Tempel; und nachdem er sich dort alles ringsum angesehen hatte, ging er, da es schon spät am Tage war, mit den Zwölfen nach Bethanien hinaus.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 11, 12, 'Als sie dann am folgenden Morgen von Bethanien wieder aufgebrochen waren, hungerte ihn.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 11, 13, 'Als er nun in der Ferne einen Feigenbaum sah, der Blätter hatte, ging er hin, ob er nicht einige Früchte an ihm fände, doch als er zu ihm hinkam, fand er nichts als Blätter, denn es war noch nicht die Feigenzeit.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 11, 14, 'Da rief er dem Baume die Worte zu: »Nie mehr in Ewigkeit soll jemand eine Frucht von dir essen!« Und seine Jünger hörten es.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 11, 15, 'Sie kamen dann nach Jerusalem, und als er dort in den Tempel hineingegangen war, machte er sich daran, die, welche im Tempel verkauften und kauften, hinauszutreiben, stieß die Tische der Geldwechsler und die Sitze der Taubenhändler um');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 11, 16, 'und duldete nicht, daß jemand ein Hausgerät über den Tempelplatz trug.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 11, 17, 'Und er belehrte sie mit den Worten: »Steht nicht geschrieben: ›Mein Haus soll ein Bethaus für alle Völker heißen‹? Ihr aber habt eine ›Räuberhöhle‹ aus ihm gemacht!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 11, 18, 'Die Hohenpriester und die Schriftgelehrten hörten davon und überlegten, wie sie ihn umbringen könnten; denn sie hatten Furcht vor ihm, weil seine Lehre auf das ganze Volk einen tiefen Eindruck machte. –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 11, 19, 'Und sooft es Abend geworden war, gingen sie aus der Stadt hinaus.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 11, 20, 'Als sie nun am folgenden Morgen vorübergingen, sahen sie den Feigenbaum von den Wurzeln aus verdorrt.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 11, 21, 'Da erinnerte sich Petrus (des Vorfalls) und sagte zu ihm: »Rabbi, sieh doch: der Feigenbaum, den du verflucht hast, ist verdorrt!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 11, 22, 'Jesus gab ihnen zur Antwort: »Habt Glauben an Gott!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 11, 23, 'Wahrlich ich sage euch: Wer zu dem Berge dort sagt: ›Hebe dich empor und stürze dich ins Meer!‹ und in seinem Herzen nicht zweifelt, sondern glaubt, daß das, was er ausspricht, in Erfüllung geht, dem wird es auch erfüllt werden.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 11, 24, 'Darum sage ich euch: Bei allem, was ihr im Gebet erbittet – glaubt nur, daß ihr es (tatsächlich) empfangen habt, so wird es euch zuteil werden.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 11, 25, 'Und wenn ihr dasteht und beten wollt, so vergebt (zunächst), wenn ihr etwas gegen jemand habt, damit auch euer himmlischer Vater euch eure Übertretungen vergebe.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 11, 26, '[Wenn aber ihr nicht vergebt, so wird auch euer himmlischer Vater euch eure Übertretungen nicht vergeben.]«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 11, 27, 'Sie kamen dann wieder nach Jerusalem; und als er dort im Tempel umherging, traten die Hohenpriester, die Schriftgelehrten und die Ältesten an ihn heran');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 11, 28, 'und fragten ihn: »Auf Grund welcher Vollmacht trittst du hier in solcher Weise auf? Oder wer hat dir die Vollmacht dazu gegeben, hier so aufzutreten?«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 11, 29, 'Da antwortete Jesus ihnen: »Ich will euch eine einzige Frage vorlegen: beantwortet sie mir, dann will ich euch sagen, auf Grund welcher Vollmacht ich hier so auftrete.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 11, 30, 'Stammte die Taufe des Johannes vom Himmel oder von Menschen? Gebt mir eine Antwort!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 11, 31, 'Da überlegten sie miteinander folgendermaßen: »Sagen wir: ›Vom Himmel‹, so wird er einwenden: ›Warum habt ihr ihm dann keinen Glauben geschenkt?‹');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 11, 32, 'Sollen wir dagegen sagen: ›Von Menschen?‹« – da fürchteten sie sich vor dem Volk; denn alle glaubten von Johannes, daß er wirklich ein Prophet gewesen sei.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 11, 33, 'So gaben sie denn Jesus zur Antwort: »Wir wissen es nicht.« Da erwiderte Jesus ihnen: »Dann sage auch ich euch nicht, auf Grund welcher Vollmacht ich hier so auftrete.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 12, 1, 'Er begann dann in Gleichnissen zu ihnen zu reden: »Ein Mann legte einen Weinberg an, umgab ihn mit einem Zaun, grub eine Kelter darin, baute einen Wachtturm, verpachtete ihn an Weingärtner und ging außer Landes.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 12, 2, 'Zu rechter Zeit sandte er dann einen Knecht zu den Weingärtnern, um seinen Teil der Früchte des Weinbergs von den Weingärtnern in Empfang zu nehmen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 12, 3, 'Die aber ergriffen den Knecht, mißhandelten ihn und schickten ihn mit leeren Händen zurück.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 12, 4, 'Da sandte er nochmals einen anderen Knecht zu ihnen; auch diesem zerschlugen sie den Kopf und beschimpften ihn.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 12, 5, 'Er sandte noch einen anderen, den sie töteten, und noch viele andere (sandte er), von denen sie die einen mißhandelten, die anderen töteten.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 12, 6, 'Nun hatte er noch einen einzigen, seinen geliebten Sohn; den sandte er zuletzt auch noch zu ihnen, weil er dachte: ›Sie werden sich doch vor meinem Sohne scheuen.‹');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 12, 7, 'Jene Weingärtner aber sagten zueinander: ›Dieser ist der Erbe; kommt, wir wollen ihn töten; dann wird das Erbgut uns gehören.‹');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 12, 8, 'So ergriffen sie ihn denn, schlugen ihn tot und warfen ihn vor den Weinberg hinaus.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 12, 9, 'Was wird nun der Herr des Weinbergs tun? Er wird kommen und die Weingärtner umbringen und wird den Weinberg an andere vergeben. –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 12, 10, 'Habt ihr nicht auch dieses Schriftwort gelesen: ›Der Stein, den die Bauleute verworfen haben, der ist zum Eckstein geworden;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 12, 11, 'durch den Herrn ist er das geworden, und ein Wunder ist er in unsern Augen?‹«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 12, 12, 'Da hätten sie ihn am liebsten festgenommen, fürchteten sich jedoch vor dem Volk; sie hatten nämlich wohl gemerkt, daß er das Gleichnis gegen sie gerichtet hatte. So ließen sie denn von ihm ab und entfernten sich.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 12, 13, 'Sie sandten darauf einige von den Pharisäern und den Anhängern des Herodes zu ihm, um ihn durch einen Ausspruch zu fangen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 12, 14, 'Jene kamen also und sagten zu ihm: »Meister, wir wissen, daß du wahrhaftig bist und auf niemand Rücksicht nimmst; denn du siehst die Person nicht an, sondern lehrst den Weg Gottes mit Wahrhaftigkeit. Ist es recht, daß man dem Kaiser Steuer entrichtet, oder nicht? Sollen wir sie entrichten oder nicht?«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 12, 15, 'Da er nun ihre Heuchelei durchschaute, antwortete er ihnen: »Warum versucht ihr mich? Reicht mir einen Denar, damit ich ihn ansehe!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 12, 16, 'Als sie ihm nun einen (Denar) gereicht hatten, fragte er sie: »Wessen Bild und Aufschrift ist das hier?« Sie antworteten ihm: »Des Kaisers.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 12, 17, 'Da sagte Jesus zu ihnen: »So gebt dem Kaiser, was dem Kaiser zusteht, und Gott, was Gott zusteht!« Und sie gerieten in Staunen über ihn.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 12, 18, 'Es traten dann Sadduzäer zu ihm, die da behaupten, es gebe keine Auferstehung, und legten ihm folgende Frage vor:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 12, 19, '»Meister, Mose hat uns vorgeschrieben: ›Wenn einem sein Bruder stirbt und eine Frau hinterläßt, aber kein Kind zurückläßt, so soll sein Bruder die Frau heiraten und für seinen Bruder das Geschlecht fortpflanzen.‹');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 12, 20, 'Nun waren da sieben Brüder; der erste nahm eine Frau, ließ aber bei seinem Tode keine Kinder zurück.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 12, 21, 'Da heiratete sie der zweite, starb aber auch, ohne Kinder zu hinterlassen; der dritte ebenso,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 12, 22, 'und alle sieben hinterließen keine Kinder; zuletzt nach allen starb auch die Frau.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 12, 23, 'In der Auferstehung nun, wenn sie auferstehen: wem von ihnen wird sie dann als Frau angehören? Alle sieben haben sie ja zur Frau gehabt.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 12, 24, 'Jesus antwortete ihnen: »Befindet ihr euch nicht deshalb im Irrtum, weil ihr die (heiligen) Schriften und die Kraft Gottes nicht kennt?');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 12, 25, 'Denn wenn sie von den Toten auferstehen, dann heiraten sie weder, noch werden sie verheiratet, sondern sie sind wie Engel im Himmel.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 12, 26, 'Was aber die Auferweckung der Toten betrifft: habt ihr nicht im Buche Moses bei der Erzählung vom Dornbusch gelesen, wie Gott zu Mose die Worte gesprochen hat: ›Ich bin der Gott Abrahams, der Gott Isaaks und der Gott Jakobs‹?');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 12, 27, 'Gott ist doch nicht der Gott von Toten, sondern von Lebenden. Ihr seid arg im Irrtum!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 12, 28, 'Da trat einer von den Schriftgelehrten hinzu, der ihnen zugehört hatte, wie sie miteinander verhandelten; und da er wußte, daß Jesus ihnen treffend geantwortet hatte, fragte er ihn: »Welches Gebot ist das erste von allen?«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 12, 29, 'Jesus antwortete: »Das erste ist: ›Höre, Israel: der Herr, unser Gott, ist Herr allein,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 12, 30, 'und du sollst den Herrn, deinen Gott, lieben mit deinem ganzen Herzen, mit deiner ganzen Seele, mit deinem ganzen Denken und mit aller deiner Kraft!‹');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 12, 31, 'An zweiter Stelle steht dieses (Gebot): ›Du sollst deinen Nächsten lieben wie dich selbst!‹ Kein anderes Gebot steht höher als diese beiden.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 12, 32, 'Da sagte der Schriftgelehrte zu ihm: »Meister, mit Recht hast du der Wahrheit gemäß gesagt, daß Gott nur einer ist und es keinen anderen außer ihm gibt;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 12, 33, 'und ihn mit ganzem Herzen und aus voller Überzeugung und mit ganzer Kraft lieben und den Nächsten wie sich selbst lieben, das ist weit mehr wert als alle Brandopfer und die Opfer überhaupt.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 12, 34, 'Als Jesus ihn so verständig antworten hörte, sagte er zu ihm: »Du bist nicht weit vom Reiche Gottes entfernt.« Und niemand wagte fortan noch, Fragen an ihn zu richten.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 12, 35, 'Jesus warf dann, während er im Tempel lehrte, die Frage auf: »Wie können die Schriftgelehrten behaupten, daß Christus Davids Sohn sei?');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 12, 36, 'David selbst hat doch im heiligen Geist gesagt: ›Der Herr hat zu meinem Herrn gesagt: Setze dich zu meiner Rechten, bis ich deine Feinde hinlege zum Schemel deiner Füße.‹');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 12, 37, 'David selbst nennt ihn ›Herr‹: wie kann er da sein Sohn sein?« Und die große Volksmenge hörte ihm gern zu.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 12, 38, 'Und in seiner Belehrung sagte er: »Hütet euch vor den Schriftgelehrten, die es lieben, in langen Gewändern einherzugehen und auf den Märkten gegrüßt zu werden;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 12, 39, 'die die Ehrensitze in den Synagogen und die obersten Plätze bei den Gastmählern beanspruchen;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 12, 40, 'die die Häuser der Witwen verschlingen und zum Schein lange Gebete verrichten. Sie werden ein um so strengeres Gericht erfahren.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 12, 41, 'Als er sich dann dem Opferkasten gegenüber hingesetzt hatte, sah er zu, wie das Volk Geld in den Kasten einwarf, und viele Reiche taten viel hinein.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 12, 42, 'Da kam auch eine arme Witwe und legte zwei Scherflein hinein, die einen Pfennig ausmachen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 12, 43, 'Da rief er seine Jünger herbei und sagte zu ihnen: »Wahrlich ich sage euch: Diese arme Witwe hat mehr eingelegt als alle, die etwas in den Opferkasten getan haben.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 12, 44, 'Denn jene haben alle von ihrem Überfluß eingelegt, sie aber hat aus ihrer Dürftigkeit heraus alles, was sie besaß, eingelegt, ihren ganzen Lebensunterhalt.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 13, 1, 'Als Jesus dann den Tempel verließ, sagte einer von seinen Jüngern zu ihm: »Meister, sieh einmal: was für Steine und was für ein Prachtbau ist das!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 13, 2, 'Da antwortete ihm Jesus: »Ja, jetzt siehst du dieses gewaltige Bauwerk (noch stehen). Es wird hier (aber) kein Stein auf dem andern bleiben, der nicht niedergerissen wird!« –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 13, 3, 'Als er sich dann am Ölberg dem Tempel gegenüber niedergesetzt hatte, fragten ihn Petrus, Jakobus, Johannes und Andreas, als sie für sich allein waren:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 13, 4, '»Sage uns doch: wann wird dies geschehen, und welches ist das Zeichen dafür, wann dies alles in Erfüllung gehen wird?«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 13, 5, 'Da begann Jesus, zu ihnen zu sagen: »Seht euch vor, daß niemand euch irreführt!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 13, 6, 'Viele werden unter meinem Namen kommen und sagen: ›Ich bin es‹ und werden viele irreführen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 13, 7, 'Wenn ihr ferner von Kriegen und Kriegsgerüchten hört, so laßt euch dadurch nicht ängstigen! Dies muß so kommen, bedeutet aber noch nicht das Ende.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 13, 8, 'Denn ein Volk wird sich gegen das andere erheben und ein Reich gegen das andere; Erdbeben werden hier und da stattfinden, Hungersnöte werden kommen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 13, 9, 'a Dies ist (aber erst) der Anfang der Wehen.« b »Gebt ihr jedoch acht auf euch selbst! Man wird euch vor die Gerichtshöfe stellen und euch in den Synagogen geißeln; auch vor Statthalter und Könige werdet ihr um meinetwillen gestellt werden ihnen zum Zeugnis;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 13, 10, 'und unter allen Völkern muß zuvor die Heilsbotschaft verkündigt werden.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 13, 11, 'Wenn man euch nun abführt und vor Gericht stellt, so macht euch nicht im voraus Sorge darüber, was ihr reden sollt, sondern was euch in jener Stunde eingegeben wird, das redet; nicht ihr seid es ja, die da reden, sondern der heilige Geist.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 13, 12, 'Es wird aber ein Bruder den anderen zum Tode überliefern und der Vater seinen Sohn, und Kinder werden gegen ihre Eltern auftreten und sie zum Tode bringen,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 13, 13, 'und ihr werdet allen verhaßt sein um meines Namens willen. Wer aber bis ans Ende ausharrt, der wird gerettet werden.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 13, 14, '»Wenn ihr aber den ›Greuel der Verwüstung‹ da stehen seht, wo er nicht stehen darf – der Leser merke auf! –, dann sollen die (Gläubigen), welche in Judäa sind, in die Berge fliehen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 13, 15, 'Wer sich alsdann auf dem Dache befindet, steige nicht erst (ins Haus) hinab und gehe nicht hinein, um noch etwas aus seinem Hause zu holen;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 13, 16, 'und wer auf dem Felde ist, kehre nicht zurück, um noch seinen Mantel zu holen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 13, 17, 'Wehe aber den Frauen, die in jenen Tagen guter Hoffnung sind, und denen, die ein Kind zu nähren haben!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 13, 18, 'Betet aber auch, daß dies nicht zur Winterszeit eintrete!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 13, 19, 'Denn jene Tage werden eine Drangsalszeit sein, wie eine solche seit dem Anfang, als Gott die Welt schuf, bis jetzt noch nicht dagewesen ist und wie auch keine je wieder kommen wird.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 13, 20, 'Und wenn der Herr diese Tage nicht verkürzt hätte, so würde kein Fleisch gerettet werden; aber um der Auserwählten willen, die er erwählt hat, hat er diese Tage verkürzt.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 13, 21, '»Wenn alsdann jemand zu euch sagt: ›Seht, hier ist Christus; seht, dort ist er!‹, so glaubt es nicht!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 13, 22, 'Denn es werden falsche Christusse und falsche Propheten auftreten und werden Zeichen und Wunder tun, um womöglich die Erwählten irrezuführen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 13, 23, 'Seht ihr euch aber vor! Ich habe euch alles vorhergesagt.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 13, 24, '»In jenen Tagen aber, nach jener Drangsalszeit, wird die Sonne sich verfinstern und der Mond seinen Schein verlieren;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 13, 25, 'die Sterne werden vom Himmel fallen und die Kräfte am Himmel in Erschütterung geraten.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 13, 26, 'Und dann wird man den Menschensohn in Wolken kommen sehen mit großer Macht und Herrlichkeit;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 13, 27, 'und dann wird er die Engel aussenden und seine Erwählten von den vier Windrichtungen her versammeln vom Ende der Erde bis zum Ende des Himmels.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 13, 28, 'Vom Feigenbaum aber mögt ihr das Gleichnis lernen: Sobald seine Zweige saftig werden und Blätter hervorsprossen, so erkennt ihr daran, daß der Sommer nahe ist.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 13, 29, 'Ebenso auch ihr: wenn ihr dies alles eintreten seht, so erkennet daran, daß es nahe vor der Tür steht.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 13, 30, 'Wahrlich ich sage euch: Dieses Geschlecht wird nicht vergehen, bis dies alles geschieht.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 13, 31, 'Der Himmel und die Erde werden vergehen, aber meine Worte werden nimmermehr vergehen!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 13, 32, 'Von jenem Tage aber und jener Stunde hat niemand Kenntnis, auch die Engel im Himmel nicht, auch der Sohn nicht, niemand außer dem Vater.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 13, 33, '»Haltet die Augen offen, seid wachsam! Denn ihr wißt nicht, wann der Zeitpunkt da ist.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 13, 34, 'Wie ein Mann, der auf Reisen geht, beim Verlassen seines Hauses seinen Knechten die Vollmacht übergibt und einem jeden sein Geschäft (zuweist) und dem Türhüter gebietet, wachsam zu sein, –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 13, 35, 'so wachet also! Denn ihr wißt nicht, wann der Herr des Hauses kommt, ob spät am Abend oder um Mitternacht oder beim Hahnenschrei oder erst frühmorgens:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 13, 36, 'daß er nur nicht, wenn er unvermutet kommt, euch im Schlaf findet!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 13, 37, 'Was ich aber euch sage, das sage ich allen: wachet!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 14, 1, 'Es stand aber in zwei Tagen das Passahfest und die (Tage der) ungesäuerten Brote bevor. Da überlegten die Hohenpriester und die Schriftgelehrten, auf welche Weise sie Jesus mit List festnehmen und töten könnten;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 14, 2, 'denn sie sagten: »Nur nicht während des Festes (selbst), damit keine Unruhen im Volk entstehen!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 14, 3, 'Als nun Jesus in Bethanien im Hause Simons des (einstmals) Aussätzigen war, kam, während er bei Tische saß, eine Frau, die ein Alabasterfläschchen mit echtem, kostbarem Nardensalböl hatte; sie zerbrach das Gefäß und goß es ihm über das Haupt.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 14, 4, 'Darüber wurden einige (der Anwesenden) unwillig und sagten zueinander: »Wozu hat diese Verschwendung des Salböls stattgefunden?');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 14, 5, 'Dieses Salböl hätte man ja für mehr als dreihundert Denare verkaufen und (den Erlös) den Armen geben können«; und sie machten der Frau laute Vorwürfe.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 14, 6, 'Da sagte Jesus: »Laßt sie in Ruhe! Warum bekümmert ihr sie? Sie hat ein gutes Werk an mir getan!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 14, 7, 'Denn die Armen habt ihr allezeit bei euch und könnt ihnen Gutes tun, sooft ihr wollt; mich aber habt ihr nicht allezeit.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 14, 8, 'Sie hat getan, was in ihren Kräften stand: sie hat meinen Leib im voraus zur Bestattung gesalbt.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 14, 9, 'Wahrlich ich sage euch: Überall, wo die Heilsbotschaft in der ganzen Welt verkündet werden wird, da wird man auch von dem sprechen, was diese Frau getan hat, zu ihrem Gedächtnis.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 14, 10, 'Da ging Judas Iskariot, der eine von den Zwölfen, zu den Hohenpriestern, um ihnen Jesus in die Hände zu liefern.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 14, 11, 'Als sie das hörten, freuten sie sich und versprachen, ihm Geld zu geben. Darauf suchte er nach einer guten Gelegenheit, um ihn zu überantworten.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 14, 12, 'Am ersten Tag der ungesäuerten Brote aber, an dem man das Passahlamm zu schlachten pflegte, fragten ihn seine Jünger: »Wohin sollen wir gehen, um alles vorzubereiten, damit du das Passahlamm essen kannst?«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 14, 13, 'Da sandte er zwei von seinen Jüngern ab und trug ihnen auf: »Geht in die Stadt: da wird euch ein Mann begegnen, der einen Krug mit Wasser trägt; folgt ihm nach,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 14, 14, 'und wo er hineingeht, da sagt zu dem Hausherrn: ›Der Meister läßt fragen: Wo ist das Eßzimmer für mich, in dem ich das Passahlamm mit meinen Jüngern essen kann?‹');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 14, 15, 'Dann wird er euch ein geräumiges Obergemach zeigen, das mit Tischpolstern ausgestattet ist und schon bereit steht; dort richtet (alles) für uns zu!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 14, 16, 'Da machten sich die Jünger auf den Weg, und als sie in die Stadt gekommen waren, fanden sie es dort so, wie er ihnen gesagt hatte, und richteten das Passahmahl zu.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 14, 17, 'Als es dann Abend geworden war, fand er sich dort mit den Zwölfen ein;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 14, 18, 'und während sie bei Tische saßen und das Mahl einnahmen, sagte Jesus: »Wahrlich ich sage euch: Einer von euch wird mich überantworten, einer, der hier mit mir ißt.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 14, 19, 'Da wurden sie betrübt und fragten ihn, einer nach dem andern: »Ich bin es doch nicht?«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 14, 20, 'Er antwortete ihnen: »Einer von euch Zwölfen, der mit mir in die Schüssel eintaucht.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 14, 21, 'Denn der Menschensohn geht zwar dahin, wie über ihn in der Schrift steht; doch wehe dem Menschen, durch den der Menschensohn verraten wird! Für diesen Menschen wäre es besser, er wäre nicht geboren!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 14, 22, 'Und während des Essens nahm Jesus ein Brot, sprach den Lobpreis (Gottes), brach (das Brot) und gab es ihnen mit den Worten: »Nehmet! Dies ist mein Leib.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 14, 23, 'Dann nahm er einen Becher, sprach das Dankgebet und gab ihnen den, und sie tranken alle daraus;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 14, 24, 'und er sagte zu ihnen: »Dies ist mein Blut, das Bundesblut, das für viele vergossen wird.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 14, 25, 'Wahrlich ich sage euch: Ich werde vom Erzeugnis des Weinstocks hinfort nicht mehr trinken bis zu jenem Tage, an dem ich es neu trinke im Reiche Gottes.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 14, 26, 'Nachdem sie dann den Lobpreis (Ps 115-118) gesungen hatten, gingen sie (aus der Stadt) hinaus an den Ölberg.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 14, 27, 'Dabei sagte Jesus zu ihnen: »Ihr werdet alle Anstoß nehmen; denn es steht geschrieben: ›Ich werde den Hirten niederschlagen, dann werden die Schafe sich zerstreuen.‹');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 14, 28, 'Aber nach meiner Auferweckung werde ich euch nach Galiläa vorausgehen.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 14, 29, 'Da antwortete Petrus: »Mögen auch alle Anstoß nehmen, so doch ich sicherlich nicht!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 14, 30, 'Jesus erwiderte ihm: »Wahrlich ich sage dir: Du wirst mich noch heute in dieser Nacht, ehe der Hahn zweimal kräht, dreimal verleugnen!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 14, 31, 'Er beteuerte aber nur um so eifriger: »Wenn ich auch mit dir sterben müßte, werde ich dich doch nicht verleugnen!« Das gleiche versicherten auch (die anderen) alle.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 14, 32, 'Sie kamen dann an einen Ort mit Namen Gethsemane; dort sagte er zu seinen Jüngern: »Laßt euch hier nieder, bis ich gebetet habe!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 14, 33, 'Dann nahm er Petrus, Jakobus und Johannes mit sich und fing an zu zittern und zu zagen');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 14, 34, 'und sagte zu ihnen: »Tiefbetrübt ist meine Seele bis zum Tode; bleibt hier und haltet euch wach!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 14, 35, 'Dann ging er noch ein wenig weiter, warf sich auf die Erde nieder und betete, daß, wenn es möglich sei, die Stunde an ihm vorübergehen möchte;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 14, 36, 'dabei sagte er: »Abba, Vater! Alles ist dir möglich: laß diesen Kelch an mir vorübergehen! Doch nicht, was ich will, sondern was du willst!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 14, 37, 'Dann ging er zurück und fand sie schlafen und sagte zu Petrus: »Simon, du schläfst? Hattest du nicht die Kraft, eine einzige Stunde wach zu bleiben?');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 14, 38, 'Wachet, und betet, damit ihr nicht in Versuchung geratet! Der Geist ist willig, das Fleisch aber ist schwach.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 14, 39, 'Darauf ging er wieder weg und betete mit denselben Worten;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 14, 40, 'und als er zurückkam, fand er sie wiederum schlafen; denn die Augen fielen ihnen vor Müdigkeit zu, und sie wußten ihm nichts zu antworten.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 14, 41, 'Und er kam zum drittenmal und sagte zu ihnen: »Schlaft ein andermal und ruht euch aus! Es ist genug so: die Stunde ist gekommen! Sehet, der Menschensohn wird den Sündern in die Hände geliefert!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 14, 42, 'Steht auf, laßt uns gehen! Seht, der mich überantwortet ist nahe gekommen!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 14, 43, 'Und sogleich darauf, während er noch redete, erschien Judas, einer von den Zwölfen, und mit ihm eine Schar mit Schwertern und Knütteln, von den Hohenpriestern, den Schriftgelehrten und Ältesten (abgesandt).');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 14, 44, 'Sein Verräter hatte aber ein Zeichen mit ihnen verabredet, nämlich: »Der, den ich küssen werde, der ist’s; den nehmt fest und führt ihn sicher ab!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 14, 45, 'Als er nun ankam, trat er sogleich auf Jesus zu und sagte: »Rabbi!« und küßte ihn;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 14, 46, 'da legten sie Hand an Jesus und nahmen ihn fest.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 14, 47, 'Einer jedoch von den Dabeistehenden zog das Schwert, schlug auf den Knecht des Hohenpriesters ein und hieb ihm das Ohr ab.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 14, 48, 'Jesus aber sagte zu ihnen: »Wie gegen einen Räuber seid ihr mit Schwertern und Knütteln ausgezogen, um mich gefangen zu nehmen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 14, 49, 'Täglich bin ich bei euch im Tempel gewesen und habe dort gelehrt, und ihr habt mich nicht festgenommen; doch die Aussprüche der Schrift müssen erfüllt werden.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 14, 50, 'Da verließen ihn alle und ergriffen die Flucht.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 14, 51, 'Aber ein junger Mann folgte ihm nach, der nur einen linnenen Überwurf auf dem bloßen Leibe anhatte; den ergriffen sie;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 14, 52, 'er aber ließ seinen Überwurf fahren und entfloh unbekleidet.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 14, 53, 'Sie führten nun Jesus zu dem Hohenpriester ab, und alle Hohenpriester sowie die Ältesten und Schriftgelehrten kamen (dort) zusammen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 14, 54, 'Petrus aber war ihm von ferne bis hinein in den Palast des Hohenpriesters gefolgt; dort hatte er sich unter die Diener gesetzt und wärmte sich am Feuer.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 14, 55, 'Die Hohenpriester aber und der gesamte Hohe Rat suchten nach einer Zeugenaussage gegen Jesus, um ihn zum Tode verurteilen zu können, fanden jedoch keine;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 14, 56, 'denn viele legten wohl falsches Zeugnis gegen ihn ab, doch ihre Aussagen stimmten nicht überein.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 14, 57, 'Einige traten auch auf und brachten ein falsches Zeugnis gegen ihn vor, indem sie aussagten:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 14, 58, '»Wir haben ihn sagen hören: ›Ich werde diesen Tempel, der von Menschenhänden errichtet ist, abbrechen und in drei Tagen einen anderen bauen, der nicht von Menschenhänden errichtet ist‹«;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 14, 59, 'doch auch darin war ihr Zeugnis nicht übereinstimmend.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 14, 60, 'Da stand der Hohepriester auf, trat in die Mitte und fragte Jesus mit den Worten: »Entgegnest du nichts auf die Aussage dieser Zeugen?«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 14, 61, 'Er aber schwieg und gab keine Antwort. Nochmals befragte ihn der Hohepriester mit den Worten: »Bist du Christus, der Sohn des Hochgelobten?«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 14, 62, 'Jesus antwortete: »Ja, ich bin es, und ihr werdet den Menschensohn sitzen sehen zur Rechten der Macht und kommen mit den Wolken des Himmels!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 14, 63, 'Da zerriß der Hohepriester seine Kleider und sagte: »Wozu brauchen wir noch weiter Zeugen?');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 14, 64, 'Ihr habt die Gotteslästerung gehört: was urteilt ihr?« Da gaben sie alle das Urteil über ihn ab, er sei des Todes schuldig.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 14, 65, 'Nun fingen einige an, ihn anzuspeien, ihm das Gesicht zu verhüllen, ihn dann mit der Faust zu schlagen und zu ihm zu sagen: »Weissage uns!« Auch die Gerichtsdiener versetzten ihm bei der Übernahme Schläge ins Gesicht.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 14, 66, 'Während nun Petrus unten im Hofe (des Palastes) war, kam eine von den Mägden des Hohenpriesters,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 14, 67, 'und als sie Petrus (am Feuer) sich wärmen sah, blickte sie ihn scharf an und sagte: »Du bist auch mit dem Nazarener, mit Jesus, zusammengewesen!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 14, 68, 'Er aber leugnete und sagte: »Ich weiß nicht und verstehe nicht, was du da sagst!« Er ging dann in die Vorhalle des Hofes hinaus,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 14, 69, 'und als die Magd ihn dort sah, fing sie wieder an und sagte zu den Dabeistehenden: »Dieser ist auch einer von ihnen!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 14, 70, 'Er aber leugnete wiederum. Nach einer kleinen Weile sagten die Dabeistehenden wieder zu Petrus: »Wahrhaftig, du gehörst zu ihnen! Du bist ja auch ein Galiläer.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 14, 71, 'Er aber fing an, sich zu verfluchen und eidlich zu beteuern: »Ich kenne diesen Menschen nicht, von dem ihr da redet!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 14, 72, 'Und alsbald krähte der Hahn zum zweitenmal. Da dachte Petrus an das Wort Jesu, wie er zu ihm gesagt hatte: »Ehe der Hahn zweimal kräht, wirst du mich dreimal verleugnen.« Als er daran dachte, brach er in Tränen aus.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 15, 1, 'Und sogleich frühmorgens fertigten die Hohenpriester mit den Ältesten und Schriftgelehrten und (somit) der gesamte Hohe Rat den (endgültigen) Beschluß aus, ließen Jesus fesseln und abführen und übergaben ihn dem Pilatus.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 15, 2, 'Dieser befragte ihn: »Bist du der König der Juden?« Er antwortete ihm mit den Worten: »Ja, ich bin es.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 15, 3, 'Die Hohenpriester brachten dann viele Anklagen gegen ihn vor;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 15, 4, 'da fragte Pilatus ihn nochmals: »Entgegnest du nichts? Höre nur, was sie alles gegen dich vorbringen!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 15, 5, 'Jesus aber gab keine Antwort mehr, so daß Pilatus sich verwunderte.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 15, 6, 'An jedem Fest aber pflegte er ihnen einen Gefangenen freizugeben, den sie sich erbaten.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 15, 7, 'Nun saß damals ein unter dem Namen Barabbas bekannter Mensch im Gefängnis mit den (anderen) Aufrührern, die beim Aufruhr einen Mord begangen hatten.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 15, 8, 'So zog denn die Volksmenge hinauf und begann um das zu bitten, was er ihnen gewöhnlich gewährte.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 15, 9, 'Pilatus antwortete ihnen mit der Frage: »Wollt ihr, daß ich euch den König der Juden freigebe?«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 15, 10, 'Er war sich nämlich klar darüber geworden, daß die Hohenpriester ihn aus Neid überantwortet hatten.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 15, 11, 'Die Hohenpriester aber hetzten die Volksmenge zu der Forderung auf, er möchte ihnen lieber den Barabbas freigeben.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 15, 12, 'Nun richtete Pilatus nochmals die Frage an sie: »Was soll ich denn mit dem (Manne) machen, den ihr den König der Juden nennt?«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 15, 13, 'Sie schrien zurück: »Laß ihn kreuzigen!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 15, 14, 'Pilatus entgegnete ihnen: »Was hat er denn Böses getan?« Da schrien sie noch lauter: »Laß ihn kreuzigen!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 15, 15, 'Um nun dem Volke den Willen zu tun, gab Pilatus ihnen den Barabbas frei, Jesus aber ließ er geißeln und übergab ihn dann (den Soldaten) zur Kreuzigung.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 15, 16, 'Nun führten ihn die Soldaten ab in das Innere des Palastes – das ist nämlich die Statthalterei – und riefen die ganze Abteilung zusammen,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 15, 17, 'dann legten sie ihm einen Purpur um, setzten ihm eine Dornenkrone auf, die sie geflochten hatten,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 15, 18, 'und fingen an, ihm als König zu huldigen mit dem Zuruf: »Sei gegrüßt, Judenkönig!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 15, 19, 'Dabei schlugen sie ihn mit einem Rohr aufs Haupt, spien ihn an, warfen sich vor ihm auf die Knie nieder und brachten ihm Huldigungen dar.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 15, 20, 'a Nachdem sie ihn so verspottet hatten, nahmen sie ihm den Purpurmantel wieder ab und legten ihm seine eigenen Kleider an. b Dann führten sie ihn zur Kreuzigung (aus der Stadt) hinaus');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 15, 21, 'und zwangen einen Vorübergehenden, Simon aus Cyrene, der vom Felde kam, den Vater Alexanders und des Rufus, ihm das Kreuz zu tragen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 15, 22, 'So brachten sie ihn nach dem Platz Golgatha, das bedeutet übersetzt ›Schädel(stätte)‹,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 15, 23, 'und reichten ihm mit Myrrhe gewürzten Wein, den er aber nicht nahm.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 15, 24, 'Dann kreuzigten sie ihn und verteilten seine Kleider unter sich, indem sie das Los um sie warfen, welches Stück jeder erhalten sollte.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 15, 25, 'Es war aber die dritte Tagesstunde, als sie ihn kreuzigten;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 15, 26, 'und die Inschrift mit der Angabe seiner Schuld lautete so: »Der König der Juden.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 15, 27, 'Mit ihm kreuzigten sie auch zwei Räuber, den einen zu seiner Rechten, den anderen zu seiner Linken.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 15, 28, '[So wurde das Schriftwort erfüllt, das da lautet: »Er ist unter die Gesetzlosen gerechnet worden.«]');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 15, 29, 'Und die Vorübergehenden schmähten ihn, schüttelten die Köpfe und riefen aus: »Ha du, der du den Tempel abbrichst und ihn in drei Tagen wieder aufbaust:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 15, 30, 'hilf dir selbst und steige vom Kreuz herab!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 15, 31, 'Ebenso verhöhnten ihn auch die Hohenpriester untereinander samt den Schriftgelehrten mit den Worten: »Anderen hat er geholfen, sich selbst kann er nicht helfen!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 15, 32, 'Der Gottgesalbte, der König von Israel, steige jetzt vom Kreuz herab, damit wir es sehen und gläubig werden!« Auch die (beiden) mit ihm Gekreuzigten schmähten ihn.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 15, 33, 'Als dann aber die sechste Stunde gekommen war, trat eine Finsternis über das ganze Land ein bis zur neunten Stunde;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 15, 34, 'und in der neunten Stunde rief Jesus mit lauter Stimme: »Eloi, Eloi, lema sabachthani?«, das heißt übersetzt: »Mein Gott, mein Gott, warum hast du mich verlassen?«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 15, 35, 'Als dies einige von den Dabeistehenden hörten, sagten sie: »Hört, er ruft den Elia!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 15, 36, 'Da lief einer hin, tränkte einen Schwamm mit Essig, steckte ihn an ein Rohr und wollte ihm zu trinken geben, wobei er sagte: »Laßt mich! Wir wollen doch sehen, ob Elia kommt, um ihn herabzunehmen!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 15, 37, 'Jesus aber stieß noch einen lauten Schrei aus und verschied dann.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 15, 38, 'Da zerriß der Vorhang des Tempels in zwei Stücke von oben bis unten.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 15, 39, 'Als aber der Hauptmann, der ihm gegenüber in der Nähe stand, ihn so verscheiden sah, erklärte er: »Dieser Mann ist wirklich Gottes Sohn gewesen.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 15, 40, 'Es waren aber auch Frauen da, die von weitem zuschauten, unter ihnen Maria von Magdala und Maria, die Mutter Jakobus des Kleinen und des Joses, und Salome,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 15, 41, 'die ihm schon, als er noch in Galiläa war, nachgefolgt waren und ihm Dienste geleistet hatten, und noch viele andere (Frauen), die mit ihm nach Jerusalem hinaufgezogen waren.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 15, 42, 'Als es nun bereits Spätnachmittag geworden war – es war nämlich Rüsttag, das ist der Tag vor dem Sabbat –,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 15, 43, 'kam Joseph von Arimathäa, ein angesehener Ratsherr, der auch auf das Reich Gottes wartete, begab sich mit kühnem Entschluß zu Pilatus hinein und bat ihn um den Leichnam Jesu.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 15, 44, 'Pilatus wunderte sich, daß er schon gestorben sein sollte; er ließ (deshalb) den Hauptmann zu sich rufen und fragte ihn, ob er schon lange tot sei;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 15, 45, 'und als er von dem Hauptmann das Nähere erfahren hatte, schenkte er den Leichnam dem Joseph.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 15, 46, 'Der kaufte nun Leinwand, nahm ihn (vom Kreuz) herab, wickelte ihn in die Leinwand und setzte ihn in einem Grabe bei, das in einen Felsen gehauen war; dann wälzte er einen Stein vor den Eingang des Grabes.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 15, 47, 'Maria von Magdala aber und Maria, die Mutter des Joses, sahen sich genau den Ort an, wohin er gelegt worden war.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 16, 1, 'Als dann der Sabbat vorüber war, kauften Maria von Magdala und Maria, die Mutter des Jakobus, und Salome wohlriechende Salben, um hinzugehen und ihn zu salben;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 16, 2, 'und ganz früh am ersten Tage der Woche kamen sie zum Grabe, als die Sonne (eben) aufgegangen war;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 16, 3, 'und sie sagten zueinander: »Wer wird uns den Stein vom Eingang des Grabes wegwälzen?«, er war nämlich sehr groß;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 16, 4, 'doch als sie hinblickten, sahen sie, daß der Stein schon weggewälzt war.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 16, 5, 'Als sie dann in das Grab hineingetreten waren, sahen sie einen Jüngling auf der rechten Seite sitzen, der mit einem langen, weißen Gewande bekleidet war, und sie erschraken sehr.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 16, 6, 'Er aber sagte zu ihnen: »Erschreckt nicht! Ihr sucht Jesus von Nazareth, den Gekreuzigten: er ist auferweckt worden, ist nicht mehr hier; seht, da ist die Stelle, wohin man ihn gelegt hatte!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 16, 7, 'Geht aber hin und sagt seinen Jüngern und (besonders) dem Petrus, daß er euch nach Galiläa vorausgeht: dort werdet ihr ihn wiedersehen, wie er euch gesagt hat.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 16, 8, 'Da gingen sie hinaus und flohen vom Grabe hinweg; denn Zittern und Entsetzen hatte sie befallen; und sie sagten niemand etwas davon, denn sie fürchteten sich.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 16, 9, 'Nachdem Jesus aber am ersten Tage der Woche frühmorgens auferstanden war, erschien er zuerst der Maria von Magdala, aus der er sieben böse Geister ausgetrieben hatte.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 16, 10, 'Diese ging hin und verkündete es denen, die bei ihm gewesen waren und (jetzt) trauerten und weinten.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 16, 11, 'Doch als diese hörten, daß er lebe und ihr erschienen sei, wollten sie es nicht glauben. –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 16, 12, 'Darauf offenbarte er sich in veränderter Gestalt zweien von ihnen, als sie auf einer Wanderung über Land gingen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 16, 13, 'Auch diese gingen hin und verkündeten es den übrigen; doch auch ihnen glaubten sie nicht.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 16, 14, 'Später aber offenbarte er sich den elf (Jüngern selbst), als sie bei Tische saßen, und schalt ihren Unglauben und ihre Herzenshärte, weil sie denen, die ihn nach seiner Auferstehung gesehen hatten, keinen Glauben geschenkt hatten.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 16, 15, 'Darauf sagte er zu ihnen: »Geht hin in alle Welt und verkündigt die Heilsbotschaft der ganzen Schöpfung!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 16, 16, 'Wer da gläubig geworden ist und sich hat taufen lassen, wird gerettet werden; wer aber ungläubig geblieben ist, wird verurteilt werden.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 16, 17, 'Denen aber, die zum Glauben gekommen sind, werden diese Wunderzeichen folgen: in meinem Namen werden sie böse Geister austreiben, in neuen Zungen reden,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 16, 18, 'werden Schlangen aufheben und, wenn sie etwas Todbringendes trinken, wird es ihnen nicht schaden; Kranken werden sie die Hände auflegen, und sie werden gesund werden.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 16, 19, 'Nachdem nun der Herr Jesus zu ihnen geredet hatte, wurde er in den Himmel emporgehoben und setzte sich zur Rechten Gottes.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 16, 20, 'Sie aber zogen aus und predigten überall, wobei der Herr mitwirkte und das Wort durch die Zeichen bestätigte, die dabei geschahen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 1, 1, 'Weil bekanntlich schon viele es unternommen haben, einen Bericht über die Begebenheiten, die sich unter uns erfüllt haben, so abzufassen,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 1, 2, 'wie die Männer sie uns überliefert haben, die von Anbeginn an Augenzeugen und (alsdann) Diener des Wortes gewesen sind,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 1, 3, 'habe auch ich mich entschlossen, nachdem ich allen Tatsachen von den Anfängen an sorgfältig nachgegangen bin, alles für dich, hochedler Theophilus, in richtiger Reihenfolge aufzuzeichnen,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 1, 4, 'damit du dich von der Zuverlässigkeit der Nachrichten, in denen du unterwiesen worden bist, überzeugen kannst.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 1, 5, 'Es lebte zur Zeit des jüdischen Königs Herodes ein Priester namens Zacharias aus der Priesterabteilung Abia; der hatte eine Frau aus der Zahl der Töchter Aarons, die Elisabeth hieß.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 1, 6, 'Sie waren beide gerecht vor Gott und wandelten in allen Geboten und Satzungen des Herrn ohne Tadel.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 1, 7, 'Sie hatten jedoch kein Kind, weil der Elisabeth Mutterfreuden versagt waren, und beide standen schon in vorgerücktem Alter.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 1, 8, 'Da begab es sich einst, als er nach der Ordnung seiner Abteilung den Priesterdienst vor Gott zu verrichten hatte,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 1, 9, 'daß er nach dem Brauch der Priesterschaft durch das Los dazu bestimmt wurde, in den Tempel des Herrn zu gehen und dort das Rauchopfer darzubringen,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 1, 10, 'während die ganze Volksmenge draußen zur Stunde des Rauchopfers dem Gebet oblag.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 1, 11, 'Da erschien ihm ein Engel des Herrn, der stand auf der rechten Seite des Rauchopferaltars.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 1, 12, 'Bei seinem Anblick erschrak Zacharias, und Furcht befiel ihn;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 1, 13, 'der Engel aber sagte zu ihm: »Fürchte dich nicht, Zacharias, denn dein Gebet hat Erhörung gefunden, und deine Frau Elisabeth wird dir Mutter eines Sohnes werden, dem du den Namen Johannes geben sollst.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 1, 14, 'Du wirst Freude und Jubel darüber empfinden, und viele werden sich über seine Geburt freuen,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 1, 15, 'denn er wird groß vor dem Herrn sein; Wein und (andere) berauschende Getränke wird er nicht genießen, und mit heiligem Geist wird er schon von Geburt an erfüllt werden.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 1, 16, 'Viele von den Söhnen Israels wird er zum Herrn, ihrem Gott, zurückführen;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 1, 17, 'und er ist es, der vor ihm einhergehen wird im Geist und in der Kraft des Elia, um die Herzen der Väter den Kindern wieder zuzuwenden und die Ungehorsamen zur Gesinnung der Gerechten (zu führen), um dem Herrn ein wohlbereitetes Volk zu schaffen.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 1, 18, 'Da sagte Zacharias zu dem Engel: »Wie soll ich das für möglich halten? Ich selbst bin ja ein alter Mann, und meine Frau ist auch schon betagt.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 1, 19, 'Da antwortete ihm der Engel: »Ich bin Gabriel, der (als Diener) vor Gottes Angesicht steht, und bin gesandt, um zu dir zu reden und dir diese frohe Botschaft zu verkündigen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 1, 20, 'Doch nun vernimm: Du wirst stumm sein und nicht reden können bis zu dem Tage, an dem diese meine Verheißung sich erfüllt, weil du meinen Worten nicht geglaubt hast, die zu ihrer Zeit in Erfüllung gehen werden.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 1, 21, 'Das Volk wartete unterdessen auf Zacharias und wunderte sich darüber, daß er so lange im Tempel verweilte.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 1, 22, 'Als er endlich heraustrat, konnte er nicht zu ihnen reden; da merkten sie, daß er eine Erscheinung im Tempel gesehen hatte; und er seinerseits suchte sich ihnen durch Kopfnicken verständlich zu machen, blieb aber stumm.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 1, 23, 'Als dann die (sieben) Tage seines Priesterdienstes zu Ende waren, kehrte er heim in sein Haus.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 1, 24, 'Nach diesen Tagen aber wurde seine Frau Elisabeth guter Hoffnung; sie hielt sich fünf Monate lang in tiefer Zurückgezogenheit und dachte:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 1, 25, '»So hat der Herr an mir getan in der Zeit, die er dazu ersehen hat, meine Schmach bei den Menschen von mir hinwegzunehmen.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 1, 26, 'Im sechsten Monat aber wurde der Engel Gabriel von Gott nach Galiläa in eine Stadt namens Nazareth gesandt');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 1, 27, 'zu einer Jungfrau, die mit einem Manne namens Joseph aus dem Hause Davids verlobt war; die Jungfrau hieß Maria.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 1, 28, 'Als nun der Engel bei ihr eintrat, sagte er: »Sei gegrüßt, du Begnadete: der Herr ist mit dir!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 1, 29, 'Sie wurde über diese Anrede bestürzt und überlegte, was dieser Gruß zu bedeuten habe.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 1, 30, 'Da sagte der Engel zu ihr: »Fürchte dich nicht, Maria, denn du hast Gnade bei Gott gefunden!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 1, 31, 'Wisse wohl: du wirst guter Hoffnung werden und Mutter eines Sohnes, dem du den Namen Jesus geben sollst.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 1, 32, 'Dieser wird groß sein und Sohn des Höchsten genannt werden, und Gott der Herr wird ihm den Thron seines Vaters David geben,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 1, 33, 'und er wird als König über das Haus Jakobs in alle Ewigkeit herrschen, und sein Königtum wird kein Ende haben.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 1, 34, 'Da sagte Maria zu dem Engel: »Wie soll das möglich sein? Ich weiß doch von keinem Manne.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 1, 35, 'Da gab der Engel ihr zur Antwort: »Heiliger Geist wird über dich kommen und die Kraft des Höchsten dich überschatten; daher wird auch das Heilige, das (von dir) geboren werden soll, Gottes Sohn genannt werden.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 1, 36, 'Und nun vernimm: Elisabeth, deine Verwandte, ist ebenfalls trotz ihres hohen Alters mit einem Sohn gesegnet und steht jetzt schon im sechsten Monat, sie, die man unfruchtbar nennt;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 1, 37, 'denn bei Gott ist kein Ding unmöglich.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 1, 38, 'Da sagte Maria: »Siehe, ich bin des Herrn Magd: mir geschehe nach deinem Wort!« Damit schied der Engel von ihr.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 1, 39, 'Maria aber machte sich in jenen Tagen auf und wanderte eilends in das Bergland nach einer Stadt (im Stamme) Juda;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 1, 40, 'dort trat sie in das Haus des Zacharias und begrüßte Elisabeth.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 1, 41, 'Da begab es sich, als Elisabeth den Gruß der Maria vernahm, da bewegte sich das Kind lebhaft in ihrem Leibe; und Elisabeth wurde mit heiligem Geist erfüllt');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 1, 42, 'und brach mit lauter Stimme in die Worte aus: »Gesegnet bist du unter den Frauen, und gesegnet ist die Frucht deines Leibes!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 1, 43, 'Doch woher wird mir die Ehre zuteil, daß die Mutter meines Herrn zu mir kommt?');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 1, 44, 'Denn wisse: als der Klang deines Grußes mir ins Ohr drang, bewegte sich das Kind vor Freude lebhaft in meinem Leibe.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 1, 45, 'O selig die, welche geglaubt hat, denn die Verheißung, die der Herr ihr gegeben hat, wird in Erfüllung gehen!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 1, 46, 'Darauf sprach Maria: »Meine Seele erhebt den Herrn,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 1, 47, 'und mein Geist jubelt über Gott, meinen Retter,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 1, 48, 'weil er die Niedrigkeit seiner Magd angesehen hat! Denn siehe: von nun an werden alle Geschlechter mich selig preisen,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 1, 49, 'weil der Allmächtige Großes an mir getan hat. Ja, heilig ist sein Name,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 1, 50, 'und sein Erbarmen wird von Geschlecht zu Geschlecht denen zuteil, die ihn fürchten.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 1, 51, 'Er wirkt seine Kraft aus mit seinem Arm, er zerstreut, die da hoffärtig sind in ihres Herzens Sinn');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 1, 52, 'er stürzt Machthaber von den Thronen und erhöht Niedrige;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 1, 53, 'Hungrige sättigt er mit Gütern und läßt Reiche leer ausgehen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 1, 54, 'Er hat sich Israels angenommen, seines Knechts, um der Barmherzigkeit zu gedenken,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 1, 55, 'wie er es unsern Vätern verheißen hat, dem Abraham und seinen Nachkommen in Ewigkeit.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 1, 56, 'Maria blieb dann etwa drei Monate bei Elisabeth und kehrte hierauf in ihr Haus zurück.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 1, 57, 'Für Elisabeth aber erfüllte sich die Zeit ihrer Niederkunft, und sie wurde Mutter eines Sohnes.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 1, 58, 'Als nun ihre Nachbarn und Verwandten hörten, daß der Herr ihr so große Barmherzigkeit erwiesen hatte, freuten sie sich mit ihr.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 1, 59, 'Am achten Tage kamen sie zur Beschneidung des Knäbleins und wollten es mit dem Namen seines Vaters Zacharias benennen;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 1, 60, 'doch seine Mutter sagte abwehrend: »Nein, er soll Johannes heißen!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 1, 61, 'Sie entgegneten ihr: »In deiner Verwandtschaft gibt es doch keinen, der diesen Namen führt.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 1, 62, 'Sie winkten nun seinem Vater die Frage zu, wie er ihn benannt haben wolle.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 1, 63, 'Der forderte ein Täfelchen und schrieb die Worte darauf: »Johannes ist sein Name!«, und alle verwunderten sich darüber.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 1, 64, 'In demselben Augenblick aber wurde ihm der Mund aufgetan, und das Band seiner Zunge (löste sich): er konnte wieder reden und pries Gott.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 1, 65, 'Da kam Furcht über alle, die in ihrer Nachbarschaft wohnten, und im ganzen Bergland von Judäa wurden alle diese Begebenheiten viel besprochen,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 1, 66, 'und alle, die von ihnen hörten, nahmen sie sich zu Herzen und sagten: »Was wird wohl aus diesem Kinde werden?« Denn auch die Hand des Herrn war mit ihm.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 1, 67, 'Und sein Vater Zacharias wurde mit heiligem Geist erfüllt und sprach die prophetischen Worte aus:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 1, 68, '»Gepriesen sei der Herr, der Gott Israels!, Denn er hat sein Volk gnädig angesehen und ihm eine Erlösung geschaffen');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 1, 69, 'und hat uns ein Horn des Heils aufgerichtet im Hause Davids, seines Knechtes.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 1, 70, 'So hat er es durch den Mund seiner heiligen Propheten von alters her verheißen:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 1, 71, 'retten will er uns von unsern Feinden und aus der Hand aller, die uns hassen,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 1, 72, 'um unsern Vätern Barmherzigkeit zu erweisen und seines heiligen Bundes zu gedenken,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 1, 73, 'des Eides, den er unserm Vater Abraham geschworen hat, er wolle uns erretten aus der Hand unserer Feinde');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 1, 74, 'und uns verleihen, daß wir ihm furchtlos dienen');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 1, 75, 'in Heiligkeit und Gerechtigkeit vor seinen Augen alle Tage unsers Lebens.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 1, 76, 'Aber auch du, Knäblein, wirst ein Prophet des Höchsten genannt werden; denn du wirst vor dem Herrn einhergehen, ihm die Wege zu bereiten,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 1, 77, 'um seinem Volke die Erkenntnis des Heils zu verschaffen, die ihnen durch Vergebung ihrer Sünden zuteil werden wird.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 1, 78, 'So will es das herzliche Erbarmen unsers Gottes, mit dem uns der Aufgang aus der Höhe erschienen ist,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 1, 79, 'um denen Licht zu spenden, die in Finsternis und Todesschatten sitzen, und unsere Füße auf den Weg des Friedens zu leiten.« –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 1, 80, 'Das Knäblein aber wuchs heran und wurde stark am Geist und hielt sich in der Einöde auf bis zum Tage seines öffentlichen Auftretens vor Israel.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 2, 1, 'Es begab sich aber in jenen Tagen, daß eine Verordnung vom Kaiser Augustus ausging, es solle eine Volkszählung im ganzen römischen Reich vorgenommen werden.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 2, 2, 'Es war dies die erste Zählung, die zu der Zeit stattfand, als Quirinius Statthalter in Syrien war.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 2, 3, 'Da machten alle sich auf, um sich in die Listen eintragen zu lassen, ein jeder in seinem (Heimats-) Ort.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 2, 4, 'So zog denn auch Joseph von Galiläa aus der Stadt Nazareth nach Judäa hinauf nach der Stadt Davids, die Bethlehem heißt, weil er aus Davids Hause und Geschlecht stammte,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 2, 5, 'um sich daselbst mit Maria, seiner jungen Ehefrau, die guter Hoffnung war, einschätzen zu lassen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 2, 6, 'Während ihres dortigen Aufenthalts kam aber für Maria die Stunde ihrer Niederkunft,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 2, 7, 'und sie gebar ihren ersten Sohn, den sie in Windeln wickelte und in eine Krippe legte, weil es sonst keinen Platz in der Herberge für sie gab.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 2, 8, 'Nun waren Hirten in derselben Gegend auf freiem Felde und hielten in jener Nacht Wache bei ihrer Herde.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 2, 9, 'Da trat ein Engel des Herrn zu ihnen, und die Herrlichkeit des Herrn umleuchtete sie, und sie gerieten in große Furcht.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 2, 10, 'Der Engel aber sagte zu ihnen: »Fürchtet euch nicht! Denn wisset wohl: ich verkündige euch große Freude, die dem ganzen Volke widerfahren wird;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 2, 11, 'denn euch ist heute ein Retter geboren, welcher ist Christus, der Herr, in der Stadt Davids.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 2, 12, 'Und dies sei das Erkennungszeichen für euch: Ihr werdet ein neugeborenes Kind finden, das in Windeln gewickelt ist und in einer Krippe liegt.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 2, 13, 'Und plötzlich war bei dem Engel die Menge der himmlischen Heerscharen, die Gott priesen mit den Worten:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 2, 14, '»Ehre sei Gott in Himmelshöhen und Friede auf Erden in den Menschen des (göttlichen) Wohlgefallens!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 2, 15, 'Als hierauf die Engel von ihnen weg in den Himmel zurückgekehrt waren, sagten die Männer, die Hirten, zueinander: »Wir wollen doch bis Bethlehem hinübergehen und uns die Sache ansehen, die sich dort begeben hat und die der Herr uns hat verkünden lassen!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 2, 16, 'So gingen sie denn eilends hin und fanden Maria und Joseph, dazu das Kind, das in der Krippe lag.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 2, 17, 'Als sie es gesehen hatten, teilten sie ihnen die Verkündigung mit, die sie über dieses Kind vernommen hatten;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 2, 18, 'und alle, die es hörten, verwunderten sich über den Bericht der Hirten.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 2, 19, 'Maria aber bewahrte alle diese Mitteilungen im Gedächtnis und bedachte sie in ihrem Herzen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 2, 20, 'Die Hirten aber kehrten wieder zurück; sie priesen und lobten Gott für alles, was sie gehört und gesehen hatten genau so, wie es ihnen (von den Engeln) verkündigt worden war.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 2, 21, 'Als dann acht Tage vergangen waren, so daß man das Kind beschneiden mußte, gab man ihm den Namen Jesus, der schon vor seiner Empfängnis von dem Engel angegeben worden war.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 2, 22, 'Als dann die (vierzig) nach dem mosaischen Gesetz für ihre Reinigung vorgeschriebenen Tage zu Ende waren, brachten sie das Kind nach Jerusalem hinauf, um es dem Herrn darzustellen –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 2, 23, 'wie im Gesetz des Herrn geschrieben steht: »Jedes erstgeborene männliche Kind, das zur Welt kommt, soll als dem Herrn geheiligt gelten« –;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 2, 24, 'zugleich wollten sie das Opfer nach der Vorschrift im Gesetz des Herrn darbringen, nämlich ein Paar Turteltauben oder zwei junge Tauben.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 2, 25, 'Und siehe, da lebte ein Mann in Jerusalem namens Simeon; dieser Mann war gerecht und gottesfürchtig; er wartete auf die Tröstung Israels, und heiliger Geist war auf ihm.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 2, 26, 'Vom heiligen Geist war ihm auch geoffenbart worden, er solle den Tod nicht eher sehen, bevor er den Gesalbten des Herrn gesehen hätte.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 2, 27, 'So kam er denn damals, vom Geist getrieben, in den Tempel; und als die Eltern das Jesuskind hineinbrachten, um nach dem Brauch des Gesetzes mit ihm zu verfahren,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 2, 28, 'da nahm auch er es in seine Arme und pries Gott mit den Worten:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 2, 29, '»Herr, nun entläßt du deinen Knecht, wie du ihm verheißen hast, im Frieden;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 2, 30, 'denn meine Augen haben dein Heil gesehen,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 2, 31, 'das du vor den Augen aller Völker bereitet hast,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 2, 32, 'ein Licht zur Erleuchtung der Heiden und zur Verherrlichung deines Volkes Israel.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 2, 33, 'Die beiden Eltern Jesu verwunderten sich über das, was da über das Kind gesagt wurde.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 2, 34, 'Simeon aber segnete sie und sagte zu Maria, seiner Mutter: »Wisse wohl: dieser ist vielen zum Fallen und (vielen) zum Aufstehen in Israel bestimmt und zu einem Zeichen, das Widerspruch erfährt –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 2, 35, 'und auch dir selbst wird ein Schwert durch die Seele dringen –, auf daß aus vielen Herzen die Gedanken offenbar werden.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 2, 36, 'Es war da auch eine Prophetin Hanna, eine Tochter Phanuels aus dem Stamme Asser, die war hochbetagt; nur sieben Jahre hatte sie nach ihrer Mädchenzeit mit ihrem Manne gelebt');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 2, 37, 'und war dann Witwe geblieben bis (zum Alter von) vierundachtzig Jahren. Sie verließ den Tempel nicht und diente Gott mit Fasten und Beten bei Tag und bei Nacht.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 2, 38, 'Diese trat auch in eben dieser Stunde hinzu, pries Gott und redete von ihm zu allen, die auf die Erlösung Jerusalems warteten.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 2, 39, 'Nachdem sie dann alles nach den Vorschriften im Gesetz des Herrn erfüllt hatten, kehrten sie nach Galiläa in ihre Stadt Nazareth zurück.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 2, 40, 'Der Knabe aber wuchs heran und wurde kräftig und mit Weisheit erfüllt, und die Gnade Gottes war über ihm.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 2, 41, 'Seine Eltern pflegten aber alle Jahre zum Passahfest nach Jerusalem zu wandern.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 2, 42, 'Als er nun zwölf Jahre alt geworden war und sie wie gewöhnlich zur Festzeit hinaufgezogen waren,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 2, 43, 'blieb, als sie die Festtage dort zugebracht hatten und sie sich auf den Heimweg machten, der Knabe Jesus in Jerusalem zurück, ohne daß seine Eltern es bemerkten.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 2, 44, 'In der Meinung, er befinde sich unter der Reisegesellschaft, gingen sie eine Tagereise weit und suchten ihn bei den Verwandten und Bekannten;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 2, 45, 'als sie ihn aber dort nicht fanden, kehrten sie nach Jerusalem zurück und suchten ihn dort.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 2, 46, 'Nach drei Tagen endlich fanden sie ihn, wie er im Tempel mitten unter den Lehrern saß und ihnen zuhörte und auch Fragen an sie richtete;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 2, 47, 'und alle, die ihn hörten, staunten über sein Verständnis und seine Antworten.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 2, 48, 'Als sie ihn dort erblickten, wurden sie betroffen, und seine Mutter sagte zu ihm: »Kind, warum hast du uns das angetan? Bedenke doch: dein Vater und ich suchen dich mit Angst!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 2, 49, 'Da antwortete er ihnen: »Wie habt ihr mich nur suchen können? Wußtet ihr nicht, daß ich im Hause meines Vaters sein muß?«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 2, 50, 'Sie verstanden aber das Wort nicht, das er zu ihnen gesagt hatte. –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 2, 51, 'Er kehrte dann mit ihnen nach Nazareth zurück und war ihnen untertan, und seine Mutter bewahrte alle diese Worte in ihrem Herzen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 2, 52, 'Jesus aber nahm an Weisheit, Körpergröße und Gnade bei Gott und den Menschen zu.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 3, 1, 'Im fünfzehnten Regierungsjahre des Kaisers Tiberius, als Pontius Pilatus Statthalter von Judäa war und Herodes Vierfürst von Galiläa, sein Bruder Philippus Vierfürst von Ituräa und der Landschaft Trachonitis und Lysanias Vierfürst von Abilene,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 3, 2, 'zur Zeit des Hohenpriesters Hannas und Kaiphas: da erging das Wort Gottes an Johannes, den Sohn des Zacharias, in der Wüste.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 3, 3, 'Er durchzog also die ganze Gegend am Jordan und verkündigte eine Taufe der Buße zur Vergebung der Sünden,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 3, 4, 'wie im Buche der Aussprüche des Propheten Jesaja geschrieben steht: »Eine Stimme ruft laut in der Wüste: ›Bereitet dem Herrn den Weg, ebnet ihm seine Pfade!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 3, 5, 'Alle Vertiefungen sollen ausgefüllt und alle Berge und Hügel geebnet werden! Was krumm ist, soll gerade und was uneben ist, soll zu glattem Wege werden,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 3, 6, 'und die gesamte Menschheit soll das Heil Gottes sehen!‹«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 3, 7, 'So sprach Johannes denn zu den Volksscharen, die zu ihm hinauszogen, um sich von ihm taufen zu lassen: »Ihr Schlangenbrut! Wer hat euch darauf gebracht, dem drohenden Zorngericht entfliehen zu wollen?');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 3, 8, 'So bringet denn Früchte, die der Buße würdig sind, und laßt euch nicht in den Sinn kommen, bei euch zu sagen: ›Wir haben ja doch Abraham zum Vater!‹, denn ich sage euch: Gott vermag dem Abraham aus den Steinen hier Kinder zu erwecken.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 3, 9, 'Schon ist aber auch die Axt den Bäumen an die Wurzel gelegt, und jeder Baum, der nicht gute Früchte bringt, wird abgehauen und ins Feuer geworfen.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 3, 10, 'Da fragte ihn die Volksmenge: »Was sollen wir denn tun?«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 3, 11, 'Er gab ihnen zur Antwort: »Wer zwei Röcke hat, der gebe einen davon dem ab, der keinen hat, und wer zu essen hat, mache es ebenso!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 3, 12, 'Es kamen auch Zöllner, um sich taufen zu lassen, und fragten ihn: »Meister, was sollen wir tun?«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 3, 13, 'Er antwortete ihnen: »Fordert nicht mehr (Geld von den Leuten), als euch vorgeschrieben ist!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 3, 14, 'Es fragten ihn auch Kriegsleute: »Was sollen wir tun?« Er antwortete ihnen: »Tut niemand Gewald an, verübt keine Erpressungen und begnügt euch mit eurer Löhnung!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 3, 15, 'Als nun das Volk in gespannter Erwartung war und alle sich in ihren Herzen Gedanken über Johannes machten, ob er nicht vielleicht selbst der Christus sei,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 3, 16, 'antwortete Johannes allen mit den Worten: »Ich taufe euch (nur) mit Wasser; es kommt aber der, welcher stärker ist als ich und für den ich nicht gut genug bin, ihm die Riemen seiner Schuhe aufzubinden: der wird euch mit heiligem Geist und mit Feuer taufen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 3, 17, 'Er hat seine Worfschaufel in der Hand, um seine Tenne gründlich zu reinigen, und er wird den Weizen in seine Scheuer sammeln, die Spreu aber mit unauslöschlichem Feuer verbrennen.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 3, 18, 'Auch noch viele andere Ermahnungen richtete er an das Volk und verkündigte ihm die Heilsbotschaft.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 3, 19, 'Der Vierfürst Herodes aber, dem er wegen Herodias, der Frau seines Bruders, und wegen alles Bösen, das Herodes verübt hatte, Vorhaltungen gemacht hatte,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 3, 20, 'fügte zu allen Übeltaten auch noch die hinzu, daß er Johannes ins Gefängnis werfen ließ.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 3, 21, 'Es begab sich aber, als das gesamte Volk sich taufen ließ und auch Jesus getauft worden war und betete, daß der Himmel sich auftat');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 3, 22, 'und der heilige Geist in leiblicher Gestalt wie eine Taube auf ihn herabschwebte und eine Stimme aus dem Himmel erscholl: »Du bist mein geliebter Sohn, an dir habe ich Wohlgefallen gefunden!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 3, 23, 'Und er, Jesus, war bei seinem Auftreten etwa dreißig Jahre alt und war, wie man meinte, der Sohn Josephs,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 3, 24, 'des Sohnes des Eli, des Matthat, des Levi, des Melchi, des Jannai, des Joseph,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 3, 25, 'des Mattathias, des Amos, des Nahum,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 3, 26, 'des Esli, des Naggai, des Maath, des Mattathias, des Semein, des Jose, des Joda,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 3, 27, 'des Johanan, des Resa, des Serubbabel, des Salathiel, des Neri,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 3, 28, 'des Melchi, des Addi, des Kosam, des Elmadam, des Er,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 3, 29, 'des Josua, des Elieser, des Jorim, des Matthath, des Levi,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 3, 30, 'des Simeon, des Juda, des Joseph, des Jona, des Eljakim,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 3, 31, 'des Melea, des Menna, des Matthatha, des Nathan, des David,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 3, 32, 'des Jesse, des Jobed, des Boas, des Sala, des Nahason,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 3, 33, 'des Amminadab, des Admin, des Arni, des Hezron, des Phares, des Juda,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 3, 34, 'des Jakob, des Isaak, des Abraham, des Tharah, des Nahor,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 3, 35, 'des Serug, des Regu, des Peleg, des Eber, des Selah,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 3, 36, 'des Kainan, des Arphachsad, des Sem, des Noah, des Lamech,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 3, 37, 'des Methusalah, des Henoch, des Jared, des Mahalaleel, des Kenan,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 3, 38, 'des Enos, des Seth, des Adam, – Gottes.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 4, 1, 'Jesus kehrte dann, voll heiligen Geistes, vom Jordan zurück und wurde vom Geist vierzig Tage lang in der Wüste (umher) geführt');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 4, 2, 'und dabei vom Teufel versucht. Er aß in diesen Tagen nichts, so daß ihn hungerte, als sie zu Ende waren.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 4, 3, 'Da sagte der Teufel zu ihm: »Bist du Gottes Sohn, so gebiete diesem Steine hier, er solle zu Brot werden!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 4, 4, 'Doch Jesus antwortete ihm: »Es steht geschrieben: ›Nicht vom Brot allein wird der Mensch leben!‹«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 4, 5, 'Hierauf führte ihn der Teufel in die Höhe, zeigte ihm in einem Augenblick alle Reiche des Erdkreises');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 4, 6, 'und sagte zu ihm: »Dir will ich diese ganze Macht und ihre Herrlichkeit geben; denn mir ist sie übergeben, und ich kann sie geben, wem ich will.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 4, 7, 'Wenn du also vor mir (niederfällst und mich) anbetest, so soll sie ganz dir gehören.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 4, 8, 'Da gab ihm Jesus zur Antwort: »Es steht geschrieben: ›Du sollst den Herrn, deinen Gott, anbeten und ihm allein dienen!‹«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 4, 9, 'Hierauf führte der Teufel ihn nach Jerusalem, stellte ihn auf die Zinne des Tempels und sagte zu ihm: »Bist du Gottes Sohn, so stürze dich von hier hinab!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 4, 10, 'Denn es steht geschrieben: ›Er wird seine Engel für dich entbieten, daß sie dich behüten,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 4, 11, 'und sie werden dich auf den Armen tragen, damit du mit deinem Fuß an keinen Stein stoßest.‹«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 4, 12, 'Da antwortete ihm Jesus: »Es ist gesagt: ›Du sollst den Herrn, deinen Gott, nicht versuchen!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 4, 13, 'Als der Teufel nun mit allen Versuchungen zu Ende war, ließ er von ihm ab bis zu einer gelegenen Zeit.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 4, 14, 'Jesus kehrte dann in der Kraft des Geistes nach Galiläa zurück, und die Kunde von ihm verbreitete sich in der ganzen Umgegend.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 4, 15, 'Er lehrte in ihren Synagogen und wurde (wegen seiner Lehre) von allen gepriesen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 4, 16, 'So kam er denn auch nach Nazareth, wo er aufgewachsen war, ging dort nach seiner Gewohnheit am nächsten Sabbattage in die Synagoge und stand auf, um vorzulesen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 4, 17, 'Da reichte man ihm das Buch des Propheten Jesaja; und als er das Buch aufrollte, traf er auf die Stelle, wo geschrieben steht:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 4, 18, '»Der Geist des Herrn ist über mir, weil er mich gesalbt hat, damit ich den Armen die frohe Botschaft bringe; er hat mich gesandt, um den Gefangenen die Freilassung und den Blinden die Verleihung des Augenlichts zu verkünden, die Unterdrückten in Freiheit zu entlassen,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 4, 19, 'ein Gnadenjahr des Herrn auszurufen.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 4, 20, 'Nachdem er dann das Buch wieder zusammengerollt und es dem Diener zurückgegeben hatte, setzte er sich, und aller Augen in der Synagoge waren gespannt auf ihn gerichtet.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 4, 21, 'Da begann er seine Ansprache an sie mit den Worten: »Heute ist dieses Schriftwort, das ihr soeben vernommen habt, zur Erfüllung gekommen!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 4, 22, 'Und alle stimmten ihm zu und staunten über die Worte der Gnade, die aus seinem Munde kamen, und sagten: »Ist dieser nicht der Sohn Josephs?«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 4, 23, 'Da antwortete er ihnen: »Jedenfalls werdet ihr mir das Sprichwort vorhalten: ›Arzt, mache dich selber gesund!‹ Alle die großen Taten, die (von dir), wie wir gehört haben, in Kapernaum vollbracht worden sind, die vollführe auch hier in deiner Vaterstadt!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 4, 24, 'Er fuhr dann aber fort: »Wahrlich ich sage euch: Kein Prophet ist in seiner Vaterstadt willkommen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 4, 25, 'In Wahrheit aber sage ich euch: Viele Witwen gab es in Israel in den Tagen Elias, als der Himmel drei Jahre und sechs Monate lang verschlossen blieb, so daß eine große Hungersnot über die ganze Erde kam;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 4, 26, 'und doch wurde Elia zu keiner einzigen von ihnen gesandt, sondern nur nach Sarepta im Gebiet von Sidon zu einer Witwe.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 4, 27, 'Und viele Aussätzige gab es in Israel zur Zeit des Propheten Elisa, und doch wurde kein einziger von ihnen gereinigt, sondern nur der Syrer Naeman.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 4, 28, 'Als sie das hörten, gerieten alle, die in der Synagoge anwesend waren, in heftigen Zorn:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 4, 29, 'sie standen auf, stießen ihn aus der Stadt hinaus und führten ihn an den Rand des Berges, auf dem ihre Stadt erbaut war, um ihn dort hinabzustürzen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 4, 30, 'Er ging aber mitten durch sie hindurch und wanderte weiter.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 4, 31, 'Er begab sich dann nach der galiläischen Stadt Kapernaum hinab und lehrte sie dort am Sabbat.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 4, 32, 'Da gerieten sie über seine Lehre in Staunen, denn seine Rede beruhte auf (göttlicher) Vollmacht.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 4, 33, 'Nun war da in der Synagoge ein Mann, der von einem unreinen Geiste besessen war; der schrie laut auf:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 4, 34, '»Ha! Was willst du von uns, Jesus von Nazareth? Du bist gekommen, um uns zu vernichten! Ich weiß wohl, wer du bist: der Heilige Gottes!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 4, 35, 'Jesus bedrohte ihn mit den Worten: »Verstumme und fahre von ihm aus!« Da warf der böse Geist den Mann mitten unter sie zu Boden und fuhr von ihm aus, ohne ihm irgendwelchen Schaden zuzufügen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 4, 36, 'Da gerieten sie alle in Staunen; sie besprachen sich miteinander und sagten: »Was ist das für ein Machtwort? Mit (göttlicher) Vollmacht und Kraft gebietet er den unreinen Geistern, und sie fahren aus!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 4, 37, 'Und die Kunde von ihm verbreitete sich in alle Orte der Umgegend.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 4, 38, 'Nachdem er dann die Synagoge verlassen hatte, begab er sich in das Haus Simons. Dort war die Schwiegermutter Simons von hohem Fieber befallen, und man wandte sich ihretwegen an ihn.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 4, 39, 'Er trat also zu ihr, beugte sich über sie und bedrohte das Fieber: da wich es von ihr; sie stand sogleich vom Lager auf und bediente sie (bei der Mahlzeit).');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 4, 40, 'Als dann die Sonne unterging, brachten alle, welche Kranke mit mancherlei Leiden hatten, sie zu ihm; er aber legte einem jeden von ihnen die Hände auf und heilte sie.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 4, 41, 'Auch böse Geister fuhren von vielen aus, wobei sie laut schrien und ausriefen: »Du bist der Sohn Gottes!« Er bedrohte sie jedoch und ließ sie nicht zu Worte kommen; denn sie wußten, daß er Christus war.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 4, 42, 'Bei Tagesanbruch aber entwich er von dort und begab sich an einen einsamen Ort; doch die Volksmenge suchte nach ihm und kam zu ihm hin und wollte ihn zurückhalten, damit er nicht von ihnen wegginge.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 4, 43, 'Er aber sagte zu ihnen: »Ich muß auch den anderen Städten die Heilsbotschaft vom Reiche Gottes verkünden, denn dazu bin ich gesandt.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 4, 44, 'So predigte er denn in den Synagogen des jüdischen Landes.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 5, 1, 'Es begab sich aber (eines Tages), als das Volk ihn umdrängte und das Wort Gottes hörte, während er selbst am See Gennesaret stand,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 5, 2, 'da sah er zwei Boote am Ufer des Sees liegen; die Fischer aber waren aus ihnen ausgestiegen und wuschen ihre Netze.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 5, 3, 'Da trat er in eins der Boote, das Simon gehörte, und bat ihn, ein wenig vom Lande abzustoßen; darauf setzte er sich nieder und lehrte die Volksscharen vom Boote aus.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 5, 4, 'Als er dann seine Ansprache beendet hatte, sagte er zu Simon: »Fahre auf die Höhe (des Sees) hinaus und werft eure Netze aus, damit ihr einen Zug tut!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 5, 5, 'Da antwortete Simon: »Meister, die ganze Nacht hindurch haben wir gearbeitet und nichts gefangen; doch auf dein Wort hin will ich die Netze auswerfen.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 5, 6, 'Als sie das getan hatten, fingen sie eine so große Menge Fische, daß ihre Netze zerreißen wollten.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 5, 7, 'Da winkten sie ihren Genossen, die in dem andern Boot waren, sie möchten kommen und ihnen helfen; die kamen auch, und man füllte beide Boote, so daß sie tiefgingen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 5, 8, 'Als Simon Petrus das sah, warf er sich vor Jesus auf die Knie nieder und rief aus: »Herr, gehe weg von mir, denn ich bin ein sündiger Mensch!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 5, 9, 'Denn Schrecken hatte ihn und alle, die bei ihm waren, wegen dieses ihres Fischfangs befallen,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 5, 10, 'ebenso auch den Jakobus und Johannes, die Söhne des Zebedäus, welche Simons Genossen waren. Doch Jesus sagte zu Simon: »Fürchte dich nicht! Von nun an wirst du ein Menschenfischer sein.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 5, 11, 'Sie brachten nun die Boote an Land, verließen alles und folgten ihm nach.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 5, 12, 'Es begab sich darauf, während er sich in einer der Städte aufhielt, daß ein Mann da war, über und über mit Aussatz behaftet. Als dieser Jesus sah, warf er sich vor ihm auf sein Angesicht nieder und bat ihn mit den Worten: »Herr, wenn du willst, kannst du mich reinigen!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 5, 13, 'Jesus streckte die Hand aus, faßte ihn an und sagte: »Ich will’s: werde rein!« Da verschwand der Aussatz sogleich von ihm.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 5, 14, 'Jesus gebot ihm dann, niemand etwas davon zu sagen, und gab ihm die Weisung: »Gehe hin, zeige dich dem Priester und bringe für deine Reinigung das Opfer dar, wie Mose es geboten hat, zum Zeugnis für sie!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 5, 15, 'Aber die Kunde über ihn breitete sich immer weiter aus, und das Volk strömte in großen Scharen zusammen, um ihn zu hören und sich von ihren Krankheiten heilen zu lassen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 5, 16, 'Er jedoch zog sich in die Einsamkeit zurück und betete dort.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 5, 17, 'Eines Tages, als er der Lehrtätigkeit oblag, saßen auch Pharisäer und Gesetzeslehrer da, die aus allen Ortschaften Galiläas und Judäas und (besonders) aus Jerusalem gekommen waren; und die Kraft des Herrn war durch ihn wirksam, so daß er Heilungen vollbrachte.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 5, 18, 'Da brachten Männer auf einem Tragbett einen Mann, der gelähmt war, und suchten ihn in das Haus hineinzubringen und vor Jesus niederzusetzen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 5, 19, 'Weil sie aber wegen der Volksmenge keine Möglichkeit fanden, ihn hineinzubringen, stiegen sie auf das Dach und ließen ihn samt dem Tragbett durch die Ziegel hindurch mitten unter die Leute vor Jesus hinab.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 5, 20, 'Als dieser ihren Glauben sah, sagte er: »Mensch, deine Sünden sind dir vergeben!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 5, 21, 'Da begannen die Schriftgelehrten und Pharisäer sich Gedanken darüber zu machen und sagten: »Wer ist dieser? Er spricht ja Gotteslästerungen aus! Wer kann Sünden vergeben außer Gott allein?«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 5, 22, 'Weil nun Jesus ihre Gedanken durchschaute, redete er sie mit den Worten an: »Was denkt ihr da in euren Herzen?');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 5, 23, 'Was ist leichter, zu sagen: ›Deine Sünden sind dir vergeben‹, oder zu sagen: ›Stehe auf und gehe umher‹?');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 5, 24, 'Damit ihr aber wißt, daß der Menschensohn Vollmacht hat, auf der Erde Sünden zu vergeben« – hierauf sagte er zu dem Gelähmten: »Ich sage dir: Stehe auf, nimm dein Bett auf dich und gehe heim in dein Haus!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 5, 25, 'Da stand er augenblicklich vor ihren Augen auf, nahm das (Tragbett), auf dem er gelegen hatte, und ging Gott preisend heim in sein Haus.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 5, 26, 'Da gerieten alle außer sich vor Erstaunen; sie priesen Gott und sagten voller Furcht: »Unglaubliches haben wir heute gesehen!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 5, 27, 'Hierauf ging er (aus dem Hause) hinaus und sah einen Zöllner namens Levi an der Zollstätte sitzen und sagte zu ihm: »Folge mir nach!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 5, 28, 'Da verließ jener alles, stand auf und folgte ihm nach.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 5, 29, 'Und Levi richtete ihm zu Ehren ein großes Gastmahl in seinem Hause zu, und eine große Schar von Zöllnern und anderen Leuten waren da, die mit ihnen am Mahl teilnahmen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 5, 30, 'Da sagten die Pharisäer und die zu ihnen gehörenden Schriftgelehrten unwillig zu seinen Jüngern: »Warum eßt und trinkt ihr mit den Zöllnern und Sündern?«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 5, 31, 'Jesus antwortete ihnen mit den Worten: »Die Gesunden haben keinen Arzt nötig, wohl aber die Kranken;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 5, 32, 'ich bin nicht gekommen, Gerechte zu berufen zur Buße, sondern Sünder.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 5, 33, 'Sie aber sagten zu ihm: »Die Jünger des Johannes fasten häufig und verrichten (dabei) Gebete, ebenso auch die (Schüler) der Pharisäer, während die deinigen essen und trinken.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 5, 34, 'Jesus antwortete ihnen: »Könnt ihr etwa von den Hochzeitsgästen verlangen, daß sie fasten, solange der Bräutigam noch bei ihnen weilt?');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 5, 35, 'Es werden aber Tage kommen, wo der Bräutigam ihnen genommen ist: dann, an jenen Tagen, werden sie fasten.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 5, 36, 'Er legte ihnen aber auch noch ein Gleichnis vor: »Niemand reißt doch von einem neuen Kleid ein Stück Zeug ab und setzt es auf ein altes Kleid, sonst würde er nur das neue (Kleid) zerreißen, und zu dem alten Kleide würde das Stück Zeug von dem neuen (Kleide) doch nicht passen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 5, 37, 'Auch füllt niemand neuen Wein in alte Schläuche; sonst sprengt der junge Wein die Schläuche und läuft selbst aus, und auch die Schläuche gehen verloren.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 5, 38, 'Nein, jungen Wein muß man in neue Schläuche füllen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 5, 39, 'Und niemand, der alten Wein getrunken hat, mag jungen Wein trinken; denn er sagt: ›Der alte ist bekömmlich.‹«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 6, 1, 'Es begab sich aber an einem Sabbat, daß er durch die Kornfelder wanderte; dabei pflückten seine Jünger Ähren ab, zerrieben sie in den Händen und aßen sie.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 6, 2, 'Da sagten einige von den Pharisäern zu ihnen: »Warum tut ihr da etwas, das man am Sabbat nicht tun darf?«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 6, 3, 'Jesus antwortete ihnen: »Habt ihr auch davon nichts gelesen, was David getan hat, als ihn samt seinen Begleitern hungerte?');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 6, 4, 'Wie er da ins Gotteshaus hineinging, dort die Schaubrote nahm und sie aß und auch seinen Begleitern davon gab, obgleich doch niemand außer den Priestern sie essen darf?«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 6, 5, 'Er schloß mit den Worten: »Der Menschensohn ist Herr (auch) über den Sabbat.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 6, 6, 'An einem anderen Sabbat aber ging er in die Synagoge und lehrte. Dort war ein Mann, dessen rechter Arm verdorrt war.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 6, 7, 'Da lauerten die Schriftgelehrten und Pharisäer ihm auf, ob er wohl am Sabbat heilen würde, um dann einen Grund zu einer Anklage gegen ihn zu haben;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 6, 8, 'er aber kannte ihre Gedanken wohl. Er sagte nun zu dem Manne mit dem gelähmten Arm: »Stehe auf und tritt vor in die Mitte!« Jener stand auf und trat hin.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 6, 9, 'Dann sagte Jesus zu ihnen: »Ich frage euch: Darf man am Sabbat Gutes tun, oder soll man Böses tun? Darf man ein Leben erhalten, oder soll man es zugrunde gehen lassen?«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 6, 10, 'Nachdem er sie dann alle ringsum (zornig) angeblickt hatte, sagte er zu ihm: »Strecke deinen Arm aus!« Jener tat es, und sein Arm wurde wieder hergestellt.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 6, 11, 'Jene aber wurden ganz sinnlos vor Wut und besprachen sich miteinander, was sie Jesus antun könnten.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 6, 12, 'Es begab sich aber in diesen Tagen, daß er hinausging auf den Berg, um zu beten, und er verbrachte dort die (ganze) Nacht im Gebet zu Gott.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 6, 13, 'Als es dann Tag geworden war, rief er seine Jünger zu sich und wählte zwölf aus ihnen aus, die er auch Apostel nannte:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 6, 14, 'Simon, den er auch Petrus nannte, und dessen Bruder Andreas; ferner Jakobus und Johannes, Philippus und Bartholomäus,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 6, 15, 'Matthäus und Thomas, Jakobus, den Sohn des Alphäus, und Simon mit dem Beinamen ›der Eiferer‹,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 6, 16, 'Judas, den Sohn des Jakobus, und Judas Iskarioth, der (später) zum Verräter an ihm wurde.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 6, 17, 'Als er dann mit ihnen (vom Berge) wieder hinabgestiegen war, blieb er auf einem ebenen Platz stehen samt einer großen Schar seiner Jünger und einer zahlreichen Volksmenge aus dem ganzen jüdischen Lande, besonders aus Jerusalem, auch aus dem Küstenlande von Tyrus und Sidon.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 6, 18, 'Alle diese waren gekommen, um ihn zu hören und sich von ihren Krankheiten heilen zu lassen; auch die von unreinen Geistern Geplagten fanden Heilung;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 6, 19, 'und die ganze Volksmenge suchte ihn anzurühren, denn eine Kraft ging von ihm aus und heilte alle.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 6, 20, 'Da richtete er seine Augen auf seine Jünger und sagte: »Selig seid ihr Armen, denn euer Teil ist das Reich Gottes!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 6, 21, 'Selig seid ihr, die ihr jetzt hungert, denn ihr werdet gesättigt werden! Selig seid ihr, die ihr jetzt weint, denn ihr werdet lachen!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 6, 22, 'Selig seid ihr, wenn die Menschen euch hassen und wenn sie euch aus ihrer Gemeinschaft ausschließen und euch schmähen und euren Namen als ein Schimpfwort verwerfen um des Menschensohnes willen!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 6, 23, 'Freuet euch alsdann und jubelt! Denn wisset wohl: euer Lohn ist groß im Himmel. Ihre Väter haben ja an den Propheten ebenso gehandelt.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 6, 24, 'Doch wehe euch Reichen, denn ihr habt euren Trost dahin!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 6, 25, 'Wehe euch, die ihr jetzt satt seid, denn ihr werdet Hunger leiden! Wehe euch, die ihr jetzt lacht, denn ihr werdet trauern und weinen!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 6, 26, 'Wehe euch, wenn alle Welt mit Lobesworten von euch redet! Ihre Väter haben ja an den falschen Propheten ebenso gehandelt.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 6, 27, '»Euch aber, meinen Hörern, sage ich: Liebet eure Feinde, tut denen Gutes, die euch hassen,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 6, 28, 'segnet die, welche euch fluchen, betet für die, welche euch anfeinden!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 6, 29, 'Wer dich auf die Wange schlägt, dem halte auch die andere hin, und wer dir den Mantel wegnimmt, dem verweigere auch den Rock nicht!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 6, 30, 'Jedem, der dich (um etwas) bittet, dem gib, und wer dir das Deine nimmt, von dem fordere es nicht zurück!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 6, 31, 'Und wie ihr von den Leuten behandelt werden wollt, ebenso behandelt auch ihr sie!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 6, 32, 'Denn wenn ihr (nur) die liebt, die euch lieben: welchen (Anspruch auf) Dank habt ihr dann? Auch die Sünder lieben ja die, welche ihnen Liebe erweisen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 6, 33, 'Und wenn ihr (nur) denen Gutes erweist, die euch Gutes tun: welchen (Anspruch auf) Dank habt ihr dann? Auch die Sünder tun dasselbe.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 6, 34, 'Und wenn ihr denen leiht, von denen ihr (das Geliehene) zurückzuerhalten hofft: welchen (Anspruch auf) Dank habt ihr dann? Auch die Sünder leihen den Sündern, um ebensoviel zurückzuerhalten.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 6, 35, 'Nein, liebet eure Feinde, tut Gutes und leihet aus, ohne etwas zurückzuerwarten! Dann wird euer Lohn groß sein, und ihr werdet Söhne des Höchsten sein; denn er ist gütig (auch) gegen die Undankbaren und Bösen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 6, 36, 'Seid barmherzig, wie euer Vater barmherzig ist!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 6, 37, '»Und richtet nicht, dann werdet ihr auch nicht gerichtet werden; und verurteilt nicht, dann werdet ihr auch nicht verurteilt werden; laßt (eure Schuldner) frei, dann werdet ihr auch freigelassen werden.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 6, 38, 'Gebt, dann wird auch euch gegeben werden: ein reichliches, festgedrücktes, gerütteltes und übervolles Maß wird man euch in den Schoß schütten; denn mit demselben Maß, mit dem ihr zumeßt, wird euch wieder zugemessen werden.« –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 6, 39, 'Er legte ihnen dann auch ein Gleichnis vor: »Kann wohl ein Blinder einen Blinden führen? Werden sie nicht beide in die Grube fallen?');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 6, 40, 'Der Jünger steht nicht über seinem Meister: jeder (Jünger) wird, wenn er völlig ausgebildet ist, immer nur wie sein Meister sein.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 6, 41, 'Was siehst du aber den Splitter im Auge deines Bruders, während du den Balken in deinem eignen Auge nicht wahrnimmst?');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 6, 42, 'Oder wie darfst du zu deinem Bruder sagen: ›Bruder, laß mich den Splitter, der in deinem Auge steckt, herausziehen‹, während du den Balken in deinem eignen Auge nicht gewahrst? Du Heuchler! Ziehe zuerst den Balken aus deinem Auge, dann magst du zusehen, daß du den Splitter herausziehst, der im Auge deines Bruders steckt.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 6, 43, '»Denn es gibt keinen guten Baum, der schlechte Früchte bringt, und umgekehrt keinen schlechten Baum, der gute Früchte bringt.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 6, 44, 'Jeden Baum erkennt man ja an seinen Früchten; denn von Dornen sammelt man keine Feigen, und von einem Dornbusch kann man keine Trauben lesen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 6, 45, 'Ein guter Mensch bringt aus der guten Schatzkammer seines Herzens das Gute hervor, während ein böser Mensch aus der bösen (Schatzkammer seines Herzens) das Böse hervorbringt; denn wovon das Herz voll ist, davon redet sein Mund.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 6, 46, '»Was nennt ihr mich aber ›Herr, Herr!‹ und tut doch nicht, was ich (euch) sage?');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 6, 47, 'Wer zu mir kommt und meine Worte hört und nach ihnen tut – ich will euch zeigen, wem der zu vergleichen ist:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 6, 48, 'Er gleicht einem Manne, der, als er ein Haus bauen wollte, bis in die Tiefe ausgraben ließ und die Grundmauer auf den Felsen legte. Als nun Hochwasser kam, stieß die Flut an jenes Haus, vermochte es aber wegen seiner festen Bauart nicht zu erschüttern.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 6, 49, 'Wer aber (meine Worte) hört und nicht nach ihnen tut, der gleicht einem Manne, der ein Haus ohne feste Grundmauer auf den (lockeren) Erdboden baute. Als dann die Flut dagegen stieß, stürzte es sogleich in sich zusammen, und der Einsturz dieses Hauses war gewaltig.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 7, 1, 'Nachdem Jesus alle seine Reden an das Volk, das ihm zuhörte, beendet hatte, ging er nach Kapernaum hinein.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 7, 2, 'Dort lag der Diener eines Hauptmanns, der diesem besonders wert war, todkrank darnieder.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 7, 3, 'Weil nun der Hauptmann von Jesus gehört hatte, sandte er Älteste der Juden zu ihm mit der Bitte, er möchte kommen und seinen Diener gesund machen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 7, 4, 'Als diese zu Jesus kamen, baten sie ihn inständig mit den Worten: »Er verdient es, daß du ihm diese Bitte erfüllst;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 7, 5, 'denn er hat unser Volk lieb, und er ist es, der uns unsere Synagoge gebaut hat.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 7, 6, 'Da machte sich Jesus mit ihnen auf den Weg. Als er aber nicht mehr weit von dem Hause entfernt war, sandte der Hauptmann Freunde ab und ließ ihm sagen: »Herr, bemühe dich nicht, denn ich bin nicht wert, daß du unter mein Dach trittst.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 7, 7, 'Darum habe ich mich auch nicht für würdig gehalten, selbst zu dir zu kommen; sprich vielmehr nur ein Wort, so muß mein Diener gesund werden.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 7, 8, 'Denn auch ich bin ein Mensch, der unter Vorgesetzten steht, und habe Mannschaften unter mir; und wenn ich zu einem sage: ›Geh!‹, so geht er, und zu einem anderen: ›Komm!‹, so kommt er, und zu meinem Diener: ›Tu das!‹, so tut er’s.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 7, 9, 'Als Jesus das hörte, wunderte er sich über ihn und sagte, zu der ihn begleitenden Volksmenge gewandt: »Ich sage euch: Selbst in Israel habe ich solchen Glauben nicht gefunden!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 7, 10, 'Als dann die Abgesandten in das Haus (des Hauptmanns) zurückkehrten, fanden sie den Diener von seiner Krankheit genesen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 7, 11, 'Kurze Zeit darauf begab es sich, daß Jesus nach einer Stadt namens Nain wanderte, und mit ihm zogen seine Jünger und eine große Volksschar.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 7, 12, 'Als er sich nun dem Stadttor näherte, da trug man gerade einen Toten heraus, den einzigen Sohn seiner Mutter, und die war eine Witwe; und eine große Volksmenge aus der Stadt gab ihr das Geleit.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 7, 13, 'Als der Herr sie sah, ging ihr Unglück ihm zu Herzen, und er sagte zu ihr: »Weine nicht!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 7, 14, 'Dann trat er hinzu und faßte die Bahre an; da standen die Träger still, und er sprach: »Jüngling, ich sage dir: stehe auf!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 7, 15, 'Da setzte der Tote sich aufrecht hin und fing an zu reden; und Jesus gab ihn seiner Mutter wieder.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 7, 16, 'Da kam Furcht über alle, und sie priesen Gott und sagten: »Ein großer Prophet ist unter uns erstanden!« und: »Gott hat sein Volk gnädig angesehen!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 7, 17, 'Die Kunde von dieser seiner Tat aber verbreitete sich im ganzen jüdischen Lande und in allen umliegenden Gegenden.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 7, 18, 'Auch dem Johannes erstatteten seine Jünger Bericht über dies alles. Da rief Johannes zwei von seinen Jüngern zu sich,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 7, 19, 'sandte sie zum Herrn und ließ ihn fragen: »Bist du es, der da kommen soll, oder sollen wir auf einen andern warten?«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 7, 20, 'Als nun die Männer bei Jesus eintrafen, sagten sie: »Johannes der Täufer hat uns zu dir gesandt und läßt dich fragen: ›Bist du es, der da kommen soll, oder sollen wir auf einen andern warten?‹«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 7, 21, 'Jesus heilte in eben jener Stunde viele von Krankheiten, von schmerzhaften Leiden und bösen Geistern und schenkte vielen Blinden das Augenlicht.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 7, 22, 'So gab er ihnen denn zur Antwort: »Geht hin und berichtet dem Johannes, was ihr (hier) gesehen und gehört habt: Blinde werden sehend, Lahme gehen, Aussätzige werden rein, Taube hören, Tote werden auferweckt, Armen wird die Heilsbotschaft verkündigt,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 7, 23, 'und selig ist, wer an mir nicht irre wird.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 7, 24, 'Als nun die Boten des Johannes wieder weggegangen waren, begann Jesus zu der Volksmenge über Johannes zu reden: »Was wolltet ihr sehen, als ihr (jüngst) in die Wüste hinauszogt? Etwa ein Schilfrohr, das vom Winde hin und her bewegt wird?');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 7, 25, 'Nein; aber wozu seid ihr hinausgezogen? Wolltet ihr einen Mann in weichen Gewändern sehen? Nein; die Leute, welche prächtige Kleidung tragen und in Üppigkeit leben, sind in den Königspalästen zu finden.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 7, 26, 'Aber wozu seid ihr hinausgezogen? Wolltet ihr einen Propheten sehen? Ja, ich sage euch: Mehr noch als einen Propheten!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 7, 27, 'Dieser ist es, über den geschrieben steht: ›Siehe, ich sende meinen Boten vor dir her, der deinen Weg vor dir her bereiten soll.‹');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 7, 28, 'Ja, ich sage euch: Unter den von Frauen Geborenen gibt es keinen größeren (Propheten) als Johannes; aber der Kleinste im Reiche Gottes ist größer als er.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 7, 29, 'Und das gesamte Volk, das ihn hörte, auch die Zöllner sind dem Willen Gottes nachgekommen, indem sie sich mit der Taufe des Johannes taufen ließen;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 7, 30, 'aber die Pharisäer und die Gesetzeslehrer haben den Heilsratschluß Gottes für ihre Person verworfen, indem sie sich von ihm nicht taufen ließen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 7, 31, 'Wem soll ich nun die Menschen des gegenwärtigen Zeitalters vergleichen? Wem sind sie gleich?');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 7, 32, 'Sie sind wie Kinder, die auf einem öffentlichen Platze sitzen und einander zurufen: ›Wir haben euch gepfiffen, doch ihr habt nicht getanzt! Wir haben Klagelieder angestimmt, doch ihr habt nicht geweint!‹');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 7, 33, 'Denn Johannes der Täufer ist gekommen, der kein Brot aß und keinen Wein trank; da sagt ihr: ›Er ist von Sinnen!‹');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 7, 34, 'Nun ist der Menschensohn gekommen, welcher ißt und trinkt; da sagt ihr: ›Seht, ein Fresser und Weintrinker, ein Freund von Zöllnern und Sündern!‹');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 7, 35, 'Und doch ist die (göttliche) Weisheit gerechtfertigt worden von allen ihren Kindern.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 7, 36, 'Es lud ihn aber einer von den Pharisäern ein, bei ihm zu speisen; er ging denn auch in die Wohnung des Pharisäers und nahm bei Tische Platz.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 7, 37, 'Und siehe, eine Frau, die in der Stadt als Sünderin lebte und erfahren hatte, daß Jesus im Hause des Pharisäers zu Gaste sei, brachte ein Alabasterfläschchen mit Myrrhenöl');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 7, 38, 'und begann, indem sie von hinten an seine Füße herantrat und weinte, seine Füße mit ihren Tränen zu benetzen und sie mit ihrem Haupthaar zu trocknen; dann küßte sie seine Füße und salbte sie mit dem Myrrhenöl.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 7, 39, 'Als nun der Pharisäer, der ihn eingeladen hatte, das sah, dachte er bei sich: »Wenn dieser wirklich ein Prophet wäre, so müßte er wissen, wer und was für eine Frau das ist, die ihn da berührt, daß sie nämlich eine Sünderin ist.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 7, 40, 'Da nahm Jesus das Wort und sagte zu ihm: »Simon, ich habe dir etwas zu sagen.« Jener erwiderte: »Meister, sprich!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 7, 41, '»Ein Geldverleiher hatte zwei Schuldner; der eine war ihm fünfhundert Denare schuldig, der andere fünfzig;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 7, 42, 'weil sie aber nicht zurückzahlen konnten, schenkte er beiden die Schuld. Wer von ihnen wird ihn nun am meisten lieben?«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 7, 43, 'Simon antwortete: »Ich denke der, dem er das meiste geschenkt hat.« Jesus erwiderte ihm: »Du hast richtig geurteilt.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 7, 44, 'Indem er sich dann zu der Frau wandte, sagte er zu Simon: »Siehst du diese Frau hier? Ich bin in dein Haus gekommen: du hast mir kein Wasser für die Füße gegeben, sie aber hat mir die Füße mit ihren Tränen genetzt und sie mit ihrem Haar getrocknet.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 7, 45, 'Du hast mir keinen Kuß gegeben, sie aber hat, seitdem ich eingetreten bin, mir die Füße unaufhörlich geküßt.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 7, 46, 'Du hast mir das Haupt nicht mit Öl gesalbt, sie aber hat mir mit Myrrhenöl die Füße gesalbt.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 7, 47, 'Deshalb sage ich dir: Ihre vielen Sünden sind ihr vergeben, denn sie hat viel Liebe erwiesen; wem aber nur wenig vergeben wird, der erweist auch nur wenig Liebe.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 7, 48, 'Dann sagte er zu ihr: »Deine Sünden sind (dir) vergeben!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 7, 49, 'Da begannen die Tischgenossen bei sich zu denken: »Wer ist dieser, daß er sogar Sünden vergibt?«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 7, 50, 'Er aber sagte zu der Frau: »Dein Glaube hat dich gerettet: gehe hin in Frieden!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 8, 1, 'In der folgenden Zeit durchwanderte er dann das Land von Stadt zu Stadt und von Dorf zu Dorf, indem er öffentlich lehrte und die Heilsbotschaft vom Reiche Gottes verkündigte. In seiner Begleitung befanden sich die zwölf Jünger');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 8, 2, 'sowie auch einige Frauen, die er von bösen Geistern und Krankheiten geheilt hatte, z.B. Maria, die Magdalena genannt wurde, aus der sieben böse Geister ausgefahren waren,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 8, 3, 'ferner Johanna, die Frau des Chuza, eines Verwalters des Herodes, und Susanna und noch viele andere, die ihnen mit den ihnen zu Gebote stehenden Mitteln Dienste leisteten.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 8, 4, 'Als nun eine große Volksmenge zusammenkam und die Leute aus allen Städten ihm zuströmten, sprach er in der Form eines Gleichnisses:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 8, 5, '»Der Sämann ging aus, um seinen Samen zu säen; und beim Säen fiel einiges (von dem Saatkorn) auf den Weg längshin und wurde zertreten, und die Vögel des Himmels fraßen es auf.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 8, 6, 'Anderes fiel auf felsigen Boden, und als es aufgegangen war, verdorrte es, weil ihm die Feuchtigkeit fehlte.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 8, 7, 'Wieder anderes fiel mitten unter die Dornen, und die Dornen wuchsen mit auf und erstickten es.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 8, 8, 'Anderes aber fiel auf den guten Boden, wuchs auf und brachte hundertfältigen Ertrag.« Bei diesen Worten rief er laut aus: »Wer Ohren hat zu hören, der höre!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 8, 9, 'Da fragten ihn seine Jünger nach dem Sinn dieses Gleichnisses;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 8, 10, 'und er antwortete: »Euch ist es gegeben, die Geheimnisse des Reiches Gottes zu erkennen, den anderen aber (werden sie) nur in Gleichnissen (vorgetragen), damit ›sie mit sehenden Augen doch nicht sehen und mit hörenden Ohren doch nicht verstehen‹.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 8, 11, 'Dies ist aber die Deutung des Gleichnisses: Der Same ist das Wort Gottes.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 8, 12, 'Die, bei denen der Same auf den Weg längshin fiel, sind solche, die (das Wort wohl) gehört haben, darauf aber kommt der Teufel und nimmt das Wort aus ihrem Herzen weg, damit sie nicht zum Glauben gelangen und dadurch gerettet werden.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 8, 13, 'Die, bei denen der Same auf den felsigen Boden fiel, sind solche, die das Wort, wenn sie es gehört haben, mit Freuden annehmen; doch es kann nicht Wurzel bei ihnen schlagen: eine Zeitlang glauben sie wohl, aber zur Zeit der Versuchung fallen sie ab.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 8, 14, 'Was dann unter die Dornen fiel, das deutet auf solche, die das Wort gehört haben, dann aber hingehen und es von den Sorgen und dem Reichtum und den Freuden des Lebens ersticken lassen, so daß sie die Frucht nicht zur Reife bringen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 8, 15, 'Was aber auf den guten Boden fiel, das deutet auf solche, die das Wort, welches sie gehört haben, in einem feinen und guten Herzen festhalten und mit Beharrlichkeit Frucht bringen.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 8, 16, '»Niemand aber, der ein Licht angezündet hat, deckt es mit einem Gefäß zu oder stellt es unter ein Bett, sondern er stellt es auf einen Leuchter, damit die Eintretenden den hellen Schein sehen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 8, 17, 'Denn nichts ist verborgen, was nicht offenbar werden wird, und nichts ist geheim, was nicht bekannt werden und ans Tageslicht kommen wird.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 8, 18, 'Darum gebt wohl acht, wie ihr hört! Denn wer da hat, dem wird noch dazugegeben werden, und wer nicht hat, dem wird auch das noch genommen werden, was er zu haben meint.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 8, 19, 'Es stellten sich dann seine Mutter und seine Brüder bei ihm ein, konnten jedoch wegen der Volksmenge nicht zu ihm gelangen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 8, 20, 'Da wurde ihm gemeldet: »Deine Mutter und deine Brüder stehen draußen und wünschen dich zu sehen.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 8, 21, 'Er aber antwortete ihnen mit den Worten: »Meine Mutter und meine Brüder sind diese da, die das Wort Gottes hören und (danach) tun.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 8, 22, 'Eines Tages begab es sich, daß er mit seinen Jüngern in ein Boot stieg und zu ihnen sagte: »Wir wollen an die andere Seite des Sees hinüberfahren!« So stießen sie denn vom Lande ab.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 8, 23, 'Während der Fahrt aber schlief er ein. Da fuhr ein Sturmwind auf den See herab, das Boot füllte sich mit Wasser, und sie gerieten in Lebensgefahr.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 8, 24, 'Da traten sie zu ihm und weckten ihn mit den Worten: »Meister, Meister, wir gehen unter!« Er aber stand auf und bedrohte den Wind und das Gewoge des Wassers: da legten sie sich, und es trat Windstille ein.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 8, 25, 'Er sagte dann zu ihnen: »Wo ist nun euer Glaube (geblieben)?« Sie waren aber in Furcht und Staunen geraten und sagten zueinander: »Wer ist denn dieser, daß er sogar den Winden und dem Wasser gebietet und sie ihm gehorsam sind?«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 8, 26, 'Sie fuhren dann nach dem Lande der Gergesener, das Galiläa gegenüber liegt.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 8, 27, 'Als er dort ans Land gestiegen war, kam ihm ein Mann aus der Stadt entgegen, der von bösen Geistern besessen war; schon seit langer Zeit hatte er keine Kleider mehr angezogen, auch hielt er sich in keinem Hause mehr auf, sondern in den Gräbern.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 8, 28, 'Als er Jesus sah, schrie er auf, warf sich vor ihm nieder und rief laut: »Was willst du von mir, Jesus, du Sohn Gottes, des Höchsten? Ich bitte dich! Quäle mich nicht!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 8, 29, 'Jesus war nämlich im Begriff, dem unreinen Geist zu gebieten, aus dem Manne auszufahren; denn dieser hatte ihn schon seit langer Zeit in seiner Gewalt, und man hatte ihn mit Ketten und Fußfesseln gebunden und in Gewahrsam gehalten; doch er hatte die Bande allemal zerrissen und wurde von dem bösen Geiste in die Einöden getrieben.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 8, 30, 'Jesus fragte ihn nun: »Wie heißt du?« Er antwortete: »Legion«; denn viele böse Geister waren in ihn gefahren.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 8, 31, 'Diese baten ihn nun, er möchte ihnen nicht gebieten, in den Abgrund zu fahren.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 8, 32, 'Nun befand sich dort eine große Herde Schweine auf der Weide an dem Berge; deshalb baten die Geister ihn um die Erlaubnis, in diese fahren zu dürfen, und er erlaubte es ihnen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 8, 33, 'So fuhren denn die Geister aus dem Manne aus und in die Schweine hinein; und die Herde stürmte den Abhang hinab in den See und ertrank dort.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 8, 34, 'Als nun die Hirten sahen, was geschehen war, ergriffen sie die Flucht und erstatteten Meldung in der Stadt und in den Gehöften.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 8, 35, 'Da zogen die Leute hinaus, um zu sehen, was vorgefallen war; sie kamen zu Jesus und fanden den Mann, aus dem die Geister ausgefahren waren, bekleidet und ganz vernünftig zu den Füßen Jesu sitzen und gerieten darüber in Furcht.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 8, 36, 'Die Augenzeugen erzählten ihnen dann, wie der (früher) Besessene geheilt worden war.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 8, 37, 'Da bat ihn die gesamte Bevölkerung der Umgegend von Gergesa, er möchte ihr Gebiet verlassen; denn sie waren in große Furcht geraten. So stieg er denn wieder ins Boot und machte sich auf den Rückweg.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 8, 38, 'Hierauf richtete der Mann, von dem die bösen Geister ausgefahren waren, die Bitte an ihn, bei ihm bleiben zu dürfen; doch Jesus hieß ihn gehen mit den Worten:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 8, 39, '»Kehre in dein Haus zurück und erzähle dort, wie Großes Gott an dir getan hat!« Da ging er denn auch hin und verkündete in der ganzen Stadt, wie Großes Jesus an ihm getan hatte.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 8, 40, 'Als Jesus dann zurückkehrte, nahm die Volksmenge ihn mit Freuden in Empfang, denn sie hatten alle auf ihn gewartet.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 8, 41, 'Da kam ein Mann namens Jairus, ein Vorsteher der (dortigen) Synagoge, warf sich vor Jesus nieder und bat ihn, in sein Haus zu kommen;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 8, 42, 'er hatte nämlich eine einzige Tochter von ungefähr zwölf Jahren, und diese lag im Sterben. Während Jesus nun hinging, umdrängte ihn die Volksmenge.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 8, 43, 'Und eine Frau, die schon seit zwölf Jahren am Blutfluß litt und [obgleich sie ihr ganzes Vermögen an Ärzte aufgewandt hatte] bei keinem Heilung hatte finden können,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 8, 44, 'die trat von hinten an ihn heran und faßte die Quaste seines Mantels an, und augenblicklich kam der Blutfluß bei ihr zum Stillstand.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 8, 45, 'Da fragte Jesus: »Wer hat mich angefaßt?« Als nun alle es in Abrede stellten, sagte Petrus: »Meister, die Volksmenge umdrängt und stößt dich von allen Seiten!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 8, 46, 'Jesus aber erwiderte: »Es hat mich jemand angefaßt, ich habe ja gefühlt, daß eine Kraft von mir ausgegangen ist.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 8, 47, 'Als nun die Frau sah, daß sie nicht unbemerkt geblieben war, kam sie zitternd herbei, warf sich vor ihm nieder und bekannte vor dem ganzen Volk, aus welchem Grunde sie ihn angefaßt habe und wie sie augenblicklich gesund geworden sei.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 8, 48, 'Da sagte er zu ihr: »Meine Tochter, dein Glaube hat dir Heilung verschafft: gehe in Frieden!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 8, 49, 'Während er noch redete, kam einer von den Leuten des Synagogenvorstehers mit der Meldung: »Deine Tochter ist gestorben: bemühe den Meister nicht weiter!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 8, 50, 'Als Jesus das hörte, sagte er zu Jairus: »Fürchte dich nicht, glaube nur, dann wird sie gerettet werden!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 8, 51, 'Als er dann an das Haus gekommen war, ließ er niemand (von den Seinen) mit sich eintreten außer Petrus, Johannes, Jakobus und den Eltern des Mädchens.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 8, 52, 'Alle weinten aber und wehklagten laut um sie; er jedoch sagte: »Weinet nicht! Sie ist nicht tot, sondern schläft nur«;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 8, 53, 'da verlachten sie ihn, weil sie wohl wußten, daß sie tot war.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 8, 54, 'Er aber faßte sie bei der Hand und rief ihr laut zu: »Mädchen, stehe auf!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 8, 55, 'Da kehrte ihr Geist zu ihr zurück, und sie stand sogleich auf; und er ordnete an, man solle ihr zu essen geben.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 8, 56, 'Und ihre Eltern waren vor Erregung ganz außer sich; er aber gebot ihnen, keinem etwas von dem Geschehenen zu erzählen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 9, 1, 'Er rief dann die Zwölf zusammen und gab ihnen Kraft und Vollmacht über alle bösen Geister sowie zur Heilung von Krankheiten,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 9, 2, 'hierauf sandte er sie aus, das Reich Gottes zu verkünden und (die Kranken) zu heilen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 9, 3, 'Dabei gab er ihnen die Weisung: »Nehmt nichts mit auf den Weg, weder einen Stock noch einen Ranzen, weder Brot noch Geld; auch sollt ihr nicht jeder zwei Röcke haben!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 9, 4, 'Wo ihr in ein Haus eingetreten seid, dort bleibt und von dort zieht weiter!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 9, 5, 'Und wo man euch nicht aufnimmt, da geht aus einer solchen Stadt weg und schüttelt den Staub von euren Füßen ab zum Zeugnis wider sie!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 9, 6, 'So machten sie sich denn auf den Weg und wanderten von Dorf zu Dorf, indem sie überall die Heilsbotschaft verkündeten und Heilungen vollführten.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 9, 7, 'Es hörte aber der Vierfürst Herodes von allen diesen Begebenheiten und fühlte sich dadurch beunruhigt; denn manche behaupteten, Johannes sei von den Toten auferweckt worden;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 9, 8, 'andere wieder meinten, Elia sei erschienen; noch andere, einer von den alten Propheten sei auferstanden.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 9, 9, 'Herodes aber sagte: »Den Johannes habe ich enthaupten lassen; wer mag nun dieser sein, über den ich solche Dinge höre?« So hegte er denn den Wunsch, Jesus persönlich zu sehen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 9, 10, 'Nach ihrer Rückkehr berichteten ihm die Apostel alles, was sie getan hatten. Da nahm er sie mit sich und zog sich in die Stille zurück in eine Ortschaft namens Bethsaida.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 9, 11, 'Als aber die Volksmenge das in Erfahrung gebracht hatte, zogen sie ihm nach, und er ließ sie auch zu sich kommen, redete zu ihnen vom Reiche Gottes und machte die gesund, welche der Heilung bedurften.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 9, 12, 'Als der Tag sich dann zu neigen begann, traten die Zwölf an ihn heran und sagten zu ihm: »Laß das Volk ziehen, damit sie in die umliegenden Ortschaften und Gehöfte gehen und dort Unterkunft und Verpflegung finden; denn hier sind wir in einer öden Gegend.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 9, 13, 'Doch er antwortete ihnen: »Gebt ihr ihnen doch zu essen!« Da erwiderten sie: »Wir haben nicht mehr als fünf Brote und zwei Fische; wir müßten sonst hingehen und Lebensmittel für dieses ganze Volk einkaufen« –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 9, 14, 'es waren nämlich gegen fünftausend Männer. Er sagte aber zu seinen Jüngern: »Laßt sie sich in Gruppen von etwa je fünfzig Personen lagern.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 9, 15, 'Sie taten so und brachten alle dazu, sich zu lagern.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 9, 16, 'Darauf nahm er die fünf Brote und die beiden Fische, blickte zum Himmel auf, sprach den Lobpreis (Gottes), brach die Brote und gab sie immer wieder den Jüngern, damit diese sie dem Volk vorlegten.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 9, 17, 'Und sie aßen und wurden alle satt; dann las man die Brocken auf, die sie übriggelassen hatten, zwölf Körbe voll.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 9, 18, 'Es begab sich hierauf, als er für sich allein betete, daß nur die Jünger sich bei ihm befanden; da fragte er sie: »Für wen halten mich die Volksscharen?«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 9, 19, 'Sie gaben ihm zur Antwort: »Für Johannes den Täufer, andere für Elia, noch andere meinen, einer von den alten Propheten sei auferstanden.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 9, 20, 'Darauf fragte er sie weiter: »Ihr aber – für wen haltet ihr mich?« Da antwortete Petrus: »Für Christus, den Gottgesalbten!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 9, 21, 'Da gab er ihnen die strenge Weisung und gebot ihnen, sie sollten das niemand sagen,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 9, 22, 'und fügte noch hinzu: »Der Menschensohn muß vieles leiden und von den Ältesten und Hohenpriestern und Schriftgelehrten verworfen werden und den Tod erleiden und am dritten Tage auferweckt werden.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 9, 23, 'Dann sagte er zu allen: »Will jemand mein Nachfolger sein, so verleugne er sich selbst und nehme sein Kreuz Tag für Tag auf sich und folge so mir nach! –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 9, 24, 'Denn wer sein Leben retten will, der wird es verlieren; wer aber sein Leben um meinetwillen verliert, der wird es retten.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 9, 25, 'Denn was hülfe es einem Menschen, wenn er die ganze Welt gewänne, sich selbst aber verlöre oder einbüßte? –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 9, 26, 'Denn wer sich meiner und meiner Worte schämt, dessen wird auch der Menschensohn sich schämen, wenn er in seiner Herrlichkeit und in der Herrlichkeit des Vaters und der heiligen Engel kommt.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 9, 27, 'Ich sage euch aber der Wahrheit gemäß: Einige unter denen, die hier stehen, werden den Tod nicht schmecken, bis sie das Reich Gottes gesehen haben.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 9, 28, 'Etwa acht Tage nach diesen Unterredungen nahm er Petrus, Johannes und Jakobus mit sich und stieg auf den Berg, um zu beten.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 9, 29, 'Während er nun betete, veränderte sich das Aussehen seines Angesichts, und seine Kleidung wurde leuchtend weiß.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 9, 30, 'Und siehe, zwei Männer besprachen sich mit ihm, das waren Mose und Elia;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 9, 31, 'sie erschienen in (himmlischer) Herrlichkeit und redeten davon, wie sein Lebensausgang sich in Jerusalem vollziehen sollte.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 9, 32, 'Petrus aber und seine Genossen waren von schwerer Schläfrigkeit befallen; weil sie sich aber mit Gewalt wach hielten, sahen sie seine Herrlichkeit und die beiden Männer, die bei ihm standen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 9, 33, 'Als diese von ihm scheiden wollten, sagte Petrus zu Jesus: »Meister, hier sind wir gut aufgehoben; wir wollen drei Hütten bauen, eine für dich, eine für Mose und eine für Elia« – er wußte nämlich nicht, was er da sagte.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 9, 34, 'Während er noch so redete, kam eine Wolke und überschattete sie; und sie gerieten in Furcht, als sie in die Wolke hineinkamen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 9, 35, 'Da erscholl eine Stimme aus der Wolke, die rief: »Dies ist mein auserwählter Sohn: höret auf ihn!«,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 9, 36, 'und während die Stimme erscholl, fand es sich, daß Jesus allein da war. Und die Jünger blieben verschwiegen und teilten in jenen Tagen niemand etwas von dem mit, was sie gesehen hatten.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 9, 37, 'Als sie aber am folgenden Tage von dem Berge wieder hinabgestiegen waren, kam ihm eine große Volksmenge entgegen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 9, 38, 'Da rief ein Mann aus der Volksmenge heraus: »Meister, ich bitte dich: nimm dich meines Sohnes an, er ist ja mein einziger!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 9, 39, 'Siehe, ein Geist packt ihn, so daß er plötzlich aufschreit; und er zerrt ihn hin und her, so daß ihm Schaum vor den Mund tritt, und läßt nur schwer von ihm ab: er reibt seine Kräfte ganz auf!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 9, 40, 'Ich habe deine Jünger gebeten, sie möchten ihn austreiben, doch sie haben es nicht gekonnt.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 9, 41, 'Da antwortete Jesus: »O ihr ungläubige und verkehrte Art von Menschen! Wie lange soll ich noch bei euch sein und es mit euch aushalten? Bringe deinen Sohn hierher!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 9, 42, 'Während nun der Knabe noch auf ihn zuging, riß der böse Geist ihn hin und her und zog ihn krampfhaft zusammen. Jesus aber bedrohte den unreinen Geist, heilte den Knaben und gab ihn seinem Vater (gesund) zurück.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 9, 43, 'Da gerieten alle außer sich vor Staunen über die große Macht Gottes. Während nun alle voll Verwunderung über alle seine Taten waren, sagte er zu seinen Jüngern:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 9, 44, '»Laßt ihr die Worte, die ich euch jetzt sage, in eure Ohren dringen! Denn der Menschensohn wird in die Hände der Menschen überantwortet werden.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 9, 45, 'Sie verstanden aber diesen Ausspruch nicht, sondern er blieb vor ihnen verhüllt, damit sie ihn nicht begriffen; doch scheuten sie sich, ihn wegen dieses Ausspruchs zu befragen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 9, 46, 'Es stieg aber (einmal) der Gedanke in ihnen auf, wer wohl der Größte unter ihnen wäre.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 9, 47, 'Da Jesus nun den Gedanken kannte, der sie beschäftigte, nahm er ein Kind, stellte es neben sich');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 9, 48, 'und sagte zu ihnen: »Wenn jemand dieses Kind auf meinen Namen hin aufnimmt, so nimmt er mich auf, und wer mich aufnimmt, der nimmt den auf, der mich gesandt hat; denn wer der Kleinste unter euch allen ist, der ist groß.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 9, 49, 'Da nahm Johannes das Wort und sagte: »Meister, wir haben jemand gesehen, der mit deinem Namen böse Geister austrieb, und haben es ihm untersagt, weil er dir nicht mit uns nachfolgt.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 9, 50, 'Jesus aber erwiderte ihm: »Untersagt es ihm nicht! Denn wer nicht gegen euch ist, der ist für euch.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 9, 51, 'Als dann aber die Zeit seines Hingangs herankam, richtete er fest entschlossen sein Augenmerk darauf, nach Jerusalem zu ziehen,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 9, 52, 'und er sandte Boten vor sich her. Diese machten sich auf den Weg und kamen in ein Dorf der Samariter, um dort ein Unterkommen für ihn zu besorgen;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 9, 53, 'doch man nahm ihn nicht auf, weil er die Absicht hatte, nach Jerusalem zu ziehen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 9, 54, 'Als die Jünger Jakobus und Johannes das sahen, fragten sie: »Herr, willst du, daß wir aussprechen, es solle Feuer vom Himmel fallen und sie verzehren, wie auch Elia getan hat?«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 9, 55, 'Er aber wandte sich um und verwies es ihnen mit den Worten: »Wißt ihr nicht, welches Geistes Kinder ihr seid? Der Menschensohn ist nicht gekommen, um Menschenleben zu vernichten, sondern um sie zu retten.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 9, 56, 'So begaben sie sich denn in ein anderes Dorf.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 9, 57, 'Als sie dann des Weges weiterzogen, sagte einer zu ihm: »Ich will dir folgen, wohin du auch gehst.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 9, 58, 'Jesus antwortete ihm: »Die Füchse haben Gruben und die Vögel des Himmels Nester, der Menschensohn aber hat keine Stätte, wohin er sein Haupt legen kann.« –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 9, 59, 'Zu einem anderen sagte er: »Folge mir nach!« Der entgegnete: »Erlaube mir, zunächst noch hinzugehen und meinen Vater zu begraben.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 9, 60, 'Da antwortete er ihm: »Laß die Toten ihre Toten begraben! Du aber gehe hin und verkündige das Reich Gottes!« –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 9, 61, 'Noch ein anderer sagte: »Herr, ich will dir folgen; zunächst aber gestatte mir, von meinen Hausgenossen Abschied zu nehmen!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 9, 62, 'Da sagte Jesus zu ihm: »Niemand, der die Hand an den Pflug gelegt hat und dann noch rückwärts blickt, ist für das Reich Gottes tauglich.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 10, 1, 'Hierauf aber bestellte der Herr noch siebzig andere (Jünger) und sandte sie paarweise vor sich her in alle Städte und Ortschaften, in die er selbst zu gehen gedachte.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 10, 2, 'Er sagte zu ihnen: »Die Ernte ist groß, aber klein die Zahl der Arbeiter; darum bittet den Herrn der Ernte, daß er Arbeiter auf sein Erntefeld sende!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 10, 3, 'Geht hin! Seht, ich sende euch wie Lämmer mitten unter Wölfe.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 10, 4, 'Nehmt keinen Geldbeutel mit euch, auch keinen Ranzen und keine Schuhe, und laßt euch unterwegs mit niemand in lange Begrüßungen ein.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 10, 5, 'Wo ihr in ein Haus eintretet, da sagt zuerst: ›Friede (sei) mit diesem Hause!‹');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 10, 6, 'Wenn dann dort ein Sohn des Friedens wohnt, wird der Friede, den ihr ihm gewünscht habt, auf ihm ruhen; andernfalls wird euer Friedensgruß zu euch zurückkehren.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 10, 7, 'In demselben Hause bleibt dann und eßt und trinkt, was man euch bietet; denn der Arbeiter ist seines Lohnes wert. Geht nicht aus einem Hause weg in ein anderes;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 10, 8, 'und wo ihr in einer Stadt einkehrt und man euch aufnimmt, so eßt, was man euch vorsetzt,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 10, 9, 'und heilt die Kranken daselbst und sagt zu den Stadtbewohnern: ›Das Reich Gottes ist nahe zu euch herbeigekommen!‹');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 10, 10, 'Wo ihr aber in einer Stadt einkehrt und man euch nicht aufnimmt, so geht auf ihre Straßen hinaus und sagt:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 10, 11, '›Sogar den Staub, der sich uns aus eurer Stadt an die Füße gehängt hat, wischen wir ab, damit er euch verbleibt, doch das sollt ihr wissen, daß das Reich Gottes nahe herbeigekommen ist!‹');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 10, 12, 'Ich sage euch: Es wird Sodom an jenem Tage erträglicher ergehen als der betreffenden Stadt!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 10, 13, 'Wehe dir, Chorazin! Wehe dir, Bethsaida! Denn wenn in Tyrus und Sidon die Wundertaten geschehen wären, die bei euch geschehen sind, so hätten sie längst, in Sack und Asche sitzend, Buße getan.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 10, 14, 'Doch es wird Tyrus und Sidon beim Gericht erträglicher ergehen als euch.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 10, 15, 'Und du, Kapernaum, wirst doch nicht etwa bis zum Himmel erhöht werden? Nein, bis zum Totenreich wirst du hinabgestoßen werden!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 10, 16, 'Wer euch hört, der hört mich, und wer euch verwirft, verwirft mich; wer aber mich verwirft, verwirft den, der mich gesandt hat.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 10, 17, 'Die Siebzig kehrten dann voller Freude zurück und sagten: »Herr, auch die bösen Geister sind uns kraft deines Namens gehorsam!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 10, 18, 'Da antwortete er ihnen: »Ich habe den Satan wie einen Blitz aus dem Himmel herabgestürzt gesehen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 10, 19, 'Ihr wißt: ich habe euch die Macht verliehen, auf Schlangen und Skorpione zu treten, und Macht über das ganze Heer des Widersachers, und keinen Schaden wird er euch irgendwie zufügen können.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 10, 20, 'Doch nicht darüber freuet euch, daß die Geister euch gehorsam sind; freut euch vielmehr darüber, daß eure Namen im Himmel eingeschrieben stehen!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 10, 21, 'In eben dieser Stunde jubelte Jesus durch den heiligen Geist mit den Worten: »Ich preise dich, Vater, Herr des Himmels und der Erde, daß du dies vor Weisen und Klugen verborgen und es Unmündigen geoffenbart hast; ja, Vater, denn so ist es dir wohlgefällig gewesen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 10, 22, 'Alles ist mir von meinem Vater übergeben worden, und niemand erkennt, wer der Sohn ist, als nur der Vater, und wer der Vater ist, als nur der Sohn, und wem der Sohn ihn offenbaren will.« –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 10, 23, 'Dann wandte er sich zu den Jüngern besonders und sagte: »Selig sind die Augen, die da sehen, was ihr seht!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 10, 24, 'Denn ich sage euch: Viele Propheten und Könige haben gewünscht, das zu sehen, was ihr seht, und haben es nicht gesehen, und das zu hören, was ihr hört, und haben es nicht gehört.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 10, 25, 'Da trat ein Gesetzeslehrer auf, um ihn zu versuchen, und fragte: »Meister, was muß ich tun, um ewiges Leben zu ererben?«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 10, 26, 'Jesus erwiderte ihm: »Was steht im Gesetz geschrieben? Wie lauten da die Worte?«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 10, 27, 'Er gab zur Antwort: »Du sollst den Herrn, deinen Gott, lieben von ganzem Herzen, mit deiner ganzen Seele, mit aller deiner Kraft und mit deinem ganzen Denken« und »deinen Nächsten wie dich selbst«.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 10, 28, 'Jesus sagte zu ihm: »Du hast richtig geantwortet; tu das, so wirst du leben!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 10, 29, 'Jener wollte sich aber rechtfertigen und sagte zu Jesus: »Ja, wer ist denn mein Nächster?«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 10, 30, 'Da erwiderte Jesus: »Ein Mann ging von Jerusalem nach Jericho hinab und fiel Räubern in die Hände; die plünderten ihn aus, schlugen ihn blutig, ließen ihn halbtot liegen und gingen davon.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 10, 31, 'Zufällig kam ein Priester jene Straße hinabgezogen und sah ihn liegen, ging aber vorüber.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 10, 32, 'Ebenso kam auch ein Levit an die Stelle und sah ihn, ging aber vorüber.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 10, 33, 'Ein Samariter aber, der auf der Reise war, kam in seine Nähe, und als er ihn sah, fühlte er Mitleid mit ihm;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 10, 34, 'er trat an ihn heran und verband ihm die Wunden, wobei er Öl und Wein darauf goß; dann setzte er ihn auf sein Maultier, brachte ihn in eine Herberge und verpflegte ihn.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 10, 35, 'Am folgenden Morgen holte er zwei Denare heraus (aus seinem Beutel), gab sie dem Wirt und sagte: ›Verpflege ihn, und was es dich etwa mehr kostet, will ich dir bei meiner Rückkehr ersetzen.‹');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 10, 36, 'Wer von diesen dreien hat sich nun nach deiner Ansicht dem unter die Räuber Gefallenen als Nächster erwiesen?«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 10, 37, 'Jener antwortete: »Der, welcher die Barmherzigkeit an ihm geübt hat.« Da sagte Jesus zu ihm: »So gehe hin und handle du ebenso!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 10, 38, 'Als sie dann weiterwanderten, kam er in ein Dorf, und eine Frau namens Martha nahm ihn in ihr Haus auf.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 10, 39, 'Diese hatte eine Schwester namens Maria, die sich zu den Füßen des Herrn niederließ und seinen Worten zuhörte;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 10, 40, 'Martha dagegen ließ sich durch vielerlei Dienstleistungen für die Bewirtung in Anspruch nehmen. Nun trat sie zu ihm und sagte: »Herr, machst du dir nichts daraus, daß meine Schwester die Bedienung mir allein überlassen hat? Sage ihr doch, sie möge mir zur Hand gehen!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 10, 41, 'Aber der Herr gab ihr zur Antwort: »Martha, Martha! Du machst dir [Sorge und] Unruhe um vielerlei;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 10, 42, 'aber nur eins ist nötig. Denn Maria hat das gute Teil erwählt: das soll ihr nicht genommen werden.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 11, 1, 'Jesus betete (einst unterwegs) an einem Orte, und als er damit zu Ende war, sagte einer seiner Jünger zu ihm: »Herr, lehre uns beten, wie auch Johannes seine Jünger (Gebete) gelehrt hat!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 11, 2, 'Da sagte er zu ihnen: »Wenn ihr beten wollt, so sprecht: ›Vater, geheiligt werde dein Name! Dein Reich komme!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 11, 3, 'Unser auskömmliches Brot gib uns Tag für Tag!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 11, 4, 'Und vergib uns unsere Sünden, denn auch wir vergeben jedem, der sich an uns verschuldet! Und führe uns nicht in Versuchung!‹«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 11, 5, 'Dann fuhr er fort: »Wer unter euch hätte wohl einen Freund und ginge (nicht) mitten in der Nacht zu ihm und sagte zu ihm: ›Freund, hilf mir mit drei Broten aus!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 11, 6, 'Denn ein Freund von mir ist auf der Reise zu mir gekommen, und ich habe ihm nichts vorzusetzen‹;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 11, 7, 'und jener würde von drinnen antworten: ›Belästige mich nicht! Die Tür ist schon verschlossen, und meine Kinder liegen schon bei mir im Bett; ich kann nicht aufstehen und es dir geben!‹');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 11, 8, 'Ich sage euch: Wenn er auch nicht deshalb aufstehen und ihm das Gewünschte geben mag, weil jener sein Freund ist, so wird er doch wegen dessen Hartnäckigkeit aufstehen und ihm geben, soviel er bedarf.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 11, 9, 'So sage denn auch ich euch: Bittet, so wird euch gegeben werden; suchet, so werdet ihr finden; klopft an, so wird man euch auftun!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 11, 10, 'Denn wer da bittet, empfängt, und wer da sucht, findet, und wer anklopft, dem wird man auftun.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 11, 11, 'Wo wäre aber unter euch ein Vater, der seinem Sohne, wenn er ihn um Brot bittet, einen Stein reichte? Oder wenn er ihn um einen Fisch bittet, wird er ihm statt dessen wohl eine Schlange reichen?');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 11, 12, 'Oder auch einen Skorpion statt eines Eies?');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 11, 13, 'Wenn nun ihr, die ihr doch böse seid, euren Kindern gute Gaben zu geben versteht: wieviel mehr wird der Vater vom Himmel her Heiligen Geist denen geben, die ihn darum bitten!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 11, 14, 'Er trieb dann einen bösen Geist aus, der stumm war; und als der böse Geist ausgefahren war, konnte der Stumme reden. Da geriet die Volksmenge in Erstaunen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 11, 15, 'Einige von ihnen aber sagten: »Im Bunde mit Beelzebul, dem Obersten der bösen Geister, treibt er die bösen Geister aus.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 11, 16, 'Andere wieder stellten ihn auf die Probe, indem sie von ihm ein Wunderzeichen vom Himmel her verlangten.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 11, 17, 'Weil er jedoch ihre Gedanken kannte, sagte er zu ihnen: »Jedes Reich, das gegen sich selbst entzweit ist, wird verwüstet, und ein Haus stürzt auf das andere.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 11, 18, 'Wenn nun auch der Satan gegen sich selbst in Zwiespalt geraten ist, wie wird dann seine Herrschaft Bestand haben können? Ihr behauptet ja, daß ich die bösen Geister im Bunde mit Beelzebul austreibe!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 11, 19, 'Wenn ich aber die Geister im Bunde mit Beelzebul austreibe, mit wessen Hilfe treiben eure Söhne sie aus? Darum werden diese eure Richter sein.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 11, 20, 'Wenn ich aber die bösen Geister durch Gottes Finger austreibe, dann ist ja das Reich Gottes (schon) zu euch gekommen. –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 11, 21, 'Solange der Starke in voller Waffenrüstung sein Schloß bewacht, ist sein Besitztum in Sicherheit;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 11, 22, 'wenn aber ein Stärkerer ihn überfällt und besiegt, so nimmt er ihm seine Waffenrüstung, auf die er sich verlassen hatte, und teilt die ihm abgenommene Beute aus. –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 11, 23, 'Wer nicht mit mir ist, der ist gegen mich, und wer nicht mit mir sammelt, der zerstreut.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 11, 24, 'Wenn der unreine Geist von einem Menschen ausgefahren ist, durchwandert er wüste Gegenden und sucht eine Ruhestätte; und wenn er keine findet, so sagt er: ›Ich will in mein Haus zurückkehren, das ich verlassen habe.‹');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 11, 25, 'Wenn er dann hinkommt, findet er es sauber gefegt und schön aufgeräumt.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 11, 26, 'Hierauf geht er hin und nimmt noch sieben andere Geister, die bösartiger sind als er selbst; und sie ziehen ein und nehmen dort Wohnung; und das Ende wird bei einem solchen Menschen schlimmer als der Anfang war.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 11, 27, 'Als er so redete, erhob eine Frau aus der Volksmenge ihre Stimme und rief ihm zu: »Selig (zu preisen) ist der Mutterschoß, der dich getragen, und die Brüste, die dich genährt haben!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 11, 28, 'Er aber erwiderte: »Selig sind vielmehr die, welche das Wort Gottes hören und bewahren!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 11, 29, 'Als dann immer noch mehr Volksscharen sich sammelten, begann er folgende Rede: »Das gegenwärtige Geschlecht ist ein böses Geschlecht! Es verlangt ein Zeichen, doch es wird ihm kein Zeichen gegeben werden als nur das Zeichen des (Propheten) Jona.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 11, 30, 'Denn wie Jona einst für die Bewohner von Ninive zu einem Zeichen geworden ist, so wird es auch der Menschensohn für dieses Geschlecht sein.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 11, 31, 'Die Königin aus dem Süden wird im Gericht mit den Männern dieses Geschlechts (als Zeugin) auftreten und ihre Verurteilung herbeiführen; denn sie ist von den Enden der Erde gekommen, um die Weisheit Salomos zu hören; und hier steht Größeres als Salomo.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 11, 32, 'Die Männer von Ninive werden im Gericht mit diesem Geschlecht (als Zeugen) auftreten und seine Verurteilung herbeiführen; denn sie haben auf Jonas Predigt hin Buße getan; und hier steht Größeres als Jona. –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 11, 33, 'Niemand zündet ein Licht an und stellt es dann in einen verborgenen Winkel oder unter den Scheffel, sondern auf den Leuchter, damit die Eintretenden den hellen Schein sehen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 11, 34, 'Die Leuchte des Leibes ist dein Auge. Solange nun dein Auge richtig ist, hat auch dein ganzer Leib Licht; wenn es aber nichts taugt, so befindet sich auch dein (ganzer) Leib in Finsternis.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 11, 35, 'Darum gib wohl acht, daß das Licht in dir sich nicht verfinstert!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 11, 36, 'Ist nun dein ganzer Leib beleuchtet und kein Teil an ihm im Finstern geblieben, dann wird er ganz so in Helligkeit sein, wie wenn die Lampe dich mit ihrem hellen Schein bestrahlt.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 11, 37, 'Im Anschluß an diese Rede bat ihn ein Pharisäer, zu Mittag bei ihm zu speisen; er ging auch zu ihm ins Haus und setzte sich (ohne weiteres) zu Tisch.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 11, 38, 'Als der Pharisäer das sah, äußerte er seine Verwunderung darüber, daß Jesus sich vor der Mahlzeit nicht zunächst gewaschen habe.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 11, 39, 'Da sagte der Herr zu ihm: »Nun ja, ihr Pharisäer haltet die Außenseite des Bechers und der Schüssel rein, euer Inneres aber ist voll von Raub (-gier) und Bosheit.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 11, 40, 'Ihr Toren! Hat nicht der, welcher das Auswendige geschaffen hat, auch das Inwendige geschaffen?');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 11, 41, 'Gebt nur das, was sich darin befindet, als Almosen: seht, dann habt ihr sofort alles rein.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 11, 42, 'Aber wehe euch Pharisäern! Ihr entrichtet den Zehnten von Minze, Raute und jedem anderen Gartengewächs, laßt aber das Recht und die Liebe zu Gott außer acht. Vielmehr sollte man diese (beiden) üben und jenes nicht unterlassen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 11, 43, 'Wehe euch Pharisäern! Ihr liebt den Ehrenplatz in den Synagogen und wollt auf den Märkten gegrüßt sein.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 11, 44, 'Wehe euch! Ihr seid wie die unkenntlich gewordenen Gräber, über welche die Leute, ohne es zu wissen, hingehen.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 11, 45, 'Da nahm einer von den Gesetzeslehrern das Wort und sagte zu ihm: »Meister, mit diesen Worten beleidigst du auch uns!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 11, 46, 'Er aber entgegnete: »Wehe auch euch Gesetzeslehrern! Denn ihr bürdet den Menschen schwer zu tragende Lasten auf, rührt aber selber die Lasten mit keinem Finger an.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 11, 47, 'Wehe euch! Ihr erbaut den Propheten Grabmäler, während eure Väter sie getötet haben.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 11, 48, 'Damit tretet ihr als Zeugen für die Taten eurer Väter auf und zollt ihnen Beifall; denn jene haben sie getötet, und ihr errichtet ihnen Bauwerke.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 11, 49, 'Darum hat auch die Weisheit Gottes gesagt: ›Ich will Propheten und Apostel zu ihnen senden, von denen sie einige töten und verfolgen werden,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 11, 50, 'damit das Blut aller Propheten, das seit Grundlegung der Welt vergossen worden ist, an diesem Geschlecht gerächt werde,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 11, 51, 'vom Blute Abels an bis zum Blute Sacharjas, der zwischen dem Brandopferaltar und dem Tempelhause den Tod erlitten hat.‹ Ja, ich sage euch: es wird an diesem Geschlecht gerächt werden!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 11, 52, 'Wehe euch Gesetzeslehrern! Ihr habt den Schlüssel zur Erkenntnis (des Heils) weggenommen; ihr selbst seid nicht hineingegangen, und die, welche hineingehen wollten, habt ihr daran gehindert.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 11, 53, 'Als er dann von dort weggegangen war, begannen die Schriftgelehrten und Pharisäer ihm mit Erbitterung zuzusetzen und ihn über immer mehr Dinge auszufragen,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 11, 54, 'wobei sie ihn belauerten, um ein (unbedachtes) Wort aus seinem Munde aufzufangen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 12, 1, 'Als sich unterdessen eine Volksmenge von vielen Tausenden angesammelt hatte, so daß sie einander auf die Füße traten, begann er, zuerst zu seinen Jüngern zu sagen: »Hütet euch vor dem Sauerteig der Pharisäer, das heißt vor der Heuchelei! –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 12, 2, 'Nichts aber ist verhüllt, das nicht enthüllt werden wird, und nichts verborgen, was nicht bekannt werden wird.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 12, 3, 'Daher wird alles, was ihr im Dunkeln geredet habt, im Licht (der Öffentlichkeit) gehört werden; und was ihr in den Kammern ins Ohr geflüstert habt, wird auf den Dächern ausgerufen werden.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 12, 4, '»Ich sage aber euch, meinen Freunden: Fürchtet euch nicht vor denen, die den Leib zwar töten, danach aber euch nichts weiter antun können!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 12, 5, 'Ich will euch aber angeben, vor wem ihr euch zu fürchten habt: Fürchtet euch vor dem, der die Macht besitzt zu töten und dann auch noch in die Hölle zu werfen! Ja, ich sage euch: Vor diesem fürchtet euch! –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 12, 6, 'Verkauft man nicht fünf Sperlinge für zwei Kupferstücke? Und doch ist kein einziger von ihnen bei Gott vergessen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 12, 7, 'Nun sind aber (bei euch) sogar die Haare auf eurem Haupt alle gezählt. Fürchtet euch nicht: ihr seid mehr wert als viele Sperlinge!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 12, 8, 'Ich sage euch aber: Wer sich zu mir vor den Menschen bekennt, zu dem wird sich auch der Menschensohn vor den Engeln Gottes bekennen;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 12, 9, 'wer mich aber vor den Menschen verleugnet, der wird auch vor den Engeln Gottes verleugnet werden.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 12, 10, '»Und wer immer ein Wort gegen den Menschensohn ausspricht, der wird Vergebung finden; wer aber gegen den heiligen Geist eine Lästerung begeht, der wird keine Vergebung finden. –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 12, 11, 'Wenn man euch aber vor die Synagogen und vor die Obrigkeiten und die Behörden stellt, so macht euch keine Sorge darüber, wie oder womit ihr euch verteidigen oder was ihr sagen sollt!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 12, 12, 'Denn der heilige Geist wird euch in eben der Stunde lehren, was ihr sagen sollt.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 12, 13, 'Es sagte aber einer aus der Volksmenge zu ihm: »Meister, sage doch meinem Bruder, er solle die Erbschaft mit mir teilen!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 12, 14, 'Jesus aber antwortete ihm: »Mensch, wer hat mich zum Richter oder Erbschaftsteiler über euch bestellt?«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 12, 15, 'Dann fuhr er fort: »Seht euch vor und hütet euch vor aller Habsucht! Denn wenn jemand auch Überfluß hat, so ist das Leben für ihn doch durch all sein Besitztum nicht gesichert.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 12, 16, 'Er legte ihnen dann folgendes Gleichnis vor: »Einem reichen Manne hatten seine Felder eine ergiebige Ernte gebracht.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 12, 17, 'Da überlegte er bei sich folgendermaßen: ›Was soll ich tun? Ich habe keinen Raum, meine Ernte unterzubringen.‹');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 12, 18, 'Dann sagte er: ›So will ich’s machen: Ich will meine Scheunen abreißen und größere bauen und dort meinen gesamten Ernteertrag und meine Güter unterbringen');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 12, 19, 'und will dann zu meiner Seele sagen: Liebe Seele, du hast nun einen reichen Vorrat auf viele Jahre daliegen; gönne dir also Ruhe, iß und trink und laß dir’s wohl sein!‹');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 12, 20, 'Aber Gott sprach zu ihm: ›Du Narr! Noch in dieser Nacht fordert man dir deine Seele ab; wem wird dann das gehören, was du aufgespeichert hast?‹');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 12, 21, 'So geht es jedem, der für sich selbst Schätze sammelt und nicht reich für Gott ist.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 12, 22, 'Weiter sagte er zu seinen Jüngern: »Deshalb sage ich euch: Seid nicht besorgt um euer Leben, was ihr essen sollt, auch nicht um euren Leib, was ihr anziehen sollt!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 12, 23, 'Das Leben ist doch wertvoller als die Nahrung und der Leib wertvoller als die Kleidung.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 12, 24, 'Sehet die Raben an: sie säen nicht und ernten nicht, sie haben keine Vorratskammern und keine Scheunen, und Gott ernährt sie doch. Wieviel mehr seid ihr doch wert als die Vögel!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 12, 25, 'Wer aber von euch vermöchte durch all seine Sorgen der Länge seiner Lebenszeit auch nur eine Spanne zuzusetzen?');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 12, 26, 'Wenn ihr also nicht einmal etwas ganz Geringes vermögt, wozu macht ihr euch da Sorge um das Übrige?');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 12, 27, 'Sehet die Lilien an, wie sie weder spinnen noch weben, und doch sage ich euch: Auch Salomo in aller seiner Pracht ist nicht so herrlich gekleidet gewesen wie eine von diesen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 12, 28, 'Wenn nun Gott das Gras auf dem Felde, das heute steht und morgen in den Ofen geworfen wird, so kleidet: wieviel eher wird er es euch tun, ihr Kleingläubigen!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 12, 29, 'So fragt denn auch ihr nicht ängstlich, was ihr essen und was ihr trinken sollt, und regt euch nicht darüber auf!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 12, 30, 'Denn nach allen diesen Dingen trachten die Heidenvölker der Welt; euer Vater weiß ja, daß ihr dies bedürft.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 12, 31, 'Trachtet vielmehr nach seinem Reich, dann wird euch dieses obendrein gegeben werden.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 12, 32, 'Fürchte dich nicht, du kleine Herde! Denn eurem Vater hat es gefallen, euch das Reich (Gottes) zu geben.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 12, 33, 'Verkauft euren Besitz und gebt ihn als Almosen hin! Verschafft euch Geldbeutel, die sich nicht abnützen, einen Schatz, der nie zu Ende geht, im Himmel, wo kein Dieb hineinkommt und keine Motte etwas zernagt!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 12, 34, 'Denn wo euer Schatz ist, da wird auch euer Herz sein.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 12, 35, '»Laßt eure Hüften gegürtet sein und eure Lampen brennen!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 12, 36, 'Denn ihr sollt Leuten gleichen, die auf ihren Herrn warten, wann er vom Hochzeitsmahl heimkehren werde, um ihm, wenn er kommt und anklopft, sogleich zu öffnen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 12, 37, 'Selig zu preisen sind solche Knechte, die der Herr bei seiner Rückkehr wachend antrifft! Wahrlich ich sage euch: Er wird sich das Gewand hochschürzen, wird sie sich zu Tische setzen lassen und herantreten, um sie zu bedienen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 12, 38, 'Und mag er erst in der zweiten oder in der dritten Nachtwache kommen und sie so vorfinden: selig sind sie zu preisen!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 12, 39, 'Das aber seht ihr ein: Wenn der Hausherr wüßte, in welcher Stunde der Dieb kommt, so würde er keinen Einbruch in sein Haus zulassen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 12, 40, 'Darum haltet auch ihr euch bereit, denn der Menschensohn kommt zu einer Stunde, in der ihr es nicht vermutet.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 12, 41, 'Da fragte Petrus: »Herr, hast du dies Gleichnis nur für uns bestimmt oder auch für alle anderen?«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 12, 42, 'Der Herr antwortete: »Wer ist demnach der treue Haushalter, der kluge, den sein Herr über seine Dienerschaft setzen wird, damit er ihnen das gebührende Speisemaß zu rechter Zeit gebe?');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 12, 43, 'Selig zu preisen ist ein solcher Knecht, den sein Herr bei seiner Rückkehr in solcher Tätigkeit findet.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 12, 44, 'Wahrlich ich sage euch: Über seine sämtlichen Güter wird er ihn setzen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 12, 45, 'Wenn aber ein solcher Knecht in seinem Herzen denkt: ›Mein Herr kommt noch lange nicht!‹ und dann anfängt, die Knechte und Mägde zu schlagen, zu schmausen und zu zechen und sich zu betrinken:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 12, 46, 'so wird der Herr eines solchen Knechtes an einem Tage kommen, an dem er ihn nicht erwartet, und zu einer Stunde, die er nicht kennt; und wird ihn zerhauen lassen und ihm seinen Platz bei den Ungetreuen anweisen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 12, 47, 'Ein solcher Knecht aber, der den Willen seines Herrn gekannt und doch nichts ausgeführt und nichts nach seinem Willen getan hat, wird viele Schläge erhalten;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 12, 48, 'wer dagegen seinen Willen nicht gekannt und Dinge getan hat, die Züchtigung verdienen, wird nur wenige Schläge erhalten. Wem aber viel gegeben ist, von dem wird auch viel gefordert werden, und wem viel anvertraut ist, von dem wird man auch um so mehr verlangen.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 12, 49, '»Ich bin dazu gekommen, ein Feuer auf die Erde zu werfen, und was sollte ich lieber wünschen, als daß es schon brennte!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 12, 50, 'Doch mit einer Taufe habe ich mich (vorher) noch taufen zu lassen, und wie ist mir so bange (und doch zugleich: wie drängt es mich), bis sie vollzogen ist!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 12, 51, 'Meint ihr, ich sei gekommen, um Frieden auf die Erde zu bringen? Nein, sage ich euch, vielmehr Zwiespalt.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 12, 52, 'Denn von nun an werden fünf, die in einem Hause wohnen, entzweit sein: drei werden gegen zwei und zwei gegen drei stehen,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 12, 53, 'der Vater gegen den Sohn und der Sohn gegen den Vater, die Mutter gegen die Tochter und die Tochter gegen die Mutter, die Schwiegermutter gegen ihre Schwiegertochter und die Schwiegertochter gegen die Schwiegermutter.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 12, 54, 'Dann sagte er auch noch zu der Volksmenge: »Wenn ihr Gewölk im Westen aufsteigen seht, dann sagt ihr sogleich: ›Es gibt Regen‹, und es kommt auch so;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 12, 55, 'und wenn ihr den Südwind wehen seht, so sagt ihr: ›Es wird heiß werden‹, und es kommt auch so.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 12, 56, 'Ihr Heuchler! Das Aussehen der Erde und des Himmels versteht ihr richtig zu beurteilen; wie kommt es denn, daß ihr die gegenwärtige Zeit nicht richtig beurteilt?');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 12, 57, 'Warum könnt ihr auch nicht von euch selbst aus zu einem Urteil über das, was recht ist, gelangen?');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 12, 58, 'Denn wenn du mit deinem Widersacher vor Gericht gehst, so gib dir noch unterwegs Mühe, dich gütlich mit ihm abzufinden, damit er dich nicht etwa vor den Richter schleppt und der Richter dich dem Gerichtsdiener übergibt und der Gerichtsdiener dich ins Gefängnis wirft.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 12, 59, 'Ich sage dir: du wirst von dort sicherlich nicht loskommen, bis du auch den letzten Heller bezahlt hast.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 13, 1, 'Es waren aber zu eben dieser Zeit einige Leute (bei ihm) eingetroffen, die ihm von den Galiläern erzählten, deren Blut Pilatus zusammen mit dem ihrer Schlachtopfer vergossen hatte.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 13, 2, 'Da antwortete ihnen Jesus: »Meint ihr etwa, diese Galiläer seien größere Sünder gewesen als alle anderen Galiläer, weil sie dies Schicksal erlitten haben?');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 13, 3, 'Nein, sage ich euch; sondern wenn ihr euren Sinn nicht ändert, werdet ihr alle ebenso umkommen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 13, 4, 'Oder meint ihr, daß jene achtzehn, auf die der Turm am (Teich) Siloah gestürzt ist und sie erschlagen hat, schuldbeladener gewesen seien als alle anderen Bewohner von Jerusalem?');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 13, 5, 'Nein, sage ich euch; sondern wenn ihr euren Sinn nicht ändert, werdet ihr alle ebenso umkommen.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 13, 6, 'Er sagte ihnen dann noch folgendes Gleichnis: »Jemand hatte einen Feigenbaum in seinem Weinberge stehen, und er kam und suchte Frucht an ihm, fand jedoch keine.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 13, 7, 'Da sagte er zu dem Weingärtner: ›Sieh, ich komme nun schon drei Jahre her und suche Frucht an diesem Feigenbaum, finde jedoch keine; haue ihn ab! Wozu soll er noch den Platz wegnehmen?‹');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 13, 8, 'Da antwortete ihm jener: ›Herr, laß ihn noch dieses Jahr stehen! Ich will noch einmal das Land um ihn herum graben und ihn düngen:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 13, 9, 'vielleicht bringt er künftig doch noch Frucht; andernfalls laß ihn umhauen!‹«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 13, 10, 'Jesus lehrte einst in einer der Synagogen am Sabbat.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 13, 11, 'Da war gerade eine Frau anwesend, die schon seit achtzehn Jahren einen Geist der Schwäche hatte; sie war zusammengekrümmt und unfähig, sich ordentlich aufzurichten.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 13, 12, 'Als Jesus sie erblickte, rief er sie herbei und sagte zu ihr: »Frau, du bist von deiner Schwäche befreit!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 13, 13, 'Dann legte er ihr die Hände auf, und sie richtete sich augenblicklich gerade empor und pries Gott.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 13, 14, 'Weil nun der Vorsteher der Synagoge unwillig darüber war, daß Jesus am Sabbat eine Heilung vollzogen hatte, sagte er zu der (versammelten) Menge: »Sechs Tage sind da, an denen man arbeiten soll; an diesen also kommt und laßt euch heilen, aber nicht (gerade) am Sabbattage!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 13, 15, 'Der Herr aber antwortete ihm mit den Worten: »Ihr Heuchler! Bindet nicht ein jeder von euch am Sabbat seinen Ochsen oder Esel von der Krippe los und führt ihn zur Tränke?');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 13, 16, 'Diese Frau aber, eine Tochter Abrahams, die der Satan nun schon achtzehn Jahre lang in Fesseln gehalten hat, die sollte von dieser Fessel am Sabbattage nicht befreit werden dürfen?«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 13, 17, 'Durch diese seine Worte wurden alle seine Gegner beschämt; die ganze Volksmenge aber freute sich über alle die herrlichen Taten, die durch ihn geschahen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 13, 18, 'Dann sagte er: »Wem ist das Reich Gottes gleich, und womit soll ich es vergleichen?');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 13, 19, 'Es ist einem Senfkorn gleich, das ein Mann nahm und in seinem Garten einlegte; dort wuchs es und wurde zu einem Baume, und die Vögel des Himmels nisteten in seinen Zweigen.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 13, 20, 'Und weiter sagte er: »Womit soll ich das Reich Gottes vergleichen?');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 13, 21, 'Es ist einem Sauerteig gleich, den eine Frau nahm und unter drei Scheffel Mehl mengte, bis der ganze Teig durchsäuert war.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 13, 22, 'So wanderte er von Stadt zu Stadt und von Dorf zu Dorf, indem er lehrte und seine Wanderung nach Jerusalem vollzog.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 13, 23, 'Da fragte ihn jemand: »Herr, es sind wohl nur wenige, die gerettet werden?« Er antwortete ihnen:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 13, 24, '»Ringet danach, durch die enge Pforte einzugehen! Denn viele, sage ich euch, werden hineinzukommen suchen und es nicht vermögen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 13, 25, 'Wenn ihr erst dann, nachdem der Hausherr sich schon erhoben und die Tür abgeschlossen hat, draußen zu stehen und an die Tür zu klopfen beginnt und ihm zuruft: ›Herr, mache uns auf!‹, so wird er euch antworten: ›Ich weiß von euch nicht, woher ihr seid.‹');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 13, 26, 'Dann werdet ihr anfangen zu versichern: ›Wir haben doch vor deinen Augen (mit dir) gegessen und getrunken, und du hast bei uns auf den Straßen gelehrt‹;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 13, 27, 'aber er wird erwidern: ›Ich sage euch: ich weiß nicht, woher ihr seid; hinweg von mir alle, die ihr die Ungerechtigkeit übt!‹');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 13, 28, 'Dort wird’s dann ein lautes Weinen und Zähneknirschen geben, wenn ihr Abraham, Isaak, Jakob und alle Propheten im Reiche Gottes sehen werdet, während ihr selbst hinausgestoßen seid.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 13, 29, 'Und sie werden von Osten und Westen, von Norden und Süden kommen und sich im Reiche Gottes zum Mahl niedersetzen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 13, 30, 'Und wisset wohl: Es gibt Letzte, die werden Erste sein, und es gibt Erste, die werden Letzte sein.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 13, 31, 'In eben dieser Stunde traten einige Pharisäer herzu und sagten zu ihm: »Entferne dich von hier und ziehe weiter, denn Herodes will dich töten!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 13, 32, 'Doch er antwortete ihnen: »Geht hin und meldet diesem Fuchs: ›Wisse wohl: ich treibe böse Geister aus und vollführe Heilungen heute noch und morgen, und übermorgen komme ich damit zum Abschluß.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 13, 33, 'Jedoch heute und morgen und übermorgen muß ich weiterziehen; denn es geht nicht an, daß ein Prophet anderswo als in Jerusalem ums Leben kommt.‹');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 13, 34, 'Jerusalem, Jerusalem, das du die Propheten tötest und die steinigst, die zu dir gesandt sind! Wie oft habe ich deine Kinder sammeln wollen, wie eine Henne ihre Küchlein unter ihre Flügel sammelt, doch ihr habt nicht gewollt!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 13, 35, 'Seht, euer Haus wird euch nun überlassen. Ich sage euch aber: Ihr werdet mich nicht sehen, bis die Zeit kommt, wo ihr ausruft: ›Gepriesen sei, der da kommt im Namen des Herrn!‹«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 14, 1, 'Als er dann an einem Sabbat in das Haus eines der Obersten der Pharisäer gekommen war, um dort am Mahl teilzunehmen, lauerten sie ihm auf.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 14, 2, 'Und siehe, ein wassersüchtiger Mann erschien dort vor ihm.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 14, 3, 'Da richtete Jesus die Frage an die Gesetzeslehrer und Pharisäer: »Darf man am Sabbat heilen oder nicht?«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 14, 4, 'Sie aber schwiegen. Da faßte er ihn an, heilte ihn und hieß ihn gehen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 14, 5, 'Hierauf sagte er zu ihnen: »Wem von euch wird sein Sohn oder sein Rind in einen Brunnen fallen, und er wird ihn nicht sofort auch am Sabbattage herausziehen?«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 14, 6, 'Und sie vermochten ihm auf diese Frage keine widersprechende Antwort zu geben.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 14, 7, 'Er legte aber den Gästen ein Gleichnis vor, weil er beobachtete, wie sie sich die obersten Plätze aussuchten, und sagte zu ihnen:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 14, 8, '»Wenn du von jemand zu einem Festmahl eingeladen bist, so setze dich nicht obenan; es könnte sonst jemand, der noch vornehmer ist als du, von ihm geladen sein,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 14, 9, 'und dann würde der, welcher dich und ihn geladen hat, kommen und zu dir sagen: ›Tritt diesem da den Platz ab!‹, und du müßtest dich alsdann dazu verstehen, beschämt untenan zu sitzen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 14, 10, 'Nein, wenn du eingeladen bist, so gehe hin und setze dich untenan; dann wird der Gastgeber kommen und zu dir sagen: ›Freund, rücke weiter nach oben!‹, dann wirst du in den Augen aller deiner Tischgenossen geehrt dastehen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 14, 11, 'Denn wer sich selbst erhöht, wird erniedrigt werden, und wer sich selbst erniedrigt, wird erhöht werden.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 14, 12, 'Er sagte dann auch zu dem, der ihn eingeladen hatte: »Wenn du ein Mittagsmahl oder ein Abendessen veranstaltest, so lade nicht deine Freunde und deine Brüder, nicht deine Verwandten und reichen Nachbarn dazu ein; sonst laden auch sie dich wieder ein, und dir wird Gleiches mit Gleichem vergolten.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 14, 13, 'Nein, wenn du ein Gastmahl veranstalten willst, so lade Arme und Krüppel, Lahme und Blinde dazu ein,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 14, 14, 'dann wirst du glückselig sein, weil sie es dir nicht vergelten können; denn es wird dir bei der Auferstehung der Gerechten vergolten werden.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 14, 15, 'Als einer von den Tischgenossen dies hörte, sagte er zu ihm: »Glückselig ist, wer am Mahl im Reiche Gottes teilnehmen wird!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 14, 16, 'Jesus aber antwortete ihm: »Ein Mann veranstaltete ein großes Gastmahl und lud viele dazu ein.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 14, 17, 'Er sandte dann seinen Knecht zur Stunde des Gastmahls aus und ließ den Geladenen sagen, sie möchten kommen, denn es sei nunmehr alles bereit.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 14, 18, 'Da begannen alle ohne Ausnahme sich zu entschuldigen. Der erste ließ ihm sagen: ›Ich habe einen Acker gekauft und muß notwendigerweise hingehen, um ihn zu besichtigen; ich bitte dich: sieh mich als entschuldigt an!‹');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 14, 19, 'Ein anderer sagte: ›Ich habe fünf Joch Ochsen gekauft und muß hingehen, um sie zu erproben; ich bitte dich: sieh mich als entschuldigt an!‹');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 14, 20, 'Wieder ein anderer sagte: ›Ich habe mich verheiratet, kann also nicht kommen.‹');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 14, 21, 'Als nun der Knecht zurückkam, berichtete er dies seinem Herrn. Da wurde der Hausherr zornig und gab seinem Knecht die Weisung: ›Gehe schnell hinaus auf die Straßen und Gassen der Stadt und bringe die Armen und Krüppel, die Blinden und Lahmen hierher.‹');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 14, 22, 'Der Knecht meldete dann: ›Herr, dein Befehl ist ausgeführt, doch es ist noch Platz vorhanden.‹');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 14, 23, 'Da sagte der Herr zu dem Knecht: ›Gehe auf die Landstraßen und an die Zäune hinaus und nötige die Leute dort hereinzukommen, damit mein Haus voll werde!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 14, 24, 'Denn ich sage euch: Keiner von jenen Männern, die (zuerst) geladen waren, wird mein Gastmahl zu kosten bekommen.‹«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 14, 25, 'Es zogen aber große Volksscharen mit ihm; da wandte er sich um und sagte zu ihnen:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 14, 26, '»Wenn jemand zu mir kommt und nicht seinen Vater und seine Mutter, sein Weib und seine Kinder, seine Brüder und seine Schwestern, ja sogar sein eigenes Leben haßt, so kann er nicht mein Jünger sein.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 14, 27, 'Wer nicht sein Kreuz trägt und mir nachfolgt, der kann nicht mein Jünger sein.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 14, 28, '»Denn wer unter euch, der einen Turm zu bauen beabsichtigt, setzt sich nicht zuerst hin und berechnet die Kosten, ob er auch die Mittel zur Ausführung des Planes habe?');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 14, 29, 'Sonst, wenn er den Grund gelegt hat, und er den Bau nicht zu Ende führen kann, werden alle, die es sehen, anfangen über ihn zu spotten');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 14, 30, 'und werden sagen: ›Dieser Mensch hat den Bau begonnen, doch ihn nicht zu Ende führen können.‹');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 14, 31, 'Oder welcher König, der zum Kriege mit einem andern König ausziehen will, setzt sich nicht zuerst hin und geht mit sich zu Rat, ob er imstande ist, mit zehntausend Mann dem entgegenzutreten, der mit zwanzigtausend gegen ihn anrückt?');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 14, 32, 'Sonst muß er, solange jener noch weit entfernt ist, eine Gesandtschaft an ihn schicken und um Friedensverhandlungen bitten.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 14, 33, 'Ebenso kann keiner von euch mein Jünger sein, der sich nicht von allem lossagt, was er besitzt. –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 14, 34, 'Das Salz ist also etwas Gutes; wenn aber einmal auch das Salz fade geworden ist, womit soll man es wieder zu Salz machen?');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 14, 35, 'Weder für den Acker noch für den Düngerhaufen ist es brauchbar: man wirft es eben aus dem Hause hinaus. Wer Ohren hat zu hören, der höre!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 15, 1, 'Es waren aber gerade die Zöllner und Sünder die, die ihm nahe zu kommen suchten, um ihn zu hören.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 15, 2, 'Darüber murrten die Pharisäer und die Schriftgelehrten laut und sagten: »Dieser nimmt Sünder (in seine Umgebung) auf und ißt mit ihnen.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 15, 3, 'Da antwortete ihnen Jesus durch folgendes Gleichnis:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 15, 4, '»Wo ist jemand unter euch, der hundert Schafe besitzt und, wenn ihm eins von ihnen verloren geht, nicht die neunundneunzig in der Einöde zurückläßt und dem verlorenen nachgeht, bis er es findet?');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 15, 5, 'Wenn er es dann gefunden hat, nimmt er es voller Freude auf seine Schultern');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 15, 6, 'und ruft, wenn er nach Hause gekommen ist, seine Freunde und Nachbarn zusammen und sagt zu ihnen: ›Freuet euch mit mir! Denn ich habe mein Schaf wiedergefunden, das verloren gegangen war.‹');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 15, 7, 'Ich sage euch: Ebenso wird im Himmel über einen einzigen Sünder, der sich bekehrt, mehr Freude herrschen als über neunundneunzig Gerechte, die der Bekehrung nicht bedürfen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 15, 8, 'Oder wo ist eine Frau, die zehn Drachmen besitzt und, wenn sie eine von ihnen verliert, nicht ein Licht anzündet und das Haus fegt und eifrig sucht, bis sie (das Geldstück) findet?');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 15, 9, 'Wenn sie es dann gefunden hat, ruft sie ihre Freundinnen und Nachbarinnen zusammen und sagt: ›Freuet euch mit mir, denn ich habe die Drachme wiedergefunden, die ich verloren hatte.‹');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 15, 10, 'Ebenso, sage ich euch, herrscht Freude bei den Engeln Gottes über einen einzigen Sünder, der sich bekehrt.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 15, 11, 'Dann fuhr er fort: »Ein Mann hatte zwei Söhne.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 15, 12, 'Der jüngere von ihnen sagte zum Vater: ›Vater, gib mir den auf mich entfallenden Teil des Vermögens!‹ Da verteilte jener das Hab und Gut unter sie.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 15, 13, 'Kurze Zeit darauf packte der jüngere Sohn alles, was ihm gehörte, zusammen und zog in ein fernes Land; dort brachte er sein Vermögen in einem ausschweifenden Leben durch.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 15, 14, 'Als er nun alles aufgebraucht hatte, entstand eine schwere Hungersnot in jenem Lande, und auch er begann Not zu leiden.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 15, 15, 'Da ging er hin und stellte sich einem der Bürger jenes Landes zur Verfügung; der schickte ihn auf seine Felder, die Schweine zu hüten,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 15, 16, 'und er hätte sich gern an den Schoten des Johannesbrotbaumes satt gegessen, welche die Schweine als Futter bekamen, doch niemand gab sie ihm.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 15, 17, 'Da ging er in sich und sagte: ›Wie viele Tagelöhner meines Vaters haben Brot im Überfluß, während ich hier vor Hunger umkomme!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 15, 18, 'Ich will mich aufmachen und zu meinem Vater gehen und zu ihm sagen: Vater, ich habe gegen den Himmel und dir gegenüber gesündigt;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 15, 19, 'ich bin nicht mehr wert, dein Sohn zu heißen: halte mich wie einen von deinen Tagelöhnern.‹');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 15, 20, 'So machte er sich denn auf den Weg zu seinem Vater. Als er aber noch weit entfernt war, sah ihn sein Vater kommen und fühlte Mitleid: er eilte (ihm entgegen), fiel ihm um den Hals und küßte ihn.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 15, 21, 'Da sagte der Sohn zu ihm: ›Vater, ich habe gegen den Himmel und dir gegenüber gesündigt; ich bin nicht mehr wert, dein Sohn zu heißen!‹');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 15, 22, 'Der Vater aber befahl seinen Knechten: ›Holt schnell das beste Gewand aus dem Hause und legt es ihm an; gebt ihm auch einen Ring an seine Hand und Schuhe an seine Füße');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 15, 23, 'und bringt das gemästete Kalb her, schlachtet es und laßt uns essen und fröhlich sein!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 15, 24, 'Denn dieser mein Sohn war tot und ist wieder lebendig geworden, er war verloren und ist wiedergefunden!‹ Und sie fingen an, fröhlich zu sein.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 15, 25, 'Sein älterer Sohn aber war währenddessen auf dem Felde. Als er nun heimkehrte und sich dem Hause näherte, hörte er Musik und Reigenchöre.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 15, 26, 'Da rief er einen von den Knechten herbei und erkundigte sich, was das zu bedeuten habe.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 15, 27, 'Der gab ihm zur Antwort: ›Dein Bruder ist heimgekommen; da hat dein Vater das gemästete Kalb schlachten lassen, weil er ihn gesund wiedererhalten hat.‹');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 15, 28, 'Da wurde er zornig und wollte nicht ins Haus hineingehen; sein Vater aber kam heraus und redete ihm gut zu.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 15, 29, 'Da antwortete er dem Vater: ›Du weißt: schon so viele Jahre diene ich dir und habe noch nie ein Gebot von dir übertreten; doch mir hast du noch nie auch nur ein Böcklein gegeben, daß ich mit meinen Freunden ein fröhliches Mahl hätte halten können.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 15, 30, 'Nun aber dieser dein Sohn heimgekehrt ist, der dein Vermögen mit Dirnen durchgebracht hat, da hast du ihm das Mastkalb schlachten lassen!‹');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 15, 31, 'Er aber erwiderte ihm: ›Mein Sohn, du bist allezeit bei mir, und alles, was mein ist, ist auch dein.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 15, 32, 'Wir mußten doch fröhlich sein und uns freuen! Denn dieser dein Bruder war tot und ist wieder lebendig geworden, er war verloren gegangen und ist wiedergefunden worden.‹«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 16, 1, 'Er sagte dann noch zu seinen Jüngern: »Es war ein reicher Mann, der einen Verwalter hatte; über diesen wurde ihm hinterbracht, daß er ihm sein Vermögen veruntreue.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 16, 2, 'Da ließ er ihn rufen und sagte zu ihm: ›Was muß ich da über dich hören? Lege Rechnung ab über deine Verwaltung, denn du kannst nicht länger mein Verwalter sein!‹');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 16, 3, 'Da überlegte der Verwalter bei sich: ›Was soll ich tun, da mein Herr mir die Verwaltung abnimmt? Zum Graben bin ich zu schwach, und zu betteln schäme ich mich.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 16, 4, 'Nun, ich weiß schon, was ich tun will, damit die Leute mich, wenn ich meines Amtes enthoben bin, in ihre Häuser aufnehmen.‹');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 16, 5, 'Er ließ also die Schuldner seines Herrn alle einzeln zu sich kommen und fragte den ersten: ›Wieviel bist du meinem Herrn schuldig?‹');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 16, 6, 'Der antwortete: ›Hundert Tonnen Öl.‹ Da sagte er zu ihm: ›Nimm hier deinen Pachtvertrag, setze dich hin und schreibe schnell fünfzig!‹');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 16, 7, 'Darauf fragte er einen andern: ›Du aber, wieviel bist du schuldig?‹ Der antwortete: ›Hundert Zentner Weizen.‹ Er sagte zu ihm: ›Nimm hier deinen Pachtvertrag und schreibe achtzig.‹«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 16, 8, 'Und der Herr lobte den unehrlichen Verwalter, daß er klug gehandelt habe; denn – sagte er – »die Kinder dieser Weltzeit sind im Verkehr mit ihresgleichen klüger als die Kinder des Lichts.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 16, 9, 'Auch ich sage euch: Macht euch Freunde mit dem ungerechten Mammon, damit, wenn er euch ausgeht, ihr Aufnahme in den ewigen Hütten findet.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 16, 10, '»Wer im Kleinsten treu ist, der ist auch im Großen treu, und wer im Kleinsten ungerecht ist, der ist auch im Großen ungerecht.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 16, 11, 'Wenn ihr euch nun in der Verwaltung des ungerechten Mammons nicht treu erwiesen habt, wer wird euch da das wahre Gut anvertrauen?');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 16, 12, 'Und wenn ihr euch am fremden Gut nicht treu erwiesen habt, wer wird euch da euer eigenes geben?');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 16, 13, 'Kein Knecht kann zwei Herren (zugleich) dienen; denn entweder wird er den einen hassen und den andern lieben, oder er wird dem einen anhangen und den andern mißachten. Ihr könnt nicht Gott dienen und (zugleich) dem Mammon.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 16, 14, 'Dies alles hörten aber die Pharisäer, die geldgierig waren, und rümpften die Nase über ihn.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 16, 15, 'Da sagte er zu ihnen: »Ihr seid die Leute, die sich selbst vor den Menschen als gerecht hinstellen, Gott aber kennt eure Herzen; denn was vor den Menschen hoch dasteht, ist ein Greuel vor Gott.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 16, 16, 'Das Gesetz und die Propheten (reichen) bis auf Johannes; von da an wird das Reich Gottes durch die Heilsbotschaft verkündigt, und ein jeder drängt sich mit Gewalt hinein.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 16, 17, 'Es ist aber eher möglich, daß Himmel und Erde vergehen, als daß vom Gesetz ein einziges Strichlein hinfällig wird.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 16, 18, 'Wer seine Frau entläßt und eine andere heiratet, begeht Ehebruch, und wer eine von ihrem Gatten entlassene Frau heiratet, begeht auch Ehebruch.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 16, 19, '»Es war aber ein reicher Mann, der kleidete sich in Purpur und kostbare Leinwand und lebte alle Tage herrlich und in Freuden.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 16, 20, 'Ein Armer aber namens Lazarus lag vor seiner Türhalle; der war mit Geschwüren bedeckt');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 16, 21, 'und hatte nur den Wunsch, sich von den Abfällen vom Tisch des Reichen zu sättigen; aber es kamen sogar die Hunde herbei und beleckten seine Geschwüre.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 16, 22, 'Nun begab es sich, daß der Arme starb und von den Engeln in Abrahams Schoß getragen wurde; auch der Reiche starb und wurde begraben.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 16, 23, 'Als dieser nun im Totenreich, wo er Qualen litt, seine Augen aufschlug, erblickte er Abraham in der Ferne und Lazarus in seinem Schoß.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 16, 24, 'Da rief er mit lauter Stimme: ›Vater Abraham! Erbarme dich meiner und sende Lazarus, damit er seine Fingerspitze ins Wasser tauche und mir die Zunge kühle! Denn ich leide Qualen in dieser Feuerglut.‹');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 16, 25, 'Aber Abraham antwortete: ›Mein Sohn, denke daran, daß du dein Gutes während deines Erdenlebens empfangen hast, und Lazarus gleicherweise das Üble; jetzt aber wird er hier getröstet, während du Qualen leiden mußt.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 16, 26, 'Und zu alledem ist zwischen uns und euch eine große Kluft festgelegt, damit die, welche von hier zu euch hinübergehen wollen, es nicht können und man auch von dort nicht zu uns herüberkommen kann.‹');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 16, 27, 'Da erwiderte er: ›So bitte ich dich denn, Vater: sende ihn in meines Vaters Haus –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 16, 28, 'denn ich habe noch fünf Brüder –, damit er sie ernstlich warne, damit sie nicht auch an diesen Ort der Qual kommen.‹');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 16, 29, 'Abraham aber antwortete: ›Sie haben Mose und die Propheten; auf diese mögen sie hören!‹');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 16, 30, 'Jener jedoch entgegnete: ›Nein, Vater Abraham! Sondern wenn einer von den Toten zu ihnen kommt, dann werden sie sich bekehren.‹');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 16, 31, 'Abraham aber antwortete ihm: ›Wenn sie nicht auf Mose und die Propheten hören, so werden sie sich auch nicht überzeugen lassen, wenn einer von den Toten aufersteht.‹«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 17, 1, 'Weiter sagte Jesus zu seinen Jüngern: »Es kann nicht anders sein, als daß Ärgernisse kommen; wehe aber dem, durch den sie kommen!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 17, 2, 'Es wäre besser für ihn, wenn ihm ein Mühlstein um den Hals gelegt und er ins Meer geworfen wäre, als daß er für einen von diesen geringen Leuten zum Ärgernis wird. –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 17, 3, 'Gebt auf euch selbst acht! Wenn dein Bruder sich (gegen dich) vergangen hat, so halte es ihm vor; und wenn er es bereut, so vergib ihm.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 17, 4, 'Selbst wenn er sich siebenmal am Tage gegen dich vergeht und siebenmal wieder zu dir kommt und erklärt: ›Es tut mir leid!‹, so sollst du ihm vergeben.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 17, 5, 'Die Apostel baten alsdann den Herrn: »Mehre uns den Glauben!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 17, 6, 'Da antwortete der Herr: »Wenn ihr Glauben wie ein Senfkorn hättet und ihr diesem Maulbeerbaum gebötet: ›Entwurzle dich und verpflanze dich ins Meer!‹, so würde er euch gehorsam sein.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 17, 7, '»Wer von euch aber, der einen Knecht beim Pflügen oder beim Viehhüten hat, wird zu ihm bei seiner Heimkehr vom Felde sagen: ›Komm sogleich her und setze dich zu Tisch!‹?');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 17, 8, 'Wird er nicht vielmehr zu ihm sagen: ›Bereite mir mein Abendessen, schürze dich und bediene mich, bis ich gegessen und getrunken habe; nachher magst auch du essen und trinken‹?');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 17, 9, 'Er wird doch wohl dem Knecht nicht noch dankbar dafür sein, daß er die ihm erteilten Befehle ausgeführt hat?');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 17, 10, 'Ebenso steht’s auch bei euch: Wenn ihr alles getan habt, was euch befohlen war, so sagt: ›Wir sind armselige Knechte; wir haben nur unsere Schuldigkeit getan.‹«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 17, 11, 'Auf seiner Wanderung nach Jerusalem durchzog Jesus das Grenzgebiet von Samaria und Galiläa.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 17, 12, 'Als er dort in ein Dorf eintrat, kamen ihm zehn aussätzige Männer entgegen, die in der Ferne stehen blieben');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 17, 13, 'und ihre Stimme erhoben und riefen: »Jesus, (lieber) Meister, erbarme dich unser!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 17, 14, 'Als er sie erblickte, sagte er zu ihnen: »Geht hin und zeigt euch den Priestern.« Während sie dann hingingen, wurden sie rein.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 17, 15, 'Einer von ihnen aber, als er sich geheilt sah, kehrte zurück, pries Gott mit lauter Stimme,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 17, 16, 'warf sich zu Jesu Füßen auf sein Angesicht nieder und dankte ihm; und das war ein Samariter.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 17, 17, 'Da sagte Jesus: »Sind ihrer nicht zehn rein geworden? Wo sind denn die anderen neun?');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 17, 18, 'Hat sich sonst keiner gefunden, der zurückgekehrt ist, um Gott die Ehre zu geben, außer diesem Fremdling?«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 17, 19, 'Zu ihm sagte er dann: »Stehe auf und gehe! Dein Glaube hat dir Rettung verschafft.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 17, 20, 'Als er aber von den Pharisäern aufs neue gefragt wurde, wann das Reich Gottes käme, gab er ihnen zur Antwort: »Das Reich Gottes kommt nicht mit äußerlichem Gebaren;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 17, 21, 'man wird auch nicht sagen können: ›Siehe, hier ist es!‹ oder ›dort ist es!‹ Denn wisset wohl: Das Reich Gottes ist (bereits) mitten unter euch.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 17, 22, 'Weiter sagte er zu seinen Jüngern: »Es werden Tage kommen, wo ihr euch danach sehnen werdet, einen einzigen von den Tagen des Menschensohnes zu sehen, doch ihr werdet ihn nicht sehen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 17, 23, 'Und wird man dann zu euch sagen: ›Seht dort! Seht hier!‹, so geht nicht hin und gebt nichts darauf!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 17, 24, 'Denn wie der Blitz, wenn er aufblitzt, am Himmel hin von einem Ende bis zum andern leuchtet, so wird es auch mit dem Menschensohn an seinem Tage sein.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 17, 25, 'Zuerst muß er aber noch vieles leiden und von diesem Geschlecht verworfen werden.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 17, 26, 'Und wie es in den Tagen Noahs zugegangen ist, so wird es auch in den Tagen des Menschensohnes sein:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 17, 27, 'Man aß und trank, man heiratete und wurde verheiratet bis zu dem Tage, an welchem Noah in die Arche ging und die Sintflut kam und allen den Untergang brachte.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 17, 28, 'Ebenso wie es in den Tagen Lots zugegangen ist: Man aß und trank, man kaufte und verkaufte, man pflanzte und baute;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 17, 29, 'aber an dem Tage, an welchem Lot aus Sodom wegging, regnete es Feuer und Schwefel vom Himmel und vernichtete alle –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 17, 30, 'ebenso wird es auch an dem Tage sein, an welchem der Menschensohn sich offenbart.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 17, 31, 'Wer an diesem Tage auf dem Dache ist, während seine Geräte sich im Hause befinden, der steige nicht erst noch hinab, um sie zu holen; und ebenso, wer auf dem Felde ist, kehre nicht zurück!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 17, 32, 'Denkt an Lots Frau!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 17, 33, 'Wer sein Leben zu erhalten sucht, der wird es verlieren, und wer es verliert, dem wird es erhalten bleiben.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 17, 34, 'Ich sage euch: In der betreffenden Nacht werden zwei (Männer) auf einem Lager liegen: der eine wird angenommen, der andere zurückgelassen werden;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 17, 35, 'zwei (Frauen) werden an derselben Handmühle mahlen: die eine wird angenommen, die andere zurückgelassen werden.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 17, 36, '');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 17, 37, 'Da erwiderten ihm die Jünger mit der Frage: »Herr, wo denn?« Er aber antwortete ihnen: »Wo das Aas liegt, da sammeln sich auch die Geier.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 18, 1, 'Er legte ihnen dann ein Gleichnis vor, um sie darauf hinzuweisen, daß man allezeit beten müsse und nicht müde darin werden dürfe.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 18, 2, '»In einer Stadt«, so sagte er, »lebte ein Richter, der Gott nicht fürchtete und auf keinen Menschen Rücksicht nahm.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 18, 3, 'Nun wohnte in jener Stadt eine Witwe, die (immer wieder) zu ihm kam mit dem Anliegen: ›Schaffe mir Recht gegen meinen Widersacher!‹');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 18, 4, 'Lange Zeit wollte er nicht; schließlich aber dachte er bei sich: ›Wenn ich auch Gott nicht fürchte und auf keinen Menschen Rücksicht nehme,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 18, 5, 'will ich dieser Witwe doch zu ihrem Recht verhelfen, weil sie mir lästig fällt; sonst kommt sie schließlich noch und wird handgreiflich gegen mich.‹«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 18, 6, 'Dann fuhr der Herr fort: »Hört, was (hier) der ungerechte Richter sagt!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 18, 7, 'Sollte nun Gott nicht auch seinen Auserwählten Recht schaffen, die Tag und Nacht zu ihm rufen, auch wenn er Langmut bei ihnen übt?');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 18, 8, 'Ich sage euch: Er wird ihnen gar bald ihr Recht schaffen! Doch wird wohl der Menschensohn bei seinem Kommen den Glauben auf Erden vorfinden?«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 18, 9, 'Er legte dann auch einigen, die von ihrer eigenen Gerechtigkeit überzeugt waren und auf die anderen mit Geringschätzung herabsahen, folgendes Gleichnis vor:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 18, 10, '»Zwei Männer gingen in den Tempel hinauf, um zu beten, der eine ein Pharisäer, der andere ein Zöllner.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 18, 11, 'Der Pharisäer trat hin und betete bei sich so: ›O Gott, ich danke dir, daß ich nicht bin wie die anderen Menschen, Räuber, Betrüger, Ehebrecher oder auch wie der Zöllner dort.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 18, 12, 'Ich faste zweimal in der Woche und gebe den Zehnten von allem, was ich erwerbe.‹');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 18, 13, 'Der Zöllner dagegen stand von ferne und mochte nicht einmal die Augen zum Himmel erheben, sondern schlug sich an die Brust und sagte: ›Gott, sei mir Sünder gnädig!‹');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 18, 14, 'Ich sage euch: Dieser ging gerechtfertigt in sein Haus hinab, ganz anders, als es bei jenem der Fall war! Denn wer sich selbst erhöht, wird erniedrigt werden; wer sich aber selbst erniedrigt, wird erhöht werden.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 18, 15, 'Die Leute brachten aber auch ihre kleinen Kinder zu ihm, damit er sie anrühre; als die Jünger das sahen, verwiesen sie es ihnen in barscher Weise.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 18, 16, 'Jesus aber rief sie zu sich heran und sagte: »Laßt die Kinder zu mir kommen und hindert sie nicht daran,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 18, 17, 'denn für ihresgleichen ist das Reich Gottes bestimmt. Wahrlich ich sage euch: Wer das Reich Gottes nicht wie ein Kind annimmt, wird sicherlich nicht hineinkommen.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 18, 18, 'Hierauf richtete ein Oberster die Frage an ihn: »Guter Meister, was muß ich tun, um ewiges Leben zu ererben?«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 18, 19, 'Jesus antwortete ihm: »Was nennst du mich gut? Niemand ist gut als Gott allein.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 18, 20, 'Du kennst die Gebote: Du sollst nicht ehebrechen, nicht töten, nicht stehlen, nicht falsches Zeugnis ablegen, ehre deinen Vater und deine Mutter!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 18, 21, 'Darauf erwiderte jener: »Dies alles habe ich von Jugend an gehalten.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 18, 22, 'Als Jesus das hörte, sagte er zu ihm: »Eins fehlt dir noch: Verkaufe alles, was du besitzest, und verteile den Erlös an die Armen, so wirst du einen Schatz im Himmel haben; dann komm und folge mir nach.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 18, 23, 'Als jener das hörte, wurde er tief betrübt; denn er war sehr reich.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 18, 24, 'Als Jesus ihn so sah, sagte er: »Wie schwer ist es doch für die Begüterten, in das Reich Gottes einzugehen!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 18, 25, 'Ja, es ist leichter, daß ein Kamel durch ein Nadelöhr hindurchgeht, als daß ein Reicher in das Reich Gottes eingeht.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 18, 26, 'Da sagten die Zuhörer: »Ja, wer kann dann gerettet werden?«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 18, 27, 'Jesus aber antwortete: »Was bei Menschen unmöglich ist, das ist bei Gott möglich.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 18, 28, 'Darauf sagte Petrus: »Siehe, wir haben alles Unsrige verlassen und sind dir nachgefolgt.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 18, 29, 'Da sagte Jesus zu ihnen: »Wahrlich ich sage euch: Niemand hat Haus oder Weib, Geschwister, Eltern oder Kinder um des Reiches Gottes willen verlassen,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 18, 30, 'der nicht vielmal Wertvolleres wiederempfinge (schon) in dieser Zeitlichkeit, und in der zukünftigen Weltzeit ewiges Leben.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 18, 31, 'Er nahm dann die Zwölf zu sich (abseits) und sagte zu ihnen: »Wir ziehen jetzt nach Jerusalem hinauf, und es wird alles in Erfüllung gehen, was durch die Propheten von dem Menschensohn geschrieben ist.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 18, 32, 'Denn er wird den Heiden überliefert und verspottet, mißhandelt und angespien werden,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 18, 33, 'und sie werden ihn geißeln und töten, und am dritten Tage wird er auferstehen.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 18, 34, 'Doch sie verstanden nichts hiervon, sondern dieser Ausspruch war ihnen dunkel, und sie begriffen nicht, was er mit diesem Wort hatte sagen wollen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 18, 35, 'Als er dann in die Nähe von Jericho kam, saß da ein Blinder am Wege und bettelte.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 18, 36, 'Als dieser nun die vielen Leute vorüberziehen hörte, erkundigte er sich, was das zu bedeuten habe.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 18, 37, 'Man teilte ihm mit, daß Jesus von Nazareth vorübergehe.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 18, 38, 'Da rief er laut: »Jesus, Sohn Davids, erbarme dich meiner!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 18, 39, 'Die an der Spitze des Zuges Gehenden riefen ihm drohend zu, er solle still sein; doch er rief nur noch lauter: »Sohn Davids, erbarme dich meiner!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 18, 40, 'Da blieb Jesus stehen und ließ ihn zu sich führen. Als er nun nahe herangekommen war, fragte Jesus ihn:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 18, 41, '»Was wünschest du von mir?« Er antwortete: »Herr, ich möchte sehen können.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 18, 42, 'Jesus erwiderte ihm: »Werde sehend! Dein Glaube hat dir Rettung verschafft.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 18, 43, 'Da konnte er augenblicklich sehen und schloß sich ihm an, indem er Gott pries; auch das gesamte Volk, das zugesehen hatte, gab Gott die Ehre durch Lobpreis.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 19, 1, 'Jesus kam dann nach Jericho hinein und zog durch die Stadt hindurch.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 19, 2, 'Dort wohnte aber ein Mann namens Zachäus, der war ein Oberzöllner und ein reicher Mann.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 19, 3, 'Er hätte Jesus gern von Person gesehen, konnte es aber wegen der Volksmenge nicht, weil er klein von Gestalt war.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 19, 4, 'So eilte er denn auf dem Wege voraus und stieg auf einen Maulbeerfeigenbaum hinauf, um ihn zu sehen; denn dort mußte er vorbeikommen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 19, 5, 'Als nun Jesus an die Stelle kam, blickte er in die Höhe und rief ihm zu: »Zachäus! Steige schnell herunter; denn ich muß heute in deinem Hause einkehren.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 19, 6, 'Da stieg er schnell herab und nahm ihn mit Freuden bei sich auf.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 19, 7, 'Und alle, die es sahen, murrten laut und sagten: »Bei einem sündigen Manne ist er eingekehrt, um bei ihm zu herbergen.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 19, 8, 'Zachäus aber trat zum Herrn und sagte: »Siehe, Herr, die Hälfte meines Vermögens will ich den Armen geben, und wenn ich jemand in etwas übervorteilt habe, will ich es ihm vierfach ersetzen!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 19, 9, 'Da sagte Jesus zu ihm: »Heute ist diesem Hause Heil widerfahren, weil ja auch er ein Sohn Abrahams ist.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 19, 10, 'Denn der Menschensohn ist gekommen, das Verlorene zu suchen und zu retten.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 19, 11, 'Als sie dies hörten, fügte er noch ein Gleichnis hinzu, weil er sich in der Nähe von Jerusalem befand und weil sie meinten, das Reich Gottes würde jetzt sofort erscheinen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 19, 12, 'Er sagte also: »Ein Mann von vornehmer Abkunft reiste in ein fernes Land, um für sich dort die Königswürde zu gewinnen und dann wieder heimzukehren.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 19, 13, 'Er berief nun zehn seiner Knechte, gab ihnen zehn Minen und sagte zu ihnen: ›Macht Geschäfte (mit dem Gelde) in der Zeit, während ich verreist bin!‹');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 19, 14, 'Seine Mitbürger aber haßten ihn und schickten eine Abordnung hinter ihm her, durch die sie erklären ließen: ›Wir wollen diesen Mann nicht als König über uns haben!‹');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 19, 15, 'Als er nun nach Empfang der Königswürde heimkehrte, ließ er jene Knechte, denen er das Geld gegeben hatte, zu sich rufen, um zu erfahren, was für Geschäfte ein jeder gemacht hätte.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 19, 16, 'Da erschien der erste und sagte: ›Herr, dein Pfund hat zehn weitere Pfunde eingebracht.‹');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 19, 17, 'Der Herr antwortete ihm: ›Schön, du guter Knecht! Weil du im Kleinen treu gewesen bist, sollst du die Verwaltung von zehn Städten erhalten.‹');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 19, 18, 'Dann kam der zweite und sagte: ›Herr, dein Pfund hat fünf Pfunde hinzugewonnen.‹');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 19, 19, 'Er sagte auch zu diesem: ›Auch du sollst über fünf Städte gesetzt sein!‹');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 19, 20, 'Hierauf kam der dritte und sagte: ›Herr, hier ist dein Pfund, das ich in einem Schweißtuch wohlverwahrt gehalten habe;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 19, 21, 'denn ich hatte Furcht vor dir, weil du ein strenger Mann bist: du hebst ab, was du nicht eingelegt hast, und erntest, was du nicht gesät hast.‹');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 19, 22, 'Da antwortete er ihm: ›Nach deiner eigenen Aussage will ich dir das Urteil sprechen, du nichtswürdiger Knecht! Du wußtest, daß ich ein strenger Mann bin, daß ich abhebe, was ich nicht eingelegt habe, und ernte, was ich nicht gesät habe?');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 19, 23, 'Warum hast du da mein Geld nicht auf eine Bank gebracht? Dann hätte ich es bei meiner Rückkehr mit Zinsen abgehoben.‹');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 19, 24, 'Darauf befahl er den Dabeistehenden: ›Nehmt ihm das Pfund weg und gebt es dem, der die zehn Pfund hat.‹');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 19, 25, 'Sie erwiderten ihm: ›Herr, er hat ja schon zehn Pfunde.‹');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 19, 26, 'Ich sage euch: Jedem, der da hat, wird (noch dazu) gegeben werden; wer aber nicht hat, dem wird auch das genommen werden, was er hat.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 19, 27, 'Doch jene meine Feinde, die mich nicht zum König über sich gewollt haben, führt hierher und macht sie vor meinen Augen nieder!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 19, 28, 'Nach diesen Worten zog Jesus weiter auf dem Wege nach Jerusalem hinauf.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 19, 29, 'Als er nun in die Nähe von Bethphage und Bethanien am sogenannten Ölberge gekommen war, sandte er zwei von seinen Jüngern ab');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 19, 30, 'mit der Weisung: »Geht in das Dorf, das dort vor euch liegt! Wenn ihr hineinkommt, werdet ihr ein Eselfüllen angebunden finden, auf dem noch nie ein Mensch gesessen hat: bindet es los und führt es her!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 19, 31, 'Und wenn euch jemand fragen sollte: ›Warum bindet ihr es los?‹, so antwortet ihm: ›Der Herr hat es nötig.‹«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 19, 32, 'Als nun die Abgesandten hingegangen waren, fanden sie es so, wie er ihnen gesagt hatte;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 19, 33, 'und als sie das Füllen losbanden, sagten dessen Eigentümer zu ihnen: »Wozu bindet ihr das Füllen los?«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 19, 34, 'Sie antworteten: »Der Herr hat es nötig.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 19, 35, 'Sie führten es darauf zu Jesus, legten ihre Mäntel auf das Füllen und ließen Jesus sich daraufsetzen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 19, 36, 'Während er dann weiterzog, breiteten sie ihre Mäntel auf den Weg aus.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 19, 37, 'Als er nunmehr an den Abstieg vom Ölberg herankam, begann die gesamte Menge der Jünger freudig Gott mit lauter Stimme um all der Wundertaten willen, die sie gesehen hatten, Lobpreis darzubringen,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 19, 38, 'indem sie ausriefen: »Gepriesen sei, der da kommt als König im Namen des Herrn! Im Himmel ist Friede und Ehre in Himmelshöhen!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 19, 39, 'Da sagten einige Pharisäer aus der Volksmenge zu ihm: »Meister, untersage das deinen Jüngern!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 19, 40, 'Doch er gab zur Antwort: »Ich sage euch: Wenn diese schwiegen, würden die Steine schreien!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 19, 41, 'Als er dann nähergekommen war und die Stadt erblickte, weinte er über sie');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 19, 42, 'und sagte: »Wenn doch auch du an diesem Tage erkennen möchtest, was zu deinem Frieden dient! Nun aber ist es deinen Augen verborgen geblieben.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 19, 43, 'Denn es werden Tage über dich kommen, da werden deine Feinde einen Wall gegen dich aufführen, dich ringsum einschließen und dich von allen Seiten bedrängen;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 19, 44, 'sie werden dich und deine Kinder in dir dem Erdboden gleichmachen und keinen Stein in dir auf dem andern lassen zur Strafe dafür, daß du die Zeit deiner (gnadenreichen) Heimsuchung nicht erkannt hast.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 19, 45, 'Als er sich darauf in den Tempel begeben hatte, machte er sich daran, die Verkäufer hinauszutreiben,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 19, 46, 'indem er ihnen zurief: »Es steht geschrieben: ›Mein Haus soll ein Bethaus sein!‹ Ihr aber habt es zu einer ›Räuberhöhle‹ gemacht.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 19, 47, 'Er lehrte dann täglich im Tempel. Die Hohenpriester aber und die Schriftgelehrten samt den Obersten des Volkes trachteten ihm nach dem Leben,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 19, 48, 'fanden jedoch keine Möglichkeit, ihre Absicht gegen ihn auszuführen; denn das gesamte Volk hing an ihm, sooft es ihn hörte.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 20, 1, 'Eines Tages nun, als er das Volk im Tempel lehrte und die Heilsbotschaft verkündigte, traten die Hohenpriester und Schriftgelehrten samt den Ältesten an ihn heran');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 20, 2, 'und sagten zu ihm: »Sage uns, aufgrund welcher Vollmacht du hier in dieser Weise auftrittst oder wer es ist, der dir die Vollmacht dazu gegeben hat?«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 20, 3, 'Da antwortete er ihnen: »Auch ich will euch eine Frage vorlegen; sagt mir:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 20, 4, 'Stammte die Taufe des Johannes vom Himmel oder von Menschen?«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 20, 5, 'Da überlegten sie bei sich folgendermaßen: »Sagen wir: ›Vom Himmel‹, so wird er fragen: ›Warum habt ihr ihm dann keinen Glauben geschenkt?‹');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 20, 6, 'Sagen wir dagegen: ›Von Menschen‹, so wird das ganze Volk uns steinigen; denn es ist überzeugt, daß Johannes ein Prophet (gewesen) ist.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 20, 7, 'So gaben sie ihm denn zur Antwort, sie wüßten nicht, woher sie stamme.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 20, 8, 'Da sagte Jesus zu ihnen: »Dann sage auch ich euch nicht, aufgrund welcher Vollmacht ich hier so auftrete.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 20, 9, 'Er begann dann dem Volk folgendes Gleichnis vorzutragen: »Ein Mann legte einen Weinberg an, verpachtete ihn an Weingärtner und ging dann für längere Zeit ins Ausland.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 20, 10, 'Als nun die Zeit da war, sandte er einen Knecht zu den Weingärtnern, damit sie ihm (seinen Teil) vom Ertrag des Weinbergs abgäben; aber die Weingärtner mißhandelten diesen und schickten ihn mit leeren Händen zurück.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 20, 11, 'Da sandte er nochmals einen andern Knecht; sie aber mißhandelten und beschimpften auch diesen und schickten ihn mit leeren Händen zurück.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 20, 12, 'Er sandte darauf noch einen dritten; sie aber schlugen auch diesen blutig und warfen ihn hinaus.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 20, 13, 'Da sagte der Herr des Weinbergs: ›Was soll ich tun? Ich will meinen geliebten Sohn hinsenden; vor diesem werden sie sich doch wohl scheuen.‹');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 20, 14, 'Als die Weingärtner ihn aber erblickten, überlegten sie miteinander und sagten: ›Dies ist der Erbe! Wir wollen ihn töten: dann fällt das Erbgut uns zu.‹');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 20, 15, 'So stießen sie ihn denn aus dem Weinberge hinaus und schlugen ihn tot. Was wird nun der Herr des Weinbergs mit ihnen machen?');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 20, 16, 'Er wird kommen und diese Weingärtner ums Leben bringen und den Weinberg an andere vergeben.« Als sie das hörten, sagten sie: »Nimmermehr!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 20, 17, 'Jesus aber blickte sie an und sagte: »Was bedeutet denn dieses Schriftwort: ›Der Stein, den die Bauleute (als unbrauchbar) verworfen haben, der ist zum Eckstein geworden‹?');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 20, 18, 'Jeder, der an diesem Steine zu Fall kommt, wird zerschmettert werden; auf wen aber der Stein fällt, den wird er zermalmen.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 20, 19, 'Da suchten die Schriftgelehrten und Hohenpriester ihn noch in derselben Stunde festzunehmen, fürchteten sich jedoch vor dem Volk; sie hatten nämlich wohl gemerkt, daß er dieses Gleichnis gegen sie gerichtet hatte.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 20, 20, 'So lauerten sie ihm denn auf und sandten Aufpasser ab, die sich das Aussehen gesetzesstrenger Leute geben sollten, damit sie ihn durch einen seiner Aussprüche fingen und ihn dann der Obrigkeit und der Gewalt des Statthalters überliefern könnten.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 20, 21, 'Die fragten ihn also: »Meister, wir wissen, daß du offen redest und lehrst und die Person nicht ansiehst, sondern den Weg Gottes mit Wahrhaftigkeit lehrst:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 20, 22, 'ist es recht, daß wir dem Kaiser Steuern entrichten, oder nicht?«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 20, 23, 'Da er nun ihre böse Absicht durchschaute, sagte er zu ihnen:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 20, 24, '»Zeigt mir einen Denar! Wessen Bild und Aufschrift trägt er?« Sie antworteten: »Des Kaisers.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 20, 25, 'Da sagte er zu ihnen: »Nun, so gebt dem Kaiser, was dem Kaiser zukommt, und Gott, was Gott zukommt.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 20, 26, 'Und sie vermochten ihn nicht bei einem Ausspruch vor dem Volk zu fangen und wußten, voll Verwunderung über seine Antwort, nichts mehr zu sagen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 20, 27, 'Hierauf traten einige Sadduzäer herzu, die da behaupten, es gebe keine Auferstehung, und legten ihm eine Frage vor');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 20, 28, 'mit den Worten: »Meister, Mose hat uns vorgeschrieben: ›Wenn jemandem sein Bruder stirbt, der eine Frau hat, jedoch kinderlos geblieben ist, so soll sein Bruder die Frau ehelichen und für seinen Bruder das Geschlecht fortpflanzen.‹');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 20, 29, 'Nun waren da sieben Brüder. Der erste nahm eine Frau und starb kinderlos;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 20, 30, 'der zweite heiratete sie darauf,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 20, 31, 'dann der dritte und in derselben Weise alle sieben, hinterließen aber keine Kinder und starben;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 20, 32, 'zuletzt starb auch die Frau.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 20, 33, 'Wem von ihnen wird diese nun bei der Auferstehung als Frau angehören? Alle sieben haben sie ja zur Frau gehabt.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 20, 34, 'Da sagte Jesus zu ihnen: »Die Kinder der jetzigen Weltzeit heiraten und werden verheiratet;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 20, 35, 'diejenigen aber, welche würdig befunden worden sind, an jener Weltzeit und an der Auferstehung der Toten teilzunehmen, die heiraten weder noch werden sie verheiratet;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 20, 36, 'sie können dann ja auch nicht mehr sterben, denn sie sind den Engeln gleich und sind Söhne Gottes, weil sie Söhne der Auferstehung sind.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 20, 37, 'Daß aber die Toten auferweckt werden, das hat auch Mose bei (der Erzählung von) dem Dornbusch erkennen lassen, indem er dort den Herrn ›den Gott Abrahams, den Gott Isaaks und den Gott Jakobs‹ nennt.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 20, 38, 'Gott ist doch nicht ein Gott von Toten, sondern von Lebenden, denn alle leben ihm.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 20, 39, 'Da antworteten mehrere Schriftgelehrte: »Meister, du hast trefflich gesprochen!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 20, 40, 'Sie wagten auch hinfort nicht mehr, ihm eine Frage vorzulegen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 20, 41, 'Er sagte dann aber zu ihnen: »Wie kann man behaupten, Christus sei Davids Sohn?');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 20, 42, 'David selbst sagt ja doch im Psalmbuch: ›Der Herr hat zu meinem Herrn gesagt: Setze dich zu meiner Rechten,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 20, 43, 'bis ich deine Feinde hinlege zum Schemel deiner Füße.‹');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 20, 44, 'David nennt ihn also ›Herr‹; wie kann er da sein Sohn sein?«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 20, 45, 'Zu seinen Jüngern aber sagte er, während das ganze Volk zuhörte:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 20, 46, '»Hütet euch vor den Schriftgelehrten, die es lieben, in langen Gewändern einherzugehen, und sich auf den öffentlichen Plätzen gern begrüßen lassen; die auf die vordersten Sitze in den Synagogen und auf die obersten Plätze bei den Gastmählern Anspruch machen;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 20, 47, 'die die Häuser der Witwen verschlingen und zum Schein lange Gebete verrichten; diese werden ein besonders strenges Gericht erfahren.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 21, 1, 'Als er dann aufblickte, sah er, wie die Reichen ihre Gaben in den Opferkasten einlegten.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 21, 2, 'Da sah er auch eine arme Witwe dort zwei Scherflein hineintun');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 21, 3, 'und sagte: »Wahrlich ich sage euch: Diese arme Witwe hat mehr als alle anderen eingelegt;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 21, 4, 'denn jene haben alle aus ihrem Überfluß eine Gabe in den Gotteskasten getan, sie aber hat aus ihrer Dürftigkeit alles eingelegt, was sie zum Lebensunterhalt besaß.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 21, 5, 'Als einige dann vom Tempel sagten, er sei (ein Prachtbau) mit herrlichen Steinen und Weihgeschenken geschmückt, antwortete er:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 21, 6, '»Was ihr da anschaut – es werden Tage kommen, an denen kein Stein auf dem andern liegen bleibt, der nicht niedergerissen wird.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 21, 7, 'Da richteten sie die Frage an ihn: »Meister, wann wird dies denn geschehen, und welches ist das Anzeichen dafür, wann dies eintreten wird?«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 21, 8, 'Da antwortete er: »Seht zu, daß ihr nicht irregeführt werdet! Denn viele werden unter meinem Namen kommen und sagen: ›Ich bin es‹, und ›Die Zeit ist nahe!‹ Lauft ihnen nicht nach!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 21, 9, 'Wenn ihr ferner von Kriegen und Aufständen hört, so laßt euch dadurch nicht erschrecken! Denn das muß zuerst kommen, aber das Ende ist dann noch nicht sogleich da.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 21, 10, 'Hierauf fuhr er fort: »Ein Volk wird sich gegen das andere erheben und ein Reich gegen das andere;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 21, 11, 'auch gewaltige Erdbeben werden stattfinden und hier und da Hungersnöte und Seuchen; auch schreckhafte Erscheinungen und große Zeichen vom Himmel her werden erfolgen.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 21, 12, '»Aber ehe alles dies geschieht, wird man Hand an euch legen und euch verfolgen, indem man euch an die Synagogen und Gefängnisse überantwortet und euch vor Könige und Statthalter führt um meines Namens willen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 21, 13, 'Da wird euch dann Gelegenheit geboten werden, Zeugnis (für mich) abzulegen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 21, 14, 'So beherzigt denn (die Warnung) wohl, daß ihr euch nicht im voraus Sorge über die Art eurer Verteidigung machet;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 21, 15, 'denn ich selbst werde euch Redegabe und Weisheit verleihen, der alle eure Widersacher nicht zu widerstehen noch zu widersprechen imstande sein sollen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 21, 16, 'Ihr werdet aber sogar von Eltern und Geschwistern, von Verwandten und Freunden überantwortet werden, ja man wird manche von euch töten,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 21, 17, 'und ihr werdet allen um meines Namens willen verhaßt sein.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 21, 18, 'Doch es soll kein Haar von eurem Haupte verlorengehen:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 21, 19, 'durch standhaftes Ausharren werdet ihr euch das Leben gewinnen.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 21, 20, '»Wenn ihr aber Jerusalem von Kriegsheeren umlagert seht, dann erkennet daran, daß seine Zerstörung nahe bevorsteht.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 21, 21, 'Dann sollen die (Gläubigen) in Judäa ins Gebirge fliehen und die Bewohner (der Hauptstadt) auswandern und die auf dem Lande Wohnenden nicht in die Stadt hineinziehen;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 21, 22, 'denn dies sind die Tage der Vergeltung, damit alles in Erfüllung gehe, was in der Schrift steht.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 21, 23, 'Wehe den Frauen, die in jenen Tagen guter Hoffnung sind, und den Müttern, die ein Kind zu nähren haben! Denn große Not wird im Lande herrschen und ein Zorngericht über dieses Volk ergehen;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 21, 24, 'und sie werden durch die Schärfe des Schwertes fallen und in die Gefangenschaft unter alle Heidenvölker weggeführt werden, und Jerusalem wird von Heiden zertreten werden, bis die Zeiten der Heiden abgelaufen sind.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 21, 25, '»Dann werden Zeichen an Sonne, Mond und Sternen in Erscheinung treten und auf der Erde wird Verzweiflung der Völker in ratloser Angst beim Brausen des Meeres und seines Wogenschwalls herrschen,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 21, 26, 'indem Menschen den Geist aufgeben vor Furcht und in banger Erwartung der Dinge, die über den Erdkreis kommen werden; denn (sogar) die Kräfte des Himmels werden in Erschütterung geraten.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 21, 27, 'Und hierauf wird man den Menschensohn in einer Wolke kommen sehen mit großer Macht und Herrlichkeit.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 21, 28, 'Wenn dies nun zu geschehen beginnt, dann richtet euch auf und hebt eure Häupter empor; denn eure Erlösung naht.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 21, 29, 'Er sagte ihnen dann noch ein Gleichnis: »Seht den Feigenbaum und alle anderen Bäume an:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 21, 30, 'sobald sie ausschlagen, erkennt ihr, wenn ihr es seht, von selbst, daß nunmehr der Sommer nahe ist.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 21, 31, 'So sollt auch ihr, wenn ihr alles dieses eintreten seht, erkennen, daß das Reich Gottes nahe ist.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 21, 32, 'Wahrlich ich sage euch: Dieses Geschlecht wird nicht vergehen, bis alles geschieht.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 21, 33, 'Himmel und Erde werden vergehen, aber meine Worte werden nimmermehr vergehen!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 21, 34, '»Habt aber auf euch selbst acht, daß eure Herzen nicht etwa durch Schlemmerei und Trunkenheit und Sorgen des Lebens beschwert werden und jener Tag euch unvermutet überfalle wie eine Schlinge;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 21, 35, 'denn hereinbrechen wird er über alle Bewohner der ganzen Erde.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 21, 36, 'Seid also allezeit wachsam und betet darum, daß ihr die Kraft empfanget, diesem allem, was da kommen soll, zu entrinnen und vor den Menschensohn hinzutreten!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 21, 37, 'Tagsüber war Jesus im Tempel, wo er lehrte; an jedem Abend aber ging er (aus der Stadt) hinaus und übernachtete am sogenannten Ölberg;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 21, 38, 'und das ganze Volk kam schon frühmorgens zu ihm, um ihm im Tempel zuzuhören.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 22, 1, 'So kam denn das Fest der ungesäuerten Brote, das sogenannte Passah, heran;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 22, 2, 'und die Hohenpriester und Schriftgelehrten suchten Mittel und Wege, wie sie ihn beseitigen könnten; denn sie fürchteten sich vor dem Volke.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 22, 3, 'Da fuhr der Satan in Judas, der den Beinamen Iskariot führte und zur Zahl der Zwölf gehörte:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 22, 4, 'er ging hin und verabredete mit den Hohenpriestern und den Hauptleuten der Tempelwache, wie er ihnen Jesus in die Hände liefern wollte.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 22, 5, 'Darüber freuten sie sich und kamen mit ihm überein, ihm Geld zu geben;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 22, 6, 'er war einverstanden und suchte nun nach einer guten Gelegenheit, um ihnen Jesus hinter dem Rücken des Volkes in die Hände zu liefern.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 22, 7, 'Als dann der Tag der ungesäuerten Brote gekommen war, an dem man das Passahlamm schlachten mußte,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 22, 8, 'sandte er Petrus und Johannes ab mit der Weisung: »Geht hin und richtet uns das Passahmahl zu, damit wir es essen können!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 22, 9, 'Auf ihre Frage: »Wo sollen wir es zurichten?«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 22, 10, 'antwortete er ihnen: »Gebt acht: sobald ihr in die Stadt hineinkommt, wird euch ein Mann begegnen, der einen Krug mit Wasser trägt; folgt ihm in das Haus, in das er hineingeht,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 22, 11, 'und sagt dem Eigentümer des Hauses: ›Der Meister läßt dich fragen: Wo ist der Speisesaal, in welchem ich das Passahlamm mit meinen Jüngern essen kann?‹');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 22, 12, 'Dann wird er euch ein geräumiges, mit Tischpolstern ausgestattetes Obergemach zeigen: dort richtet das Mahl zu!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 22, 13, 'Sie gingen hin und fanden es so, wie er ihnen gesagt hatte, und richteten das Passahmahl zu.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 22, 14, 'Als dann die Stunde gekommen war, setzte er sich zu Tisch und die Apostel mit ihm.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 22, 15, 'Da sagte er zu ihnen: »Herzlich habe ich mich danach gesehnt, dieses Passahmahl vor meinem Leiden noch mit euch zu essen;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 22, 16, 'denn ich sage euch: ich werde es nicht mehr essen, bis es im Reiche Gottes seine Vollendung findet.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 22, 17, 'Dann nahm er einen Becher, sprach das Dankgebet und sagte: »Nehmt diesen (Becher) und teilt ihn unter euch!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 22, 18, 'Denn ich sage euch: Ich werde von nun an von dem Erzeugnis des Weinstocks nicht mehr trinken, bis das Reich Gottes kommt.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 22, 19, 'Dann nahm er Brot, sprach den Lobpreis (Gottes), brach das Brot und gab es ihnen mit den Worten: »Dies ist mein Leib [der für euch dahingegeben wird; das tut zu meinem Gedächtnis!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 22, 20, 'Ebenso tat er mit dem Becher nach dem Mahl und sagte: »Dieser Kelch ist der neue Bund in meinem Blut, das für euch vergossen wird].');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 22, 21, 'Doch wisset wohl: Die Hand meines Verräters ist mit mir zusammen auf dem Tische.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 22, 22, 'Denn der Menschensohn geht zwar dahin, wie es bestimmt ist; doch wehe dem Menschen, durch den er verraten wird!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 22, 23, 'Da fingen sie an, sich untereinander zu besprechen, wer von ihnen es wohl sein möchte, der dies tun würde.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 22, 24, 'Da entstand auch noch ein Streit unter ihnen darüber, wer von ihnen als der Größte zu gelten habe.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 22, 25, 'Er aber sagte zu ihnen: »Die Könige der Völker herrschen gewaltsam über sie, und ihre Machthaber lassen sich ›Wohltäter‹ nennen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 22, 26, 'Bei euch aber darf es nicht so sein, sondern der Größte unter euch muß wie der Jüngste sein und wer obenan sitzt, wie der Aufwartende.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 22, 27, 'Denn wer ist der Größere: der zu Tische sitzt oder der dabei bedient? Doch wohl der zu Tische Sitzende. Ich aber bin in eurer Mitte wie der Aufwartende.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 22, 28, 'Ihr aber seid es, die in meinen Anfechtungen bei mir ausgeharrt haben.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 22, 29, 'So vermache ich euch denn die Königswürde, wie mein Vater sie mir vermacht hat:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 22, 30, 'ihr sollt (dereinst) in meinem Reiche an meinem Tische essen und trinken und sollt auf Thronen sitzen, um die zwölf Stämme Israels zu richten.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 22, 31, '»Simon, Simon! Wisse wohl: der Satan hat sich (von Gott) ausgebeten, Gewalt über euch zu erhalten, um euch zu sichten, wie man Weizen siebt;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 22, 32, 'ich aber habe für dich gebeten, daß dein Glaube nicht ausgehe; und du, wenn du dich einst bekehrt hast, stärke deine Brüder!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 22, 33, 'Da antwortete ihm Petrus: »Herr, ich bin bereit, mit dir sowohl ins Gefängnis als auch in den Tod zu gehen!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 22, 34, 'Jesus aber entgegnete: »Ich sage dir, Petrus: Der Hahn wird heute nicht krähen, bis du dreimal geleugnet hast, mich zu kennen!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 22, 35, 'Dann fuhr er fort: »Als ich euch ohne Geldbeutel, ohne Ranzen und Schuhe aussandte, habt ihr da Mangel an irgend etwas gelitten?« Sie antworteten: »Nein, an nichts!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 22, 36, 'Er fuhr fort: »Jetzt aber – wer einen Beutel (mit Geld) hat, der nehme ihn mit sich, ebenso auch einen Ranzen, und wer nichts (derartiges) hat, verkaufe seinen Mantel und kaufe sich ein Schwert!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 22, 37, 'Denn ich sage euch: Folgendes Schriftwort muß sich an mir erfüllen: ›Er ist unter die Gesetzlosen gerechnet worden‹; denn in der Tat: das mir bestimmte Geschick kommt jetzt zum Abschluß.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 22, 38, 'Da sagten sie: »Herr, siehe, hier sind zwei Schwerter!« Er antwortete ihnen: »Das genügt.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 22, 39, 'Er ging dann (aus der Stadt) hinaus und begab sich nach seiner Gewohnheit an den Ölberg; es begleiteten ihn auch seine Jünger.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 22, 40, 'Als er an Ort und Stelle angelangt war, sagte er zu ihnen: »Betet darum, daß ihr nicht in Versuchung geratet!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 22, 41, 'Darauf entfernte er sich etwa einen Steinwurf weit von ihnen, kniete nieder und betete');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 22, 42, 'mit den Worten: »Vater, wenn du willst, so laß diesen Kelch an mir vorübergehen! Doch nicht mein Wille, sondern der deine geschehe!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 22, 43, 'Da erschien ihm ein Engel vom Himmel und stärkte ihn.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 22, 44, 'Und als er in angstvollen Seelenkampf geraten war, betete er noch inbrünstiger; und sein Schweiß wurde wie Blutstropfen, die zur Erde niederfielen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 22, 45, 'Nach dem Gebet stand er auf, und als er zu seinen Jüngern kam, fand er sie vor Traurigkeit eingeschlafen');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 22, 46, 'und sagte zu ihnen: »Was schlaft ihr? Steht auf und betet, damit ihr nicht in Versuchung geratet!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 22, 47, 'Während er noch (zu ihnen) redete, erschien plötzlich eine Volksschar, und der mit dem Namen Judas, einer von den Zwölfen, ging an ihrer Spitze und trat auf Jesus zu, um ihn zu küssen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 22, 48, 'Jesus aber sagte zu ihm: »Judas, mit einem Kuß verrätst du den Menschensohn?«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 22, 49, 'Als nun die Begleiter Jesu sahen, was da kommen würde, sagten sie: »Herr, sollen wir mit dem Schwert dreinschlagen?«,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 22, 50, 'und einer von ihnen schlug (wirklich) nach dem Knecht des Hohenpriesters und hieb ihm das rechte Ohr ab.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 22, 51, 'Jesus aber antwortete: »Laßt ab! Bis hierher und nicht weiter!« Dann rührte er das Ohr an und heilte ihn.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 22, 52, 'Zu den Hohenpriestern aber und den Hauptleuten der Tempelwache und den Ältesten, die gegen ihn hergekommen waren, sagte Jesus: »Wie gegen einen Räuber seid ihr mit Schwertern und Knütteln ausgezogen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 22, 53, 'Während ich täglich bei euch im Tempel war, habt ihr die Hände nicht gegen mich ausgestreckt. Aber dies ist eure Stunde und die Macht der Finsternis!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 22, 54, 'Als sie ihn dann festgenommen hatten, führten sie ihn ab und brachten ihn in das Haus des Hohenpriesters; Petrus aber folgte von weitem.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 22, 55, 'Als sie dann mitten im Hof ein Feuer angezündet und sich zusammengesetzt hatten, nahm auch Petrus mitten unter ihnen Platz.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 22, 56, 'Da sah ihn eine Magd am Feuer sitzen; sie blickte ihn scharf an und sagte: »Dieser ist auch bei ihm gewesen.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 22, 57, 'Petrus aber leugnete mit den Worten: »Weib, ich kenne ihn nicht!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 22, 58, 'Nach einer kleinen Weile bemerkte ihn ein anderer und sagte: »Du gehörst auch zu ihnen!« Petrus aber entgegnete: »Mensch, ich nicht!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 22, 59, 'Nach Verlauf von etwa einer Stunde versicherte ein anderer bestimmt: »Wahrhaftig, dieser ist auch mit ihm zusammen gewesen, er ist ja auch ein Galiläer!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 22, 60, 'Da entgegnete Petrus: »Mensch, ich verstehe nicht, was du sagst!«; und unmittelbar darauf, während er noch redete, krähte der Hahn.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 22, 61, 'Da wandte der Herr sich um und blickte Petrus an; und Petrus dachte an das Wort des Herrn, wie er zu ihm gesagt hatte: »Ehe noch der Hahn heute kräht, wirst du mich dreimal verleugnen.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 22, 62, 'Und er ging hinaus und weinte bitterlich.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 22, 63, 'Die Männer aber, die Jesus zu bewachen hatten, trieben ihren Spott mit ihm und schlugen ihn;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 22, 64, 'sie verhüllten ihm das Gesicht und richteten dann die Frage an ihn: »Weissage uns: Wer ist’s, der dich (eben) geschlagen hat?«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 22, 65, 'Auch noch viele andere Schmähungen stießen sie gegen ihn aus.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 22, 66, 'Als es dann Tag geworden war, versammelte sich der Rat der Ältesten des Volkes, Hohepriester und Schriftgelehrte; sie ließen ihn in ihre Versammlung führen');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 22, 67, 'und sagten: »Wenn du Christus bist, so sage es uns!« Doch er erwiderte ihnen: »Wenn ich es euch sage, werdet ihr es mir doch nicht glauben,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 22, 68, 'und wenn ich Fragen an euch richte, werdet ihr mir keine Antwort geben.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 22, 69, 'Aber von nun an wird der Menschensohn zur Rechten der Macht Gottes sitzen!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 22, 70, 'Da sagten sie alle: »So bist du also der Sohn Gottes?« Er antwortete ihnen: »Ja, ihr selbst sagt es: ich bin’s.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 22, 71, 'Da erklärten sie: »Wozu haben wir noch weitere Zeugenaussagen nötig? Wir haben es ja selbst aus seinem Munde gehört!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 23, 1, 'Nun erhob sich ihre ganze Versammlung, und sie führten ihn dem Pilatus vor.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 23, 2, 'Dort erhoben sie folgende Anklagen gegen ihn: »Wir haben festgestellt, daß dieser Mensch unser Volk aufwiegelt und es davon abhalten will, dem Kaiser Steuern zu entrichten, und daß er behauptet, er sei Christus, ein König.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 23, 3, 'Pilatus fragte ihn nun: »Bist du der König der Juden?«, und Jesus antwortete ihm: »Ja, ich bin es!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 23, 4, 'Da sagte Pilatus zu den Hohenpriestern und der Volksmenge: »Ich finde keine Schuld an diesem Manne.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 23, 5, 'Sie aber versicherten immer heftiger: »Er wiegelt das Volk auf, indem er seine Lehre im ganzen jüdischen Lande verbreitet: in Galiläa hat er damit begonnen und bis hierher es fortgesetzt!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 23, 6, 'Als Pilatus das hörte, fragte er, ob der Mann ein Galiläer wäre;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 23, 7, 'und als er vernahm, daß er aus dem Machtbereich des Herodes sei, sandte er ihn dem Herodes zu, der in diesen Tagen ebenfalls in Jerusalem weilte.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 23, 8, 'Herodes aber war sehr erfreut darüber, Jesus zu sehen; denn er hätte ihn längst gern gesehen, weil er viel über ihn gehört hatte; er hoffte auch, ein Wunderzeichen von ihm vollführt zu sehen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 23, 9, 'So richtete er denn mancherlei Fragen an ihn, doch Jesus gab ihm keinerlei Antwort;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 23, 10, 'die Hohenpriester und Schriftgelehrten aber standen dabei und verklagten ihn leidenschaftlich.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 23, 11, 'Da behandelte ihn denn Herodes samt den Herren seines Gefolges mit Verachtung und Hohn und sandte ihn, nachdem er ihm ein Prachtgewand hatte anlegen lassen, zu Pilatus zurück.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 23, 12, 'An diesem Tage wurden Herodes und Pilatus miteinander befreundet, während sie vordem in Feindschaft gegeneinander gestanden hatten.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 23, 13, 'Pilatus ließ nun die Hohenpriester und die Mitglieder des Hohen Rates und das Volk zusammenrufen');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 23, 14, 'und sagte zu ihnen: »Ihr habt mir diesen Mann als einen Volksverführer vorgeführt. Nun, ihr seht, ich habe ihn in eurem Beisein verhört, habe aber an ihm durchaus nicht die Schuld gefunden, deren ihr ihn anklagt.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 23, 15, 'Ebensowenig auch Herodes, denn er hat ihn an uns zurückverwiesen. Ihr seht also: nichts, was die Todesstrafe verdient, ist von ihm begangen worden.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 23, 16, 'Darum will ich ihn geißeln lassen und dann freigeben.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 23, 17, '[Er war aber verpflichtet, ihnen an jedem Fest einen (Gefangenen) freizugeben.]');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 23, 18, 'Da schrien sie aber allesamt: »Hinweg mit diesem! Gib uns dagegen Barabbas frei!« –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 23, 19, 'dieser saß nämlich wegen eines Aufruhrs, der in der Stadt vorgekommen war, und wegen Mordes im Gefängnis.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 23, 20, 'Da redete Pilatus zum zweitenmal auf sie ein, weil er Jesus gern freigeben wollte;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 23, 21, 'sie aber riefen ihm dagegen zu: »Kreuzige, kreuzige ihn!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 23, 22, 'Zum drittenmal fragte er sie dann: »Was hat denn dieser Mann Böses getan? Ich habe keine todeswürdige Schuld an ihm gefunden! Ich will ihn also geißeln lassen und dann freigeben.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 23, 23, 'Sie aber bestürmten ihn mit lautem Geschrei und verlangten seine Kreuzigung; und ihr Geschrei drang durch.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 23, 24, 'So fällte denn Pilatus das Urteil, ihr Verlangen solle erfüllt werden.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 23, 25, 'Er gab also den Mann frei, der wegen Aufruhrs und Mordes ins Gefängnis geworfen worden war, wie sie es verlangten; Jesus dagegen gab er ihrem Willen preis.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 23, 26, 'Als sie ihn dann (zur Richtstätte) abführten, griffen sie einen gewissen Simon aus Cyrene auf, der vom Felde heimkam, und bürdeten ihm das Kreuz auf, damit er es Jesu nachtrüge.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 23, 27, 'Es folgte ihm aber eine große Volksmenge, auch viele Frauen, die um ihn wehklagten und weinten.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 23, 28, 'Da wandte Jesus sich zu ihnen um und sagte: »Ihr Töchter Jerusalems, weint nicht über mich, weint vielmehr über euch selbst und über eure Kinder!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 23, 29, 'Denn wisset wohl: es kommen Tage, an denen man sagen wird: ›Glücklich zu preisen sind die Unfruchtbaren und die Frauen, die nicht Mutter geworden sind und die kein Kind an der Brust genährt haben!‹');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 23, 30, 'Dann wird man anfangen, den Bergen zuzurufen: ›Fallet auf uns!‹ und den Hügeln: ›Bedecket uns!‹');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 23, 31, 'Denn wenn man dies am grünen Holze tut, was wird da erst am dürren geschehen?«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 23, 32, 'Es wurden aber außerdem noch zwei Verbrecher mit ihm zur Hinrichtung abgeführt.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 23, 33, 'Als sie nun an den Platz gekommen waren, der ›Schädel(stätte)‹ heißt, kreuzigten sie dort ihn und die beiden Verbrecher, den einen zu seiner Rechten, den anderen zu seiner Linken.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 23, 34, 'Jesus aber sprach: »Vater, vergib ihnen, denn sie wissen nicht, was sie tun!« Darauf verteilten sie seine Kleidungsstücke unter sich, indem sie das Los darüber warfen;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 23, 35, 'und das Volk stand dabei und sah zu. Es verhöhnten (ihn) aber auch die Mitglieder des Hohen Rates mit den Worten: »Anderen hat er geholfen; so helfe er nun sich selbst, wenn er wirklich Christus, der Gesalbte Gottes, ist, der Auserwählte!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 23, 36, 'Auch die Soldaten verspotteten ihn: sie traten hinzu, reichten ihm Essig');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 23, 37, 'und sagten: »Bist du der König der Juden, so hilf dir selbst!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 23, 38, 'Über ihm war aber auch eine Inschrift angebracht [in griechischer, lateinischer und hebräischer Schrift]: »Dies ist der König der Juden.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 23, 39, 'Einer aber von den Verbrechern, die da gehenkt waren, schmähte ihn mit den Worten: »Du willst Christus sein? So hilf dir doch selbst und uns!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 23, 40, 'Da antwortete ihm der andere mit lautem Vorwurf: »Hast du denn nicht einmal Furcht vor Gott, da dich doch derselbe Urteilsspruch getroffen hat?');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 23, 41, 'Und zwar uns beide mit Recht, denn wir empfangen den Lohn für unsere Taten; dieser aber hat nichts Unrechtes getan!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 23, 42, 'Dann fuhr er fort: »Jesus, denke an mich, wenn du in deine Königsherrschaft kommst!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 23, 43, 'Da sagte Jesus zu ihm: »Wahrlich ich sage dir: Heute (noch) wirst du mit mir im Paradiese sein!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 23, 44, 'Es war nunmehr um die sechste Stunde: da kam eine Finsternis über das ganze Land bis zur neunten Stunde,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 23, 45, 'indem die Sonne ihren Schein verlor; und der Vorhang im Tempel riß mitten entzwei.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 23, 46, 'Da rief Jesus mit lauter Stimme die Worte aus: »Vater, in deine Hände befehle ich meinen Geist!«, und nach diesen Worten verschied er.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 23, 47, 'Als nun der Hauptmann sah, was geschehen war, pries er Gott und sagte: »Dieser Mann ist wirklich ein Gerechter gewesen!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 23, 48, 'Und die ganze Volksmenge, die zu diesem Schauspiel zusammengekommen war und alles sah, was sich zugetragen hatte, schlug sich an die Brust und kehrte heim.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 23, 49, 'Alle seine Bekannten aber standen von ferne, auch die Frauen, die ihm aus Galiläa nachgefolgt waren und dies alles mit ansahen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 23, 50, 'Und siehe, ein Mann namens Joseph, der ein Mitglied des Hohen Rates war, ein guter und gerechter Mann –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 23, 51, 'er war mit ihrem Beschluß und ihrer Handlungsweise nicht einverstanden gewesen – aus der jüdischen Stadt Arimathäa, der auf das Reich Gottes wartete:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 23, 52, 'dieser ging zu Pilatus und bat ihn um den Leichnam Jesu.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 23, 53, 'Dann nahm er ihn (vom Kreuz) herab, wickelte ihn in feine Leinwand und legte ihn in ein Grab, das in den Felsen gehauen und in welchem bisher noch niemand beigesetzt worden war.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 23, 54, 'Es war aber der Rüsttag, und der Sabbat wollte anbrechen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 23, 55, 'Die Frauen aber, die ihn aus Galiläa begleitet hatten, waren mitgegangen und hatten sich das Grab und die Beisetzung seines Leichnams angesehen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 23, 56, 'Nachdem sie hierauf (in die Stadt) zurückgekehrt waren, besorgten sie wohlriechende Stoffe und Salben und brachten dann den Sabbat nach der Vorschrift des Gesetzes in der Stille zu.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 24, 1, 'Am ersten Tage nach dem Sabbat aber kamen sie beim Morgengrauen zum Grabe mit den wohlriechenden Stoffen, die sie zubereitet hatten.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 24, 2, 'Da fanden sie den Stein vom Grabe weggewälzt,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 24, 3, 'doch als sie hineingetreten waren, fanden sie den Leichnam des Herrn Jesus nicht.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 24, 4, 'Während sie nun hierüber ratlos waren, standen plötzlich zwei Männer in strahlenden Gewändern bei ihnen;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 24, 5, 'und als sie in Furcht gerieten und den Blick zu Boden schlugen, sagten diese zu ihnen: »Was sucht ihr den Lebenden bei den Toten?');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 24, 6, 'Er ist nicht (mehr) hier, sondern ist auferweckt worden. Denkt daran, wie er zu euch geredet hat, als er noch in Galiläa war,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 24, 7, 'und aussagte, der Menschensohn müsse in die Hände sündiger Menschen ausgeliefert und ans Kreuz geschlagen werden und am dritten Tage auferstehen.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 24, 8, 'Da erinnerten sie sich seiner Worte,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 24, 9, 'kehrten vom Grabe zurück und berichteten dies alles den elf (Jüngern) und allen übrigen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 24, 10, 'Es waren dies aber Maria von Magdala und Johanna und Maria, die Mutter des Jakobus, und die anderen Frauen mit ihnen, die den Aposteln dies berichteten;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 24, 11, 'doch diese Mitteilungen erschienen ihnen als leeres Gerede, und sie schenkten ihnen keinen Glauben.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 24, 12, 'Petrus aber machte sich auf und eilte zum Grabe, und als er sich hineinbückte, sah er nur die Leintücher daliegen; so kehrte er denn nach Hause zurück, voll Verwunderung über das Geschehene.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 24, 13, 'Und siehe, zwei von ihnen waren an demselben Tage auf der Wanderung nach einem Dorf begriffen, das sechzig Stadien von Jerusalem entfernt lag und Emmaus hieß.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 24, 14, 'Sie unterhielten sich miteinander über alle diese Begebenheiten.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 24, 15, 'Während sie sich nun so unterhielten und sich gegeneinander aussprachen, kam Jesus selbst hinzu und schloß sich ihnen auf der Wanderung an;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 24, 16, 'ihre Augen jedoch wurden gehalten, so daß sie ihn nicht erkannten.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 24, 17, 'Er fragte sie nun: »Was sind das für Gespräche, die ihr da auf eurer Wanderung miteinander führt?« Da blieben sie betrübten Angesichts stehen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 24, 18, 'Der eine aber von ihnen, namens Kleopas, erwiderte ihm: »Du bist wohl der einzige, der sich in Jerusalem aufhält und nichts von dem erfahren hat, was in diesen Tagen dort geschehen ist?«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 24, 19, 'Er fragte sie: »Was denn?« Sie antworteten ihm: »Das, was mit Jesus von Nazareth geschehen ist, der ein Prophet war, gewaltig in Tat und Wort vor Gott und dem ganzen Volk.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 24, 20, 'Ihn haben unsere Hohenpriester und der Hohe Rat zur Todesstrafe ausgeliefert und ans Kreuz gebracht.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 24, 21, 'Wir aber hatten gehofft, daß er es sei, der Israel erlösen würde; aber nun ist bei dem allem heute schon der dritte Tag, seit dies geschehen ist.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 24, 22, 'Dazu haben uns aber auch noch einige Frauen, die zu uns gehören, in Bestürzung versetzt: sie sind heute in der Frühe am Grabe gewesen');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 24, 23, 'und haben, als sie seinen Leichnam nicht gefunden hatten, nach ihrer Rückkehr erzählt, sie hätten auch noch eine Erscheinung von Engeln gesehen, und diese hätten gesagt, daß er lebe.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 24, 24, 'Da sind denn einige der Unseren zum Grabe hingegangen und haben es so gefunden, wie die Frauen berichtet hatten, ihn selbst aber haben sie nicht gesehen.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 24, 25, 'Da sagte er zu ihnen: »O ihr Gedankenlosen, wie ist doch euer Herz so träge, um an alles das zu glauben, was die Propheten verkündigt haben!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 24, 26, 'Mußte denn Christus dies nicht leiden und dann in seine Herrlichkeit eingehen?«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 24, 27, 'Darauf fing er bei Mose und allen Propheten an und legte ihnen alle Schriftstellen aus, die sich auf ihn bezogen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 24, 28, 'So kamen sie in die Nähe des Dorfes, wohin die Wanderung ging, und er tat so, als wollte er weiterwandern.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 24, 29, 'Da nötigten sie ihn mit den Worten: »Bleibe bei uns, denn es will Abend werden, und der Tag hat sich schon geneigt!« So trat er denn ein, um bei ihnen zu bleiben.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 24, 30, 'Als er sich hierauf mit ihnen zu Tisch gesetzt hatte, nahm er das Brot, sprach den Lobpreis (Gottes), brach das Brot und gab es ihnen:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 24, 31, 'da gingen ihnen die Augen auf, und sie erkannten ihn; doch er entschwand ihren Blicken.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 24, 32, 'Da sagten sie zueinander: »Brannte nicht unser Herz in uns, als er unterwegs mit uns redete und uns den Sinn der Schriftstellen erschloß?«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 24, 33, 'Und sie machten sich noch in derselben Stunde auf, kehrten nach Jerusalem zurück und fanden dort die Elf nebst ihren Genossen versammelt;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 24, 34, 'diese teilten ihnen mit: »Der Herr ist wirklich auferweckt worden und ist dem Simon erschienen!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 24, 35, 'Da erzählten auch sie, was sich unterwegs zugetragen hatte und wie er von ihnen am Brechen des Brotes erkannt worden war.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 24, 36, 'Während sie hierüber noch sprachen, trat Jesus selbst mitten unter sie mit den Worten: »Friede sei mit euch!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 24, 37, 'Da gerieten sie in Angst und Furcht und meinten, einen Geist zu sehen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 24, 38, 'Doch er sagte zu ihnen: »Was seid ihr so bestürzt, und warum steigen Zweifel in euren Herzen auf?');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 24, 39, 'Seht meine Hände und meine Füße an, daß ich es leibhaftig bin! Betastet mich und beschaut mich; ein Geist hat ja doch kein Fleisch und keine Knochen, wie ihr solche an mir wahrnehmt.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 24, 40, 'Nach diesen Worten zeigte er ihnen seine Hände und Füße.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 24, 41, 'Als sie aber vor Freude immer noch ungläubig und voll Verwunderung waren, fragte er sie:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 24, 42, '»Habt ihr hier nicht etwas zu essen?« Da reichten sie ihm ein Stück von einem gebratenen Fisch;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 24, 43, 'das nahm er und aß es vor ihren Augen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 24, 44, 'Dann sagte er zu ihnen: »Dies besagen meine Worte, die ich zu euch gesprochen habe, als ich noch bei euch war: es müsse alles in Erfüllung gehen, was im mosaischen Gesetz, bei den Propheten und in den Psalmen über mich geschrieben steht.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 24, 45, 'Hierauf erschloß er ihnen den Sinn für das Verständnis der Schriften');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 24, 46, 'und sagte zu ihnen: »So steht geschrieben: Christus muß leiden und am dritten Tage von den Toten auferstehen,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 24, 47, 'und auf Grund seines Namens muß Buße zur Vergebung der Sünden bei allen Völkern gepredigt werden, zuerst aber in Jerusalem.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 24, 48, 'Ihr seid die Zeugen hierfür.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 24, 49, 'Und wisset wohl: Ich sende das Verheißungsgut meines Vaters auf euch herab; ihr aber bleibt hier in der Stadt, bis ihr mit Kraft aus der Höhe ausgerüstet worden seid!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 24, 50, 'Hierauf führte er sie (aus der Stadt) hinaus bis in die Nähe von Bethanien, erhob dann seine Hände und segnete sie;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 24, 51, 'und es begab sich: während er sie segnete, schied er von ihnen und wurde in den Himmel emporgehoben.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 24, 52, 'Und sie warfen sich anbetend vor ihm nieder und kehrten hocherfreut nach Jerusalem zurück');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 24, 53, 'und hielten sich beständig im Tempel auf und priesen Gott.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 1, 1, 'Im Anfang war das Wort, und das Wort war bei Gott, und Gott war das Wort.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 1, 2, 'Dieses war im Anfang bei Gott.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 1, 3, 'Alle Dinge sind durch dieses (Wort) geworden, und ohne dieses ist nichts geworden (von allem), was geworden ist.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 1, 4, 'In ihm war Leben, und das Leben war das Licht der Menschen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 1, 5, 'Und das Licht leuchtet in der Finsternis, doch die Finsternis hat es nicht ergriffen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 1, 6, 'Es trat ein Mann auf, von Gott gesandt, sein Name war Johannes;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 1, 7, 'dieser kam, um Zeugnis abzulegen, Zeugnis von dem Licht, damit alle durch ihn zum Glauben kämen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 1, 8, 'Er war nicht selbst das Licht, sondern Zeugnis sollte er von dem Licht ablegen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 1, 9, 'Das Licht war da, das wahre, das jeden Menschen erleuchtet, es kam gerade in die Welt;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 1, 10, 'es war in der Welt, und die Welt war durch ihn (der das Licht war) geschaffen worden, doch die Welt erkannte ihn nicht.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 1, 11, 'Er kam in das Seine, doch die Seinen nahmen ihn nicht auf;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 1, 12, 'allen aber, die ihn annahmen, verlieh er das Anrecht, Kinder Gottes zu werden, nämlich denen, die an seinen Namen glauben,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 1, 13, 'die nicht durch Geblüt oder durch den Naturtrieb des Fleisches, auch nicht durch den Willen eines Mannes, sondern aus Gott gezeugt sind.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 1, 14, 'Und das Wort wurde Fleisch und nahm seine Wohnung unter uns, und wir haben seine Herrlichkeit geschaut, eine Herrlichkeit, wie sie dem eingeborenen Sohne vom Vater verliehen wird; eine mit Gnade und Wahrheit erfüllte.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 1, 15, 'Johannes legt Zeugnis von ihm ab und hat laut verkündet: »Dieser war es, von dem ich gesagt habe: ›Der nach mir kommt, ist (schon) vor mir gewesen, denn er war eher als ich.‹«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 1, 16, 'Aus seiner Fülle haben wir ja alle empfangen, und zwar Gnade über Gnade.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 1, 17, 'Denn das Gesetz ist durch Mose gegeben worden, aber die Gnade und die Wahrheit sind durch Jesus Christus geworden.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 1, 18, 'Niemand hat Gott jemals gesehen: der eingeborene Sohn, der an des Vaters Brust liegt, der hat Kunde (von ihm) gebracht.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 1, 19, 'Dies ist nun das Zeugnis des Johannes, als die Juden aus Jerusalem Priester und Leviten zu ihm sandten, die ihn fragen sollten, wer er sei.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 1, 20, 'Da bekannte er unverhohlen und erklärte offen: »Ich bin nicht Christus.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 1, 21, 'Sie fragten ihn weiter: »Was denn? Bist du Elia?« Er sagte: »Nein, ich bin es nicht.« »Bist du der Prophet?« Er antwortete: »Nein.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 1, 22, 'Da sagten sie zu ihm: »Wer bist du denn? Wir müssen doch denen, die uns gesandt haben, eine Antwort bringen! Wofür gibst du selbst dich aus?«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 1, 23, 'Da antwortete er: »Ich bin die Stimme dessen, der in der Wüste ruft: ›Ebnet dem Herrn den Weg!‹, wie der Prophet Jesaja geboten hat.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 1, 24, 'Die Gesandten aber gehörten zu den Pharisäern');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 1, 25, 'und fragten ihn weiter: »Warum taufst du denn, wenn du weder Christus noch Elia, noch der Prophet bist?«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 1, 26, 'Da antwortete Johannes ihnen: »Ich taufe nur mit Wasser; aber mitten unter euch steht der, den ihr nicht kennt,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 1, 27, 'der nach mir kommt und für den ich nicht gut genug bin, ihm den Riemen seines Schuhwerks aufzubinden.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 1, 28, 'Dies ist in Bethanien geschehen jenseits des Jordans, wo Johannes sich aufhielt und taufte.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 1, 29, 'Am folgenden Tage sah er Jesus auf sich zukommen; da sagte er: »Seht, das Lamm Gottes, das die Sünde der Welt hinwegnimmt!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 1, 30, 'Dieser ist’s, von dem ich gesagt habe: ›Nach mir kommt ein Mann, der (schon) vor mir gewesen ist; denn er war eher da als ich.‹');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 1, 31, 'Ich selbst kannte ihn nicht; aber damit er Israel offenbart würde, deshalb bin ich gekommen, ich mit meiner Wassertaufe.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 1, 32, 'Weiter legte Johannes Zeugnis ab mit den Worten: »Ich habe gesehen, daß der Geist wie eine Taube aus dem Himmel herabschwebte und auf ihm blieb;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 1, 33, 'und ich selbst kannte ihn nicht, aber der, welcher mich gesandt hat, um mit Wasser zu taufen, der hat zu mir gesagt: ›Auf welchen du den Geist herabschweben und auf ihm bleiben siehst, der ist’s, der mit heiligem Geiste tauft.‹');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 1, 34, 'Nun habe ich selbst es auch gesehen und bezeugt, daß dieser der Sohn Gottes ist.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 1, 35, 'Am folgenden Tage stand Johannes wieder da mit zweien seiner Jünger,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 1, 36, 'und indem er den Blick auf Jesus richtete, der dort umherging, sagte er: »Seht, das Lamm Gottes!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 1, 37, 'Als die beiden Jünger ihn das sagen hörten, gingen sie hinter Jesus her;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 1, 38, 'dieser wandte sich um, und als er sie hinter sich herkommen sah, fragte er sie: »Was sucht ihr?« Sie antworteten ihm: »Rabbi« – das heißt übersetzt ›Meister‹ –, »wo hast du deine Herberge?«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 1, 39, 'Er antwortete ihnen: »Kommt mit, so werdet ihr es sehen!« Sie gingen also mit und sahen, wo er seine Herberge hatte, und blieben jenen ganzen Tag bei ihm; es war um die zehnte Stunde.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 1, 40, 'Andreas, der Bruder des Simon Petrus, war einer von den beiden, die es von Johannes gehört hatten und hinter Jesus hergegangen waren.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 1, 41, 'Dieser traf zuerst seinen Bruder Simon und sagte zu ihm: »Wir haben den Messias« – das heißt übersetzt ›den Gesalbten‹ – »gefunden.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 1, 42, 'Er führte ihn dann zu Jesus; dieser blickte ihn an und sagte: »Du bist Simon, der Sohn des Johannes; du sollst Kephas – das heißt übersetzt ›Fels‹ – heißen.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 1, 43, 'Am folgenden Tage wollte Jesus nach Galiläa aufbrechen; da traf er Philippus und sagte zu ihm: »Folge mir nach!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 1, 44, 'Philippus stammte aber aus Bethsaida, dem Heimatort des Andreas und des Petrus.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 1, 45, 'Philippus traf (darauf) den Nathanael und berichtete ihm: »Wir haben den gefunden, von welchem Mose im Gesetz und die Propheten geschrieben haben, Jesus, den Sohn Josephs, aus Nazareth.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 1, 46, 'Da sagte Nathanael zu ihm: »Kann aus Nazareth etwas Gutes kommen?« Philippus erwiderte ihm: »Komm mit uns sieh!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 1, 47, 'Als Jesus den Nathanael auf sich zukommen sah, sagte er von ihm: »Siehe da, in Wahrheit ein Israelit, in dem kein Falsch ist!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 1, 48, 'Nathanael fragte ihn: »Woher kennst du mich?« Jesus antwortete ihm mit den Worten: »Noch ehe Philippus dich rief, als du unter dem Feigenbaum warst, habe ich dich gesehen.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 1, 49, 'Da antwortete ihm Nathanael: »Rabbi, du bist Gottes Sohn, du bist der König von Israel!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 1, 50, 'Jesus gab ihm zur Antwort: »Du glaubst (an mich), weil ich dir gesagt habe, daß ich dich unter dem Feigenbaum gesehen habe? Du wirst noch Größeres als dies zu sehen bekommen.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 1, 51, 'Dann fuhr er fort: »Wahrlich, wahrlich ich sage euch: Ihr werdet den Himmel offen sehen und die Engel Gottes über dem Menschensohn hinauf- und herabsteigen sehen.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 2, 1, 'Am dritten Tage darauf fand zu Kana in Galiläa eine Hochzeit statt, und die Mutter Jesu nahm daran teil;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 2, 2, 'aber auch Jesus wurde mit seinen Jüngern zu der Hochzeit eingeladen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 2, 3, 'Als es nun an Wein mangelte, sagte die Mutter Jesu zu ihm: »Sie haben keinen Wein (mehr)!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 2, 4, 'Jesus antwortete ihr: »Was kümmern dich meine Angelegenheiten, Frau? Meine Stunde ist noch nicht gekommen.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 2, 5, 'Seine Mutter sagte dann zu den Aufwärtern: »Was er euch etwa sagt, das tut.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 2, 6, 'Nun waren dort sechs steinerne Wassergefäße aufgestellt, wie es die Sitte der jüdischen Reinigung erforderte; jedes von ihnen faßte zwei bis drei große Eimer.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 2, 7, 'Da sagte Jesus zu den Aufwärtern: »Füllt die Gefäße mit Wasser!« Sie füllten sie darauf bis oben hin.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 2, 8, 'Dann sagte er zu ihnen: »Schöpft nun davon und bringt es dem Speisemeister!« Sie brachten es hin.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 2, 9, 'Als aber der Speisemeister das zu Wein gewordene Wasser gekostet hatte, ohne zu wissen, woher es gekommen war – die Aufwärter aber, die das Wasser geschöpft hatten, wußten es –, ließ der Speisemeister den Bräutigam rufen');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 2, 10, 'und sagte zu ihm: »Jedermann setzt doch (seinen Gästen) zuerst den guten Wein vor und, wenn sie trunken geworden sind, dann den geringeren; du aber hast den guten Wein bis jetzt zurückbehalten.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 2, 11, 'Hiermit machte Jesus den Anfang seiner Zeichen zu Kana in Galiläa; er offenbarte dadurch seine (göttliche) Herrlichkeit, und seine Jünger lernten an ihn glauben.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 2, 12, 'Hierauf zog er nach Kapernaum hinab, er, seine Mutter, seine Brüder und seine Jünger; sie blieben dort aber nur wenige Tage;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 2, 13, 'denn weil das Passah der Juden nahe bevorstand, zog Jesus nach Jerusalem hinauf.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 2, 14, 'Er fand dort im Tempel die Verkäufer von Rindern, Schafen und Tauben und die Geldwechsler sitzen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 2, 15, 'Da flocht er sich eine Geißel aus Stricken und trieb sie alle samt ihren Schafen und Rindern aus dem Tempel hinaus, verschüttete den Wechslern das Geld und stieß ihnen die Tische um');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 2, 16, 'und rief den Taubenhändlern zu: »Schafft das weg von hier, macht das Haus meines Vaters nicht zu einem Kaufhaus!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 2, 17, 'Da dachten seine Jünger an das Schriftwort: »Der Eifer um dein Haus wird mich verzehren.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 2, 18, 'Nun richteten die Juden die Frage an ihn: »Welches Wunderzeichen läßt du uns sehen (zum Beweis dafür), daß du so vorgehen darfst?«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 2, 19, 'Jesus antwortete ihnen mit den Worten: »Brecht diesen Tempel ab, so werde ich ihn in drei Tagen wieder erstehen lassen!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 2, 20, 'Da sagten die Juden: »Sechsundvierzig Jahre lang hat man an diesem Tempel gebaut, und du willst ihn in drei Tagen wieder erstehen lassen?«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 2, 21, 'Jesus hatte aber den Tempel seines eigenen Leibes gemeint.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 2, 22, 'Als er nun (später) von den Toten auferweckt worden war, dachten seine Jünger an diese seine Worte und kamen zum Glauben an die Schrift und an den Ausspruch, den Jesus (damals) getan hatte.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 2, 23, 'Während er sich nun am Passahfest in Jerusalem aufhielt, kamen viele zum Glauben an seinen Namen, weil sie die Wunderzeichen sahen, die er tat.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 2, 24, 'Jesus selbst aber vertraute sich ihnen nicht an, weil er alle kannte');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 2, 25, 'und von niemand ein Zeugnis über irgendeinen Menschen nötig hatte; denn er erkannte von sich selbst aus, wie es innerlich mit jedem Menschen stand.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 3, 1, 'Nun war da unter den Pharisäern ein Mann namens Nikodemus, ein Mitglied des Hohen Rates der Juden;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 3, 2, 'dieser kam zu Jesus bei Nacht und sagte zu ihm: »Rabbi, wir wissen: du bist als Lehrer von Gott gekommen; denn niemand kann solche Wunderzeichen tun, wie du sie tust, wenn Gott nicht mit ihm ist.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 3, 3, 'Jesus gab ihm zur Antwort: »Wahrlich, wahrlich ich sage dir: Wenn jemand nicht von oben her geboren wird, kann er das Reich Gottes nicht sehen.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 3, 4, 'Nikodemus entgegnete ihm: »Wie kann jemand geboren werden, wenn er ein Greis ist? Kann er etwa zum zweitenmal in den Schoß seiner Mutter eingehen und geboren werden?«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 3, 5, 'Jesus antwortete: »Wahrlich, wahrlich ich sage dir: Wenn jemand nicht aus Wasser und Geist geboren wird, kann er nicht in das Reich Gottes eingehen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 3, 6, 'Was aus dem Fleisch geboren ist, das ist Fleisch, und was aus dem Geist geboren ist, das ist Geist.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 3, 7, 'Wundere dich nicht, daß ich zu dir gesagt habe: Ihr müßt von oben her geboren werden.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 3, 8, 'Der Wind weht, wo er will, und du hörst sein Sausen wohl, weißt aber nicht, woher er kommt und wohin er fährt. Ebenso verhält es sich auch mit jedem, der aus dem Geist geboren ist.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 3, 9, 'Nikodemus entgegnete ihm mit der Frage: »Wie ist das möglich?«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 3, 10, 'Jesus gab ihm zur Antwort: »Du bist der Lehrer Israels und verstehst das nicht?');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 3, 11, 'Wahrlich, wahrlich ich sage dir: Wir reden, was wir wissen, und geben Zeugnis von dem, was wir gesehen haben, und doch nehmt ihr unser Zeugnis nicht an.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 3, 12, 'Wenn ich von den irdischen Dingen zu euch geredet habe und ihr nicht glaubt: wie werdet ihr da glauben, wenn ich von den himmlischen Dingen zu euch rede?');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 3, 13, 'Und niemand ist in den Himmel hinaufgestiegen außer dem einen, der aus dem Himmel herabgekommen ist, (nämlich) der Menschensohn, der im Himmel ist.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 3, 14, 'Und wie Mose die Schlange in der Wüste erhöht hat, so muß auch der Menschensohn erhöht werden,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 3, 15, 'damit alle, die (an ihn) glauben, in ihm ewiges Leben haben.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 3, 16, 'Denn so sehr hat Gott die Welt geliebt, daß er seinen eingeborenen Sohn hingegeben hat, damit alle, die an ihn glauben, nicht verloren gehen, sondern ewiges Leben haben.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 3, 17, 'Denn Gott hat seinen Sohn nicht dazu in die Welt gesandt, daß er die Welt richte, sondern daß die Welt durch ihn gerettet werde.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 3, 18, 'Wer an ihn glaubt, wird nicht gerichtet; wer nicht (an ihn) glaubt, ist schon gerichtet, weil er nicht an den Namen des eingeborenen Sohnes Gottes geglaubt hat.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 3, 19, 'Darin besteht aber das Gericht, daß das Licht in die Welt gekommen ist, die Menschen aber die Finsternis mehr geliebt haben als das Licht, denn ihre Werke waren böse.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 3, 20, 'Denn jeder, der Nichtiges treibt, haßt das Licht und kommt nicht zum Licht, damit seine Werke nicht bloßgestellt werden;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 3, 21, 'wer aber die Wahrheit tut, der kommt zum Licht, damit seine Werke offenbar werden, denn sie sind in Gott getan.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 3, 22, 'Hierauf begab sich Jesus mit seinen Jüngern in die Landschaft Judäa und blieb dort längere Zeit mit ihnen und taufte.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 3, 23, 'Aber auch Johannes war (damals noch) als Täufer zu Änon in der Nähe von Salim tätig, weil es dort reichlich Wasser gab; und die Leute kamen dorthin und ließen sich taufen;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 3, 24, 'Johannes war nämlich damals noch nicht ins Gefängnis geworfen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 3, 25, 'Da kam es denn zu einem Streite von seiten der Jünger des Johannes mit einem Juden über die Reinigung (durch die Taufe);');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 3, 26, 'und sie kamen zu Johannes und berichteten ihm: »Rabbi, der Mann, der jenseits des Jordans bei dir war und für den du mit deinem Zeugnis eingetreten bist, denke nur: der tauft (jetzt auch), und alle laufen ihm zu.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 3, 27, 'Da gab Johannes ihnen zur Antwort: »Kein Mensch kann sich etwas nehmen, wenn es ihm nicht vom Himmel her gegeben ist.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 3, 28, 'Ihr selbst könnt mir bezeugen, daß ich gesagt habe: ›Ich bin nicht Christus, sondern bin nur als sein Vorläufer gesandt.‹');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 3, 29, 'Wer die Braut hat, ist der Bräutigam; der Freund des Bräutigams aber, der dabeisteht und ihm zuhört, freut sich von Herzen über den Jubelruf des Bräutigams. Diese meine Freude ist nun vollkommen geworden.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 3, 30, 'Er muß wachsen, ich dagegen muß abnehmen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 3, 31, 'Er, der von oben her kommt, steht höher als alle anderen; wer von der Erde her stammt, der gehört zur Erde und redet von der Erde her. Er, der aus dem Himmel kommt, steht über allen anderen;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 3, 32, 'er legt Zeugnis von dem ab, was er (im Himmel) gesehen und gehört hat, und doch nimmt niemand sein Zeugnis an.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 3, 33, 'Wer sein Zeugnis angenommen hat, der hat damit besiegelt, daß Gott wahrhaftig ist.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 3, 34, 'Denn der, den Gott gesandt hat, redet die Worte Gottes; denn Gott verleiht den Geist nicht nach einem Maß.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 3, 35, 'Der Vater liebt den Sohn und hat alles in seine Hand gegeben.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 3, 36, 'Wer an den Sohn glaubt, hat ewiges Leben; wer aber dem Sohne ungehorsam bleibt, wird das Leben nicht zu sehen bekommen, sondern der Zorn Gottes bleibt auf ihn gerichtet.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 4, 1, 'Als nun der Herr erfuhr, den Pharisäern sei zu Ohren gekommen, daß Jesus mehr Jünger gewinne und taufe als Johannes –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 4, 2, 'übrigens taufte Jesus nicht selbst, sondern nur seine Jünger –,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 4, 3, 'verließ er Judäa und kehrte wieder nach Galiläa zurück;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 4, 4, 'dabei mußte er aber seinen Weg durch Samaria nehmen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 4, 5, 'So kam er denn ins Gebiet einer samaritischen Stadt namens Sychar, die nahe bei dem Felde liegt, das Jakob einst seinem Sohne Joseph geschenkt hatte.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 4, 6, 'Dort war aber der Jakobsbrunnen. Weil nun Jesus von der Wanderung ermüdet war, setzte er sich ohne weiteres am Brunnen nieder; es war ungefähr die sechste Stunde.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 4, 7, 'Da kam eine samaritische Frau, um Wasser zu schöpfen. Jesus bat sie: »Gib mir zu trinken!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 4, 8, 'Seine Jünger waren nämlich in die Stadt weggegangen, um Lebensmittel zu kaufen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 4, 9, 'Da sagte die Samariterin zu ihm: »Wie kommst du dazu, da du doch ein Jude bist, von mir, einer Samariterin, einen Trunk zu erbitten?« – Die Juden haben nämlich mit den Samaritern keinen Verkehr. –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 4, 10, 'Jesus gab ihr zur Antwort: »Wenn du die Gabe Gottes kenntest und wüßtest, wer der ist, der einen Trunk von dir wünscht, so würdest du ihn bitten, und er würde dir lebendiges Wasser geben.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 4, 11, 'Da erwiderte ihm die Frau: »Herr, du hast ja kein Gefäß zum Schöpfen, und der Brunnen ist tief: woher willst du denn das lebendige Wasser nehmen?');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 4, 12, 'Du bist doch nicht mehr als unser Vater Jakob, der uns den Brunnen gegeben hat? Und er selbst hat aus ihm getrunken samt seinen Söhnen und seinen Herden.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 4, 13, 'Jesus antwortete ihr: »Jeder, der von diesem Wasser trinkt, wird wieder dürsten;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 4, 14, 'wer aber von dem Wasser trinkt, das ich ihm geben werde, der wird in Ewigkeit nicht wieder Durst leiden, sondern das Wasser, das ich ihm geben werde, wird in ihm zu einer Wasserquelle werden, die zu ewigem Leben sprudelt.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 4, 15, 'Die Frau antwortete ihm: »Herr, gib mir dieses Wasser, damit ich nicht wieder durstig werde und nicht mehr hierher zu kommen brauche, um Wasser zu holen!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 4, 16, 'Da sagte Jesus zu ihr: »Geh hin, rufe deinen Mann und komm dann wieder hierher!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 4, 17, 'Die Frau antwortete: »Ich habe keinen Mann.« Jesus erwiderte ihr: »Du hast mit Recht gesagt: ›Ich habe keinen Mann‹;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 4, 18, 'denn fünf Männer hast du gehabt, und der, den du jetzt hast, ist nicht dein Ehemann; damit hast du die Wahrheit gesagt.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 4, 19, 'Die Frau entgegnete ihm: »Herr, ich sehe: du bist ein Prophet.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 4, 20, 'Unsere Väter haben auf dem Berge dort (Gott) angebetet, und ihr behauptet, in Jerusalem sei die Stätte, wo man anbeten müsse.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 4, 21, 'Jesus erwiderte ihr: »Glaube mir, Frau: die Stunde kommt, in der ihr weder auf dem Berge dort noch in Jerusalem den Vater anbeten werdet.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 4, 22, 'Ihr betet an, was ihr nicht kennt; wir beten an, was wir kennen; denn die Rettung ist aus den Juden.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 4, 23, 'Es kommt aber die Stunde, ja, sie ist jetzt schon da, in der die wahren Anbeter den Vater im Geist und in Wahrheit anbeten werden; denn auch der Vater will solche als seine Anbeter haben.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 4, 24, 'Gott ist Geist, und die ihn anbeten, müssen ihn im Geist und in Wahrheit anbeten.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 4, 25, 'Da sagte die Frau zu ihm: »Ich weiß, daß der Messias kommt, den man Christus nennt; wenn der kommt, wird er uns über alles Auskunft geben.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 4, 26, 'Jesus antwortete ihr: »Ich bin’s, der mit dir redet.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 4, 27, 'In diesem Augenblick kamen seine Jünger und wunderten sich darüber, daß er mit einer Frau redete; doch fragte ihn keiner: »Was willst du (von ihr)?« oder: »Wozu redest du mit ihr?«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 4, 28, 'Da ließ nun die Frau ihren Wasserkrug stehen, ging in die Stadt zurück und sagte zu den Leuten dort:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 4, 29, '»Kommt und seht einen Mann, der mir alles gesagt hat, was ich getan habe! Sollte dieser vielleicht Christus sein?«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 4, 30, 'Da gingen sie aus der Stadt hinaus und begaben sich zu ihm.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 4, 31, 'Inzwischen baten ihn seine Jünger: »Rabbi, iß!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 4, 32, 'Er antwortete ihnen aber: »Ich habe eine Speise zu essen, von der ihr nichts wißt.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 4, 33, 'Da sagten die Jünger zueinander: »Hat ihm denn jemand zu essen gebracht?«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 4, 34, 'Jesus erwiderte ihnen: »Meine Speise ist die, daß ich den Willen dessen tue, der mich gesandt hat, und sein Werk vollende.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 4, 35, 'Sagt ihr nicht selbst: ›Es währt noch vier Monate, bis die Ernte kommt‹? Nun sage ich euch: Laßt eure Augen ausschauen und seht die Felder an: sie sind (schon jetzt) weiß zur Ernte.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 4, 36, 'Nunmehr empfängt der Schnitter Lohn, und zwar dadurch, daß er Frucht sammelt zu ewigem Leben, damit beide sich gemeinsam freuen, der Sämann und der Schnitter.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 4, 37, 'Denn in diesem Falle trifft das Sprichwort zu: ›Ein anderer ist’s, der da sät, und ein anderer, der da erntet.‹');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 4, 38, 'Ich habe euch ausgesandt, um das zu ernten, wofür ihr nicht gearbeitet habt: andere haben die Arbeit geleistet, und ihr seid in ihre Arbeit eingetreten.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 4, 39, 'Aus jener Stadt aber wurden viele von den Samaritern an ihn gläubig infolge der Versicherung der Frau: »Er hat mir alles gesagt, was ich getan habe.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 4, 40, 'Als nun die Samariter zu ihm gekommen waren, baten sie ihn, er möchte bei ihnen bleiben; und er blieb auch zwei Tage dort.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 4, 41, 'Da wurden noch viel mehr Leute infolge seiner Predigt gläubig');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 4, 42, 'und sagten zu der Frau: »Wir glauben jetzt nicht mehr infolge deiner Aussage; denn wir haben nunmehr selbst gehört und wissen, daß dieser wirklich der Retter der Welt ist.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 4, 43, 'Nach Verlauf der beiden Tage aber zog Jesus von dort weiter nach Galiläa,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 4, 44, 'wiewohl er selbst ausdrücklich erklärt hatte, daß ein Prophet in seiner eigenen Heimat keine Anerkennung finde.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 4, 45, 'Doch als er nach Galiläa kam, nahmen ihn die Galiläer gastlich auf, weil sie alles gesehen hatten, was er in Jerusalem während des Festes getan hatte; denn sie waren gleichfalls auf dem Fest gewesen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 4, 46, 'So kam er denn wieder nach Kana in Galiläa, wo er das Wasser in Wein verwandelt hatte. Es war aber in Kapernaum ein königlicher Beamter, dessen Sohn krank darniederlag.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 4, 47, 'Als dieser hörte, daß Jesus aus Judäa nach Galiläa gekommen sei, begab er sich zu ihm und bat ihn, er möchte (nach Kapernaum) hinunterkommen und seinen Sohn heilen; denn dieser lag im Sterben.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 4, 48, 'Da sagte Jesus zu ihm: »Wenn ihr nicht Zeichen und Wunder seht, glaubt ihr überhaupt nicht!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 4, 49, 'Der königliche Beamte entgegnete ihm: »Herr, komm doch hinab, ehe mein Kind stirbt!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 4, 50, 'Jesus antwortete ihm: »Gehe heim, dein Sohn lebt!« Der Mann glaubte der Versicherung, die Jesus ihm gegeben hatte, und machte sich auf den Heimweg,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 4, 51, 'und schon während seiner Rückkehr kamen ihm seine Knechte mit der Meldung entgegen, daß sein Sohn lebe.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 4, 52, 'Da erkundigte er sich bei ihnen nach der Stunde, in der sein Befinden sich gebessert habe. Sie antworteten ihm: »Gestern in der siebten Stunde hat das Fieber ihn verlassen.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 4, 53, 'Nun erkannte der Vater, daß es in jener Stunde geschehen war, in der Jesus zu ihm gesagt hatte: »Dein Sohn lebt«; und er wurde gläubig mit seinem ganzen Hause.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 4, 54, 'Dies ist das zweite Wunderzeichen, das Jesus wiederum (in Kana) nach seiner Rückkehr aus Judäa nach Galiläa getan hat.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 5, 1, 'Hierauf fand ein Fest der Juden statt, und Jesus zog nach Jerusalem hinauf.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 5, 2, 'Nun liegt in Jerusalem am Schaftor ein Teich, der auf hebräisch Bethesda heißt und fünf Hallen hat.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 5, 3, 'In diesen lagen Kranke in großer Zahl, Blinde, Lahme und Schwindsüchtige [die auf die Bewegung des Wassers warteten.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 5, 4, 'Ein Engel des Herrn stieg nämlich von Zeit zu Zeit in den Teich hinab und setzte das Wasser in Bewegung. Wer dann nach der Bewegung des Wassers zuerst hineinstieg, der wurde gesund, gleichviel mit welchem Leiden er behaftet war].');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 5, 5, 'Nun lag dort ein Mann, der schon achtunddreißig Jahre an seiner Krankheit gelitten hatte.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 5, 6, 'Als Jesus diesen daliegen sah und erfuhr, daß er schon so lange Zeit als Kranker dort zugebracht hatte, fragte er ihn: »Willst du gesund werden?«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 5, 7, 'Der Kranke antwortete ihm: »Ach, Herr, ich habe keinen Menschen, der mich in den Teich schafft, wenn das Wasser in Bewegung gerät; während ich aber hingehe, steigt immer schon ein anderer vor mir hinab.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 5, 8, 'Jesus sagte zu ihm: »Steh auf, nimm dein Bett auf dich und bewege dich frei!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 5, 9, 'Da wurde der Mann sogleich gesund, nahm sein Bett auf sich und ging umher. Es war aber (gerade) Sabbat an jenem Tage.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 5, 10, 'Daher sagten die Juden zu dem Geheilten: »Heute ist Sabbat; da darfst du das Bett nicht tragen!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 5, 11, 'Doch er antwortete ihnen: »Der Mann, der mich gesund gemacht hat, der hat zu mir gesagt: ›Nimm dein Bett auf dich und bewege dich frei!‹«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 5, 12, 'Sie fragten ihn: »Wer ist der Mann, der zu dir gesagt hat: ›Nimm es auf dich und gehe umher!‹?«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 5, 13, 'Der Geheilte wußte aber nicht, wer es war; denn Jesus hatte sich in der Menschenmenge, die sich an dem Orte befand, unbemerkt entfernt.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 5, 14, 'Später traf Jesus ihn im Tempel wieder und sagte zu ihm: »Du bist nun gesund geworden; sündige fortan nicht mehr, damit dir nicht noch Schlimmeres widerfährt!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 5, 15, 'Da ging der Mann hin und teilte den Juden mit, Jesus sei es, der ihn gesund gemacht habe.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 5, 16, 'Deshalb verfolgten die Juden Jesus, weil er solche Werke (auch) am Sabbat tat.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 5, 17, 'Jesus aber antwortete ihnen: »Mein Vater wirkt (ununterbrochen) bis zu dieser Stunde; darum wirke ich auch.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 5, 18, 'Deshalb trachteten die Juden ihm um so mehr nach dem Leben, weil er nicht nur den Sabbat brach, sondern auch Gott seinen eigenen Vater nannte und sich damit Gott gleichstellte.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 5, 19, 'Daher sprach sich Jesus ihnen gegenüber so aus: »Wahrlich, wahrlich ich sage euch: der Sohn vermag von sich selber aus nichts zu tun, als was er den Vater tun sieht; denn was jener tut, das tut in gleicher Weise auch der Sohn.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 5, 20, 'Denn der Vater hat den Sohn lieb und läßt ihn alles sehen, was er selbst tut; und er wird ihn noch größere Werke als diese sehen lassen, damit ihr euch wundert.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 5, 21, 'Denn wie der Vater die Toten auferweckt und lebendig macht, ebenso macht auch der Sohn lebendig, welche er will.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 5, 22, 'Denn auch der Vater ist es nicht, der jemand richtet; sondern er hat das Gericht ganz dem Sohne übertragen,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 5, 23, 'damit alle den Sohn ebenso ehren, wie sie den Vater ehren. Wer den Sohn nicht ehrt, ehrt auch den Vater nicht, der ihn gesandt hat.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 5, 24, 'Wahrlich, wahrlich ich sage euch: Wer mein Wort hört und dem glaubt, der mich gesandt hat, der hat ewiges Leben und kommt nicht ins Gericht, sondern ist aus dem Tode ins Leben hinübergegangen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 5, 25, 'Wahrlich, wahrlich ich sage euch: Es kommt die Stunde, ja sie ist jetzt schon da, wo die Toten die Stimme des Sohnes Gottes hören werden, und die, welche auf sie hören, werden leben.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 5, 26, 'Denn wie der Vater (das) Leben in sich selbst hat, so hat er auch dem Sohne verliehen, (das) Leben in sich selbst zu haben;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 5, 27, 'und er hat ihm Vollmacht gegeben, Gericht abzuhalten, weil er ein Menschensohn ist.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 5, 28, 'Wundert euch nicht hierüber! Denn die Stunde kommt, in der alle, die in den Gräbern ruhen, seine Stimme hören werden,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 5, 29, 'und es werden hervorgehen: die einen, die das Gute getan haben, zur Auferstehung für das Leben, die anderen aber, die das Böse betrieben haben, zur Auferstehung für das Gericht.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 5, 30, 'Ich vermag nichts von mir selbst aus zu tun; nein, wie ich es (vom Vater) höre, so richte ich, und mein Gericht ist gerecht, weil ich nicht meinen Willen (durchzuführen) suche, sondern den Willen dessen, der mich gesandt hat.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 5, 31, '»Wenn ich über mich selbst Zeugnis ablege, so ist mein Zeugnis ungültig.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 5, 32, '(Nein) ein anderer ist es, der mit seinem Zeugnis für mich eintritt, und ich weiß, daß das Zeugnis, das er über mich ablegt, wahr ist.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 5, 33, 'Ihr habt zu Johannes gesandt, und er hat Zeugnis für die Wahrheit abgelegt;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 5, 34, 'ich aber nehme das Zeugnis von einem Menschen nicht an, sondern erwähne dies nur deshalb, damit ihr gerettet werdet.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 5, 35, 'Jener war wirklich die Leuchte, die mit hellem Schein brannte; ihr aber wolltet euch nur eine Zeitlang an ihrem Lichtschein vergnügen.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 5, 36, '»Ich aber habe ein Zeugnis, das gewichtiger ist als das des Johannes; denn die Werke, die der Vater mir zu vollführen übertragen hat, eben die Werke, die ich vollbringe, bezeugen von mir, daß der Vater mich gesandt hat.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 5, 37, 'So ist also, der mich gesandt hat, der Vater selbst, mit seinem Zeugnis für mich eingetreten. Ihr habt weder seine Stimme jemals gehört noch seine Gestalt gesehen;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 5, 38, 'und auch sein Wort habt ihr nicht als bleibenden Besitz in euch, weil ihr dem nicht glaubt, den er gesandt hat.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 5, 39, 'Ihr durchforscht (wohl) die (heiligen) Schriften, weil ihr in ihnen ewiges Leben zu haben vermeint, und sie sind es auch wirklich, die von mir Zeugnis ablegen;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 5, 40, 'aber trotzdem wollt ihr nicht zu mir kommen, um wirklich Leben zu haben.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 5, 41, '»Ehre von Menschen nehme ich nicht an,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 5, 42, 'vielmehr habe ich bei euch erkannt, daß ihr die Liebe zu Gott nicht in euch tragt.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 5, 43, 'Ich bin im Namen meines Vaters gekommen, doch ihr nehmt mich nicht an; wenn ein anderer in seinem eigenen Namen kommt, den werdet ihr annehmen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 5, 44, 'Wie könnt ihr zum Glauben kommen, da ihr Ehre voneinander annehmt, aber nach der Ehrung, die vom alleinigen Gott kommt, kein Verlangen tragt?');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 5, 45, 'Denkt nicht, daß ich euer Ankläger beim Vater sein werde! Nein, es ist (ein anderer) da, der euch anklagt, nämlich Mose, auf den ihr eure Hoffnung gesetzt habt.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 5, 46, 'Denn wenn ihr Mose glaubtet, dann würdet ihr auch mir glauben; denn ich bin es, von dem er geschrieben hat.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 5, 47, 'Wenn ihr aber seinen Schriften nicht glaubt, wie solltet ihr da meinen Worten Glauben schenken?«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 6, 1, 'Hierauf begab sich Jesus auf die andere Seite des Galiläischen Sees, des Sees von Tiberias;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 6, 2, 'es zog ihm aber dorthin eine große Volksmenge nach, weil sie die Wunderzeichen sahen, die er an den Kranken tat.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 6, 3, 'Jesus stieg aber auf den Berg hinauf und ließ sich dort mit seinen Jüngern nieder;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 6, 4, 'das jüdische Passah stand aber nahe bevor.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 6, 5, 'Als nun Jesus sich dort umschaute und eine große Volksmenge zu sich kommen sah, sagte er zu Philippus: »Woher sollen wir Brote kaufen, damit diese zu essen haben?«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 6, 6, 'So fragte er aber, um ihn auf die Probe zu stellen; denn er selbst wußte wohl, was er tun wollte.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 6, 7, 'Philippus antwortete ihm: »Für zweihundert Denare Brot reicht für sie nicht hin, damit jeder auch nur ein kleines Stück erhält.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 6, 8, 'Da sagte einer von seinen Jüngern, nämlich Andreas, der Bruder des Simon Petrus, zu ihm:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 6, 9, '»Es ist ein Knabe hier, der fünf Gerstenbrote und zwei Fische (zum Verkauf bei sich) hat, doch was ist das für so viele?«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 6, 10, 'Jesus aber sagte: »Laßt die Leute sich lagern!«, es war nämlich dichter Rasen an dem Ort. So lagerten sich denn die Männer, etwa fünftausend an Zahl.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 6, 11, 'Jesus nahm sodann die Brote, sprach den Lobpreis (Gottes) und ließ sie unter die Leute austeilen, die sich gelagert hatten; ebenso auch von den Fischen, soviel sie begehrten.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 6, 12, 'Als sie dann satt geworden waren, sagte er zu seinen Jüngern: »Sammelt die übriggebliebenen Brocken, damit nichts umkommt.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 6, 13, 'Da sammelten sie und füllten von den fünf Gerstenbroten zwölf Körbe mit Brocken, die beim Essen übriggeblieben waren.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 6, 14, 'Als nun die Leute das Wunderzeichen sahen, das er getan hatte, erklärten sie: »Dieser ist wahrhaftig der Prophet, der in die Welt kommen soll!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 6, 15, 'Da nun Jesus erkannte, daß sie kommen und sich seiner Person mit Gewalt bemächtigen würden, um ihn zum König zu machen, zog er sich wieder auf den Berg zurück, er für sich allein.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 6, 16, 'Als es dann Abend geworden war, gingen seine Jünger an den See hinab,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 6, 17, 'stiegen in ein Boot und wollten über den See nach Kapernaum hinüberfahren. Die Dunkelheit war bereits eingetreten und Jesus immer noch nicht zu ihnen gekommen;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 6, 18, 'dabei ging der See hoch, weil ein starker Wind wehte.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 6, 19, 'Als sie nun etwa fünfundzwanzig bis dreißig Stadien weit gefahren waren, sahen sie Jesus über den See hingehen und sich ihrem Boote nähern; da gerieten sie in Angst.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 6, 20, 'Er aber rief ihnen zu:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 6, 21, '»Ich bin’s; fürchtet euch nicht!« Sie wollten ihn nun in das Boot hineinnehmen, doch sogleich befand sich das Boot am Lande, (und zwar da) wohin sie fahren wollten.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 6, 22, 'Am folgenden Tage überzeugte sich die Volksmenge, die am jenseitigen Ufer des Sees stand, daß dort weiter kein Fahrzeug außer dem einen gewesen war und daß Jesus nicht mit seinen Jüngern zusammen das Boot bestiegen hatte, sondern daß seine Jünger allein abgefahren waren.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 6, 23, 'Doch es kamen jetzt andere Fahrzeuge von Tiberias her in die Nähe des Platzes, wo sie das Brot nach dem Dankgebet des Herrn gegessen hatten.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 6, 24, 'Als die Volksmenge nun sah, daß Jesus ebensowenig da war wie seine Jünger, stiegen auch sie in die Fahrzeuge und kamen nach Kapernaum, um Jesus zu suchen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 6, 25, 'Als sie ihn dann auf der anderen Seite des Sees angetroffen hatten, fragten sie ihn: »Rabbi, wann bist du hierher gekommen?«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 6, 26, 'Jesus antwortete ihnen: »Wahrlich, wahrlich ich sage euch: Ihr sucht mich nicht deshalb, weil ihr Wunderzeichen gesehen, sondern weil ihr von den Broten gegessen habt und satt geworden seid.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 6, 27, 'Verschafft euch doch nicht die Speise, die vergänglich ist, sondern die Speise, die für das ewige Leben vorhält und die der Menschensohn euch geben wird; denn diesen hat Gott der Vater besiegelt.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 6, 28, 'Da entgegneten sie ihm: »Was sollen wir denn tun, um die Werke Gottes zu wirken?«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 6, 29, 'Jesus antwortete ihnen mit den Worten: »Das Werk Gottes besteht darin, daß ihr an den glaubt, den er gesandt hat.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 6, 30, 'Da fragten sie ihn: »Welches Zeichen tust du nun, damit wir es sehen und zum Glauben an dich kommen? Womit kannst du dich ausweisen?');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 6, 31, 'Unsere Väter haben das Manna in der Wüste zu essen bekommen, wie geschrieben steht: ›Brot aus dem Himmel gab er ihnen zu essen.‹«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 6, 32, 'Da sagte Jesus zu ihnen: »Wahrlich, wahrlich ich sage euch: Nicht Mose hat euch das Himmelsbrot gegeben, sondern mein Vater gibt euch das wahre Himmelsbrot;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 6, 33, 'denn das Brot Gottes ist das, welches aus dem Himmel herabkommt und der Welt Leben gibt.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 6, 34, 'Da riefen sie ihm zu: »Herr, gib uns dieses Brot allezeit!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 6, 35, 'Da sagte Jesus zu ihnen: »Ich bin das Brot des Lebens! Wer zu mir kommt, den wird nimmermehr hungern, und wer an mich glaubt, den wird niemals wieder dürsten.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 6, 36, 'Aber ich habe euch (schon) gesagt: Ihr habt mich wohl gesehen, glaubt aber doch nicht.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 6, 37, 'Alles, was der Vater mir gibt, wird zu mir kommen, und wer zu mir kommt, den werde ich nimmer hinausstoßen;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 6, 38, 'denn ich bin aus dem Himmel herabgekommen, nicht um meinen Willen auszuführen, sondern den Willen dessen, der mich gesandt hat.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 6, 39, 'Das aber ist der Wille dessen, der mich gesandt hat, daß ich von allem dem, was er mir gegeben hat, nichts verloren gehen lasse, sondern es am jüngsten Tage auferwecke.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 6, 40, 'Denn das ist der Wille meines Vaters, daß jeder, der den Sohn sieht und an ihn glaubt, ewiges Leben habe, und ich werde ihn am jüngsten Tage auferwecken.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 6, 41, 'Da murrten die Juden über ihn, weil er gesagt hatte: »Ich bin das Brot, das aus dem Himmel herabgekommen ist«,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 6, 42, 'und sie sagten: »Ist dieser nicht Jesus, Josephs Sohn, dessen Vater und Mutter wir kennen? Wie kann er da jetzt behaupten: ›Ich bin aus dem Himmel herabgekommen?‹«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 6, 43, 'Jesus antwortete ihnen mit den Worten: »Murret nicht untereinander!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 6, 44, 'Niemand kann zu mir kommen, wenn nicht der Vater, der mich gesandt hat, ihn zieht, und ich werde ihn dann am jüngsten Tage auferwecken.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 6, 45, 'Es steht ja bei den Propheten geschrieben: ›Sie werden alle von Gott gelehrt sein.‹ Jeder, der (es) vom Vater gehört und gelernt hat, kommt zu mir.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 6, 46, 'Nicht als ob jemand den Vater gesehen hätte; denn nur der eine, der von Gott her (gekommen) ist, nur der hat den Vater gesehen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 6, 47, 'Wahrlich, wahrlich ich sage euch: Wer da glaubt, hat ewiges Leben!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 6, 48, 'Ich bin das Brot des Lebens.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 6, 49, 'Eure Väter haben in der Wüste das Manna gegessen und sind dann doch gestorben;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 6, 50, 'hier dagegen ist das Brot, das aus dem Himmel herabkommt, damit man davon esse und nicht sterbe.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 6, 51, 'Ich bin das lebendige Brot, das aus dem Himmel herabgekommen ist: wenn jemand von diesem Brote ißt, so wird er ewiglich leben; und zwar ist das Brot, das ich (zu essen) geben werde, mein Fleisch, (das ich geben werde) für das Leben der Welt.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 6, 52, 'Nun gerieten die Juden in Streit untereinander und sagten: »Wie kann dieser uns sein Fleisch zu essen geben?«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 6, 53, 'Da sagte Jesus zu ihnen: »Wahrlich, wahrlich ich sage euch: Wenn ihr nicht das Fleisch des Menschensohnes eßt und sein Blut trinkt, so habt ihr kein Leben in euch;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 6, 54, 'wer (dagegen) mein Fleisch ißt und mein Blut trinkt, der hat ewiges Leben, und ich werde ihn am jüngsten Tage auferwecken.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 6, 55, 'Denn mein Fleisch ist wahre Speise, und mein Blut ist wahrer Trank.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 6, 56, 'Wer mein Fleisch ißt und mein Blut trinkt, bleibt in mir und ich in ihm.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 6, 57, 'Wie mich mein Vater, der das Leben in sich trägt, gesandt hat und ich Leben in mir trage um des Vaters willen, so wird auch der, welcher mich ißt, das Leben haben um meinetwillen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 6, 58, 'Von solcher Beschaffenheit ist das Brot, das aus dem Himmel herabgekommen ist; es ist nicht von der Art, wie die Väter es gegessen haben und gestorben sind; nein, wer dieses Brot ißt, wird leben in Ewigkeit.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 6, 59, 'So sprach Jesus, als er in der Synagoge zu Kapernaum lehrte.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 6, 60, 'Viele nun von seinen Jüngern, die ihm zugehört hatten, erklärten: »Das ist eine harte Rede: wer kann sie anhören?«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 6, 61, 'Weil aber Jesus bei sich wußte, daß seine Jünger darüber murrten, sagte er zu ihnen: »Das ist euch anstößig?');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 6, 62, 'Wie nun (wird es sein), wenn ihr den Menschensohn dahin auffahren seht, wo er vordem war?');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 6, 63, 'Der Geist ist es, der das Leben schafft, das Fleisch hilft nichts; die Worte, die ich zu euch geredet habe, sind Geist und sind Leben;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 6, 64, 'aber es sind unter euch auch solche, die nicht glauben.« Jesus wußte nämlich von Anfang an, wer die waren, welche ungläubig blieben, und wer der war, der ihn verraten würde.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 6, 65, 'Er fuhr dann fort: »Aus diesem Grunde habe ich euch gesagt: ›Niemand kann zu mir kommen, wenn es ihm nicht vom Vater verliehen ist.‹«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 6, 66, 'Von da an zogen sich viele seiner Jünger von ihm zurück und begleiteten ihn nicht mehr auf seinen Wanderungen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 6, 67, 'Daher sagte Jesus zu den Zwölfen: »Ihr wollt doch nicht auch weggehen?«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 6, 68, 'Simon Petrus antwortete ihm: »Herr, zu wem sollten wir gehen? Du hast Worte ewigen Lebens;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 6, 69, 'und wir haben den Glauben und die Erkenntnis gewonnen, daß du der Heilige Gottes bist.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 6, 70, 'Jesus antwortete ihnen: »Habe nicht ich selbst euch Zwölf erwählt? Und einer von euch ist ein Teufel.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 6, 71, 'Er meinte damit aber den Judas, den Sohn Simons aus Kariot; denn dieser sollte ihn verraten, (und war doch) einer von den Zwölfen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 7, 1, 'Hierauf zog Jesus in Galiläa umher; denn in Judäa wollte er nicht umherziehen, weil die Juden ihm nach dem Leben trachteten;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 7, 2, 'es stand aber das jüdische Laubhüttenfest nahe bevor.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 7, 3, 'Darum sagten seine Brüder zu ihm: »Mache dich von hier auf den Weg und begib dich nach Judäa, damit deine Jünger auch dort die Werke sehen, die du tust;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 7, 4, 'denn niemand wirkt doch in der Verborgenheit, wenn er sich in der Öffentlichkeit geltend machen will. Willst du überhaupt solche Tätigkeit ausüben, so zeige dich der Welt öffentlich« –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 7, 5, 'nicht einmal seine Brüder nämlich glaubten an ihn.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 7, 6, 'Da antwortete Jesus ihnen: »Meine Zeit ist noch nicht da; für euch freilich ist die Zeit immer gelegen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 7, 7, 'Euch kann die Welt nicht hassen, mich aber haßt sie, weil ich von ihr bezeuge, daß ihr ganzes Tun böse ist.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 7, 8, 'Geht ihr nur zum Fest hinauf, ich gehe zu diesem Fest nicht hinauf, weil meine Zeit noch nicht erfüllt ist.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 7, 9, 'So sprach er zu ihnen und blieb in Galiläa.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 7, 10, 'Als dann aber seine Brüder zum Fest hinaufgegangen waren, da ging auch er hinauf, jedoch nicht öffentlich, sondern ganz in der Stille.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 7, 11, 'Die Juden suchten nun während des Festes nach ihm und fragten: »Wo ist er?«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 7, 12, 'Und unter den Volksscharen war viel Gerede über ihn; die einen sagten: »Er ist ein guter Mann«; andere dagegen behaupteten: »Nein, er ist ein Volksverführer«;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 7, 13, 'doch niemand redete mit voller Offenheit über ihn aus Furcht vor den Juden.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 7, 14, 'Als aber die Festwoche schon zur Hälfte vorüber war, ging Jesus zum Tempel hinauf und lehrte.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 7, 15, 'Da wunderten sich die Juden und sagten: »Wie kommt dieser zur Schriftgelehrsamkeit, obwohl er doch keinen Unterricht in ihr erhalten hat?«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 7, 16, 'Da antwortete ihnen Jesus mit den Worten: »Meine Lehre stammt nicht von mir, sondern von dem, der mich gesandt hat;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 7, 17, 'wenn jemand dessen Willen tun will, wird er inne werden, ob diese Lehre von Gott stammt oder ob ich von mir selbst aus rede.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 7, 18, 'Wer von sich selbst aus redet, sucht seine eigene Ehre; wer aber die Ehre dessen sucht, der ihn gesandt hat, der ist wahrhaftig, und bei dem findet sich keine Ungerechtigkeit.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 7, 19, 'Hat nicht Mose euch das Gesetz gegeben? Und doch erfüllt niemand von euch das Gesetz! Warum sucht ihr mich zu töten?«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 7, 20, 'Die Volksmenge antwortete: »Du bist von Sinnen! Wer sucht dich denn zu töten?«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 7, 21, 'Jesus antwortete ihnen: »Ein einziges Werk habe ich (hier in Jerusalem) getan, und ihr seid allesamt verwundert darüber.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 7, 22, 'Mose hat euch die Beschneidung gegeben – von Mose stammt sie freilich nicht, sondern von den Erzvätern –, und so beschneidet ihr denn einen Menschen (auch) am Sabbat.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 7, 23, 'Wenn (nun) ein Mensch am Sabbat die Beschneidung empfängt, damit das mosaische Gesetz nicht gebrochen wird: da wollt ihr mir zürnen, weil ich einen ganzen Menschen am Sabbat gesund gemacht habe?');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 7, 24, 'Urteilt nicht nach dem äußeren Schein, sondern gebt ein gerechtes Urteil ab!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 7, 25, 'Da sagten einige von den Bewohnern Jerusalems: »Ist dieser Mensch es nicht, den sie zu töten suchen?');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 7, 26, 'Und seht nur: er redet ganz öffentlich, und man sagt ihm kein Wort! Die Oberen werden doch nicht etwa zu der Erkenntnis gekommen sein, daß dieser der Messias ist?');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 7, 27, 'Freilich von diesem wissen wir, woher er stammt; wenn aber der Messias kommt, weiß niemand, woher er stammt.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 7, 28, 'Da rief Jesus im Tempel, wo er lehrte, laut aus: »Ja, ihr kennt mich und wißt, woher ich stamme! Und doch bin ich nicht von mir selbst aus gekommen, sondern es ist der rechte Sender, der mich gesandt hat, den ihr aber nicht kennt.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 7, 29, 'Ich kenne ihn, weil ich von ihm her (ausgegangen) bin, und er hat mich gesandt.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 7, 30, 'Da suchten sie ihn festzunehmen, doch niemand legte Hand an ihn, weil seine Stunde noch nicht gekommen war.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 7, 31, 'Aus dem Volke kamen aber viele zum Glauben an ihn und sagten: »Wird wohl Christus, wenn er kommt, mehr Wunderzeichen tun, als dieser getan hat?«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 7, 32, 'Die Pharisäer erfuhren, daß das Volk solche Ansichten im geheimen über ihn äußerte; daher schickten die Hohenpriester und die Pharisäer Diener ab, die ihn festnehmen sollten.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 7, 33, 'Da sagte Jesus: »Nur noch kurze Zeit bin ich bei euch, dann gehe ich hin zu dem, der mich gesandt hat.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 7, 34, 'Ihr werdet mich (dann) suchen, aber nicht finden, und wo ich (dann) bin, dahin könnt ihr nicht kommen.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 7, 35, 'Da sagten die Juden zueinander: »Wohin will dieser gehen, daß wir ihn nicht finden können? Will er etwa zu den Juden gehen, die unter den Griechen zerstreut leben, und der Lehrer der Griechen werden?');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 7, 36, 'Welchen Sinn hat dieses Wort, das er ausgesprochen hat: ›Ihr werdet mich suchen, aber nicht finden‹ und ›Wo ich (dann) bin, dahin könnt ihr nicht kommen‹?«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 7, 37, 'Am letzten, dem großen Tage des Festes aber stand Jesus da und rief laut aus: »Wen da dürstet, der komme zu mir und trinke!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 7, 38, 'Wer an mich glaubt, aus dessen Leibe werden, wie die Schrift gesagt hat, Ströme lebendigen Wassers fließen.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 7, 39, 'Damit meinte er aber den Geist, den die, welche zum Glauben an ihn gekommen waren, empfangen sollten; denn der (heilige) Geist war noch nicht da, weil Jesus noch nicht zur Herrlichkeit erhoben worden war.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 7, 40, 'Nun sagten manche aus dem Volk, die diese Worte gehört hatten: »Dieser ist wirklich der Prophet!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 7, 41, 'Andere sagten: »Er ist Christus«; wieder andere meinten: »Christus kommt doch nicht aus Galiläa!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 7, 42, 'Hat nicht die Schrift gesagt, daß Christus aus dem Samen Davids und aus der Ortschaft Bethlehem, wo David gewohnt hat, kommen soll?«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 7, 43, 'So entstand seinetwegen eine Spaltung unter dem Volk.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 7, 44, 'Einige von ihnen hätten ihn nun gern festgenommen, aber keiner legte Hand an ihn.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 7, 45, 'So kamen denn die Diener zu den Hohenpriestern und Pharisäern zurück, und diese fragten sie: »Warum habt ihr ihn nicht hergebracht?«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 7, 46, 'Die Diener antworteten: »Noch niemals hat ein Mensch so geredet, wie dieser Mann redet!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 7, 47, 'Da erwiderten ihnen die Pharisäer: »Habt auch ihr euch irreführen lassen?');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 7, 48, 'Ist etwa irgendein Oberer oder ein Pharisäer zum Glauben an ihn gekommen?');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 7, 49, 'Nein, nur dieses gemeine Volk, das vom Gesetz nichts weiß – verflucht sind sie!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 7, 50, 'Da sagte Nikodemus, der früher einmal zu Jesus gekommen war und ihrer Partei angehörte:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 7, 51, '»Verurteilt etwa unser Gesetz einen Menschen, ohne daß man ihn zuvor verhört und seine Schuld festgestellt hat?«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 7, 52, 'Da gaben sie ihm zur Antwort: »Stammst du vielleicht auch aus Galiläa? Forsche doch nach und lerne begreifen, daß aus Galiläa kein Prophet hervorgeht!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 7, 53, 'Dann gingen sie weg, ein jeder in sein Haus;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 8, 1, 'Jesus aber begab sich an den Ölberg.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 8, 2, 'Am folgenden Morgen jedoch fand er sich wieder im Tempel ein, und das gesamte Volk kam zu ihm; er setzte sich dann und lehrte sie.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 8, 3, 'Da führten die Schriftgelehrten und Pharisäer eine Frau herbei, die beim Ehebruch ergriffen worden war, stellten sie in die Mitte');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 8, 4, 'und sagten zu ihm: »Meister, diese Frau ist auf frischer Tat beim Ehebruch ergriffen worden.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 8, 5, 'Nun hat Mose uns im Gesetz geboten, solche Frauen zu steinigen. Was sagst nun du dazu?«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 8, 6, 'Dies sagten sie aber, um ihn zu versuchen, damit sie einen Grund zur Anklage gegen ihn hätten. Jesus aber bückte sich nieder und schrieb mit dem Finger auf den Erdboden.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 8, 7, 'Als sie aber ihre Frage an ihn mehrfach wiederholten, richtete er sich auf und sagte zu ihnen: »Wer unter euch ohne Sünde ist, werfe den ersten Stein auf sie!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 8, 8, 'Hierauf bückte er sich aufs neue und schrieb auf dem Erdboden weiter.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 8, 9, 'Als aber jene das gehört hatten, gingen sie einer nach dem andern weg, die Ältesten zuerst bis zu den Letzten, und Jesus blieb allein zurück mit der Frau, die in der Mitte stand.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 8, 10, 'Da richtete Jesus sich auf und fragte sie: »Frau, wo sind sie? Hat keiner dich verurteilt?« Sie antwortete: »Keiner, Herr.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 8, 11, 'Da sagte Jesus: »Auch ich verurteile dich nicht: gehe hin und sündige hinfort nicht mehr!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 8, 12, 'Nun redete Jesus aufs neue zu ihnen und sagte: »Ich bin das Licht der Welt: wer mir nachfolgt, wird nicht in der Finsternis wandeln, sondern das Licht des Lebens haben.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 8, 13, 'Da sagten die Pharisäer zu ihm: »Du legst Zeugnis über dich selbst ab: dein Zeugnis ist ungültig.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 8, 14, 'Jesus gab ihnen zur Antwort: »Auch wenn ich über mich selbst Zeugnis ablege, so ist mein Zeugnis doch gültig, denn ich weiß, woher ich gekommen bin und wohin ich gehe; ihr aber wißt nicht, woher ich komme und wohin ich gehe.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 8, 15, 'Ihr richtet nach dem Fleisch, ich richte überhaupt niemand.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 8, 16, 'Doch auch wenn ich richte, ist mein Urteil wahr; denn ich stehe (mit meinem Zeugnis) nicht allein, sondern mit mir ist der, welcher mich gesandt hat.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 8, 17, 'Nun steht doch auch in eurem Gesetz geschrieben, daß das Zeugnis zweier Personen wahr ist.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 8, 18, 'Ich lege Zeugnis von mir ab, und der Vater, der mich gesandt hat, legt auch Zeugnis von mir ab.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 8, 19, 'Da fragten sie ihn: »Wo ist (denn) dein Vater?« Jesus antwortete: »Weder mich noch meinen Vater kennt ihr; wenn ihr mich kenntet, würdet ihr auch meinen Vater kennen.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 8, 20, 'Diese Worte sprach er aus, als er beim Opferkasten im Tempel lehrte; und niemand legte Hand an ihn, weil seine Stunde noch nicht gekommen war.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 8, 21, 'Aufs neue sagte er dann zu ihnen: »Ich gehe weg; dann werdet ihr mich suchen und in eurer Sünde sterben. Wohin ich gehe, dahin könnt ihr nicht kommen.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 8, 22, 'Da sagten die Juden: »Will er sich etwa das Leben nehmen, weil er sagt: ›Wohin ich gehe, dahin könnt ihr nicht kommen‹?«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 8, 23, 'Da sagte er zu ihnen: »Ihr seid von unten her, ich bin von oben her; ihr seid aus dieser Welt, ich bin nicht aus dieser Welt.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 8, 24, 'Darum habe ich euch gesagt, daß ihr in euren Sünden sterben werdet; denn wenn ihr nicht glaubt, daß ich es bin, so werdet ihr in euren Sünden sterben.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 8, 25, 'Da fragten sie ihn: »Wer bist du denn?« Jesus antwortete ihnen: »Das, was ich von Anfang an (gesagt habe) und auch jetzt euch sage.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 8, 26, 'Vieles hätte ich über euch noch zu sagen und zu richten; aber der mich gesandt hat, ist wahrhaftig, und ich – was ich von ihm gehört habe, das rede ich zur Welt.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 8, 27, 'Sie verstanden nicht, daß er vom Vater zu ihnen redete.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 8, 28, 'Da fuhr nun Jesus fort: »Wenn ihr den Menschensohn erhöht haben werdet, dann werdet ihr erkennen, daß ich es bin und daß ich nichts von mir selbst aus tue, sondern so rede, wie der Vater mich gelehrt hat.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 8, 29, 'Und der mich gesandt hat, ist mit mir; er hat mich nicht allein gelassen, weil ich allezeit das tue, was ihm wohlgefällig ist.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 8, 30, 'Als er das sagte, kamen viele zum Glauben an ihn.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 8, 31, 'Nun sagte Jesus zu den Juden, die an ihn gläubig geworden waren: »Wenn ihr in meinem Wort bleibt, so seid ihr in Wahrheit meine Jünger');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 8, 32, 'und werdet die Wahrheit erkennen, und die Wahrheit wird euch frei machen.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 8, 33, 'Da entgegneten sie ihm: »Wir sind Abrahams Nachkommenschaft und haben noch niemals jemandem als Knechte gedient; wie kannst du da sagen: ›Ihr werdet frei werden‹?«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 8, 34, 'Jesus antwortete ihnen: »Wahrlich, wahrlich ich sage euch: ein jeder, der Sünde tut, ist ein Knecht der Sünde.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 8, 35, 'Der Knecht aber bleibt nicht für immer im Hause, der Sohn dagegen bleibt für immer darin.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 8, 36, 'Wenn also der Sohn euch frei gemacht hat, dann werdet ihr wirklich frei sein.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 8, 37, '»Ich weiß wohl, daß ihr Abrahams Nachkommenschaft seid; aber ihr sucht mich zu töten, weil mein Wort keinen Eingang bei euch findet.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 8, 38, 'Was ich beim Vater gesehen habe, das rede ich; dementsprechend tut auch ihr das, was ihr vom Vater gehört habt.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 8, 39, 'Sie antworteten ihm mit der Versicherung: »Unser Vater ist Abraham!« Jesus erwiderte ihnen: »Wenn ihr Abrahams Kinder seid, so handelt auch so wie Abraham (gehandelt hat)!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 8, 40, 'Nun aber geht ihr darauf aus, mich zu töten, einen Mann, der euch die Wahrheit verkündigt hat, wie ich sie von Gott gehört habe: so etwas hat Abraham nicht getan.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 8, 41, 'Ihr vollbringt die Werke eures Vaters.« Sie erwiderten ihm: »Wir sind keine unehelichen Kinder; wir haben nur einen einzigen Vater, nämlich Gott.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 8, 42, 'Da sagte Jesus zu ihnen: »Wenn Gott euer Vater wäre, dann würdet ihr mich lieben; denn ich bin von Gott ausgegangen und (von ihm) gekommen; ich bin nicht von mir selbst gekommen, sondern er hat mich gesandt.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 8, 43, 'Wie geht es nun zu, daß ihr meine Art zu reden nicht versteht? Weil ihr nicht imstande seid, das, was meine Worte besagen, auch nur anzuhören.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 8, 44, 'Ihr stammt eben vom Teufel als eurem Vater und wollt nach den Gelüsten eures Vaters handeln. Der ist ein Menschenmörder von Anfang an gewesen und steht nicht in der Wahrheit, weil die Wahrheit nicht in ihm ist. Wenn er die Lüge redet, dann redet er aus seinem eigensten Wesen heraus, denn er ist ein Lügner und der Vater von ihr.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 8, 45, 'Weil ich dagegen die Wahrheit rede, schenkt ihr mir keinen Glauben.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 8, 46, 'Wer von euch kann mich einer Sünde zeihen? Wenn ich die Wahrheit rede, warum schenkt ihr mir keinen Glauben?');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 8, 47, 'Wer aus Gott ist, hört die Worte Gottes; deshalb hört ihr sie nicht, weil ihr nicht von Gott seid.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 8, 48, 'Da gaben ihm die Juden zur Antwort: »Sagen wir nicht mit Recht, daß du ein Samariter und von einem bösen Geist besessen bist?«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 8, 49, 'Jesus antwortete ihnen: »Ich bin von keinem bösen Geist besessen, sondern ehre meinen Vater; doch ihr beschimpft mich.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 8, 50, 'Ich aber sorge nicht für meine Ehre: es ist einer da, der (für sie) sorgt und Gericht (für sie) hält.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 8, 51, 'Wahrlich, wahrlich ich sage euch: Wenn jemand mein Wort bewahrt, wird er den Tod in Ewigkeit nicht sehen.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 8, 52, 'Da entgegneten ihm die Juden: »Jetzt wissen wir sicher, daß du von einem bösen Geist besessen bist. Abraham ist gestorben und (ebenso) die Propheten, und du behauptest: ›Wenn jemand mein Wort bewahrt, wird er den Tod in Ewigkeit nicht schmecken.‹');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 8, 53, 'Bist du etwa größer als unser Vater Abraham, der doch gestorben ist? Und auch die Propheten sind gestorben. Was machst du aus dir selbst?«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 8, 54, 'Jesus antwortete: »Wenn ich mich selbst ehrte, so wäre es mit meiner Ehre nichts; nein, mein Vater ist es, der mich ehrt, derselbe, von dem ihr behauptet, er sei euer Gott;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 8, 55, 'und dabei habt ihr ihn nicht erkannt. Ich aber kenne ihn; und wenn ich sagen wollte, daß ich ihn nicht kenne, so würde ich euch gleich sein, nämlich ein Lügner. Doch ich kenne ihn und bewahre sein Wort.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 8, 56, 'Euer Vater Abraham hat darüber gejubelt, daß er meinen Tag sehen sollte, und er hat ihn gesehen und sich darüber gefreut.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 8, 57, 'Da sagten die Juden zu ihm: »Du bist noch nicht fünfzig Jahre alt und willst Abraham gesehen haben?«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 8, 58, 'Jesus antwortete ihnen: »Wahrlich, wahrlich ich sage euch: Ehe Abraham (geboren) ward, bin ich.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 8, 59, 'Da hoben sie Steine auf, um sie auf ihn zu werfen; Jesus aber verbarg sich und ging aus dem Tempel hinaus.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 9, 1, 'Im Vorübergehen sah er alsdann einen Mann, der von Geburt an blind war.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 9, 2, 'Da fragten ihn seine Jünger: »Rabbi, wer hat gesündigt, dieser Mann oder seine Eltern, daß er als Blinder geboren worden ist?«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 9, 3, 'Jesus antwortete: »Weder dieser hat gesündigt noch seine Eltern; sondern (dazu ist es geschehen) damit das Wirken Gottes an ihm offenbar würde.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 9, 4, 'Wir müssen die Werke dessen wirken, der mich gesandt hat, solange es Tag ist; es kommt die Nacht, in der niemand wirken kann.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 9, 5, 'Solange ich in der Welt bin, bin ich das Licht der Welt.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 9, 6, 'Nach diesen Worten spie er auf den Boden, stellte mit dem Speichel einen Teig her, legte dem Blinden den Teig auf die Augen');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 9, 7, 'und sagte zu ihm: »Gehe hin, wasche dich im Teiche Siloah!« – Das heißt übersetzt ›Abgesandter‹. – Da ging er hin, wusch sich und kam sehend zurück.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 9, 8, 'Nun sagten die Nachbarn und die Leute, die ihn früher als Bettler gesehen hatten: »Ist dieser nicht der Mann, der früher dasaß und bettelte?«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 9, 9, 'Die einen sagten: »Ja, er ist’s«; andere meinten: »Nein, er sieht ihm nur ähnlich«; er selbst aber sagte: »Ja, ich bin’s.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 9, 10, 'Da fragten sie ihn: »Auf welche Weise sind dir denn die Augen aufgetan worden?«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 9, 11, 'Er antwortete: »Der Mann, der Jesus heißt, stellte einen Teig her, strich ihn mir auf die Augen und sagte zu mir: ›Gehe hin an den Siloahteich und wasche dich dort!‹ Da ging ich hin, wusch mich und konnte sehen.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 9, 12, 'Sie fragten ihn nun: »Wo ist der Mann?« Er antwortete: »Das weiß ich nicht.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 9, 13, 'Man führte ihn nun zu den Pharisäern, ihn, den ehemals Blinden.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 9, 14, 'Es war aber (gerade) Sabbat an dem Tage gewesen, an dem Jesus den Teig hergestellt und ihm die Augen aufgetan hatte.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 9, 15, 'Da fragten ihn nochmals auch die Pharisäer, wie er sehend geworden sei, und er antwortete ihnen: »Er hat mir einen Teig auf die Augen gelegt, ich habe mich dann gewaschen und kann nun sehen.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 9, 16, 'Da sagten einige von den Pharisäern: »Der betreffende Mensch ist nicht von Gott her, weil er den Sabbat nicht hält«; andere dagegen meinten: »Wie könnte ein sündiger Mensch derartige Wunderzeichen tun?« So bestand eine Meinungsverschiedenheit unter ihnen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 9, 17, 'Sie fragten also den Blindgeborenen aufs neue: »Was sagst du denn von ihm? Dir hat er doch die Augen aufgetan.« Jener antwortete: »Er ist ein Prophet.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 9, 18, 'Die Juden wollten nun von ihm nicht glauben, daß er blind gewesen und sehend geworden sei, bis sie schließlich die Eltern des Sehendgewordenen riefen');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 9, 19, 'und sie fragten: »Ist dies euer Sohn, der, wie ihr behauptet, blind geboren worden ist? Wie kommt es denn, daß er jetzt sehen kann?«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 9, 20, 'Da antworteten seine Eltern: »Wir wissen, daß dies unser Sohn ist und daß er als Blinder geboren worden ist;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 9, 21, 'wie es aber kommt, daß er jetzt sehen kann, das wissen wir nicht, und wer ihm die Augen geöffnet hat, wissen wir auch nicht. Befragt ihn selbst darüber: er ist alt genug; er wird selbst Auskunft über sich geben.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 9, 22, 'Das sagten seine Eltern, weil sie sich vor den Juden fürchteten; denn die Juden hatten bereits miteinander abgemacht, daß, wenn jemand Jesus als den Messias anerkenne, er in den Bann getan werden solle.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 9, 23, 'Aus diesem Grunde sagten seine Eltern: »Er ist alt genug: fragt ihn selbst!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 9, 24, 'So ließen sie denn den Mann, der blind gewesen war, zum zweitenmal rufen und sagten zu ihm: »Gib Gott die Ehre! Wir wissen, daß dieser Mensch ein Sünder ist.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 9, 25, 'Da antwortete jener: »Ob er ein Sünder ist, weiß ich nicht; eins aber weiß ich, daß ich blind gewesen bin und jetzt sehen kann.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 9, 26, 'Da fragten sie ihn noch einmal: »Was hat er mit dir vorgenommen? Auf welche Weise hat er dir die Augen aufgetan?«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 9, 27, 'Er antwortete ihnen: »Ich habe es euch schon einmal gesagt, doch ihr habt nicht darauf gehört; warum wollt ihr es noch einmal hören? Wollt etwa auch ihr seine Jünger werden?«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 9, 28, 'Da schmähten sie ihn und sagten: »Du bist ein Jünger von ihm, wir aber sind Jünger von Mose.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 9, 29, 'Wir wissen, daß Gott zu Mose geredet hat; von diesem aber wissen wir nicht, woher er stammt.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 9, 30, 'Der Mann gab ihnen zur Antwort: »Darin liegt eben das Verwunderliche, daß ihr nicht wißt, woher er stammt, und mir hat er doch die Augen aufgetan.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 9, 31, 'Wir wissen, daß Gott Sünder nicht erhört, sondern nur wenn jemand gottesfürchtig ist und seinen Willen tut, den erhört er.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 9, 32, 'Von der Weltzeit an hat man noch nicht vernommen, daß jemand einem Blindgeborenen die Augen aufgetan hat.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 9, 33, 'Wenn dieser Mann nicht von Gott her wäre, so vermöchte er nichts zu tun.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 9, 34, 'Sie antworteten ihm: »Du bist ganz in Sünden geboren, und du willst uns Lehren geben?« Und sie stießen ihn (aus der Gemeinde der Gesetzesfrommen) aus.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 9, 35, 'Jesus erfuhr von seiner Ausstoßung und sagte zu ihm, als er ihn antraf: »Glaubst du an den Sohn Gottes?«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 9, 36, 'Jener gab zur Antwort: »Herr, wer ist denn das? Ich möchte gern an ihn glauben.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 9, 37, 'Jesus antwortete ihm: »Du hast ihn gesehen, und der mit dir redet, der ist es!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 9, 38, 'Jener sagte: »Ich glaube, Herr!« und warf sich vor ihm nieder.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 9, 39, 'Nun sagte Jesus: »Zu einer Scheidung bin ich in diese Welt gekommen: die Nichtsehenden sollen sehen können und die Sehenden blind werden.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 9, 40, 'Dies hörten einige von den Pharisäern, die sich in seiner Nähe befanden, und fragten ihn: »Sind wir etwa auch blind?«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 9, 41, 'Jesus antwortete ihnen: »Wäret ihr blind, so hättet ihr keine Sünde; nun ihr aber behauptet: ›Wir sind sehend‹, so bleibt eure Sünde!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 10, 1, '»Wahrlich, wahrlich ich sage euch: Wer nicht durch die Tür in die Hürde der Schafe hineingeht, sondern anderswo hineinsteigt, der ist ein Dieb und ein Räuber;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 10, 2, 'wer aber durch die Tür hineingeht, der ist der Hirt der Schafe.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 10, 3, 'Diesem macht der Türhüter auf, und die Schafe hören auf seine Stimme; er ruft die ihm gehörenden Schafe mit Namen und führt sie hinaus.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 10, 4, 'Wenn er dann alle Schafe, die ihm gehören, hinausgelassen hat, geht er vor ihnen her, und die Schafe folgen ihm, weil sie seine Stimme kennen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 10, 5, 'Einem Fremden aber würden sie nicht folgen, sondern vor ihm fliehen, weil sie die Stimme der Fremden nicht kennen.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 10, 6, 'Dies sagte Jesus ihnen in bildlicher Rede; sie verstanden aber nicht, was er ihnen damit sagen wollte.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 10, 7, 'Da sagte Jesus von neuem zu ihnen: »Wahrlich, wahrlich ich sage euch: Ich bin die Tür für die Schafe!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 10, 8, 'Alle, die vor mir gekommen sind, sind Diebe und Räuber; aber die Schafe haben nicht auf sie gehört.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 10, 9, 'Ich bin die Tür: Wenn jemand durch mich eingeht, wird er gerettet werden, wird ein- und ausgehen und Weide finden.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 10, 10, 'Der Dieb kommt nur, um zu stehlen und zu schlachten und Unheil anzurichten; ich aber bin gekommen, damit die Schafe Leben haben und Überfluß haben.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 10, 11, '»Ich bin der gute Hirt! Der gute Hirt gibt sein Leben für die Schafe hin.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 10, 12, 'Der Mietling (aber), der kein Hirt ist und dem die Schafe nicht zu eigen gehören, sieht den Wolf kommen, verläßt die Schafe und flieht; und der Wolf fällt sie an und zerstreut sie:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 10, 13, 'er ist ja nur ein Mietling, und ihm ist an den Schafen nichts gelegen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 10, 14, 'Ich bin der gute Hirt und kenne die Meinen, und die Meinen kennen mich,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 10, 15, 'ebenso wie der Vater mich kennt und ich den Vater kenne; und ich gebe mein Leben für die Schafe hin. –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 10, 16, 'Ich habe auch noch andere Schafe, die nicht zu dieser Hürde gehören; auch diese muß ich führen, und sie werden auf meinen Ruf hören, und es wird eine Herde, ein Hirt sein.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 10, 17, 'Um deswillen hat der Vater mich lieb, weil ich mein Leben hingebe, damit ich es wieder an mich nehme;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 10, 18, 'niemand nimmt es mir, sondern ich gebe es freiwillig hin. Ich habe Vollmacht, es hinzugeben, und ich habe Vollmacht, es wieder an mich zu nehmen; die Ermächtigung dazu habe ich von meinem Vater erhalten.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 10, 19, 'Da entstand wegen dieser Worte wieder eine Meinungsverschiedenheit unter den Juden.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 10, 20, 'Viele von ihnen sagten nämlich: »Er ist von einem bösen Geist besessen und ist von Sinnen: was hört ihr ihn noch an?«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 10, 21, 'Andere aber sagten: »Das sind nicht Worte eines Besessenen; kann etwa ein böser Geist Blinden die Augen auftun?«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 10, 22, 'Damals fand das Fest der Tempelweihe in Jerusalem statt; es war Winter,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 10, 23, 'und Jesus ging im Tempel in der Halle Salomos auf und ab.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 10, 24, 'Da umringten ihn die Juden und sagten zu ihm: »Wie lange läßt du uns noch in Ungewißheit schweben? Bist du Christus, so sage es uns frei heraus!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 10, 25, 'Jesus antwortete ihnen: »Ich habe es euch gesagt, doch ihr glaubt (es) nicht. Die Werke, die ich im Namen meines Vaters vollbringe, die legen Zeugnis von mir ab;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 10, 26, 'aber ihr glaubt nicht, weil ihr nicht zu meinen Schafen gehört.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 10, 27, 'Meine Schafe hören auf meine Stimme, und ich kenne sie, und sie folgen mir nach;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 10, 28, 'und ich gebe ihnen ewiges Leben, und sie werden in alle Ewigkeit nicht umkommen, und niemand wird sie meiner Hand entreißen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 10, 29, 'Mein Vater, der sie mir gegeben hat, ist größer als alle, und niemand vermag sie der Hand meines Vaters zu entreißen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 10, 30, 'Ich und der Vater sind eins!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 10, 31, 'Da holten die Juden wieder Steine herbei, um ihn zu steinigen;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 10, 32, 'Jesus aber sagte zu ihnen: »Viele gute Werke habe ich euch vom Vater her sehen lassen: welches von diesen Werken ist es, wegen dessen ihr mich steinigen wollt?«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 10, 33, 'Die Juden antworteten ihm: »Nicht wegen eines guten Werkes wollen wir dich steinigen, sondern wegen Gotteslästerung, und zwar weil du, der du doch (nur) ein Mensch bist, dich selbst zu Gott machst.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 10, 34, 'Jesus antwortete ihnen: »Steht nicht in eurem Gesetz geschrieben: ›Ich habe gesagt: Ihr seid Götter‹?');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 10, 35, 'Wenn die Schrift schon jene (Männer), an die das Wort Gottes erging, Götter genannt hat – und die Schrift kann doch ihre Gültigkeit nicht verlieren –:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 10, 36, 'wie könnt ihr da dem, welchem der Vater die Weihe erteilt und den er in die Welt gesandt hat, Gotteslästerung vorwerfen, weil ich gesagt habe: ›Ich bin Gottes Sohn‹?');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 10, 37, 'Wenn ich nicht die Werke meines Vaters tue, so glaubt mir nicht;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 10, 38, 'wenn ich sie aber tue, so glaubt, wenn auch nicht mir selbst, so doch meinen Werken, damit ihr immer gewisser zu der Erkenntnis gelangt, daß der Vater in mir ist und ich im Vater bin.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 10, 39, 'Da suchten sie ihn wiederum festzunehmen, doch er entkam aus ihren Händen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 10, 40, 'Er zog nun wieder in das Ostjordanland an den Ort, wo Johannes zuerst getauft hatte, und blieb dort.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 10, 41, 'Da kamen viele zu ihm und sagten: »Johannes hat zwar keinerlei Wunder getan, alles aber, was Johannes über diesen Mann gesagt hat, ist wahr gewesen.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 10, 42, 'Und viele kamen dort zum Glauben an ihn.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 11, 1, 'Es lag aber ein Mann krank darnieder, Lazarus von Bethanien, aus dem Dorfe, in welchem Maria und ihre Schwester Martha wohnten –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 11, 2, 'es war die Maria, die den Herrn mit Myrrhenbalsam gesalbt und seine Füße mit ihren Haaren getrocknet hat –: deren Bruder Lazarus lag krank darnieder.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 11, 3, 'Da sandten die Schwestern zu Jesus und ließen ihm sagen: »Herr, siehe, der, den du lieb hast, der ist krank!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 11, 4, 'Als Jesus das vernahm, sagte er: »Diese Krankheit führt nicht zum Tode, sondern dient zur Verherrlichung Gottes, weil der Sohn Gottes durch sie verherrlicht werden soll.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 11, 5, 'Jesus hatte aber die Martha und ihre Schwester und auch den Lazarus lieb.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 11, 6, 'Als er nun von dessen Krankheit gehört hatte, blieb er zunächst noch zwei Tage an dem Orte, wo er sich befand;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 11, 7, 'dann erst sagte er zu seinen Jüngern: »Wir wollen wieder nach Judäa ziehen!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 11, 8, 'Die Jünger erwiderten ihm: »Rabbi, soeben erst haben die Juden dich steinigen wollen, und nun willst du wieder dorthin gehen?«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 11, 9, 'Jesus antwortete: »Hat der Tag nicht zwölf Stunden? Wenn man am Tage wandert, stößt man nicht an, weil man das Licht dieser Welt sieht;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 11, 10, 'wenn man aber bei Nacht wandert, stößt man an, weil man kein Licht in sich hat, um zu sehen.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 11, 11, 'So sagte er und fuhr dann fort: »Unser Freund Lazarus ist eingeschlafen; aber ich gehe hin, um ihn aus dem Schlaf zu wecken.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 11, 12, 'Da erwiderten ihm die Jünger: »Herr, wenn er eingeschlafen ist, wird er wieder gesund werden.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 11, 13, 'Jesus hatte den Tod des Lazarus gemeint, sie dagegen waren der Meinung, er rede vom gewöhnlichen Schlaf.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 11, 14, 'Da sagte Jesus ihnen denn mit klaren Worten: »Lazarus ist gestorben,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 11, 15, 'und ich freue mich euretwegen, daß ich nicht dort gewesen bin, damit ihr glauben lernt. Doch nun laßt uns zu ihm gehen!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 11, 16, 'Da sagte Thomas, der auch den Namen ›Zwilling‹ führt, zu seinen Mitjüngern: »Laßt uns hingehen, um mit ihm zu sterben!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 11, 17, 'Als nun Jesus hinkam, fand er ihn schon seit vier Tagen im Grabe liegen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 11, 18, 'Bethanien lag aber in der Nähe von Jerusalem, etwa fünfzehn Stadien von dort entfernt;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 11, 19, 'darum hatten sich viele von den Juden bei Martha und Maria eingefunden, um sie über den Tod ihres Bruders zu trösten.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 11, 20, 'Als nun Martha von der Ankunft Jesu hörte, ging sie ihm entgegen; Maria aber blieb im Hause (bei den Trauergästen) sitzen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 11, 21, 'Da sagte Martha zu Jesus: »Herr, wärest du hier gewesen, so wäre mein Bruder nicht gestorben!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 11, 22, 'Doch auch so weiß ich, daß Gott dir alles gewähren wird, um was du Gott bittest.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 11, 23, 'Jesus erwiderte ihr: »Dein Bruder wird auferstehen!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 11, 24, 'Martha antwortete ihm: »Ich weiß, daß er bei der Auferstehung am jüngsten Tage auferstehen wird.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 11, 25, 'Jesus entgegnete ihr: »Ich bin die Auferstehung und das Leben; wer an mich glaubt, wird leben, wenn er auch stirbt,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 11, 26, 'und wer da lebt und an mich glaubt, wird in Ewigkeit nicht sterben! Glaubst du das?«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 11, 27, 'Sie antwortete ihm: »Ja, Herr, ich habe den Glauben gewonnen, daß du Christus bist, der Sohn Gottes, der in die Welt kommen soll.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 11, 28, 'Nach diesen Worten ging sie weg und rief ihre Schwester Maria, indem sie ihr zuflüsterte: »Der Meister ist da und läßt dich rufen!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 11, 29, 'Sobald jene das gehört hatte, stand sie schnell auf und machte sich auf den Weg zu ihm;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 11, 30, 'Jesus war aber noch nicht in das Dorf gekommen, sondern befand sich noch an der Stelle, wohin Martha ihm entgegengekommen war.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 11, 31, 'Als nun die Juden, die bei Maria im Hause waren und sie zu trösten suchten, sie schnell aufstehen und hinausgehen sahen, folgten sie ihr nach in der Meinung, sie wolle zum Grabe gehen, um dort zu weinen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 11, 32, 'Als nun Maria an die Stelle kam, wo Jesus sich befand, und ihn erblickt hatte, warf sie sich ihm zu Füßen und sagte zu ihm: »Herr, wärest du hier gewesen, so wäre mein Bruder nicht gestorben!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 11, 33, 'Als nun Jesus sah, wie sie weinte und wie auch die Juden weinten, die mit ihr gekommen waren, fühlte er sich im Geist heftig bewegt und erschüttert.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 11, 34, 'Darauf fragte er: »Wo habt ihr ihn beigesetzt?« Sie antworteten ihm: »Herr, komm und sieh es!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 11, 35, 'Jesus weinte.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 11, 36, 'Da sagten die Juden: »Seht, wie lieb hat er ihn gehabt!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 11, 37, 'Einige von ihnen aber sagten: »Hätte dieser, der dem Blinden die Augen aufgetan hat, nicht auch machen können, daß dieser hier nicht zu sterben brauchte?«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 11, 38, 'Da geriet Jesus in seinem Innern aufs neue in heftige Erregung und trat an das Grab; es war dies aber eine Höhle, vor deren Eingang ein Stein lag.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 11, 39, 'Jesus sagte: »Hebt den Stein weg!« Martha, die Schwester des Verstorbenen, erwiderte ihm: »Herr, er ist schon in Verwesung; es ist ja schon der vierte Tag seit seinem Tode.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 11, 40, 'Jesus entgegnete ihr: »Habe ich dir nicht gesagt, daß, wenn du glaubst, du die Herrlichkeit Gottes sehen wirst?«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 11, 41, 'Da hoben sie den Stein weg; Jesus aber richtete die Augen (zum Himmel) empor und betete: »Vater, ich danke dir, daß du mich erhört hast!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 11, 42, 'Ich wußte wohl, daß du mich allezeit erhörst; aber um des Volkes willen, das hier rings (um mich) steht, habe ich’s gesagt, damit sie zum Glauben kommen, daß du mich gesandt hast.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 11, 43, 'Nach diesen Worten rief er mit lauter Stimme: »Lazarus, komm heraus!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 11, 44, 'Da kam der Gestorbene heraus, an den Beinen und Armen mit Binden umwickelt, und sein Gesicht war mit einem Schweißtuch umbunden. Jesus sagte zu ihnen: »Macht ihn los (von seinen Hüllen) und laßt ihn (frei) gehen!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 11, 45, 'Viele nun von den Juden, die zu Maria gekommen waren und zugeschaut hatten bei dem, was Jesus getan hatte, wurden an ihn gläubig;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 11, 46, 'einige von ihnen aber gingen weg zu den Pharisäern und berichteten ihnen, was Jesus getan hatte.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 11, 47, 'Infolgedessen beriefen die Hohenpriester und Pharisäer eine Versammlung des Hohen Rates und sagten: »Was sollen wir tun, da dieser Mensch so viele Wunderzeichen vollführt?');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 11, 48, 'Lassen wir ihn so weiter gewähren, so werden (schließlich) noch alle an ihn glauben, und dann werden die Römer kommen und uns die Stätte und unser Volkstum beseitigen.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 11, 49, 'Einer aber von ihnen, nämlich Kaiphas, der in jenem Jahre Hoherpriester war, sagte zu ihnen: »Ihr seid ganz ohne Einsicht');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 11, 50, 'und bedenkt nicht, daß es besser für euch ist, daß ein einzelner Mensch für das Volk stirbt, und nicht das ganze Volk zugrunde geht.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 11, 51, 'Dies sagte er aber nicht von sich selbst aus, sondern als Hoherpriester jenes Jahres weissagte er (unbewußt), daß Jesus (zum Heil) für das Volk sterben würde,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 11, 52, 'und zwar nicht für das (jüdische) Volk allein, sondern auch, damit er die (unter den Völkern) zerstreuten Gotteskinder zu einem einheitlichen Ganzen vereinigte.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 11, 53, 'So beratschlagten sie denn von diesem Tage an miteinander in der Absicht, ihn zu töten.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 11, 54, 'Daher ging Jesus nicht mehr öffentlich unter den Juden umher, sondern zog sich von dort in die Gegend nahe bei der Wüste nach einer Stadt namens Ephraim zurück und verweilte dort mit seinen Jüngern längere Zeit.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 11, 55, 'Es stand aber das jüdische Passah nahe bevor, und viele Leute zogen aus dem (ganzen) Lande schon vor dem Passah nach Jerusalem hinauf, um sich zu heiligen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 11, 56, 'Sie suchten nun dort nach Jesus und besprachen sich miteinander, während sie auf dem Tempelplatze standen: »Was meint ihr? Er wird doch wohl nicht zum Feste kommen?«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 11, 57, 'Die Hohenpriester und Pharisäer aber hatten mehrfach die Verfügung ergehen lassen, wenn jemand seinen Aufenthaltsort in Erfahrung bringe, solle er Anzeige erstatten, damit sie ihn festnehmen könnten.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 12, 1, 'Jesus kam nun sechs Tage vor dem Passah nach Bethanien, wo Lazarus wohnte, den Jesus von den Toten auferweckt hatte.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 12, 2, 'Sie veranstalteten ihm zu Ehren dort ein Mahl, bei dem Martha die Bedienung besorgte, während Lazarus sich unter denen befand, die mit ihm zu Tische saßen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 12, 3, 'Da nahm Maria ein Pfund Myrrhenbalsam, echte, kostbare Nardensalbe, salbte Jesus die Füße und trocknete ihm die Füße mit ihrem Haar ab; das ganze Haus wurde dabei vom Duft der Salbe erfüllt.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 12, 4, 'Da sagte Judas Iskariot, einer von seinen Jüngern, sein nachmaliger Verräter:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 12, 5, '»Warum hat man diese Salbe nicht für dreihundert Denare verkauft und (den Erlös) den Armen gegeben?«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 12, 6, 'Das sagte er aber nicht, weil ihm die Armen sonderlich am Herzen lagen, sondern weil er ein Dieb war und als Kassenführer die Einlagen veruntreute.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 12, 7, 'Da sagte Jesus: »Laß sie in Ruhe! Sie soll (die Salbe) für den Tag meiner Bestattung aufbewahrt haben.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 12, 8, 'Denn die Armen habt ihr allezeit bei euch, mich aber habt ihr nicht allezeit.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 12, 9, 'Es erfuhr nun die zahlreiche Volksmenge der Juden, daß Jesus dort sei; und sie kamen hin nicht nur um Jesu willen, sondern auch um Lazarus zu sehen, den er von den Toten auferweckt hatte.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 12, 10, 'Die Hohenpriester aber hielten Beratungen ab in der Absicht, auch Lazarus zu töten,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 12, 11, 'weil viele Juden seinetwegen dorthin gingen und zum Glauben an Jesus kamen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 12, 12, 'Als dann am folgenden Tage von der Volksmenge, die zum Fest gekommen war, ein großer Teil erfuhr, daß Jesus auf dem Wege nach Jerusalem sei,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 12, 13, 'nahmen sie Palmenzweige, zogen hinaus ihm entgegen und riefen laut: »Hosianna! Gepriesen sei, der da kommt im Namen des Herrn und als der König Israels!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 12, 14, 'Jesus hatte aber einen jungen Esel vorgefunden und sich daraufgesetzt, wie geschrieben steht:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 12, 15, '»Fürchte dich nicht, Tochter Zion! Siehe, dein König kommt und reitet auf einem Eselsfüllen.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 12, 16, 'An dies Wort hatten seine Jünger zunächst nicht gedacht; als Jesus aber zur Herrlichkeit eingegangen war, da wurde es ihnen klar, daß dies mit Bezug auf ihn geschrieben stand und daß man dies so an ihm zur Ausführung gebracht hatte.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 12, 17, 'Die Volksmenge nun, die bei ihm gewesen war, als er Lazarus aus dem Grabe gerufen und ihn von den Toten auferweckt hatte, hatte Zeugnis für ihn abgelegt;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 12, 18, 'darum waren ihm auch die vielen Menschen entgegengezogen, weil sie erfahren hatten, daß er dies Wunderzeichen getan habe.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 12, 19, 'Da sagten die Pharisäer zueinander: »Ihr seht, daß ihr nichts erreicht: die ganze Welt ist ja hinter ihm hergelaufen!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 12, 20, 'Es befanden sich aber einige Griechen unter denen, die nach Jerusalem hinaufzuziehen pflegten, um dort ihre Anbetung am Fest zu verrichten.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 12, 21, 'Diese wandten sich nun an Philippus, der aus Bethsaida in Galiläa war, mit der Bitte: »Herr, wir möchten Jesus gern sehen!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 12, 22, 'Da ging Philippus hin und sagte es dem Andreas; Andreas und Philippus kamen alsdann und teilten es Jesus mit.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 12, 23, 'Dieser antwortete ihnen mit den Worten: »Die Stunde der Verherrlichung ist für den Menschensohn gekommen!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 12, 24, 'Wahrlich, wahrlich ich sage euch: Wenn das Weizenkorn nicht in die Erde hineinfällt und erstirbt, so bleibt es für sich allein; wenn es aber erstirbt, bringt es reiche Frucht.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 12, 25, 'Wer sein Leben liebt, verliert es; wer aber sein Leben in dieser Welt haßt, wird es zu ewigem Leben bewahren.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 12, 26, 'Will jemand mir dienen, so folge er mir nach, und wo ich bin, da wird auch mein Diener sein; wenn jemand mir dient, wird der Vater ihn ehren.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 12, 27, 'Jetzt ist meine Seele erschüttert, und was soll ich sagen? (Soll ich bitten:) ›Vater, errette mich aus dieser Stunde!‹? Nein, gerade deshalb bin ich ja in diese Stunde gekommen:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 12, 28, 'Vater, verherrliche deinen Namen!« Da erscholl eine Stimme aus dem Himmel: »Ich habe ihn (schon) verherrlicht und werde ihn noch weiter verherrlichen!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 12, 29, 'Da sagte die Volksmenge, die dabeistand und zuhörte, es habe gedonnert; andere sagten: »Ein Engel hat mit ihm geredet.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 12, 30, 'Da nahm Jesus das Wort und sagte: »Nicht um meinetwillen ist diese Stimme erschollen, sondern um euretwillen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 12, 31, 'Jetzt ergeht ein Gericht über diese Welt, jetzt wird der Fürst dieser Welt hinausgestoßen werden,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 12, 32, 'und ich werde, wenn ich von der Erde erhöht sein werde, alle zu mir ziehen!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 12, 33, 'Dies sagte er aber, um anzudeuten, welches Todes er sterben würde.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 12, 34, 'Da entgegnete ihm die Volksmenge: »Wir haben aus dem Gesetz gehört, daß Christus in Ewigkeit (am Leben) bleibt; wie kannst du da behaupten, der Menschensohn müsse erhöht werden? Wer ist denn dieser Menschensohn?«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 12, 35, 'Da sagte Jesus zu ihnen: »Nur noch kurze Zeit ist das Licht unter euch. Wandelt (im Licht), solange ihr das Licht noch habt, damit euch die Finsternis nicht überfällt; denn wer in der Finsternis wandelt, weiß nicht, wohin er gelangt.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 12, 36, 'Solange ihr das Licht noch habt, glaubt an das Licht, damit ihr Söhne des Lichtes werdet!« So sprach Jesus, entfernte sich dann und hielt sich vor ihnen verborgen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 12, 37, 'Obwohl er aber so viele Wunderzeichen vor ihren Augen getan hatte, glaubten sie doch nicht an ihn;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 12, 38, 'es sollte sich eben das Wort des Propheten Jesaja erfüllen, das da lautet: »Herr, wer hat unserer Botschaft Glauben geschenkt, und wem ist der Arm des Herrn offenbar geworden?«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 12, 39, 'Deshalb konnten sie nicht glauben, weil Jesaja an einer anderen Stelle gesagt hat:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 12, 40, '»Er hat ihnen die Augen geblendet und ihr Herz verhärtet, damit sie mit ihren Augen nicht sehen und mit ihrem Herzen (nicht) zur Erkenntnis gelangen und sie sich (nicht) bekehren sollten und ich sie (nicht) heile.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 12, 41, 'So hat Jesaja gesprochen, weil er seine Herrlichkeit schaute, und von ihm hat er geredet.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 12, 42, 'Gleichwohl glaubten auch von den Obersten viele an ihn, bekannten es aber um der Pharisäer willen nicht offen, um nicht in den Bann getan zu werden;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 12, 43, 'denn an der Ehre bei den Menschen lag ihnen mehr als an der Ehre bei Gott.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 12, 44, 'Jesus aber rief mit lauter Stimme aus: »Wer an mich glaubt, glaubt nicht an mich, sondern an den, der mich gesandt hat;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 12, 45, 'und wer mich sieht, sieht den, der mich gesandt hat.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 12, 46, 'Ich bin als Licht in die Welt gekommen, damit jeder, der an mich glaubt, nicht in der Finsternis bleibt.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 12, 47, 'Und wenn jemand meine Worte hört und sie nicht befolgt, so richte nicht ich ihn; denn ich bin nicht gekommen, um die Welt zu richten, sondern um die Welt zu retten.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 12, 48, 'Wer mich verwirft und meine Worte nicht annimmt, der hat (damit schon) seinen Richter: das Wort, das ich verkündet habe, wird sein Richter sein am jüngsten Tage.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 12, 49, 'Denn ich habe nicht von mir selbst aus geredet, sondern der Vater, der mich gesandt hat, der hat mir Auftrag gegeben, was ich sagen und was ich reden soll,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 12, 50, 'und ich weiß, daß sein Auftrag ewiges Leben bedeutet. Was ich also rede, das rede ich so, wie der Vater es mir gesagt hat.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 13, 1, 'Vor dem Passahfest aber, da Jesus wohl wußte, daß für ihn die Stunde gekommen sei, aus dieser Welt zum Vater hinüberzugehen, bewies er den Seinen, die in der Welt waren, die Liebe, die er (bisher) zu ihnen gehegt hatte, bis zum letzten Augenblick.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 13, 2, 'Es war bei einem Mahl, und schon hatte der Teufel dem Judas Iskariot, dem Sohne Simons, den Entschluß des Verrats eingegeben.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 13, 3, 'Weil Jesus nun wußte, daß der Vater ihm alles in die Hände gegeben hatte und daß er von Gott ausgegangen sei und wieder zu Gott hingehe,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 13, 4, 'erhob er sich beim Mahl von seinem Platz, legte die Oberkleidung ab, nahm einen linnenen Schurz und band ihn sich um.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 13, 5, 'Danach goß er Wasser in das Waschbecken und begann seinen Jüngern die Füße zu waschen und sie mit dem linnenen Schurz, den er sich umgebunden hatte, abzutrocknen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 13, 6, 'So kam er denn auch zu Simon Petrus. Dieser sagte zu ihm: »Herr, du willst mir die Füße waschen?«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 13, 7, 'Jesus antwortete ihm mit den Worten: »Was ich damit tue, verstehst du jetzt noch nicht, du wirst es aber nachher verstehen.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 13, 8, 'Petrus entgegnete ihm: »Nun und nimmer sollst du mir die Füße waschen!« Jesus antwortete ihm: »Wenn ich dich nicht wasche, so hast du keinen Anteil an mir.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 13, 9, 'Da sagte Simon Petrus zu ihm: »Herr, dann nicht nur meine Füße, sondern auch die Hände und den Kopf!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 13, 10, 'Jesus antwortete ihm: »Wer gebadet ist, dem braucht nichts weiter gewaschen zu werden als die Füße, sondern er ist am ganzen Körper rein; und ihr seid rein, jedoch nicht alle.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 13, 11, 'Er kannte nämlich seinen Verräter wohl; deshalb sagte er: »Ihr seid nicht alle rein.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 13, 12, 'Nachdem er ihnen nun die Füße gewaschen und seine Oberkleidung wieder angelegt und seinen Platz am Tisch wieder eingenommen hatte, sagte er zu ihnen: »Versteht ihr, was ich an euch getan habe?');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 13, 13, 'Ihr redet mich mit ›Meister‹ und ›Herr‹ an und habt recht mit dieser Benennung, denn ich bin es wirklich.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 13, 14, 'Wenn nun ich, der Herr und der Meister, euch die Füße gewaschen habe, so seid auch ihr verpflichtet, einander die Füße zu waschen;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 13, 15, 'denn ein Vorbild habe ich euch gegeben, damit ihr es ebenso machet, wie ich an euch getan habe.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 13, 16, 'Wahrlich, wahrlich ich sage euch: Ein Knecht steht nicht höher als sein Herr, und ein Sendbote nicht höher als sein Absender.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 13, 17, 'Wenn ihr dies wißt – selig seid ihr, wenn ihr danach handelt!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 13, 18, 'Nicht von euch allen rede ich; ich weiß ja, wie die beschaffen sind, welche ich erwählt habe; aber das Schriftwort muß erfüllt werden: ›Der mein Brot ißt, hat seine Ferse gegen mich erhoben.‹');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 13, 19, 'Schon jetzt sage ich es euch, noch bevor es geschieht, damit ihr, wenn es geschehen ist, glaubt, daß ich es bin (den die Schrift meint).');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 13, 20, 'Wahrlich, wahrlich ich sage euch: Wer dann, wenn ich jemand sende, ihn aufnimmt, der nimmt mich auf; wer aber mich aufnimmt, nimmt den auf, der mich gesandt hat.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 13, 21, 'Nach diesen Worten wurde Jesus im Geist aufs tiefste erschüttert und sprach es offen aus: »Wahrlich, wahrlich ich sage euch: Einer von euch wird mich verraten!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 13, 22, 'Da blickten die Jünger einander an und waren ratlos darüber, wen er meinte.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 13, 23, 'Es hatte aber einer von seinen Jüngern bei Tisch seinen Platz an der Brust Jesu, nämlich der, den Jesus (besonders) lieb hatte.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 13, 24, 'Diesem gab nun Simon Petrus einen Wink und sagte ihm: »Laß uns wissen, wen er meint!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 13, 25, 'Jener lehnte sich nun auch sogleich an die Brust Jesu zurück und fragte ihn: »Herr, wer ist es?«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 13, 26, 'Da antwortete Jesus: »Der ist es, dem ich den Bissen (in die Schüssel) eintauchen und reichen werde.« Darauf tauchte er den Bissen ein, nahm ihn und reichte ihn dem Judas, dem Sohne Simons aus Kariot.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 13, 27, 'Nachdem dieser den Bissen genommen hatte, fuhr der Satan in ihn hinein. Nun sagte Jesus zu ihm: »Was du zu tun vorhast, das tu bald!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 13, 28, 'Was er ihm damit hatte sagen wollen, verstand keiner von den Tischgenossen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 13, 29, 'Einige nämlich meinten, weil Judas die Kasse führte, wolle Jesus ihm sagen: »Kaufe das ein, was wir für das Fest nötig haben«, oder er solle den Armen etwas geben.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 13, 30, 'Nachdem nun jener den Bissen genommen hatte, ging er sogleich hinaus. Es war aber Nacht.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 13, 31, 'Nach seinem Weggange nun sagte Jesus: »Jetzt ist der Menschensohn verherrlicht, und Gott ist in ihm verherrlicht worden!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 13, 32, 'Wenn Gott in ihm verherrlicht ist, so wird Gott auch ihn in sich selbst verherrlichen, und zwar wird er ihn sofort verherrlichen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 13, 33, 'Liebe Kinder, nur noch kurze Zeit bin ich bei euch; dann werdet ihr mich suchen, und, wie ich schon den Juden gesagt habe: ›Wohin ich gehe, dahin könnt ihr nicht kommen‹, so sage ich es jetzt auch euch.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 13, 34, '»Ein neues Gebot gebe ich euch, daß ihr einander lieben sollt; wie ich euch geliebt habe, so sollt auch ihr einander lieben.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 13, 35, 'Daran werden alle erkennen, daß ihr meine Jünger seid, wenn ihr Liebe untereinander habt.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 13, 36, 'Da fragte ihn Simon Petrus: »Herr, wohin gehst du?« Jesus antwortete ihm: »Wohin ich gehe, dahin kannst du mir jetzt nicht folgen; du wirst mir aber später folgen.« Petrus antwortete ihm:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 13, 37, '»Herr, warum sollte ich dir jetzt nicht folgen können? Mein Leben will ich für dich hingeben!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 13, 38, 'Da antwortete Jesus: »Dein Leben willst du für mich hingeben? Wahrlich, wahrlich ich sage dir: Der Hahn wird nicht krähen, bevor du mich dreimal verleugnet hast.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 14, 1, '»Euer Herz erschrecke nicht! Vertrauet auf Gott und vertrauet auf mich!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 14, 2, 'In meines Vaters Hause sind viele Wohnungen; wenn es nicht so wäre, hätte ich es euch gesagt; denn ich gehe hin, euch eine Stätte zu bereiten;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 14, 3, 'und wenn ich hingegangen bin und euch eine Stätte bereitet habe, komme ich wieder und werde euch zu mir nehmen, damit da, wo ich bin, auch ihr seid.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 14, 4, 'Und wohin ich gehe – den Weg dahin kennt ihr.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 14, 5, 'Da sagte Thomas zu ihm: »Herr, wir wissen nicht, wohin du gehst: wie sollten wir da den Weg kennen?«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 14, 6, 'Jesus antwortete ihm: »Ich bin der Weg und die Wahrheit und das Leben; niemand kommt zum Vater außer durch mich.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 14, 7, 'Wenn ihr mich erkannt hättet, würdet ihr auch meinen Vater kennen; von jetzt an kennt ihr ihn und habt ihn gesehen.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 14, 8, 'Philippus sagte zu ihm: »Herr, zeige uns den Vater: das genügt uns.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 14, 9, 'Da sagte Jesus zu ihm: »So lange Zeit schon bin ich mit euch zusammen, und (trotzdem) hast du mich noch nicht erkannt, Philippus? Wer mich gesehen hat, der hat den Vater gesehen; wie kannst du sagen: ›Zeige uns den Vater!‹');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 14, 10, 'Glaubst du nicht, daß ich im Vater bin und der Vater in mir ist? Die Worte, die ich zu euch rede, spreche ich nicht von mir selbst aus, nein, der Vater, der dauernd in mir ist, der tut seine Werke.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 14, 11, 'Glaubet mir, daß ich im Vater bin und der Vater in mir ist; wo nicht, so glaubt doch um der Werke selbst willen!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 14, 12, 'Wahrlich, wahrlich ich sage euch: Wer an mich glaubt, wird die Werke, die ich tue, auch vollbringen, ja er wird noch größere als diese vollbringen;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 14, 13, 'denn ich gehe zum Vater, und alles, um was ihr (dann) in meinem Namen bitten werdet, das werde ich tun, damit der Vater im Sohn verherrlicht werde.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 14, 14, 'Wenn ihr mich um etwas in meinem Namen bitten werdet, so werde ich es tun. –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 14, 15, 'Wenn ihr mich liebt, so werdet ihr meine Gebote halten;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 14, 16, 'und ich werde den Vater bitten, und er wird euch einen anderen Helfer geben, damit er bis in Ewigkeit bei euch sei:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 14, 17, 'den Geist der Wahrheit, den die Welt nicht empfangen kann, weil sie ihn nicht sieht und ihn nicht erkennt; ihr aber erkennt ihn, weil er bei euch bleibt und in euch sein wird. –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 14, 18, 'Ich will euch nicht verwaist zurücklassen: ich komme zu euch!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 14, 19, 'Nur noch eine kurze Zeit, dann sieht mich die Welt nicht mehr; ihr aber seht mich, daß ich lebe, und ihr sollt auch leben!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 14, 20, 'An jenem Tage werdet ihr erkennen, daß ich in meinem Vater bin und ihr in mir seid und ich in euch.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 14, 21, '»Wer meine Gebote hat und sie hält, der ist es, der mich liebt; wer aber mich liebt, wird von meinem Vater geliebt werden, und auch ich werde ihn lieben und mich ihm offenbaren.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 14, 22, 'Da fragte ihn Judas – nicht der Iskariot –: »Herr, wie kommt es, daß du dich (nur) uns offenbaren willst und nicht (auch) der Welt?«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 14, 23, 'Jesus antwortete ihm mit den Worten: »Wenn jemand mich liebt, wird er mein Wort halten, und mein Vater wird ihn lieben, und wir werden zu ihm kommen und Wohnung bei ihm nehmen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 14, 24, 'Wer mich nicht liebt, hält auch meine Worte nicht; und doch kommt das Wort, das ihr hört, nicht von mir, sondern vom Vater, der mich gesandt hat.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 14, 25, '»Dies habe ich zu euch geredet, während ich bei euch weilte.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 14, 26, 'Der Helfer aber, der heilige Geist, den der Vater in meinem Namen senden wird, der wird euch über alles (Weitere) belehren und euch an alles erinnern, was ich euch gesagt habe. –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 14, 27, 'Frieden hinterlasse ich euch, meinen Frieden gebe ich euch; nicht so, wie die Welt gibt, gebe ich euch. Euer Herz erschrecke nicht und verzage nicht!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 14, 28, 'Ihr habt gehört, daß ich euch gesagt habe: ›Ich gehe hin und komme wieder zu euch.‹ Hättet ihr mich lieb, so hättet ihr euch gefreut, daß ich zum Vater gehe, denn der Vater ist größer als ich.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 14, 29, 'Und schon jetzt habe ich es euch gesagt, bevor es geschieht, damit ihr zum Glauben kommt, wenn es geschieht.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 14, 30, 'Ich werde nicht mehr viel mit euch reden, denn es kommt der Fürst der Welt; doch über mich hat er keine Macht.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 14, 31, 'Damit aber die Welt erkennt, daß ich den Vater liebe und so tue, wie der Vater mir geboten hat: erhebt euch! Laßt uns von hier aufbrechen!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 15, 1, '»Ich bin der wahre Weinstock, und mein Vater ist der Weingärtner.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 15, 2, 'Jede Rebe an mir, die keine Frucht bringt, entfernt er, und jede (Rebe), die Frucht bringt, reinigt er, damit sie noch mehr Frucht bringe.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 15, 3, 'Ihr seid bereits rein infolge des Wortes, das ich zu euch geredet habe:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 15, 4, 'bleibt in mir, so bleibe ich in euch. Wie die Rebe nicht von sich selbst aus Frucht bringen kann, wenn sie nicht am Weinstock bleibt, so könnt auch ihr es nicht, wenn ihr nicht in mir bleibt.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 15, 5, 'Ich bin der Weinstock, ihr seid die Reben: wer in mir bleibt und in wem ich bleibe, der bringt reichlich Frucht; dagegen ohne mich könnt ihr nichts vollbringen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 15, 6, 'Wer nicht in mir bleibt, der wird weggeworfen wie die Rebe und verdorrt; man sammelt sie dann und wirft sie ins Feuer: da verbrennen sie.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 15, 7, 'Wenn ihr in mir bleibt und meine Worte in euch bleiben, dann bittet, um was ihr wollt: es wird euch zuteil werden.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 15, 8, 'Dadurch ist mein Vater verherrlicht, daß ihr reichlich Frucht bringt und euch als meine Jünger erweist.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 15, 9, '»Wie mich der Vater geliebt hat, so habe auch ich euch geliebt: bleibet in meiner Liebe!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 15, 10, 'Wenn ihr meine Gebote haltet, werdet ihr in meiner Liebe bleiben, gleichwie ich die Gebote meines Vaters gehalten habe und damit in seiner Liebe bleibe.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 15, 11, 'Dies habe ich zu euch geredet, damit die Freude, wie ich sie habe, auch in euch (vorhanden) sei und eure Freude vollkommen werde. –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 15, 12, 'Das ist mein Gebot, daß ihr einander liebt, wie ich euch geliebt habe.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 15, 13, 'Größere Liebe kann niemand haben als die, daß er sein Leben für seine Freunde hingibt.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 15, 14, 'Ihr seid meine Freunde, wenn ihr tut, was ich euch gebiete.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 15, 15, 'Ich nenne euch nicht mehr Knechte, denn der Knecht hat keine Einsicht in das Tun seines Herrn; vielmehr habe ich euch Freunde genannt, weil ich euch alles kundgetan habe, was ich von meinem Vater gehört habe.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 15, 16, 'Nicht ihr habt mich erwählt, sondern ich habe euch erwählt und euch dazu bestellt, daß ihr hingehen und Frucht bringen sollt und eure Frucht eine bleibende sei, auf daß der Vater euch alles gebe, um was ihr ihn in meinem Namen bittet.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 15, 17, 'Dies ist mein Gebot an euch, daß ihr einander liebet.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 15, 18, '»Wenn die Welt euch haßt, so bedenkt, daß sie mich noch eher als euch gehaßt hat!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 15, 19, 'Wenn ihr aus der Welt wärt, so würde die Welt euch als das zu ihr Gehörige lieben; weil ihr aber nicht aus der Welt seid, sondern ich euch aus der Welt heraus erwählt habe, deshalb haßt euch die Welt.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 15, 20, 'Gedenkt an das Wort, das ich euch gesagt habe: ›Ein Knecht steht nicht höher als sein Herr.‹ Haben sie mich verfolgt, so werden sie auch euch verfolgen; haben sie mein Wort befolgt, so werden sie auch das eure befolgen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 15, 21, 'Dies alles aber werden sie euch um meines Namens willen antun, weil sie den nicht kennen, der mich gesandt hat.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 15, 22, 'Wenn ich nicht gekommen wäre und nicht zu ihnen geredet hätte, so wären sie frei von Verschulden; so aber haben sie keine Entschuldigung für ihr Verschulden.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 15, 23, 'Wer mich haßt, der haßt auch meinen Vater.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 15, 24, 'Wenn ich nicht solche Werke unter ihnen getan hätte, wie kein anderer sie getan hat, so wären sie frei von Verschulden; so aber haben sie (alles) gesehen und doch sowohl mich als auch meinen Vater gehaßt.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 15, 25, 'Aber es muß das Wort, das in ihrem Gesetz geschrieben steht, erfüllt werden: ›Sie haben mich ohne Grund gehaßt.‹ –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 15, 26, 'Wenn aber der Helfer kommt, den ich euch vom Vater her senden werde, der Geist der Wahrheit, der vom Vater ausgeht, der wird Zeugnis über mich ablegen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 15, 27, 'Doch auch ihr seid (meine) Zeugen, weil ihr von Anfang an bei mir (gewesen) seid.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 16, 1, 'Dies habe ich euch gesagt, damit ihr nicht Anstoß nehmt.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 16, 2, 'Man wird euch in den Bann tun; ja, es kommt die Stunde, wo jeder, der euch tötet, Gott eine Opfergabe darzubringen meint.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 16, 3, 'Und so werden sie verfahren, weil sie weder den Vater noch mich erkannt haben.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 16, 4, 'Aber ich habe euch dies gesagt, damit, wenn die Stunde der Erfüllung kommt, ihr daran gedenkt, daß ich es euch gesagt habe.« »Dies habe ich euch aber nicht gleich anfangs gesagt, weil ich noch bei euch war.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 16, 5, 'Jetzt aber gehe ich hin zu dem, der mich gesandt hat, und keiner von euch fragt mich: ›Wohin gehst du?‹,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 16, 6, 'sondern weil ich dies zu euch gesagt habe, hat die Traurigkeit euer Herz erfüllt.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 16, 7, 'Aber ich sage euch die Wahrheit: Es ist gut für euch, daß ich weggehe. Denn wenn ich nicht weggehe, so wird der Helfer nicht zu euch kommen; wenn ich aber hingegangen bin, werde ich ihn zu euch senden.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 16, 8, 'Und wenn er gekommen ist, wird er der Welt die Augen öffnen über Sünde und über Gerechtigkeit und über Gericht:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 16, 9, 'über Sünde, (die darin besteht) daß sie nicht an mich glauben;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 16, 10, 'über Gerechtigkeit, (die darin besteht) daß ich zum Vater hingehe und ihr mich fortan nicht mehr seht;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 16, 11, 'über Gericht, (das darin besteht) daß der Fürst dieser Welt gerichtet ist.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 16, 12, 'Noch vieles hätte ich euch zu sagen, doch ihr könnt es jetzt nicht tragen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 16, 13, 'Wenn aber jener gekommen ist, der Geist der Wahrheit, der wird euch in die ganze Wahrheit einführen; denn er wird nicht von sich selbst aus reden, sondern was er hört, das wird er reden und euch das Zukünftige verkündigen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 16, 14, 'Er wird mich verherrlichen, denn von meinem Eigentum wird er es nehmen und euch verkündigen. Alles, was der Vater hat, ist mein;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 16, 15, 'deshalb habe ich gesagt, daß er es von meinem Eigentum nimmt und es euch verkündigen wird.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 16, 16, '»Nur noch eine kurze Zeit, so seht ihr mich nicht mehr; dann wieder eine kurze Zeit, so werdet ihr mich sehen.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 16, 17, 'Da sagten einige von seinen Jüngern zueinander: »Was meint er damit, daß er zu uns sagt: ›Nur noch eine kurze Zeit, so seht ihr mich nicht mehr; dann wieder eine kurze Zeit, so werdet ihr mich sehen‹, und weiter: ›Ich gehe hin zum Vater‹?«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 16, 18, 'Sie sagten also: »Was meint er mit dem Ausdruck ›eine kurze Zeit‹? Wir verstehen seine Worte nicht.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 16, 19, 'Jesus merkte, daß sie ihn darüber befragen wollten, und sagte zu ihnen: »Darüber verhandelt ihr miteinander, (was das zu bedeuten habe) daß ich gesagt habe: ›Nur noch eine kurze Zeit, so seht ihr mich nicht mehr, dann wieder eine kurze Zeit, so werdet ihr mich sehen‹?');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 16, 20, 'Wahrlich, wahrlich ich sage euch: ihr werdet weinen und wehklagen, die Welt aber wird sich freuen; ihr werdet traurig sein, doch eure Traurigkeit wird zur Freude werden.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 16, 21, 'Wenn eine Frau Mutter werden soll, so ist sie traurig, weil ihre Stunde gekommen ist; wenn sie aber das Kind geboren hat, denkt sie nicht mehr an die Angst um der Freude willen, daß ein Mensch in die Welt geboren ist.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 16, 22, 'So seid auch ihr jetzt in Traurigkeit; aber ich werde euch wiedersehen: dann wird euer Herz sich freuen, und niemand wird euch eure Freude rauben.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 16, 23, 'Und an jenem Tage werdet ihr mich um nichts mehr befragen. Wahrlich, wahrlich ich sage euch: Wenn ihr den Vater um etwas bitten werdet, so wird er es euch in meinem Namen geben.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 16, 24, 'Bisher habt ihr noch nie um etwas in meinem Namen gebeten: bittet, so werdet ihr empfangen, damit eure Freude vollkommen sei.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 16, 25, '»Dies habe ich euch in Gleichnissen verkündet; es kommt aber die Stunde, da werde ich nicht mehr in Gleichnissen zu euch reden, sondern euch mit voller Offenheit Kunde über den Vater geben.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 16, 26, 'An jenem Tage werdet ihr in meinem Namen bitten, und ich sage euch nicht, daß ich den Vater für euch bitten werde;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 16, 27, 'denn er selbst, der Vater, hat euch lieb, weil ihr mich geliebt und den Glauben gewonnen habt, daß ich von Gott ausgegangen bin.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 16, 28, 'Ich bin vom Vater ausgegangen und in die Welt gekommen; hinwiederum verlasse ich die Welt und kehre zum Vater zurück.« –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 16, 29, 'Da sagten seine Jünger: »Siehe, jetzt redest du frei heraus und gebrauchst keine bildliche Rede mehr;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 16, 30, 'jetzt wissen wir, daß du alles weißt und niemand dich erst zu befragen braucht; darum glauben wir, daß du von Gott ausgegangen bist.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 16, 31, 'Jesus antwortete ihnen: »Jetzt glaubt ihr?');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 16, 32, 'Wisset wohl: es kommt die Stunde, ja sie ist schon da, daß ihr euch zerstreuen werdet, ein jeder in das Seine, und ihr mich allein lassen werdet. Und doch bin ich (alsdann) nicht allein, denn der Vater ist bei mir.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 16, 33, 'Dies habe ich zu euch geredet, damit ihr in mir Frieden habet. In der Welt habt ihr Bedrängnis; doch seid getrost: ich habe die Welt überwunden!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 17, 1, 'So redete Jesus; dann richtete er seine Augen zum Himmel empor und betete: »Vater, die Stunde ist gekommen: verherrliche deinen Sohn, damit der Sohn dich verherrliche!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 17, 2, 'Du hast ihm ja Macht über alles Fleisch verliehen, damit er allen, die du ihm gegeben hast, ewiges Leben gebe.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 17, 3, 'Darin besteht aber das ewige Leben, daß sie dich, den allein wahren Gott, und den du gesandt hast, Jesus Christus, erkennen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 17, 4, 'Ich habe dich hier auf der Erde verherrlicht und habe das Werk vollendet, dessen Vollführung du mir aufgetragen hast.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 17, 5, 'Und jetzt verherrliche du mich, Vater, bei dir selbst mit der Herrlichkeit, die ich bei dir besaß, ehe die Welt war.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 17, 6, '»Ich habe deinen Namen den Menschen geoffenbart, die du mir aus der Welt gegeben hast. Dir gehörten sie an, und mir hast du sie gegeben, und sie haben dein Wort bewahrt.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 17, 7, 'Jetzt haben sie erkannt, daß alles, was du mir gegeben hast, von dir stammt;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 17, 8, 'denn die Worte, die du mir gegeben hast, habe ich ihnen gegeben, und sie haben sie angenommen und haben in Wahrheit erkannt, daß ich von dir ausgegangen bin, und haben den Glauben gewonnen, daß du es bist, der mich gesandt hat.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 17, 9, 'Ich bitte für sie; nicht für die Welt bitte ich, sondern für die, welche du mir gegeben hast; denn sie sind dein Eigentum,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 17, 10, 'und was mein ist, ist ja alles dein, und was dein ist, das ist mein, und ich bin in ihnen verherrlicht worden.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 17, 11, 'Und ich bin nicht mehr in der Welt, doch sie sind noch in der Welt, während ich zu dir gehe. Heiliger Vater, erhalte sie in deinem Namen, den du mir anvertraut hast, damit sie eins seien, so wie wir es sind.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 17, 12, 'Solange ich in ihrer Mitte gewesen bin, habe ich sie, die du mir gegeben hast, in deinem Namen erhalten und habe sie behütet, und keiner von ihnen ist verlorengegangen außer dem Sohne des Verderbens, damit die Schrift erfüllt würde.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 17, 13, 'Jetzt aber gehe ich zu dir und rede dieses noch in der Welt, damit sie die Freude, wie ich sie habe, vollkommen in sich tragen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 17, 14, 'Ich habe ihnen dein Wort gegeben, und die Welt hat sie gehaßt, weil sie nicht zur Welt gehören, wie auch ich nicht der Welt angehöre.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 17, 15, 'Ich bitte dich nicht, sie aus der Welt hinwegzunehmen, sondern sie vor dem Bösen zu behüten.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 17, 16, 'Sie gehören nicht zur Welt, wie auch ich nicht der Welt angehöre.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 17, 17, 'Heilige sie in deiner Wahrheit: dein Wort ist Wahrheit.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 17, 18, 'Wie du mich in die Welt gesandt hast, so habe auch ich sie in die Welt gesandt;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 17, 19, 'und für sie heilige ich mich, damit auch sie in Wahrheit geheiligt seien.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 17, 20, '»Ich bitte aber nicht für diese allein, sondern auch für die, welche durch ihr Wort zum Glauben an mich kommen (werden),');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 17, 21, 'daß sie alle eins seien; wie du, Vater, in mir bist und ich in dir bin, so laß auch sie in uns eins sein, damit die Welt glaube, daß du mich gesandt hast.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 17, 22, 'Ich habe auch die Herrlichkeit, die du mir gegeben hast, ihnen gegeben, damit sie eins seien, wie wir eins sind:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 17, 23, 'ich in ihnen und du in mir, auf daß sie zu vollkommener Einheit gelangen, damit die Welt erkenne, daß du mich gesandt und sie geliebt hast, wie du mich geliebt hast.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 17, 24, 'Vater, ich will, daß da, wo ich bin, auch die bei mir seien, die du mir gegeben hast, damit sie meine Herrlichkeit sehen, die du mir verliehen hast; denn du hast mich schon vor der Grundlegung der Welt geliebt.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 17, 25, 'Gerechter Vater, die Welt hat dich nicht erkannt, ich aber habe dich erkannt, und diese haben erkannt, daß du mich gesandt hast.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 17, 26, 'Und ich habe ihnen deinen Namen kundgetan und werde ihn (auch weiterhin) kundtun, damit die Liebe, mit der du mich geliebt hast, in ihnen sei und ich in ihnen.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 18, 1, 'Nachdem Jesus so gebetet hatte, ging er mit seinen Jüngern (aus der Stadt) hinaus über den Bach Kidron hinüber an einen Ort, wo ein Garten war, in den er mit seinen Jüngern eintrat.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 18, 2, 'Aber auch Judas, sein Verräter, kannte diesen Ort, weil Jesus dort oft mit seinen Jüngern zusammengekommen war.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 18, 3, 'Nachdem nun Judas die Abteilung Soldaten und von den Hohenpriestern und Pharisäern Diener erhalten hatte, kam er mit Fackeln, Laternen und Waffen dorthin.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 18, 4, 'Wiewohl nun Jesus alles wußte, was über ihn kommen würde, trat er doch (aus dem Garten) hinaus und fragte sie: »Wen sucht ihr?«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 18, 5, 'Sie antworteten ihm: »Jesus von Nazareth.« Er sagte zu ihnen: »Der bin ich.« Auch Judas, sein Verräter, stand bei ihnen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 18, 6, 'Als Jesus nun zu ihnen sagte: »Der bin ich!«, wichen sie zurück und fielen zu Boden.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 18, 7, 'Da fragte er sie nochmals: »Wen sucht ihr?« Sie sagten: »Jesus von Nazareth.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 18, 8, 'Jesus antwortete: »Ich habe euch gesagt, daß ich es bin. Wenn ihr also mich sucht, so laßt diese hier gehen!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 18, 9, 'So sollte sich das Wort erfüllen, das er ausgesprochen hatte: »Ich habe keinen von denen, die du mir gegeben hast, verloren gehen lassen.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 18, 10, 'Da nun Simon Petrus ein Schwert bei sich hatte, zog er es heraus, schlug damit nach dem Knechte des Hohenpriesters und hieb ihm das rechte Ohr ab; der Knecht hieß Malchus.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 18, 11, 'Da sagte Jesus zu Petrus: »Stecke das Schwert in die Scheide! Soll ich den Kelch nicht trinken, den mir der Vater gereicht hat?«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 18, 12, 'Hierauf nahmen die Abteilung Soldaten mit ihrem Hauptmann und die Diener der Juden Jesus fest, fesselten ihn');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 18, 13, 'und führten ihn zunächst zu Hannas ab; dieser war nämlich der Schwiegervater des Kaiphas, der in jenem Jahre Hoherpriester war.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 18, 14, 'Kaiphas aber war es, der den Juden den Rat gegeben hatte, es sei besser, daß ein einzelner Mensch für das Volk sterbe.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 18, 15, 'Simon Petrus aber und noch ein anderer Jünger waren Jesus nachgefolgt. Dieser (andere) Jünger war aber mit dem Hohenpriester bekannt und ging (deshalb) gleichzeitig mit Jesus in den Palast des Hohenpriesters hinein,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 18, 16, 'während Petrus draußen vor der Tür stehenblieb. Da ging der andere Jünger, der mit dem Hohenpriester bekannt war, hinaus, redete mit der Türhüterin und führte Petrus hinein.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 18, 17, 'Da sagte die Magd, welche die Tür hütete, zu Petrus: »Gehörst du nicht auch zu den Jüngern dieses Menschen?« Er antwortete: »Nein.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 18, 18, 'Es standen aber die Knechte und Diener da, hatten sich wegen der Kälte ein Kohlenfeuer angemacht und wärmten sich daran; aber auch Petrus stand bei ihnen und wärmte sich.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 18, 19, 'Der Hohepriester (Hannas) befragte nun Jesus über seine Jünger und seine Lehre.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 18, 20, 'Jesus antwortete ihm: »Ich habe frei und offen zu aller Welt geredet; ich habe allezeit in den Synagogen und im Tempel gelehrt, wo alle Juden zusammenkommen; im geheimen habe ich überhaupt nicht geredet.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 18, 21, 'Warum fragst du mich? Frage die, welche gehört haben, was ich zu ihnen geredet habe; diese wissen, was ich gesagt habe.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 18, 22, 'Als er das ausgesprochen hatte, gab einer von den Dienern, der dabeistand, Jesus einen Schlag ins Gesicht und sagte: »So antwortest du dem Hohenpriester?«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 18, 23, 'Jesus entgegnete ihm: »Wenn ich ungehörig gesprochen habe, so gib an, was ungehörig daran gewesen ist; wenn ich aber richtig gesprochen habe, warum schlägst du mich?«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 18, 24, 'Darauf sandte Hannas ihn gefesselt zum Hohenpriester Kaiphas.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 18, 25, 'Simon Petrus aber stand (unterdessen) da und wärmte sich. Da fragten sie ihn: »Gehörst du nicht auch zu seinen Jüngern?«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 18, 26, 'Er leugnete aber mit einem »Nein«. Da sagte einer von den Knechten des Hohenpriesters, ein Verwandter des Knechtes, dem Petrus das Ohr abgehauen hatte: »Habe ich dich nicht in dem Garten bei ihm gesehen?«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 18, 27, 'Da leugnete Petrus nochmals; und sogleich darauf krähte der Hahn.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 18, 28, 'Man führte Jesus dann aus dem Hause des Kaiphas nach der Statthalterei; es war früh am Morgen. Die Juden selbst gingen dabei nicht in die Statthalterei hinein, um nicht unrein zu werden, sondern das Passah essen zu können.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 18, 29, 'Darum kam Pilatus zu ihnen hinaus und fragte sie: »Welche Anklage habt ihr gegen diesen Mann zu erheben?«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 18, 30, 'Sie antworteten ihm mit den Worten: »Wenn dieser Mensch kein Verbrecher wäre, so hätten wir ihn dir nicht überliefert!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 18, 31, 'Da sagte Pilatus zu ihnen: »Nehmt ihr ihn und richtet ihn nach eurem Gesetz.« Da entgegneten ihm die Juden: »Wir haben nicht das Recht, jemand hinzurichten« –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 18, 32, 'so sollte sich das Wort Jesu erfüllen, durch das er die Art seines Todes angedeutet hatte.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 18, 33, 'Pilatus ging nun wieder in die Statthalterei hinein, ließ Jesus rufen und fragte ihn: »Bist du der König der Juden?«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 18, 34, 'Jesus antwortete: »Fragst du so von dir selbst aus, oder haben andere es dir von mir gesagt?«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 18, 35, 'Pilatus antwortete: »Ich bin doch kein Jude! Dein Volk und zwar die Hohenpriester haben dich mir überantwortet: was hast du verbrochen?«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 18, 36, 'Jesus antwortete: »Mein Reich ist nicht von dieser Welt. Wäre mein Reich von dieser Welt, so würden meine Diener (für mich) kämpfen, damit ich den Juden nicht überliefert würde; nun aber ist mein Reich nicht von hier.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 18, 37, 'Da sagte Pilatus zu ihm: »Ein König bist du also?« Jesus antwortete: »Ja, ich bin ein König. Ich bin dazu geboren und dazu in die Welt gekommen, um für die Wahrheit Zeugnis abzulegen; jeder, der aus der Wahrheit ist, hört auf meine Stimme.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 18, 38, 'Darauf antwortete ihm Pilatus: »Was ist Wahrheit?!« Nach diesen Worten ging er wieder zu den Juden hinaus und sagte zu ihnen: »Ich finde keinerlei Schuld an ihm.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 18, 39, 'Es ist aber herkömmlich bei euch, daß ich euch am Passah einen (Gefangenen) freigebe: soll ich euch also den König der Juden freigeben?«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 18, 40, 'Da riefen sie wieder laut: »Nein, nicht diesen, sondern den Barabbas!« Barabbas war aber ein Räuber.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 19, 1, 'Da ließ nun Pilatus Jesus ergreifen und geißeln;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 19, 2, 'dann flochten die Soldaten eine Dornenkrone, setzten sie ihm aufs Haupt und legten ihm einen scharlachroten Mantel um;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 19, 3, 'hierauf traten sie vor ihn hin und riefen aus: »Sei gegrüßt, Judenkönig!« und versetzten ihm Schläge ins Gesicht.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 19, 4, 'Pilatus kam dann wieder heraus und sagte zu ihnen: »Seht, ich führe ihn zu euch heraus, damit ihr erkennt, daß ich keinerlei Schuld an ihm finde.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 19, 5, 'So kam denn Jesus heraus, indem er die Dornenkrone und den Purpurmantel trug, und Pilatus sagte zu ihnen: »Seht, der Mensch!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 19, 6, 'Als ihn nun die Hohenpriester und die Tempeldiener erblickten, schrien sie: »Ans Kreuz mit ihm, ans Kreuz!« Pilatus entgegnete ihnen: »Nehmt ihr ihn und kreuzigt ihn! Denn ich finde keine Schuld an ihm.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 19, 7, 'Die Juden antworteten ihm: »Wir haben ein Gesetz, und nach diesem Gesetz muß er sterben, weil er sich selbst zu Gottes Sohn gemacht hat.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 19, 8, 'Als nun Pilatus dies Wort hörte, geriet er in noch größere Angst;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 19, 9, 'er ging also wieder in die Statthalterei hinein und fragte Jesus: »Woher bist du?« Jesus aber gab ihm keine Antwort.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 19, 10, 'Da sagte Pilatus zu ihm: »Mir willst du nicht Rede stehen? Weißt du nicht, daß ich die Macht habe, dich freizugeben, und auch die Macht habe, dich kreuzigen zu lassen?«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 19, 11, 'Jesus antwortete ihm: »Du hättest keine Macht über mich, wenn sie dir nicht von oben her gegeben wäre; deshalb trifft den, welcher mich dir ausgeliefert hat, eine größere Schuld.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 19, 12, 'Von da an suchte Pilatus ihn freizugeben; aber die Juden schrien: »Gibst du diesen frei, so bist du kein Freund des Kaisers! Jeder, der sich selbst zum König macht, lehnt sich gegen den Kaiser auf!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 19, 13, 'Als Pilatus diese Worte hörte, ließ er Jesus hinausführen und setzte sich auf den Richterstuhl an dem Platze, welcher ›Steinpflaster‹, auf hebräisch Gabbatha, heißt.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 19, 14, 'Es war aber der Rüsttag auf das Passahfest, und zwar um die sechste Stunde. Nun sagte Pilatus zu den Juden: »Seht, da ist euer König!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 19, 15, 'Da schrien jene: »Weg, weg mit ihm, kreuzige ihn!« Pilatus entgegnete ihnen: »Euren König soll ich kreuzigen lassen?« Die Hohenpriester antworteten: »Wir haben keinen König als den Kaiser!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 19, 16, 'a Darauf übergab er ihnen Jesus zur Kreuzigung. b So übernahmen sie denn Jesus;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 19, 17, 'und dieser ging, indem er sein Kreuz selber trug, (aus der Stadt) hinaus nach der sogenannten ›Schädelstätte‹, die auf hebräisch Golgatha heißt;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 19, 18, 'dort kreuzigten sie ihn und mit ihm noch zwei andere auf beiden Seiten, Jesus aber in der Mitte.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 19, 19, 'Auch eine Aufschrift hatte Pilatus schreiben und oben am Kreuz anbringen lassen; sie lautete: »Jesus von Nazareth, der König der Juden.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 19, 20, 'Diese Aufschrift nun lasen viele von den Juden, weil der Platz, wo Jesus gekreuzigt wurde, nahe bei der Stadt lag und die Aufschrift in hebräischer, römischer und griechischer Sprache abgefaßt war.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 19, 21, 'Da sagten die Hohenpriester der Juden zu Pilatus: »Schreibe nicht: ›Der König der Juden‹, sondern: ›Dieser Mensch hat behauptet, er sei der König der Juden‹!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 19, 22, 'Pilatus (aber) antwortete: »Was ich geschrieben habe, das habe ich geschrieben!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 19, 23, 'Als nun die Soldaten Jesus gekreuzigt hatten, nahmen sie seine Kleidungsstücke und machten vier Teile daraus, für jeden Soldaten einen Teil, außerdem noch das Unterkleid. Dieses Unterkleid war aber ohne Naht, von oben an in einem Stück gewebt.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 19, 24, 'Da sagten sie zueinander: »Wir wollen es nicht zerschneiden, sondern darum losen, wem es gehören soll« – so sollte das Schriftwort seine Erfüllung finden: »Sie haben meine Kleider unter sich verteilt und über mein Gewand das Los geworfen.« Auf diese Weise verfuhren also die Soldaten.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 19, 25, 'Es standen aber beim Kreuze Jesu seine Mutter und die Schwester seiner Mutter, auch Maria, die Frau des Klopas, und Maria von Magdala.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 19, 26, 'Als nun Jesus seine Mutter und neben ihr den Jünger, den er (besonders) lieb hatte, stehen sah, sagte er zu seiner Mutter: »Frau, siehe dein Sohn!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 19, 27, 'Darauf sagte er zu dem Jünger: »Siehe deine Mutter!« Und von dieser Stunde an nahm der Jünger sie zu sich in sein Haus.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 19, 28, 'Darauf, weil Jesus wußte, daß nunmehr alles vollbracht war, sagte er, damit die Schrift ganz erfüllt würde: »Mich dürstet.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 19, 29, 'Es stand dort nun ein mit Essig gefülltes Gefäß. Sie umwickelten also einen mit dem Essig getränkten Schwamm mit Ysop und hielten ihm diesen an den Mund.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 19, 30, 'Als nun Jesus den Essig genommen hatte, sagte er: »Es ist vollbracht!«, neigte dann das Haupt und gab den Geist auf.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 19, 31, 'Weil es nun Rüsttag war, trugen die Juden, damit die Leichen nicht während des Sabbats am Kreuz blieben – dieser Sabbattag war nämlich ein hoher Festtag –, dem Pilatus die Bitte vor, es möchten ihnen die Schenkel mit Keulen zerschlagen und sie dann (vom Kreuz) herabgenommen werden.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 19, 32, 'So kamen denn die Soldaten und zerschlugen dem ersten die Schenkel, ebenso auch dem andern, der mit (Jesus) gekreuzigt worden war.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 19, 33, 'Als sie aber zu Jesus kamen und sahen, daß er bereits tot war, zerschlugen sie ihm die Schenkel nicht,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 19, 34, 'sondern einer von den Soldaten stieß ihn mit seiner Lanze in die Seite; da floß sogleich Blut und Wasser heraus.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 19, 35, 'Ein Augenzeuge hat dies bezeugt, und sein Zeugnis ist zuverlässig, und jener weiß, daß er die Wahrheit sagt, damit auch ihr zum Glauben kommet.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 19, 36, 'Dies ist nämlich geschehen, damit das Schriftwort erfüllt würde: »Es soll kein Knochen an ihm zerbrochen werden.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 19, 37, 'Und noch eine andere Schriftstelle lautet: »Sie werden auf den blicken, den sie durchbohrt haben.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 19, 38, 'Hierauf trug Joseph von Arimathäa, der ein Jünger Jesu war – allerdings war er’s nur im geheimen aus Furcht vor den Juden –, dem Pilatus die Bitte vor, daß er den Leichnam Jesu vom Kreuze abnehmen dürfe; und Pilatus gewährte ihm die Bitte. So ging er denn hin und nahm seinen Leichnam (vom Kreuz) ab.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 19, 39, 'Aber auch Nikodemus kam, derselbe, der zum erstenmal bei Nacht zu Jesus gekommen war, und brachte eine Mischung von Myrrhe und Aloe mit, wohl hundert Pfund.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 19, 40, 'So nahmen sie denn den Leib Jesu und banden ihn ein in Leinwandstreifen mitsamt den wohlriechenden Stoffen, wie es Sitte der Juden bei Bestattungen ist.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 19, 41, 'Es lag aber bei dem Platze, wo er gekreuzigt worden war, ein Garten, und in dem Garten (befand sich) ein neues Grab, in welchem bisher noch niemand beigesetzt worden war.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 19, 42, 'Dorthin brachten sie nun Jesus mit Rücksicht auf den jüdischen Rüsttag, weil das Grab sich in der Nähe befand.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 20, 1, 'Am ersten Tage nach dem Sabbat aber ging Maria Magdalena frühmorgens, als es noch dunkel war, zum Grabe hin und sah, daß der Stein vom Grabe weggenommen war.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 20, 2, 'Da eilte sie hin und kam zu Simon Petrus und zu dem anderen Jünger, den Jesus (besonders) lieb gehabt hatte, und sagte zu ihnen: »Man hat den Herrn aus dem Grabe weggenommen, und wir wissen nicht, wohin man ihn gelegt hat!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 20, 3, 'Da gingen Petrus und der andere Jünger hinaus und machten sich auf den Weg zum Grabe.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 20, 4, 'Die beiden liefen miteinander, doch der andere Jünger lief voraus, schneller als Petrus, und kam zuerst an das Grab.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 20, 5, 'Als er sich nun hineinbeugte, sah er die leinenen Binden daliegen, ging jedoch nicht hinein.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 20, 6, 'Nun kam auch Simon Petrus hinter ihm her und trat in das Grab hinein; er sah dort die leinenen Binden liegen,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 20, 7, 'das Schweißtuch aber, das auf seinem Kopf gelegen hatte, lag nicht bei den (anderen) Leintüchern, sondern für sich zusammengefaltet an einer besonderen Stelle.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 20, 8, 'Jetzt trat auch der andere Jünger hinein, der zuerst am Grabe angekommen war, und sah es auch und kam zum Glauben;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 20, 9, 'denn sie hatten die Schrift noch nicht verstanden, daß er von den Toten auferstehen müsse.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 20, 10, 'So gingen denn die (beiden) Jünger wieder heim.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 20, 11, 'Maria aber war draußen am Grabe stehengeblieben und weinte. Mit Tränen in den Augen beugte sie sich vor in das Grab hinein;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 20, 12, 'da sah sie dort zwei Engel in weißen Gewändern dasitzen, den einen am Kopfende, den andern am Fußende der Stelle, wo der Leichnam Jesu gelegen hatte.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 20, 13, 'Diese sagten zu ihr: »Frau, warum weinst du?« Sie antwortete ihnen: »Man hat meinen Herrn weggenommen, und ich weiß nicht, wohin man ihn gelegt hat.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 20, 14, 'Nach diesen Worten wandte sie sich um und sah Jesus dastehen, wußte aber nicht, daß es Jesus war.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 20, 15, 'Da sagte Jesus zu ihr: »Frau, warum weinst du? Wen suchst du?« Sie hielt ihn für den Hüter des Gartens und sagte zu ihm: »Herr, wenn du ihn weggetragen hast, so sage mir doch, wohin du ihn gebracht hast; dann will ich ihn wieder holen.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 20, 16, 'Jesus sagte zu ihr: »Maria!« Da wandte sie sich um und sagte auf hebräisch zu ihm: »Rabbuni!«, das heißt »Meister«.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 20, 17, 'Jesus sagte zu ihr: »Rühre mich nicht an, denn ich bin noch nicht zum Vater aufgefahren! Gehe aber zu meinen Brüdern und sage ihnen: ›Ich fahre auf zu meinem Vater und eurem Vater, zu meinem Gott und eurem Gott.‹«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 20, 18, 'Da ging Maria Magdalena hin und verkündigte den Jüngern, sie habe den Herrn gesehen, und er habe dies zu ihr gesagt.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 20, 19, 'Als es nun an jenem Tage, dem ersten Wochentage, Abend geworden war und die Türen an dem Ort, wo die Jünger sich befanden, aus Furcht vor den Juden verschlossen waren, kam Jesus, trat mitten unter sie und sagte zu ihnen: »Friede sei mit euch!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 20, 20, 'Nach diesen Worten zeigte er ihnen seine Hände und seine Seite; da freuten sich die Jünger, weil sie den Herrn sahen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 20, 21, 'Dann sagte er nochmals zu ihnen: »Friede sei mit euch! Wie mich der Vater gesandt hat, so sende auch ich euch.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 20, 22, 'Nach diesen Worten hauchte er sie an und sagte zu ihnen: »Empfanget heiligen Geist!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 20, 23, 'Wem immer ihr die Sünden vergebt, dem sind sie vergeben, und wem ihr sie behaltet, dem sind sie behalten.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 20, 24, 'Thomas aber, einer von den Zwölfen, der auch den Namen ›Zwilling‹ führt, war nicht bei ihnen gewesen, als Jesus gekommen war.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 20, 25, 'Die anderen Jünger teilten ihm nun mit: »Wir haben den Herrn gesehen!« Er aber erklärte ihnen: »Wenn ich nicht das Nägelmal in seinen Händen sehe und meinen Finger in das Nägelmal und meine Hand in seine Seite lege, werde ich es nimmermehr glauben!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 20, 26, 'Acht Tage später befanden sich seine Jünger wieder im Hause, und (diesmal) war Thomas bei ihnen. Da kam Jesus bei verschlossenen Türen, trat mitten unter sie und sagte: »Friede sei mit euch!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 20, 27, 'Darauf sagte er zu Thomas: »Reiche deinen Finger her und sieh dir meine Hände an; dann reiche deine Hand her und lege sie mir in die Seite und sei nicht (länger) ungläubig, sondern werde gläubig!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 20, 28, 'Da antwortete ihm Thomas: »Mein Herr und mein Gott!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 20, 29, 'Jesus erwiderte ihm: »Weil du mich gesehen hast, bist du gläubig geworden. Selig sind die, welche nicht gesehen haben und doch zum Glauben gekommen sind!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 20, 30, 'Noch viele andere Wunderzeichen hat Jesus vor den Augen seiner Jünger getan, die in diesem Buche nicht aufgezeichnet stehen;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 20, 31, 'diese aber sind niedergeschrieben worden, damit ihr glaubt, daß Jesus der Gesalbte, der Sohn Gottes ist, und damit ihr durch den Glauben Leben in seinem Namen habt.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 21, 1, 'Danach offenbarte Jesus sich seinen Jüngern noch einmal am See von Tiberias, und zwar offenbarte er sich auf folgende Weise:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 21, 2, 'Es waren beisammen Simon Petrus und Thomas, der den Namen ›Zwilling‹ führt, Nathanael aus Kana in Galiläa, die (beiden) Söhne des Zebedäus und noch zwei andere aus der Zahl seiner Jünger.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 21, 3, 'Da sagte Simon Petrus zu ihnen: »Ich gehe hin und fische!« Sie erwiderten ihm: »Dann gehen auch wir mit dir!« So gingen sie denn hinaus und stiegen in das Boot, fingen aber in jener Nacht nichts.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 21, 4, 'Als es bereits gegen Morgen war, stand Jesus am Ufer; die Jünger wußten jedoch nicht, daß es Jesus war.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 21, 5, 'Da rief Jesus ihnen zu: »Kinder, habt ihr nicht etwas (Fisch) als Zukost?« Sie antworteten ihm: »Nein.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 21, 6, 'Nun sagte er zu ihnen: »Werft das Netz nach der rechten Seite des Bootes aus, so werdet ihr einen Fang tun!« Da warfen sie es aus und konnten es vor der Menge der Fische nicht mehr (aus dem Wasser) herausziehen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 21, 7, 'Da sagte jener Jünger, den Jesus (besonders) lieb hatte, zu Petrus: »Es ist der Herr!« Als nun Simon Petrus hörte, daß es der Herr sei, gürtete er sich sein Obergewand um – er hatte nämlich nur ein Unterkleid angehabt – und sprang in den See;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 21, 8, 'die anderen Jünger aber kamen mit dem Boote hinter ihm her – sie waren nämlich nicht weit vom Lande, sondern nur in einer Entfernung von etwa zweihundert Ellen – und zogen das Netz mit den Fischen hinter sich her.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 21, 9, 'Als sie dann ans Land ausgestiegen waren, sahen sie ein Kohlenfeuer (am Boden) hergerichtet und Fische darauf gelegt und Brot (daneben).');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 21, 10, 'Jesus sagte zu ihnen: »Bringt noch einige von den Fischen her, die ihr soeben gefangen habt!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 21, 11, 'Da stieg Simon Petrus (in das Boot) hinein und zog das Netz ans Land, das mit hundertunddreiundfünfzig großen Fischen gefüllt war und trotz dieser großen Zahl nicht zerriß.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 21, 12, 'Nun sagte Jesus zu ihnen: »Kommt her und haltet das Frühmahl!« Keiner aber von den Jüngern wagte die Frage an ihn zu richten: »Wer bist du?« Sie wußten ja, daß es der Herr war.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 21, 13, 'Jesus trat nun hin, nahm das Brot und gab es ihnen, ebenso auch die Fische.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 21, 14, 'Dies war nun schon das dritte Mal, daß Jesus sich nach seiner Auferstehung von den Toten seinen Jüngern offenbarte.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 21, 15, 'Als sie nun das Frühmahl gehalten hatten, sagte Jesus zu Simon Petrus: »Simon, Sohn des Johannes, liebst du mich mehr als diese?« Er antwortete ihm: »Ja, Herr, du weißt, daß ich dich lieb habe.« Da sagte er zu ihm: »Weide meine Lämmer!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 21, 16, 'Darauf fragte ihn Jesus zum zweitenmal: »Simon, Sohn des Johannes, liebst du mich?« Er antwortete ihm: »Ja, Herr, du weißt, daß ich dich lieb habe.« Da sagte Jesus zu ihm: »Hüte meine Schafe!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 21, 17, 'Zum drittenmal fragte er ihn: »Simon, Sohn des Johannes, hast du mich lieb?« Da wurde Petrus betrübt, weil er ihn zum drittenmal fragte: »Hast du mich lieb?«, und er antwortete ihm: »Herr, du weißt alles; du weißt auch, daß ich dich lieb habe.« Da sagte Jesus zu ihm: »Weide meine Schafe!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 21, 18, 'Wahrlich, wahrlich ich sage dir: Als du noch jünger warst, hast du dir dein Gewand selbst gegürtet und bist umhergegangen, wohin du wolltest; wenn du aber alt geworden bist, wirst du deine Arme ausstrecken, und ein anderer wird dich gürten und dich an eine Stätte führen, wohin du nicht willst.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 21, 19, 'Dies sagte er aber, um anzudeuten, durch was für eine Todesart Petrus Gott verherrlichen würde. Nach diesen Worten sagte er zu ihm: »Folge mir nach!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 21, 20, 'Als Petrus sich dann umwandte, sah er den Jünger, den Jesus (besonders) liebhatte, hinter ihnen herkommen, denselben, der sich auch beim Abendmahl an seine Brust gelehnt und gefragt hatte: »Herr, wer ist’s, der dich verrät?«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 21, 21, 'Als nun Petrus diesen sah, fragte er Jesus: »Herr, was wird aber mit diesem werden?«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 21, 22, 'Jesus antwortete ihm: »Wenn es mein Wille ist, daß er bis zu meinem Kommen (am Leben) bleibt, was geht das dich an? Folge du mir nach!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 21, 23, 'So verbreitete sich denn diese Rede unter den Brüdern: »Jener Jünger stirbt nicht.« Aber Jesus hatte zu ihm nicht gesagt: »Er stirbt nicht«, sondern: »Wenn es mein Wille ist, daß er bis zu meinem Kommen (am Leben) bleibt, was geht das dich an?«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 21, 24, 'Dies ist der Jünger, der von diesen Dingen Zeugnis ablegt und auch diese Schrift verfaßt hat, und wir wissen, daß sein Zeugnis wahr ist.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 21, 25, 'Es gibt aber noch vieles andere, was Jesus getan hat; wollte man das alles im einzelnen aufschreiben, so würde nach meiner Überzeugung die Welt die Bücher nicht fassen, die dann zu schreiben wären.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 1, 1, 'Meinen ersten Bericht habe ich, lieber Theophilus, über alles das verfaßt, was Jesus getan und gelehrt hat von Anfang an');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 1, 2, 'bis zu dem Tage, an dem er den Aposteln, die er erwählt hatte, durch den heiligen Geist seine (letzten) Aufträge erteilte und dann (in den Himmel) aufgenommen wurde.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 1, 3, 'Ihnen hatte er sich auch nach seinem Leiden durch viele Beweise als lebendig bezeugt, indem er sich vierzig Tage lang vor ihnen sehen ließ und mit ihnen über das Reich Gottes redete.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 1, 4, 'Als er so mit ihnen zusammen war, gebot er ihnen, sich von Jerusalem nicht zu entfernen, sondern (dort) die (Erfüllung der) Verheißung des Vaters abzuwarten, »die ihr« – so lauteten seine Worte – »von mir vernommen habt;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 1, 5, 'denn Johannes hat (nur) mit Wasser getauft, ihr aber werdet mit heiligem Geist getauft werden, und zwar nicht lange nach diesen Tagen.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 1, 6, 'Da fragten ihn die dort Versammelten: »Herr, stellst du in dieser Zeit das Königtum für (das Volk) Israel wieder her?«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 1, 7, 'Er antwortete ihnen: »Euch kommt es nicht zu, Zeiten und Fristen zu wissen, die der Vater vermöge seiner eigenen Machtvollkommenheit festgesetzt hat.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 1, 8, 'Ihr werdet jedoch Kraft empfangen, wenn der heilige Geist auf euch kommt, und ihr werdet Zeugen für mich sein in Jerusalem und in ganz Judäa und Samaria und bis ans Ende der Erde.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 1, 9, 'Nach diesen Worten wurde er vor ihren Augen emporgehoben: eine Wolke nahm ihn auf und entzog ihn ihren Blicken;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 1, 10, 'und als sie ihm noch unverwandt nachschauten, während er zum Himmel auffuhr, standen mit einemmal zwei Männer in weißen Gewändern bei ihnen,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 1, 11, 'die sagten: »Ihr Männer aus Galiläa, was steht ihr da und blickt zum Himmel empor? Dieser Jesus, der aus eurer Mitte in den Himmel emporgehoben worden ist, wird in derselben Weise kommen, wie ihr ihn in den Himmel habt auffahren sehen!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 1, 12, 'Darauf kehrten sie von dem sogenannten Ölberge, der nahe bei Jerusalem liegt und nur einen Sabbatweg entfernt ist, nach Jerusalem zurück.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 1, 13, 'Als sie dort angekommen waren, gingen sie in das Obergemach (des Hauses) hinauf, wo sie sich aufzuhalten pflegten, nämlich Petrus und Johannes und Jakobus und Andreas, Philippus und Thomas, Bartholomäus und Matthäus, Jakobus, der Sohn des Alphäus, und Simon der Eiferer und Judas, der Sohn des Jakobus.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 1, 14, 'Diese alle waren dort einmütig und andauernd im Gebet vereinigt samt (einigen) Frauen, besonders auch mit Maria, der Mutter Jesu, und mit seinen Brüdern.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 1, 15, 'In diesen Tagen nun trat Petrus im Kreise der Brüder auf – es war aber eine Schar von ungefähr einhundertundzwanzig Personen versammelt – und sagte:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 1, 16, '»Liebe Brüder, das Schriftwort mußte erfüllt werden, das der heilige Geist durch den Mund Davids im voraus ausgesprochen hat über Judas, der denen, die Jesus gefangen nahmen, als Führer gedient hat;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 1, 17, 'und er gehörte doch zu unserer Zahl und hatte Anteil an diesem Dienst mit uns empfangen!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 1, 18, 'Dieser hat sich nun zwar von seinem Sündenlohn einen Acker gekauft, ist aber kopfüber zu Boden gestürzt und mitten auseinander geborsten, so daß alle seine Eingeweide herausgetreten sind.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 1, 19, 'Dies ist allen Einwohnern Jerusalems bekannt geworden, so daß auch jener Acker in ihrer Sprache den Namen Hakeldamach, das heißt ›Blutacker‹, erhalten hat.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 1, 20, 'Denn im Psalmbuch steht geschrieben: ›Seine Behausung soll öde werden und kein Bewohner darin sein‹, und ferner: ›Sein Aufseheramt soll ein anderer übernehmen.‹');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 1, 21, 'Es muß also einer von den Männern, die mit uns zusammen gezogen sind während der ganzen Zeit, in welcher der Herr Jesus bei uns ein- und ausgegangen ist,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 1, 22, 'nämlich von der Taufe des Johannes an bis zu dem Tage, an dem er aus unserer Mitte hinweg (zum Himmel) emporgehoben worden ist – einer von diesen muß ein Zeuge seiner Auferstehung im Verein mit uns werden.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 1, 23, 'So stellten sie denn zwei Männer auf: Joseph, genannt Barsabbas, der den Beinamen Justus führte, und Matthias.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 1, 24, 'Dann beteten sie mit den Worten: »Du, o Herr, der du die Herzen aller kennst, zeige du (uns) den einen an, den du von diesen beiden erwählt hast,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 1, 25, 'damit er die Stelle in diesem Dienst und Apostelamt übernehme, aus welchem Judas abgetreten ist, um an den ihm gebührenden Platz zu kommen!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 1, 26, 'Hierauf teilte man ihnen Lose zu, und das Los fiel auf Matthias, der nunmehr den elf Aposteln zugeordnet wurde.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 2, 1, 'Als dann der Tag des Pfingstfestes herbeigekommen war, befanden sie alle sich an einem Ort beisammen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 2, 2, 'Da entstand plötzlich ein Brausen vom Himmel her, wie wenn ein gewaltiger Wind daherfährt, und erfüllte das ganze Haus, in welchem sie weilten;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 2, 3, 'und es erschienen ihnen Zungen wie von Feuer, die sich (in Flämmchen) zerteilten und von denen sich eine auf jeden von ihnen niederließ;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 2, 4, 'und sie wurden alle mit heiligem Geist erfüllt und begannen in anderen Zungen zu reden, wie der Geist es ihnen eingab auszusprechen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 2, 5, 'Nun waren aber Juden in Jerusalem wohnhaft, gottesfürchtige Männer aus allen Völkern unter dem Himmel.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 2, 6, 'Als nun dieses Brausen erfolgt war, kamen sie in großer Zahl zusammen und gerieten in Bestürzung; denn jeder hörte sie in seiner eigenen Sprache reden.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 2, 7, 'Da wurden sie alle betroffen und fragten voll Verwunderung: »Sind nicht diese alle, die da reden, aus Galiläa?');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 2, 8, 'Wie kommt es denn, daß wir ein jeder sie in unserer eigenen Sprache reden hören, in der wir geboren sind:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 2, 9, 'Parther, Meder und Elamiter und wir Bewohner von Mesopotamien, von Judäa und Kappadocien, von Pontus und (der Provinz) Asien,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 2, 10, 'von Phrygien und Pamphylien, von Ägypten und der Landschaft Libyen bei Cyrene, auch die hier ansässigen Römer,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 2, 11, 'geborene Juden und Judengenossen, Kreter und Araber – wir hören sie mit unsern Zungen die großen Taten Gottes verkünden!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 2, 12, 'So waren sie alle betroffen und ratlos und sagten einer zum anderen: »Was hat das zu bedeuten?«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 2, 13, 'Andere aber spotteten und sagten: »Sie sind voll süßen Weins!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 2, 14, 'Da trat Petrus im Verein mit den Elfen auf und redete sie mit laut erhobener Stimme so an: »Ihr jüdischen Männer und ihr anderen alle, die ihr in Jerusalem wohnt: dies sei euch kundgetan und schenkt meinen Worten Gehör!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 2, 15, 'Diese Männer hier sind nicht betrunken, wie ihr meint – es ist ja erst die dritte Stunde des Tages –,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 2, 16, 'nein, hier erfüllt sich die Verheißung des Propheten Joel (3,1-5):');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 2, 17, '›In den letzten Tagen wird es geschehen, spricht Gott, da werde ich von meinem Geist auf alles Fleisch ausgießen, so daß eure Söhne und eure Töchter prophetisch reden und eure jungen Männer Gesichte schauen und eure Greise Offenbarungen in Träumen empfangen;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 2, 18, 'ja, sogar auf meine Knechte und auf meine Mägde werde ich in jenen Tagen von meinem Geist ausgießen, so daß sie prophetisch reden.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 2, 19, 'Und ich werde Wunderzeichen erscheinen lassen oben am Himmel und Wahrzeichen unten auf der Erde: Blut und Feuer und Rauchwolken.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 2, 20, 'Die Sonne wird sich in Finsternis verwandeln und der Mond in Blut, bevor der Tag des Herrn kommt, der große und herrliche.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 2, 21, 'Und es wird geschehen: Jeder, der den Namen des Herrn anruft, wird gerettet werden.‹«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 2, 22, '»Ihr Männer von Israel, vernehmt diese Worte! Jesus von Nazareth, einen Mann, der als Gottgesandter durch Machttaten, Wunder und Zeichen, die Gott durch ihn in eurer Mitte getan hat, wie ihr selbst wißt, vor euch erwiesen worden ist –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 2, 23, 'diesen Mann, der nach dem festgesetzten Ratschluß und der Vorherbestimmung Gottes euch preisgegeben war, habt ihr durch die Hand der Gesetzlosen ans Kreuz nageln und hinrichten lassen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 2, 24, 'Gott aber hat ihn auferweckt, indem er die Wehen des Todes löste, weil er ja unmöglich vom Tode festgehalten werden konnte.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 2, 25, 'David sagt ja mit Bezug auf ihn: ›Ich habe den Herrn allezeit vor meinen Augen gesehen, denn er steht mir zur Rechten, damit ich nicht wanke.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 2, 26, 'Deshalb freute sich mein Herz, und meine Zunge frohlockte; zudem wird auch mein Leib in Hoffnung ruhen;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 2, 27, 'denn du wirst meine Seele nicht im Totenreich belassen und nicht zugeben, daß dein Heiliger die Verwesung sieht.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 2, 28, 'Du hast mir Wege des Lebens kundgetan; du wirst mich mit Freude erfüllen vor deinem Angesicht.‹');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 2, 29, 'Werte Brüder! Ich darf mit Freimütigkeit zu euch vom Erzvater David reden: er ist gestorben und ist begraben worden, und sein Grabmal befindet sich bis auf den heutigen Tag hier bei uns.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 2, 30, 'Weil er nun ein Prophet war und wußte, daß Gott ihm mit einem Eide zugeschworen hatte, es solle einer von seinen leiblichen Nachkommen auf seinem Throne sitzen,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 2, 31, 'so hat er vorausschauend von der Auferstehung Christi geredet, daß dieser nämlich weder dem Totenreich überlassen worden ist noch sein Leib die Verwesung gesehen hat.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 2, 32, 'Diesen Jesus hat Gott auferweckt: dafür sind wir alle Zeugen!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 2, 33, 'Nachdem er nun durch die Rechte Gottes erhöht worden ist und den verheißenen heiligen Geist empfangen hat vom Vater, hat er jetzt diesen (Geist), wie ihr selbst seht und hört, hier ausgegossen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 2, 34, 'Denn nicht David ist in die Himmel hinaufgefahren; wohl aber sagt er selbst: ›Der Herr hat zu meinem Herrn gesagt: Setze dich zu meiner Rechten,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 2, 35, 'bis ich deine Feinde hinlege zum Schemel deiner Füße!‹');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 2, 36, 'So möge denn das ganze Haus Israel mit Sicherheit erkennen, daß Gott ihn zum Herrn und zum Christus gemacht hat, eben diesen Jesus, den ihr gekreuzigt habt!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 2, 37, 'Als sie das hörten, ging es ihnen wie ein Stich durchs Herz, und sie wandten sich an Petrus und die anderen Apostel mit der Frage: »Was sollen wir tun, werte Brüder?«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 2, 38, 'Da antwortete ihnen Petrus: »Tut Buße und laßt euch ein jeder auf den Namen Jesu Christi zur Vergebung eurer Sünden taufen, dann werdet ihr die Gabe des heiligen Geistes empfangen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 2, 39, 'Denn euch gilt die Verheißung und euren Kindern und allen, die noch fern stehen, soviele ihrer der Herr, unser Gott, berufen wird.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 2, 40, 'Auch noch mit vielen anderen Worten redete er ihnen eindringlich zu und ermahnte sie: »Laßt euch aus diesem verkehrten Geschlecht erretten!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 2, 41, 'Die nun sein Wort annahmen, ließen sich taufen, und so kamen an jenem Tage etwa dreitausend Seelen (zu der Gemeinde) hinzu.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 2, 42, 'Sie hielten aber beharrlich fest an der Lehre der Apostel und an der (brüderlichen) Gemeinschaft, am Brechen des Brotes und an den (gemeinsamen) Gebeten.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 2, 43, 'Und über jedermann (im Volk) kam Furcht, und viele Wunder und Zeichen geschahen durch die Apostel.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 2, 44, 'Alle Gläubiggewordenen aber waren beisammen und hatten alles gemeinsam;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 2, 45, 'sie verkauften ihre Besitztümer und ihre Habe und verteilten (den Erlös) unter alle nach Maßgabe der Bedürftigkeit eines jeden;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 2, 46, 'und indem sie am täglichen Besuch des Tempels mit Einmütigkeit festhielten und das Brot in den einzelnen Häusern brachen, genossen sie ihre (tägliche) Nahrung mit Frohlocken und in Herzenseinfalt,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 2, 47, 'priesen Gott und standen mit dem ganzen Volk in gutem Einvernehmen. Der Herr aber fügte täglich solche, die gerettet wurden, zu festem Anschluß hinzu.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 3, 1, 'Petrus und Johannes aber gingen (eines Tages) zusammen um die neunte Stunde, die Gebetsstunde, in den Tempel hinauf.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 3, 2, 'Da wurde (gerade) ein Mann herbeigetragen, der von seiner Geburt an lahm war und den man täglich an das sogenannte Schöne Tor des Tempels hinsetzte, damit er sich dort Almosen von den Besuchern des Tempels erbitte.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 3, 3, 'Als dieser nun Petrus und Johannes sah, die in den Tempel hineingehen wollten, bat er sie um ein Almosen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 3, 4, 'Da sah Petrus samt Johannes ihn scharf an und sagte: »Sieh uns an!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 3, 5, 'Jener blickte sie nun aufmerksam an in der Erwartung, eine Gabe von ihnen zu erhalten.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 3, 6, 'Petrus aber sagte: »Silber und Gold besitze ich nicht; was ich aber habe, das gebe ich dir: Im Namen Jesu Christi von Nazareth: Gehe umher!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 3, 7, 'Dann faßte er ihn bei der rechten Hand und richtete ihn auf; da wurden seine Füße und Knöchel augenblicklich fest;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 3, 8, 'er sprang auf, konnte stehen, ging umher und trat mit ihnen in den Tempel ein, indem er umherging und sprang und Gott pries.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 3, 9, 'So sahen ihn denn alle Leute, wie er umherging und Gott pries;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 3, 10, 'sie erkannten in ihm auch den Mann, der sonst, um Almosen zu erbitten, am Schönen Tore des Tempels gesessen hatte, und wurden voller Staunen und Verwunderung wegen der Heilung, die an ihm vorgegangen war.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 3, 11, 'Da er sich aber fest zu Petrus und Johannes hielt, strömte das gesamte Volk zu ihnen bei der sogenannten Halle Salomos zusammen, außer sich vor Staunen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 3, 12, 'Als Petrus das sah, richtete er folgende Ansprache an das Volk: »Ihr Männer von Israel, was wundert ihr euch über diesen Mann, oder was seht ihr uns so erstaunt an, als hätten wir durch eigene Kraft oder Frömmigkeit bewirkt, daß er umhergehen kann?');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 3, 13, 'Nein, der Gott Abrahams, Isaaks und Jakobs, der Gott unserer Väter, hat seinen Knecht Jesus verherrlicht, den ihr (den Heiden) ausgeliefert und vor Pilatus verleugnet habt, als dieser seine Freigebung beschlossen hatte;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 3, 14, 'da habt ihr den Heiligen und Gerechten verleugnet und die Begnadigung eines Mörders verlangt,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 3, 15, 'dagegen den Fürsten des Lebens hinrichten lassen. Diesen hat Gott von den Toten auferweckt: dafür sind wir Zeugen!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 3, 16, 'Und auf Grund des Glaubens an seinen Namen hat sein Name diesem Manne hier, den ihr seht und kennt, jetzt Kraft verliehen, und der durch Jesus (in uns) gewirkte Glaube hat ihm vor euer aller Augen diese seine gesunden Glieder geschenkt.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 3, 17, 'Und nun, ihr Brüder: ich weiß, daß ihr aus Unwissenheit gehandelt habt, wie auch eure Oberen;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 3, 18, 'Gott aber hat auf diese Weise das in Erfüllung gehen lassen, was er schon vorher durch den Mund aller Propheten verkündigt hat, daß nämlich sein Gesalbter leiden werde.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 3, 19, 'So tut denn Buße und bekehrt euch, damit eure Sünden vergeben werden,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 3, 20, 'auf daß Zeiten der Erquickung vom Angesicht des Herrn kommen und er den für euch zum Gesalbten bestimmten Jesus senden kann.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 3, 21, 'Diesen muß allerdings der Himmel aufnehmen bis zu den Zeiten der Wiederherstellung alles dessen, was Gott durch den Mund seiner heiligen Propheten von der Urzeit her verkündet hat.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 3, 22, 'Mose hat ja gesagt: ›Einen Propheten wie mich wird der Herr, unser Gott, euch aus euren Brüdern erstehen lassen: auf den sollt ihr in allem hören, was er zu euch reden wird;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 3, 23, 'und jede Seele, die auf diesen Propheten nicht hört, soll aus dem Volke ausgerottet werden!‹');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 3, 24, 'Aber auch alle anderen Propheten, soviele ihrer von Samuel an und in den folgenden Zeiten aufgetreten sind, haben diese Tage angekündigt.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 3, 25, 'Ihr seid die Söhne der Propheten und gehört dem Bunde an, den Gott mit euren Vätern geschlossen hat, als er dem Abraham die Verheißung gab: ›In deiner Nachkommenschaft sollen alle Geschlechter der Erde gesegnet werden.‹');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 3, 26, 'Für euch zuerst hat Gott seinen Knecht erstehen lassen und ihn gesandt, um euch dadurch zu segnen, daß ein jeder unter euch sich von seinen Bosheiten bekehrt.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 4, 1, 'Während sie noch zum Volk redeten, traten die Priester sowie der Tempelhauptmann und die Sadduzäer an sie heran;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 4, 2, 'diese waren nämlich unwillig darüber, daß sie dem Volk ihre Lehre vortrugen und die an Jesus vollführte Auferstehung von den Toten verkündeten.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 4, 3, 'Sie nahmen sie also fest und setzten sie in Gewahrsam bis zum folgenden Morgen; es war nämlich bereits Abend.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 4, 4, 'Viele aber von denen, welche die Ansprache (des Petrus) gehört hatten, waren zum Glauben gekommen, so daß die Zahl der (gläubigen) Männer sich (nunmehr) auf etwa fünftausend belief.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 4, 5, 'Am andern Morgen aber versammelten sich ihre Oberen sowie die Ältesten und Schriftgelehrten in Jerusalem,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 4, 6, 'auch der Hohepriester Hannas, ferner Kaiphas, Johannes, Alexander und alle, die zu einer hohenpriesterlichen Familie gehörten.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 4, 7, 'Dann ließ man sie vorführen und fragte sie: »Durch was für eine Kraft oder durch welchen Namen habt ihr dies (Zeichen) vollführt?«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 4, 8, 'Da wurde Petrus mit heiligem Geist erfüllt und sagte zu ihnen: »Ihr Oberen des Volkes und ihr Ältesten!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 4, 9, 'Wenn wir uns heute wegen der einem kranken Menschen erwiesenen Wohltat zu verantworten haben (und gefragt werden), durch wen dieser Mann hier gesund geworden sei,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 4, 10, 'so soll euch allen und dem Volk Israel kundgetan sein: In der Kraft des Namens Jesu Christi von Nazareth, den ihr gekreuzigt habt, den Gott aber von den Toten auferweckt hat – ja, durch dessen Namen steht der Mann hier gesund vor euch!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 4, 11, 'Dieser (Jesus) ist der von euch Bauleuten verworfene Stein, der zum Eckstein geworden ist;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 4, 12, 'und in keinem andern ist die Rettung zu finden; denn es ist auch kein anderer Name unter dem Himmel den Menschen gegeben, in dem wir gerettet werden sollen.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 4, 13, 'Als sie nun die freudige Zuversicht des Petrus und Johannes sahen und in Erfahrung gebracht hatten, daß es Menschen ohne Schulung und ohne gelehrte Bildung waren, verwunderten sie sich; sie erkannten auch wohl, daß sie Begleiter Jesu gewesen waren,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 4, 14, 'und weil sie den Mann, der geheilt worden war, bei ihnen stehen sahen, wußten sie nichts zu entgegnen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 4, 15, 'Sie ließen sie also aus der Ratssitzung abtreten und berieten miteinander die Frage:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 4, 16, '»Was sollen wir mit diesen Menschen machen? Denn daß ein unverkennbares Wunderzeichen durch sie geschehen ist, das ist allen Einwohnern Jerusalems bekannt geworden, und wir können es nicht bestreiten.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 4, 17, 'Damit aber die Kunde davon sich nicht noch weiter unter dem Volk verbreitet, wollen wir ihnen ernstlich gebieten, in Zukunft zu keinem Menschen mehr unter Nennung dieses Namens zu reden.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 4, 18, 'Sie ließen sie dann wieder hereinrufen und geboten ihnen, überhaupt nichts mehr unter Nennung des Namens Jesu verlauten zu lassen und zu lehren.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 4, 19, 'Doch Petrus und Johannes antworteten ihnen mit den Worten: »Urteilt selbst, ob es vor Gott recht ist, euch mehr zu gehorchen als Gott!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 4, 20, 'Wir unserseits können es ja unmöglich unterlassen, von dem zu reden, was wir gesehen und gehört haben!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 4, 21, 'Jene fügten noch weitere Drohungen hinzu, ließen sie dann aber frei, weil sie keine Möglichkeit fanden, sie zu bestrafen, (auch) mit Rücksicht auf das Volk, weil alle Gott wegen des Geschehenen priesen;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 4, 22, 'denn über vierzig Jahre war der Mann alt, an dem dieses Heilungswunder geschehen war.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 4, 23, 'Nach ihrer Freilassung kehrten Petrus und Johannes zu den Ihrigen zurück und berichteten ihnen alles, was die Hohenpriester und die Ältesten zu ihnen gesagt hatten.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 4, 24, 'Als jene es vernommen hatten, erhoben sie einmütig ihre Stimme zu Gott und beteten: »Herr, du bist es, der den Himmel und die Erde, das Meer und alles, was in ihnen ist, geschaffen hat;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 4, 25, 'du hast durch den heiligen Geist zu unsern Vätern durch den Mund Davids, deines Knechtes, gesagt: ›Was soll das Toben der Heiden und das eitle Sinnen der Völker?');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 4, 26, 'Die Könige der Erde erheben sich, und die Fürsten rotten sich zusammen gegen den Herrn und gegen seinen Gesalbten!‹');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 4, 27, 'Ja, es haben sich in Wahrheit gegen deinen heiligen Knecht Jesus, den du gesalbt hast, in dieser Stadt Herodes und Pontius Pilatus mit den Heiden und den Volksscharen Israels zusammengetan,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 4, 28, 'um alles auszuführen, was deine Hand und dein Ratschluß vorherbestimmt haben, daß es geschehen sollte.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 4, 29, 'Und jetzt, Herr, blicke hin auf ihre Drohungen und verleihe deinen Knechten Kraft, dein Wort mit allem Freimut zu verkündigen!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 4, 30, 'Strecke deine Hand dabei zu Heilungen aus und laß Zeichen und Wunder durch den Namen deines heiligen Knechtes Jesus geschehen!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 4, 31, 'Als sie so gebetet hatten, erbebte die Stätte, wo sie versammelt waren, und sie wurden alle vom heiligen Geist erfüllt und verkündigten das Wort Gottes unerschrocken.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 4, 32, 'Die Gesamtheit der Gläubiggewordenen aber war ein Herz und eine Seele, und kein einziger nannte ein Stück seines Besitzes sein ausschließliches Eigentum, sondern sie hatten alles als Gemeingut.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 4, 33, 'Zudem legten die Apostel mit großem Nachdruck Zeugnis von der Auferstehung des Herrn Jesus ab, und alle erfreuten sich großer Beliebtheit.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 4, 34, 'Denn es gab auch keinen Notleidenden unter ihnen; alle nämlich, welche Ländereien oder Häuser besaßen, verkauften diese, brachten dann den Erlös aus dem Verkauf');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 4, 35, 'und stellten ihn den Aposteln zur Verfügung; davon wurde dann jedem nach seiner Bedürftigkeit zugeteilt.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 4, 36, 'So besaß (z.B.) Joseph, der von den Aposteln den Beinamen Barnabas, das heißt auf deutsch ›Sohn der Tröstung‹, erhalten hatte, ein Levit, aus Cypern gebürtig, einen Acker;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 4, 37, 'den verkaufte er, brachte dann den Geldbetrag und stellte ihn den Aposteln zur Verfügung.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 5, 1, 'Ein Mann dagegen namens Ananias verkaufte im Einvernehmen mit seiner Frau Sapphira ein Grundstück,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 5, 2, 'behielt aber einen Teil des Erlöses unter Mitwissen seiner Frau für sich zurück: er brachte nur einen Teil davon und stellte ihn den Aposteln zur Verfügung.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 5, 3, 'Da sagte Petrus: »Ananias, warum hat der Satan dir das Herz erfüllt, daß du den heiligen Geist belogen und einen Teil vom Erlös des Ackers für dich zurückbehalten hast?');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 5, 4, 'Blieb er nicht dein Eigentum, wenn du ihn unverkauft gelassen hättest, und stand dir nicht auch nach dem Verkauf die Verfügung über ihn frei? Warum hast du dir eine solche Handlungsweise in den Sinn kommen lassen? Du hast nicht Menschen belogen, sondern Gott!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 5, 5, 'Als Ananias diese Worte hörte, fiel er nieder und gab seinen Geist auf. Da kam große Furcht über alle, die es hörten.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 5, 6, 'Die jüngeren Männer aber standen auf, hüllten die Leiche in Tücher und trugen sie zum Begräbnis hinaus.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 5, 7, 'Nach Verlauf von etwa drei Stunden trat auch seine Frau ein, ohne von dem Vorgefallenen etwas zu wissen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 5, 8, 'Petrus redete sie mit den Worten an: »Sage mir: habt ihr das Grundstück für diesen Preis verkauft?« Sie antwortete: »Ja, für diesen Preis.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 5, 9, 'Da sagte Petrus zu ihr: »Warum habt ihr beide euch verabredet, den Geist des Herrn zu versuchen? Siehe, die Füße derer, die deinen Mann zu Grabe getragen haben, stehen vor der Tür, und sie werden auch dich hinaustragen!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 5, 10, 'Da fiel sie augenblicklich zu seinen Füßen nieder und gab ihren Geist auf; und als die jungen Männer hereinkamen, fanden sie sie als Leiche vor; sie trugen sie hinaus und begruben sie bei ihrem Manne.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 5, 11, 'Da kam eine große Furcht über die ganze Gemeinde und über alle, die davon hörten.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 5, 12, 'Durch die Hände der Apostel aber geschahen viele Zeichen und Wunder unter dem Volke, und alle (Gläubigen) pflegten sich einmütig in der Halle Salomos zu versammeln;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 5, 13, 'von den übrigen aber wagte sich niemand dort störend an sie heranzudrängen, sondern das Volk hielt sie hoch in Ehren.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 5, 14, 'Und immer mehr kamen solche hinzu, die an den Herrn glaubten, ganze Scharen von Männern und Frauen;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 5, 15, 'ja man brachte die Kranken sogar auf die Straßen hinaus und legte sie dort auf Betten und Bahren, damit, wenn Petrus käme, wenigstens sein Schatten auf den einen oder andern von ihnen fiele.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 5, 16, 'Aber auch aus den rings um Jerusalem liegenden Ortschaften strömte die Bevölkerung zusammen und brachte Kranke und von unreinen Geistern Geplagte dorthin, die dann alle geheilt wurden.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 5, 17, 'Da erhob sich aber der Hohepriester samt seinem ganzen Anhang, nämlich die Partei der Sadduzäer; sie waren voll von Eifersucht,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 5, 18, 'ließen die Apostel festnehmen und sie in das öffentliche Gefängnis setzen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 5, 19, 'Aber ein Engel des Herrn öffnete während der Nacht die Gefängnistüren, führte sie hinaus und gebot ihnen:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 5, 20, '»Geht hin, tretet offen auf und verkündigt im Tempel dem Volk alle diese Lebensworte!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 5, 21, 'Als sie das gehört hatten, begaben sie sich mit Tagesanbruch in den Tempel und lehrten dort. Der Hohepriester und sein Anhang hatten sich inzwischen eingestellt und den Hohen Rat und die gesamte Ältestenschaft der Israeliten zur Versammlung berufen lassen und sandten nun ins Gefängnis, um sie vorführen zu lassen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 5, 22, 'Als aber die Diener hinkamen, fanden sie sie im Gefängnis nicht vor und meldeten nach ihrer Rückkehr:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 5, 23, '»Wir haben das Gefängnis ganz fest verschlossen gefunden, auch die Wächter standen auf ihrem Posten an den Türen; als wir aber aufschlossen, haben wir niemand drinnen vorgefunden.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 5, 24, 'Als der Tempelhauptmann und die Hohenpriester diese Meldung vernahmen, waren sie ihretwegen ratlos, welche Bewandtnis es damit wohl haben möchte.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 5, 25, 'Da kam einer und meldete ihnen: »Denkt nur! Die Männer, die ihr ins Gefängnis gesetzt habt, die stehen jetzt im Tempel und lehren das Volk!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 5, 26, 'Da ging der Hauptmann mit den Dienern hin und holte sie herbei, doch ohne Anwendung von Gewalt; denn sie hatten zu befürchten, vom Volk gesteinigt zu werden.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 5, 27, 'Sie brachten sie also herbei und stellten sie vor den Hohen Rat; und der Hohepriester verhörte sie folgendermaßen:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 5, 28, '»Wir haben euch doch ausdrücklich geboten, auf Grund dieses Namens nicht zu lehren, und trotzdem habt ihr mit eurer Lehre ganz Jerusalem erfüllt und wollt das Blut dieses Menschen auf uns bringen!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 5, 29, 'Da antwortete Petrus, und die Apostel erklärten: »Man muß Gott mehr gehorchen als den Menschen!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 5, 30, 'Der Gott unserer Väter hat Jesus auferweckt, den ihr ans Holz gehängt und hingerichtet habt.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 5, 31, 'Diesen hat Gott durch seine rechte Hand zum Anführer und Retter erhöht, um Israel Buße und Vergebung der Sünden zu verleihen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 5, 32, 'Für diese Tatsachen sind wir Zeugen und auch der heilige Geist, den Gott denen verliehen hat, die ihm gehorsam sind.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 5, 33, 'Als jene das hörten, ging es ihnen wie ein Stich durchs Herz, und sie waren entschlossen, sie hinrichten zu lassen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 5, 34, 'Doch da stand in der Versammlung ein Pharisäer namens Gamaliel auf, ein beim ganzen Volk hochangesehener Gesetzeslehrer; er ließ die Männer auf kurze Zeit hinausführen');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 5, 35, 'und richtete dann folgende Ansprache an die Versammlung: »Ihr Männer von Israel, überlegt euch wohl, wie ihr mit diesen Leuten verfahren wollt!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 5, 36, 'Denn vor einiger Zeit trat Theudas auf und gab sich für etwas Besonderes aus, und eine Anzahl von etwa vierhundert Männern fiel ihm zu; aber er fand den Tod, und alle seine Anhänger wurden zersprengt und vernichtet.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 5, 37, 'Nach diesem trat Judas aus Galiläa zur Zeit der Schätzung auf und brachte einen Volkshaufen zum Aufstand unter seiner Führung; aber auch er kam ums Leben, und sein ganzer Anhang wurde zerstreut.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 5, 38, 'Und nunmehr gebe ich euch den Rat: Steht von diesen Leuten ab und laßt sie gewähren! Denn wenn dieses Vorhaben oder dieses Werk von Menschen ausgeht, so wird es zunichte werden;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 5, 39, 'hat es aber seinen Ursprung in Gott, so werdet ihr diese Leute nicht zu vernichten vermögen. Laßt ihr euch nur nicht gar als Widersacher Gottes erfinden!« Daraufhin folgten sie seinem Rat:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 5, 40, 'sie ließen die Apostel wieder hereinrufen und geißeln und befahlen ihnen, auf Grund des Namens Jesu nicht mehr zu predigen; dann gab man sie frei.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 5, 41, 'So gingen sie denn aus dem Hohen Rat weg, hocherfreut, daß sie gewürdigt worden waren, um des Namens (Jesu) willen Schmach zu erleiden;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 5, 42, 'und sie hörten nicht auf, täglich im Tempel und in den Häusern zu lehren und die Heilsbotschaft von Christus Jesus zu verkündigen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 6, 1, 'In diesen Tagen nun entstand bei der Zunahme der Zahl der Jünger laute Unzufriedenheit der Hellenisten gegen die Hebräer, weil ihre Witwen bei der täglichen Verpflegung nicht genügend berücksichtigt würden.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 6, 2, 'So beriefen denn die Zwölf die Gesamtheit der Jünger und sagten: »Es scheint uns nicht das Richtige zu sein, daß wir die Verkündigung des Wortes Gottes hintansetzen, um den Tischdienst zu besorgen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 6, 3, 'So seht euch nun, ihr Brüder, nach sieben bewährten, mit Geist und Weisheit erfüllten Männern aus eurer Mitte um, damit wir sie zu diesem Dienst bestellen;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 6, 4, 'wir selbst aber wollen uns ausschließlich dem Gebet und dem Dienst am Wort widmen.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 6, 5, 'Dieser Vorschlag fand den Beifall der ganzen Versammlung, und man wählte Stephanus, einen Mann voll Glaubens und heiligen Geistes, ferner den Philippus, Prochorus, Nikanor, Timon, Parmenas und Nikolaus, einen Judengenossen aus Antiochia.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 6, 6, 'Diese Männer ließ man vor die Apostel hintreten, die (für sie) beteten und ihnen die Hände auflegten.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 6, 7, 'Das Wort Gottes breitete sich nun immer weiter aus, und die Zahl der Jünger vermehrte sich in Jerusalem stark; sogar eine große Menge von Priestern wurde dem Glauben gehorsam.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 6, 8, 'Stephanus aber, ein Mann voll Gnade und Geisteskraft, tat Wunder und große Zeichen unter dem Volke.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 6, 9, 'Da traten einige Mitglieder der sogenannten Synagoge der Freigelassenen sowie der Cyrenäer und Alexandriner und der Synagogen der Cilicier und der Provinz Asien auf und führten mit Stephanus Streitgespräche,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 6, 10, 'vermochten jedoch gegen die Weisheit und den Geist, mit dem er redete, nicht aufzukommen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 6, 11, 'Infolgedessen stifteten sie Männer an, die aussagen mußten: »Wir haben ihn Lästerworte gegen Mose und gegen Gott aussprechen hören.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 6, 12, 'So wiegelten sie denn das Volk sowie die Ältesten und die Schriftgelehrten auf, fielen dann über ihn her, schleppten ihn mit sich und führten ihn vor den Hohen Rat.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 6, 13, 'Hier ließen sie falsche Zeugen auftreten, die aussagten: »Dieser Mensch hört nicht auf, Reden gegen die heilige Stätte hier und das Gesetz zu führen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 6, 14, 'So haben wir ihn sagen hören: ›Dieser Jesus von Nazareth wird diese Stätte zerstören und die Gebräuche abändern, die Mose uns verordnet hat.‹«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 6, 15, 'Als nun alle, die im Hohen Rate saßen, ihre Blicke gespannt auf ihn richteten, sahen sie sein Antlitz (verklärt) wie das Angesicht eines Engels.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 7, 1, 'Der Hohepriester fragte ihn nun: »Verhält sich dies so?«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 7, 2, 'Da antwortete Stephanus: »Werte Brüder und Väter, hört mich an! Der Gott der Herrlichkeit erschien unserm Vater Abraham, als er noch in Mesopotamien wohnte, bevor er sich in Haran niedergelassen hatte,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 7, 3, 'und gebot ihm: ›Verlaß dein Heimatland und deine Verwandtschaft und ziehe in das Land, das ich dir zeigen werde!‹');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 7, 4, 'Da wanderte er aus dem Lande der Chaldäer aus und ließ sich in Haran nieder. Von dort ließ Gott ihn dann nach dem Tode seines Vaters in dieses Land hier übersiedeln, das ihr noch jetzt bewohnt;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 7, 5, 'doch gab er ihm keinen festen Besitz darin, auch nicht einen Fuß breit, verhieß ihm jedoch, er wolle es ihm und seiner Nachkommenschaft späterhin zum Eigentum geben, obgleich er damals noch kein Kind hatte.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 7, 6, 'So lauteten aber Gottes Worte: ›Seine Nachkommen werden als Beisassen in einem fremden Lande ansässig sein, wo man sie vierhundert Jahre lang knechten und mißhandeln wird;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 7, 7, 'doch das Volk, dem sie als Knechte dienen werden, will ich richten‹, sagte Gott; ›und hierauf werden sie ausziehen und mir an dieser Stätte dienen.‹');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 7, 8, 'Dann gab Gott ihm den Bund der Beschneidung, und so wurde Abraham der Vater Isaaks, den er am achten Tage beschnitt; Isaak wurde dann der Vater Jakobs und Jakob der Vater der zwölf Erzväter.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 7, 9, 'Weil dann aber die Erzväter auf Joseph neidisch wurden, verkauften sie ihn nach Ägypten; doch Gott war mit ihm');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 7, 10, 'und rettete ihn aus allen seinen Bedrängnissen und verlieh ihm Gnade und Weisheit vor dem Pharao, dem ägyptischen König, der ihn zum Gebieter über Ägypten und über sein ganzes Haus einsetzte.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 7, 11, 'Da kam eine Hungersnot und große Drangsal über das ganze Land Ägypten und Kanaan, und unsere Väter hatten nichts zu essen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 7, 12, 'Als aber Jakob erfuhr, daß in Ägypten Getreide zu haben sei, sandte er unsere Väter zum erstenmal hin.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 7, 13, 'Beim zweitenmal gab sich dann Joseph seinen Brüdern zu erkennen, und Josephs Herkunft wurde dem Pharao bekannt.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 7, 14, 'Joseph sandte dann hin und ließ seinen Vater Jakob und seine gesamte Verwandtschaft holen, im ganzen fünfundsiebenzig Seelen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 7, 15, 'So zog denn Jakob nach Ägypten hinab, wo er starb und ebenso auch unsere Väter;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 7, 16, 'sie wurden nach Sichem überführt und in dem Grabe beigesetzt, das Abraham für eine Geldsumme von den Söhnen Hemors in Sichem gekauft hatte.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 7, 17, '»Je näher aber die Zeit der Verheißung kam, die Gott dem Abraham zugesagt hatte, desto mehr wuchs das Volk in Ägypten an und wurde zahlreich,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 7, 18, 'bis ein anderer König zur Regierung über Ägypten kam, der von Joseph nichts wußte.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 7, 19, 'Dieser verfuhr arglistig gegen unser Volk und mißhandelte unsere Väter, so daß sie ihre neugeborenen Kinder aussetzen mußten, damit sie nicht am Leben bleiben sollten.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 7, 20, 'In dieser Zeit wurde Mose geboren und war ein ausnehmend schönes Kind; drei Monate lang wurde er im Elternhause aufgezogen,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 7, 21, 'und als man ihn dann ausgesetzt hatte, nahm ihn die Tochter Pharaos zu sich und erzog ihn für sich selbst zum Sohn.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 7, 22, 'So wurde denn Mose in aller Weisheit der Ägypter unterrichtet und war gewaltig in seinen Worten und Taten.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 7, 23, 'Als er aber volle vierzig Jahre alt geworden war, stieg das Verlangen in ihm auf, sich einmal nach seinen Brüdern, den Israeliten, umzusehen;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 7, 24, 'und als er einen von ihnen sah, dem Unrecht geschah, leistete er ihm Beistand und verschaffte dem Mißhandelten Genugtuung, indem er den Ägypter erschlug.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 7, 25, 'Dabei war er der Meinung, seine Volksgenossen würden zu der Einsicht kommen, daß Gott ihnen durch seine Hand Rettung schaffen würde; doch sie erkannten es nicht.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 7, 26, 'Am folgenden Tage kam er gerade dazu, als zwei von ihnen einen Streit miteinander hatten; da wollte er sie versöhnen, damit sie Frieden hielten, indem er sagte: ›Ihr Männer, ihr seid doch Brüder: warum tut ihr einander unrecht?‹');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 7, 27, 'Der aber, welcher seinem Genossen unrecht tat, stieß ihn zurück mit den Worten: ›Wer hat dich zum Oberhaupt und Richter über uns eingesetzt?');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 7, 28, 'Willst du mich etwa ebenso erschlagen, wie du gestern den Ägypter erschlagen hast?‹');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 7, 29, 'Um dieses Wortes willen ergriff Mose die Flucht und lebte als Fremdling im Lande Midian, wo ihm zwei Söhne geboren wurden.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 7, 30, 'Als dann wieder volle vierzig Jahre vergangen waren, erschien ihm in der Wüste des Berges Sinai ein Engel in der Feuerflamme eines Dornbusches.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 7, 31, 'Als Mose das sah, verwunderte er sich über die Erscheinung; als er aber näher hinzutrat, um genauer zuzusehen, erscholl die Stimme des Herrn:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 7, 32, '›Ich bin der Gott deiner Väter, der Gott Abrahams, Isaaks und Jakobs.‹ Da begann Mose zu zittern und wagte nicht, genauer hinzusehen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 7, 33, 'Der Herr aber sagte zu ihm: ›Ziehe dir die Schuhe ab von den Füßen; denn die Stätte, auf der du stehst, ist heiliges Land.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 7, 34, 'Ich habe die Mißhandlung meines Volkes in Ägypten gesehen und ihr Seufzen gehört; darum bin ich herabgekommen, sie zu erretten. Und jetzt komm: ich will dich nach Ägypten senden!‹');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 7, 35, 'Diesen Mose, den sie verleugnet hatten, als sie sagten: ›Wer hat dich zum Oberhaupt und Richter (über uns) gesetzt?‹, eben diesen hat Gott als Oberhaupt und Erlöser gesandt durch die Vermittlung des Engels, der ihm im Dornbusch erschienen war.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 7, 36, 'Dieser ist es auch, der sie (aus dem Lande) weggeführt hat, indem er Wunder und Zeichen im Lande Ägypten und am Roten Meer sowie vierzig Jahre lang in der Wüste tat.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 7, 37, 'Dieser Mose ist es, der zu den Israeliten gesagt hat: ›Einen Propheten wie mich wird Gott euch aus euren Volksgenossen erwecken.‹');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 7, 38, 'Dieser ist es, der bei der Gemeindeversammlung in der Wüste Vermittler gewesen ist zwischen dem Engel, der auf dem Berge Sinai zu ihm redete, und zwischen unsern Vätern, derselbe, der lebendige Worte empfing, um sie uns mitzuteilen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 7, 39, 'Doch unsere Väter wollten ihm nicht gehorsam sein; vielmehr stießen sie ihn von sich und sehnten sich nach Ägypten zurück');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 7, 40, 'und sagten zu Aaron: ›Mache uns Götter, die vor uns herziehen sollen! Denn von diesem Mose, der uns aus dem Lande Ägypten herausgeführt hat, wissen wir nicht, was aus ihm geworden ist.‹');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 7, 41, 'So machten sie sich denn damals ein Stierbild, brachten diesem Götzen Opfer dar und hatten ihre Freude an den Werken ihrer Hände.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 7, 42, 'Da wandte Gott sich von ihnen ab und gab sie dahin, daß sie dem Sternenheer des Himmels dienten, wie im Buch der Propheten geschrieben steht: ›Habt ihr etwa mir Schlachttiere und Opfergaben während der vierzig Jahre in der Wüste dargebracht, ihr vom Hause Israel?');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 7, 43, 'Nein, das Zelt des Moloch und das Sternbild des Gottes Rephan habt ihr getragen, die Götzenbilder, die ihr zur Anbetung angefertigt hattet; darum werde ich euch über Babylon hinaus (in die Verbannung) wegführen lassen.‹«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 7, 44, '»Die Hütte des Zeugnisses hatten unsere Väter in der Wüste so, wie Gott es angeordnet hatte, als er dem Mose gebot, sie nach dem Vorbild, das er gesehen hatte, herzustellen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 7, 45, 'Diese (Hütte) haben unsere Väter dann auch übernommen und sie unter Josua in das Gebiet der Heidenvölker gebracht, die Gott vor den Augen unserer Väter vertrieb; (und so blieb es) bis zur Zeit Davids.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 7, 46, 'Dieser fand Gnade vor Gott und erbat es sich als Gunst, eine Wohnung für den Gott Jakobs zu finden.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 7, 47, 'Aber erst Salomo hat ihm ein Haus erbaut.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 7, 48, 'Doch der Höchste wohnt nicht in einem Bau, der von Menschenhand hergestellt ist, wie der Prophet sagt:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 7, 49, '›Der Himmel ist mein Thron und die Erde der Schemel meiner Füße. Was für ein Haus wäre es, das ihr mir bauen könntet?‹ – sagt der Herr – ›oder welches wäre die Stätte der Ruhe für mich?');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 7, 50, 'Hat nicht meine Hand dies ganze Weltall geschaffen?‹«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 7, 51, '»O ihr Halsstarrigen und an Herz und Ohren Unbeschnittenen! Immerfort widerstrebt ihr dem heiligen Geist, wie eure Väter, so auch ihr.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 7, 52, 'Wo ist ein Prophet gewesen, den eure Väter nicht verfolgt haben? Und so haben sie auch die getötet, welche das Kommen des Gerechten vorausverkündigt haben, an dem ihr jetzt zu Verrätern und Mördern geworden seid.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 7, 53, 'Auf Anordnung von Engeln habt ihr das Gesetz empfangen und es doch nicht gehalten!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 7, 54, 'Als sie das hörten, ging es ihnen wie ein Stich durchs Herz, und sie knirschten mit den Zähnen gegen ihn.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 7, 55, 'Er aber, voll heiligen Geistes, blickte fest zum Himmel empor, sah die Herrlichkeit Gottes und Jesus zur Rechten Gottes stehen');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 7, 56, 'und rief aus: »Ich sehe die Himmel aufgetan und den Menschensohn zur Rechten Gottes stehen!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 7, 57, 'Da erhoben sie ein lautes Geschrei, hielten sich die Ohren zu und stürmten einmütig auf ihn los;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 7, 58, 'dann stießen sie ihn zur Stadt hinaus und steinigten ihn. Dabei legten die Zeugen ihre Obergewänder ab zu den Füßen eines jungen Mannes mit Namen Saulus');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 7, 59, 'und steinigten den Stephanus, der betend ausrief: »Herr Jesus, nimm meinen Geist auf!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 7, 60, 'Alsdann auf die Knie niedergesunken, rief er noch laut aus: »Herr, rechne ihnen diese Sünde nicht zu!« Nach diesen Worten gab er seinen Geist auf.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 8, 1, 'Saulus aber war mit seiner Hinrichtung durchaus einverstanden. b An jenem Tage kam es aber zu einer schweren Verfolgung der Gemeinde in Jerusalem. Da zerstreuten sich alle mit Ausnahme der Apostel in die Landbezirke von Judäa und Samaria.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 8, 2, 'Den Stephanus aber bestatteten gottesfürchtige Männer und veranstalteten eine feierliche Trauerfeier um ihn.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 8, 3, 'Saulus aber wütete gegen die Gemeinde, indem er überall in die Häuser eindrang, Männer und Frauen fortschleppte und sie ins Gefängnis werfen ließ.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 8, 4, 'Die Versprengten nun zogen im Lande umher und verkündigten die Heilsbotschaft.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 8, 5, 'Dabei kam Philippus in die Hauptstadt von Samarien hinab und predigte ihren Bewohnern den Gottgesalbten.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 8, 6, 'Die Volksmenge zeigte sich allgemein für die Predigt des Philippus empfänglich, indem sie ihm zuhörten und die Zeichen sahen, die er tat;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 8, 7, 'denn aus vielen fuhren die unreinen Geister, von denen sie besessen waren, mit lautem Geschrei aus, und zahlreiche Gelähmte und Verkrüppelte wurden geheilt.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 8, 8, 'Darüber herrschte in jener Stadt große Freude.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 8, 9, 'Nun hatte schon vorher ein Mann namens Simon in der Stadt gelebt, der sich mit Zauberei abgab und die Bevölkerung von Samaria dadurch in Staunen versetzte; denn er behauptete von sich, er sei etwas Großes.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 8, 10, 'Alle waren für ihn eingenommen, klein und groß, und erklärten: »Dieser Mann ist die Kraft Gottes, welche die große heißt.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 8, 11, 'Sie waren aber deshalb für ihn so eingenommen, weil er sie lange Zeit durch seine Zauberkünste in Erstaunen gesetzt hatte.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 8, 12, 'Als sie jetzt aber dem Philippus Glauben schenkten, der ihnen die Heilsbotschaft vom Reiche Gottes und vom Namen Jesu Christi verkündigte, ließen sie sich taufen, Männer wie Frauen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 8, 13, 'So wurde denn Simon ebenfalls gläubig; er schloß sich nach seiner Taufe eng an Philippus an und kam nicht aus dem Staunen heraus, als er die Zeichen und großen Wunder sah, die da geschahen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 8, 14, 'Als nun die Apostel in Jerusalem vernahmen, daß Samaria das Wort Gottes angenommen habe, entsandten sie Petrus und Johannes zu ihnen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 8, 15, 'Diese beteten nach ihrer Ankunft für sie, daß sie den heiligen Geist empfangen möchten;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 8, 16, 'denn dieser war noch auf keinen von ihnen gefallen, sondern sie waren lediglich auf den Namen des Herrn Jesus getauft worden.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 8, 17, 'Infolgedessen legten sie (die beiden Apostel) ihnen die Hände auf, und sie empfingen den heiligen Geist.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 8, 18, 'Als nun Simon sah, daß durch die Handauflegung der Apostel der heilige Geist verliehen wurde, bot er ihnen Geld an');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 8, 19, 'und bat: »Verleiht doch auch mir diese Kraft, daß jeder, dem ich die Hände auflege, den heiligen Geist empfängt.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 8, 20, 'Petrus aber gab ihm zur Antwort: »Dein Geld fahre samt dir ins Verderben, weil du gemeint hast, die Gabe Gottes durch Geld erkaufen zu können!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 8, 21, 'Du hast keinen Anteil und kein Anrecht an dieser Sache; denn dein Herz ist nicht aufrichtig vor Gott.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 8, 22, 'Darum bekehre dich von dieser deiner Bosheit und bete zum Herrn, ob dir vielleicht das Trachten deines Herzens vergeben werden mag;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 8, 23, 'denn ich sehe, daß du in ›Galle der Bitterkeit‹ und in ›Bande der Ungerechtigkeit‹ geraten bist.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 8, 24, 'Da antwortete Simon: »Betet ihr für mich zum Herrn, daß nichts von dem, was ihr ausgesprochen habt, mich treffen möge!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 8, 25, 'Als sie nun (die beiden Apostel) das Wort des Herrn bezeugt und gepredigt hatten, machten sie sich auf die Rückreise nach Jerusalem und verkündigten (dabei noch) in vielen samaritischen Ortschaften die Heilsbotschaft.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 8, 26, 'Ein Engel des Herrn aber gebot dem Philippus: »Mach dich auf und begib dich um die Mittagszeit auf die Straße, die von Jerusalem nach Gaza hinabführt und einsam ist!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 8, 27, 'Da machte er sich auf und ging hin. Und siehe, ein Äthiopier, ein Hofbeamter und Würdenträger der äthiopischen Königin Kandace, der ihren gesamten Schatz zu verwalten hatte, war nach Jerusalem gekommen, um dort anzubeten.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 8, 28, 'Jetzt befand er sich wieder auf der Heimreise und saß auf seinem Wagen, indem er den Propheten Jesaja las.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 8, 29, 'Da gebot der Geist dem Philippus: »Tritt hinzu und halte dich nahe an diesen Wagen!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 8, 30, 'So lief denn Philippus hinzu, und als er hörte, wie jener den Propheten Jesaja las, fragte er ihn: »Verstehst du auch, was du liest?«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 8, 31, 'Er antwortete: »Wie sollte ich das können, wenn mir niemand Anleitung gibt?« Dann bat er Philippus, aufzusteigen und sich zu ihm zu setzen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 8, 32, 'Der Wortlaut der Schriftstelle nun, die er gerade las, war dieser: »Wie ein Schaf wurde er zur Schlachtbank geführt, und wie ein Lamm vor seinem Scherer stumm bleibt, so tat er seinen Mund nicht auf.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 8, 33, 'In seiner Erniedrigung wurde das Strafgericht über ihn aufgehoben, und wer wird seine Nachkommenschaft berechnen? Denn erhoben wird sein Leben von der Erde hinweg.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 8, 34, 'Da wandte sich der Hofbeamte an Philippus mit der Frage: »Ich bitte dich: von wem redet hier der Prophet? Von sich selbst oder von einem andern?«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 8, 35, 'Da tat Philippus seinen Mund auf und verkündigte ihm, indem er an dieses Schriftwort anknüpfte, die Heilsbotschaft von Jesus.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 8, 36, 'Als sie nun so auf der Straße dahinfuhren, kamen sie an ein Gewässer; da sagte der Hofbeamte: »Hier ist ja Wasser! Was steht meiner Taufe noch im Wege?«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 8, 37, '[Philippus antwortete ihm: »Wenn du von ganzem Herzen glaubst, so darf es wohl geschehen.« Jener antwortete: »Ich glaube, daß Jesus Christus der Sohn Gottes ist.«]');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 8, 38, 'Er ließ also den Wagen halten, und beide stiegen in das Wasser hinab, Philippus sowohl wie der Hofbeamte, und er taufte ihn.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 8, 39, 'Als sie dann wieder aus dem Wasser heraufgestiegen waren, entrückte der Geist des Herrn den Philippus, und der Hofbeamte sah ihn nicht mehr; denn freudig zog er auf seiner Straße weiter.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 8, 40, 'Philippus aber befand sich in Asdod; er zog dort von Ort zu Ort und verkündigte die Heilsbotschaft in allen Städten, bis er nach Cäsarea kam.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 9, 1, 'Saulus aber, der noch immer Drohungen und Mord gegen die Jünger des Herrn schnaubte, wandte sich an den Hohenpriester');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 9, 2, 'und erbat sich von ihm Briefe nach Damaskus an die dortigen Synagogen, um Anhänger der neuen Lehre, die er etwa fände, Männer wie Frauen, in Fesseln nach Jerusalem zu bringen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 9, 3, 'Während er nun so dahinzog und schon in die Nähe von Damaskus gekommen war, umstrahlte ihn plötzlich ein Lichtschein vom Himmel her;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 9, 4, 'er stürzte zu Boden und vernahm eine Stimme, die ihm zurief: »Saul, Saul! Was verfolgst du mich?«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 9, 5, 'Er fragte: »Wer bist du, Herr?« Jener antwortete: »Ich bin Jesus, den du verfolgst!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 9, 6, 'Doch stehe auf und geh in die Stadt hinein: dort wird dir gesagt werden, was du tun sollst!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 9, 7, 'Die Männer nun, die ihn auf der Reise begleiteten, standen sprachlos da; denn sie hörten wohl die Stimme, sahen aber niemand.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 9, 8, 'Saulus erhob sich dann von der Erde; obwohl jedoch seine Augen geöffnet waren, konnte er nichts sehen: an der Hand mußte man ihn nach Damaskus hinführen,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 9, 9, 'und er war drei Tage lang ohne Sehvermögen; auch aß und trank er nichts.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 9, 10, 'Nun wohnte in Damaskus ein Jünger namens Ananias; zu dem sprach der Herr in einem Gesicht: »Ananias!« Jener antwortete: »Hier bin ich, Herr!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 9, 11, 'Der Herr fuhr fort: »Stehe auf und begib dich in die sogenannte Gerade Straße; erkundige dich dort im Hause des Judas nach einem Manne namens Saulus aus Tarsus; denn siehe, er betet');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 9, 12, 'und hat in einem Gesicht gesehen, wie ein Mann namens Ananias bei ihm eintrat und ihm die Hände auflegte, damit er sein Augenlicht wiederbekomme.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 9, 13, 'Ananias aber antwortete: »Herr, ich habe von vielen Seiten über diesen Mann gehört, wieviel Böses er deinen Heiligen in Jerusalem zugefügt hat;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 9, 14, 'und auch hier hat er von den Hohenpriestern Vollmacht, alle in Fesseln zu legen, die deinen Namen anrufen.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 9, 15, 'Aber der Herr gab ihm zur Antwort: »Gehe hin! Denn dieser Mann ist für mich ein auserwähltes Werkzeug: er soll meinen Namen vor Heidenvölker und Könige und vor die Kinder Israel tragen;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 9, 16, 'denn ich werde ihm zeigen, wieviel er um meines Namens willen leiden muß.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 9, 17, 'Da machte sich Ananias auf den Weg, ging in das Haus und legte ihm die Hände auf mit den Worten: »Bruder Saul, der Herr hat mich gesandt, Jesus, der dir auf dem Wege hierher erschienen ist: du sollst wieder sehen können und mit heiligem Geist erfüllt werden.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 9, 18, 'Da fiel es ihm sogleich von den Augen ab wie Schuppen: er konnte wieder sehen, stand auf und ließ sich taufen;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 9, 19, 'a dann nahm er auch Nahrung zu sich und kam wieder zu Kräften. b Einige Tage war er nun mit den Jüngern in Damaskus zusammen;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 9, 20, 'dann predigte er sogleich in den (dortigen) Synagogen von Jesus, daß dieser der Sohn Gottes sei.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 9, 21, 'Da gerieten alle, die ihn hörten, in Erstaunen und sagten: »Ist das nicht derselbe Mann, der in Jerusalem die Bekenner dieses Namens wütend verfolgt hat und auch hierher in der Absicht gekommen war, sie in Fesseln vor die Hohenpriester zu führen?«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 9, 22, 'Saulus aber trat nur um so entschlossener auf und brachte die Juden, die in Damaskus wohnten, völlig außer Fassung, indem er bewies: »Dieser ist Christus!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 9, 23, 'Als so eine geraume Zeit vergangen war, beschlossen die Juden gemeinsam, ihn zu ermorden;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 9, 24, 'doch ihr Anschlag wurde dem Saulus bekannt. Da sie nun sogar die Stadttore bei Tag und bei Nacht bewachten, um ihn zu ermorden,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 9, 25, 'nahmen ihn die Jünger und ließen ihn bei Nacht in einem Korbe über die Mauer hinab.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 9, 26, 'Als er dann nach Jerusalem gekommen war, machte er dort Versuche, sich an die Jünger anzuschließen; aber alle fürchteten sich vor ihm, weil sie nicht glauben konnten, daß er ein Jünger sei.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 9, 27, 'Da nahm sich Barnabas seiner an, führte ihn zu den Aposteln und teilte ihnen mit, wie er unterwegs den Herrn gesehen und daß dieser zu ihm geredet habe, und wie er dann in Damaskus freimütig im Namen Jesu öffentlich gepredigt habe.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 9, 28, 'So ging er denn in Jerusalem mit ihnen ein und aus und predigte freimütig im Namen des Herrn;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 9, 29, 'auch unterredete er sich und hielt Streitgespräche mit den griechisch redenden Juden, die dann aber einen Anschlag auf sein Leben machten.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 9, 30, 'Als die Brüder das erfuhren, schafften sie ihn nach Cäsarea hinab und ließen ihn von da weiter nach Tarsus reisen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 9, 31, 'So hatte nun die Gemeinde in ganz Judäa, Galiläa und Samaria Frieden; sie baute sich innerlich auf, wandelte in der Furcht des Herrn und wuchs auch äußerlich durch den Beistand des heiligen Geistes.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 9, 32, 'Da geschah es, als Petrus allenthalben umherzog, daß er auch zu den Heiligen kam, die in Lydda wohnten.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 9, 33, 'Er fand dort einen Mann namens Äneas, der schon seit acht Jahren zu Bett lag, weil er gelähmt war.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 9, 34, 'Da sagte Petrus zu ihm: »Äneas, Jesus Christus macht dich gesund; stehe auf und mache dir dein Bett selbst!« Da stand er sogleich auf,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 9, 35, 'und alle Einwohner von Lydda und (der Landschaft) Saron sahen ihn und bekehrten sich zum Herrn.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 9, 36, 'In Joppe aber lebte eine Jüngerin namens Tabitha, das heißt auf deutsch ›Gazelle‹; die tat außerordentlich viel Gutes und spendete reichlich Almosen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 9, 37, 'Gerade in jenen Tagen aber begab es sich, daß sie krank wurde und starb. Man wusch sie also und bahrte sie in einem Obergemach auf.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 9, 38, 'Weil nun Lydda nahe bei Joppe liegt, sandten die Jünger auf die Nachricht, daß Petrus dort sei, zwei Männer an ihn ab und ließen ihn bitten: »Komm doch unverzüglich zu uns herüber!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 9, 39, 'Da machte sich Petrus auf den Weg und ging mit ihnen. Nach seiner Ankunft führte man ihn in das Obergemach hinauf; da traten alle Witwen weinend zu ihm und zeigten ihm die Röcke und Oberkleider, welche die Gazelle angefertigt hatte, als sie noch bei ihnen war.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 9, 40, 'Petrus ließ nun alle aus dem Zimmer hinausgehen, kniete nieder und betete; dann wandte er sich der Toten zu und sagte: »Tabitha, stehe auf!« Da schlug sie die Augen auf, und als sie Petrus erblickte, setzte sie sich aufrecht hin.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 9, 41, 'Er reichte ihr nun die Hand und half ihr auf; dann rief er die Heiligen und die Witwen herbei und stellte sie lebend vor sie hin.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 9, 42, 'Das wurde in ganz Joppe bekannt, und viele kamen zum Glauben an den Herrn.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 9, 43, 'Petrus blieb dann noch geraume Zeit in Joppe bei einem gewissen Simon, einem Gerber.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 10, 1, 'In Cäsarea aber lebte (damals) ein Mann namens Kornelius, ein Hauptmann bei der sogenannten Italischen Abteilung;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 10, 2, 'er war fromm und gottesfürchtig mit seinem ganzen Hause, tat dem (jüdischen) Volke viel Gutes durch seine Mildtätigkeit und betete ohne Unterlaß zu Gott.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 10, 3, 'Dieser Mann sah (eines Tages) in einem Gesicht um die neunte Tagesstunde deutlich einen Engel Gottes bei sich eintreten, der ihn anredete: »Kornelius!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 10, 4, 'Dieser blickte ihn starr an und fragte erschrocken: »Was soll ich, Herr?« Jener antwortete ihm: »Deine Gebete und deine Almosen sind zu Gott emporgestiegen, und er gedenkt ihrer wohl.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 10, 5, 'Und nun sende Boten nach Joppe und laß einen gewissen Simon mit dem Beinamen Petrus zu dir kommen;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 10, 6, 'der ist als Gast bei einem Gerber Simon, dessen Haus am Meere liegt.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 10, 7, 'Als nun der Engel, der mit ihm gesprochen hatte, verschwunden war, rief Kornelius zwei von seinen Dienern und einen frommen Soldaten aus der Zahl der Mannschaften, die ihn persönlich zu bedienen hatten,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 10, 8, 'teilte ihnen alles mit und sandte sie nach Joppe.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 10, 9, 'Am folgenden Tage aber, als diese unterwegs waren und sich schon der Stadt näherten, stieg Petrus um die Mittagszeit auf das Dach des Hauses hinauf, um dort zu beten.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 10, 10, 'Da wurde er hungrig und wünschte, etwas zu genießen. Während man es ihm nun zubereitete, kam eine Verzückung über ihn:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 10, 11, 'er sah den Himmel offen stehen und einen Behälter herabkommen wie ein großes Stück Leinwand, das an den vier Zipfeln zur Erde herabgelassen wurde.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 10, 12, 'Darin befanden sich alle Arten vierfüßiger und kriechender Tiere der Erde und Vögel des Himmels.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 10, 13, 'Nun rief eine Stimme ihm zu: »Stehe auf, Petrus, schlachte und iß!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 10, 14, 'Petrus aber antwortete: »Nicht doch, Herr! Denn noch nie habe ich etwas Unheiliges und Unreines genossen.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 10, 15, 'Da rief zum zweitenmal eine Stimme ihm zu: »Was Gott gereinigt hat, das erkläre du nicht für unrein!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 10, 16, 'Dies wiederholte sich dreimal; dann wurde der Behälter sogleich wieder in den Himmel emporgezogen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 10, 17, 'Als nun Petrus sich nicht zu erklären wußte, was die Erscheinung, die er gesehen hatte, zu bedeuten habe, siehe, da standen die Männer, die von Kornelius abgesandt worden waren und das Haus Simons ausfindig gemacht hatten, am Toreingang;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 10, 18, 'dort riefen sie und erkundigten sich, ob Simon mit dem Beinamen Petrus hier als Gast wohne.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 10, 19, 'Während Petrus noch immer über das Gesicht nachdachte, sagte der Geist zu ihm: »Da sind drei Männer, die dich suchen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 10, 20, 'So stehe nun auf, gehe hinunter und mache dich mit ihnen ohne Bedenken auf den Weg! Denn ich habe sie gesandt.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 10, 21, 'Petrus stieg also zu den Männern hinunter und sagte zu ihnen: »Ich bin der, den ihr sucht! Aus welchem Grunde seid ihr hergekommen?«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 10, 22, 'Jene antworteten: »Ein Hauptmann Kornelius, ein ehrenhafter, gottesfürchtiger und von der ganzen jüdischen Bevölkerung anerkannter Mann, hat von einem heiligen Engel die (göttliche) Weisung erhalten, dich in sein Haus kommen zu lassen und zu hören, was du ihm zu sagen hast.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 10, 23, 'Da lud Petrus sie zu sich herein und nahm sie gastlich auf. Am folgenden Tage aber machte er sich mit ihnen auf den Weg; auch einige von den Brüdern aus Joppe begleiteten ihn.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 10, 24, 'Tags darauf kam er in Cäsarea an, wo Kornelius sie schon erwartete und alle seine Verwandten und vertrauten Freunde zu sich eingeladen hatte.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 10, 25, 'Als Petrus nun im Begriff stand, in das Haus einzutreten, kam Kornelius ihm entgegen, warf sich vor ihm nieder und bezeigte ihm seine hohe Verehrung.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 10, 26, 'Petrus aber hob ihn auf mit den Worten: »Stehe auf! Ich bin auch nur ein Mensch.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 10, 27, 'Dann trat er im Gespräch mit ihm ein und traf eine zahlreiche Versammlung an,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 10, 28, 'zu der er sagte: »Ihr wißt, wie streng es einem Juden verboten ist, Verkehr mit jemand zu haben, der zu einem anderen Volke gehört, oder gar bei ihm einzukehren. Doch mir hat Gott gezeigt, daß man keinen Menschen als unheilig oder unrein bezeichnen darf.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 10, 29, 'Deshalb habe ich mich auch auf eure Einladung hin ohne Weigerung hier eingefunden. Ich möchte nun aber wissen, aus welchem Grunde ihr mich habt herkommen lassen.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 10, 30, 'Da antwortete Kornelius: »Vor vier Tagen, genau zu dieser Zeit, betete ich um die neunte Stunde in meinem Hause; da stand plötzlich ein Mann in einem glänzenden Gewande vor mir');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 10, 31, 'und sagte: ›Kornelius, dein Gebet hat Erhörung gefunden, und deiner Almosen ist vor Gott gedacht worden.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 10, 32, 'So sende nun nach Joppe und laß Simon, der den Beinamen Petrus führt, herrufen; der ist als Gast im Hause eines Gerbers Simon am Meer.‹');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 10, 33, 'Da habe ich auf der Stelle zu dir gesandt, und ich bin dir dankbar dafür, daß du gekommen bist. Jetzt haben wir nun alle uns hier vor Gottes Angesicht eingefunden, um alles zu vernehmen, was dir vom Herrn aufgetragen worden ist.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 10, 34, 'Da tat Petrus den Mund auf und sagte: »Nun erkenne ich in Wahrheit, daß Gott nicht die Person ansieht,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 10, 35, 'sondern daß in jedem Volk der, welcher ihn fürchtet und Gerechtigkeit übt, ihm angenehm ist.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 10, 36, 'Ihr kennt das Wort, das er an die Kinder Israel hat ergehen lassen, indem er ihnen (die Heilsbotschaft vom) Frieden durch Jesus Christus verkündigen ließ: dieser ist der Herr über alle.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 10, 37, 'Ebenso kennt ihr die Ereignisse, die sich im ganzen jüdischen Lande zugetragen haben und von Galiläa nach der Taufe, die Johannes gepredigt hatte, ausgegangen sind,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 10, 38, 'nämlich wie Gott Jesus von Nazareth mit heiligem Geist und mit Kraft gesalbt hat, wie dieser dann umhergezogen ist und Gutes getan und alle geheilt hat, die vom Teufel überwältigt waren, denn Gott war mit ihm;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 10, 39, 'und wir sind Zeugen für alles das, was er im jüdischen Lande sowie in Jerusalem vollbracht hat. Den haben sie dann zwar ans Kreuz gehängt und getötet,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 10, 40, 'aber Gott hat ihn am dritten Tage auferweckt und ihn sichtbar erscheinen lassen,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 10, 41, 'nicht dem ganzen Volk, sondern uns, den von Gott zuvor erwählten Zeugen, die wir nach seiner Auferstehung von den Toten mit ihm zusammen gegessen und getrunken haben.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 10, 42, 'Und er hat uns geboten, dem Volke zu verkündigen und zu bezeugen, daß dieser der von Gott bestimmte Richter über Lebende und Tote ist.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 10, 43, 'Für diesen legen alle Propheten das Zeugnis ab, daß jeder, der an ihn glaubt, Vergebung der Sünden durch seinen Namen empfängt.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 10, 44, 'Während Petrus noch in dieser Weise redete, fiel der heilige Geist auf alle, die seine Ansprache hörten.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 10, 45, 'Da gerieten die Gläubigen jüdischer Herkunft, die mit Petrus gekommen waren, in das höchste Erstaunen darüber, daß auch auf die Heiden die Gabe des heiligen Geistes ausgegossen war;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 10, 46, 'denn sie hörten sie mit Zungen reden und Gott preisen. Da sprach Petrus:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 10, 47, '»Kann wohl jemand diesen Leuten, die den heiligen Geist ebenso wie wir empfangen haben, das Wasser versagen, daß diese nicht getauft würden?«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 10, 48, 'So ordnete er denn an, daß sie im Namen Jesu Christi getauft würden. Hierauf baten sie ihn, noch einige Tage bei ihnen zu bleiben.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 11, 1, 'Es erhielten aber die Apostel und die Brüder in Judäa Kunde davon, daß auch die Heiden das Wort Gottes angenommen hätten.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 11, 2, 'Als daher Petrus nach Jerusalem zurückgekehrt war, stellten die Gläubigen jüdischer Herkunft ihn zur Rede');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 11, 3, 'und hielten ihm vor: »Du bist bei Nichtjuden eingekehrt und hast mit ihnen gegessen!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 11, 4, 'Da legte Petrus ihnen im einzelnen dar, wie sich alles von Anfang an zugetragen hatte, und berichtete:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 11, 5, '»Ich befand mich in der Stadt Joppe im Gebet; da sah ich im Zustande der Verzückung ein Gesicht: ein Behälter kam herab wie ein großes Stück Leinwand, das an den vier Zipfeln vom Himmel herabgelassen wurde und bis zu mir kam.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 11, 6, 'Als ich dann hineinschaute und es mir genau ansah, erblickte ich darin die vierfüßigen Tiere der Erde, auch die wilden, und die kriechenden Tiere und die Vögel des Himmels.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 11, 7, 'Zugleich vernahm ich auch eine Stimme, die mir zurief: ›Stehe auf, Petrus, schlachte und iß!‹');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 11, 8, 'Ich erwiderte darauf: ›Nicht doch, Herr! Denn noch nie ist etwas Unheiliges und Unreines in meinen Mund gekommen.‹');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 11, 9, 'Aber eine Stimme erscholl zum zweitenmal vom Himmel her: ›Was Gott gereinigt hat, das erkläre du nicht für unrein!‹');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 11, 10, 'Dies wiederholte sich bis zum drittenmal; dann wurde alles wieder in den Himmel hinaufgezogen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 11, 11, 'Und seht, sogleich standen vor dem Hause, in dem wir waren, drei Männer, die aus Cäsarea zu mir gesandt waren;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 11, 12, 'und der Geist gebot mir, ohne alles Bedenken mit ihnen zu gehen. Es begleiteten mich aber auch diese sechs Brüder hier, und wir traten in das Haus des Mannes ein.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 11, 13, 'Der berichtete uns nun, wie er den Engel in seinem Hause gesehen habe, der dagestanden und gesagt hätte: ›Sende nach Joppe und laß Simon mit dem Beinamen Petrus holen;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 11, 14, 'der wird Worte zu dir reden, durch die du mit deinem ganzen Hause gerettet werden wirst.‹');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 11, 15, 'Während ich dann zu reden begann, fiel der heilige Geist auf sie ebenso wie auch auf uns im Anfang.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 11, 16, 'Da gedachte ich an das Wort des Herrn, wie er sagte: ›Johannes hat mit Wasser getauft, ihr aber werdet mit heiligem Geist getauft werden.‹');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 11, 17, 'Wenn somit Gott ihnen die gleiche Gnadengabe verliehen hat wie uns, die wir zum Glauben an den Herrn Jesus Christus gekommen sind, wie wäre ich da imstande gewesen, Gott zu wehren?«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 11, 18, 'Als sie das hörten, beruhigten sie sich und priesen Gott mit den Worten: »So hat Gott also auch den Heiden die Buße zum Leben verliehen!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 11, 19, 'Diejenigen (Gläubigen) nun, welche sich aus Anlaß der Verfolgung, die wegen des Stephanus entstanden war, zerstreut hatten, waren bis nach Phönizien, Cypern und Antiochia gezogen, ohne jedoch jemandem das Wort zu verkündigen als nur Juden.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 11, 20, 'Es befanden sich aber einige Männer aus Cypern und Cyrene unter ihnen, die sich nach ihrer Ankunft in Antiochia auch mit den Griechen besprachen und ihnen die Heilsbotschaft vom Herrn Jesus verkündigten.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 11, 21, 'Und die Hand des Herrn war mit ihnen, so daß eine große Anzahl gläubig wurde und sich zum Herrn bekehrte.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 11, 22, 'Die Kunde hiervon kam der Gemeinde in Jerusalem zu Ohren, die dann den Barnabas nach Antiochia entsandte.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 11, 23, 'Als dieser nach seiner Ankunft dort die Gnade Gottes wahrnahm, freute er sich und ermahnte alle, mit festem Herzen dem Herrn treu zu bleiben;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 11, 24, 'er war nämlich ein trefflicher Mann, erfüllt mit heiligem Geist und mit Glauben. So wurde denn eine ansehnliche Menge für den Herrn hinzugewonnen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 11, 25, 'Barnabas begab sich dann von dort nach Tarsus, um Saulus aufzusuchen;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 11, 26, 'und als er ihn gefunden hatte, nahm er ihn mit nach Antiochia; und es fügte sich dann so, daß sie ein ganzes Jahr hindurch als Gäste in der Gemeinde tätig waren und eine beträchtliche Menge unterwiesen und daß man in Antiochia zuerst den Jüngern den Namen ›Christen‹ (wörtlich: Christianer) beilegte.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 11, 27, 'In dieser Zeit kamen Propheten von Jerusalem nach Antiochia hinab.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 11, 28, 'Einer von ihnen namens Agabus trat auf und weissagte auf Eingebung des Geistes, daß eine große Hungersnot über den ganzen Erdkreis kommen würde, die dann auch wirklich unter der Regierung des (Kaisers) Klaudius eintrat.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 11, 29, 'Da beschlossen die Jünger, jeder von ihnen solle nach Maßgabe seines Vermögens den im jüdischen Lande wohnenden Brüdern eine Unterstützung zukommen lassen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 11, 30, 'Sie führten diesen Beschluß auch aus und ließen es (den Ertrag der Sammlung) durch Vermittlung des Barnabas und Saulus an die Ältesten (der Gemeinde) gelangen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 12, 1, 'Um jene Zeit ließ der König Herodes einige Mitglieder der Gemeinde gefangennehmen, um seine Wut an ihnen auszulassen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 12, 2, 'So ließ er Jakobus, den Bruder des Johannes, mit dem Schwert hinrichten;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 12, 3, 'und als er sah, daß sein Vorgehen den Beifall der Juden fand, ließ er weiter auch Petrus verhaften, und zwar während der Tage der ungesäuerten Brote.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 12, 4, 'Als er ihn nun festgenommen hatte, ließ er ihn ins Gefängnis setzen und übertrug seine Bewachung vier Abteilungen Soldaten von je vier Mann; nach dem Passah wollte er ihn dann dem Volk (zur Aburteilung) vorführen lassen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 12, 5, 'So wurde also Petrus im Gefängnis bewacht, während von der Gemeinde unablässig für ihn zu Gott gebetet wurde.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 12, 6, 'Als ihn nun Herodes (zur Verurteilung) vorführen lassen wollte, schlief Petrus in der Nacht zuvor zwischen zwei Soldaten, mit zwei Ketten gefesselt; außerdem versahen Posten vor der Tür die Bewachung (der Zelle).');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 12, 7, 'Da stand mit einemmal ein Engel des Herrn da, und Lichtschein erhellte den Raum. Der Engel weckte den Petrus durch einen Stoß in die Seite und sagte zu ihm: »Stehe schnell auf!« Zugleich fielen ihm die Ketten von den Armen ab.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 12, 8, 'Weiter sagte der Engel zu ihm: »Gürte dich und binde dir die Sandalen unter!« Das tat Petrus. Dann sagte der Engel zu ihm: »Wirf dir deinen Mantel um und folge mir!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 12, 9, 'So ging Petrus denn hinter ihm her (aus der Zelle) hinaus, wußte aber nicht, daß das, was durch den Engel geschah, Wirklichkeit war; er meinte vielmehr zu träumen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 12, 10, 'Als sie dann an dem ersten und zweiten Wachposten vorübergegangen waren, kamen sie an das eiserne Tor, das zur Stadt hinausführte; dieses öffnete sich ihnen von selbst, und nachdem sie hinausgetreten waren, gingen sie eine Straße weit vorwärts; da verschwand plötzlich der Engel neben ihm.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 12, 11, 'Als Petrus nun zu sich kam, sagte er: »Jetzt weiß ich in Wahrheit, daß der Herr seinen Engel gesandt und mich aus der Hand des Herodes und vor der ganzen Gier des jüdischen Volks gerettet hat.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 12, 12, 'Nachdem er sich hierüber klar geworden war, ging er nach dem Hause der Maria, der Mutter des Johannes, der den Beinamen Markus führte; hier waren viele (Brüder) versammelt und beteten.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 12, 13, 'Als er nun an die Tür des Hoftores geklopft hatte, kam eine Magd namens Rhode herbei, um zu horchen, wer da sei.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 12, 14, 'Als sie Petrus an der Stimme erkannte, schloß sie in ihrer Freude das Tor nicht auf, sondern lief ins Haus hinein und meldete, Petrus stehe vor dem Tor.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 12, 15, 'Jene antworteten ihr: »Du bist von Sinnen!«, doch sie versicherte bestimmt, es verhalte sich so.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 12, 16, 'Da sagten sie: »Es muß sein Engel sein!« Petrus aber fuhr inzwischen beharrlich fort zu pochen; da schlossen sie auf, sahen ihn und gerieten in das höchste Erstaunen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 12, 17, 'Er aber gab ihnen mit der Hand einen Wink, sie möchten sich still verhalten, erzählte ihnen dann, wie der Herr ihn aus dem Gefängnis herausgeführt habe, und gab ihnen den Auftrag: »Teilt dies dem Jakobus und den (übrigen) Brüdern mit!« Darauf entfernte er sich und begab sich an einen anderen Ort.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 12, 18, 'Nach Tagesanbruch aber entstand eine nicht geringe Bestürzung unter den Soldaten, was wohl mit Petrus geschehen sei.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 12, 19, 'Herodes wollte ihn nämlich holen lassen; und als er ihn nicht vorfand, stellte er ein Verhör mit den Wächtern an und ließ sie (zur Hinrichtung) abführen. Darnach begab er sich aus Judäa nach Cäsarea hinab und verlegte dorthin seine Hofhaltung.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 12, 20, 'Er war damals aber gegen die Einwohner von Tyrus und Sidon erbittert; diese schickten jedoch nach gemeinsamem Beschluß eine Gesandtschaft an ihn, gewannen Blastus, den königlichen Kammerherrn, für sich und baten um Frieden; ihr Land war nämlich bezüglich der Zufuhr auf das Land des Königs angewiesen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 12, 21, 'Am festgesetzten Tage nun legte Herodes königliche Gewandung an, nahm auf der Rednerbühne Platz und hielt eine Ansprache an sie.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 12, 22, 'Dabei rief das Volk ihm zu: »Ein Gott redet und nicht ein Mensch!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 12, 23, 'Da schlug ihn augenblicklich ein Engel des Herrn zur Strafe dafür, daß er nicht Gott die Ehre gegeben hatte: er erkrankte am Wurmfraß und beschloß sein Leben.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 12, 24, 'Das Wort Gottes jedoch wuchs und breitete sich immer weiter aus.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 12, 25, 'Barnabas und Saulus aber kehrten nach Ausrichtung ihres Auftrags von Jerusalem (nach Antiochia) zurück und nahmen auch Johannes mit dem Beinamen Markus mit sich.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 13, 1, 'In Antiochia wirkten damals in der dortigen Gemeinde folgende Propheten und Lehrer: Barnabas, Symeon mit dem Beinamen Niger, Lucius aus Cyrene, Manaën, der mit dem Vierfürsten Herodes erzogen worden war, und Saulus.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 13, 2, 'Als sie nun einst dem Herrn Gottesdienst hielten und fasteten, gebot der heilige Geist: »Sondert mir doch Barnabas und Saulus für das Werk aus, zu dem ich sie berufen habe!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 13, 3, 'Da fasteten und beteten sie, legten ihnen die Hände auf und ließen sie ziehen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 13, 4, 'So gingen denn die beiden, vom heiligen Geist ausgesandt, nach Seleucia hinab, fuhren von dort zu Schiff nach Cypern');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 13, 5, 'und verkündigten nach ihrer Ankunft dort in Salamis das Wort Gottes in den Synagogen der Juden; als Gehilfen hatten sie noch Johannes (Markus) bei sich.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 13, 6, 'Nachdem sie nun die ganze Insel bis nach Paphos durchzogen hatten, trafen sie dort einen jüdischen Zauberer und falschen Propheten namens Barjesus,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 13, 7, 'der zu der Umgebung des (römischen) Statthalters Sergius Paulus, eines verständigen Mannes, gehörte. Dieser ließ Barnabas und Saulus zu sich rufen und wünschte von ihnen das Wort Gottes zu hören.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 13, 8, 'Da trat aber Elymas, der Zauberer – so lautet nämlich sein Name übersetzt –, ihnen entgegen und suchte den Statthalter vom Glauben abzuhalten.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 13, 9, 'Saulus aber, der auch Paulus heißt, blickte ihn fest an und sagte, voll heiligen Geistes:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 13, 10, '»O du Teufelssohn, der du ganz voll von lauter Lug und Trug bist, du Feind aller Gerechtigkeit, wirst du nicht aufhören, die geraden Wege des Herrn krumm zu machen?');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 13, 11, 'Jetzt aber kommt die Hand des Herrn über dich: du sollst blind sein und das Sonnenlicht eine Zeitlang nicht sehen!« Da fiel augenblicklich Dunkel und Finsternis auf ihn: er tappte umher und suchte nach jemandem, der ihn an der Hand führen sollte.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 13, 12, 'Als der Statthalter den Vorgang sah, kam er zum Glauben und war voll Staunens über die (Kraft der) Lehre des Herrn.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 13, 13, 'Von Paphos gingen Paulus und seine Gefährten wieder in See und kamen nach Perge in Pamphylien; hier trennte sich Johannes von ihnen und kehrte nach Jerusalem zurück.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 13, 14, 'Sie aber zogen von Perge aus landeinwärts weiter und gelangten nach dem pisidischen Antiochia, wo sie am Sabbattage in die Synagoge gingen und sich dort (auf den für Fremde bestimmten Plätzen) niedersetzten.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 13, 15, 'Nach der Schriftverlesung aus dem Gesetz und den Propheten ließen ihnen die Vorsteher der Synagoge sagen: »Werte Brüder, wenn ihr eine erbauliche Ansprache an das Volk zu richten habt, so redet!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 13, 16, 'Da stand Paulus auf, gab einen Wink mit der Hand und sagte: »Ihr Männer von Israel und ihr, die ihr Gott fürchtet, hört mich an!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 13, 17, 'Der Gott unsers Volkes Israel hat unsere Väter sich erwählt und unser Volk während seines Aufenthalts in dem fremden Lande Ägypten emporgebracht und sie dann mit hocherhobenem Arm von dort weggeführt.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 13, 18, 'Während einer Zeit von ungefähr vierzig Jahren hat er sie dann in der Wüste mit schonender Liebe getragen,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 13, 19, 'hat sieben Völker im Lande Kanaan vernichtet und ihnen deren Land zum Besitz gegeben;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 13, 20, 'das hat ungefähr vierhundertfünfzig Jahre gedauert. Hierauf gab er ihnen Richter bis auf den Propheten Samuel.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 13, 21, 'Von da an wollten sie einen König haben, und Gott gab ihnen Saul, den Sohn des Kis, einen Mann aus dem Stamme Benjamin, für vierzig Jahre.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 13, 22, 'Nach dessen Verwerfung erhob er David zum König über sie; ihm hat er dann auch das Zeugnis erteilt: ›Ich habe David gefunden, den Sohn Isais, einen Mann nach meinem Herzen, der in allem meinen Willen tun wird.‹');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 13, 23, 'Dieser ist’s, aus dessen Nachkommenschaft Gott jetzt nach seiner Verheißung Jesus als Retter für Israel hat hervorgehen lassen,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 13, 24, 'nachdem vor dessen Auftreten Johannes dem ganzen Volk Israel eine Taufe der Buße verkündigt hatte.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 13, 25, 'Als aber Johannes am Abschluß seiner Laufbahn stand, erklärte er: ›Das, wofür ihr mich haltet, bin ich nicht; doch wisset wohl, nach mir kommt der, für den ich nicht gut genug bin, ihm die Schuhe von den Füßen loszubinden!‹');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 13, 26, 'Werte Brüder, Söhne von Abrahams Geschlecht, und ihr anderen hier, die ihr Gott fürchtet: an uns ist diese Heilsverkündigung ergangen!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 13, 27, 'Denn die Bewohner Jerusalems und ihre Oberen haben, obwohl sie diesen Jesus nicht erkannten, doch die Aussprüche der Propheten, die an jedem Sabbat zur Verlesung kommen, durch ihr Verdammungsurteil zur Erfüllung gebracht');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 13, 28, 'und, obwohl sie keine todeswürdige Schuld an ihm fanden, doch seine Hinrichtung von Pilatus verlangt.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 13, 29, 'Nachdem sie schließlich alles ausgeführt hatten, was über ihn in der Schrift steht, haben sie ihn vom Kreuz herabgenommen und ihn in ein Grab gelegt.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 13, 30, 'Gott aber hat ihn von den Toten auferweckt,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 13, 31, 'und mehrere Tage hindurch ist er denen erschienen, die mit ihm aus Galiläa nach Jerusalem hinaufgezogen waren und die jetzt Zeugen für ihn dem Volk gegenüber sind.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 13, 32, 'Und wir bringen euch die das Heil verkündende Botschaft, daß Gott die Verheißung, die unsern Vätern einst zuteil geworden ist,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 13, 33, 'für uns, die Nachkommen jener, durch die Auferweckung Jesu zur Erfüllung gebracht hat, wie ja auch im zweiten Psalm geschrieben steht: ›Du bist mein Sohn, ich habe dich heute gezeugt.‹');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 13, 34, 'Daß er ihn aber von den Toten auferweckt hat, um ihn nicht wieder der Verwesung anheimfallen zu lassen, hat er mit den Worten ausgesprochen: ›Ich will euch die heiligen, dem David verheißenen unverbrüchlichen Güter verleihen.‹');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 13, 35, 'Darum heißt es auch an einer andern Stelle: ›Du wirst nicht zulassen, daß dein Heiliger die Verwesung sieht.‹');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 13, 36, 'Denn David selbst ist doch entschlafen, nachdem er zu seiner Zeit dem Willen Gottes gedient hatte: er ist zu seinen Vätern versammelt worden und hat die Verwesung gesehen;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 13, 37, 'der aber, den Gott auferweckt hat, der hat die Verwesung nicht gesehen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 13, 38, 'So soll euch denn kundgetan sein, werte Brüder, daß euch durch diesen (Jesus) die Vergebung der Sünden verkündigt wird,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 13, 39, 'und von allem, wovon ihr durch das mosaische Gesetz keine Rechtfertigung habt erlangen können, wird in diesem ein jeder gerechtfertigt, der da glaubt.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 13, 40, 'Darum seht wohl zu, daß [bei euch] nicht das Prophetenwort zutreffe:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 13, 41, '›Seht, ihr Verächter, verwundert euch und vergeht! Denn ein Werk vollführe ich in euren Tagen, ein Werk, das ihr gewiß nicht glauben würdet, wenn jemand es euch erzählte.‹«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 13, 42, 'Als sie dann die Synagoge verließen, sprach man die Bitte gegen sie aus, sie möchten am nächsten Sabbat von diesen Dingen noch weiter zu ihnen reden.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 13, 43, 'Nachdem nun die Synagogen-Versammlung auseinandergegangen war, folgten viele von den Juden und den gottesfürchtigen Heidenjuden dem Paulus und Barnabas nach; diese redeten ihnen eifrig zu und ermahnten sie, in der Gnade Gottes zu verharren.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 13, 44, 'Am folgenden Sabbat aber fand sich beinahe die ganze Stadt ein, um das Wort Gottes zu hören.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 13, 45, 'Als jedoch die Juden die Volksmenge sahen, wurden sie mit Eifersucht erfüllt und widersprachen den Darlegungen des Paulus unter Schmähungen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 13, 46, 'Da erklärten ihnen Paulus und Barnabas mit Freimut: »Euch (Juden) mußte das Wort Gottes zuerst verkündigt werden; weil ihr es aber zurückstoßt und euch selbst des ewigen Lebens nicht für würdig erachtet, so wenden wir uns nunmehr zu den Heiden!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 13, 47, 'Denn so hat uns der Herr geboten: ›Ich habe dich zum Licht der Heiden gemacht, damit du zum Heil werdest bis ans Ende der Erde.‹«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 13, 48, 'Als die Heiden das hörten, freuten sie sich und priesen das Wort des Herrn; und alle, soweit sie zum ewigen Leben verordnet waren, wurden gläubig.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 13, 49, 'So verbreitete sich denn das Wort des Herrn durch die ganze Gegend.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 13, 50, 'Die Juden aber hetzten die vornehmen Frauen, die sich zum Judentum hielten, und die angesehensten Männer der Stadt auf, erregten eine Verfolgung gegen Paulus und Barnabas und vertrieben sie aus dem Gebiet ihrer Stadt.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 13, 51, 'Da schüttelten diese den Staub von ihren Füßen (zum Zeugnis) gegen sie und begaben sich nach Ikonium;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 13, 52, 'die Jünger aber wurden mit Freude und mit heiligem Geist erfüllt.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 14, 1, 'In Ikonium gingen sie in derselben Weise (wie in Antiochia) in die Synagoge der Juden und predigten mit solchem Erfolg, daß sowohl von den Juden als auch von den Griechen eine große Zahl zum Glauben kam.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 14, 2, 'Von den Juden aber reizten die, welche ungläubig geblieben waren, die heidnische Bevölkerung zur Erbitterung gegen die Brüder an.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 14, 3, 'Dennoch blieben Paulus und Barnabas geraume Zeit dort und predigten freimütig im Vertrauen auf den Herrn, der für das Wort seiner Gnade dadurch Zeugnis ablegte, daß er Zeichen und Wunder durch ihre Hände geschehen ließ.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 14, 4, 'Da entstand eine Spaltung unter der Bevölkerung der Stadt: die einen hielten es mit den Juden, die anderen mit den Aposteln.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 14, 5, 'Als aber die Heiden und die Juden im Einvernehmen mit der dortigen Obrigkeit voller Wut den Beschluß faßten, sich tätlich an ihnen zu vergreifen und sie zu steinigen,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 14, 6, 'entflohen sie, nachdem sie Kunde davon erhalten hatten, in die lykaonischen Städte Lystra und Derbe und deren Umgegend');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 14, 7, 'und setzten auch dort die Verkündigung der Heilsbotschaft fort.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 14, 8, 'Nun wohnte da in Lystra ein Mann, der keine Kraft in seinen Beinen hatte; er war von Geburt an lahm und hatte noch niemals gehen können.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 14, 9, 'Dieser hörte der Predigt des Paulus zu; und als dieser ihn fest ansah und erkannte, daß er den Glauben hatte, der zu seiner Heilung nötig war,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 14, 10, 'rief er ihm mit lauter Stimme zu: »Stelle dich aufrecht auf deine Füße hin!« Da sprang er auf und ging umher.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 14, 11, 'Als nun die Volksmenge sah, was Paulus getan hatte, erhoben sie ihre Stimme und riefen auf lykaonisch aus: »Die Götter haben Menschengestalt angenommen und sind zu uns herabgekommen!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 14, 12, 'Dabei nannten sie Barnabas Zeus und den Paulus Hermes, weil dieser es war, der das Wort führte;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 14, 13, 'und der Priester des Zeus, der vor der Stadt seinen Tempel hatte, brachte Stiere und Kränze an das Stadttor und wollte mit den Volksscharen Opfer darbringen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 14, 14, 'Als die Apostel Barnabas und Paulus das vernahmen, zerrissen sie ihre Kleider, sprangen in die Volksmenge hinein');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 14, 15, 'und riefen laut: »Ihr Männer, was tut ihr da? Wir sind auch nur Menschen von derselben Art wie ihr und verkündigen euch die Heilsbotschaft, damit ihr euch von diesen Verkehrtheiten zu dem lebendigen Gott bekehrt, der den Himmel und die Erde, das Meer und alles, was darin ist, geschaffen hat.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 14, 16, 'Er hat in den vergangenen Zeiten alle Heidenvölker ihre eigenen Wege gehen lassen,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 14, 17, 'doch sich durch seine Wohltaten nicht unbezeugt gelassen, indem er euch Regen und fruchtbare Zeiten vom Himmel her gesandt und euch reichlich Nahrung geschenkt und eure Herzen mit Freude erfüllt hat.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 14, 18, 'Durch diese Worte brachten sie die Menge nur mit Mühe davon ab, ihnen zu opfern.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 14, 19, 'Es kamen dann aber Juden aus Antiochia und Ikonium herüber, welche die Einwohnerschaft umstimmten; sie steinigten Paulus und schleiften ihn zur Stadt hinaus in der Meinung, er sei tot.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 14, 20, 'Als ihn aber die Jünger umringten, stand er auf und ging wieder in die Stadt hinein.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 14, 21, 'a Am folgenden Tage zog er dann mit Barnabas nach Derbe weiter. b Sie verkündigten die Heilsbotschaft (auch) in dieser Stadt und kehrten, nachdem sie zahlreiche Jünger gewonnen hatten, nach Lystra, Ikonium und (dem pisidischen) Antiochia zurück.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 14, 22, 'Sie stärkten überall die Herzen der Jünger, ermahnten sie zu festem Ausharren im Glauben und wiesen sie darauf hin, daß wir durch viele Leiden in das Reich Gottes eingehen müssen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 14, 23, 'Sie erwählten ihnen für jede Gemeinde Älteste und befahlen diese unter Gebet und Fasten dem Herrn, an den sie gläubig geworden waren.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 14, 24, 'Als sie dann Pisidien durchzogen hatten, kamen sie nach Pamphylien,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 14, 25, 'wo sie in Perge das Wort (des Herrn) noch predigten; dann zogen sie nach Attalia hinab.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 14, 26, 'Von dort fuhren sie zu Schiff nach Antiochia, von wo aus sie der Gnade Gottes für das Werk, das sie nun glücklich vollbracht hatten, befohlen worden waren.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 14, 27, 'Nach ihrer Ankunft beriefen sie eine Gemeindeversammlung und berichteten über alles, was Gott durch sie vollbracht hatte, besonders darüber, daß er den Heiden die Tür zum Glauben aufgetan habe.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 14, 28, 'Sie blieben sodann noch längere Zeit bei den Jüngern dort.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 15, 1, 'Da trugen einige (Gläubige), die aus Judäa (nach Antiochia) herabgekommen waren, den Brüdern die Lehre vor: »Wenn ihr euch nicht nach mosaischem Brauch beschneiden laßt, könnt ihr die Rettung nicht erlangen!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 15, 2, 'Als nun dadurch eine Aufregung (in der Gemeinde) und ein heftiger Streit zwischen diesen Männern und Paulus und Barnabas entstanden war, faßte man den Beschluß, Paulus und Barnabas nebst einigen anderen aus ihrer Mitte sollten wegen dieser Streitfrage zu den Aposteln und Ältesten nach Jerusalem hinaufziehen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 15, 3, 'Diese wurden also von der Gemeinde feierlich entlassen und reisten dann durch Phönizien und Samarien, wobei sie (überall) von der Bekehrung der Heiden berichteten und dadurch allen Brüdern große Freude bereiteten.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 15, 4, 'Nach ihrer Ankunft in Jerusalem wurden sie von der Gemeinde und von den Aposteln und den Ältesten empfangen und berichteten alles, was Gott durch sie vollführt hatte.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 15, 5, 'Da traten einige, die zu der Partei der Pharisäer gehört hatten und gläubig geworden waren, mit der Forderung auf, man müsse (die Heidenchristen) beschneiden und von ihnen die Beobachtung des mosaischen Gesetzes verlangen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 15, 6, 'So traten denn die Apostel und die Ältesten zur Beratung über diese Frage zusammen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 15, 7, 'Nachdem nun eine lange, erregte Erörterung stattgefunden hatte, stand Petrus auf und sprach zu ihnen: »Werte Brüder! Ihr wißt, daß Gott schon vor längerer Zeit mich in eurem Kreise dazu erwählt hat, daß die Heiden durch meinen Mund das Wort der Heilsbotschaft vernehmen und so zum Glauben kommen sollten.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 15, 8, 'Und Gott, der Herzenskenner, hat selbst Zeugnis für sie dadurch abgelegt, daß er ihnen den heiligen Geist gerade so verliehen hat wie uns:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 15, 9, 'er hat keinen Unterschied zwischen uns und ihnen gemacht, indem er ihre Herzen durch den Glauben gereinigt hat.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 15, 10, 'Warum versucht ihr also jetzt Gott dadurch, daß ihr den Jüngern ein Joch auf den Nacken legen wollt, das weder unsere Väter noch wir zu tragen vermocht haben?');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 15, 11, 'Nein, durch die Gnade des Herrn Jesus glauben wir auf dieselbe Weise die Rettung zu erlangen wie jene auch.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 15, 12, 'Da schwieg die ganze Versammlung still und schenkte dem Barnabas und Paulus Gehör, die einen Bericht über alle die Zeichen und Wunder erstatteten, die Gott unter den Heiden durch sie getan hatte.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 15, 13, 'Als sie damit zu Ende waren, nahm Jakobus das Wort zu folgender Ansprache: »Werte Brüder, hört mich an!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 15, 14, 'Symeon hat berichtet, wie Gott selbst zuerst darauf bedacht gewesen ist, ein Volk aus den Heiden für seinen Namen zu gewinnen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 15, 15, 'Und damit stimmen die Worte der Propheten überein; denn es steht geschrieben:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 15, 16, '›Hierauf will ich umkehren und die zerfallene Hütte Davids wieder aufbauen; ich will ihre Trümmer wieder aufrichten und sie selbst neu erstehen lassen,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 15, 17, 'damit die Menschen, welche übriggeblieben sind, den Herrn suchen, auch alle Heiden, die mir als mein Volk zu eigen gehören, spricht der Herr, der dieses vollbringt,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 15, 18, 'wie es von Ewigkeit her kund geworden ist.‹');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 15, 19, 'Deshalb bin ich meinerseits der Ansicht, man solle denen, die aus der Heidenwelt sich zu Gott bekehren, keine (unnötigen) Lasten aufbürden,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 15, 20, 'sondern ihnen nur die Verpflichtung auferlegen, sich von der Verunreinigung durch die Götzen, von der Unzucht, vom Fleisch erstickter Tiere und vom (Genuß von) Blut fernzuhalten.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 15, 21, 'Denn Mose hat seit alten Zeiten in jeder Stadt seine Verkündiger, weil er ja in den Synagogen an jedem Sabbat vorgelesen wird.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 15, 22, 'Hierauf beschlossen die Apostel und die Ältesten im Einvernehmen mit der ganzen Gemeinde, Männer aus ihrer Mitte zu wählen und sie mit Paulus und Barnabas nach Antiochia zu senden, nämlich Judas mit dem Beinamen Barsabbas und Silas, zwei Männer, die unter den Brüdern eine führende Stellung einnahmen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 15, 23, 'Durch diese ließen sie folgendes Schreiben überbringen: »Wir Apostel und Älteste senden als Brüder unseren Brüdern, den Heidenchristen in Antiochia, Syrien und Cilicien, unsern Gruß.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 15, 24, 'Da wir vernommen haben, daß einige aus unserer Mitte zu euch gekommen sind und euch durch Reden beunruhigt und eure Seelen in Aufregung versetzt haben, ohne daß sie einen Auftrag dazu von uns erhalten hatten,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 15, 25, 'so haben wir in einer Versammlung den einmütigen Beschluß gefaßt, Männer zu erwählen und zu euch zu senden zusammen mit unserm geliebten Barnabas und Paulus,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 15, 26, 'zwei Männer, die ihre Seele für den Namen unsers Herrn Jesus Christus eingesetzt haben.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 15, 27, 'Wir haben also Judas und Silas abgesandt, die euch dasselbe auch noch mündlich mitteilen werden.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 15, 28, 'Es ist nämlich des heiligen Geistes und unser Beschluß, euch keine weitere Last aufzubürden als folgende Stücke, die unerläßlich sind:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 15, 29, 'daß ihr euch vom Götzenopferfleisch, vom Blutgenuß, vom Fleisch erstickter Tiere und von Unzucht fernhaltet. Wenn ihr euch davor bewahrt, werdet ihr euch gut dabei stehen. Gehabt euch wohl!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 15, 30, 'So wurden diese denn verabschiedet und kamen nach Antiochia, wo sie die Gemeinde beriefen und das Schreiben übergaben.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 15, 31, 'Als jene es gelesen hatten, freuten sie sich über den tröstlichen Zuspruch.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 15, 32, 'Judas aber und Silas, welche Propheten waren, spendeten auch ihrerseits den Brüdern durch viele Ansprachen Zuspruch und stärkten sie (im Glauben).');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 15, 33, 'Nachdem sie dann einige Zeit dort zugebracht hatten, wurden sie von den Brüdern in Frieden wieder zu ihren Auftraggebern entlassen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 15, 34, 'Silas aber entschloß sich, dort zu bleiben.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 15, 35, 'Paulus und Barnabas blieben dann in Antiochia, indem sie das Wort des Herrn lehrten und die Heilsbotschaft mit noch vielen anderen verkündigten.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 15, 36, 'Nach einiger Zeit aber sagte Paulus zu Barnabas: »Laß uns doch wieder ausziehen und in allen Städten, in denen wir das Wort des Herrn verkündigt haben, uns nach den Brüdern umsehen, wie es mit ihnen steht!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 15, 37, 'Nun wollte Barnabas auch den Johannes mit dem Beinamen Markus (wieder) mitnehmen;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 15, 38, 'Paulus aber hielt es nicht für recht, einen Mann mitzunehmen, der sich (das vorige Mal) in Pamphylien von ihnen getrennt und sie nicht auf das Arbeitsfeld begleitet hatte.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 15, 39, 'So kam es denn zwischen beiden zu einem hitzigen Streit, infolgedessen sie sich voneinander trennten: Barnabas nahm den Markus zu sich und fuhr zu Schiff nach Cypern;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 15, 40, 'Paulus dagegen wählte sich Silas zum Begleiter und trat (mit ihm) die Landreise an, nachdem er von den Brüdern der Gnade des Herrn anbefohlen worden war.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 15, 41, 'Er durchzog (zunächst) Syrien und Cilicien und stärkte die dortigen Gemeinden.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 16, 1, 'Weiter kam er dann auch nach Derbe und Lystra. Und siehe, hier war ein Jünger namens Timotheus – der Sohn einer gläubig gewordenen Jüdin, aber eines griechischen Vaters –,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 16, 2, 'dem von den Brüdern in Lystra und Ikonium ein empfehlendes Zeugnis ausgestellt wurde.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 16, 3, 'Paulus wünschte diesen als Begleiter auf der Reise zu haben; so nahm er ihn denn zu sich und vollzog die Beschneidung an ihm mit Rücksicht auf die Juden, die in jenen Gegenden (wohnhaft) waren; denn es wußten ja alle, daß sein Vater ein Grieche war.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 16, 4, 'Auf ihrer Wanderung durch die Städte machten sie den Gläubigen dort zur Pflicht, die von den Aposteln und Ältesten in Jerusalem beschlossenen Satzungen zu beobachten.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 16, 5, 'So wurden denn die Gemeinden von ihnen im Glauben gestärkt und nahmen täglich an Zahl zu.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 16, 6, 'Sie zogen dann weiter durch Phrygien und das galatische Land, weil sie vom heiligen Geist daran gehindert wurden, die Heilsbotschaft in (der römischen Provinz) Asien zu verkündigen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 16, 7, 'Als sie aber in die Nähe von Mysien gekommen waren, machten sie den Versuch, nach Bithynien zu gelangen, doch der Geist Jesu gestattete es ihnen nicht;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 16, 8, 'sie zogen vielmehr an der Grenze von Mysien hin und kamen so an die Küste nach Troas hinunter.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 16, 9, 'Hier erschien dem Paulus nachts ein Traumgesicht: Ein mazedonischer Mann stand da und sprach die Bitte gegen ihn aus: »Komm nach Mazedonien herüber und hilf uns!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 16, 10, 'Als er diese Erscheinung gesehen hatte, suchten wir sofort eine Gelegenheit, nach Mazedonien zu gelangen, weil wir aus ihr schlossen, daß Gott uns dazu berufen habe, ihnen die Heilsbotschaft zu verkündigen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 16, 11, 'So segelten wir denn von Troas ab und fuhren geradeswegs nach Samothrake, am folgenden Tage nach Neapolis');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 16, 12, 'und von dort nach Philippi, welches die erste Stadt des (dortigen) mazedonischen Bezirks ist, eine römische Kolonie. In dieser Stadt blieben wir einige Tage');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 16, 13, 'und gingen am Sabbattage zum Stadttor hinaus an den Fluß, wo wir eine (jüdische) Gebetsstätte vermuteten. Wir setzten uns dort nieder und redeten zu den Frauen, die sich da versammelt hatten.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 16, 14, 'Unter den Zuhörerinnen befand sich auch eine gottesfürchtige Frau namens Lydia, eine Purpurhändlerin aus der Stadt Thyatira (in Lydien); ihr öffnete der Herr das Herz, so daß sie den Worten des Paulus Beachtung schenkte.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 16, 15, 'Als sie sich dann samt ihren Hausgenossen hatte taufen lassen, sprach sie die Bitte aus: »Wenn ihr wirklich in mir eine treue Jüngerin des Herrn erkannt habt, so kommt in mein Haus und wohnt bei mir!« So nötigte sie uns (zu sich).');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 16, 16, 'Als wir nun (eines Tages wieder) auf dem Wege zu der Gebetsstätte waren, begegnete uns eine Magd, die von einem Wahrsagegeist besessen war und ihrer Herrschaft durch ihr Wahrsagen viel Geld einbrachte.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 16, 17, 'Die ging hinter Paulus und uns her und rief laut: »Diese Männer sind Diener des höchsten Gottes, die euch den Weg zur Rettung verkündigen!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 16, 18, 'Das setzte sie viele Tage hindurch fort. Darüber wurde Paulus unwillig; er wandte sich um und sprach zu dem Geist: »Ich gebiete dir im Namen Jesu Christi, von ihr auszufahren!«, und er fuhr wirklich auf der Stelle aus.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 16, 19, 'Als nun die Herrschaft sah, daß es mit ihrer Hoffnung auf Geldgewinn vorbei war, ergriffen sie den Paulus und Silas, schleppten sie auf den Marktplatz vor die Behörde,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 16, 20, 'führten sie vor die Stadtrichter und sagten: »Diese Menschen stören die Ruhe in unserer Stadt; sie sind Juden');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 16, 21, 'und verkünden Gebräuche, die wir als Römer nicht annehmen und ausüben dürfen.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 16, 22, 'Da trat die Volksmenge gleichfalls gegen sie auf, und die Stadtrichter ließen ihnen die Kleider vom Leibe reißen und ordneten ihre Auspeitschung an.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 16, 23, 'Nachdem sie ihnen dann viele Stockschläge hatten verabfolgen lassen, setzten sie sie ins Gefängnis mit der Weisung an den Gefängnisaufseher, er solle sie in sicherem Gewahrsam halten.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 16, 24, 'Der warf sie auf diesen Befehl hin in die innerste Zelle des Gefängnisses und schloß ihnen die Füße in den Block ein.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 16, 25, 'Um Mitternacht aber beteten Paulus und Silas und priesen Gott in Lobliedern; die übrigen Gefangenen aber hörten ihnen zu.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 16, 26, 'Da entstand plötzlich ein starkes Erdbeben, so daß die Grundmauern des Gefängnisses erbebten; sofort sprangen sämtliche Türen auf, und allen fielen die Fesseln von selbst ab.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 16, 27, 'Als nun der Gefängnisaufseher aus dem Schlaf erwachte und die Türen der Gefängniszellen offenstehen sah, zog er sein Schwert und wollte sich das Leben nehmen; denn er dachte, die Gefangenen seien entflohen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 16, 28, 'Paulus jedoch rief mit lauter Stimme: »Tu dir kein Leid an, denn wir sind alle noch hier!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 16, 29, 'Da rief jener nach Licht, stürzte in die Zelle hinein und warf sich zitternd vor Paulus und Silas nieder;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 16, 30, 'dann führte er sie hinaus und fragte sie: »Ihr Herren, was muß ich tun, um gerettet zu werden?«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 16, 31, 'Sie antworteten: »Glaube an den Herrn Jesus, so wirst du mit deinem Hause gerettet werden.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 16, 32, 'Nun verkündigten sie ihm und allen seinen Hausgenossen das Wort des Herrn.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 16, 33, 'Da nahm er sie noch in derselben Stunde der Nacht zu sich, wusch ihnen die blutigen Striemen ab und ließ sich mit all den Seinen sogleich taufen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 16, 34, 'Danach führte er sie in seine Wohnung hinauf, ließ ihnen den Tisch decken und frohlockte mit seinem ganzen Hause, daß er zum Glauben an Gott gekommen war.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 16, 35, 'Als es dann Tag geworden war, schickten die Stadtrichter ihre Gerichtsdiener und ließen sagen: »Laß jene Männer frei!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 16, 36, 'Der Gefängnisaufseher teilte dem Paulus diese Botschaft mit: »Die Stadtrichter haben sagen lassen, ihr sollt freigelassen werden; so geht jetzt also hinaus und zieht in Frieden weiter!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 16, 37, 'Paulus aber entgegnete ihnen: »Sie haben uns ohne Verhör und Urteil öffentlich auspeitschen lassen, obgleich wir römische Bürger sind, haben uns ins Gefängnis gesetzt und wollen uns jetzt unter der Hand ausweisen? O nein! Sie sollen selbst herkommen und uns hinausgeleiten!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 16, 38, 'Die Gerichtsdiener überbrachten diese Antwort den Stadtrichtern. Diese bekamen einen Schrecken, als sie hörten, daß es sich um römische Bürger handle;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 16, 39, 'sie kamen also, entschuldigten sich bei ihnen und führten sie (aus dem Gefängnis) hinaus mit der Bitte, sie möchten die Stadt verlassen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 16, 40, 'Da gingen sie aus dem Gefängnis hinaus und begaben sich zu Lydia, besuchten dann die Brüder, sprachen ihnen zu und zogen weiter.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 17, 1, 'Nachdem sie durch Amphipolis und Apollonia gewandert waren, kamen sie nach Thessalonike, wo es eine Synagoge der Juden gab.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 17, 2, 'Nach seiner Gewohnheit ging Paulus zu ihnen hinein und besprach sich an drei Sabbaten mit ihnen auf Grund der Schriftworte,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 17, 3, 'die er ihnen auslegte und aus denen er dartat, daß Christus leiden und von den Toten auferstehen mußte, und (so schloß er): »Dieser Jesus, den ich euch verkündige, ist Christus.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 17, 4, 'Einige von ihnen ließen sich auch überzeugen und wurden für Paulus und Silas gewonnen, ebenso auch gottesfürchtige Griechen in großer Zahl und nicht wenige von den vornehmsten Frauen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 17, 5, 'Darüber wurden aber die Juden eifersüchtig, nahmen einige schlechte Männer aus dem Straßengesindel zu Hilfe, erregten einen Volksauflauf und brachten die Stadt in Aufruhr; dann stellten sie sich vor dem Hause Jasons auf und suchten dort nach Paulus und Silas, um sie dem versammelten Volke vorzuführen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 17, 6, 'Als man sie dort aber nicht fand, schleppten sie den Jason und einige Brüder vor die Oberhäupter der Stadt, wobei sie schrien: »Diese Menschen, die den ganzen Erdkreis aufgewiegelt haben, sind jetzt auch hierher gekommen:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 17, 7, 'Jason hat sie bei sich aufgenommen, und diese Leute verstoßen alle gegen die Verordnungen des Kaisers, denn sie behaupten, ein anderer sei König, nämlich Jesus.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 17, 8, 'Durch solche Reden versetzten sie die Volksmenge und auch die Oberhäupter der Stadt in Aufregung;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 17, 9, 'diese ließen sich von Jason und den anderen die erforderliche Bürgschaft stellen und gaben sie dann frei.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 17, 10, 'Die Brüder aber veranlaßten den Paulus und Silas sogleich noch während der Nacht dazu, nach Beröa aufzubrechen, wo sie sich nach ihrer Ankunft in die Synagoge der Juden begaben.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 17, 11, 'Diese waren edler gesinnt als die Juden in Thessalonike: sie nahmen das Wort mit aller Bereitwilligkeit an und forschten Tag für Tag in den (heiligen) Schriften, ob dies (alles) sich so verhalte.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 17, 12, 'So wurden denn viele von ihnen gläubig, auch von den vornehmen griechischen Frauen und Männern nicht wenige.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 17, 13, 'Als jedoch die Juden in Thessalonike erfuhren, daß auch in Beröa das Wort Gottes von Paulus verkündigt worden sei, kamen sie auch dorthin und versetzten die Volksmassen in Unruhe und Aufregung.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 17, 14, 'Da ließen die Brüder den Paulus sogleich (aus der Stadt) weggehen, damit er sich ans Meer begäbe, während Silas und Timotheus dort (in Beröa) zurückblieben.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 17, 15, 'Die Geleiter des Paulus aber brachten ihn bis Athen und kehrten dann von dort wieder zurück mit dem Auftrag an Silas und Timotheus, sie möchten möglichst bald zu ihm kommen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 17, 16, 'Während Paulus nun in Athen auf sie wartete, wurde er innerlich schmerzlich erregt, weil er die Stadt voll von Götterbildern sah.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 17, 17, 'Er besprach sich in der Synagoge mit den Juden und den zum Judentum übergetretenen Griechen, ebenso auf dem Markte Tag für Tag mit denen, die er dort gerade antraf.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 17, 18, 'Aber auch einige epikureische und stoische Philosophen ließen sich mit ihm ein, und manche sagten: »Was fällt denn diesem Schwätzer ein zu behaupten?« Andere aber meinten: »Er scheint ein Verkünder fremder Gottheiten zu sein« – er verkündigte nämlich die Heilsbotschaft von Jesus und von der Auferstehung.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 17, 19, 'So nahmen sie ihn denn mit sich, führten ihn auf den Areshügel und fragten: »Dürfen wir erfahren, was das für eine neue Lehre ist, die du vorträgst?');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 17, 20, 'Du gibst uns seltsame Dinge zu hören; darum möchten wir gern wissen, was dahinter steckt.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 17, 21, 'Alle Athener nämlich und auch die dort sich aufhaltenden Ausländer hatten für nichts anderes so viel Zeit übrig als dafür, irgendeine Neuigkeit zu erzählen oder zu hören.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 17, 22, 'So trat denn Paulus mitten auf den Areshügel und hielt folgende Rede: »Männer von Athen! Nach allem, was ich sehe, seid ihr in besonderem Grade eifrige Gottesverehrer.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 17, 23, 'Denn als ich hier umherging und mir eure Heiligtümer ansah, fand ich auch einen Altar mit der Aufschrift: ›Einem unbekannten Gott‹. Das Wesen nun, das ihr verehrt, ohne es zu kennen, das verkündige ich euch.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 17, 24, 'Der Gott, der die Welt und alles, was in ihr ist, geschaffen hat, er, der Herr des Himmels und der Erde, wohnt nicht in Tempeln, die von Menschenhand erbaut sind,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 17, 25, 'läßt sich auch nicht von Menschenhänden bedienen, als ob er etwas bedürfte, während er doch selbst allen Wesen Leben und Odem und alles andere gibt.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 17, 26, 'Er hat auch gemacht, daß das ganze Menschengeschlecht von einem einzigen (Stammvater) her auf der ganzen Oberfläche der Erde wohnt, und hat für sie bestimmte Zeiten ihres Bestehens und auch die Grenzen ihrer Wohnsitze festgesetzt:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 17, 27, 'sie sollten Gott suchen, ob sie ihn wohl wahrnehmen und finden möchten, ihn, der ja nicht fern von einem jeden unter uns ist;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 17, 28, 'denn in ihm leben wir und bewegen wir uns und sind wir, wie ja auch einige von euren Dichtern gesagt haben: ›Seines Geschlechts sind auch wir.‹');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 17, 29, 'Weil wir also göttlichen Geschlechts sind, dürfen wir nicht meinen, die Gottheit gleiche dem Gold oder Silber oder Stein, einem Gebilde menschlicher Kunstfertigkeit und Überlegung.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 17, 30, 'Über die (früheren) Zeiten der Unwissenheit hat Gott zwar hinweggesehen; jetzt aber läßt er den Menschen ansagen, daß sie alle überall Buße tun sollen;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 17, 31, 'denn er hat einen Tag festgesetzt, an welchem er den Erdkreis mit Gerechtigkeit richten will durch einen Mann, den er dazu ausersehen und den er für alle durch seine Auferweckung von den Toten beglaubigt hat.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 17, 32, 'Als sie aber von einer Auferstehung der Toten hörten, spotteten die einen, die anderen aber sagten: »Wir wollen dich hierüber später noch einmal hören.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 17, 33, 'So ging denn Paulus aus ihrer Mitte hinweg.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 17, 34, 'Einige Männer jedoch schlossen sich ihm an und kamen zum Glauben, z.B. Dionysius, ein Mitglied des Areopags, sowie eine Frau namens Damaris und noch mehrere andere mit ihnen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 18, 1, 'Hierauf verließ Paulus Athen und begab sich nach Korinth.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 18, 2, 'Dort traf er einen Juden namens Aquila, der aus Pontus stammte und erst vor kurzem mit seiner Frau Priscilla aus Italien gekommen war, weil (der Kaiser) Klaudius alle Juden aus Rom hatte ausweisen lassen. Paulus besuchte die beiden,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 18, 3, 'und weil er das gleiche Handwerk betrieb wie sie, blieb er bei ihnen wohnen und arbeitete mit ihnen zusammen; sie waren nämlich nach ihrem Handwerk Zeltmacher.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 18, 4, 'In der Synagoge aber besprach er sich an jedem Sabbat und suchte Juden wie Griechen zu gewinnen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 18, 5, 'Als dann Silas und Timotheus aus Mazedonien eingetroffen waren, widmete Paulus sich ganz der Lehrtätigkeit und bezeugte den Juden nachdrücklich, daß Jesus der Gottgesalbte sei.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 18, 6, 'Weil sie aber nichts davon wissen wollten und Lästerreden führten, schüttelte er den Staub von seinen Kleidern ab und sagte zu ihnen: »Euer Blut komme auf euer Haupt: ich bin unschuldig! Von nun an wende ich mich an die Heiden!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 18, 7, 'Damit ging er von dort weg und begab sich in das Haus eines Heidenjuden namens Titius Justus, dessen Haus an die Synagoge anstieß.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 18, 8, 'Crispus aber, der Vorsteher der Synagoge, wurde mit seinem ganzen Hause gläubig an den Herrn, und ebenso kamen viele Korinther, die Paulus predigen hörten, zum Glauben und ließen sich taufen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 18, 9, 'Der Herr aber sagte zu Paulus bei Nacht in einem Traumgesicht: »Fürchte dich nicht, sondern rede weiter und schweige nicht;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 18, 10, 'denn ich bin mit dir, und niemand soll sich an dir vergreifen und dir ein Leid antun; denn ich habe ein zahlreiches Volk in dieser Stadt.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 18, 11, 'So blieb denn Paulus anderthalb Jahre dort und lehrte das Wort Gottes unter ihnen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 18, 12, 'Als aber Gallio Statthalter von Griechenland (geworden) war, traten die Juden einmütig gegen Paulus auf und führten ihn vor den Richterstuhl (des Statthalters)');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 18, 13, 'mit der Beschuldigung: »Dieser Mensch verleitet die Leute zu einer Gottesverehrung, die gegen unser Gesetz verstößt.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 18, 14, 'Als Paulus sich nun dagegen verantworten wollte, sagte Gallio zu den Juden: »Wenn irgendein Verbrechen oder ein böswilliges Vergehen vorläge, ihr Juden, so würde ich eure Klage selbstverständlich angenommen haben;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 18, 15, 'wenn es sich jedoch (nur) um Streitfragen über eine Lehre und über Benennungen und über das für euch gültige Gesetz handelt, so müßt ihr selbst zusehen: über solche Dinge will ich nicht Richter sein.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 18, 16, 'Damit wies er sie von seinem Richterstuhl weg.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 18, 17, 'Da fielen alle über Sosthenes, den Vorsteher der Synagoge, her und verprügelten ihn vor dem Richterstuhl; Gallio aber kümmerte sich nicht weiter darum.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 18, 18, 'Nachdem Paulus dann noch längere Zeit (in Korinth) geblieben war, nahm er von den Brüdern Abschied und trat die Seefahrt nach Syrien an, und zwar zusammen mit Priscilla und Aquila, nachdem er sich in Kenchreä (dem östlichen Hafen Korinths) das Haupt hatte scheren lassen, weil er ein Gelübde getan hatte.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 18, 19, 'Sie kamen dann nach Ephesus, wo Paulus sich von jenen beiden trennte; er selbst aber ging in die Synagoge und unterredete sich mit den Juden.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 18, 20, 'Als sie ihn aber baten, er möchte noch länger dort bleiben, ging er nicht darauf ein,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 18, 21, 'sondern nahm Abschied von ihnen mit den Worten: »[Ich muß durchaus das bevorstehende Fest in Jerusalem feiern; aber] so Gott will, werde ich später zu euch zurückkehren.« Dann fuhr er zu Schiff von Ephesus ab,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 18, 22, 'landete in Cäsarea, ging (nach Jerusalem) hinauf, wo er die Gemeinde begrüßte, und zog dann nach Antiochia hinab.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 18, 23, 'Nachdem er dort einige Zeit zugebracht hatte, brach er wieder auf, durchwanderte von einem Ort zum anderen das galatische Land und Phrygien und stärkte überall die Jünger durch Zuspruch.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 18, 24, 'Inzwischen war ein Jude namens Apollos, der aus Alexandria stammte, ein gelehrter Mann, der in den (heiligen) Schriften außerordentlich bewandert war, nach Ephesus gekommen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 18, 25, 'Er hatte Unterweisung über den Weg des Herrn erhalten, redete mit glühender Begeisterung und trug das auf Jesus Bezügliche richtig vor, obgleich er nur von der Taufe des Johannes wußte.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 18, 26, 'Dieser Mann fing dann auch an, in der Synagoge freimütig zu reden. Als Priscilla und Aquila ihn gehört hatten, traten sie mit ihm in Verbindung und setzten ihm die Lehre Gottes noch genauer auseinander.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 18, 27, 'Als er dann nach Griechenland hinüberzureisen wünschte, bestärkten die Brüder ihn in dieser Absicht und schrieben an die Jünger (in Korinth), sie möchten ihn freundlich aufnehmen. Nach seiner Ankunft leistete er denen, die gläubig geworden waren, durch seine Gnadengabe die erfreulichsten Dienste;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 18, 28, 'denn in schlagender Weise widerlegte er die Juden öffentlich, indem er aus den (heiligen) Schriften nachwies, daß Jesus der Messias sei.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 19, 1, 'Während nun Apollos sich in Korinth aufhielt, kam Paulus, nachdem er das Binnenland von Kleinasien durchwandert hatte, nach Ephesus und fand dort einige Jünger vor.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 19, 2, 'Er fragte diese: »Habt ihr den heiligen Geist empfangen, nachdem ihr gläubig geworden waret?« Sie antworteten ihm: »Nein, wir haben überhaupt noch nichts davon gehört, ob der heilige Geist (schon) da ist.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 19, 3, 'Darauf fragte er sie: »Worauf seid ihr denn getauft worden?« Sie antworteten: »Auf die Taufe des Johannes.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 19, 4, 'Da sagte Paulus: »Johannes hat (nur) eine Bußtaufe vollzogen und dabei dem Volke geboten, sie sollten an den glauben, der nach ihm kommen würde, nämlich an Jesus.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 19, 5, 'Als sie das hörten, ließen sie sich auf den Namen des Herrn Jesus taufen;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 19, 6, 'und als Paulus ihnen dann die Hände auflegte, kam der heilige Geist auf sie, und sie redeten mit Zungen und sprachen prophetisch.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 19, 7, 'Es waren dies im ganzen etwa zwölf Männer.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 19, 8, 'Paulus ging dann in die Synagoge und trat dort ein Vierteljahr lang mit Freimut auf, indem er sich besprach und sie für das Reich Gottes zu gewinnen suchte.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 19, 9, 'Als manche jedoch verstockt und unzugänglich blieben und die (neue) Lehre vor der versammelten Menge schmähten, sagte er sich von ihnen los, sonderte auch die Jünger von ihnen ab und hielt nun täglich seine Vorträge im Hörsaal eines gewissen Tyrannus.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 19, 10, 'Das ging so zwei Jahre lang fort, so daß alle Bewohner der Provinz Asien das Wort des Herrn zu hören bekamen, Juden sowohl wie Griechen. –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 19, 11, 'Auch ungewöhnliche Wunder ließ Gott durch die Hände des Paulus geschehen,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 19, 12, 'so daß man sogar Schweißtücher oder Schürzen, die er (bei der Arbeit) an seinem Leibe getragen hatte, zu den Kranken brachte, worauf dann die Krankheiten von ihnen wichen und die bösen Geister ausfuhren.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 19, 13, 'Nun unterfingen sich aber auch einige von den umherziehenden jüdischen Beschwörern, über Personen, die von bösen Geistern besessen waren, den Namen des Herrn Jesus auszusprechen, indem sie sagten: »Ich beschwöre euch bei dem Jesus, den Paulus predigt!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 19, 14, 'Es waren besonders sieben Söhne eines gewissen Skeuas, eines Juden aus hohepriesterlichem Geschlecht, die das taten.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 19, 15, 'Der böse Geist aber gab ihnen zur Antwort: »Jesus kenne ich wohl, und auch Paulus ist mir bekannt; doch wer seid ihr?«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 19, 16, 'Hierauf sprang der Mensch, in welchem der böse Geist war, auf sie los, überwältigte beide und richtete sie so zu, daß sie unbekleidet und blutig geschlagen aus jenem Hause entflohen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 19, 17, 'Dieses Vorkommnis wurde alsdann allen Juden und Griechen bekannt, die in Ephesus wohnten, und Furcht befiel sie alle; der Name des Herrn Jesus aber wurde hoch gepriesen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 19, 18, 'Ebenso kamen auch viele von denen, die gläubig geworden waren, und bekannten offen und unverhohlen ihr früheres Treiben;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 19, 19, 'ja nicht wenige von denen, die sich mit Zauberei abgegeben hatten, brachten die Zauberbücher auf einen Haufen zusammen und verbrannten sie öffentlich. Als man ihre Preise zusammenrechnete, kam der Betrag von fünfzigtausend Drachmen heraus.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 19, 20, 'So breitete sich das Wort des Herrn unaufhaltsam aus und wurde immer stärker.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 19, 21, 'Als dieses glücklich ausgeführt war, entschloß sich Paulus dazu, Mazedonien und Griechenland zu durchwandern und sich dann nach Jerusalem zu begeben, wobei er erklärte: »Nachdem ich dort gewesen bin, muß ich auch Rom sehen.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 19, 22, 'So sandte er denn zwei von seinen Gehilfen, Timotheus und Erastus, nach Mazedonien ab, während er selbst noch eine Zeitlang in der Provinz Asien verblieb.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 19, 23, 'Um diese Zeit aber kam es (in Ephesus) zu großen Unruhen wegen des Weges.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 19, 24, 'Ein Silberschmied nämlich, Demetrius mit Namen, der silberne Tempel der Artemis verfertigte und den Handwerkern dadurch viel zu verdienen gab,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 19, 25, 'berief diese und die hierbei beschäftigten Arbeiter zu einer Versammlung und sprach sich so aus: »Ihr Männer, ihr wißt, daß wir unsern Wohlstand diesem unserm Gewerbe verdanken.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 19, 26, 'Nun seht und hört ihr aber, daß dieser Paulus nicht nur hier in Ephesus, sondern beinahe in der ganzen Provinz Asien viele Leute durch sein Gerede betört hat, indem er ihnen vorhält, das seien keine Götter, die von Menschenhänden angefertigt würden.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 19, 27, 'Aber nicht nur dieser unser Erwerbszweig droht in Mißachtung zu kommen, sondern auch der Tempel der großen Göttin Artemis schwebt in Gefahr, in völlige Mißachtung zu geraten; ja es ist zu befürchten, daß sie sogar ihres hohen Ruhmes ganz verlustig geht, während sie jetzt doch von ganz Asien, ja von aller Welt verehrt wird.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 19, 28, 'Als sie das hörten, gerieten sie in volle Wut und riefen laut: »Groß ist die Artemis von Ephesus!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 19, 29, 'Die ganze Stadt geriet in Aufruhr, und alle stürmten einmütig ins Theater, wohin sie auch die Mazedonier Gajus und Aristarchus, die Reisegefährten des Paulus, mitschleppten.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 19, 30, 'Als Paulus nun (selbst) vor die Volksmenge treten wollte, ließen die Jünger es ihm nicht zu;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 19, 31, 'auch einige von den obersten Beamten der Provinz Asien, die seine guten Freunde waren, schickten zu ihm und ließen ihm die Mahnung zugehen, er möchte sich nicht ins Theater begeben.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 19, 32, 'Dort schrie nun alles wild durcheinander; denn die Versammlung war ein Wirrwarr; die meisten wußten überhaupt nicht, weswegen man zusammengekommen war.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 19, 33, 'Da verständigte man aus der Volksmenge heraus den Alexander, den die Juden vorschoben. Dieser Alexander gab auch ein Zeichen mit der Hand und wollte eine Verteidigungsrede an das Volk richten;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 19, 34, 'als man aber merkte, daß er ein Jude sei, erscholl von allen wie aus einem Munde etwa zwei Stunden lang der Ruf: »Groß ist die Artemis von Ephesus!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 19, 35, 'Endlich brachte der Stadtschreiber die Menge zur Ruhe und sagte: »Ihr Männer von Ephesus! Wo gibt es wohl in der ganzen Welt einen Menschen, der nicht wüßte, daß die Stadt Ephesus die Tempelhüterin der großen Artemis und ihres vom Himmel herabgefallenen Bildes ist?');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 19, 36, 'Da dies also eine unbestreitbare Tatsache ist, solltet ihr euch ja ruhig verhalten und nichts Übereiltes tun.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 19, 37, 'Ihr habt ja doch diese Männer hierher gebracht, die weder Tempelräuber sind noch unsere Göttin lästern.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 19, 38, 'Wenn nun Demetrius und die Zunft der Kunsthandwerker mit ihm Grund zu einer Klage gegen jemand haben, nun, so werden ja Gerichtstage abgehalten, und es gibt Statthalter; dort mögen sie ihre Sache miteinander abmachen!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 19, 39, 'Habt ihr aber außerdem noch Wünsche, so wird das in der ordentlichen Volksversammlung erledigt werden.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 19, 40, 'Droht uns doch wegen der heutigen Vorkommnisse sogar eine Anklage wegen Aufruhrs, weil kein Grund vorliegt, mit dem wir diesen Aufruhr rechtfertigen könnten.« Durch diese Worte brachte er die Versammlung zum Auseinandergehen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 20, 1, 'Als sich nun die Unruhe gelegt hatte, ließ Paulus die Jünger zu sich kommen, hielt eine ermahnende Ansprache an sie, nahm dann Abschied von ihnen und trat die Reise nach Mazedonien an.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 20, 2, 'Nachdem er diese Gegenden durchzogen und (den dortigen Gläubigen) reichen Zuspruch gespendet hatte, begab er sich nach Griechenland.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 20, 3, 'Als er sich dann nach einem Aufenthalt von drei Monaten nach Syrien einschiffen wollte und die Juden einen Anschlag gegen ihn planten, entschloß er sich zur Rückkehr durch Mazedonien.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 20, 4, 'Auf der Reise begleiteten ihn (bis nach Kleinasien): Sopater, der Sohn des Pyrrhus aus Beröa, ferner von den Thessalonikern Aristarchus und Sekundus, weiter aus Derbe Gajus und Timotheus; außerdem aus der Provinz Asien Tychikus und Trophimus.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 20, 5, 'Diese (letzten beiden) jedoch reisten uns voraus und erwarteten uns in Troas;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 20, 6, 'wir selbst dagegen fuhren nach den Tagen der ungesäuerten Brote zu Schiff von Philippi ab und kamen fünf Tage später zu ihnen nach Troas, wo wir sieben Tage blieben.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 20, 7, 'Als wir uns nun am ersten Tage nach dem Sabbat versammelt hatten, um das Brot zu brechen, besprach sich Paulus mit ihnen, weil er am folgenden Tage abreisen wollte, und dehnte die Unterredung bis Mitternacht aus.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 20, 8, 'Zahlreiche Lampen brannten in dem Obergemach, in dem wir versammelt waren.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 20, 9, 'Da wurde ein Jüngling namens Eutychus, der im (offenen) Fenster saß, von tiefem Schlaf überwältigt, weil Paulus so lange fortredete; er stürzte dann im Schlaf vom dritten Stockwerk hinab und wurde tot aufgehoben.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 20, 10, 'Paulus aber ging hinunter, warf sich über ihn, schlang die Arme um ihn und sagte: »Beunruhigt euch nicht! Seine Seele ist (wieder) in ihm.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 20, 11, 'Als er dann wieder hinaufgegangen war und das Brot gebrochen hatte, nahm er einen Imbiß und unterredete sich noch lange weiter mit ihnen, bis der Tag anbrach; dann erst machte er sich auf den Weg.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 20, 12, 'Den Knaben aber hatte man lebend weggetragen, wodurch alle sich nicht wenig getröstet fühlten.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 20, 13, 'Wir (anderen) waren unterdessen auf das Schiff vorausgegangen und fuhren auf Assos zu in der Absicht, dort Paulus an Bord zu nehmen; denn so hatte er es angeordnet, weil er selbst den Weg dorthin zu Fuß machen wollte.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 20, 14, 'Als er dann in Assos mit uns wieder zusammengetroffen war, nahmen wir ihn an Bord und gelangten nach Mitylene.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 20, 15, 'Von dort fuhren wir weiter und kamen am folgenden Tage auf die Höhe von Chios; tags darauf legten wir in Samos an und gelangten [nach einem Aufenthalt in Trogyllion] am nächsten Tage nach Milet.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 20, 16, 'Paulus hatte sich nämlich entschlossen, an Ephesus vorüberzufahren, um keine Zeit mehr in der Provinz Asien zu verlieren; denn er beeilte sich, um womöglich am Tage des Pfingstfestes in Jerusalem zu sein.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 20, 17, 'Von Milet aus aber sandte er Botschaft nach Ephesus und ließ die Ältesten der Gemeinde zu sich rufen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 20, 18, 'Als sie sich bei ihm eingefunden hatten, richtete er folgende Ansprache an sie: »Ihr wißt selbst, wie ich mich vom ersten Tage ab, an dem ich die Provinz Asien betreten hatte, die ganze Zeit hindurch bei euch verhalten');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 20, 19, 'und dem Herrn gedient habe mit aller Demut und unter Tränen und Anfechtungen, die mir aus den Nachstellungen der Juden erwuchsen,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 20, 20, 'wie ich durchaus nichts verabsäumt habe, um euch alles, was euch heilsam sein konnte, öffentlich und in den Häusern zu verkündigen und zu lehren,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 20, 21, 'indem ich es sowohl Juden als auch Griechen ans Herz legte, sich zu Gott zu bekehren und an unsern Herrn Jesus Christus zu glauben.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 20, 22, 'Und jetzt, seht: im Geist gebunden, reise ich nach Jerusalem, ohne zu wissen, was mir dort widerfahren wird;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 20, 23, 'nur das bezeugt mir der heilige Geist in jeder Stadt mit Bestimmtheit, daß Gefangenschaft und Leiden auf mich warten.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 20, 24, 'Doch ich sehe das Leben als für mich selbst völlig wertlos an, wenn ich nur meinen Lauf [mit Freuden] vollende und den Dienst (zum Abschluß bringe), den ich vom Herrn Jesus empfangen habe, nämlich Zeugnis für die Heilsbotschaft von der Gnade Gottes abzulegen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 20, 25, 'Und jetzt, seht: ich weiß, daß ihr mein Angesicht nicht wiedersehen werdet, ihr alle, unter denen ich mich als Prediger des Reiches (Gottes) bewegt habe.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 20, 26, 'Darum gebe ich euch am heutigen Tage die feste Versicherung, daß ich den Tod niemandes auf dem Gewissen habe;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 20, 27, 'denn ich habe es an mir nicht fehlen lassen, euch den ganzen Ratschluß Gottes zu verkündigen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 20, 28, 'So gebt denn acht auf euch selbst und auf die ganze Herde, bei welcher der heilige Geist euch zu Aufsehern bestellt hat, damit ihr die Gemeinde des Herrn weidet, die er sich durch sein eigenes Blut erworben hat.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 20, 29, 'Ich weiß, daß nach meinem Weggang schlimme Wölfe bei euch einbrechen und die Herde nicht verschonen werden;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 20, 30, 'ja aus eurer eigenen Mitte werden Männer auftreten und Irrlehren vortragen, um die Jünger in ihre Gefolgschaft zu ziehen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 20, 31, 'Darum seid wachsam und bleibt dessen eingedenk, daß ich drei Jahre hindurch Tag und Nacht nicht aufgehört habe, jeden einzelnen (von euch) unter Tränen zu ermahnen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 20, 32, 'Und nunmehr befehle ich euch Gott und dem Wort seiner Gnade, das die Kraft besitzt, aufzubauen und das Erbe zu verleihen unter allen, die sich haben heiligen lassen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 20, 33, 'Silber, Gold und Kleidung habe ich von niemand begehrt;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 20, 34, 'ihr wißt selbst, daß für meinen Lebensunterhalt und auch für meine Begleiter diese (meine) Hände gesorgt haben.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 20, 35, 'Immer und überall habe ich euch gezeigt, daß man in solcher Weise arbeiten und sich der Schwachen annehmen und dabei der Worte des Herrn Jesus eingedenk sein muß; denn er hat selbst gesagt: ›Geben ist seliger als Nehmen.‹«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 20, 36, 'Nach diesen Worten kniete er mit ihnen allen nieder und betete.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 20, 37, 'Da brachen alle in lautes Wehklagen aus, fielen dem Paulus um den Hals und küßten ihn;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 20, 38, 'am schmerzlichsten war für sie das Wort, das er ausgesprochen hatte, sie würden sein Angesicht nicht wiedersehen. Sie gaben ihm darauf das Geleit bis zum Schiff.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 21, 1, 'Als wir uns dann von ihnen losgerissen hatten und wieder in See gegangen waren, kamen wir in gerader Fahrt nach Kos, am nächsten Tage nach Rhodus und von dort nach Patara.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 21, 2, 'Als wir dort ein Schiff fanden, das nach Phönizien bestimmt war, stiegen wir ein und fuhren ab.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 21, 3, 'Wir bekamen Cypern in Sicht, das wir aber zur Linken liegen ließen, steuerten auf Syrien zu und legten in Tyrus an; denn dort hatte das Schiff seine Ladung zu löschen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 21, 4, 'Wir suchten nun die Jünger auf und blieben sieben Tage dort; jene warnten den Paulus auf Eingebung des Geistes wiederholt vor der Reise nach Jerusalem.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 21, 5, 'Als wir aber die Tage dort verlebt hatten, machten wir uns zur Weiterfahrt auf den Weg, wobei alle (Brüder) samt Frauen und Kindern uns das Geleit bis vor die Stadt hinaus gaben. Am Strande knieten wir nieder und beteten;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 21, 6, 'dann nahmen wir Abschied voneinander und gingen an Bord, während jene wieder heimkehrten.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 21, 7, 'Wir aber legten den letzten Teil unserer Fahrt zurück, indem wir von Tyrus nach Ptolemais segelten; wir begrüßten auch hier die Brüder, blieben aber nur einen Tag bei ihnen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 21, 8, 'Am nächsten Morgen zogen wir weiter und kamen nach Cäsarea, wo wir bei dem Evangelisten Philippus, einem der sieben, einkehrten und bei ihm blieben.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 21, 9, 'Dieser hatte vier unverheiratete Töchter, welche Prophetengabe besaßen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 21, 10, 'Während unseres mehrtägigen Aufenthalts (in Cäsarea) kam ein Prophet namens Agabus aus Judäa herab');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 21, 11, 'und besuchte uns, er nahm den Gürtel des Paulus, band sich Hände und Füße damit und sagte dann: »So spricht der heilige Geist: ›Den Mann, dem dieser Gürtel gehört, werden die Juden in Jerusalem in dieser Weise binden und ihn den Heiden in die Hände liefern.‹«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 21, 12, 'Als wir das hörten, baten wir und die Einheimischen den Paulus inständig, er möchte nicht nach Jerusalem hinaufgehen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 21, 13, 'Da antwortete Paulus: »Was weint ihr so und macht mir das Herz schwer? Ich bin ja bereit, mich in Jerusalem nicht nur binden zu lassen, sondern auch den Tod für den Namen des Herrn Jesus zu erleiden!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 21, 14, 'Weil er sich nun nicht umstimmen ließ, beruhigten wir uns und sagten: »Des Herrn Wille geschehe!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 21, 15, 'Nach Ablauf dieser Tage machten wir uns reisefertig und zogen nach Jerusalem hinauf.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 21, 16, 'Dabei begleiteten uns auch einige Jünger aus Cäsarea und brachten uns zu einem gewissen Mnason aus Cypern, einem alten Jünger, bei dem wir als Gäste wohnen sollten.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 21, 17, 'Nach unserer Ankunft in Jerusalem nahmen uns die Brüder mit Freuden auf.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 21, 18, 'Gleich am folgenden Tage ging Paulus mit uns zu Jakobus, und auch alle Ältesten fanden sich dort ein.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 21, 19, 'Nachdem Paulus sie begrüßt hatte, erzählte er ihnen alles im einzelnen, was Gott unter den Heiden durch seine Arbeit vollbracht hatte.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 21, 20, 'Als sie das gehört hatten, priesen sie Gott, sagten aber zu ihm: »Du siehst, lieber Bruder, wie viele Tausende es unter den Juden gibt, die gläubig geworden sind; doch alle sind sie eifrige Anhänger des (mosaischen) Gesetzes.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 21, 21, 'Nun ist ihnen aber über dich berichtet worden, daß du allen Juden, die unter den Heiden leben, den Abfall von Mose predigest und ihnen empfehlest, sie möchten ihre Kinder nicht beschneiden lassen und überhaupt die herkömmlichen Gebräuche nicht mehr beobachten.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 21, 22, 'Was ist da nun zu tun? Jedenfalls werden sie von deinem Hiersein erfahren.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 21, 23, 'Tu also, was wir dir raten! Wir haben hier (gerade) vier Männer unter uns, die ein Gelübde auf sich genommen haben;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 21, 24, 'nimm diese mit dir, laß dich mit ihnen reinigen und bezahle für sie (die zu entrichtenden Gebühren), damit sie sich das Haupt scheren lassen können; dann werden alle einsehen, daß an den Gerüchten, die ihnen über dich zu Ohren gekommen sind, nichts Wahres ist, daß vielmehr auch du in der Beobachtung des Gesetzes wandelst.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 21, 25, 'Was aber die gläubig gewordenen Heiden betrifft, so haben wir beschlossen und ihnen (schriftlich) mitgeteilt, daß sie sich vor Götzenopferfleisch, vor (dem Genuß von) Blut, vor dem Fleisch erstickter Tiere und vor Unzucht zu hüten haben.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 21, 26, 'Daraufhin nahm Paulus die (betreffenden) Männer mit sich, ließ sich am folgenden Tage reinigen und ging mit ihnen in den Tempel, wo er den Abschluß der Reinigungstage anmeldete, (die so lange dauerten) bis für einen jeden von ihnen das Löseopfer dargebracht sein würde.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 21, 27, 'Als aber die sieben Tage (der Reinigungszeit) nahezu abgelaufen waren, erblickten ihn die Juden, die aus der Provinz Asien gekommen waren, im Tempel und brachten die ganze Volksmenge in Aufruhr; sie nahmen ihn fest');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 21, 28, 'und riefen laut: »Ihr Männer von Israel, kommt uns zu Hilfe! Dies ist der Mensch, der überall vor allen Leuten seine Lehre gegen unser Volk und gegen das Gesetz und gegen diese Stätte vorträgt! Dazu hat er jetzt auch noch Griechen in den Tempel hineingebracht und dadurch diese heilige Stätte entweiht!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 21, 29, 'Sie hatten nämlich vorher den Trophimus aus Ephesus in der Stadt mit ihm zusammen gesehen und meinten nun, Paulus habe ihn in den Tempel mitgenommen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 21, 30, 'So geriet denn die ganze Stadt in Bewegung, und es entstand ein Volksauflauf; man ergriff Paulus und schleppte ihn aus dem Tempel hinaus, worauf dessen Tore sogleich geschlossen wurden.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 21, 31, 'Während man nun darauf ausging, ihn totzuschlagen, gelangte an den Obersten der römischen Abteilung die Meldung hinauf, ganz Jerusalem sei in Aufruhr.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 21, 32, 'Dieser nahm (daher) sofort Mannschaften und Hauptleute mit sich und eilte zu ihnen hinab. Als jene nun den Obersten und die Soldaten sahen, hörten sie auf, Paulus zu schlagen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 21, 33, 'Da trat der Oberst heran, bemächtigte sich seiner, ließ ihn in zwei Ketten legen und fragte, wer er sei und was er getan habe.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 21, 34, 'Da schrien alle in der Volksmenge durcheinander. Weil er nun wegen des Lärms nichts Sicheres ermitteln konnte, gab er Befehl, man solle Paulus in die Burg führen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 21, 35, 'Als Paulus aber an die Treppe (zur Burg hinauf) gelangt war, mußte er wegen des gewaltsamen Andrangs der Menge von den Soldaten getragen werden;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 21, 36, 'denn die Volksmenge zog mit unter dem lauten Ruf: »Nieder mit ihm!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 21, 37, 'Als nun Paulus eben in die Burg hineingeführt werden sollte, fragte er den Obersten: »Darf ich dir etwas sagen?« Jener erwiderte: »Du kannst Griechisch?');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 21, 38, 'Da bist du also nicht der Ägypter, der vor einiger Zeit den Aufruhr erregt und die viertausend Mann Banditen in die Wüste hinausgeführt hat?«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 21, 39, 'Paulus antwortete: »Nein, ich bin ein Jude aus Tarsus, Bürger einer namhaften Stadt in Cilicien. Erlaube mir, bitte, zum Volke zu reden!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 21, 40, 'Als jener ihm die Erlaubnis gegeben hatte, gab Paulus, auf der Treppe stehend, dem Volk ein Zeichen mit der Hand; als dann völlige Stille eingetreten war, hielt er in der hebräischen Landessprache folgende Ansprache an sie:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 22, 1, '»Werte Brüder und Väter, hört jetzt meine Rechtfertigung vor euch an!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 22, 2, 'Als sie nun hörten, daß er in hebräischer Sprache zu ihnen redete, verhielten sie sich noch ruhiger; und er fuhr fort:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 22, 3, '»Ich bin ein Jude, geboren zu Tarsus in Cilicien, aber hier in dieser Stadt erzogen: zu den Füßen Gamaliels habe ich meine Ausbildung in strenger Befolgung des Gesetzes unserer Väter erhalten und bin ein ebensolcher Eiferer für Gott gewesen, wie ihr alle es noch heute seid.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 22, 4, 'Als solcher habe ich auch diese Glaubensrichtung bis auf den Tod verfolgt, indem ich Männer wie Frauen in Ketten legte und ins Gefängnis werfen ließ,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 22, 5, 'wie mir das auch der Hohepriester und der gesamte Rat der Ältesten bezeugen können. Von diesen habe ich mir sogar Briefe an unsere Volksgenossen geben lassen und mich nach Damaskus begeben, um auch die Leute dort gefesselt zur Bestrafung nach Jerusalem zu bringen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 22, 6, 'Da geschah es, als ich mich auf dem Wege dorthin befand und in die Nähe von Damaskus gekommen war, daß mich zur Mittagszeit plötzlich ein helles Licht vom Himmel her umstrahlte.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 22, 7, 'Ich stürzte zu Boden und hörte eine Stimme, die mir zurief: ›Saul, Saul! Was verfolgst du mich?‹');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 22, 8, 'Ich antwortete: ›Wer bist du, Herr?‹ Er sagte zu mir: ›Ich bin Jesus von Nazareth, den du verfolgst!‹');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 22, 9, 'Meine Begleiter nahmen zwar das Licht wahr, hörten aber die Stimme dessen nicht, der zu mir redete.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 22, 10, 'Ich fragte dann: ›Was soll ich tun, Herr?‹ Da antwortete mir der Herr: ›Steh auf und geh nach Damaskus! Dort wirst du Auskunft über alles erhalten, was dir zu tun verordnet ist.‹');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 22, 11, 'Weil ich nun, von dem Glanz jenes Lichtes geblendet, nicht sehen konnte, wurde ich von meinen Begleitern an der Hand geführt und gelangte so nach Damaskus.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 22, 12, 'Dort kam ein gewisser Ananias, ein gesetzesfrommer Mann, der sich der Anerkennung aller dortigen Juden erfreute,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 22, 13, 'zu mir, trat vor mich hin und sagte zu mir: ›Bruder Saul, werde wieder sehend!‹, und augenblicklich erhielt ich das Augenlicht zurück und konnte ihn sehen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 22, 14, 'Er aber fuhr fort: ›Der Gott unserer Väter hat dich dazu bestimmt, seinen Willen zu erkennen und den Gerechten zu sehen und einen Ruf aus seinem Munde zu vernehmen;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 22, 15, 'denn du sollst Zeugnis für ihn vor allen Menschen ablegen von dem, was du gesehen und gehört hast.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 22, 16, 'Und nun – was zögerst du noch? Stehe auf, laß dich taufen und wasche deine Sünden ab, indem du seinen Namen anrufst!‹');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 22, 17, 'Als ich dann nach Jerusalem zurückgekehrt war und im Tempel betete, geriet ich in eine Verzückung');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 22, 18, 'und sah ihn, der mir gebot: ›Beeile dich und verlaß Jerusalem schleunigst! Denn man wird hier dein Zeugnis über mich nicht annehmen.‹');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 22, 19, 'Da entgegnete ich: ›Herr, sie wissen doch selbst, daß ich es gewesen bin, der die an dich Gläubigen ins Gefängnis werfen und in den Synagogen auspeitschen ließ;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 22, 20, 'und als das Blut deines Zeugen Stephanus vergossen wurde, da habe auch ich dabeigestanden und Freude daran gehabt und Wache bei den Mänteln derer gehalten, die ihn ums Leben brachten.‹');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 22, 21, 'Doch er antwortete mir: ›Mache dich auf den Weg, denn ich will dich in die Ferne zu den Heiden senden!‹«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 22, 22, 'Bis zu diesem Wort hatten sie ihm ruhig zugehört; nun aber erhoben sie ein Geschrei: »Hinweg mit einem solchen Menschen von der Erde! Er darf nicht am Leben bleiben!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 22, 23, 'Während sie noch so schrien und dabei ihre Mäntel abwarfen und Staub in die Luft schleuderten,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 22, 24, 'ließ der Oberst ihn in die Burg hineinbringen und gab Befehl, man solle ihn unter Geißelhieben verhören, damit man herausbrächte, aus welchem Grunde sie so wütend gegen ihn schrien.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 22, 25, 'Als man ihn nun schon für die (Geißelung mit) Riemen ausgestreckt hatte, sagte Paulus zu dem Hauptmann, der dabeistand: »Dürft ihr einen römischen Bürger geißeln, und noch dazu, ehe ein richterliches Urteil vorliegt?«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 22, 26, 'Als der Hauptmann das hörte, begab er sich zu dem Oberst und meldete ihm: »Was willst du tun? Dieser Mann ist ja ein römischer Bürger!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 22, 27, 'Da trat der Oberst herzu und sagte zu ihm: »Sage mir: bist du wirklich ein römischer Bürger?« Er erwiderte: »Ja.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 22, 28, 'Da antwortete der Oberst: »Ich habe mir dieses Bürgerrecht für viel Geld erworben.« Paulus sagte: »Ich dagegen bin sogar als römischer Bürger geboren!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 22, 29, 'So ließ man denn sofort von dem beabsichtigten peinlichen Verhör ab; aber auch der Oberst hatte einen Schrecken bekommen, da er erfahren hatte, daß er ein römischer Bürger sei, und weil er ihn hatte fesseln lassen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 22, 30, 'Weil er aber über das Vergehen, das ihm von seiten der Juden vorgeworfen wurde, ins klare kommen wollte, ließ er ihm am folgenden Tage die Fesseln abnehmen und ordnete eine Versammlung der Hohenpriester und des ganzen Hohen Rates an; dann ließ er Paulus hinabführen und ihn vor sie stellen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 23, 1, 'Paulus blickte nun den Hohen Rat fest an und sagte: »Werte Brüder! Ich habe bis heute meinen Wandel mit durchaus reinem Gewissen im Dienste Gottes geführt.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 23, 2, 'Da befahl der Hohepriester Ananias den neben ihm stehenden (Gerichtsdienern), ihn auf den Mund zu schlagen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 23, 3, 'Paulus aber rief ihm zu: »Dich wird Gott schlagen, du getünchte Wand! Du sitzest da, um mich nach dem Gesetz zu richten, und läßt mich unter Verletzung des Gesetzes schlagen?«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 23, 4, 'Da sagten die neben ihm Stehenden: »Den Hohenpriester Gottes schmähst du?«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 23, 5, 'Da antwortete Paulus: »Ich habe nicht gewußt, ihr Brüder, daß er Hoherpriester ist! Es steht ja geschrieben: ›Einen Obersten deines Volkes sollst du nicht schmähen!‹«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 23, 6, 'Weil Paulus nun wußte, daß der eine Teil (des Hohen Rates) aus Sadduzäern, der andere aus Pharisäern bestand, rief er laut in die Versammlung hinein: »Werte Brüder! Ich bin ein Pharisäer und aus pharisäischer Familie! Wegen unserer Hoffnung, nämlich wegen der Auferstehung der Toten, stehe ich hier vor Gericht!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 23, 7, 'Infolge dieser seiner Äußerung entstand ein Streit zwischen den Pharisäern und Sadduzäern, und die Versammlung spaltete sich.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 23, 8, 'Die Sadduzäer behaupten nämlich, es gebe keine Auferstehung, auch keine Engel und keine Geister, während die Pharisäer beides annehmen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 23, 9, 'So erhob sich denn ein gewaltiges Geschrei; ja, einige Schriftgelehrte von der pharisäischen Partei standen auf, hielten Streitreden und erklärten: »Wir finden nichts Unrechtes an diesem Mann! Kann nicht wirklich ein Geist oder ein Engel zu ihm geredet haben?«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 23, 10, 'Als nun der Streit leidenschaftlich wurde und der Oberst befürchtete, Paulus möchte von ihnen zerrissen werden, ließ er seine Mannschaft herunterkommen, ihn aus ihrer Mitte herausreißen und in die Burg zurückführen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 23, 11, 'In der folgenden Nacht aber trat der Herr zu Paulus und sagte: »Sei getrost! Denn wie du für mich in Jerusalem Zeugnis abgelegt hast, so sollst du auch in Rom Zeuge (für mich) sein!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 23, 12, 'Als es aber Tag geworden war, rotteten sich die Juden zusammen und verschworen sich unter feierlicher Selbstverfluchung, weder Speise noch Trank zu sich zu nehmen, bis sie Paulus ums Leben gebracht hätten.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 23, 13, 'Es waren ihrer aber mehr als vierzig, die sich zu dieser Verschwörung zusammengetan hatten.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 23, 14, 'Diese begaben sich nun zu den Hohenpriestern und Ältesten und sagten: »Wir haben uns hoch und heilig verschworen, nichts zu genießen, bis wir Paulus ums Leben gebracht haben.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 23, 15, 'Werdet ihr jetzt also zusammen mit dem Hohen Rat bei dem Oberst vorstellig, er möge ihn zu euch herabführen lassen, weil ihr seine Sache noch genauer zu untersuchen gedächtet; wir halten uns dann bereit, ihn zu ermorden, noch ehe er in eure Nähe kommt.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 23, 16, 'Von diesem Anschlag erhielt jedoch der Schwestersohn des Paulus Kenntnis; er begab sich deshalb hin, verschaffte sich Eingang in die Burg und machte dem Paulus Mitteilung von der Sache.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 23, 17, 'Da ließ Paulus einen von den Hauptleuten zu sich rufen und bat ihn: »Führe doch diesen jungen Mann zum Obersten, denn er hat ihm etwas zu melden.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 23, 18, 'Der nahm ihn mit sich, führte ihn zu dem Obersten und meldete: »Der Gefangene Paulus hat mich zu sich rufen lassen und mich ersucht, diesen jungen Mann zu dir zu führen, weil er dir etwas mitzuteilen habe.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 23, 19, 'Der Oberst nahm ihn darauf bei der Hand, trat (mit ihm) beiseite und fragte ihn unter vier Augen: »Was hast du mir zu melden?«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 23, 20, 'Da berichtete er: »Die Juden haben sich verabredet, dich zu bitten, du möchtest morgen Paulus vor den Hohen Rat hinabführen lassen, angeblich weil dieser noch eine genauere Untersuchung seiner Sache vornehmen wolle.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 23, 21, 'Glaube du ihnen aber nicht! Denn mehr als vierzig Männer von ihnen trachten ihm nach dem Leben; die haben sich feierlich verschworen, weder Speise noch Trank zu sich zu nehmen, bis sie ihn ermordet haben; und sie halten sich jetzt schon dazu bereit und warten nur noch auf deine Zusage.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 23, 22, 'Der Oberst entließ darauf den jungen Mann mit der Weisung, niemandem zu verraten, daß er ihm diese Mitteilung gemacht habe.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 23, 23, 'Danach ließ er zwei von seinen Hauptleuten zu sich kommen und befahl ihnen: »Haltet zweihundert Mann für einen Marsch nach Cäsarea bereit, ferner siebzig Reiter und zweihundert Lanzenträger, von der dritten Stunde der Nacht an.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 23, 24, 'Auch Reittiere sollten sie bereithalten, um Paulus beritten zu machen und ihn sicher zum Statthalter Felix zu bringen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 23, 25, 'Er schrieb außerdem einen Brief folgenden Wortlauts:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 23, 26, '»Ich, Klaudius Lysias, sende dem hochedlen Statthalter Felix meinen Gruß!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 23, 27, 'Dieser Mann war von den Juden festgenommen worden und schwebte in Gefahr, von ihnen totgeschlagen zu werden; da griff ich mit meinen Leuten ein und befreite ihn, weil ich erfahren hatte, daß er ein römischer Bürger sei.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 23, 28, 'Da ich nun den Grund festzustellen wünschte, weswegen sie ihn verklagten, führte ich ihn vor ihren Hohen Rat hinab.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 23, 29, 'Dabei fand ich, daß man ihn wegen Streitfragen über ihr Gesetz verklagte, daß aber keine Anschuldigung, auf welche Todesstrafe oder Gefängnis steht, gegen ihn vorlag.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 23, 30, 'Weil dann aber die Anzeige bei mir einging, daß ein Mordanschlag gegen den Mann geplant werde, habe ich ihn sofort von hier weg zu dir gesandt und zugleich seine Ankläger angewiesen, ihre Sache gegen ihn bei dir anhängig zu machen. Lebe wohl!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 23, 31, 'Die Soldaten nahmen nun dem erhaltenen Befehl gemäß Paulus mit sich und brachten ihn während der Nacht nach Antipatris;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 23, 32, 'am folgenden Tage ließen sie dann die Reiter (allein) mit ihm weiterziehen, während sie selbst in die Burg zurückkehrten.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 23, 33, 'Nach ihrer Ankunft in Cäsarea händigten jene dem Statthalter das Schreiben ein und führten ihm auch den Paulus vor.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 23, 34, 'Nachdem der Statthalter (das Schreiben) gelesen hatte, fragte er (Paulus), aus welcher Provinz er sei; und als er erfuhr, daß er aus Cilicien stamme, erklärte er:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 23, 35, '»Ich werde dich verhören, wenn auch deine Ankläger hier eingetroffen sind.« Zugleich befahl er, ihn in der Statthalterei des Herodes in Gewahrsam zu halten.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 24, 1, 'Fünf Tage später kam dann der Hohepriester Ananias mit einigen Ältesten und einem Rechtsanwalt, einem gewissen Tertullus (nach Cäsarea) hinab, und sie machten die Anklage gegen Paulus beim Statthalter anhängig.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 24, 2, 'Nachdem man nun Paulus herbeigerufen hatte, begann Tertullus mit der Anklagerede folgendermaßen:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 24, 3, '»Hochedler Felix! Daß wir durch dein Verdienst in tiefem Frieden leben und der hiesigen Bevölkerung durch deine Fürsorge treffliche Einrichtungen allerseits und überall zuteil werden, das erkennen wir mit aufrichtiger Dankbarkeit an.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 24, 4, 'Um dich aber nicht unnötigerweise zu belästigen, bitte ich dich, du wollest uns nach deiner gewohnten Güte für kurze Zeit Gehör schenken.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 24, 5, 'Wir haben nämlich diesen Mann als eine Pest und als einen Unruhestifter unter allen Juden im ganzen römischen Reich und als den Hauptführer der Sekte der Nazaräer ermittelt;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 24, 6, 'er hat sogar den Versuch gemacht, den Tempel zu entweihen. Dabei haben wir ihn auch festgenommen;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 24, 7, '');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 24, 8, 'und wenn du ihn jetzt verhörst, wirst du dir selbst nach seinen Aussagen ein Urteil über alles das bilden können, was wir ihm zur Last legen.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 24, 9, 'Diesen Angaben schlossen sich auch die anderen Juden an und bestätigten deren Wahrheit.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 24, 10, 'Durch einen Wink des Statthalters aufgefordert, begann nun Paulus seine Verteidigungsrede: »Da ich weiß, daß du schon seit vielen Jahren Richter für die hiesige Bevölkerung bist, so gehe ich getrosten Mutes an die Verteidigung meiner Sache vor dir.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 24, 11, 'Wie du dich vergewissern kannst, sind erst zwölf Tage vergangen, seitdem ich nach Jerusalem hinaufgezogen bin, um dort anzubeten;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 24, 12, 'und weder im Tempel hat man mich bei einer Verhandlung mit jemand oder bei der Anstiftung eines Volksauflaufs betroffen, auch nicht in den Synagogen oder sonst irgendwo in der Stadt;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 24, 13, 'sie sind überhaupt nicht imstande, dir Beweise für ihre jetzigen Anklagen gegen mich zu erbringen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 24, 14, 'Das freilich bekenne ich dir offen, daß ich nach der Glaubensrichtung, die sie als Sekte bezeichnen, dem Gott unserer Väter in der Weise diene, daß ich allem, was im Gesetz und was in den Propheten geschrieben steht, Glauben schenke');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 24, 15, 'und auf Gott dieselbe Hoffnung setze, welche auch sie selbst hegen, daß nämlich eine Auferstehung der Gerechten wie der Ungerechten stattfinden wird.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 24, 16, 'Darum bemühe ich mich auch, immerdar ein unverletztes Gewissen Gott und den Menschen gegenüber zu haben.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 24, 17, 'Nun bin ich nach einer Zwischenzeit von mehreren Jahren hergekommen, um Almosen für mein Volk zu überbringen und Opfer darzubringen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 24, 18, 'Als ich mich dabei einer Weihe unterzogen hatte, haben sie mich im Tempel angetroffen, und zwar nicht in Begleitung eines Volkshaufens oder unter Erregung eines Aufruhrs;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 24, 19, 'nein, einige Juden aus der Provinz Asien sind es gewesen; diese hätten hier vor dir erscheinen und Anklage erheben müssen, wenn sie etwas gegen mich vorzubringen haben.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 24, 20, 'Oder laß diese hier selber angeben, welche Schuld sie (an mir) ermittelt haben, als ich vor dem Hohen Rate stand;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 24, 21, 'es müßte denn das eine Wort sein, das ich in ihrer Mitte stehend ausgerufen habe: ›Wegen der Auferstehung der Toten stehe ich heute als Angeklagter hier vor euch!‹«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 24, 22, 'Felix vertagte darauf die Entscheidung ihrer Sache, weil er ganz genau wußte, was es mit der (in Frage stehenden) Glaubensrichtung auf sich hatte, und sagte: »Wenn der Oberst Lysias herabkommt, werde ich eure Sache entscheiden.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 24, 23, 'Zugleich gab er aber dem Hauptmann die Weisung, Paulus in Gewahrsam zu halten, doch in milder Haft, und keinen von seinen Freunden an der Erweisung von Liebesdiensten zu hindern.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 24, 24, 'Einige Tage später aber erschien Felix mit seiner Gattin Drusilla, einer Jüdin; er beschied Paulus vor sich und ließ sich einen Vortrag über den Glauben an Christus Jesus halten.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 24, 25, 'Als Paulus dabei aber über Gerechtigkeit, Enthaltsamkeit und über das künftige Gericht redete, geriet Felix in Unruhe und sagte: »Für diesmal kannst du gehen! Wenn ich (später) gelegene Zeit habe, will ich dich wieder rufen lassen.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 24, 26, 'Daneben hegte er auch die Hoffnung, er werde Geld von Paulus erhalten; daher ließ er ihn auch öfter rufen und unterredete sich mit ihm.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 24, 27, 'Nach Verlauf von zwei Jahren aber erhielt Felix einen Nachfolger in Porcius Festus; und weil Felix sich die Juden zu Dank verpflichten wollte, ließ er Paulus als Gefangenen zurück.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 25, 1, 'Als Festus nun die Statthalterschaft in der Provinz angetreten hatte, begab er sich drei Tage später von Cäsarea nach Jerusalem hinauf.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 25, 2, 'Da wurden die Hohenpriester und die vornehmsten Juden bei ihm in der Sache gegen Paulus vorstellig und trugen ihm ihr Anliegen vor,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 25, 3, 'wobei sie es sich als besondere Vergünstigung wider ihn (Paulus) erbaten, daß er ihn nach Jerusalem bringen lasse; sie planten nämlich einen Anschlag, um ihn unterwegs zu ermorden.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 25, 4, 'Da gab Festus ihnen zur Antwort, Paulus werde in Cäsarea in Haft gehalten und er selbst werde binnen kurzem (wieder dahin) abreisen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 25, 5, '»Darum mögen«, fuhr er fort, »Bevollmächtigte aus eurer Mitte mit mir hinabkommen und die Anklage gegen ihn erheben, wenn eine Verschuldung bei dem Manne vorliegt.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 25, 6, 'Nachdem er sich dann höchstens acht oder zehn Tage bei ihnen aufgehalten hatte, kehrte er nach Cäsarea zurück, hielt am folgenden Tage eine Gerichtssitzung ab und ließ Paulus vorführen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 25, 7, 'Als dieser erschienen war, umringten ihn die Juden, die aus Jerusalem gekommen waren, und brachten viele schwere Beschuldigungen gegen ihn vor, die sie aber nicht zu beweisen vermochten,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 25, 8, 'während Paulus in seiner Verteidigung dartat: »Ich habe mich weder gegen das jüdische Gesetz noch gegen den Tempel noch gegen den Kaiser irgendwie vergangen.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 25, 9, 'Weil Festus sich aber die Juden zu Dank verpflichten wollte, legte er dem Paulus die Frage vor: »Willst du nach Jerusalem hinaufgehen und dich dort in dieser Sache vor mir richten lassen?«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 25, 10, 'Da antwortete Paulus: »Ich stehe hier vor des Kaisers Richterstuhl, und hier habe ich auch mein Urteil zu empfangen. Den Juden habe ich nichts zuleide getan, wie du selbst ganz genau weißt.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 25, 11, 'Wenn ich nun im Unrecht bin und ein todeswürdiges Verbrechen begangen habe, so weigere ich mich nicht, zu sterben; wenn aber an den Beschuldigungen, die diese gegen mich vorbringen, nichts Wahres ist, so darf mich niemand ihnen zuliebe preisgeben. Ich lege Berufung an den Kaiser ein!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 25, 12, 'Darauf besprach sich Festus mit seinen Räten und gab dann den Bescheid ab: »An den Kaiser hast du Berufung eingelegt: vor den Kaiser sollst du kommen!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 25, 13, 'Einige Tage später kamen der König Agrippa und (seine Schwester) Bernice nach Cäsarea, um dem Festus ihren Besuch zu machen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 25, 14, 'Während ihres mehrtägigen Aufenthalts daselbst legte Festus dem König die Sache des Paulus vor mit den Worten: »Hier ist von Felix ein Mann als Gefangener zurückgelassen worden,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 25, 15, 'gegen den während meiner Anwesenheit in Jerusalem die Hohenpriester und die Ältesten der Juden bei mir vorstellig geworden sind und dessen Verurteilung sie von mir verlangt haben.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 25, 16, 'Ich habe ihnen zur Antwort gegeben, bei den Römern sei es nicht üblich, einen Menschen aus Gefälligkeit preiszugeben, bevor nicht der Angeklagte seinen Anklägern persönlich gegenübergestanden und Gelegenheit zur Verteidigung gegen die Anklage erhalten habe.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 25, 17, 'Als sie dann hierher gekommen waren, habe ich unverzüglich schon am nächsten Tage eine Gerichtssitzung abgehalten und den Mann vorführen lassen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 25, 18, 'Die Ankläger traten auf, brachten aber über ihn keine Beschuldigung wegen schwerer Verbrechen vor, wie ich erwartet hatte,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 25, 19, 'sondern sie hatten gegen ihn nur einige Streitfragen bezüglich ihrer besonderen Gottesverehrung sowie bezüglich eines gewissen Jesus, der bereits tot ist, von dem Paulus aber behauptete, daß er lebe.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 25, 20, 'Da ich mich nun auf die Untersuchung dieser Dinge nicht verstand, fragte ich ihn, ob er nicht nach Jerusalem gehen und sich dort hierüber das Urteil sprechen lassen wollte.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 25, 21, 'Als Paulus dann aber Berufung einlegte und bis zur Entscheidung des Kaisers in Haft zu bleiben verlangte, habe ich befohlen, man solle ihn weiter in Gewahrsam halten, bis ich ihn zum Kaiser senden würde.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 25, 22, 'Da sagte Agrippa zu Festus: »Ich möchte den Mann gern persönlich (einmal) hören«, worauf jener erwiderte: »Gleich morgen sollst du ihn hören!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 25, 23, 'Als nun am folgenden Tage Agrippa und Bernice mit großem Gepränge erschienen und mit den Heeresobersten und den vornehmsten Männern der Stadt in den Vortragssaal eingetreten waren, wurde Paulus auf Befehl des Festus vorgeführt.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 25, 24, 'Darauf sagte Festus: »König Agrippa und ihr anderen mit uns hier anwesenden Herrn alle! Ihr seht hier den Mann, wegen dessen die gesamte Judenschaft mich in Jerusalem wie auch hier mit dem lauten Ruf bestürmt hat, er dürfe nicht länger am Leben bleiben.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 25, 25, 'Ich bin mir jedoch klar darüber geworden, daß er kein todeswürdiges Verbrechen begangen hat. Weil er selbst aber Berufung an den Kaiser eingelegt hat, habe ich mich für seine Hinsendung entschieden.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 25, 26, 'Nun weiß ich aber meinem kaiserlichen Herrn nichts Zuverlässiges über ihn zu berichten; darum habe ich ihn euch und vornehmlich dir, König Agrippa, hier vorführen lassen, damit ich nach erfolgtem Verhör eine Unterlage für meinen schriftlichen Bericht erhalte.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 25, 27, 'Denn es scheint mir widersinnig zu sein, einen Gefangenen hinzusenden, ohne zugleich die gegen ihn erhobenen Beschuldigungen anzugeben.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 26, 1, 'Darauf sagte Agrippa zu Paulus: »Es ist dir gestattet, zu deiner Rechtfertigung zu reden.« Da streckte Paulus die Hand aus und hielt folgende Verteidigungsrede:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 26, 2, '»Ich schätze mich glücklich, König Agrippa, daß ich mich heute wegen aller Beschuldigungen, welche die Juden gegen mich erheben, hier vor dir verantworten darf,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 26, 3, 'weil du ja ein ausgezeichneter Kenner aller Gebräuche und Streitfragen der Juden bist. Deshalb bitte ich dich, mir geduldiges Gehör zu schenken.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 26, 4, 'Wie sich meine Lebensführung von Jugend auf inmitten meines Volkes, und zwar in Jerusalem, von Anfang an gestaltet hat, das wissen alle Juden,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 26, 5, 'die mich von früher her kennen; sie müssen, wenn sie nur wollen, mir das Zeugnis ausstellen, daß ich nach der strengsten Richtung unserer Gottesverehrung gelebt habe, nämlich als Pharisäer.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 26, 6, 'Und jetzt stehe ich hier als Angeklagter, um mich richten zu lassen wegen der Hoffnung auf die (Erfüllung der) Verheißung, die von Gott an unsere Väter ergangen ist');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 26, 7, 'und zu der unser Zwölfstämmevolk durch anhaltenden Gottesdienst bei Tag und Nacht zu gelangen hofft: wegen dieser Hoffnung, o König, werde ich von Juden angeklagt!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 26, 8, 'Warum gilt es denn bei euch für unglaublich, wenn Gott Tote auferweckt?');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 26, 9, 'Was mich freilich betrifft, so habe ich es (einst) für meine Pflicht gehalten, den Namen Jesu von Nazareth als erklärter Feind zu bekämpfen,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 26, 10, 'und das habe ich denn auch in Jerusalem getan. Ich verschaffte mir nämlich Vollmacht von den Hohenpriestern und ließ viele von den Heiligen in die Gefängnisse einschließen; und wenn sie hingerichtet werden sollten, erklärte ich mich damit einverstanden.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 26, 11, 'In allen Synagogen zwang ich sie oftmals durch Strafen zur Lästerung und verfolgte sie in maßloser Wut sogar bis in die auswärtigen Städte.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 26, 12, 'Als ich hierbei mit der Vollmacht und im Auftrag der Hohenpriester nach Damaskus reiste,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 26, 13, 'sah ich unterwegs, o König, zur Mittagszeit vom Himmel her ein Licht, das heller als der Glanz der Sonne mich und meine Reisebegleiter umstrahlte.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 26, 14, 'Als wir nun alle zu Boden niedergestürzt waren, hörte ich eine Stimme, die mir in der hebräischen Volkssprache zurief: ›Saul, Saul! Was verfolgst du mich? Es ist schwer für dich, gegen den Stachel auszuschlagen!‹');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 26, 15, 'Ich antwortete: ›Wer bist du, Herr?‹ Da erwiderte der Herr: ›Ich bin Jesus, den du verfolgst.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 26, 16, 'Doch stehe auf und tritt auf deine Füße! Denn dazu bin ich dir erschienen, dich zum Diener und Zeugen für das zu machen, was du von mir (als Auferstandenem) gesehen hast, und für das, was ich dich noch sehen lassen werde;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 26, 17, 'und ich werde dich retten vor dem Volk (Israel) und vor den Heiden, zu denen ich dich senden will:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 26, 18, 'du sollst ihnen die Augen öffnen, damit sie sich von der Finsternis zum Licht und von der Gewalt des Satans zu Gott bekehren, auf daß sie Vergebung der Sünden und ein Erbteil unter denen erhalten, die durch den Glauben an mich geheiligt worden sind.‹');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 26, 19, 'Infolgedessen bin ich, o König Agrippa, der himmlischen Erscheinung nicht ungehorsam gewesen,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 26, 20, 'sondern habe zuerst den Einwohnern von Damaskus und Jerusalem, dann denen im ganzen jüdischen Lande und weiterhin den Heiden gepredigt, sie möchten Buße tun, sich zu Gott bekehren und Werke vollbringen, die der Buße würdig sind.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 26, 21, 'Das ist der Grund, weshalb die Juden mich im Tempel festgenommen und mich ums Leben zu bringen versucht haben.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 26, 22, 'Weil ich nun Gottes Beistand bis auf den heutigen Tag gefunden habe, stehe ich da und lege Zeugnis vor hoch und niedrig ab; dabei sage ich nichts anderes als das, wovon schon die Propheten und Mose geweissagt haben, daß es geschehen werde,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 26, 23, 'nämlich ob Christus zum Leiden bestimmt sei und ob er als Erstling unter den vom Tode Auferstandenen sowohl dem Volk (Israel) als auch den Heiden das Licht verkünden solle.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 26, 24, 'Als Paulus in dieser Weise zu seiner Verteidigung redete, rief Festus mit lauter Stimme aus: »Paulus, du bist von Sinnen! Die große Gelehrsamkeit bringt dich um den Verstand!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 26, 25, 'Da erwiderte Paulus: »Ich bin nicht von Sinnen, hochedler Festus, sondern ich rede wahre und wohlüberlegte Worte!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 26, 26, 'Denn der König versteht sich auf diese Dinge; an ihn wende ich mich darum auch mit meiner freimütigen Rede; denn ich bin überzeugt, daß ihm nichts von diesen Dingen verborgen geblieben ist; dies alles hat sich ja nicht in einem Winkel abgespielt.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 26, 27, 'Glaubst du den Propheten, König Agrippa? Ich weiß, daß du ihnen glaubst.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 26, 28, 'Da antwortete Agrippa dem Paulus: »Beinahe bringst du es fertig, mich zu einem Christen zu machen!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 26, 29, 'Paulus erwiderte: »Ich möchte zu Gott beten, daß über kurz oder lang nicht allein du, sondern alle, die mich heute hier hören, ebenso werden möchten wie ich es bin, abgesehen allerdings von diesen meinen Fesseln.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 26, 30, 'Darauf erhoben sich der König und der Statthalter sowie Bernice und die übrigen neben ihnen Sitzenden.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 26, 31, 'Nachdem sie sich zurückgezogen hatten, unterhielten sie sich noch miteinander und erklärten: »Dieser Mann tut nichts, was Todesstrafe oder Gefängnis verdient.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 26, 32, 'Agrippa aber erklärte dem Festus: »Dieser Mann könnte freigelassen werden, wenn er nicht Berufung an den Kaiser eingelegt hätte.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 27, 1, 'Als nun unsere Abfahrt nach Italien beschlossen war, übergab man den Paulus und einige andere Gefangene einem Hauptmann der Kaiserlichen Abteilung namens Julius.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 27, 2, 'Wir bestiegen dann ein Schiff aus Adramyttium, das die Küstenplätze der römischen Provinz Asien anlaufen sollte, und fuhren ab; in unserer Begleitung befand sich auch noch Aristarchus, ein Mazedonier aus Thessalonike.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 27, 3, 'Am folgenden Tage landeten wir in Sidon; und weil Julius den Paulus menschenfreundlich behandelte, erlaubte er ihm, seine (dortigen) Freunde zu besuchen und sich von ihnen mit dem nötigen Reisebedarf versorgen zu lassen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 27, 4, 'Von da fuhren wir weiter, und zwar dicht an (der Ostseite von) Cypern hin, weil wir Gegenwind hatten.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 27, 5, 'Nachdem wir dann die See längs der Küste von Cilicien und Pamphylien hin durchsegelt hatten, gelangten wir nach Myra in Lycien.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 27, 6, 'Als der Hauptmann dort ein alexandrinisches Schiff vorfand, das auf der Fahrt nach Italien begriffen war, brachte er uns auf dieses.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 27, 7, 'Im Verlauf vieler Tage langsamer Fahrt kamen wir mit Mühe in die Nähe von Knidus; und weil uns der Wind dort nicht anlegen ließ, fuhren wir an Kreta hin, und zwar bei Salome.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 27, 8, 'Nur mit Mühe erreichten wir bei dieser Küstenfahrt einen Ort namens Schönhafen, in dessen Nähe die Stadt Lasäa lag.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 27, 9, 'Da inzwischen geraume Zeit verflossen war und die Schiffahrt bereits gefährlich zu werden begann – sogar der große (jüdische Versöhnungs-) Fasttag war schon vorüber –, sagte Paulus warnend zu ihnen:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 27, 10, '»Ihr Männer, ich sehe voraus, daß ein Weiterfahren mit Gefahr und großem Schaden nicht nur für die Ladung und das Schiff, sondern auch für unser Leben verbunden sein wird.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 27, 11, 'Aber der Hauptmann schenkte dem Steuermann und dem Schiffsherrn mehr Glauben als den Worten des Paulus;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 27, 12, 'und weil der Hafen zum Überwintern ungeeignet war, faßte die Mehrzahl den Beschluß, von dort weiterzufahren und womöglich zum Überwintern nach Phönix zu gelangen, einem kretischen Hafen, der gegen den Südwest- und Nordwestwind geschützt liegt.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 27, 13, 'Als nun ein schwacher Südwind einsetzte, glaubten sie, ihr Vorhaben sicher ausführen zu können; sie lichteten daher die Anker und fuhren ganz nahe an der Küste von Kreta hin.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 27, 14, 'Doch schon nach kurzer Zeit brach von der Insel her ein Sturmwind los, der sogenannte Euraquilo.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 27, 15, 'Da nun das Schiff von diesem fortgerissen wurde und dem Wind gegenüber machtlos war, mußten wir uns auf gut Glück treiben lassen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 27, 16, 'Als wir dann unter dem Schutz eines Inselchens namens Klauda hinfuhren, gelang es uns nur mit großer Mühe, uns im Besitz des Rettungsbootes zu erhalten:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 27, 17, 'man zog es an Bord herauf und brachte Schutzmittel in Anwendung, indem man das Schiff (mit Tauen) gürtete; und weil man auf die (Sandbänke der) Syrte zu geraten befürchtete, holte man die Segel herunter und ließ sich so treiben.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 27, 18, 'Weil wir aber vom Sturm schwer zu leiden hatten, warf man am folgenden Tage einen Teil der Ladung über Bord');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 27, 19, 'und ließ am dritten Tage das Schiffsgerät notgedrungen nachfolgen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 27, 20, 'Als dann aber mehrere Tage hindurch weder die Sonne noch Sterne sichtbar waren und der Sturm ungeschwächt weitertobte, schwand uns schließlich alle Hoffnung auf Rettung.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 27, 21, 'Weil nun niemand mehr Nahrung zu sich nehmen mochte, trat Paulus mitten unter sie und sagte: »Ihr Männer! Man hätte allerdings auf mich hören und nicht von Kreta abfahren sollen: dann wäre uns dieses Ungemach und dieser Schaden erspart geblieben.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 27, 22, 'Doch, wie die Dinge jetzt einmal liegen, fordere ich euch auf, getrosten Mutes zu sein; denn keiner von euch wird das Leben verlieren; nur das Schiff ist verloren.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 27, 23, 'Denn in dieser Nacht ist mir ein Engel des Gottes erschienen, dem ich angehöre und dem ich auch diene,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 27, 24, 'und hat zu mir gesagt: ›Fürchte dich nicht, Paulus! Du mußt vor den Kaiser treten, und wisse wohl: Gott hat dir das Leben aller deiner Reisegefährten geschenkt!‹');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 27, 25, 'Darum seid guten Mutes, ihr Männer! Denn ich habe die feste Zuversicht zu Gott, daß es so kommen wird, wie mir angekündigt worden ist.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 27, 26, 'Wir müssen aber an irgendeiner Insel stranden.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 27, 27, 'Als dann die vierzehnte Nacht gekommen war, seit wir im Adriatischen Meer umhertrieben, vermuteten die Schiffsleute um Mitternacht die Annäherung von Land.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 27, 28, 'Als sie nämlich das Senkblei auswarfen, stellten sie zwanzig Klafter Tiefe fest; und als sie in kurzer Entfernung wieder loteten, fanden sie nur fünfzehn Klafter.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 27, 29, 'Weil sie nun fürchteten, wir könnten irgendwo auf Klippen geraten, warfen sie vier Anker hinten vom Schiff aus und erwarteten mit Sehnsucht den Anbruch des Tages.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 27, 30, 'Als nun aber die Schiffsleute aus dem Schiff zu entfliehen suchten und (zu diesem Zweck) das Rettungsboot ins Meer niederließen unter dem Vorgeben, sie wollten auch vorn aus dem Schiff Anker auswerfen,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 27, 31, 'erklärte Paulus dem Hauptmann und den Soldaten: »Wenn diese Leute nicht im Schiff bleiben, könnt ihr unmöglich gerettet werden!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 27, 32, 'Daraufhin hieben die Soldaten die Taue des Bootes ab und ließen es in die See treiben.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 27, 33, 'Bis es aber Tag werden wollte, redete Paulus allen zu, sie möchten Nahrung zu sich nehmen; er sagte nämlich: »Heute ist es der vierzehnte Tag, daß ihr ohne Nahrung ununterbrochen in ängstlicher Erwartung schwebt und nichts Rechtes zu euch genommen habt.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 27, 34, 'Darum rate ich euch: nehmt Nahrung zu euch! Das ist zu eurer Rettung notwendig; denn keinem von euch wird ein Haar vom Haupt verlorengehen!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 27, 35, 'Nach diesen Worten nahm er Brot, sagte Gott vor aller Augen Dank, brach ein Stück ab und begann zu essen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 27, 36, 'Da bekamen alle neuen Mut und nahmen ebenfalls Nahrung zu sich.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 27, 37, 'Wir waren aber unser im ganzen zweihundertsechsundsiebzig Seelen auf dem Schiff.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 27, 38, 'Nachdem sie sich nun satt gegessen hatten, erleichterten sie das Schiff dadurch, daß sie die Getreideladung ins Meer warfen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 27, 39, 'Als es dann (endlich) Tag wurde, erkannten sie das Land nicht, gewahrten aber eine Bucht mit flachem Strand, auf den sie, wenn möglich, das Schiff auflaufen zu lassen beschlossen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 27, 40, 'So kappten sie denn die Ankertaue und ließen sie ins Meer fallen; zugleich machten sie die Riemen an den (beiden) Steuerrudern los, stellten das Vordersegel vor den Wind und hielten auf den Strand zu.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 27, 41, 'Dabei gerieten sie aber auf eine Sandbank, auf die sie das Schiff auflaufen ließen: das Vorderteil bohrte sich tief ein und saß unbeweglich fest, während das Hinterschiff infolge der Gewalt der Wogen allmählich auseinanderging.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 27, 42, 'Die Soldaten faßten nun den Plan, die Gefangenen zu töten, damit keiner von ihnen durch Schwimmen entkäme;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 27, 43, 'der Hauptmann aber, welcher Paulus am Leben zu erhalten wünschte, hinderte sie an der Ausführung ihres Vorhabens; er ließ vielmehr die, welche schwimmen konnten, ins Meer springen und sich zuerst ans Land retten;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 27, 44, 'die übrigen (mußten) dann teils auf Brettern, teils auf irgendwelchen Gegenständen aus dem Schiff (das Ufer gewinnen). Auf diese Weise gelang es allen, wohlbehalten ans Land zu kommen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 28, 1, 'Jetzt, nach unserer Rettung, erfuhren wir, daß die Insel Malta hieß.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 28, 2, 'Die fremdsprachigen Eingeborenen erwiesen uns eine außerordentliche Menschenfreundlichkeit; denn sie zündeten einen Holzstoß an und gaben uns allen wegen des eingetretenen Regens und wegen der Kälte einen Platz (am Feuer).');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 28, 3, 'Als aber Paulus einen Haufen Reisig zusammenraffte und ihn auf den Holzstoß ins Feuer legte, fuhr eine Otter infolge der Hitze heraus und biß sich in seine Hand fest.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 28, 4, 'Als nun die Eingeborenen das Tier an seiner Hand hängen sahen, sagten sie zueinander: »Dieser Mensch muß ein Mörder sein, den die Göttin der Vergeltung trotz seiner Rettung aus dem Meer nicht am Leben lassen will.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 28, 5, 'Er schleuderte jedoch das Tier von sich ab ins Feuer, und es widerfuhr ihm nichts Schlimmes.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 28, 6, 'Jene warteten zwar darauf, daß er anschwellen oder plötzlich tot niederfallen werde; als sie aber geraume Zeit gewartet hatten und nichts Unheilvolles an ihm vorgehen sahen, änderten sie ihre Meinung und sagten, er müsse ein Gott sein.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 28, 7, 'Nun besaß in der Nähe jenes Ortes der vornehmste Mann der Insel namens Publius Landgüter; dieser nahm uns bei sich auf und beherbergte uns drei Tage lang freundlich.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 28, 8, 'Der Vater des Publius aber lag gerade an Fieberanfällen und an der Ruhr krank darnieder. Paulus ging nun zu ihm ins Zimmer, legte ihm unter Gebet die Hände auf und machte ihn dadurch gesund.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 28, 9, 'Infolgedessen kamen auch die anderen Inselbewohner, die an Krankheiten litten, zu ihm und ließen sich heilen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 28, 10, 'Dafür erwies man uns denn auch viele Ehren und versah uns bei unserer Abfahrt mit allem, was wir nötig hatten.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 28, 11, 'Nach einem Vierteljahr fuhren wir dann auf einem alexandrinischen Schiff ab, das auf der Insel überwintert hatte und als Wahrzeichen das Bild der Dioskuren führte.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 28, 12, 'Wir landeten hierauf in Syrakus, wo wir drei Tage blieben.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 28, 13, 'Von dort fuhren wir, im Bogen segelnd, nach Regium weiter und gelangten, da am folgenden Tage der Südwind einsetzte, schon in einer Fahrt von zwei Tagen nach Puteoli.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 28, 14, 'Hier trafen wir Brüder an, die uns baten, sieben Tage bei ihnen zu bleiben; so gelangten wir denn nach Rom.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 28, 15, 'Von dort kamen uns die Brüder, die über uns schon Kunde erhalten hatten, bis Forum Appii und Tres Tabernä entgegen; bei ihrem Anblick sprach Paulus ein Dankgebet zu Gott und faßte neuen Mut.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 28, 16, 'Nach unserer Ankunft in Rom [aber übergab der Hauptmann seine Gefangenen dem Befehlshaber der kaiserlichen Leibwache;] Paulus aber erhielt die Erlaubnis, mit dem ihn bewachenden Soldaten eine eigene (Miets-) Wohnung zu beziehen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 28, 17, 'Nach drei Tagen lud er dann die Vornehmsten der Juden zu sich ein; und als sie sich eingefunden hatten, richtete er folgende Worte an sie: »Werte Brüder! Obgleich ich nichts Feindseliges gegen unser Volk und die Gebräuche der Väter begangen habe, bin ich doch als Gefangener von Jerusalem her den Römern in die Hände geliefert worden.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 28, 18, 'Diese wollten mich nach angestellter richterlicher Untersuchung freilassen, weil keine todeswürdige Schuld bei mir vorlag;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 28, 19, 'weil jedoch die Juden Widerspruch erhoben, sah ich mich gezwungen, die Entscheidung des Kaisers anzurufen, nicht als ob ich gegen mein Volk eine Anklage vorzubringen hätte.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 28, 20, 'Aus diesem Grunde also habe ich euch zu mir gebeten, um euch zu sehen und mich mit euch zu besprechen; denn um der Hoffnung Israels willen habe ich diese Kette zu tragen.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 28, 21, 'Sie gaben ihm zur Antwort: »Wir haben weder Zuschriften über dich aus Judäa erhalten, noch ist irgendein Bruder dagewesen, der etwas Nachteiliges über dich berichtet oder ausgesagt hätte.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 28, 22, 'Wir halten es aber für billig, von dir über deine Ansichten Näheres zu erfahren; denn von dieser Sonderrichtung ist uns (allerdings) bekannt, daß sie überall auf Widerspruch stößt.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 28, 23, 'So bestimmten sie ihm denn einen Tag und fanden sich (an diesem) bei ihm in seiner Wohnung in noch größerer Anzahl ein (als das erste Mal). Da legte er ihnen von früh morgens bis spät abends das Reich Gottes dar und bezeugte es ihnen, indem er sie im Anschluß sowohl an das mosaische Gesetz als an die Propheten für Jesus zu gewinnen suchte.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 28, 24, 'Ein Teil von ihnen ließ sich auch durch seine Darlegungen überzeugen, die anderen dagegen blieben ungläubig.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 28, 25, 'Ohne also zu einer Einigung miteinander gelangt zu sein, trennten sie sich, nachdem Paulus noch das eine Wort an sie gerichtet hatte: »Treffend hat der heilige Geist durch den Propheten Jesaja zu euren Vätern gesagt:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 28, 26, '›Gehe zu diesem Volk und sprich: Ihr werdet immerfort hören und doch kein Verständnis erlangen, und ihr werdet immerfort sehen und doch nicht wahrnehmen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 28, 27, 'Denn das Herz dieses Volkes ist verhärtet, und ihre Ohren sind schwerhörig geworden, und ihre Augen haben sie geschlossen, damit sie mit ihren Augen nicht sehen und mit ihren Ohren nicht hören und mit ihrem Herzen nicht zum Verständnis gelangen, so daß sie sich bekehren und ich sie heile.‹');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 28, 28, 'So sei euch denn kundgetan, daß diese Rettung Gottes den Heiden gesandt worden ist:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 28, 29, 'die werden ihr auch Gehör schenken!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 28, 30, 'Paulus blieb dann zwei volle Jahre in einer eigenen Mietswohnung und nahm (daselbst) alle auf, die ihn besuchten;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 28, 31, 'er verkündigte dabei das Reich Gottes und erteilte Belehrung über den Herrn Jesus Christus mit vollem Freimut, ungehindert.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 1, 1, 'Ich, Paulus, ein Knecht Christi Jesu, bin durch Berufung zum Apostel ausgesondert, die Heilsbotschaft Gottes zu verkündigen,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 1, 2, 'die er durch seine Propheten in (den) heiligen Schriften voraus verheißen hat,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 1, 3, 'nämlich (die Heilsbotschaft) von seinem Sohne. Dieser ist nach dem Fleische aus Davids Samen hervorgegangen,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 1, 4, 'aber als Sohn Gottes in Macht erwiesen nach dem Geist der Heiligkeit aufgrund seiner Auferstehung aus den Toten. Durch ihn, unsern Herrn Jesus Christus,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 1, 5, 'haben wir Gnade und das Apostelamt empfangen, um Glaubensgehorsam zu seines Namens Ehre unter allen Heidenvölkern zu wirken;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 1, 6, 'zu diesen gehört auch ihr, da ihr für Jesus Christus (von Gott) berufen worden seid.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 1, 7, 'Euch allen, die ihr als Geliebte Gottes, als berufene Heilige in Rom wohnt, sende ich meinen Gruß: Gnade werde euch zuteil und Friede von Gott unserm Vater und dem Herrn Jesus Christus!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 1, 8, 'Zuerst sage ich meinem Gott durch Jesus Christus um euer aller willen Dank dafür, daß man von eurem Glauben in der ganzen Welt mit Anerkennung redet.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 1, 9, 'Denn Gott, dem ich in meinem Geiste bei der Verkündigung der Heilsbotschaft seines Sohnes diene, ist mein Zeuge, daß ich euer ohne Unterlaß gedenke');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 1, 10, 'und jedesmal in meinen Gebeten die Bitte ausspreche, ob es mir wohl endlich einmal durch Gottes Willen vergönnt sein möchte, zu euch zu kommen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 1, 11, 'Denn ich sehne mich danach, euch zu sehen; ich möchte euch gern diese und jene geistliche Gabe zu eurer Stärkung mitteilen');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 1, 12, 'oder, besser gesagt, in eurer Mitte durch die Wechselwirkung unsers beiderseitigen Glaubens gleichfalls eine Kräftigung erfahren.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 1, 13, 'Sodann will ich euch nicht in Unkenntnis darüber lassen, liebe Brüder, daß ich mir schon oftmals vorgenommen habe, euch zu besuchen – ich bin bis jetzt nur immer wieder an der Ausführung (meiner Absicht) gehindert worden –, um auch bei euch ebenso wie bei den übrigen Heidenvölkern einige Frucht zu erlangen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 1, 14, 'Den Griechen wie den Barbaren, den Gebildeten wie den Ungelehrten bin ich (zu dienen) verpflichtet;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 1, 15, 'der gute Wille ist also meinerseits vorhanden, auch euch in Rom die Heilsbotschaft zu verkünden.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 1, 16, 'Denn ich schäme mich der Heilsbotschaft nicht; ist sie doch eine Gotteskraft, die jedem, der da glaubt, die Rettung bringt, wie zuerst dem Juden, so auch dem Griechen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 1, 17, 'Denn Gottesgerechtigkeit wird in ihr geoffenbart, aus Glauben zu Glauben, wie geschrieben steht: »Der Gerechte wird aus Glauben leben.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 1, 18, 'Denn Gottes Zorn offenbart sich vom Himmel her über alle Gottlosigkeit und Ungerechtigkeit der Menschen, welche die Wahrheit in Ungerechtigkeit unterdrücken.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 1, 19, 'Denn was man von Gott erkennen kann, das ist in ihnen wohlbekannt; Gott selbst hat es ihnen ja kundgetan.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 1, 20, 'Sein unsichtbares Wesen läßt sich ja doch seit Erschaffung der Welt an seinen Werken mit dem geistigen Auge deutlich ersehen, nämlich seine ewige Macht und göttliche Größe. Daher gibt es keine Entschuldigung für sie,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 1, 21, 'weil sie Gott zwar kannten, ihm aber doch nicht als Gott Verehrung und Dank dargebracht haben, sondern in ihren Gedanken auf nichtige Dinge verfallen sind und ihr unverständiges Herz in Verfinsterung haben geraten lassen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 1, 22, 'Während sie sich ihrer angeblichen Weisheit rühmten, sind sie zu Toren geworden');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 1, 23, 'und haben die Herrlichkeit des unvergänglichen Gottes mit dem Abbild des vergänglichen Menschen und der Gestalt von Vögeln, von vierfüßigen Tieren und kriechendem Gewürm vertauscht.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 1, 24, 'Daher hat Gott sie durch die Begierden ihrer Herzen in den Schmutz der Unsittlichkeit versinken lassen, so daß ihre Leiber an ihnen selbst geschändet wurden;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 1, 25, 'denn sie haben die Wahrheit Gottes mit der Lüge vertauscht und Anbetung und Verehrung dem Geschaffenen erwiesen anstatt dem Schöpfer, der da gepriesen ist in Ewigkeit. Amen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 1, 26, 'Deshalb hat Gott sie auch in schandbare Leidenschaften fallen lassen; denn ihre Frauen haben den natürlichen Geschlechtsverkehr mit dem widernatürlichen vertauscht;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 1, 27, 'und ebenso haben auch die Männer den natürlichen Verkehr mit der Frau aufgegeben und sind in ihrer wilden Gier zueinander entbrannt, so daß sie, Männer mit Männern, die Schamlosigkeit verübten, aber auch die gebührende Strafe für ihre Verirrung an sich selbst empfingen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 1, 28, 'Und weil sie es verschmähten, Gott in rechter Erkenntnis festzuhalten, hat Gott sie in eine verworfene Sinnesweise versinken lassen, so daß sie alle Ungebühr verüben:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 1, 29, 'sie sind erfüllt mit jeglicher Ungerechtigkeit, Schlechtigkeit, Habgier und Bosheit, voll von Neid, Mordlust, Streitsucht, Arglist und Niedertracht;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 1, 30, 'sie sind Ohrenbläser, Verleumder, Gottesfeinde, gewalttätige und hoffärtige Leute, Prahler, erfinderisch im Bösen, ungehorsam gegen die Eltern,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 1, 31, 'unverständig, treulos, ohne Liebe und Erbarmen;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 1, 32, 'sie kennen zwar die göttliche Rechtsordnung genau, daß, wer derartiges verübt, den Tod verdient, tun es aber trotzdem nicht nur selbst, sondern spenden auch noch denen Beifall, die solche Dinge verüben.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 2, 1, 'Daher gibt es (auch) für dich, o Mensch, wer du auch sein magst, der du dich zum Richter (über andere) machst, keine Entschuldigung; denn worin du den anderen richtest, darin verurteilst du dich selbst; du, sein Richter, begehst ja dieselben Sünden!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 2, 2, 'Wir wissen aber, daß Gottes Gericht der Wahrheit gemäß über die ergeht, welche derartiges verüben.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 2, 3, 'Rechnest du etwa darauf, o Mensch, der du dich zum Richter über solche Übeltäter machst und doch selber das Gleiche verübst, daß du dem Urteil Gottes (beim jüngsten Gericht) entrinnen werdest?');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 2, 4, 'Oder verachtest du den Reichtum seiner Güte, Geduld und Langmut, und erkennst du nicht, daß Gottes Güte dich zur Buße führen will?');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 2, 5, 'Mit deinem Starrsinn und unbußfertigen Herzen aber häufst du dir selbst Zorn auf für den Tag des Zorns und der Offenbarung des gerechten Gerichts Gottes,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 2, 6, 'der einem jeden nach seinen Werken vergelten wird,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 2, 7, 'nämlich ewiges Leben (wird er geben) denen, welche im guten Werk standhaft ausharrend, nach Herrlichkeit, Ehre und Unvergänglichkeit trachten;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 2, 8, 'dagegen (seinen) Zorn und Grimm denen, welche starrsinnig sind und der Wahrheit nicht gehorchen, sondern der Ungerechtigkeit dienen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 2, 9, 'Trübsal und Angst wird über die Seele jedes Menschen kommen, der das Böse tut, wie zunächst über den Juden, so auch über den Griechen;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 2, 10, 'dagegen Herrlichkeit, Ehre und Friede (wird) einem jeden (zuteil werden), der das Gute tut, wie zunächst dem Juden, so auch dem Griechen;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 2, 11, 'denn bei Gott gibt es kein Ansehen der Person.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 2, 12, 'Denn alle, die, ohne das (mosaische) Gesetz (zu besitzen), gesündigt haben, werden auch ohne Zutun des Gesetzes verlorengehen, und alle, die innerhalb des Gesetzes gesündigt haben, werden durch das Gesetz gerichtet werden;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 2, 13, 'denn nicht die Hörer des Gesetzes sind vor Gott gerecht, sondern (nur) die Täter des Gesetzes werden gerechtfertigt werden.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 2, 14, 'Sooft nämlich Heiden, die das Gesetz nicht haben, von Natur die Forderungen des Gesetzes erfüllen, so sind diese, weil sie das Gesetz nicht haben, sich selbst (das) Gesetz;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 2, 15, 'sie liefern ja dadurch den tatsächlichen Beweis, daß das vom Gesetz gebotene Tun ihnen ins Herz geschrieben ist, wofür auch ihr Gewissen sein Zeugnis ablegt und ebenso ihre Gedanken, die im Widerstreit miteinander Anklagen erheben oder auch Entschuldigungen vorbringen –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 2, 16, '(das wird sich) an dem Tage (herausstellen), an welchem Gott das in den (Herzen der) Menschen Verborgene richten wird, (und zwar) nach der Heilsbotschaft, wie ich sie verkündige, durch Jesus Christus.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 2, 17, 'Wenn andererseits du dich mit Stolz einen Juden nennst und dich durch den Besitz des Gesetzes gesichert fühlst und dich deines Verhältnisses zu Gott rühmst');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 2, 18, 'und seinen Willen kennst und infolge der aus dem Gesetz gewonnenen Unterweisung das, was in jedem Fall das Richtige ist, wohl zu beurteilen verstehst');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 2, 19, 'und dir zutraust, ein Führer der Blinden zu sein, ein Licht für die in der Finsternis Lebenden,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 2, 20, 'ein Erzieher der Unverständigen, ein Lehrer der Unmündigen, weil du ja im Gesetz die Erkenntnis und Wahrheit verkörpert besitzest –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 2, 21, 'nun, andere Leute belehrst du, und dich selbst belehrst du nicht? Du predigst, man dürfe nicht stehlen, und stiehlst selbst?');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 2, 22, 'Du sagst, man dürfe nicht ehebrechen, und brichst selber die Ehe? Du verabscheust die Götzenbilder und vergreifst dich doch räuberisch an ihren Tempeln?');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 2, 23, 'Du rühmst dich des Gesetzes und verunehrst doch Gott durch deine Übertretung des Gesetzes?');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 2, 24, 'Denn »der Name Gottes wird durch eure Schuld unter den Heiden gelästert«, wie geschrieben steht.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 2, 25, 'Denn was die Beschneidung betrifft, so ist sie zwar eine heilsame Sache, wenn du nämlich das Gesetz tatsächlich hältst; bist du aber ein Übertreter des Gesetzes, so ist dir die Beschneidung zum Unbeschnittensein geworden.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 2, 26, 'Wenn umgekehrt der Unbeschnittene die Forderungen des Gesetzes beobachtet, wird ihm dann sein Unbeschnittensein nicht als Beschneidung angerechnet werden?');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 2, 27, 'Ja, der von Natur Unbeschnittene, der das Gesetz erfüllt, wird (am Gerichtstage) das Urteil über dich sprechen, der du trotz (deines) geschriebenen Gesetzes und (trotz deiner) Beschneidung ein Übertreter des Gesetzes bist.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 2, 28, 'Denn nicht der ist (in Wahrheit) ein Jude, der es sichtbar ist, und die (rechte) Beschneidung besteht nicht in dem, was äußerlich am Fleisch vorgenommen wird;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 2, 29, 'nein, (nur) der ist ein Jude, der es innerlich ist, und die Beschneidung muß am Herzen vollzogen sein im Geist, nicht (äußerlich) nach dem Buchstaben – das Lob eines solchen kommt nicht von Menschen her, sondern von Gott.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 3, 1, 'Was bleibt hiernach überhaupt noch als Vorzug der Juden (vor den Heiden) oder als Nutzen der Beschneidung bestehen?');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 3, 2, 'Immerhin viel in jeder Hinsicht! Zuerst, daß ihnen die Verheißungen Gottes anvertraut worden sind.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 3, 3, 'Denn nicht wahr, wenn manche sich untreu erwiesen haben – wird etwa deren Untreue die Treue Gottes aufheben?');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 3, 4, 'Nimmermehr! Es bleibt vielmehr dabei: Gott ist wahrhaftig, ob auch jeder Mensch ein Lügner ist, wie es in der Schrift heißt: »Du sollst in deinen Worten als gerecht erfunden werden und Sieger bleiben, wenn man mit dir rechtet.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 3, 5, 'Wenn aber so unsere Ungerechtigkeit die Gerechtigkeit Gottes erweist, was sollen wir daraus folgern? Ist Gott dann nicht ungerecht, wenn er seinen Zorn verhängt? – ich rede da nach gewöhnlicher Menschenweise. –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 3, 6, 'Nimmermehr! Wie sollte Gott sonst wohl Richter der ganzen Welt sein können?');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 3, 7, 'Wenn aber Gottes Wahrhaftigkeit infolge meines Lügens um so stärker zu seiner Verherrlichung hervorgetreten ist, warum werde auch ich dann noch als Sünder gerichtet?');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 3, 8, 'Und warum halten wir uns dann nicht an den Grundsatz, den manche Lästerzungen mir wirklich in den Mund legen: »Laßt uns das Böse tun, damit das Gute dabei herauskomme?« Nun, die betreffenden Leute trifft das verdammende Urteil mit Fug und Recht.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 3, 9, 'Wie steht es also? Haben wir (Juden) für uns etwas voraus? Nicht unbedingt. Wir haben ja schon vorhin gegen Juden ebenso wie gegen Griechen die Anklage erheben müssen, daß sie ausnahmslos unter (der Herrschaft) der Sünde stehen,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 3, 10, 'wie es in der Schrift heißt: »Es gibt keinen Gerechten, auch nicht einen;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 3, 11, 'es gibt keinen Einsichtigen, keinen, der Gott mit Ernst sucht;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 3, 12, 'sie sind alle abgewichen, allesamt entartet; keiner ist da, der das Gute tut, auch nicht ein einziger.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 3, 13, '»Ein offenes Grab ist ihre Kehle, mit ihren Zungen reden sie Trug.« »Otterngift ist unter ihren Lippen.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 3, 14, '»Ihr Mund ist voll Fluchens und Bitterkeit.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 3, 15, '»Schnell sind ihre Füße, Blut zu vergießen;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 3, 16, 'Verwüstung und Unheil sind auf ihren Wegen,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 3, 17, 'und den Weg des Friedens kennen sie nicht.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 3, 18, '»Keine Furcht Gottes steht ihnen vor Augen.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 3, 19, 'Wir wissen aber, daß das Gesetz alles, was es ausspricht, denen vorhält, die unter dem Gesetz sind; es soll eben einem jeden der Mund gestopft werden und die ganze Welt dem Gericht Gottes verfallen sein;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 3, 20, 'denn aufgrund von Gesetzeswerken wird kein Fleisch vor Gott gerechtfertigt werden; durch das Gesetz kommt ja (nur) Erkenntnis der Sünde.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 3, 21, 'Jetzt aber ist, unabhängig vom Gesetz, jedoch bezeugt von dem Gesetz und den Propheten, die Gottesgerechtigkeit geoffenbart worden,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 3, 22, 'nämlich die Gottesgerechtigkeit, die durch den Glauben an Jesus Christus für alle da ist und allen zukommt, die da glauben. Denn hier gibt es keinen Unterschied;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 3, 23, 'alle haben ja gesündigt und ermangeln des Ruhmes, den Gott verleiht;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 3, 24, 'so werden sie umsonst durch seine Gnade gerechtfertigt vermöge der Erlösung, die in Christus Jesus (erfolgt) ist.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 3, 25, 'Ihn hat Gott in seinem Blute als ein durch den Glauben wirksames Sühnemittel hingestellt, damit er seine Gerechtigkeit erweise, weil die Sünden, die früher während der Zeiten der Langmut Gottes begangen worden waren, bisher ungestraft geblieben waren;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 3, 26, 'er wollte also seine Gerechtigkeit in der gegenwärtigen Zeit erweisen, damit er selbst als gerecht dastehe und (zugleich) jeden, der den Glauben an Jesus besitzt, für gerecht erkläre.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 3, 27, 'Wo bleibt nun da das Rühmen? Es ist ausgeschlossen! Durch was für ein Gesetz? Durch das der Werke? Nein, sondern durch das Gesetz des Glaubens.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 3, 28, 'Denn wir halten dafür, daß der Mensch durch den Glauben gerechtfertigt werde ohne Gesetzeswerke.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 3, 29, 'Oder ist Gott etwa nur der Juden und nicht auch der Heiden Gott? Jawohl, auch der Heiden,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 3, 30, 'so gewiß es nur einen einzigen Gott gibt, der die Beschnittenen aus Glauben und die Unbeschnittenen durch den Glauben rechtfertigen wird.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 3, 31, 'Heben wir demnach das Gesetz durch den Glauben auf? Nimmermehr! Nein, wir geben dem Gesetz die rechte Stellung.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 4, 1, 'Was werden wir somit von unserm Stammvater Abraham sagen? Was hat er nach dem Fleisch erlangt?');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 4, 2, 'Wenn Abraham nämlich aufgrund von Werken gerechtfertigt worden ist, so hat er allerdings Grund, sich zu rühmen, freilich (auch dann) nicht vor Gott.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 4, 3, 'Denn was sagt die Schrift? »Abraham glaubte Gott, und das wurde ihm zur Gerechtigkeit gerechnet.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 4, 4, 'Wenn nun jemand Werke verrichtet, so erhält er den Lohn nicht aus Gnade angerechnet, sondern (zugeteilt) nach Schuldigkeit;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 4, 5, 'wer dagegen keine Werke verrichtet, sondern an den glaubt, der den Gottlosen rechtfertigt, dem wird sein Glaube zur Gerechtigkeit gerechnet;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 4, 6, 'wie ja auch David die Seligpreisung über den Menschen ausspricht, dem Gott Gerechtigkeit ohne Rücksicht auf Werke anrechnet:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 4, 7, '»Glückselig sind die, denen die Gesetzesübertretungen vergeben und deren Sünden zugedeckt worden sind;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 4, 8, 'glückselig ist der Mann, dem der Herr (die) Sünde nicht anrechnet.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 4, 9, 'Gilt nun diese Seligpreisung nur den Beschnittenen oder auch den Unbeschnittenen? Wir behaupten ja doch: »Dem Abraham wurde sein Glaube zur Gerechtigkeit gerechnet.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 4, 10, 'Unter welchen Umständen hat denn diese Anrechnung stattgefunden? Als er schon beschnitten oder als er noch unbeschnitten war? Nun: nicht als er schon beschnitten, sondern als er noch unbeschnitten war;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 4, 11, 'und das äußere Zeichen der Beschneidung empfing er dann als Siegel für die Glaubensgerechtigkeit, die er im Zustande der Unbeschnittenheit besessen hatte. So sollte er der Vater aller derer werden, die ohne Beschneidung glauben, damit ihnen die Gerechtigkeit angerechnet werde,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 4, 12, 'und (ebenso) der Vater der Beschnittenen, nämlich derer, die nicht nur infolge der (leiblichen) Beschneidung ihm angehören, sondern die auch in den Fußtapfen des Glaubens wandeln, den unser Vater Abraham schon in unbeschnittenem Zustande besessen hat.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 4, 13, 'Denn die Verheißung, die Abraham oder sein Samen empfangen hat, daß er der Erbe der Welt sein sollte, ist ihm nicht durch das Gesetz zuteil geworden, sondern durch die Glaubensgerechtigkeit.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 4, 14, 'Wenn nämlich die Gesetzesleute die Erben sind, so ist damit der Glaube entleert und die Verheißung entkräftet;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 4, 15, 'denn das Gesetz bringt (nur) Zorn zustande; wo dagegen kein Gesetz ist, da gibt es auch keine Übertretung.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 4, 16, 'Deshalb ist es an den Glauben gebunden – es soll ja ein Gnadengeschenk sein –, damit die Verheißung für die gesamte Nachkommenschaft Gültigkeit habe, und zwar nicht nur für die, welche es aufgrund des Gesetzes ist, sondern auch für die, welche wie Abraham glaubt, der ja unser aller Vater ist –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 4, 17, 'nach dem Schriftwort: »Zum Vater vieler Völker habe ich dich gesetzt« – vor dem Gott, dem er geglaubt hat als dem, welcher die Toten lebendig macht und das noch nicht Vorhandene benennt, als wäre es schon vorhanden.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 4, 18, 'Abraham hat da, wo nichts zu hoffen war, doch hoffnungsvoll am Glauben festgehalten, damit er der Vater vieler Völker würde nach der Verheißung: »So (unzählbar) soll deine Nachkommenschaft sein«;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 4, 19, 'und ohne im Glauben schwach zu werden, nahm er, der fast hundertjährige Mann, die Erstorbenheit seines eigenen Leibes und den schon erstorbenen Mutterschoß der Sara wahr.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 4, 20, 'Trotzdem ließ er sich im Hinblick auf die Verheißung Gottes nicht durch Unglauben irre machen, sondern vielmehr wurde er im Glauben immer stärker, indem er Gott die Ehre gab');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 4, 21, 'und der festen Überzeugung lebte, daß Gott das, was er verheißen hatte, auch zu verwirklichen vermöge.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 4, 22, 'Darum ist es ihm auch zur Gerechtigkeit gerechnet worden.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 4, 23, 'Aber nicht nur um seinetwillen steht geschrieben, daß es ihm angerechnet worden ist,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 4, 24, 'sondern auch um unsertwillen; denn auch uns soll es angerechnet werden, uns, die wir an den glauben, der unsern Herrn Jesus von den Toten auferweckt hat,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 4, 25, 'ihn, der um unserer Übertretungen willen in den Tod gegeben und um unserer Rechtfertigung willen auferweckt worden ist.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 5, 1, 'Da wir nun aus Glauben gerechtfertigt worden sind, so haben wir Frieden mit Gott durch unsern Herrn Jesus Christus,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 5, 2, 'durch den wir im Glauben auch den Zugang zu unserm jetzigen Gnadenstande erlangt haben, und wir rühmen uns auch der Hoffnung auf die Herrlichkeit Gottes.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 5, 3, 'Ja noch mehr als das: wir rühmen uns dessen sogar in den Trübsalen, weil wir wissen, daß die Trübsal standhaftes Ausharren wirkt,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 5, 4, 'das standhafte Ausharren Bewährung, die Bewährung Hoffnung;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 5, 5, 'die Hoffnung aber führt nicht zur Enttäuschung, weil die Liebe Gottes in unsere Herzen ausgegossen ist durch den heiligen Geist, der uns verliehen worden ist.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 5, 6, 'Denn Christus ist ja, als wir nach Lage der Dinge noch schwach waren, für Gottlose gestorben.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 5, 7, 'Denn kaum wird (sonst wohl) jemand für einen Gerechten den Tod erleiden – doch für den Guten entschließt sich vielleicht noch jemand dazu, sogar sein Leben hinzugeben –;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 5, 8, 'Gott aber beweist seine Liebe zu uns dadurch, daß Christus für uns gestorben ist, als wir noch Sünder waren.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 5, 9, 'So werden wir also jetzt, nachdem wir durch sein Blut gerechtfertigt sind, noch viel gewisser durch ihn vor dem Zorn (Gottes) gerettet werden.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 5, 10, 'Denn wenn wir, als wir noch Feinde Gottes waren, mit ihm durch den Tod seines Sohnes versöhnt worden sind, so werden wir jetzt als Versöhnte noch viel gewisser Rettung finden durch sein Leben.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 5, 11, 'Aber noch mehr: wir rühmen uns sogar Gottes durch unsern Herrn Jesus Christus, durch den wir jetzt die Versöhnung empfangen haben.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 5, 12, 'Darum, gleichwie durch einen Menschen die Sünde in die Welt hineingekommen ist und durch die Sünde der Tod, und so der Tod zu allen Menschen hindurchgedrungen ist, weil sie ja alle gesündigt haben –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 5, 13, 'denn bis zum Gesetz war Sünde in der Welt vorhanden, die Sünde wird nur nicht angerechnet, wenn kein Gesetz vorhanden ist;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 5, 14, 'aber trotzdem hat der Tod seine Herrschaft unbeschränkt von Adam bis Mose sogar über die ausgeübt, welche sich nicht durch Übertretung (eines vorliegenden Gebotes) in gleicher Weise versündigt hatten wie Adam, der das Vorbild des zukünftigen (Adam) ist.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 5, 15, 'Jedoch verhält es sich mit der Gnadengabe (Jesu) nicht so wie mit der Übertretung (Adams). Denn wenn (dort) die Übertretung des Einen den Tod der Vielen zur Folge gehabt hat, so hat sich (hier) die Gnade Gottes und die Gnadengabe des einen Menschen Jesus Christus erst recht an den Vielen überreich erwiesen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 5, 16, 'Auch ist bei der Gabe die Wirkung nicht so wie dort, wo ein einziger Sünder den Anlaß gegeben hat. Denn (dort) ist das Urteil aus Anlaß eines einzigen Sünders zum Verdammungsurteil geworden, (hier) dagegen die Gnadengabe aus Anlaß dieser Übertretungen zum Rechtfertigungsurteil.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 5, 17, 'Denn wenn (dort) infolge der Übertretung des Einen der Tod durch die Schuld jenes Einen seine Herrschaft unbeschränkt ausgeübt hat, so werden (hier) noch viel gewisser die, welche die überschwengliche Fülle der Gnade und des Geschenks der Gerechtigkeit empfangen, im (künftigen) Leben als Könige herrschen durch den Einen, Jesus Christus.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 5, 18, 'Also: wie es durch eine einzige Übertretung für alle Menschen zum Verdammungsurteil gekommen ist, so kommt es auch durch eine einzige Rechttat für alle Menschen zur lebenwirkenden Rechtfertigung.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 5, 19, 'Wie nämlich durch den Ungehorsam des einen Menschen die Vielen als Sünder hingestellt worden sind, ebenso werden auch durch den Gehorsam des Einen die Vielen als Gerechte hingestellt werden.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 5, 20, 'Das Gesetz aber ist nur nebenbei hereingekommen, damit die Übertretung noch größer würde. Wo aber die Sünde zugenommen hatte, da ist die Gnade erst recht überreich hervorgetreten,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 5, 21, 'damit, gleichwie die Sünde königlich geherrscht hat durch den Tod, so auch die Gnade ihre Königsherrschaft ausübe durch (gottgewirkte) Gerechtigkeit zum ewigen Leben durch Jesus Christus, unsern Herrn.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 6, 1, 'Was folgt nun daraus? Wollen wir in der Sünde verharren, damit die Gnade sich um so reicher erweise?');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 6, 2, 'Nimmermehr! Wie sollten wir, die wir der Sünde gestorben sind, in ihr noch weiterleben?');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 6, 3, 'Oder wißt ihr nicht, daß wir alle, die wir auf Christus Jesus getauft worden sind, auf seinen Tod getauft worden sind?');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 6, 4, 'Wir sind also deshalb durch die Taufe in den Tod mit ihm begraben worden, damit, gleichwie Christus von den Toten auferweckt worden ist durch die Herrlichkeit des Vaters, ebenso auch wir in einem neuen Leben wandeln.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 6, 5, 'Denn wenn wir mit ihm zur Gleichheit des Todes verwachsen sind, so werden wir es auch hinsichtlich seiner Auferstehung sein;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 6, 6, 'wir erkennen ja dies, daß unser alter Mensch deshalb mitgekreuzigt worden ist, damit der von der Sünde beherrschte Leib vernichtet werde, auf daß wir hinfort nicht mehr der Sünde als Sklaven dienen;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 6, 7, 'denn wer gestorben ist, der ist dadurch von (jedem Rechtsanspruch) der Sünde freigesprochen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 6, 8, 'Sind wir aber mit Christus gestorben, so glauben wir zuversichtlich, daß wir auch mit ihm leben werden,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 6, 9, 'da Christus, wie wir wissen, nach seiner Auferweckung von den Toten nicht mehr stirbt: der Tod hat keine Herrschermacht mehr über ihn.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 6, 10, 'Denn den Tod, den er gestorben ist, hat er der Sünde ein für allemal entrichtet, das Leben aber, das er (jetzt) lebt, ist Leben für Gott.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 6, 11, 'Ebenso müßt auch ihr euch als tot für die Sünde betrachten, aber als lebend für Gott in Christus Jesus, unserm Herrn.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 6, 12, 'So darf also die Sünde in eurem sterblichen Leibe nicht mehr so herrschen, daß ihr seinen Begierden Gehorsam leistet;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 6, 13, 'und stellet auch eure Glieder nicht mehr als Waffen der Ungerechtigkeit in den Dienst der Sünde; stellet euch vielmehr als solche, die aus dem Tode zum Leben erstanden sind, in den Dienst Gottes, und gebt (so) eure Glieder als Waffen der Gerechtigkeit an Gott hin!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 6, 14, 'Denn die Sünde wird kein Herrscherrecht (mehr) über euch ausüben: ihr steht ja nicht (mehr) unter dem Gesetz, sondern unter der Gnade.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 6, 15, 'Was folgt nun daraus? Wollen wir sündigen, weil wir nicht unter dem Gesetz, sondern unter der Gnade stehen? Nimmermehr!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 6, 16, 'Ihr wißt ja doch, daß, wenn ihr euch jemand als Knechte zum Gehorsam hingebt, ihr dann auch dessen Knechte seid und ihm Gehorsam zu leisten habt, und zwar entweder (als Knechte) der Sünde, was zum Tode führt, oder (als Knechte) des Gehorsams (gegen Gott), wodurch ihr zur (lebenspendenden) Gerechtigkeit gelangt.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 6, 17, 'Gott aber sei Dank, daß ihr früher zwar Knechte der Sünde gewesen seid, jetzt aber euch von Herzen der Lehre in der Gestalt angeschlossen habt, wie ihr derselben übergeben worden seid!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 6, 18, 'So seid ihr nunmehr von (der Herrschaft) der Sünde frei geworden und in den Dienst der Gerechtigkeit getreten –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 6, 19, 'ich gebrauche da einen Ausdruck, der menschlichen Verhältnissen entnommen ist, und zwar mit Rücksicht auf die Schwachheit eures Fleisches. Denn wie ihr vordem eure Glieder in den Knechtsdienst der Unsittlichkeit und der Gesetzlosigkeit zu einem gesetzlosen Leben gestellt habt, ebenso stellet jetzt eure Glieder als Knechte in den Dienst der Gerechtigkeit, um zur Heiligung zu gelangen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 6, 20, 'Denn damals, als ihr Knechte der Sünde waret, da waret ihr freie Leute gegenüber der Gerechtigkeit.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 6, 21, 'Welche Frucht habt ihr nun damals aufzuweisen gehabt? Nur solche (Früchte), deren ihr euch jetzt schämt; denn das Ende davon ist der Tod.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 6, 22, 'Jetzt dagegen, wo ihr von der Sünde frei und Knechte Gottes geworden seid, habt ihr als eure Frucht die Heiligung und als Endergebnis das ewige Leben.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 6, 23, 'Denn der Sold, den die Sünde zahlt, ist der Tod, die Gnadengabe Gottes aber ist das ewige Leben in Christus Jesus, unserm Herrn.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 7, 1, 'Oder wißt ihr nicht, meine Brüder – ich rede ja doch zu gesetzeskundigen Leuten –, daß das Gesetz für den Menschen nur, solange er lebt, bindende Gewalt hat?');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 7, 2, 'So ist z.B. eine verheiratete Frau gesetzlich an ihren Mann so lange gebunden, als er lebt; wenn aber der Mann stirbt, so ist sie frei von dem Gesetz, das sie an den Mann bindet.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 7, 3, 'Demnach wird sie zwar, solange ihr Mann lebt, allgemein als Ehebrecherin gelten, wenn sie sich einem andern Manne zu eigen gibt; stirbt aber ihr Mann, so ist sie frei vom Gesetz und keine Ehebrecherin, wenn sie sich einem andern Mann zu eigen gibt.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 7, 4, 'Mithin seid auch ihr, meine Brüder, dem Gesetz gegenüber getötet worden, und zwar durch (das Getötetwerden) des Leibes Christi, um hinfort einem anderen, nämlich dem, der von den Toten auferweckt worden ist, als Eigentum anzugehören, damit wir nunmehr für Gott Frucht brächten.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 7, 5, 'Denn solange wir im Fleische waren, wirkten sich die durch das Gesetz erregten sündhaften Leidenschaften in unsern Gliedern in der Weise aus, daß wir für den Tod Frucht brachten.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 7, 6, 'Jetzt aber sind wir vom Gesetz losgekommen, da wir dem, was uns in Banden hielt, gestorben sind, so daß wir nunmehr unsern Dienst im neuen Wesen des Geistes und nicht mehr im alten Wesen des Buchstabens (des Gesetzes) leisten.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 7, 7, 'Was folgt nun daraus? Ist das Gesetz (selbst) Sünde? Nimmermehr! Aber ich hätte die Sünde nicht kennengelernt außer durch das Gesetz; denn ich hätte auch von der bösen Lust nichts gewußt, wenn das Gesetz nicht gesagt hätte: »Laß dich nicht gelüsten!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 7, 8, 'Da hat die Sünde eine Angriffsgelegenheit gegen mich gewonnen und durch das Gebot jegliche böse Lust in mir zustande gebracht; denn ohne Gesetz ist die Sünde tot.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 7, 9, 'Ich lebte einst ohne das Gesetz; als dann aber das Gebot (des Gesetzes) kam, lebte die Sünde (in mir) auf,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 7, 10, 'für mich aber kam der Tod; und so erwies sich dasselbe Gebot, das doch zum Leben verhelfen soll, für mich als todbringend;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 7, 11, 'denn nachdem die Sünde eine Angriffsgelegenheit gegen mich gewonnen hatte, betrog sie mich durch das Gebot und brachte mir durch dieses den Tod.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 7, 12, 'Demnach ist das Gesetz (an sich) heilig und ebenso das Gebot heilig, gerecht und gut.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 7, 13, 'So hat also etwas Gutes mir den Tod gebracht? O nein, das hat vielmehr die Sünde getan: sie sollte als Sünde zutage treten, indem sie mir durch das Gute den Tod brachte; sie sollte sich eben durch das Gebot als über alle Maßen sündig erweisen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 7, 14, 'Wir wissen ja, daß das Gesetz geistlich ist; ich aber bin von fleischlicher Art (und dadurch) unter die (Gewalt der) Sünde verkauft.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 7, 15, 'Ja, mein ganzes Tun ist mir unbegreiflich; denn ich vollbringe nicht das, was ich will, sondern tue das, was ich hasse.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 7, 16, 'Wenn ich aber das tue, was ich nicht will, so erkenne ich durch die innere Zustimmung zum Gesetz an, daß dieses gut sei.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 7, 17, 'Jetzt aber bin nicht mehr ich der, welcher es vollbringt, sondern die in mir wohnende Sünde.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 7, 18, 'Denn ich weiß ja: in mir, das heißt in meinem Fleische, wohnt nichts Gutes; denn der gute Wille ist bei mir wohl vorhanden, dagegen das Vollbringen des Guten nicht;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 7, 19, 'denn ich tue nicht das Gute, das ich tun will, sondern vollbringe das Böse, das ich nicht tun will.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 7, 20, 'Wenn ich aber das tue, was ich nicht will, so bin nicht mehr ich es, der es vollbringt, sondern die in mir wohnende Sünde.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 7, 21, 'Ich finde somit bei mir, der ich das Gute tun will, das Gesetz vor, daß bei mir das Böse zustande kommt.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 7, 22, 'Denn nach meinem inneren Menschen stimme ich dem göttlichen Gesetz freudig zu,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 7, 23, 'nehme aber in meinen Gliedern ein andersartiges Gesetz wahr, das dem Gesetz meiner Vernunft widerstreitet und mich gefangennimmt unter das Gesetz der Sünde, das in meinen Gliedern wirkt.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 7, 24, 'O ich unglückseliger Mensch! Wer wird mich aus diesem Todesleibe erlösen?');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 7, 25, 'Dank sei Gott; (es ist geschehen) durch Jesus Christus, unsern Herrn! Also ist es so: Auf mich selbst gestellt diene ich mit der Vernunft dem Gesetz Gottes, mit dem Fleisch dagegen dem Gesetz der Sünde.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 8, 1, 'So gibt es also jetzt keine Verurteilung mehr für die, welche in Christus Jesus sind;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 8, 2, 'denn das Gesetz des Lebensgeistes in Christus Jesus hat uns von dem Gesetz der Sünde und des Todes freigemacht.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 8, 3, 'Denn was dem (mosaischen) Gesetz unmöglich war, das, worin es wegen (des Widerstandes) des Fleisches ohnmächtig war – Gott hat (es vollbracht), (nämlich) die Sünde im Fleische verurteilt, indem er seinen Sohn in der Gleichgestalt des Sündenfleisches und um der Sünde willen sandte,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 8, 4, 'damit die Rechtsforderung des Gesetzes ihre Erfüllung fände in uns, die wir nicht nach dem Fleische wandeln, sondern nach dem Geiste.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 8, 5, 'Denn die fleischlich gesinnten (Menschen) haben ein fleischliches Trachten, die geistlich gesinnten aber ein geistliches.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 8, 6, 'Denn das Trachten des Fleisches bedeutet Tod, das Trachten des Geistes dagegen Leben und Frieden,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 8, 7, 'und zwar deshalb, weil das Trachten des Fleisches Feindschaft gegen Gott ist; es unterwirft sich ja dem Gesetz Gottes nicht, vermag das auch gar nicht;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 8, 8, 'so können denn die fleischlich gerichteten (Menschen) Gott nicht gefallen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 8, 9, 'Ihr dagegen seid nicht im Fleisch, sondern im Geist, wenn nämlich Gottes Geist wirklich in euch wohnt; wenn aber jemand den Geist Christi nicht hat, so gehört ein solcher (Mensch) ihm auch nicht an.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 8, 10, 'Wohnt dagegen Christus in euch, so ist euer Leib zwar tot um der Sünde willen, euer Geist aber ist Leben um der Gerechtigkeit willen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 8, 11, 'Und wenn der Geist dessen, der Jesus von den Toten auferweckt hat, in euch wohnt, so wird er, der Christus von den Toten auferweckt hat, auch eure sterblichen Leiber lebendig machen durch seinen in euch wohnenden Geist.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 8, 12, 'Somit haben wir, liebe Brüder, nicht dem Fleische gegenüber die Verpflichtung, nach dem Fleische zu leben;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 8, 13, 'denn wenn ihr nach dem Fleische lebt, so ist euch der Tod gewiß; wenn ihr dagegen durch den Geist die Geschäfte des Leibes tötet, so werdet ihr leben.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 8, 14, 'Denn alle, die vom Geiste Gottes geleitet werden, die sind Söhne Gottes.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 8, 15, 'Der Geist, den ihr empfangen habt, ist ja doch nicht ein Geist der Knechtschaft, so daß ihr euch aufs neue fürchten müßtet; sondern ihr habt den Geist der Sohnschaft empfangen, in welchem wir rufen: »Abba, (lieber) Vater!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 8, 16, 'Eben dieser Geist ist es, der vereint mit unserm Geiste ihm bezeugt, daß wir Gottes Kinder sind.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 8, 17, 'Sind wir aber Kinder, so sind wir auch Erben, und zwar Erben Gottes und Miterben Christi, wenn wir nämlich mit ihm leiden, um (einst) auch an seiner Herrlichkeit teilzunehmen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 8, 18, 'Ich halte nämlich dafür, daß die Leiden der Jetztzeit nicht wert sind, verglichen zu werden mit der Herrlichkeit, die an uns geoffenbart werden soll.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 8, 19, 'Denn das sehnsüchtige Harren des Geschaffenen wartet auf das Offenbarwerden (der Herrlichkeit) der Söhne Gottes.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 8, 20, 'Denn der Nichtigkeit ist die ganze Schöpfung unterworfen worden – allerdings nicht freiwillig, sondern um dessen willen, der ihre Unterwerfung bewirkt hat –, jedoch auf die Hoffnung hin,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 8, 21, 'daß auch sie selbst, die Schöpfung, von der Knechtschaft der Vergänglichkeit befreit werden wird zur (Teilnahme an der) Freiheit, welche die Kinder Gottes im Stande der Verherrlichung besitzen werden.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 8, 22, 'Wir wissen ja, daß die gesamte Schöpfung bis jetzt noch überall seufzt und mit Schmerzen einer Neugeburt harrt.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 8, 23, 'Aber nicht nur sie, sondern auch wir selbst, die wir doch den Geist als Erstlingsgabe bereits besitzen, seufzen gleichfalls in unserm Inneren beim Warten auf (das Offenbarwerden) der Sohnschaft, nämlich auf die Erlösung unsers Leibes.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 8, 24, 'Denn wir sind zwar gerettet worden, aber doch (bisher) nur auf Hoffnung hin. Eine Hoffnung aber, die man schon (verwirklicht) sieht, ist keine (rechte) Hoffnung mehr; denn wozu braucht man noch auf etwas zu hoffen, das man schon (verwirklicht) sieht?');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 8, 25, 'Wenn wir dagegen auf das hoffen, was wir noch nicht (verwirklicht) sehen, so warten wir darauf in Geduld.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 8, 26, 'Gleicherweise kommt aber auch der Geist unserer Schwachheit zu Hilfe; denn wir wissen nicht, was wir so, wie es gerade not tut, beten sollen. Da tritt dann aber der Geist selbst mit unaussprechlichen Seufzern für uns ein;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 8, 27, 'der aber, der die Herzen erforscht, versteht die Sprache des Geistes, weil dieser in einer dem Willen Gottes entsprechenden Weise für Heilige eintritt.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 8, 28, 'Wir wissen aber, daß denen, die Gott lieben, alle Dinge zum Guten mitwirken, nämlich denen, welche nach seinem Vorsatz berufen sind.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 8, 29, 'Denn die, welche er zuvor ersehen hat, die hat er auch im voraus dazu bestimmt, (einst) dem Bilde seines Sohnes gleichgestaltet zu werden: dieser sollte eben der Erstgeborene unter vielen Brüdern sein.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 8, 30, 'Und die, welche er vorausbestimmt hat, die hat er auch berufen; und die er berufen hat, die hat er auch gerechtfertigt; und die er gerechtfertigt hat, denen hat er auch die (himmlische) Herrlichkeit verliehen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 8, 31, 'Was folgt nun hieraus? Wenn Gott für uns ist, wer kann dann gegen uns sein?');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 8, 32, 'Er, der seinen eigenen Sohn nicht verschont, sondern ihn für uns alle (in den Tod) dahingegeben hat: wie sollte er uns mit ihm nicht auch alles (andere) schenken?');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 8, 33, 'Wer will Anklage gegen die Auserwählten Gottes erheben? Gott ist es ja, der sie rechtfertigt.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 8, 34, 'Wer will sie verurteilen? Etwa Christus Jesus, der doch (für uns) gestorben ist, ja, mehr noch, der auferweckt worden ist, der zur Rechten Gottes sitzt und auch für uns eintritt?');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 8, 35, 'Wer will uns von der Liebe Christi scheiden? Etwa Trübsal oder Bedrängnis, Verfolgung oder Hunger oder Mangel an Kleidung, Gefahr oder Henkerbeil?');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 8, 36, 'Wie geschrieben steht: »Um deinetwillen werden wir den ganzen Tag gemordet; wir sind geachtet wie Schlachtschafe.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 8, 37, 'Nein, in dem allem siegen wir weitaus durch den, der uns geliebt hat.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 8, 38, 'Denn ich bin dessen gewiß, daß weder Tod noch Leben, weder Engel noch Gewalten, weder Gegenwärtiges noch Zukünftiges noch irgendwelche Mächte,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 8, 39, 'weder Höhe noch Tiefe noch sonst irgendetwas anderes Geschaffenes imstande sein wird, uns von der Liebe Gottes zu scheiden, die da ist in Christus Jesus, unserm Herrn.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 9, 1, 'Ich sage die Wahrheit in Christus, ich lüge nicht – mein Gewissen bezeugt es mir im heiligen Geist –:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 9, 2, 'ich trage schweren Kummer und unaufhörlichen Schmerz in meinem Herzen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 9, 3, 'Gern wollte ich selbst durch einen Fluch aus der Gemeinschaft mit Christus ausgestoßen sein, wenn ich dadurch meine Brüder, meine Volksgenossen nach dem Fleische, retten könnte;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 9, 4, 'sie sind ja doch Israeliten, denen der Sohnesstand und die Herrlichkeit Gottes, die Bündnisse und die Gesetzgebung, der Gottesdienst und die Verheißungen zuteil geworden sind,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 9, 5, 'denen die Erzväter angehören und aus denen der Messias dem Fleische nach stammt: der da Gott über allem ist, gepriesen in Ewigkeit! Amen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 9, 6, 'Ich will damit aber nicht gesagt haben, daß Gottes Verheißungswort hinfällig geworden sei; denn nicht alle, die aus Israel stammen, sind Israel,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 9, 7, 'und nicht alle sind schon deshalb, weil sie Abrahams Same sind, auch seine Kinder; sondern: »In Isaak soll dir Nachkommenschaft genannt werden.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 9, 8, 'Das will ich sagen: Nicht die leiblichen Kinder (Abrahams) sind damit auch Gottes Kinder, sondern (nur) die Kinder der Verheißung werden als Nachkommenschaft (Abrahams) gerechnet.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 9, 9, 'Denn so lautet das Wort der Verheißung: »(Übers Jahr) um diese Zeit werde ich (wieder-) kommen, da wird Sara einen Sohn haben.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 9, 10, 'Und nicht nur hier ist es so gewesen, sondern auch bei Rebekka, die von einem und demselben Manne, nämlich unserm Vater Isaak, guter Hoffnung war.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 9, 11, 'Denn ehe sie (ihre beiden Kinder) noch geboren waren und irgend etwas Gutes oder Böses getan hatten, schon da wurde – damit Gottes Vorherbestimmung aus freier Wahl bestehen bliebe,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 9, 12, 'abhängig nicht von Werken, sondern (allein) von dem (Willen des) Berufenden – der Rebekka gesagt: »Der Ältere wird dem Jüngeren dienstbar sein«;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 9, 13, 'wie ja auch (anderswo) geschrieben steht: »Jakob habe ich geliebt, Esau aber habe ich gehaßt.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 9, 14, 'Was folgt nun daraus? Liegt da etwa Ungerechtigkeit auf seiten Gottes vor? Nimmermehr!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 9, 15, 'Zu Mose sagt er ja: »Ich werde Gnade erweisen, wem ich gnädig bin, und werde Barmherzigkeit dem erzeigen, dessen ich mich erbarme.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 9, 16, 'Demnach kommt es nicht auf jemandes Wollen oder Laufen an, sondern auf Gottes Erbarmen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 9, 17, 'So sagt ja auch die Schrift zum Pharao: »Gerade dazu habe ich dich in die Welt kommen lassen, um an dir meine Macht zu erweisen und damit mein Name auf der ganzen Erde verkündet werde.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 9, 18, 'Also: Gott erbarmt sich, wessen er will, und verstockt auch, wen er will.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 9, 19, 'Da wirst du mir nun einwenden: »Wie kann er dann noch (jemand) tadeln? Wer vermöchte denn seinem Willen Widerstand zu leisten?«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 9, 20, 'Ja, o Mensch, wer bist denn du, daß du Gott zur Verantwortung ziehen willst? Darf etwa das Gebilde zu seinem Bildner sagen: »Warum hast du mich so gemacht?«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 9, 21, 'Oder hat der Töpfer nicht Macht über den Ton, aus derselben Masse hier ein Gefäß zu ehrenvoller Bestimmung und dort ein anderes zu gemeiner Verwendung zu verfertigen?');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 9, 22, 'Wie aber, wenn Gott, obgleich er seinen Zorn offenbaren und seine Macht an den Tag legen will, doch die Gefäße des Zornes, die zur Vernichtung hergestellt sind, mit großer Langmut getragen hat,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 9, 23, 'um zugleich den Reichtum seiner Herrlichkeit an Gefäßen des Erbarmens zu erweisen, die er zur (Teilnahme an seiner) Herrlichkeit zuvor bereitet hat?');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 9, 24, 'Als solche (Gefäße des Erbarmens) hat er auch uns berufen, und zwar nicht nur aus den Juden, sondern auch aus den Heiden(völkern),');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 9, 25, 'wie er ja auch bei (dem Propheten) Hosea sagt: »Ich werde das, was nicht mein Volk ist, mein Volk nennen und der Ungeliebten den Namen ›Geliebte‹ beilegen«;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 9, 26, 'und: »Es wird geschehen: an dem Orte, wo zu ihnen gesagt worden ist: ›Ihr seid nicht mein Volk‹, dort werden sie ›Söhne des lebendigen Gottes‹ genannt werden.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 9, 27, 'Jesaja ferner ruft laut im Hinblick auf Israel aus: »Wenn auch die Zahl der Söhne Israels wie der Sand am Meer wäre, wird doch nur der Rest davon gerettet werden;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 9, 28, 'denn sein Wort wird der Herr, indem er die Dinge sicher und Schlag auf Schlag verlaufen läßt, zur Ausführung auf der Erde bringen.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 9, 29, 'Und wie Jesaja vorhergesagt hat: »Hätte der Herr der Heerscharen uns nicht einen Samen übriggelassen, so wären wir wie Sodom geworden und hätten gleiches Schicksal mit Gomorrha gehabt.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 9, 30, 'Was folgt nun daraus? Dieses: Heiden, die nicht nach Gerechtigkeit trachteten, haben Gerechtigkeit erlangt, nämlich die Gerechtigkeit, die aus dem Glauben kommt;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 9, 31, 'Israel dagegen, das nach der vom Gesetz geforderten Gerechtigkeit trachtete, hat das vom Gesetz gesteckte Ziel (der Rechtfertigung) nicht erreicht.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 9, 32, 'Warum nicht? Weil sie es nicht auf dem Glaubensweg, sondern es mit Werken haben erreichen wollen: da haben sie sich am Stein des Anstoßes gestoßen,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 9, 33, 'von dem geschrieben steht: »Siehe, ich lege in Zion einen Stein des Anstoßes und einen Felsen des Ärgernisses; und wer auf ihn sein Vertrauen setzt, wird nicht zuschanden werden.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 10, 1, 'Liebe Brüder! Der aufrichtige Wunsch meines Herzens und mein Gebet zu Gott für sie geht dahin, daß sie gerettet werden;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 10, 2, 'denn ich muß ihnen das Zeugnis ausstellen, daß sie Eifer für Gott haben, aber leider nicht in der rechten Erkenntnis.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 10, 3, 'Denn weil sie die Gottesgerechtigkeit verkannt haben und dagegen beflissen sind, ihre eigene Gerechtigkeit zur Geltung zu bringen, haben sie sich der Gottesgerechtigkeit nicht unterworfen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 10, 4, 'Denn dem Gesetz hat Christus ein Ende gemacht, damit jeder, der da glaubt, zur Gerechtigkeit gelange.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 10, 5, 'Mose schreibt nämlich: »Der Mensch, der die vom Gesetz geforderte Gerechtigkeit geübt hat, wird durch sie das Leben haben.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 10, 6, 'Die Gerechtigkeit dagegen, die aus dem Glauben kommt, spricht so: »Denke nicht in deinem Herzen: ›Wer wird in den Himmel hinaufsteigen?‹ – nämlich um Christus herabzuholen –,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 10, 7, 'oder: ›Wer wird in den Abgrund hinabsteigen?‹ – nämlich um Christus von den Toten heraufzuholen« –,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 10, 8, 'sondern was sagt sie? »Nahe ist dir das Wort: in deinem Munde und in deinem Herzen (hast du es)«, nämlich das Wort vom Glauben, das wir verkündigen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 10, 9, 'Denn wenn du »mit deinem Munde« Jesus als den Herrn bekennst und »mit deinem Herzen« glaubst, daß Gott ihn von den Toten auferweckt hat, so wirst du gerettet werden.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 10, 10, 'Denn mit dem Herzen glaubt man (an ihn) zur Gerechtigkeit, und mit dem Munde bekennt man (ihn) zur Errettung.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 10, 11, 'Sagt doch die Schrift: »Keiner, der auf ihn sein Vertrauen setzt, wird zuschanden werden.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 10, 12, 'Denn hier gibt es keinen Unterschied zwischen dem Juden und dem Griechen: sie alle haben ja einen und denselben Herrn, ihn, der sich reich erweist an allen, die ihn anrufen;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 10, 13, 'denn »jeder, der den Namen des Herrn anruft, wird gerettet werden«.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 10, 14, 'Nun – wie sollen sie den anrufen, an den sie nicht zu glauben gelernt haben? Wie sollen sie aber an den glauben, von dem sie nicht gehört haben? Wie sollen sie aber von ihm hören ohne einen Verkündiger?');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 10, 15, 'Und wie soll ihnen jemand verkündigen, ohne dazu ausgesandt zu sein? – wie es in der Schrift heißt: »Wie lieblich sind die Füße derer, welche frohe Botschaft von guten Dingen bringen!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 10, 16, 'Aber freilich: nicht alle sind der Heilsbotschaft gehorsam gewesen; sagt doch (schon) Jesaja: »Herr, wer hat unserer Botschaft Glauben geschenkt?«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 10, 17, 'Mithin kommt der Glaube aus der Botschaft, die Predigt aber (erfolgt) durch Christi Wort.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 10, 18, 'Aber, frage ich: Haben sie (die Predigt) vielleicht nicht zu hören bekommen? O doch! »Über die ganze Erde ist ihr Schall gedrungen und ihre Worte bis an die Enden der bewohnten Welt.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 10, 19, 'Aber, frage ich: Hat Israel sie vielleicht nicht verstanden? O doch! (Schon) Mose sagt als erster Zeuge: »Ich will euch eifersüchtig machen auf solche, die kein Volk sind; gegen ein unverständiges Volk will ich euch erbittern.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 10, 20, 'Jesaja ferner erkühnt sich zu sagen: »Ich bin gefunden worden von denen, die mich nicht suchten; ich bin denen bekannt geworden, die nicht nach mir fragten.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 10, 21, 'Dagegen in bezug auf Israel sagt er: »Den ganzen Tag habe ich meine Arme (vergebens) ausgestreckt nach einem Volke, das ungehorsam ist und widerspricht.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 11, 1, 'So frage ich nun: Hat Gott sein Volk etwa verstoßen? Keineswegs! Ich bin doch auch ein Israelit, aus Abrahams Nachkommenschaft, aus dem Stamme Benjamin.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 11, 2, 'Nein, Gott hat sein Volk, das er zuvor ersehen hat, nicht verstoßen. Oder wißt ihr nicht, was die Schrift bei (der Erzählung von) Elia sagt, als dieser vor Gott gegen Israel mit der Klage auftritt:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 11, 3, '»Herr, deine Propheten haben sie getötet, deine Altäre niedergerissen; ich bin allein übriggeblieben, und nun trachten sie mir nach dem Leben«?');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 11, 4, 'Aber wie lautet da die göttliche Antwort an ihn? »Ich habe mir noch siebentausend Männer übrigbehalten, die ihre Knie vor Baal nicht gebeugt haben.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 11, 5, 'Ebenso ist nun auch in unserer Zeit ein Rest nach der göttlichen Gnadenauswahl vorhanden.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 11, 6, 'Ist er aber durch Gnade (ausgesondert), so ist er es nicht mehr aufgrund von Werken; sonst würde ja die Gnade keine Gnade mehr sein.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 11, 7, 'Wie steht es also? Was Israel erstrebt, das hat es (in seiner Gesamtheit) nicht erreicht; der auserwählte Teil aber hat es erreicht; die übrigen dagegen sind verstockt worden,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 11, 8, 'wie geschrieben steht: »Gott hat ihnen den Geist der Betäubung gegeben, Augen des Nichtsehens und Ohren des Nichthörens, bis auf den heutigen Tag.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 11, 9, 'Und David sagt: »Möge ihr Tisch ihnen zur Schlinge und zum Fangnetz werden, zum Fallstrick und zur Vergeltung!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 11, 10, 'Ihre Augen sollen verfinstert werden, damit sie nicht sehen, und den Rücken beuge ihnen für immer!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 11, 11, 'So frage ich nun: Sind sie etwa deshalb gestrauchelt, damit sie zu Fall kommen sollten? Keineswegs! Vielmehr ist infolge ihrer Verfehlung das Heil den Heiden zuteil geworden; das soll sie wiederum zur Nacheiferung reizen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 11, 12, 'Wenn aber schon ihre Verfehlung ein reicher Segen für die Menschheit und ihr Zurückbleiben ein reicher Segen für die Heiden geworden ist, um wieviel segensreicher wird (dann erst) ihre Vollzahl sein!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 11, 13, 'Euch Heiden(christen) aber sage ich: Gerade weil ich Heidenapostel bin, tue ich meinem Dienst um so größere Ehre an,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 11, 14, '(wenn ich bemüht bin) ob ich vielleicht meine Volksgenossen zur Nacheiferung zu reizen und (wenigstens) einige von ihnen zu retten vermag.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 11, 15, 'Denn wenn schon ihre Verwerfung zur Versöhnung der Welt geführt hat, was wird da ihre Annahme anderes sein als Leben aus den Toten?');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 11, 16, 'Wenn aber das Erstlingsbrot heilig ist, so ist es auch die (ganze übrige) Teigmasse; und wenn die Wurzel heilig ist, so sind es auch die Zweige.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 11, 17, 'Wenn nun aber einige von den Zweigen herausgebrochen worden sind und du, der du ein wilder Ölbaum(zweig) warst, unter sie eingepfropft worden bist und dadurch Anteil an der Wurzel, die dem Ölbaum die Fettigkeit schafft, erhalten hast,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 11, 18, 'so rühme dich deswegen nicht gegen die (anderen) Zweige! Tust du es dennoch (so bedenke wohl): nicht du trägst die Wurzel, sondern die Wurzel trägt dich.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 11, 19, 'Du wirst nun einwenden: »Es sind ja doch Zweige ausgebrochen worden, weil ich eingepfropft werden sollte.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 11, 20, 'Ganz recht! Infolge ihres Unglaubens sind sie ausgebrochen worden, und du stehst infolge deines Glaubens (an ihrer Stelle). Sei nicht hochmütig, sondern sei auf deiner Hut!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 11, 21, 'Denn wenn Gott die natürlichen Zweige nicht verschont hat, so wird er auch dich nicht verschonen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 11, 22, 'Darum beachte wohl die Güte, aber auch die Strenge Gottes: seine Strenge gegen die Gefallenen, dagegen die Güte Gottes gegen dich, vorausgesetzt daß du bei der (dir widerfahrenen) Güte verbleibst; denn sonst wirst auch du (aus dem Ölbaum) wieder herausgeschnitten werden,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 11, 23, 'während umgekehrt jene, wenn sie nicht im Unglauben verharren, wieder eingepfropft werden; Gott hat ja die Macht dazu, sie wieder einzupfropfen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 11, 24, 'Denn wenn du aus dem wilden Ölbaum, dem du von Haus aus angehörst, herausgeschnitten und gegen die Natur in den edlen Ölbaum eingepfropft worden bist: wieviel eher werden diese, die von Natur dahin gehören, ihrem ursprünglichen Ölbaum (wieder) eingepfropft werden!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 11, 25, 'Ich will euch nämlich, meine Brüder, über dieses Geheimnis nicht in Unkenntnis lassen, damit ihr nicht in vermeintlicher Klugheit auf eigene Gedanken verfallt: Verstockung ist über einen Teil der Israeliten gekommen bis zu der Zeit, da die Vollzahl der Heiden (in die Gemeinde Gottes) eingegangen sein wird;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 11, 26, 'und auf diese Weise wird Israel in seiner Gesamtheit gerettet werden, wie geschrieben steht: »Aus Zion wird der Retter kommen; er wird Jakob von allem gottlosen Wesen frei machen;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 11, 27, 'und darin wird sich ihnen der von mir herbeigeführte Bund zeigen, wenn ich ihre Sünden wegnehme.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 11, 28, 'So sind sie im Hinblick auf die Heilsbotschaft zwar Feinde (Gottes) um euretwillen, aber im Hinblick auf die Erwählung sind sie Geliebte (Gottes) um der Väter willen;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 11, 29, 'denn unwiderruflich sind die Gnadengaben und die Berufung Gottes.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 11, 30, 'Denn wie ihr einst ungehorsam gegen Gott gewesen seid, jetzt aber infolge des Ungehorsams dieser Erbarmen erlangt habt,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 11, 31, 'ebenso sind wiederum diese jetzt ungehorsam geworden, um durch das euch gewährte Erbarmen (dereinst) ebenfalls Barmherzigkeit zu erlangen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 11, 32, 'Denn Gott hat alle zusammen in Ungehorsam verschlossen, um allen Erbarmen widerfahren zu lassen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 11, 33, 'O welch eine Tiefe des Reichtums und der Weisheit und der Erkenntnis Gottes! Wie unbegreiflich sind seine Gerichte und unerforschlich seine Wege!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 11, 34, '»Denn wer hat den Sinn des Herrn erkannt, oder wer ist sein Ratgeber gewesen?«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 11, 35, 'Oder »wer hat ihm zuerst etwas gegeben, wofür ihm Vergeltung zuteil werden müßte?«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 11, 36, 'Denn von ihm und durch ihn und zu ihm sind alle Dinge: ihm gebührt die Ehre in Ewigkeit! Amen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 12, 1, 'So ermahne ich euch nun, liebe Brüder, durch (den Hinweis auf) die Barmherzigkeit Gottes: Bringt eure Leiber als ein lebendiges, heiliges und Gott wohlgefälliges Opfer dar: (das sei) euer vernünftiger Gottesdienst!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 12, 2, 'Gestaltet eure Lebensführung nicht nach der Weise dieser Weltzeit, sondern wandelt euch um durch die Erneuerung eures Sinnes, damit ihr ein sicheres Urteil darüber gewinnt, welches der Wille Gottes sei, nämlich das Gute und (Gott) Wohlgefällige und Vollkommene.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 12, 3, 'So fordere ich denn kraft der mir verliehenen Gnade einen jeden von euch auf, nicht höher von sich zu denken, als zu denken sich gebührt, sondern auf eine besonnene Selbstschätzung bedacht zu sein nach dem Maß des Glaubens, das Gott einem jeden zugeteilt hat.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 12, 4, 'Denn wie wir an einem Leibe viele Glieder haben, die Glieder aber nicht alle denselben Dienst verrichten,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 12, 5, 'so bilden auch wir trotz unserer Vielheit einen einzigen Leib in Christus, im Verhältnis zueinander aber sind wir Glieder,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 12, 6, 'doch so, daß wir Gnadengaben besitzen, die nach der uns verliehenen Gnade verschieden sind. Wer also die Gabe prophetischer Rede besitzt, bleibe in Übereinstimmung mit dem Maß des Glaubens;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 12, 7, 'wem die Gabe des Gemeindedienstes zuteil geworden ist, der betätige sie durch Dienstleistungen; wer Lehrgabe besitzt, verwende sie als Lehrer;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 12, 8, 'hat jemand die Gabe des Ermahnens, so betätige er sich im Ermahnen; wer Mildtätigkeit übt, tue es in Einfalt; wer zu den Vorstehern gehört, zeige rechten Eifer; wer Barmherzigkeit übt, tue es mit Freudigkeit!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 12, 9, 'Die Liebe sei ungeheuchelt! Verabscheut das Böse, haltet am Guten fest!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 12, 10, 'In der Bruderliebe zueinander seid voll Herzlichkeit; in der Ehrerbietung komme einer dem andern zuvor!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 12, 11, 'Seid unverdrossen, wo es Eifer gilt; seid feurig im Geist, dem Herrn zu dienen bereit!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 12, 12, 'Seid fröhlich in der Hoffnung, geduldig im Leiden, beharrlich im Gebet!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 12, 13, 'Für die Bedürfnisse der Heiligen beweist Anteilnahme; übt die Gastfreundschaft willig.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 12, 14, 'Segnet, die euch verfolgen, segnet sie und flucht ihnen nicht!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 12, 15, 'Freuet euch mit den Fröhlichen und weinet mit den Weinenden!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 12, 16, 'Seid einträchtig untereinander gesinnt; richtet eure Gedanken nicht auf hohe Dinge, sondern laßt euch zu den niedrigen herab; haltet euch nicht selbst für klug!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 12, 17, 'Vergeltet niemand Böses mit Bösem; seid auf das bedacht, was in den Augen aller Menschen löblich ist!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 12, 18, 'Ist’s möglich, soviel an euch liegt, so lebt mit allen Menschen in Frieden!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 12, 19, 'Rächet euch nicht selbst, Geliebte, sondern gebt Raum dem (göttlichen) Zorn; denn es steht geschrieben: »Mein ist die Rache, ich will vergelten, spricht der Herr.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 12, 20, 'Vielmehr: »Wenn deinen Feind hungert, so speise ihn; wenn ihn dürstet, so gib ihm zu trinken; denn wenn du das tust, wirst du feurige Kohlen auf sein Haupt sammeln.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 12, 21, 'Laß dich nicht vom Bösen überwinden, sondern überwinde das Böse durch das Gute!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 13, 1, 'Jedermann sei den obrigkeitlichen Gewalten untertan; denn es gibt keine Obrigkeit, ohne von Gott (bestellt zu sein), und wo immer eine besteht, ist sie von Gott verordnet.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 13, 2, 'Wer sich also der Obrigkeit widersetzt, der lehnt sich damit gegen Gottes Ordnung auf; und die sich auflehnen, werden sich selbst ein Strafurteil zuziehen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 13, 3, 'Denn die obrigkeitlichen Personen sind nicht für die guten Taten ein Schrecken, sondern für die bösen. Willst du also frei von Furcht vor der Obrigkeit sein, so tu das Gute: dann wirst du Anerkennung von ihr erhalten;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 13, 4, 'denn sie ist Gottes Dienerin dir zum Guten. Tust du aber das Böse, so fürchte dich; denn sie trägt das Schwert nicht umsonst: sie ist ja Gottes Dienerin, eine Vergelterin zur Vollziehung des (göttlichen) Zornes an dem Übeltäter.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 13, 5, 'Darum muß man ihr untertan sein, und zwar nicht nur aus Furcht vor dem (göttlichen) Zorn, sondern auch um des Gewissens willen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 13, 6, 'Deshalb entrichtet ihr ja auch Steuern; denn sie sind Gottes Dienstleute, die für eben diesen Zweck unablässig tätig sind.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 13, 7, 'Lasset allen zukommen, was ihr ihnen schuldig seid: die Steuer, wem die Steuer gebührt, den Zoll, wem der Zoll zukommt, die Furcht, wem die Furcht, und die Ehre, wem die Ehre gebührt.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 13, 8, 'Bleibt niemand etwas schuldig, außer daß ihr einander liebt; denn wer den anderen liebt, hat damit das Gesetz erfüllt.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 13, 9, 'Denn das Gebot: »Du sollst nicht ehebrechen, nicht töten, nicht stehlen, laß dich nicht gelüsten!« und jedes andere derartige Gebot ist in diesem Wort einheitlich zusammengefaßt: »Du sollst deinen Nächsten lieben wie dich selbst!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 13, 10, 'Die Liebe tut dem Nächsten nichts Böses; demnach ist die Liebe die Erfüllung des Gesetzes.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 13, 11, 'Und zwar (verhaltet euch auf diese Weise) in richtiger Erkenntnis der (gegenwärtigen) Zeit, daß nämlich die Stunde nunmehr für uns da ist, aus dem Schlaf zu erwachen; denn jetzt ist die Rettung uns näher als damals, als wir zum Glauben gekommen sind:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 13, 12, 'die Nacht ist vorgerückt und der Tag nahegekommen. So lasset uns denn die Werke der Finsternis abtun, dagegen die Waffen des Lichts anlegen!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 13, 13, 'Lasset uns sittsam wandeln, wie es sich am Tage geziemt: nicht in Schwelgereien und Trinkgelagen, nicht in Unzucht und Ausschweifungen, nicht in Streit und Eifersucht;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 13, 14, 'nein, ziehet den Herrn Jesus Christus an, und seid dem Fleisch nicht so zu Diensten, daß böse Begierden dadurch erregt werden!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 14, 1, 'Auf den im Glauben Schwachen nehmet (liebevolle) Rücksicht, ohne über Gewissensbedenken (mit ihm) zu streiten.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 14, 2, 'Der eine ist überzeugt, alles essen zu dürfen, während der Schwache nur Pflanzenkost genießt.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 14, 3, 'Wer (alles) ißt, verachte den nicht, der nicht (alles) ißt; und wer nicht (alles) ißt, soll über den, der (alles) ißt, nicht zu Gericht sitzen, denn Gott hat ihn (als Angehörigen) angenommen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 14, 4, 'Wie kommst du dazu, dich zum Richter über den Knecht eines andern zu machen? Er steht oder fällt seinem eigenen Herrn; und zwar wird er stehen bleiben, denn sein Herr ist stark genug, ihn aufrecht zu halten.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 14, 5, 'Mancher macht einen Unterschied zwischen den Tagen, während einem andern alle Tage als gleich gelten: ein jeder möge nach seiner eigenen Denkweise zu einer festen Überzeugung kommen!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 14, 6, 'Wer etwas auf einzelne Tage gibt, der tut es für den Herrn; und wer (alles) ißt, tut es für den Herrn, denn er sagt Gott Dank dabei; und wer nicht (alles) ißt, tut es auch für den Herrn und sagt Gott Dank dabei.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 14, 7, 'Keiner von uns lebt ja für sich selbst, und keiner stirbt für sich selbst;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 14, 8, 'denn leben wir, so leben wir dem Herrn, und sterben wir, so sterben wir dem Herrn; darum, mögen wir leben oder sterben, so gehören wir dem Herrn als Eigentum an.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 14, 9, 'Dazu ist ja Christus gestorben und wieder lebendig geworden, um sowohl über Tote als auch über Lebende Herr zu sein.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 14, 10, 'Du aber: wie kannst du dich zum Richter über deinen Bruder machen? Oder auch du: wie darfst du deinen Bruder verachten? Wir werden ja alle (einmal) vor den Richterstuhl Gottes treten müssen;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 14, 11, 'denn es steht geschrieben: »So wahr ich lebe«, spricht der Herr, »mir (zu Ehren) wird jedes Knie sich beugen, und jede Zunge wird Gott bekennen.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 14, 12, 'Demnach wird ein jeder von uns über sich selbst Rechenschaft vor Gott abzulegen haben.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 14, 13, 'Darum wollen wir nicht mehr einer den andern richten, sondern haltet vielmehr das für das Richtige, dem Bruder keinen Anstoß und kein Ärgernis zu bereiten!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 14, 14, 'Ich weiß und bin dessen im Herrn Jesus gewiß, daß nichts an und für sich unrein ist; jedoch wenn jemand etwas für unrein hält, so ist es für ihn (tatsächlich) unrein.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 14, 15, 'Denn wenn dein Bruder (durch dich) um einer Speise willen in Betrübnis versetzt wird, so wandelst du nicht mehr nach (dem Gebot) der Liebe. Bringe durch dein Essen nicht den ins Verderben, für den Christus gestorben ist!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 14, 16, 'Verschuldet es also nicht, daß euer Heilsgut der Verlästerung anheimfällt!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 14, 17, 'Das Reich Gottes besteht ja nicht in Essen und Trinken, sondern in Gerechtigkeit und Frieden und Freude im heiligen Geist;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 14, 18, 'denn wer darin Christus dient, der ist Gott wohlgefällig und vor den Menschen bewährt.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 14, 19, 'Darum wollen wir auf das bedacht sein, was zum Frieden und zu gegenseitiger Erbauung dient!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 14, 20, 'Zerstöre nicht um einer Speise willen das Werk Gottes! Zwar ist alles rein, aber zum Unheil ist es für jemand, der es mit inneren Bedenken genießt;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 14, 21, 'da ist es löblich, kein Fleisch zu essen und keinen Wein zu trinken, überhaupt nichts (zu tun), woran dein Bruder Anstoß nimmt.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 14, 22, 'Du hast Glaubenszuversicht: halte sie für dich selbst vor dem Angesicht Gottes fest! Wohl dem, der nicht mit sich selbst ins Gericht zu gehen braucht bei dem, was er für recht hält!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 14, 23, 'Wer dagegen ißt, obwohl er Bedenken hegt, der hat sich dadurch die Verurteilung zugezogen, weil (er) nicht aus Glauben (gehandelt hat); alles aber, was nicht aus Glauben geschieht, ist Sünde.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 15, 1, 'Da haben wir Starken die Pflicht, die Schwächen derer, die nicht so stark sind (wie wir), zu tragen und nicht wohlgefällig an uns selbst zu denken:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 15, 2, 'nein, jeder von uns lebe dem Nächsten zu Gefallen, ihm zum Besten, zu seiner Erbauung!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 15, 3, 'Denn auch Christus hat nicht sich selbst zu Gefallen gelebt, sondern wie geschrieben steht: »Die Schmähungen derer, die dich schmähen, sind auf mich gefallen.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 15, 4, 'So ist ja alles, was vor Zeiten geschrieben worden ist, für uns zur Belehrung geschrieben, damit wir durch standhaftes Ausharren und durch den Trost, den die (heiligen) Schriften gewähren, an der Hoffnung festhalten.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 15, 5, 'Der Gott aber, von dem standhaftes Ausharren und Trost kommen, möge euch dazu verhelfen, einen einträchtigen Sinn untereinander nach der Weise Christi Jesu zu besitzen,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 15, 6, 'damit ihr einmütig mit einem Munde den Gott und Vater unsers Herrn Jesus Christus preisen könnt.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 15, 7, 'Darum nehmet euch gegenseitig (in Liebe) an, wie auch Christus euch zu Gottes Verherrlichung (in Liebe) angenommen hat!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 15, 8, 'Ich meine nämlich: Christus ist ein Diener der Beschneidung geworden zum Erweis der Wahrhaftigkeit Gottes, um die den Vätern gegebenen Verheißungen zu verwirklichen,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 15, 9, 'die Heiden andrerseits sollen Gott um seiner Barmherzigkeit willen preisen, wie geschrieben steht: »Darum will ich dich preisen unter den Heiden und deinem Namen lobsingen.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 15, 10, 'Und an einer anderen Stelle heißt es: »Freuet euch, ihr Heiden, im Verein mit seinem Volke!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 15, 11, 'und an einer anderen Stelle: »Lobet, ihr Heiden alle, den Herrn, und alle Völker sollen ihn preisen!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 15, 12, 'Weiter sagt Jesaja: »Erscheinen wird der Wurzelschoß Isais, und zwar er, der da aufsteht, um über die Heiden zu herrschen: auf ihn werden die Heiden ihre Hoffnung setzen.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 15, 13, 'Der Gott aber, der unsere Hoffnung ist, erfülle euch mit aller Freude und mit Frieden auf dem Grunde des Glaubens, damit ihr immer reicher an Hoffnung werdet durch die Kraft des heiligen Geistes!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 15, 14, 'Ich habe aber auch persönlich von euch, liebe Brüder, die feste Überzeugung, daß ihr eurerseits mit dem besten Willen erfüllt und, mit aller Erkenntnis voll ausgerüstet, wohlbefähigt seid, euch auch untereinander zurechtzuweisen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 15, 15, 'Trotzdem habe ich euch, wenigstens stellenweise, etwas rückhaltlos geschrieben, um euch (an dies und das) zu erinnern, und zwar aufgrund des mir von Gott verliehenen Gnadenamtes.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 15, 16, 'Ich soll ja ein Diener Christi Jesu für die Heiden sein und als solcher den Priesterdienst an der Heilsbotschaft Gottes verrichten, damit die Heiden zu einer gottwohlgefälligen, durch den heiligen Geist geheiligten Opfergabe werden.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 15, 17, 'In Christus Jesus darf ich mich daher meines für die Sache Gottes geleisteten Dienstes rühmen;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 15, 18, 'denn ich werde mich nicht erkühnen, von irgendwelchen Erfolgen zu reden, die nicht Christus durch mich gewirkt hat, um Heiden(völker) zum Gehorsam zu bringen durch Wort und Tat,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 15, 19, 'durch die Kraft von Zeichen und Wundern, durch die Kraft des heiligen Geistes. Auf diese Weise habe ich nämlich von Jerusalem aus und in weitem Umkreise bis nach Illyrikum hin die (Verkündigung der) Heilsbotschaft von Christus voll ausgerichtet.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 15, 20, 'Dabei habe ich es mir aber zur Ehrensache gemacht, die Heilsbotschaft nicht da zu verkündigen, wo der Name Christi bereits bekannt war; denn ich habe nicht auf fremdem Grund und Boden (weiter) bauen wollen,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 15, 21, 'sondern bin dem Schriftwort gefolgt: »Die sollen (ihn) zu sehen bekommen, denen noch nichts über ihn verkündigt worden ist, und die noch keine Kunde (von ihm) haben, die sollen (ihn) kennenlernen.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 15, 22, 'Das ist denn auch der Grund, weshalb ich so oft verhindert worden bin, zu euch zu kommen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 15, 23, 'Da ich jetzt aber in den Gegenden hier kein Arbeitsfeld mehr habe, wohl aber seit vielen Jahren mich danach sehne, zu euch zu kommen,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 15, 24, 'so werde ich, sobald ich die Reise nach Spanien unternehme (meinen Plan ausführen). Ich hoffe nämlich, euch auf der Durchreise zu sehen und von euch das Geleit zur Weiterreise dorthin zu erhalten, nachdem ich mich zunächst ein wenig bei euch erquickt habe.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 15, 25, 'Augenblicklich aber befinde ich mich auf der Reise nach Jerusalem anläßlich eines Liebesdienstes für die Heiligen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 15, 26, 'Mazedonien und Achaja haben nämlich beschlossen, eine Geldsammlung für die Armen unter den Heiligen in Jerusalem zu veranstalten.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 15, 27, 'Ja, sie haben es beschlossen und sind es ihnen ja auch schuldig; denn wenn die Heiden(christen) Anteil an den geistlichen Gütern jener erhalten haben, so sind sie dafür auch verpflichtet, ihnen mit ihren irdischen Gütern auszuhelfen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 15, 28, 'Wenn ich nun dieses Geschäft erledigt und ihnen den Ertrag dieser Sammlung sicher übermittelt habe, dann werde ich über euer Rom nach Spanien reisen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 15, 29, 'Ich weiß aber, daß, wenn ich zu euch komme, ich euch eine Fülle des Segens Christi mitbringen werde.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 15, 30, 'Ich bitte euch aber dringend, liebe Brüder, bei unserm Herrn Jesus Christus und bei der Liebe, die der (heilige) Geist wirkt: steht mir mit den Gebeten, die ihr für mich an Gott richtet, im Kampfe kräftig bei,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 15, 31, 'damit ich von den Ungehorsamen in Judäa errettet werde und meine Dienstleistung für Jerusalem bei den Heiligen dort eine gute Aufnahme finden möge!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 15, 32, 'Dann kann ich, so Gott will, in freudiger Stimmung zu euch kommen und mich im Zusammensein mit euch erquicken.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 15, 33, 'Der Gott des Friedens aber sei mit euch allen! Amen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 16, 1, 'Ich empfehle euch aber unsere Schwester Phöbe, die im Dienst der Gemeinde zu Kenchreä steht:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 16, 2, 'nehmt sie im Herrn auf, wie es sich für Heilige geziemt, und steht ihr in allen Fällen, wo sie euer bedarf, hilfreich zur Seite; denn sie hat gleichfalls vielen Beistand geleistet, auch mir persönlich.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 16, 3, 'Grüßt Priska und Aquila, meine Mitarbeiter in Christus Jesus,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 16, 4, 'die für mein Leben ihren eigenen Hals eingesetzt haben, wofür nicht ich allein ihnen zu Dank verpflichtet bin, sondern auch sämtliche heidenchristlichen Gemeinden;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 16, 5, 'grüßt auch die Gemeinde in ihrem Hause. Grüßt meinen geliebten Epänetus, der die Erstlingsgabe Asiens für Christus ist.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 16, 6, 'Grüßt Maria, die sich hingebend für euch gemüht hat.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 16, 7, 'Grüßt Andronikus und Junias, meine Volksgenossen und (einst) meine Mitgefangenen, die bei den Aposteln in hohem Ansehen stehen und auch schon vor mir in Christus gewesen sind.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 16, 8, 'Grüßt meinen im Herrn geliebten Ampliatus.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 16, 9, 'Grüßt Urbanus, unsern Mitarbeiter in Christus, und meinen geliebten Stachys.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 16, 10, 'Grüßt Apelles, der ein bewährter Jünger Christi ist. Grüßt die Brüder unter den Leuten des Aristobulus.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 16, 11, 'Grüßt meinen Volksgenossen Herodion. Grüßt diejenigen unter den Leuten des Narcissus, die im Herrn sind.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 16, 12, 'Grüßt Tryphäna und Tryphosa, die eifrig im Herrn arbeiten. Grüßt die geliebte Persis, die eine treue Arbeiterin im Herrn gewesen ist.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 16, 13, 'Grüßt den im Herrn auserwählten Rufus und seine Mutter, die auch mir eine Mutter gewesen ist.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 16, 14, 'Grüßt Asynkritus, Phlegon, Hermes, Patrobas, Hermas und die (anderen) Brüder bei ihnen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 16, 15, 'Grüßt Philologus und Julias, Nereus nebst seiner Schwester, auch Olympas und alle Heiligen bei ihnen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 16, 16, 'Grüßt einander mit dem heiligen Kuß. Alle Gemeinden Christi lassen euch grüßen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 16, 17, 'Ich ermahne euch aber, liebe Brüder, auf der Hut vor denen zu sein, welche die Spaltungen und Ärgernisse erregen im Gegensatz zu der Lehre, in der ihr unterwiesen worden seid: geht ihnen aus dem Wege;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 16, 18, 'denn solche Menschen dienen nicht unserm Herrn Christus, sondern ihrem Bauche und betören durch ihre schön klingenden Reden und glatten Worte die Herzen der Arglosen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 16, 19, 'Die Kunde von eurem (Glaubens-) Gehorsam ist ja zu allen gedrungen. Deshalb habe ich meine Freude an euch, wünsche aber, daß ihr weise seid, wo es das Gute gilt, dagegen einfältig gegenüber dem Bösen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 16, 20, 'Der Gott des Friedens aber wird den Satan unter euren Füßen zertreten, und zwar in Bälde. Die Gnade unsers Herrn Jesus sei mit euch!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 16, 21, 'Es grüßen euch mein Mitarbeiter Timotheus und meine Volksgenossen Lucius, Jason und Sosipater.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 16, 22, 'Ich, Tertius, der Schreiber dieses Briefes, grüße euch im Herrn.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 16, 23, 'Es grüßt euch Gaius, dessen Gastfreundschaft ich und die ganze Gemeinde genießen. Es grüßen euch der Stadtkämmerer Erastus und der Bruder Quartus.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 16, 24, 'Die Gnade unsers Herrn Jesus Christus sei mit euch allen! Amen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 16, 25, 'Ihm aber, der die Kraft hat, euch (im Glauben) fest zu machen nach meiner Heilsverkündigung und der Predigt von Jesus Christus nach der Offenbarung des Geheimnisses, das ewige Zeiten hindurch verschwiegen geblieben,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 16, 26, 'jetzt aber bekanntgegeben und auch durch prophetische Schriften nach dem Auftrage des ewigen Gottes bei allen Heidenvölkern verkündigt worden ist, um Glaubensgehorsam (bei ihnen) zu wirken:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 16, 27, 'ihm, dem allein weisen Gott, sei durch Jesus Christus die Herrlichkeit in alle Ewigkeit! Amen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 1, 1, 'Ich, Paulus, der ich zum Apostel Jesu Christi durch den Willen Gottes berufen bin, und der Bruder Sosthenes');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 1, 2, 'senden unsern Gruß der Gemeinde Gottes in Korinth, den in Christus Jesus Geheiligten, den (von Gott) berufenen Heiligen, samt allen denen, welche den Namen unsers Herrn Jesus Christus anrufen an jeglichem Ort, bei ihnen wie bei uns.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 1, 3, 'Gnade sei mit euch und Friede von Gott, unserm Vater, und dem Herrn Jesus Christus!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 1, 4, 'Ich danke meinem Gott allezeit euretwegen für die Gnade Gottes, die euch in Christus Jesus widerfahren ist.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 1, 5, 'Ihr seid ja in ihm an allem reich geworden, an aller Redegabe und aller Erkenntnis,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 1, 6, 'wie denn das Zeugnis von Christus in euch fest gegründet worden ist.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 1, 7, 'Ihr steht infolgedessen an keiner Gnadengabe (hinter anderen Gemeinden) zurück, während ihr auf die Offenbarung unsers Herrn Jesus Christus wartet,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 1, 8, 'der euch auch Festigkeit verleihen wird bis ans Ende, so daß ihr am Tage unsers Herrn Jesus Christus frei von Tadel dastehen könnt.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 1, 9, 'Treu ist Gott, durch den ihr in die Gemeinschaft mit seinem Sohne Jesus Christus, unserm Herrn, berufen worden seid.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 1, 10, 'Ich ermahne euch aber, liebe Brüder, unter Berufung auf den Namen unsers Herrn Jesus Christus: Führt allesamt einerlei Rede und laßt keine Spaltungen unter euch herrschen, sondern steht in gleicher Gesinnung und in derselben Überzeugung fest geschlossen da!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 1, 11, 'Es ist mir nämlich über euch, meine Brüder, von den Leuten der Chloe berichtet worden, daß Streitigkeiten unter euch bestehen;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 1, 12, 'ich meine damit nämlich den Übelstand, daß jeder von euch (als seine Losung) ausspricht: »Ich halte zu Paulus«, »Ich dagegen zu Apollos«, »Ich aber zu Kephas«, »Ich aber zu Christus«.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 1, 13, 'Ist Christus in Stücke zerteilt worden? Ist etwa Paulus für euch gekreuzigt worden? Oder seid ihr auf den Namen des Paulus getauft worden?');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 1, 14, 'Ich sage (Gott) Dank dafür, daß ich niemand von euch außer Krispus und Gaius getauft habe;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 1, 15, 'so kann niemand behaupten, ihr seiet auf meinen Namen getauft worden.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 1, 16, 'Doch ja, ich habe (außerdem) auch noch die Hausgenossen des Stephanas getauft; sonst aber wüßte ich nicht, daß ich noch irgendeinen andern getauft hätte.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 1, 17, 'Christus hat mich ja nicht ausgesandt, um zu taufen, sondern um die Heilsbotschaft zu verkündigen, und zwar nicht mit hoher Redeweisheit, damit das Kreuz Christi nicht entleert werde.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 1, 18, 'Denn das Wort vom Kreuz ist für die, welche verlorengehen, eine Torheit, für die aber, welche gerettet werden, für uns, ist es eine Gotteskraft.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 1, 19, 'Denn es steht geschrieben: »Ich will die Weisheit der Weisen zuschanden machen und den Verstand der Verständigen als nichtig abtun.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 1, 20, 'Wo ist denn ein Weiser? Wo ein Gelehrter? Wo ein Forscher dieser Weltzeit? Hat Gott nicht die Weisheit der Welt als Torheit hingestellt?');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 1, 21, 'Weil nämlich die Welt da, wo Gottes Weisheit tatsächlich vorlag, Gott vermittelst ihrer Weisheit nicht erkannte, hat es Gott gefallen, durch die Torheit der Predigt die zu retten, welche Glauben haben.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 1, 22, 'Denn während einerseits die Juden Wunderzeichen fordern, andrerseits die Griechen Weltweisheit verlangen,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 1, 23, 'verkünden wir dagegen Christus als den Gekreuzigten, der für die Juden ein Ärgernis und für die Heiden eine Torheit ist;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 1, 24, 'denen aber, die berufen sind, sowohl den Juden als auch den Griechen, (verkünden wir) Christus als Gotteskraft und Gottesweisheit.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 1, 25, 'Denn die Torheit Gottes ist weiser als die Menschen (sind), und die Schwachheit Gottes ist der Stärke der Menschen überlegen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 1, 26, 'Seht euch doch einmal eure Berufung an, liebe Brüder! Da sind nicht viele Weise nach dem Fleisch unter euch, nicht viele einflußreiche Personen, nicht viele Hochgeborene;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 1, 27, 'nein, was der Welt als töricht gilt, das hat Gott erwählt, um die Weisen zu beschämen; und was der Welt als schwach gilt, das hat Gott erwählt, um das Starke zu beschämen;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 1, 28, 'und was der Welt als niedrig und verächtlich gilt, das hat Gott erwählt, ja das, was der Welt nichts gilt, um das, was ihr etwas gilt, zunichte zu machen:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 1, 29, 'es soll sich eben kein Fleisch vor Gott rühmen können.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 1, 30, 'Ihm habt ihr es also zu verdanken, daß ihr in Christus Jesus seid, der uns von Gott her zur Weisheit gemacht worden ist wie auch zur Gerechtigkeit und Heiligung und zur Erlösung,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 1, 31, 'damit das Schriftwort seine Geltung behalte: »Wer sich rühmen will, der rühme sich des Herrn!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 2, 1, 'So bin denn auch ich, als ich zu euch kam, liebe Brüder, nicht in der Absicht gekommen, euch mit überwältigender Redekunst oder Weisheit das Zeugnis Gottes zu verkündigen;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 2, 2, 'nein, ich hatte mir vorgenommen, kein anderes Wissen bei euch zu zeigen als das von Jesus Christus, und zwar dem Gekreuzigten.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 2, 3, 'Dabei trat ich mit (dem Gefühl der) Schwachheit und mit Furcht und großer Ängstlichkeit bei euch auf,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 2, 4, 'und meine Rede und meine Predigt erfolgte nicht mit eindrucksvollen Weisheitsworten, sondern mit dem Ausweis von Geist und Kraft;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 2, 5, 'denn euer Glaube sollte nicht auf Menschenweisheit, sondern auf Gotteskraft beruhen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 2, 6, 'Was wir aber vortragen, ist dennoch Weisheit – bei den Vollkommenen, jedoch nicht die Weisheit dieser Weltzeit, auch nicht die der Machthaber dieser Weltzeit, die dem Untergang verfallen:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 2, 7, 'nein, wir tragen Gottes geheimnisvolle, verborgene Weisheit vor, die Gott vor allen Weltzeiten zu unserer Verherrlichung vorherbestimmt hat.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 2, 8, 'Diese (Weisheit) hat keiner von den Machthabern dieser Weltzeit erkannt; denn hätten sie sie erkannt, so hätten sie den Herrn der Herrlichkeit nicht ans Kreuz geschlagen;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 2, 9, 'vielmehr (predigen wir so), wie geschrieben steht: »Was kein Auge gesehen und kein Ohr gehört hat und wovon keines Menschen Herz eine Ahnung gehabt hat, nämlich das, was Gott denen bereitet hat, die ihn lieben.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 2, 10, 'Uns aber hat Gott dies durch den Geist geoffenbart; denn der Geist erforscht alles, selbst die Tiefen Gottes.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 2, 11, 'Denn wer von den Menschen kennt das innere Wesen eines Menschen? Doch nur der Geist, der in dem betreffenden Menschen wohnt. Ebenso hat auch niemand das innere Wesen Gottes erkannt als nur der Geist Gottes.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 2, 12, 'Wir aber haben nicht den Geist der Welt empfangen, sondern den Geist, der aus Gott ist, um das zu erkennen, was uns von Gott aus Gnaden geschenkt worden ist.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 2, 13, 'Und davon reden wir auch, (aber) nicht mit Worten, wie menschliche Weisheit sie lehrt, sondern mit solchen, wie der Geist sie lehrt, indem wir geistgewirkten Inhalt mit geistgewirkter Sprache verbinden.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 2, 14, 'Der seelische Mensch aber nimmt nichts an, was vom Geiste Gottes kommt, denn es gilt ihm als Torheit, und er ist nicht imstande, es zu verstehen, weil es geistlich beurteilt werden muß.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 2, 15, 'Der Geistesmensch dagegen beurteilt alles zutreffend, während er selbst von niemand zutreffend beurteilt wird.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 2, 16, '»Denn wer hat den Sinn des Herrn erkannt, daß er ihn unterweisen könnte?« Wir aber haben den Sinn Christi.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 3, 1, 'So habe denn auch ich, liebe Brüder, (damals) zu euch nicht als zu Geistesmenschen reden können, sondern nur als zu fleischlich gesinnten Menschen, nur als zu unmündigen Kindern in Christus.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 3, 2, 'Milch habe ich euch zu trinken gegeben, nicht feste Speise; denn die konntet ihr noch nicht vertragen. Ja, ihr könnt sie auch jetzt noch nicht vertragen;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 3, 3, 'ihr seid ja immer noch fleischlich gesinnt. Denn solange noch Eifersucht und Streit unter euch herrschen, seid ihr da nicht fleischlich gerichtet und wandelt wie Menschen (gewöhnlichen Schlages)?');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 3, 4, 'Wenn nämlich der eine erklärt: »Ich halte zu Paulus«, der andere: »Ich zu Apollos«, seid ihr da nicht Menschen (gewöhnlichen Schlages)?');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 3, 5, 'Was ist denn Apollos, und was ist Paulus? Diener sind sie, durch die ihr zum Glauben gekommen seid; und zwar dient jeder (von uns beiden) so, wie der Herr es ihm verliehen hat:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 3, 6, 'ich habe gepflanzt, Apollos hat begossen, Gott aber hat das Wachstum gegeben.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 3, 7, 'Somit ist weder der Pflanzende noch der Begießende (für sich) etwas, sondern nur Gott, der das Wachstum verleiht.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 3, 8, 'Der Pflanzende hingegen und der Begießende sind einer wie der andere, doch wird jeder seinen besonderen Lohn empfangen nach seiner besonderen Arbeit.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 3, 9, 'Denn Gottes Mitarbeiter sind wir; Gottes Ackerfeld, Gottes Bau seid ihr.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 3, 10, 'Nach der mir von Gott verliehenen Gnade habe ich als ein kundiger Baumeister den Grund (bei euch) gelegt; ein anderer baut darauf weiter; jeder aber möge zusehen, wie er darauf weiterbaut!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 3, 11, 'Denn einen anderen Grund kann niemand legen als den, der gelegt ist, und der ist Jesus Christus.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 3, 12, 'Ob aber jemand auf diesen Grund weiterbaut mit Gold, Silber und kostbaren Steinen, (oder aber) mit Holz, Heu und Stroh –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 3, 13, 'eines jeden Arbeit wird (dereinst) offenbar werden; denn der Gerichtstag wird es ausweisen, weil er sich in Feuer offenbart; und wie die Arbeit eines jeden beschaffen ist, wird eben das Feuer erproben.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 3, 14, 'Wenn das Werk jemandes, das er darauf weitergebaut hat, (in dem Feuer) standhält, so wird er Lohn empfangen;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 3, 15, 'wenn aber das Werk jemandes verbrennt, so wird er den Schaden zu tragen haben: er selbst zwar wird gerettet werden, aber nur so, wie durchs Feuer hindurch.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 3, 16, 'Wißt ihr nicht, daß ihr (als Gemeinde) ein Tempel Gottes seid und daß der Geist Gottes in euch wohnt?');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 3, 17, 'Wenn jemand den Tempel Gottes verderbt, den wird Gott verderben; denn der Tempel Gottes ist heilig, und der seid ihr!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 3, 18, 'Niemand betrüge sich selbst! Wenn jemand unter euch in (den Dingen) dieser Weltzeit weise zu sein vermeint, so muß er erst ein Tor werden, um dann wirklich zur Weisheit zu gelangen;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 3, 19, 'denn die Weisheit dieser Welt ist in Gottes Augen Torheit. Es steht ja doch geschrieben: »Er fängt die Weisen in ihrer Schlauheit«;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 3, 20, 'und an einer andern Stelle: »Der Herr kennt die Gedanken der Weisen, daß sie nichtig sind.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 3, 21, 'Daher mache niemand viel Rühmens von Menschen! Alles gehört ja euch zu eigen:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 3, 22, 'Paulus ebensowohl wie Apollos und Kephas, die ganze Welt, das Leben ebensowohl wie der Tod, das Gegenwärtige wie das Zukünftige: alles gehört euch;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 3, 23, 'ihr aber gehört Christus an, und Christus gehört zu Gott.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 4, 1, 'Dafür halte uns jedermann, nämlich für Diener Christi und für Verwalter der Geheimnisse Gottes.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 4, 2, 'Bei dieser Sachlage verlangt man allerdings von den Verwaltern, daß ein solcher treu erfunden werde.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 4, 3, 'Doch was mich betrifft, so ist es mir etwas ganz Geringes, ob ich von euch oder von (sonst) einem menschlichen Gerichtstage ein Urteil empfange; ja, ich gebe nicht einmal selbst ein Urteil über mich ab.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 4, 4, 'Denn ich bin mir wohl keiner Schuld bewußt, aber dadurch bin ich noch nicht gerechtfertigt; nein, der Herr ist’s, der das Urteil über mich abgibt.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 4, 5, 'Daher urteilet über nichts vor der Zeit, bis der Herr kommt, der auch das im Dunkel Verborgene ans Licht bringen und die Gedanken der Herzen offenbar machen wird; und dann wird einem jeden das ihm gebührende Lob von Gott her zuteil werden.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 4, 6, 'Ich habe das Gesagte aber, liebe Brüder, auf mich und Apollos bezogen (und zwar) mit Rücksicht auf euch, damit ihr an uns (beiden) das Wort verstehen lernt: »Nicht hinausgehen über das, was geschrieben steht!«, damit sich niemand (von euch) für den einen (Lehrer) gegen den andern aufblähen möge.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 4, 7, 'Denn wer ist es, der dir ein Vorrecht gibt? Was besitzest du aber, das du nicht empfangen hättest? Wenn du es aber empfangen hast, was rühmst du dich, als ob du es nicht empfangen hättest?');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 4, 8, 'Ihr (freilich) seid bereits gesättigt, seid bereits im Besitz des Reichtums, habt es ohne unser Zutun zu königlicher Herrschaft (im Gottesreich) gebracht! Wollte Gott, ihr hättet es wirklich schon zu königlicher Herrschaft gebracht, damit auch wir mit euch zum Herrschen kämen!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 4, 9, 'Denn ich bin der Ansicht, Gott habe uns Aposteln den letzten Platz zugewiesen wie zum Tode verurteilten (Verbrechern); wir sind ja der (ganzen) Welt, Engeln sowohl wie Menschen, ein Schaustück geworden!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 4, 10, 'Wir stehen als Toren da um Christi willen, ihr aber seid kluge Leute in Christus; wir sind schwach, ihr aber stark; ihr steht in Ehren und wir in Verachtung.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 4, 11, 'Bis zur jetzigen Stunde leiden wir Hunger und Durst, haben keine Kleidung und müssen uns mit Fäusten schlagen lassen, führen ein unstetes Leben');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 4, 12, 'und mühen uns ab, um mit eigenen Händen das tägliche Brot zu verdienen. Schmäht man uns, so segnen wir; verfolgt man uns, so halten wir geduldig still;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 4, 13, 'beschimpft man uns, so geben wir gute Worte: wie der Kehricht der Welt, wie der allgemeine Auswurf sind wir bis heute geworden.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 4, 14, 'Ich schreibe dies nicht, um euch zu beschämen, sondern um euch als meine geliebten Kinder zu ermahnen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 4, 15, 'Denn wenn ihr auch viele tausend Lehrmeister in Christus hättet, so habt ihr doch nicht viele Väter; denn in Christus Jesus bin ich durch die (Verkündigung der) Heilsbotschaft euer (geistlicher) Vater geworden.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 4, 16, 'Daher rufe ich euch mahnend zu: »Nehmt mich zum Vorbild!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 4, 17, 'Eben deswegen habe ich auch Timotheus zu euch gesandt, mein im Herrn geliebtes und treues Kind; er wird euch an meine Wege in Christus Jesus erinnern, wie ich sie überall in jeder Gemeinde lehre.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 4, 18, 'Freilich haben sich einige (bei euch) in der Annahme, daß ich nicht zu euch kommen würde, in die Brust geworfen;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 4, 19, 'ich werde aber, wenn es des Herrn Wille ist, bald zu euch kommen und dann nicht die Worte derer prüfen, die sich so in die Brust geworfen haben, sondern ihre Kraft;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 4, 20, 'denn nicht auf Worten beruht das Reich Gottes, sondern auf Kraft.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 4, 21, 'Was wünscht ihr nun? Soll ich mit dem Stock zu euch kommen oder mit Liebe und dem Geiste der Sanftmut?');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 5, 1, 'Allgemein hört man von Unzucht bei euch, und noch dazu von einer solchen Unzucht, wie sie selbst bei den Heiden unerhört ist, daß nämlich einer die Frau seines Vaters zum Weibe genommen hat!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 5, 2, 'Und da wollt ihr euch noch in die Brust werfen und habt nicht vielmehr Leid getragen, damit der Schuldige aus eurer Mitte entfernt werde?');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 5, 3, 'Nun – ich, der ich leiblich zwar abwesend, aber mit meinem Geiste bei euch anwesend bin, habe über diesen Menschen, der sich so schwer vergangen hat, bereits Gericht gehalten, als ob ich persönlich bei euch wäre.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 5, 4, 'Wir wollen uns nämlich im Namen des Herrn Jesus versammeln, ihr und mein Geist im Verein mit der Kraft unsers Herrn Jesus,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 5, 5, 'und wollen den betreffenden Menschen dem Satan zur Vernichtung des Fleisches übergeben, damit der Geist am Tage des Herrn Jesus gerettet werde.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 5, 6, 'Euer Ruhm ist nicht schön! Wißt ihr nicht, daß schon ein wenig Sauerteig den ganzen Teig durchsäuert?');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 5, 7, 'Schafft den alten Sauerteig weg, damit ihr (durchweg) ein neuer Teig seid; ihr seid ja doch (als Christen) frei von allem Sauerteig; denn es ist ja auch unser Passahlamm geschlachtet worden: Christus.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 5, 8, 'Darum laßt uns Festfeier halten nicht im alten Sauerteig, auch nicht im Sauerteig der Schlechtigkeit und Bosheit, sondern im Süßteig der Lauterkeit und Wahrheit.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 5, 9, 'Ich habe euch in meinem (vorigen) Briefe geschrieben, ihr möchtet keinen Verkehr mit unzüchtigen Leuten haben;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 5, 10, '(das heißt) nicht überhaupt mit den Unzüchtigen dieser Welt oder mit den Betrügern und Räubern oder Götzendienern; sonst müßtet ihr ja aus der Welt auswandern.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 5, 11, 'Jetzt aber schreibe ich euch (unmißverständlich) so: Ihr dürft keinen Verkehr mit jemand haben, der den (christlichen) Brudernamen führt und dabei ein unzüchtiger Mensch oder ein Betrüger, ein Götzendiener, ein Verleumder, ein Trunkenbold oder ein Räuber ist; mit einem solchen Menschen dürft ihr nicht einmal Tischgemeinschaft haben.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 5, 12, 'Denn was habe ich mit dem Richten von Leuten außerhalb der Gemeinde zu tun? Habt nicht auch ihr (nur) die zu eurer Gemeinde Gehörigen zu richten?');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 5, 13, 'Die draußen Stehenden wird Gott richten. Schafft den bösen Menschen aus eurer Mitte weg!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 6, 1, 'Gewinnt es wirklich jemand von euch über sich, wenn er einen Rechtshandel mit einem andern (Bruder) hat, sein Recht vor den Ungerechten anstatt vor den Heiligen zu suchen?');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 6, 2, 'Wißt ihr denn nicht, daß die Heiligen (einst) die Welt richten werden? Wenn euch also das Gericht über die Welt zusteht, seid ihr da nicht geeignet für die Entscheidung der geringfügigsten Rechtshändel?');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 6, 3, 'Wißt ihr nicht, daß wir sogar Engel richten werden, geschweige denn Rechtshändel um mein und dein?');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 6, 4, 'Wenn ihr also Streitsachen über mein und dein habt, da laßt ihr solche Leute über euch zu Gericht sitzen, die sonst in der Gemeinde keine Achtung genießen!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 6, 5, 'Euch zur Beschämung muß ich das sagen! Gibt es denn wirklich keinen einzigen einsichtigen Mann unter euch, der befähigt wäre, zwischen Brüdern als Schiedsrichter zu entscheiden?');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 6, 6, 'Aber nein, statt dessen streitet ein Bruder mit dem andern vor den Richtern, und noch dazu vor Ungläubigen!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 6, 7, 'Es ist überhaupt das schon ein sittlicher Mangel an euch, daß ihr Rechtshändel miteinander habt. Warum laßt ihr euch nicht lieber Unrecht zufügen, warum laßt ihr euch nicht lieber übervorteilen?');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 6, 8, 'Aber statt dessen verübt ihr selber Unrecht und Übervorteilung, und noch dazu an Brüdern!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 6, 9, 'Wißt ihr nicht, daß keiner, der Unrecht tut, das Reich Gottes erben wird? Irret euch nicht! Weder Unzüchtige noch Götzendiener, weder Ehebrecher noch Lüstlinge und Knabenschänder,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 6, 10, 'weder Diebe noch Betrüger, auch keine Trunkenbolde, keine Verleumder und Räuber werden das Reich Gottes erben.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 6, 11, 'Und Leute solcher Art sind manche (von euch früher) gewesen. Doch ihr habt euch (in der Taufe) reinwaschen lassen, seid geheiligt worden, habt die Rechtfertigung erlangt durch den Namen des Herrn Jesus Christus und durch den Geist unsers Gottes.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 6, 12, '»Alles ist mir erlaubt!« – Ja, aber nicht alles ist zuträglich. »Alles ist mir erlaubt!« – Ja, aber ich darf mich nicht von irgend etwas beherrschen lassen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 6, 13, '»Die Speisen sind für den Bauch da, und der Bauch ist für die Speisen da.« – Ja, aber Gott wird sowohl diesen als auch jenem ein Ende bereiten. Doch der Leib ist nicht für die Unzucht da, sondern für den Herrn, und der Herr ist da für den Leib;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 6, 14, 'Gott aber hat den Herrn auferweckt und wird auch uns durch seine Macht auferwecken.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 6, 15, 'Wißt ihr nicht, daß eure Leiber Glieder Christi sind? Soll ich nun die Glieder Christi nehmen und Glieder einer Buhlerin aus ihnen machen? Nimmermehr!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 6, 16, 'Oder wißt ihr nicht, daß, wer sich an eine Buhlerin hängt, ein Leib mit ihr ist? Es heißt ja: »Die beiden werden ein Fleisch sein.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 6, 17, 'Wer dagegen dem Herrn anhängt, der ist ein Geist mit ihm.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 6, 18, 'Fliehet die Unzucht! Jede (andere) Sünde, die ein Mensch begeht, bleibt außerhalb seines Leibes, der Unzüchtige aber sündigt gegen seinen eigenen Leib.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 6, 19, 'Oder wißt ihr nicht, daß euer Leib ein Tempel des in euch wohnenden heiligen Geistes ist, den ihr von Gott empfangen habt, und daß ihr (somit) nicht euch selbst gehört?');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 6, 20, 'Denn ihr seid teuer erkauft worden. Macht also Gott Ehre mit eurem Leibe!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 7, 1, 'Auf die Anfragen in eurem Briefe aber (antworte ich folgendes): Ein Mann tut gut, (überhaupt) kein Weib zu berühren;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 7, 2, 'aber um der (Vermeidung der) Unzuchtsünden willen mag jeder (Mann) eine Ehefrau und jede (Frau) ihren Ehemann haben.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 7, 3, 'Der Mann leiste seiner Frau die schuldige Ehepflicht, ebenso auch die Frau ihrem Manne!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 7, 4, 'Die Frau hat nicht über ihren Leib zu verfügen, sondern ihr Mann; gleicherweise besitzt aber auch der Mann kein Verfügungsrecht über seinen Leib, sondern die Frau.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 7, 5, 'Entzieht euch einander nicht, höchstens aufgrund beiderseitigen Einverständnisses für eine (bestimmte) Zeit, um euch (ungestört) dem Gebet zu widmen, aber dann wieder zusammenzukommen, damit der Satan euch nicht infolge eurer Unenthaltsamkeit in Versuchung führe!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 7, 6, 'Übrigens spreche ich dies nur als ein Zugeständnis aus, nicht als ein Gebot.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 7, 7, 'Ich möchte freilich wünschen, daß alle Menschen so wären wie ich; doch jeder hat hierin eine besondere Gabe von Gott, der eine so, der andere anders.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 7, 8, 'Den Unverheirateten aber und den Witwen sage ich: Sie tun gut, wenn sie so bleiben, wie auch ich es bin;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 7, 9, 'können sie aber nicht enthaltsam leben, so mögen sie heiraten; denn in der Ehe leben ist besser als entflammt sein.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 7, 10, 'Den Verheirateten aber gebiete ich – nein, nicht ich, sondern der Herr –, daß eine Frau sich von ihrem Manne nicht scheiden soll;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 7, 11, 'hat sie sich aber doch geschieden, so soll sie unverheiratet bleiben oder sich mit ihrem Mann wieder versöhnen; und ebenso soll auch der Mann seine Frau nicht entlassen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 7, 12, 'Den übrigen aber sage ich von mir aus, nicht der Herr: Wenn ein (christlicher) Bruder eine Ungläubige zur Frau hat und diese einverstanden ist, mit ihm weiterzuleben, so soll er sie nicht entlassen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 7, 13, 'Ebenso, wenn eine (gläubige) Frau einen ungläubigen Mann hat und dieser einverstanden ist, mit ihr weiterzuleben, so soll sie ihren Mann nicht entlassen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 7, 14, 'Denn der ungläubige Mann ist durch seine Frau geweiht, und die ungläubige Frau ist durch den (gläubigen) Bruder geweiht; sonst wären ja auch eure Kinder unrein, und sie sind doch in Wirklichkeit geweiht.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 7, 15, 'Wenn jedoch der ungläubige Teil durchaus die Trennung will, so mag er sich trennen: in solchen Fällen ist der Bruder oder die Schwester nicht sklavisch (an eine Ehe) gebunden; vielmehr hat Gott uns zu einem Leben in Frieden berufen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 7, 16, 'Denn wie kannst du, o Frau, wissen, ob du deinen Mann wirklich retten wirst? Oder wie kannst du, o Mann, wissen, ob du deine Frau wirklich retten wirst?');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 7, 17, 'Nur wie der Herr einem jeden sein Los zugeteilt, wie Gott einen jeden berufen hat, so lebe er weiter: diese Vorschrift gebe ich in allen Gemeinden.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 7, 18, 'Ist jemand als Beschnittener berufen worden, so suche er seine Beschneidung nicht rückgängig zu machen; und wer als Unbeschnittener berufen worden ist, lasse sich nicht beschneiden:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 7, 19, 'die Beschneidung hat keinen Wert, und auch das Unbeschnittensein hat keinen Wert, sondern nur die Beobachtung der Gebote Gottes.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 7, 20, 'Jeder bleibe in dem Stande, in dem er berufen worden ist!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 7, 21, 'Bist du als Sklave berufen worden: laß dich’s nicht anfechten, nein, selbst wenn du frei werden kannst, so bleibe nur um so lieber dabei.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 7, 22, 'Denn der im Herrn berufene Sklave ist ein Freigelassener des Herrn, und ebenso ist der Freie nach seiner Berufung ein Sklave Christi.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 7, 23, 'Ihr seid teuer erkauft worden: werdet nicht Knechte der Menschen!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 7, 24, 'Ein jeder, liebe Brüder, möge in dem Stande, in dem er berufen worden ist, bei Gott verbleiben!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 7, 25, 'In betreff der Mädchen aber habe ich kein (ausdrückliches) Gebot des Herrn, spreche aber meine eigene Ansicht aus als einer, der Barmherzigkeit vom Herrn erfahren hat, so daß ich Vertrauen verdiene.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 7, 26, 'Ich halte also dafür, daß dieser Stand (der Ehelosigkeit) empfehlenswert ist wegen der gegenwärtigen schweren Zeitlage, daß (nämlich) ein jeder gut tut, so zu bleiben (wie er ist).');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 7, 27, 'Bist du an eine Gattin gebunden, so suche keine Lösung des Verhältnisses; bist du ledig, so suche keine Gattin;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 7, 28, 'doch hast du, wenn du heiratest, damit keine Sünde begangen, und auch ein Mädchen sündigt nicht, wenn es sich verheiratet. Freilich – Not im äußeren Leben werden die Betreffenden (durchzumachen) haben, und ich möchte euch doch davon verschont sehen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 7, 29, 'Das aber sage ich euch, liebe Brüder: Die Frist ist nur noch kurz bemessen; künftighin müssen auch die, welche eine Frau haben, sich so verhalten, als hätten sie keine,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 7, 30, 'ebenso die Weinenden, als weinten sie nicht, die Fröhlichen, als wären sie nicht fröhlich, die Kaufenden, als ob sie (das Gekaufte) nicht behielten,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 7, 31, 'und die mit der Welt Verkehrenden, als hätten sie nichts mit ihr zu schaffen; denn die Welt in ihrer jetzigen Gestalt geht dem Untergang entgegen!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 7, 32, 'Da möchte ich nun wünschen, daß ihr frei von Sorgen bliebet. Der Unverheiratete ist um die Sache des Herrn besorgt: er möchte dem Herrn gefallen;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 7, 33, 'der Verheiratete dagegen sorgt sich um die Dinge der Welt: er möchte seiner Frau gefallen;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 7, 34, 'so ist er geteilten Herzens. Ebenso richtet die Frau, die keinen Mann mehr hat, und die Jungfrau ihr Sorgen auf die Sache des Herrn: sie möchten an Leib und Geist heilig sein; die verheiratete Frau dagegen sorgt sich um die Dinge der Welt: sie möchte ihrem Manne gefallen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 7, 35, 'Diesen Rat (ledig zu bleiben) gebe ich euch aber zu eurem eigenen Besten, nicht um euch eine Schlinge um den Hals zu legen, sondern zur Förderung guter Sitte und zu treuem Festhalten am Herrn.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 7, 36, 'Meint jedoch jemand, an seiner unverheirateten Tochter nicht recht zu handeln, falls sie die Jahre ihrer Jugendblüte überschreite, und liegt demnach ein Anlaß (zu ihrer Verheiratung) vor, so tue er, was er will; er versündigt sich nicht: sie mögen sich heiraten.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 7, 37, 'Wer dagegen in seinem Herzen fest geworden ist und sich in keiner Zwangslage befindet, sondern freier Herr über seinen Willen ist und sich fest vorgenommen hat, seine jungfräuliche Tochter unverheiratet zu lassen, der wird gut daran tun.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 7, 38, 'Also: wer seine unverheiratete Tochter verheiratet, tut gut daran, und wer sie nicht verheiratet, wird noch besser tun.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 7, 39, 'Eine Ehefrau ist so lange gebunden, als ihr Mann lebt; wenn aber ihr Mann entschlafen ist, so steht es ihr frei, sich zu verheiraten, mit wem sie will, nur geschehe es im Herrn!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 7, 40, 'Glücklicher aber ist sie zu preisen, wenn sie so bleibt (wie sie ist); das ist meine Ansicht, und ich denke doch auch den Geist Gottes zu besitzen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 8, 1, '»Was sodann das Götzenopferfleisch betrifft, so wissen wir, daß wir allesamt im Besitz der (erforderlichen) Erkenntnis sind.« Ja, aber die Erkenntnis macht dünkelhaft, die Liebe dagegen erbaut.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 8, 2, 'Wer sich auf seine Erkenntnis etwas einbildet, der hat noch nicht so erkannt, wie man erkennen muß;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 8, 3, 'wer dagegen Gott liebt, der ist von ihm erkannt.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 8, 4, '»Was nun den Genuß des Götzenopferfleisches betrifft, so wissen wir, daß es keinen Götzen in der Welt gibt und daß es keinen (anderen) Gott gibt als den einen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 8, 5, 'Denn mag es auch sogenannte Götter, sei es im Himmel oder auf der Erde geben – es gibt ja (wirklich) viele solche Götter und viele Herren –,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 8, 6, 'so gibt es doch für uns (Christen) nur einen Gott, nämlich den Vater, von dem alle Dinge sind und wir zu ihm, und nur einen Herrn, nämlich Jesus Christus, durch den alle Dinge (geworden) sind und wir durch ihn.« –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 8, 7, 'Ja, aber es besitzen nicht alle (Christen) solche Erkenntnis, vielmehr gibt es manche, die infolge ihrer (früheren) Gewöhnung an den Götzendienst (das Fleisch) noch als ein dem Götzen geweihtes Opfer essen, und so wird ihr Gewissen, schwach wie es ist, dadurch befleckt.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 8, 8, '»(Der Genuß von) Speise wird für unsere Stellung zu Gott nicht maßgebend sein: essen wir nicht, so haben wir dadurch keinen Nachteil, und essen wir, so haben wir dadurch keinen Vorteil.« –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 8, 9, 'Ja, aber sehet wohl zu, daß diese eure Freiheit für die Schwachen nicht zu einem Anstoß werde!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 8, 10, 'Denn wenn jemand dich mit deiner »Erkenntnis« in einem Götzentempel am Mahl teilnehmen sieht, muß da nicht sein Gewissen, wenn er schwach ist, dazu »erbaut« werden, (ebenfalls) das Götzenopferfleisch zu essen?');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 8, 11, 'So wird dann der Schwache durch deine Erkenntnis ins Verderben gebracht, der Bruder, um dessen willen Christus gestorben ist!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 8, 12, 'Wenn ihr euch aber auf diese Weise an den Brüdern versündigt und ihr schwaches Gewissen mißhandelt, so versündigt ihr euch an Christus.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 8, 13, 'Darum, wenn Speise meinem Bruder zum Anstoß wird, so will ich in Ewigkeit kein Fleisch genießen, um meinem Bruder kein Ärgernis zu bereiten.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 9, 1, 'Bin ich nicht ein freier (Mann)? Bin ich nicht ein Apostel? Habe ich nicht unsern Herrn Jesus gesehen? Seid ihr nicht mein Werk im Herrn?');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 9, 2, 'Mag ich für andere kein Apostel sein, so bin ich es doch sicherlich für euch; denn das Siegel für mein Apostelamt seid ihr im Herrn.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 9, 3, 'Das ist meine Rechtfertigung denen gegenüber, die über mich zu Gericht sitzen (wollen).');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 9, 4, 'Haben wir (Apostel) etwa nicht das Recht, Essen und Trinken zu beanspruchen?');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 9, 5, 'Haben wir nicht das Recht, eine Schwester als Ehefrau (auf unsern Reisen) bei uns zu haben wie die übrigen Apostel und die Brüder des Herrn und Kephas?');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 9, 6, 'Oder sind wir allein, ich und Barnabas, nicht berechtigt, die Handarbeit zu unterlassen?');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 9, 7, 'Wer leistet jemals Kriegsdienste für eigenen Sold? Wer legt einen Weinberg an, ohne von dessen Früchten zu essen? Oder wer hütet eine Herde, ohne von der Milch der Herde zu genießen?');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 9, 8, 'Behaupte ich dies etwa als einen bloß von Menschen aufgestellten Grundsatz, oder enthält nicht das Gesetz dieselbe Verordnung?');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 9, 9, 'Im mosaischen Gesetz steht ja doch geschrieben: »Du sollst einem Ochsen, der zu dreschen hat, das Maul nicht verbinden!« Ist es Gott etwa um die Ochsen zu tun?');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 9, 10, 'Oder gehen seine Worte nicht ohne allen Zweifel auf uns? Ja, um unsertwillen steht geschrieben, daß der Pflüger auf Hoffnung hin pflügen und der Drescher in der Hoffnung auf Mitgenuß (des Ertrages) arbeiten soll.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 9, 11, 'Wenn wir für euch das Geistliche ausgesät haben, ist es da etwas Absonderliches, wenn wir von euch das Irdische ernten?');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 9, 12, 'Wenn andere an dem Verfügungsrecht über euch Anteil haben, sind wir dann nicht in noch höherem Grade dazu berechtigt? Aber wir haben von diesem Recht keinen Gebrauch gemacht, sondern ertragen lieber alles, um nur der Heilsbotschaft Christi kein Hindernis in den Weg zu legen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 9, 13, 'Wißt ihr nicht, daß die, welche den Tempeldienst verrichten, von den Einkünften des Tempels ihren Unterhalt haben? Daß die, welche beständig am Opferaltar tätig sind, ihren Anteil vom Altar erhalten?');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 9, 14, 'Ebenso hat auch der Herr über die Verkündiger der Heilsbotschaft die Anordnung getroffen, daß sie von der Heilsverkündigung leben sollen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 9, 15, 'Ich aber habe von keinem dieser Rechte für mich Gebrauch gemacht, und ich schreibe euch dieses auch nicht deshalb, damit es fortan mit mir so gehalten werde; denn lieber wollte ich sterben, als – nein, meinen Ruhm soll mir niemand zunichte machen!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 9, 16, 'Denn wenn ich die Heilsbotschaft verkündige, so habe ich daran keinen Grund zum Rühmen, denn ich stehe dabei unter einem Zwang; ein ›Wehe!‹ träfe mich ja, wenn ich die Heilsbotschaft nicht verkündigte!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 9, 17, 'Denn nur, wenn ich dies aus freiem Entschluß tue, habe ich (Anspruch auf) Lohn; wenn ich es aber unfreiwillig tue, so ist es nur ein Haushalteramt, mit dem ich betraut bin.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 9, 18, 'Worin besteht demnach mein Lohn? Darin, daß ich als Verkündiger der Heilsbotschaft diese unentgeltlich darbiete, so daß ich von meinem Recht bei der Verkündigung der Heilsbotschaft keinen Gebrauch mache.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 9, 19, 'Denn obwohl ich von allen Menschen unabhängig bin, habe ich mich doch allen zum Knecht gemacht, um die Mehrzahl von ihnen zu gewinnen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 9, 20, 'So bin ich denn für die Juden zu einem Juden geworden, um Juden zu gewinnen; für die Gesetzesleute zu einem Mann des Gesetzes – obgleich ich selbst nicht unter dem Gesetz stehe –, um die Gesetzesleute zu gewinnen;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 9, 21, 'für die (Heiden), die das Gesetz nicht haben, zu einem Manne, der ohne das Gesetz lebt – obgleich ich nicht ohne Gottes Gesetz lebe, vielmehr dem Gesetz Christi unterworfen bin –, um die, welche das Gesetz nicht haben, zu gewinnen;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 9, 22, 'für die Schwachen bin ich ein Schwacher geworden, um die Schwachen zu gewinnen; kurz: für alle bin ich alles geworden, um auf jeden Fall einige zu retten.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 9, 23, 'Alles (das) aber tue ich um der Heilsbotschaft willen, damit auch ich Anteil an ihr erlange.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 9, 24, 'Wißt ihr nicht, daß die, welche in der Rennbahn laufen, zwar alle laufen, daß aber nur einer den Siegespreis erhält? Lauft ihr nun in der Weise, daß ihr ihn erlangt!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 9, 25, 'Jeder aber, der sich am Wettkampf beteiligen will, legt sich Enthaltsamkeit in allen Beziehungen auf, jene, um einen vergänglichen Kranz zu empfangen, wir aber einen unvergänglichen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 9, 26, 'So laufe ich denn nicht ziellos und treibe den Faustkampf so, daß ich keine Lufthiebe führe;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 9, 27, 'sondern ich zerschlage meinen Leib und mache ihn mir dienstbar, um nicht, nachdem ich als Herold andere zum Kampf aufgerufen habe, mich selbst als untüchtig zu erweisen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 10, 1, 'Ich will euch nämlich nicht in Unkenntnis darüber lassen, liebe Brüder, daß unsere Väter allesamt unter (dem Schutz) der Wolke gestanden haben und allesamt durch das Meer hindurchgezogen sind');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 10, 2, 'und sämtlich die Taufe auf Mose in der Wolke und im Meer empfangen,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 10, 3, 'auch allesamt dieselbe geistliche Speise gegessen');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 10, 4, 'und sämtlich denselben geistlichen Trank getrunken haben: sie tranken nämlich aus einem geistlichen Felsen, der sie begleitete, und dieser Fels war Christus.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 10, 5, 'Doch an den meisten von ihnen hatte Gott kein Wohlgefallen, denn sie sind in der Wüste niedergestreckt worden.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 10, 6, 'Diese Dinge aber sind zum warnenden Vorbild für uns geschehen, damit wir unsre Gelüste nicht auf Böses richten, wie jene sich haben gelüsten lassen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 10, 7, 'Werdet auch keine Götzendiener, wie manche von jenen; es steht ja geschrieben: »Das Volk setzte sich nieder, um zu essen und zu trinken, und stand wieder auf, um sich zu belustigen.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 10, 8, 'Wir wollen auch keine Unzucht treiben, wie manche von jenen es getan haben; sind doch (deshalb) von ihnen an einem einzigen Tage dreiundzwanzigtausend gefallen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 10, 9, 'Wir wollen auch den Herrn nicht versuchen, wie manche von ihnen es getan haben und dafür von den Schlangen umgebracht worden sind.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 10, 10, 'Murret auch nicht, wie manche von ihnen getan und dafür den Tod durch den Verderber erlitten haben.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 10, 11, 'Dies alles ist jenen aber vorbildlicherweise widerfahren und ist niedergeschrieben worden zur Warnung für uns, denen das Ende der Weltzeiten nahe bevorsteht.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 10, 12, 'Wer daher festzustehen meint, der sehe wohl zu, daß er nicht falle!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 10, 13, 'Es hat euch (bisher) noch keine andere als menschliche Versuchung betroffen; und Gott ist treu: er wird nicht zulassen, daß ihr über euer Vermögen hinaus versucht werdet, sondern wird zugleich mit der Versuchung auch einen solchen Ausgang schaffen, daß ihr sie bestehen könnt.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 10, 14, 'Darum, meine Geliebten, fliehet vor dem Götzendienst!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 10, 15, 'Ich rede ja doch zu euch als zu verständigen Leuten: urteilt selbst über das, was ich sage!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 10, 16, 'Der Kelch des Segens, den wir segnen: ist er nicht die Gemeinschaft mit dem Blute Christi? Das Brot, das wir brechen: ist es nicht die Gemeinschaft mit dem Leibe Christi?');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 10, 17, 'Weil es ein einziges Brot ist, sind wir trotz unserer Vielheit doch ein einziger Leib, denn wir alle teilen uns in das eine Brot.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 10, 18, 'Sehet das irdische Israel an: stehen nicht die, welche die Opfer essen, in engster Gemeinschaft mit dem Opferaltar?');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 10, 19, 'Was behaupte ich nun damit? Daß das Götzenopferfleisch etwas sei? Oder daß ein Götze etwas sei?');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 10, 20, 'Nein, wohl aber (behaupte ich), daß die Heiden die Opfer, die sie darbringen, dämonischen Wesen und nicht Gott darbringen. Ich will aber nicht, daß ihr in Verbindung mit den Dämonen tretet.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 10, 21, 'Ihr könnt nicht (zugleich) den Kelch des Herrn und den Kelch der Dämonen trinken; ihr könnt nicht (zugleich) am Tisch des Herrn und am Tisch der Dämonen Gäste sein.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 10, 22, 'Oder wollen wir den Herrn zu Eifersucht reizen? Sind wir etwa stärker als er?');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 10, 23, '»Alles ist (uns Christen) erlaubt!« – Ja, aber nicht alles ist zuträglich. »Alles ist erlaubt!« – Ja, aber nicht alles erbaut.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 10, 24, 'Niemand sei (nur) auf seinen eigenen Vorteil bedacht, sondern (jeder) auf die Förderung des anderen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 10, 25, 'Alles, was auf dem Fleischmarkt zum Verkauf steht, das esset, ohne um des Gewissens willen Nachforschungen anzustellen;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 10, 26, 'denn »dem Herrn gehört die (ganze) Erde und alle ihre Fülle«.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 10, 27, 'Wenn einer von den Ungläubigen euch zu Gast einlädt und ihr hingehen wollt, so esset alles, was man euch vorsetzt, ohne um des Gewissens willen Nachforschungen anzustellen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 10, 28, 'Wenn aber jemand euch (ausdrücklich) sagt: »Dies ist Opferfleisch!«, so esset nicht davon mit Rücksicht auf den, der euch darauf hingewiesen hat, und um des Gewissens willen –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 10, 29, 'ich meine damit jedoch nicht euer eigenes Gewissen, sondern das des anderen; denn warum soll ich meine Freiheit von dem Gewissen eines anderen richten lassen?');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 10, 30, 'Wenn ich für meine Person etwas mit Danksagung (gegen Gott) genieße, warum soll ich mich da bezüglich dessen, wofür ich ein Dankgebet spreche, schmähen lassen?');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 10, 31, 'Nun: mögt ihr essen oder trinken oder sonst etwas tun, tut alles zur Verherrlichung Gottes!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 10, 32, 'Gebt weder den Juden noch den Griechen noch der Gemeinde Gottes einen Anstoß,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 10, 33, 'wie auch ich allen in jeder Hinsicht zu Gefallen lebe, indem ich nicht meinen Vorteil suche, sondern den der vielen, damit sie gerettet werden.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 11, 1, 'Nehmt mich zum Vorbild, gleichwie ich meinerseits dem Vorbild Christi nachfolge!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 11, 2, 'Ich erkenne es aber lobend bei euch an, daß »ihr in allen Beziehungen meiner eingedenk seid und an den Überlieferungen festhaltet, wie ich sie euch mitgeteilt habe.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 11, 3, 'Ich möchte euch aber zu bedenken geben, daß das Haupt jedes Mannes Christus ist, das Haupt der Frau aber ist der Mann, und das Haupt Christi ist Gott.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 11, 4, 'Jeder Mann, der beim Beten oder beim prophetischen Reden eine Kopfbedeckung trägt, entehrt dadurch sein Haupt;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 11, 5, 'jede Frau dagegen, die mit unverhülltem Haupte betet oder prophetisch redet, entehrt dadurch ihr Haupt, denn sie steht damit auf völlig gleicher Stufe mit einer Geschorenen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 11, 6, 'Denn wenn eine Frau sich nicht verschleiert, so mag sie sich auch das Haar abschneiden lassen; ist es aber für eine Frau schimpflich, sich das Haar kurz zu schneiden oder es sich ganz abscheren zu lassen, so soll sie sich verschleiern!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 11, 7, 'Der Mann dagegen darf das Haupt nicht verhüllt haben, weil er Gottes Abbild und Abglanz ist; die Frau aber ist der Abglanz des Mannes.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 11, 8, 'Der Mann stammt ja doch nicht von der Frau, sondern die Frau vom Manne;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 11, 9, 'auch ist der Mann ja nicht um der Frau willen geschaffen, sondern die Frau um des Mannes willen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 11, 10, 'Deshalb muß die Frau (ein Zeichen der) Herrschaft auf dem Haupte tragen um der Engel willen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 11, 11, 'Sonst steht jedoch weder die Frau gesondert vom Mann, noch der Mann gesondert von der Frau im Herrn da;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 11, 12, 'denn wie die Frau aus dem Manne entstanden ist, so wird wiederum der Mann durch die Frau geboren; alles aber ist von Gott ausgegangen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 11, 13, 'Urteilt für euch selbst: Ist es schicklich, daß eine Frau unverhüllt zu Gott betet?');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 11, 14, 'Und lehrt euch nicht schon euer natürliches Gefühl, daß, wenn ein Mann langes Haar trägt, es eine Schmach für ihn ist,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 11, 15, 'während, wenn eine Frau langes Haar trägt, es eine Ehre für sie ist? Denn das lange Haar ist ihr als Schleier gegeben.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 11, 16, 'Will aber jemand durchaus auf seiner abweichenden Meinung bestehen (so wisse er): Wir kennen eine solche Sitte nicht, und auch die Gemeinden Gottes überhaupt.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 11, 17, 'Die folgenden Anordnungen aber treffe ich, weil ich es nicht löblich finde, daß eure Zusammenkünfte euch nicht zum Segen, sondern zur Schädigung gereichen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 11, 18, 'Zunächst nämlich höre ich, daß, wenn ihr in einer Gemeindeversammlung zusammenkommt, Spaltungen unter euch bestehen, und zum Teil glaube ich es wirklich;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 11, 19, 'es muß ja doch auch Parteiungen bei euch geben, damit die Bewährten unter euch erkennbar werden!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 11, 20, 'Wenn ihr also an einem Ort zusammenkommt, so ist es nicht möglich, das Herrenmahl zu essen;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 11, 21, 'denn jeder nimmt beim Essen seine eigene Mahlzeit vorweg, so daß der eine hungrig bleibt, während der andere trunken ist.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 11, 22, 'Habt ihr denn keine Häuser, um dort zu essen und zu trinken? Oder verachtet ihr die Gemeinde Gottes und geht ihr darauf aus, die Unbemittelten zu beschämen? Was soll ich dazu sagen? Soll ich euch etwa loben? In diesem Punkte sicherlich nicht!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 11, 23, 'Denn ich habe es meinerseits vom Herrn her so überkommen, wie ich es euch auch überliefert habe: Der Herr Jesus, in der Nacht, in der er verraten wurde, nahm er Brot,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 11, 24, 'sprach das Dankgebet, brach das Brot und sagte: »Dies ist mein Leib, (der) für euch (gebrochen oder: dahingegeben wird); dies tut zu meinem Gedächtnis!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 11, 25, 'Ebenso (nahm er) auch den Kelch nach dem Mahl und sagte: »Dieser Kelch ist der neue Bund in meinem Blut; dies tut, sooft ihr (ihn) trinkt, zu meinem Gedächtnis!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 11, 26, 'Denn sooft ihr dieses Brot eßt und den Kelch trinkt, verkündigt ihr (damit) den Tod des Herrn, bis er (wieder-) kommt.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 11, 27, 'Wer daher in unwürdiger Weise das Brot ißt oder den Kelch des Herrn trinkt, der wird sich am Leibe und am Blute des Herrn versündigen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 11, 28, 'Jedermann prüfe sich also selbst und esse dann erst von dem Brot und trinke von dem Kelch!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 11, 29, 'Denn wer da ißt und trinkt, der zieht sich selbst durch sein Essen und Trinken ein (göttliches) Strafurteil zu, wenn er den Leib (des Herrn) nicht unterscheidet.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 11, 30, 'Deshalb gibt es unter euch auch Schwache und Kranke in so großer Zahl, und gar viele sind schon entschlafen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 11, 31, 'Wenn wir aber mit uns selbst ins Gericht gingen, so würden wir kein Strafurteil empfangen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 11, 32, 'Indem wir jedoch ein Strafurteil empfangen, werden wir vom Herrn gezüchtigt, damit wir nicht mit der Welt zusammen verurteilt werden.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 11, 33, 'Darum, meine Brüder, wenn ihr zum Essen zusammenkommt, so wartet aufeinander!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 11, 34, 'Wenn jemand Hunger hat, so esse er (vorher) zu Hause, damit ihr durch eure Zusammenkünfte euch kein Strafgericht zuzieht. Das Weitere werde ich anordnen, wenn ich (zu euch) komme.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 12, 1, 'In betreff der Geistesgaben aber will ich euch, liebe Brüder, nicht im unklaren lassen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 12, 2, 'Ihr wißt von eurer Heidenzeit her: da waren es die stummen Götzenbilder, zu denen ihr mit unwiderstehlicher Gewalt hingezogen wurdet.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 12, 3, 'Darum tue ich euch kund, daß niemand, der im Geiste Gottes redet, sagt: »Verflucht ist Jesus!« und keiner zu sagen vermag: »Jesus ist der Herr!«, außer im heiligen Geist.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 12, 4, 'Es gibt nun zwar verschiedene Arten von Gnadengaben, aber nur einen und denselben Geist;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 12, 5, 'und es gibt verschiedene Arten von Dienstleistungen, doch nur einen und denselben Herrn;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 12, 6, 'und es gibt verschiedene Arten von Kraftwirkungen, aber nur einen und denselben Gott, der alles in allen wirkt.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 12, 7, 'Jedem wird aber die Offenbarung des Geistes zum allgemeinen Besten verliehen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 12, 8, 'So wird dem einen durch den Geist Weisheitsrede verliehen, einem andern Erkenntnisrede nach Maßgabe desselben Geistes,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 12, 9, 'einem andern Glaube in demselben Geist, einem andern Heilungsgaben in dem einen Geiste,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 12, 10, 'einem andern Verrichtung von Wundertaten, einem andern Weissagung, einem andern Unterscheidung der Geister, einem andern mancherlei Arten von Zungenreden, einem andern die Auslegung der Zungenreden.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 12, 11, 'Dies alles wirkt aber ein und derselbe Geist, indem er jedem eine besondere Gabe zuteilt, wie er will.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 12, 12, 'Denn wie der Leib eine Einheit ist und doch viele Glieder hat, alle Glieder des Leibes aber trotz ihrer Vielheit einen Leib bilden, so ist es auch mit Christus.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 12, 13, 'Denn durch einen Geist sind wir alle durch die Taufe zu einem Leibe zusammengeschlossen worden, wir mögen Juden oder Griechen, Sklaven oder Freie sein, und wir sind alle mit einem Geist getränkt worden.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 12, 14, 'Auch der Leib besteht ja nicht aus einem einzigen Gliede, sondern aus vielen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 12, 15, 'Wenn der Fuß sagte: »Weil ich nicht Hand bin, gehöre ich nicht zum Leibe«, so gehört er darum doch zum Leibe;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 12, 16, 'und wenn das Ohr sagte: »Weil ich kein Auge bin, gehöre ich nicht zum Leibe«, so gehört es darum doch zum Leibe.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 12, 17, 'Wenn der ganze Leib nur Auge wäre, wo bliebe da das Gehör? Wenn er ganz Gehör wäre, wo bliebe da der Geruchssinn?');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 12, 18, 'Nun aber hat Gott jedem einzelnen Gliede seine besondere Stelle am Leibe angewiesen, wie es seinem Willen entsprach.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 12, 19, 'Wäre das Ganze nur ein einziges Glied, wo bliebe da der Leib?');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 12, 20, 'So aber sind zwar viele Glieder vorhanden, aber es besteht doch nur ein Leib.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 12, 21, 'Das Auge kann aber nicht zu der Hand sagen: »Ich habe dich nicht nötig«, ebensowenig der Kopf zu den Füßen: »Ich habe euch nicht nötig«;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 12, 22, 'ganz im Gegenteil: die scheinbar schwächsten Glieder des Leibes sind gerade notwendig,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 12, 23, 'und denjenigen Körperteilen, die wir für weniger edel halten, erweisen wir besondere Ehre, und die weniger anständigen Teile unsers Leibes erhalten eine besonders wohlanständige Ausstattung,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 12, 24, 'deren unsere anständigen Glieder nicht bedürfen. Ja, Gott hat den Leib so zusammengefügt, daß er dem weniger wichtigen Gliede desto größere Ehre zugeteilt hat,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 12, 25, 'damit keine Uneinigkeit im Leibe herrsche, sondern die Glieder einträchtig füreinander sorgen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 12, 26, 'Und wenn ein Glied leidet, so leiden alle Glieder mit, und wenn ein Glied besonders geehrt wird, so freuen sich alle Glieder mit.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 12, 27, 'Ihr aber seid Christi Leib, und jeder einzelne ist ein Glied daran nach seinem Teil;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 12, 28, 'und zwar hat Gott in der Gemeinde eingesetzt erstens die einen zu Aposteln, zweitens (andere) zu Propheten, drittens (noch andere) zu Lehrern; sodann Wunderkräfte, sodann Gaben der Heilungen, Hilfeleistungen, Verwaltungsgeschäfte, mancherlei Arten von Zungenreden.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 12, 29, 'Sind etwa alle (Gemeindeglieder) Apostel? Etwa alle Propheten? Alle Lehrer? Besitzen etwa alle Wunderkräfte?');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 12, 30, 'Haben etwa alle Heilungsgaben? Reden alle mit Zungen? Können alle die Zungensprachen auslegen?');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 12, 31, 'Strebet nun eifrig nach den höchsten Gnadengaben! Und jetzt will ich euch noch einen ganz unvergleichlichen Weg zeigen:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 13, 1, 'Wenn ich in den Zungensprachen der Menschen und der Engel reden könnte, aber die Liebe nicht besäße, so wäre ich nur ein tönendes Erz oder eine klingende Schelle.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 13, 2, 'Und wenn ich die Gabe prophetischer Rede besäße und alle Geheimnisse wüßte und alle Erkenntnis und wenn ich allen Glauben besäße, so daß ich Berge versetzen könnte, aber die Liebe mir fehlte, so wäre ich nichts.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 13, 3, 'Und wenn ich alle meine Habe (an die Armen) austeilte und meinen Leib dem Feuertode preisgäbe, aber keine Liebe besäße, so würde es mir nichts nützen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 13, 4, 'Die Liebe ist langmütig, ist gütig; die Liebe ist frei von Eifersucht (und Neid), die Liebe prahlt nicht, sie bläht sich nicht auf,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 13, 5, 'sie ist nicht rücksichtslos, sie sucht nicht den eigenen Vorteil, läßt sich nicht erbittern, rechnet das Böse nicht an;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 13, 6, 'sie freut sich nicht über die Ungerechtigkeit, freut sich vielmehr (im Bunde) mit der Wahrheit;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 13, 7, 'sie deckt alles zu, sie glaubt alles, sie hofft alles, sie erträgt alles.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 13, 8, 'Die Liebe hört niemals auf. Die Gabe prophetischer Rede wird ein Ende nehmen, die Zungenreden werden aufhören, die Erkenntnis wird ein Ende haben.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 13, 9, 'Denn Stückwerk ist unser Erkennen und Stückwerk unsere prophetische Redegabe,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 13, 10, 'und wenn das Vollkommene kommt, dann wird das Stückwerk ein Ende haben.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 13, 11, 'Als ich ein Kind war, redete ich wie ein Kind, hatte einen Sinn wie ein Kind, urteilte wie ein Kind; seit ich aber ein Mann geworden bin, habe ich das kindische Wesen abgetan.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 13, 12, 'Denn jetzt sehen wir in einem Spiegel nur undeutliche Bilder, dann aber von Angesicht zu Angesicht. Jetzt ist mein Erkennen nur Stückwerk; dann aber werde ich ganz erkennen, wie auch ich ganz erkannt worden bin.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 13, 13, 'Nun aber bleiben Glaube, Hoffnung, Liebe, diese drei; die größte unter diesen aber ist die Liebe.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 14, 1, 'Jaget also der Liebe nach! Doch bemüht euch (daneben) auch um die Geistesgaben, besonders aber um die Gabe der prophetischen Rede.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 14, 2, 'Denn der Zungenredner redet nicht zu Menschen, sondern zu Gott; niemand versteht ihn ja, vielmehr redet er im Geist Geheimnisse.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 14, 3, 'Der prophetisch Redende dagegen redet zu Menschen zu ihrer Erbauung und Ermahnung und Tröstung.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 14, 4, 'Der Zungenredner erbaut sich selbst, der prophetisch Redende dagegen erbaut die Gemeinde.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 14, 5, 'Ich möchte, daß ihr allesamt mit Zungen redetet, aber noch lieber, daß ihr prophetische Redegabe besäßet; denn der prophetisch Redende steht über dem Zungenredner, es müßte denn sein, daß er (das von ihm Geredete) auch auslegt, damit die Gemeinde Erbauung dadurch empfängt.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 14, 6, 'So aber, liebe Brüder – wenn ich als Zungenredner zu euch käme, was würde ich euch da nützen, wenn ich an euch nicht (auch) Worte der Offenbarung oder Erkenntnis, der prophetischen Zusprache oder der Belehrung richtete?');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 14, 7, 'Wenn die seelenlosen Musikwerkzeuge, obwohl sie einen Klang von sich geben, z.B. eine Flöte oder Zither, die einzelnen Töne nicht unterscheiden lassen, wie soll man da erkennen, was auf der Flöte oder auf der Zither gespielt wird?');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 14, 8, 'Ebenso auch, wenn eine Trompete nur einen undeutlichen Schall hören läßt, wer wird sich da zum Kampfe rüsten?');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 14, 9, 'So steht es auch bei euch: wenn ihr beim Zungenreden keine deutlichen Worte vernehmen laßt, wie soll man da das Gesprochene verstehen? Ihr werdet dann eben nur in den Wind reden.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 14, 10, 'Es gibt wer weiß wie viele verschiedene Sprachen in der Welt, und keine ist (an und für sich) unverständlich;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 14, 11, 'wenn ich aber die Bedeutung (der Wörter) einer Sprache nicht kenne, so werde ich für den in ihr Redenden ein Fremdling sein, und der in ihr Redende bleibt für mich ein Fremdling.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 14, 12, 'So steht es auch mit euch: weil ihr nach den Erweisungen des Geistes eifrig trachtet, so seid darauf bedacht, zur Erbauung der Gemeinde eine reiche Fülle von ihnen zu haben.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 14, 13, 'Deshalb möge der Zungenredner auch um die Gabe der Auslegung beten;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 14, 14, 'denn wenn ich in Zungenrede bete, so betet dabei wohl mein Geist, aber mein Verstand bleibt unbeteiligt.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 14, 15, 'Was folgt nun daraus? Ich will mit dem Geist beten, will aber auch mit dem Verstande beten; ich will Psalmen mit dem Geist singen, aber auch mit dem Verstande;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 14, 16, 'sonst wenn du ein Dankgebet nur mit dem Geist sprichst, wie soll da einer, der den Platz des Laien einnimmt, das Amen zu deinem Dankgebet sprechen? Er versteht ja gar nicht, was du sagst.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 14, 17, 'Du für deine Person magst wohl ein treffliches Dankgebet sprechen, aber der andere wird dadurch nicht erbaut.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 14, 18, 'Ich danke Gott: mehr als ihr alle rede ich in Zungen;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 14, 19, 'aber in einer Gemeindeversammlung will ich lieber fünf Worte mit meinem Verstande reden, um auch andere zu unterweisen, als viele tausend Worte in Zungenrede.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 14, 20, 'Liebe Brüder, zeigt euch nicht als Kinder in der Urteilskraft! Nein, in der Bosheit sollt ihr Kinder sein, aber hinsichtlich der Urteilskraft zeigt euch als Erwachsene.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 14, 21, 'Im Gesetz steht geschrieben: »Durch Menschen mit fremder Sprache und durch die Lippen von Fremden will ich zu diesem Volke reden, und auch so werden sie nicht auf mich hören, spricht der Herr.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 14, 22, 'Mithin sind die Zungenreden ein Zeichen nicht für die Gläubigen, sondern für die Ungläubigen; die prophetische Beredsamkeit dagegen ist ein solches nicht für die Ungläubigen, sondern für die Gläubigen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 14, 23, 'Wenn also die ganze Gemeinde sich an einem Ort versammelte und alle in Zungensprachen redeten und dann Laien oder Ungläubige hereinkämen, würden diese da nicht sagen, ihr seiet von Sinnen?');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 14, 24, 'Wenn dagegen alle prophetisch reden und dann ein Ungläubiger oder ein Laie dazukommt, so wird ihm von allen ins Gewissen geredet, er fühlt sich von allen ins Gericht genommen,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 14, 25, 'die geheimen Gedanken seines Herzens werden aufgedeckt, und so wird er auf sein Angesicht fallen und Gott anbeten und offen bekennen, daß Gott tatsächlich in euch (wirksam) ist.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 14, 26, 'Was folgt nun daraus, ihr Brüder? Sooft ihr euch versammelt, hat ein jeder (etwas in Bereitschaft): ein geistliches Lied, einen belehrenden Vortrag, eine Offenbarung, eine Zungenrede, eine Auslegung (derselben) – das alles laßt zur Erbauung (der Gemeinde) dienen!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 14, 27, 'Will man in Zungensprachen reden, so sollen es jedesmal nur zwei oder höchstens drei sein, und zwar der Reihe nach, und einer soll die Auslegung geben.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 14, 28, 'Ist jedoch kein Ausleger da, so soll er (der Zungenredner) in der Versammlung schweigen: er mag dann für sich allein und zu Gott reden.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 14, 29, 'Propheten sollen gleichfalls nur zwei oder drei zu Worte kommen und die anderen sich ein Urteil darüber bilden.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 14, 30, 'Wenn aber einem anderen, der noch dasitzt, eine Offenbarung zuteil wird, so soll der erste schweigen;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 14, 31, 'denn ihr könnt alle einzeln als prophetische Redner auftreten, damit alle Belehrung empfangen und alle ermahnt werden;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 14, 32, 'und die prophetischen Geister sind ja auch den Propheten gehorsam –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 14, 33, 'denn Gott ist nicht ein Gott der Unordnung, sondern des Friedens – wie in allen Gemeinden der Heiligen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 14, 34, 'Die Frauen sollen in den Gemeindeversammlungen schweigen, denn es kann ihnen nicht gestattet werden zu reden, sondern sie haben sich unterzuordnen, wie auch das (mosaische) Gesetz es gebietet.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 14, 35, 'Wünschen sie aber Belehrung über irgend etwas, so mögen sie daheim ihre Ehemänner befragen; denn es steht einer Frau übel an, sich in einer Gemeindeversammlung hören zu lassen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 14, 36, 'Oder ist etwa das Wort Gottes von euch ausgegangen oder zu euch allein hingekommen?');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 14, 37, 'Wenn jemand sich für einen Propheten oder (überhaupt) für einen Geistbegabten hält, so muß er erkennen, daß das, was ich euch hier schreibe, das Gebot des Herrn ist.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 14, 38, 'Wenn jemand es aber nicht anerkennen will, so wird er (auch von Gott) nicht (an)erkannt.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 14, 39, 'Also, meine Brüder: bemüht euch eifrig um die Gabe prophetischer Beredsamkeit und hindert auch das Zungenreden nicht!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 14, 40, 'Laßt aber alles mit Anstand und in Ordnung vor sich gehen!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 15, 1, 'Ich weise euch aber, liebe Brüder, auf die Heilsbotschaft hin, die ich euch (seinerzeit) getreulich verkündigt habe, die ihr auch angenommen habt, in der ihr auch fest steht');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 15, 2, 'und durch die ihr auch die Rettung erlangt, wenn ihr sie in der Gestalt festhaltet, in welcher ich sie euch getreulich verkündigt habe; es müßte sonst sein, daß ihr vergeblich zum Glauben gekommen wäret.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 15, 3, 'Ich habe euch nämlich an erster Stelle mitgeteilt, was ich auch überkommen habe, daß Christus für unsere Sünden gestorben ist, den Schriften gemäß,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 15, 4, 'und daß er begraben und daß er am dritten Tage auferweckt worden ist, den Schriften gemäß,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 15, 5, 'und daß er dem Kephas erschienen ist, danach den Zwölfen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 15, 6, 'Darauf ist er mehr als fünfhundert Brüdern auf einmal erschienen, von denen die meisten jetzt noch leben, einige aber entschlafen sind.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 15, 7, 'Darauf ist er dem Jakobus erschienen, danach sämtlichen Aposteln.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 15, 8, 'Zuallerletzt aber ist er gleichsam als der Fehlgeburt auch mir erschienen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 15, 9, 'Denn ich bin der geringste unter den Aposteln und des Apostelnamens nicht würdig, weil ich die Gemeinde Gottes verfolgt habe.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 15, 10, 'Durch Gottes Gnade aber bin ich, was ich bin, und seine Gnade gegen mich hat sich nicht erfolglos erwiesen, sondern ich habe weit mehr geschafft als sie alle, doch nicht ich, sondern die Gnade Gottes, die mit mir ist.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 15, 11, 'Ganz gleich nun, ob ich (es bin) oder jene: so lautet unsere Verkündigung, und so seid ihr zum Glauben gekommen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 15, 12, 'Wenn aber unsere Predigt die Auferweckung Christi von den Toten verkündigt, wie kommen da einige unter euch zu der Behauptung, daß es eine Auferstehung der Toten nicht gebe?');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 15, 13, 'Gibt es nämlich keine Auferstehung der Toten, so ist auch Christus nicht auferweckt worden;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 15, 14, 'ist aber Christus nicht auferweckt worden, so ist unsere Predigt leer und leer auch euer Glaube.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 15, 15, 'Dann werden aber auch wir als falsche Zeugen in Gottes Sache erfunden, weil wir gegen Gott das Zeugnis abgelegt haben, daß er Christus auferweckt habe, während er ihn doch nicht auferweckt hat, wenn es wirklich keine Auferweckung der Toten gibt.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 15, 16, 'Denn wenn Tote (überhaupt) nicht auferweckt werden, so ist auch Christus nicht auferweckt worden;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 15, 17, 'wenn aber Christus nicht auferweckt worden ist, so ist euer Glaube nichtig; dann seid ihr noch in euren Sünden;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 15, 18, 'dann sind also auch die in Christus Entschlafenen verloren(gegangen)!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 15, 19, 'Wenn wir weiter nichts sind als solche, die in diesem Leben ihre Hoffnung auf Christus gesetzt haben, so sind wir die beklagenswertesten unter allen Menschen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 15, 20, 'Nun aber ist Christus von den Toten auferweckt worden (und zwar) als Erstling der Entschlafenen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 15, 21, 'Denn weil der Tod durch einen Menschen gekommen ist, erfolgt auch die Auferstehung der Toten durch einen Menschen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 15, 22, 'Wie nämlich in Adam alle sterben, so werden auch in Christus alle wieder zum Leben gebracht werden,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 15, 23, 'ein jeder aber in seiner besonderen Abteilung: als Erstling Christus, hierauf die, welche Christus angehören, bei seiner Ankunft,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 15, 24, 'danach das Ende, wenn er Gott [und] dem Vater das Reich übergibt, sobald er jede (andere) Herrschaft und jede Gewalt und Macht vernichtet hat;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 15, 25, 'denn er muß als König herrschen, »bis er ihm alle Feinde unter die Füße gelegt hat«.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 15, 26, 'Der letzte Feind, der vernichtet wird, ist der Tod;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 15, 27, 'denn »alles hat er ihm unter die Füße gelegt«. Wenn er dann aber aussprechen wird: »Alles ist unterworfen!«, so ist doch selbstverständlich der ausgenommen, der ihm alles unterworfen hat.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 15, 28, 'Sobald ihm aber alles unterworfen ist, dann wird auch der Sohn selbst sich dem unterwerfen, der ihm alles unterworfen hat, damit Gott (alsdann) alles sei in allen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 15, 29, 'Wie kämen sonst manche dazu, sich für die Toten taufen zu lassen? Wenn Tote überhaupt nicht auferweckt werden, wozu läßt man sich da noch für sie taufen?');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 15, 30, 'Und wir? Wozu setzen wir uns da Stunde für Stunde Gefahren aus?');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 15, 31, 'Tagtäglich sterbe ich, so wahr ihr, liebe Brüder, mein Ruhm seid, den ich in Christus Jesus, unserm Herrn, habe.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 15, 32, 'Wenn ich nach der Weise der Menschen in Ephesus mit wilden Tieren gekämpft habe, was hilft mir das? Wenn die Toten nicht auferweckt werden, so »laßt uns essen und trinken, denn morgen sind wir tot!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 15, 33, 'Laßt euch nicht irreführen! »Schlechter Umgang verderbt gute Sitten.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 15, 34, 'Werdet nüchtern, wie es sich gehört, und sündigt nicht; denn manchen fehlt die richtige Gotteserkenntnis: zur Beschämung muß ich euch das sagen!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 15, 35, '»Aber«, wird mancher fragen, »wie werden die Toten auferweckt, und mit was für einem Leibe erscheinen sie?«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 15, 36, 'Du Tor! Der Same, den du säst, bekommt doch auch nur dann Leben, wenn er (zuvor) erstorben ist;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 15, 37, 'und was du säen magst: du säst damit doch nicht schon den Leib, der erst noch entstehen wird, sondern ein nacktes Samenkorn, zum Beispiel von Weizen oder von sonst einem Gewächs.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 15, 38, 'Gott aber gibt ihm einen Leib nach seinem Belieben, und zwar einer jeden Samenart einen besonderen Leib.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 15, 39, 'Nicht jedes Fleisch hat die gleiche Beschaffenheit, sondern anders ist das Fleisch der Menschen beschaffen, anders das der vierfüßigen Tiere, anders das Fleisch der Vögel, anders das der Fische.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 15, 40, 'Auch gibt es himmlische Leiber und irdische Leiber; aber andersartig ist die Herrlichkeit der himmlischen, andersartig die (äußere Erscheinung) der irdischen Leiber.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 15, 41, 'Einen anderen Glanz hat die Sonne, einen anderen der Mond, und einen anderen Glanz haben die Sterne; denn jeder Stern ist von dem anderen an Glanz verschieden.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 15, 42, 'Ebenso verhält es sich auch mit der Auferstehung der Toten: Es wird gesät in Vergänglichkeit, auferweckt in Unvergänglichkeit;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 15, 43, 'es wird gesät in Unehre, auferweckt in Herrlichkeit; gesät wird in Schwachheit, auferweckt in Kraft;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 15, 44, 'gesät wird ein seelischer Leib, auferweckt ein geistlicher Leib. So gut es einen seelischen Leib gibt, so gibt es auch einen geistlichen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 15, 45, 'So steht auch geschrieben: »Der erste Mensch Adam wurde zu einem lebendigen Seelenwesen«, der letzte Adam zu einem lebenschaffenden Geisteswesen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 15, 46, 'Doch nicht das Geistliche kommt dabei zuerst, sondern das Seelische, danach erst das Geistliche.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 15, 47, 'Der erste Mensch ist von der Erde her, ist erdig, der zweite Mensch (nämlich Christus) ist himmlischen Ursprungs.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 15, 48, 'Wie der irdische Mensch (Adam) beschaffen ist, so sind auch die irdischen (Menschen) beschaffen; und wie der himmlische Mensch (Christus) beschaffen ist, so sind auch die himmlischen (Menschen) beschaffen;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 15, 49, 'und wie wir das Bild des irdischen (Adam) an uns getragen haben, so werden wir auch das Bild des himmlischen (Christus) an uns tragen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 15, 50, 'Das aber versichere ich (euch), liebe Brüder: Fleisch und Blut können das Reich Gottes nicht ererben; auch kann das Vergängliche nicht die Unvergänglichkeit ererben.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 15, 51, 'Seht, ich sage euch ein Geheimnis: Wir werden nicht alle entschlafen, wohl aber werden wir alle verwandelt werden,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 15, 52, '(und zwar) im Nu, in einem Augenblick, beim letzten Posaunenstoß; denn die Posaune wird erschallen, und sofort werden die Toten in Unvergänglichkeit auferweckt werden, und wir werden verwandelt werden.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 15, 53, 'Denn dieser vergängliche Leib muß die Unvergänglichkeit anziehen, und dieser sterbliche Leib muß die Unsterblichkeit anziehen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 15, 54, 'Wenn aber dieser vergängliche Leib die Unvergänglichkeit angezogen hat und dieser sterbliche Leib die Unsterblichkeit, dann wird sich das Wort erfüllen, das geschrieben steht: »Verschlungen ist der Tod in Sieg:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 15, 55, 'Tod, wo ist dein Sieg?');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 15, 56, 'Tod, wo ist dein Stachel?« Der Stachel des Todes ist aber die Sünde, und die Kraft der Sünde liegt im Gesetz.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 15, 57, 'Gott aber sei Dank, der uns den Sieg verleiht durch unsern Herrn Jesus Christus!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 15, 58, 'Daher, meine geliebten Brüder, werdet fest, unerschütterlich, und beteiligt euch allezeit eifrig am Werk des Herrn; ihr wißt ja, daß eure Arbeit nicht vergeblich ist im Herrn.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 16, 1, 'Was sodann die Sammlung für die Heiligen (in Jerusalem) betrifft, so haltet auch ihr es damit ebenso, wie ich es für die galatischen Gemeinden angeordnet habe:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 16, 2, 'Am ersten Tage jeder Woche lege jeder von euch (in seinem Hause) etwas beiseite und spare soviel zusammen, wie seine Verhältnisse es gestatten, damit die Sammlungen nicht erst nach meiner Ankunft stattzufinden brauchen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 16, 3, 'Wenn ich dann bei euch eingetroffen bin, werde ich die von euch bezeichneten Vertrauensmänner mit Briefen entsenden, damit sie eure Liebesgabe nach Jerusalem überbringen;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 16, 4, 'ist es aber der Mühe wert, daß auch ich hinreise, so sollen sie mit mir zusammen reisen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 16, 5, 'Ich werde aber zu euch kommen, wenn ich Mazedonien durchreist habe, denn Mazedonien durchreise ich nur,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 16, 6, 'bei euch aber werde ich wohl länger bleiben, vielleicht sogar den ganzen Winter zubringen, damit ihr mir dann bei meiner Weiterreise das Geleit geben könnt.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 16, 7, 'Ich möchte euch nämlich diesmal nicht nur auf der Durchreise sehen, sondern kann hoffentlich eine Zeitlang bei euch verweilen, wenn es des Herrn Wille ist.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 16, 8, 'Hier in Ephesus bleibe ich noch bis zum Pfingstfest,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 16, 9, 'denn es hat sich mir hier Gelegenheit zu vielseitiger und erfolgreicher Wirksamkeit geboten; freilich fehlt es auch nicht an Gegnern. –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 16, 10, 'Wenn aber Timotheus (zu euch) kommt, so sorgt dafür, daß er ohne Furcht bei euch verweilen kann; er arbeitet ja am Werk des Herrn ebenso wie ich.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 16, 11, 'Niemand möge ihn also über die Achsel ansehen! Entlaßt ihn dann in Frieden, damit er wieder zu mir komme; denn ich warte auf ihn samt den Brüdern. –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 16, 12, 'Was sodann den Bruder Apollos betrifft, so habe ich ihm dringend zugeredet, er möchte sich mit den Brüdern zu euch begeben; doch er will jetzt die Reise durchaus nicht unternehmen; er wird aber kommen, sobald es ihm gelegen ist.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 16, 13, 'Seid wachsam, steht fest im Glauben, seid mannhaft, werdet stark!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 16, 14, 'Laßt alles bei euch in Liebe zugehen! –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 16, 15, 'Ich habe euch noch auf eines aufmerksam zu machen, liebe Brüder: Ihr wißt vom Hause des Stephanas, daß er der erste gewesen ist, der in Achaja bekehrt worden ist und daß sie (er und die Seinen) sich in den Dienst für die Heiligen gestellt haben.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 16, 16, 'So ordnet denn auch ihr euch solchen Leuten unter und überhaupt einem jeden, der da mitarbeitet und sich abmüht!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 16, 17, 'Ich bin erfreut über die Ankunft des Stephanas, des Fortunatus und Achaikus: sie haben mir für euer Fernsein Ersatz geleistet');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 16, 18, 'und mir wie auch euch geistige Ruhe gebracht. Solchen Männern müßt ihr Anerkennung zollen!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 16, 19, 'Es grüßen euch die Gemeinden der Provinz Asien. Es grüßen euch herzlich im Herrn Aquila und Priska samt der Gemeinde in ihrem Hause.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 16, 20, 'Es grüßen euch die Brüder alle. Grüßt ihr einander mit dem heiligen Kuß.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 16, 21, 'Hier mein, des Paulus, eigenhändiger Gruß!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 16, 22, 'Wer den Herrn nicht liebt, der sei verflucht! Maranatha!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 16, 23, 'Die Gnade des Herrn Jesus sei mit euch!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 16, 24, 'Meine Liebe ist mit euch allen in Christus Jesus.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 1, 1, 'Ich, Paulus, ein Apostel Christi Jesu durch den Willen Gottes, und der Bruder Timotheus senden der Gemeinde Gottes in Korinth samt allen Heiligen in ganz Achaja unsern Gruß:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 1, 2, 'Gnade sei mit euch und Friede von Gott unserm Vater und dem Herrn Jesus Christus!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 1, 3, 'Gepriesen sei der Gott und Vater unsers Herrn Jesus Christus, der Vater der Barmherzigkeit und der Gott alles Trostes,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 1, 4, 'der uns in aller unserer Trübsal tröstet, damit wir dann (unserseits) alle, die sich in irgendeiner Trübsal befinden, mit dem Trost zu erquicken vermögen, mit dem wir selbst von Gott getröstet werden.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 1, 5, 'Denn wie die Leiden Christi sich überaus reichlich über uns ergießen, so ergießt sich durch Christus auch unser Trost überaus reichlich.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 1, 6, 'Werden wir nun (von Trübsal) bedrängt, so dient das zur Tröstung und zum Heil für euch; und empfangen wir Trost (von Gott), so dient das (gleichfalls) euch zum Trost, und dieser erweist sich dann wirksam in standhaftem Ertragen der gleichen Leiden, die auch wir durchzumachen haben;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 1, 7, 'und so steht unsere Hoffnung für euch unerschütterlich fest, weil wir wissen, daß ihr wie an den Leiden, so auch am Troste Anteil habt.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 1, 8, 'Wir möchten euch nämlich, liebe Brüder, über die Trübsal, die uns in der Provinz Asien betroffen hat, nicht in Unkenntnis lassen, daß nämlich das Leid so übergewaltig, so unerträglich schwer auf uns gelastet hat, daß wir sogar unser Leben verloren gaben;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 1, 9, 'ja, wir selber hatten es schon für ausgemacht gehalten, daß wir sterben müßten; wir sollten eben lernen, unser Vertrauen nicht auf uns selbst zu setzen, sondern auf den Gott, der die Toten auferweckt.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 1, 10, 'Er hat uns denn auch aus einer so großen Todesgefahr errettet und wird uns auch fernerhin erretten; auf ihn setzen wir unsere Hoffnung, daß er uns auch in Zukunft erretten wird,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 1, 11, 'wenn auch ihr mit eurer Fürbitte hilfreich für uns eintretet, damit aus dem Munde vieler (Anteilnehmenden) der uns zuteil gewordene Gnadenerweis durch viele auch die Dankesweihe im Hinblick auf uns erhalte.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 1, 12, 'Denn darin besteht unser Ruhm: in dem Zeugnis unsers Gewissens, daß wir in Sittenreinheit und Lauterkeit Gottes, nicht in fleischlicher Weisheit, sondern in der Gnade Gottes unsern Wandel in der Welt und ganz besonders euch gegenüber geführt haben.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 1, 13, 'Denn wir schreiben euch (in unsern Briefen) nichts anderes, als was ihr da lest und auch (daraus) versteht; ich hoffe aber, daß ihr es bis ans Ende verstehen werdet,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 1, 14, 'wie ihr uns ja, wenigstens zum Teil, schon verstanden habt, nämlich, daß wir euer Ruhm sind, ebenso wie ihr es für uns seid am Tage unsers Herrn Jesus.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 1, 15, 'Auf Grund dieser festen Überzeugung nun war ich willens, schon früher zu euch zu kommen, damit ihr eine zweite Freude erhieltet,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 1, 16, 'und über euer Korinth nach Mazedonien weiterzureisen; alsdann wollte ich von Mazedonien aus nochmals zu euch kommen und mir von euch das Geleit nach Judäa geben lassen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 1, 17, 'Habe ich mich nun etwa, wenn ich diese Absicht hatte, der Leichtfertigkeit schuldig gemacht? Oder sind meine Entschlüsse überhaupt Entschlüsse nach dem Fleisch, damit das »Ja ja« und das »Nein nein« mir (gleichzeitig) zur Verfügung stehe?');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 1, 18, 'Aber Gott ist Bürge dafür, daß unser Wort, das an euch ergeht, nicht Ja und Nein (zu gleicher Zeit) ist.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 1, 19, 'Denn Gottes Sohn Jesus Christus, der unter euch durch uns gepredigt worden ist, nämlich durch mich und Silvanus und Timotheus, ist auch nicht Ja und Nein (zugleich) gewesen, sondern in ihm ist das »Ja« geschehen;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 1, 20, 'denn für alle Verheißungen Gottes liegt in ihm das »Ja«; daher ist durch ihn auch das »Amen« erfolgt, Gott zur Verherrlichung durch uns.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 1, 21, 'Der uns aber samt euch auf Christus fest gründet und uns gesalbt hat, das ist Gott,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 1, 22, 'er, der uns auch sein Siegel aufgedrückt und uns den Geist als Unterpfand in unsere Herzen gegeben hat.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 1, 23, 'Meinerseits aber rufe ich Gott zum Zeugen gegen meine Seele an, daß ich (nur) aus Schonung für euch noch nicht wieder nach Korinth gekommen bin.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 1, 24, 'Nicht daß wir als die Herren über euren Glauben zu bestimmen hätten, nein, wir sind Mitarbeiter an eurer Freude; denn im Glauben steht ihr fest.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 2, 1, 'Ich habe aber aus Rücksicht auf mich selbst diesen Beschluß gefaßt, nicht nochmals zu euch zu kommen, wenn mein Besuch nur unter Betrübnis möglich ist.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 2, 2, 'Denn wenn ich euch in Betrübnis versetze – ja, wer ist dann da, der mich noch erfreuen könnte? Wer sonst als der, welcher von mir in Betrübnis versetzt wird?');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 2, 3, 'Und eben dies habe ich auch in meinem Briefe ausgesprochen, um nicht nach meiner Ankunft Betrübnis an denen zu erleben, von denen mir doch billigerweise Freude widerfahren müßte; ich darf ja doch zu euch allen das Vertrauen haben, daß meine Freude euer aller Freude ist.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 2, 4, 'Denn aus großer Bedrängnis und Herzensangst heraus habe ich euch unter vielen Tränen (meinen Brief) geschrieben, nicht damit ihr in Betrübnis versetzt würdet, sondern damit ihr die Liebe erkennen möchtet, die ich in besonders hohem Maße gerade zu euch habe.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 2, 5, 'Wenn aber jemand Betrübnis verursacht hat, so hat er nicht mich (persönlich) betrübt, sondern mehr oder weniger – damit ich ihn nicht zu schwer belaste – euch alle.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 2, 6, 'Für den Betreffenden genügt nun diese von der Mehrheit (der Gemeinde) ihm zuerkannte Strafe,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 2, 7, 'so daß ihr im Gegenteil ihm jetzt lieber verzeihen und Trost zusprechen solltet, damit der Betreffende nicht durch die übergroße Traurigkeit in Verzweiflung versetzt wird.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 2, 8, 'Deshalb empfehle ich euch, Liebe gegen ihn walten zu lassen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 2, 9, 'Denn ich habe mich ja bei meinem Schreiben auch von der Absicht leiten lassen, euch auf die Probe zu stellen, ob euer Gehorsam sich in allen Stücken bewähren würde.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 2, 10, 'Wem ihr aber eine Verfehlung verzeiht, dem verzeihe auch ich; denn auch ich habe das, was ich verziehen habe – wenn ich überhaupt etwas zu verzeihen hatte –, um euretwillen vor dem Angesicht Christi verziehen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 2, 11, 'Wir wollen uns doch nicht vom Satan überlisten lassen, dessen Gedanken uns ja wohlbekannt sind.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 2, 12, 'Als ich aber nach Troas gekommen war, um die Heilsbotschaft Christi zu verkünden, stand mir dort wohl eine Tür im Herrn offen,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 2, 13, 'aber ich kam doch innerlich zu keiner Ruhe, weil ich meinen Bruder Titus dort nicht antraf; ich nahm vielmehr Abschied von ihnen und zog weiter nach Mazedonien.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 2, 14, 'Gott aber sei gedankt, der uns in Christus allezeit (wie) in einem Triumphzug mit sich einherführt und den Wohlgeruch seiner Erkenntnis durch uns an allen Orten offenbart!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 2, 15, 'Denn ein Wohlgeruch Christi sind wir für Gott bei denen, die gerettet werden, und auch bei denen, die verlorengehen:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 2, 16, 'für die letzteren ein Geruch vom Tode her zum Tod, für die ersteren ein Geruch vom Leben her zum Leben. Und wer ist dazu tüchtig?');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 2, 17, 'Nun, wir machen es nicht wie so viele, die mit Gottes Wort hausieren gehen; nein, aus reinem Herzen, nein, auf Antrieb Gottes reden wir vor Gottes Angesicht in Christus.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 3, 1, 'Fangen wir schon wieder an, »uns selbst zu empfehlen«? Nein; oder haben wir etwa, wie gewisse Leute, Empfehlungsbriefe an euch oder von euch nötig?');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 3, 2, 'Nein, unser Empfehlungsbrief seid ihr: der ist uns ins Herz hineingeschrieben, der wird von aller Welt zur Kenntnis genommen und gelesen;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 3, 3, 'bei euch liegt es ja klar zutage, daß ihr ein Brief Christi seid, der von uns in seinem Dienst ausgefertigt ist, geschrieben nicht mit Tinte, sondern mit dem Geiste des lebendigen Gottes, nicht auf Tafeln von Stein, sondern auf Herzenstafeln von Fleisch.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 3, 4, 'Solche Zuversicht haben wir aber durch Christus zu Gott;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 3, 5, 'nicht als ob wir von uns selbst aus tüchtig wären, etwas auszudenken, als stamme es von uns selbst; nein, unsere Tüchtigkeit stammt von Gott.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 3, 6, 'Er ist es auch, der uns tüchtig gemacht hat zu Dienern des neuen Bundes, (der ein Bund) nicht des Buchstabens, sondern des Geistes (ist); denn der Buchstabe (des Gesetzes) tötet, der Geist aber macht lebendig.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 3, 7, 'Wenn nun aber (schon) der Dienst, der den Tod bringt, mit seiner auf Stein eingegrabenen Buchstabenschrift solche Herrlichkeit besaß, daß die Israeliten das Angesicht Moses nicht anzuschauen vermochten wegen des auf seinem Antlitz liegenden Glanzes, der doch wieder verschwand:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 3, 8, 'wie sollte da der Dienst des Geistes nicht eine noch weit größere Herrlichkeit besitzen?');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 3, 9, 'Denn wenn (schon) der Dienst, der die Verurteilung (zum Tode) bringt, Herrlichkeit besitzt, so muß der Dienst, der die Gerechtsprechung vermittelt, in noch viel höherem Grade überreich an Herrlichkeit sein;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 3, 10, 'ja, die auch dort vorhandene Herrlichkeit verschwindet in dieser Beziehung völlig gegenüber der überschwenglichen Herrlichkeit (dieses Dienstes).');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 3, 11, 'Denn wenn (schon) das Vergängliche Herrlichkeit besitzt, so muß das Bleibende in einer noch viel größeren Herrlichkeit dastehen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 3, 12, 'Weil wir nun eine solche Hoffnung haben, treten wir auch mit rückhaltlosem Freimut auf');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 3, 13, 'und (machen es) nicht wie Mose (,der) eine Decke auf sein Gesicht legte, damit die Israeliten nicht das Ende des verschwindenden (Glanzes) wahrnehmen könnten.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 3, 14, 'Indessen ihr geistliches Denken ist verhärtet worden; denn bis auf den heutigen Tag ist dieselbe Decke immer noch da, wenn die Schriften des alten Bundes vorgelesen werden, und wird nicht abgetan, weil sie nur in Christus weggenommen wird.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 3, 15, 'Ja, bis heute liegt, sooft Mose vorgelesen wird, eine Decke über ihrem Herzen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 3, 16, 'Sobald Israel sich aber zum Herrn bekehrt, wird die Decke weggezogen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 3, 17, 'Der Herr aber ist der Geist; wo aber der Geist des Herrn ist, da ist Freiheit.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 3, 18, 'Wir alle aber, die wir mit unverhülltem Angesicht die Herrlichkeit des Herrn widerspiegeln, werden dadurch in das gleiche Bild umgestaltet von Herrlichkeit zu Herrlichkeit, wie das vom Herrn des Geistes geschieht.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 4, 1, 'Deshalb werden wir, weil wir infolge des uns widerfahrenen (göttlichen) Erbarmens dieses Amt zu verwalten haben, nicht mutlos,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 4, 2, 'sondern haben uns von aller schändlichen Heimlichtuerei losgesagt; denn wir gehen nicht mit Arglist um, verfälschen auch das Wort Gottes nicht, empfehlen uns vielmehr durch die offene Verkündigung der Wahrheit jedem Gewissensurteil der Menschen vor den Augen Gottes.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 4, 3, 'Wenn trotzdem die von uns verkündigte Heilsbotschaft »verhüllt« ist, so ist sie doch nur bei denen verhüllt, welche verlorengehen,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 4, 4, 'weil in ihnen der Gott dieser Weltzeit das Denkvermögen der Ungläubigen verdunkelt hat, damit ihnen das helle Licht der Heilsbotschaft von der Herrlichkeit Christi, der das Ebenbild Gottes ist, nicht leuchte.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 4, 5, 'Denn nicht »uns selbst« verkündigen wir, sondern Christus Jesus als den Herrn, uns selbst aber als eure Knechte um Jesu willen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 4, 6, 'Denn Gott, der da geboten hat: »Aus der Finsternis strahle das Licht hervor!«, der ist es auch, der das Licht in unsern Herzen hat aufstrahlen lassen, um (uns) die Erkenntnis der Herrlichkeit Gottes im Angesicht Christi erglänzen zu lassen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 4, 7, 'Wir besitzen aber diesen Schatz in irdenen Gefäßen, damit die überschwengliche (Fülle der) Kraft sich als Gott angehörend und nicht als von uns stammend erweise.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 4, 8, 'Allenthalben sind wir bedrängt, aber nicht erdrückt, in Ratlosigkeit versetzt, aber nicht in Verzagtheit,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 4, 9, 'verfolgt, aber nicht im Stich gelassen, zu Boden niedergeworfen, aber nicht ums Leben gebracht;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 4, 10, 'allezeit tragen wir das Sterben Jesu an unserm Leibe mit uns umher, damit auch das Leben Jesu an unserm Leibe sichtbar werde.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 4, 11, 'Denn immerfort werden wir mitten im Leben in den Tod dahingegeben um Jesu willen, damit auch das Leben Jesu an unserm sterblichen Fleische sichtbar werde.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 4, 12, 'Somit tut der Tod sein Werk in uns, das Leben aber in euch.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 4, 13, 'Weil wir aber denselben Geist des Glaubens besitzen – nach dem Wort der Schrift: »Ich habe geglaubt, darum habe ich geredet« –, so glauben auch wir und deshalb reden wir auch;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 4, 14, 'denn wir wissen, daß der, welcher den Herrn Jesus auferweckt hat, auch uns mit Jesus auferwecken und uns mit euch zusammen (vor ihm, d.h. vor dem Richterstuhl Christi) darstellen wird.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 4, 15, 'Denn das alles geschieht um euretwillen, damit die Gnade, gemehrt durch immer weiteren Zuwachs (der Begnadeten), die Danksagung in immer stärkerem Strom sich ergießen lasse zur Ehre Gottes.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 4, 16, 'Darum werden wir auch nicht verzagt; nein, wenn auch unser äußerer Mensch aufgerieben wird, so empfängt doch unser innerer Mensch Tag für Tag neue Kraft.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 4, 17, 'Denn die augenblickliche, leicht wiegende Last unserer Leiden bringt uns in überschwenglicher Weise über alles Maß hinaus ein ewiges Vollgewicht von Herrlichkeit ein,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 4, 18, 'weil wir den Blick nicht auf das Sichtbare, sondern auf das Unsichtbare richten; denn das Sichtbare ist zeitlich, das Unsichtbare aber bleibt ewig.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 5, 1, 'Wir wissen ja, daß, wenn unser irdisches Haus, das Leibeszelt, abgebrochen sein wird, wir einen von Gott bereiteten Bau erhalten, ein nicht von Menschenhänden hergestelltes, ewiges Haus im Himmel.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 5, 2, 'In diesem (gegenwärtigen) Zustande seufzen wir ja auch, weil wir danach verlangen, mit unserer himmlischen Behausung überkleidet zu werden,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 5, 3, 'da wir ja (erst dann), wenn wir diese angelegt haben, nicht unbekleidet werden erfunden werden.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 5, 4, 'Denn solange wir uns noch in dem Leibeszelte (hier) befinden, haben wir zu seufzen und fühlen uns bedrückt, weil wir lieber nicht erst entkleidet, sondern (sogleich) überkleidet werden möchten, damit das Sterbliche vom Leben verschlungen werde.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 5, 5, 'Der uns aber eben dafür zubereitet hat, das ist Gott, der uns den Geist als Unterpfand gegeben hat.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 5, 6, 'So haben wir denn allezeit guten Mut, und da wir wissen, daß, solange wir unsere Heimat im Leibe haben, wir fern vom Herrn in der Fremde leben');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 5, 7, '– denn wir wandeln (hier noch) in (der Welt des) Glaubens, nicht schon in (der Welt des) Schauens –,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 5, 8, 'so haben wir guten Mut, möchten jedoch lieber aus dem Leibe auswandern und in die Heimat zum Herrn kommen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 5, 9, 'Darum bieten wir auch allen Eifer auf, mögen wir uns (schon) in der Heimat oder noch in der Fremde befinden, ihm wohlgefällig zu sein.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 5, 10, 'Denn wir müssen alle vor dem Richterstuhl Christi offenbar werden, damit ein jeder (seinen Lohn) empfange, je nachdem er während seines leiblichen Lebens gehandelt hat, es sei gut oder böse.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 5, 11, 'Weil wir also die Furcht vor dem Herrn kennen, suchen wir »Menschen zu gewinnen«, für Gott aber sind wir offenbar; doch hoffe ich, auch in euren Gewissen offenbar zu sein.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 5, 12, 'Wir bringen uns damit nicht schon wieder bei euch in Empfehlung, sondern wollen euch einen Anlaß zum Ruhmeszeugnis für uns geben, damit ihr denen zu antworten wißt, die sich nur äußerer Vorzüge, nicht aber ihrer Herzensverfassung rühmen können.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 5, 13, 'Denn »sind wir um den Verstand gekommen«, so ist es für Gott geschehen, und »sind wir bei gesundem Verstande«, so (sind wir’s) zum Segen für euch.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 5, 14, 'Denn die Liebe Christi drängt uns, weil wir uns von der Überzeugung leiten lassen: Einer ist für alle gestorben, folglich sind sie allesamt gestorben;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 5, 15, 'und er ist darum für alle gestorben, damit die, welche leben, nicht mehr sich selbst leben, sondern dem, der für sie gestorben und auferweckt ist.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 5, 16, 'Daher kennen wir von jetzt ab niemand mehr nach dem Fleisch; nein, sogar wenn wir (früher) Christus nach dem Fleisch gekannt haben, so kennen wir ihn doch jetzt nicht mehr so.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 5, 17, 'Wenn also jemand in Christus ist, so ist er eine neue Schöpfung: das Alte ist vergangen, siehe, ein Neues ist entstanden!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 5, 18, 'Das alles ist aber das Werk Gottes, der uns durch Christus mit sich versöhnt hat und uns (Aposteln) den Dienst der Versöhnung übertragen hat.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 5, 19, 'Denn (so steht es:) Gott war in Christus und hat die Welt mit sich versöhnt, indem er ihnen ihre Übertretungen nicht anrechnete und in uns das Wort von der Versöhnung niedergelegt hat.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 5, 20, 'Für Christus also reden wir als seine Gesandten, da ja Gott durch uns ermahnt; wir bitten für Christus: »Laßt euch mit Gott versöhnen!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 5, 21, 'Er hat den, der Sünde nicht kannte, für uns zur Sünde gemacht, damit wir in ihm Gottes Gerechtigkeit würden.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 6, 1, 'Als (Gottes) Mitarbeiter aber ermahnen wir euch auch: (Seid darauf bedacht) die Gnade Gottes nicht vergeblich anzunehmen! –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 6, 2, 'Es steht ja geschrieben: »Zur willkommenen Zeit habe ich dich erhört und am Tage des Heils dir geholfen.« Seht, jetzt ist die hochwillkommene Zeit, seht, jetzt ist der Tag des Heils!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 6, 3, 'Und dabei geben wir niemand irgendwelchen Anstoß, damit kein Tadel unsern Dienst treffe;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 6, 4, 'vielmehr suchen wir uns in jeder Hinsicht als Diener Gottes zu empfehlen: durch große Standhaftigkeit in Leiden, in Nöten, in Bedrängnissen,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 6, 5, 'bei Schlägen, bei Gefangenschaften, bei Volksaufständen, in Mühsalen, in durchwachten Nächten, bei Mangel an Nahrung,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 6, 6, 'in Sittenreinheit, durch Erkenntnis, durch Langmut, durch Gütigkeit, durch heiligen Geist, durch ungeheuchelte Liebe,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 6, 7, 'im Wort der Wahrheit, durch die Kraft Gottes, durch die Waffen der Gerechtigkeit zur Rechten und zur Linken,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 6, 8, 'unter Ehre und Schande, bei übler und guter Nachrede, als wären wir Verführer und doch wahrhaftig,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 6, 9, 'als die Unbekannten und doch wohlbekannt, als die Sterbenden und seht, wir leben; als die Gezüchtigten und doch nicht zu Tode gepeinigt,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 6, 10, 'als die Leidtragenden, aber doch allezeit Fröhlichen, als Bettler, die aber viele reich machen; als solche, die nichts haben und doch alles besitzen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 6, 11, 'Liebe Korinther! Unser Mund hat sich euch gegenüber aufgetan, das Herz ist uns weit geworden!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 6, 12, 'Ihr nehmt in unserm Herzen keinen engen Raum ein, aber eng ist der Raum in eurem Inneren (für uns)!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 6, 13, 'So vergeltet (uns) nun Gleiches mit Gleichem – ich rede zu euch wie zu Kindern –: laßt auch eure Herzen sich weit erschließen!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 6, 14, 'Gebt euch nicht dazu her, mit Ungläubigen an einem fremdartigen Joch zu ziehen! Denn was haben Gerechtigkeit und Gesetzlosigkeit miteinander gemein? Oder was hat das Licht mit der Finsternis zu schaffen?');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 6, 15, 'Wie stimmt Christus mit Beliar überein, oder welche Gemeinschaft besteht zwischen einem Gläubigen und einem Ungläubigen?');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 6, 16, 'Wie verträgt sich der Tempel Gottes mit den Götzen? Wir sind ja doch der Tempel des lebendigen Gottes, wie Gott gesagt hat: »Ich werde unter ihnen wohnen und wandeln; ich will ihr Gott sein, und sie sollen mein Volk sein.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 6, 17, 'Darum: »Geht aus ihrer Mitte hinweg und sondert euch (von ihnen) ab«, gebietet der Herr, »und rührt nichts Unreines an, so will ich euch aufnehmen« und:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 6, 18, '»Ich will euch ein Vater sein, und ihr sollt mir Söhne und Töchter sein«, sagt der Herr, der Allmächtige.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 7, 1, 'Da wir nun solche Verheißungen haben, Geliebte, wollen wir uns von jeder Befleckung des Fleisches und des Geistes reinigen und völlige Heiligung bei uns schaffen in der Furcht Gottes!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 7, 2, 'Lasset uns Eingang (in eure Herzen) finden! Wir haben niemand (von euch) unrecht getan, niemand zugrunde gerichtet, niemand übervorteilt.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 7, 3, 'Ich sage das nicht, um eine Verurteilung auszusprechen; ich habe euch ja vorhin schon erklärt, daß wir euch in unserm Herzen tragen, um zusammen mit euch zu sterben und zusammen zu leben.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 7, 4, 'Ich spreche mich mit voller Offenheit euch gegenüber aus, ich bin voll Rühmens über euch, habe Trost in Fülle und bin überreich an Freude bei aller meiner Trübsal.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 7, 5, 'Denn auch nach unserer Ankunft in Mazedonien fanden wir durchaus keine leibliche Ruhe, sondern überall gab es Bedrängnis; von außen Kämpfe, im Inneren Ängste.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 7, 6, 'Aber Gott, der die Gebeugten tröstet, hat auch uns getröstet durch die Ankunft des Titus,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 7, 7, 'und zwar nicht nur durch seine Ankunft, sondern auch durch den Trost, den er bei euch gefunden hatte; denn er berichtete uns von eurer Sehnsucht nach mir, von euren Klagen, von eurem Eifer für mich, so daß meine Freude noch größer wurde.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 7, 8, 'Denn wenn ich euch auch durch meinen (vorigen) Brief betrübt habe, so tut das mir doch nicht leid. Wenn es mir (früher) auch leid getan hat – ich sehe ja, daß jener Brief euch, wenn auch nur vorübergehend, betrübt hat –,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 7, 9, 'so freue ich mich doch jetzt, allerdings nicht darüber, daß ihr in Betrübnis versetzt worden seid, wohl aber darüber, daß ihr durch die Betrübnis zur Reue geführt worden seid; denn eure Betrübnis ist so gewesen, wie Gott sie haben will, damit ihr von unserer Seite in keiner Weise Schaden erlittet.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 7, 10, 'Denn die Betrübnis, wie Gott sie haben will, wirkt eine Reue zum Heil, die niemand (später) zu bereuen hat; die Betrübnis der Welt dagegen wirkt den Tod.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 7, 11, 'Denn seht doch: eben diese eure gottwohlgefällige Betrübnis – welche Bereitwilligkeit hat sie bei euch gewirkt, ja noch mehr: Entschuldigung, Unwillen, Furcht, Sehnsucht, Eifer, Bestrafung (des Schuldigen)! In jeder Beziehung habt ihr bewiesen, daß ihr in der (bewußten) Sache vorwurfsfrei dasteht.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 7, 12, 'Darum, wenn ich euch auch geschrieben habe, so (habe ich es) doch nicht wegen des Beleidigers und auch nicht wegen des Beleidigten (getan), sondern zu dem Zweck, daß euer Eifer für uns bei euch vor Gottes Angesicht offenbar würde. Dadurch haben wir Trost gefunden.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 7, 13, 'Zu diesem unserm Trost kam aber noch ein außerordentlicher Zuwachs an Freude hinzu im Hinblick auf die Freude des Titus, weil ihm eine geistige Erquickung von euch allen zuteil geworden ist.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 7, 14, 'Denn wenn ich mich (früher) ihm gegenüber mehrfach rühmend über euch ausgesprochen hatte, so habe ich nun damit keine Enttäuschung erlebt; vielmehr, wie alles, was ich zu euch geredet habe, wahr gewesen ist, so hat sich nun auch mein Rühmen dem Titus gegenüber als Wahrheit erwiesen;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 7, 15, 'und sein Herz ist euch (jetzt) noch hingebender zugewandt, weil er an euer aller Gehorsam zurückdenkt, wie ihr ihn mit Furcht und Zittern aufgenommen habt.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 7, 16, 'Ich freue mich, daß ich mich in jeder Beziehung auf euch verlassen kann!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 8, 1, 'Wir können euch nun auch, liebe Brüder, Mitteilung von der Gnade Gottes machen, die (den Brüdern) in den mazedonischen Gemeinden verliehen worden ist,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 8, 2, 'daß nämlich trotz schwerer Leidensprüfung die überschwengliche Fülle ihrer Freude und ihre abgrundtiefe Armut sich in den reichen Erweis ihrer Mildtätigkeit ergossen haben.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 8, 3, 'Denn nach Vermögen, ich bezeuge es ihnen, ja über Vermögen haben sie aus eigenem Antrieb gespendet,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 8, 4, 'indem sie uns inständig um die Vergünstigung baten, sich an dem Liebeswerk für die Heiligen (in Jerusalem) beteiligen zu dürfen;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 8, 5, 'und sie haben dann nicht nur, wie wir gehofft hatten, (gespendet,) nein, sie haben geradezu sich selbst hingegeben, in erster Linie dem Herrn und (dann) auch uns nach Gottes Willen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 8, 6, 'Wir haben daher dem Titus zugeredet, er möchte, wie er schon früher damit begonnen habe, so dieses Liebeswerk bei euch jetzt auch zum Abschluß bringen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 8, 7, 'Aber wie ihr euch in allen Beziehungen hervortut, durch Glauben und Redegabe, durch Erkenntnis und Eifer in jeder Hinsicht und durch die Liebe, die von uns her in euch (geweckt oder: wirksam ist), so tut euch nun auch bei diesem Liebeswerk durch reiche Betätigung hervor!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 8, 8, 'Ich sage das nicht als einen Befehl, nein, ich möchte am Eifer der anderen die Echtheit auch eurer Liebe erproben.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 8, 9, 'Ihr kennt ja die Gnade unsers Herrn Jesus Christus, daß er, obschon er reich war, doch um euretwillen arm geworden ist, damit ihr durch seine Armut reich würdet.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 8, 10, 'Nur einen Rat will ich euch hierbei geben, nämlich: dieses ist für euch selbst rätlich, weil ihr ja schon seit vorigem Jahr nicht nur mit der Ausführung (der Sammlung), sondern auch mit dem Entschluß dazu den anderen vorangegangen seid.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 8, 11, 'So bringt denn jetzt auch das begonnene Werk zum Abschluß, damit, wie der gute Wille vorhanden ist, so auch die Ausführung dem Maße eures Vermögens entspricht.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 8, 12, 'Denn wenn der gute Wille vorhanden ist, so ist er wohlgefällig nach dem Maß dessen, was einer hat, nicht nach dem Maß dessen, was er nicht hat.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 8, 13, 'Denn nicht soll anderen eine Entlastung, euch selbst aber eine Belastung geschaffen werden; nein, des Ausgleichs wegen');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 8, 14, 'soll diesmal euer Überfluß dem Mangel jener abhelfen, damit (ein andermal) der Überfluß jener eurem Mangel zugute komme und so ein Ausgleich stattfinde,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 8, 15, 'wie geschrieben steht: »Wer viel (Manna gesammelt) hatte, besaß doch keinen Überschuß, und wer nur wenig besaß, hatte keinen Mangel.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 8, 16, 'Dank aber sei Gott, der dem Titus den gleichen Eifer für euch ins Herz legt (wie mir)!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 8, 17, 'Denn er hat unserer Aufforderung (euch zu besuchen) bereitwillig Gehör geschenkt, ist aber, weil sein Eifer noch größer ist, aus freiem Entschluß zu euch abgereist.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 8, 18, 'Wir haben ihm aber den Bruder mitgegeben, dessen Lob bezüglich der (Verkündigung der) Heilsbotschaft durch alle Gemeinden verbreitet ist.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 8, 19, 'Aber davon abgesehen ist er auch von den Gemeinden zu unserm Reisegefährten bei der Überbringung dieser Liebesgabe gewählt worden, die von uns ins Werk gesetzt wird zur Ehre des Herrn selbst und zum Erweis unsers guten Willens;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 8, 20, 'denn dadurch verhüten wir den Übelstand, daß jemand uns verdächtigt um dieser reichen Spende willen, die durch unsern Dienst vermittelt wird.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 8, 21, 'Wir sind ja darauf bedacht, daß alles löblich dabei zugehe, nicht nur vor dem Herrn, sondern auch vor den Menschen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 8, 22, 'Wir haben aber mit jenen beiden zusammen auch noch unsern Bruder gesandt, dessen Eifer wir schon oftmals bei vielen Gelegenheiten erprobt haben, der jetzt aber bei seinem vollen Vertrauen zu euch noch viel eifriger ist.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 8, 23, 'Wenn ich hier für Titus eintrete, so geschieht es, weil er mein Genosse und in bezug auf euch mein Mitarbeiter ist; und was unsere (beiden anderen) Brüder betrifft, so sind sie Abgeordnete von Gemeinden, ein Abglanz Christi.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 8, 24, 'Erweist ihnen also eure Liebe und liefert den Gemeinden den offenkundigen Beweis, daß ihr unser Rühmen ihnen gegenüber wirklich verdient habt.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 9, 1, 'Denn in betreff der Liebesgabe selbst, die für die Heiligen bestimmt ist, brauche ich euch nicht weiter zu schreiben;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 9, 2, 'ich kenne ja eure Bereitwilligkeit, von der ich den Mazedoniern gegenüber zu eurer Empfehlung rühmend hervorhebe, daß Achaja schon seit vorigem Jahre in Bereitschaft sei; und euer Eifer hat die meisten von ihnen angespornt.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 9, 3, 'Die Brüder aber habe ich deshalb abgesandt, damit das Lob, das wir euch erteilt haben, sich in diesem Punkte nicht als unberechtigt erweist, damit ihr vielmehr, wie ich angegeben habe, wirklich in Bereitschaft seid.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 9, 4, 'Ich möchte nicht, daß, wenn Mazedonier mit mir (nach Korinth) kommen und euch noch nicht fertig finden, wir – um nicht zu sagen »ihr« – mit dieser zuversichtlichen Versicherung beschämt dastehen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 9, 5, 'Deshalb habe ich es für erforderlich gehalten, den Brüdern zuzureden, zu euch vorauszureisen und die von euch früher angekündigte Segensgabe schon vorher fertigzustellen, damit diese dann wirklich als ein Segen bereitliegt und nicht nach Geiz aussieht.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 9, 6, 'Ich meine das aber so: Wer kärglich sät, der wird auch kärglich ernten, und wer reichlich sät, der wird auch reichlich ernten.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 9, 7, 'Jeder (gebe), wie er es sich im Herzen vorgenommen hat, nicht mit Unlust oder aus Zwang; denn (nur) »einen freudigen Geber hat Gott lieb«.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 9, 8, 'Gott hat aber die Macht, euch mit jeglicher Gnadengabe reichlich zu segnen, auf daß ihr allezeit in jeder Hinsicht vollauf genug habt und (außerdem noch) reiche Mittel besitzt zu guten Werken jeder Art,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 9, 9, 'wie geschrieben steht: »Er hat reichlich ausgeteilt, hat den Armen gespendet; seine Gerechtigkeit bleibt ewig bestehen.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 9, 10, 'Er aber, der dem Sämann Samen darreicht und Brot zur Speise, der wird auch euch die (Mittel zur) Aussaat darreichen und mehren und die Früchte eurer Gerechtigkeit wachsen lassen,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 9, 11, 'so daß ihr mit allem reichlich ausgestattet werdet zur Erweisung jeder Mildtätigkeit, welche durch unsere Vermittlung die Danksagung (der Empfänger) gegen Gott bewirkt.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 9, 12, 'Denn der durch diese Liebesgabe geleistete Dienst hilft nicht nur dem Mangel der Heiligen ab, sondern schafft auch reichen Segen durch viele an Gott gerichtete Dankgebete.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 9, 13, 'Jene werden ja infolge eurer Bewährung bei diesem Liebeswerk Gott dafür preisen, daß ihr in eurem Bekenntnis zu der Heilsbotschaft Christi Gehorsam und in der Teilnahme für sie und für alle (anderen) Aufrichtigkeit bewiesen habt.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 9, 14, 'Dabei werden sie auch im Gebet für euch ihrer Sehnsucht nach euch Ausdruck geben wegen der Gnade Gottes, die sich überreich an euch erweist.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 9, 15, 'Dank sei Gott für seine unaussprechlich reiche Gabe!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 10, 1, 'Persönlich aber ermahne ich, Paulus, euch mit dem Hinweis auf die Sanftmut und Milde Christi, ich, der ich (angeblich) »Auge in Auge zwar demütig bei euch bin, aus der Ferne aber mich selbstbewußt gegen euch zeige«.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 10, 2, 'Ich bitte (euch) nur: (Zwingt mich nicht dazu) bei meiner Anwesenheit Selbstbewußtsein beweisen zu müssen in der Zuversicht, die ich mir gegen gewisse Leute herauszunehmen gedenke, die da von uns die Meinung haben, daß »wir einen Wandel nach dem Fleische führen«.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 10, 3, 'Ja, wir wandeln wohl im Fleische, führen aber unsern Kampf nicht nach Fleischesart;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 10, 4, 'denn die Waffen, mit denen wir kämpfen, sind nicht fleischlicher Art, sondern starke Gotteswaffen zur Zerstörung von Bollwerken: wir zerstören mit ihnen klug ausgedachte Anschläge');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 10, 5, 'und jede hohe Burg, die sich gegen die Erkenntnis Gottes erhebt, und nehmen alles Sinnen in den Gehorsam gegen Christus gefangen');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 10, 6, 'und halten uns bereit, jeden Ungehorsam zu bestrafen, sobald nur erst euer Gehorsam völlig wiederhergestellt ist.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 10, 7, 'Sehet doch auf das, was vor Augen liegt! Wenn jemand von sich selbst die feste Überzeugung hat, daß er für seine Person Christus angehört, so möge er andererseits auch dies bei sich bedenken, daß ebenso gut wie er selbst auch wir Christus angehören.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 10, 8, 'Ja, wenn ich mich noch etwas stärker bezüglich meiner Befugnis rühmen wollte, die der Herr mir zu eurer »Auferbauung«, nicht zu eurer »Zerstörung« verliehen hat, so würde ich damit nicht zuschanden werden,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 10, 9, 'und es würde sich nicht herausstellen, daß ich euch durch meine Briefe gewissermaßen einzuschüchtern suche.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 10, 10, 'Denn »seine Briefe«, sagt man, »sind allerdings wuchtig und kraftvoll, aber sein persönliches Auftreten ist schwächlich, und reden kann er gar nicht«.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 10, 11, 'Wer so redet, möge sich folgendes gesagt sein lassen: Wie wir uns aus der Ferne brieflich mit Worten zeigen, ebenso werden wir uns auch bei unserer Anwesenheit mit der Tat beweisen!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 10, 12, 'Wir nehmen uns allerdings nicht heraus, uns mit gewissen Leuten unter denen, die sich selbst empfehlen, auf eine Stufe zu stellen oder uns mit ihnen zu vergleichen; nein, sie sind unverständig genug, sich an sich selbst zu messen und sich mit sich selbst zu vergleichen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 10, 13, 'Wir dagegen wollen uns nicht ins Maßlose rühmen, sondern nach dem Maße des Arbeitsfeldes, das Gott uns als Maßstab zugewiesen hat, daß wir nämlich auch bis zu euch gelangen sollten.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 10, 14, 'Denn wir strecken uns nicht über Gebühr aus, als reichten wir nicht bis zu euch hin; wir sind ja doch tatsächlich mit der (Verkündung der) Heilsbotschaft Christi auch bis zu euch hingelangt.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 10, 15, 'Und dabei rühmen wir uns nicht maßlos aufgrund fremder Arbeitsleistungen, hegen aber die Hoffnung, beim Wachstum eures Glaubens dem uns zugewiesenen Wirkungsgebiet entsprechend bei euch noch ungleich größer dazustehen,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 10, 16, 'wenn wir die Heilsbotschaft noch in die über eure Grenzen hinausliegenden Länder tragen, ohne uns dabei auf fremdem Arbeitsfelde dessen zu rühmen, was (dort schon von anderen) fertiggestellt ist.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 10, 17, 'Nein, »wer sich rühmen will, der rühme sich des Herrn«;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 10, 18, 'denn nicht wer sich selbst empfiehlt, ist bewährt, sondern der, den der Herr empfiehlt.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 11, 1, 'Möchtet ihr euch doch ein klein wenig Torheit von mir gefallen lassen! Nicht wahr? Ihr laßt sie euch auch von mir gefallen;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 11, 2, 'denn ich eifere um euch mit göttlichem Eifer; ich habe euch ja einem einzigen Manne verlobt, um euch Christus als eine reine Jungfrau zuzuführen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 11, 3, 'Ich fürchte aber, daß, wie die Schlange einst Eva mit ihrer Arglist verführt hat, so auch eure Gedanken von der Einfalt und lauteren Gesinnung gegen Christus zum Argen hingezogen werden.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 11, 4, 'Denn wenn irgend jemand daherkommt und euch einen anderen Jesus verkündigt, den wir nicht verkündigt haben, oder wenn ihr einen andersartigen Geist empfangt, den ihr (durch uns) nicht empfangen habt, oder eine andersartige Heilsbotschaft, die ihr (durch uns) nicht erhalten habt, so laßt ihr euch das bestens gefallen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 11, 5, 'Ich denke doch, in keiner Beziehung hinter den »unvergleichlichen« Aposteln zurückgeblieben zu sein.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 11, 6, 'Denn mag ich auch im Reden ungeschult sein, so bin ich es doch nicht in der Erkenntnis, die wir ja doch in jeder Hinsicht euch gegenüber bei allen erwiesen haben.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 11, 7, 'Oder habe ich etwa dadurch eine Sünde begangen, daß ich mich selbst erniedrigt habe, damit ihr erhöht würdet, insofern ich euch die Heilsbotschaft Gottes ohne Entgelt getreulich verkündigt habe?');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 11, 8, 'Andere Gemeinden habe ich ausgebeutet, indem ich Belohnung von ihnen genommen habe, um euch zu dienen;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 11, 9, 'und während meines Aufenthalts bei euch bin ich, auch als ich Mangel litt, doch keinem zur Last gefallen; denn meinem Mangel haben die Brüder abgeholfen, die damals aus Mazedonien gekommen waren; und in jeder Beziehung habe ich mich so gehalten, daß ich euch nicht beschwerlich gefallen bin, und werde es auch (in Zukunft) so halten.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 11, 10, 'So gewiß die Wahrhaftigkeit Christi in mir wohnt: dieser Ruhm soll mir in den Gebieten von Achaja nicht verkümmert werden!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 11, 11, 'Warum das? Etwa weil ich keine Liebe zu euch habe? Das weiß Gott.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 11, 12, 'Doch was ich (jetzt) tue, werde ich auch (fernerhin) tun, um denen, die gern eine Möglichkeit haben möchten, bei ihrem Rühmen ebenso erfunden zu werden wie ich, diese Möglichkeit abzuschneiden.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 11, 13, 'Denn diese Leute sind Lügenapostel, unredliche Arbeiter, die nur die Maske von Aposteln Christi tragen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 11, 14, 'Und das ist kein Wunder, denn der Satan selbst nimmt ja das Aussehen eines Lichtengels an.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 11, 15, 'Da ist es denn nichts Verwunderliches, wenn auch seine Diener mit der Maske von Dienern der Gerechtigkeit auftreten. Doch ihr Ende wird ihrem ganzen Tun entsprechen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 11, 16, 'Nochmals wiederhole ich es: Niemand möge mich für einen (wirklichen) Toren halten! Wenn aber doch – nun, so laßt euch meine Torheit einmal gefallen, damit auch ich ein kleines Loblied von mir anstimme!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 11, 17, 'Was ich (jetzt) rede, das rede ich nicht im Sinne des Herrn, sondern eben in Torheit, weil das Rühmen nun einmal an der Tagesordnung ist.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 11, 18, 'Weil so viele sich nach dem Fleische rühmen, will auch ich es einmal tun.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 11, 19, 'Ihr laßt euch ja die Toren gern gefallen, ihr klugen Leute;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 11, 20, 'ihr haltet ja still, wenn man euch als Knechte behandelt, wenn man euch aufzehrt, euch listig einfängt, wenn man selbstbewußt auftritt, ja euch ins Gesicht schlägt.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 11, 21, 'Zu meiner Schande muß ich gestehen: Dazu sind wir freilich zu schwach gewesen. Worauf sich aber sonst jemand ohne Scheu etwas einbildet – ich rede in Torheit –, darauf kann auch ich es mir ohne Scheu herausnehmen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 11, 22, 'Sie sind Hebräer? Ich auch. Sie sind Israeliten? Ich auch. Sie sind Nachkommen Abrahams? Ich auch.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 11, 23, 'Sie sind Diener Christi? Ich rede im Aberwitz: Ich bin’s noch mehr: In mühevollen Arbeiten überreichlich, in Gefangenschaften überreichlich, unter Schlägen mehr als genug, in Todesgefahren gar oft;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 11, 24, 'von Juden habe ich fünfmal die vierzig (Geißelhiebe) weniger einen erhalten;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 11, 25, 'dreimal bin ich ausgepeitscht, einmal gesteinigt worden; dreimal habe ich Schiffbruch gelitten, einen Tag und eine Nacht bin ich ein Spielball der Wellen gewesen;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 11, 26, 'wie viele beschwerliche Fußwanderungen habe ich gemacht, wie viele Gefahren bestanden durch Flüsse, Gefahren durch Räuber, Gefahren durch meine eigenen Volksgenossen, Gefahren durch Heiden, Gefahren in Städten, Gefahren in Einöden, Gefahren auf dem Meer, Gefahren unter falschen Brüdern!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 11, 27, 'Wie oft habe ich Mühsale und Beschwerden bestanden, wie oft durchwachte Nächte, Hunger und Durst, wie oft Entbehrungen (jeder Art), Kälte und Mangel an Kleidung!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 11, 28, 'Dazu – abgesehen von allem Außergewöhnlichen – das Überlaufenwerden tagaus tagein, die Sorge für alle (meine) Gemeinden!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 11, 29, 'Wo ist jemand schwach (in seinem Glaubensleben), und ich wäre nicht auch schwach? Wo wird jemandem Anstoß bereitet, ohne daß ich brennenden Schmerz empfände?');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 11, 30, 'Wenn einmal gerühmt sein muß, so will ich mich der Erweisungen meiner Schwachheit rühmen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 11, 31, 'Der Gott und Vater des Herrn Jesus, der in alle Ewigkeit Hochgelobte, weiß, daß ich nicht lüge.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 11, 32, 'In Damaskus hat der Statthalter des Königs Aretas die Stadt (Damaskus) bewachen lassen, um mich festzunehmen;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 11, 33, 'da hat man mich durch eine Öffnung in einem Korbe über die Stadtmauer hinabgelassen, und so bin ich seinen Händen entronnen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 12, 1, 'Gerühmt muß sein; es ist zwar nicht heilsam, aber ich will doch auf die Gesichte und Offenbarungen des Herrn zu sprechen kommen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 12, 2, 'Ich weiß von einem Menschen in Christus, daß er vor vierzehn Jahren bis zum dritten Himmel entrückt wurde; ob er dabei im Leibe gewesen ist, weiß ich nicht, ob außerhalb des Leibes, weiß ich auch nicht, Gott weiß es.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 12, 3, 'Und ich weiß von dem betreffenden Menschen – ob er im Leibe oder ohne den Leib gewesen ist, weiß ich nicht, Gott weiß es –,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 12, 4, 'daß er in das Paradies entrückt wurde und unsagbare Worte hörte, die ein Mensch nicht aussprechen darf.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 12, 5, 'Als ein solcher Mensch will ich mich rühmen, in bezug auf mich selbst aber will ich mich nicht rühmen als nur wegen der Schwachheiten.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 12, 6, 'Wenn ich mich nämlich wirklich entschlösse, mich zu rühmen, wäre ich deshalb kein Tor, denn ich würde die Wahrheit sagen; doch ich unterlasse es, damit niemand höher von mir denke als dem entsprechend, was er an mir sieht oder von mir hört,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 12, 7, 'und auch wegen der außerordentlichen Größe der Offenbarungen. Deswegen ist mir auch, damit ich mich nicht überhebe, ein Dorn ins Fleisch gegeben worden, ein Engel Satans, der mich mit Fäusten schlagen muß, damit ich mich nicht überhebe.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 12, 8, 'Dreimal habe ich um seinetwillen den Herrn angefleht, er möchte von mir ablassen;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 12, 9, 'doch er hat zu mir gesagt: »Meine Gnade ist für dich genügend, denn meine Kraft gelangt in der Schwachheit zur Vollendung.« Daher will ich mich am liebsten um so mehr meiner Schwachheiten rühmen, damit die Kraft Christi Wohnung bei mir nimmt.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 12, 10, 'Darum bin ich freudigen Muts in Schwachheiten, bei Mißhandlungen, in Notlagen, in Verfolgungen und Bedrängnissen, die ich um Christi willen erleide; denn gerade wenn ich schwach bin, dann bin ich stark.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 12, 11, 'Ich bin ein Tor geworden; ihr habt mich dazu gezwungen; denn (eigentlich) hätte ich von euch empfohlen werden müssen; ich bin ja doch in keiner Beziehung hinter den »unvergleichlichen« Aposteln zurückgeblieben, wenn ich auch nichts bin;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 12, 12, 'wenigstens sind die Zeichen des Apostels unter euch in aller Ausdauer erbracht worden durch Zeichen, Wunder und Machttaten;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 12, 13, 'denn was wäre es, worin ihr im Vergleich mit den anderen Gemeinden verkürzt worden wäret? Höchstens das eine, daß ich persönlich euch nicht zur Last gefallen bin: vergebt mir dieses Unrecht!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 12, 14, 'Seht, ich halte mich jetzt zu einem dritten Besuche bei euch bereit und werde euch (auch diesmal) nicht zur Last fallen; denn ich suche nicht euer Hab und Gut, sondern euch selbst; die Kinder sind ja nicht verpflichtet, für die Eltern Schätze zu sammeln, sondern umgekehrt die Eltern für die Kinder.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 12, 15, 'Ich aber will herzlich gern (Geld und Gut) zum Opfer bringen, ja mich selbst völlig aufopfern lassen, wenn es sich um euer Seelenheil handelt. Soll ich, wenn ich euch in besonderem Maße liebe, darum weniger Gegenliebe (bei euch) finden?');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 12, 16, 'Doch gut: ich persönlich bin euch nicht beschwerlich gefallen; aber weil ich ein »schlauer« Mann bin, habe ich euch »mit List eingefangen«?');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 12, 17, 'Habe ich euch etwa durch einen von denen ausbeuten lassen, die ich zu euch gesandt habe?');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 12, 18, 'Ich habe Titus zur Reise veranlaßt und den Bruder mitgesandt: hat euch nun Titus irgendwie ausgebeutet? Sind wir (beide) nicht in dem gleichen Geiste gewandelt? Nicht in den gleichen Fußtapfen?');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 12, 19, 'Schon lange seid ihr der Meinung, daß wir uns euch gegenüber verantworten wollen. Nein, vor Gottes Angesicht in Christus reden wir, und zwar soll das alles, Geliebte, zu eurer Auferbauung dienen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 12, 20, 'Ich fürchte nämlich, euch bei meinem Kommen nicht so zu finden, wie ich es wünsche, und (selbst) von euch so erfunden zu werden, wie ihr es nicht wünscht; ich fürchte, Streitigkeiten und Eifersucht, Zerwürfnisse und Parteiwesen, Verleumdungen und Ohrenbläsereien, Überhebung und Unordnung (bei euch) vorzufinden;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 12, 21, '(ich fürchte) daß mein Gott mich nach meiner Ankunft aufs neue demütigende Erfahrungen bei euch machen läßt und daß ich um viele von denen Leid tragen muß, die früher gesündigt haben und wegen der Unsittlichkeit, der Unzucht und ausschweifenden Lebensweise, die sie getrieben haben, unbußfertig geblieben sind.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 13, 1, 'Zum drittenmal komme ich jetzt zu euch: »auf Grund der Aussagen von zwei oder drei Zeugen wird jede Sache festgestellt werden«.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 13, 2, 'Ich habe es denen, die früher gesündigt haben, und allen anderen im voraus angekündigt und gebe wie bei meinem zweiten Besuch, so auch jetzt, während ich noch abwesend bin, die Erklärung ab: »Wenn ich noch einmal komme, werde ich keine Schonung üben!« –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 13, 3, 'Ihr verlangt ja den Beweis dafür, daß Christus in mir redet, und der ist gegen euch nicht schwach, sondern stark unter euch.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 13, 4, 'Denn er ist (wohl) infolge von Schwachheit gekreuzigt worden, lebt aber durch die Kraft Gottes. So sind auch wir wohl schwach in ihm, werden uns aber im Verein mit ihm durch die Kraft Gottes lebendig an euch erweisen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 13, 5, 'Macht an euch selbst die Probe, ob ihr im Glauben steht, prüft euch selbst! Oder könnt ihr nicht an euch selbst erkennen, daß Jesus Christus in euch ist? Da müßtet ihr ja unbewährt sein.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 13, 6, 'Daß wir aber nicht unbewährt sind, sollt ihr hoffentlich erkennen!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 13, 7, 'Doch wir beten zu Gott, daß ihr nichts Böses tun mögt, nicht zu dem Zweck, daß wir uns als bewährt offenbaren, sondern damit ihr das Gute tut, wir aber wie Nichtbewährte dastehen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 13, 8, 'Denn wir vermögen nichts wider die Wahrheit, sondern nur für die Wahrheit.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 13, 9, 'Wir freuen uns ja, wenn wir schwach sind, ihr aber stark seid; und dahin geht auch unser Gebet, nämlich daß ihr euch völlig zurechtbringen laßt.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 13, 10, 'Aus diesem Grunde schreibe ich euch dieses noch als Abwesender, um bei meiner Anwesenheit nicht mit Strenge vorgehen zu müssen in Ausübung der Machtbefugnis, die der Herr mir zur Auferbauung und nicht »zur Zerstörung« verliehen hat.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 13, 11, 'Im übrigen, liebe Brüder, freuet euch! Laßt euch zurechtbringen, nehmt Ermahnungen an, seid eines Sinnes und haltet Frieden; dann wird der Gott der Liebe und des Friedens mit euch sein.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 13, 12, 'Grüßt einander mit dem heiligen Kuß. Es grüßen euch die Heiligen alle. –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 13, 13, 'Die Gnade des Herrn Jesus Christus und die Liebe Gottes und die Gemeinschaft des heiligen Geistes sei mit euch allen!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 1, 1, 'Ich, Paulus, ein Apostel – nicht von Menschen her (entsandt), auch nicht durch Vermittlung eines Menschen (dazu gemacht), sondern durch Jesus Christus und Gott den Vater, der ihn von den Toten auferweckt hat –:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 1, 2, 'ich und sämtliche Brüder, die hier bei mir sind, senden den Gemeinden in Galatien unsern Gruß:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 1, 3, 'Gnade sei mit euch und Friede von Gott, unserm Vater, und dem Herrn Jesus Christus,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 1, 4, 'der sich für unsere Sünden hingegeben hat, um uns aus der gegenwärtigen bösen Welt zu erretten, nach dem Willen unsers Gottes und Vaters.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 1, 5, 'Diesem sei die Ehre in alle Ewigkeit. Amen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 1, 6, 'Ich muß mich darüber wundern, daß ihr so schnell wieder abfallt von dem, der euch durch die Gnade Christi berufen hat, und euch einer anderen Heilsbotschaft zuwendet,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 1, 7, 'während es doch keine andere (Heilsbotschaft) gibt; nur daß gewisse Leute da sind, die euch verwirren und die Heilsbotschaft Christi verkehren möchten.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 1, 8, 'Aber auch wenn wir selbst oder ein Engel aus dem Himmel euch eine andere Heilsbotschaft verkündigten als die, welche wir euch verkündigt haben: Fluch über ihn!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 1, 9, 'Wie wir es schon früher ausgesprochen haben, so wiederhole ich es jetzt noch einmal: »Wenn jemand euch eine andere Heilsbotschaft verkündigt als die, welche ihr (von mir) empfangen habt: Fluch über ihn!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 1, 10, 'Suche ich jetzt nun (mit solcher Sprache) den Beifall von Menschen zu gewinnen oder (nicht vielmehr) die Zustimmung Gottes? Oder gehe ich etwa darauf aus, Menschen zu gefallen? Nein, wenn ich mich noch um das Wohlgefallen von Menschen bemühte, so wäre ich kein Knecht Christi.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 1, 11, 'Ich weise euch nämlich darauf hin, liebe Brüder, daß die von mir zuverlässig verkündigte Heilsbotschaft nicht nach Menschenart ist.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 1, 12, 'Ich habe sie ja auch nicht von einem Menschen empfangen, noch sie durch Unterricht erlernt, sondern (sie) durch eine Offenbarung Jesu Christi (erhalten).');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 1, 13, 'Ihr habt ja von meinem einstmaligen Verhalten im Judentum gehört: daß ich nämlich die Gemeinde Gottes maßlos verfolgt habe und sie zu vernichten suchte');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 1, 14, 'und daß ich es an Leidenschaft für das jüdische Wesen vielen meiner Altersgenossen in meinem Volk zuvorgetan habe, indem ich ein ganz besonderer Eiferer für die von meinen Vätern überkommenen Überlieferungen war.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 1, 15, 'Als es aber dem, der mich vom Mutterleibe an ausgesondert und durch seine Gnade berufen hat, wohlgefällig war,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 1, 16, 'seinen Sohn in mir zu offenbaren, damit ich die Heilsbotschaft von ihm unter den Heiden verkündigte, da habe ich mich sofort nicht an Menschen von Fleisch und Blut (um Rat) gewandt,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 1, 17, 'bin auch nicht nach Jerusalem zu meinen Vorgängern im Apostelamt hinaufgegangen, nein, ich begab mich nach Arabien und kehrte dann wieder nach Damaskus zurück.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 1, 18, 'Darauf, drei Jahre später, ging ich nach Jerusalem hinauf, um Kephas kennenzulernen, und blieb fünfzehn Tage bei ihm.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 1, 19, 'Von den übrigen Aposteln habe ich damals keinen gesehen außer Jakobus, den Bruder des Herrn.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 1, 20, 'Was ich euch hier schreibe – vor Gottes Angesicht (versichere ich), daß ich die reine Wahrheit sage!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 1, 21, 'Hierauf begab ich mich in die Landschaften von Syrien und Cilicien.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 1, 22, 'Den Christengemeinden in Judäa aber blieb ich persönlich unbekannt;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 1, 23, 'nur vom Hörensagen wußten sie: »Unser ehemaliger Verfolger verkündigt jetzt als Heilsbotschaft den Glauben, den er einst ausrotten wollte«;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 1, 24, 'und sie priesen Gott im Hinblick auf mich.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 2, 1, 'Darauf, vierzehn Jahre später, zog ich wieder nach Jerusalem hinauf, (diesmal) mit Barnabas, und nahm auch Titus mit.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 2, 2, 'Ich unternahm aber diese Reise aufgrund einer (göttlichen) Offenbarung und legte ihnen, insbesondere den Angesehenen, die Heilsbotschaft dar, die ich unter den Heiden verkündige, (um feststellen zu lassen) ob meine Arbeit vergeblich wäre oder gewesen wäre.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 2, 3, 'Doch nicht einmal mein Begleiter Titus, der doch (ein Heidenchrist) aus den Griechen war, wurde zur Beschneidung genötigt.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 2, 4, 'Was aber die eingedrungenen falschen Brüder anlangt, die sich eingeschlichen hatten, um unsere Freiheit, die wir in Christus Jesus haben, zu belauern und uns ganz in die Knechtschaft (des Gesetzes) zu bringen:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 2, 5, 'vor ihnen sind wir auch nicht für eine Stunde in Unterwürfigkeit zurückgewichen, damit die Heilsbotschaft in ihrer Wahrheit bei euch bestehen bliebe.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 2, 6, 'Von seiten der Angesehenen aber, die als Häupter galten – übrigens ist es mir gleichgültig, von welcher Art ihr Ansehen damals war: Gott nimmt ja auf das äußere Ansehen eines Menschen keine Rücksicht –: mir also haben diese Angesehenen keine weitere Verpflichtung auferlegt;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 2, 7, 'nein, im Gegenteil, weil sie einsahen, daß ich mit der Heilsbotschaft für die Unbeschnittenen betraut bin, ebenso wie Petrus (mit der Heilsbotschaft) für die Beschnittenen –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 2, 8, 'denn (Gott), der sich in Petrus für den Aposteldienst an den Juden mit seiner Kraft wirksam erwiesen hat, ist mit seiner Kraft auch in mir für die Heiden wirksam gewesen –,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 2, 9, 'und weil sie die Gnade (Gottes) erkannten, die mir zuteil geworden ist, haben Jakobus, Kephas und Johannes, die als Säulen (der Gemeinde) galten, mir und Barnabas den Handschlag zum Gemeinschaftsbunde gegeben (mit der Bestimmung): wir sollten für die Heiden, sie aber für die Juden wirken;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 2, 10, 'nur der Armen (in Jerusalem) sollten wir gedenken, was ich mir eben deshalb auch ernstlich habe angelegen sein lassen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 2, 11, 'Als (später) aber Kephas nach Antiochien gekommen war, trat ich ihm Auge in Auge entgegen, denn er war ganz offenbar im Unrecht.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 2, 12, 'Bevor nämlich einige (Abgesandte) des Jakobus kamen, hatte er mit den Heidenchristen Tischgemeinschaft gehalten; aber nach der Ankunft jener hatte er sich zurückgezogen und sich (von ihnen) abgesondert aus Furcht vor den Judenchristen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 2, 13, 'An dieser Heuchelei hatten sich auch die übrigen Judenchristen mit ihm beteiligt, so daß sich sogar Barnabas durch ihre Heuchelei hatte mit fortreißen lassen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 2, 14, 'Als ich jedoch sah, daß sie nicht den rechten Weg in Übereinstimmung mit der Wahrheit der Heilsbotschaft wandelten, sagte ich zu Kephas offen im Beisein aller: »Wenn du, der du doch ein Jude bist, nach heidnischer und nicht nach jüdischer Weise lebst, wie kannst du da die Heiden zwingen wollen, die jüdischen Bräuche zu beobachten?');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 2, 15, 'Wohl sind wir von Natur Juden und nicht Sünder heidnischer Herkunft;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 2, 16, 'weil wir aber wissen, daß der Mensch nicht aufgrund von Gesetzeswerken gerechtfertigt wird, sondern nur durch den Glauben an Christus Jesus, haben auch wir den Glauben an Christus Jesus angenommen, um aufgrund des Glaubens an Christus und nicht aufgrund von Gesetzeswerken gerechtfertigt zu werden; denn aufgrund von Gesetzeswerken wird kein Fleisch gerechtfertigt werden.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 2, 17, 'Wenn wir nun aber bei unserem Streben, in Christus gerechtfertigt zu werden, gerade als Sünder erfunden worden wären, da stünde ja Christus im Dienst der Sünde! Das kann nicht sein!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 2, 18, 'Allerdings, wenn ich das, was ich niedergerissen habe, (später) wieder aufbaue, so stelle ich mich damit selbst als Übertreter hin.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 2, 19, 'Ich meinerseits dagegen bin durch das Gesetz für das Gesetz gestorben, um (fortan) für Gott zu leben: ich bin mit Christus gekreuzigt.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 2, 20, 'So lebe also nicht mehr ich selbst, sondern Christus lebt in mir; was ich jetzt aber noch im Fleisch lebe, das lebe ich im Glauben an den Sohn Gottes, der mich geliebt und sich selbst für mich dahingegeben hat.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 2, 21, 'Ich verwerfe die Gnade Gottes nicht; denn wenn Gerechtigkeit durch das Gesetz kommt, dann freilich ist Christus umsonst gestorben.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 3, 1, 'O ihr unverständigen Galater! Wer hat euch nur bezaubert, da euch doch Jesus Christus vor die Augen gemalt worden ist als Gekreuzigter?');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 3, 2, 'Nur das eine möchte ich von euch erfahren: Habt ihr den Geist aufgrund von Gesetzeswerken empfangen oder infolge der Predigt vom Glauben?');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 3, 3, 'Seid ihr wirklich so unverständig? Im Geist habt ihr den Anfang gemacht und wollt jetzt im Fleisch den Abschluß machen?');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 3, 4, 'So Großes solltet ihr vergeblich erlitten haben?! Ja, wenn wirklich bloß vergeblich!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 3, 5, 'Der euch also den Geist mitteilt und Wunderkräfte in euch wirkt, (tut er das) aufgrund von Gesetzeswerken oder infolge der Predigt vom Glauben?');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 3, 6, '(Ja, es ist so) wie bei Abraham: »er glaubte Gott, und das wurde ihm zur Gerechtigkeit gerechnet«.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 3, 7, 'Ihr erkennt also: die Gläubigen, die sind Abrahams Söhne.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 3, 8, 'Weil aber die Schrift voraussah, daß Gott die Völker um des Glaubens willen rechtfertigt, hat sie dem Abraham die Heilsverheißung im voraus verkündigt: »In dir sollen alle Völker gesegnet werden.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 3, 9, 'Somit empfangen die, welche aus dem Glauben sind den Segen zugleich mit dem gläubigen Abraham.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 3, 10, 'Denn alle, die aus Werken des Gesetzes sind, stehen unter einem Fluch; denn es steht geschrieben: »Verflucht ist jeder, der nicht in allen (Geboten), die im Buch des Gesetzes geschrieben stehen, beharrt, um sie (tatsächlich) zu erfüllen.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 3, 11, 'Daß aber aufgrund des Gesetzes niemand bei Gott gerechtfertigt wird, ist offenbar; denn »der Gerechte wird aus Glauben leben«.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 3, 12, 'Das Gesetz aber hat mit dem Glauben nichts zu tun, sondern: »Wer sie erfüllt hat, der wird durch sie leben.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 3, 13, 'Christus hat uns vom Fluch des Gesetzes dadurch losgekauft, daß er für uns zum Fluch geworden ist; denn es steht geschrieben: »Verflucht ist jeder, der am Holze hängt.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 3, 14, 'Es sollte eben der dem Abraham verheißene Segen den Heiden in Christus Jesus zuteil werden, damit wir das Verheißungsgut des Geistes durch den Glauben empfangen könnten.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 3, 15, 'Liebe Brüder, ich will an menschliche Verhältnisse erinnern: Auch die letztwillige Verfügung eines Menschen, die rechtskräftig geworden ist, kann doch niemand umstoßen oder nachträglich mit Zusätzen versehen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 3, 16, 'Nun sind aber die (göttlichen) Verheißungen dem Abraham »und seinem Samen« zugesprochen worden. Es heißt nicht: »und den Samen« in der Mehrzahl, sondern mit Bezug auf einen einzigen: »und deinem Samen«, und das ist Christus.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 3, 17, 'Ich meine das aber so: Eine von Gott bereits früher vollgültig gemachte Verfügung kann durch das Gesetz, das erst vierhundertunddreißig Jahre später gekommen ist, nicht außer Kraft gesetzt werden, so daß es die Verheißung aufhöbe.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 3, 18, 'Wenn nämlich das (verheißene) Erbe vom Gesetz abhängt, so hängt es nicht mehr von der Verheißung ab; dem Abraham aber hat Gott es durch eine Verheißung als Gnadengabe verliehen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 3, 19, 'Was soll nun aber das Gesetz? Der Übertretungen wegen ist es (der Verheißung) hinzugefügt worden (für die Zwischenzeit), bis der Same käme, dem die Verheißung gilt; und zwar ist es durch Engel verordnet worden unter Mitwirkung eines Mittlers.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 3, 20, 'Ein Mittler aber vertritt nicht einen einzigen; Gott aber ist ein einziger.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 3, 21, 'Steht demnach das Gesetz mit den Verheißungen Gottes in Widerspruch? Nimmermehr! Ja, wenn ein Gesetz gegeben worden wäre, das die Kraft besäße, Leben zu verleihen, dann käme die Gerechtigkeit tatsächlich aus dem Gesetz.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 3, 22, 'Nun aber hat die Schrift alles unter die (Herrschaft der) Sünde zusammengeschlossen, damit das Verheißungsgut den Gläubigen aufgrund des Glaubens an Jesus Christus zuteil würde.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 3, 23, 'Bevor aber der Glaube kam, wurden wir unter dem Gesetz in Verwahrung gehalten und waren unter Verschluß gelegt für den Glauben, der erst später geoffenbart werden sollte.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 3, 24, 'Somit ist das Gesetz unser Erzieher für Christus geworden, damit wir aufgrund des Glaubens gerechtfertigt würden.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 3, 25, 'Seitdem nun aber der Glaube gekommen ist, stehen wir nicht mehr unter einem Erzieher;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 3, 26, 'denn ihr alle seid Söhne Gottes durch den Glauben an Christus Jesus.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 3, 27, 'Denn ihr alle, die ihr in Christus getauft worden seid, habt (damit) Christus angezogen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 3, 28, 'Da gibt es nun nicht mehr Juden und Griechen, nicht mehr Knechte und Freie, nicht mehr Mann und Weib: nein, ihr seid allesamt Einer in Christus Jesus.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 3, 29, 'Wenn ihr aber Christus angehört, so seid ihr damit ja Abrahams Nachkommenschaft, Erben gemäß der Verheißung.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 4, 1, 'Ich sage aber: Solange der Erbe noch unmündig ist, besteht zwischen ihm und einem Knecht kein Unterschied, wenn er auch der Herr von allem ist;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 4, 2, 'er steht vielmehr unter Vormündern und Vermögensverwaltern bis zu dem vom Vater festgesetzten Zeitpunkt.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 4, 3, 'So standen auch wir, solange wir (geistlich) unmündig waren, als Sklaven unter der Herrschaft der Elemente der Welt.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 4, 4, 'Als aber die Erfüllung der Zeit gekommen war, sandte Gott seinen Sohn, der von einem Weibe geboren und dem Gesetz unterworfen wurde;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 4, 5, 'er sollte die unter dem Gesetz Stehenden loskaufen, damit wir die Einsetzung in die Sohnschaft erlangten.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 4, 6, 'Weil ihr jetzt aber Söhne seid, hat Gott den Geist seines Sohnes in unsere Herzen gesandt, der da ruft: »Abba, (lieber) Vater!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 4, 7, 'Mithin bist du kein Knecht mehr, sondern ein Sohn; bist du aber ein Sohn, so bist du auch ein Erbe durch Gott.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 4, 8, 'Damals freilich, als ihr Gott noch nicht kanntet, habt ihr solchen Göttern gedient, die ihrem Wesen nach gar keine Götter sind.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 4, 9, 'Da ihr jetzt aber Gott erkannt habt oder vielmehr von Gott erkannt worden seid: wie könnt ihr euch da nur wieder den erbärmlichen und armseligen Elementen zuwenden und Lust haben, ihnen noch einmal von neuem als Knechte zu dienen?!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 4, 10, 'Ihr beobachtet ja Tage und Monate, Festzeiten und Jahre!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 4, 11, 'Ich bin um euch besorgt, daß ich vergeblich an euch gearbeitet haben möchte.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 4, 12, 'Werdet doch so, wie ich (bin)! Denn auch ich (bin so gesetzesfrei geworden), wie ihr, liebe Brüder, ich bitte euch! Ihr habt mir (ja früher) nichts zuleide getan;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 4, 13, 'ihr wißt vielmehr, daß ich euch das erste Mal, veranlaßt durch leibliche Schwäche, die Heilsbotschaft verkündigt habe.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 4, 14, 'Damals habt ihr mich trotz des Anstoßes, den mein leiblicher Zustand bei euch erregen mußte, nicht mit Verachtung behandelt und nicht mit Abscheu zurückgewiesen, sondern mich wie einen Engel Gottes, ja wie Christus Jesus (selber) aufgenommen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 4, 15, 'Wo ist nun eure (damalige) glückselige Freude geblieben? Ich muß euch ja das Zeugnis ausstellen, daß ihr euch damals, wenn es möglich gewesen wäre, die Augen ausgerissen und sie mir geschenkt hättet.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 4, 16, 'Sonach bin ich jetzt wohl dadurch euer Feind geworden, daß ich euch die Wahrheit vorhalte?');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 4, 17, 'O sie bewerben sich nicht in guter Absicht eifrig um eure Gunst, nein, sie möchten euch gern (von mir) ausschließen, damit ihr euch dann eifrig um ihre Gunst bemüht.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 4, 18, 'Schön ist es ja, in guter Sache Gegenstand eifriger Umwerbung zu sein, und zwar allezeit und nicht nur während meiner Anwesenheit bei euch.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 4, 19, 'Meine lieben Kinder, um die ich jetzt wiederum Geburtsschmerzen leide, bis Christus (endlich) in euch Gestalt gewinnt:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 4, 20, 'ich wollte, ich wäre gerade jetzt bei euch und könnte in anderem Ton zu euch reden; denn ich weiß mir euretwegen keinen Rat!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 4, 21, 'Sagt mir doch, die ihr gern unter dem Gesetz stehen möchtet: hört ihr denn das Gesetz nicht?');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 4, 22, 'Es steht ja doch geschrieben, daß Abraham zwei Söhne hatte, einen von der Magd und einen von der Freien.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 4, 23, 'Jedoch jener von der Magd war nur sein fleischmäßig erzeugter Sohn, dieser von der Freien aber war ihm aufgrund der (göttlichen) Verheißung geboren.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 4, 24, 'Das ist bildlich gesprochen; denn diese (beiden Frauen) stellen zwei Bündnisse dar, das eine vom Berge Sinai, das zur Knechtschaft gebiert: das ist die Hagar;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 4, 25, 'das Wort Hagar bedeutet nämlich den Berg Sinai in Arabien, und sie entspricht dem heutigen Jerusalem; denn dieses befindet sich (auch) in Knechtschaft samt seinen Kindern.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 4, 26, 'Das Jerusalem droben dagegen ist eine Freie, und dies (Jerusalem) ist unsere Mutter;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 4, 27, 'denn es steht geschrieben: »Freue dich, du Kinderlose, die du nicht Mutter wirst! Brich in Jubel aus und frohlocke, die du keine Geburtsschmerzen zu leiden hast! Denn die Alleinstehende hat zahlreiche Kinder, mehr als die Verehelichte.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 4, 28, 'Ihr aber, liebe Brüder, seid nach Isaaks Art Kinder der Verheißung.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 4, 29, 'Wie jedoch damals der nach dem Fleisch erzeugte Sohn den nach dem Geist erzeugten verfolgt hat, so ist es auch jetzt der Fall.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 4, 30, 'Aber was sagt die Schrift dazu? »Verstoße die Magd und ihren Sohn! Denn der Sohn der Magd soll nicht das gleiche Erbrecht mit dem Sohn der Freien haben.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 4, 31, 'Darum, liebe Brüder: Wir sind nicht Kinder einer Magd, sondern der Freien!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 5, 1, 'Zur Freiheit hat Christus uns frei gemacht. Stehet also fest und laßt euch nicht wieder in das Joch der Knechtschaft spannen!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 5, 2, 'Seht, ich, Paulus, erkläre euch: Wenn ihr euch beschneiden laßt, so wird Christus euch nichts mehr nützen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 5, 3, 'Nochmals bezeuge ich es einem jeden, der sich beschneiden läßt: er ist damit zur Beobachtung des ganzen Gesetzes verpflichtet.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 5, 4, 'Aus der Verbindung mit Christus seid ihr ausgeschieden, wenn ihr durch das Gesetz gerechtfertigt werden wollt: ihr seid dann aus der Gnade herausgefallen;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 5, 5, 'denn wir erwarten durch den Geist das Hoffnungsgut der Gerechtigkeit aufgrund des Glaubens.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 5, 6, 'Denn in Christus Jesus hat weder die Beschneidung noch das Unbeschnittensein irgendwelche Bedeutung, sondern nur der Glaube, der sich durch Liebe betätigt.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 5, 7, 'Ihr hattet einen so schönen Anlauf genommen: wer hat euch aufgehalten, daß ihr der Wahrheit nicht mehr gehorchen wollt?');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 5, 8, 'Der Antrieb dazu kommt nicht von dem her, der euch beruft.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 5, 9, 'Schon ein wenig Sauerteig macht den ganzen Teig sauer.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 5, 10, 'Ich für meine Person habe das Vertrauen zu euch im Herrn, daß ihr eure Gesinnung nicht ändern werdet; wer euch aber irre macht: er wird sein Strafurteil zu tragen haben, er sei, wer er wolle.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 5, 11, 'Was mich aber betrifft, liebe Brüder: wenn ich wirklich noch die Beschneidung predige, warum verfolgt man mich da noch? Dann ist ja das Ärgernis des Kreuzes aus der Welt geschafft!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 5, 12, 'Möchten doch die Leute, die euch aufwiegeln, sich sogar verschneiden lassen!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 5, 13, 'Ihr seid ja doch zur Freiheit berufen, liebe Brüder; nur mißbraucht die Freiheit nicht als einen willkommenen Anlaß für das Fleisch, sondern dienet einander durch die Liebe!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 5, 14, 'Denn das ganze Gesetz findet seine Erfüllung in dem einen Gebot: »Du sollst deinen Nächsten lieben wie dich selbst!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 5, 15, 'Wenn ihr euch aber untereinander beißt und freßt, so sehet zu, daß ihr nicht voneinander verschlungen werdet!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 5, 16, 'Ich meine aber so: Wandelt im Geist, dann werdet ihr sicherlich das Gelüst des Fleisches nicht vollführen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 5, 17, 'Denn das Fleisch widerstrebt mit seinem Begehren dem Geist und ebenso der Geist dem Fleisch; denn diese beiden liegen im Streit miteinander (und dulden nicht), daß ihr das tut, was ihr tun möchtet.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 5, 18, 'Laßt ihr euch aber vom Geist leiten, so steht ihr nicht (mehr) unter dem Gesetz.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 5, 19, 'Offenbar aber sind die Werke des Fleisches, nämlich Unzucht, Unsittlichkeit, Ausschweifung,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 5, 20, 'Götzendienst, Zauberei, Feindseligkeiten, Zank, Eifersucht, Zerwürfnisse, gemeine Selbstsucht, Zwietracht, Parteiungen,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 5, 21, 'Neid, Trunksucht, Schwelgerei und so weiter. Von diesen (Sünden) habe ich euch schon früher gesagt und wiederhole es jetzt, daß, wer derartiges verübt, das Reich Gottes nicht erben wird.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 5, 22, 'Die Frucht des Geistes dagegen besteht in Liebe, Freude, Friede, Geduld, Freundlichkeit, Gütigkeit, Treue,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 5, 23, 'Sanftmut, Beständigkeit; gegen derartige (Geistesfrüchte) kann das Gesetz keine Anklage erheben.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 5, 24, 'Die aber Christus Jesus angehören, haben ihr Fleisch samt seinen Leidenschaften und Begierden gekreuzigt.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 5, 25, 'Wenn wir nun im Geiste leben, so laßt uns im Geiste auch wandeln!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 5, 26, 'Laßt uns nicht nach eitler Ehre begierig sein, einander nicht (zum Streit) herausfordern, einander nicht beneiden! –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 6, 1, 'Liebe Brüder, wenn auch jemand sich von einem Fehltritt hat übereilen lassen, so bringt ihr Geistesmenschen den Betreffenden mit dem Geist der Sanftmut wieder zurecht, und gib dabei auf dich selbst acht, damit du nicht auch in Versuchung gerätst!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 6, 2, 'Traget einer des andern Lasten, so werdet ihr dadurch das Gesetz Christi erfüllen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 6, 3, 'Denn wenn jemand sich dünken läßt, er sei etwas, obwohl er doch nichts ist, so betrügt er sich selbst in seinem Sinn.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 6, 4, 'Jeder prüfe aber sein eigenes Werk, und dann mag er für sich allein zu rühmen haben, aber nicht dem andern gegenüber;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 6, 5, 'denn ein jeder wird an seiner eigenen Last zu tragen haben.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 6, 6, 'Wer aber Unterricht im Wort (Gottes) erhält, lasse seinen Lehrer an allen Gütern teilnehmen! –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 6, 7, 'Irret euch nicht: Gott läßt sich nicht spotten; denn was der Mensch sät, das wird er auch ernten.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 6, 8, 'Denn wer auf sein Fleisch sät, wird vom Fleisch Verderben ernten; wer aber auf den Geist sät, wird vom Geist ewiges Leben ernten.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 6, 9, 'Laßt uns aber nicht müde werden, das Rechte zu tun; denn zu seiner Zeit werden wir ernten, wenn wir nicht ermatten.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 6, 10, 'Darum wollen wir so, wie wir Gelegenheit haben, allen Menschen Gutes erweisen, besonders aber den Glaubensgenossen!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 6, 11, 'Sehet, mit wie großen Buchstaben ich euch (nun noch) eigenhändig schreibe!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 6, 12, '(Nur) solche (Leute), die im Fleische etwas Besonderes vorstellen wollen, suchen euch die Beschneidung aufzunötigen, lediglich um nicht wegen (der Verkündigung) des Kreuzes Christi Verfolgungen zu erleiden.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 6, 13, 'Denn trotz ihrer Beschneidung beobachten sie selbst das Gesetz nicht, sondern dringen auf eure Beschneidung nur deshalb, um sich eures leiblichen Menschen rühmen zu können.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 6, 14, 'Mir aber soll es nicht beikommen, mich irgendeiner anderen Sache zu rühmen als nur des Kreuzes unsers Herrn Jesus Christus, durch das für mich die Welt gekreuzigt ist und ich für die Welt.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 6, 15, 'Denn weder auf die Beschneidung noch auf das Unbeschnittensein kommt es an, sondern nur auf eine »neue Schöpfung«;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 6, 16, 'und alle, die nach dieser Richtschnur wandeln werden: über die komme Friede und (göttliches) Erbarmen, nämlich über das Israel Gottes!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 6, 17, 'In Zukunft möge mir niemand zu schaffen machen, denn ich trage die Malzeichen Jesu an meinem Leibe! –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 6, 18, 'Die Gnade unsers Herrn Jesus Christus sei mit eurem Geiste, liebe Brüder! Amen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 1, 'Ich, Paulus, ein Apostel Jesu Christi durch den Willen Gottes, sende meinen Gruß den Heiligen und an Christus Jesus Gläubigen, die [in Ephesus] sind:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 2, 'Gnade sei mit euch und Friede von Gott unserm Vater und dem Herrn Jesus Christus!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 3, 'Gepriesen sei der Gott und Vater unsers Herrn Jesus Christus, der uns mit jedem Segen geistlicher Art, (der) in der Himmelswelt (vorhanden ist), in Christus gesegnet hat!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 4, 'Denn in ihm hat er uns ja schon vor der Grundlegung der Welt dazu erwählt, daß wir heilig und unsträflich vor seinem Angesicht dastehen sollten,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 5, 'und hat uns in Liebe durch Jesus Christus zu Söhnen, die ihm angehören sollten, vorherbestimmt nach dem Wohlgefallen seines Willens,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 6, 'zum Lobpreis der Herrlichkeit seiner Gnade, die er uns in dem Geliebten erwiesen hat.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 7, 'In diesem haben wir die Erlösung durch sein Blut, nämlich die Vergebung unserer Übertretungen, nach dem Reichtum seiner Gnade,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 8, 'die er uns nach Mitteilung aller Weisheit und Einsicht in überströmender Fülle hat zuteil werden lassen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 9, 'Er hat uns ja das Geheimnis seines Willens kundgetan, nach seinem freien Ratschluß, dessen Ausführung er sich vorgenommen hatte,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 10, 'sobald die Zeiten zum Vollmaß der von ihm geordneten Entwicklung gelangt wären: er wollte in Christus als dem Haupt alles einheitlich zusammenfassen, was in den Himmeln und was auf der Erde ist.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 11, 'In ihm sind wir nun auch des (verheißenen) Heilsbesitzes teilhaftig geworden, nachdem wir dazu vorherbestimmt worden waren nach dem Vorsatz dessen, der alles nach dem Beschluß seines Willens vollbringt:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 12, 'wir sollten eben zum Lobpreis seiner Herrlichkeit dienen, wir, die wir unsere Hoffnung von vornherein auf Christus gesetzt haben.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 13, 'In ihm seid auch ihr, nachdem ihr das Wort der Wahrheit, die Heilsbotschaft von eurer Rettung, vernommen habt und zum Glauben gekommen seid, mit dem verheißenen heiligen Geist versiegelt worden,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 14, 'der das Angeld für unser Erbe ist (und) für die Erlösung seiner Eigentumsgemeinde (Bürgschaft leistet), zum Lobpreis seiner Herrlichkeit.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 15, 'Das ist denn auch der Grund, weshalb ich auf die Kunde von eurem Glauben an den Herrn Jesus und von eurer Liebe zu allen Heiligen');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 16, 'mit der Danksagung für euch nicht aufhöre und in meinen Gebeten euer mit Namensnennung gedenke:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 17, 'der Gott unsers Herrn Jesus Christus, der Vater der Herrlichkeit, wolle euch den Geist der Weisheit und der Offenbarung durch die Erkenntnis seiner selbst verleihen');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 18, '(und) euren Herzen erleuchtete Augen (verleihen), damit ihr begreift, welche Hoffnung ihr infolge seiner Berufung habt, wie groß der Reichtum seines herrlichen Erbes bei den Heiligen ist,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 19, 'und wie überschwenglich seine Kraft sich an uns, den Gläubigen, erweist, nämlich die mit gewaltiger Macht sich betätigende Stärke,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 20, 'die er an Christus erwiesen hat, als er ihn von den Toten auferweckte und ihn in der Himmelswelt zu seiner Rechten sitzen ließ,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 21, 'hocherhaben über jede (andere) Herrschaft und Gewalt, über jede Macht und Hoheit, überhaupt über jeden Namen, der nicht nur in dieser, sondern auch in der zukünftigen Weltzeit genannt wird.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 22, 'Ja, alles hat er ihm zu Füßen gelegt und hat ihn zum alles überragenden Haupt gemacht für die Gemeinde,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 23, 'die sein Leib ist, die Fülle dessen, der alles in allen erfüllt.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 2, 1, 'So hat er auch euch, die ihr tot waret durch eure Übertretungen und Sünden,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 2, 2, 'in denen ihr einst wandeltet, abhängig vom Zeitgeist dieser Welt, abhängig von dem Machthaber, der die Gewalt über die Luft hat, dem Geist, der gegenwärtig in den Söhnen des Ungehorsams wirksam ist, –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 2, 3, 'unter diesen haben auch wir alle einst in unseren fleischlichen Lüsten dahingelebt, indem wir den Willen des Fleisches und unserer Gedanken ausführten und von Natur Kinder des (göttlichen) Zornes waren wie die anderen auch –;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 2, 4, 'Gott aber, der an Barmherzigkeit reich ist, hat uns um seiner großen Liebe willen, die er zu uns hegte,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 2, 5, 'und zwar als wir tot waren durch unsere Übertretungen, zugleich mit Christus lebendig gemacht – durch Gnade seid ihr gerettet worden! –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 2, 6, 'und hat uns in Christus Jesus mitauferweckt und mit ihm in die Himmelswelt versetzt,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 2, 7, 'um in den kommenden Weltzeiten den überschwenglichen Reichtum seiner Gnade durch die Gütigkeit gegen uns in Christus Jesus zu erweisen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 2, 8, 'Denn durch die Gnade seid ihr gerettet worden auf Grund des Glaubens, und zwar nicht aus euch – nein, Gottes Geschenk ist es –,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 2, 9, 'nicht aufgrund von Werken, damit niemand sich rühme.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 2, 10, 'Denn sein Gebilde sind wir, in Christus Jesus geschaffen zu guten Werken, die Gott im voraus bereitgestellt hat, damit wir in ihnen wandeln könnten.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 2, 11, 'Darum bleibt dessen eingedenk, daß einstmals ihr, die ihr nach dem Fleisch Heiden waret und von dem Volk der äußerlich mit Händen am Leibe vollzogenen Beschneidung »Vorhaut« genannt wurdet –,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 2, 12, 'daß ihr in jener Zeit fern von Christus gestanden habt, ausgeschlossen vom Bürgerrecht Israels und ohne Anteil an den Bündnissen der Verheißung, ohne Hoffnung und ohne Gott in der Welt.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 2, 13, 'Jetzt aber in Christus Jesus seid ihr, die ihr ehedem in der Ferne standet, durch das Blut Christi zu Nahestehenden geworden.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 2, 14, 'Denn er ist unser Friede, er, der die beiden Teile zu einer Einheit gemacht und die trennende Scheidewand, die Feindschaft weggeräumt hat, nachdem er durch (die Hingabe) seines Leibes');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 2, 15, 'das Gesetz mit seinen in Satzungen gefaßten Geboten beseitigt hatte, um so die beiden in seiner Person zu einem einzigen neuen Menschen als Friedensstifter umzugestalten');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 2, 16, 'und die beiden in einem Leibe mit Gott durch das Kreuz zu versöhnen, nachdem er durch dieses die Feindschaft getötet hatte.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 2, 17, 'So ist er denn gekommen und hat Frieden euch, den Fernstehenden, und ebenso Frieden den Nahestehenden als frohe Botschaft verkündigt;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 2, 18, 'denn durch ihn haben wir beide nunmehr den freien Zugang zum Vater in einem Geist.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 2, 19, 'Demnach seid ihr jetzt nicht mehr Fremdlinge und Beisassen, sondern seid Vollbürger mit den Heiligen und Gottes Hausgenossen,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 2, 20, 'aufgebaut auf dem Grund der Apostel und Propheten, (ein Bau) bei welchem Christus Jesus selber der Eckstein ist:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 2, 21, 'in ihm wächst jeder Bau, fest zusammengefügt, zu einem heiligen Tempel im Herrn empor,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 2, 22, 'und in diesem werdet auch ihr (Heiden) mitauferbaut zu einer Wohnstätte Gottes im Geist.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 3, 1, 'Das ist der Grund, weshalb ich, Paulus, der ich euch Heiden zugute der Gefangene Christi Jesu bin, –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 3, 2, 'ihr habt doch wohl von der Verwaltung der Gnade Gottes gehört, die mir für euch verliehen worden ist,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 3, 3, 'daß mir nämlich durch Offenbarung das Geheimnis kundgetan worden ist, wie ich davon schon vorhin in Kürze geschrieben habe.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 3, 4, 'Daran könnt ihr, wenn ihr es lest, meine Vertrautheit mit dem Geheimnis Christi erkennen,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 3, 5, 'das in früheren Zeitaltern den Menschenkindern nicht kundgetan worden ist, wie es jetzt seinen heiligen Aposteln und Propheten geoffenbart worden ist:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 3, 6, 'daß nämlich die Heiden Miterben und Miteinverleibte und Mitgenossen der Verheißung in Jesus Christus sind durch die Heilsbotschaft,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 3, 7, 'deren Diener ich geworden bin nach der Gnadengabe Gottes, die mir nach der in ihrer Wirkung gewaltigen Kraft verliehen worden ist.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 3, 8, 'Mir, dem geringsten unter allen Heiligen, ist dieses Gnadenamt verliehen worden, den Heiden die Heilsbotschaft von dem unergründlichen Reichtum Christi zu verkündigen');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 3, 9, 'und allen Aufklärung darüber zu geben, welche Bewandtnis es mit der Verwirklichung des Geheimnisses hat, das von Urzeiten in Gott, dem Schöpfer aller Dinge, verborgen gewesen ist,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 3, 10, 'damit nunmehr den Gewalten und den Mächten in den Himmelsräumen durch die Gemeinde die vielgestaltige Weisheit Gottes kundgetan werde.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 3, 11, 'Diesen Vorsatz, den er von Ewigkeit her gefaßt hatte, hat er zur Ausführung gebracht in Christus Jesus, unserm Herrn,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 3, 12, 'in welchem wir die freudige Zuversicht und den freien Zutritt (zu Gott) in freudigem Vertrauen durch den Glauben an ihn haben.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 3, 13, 'Deshalb bitte ich auch darum, in meinen Leiden für euch nicht mutlos zu werden; das ist ja eine Verherrlichung für euch.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 3, 14, 'Deswegen beuge ich meine Knie vor dem Vater,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 3, 15, 'von dem jede Vaterschaft, die es im Himmel und auf Erden gibt, ihren Namen trägt:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 3, 16, 'er wolle euch nach dem Reichtum seiner Herrlichkeit verleihen, durch seinen Geist am inwendigen Menschen mit Kraft ausgerüstet zu werden,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 3, 17, 'damit Christus durch den Glauben Wohnung in euren Herzen nehme und ihr in der Liebe tiefgewurzelt und festgegründet dastehet,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 3, 18, 'auf daß ihr fähig werdet, im Verein mit allen Heiligen die Breite und Länge, die Tiefe und Höhe (des göttlichen Heilsratschlusses) zu erfassen');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 3, 19, 'und die alle Erkenntnis übersteigende Liebe Christi kennenzulernen, damit ihr schließlich zum Erfülltsein mit der ganzen Gottesfülle gelangt.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 3, 20, 'Ihm aber, der nach der Kraft, die in uns wirksam ist, unendlich mehr zu tun vermag über alles hinaus, was wir erbitten und erdenken (können):');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 3, 21, 'ihm gebührt die Ehre in der Gemeinde und in Christus Jesus bis hinaus auf alle Geschlechter aller Zeiten der Ewigkeit! Amen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 4, 1, 'So ermahne ich euch denn, ich, der Gefangene im Herrn: Wandelt würdig der Berufung, die an euch ergangen ist,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 4, 2, 'mit aller Demut und Sanftmut, mit Geduld als solche, die einander in Liebe ertragen,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 4, 3, 'und seid eifrig bemüht, die Einheit des Geistes durch das Band des Friedens zu erhalten:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 4, 4, 'ein Leib und ein Geist, wie ihr ja auch bei eurer Berufung aufgrund einer Hoffnung berufen worden seid;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 4, 5, 'ein Herr, ein Glaube, eine Taufe;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 4, 6, 'ein Gott und Vater aller, der da ist über allen und durch alle (wirkt) und in allen (wohnt).');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 4, 7, 'Jedem einzelnen von uns aber ist die Gnade nach dem Maße verliehen worden, wie Christus sie ihm zugeteilt hat.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 4, 8, 'Daher heißt es ja auch: »Aufgestiegen in die Höhe, hat er Gefangene weggeführt und den Menschen Gaben verliehen.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 4, 9, 'Daß er aber hinaufgestiegen ist, welchen Sinn hat das als den, daß er auch (zuvor) in die niederen Gegenden der Erde hinabgestiegen ist?');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 4, 10, 'Er, der Hinabgestiegene, ist derselbe, der hoch über alle Himmel hinaus aufgestiegen ist, um das ganze Weltall zu erfüllen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 4, 11, 'Und eben dieser ist es auch, der die einen zu Aposteln bestellt hat, andere zu Propheten, andere zu Evangelisten, noch andere zu Hirten und Lehrern,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 4, 12, 'um die Heiligen tüchtig zu machen für die Ausübung des Gemeindedienstes, für die Erbauung des Leibes Christi,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 4, 13, 'bis wir endlich allesamt zur Einheit des Glaubens und der Erkenntnis des Sohnes Gottes gelangen, zur vollkommenen Mannesreife, zum Vollmaß des Wuchses in der Fülle Christi.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 4, 14, 'Denn wir sollen nicht länger unmündige Kinder sein, die von jedem Wind der Lehre durch das Trugspiel der Menschen, die mit Arglist auf Irreführung ausgehen, wie Meereswogen hin und her geworfen und umhergetrieben werden;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 4, 15, 'vielmehr sollen wir, die Wahrheit übend, in Liebe in allen Stücken in ihn hineinwachsen, der das Haupt ist, Christus;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 4, 16, 'denn von ihm aus wird der ganze Leib fest zusammengefügt und zusammengehalten und vollzieht durch jedes Glied, das seinen Dienst nach der Wirksamkeit verrichtet, die dem Maß jedes einzelnen Teiles entspricht, das Wachstum des Leibes zu seinem eigenen Aufbau in Liebe.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 4, 17, 'So sage ich also folgendes und spreche die ernste Mahnung im Herrn aus: Wandelt nicht mehr so, wie die Heiden in der Nichtigkeit ihres Sinnes wandeln!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 4, 18, 'Sie sind ja in ihrem (ganzen) Denken verfinstert, dem Leben Gottes entfremdet infolge der Unwissenheit, die in ihnen wegen der Verstocktheit ihres Herzens wohnt.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 4, 19, 'Sittlich völlig abgestumpft, haben sie sich dem Genußleben hingegeben zur Verübung jeder Art von Unsittlichkeit in Verbindung mit Habgier.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 4, 20, 'Ihr aber habt Christus nicht so kennengelernt,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 4, 21, 'wenn ihr überhaupt von ihm gehört habt und in ihm so unterwiesen worden seid, wie es Wahrheit in Jesus ist:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 4, 22, 'daß ihr nämlich im Hinblick auf den früheren Lebenswandel den alten Menschen ablegen müßt, der sich infolge der trügerischen Begierden zugrunde richtet,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 4, 23, 'daß ihr dagegen im tiefsten Inneren eures Geisteslebens erneuert werden müßt');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 4, 24, 'und den neuen Menschen anziehet, der nach Gottes Ebenbild geschaffen ist in wahrhafter Gerechtigkeit und Reinheit.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 4, 25, 'Darum leget die Lüge ab und »redet die Wahrheit, ein jeder mit seinem Nächsten«; wir sind ja untereinander Glieder (desselben Leibes). –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 4, 26, '»Zürnet ihr, so sündiget dabei nicht«; laßt die Sonne über eurem Zorn nicht untergehen');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 4, 27, 'und gebt dem Verleumder keinen Raum! –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 4, 28, 'Der Dieb stehle fortan nicht mehr, sondern arbeite vielmehr angestrengt und erwerbe mit seiner Hände Arbeit das Gute, damit er imstande ist, den Notleidenden zu unterstützen. –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 4, 29, 'Laßt keine faule Rede aus eurem Munde hervorgehen, sondern nur eine solche, die da, wo es nottut, zur Erbauung dient, damit sie den Hörern Segen bringe.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 4, 30, 'Und betrübt nicht den heiligen Geist Gottes, mit dem ihr auf den Tag der Erlösung versiegelt seid. –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 4, 31, 'Alle Bitterkeit, aller Zorn und Groll, alles Schreien und Schmähen sei aus eurer Mitte weggetan, überhaupt alles boshafte Wesen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 4, 32, 'Zeigt euch vielmehr gütig und herzlich gegeneinander, und vergebt einer dem andern, wie auch Gott euch in Christus vergeben hat!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 5, 1, 'Folgt also dem Vorbild Gottes nach als (von ihm) geliebte Kinder');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 5, 2, 'und wandelt in der Liebe, wie auch Christus euch geliebt und sich selbst für uns als Weihegabe und Opfer dargebracht hat, Gott zu einem lieblichen Wohlgeruch.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 5, 3, 'Unzucht aber und Unsittlichkeit jeder Art oder Geldgier dürfen bei euch nicht einmal mit Namen erwähnt werden, wie es sich für Heilige geziemt,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 5, 4, 'ebensowenig unanständiges Wesen und fades Geschwätz oder leichtfertige Witze, die sich für euch nicht schicken würden, statt dessen vielmehr Danksagung.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 5, 5, 'Denn das wißt und erkennt ihr wohl, daß kein Unzüchtiger und Unsittlicher, kein Geldgieriger – das ist gleichbedeutend mit Götzendiener – ein Erbteil im Reiche Christi und Gottes hat.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 5, 6, 'Laßt euch von niemand durch leere Worte betrügen; denn um solcher Dinge willen kommt Gottes Zorn über die Ungehorsamen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 5, 7, 'Macht euch daher nicht zu ihren Mitgenossen;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 5, 8, 'denn früher seid ihr zwar Finsternis gewesen, jetzt aber seid ihr Licht im Herrn: führt euren Wandel als Kinder des Lichts –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 5, 9, 'die Frucht des Lichts erweist sich nämlich in lauter Gütigkeit, Gerechtigkeit und Wahrheit –,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 5, 10, 'und prüfet dabei, was dem Herrn wohlgefällig ist.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 5, 11, 'Habt auch nichts zu tun mit den unfruchtbaren Werken der Finsternis, legt vielmehr mißbilligend Zeugnis gegen sie ab;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 5, 12, 'denn was im Verborgenen von ihnen getrieben wird, davon auch nur zu reden ist schandbar.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 5, 13, 'Das alles wird aber, wenn es aufgedeckt wird, vom Licht getroffen und offenbar gemacht; denn alles, was offenbar gemacht wird, ist Licht.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 5, 14, 'Daher heißt es auch: »Wache auf, du Schläfer, und stehe auf von den Toten! Dann wird Christus dir aufleuchten.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 5, 15, 'Achtet also genau darauf, wie ihr wandelt, nicht als Unweise, sondern als Weise,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 5, 16, 'indem ihr die Zeit auskauft, denn die Tage sind böse.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 5, 17, 'Darum zeigt euch nicht unverständig, sondern sucht zu verstehen, welches der Wille des Herrn ist.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 5, 18, 'Berauscht euch auch nicht an Wein, was zur Liederlichkeit führt, sondern werdet voll Geistes,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 5, 19, 'so daß ihr zueinander mit Psalmen, Lobgesängen und geistlichen Liedern redet und dem Herrn in eurem Herzen singt und spielt;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 5, 20, 'und sagt Gott dem Vater allezeit Dank für alles im Namen unsers Herrn Jesus Christus.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 5, 21, 'Ordnet euch einander unter, wie es die Furcht vor Christus verlangt:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 5, 22, 'Die Frauen seien ihren Ehemännern untertan, als gälte es dem Herrn;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 5, 23, 'denn der Mann ist das Haupt der Frau, ebenso wie Christus das Haupt der Gemeinde ist, er freilich ist (zugleich) der Retter seines Leibes;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 5, 24, 'dennoch, wie die Gemeinde (dem Herrn) Christus untertan ist, so sollen es auch die Frauen ihren Männern in jeder Beziehung sein.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 5, 25, 'Ihr Männer, liebet eure Frauen, wie auch Christus die Gemeinde geliebt und sich für sie dahingegeben hat,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 5, 26, 'um sie zu heiligen, nachdem er sie durch das Wasserbad im Wort gereinigt hat,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 5, 27, 'um so die Gemeinde für sich selbst in herrlicher Schönheit hinzustellen, ohne Flecken und Runzeln oder irgendeinen derartigen Fehler, vielmehr so, daß sie heilig und ohne Tadel sei.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 5, 28, 'Ebenso sind auch die Männer verpflichtet, ihre Frauen wie ihre eigenen Leiber zu lieben. Wer seine Frau liebt, liebt sich selbst;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 5, 29, 'es hat ja doch noch nie ein Mensch sein eigenes Fleisch gehaßt, sondern jeder hegt und pflegt es, ebenso wie Christus es mit der Gemeinde tut,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 5, 30, 'denn wir sind Glieder seines Leibes, Fleisch von seinem Fleisch und Bein von seinem Bein.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 5, 31, '»Deshalb wird ein Mann Vater und Mutter verlassen und seinem Weibe anhangen, und die beiden werden ein Fleisch sein.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 5, 32, 'Hier liegt ein großes Geheimnis vor; ich deute es auf Christus und die Gemeinde.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 5, 33, 'Doch wie dem auch sei: auch bei euch soll ein jeder seine Frau so lieben wie sich selbst; die Frau aber soll ihrem Manne mit Furcht begegnen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 6, 1, 'Ihr Kinder, seid euren Eltern gehorsam im Herrn; denn das ist in der Ordnung.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 6, 2, '»Ehre deinen Vater und deine Mutter!« – dies ist das erste Gebot mit (der) Verheißung:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 6, 3, '»damit es dir wohl ergehe und du lange lebest auf Erden«. –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 6, 4, 'Und ihr Väter, reizt eure Kinder nicht zum Zorn, sondern erzieht sie in der Zucht und Vermahnung des Herrn!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 6, 5, 'Ihr Knechte, seid euren leiblichen Herren gehorsam mit Furcht und Zittern, in Aufrichtigkeit eures Herzens, als gälte es (dem Herrn) Christus,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 6, 6, 'nicht mit Augendienerei, als solche, die Menschen gefallen wollen, sondern als Knechte Christi, die den Willen Gottes von Herzen tun.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 6, 7, 'Verrichtet euren Dienst mit Willigkeit, als gälte es dem Herrn und nicht den Menschen;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 6, 8, 'ihr wißt ja, daß jeder für das, was er Gutes tut, den entsprechenden Lohn vom Herrn empfangen wird, er sei ein Knecht oder ein Freier. –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 6, 9, 'Und ihr Herren, handelt ebenso gegen sie und unterlaßt das Drohen! Ihr wißt ja, daß ihr ebenso wie sie einen Herrn im Himmel habt und daß es bei diesem kein Ansehen der Person gibt.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 6, 10, 'Zuletzt: werdet stark im Herrn und in der gewaltigen, ihm innewohnenden Kraft.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 6, 11, 'Ziehet die volle Waffenrüstung Gottes an, damit ihr gegen die listigen Anläufe des Teufels zu bestehen vermögt!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 6, 12, 'Denn wir haben nicht mit Wesen von Fleisch und Blut zu kämpfen, sondern mit den (überirdischen) Mächten, mit den (teuflischen) Gewalten, mit den Beherrschern dieser Welt der Finsternis, mit den bösen Geisterwesen in der Himmelswelt.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 6, 13, 'Darum nehmt die volle Waffenrüstung Gottes zur Hand, damit ihr imstande seid, am bösen Tage Widerstand zu leisten, alles gut auszurichten und das Feld zu behaupten!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 6, 14, 'So stehet also da, an den Hüften gegürtet mit Wahrheit, angetan mit dem Panzer der Gerechtigkeit,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 6, 15, 'an den Füßen beschuht mit der Bereitschaft, die Heilsbotschaft des Friedens zu verkünden!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 6, 16, 'Zu dem allem ergreift noch den Großschild des Glaubens, mit dem ihr alle Brandgeschosse des Bösen zum Verlöschen werdet bringen können.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 6, 17, 'Nehmet auch den Helm des Heils an euch und das Schwert des Geistes, nämlich das Wort Gottes.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 6, 18, 'Betet allezeit im Geist mit Bitten und Flehen jeder Art, und seid zu diesem Zweck wachsam mit aller Beharrlichkeit und unter Fürbitte für alle Heiligen,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 6, 19, 'auch für mich, daß mir, sooft ich den Mund auftue, das Wort gegeben werde, um freimütig das Geheimnis der Heilsbotschaft zu verkündigen,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 6, 20, 'für die ich auch in Ketten ein Sendbote bin, damit ich in ihr ein freimütiges Bekenntnis ablege, wie es mir gebührt zu reden.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 6, 21, 'Damit aber auch ihr über meine Lage hier und mein Ergehen etwas erfahrt, wird Tychikus, der geliebte Bruder und treue Diener im Herrn, euch alles berichten.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 6, 22, 'Ihn habe ich eben deshalb zu euch gesandt, damit ihr von unserer Lage hier Kenntnis erhaltet und er eure Herzen ermutige.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 6, 23, 'Friede (werde) den Brüdern (zuteil) und Liebe im Verein mit Glauben von Gott dem Vater und dem Herrn Jesus Christus!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 6, 24, 'Die Gnade sei mit allen, die unsern Herrn Jesus Christus lieben mit unverbrüchlicher Treue.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 1, 1, 'Wir, Paulus und Timotheus, Knechte Christi Jesu, entbieten allen Heiligen in Christus Jesus, die in Philippi sind, sowie auch den dortigen Vorstehern und Gemeindedienern unsern Gruß:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 1, 2, 'Gnade sei (mit) euch und Friede von Gott unserm Vater und vom Herrn Jesus Christus!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 1, 3, 'Ich sage meinem Gott Dank, sooft ich euer gedenke,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 1, 4, 'indem ich allezeit in jeder meiner Fürbitten für euch alle mit Freuden bete');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 1, 5, 'wegen der Teilnahme, die ihr an (der Verkündigung) der Heilsbotschaft vom ersten Tage an bis heute betätigt habt;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 1, 6, 'ich hege eben deshalb auch die feste Zuversicht, daß der, welcher ein gutes Werk in euch angefangen hat, es auch bis zum Tage Jesu Christi vollenden wird.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 1, 7, 'Es ist ja doch nur recht und billig für mich, diese gute Meinung von euch allen zu hegen; denn ich halte die Erinnerung an euch in meinem Herzen fest, weil ihr allesamt sowohl während meiner Gefangenschaft als auch bei der Verteidigung und Bezeugung der Heilsbotschaft Mitgenossen des mir verliehenen Gnadenamts seid.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 1, 8, 'Denn Gott ist mein Zeuge, wie ich mich mit der innigen Liebe Christi Jesu nach euch allen sehne.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 1, 9, 'Und dahin geht mein Gebet, daß eure Liebe je länger desto mehr zunehme an Erkenntnis und allem Feingefühl');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 1, 10, 'zur Prüfung dessen, was in jedem Fall das richtige sei, damit ihr auf den Tag Christi lauter und ohne Tadel dasteht,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 1, 11, 'voll ausgestattet mit der Frucht der Gerechtigkeit, die durch Jesus Christus erwächst, zur Ehre und zum Lobpreis Gottes.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 1, 12, 'Ich will euch aber wissen lassen, liebe Brüder, daß meine Lage hier eher zur Förderung der Heilsverkündigung sich entwickelt hat.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 1, 13, 'Es ist nämlich bei der ganzen kaiserlichen Leibwache und auch sonst überall offenkundig geworden, daß ich um Christus willen meine Fesseln trage;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 1, 14, 'und so haben denn die meisten Brüder durch meine Gefangenschaft neue Zuversicht im Herrn gewonnen und wagen deshalb mit wachsender Furchtlosigkeit das Wort Gottes zu verkündigen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 1, 15, 'Einige freilich predigen Christus auch aus Neid und Streitsucht, manche aber doch auch in guter Absicht:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 1, 16, 'die einen aus Liebe (zu mir), weil sie wissen, daß ich zur Verteidigung der Heilsbotschaft bestellt bin;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 1, 17, 'die anderen, die es aus Rechthaberei tun, verkündigen Christus nicht in lauterer Absicht, (sondern) in der Meinung, daß sie mir dadurch zu meiner Gefangenschaft auch noch Kummer verursachen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 1, 18, 'Doch was tut’s? Wird doch in jedem Fall, mit oder ohne Hintergedanken, Christus verkündigt, und darüber freue ich mich. Aber (auch fernerhin) werde ich mich freuen;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 1, 19, 'ich weiß ja, daß dieses mir infolge eurer Fürbitte und der Unterstützung des Geistes Jesu Christi zum Heil ausschlagen wird;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 1, 20, 'wie ich überhaupt die feste Erwartung und freudige Hoffnung hege, daß ich in keiner Beziehung beschämt dastehen werde, sondern daß ganz offensichtlich wie allezeit, so auch jetzt Christus an meinem Leibe verherrlicht werden wird, es sei durch mein Weiterleben oder durch meinen (Zeugen-) Tod.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 1, 21, 'Denn für mich bedeutet Christus das Leben, und darum ist das Sterben für mich ein Gewinn.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 1, 22, 'Wenn aber mein Weiterleben ein leibliches (Leben) sein soll, so bedeutet das für mich Fruchtbringen durch Arbeit, und so weiß ich nicht, was ich vorziehen soll.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 1, 23, 'Ich fühle mich nämlich nach beiden Seiten hingezogen: ich habe Lust aufzubrechen und mit Christus vereint zu sein; das wäre ja doch auch weitaus das Beste (für mich).');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 1, 24, 'Aber daß ich leiblich weiterlebe, ist um euretwillen notwendiger;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 1, 25, 'und so weiß ich mit voller Gewißheit, daß ich am Leben bleiben und euch allen erhalten bleiben werde, euch zur Förderung und zur Freude im Glauben,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 1, 26, 'damit ihr noch weit mehr Grund habt, euch meiner in Christus Jesus zu rühmen, wenn ich noch einmal bei euch anwesend sein werde.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 1, 27, 'Nur verwaltet die Gemeinde so, wie es der Heilsbotschaft Christi würdig ist; denn ich möchte, falls ich kommen sollte, an euch sehen oder, falls ich fernbleibe, über euch hören, daß ihr in einem Geiste feststeht, indem ihr einmütig wie ein Mann für den Glauben an die Heilsbotschaft kämpft');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 1, 28, 'und euch in keiner Beziehung von den Widersachern einschüchtern laßt; das ist (alsdann) für sie ein Hinweis auf ihr Verderben, für euch dagegen auf eure Rettung, und zwar (ein Hinweis) von Gott her.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 1, 29, 'Denn euch ist in eurem Christenstand die Gnade zuteil geworden, nicht nur an Christus zu glauben, sondern auch um seinetwillen zu leiden,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 1, 30, 'indem ihr denselben Leidenskampf zu bestehen habt, wie ihr ihn (vordem) bei mir gesehen habt und jetzt bei mir hört.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 2, 1, 'Wenn nun eine in Christus ausgesprochene Ermahnung, wenn ein liebevoller Zuspruch, wenn eine Gemeinschaft des Geistes, wenn inniges Mitgefühl und Erbarmen (noch vorhanden sind, oder: etwas gelten),');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 2, 2, 'so macht meine Freude dadurch vollkommen, daß ihr eines Sinnes seid, indem ihr die gleiche Liebe hegt und einmütig dem gleichen Ziel zustrebt');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 2, 3, 'und nichts aus Rechthaberei oder eitlem Ehrgeiz tut, sondern in Demut einer den andern höher als sich selbst erachtet;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 2, 4, 'jeder habe nicht (nur) seinen eigenen Vorteil im Auge, sondern jeder auch den des andern.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 2, 5, 'Solche Gesinnung wohne in euch allen, wie sie auch in Christus Jesus vorhanden war;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 2, 6, 'denn obgleich er Gottes Gestalt besaß, sah er doch das Gleichsein mit Gott nicht als einen gewaltsam festzuhaltenden Raub an;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 2, 7, 'nein, er entäußerte sich selbst (seiner Herrlichkeit), indem er Knechtsgestalt annahm, ganz in menschliches Wesen einging und in seiner leiblichen Beschaffenheit als ein Mensch erfunden wurde;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 2, 8, 'er erniedrigte sich selbst und wurde gehorsam bis zum Tode, ja, bis zum Tode am Kreuz.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 2, 9, 'Daher hat Gott ihn auch über die Maßen erhöht und ihm den Namen verliehen, der jedem anderen Namen überlegen ist,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 2, 10, 'damit im Namen Jesu sich jedes Knie aller derer beuge, die im Himmel und auf der Erde und unter der Erde sind,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 2, 11, 'und jede Zunge bekenne, daß Jesus Christus der Herr ist, zur Ehre Gottes, des Vaters.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 2, 12, 'Daher, meine Geliebten: wie ihr allezeit gehorsam gewesen seid, so seid darauf bedacht, nicht nur wie damals, als ich bei euch anwesend war, sondern jetzt, wo ich fern von euch bin, noch weit mehr eure Rettung mit Furcht und Zittern zu schaffen;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 2, 13, 'denn Gott ist es, der beides, das Wollen und das Vollbringen, in euch wirkt, damit ihr ihm wohlgefallt:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 2, 14, 'Tut alles ohne Murren und Bedenken,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 2, 15, 'damit ihr euch tadellos und lauter erweist, als unsträfliche Gotteskinder inmitten einer verkehrten und verdrehten Menschheit, unter der ihr wie helle Sterne in der Welt leuchtet.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 2, 16, 'Haltet fest am Wort des Lebens, mir zum Ruhm auf den Tag Christi, weil ich dann nicht vergeblich gelaufen bin und nicht vergeblich gearbeitet habe.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 2, 17, 'Aber auch wenn ich als Trankopfer ausgegossen werden sollte über dem Opfer und dem priesterlichen Dienst an eurem Glauben, so freue ich mich doch und freue mich im Verein mit euch allen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 2, 18, 'Ebenso freuet aber auch ihr euch, und zwar im Verein mit mir!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 2, 19, 'Ich hoffe aber im Herrn Jesus, Timotheus bald zu euch senden zu können, damit auch ich mich beruhigt fühle, wenn ich erfahre, wie es um euch steht.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 2, 20, 'Denn ich habe keinen ihm Gleichgesinnten, der so hingebend für euer Bestes Sorge tragen wird;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 2, 21, 'alle anderen denken ja nur an sich selbst, nicht an das, was der Sache Jesu Christi dient.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 2, 22, 'Aber seine bewährte Treue ist euch bekannt, daß er wie ein Sohn seinem Vater, zusammen mit mir den Dienst (der Verkündigung) der Heilsbotschaft geleistet hat.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 2, 23, 'Ihn also hoffe ich euch unverzüglich senden zu können, sobald ich meine Lage zu übersehen vermag;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 2, 24, 'ich bin aber im Herrn der Zuversicht, daß auch ich selbst bald werde kommen können.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 2, 25, 'Für nötig habe ich es aber gehalten, den Bruder Epaphroditus, meinen Mitarbeiter und Mitstreiter, der euer Abgesandter und der Überbringer eurer Gabe für meinen Lebensunterhalt ist, zu euch zurückzusenden;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 2, 26, 'denn er hatte Heimweh nach euch allen und war in Unruhe darüber, daß ihr von seiner Erkrankung Kunde erhalten hattet.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 2, 27, 'Ach ja, er ist wirklich todkrank gewesen; aber Gott hat sich seiner erbarmt, und nicht nur seiner, sondern auch meiner, damit ich nicht Trauer über Trauer erlebte.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 2, 28, 'So habe ich mich denn doppelt beeilt, ihn heimzusenden, damit ihr seines Wiedersehens froh werdet und ich eine Sorge weniger habe.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 2, 29, 'Nehmt ihn also im Herrn mit aller Freude auf und haltet solche Männer in Ehren!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 2, 30, 'Denn um des Werkes Christi willen ist er dem Tode nahe gekommen, da er sein Leben aufs Spiel gesetzt hatte, um eurem Liebesdienste für mich das hinzuzufügen, was ihr selbst nicht leisten konntet.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 3, 1, 'Im übrigen, meine Brüder, freuet euch im Herrn! Euch (nochmals) dasselbe zu schreiben, verursacht mir keine Beschwerde, euch aber verleiht es Festigkeit.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 3, 2, 'Seht euch die Hunde an, seht euch die bösen Arbeiter an, seht euch die (Männer der) Verschneidung an!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 3, 3, 'Denn wir sind die (rechte) Beschneidung, die wir Gott im Geiste dienen und unsern Ruhm in Christus Jesus suchen und unser Vertrauen nicht auf das Fleisch setzen,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 3, 4, 'wiewohl ich persönlich mich zuversichtlich auch auf das Fleisch berufen kann. Wenn irgendein anderer sein Vertrauen auf das Fleisch setzen zu dürfen glaubt, so kann ich es erst recht:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 3, 5, 'Ich bin am achten Tage beschnitten worden, bin aus dem Volk Israel gebürtig, aus dem Stamme Benjamin, ein Hebräer von Hebräern, nach meiner Stellung zum Gesetz ein Pharisäer,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 3, 6, 'in Hinsicht auf den Eifer ein Verfolger der Gemeinde, in Hinsicht auf die Gerechtigkeit, die im Gesetz verlangt wird, untadelig erfunden.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 3, 7, 'Doch das, was ich (früher) für Gewinn hielt, das habe ich um Christi willen für Verlust zu achten gelernt;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 3, 8, 'ja, ich achte sogar unbedingt alles für Schaden gegenüber der unendlich wertvolleren Erkenntnis Christi Jesu, meines Herrn, um dessen willen ich das alles preisgegeben habe und es geradezu für Kehricht halte, damit ich nur Christus gewinne');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 3, 9, 'und in ihm als ein solcher erfunden werde, der nicht seine eigene Gerechtigkeit besitzt, die aus dem Gesetz gewonnen wird, sondern die Gerechtigkeit, die durch den Glauben an Christus vermittelt wird, die Gerechtigkeit aus Gott aufgrund des Glaubens.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 3, 10, 'Denn ich möchte ihn erkennen und die Kraft seiner Auferstehung und die Teilnahme an seinen Leiden, indem ich seinem Tode gleichgestaltet werde,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 3, 11, 'ob ich wohl zur Auferstehung aus den Toten gelangen möchte.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 3, 12, 'Nicht als ob ich es schon ergriffen hätte oder schon zur Vollendung gelangt wäre; ich jage ihm aber nach, ob ich’s wohl ergreifen möchte, weil ich ja auch von Christus Jesus ergriffen worden bin.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 3, 13, 'Liebe Brüder, ich denke von mir noch nicht, daß ich’s ergriffen habe; eins aber (tue ich): ich vergesse, was hinter mir liegt, und strecke mich nach dem aus, was vor mir liegt,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 3, 14, 'und jage, das vorgesteckte Ziel im Auge, nach dem Siegespreis, den die in Christus Jesus ergangene himmlische Berufung Gottes in Aussicht stellt.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 3, 15, 'Wir alle nun, die wir zielbewußt sind, wollen hierauf unsern Sinn gerichtet halten, und wenn ihr über irgend etwas anderer Meinung seid, so wird Gott euch auch darüber Klarheit verleihen;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 3, 16, 'nur laßt uns nach derselben Überzeugung, zu der wir bereits gelangt sind, unbeirrt weiterwandeln!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 3, 17, 'Folgt meinem Beispiel allesamt nach, liebe Brüder, und richtet euren Blick auf die, welche so wandeln, wie ihr uns zum Vorbild habt.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 3, 18, 'Denn gar manche wandeln – ich habe es euch von ihnen schon oft gesagt und wiederhole es jetzt sogar mit Tränen – als die Feinde des Kreuzes Christi:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 3, 19, 'ihr Ende ist das Verderben, ihr Gott ist der Bauch, und ihre Ehre besteht in ihrer Schande, ihr Sinnen ist nur auf das Irdische gerichtet.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 3, 20, 'Unser Bürgertum dagegen ist im Himmel, von wo wir auch den Herrn Jesus Christus als Retter erwarten,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 3, 21, 'der unsern niedrigen Leib umwandeln wird zur Gleichgestalt mit seinem Herrlichkeitsleibe vermöge der Kraft, mit der er auch alle Dinge sich zu unterwerfen vermag.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 4, 1, 'Daher, meine geliebten Brüder, nach denen ich mich sehne, ihr meine Freude und meine Krone: stehet in dieser Weise fest im Herrn, Geliebte!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 4, 2, 'Die Evodia ermahne ich und ebenso die Syntyche, eines Sinnes zu sein im Herrn.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 4, 3, 'Ja, ich bitte auch dich, mein Syzygus: nimm dich als echter Genosse ihrer an! Sie haben mir ja im Kampf für die Heilsbotschaft Beistand geleistet im Verein mit Klemens und meinen übrigen Mitarbeitern, deren Namen im Buche des Lebens verzeichnet stehen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 4, 4, 'Freuet euch im Herrn allezeit! Noch einmal wiederhole ich’s: »Freuet euch!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 4, 5, 'Laßt eure Sanftmut allen Menschen kund werden: der Herr ist nahe!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 4, 6, 'Sorgt euch um nichts, sondern laßt in jeder Lage eure Anliegen durch Gebet und Flehen verbunden mit Danksagung vor Gott kund werden!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 4, 7, 'Dann wird der Friede Gottes, der höher ist als aller Verstand, eure Herzen und euer ganzes Denken in Christus Jesus bewahren.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 4, 8, 'Endlich, liebe Brüder: alles, was wahr ist, was ehrbar, was gerecht, was rein, was liebenswert, was unanstößig ist, sei es irgendeine Tugend oder etwas Lobenswertes, darauf seid bedacht!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 4, 9, 'Was ihr auch (von mir) gelernt und überkommen, gehört und an mir gesehen habt, das tut: dann wird der Gott des Friedens mit euch sein.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 4, 10, 'Es ist für mich aber eine hohe Freude im Herrn gewesen, daß ihr jetzt endlich wieder in die günstige Lage gekommen seid, fürsorglich an mich zu denken; ihr habt zwar immer daran gedacht, befandet euch aber äußerlich nicht in der Lage (zur Ausführung).');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 4, 11, 'Ich sage das nicht, weil ich mich in Not befinde; denn ich habe gelernt, in welcher Lage ich mich auch befinde, mir genügen zu lassen;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 4, 12, 'ich verstehe mich darauf, in Ärmlichkeit und ebenso auch im Überfluß zu leben: in alles und jedes bin ich eingeweiht, sowohl satt zu sein als auch zu hungern, sowohl Überfluß zu haben als Mangel zu leiden;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 4, 13, 'alles vermag ich in ihm, der mich stark macht.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 4, 14, 'Trotzdem: ihr habt wohl daran getan, daß ihr mir in meiner bedrängten Lage eure Teilnahme bewiesen habt.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 4, 15, 'Ihr wißt aber selbst, liebe Philipper, daß im Anfang (meiner Verkündigung) der Heilsbotschaft, als ich aus Mazedonien weggegangen war, keine Gemeinde mit mir in das Wechselverhältnis des Gebens und Nehmens getreten ist als ihr allein;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 4, 16, 'denn schon als ich in Thessalonike war, habt ihr mir mehr als einmal eine Unterstützung für meinen Bedarf zukommen lassen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 4, 17, 'Nicht daß es mir um die Gabe zu tun wäre; nein, für mich handelt es sich um die Frucht, die als Guthaben auf eure Rechnung kommt.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 4, 18, 'Ich habe aber alles (was ihr gesandt habt) richtig erhalten und habe nun mehr als genug: ich lebe in Hülle und Fülle, seitdem ich von Epaphroditus eure Zuwendung erhalten habe, einen lieblichen Wohlgeruch, ein willkommenes, Gott wohlgefälliges Opfer.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 4, 19, 'Mein Gott aber wird euch nach seinem Reichtum alles, was ihr bedürft, in Herrlichkeit zukommen lassen in Christus Jesus.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 4, 20, 'Unserm Gott und Vater aber sei die Ehre in alle Ewigkeit!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 4, 21, 'Grüßt jeden Heiligen in Christus Jesus! Es grüßen euch die Brüder, die hier bei mir sind.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 4, 22, 'Alle Heiligen lassen euch grüßen, besonders die vom kaiserlichen Hofe.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 4, 23, 'Die Gnade des Herrn Jesus Christus sei mit eurem Geiste! Amen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 1, 1, 'Ich, Paulus, ein Apostel Christi Jesu durch Gottes Willen, und der Bruder Timotheus');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 1, 2, 'senden unsern Gruß den in Kolossä lebenden heiligen und gläubigen Brüdern in Christus Jesus: Gnade sei mit euch und Friede von Gott, unserm Vater!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 1, 3, 'Wir danken Gott, dem Vater unsers Herrn Jesus Christus, allezeit in unsern Gebeten für euch,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 1, 4, 'da wir von eurem Glaubensstand in Christus Jesus und von der Liebe, die ihr zu allen Heiligen hegt, gehört haben,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 1, 5, '(und zwar danken wir Gott) um des Hoffnungsgutes willen, das für euch im Himmel aufbewahrt liegt. Von diesem habt ihr schon im voraus Kunde erhalten durch das Wort der Wahrheit, nämlich der Heilsbotschaft,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 1, 6, 'die bei euch Eingang gefunden hat, wie sie ja auch in der ganzen Welt (verbreitet) ist und ebenso Frucht bringt und wächst wie auch bei euch seit dem Tage, an dem ihr sie vernommen und die Gnade Gottes in Wahrheit erkannt habt.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 1, 7, 'Ihr habt ja die betreffende Unterweisung von unserm geliebten Mitknecht Epaphras empfangen, der als unser Vertreter ein treuer Diener Christi ist');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 1, 8, 'und uns auch von eurer durch den Geist gewirkten Liebe berichtet hat.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 1, 9, 'Deshalb hören auch wir seit dem Tage, an dem wir es vernommen haben, nicht auf, für euch zu beten und (Gott) zu bitten, daß ihr mit der Erkenntnis seines Willens in aller geistgewirkten Weisheit und Einsicht erfüllt werden möchtet,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 1, 10, 'damit ihr so, wie es des Herrn würdig ist, zu seinem völligen Wohlgefallen wandelt. Ja, möchtet ihr in jedem guten Werke Frucht bringen und in der Erkenntnis Gottes wachsen!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 1, 11, 'Möchtet ihr mit aller Kraft, wie es der Macht seiner Herrlichkeit entspricht, zu aller Standhaftigkeit und Ausdauer ausgerüstet werden');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 1, 12, 'und mit Freuden dem Vater Dank sagen, der uns zur Teilnahme am Erbe der Heiligen im Licht tüchtig gemacht hat!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 1, 13, 'Er hat uns ja aus der Gewalt der Finsternis gerettet und uns in das Reich des Sohnes seiner Liebe versetzt.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 1, 14, 'In diesem haben wir die Erlösung, nämlich die Vergebung der Sünden;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 1, 15, 'er ist ja das Ebenbild des unsichtbaren Gottes, der Erstgeborene aller Schöpfung;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 1, 16, 'denn in ihm ist alles geschaffen worden, was im Himmel und auf der Erde ist, das Sichtbare wie das Unsichtbare, mögen es Throne oder Herrschaften, Mächte oder Gewalten sein: alles ist durch ihn und für ihn geschaffen worden,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 1, 17, 'und er ist vor allem, und alles hat in ihm seinen Bestand.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 1, 18, 'Ferner ist er das Haupt des Leibes, nämlich der Gemeinde: er ist der Anfang, der Erstgeborene aus den Toten, er, der in allen Beziehungen den Vorrang haben sollte.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 1, 19, 'Denn es war (Gottes) Ratschluß, in ihm die ganze Fülle wohnen zu lassen');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 1, 20, 'und durch ihn alles mit sich zu versöhnen – nachdem er durch sein am Kreuz vergossenes Blut Frieden gestiftet hat –, durch ihn (zu versöhnen) sowohl das, was auf der Erde, als auch das, was in den Himmeln ist.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 1, 21, 'Auch euch, die ihr einst (gott)entfremdet und feindlichen Sinnes in euren bösen Werken waret, –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 1, 22, 'jetzt aber hat er euch in seinem Fleischesleibe durch seinen Tod versöhnt, um euch als heilig, untadelig und unanklagbar vor ihm darzustellen,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 1, 23, 'wofern ihr im Glauben fest gegründet und unerschütterlich beharrt und euch nicht von der Hoffnung abbringen laßt, die in der Heilsbotschaft beschlossen liegt. Diese (Botschaft) habt ihr vernommen: sie ist ja in der ganzen Schöpfung unter dem Himmel verkündigt worden, und ich, Paulus, bin ihr Diener geworden.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 1, 24, 'Jetzt freue ich mich der Leiden, die ich für euch zu erdulden habe, und ergänze das, was an den Trübsalen Christi noch fehlt, in meinem Fleisch für seinen Leib, das heißt für die Gemeinde,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 1, 25, 'deren Diener ich infolge des Haushalteramts geworden bin, das mir von Gott im Hinblick auf euch übertragen worden ist, um das Wort Gottes vollkommen auszurichten,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 1, 26, 'nämlich das Geheimnis, das, seitdem es Weltzeiten und Menschengeschlechter gibt, verborgen gewesen, jetzt aber seinen Heiligen geoffenbart worden ist.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 1, 27, 'Denn ihnen hat Gott kundtun wollen, welche Fülle von Herrlichkeit dieses Geheimnis (gerade) unter den Heidenvölkern in sich berge. Dieser Reichtum besteht darin, daß Christus in euch ist, als die Hoffnung auf die (künftige) Herrlichkeit.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 1, 28, 'Und er ist es, den wir verkündigen, indem wir jedermann ermahnen und jedermann in aller Weisheit unterweisen, um einem jeden zur Vollkommenheit in Christus zu verhelfen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 1, 29, 'Um dieses zu erreichen, arbeite ich auch angestrengt und kämpfe vermöge seiner Kraft, die sich machtvoll in mir wirksam erweist.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 2, 1, 'Ich will euch nämlich wissen lassen, welch schweren Kampf ich für euch und die (Brüder) in Laodizea sowie (überhaupt) für alle, denen ich bis jetzt persönlich noch unbekannt geblieben bin, zu bestehen habe.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 2, 2, 'Ihre Herzen sollen dadurch ermutigt werden, nachdem sie sich in Liebe fest zusammengeschlossen haben und in den ganzen Reichtum des vollen Verständnisses (eingeführt werden), zur Erkenntnis des Geheimnisses Gottes.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 2, 3, 'Dieses (Geheimnis) ist Christus, in welchem alle Schätze der Weisheit und Erkenntnis verborgen liegen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 2, 4, 'Ich sage dies aber, damit niemand euch durch Überredungskünste täusche.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 2, 5, 'Denn wenn ich auch leiblich abwesend bin, so bin ich doch dem Geist nach bei euch gegenwärtig und sehe mit Freuden eure festgeschlossene Kampfstellung und das gesicherte Bollwerk eures Glaubens an Christus.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 2, 6, 'Wie ihr nun den Herrn Christus Jesus angenommen habt, so wandelt nun auch in ihm:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 2, 7, 'bleibt in ihm festgewurzelt und baut euch in ihm auf und werdet fest im Glauben, wie ihr unterwiesen worden seid, und laßt es an reichlicher Danksagung nicht fehlen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 2, 8, 'Gebt wohl acht, daß niemand euch einfängt durch die Philosophie und eitle Täuschung, die sich auf menschliche Überlieferung, auf die Elemente der Welt, gründet und mit Christus nichts zu tun hat.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 2, 9, 'Denn in ihm wohnt die ganze Fülle der Gottheit leibhaftig,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 2, 10, 'und ihr besitzt die ganze Fülle in ihm, der das Haupt jeder Herrschaft und Gewalt ist.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 2, 11, 'In ihm habt ihr auch die Beschneidung empfangen, nämlich eine solche, die nicht mit Händen vollzogen ist, nein, die in der Ablegung des Fleischesleibes besteht: die Beschneidung Christi,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 2, 12, 'da ihr in der Taufe mit ihm zusammen begraben worden seid. In ihm seid ihr auch mitauferweckt worden durch den Glauben an die Kraftwirkung Gottes, der ihn aus den Toten auferweckt hat.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 2, 13, 'Auch euch, die ihr durch eure Übertretungen und den unbeschnittenen Zustand eures Fleisches (einst) tot waret, auch euch hat Gott zusammen mit ihm lebendig gemacht, indem er uns alle Übertretungen aus Gnaden vergeben hat,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 2, 14, 'dadurch, daß er den durch seine Satzungen gegen uns lautenden Schuldschein, der für unser Heil ein Hindernis bildete, ausgelöscht und ihn weggeschafft hat, indem er ihn ans Kreuz heftete.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 2, 15, 'Nachdem er dann die Mächte und die Gewalten völlig entwaffnet hatte, stellte er sie öffentlich zur Schau und triumphierte in ihm über sie.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 2, 16, 'Darum soll niemand um Speisen und Getränke willen oder in bezug auf Fest- oder Neumondsfeier oder Sabbate absprechende Urteile über euch abgeben;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 2, 17, 'diese Dinge sind ja doch nur der Schatten von dem in der Zukunft Kommenden; das leibhaftige Wesen dagegen gehört Christus an.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 2, 18, 'Niemand soll euch verurteilen, indem er sich in demutsvollem Wesen und in Verehrung der Engel gefällt, sich mit Gesichten brüstet, ohne Grund von seinem fleischlichen Sinn aufgeblasen ist');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 2, 19, 'und sich nicht an das Haupt hält, von dem aus der ganze Leib durch die Gelenke und Bänder unterstützt und zusammengehalten wird und so ein gottgeordnetes Wachstum vollzieht.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 2, 20, 'Wenn ihr mit Christus gestorben seid, los von den Elementen der Welt, was laßt ihr euch da, als ob ihr noch in der Welt lebtet, Satzungen aufbürden,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 2, 21, 'z.B.: »Das darfst du nicht anfassen und das nicht essen und das nicht anrühren«? –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 2, 22, 'Alles Derartige ist doch dazu bestimmt, durch den Verbrauch der Vernichtung anheimzufallen, und stellt (nur) Menschengebote und Menschenlehren dar,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 2, 23, 'die zwar im Ruf besonderer Weisheit infolge einer selbsterwählten Frömmigkeit und Demut und schonungsloser Härte gegen den Körper stehen, aber ohne wirklichen Wert sind, indem sie nur zur Befriedigung des Fleisches dienen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 3, 1, 'Seid ihr also mit Christus auferweckt worden, so suchet das, was droben ist, dort, wo Christus weilt, indem er zur Rechten Gottes thront!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 3, 2, 'Trachtet nach dem, was droben ist, nicht nach dem, was auf Erden ist;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 3, 3, 'ihr seid ja doch gestorben, und euer Leben ist zusammen mit Christus in Gott verborgen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 3, 4, 'Wenn Christus, unser Leben, offenbar werden wird, dann werdet auch ihr zusammen mit ihm offenbar werden in Herrlichkeit.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 3, 5, 'So ertötet denn eure Glieder, die an der Erde (haften), (in denen) Unzucht, Unsittlichkeit, Leidenschaft, böse Begierde (wohnen) und die Habsucht, die nichts anderes als Götzendienst ist;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 3, 6, 'um dieser (Sünden) willen ergeht das Zorngericht Gottes über die Söhne des Ungehorsams.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 3, 7, 'In diesen (Sünden) seid auch ihr einst gewandelt, als ihr noch in ihnen lebtet.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 3, 8, 'Jetzt aber legt auch ihr alles derartige ab: Zorn, Erbitterung, Bosheit, Schimpfworte und unanständige Reden eures Mundes!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 3, 9, 'Belügt euch nicht gegenseitig! Ihr habt ja doch den alten Menschen samt seinem ganzen Tun ausgezogen');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 3, 10, 'und den neuen Menschen angezogen, der zur Erkenntnis nach dem Bilde seines Schöpfers erneuert wird,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 3, 11, 'wo keine Rede mehr ist von Griechen und Juden, von Beschnittenen und Unbeschnittenen, von Barbaren und Skythen, Sklaven und Freien, sondern alles und in allen (allein) Christus.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 3, 12, 'So ziehet nun als von Gott Auserwählte, als Heilige und Geliebte, herzliches Erbarmen, Gütigkeit, Demut, Sanftmut und Geduld an;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 3, 13, 'ertragt einander und vergebt euch gegenseitig, wenn jemand dem andern etwas vorzuwerfen hat; wie der Herr euch vergeben hat, so tut auch ihr es.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 3, 14, 'Zu dem allem aber (ziehet) die Liebe (an), die das Band der Vollkommenheit ist.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 3, 15, 'Und der Friede Christi regiere in euren Herzen – zu diesem seid ihr ja auch berufen worden als ein Leib –, und erweiset euch dankbar (dafür)!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 3, 16, 'Laßt das Wort Christi reichlich unter euch wohnen; belehrt und ermahnt einander in aller Weisheit, und singet Gott mit Psalmen, Lobgesängen und geistlichen Liedern, voller Dankbarkeit in euren Herzen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 3, 17, 'Und alles, was ihr mit Worten oder Werken tun mögt, das tut alles im Namen des Herrn Jesus, indem ihr eure Dankgebete durch seine Vermittlung vor Gott den Vater bringt.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 3, 18, 'Ihr Frauen, seid euren Männern untertan, wie es sich im Herrn gebührt! –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 3, 19, 'Ihr Männer, habt eure Frauen lieb und laßt euch nicht erbittern gegen sie! –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 3, 20, 'Ihr Kinder, seid euren Eltern in allen Stücken gehorsam, denn das ist wohlgefällig im Herrn. –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 3, 21, 'Ihr Väter, reizt eure Kinder nicht, damit sie nicht verdrossen werden! –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 3, 22, 'Ihr Knechte, seid euren leiblichen Herren in allen Stücken gehorsam, nicht mit Augendienerei als solche, die Menschen zu gefallen suchen, sondern in Aufrichtigkeit des Herzens als solche, die den (himmlischen) Herrn fürchten.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 3, 23, 'Alles, was ihr zu tun habt, das leistet mit willigem Herzen, als gälte es dem Herrn und nicht den Menschen;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 3, 24, 'ihr wißt ja, daß ihr vom Herrn das (himmlische) Erbe als Lohn empfangen werdet: ihr dient ja dem Herrn Christus als Knechte.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 3, 25, 'Wer dagegen unrecht tut, wird den Lohn für das, was er Unrechtes getan hat, empfangen; da gibt es kein Ansehen der Person. –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 4, 1, 'Ihr Herren, gewährt euren Knechten das, was recht und billig ist; ihr wißt ja, daß auch ihr einen Herrn im Himmel habt.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 4, 2, 'Haltet an am Gebet und seid wachsam dabei mit Danksagung.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 4, 3, 'Betet zugleich auch für uns, Gott möge uns die Möglichkeit zur Predigt des Wortes geben, damit wir das Geheimnis Christi, um dessen willen ich auch in Ketten gefesselt bin, verkündigen können');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 4, 4, 'und ich es so kundtue, wie meine Pflicht es erfordert.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 4, 5, 'Benehmt euch mit Weisheit im Verkehr mit denen, die draußen sind, und kauft die Zeit aus.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 4, 6, 'Eure Rede sei allezeit herzgewinnend, mit Salz gewürzt; ihr müßt wissen, wie ihr einem jeden zu antworten habt.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 4, 7, 'Über meine persönliche Lage wird euch der geliebte Bruder Tychikus berichten, mein treuer Gehilfe und Mitarbeiter im Herrn.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 4, 8, 'Ich habe ihn eben deswegen zu euch gesandt, damit ihr erfahrt, wie es um uns steht, und damit er eure Herzen ermutige.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 4, 9, 'In seiner Begleitung befindet sich Onesimus, der treue und geliebte Bruder, euer Landsmann; diese (beiden) werden euch berichten, wie hier alles steht.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 4, 10, 'Grüße sendet euch mein Mitgefangener Aristarchus, ebenso Markus, der Vetter des Barnabas, in betreff dessen ihr bereits (die erforderlichen) Aufträge erhalten habt – wenn er zu euch kommt, so nehmt ihn freundlich auf! –,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 4, 11, 'ferner Jesus, der den Beinamen Justus führt; diese drei sind die einzigen, die aus dem Judentum stammen und als meine Mitarbeiter am Reiche Gottes sich betätigen; sie sind mir ein rechter Trost geworden.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 4, 12, 'Es grüßt euch euer Landsmann Epaphras, ein Knecht Christi Jesu, der allezeit in seinen Gebeten für euch ringt, damit ihr in allem, was dem Willen Gottes entspricht, als Vollkommene und völlig Überzeugte dastehen möget.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 4, 13, 'Ja, ich muß ihm das Zeugnis geben, daß er sich um euch und um die (Brüder) in Laodizea und in Hierapolis viel Mühe gibt.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 4, 14, 'Es grüßt euch unser geliebter Lukas, der Arzt, und Demas.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 4, 15, 'Grüßet ihr die Brüder in Laodizea, auch Nymphas sowie die Gemeinde in ihrem Haus;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 4, 16, 'und wenn dieser Brief bei euch (vor)gelesen ist, so sorgt dafür, daß er auch in der Gemeinde von Laodizea zur Verlesung gelange und daß auch ihr den von Laodizea zu lesen bekommt.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 4, 17, 'Bestellt ferner dem Archippus: »Sei darauf bedacht, daß du den Dienst, den du im Herrn übernommen hast, gehörig ausrichtest!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 4, 18, 'Hier mein, des Paulus, eigenhändig geschriebener Gruß! Gedenket meiner Fesseln! Die Gnade sei mit euch!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 1, 1, 'Wir, Paulus, Silvanus und Timotheus, senden unsern Gruß der Gemeinde der Thessaloniker, (die) in (Gemeinschaft mit) Gott dem Vater und dem Herrn Jesus Christus (steht): Gnade sei (mit) euch und Friede!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 1, 2, 'Wir sagen Gott allezeit Dank im Hinblick auf euch alle, wenn wir euer mit Namensnennung in unseren Gebeten gedenken;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 1, 3, 'denn unablässig halten wir vor dem Angesicht unsers Gottes und Vaters die Erinnerung an euer tatkräftiges Glaubensleben fest sowie an eure eifrige Arbeit in der Liebe und an eure Standhaftigkeit in der Hoffnung auf unsern Herrn Jesus Christus.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 1, 4, 'Wir wissen ja, von Gott geliebte Brüder, daß ihr zu den Erwählten gehört;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 1, 5, 'denn unsere Verkündigung der Heilsbotschaft ist bei euch nicht allein im Wort erfolgt, sondern auch in Kraft und im heiligen Geist und in großer Zuversichtlichkeit; ihr wißt ja doch (noch gut), wie wir uns unter euch um euretwillen verhalten haben.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 1, 6, 'Und ihr seid unsere und (so auch) des Herrn Nachfolger geworden, nachdem ihr das Wort trotz schwerer Leiden mit der Freudigkeit angenommen hattet, die der heilige Geist wirkt,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 1, 7, 'so daß ihr für alle Gläubigen in Mazedonien und Achaja vorbildlich geworden seid.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 1, 8, 'Denn von euch aus hat das Wort des Herrn sich nicht nur in Mazedonien und Achaja mit lautem Schall verbreitet, nein, überallhin ist die Kunde von eurem Glauben an Gott gedrungen, so daß wir nicht nötig haben, etwas darüber zu sagen;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 1, 9, 'denn die Leute selbst erzählen im Hinblick auf uns, welchen Eingang wir bei euch gefunden haben und wie ihr euch von den Götzen hinweg zu Gott bekehrt habt, um (hinfort) dem lebendigen und wahren Gott zu dienen');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 1, 10, 'und seinen Sohn vom Himmel her zu erwarten, den er von den Toten auferweckt hat, Jesus, der uns vor dem kommenden Zorn(gericht) rettet.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 2, 1, 'Ihr wißt ja selbst, liebe Brüder, daß unser erstmaliges Auftreten bei euch nicht erfolglos gewesen ist;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 2, 2, 'sondern nachdem wir vorher, wie ihr wißt, in Philippi Leiden und Mißhandlungen hatten erdulden müssen, gewannen wir doch in unserm Gott den frohen Mut, die Heilsbotschaft Gottes unter schweren Kämpfen bei euch zu verkündigen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 2, 3, 'Denn unsere Predigt erfolgt nicht aus Schwärmerei oder unlauteren Absichten, auch nicht mit Hintergedanken;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 2, 4, 'nein, wie wir von Gott gewürdigt worden sind, mit der (Verkündigung der) Heilsbotschaft betraut zu werden, so reden wir nun auch, nicht um Menschen zu gefallen, sondern Gott, der unsere Herzen prüft.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 2, 5, 'Denn weder sind wir jemals, wie ihr wißt, mit Schmeichelworten umgegangen, noch mit versteckter Gewinnsucht – Gott ist unser Zeuge! –,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 2, 6, 'auch haben wir nicht Ehre von seiten der Menschen gesucht, weder von euch noch von anderen,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 2, 7, 'obgleich wir als Sendboten Christi sehr wohl Anspruch auf Ehren hätten erheben können; vielmehr sind wir unter euch sanft aufgetreten wie eine Amme, die ihre Kinder hegt und pflegt:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 2, 8, 'so fühlten wir uns in Liebe zu euch hingezogen und hegten den Wunsch, euch nicht nur die Heilsbotschaft Gottes, sondern auch unsere eigenen Seelen darzubringen; denn ihr waret uns lieb geworden.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 2, 9, 'Ihr erinnert euch doch noch, liebe Brüder, unserer Mühsal und Arbeitslast: während wir Tag und Nacht mit Handarbeit beschäftigt waren, um keinem von euch zur Last zu fallen, haben wir bei euch die Heilsbotschaft Gottes verkündigt.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 2, 10, 'Ihr seid unsere Zeugen, und auch Gott ist Zeuge dafür, wie pflichtgetreu, gerecht und untadelig wir uns gegen euch, die ihr gläubig (geworden) waret, verhalten haben,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 2, 11, 'wie wir – ihr wißt es ja – jeden einzelnen von euch wie ein Vater seine Kinder');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 2, 12, 'ermahnt und euch zugeredet und euch beschworen haben, ihr möchtet würdig des Gottes wandeln, der euch zu seinem Reich und zu seiner Herrlichkeit beruft.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 2, 13, 'Deshalb sagen wir auch Gott unablässig Dank dafür, daß ihr nach Empfang des von uns gepredigten Gotteswortes es nicht als Menschenwort angenommen habt, sondern als das, was es ja in der Tat ist, als Gottes Wort, das sich nun in euch, seitdem ihr gläubig seid, auch wirksam erweist.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 2, 14, 'Ihr seid ja, liebe Brüder, in die Nachfolge der Gottesgemeinden eingetreten, die im jüdischen Lande in Christus (gegründet) sind; denn auch ihr habt von euren eigenen Volksgenossen die gleichen Leiden erduldet wie jene von den Juden,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 2, 15, 'die sogar den Herrn Jesus getötet und die Propheten wie auch uns verfolgt haben. Die besitzen Gottes Wohlgefallen nicht und sind allen Menschen feindselig,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 2, 16, 'weil sie uns daran hindern (wollen), den Heiden zu ihrer Rettung zu predigen, um so nur ja das Maß ihrer Sünden jederzeit voll zu machen. Es ist aber der Zorn über sie hereingebrochen bis zum Äußersten.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 2, 17, 'Wir aber, liebe Brüder, da wir eine Zeitlang fern von euch verwaist waren – freilich nur (räumlich) dem Angesicht, nicht dem Herzen nach –, haben uns mit lebhaftem Verlangen um so eifriger bemüht, euch Auge in Auge wiederzusehen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 2, 18, 'Deshalb hatten wir uns vorgenommen, euch zu besuchen – ich, Paulus, sogar mehr als einmal –, doch der Satan hat uns nicht dazu kommen lassen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 2, 19, 'Denn wer ist unsere Hoffnung, unsere Freude und unser Ruhmeskranz, wenn nicht auch ihr es seid, vor dem Angesicht unsers Herrn Jesus bei seiner Ankunft?');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 2, 20, 'Ihr seid ja doch unser Ruhm und unsere Freude!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 3, 1, 'Daher, als wir es nicht länger aushalten konnten, entschlossen wir uns, in Athen allein zurückzubleiben,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 3, 2, 'und sandten Timotheus ab, unsern Bruder und Gottes Diener bei der (Verkündigung der) Heilsbotschaft von Christus: er sollte euch stärken und euch Zuspruch für euren Glauben bringen,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 3, 3, 'damit niemand in den gegenwärtigen Bedrängnissen wankend würde; ihr wißt ja selbst: dazu (zur standhaften Ertragung der Drangsale) sind wir bestimmt.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 3, 4, 'Denn schon damals, als wir noch bei euch waren, haben wir euch vorausgesagt, daß wir Drangsale würden erleiden müssen; und so ist es denn auch gekommen, ihr wißt es ja.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 3, 5, 'Deshalb habe ich auch, als ich es nicht länger aushalten konnte, (einen Boten) an euch abgeschickt, um Kunde über euren Glaubensstand zu erhalten, ob nicht etwa der Versucher euch in Versuchung geführt habe und unsere Arbeit damit vergeblich werden sollte.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 3, 6, 'Jetzt aber, nachdem Timotheus von euch zu uns zurückgekehrt ist und uns gute Botschaft von eurem Glauben und eurer Liebe gebracht und (uns berichtet hat,) daß ihr uns allezeit ein gutes Andenken bewahrt und euch nach einem Wiedersehen mit uns ebenso sehnet, wie auch wir uns nach euch sehnen,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 3, 7, 'so sind wir dadurch, was euch, liebe Brüder, betrifft, trotz aller unserer äußeren Not und Bedrängnis durch eure glaubenstreue wieder guten Mutes geworden;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 3, 8, 'denn jetzt haben wir wieder vollen Lebensmut, wenn ihr feststeht im Herrn.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 3, 9, 'Ja, wie könnten wir wohl Gott im Hinblick auf euch genug Dank als Gegengabe für all die Freude darbringen, mit der wir um euretwillen vor unserm Gott erfüllt sind?');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 3, 10, 'Bei Tag und bei Nacht bitten wir ihn deshalb aufs inständigste darum, er wolle uns vergönnen, euch von Angesicht zu Angesicht wiederzusehen und den Mängeln abzuhelfen, die eurem Glauben noch anhaften.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 3, 11, 'Ja, er selbst, unser Gott und Vater, und unser Herr Jesus wolle uns den Weg zu euch bahnen!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 3, 12, 'Euch aber lasse der Herr in der Liebe zueinander und zu allen Menschen wachsen und reich werden, wie auch wir euch gegenüber (von Liebe durchdrungen sind)!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 3, 13, 'Ja, er mache eure Herzen fest, damit sie vor unserm Gott und Vater tadellos in Heiligkeit seien, wenn unser Herr Jesus mit allen seinen Heiligen kommt!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 4, 1, 'Weiter nun, liebe Brüder, bitten und ermahnen wir euch in dem Herrn Jesus, daß ihr ganz so, wie ihr es von uns vernommen habt, auf welche Weise ihr wandeln und zu Gottes Wohlgefallen leben müßt, – ihr wandelt ja auch wirklich so –, daß ihr darin immer noch zunehmet;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 4, 2, 'ihr wißt ja, welche Weisungen wir euch im Auftrag des Herrn Jesus gegeben haben.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 4, 3, 'Denn das ist der Wille Gottes, eure Heiligung, daß ihr die Unzucht meidet,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 4, 4, 'daß ein jeder von euch wisse, sein eigenes Gefäß sich zu erwerben in Heiligkeit und Ehrbarkeit,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 4, 5, 'nicht in leidenschaftlicher Begierde wie die Heiden, die Gott nicht kennen,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 4, 6, 'daß niemand sich Übergriffe zuschulden kommen lasse und in Geschäften seinen Bruder übervorteile; denn ein Rächer ist der Herr über alle solche Verfehlungen, wie wir es euch schon früher gesagt und nachdrücklich bezeugt haben;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 4, 7, 'Gott hat uns ja nicht zur Unsittlichkeit berufen, sondern zur Heiligung.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 4, 8, 'Mithin wer (diese Weisungen) mißachtet, der mißachtet damit nicht einen Menschen, sondern Gott, denselben, der euch auch seinen heiligen Geist ins Herz gibt.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 4, 9, 'Was sodann die Bruderliebe betrifft, so brauchen wir euch über diese nicht brieflich zu unterweisen, denn ihr seid selber von Gott gelehrt worden, einander zu lieben,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 4, 10, 'und ihr beweist das auch durch die Tat an allen Brüdern in ganz Mazedonien. Doch ermahnen wir euch, liebe Brüder, darin noch vollkommener zu werden');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 4, 11, 'und eure Ehre darin zu suchen, daß ihr ein ruhiges Leben führt, euren eigenen Geschäften nachgeht und euch euer Brot mit eurer Hände Arbeit verdient. So haben wir es euch geboten,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 4, 12, 'damit ihr im Verkehr mit den Draußenstehenden einen ehrbaren Wandel führt und niemandes Unterstützung nötig habt.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 4, 13, 'Wir wollen euch aber, liebe Brüder, über die Entschlafenen nicht im unklaren lassen, damit ihr nicht betrübt zu sein braucht wie die anderen, die keine Hoffnung haben.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 4, 14, 'Denn so gewiß wir glauben, daß Jesus gestorben und auferstanden ist, ebenso gewiß wird Gott auch die Entschlafenen durch Jesus mit ihm zusammen (den gleichen Weg) führen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 4, 15, 'Denn das sagen wir euch aufgrund eines Wortes des Herrn: Wir, die wir leben, die wir bis zur Ankunft des Herrn übrigbleiben, werden vor den Entschlafenen nichts voraushaben.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 4, 16, 'Denn der Herr selbst wird, sobald sein Weckruf ergeht, sobald die Stimme des Engelfürsten erschallt und die Posaune Gottes ertönt, vom Himmel herabkommen, und die Toten in Christus werden zuerst auferstehen;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 4, 17, 'darauf werden wir, die wir noch leben und übriggeblieben sind, zusammen mit ihnen auf Wolken dem Herrn entgegen in die Luft entrückt werden; und alsdann werden wir allezeit mit dem Herrn vereinigt sein.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 4, 18, 'So tröstet euch also untereinander mit diesen Worten!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 5, 1, 'Was aber die Zeit und die Stunde betrifft, so bedürft ihr, liebe Brüder, darüber keiner schriftlichen Belehrung;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 5, 2, 'ihr wißt ja selber genau, daß der Tag des Herrn so kommt wie ein Dieb in der Nacht.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 5, 3, 'Wenn sie sagen: »Jetzt herrscht Friede und Sicherheit«, (gerade) dann überfällt sie das Verderben plötzlich wie die Wehen eine schwangere Frau, und sie werden sicherlich nicht entrinnen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 5, 4, 'Ihr aber, liebe Brüder, lebt nicht in Finsternis, daß der Tag (des Herrn) euch wie ein Dieb überraschen könnte;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 5, 5, 'denn ihr alle seid Söhne des Lichts und Söhne des Tages: wir haben mit der Nacht und der Finsternis nichts zu schaffen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 5, 6, 'Laßt uns also nicht schlafen wie die anderen, sondern wachsam und nüchtern sein!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 5, 7, 'Denn die Schläfer schlafen bei Nacht, und die sich berauschen, sind bei Nacht trunken;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 5, 8, 'wir aber, die wir dem Tage angehören, wollen nüchtern bleiben, angetan mit dem Panzer des Glaubens und der Liebe und mit dem Helm der Hoffnung auf Rettung;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 5, 9, 'denn uns hat Gott nicht für das Zorngericht bestimmt, sondern dazu, daß wir die Rettung durch unsern Herrn Jesus Christus erlangen,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 5, 10, 'der für uns gestorben ist, damit wir, mögen wir (bei seinem Kommen noch) wachen oder (schon) entschlafen sein, vereint mit ihm leben.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 5, 11, 'Darum ermahnt euch gegenseitig und erbauet euch einer den andern, wie ihr das ja auch tut!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 5, 12, 'Wir bitten euch aber, liebe Brüder, denen Anerkennung zu zollen, die bei euch die Arbeiten besorgen und eure Vorsteher und eure Seelsorger im Herrn sind;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 5, 13, 'haltet sie ganz besonders lieb und wert um ihrer Arbeit willen! Haltet Frieden untereinander!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 5, 14, 'Sodann ermahnen wir euch, liebe Brüder: Weiset die Unordentlichen zurecht, ermutigt die Verzagten, nehmt euch der Schwachen an, verfahrt mit Geduld gegen alle!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 5, 15, 'Achtet darauf, daß niemand einem andern Böses mit Bösem vergelte, befleißigt euch vielmehr allezeit des Guten gegeneinander und gegen alle (Menschen)!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 5, 16, 'Seid allezeit fröhlich,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 5, 17, 'betet ohne Unterlaß,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 5, 18, 'sagt in jeder Lage Dank, denn so will es Gott von euch in Christus Jesus.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 5, 19, 'Den (heiligen) Geist laßt in euch nicht erlöschen;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 5, 20, 'prophetische Reden verachtet nicht.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 5, 21, 'Prüfet alles, behaltet das Gute;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 5, 22, 'meidet das Böse in jeder Gestalt!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 5, 23, 'Er selbst aber, der Gott des Friedens, heilige euch durch und durch, und völlig tadellos möge euer Geist samt der Seele und dem Leibe bei der Wiederkunft unsers Herrn Jesus Christus bewahrt geblieben sein!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 5, 24, 'Treu ist er, der euch beruft: er wird es auch vollführen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 5, 25, 'Liebe Brüder, betet für uns! Grüßet alle Brüder mit dem heiligen Kuß!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 5, 26, 'Ich beschwöre euch beim Herrn:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 5, 27, 'laßt diesen Brief zur Vorlesung bei allen Brüdern kommen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 5, 28, 'Die Gnade unsers Herrn Jesus Christus sei mit euch!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 1, 1, 'Wir, Paulus, Silvanus und Timotheus, senden unsern Gruß der Gemeinde der Thessaloniker in Gott, unserm Vater, und dem Herrn Jesus Christus.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 1, 2, 'Gnade sei (mit) euch und Friede von Gott dem Vater und dem Herrn Jesus Christus!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 1, 3, 'Wir sind Gott allezeit zur Danksagung für euch, liebe Brüder, verpflichtet; das ist recht und billig, weil euer Glaube überaus kräftig wächst und die brüderliche Liebe bei jedem einzelnen von euch allen zunimmt,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 1, 4, 'so daß wir selbst uns in den Gemeinden Gottes euer rühmen wegen eurer Standhaftigkeit und Glaubenstreue in allen euren Verfolgungen und den Leiden, die ihr zu erdulden habt.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 1, 5, 'Darin liegt ein Hinweis auf das gerechte Gericht Gottes, daß ihr nämlich des Reiches Gottes würdig erachtet werdet, um dessen willen ihr eben zu leiden habt.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 1, 6, 'Denn das entspricht doch sicherlich der Gerechtigkeit Gottes, euren Bedrängern mit Drangsal zu vergelten,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 1, 7, 'euch aber, den Bedrängten, Erquickung in Gemeinschaft mit uns zuteil werden zu lassen, wenn der Herr Jesus sich vom Himmel her mit den Engeln seiner Macht');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 1, 8, 'in loderndem Feuer offenbart, um Vergeltung an denen zu üben, die Gott nicht (aner)kennen, und an denen, die der Heilsbotschaft unsers Herrn Jesus kein Gehör schenken.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 1, 9, 'Diese werden als Strafe ewiges Verderben erleiden fern vom Angesicht des Herrn und fern von der Herrlichkeit seiner Kraft,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 1, 10, 'wenn er kommen wird, um unter seinen Heiligen verherrlicht zu werden und Bewunderung zu finden bei allen, die gläubig geworden sind – denn bei euch hat unser Zeugnis Glauben gefunden –, an jenem Tage.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 1, 11, 'Im Hinblick hierauf beten wir auch allezeit für euch, unser Gott möge euch der (endgültigen) Berufung für würdig erachten und alle Freude am Guten und die Glaubensarbeit (in euch) kraftvoll zur Vollendung bringen,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 1, 12, 'damit der Name unsers Herrn Jesus in euch verherrlicht werde und ihr in ihm, wie es der Gnade unsers Gottes und des Herrn Jesus Christus entspricht.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 2, 1, 'Wir richten aber in betreff der Ankunft unsers Herrn Jesus Christus und unserer Vereinigung mit ihm eine Bitte an euch, liebe Brüder:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 2, 2, 'Laßt euch nicht leichthin aus der ruhigen Überlegung in Aufregung versetzen und euch durch nichts erschrecken, weder durch eine Geistesoffenbarung noch durch (Berufung auf) eine Äußerung oder einen Brief, die angeblich von uns herrühren, als ob der Tag des Herrn schon da wäre.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 2, 3, 'Laßt euch von niemand auf irgendeine Weise täuschen; denn zunächst muß ja doch der Abfall eintreten und der Mensch der Gesetzlosigkeit erschienen sein, der Sohn des Verderbens,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 2, 4, 'der Widersacher, der sich über alles erhöht, was Gott oder anbetungswürdig heißt, so daß er sich sogar in den Tempel Gottes setzt und sich für Gott ausgibt.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 2, 5, 'Erinnert ihr euch nicht, daß ich euch dies schon während meiner Anwesenheit bei euch wiederholt gesagt habe?');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 2, 6, 'Und was die Gegenwart betrifft, so wißt ihr doch, was ihn noch zurückhält, damit er sich zu der für ihn bestimmten Zeit offenbaren kann.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 2, 7, 'Freilich – im geheimen ist die (Macht der) Gesetzlosigkeit bereits wirksam; nur muß erst der aus dem Wege geräumt werden, der sie bis jetzt noch zurückhält.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 2, 8, 'Dann erst wird der Gesetzlose offen hervortreten, den der Herr Jesus aber durch den Hauch seines Mundes wegraffen und durch den Eintritt seiner Ankunft vernichten wird,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 2, 9, 'ihn, dessen Auftreten sich als Wirksamkeit des Satans kundgibt durch alle möglichen Machttaten, Zeichen und Wunder der Lüge');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 2, 10, 'und durch jede Art von Trug der Ungerechtigkeit für die, welche deshalb verlorengehen, weil sie die Liebe zur Wahrheit sich nicht zu eigen gemacht haben, um ihre Rettung zu erlangen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 2, 11, 'Und aus diesem Grunde sendet Gott ihnen einen starken Irrwahn, damit sie der Lüge Glauben schenken;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 2, 12, 'denn alle sollen dem Gericht verfallen, die nicht der Wahrheit Glauben geschenkt, sondern Wohlgefallen an der Ungerechtigkeit gefunden haben.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 2, 13, 'Wir aber sind verpflichtet, Gott für euch, vom Herrn geliebte Brüder, allezeit Dank zu sagen, weil Gott euch von Anfang an zur Errettung erwählt hat durch die vom Geist gewirkte Heiligung und durch den Glauben an die Wahrheit.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 2, 14, 'Dazu hat er euch ja auch durch unsere Heilsverkündigung berufen, damit ihr (einst) die Herrlichkeit unsers Herrn Jesus Christus erlangt.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 2, 15, 'So stehet denn fest, liebe Brüder, und haltet euch an die überlieferten Lehren, die euch, sei es mündlich, sei es brieflich, von uns übermittelt worden sind.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 2, 16, 'Er selbst aber, unser Herr Jesus Christus, und Gott, unser Vater, der uns geliebt und uns einen ewigen Trost und eine gute Hoffnung in Gnaden geschenkt hat,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 2, 17, 'der tröste eure Herzen und mache sie stark in jedem guten Werk und Wort!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 3, 1, 'Im übrigen, liebe Brüder, betet für uns, daß das Wort des Herrn laufe und in seiner Herrlichkeit offenbar werden möge, wie bei euch,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 3, 2, 'und daß wir von den verkehrten und bösartigen Menschen errettet werden; denn der Glaube ist nicht jedermanns Sache.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 3, 3, 'Treu aber ist der Herr, der euch stärken und vor dem Bösen behüten wird.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 3, 4, 'Wir haben aber im Herrn das Vertrauen zu euch, daß ihr unsern Weisungen nachkommt und immer nachkommen werdet.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 3, 5, 'Der Herr aber lenke eure Herzen zur Liebe Gottes und zum standhaften Ausharren Christi!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 3, 6, 'Wir gebieten euch aber, liebe Brüder, im Namen des Herrn Jesus Christus: ziehet euch von jedem Bruder zurück, der einen unordentlichen Lebenswandel führt und nicht nach der Unterweisung, die ihr von uns empfangen habt.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 3, 7, 'Ihr wißt ja selbst, wie ihr uns zum Vorbild nehmen sollt; denn wir haben unter euch keinen unordentlichen Wandel geführt,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 3, 8, 'haben auch nicht unentgeltlich jemandes Brot gegessen, sondern haben Tag und Nacht angestrengt und mühselig gearbeitet, um keinem von euch zur Last zu fallen;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 3, 9, 'nicht als ob wir nicht das Recht dazu hätten, nein wir wollten euch an uns ein Vorbild geben, damit ihr uns nachfolgen solltet.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 3, 10, 'Denn schon während unsers Aufenthalts bei euch haben wir euch dieses Gebot gegeben: »Wenn einer nicht arbeiten will, dann soll er auch nicht essen!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 3, 11, 'Es ist uns nämlich zu Ohren gekommen, daß manche unter euch einen unordentlichen Lebenswandel führen, indem sie, statt zu arbeiten, sich unnütz umhertreiben.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 3, 12, 'Solchen Leuten schärfen wir aber nachdrücklich im Herrn Jesus Christus ein, daß sie sich ihr eigenes Brot in stiller Arbeit selbst verdienen sollen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 3, 13, 'Ihr (anderen) aber, liebe Brüder, werdet nicht müde, das Rechte zu tun.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 3, 14, 'Sollte jemand aber dieser unserer brieflichen Weisung nicht nachkommen, so merkt ihn euch und meidet den Verkehr mit ihm, damit er in sich gehe;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 3, 15, 'doch sehet in ihm keinen Feind, sondern weist ihn als einen Bruder zurecht.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 3, 16, 'Er selbst aber, der Herr des Friedens, gebe euch seinen Frieden immerdar auf alle Weise! Der Herr sei mit euch allen!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 3, 17, 'Hier mein, des Paulus, eigenhändiger Gruß! Dies ist das (beglaubigende) Kennzeichen in jedem meiner Briefe: so schreibe ich!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 3, 18, 'Die Gnade unsers Herrn Jesus Christus sei mit euch allen!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 1, 1, 'Ich, Paulus, ein Apostel Christi Jesu nach dem Auftrage Gottes, unsers Retters, und Christi Jesu, der unsere Hoffnung ist,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 1, 2, 'sende meinen Gruß dem Timotheus, meinem echten Sohn im Glauben: Gnade, Barmherzigkeit und Friede (sei mit dir) von Gott dem Vater und unserm Herrn Christus Jesus!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 1, 3, 'Ich habe dich bei meiner Abreise nach Mazedonien aufgefordert, noch länger in Ephesus zu bleiben, damit du gewissen Leuten gebieten möchtest, keine fremden Lehren vorzutragen');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 1, 4, 'und sich nicht mit Fabeln und endlosen Geschlechtsverzeichnissen zu befassen, die ja doch eher Anlaß zu spitzfindigen Untersuchungen als zu einer im Glauben sich vollziehenden Wirksamkeit eines Haushalters Gottes geben.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 1, 5, 'Das Endziel der Heilsverkündigung ist aber Liebe, die aus reinem Herzen und gutem Gewissen und ungeheucheltem Glauben stammt.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 1, 6, 'Davon sind manche abgeirrt und haben sich leerem Geschwätz zugewandt;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 1, 7, 'sie wollen Belehrung über das Gesetz erteilen, ohne doch das nötige Verständnis für das zu besitzen, was sie vortragen, und ebensowenig für das, worüber sie zuversichtliche Behauptungen aufstellen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 1, 8, 'Wir wissen aber, daß das Gesetz gut ist, wenn man es richtig anwendet,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 1, 9, 'nämlich in der Erkenntnis, daß für einen Gerechten das Gesetz überhaupt nicht da ist, sondern für Gesetzlose und Unbotmäßige, für Gottlose und Sünder, für Unfromme und solche, denen nichts heilig ist, für Menschen, die sich an Vater und Mutter vergreifen, für Mörder,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 1, 10, 'Unzüchtige, Knabenschänder, Menschenverkäufer, Lügner, Meineidige und was sonst noch in Widerspruch mit der gesunden Lehre steht,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 1, 11, 'wie sie die Heilsbotschaft von der Herrlichkeit des seligen Gottes darbietet, mit deren Verkündigung ich betraut worden bin.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 1, 12, 'Dankbar bin ich dem, der mich stark gemacht hat, unserm Herrn Christus Jesus, dafür, daß er mich für treu erachtet hat, als er mich in seinen Dienst einsetzte,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 1, 13, 'obgleich ich früher doch ein Lästerer (seines Namens), ein Verfolger und gewalttätiger Frevler gewesen war. Doch mir ist Barmherzigkeit widerfahren, weil ich unbewußt so gehandelt hatte in ungläubigem Zustand.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 1, 14, 'Ja, die Gnade unsers Herrn hat sich überschwenglich wirksam an mir erwiesen im Verein mit dem Glauben und der Liebe, die in Christus Jesus wurzeln.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 1, 15, 'Zuverlässig ist das Wort und wert, daß alle es annehmen: »Christus Jesus ist in die Welt gekommen, um Sünder zu retten«, unter denen ich der erste bin.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 1, 16, 'Aber gerade deshalb ist mir Barmherzigkeit widerfahren, weil Christus Jesus an mir als dem ersten die ganze Fülle seiner Langmut erweisen wollte, um an mir vorbildlich darzustellen, was für Menschen künftighin durch den Glauben an ihn zum ewigen Leben gelangen würden.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 1, 17, 'Ihm aber, dem Könige der Weltzeiten, dem unvergänglichen, unsichtbaren, alleinigen Gott, sei Ehre und Verherrlichung in alle Ewigkeiten! Amen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 1, 18, 'Diese Anweisung lege ich dir, mein Kind Timotheus, im Anschluß an die früher über dich ergangenen prophetischen Aussprüche ans Herz: Kämpfe in ihrer Kraft den guten Kampf,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 1, 19, 'indem du am Glauben festhältst und dir ein gutes Gewissen bewahrst! Von diesem haben sich manche leider gewaltsam losgesagt und dadurch am Glauben Schiffbruch erlitten,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 1, 20, 'wie z.B. Hymenäus und Alexander, die ich dem Satan übergeben habe, damit sie durch seine Züchtigung das Lästern verlernen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 2, 1, 'So spreche ich denn zu allererst die Mahnung aus, daß man Bitten und Gebete, Fürbitten und Danksagungen für alle Menschen verrichte,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 2, 2, 'für Könige und alle obrigkeitlichen Personen, damit wir ein stilles und ruhiges Leben in aller Gottseligkeit und Ehrbarkeit führen können.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 2, 3, 'So ist es löblich und wohlgefällig vor Gott, unserm Retter,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 2, 4, 'dessen Wille es ist, daß alle Menschen gerettet werden und zur Erkenntnis der Wahrheit kommen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 2, 5, 'Denn es ist (nur) ein Gott, ebenso auch (nur) ein Mittler zwischen Gott und den Menschen, nämlich ein Mensch Christus Jesus,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 2, 6, 'der sich selbst als Lösegeld für alle dahingegeben hat – das Zeugnis, (das) zu den festgesetzten Zeiten (verkündigt worden ist).');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 2, 7, 'Für dieses (Zeugnis) bin ich zum Herold und Apostel bestellt worden – ich sage die Wahrheit, ich lüge nicht –: zum Lehrer der Heiden im Glauben und in der Wahrheit.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 2, 8, 'Mein Wille ist nun, daß die Männer an jedem Versammlungsort beten sollen, indem sie heilige Hände aufheben, frei von Zorn und Zweifel.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 2, 9, 'Ebenso (will ich), daß die Frauen in züchtiger Kleidung im Verein mit Schamhaftigkeit und Sittsamkeit sich schmücken, nicht mit Haargeflechten und Goldzierat, mit Perlen oder kostbaren Gewändern,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 2, 10, 'sondern, wie es sich für Frauen geziemt, welche Gottesfurcht an den Tag legen wollen, mit guten Werken.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 2, 11, 'Die Frau suche (beim Gottesdienst) Belehrung durch stilles Zuhören in aller Unterordnung;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 2, 12, 'dagegen gestatte ich keiner Frau, Lehrvorträge zu halten oder sich die Gewalt über den Mann anzumaßen; nein, sie soll in stiller Zurückhaltung verbleiben.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 2, 13, 'Denn Adam ist zuerst geschaffen worden, danach erst Eva;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 2, 14, 'auch hat nicht Adam sich verführen lassen, sondern die Frau ist dadurch, daß sie sich hat verführen lassen, in Übertretung geraten.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 2, 15, 'Sie wird jedoch dadurch gerettet werden, daß sie Kindern das Leben gibt, vorausgesetzt, daß sie im Glauben, in der Liebe und in einer mit Besonnenheit vollzogenen Heiligung verharren.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 3, 1, 'Zutreffend ist das Wort: »Wer nach dem Vorsteheramt strebt, begehrt eine köstliche Wirksamkeit.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 3, 2, 'So muß denn der Vorsteher unbescholten sein, eines Weibes Mann, nüchtern, besonnen, ehrbar, gastfrei, ein tüchtiger Lehrer,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 3, 3, 'kein Trinker und kein Händelsucher, sondern freundlich, frei von Streitsucht und Geldgier,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 3, 4, 'ein Mann, der seinem eigenen Hause gut vorsteht, indem er seine Kinder in Zucht hält mit aller Würde;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 3, 5, 'denn wenn jemand seinem eigenen Hause nicht vorzustehen weiß, wie sollte der für eine Gemeinde Gottes sorgen können?');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 3, 6, 'Er darf auch kein Neubekehrter sein, sonst könnte er leicht in Hochmut geraten und der Beurteilung des Verleumders anheimfallen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 3, 7, 'Er muß sich aber auch bei denen, die draußen sind, eines guten Rufes erfreuen, damit er nicht in üble Nachrede gerät und in die Schlinge des Verleumders.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 3, 8, 'Ebenso müssen auch die Gehilfen ehrbare Männer sein, nicht doppelzüngig, nicht übermäßigem Weingenuß oder häßlicher Gewinnsucht ergeben;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 3, 9, 'Männer, die das Geheimnis des Glaubens in einem reinen Gewissen bewahren.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 3, 10, 'Aber auch sie sollen zunächst einer Prüfung unterzogen werden und erst dann den Dienst ausüben, wenn sie unbescholten (erfunden) sind.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 3, 11, 'Ebenso müssen auch ihre Frauen ehrbar sein, nicht klatschsüchtig, nüchtern, zuverlässig in allen Beziehungen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 3, 12, 'Die Gehilfen sollen jeder nur eines Weibes Mann sein und müssen die Leitung ihrer Kinder und ihres eigenen Hauswesens gut versehen;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 3, 13, 'denn die, welche den Dienst als Gehilfen gut versehen haben, erwerben sich dadurch eine wertvolle Vertrauensstellung und das Recht, im Vertrauen auf Christus Jesus mit voller Zuversicht aufzutreten.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 3, 14, 'Dies schreibe ich dir in der Hoffnung, recht bald zu dir kommen zu können;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 3, 15, 'sollte sich mein Kommen jedoch verzögern, so sollst du dir klar darüber sein, wie man sich im Hause Gottes zu verhalten hat, das da ist die Gemeinde des lebendigen Gottes, die Säule und Grundfeste der Wahrheit.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 3, 16, 'Und etwas unbestreitbar Großes ist das Geheimnis der Gottseligkeit: »Er, der geoffenbart ist im Fleisch, als gerecht erwiesen im Geist, erschienen den Sendboten, verkündigt unter den Völkern, gläubig angenommen in der Welt, emporgehoben in die Herrlichkeit.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 4, 1, 'Der Geist aber kündigt ausdrücklich an, daß in späteren Zeiten manche vom Glauben abfallen werden, weil sie sich irreführenden Geistern und Lehren, die von Dämonen herrühren, zuwenden,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 4, 2, 'verführt durch das heuchlerische Gebaren von Lügenrednern, die das Brandmal der Schuld im eigenen Gewissen tragen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 4, 3, 'Es sind dies Leute, die das Heiraten verbieten und Enthaltsamkeit von Speisen (gebieten), welche Gott doch dazu geschaffen hat, daß die Gläubigen und alle, welche die Wahrheit erkannt haben, sie mit Danksagung genießen sollen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 4, 4, 'Denn alles von Gott Geschaffene ist gut, und nichts (davon) ist verwerflich, wenn man es mit Danksagung hinnimmt;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 4, 5, 'es wird ja durch das Wort Gottes und durch Gebet geheiligt.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 4, 6, 'Wenn du dieses den Brüdern vorhältst, wirst du ein löblicher Diener Christi Jesu sein, weil du zu deiner Speise die Worte des Glaubens und der guten Lehre machst, die du dir zur Richtschnur genommen hast.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 4, 7, 'Aber die wertlosen und nur den alten Weibern zusagenden Fabeln weise zurück; übe dich dagegen zur Gottseligkeit.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 4, 8, 'Denn die dem Leibe gewidmete Übung bringt nur geringen Nutzen; die Gottseligkeit aber ist zu allen Dingen nütze, weil sie die Verheißung für das gegenwärtige wie für das zukünftige Leben hat.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 4, 9, 'Zuverlässig ist das Wort und wert, daß alle es anerkennen;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 4, 10, 'denn dafür mühen wir uns ab und lassen auch Schmähungen über uns ergehen, weil wir unsere Hoffnung auf den lebendigen Gott gesetzt haben, der ein Retter aller Menschen ist, zumal der Gläubigen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 4, 11, 'Dies schärfe ein und lehre!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 4, 12, 'Niemand soll dir wegen deiner Jugend die gebührende Achtung versagen; werde du vielmehr ein Vorbild für die Gläubigen in Wort und Wandel, in der Liebe wie im Glauben und in der Sittenreinheit.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 4, 13, 'Bis zu meiner Ankunft fahre fort mit dem Vorlesen (der heiligen Schrift), mit den ermahnenden Ansprachen, mit der Lehrtätigkeit!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 4, 14, 'Laß die dir zu Gebot stehende Gnadengabe nicht unbetätigt, die dir durch prophetische Verheißung unter Handauflegung der Ältestenschaft verliehen worden ist.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 4, 15, 'Dies laß dir angelegen sein, hierin lebe: alle müssen wahrnehmen können, welche Fortschritte du darin machst.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 4, 16, 'Gib auf dich selbst und auf die Lehre acht, halte daran fest; denn wenn du das tust, wirst du sowohl dich selbst als auch deine Hörer retten.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 5, 1, 'Einen älteren Mann fahre nicht hart an, sondern rede mahnend zu ihm wie zu einem Vater; jüngere Männer ermahne wie Brüder,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 5, 2, 'ältere Frauen wie Mütter, jüngere wie Schwestern in aller Sittsamkeit.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 5, 3, 'Witwen, die wirklich Witwen sind, begegne mit Ehrerbietung;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 5, 4, 'wenn aber eine Witwe Kinder oder Enkel hat, so sollen diese lernen, an erster Stelle gegen ihre eigene Familie liebevoll zu handeln und ihren gealterten Angehörigen die empfangenen Wohltaten zu vergelten, denn das ist wohlgefällig vor Gott.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 5, 5, 'Eine wirkliche Witwe aber, die ganz allein steht, hat ihre Hoffnung auf Gott gesetzt und verharrt in ihren Bitten und Gebeten bei Tag und Nacht;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 5, 6, 'wenn eine Witwe dagegen in Üppigkeit lebt, so ist sie schon bei Lebzeiten tot.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 5, 7, 'Auch dies schärfe ihnen ein, damit sie sich unsträflich halten!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 5, 8, 'Wenn aber jemand seine Angehörigen, zumal wenn sie seine Hausgenossen sind, nicht versorgt, so hat er damit den Glauben verleugnet und ist schlimmer als ein Ungläubiger.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 5, 9, 'Eine Witwe soll nur dann in das Verzeichnis (der von der Gemeinde zu versorgenden Witwen) eingetragen werden, wenn sie mindestens sechzig Jahre alt ist, nur eines Mannes Ehefrau gewesen');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 5, 10, 'und durch gute Werke wohl bezeugt ist, insofern sie nämlich Kinder großgezogen, Gastfreundschaft gegen Fremde geübt, Heiligen die Füße gewaschen, Bedrängten Hilfe geleistet hat, überhaupt guten Werken aller Art eifrig nachgegangen ist.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 5, 11, 'Jüngere Witwen dagegen weise zurück; denn wenn sie im Gegensatz zur Hingabe an Christus sinnlich erregt geworden sind, wollen sie wieder heiraten,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 5, 12, 'obgleich sie dadurch ein Schuldurteil auf sich lasten haben, weil sie das erste Treuegelöbnis gebrochen haben.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 5, 13, 'Da sie zugleich beschäftigungslos sind, gewöhnen sie sich daran, in den Häusern umherzulaufen, und sind dann nicht nur beschäftigungslos, sondern führen auch bei ihrer Geschwätzigkeit und Neugier ungehörige Reden.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 5, 14, 'Es ist daher mein Wille, daß die jüngeren (Witwen wieder) heiraten, Mütter werden, ihrem Haushalt vorstehen und dem Widersacher keinen Anlaß zu übler Nachrede geben;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 5, 15, 'manche sind ja leider schon vom rechten Wege abgewichen und dem Satan nachgefolgt.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 5, 16, 'Wenn eine gläubige Frau Witwen (in ihrer Verwandtschaft) hat, so soll sie für deren Bedarf sorgen, die Gemeinde aber soll unbelastet bleiben, damit sie sich der wirklichen Witwen ausreichend annehmen kann.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 5, 17, 'Die Ältesten, die sich in ihrem Vorsteheramt bewähren, sollen doppelter Ehre würdig geachtet werden, besonders die, welche als Prediger und Lehrer mit Eifer tätig sind;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 5, 18, 'denn die Schrift sagt: »Du sollst einem Ochsen beim Dreschen das Maul nicht verbinden« und: »Der Arbeiter ist seines Lohnes wert.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 5, 19, 'Gegen einen Ältesten nimm keine Klage an, außer aufgrund der Aussagen von zwei oder drei Zeugen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 5, 20, 'Solche, die sich etwas zuschulden kommen lassen, weise in Gegenwart aller (Ältesten) zurecht, damit auch die übrigen (Ältesten) Furcht bekommen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 5, 21, 'Ich beschwöre dich vor dem Angesicht Gottes und des Herrn Christus Jesus und der auserwählten Engel: befolge diese Weisungen ohne Vorurteil und handle in keinem Fall nach Gunst.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 5, 22, 'Die Handauflegung erteile niemandem übereilt, und mache dich (dadurch) nicht zum Mitschuldigen fremder Sünden; erhalte dich selbst rein!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 5, 23, 'Trinke nicht mehr immer nur Wasser, sondern nimm etwas Wein hinzu wegen deines Magens und deiner häufigen Schwächeanfälle. –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 5, 24, 'Bei manchen Menschen liegen die Sünden offenkundig zutage und treten für die Beurteilung schon vorher hervor; bei manchen werden sie aber auch erst hinterdrein bekannt.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 5, 25, 'Ebenso sind auch die guten Werke offenkundig, und die, bei denen das nicht der Fall ist, können (auf die Dauer) doch nicht verborgen bleiben.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 6, 1, 'Alle, die als Sklaven unter dem Joch (der Knechtschaft) stehen, sollen ihre Herren aller Ehrerbietung würdig achten, damit der Name Gottes und die (christliche) Lehre nicht gelästert werden.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 6, 2, 'Diejenigen aber unter ihnen, welche Gläubige zu Herren haben, sollen diesen deshalb nicht mit Geringschätzung entgegentreten, weil sie Brüder sind, sondern sollen ihren Dienst um so eifriger versehen, weil sie es mit Gläubigen und Gottgeliebten zu tun haben, die sich des Wohltuns befleißigen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 6, 3, 'Dieses lehre und schärfe es ein: Wer anders lehrt und sich nicht an die gesunden Worte unsers Herrn Jesus Christus und an die Lehre hält, welche der Gottseligkeit dient,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 6, 4, 'der ist von Hochmut verblendet und versteht in Wirklichkeit nichts, sondern krankt an der Sucht nach spitzfindigen Untersuchungen und Wortgezänk, aus denen nur Neid und Streit, Schmähungen, boshafte Verdächtigungen');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 6, 5, 'und fortwährende Zänkereien von Menschen entstehen, die geistig zerrüttet sind und (den Sinn für) die Wahrheit verloren haben, weil sie in der Gottseligkeit eine Erwerbsquelle sehen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 6, 6, 'Allerdings ist die Gottseligkeit eine reiche Erwerbsquelle, nämlich in Verbindung mit Genügsamkeit;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 6, 7, 'denn wir haben nichts (mit uns) in die Welt hineingebracht; so können wir auch nichts aus ihr mit hinausnehmen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 6, 8, 'Haben wir also Nahrung und Kleidung, so wollen wir uns daran genügen lassen;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 6, 9, 'denn die, welche um jeden Preis reich werden wollen, geraten in Versuchung und in eine Schlinge und in viele törichte und schädliche Begierden, welche die Menschen in Untergang und Verderben stürzen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 6, 10, 'Denn eine Wurzel alles Bösen ist die Geldgier; gar manche, die sich ihr ergeben haben, sind vom Glauben abgeirrt und zermartern sich selbst mit vielen qualvollen Schmerzen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 6, 11, 'Du aber, Mann Gottes, halt dich von diesem (allem) fern. Trachte vielmehr nach Gerechtigkeit und Gottseligkeit, nach Glauben und Liebe, nach Standhaftigkeit und Sanftmut!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 6, 12, 'Kämpfe den guten Kampf des Glaubens, ergreife das ewige Leben, zu dem du berufen bist und für das du das herrliche Bekenntnis vor vielen Zeugen abgelegt hast.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 6, 13, 'Ich gebiete dir vor dem Angesicht Gottes, der alles Leben schafft, und vor Christus Jesus, der vor Pontius Pilatus das herrliche Bekenntnis abgelegt hat:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 6, 14, 'Führe den (dir erteilten) Auftrag so aus, daß du ohne Flecken, ohne Tadel bleibst bis zur Erscheinung unsers Herrn Jesus Christus,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 6, 15, 'die der selige und alleinige Machthaber zur festgesetzten Zeit eintreten lassen wird, er, der König der Könige und der Herr der Herren,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 6, 16, 'der allein Unsterblichkeit besitzt, der da wohnt in einem unzugänglichen Licht, den kein Mensch gesehen hat noch zu sehen vermag: ihm gebührt Ehre und Macht! Amen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 6, 17, 'Denen, die Reichtum in der jetzigen Weltzeit besitzen, schärfe ein, daß sie sich nicht überheben und ihre Hoffnung nicht auf die Unsicherheit des Reichtums setzen, sondern auf Gott, der uns alles reichlich zum Genießen darbietet.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 6, 18, '(Schärfe ihnen ein,) Gutes zu tun, reich an guten Werken zu sein, Freigebigkeit und Mildtätigkeit zu üben');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 6, 19, 'und sich dadurch ein gutes Grundvermögen für die Zukunft anzulegen, damit sie das wirkliche Leben erlangen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 6, 20, 'O Timotheus, nimm das dir anvertraute Gut in treue Hut und meide das unfromme leere Geschwätz und die Streitsätze der mit Unrecht so genannten »Erkenntnis«!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 6, 21, 'Manche sind schon dadurch, daß sie sich zu ihr bekannten, im Glauben auf Abwege geraten. Die Gnade sei mit euch!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 1, 1, 'Ich, Paulus, ein Apostel Christi Jesu durch den Willen Gottes auf Grund der Verheißung des Lebens (das) in Christus Jesus (begründet ist),');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 1, 2, 'sende meinen Gruß dem Timotheus, meinem geliebten (Glaubens-)Kinde: Gnade, Barmherzigkeit und Friede (sei mit dir) von Gott dem Vater und unserm Herrn Christus Jesus!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 1, 3, 'Ich bin meinem Gott, dem ich von meinen Vorfahren her mit reinem Gewissen diene, dankbar dafür, wie unablässig ich deiner in meinen Gebeten bei Tag und Nacht gedenke.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 1, 4, 'Ich sehne mich dabei in der Erinnerung an deine Tränen nach einem Wiedersehen mit dir, um mich mit ganzem Herzen freuen zu können,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 1, 5, 'wenn ich einen neuen Eindruck von deinem aufrichtigen Glauben empfange, der zuerst in deiner Großmutter Lois und deiner Mutter Eunike gewohnt hat und (jetzt), wie ich überzeugt bin, auch in dir (wohnt).');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 1, 6, 'Aus diesem Grunde erinnere ich dich mahnend daran, die Gnadengabe Gottes, die dir infolge meiner Handauflegung zuteil geworden ist, zu heller Flamme zu entfachen;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 1, 7, 'denn Gott hat uns nicht einen Geist der Verzagtheit gegeben, sondern der Kraft und der Liebe und der Selbstzucht.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 1, 8, 'So schäme dich also nicht, Zeugnis von unserm Herrn abzulegen; (schäme dich) auch meiner nicht, der ich um seinetwillen ein Gefangener bin, sondern nimm an den Leiden für die (Verkündigung der) Heilsbotschaft teil nach Maßgabe der Kraft Gottes,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 1, 9, 'der uns errettet hat und berufen mit einer heiligen Berufung, nicht auf Grund unserer Werke, sondern nach seinem Vorsatz und nach seiner Gnade, die uns in Christus Jesus vor ewigen Zeiten verliehen,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 1, 10, 'jetzt aber durch die Erscheinung unsers Retters Jesus Christus geoffenbart worden ist. Der hat die Macht des Todes vernichtet, dafür aber Leben und unvergängliches Wesen ans Licht gebracht durch die Heilsbotschaft,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 1, 11, 'für die ich meinerseits zum Herold, zum Apostel und zum Lehrer bestellt worden bin.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 1, 12, 'Das ist auch die Ursache meiner jetzigen Leiden, deren ich mich aber nicht schäme; denn ich weiß, wer es ist, auf den ich mein Vertrauen gesetzt habe, und bin dessen gewiß, daß er stark genug ist, mein mir anvertrautes Gut bis auf jenen Tag zu bewahren.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 1, 13, 'Als Vorbild gesunder Lehren halte die fest, welche du von mir gehört hast, im Glauben und in der Liebe, die in Christus Jesus wurzeln.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 1, 14, 'Bewahre das dir anvertraute kostbare Gut durch den heiligen Geist, der in uns wohnt!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 1, 15, 'Das weißt du (bereits), daß alle in der Provinz Asien mir den Rücken gekehrt haben, unter ihnen Phygelus und Hermogenes.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 1, 16, 'Der Herr erweise seine Barmherzigkeit dem Hause des Onesiphorus; denn er hat mich oft erquickt und meiner Ketten sich nicht geschämt,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 1, 17, 'sondern nach seiner Ankunft in Rom eifrig nach mir gesucht und mich auch ausfindig gemacht.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 1, 18, 'Der Herr (Jesus) lasse ihn bei (Gott) dem Herrn an jenem Tage Barmherzigkeit finden! Wie viele wichtige Dienste er (uns) außerdem in Ephesus geleistet hat, weißt du selbst am besten.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 2, 1, 'Tritt du nun, mein (Glaubens-) Kind, durch die Gnade, die in Christus Jesus (dargeboten) ist, kraftvoll auf');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 2, 2, 'und vertraue das, was du von mir unter Bestätigung vieler Zeugen gehört hast, zuverlässigen Personen an, die (dann auch) befähigt sein werden, wieder andere zu unterweisen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 2, 3, 'Tritt als ein rechter Streiter Christi Jesu in die Leidensgemeinschaft ein!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 2, 4, 'Kein Kriegsmann gibt sich mit (den kleinlichen) Geschäften des Broterwerbs ab; sonst kann er dem, der ihn in Dienst genommen hat, nicht gefallen;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 2, 5, 'und wenn jemand auch am Wettkampf teil nimmt, empfängt er doch den Siegeskranz nicht, wenn er nicht ordnungsgemäß gekämpft hat.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 2, 6, 'Der Landmann, der die mühevolle Arbeit verrichtet, hat auch den ersten Anspruch auf den Genuß der Früchte.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 2, 7, 'Suche den Sinn meiner Worte zu begreifen: der Herr wird dir schon in allen Fällen die rechte Einsicht verleihen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 2, 8, 'Halt im Gedächtnis Jesus Christus fest, der von den Toten auferweckt worden ist, der aus Davids Nachkommenschaft stammt – wie meine Heilsbotschaft lautet,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 2, 9, 'für die ich Leiden zu erdulden habe, sogar Ketten wie ein Verbrecher; doch das Wort Gottes liegt (darum) nicht in Ketten.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 2, 10, 'Deshalb ertrage ich auch alles standhaft um der Auserwählten willen, damit auch sie das Heil, das in Christus Jesus (begründet) ist, samt der ewigen Herrlichkeit erlangen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 2, 11, 'Zuverlässig ist das Wort: »Sind wir mitgestorben, so werden wir auch mitleben;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 2, 12, 'harren wir standhaft aus, so werden wir auch mitherrschen; verleugnen wir, so wird auch er uns verleugnen;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 2, 13, 'sind wir untreu, so bleibt er doch treu; denn er kann sich selbst nicht verleugnen.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 2, 14, 'Dies bringe (allen) in Erinnerung und ermahne sie eindringlich vor dem Angesicht Gottes, sich auf keinen Streit um Worte einzulassen, was zu nichts nütze ist und nur zur Verstörung der Zuhörer führt.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 2, 15, 'Sei eifrig bemüht, dich Gott als bewährt darzustellen, als einen Arbeiter, der sich (seiner Arbeit) nicht zu schämen braucht, weil er das Wort der Wahrheit richtig darbietet.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 2, 16, 'Mit den wertlosen leeren Geschwätzen dagegen sollst du nichts zu tun haben; denn sie werden (mit ihnen) immer tiefer in die Gottentfremdung hineingeraten,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 2, 17, 'und ihr Gerede wird wie ein Krebsgeschwür immer weiter um sich fressen. Zu ihnen gehören Hymenäus und Philetus,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 2, 18, 'die in betreff der Wahrheit auf Abwege geraten sind, da sie behaupten, die Auferstehung habe bereits stattgefunden: sie bringen dadurch manchen um seinen Glauben.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 2, 19, 'Doch der feste, von Gott gelegte Grundbau bleibt trotzdem bestehen und trägt als Siegel diese Inschrift: »Der Herr kennt die Seinen« und: »Es halte sich von der Ungerechtigkeit jeder fern, der den Namen des Herrn nennt!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 2, 20, 'In einem großen Hauswesen gibt es aber nicht nur goldene und silberne Gefäße, sondern auch hölzerne und irdene, und zwar die ersteren zu ehrenvoller Verwendung, die letzteren zu ungeehrtem Gebrauch.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 2, 21, 'Wenn nun jemand sich von diesen (letztgenannten) völlig rein erhält, so wird er ein Gefäß zu ehrenvoller Verwendung sein, ein geheiligtes, für den Hausherrn brauchbares, zu jedem guten Werk geeignetes.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 2, 22, 'Fliehe die Begierden der Jugend, jage vielmehr der Gerechtigkeit und dem Glauben, der Liebe und dem Frieden nach im Verein mit denen, die den Herrn aus reinem Herzen anrufen!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 2, 23, 'Aber auf die törichten und kindischen Untersuchungen laß dich nicht ein; du weißt ja, daß sie nur Streitigkeiten hervorrufen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 2, 24, 'Ein Knecht des Herrn aber soll nicht streitsüchtig sein, sondern freundlich gegen jedermann, ein tüchtiger Lehrer, fähig, Böses mit Geduld zu ertragen');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 2, 25, 'und die Widerstrebenden mit Sanftmut zurechtzuweisen, ob Gott ihnen nicht doch noch die Umkehr zur Erkenntnis der Wahrheit verleihe,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 2, 26, 'so daß sie wieder nüchtern werden und sich aus der Schlinge des Teufels losmachen, nachdem sie sich von ihm haben einfangen lassen, ihm zu Willen zu sein.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 3, 1, 'Das sollst du aber wissen, daß in den letzten Tagen schlimme Zeiten eintreten werden;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 3, 2, 'denn da werden die Menschen selbstsüchtig und geldgierig sein, prahlerisch und hochmütig, schmähsüchtig, den Eltern ungehorsam, undankbar, gottlos,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 3, 3, 'ohne Liebe und Treue, verleumderisch, unmäßig, zügellos, allem Guten feind,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 3, 4, 'verräterisch, leichtfertig und dünkelhaft, mehr dem Genuß als der Liebe zu Gott ergeben;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 3, 5, 'sie werden wohl noch den äußeren Schein der Gottseligkeit wahren, aber deren innere Kraft nicht erkennen lassen. Von solchen Menschen wende dich ab!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 3, 6, 'Denn zu diesen gehören die, welche sich Eingang in die Häuser zu verschaffen wissen und Angehörige des weiblichen Geschlechts einzufangen suchen (und zwar solche), die mit Sünden beladen sind und von mancherlei Leidenschaften umgetrieben werden,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 3, 7, 'die immerfort (etwas Neues) lernen wollen und doch niemals zur wirklichen Erkenntnis der Wahrheit zu gelangen vermögen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 3, 8, 'Geradeso wie einst Jannes und Jambres gegen Mose aufgetreten sind, so treten auch diese gegen die Wahrheit auf: Menschen mit zerrüttetem Verstand und im Glauben unbewährt.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 3, 9, 'Doch sie werden mit ihrem Treiben nicht weit kommen, denn ihr Unverstand wird für alle klar zutage liegen, wie es ja auch bei jenen (beiden) der Fall gewesen ist.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 3, 10, 'Du aber hast dir zur Richtschnur genommen meine Lehre und Lebensführung, mein Streben, meinen Glauben, meine Langmut, Liebe und Geduld,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 3, 11, 'meine Verfolgungen und Leiden, wie sie mir in Antiochia, in Ikonium und in Lystra widerfahren sind. Derartige Verfolgungen habe ich zu bestehen gehabt, und aus allen hat der Herr mich errettet;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 3, 12, 'und so werden auch alle (anderen), die in Christus Jesus ein gottseliges Leben zu führen gewillt sind, Verfolgungen zu erleiden haben.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 3, 13, 'Böse Menschen dagegen und Betrüger werden es immer ärger treiben, indem sie verführen und selbst verführt werden.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 3, 14, 'Du aber bleibe dem treu, was du gelernt hast und was dir zu völliger Gewißheit geworden ist; du weißt ja, von welchen Lehrern du es gelernt hast,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 3, 15, 'und kennst ja von Kind auf die heiligen Schriften, die imstande sind, dich weise zu machen zur Errettung durch den auf Christus Jesus gegründeten Glauben.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 3, 16, 'Jede von Gottes Geist eingegebene Schrift ist auch förderlich zur Belehrung und zur Überführung, zur Besserung und zur Erziehung in der Gerechtigkeit,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 3, 17, 'damit der Gottesmensch vollkommen sei, zu jedem guten Werk voll ausgerüstet.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 4, 1, 'Ich beschwöre dich vor dem Angesicht Gottes und Christi Jesu, welcher dereinst Lebende und Tote richten wird, und bei seiner Erscheinung und bei seiner Königsherrschaft:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 4, 2, 'verkündige das Wort, tritt damit auf, du magst gelegen oder ungelegen kommen, überführe, weise zurecht, ermahne mit allem Aufwand von Langmut und Belehrung!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 4, 3, 'Denn es wird eine Zeit kommen, da wird man die gesunde Lehre unerträglich finden und sich nach eigenem Gelüsten Lehrer über Lehrer beschaffen, weil man nach Ohrenkitzel Verlangen trägt;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 4, 4, 'von der Wahrheit dagegen wird man die Ohren abkehren und sich den Fabeln zuwenden.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 4, 5, 'Du aber bleibe nüchtern in jeder Hinsicht, nimm die Leiden auf dich, richte die Arbeit eines Predigers der Heilsbotschaft aus und versieh deinen Dienst voll und ganz.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 4, 6, 'Denn was mich betrifft, so wird mein Blut nunmehr als Trankopfer ausgegossen, und die Zeit meines Abscheidens ist da.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 4, 7, 'Ich habe den guten Kampf gekämpft, habe den Lauf vollendet, den Glauben unverletzt bewahrt:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 4, 8, 'fortan liegt für mich der Siegeskranz der Gerechtigkeit bereit, den der Herr, der gerechte Richter, mir an jenem Tage zuteilen wird; jedoch nicht nur mir, sondern überhaupt allen, die sein Erscheinen lieb gehabt haben.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 4, 9, 'Komm möglichst bald zu mir,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 4, 10, 'denn Demas hat mich aus Liebe zur jetzigen Weltzeit verlassen und ist nach Thessalonike abgereist, Crescens nach Galatien, Titus nach Dalmatien;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 4, 11, 'nur Lukas ist noch bei mir. Nimm Markus zu dir und bringe ihn mit; denn ich kann ihn zu Dienstleistungen gut gebrauchen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 4, 12, 'Tychikus aber habe ich nach Ephesus gesandt.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 4, 13, 'Den Reisemantel, den ich in Troas bei Karpus zurückgelassen habe, bringe mir mit, wenn du kommst, auch die Bücher, besonders die Pergamentblätter.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 4, 14, 'Der Schmied Alexander hat mir viel Böses angetan: der Herr wird ihm nach seinem Tun vergelten.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 4, 15, 'Nimm auch du dich vor ihm in acht, denn er ist unsern Aussagen mit Entschiedenheit entgegengetreten.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 4, 16, 'Bei meiner ersten Verteidigung (vor Gericht) hat mir niemand zur Seite gestanden, sondern alle haben mich im Stich gelassen: möge es ihnen (von Gott) nicht angerechnet werden!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 4, 17, 'Doch der Herr ist mir beigestanden und hat mir Kraft verliehen, damit durch mich die Verkündigung (der Heilsbotschaft) zum Abschluß gebracht würde und alle Heiden sie zu hören bekämen; so bin ich denn aus dem Löwenrachen glücklich errettet worden.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 4, 18, 'Der Herr wird mich auch fernerhin vor allen Anschlägen der Bosheit behüten und mich hinüberretten in sein himmlisches Reich: ihm sei die Ehre in alle Ewigkeit! Amen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 4, 19, 'Grüße Priska und Aquila sowie das Haus des Onesiphorus.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 4, 20, 'Erastus ist in Korinth geblieben, Trophimus aber habe ich in Milet krank zurückgelassen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 4, 21, 'Komm, wenn irgend möglich, noch vor Eintritt des Winters (zu mir)! Eubulus, Pudens, Linus, Klaudia, überhaupt sämtliche Brüder lassen dich grüßen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 4, 22, 'Der Herr (Jesus) sei mit deinem Geist! Die Gnade (Gottes) sei mit euch!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 1, 1, 'Ich, Paulus, ein Knecht Gottes und ein Apostel Jesu Christi, (bestellt) für den Glauben der Auserwählten Gottes und für die Erkenntnis der Wahrheit, die sich in einem gottseligen Wandel bewährt,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 1, 2, '(bestellt) aufgrund der Hoffnung des ewigen Lebens, das der untrügliche Gott (schon) vor ewigen Zeiten verheißen hat –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 1, 3, 'kundgetan aber hat er sein Wort zur festgesetzten Zeit durch die Predigt, mit der ich im Auftrage Gottes, unsers Retters betraut worden bin –:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 1, 4, 'ich sende meinen Gruß dem Titus, meinem hinsichtlich des gemeinsamen Glaubens echten Kinde: Gnade (sei mit dir) und Friede von Gott dem Vater und unserm Retter Christus Jesus!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 1, 5, 'Ich habe dich zu dem Zweck in Kreta zurückgelassen, daß du das (von mir dort) noch nicht Erledigte in Ordnung bringen und in den einzelnen Städten Älteste einsetzen möchtest, wie ich es dir aufgetragen habe,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 1, 6, 'nämlich solche (Männer), die unbescholten und nur eines Weibes Mann sind und gläubige Kinder haben, denen man nicht zuchtlosen Lebenswandel oder Unbotmäßigkeit nachsagen kann;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 1, 7, 'denn ein Gemeindevorsteher muß als Gottes Haushalter unbescholten sein, nicht eigenwillig, nicht zornmütig, kein Trinker, kein Händelsucher, nicht schändlichem Gewinn nachgehend;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 1, 8, 'vielmehr muß er gastfrei sein, allem Guten zugetan, besonnen, gerecht, gottesfürchtig, enthaltsam;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 1, 9, 'er muß an dem zuverlässigen Wort (Gottes) festhalten, wie er es im Unterricht empfangen hat, damit er imstande ist, aufgrund der gesunden Lehre ebensowohl zu ermahnen als auch die Widersprechenden zu widerlegen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 1, 10, 'Denn es gibt viele, die sich nicht unterordnen wollen, Schwätzer und Schwindler, besonders unter den Judenchristen;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 1, 11, 'ihnen muß man den Mund stopfen, weil sie ganze Häuser zerrütten, indem sie um schändlichen Gewinnes willen ungehörige Lehren vortragen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 1, 12, 'Hat doch ein Prophet aus ihrer eigenen Mitte gesagt: »Die Kreter sind immer verlogen, bösartige Tiere, faule Bäuche.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 1, 13, 'Dies Zeugnis entspricht der Wahrheit, und aus diesem Grunde weise sie rücksichtslos zurecht, damit sie im Glauben gesund bleiben');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 1, 14, 'und ihre Gedanken nicht auf jüdische Fabeln und auf Gebote von Menschen richten, die der Wahrheit den Rücken kehren.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 1, 15, '»Für die Reinen ist alles rein«, für die Befleckten und Ungläubigen dagegen ist nichts rein, sondern bei ihnen ist beides, ihr Verstand und ihr Gewissen, befleckt.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 1, 16, 'Sie behaupten zwar, Gott zu kennen, verleugnen ihn aber durch ihr ganzes Tun: verabscheuenswerte und ungehorsame, zu jedem guten Werk untüchtige Menschen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 2, 1, 'Du aber sprich offen aus, was der gesunden Lehre entspricht,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 2, 2, 'nämlich daß die älteren Männer nüchtern sein sollen, ehrbar, besonnen, gesund im Glauben, in der Liebe und in der Standhaftigkeit. –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 2, 3, 'Ebenso ermahne die älteren Frauen, sich in ihrer Haltung würdevoll zu benehmen, nicht klatschsüchtig zu sein, nicht dem übermäßigen Weingenuß ergeben, Lehrerinnen des Guten,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 2, 4, 'damit sie die jungen Frauen zu besonnener Pflichterfüllung anleiten, nämlich ihre Männer und ihre Kinder zu lieben,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 2, 5, 'züchtig, keusch, tüchtige Haushälterinnen, gütig zu sein und sich ihren Ehemännern unterzuordnen, damit das Wort Gottes nicht gelästert werde. –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 2, 6, 'Die jungen Männer ermahne gleichfalls, besonnen zu sein,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 2, 7, 'und biete dich selbst ihnen in jeder Beziehung als Vorbild guter Werke dar. In der Lehre beweise Unverfälschtheit, würdevollen Ernst,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 2, 8, 'gesunde, unanfechtbare Rede, damit jeder Gegner sich beschämt fühlt, weil er uns nichts Schlechtes nachsagen kann. –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 2, 9, 'Die Knechte ermahne, ihren Herren in jeder Hinsicht gehorsam zu sein und ihnen zu Gefallen zu leben, nicht zu widersprechen,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 2, 10, 'nichts zu veruntreuen, vielmehr volle, echte Treue zu beweisen, damit sie der Lehre Gottes, unsers Retters, in allen Beziehungen Ehre machen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 2, 11, 'Denn erschienen ist die Gnade Gottes, die allen Menschen das Heil bringt,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 2, 12, 'indem sie uns dazu erzieht, dem gottlosen Wesen und den weltlichen Begierden abzusagen und besonnen, gerecht und gottselig (schon) in der gegenwärtigen Weltzeit zu leben,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 2, 13, 'indem wir dabei auf unser seliges Hoffnungsgut und auf das Erscheinen der Herrlichkeit des großen Gottes und unsers Retters Christus Jesus warten,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 2, 14, 'der sich selbst für uns dahingegeben hat, um uns von aller Gesetzlosigkeit zu erlösen und sich ein reines Volk zum Eigentum zu schaffen, das eifrig auf gute Werke bedacht ist.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 2, 15, 'Dies trage ihnen vor, dazu ermahne sie und rede ihnen mit allem Nachdruck ins Gewissen; laß dich (dabei) von niemand geringschätzig behandeln!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 3, 1, 'Schärfe ihnen ein, daß sie sich den obrigkeitlichen Gewalten unterordnen, (ihren Befehlen) Gehorsam leisten und zu jedem guten Werk bereit seien,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 3, 2, 'daß sie niemand schmähen, sich friedfertig und nachgiebig benehmen und volle Sanftmut gegen alle Menschen beweisen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 3, 3, 'Denn einst sind auch wir unverständig und ungehorsam gewesen und irre gegangen, indem wir mannigfachen Begierden und Lüsten dienten und in Bosheit und Neid dahinlebten, hassenswert und gegeneinander haßerfüllt.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 3, 4, 'Als aber die Güte und Menschenfreundlichkeit Gottes, unsers Retters, erschienen war,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 3, 5, 'da hat er uns – nicht aufgrund von Werken der Gerechtigkeit, die wir unserseits vollbracht hätten, sondern nach seiner Barmherzigkeit – gerettet durch das Bad der Wiedergeburt und der Erneuerung des heiligen Geistes,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 3, 6, 'den er reichlich auf uns ausgegossen hat durch unsern Retter Jesus Christus,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 3, 7, 'damit wir durch seine Gnade gerechtgesprochen und unserer Hoffnung gemäß Erben des ewigen Lebens würden.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 3, 8, 'Zuverlässig ist das Wort, und ich will, daß du dich hierüber mit aller Bestimmtheit aussprichst, damit die, welche zum Glauben an Gott gekommen sind, allen Eifer darauf verwenden, sich in guten Werken zu betätigen – das ist etwas Schönes und für die Menschen Segensreiches.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 3, 9, 'Dagegen mit törichten Untersuchungen und Geschlechtsverzeichnissen sowie mit Streitigkeiten und Gezänk über das Gesetz habe du nichts zu tun, denn das sind unnütze und unfruchtbare Dinge.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 3, 10, 'Einen Menschen, der Spaltungen anrichtet, weise nach einmaliger oder zweimaliger Verwarnung ab;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 3, 11, 'du weißt ja, daß ein solcher Mensch auf verkehrte Wege geraten und nach seinem eigenen Urteil ein Sünder ist.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 3, 12, 'Sobald ich Artemas oder Tychikus zu dir sende, beeile dich, zu mir nach Nikopolis zu kommen; denn ich habe mich entschlossen, dort den Winter zuzubringen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 3, 13, 'Zenas, den Gesetzeslehrer, und Apollos rüste sorgfältig für ihre Winterreise aus, damit es ihnen an nichts gebricht.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 3, 14, 'Auch unsere Leute müssen daraus eine löbliche Liebestätigkeit zur Befriedigung unumgänglicher Bedürfnisse lernen, damit sie nicht ohne Früchte (ihres Glaubens) bleiben.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 3, 15, 'Alle, die hier bei mir sind, lassen dich grüßen. Grüße die, welche im Glauben uns lieben! Die Gnade (Gottes) sei mit euch allen!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (67, 1, 1, 'Ich, Paulus, ein Gefangener (um) Christi Jesu (willen), und der Bruder Timotheus senden dem geliebten Philemon, unserm Mitarbeiter,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (67, 1, 2, 'sowie der Schwester Appia und unserm Mitstreiter Archippus nebst der Gemeinde in deinem Hause unsern Gruß:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (67, 1, 3, 'Gnade (sei mit) euch und Friede von Gott unserm Vater und dem Herrn Jesus Christus!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (67, 1, 4, 'Ich sage meinem Gott allezeit Dank, sooft ich deiner in meinen Gebeten gedenke;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (67, 1, 5, 'ich höre ja, welche Liebe und welchen Glauben du dem Herrn Jesus und allen Heiligen gegenüber bewährst.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (67, 1, 6, '(Dahin geht aber mein Gebet,) daß die aus deinem Glauben erwachsene gemeinnützige Tätigkeit sich in der Erkenntnis all des Guten wirksam erweise, das in uns vorhanden ist auf Christus hin.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (67, 1, 7, 'Ja, große Freude und reichen Trost habe ich deiner Liebe zu verdanken, weil die Herzen der Heiligen durch dich, lieber Bruder, erquickt worden sind.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (67, 1, 8, 'Darum, wenn ich es mir auch in Christus unbedenklich herausnehmen dürfte, dir vorzuschreiben, was sich gebührt,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (67, 1, 9, 'so ziehe ich es doch um der Liebe willen vor, nur eine Bitte gegen dich auszusprechen: ein Mann, wie ich es bin, ein alter Paulus und jetzt obendrein ein Gefangener (um) Christi Jesu (willen),');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (67, 1, 10, 'ich bitte dich für mein (Glaubens-) Kind, dessen Vater ich in meiner Gefangenschaft geworden bin, für Onesimus,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (67, 1, 11, 'der sich dir zwar ehemals als ein Nichtsnutz erwiesen hat, jetzt aber dir ebenso wie mir von großem Nutzen ist.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (67, 1, 12, 'Ich sende ihn, das will sagen mein eigenes Herz, hiermit dir zurück.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (67, 1, 13, 'Gern hätte ich ihn hier bei mir behalten, damit er mir als dein Vertreter in der Gefangenschaft, die ich für die Heilsbotschaft leide, Dienste leisten möchte;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (67, 1, 14, 'doch ohne deine Einwilligung habe ich nichts tun wollen, damit deine Guttat nicht erzwungen erscheine, sondern als eine freiwillige Leistung erfolge.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (67, 1, 15, 'Vielleicht ist er nämlich nur deswegen eine Zeitlang (von dir) getrennt gewesen, damit du ihn auf ewig wieder erhieltest,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (67, 1, 16, '(und zwar) nicht mehr als einen Sklaven, sondern als einen, der etwas Besseres darstellt, nämlich einen geliebten Bruder, als der er mir schon in besonderem Maße gilt, wieviel mehr noch dir, dem er sowohl mit seinem Leibe als nun auch im Herrn angehört!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (67, 1, 17, 'Wenn du dich nun mit mir eng verbunden weißt, so nimm ihn auf wie mich selbst!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (67, 1, 18, 'Und hat er dich irgendwie geschädigt oder ist er dir etwas schuldig, so setze das mir auf Rechnung!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (67, 1, 19, 'Ich, Paulus, gebe es dir hier schriftlich: Ich will es bezahlen! Dabei brauche ich dir nicht zu sagen, daß auch du mir etwas schuldig bist, nämlich dich selbst.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (67, 1, 20, 'Ja, lieber Bruder, ich möchte dich gern ein wenig ausnutzen im Herrn: erfülle mir einen Herzenswunsch in Christus!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (67, 1, 21, 'Im Vertrauen auf deinen Gehorsam schreibe ich dir; ich weiß ja, du wirst sogar noch mehr tun, als ich verlange.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (67, 1, 22, 'Zugleich rüste dich aber auch, mich als Gast bei dir aufzunehmen, denn ich hoffe, infolge eurer Gebete euch geschenkt zu werden.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (67, 1, 23, 'Es grüßen dich Epaphras, mein Mitgefangener in Christus Jesus,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (67, 1, 24, 'Markus, Aristarchus, Demas und Lukas, meine Mitarbeiter.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (67, 1, 25, 'Die Gnade des Herrn Jesus Christus sei mit eurem Geiste!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (68, 1, 1, 'Ich, Petrus, ein Apostel Jesu Christi, entbiete meinen Gruß den Fremdlingen, die in Pontus, Galatien, Kappadozien, (der römischen Provinz) Asien und Bithynien in der Zerstreuung leben');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (68, 1, 2, 'und nach der Vorersehung Gottes des Vaters dazu auserwählt sind, in der Heiligung des Geistes zum Gehorsam und zur Besprengung mit dem Blute Jesu Christi (zu gelangen): Gnade und Friede möge euch immer reichlicher zuteil werden!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (68, 1, 3, 'Gelobt sei der Gott und Vater unsers Herrn Jesus Christus, der nach seiner großen Barmherzigkeit uns wiedergeboren hat zu einer lebendigen Hoffnung durch die Auferstehung Jesu Christi von den Toten,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (68, 1, 4, 'zu einem unvergänglichen, unbefleckten und unverwelklichen Erbe, das im Himmel aufbewahrt ist für euch,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (68, 1, 5, 'die ihr in der Kraft Gottes durch den Glauben für die Errettung bewahrt werdet, die (schon jetzt) bereitsteht, um in der letzten Zeit geoffenbart zu werden.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (68, 1, 6, 'Darüber jubelt ihr, mögt ihr jetzt auch eine kurze Zeit, wenn es so sein muß, durch mancherlei Anfechtung in Trübsal versetzt sein;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (68, 1, 7, 'dadurch soll sich ja die Echtheit eures Glaubens bewähren und wertvoller erfunden werden als Gold, das vergänglich ist, aber durch Feuer in seiner Echtheit erprobt wird, und sich (euch) zum Lobe, zur Ehre und zur Verherrlichung bei der Offenbarung Jesu Christi erweisen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (68, 1, 8, 'Ihn habt ihr lieb, obgleich ihr ihn nicht gesehen habt; an ihn glaubt ihr, obgleich ihr ihn jetzt nicht seht, und ihm jubelt ihr mit unaussprechlicher und verklärter Freude entgegen,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (68, 1, 9, 'weil ihr das Endziel eures Glaubens davontragt, nämlich die Errettung eurer Seelen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (68, 1, 10, 'In betreff dieser Errettung haben die Propheten nachgesonnen und nachgeforscht, die von der euch zugedachten Gnade geweissagt haben,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (68, 1, 11, 'indem sie ausfindig zu machen suchten, welche oder was für eine Zeit es sei, auf welche der in ihnen wirkende Geist Christi hinwies, wenn er ihnen die für Christus bestimmten Leiden und seine darauf folgenden Verherrlichungen im voraus bezeugte.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (68, 1, 12, 'Dabei wurde ihnen geoffenbart, daß sie durch ihren Dienst nicht sich selbst, sondern euch eben das vermitteln sollten, was euch jetzt durch die Männer verkündigt worden ist, die euch die Heilsbotschaft in der Kraft des vom Himmel hergesandten heiligen Geistes gepredigt haben: Dinge, in welche auch die Engel gern hineinschauen möchten.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (68, 1, 13, 'Darum macht euch geistlich fertig zum rüstigen Vorwärtsschreiten, seid nüchtern und setzt eure Hoffnung ausschließlich auf die Gnade, die euch in der Offenbarung Jesu Christi dargeboten wird.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (68, 1, 14, 'Als gehorsame (Gottes-) Kinder gestaltet euer Leben nicht nach den Lüsten, die ihr früher während (der Zeit) eurer Unwissenheit gehegt habt,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (68, 1, 15, 'sondern werdet nach dem Vorbild des Heiligen, der euch berufen hat, gleichfalls in eurem ganzen Wandel heilig,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (68, 1, 16, 'weil ja doch geschrieben steht: »Ihr sollt heilig sein, denn ich bin heilig!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (68, 1, 17, 'Und wenn ihr den als Vater anruft, der ohne Ansehen der Person nach dem Werk eines jeden richtet, so führet euren Wandel in Furcht während der Zeit eurer Fremdlingschaft;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (68, 1, 18, 'ihr wißt ja, daß ihr von eurem eitlen Wandel, den ihr von den Vätern her überkommen hattet, nicht mit vergänglichen Dingen, mit Silber oder Gold, losgekauft worden seid,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (68, 1, 19, 'sondern mit dem kostbaren Blute Christi als eines fehllosen und unbefleckten Lammes.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (68, 1, 20, 'Er war zwar schon vor Grundlegung der Welt zuvorersehen, ist aber erst am Ende der Zeiten geoffenbart worden euch zugute;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (68, 1, 21, 'denn durch ihn seid ihr zum Glauben an Gott gekommen, der ihn von den Toten auferweckt und ihm Herrlichkeit verliehen hat, so daß euer Glaube zugleich Hoffnung auf Gott ist.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (68, 1, 22, 'Da ihr eure Seelen im Gehorsam gegen die Wahrheit zu ungeheuchelter Bruderliebe gereinigt habt, so liebet einander innig von Herzen;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (68, 1, 23, 'ihr seid ja nicht aus vergänglichem, sondern aus unvergänglichem Samen wiedergeboren, nämlich durch das lebendige und ewigbleibende Wort Gottes.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (68, 1, 24, 'Denn »alles Fleisch ist wie Gras und alle seine Herrlichkeit wie des Grases Blume; das Gras verdorrt und seine Blume fällt ab,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (68, 1, 25, 'das Wort des Herrn aber bleibt in Ewigkeit«. Dies ist aber das Wort, das euch als Heilsbotschaft verkündigt worden ist.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (68, 2, 1, 'So legt also alle Bosheit und alle Falschheit, die Heuchelei, den Neid und alle Verleumdungssucht ab');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (68, 2, 2, 'und tragt wie neugeborene Kinder nach der geistigen lauteren Milch Verlangen, damit ihr durch sie zur Errettung heranwachst,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (68, 2, 3, 'wenn ihr wirklich »geschmeckt habt, daß der Herr freundlich ist«.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (68, 2, 4, 'Wenn ihr zu ihm, dem lebendigen Stein, herantretet, der von den Menschen zwar als unbrauchbar verworfen, bei Gott aber als ein auserwähltes Kleinod gilt,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (68, 2, 5, 'so werdet auch ihr selbst als lebendige Bausteine zu einem geistlichen Hause, zu einer heiligen Priesterschaft aufgebaut, um geistliche Opfer darzubringen, die Gott durch Jesus Christus wohlgefällig sind.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (68, 2, 6, 'In der Schrift heißt es ja: »Seht, ich lege in Zion einen auserwählten Stein, einen kostbaren Eckstein; und wer auf ihn sein Vertrauen setzt, wird nimmermehr zuschanden werden.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (68, 2, 7, 'Euch also, die ihr Vertrauen besitzt, wird das kostbare Gut zuteil; für die Ungläubigen aber ist »der Stein, den die Bauleute verworfen haben – gerade der ist zum Eckstein geworden«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (68, 2, 8, 'und damit »zu einem Stein des Anstoßes« und »zum Felsen des Ärgernisses«; sie stoßen sich an ihm in ihrem Ungehorsam gegen das Wort, wozu sie auch bestimmt sind.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (68, 2, 9, 'Ihr dagegen seid »das auserwählte Geschlecht, die königliche Priesterschaft, die heilige Volksgemeinschaft, das zum Eigentum erkorene Volk«, und sollt die Tugenden dessen verkünden, der euch aus der Finsternis in sein wunderbares Licht berufen hat,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (68, 2, 10, 'euch, die ihr vordem »ein Nicht-Volk« waret, jetzt aber »das Volk Gottes« seid, einst »ohne Gottes Erbarmen«, jetzt aber »reich an Gotteserbarmen«.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (68, 2, 11, 'Geliebte, ich ermahne euch: Enthaltet euch, da ihr ja »Fremdlinge und Beisassen« seid, der fleischlichen Begierden, die im Kampf gegen die Seele liegen;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (68, 2, 12, 'führt einen guten Wandel unter den Heiden, damit sie in allem, worin sie euch (jetzt) als Übeltäter verlästern, bei genauer Prüfung auf Grund eurer guten Werke Gott preisen am »Tage der Gnadenheimsuchung«.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (68, 2, 13, 'Seid jeder menschlichen Ordnung um des Herrn willen untertan, es sei dem König als dem obersten Herrn');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (68, 2, 14, 'oder den Statthaltern als denen, die von ihm zur Bestrafung der Übeltäter und Belobigung der recht Handelnden entsandt werden.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (68, 2, 15, 'Denn so ist es der Wille Gottes, daß ihr durch Gutestun den Unverstand der törichten Menschen zum Schweigen bringt,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (68, 2, 16, 'und zwar als (wahrhaft) Freie und nicht als solche, welche die Freiheit zum Deckmantel der Bosheit machen, sondern als Knechte Gottes.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (68, 2, 17, 'Erweiset jedermann die schuldige Ehre, habt die Brüder lieb, »fürchtet Gott, ehret den König«!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (68, 2, 18, 'Ihr Dienstleute, seid in aller Furcht euren Herren untertan, nicht nur den gütigen und nachsichtigen, sondern auch den verkehrten;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (68, 2, 19, 'denn das ist Gnade, wenn jemand im Gedanken an Gott Trübsale geduldig erträgt, sofern er unschuldig leidet.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (68, 2, 20, 'Denn was ist das für ein Ruhm, wenn ihr (die Schläge) geduldig aushaltet, wo ihr euch vergeht und dann gezüchtigt werdet? Aber wenn ihr geduldig aushaltet, wo ihr trotz eures guten Verhaltens leiden müßt, das ist Gnade bei Gott.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (68, 2, 21, 'Denn dazu seid ihr berufen worden, weil auch Christus für euch gelitten und euch (dadurch) ein Vorbild hinterlassen hat, damit ihr seinen Fußtapfen nachfolget.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (68, 2, 22, 'Er hat keine Sünde getan, auch ist kein Trug in seinem Munde gefunden worden;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (68, 2, 23, 'er hat, wenn er geschmäht wurde, nicht wieder geschmäht und, als er litt, keine Drohungen ausgestoßen, sondern es dem anheimgestellt, der gerecht richtet.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (68, 2, 24, 'Er hat unsere Sünden selber mit seinem Leibe an das (Marter-) Holz hinaufgetragen, damit wir, von den Sünden freigemacht, der Gerechtigkeit leben möchten: durch seine Wunden seid ihr geheilt worden.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (68, 2, 25, 'Denn ihr ginget (einst) wie Schafe in der Irre; jetzt aber seid ihr zu dem Hirten und Hüter eurer Seelen bekehrt worden.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (68, 3, 1, 'Ebenso, ihr Frauen: seid euren Ehemännern untertan, damit auch solche (Männer), die dem Wort ungehorsam sind, durch den Wandel ihrer Frauen auch ohne Wort gewonnen werden,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (68, 3, 2, 'wenn sie euren in Gottesfurcht sittsamen Wandel wahrnehmen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (68, 3, 3, 'Euer Schmuck sei nicht der äußerliche, nicht kunstvolles Haargeflecht und das Anlegen goldenen Geschmeides oder das Anziehen prächtiger Gewänder,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (68, 3, 4, 'sondern der im Herzen verborgene Mensch mit dem unvergänglichen Wesen eines sanften und stillen Geistes, der vor Gott als kostbar gilt.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (68, 3, 5, 'So haben sich ja einst auch die heiligen Frauen geschmückt, die ihre Hoffnung auf Gott setzten, indem sie sich ihren Ehemännern untertan bewiesen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (68, 3, 6, 'So hat sich z.B. Sara dem Abraham gehorsam gezeigt, indem sie ihn »Herr« nannte. Ihre Kinder seid ihr geworden, wenn ihr das Gute tut und euch durch keine Drohung einschüchtern laßt.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (68, 3, 7, 'Ebenso, ihr Männer: lebt in vernünftiger Weise mit euren Frauen zusammen als mit dem schwächeren Teil und erweist ihnen (die schuldige) Ehre, indem ihr in ihnen auch Miterben der Gnadengabe des (ewigen) Lebens seht; sonst würden ja eure (gemeinsamen) Gebete unmöglich gemacht.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (68, 3, 8, 'Schließlich aber: seid alle einträchtig, voll Mitgefühl und Bruderliebe, barmherzig und demütig!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (68, 3, 9, 'Vergeltet nicht Böses mit Bösem oder Scheltwort mit Scheltwort, sondern im Gegenteil segnet, denn dazu seid ihr berufen, damit ihr Segen ererbet.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (68, 3, 10, 'Denn »wer seines Lebens froh werden will und gute Tage zu sehen wünscht, der halte seine Zunge vom Bösen fern und seine Lippen, daß sie nicht Trug reden;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (68, 3, 11, 'er wende sich vom Bösen ab und tue das Gute, er suche Frieden und jage ihm nach!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (68, 3, 12, 'Denn die Augen des Herrn (sind) auf die Gerechten (hingewandt), und seine Ohren (achten) auf ihr Flehen; dagegen ist das Angesicht des Herrn gegen die Übeltäter (gerichtet).«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (68, 3, 13, 'Und wo ist jemand, der euch Böses zufügen sollte, wenn ihr dem Guten eifrig nachtrachtet?');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (68, 3, 14, 'Doch müßtet ihr um der Gerechtigkeit willen auch leiden: selig seid ihr zu preisen! So fürchtet euch denn nicht vor ihnen und laßt euch nicht erschrecken!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (68, 3, 15, 'Haltet nur den Herrn Christus in euren Herzen heilig und seid allezeit bereit, euch gegen jedermann zu verantworten, der von euch Rechenschaft über die Hoffnung fordert, die in euch lebt;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (68, 3, 16, 'tut es jedoch mit Sanftmut und Furcht, so daß ihr euch ein gutes Gewissen bewahrt, damit die, welche euren guten Wandel in Christus schmähen, mit ihren Verleumdungen gegen euch zuschanden werden.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (68, 3, 17, 'Es ist ja doch besser, wenn Gottes Wille es so fügen sollte, für Gutestun zu leiden als für Bösestun.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (68, 3, 18, 'Denn auch Christus ist einmal um der Sünden willen gestorben, als Gerechter für Ungerechte, um uns zu Gott zu führen, er, der am Fleisch zwar getötet worden ist, aber zum Leben erweckt am Geist.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (68, 3, 19, 'Im Geist ist er auch hingegangen und hat den Geistern im Gefängnis gepredigt,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (68, 3, 20, 'nämlich denen, welche einst ungehorsam gewesen waren, als Gottes Langmut geduldig wartete in den Tagen Noahs, während die Arche hergestellt wurde, in der nur wenige, nämlich acht Seelen, Rettung fanden durchs Wasser hindurch.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (68, 3, 21, 'Dieses (Wasser) rettet jetzt als Gegenstück auch euch, nämlich die Taufe, die nicht eine Beseitigung des Schmutzes am Fleisch ist, sondern eine an Gott gerichtete Bitte um ein gutes Gewissen; (sie rettet euch) kraft der Auferstehung Jesu Christi,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (68, 3, 22, 'der nach seiner Himmelfahrt zur Rechten Gottes sitzt: Engel, Gewalten und Mächte sind ihm untertan geworden.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (68, 4, 1, 'Weil nun Christus am Fleisch gelitten hat, so wappnet auch ihr euch mit der gleichen Gesinnung – denn wer leiblich gelitten hat, ist damit zur Ruhe vor der Sünde gekommen –,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (68, 4, 2, 'damit ihr die noch übrige Zeit eures leiblichen Daseins nicht mehr im Dienst menschlicher Lüste, sondern nach dem Willen Gottes verlebt.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (68, 4, 3, 'Denn lang genug ist die vergangene Zeit, in der ihr den Willen der Heiden vollbracht habt, indem ihr in Ausschweifungen und Lüsten, in Trunkenheit, Schmausereien, Zechgelagen und verwerflichem Götzendienst dahingelebt habt.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (68, 4, 4, 'Darum befremdet es sie jetzt, daß ihr euch nicht mehr mit ihnen in denselben Schlamm der Liederlichkeit stürzt, und deshalb schmähen sie euch;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (68, 4, 5, 'doch sie werden sich vor dem zu verantworten haben, der sich bereithält, Lebende und Tote zu richten.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (68, 4, 6, 'Denn dazu ist auch Toten die Heilsbotschaft verkündigt worden, daß sie, wenn sie auch leiblich, dem menschlichen Lose entsprechend, dem Gericht verfallen sind, doch im Geist, dem Wesen Gottes entsprechend, das Leben haben (sollen).');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (68, 4, 7, 'Das Ende aller Dinge steht nahe bevor. Werdet also besonnen und nüchtern zum Gebet;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (68, 4, 8, 'vor allem aber hegt innige Liebe zueinander, denn »die Liebe deckt der Sünden Menge zu«.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (68, 4, 9, 'Seid gastfrei gegeneinander ohne Murren.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (68, 4, 10, 'Dienet einander, ein jeder mit der Gnadengabe, die er empfangen hat, als gute Verwalter der mannigfachen Gnadengaben Gottes!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (68, 4, 11, 'Redet jemand, so seien seine Worte wie Aussprüche Gottes; hat jemand Dienste (als Diakon) zu leisten, so (tue er es) in der Kraft, die Gott verleiht, damit in allen Fällen Gott verherrlicht werde durch Jesus Christus: sein ist die Herrlichkeit und die Macht in alle Ewigkeit. Amen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (68, 4, 12, 'Geliebte, laßt die Feuerglut (der Leiden), die zur Prüfung über euch ergeht, nicht befremdlich auf euch wirken, als ob euch damit etwas Unbegreifliches widerführe,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (68, 4, 13, 'sondern freuet euch darüber in dem Maße, wie ihr an den Leiden Christi Anteil bekommt, damit ihr auch bei der Offenbarung seiner Herrlichkeit euch freuen und jubeln könnt.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (68, 4, 14, 'Wenn ihr um des Namens Christi willen geschmäht werdet, so seid ihr selig zu preisen; denn dann ruht der Geist der Herrlichkeit und der (Geist) Gottes auf euch.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (68, 4, 15, 'Keiner nämlich von euch möge als Mörder oder Dieb oder Übeltäter oder auch nur deshalb leiden, weil er unbefugt in fremde Angelegenheiten eingegriffen hat; muß er aber als Christ leiden,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (68, 4, 16, 'so schäme er sich dessen nicht, sondern mache vielmehr Gott durch diesen (Christen-) Namen Ehre!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (68, 4, 17, 'Denn die Zeit ist da, daß das Gericht beim Hause Gottes seinen Anfang nimmt. Wenn es aber bei uns zuerst (anhebt), wie wird da das Ende bei denen sein, die der Heilsbotschaft Gottes nicht gehorchen?');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (68, 4, 18, 'Und »wenn der Gerechte kaum gerettet wird, wo wird da der Gottlose und Sünder sich zeigen«?');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (68, 4, 19, 'Daher sollen auch die, welche nach dem Willen Gottes zu leiden haben, ihm, dem treuen Schöpfer, ihre Seelen befehlen, und zwar dadurch, daß sie Gutes tun.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (68, 5, 1, 'Die Ältesten nun unter euch ermahne ich als ihr Mitältester und als der Zeuge der Leiden Christi, wie auch als Teilnehmer an der Herrlichkeit, deren Offenbarung bevorsteht:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (68, 5, 2, 'weidet die euch anvertraute Herde Gottes und überwacht sie, nicht aus Zwang, sondern mit freudiger Bereitwilligkeit nach Gottes Willen, auch nicht in schnöder Gewinnsucht, sondern mit Hingebung,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (68, 5, 3, 'auch nicht als Gewaltherrscher über die euch anvertrauten (Gemeinden), sondern als Vorbilder für die Herde;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (68, 5, 4, 'dann werdet ihr auch, wenn der Erzhirte erscheint, den unverwelklichen Kranz der Herrlichkeit empfangen. –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (68, 5, 5, 'Ebenso, ihr Jüngeren: seid den Ältesten untertan. Allesamt aber legt euch im Verkehr miteinander das Dienstgewand der Demut an, denn »Gott widersteht den Hoffärtigen, aber den Demütigen gibt er Gnade«.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (68, 5, 6, 'Demütigt euch also unter die gewaltige Hand Gottes, damit er euch zu seiner Zeit erhöhe!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (68, 5, 7, 'Alle eure Sorge werft auf ihn, denn er sorgt für euch!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (68, 5, 8, 'Seid nüchtern, seid wachsam! Euer Widersacher, der Teufel, geht wie ein brüllender Löwe umher und sucht, wen er verschlingen kann!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (68, 5, 9, 'Dem leistet Widerstand in Glaubensfestigkeit; ihr wißt ja, daß die gleichen Leiden euren Brüdern in der ganzen Welt auferlegt werden.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (68, 5, 10, 'Der Gott aller Gnade aber, der uns berufen hat zu seiner ewigen Herrlichkeit in Christus, der wird euch nach einer kurzen Leidenszeit vollbereiten, festigen, stärken und gründen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (68, 5, 11, 'Sein ist die Macht in alle Ewigkeit! Amen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (68, 5, 12, '(Dies) habe ich euch durch Silvanus, den – wie ich überzeugt bin – treuen Bruder, in Kürze geschrieben, um euch zu ermahnen und euch zu bezeugen, daß dies die wahre Gnade Gottes ist, in der ihr stehen sollt. –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (68, 5, 13, 'Es grüßt euch die miterwählte (Gemeinde) in Babylon und mein Sohn Markus.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (68, 5, 14, 'Grüßt einander mit dem Liebeskuß! Friede sei mit euch allen, die ihr in Christus seid!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (69, 1, 1, 'Ich, Symeon Petrus, ein Knecht und Apostel Jesu Christi, sende meinen Gruß denen, welche mit uns den gleichwertigen Glauben durch die Gerechtigkeit unsers Gottes und (des) Erretters Jesus Christus erlangt haben.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (69, 1, 2, 'Gnade und Friede möge euch in der Erkenntnis Gottes und unsers Herrn Jesus immer reichlicher zuteil werden!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (69, 1, 3, 'Seine göttliche Kraft hat uns ja doch alles, was zum Leben und zur Gottseligkeit erforderlich ist, durch die Erkenntnis dessen geschenkt, der uns durch die ihm eigene Herrlichkeit und Tugend berufen hat.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (69, 1, 4, 'Durch sie hat er uns die kostbaren und überaus wichtigen Verheißungen geschenkt, damit ihr durch diese dem in der Welt infolge der Sinnenlust herrschenden Verderben entrinnet und Anteil an der göttlichen Natur erhaltet.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (69, 1, 5, 'Eben darum müßt ihr aber auch mit Aufbietung allen Eifers in eurem Glauben die Tugend darreichen, in der Tugend die Erkenntnis,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (69, 1, 6, 'in der Erkenntnis die Selbstbeherrschung, in der Selbstbeherrschung die Standhaftigkeit, in der Standhaftigkeit die Gottseligkeit,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (69, 1, 7, 'in der Gottseligkeit die Bruderliebe, in der Bruderliebe die allgemeine Liebe.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (69, 1, 8, 'Denn wenn diese (Eigenschaften) bei euch vorhanden sind und beständig zunehmen, so lassen sie euch hinsichtlich der Erkenntnis unsers Herrn Jesus Christus nicht untätig und ohne Frucht bleiben.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (69, 1, 9, 'Wem dagegen diese (Eigenschaften) fehlen, der ist blind in Kurzsichtigkeit und hat die Reinigung von seinen früheren Sünden in Vergessenheit geraten lassen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (69, 1, 10, 'Darum seid um so eifriger darauf bedacht, liebe Brüder, eure Berufung und Erwählung festzumachen; denn wenn ihr das tut, werdet ihr sicherlich niemals zu Fall kommen;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (69, 1, 11, 'denn auf diese Weise wird euch der Eingang in das ewige Reich unsers Herrn und Retters Jesus Christus gewährt werden.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (69, 1, 12, 'Daher will ich auch darauf bedacht sein, euch immer wieder an diese Dinge zu erinnern, wenn sie euch auch schon bekannt sind und ihr in der Wahrheit, wie sie (bei euch) vorhanden ist, fest gegründet seid.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (69, 1, 13, 'Ich halte es aber für meine Pflicht, solange ich noch in dieser Leibeshütte wohne, euch durch solches Erinnern wachzuhalten,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (69, 1, 14, 'zumal da ich weiß, daß das Ablegen meiner Leibeshütte plötzlich erfolgen wird, wie es mir auch unser Herr Jesus Christus angekündigt hat.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (69, 1, 15, 'Ich will aber dafür Sorge tragen, daß ihr auch nach meinem Heimgang jederzeit in der Lage seid, euch diese Dinge ins Gedächtnis zu rufen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (69, 1, 16, 'Denn wir sind nicht klug ersonnenen Fabeln nachgegangen, als wir euch die Macht und Wiederkunft unsers Herrn Jesus Christus verkündigten, sondern wir sind Augenzeugen seiner wunderbaren Herrlichkeit gewesen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (69, 1, 17, 'Denn von Gott dem Vater hat er (damals) Ehre und Verherrlichung empfangen, als von der hocherhabenen Herrlichkeit jener Zuruf an ihn erging: »Dieser ist mein geliebter Sohn, an dem ich Wohlgefallen gefunden habe.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (69, 1, 18, 'Diesen Ruf haben wir ja vom Himmel her erschallen hören, als wir mit ihm auf dem heiligen Berge waren,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (69, 1, 19, 'und um so fester steht uns nun das prophetische Wort, das wir besitzen, und ihr tut wohl, auf dieses achtzugeben als auf ein Licht, das an einem dunklen Ort scheint, bis der volle Tag anbricht und der Morgenstern in euren Herzen aufgeht.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (69, 1, 20, 'Dabei müßt ihr euch vor allem darüber klar sein, daß keine Weissagung der Schrift eine eigenmächtige Deutung zuläßt;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (69, 1, 21, 'denn noch niemals ist eine Weissagung durch menschlichen Willen ergangen, sondern, vom heiligen Geist getrieben, haben Menschen von Gott aus geredet.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (69, 2, 1, 'Es sind allerdings auch falsche Propheten unter dem Volk (Israel) aufgetreten, wie es auch unter euch falsche Lehrer geben wird, welche verderbliche Irrlehren heimlich bei euch einführen werden, indem sie sogar den Herrn, der sie (zu seinem Eigentum) erkauft hat, verleugnen, wodurch sie jähes Verderben über sich bringen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (69, 2, 2, 'Viele jedoch werden sich ihnen bei ihren Ausschweifungen anschließen, und um dieser willen wird der Weg der Wahrheit gelästert werden.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (69, 2, 3, 'Von Gewinnsucht getrieben, werden sie euch durch erdichtete Worte auszubeuten suchen; aber das Verdammungsurteil ist für sie von altersher nicht müßig, und ihr Verderben schlummert nicht.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (69, 2, 4, 'Gott hat ja nicht einmal gegen sündige Engel Schonung geübt, sondern hat sie in den tiefsten Abgrund hinabgestoßen, hinein in Ketten der Finsternis, wo sie für das Gericht aufbewahrt werden.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (69, 2, 5, 'Er hat auch die alte Welt nicht verschont, sondern nur Noah, den Herold der Gerechtigkeit, zusammen mit sieben anderen (Personen) am Leben erhalten, als er die Sintflut über die gottlose Menschenwelt hereinbrechen ließ.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (69, 2, 6, 'Ebenso hat er die Städte Sodom und Gomorrha in Asche gelegt und sie zum Untergang verurteilt und sie dadurch als warnendes Beispiel für künftige Gottlose hingestellt.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (69, 2, 7, 'Den gerechten Lot aber, der unter dem ausschweifenden Lebenswandel der Zuchtlosen schwer litt, hat er gerettet;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (69, 2, 8, 'denn die gesetzwidrigen Taten, die der unter ihnen lebende Gerechte Tag für Tag sehen und hören mußte, verursachten seiner gerechten Seele Qualen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (69, 2, 9, 'So versteht der Herr es wohl, Gottselige aus der Prüfung zu erretten, Ungerechte dagegen für den Tag des Gerichts unter Verbüßung von Strafen aufzubewahren,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (69, 2, 10, 'vornehmlich solche, die in Begier nach Befleckung dem Fleisch nachlaufen und niemand als Herrn über sich anerkennen. In ihrer frechen Vermessenheit schrecken sie nicht vor der Lästerung von Herrlichkeiten zurück,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (69, 2, 11, 'während doch Engel, obwohl sie an Kraft und Macht über ihnen stehen, kein lästerndes Urteil gegen sie beim Herrn vorbringen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (69, 2, 12, 'Diese Leute aber sind wie vernunftlose Tiere, die ihrer Natur entsprechend nur dazu geschaffen sind, daß man sie fängt und abtut; sie schmähen das, wovon sie nichts verstehen, und werden auch in dem Untergang, wie er jene trifft, zugrunde gehen');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (69, 2, 13, 'und den Lohn für ihre Ungerechtigkeit empfangen. Schon am hellen Tage zu schlemmen halten sie für eine Lust; als Schmutz- und Schandflecken schwelgen sie in ihren verführerischen Lehren, wenn sie mit euch zusammen schmausen;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (69, 2, 14, 'ihre Augen sind voll ehebrecherischer Gier und im Sündigen unersättlich; sie locken ungefestigte Seelen an sich und haben ein in Gewinnsucht wohlgeübtes Herz: Kinder des Fluches!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (69, 2, 15, 'Den geraden Weg haben sie verlassen und sind irregegangen; sie haben den Weg Bileams, des Sohnes Bosors, eingeschlagen, der nach Sündenlohn Verlangen trug,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (69, 2, 16, 'aber auch für seine Gesetzesübertretung eine Zurechtweisung erhielt: ein (sonst) sprachloses Lasttier, das mit Menschenstimme redete, verhinderte das törichte Beginnen des Propheten.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (69, 2, 17, 'Diese Leute sind wasserlose Quellen und Nebelschwaden, die vom Sturmwind dahingetrieben werden; die dunkelste Finsternis ist für sie aufgespart.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (69, 2, 18, 'Denn indem sie hochfahrende Reden führen, hinter denen nichts ist, locken sie im Taumel fleischlicher Begierden durch Ausschweifungen solche an sich, die sich eben erst von den im Irrwahn Wandelnden abgekehrt hatten;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (69, 2, 19, 'sie verheißen ihnen Freiheit, während sie selbst doch Sklaven des Verderbens sind; denn von wem jemand im Kampf überwunden ist, dem ist er auch als Sklave verfallen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (69, 2, 20, 'Wenn sie nämlich den Befleckungen der Welt durch die Erkenntnis des Herrn und Erretters Jesus Christus entronnen waren und sich doch aufs neue in diese verstricken und von ihnen überwinden lassen, dann ist der letzte Zustand für sie schlimmer geworden, als der erste war.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (69, 2, 21, 'Denn es wäre besser für sie gewesen, sie hätten den Weg der Gerechtigkeit überhaupt nicht kennengelernt, als daß sie sich nach erlangter Erkenntnis von dem ihnen mitgeteilten heiligen Gebot wieder abgewandt haben.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (69, 2, 22, 'Bei ihnen bestätigt sich die Wahrheit des Sprichworts: »Ein Hund kehrt zu seinem eigenen Gespei zurück« und »Ein Schwein wälzt sich nach der Schwemme wieder im Kot.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (69, 3, 1, 'Dies ist nun schon der zweite Brief, Geliebte, den ich euch schreibe; in beiden suche ich die lautere Gesinnung in euch durch (meine) mahnende Erinnerung wachzurufen,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (69, 3, 2, 'damit ihr die Worte, welche die heiligen Propheten zuvor geredet haben, und das von euren Aposteln euch mitgeteilte Gebot unsers Herrn und Erretters in der Erinnerung festhaltet.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (69, 3, 3, 'Ihr müßt dabei aber zunächst bedenken, daß am Ende der Tage Spötter voll Spottsucht auftreten werden, Menschen, die nach ihren eigenen Lüsten wandeln');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (69, 3, 4, 'und sagen: »Wo ist denn seine verheißene Wiederkunft? Seitdem die Väter entschlafen sind, bleibt ja alles doch so, wie es seit Beginn der Schöpfung gewesen ist.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (69, 3, 5, 'Bei dieser Behauptung lassen sie nämlich unbeachtet, daß es von alters her Himmel gab und eine Erde da war, die aus Wasser und mittelst Wassers kraft des Wortes Gottes ihren Bestand hatte,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (69, 3, 6, 'und eben deshalb ist die damalige Welt im Wasser durch Überflutung zugrunde gegangen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (69, 3, 7, 'Der gegenwärtige Himmel und die (jetzige) Erde dagegen sind durch dasselbe Wort für das Feuer aufgespart und werden für den Tag des Gerichts und des Untergangs der gottlosen Menschen aufbewahrt.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (69, 3, 8, 'Ferner dürft ihr dies eine nicht unbeachtet lassen, Geliebte, daß »ein Tag beim Herrn wie tausend Jahre ist und tausend Jahre wie ein Tag«.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (69, 3, 9, 'Der Herr ist mit der (Erfüllung seiner) Verheißung nicht säumig, wie manche Leute (in seinem Verhalten) eine Säumigkeit sehen, sondern er übt Langmut gegen euch, weil er nicht will, daß einige verlorengehen, sondern daß alle zur Buße gelangen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (69, 3, 10, 'Kommen aber wird der Tag des Herrn wie ein Dieb; an ihm werden die Himmel mit Krachen vergehen, die Elemente aber in der Flammenglut sich auflösen, und die Erde wird mit allen Menschenwerken, die auf ihr sind, in Feuer aufgehen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (69, 3, 11, 'Da nun dies alles sich so auflöst, wie muß es da bei euch mit den Erweisen von heiligem Wandel und Gottseligkeit bestellt sein,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (69, 3, 12, 'indem ihr auf die Ankunft des Tages Gottes wartet und euch darauf rüstet, um dessen willen die Himmel im Feuer zergehen werden und die Elemente in der Flammenglut zerschmelzen!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (69, 3, 13, 'Wir erwarten aber nach seiner Verheißung neue Himmel und eine neue Erde, in denen Gerechtigkeit wohnt.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (69, 3, 14, 'Darum, Geliebte, seid in Erwartung dieser Dinge eifrig bemüht, fleckenlos und unsträflich vor ihm erfunden zu werden im Frieden,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (69, 3, 15, 'und erachtet die Langmut unsers Herrn für Errettung, wie ja auch unser geliebter Bruder Paulus nach der ihm verliehenen Weisheit euch geschrieben hat.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (69, 3, 16, 'Ebenso ist es ja in allen seinen Briefen der Fall, wenn er in ihnen auf diese Dinge zu sprechen kommt. In diesen (Briefen) findet sich allerdings manches Schwerverständliche, das die Unwissenden und Ungefestigten ebenso zu ihrem eigenen Verderben verdrehen, wie sie es auch bei den übrigen (heiligen) Schriften tun.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (69, 3, 17, 'Weil ihr dies nun zum voraus wißt, Geliebte, so seid auf eurer Hut, daß ihr nicht durch die Verirrung der gewissenlosen Leute mit fortgerissen und aus eurem eigenen festen Glaubensstande hinausgeworfen werdet!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (69, 3, 18, 'Wachst vielmehr in der Gnade und Erkenntnis unsers Herrn und Erretters Jesus Christus! Ihm gebührt die Herrlichkeit sowohl jetzt als auch für den Tag der Ewigkeit!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (70, 1, 1, 'Was von Anfang an da war, was wir gehört, was wir mit unsern (eigenen) Augen gesehen, was wir beschaut und unsere Hände betastet haben, (nämlich) vom Wort des Lebens, –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (70, 1, 2, 'und das Leben ist offenbar geworden, und wir haben (es) gesehen und bezeugen und verkündigen euch das ewige Leben, das beim Vater war und uns offenbar geworden ist –,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (70, 1, 3, 'was wir (also) gesehen und gehört haben, das verkündigen wir auch euch, damit auch ihr Gemeinschaft mit uns habt; die Gemeinschaft mit uns ist aber (zugleich) auch die (Gemeinschaft) mit dem Vater und mit seinem Sohne Jesus Christus.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (70, 1, 4, 'Und dieses schreiben wir (euch), damit unsere Freude vollkommen sei.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (70, 1, 5, 'Und dies ist die Botschaft, die wir von ihm gehört haben und euch verkündigen: »Gott ist Licht, und keinerlei Finsternis ist in ihm.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (70, 1, 6, 'Wenn wir behaupten, Gemeinschaft mit ihm zu haben, und dabei doch in der Finsternis wandeln, so lügen wir und halten uns nicht an die Wahrheit.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (70, 1, 7, 'Wenn wir aber im Licht wandeln, wie er im Licht ist, so haben wir Gemeinschaft miteinander, und das Blut seines Sohnes Jesus macht uns von aller Sünde rein.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (70, 1, 8, 'Wenn wir behaupten, keine Sünde zu haben, so betrügen wir uns selbst, und die Wahrheit ist nicht in uns;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (70, 1, 9, 'wenn wir (aber) unsere Sünden bekennen, so ist er treu und gerecht, daß er uns die Sünden vergibt und uns von aller Ungerechtigkeit reinigt.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (70, 1, 10, 'Wenn wir behaupten, nicht gesündigt zu haben, so machen wir ihn zum Lügner, und sein Wort ist nicht in uns.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (70, 2, 1, 'Meine Kindlein, dieses schreibe ich euch, damit ihr nicht sündigt. Sollte aber jemand (trotzdem) sündigen, so haben wir einen Fürsprecher beim Vater, nämlich Jesus Christus, den Gerechten.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (70, 2, 2, 'Und er ist die Versöhnung für unsere Sünden, aber nicht nur für die unsrigen, sondern auch für die der ganzen Welt.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (70, 2, 3, 'Daran erkennen wir aber, daß wir ihn erkannt haben: wenn wir seine Gebote halten.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (70, 2, 4, 'Wer da behauptet: »Ich habe ihn erkannt« und (dabei) seine Gebote nicht hält, der ist ein Lügner, und in diesem wohnt die Wahrheit nicht.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (70, 2, 5, 'Wer aber sein Wort hält, in dem ist die Liebe zu Gott zur Vollendung gekommen: daran erkennen wir, daß wir in ihm sind.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (70, 2, 6, 'Wer da behauptet, er bleibe in ihm, der ist auch verpflichtet, selbst ebenso zu wandeln, wie er gewandelt ist.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (70, 2, 7, 'Geliebte, nicht ein neues Gebot schreibe ich euch, sondern es ist ein altes Gebot, das ihr von Anfang an gehabt habt; das alte Gebot ist das Wort, das ihr gehört habt.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (70, 2, 8, 'Andrerseits ist es auch ein neues Gebot, das ich euch schreibe, wie dies sich in ihm und in euch als wahr erweist; denn die Finsternis ist im Verschwinden, und das wahre Licht leuchtet bereits.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (70, 2, 9, 'Wer nun im Licht zu sein behauptet und doch seinen Bruder haßt, befindet sich immer noch in der Finsternis.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (70, 2, 10, 'Wer seinen Bruder liebt, der ist dauernd im Licht, und kein Anstoß ist in ihm vorhanden.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (70, 2, 11, 'Wer dagegen seinen Bruder haßt, befindet sich in der Finsternis und wandelt in der Finsternis und weiß nicht, wohin er geht, weil die Finsternis seine Augen blind gemacht hat.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (70, 2, 12, 'Ich schreibe euch, ihr Kindlein, weil euch die Sünden um seines Namens willen vergeben sind.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (70, 2, 13, 'Ich schreibe euch, ihr Väter, weil ihr den erkannt habt, der von Anfang an ist. Ich schreibe euch, ihr Jünglinge, weil ihr den Bösen überwunden habt. Ich habe euch, ihr Kindlein, geschrieben, weil ihr den Vater erkannt habt.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (70, 2, 14, 'Ich habe euch geschrieben, ihr Väter, weil ihr den erkannt habt, der von Anfang an ist. Ich habe euch, ihr Jünglinge, geschrieben, weil ihr stark seid, und das Wort Gottes dauernd in euch wohnt und ihr den Bösen überwunden habt.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (70, 2, 15, 'Habt nicht lieb die Welt, auch nicht das, was in der Welt ist! Wenn jemand die Welt lieb hat, so wohnt die Liebe zum Vater nicht in ihm;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (70, 2, 16, 'denn alles weltliche Wesen, die Fleischeslust und die Augenlust und das hoffärtige Leben, kommt nicht vom Vater her, sondern stammt aus der Welt;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (70, 2, 17, 'und die Welt vergeht samt ihrer Lust; wer aber den Willen Gottes tut, der bleibt in Ewigkeit.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (70, 2, 18, 'Ihr Kindlein, die letzte Stunde ist da, und wie ihr gehört habt, daß ein Widerchrist kommt, so sind jetzt schon Widerchristen in großer Anzahl aufgetreten; daran erkennen wir, daß die letzte Stunde da ist.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (70, 2, 19, 'Sie sind aus unserer Mitte hervorgegangen, haben aber nicht (wirklich) zu uns gehört; denn wenn sie (in der Tat) zu uns gehörten, wären sie bei uns geblieben; so aber sollte (an ihnen) offenbar werden, daß sie nicht alle von uns sind.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (70, 2, 20, 'Doch ihr habt die Salbung vom Heiligen (empfangen) und seid im vollen Besitz des Wissens.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (70, 2, 21, 'Ich habe euch nicht geschrieben, weil euch die Wahrheit unbekannt ist, im Gegenteil: weil ihr sie kennt und auch (wißt), daß keine Lüge ihren Ursprung aus der Wahrheit hat.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (70, 2, 22, 'Wer ist der Lügner? Doch wohl der, welcher leugnet, daß Jesus der Gottgesalbte ist. Der ist der Widerchrist, der den Vater und den Sohn leugnet.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (70, 2, 23, 'Jeder, der den Sohn leugnet, hat auch den Vater nicht; wer (dagegen) den Sohn bekennt, der hat auch den Vater.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (70, 2, 24, 'Was ihr von Anfang an gehört habt, das muß auch dauernd in euch bleiben. Wenn das, was ihr von Anfang an gehört habt, in euch bleibt, so werdet auch ihr im Sohn und im Vater bleiben,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (70, 2, 25, 'und das ist eben die Verheißung, die er uns gegeben hat: das ewige Leben.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (70, 2, 26, 'Dies habe ich euch im Hinblick auf die geschrieben, welche euch irreführen (wollen).');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (70, 2, 27, 'Und was euch betrifft, so bleibt die (geistige) Salbung, die ihr von ihm empfangen habt, dauernd in euch, und ihr bedürft keiner anderweitigen Belehrung; nein, wie seine Salbung euch über alles belehrt, so ist sie auch wahr und ist keine Lüge; und wie sie euch gelehrt hat, so bleibt (nun auch) in ihm!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (70, 2, 28, 'Und gerade jetzt, ihr Kindlein, bleibet in ihm, damit wir, wenn er sich offenbart, freudige Zuversicht haben dürfen und bei seiner Ankunft nicht beschämt vor ihm zurücktreten müssen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (70, 2, 29, 'Wenn ihr wißt, daß er gerecht ist, so erkennet auch zugleich, daß jeder, der die Gerechtigkeit übt, aus ihm erzeugt ist.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (70, 3, 1, 'Sehet, welch große Liebe uns der Vater dadurch erwiesen hat, daß wir Kinder Gottes heißen sollen, und wir sind es auch. Deshalb erkennt die Welt uns nicht, weil sie ihn nicht erkannt hat.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (70, 3, 2, 'Geliebte, (schon) jetzt sind wir Kinder Gottes, und es ist noch nicht offenbar geworden, was wir (dereinst) sein werden. Wir wissen jedoch, daß, wenn diese Offenbarung eintritt, wir ihm gleich sein werden; denn wir werden ihn sehen, wie er ist.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (70, 3, 3, 'Und jeder, der diese Hoffnung auf ihn setzt, reinigt sich, gleichwie er (auch) rein ist.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (70, 3, 4, 'Jeder, der Sünde tut, begeht damit auch Gesetzlosigkeit, und die Sünde ist die Gesetzlosigkeit.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (70, 3, 5, 'Ihr wißt aber, daß er dazu erschienen ist, um die Sünden hinwegzunehmen, und daß keinerlei Sünde in ihm ist.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (70, 3, 6, 'Jeder, der in ihm bleibt, sündigt nicht; wer da sündigt, hat ihn nicht gesehen und nicht erkannt.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (70, 3, 7, 'Kindlein, laßt euch von niemand irreführen! (Nur) wer die Gerechtigkeit tut, ist gerecht, so wie er gerecht ist;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (70, 3, 8, 'wer die Sünde tut, stammt vom Teufel, denn der Teufel ist ein Sünder von Anfang an. Dazu ist der Sohn Gottes erschienen, daß er die Werke des Teufels zerstöre.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (70, 3, 9, 'Jeder, der aus Gott erzeugt ist, tut keine Sünde, weil sein Same dauernd in ihm ist, und er kann nicht sündigen, weil er aus Gott erzeugt ist.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (70, 3, 10, 'Daran sind die Kinder Gottes und die Kinder des Teufels zu erkennen: Jeder, der die Gerechtigkeit nicht tut, stammt nicht aus Gott, und (ebenso) auch jeder, der seinen Bruder nicht liebt.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (70, 3, 11, 'Denn dies ist die Botschaft, die ihr von Anfang an gehört habt: »Wir sollen einander lieben«,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (70, 3, 12, 'nicht in der Weise Kains, der ein Kind des Teufels war und seinen Bruder erschlug; und warum hat er ihn erschlagen? Weil sein ganzes Tun böse war, das Tun seines Bruders dagegen gerecht.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (70, 3, 13, 'Wundert euch nicht, liebe Brüder, wenn die Welt euch haßt.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (70, 3, 14, 'Wir wissen, daß wir aus dem Tode ins Leben hinübergegangen sind, weil wir die Brüder lieben: wer (seinen Bruder) nicht liebt, verbleibt im Tode.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (70, 3, 15, 'Jeder, der seinen Bruder haßt, ist ein Menschenmörder, und ihr wißt, daß kein Menschenmörder ewiges Leben als bleibenden Besitz in sich trägt.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (70, 3, 16, 'Daran haben wir die Liebe erkannt, daß er sein Leben für uns hingegeben hat; so sind nun auch wir verpflichtet, das Leben für die Brüder hinzugeben.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (70, 3, 17, 'Wenn jemand aber die Güter dieser Welt besitzt und seinen Bruder Not leiden sieht und sein Herz vor ihm verschließt: wie bleibt da die Liebe Gottes in ihm?');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (70, 3, 18, 'Kindlein, laßt uns nicht mit Worten und nicht mit der Zunge lieben, sondern mit der Tat und in Wahrheit!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (70, 3, 19, 'Daran werden wir erkennen, daß wir aus der Wahrheit sind, und werden unsere Herzen vor ihm davon überzeugen,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (70, 3, 20, 'daß, wenn unser Herz uns verurteilt, Gott größer ist als unser Herz und alles erkennt.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (70, 3, 21, 'Geliebte, wenn unser Herz (uns) nicht verurteilt, so besitzen wir Freudigkeit zu Gott,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (70, 3, 22, 'und um was wir auch bitten, das empfangen wir von ihm, weil wir seine Gebote halten und das tun, was ihm wohlgefällig ist.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (70, 3, 23, 'Dies ist aber sein Gebot, daß wir an den Namen seines Sohnes Jesus Christus glauben und einander lieben dem Gebot entsprechend, das er uns gegeben hat.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (70, 3, 24, 'Und wer seine Gebote hält, der bleibt in der Gemeinschaft mit ihm und er mit ihm; und daran erkennen wir, daß er in der Gemeinschaft mit uns bleibt: an dem Geist, den er uns gegeben hat.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (70, 4, 1, 'Geliebte, schenkt nicht jedem Geiste Glauben, sondern prüfet die Geister, ob sie aus Gott sind; denn viele falsche Propheten sind in die Welt ausgezogen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (70, 4, 2, 'Daran könnt ihr den Geist Gottes erkennen: Jeder Geist, der da bekennt, daß Jesus der im Fleisch gekommene Christus ist, der ist aus Gott;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (70, 4, 3, 'und jeder Geist, der Jesus nicht so bekennt, ist nicht aus Gott; das ist vielmehr der Geist des Widerchrists, von dessen Kommen ihr gehört habt und der jetzt schon in der Welt ist.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (70, 4, 4, 'Ihr seid aus Gott, Kindlein, und habt sie überwunden, weil der, welcher in euch (wirksam) ist, stärker ist als der in der Welt.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (70, 4, 5, 'Sie stammen aus der Welt; deshalb reden sie aus der Welt heraus, und die Welt hört auf sie.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (70, 4, 6, 'Wir aber sind aus Gott; wer Gott (er)kennt, der hört auf uns; wer nicht aus Gott ist, hört nicht auf uns. Daran erkennen wir den Geist der Wahrheit und den Geist der Täuschung.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (70, 4, 7, 'Geliebte, laßt uns einander lieben! Denn die Liebe stammt aus Gott, und jeder, der liebt, ist aus Gott erzeugt und erkennt Gott.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (70, 4, 8, 'Wer nicht liebt, hat Gott nicht erkannt; denn Gott ist Liebe.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (70, 4, 9, 'Darin ist die Liebe Gottes an uns offenbar geworden, daß Gott seinen eingeborenen Sohn in die Welt gesandt hat, damit wir durch ihn leben.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (70, 4, 10, 'Darin besteht die Liebe: nicht daß wir Gott geliebt haben, sondern daß er uns geliebt und seinen Sohn zur Sühnung für unsere Sünden gesandt hat.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (70, 4, 11, 'Geliebte, wenn Gott uns so sehr geliebt hat, so sind auch wir verpflichtet, einander zu lieben.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (70, 4, 12, 'Niemand hat Gott jemals (mit Augen) gesehen; doch wenn wir einander lieben, so bleibt Gott dauernd in uns, und seine Liebe ist in uns zur Vollendung gekommen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (70, 4, 13, 'Daß wir aber in ihm bleiben und er in uns, erkennen wir daran, daß er uns (eine Spende) von seinem Geist gegeben hat.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (70, 4, 14, 'Und wir haben (mit Augen) gesehen und bezeugen es, daß der Vater den Sohn als Retter der Welt gesandt hat.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (70, 4, 15, 'Wer nun bekennt, daß Jesus der Sohn Gottes ist, in dem wohnt Gott dauernd, und er wohnt dauernd in Gott.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (70, 4, 16, 'Und wir haben die Liebe, die Gott zu uns hat, erkannt und geglaubt: Gott ist Liebe, und wer in der Liebe bleibt, der bleibt in Gott, und Gott bleibt in ihm.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (70, 4, 17, 'Darin ist die Liebe bei uns zur Vollendung gekommen, daß wir eine freudige Zuversicht am Tage des Gerichts haben; denn wie er ist, so sind auch wir in dieser Welt.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (70, 4, 18, 'Furcht ist nicht in der Liebe, sondern die vollkommene Liebe treibt die Furcht aus, weil die Furcht es mit Strafe zu tun hat; wer also Furcht empfindet, der ist in der Liebe noch nicht zur Vollendung gelangt.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (70, 4, 19, 'Wir dagegen lieben, weil er uns zuerst geliebt hat.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (70, 4, 20, 'Wenn jemand behauptet: »Ich liebe Gott« und doch seinen Bruder haßt, so ist er ein Lügner; denn wer seinen Bruder nicht liebt, der sichtbar bei ihm ist, kann ganz gewiß Gott nicht lieben, den er nicht gesehen hat.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (70, 4, 21, 'Und dies Gebot haben wir von ihm, daß, wer Gott liebt, auch seinen Bruder liebe.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (70, 5, 1, 'Jeder, der da glaubt, daß Jesus der Gottgesalbte ist, der ist aus Gott erzeugt, und jeder, der seinen Vater liebt, liebt auch dessen Kinder.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (70, 5, 2, 'Daran erkennen wir, daß wir die Kinder Gottes lieben, wenn wir Gott lieben und seine Gebote erfüllen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (70, 5, 3, 'Denn das ist die Liebe zu Gott, daß wir seine Gebote halten; und seine Gebote sind nicht schwer;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (70, 5, 4, 'denn alles, was aus Gott erzeugt ist, überwindet die Welt; und dies ist die Siegesmacht, welche die Welt überwunden hat: unser Glaube.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (70, 5, 5, 'Wer anders aber ist es, der die Welt überwindet, außer dem, welcher glaubt, daß Jesus der Sohn Gottes ist?');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (70, 5, 6, 'Dieser ist es, der durch Wasser und Blut gekommen ist, Jesus Christus; nicht im Wasser allein, sondern im Wasser und im Blut; und der Geist ist es, der Zeugnis (für ihn) ablegt, weil der Geist die Wahrheit ist.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (70, 5, 7, 'Drei sind es nämlich, die Zeugnis ablegen:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (70, 5, 8, 'der Geist, das Wasser und das Blut; und diese drei sind vereint.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (70, 5, 9, 'Wenn wir schon das Zeugnis der Menschen annehmen, so hat das Zeugnis Gottes doch noch größere Kraft; denn darin besteht das Zeugnis Gottes, daß er Zeugnis über seinen Sohn abgelegt hat.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (70, 5, 10, 'Wer an den Sohn Gottes glaubt, hat das Zeugnis in ihm. Wer (dagegen) Gott nicht glaubt, hat ihn (damit) zum Lügner gemacht; denn er hat dem Zeugnis, das Gott über seinen Sohn abgelegt hat, keinen Glauben geschenkt.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (70, 5, 11, 'Und dies Zeugnis lautet so: »Gott hat uns ewiges Leben gegeben, und dieses Leben ist in seinem Sohne vorhanden.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (70, 5, 12, 'Wer den Sohn hat, der hat das Leben; wer den Sohn Gottes nicht hat, der hat auch das Leben nicht.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (70, 5, 13, 'Dies habe ich euch, die ihr an den Namen des Sohnes Gottes glaubt, geschrieben, damit ihr wißt, daß ihr ewiges Leben habt.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (70, 5, 14, 'Und dies ist die freudige Zuversicht, die wir zu ihm haben, daß, wenn wir ihn um etwas nach seinem Willen bitten, er uns erhört.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (70, 5, 15, 'Und wenn wir wissen, daß er alle unsere Bitten erhört, so wissen wir (zugleich), daß die Bitten, die wir vor ihn gebracht haben, uns schon gewährt sind. –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (70, 5, 16, 'Wenn jemand seinen Bruder eine Sünde begehen sieht, eine Sünde, die nicht zum Tode ist, so soll er (für ihn) bitten und ihm dadurch zum Leben verhelfen, nämlich denen, die nicht zum Tode sündigen. Es gibt (nämlich) auch eine Sünde zum Tode; von dieser sage ich nicht, daß man (für eine solche) Fürbitte einlegen soll.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (70, 5, 17, 'Jede Ungerechtigkeit ist Sünde; doch es gibt auch Sünde, die nicht zum Tode ist.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (70, 5, 18, 'Wir wissen, daß jeder, der aus Gott erzeugt ist, nicht sündigt, sondern wer aus Gott erzeugt ist, bewahrt sich, und der Böse tastet ihn nicht an.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (70, 5, 19, 'Wir wissen, daß wir aus Gott sind, die ganze Welt dagegen im Argen liegt.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (70, 5, 20, 'Wir wissen aber (auch), daß der Sohn Gottes gekommen ist und uns Einsicht verliehen hat, damit wir den Wahrhaftigen erkennen; und wir sind in dem Wahrhaftigen, (indem wir) in seinem Sohne Jesus Christus (sind). Dieser ist der wahrhaftige Gott und ewiges Leben.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (70, 5, 21, 'Kindlein, hütet euch vor den Götzen!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (71, 1, 1, 'Ich, der Alte, sende meinen Gruß der auserwählten Herrin und ihren Kindern, die ich aufrichtig lieb habe – und nicht ich allein, sondern alle, welche die Wahrheit erkannt haben –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (71, 1, 2, 'um der Wahrheit willen, die dauernd in uns wohnt und in unserer Mitte sein wird in Ewigkeit.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (71, 1, 3, 'Gnade, Barmherzigkeit und Friede werden mit uns sein von Gott dem Vater und von Jesus Christus, dem Sohne des Vaters, in Wahrheit und Liebe.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (71, 1, 4, 'Es ist mir eine große Freude gewesen, daß ich unter deinen Kindern solche gefunden habe, die in der Wahrheit wandeln dem Gebot entsprechend, das wir vom Vater empfangen haben.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (71, 1, 5, 'Und jetzt wende ich mich an dich, Herrin, mit einer Bitte – nicht als ob ich dir ein neues Gebot schriebe, sondern nur das, welches wir von Anfang an gehabt haben –: daß wir einander lieben sollen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (71, 1, 6, 'Und darin besteht die Liebe (zu Gott), daß wir nach seinen Geboten wandeln. Dies ist das Gebot, wie ihr es von Anfang an gehört habt, daß ihr darin wandeln sollt.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (71, 1, 7, 'Denn viele Irrlehrer sind in die Welt ausgezogen, die Jesus Christus nicht als den im Fleisch erscheinenden (Messias) bekennen: darin zeigt sich der Irrlehrer und der Widerchrist.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (71, 1, 8, 'Gebt acht auf euch selbst, daß ihr nicht das verliert, was ihr durch eure Arbeit bereits erreicht habt, sondern vollen Lohn empfangt.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (71, 1, 9, 'Jeder, der darüber hinausgeht und nicht in der Lehre Christi verbleibt, der hat Gott nicht; wer (dagegen) in der Lehre verbleibt, der hat sowohl den Vater als auch den Sohn.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (71, 1, 10, 'Wenn jemand zu euch kommt und diese Lehre nicht mitbringt, so nehmt ihn nicht ins Haus und bietet ihm auch keinen Gruß!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (71, 1, 11, 'Denn wer ihn begrüßt, macht sich an seinem bösen Tun mitschuldig.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (71, 1, 12, 'Ich hätte euch noch vieles zu schreiben, mag es aber nicht mit Papier und Tinte tun; vielmehr hoffe ich, zu euch zu kommen und mich mündlich (mit euch) auszusprechen, damit unsere Freude vollkommen sei.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (71, 1, 13, 'Es grüßen dich die Kinder deiner Schwester, der Auserwählten.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (72, 1, 1, 'Ich, der Alte, sende meinen Gruß dem geliebten Gajus, den ich aufrichtig lieb habe.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (72, 1, 2, 'Geliebter, ich wünsche dir allseitiges Wohlergehen und Gesundheit, wie es ja mit deiner Seele gut steht.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (72, 1, 3, 'Denn es ist mir eine große Freude gewesen, wenn Brüder kamen und dir wegen deiner Wahrhaftigkeit ein anerkennendes Zeugnis erteilten, wie du ja (wirklich) in der Wahrheit wandelst.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (72, 1, 4, 'Eine größere Freude gibt es für mich nicht als die, von meinen Kindern zu hören, daß sie in der Wahrheit wandeln.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (72, 1, 5, 'Geliebter, du handelst mit Treue in allem, was du an den Brüdern tust und noch dazu an fremden;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (72, 1, 6, 'diese haben deine Liebe vor der ganzen Gemeinde rühmend anerkannt, und du wirst gut tun, wenn du ihnen so, wie es Gottes würdig ist, die Weiterreise ermöglichst;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (72, 1, 7, 'denn um (der Verkündigung) seines Namens willen sind sie ausgezogen und nehmen von den Heiden keine Unterstützung an.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (72, 1, 8, 'Wir sind deshalb verpflichtet, uns solcher (Männer) anzunehmen, damit wir uns als Mitarbeiter für die (Sache der) Wahrheit erweisen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (72, 1, 9, 'Ich habe ein Schreiben an die Gemeinde gerichtet, aber Diotrephes, der unter ihnen der Erste sein möchte, nimmt uns nicht an.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (72, 1, 10, 'Deshalb werde ich bei meinem Kommen auf seine Handlungsweise aufmerksam machen, wie er uns mit boshaften Äußerungen verdächtigt und, damit noch nicht zufrieden, für seine Person keinen Bruder gastlich bei sich aufnimmt und die, welche dazu bereit sind, daran hindert und sie aus der Gemeinde ausstößt.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (72, 1, 11, 'Geliebter, nimm dir nicht das Böse zum Vorbild, sondern das Gute: wer Gutes tut, ist aus Gott; wer Böses tut, hat Gott nicht gesehen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (72, 1, 12, 'Dem Demetrius ist von allen und von der Wahrheit selber ein rühmliches Zeugnis erteilt worden; auch wir erteilen es ihm, und du weißt, daß unser Zeugnis der Wahrheit entspricht.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (72, 1, 13, 'Ich hätte dir noch vieles zu schreiben, mag es aber nicht mit Tinte und Schreibrohr tun.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (72, 1, 14, 'Ich hoffe aber, dich recht bald zu sehen; dann wollen wir uns mündlich aussprechen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (72, 1, 15, 'Friede sei mit dir! Die Freunde lassen dich grüßen. Grüße die Freunde, jeden persönlich!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 1, 1, 'Nachdem Gott vorzeiten vielfältig und auf vielerlei Weise zu den Vätern geredet hat in den Propheten,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 1, 2, 'hat er am Ende dieser Tage zu uns geredet im Sohn, den er zum Erben von allem eingesetzt, durch den er auch die Weltzeiten geschaffen hat.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 1, 3, 'Dieser ist der Abglanz seiner Herrlichkeit und die Ausprägung seines Wesens und trägt das Weltall durch sein Allmachtswort; er hat sich, nachdem er die Reinigung von den Sünden vollbracht hat, zur Rechten der Erhabenheit in den Himmelshöhen gesetzt');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 1, 4, 'und ist dadurch um so viel größer geworden als die Engel, wie der Name, den er als Erbteil erhalten hat, den ihrigen überragt.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 1, 5, 'Denn zu welchem von den Engeln hätte Gott jemals gesagt: »Mein Sohn bist du: ich habe dich heute gezeugt«? Und ein andermal: »Ich will ihm Vater sein, und er soll für mich Sohn sein?«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 1, 6, 'Weiter sagt er von der Zeit, in welcher er den Erstgeborenen wiederum in die Menschenwelt einführen wird: »Alle Engel Gottes sollen vor ihm huldigend sich neigen.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 1, 7, 'Und in bezug auf die Engel heißt es zwar: »Er macht seine Engel zu Winden und seine Diener zur Feuerflamme«,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 1, 8, 'aber in bezug auf den Sohn: »Dein Thron, o Gott, steht fest in alle Ewigkeit, und der Stab der Geradheit ist der Stab deiner Königsherrschaft.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 1, 9, 'Du hast Gerechtigkeit geliebt und Gesetzwidrigkeit gehaßt; darum hat dich, o Gott, dein Gott mit Freudenöl gesalbt vor deinen Genossen.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 1, 10, 'Und ferner: »Du hast im Anfang, Herr, die Erde gegründet, und die Himmel sind deiner Hände Werk;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 1, 11, 'sie werden vergehen, du aber bleibst, und sie werden alle veralten wie ein Gewand;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 1, 12, 'wie einen Mantel wirst du sie zusammenrollen, und sie werden verwandelt werden; du aber bleibst derselbe, und deine Jahre werden kein Ende nehmen.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 1, 13, 'Zu welchem Engel hätte er ferner jemals gesagt: »Setze dich zu meiner Rechten, bis ich deine Feinde hinlege zum Schemel deiner Füße«?');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 1, 14, 'Sind sie nicht allesamt (nur) dienstbare Geister, die zu Dienstleistungen ausgesandt werden um derer willen, welche die Rettung ererben sollen?');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 2, 1, 'Darum müssen wir uns um so fester an das halten, was wir gehört haben, um seiner ja nicht verlustig zu gehen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 2, 2, 'Denn wenn schon das durch Vermittlung von Engeln verkündete Wort unverbrüchlich war und jede Übertretung und jeder Ungehorsam die gebührende Vergeltung empfing:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 2, 3, 'wie sollten wir da (der Strafe) entrinnen, wenn wir ein so hohes Heil unbeachtet lassen? Dieses hat ja seinen Anfang von der Verkündigung durch den Herrn (selbst) genommen und ist uns dann von den Ohrenzeugen zuverlässig bestätigt worden,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 2, 4, 'wobei auch Gott noch Zeugnis dafür abgelegt hat durch Zeichen und Wunder, durch mannigfache Krafttaten und Austeilungen des heiligen Geistes, nach seinem Ermessen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 2, 5, 'Denn nicht Engeln hat er die zukünftige Welt, von der wir hier reden, unterstellt,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 2, 6, 'vielmehr hat jemand an einer Stelle ausdrücklich bezeugt: »Was ist der Mensch, daß du seiner gedenkst, oder des Menschen Sohn, daß du ihn beachtest?');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 2, 7, 'Du hast ihn für eine kurze Zeit unter die Engel erniedrigt, ihn (dann aber) mit Herrlichkeit und Ehre gekrönt;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 2, 8, 'alles hast du ihm unter die Füße unterworfen.« Dadurch nämlich, daß er »ihm alles unterworfen hat«, hat er nichts von der Unterwerfung unter ihn ausgenommen. Bisher nehmen wir allerdings noch nicht wahr, daß ihm alles unterworfen ist;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 2, 9, 'wohl aber sehen wir den, der für eine kurze Zeit unter die Engel erniedrigt gewesen ist, nämlich Jesus, um seines Todesleidens willen mit Herrlichkeit und Ehre gekrönt; er sollte ja durch Gottes Gnade für jeden den Tod schmecken.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 2, 10, 'Denn es geziemte ihm, um dessen willen alles ist und durch den alles ist, nachdem er viele Söhne zur Herrlichkeit geführt hatte, den Urheber ihrer Rettung durch Leiden hindurch zur Vollendung zu bringen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 2, 11, 'Denn beide, sowohl der Heiligende als auch die, welche (von ihm) geheiligt werden, (kommen = stammen) alle von dem gleichen Vater her; aus diesem Grunde schämt er sich auch nicht, sie »Brüder« zu nennen,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 2, 12, 'indem er sagt: »Ich will deinen Namen meinen Brüdern verkündigen, inmitten der Gemeinde will ich dich preisen«;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 2, 13, 'und an einer andern Stelle: »Ich will mein Vertrauen auf ihn setzen«; und wiederum: »Siehe, hier bin ich und die Kinder, die Gott mir gegeben hat.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 2, 14, 'Weil nun die Kinder (leiblich) am Blut und Fleisch Anteil haben, hat auch er gleichermaßen Anteil an ihnen erhalten, um durch seinen Tod den zu vernichten, der die Macht des Todes hat, nämlich den Teufel,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 2, 15, 'und um alle die in Freiheit zu setzen, die durch Furcht vor dem Tode während ihres ganzen Lebens in Knechtschaft gehalten wurden.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 2, 16, 'Denn es sind doch sicherlich nicht Engel, deren er sich anzunehmen hat, sondern der Nachkommenschaft Abrahams nimmt er sich an;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 2, 17, 'und daher mußte er in allen Stücken seinen Brüdern gleich werden, damit er barmherzig würde und ein treuer Hoherpriester Gott gegenüber, um für die Sünden des Volkes Vergebung zu erwirken.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 2, 18, 'Denn eben deshalb, weil er selbst Versuchung erlitten hat, vermag er denen zu helfen, die versucht werden.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 3, 1, 'Darum, heilige Brüder, Genossen der himmlischen Berufung, richtet euer Augenmerk auf den Gottesboten und Hohenpriester unsers Bekenntnisses, auf Jesus,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 3, 2, 'der da »treu« war dem, der ihn geschaffen hat, wie auch Mose (treu gewesen ist) »in Gottes ganzem Hause«.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 3, 3, 'Denn einer größeren Herrlichkeit als Mose ist dieser würdig erachtet worden, in dem Maße, als der, welcher das Haus hergestellt hat, höher an Ehre steht als das Haus.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 3, 4, 'Denn jedes Haus wird von jemand hergestellt; der aber alles hergestellt hat, das ist Gott.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 3, 5, 'Und was Mose betrifft, so ist er zwar »in seinem ganzen Hause treu« gewesen, (aber doch nur) als »Diener«, um Zeugnis abzulegen für das, was als Offenbarung verkündigt werden sollte;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 3, 6, 'Christus dagegen (ist treu) als »Sohn« über »sein eigenes Haus«, und sein Haus sind wir, vorausgesetzt, daß wir an der freudigen Zuversicht und an der Hoffnung, deren wir uns rühmen, bis ans Ende unerschütterlich festhalten.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 3, 7, 'Deshalb (gilt uns) das Wort des heiligen Geistes: »Heute, wenn ihr seine Stimme hört,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 3, 8, 'verhärtet eure Herzen nicht, wie (es einst) bei der Erbitterung am Tage der Versuchung in der Wüste (geschah),');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 3, 9, 'wo eure Väter (mich) mit einer Erprobung versuchten; und doch haben sie meine Werke vierzig Jahre hindurch gesehen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 3, 10, 'Deshalb ward ich über dieses Geschlecht entrüstet und sprach: ›Allezeit gehen sie mit ihrem Herzen irre!‹ Sie aber erkannten meine Wege nicht,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 3, 11, 'so daß ich in meinem Zorn schwur: ›Sie sollen nimmermehr in meine Ruhe eingehen!‹«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 3, 12, 'Gebt acht, liebe Brüder, daß sich in keinem von euch ein böses Herz des Unglaubens im Abfall von dem lebendigen Gott zeige!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 3, 13, 'Ermahnt euch vielmehr selbst an jedem Tage, solange das »Heute« noch gilt, damit keiner von euch durch den Betrug der Sünde verhärtet werde.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 3, 14, 'Denn Genossen Christi sind wir geworden, wenn anders wir die anfängliche Glaubenszuversicht bis ans Ende unerschütterlich festhalten.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 3, 15, 'Wenn es heißt: »Heute, wenn ihr seine Stimme hört, verhärtet eure Herzen nicht, wie es bei der Erbitterung geschah« –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 3, 16, 'wer waren denn die Leute, die, obgleich sie (seine Verheißung) gehört hatten, dennoch sich erbittern ließen? Waren es nicht alle, die durch Moses Vermittlung aus Ägypten ausgezogen waren?');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 3, 17, 'Und wer waren die Leute, über die er vierzig Jahre lang entrüstet gewesen ist? Doch wohl die, welche gesündigt hatten und deren Glieder (dann) in der Wüste zerfallen sind.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 3, 18, 'Und wer waren die Leute, denen er zugeschworen hat, sie sollten nicht in seine Ruhe eingehen? Doch wohl die, welche sich ungehorsam bewiesen hatten.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 3, 19, 'So sehen wir denn, daß sie nicht haben hineingelangen können infolge (ihres) Unglaubens.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 4, 1, 'Da nun die Verheißung des Eingehens in seine Ruhe noch unerfüllt geblieben ist, so wollen wir ängstlich darauf bedacht sein, daß es sich bei keinem von euch herausstelle, er sei zurückgeblieben.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 4, 2, 'Denn die Heilsbotschaft ist an uns ebensogut ergangen wie an jene; aber jenen hat das Wort, das sie zu hören bekamen, nichts genützt, weil es bei den Hörern nicht mit dem Glauben vereinigt war.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 4, 3, 'Wir dagegen, die wir zum Glauben gekommen sind, gehen in die Ruhe ein, wie er gesagt hat: »So daß ich in meinem Zorn schwur: ›Sie sollen nimmermehr in meine Ruhe eingehen!‹« – wiewohl doch das Wirken (Gottes) seit der Vollendung der Weltschöpfung zum Abschluß gekommen war.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 4, 4, 'Er hat sich ja an einer Stelle über den siebten Tag so ausgesprochen: »Gott ruhte am siebten Tage von allen seinen Werken«;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 4, 5, 'an anderer Stelle dagegen heißt es: »Sie sollen nimmermehr in meine Ruhe eingehen!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 4, 6, 'Da also das Eingehen einiger in die Ruhe bestehen bleibt, andrerseits die, welche zuerst die beglückende Botschaft empfangen haben, infolge (ihres) Ungehorsams nicht hineingelangt sind,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 4, 7, 'so setzt (Gott) aufs neue einen Tag fest, ein »Heute«, indem er nach so langer Zeit durch David, wie schon vorhin gesagt worden ist, verkündigt: »Heute, wenn ihr seine Stimme hört, verhärtet eure Herzen nicht!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 4, 8, 'Denn wenn Josua sie wirklich in die Ruhe eingeführt hätte, so würde (Gott) nicht von einem anderen, späteren Tage reden.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 4, 9, 'Somit bleibt dem Volk Gottes eine Sabbatruhe noch vorbehalten;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 4, 10, 'denn wer in seine Ruhe eingegangen ist, der ist damit auch seinerseits zur Ruhe von seinen Werken gelangt, geradeso wie Gott von den seinigen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 4, 11, 'So wollen wir also eifrig darauf bedacht sein, in jene Ruhe einzugehen, damit keiner zu Fall kommt und dadurch das gleiche warnende Beispiel des Ungehorsams darbiete.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 4, 12, 'Denn lebendig ist das Wort Gottes und wirkungskräftig und schärfer als jedes zweischneidige Schwert: es dringt hindurch, bis es Seele und Geist, Gelenke und Mark scheidet, und ist ein Richter über die Regungen und Gedanken des Herzens;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 4, 13, 'und es gibt nichts Geschaffenes, das sich vor ihm verbergen könnte, nein, alles liegt entblößt und aufgedeckt vor den Augen dessen, dem wir Rechenschaft abzulegen haben.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 4, 14, 'Da wir nun einen großen Hohenpriester haben, der durch die Himmel hindurchgegangen ist, Jesus, den Sohn Gottes, so wollen wir am Bekenntnis (zu ihm) festhalten.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 4, 15, 'Wir haben ja (an ihm) nicht einen Hohenpriester, der nicht Mitgefühl mit unsern Schwachheiten haben könnte, sondern einen solchen, der in allen Stücken auf gleiche Weise (wie wir) versucht worden ist, nur ohne Sünde.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 4, 16, 'So wollen wir denn mit freudiger Zuversicht zum Thron der Gnade hinzutreten, um Barmherzigkeit zu empfangen und Gnade zu finden zu rechtzeitiger Hilfe.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 5, 1, 'Denn jeder aus der Zahl der Menschen genommene Hohepriester wird für Menschen zum Dienst vor Gott eingesetzt, um teils unblutige, teils blutige Opfer für Sünden darzubringen;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 5, 2, 'und er ist dabei wohl imstande, die Unwissenden und Irrenden billig zu beurteilen, weil er ja selbst mit Schwachheit behaftet ist.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 5, 3, 'Und um dieser willen muß er wie für das Volk, so auch für sich selbst Opfer der Sünden wegen darbringen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 5, 4, 'Und niemand kann sich selbst diese Würde zueignen, sondern er muß von Gott dazu berufen werden, ganz so wie es auch bei Aaron der Fall gewesen ist.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 5, 5, 'So hat denn auch Christus sich nicht selbst die hohe Würde des Hohenpriesters zugeeignet, sondern der (hat sie ihm verliehen), der zu ihm gesagt hat: »Mein Sohn bist du, ich selbst habe dich heute gezeugt«;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 5, 6, 'wie er auch an einer anderen Stelle sagt: »Du bist Priester in Ewigkeit nach der Ordnung Melchisedeks.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 5, 7, 'Er hat in den Tagen seines Fleisches Gebete und flehentliche Bitten mit lautem Schreien und Tränen vor den gebracht, der ihn vom Tode zu erretten vermochte, und hat auch Erhörung gefunden (und ist) aus seiner Angst (befreit worden)');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 5, 8, 'und hat trotz seiner Sohnesstellung an seinem Leiden den Gehorsam gelernt.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 5, 9, 'Nachdem er so zur Vollendung gelangt war, ist er für alle, die ihm gehorsam sind, der Urheber ewigen Heils geworden,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 5, 10, 'er, der von Gott mit der Bezeichnung »Hoherpriester nach der Ordnung Melchisedeks« angeredet worden ist.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 5, 11, 'Darüber hätten wir noch viel zu sagen, doch es ist schwer, euch das klarzumachen, weil eure Fassungskraft stumpf geworden ist.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 5, 12, 'Denn während ihr nach (der Länge) der Zeit schon Lehrer sein müßtet, bedürft ihr umgekehrt noch der Belehrung in den Anfangsgründen der göttlichen Offenbarungsworte und seid dahin gekommen, daß ihr Milch statt fester Nahrung nötig habt.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 5, 13, 'Denn jeder, der noch auf Milch angewiesen ist, versteht sich noch nicht auf das Wort der Gerechtigkeit; er ist eben noch ein unmündiges Kind.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 5, 14, 'Für Gereifte dagegen ist die feste Nahrung da, nämlich für die, welche infolge ihrer Gewöhnung geübte Sinne besitzen, so daß sie das Gute und das Schlechte zu unterscheiden vermögen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 6, 1, 'Darum wollen wir (jetzt) von den Anfangsgründen der Lehre Christi absehen und uns zur vollen Reife erheben, wollen nicht noch einmal den Grund legen mit Sinnesänderung, die sich von toten Werken abkehrt, und mit dem Glauben an Gott,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 6, 2, 'mit der Belehrung über Waschungen und Handauflegung, über Totenauferstehung und ewiges Gericht.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 6, 3, 'Ja, dies wollen wir tun, wenn anders Gott es gelingen läßt.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 6, 4, 'Denn es ist unmöglich, solche, die einmal die Erleuchtung empfangen und die himmlische Gabe geschmeckt haben und des heiligen Geistes teilhaftig geworden sind');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 6, 5, 'und das köstliche Gotteswort und die Kräfte der zukünftigen Welt gekostet haben');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 6, 6, 'und dann doch abgefallen sind, noch einmal zur Sinnesänderung zu erneuern, weil sie für ihre Person den Sohn Gottes von neuem kreuzigen und ihn der Beschimpfung preisgeben.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 6, 7, 'Denn wenn ein Acker den oftmals auf ihn fallenden Regen in sich eingesogen hat und denen, für die er bestellt wird, nützlichen Ertrag hervorbringt, so macht er sich den von Gott kommenden Segen zu eigen;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 6, 8, 'bringt er dagegen Dornen und Disteln hervor, so ist er unbrauchbar und geht dem Fluch entgegen, dessen Ende zum Feuerbrand führt.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 6, 9, 'Wir sind aber in bezug auf euch, Geliebte, wenn wir auch so reden, doch eines Besseren gewiß, nämlich dessen, was in engster Beziehung zur Errettung steht.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 6, 10, 'Denn Gott ist nicht ungerecht, daß er eure Arbeit und die Liebe vergäße, die ihr für seinen Namen dadurch an den Tag gelegt habt, daß ihr den Heiligen Dienste geleistet habt und auch jetzt noch leistet.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 6, 11, 'Wir wünschen aber innig, daß jeder einzelne von euch den gleichen Eifer an den Tag legen möge, um die Hoffnung bis ans Ende mit voller Gewißheit festzuhalten,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 6, 12, 'damit ihr nicht stumpf werdet, sondern dem Vorbild derer nachfolgt, die durch Glauben und standhaftes Ausharren die verheißenen Heilsgüter erben.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 6, 13, 'Nachdem Gott nämlich dem Abraham die Verheißung gegeben hatte, schwur er, weil er bei keinem Höheren schwören konnte, bei sich selbst');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 6, 14, 'mit den Worten: »Fürwahr, ich will dich reichlich segnen und dich überaus zahlreich machen!«,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 6, 15, 'und auf diese Weise harrte jener geduldig aus und erlangte das Verheißene.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 6, 16, 'Menschen schwören bekanntlich bei dem Höheren, und der Eid dient ihnen zur Bekräftigung, so daß alle Widerrede ausgeschlossen ist.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 6, 17, 'Aus diesem Grunde ist auch Gott, weil er den Erben seiner Verheißung das Unabänderliche seines Ratschlusses in besonderem Grade deutlich dartun wollte, als Bürge mit einem Eid eingetreten,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 6, 18, 'damit wir durch zwei unabänderliche Tatsachen, bei denen Gott unmöglich getäuscht haben kann, eine starke Ermutigung besäßen, wir, die wir unsere Zuflucht dazu genommen haben, die uns eröffnete Hoffnung zu ergreifen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 6, 19, 'In dieser besitzen wir ja gleichsam einen festen und zuverlässigen Anker für unsere Seele, der bis hinter den Vorhang (in das himmlische Heiligtum) hineinreicht,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 6, 20, 'wohin Jesus als Vorläufer uns zum Heil hineingegangen ist, insofern er »Hoherpriester nach der Ordnung Melchisedeks« geworden ist in Ewigkeit.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 7, 1, 'Dieser Melchisedek nämlich, König von Salem, Priester des höchsten Gottes, ging dem Abraham entgegen, als dieser von der Besiegung der Könige zurückkehrte, und segnete ihn;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 7, 2, 'dafür teilte Abraham ihm dann auch den Zehnten von der ganzen Beute zu. Zunächst ist er, wenn man seinen Namen deutet, ›König der Gerechtigkeit‹, sodann aber auch ›König von Salem‹, das bedeutet ›König des Friedens‹;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 7, 3, 'er hat (im biblischen Bericht) keinen Vater, keine Mutter, keine Ahnenreihe, weder einen Anfang seiner Tage noch ein Ende seines Lebens, gleicht vielmehr dem Sohne Gottes: er bleibt Priester für immer.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 7, 4, 'Beachtet nun wohl, wie groß dieser Mann dasteht, dem der Erzvater Abraham den Zehnten von den auserlesensten Beutestücken gegeben hat!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 7, 5, 'Wohl sind auch diejenigen Nachkommen Levis, die das Priestertum empfangen, berechtigt, den Zehnten von dem Volk in der vom Gesetz vorgeschriebenen Weise zu erheben, also von ihren Brüdern, obgleich doch auch diese leibliche Nachkommen Abrahams sind;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 7, 6, 'jener aber hat, wiewohl er seiner Abstammung nach mit ihnen in keiner Verbindung steht, von Abraham (selbst) den Zehnten erhoben und den, der im Besitz der Verheißungen war, gesegnet.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 7, 7, 'Nun ist es aber durchaus unbestreitbar, daß das Geringere von dem Höheren gesegnet wird.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 7, 8, 'Und hier sind es sterbliche Menschen, welche die Zehnten entgegennehmen, dort aber ist es einer, dem bezeugt wird, daß er lebt.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 7, 9, 'Weiter: in der Person Abrahams ist gewissermaßen auch vom Zehntenempfänger Levi der Zehnte erhoben worden;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 7, 10, 'denn er (Levi) befand sich (damals) noch in der Lende seines Stammvaters, als Melchisedek diesem entgegenging.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 7, 11, 'Freilich, wenn eine Vollendung durch das levitische Priestertum möglich wäre – auf diesem (Priestertum) beruht ja die ganze Gesetzgebung des Volkes –: welches Bedürfnis hätte dann noch vorgelegen, einen andersartigen Priester »nach der Ordnung Melchisedeks« einzusetzen und ihn nicht (einfach) »nach der Ordnung Aarons« zu benennen?');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 7, 12, 'Denn mit einer Änderung des Priestertums tritt mit Notwendigkeit auch eine Änderung des Gesetzes ein.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 7, 13, 'Der nämlich, auf den sich jener Ausspruch bezieht, hat ja doch einem anderen Stamme angehört, aus dem niemand (jemals) mit dem Altardienst zu tun gehabt hat.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 7, 14, 'Es ist ja doch allbekannt, daß unser Herr (Jesus) aus (dem Stamme) Juda hervorgegangen ist, und in bezug auf diesen Stamm hat Mose nichts verlauten lassen, was sich auf Priester bezieht.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 7, 15, 'Und vollends klar liegt die Sache dadurch, daß ein andersartiger Priester, der dem Melchisedek ähnlich ist, eingesetzt wird,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 7, 16, 'der es nicht nach der Bestimmung eines an leibliche Abstammung bindenden Gebotes geworden ist, sondern nach der Kraft unzerstörbaren Lebens.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 7, 17, 'Denn ihm wird bezeugt: »Du bist Priester in Ewigkeit nach der Ordnung Melchisedeks.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 7, 18, 'Damit tritt einerseits zwar die Aufhebung eines bis dahin gültigen Gebotes ein, weil es sich unwirksam und unbrauchbar erwiesen hatte –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 7, 19, 'das (mosaische) Gesetz hat ja auch wirklich keine Vollendung zustande gebracht –, andrerseits (tritt dadurch) aber auch die Herbeiführung einer besseren Hoffnung (ein), mittels derer wir Gott (wirklich) nahen können.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 7, 20, 'Und insofern (er) nicht ohne Eidesleistung (Priester geworden ist) – jene sind ja ohne Eidschwur Priester geworden,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 7, 21, 'dieser dagegen mit einem Eidschwur von seiten dessen, der zu ihm spricht: »Geschworen hat der Herr, und es wird ihn nicht gereuen: du bist Priester in Ewigkeit« –:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 7, 22, 'dementsprechend ist Jesus um so mehr der Bürge eines besseren Bundes geworden.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 7, 23, 'Außerdem sind dort Priester als Vielheit vorhanden gewesen, weil sie durch den Tod daran gehindert wurden, (im Amt) zu verbleiben;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 7, 24, 'hier aber ist es ein solcher, der, weil er »in Ewigkeit« bleibt, ein nie wechselndes Priestertum im Besitz hat.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 7, 25, 'Daher vermag er auch denen, die durch seine Vermittlung zu Gott hinzutreten, vollkommene Rettung zu schaffen: er lebt ja immerdar, um fürbittend für sie (vor Gott) einzutreten.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 7, 26, 'Denn einen solchen Hohenpriester mußten wir auch haben, der da heilig, schuldlos, unbefleckt ist, von den Sündern geschieden und über die Himmel hoch erhöht;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 7, 27, 'der nicht wie die (menschlichen) Hohenpriester Tag für Tag nötig hat, zunächst für seine eigenen Sünden Opfer darzubringen, danach für die des Volkes; denn letzteres hat er ein für allemal dadurch geleistet, daß er sich selbst (zum Opfer) dargebracht hat.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 7, 28, 'Denn das (mosaische) Gesetz bestellt zu Hohenpriestern Menschen, die mit Schwachheit behaftet sind; das Wort des Eidschwurs dagegen, der erst nach dem Gesetz erfolgt ist, setzt einen Sohn ein, der für die Ewigkeit vollendet ist.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 8, 1, 'Die Hauptsache aber bei der vorliegenden Darlegung ist folgendes: Einen solchen Hohenpriester haben wir, der sich im Himmel zur Rechten des Thrones der göttlichen Erhabenheit gesetzt hat,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 8, 2, 'und zwar als Verwalter des Heiligtums, nämlich des wahren Zeltes, das der Herr, nicht ein Mensch errichtet hat.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 8, 3, 'Denn jeder Hohepriester wird zu dem Zweck bestellt, unblutige und blutige Opfer darzubringen; daher muß auch dieser etwas darzubringen haben.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 8, 4, 'Befände er sich nun auf der Erde, so würde er nicht einmal Priester sein, weil hier ja bereits Priester vorhanden sind, welche die Gaben nach dem (mosaischen) Gesetz darbringen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 8, 5, 'Diese versehen freilich den Dienst nur an einer Nachbildung und einem Schattenbild der himmlischen Dinge entsprechend der göttlichen Weisung, die Mose erhielt, als er das Zelt herstellen sollte; denn »Gib wohl acht«, sagt der Herr zu ihm, »daß du alles nach dem Vorbild anfertigst, das dir auf dem Berge gezeigt worden ist«.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 8, 6, 'Nun aber hat er einen um so vorzüglicheren Priesterdienst erlangt, als er auch Mittler eines besseren Bundes ist, der auf der Grundlage besserer Verheißungen festgesetzt worden ist.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 8, 7, 'Wenn nämlich jener erste (Bund) tadellos gewesen wäre, so würde nicht die Möglichkeit, einen zweiten (Bund) zu schließen, gesucht werden.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 8, 8, 'Denn einen Tadel spricht (Gott) gegen sie (die Israeliten) aus mit den Worten: »Wisset wohl: es kommen Tage« – so lautet der Ausspruch des Herrn –, »da will ich mit dem Hause Israel und mit dem Hause Juda einen neuen Bund aufrichten,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 8, 9, 'nicht einen solchen Bund, wie ich ihn mit ihren Vätern damals geschlossen habe, als ich sie bei der Hand nahm, um sie aus dem Lande Ägypten wegzuführen; denn sie sind meinem Bunde nicht treu geblieben, und auch ich habe mich nicht (mehr) um sie gekümmert« – so lautet der Ausspruch des Herrn –.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 8, 10, '»Nein, darin soll der Bund bestehen, den ich mit dem Hause Israel nach jenen Tagen schließen werde« – so lautet der Ausspruch des Herrn –: »Ich will meine Gesetze in ihren Sinn hineinlegen und sie ihnen ins Herz schreiben und will dann ihr Gott sein, und sie sollen mein Volk sein.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 8, 11, 'Dann braucht niemand mehr seinem Mitbürger und niemand seinem Bruder Belehrung zu erteilen und ihm vorzuhalten: ›Lerne den Herrn kennen!‹ Denn sie werden mich allesamt kennen vom Kleinsten bis zum Größten unter ihnen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 8, 12, 'Denn ihren Übertretungen gegenüber werde ich Nachsicht üben und ihrer Sünden nicht mehr gedenken.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 8, 13, 'Indem er hier von einem »neuen« (Bunde) redet, hat er den ersten für veraltet erklärt; was aber veraltet ist und sich überlebt hat, das geht dem Untergang entgegen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 9, 1, 'Allerdings hatte auch der erste (Bund) Satzungen für den Gottesdienst und (hatte) auch das weltliche Heiligtum.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 9, 2, 'Es wurde nämlich ein Zelt hergestellt, dessen Vorderraum, in welchem sich der Leuchter sowie der Tisch mit den aufgelegten Schaubroten befinden, das sogenannte Heilige ist.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 9, 3, 'Hinter dem zweiten Vorhang aber liegt der Teil des Zeltes, der das Allerheiligste genannt wird,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 9, 4, 'mit dem goldenen Räucheraltar und der ganz mit Gold überzogenen Bundeslade, in welcher sich der goldene Krug mit dem Manna sowie der Stab Aarons, der Blüten getrieben hatte, und die Bundestafeln befinden;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 9, 5, 'oben über ihr aber stehen die (beiden) Cherube der Herrlichkeit, welche (mit ihren Flügeln) die Deckplatte überschatten – doch hierüber soll jetzt nicht im einzelnen geredet werden.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 9, 6, 'Seitdem nun dies so eingerichtet worden ist, betreten die Priester, welche die gottesdienstlichen Handlungen zu verrichten haben, den Vorderraum des Zeltes jederzeit;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 9, 7, 'in den zweiten Raum dagegen darf nur der Hohepriester einmal im Jahr eintreten, (und zwar) nicht ohne Blut, das er für sich selbst und für die Verfehlungen des Volkes darbringt.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 9, 8, 'Dadurch weist der heilige Geist darauf hin, daß der Weg zum wahrhaften Heiligtum noch nicht geoffenbart ist, solange das vordere Zelt noch Bestand hat.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 9, 9, 'So ist denn dieser Vorraum ein Sinnbild auf die Gegenwart, insofern in ihm unblutige und blutige Opfer dargebracht werden, die doch nicht imstande sind, den, der (Gott mit ihnen) dient, in seinem Gewissen ans Ziel zu bringen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 9, 10, 'Sie sind ja neben den (Verordnungen über) Speisen, Getränke und mancherlei Waschungen ebenfalls nur als fleischliche Satzungen bis zu der Zeit auferlegt, wo etwas Besseres in Geltung tritt.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 9, 11, 'Christus dagegen ist, indem er als Hoherpriester der zukünftigen Güter kam, durch das größere und vollkommenere Zelt, das nicht mit Händen gemacht ist, d.h. nicht dieser erschaffenen Welt angehört,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 9, 12, 'auch nicht mittels des Blutes von Böcken und Kälbern, sondern mittels seines eigenen Blutes ein für allemal in das (himmlische) Heiligtum eingetreten und hat eine ewiggültige Erlösung ausfindig gemacht.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 9, 13, 'Denn wenn schon das Blut von Böcken und Stieren und die Asche einer Kuh, mit der man die Verunreinigten besprengt, Heiligung zu leiblicher Reinheit bewirkt,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 9, 14, 'um wieviel mehr wird das Blut Christi, der kraft ewigen Geistes sich selbst als ein fehlerloses Opfer Gott dargebracht hat, unser Gewissen von toten Werken reinigen, damit wir dem lebendigen Gott dienen!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 9, 15, 'Und aus diesem Grunde ist er auch der Mittler eines neuen Bundes, damit aufgrund eines Todes, der zum Erlaß der während der Dauer des ersten Bundes begangenen Übertretungen erfolgt ist, die Berufenen das verheißene Gut des ewigen Erbes empfangen sollten.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 9, 16, 'Denn wo eine letztwillige Stiftung vorliegt, da muß unbedingt der Tod dessen, der die Stiftung errichtet hat, (als eingetreten) nachgewiesen werden;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 9, 17, 'eine Stiftung wird ja erst nach Eintritt des Todes rechtskräftig, während sie durchaus keine Kraft besitzt, solange der Stifter noch lebt.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 9, 18, 'Daher ist ja auch der erste Bund nicht ohne Blut eingeweiht worden.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 9, 19, 'Nachdem nämlich Mose jedes Gebot, wie das Gesetz es vorschrieb, dem ganzen Volke vorgetragen hatte, nahm er das Blut der Kälber und der Böcke nebst Wasser und Scharlachwolle und einem Büschel Ysop und besprengte damit wie das Buch selbst, so auch das gesamte Volk,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 9, 20, 'indem er dabei ausrief: »Dies ist das Blut des Bundes, den Gott für euch angeordnet hat!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 9, 21, 'Aber auch das Zelt und sämtliche gottesdienstlichen Geräte besprengte er in gleicher Weise mit dem Blute;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 9, 22, 'überhaupt wird beinahe alles nach dem Gesetz mit Blut gereinigt, und ohne Blutvergießen erfolgt keine Vergebung.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 9, 23, 'Es mußten also zwar die Nachbildungen der im Himmel (befindlichen Heiligtümer) durch diese Mittel gereinigt werden, aber für die himmlischen Heiligtümer selbst muß es bessere Opfer geben, als jene es sind.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 9, 24, 'Denn Christus ist nicht in ein von Menschenhänden hergestelltes Heiligtum eingegangen, das nur eine Nachbildung des wahren Heiligtums wäre, sondern in den Himmel selbst, um jetzt uns zum Heil (persönlich) vor dem Angesicht Gottes zu erscheinen;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 9, 25, 'auch hat er das nicht in der Absicht getan, sich oftmals als Opfer darzubringen, wie der (irdische) Hohepriester alljährlich mit fremdem Blut in das Heiligtum hineingeht;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 9, 26, 'sonst hätte er ja seit Erschaffung der Welt oftmals leiden müssen. So aber ist er nur einmal am Ende der Weltzeiten offenbar geworden, um die Sünde durch sein Opfer aufzuheben.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 9, 27, 'Und so gewiß es den Menschen bevorsteht, einmal zu sterben, danach aber das Gericht,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 9, 28, 'ebenso wird auch Christus, nachdem er ein einziges Mal als Opfer dargebracht worden ist, um die Sünden vieler wegzunehmen, zum zweitenmal ohne (Beziehung zur) Sünde denen, die auf ihn warten, zum Heil erscheinen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 10, 1, 'Denn weil das (mosaische) Gesetz nur das schattenhafte Abbild der zukünftigen Heilsgüter enthält, nicht aber die Gestalt der Dinge selbst, so ist es nimmermehr imstande, alljährlich durch dieselben Opfer, die man immer wieder darbringt, die an den Opfern Teilnehmenden ans Ziel zu bringen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 10, 2, 'Würde man sonst nicht mit ihrer Darbringung aufgehört haben, weil doch die Teilnehmer am Gottesdienst keinerlei Schuldbewußtsein mehr gehabt hätten, wenn sie ein für allemal gereinigt gewesen wären?');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 10, 3, 'Statt dessen tritt durch diese Opfer alljährlich eine Erinnerung an (die) Sünden ein,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 10, 4, 'denn Blut von Stieren und Böcken kann unmöglich Sünden wegschaffen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 10, 5, 'Daher sagt er auch bei seinem Eintritt in die Welt: »Schlachtopfer und Speisopfer hast du nicht gewollt, wohl aber hast du mir einen Leib bereitet;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 10, 6, 'an Brandopfern und Sündopfern hast du kein Wohlgefallen gehabt.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 10, 7, 'Da sprach ich: ›Siehe, ich komme – in der Buchrolle steht über mich geschrieben –, um deinen Willen, o Gott, zu tun.‹«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 10, 8, 'Während er zu Anfang sagt: »Schlachtopfer und Speisopfer, Brandopfer und Sündopfer hast du nicht gewollt und kein Wohlgefallen an ihnen gehabt« – obgleich diese Opfer doch dem Gesetz entsprechend dargebracht werden –,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 10, 9, 'fährt er danach fort: »Siehe, ich komme, um deinen Willen zu tun«: er hebt (also) das Erste auf, um das Zweite dafür als gültig hinzustellen;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 10, 10, 'und auf Grund dieses Willens (Gottes) sind wir durch die Darbringung des Leibes Jesu Christi ein für allemal geheiligt.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 10, 11, 'Und jeder Priester zwar steht Tag für Tag da, indem er seinen Dienst verrichtet und immer wieder dieselben Opfer darbringt, die doch nimmermehr imstande sind, Sünden wegzuschaffen;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 10, 12, 'dieser dagegen hat nur ein einziges Opfer für (die) Sünden dargebracht und sich dann für immer zur Rechten Gottes gesetzt;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 10, 13, 'hinfort wartet er, bis seine Feinde hingelegt sein werden zum Schemel seiner Füße.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 10, 14, 'Denn durch eine einzige Darbringung hat er die, welche sich (von ihm) heiligen lassen (wollen), für immer ans Ziel gebracht.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 10, 15, 'Dafür gibt uns aber auch der heilige Geist sein Zeugnis; denn nach den Worten:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 10, 16, '»Dies ist der Bund, den ich nach jenen Tagen mit ihnen schließen werde«, fährt der Herr fort: »Ich will meine Gesetze in ihre Herzen hineinlegen und sie ihnen in den Sinn schreiben«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 10, 17, 'und »ihrer Sünden und ihrer Gesetzlosigkeiten will ich nicht mehr gedenken«.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 10, 18, 'Wo diese aber Vergebung gefunden haben, da ist keine Darbringung für Sünde mehr erforderlich.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 10, 19, 'Da wir also, liebe Brüder, die freudige Zuversicht haben, durch das Blut Jesu in das (himmlische) Heiligtum einzugehen –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 10, 20, 'das ist der neue, lebendige Weg, den er uns durch den Vorhang hindurch, das heißt durch sein Fleisch, eingeweiht hat –,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 10, 21, 'und da wir einen großen Priester haben, der über das Haus Gottes gesetzt ist,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 10, 22, 'so laßt uns mit aufrichtigem Herzen in voller Glaubensgewißheit hinzutreten, nachdem wir uns durch Besprengung der Herzen vom bösen Gewissen befreit und unsern Leib mit reinem Wasser gewaschen haben.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 10, 23, 'Laßt uns am Bekenntnis der Hoffnung unerschütterlich festhalten; denn treu ist der, welcher die Verheißung gegeben hat.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 10, 24, 'Und laßt uns auch aufeinander achtgeben, um uns gegenseitig zur Liebe und zu guten Werken anzuregen,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 10, 25, 'indem wir unsere Zusammenkünfte nicht versäumen, wie das bei etlichen Gewohnheit ist, sondern uns gegenseitig ermuntern, und zwar um so mehr, als ihr den Tag (der Wiederkunft Jesu) schon nahen seht.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 10, 26, 'Denn wenn wir vorsätzlich sündigen, nachdem wir die Erkenntnis der Wahrheit erlangt haben, so bleibt uns fortan kein Opfer für die Sünden mehr übrig,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 10, 27, 'sondern nur ein angstvolles Warten auf das Gericht und die Gier des Feuers, das die Widerspenstigen verzehren wird.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 10, 28, 'Wenn jemand das mosaische Gesetz verworfen hat, so muß er ohne Erbarmen auf (die Aussage von) zwei oder drei Zeugen hin sterben:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 10, 29, 'eine wieviel härtere Strafe, denkt doch, wird dem zuerkannt werden, der den Sohn Gottes mit Füßen getreten und das Blut des Bundes, durch das er geheiligt worden ist, für wertlos geachtet und mit dem Geist der Gnade Spott getrieben hat!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 10, 30, 'Wir kennen ja den, der gesagt hat: »Mein ist die Rache, ich will vergelten«, und an einer anderen Stelle: »Der Herr wird sein Volk richten.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 10, 31, 'Schrecklich ist es, dem lebendigen Gott in die Hände zu fallen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 10, 32, 'Denkt aber an die früheren Tage zurück, in denen ihr nach empfangener Erleuchtung einen harten Leidenskampf geduldig bestanden habt,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 10, 33, 'indem ihr teils selbst durch Beschimpfungen und Drangsale zum öffentlichen Schauspiel gemacht wurdet, teils an den Geschicken derer teilnehmen mußtet, die in solche Lagen versetzt waren.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 10, 34, 'Ihr habt ja doch mit den Gefangenen mitgelitten und den Raub eurer Habe mit Freuden hingenommen in der Erkenntnis, daß ihr selbst einen wertvolleren und bleibenden Besitz habt.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 10, 35, 'Werft also eure freudige Zuversicht nicht weg: sie bringt ja eine hohe Lohnvergeltung mit sich!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 10, 36, 'Denn standhaftes Ausharren tut euch not, damit ihr nach Erfüllung des göttlichen Willens das verheißene Gut erlangt.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 10, 37, 'Denn es währt »nur noch eine kleine, ganz kurze Zeit, dann wird der kommen, der kommen soll, und nicht auf sich warten lassen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 10, 38, 'Mein Gerechter aber wird aus Glauben das Leben haben«, und »wenn er kleinmütig zurückweicht, hat mein Herz kein Wohlgefallen an ihm«.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 10, 39, 'Wir aber haben nichts mit dem Zurückweichen zu tun, das zum Verderben führt, sondern (halten es) mit dem Glauben, der das Leben gewinnt.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 11, 1, 'Es ist aber der Glaube ein zuversichtliches Vertrauen auf das, was man hofft, ein festes Überzeugtsein von Dingen, die man (mit Augen) nicht sieht.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 11, 2, 'Im Besitz solchen Glaubens haben nämlich die Altvordern (das ehrende) Zeugnis (von Gott) erlangt.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 11, 3, 'Durch Glauben erkennen wir, daß die Welt durch Gottes Wort ins Dasein gerufen worden ist; es sollte eben das jetzt Sichtbare nicht aus dem sinnlich Wahrnehmbaren entstanden sein.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 11, 4, 'Durch Glauben hat Abel Gott ein wertvolleres Opfer als Kain dargebracht und durch ihn das Zeugnis erhalten, er sei ein Gerechter, indem Gott (selbst) Zeugnis für seine Opfergaben ablegte; und durch ihn redet er auch jetzt noch nach seinem Tode. –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 11, 5, 'Durch Glauben wurde Henoch entrückt, damit er den Tod nicht sähe, und »er war (auf Erden) nicht mehr zu finden, weil Gott ihn entrückt hatte«; denn vor seiner Entrückung ist ihm bezeugt worden, daß er Gottes Wohlgefallen besessen habe.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 11, 6, 'Ohne Glauben aber kann man (Gott) unmöglich wohlgefallen; denn wer sich Gott nahen will, muß glauben, daß es einen Gott gibt und daß er denen, die ihn suchen, ihren Lohn zukommen läßt. –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 11, 7, 'Durch Glauben hat Noah, als er die (göttliche) Weisung erhalten hatte, in Besorgnis um die Dinge, die noch nicht sichtbar vor Augen lagen, eine Arche zur Rettung seiner Familie gebaut; durch solchen Glauben hat er der Welt das Urteil gesprochen und ist ein Erbe der glaubensgemäßen Gerechtigkeit geworden.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 11, 8, 'Durch Glauben leistete Abraham dem Ruf Folge, der ihn in ein Land ziehen hieß, das er zum Erbbesitz empfangen sollte: er wanderte aus, ohne zu wissen wohin.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 11, 9, 'Durch Glauben siedelte er sich als Beisasse in dem verheißenen Lande wie in der Fremde an und wohnte in Zelten samt Isaak und Jakob, den Miterben der gleichen Verheißung;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 11, 10, 'denn er wartete auf die Stadt, welche die festen Grundmauern hat, deren Erbauer und Werkmeister Gott ist.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 11, 11, 'Durch Glauben empfing ebenso auch Sara die Kraft, trotz ihres hohen Alters Mutter zu werden, weil sie den für zuverlässig ansah, der ihr die Verheißung gegeben hatte.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 11, 12, 'Daher sind auch von einem einzigen und zwar einem bereits erstorbenen Manne Nachkommen entsprossen so zahlreich wie die Sterne des Himmels und wie der Sand am Gestade des Meeres, den niemand zählen kann. –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 11, 13, 'Im Glauben sind diese alle gestorben, ohne die (Erfüllung der) Verheißungen erlangt zu haben; nur von ferne haben sie diese gesehen und freudig begrüßt und bekannt, daß sie nur Fremdlinge und Gäste auf der Erde seien;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 11, 14, 'denn wer ein solches Bekenntnis ablegt, gibt dadurch zu erkennen, daß er ein Vaterland sucht.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 11, 15, 'Hätten sie nun dabei an jenes (Vaterland) gedacht, aus dem sie ausgewandert waren, so hätten sie Zeit zur Rückkehr dorthin gehabt;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 11, 16, 'so aber tragen sie nach einem besseren (Vaterland) Verlangen, nämlich nach dem himmlischen. Daher schämt sich auch Gott ihrer nicht, ihr Gott genannt zu werden; er hat ihnen ja (bereits) eine Stadt (als Wohnung) bereitet. –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 11, 17, 'Durch Glauben hat Abraham, als er versucht wurde, den Isaak zur Opferung dargebracht; ja er wollte seinen einzigen (Sohn) opfern, obgleich er die Verheißungen empfangen hatte');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 11, 18, 'und ihm zugesagt worden war: »Nach Isaak soll dir Nachkommenschaft genannt werden«;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 11, 19, 'er bedachte eben, daß Gott die Macht habe, auch aus den Toten zu erwecken; daher hat er ihn auch als ein Gleichnis zurückerhalten. –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 11, 20, 'Durch Glauben segnete Isaak auch den Jakob und Esau im Hinblick auf zukünftige Geschicke. –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 11, 21, 'Durch Glauben segnete Jakob bei seinem Sterben jeden der (beiden) Söhne Josephs und betete zu Gott, auf die Spitze seines Stabes gelehnt. –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 11, 22, 'Durch Glauben gedachte Joseph bei seinem Lebensende des (einstigen) Auszuges der Israeliten und traf Anordnungen in betreff seiner Gebeine.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 11, 23, 'Durch Glauben geschah es, daß Mose nach seiner Geburt drei Monate lang von seinen Eltern verborgen gehalten wurde, weil sie die Schönheit des Knäbleins sahen, und daß sie sich vor dem Befehl des Königs nicht fürchteten.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 11, 24, 'Durch Glauben verschmähte es Mose, als er herangewachsen war, ein Sohn der Tochter des Pharaos zu heißen;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 11, 25, 'lieber wollte er mit dem Volke Gottes Drangsale erleiden, als einen vorübergehenden Genuß von der Sünde haben:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 11, 26, 'er achtete die Schmach Christi für einen größeren Reichtum als die Schätze Ägyptens; denn er hatte die (himmlische) Belohnung im Auge.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 11, 27, 'Durch Glauben verließ er Ägypten, ohne Furcht vor dem Zorn des Königs; denn er wurde stark, als ob er den Unsichtbaren sähe.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 11, 28, 'Durch Glauben hat er das Passah und die Besprengung (der Türpfosten) mit dem Blute angeordnet, damit der Würgengel die Erstgeburten der Israeliten nicht antaste.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 11, 29, 'Durch Glauben sind sie durch das Rote Meer gezogen wie über trockenes Land, während die Ägypter ertranken, als sie denselben Versuch machten. –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 11, 30, 'Durch Glauben geschah es, daß die Mauern Jerichos einstürzten, nachdem man sieben Tage lang um sie herumgezogen war. –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 11, 31, 'Durch Glauben kam die Dirne Rahab nicht zugleich mit den Ungehorsamen ums Leben, weil sie die Kundschafter friedlich bei sich aufgenommen hatte.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 11, 32, 'Und was soll ich noch weiter sagen? Die Zeit würde mir ja fehlen, wenn ich von Gideon und Barak, von Simson und Jephtha, von David und Samuel und den Propheten reden wollte:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 11, 33, 'Durch Glauben haben diese (Männer) Königreiche überwältigt, (vergeltende) Gerechtigkeit geübt, (Erfüllung von) Verheißungen erlangt, Löwenrachen verschlossen,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 11, 34, 'die Kraft des Feuers ausgelöscht; sie sind der Schärfe des Schwertes entronnen, aus Kraftlosigkeit wieder erstarkt, im Kampfe Helden geworden, haben Heere fremder Völker in die Flucht geschlagen;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 11, 35, 'Frauen haben ihre Toten durch Auferweckung zurückerhalten. Andere haben sich martern lassen und die Befreiung zurückgewiesen, um einer desto herrlicheren Auferstehung teilhaftig zu werden.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 11, 36, 'Wieder andere haben Verhöhnung und Geißelung, dazu noch Ketten und Kerker über sich ergehen lassen;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 11, 37, 'sie sind gesteinigt, gefoltert, zersägt, mit dem Henkerbeil hingerichtet worden, sind in Schaffellen, in Ziegenhäuten unter Entbehrungen, Drangsalen und Mißhandlungen umhergezogen;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 11, 38, 'sie, deren die Welt nicht wert war, haben in Einöden und Gebirgen, in Höhlen und Erdklüften umherirren müssen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 11, 39, 'Und diese alle, denen doch durch den Glauben ihr Zeugnis zuteil geworden ist, haben die (Erfüllung der) Verheißung nicht erlangt,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 11, 40, 'weil Gott für uns etwas Besseres zuvor ersehen hatte: sie sollten nicht ohne uns zur (himmlischen) Vollendung gelangen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 12, 1, 'So wollen denn auch wir, da wir uns von einer solchen Wolke von Zeugen umgeben sehen, alles, was uns beschwert, und (besonders) die uns so leicht umstrickende Sünde ablegen und mit standhafter Ausdauer in dem uns obliegenden Wettkampfe laufen,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 12, 2, 'indem wir dabei hinblicken auf Jesus, den Anfänger und Vollender des Glaubens, der um den Preis der Freude, die ihn (als Siegeslohn) erwartete, den Kreuzestod erduldet und die Schmach für nichts geachtet, dann sich aber zur Rechten des Thrones Gottes gesetzt hat.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 12, 3, 'Ja, denkt an ihn, der ein derartiges Widersprechen von den Sündern gegen sich geduldig ertragen hat, damit ihr (im Lauf) nicht ermattet und euren Mut nicht sinken laßt!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 12, 4, 'Denn bis jetzt habt ihr im Kampf gegen die Sünde noch nicht bis aufs Blut Widerstand geleistet');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 12, 5, 'und habt das Mahnwort vergessen, das zu euch wie zu Söhnen spricht: »Mein Sohn, achte die Züchtigung des Herrn nicht gering und verzage nicht, wenn du von ihm zurechtgewiesen wirst;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 12, 6, 'denn wen der Herr lieb hat, den züchtigt er und geißelt jeden Sohn, den er als den seinigen annimmt.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 12, 7, 'Haltet standhaft aus, um euch erziehen zu lassen! Gott verfährt mit euch wie mit Söhnen; denn wo wäre wohl ein Sohn, den sein Vater nicht züchtigt?');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 12, 8, 'Wenn ihr dagegen ohne Züchtigung bliebet, die doch allen (anderen Söhnen) zuteil geworden ist, so wäret ihr ja unechte Kinder und keine Söhne.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 12, 9, 'Ferner (bedenkt): wir haben doch unter der Zucht unserer leiblichen Väter gestanden und ihnen Ehrerbietung erwiesen; wollten wir uns da nicht viel eher dem Vater der Geister unterwerfen und dadurch zum Leben gelangen?');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 12, 10, 'Denn jene haben doch nur für kurze Zeit nach ihrem Ermessen Zucht (an uns) geübt, er aber zu unserm wahren Besten, damit wir seiner Heiligkeit teilhaftig würden.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 12, 11, 'Jede Züchtigung scheint uns freilich für den Augenblick nicht erfreulich, sondern betrübend zu sein; hinterher aber läßt sie denen, die sich durch sie haben üben lassen, die friedvolle Frucht der Gerechtigkeit erwachsen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 12, 12, 'Darum »richtet die erschlafften Hände und die ermatteten Knie wieder auf«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 12, 13, 'und »stellt für eure Füße gerade Bahnen her«, damit das Lahme nicht ganz vom rechten Wege abkomme, sondern vielmehr geheilt werde.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 12, 14, 'Trachtet eifrig nach dem Frieden mit jedermann und nach der Heiligung, ohne die niemand den Herrn schauen wird;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 12, 15, 'und gebt acht darauf, daß niemand hinter der Gnade Gottes zurückbleibe, daß keine »Wurzel voll Bitterkeit« aufwachse und Unheil anrichte und gar viele durch sie befleckt werden;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 12, 16, 'daß niemand ein ehebrecherischer oder verworfener Mensch sei wie Esau, der für eine einzige Mahlzeit sein Erstgeburtsrecht verkauft hat.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 12, 17, 'Ihr wißt ja, daß er auch später, als er den Segen zum Erbe erlangen wollte, abgewiesen wurde; denn er fand keinen Raum zu einer Gesinnungsumkehr, obgleich er sie unter Tränen suchte.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 12, 18, 'Denn ihr seid nicht zu einem mit Händen greifbaren und im Feuer lodernden Berge herangetreten, nicht zu Wolkendunkel, Finsternis und Gewittersturm,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 12, 19, 'nicht zu Posaunenschall und Donnerworten, bei denen die Zuhörer die Bitte aussprachen, es möchte nicht weiter zu ihnen geredet werden –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 12, 20, 'sie konnten nämlich die Verordnung nicht ertragen: »Selbst ein Tier, das den Berg berührt, soll gesteinigt werden!« –;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 12, 21, 'ja, so furchtbar war die Erscheinung, daß (sogar) Mose erklärte: »Ich bin voller Furcht und Zittern!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 12, 22, 'Nein, ihr seid zu dem Berge Zion und zur Stadt des lebendigen Gottes, dem himmlischen Jerusalem, herangetreten und zu vielen Tausenden von Engeln, zu einer Festversammlung');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 12, 23, 'und zur Gemeinde der im Himmel aufgeschriebenen Erstgeborenen und zu Gott, dem Richter über alle, und zu den Geistern der vollendeten Gerechten,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 12, 24, 'und zu Jesus, dem Mittler des neuen Bundes, und zum Blute der Besprengung, das Besseres redet als (das Blut) Abels.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 12, 25, 'Hütet euch, daß ihr den nicht ablehnt, der (zu euch) redet! Denn wenn jene nicht ungestraft geblieben sind, die den ablehnten, der sich ihnen auf Erden kundgab: wieviel weniger werden wir dann davonkommen, wenn wir uns von dem abwenden, der vom Himmel her (zu uns redet)!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 12, 26, 'Seine Stimme hat damals die Erde erschüttert; jetzt aber hat er diese Verheißung gegeben: »Noch einmal werde ich nicht nur die Erde, sondern auch den Himmel erbeben machen.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 12, 27, 'Das Wort »noch einmal« weist auf die Umwandlung dessen hin, das erschüttert wird, weil es etwas Geschaffenes ist; es soll eben etwas Bleibendes entstehen, das nicht erschüttert werden kann.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 12, 28, 'Darum wollen wir, weil wir ein unerschütterliches Reich empfangen sollen, dankbar dafür sein; denn dadurch dienen wir Gott so, wie es ihm wohlgefällig ist, mit frommer Scheu und Furcht;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 12, 29, 'denn auch unser Gott ist ein verzehrendes Feuer.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 13, 1, 'Bleibt fest in der Bruderliebe.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 13, 2, 'Vergeßt die Gastfreundschaft nicht; denn durch diese haben einige, ohne es zu wissen, Engel beherbergt.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 13, 3, 'Gedenkt der Gefangenen, als ob ihr mitgefangen wäret, der Mißhandelten als solche, die gleichfalls noch im Leibe sind.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 13, 4, 'Die Ehe werde von allen in Ehren gehalten und das Ehebett bleibe unbefleckt; denn Unzüchtige und Ehebrecher wird Gott richten.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 13, 5, 'Euer Sinn sei frei von Geldgier; begnügt euch mit dem, was euch gerade zu Gebote steht, denn er selbst hat gesagt: »Ich will dir nimmermehr meine Hilfe versagen und dich nicht verlassen«;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 13, 6, 'daher dürfen wir auch zuversichtlich sagen: »Der Herr ist meine Hilfe, ich will mich nicht fürchten: was können Menschen mir antun?«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 13, 7, 'Bleibt eurer Führer eingedenk, die euch das Wort Gottes verkündigt haben! Betrachtet immer wieder den Ausgang ihres Wandels und nehmt ihren Glauben zum Vorbild!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 13, 8, 'Jesus Christus ist gestern und heute derselbe und (ist’s auch = bleibt’s auch) in Ewigkeit! –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 13, 9, 'Laßt euch nicht durch mancherlei und fremdartige Lehren fortreißen! Denn es ist gut, daß das Herz durch Gnade gefestigt wird, nicht durch Speisen, mit denen sich zu befassen noch niemandem Nutzen gebracht hat.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 13, 10, 'Wir besitzen einen Opferaltar, von dem zu essen die kein Recht haben, welche dem Zelt obliegen;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 13, 11, 'denn von den Tieren, deren Blut zur Sühnung der Sünde durch den Hohenpriester in das Heiligtum hineingebracht wird, werden die Leiber außerhalb des Lagers verbrannt.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 13, 12, 'Deshalb hat auch Jesus, um das Volk durch sein eigenes Blut zu heiligen, außerhalb des Stadttores gelitten.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 13, 13, 'So wollen wir denn zu ihm vor das Lager hinausgehen und seine Schmach tragen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 13, 14, 'Denn wir haben hier keine bleibende Stadt, sondern suchen die zukünftige.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 13, 15, 'So wollen wir also durch ihn Gott allezeit ein Lobopfer darbringen, das heißt die »Frucht unserer Lippen«, die seinen Namen bekennen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 13, 16, 'Wohlzutun und mitzuteilen vergeßt nicht, denn das sind Opfer, an denen Gott Wohlgefallen hat. –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 13, 17, 'Gehorcht euren Führern und fügt euch ihnen, denn sie wachen über eure Seelen als solche, die einst Rechenschaft abzulegen haben: möchten sie das mit Freuden tun und nicht mit Seufzen, denn das wäre für euch kein Gewinn!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 13, 18, 'Betet für uns; denn wir sind uns bewußt, ein gutes Gewissen zu haben, weil wir bestrebt sind, in allen Beziehungen einen ehrbaren Wandel zu führen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 13, 19, 'Um so dringender aber fordere ich euch dazu auf, damit ich euch um so schneller zurückgegeben werde.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 13, 20, 'Der Gott des Friedens aber, der den großen Hirten der Schafe, unsern Herrn Jesus, von den Toten heraufgeführt hat durch das Blut des ewigen Bundes,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 13, 21, 'der möge euch in allem Guten zur Ausrichtung seines Willens ausrüsten und in uns das wirken, was (vor) ihm wohlgefällig ist, durch Jesus Christus, dem die Herrlichkeit gebührt in alle Ewigkeit! Amen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 13, 22, 'Ich ermahne euch aber, liebe Brüder: laßt euch dies (mein) Mahnwort gefallen; ich habe euch ja auch nur kurz geschrieben.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 13, 23, 'Vernehmt die Mitteilung, daß unser Bruder Timotheus freigelassen ist; mit ihm zusammen werde ich euch besuchen, wenn er bald kommt.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 13, 24, 'Grüßt alle eure Vorsteher und alle Heiligen. Die (Brüder) aus Italien lassen euch grüßen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 13, 25, 'Die Gnade sei mit euch allen!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (74, 1, 1, 'Ich, Jakobus, ein Knecht Gottes und des Herrn Jesus Christus, sende den zwölf in der Zerstreuung (unter den Heiden) lebenden Stämmen meinen Gruß.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (74, 1, 2, 'Erachtet es für lauter Freude, meine Brüder, wenn ihr in mancherlei Versuchungen geratet;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (74, 1, 3, 'ihr erkennt ja, daß die Bewährung eures Glaubens standhaftes Ausharren bewirkt.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (74, 1, 4, 'Das standhafte Ausharren muß aber zu voller Betätigung führen, damit ihr vollkommen und tadellos seid und sich in keiner Beziehung ein Mangel an euch zeigt.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (74, 1, 5, 'Sollte aber jemand von euch Mangel an Weisheit haben, so erbitte er sie sich von Gott, der allen ohne weiteres und ohne laute Vorwürfe gibt: dann wird sie ihm zuteil werden.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (74, 1, 6, 'Nur bitte er im Glauben, ohne irgendeinen Zweifel zu hegen; denn wer da zweifelt, der gleicht einer vom Wind getriebenen und hin und her geworfenen Meereswoge.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (74, 1, 7, 'Ein solcher Mensch darf nicht erwarten, daß er etwas vom Herrn empfangen werde,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (74, 1, 8, 'er, ein Mann mit zwei Seelen, unbeständig auf allen seinen Wegen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (74, 1, 9, 'Es rühme sich aber der niedrig stehende Bruder seiner Höhe,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (74, 1, 10, 'der reiche dagegen seiner Niedrigkeit, weil er wie die Blumen des Grases vergehen wird.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (74, 1, 11, 'Denn die Sonne geht mit ihrer Glut auf und versengt das Gras; dann fallen seine Blumen ab, und seine ganze Schönheit ist dahin: so wird auch der Reiche in seinen Wegen verwelken. –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (74, 1, 12, 'Selig ist der Mann, der die Versuchung standhaft erträgt! Denn nachdem er sich bewährt hat, wird er das Leben als Siegeskranz empfangen, den er denen verheißen hat, die ihn lieben.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (74, 1, 13, 'Niemand sage, wenn er (zum Bösen) versucht wird: »Von Gott werde ich versucht«; denn Gott kann nicht vom Bösen versucht werden, versucht aber auch seinerseits niemand.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (74, 1, 14, 'Nein, ein jeder wird (zum Bösen) versucht, indem er von seiner eigenen Lust gereizt und gelockt wird.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (74, 1, 15, 'Sodann, wenn die Lust empfangen hat, gebiert sie Sünde; die Sünde aber gebiert, wenn sie zur Vollendung gekommen ist, den Tod. –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (74, 1, 16, 'Irret euch nicht, meine geliebten Brüder:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (74, 1, 17, 'lauter gute Gabe und lauter vollkommenes Geschenk kommt von oben herab, vom Vater der Himmelslichter, bei dem keine Veränderung und keine zeitweilige Verdunkelung stattfindet.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (74, 1, 18, 'Aus freiem Liebeswillen hat er uns durch das Wort der Wahrheit ins Dasein gerufen, damit wir gewissermaßen die Erstlingsfrucht unter seinen Geschöpfen wären.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (74, 1, 19, 'Wisset, meine geliebten Brüder: es sei [aber] jeder Mensch schnell (bereit) zum Hören, langsam zum Reden und langsam zum Zorn;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (74, 1, 20, 'denn der Zorn des Menschen tut nichts, was vor Gott recht ist.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (74, 1, 21, 'Darum legt alle Unsauberkeit und den letzten Rest der Bosheit ab, und nehmt mit Sanftmut das euch eingepflanzte Wort an, das eure Seelen zu retten vermag.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (74, 1, 22, 'Seid aber Täter des Wortes und nicht bloß Hörer, sonst betrügt ihr euch selbst.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (74, 1, 23, 'Denn wer nur ein Hörer des Wortes ist, aber kein Täter, der gleicht einem Menschen, der sein leibliches Gesicht im Spiegel beschaut;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (74, 1, 24, 'denn nachdem er sich beschaut hat und weggegangen ist, vergißt er alsbald, wie er ausgesehen hat.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (74, 1, 25, 'Wer dagegen in das vollkommene Gesetz der Freiheit hineingeschaut hat und bei ihm verbleibt, indem er nicht ein vergeßlicher Hörer, sondern ein wirklicher Täter ist, der wird in seinem Tun selig sein.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (74, 1, 26, 'Wenn jemand Gott zu dienen meint und dabei seine Zunge nicht im Zaume hält, vielmehr sein Herz betrügt, dessen Gottesdienst ist nichtig.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (74, 1, 27, 'Ein reiner und fleckenloser Gottesdienst vor Gott dem Vater besteht darin, daß man Waisen und Witwen in ihrer Trübsal besucht und sich selbst von der Welt unbefleckt erhält.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (74, 2, 1, 'Meine Brüder, habt den Glauben an unsern Herrn Jesus Christus, (den Herrn) der Herrlichkeit, nicht so, daß Ansehen der Person damit verbunden ist.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (74, 2, 2, 'Wenn z.B. in eure (gottesdienstliche) Versammlung ein Mann mit goldenen Ringen an den Fingern und in prächtiger Kleidung tritt und zugleich ein armer in unsauberem Anzug erscheint,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (74, 2, 3, 'und ihr dann eure Blicke auf den prächtig Gekleideten richtet und zu ihm sagt: »Setze du dich hierher auf den guten Platz«, während ihr zu dem Armen sagt: »Stelle du dich dorthin oder setze dich hier unten auf meinen Fußschemel!« –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (74, 2, 4, 'seid ihr da nicht in Zwiespalt mit euch selbst geraten und zu Richtern mit bösen Erwägungen geworden?');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (74, 2, 5, 'Hört (mich an), meine geliebten Brüder! Hat Gott nicht gerade die, welche für die Welt arm sind, dazu erwählt, reich im Glauben und Erben des Reiches zu sein, das er denen verheißen hat, die ihn lieben?');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (74, 2, 6, 'Ihr aber habt den Armen mißachtet. Sind es nicht gerade die Reichen, die euch gewalttätig behandeln, und ziehen nicht gerade sie euch vor die Gerichte?');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (74, 2, 7, 'Sind nicht gerade sie es, die den guten Namen lästern, der (bei der Taufe) über euch angerufen worden ist?');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (74, 2, 8, 'Allerdings, wenn ihr das königliche Gesetz nach dem Schriftwort erfüllt: »Du sollst deinen Nächsten lieben wie dich selbst«, so tut ihr recht daran;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (74, 2, 9, 'wenn ihr aber die Person anseht, so begeht ihr Sünde und werdet vom Gesetz als Übertreter überführt.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (74, 2, 10, 'Denn wer das ganze Gesetz erfüllt, aber gegen ein einziges Gebot verstößt, der hat sich damit gegen das ganze (Gesetz) vergangen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (74, 2, 11, 'Denn der da geboten hat: »Du sollst nicht ehebrechen«, der hat auch geboten: »Du sollst nicht töten.« Wenn du nun zwar kein Ehebrecher bist, wohl aber ein Mörder, so bist du ein Übertreter des (ganzen) Gesetzes geworden.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (74, 2, 12, 'Redet so und handelt so wie Leute, die (einst) durch das Gesetz der Freiheit gerichtet werden sollen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (74, 2, 13, 'Denn das Gericht verfährt erbarmungslos gegen den, der kein Erbarmen geübt hat; die Barmherzigkeit dagegen rühmt sich gegen das Gericht.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (74, 2, 14, 'Was nützt es, meine Brüder, wenn jemand behauptet, Glauben zu besitzen, dabei aber keine Werke (aufzuweisen) hat? Vermag etwa der Glaube ihn zu retten?');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (74, 2, 15, 'Wenn z.B. ein Bruder oder eine Schwester keine Kleidung hat und an der täglichen Nahrung Mangel leidet');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (74, 2, 16, 'und dann jemand von euch zu ihnen sagt: »Geht hin in Frieden, wärmt euch und eßt euch satt!«, ohne ihnen jedoch das zu geben, was ihr Leib bedarf: welchen Nutzen hat das für sie?');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (74, 2, 17, 'So steht es auch mit dem Glauben: hat er keine Werke (aufzuweisen), so ist er an sich selbst tot.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (74, 2, 18, 'Doch es wird jemand einwenden: »Du hast Glauben, und ich habe Werke; weise mir deinen Glauben nach, der ohne Werke ist, und ich will dir aus meinen Werken den Glauben nachweisen!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (74, 2, 19, 'Du glaubst, daß es nur einen Gott gibt? Du tust recht daran; aber das glauben auch die Teufel und – schaudern dabei.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (74, 2, 20, 'Willst du wohl einsehen, du gedankenloser Mensch, daß der Glaube ohne die Werke unnütz ist?');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (74, 2, 21, 'Ist nicht unser Vater Abraham aus Werken gerechtfertigt worden, da er seinen Sohn Isaak auf dem Opferaltar darbrachte?');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (74, 2, 22, 'Daran siehst du, daß der Glaube mit seinen Werken zusammengewirkt hat und der Glaube erst durch die Werke zur Vollendung gebracht ist,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (74, 2, 23, 'und daß so erst das Schriftwort sich erfüllt hat, das da lautet: »Abraham glaubte aber Gott, und das wurde ihm als Gerechtigkeit angerechnet«, und er wurde ›Gottes Freund‹ genannt.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (74, 2, 24, 'So seht ihr, daß der Mensch aus Werken gerechtfertigt wird und nicht aus Glauben allein.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (74, 2, 25, 'Ist nicht ebenso auch die Dirne Rahab aufgrund von Werken gerechtfertigt worden, weil sie die Kundschafter bei sich aufgenommen und sie auf einem anderen Wege wieder (aus dem Hause) entlassen hatte?');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (74, 2, 26, 'Denn ebenso wie der Leib ohne Geist tot ist, ebenso ist auch der Glaube ohne Werke tot.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (74, 3, 1, 'Drängt euch nicht zum Lehrerberuf, meine Brüder! Bedenkt wohl, daß wir (Lehrer) ein um so strengeres Urteil empfangen werden.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (74, 3, 2, 'Wir fehlen ja allesamt vielfach; wer sich beim Reden nicht verfehlt, der ist ein vollkommener Mann und vermag auch den ganzen Leib im Zaume zu halten.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (74, 3, 3, 'Wenn wir den Pferden die Zäume ins Maul legen, um sie uns gehorsam zu machen, so haben wir damit auch ihren ganzen Leib in der Gewalt.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (74, 3, 4, 'Seht, auch die Schiffe, die doch so groß sind und von starken Winden getrieben werden, lassen sich durch ein ganz kleines Steuerruder dahin lenken, wohin das Belieben des Steuermannes sie haben will.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (74, 3, 5, 'So ist auch die Zunge nur ein kleines Glied und kann sich doch großer Dinge rühmen. Seht, wie klein ist das Feuer und wie groß der Wald, den es in Brand setzt!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (74, 3, 6, 'Auch die Zunge ist ein Feuer; als der Inbegriff der Ungerechtigkeit steht die Zunge unter unsern Gliedern da, sie, die den ganzen Leib befleckt, die sowohl das (rollende) Rad des Seins in Brand setzt als auch (selbst) von der Hölle in Brand gesetzt wird.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (74, 3, 7, 'Denn jede Art der vierfüßigen Tiere und Vögel, der Schlangen und Seetiere wird von der menschlichen Natur gebändigt und ist von ihr gebändigt worden;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (74, 3, 8, 'aber die Zunge vermag kein Mensch zu bändigen, dies ruhelose Übel, voll todbringenden Giftes.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (74, 3, 9, 'Mit ihr segnen wir den Herrn und Vater, und mit ihr fluchen wir den Menschen, die doch nach Gottes Bild geschaffen sind:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (74, 3, 10, 'aus demselben Munde gehen Segen und Fluch hervor. Das darf nicht so sein, meine Brüder.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (74, 3, 11, 'Läßt etwa eine Quelle aus derselben Öffnung süßes und bitteres Wasser sprudeln?');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (74, 3, 12, 'Kann etwa, meine Brüder, ein Feigenbaum Oliven tragen oder ein Weinstock Feigen? Ebensowenig kann eine Salzquelle süßes Wasser geben.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (74, 3, 13, 'Wer ist weise und einsichtsvoll unter euch? Der beweise durch seinen guten Wandel seine Werke in sanftmütiger Weisheit!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (74, 3, 14, 'Wenn ihr aber bittere Eifersucht und Zanksucht in eurem Herzen hegt, so rühmt euch nicht lügnerisch im Widerspruch mit der Wahrheit.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (74, 3, 15, 'Das ist nicht die Weisheit, die von oben her kommt, sondern ist eine irdische, sinnliche, teuflische.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (74, 3, 16, 'Denn wo Eifersucht und Zanksucht herrschen, da gibt’s Unfrieden und alle Arten bösen Tuns.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (74, 3, 17, 'Die Weisheit dagegen, die von oben kommt, ist fürs erste lauter, sodann friedfertig, freundlich, nachgiebig, reich an Erbarmen und guten Früchten, frei von Zweifel und ohne Heuchelei.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (74, 3, 18, '(Der Same) aber, (der) die Frucht der Gerechtigkeit (hervorbringt), wird in Frieden für die gesät, die Frieden stiften.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (74, 4, 1, 'Woher kommen die Kämpfe und woher die Streitigkeiten bei euch? Doch wohl daher, daß eure Lüste einen Kampf in euren Gliedern führen?');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (74, 4, 2, 'Ihr seid begehrlich – und gelangt doch nicht zum Besitz; ihr mordet und seid neidisch, ohne doch eure Wünsche erfüllt zu sehen; ihr lebt in Kampf und Streitigkeiten und gelangt doch nicht zum Besitz, weil ihr nicht betet;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (74, 4, 3, 'ihr betet wohl, empfangt aber nichts, weil ihr in böser Absicht betet, nämlich um (das Erbetene) in euren Lüsten wieder durchzubringen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (74, 4, 4, 'Ihr gottabtrünnigen Seelen! Wißt ihr nicht, daß die Freundschaft mit der Welt Feindschaft gegen Gott ist? Wer also ein Freund der Welt sein will, erweist sich als Feind Gottes.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (74, 4, 5, 'Oder meint ihr, die Schrift mache leere Worte, wenn sie sagt: »Eifersüchtiges Verlangen hegt der Geist, den er Wohnung in uns hat nehmen lassen«?');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (74, 4, 6, 'Um so reicher ist aber die Gnade, die er zuteilt. Darum heißt es: »Gott widersteht den Hoffärtigen, den Demütigen aber gibt er Gnade.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (74, 4, 7, 'Unterwerft euch also Gott und widersteht dem Teufel, so wird er von euch fliehen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (74, 4, 8, 'Nahet euch zu Gott, so wird er sich zu euch nahen; reinigt euch die Hände, ihr Sünder, und heiligt eure Herzen, ihr Doppelherzigen!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (74, 4, 9, 'Fühlt euer Elend, trauert und weint! Euer Lachen verwandle sich in Traurigkeit und eure Freude in Betrübnis!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (74, 4, 10, 'Demütigt euch vor dem Herrn, so wird er euch erhöhen!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (74, 4, 11, 'Redet nicht feindselig gegeneinander, liebe Brüder! Wer feindselig gegen seinen Bruder redet oder seinen Bruder richtet, der redet feindselig gegen das Gesetz und richtet das Gesetz; wenn du aber das Gesetz richtest, so bist du nicht ein Täter des Gesetzes, sondern ein Richter.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (74, 4, 12, 'Nur einer ist Gesetzgeber und Richter; er, der die Macht hat zu erretten und zu verderben. Wer aber bist du, daß du dich zum Richter über den Nächsten machst?');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (74, 4, 13, 'Weiter nun: Ihr, die ihr sagt: »Heute oder morgen wollen wir in die und die Stadt ziehen, wollen dort ein Jahr bleiben, Geschäfte machen und Geld verdienen«, –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (74, 4, 14, 'und ihr wißt doch nicht, was der morgende Tag bringen wird, wie es dann um euer Leben steht. Ihr seid doch nur ein Rauch, der für kurze Zeit sichtbar wird und dann verschwindet.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (74, 4, 15, 'Statt dessen solltet ihr sagen: »Wenn es der Wille des Herrn ist, werden wir am Leben bleiben und dies oder jenes tun.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (74, 4, 16, 'So aber tut ihr noch groß mit euren hochfahrenden Gedanken! Alle derartige Großtuerei ist verwerflich.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (74, 4, 17, 'Wer also weiß, wie er sich richtig zu verhalten hat, es aber nicht tut, für den ist es Sünde.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (74, 5, 1, 'Weiter nun: Ihr Reichen, weinet und jammert über die Leiden, die euch bevorstehen!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (74, 5, 2, 'Euer Reichtum ist vermodert, und eure Gewänder sind ein Fraß für die Motten geworden,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (74, 5, 3, 'euer Gold und Silber ist vom Rost angefressen, und ihr Rost wird ein Zeugnis für euch sein, und der Rost wird euer Fleisch fressen wie Feuer. Noch jetzt in der Endzeit habt ihr euch Schätze gesammelt!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (74, 5, 4, 'Wisset wohl: Der Lohn, den ihr den Arbeitern, die eure Ernte eingebracht haben, vorenthalten habt, schreit (aus euren Häusern zum Himmel empor), und die Klagerufe eurer Schnitter sind zu den Ohren des Herrn der Heerscharen gedrungen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (74, 5, 5, 'Ihr habt hier auf Erden geschwelgt und gepraßt, habt euch noch am Tage der Schlachtung nach Herzenslust gütlich getan.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (74, 5, 6, 'Ihr habt den Gerechten verurteilt, ihn gemordet; er leistet euch keinen Widerstand.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (74, 5, 7, 'So harret denn standhaft aus, liebe Brüder, bis zur Ankunft des Herrn! Bedenket: Der Landmann wartet auf die köstliche Frucht der Erde und geduldet sich ihretwegen, bis sie den Früh- und Spätregen empfängt.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (74, 5, 8, 'So haltet auch ihr geduldig aus und macht eure Herzen fest, denn die Ankunft des Herrn steht nahe bevor.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (74, 5, 9, 'Seufzt nicht gegeneinander, liebe Brüder, damit ihr nicht gerichtet werdet! Bedenkt wohl: Der Richter steht (schon) vor der Tür!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (74, 5, 10, 'Nehmt euch, liebe Brüder, für die Leiden und das geduldige Aushalten die Propheten zum Vorbild, die im Namen des Herrn geredet haben!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (74, 5, 11, 'Seht, wir preisen die selig, welche geduldig ausgeharrt haben. Vom standhaften Ausharren Hiobs habt ihr gehört und von dem Ausgang, den der Herr ihm bereitet hat; erkennet daraus, daß der Herr reich an Mitleid und voll Erbarmens ist.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (74, 5, 12, 'Vor allem aber, meine Brüder, schwöret nicht, weder beim Himmel noch bei der Erde noch sonst irgendeinen Eid; es sei vielmehr euer Ja ein Ja und euer Nein ein Nein, damit ihr nicht dem Gericht verfallt.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (74, 5, 13, 'Hat jemand unter euch zu leiden, so bete er; geht es jemandem gut, so singe er Loblieder.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (74, 5, 14, 'Ist jemand unter euch krank, so lasse er die Ältesten der Gemeinde zu sich kommen; diese sollen dann über ihm beten, nachdem sie ihn im Namen des Herrn mit Öl gesalbt haben;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (74, 5, 15, 'alsdann wird das gläubige Gebet den Kranken retten, und der Herr wird ihn aufrichten, und wenn er Sünden begangen hat, wird ihm Vergebung zuteil werden.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (74, 5, 16, 'Bekennet also einander die Sünden und betet füreinander, damit ihr Heilung erlangt; das Gebet eines Gerechten besitzt eine große Kraft, wenn es ernstlich ist.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (74, 5, 17, 'Elia war ein Mensch von gleicher Art wie wir und betete inständig, es möchte nicht regnen; da regnete es drei und ein halbes Jahr lang nicht im Lande.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (74, 5, 18, 'Er betete dann nochmals: da gab der Himmel wieder Regen, und die Erde ließ ihre Frucht sprossen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (74, 5, 19, 'Meine Brüder, wenn jemand unter euch von der Wahrheit abgeirrt ist und einer ihn zur Umkehr bringt,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (74, 5, 20, 'so soll er wissen: Wer einen Sünder von seinem Irrweg bekehrt, der wird damit seine Seele vom Tode retten und eine Menge von Sünden bedecken.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (75, 1, 1, 'Ich, Judas, ein Knecht Jesu Christi und ein Bruder des Jakobus, sende meinen Gruß den Berufenen, die in Gott, dem Vater, geliebt und für Jesus Christus bewahrt sind.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (75, 1, 2, 'Barmherzigkeit, Friede und Liebe mögen euch immer reichlicher zuteil werden!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (75, 1, 3, 'Geliebte! Da es mein Herzenswunsch ist, euch über unsere gemeinsame Rettung zu schreiben, fühle ich mich gedrungen, in meiner Zuschrift die Mahnung an euch zu richten, für den Glauben zu kämpfen, der den Heiligen ein für allemal übergeben worden ist.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (75, 1, 4, 'Es haben sich nämlich gewisse Leute nebenbei eingeschlichen, die schon längst für folgendes Verdammungsurteil aufgeschrieben sind: »Gottlose Leute, welche die Gnade unsers Gottes zur Ausschweifung verkehren und unsern alleinigen Gebieter und Herrn Jesus Christus verleugnen.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (75, 1, 5, 'Ich will euch aber daran erinnern – die betreffenden Tatsachen sind euch allerdings sämtlich schon bekannt –, daß der Herr (zuerst) zwar das Volk Israel aus dem Lande Ägypten gerettet, beim zweiten Mal aber die, welche nicht glaubten, vernichtet hat;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (75, 1, 6, 'daß er ferner die Engel, die ihren Herrschaftsbereich nicht bewahrt, sondern ihre eigene Wohnstätte verlassen hatten, für den großen Gerichtstag mit ewigen Fesseln in der Finsternis drunten verwahrt hat.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (75, 1, 7, 'Wie Sodom und Gomorrha nebst den umliegenden Städten, die in gleicher Weise wie diese in Unzucht gelebt und (Wesen von) andersartigem Fleisch nachgestellt haben, stehen sie als warnendes Beispiel da, indem sie die Strafe ewigen Feuers zu erleiden haben.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (75, 1, 8, 'Trotzdem beflecken sich auch diese Leute in ihren Träumereien fleischlich in gleicher Weise, erkennen keine Herrschermacht an und lästern Herrlichkeiten.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (75, 1, 9, 'Dagegen hat der Erzengel Michael, als er mit dem Teufel um den Leichnam Moses stritt und einen Wortwechsel mit ihm führte, kein lästerndes Urteil über ihn auszusprechen gewagt, sondern (nur) gesagt: »Der Herr wolle dich zur Ruhe verweisen!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (75, 1, 10, 'Diese Leute dagegen schmähen, was sie gar nicht kennen; worauf sie sich aber nach ihrer natürlichen Veranlagung wie die vernunftlosen Tiere verstehen, darin richten sie sich zugrunde.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (75, 1, 11, 'Wehe ihnen! Sie sind auf dem Wege Kains gegangen, haben sich aus Gewinnsucht in die Verirrung Bileams verstricken lassen und sich durch ihre Auflehnung wie einst Korah ins Verderben gestürzt.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (75, 1, 12, 'Dies sind die Leute, die bei euren Liebesmahlen als Schmutzflecken ohne Scheu mitschmausen und es sich dabei wohl sein lassen; regenlose Wolken sind sie, die von Winden vorübergetrieben werden, spätherbstlich kahle, fruchtlose, zweimal abgestorbene, entwurzelte Bäume,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (75, 1, 13, 'wilde Meereswogen, die ihre eigenen Schändlichkeiten ausschäumen, Irrsterne, denen die dunkelste Finsternis in (alle) Ewigkeit aufbewahrt ist.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (75, 1, 14, 'Nun, auch diesen Leuten gilt die Weissagung, die Henoch, der siebte Nachkomme Adams, ausgesprochen hat mit den Worten: »Siehe, gekommen ist der Herr inmitten seiner heiligen Zehntausende,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (75, 1, 15, 'um Gericht über alle zu halten und um alle Gottlosen zu bestrafen wegen aller ihrer gottlosen Taten, mit denen sie gefrevelt haben, und wegen aller frechen Reden, die sie als gottlose Sünder gegen ihn geführt haben.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (75, 1, 16, 'Dies sind die mißvergnügten Leute, die über ihr Geschick stets murren, obwohl sie nach ihren Lüsten wandeln, Leute, deren Mund hochfahrende Reden führt, während sie da, wo es ihren Vorteil gilt, hochstehenden Personen huldigen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (75, 1, 17, 'Ihr aber, Geliebte, bleibet der Worte eingedenk, welche die Apostel unsers Herrn Jesus Christus vormals geredet haben;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (75, 1, 18, 'sie haben euch (immer wieder) verkündet: »In der Endzeit werden Spötter auftreten, die nach ihren der Gottlosigkeit zugewandten Lüsten wandeln.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (75, 1, 19, 'Dies sind die Leute, welche Spaltungen hervorrufen, seelische Menschen, die den (heiligen) Geist nicht haben.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (75, 1, 20, 'Ihr aber, Geliebte, erbauet euch auf eurem hochheiligen Glaubensgrunde, betet im heiligen Geiste');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (75, 1, 21, 'und bewahret euch dadurch in der Liebe Gottes, voll zuversichtlichen Wartens auf die Barmherzigkeit unsers Herrn Jesus Christus, (die euch) zum ewigen Leben (führen wird)!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (75, 1, 22, 'Und mit den einen, die sich in Zweifeln befinden, habt Mitleid:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (75, 1, 23, 'reißt sie aus dem Feuer heraus und rettet sie so! Mit den anderen dagegen habt Mitleid in Furcht, indem ihr sogar das Kleid (an ihnen) verabscheut, das vom Fleisch her beschmutzt ist!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (75, 1, 24, 'Dem aber, der euch vor allem Straucheln zu bewahren und euch unsträflich mit Frohlocken vor das Angesicht seiner Herrlichkeit hinzustellen vermag,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (75, 1, 25, 'ihm, dem alleinigen Gott, der durch unsern Herrn Jesus Christus unser Retter ist – ihm gebührt Herrlichkeit und Erhabenheit, Macht und Gewalt (wie) vor aller Weltzeit, (so) auch jetzt und in alle Ewigkeit! Amen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 1, 1, 'Offenbarung Jesu Christi, die Gott ihm hat zuteil werden lassen, um seinen Knechten anzuzeigen, was in Bälde geschehen soll; und er hat es durch die Sendung seines Engels seinem Knechte Johannes durch Zeichen kundgetan,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 1, 2, 'und dieser legt nunmehr Zeugnis ab von dem Worte Gottes und von dem Zeugnis Jesu Christi, von allem, was er gesehen hat.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 1, 3, 'Selig ist der Vorleser und (selig sind) die Hörer der Worte der Weissagung und die das bewahren, was in ihr geschrieben steht; denn die Zeit (der Erfüllung) ist nahe.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 1, 4, 'Ich, Johannes, sende den sieben Gemeinden in der Provinz Asien meinen Gruß: Gnade sei mit euch und Friede von dem, der da ist und der da war und der da kommt, und von den sieben Geistern, die vor seinem Thron (sind),');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 1, 5, 'und von Jesus Christus, dem treuen Zeugen, dem Erstgeborenen der Toten und dem Herrscher über die Könige der Erde! Ihm, der uns liebt und uns durch sein Blut von unsern Sünden erlöst hat');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 1, 6, 'und uns zu einer Königsherrschaft gemacht hat, zu Priestern für seinen Gott und Vater: sein ist die Herrlichkeit und die Macht in alle Ewigkeit! Amen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 1, 7, 'Seht, er kommt mit den Wolken, und sehen werden ihn die Augen aller, auch die, welche ihn durchstochen haben, und wehklagen werden um ihn alle Geschlechter der Erde. Ja, Amen!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 1, 8, '»Ich bin das A und das O«, spricht Gott der Herr, der da ist und der da war und der da kommt, der Allmächtige.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 1, 9, 'Ich, Johannes, euer Bruder und Genosse, der ich mit euch teilhabe an der Drangsal und an der Königsherrschaft und an standhaftem Ausharren in Jesus – ich war auf die Insel namens Patmos gekommen um des Wortes Gottes und des Zeugnisses Jesu willen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 1, 10, 'Da geriet ich durch den Geist in Verzückung am Tage des Herrn und hörte hinter mir eine Stimme, gewaltig wie Posaunenschall;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 1, 11, 'die rief mir zu: »Was du zu sehen bekommst, das schreibe in ein Buch und sende es an die sieben Gemeinden: nach Ephesus und nach Smyrna und nach Pergamon und nach Thyatira und nach Sardes und nach Philadelphia und nach Laodizea.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 1, 12, 'Da wandte ich mich um und wollte nach der Stimme sehen, die mit mir redete; und als ich mich umgewandt hatte, erblickte ich sieben goldene Leuchter');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 1, 13, 'und in der Mitte der Leuchter Einen, der wie ein Menschensohn aussah; er war mit einem Talar angetan und um die Brust mit einem goldenen Gürtel gegürtet;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 1, 14, 'sein Haupt(haar) aber und seine (Bart)haare waren so weiß wie schneeweiße Wolle und seine Augen wie eine Feuerflamme;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 1, 15, 'seine Füße glichen dem Golderz, als wären sie im Schmelzofen glühend gemacht, und seine Stimme (klang) wie das Rauschen vieler Wasser.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 1, 16, 'In seiner rechten Hand hatte er sieben Sterne; aus seinem Munde ging ein scharfes, zweischneidiges Schwert hervor, und sein Angesicht (leuchtete), wie wenn die Sonne in ihrer Kraft scheint.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 1, 17, 'Bei seinem Anblick fiel ich wie tot ihm zu Füßen nieder; da legte er seine rechte Hand auf mich und sagte: »Fürchte dich nicht! Ich bin’s, der Erste und der Letzte');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 1, 18, 'und der Lebende; ich war tot, und siehe, ich lebe in alle Ewigkeit und habe die Schlüssel des Todes und des Totenreiches.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 1, 19, 'Schreibe nun auf, was du (bisher) gesehen hast, und was (jetzt schon) ist und was danach noch geschehen wird.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 1, 20, 'Was das Geheimnis der sieben Sterne betrifft, die du auf meiner rechten Hand gesehen hast, sowie die sieben goldenen Leuchter, (so wisse): Die sieben Sterne sind die Engel der sieben Gemeinden, und die sieben Leuchter sind die sieben Gemeinden.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 2, 1, '»Dem Engel der Gemeinde in Ephesus schreibe: So spricht der, welcher die sieben Sterne fest in seiner rechten Hand hält und der inmitten der sieben goldenen Leuchter wandelt:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 2, 2, 'Ich kenne deine Werke und deine Arbeit und dein standhaftes Ausharren und (weiß), daß du Böse nicht zu ertragen vermagst; du hast auch die geprüft, welche sich für Apostel ausgeben, ohne es zu sein, und hast Lügner in ihnen erkannt.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 2, 3, 'Auch standhaftes Ausharren besitzest du und hast um meines Namens willen schwere Lasten getragen und bist nicht müde geworden.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 2, 4, 'Aber ich habe an dir auszusetzen, daß du deine erste Liebe aufgegeben hast.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 2, 5, 'Denke also daran, von welcher Höhe du herabgefallen bist; und gehe in dich und tue die ersten Werke wieder! Sonst komme ich über dich und werde deinen Leuchter von seiner Stelle rücken, wenn du nicht in dich gehst.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 2, 6, 'Doch das hast du (für dich), daß du die Werke der Nikolaiten hassest, die auch mir verhaßt sind.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 2, 7, 'Wer ein Ohr hat, der höre, was der Geist den Gemeinden sagt: Wer da überwindet, dem werde ich zu essen geben vom Baume des Lebens, der im Paradiese Gottes steht.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 2, 8, '»Und dem Engel der Gemeinde in Smyrna schreibe: So spricht der Erste und der Letzte, der tot gewesen und wieder lebendig geworden ist:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 2, 9, 'Ich kenne deine Drangsal und deine Armut – dennoch bist du reich –; ich weiß auch, daß du von denen geschmäht wirst, welche Juden zu sein behaupten und es doch nicht sind, sondern sie sind eine Synagoge des Satans.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 2, 10, 'Fürchte dich nicht vor den Leiden, die dir noch bevorstehen! Siehe, der Teufel hat vor, einige von euch ins Gefängnis zu werfen, damit ihr erprobt werdet, und ihr werdet eine zehntägige Drangsalszeit zu bestehen haben. Beweise dich getreu bis in den Tod, so will ich dir den (Sieges-) Kranz des Lebens geben!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 2, 11, 'Wer ein Ohr hat, der höre, was der Geist den Gemeinden sagt: Wer da überwindet, dem soll der zweite Tod nichts anhaben können.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 2, 12, '»Und dem Engel der Gemeinde in Pergamon schreibe: So spricht der, welcher das scharfe, zweischneidige Schwert hat:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 2, 13, 'Ich weiß, wo du wohnst, nämlich da, wo der Thron des Satans steht; doch du hältst meinen Namen fest und hast den Glauben an mich auch in den Tagen des Antipas, meines treuen Zeugen, nicht verleugnet, der bei euch ermordet worden ist, dort, wo der Satan wohnt.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 2, 14, 'Doch ich habe einiges wenige an dir auszusetzen; denn du hast dort Leute unter dir, die an die Lehre Bileams sich halten, der den Balak unterwies, die Israeliten zum Bösen zu verführen, nämlich Götzenopferfleisch zu essen und Unzucht zu treiben.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 2, 15, 'So hast auch du solche unter dir, die sich in derselben Weise an die Lehre der Nikolaiten halten.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 2, 16, 'Gehe also in dich, sonst komme ich bald über dich und werde jene mit dem Schwert meines Mundes bekämpfen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 2, 17, 'Wer ein Ohr hat, der höre, was der Geist den Gemeinden sagt: Wer da überwindet, dem werde ich von dem verborgenen Manna (zu essen) geben; auch will ich ihm einen weißen Stein geben, auf dem ein neuer Name geschrieben steht, den außer dem Empfänger niemand kennt.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 2, 18, '»Und dem Engel der Gemeinde in Thyatira schreibe: So spricht der Sohn Gottes, der Augen hat wie eine Feuerflamme und dessen Füße dem schimmernden Golderz gleichen:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 2, 19, 'Ich kenne deine Werke: deine Liebe und deine Treue, deine Hilfsbereitschaft und dein standhaftes Ausharren, und weiß, daß deine Werke in letzter Zeit noch zahlreicher sind als die ersten.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 2, 20, 'Doch ich habe an dir auszusetzen, daß du das Weib Isebel gewähren läßt, die sich für eine Prophetin ausgibt und als Lehrerin wirkt und meine Knechte dazu verführt, Unzucht zu treiben und Götzenopferfleisch zu essen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 2, 21, 'Ich habe ihr eine Frist zur Umkehr gegeben, doch sie will sich von ihrer Unzucht nicht bekehren.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 2, 22, 'Siehe, ich werfe sie aufs Krankenlager und stürze die, welche mit ihr die Ehe brechen, in große Trübsal (Kap. 18), wenn sie sich nicht vom Treiben dieser (Buhlerin) abwenden;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 2, 23, 'und ihre Kinder will ich an einer Seuche sterben lassen; dann werden alle Gemeinden erkennen, daß ich es bin, der Nieren und Herzen erforscht, und ich werde einem jeden von euch nach seinen Werken vergelten.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 2, 24, 'Euch anderen aber in Thyatira, allen denen, welche sich zu dieser Lehre nicht halten, da ihr die ›Tiefen des Satans‹, wie sie behaupten, nicht erkannt habt – euch sage ich: Ich lege euch keine weitere Last auf;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 2, 25, 'nur haltet das fest, was ihr besitzt, bis ich komme!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 2, 26, 'Und wer da überwindet und in meinen Werken bis ans Ende verharrt, dem will ich Macht über die Heiden geben,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 2, 27, 'und er soll sie mit eisernem Stabe weiden, wie man irdenes Geschirr zerschlägt,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 2, 28, 'wie auch ich (solche Macht) von meinem Vater empfangen habe; und ich will ihm den Morgenstern geben.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 2, 29, 'Wer ein Ohr hat, der höre, was der Geist den Gemeinden sagt.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 3, 1, '»Und dem Engel der Gemeinde in Sardes schreibe: So spricht der, der die sieben Geister Gottes und die sieben Sterne hat: Ich kenne deine Werke: du stehst in dem Rufe, daß du lebest, und bist doch tot.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 3, 2, 'Wache auf und stärke die übrigen (Gemeindeglieder), die nahe am Sterben waren! Denn ich habe deine Werke nicht als vollkommen vor meinem Gott erfunden.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 3, 3, 'Denke also daran, wie du (die Heilsbotschaft, oder: das Heil) empfangen und vernommen hast, halte daran fest und gehe in dich! Willst du aber nicht wachsam sein, so werde ich wie ein Dieb kommen, und du sollst sicherlich nicht wissen, zu welcher Stunde ich über dich kommen werde.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 3, 4, 'Du hast jedoch einige Namen in Sardes, die ihre Kleider nicht befleckt haben; diese sollen mit mir in weißen Kleidern einhergehen, denn sie sind dessen würdig.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 3, 5, 'Wer da überwindet, der wird mit weißen Kleidern angetan werden, und ich werde seinen Namen nimmermehr aus dem Buche des Lebens ausstreichen und werde seinen Namen vor meinem Vater und vor seinen Engeln bekennen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 3, 6, 'Wer ein Ohr hat, der höre, was der Geist den Gemeinden sagt.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 3, 7, '»Und dem Engel der Gemeinde in Philadelphia schreibe: So spricht der Heilige, der Wahrhaftige, der den Schlüssel Davids hat, er, der da öffnet, so daß niemand wieder zuschließen wird, und der da zuschließt, so daß? niemand wieder öffnet:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 3, 8, 'Ich kenne deine Werke. Siehe, ich habe eine offene Tür vor dir angebracht, die niemand zuzuschließen vermag; denn du besitzest zwar nur geringe Kraft, hast aber doch an meinem Wort festgehalten und meinen Namen nicht verleugnet.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 3, 9, 'Siehe, ich füge es so: aus der Synagoge des Satans, von den Leuten, die sich Juden nennen, aber es nicht sind, sondern lügen – siehe, ich will sie dahin bringen, daß sie kommen und sich vor deinen Füßen niederwerfen und erkennen, daß ich dich geliebt habe.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 3, 10, 'Weil du das Wort vom standhaften Warten auf mich bewahrt hast, will auch ich dich bewahren aus der Stunde der Versuchung, die über den ganzen Erdkreis kommen wird, um die Bewohner der Erde zu versuchen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 3, 11, 'Ich komme bald: halte fest, was du hast, damit niemand dir deine Krone raube!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 3, 12, 'Wer da überwindet, den werde ich zu einer Säule im Tempel meines Gottes machen, und er wird seinen Platz dort nie wieder verlieren, und ich werde auf ihn den Namen meines Gottes schreiben und den Namen der Stadt meines Gottes, des neuen Jerusalem, das aus dem Himmel von meinem Gott herabkommt, und auch meinen neuen Namen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 3, 13, 'Wer ein Ohr hat, der höre, was der Geist den Gemeinden sagt.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 3, 14, '»Und dem Engel der Gemeinde in Laodizea schreibe: So spricht der, welcher (das) Amen ist, der treue und wahrhaftige Zeuge, der Anfang der Schöpfung Gottes:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 3, 15, 'Ich kenne deine Werke, (ich weiß) daß du weder kalt noch heiß bist. O, daß du kalt oder heiß wärest!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 3, 16, 'So aber, weil du lau bist und weder heiß noch kalt, will ich dich aus meinem Munde ausspeien.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 3, 17, 'Weil du sagst: ›Ich bin reich, ja reich bin ich geworden und habe an nichts Mangel‹, und weil du nicht weißt, daß gerade du elend und erbarmenswert, arm, blind und nackt bist,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 3, 18, 'so rate ich dir: kaufe dir Gold von mir, das durch Feuer geläutert ist, damit du reich wirst, und weiße Kleider, damit du sie anziehst und die Schande deiner Blöße nicht zutage tritt, und Augensalbe zum Bestreichen deiner Augen, damit du sehen kannst.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 3, 19, 'Ich überführe und züchtige alle, die ich lieb habe. So sei nun eifrig und gehe in dich!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 3, 20, 'Siehe, ich stehe vor der Tür und klopfe an; wenn jemand meine Stimme hört und die Tür auftut, so werde ich bei ihm eintreten und das Mahl mit ihm halten und er mit mir.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 3, 21, 'Wer da überwindet, dem werde ich verleihen, mit mir auf meinem Thron zu sitzen, wie auch ich überwunden und mich mit meinem Vater auf seinen Thron gesetzt habe.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 3, 22, 'Wer ein Ohr hat, der höre, was der Geist den Gemeinden sagt.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 4, 1, 'Hierauf hatte ich ein Gesicht: ich sah, wie eine Tür im Himmel offenstand, und die erste Stimme, die ich wie Posaunenschall mit mir hatte reden hören, rief mir zu: »Komm herauf, hierher, so will ich dir zeigen, was hernach geschehen muß.« Sogleich geriet ich durch den Geist in Verzückung;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 4, 2, 'und siehe, da stand ein Thron im Himmel, und auf dem Thron saß jemand,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 4, 3, 'und der dort Thronende sah wie Jaspis- und Karneolstein aus, und den Thron umgab rings ein Regenbogen, der wie ein Smaragd aussah.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 4, 4, 'Rings um den Thron (standen; oder: sah ich) vierundzwanzig Throne, und auf den Thronen (sah ich) vierundzwanzig Älteste sitzen, die mit weißen Gewändern angetan waren und goldene Kronen auf ihren Häuptern hatten.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 4, 5, 'Dabei gehen aus dem Thron Blitze, Stimmen und Donnerschläge hervor; und sieben Feuerfackeln brennen vor dem Thron, das sind die sieben Geister Gottes.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 4, 6, '(Der Platz) vor dem Thron ist wie ein gläsernes Meer, wie Kristall; und inmitten des Thrones, und zwar rings um den Thron, sind vier Lebewesen, die vorn und hinten mit Augen übersät sind.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 4, 7, 'Das erste Lebewesen gleicht einem Löwen, das zweite einem Stier, das dritte hat ein Gesicht wie das eines Menschen, und das vierte Lebewesen gleicht einem fliegenden Adler.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 4, 8, 'Die vier Wesen haben ein jedes sechs Flügel und sind ringsum innen und außen mit Augen übersät; und ohne Aufhören rufen sie bei Tag und bei Nacht: »Heilig, heilig, heilig ist der Herr, der allmächtige Gott, der da war und der da ist und der da kommt!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 4, 9, 'Und jedesmal, wenn die vier Lebewesen Preis und Ehre und Danksagung dem darbringen, der auf dem Throne sitzt, dem, der in alle Ewigkeit lebt,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 4, 10, 'werfen sich die vierundzwanzig Ältesten vor dem auf dem Throne Sitzenden nieder und beten den an, der in alle Ewigkeit lebt, und legen ihre Kronen vor dem Throne nieder mit den Worten:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 4, 11, '»Würdig bist du, unser Herr und Gott, den Preis und die Ehre und die Macht zu empfangen; denn du hast alle Dinge geschaffen, und durch deinen Willen waren sie da und sind sie geschaffen worden.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 5, 1, 'Und ich sah auf der rechten Hand des auf dem Throne Sitzenden ein Buch, das inwendig beschrieben und auf der Rückseite mit sieben Siegeln versiegelt war.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 5, 2, 'Dann sah ich einen starken Engel, der mit lauter Stimme ausrief: »Wer ist würdig, das Buch zu öffnen und seine Siegel zu lösen?«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 5, 3, 'Doch niemand im Himmel und auf der Erde und unter der Erde vermochte das Buch zu öffnen und hineinzusehen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 5, 4, 'Da weinte ich laut, weil niemand würdig erfunden wurde, das Buch zu öffnen und hineinzusehen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 5, 5, 'Doch einer von den Ältesten sagte zu mir: »Weine nicht! Siehe, der Löwe aus dem Stamme Juda, die Wurzel Davids, hat überwunden, um das Buch und seine sieben Siegel zu öffnen.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 5, 6, 'Da sah ich in der Mitte zwischen dem Thron und den vier Lebewesen einerseits und den Ältesten anderseits ein Lamm stehen, (das sah aus) als wäre es (eben) geschlachtet; es hatte sieben Hörner und sieben Augen – das sind die sieben Geister Gottes, die auf die ganze Erde ausgesandt sind.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 5, 7, 'Da ging das Lamm hin und nahm (das Buch) aus der rechten Hand des auf dem Throne Sitzenden.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 5, 8, 'Als es nun das Buch genommen hatte, warfen sich die vier Lebewesen und die vierundzwanzig Ältesten vor dem Lamm nieder; jeder von ihnen hatte eine Harfe und goldene, mit Räucherwerk gefüllte Schalen; das sind die Gebete der Heiligen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 5, 9, 'Und sie sangen ein neues Lied, das da lautete: »Würdig bist du, das Buch zu nehmen und seine Siegel zu öffnen; denn du hast dich schlachten lassen und hast für Gott durch dein Blut aus allen Stämmen und Sprachen, aus allen Völkern und Völkerschaften (Menschen) erkauft,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 5, 10, 'und hast sie für unsern Gott zu einem Königtum und zu Priestern gemacht, und sie werden (einst) als Könige auf der Erde herrschen.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 5, 11, 'Dann sah ich hin und hörte den Gesang vieler Engel rings um den Thron und um die (vier) Lebewesen und die Ältesten her; ihre Zahl war zehntausendmal zehntausend und tausendmal tausend;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 5, 12, 'die riefen laut: »Würdig ist das Lamm, das sich hat schlachten lassen, zu empfangen die Macht und den Reichtum, Weisheit und Kraft, Ehre, Herrlichkeit und Lobpreis.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 5, 13, 'Und die ganze Schöpfung im Himmel und auf der Erde und unter der Erde und auf dem Meere und alles, was in ihnen lebt, hörte ich rufen: »Dem, der auf dem Throne sitzt, und dem Lamm (gebühren) Lobpreis und Ehre, Herrlichkeit und Macht in alle Ewigkeit.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 5, 14, 'Und die vier Lebewesen riefen: »Amen!«, die Ältesten aber warfen sich nieder und beteten an.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 6, 1, 'Nun sah ich, wie das Lamm eines von den sieben Siegeln öffnete, und ich hörte eines von den vier Lebewesen wie mit Donnerstimme rufen: »Komm!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 6, 2, 'Als ich nun hinsah, erblickte ich ein weißes Roß, und der auf ihm sitzende (Reiter) hatte einen Bogen; es wurde ihm ein (Sieges-) Kranz gereicht, und er zog dann aus von Sieg zu Sieg.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 6, 3, 'Als (das Lamm) hierauf das zweite Siegel öffnete, hörte ich das zweite Lebewesen rufen: »Komm!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 6, 4, 'Da kam ein anderes Roß, ein feuerrotes, zum Vorschein; und dem auf ihm sitzenden (Reiter) wurde (die Macht) verliehen, den Frieden von der Erde wegzunehmen und (die Menschen dahin zu bringen), daß sie einander niedermetzelten; und es wurde ihm ein großes Schwert gereicht.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 6, 5, 'Als (das Lamm) dann das dritte Siegel öffnete, hörte ich das dritte Lebewesen rufen: »Komm!« Da erschien vor meinen Augen ein schwarzes Roß, dessen Reiter eine Waage in der Hand hielt;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 6, 6, 'und ich hörte, wie eine Stimme mitten unter den vier Lebewesen sagte: »Ein Speisemaß Weizen für einen Denar und drei Speisemaß Gerste für einen Denar! Doch dem Öl und dem Wein darfst du keinen Schaden zufügen!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 6, 7, 'Als (das Lamm) dann das vierte Siegel öffnete, hörte ich das vierte Lebewesen laut rufen: »Komm!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 6, 8, 'Da sah ich hin und erblickte ein fahles Roß, und der auf ihm sitzende (Reiter), der hieß ›der Tod‹, und das Totenreich bildete sein Gefolge; und es wurde ihnen die Macht über den vierten Teil der Erde gegeben, die (Menschen) durch das Schwert und Hunger, durch Pest und durch die wilden Tiere der Erde zu Tode zu bringen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 6, 9, 'Als (das Lamm) dann das fünfte Siegel öffnete, sah ich unten am Brandopferaltar die Seelen derer, die hingemordet waren wegen des Wortes Gottes und um des Zeugnisses willen, das sie besaßen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 6, 10, 'Sie riefen mit lauter Stimme: »Wie lange, o heiliger und wahrhaftiger Herr, verziehst du noch mit dem Gericht und rächst unser Blut nicht an den Bewohnern der Erde?«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 6, 11, 'Da wurde einem jeden von ihnen ein weißes Gewand gegeben, und es wurde ihnen gesagt, sie möchten sich noch eine kurze Zeit gedulden, bis auch ihre Mitknechte und ihre Brüder vollzählig wären, die ebenso wie sie den Tod erleiden müßten.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 6, 12, 'Weiter sah ich: als (das Lamm) das sechste Siegel öffnete, da entstand ein gewaltiges Erdbeben; und die Sonne wurde schwarz wie ein härenes Sackkleid, und der Mond wurde wie Blut;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 6, 13, 'die Sterne des Himmels fielen auf die Erde, wie ein Feigenbaum seine unreifen Früchte abwirft, wenn ein Sturmwind ihn schüttelt;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 6, 14, 'der Himmel verschwand wie eine Buchrolle, die man zusammenrollt, und alle Berge und Inseln wurden von ihrer Stelle weggerückt.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 6, 15, 'Und die Könige der Erde, die Würdenträger und obersten Heerführer, die Reichen und Mächtigen, alle Sklaven und Freien verbargen sich in den Höhlen und zwischen den Felsen der Gebirge');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 6, 16, 'und riefen den Bergen und Felsen zu: »Fallet auf uns und verbergt uns vor dem Angesicht des auf dem Throne Sitzenden und vor dem Zorn des Lammes!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 6, 17, 'Denn gekommen ist der große Tag ihres Zorngerichts: wer vermag da zu bestehen?!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 7, 1, 'Danach sah ich vier Engel an den vier Enden der Erde stehen, die hielten die vier Winde der Erde fest, damit kein Wind auf der Erde und auf dem Meer und über irgendeinen Baum wehe.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 7, 2, 'Weiter sah ich einen anderen Engel vom Sonnenaufgang her emporsteigen, der ein Siegel des lebendigen Gottes hatte; der rief den vier Engeln, denen der Auftrag erteilt war, Unheil auf der Erde und auf dem Meer anzurichten, mit lauter Stimme die Worte zu:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 7, 3, '»Richtet kein Unheil auf der Erde und auf dem Meere und an den Bäumen an, bis wir die Knechte unsers Gottes mit einem Siegel auf ihrer Stirn bezeichnet haben!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 7, 4, 'Dann vernahm ich die Zahl der Versiegelten, nämlich hundertvierundvierzigtausend Versiegelte aus allen Stämmen der Israeliten:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 7, 5, 'aus dem Stamm Juda zwölftausend Versiegelte, aus dem Stamm Ruben zwölftausend, aus dem Stamm Gad zwölftausend,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 7, 6, 'aus dem Stamm Asser zwölftausend, aus dem Stamm Naphthali zwölftausend, aus dem Stamm Manasse zwölftausend,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 7, 7, 'aus dem Stamm Simeon zwölftausend, aus dem Stamm Levi zwölftausend,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 7, 8, 'aus dem Stamm Issaschar zwölftausend, aus dem Stamm Sebulon zwölftausend, aus dem Stamm Joseph zwölftausend, aus dem Stamm Benjamin zwölftausend Versiegelte.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 7, 9, 'Danach hatte ich ein Gesicht: Ich sah eine große Schar, die niemand zählen konnte, aus allen Völkerschaften und Stämmen, Völkern und Sprachen; die standen vor dem Thron und vor dem Lamm, mit weißen Gewändern angetan und mit Palmzweigen in den Händen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 7, 10, 'Sie riefen mit lauter Stimme: »Die Rettung steht bei unserm Gott, der auf dem Throne sitzt, und bei dem Lamm!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 7, 11, 'Und alle Engel standen rings um den Thron und um die Ältesten und um die vier Lebewesen herum und warfen sich vor dem Thron auf ihr Angesicht nieder, beteten Gott an');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 7, 12, 'und riefen: »Amen! Lobpreis und Herrlichkeit, Weisheit und Danksagung, Ehre, Macht und Stärke (gebühren) unserm Gott in alle Ewigkeit! Amen.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 7, 13, 'Da nahm einer von den Ältesten das Wort und sagte zu mir: »Wer sind wohl diese Weißgekleideten, und woher sind sie gekommen?«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 7, 14, 'Ich erwiderte ihm: »Mein Herr, du weißt es.« Da sagte er zu mir: »Das sind die, welche aus der großen Trübsal kommen und ihre Kleider gewaschen und im Blut des Lammes weiß gemacht haben.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 7, 15, 'Darum sind sie vor dem Throne Gottes und dienen ihm bei Tag und bei Nacht in seinem Tempel, und der auf dem Throne Sitzende wird über ihnen wohnen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 7, 16, 'Sie werden keinen Hunger und keinen Durst mehr haben, und kein Sonnenbrand wird sie jemals treffen noch irgendeine Hitze;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 7, 17, 'denn das Lamm dort mitten vor dem Thron wird sie weiden und sie zu Wasserquellen des Lebens führen, und Gott wird alle Tränen aus ihren Augen abwischen.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 8, 1, 'Als das Lamm dann das siebte Siegel öffnete, trat eine Stille im Himmel ein, wohl eine halbe Stunde lang.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 8, 2, 'Und ich sah die sieben Engel, die vor Gott stehen; denen wurden sieben Posaunen gegeben.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 8, 3, 'Dann kam ein anderer Engel und trat mit einer goldenen Räucherpfanne in der Hand an den Altar heran, und viel Räucherwerk wurde ihm gegeben, damit er es für die Gebete aller Heiligen auf den goldenen Altar bringe, der vor dem Throne (Gottes) steht;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 8, 4, 'und der Rauch des Räucherwerks stieg für die Gebete der Heiligen aus der Hand des Engels vor Gott empor.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 8, 5, 'Hierauf nahm der Engel die Räucherpfanne, füllte sie mit glühenden Kohlen vom Altar und schleuderte sie auf die Erde hinab; da erfolgten Donnerschläge und Stimmen, Blitze und ein Erdbeben.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 8, 6, 'Hierauf machten sich die sieben Engel, welche die sieben Posaunen hatten, fertig, um in die Posaunen zu stoßen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 8, 7, 'Und der erste Engel stieß in die Posaune: da entstand Hagel und Feuer, mit Blut vermischt, und wurde auf die Erde geworfen; da verbrannte der dritte Teil der Erde, und der dritte Teil der Bäume verbrannte und ebenso alles grüne Gras.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 8, 8, 'Und der zweite Engel stieß in die Posaune: da war es, als würde ein großer, feuerflammender Berg ins Meer geschleudert; und ein Drittel des Meeres wurde zu Blut,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 8, 9, 'und ein Drittel der Geschöpfe im Meer, die Leben hatten, starb, und ein Drittel der Schiffe ging zugrunde.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 8, 10, 'Und der dritte Engel stieß in die Posaune: da fiel ein großer Stern, der wie eine Fackel brannte, vom Himmel herab und fiel auf den dritten Teil der Flüsse und auf die Wasserquellen;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 8, 11, 'der Name des Sternes lautet ›Wermut‹. Da wurde der dritte Teil der Gewässer zu Wermut, und viele Menschen starben von dem Genuß des Wassers, weil es bitter geworden war.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 8, 12, 'Und der vierte Engel stieß in die Posaune: da wurde ein Drittel der Sonne und ein Drittel des Mondes und ein Drittel der Sterne (mit dem Bann) geschlagen, damit der dritte Teil von ihnen sich verfinsterte und der Tag während des dritten Teils seiner Dauer kein Licht hätte und die Nacht ebenso.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 8, 13, 'Hierauf sah ich hin: da hörte ich einen Adler, der hoch oben am Himmel flog und mit lauter Stimme rief: »Wehe, wehe, wehe den Bewohnern der Erde wegen der noch übrigen Posaunenstöße der drei Engel, die noch blasen werden!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 9, 1, 'Und der fünfte Engel stieß in die Posaune: da sah ich einen Stern, der vom Himmel auf die Erde gefallen war; und der Schlüssel zum Schlund des Abgrundes wurde ihm gegeben.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 9, 2, 'Er schloß also den Schlund des Abgrundes auf: da stieg Rauch aus dem Schlunde empor wie der Rauch eines großen Ofens, und die Sonne und die Luft wurden durch den Rauch des Schlundes verfinstert.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 9, 3, 'Aus dem Rauch kamen dann Heuschrecken hervor auf die Erde; denen wurde eine Kraft gegeben, wie sonst die Skorpione auf Erden sie besitzen,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 9, 4, 'und es wurde ihnen geboten, sie sollten dem Gras der Erde sowie allem Grün und allen Bäumen keinen Schaden zufügen, sondern allein den Menschen, die nicht das Siegel Gottes auf ihrer Stirn trügen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 9, 5, 'Weiter wurde ihnen die Weisung gegeben, sie nicht zu töten, sondern sie sollten fünf Monate lang gequält werden; und die Art der Qual, die sie verursachten, sollte wie die eines Skorpions sein, wenn er einen Menschen sticht.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 9, 6, 'In jenen Tagen werden die Menschen den Tod suchen, ihn aber nicht finden; sie werden sich danach sehnen, zu sterben, aber der Tod flieht vor ihnen hinweg.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 9, 7, 'Die Heuschrecken waren aber wie Rosse gestaltet, die zum Kampf gerüstet sind; auf ihren Köpfen trugen sie (einen Aufsatz) wie Kränze von Gold, und ihre Gesichter waren wie die von Menschen;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 9, 8, 'Haare hatten sie (so lang) wie Frauenhaare, und ihr Gebiß war wie das von Löwen;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 9, 9, 'und sie hatten Brustharnische wie eiserne Panzer, und das Rauschen ihrer Flügel klang wie das Gerassel von Kriegswagen mit vielen Rossen, die in den Kampf stürmen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 9, 10, 'Auch haben sie Schwänze, die denen der Skorpione ähnlich sind, und Stachel, und in ihren Schwänzen liegt ihre Kraft, den Menschen fünf Monate lang Schaden zuzufügen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 9, 11, 'Als König haben sie über sich den Engel des Abgrundes, der auf hebräisch ›Abaddon‹, auf griechisch ›Apollyon‹ heißt.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 9, 12, 'Das erste Wehe ist vorüber, es kommen aber noch zwei Wehe nach diesem!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 9, 13, 'Nun stieß der sechste Engel in die Posaune: da hörte ich aus den vier Hörnern des goldenen Altars, der vor Gott steht, eine Stimme,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 9, 14, 'die gebot dem sechsten Engel, der die Posaune hatte: »Binde die vier Engel los, die am großen Strome Euphrat gefesselt sind!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 9, 15, 'Da wurden die vier Engel losgebunden, die auf Stunde und Tag, auf Monat und Jahr in Bereitschaft standen, um den dritten Teil der Menschen zu töten.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 9, 16, 'Die Zahl der Scharen des Reiterheeres betrug zweihundert Millionen – ich hörte nämlich ihre Zahl –;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 9, 17, 'und wie ich in meinem Gesicht sah, hatten die Rosse und ihre Reiter folgendes Aussehen: sie trugen feuerrote, hyazinthblaue und schwefelgelbe Panzer, und die Köpfe ihrer Rosse waren wie Löwenköpfe, und aus ihrem Maul kam Feuer, Rauch und Schwefel hervor.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 9, 18, 'Durch diese drei Plagen wurde ein Drittel der Menschen getötet, nämlich durch das Feuer, den Rauch und den Schwefel, der aus ihrem Maul herauskam.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 9, 19, 'Die Kraft dieser Rosse liegt nämlich in ihrem Maul und in ihren Schwänzen; denn ihre Schwänze sehen wie Schlangen aus und haben Köpfe, mit denen sie Unheil anrichten.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 9, 20, 'Doch die übrigen Menschen, die durch diese Plagen nicht ums Leben gekommen waren, bekehrten sich trotzdem nicht von ihrem gewohnten Tun, daß sie von der Anbetung der bösen Geister und der Götzenbilder von Gold und Silber, von Erz, Stein und Holz, die doch weder sehen noch hören noch gehen können, abgelassen hätten;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 9, 21, 'nein, sie bekehrten sich nicht von ihren Mordtaten und Zaubereien, von ihrer Unzucht und ihren Diebstählen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 10, 1, 'Hierauf sah ich einen anderen starken Engel aus dem Himmel herabkommen, der in eine Wolke gehüllt war; der Regenbogen (wölbte sich) über seinem Haupte, sein Antlitz sah wie die Sonne aus und seine Beine wie Feuersäulen;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 10, 2, 'in seiner Hand hielt er ein aufgeschlagenes Büchlein. Er setzte nun seinen rechten Fuß auf das Meer, den linken auf die Erde');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 10, 3, 'und rief mit lauter Stimme, wie ein Löwe brüllt. Als er so gerufen hatte, ließen die sieben Donner ihre Stimmen erschallen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 10, 4, 'Als dann die sieben Donner geredet hatten, wollte ich (das Gehörte) aufschreiben; doch ich vernahm eine Stimme, die aus dem Himmel mir zurief: »Versiegle, was die sieben Donner geredet haben, und schreibe es nicht auf!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 10, 5, 'Da hob der Engel, den ich auf dem Meer und auf dem Land hatte stehen sehen, seine rechte Hand zum Himmel empor');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 10, 6, 'und schwur bei dem, der in alle Ewigkeit lebt, der den Himmel geschaffen hat und was in ihm ist, die Erde und was auf ihr ist und das Meer und was in ihm ist: »Es wird hinfort kein Verzug mehr sein,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 10, 7, 'sondern in den Tagen, in denen die Stimme des siebten Engels erschallt, wenn er in die Posaune stoßen wird, ist dann das Geheimnis Gottes zum Abschluß gekommen, wie er es seinen Knechten, den Propheten, als Freudenbotschaft zuverlässig mitgeteilt hat!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 10, 8, 'Dann redete die Stimme, die ich aus dem Himmel vernommen hatte, zum zweitenmal mit mir und sagte: »Gehe hin, nimm das aufgeschlagene Büchlein aus der Hand des Engels, der auf dem Meer und auf der Erde steht!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 10, 9, 'Da ging ich zu dem Engel hin und bat ihn, mir das Büchlein zu geben; und er antwortete mir: »Nimm es und verzehre es! Es wird dir im Bauch bitteren Geschmack erregen, aber im Munde wird es dir süß wie Honig sein.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 10, 10, 'Da nahm ich das Büchlein aus der Hand des Engels und verzehrte es; und es schmeckte mir (in der Tat) im Munde süß wie Honig; doch als ich es verschluckt hatte, wurde es mir bitter im Bauch.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 10, 11, 'Man sagte mir dann: »Du mußt nochmals über viele Völker und Völkerschaften, Sprachen und Könige weissagen.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 11, 1, 'Man gab mir dann ein Rohr, das einem Stabe glich, und gebot mir: »Mache dich auf und miß den Tempel Gottes nebst dem Brandopferaltar und den dort Anbetenden;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 11, 2, 'doch den Vorhof außerhalb des Tempels tu hinaus und miß ihn nicht mit; denn er ist den Heiden preisgegeben; die werden die heilige Stadt zweiundvierzig Monate lang zertreten.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 11, 3, '»Doch meinen zwei Zeugen will ich verleihen, daß sie, in Säcke gekleidet, zwölfhundertundsechzig Tage lang prophetisch reden.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 11, 4, 'Diese sind die zwei Ölbäume und die zwei Leuchter, die vor dem Herrn der Erde stehen;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 11, 5, 'und wenn jemand sich an ihnen vergreifen will, so geht Feuer aus ihrem Munde hervor und verzehrt ihre Feinde; und wenn jemand sich an ihnen vergreifen will, muß er auf diese Weise (durch Feuer) ums Leben kommen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 11, 6, 'Diese haben die Macht, den Himmel zu verschließen, damit kein Regen während der Tage ihrer prophetischen Rede falle; auch haben sie Macht über die Gewässer, sie in Blut zu verwandeln und die Erde mit Plagen jeder Art zu schlagen, sooft sie wollen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 11, 7, 'Wenn sie dann mit ihrem Zeugnis zum Abschluß gekommen sind, wird das Tier, das aus dem Abgrund heraufsteigt, mit ihnen kämpfen und wird sie besiegen und sie töten;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 11, 8, 'und ihre Leichname (werden) auf der Straße der großen Stadt (liegen), die, geistlich geredet, ›Sodom und Ägypten‹ heißt, wo auch ihr Herr gekreuzigt worden ist.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 11, 9, 'Und Leute aus den Völkern und Stämmen, den Sprachen und Völkerschaften sehen ihre Leichname drei und einen halben Tag lang (daliegen) und lassen nicht zu, daß ihre Leichname in einem Grabe beigesetzt werden.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 11, 10, 'Und die Bewohner der Erde freuen sich über sie und sind guter Dinge und werden einander Geschenke zusenden; denn diese beiden Propheten hatten den Bewohnern der Erde Plagen verursacht.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 11, 11, 'Doch nach den drei und einem halben Tage kam Lebensgeist aus Gott in sie hinein, und sie traten (wieder) auf ihre Füße, und große Furcht befiel alle, die sie sahen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 11, 12, 'Und sie hörten eine laute Stimme vom Himmel her ihnen zurufen: »Kommt herauf hierher!« Da fuhren sie in einer Wolke in den Himmel empor, und ihre Feinde sahen ihnen nach.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 11, 13, 'Und in jener Stunde erfolgte ein starkes Erdbeben: der zehnte Teil der Stadt stürzte ein, und siebentausend Menschennamen fanden durch das Erdbeben ihren Tod; die übrigen aber gerieten in Furcht und gaben dem Gott des Himmels die Ehre. –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 11, 14, 'Das zweite Wehe (des Adlers) ist vorüber; aber das dritte Wehe kommt bald.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 11, 15, 'Nun stieß der siebte Engel in die Posaune: da ließen sich laute Stimmen im Himmel vernehmen, die riefen: »Die Königsherrschaft über die Welt ist an unsern Herrn und seinen Gesalbten gekommen, und er wird (fortan) als König in alle Ewigkeit herrschen!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 11, 16, 'Da warfen sich die vierundzwanzig Ältesten, die vor Gott auf ihren Thronen sitzen, auf ihr Angesicht nieder und beteten Gott an');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 11, 17, 'mit den Worten: »Wir danken dir, Herr, allmächtiger Gott, der da ist und der da war, daß du deine große Macht an dich genommen und die Königsherrschaft angetreten hast.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 11, 18, 'Die Völker sind zwar in Zorn geraten, doch dein Zorn ist gekommen und die Zeit des Gerichts für die Toten und (die Zeit) der Belohnung für deine Knechte, die Propheten, und für die Heiligen und für alle, die deinen Namen fürchten, die Kleinen wie die Großen; und (die Zeit) des Verderbens für die, welche die Erde verderben.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 11, 19, 'Da tat sich der Tempel Gottes im Himmel auf, und die Lade seines Bundes wurde in seinem Tempel sichtbar; zugleich erfolgten Blitze und Stimmen, Donnerschläge, ein Erdbeben und gewaltiger Hagelschlag.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 12, 1, 'Es erschien dann ein großes Zeichen im Himmel: ein Weib, das mit der Sonne umkleidet war; der Mond war unter ihren Füßen und ein Kranz von zwölf Sternen auf ihrem Haupt;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 12, 2, 'sie war guter Hoffnung und schrie in ihren Geburtsschmerzen und Kindesnöten.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 12, 3, 'Dann erschien plötzlich noch ein anderes Zeichen im Himmel: ein großer, feuerroter Drache mit sieben Köpfen und zehn Hörnern und mit sieben Königskronen auf seinen Köpfen;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 12, 4, 'sein Schweif fegte den dritten Teil der Sterne des Himmels weg und schleuderte sie auf die Erde. Der Drache stellte sich dann vor das Weib, die in Wehen lag, um ihr Kind sofort nach der Geburt zu verschlingen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 12, 5, 'Und sie gebar einen Sohn, einen Knaben, der »alle Völker mit eisernem Stabe weiden soll«, und ihr Kind wurde zu Gott und zu seinem Thron entrückt.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 12, 6, 'Da floh das Weib in die Wüste, wo sie eine von Gott bereitete Stätte hat, um sich dort zwölfhundertsechzig Tage lang ernähren zu lassen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 12, 7, 'Es erhob sich dann ein Kampf im Himmel: Michael und seine Engel kämpften mit dem Drachen; auch der Drache und seine Engel kämpften,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 12, 8, 'doch gewannen sie den Sieg nicht, und ihres Bleibens war nicht länger im Himmel.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 12, 9, 'So wurde denn der große Drache, die alte Schlange, die da ›Teufel‹ und ›Satan‹ heißt, der Verführer des ganzen Erdkreises, auf die Erde hinabgestürzt, und seine Engel wurden mit ihm hinabgestürzt.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 12, 10, 'Da hörte ich eine laute Stimme im Himmel rufen: »Jetzt ist das Heil, die Macht und die Königsherrschaft an unsern Gott gekommen und die Herrschergewalt an seinen Gesalbten! Denn hinabgestürzt ist der Ankläger unserer Brüder, der sie vor unserm Gott verklagt hat bei Tag und bei Nacht.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 12, 11, 'Diese haben ihn um des Blutes des Lammes und um des Wortes ihres Zeugnisses willen überwunden und haben ihr Leben nicht geliebt bis zum Tode.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 12, 12, 'Darum freuet euch, ihr Himmel und die ihr in ihnen wohnt! Wehe aber der Erde und dem Meer! Denn der Teufel ist nun zu euch hinabgekommen und hegt gewaltige Wut, weil er weiß, daß seine Zeit nur noch kurz bemessen ist.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 12, 13, 'Als nun der Drache sich auf die Erde hinabgestürzt sah, verfolgte er das Weib, das den Knaben geboren hatte.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 12, 14, 'Da wurden dem Weibe die beiden Flügel des großen Adlers gegeben, damit sie in die Wüste an ihre Stätte flöge, wo sie fern vom Anblick der Schlange »eine Zeit und (zwei) Zeiten und eine halbe Zeit lang« ernährt wird.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 12, 15, 'Da spie die Schlange aus ihrem Rachen Wasser hinter dem Weibe her wie einen Strom, um sie durch die Flut wegzuschwemmen;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 12, 16, 'doch die Erde kam dem Weibe zu Hilfe, indem sie ihren Mund auftat und den Strom verschluckte, den der Drache aus seinem Rachen ausgespien hatte.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 12, 17, 'Da geriet der Drache in Wut gegen das Weib und ging hin, um Krieg mit den übrigen ihres Samens zu führen, (nämlich mit denen) die Gottes Gebote beobachten und das Zeugnis Jesu haben.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 12, 18, 'Hierauf trat ich an den Sand des Meeres.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 13, 1, 'Da sah ich aus dem Meere ein Tier heraufkommen, das hatte zehn Hörner und sieben Köpfe und auf seinen Hörnern zehn Königskronen und auf seinen Köpfen gotteslästerliche Namen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 13, 2, 'Das Tier, das ich sah, glich einem Panther, doch seine Füße waren wie die eines Bären und sein Maul wie ein Löwenrachen. Der Drache gab ihm dann seine Kraft und seinen Thron und große Macht,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 13, 3, 'dazu einen von seinen Köpfen, der wie zum Tode geschlachtet war, dessen Todeswunde jedoch wieder geheilt wurde. Da sah die ganze (Bevölkerung der) Erde dem Tier mit staunender Bewunderung nach,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 13, 4, 'und man betete den Drachen an, weil er dem Tiere die Macht gegeben hatte, und man betete das Tier an und sagte: »Wer ist dem Tiere gleich, und wer kann den Kampf mit ihm aufnehmen?«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 13, 5, 'Und es wurde ihm ein Maul gegeben, das große Worte und Lästerungen ausstieß, und es wurde ihm Vollmacht gegeben, es zweiundvierzig Monate lang so zu treiben.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 13, 6, 'Da öffnete es sein Maul zu Lästerungen gegen Gott, um seinen Namen und sein Zelt, nämlich die, welche ihre Wohnung im Himmel haben, zu lästern.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 13, 7, 'Auch wurde ihm gestattet, Krieg mit den Heiligen zu führen und sie zu besiegen; und Macht wurde ihm über alle Stämme und Völker, Sprachen und Völkerschaften verliehen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 13, 8, 'So werden ihn denn alle Bewohner der Erde anbeten, alle, deren Namen nicht im Lebensbuche des geschlachteten Lammes seit Grundlegung der Welt geschrieben stehen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 13, 9, 'Wer ein Ohr hat, der höre:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 13, 10, '»Wer andere in Gefangenschaft führt, wandert selbst in Gefangenschaft; wer mit dem Schwert tötet, muß selbst durch das Schwert den Tod finden.« Hier ist das standhafte Ausharren und der Glaube der Heiligen erforderlich.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 13, 11, 'Weiter sah ich ein anderes Tier aus der Erde heraufkommen, das hatte zwei Hörner gleich einem Lamm, redete jedoch wie ein Drache;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 13, 12, 'und es übt die ganze Macht des ersten Tieres vor dessen Augen aus und bringt die Erde und ihre Bewohner dahin, daß sie das erste Tier anbeten, dessen Todeswunde geheilt worden war.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 13, 13, 'Auch vollführt es große Wunderzeichen, so daß es sogar Feuer vor den Augen der Menschen vom Himmel auf die Erde herabfallen macht;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 13, 14, 'und es verführt die Bewohner der Erde durch die Wunderzeichen, die es infolge der ihm verliehenen Gabe vor den Augen des (ersten) Tieres vollführt, indem es die Bewohner der Erde dazu beredet, dem Tiere, das die Schwertwunde hat und wieder aufgelebt ist, ein Bild anzufertigen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 13, 15, 'Auch wurde ihm verliehen, dem Bilde des Tieres Leben zu verleihen, so daß das Bild des Tieres sogar redete, und es erreichte auch, daß alle getötet wurden, die das Bild des Tieres nicht anbeteten.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 13, 16, 'Weiter bringt es alle, die Kleinen wie die Großen, die Reichen wie die Armen, die Freien wie die Sklaven, dazu, sich ein Malzeichen an ihrer rechten Hand oder an ihrer Stirn anzubringen,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 13, 17, 'und niemand soll etwas kaufen oder verkaufen dürfen, der nicht das Malzeichen an sich trägt, nämlich den Namen des Tieres oder die Zahl seines Namens.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 13, 18, 'Hier kann sich wahre Klugheit zeigen. Wer Verstand besitzt, rechne die Zahl des Tieres aus; sie ist nämlich die Zahl eines Menschen(namens), und seine Zahl ist sechshundertsechsundsechzig.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 14, 1, 'Nun hatte ich ein Gesicht: ich sah nämlich das Lamm auf dem Berge Zion stehen und mit ihm hundertvierundvierzigtausend, die seinen Namen und den Namen seines Vaters auf ihrer Stirn geschrieben trugen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 14, 2, 'Und ich hörte einen Schall aus dem Himmel wie das Rauschen vieler Wasser und wie das Rollen eines starken Donners; zugleich aber klang der Schall, den ich hörte, wie der von Harfenspielern, die auf ihren Harfen spielen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 14, 3, 'Sie sangen ein neues Lied vor dem Throne und vor den vier Lebewesen und den Ältesten, und niemand konnte das Lied (singen) lernen außer den Hundertvierundvierzigtausend, die von der Erde erkauft sind.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 14, 4, 'Diese sind es, die sich mit Weibern nicht befleckt haben, denn sie sind jungfräulich rein; diese sind es, die dem Lamme nachfolgen, wohin es auch gehen mag. Diese sind aus der Menschheit als Erstlingsgabe für Gott und für das Lamm erkauft worden,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 14, 5, 'und in ihrem Munde ist keine Lüge gefunden worden: sie sind ohne Fehl.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 14, 6, 'Dann sah ich einen anderen Engel hoch oben mitten am Himmel fliegen, der den Bewohnern der Erde und allen Völkerschaften und Stämmen, Sprachen und Völkern eine ewiggültige Heilsbotschaft zuverlässig zu verkündigen hatte.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 14, 7, 'Er rief mit lauter Stimme: »Fürchtet Gott und gebt ihm Ehre! Denn gekommen ist die Stunde seines Gerichts; und betet den an, der den Himmel und die Erde, das Meer und die Wasserquellen geschaffen hat!« –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 14, 8, 'Hinter ihm kam ein anderer, zweiter Engel, der rief: »Gefallen, gefallen ist das große Babylon, das alle Völker vom Glutwein seiner Unzucht hat trinken lassen!« –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 14, 9, 'Noch ein anderer, dritter Engel folgte ihnen nach, der mit lauter Stimme rief: »Wenn jemand das Tier und sein Bild anbetet und das Malzeichen an seiner Stirn oder seiner Hand annimmt,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 14, 10, 'der wird gleichfalls vom Zornwein Gottes trinken, der ungemischt im Becher seines Zornes hergestellt ist, und wird mit Feuer und Schwefel vor den Augen der heiligen Engel und vor dem Lamm gepeinigt werden;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 14, 11, 'und der Rauch von ihrer Peinigung steigt in alle Ewigkeit auf, und sie haben keine Ruhe bei Tag und bei Nacht, sie die das Tier und sein Bild anbeten, und alle, die das Malzeichen seines Namens an sich tragen!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 14, 12, 'Hier muß sich das standhafte Ausharren der Heiligen zeigen, die da treu bleiben den Geboten Gottes und dem Glauben an Jesus.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 14, 13, 'Da vernahm ich eine Stimme aus dem Himmel, die (mir) zurief: »Schreibe: Selig sind die Toten, die im Herrn sterben, von jetzt an! Ja – so spricht der Geist –, sie sollen ausruhen von ihren Mühsalen; denn ihre Werke folgen ihnen nach.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 14, 14, 'Nun sah ich plötzlich eine weiße Wolke, und auf der Wolke saß einer, der wie ein Menschensohn aussah; er hatte auf dem Haupt eine goldene Krone und eine scharfe Sichel in der Hand.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 14, 15, 'Dann trat ein anderer Engel aus dem Tempel heraus und rief dem auf der Wolke Sitzenden mit lauter Stimme zu: »Lege deine Sichel an und beginne die Ernte! Denn die Zeit zum Ernten ist gekommen, weil die Ernte der Erde dürr geworden ist.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 14, 16, 'Da ließ der auf der Wolke Sitzende seine Sichel über die Erde fahren, und die Erde wurde abgeerntet.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 14, 17, 'Dann trat noch ein anderer Engel aus dem Tempel im Himmel heraus, der gleichfalls eine scharfe Sichel hatte,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 14, 18, 'und ein anderer Engel kam aus dem Altar heraus; der hatte Macht über das Feuer und rief dem, der die scharfe Sichel hatte, mit lauter Stimme die Worte zu: »Lege deine scharfe Sichel an und schneide den Fruchtertrag am Weinstock der Erde ab! Denn seine Trauben sind reif geworden.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 14, 19, 'Da ließ der Engel seine Sichel über die Erde fahren, erntete den Weinstock der Erde ab und schüttete (die Trauben) in die große Zorneskelter Gottes.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 14, 20, 'Hierauf wurde die Kelter draußen vor der Stadt getreten: da kam Blut aus der Kelter hervor bis hinauf an die Zügel der Pferde (und ergoß sich) sechzehnhundert Stadien weit.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 15, 1, 'Weiter sah ich ein anderes großes und wunderbares Zeichen im Himmel: sieben Engel, welche sieben Plagen (herbeizuführen) hatten, die letzten; denn durch diese kam der Zorn Gottes zum Abschluß.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 15, 2, 'Und ich sah etwas wie ein kristallenes Meer, das mit Feuer durchmengt war, und ich sah die, welche den Sieg über das Tier und sein Bild und über seine Namenszahl errungen hatten, an dem kristallenen Meer stehen, mit Harfen (zum Lobpreis) Gottes in der Hand.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 15, 3, 'Sie sangen das Lied Moses, des Knechtes Gottes, und das Lied des Lammes mit den Worten: »Groß und wunderbar sind deine Werke, Herr, allmächtiger Gott! Gerecht und wahrhaftig sind deine Wege, du König der Völker!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 15, 4, 'Wer sollte sich nicht (vor dir) fürchten, Herr, und deinen Namen nicht preisen? Denn du allein bist heilig. Ja, alle Völker werden kommen und vor dir anbeten; denn deine Rechttaten sind offenbar geworden.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 15, 5, 'Hierauf hatte ich ein (neues) Gesicht: ich sah, wie der Tempel des Zeltes des Zeugnisses im Himmel sich auftat');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 15, 6, 'und die sieben Engel, welche die sieben Plagen hatten, aus dem Tempel heraustraten; sie waren in glänzend weiße Leinwand gekleidet und um die Brust mit goldenen Gürteln umgürtet.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 15, 7, 'Da gab eins von den vier Lebewesen den sieben Engeln sieben goldene Schalen, die mit dem Zorn des in alle Ewigkeit lebenden Gottes gefüllt waren;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 15, 8, 'und der Tempel füllte sich mit Rauch von der Herrlichkeit Gottes und von seiner Kraft; und niemand konnte in den Tempel eintreten, bis die sieben Plagen der sieben Engel zu Ende waren.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 16, 1, 'Nun hörte ich eine laute Stimme aus dem Tempel den sieben Engeln zurufen: »Gehet hin und gießt die sieben Schalen des göttlichen Zornes auf die Erde aus!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 16, 2, 'Da ging der erste hin und goß seine Schale auf die Erde aus; da kamen schlimme und bösartige Geschwüre an die Menschen, die das Malzeichen des Tieres an sich trugen und sein Bild anbeteten.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 16, 3, 'Dann goß der zweite seine Schale in das Meer aus; da wurde es zu Blut, wie Leichenblut, und alle lebenden Seelen im Meere starben.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 16, 4, 'Weiter goß der dritte seine Schale in die Flüsse und die Wasserquellen aus; da wurden sie zu Blut;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 16, 5, 'und ich hörte den Engel der Gewässer sagen: »Gerecht bist du, der du bist und der du warst, du Heiliger, daß du solche Gerichte vollzogen hast!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 16, 6, 'Denn das Blut von Heiligen und Propheten haben sie vergossen; dafür hast du ihnen Blut zu trinken gegeben: sie haben es so verdient.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 16, 7, 'Und ich hörte den Altar sagen: »Ja, Herr, allmächtiger Gott, wahrhaft und gerecht sind deine Gerichte!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 16, 8, 'Hierauf goß der vierte seine Schale auf die Sonne aus; da wurde ihr (die Kraft) verliehen, die Menschen mit Feuerglut zu versengen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 16, 9, 'So wurden denn die Menschen von gewaltiger Glut versengt, lästerten aber trotzdem den Namen Gottes, der die Macht über diese Plagen hat, und bekehrten sich nicht dazu, ihm die Ehre zu geben.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 16, 10, 'Nun goß der fünfte seine Schale auf den Thron des Tieres aus; da wurde sein Reich verfinstert, und die Menschen zerbissen sich die Zungen vor qualvollem Schmerz,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 16, 11, 'lästerten aber trotzdem den Gott des Himmels wegen ihrer qualvollen Schmerzen und wegen ihrer Geschwüre und bekehrten sich nicht von ihrem (bösen) Tun.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 16, 12, 'Hierauf goß der sechste seine Schale auf den großen Strom Euphrat aus; da vertrocknete sein Wasser, damit den Königen vom Aufgang der Sonne her der Weg offenstände.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 16, 13, 'Und ich sah aus dem Maul des Drachen und aus dem Maul des Tieres und aus dem Munde des falschen Propheten drei unreine Geister wie Frösche (hervorkommen) –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 16, 14, 'sie sind nämlich Teufelsgeister, welche Wunderzeichen verrichten –; diese begeben sich zu den Königen des ganzen Erdkreises, um sie zum Kampf am großen Tage Gottes, des Allmächtigen, zu sammeln.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 16, 15, '»Seht, ich komme wie ein Dieb! Selig ist, wer da wacht und seine Kleider bereithält, damit er nicht nackt einherzugehen braucht und man seine Schande nicht zu sehen bekommt!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 16, 16, 'Und sie (jene unreinen Geister) versammelten sie (die Könige) in der Gegend, die auf hebräisch ›Harmagedon‹ heißt.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 16, 17, 'Nun goß der siebte seine Schale in die Luft aus; da erscholl eine laute Stimme aus dem Tempel (im Himmel) vom Throne her und rief: »Es ist geschehen!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 16, 18, 'Da erfolgten Blitze, Rufe und Donnerschläge; und ein gewaltiges Erdbeben entstand, wie noch nie eins gewesen war, seit es Menschen auf der Erde gegeben hat, ein solch gewaltig starkes Erdbeben.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 16, 19, 'Da zerfiel die große Stadt in drei Teile, und die Städte der Völker stürzten ein, und der großen Stadt Babylon wurde vor Gott gedacht, um ihr den Becher mit dem Glutwein seines Zorns zu reichen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 16, 20, 'Auch alle Inseln verschwanden, und Berge waren nicht mehr zu finden.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 16, 21, 'Und ein gewaltiger Hagelschlag mit pfundschweren Stücken fiel vom Himmel auf die Menschen herab; aber die Menschen lästerten Gott trotzdem wegen der Plage des Hagels; denn dessen Plage ist ganz entsetzlich.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 17, 1, 'Da kam einer von den sieben Engeln, welche die sieben Schalen hatten, redete mit mir und sagte: »Komm, ich will dir das Gericht über die große Buhlerin zeigen, die an vielen Wassern ihren Sitz hat,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 17, 2, 'mit der die Könige der Erde gebuhlt haben und von deren Unzuchtswein die Bewohner der Erde trunken geworden sind.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 17, 3, 'So entführte er mich denn im Geist in eine Wüste; und ich sah dort ein Weib auf einem scharlachroten Tier sitzen, das mit gotteslästerlichen Namen übersät war und sieben Köpfe und zehn Hörner hatte.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 17, 4, 'Das Weib war in Purpur und Scharlach gekleidet und mit Gold, Edelsteinen und Perlen reich geschmückt; in ihrer Hand hielt sie einen goldenen Becher, der mit (götzendienerischen) Greueln und mit dem Schmutz ihrer Buhlerei gefüllt war;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 17, 5, 'und auf ihrer Stirn stand ein Name geschrieben, ein Geheimnis: »Groß-Babylon, die Mutter der Buhlerinnen und der (götzendienerischen) Greuel der Erde.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 17, 6, 'Ich sah das Weib trunken vom Blut der Heiligen und vom Blut der Zeugen Jesu; bei ihrem Anblick geriet ich in großes Staunen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 17, 7, 'Da sagte der Engel zu mir: »Warum bist du so erstaunt? Ich will dir Aufschluß geben über das Geheimnis des Weibes und des Tieres, auf dem sie sitzt und das die sieben Köpfe und die zehn Hörner hat.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 17, 8, 'Das Tier, das du gesehen hast, ist (schon früher) dagewesen und ist (jetzt) nicht mehr (da); doch wird es aus dem Abgrund wieder heraufsteigen und ins Verderben fahren; da werden dann die Bewohner der Erde sich verwundern, die, deren Name nicht eingeschrieben steht im Buch des Lebens seit Grundlegung der Welt, wenn sie sehen, daß das Tier (schon früher) dagewesen war und (jetzt) nicht mehr da ist und (nunmehr) wieder da sein wird.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 17, 9, 'Hier ist Verstand erforderlich, der mit Weisheit gepaart ist. Die sieben Köpfe sind sieben Berge, auf denen das Weib thront,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 17, 10, 'und bedeuten (zugleich) sieben Könige: fünf von ihnen sind (bereits) zu Fall gekommen, der eine (sechste) ist (jetzt) da, der andere (siebte) ist noch nicht gekommen, und wenn er gekommen ist, darf er nur eine kurze Zeit bleiben.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 17, 11, 'Ferner das Tier, das (schon früher) gewesen war und (jetzt) nicht mehr da ist, ist selbst der achte und gehört trotzdem zu den sieben (Königen) und fährt dahin ins Verderben.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 17, 12, 'Und die zehn Hörner, die du gesehen hast, sind zehn Könige, welche die Herrschaft noch nicht empfangen haben, sondern ihre königliche Gewalt zu derselben Stunde zugleich mit dem Tier erhalten.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 17, 13, 'Diese (zehn) haben einmütigen Sinn und stellen ihre Macht und Gewalt dem Tier zur Verfügung.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 17, 14, 'Diese werden mit dem Lamm kämpfen, aber das Lamm wird sie besiegen – denn es ist der Herr der Herren und der König der Könige –, mit seinen Kampfgenossen, den Berufenen und Auserwählten und Getreuen.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 17, 15, 'Dann fuhr er fort: »Die Wasser, die du gesehen hast, wo die Buhlerin thront, sind Völker und Scharen, Völkerschaften und Sprachen;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 17, 16, 'und die zehn Hörner, die du gesehen hast, und das Tier: die werden die Buhlerin hassen, werden sie einsam und nackt machen, ihr Fleisch verzehren und sie selbst mit Feuer verbrennen;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 17, 17, 'denn Gott hat ihnen ins Herz gegeben, seinen Ratschluß auszuführen und in einem Sinn zu handeln und ihre Königsherrschaft solange dem Tier zur Verfügung zu stellen, bis die Worte Gottes erfüllt sein werden.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 17, 18, 'Das Weib endlich, das du gesehen hast, ist die große Stadt, welche die Herrschaft über die Könige der Erde hat.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 18, 1, 'Danach sah ich einen anderen Engel aus dem Himmel herabkommen, der eine weitgehende Macht erhalten hatte, und die Erde wurde von seiner Herrlichkeit erleuchtet.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 18, 2, 'Er rief mit mächtiger Stimme: »Gefallen, gefallen ist das große Babylon und ist zur Behausung von Teufeln, zur Unterkunft aller unreinen Geister und zur Unterkunft aller unreinen und verabscheuten Vögel geworden!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 18, 3, 'Denn von dem Glutwein ihrer Unzucht haben alle Völker getrunken, und die Könige der Erde haben mit ihr gebuhlt, und die Kaufleute der Erde sind durch ihre maßlose Üppigkeit reich geworden.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 18, 4, 'Dann hörte ich eine andere Stimme aus dem Himmel rufen: »Gehet aus ihr hinaus, ihr mein Volk, damit ihr an ihren Sünden keinen Anteil habt und von ihren Plagen nicht mitbetroffen werdet!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 18, 5, 'Denn ihre Sünden haben sich aufgetürmt bis an den Himmel, und Gott hat ihrer Ungerechtigkeiten gedacht.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 18, 6, 'Tut an ihr, wie auch sie getan hat, und zahlt ihr doppelt heim, wie ihre Taten es verdienen! In dem Becher, in dem sie den Wein gemischt hat, mischt für sie ein doppeltes Maß!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 18, 7, 'Soviel sie geprunkt und Üppigkeit getrieben hat, ebensoviel Qual und Leid fügt ihr zu! Weil sie in ihrem Herzen denkt: ›Ich throne hier als Königin und bin keine Witwe und werde niemals Trauer erleben‹,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 18, 8, 'deshalb sollen ihre Plagen an einem Tage über sie kommen, Pest, Trauer und Hunger, und mit Feuer soll sie verbrannt werden; denn stark ist Gott der Herr, der das Urteil über sie gesprochen hat.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 18, 9, '»Und weinen und wehklagen werden um sie die Könige der Erde, die mit ihr gebuhlt und Üppigkeit getrieben haben, wenn sie den Rauch von ihrem Brande sehen;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 18, 10, 'von ferne werden sie aus Furcht vor ihrer Qual stehen und ausrufen: ›Wehe, wehe, du große Stadt Babylon, du mächtige Stadt! In einer einzigen Stunde ist nun das Gericht über dich gekommen!‹');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 18, 11, 'Auch die Kaufleute der Erde weinen und trauern um sie, weil jetzt niemand mehr ihre Waren kauft:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 18, 12, 'die Waren von Gold und Silber, von Edelsteinen und Perlen, von feiner Leinwand und Purpur, von Seide und Scharlach, all das duftende Thujaholz und alle die Geräte von Elfenbein, alle die Geräte von kostbarem Holz und Erz, von Eisen und Marmor;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 18, 13, 'auch Zimt und Haarbalsam und Räucherwerk, Salbe und Weihrauch, Wein und Öl, Feinmehl und Weizen, Zugvieh und Schafe, Pferde und Wagen, Menschenleiber und Menschenseelen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 18, 14, 'Auch das Obst, an dem du deine Herzenslust hattest, ist dir verlorengegangen, und alles, was glänzt und prunkt, ist dir entschwunden und wird sicherlich nie wieder anzutreffen sein.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 18, 15, 'Die Kaufleute, die mit diesen Dingen Handel treiben und an ihr reich geworden sind, werden aus Furcht vor ihrer Qual weinend und trauernd in der Ferne stehen');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 18, 16, 'und ausrufen: ›Wehe, wehe, du große Stadt, die du dich in feine Leinwand, in Purpur und Scharlach kleidetest und mit Gold, Edelsteinen und Perlen reich geschmückt warst! O daß eine einzige Stunde diesen großen Reichtum verwüstet hat!‹');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 18, 17, 'Und alle Steuermänner und alle Küstenfahrer, die Schiffsleute und alle, die auf dem Meer arbeiten, standen von fern');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 18, 18, 'und riefen, als sie den Rauch von ihrem Brande sahen, laut aus: ›Wo ist eine Stadt so groß, wie diese (war)!‹');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 18, 19, 'Sie streuten sich Staub auf die Häupter und riefen unter Weinen und Wehklagen: ›Wehe, wehe, du große Stadt, in der alle, die ihre Schiffe auf dem Meer haben, von ihrem Überfluß reich geworden sind! Ach, in einer einzigen Stunde ist sie verwüstet worden!‹«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 18, 20, '»Frohlocke über sie, du Himmel und ihr Heiligen, ihr Apostel und Propheten, denn Gott hat das Strafgericht für euch an ihr vollzogen!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 18, 21, 'Da hob ein starker Engel einen Stein auf, der so groß wie ein Mühlstein war, und schleuderte ihn ins Meer mit den Worten: »So wird mit gewaltigem Schwung die große Stadt Babylon weggeschleudert werden und nicht mehr zu finden sein!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 18, 22, 'Kein Klang von Harfenspielern und Sängern, von Flötenspielern und Posaunenbläsern wird je wieder in dir vernommen werden! Auch kein Künstler in irgendwelcher Kunst wird noch in dir gefunden und kein Schall von einer Mühle in dir gehört werden!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 18, 23, 'Kein Licht von einer Lampe wird noch in dir scheinen und kein Jubelruf eines Bräutigams und einer Braut sich in dir vernehmen lassen! Denn deine Kaufherren sind die Großen der Erde gewesen, und durch deine Giftmischereien sind alle Völker verführt worden;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 18, 24, 'und in ihr ist das Blut der Propheten und Heiligen und aller derer gefunden, die auf der Erde hingeschlachtet worden sind.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 19, 1, 'Danach hörte ich ein Getön, das klang wie der laute Jubel einer großen Schar, die im Himmel riefen: »Halleluja! Das Heil, die Herrlichkeit und die Kraft gehören unserm Gott;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 19, 2, 'denn wahrhaftig und gerecht sind seine Gerichte, daß er die große Buhlerin gerichtet hat, die mit ihrer Unzucht die Erde verstörte, und das Blut seiner Knechte hat er an ihr gerächt!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 19, 3, 'Und zum zweitenmal riefen sie: »Halleluja! Und der Rauch von ihr steigt in alle Ewigkeit auf!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 19, 4, 'Da warfen sich die vierundzwanzig Ältesten und die vier Lebewesen nieder und beteten Gott, der auf dem Throne sitzt, mit den Worten an: »Amen! Halleluja!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 19, 5, 'Und eine Stimme ging vom Throne aus, die rief: »Lobet unsern Gott, ihr alle seine Knechte, die ihr ihn fürchtet, die Kleinen wie die Großen!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 19, 6, 'Dann hörte ich ein Getön, das klang wie der Jubel einer großen Volksmenge und wie das Rauschen vieler Wasser und wie das Krachen starker Donnerschläge, als sie riefen: »Halleluja! Der Herr, unser Gott, der Allmächtige, hat die Herrschaft angetreten!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 19, 7, 'Laßt uns fröhlich sein und jubeln und ihm die Ehre geben! Denn die Hochzeit des Lammes ist gekommen, und seine Braut hat sich gerüstet,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 19, 8, 'und ihr ist verliehen worden, sich in glänzend weiße Leinwand zu kleiden«; die Leinwand nämlich, die bedeutet die Rechttaten der Heiligen. –');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 19, 9, 'Dann sagte er zu mir: »Schreibe: Selig sind die, welche zum Hochzeitsmahl des Lammes geladen sind!« Weiter sagte er zu mir: »Dies sind die wahrhaftigen Worte Gottes.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 19, 10, 'Da warf ich mich ihm zu Füßen nieder, um ihn anzubeten; aber er sagte zu mir: »Nicht doch! Ich bin nur ein Mitknecht von dir und von deinen Brüdern, die das Zeugnis Jesu haben. Bete Gott an!« – Das Zeugnis Jesu nämlich, das ist der Geist der Weissagung.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 19, 11, 'Dann sah ich den Himmel offenstehen und erblickte ein weißes Roß; der auf ihm sitzende Reiter heißt ›Treu und Wahrhaftig‹; er richtet und streitet mit Gerechtigkeit.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 19, 12, 'Seine Augen aber sind (wie) eine Feuerflamme; auf seinem Haupt hat er viele Königskronen, und er trägt an sich einen Namen geschrieben, den niemand außer ihm selbst kennt;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 19, 13, 'bekleidet ist er mit einem in Blut getauchten Gewande, und sein Name lautet ›das Wort Gottes‹.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 19, 14, 'Die himmlischen Heerscharen folgten ihm auf weißen Rossen und waren mit glänzend weißer Leinwand angetan.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 19, 15, 'Aus seinem Munde geht ein scharfes Schwert hervor, mit dem er die Völker (nieder)schlagen soll, und er wird sie mit eisernem Stabe weiden, und er ist es, der die Kelter des Glutweins des Zornes des allmächtigen Gottes tritt.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 19, 16, 'An seinem Gewande, und zwar an seiner Hüfte, trägt er den Namen geschrieben: »König der Könige und Herr der Herren«.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 19, 17, 'Dann sah ich einen Engel in der Sonne stehen, der rief mit lauter Stimme allen Vögeln zu, die hoch oben am Himmel fliegen: »Kommt her, versammelt euch zu dem großen Mahle Gottes!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 19, 18, 'Ihr sollt Fleisch fressen von Königen, Fleisch von Kriegsobersten, Fleisch von Starken, Fleisch von Rossen und ihren Reitern, Fleisch von Leuten aller Art, von Freien und Sklaven, von Kleinen und Großen!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 19, 19, 'Weiter sah ich das Tier und die Könige der Erde und ihre Heere versammelt, um mit dem auf dem Roß sitzenden Reiter und mit seinem Heer zu kämpfen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 19, 20, 'Da wurde das Tier gegriffen und mit ihm der Lügenprophet, der die Wunderzeichen vor seinen Augen getan und dadurch die verführt hatte, welche das Malzeichen des Tieres trugen und sein Bild anbeteten; bei lebendigem Leibe wurden beide in den Feuersee geworfen, der mit Schwefel brennt.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 19, 21, 'Die übrigen aber wurden mit dem Schwerte getötet, das aus dem Munde des auf dem Rosse sitzenden Reiters hervorging; und alle Vögel sättigten sich an ihrem Fleisch.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 20, 1, 'Dann sah ich einen Engel aus dem Himmel herabkommen, der den Schlüssel zum Abgrund und eine große Kette in seiner Hand hatte.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 20, 2, 'Er ergriff den Drachen, die alte Schlange – das ist der Teufel und der Satan –, legte ihn auf tausend Jahre in Fesseln,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 20, 3, 'warf ihn in den Abgrund, verschloß den Eingang und brachte über ihm ein Siegel an, damit er die Völker nicht mehr verführe, bis die tausend Jahre zu Ende sind; danach muß er auf kurze Zeit noch einmal freigelassen werden.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 20, 4, 'Dann sah ich Thronsessel (aufgestellt), auf die sich (Richter) setzen; und es wurde ihnen das Gericht übertragen. Dann sah ich die Seelen derer, die wegen des Zeugnisses Jesu und um des Wortes Gottes willen enthauptet worden waren und die das Tier und sein Bild nicht angebetet und das Malzeichen an Stirn und Hand nicht angenommen hatten; sie wurden wieder lebendig und herrschten als Könige zusammen mit Christus tausend Jahre lang.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 20, 5, 'Die übrigen Toten aber lebten bis zum Ablauf der tausend Jahre nicht wieder auf. Dies ist die erste Auferstehung:');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 20, 6, 'selig und heilig ist, wer an der ersten Auferstehung Anteil hat! Über diese hat der zweite Tod keine Gewalt, sondern sie werden Priester Gottes und Christi sein und die tausend Jahre hindurch zusammen mit ihm herrschen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 20, 7, 'Wenn dann aber die tausend Jahre zu Ende sind, wird der Satan aus seinem Gefängnis freigelassen werden,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 20, 8, 'und er wird sich aufmachen, um die Völker an den vier Ecken der Erde zu verführen, den Gog und Magog, um sie zum Kampf zusammenzubringen; deren Zahl ist wie die des Sandes am Meer.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 20, 9, 'Sie zogen dann auf die Breite der Erde hinauf und umzingelten das Heerlager der Heiligen und die geliebte Stadt. Da fiel Feuer vom Himmel herab und verzehrte sie;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 20, 10, 'und ihr Verführer, der Teufel, wurde in den Feuer- und Schwefelsee geworfen, in welchem sich auch das Tier und der Lügenprophet befinden; dort werden sie bei Tag und bei Nacht in alle Ewigkeit gepeinigt werden.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 20, 11, 'Weiter sah ich einen großen weißen Thron und den, der auf ihm saß; vor dessen Angesicht flohen die Erde und der Himmel, und es fand sich keine Stätte mehr für sie.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 20, 12, 'Und ich sah die Toten, die Großen wie die Kleinen, vor dem Throne stehen, und Bücher wurden aufgetan; dann wurde noch ein anderes Buch aufgeschlagen, nämlich das Buch des Lebens, und die Toten wurden aufgrund dessen gerichtet, was in den Büchern geschrieben stand, (nämlich) nach ihren Werken.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 20, 13, 'Und das Meer gab die Toten zurück, die es barg, und der Tod und das Totenreich gaben die Toten heraus, die sich in ihnen befanden, und sie wurden alle nach ihren Werken gerichtet;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 20, 14, 'hierauf wurden der Tod und das Totenreich in den Feuersee geworfen. Dies ist der zweite Tod, nämlich der Feuersee;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 20, 15, 'und wenn jemand nicht im Buch des Lebens verzeichnet gefunden wurde, so wurde er in den Feuersee geworfen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 21, 1, 'Dann sah ich einen neuen Himmel und eine neue Erde; denn der erste Himmel und die erste Erde waren verschwunden, und auch das Meer ist nicht mehr da.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 21, 2, 'Und ich sah die heilige Stadt, ein neues Jerusalem, aus dem Himmel herabkommen von Gott her, ausgestattet wie eine für ihren Bräutigam geschmückte Braut.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 21, 3, 'Dabei hörte ich eine laute Stimme aus dem Himmel rufen: »Siehe da, die Hütte Gottes ist bei den Menschen! Und er wird bei ihnen wohnen, und sie werden sein Volk sein; ja, Gott selbst wird unter ihnen sein');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 21, 4, 'und wird alle Tränen aus ihren Augen abwischen, und der Tod wird nicht mehr sein, und keine Trauer, kein Klaggeschrei und kein Schmerz wird mehr sein; denn das Erste ist vergangen.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 21, 5, 'Da sagte der auf dem Thron Sitzende: »Siehe, ich mache alles neu!« Dann fuhr er fort: »Schreibe! Denn diese Worte sind zuverlässig und gewiß!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 21, 6, 'Weiter sagte er zu mir: »Es ist geschehen. Ich bin das A und das O, der Anfang und das Ende; ich will dem Dürstenden aus der Quelle des Lebenswassers umsonst (zu trinken) geben.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 21, 7, 'Wer da überwindet, soll dieses erben, und ich will sein Gott sein, und er soll mein Sohn sein.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 21, 8, 'Dagegen den Feigen und Ungläubigen, den Unreinen und Mördern, den Unzüchtigen und Zauberern, den Götzendienern und allen Lügnern soll ihr Teil in dem See werden, der mit Feuer und Schwefel brennt: dies ist der zweite Tod.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 21, 9, 'Da kam einer von den sieben Engeln, welche die sieben Schalen (gehabt) hatten, die mit den sieben letzten Plagen gefüllt waren, und richtete die Worte an mich: »Komm, ich will dir die Braut, das Weib des Lammes, zeigen!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 21, 10, 'Hierauf entrückte er mich im Geist auf einen großen, hohen Berg und zeigte mir die heilige Stadt Jerusalem, wie sie aus dem Himmel herabkam von Gott her,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 21, 11, 'geschmückt mit der Herrlichkeit Gottes. Ihr Lichtglanz war wie der kostbarste Edelstein, wie ein kristalleuchtender Jaspis.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 21, 12, 'Sie hatte eine große, hohe Mauer mit zwölf Toren darin und auf den Toren zwölf Engel (als Wächter); und Namen waren darangeschrieben, nämlich die Namen der zwölf Stämme der Israeliten;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 21, 13, 'drei Tore lagen nach Osten, drei nach Norden, drei nach Süden und drei nach Westen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 21, 14, 'Die Mauer der Stadt hatte zwölf Grundsteine, und auf ihnen standen die zwölf Namen der zwölf Apostel des Lammes geschrieben.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 21, 15, 'Der mit mir redende (Engel) hatte als Meßstab ein goldenes Rohr, um die Stadt sowie ihre Tore und ihre Mauer auszumessen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 21, 16, 'Die Stadt bildet nämlich ein Viereck, und ihre Länge ist ebenso groß wie die Breite. So maß er denn die Stadt mit dem Rohr: zwölftausend Stadien; Länge, Breite und Höhe sind bei ihr gleich.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 21, 17, 'Dann maß er ihre Mauer: hundertundvierundvierzig Ellen nach Menschenmaß, das auch Engelmaß ist.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 21, 18, 'Der Baustoff ihrer Mauer ist Jaspis, und die Stadt (selbst) besteht aus lauterem Gold, (durchsichtig) wie reines Glas.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 21, 19, 'Die Grundsteine der Stadtmauer sind mit Edelsteinen jeder Art verziert: der erste Grundstein ist ein Jaspis, der zweite ein Saphir, der dritte ein Chalzedon, der vierte ein Smaragd,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 21, 20, 'der fünfte ein Sardonyx, der sechste ein Karneol, der siebte ein Chrysolith, der achte ein Beryll, der neunte ein Topas, der zehnte ein Chrysopras, der elfte ein Hyazinth, der zwölfte ein Amethyst.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 21, 21, 'Die zwölf Tore waren zwölf Perlen; jedes von ihnen bestand aus einer einzigen Perle; und die Straßen der Stadt waren lauteres Gold, wie durchsichtiges Glas.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 21, 22, 'Einen Tempel sah ich nicht in ihr; denn Gott der Herr, der Allmächtige, ist ihr Tempel und (außerdem) das Lamm.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 21, 23, 'Auch bedarf die Stadt nicht der Sonne und nicht des Mondes zu ihrer Erleuchtung; denn die Herrlichkeit Gottes spendet ihr Licht, und ihre Leuchte ist das Lamm.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 21, 24, 'Die Völker werden in ihrem Lichte wandeln, und die Könige der Erde bringen ihre Herrlichkeit in sie hinein.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 21, 25, 'Ihre Tore werden am Tage niemals verschlossen werden, denn Nacht wird es dort nicht mehr geben,');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 21, 26, 'und man wird die Herrlichkeit und die Pracht der Völker in sie hineinbringen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 21, 27, 'Und niemals wird etwas Unreines in sie hineinkommen und niemand, der Greuel und Lüge übt, sondern nur die, welche im Lebensbuche des Lammes verzeichnet stehen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 22, 1, 'Weiter zeigte er mir einen Strom von Wasser des Lebens, klar wie Kristall, der aus dem Throne Gottes und des Lammes hervorfloß.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 22, 2, 'Auf beiden Seiten des Stromes, halbwegs zwischen ihm und den Straßen der Stadt, standen Lebensbäume, die zwölfmal Früchte tragen: in jedem Monat bringen sie ihre Früchte, und die Blätter der Bäume dienen den Völkern zur Heilung.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 22, 3, 'Es wird dort auch nichts mehr vom Bann Getroffenes geben, vielmehr wird der Thron Gottes und des Lammes in ihr stehen, und seine Knechte werden ihm dienen');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 22, 4, 'und werden sein Angesicht schauen, und sein Name wird auf ihren Stirnen stehen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 22, 5, 'Es wird dort auch keine Nacht mehr geben, und man bedarf keines Lampenlichts und keines Sonnenlichts; denn Gott der Herr wird ihnen leuchten, und sie werden als Könige in alle Ewigkeit herrschen.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 22, 6, 'Dann sagte er zu mir: »Diese Worte sind zuverlässig und wahrhaftig, und der Herr, der Gott der Prophetengeister, hat seinen Engel gesandt, um seinen Knechten anzuzeigen, was in Bälde geschehen muß.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 22, 7, '»Und wisse wohl: ich komme bald! Selig ist, wer die Worte der Weissagung dieses Buches festhält!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 22, 8, 'Und ich, Johannes, bin es, der dies gehört und gesehen hat; und als ich es gehört und gesehen hatte, warf ich mich dem Engel, der mir dies (alles) gezeigt hatte, zu Füßen nieder, um ihn anzubeten;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 22, 9, 'aber er sagte zu mir: »Nicht doch! Ich bin (nur) ein Mitknecht von dir und deinen Brüdern, den Propheten, sowie von denen, welche die Worte dieses Buches festhalten. Bete Gott an!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 22, 10, 'Dann fuhr er fort: »Lege die Worte der Weissagung dieses Buches nicht unter Siegel! Denn die Zeit (ihrer Erfüllung) ist nahe.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 22, 11, 'Wer Unrecht tut, möge noch weiter Unrecht tun und der Schuldbefleckte sich weiterhin beflecken; aber auch der Gerechte möge weiterhin Gerechtigkeit üben und der Heilige sich weiterhin heiligen!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 22, 12, '»Siehe, ich komme bald und mein Lohn mit mir, um einem jeden nach seinem Werk zu vergelten.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 22, 13, 'Ich bin das A und das O, der Erste und der Letzte, der Anfang und das Ende.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 22, 14, 'Selig sind die, welche ihre Kleider waschen, damit sie ein Anrecht an den Baum des Lebens erlangen und durch die Tore in die Stadt eingehen (können)!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 22, 15, 'Draußen sind die Hunde und die Zauberer, die Unzüchtigen und die Mörder, die Götzendiener und alle, welche die Lüge lieben und üben.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 22, 16, '»Ich, Jesus, habe meinen Engel gesandt, um euch dieses vor den Gemeinden zu bezeugen. Ich bin der Wurzelsproß vom Geschlecht Davids, der helle Morgenstern.«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 22, 17, 'Und der Geist und die Braut sagen: »Komm!«, und wer es hört, der sage: »Komm!«, und wen da dürstet, der komme! Wer Verlangen trägt, der empfange Wasser des Lebens umsonst!');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 22, 18, 'Ich (Johannes) bezeuge jedem, der die Worte der Weissagung dieses Buches hört: Wenn jemand zu ihnen etwas hinzufügt, so wird Gott auf ihn die Plagen legen, von denen in diesem Buche geschrieben steht;');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 22, 19, 'und wenn jemand von den Worten dieses Buches der Weissagung etwas wegnimmt, so wird Gott ihm seinen Anteil am Baume des Lebens und an der heiligen Stadt wegnehmen, von denen in diesem Buche geschrieben steht.');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 22, 20, 'Es spricht der, welcher dies bezeugt: »Ja, ich komme bald!« »Amen, komm, Herr Jesus!«');
INSERT INTO `GerMenge_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 22, 21, 'Die Gnade des Herrn Jesus sei mit allen.');
